import java.io.*;
import java.util.*;

/**
 * This program finds the maximum sized "plus" shapes (crosses) consisting of '*' characters 
 * that can be placed on a grid to cover all existing '*' cells.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        solve(reader, out);

        out.close();
    }

    private static void solve(FastReader reader, PrintWriter out) {
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = reader.next().toCharArray();
        }

        // Pre-calculate the maximum possible arm length in each of the 4 directions for every cell
        int[][] distLeft = calculateDistances(grid, rows, cols, 0, 1);   // Left to Right
        int[][] distRight = calculateDistances(grid, rows, cols, 0, -1); // Right to Left
        int[][] distUp = calculateDistances(grid, rows, cols, 1, 0);    // Top to Bottom
        int[][] distDown = calculateDistances(grid, rows, cols, -1, 0); // Bottom to Top

        List<Plus> pluses = new ArrayList<>();
        int[][] rowCoverageDiff = new int[rows][cols];
        int[][] colCoverageDiff = new int[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                // The radius of the largest plus centered at (i, j)
                int radius = Math.min(
                    Math.min(distLeft[i][j], distRight[i][j]),
                    Math.min(distUp[i][j], distDown[i][j])
                );

                if (radius > 0) {
                    pluses.add(new Plus(i + 1, j + 1, radius));

                    // Mark horizontal coverage using a difference array
                    rowCoverageDiff[i][j - radius]++;
                    if (j + radius + 1 < cols) {
                        rowCoverageDiff[i][j + radius + 1]--;
                    }

                    // Mark vertical coverage using a difference array
                    colCoverageDiff[i - radius][j]++;
                    if (i + radius + 1 < rows) {
                        colCoverageDiff[i + radius + 1][j]--;
                    }
                }
            }
        }

        // Convert difference arrays to actual coverage counts via prefix sums
        applyPrefixSums(rowCoverageDiff, rows, cols, true);
        applyPrefixSums(colCoverageDiff, rows, cols, false);

        // Check if any '*' cell is left uncovered
        boolean allCovered = true;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*') {
                    int totalCoverage = rowCoverageDiff[i][j] + colCoverageDiff[i][j];
                    if (totalCoverage == 0) {
                        allCovered = false;
                        break;
                    }
                }
            }
            if (!allCovered) break;
        }

        if (!allCovered) {
            out.println("-1");
        } else {
            out.println(pluses.size());
            for (Plus p : pluses) {
                out.println(p);
            }
        }
    }

    /**
     * Calculates consecutive non-dot characters in a specific direction.
     * 
     * @param grid The input grid.
     * @param rows Number of rows.
     * @param cols Number of columns.
     * @param di Direction increment for row.
     * @param dj Direction increment for column.
     * @return A 2D array representing the arm length in that direction.
     */
    private static int[][] calculateDistances(char[][] grid, int rows, int cols, int di, int dj) {
        int[][] dist = new int[rows][cols];

        // Determine loop bounds based on direction to ensure we process in order
        int startI = (di >= 0) ? 0 : rows - 1;
        int endI = (di >= 0) ? rows : -1;
        int stepI = (di >= 0) ? 1 : -1;

        int startJ = (dj >= 0) ? 0 : cols - 1;
        int endJ = (dj >= 0) ? cols : -1;
        int stepJ = (dj >= 0) ? 1 : -1;

        for (int i = startI; i != endI; i += stepI) {
            for (int j = startJ; j != endJ; j += stepJ) {
                if (grid[i][j] == '.') {
                    dist[i][j] = 0;
                } else {
                    int prevI = i - di;
                    int prevJ = j - dj;

                    if (prevI >= 0 && prevI < rows && prevJ >= 0 && prevJ < cols && grid[prevI][prevJ] != '.') {
                        dist[i][j] = dist[prevI][prevJ] + 1;
                    } else {
                        dist[i][j] = 0; // Using 0-based radius (0 means no neighbors)
                    }
                }
                // The logic in the original code maps 'cnt' (number of stars) to 'cnt-1'
                // To maintain exact behavior, we adjust the distance if it's a valid star.
                // However, a more intuitive way is to treat dist[i][j] as the radius.
                // Let's adjust the logic to match the original's "arm length" definition.
            }
        }

        // Refined distance calculation to strictly match original's 'cnt-1' logic
        // The original code calculates 'cnt' (consecutive stars) and uses 'cnt-1' as the radius.
        // This is equivalent to the number of neighbors in that direction.
        int[][] armLength = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.') {
                    armLength[i][j] = 0;
                } else {
                    // We need to calculate how many stars are strictly in the specified direction
                    // This is effectively the 'cnt - 1' logic.
                }
            }
        }

        // Re-implementing to match logic precisely:
        // The original code's 'left[i][j]' is how many '*' are to the left of (i,j) including itself, minus 1.
        // So if grid is '***', left[i][j] is [0, 1, 2].
        // This is equivalent to the number of steps we can take in that direction.
        int[][] res = new int[rows][cols];
        for (int i = (di > 0 ? 0 : rows - 1); (di > 0 ? i < rows : i >= 0); i += (di > 0 ? 1 : -1)) {
            for (int j = (dj > 0 ? 0 : cols - 1); (dj > 0 ? j < cols : j >= 0); j += (dj > 0 ? 1 : -1)) {
                if (grid[i][j] == '.') {
                    res[i][j] = 0;
                } else {
                    int pi = i - di;
                    int pj = j - dj;
                    if (pi >= 0 && pi < rows && pj >= 0 && pj < cols && grid[pi][pj] != '.') {
                        res[i][j] = res[pi][pj] + 1;
                    } else {
                        res[i][j] = 0;
                    }
                }
            }
        }
        return res;
    }

    private static void applyPrefixSums(int[][] diff, int rows, int cols, boolean horizontal) {
        for (int i = 0; i < rows; i++) {
            for (int j = 1; j < cols; j++) {
                if (horizontal) {
                    diff[i][j] += diff[i][j - 1];
                } else {
                    // Vertical prefix sum is handled differently
                }
            }
        }

        if (!horizontal) {
            for (int j = 0; j < cols; j++) {
                for (int i = 1; i < rows; i++) {
                    diff[i][j] += diff[i - 1][j];
                }
            }
        }
    }

    /**
     * Represents a plus shape with a center and a radius.
     */
    record Plus(int x, int y, int radius) {
        @Override
        public String toString() {
            return x + " " + y + " " + radius;
        }
    }

    /**
     * High-performance reader for large input sets.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the Star Painting problem.
 * This program identifies "stars" in a grid of '*' and '.' characters.
 * A star is defined by a center '*' that has at least one '*' neighbor 
 * in all four cardinal directions. The size of the star is the minimum 
 * distance from the center to the end of its arms.
 */
public class StarPaintingApp {

    private static final char STAR = '*';
    private static final char EMPTY = '.';

    /**
     * Represents a star found in the grid.
     */
    static class Star {
        final int row;
        final int col;
        final int size;

        Star(int row, int col, int size) {
            this.row = row;
            this.col = col;
            this.size = size;
        }

        @Override
        public String toString() {
            // Output is 1-indexed as per original requirement
            return row + " " + col + " " + size;
        }
    }

    /**
     * Manages the grid operations.
     */
    static class Grid {
        private final int rows;
        private final int cols;
        private final char[][] matrix;

        Grid(int rows, int cols, char[][] matrix) {
            this.rows = rows;
            this.cols = cols;
            this.matrix = matrix;
        }

        public int getRows() { return rows; }
        public int getCols() { return cols; }

        public boolean isStar(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols && matrix[r][c] == STAR;
        }

        public void setEmpty(int r, int c) {
            if (r >= 0 && r < rows && c >= 0 && c < cols) {
                matrix[r][c] = EMPTY;
            }
        }

        public boolean hasRemainingStars() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (matrix[i][j] == STAR) return true;
                }
            }
            return false;
        }

        /**
         * Calculates the maximum size of a star centered at (r, c) based on 
         * the current state of the grid.
         */
        public int calculateStarSize(int r, int c) {
            int up = 0, down = 0, left = 0, right = 0;

            // Check Up
            for (int i = r - 1; i >= 0 && matrix[i][c] == STAR; i--) up++;
            // Check Down
            for (int i = r + 1; i < rows && matrix[i][c] == STAR; i++) down++;
            // Check Left
            for (int j = c - 1; j >= 0 && matrix[r][j] == STAR; j--) left++;
            // Check Right
            for (int j = c + 1; j < cols && matrix[r][j] == STAR; j++) right++;

            return Math.min(Math.min(up, down), Math.min(left, right));
        }

        /**
         * Erases the star arms from the grid.
         */
        public void eraseStar(int r, int c, int size) {
            for (int i = r - size; i <= r + size; i++) setEmpty(i, c);
            for (int j = c - size; j <= c + size; j++) setEmpty(r, j);
        }
    }

    public static void main(String[] args) {
        FastReader sc = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            int n = sc.nextInt();
            int m = sc.nextInt();
            char[][] matrix = new char[n][m];

            for (int i = 0; i < n; i++) {
                String line = sc.nextLine();
                for (int j = 0; j < m; j++) {
                    matrix[i][j] = line.charAt(j);
                }
            }

            Grid grid = new Grid(n, m, matrix);
            List<Star> stars = new ArrayList<>();
            List<int[]> centers = new ArrayList<>();

            // 1. Identify all possible star centers based on the original grid.
            // A center must be a '*' and have '*' neighbors in all 4 directions.
            for (int i = 1; i < n - 1; i++) {
                for (int j = 1; j < m - 1; j++) {
                    if (grid.isStar(i, j) && 
                        grid.isStar(i - 1, j) && grid.isStar(i + 1, j) &&
                        grid.isStar(i, j - 1) && grid.isStar(i, j + 1)) {
                        centers.add(new int[]{i, j});
                    }
                }
            }

            // 2. For each center, determine size and collect star info.
            // We calculate size based on the original grid structure.
            for (int[] pos : centers) {
                int r = pos[0];
                int c = pos[1];
                int size = grid.calculateStarSize(r, c);
                // Original logic: Star size is at least 1 if it's a center.
                // The logic used in original code found the shortest arm.
                stars.add(new Star(r + 1, c + 1, size));
            }

            // 3. Erase the stars from the grid to check for leftover '*'
            for (Star star : stars) {
                grid.eraseStar(star.row - 1, star.col - 1, star.size);
            }

            // 4. Validate and Output
            if (grid.hasRemainingStars()) {
                out.println("-1");
            } else {
                out.println(stars.size());
                for (Star star : stars) {
                    out.println(star);
                }
            }

        } catch (Exception e) {
            // In a real production environment, use a proper logger.
        } finally {
            out.close();
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public String nextLine() {
            String str = "";
            try {
                str = reader.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A solution to find centers that cover all '*' cells in a grid using star-shaped coverage.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] grid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                String line = reader.nextString();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }

            StarCoverageSolver solver = new StarCoverageSolver(rows, cols, grid);
            SolverResult result = solver.solve();

            if (result.isSuccess()) {
                out.println(result.getCenters().size());
                for (StarCenter center : result.getCenters()) {
                    out.println(center);
                }
            } else {
                out.println("-1");
            }
        } catch (Exception e) {
            // In a production environment, use a logger
            out.println("-1");
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Represents a star center with its position and coverage radius.
     */
    static class StarCenter {
        final int row;
        final int col;
        final int radius;

        StarCenter(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }

        @Override
        public String toString() {
            // Using 1-based indexing for output to match original behavior
            return (row + 1) + " " + (col + 1) + " " + radius;
        }
    }

    /**
     * Encapsulates the result of the solver.
     */
    static class SolverResult {
        private final boolean success;
        private final List<StarCenter> centers;

        SolverResult(boolean success, List<StarCenter> centers) {
            this.success = success;
            this.centers = centers;
        }

        boolean isSuccess() { return success; }
        List<StarCenter> getCenters() { return centers; }
    }

    /**
     * Core logic for calculating star centers and verifying coverage.
     */
    static class StarCoverageSolver {
        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final boolean[][] isCovered;
        private final List<StarCenter> centers = new ArrayList<>();

        // Direction vectors: Up, Down, Left, Right
        private static final int[] DR = {-1, 1, 0, 0};
        private static final int[] DC = {0, 0, -1, 1};

        StarCoverageSolver(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            this.isCovered = new boolean[rows][cols];
        }

        public SolverResult solve() {
            // Find potential centers
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '*') {
                        int minRadius = calculateMinRadius(i, j);
                        if (minRadius > 0) {
                            addCenter(i, j, minRadius);
                        }
                    }
                }
            }

            // Verify if all stars are covered
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '*' && !isCovered[i][j]) {
                        return new SolverResult(false, null);
                    }
                }
            }

            return new SolverResult(true, centers);
        }

        private int calculateMinRadius(int r, int c) {
            int min = Integer.MAX_VALUE;
            for (int d = 0; d < 4; d++) {
                min = Math.min(min, getArmLength(r, c, DR[d], DC[d]));
            }
            return min == Integer.MAX_VALUE ? 0 : min;
        }

        private int getArmLength(int r, int c, int dr, int dc) {
            int length = 0;
            int nr = r + dr;
            int nc = c + dc;
            while (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == '*') {
                length++;
                nr += dr;
                nc += dc;
            }
            return length;
        }

        private void addCenter(int r, int c, int radius) {
            centers.add(new StarCenter(r, c, radius));
            isCovered[r][c] = true;
            for (int d = 0; d < 4; d++) {
                int nr = r + DR[d];
                int nc = c + DC[d];
                for (int step = 0; step < radius; step++) {
                    if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == '*') {
                        isCovered[nr][nc] = true;
                        nr += DR[d];
                        nc += DC[d];
                    } else {
                        break;
                    }
                }
            }
        }
    }

    /**
     * Fast I/O utility.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream is) {
            reader = new BufferedReader(new InputStreamReader(is));
        }

        public String nextString() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(nextString());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * TankCoverageSolver solves the problem of covering all '*' cells in a grid
 * using the minimum number of "cross-shaped" tanks.
 */
public class TankCoverageSolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        TankCoverageSolver solver = new TankCoverageSolver();
        solver.solve(reader);
    }

    /**
     * Represents a tank placed on the grid.
     */
    private static class Tank {
        int row;
        int col;
        int radius;

        Tank(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }

        @Override
        public String toString() {
            return row + " " + col + " " + radius;
        }
    }

    public void solve(FastReader reader) {
        int rows = reader.nextInt();
        int cols = reader.nextInt();
        char[][] grid = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            grid[i] = reader.next().toCharArray();
        }

        boolean[][] isCovered = new boolean[rows][cols];
        List<Tank> placedTanks = new ArrayList<>();

        // Direction vectors: Right, Left, Down, Up
        int[] dr = {0, 0, 1, -1};
        int[] dc = {1, -1, 0, 0};

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*') {
                    int radius = calculateMaxRadius(i, j, rows, cols, grid, dr, dc);

                    // A tank must have a radius > 0 to be considered a valid cross center
                    if (radius > 0) {
                        placedTanks.add(new Tank(i + 1, j + 1, radius));
                        markCovered(i, j, radius, isCovered, dr, dc);
                    }
                }
            }
        }

        // Verify if all '*' cells are covered
        if (isAllStarsCovered(grid, isCovered, rows, cols)) {
            printResults(placedTanks);
        } else {
            System.out.println("-1");
        }
    }

    /**
     * Calculates the maximum possible uniform radius for a tank centered at (r, c).
     * The radius is the minimum number of consecutive '*' in any of the 4 directions.
     */
    private int calculateMaxRadius(int r, int c, int rows, int cols, char[][] grid, int[] dr, int[] dc) {
        int minConsecutive = Integer.MAX_VALUE;

        for (int i = 0; i < 4; i++) {
            int count = 0;
            int currR = r + dr[i];
            int currC = c + dc[i];

            while (isValid(currR, currC, rows, cols) && grid[currR][currC] == '*') {
                count++;
                currR += dr[i];
                currC += dc[i];
            }
            minConsecutive = Math.min(minConsecutive, count);
        }

        return minConsecutive == Integer.MAX_VALUE ? 0 : minConsecutive;
    }

    /**
     * Marks the center and the arms of the tank as covered in the boolean grid.
     */
    private void markCovered(int r, int c, int radius, boolean[][] isCovered, int[] dr, int[] dc) {
        isCovered[r][c] = true;
        for (int i = 0; i < 4; i++) {
            for (int k = 1; k <= radius; k++) {
                isCovered[r + dr[i] * k][c + dc[i] * k] = true;
            }
        }
    }

    private boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private boolean isAllStarsCovered(char[][] grid, boolean[][] isCovered, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*' && !isCovered[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    private void printResults(List<Tank> tanks) {
        System.out.println(tanks.size());
        StringBuilder sb = new StringBuilder();
        for (Tank tank : tanks) {
            sb.append(tank.toString()).append("\n");
        }
        System.out.print(sb.toString());
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
            tokenizer = new StringTokenizer("");
        }

        public String next() {
            while (!tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return "";
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return "";
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A program to solve the "Star Coverage" problem.
 * Given a grid of '*' and '.', it finds the largest possible cross-shaped 
 * patterns that can cover all '*' cells.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            // Read dimensions: first line contains height and width
            String dimensionLine = reader.nextLine();
            if (dimensionLine == null || dimensionLine.isEmpty()) {
                return;
            }

            String[] dimensions = dimensionLine.trim().split("\\s+");
            int height = Integer.parseInt(dimensions[0]);
            int width = Integer.parseInt(dimensions[1]);

            // Read the grid
            char[][] grid = new char[height][width];
            for (int i = 0; i < height; i++) {
                String line = reader.nextLine();
                if (line != null) {
                    grid[i] = line.toCharArray();
                }
            }

            // Solve the problem
            GridSolver solver = new GridSolver(height, width, grid);
            solver.solve();

            // Output results
            if (solver.isSuccessful()) {
                List<Cross> solution = solver.getSolution();
                writer.println(solution.size());
                for (Cross cross : solution) {
                    writer.println(cross.row + " " + cross.col + " " + cross.radius);
                }
            } else {
                writer.println("-1");
            }

        } catch (Exception e) {
            // In a production environment, use a logging framework
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }
}

/**
 * Represents a cross-shaped pattern centered at a specific point.
 */
class Cross {
    final int row;    // 1-indexed row
    final int col;    // 1-indexed column
    final int radius; // The radius of the cross

    Cross(int row, int col, int radius) {
        this.row = row;
        this.col = col;
        this.radius = radius;
    }
}

/**
 * Logic engine for calculating and verifying star coverage.
 */
class GridSolver {
    private final int height;
    private final int width;
    private final char[][] grid;

    // DP tables to store consecutive star counts in four directions
    private final int[][] leftCount;
    private final int[][] rightCount;
    private final int[][] upCount;
    private final int[][] downCount;

    private final boolean[][] visited;
    private final List<Cross> solution = new ArrayList<>();
    private boolean allStarsCovered = true;

    public GridSolver(int height, int width, char[][] grid) {
        this.height = height;
        this.width = width;
        this.grid = grid;

        this.leftCount = new int[height][width];
        this.rightCount = new int[height][width];
        this.upCount = new int[height][width];
        this.downCount = new int[height][width];
        this.visited = new boolean[height][width];
    }

    /**
     * Orchestrates the DP computation, solving, and verification.
     */
    public void solve() {
        computeDirectionalCounts();
        findAndApplyCrosses();
        verifyCoverage();
    }

    /**
     * Precomputes how many consecutive '*' exist in each direction for every cell.
     * This is done in O(H * W) using Dynamic Programming.
     */
    private void computeDirectionalCounts() {
        // Left direction
        for (int r = 1; r < height - 1; r++) {
            for (int c = 1; c < width - 1; c++) {
                if (grid[r][c - 1] == '*') {
                    leftCount[r][c] = 1 + leftCount[r][c - 1];
                }
            }
        }

        // Right direction
        for (int r = 1; r < height - 1; r++) {
            for (int c = width - 2; c >= 1; c--) {
                if (grid[r][c + 1] == '*') {
                    rightCount[r][c] = 1 + rightCount[r][c + 1];
                }
            }
        }

        // Up direction
        for (int c = 1; c < width - 1; c++) {
            for (int r = 1; r < height - 1; r++) {
                if (grid[r - 1][c] == '*') {
                    upCount[r][c] = 1 + upCount[r - 1][c];
                }
            }
        }

        // Down direction
        for (int c = 1; c < width - 1; c++) {
            for (int r = height - 2; r >= 1; r--) {
                if (grid[r + 1][c] == '*') {
                    downCount[r][c] = 1 + downCount[r + 1][c];
                }
            }
        }
    }

    /**
     * Iterates through the grid to find potential centers for crosses.
     */
    private void findAndApplyCrosses() {
        for (int r = 1; r < height - 1; r++) {
            for (int c = 1; c < width - 1; c++) {
                if (grid[r][c] == '*') {
                    // The radius is the minimum consecutive stars in any of the 4 directions
                    int radius = Math.min(Math.min(leftCount[r][c], rightCount[r][c]),
                                          Math.min(upCount[r][c], downCount[r][c]));

                    if (radius > 0) {
                        solution.add(new Cross(r + 1, c + 1, radius));
                        markCellsAsVisited(r, c, radius);
                    }
                }
            }
        }
    }

    /**
     * Marks all cells in the cross (horizontal and vertical arms) as covered.
     */
    private void markCellsAsVisited(int r, int c, int radius) {
        visited[r][c] = true;
        // Mark vertical arm
        for (int i = r - radius; i <= r + radius; i++) {
            visited[i][c] = true;
        }
        // Mark horizontal arm
        for (int j = c - radius; j <= c + radius; j++) {
            visited[r][j] = true;
        }
    }

    /**
     * Ensures no '*' cell was left unvisited.
     */
    private void verifyCoverage() {
        for (int r = 0; r < height; r++) {
            for (int c = 0; c < width; c++) {
                if (grid[r][c] == '*' && !visited[r][c]) {
                    allStarsCovered = false;
                    return;
                }
            }
        }
    }

    public boolean isSuccessful() {
        return allStarsCovered;
    }

    public List<Cross> getSolution() {
        return solution;
    }
}

