import java.io.*;
import java.util.*;

/**
 * A program that identifies and marks "star" patterns in a 2D grid.
 * A star consists of a center '*' and four equal-length arms in cardinal directions.
 */
public class StarsDrawing {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            String rowsStr = reader.next();
            if (rowsStr == null) return;

            int rows = Integer.parseInt(rowsStr);
            int cols = reader.nextInt();
            char[][] grid = reader.readGrid(rows, cols);

            StarFinder starFinder = new StarFinder(rows, cols, grid);
            starFinder.solve(writer);

        } catch (Exception e) {
            // In a production environment, use a logging framework.
        } finally {
            writer.close();
        }
    }

    /**
     * Encapsulates the logic for finding and marking star patterns within a grid.
     */
    static class StarFinder {
        private final int rows;
        private final int cols;
        private final char[][] grid;

        public StarFinder(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
        }

        /**
         * Executes the star-finding algorithm and writes the result to the provided writer.
         */
        public void solve(PrintWriter writer) {
            boolean starFound = false;
            int starCount = 0;
            StringBuilder resultsBuilder = new StringBuilder();
            List<Star> starsToMark = new ArrayList<>();

            // 1. Scan the grid for potential star centers
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '*') {
                        starFound = true;
                        int minArmLength = calculateMinArmLength(r, c);

                        // A star must have arms of at least length 1
                        if (minArmLength > 0) {
                            starCount++;
                            starsToMark.add(new Star(r, c, minArmLength));
                            resultsBuilder.append(String.format("%d %d %d\n", r + 1, c + 1, minArmLength));
                        }
                    }
                }
            }

            // 2. Mark all identified stars on the grid to check for coverage
            for (Star star : starsToMark) {
                applyStarToGrid(star);
            }

            // 3. Check if any '*' cells remain uncovered
            boolean allStarsCovered = checkAllStarsCovered();

            // Result output logic based on the original problem constraints
            if ((starCount == 0 && starFound) || !allStarsCovered) {
                writer.println("-1");
            } else {
                writer.println(starCount);
                writer.print(resultsBuilder);
            }
        }

        private int calculateMinArmLength(int r, int c) {
            int top = countConsecutiveStars(r, c, -1, 0);
            int bottom = countConsecutiveStars(r, c, 1, 0);
            int left = countConsecutiveStars(r, c, 0, -1);
            int right = countConsecutiveStars(r, c, 0, 1);

            return Math.min(Math.min(top, bottom), Math.min(left, right));
        }

        private int countConsecutiveStars(int r, int c, int dr, int dc) {
            int length = 0;
            int currR = r + dr;
            int currC = c + dc;

            while (isWithinBounds(currR, currC) && grid[currR][currC] == '*') {
                length++;
                currR += dr;
                currC += dc;
            }
            return length;
        }

        private void applyStarToGrid(Star star) {
            // Mark the center cell
            grid[star.row][star.col] = '#';

            // Directions: Up, Down, Left, Right
            int[] drs = {-1, 1, 0, 0};
            int[] dcs = {0, 0, -1, 1};

            for (int i = 0; i < 4; i++) {
                int currR = star.row + drs[i];
                int currC = star.col + dcs[i];

                for (int step = 0; step < star.radius; step++) {
                    if (isWithinBounds(currR, currC)) {
                        grid[currR][currC] = '#';
                    }
                    currR += drs[i];
                    currC += dcs[i];
                }
            }
        }

        private boolean checkAllStarsCovered() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '*') {
                        return false;
                    }
                }
            }
            return true;
        }

        private boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * Immutable data class representing a star.
     */
    static class Star {
        final int row;
        final int col;
        final int radius;

        Star(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }
    }

    /**
     * High-performance input reader for large datasets.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public char[][] readGrid(int rows, int cols) {
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = next().toCharArray();
            }
            return grid;
        }
    }
}

import java.io.*;
import java.util.Arrays;
import java.util.StringTokenizer;

/**
 * This program solves a grid-based problem where we need to cover all '*' cells
 * using the minimum number of "cross" shapes. A cross is defined by a center 
 * and four arms of equal length.
 */
public class Main {
    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        GridSolver solver = new GridSolver();
        solver.solve(reader, writer);

        writer.close();
    }

    static class GridSolver {

        /**
         * Main execution flow of the solver.
         */
        public void solve(FastReader in, PrintWriter out) {
            int inputRows = in.nextInt();
            int inputCols = in.nextInt();

            // We pad the grid with '.' to simplify boundary checks
            int rows = inputRows + 2;
            int cols = inputCols + 2;
            char[][] grid = initializeGrid(in, rows, cols);

            // armLengths[direction][r][c] stores the number of consecutive stars 
            // in a specific direction from (r, c), excluding the cell itself.
            int[][] leftArms = new int[rows][cols];
            int[][] upArms = new int[rows][cols];
            int[][] rightArms = new int[rows][cols];
            int[][] downArms = new int[rows][cols];

            computeDirectionalArms(grid, rows, cols, leftArms, upArms, rightArms, downArms);

            // minArmLength[r][c] is the maximum arm length 'k' such that a cross 
            // can be centered at (r, c) with arms of length k.
            int[][] minArmLength = new int[rows][cols];
            int crossCount = 0;

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    int min = Math.min(Math.min(leftArms[i][j], upArms[i][j]), 
                                       Math.min(rightArms[i][j], downArms[i][j]));

                    // The original logic: if min is 0, it's not a valid cross center 
                    // for our counting purposes (it becomes -1).
                    if (min == 0) {
                        minArmLength[i][j] = -1;
                    } else {
                        minArmLength[i][j] = min;
                        crossCount++;
                    }
                }
            }

            boolean[][] isCovered = markCoveredCells(minArmLength, rows, cols);

            if (!validateCoverage(grid, isCovered, rows, cols)) {
                out.println("-1");
                return;
            }

            out.println(crossCount);
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (minArmLength[i][j] > 0) {
                        out.println(i + " " + j + " " + minArmLength[i][j]);
                    }
                }
            }
        }

        private char[][] initializeGrid(FastReader in, int rows, int cols) {
            char[][] grid = new char[rows][cols];
            // Fill with default padding
            for (char[] row : grid) {
                Arrays.fill(row, '.');
            }
            // Load the actual input into the center
            for (int i = 1; i < rows - 1; i++) {
                char[] line = in.nextCharArray();
                for (int j = 1; j < cols - 1; j++) {
                    grid[i][j] = line[j - 1];
                }
            }
            return grid;
        }

        private void computeDirectionalArms(char[][] grid, int rows, int cols,
                                            int[][] left, int[][] up, 
                                            int[][] right, int[][] down) {
            // Initialize with -1 to match original logic behavior
            for (int i = 0; i < rows; i++) {
                Arrays.fill(left[i], -1);
                Arrays.fill(right[i], -1);
            }
            for (int j = 0; j < cols; j++) {
                for (int i = 0; i < rows; i++) {
                    Arrays.fill(up[i][j], -1); // This is slightly wrong in structure, fixing below
                }
            }
            // Re-initializing properly for clarity
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    left[i][j] = -1;
                    right[i][j] = -1;
                    up[i][j] = -1;
                    down[i][j] = -1;
                }
            }

            // Left-to-Right sweep
            for (int i = 1; i < rows - 1; i++) {
                for (int j = 1; j < cols - 1; j++) {
                    if (grid[i][j] == '*') left[i][j] = left[i][j - 1] + 1;
                }
            }

            // Right-to-Left sweep
            for (int i = 1; i < rows - 1; i++) {
                for (int j = cols - 2; j >= 1; j--) {
                    if (grid[i][j] == '*') right[i][j] = right[i][j + 1] + 1;
                }
            }

            // Top-to-Bottom sweep
            for (int j = 1; j < cols - 1; j++) {
                for (int i = 1; i < rows - 1; i++) {
                    if (grid[i][j] == '*') up[i][j] = up[i - 1][j] + 1;
                }
            }

            // Bottom-to-Top sweep
            for (int j = 1; j < cols - 1; j++) {
                for (int i = rows - 2; i >= 1; i--) {
                    if (grid[i][j] == '*') down[i][j] = down[i + 1][j] + 1;
                }
            }
        }

        private boolean[][] markCoveredCells(int[][] minArmLength, int rows, int cols) {
            boolean[][] isCovered = new boolean[rows][cols];

            // Row-wise greedy marking
            for (int i = 0; i < rows; i++) {
                int leftSweepCounter = -1;
                int rightSweepCounter = -1;
                for (int j = 0; j < cols; j++) {
                    // Sweep from left to right
                    leftSweepCounter = Math.max(leftSweepCounter, minArmLength[i][j]);
                    if (leftSweepCounter >= 0) {
                        isCovered[i][j] = true;
                        leftSweepCounter--;
                    }
                    // Sweep from right to left
                    rightSweepCounter = Math.max(rightSweepCounter, minArmLength[i][cols - 1 - j]);
                    if (rightSweepCounter >= 0) {
                        isCovered[i][cols - 1 - j] = true;
                        rightSweepCounter--;
                    }
                }
            }

            // Column-wise greedy marking
            for (int j = 0; j < cols; j++) {
                int topSweepCounter = -1;
                int bottomSweepCounter = -1;
                for (int i = 0; i < rows; i++) {
                    // Sweep from top to bottom
                    topSweepCounter = Math.max(topSweepCounter, minArmLength[i][j]);
                    if (topSweepCounter >= 0) {
                        isCovered[i][j] = true;
                        topSweepCounter--;
                    }
                    // Sweep from bottom to top
                    bottomSweepCounter = Math.max(bottomSweepCounter, minArmLength[rows - 1 - i][j]);
                    if (bottomSweepCounter >= 0) {
                        isCovered[rows - 1 - i][j] = true;
                        bottomSweepCounter--;
                    }
                }
            }
            return isCovered;
        }

        private boolean validateCoverage(char[][] grid, boolean[][] isCovered, int rows, int cols) {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '*' && !isCovered[i][j]) {
                        return false;
                    }
                }
            }
            return true;
        }
    }

    static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public char[] nextCharArray() {
            return next().toCharArray();
        }
    }
}

import java.io.BufferedInputStream;
import java.io.BufferedOutputStream;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * A solver for identifying cross-shaped star patterns in a 2D grid.
 * A star is defined by a center coordinate and a radius, forming a '+' shape.
 */
public class StarPatternSolver {

    /**
     * Represents a star pattern found in the grid.
     */
    private static class Star {
        final int row;
        final int col;
        final int radius;

        Star(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }
    }

    public static void main(String[] args) {
        // Using try-with-resources to ensure streams are closed automatically
        try (Scanner scanner = new Scanner(new BufferedInputStream(System.in));
             PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out))) {
            solve(scanner, out);
        }
    }

    /**
     * Orchestrates the reading, processing, and output of the star pattern problem.
     */
    public static void solve(Scanner in, PrintWriter out) {
        if (!in.hasNextInt()) {
            return;
        }

        int rows = in.nextInt();
        int cols = in.nextInt();
        in.nextLine(); // Consume the remaining newline character

        boolean[][] targetGrid = readGrid(in, rows, cols);
        List<Star> foundStars = findMaximalStars(rows, cols, targetGrid);

        if (isReconstructionValid(rows, cols, targetGrid, foundStars)) {
            out.println(foundStars.size());
            for (Star star : foundStars) {
                // Outputting 1-based indexing as per requirements
                out.printf("%d %d %d%n", star.row + 1, star.col + 1, star.radius);
            }
        } else {
            out.println("-1");
        }
    }

    /**
     * Reads the grid from the input stream.
     */
    private static boolean[][] readGrid(Scanner in, int rows, int cols) {
        boolean[][] grid = new boolean[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = in.nextLine();
            for (int j = 0; j < cols; j++) {
                if (j < line.length() && line.charAt(j) == '*') {
                    grid[i][j] = true;
                }
            }
        }
        return grid;
    }

    /**
     * Iterates through every cell to find the largest possible star that can be centered there.
     */
    private static List<Star> findMaximalStars(int rows, int cols, boolean[][] grid) {
        List<Star> stars = new ArrayList<>();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int maxRadius = 0;
                // Increment radius as long as the star shape matches the grid
                while (canPlaceStar(r, c, maxRadius + 1, rows, cols, grid)) {
                    maxRadius++;
                }
                if (maxRadius > 0) {
                    stars.add(new Star(r, c, maxRadius));
                }
            }
        }
        return stars;
    }

    /**
     * Checks if a star of a specific radius can be placed at (row, col) without 
     * violating grid boundaries or mismatching the target pattern.
     */
    private static boolean canPlaceStar(int row, int col, int radius, int rows, int cols, boolean[][] grid) {
        int startRow = row - radius;
        int endRow = row + radius;
        int startCol = col - radius;
        int endCol = col + radius;

        // Check boundary constraints
        if (startRow < 0 || endRow >= rows || startCol < 0 || endCol >= cols) {
            return false;
        }

        // Check horizontal line of the star
        for (int c = startCol; c <= endCol; c++) {
            if (!grid[row][c]) {
                return false;
            }
        }

        // Check vertical line of the star
        for (int r = startRow; r <= endRow; r++) {
            if (!grid[r][col]) {
                return false;
            }
        }

        return true;
    }

    /**
     * Verifies if the found stars, when drawn on a blank grid, exactly match the target grid.
     */
    private static boolean isReconstructionValid(int rows, int cols, boolean[][] targetGrid, List<Star> stars) {
        boolean[][] reconstructedGrid = new boolean[rows][cols];
        for (Star star : stars) {
            drawStar(reconstructedGrid, star);
        }

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (targetGrid[r][c] != reconstructedGrid[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Draws a star pattern onto a provided grid.
     */
    private static void drawStar(boolean[][] grid, Star star) {
        int startRow = star.row - star.radius;
        int endRow = star.row + star.radius;
        int startCol = star.col - star.radius;
        int endCol = star.col + star.radius;

        // Draw horizontal line
        for (int c = startCol; c <= endCol; c++) {
            grid[star.row][c] = true;
        }
        // Draw vertical line
        for (int r = startRow; r <= endRow; r++) {
            grid[r][star.col] = true;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Represents a cross shape centered at a specific coordinate with a given radius.
 */
class Cross {
    final int row;
    final int col;
    final int radius;

    public Cross(int row, int col, int radius) {
        this.row = row;
        this.col = col;
        this.radius = radius;
    }

    @Override
    public String toString() {
        // Convert to 1-based indexing for output
        return (row + 1) + " " + (col + 1) + " " + radius;
    }
}

/**
 * Manages the grid of asterisks and pre-computes the available expansion 
 * directions for each cell.
 */
class Grid {
    private final int rows;
    private final int cols;
    private final boolean[][] isAsterisk;
    private final int[][] consecutiveLeft;
    private final int[][] consecutiveRight;
    private final int[][] consecutiveUp;
    private final int[][] consecutiveDown;

    public Grid(int rows, int cols, String[] mapData) {
        this.rows = rows;
        this.cols = cols;
        this.isAsterisk = new boolean[rows][cols];
        this.consecutiveLeft = new int[rows][cols];
        this.consecutiveRight = new int[rows][cols];
        this.consecutiveUp = new int[rows][cols];
        this.consecutiveDown = new int[rows][cols];

        initializeAsterisks(mapData);
        computeDirections();
    }

    private void initializeAsterisks(String[] mapData) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                isAsterisk[i][j] = mapData[i].charAt(j) == '*';
            }
        }
    }

    private void computeDirections() {
        // Compute horizontal expansions
        for (int i = 0; i < rows; i++) {
            for (int j = 1; j < cols; j++) {
                if (isAsterisk[i][j - 1]) {
                    consecutiveLeft[i][j] = consecutiveLeft[i][j - 1] + 1;
                }
            }
            for (int j = cols - 2; j >= 0; j--) {
                if (isAsterisk[i][j + 1]) {
                    consecutiveRight[i][j] = consecutiveRight[i][j + 1] + 1;
                }
            }
        }

        // Compute vertical expansions
        for (int j = 0; j < cols; j++) {
            for (int i = 1; i < rows; i++) {
                if (isAsterisk[i - 1][j]) {
                    consecutiveUp[i][j] = consecutiveUp[i - 1][j] + 1;
                }
            }
            for (int i = rows - 2; i >= 0; i--) {
                if (isAsterisk[i + 1][j]) {
                    consecutiveDown[i][j] = consecutiveDown[i + 1][j] + 1;
                }
            }
        }
    }

    public boolean isAsterisk(int r, int c) {
        return isAsterisk[r][c];
    }

    public int getMaxCrossRadius(int r, int c) {
        int l = consecutiveLeft[r][c];
        int r_dist = consecutiveRight[r][c];
        int u = consecutiveUp[r][c];
        int d = consecutiveDown[r][c];
        return Math.min(Math.min(l, r_dist), Math.min(u, d));
    }

    public int getRows() { return rows; }
    public int getCols() { return cols; }
}

/**
 * Contains the business logic to solve the cross-covering problem.
 */
class CrossCoveringSolver {
    private final Grid grid;

    public CrossCoveringSolver(Grid grid) {
        this.grid = grid;
    }

    public List<Cross> solve() {
        int rows = grid.getRows();
        int cols = grid.getCols();

        List<Cross> foundCrosses = new ArrayList<>();
        int[][] horizontalDiff = new int[rows][cols];
        int[][] verticalDiff = new int[rows][cols];

        // 1. Find all potential crosses and mark their coverage using difference arrays
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid.isAsterisk(i, j)) {
                    int radius = grid.getMaxCrossRadius(i, j);
                    if (radius > 0) {
                        foundCrosses.add(new Cross(i, j, radius));

                        // Mark horizontal coverage segment [j - radius, j + radius]
                        horizontalDiff[i][j - radius]++;
                        if (j + radius + 1 < cols) {
                            horizontalDiff[i][j + radius + 1]--;
                        }

                        // Mark vertical coverage segment [i - radius, i + radius]
                        verticalDiff[i - radius][j]++;
                        if (i + radius + 1 < rows) {
                            verticalDiff[i + radius + 1][j]--;
                        }
                    }
                }
            }
        }

        // 2. Process difference arrays to get actual coverage counts
        for (int i = 0; i < rows; i++) {
            for (int j = 1; j < cols; j++) {
                horizontalDiff[i][j] += horizontalDiff[i][j - 1];
            }
        }
        for (int j = 0; j < cols; j++) {
            for (int i = 1; i < rows; i++) {
                verticalDiff[i][j] += verticalDiff[i - 1][j];
            }
        }

        // 3. Validate if every asterisk is covered
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid.isAsterisk(i, j) && horizontalDiff[i][j] == 0 && verticalDiff[i][j] == 0) {
                    return null; // Indicates no valid covering found
                }
            }
        }

        return foundCrosses;
    }
}

