/**
 * Refactored solution for the grid coverage problem.
 * The goal is to find a set of center points such that every '*' cell is covered 
 * by a cross-shaped area, maximizing the radius for each center based on 
 * its contiguous horizontal and vertical segments.
 */
public class E1015 {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        Solver solver = new Solver(reader);
        solver.solve(writer);

        writer.flush();
        writer.close();
    }

    static class Solver {
        private final int rows;
        private final int cols;
        private final boolean[][] grid;

        private final int[][] rowSegmentId;
        private final int[][] colSegmentId;

        private final int[] rowSegStart, rowSegEnd;
        private final int[] colSegStart, colSegEnd;

        public Solver(FastReader reader) {
            this.rows = reader.nextInt();
            this.cols = reader.nextInt();
            this.grid = new boolean[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j) == '*';
                }
            }

            this.rowSegmentId = new int[rows][cols];
            this.colSegmentId = new int[rows][cols];
            for (int i = 0; i < rows; i++) {
                Arrays.fill(rowSegmentId[i], -1);
                Arrays.fill(colSegmentId[i], -1);
            }

            // Max possible segments in any direction is rows * cols
            int maxSegments = rows * cols;
            this.rowSegStart = new int[maxSegments];
            this.rowSegEnd = new int[maxSegments];
            this.colSegStart = new int[maxSegments];
            this.colSegEnd = new int[maxSegments];
        }

        public void solve(PrintWriter out) {
            identifySegments();

            FenwickTree[] rowBITs = new FenwickTree[rows];
            for (int i = 0; i < rows; i++) rowBITs[i] = new FenwickTree(cols);

            FenwickTree[] colBITs = new FenwickTree[cols];
            for (int j = 0; j < cols; j++) colBITs[j] = new FenwickTree(rows);

            StringBuilder centerList = new StringBuilder();
            int centerCount = 0;

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (!grid[r][c]) continue;

                    int rid = rowSegmentId[r][c];
                    int cid = colSegmentId[r][c];

                    // Calculate max radius such that the cross stays within segments
                    int horizontalDist = Math.min(c - rowSegStart[rid], rowSegEnd[rid] - c);
                    int verticalDist = Math.min(r - colSegStart[cid], colSegEnd[cid] - r);
                    int radius = Math.min(horizontalDist, verticalDist);

                    if (radius <= 0) continue;

                    // Valid center found
                    centerCount++;
                    centerList.append(r + 1).append(" ").append(c + 1).append(" ").append(radius).append("\n");

                    // Mark coverage in row BIT and column BIT
                    rowBITs[r].updateRange(c - radius, c + radius, 1);
                    colBITs[c].updateRange(r - radius, r + radius, 1);
                }
            }

            if (isAllCovered(rowBITs, colBITs)) {
                out.println(centerCount);
                out.print(centerList.toString());
            } else {
                out.println("-1");
            }
        }

        private void identifySegments() {
            int rowIdCounter = 0;
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] && rowSegmentId[r][c] == -1) {
                        int start = c;
                        while (c < cols && grid[r][c]) {
                            rowSegmentId[r][c] = rowIdCounter;
                            c++;
                        }
                        int end = c - 1;
                        rowSegStart[rowIdCounter] = start;
                        rowSegEnd[rowIdCounter] = end;
                        rowIdCounter++;
                        c--; // Adjust for loop increment
                    }
                }
            }

            int colIdCounter = 0;
            for (int c = 0; c < cols; c++) {
                for (int r = 0; r < rows; r++) {
                    if (grid[r][c] && colSegmentId[r][c] == -1) {
                        int start = r;
                        while (r < rows && grid[r][c]) {
                            colSegmentId[r][c] = colIdCounter;
                            r++;
                        }
                        int end = r - 1;
                        colSegStart[colIdCounter] = start;
                        colSegEnd[colIdCounter] = end;
                        colIdCounter++;
                        r--; // Adjust for loop increment
                    }
                }
            }
        }

        private boolean isAllCovered(FenwickTree[] rowBITs, FenwickTree[] colBITs) {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c]) {
                        // Cell is covered if a center's horizontal or vertical range covers it
                        int coverage = rowBITs[r].queryPoint(c) + colBITs[c].queryPoint(r);
                        if (coverage <= 0) return false;
                    }
                }
            }
            return true;
        }
    }

    /**
     * Fenwick Tree (Binary Indexed Tree) implementation for 
     * range updates and point queries.
     */
    static class FenwickTree {
        private final int[] tree;
        private final int size;

        public FenwickTree(int n) {
            this.size = n;
            this.tree = new int[n + 2]; 
        }

        // Standard BIT update
        private void add(int i, int val) {
            for (i++; i <= size + 1; i += i & -i) {
                tree[i] += val;
            }
        }

        // Range update: adds val to all elements in [l, r]
        public void updateRange(int l, int r, int val) {
            add(l, val);
            add(r + 1, -val);
        }

        // Point query: returns value at index i
        public int queryPoint(int i) {
            int sum = 0;
            for (i++; i > 0; i -= i & -i) {
                sum += tree[i];
            }
            return sum;
        }
    }

    /**
     * Utility class for fast I/O operations.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A solution to find the minimum number of star-shaped patterns 
 * required to cover all '*' characters in a grid.
 */
public class StarPatternSolver {

    private static final int CELL_EMPTY = 0;
    private static final int CELL_STAR = 1;
    private static final int CELL_COVERED = 2;

    /**
     * Represents the center and radius of a star pattern.
     */
    public record StarCenter(int x, int y, int radius) {
        @Override
        public String toString() {
            return x + " " + y + " " + radius;
        }
    }

    /**
     * Manages the grid state and operations.
     */
    static class Grid {
        private final int[][] cells;
        private final int rows;
        private final int cols;

        public Grid(int rows, int cols, String[] inputRows) {
            this.rows = rows;
            this.cols = cols;
            this.cells = new int[rows][cols];
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    cells[i][j] = (inputRows[i].charAt(j) == '*') ? CELL_STAR : CELL_EMPTY;
                }
            }
        }

        public int getCell(int r, int c) {
            if (r < 0 || r >= rows || c < 0 || c >= cols) return CELL_EMPTY;
            return cells[r][c];
        }

        public void markAsCovered(int r, int c) {
            cells[r][c] = CELL_COVERED;
        }

        public boolean hasUncoveredStars() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (cells[i][j] == CELL_STAR) return true;
                }
            }
            return false;
        }

        /**
         * Calculates the maximum possible radius for a star centered at (r, c).
         * A radius of 1 means the star covers (r,c) and its 4 immediate neighbors.
         */
        public Optional<Integer> calculateMaxRadius(int r, int c) {
            if (getCell(r, c) != CELL_STAR) {
                return Optional.empty();
            }

            int[] dr = {-1, 1, 0, 0};
            int[] dc = {0, 0, -1, 1};
            int minConsecutive = Integer.MAX_VALUE;

            for (int i = 0; i < 4; i++) {
                int count = 0;
                int currR = r;
                int currC = c;

                // Count how many consecutive '*' exist in this direction including the center
                while (getCell(currR, currC) == CELL_STAR) {
                    count++;
                    currR += dr[i];
                    currC += dc[i];
                }
                minConsecutive = Math.min(minConsecutive, count);
            }

            // Radius is the number of steps from center. 
            // If minConsecutive is 2 (center + 1 neighbor), radius is 1.
            int radius = minConsecutive - 1;
            return (radius > 0) ? Optional.of(radius) : Optional.empty();
        }

        public void applyStar(int r, int c, int radius) {
            int[] dr = {-1, 1, 0, 0};
            int[] dc = {0, 0, -1, 1};

            // Mark the center
            markAsCovered(r, c);
            // Mark the arms
            for (int i = 0; i < 4; i++) {
                for (int step = 1; step <= radius; step++) {
                    markAsCovered(r + dr[i] * step, c + dc[i] * step);
                }
            }
        }
    }

    public static void solve() throws IOException {
        FastReader sc = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = sc.nextInt();
        int m = sc.nextInt();
        if (n <= 0 || m <= 0) {
            out.close();
            return;
        }

        String[] inputLines = new String[n];
        for (int i = 0; i < n; i++) {
            inputLines[i] = sc.next();
        }

        Grid grid = new Grid(n, m, inputLines);
        List<StarCenter> foundStars = new ArrayList<>();

        // Greedy approach: iterate through the grid and pick star centers
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                Optional<Integer> radiusOpt = grid.calculateMaxRadius(i, j);
                if (radiusOpt.isPresent()) {
                    int radius = radiusOpt.get();
                    grid.applyStar(i, j, radius);
                    // We use 1-based indexing for output to match original requirement
                    foundStars.add(new StarCenter(i + 1, j + 1, radius));
                }
            }
        }

        if (grid.hasUncoveredStars()) {
            out.println("-1");
        } else {
            out.println(foundStars.size());
            for (StarCenter star : foundStars) {
                out.println(star);
            }
        }

        out.flush();
        out.close();
    }

    public static void main(String[] args) {
        try {
            solve();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /**
     * Optimized reader for fast I/O operations.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

/**
 * Solver for the grid coverage problem.
 * The goal is to cover all '*' cells in a grid using the minimum number of "cross" moves.
 */
public class E1015 {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        GridCoverageSolver solver = new GridCoverageSolver();
        solver.solve(reader, out);

        out.close();
    }

    static class Move {
        int row;
        int col;
        int length;

        Move(int row, int col, int length) {
            this.row = row;
            this.col = col;
            this.length = length;
        }

        @Override
        public String toString() {
            // The original problem requires length - 1 in the output
            return String.format("%d %d %d", row, col, length - 1);
        }
    }

    static class GridCoverageSolver {
        private int rows;
        private int cols;
        private boolean[][] isTarget;
        private int[][] horizontalLen;
        private int[][] verticalLen;
        private boolean[][] isCovered;

        public void solve(FastReader reader, PrintWriter out) {
            if (!readInput(reader)) return;

            calculateSegmentLengths();
            List<Move> moves = findMoves();

            if (!validateCoverage()) {
                out.println("-1");
            } else {
                out.println(moves.size());
                for (Move move : moves) {
                    out.println(move);
                }
            }
        }

        private boolean readInput(FastReader reader) {
            try {
                rows = reader.nextInt();
                cols = reader.nextInt();
                isTarget = new boolean[rows][cols];
                for (int i = 0; i < rows; i++) {
                    String rowStr = reader.next();
                    for (int j = 0; j < cols; j++) {
                        isTarget[i][j] = (rowStr.charAt(j) == '*');
                    }
                }
                return true;
            } catch (Exception e) {
                return false;
            }
        }

        /**
         * Precomputes the length of the contiguous segment of '*' cells 
         * each cell belongs to, both horizontally and vertically.
         */
        private void calculateSegmentLengths() {
            horizontalLen = new int[rows][cols];
            verticalLen = new int[rows][cols];

            // Calculate horizontal segment lengths
            for (int i = 0; i < rows; i++) {
                int j = 0;
                while (j < cols) {
                    if (!isTarget[i][j]) {
                        j++;
                        continue;
                    }
                    int start = j;
                    while (j < cols && isTarget[i][j]) {
                        j++;
                    }
                    int length = j - start;
                    for (int k = start; k < j; k++) {
                        horizontalLen[i][k] = length;
                    }
                }
            }

            // Calculate vertical segment lengths
            for (int j = 0; j < cols; j++) {
                int i = 0;
                while (i < rows) {
                    if (!isTarget[i][j]) {
                        i++;
                        continue;
                    }
                    int start = i;
                    while (i < rows && isTarget[i][j]) {
                        i++;
                    }
                    int length = i - start;
                    for (int k = start; k < i; k++) {
                        verticalLen[k][j] = length;
                    }
                }
            }
        }

        /**
         * Finds the optimal moves by picking cells that can center a large cross.
         */
        private List<Move> findMoves() {
            List<Move> moves = new ArrayList<>();
            isCovered = new boolean[rows][cols];

            int[] dr = {-1, 0, 0, 1}; // UP, LEFT, RIGHT, DOWN
            int[] dc = {0, -1, 1, 0};

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (!isTarget[i][j]) continue;

                    // The "reach" is the minimum of the horizontal and vertical segments
                    int minReach = Math.min(horizontalLen[i][j], verticalLen[i][j]);

                    if (minReach >= 2) {
                        moves.add(new Move(i + 1, j + 1, minReach));

                        // Mark cells covered by this cross-shaped move
                        for (int k = 0; k < minReach; k++) {
                            for (int d = 0; d < 4; d++) {
                                int ni = i + k * dr[d];
                                int nj = j + k * dc[d];
                                if (ni >= 0 && ni < rows && nj >= 0 && nj < cols) {
                                    isCovered[ni][nj] = true;
                                }
                            }
                        }
                    }
                }
            }
            return moves;
        }

        private boolean validateCoverage() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (isTarget[i][j] && !isCovered[i][j]) {
                        return false;
                    }
                }
            }
            return true;
        }
    }

    /**
     * Efficient input reader for large datasets.
     */
    static class FastReader {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (numChars == -1) throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) return -1;
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

