/**
 * Handles the logic of finding plus-shaped patterns in a grid.
 */
class PlusShapeFinder {
    private final char[][] board;
    private final int rows;
    private final int cols;
    private final boolean[][] covered;
    private final List<Plus> foundPluses;

    /**
     * Represents a found plus shape.
     */
    private static class Plus {
        final int row;
        final int col;
        final int radius;

        Plus(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }

        @Override
        public String toString() {
            return row + " " + col + " " + radius;
        }
    }

    public PlusShapeFinder(char[][] board, int rows, int cols) {
        this.board = board;
        this.rows = rows;
        this.cols = cols;
        this.covered = new boolean[rows][cols];
        this.foundPluses = new ArrayList<>();
    }

    /**
     * Executes the core algorithm: finds pluses, marks coverage, and validates results.
     */
    public void solve() {
        findPluses();

        if (hasUncoveredStars()) {
            System.out.println("-1");
        } else {
            printResults();
        }
    }

    private void findPluses() {
        // We iterate from 1 to n-2 because a plus must have at least one arm, 
        // meaning the center cannot be on the edge.
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (isPotentialCenter(i, j)) {
                    int radius = calculateMaxRadius(i, j);
                    foundPluses.add(new Plus(i + 1, j + 1, radius));
                    markAsCovered(i, j, radius);
                }
            }
        }
    }

    private boolean isPotentialCenter(int r, int c) {
        return board[r][c] == '*' &&
               board[r - 1][c] == '*' &&
               board[r + 1][c] == '*' &&
               board[r][c - 1] == '*' &&
               board[r][c + 1] == '*';
    }

    private int calculateMaxRadius(int r, int c) {
        int radius = 0;
        // Check how far we can expand the plus arms equally in all four directions
        while (canExpand(r, c, radius + 1)) {
            radius++;
        }
        return radius;
    }

    private boolean canExpand(int r, int c, int dist) {
        return r - dist >= 0 && r + dist < rows &&
               c - dist >= 0 && c + dist < cols &&
               board[r - dist][c] == '*' &&
               board[r + dist][c] == '*' &&
               board[r][c - dist] == '*' &&
               board[r][c + dist] == '*';
    }

    private void markAsCovered(int r, int c, int radius) {
        for (int i = 0; i <= radius; i++) {
            covered[r + i][c] = true;
            covered[r - i][c] = true;
            covered[r][c + i] = true;
            covered[r][c - i] = true;
        }
    }

    private boolean hasUncoveredStars() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (board[i][j] == '*' && !covered[i][j]) {
                    return true;
                }
            }
        }
        return false;
    }

    private void printResults() {
        StringBuilder sb = new StringBuilder();
        sb.append(foundPluses.size()).append("\n");
        for (Plus plus : foundPluses) {
            sb.append(plus.toString()).append("\n");
        }
        System.out.print(sb.toString());
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to find and mark "cross" shapes in a grid.
 * A cross is defined by a center and four arms of equal length.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] gridData = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                gridData[i] = reader.next().toCharArray();
            }

            CrossSolver solver = new CrossSolver(rows, cols, gridData);
            solver.solve();

            if (solver.hasUncoveredTargets()) {
                writer.println("-1");
            } else {
                writer.println(solver.getCrossCount());
                writer.print(solver.getFormattedCrosses());
            }
        } catch (Exception e) {
            // In a production environment, use a logger
            e.printStackTrace();
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Represents a cross shape found in the grid.
     */
    static class Cross {
        final int row;
        final int col;
        final int size;

        Cross(int row, int col, int size) {
            this.row = row;
            this.col = col;
            this.size = size;
        }

        @Override
        public String toString() {
            return row + " " + col + " " + size;
        }
    }

    /**
     * Handles the logic of finding crosses within the grid.
     */
    static class CrossSolver {
        private static final char EMPTY_CHAR = '.';
        private static final char VISITED_CHAR = 'n';
        private static final char TARGET_CHAR = '*';
        private static final int MAX_SEARCH_SIZE = 500;

        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final List<Cross> foundCrosses = new ArrayList<>();

        public CrossSolver(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
        }

        public void solve() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    // If the cell is not empty and not already marked as visited
                    if (grid[i][j] != EMPTY_CHAR && grid[i][j] != VISITED_CHAR) {
                        findLargestCrossAt(i, j);
                    }
                }
            }
        }

        private void findLargestCrossAt(int r, int c) {
            int lastSuccessfulSize = 0;
            int lastR = -1;
            int lastC = -1;

            for (int k = 1; k < MAX_SEARCH_SIZE; k++) {
                if (isValidExpansion(r, c, k)) {
                    // Mark the specific arms for this size
                    markExpansion(r, c, k);
                    lastSuccessfulSize = k;
                    lastR = r;
                    lastC = c;
                } else {
                    break;
                }
            }

            if (lastSuccessfulSize > 0) {
                // Using 1-based indexing for output to match original requirement
                foundCrosses.add(new Cross(lastR + 1, lastC + 1, lastSuccessfulSize));
            }
        }

        private boolean isValidExpansion(int r, int c, int size) {
            // Bounds check
            if (r - size < 0 || r + size >= rows || c - size < 0 || c + size >= cols) {
                return false;
            }
            // Check if any arm hits an empty cell
            return grid[r - size][c] != EMPTY_CHAR &&
                   grid[r + size][c] != EMPTY_CHAR &&
                   grid[r][c - size] != EMPTY_CHAR &&
                   grid[r][c + size] != EMPTY_CHAR;
        }

        private void markExpansion(int r, int c, int size) {
            grid[r][c] = VISITED_CHAR;
            grid[r - size][c] = VISITED_CHAR;
            grid[r + size][c] = VISITED_CHAR;
            grid[r][c - size] = VISITED_CHAR;
            grid[r][c + size] = VISITED_CHAR;
        }

        public boolean hasUncoveredTargets() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == TARGET_CHAR) {
                        return true;
                    }
                }
            }
            return false;
        }

        public int getCrossCount() {
            return foundCrosses.size();
        }

        public String getFormattedCrosses() {
            StringBuilder sb = new StringBuilder();
            for (Cross cross : foundCrosses) {
                sb.append(cross.toString()).append("\n");
            }
            return sb.toString();
        }
    }

    /**
     * Utility class for fast I/O operations.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * A solver to identify cross-shaped patterns in a grid.
 * A cross is defined by a center cell and arms extending equally in four directions.
 */
public class CrossPatternSolver {

    private static final int EMPTY_CELL = 0;
    private static final int WALL_CELL = 1;

    private final int rows;
    private final int cols;
    private final int[][] grid;
    private final boolean[][] visited;
    private final int[][] radii;

    public CrossPatternSolver(int rows, int cols, int[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.visited = new boolean[rows][cols];
        this.radii = new int[rows][cols];
    }

    /**
     * Executes the core logic: finding centers, validating coverage, and collecting results.
     */
    public void solve() {
        calculateRadii();

        if (!areAllWallsCovered()) {
            System.out.println("-1");
            return;
        }

        printResults();
    }

    /**
     * Iterates through the grid to find cells that can act as the center of a cross.
     */
    private void calculateRadii() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == WALL_CELL) {
                    expandCross(r, c);
                }
            }
        }
    }

    /**
     * Checks how many layers of a cross can be formed from the given center.
     */
    private void expandCross(int r, int c) {
        int radius = 0;
        while (true) {
            int nextRadius = radius + 1;
            if (isWithinBounds(r - nextRadius, c) &&
                isWithinBounds(r + nextRadius, c) &&
                isWithinBounds(r, c - nextRadius) &&
                isWithinBounds(r, c + nextRadius) &&
                grid[r - nextRadius][c] == WALL_CELL &&
                grid[r + nextRadius][c] == WALL_CELL &&
                grid[r][c - nextRadius] == WALL_CELL &&
                grid[r][c + nextRadius] == WALL_CELL) {

                radius = nextRadius;
                markAsVisited(r, c, radius);
            } else {
                break;
            }
        }
        radii[r][c] = radius;
    }

    private void markAsVisited(int r, int c, int radius) {
        visited[r][c] = true;
        visited[r - radius][c] = true;
        visited[r + radius][c] = true;
        visited[r][c - radius] = true;
        visited[r][c + radius] = true;
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Validates that every wall cell in the grid is part of at least one cross.
     */
    private boolean areAllWallsCovered() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == WALL_CELL && !visited[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Formats and prints the found centers and their radii.
     */
    private void printResults() {
        List<String> results = new ArrayList<>();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (radii[r][c] > 0) {
                    // Convert to 1-based indexing for output
                    results.add(String.format("%d %d %d", r + 1, c + 1, radii[r][c]));
                }
            }
        }

        System.out.println(results.size());
        for (String line : results) {
            System.out.println(line);
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        scanner.nextLine(); // consume newline

        int[][] grid = new int[n][m];
        for (int i = 0; i < n; i++) {
            String line = scanner.nextLine();
            for (int j = 0; j < m; j++) {
                // '.' is treated as empty (0), anything else is a wall (1)
                grid[i][j] = (line.charAt(j) == '.') ? EMPTY_CELL : WALL_CELL;
            }
        }

        CrossPatternSolver solver = new CrossPatternSolver(n, m, grid);
        solver.solve();

        scanner.close();
    }
}

import java.util.*;
import java.io.*;

/**
 * A solution to find a set of "cross" shapes that cover all '*' cells in a grid.
 * A cross is defined by a center and an arm length extending in four directions.
 */
public class CrossCoverageSolver {

    /**
     * Represents a cross shape centered at (row, col) with a specific arm length.
     */
    private static class Cross {
        final int row;
        final int col;
        final int armLength;

        Cross(int row, int col, int armLength) {
            this.row = row;
            this.col = col;
            this.armLength = armLength;
        }

        @Override
        public String toString() {
            return row + " " + col + " " + armLength;
        }
    }

    public static void main(String[] args) {
        try {
            FastReader reader = new FastReader(System.in);
            PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

            Solver solver = new Solver(reader, out);
            solver.solve();

            out.flush();
            out.close();
        } catch (IOException e) {
            System.err.println("An error occurred during execution: " + e.getMessage());
        }
    }

    private static class Solver {
        private final FastReader reader;
        private final PrintWriter out;

        public Solver(FastReader reader, PrintWriter out) {
            this.reader = reader;
            this.out = out;
        }

        /**
         * Main logic to process the grid and find crosses.
         */
        public void solve() throws IOException {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            List<Cross> foundCrosses = new ArrayList<>();
            boolean[][] isCovered = new boolean[rows][cols];

            // Identify all possible crosses and mark cells they cover
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '*') {
                        int maxRadius = calculateMaxArmRadius(grid, r, c, rows, cols);

                        // A valid cross must have an arm length of at least 1
                        // (radius > 1 means the center and at least one neighbor in each direction is '*')
                        if (maxRadius > 1) {
                            foundCrosses.add(new Cross(r + 1, c + 1, maxRadius - 1));
                            markCellsAsCovered(isCovered, r, c, maxRadius);
                        }
                    }
                }
            }

            // Check if all '*' cells were covered by the found crosses
            if (areAllStarsCovered(grid, isCovered, rows, cols)) {
                out.println(foundCrosses.size());
                for (Cross cross : foundCrosses) {
                    out.println(cross);
                }
            } else {
                out.println("-1");
            }
        }

        /**
         * Calculates the maximum radius 'k' such that the cell and its 
         * neighbors up to distance k in all four cardinal directions are '*'.
         */
        private int calculateMaxArmRadius(char[][] grid, int r, int c, int rows, int cols) {
            // Downward boundary
            int down = r;
            while (down < rows && grid[down][c] == '*') {
                down++;
            }

            // Upward boundary
            int up = r;
            while (up >= 0 && grid[up][c] == '*') {
                up--;
            }

            // Rightward boundary
            int right = c;
            while (right < cols && grid[r][right] == '*') {
                right++;
            }

            // Leftward boundary
            int left = c;
            while (left >= 0 && grid[r][left] == '*') {
                left--;
            }

            int distDown = down - r;
            int distUp = r - up;
            int distRight = right - c;
            int distLeft = c - left;

            return Math.min(Math.min(distDown, distUp), Math.min(distRight, distLeft));
        }

        /**
         * Marks the cells in the coverage grid as true for the given cross.
         */
        private void markCellsAsCovered(boolean[][] isCovered, int r, int c, int radius) {
            for (int k = 0; k < radius; k++) {
                isCovered[r + k][c] = true;
                isCovered[r - k][c] = true;
                isCovered[r][c + k] = true;
                isCovered[r][c - k] = true;
            }
        }

        /**
         * Validates if every '*' in the grid is marked in the coverage array.
         */
        private boolean areAllStarsCovered(char[][] grid, boolean[][] isCovered, int rows, int cols) {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '*' && !isCovered[r][c]) {
                        return false;
                    }
                }
            }
            return true;
        }
    }

    /**
     * Fast utility for reading input using BufferedReader and StringTokenizer.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        public double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to find all maximal '+' shaped patterns formed by '*' in a grid
 * and verify if all '*' cells are covered by these shapes.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        // The original logic processed a single test case.
        int testCases = 1;
        while (testCases-- > 0) {
            GridSolver solver = new GridSolver(reader);
            solver.solve(writer);
        }

        writer.flush();
        writer.close();
    }

    /**
     * Data model representing a '+' shape found in the grid.
     */
    static class Shape {
        final int row;
        final int col;
        final int armLength;

        Shape(int row, int col, int armLength) {
            this.row = row;
            this.col = col;
            this.armLength = armLength;
        }
    }

    /**
     * Logic handler for the grid problem.
     */
    static class GridSolver {
        private final FastReader reader;

        GridSolver(FastReader reader) {
            this.reader = reader;
        }

        public void solve(PrintWriter out) {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            char[][] grid = new char[rows + 2][cols + 2];
            boolean[][] isCovered = new boolean[rows + 2][cols + 2];

            for (int i = 1; i <= rows; i++) {
                String line = reader.next();
                for (int j = 1; j <= cols; j++) {
                    grid[i][j] = line.charAt(j - 1);
                    // If the cell is '.', it is considered "already covered" 
                    // relative to the original logic's goal of checking '*' coverage.
                    isCovered[i][j] = (grid[i][j] == '.');
                }
            }

            // Precompute the maximum continuous '*' in each direction for every cell
            int[][] leftArm = new int[rows + 2][cols + 2];
            int[][] rightArm = new int[rows + 2][cols + 2];
            int[][] upArm = new int[rows + 2][cols + 2];
            int[][] downArm = new int[rows + 2][cols + 2];

            // Forward passes for Left and Up
            for (int i = 1; i <= rows; i++) {
                for (int j = 1; j <= cols; j++) {
                    if (grid[i][j] == '*') {
                        leftArm[i][j] = leftArm[i][j - 1] + 1;
                        upArm[i][j] = upArm[i - 1][j] + 1;
                    }
                }
            }

            // Backward passes for Right and Down
            for (int i = rows; i >= 1; i--) {
                for (int j = cols; j >= 1; j--) {
                    if (grid[i][j] == '*') {
                        rightArm[i][j] = rightArm[i][j + 1] + 1;
                        downArm[i][j] = downArm[i + 1][j] + 1;
                    }
                }
            }

            List<Shape> placedShapes = new ArrayList<>();

            // Identify '+' shapes centered at '*'
            for (int i = 1; i <= rows; i++) {
                for (int j = 1; j <= cols; j++) {
                    if (grid[i][j] == '*') {
                        int minDirectionalArm = Math.min(
                            Math.min(leftArm[i][j], rightArm[i][j]),
                            Math.min(upArm[i][j], downArm[i][j])
                        );

                        // If minDirectionalArm > 1, it means there is at least one '*' 
                        // in every cardinal direction.
                        if (minDirectionalArm > 1) {
                            int actualArmLen = minDirectionalArm - 1;
                            placedShapes.add(new Shape(i, j, actualArmLen));

                            // Mark the center and the arms as "covered"
                            isCovered[i][j] = true;
                            for (int k = 1; k <= actualArmLen; k++) {
                                isCovered[i - k][j] = true;
                                isCovered[i + k][j] = true;
                                isCovered[i][j - k] = true;
                                isCovered[i][j + k] = true;
                            }
                        }
                    }
                }
            }

            // The original logic verifies if all '*' cells were covered by the shapes.
            boolean allStarsCovered = true;
            for (int i = 1; i <= rows; i++) {
                for (int j = 1; j <= cols; j++) {
                    if (!isCovered[i][j]) {
                        allStarsCovered = false;
                        break;
                    }
                }
                if (!allStarsCovered) break;
            }

            if (!allStarsCovered) {
                out.println("-1");
            } else {
                out.println(placedShapes.size());
                for (Shape shape : placedShapes) {
                    out.println(shape.row + " " + shape.col + " " + shape.armLength);
                }
            }
        }
    }

    /**
     * High-performance input reader.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solution to find a set of "Star" patterns that cover all '*' cells in a grid.
 * A Star is defined by its center (r, c) and a radius 's', covering cells 
 * in a cross shape spanning from r-s to r+s and c-s to c+s.
 */
public class Main {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            StarProblemSolver solver = new StarProblemSolver(scanner);
            solver.solve(writer);
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    /**
     * Core logic for solving the Star coverage problem.
     */
    static class StarProblemSolver {
        private final int rowsCount;
        private final int colsCount;
        private final boolean[][] grid;
        private final List<Star> detectedStars = new ArrayList<>();

        // Mapping of grid coordinates to their index in the sorted list of '*' coordinates
        private final Map<Integer, Integer>[] rowCoordToIndex;
        private final Map<Integer, Integer>[] colCoordToIndex;
        private final List<Integer>[] rowStarCoords;
        private final List<Integer>[] colStarCoords;

        public StarProblemSolver(FastScanner scanner) {
            this.rowsCount = scanner.nextInt();
            this.colsCount = scanner.nextInt();
            this.grid = new boolean[rowsCount][colsCount];

            this.rowCoordToIndex = new HashMap[rowsCount];
            this.colCoordToIndex = new HashMap[colsCount];
            this.rowStarCoords = new ArrayList[rowsCount];
            this.colStarCoords = new ArrayList[colsCount];

            for (int i = 0; i < rowsCount; i++) {
                rowCoordToIndex[i] = new HashMap<>();
                rowStarCoords[i] = new ArrayList<>();
            }
            for (int j = 0; j < colsCount; j++) {
                colCoordToIndex[j] = new HashMap<>();
                colStarCoords[j] = new ArrayList<>();
            }

            parseGrid(scanner);
            mapStarCoordinates();
        }

        private void parseGrid(FastScanner scanner) {
            for (int i = 0; i < rowsCount; i++) {
                String line = scanner.next();
                for (int j = 0; j < colsCount; j++) {
                    if (line.charAt(j) == '*') {
                        grid[i][j] = true;
                    }
                }
            }
        }

        private void mapStarCoordinates() {
            // Map column indices for each row
            for (int i = 0; i < rowsCount; i++) {
                int index = 0;
                for (int j = 0; j < colsCount; j++) {
                    if (grid[i][j]) {
                        rowStarCoords[i].add(j);
                        rowCoordToIndex[i].put(j, index++);
                    }
                }
            }
            // Map row indices for each column
            for (int j = 0; j < colsCount; j++) {
                int index = 0;
                for (int i = 0; i < rowsCount; i++) {
                    if (grid[i][j]) {
                        colStarCoords[j].add(i);
                        colCoordToIndex[j].put(i, index++);
                    }
                }
            }
        }

        public void solve(PrintWriter writer) {
            BinaryIndexedTree[] rowBITs = new BinaryIndexedTree[rowsCount];
            BinaryIndexedTree[] colBITs = new BinaryIndexedTree[colsCount];

            for (int i = 0; i < rowsCount; i++) rowBITs[i] = new BinaryIndexedTree(colsCount + 1);
            for (int j = 0; j < colsCount; j++) colBITs[j] = new BinaryIndexedTree(rowsCount + 1);

            // Identify valid stars and update coverage via Difference Array technique in BIT
            for (int i = 0; i < rowsCount; i++) {
                for (int j = 0; j < colsCount; j++) {
                    if (grid[i][j]) {
                        int rowIdx = rowCoordToIndex[i].get(j);
                        int colIdx = colCoordToIndex[j].get(i);

                        int leftRadius = countContiguousLeft(rowStarCoords[i], rowIdx);
                        int rightRadius = countContiguousRight(rowStarCoords[i], rowIdx);
                        int upRadius = countContiguousLeft(colStarCoords[j], colIdx);
                        int downRadius = countContiguousRight(colStarCoords[j], colIdx);

                        int radius = Math.min(Math.min(leftRadius, rightRadius), Math.min(upRadius, downRadius));

                        if (radius > 0) {
                            detectedStars.add(new Star(i, j, radius));
                            // Update row coverage: range [j-radius, j+radius]
                            rowBITs[i].update(j - radius, 1);
                            rowBITs[i].update(j + radius + 1, -1);
                            // Update column coverage: range [i-radius, i+radius]
                            colBITs[j].update(i - radius, 1);
                            colBITs[j].update(i + radius + 1, -1);
                        }
                    }
                }
            }

            // Verify if all '*' are covered
            boolean allCovered = true;
            for (int i = 0; i < rowsCount; i++) {
                for (int j = 0; j < colsCount; j++) {
                    if (grid[i][j]) {
                        // A cell is covered if either its row or its column segment is covered
                        if (rowBITs[i].query(j) == 0 && colBITs[j].query(i) == 0) {
                            allCovered = false;
                            break;
                        }
                    }
                }
                if (!allCovered) break;
            }

            if (allCovered) {
                writer.println(detectedStars.size());
                for (Star star : detectedStars) {
                    writer.println(star);
                }
            } else {
                writer.println("-1");
            }
        }

        private int countContiguousLeft(List<Integer> coords, int index) {
            int targetVal = coords.get(index);
            int low = 0, high = index;
            while (low < high) {
                int mid = (low + high) / 2;
                if (coords.get(mid) == targetVal - (index - mid)) {
                    high = mid;
                } else {
                    low = mid + 1;
                }
            }
            return index - low;
        }

        private int countContiguousRight(List<Integer> coords, int index) {
            int targetVal = coords.get(index);
            int low = index, high = coords.size() - 1;
            while (low < high) {
                int mid = (low + high + 1) / 2;
                if (coords.get(mid) == targetVal + (mid - index)) {
                    low = mid;
                } else {
                    high = mid - 1;
                }
            }
            return low - index;
        }
    }

    /**
     * Data model representing a Star pattern.
     */
    static class Star {
        final int row;
        final int col;
        final int radius;

        Star(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }

        @Override
        public String toString() {
            // Using 1-based indexing for output as per original program
            return String.format("%d %d %d", row + 1, col + 1, radius);
        }
    }

    /**
     * Binary Indexed Tree (Fenwick Tree) for prefix sums and range updates.
     */
    static class BinaryIndexedTree {
        private final int[] tree;

        public BinaryIndexedTree(int size) {
            this.tree = new int[size + 1];
        }

        public void update(int index, int delta) {
            int node = index + 1;
            while (node < tree.length) {
                tree[node] += delta;
                node += node & (-node);
            }
        }

        public int query(int index) {
            int sum = 0;
            int node = index + 1;
            while (node > 0) {
                sum += tree[node];
                node -= node & (-node);
            }
            return sum;
        }
    }

    /**
     * High-performance scanner for integer and string inputs.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

