/**
 * Core logic for detecting and validating star patterns.
 */
class StarSolver {
    private final FastScanner scanner;
    private final FastOutput output;

    public StarSolver(InputStream in, OutputStream out) {
        this.scanner = new FastScanner(in);
        this.output = new FastOutput(out);
    }

    public void solve() {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        boolean[][] isStarCell = new boolean[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            for (int j = 0; j < cols; j++) {
                isStarCell[i][j] = (line.charAt(j) == '*');
            }
        }

        List<Star> foundStars = findStars(rows, cols, isStarCell);

        if (validateCoverage(rows, cols, isStarCell, foundStars)) {
            output.println(foundStars.size());
            for (Star star : foundStars) {
                output.println(star.toString());
            }
        } else {
            output.println("-1");
        }
        output.finish();
    }

    private List<Star> findStars(int rows, int cols, boolean[][] isStarCell) {
        int[][] left = new int[rows][cols];
        int[][] right = new int[rows][cols];
        int[][] top = new int[rows][cols];
        int[][] bottom = new int[rows][cols];

        // Precompute consecutive star counts in all 4 directions
        for (int i = 0; i < rows; i++) {
            int count = 0;
            for (int j = 0; j < cols; j++) {
                left[i][j] = count;
                count = isStarCell[i][j] ? count + 1 : 0;
            }
            count = 0;
            for (int j = cols - 1; j >= 0; j--) {
                right[i][j] = count;
                count = isStarCell[i][j] ? count + 1 : 0;
            }
        }

        for (int j = 0; j < cols; j++) {
            int count = 0;
            for (int i = 0; i < rows; i++) {
                top[i][j] = count;
                count = isStarCell[i][j] ? count + 1 : 0;
            }
            count = 0;
            for (int i = rows - 1; i >= 0; i--) {
                bottom[i][j] = count;
                count = isStarCell[i][j] ? count + 1 : 0;
            }
        }

        List<Star> stars = new ArrayList<>();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (!isStarCell[i][j]) continue;

                int radius = Math.min(Math.min(Math.min(left[i][j], right[i][j]), 
                                               Math.min(top[i][j], bottom[i][j])), 
                                      Math.min(left[i][j], right[i][j])); 
                // Re-calculating min radius to ensure accuracy
                radius = Math.min(Math.min(left[i][j], right[i][j]), 
                                 Math.min(top[i][j], bottom[i][j]));

                if (radius > 0) {
                    stars.add(new Star(i, j, radius));
                }
            }
        }
        return stars;
    }

    private boolean validateCoverage(int rows, int cols, boolean[][] isStarCell, List<Star> stars) {
        int[][] verticalDiff = new int[rows][cols];
        int[][] horizontalDiff = new int[rows][cols];

        // Use difference arrays to mark coverage efficiently
        for (Star star : stars) {
            int r = star.row;
            int c = star.col;
            int rad = star.radius;

            // Mark vertical coverage
            verticalDiff[r - rad][c]++;
            if (r + rad + 1 < rows) {
                verticalDiff[r + rad + 1][c]--;
            }

            // Mark horizontal coverage
            horizontalDiff[r][c - rad]++;
            if (c + rad + 1 < cols) {
                horizontalDiff[r][c + rad + 1]--;
            }
        }

        // Compute prefix sums and verify if coverage matches isStarCell exactly
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (i > 0) verticalDiff[i][j] += verticalDiff[i - 1][j];
                if (j > 0) horizontalDiff[i][j] += horizontalDiff[i][j - 1];

                boolean isCovered = (verticalDiff[i][j] > 0 || horizontalDiff[i][j] > 0);
                if (isCovered != isStarCell[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }
}

