import java.io.*;
import java.util.*;

/**
 * This program identifies "star" patterns in a grid.
 * A star pattern consists of a center '*' and four arms of equal length 
 * extending in cardinal directions, all consisting of '*'.
 */
public class StarPatternSolver {

    private static final int[] DIRECTION_X = {1, -1, 0, 0};
    private static final int[] DIRECTION_Y = {0, 0, -1, 1};

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] grid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            solve(rows, cols, grid, writer);
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    private static void solve(int rows, int cols, char[][] grid, PrintWriter writer) {
        int[][] coverageCount = new int[rows][cols];
        List<Star> foundStars = new ArrayList<>();

        // Iterate through each cell to find potential star centers
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*') {
                    processPotentialStar(r, c, rows, cols, grid, coverageCount, foundStars);
                }
            }
        }

        // Validate if all '*' cells are covered by at least one star pattern
        boolean allStarsCovered = true;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*' && coverageCount[r][c] <= 0) {
                    allStarsCovered = false;
                    break;
                }
            }
            if (!allStarsCovered) break;
        }

        if (!allStarsCovered) {
            writer.println("-1");
        } else {
            writer.println(foundStars.size());
            for (Star star : foundStars) {
                writer.println(star.x + " " + star.y + " " + star.radius);
            }
        }
    }

    /**
     * Expands outwards from a cell to check if it forms a star pattern.
     */
    private static void processPotentialStar(int r, int c, int rows, int cols, 
                                            char[][] grid, int[][] coverageCount, 
                                            List<Star> foundStars) {
        int radius = 0;
        while (true) {
            int nextRadius = radius + 1;
            if (canExpand(r, c, nextRadius, rows, cols, grid)) {
                radius = nextRadius;
                // Mark the cells at the tips of the arms as covered
                for (int i = 0; i < 4; i++) {
                    int targetX = r + DIRECTION_X[i] * radius;
                    int targetY = c + DIRECTION_Y[i] * radius;
                    coverageCount[targetX][targetY]++;
                }
            } else {
                break;
            }
        }

        // If a valid star (radius > 0) was found, mark the center and record it
        if (radius > 0) {
            coverageCount[r][c]++;
            // Adding 1 to coordinates to convert from 0-indexed to 1-indexed
            foundStars.add(new Star(r + 1, c + 1, radius));
        }
    }

    /**
     * Checks if the star can expand to a specific radius in all 4 directions.
     */
    private static boolean canExpand(int r, int c, int radius, int rows, int cols, char[][] grid) {
        for (int i = 0; i < 4; i++) {
            int targetX = r + DIRECTION_X[i] * radius;
            int targetY = c + DIRECTION_Y[i] * radius;

            if (targetX < 0 || targetX >= rows || targetY < 0 || targetY >= cols || grid[targetX][targetY] != '*') {
                return false;
            }
        }
        return true;
    }

    /**
     * Data model representing a discovered star.
     */
    static class Star {
        final int x;
        final int y;
        final int radius;

        Star(int x, int y, int radius) {
            this.x = x;
            this.y = y;
            this.radius = radius;
        }
    }

    /**
     * Optimized reader for large input sets.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public int[] readIntArray(int n) {
            int[] array = new int[n];
            for (int i = 0; i < n; i++) {
                array[i] = nextInt();
            }
            return array;
        }
    }
}

