/**
 * A program to find and cover all non-dot cells in a grid using star shapes.
 */
public class Main {

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter writer = new PrintWriter(System.out)) {

            if (!scanner.hasNextInt()) {
                return;
            }

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            scanner.nextLine(); // Consume the newline character

            char[][] grid = new char[rows][cols];
            boolean[][] covered = new boolean[rows][cols];

            for (int i = 0; i < rows; i++) {
                String line = scanner.nextLine();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                    // A cell is "covered" if it's a dot, as it doesn't need covering.
                    if (grid[i][j] == '.') {
                        covered[i][j] = true;
                    }
                }
            }

            StarSolver solver = new StarSolver(grid, covered);
            List<Star> result = solver.solve();

            if (result == null) {
                writer.println("-1");
            } else {
                writer.println(result.size());
                for (Star star : result) {
                    writer.println(star);
                }
            }
        }
    }
}

/**
 * Represents a star shape with a center coordinate and a radius.
 */
class Star {
    private final int row;
    private final int col;
    private final int radius;

    public Star(int row, int col, int radius) {
        this.row = row;
        this.col = col;
        this.radius = radius;
    }

    @Override
    public String toString() {
        return String.format("%d %d %d", row, col, radius);
    }
}

/**
 * Handles the logic for finding stars to cover the grid.
 */
class StarSolver {
    private final char[][] grid;
    private final boolean[][] covered;
    private final int rows;
    private final int cols;
    private final List<Star> stars = new ArrayList<>();

    public StarSolver(char[][] grid, boolean[][] covered) {
        this.grid = grid;
        this.covered = covered;
        this.rows = grid.length;
        this.cols = grid[0].length;
    }

    /**
     * Executes the star-finding algorithm.
     * @return A list of stars if all cells are covered, otherwise null.
     */
    public List<Star> solve() {
        // Iterate through the interior of the grid as stars require space to expand
        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < cols - 1; c++) {
                if (grid[r][c] == '.') {
                    continue;
                }

                int maxPossibleRadius = calculateMaxPossibleRadius(r, c);
                tryDrawStar(r, c, maxPossibleRadius);
            }
        }

        return isAllCovered() ? stars : null;
    }

    private int calculateMaxPossibleRadius(int r, int c) {
        int distToTop = r;
        int distToBottom = (rows - 1) - r;
        int distToLeft = c;
        int distToRight = (cols - 1) - c;
        return Math.min(Math.min(distToTop, distToBottom), Math.min(distToLeft, distToRight));
    }

    private void tryDrawStar(int r, int c, int maxRadius) {
        int actualRadius = 0;

        // Expand the star as long as the ring of cells is not composed of dots
        for (int k = 1; k <= maxRadius; k++) {
            if (isRingValid(r, c, k)) {
                actualRadius = k;
            } else {
                break;
            }
        }

        if (actualRadius > 0) {
            stars.add(new Star(r + 1, c + 1, actualRadius));
            markAsCovered(r, c, actualRadius);
        }
    }

    private boolean isRingValid(int r, int c, int k) {
        return grid[r - k][c] != '.' &&
               grid[r + k][c] != '.' &&
               grid[r][c - k] != '.' &&
               grid[r][c + k] != '.';
    }

    private void markAsCovered(int r, int c, int radius) {
        covered[r][c] = true;
        for (int k = 1; k <= radius; k++) {
            covered[r - k][c] = true;
            covered[r + k][c] = true;
            covered[r][c - k] = true;
            covered[r][c + k] = true;
        }
    }

    private boolean isAllCovered() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (!covered[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }
}

