import java.util.*;

/**
 * Represents a cross-shaped placement on the grid.
 */
class Cross {
    private final int row;
    private final int col;
    private final int armLength;

    public Cross(int row, int col, int armLength) {
        this.row = row;
        this.col = col;
        this.armLength = armLength;
    }

    @Override
    public String toString() {
        // Outputs 1-based indexing as per original requirements
        return String.format("%d %d %d", row + 1, col + 1, armLength);
    }
}

/**
 * Manages the grid state, including cell values and coverage tracking.
 */
class Grid {
    private final int rows;
    private final int cols;
    private final char[][] cells;
    private final boolean[][] covered;

    private static final int[][] DIRECTIONS = {
        {1, 0}, {-1, 0}, {0, 1}, {0, -1}
    };

    public Grid(int rows, int cols, char[][] cells) {
        this.rows = rows;
        this.cols = cols;
        this.cells = cells;
        this.covered = new boolean[rows][cols];
    }

    /**
     * Calculates the maximum arm length of a cross centered at (r, c).
     * Returns 0 if the center is empty or no arms can be formed.
     */
    public int calculateMaxArmLength(int r, int c) {
        if (cells[r][c] == '.') {
            return 0;
        }

        int maxArm = 0;
        // The arm length cannot exceed the dimensions of the grid
        for (int size = 1; size < Math.max(rows, cols); size++) {
            boolean canExpand = true;
            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0] * size;
                int nc = c + dir[1] * size;

                if (isOutOfBounds(nr, nc) || cells[nr][nc] == '.') {
                    canExpand = false;
                    break;
                }
            }

            if (canExpand) {
                maxArm = size;
            } else {
                break;
            }
        }
        return maxArm;
    }

    /**
     * Marks the center and all arms of a cross as covered.
     */
    public void markAsCovered(int r, int c, int armLength) {
        covered[r][c] = true;
        for (int size = 1; size <= armLength; size++) {
            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0] * size;
                int nc = c + dir[1] * size;
                covered[nr][nc] = true;
            }
        }
    }

    /**
     * Checks if all target characters (e.g., '*') are covered.
     */
    public boolean areAllTargetsCovered(char target) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (cells[r][c] == target && !covered[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    private boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= rows || c < 0 || c >= cols;
    }
}

/**
 * Main class to solve the cross placement problem.
 */
public class CrossPlacementSolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int n = reader.nextInt();
            int m = reader.nextInt();
            reader.nextLine(); // Consume trailing newline after nextInt()

            char[][] gridData = new char[n][m];
            for (int i = 0; i < n; i++) {
                gridData[i] = reader.nextLine().toCharArray();
            }

            Grid grid = new Grid(n, m, gridData);
            List<Cross> placedCrosses = new ArrayList<>();

            // Iterate through every cell to find potential cross centers
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    int armLength = grid.calculateMaxArmLength(i, j);
                    if (armLength > 0) {
                        placedCrosses.add(new Cross(i, j, armLength));
                        grid.markAsCovered(i, j, armLength);
                    }
                }
            }

            // Verify if all required targets ('*') are covered
            if (!grid.areAllTargetsCovered('*')) {
                writer.println("-1");
            } else {
                writer.println(placedCrosses.size());
                for (Cross cross : placedCrosses) {
                    writer.println(cross);
                }
            }

        } catch (Exception e) {
            // In production, replace with a logging framework
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    /**
     * Efficient input reader for handling large datasets.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solution to find the minimum number of "cross" shapes needed to cover all '*' cells in a grid.
 * A cross centered at (r, c) with radius k covers cells in a horizontal and vertical line.
 */
public class CrossProblemSolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] grid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            solve(rows, cols, grid, writer);
        } catch (Exception e) {
            // Handle or log exceptions as appropriate for the environment
        } finally {
            writer.flush();
            writer.close();
        }
    }

    private static void solve(int rows, int cols, char[][] grid, PrintWriter writer) {
        int[][] maxRadii = calculateMaxRadii(rows, cols, grid);
        boolean[][] isCovered = calculateCoverage(rows, cols, maxRadii);

        // 1. Check if all '*' cells are covered
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*' && !isCovered[i][j]) {
                    writer.println("-1");
                    return;
                }
            }
        }

        // 2. Count valid crosses and collect their data
        List<Cross> crosses = new ArrayList<>();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (maxRadii[i][j] > 1) {
                    // Radius in the output is (maxRadii - 1)
                    crosses.add(new Cross(i + 1, j + 1, maxRadii[i][j] - 1));
                }
            }
        }

        // 3. Output results
        writer.println(crosses.size());
        for (Cross cross : crosses) {
            writer.println(cross.row + " " + cross.col + " " + cross.radius);
        }
    }

    /**
     * Calculates the maximum possible radius for a cross centered at each cell.
     * The radius is determined by the minimum number of consecutive '*' in all 4 directions.
     */
    private static int[][] calculateMaxRadii(int rows, int cols, char[][] grid) {
        int[][] maxRadii = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            Arrays.fill(maxRadii[i], Integer.MAX_VALUE);
        }

        // Horizontal passes: Left-to-Right and Right-to-Left
        for (int i = 0; i < rows; i++) {
            int consecutive = 0;
            for (int j = 0; j < cols; j++) {
                consecutive = (grid[i][j] == '*') ? consecutive + 1 : 0;
                maxRadii[i][j] = Math.min(maxRadii[i][j], consecutive);
            }
            consecutive = 0;
            for (int j = cols - 1; j >= 0; j--) {
                consecutive = (grid[i][j] == '*') ? consecutive + 1 : 0;
                maxRadii[i][j] = Math.min(maxRadii[i][j], consecutive);
            }
        }

        // Vertical passes: Top-to-Bottom and Bottom-to-Top
        for (int j = 0; j < cols; j++) {
            int consecutive = 0;
            for (int i = 0; i < rows; i++) {
                consecutive = (grid[i][j] == '*') ? consecutive + 1 : 0;
                maxRadii[i][j] = Math.min(maxRadii[i][j], consecutive);
            }
            consecutive = 0;
            for (int i = rows - 1; i >= 0; i--) {
                consecutive = (grid[i][j] == '*') ? consecutive + 1 : 0;
                maxRadii[i][j] = Math.min(maxRadii[i][j], consecutive);
            }
        }

        // If a cell is not a '*', maxRadii should be 0
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.') {
                    maxRadii[i][j] = 0;
                }
            }
        }

        return maxRadii;
    }

    /**
     * Uses a difference array approach to mark all cells covered by the crosses.
     */
    private static boolean[][] calculateCoverage(int rows, int cols, int[][] maxRadii) {
        boolean[][] isCovered = new boolean[rows][cols];

        // Horizontal coverage pass
        for (int i = 0; i < rows; i++) {
            int[] diff = new int[cols + 1];
            for (int j = 0; j < cols; j++) {
                int r = maxRadii[i][j];
                if (r > 1) {
                    int start = j - r + 1;
                    int end = j + r - 1;
                    diff[start]++;
                    diff[end + 1]--;
                }
            }
            int current = 0;
            for (int j = 0; j < cols; j++) {
                current += diff[j];
                if (current > 0) isCovered[i][j] = true;
            }
        }

        // Vertical coverage pass
        for (int j = 0; j < cols; j++) {
            int[] diff = new int[rows + 1];
            for (int i = 0; i < rows; i++) {
                int r = maxRadii[i][j];
                if (r > 1) {
                    int start = i - r + 1;
                    int end = i + r - 1;
                    diff[start]++;
                    diff[end + 1]--;
                }
            }
            int current = 0;
            for (int i = 0; i < rows; i++) {
                current += diff[i];
                if (current > 0) isCovered[i][j] = true;
            }
        }

        return isCovered;
    }

    /**
     * Data structure to represent a cross.
     */
    private static class Cross {
        int row, col, radius;

        Cross(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }
    }

    /**
     * Efficient input reader.
     */
    private static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

