/**
 * A program to detect diamond-shaped patterns of '*' characters in a grid.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        GridSolver solver = new GridSolver(reader);
        solver.solve();
    }

    /**
     * Represents a diamond pattern found in the grid.
     */
    static class Diamond {
        final int row;
        final int col;
        final int radius;

        Diamond(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }

        @Override
        public String toString() {
            return row + " " + col + " " + radius;
        }
    }

    /**
     * Handles the core logic of solving the grid problem.
     */
    static class GridSolver {
        private final FastReader reader;
        private final PrintWriter out = new PrintWriter(System.out);

        GridSolver(FastReader reader) {
            this.reader = reader;
        }

        public void solve() {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            boolean[][] isCovered = new boolean[rows][cols];
            List<Diamond> diamonds = new ArrayList<>();

            findDiamonds(grid, isCovered, rows, cols, diamonds);

            if (isAllStarsCovered(grid, isCovered, rows, cols)) {
                printResults(diamonds);
            } else {
                out.println("-1");
            }
            out.close();
        }

        private void findDiamonds(char[][] grid, boolean[][] isCovered, int rows, int cols, List<Diamond> diamonds) {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.') {
                        continue;
                    }

                    int span = expandDiamond(grid, isCovered, i, j, rows, cols);
                    if (span > 0) {
                        // Convert 0-indexed to 1-indexed for output
                        diamonds.add(new Diamond(i + 1, j + 1, span));
                    }
                }
            }
        }

        private int expandDiamond(char[][] grid, boolean[][] isCovered, int centerR, int centerC, int rows, int cols) {
            int span = 0;
            int rUp = centerR - 1, rDown = centerR + 1;
            int cLeft = centerC - 1, cRight = centerC + 1;

            // Check if the diamond can expand in all four directions simultaneously
            while (isStarAt(grid, rUp, centerC, rows, cols) &&
                   isStarAt(grid, rDown, centerC, rows, cols) &&
                   isStarAt(grid, centerR, cLeft, rows, cols) &&
                   isStarAt(grid, centerR, cRight, rows, cols)) {

                // Mark the center and the four tips as covered
                isCovered[centerR][centerC] = true;
                isCovered[rUp][centerC] = true;
                isCovered[rDown][centerC] = true;
                isCovered[centerR][cLeft] = true;
                isCovered[centerR][cRight] = true;

                span++;

                // Move tips further out
                rUp--;
                rDown++;
                cLeft--;
                cRight++;
            }
            return span;
        }

        private boolean isStarAt(char[][] grid, int r, int c, int rows, int cols) {
            return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] == '*';
        }

        private boolean isAllStarsCovered(char[][] grid, boolean[][] isCovered, int rows, int cols) {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '*' && !isCovered[i][j]) {
                        return false;
                    }
                }
            }
            return true;
        }

        private void printResults(List<Diamond> diamonds) {
            out.println(diamonds.size());
            for (Diamond d : diamonds) {
                out.println(d);
            }
        }
    }

    /**
     * Optimized reader for fast input processing.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

