import java.util.*;

/**
 * A solver for the Grid Cross Coverage problem.
 * The goal is to cover all '*' (stars) using cross-shaped patterns of a certain level,
 * where a cross of level L covers cells at distance 0 to L in four cardinal directions.
 */
public class GridCrossCoverer {

    private static final char EMPTY = '.';
    private static final char STAR = '*';
    private static final char COVERED = '#';

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final List<Action> actions;

    /**
     * Represents a single cross-shaped action taken on the grid.
     */
    private record Action(int row, int col, int level) {
        @Override
        public String toString() {
            return row + " " + col + " " + level;
        }
    }

    public GridCrossCoverer(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.actions = new ArrayList<>();
    }

    /**
     * Executes the logic to cover stars using the largest possible crosses.
     * @return true if all stars are covered, false otherwise.
     */
    public boolean solve() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                // We only attempt to start a cross from a cell that is not empty
                if (grid[r][c] == EMPTY) {
                    continue;
                }

                int maxLevel = calculateMaxLevel(r, c);

                // If a valid cross can be formed (level > 0)
                if (maxLevel > 0) {
                    actions.add(new Action(r + 1, c + 1, maxLevel));
                    applyCross(r, c, maxLevel);
                }
            }
        }

        return allStarsCovered();
    }

    /**
     * Calculates the maximum radius 'k' for a cross centered at (r, c).
     * A cross can expand if all four cardinal cells at distance k are either stars or already covered.
     */
    private int calculateMaxLevel(int r, int c) {
        int level = 0;
        while (canExpand(r, c, level + 1)) {
            level++;
        }
        return level;
    }

    private boolean canExpand(int r, int c, int k) {
        // Check boundary conditions
        if (r - k < 0 || r + k >= rows || c - k < 0 || c + k >= cols) {
            return false;
        }

        // Check if the four cardinal points at distance k are valid targets
        return isTargetable(grid[r - k][c]) &&
               isTargetable(grid[r + k][c]) &&
               isTargetable(grid[r][c - k]) &&
               isTargetable(grid[r][c + k]);
    }

    private boolean isTargetable(char cell) {
        return cell == STAR || cell == COVERED;
    }

    /**
     * Marks the cells covered by the cross pattern with the COVERED character.
     */
    private void applyCross(int r, int c, int level) {
        for (int k = 0; k <= level; k++) {
            grid[r - k][c] = COVERED;
            grid[r + k][c] = COVERED;
            grid[r][c - k] = COVERED;
            grid[r][c + k] = COVERED;
        }
    }

    private boolean allStarsCovered() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == STAR) {
                    return false;
                }
            }
        }
        return true;
    }

    public int getActionCount() {
        return actions.size();
    }

    public List<Action> getActions() {
        return actions;
    }

    public static void main(String[] args) throws IOException {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = reader.nextInt();
            int m = reader.nextInt();
            char[][] grid = new char[n][m];

            for (int i = 0; i < n; i++) {
                grid[i] = reader.next().toCharArray();
            }

            GridCrossCoverer solver = new GridCrossCoverer(n, m, grid);

            if (solver.solve()) {
                out.println(solver.getActionCount());
                for (Action action : solver.getActions()) {
                    out.println(action);
                }
            } else {
                out.println("-1");
            }
        } catch (Exception e) {
            // Handle or log exception as per requirements
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Efficient reader for fast input processing.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream inputStream) {
            br = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

