/**
 * Solves the problem of covering all '*' cells in a grid using the largest possible stars.
 */
class StarGridSolver {
    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final List<Star> stars;

    public StarGridSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.stars = new ArrayList<>();
    }

    public void solve(PrintWriter out) {
        List<Star> foundStars = findStars();
        if (isGridFullyCovered(foundStars)) {
            out.println(foundStars.size());
            for (Star star : foundStars) {
                out.println(star);
            }
        } else {
            out.println("-1");
        }
    }

    private List<Star> findStars() {
        int[][] starsAbove = new int[rows][cols];
        int[][] starsBelow = new int[rows][cols];
        int[][] starsLeft = new int[rows][cols];
        int[][] starsRight = new int[rows][cols];

        // Calculate consecutive stars in each direction
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (i > 0 && grid[i - 1][j] == '*') {
                    starsAbove[i][j] = starsAbove[i - 1][j] + 1;
                }
                if (j > 0 && grid[i][j - 1] == '*') {
                    starsLeft[i][j] = starsLeft[i][j - 1] + 1;
                }
            }
        }

        for (int i = rows - 1; i >= 0; i--) {
            for (int j = cols - 1; j >= 0; j--) {
                if (i < rows - 1 && grid[i + 1][j] == '*') {
                    starsBelow[i][j] = starsBelow[i + 1][j] + 1;
                }
                if (j < cols - 1 && grid[i][j + 1] == '*') {
                    starsRight[i][j] = starsRight[i][j + 1] + 1;
                }
            }
        }

        List<Star> starList = new ArrayList<>();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*') {
                    int radius = Math.min(Math.min(starsLeft[i][j], starsRight[i][j]),
                                          Math.min(starsAbove[i][j], starsBelow[i][j]));
                    if (radius > 0) {
                        // Note: Using 1-based indexing for the Star output as per original logic
                        starList.add(new Star(i + 1, j + 1, radius));
                    }
                }
            }
        }
        return starList;
    }

    private boolean isGridFullyCovered(List<Star> foundStars) {
        int[][] rowCoverageDiff = new int[rows][cols];
        int[][] colCoverageDiff = new int[rows][cols];

        // Use difference arrays to mark coverage efficiently
        for (Star star : foundStars) {
            int r = star.getRow() - 1; // convert back to 0-based
            int c = star.getCol() - 1;
            int rad = star.getRadius();

            // Horizontal coverage
            rowCoverageDiff[r][c - rad]++;
            if (c + rad + 1 < cols) {
                rowCoverageDiff[r][c + rad + 1]--;
            }

            // Vertical coverage
            colCoverageDiff[r - rad][c]++;
            if (r + rad + 1 < rows) {
                colCoverageDiff[r + rad + 1][c]--;
            }
        }

        // Apply prefix sums to resolve difference arrays
        for (int i = 0; i < rows; i++) {
            for (int j = 1; j < cols; j++) {
                rowCoverageDiff[i][j] += rowCoverageDiff[i][j - 1];
            }
        }
        for (int j = 0; j < cols; j++) {
            for (int i = 1; i < rows; i++) {
                colCoverageDiff[i][j] += colCoverageDiff[i - 1][j];
            }
        }

        // Check if every '*' is covered by either a horizontal or vertical component
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*' && rowCoverageDiff[i][j] <= 0 && colCoverageDiff[i][j] <= 0) {
                    return false;
                }
            }
        }
        return true;
    }
}

/**
 * Fast I/O utility class.
 */
class FastReader {
    private final InputStream in;
    private final byte[] buffer = new byte[8192];
    private int pointer = 0;
    private int bytesRead = 0;

    public FastReader(InputStream in) {
        this.in = in;
    }

    private int readByte() {
        if (pointer >= bytesRead) {
            pointer = 0;
            try {
                bytesRead = in.read(buffer);
            } catch (IOException e) {
                return -1;
            }
            if (bytesRead <= 0) return -1;
        }
        return buffer[pointer++] & 0xFF;
    }

    public int nextInt() {
        int c = readByte();
        while (c != -1 && c <= 32) c = readByte();
        if (c == -1) return 0;
        int sign = 1;
        if (c == '-') {
            sign = -1;
            c = readByte();
        }
        int res = 0;
        while (c >= '0' && c <= '9') {
            res = res * 10 + (c - '0');
            c = readByte();
        }
        return res * sign;
    }

    public String nextString() {
        int c = readByte();
        while (c != -1 && c <= 32) c = readByte();
        if (c == -1) return "";
        StringBuilder sb = new StringBuilder();
        while (c > 32) {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }
}

public class Main {
    public static void main(String[] args) {
        FastReader fr = new FastReader(System.in);
        PrintWriter pw = new PrintWriter(System.out);

        int rows = fr.nextInt();
        int cols = fr.nextInt();

        if (rows <= 0 || cols <= 0) {
            pw.close();
            return;
        }

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = fr.nextString().toCharArray();
        }

        StarGridSolver solver = new StarGridSolver(rows, cols, grid);
        solver.solve(pw);

        pw.flush();
        pw.close();
    }
}

