class GridSolver {
    private final int rows;
    private final int cols;
    private final char[][] grid;

    public GridSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
    }

    /**
     * Represents a found plus shape.
     */
    private static class Plus {
        final int r, c, armLength;

        Plus(int r, int c, int armLength) {
            this.r = r;
            this.c = c;
            this.armLength = armLength;
        }

        @Override
        public String toString() {
            return (r + 1) + " " + (c + 1) + " " + armLength + "\n";
        }
    }

    /**
     * Container for the solver's output.
     */
    public static class Result {
        private final boolean success;
        private final int count;
        private final String output;

        public Result(boolean success, int count, String output) {
            this.success = success;
            this.count = count;
            this.output = output;
        }

        public boolean isSuccessful() { return success; }
        public int getCount() { return count; }
        public String getOutput() { return output; }
    }

    public Result solve() {
        int[][] up = computeUp();
        int[][] down = computeDown();
        int[][] left = computeLeft();
        int[][] right = computeRight();

        char[][] reconstructed = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            Arrays.fill(reconstructed[i], '.');
        }

        List<Plus> foundPluses = new ArrayList<>();
        int count = 0;

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                // The arm length is the minimum consecutive stars in all 4 directions minus the center cell
                int minConsecutive = Math.min(Math.min(up[i][j], down[i][j]), 
                                              Math.min(left[i][j], right[i][j]));
                int armLength = minConsecutive - 1;

                if (armLength >= 1) {
                    foundPluses.add(new Plus(i, j, armLength));
                    fillReconstructed(reconstructed, i, j, armLength);
                    count++;
                }
            }
        }

        if (isGridMatch(grid, reconstructed)) {
            StringBuilder sb = new StringBuilder();
            for (Plus p : foundPluses) {
                sb.append(p.toString());
            }
            return new Result(true, count, sb.toString());
        } else {
            return new Result(false, 0, "");
        }
    }

    private void fillReconstructed(char[][] target, int row, int col, int armLength) {
        target[row][col] = '*';
        for (int i = 1; i <= armLength; i++) {
            target[row + i][col] = '*';
            target[row - i][col] = '*';
            target[row][col + i] = '*';
            target[row][col - i] = '*';
        }
    }

    private boolean isGridMatch(char[][] original, char[][] reconstructed) {
        for (int i = 0; i < rows; i++) {
            if (!Arrays.equals(original[i], reconstructed[i])) {
                return false;
            }
        }
        return true;
    }

    private int[][] computeUp() {
        int[][] res = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*') {
                    res[i][j] = 1 + (i > 0 ? res[i - 1][j] : 0);
                }
            }
        }
        return res;
    }

    private int[][] computeDown() {
        int[][] res = new int[rows][cols];
        for (int i = rows - 1; i >= 0; i--) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*') {
                    res[i][j] = 1 + (i < rows - 1 ? res[i + 1][j] : 0);
                }
            }
        }
        return res;
    }

    private int[][] computeLeft() {
        int[][] res = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*') {
                    res[i][j] = 1 + (j > 0 ? res[i][j - 1] : 0);
                }
            }
        }
        return res;
    }

    private int[][] computeRight() {
        int[][] res = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = cols - 1; j >= 0; j--) {
                if (grid[i][j] == '*') {
                    res[i][j] = 1 + (j < cols - 1 ? res[i][j + 1] : 0);
                }
            }
        }
        return res;
    }
}

/**
 * Fast I/O utility for efficient reading.
 */
class FastReader {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    public FastReader(InputStream input) {
        reader = new BufferedReader(new InputStreamReader(input));
    }

    public String next() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreElements()) {
            String line = reader.readLine();
            if (line == null) return null;
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    public int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    public String nextRow() throws IOException {
        // If tokenizer has leftover tokens from the previous nextInt(), 
        // we must consume the rest of that line to avoid reading empty strings.
        if (tokenizer != null && tokenizer.hasMoreTokens()) {
            StringBuilder sb = new StringBuilder(tokenizer.nextToken());
            while (tokenizer.hasMoreTokens()) {
                sb.append(" ").append(tokenizer.nextToken());
            }
            return sb.toString();
        }
        return reader.readLine();
    }
}

