/**
 * Represents a mathematical "plus" shape found in the grid.
 */
class PlusShape {
    private final int row;
    private final int col;
    private final int radius;

    public PlusShape(int row, int col, int radius) {
        this.row = row;
        this.col = col;
        this.radius = radius;
    }

