}

/**
 * Encapsulates the result of the grid analysis.
 */
class SolverResult {
    private final boolean possible;
    private final List<PlusShape> shapes;

    private SolverResult(boolean possible, List<PlusShape> shapes) {
        this.possible = possible;
        this.shapes = shapes;
    }

    public static SolverResult success(List<PlusShape> shapes) {
        return new SolverResult(true, shapes);
    }

    public static SolverResult failure() {
        return new SolverResult(false, Collections.emptyList());
    }

    public boolean isPossible() { return possible; }
    public List<PlusShape> getShapes() { return shapes; }
}

/**
 * Contains the core logic for finding plus shapes and validating grid coverage.
 */
class PlusShapeFinder {
    private final char[][] grid;
    private final int rows;
    private final int cols;

    public PlusShapeFinder(char[][] grid) {
        this.grid = grid;
        this.rows = grid.length;
        this.cols = grid.length > 0 ? grid[0].length : 0;
    }

    /**
     * Analyzes the grid to find all plus shapes and ensures every '*' is covered.
     * @return A SolverResult indicating success (with shapes) or failure.
     */
    public SolverResult solve() {
        boolean[][] covered = new boolean[rows][cols];
        List<PlusShape> foundShapes = new ArrayList<>();

        // A plus shape needs at least a 3x3 area to have a radius of 1
        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < cols - 1; c++) {
                if (grid[r][c] == '*') {
                    int radius = findMaxRadius(r, c);
                    if (radius > 0) {
                        foundShapes.add(new PlusShape(r + 1, c + 1, radius));
                        markCoverage(covered, r, c, radius);
                    }
                }
            }
        }

        if (isCoverageValid(covered)) {
            return SolverResult.success(foundShapes);
        } else {
            return SolverResult.failure();
        }
    }

    private int findMaxRadius(int r, int c) {
        int radius = 0;
        while (true) {
            int nextRadius = radius + 1;
            if (isWithinBounds(r, c, nextRadius) && 
                grid[r - nextRadius][c] == '*' &&
                grid[r + nextRadius][c] == '*' &&
                grid[r][c - nextRadius] == '*' &&
                grid[r][c + nextRadius] == '*') {
                radius = nextRadius;
            } else {
                break;
            }
        }
        return radius;
    }

    private void markCoverage(boolean[][] covered, int r, int c, int radius) {
        covered[r][c] = true; // Center
        for (int i = 1; i <= radius; i++) {
            covered[r - i][c] = true;
            covered[r + i][c] = true;
            covered[r][c - i] = true;
            covered[r][c + i] = true;
        }
    }

    private boolean isCoverageValid(boolean[][] covered) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                boolean isStar = (grid[r][c] == '*');
                // If it's a star but not covered, or covered but not a star, it's invalid
                if (isStar != covered[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    private boolean isWithinBounds(int r, int c, int radius) {
        return r - radius >= 0 && r + radius < rows &&
               c - radius >= 0 && c + radius < cols;
    }
}

