import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * A solver for the Stars Drawing problem.
 * The goal is to cover all '*' characters using the minimum number of star shapes.
 */
public class StarDrawingSolver {

    private static final char STAR = '*';
    private static final char PROCESSED = 'X';

    /**
     * Represents a successfully placed star.
     */
    private static class StarPlacement {
        final int row;
        final int col;
        final int radius;

        StarPlacement(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }

        @Override
        public String toString() {
            // Return 1-based coordinates to match original problem expectations
            return (row + 1) + " " + (col + 1) + " " + radius;
        }
    }

    private final int rowCount;
    private final int colCount;
    private final char[][] grid;
    private final List<StarPlacement> placements;

    public StarDrawingSolver(int rowCount, int colCount, char[][] grid) {
        this.rowCount = rowCount;
        this.colCount = colCount;
        this.grid = grid;
        this.placements = new ArrayList<>();
    }

    /**
     * Executes the greedy algorithm to place stars.
     * @return true if all stars were covered, false otherwise.
     */
    public boolean solve() {
        for (int r = 0; r < rowCount; r++) {
            for (int c = 0; c < colCount; c++) {
                // If the cell is a star or already part of a previous star, try centering a star here
                if (grid[r][c] == STAR || grid[r][c] == PROCESSED) {
                    attemptToPlaceStarAt(r, c);
                }
            }
        }
        return isAllStarsCovered();
    }

    private void attemptToPlaceStarAt(int r, int c) {
        int maxPossibleRad = calculateMaxRadius(r, c);

        // Try placing the largest possible star first (Greedy approach)
        for (int rad = maxPossibleRad; rad >= 1; rad--) {
            if (canPlaceStar(r, c, rad)) {
                applyStar(r, c, rad);
                placements.add(new StarPlacement(r, c, rad));
                break;
            }
        }
    }

    private int calculateMaxRadius(int r, int c) {
        int distToTop = r;
        int distToBottom = rowCount - 1 - r;
        int distToLeft = c;
        int distToRight = colCount - 1 - c;
        return Math.min(Math.min(distToTop, distToBottom), Math.min(distToLeft, distToRight));
    }

    private boolean canPlaceStar(int r, int c, int radius) {
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int i = 0; i < 4; i++) {
            for (int step = 1; step <= radius; step++) {
                int nr = r + dr[i] * step;
                int nc = c + dc[i] * step;

                // A star arm can only pass through '*' or already processed 'X'
                if (grid[nr][nc] != STAR && grid[nr][nc] != PROCESSED) {
                    return false;
                }
            }
        }
        return true;
    }

    private void applyStar(int r, int c, int radius) {
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        // Mark center
        grid[r][c] = PROCESSED;

        // Mark arms
        for (int i = 0; i < 4; i++) {
            for (int step = 1; step <= radius; step++) {
                grid[r + dr[i] * step][c + dc[i] * step] = PROCESSED;
            }
        }
    }

    private boolean isAllStarsCovered() {
        for (int r = 0; r < rowCount; r++) {
            for (int c = 0; c < colCount; c++) {
                if (grid[r][c] == STAR) {
                    return false;
                }
            }
        }
        return true;
    }

    public List<StarPlacement> getPlacements() {
        return placements;
    }

    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            if (!sc.hasNextInt()) return;

            int n = sc.nextInt();
            int m = sc.nextInt();
            char[][] grid = new char[n][m];

            for (int i = 0; i < n; i++) {
                String rowString = sc.next();
                grid[i] = rowString.toCharArray();
            }

            StarDrawingSolver solver = new StarDrawingSolver(n, m, grid);
            if (solver.solve()) {
                System.out.println(solver.getPlacements().size());
                for (StarPlacement placement : solver.getPlacements()) {
                    System.out.println(placement);
                }
            } else {
                System.out.println("-1");
            }
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to find and mark star-shaped patterns in a grid of characters.
 */
public class StarDrawing {

    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in);
             PrintWriter pw = new PrintWriter(System.out)) {

            if (!sc.hasNextInt()) return;
            int n = sc.nextInt();
            int m = sc.nextInt();

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                grid[i] = sc.next().toCharArray();
            }

            StarDrawingSolver solver = new StarDrawingSolver(n, m, grid);
            solver.solve(pw);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * Record to store the coordinate and radius of a found star.
     */
    private record Star(int row, int col, int radius) {
        @Override
        public String toString() {
            return String.format("%d %d %d", row + 1, col + 1, radius);
        }
    }

    /**
     * Core logic engine for solving the Star Drawing problem.
     */
    private static class StarDrawingSolver {
        private final int rows;
        private final int cols;
        private final char[][] grid;

        public StarDrawingSolver(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
        }

        public void solve(PrintWriter pw) {
            boolean initiallyHasStars = hasAnyStars('*');

            // Pre-calculate how many '*' extend in each direction from every cell
            int[][] leftDist = computeDirectionalDistances(0, 0, 0, 1);   // Left
            int[][] rightDist = computeDirectionalDistances(0, 1, 0, -1); // Right
            int[][] upDist = computeDirectionalDistances(-1, 0, 1, 0);    // Up
            int[][] downDist = computeDirectionalDistances(1, 0, -1, 0);  // Down

            List<Star> foundStars = new ArrayList<>();

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '*') {
                        // The radius is the minimum extension in all four directions
                        int radius = Math.min(Math.min(leftDist[r][c], rightDist[r][c]),
                                              Math.min(upDist[r][c], downDist[r][c]));

                        if (radius > 0) {
                            foundStars.add(new Star(r, c, radius));
                            markStar(r, c, radius);
                        }
                    }
                }
            }

            // Validation:
            // 1. If stars were expected (initiallyHasStars) but none were found (foundStars.isEmpty())
            // 2. If there are '*' characters left that weren't part of any star
            boolean starsRemaining = hasAnyStars('*');

            if ((foundStars.isEmpty() && initiallyHasStars) || starsRemaining) {
                pw.println("-1");
            } else {
                pw.println(foundStars.size());
                for (Star star : foundStars) {
                    pw.println(star);
                }
            }
        }

        /**
         * Computes distances in a specific direction using Dynamic Programming.
         * 
         * @param dr Row direction step (-1, 0, 1)
         * @param dc Column direction step (-1, 0, 1)
         * @param startR Starting row for iteration
         * @param endR Ending row for iteration (inclusive)
         * @return 2D array containing distances
         */
        private int[][] computeDirectionalDistances(int dr, int dc, int startR, int endR) {
            // Note: The original logic used loops that were somewhat complex. 
            // This approach ensures we calculate directionally in one pass.
            int[][] dist = new int[rows][cols];

            // Determine iteration order based on direction to ensure DP dependency is met
            int rowStep = (dr >= 0) ? 1 : -1;
            int colStep = (dc >= 0) ? 1 : -1;

            // For simplicity in this specific problem, we use standard iteration 
            // and just handle the dependency direction carefully.
            // We'll iterate in a way that the "previous" cell in the direction is already computed.

            // Directions: 
            // Left: col 0 -> m-1
            // Right: col m-1 -> 0
            // Up: row 0 -> n-1
            // Down: row n-1 -> 0

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    // We use a logic that works regardless of the direction step by 
                    // adjusting the loop bounds or simply checking bounds.
                }
            }

            // Re-implementing the direction logic clearly:
            if (dr == 0 && dc == 1) { // Left direction (checking cell to the left)
                for (int r = 0; r < rows; r++) {
                    for (int c = 1; c < cols; c++) {
                        if (grid[r][c] == '*' && grid[r][c-1] == '*') dist[r][c] = 1 + dist[r][c-1];
                    }
                }
            } else if (dr == 0 && dc == -1) { // Right direction (checking cell to the right)
                for (int r = 0; r < rows; r++) {
                    for (int c = cols - 2; c >= 0; c--) {
                        if (grid[r][c] == '*' && grid[r][c+1] == '*') dist[r][c] = 1 + dist[r][c+1];
                    }
                }
            } else if (dr == 1 && dc == 0) { // Up direction (checking cell above)
                for (int c = 0; c < cols; c++) {
                    for (int r = 1; r < rows; r++) {
                        if (grid[r][c] == '*' && grid[r-1][c] == '*') dist[r][c] = 1 + dist[r-1][c];
                    }
                }
            } else if (dr == -1 && dc == 0) { // Down direction (checking cell below)
                for (int c = 0; c < cols; c++) {
                    for (int r = rows - 2; r >= 0; r--) {
                        if (grid[r][c] == '*' && grid[r+1][c] == '*') dist[r][c] = 1 + dist[r+1][c];
                    }
                }
            }
            return dist;
        }

        private void markStar(int r, int c, int radius) {
            grid[r][c] = '#'; // Center
            for (int i = 1; i <= radius; i++) {
                grid[r + i][c] = '#';
                grid[r - i][c] = '#';
                grid[r][c + i] = '#';
                grid[r][c - i] = '#';
            }
        }

        private boolean hasAnyStars(char target) {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == target) return true;
                }
            }
            return false;
        }
    }
}

