/**
 * A solver to identify star-shaped patterns in a 2D grid.
 * A star pattern is defined by a center cell and a radius where the 
 * top, bottom, left, and right cells at each step of the radius are '*' characters.
 */
public class Main {
    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int testCases = reader.nextInt();
            for (int t = 0; t < testCases; t++) {
                StarPatternSolver solver = new StarPatternSolver(reader);
                solver.solve(out);
            }
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            out.close();
        }
    }
}

class StarPatternSolver {
    private final FastReader reader;
    private int rows;
    private int cols;
    private char[][] grid;
    private boolean[][] isCovered;

    public StarPatternSolver(FastReader reader) {
        this.reader = reader;
    }

    /**
     * Orchestrates the pattern detection and validation logic.
     */
    public void solve(PrintWriter out) throws IOException {
        rows = reader.nextInt();
        cols = reader.nextInt();
        grid = new char[rows][cols];
        isCovered = new boolean[rows][cols];

        for (int i = 0; i < rows; i++) {
            grid[i] = reader.next().toCharArray();
        }

        List<StarPattern> patterns = findStarPatterns();

        if (allStarsCovered()) {
            out.println(patterns.size());
            for (StarPattern pattern : patterns) {
                out.println(pattern.row() + " " + pattern.col() + " " + pattern.radius());
            }
        } else {
            out.println("-1");
        }
    }

    /**
     * Iterates through the grid to find every possible star pattern center.
     */
    private List<StarPattern> findStarPatterns() {
        List<StarPattern> patterns = new ArrayList<>();

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*') {
                    int radius = calculateStarRadius(i, j);
                    if (radius > 0) {
                        // Convert 0-indexed to 1-indexed for output
                        patterns.add(new StarPattern(i + 1, j + 1, radius));
                    }
                }
            }
        }
        return patterns;
    }

    /**
     * Calculates the maximum expansion radius of a star centered at (row, col).
     * As it finds valid layers, it marks the perimeter cells as covered.
     */
    private int calculateStarRadius(int row, int col) {
        int radius = 0;
        int up = row - 1;
        int down = row + 1;
        int left = col - 1;
        int right = col + 1;

        while (up >= 0 && down < rows && left >= 0 && right < cols &&
               grid[up][col] == '*' && grid[down][col] == '*' &&
               grid[row][left] == '*' && grid[row][right] == '*') {

            isCovered[up][col] = true;
            isCovered[down][col] = true;
            isCovered[row][left] = true;
            isCovered[row][right] = true;

            radius++;
            up--;
            down++;
            left--;
            right++;
        }

        if (radius > 0) {
            isCovered[row][col] = true;
        }
        return radius;
    }

    /**
     * Checks if every '*' in the original grid has been marked as covered.
     */
    private boolean allStarsCovered() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*' && !isCovered[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }
}

