import java.io.*;
import java.util.*;

/**
 * A solution to identify the largest possible "stars" in a grid of characters
 * and verify if the union of these stars perfectly reconstructs the original grid.
 */
public class StarSolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            solve(reader, writer);
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            writer.flush();
            writer.close();
        }
    }

    private static void solve(FastReader reader, PrintWriter writer) throws IOException {
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        char[][] originalGrid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            originalGrid[i] = reader.next().toCharArray();
        }

        List<Star> stars = findStars(originalGrid, rows, cols);
        char[][] reconstructedGrid = reconstructGrid(stars, rows, cols);

        if (isMatch(originalGrid, reconstructedGrid, rows, cols)) {
            writer.println(stars.size());
            for (Star star : stars) {
                // Output is 1-indexed as per original requirement
                writer.printf("%d %d %d%n", star.row + 1, star.col + 1, star.radius);
            }
        } else {
            writer.println("-1");
        }
    }

    /**
     * Finds the largest possible star centered at each '*' cell.
     * A star is defined by a center (r, c) and a radius s, 
     * covering a horizontal and vertical line of length 2s + 1.
     */
    private static List<Star> findStars(char[][] grid, int rows, int cols) {
        int[][] left = new int[rows][cols];
        int[][] right = new int[rows][cols];
        int[][] up = new int[rows][cols];
        int[][] down = new int[rows][cols];

        // Calculate distances to the nearest '.' or boundary in all 4 directions
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*') {
                    left[i][j] = (j > 0 ? left[i][j - 1] : 0) + 1;
                }
            }
            for (int j = cols - 1; j >= 0; j--) {
                if (grid[i][j] == '*') {
                    right[i][j] = (j < cols - 1 ? right[i][j + 1] : 0) + 1;
                }
            }
        }

        for (int j = 0; j < cols; j++) {
            for (int i = 0; i < rows; i++) {
                if (grid[i][j] == '*') {
                    up[i][j] = (i > 0 ? up[i - 1][j] : 0) + 1;
                }
            }
            for (int i = rows - 1; i >= 0; i--) {
                if (grid[i][j] == '*') {
                    down[i][j] = (i < rows - 1 ? down[i + 1][j] : 0) + 1;
                }
            }
        }

        List<Star> stars = new ArrayList<>();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*') {
                    // The radius is the minimum extension possible in all 4 directions minus the center itself
                    int minExtension = Math.min(Math.min(left[i][j], right[i][j]), 
                                                Math.min(up[i][j], down[i][j]));
                    int radius = minExtension - 1;
                    if (radius > 0) {
                        stars.add(new Star(i, j, radius));
                    }
                }
            }
        }
        return stars;
    }

    /**
     * Uses difference arrays to reconstruct the grid from the list of stars.
     */
    private static char[][] reconstructGrid(List<Star> stars, int rows, int cols) {
        int[][] horizontalDiff = new int[rows][cols];
        int[][] verticalDiff = new int[rows][cols];

        for (Star star : stars) {
            // Mark horizontal line segment [col - radius, col + radius]
            horizontalDiff[star.row][star.col - star.radius]++;
            if (star.col + star.radius + 1 < cols) {
                horizontalDiff[star.row][star.col + star.radius + 1]--;
            }

            // Mark vertical line segment [row - radius, row + radius]
            verticalDiff[star.row - star.radius][star.col]++;
            if (star.row + star.radius + 1 < rows) {
                verticalDiff[star.row + star.radius + 1][star.col]--;
            }
        }

        char[][] reconstructed = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            Arrays.fill(reconstructed[i], '.');
        }

        // Process horizontal segments
        for (int i = 0; i < rows; i++) {
            int currentLineCount = 0;
            for (int j = 0; j < cols; j++) {
                currentLineCount += horizontalDiff[i][j];
                if (currentLineCount > 0) {
                    reconstructed[i][j] = '*';
                }
            }
        }

        // Process vertical segments
        for (int j = 0; j < cols; j++) {
            int currentLineCount = 0;
            for (int i = 0; i < rows; i++) {
                currentLineCount += verticalDiff[i][j];
                if (currentLineCount > 0) {
                    reconstructed[i][j] = '*';
                }
            }
        }

        return reconstructed;
    }

    private static boolean isMatch(char[][] original, char[][] reconstructed, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            if (!Arrays.equals(original[i], reconstructed[i])) {
                return false;
            }
        }
        return true;
    }

    /**
     * Represents a star with a center coordinate and a radius.
     */
    static class Star {
        final int row;
        final int col;
        final int radius;

        Star(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }
    }

    /**
     * Efficient input reader.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A solver to determine if a given grid of '*' and '.' characters 
 * can be perfectly reconstructed using "plus" shapes.
 */
public class PlusShapeSolver {

    /**
     * Represents a plus shape centered at (row, col) with a specific radius.
     */
    static class PlusShape {
        final int row;
        final int col;
        final int radius;

        PlusShape(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }

        @Override
        public String toString() {
            // Adding 1 to convert 0-indexed to 1-indexed for output
            return (row + 1) + " " + (col + 1) + " " + radius;
        }
    }

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            char[][] grid = new char[rows][];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            PlusShapeSolver solver = new PlusShapeSolver();
            solver.solve(grid, rows, cols, writer);

        } catch (Exception e) {
            // In a real production environment, use a proper logger
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    /**
     * Orchestrates the logic of finding shapes, reconstructing the grid, and validating.
     */
    public void solve(char[][] grid, int rows, int cols, PrintWriter writer) {
        List<PlusShape> plusShapes = findPlusShapes(grid, rows, cols);
        char[][] reconstructedGrid = reconstructGrid(plusShapes, rows, cols);

        if (isGridMatch(grid, reconstructedGrid, rows, cols)) {
            writer.println(plusShapes.size());
            for (PlusShape shape : plusShapes) {
                writer.println(shape.toString());
            }
        } else {
            writer.println("-1");
        }
    }

    /**
     * Iterates through the grid to find all possible maximal plus shapes.
     */
    private List<PlusShape> findPlusShapes(char[][] grid, int rows, int cols) {
        List<PlusShape> shapes = new ArrayList<>();

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*') {
                    int radius = calculateMaxRadius(grid, r, c, rows, cols);
                    if (radius > 0) {
                        shapes.add(new PlusShape(r, c, radius));
                    }
                }
            }
        }
        return shapes;
    }

    /**
     * Calculates the maximum radius a plus shape can have at a given center.
     */
    private int calculateMaxRadius(char[][] grid, int r, int c, int rows, int cols) {
        int radius = 0;
        int k = 1;

        while (true) {
            // Check boundaries
            if (r - k < 0 || r + k >= rows || c - k < 0 || c + k >= cols) {
                break;
            }
            // Check if all arms of the plus shape consist of '*'
            if (grid[r - k][c] == '.' || grid[r + k][c] == '.' || 
                grid[r][c - k] == '.' || grid[r][c + k] == '.') {
                break;
            }
            radius = k;
            k++;
        }
        return radius;
    }

    /**
     * Creates a new grid based on the identified plus shapes.
     */
    private char[][] reconstructGrid(List<PlusShape> shapes, int rows, int cols) {
        char[][] reconstructed = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            Arrays.fill(reconstructed[i], '.');
        }

        for (PlusShape shape : shapes) {
            int r = shape.row;
            int c = shape.col;
            reconstructed[r][c] = '*';
            for (int k = 1; k <= shape.radius; k++) {
                reconstructed[r - k][c] = '*';
                reconstructed[r + k][c] = '*';
                reconstructed[r][c - k] = '*';
                reconstructed[r][c + k] = '*';
            }
        }
        return reconstructed;
    }

    /**
     * Compares the original grid with the reconstructed grid.
     */
    private boolean isGridMatch(char[][] original, char[][] reconstructed, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (original[r][c] != reconstructed[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Efficient reader for large input datasets.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A program to identify star-shaped patterns (crosses) in a grid of stars.
 * A star is defined by a horizontal and vertical segment of stars intersecting 
 * at a center, with at least one star extending in all four cardinal directions.
 */
public class DrawingStars {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        StarSolver solver = new StarSolver(rows, cols, grid);
        solver.solve(out);
        out.flush();
        out.close();
    }

    /**
     * Represents a continuous segment of stars ('*') in a row or column.
     */
    static class Segment {
        final int start;
        final int end;
        final int fixedCoord; // Row index for horizontal, Column index for vertical

        Segment(int start, int end, int fixedCoord) {
            this.start = start;
            this.end = end;
            this.fixedCoord = fixedCoord;
        }
    }

    /**
     * Represents an event for the sweep-line algorithm.
     */
    static class SweepEvent implements Comparable<SweepEvent> {
        static final int END = 0;
        static final int START = 1;

        final int pos;
        final int type;
        final int segmentIndex;

        SweepEvent(int pos, int type, int segmentIndex) {
            this.pos = pos;
            this.type = type;
            this.segmentIndex = segmentIndex;
        }

        @Override
        public int compareTo(SweepEvent other) {
            if (this.pos != other.pos) {
                return Integer.compare(this.pos, other.pos);
            }
            return Integer.compare(this.type, other.type);
        }
    }

    /**
     * Orchestrates the identification of star patterns and validates coverage.
     */
    static class StarSolver {
        private final int rows;
        private final int cols;
        private final char[][] grid;

        private final List<Segment> horizontalLines = new ArrayList<>();
        private final List<Segment> verticalLines = new ArrayList<>();
        private final PriorityQueue<SweepEvent> eventQueue = new PriorityQueue<>();

        private final int[][] prefVert;
        private final int[][] prefHoriz;
        private final StringBuilder outputBuilder = new StringBuilder();
        private int starCount = 0;

        public StarSolver(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            this.prefVert = new int[rows + 1][cols];
            this.prefHoriz = new int[rows][cols + 1];
        }

        public void solve(PrintWriter out) {
            extractSegments();
            findStars();
            if (validateCoverage()) {
                out.println(starCount);
                out.print(outputBuilder);
            } else {
                out.println("-1");
            }
        }

        private void extractSegments() {
            // Find horizontal segments of length >= 3
            for (int i = 0; i < rows; i++) {
                int start = -1;
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '*') {
                        if (start == -1) start = j;
                    } else {
                        if (start != -1) {
                            if (j - start > 2) addHorizontalLine(i, start, j);
                            start = -1;
                        }
                    }
                }
                if (start != -1 && cols - start > 2) {
                    addHorizontalLine(i, start, cols);
                }
            }

            // Find vertical segments
            for (int j = 0; j < cols; j++) {
                int start = -1;
                for (int i = 0; i < rows; i++) {
                    if (grid[i][j] == '*') {
                        if (start == -1) start = i;
                    } else {
                        if (start != -1) {
                            if (i - start > 2) verticalLines.add(new Segment(start, i, j));
                            start = -1;
                        }
                    }
                }
                if (start != -1) verticalLines.add(new Segment(start, rows, j));
            }

            // Sort vertical lines by column, then by starting row
            Collections.sort(verticalLines, (a, b) -> {
                if (a.fixedCoord != b.fixedCoord) return Integer.compare(a.fixedCoord, b.fixedCoord);
                return Integer.compare(a.start, b.start);
            });
        }

        private void addHorizontalLine(int row, int start, int end) {
            int idx = horizontalLines.size();
            horizontalLines.add(new Segment(start, end, row));
            eventQueue.offer(new SweepEvent(start, SweepEvent.START, idx));
            eventQueue.offer(new SweepEvent(end, SweepEvent.END, idx));
        }

        private void findStars() {
            Segment[] activeAtRow = new Segment[rows];

            for (Segment vLine : verticalLines) {
                int col = vLine.fixedCoord;

                // Process events up to the current column
                while (!eventQueue.isEmpty() && eventQueue.peek().pos <= col) {
                    SweepEvent event = eventQueue.poll();
                    Segment hLine = horizontalLines.get(event.segmentIndex);
                    if (event.type == SweepEvent.END) {
                        activeAtRow[hLine.fixedCoord] = null;
                    } else {
                        activeAtRow[hLine.fixedCoord] = hLine;
                    }
                }

                // Check every cell along the vertical line for an intersection
                for (int r = vLine.start; r < vLine.end; r++) {
                    Segment hLine = activeAtRow[r];
                    if (hLine == null) continue;

                    int vDist = Math.min(vLine.end - r - 1, r - vLine.start);
                    int hDist = Math.min(hLine.end - col - 1, col - hLine.start);
                    int radius = Math.min(vDist, hDist);

                    if (radius > 0) {
                        starCount++;
                        outputBuilder.append(r + 1).append(" ").append(col + 1).append(" ").append(radius).append("\n");

                        // Mark coverage using 1D difference arrays applied per row/column
                        prefVert[r - radius][col]++;
                        prefVert[r + radius + 1][col]--;
                        prefHoriz[r][col - radius]++;
                        prefHoriz[r][col + radius + 1]--;
                    }
                }
            }
        }

        private boolean validateCoverage() {
            int[][] horizontalCoverage = new int[rows][cols];
            int[][] verticalCoverage = new int[cols][rows];

            // Compute prefix sums for horizontal arms
            for (int i = 0; i < rows; i++) {
                int current = 0;
                for (int j = 0; j < cols; j++) {
                    current += prefHoriz[i][j];
                    horizontalCoverage[i][j] = current;
                }
            }

            // Compute prefix sums for vertical arms
            for (int j = 0; j < cols; j++) {
                int current = 0;
                for (int i = 0; i < rows; i++) {
                    current += prefVert[i][j];
                    verticalCoverage[j][i] = current;
                }
            }

            // Check if every '*' cell is part of at least one star arm
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '*') {
                        boolean covered = (horizontalCoverage[i][j] > 0 || verticalCoverage[j][i] > 0);
                        if (!covered) return false;
                    }
                }
            }
            return true;
        }
    }

    /**
     * Utility for high-performance input reading.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * StarGridSolver solves the problem of identifying a set of "star" shapes
 * that perfectly reconstruct a given grid of '*' and '.' characters.
 * A star consists of a center '*' and four arms of equal length 'k'.
 */
public class StarGridSolver {

    private static class Star {
        final int row;
        final int col;
        final int armLength;

        Star(int row, int col, int armLength) {
            this.row = row;
            this.col = col;
            this.armLength = armLength;
        }
    }

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int[][] rowPrefixSums;
    private final int[][] colPrefixSums;

    public StarGridSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.rowPrefixSums = new int[rows][cols];
        this.colPrefixSums = new int[cols][rows];
        precomputePrefixSums();
    }

    /**
     * Precomputes prefix sums for rows and columns to allow O(1) checks
     * for continuous segments of stars.
     */
    private void precomputePrefixSums() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*') {
                    rowPrefixSums[i][j] = 1;
                    colPrefixSums[j][i] = 1;
                }
            }
        }

        for (int i = 0; i < rows; i++) {
            for (int j = 1; j < cols; j++) {
                rowPrefixSums[i][j] += rowPrefixSums[i][j - 1];
            }
        }

        for (int j = 0; j < cols; j++) {
            for (int i = 1; i < rows; i++) {
                colPrefixSums[j][i] += colPrefixSums[j][i - 1];
            }
        }
    }

    /**
     * Finds all maximal stars in the grid.
     */
    public List<Star> findStars() {
        List<Star> stars = new ArrayList<>();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*') {
                    int maxArm = findMaxArmLength(i, j);
                    if (maxArm > 0) {
                        stars.add(new Star(i, j, maxArm));
                    }
                }
            }
        }
        return stars;
    }

    /**
     * Uses binary search to find the largest arm length k for a star at (r, c).
     */
    private int findMaxArmLength(int r, int c) {
        int low = 0;
        int high = Math.min(Math.min(r, rows - 1 - r), Math.min(c, cols - 1 - c));
        int result = 0;

        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (mid == 0) {
                low = mid + 1;
                continue;
            }
            if (isContinuousStar(r, c, mid)) {
                result = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return result;
    }

    /**
     * Checks if a star with arm length k centered at (r, c) consists entirely of stars.
     */
    private boolean isContinuousStar(int r, int c, int k) {
        // Boundary check implicitly handled by high limit in findMaxArmLength, 
        // but we check explicit endpoints for safety.
        if (r - k < 0 || r + k >= rows || c - k < 0 || c + k >= cols) return false;

        // Check row segment [c-k, c+k]
        int rowSum = rowPrefixSums[r][c + k];
        if (c - k > 0) rowSum -= rowPrefixSums[r][c - k - 1];
        if (rowSum != (2 * k + 1)) return false;

        // Check column segment [r-k, r+k]
        int colSum = colPrefixSums[c][r + k];
        if (r - k > 0) colSum -= colPrefixSums[c][r - k - 1];
        if (colSum != (2 * k + 1)) return false;

        return true;
    }

    /**
     * Validates if the found stars reconstruct the original grid exactly.
     */
    public boolean isValid(List<Star> stars) {
        char[][] reconstructed = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            Arrays.fill(reconstructed[i], '.');
        }

        for (Star star : stars) {
            // Fill horizontal arm
            for (int j = star.col - star.armLength; j <= star.col + star.armLength; j++) {
                reconstructed[star.row][j] = '*';
            }
            // Fill vertical arm
            for (int i = star.row - star.armLength; i <= star.row + star.armLength; i++) {
                reconstructed[i][star.col] = '*';
            }
        }

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] != reconstructed[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    public static void main(String[] args) throws IOException {
        FastReader sc = new FastReader(System.in);
