import java.io.*;
import java.util.*;

/**
 * A refactored solution for the Star Drawing problem.
 * This program identifies the maximum number of "stars" (cross-shaped patterns)
 * that can be placed on a grid such that they perfectly match a target pattern.
 */
public class Main {

    public static void main(String[] args) {
        // Using try-with-resources for automatic resource management
        try (InputStream inputStream = System.in;
             PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)))) {

            FastReader reader = new FastReader(inputStream);
            StarPatternSolver solver = new StarPatternSolver();
            solver.solve(reader, out);

        } catch (Exception e) {
            // In a production environment, use a proper logging framework.
            e.printStackTrace();
        }
    }

    /**
     * Encapsulates the logic for solving the Star Drawing problem.
     */
    static class StarPatternSolver {
        private int rows;
        private int cols;
        private char[][] targetGrid;
        private char[][] coverageGrid;

        /**
         * Represents a single star placed on the grid.
         */
        private static class Star {
            final int row;
            final int col;
            final int radius;

            Star(int row, int col, int radius) {
                this.row = row;
                this.col = col;
                this.radius = radius;
            }

            @Override
            public String toString() {
                return row + " " + col + " " + radius;
            }
        }

        /**
         * Executes the core algorithm.
         * 
         * @param in Fast reader for input
         * @param out PrintWriter for output
         */
        public void solve(FastReader in, PrintWriter out) {
            String line1 = in.next();
            if (line1 == null) return;

            rows = Integer.parseInt(line1);
            cols = in.nextInt();

            targetGrid = new char[rows][cols];
            coverageGrid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                String rowStr = in.next();
                targetGrid[i] = rowStr.toCharArray();
                // Initialize coverage grid with '.'
                Arrays.fill(coverageGrid[i], '.');
            }

            List<Star> placedStars = new ArrayList<>();

            // Iterate through every cell to find the largest possible star that can be centered there
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    int maxRadius = findMaxStarRadius(i, j);

                    if (maxRadius > 0) {
                        placedStars.add(new Star(i + 1, j + 1, maxRadius));
                        applyStarToCoverage(i, j, maxRadius);
                    }
                }
            }

            // Validate if the generated coverage exactly matches the target grid
            if (isCoverageValid()) {
                out.println(placedStars.size());
                for (Star star : placedStars) {
                    out.println(star);
                }
            } else {
                // If the pattern cannot be perfectly reconstructed, output -1
                out.println(-1);
            }
        }

        /**
         * Finds the maximum radius k >= 1 such that a star centered at (r, c)
         * only covers cells that are '*' in the target grid.
         */
        private int findMaxStarRadius(int r, int c) {
            if (targetGrid[r][c] != '*') {
                return 0;
            }

            int bestK = 0;
            // We check radii up to 100 as per the original specification, 
            // constrained by the grid boundaries.
            int limit = Math.min(100, Math.max(rows, cols));

            for (int k = 1; k <= limit; k++) {
                if (canPlaceStar(r, c, k)) {
                    bestK = k;
                } else {
                    // Since we are looking for consecutive radii, we can break early
                    break;
                }
            }
            return bestK;
        }

        /**
         * Checks if a star of radius k centered at (r, c) fits within bounds
         * and only covers '*' cells.
         */
        private boolean canPlaceStar(int r, int c, int k) {
            // Check boundary constraints
            if (r - k < 0 || r + k >= rows || c - k < 0 || c + k >= cols) {
                return false;
            }

            // Check vertical arm
            for (int i = r - k; i <= r + k; i++) {
                if (targetGrid[i][c] != '*') return false;
            }

            // Check horizontal arm
            for (int j = c - k; j <= c + k; j++) {
                if (targetGrid[r][j] != '*') return false;
            }

            return true;
        }

        /**
         * Marks the cells covered by a star in the coverage grid.
         */
        private void applyStarToCoverage(int r, int c, int k) {
            coverageGrid[r][c] = '*';
            // Vertical arm
            for (int i = r - k; i <= r + k; i++) {
                coverageGrid[i][c] = '*';
            }
            // Horizontal arm
            for (int j = c - k; j <= c + k; j++) {
                coverageGrid[r][j] = '*';
            }
        }

        /**
         * Compares the coverage grid with the target grid to ensure they are identical.
         */
        private boolean isCoverageValid() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (targetGrid[i][j] != coverageGrid[i][j]) {
                        return false;
                    }
                }
            }
            return true;
        }
    }

    /**
     * A high-performance reader for parsing input.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            return next != null ? Integer.parseInt(next) : 0;
        }
    }
}

import java.io.*;
import java.util.*;

public class Solution {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int rows = reader.nextInt();
        int cols = reader.nextInt();
        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            grid[i] = reader.next().toCharArray();
        }

        GridSolver solver = new GridSolver(rows, cols, grid);
        solver.solve(out);

        out.flush();
        out.close();
    }

    static class Star {
        int r, c, radius;

        Star(int r, int c, int radius) {
            this.r = r;
            this.c = c;
            this.radius = radius;
        }

        @Override
        public String toString() {
            return (r + 1) + " " + (c + 1) + " " + radius;
        }
    }

    static class GridSolver {
        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final boolean[][] visited;
        private final List<Star> stars = new ArrayList<>();

        public GridSolver(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            this.visited = new boolean[rows][cols];
        }

        public void solve(PrintWriter out) {
            int[][] distUp = computeDistances(0);
            int[][] distDown = computeDistances(1);
            int[][] distLeft = computeDistances(2);
            int[][] distRight = computeDistances(3);

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '*') {
                        int radius = Math.min(Math.min(distUp[r][c], distDown[r][c]), 
                                              Math.min(distLeft[r][c], distRight[r][c]));
                        if (radius > 0) {
                            addStar(r, c, radius);
                        }
                    }
                }
            }

            if (isAllCovered()) {
                out.println(stars.size());
                for (Star s : stars) {
                    out.println(s.toString());
                }
            } else {
                out.println("-1");
            }
        }

        private int[][] computeDistances(int direction) {
            int[][] dist = new int[rows][cols];
            switch (direction) {
                case 0: // Up
                    for (int c = 0; c < cols; c++) {
                        for (int r = 1; r < rows; r++) {
                            if (grid[r][c] == '*' && grid[r - 1][c] == '*') 
                                dist[r][c] = dist[r - 1][c] + 1;
                        }
                    }
                    break;
                case 1: // Down
                    for (int c = 0; c < cols; c++) {
                        for (int r = rows - 2; r >= 0; r--) {
                            if (grid[r][c] == '*' && grid[r + 1][c] == '*') 
                                dist[r][c] = dist[r + 1][c] + 1;
                        }
                    }
                    break;
                case 2: // Left
                    for (int r = 0; r < rows; r++) {
                        for (int c = 1; c < cols; c++) {
                            if (grid[r][c] == '*' && grid[r][c - 1] == '*') 
                                dist[r][c] = dist[r][c - 1] + 1;
                        }
                    }
                    break;
                case 3: // Right
                    for (int r = 0; r < rows; r++) {
                        for (int c = cols - 2; c >= 0; c--) {
                            if (grid[r][c] == '*' && grid[r][c + 1] == '*') 
                                dist[r][c] = dist[r][c + 1] + 1;
                        }
                    }
                    break;
            }
            return dist;
        }

        private void addStar(int r, int c, int radius) {
            stars.add(new Star(r, c, radius));
            visited[r][c] = true;
            for (int k = 1; k <= radius; k++) {
                visited[r + k][c] = true;
                visited[r - k][c] = true;
                visited[r][c + k] = true;
                visited[r][c - k] = true;
            }
        }

        private boolean isAllCovered() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '*' && !visited[r][c]) return false;
                }
            }
            return true;
        }
    }

    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A solver that identifies the largest possible crosses centered at '*' cells
 * and verifies if all '*' cells in a grid are covered by at least one cross.
 */
public class CrossCoverageSolver {

    /**
     * Represents a cross shape centered at (row, col) with a given size.
     */
    static class Cross {
        final int row;
        final int col;
        final int size;

        public Cross(int row, int col, int size) {
            this.row = row;
            this.col = col;
            this.size = size;
        }

        @Override
        public String toString() {
            return row + " " + col + " " + size;
        }
    }

    /**
     * Efficient input reader for large datasets.
     */
    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) {
        InputReader input = new InputReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            String rStr = input.next();
            if (rStr == null) return;

            int rows = Integer.parseInt(rStr);
            int cols = input.nextInt();
            char[][] grid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                String rowString = input.next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = rowString.charAt(j);
                }
            }

            solve(rows, cols, grid, out);
        } catch (Exception e) {
            // Handle or log exception as per requirements
        } finally {
            out.flush();
            out.close();
        }
    }

    private static void solve(int rows, int cols, char[][] grid, PrintWriter out) {
        // isStarCovered tracks if a '*' cell is part of at least one cross.
        // Based on the original logic, we only care if all '*' cells are covered.
        boolean[][] isStarCovered = new boolean[rows][cols];
        List<Cross> foundCrosses = new ArrayList<>();

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*') {
                    int maxPossibleK = calculateMaxPossibleK(i, j, rows, cols);
                    int bestK = findLargestCrossAt(i, j, maxPossibleK, grid, isStarCovered);

                    if (bestK > 0) {
                        foundCrosses.add(new Cross(i + 1, j + 1, bestK));
                    }
                }
            }
        }

        if (allStarsCovered(rows, cols, grid, isStarCovered)) {
            out.println(foundCrosses.size());
            for (Cross cross : foundCrosses) {
                out.println(cross);
            }
        } else {
            out.println("-1");
        }
    }

    /**
     * Calculates the distance to the nearest boundary to prevent ArrayOutOfBounds.
     */
    private static int calculateMaxPossibleK(int r, int c, int rows, int cols) {
        return Math.min(Math.min(r, rows - 1 - r), Math.min(c, cols - 1 - c));
    }

    /**
     * Finds the largest k for a cross at (r, c) and marks the cells as covered.
     * @return the largest k found, or 0 if no cross of size >= 1 is possible.
     */
    private static int findLargestCrossAt(int r, int c, int maxK, char[][] grid, boolean[][] isStarCovered) {
        int bestK = 0;
        for (int k = 1; k <= maxK; k++) {
            if (isCrossValid(r, c, k, grid)) {
                // Mark center and the four arms of the current k-size cross as covered
                isStarCovered[r][c] = true;
                isStarCovered[r + k][c] = true;
                isStarCovered[r - k][c] = true;
                isStarCovered[r][c + k] = true;
                isStarCovered[r][c - k] = true;
                bestK = k;
            } else {
                break;
            }
        }
        return bestK;
    }

    private static boolean isCrossValid(int r, int c, int k, char[][] grid) {
        return grid[r + k][c] == '*' &&
               grid[r - k][c] == '*' &&
               grid[r][c + k] == '*' &&
               grid[r][c - k] == '*';
    }

    /**
     * Checks if every '*' cell in the grid has been marked as covered.
     */
    private static boolean allStarsCovered(int rows, int cols, char[][] grid, boolean[][] isStarCovered) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*' && !isStarCovered[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves the problem of covering all '#' cells in a grid using 
 * cross-shaped patterns with a uniform radius.
 */
public class GridCoverageSolver {

    private static final int EMPTY = 0;
    private static final int FILLED = 1;

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int rowCount = reader.nextInt();
            int colCount = reader.nextInt();

            int[][] grid = new int[rowCount][colCount];
            for (int i = 0; i < rowCount; i++) {
                String line = reader.next();
                for (int j = 0; j < colCount; j++) {
                    grid[i][j] = (line.charAt(j) == '.') ? EMPTY : FILLED;
                }
            }

            solve(rowCount, colCount, grid, out);
        } catch (Exception e) {
            // In a production environment, use a proper logger
            e.printStackTrace();
        } finally {
            out.close();
        }
    }

    private static void solve(int rows, int cols, int[][] grid, PrintWriter out) {
        List<CrossPattern> patterns = new ArrayList<>();
        boolean[][] isCovered = new boolean[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == FILLED) {
                    int radius = calculateMinRadius(i, j, grid);

                    // Only consider cells that can form a cross with radius > 0
                    if (radius > 0) {
                        patterns.add(new CrossPattern(i + 1, j + 1, radius));
                        markCrossArea(isCovered, i, j, radius);
                    }
                }
            }
        }

        if (isAllFilledCellsCovered(grid, isCovered)) {
            out.println(patterns.size());
            for (CrossPattern p : patterns) {
                out.println(p.row + " " + p.col + " " + p.radius);
            }
        } else {
            out.println("-1");
        }
    }

    /**
     * Calculates the maximum possible uniform radius for a cross centered at (r, c).
     */
    private static int calculateMinRadius(int r, int c, int[][] grid) {
        int up = getDistance(r, c, -1, 0, grid);
        int down = getDistance(r, c, 1, 0, grid);
        int left = getDistance(r, c, 0, -1, grid);
        int right = getDistance(r, c, 0, 1, grid);

        return Math.min(Math.min(up, down), Math.min(left, right));
    }

    /**
     * Counts how many consecutive FILLED cells exist in a specific direction.
     * Returns (count - 1) to represent the radius.
     */
    private static int getDistance(int r, int c, int dr, int dc, int[][] grid) {
        int count = 0;
        int currR = r;
        int currC = c;

        while (currR >= 0 && currR < grid.length && 
               currC >= 0 && currC < grid[0].length && 
               grid[currR][currC] == FILLED) {
            count++;
            currR += dr;
            currC += dc;
        }
        return count - 1;
    }

    /**
     * Marks the cells covered by the cross pattern as true in the isCovered array.
     */
    private static void markCrossArea(boolean[][] isCovered, int r, int c, int radius) {
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        // Mark the center
        isCovered[r][c] = true;

        // Mark the arms
        for (int i = 0; i < 4; i++) {
            for (int step = 1; step <= radius; step++) {
                int targetR = r + (dr[i] * step);
                int targetC = c + (dc[i] * step);
                if (targetR >= 0 && targetR < isCovered.length && 
                    targetC >= 0 && targetC < isCovered[0].length) {
                    isCovered[targetR][targetC] = true;
                }
            }
        }
    }

    private static boolean isAllFilledCellsCovered(int[][] grid, boolean[][] isCovered) {
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[0].length; j++) {
                if (grid[i][j] == FILLED && !isCovered[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Represents a selected cross center and its radius.
     */
    static class CrossPattern {
        final int row;
        final int col;
        final int radius;

        CrossPattern(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }
    }

    /**
     * Optimized utility for reading input.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A solver for the grid-based cross-covering problem.
 * The goal is to identify crosses (a center cell with arms of equal length)
 * that cover all '*' cells in a grid.
 */
public class CrossCoverSolver {

    /**
     * Represents a single cross found in the grid.
     */
    private static class Cross {
        final int row;
        final int col;
        final int armLength;

        Cross(int row, int col, int armLength) {
            this.row = row;
            this.col = col;
            this.armLength = armLength;
        }

        @Override
        public String toString() {
            return row + " " + col + " " + armLength;
        }
    }

    /**
     * Main logic to solve the problem.
     */
    public void solve() throws IOException {
        FastReader sc = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int rows = sc.nextInt();
        int cols = sc.nextInt();

        int[][] grid = new int[rows][cols];
        boolean hasStars = false;

        // Read input and initialize the grid
        for (int i = 0; i < rows; i++) {
            String line = sc.next();
            for (int j = 0; j < cols; j++) {
                if (line.charAt(j) == '*') {
                    grid[i][j] = 1;
                    hasStars = true;
                }
            }
        }

        // Edge case: If no stars exist, 0 crosses are needed
        if (!hasStars) {
            out.println("0");
            out.close();
            return;
        }

        // Precompute the number of consecutive stars in all 4 directions for every cell
        int[][] leftArms = new int[rows][cols];
        int[][] rightArms = new int[rows][cols];
        int[][] upArms = new int[rows][cols];
        int[][] downArms = new int[rows][cols];

        precomputeArms(grid, rows, cols, leftArms, rightArms, upArms, downArms);

        List<Cross> crosses = new ArrayList<>();

        // Greedy approach: Traverse the grid and find the largest possible crosses
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                // Only attempt to form a cross if the current cell is a star
                if (grid[i][j] == 1) {
                    int maxReach = Math.min(
                        Math.min(leftArms[i][j], rightArms[i][j]),
                        Math.min(upArms[i][j], downArms[i][j])
                    );

                    // A cross must have an arm length of at least 1 (total reach >= 2)
                    if (maxReach > 1) {
                        int armLen = maxReach - 1;
                        crosses.add(new Cross(i + 1, j + 1, armLen));

                        // Mark the cells covered by this cross as 0
                        markCellsAsCovered(grid, i, j, armLen);
                    }
                }
            }
        }

        // Verify if all stars have been covered
        if (isGridEmpty(grid) && !crosses.isEmpty()) {
            out.println(crosses.size());
            for (Cross cross : crosses) {
                out.println(cross.toString());
            }
        } else {
            // If some stars remain or no crosses were found
            out.println("-1");
        }

        out.close();
    }

    private void precomputeArms(int[][] grid, int rows, int cols, 
                                int[][] left, int[][] right, 
                                int[][] up, int[][] down) {
        for (int i = 0; i < rows; i++) {
            // Left-to-right pass
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 1) {
                    left[i][j] = (j == 0) ? 1 : left[i][j - 1] + 1;
                }
            }
            // Right-to-left pass
            for (int j = cols - 1; j >= 0; j--) {
                if (grid[i][j] == 1) {
                    right[i][j] = (j == cols - 1) ? 1 : right[i][j + 1] + 1;
                }
            }
        }

        for (int j = 0; j < cols; j++) {
            // Top-to-bottom pass
            for (int i = 0; i < rows; i++) {
                if (grid[i][j] == 1) {
                    up[i][j] = (i == 0) ? 1 : up[i - 1][j] + 1;
                }
            }
            // Bottom-to-top pass
            for (int i = rows - 1; i >= 0; i--) {
                if (grid[i][j] == 1) {
                    down[i][j] = (i == rows - 1) ? 1 : down[i + 1][j] + 1;
                }
            }
        }
    }

    private void markCellsAsCovered(int[][] grid, int row, int col, int armLen) {
        // Clear vertical arm
        for (int i = row - armLen; i <= row + armLen; i++) {
            grid[i][col] = 0;
        }
        // Clear horizontal arm
        for (int j = col - armLen; j <= col + armLen; j++) {
            grid[row][j] = 0;
        }
    }

    private boolean isGridEmpty(int[][] grid) {
        for (int[] row : grid) {
            for (int cell : row) {
                if (cell == 1) return false;
            }
        }
        return true;
    }

    public static void main(String[] args) throws IOException {
        new CrossCoverSolver().solve();
    }

    /**
     * Optimized reader for fast input processing.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

/**
 * Solution for finding the maximum squares of '*' characters in a grid 
 * and ensuring all '*' characters are covered by the spines of these squares.
 */
public class Solution {

    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        try {
            int rowCount = sc.nextInt();
            int colCount = sc.nextInt();

            char[][] grid = new char[rowCount][colCount];
            for (int i = 0; i < rowCount; i++) {
                grid[i] = sc.next().toCharArray();
            }

            GridSolver solver = new GridSolver(rowCount, colCount, grid);
            solver.solve(out);

        } catch (Exception e) {
            // In a production environment, use a proper logging framework
            e.printStackTrace();
        } finally {
            out.close();
        }
    }

    /**
     * Represents a detected square in the grid.
     */
    static class Square {
        final int row;
        final int col;
        final int radius;

        Square(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }

        @Override
        public String toString() {
            // Converting 0-indexed to 1-indexed for output requirements
            return (row + 1) + " " + (col + 1) + " " + radius;
        }
    }

    /**
     * Handles the logic of processing the grid.
     */
    static class GridSolver {
        private final int rows;
        private final int cols;
        private final char[][] grid;

        private final int[][] verticalCoverage;
        private final int[][] horizontalCoverage;

        public GridSolver(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            this.verticalCoverage = new int[rows][cols];
            this.horizontalCoverage = new int[rows][cols];
        }

        public void solve(PrintWriter out) {
            int[][] up = new int[rows][cols];
            int[][] down = new int[rows][cols];
            int[][] left = new int[rows][cols];
            int[][] right = new int[rows][cols];

            calculateDistances(up, down, left, right);

            List<Square> detectedSquares = new ArrayList<>();

            // Identify the largest possible square centered at each '*'
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '*') {
                        int maxRadius = Math.min(Math.min(up[i][j], down[i][j]), 
                                                 Math.min(left[i][j], right[i][j])) - 1;
                        if (maxRadius > 0) {
                            applySquareSpineCoverage(i, j, maxRadius);
                            detectedSquares.add(new Square(i, j, maxRadius));
                        }
                    }
                }
            }

            // Compute prefix sums to resolve the 1D difference arrays
            computePrefixSums();

            // Verify if all '*' are covered by at least one square spine
            if (isEveryStarCovered()) {
                out.println(detectedSquares.size());
                for (Square sq : detectedSquares) {
                    out.println(sq.toString());
                }
            } else {
                out.println("-1");
            }
        }

        private void calculateDistances(int[][] up, int[][] down, int[][] left, int[][] right) {
            // Top-Left to Bottom-Right pass
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '*') {
                        up[i][j] = (i > 0) ? up[i - 1][j] + 1 : 1;
                        left[i][j] = (j > 0) ? left[i][j - 1] + 1 : 1;
                    }
                }
            }

            // Bottom-Right to Top-Left pass
            for (int i = rows - 1; i >= 0; i--) {
                for (int j = cols - 1; j >= 0; j--) {
                    if (grid[i][j] == '*') {
                        down[i][j] = (i < rows - 1) ? down[i + 1][j] + 1 : 1;
                        right[i][j] = (j < cols - 1) ? right[i][j + 1] + 1 : 1;
                    }
                }
            }
        }

        private void applySquareSpineCoverage(int r, int c, int radius) {
            // Vertical spine coverage (Column-wise difference array)
            verticalCoverage[r - radius][c]++;
            if (r + radius + 1 < rows) {
                verticalCoverage[r + radius + 1][c]--;
            }

            // Horizontal spine coverage (Row-wise difference array)
            horizontalCoverage[r][c - radius]++;
            if (c + radius + 1 < cols) {
                horizontalCoverage[r][c + radius + 1]--;
            }
        }

        private void computePrefixSums() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (i > 0) verticalCoverage[i][j] += verticalCoverage[i - 1][j];
                    if (j > 0) horizontalCoverage[i][j] += horizontalCoverage[i][j - 1];
                }
            }
        }

        private boolean isEveryStarCovered() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '*') {
                        // A star is covered if it lies on any vertical or horizontal spine
                        if (verticalCoverage[i][j] == 0 && horizontalCoverage[i][j] == 0) {
                            return false;
                        }
                    }
                }
            }
            return true;
        }
    }

    /**
     * Fast I/O utility for efficient input reading.
     */
    static class FastScanner {
        private final BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        private StringTokenizer st = new StringTokenizer("");

        public String next() {
            while (!st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solution to the Star Coverage problem.
 * The goal is to find the maximum possible star radii such that all '*' cells 
 * are covered by the arms of the stars.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            boolean[][] grid = new boolean[rows][cols];
            for (int i = 0; i < rows; i++) {
                String rowString = reader.next();
                for (int j = 0; j < cols; j++) {
                    if (rowString.charAt(j) == '*') {
                        grid[i][j] = true;
                    }
                }
            }

            GridSolver solver = new GridSolver(rows, cols, grid);
            GridSolver.Result result = solver.solve();

            if (!result.isPossible()) {
                out.println("-1");
            } else {
                out.println(result.getStars().size());
                for (Star star : result.getStars()) {
                    out.println(star.row() + " " + star.col() + " " + star.radius());
                }
            }
        } catch (Exception e) {
            // In a production environment, use a logger.
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Represents a star located at (row, col) with a given arm radius.
     */
    record Star(int row, int col, int radius) {}

    /**
     * Handles the logic for calculating stars and verifying grid coverage.
     */
    static class GridSolver {
        private final int rows;
        private final int cols;
        private final boolean[][] isStarCell;

        public GridSolver(int rows, int cols, boolean[][] isStarCell) {
            this.rows = rows;
            this.cols = cols;
            this.isStarCell = isStarCell;
        }

        public Result solve() {
            int[][] top = new int[rows][cols];
            int[][] left = new int[rows][cols];
            int[][] bottom = new int[rows][cols];
            int[][] right = new int[rows][cols];

            // Step 1: Compute continuous star cell counts in 4 directions (DP)
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (isStarCell[i][j]) {
                        top[i][j] = (i == 0) ? 1 : top[i - 1][j] + 1;
                        left[i][j] = (j == 0) ? 1 : left[i][j - 1] + 1;
                    }
                }
            }

            for (int i = rows - 1; i >= 0; i--) {
                for (int j = cols - 1; j >= 0; j--) {
                    if (isStarCell[i][j]) {
                        bottom[i][j] = (i == rows - 1) ? 1 : bottom[i + 1][j] + 1;
                        right[i][j] = (j == cols - 1) ? 1 : right[i][j + 1] + 1;
                    }
                }
            }

            // Step 2: Identify maximal stars
            int[][] starRadii = new int[rows][cols];
            List<Star> starList = new ArrayList<>();

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (isStarCell[i][j]) {
                        int minArm = Math.min(Math.min(top[i][j], bottom[i][j]), 
                                              Math.min(left[i][j], right[i][j]));
                        int radius = minArm - 1;
                        if (radius > 0) {
                            starRadii[i][j] = radius;
                            // Convert to 1-based indexing for output
                            starList.add(new Star(i + 1, j + 1, radius));
                        }
                    }
                }
            }

            // Step 3: Verify if all '*' cells are covered
            boolean[][] covered = new boolean[rows][cols];
            applyCoverage(starRadii, covered);

            boolean allCovered = true;
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (isStarCell[i][j] && !covered[i][j]) {
                        allCovered = false;
                        break;
                    }
                }
                if (!allCovered) break;
            }

            return new Result(allCovered, starList);
        }

        /**
         * Simulates the coverage of stars across the grid using a sweep-line approach.
         */
        private void applyCoverage(int[][] starRadii, boolean[][] covered) {
            // Horizontal coverage (Rows)
            for (int r = 0; r < rows; r++) {
                // Left to Right
                int coverageRemaining = 0;
                for (int c = 0; c < cols; c++) {
                    if (starRadii[r][c] > 0) {
                        coverageRemaining = Math.max(coverageRemaining, starRadii[r][c]);
                        covered[r][c] = true;
                    } else if (coverageRemaining > 0) {
                        covered[r][c] = true;
                        coverageRemaining--;
                    }
                }
                // Right to Left
                coverageRemaining = 0;
                for (int c = cols - 1; c >= 0; c--) {
                    if (starRadii[r][c] > 0) {
                        coverageRemaining = Math.max(coverageRemaining, starRadii[r][c]);
                        covered[r][c] = true;
                    } else if (coverageRemaining > 0) {
                        covered[r][c] = true;
                        coverageRemaining--;
                    }
                }
            }

            // Vertical coverage (Columns)
            for (int c = 0; c < cols; c++) {
                // Top to Bottom
                int coverageRemaining = 0;
                for (int r = 0; r < rows; r++) {
                    if (starRadii[r][c] > 0) {
                        coverageRemaining = Math.max(coverageRemaining, starRadii[r][c]);
                        covered[r][c] = true;
                    } else if (coverageRemaining > 0) {
                        covered[r][c] = true;
                        coverageRemaining--;
                    }
                }
                // Bottom to Top
                coverageRemaining = 0;
                for (int r = rows - 1; r >= 0; r--) {
                    if (starRadii[r][c] > 0) {
                        coverageRemaining = Math.max(coverageRemaining, starRadii[r][c]);
                        covered[r][c] = true;
                    } else if (coverageRemaining > 0) {
                        covered[r][c] = true;
                        coverageRemaining--;
                    }
                }
            }
        }

        /**
         * Result container for the solver.
         */
        static class Result {
            private final boolean possible;
            private final List<Star> stars;

            public Result(boolean possible, List<Star> stars) {
                this.possible = possible;
                this.stars = stars;
            }

            public boolean isPossible() { return possible; }
            public List<Star> getStars() { return stars; }
        }
    }

    /**
     * Fast I/O utility.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

