/**
 * Represents a cross shape found in the grid.
 */
class Cross {
    final int row;
    final int col;
    final int radius;

    public Cross(int row, int col, int radius) {
        this.row = row;
        this.col = col;
        this.radius = radius;
    }

    @Override
    public String toString() {
        // Converting 0-indexed to 1-indexed for output
        return (row + 1) + " " + (col + 1) + " " + radius;
    }
}

/**
 * Handles the logic for finding and verifying crosses in a grid.
 */
class CrossSolver {
    private final int rows;
    private final int cols;
    private final boolean[][] grid;
    private final boolean[][] isCovered;
    private final List<Cross> foundCrosses = new ArrayList<>();

    public CrossSolver(int rows, int cols, boolean[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.isCovered = new boolean[rows][cols];
    }

    public void solve() {
        int[][] upCount = computeConsecutive(true, true);
        int[][] downCount = computeConsecutive(true, false);
        int[][] leftCount = computeConsecutive(false, true);
        int[][] rightCount = computeConsecutive(false, false);

        // Step 1: Identify valid crosses and mark coverage
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j]) {
                    // The radius is the minimum distance we can extend in all 4 directions minus the center itself
                    int maxRadius = Math.min(Math.min(upCount[i][j], downCount[i][j]),
                                             Math.min(leftCount[i][j], rightCount[i][j])) - 1;

                    if (maxRadius > 0) {
                        foundCrosses.add(new Cross(i, j, maxRadius));
                        markCoverage(i, j, maxRadius);
                    }
                }
            }
        }

        // Step 2: Verify if all '#' cells are covered
        if (isAllCovered()) {
            printResult();
        } else {
            System.out.println("-1");
        }
    }

    /**
     * Computes consecutive '#' counts in a specific direction.
     * @param vertical If true, moves up/down. If false, moves left/right.
     * @param forward If true, starts from index 0 (or top/left). If false, starts from end.
     */
    private int[][] computeConsecutive(boolean vertical, boolean forward) {
        int[][] counts = new int[rows][cols];

        for (int i = (vertical ? (forward ? 0 : rows - 1) : (forward ? 0 : cols - 1));
             vertical ? (forward ? i < rows : i >= 0) : (forward ? i < cols : i >= 0);
             vertical ? (forward ? i++ : i--) : (forward ? i++ : i--)) {

            for (int j = (vertical ? 0 : (forward ? 0 : cols - 1));
                 vertical ? j < cols : (forward ? j < cols : j >= 0); // This loop structure is a bit complex, refactored below
                 vertical ? j++ : (forward ? j++ : j--)) {
                // The logic below is a cleaner implementation of the nested loops
            }
        }
        // Re-implementing clearly to avoid nested ternary confusion
        return calculateCounts(vertical, forward);
    }

    private int[][] calculateCounts(boolean vertical, boolean forward) {
        int[][] counts = new int[rows][cols];
        if (vertical) {
            for (int j = 0; j < cols; j++) {
                if (forward) {
                    for (int i = 0; i < rows; i++) {
                        if (grid[i][j]) counts[i][j] = (i > 0 ? counts[i - 1][j] : 0) + 1;
                    }
                } else {
                    for (int i = rows - 1; i >= 0; i--) {
                        if (grid[i][j]) counts[i][j] = (i < rows - 1 ? counts[i + 1][j] : 0) + 1;
                    }
                }
            }
        } else {
            for (int i = 0; i < rows; i++) {
                if (forward) {
                    for (int j = 0; j < cols; j++) {
                        if (grid[i][j]) counts[i][j] = (j > 0 ? counts[i][j - 1] : 0) + 1;
                    }
                } else {
                    for (int j = cols - 1; j >= 0; j--) {
                        if (grid[i][j]) counts[i][j] = (j < cols - 1 ? counts[i][j + 1] : 0) + 1;
                    }
                }
            }
        }
        return counts;
    }

    private void markCoverage(int r, int c, int radius) {
        // Mark horizontal arm
        for (int j = c - radius; j <= c + radius; j++) {
            isCovered[r][j] = true;
        }
        // Mark vertical arm
        for (int i = r - radius; i <= r + radius; i++) {
            isCovered[i][c] = true;
        }
    }

    private boolean isAllCovered() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] && !isCovered[i][j]) return false;
            }
        }
        return true;
    }

    private void printResult() {
        StringBuilder sb = new StringBuilder();
        sb.append(foundCrosses.size()).append("\n");
        for (Cross cross : foundCrosses) {
            sb.append(cross.toString()).append("\n");
        }
        System.out.print(sb.toString());
    }
}

