         */
        private void computeDistances() {
            // Initialize base distances
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (isStar[i][j]) {
                        distUp[i][j] = distDown[i][j] = distLeft[i][j] = distRight[i][j] = 1;
                    }
                }
            }

            // Upward pass
            for (int i = 1; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (isStar[i][j] && isStar[i - 1][j]) {
                        distUp[i][j] += distUp[i - 1][j];
                    }
                }
            }

            // Downward pass
            for (int i = rows - 2; i >= 0; i--) {
                for (int j = 0; j < cols; j++) {
                    if (isStar[i][j] && isStar[i + 1][j]) {
                        distDown[i][j] += distDown[i + 1][j];
                    }
                }
            }

            // Leftward pass
            for (int i = 0; i < rows; i++) {
                for (int j = 1; j < cols; j++) {
                    if (isStar[i][j] && isStar[i][j - 1]) {
                        distLeft[i][j] += distLeft[i][j - 1];
                    }
                }
            }

            // Rightward pass
            for (int i = 0; i < rows; i++) {
                for (int j = cols - 2; j >= 0; j--) {
                    if (isStar[i][j] && isStar[i][j + 1]) {
                        distRight[i][j] += distRight[i][j + 1];
                    }
                }
            }
        }

        private List<Cross> findMaximalCrosses() {
            List<Cross> crosses = new ArrayList<>();
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (isStar[i][j]) {
                        int minArm = Math.min(Math.min(distUp[i][j], distDown[i][j]),
                                              Math.min(distLeft[i][j], distRight[i][j]));
                        int radius = minArm - 1;

                        // A cross must have a radius of at least 1 to be valid for this problem
                        if (radius >= 1) {
                            crosses.add(new Cross(i + 1, j + 1, radius));
                        }
                    }
                }
            }
            return crosses;
        }

        /**
         * Verifies if the set of identified crosses covers exactly the set of original stars.
         */
        private boolean validateCoverage(List<Cross> crosses) {
            boolean[][] coverageMap = new boolean[rows][cols];

            for (Cross cross : crosses) {
                int r = cross.row - 1; // Convert back to 0-indexed
                int c = cross.col - 1;
                int rad = cross.radius;

                // Mark horizontal arm
                for (int j = c - rad; j <= c + rad; j++) {
                    coverageMap[r][j] = true;
                }
                // Mark vertical arm
                for (int i = r - rad; i <= r + rad; i++) {
                    coverageMap[i][c] = true;
                }
            }

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (isStar[i][j] != coverageMap[i][j]) {
                        return false;
                    }
                }
            }
            return true;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to find the minimum number of "stars" (cross-shaped patterns) 
 * required to cover all '*' cells in a grid.
 */
public class Main {

    public static void main(String[] args) {
        FastReader sc = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = sc.nextInt();
            int m = sc.nextInt();

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                String row = sc.next();
                grid[i] = row.toCharArray();
            }

            StarSolver solver = new StarSolver(n, m, grid);
            StarSolver.Result result = solver.solve();

            if (!result.isAllCovered()) {
                out.println("-1");
            } else {
                out.println(result.getStars().size());
                for (StarSolver.Star star : result.getStars()) {
                    out.println(star.getRow() + " " + star.getCol() + " " + star.getRadius());
                }
            }
        } catch (Exception e) {
            // In a real-world scenario, use proper logging.
        } finally {
            out.close();
        }
    }

    /**
     * Orchestrates the logic for finding stars and verifying coverage.
     */
    static class StarSolver {
        private final int rows;
        private final int cols;
        private final char[][] grid;

        public StarSolver(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
        }

        public Result solve() {
            int[][] left = computeDirectionalDP(0);
            int[][] right = computeDirectionalDP(1);
            int[][] up = computeDirectionalDP(2);
            int[][] down = computeDirectionalDP(3);

            List<Star> stars = new ArrayList<>();
            PriorityQueue<Interval>[] rowIntervals = new PriorityQueue[rows];
            PriorityQueue<Interval>[] colIntervals = new PriorityQueue[cols];

            for (int i = 0; i < rows; i++) rowIntervals[i] = new PriorityQueue<>();
            for (int j = 0; j < cols; j++) colIntervals[j] = new PriorityQueue<>();

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '*') {
                        int radius = Math.min(Math.min(left[i][j], right[i][j]),
                                              Math.min(up[i][j], down[i][j]));
                        if (radius > 0) {
                            stars.add(new Star(i + 1, j + 1, radius));
                            rowIntervals[i].add(new Interval(j - radius, j + radius));
                            colIntervals[j].add(new Interval(i - radius, i + radius));
                        }
                    }
                }
            }

            boolean[][] covered = new boolean[rows][cols];
            applyIntervals(rowIntervals, covered, true);
            applyIntervals(colIntervals, covered, false);

            boolean allCovered = true;
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '*' && !covered[i][j]) {
                        allCovered = false;
                        break;
                    }
                }
                if (!allCovered) break;
            }

            return new Result(stars, allCovered);
        }

        private int[][] computeDirectionalDP(int direction) {
            int[][] dp = new int[rows][cols];
            // Directions: 0=Left, 1=Right, 2=Up, 3=Down
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    int r = i, c = j;
                    if (direction == 0) c = j - 1;
                    else if (direction == 1) c = j + 1;
                    else if (direction == 2) r = i - 1;
                    else if (direction == 3) r = i + 1;

                    if (r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] == '*') {
                        if (direction == 0) dp[i][j] = dp[i][j - 1] + 1;
                        else if (direction == 1) dp[i][j] = dp[i][j + 1] + 1;
                        else if (direction == 2) dp[i][j] = dp[i - 1][j] + 1;
                        else if (direction == 3) dp[i][j] = dp[i + 1][j] + 1;
                    }
                }
            }

            // Correct iteration order for non-linear directions
            if (direction == 1) { // Right
                for (int i = 0; i < rows; i++) 
                    for (int j = cols - 2; j >= 0; j--) 
                        if (grid[i][j+1] == '*') dp[i][j] = dp[i][j+1] + 1;
            } else if (direction == 2) { // Up
                for (int j = 0; j < cols; j++) 
                    for (int i = 1; i < rows; i++) 
                        if (grid[i-1][j] == '*') dp[i][j] = dp[i-1][j] + 1;
            } else if (direction == 3) { // Down
                for (int j = 0; j < cols; j++) 
                    for (int i = rows - 2; i >= 0; i--) 
                        if (grid[i+1][j] == '*') dp[i][j] = dp[i+1][j] + 1;
            } else { // Left
                for (int i = 0; i < rows; i++) 
                    for (int j = 1; j < cols; j++) 
                        if (grid[i][j-1] == '*') dp[i][j] = dp[i][j-1] + 1;
            }
            return dp;
        }

        private void applyIntervals(PriorityQueue<Interval>[] queues, boolean[][] covered, boolean isRow) {
            for (int i = 0; i < queues.length; i++) {
                int maxEnd = -1;
                while (!queues[i].isEmpty()) {
                    Interval curr = queues[i].poll();
                    int start = Math.max(curr.start, maxEnd);
                    int end = curr.end;
                    for (int k = start; k <= end; k++) {
                        if (isRow) covered[i][k] = true;
                        else covered[k][i] = true;
                    }
                    maxEnd = Math.max(maxEnd, end);
                }
            }
        }

        public static class Star {
            private final int row, col, radius;
            public Star(int row, int col, int radius) {
                this.row = row; this.col = col; this.radius = radius;
            }
            public int getRow() { return row; }
            public int getCol() { return col; }
            public int getRadius() { return radius; }
        }

        public static class Result {
            private final List<Star> stars;
            private final boolean success;
            public Result(List<Star> stars, boolean success) {
                this.stars = stars; this.success = success;
            }
            public List<Star> getStars() { return stars; }
            public boolean isAllCovered() { return success; }
        }

        private static class Interval implements Comparable<Interval> {
            int start, end;
            Interval(int start, int end) { this.start = start; this.end = end; }
            @Override
            public int compareTo(Interval o) { return Integer.compare(this.start, o.start); }
        }
    }

    /**
     * High-performance input reader.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for finding the minimum number of crosses to cover a grid of stars.
 * Uses Dynamic Programming to optimize arm length calculation to O(N*M).
 */
public class E1015 {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        int n = reader.nextInt();
        int m = reader.nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = reader.nextRow(m);
        }

        GridCrossSolver solver = new GridCrossSolver(grid);
        List<GridCrossSolver.Cross> solution = solver.solve();

        if (solution == null) {
            System.out.println("-1");
        } else {
            System.out.println(solution.size());
            StringBuilder sb = new StringBuilder();
            for (GridCrossSolver.Cross cross : solution) {
                sb.append(cross.row()).append(" ")
                  .append(cross.col()).append(" ")
                  .append(cross.armLength()).append("\n");
            }
            System.out.print(sb.toString());
        }
    }

    /**
     * Encapsulates the logic for solving the grid cross problem.
     */
    static class GridCrossSolver {
        private final int rows;
        private final int cols;
        private final char[][] grid;

        private static final char STAR = '*';
        private static final char COVERED = '#';

        public record Cross(int row, int col, int armLength) {}

        private enum Direction {
            UP(-1, 0), DOWN(1, 0), LEFT(0, -1), RIGHT(0, 1);
            final int dr, dc;
            Direction(int dr, int dc) {
                this.dr = dr;
                this.dc = dc;
            }
        }

        public GridCrossSolver(char[][] grid) {
            this.grid = grid;
            this.rows = grid.length;
            this.cols = grid[0].length;
        }

        /**
         * Solves the puzzle using a greedy approach based on pre-calculated arm lengths.
         * @return A list of Crosses if solvable, otherwise null.
         */
        public List<Cross> solve() {
            int[][][] armLengths = precomputeArmLengths();
            List<Cross> foundCrosses = new ArrayList<>();

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == STAR) {
                        // The maximum possible arm length at this cell
                        int maxPossibleArm = Math.min(
                            Math.min(armLengths[i][j][Direction.UP.ordinal()], armLengths[i][j][Direction.LEFT.ordinal()),
                            Math.min(armLengths[i][j][Direction.RIGHT.ordinal()], armLengths[i][j][Direction.DOWN.ordinal()])
                        );

                        if (maxPossibleArm > 0) {
                            foundCrosses.add(new Cross(i + 1, j + 1, maxPossibleArm));
                            markCovered(i, j, maxPossibleArm);
                        }
                    }
                }
            }

            return isAllCovered() ? foundCrosses : null;
        }

        /**
         * Uses Dynamic Programming to compute the number of consecutive stars 
         * in all four directions for every cell in O(N*M).
         */
        private int[][][] precomputeArmLengths() {
            int[][][] arms = new int[rows][cols][Direction.values().length];

            // Up and Left (Top-to-Bottom, Left-to-Right)
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == STAR) {
                        if (i > 0 && grid[i - 1][j] == STAR) arms[i][j][Direction.UP.ordinal()] = arms[i - 1][j][Direction.UP.ordinal()] + 1;
                        if (j > 0 && grid[i][j - 1] == STAR) arms[i][j][Direction.LEFT.ordinal()] = arms[i][j - 1][Direction.LEFT.ordinal()] + 1;
                    }
                }
            }

            // Down and Right (Bottom-to-Top, Right-to-Left)
            for (int i = rows - 1; i >= 0; i--) {
                for (int j = cols - 1; j >= 0; j--) {
                    if (grid[i][j] == STAR) {
                        if (i < rows - 1 && grid[i + 1][j] == STAR) arms[i][j][Direction.DOWN.ordinal()] = arms[i + 1][j][Direction.DOWN.ordinal()] + 1;
                        if (j < cols - 1 && grid[i][j + 1] == STAR) arms[i][j][Direction.RIGHT.ordinal()] = arms[i][j + 1][Direction.RIGHT.ordinal()] + 1;
                    }
                }
            }
            return arms;
        }

        private void markCovered(int r, int c, int armLength) {
            grid[r][c] = COVERED;
            for (Direction dir : Direction.values()) {
                for (int step = 1; step <= armLength; step++) {
                    grid[r + (dir.dr * step)][c + (dir.dc * step)] = COVERED;
                }
            }
        }

        private boolean isAllCovered() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == STAR) return false;
                }
            }
            return true;
        }
    }

    /**
     * High-performance reader for large inputs.
     */
    static class FastReader {
        private final InputStream in;
        private final byte[] buffer = new byte[1024 * 16];
        private int pointer = 0;
        private int bufferLength = 0;

        public FastReader(InputStream in) {
            this.in = in;
        }

        private int read() throws IOException {
            if (pointer >= bufferLength) {
                pointer = 0;
                bufferLength = in.read(buffer);
                if (bufferLength <= 0) return -1;
            }
            return buffer[pointer++] & 0xff;
        }

        public int nextInt() {
            int c = read();
            while (c >= 0 && c <= 32) c = read();
            if (c == -1) return -1;
            int neg = 1;
            if (c == '-') {
                neg = -1;
                c = read();
            }
            int res = 0;
            while (c > 32) {
                res = res * 10 + (c - '0');
                c = read();
            }
            return res * neg;
        }

        public char[] nextRow(int m) {
            int c = read();
            while (c >= 0 && c <= 32) c = read(); // skip whitespace
            char[] row = new char[m];
            for (int i = 0; i < m; i++) {
                row[i] = (char) c;
                c = read();
            }
            return row;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solution for drawing star patterns to cover all '*' in a grid.
 * Complexity: O(R * C) time and O(R * C) space.
 */
public class StarsDrawing_CF1015E {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            StarDrawingSolver solver = new StarDrawingSolver(rows, cols, reader);
            solver.solve(out);
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    static class Star {
        int r, c, radius;

        Star(int r, int c, int radius) {
            this.r = r;
            this.c = c;
            this.radius = radius;
        }

        @Override
        public String toString() {
            return (r + 1) + " " + (c + 1) + " " + radius;
        }
    }

    static class StarDrawingSolver {
        private final int rows;
        private final int cols;
        private final boolean[][] grid;
        private final FastReader reader;

        public StarDrawingSolver(int rows, int cols, FastReader reader) throws IOException {
            this.rows = rows;
            this.cols = cols;
            this.reader = reader;
            this.grid = new boolean[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                for (int j = 0; j < cols; j++) {
                    if (line.charAt(j) == '*') {
                        grid[i][j] = true;
                    }
                }
            }
        }

        public void solve(PrintWriter out) {
            int[][] leftCount = new int[rows][cols];
            int[][] rightCount = new int[rows][cols];
            int[][] upCount = new int[rows][cols];
            int[][] downCount = new int[rows][cols];

            // Precompute continuous '*' counts in all 4 directions
            for (int i = 0; i < rows; i++) {
                int count = 0;
                for (int j = 0; j < cols; j++) {
                    count = grid[i][j] ? count + 1 : 0;
                    leftCount[i][j] = count;
                }
                count = 0;
                for (int j = cols - 1; j >= 0; j--) {
                    count = grid[i][j] ? count + 1 : 0;
                    rightCount[i][j] = count;
                }
            }

            for (int j = 0; j < cols; j++) {
                int count = 0;
                for (int i = 0; i < rows; i++) {
                    count = grid[i][j] ? count + 1 : 0;
                    upCount[i][j] = count;
                }
                count = 0;
                for (int i = rows - 1; i >= 0; i--) {
                    count = grid[i][j] ? count + 1 : 0;
                    downCount[i][j] = count;
                }
            }

            List<Star> stars = new ArrayList<>();
            // Difference arrays for coverage checking
            // rowDiff handles horizontal coverage, colDiff handles vertical coverage
            int[][] rowDiff = new int[rows][cols + 1];
            int[][] colDiff = new int[cols][rows + 1];

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j]) {
                        int radius = Math.min(Math.min(leftCount[i][j], rightCount[i][j]),
                                              Math.min(upCount[i][j], downCount[i][j])) - 1;

                        // The original logic only considers stars with radius >= 1
                        if (radius > 0) {
                            stars.add(new Star(i, j, radius));

                            // Mark horizontal coverage
                            rowDiff[i][j - radius]++;
                            rowDiff[i][j + radius + 1]--;

                            // Mark vertical coverage
                            colDiff[j][i - radius]++;
                            colDiff[j][i + radius + 1]--;
                        }
                    }
                }
            }

            // Compute Prefix Sums to resolve difference arrays
            for (int i = 0; i < rows; i++) {
                for (int j = 1; j < cols; j++) {
                    rowDiff[i][j] += rowDiff[i][j - 1];
                }
            }
            for (int j = 0; j < cols; j++) {
                for (int i = 1; i < rows; i++) {
                    colDiff[j][i] += colDiff[j][i - 1];
                }
            }

            // Verify if all '*' cells are covered
            boolean allCovered = true;
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j]) {
                        // A cell is covered if it's in the horizontal or vertical range of any star
                        if (rowDiff[i][j] <= 0 && colDiff[j][i] <= 0) {
                            allCovered = false;
                            break;
                        }
                    }
                }
                if (!allCovered) break;
            }

            if (!allCovered) {
                out.println("-1");
            } else {
                out.println(stars.size());
                StringBuilder sb = new StringBuilder();
                for (Star star : stars) {
                    sb.append(star.toString()).append("\n");
                }
                out.print(sb);
            }
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

