/**
 * A solver for the Star Coverage problem.
 * The goal is to find the minimum number of "star" shapes that cover all '*' cells in a grid.
 * A star consists of a center cell and a radius 'r' extending in four directions.
 */
public class Solve6 {

    public static void main(String[] args) {
        try (PrintWriter pw = new PrintWriter(System.out)) {
            StarSolver solver = new StarSolver(new FastReader(System.in));
            solver.solve(pw);
            pw.flush();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    static class Star {
        final int row;
        final int col;
        final int radius;

        public Star(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }

        @Override
        public String toString() {
            return row + " " + col + " " + radius;
        }
    }

    static class StarSolver {
        private final FastReader reader;
        private int rows;
        private int cols;
        private char[][] grid;

        public StarSolver(FastReader reader) {
            this.reader = reader;
        }

        public void solve(PrintWriter pw) throws IOException {
            if (!reader.hasNext()) return;

            this.rows = reader.nextInt();
            this.cols = reader.nextInt();
            this.grid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            // Step 1: Precompute consecutive stars in all 4 directions
            int[][] left = new int[rows][cols];
            int[][] right = new int[rows][cols];
            int[][] up = new int[rows][cols];
            int[][] down = new int[rows][cols];
            computeDirectionalCounts(left, right, up, down);

            // Step 2: Find all maximal stars and track coverage requirements
            List<Star> stars = new ArrayList<>();
            int[][] horizontalCoverageMarker = new int[rows][cols];
            int[][] verticalCoverageMarker = new int[rows][cols];

            findStars(left, right, up, down, stars, horizontalCoverageMarker, verticalCoverageMarker);

            // Step 3: Validate if all '*' cells are covered by the found stars
            boolean[][] isCovered = checkCoverage(horizontalCoverageMarker, verticalCoverageMarker);

            if (!allStarsCovered(isCovered)) {
                pw.println("-1");
            } else {
                pw.println(stars.size());
                for (Star star : stars) {
                    pw.println(star);
                }
            }
        }

        private void computeDirectionalCounts(int[][] left, int[][] right, int[][] up, int[][] down) {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '*') {
                        left[i][j] = (j == 0) ? 1 : left[i][j - 1] + 1;
                        up[i][j] = (i == 0) ? 1 : up[i - 1][j] + 1;
                    }
                }
                for (int j = cols - 1; j >= 0; j--) {
                    if (grid[i][j] == '*') {
                        right[i][j] = (j == cols - 1) ? 1 : right[i][j + 1] + 1;
                    }
                }
            }

            for (int j = 0; j < cols; j++) {
                for (int i = rows - 1; i >= 0; i--) {
                    if (grid[i][j] == '*') {
                        down[i][j] = (i == rows - 1) ? 1 : down[i + 1][j] + 1;
                    }
                }
            }
        }

        private void findStars(int[][] left, int[][] right, int[][] up, int[][] down,
                               List<Star> stars, int[][] hMarker, int[][] vMarker) {
            // We iterate from 1 to n-2 because a star needs neighbors in all directions
            for (int i = 1; i < rows - 1; i++) {
                for (int j = 1; j < cols - 1; j++) {
                    if (grid[i][j] == '*') {
                        // Radius is the minimum number of consecutive stars in any of the 4 directions
                        // subtracting 1 because the center is included in the count
                        int radius = Math.min(Math.min(left[i][j - 1], right[i][j + 1]),
                                              Math.min(up[i - 1][j], down[i + 1][j]));

                        if (radius > 0) {
                            stars.add(new Star(i + 1, j + 1, radius));

                            // Mark segments for coverage validation using a sweeping-length approach
                            // A star of radius R covers 2R + 1 cells
                            hMarker[i][j - radius] = Math.max(hMarker[i][j - radius], 2 * radius + 1);
                            vMarker[i - radius][j] = Math.max(vMarker[i - radius][j], 2 * radius + 1);
                        }
                    }
                }
            }
        }

        private boolean[][] checkCoverage(int[][] hMarker, int[][] vMarker) {
            boolean[][] covered = new boolean[rows][cols];

            // Process horizontal coverage segments
            for (int i = 0; i < rows; i++) {
                int remainingLength = 0;
                for (int j = 0; j < cols; j++) {
                    remainingLength = Math.max(remainingLength, hMarker[i][j]);
                    if (remainingLength > 0) {
                        covered[i][j] = true;
                        remainingLength--;
                    }
                }
            }

            // Process vertical coverage segments
            for (int j = 0; j < cols; j++) {
                int remainingLength = 0;
                for (int i = 0; i < rows; i++) {
                    remainingLength = Math.max(remainingLength, vMarker[i][j]);
                    if (remainingLength > 0) {
                        covered[i][j] = true;
                        remainingLength--;
                    }
                }
            }
            return covered;
        }

        private boolean allStarsCovered(boolean[][] covered) {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '*' && !covered[i][j]) {
                        return false;
                    }
                }
            }
            return true;
        }
    }

    /**
     * Fast I/O Utility
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public boolean hasNext() throws IOException {
            while (st != null && st.hasMoreElements()) return true;
            String line = br.readLine();
            if (line == null) return false;
            st = new StringTokenizer(line);
            return true;
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            StarSolver solver = new StarSolver(reader);
            solver.solve(writer);
        } catch (Exception e) {
            // Standard error output for debugging
            e.printStackTrace();
        } finally {
            writer.flush();
            writer.close();
        }
    }

    static class Star {
        private final int row;
        private final int col;
        private final int radius;

        public Star(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }

        public int getRow() { return row; }
        public int getCol() { return col; }
        public int getRadius() { return radius; }

        @Override
        public String toString() {
            return row + " " + col + " " + radius;
        }
    }

    static class StarSolver {
        private final FastReader reader;

        public StarSolver(FastReader reader) {
            this.reader = reader;
        }

        public void solve(PrintWriter out) throws IOException {
            String firstLine = reader.next();
            if (firstLine == null) return;

            int rows = Integer.parseInt(firstLine);
            int cols = reader.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            List<Star> foundStars = findStars(grid, rows, cols);
            boolean[][] visited = createCoverageMap(foundStars, rows, cols);

            if (isAllStarsCovered(grid, visited, rows, cols)) {
                out.println(foundStars.size());
                for (Star star : foundStars) {
                    out.println(star);
                }
            } else {
                out.println("-1");
            }
        }

        private List<Star> findStars(char[][] grid, int rows, int cols) {
            List<Star> stars = new ArrayList<>();
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '*') {
                        int radius = calculateMaxRadius(grid, i, j, rows, cols);
                        if (radius > 0) {
                            stars.add(new Star(i + 1, j + 1, radius));
                        }
                    }
                }
            }
            return stars;
        }

        private int calculateMaxRadius(char[][] grid, int r, int c, int rows, int cols) {
            int radius = 0;
            while (true) {
                int nextRadius = radius + 1;
                if (r - nextRadius >= 0 && r + nextRadius < rows &&
                    c - nextRadius >= 0 && c + nextRadius < cols &&
                    grid[r - nextRadius][c] == '*' &&
                    grid[r + nextRadius][c] == '*' &&
                    grid[r][c - nextRadius] == '*' &&
                    grid[r][c + nextRadius] == '*') {
                    radius = nextRadius;
                } else {
                    break;
                }
            }
            return radius;
        }

        private boolean[][] createCoverageMap(List<Star> stars, int rows, int cols) {
            boolean[][] visited = new boolean[rows][cols];
            for (Star star : stars) {
                int r = star.getRow() - 1;
                int c = star.getCol() - 1;
                int radius = star.getRadius();

                visited[r][c] = true;
                for (int k = 1; k <= radius; k++) {
                    visited[r - k][c] = true;
                    visited[r + k][c] = true;
                    visited[r][c - k] = true;
                    visited[r][c + k] = true;
                }
            }
            return visited;
        }

        private boolean isAllStarsCovered(char[][] grid, boolean[][] visited, int rows, int cols) {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '*' && !visited[i][j]) {
                        return false;
                    }
                }
            }
            return true;
        }
    }

    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

/**
 * Main entry point for the Cross Pattern Solver.
 */
public class Main {
    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        CrossSolver solver = new CrossSolver();
        solver.solve(in, out);

        out.close();
    }

    /**
     * Represents a coordinate point in the grid.
     */
    record Point(int row, int col) {}

    /**
     * Represents a found cross pattern with its center and ray length.
     */
    record Cross(int row, int col, int ray) {}

    /**
     * Manages the grid state and provides semantic operations.
     */
    static class Grid {
        private static final char STAR = '*';
        private static final char DOT = '.';
        private static final char COVERED = '1';

        private final char[][] cells;
        private final int rows;
        private final int cols;

        public Grid(int rows, int cols, InputReader in) {
            this.rows = rows;
            this.cols = cols;
            this.cells = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                this.cells[i] = in.next().toCharArray();
            }
        }

        public int getRows() { return rows; }
        public int getCols() { return cols; }

        public boolean isStar(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols && cells[r][c] == STAR;
        }

        public boolean isNotDot(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols && cells[r][c] != DOT;
        }

        public void markCovered(int r, int c) {
            cells[r][c] = COVERED;
        }

        public boolean hasUncoveredStars() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (cells[i][j] == STAR) return true;
                }
            }
            return false;
        }

        /**
         * Finds all points that could serve as the center of a cross of at least ray 1.
         */
        public List<Point> findPotentialCenters() {
            List<Point> centers = new ArrayList<>();
            for (int r = 1; r < rows - 1; r++) {
                for (int c = 1; c < cols - 1; c++) {
                    if (isStar(r, c) && isStar(r - 1, c) && isStar(r + 1, c) 
                        && isStar(r, c - 1) && isStar(r, c + 1)) {
                        centers.add(new Point(r, c));
                    }
                }
            }
            return centers;
        }

        /**
         * Attempts to expand a cross from the center and marks cells as covered.
         * @return the maximum ray length found.
         */
        public int expandAndMark(int centerR, int centerC) {
            markCovered(centerR, centerC);
            int maxRay = 0;
            int limit = Math.max(rows, cols);

            for (int ray = 1; ray < limit; ray++) {
                int up = centerR - ray, down = centerR + ray;
                int left = centerC - ray, right = centerC + ray;

                if (isNotDot(up, centerC) && isNotDot(down, centerC) 
                    && isNotDot(centerR, left) && isNotDot(centerR, right)) {

                    markCovered(up, centerC);
                    markCovered(down, centerC);
                    markCovered(centerR, left);
                    markCovered(centerR, right);
                    maxRay = ray;
                } else {
                    break;
                }
            }
            return maxRay;
        }
    }

    /**
     * Contains the core logic to solve the cross pattern problem.
     */
    static class CrossSolver {
        public void solve(InputReader in, PrintWriter out) {
            int rows = in.nextInt();
            int cols = in.nextInt();
            Grid grid = new Grid(rows, cols, in);

            List<Point> candidates = grid.findPotentialCenters();
            List<Cross> foundCrosses = new ArrayList<>();

            for (Point p : candidates) {
                int ray = grid.expandAndMark(p.row(), p.col());
                if (ray > 0) {
                    foundCrosses.add(new Cross(p.row(), p.col(), ray));
                }
            }

            if (grid.hasUncoveredStars()) {
                out.println("-1");
            } else {
                out.println(foundCrosses.size());
                for (Cross cross : foundCrosses) {
                    // Convert 0-indexed to 1-indexed for output
                    out.printf("%d %d %d%n", cross.row() + 1, cross.col() + 1, cross.ray());
                }
            }
        }
    }

    /**
     * Utility class for fast I/O.
     */
    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver for finding a set of maximal "plus" shapes that cover all '*' characters in a grid.
 * A plus shape consists of a center and arms extending in four directions.
 */
public class E501B {

    private static final char STAR = '*';
    private static final char EMPTY = '.';

    /**
     * Represents a found plus shape with its center coordinates and radius.
     */
    private record PlusShape(int row, int col, int radius) {
        @Override
        public String toString() {
            return row + " " + col + " " + radius;
        }
    }

    public static void main(String[] args) {
        try {
            Solver solver = new Solver(System.in);
            solver.solve();
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    static class Solver {
        private final BufferedReader reader;
        private final PrintWriter out;
        private int rows;
        private int cols;
        private char[][] grid;

        public Solver(InputStream inputStream) {
            this.reader = new BufferedReader(new InputStreamReader(inputStream));
            this.out = new PrintWriter(System.out);
        }

        public void solve() throws IOException {
            if (!readInput()) {
                return;
            }

            // Boundary condition: if any corner is a star, it cannot be covered by a plus shape
            if (isCornerInvalid()) {
                out.println("-1");
                out.close();
                return;
            }

            int[][] upDist = calculateDistances(true, true);    // Up
            int[][] downDist = calculateDistances(false, true); // Down
            int[][] leftDist = calculateDistances(true, false); // Left
            int[][] rightDist = calculateDistances(false, false); // Right

            List<PlusShape> foundPluses = findMaximalPluses(upDist, downDist, leftDist, rightDist);
            boolean[][] coverageMask = createCoverageMask(foundPluses);

            if (isAllStarsCovered(coverageMask)) {
                out.println(foundPluses.size());
                for (PlusShape plus : foundPluses) {
                    out.println(plus);
                }
            } else {
                out.println("-1");
            }

            out.close();
        }

        private boolean readInput() throws IOException {
            String line = reader.readLine();
            if (line == null) return false;

            StringTokenizer st = new StringTokenizer(line);
            rows = Integer.parseInt(st.nextToken());
            cols = Integer.parseInt(st.nextToken());
            grid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                String rowStr = reader.readLine();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = rowStr.charAt(j);
                }
            }
            return true;
        }

        private boolean isCornerInvalid() {
            return grid[0][0] == STAR || 
                   grid[0][cols - 1] == STAR || 
                   grid[rows - 1][0] == STAR || 
                   grid[rows - 1][cols - 1] == STAR;
        }

        /**
         * Calculates the number of consecutive stars in a specific direction for every cell.
         * 
         * @param forward Direction of iteration (true: 0 to N, false: N to 0)
         * @param vertical If true, processes columns; if false, processes rows
         * @return A 2D array of counts
         */
        private int[][] calculateDistances(boolean forward, boolean vertical) {
            int[][] dist = new int[rows][cols];

            for (int i = (forward ? 0 : rows - 1); 
                 (forward ? i < rows : i >= 0); 
                 (forward ? i++ : i--)) {

                for (int j = (forward ? 0 : cols - 1); 
                     (forward ? j < cols : j >= 0); 
                     (forward ? j++ : j--)) {

                    if (grid[i][j] == EMPTY) {
                        dist[i][j] = 0;
                        continue;
                    }

                    int prevI = vertical ? (forward ? i - 1 : i + 1) : i;
                    int prevJ = !vertical ? (forward ? j - 1 : j + 1) : j;

                    if (isOutOfBounds(prevI, prevJ)) {
                        dist[i][j] = 1;
                    } else {
                        dist[i][j] = dist[prevI][prevJ] + 1;
                    }
                }
            }
            return dist;
        }

        private List<PlusShape> findMaximalPluses(int[][] up, int[][] down, int[][] left, int[][] right) {
            List<PlusShape> plusShapes = new ArrayList<>();

            // We only check internal cells because a plus needs at least 1 neighbor in all 4 directions
            for (int i = 1; i < rows - 1; i++) {
                for (int j = 1; j < cols - 1; j++) {
                    if (grid[i][j] == STAR) {
                        int minArm = Math.min(Math.min(up[i][j], down[i][j]), 
                                              Math.min(left[i][j], right[i][j]));

                        // A center is valid if it has at least one neighbor in all 4 directions
                        if (minArm > 1) {
                            int radius = minArm - 1;
                            // The problem implies we use the largest possible plus for this center
                            plusShapes.add(new PlusShape(i + 1, j + 1, radius));
                        }
                    }
                }
            }
            return plusShapes;
        }

        private boolean[][] createCoverageMask(List<PlusShape> pluses) {
            boolean[][] mask = new boolean[rows][cols];
            for (PlusShape p : pluses) {
                int r = p.row - 1; // convert to 0-indexed
                int c = p.col - 1;
                int rad = p.radius;

                for (int k = 0; k <= rad; k++) {
                    mask[r + k][c] = true;
                    mask[r - k][c] = true;
                    mask[r][c + k] = true;
                    mask[r][c - k] = true;
                }
            }
            return mask;
        }

        private boolean isAllStarsCovered(boolean[][] mask) {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == STAR && !mask[i][j]) {
                        return false;
                    }
                }
            }
            return true;
        }

        private boolean isOutOfBounds(int r, int c) {
            return r < 0 || r >= rows || c < 0 || c >= cols;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver for finding the maximum possible plus-shaped patterns 
 * in a grid of characters and verifying if they cover all '*' characters.
 */
public class PlusSignSolver {

    private static final char TARGET_CHAR = '*';
    private static final char EMPTY_CHAR = '.';

    /**
     * Represents a plus-sign pattern centered at (row, col) with a given radius.
     */
    public static class PlusSign {
        private final int row;
        private final int col;
        private final int radius;

        public PlusSign(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }

        @Override
        public String toString() {
            return row + " " + col + " " + radius;
        }
    }

    private int rows;
    private int cols;
    private char[][] originalGrid;
    private char[][] reconstructedGrid;

    private int[][] leftDist;
    private int[][] rightDist;
    private int[][] upDist;
    private int[][] downDist;

    private final List<PlusSign> foundPlusSigns = new ArrayList<>();

    public void solve() throws IOException {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            rows = reader.nextInt();
            cols = reader.nextInt();
            originalGrid = new char[rows][cols];
            reconstructedGrid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                originalGrid[i] = line.toCharArray();
                Arrays.fill(reconstructedGrid[i], EMPTY_CHAR);
            }

            calculateDistances();
            findAndApplyPlusSigns();

            if (isReconstructionValid()) {
                out.println(foundPlusSigns.size());
                for (PlusSign ps : foundPlusSigns) {
                    out.println(ps);
                }
            } else {
                out.println("-1");
            }
        } finally {
            out.close();
        }
    }

    /**
     * Pre-calculates the number of consecutive '*' in all four directions for every cell.
     */
    private void calculateDistances() {
        leftDist = new int[rows][cols];
        rightDist = new int[rows][cols];
        upDist = new int[rows][cols];
        downDist = new int[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (originalGrid[i][j] == TARGET_CHAR) {
                    leftDist[i][j] = (j > 0 ? leftDist[i][j - 1] : 0) + 1;
                }
            }
            for (int j = cols - 1; j >= 0; j--) {
                if (originalGrid[i][j] == TARGET_CHAR) {
                    rightDist[i][j] = (j < cols - 1 ? rightDist[i][j + 1] : 0) + 1;
                }
            }
        }

        for (int j = 0; j < cols; j++) {
            for (int i = 0; i < rows; i++) {
                if (originalGrid[i][j] == TARGET_CHAR) {
                    upDist[i][j] = (i > 0 ? upDist[i - 1][j] : 0) + 1;
                }
            }
            for (int i = rows - 1; i >= 0; i--) {
                if (originalGrid[i][j] == TARGET_CHAR) {
                    downDist[i][j] = (i < rows - 1 ? downDist[i + 1][j] : 0) + 1;
                }
            }
        }
    }

    /**
     * Iterates through the grid and attempts to place the largest possible plus sign at each '*'.
     */
    private void findAndApplyPlusSigns() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (originalGrid[i][j] == TARGET_CHAR) {
                    attemptToPlacePlusSign(i, j);
                }
            }
        }
    }

    private void attemptToPlacePlusSign(int r, int c) {
        int maxRadius = Math.min(Math.min(leftDist[r][c], rightDist[r][c]),
                                 Math.min(upDist[r][c], downDist[r][c]));

        // The original logic only uses radius k where k = maxRadius - 1
        int k = maxRadius - 1;

        if (k > 0) {
            foundPlusSigns.add(new PlusSign(r + 1, c + 1, k));
            // Draw the plus sign onto the reconstruction grid
            for (int radius = k; radius >= 0; radius--) {
                markCell(r + radius, c);
                markCell(r - radius, c);
                markCell(r, c + radius);
                markCell(r, c - radius);
            }
        }
    }

    private void markCell(int r, int c) {
        if (r >= 0 && r < rows && c >= 0 && c < cols) {
            reconstructedGrid[r][c] = TARGET_CHAR;
        }
    }

    /**
     * Checks if the reconstructed grid matches the original grid pattern.
     */
    private boolean isReconstructionValid() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (originalGrid[i][j] != reconstructedGrid[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    public static void main(String[] args) {
        try {
            new PlusSignSolver().solve();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * Utility class for fast input parsing.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Main entry point for the Stars Drawing problem.
 */
public class Main {
    public static void main(String[] args) {
        try (InputStream inputStream = System.in;
             PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)))) {

            FastReader reader = new FastReader(inputStream);
