/**
 * Handles the core logic for identifying stars and ensuring all '*' cells are covered.
 */
class StarProblemSolver {

    /**
     * Executes the problem-solving algorithm.
     * 
     * @param reader The input reader.
     * @param out    The output writer.
     * @throws IOException If an I/O error occurs.
     */
    public void solve(FastReader reader, PrintWriter out) throws IOException {
        int rows = reader.nextInt();
        int cols = reader.nextInt();
        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            grid[i] = reader.next().toCharArray();
        }

        // 1. Calculate how many consecutive '*' exist in each direction for every cell.
        int[][] leftReach = new int[rows][cols];
        int[][] rightReach = new int[rows][cols];
        int[][] upReach = new int[rows][cols];
        int[][] downReach = new int[rows][cols];
        calculateDirectionalReach(grid, rows, cols, leftReach, rightReach, upReach, downReach);

        // 2. Identify star centers and update reach arrays to mark the star's "influence".
        StringBuilder starResults = new StringBuilder();
        int starCount = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int radius = Math.min(Math.min(leftReach[i][j], rightReach[i][j]),
                                      Math.min(upReach[i][j], downReach[i][j]));

                if (radius > 0) {
                    starCount++;
                    starResults.append((i + 1)).append(" ").append((j + 1)).append(" ").append(radius).append("\n");

                    // Update reach arrays to store the "influence" of this star for coverage checking.
                    // We store radius + 1 so the sweep algorithm knows how far to extend.
                    int influence = radius + 1;
                    leftReach[i][j] = rightReach[i][j] = upReach[i][j] = downReach[i][j] = influence;
                } else {
                    leftReach[i][j] = rightReach[i][j] = upReach[i][j] = downReach[i][j] = 0;
                }
            }
        }

        // 3. Mark all cells covered by the identified stars.
        boolean[][] isCovered = markCoveredCells(rows, cols, leftReach, rightReach, upReach, downReach);

        // 4. Validate that every '*' in the original grid is covered.
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*' && !isCovered[i][j]) {
                    out.println("-1");
                    return;
                }
            }
        }

        out.println(starCount);
        out.print(starResults.toString());
    }

    private void calculateDirectionalReach(char[][] grid, int rows, int cols, 
                                           int[][] left, int[][] right, 
                                           int[][] up, int[][] down) {
        // Horizontal passes
        for (int i = 0; i < rows; i++) {
            for (int j = 1; j < cols; j++) {
                if (grid[i][j - 1] == '*' && grid[i][j] == '*') {
                    left[i][j] = left[i][j - 1] + 1;
                }
            }
            for (int j = cols - 2; j >= 0; j--) {
                if (grid[i][j + 1] == '*' && grid[i][j] == '*') {
                    right[i][j] = right[i][j + 1] + 1;
                }
            }
        }

        // Vertical passes
        for (int j = 0; j < cols; j++) {
            for (int i = 1; i < rows; i++) {
                if (grid[i - 1][j] == '*' && grid[i][j] == '*') {
                    up[i][j] = up[i - 1][j] + 1;
                }
            }
            for (int i = rows - 2; i >= 0; i--) {
                if (grid[i + 1][j] == '*' && grid[i][j] == '*') {
                    down[i][j] = down[i + 1][j] + 1;
                }
            }
        }
    }

    private boolean[][] markCoveredCells(int rows, int cols, int[][] left, int[][] right, 
                                         int[][] up, int[][] down) {
        boolean[][] isCovered = new boolean[rows][cols];

        // Sweep rows (Left-to-Right and Right-to-Left)
        for (int i = 0; i < rows; i++) {
            int maxReach = 0;
            for (int j = 0; j < cols; j++) {
                maxReach = Math.max(maxReach, right[i][j]);
                if (maxReach > 0) {
                    isCovered[i][j] = true;
                    maxReach--;
                }
            }
            maxReach = 0;
            for (int j = cols - 1; j >= 0; j--) {
                maxReach = Math.max(maxReach, left[i][j]);
                if (maxReach > 0) {
                    isCovered[i][j] = true;
                    maxReach--;
                }
            }
        }

        // Sweep columns (Top-to-Bottom and Bottom-to-Top)
        for (int j = 0; j < cols; j++) {
            int maxReach = 0;
            for (int i = 0; i < rows; i++) {
                maxReach = Math.max(maxReach, down[i][j]);
                if (maxReach > 0) {
                    isCovered[i][j] = true;
                    maxReach--;
                }
            }
            maxReach = 0;
            for (int i = rows - 1; i >= 0; i--) {
                maxReach = Math.max(maxReach, up[i][j]);
                if (maxReach > 0) {
                    isCovered[i][j] = true;
                    maxReach--;
                }
            }
        }
        return isCovered;
    }
}

/**
 * Efficient reader for fast I/O operations.
 */
class FastReader {
    private final InputStream stream;
    private final byte[] buffer = new byte[1024];
    private int curChar;
    private int numChars;

    public FastReader(InputStream stream) {
        this.stream = stream;
    }

    private int read() {
        if (numChars == -1) throw new InputMismatchException();
        if (curChar >= numChars) {
            curChar = 0;
            try {
                numChars = stream.read(buffer);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (numChars <= 0) return -1;
        }
        return buffer[curChar++];
    }

    public int nextInt() {
        int c = read();
        while (isSpaceChar(c)) c = read();
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        int res = 0;
        do {
            if (c < '0' || c > '9') throw new InputMismatchException();
            res *= 10;
            res += c - '0';
            c = read();
        } while (!isSpaceChar(c));
        return res * sgn;
    }

    public String next() {
        int c = read();
        while (isSpaceChar(c)) c = read();
        StringBuilder res = new StringBuilder();
        do {
            res.appendCodePoint(c);
            c = read();
        } while (!isSpaceChar(c));
        return res.toString();
    }

    private boolean isSpaceChar(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }
}

import java.util.*;

/**
 * Solution for identifying and reconstructing cross shapes within a grid of characters.
 */
public class Solution {

    /**
     * Represents a cross shape centered at a specific coordinate with a given radius.
     */
    private static class Cross {
        final int row;
        final int col;
        final int radius;

        Cross(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        char[][] grid = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            grid[i] = line.toCharArray();
        }
        scanner.close();

        List<Cross> detectedCrosses = findCrosses(grid, rows, cols);
        char[][] reconstructedGrid = reconstructGrid(rows, cols, detectedCrosses);

        if (isGridMatch(grid, reconstructedGrid)) {
            printResults(detectedCrosses);
        } else {
            System.out.println("-1");
        }
    }

    /**
     * Scans the input grid to identify all valid crosses.
     * A cross is defined by a center '*' and arms of equal length in four directions.
     */
    private static List<Cross> findCrosses(char[][] grid, int rows, int cols) {
        List<Cross> crosses = new ArrayList<>();

        // The original logic avoids checking the boundary rows/cols as potential centers.
        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < cols - 1; c++) {
                if (grid[r][c] == '*') {
                    int radius = calculateMaxRadius(grid, r, c, rows, cols);
                    if (radius > 0) {
                        crosses.add(new Cross(r, c, radius));
                    }
                }
            }
        }
        return crosses;
    }

    /**
     * Determines the maximum radius of a cross centered at (r, c).
     * Replicates the specific boundary-checking behavior of the original algorithm.
     */
    private static int calculateMaxRadius(char[][] grid, int r, int c, int rows, int cols) {
        int radius = 0;
        while (true) {
            int nextRadius = radius + 1;

            // Check if the next radius is within valid bounds and if arms are all '*'
            if (isWithinBounds(r, c, nextRadius, rows, cols) && 
                isArmValid(grid, r, c, nextRadius)) {
                radius = nextRadius;
            } else {
                break;
            }
        }
        return radius;
    }

    /**
     * Checks if the arms of a cross with the given radius stay within the array boundaries.
     */
    private static boolean isWithinBounds(int r, int c, int rad, int rows, int cols) {
        return r - rad >= 0 && r + rad < rows && 
               c - rad >= 0 && c + rad < cols;
    }

    /**
     * Checks if all four arms of the cross at the given radius consist of '*' characters.
     */
    private static boolean isArmValid(char[][] grid, int r, int c, int rad) {
        return grid[r - rad][c] == '*' && 
               grid[r + rad][c] == '*' && 
               grid[r][c - rad] == '*' && 
               grid[r][c + rad] == '*';
    }

    /**
     * Creates a new grid and draws all detected crosses onto it.
     */
    private static char[][] reconstructGrid(int rows, int cols, List<Cross> crosses) {
        char[][] reconstructed = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            Arrays.fill(reconstructed[i], '.');
        }

        for (Cross cross : crosses) {
            for (int i = 0; i <= cross.radius; i++) {
                reconstructed[cross.row - i][cross.col] = '*';
                reconstructed[cross.row + i][cross.col] = '*';
                reconstructed[cross.row][cross.col - i] = '*';
                reconstructed[cross.row][cross.col + i] = '*';
            }
        }
        return reconstructed;
    }

    /**
     * Compares the original grid with the reconstructed grid to ensure they are identical.
     */
    private static boolean isGridMatch(char[][] original, char[][] reconstructed) {
        for (int i = 0; i < original.length; i++) {
            for (int j = 0; j < original[0].length; j++) {
                if (original[i][j] != reconstructed[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Outputs the number of crosses and their 1-based coordinates and radius.
     */
    private static void printResults(List<Cross> crosses) {
        System.out.println(crosses.size());
        for (Cross cross : crosses) {
            // Output format: row col radius (using 1-based indexing for row and col)
            System.out.printf("%d %d %d%n", cross.row + 1, cross.col + 1, cross.radius);
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * Problem: Draw stars (diamonds) to cover all '*' cells in a grid.
 * A star of radius k at (r, c) covers all cells (i, j) where |r-i| + |c-j| <= k.
 * This implementation uses the property that if a solution exists, 
 * every '*' cell must lie on the horizontal or vertical axis of a maximal star.
 */
public class StarDrawing {

    public static void main(String[] args) {
        try {
            StarDrawingSolver solver = new StarDrawingSolver();
            solver.solve();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /**
     * Represents a star with a center position and a radius.
     */
    static class Star {
        int row, col, radius;

        Star(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }

        @Override
        public String toString() {
            return row + " " + col + " " + radius;
        }
    }

    /**
     * Handles the core logic of the star drawing problem.
     */
    static class StarDrawingSolver {
        private final FastReader reader = new FastReader();
        private final PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        public void solve() throws IOException {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            boolean[][] isStarGrid = new boolean[rows + 1][cols + 1];
            for (int i = 1; i <= rows; i++) {
                String line = reader.next();
                for (int j = 1; j <= cols; j++) {
                    if (line.charAt(j - 1) == '*') {
                        isStarGrid[i][j] = true;
                    }
                }
            }

            // Precompute consecutive stars in all four directions
            int[][] upCount = new int[rows + 2][cols + 2];
            int[][] downCount = new int[rows + 2][cols + 2];
            int[][] leftCount = new int[rows + 2][cols + 2];
            int[][] rightCount = new int[rows + 2][cols + 2];

            for (int i = 1; i <= rows; i++) {
                for (int j = 1; j <= cols; j++) {
                    if (isStarGrid[i][j]) {
                        upCount[i][j] = upCount[i - 1][j] + 1;
                        leftCount[i][j] = leftCount[i][j - 1] + 1;
                    }
                }
            }

            for (int i = rows; i >= 1; i--) {
                for (int j = cols; j >= 1; j--) {
                    if (isStarGrid[i][j]) {
                        downCount[i][j] = downCount[i + 1][j] + 1;
                        rightCount[i][j] = rightCount[i][j + 1] + 1;
                    }
                }
            }

            // difference arrays to track coverage of '*' by star axes
            int[][] verticalDiff = new int[rows + 2][cols + 2];
            int[][] horizontalDiff = new int[rows + 2][cols + 2];
            List<Star> stars = new ArrayList<>();

            for (int i = 1; i <= rows; i++) {
                for (int j = 1; j <= cols; j++) {
                    if (isStarGrid[i][j]) {
                        // The maximum possible radius for a star centered at (i, j)
                        int maxRadius = Math.min(
                            Math.min(upCount[i][j], downCount[i][j]),
                            Math.min(leftCount[i][j], rightCount[i][j])
                        ) - 1;

                        if (maxRadius > 0) {
                            stars.add(new Star(i, j, maxRadius));
                            // Mark vertical axis coverage
                            verticalDiff[i - maxRadius][j]++;
                            verticalDiff[i + maxRadius + 1][j]--;
                            // Mark horizontal axis coverage
                            horizontalDiff[i][j - maxRadius]++;
                            horizontalDiff[i][j + maxRadius + 1]--;
                        }
                    }
                }
            }

            // Apply prefix sums to difference arrays to get actual coverage counts
            for (int i = 1; i <= rows; i++) {
                for (int j = 1; j <= cols; j++) {
                    verticalDiff[i][j] += verticalDiff[i - 1][j];
                }
            }

            boolean allCovered = true;
            for (int i = 1; i <= rows; i++) {
                for (int j = 1; j <= cols; j++) {
                    horizontalDiff[i][j] += horizontalDiff[i][j - 1];

                    // If a star cell is not covered by any star's axis, it's impossible
                    if (isStarGrid[i][j] && (verticalDiff[i][j] + horizontalDiff[i][j] == 0)) {
                        allCovered = false;
                        break;
                    }
                }
                if (!allCovered) break;
            }

            if (!allCovered) {
                writer.println("-1");
            } else {
                writer.println(stars.size());
                for (Star star : stars) {
                    writer.println(star.toString());
                }
            }
            writer.flush();
        }
    }

    /**
     * Efficient input reader for large datasets.
     */
    static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A refactored solution for the Star Coverage problem.
 * The goal is to identify stars (crosses) that cover all '#' cells in a grid.
 */
public class Main {
    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        StarCoverageSolver solver = new StarCoverageSolver();
        solver.solve(in, out);

        out.flush();
        out.close();
    }

    /**
     * Represents a star with a center coordinate and a radius.
     */
    static class Star {
        final int x;
        final int y;
        final int radius;

        Star(int x, int y, int radius) {
            this.x = x;
            this.y = y;
            this.radius = radius;
        }
    }

    static class StarCoverageSolver {
        private int rows;
        private int cols;
        private boolean[][] isCovered;
        private int[][] grid;

        public void solve(FastScanner in, PrintWriter out) {
            String firstLine = in.nextLine();
            if (firstLine == null || firstLine.isEmpty()) return;

            StringTokenizer st = new StringTokenizer(firstLine);
            rows = Integer.parseInt(st.nextToken());
            cols = Integer.parseInt(st.nextToken());

            grid = new int[rows][cols];
            isCovered = new boolean[rows][cols];

            for (int i = 0; i < rows; i++) {
                String line = in.nextLine();
                for (int j = 0; j < cols; j++) {
                    // '.' is empty (0), '#' is occupied (1)
                    grid[i][j] = (line.charAt(j) == '.') ? 0 : 1;
                }
            }

            // Precompute distances to the nearest empty cell or boundary in all 4 directions
            int[][] upDist = computeUpDistances();
            int[][] downDist = computeDownDistances();
            int[][] leftDist = computeLeftDistances();
            int[][] rightDist = computeRightDistances();

            List<Star> stars = new ArrayList<>();

            // Iterate through the grid to find potential star centers
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == 1) {
                        // The maximum radius is the minimum distance to an empty cell in any direction
                        int radius = Math.min(
                            Math.min(upDist[i][j], downDist[i][j]),
                            Math.min(leftDist[i][j], rightDist[i][j])
                        );

                        if (radius > 0) {
                            isCovered[i][j] = true;
                            stars.add(new Star(i + 1, j + 1, radius));
                            markCoverage(i, j, radius);
                        }
                    }
                }
            }

            if (isAllOccupiedCellsCovered()) {
                out.println(stars.size());
                for (Star star : stars) {
                    out.println(star.x + " " + star.y + " " + star.radius);
                }
            } else {
                out.println("-1");
            }
        }

        private int[][] computeUpDistances() {
            int[][] dist = new int[rows][cols];
            for (int j = 0; j < cols; j++) {
                for (int i = 1; i < rows; i++) {
                    if (grid[i - 1][j] == 1) {
                        dist[i][j] = dist[i - 1][j] + 1;
                    }
                }
            }
            return dist;
        }

        private int[][] computeDownDistances() {
            int[][] dist = new int[rows][cols];
            for (int j = 0; j < cols; j++) {
                for (int i = rows - 2; i >= 0; i--) {
                    if (grid[i + 1][j] == 1) {
                        dist[i][j] = dist[i + 1][j] + 1;
                    }
                }
            }
            return dist;
        }

        private int[][] computeLeftDistances() {
            int[][] dist = new int[rows][cols];
            for (int i = 0; i < rows; i++) {
                for (int j = 1; j < cols; j++) {
                    if (grid[i][j - 1] == 1) {
                        dist[i][j] = dist[i][j - 1] + 1;
                    }
                }
            }
            return dist;
        }

        private int[][] computeRightDistances() {
            int[][] dist = new int[rows][cols];
            for (int i = 0; i < rows; i++) {
                for (int j = cols - 2; j >= 0; j--) {
                    if (grid[i][j + 1] == 1) {
                        dist[i][j] = dist[i][j + 1] + 1;
                    }
                }
            }
            return dist;
        }

        private void markCoverage(int row, int col, int radius) {
            // Mark the vertical arm of the star
            for (int i = row - radius; i <= row + radius; i++) {
                isCovered[i][col] = true;
            }
            // Mark the horizontal arm of the star
            for (int j = col - radius; j <= col + radius; j++) {
                isCovered[row][j] = true;
            }
        }

        private boolean isAllOccupiedCellsCovered() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == 1 && !isCovered[i][j]) {
                        return false;
                    }
                }
            }
            return true;
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = nextLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public String nextLine() {
            try {
                return reader.readLine();
            } catch (IOException e) {
                return null;
            }
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Represents a cross pattern found in the grid.
 */
class Cross {
    final int row;
    final int col;
    final int armLength;

    public Cross(int row, int col, int armLength) {
        this.row = row;
        this.col = col;
        this.armLength = armLength;
    }

    @Override
    public String toString() {
        // Returns 1-indexed coordinates and arm length as per original requirements
        return (row + 1) + " " + (col + 1) + " " + armLength;
    }
}

/**
 * Logic for finding and validating cross patterns in a grid of characters.
 */
class CrossPatternFinder {
    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final boolean[][] isCellCovered;
    private final List<Cross> foundCrosses;

    public CrossPatternFinder(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.isCellCovered = new boolean[rows][cols];
        this.foundCrosses = new ArrayList<>();
    }

    /**
     * Iterates through the grid to find all possible maximal cross patterns.
     */
    public void findCrosses() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*' && isValidCenter(r, c)) {
                    expandAndRecordCross(r, c);
                }
            }
        }
    }

    /**
     * Checks if a cell can be the center of a cross (must have 4 neighbors).
     */
    private boolean isValidCenter(int r, int c) {
        return r > 0 && r < rows - 1 && c > 0 && c < cols - 1 &&
               grid[r][c] == '*' &&
               grid[r - 1][c] == '*' && grid[r + 1][c] == '*' &&
               grid[r][c - 1] == '*' && grid[r][c + 1] == '*';
    }

    /**
     * Calculates the largest possible symmetrical cross at (r, c) and marks cells as covered.
     */
    private void expandAndRecordCross(int r, int c) {
        int right = countDirection(r, c, 0, 1);
        int left = countDirection(r, c, 0, -1);
        int down = countDirection(r, c, 1, 0);
        int up = countDirection(r, c, -1, 0);

        // The smallest arm determines the maximum symmetrical cross size
        int minArmCount = Math.min(Math.min(right, left), Math.min(up, down));
        int armLength = minArmCount - 1;

        // Mark cells as covered
        markCells(r, c, minArmCount);

        // Store the cross (using armLength as requested by original logic)
        foundCrosses.add(new Cross(r, c, armLength));
    }

    private int countDirection(int r, int c, int dr, int dc) {
        int count = 0;
        int currR = r;
        int currC = c;
        while (currR >= 0 && currR < rows && currC >= 0 && currC < cols && grid[currR][currC] == '*') {
            count++;
            currR += dr;
            currC += dc;
        }
        return count;
    }

    private void markCells(int r, int c, int count) {
        // Directions: Right, Left, Down, Up
        int[][] dirs = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

        // Mark center
        isCellCovered[r][c] = true;

        // Mark arms
        for (int[] dir : dirs) {
            int dr = dir[0];
            int dc = dir[1];
            for (int i = 1; i < count; i++) {
                isCellCovered[r + dr * i][c + dc * i] = true;
            }
        }
    }

    public boolean areAllAsterisksCovered() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*' && !isCellCovered[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    public int getCrossCount() {
        return foundCrosses.size();
    }

    public List<Cross> getFoundCrosses() {
        return foundCrosses;
    }
}

