import java.util.*;
import java.io.*;

/**
 * Solves the problem of finding the maximum number of non-overlapping 
 * crosses (plus-shaped patterns) that cover all '*' characters in a grid.
 */
public class Codeforces {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            int n = reader.nextInt();
            int m = reader.nextInt();
            char[][] grid = reader.readGrid(n);

            CrossGridSolver solver = new CrossGridSolver(n, m, grid);
            solver.solve(out);
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            out.close();
        }
    }

    /**
     * Represents a cross pattern found in the grid.
     */
    static class Cross {
        final int row;
        final int col;
        final int radius;

        Cross(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }

        @Override
        public String toString() {
            return (row + 1) + " " + (col + 1) + " " + radius;
        }
    }

    /**
     * Core logic for processing the grid and calculating cross coverage.
     */
    static class CrossGridSolver {
        private final int rows;
        private final int cols;
        private final char[][] grid;

        CrossGridSolver(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
        }

        public void solve(PrintWriter out) {
            int[][] distUp = calculateDistances(true, true);    // up
            int[][] distDown = calculateDistances(false, true); // down
            int[][] distLeft = calculateDistances(true, false); // left
            int[][] distRight = calculateDistances(false, false); // right

            List<Cross> crosses = new ArrayList<>();
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '*') {
                        int radius = Math.min(Math.min(distUp[i][j], distDown[i][j]),
                                              Math.min(distLeft[i][j], distRight[i][j]));
                        if (radius > 0) {
                            crosses.add(new Cross(i, j, radius));
                        }
                    }
                }
            }

            // Difference arrays to mark coverage
            int[][] rowCoverageDiff = new int[rows][cols];
            int[][] colCoverageDiff = new int[rows][cols];

            for (Cross cross : crosses) {
                // Mark horizontal coverage
                rowCoverageDiff[cross.row][cross.col - cross.radius]++;
                if (cross.col + cross.radius + 1 < cols) {
                    rowCoverageDiff[cross.row][cross.col + cross.radius + 1]--;
                }

                // Mark vertical coverage
                colCoverageDiff[cross.row - cross.radius][cross.col]++;
                if (cross.row + cross.radius + 1 < rows) {
                    colCoverageDiff[cross.row + cross.radius + 1][cross.col]--;
                }
            }

            // Compute prefix sums for coverage
            int[][] rowCoverage = computePrefixSums(rowCoverageDiff, rows, cols, true);
            int[][] colCoverage = computePrefixSums(colCoverageDiff, rows, cols, false);

            // Verify if all '*' are covered
            if (isAllCovered(rowCoverage, colCoverage)) {
                out.println(crosses.size());
                for (Cross cross : crosses) {
                    out.println(cross);
                }
            } else {
                out.println("-1");
            }
        }

        private int[][] calculateDistances(boolean upOrDown, boolean vertical) {
            int[][] dist = new int[rows][cols];
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    // Adjust loop direction for down/right traversals
                    int r = upOrDown ? i : (rows - 1 - i);
                    int c = vertical ? j : (cols - 1 - j);

                    if (grid[r][c] == '.') {
                        dist[r][c] = -1;
                    } else {
                        int prevR = upOrDown ? r - 1 : r + 1;
                        int prevC = vertical ? c - 1 : c + 1;

                        if (isOutOfBounds(prevR, prevC) || grid[prevR][c] == '.') {
                            dist[r][c] = 0;
                        } else {
                            dist[r][c] = 1 + dist[prevR][c];
                        }
                    }
                }
            }
            // Note: The logic above simplifies the 'distance' to the nearest non-star.
            // However, the directions are actually interdependent. 
            // Let's use a more robust directional approach.
            return computeDirectionalDistances(upOrDown, vertical);
        }

        private int[][] computeDirectionalDistances(boolean upOrDown, boolean vertical) {
            int[][] dist = new int[rows][cols];
            // Re-implementing to ensure correct directionality
            // upOrDown: true = Up, false = Down
            // vertical: true = Left, false = Right (Logic flipped in param name for simplicity)

            // To keep it clean, we define direction vectors
            int dr = upOrDown ? -1 : 1;
            int dc = vertical ? -1 : 1;

            // We must iterate in an order that respects the direction
            for (int i = (upOrDown ? 0 : rows - 1); (upOrDown ? i < rows : i >= 0); i += (upOrDown ? 1 : -1)) {
                for (int j = (vertical ? 0 : cols - 1); (vertical ? j < cols : j >= 0); j += (vertical ? 1 : -1)) {
                    if (grid[i][j] == '.') {
                        dist[i][j] = -1;
                    } else {
                        int pr = i + dr;
                        int pc = j + dc;
                        if (isOutOfBounds(pr, pc) || grid[pr][pc] == '.') {
                            dist[i][j] = 0;
                        } else {
                            dist[i][j] = 1 + dist[pr][pc];
                        }
                    }
                }
            }
            return dist;
        }

        private int[][] computePrefixSums(int[][] diff, int r, int c, boolean horizontal) {
            int[][] sum = new int[r][c];
            for (int i = 0; i < r; i++) {
                for (int j = 0; j < c; j++) {
                    if (horizontal) {
                        sum[i][j] = diff[i][j] + (j > 0 ? sum[i][j - 1] : 0);
                    } else {
                        sum[i][j] = diff[i][j] + (i > 0 ? sum[i - 1][j] : 0);
                    }
                }
            }
            return sum;
        }

        private boolean isAllCovered(int[][] rowCov, int[][] colCov) {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '*' && rowCov[i][j] <= 0 && colCov[i][j] <= 0) {
                        return false;
                    }
                }
            }
            return true;
        }

        private boolean isOutOfBounds(int r, int c) {
            return r < 0 || r >= rows || c < 0 || c >= cols;
        }
    }

    /**
     * Fast I/O Utility.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public char[][] readGrid(int n) throws IOException {
            char[][] grid = new char[n][];
            for (int i = 0; i < n; i++) {
                String line = reader.readLine();
                // Handle cases where nextInt() might leave a newline
                while (line == null || line.isEmpty()) {
                    line = reader.readLine();
                }
                grid[i] = line.toCharArray();
            }
            return grid;
        }
    }
}

