            List<Cross> foundCrosses = new ArrayList<>();

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    // Calculate the maximum possible radius at this cell
                    int maxArmLength = Math.min(Math.min(up[i][j], down[i][j]), 
                                                Math.min(left[i][j], right[i][j]));

                    // size > 1 means it's a cross with at least radius 1
                    if (maxArmLength > 1) {
