        private int[][] computeDistances(Direction dir) {
            int[][] dists = new int[rows][cols];
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    int r = i, c = j, count = 0;

                    // Traverse in the given direction until we hit a '.' or boundary
                    while (r >= 0 && r < rows && c >= 0 && c < cols && originalGrid[r][c] != '.') {
                        count++;
                        if (dir == Direction.UP) r--;
                        else if (dir == Direction.DOWN) r++;
                        else if (dir == Direction.LEFT) c--;
                        else if (dir == Direction.RIGHT) c++;
                    }

                    // Note: The original logic calculates distance from the cell itself 
                    // looking "backwards" towards the boundary. 
                    // We re-implement that specific logic here.
                }
            }

            // To perfectly mirror the original logic (which was O(N*M)):
            return runDirectionalScan(dir);
        }

        private int[][] runDirectionalScan(Direction dir) {
            int[][] dists = new int[rows][cols];
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    // Resetting logic to match original: 'up' is count of '#' from top to current
                    // We actually need to iterate based on the direction's flow
                }
            }
            // Let's use a cleaner approach for the 4 passes:
            return scan(dir);
        }

        private int[][] scan(Direction dir) {
            int[][] dists = new int[rows][cols];
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    // This is a simplified way to represent the 4 specific loops in the original code
                }
            }
            // Re-implementing original loop logic for absolute correctness to original algorithm
            if (dir == Direction.UP) {
                for (int j = 0; j < cols; j++) {
                    int cnt = 0;
                    for (int i = 0; i < rows; i++) {
                        cnt = (originalGrid[i][j] == '.') ? 0 : cnt + 1;
                        dists[i][j] = cnt;
                    }
                }
            } else if (dir == Direction.DOWN) {
                for (int j = 0; j < cols; j++) {
                    int cnt = 0;
                    for (int i = rows - 1; i >= 0; i--) {
                        cnt = (originalGrid[i][j] == '.') ? 0 : cnt + 1;
                        dists[i][j] = cnt;
                    }
                }
            } else if (dir == Direction.LEFT) {
                for (int i = 0; i < rows; i++) {
                    int cnt = 0;
                    for (int j = 0; j < cols; j++) {
                        cnt = (originalGrid[i][j] == '.') ? 0 : cnt + 1;
                        dists[i][j] = cnt;
                    }
                }
            } else if (dir == Direction.RIGHT) {
                for (int i = 0; i < rows; i++) {
                    int cnt = 0;
                    for (int j = cols - 1; j >= 0; j--) {
                        cnt = (originalGrid[i][j] == '.') ? 0 : cnt + 1;
                        dists[i][j] = cnt;
                    }
                }
            }
            return dists;
        }

        private void drawCross(int centerRow, int centerCol, int radius) {
            for (int k = 0; k <= radius; k++) {
                reconstructedGrid[centerRow + k][centerCol] = '*';
                reconstructedGrid[centerRow - k][centerCol] = '*';
                reconstructedGrid[centerRow][centerCol + k] = '*';
                reconstructedGrid[centerRow][centerCol - k] = '*';
            }
        }

        private boolean isReconstructionValid() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (originalGrid[i][j] != reconstructedGrid[i][j]) {
                        return false;
