import java.util.*;
import java.io.*;

/**
 * A program to identify maximal cross patterns in a grid of stars ('*').
 * A cross consists of a center and an equal number of stars extending 
 * in all four cardinal directions.
 */
public class StarGridSolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            solve(reader, writer);
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            writer.flush();
            writer.close();
        }
    }

    private static void solve(FastReader reader, PrintWriter writer) throws IOException {
        String firstLine = reader.nextLine();
        if (firstLine == null || firstLine.isEmpty()) return;

        StringTokenizer st = new StringTokenizer(firstLine);
        if (!st.hasMoreTokens()) return;

        int rows = Integer.parseInt(st.nextToken());
        int cols = Integer.parseInt(st.nextToken());

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String rowStr = reader.next();
            if (rowStr != null) {
                grid[i] = rowStr.toCharArray();
            }
        }

        StarGridProcessor processor = new StarGridProcessor(grid, rows, cols);
        processor.process();
        processor.printResults(writer);
    }

    /**
     * Represents a found cross pattern.
     */
    static class Cross {
        final int row;
        final int col;
        final int radius;

        Cross(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }

        @Override
        public String toString() {
            return row + " " + col + " " + radius;
        }
    }

    /**
     * Handles the logic for processing the star grid and finding valid crosses.
     */
    static class StarGridProcessor {
        private final char[][] grid;
        private final int rows;
        private final int cols;
        private final boolean[][] covered;
        private final List<Cross> foundCrosses;

        StarGridProcessor(char[][] grid, int rows, int cols) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
            this.covered = new boolean[rows][cols];
            this.foundCrosses = new ArrayList<>();
        }

        /**
         * Iterates through the grid to find and mark maximal crosses.
         */
        public void process() {
            // Centers cannot be on the extreme edges of the grid
            for (int r = 1; r < rows - 1; r++) {
                for (int c = 1; c < cols - 1; c++) {
                    if (isPotentialCenter(r, c)) {
                        int radius = calculateMaxRadius(r, c);
                        if (radius > 0) {
                            // Store as 1-based coordinates to match original requirement
                            foundCrosses.add(new Cross(r + 1, c + 1, radius));
                            markAsCovered(r, c, radius);
                        }
                    }
                }
            }
        }

        private boolean isPotentialCenter(int r, int c) {
            return grid[r][c] == '*' &&
                   grid[r - 1][c] == '*' &&
                   grid[r + 1][c] == '*' &&
                   grid[r][c - 1] == '*' &&
                   grid[r][c + 1] == '*';
        }

        private int calculateMaxRadius(int r, int c) {
            int up = countConsecutiveStars(r, c, -1, 0);
            int down = countConsecutiveStars(r, c, 1, 0);
            int left = countConsecutiveStars(r, c, 0, -1);
            int right = countConsecutiveStars(r, c, 0, 1);

            return Math.min(Math.min(up, down), Math.min(left, right));
        }

        private int countConsecutiveStars(int r, int c, int dr, int dc) {
            int count = 0;
            int nr = r + dr;
            int nc = c + dc;
            while (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == '*') {
                count++;
                nr += dr;
                nc += dc;
            }
            return count;
        }

        private void markAsCovered(int r, int c, int radius) {
            covered[r][c] = true;
            for (int i = 1; i <= radius; i++) {
                covered[r + i][c] = true;
                covered[r - i][c] = true;
                covered[r][c + i] = true;
                covered[r][c - i] = true;
            }
        }

        public void printResults(PrintWriter writer) {
            if (!allStarsCovered()) {
                writer.println("-1");
                return;
            }

            writer.println(foundCrosses.size());
            for (Cross cross : foundCrosses) {
                writer.println(cross);
            }
        }

        private boolean allStarsCovered() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '*' && !covered[r][c]) {
                        return false;
                    }
                }
            }
            return true;
        }
    }

    /**
     * Fast I/O utility.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public String nextLine() throws IOException {
            return reader.readLine();
        }
    }
}

