/**
 * A solution to solve the Cross Coverage problem.
 * The goal is to find all possible 'cross' patterns in a grid of stars ('*')
 * such that every star is covered by at least one cross.
 */
public class Codechef {

    /**
     * Represents a cross pattern found in the grid.
     */
    static class Cross {
        final int row;
        final int col;
        final int radius;

        Cross(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }

        @Override
        public String toString() {
            return row + " " + col + " " + radius;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        if (!sc.hasNextInt()) {
            return;
        }

        int rows = sc.nextInt();
        int cols = sc.nextInt();
        char[][] grid = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            grid[i] = sc.next().toCharArray();
        }

        solve(rows, cols, grid);
        sc.close();
    }

    /**
     * Orchestrates the logic to find crosses and verify star coverage.
     */
    private static void solve(int rows, int cols, char[][] grid) {
        boolean[][] isCovered = new boolean[rows][cols];
        List<Cross> foundCrosses = new ArrayList<>();

        // We only iterate through internal cells because a cross 
        // with radius >= 1 must have a center that is not on the boundary.
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                // A cross must be centered on a star symbol
                if (grid[i][j] == '*') {
                    int radius = calculateMaxRadius(grid, i, j, rows, cols);
                    if (radius > 0) {
                        // Store 1-indexed coordinates for output requirements
                        foundCrosses.add(new Cross(i + 1, j + 1, radius));
                        markAsCovered(isCovered, i, j, radius);
                    }
                }
            }
        }

        if (checkAllStarsCovered(grid, isCovered, rows, cols)) {
            printResults(foundCrosses);
        } else {
            System.out.println("-1");
        }
    }

    /**
     * Calculates the maximum expansion radius of a cross centered at (r, c).
     * A cross is valid if the center and all four arms at distance k are stars.
     */
    private static int calculateMaxRadius(char[][] grid, int r, int c, int rows, int cols) {
        int k = 1;
        while (true) {
            // Check if expanding further would go out of bounds
            if (r - k < 0 || r + k >= rows || c - k < 0 || c + k >= cols) {
                break;
            }
            // Check if any of the four cardinal directions at distance k hit an empty space
            if (grid[r - k][c] == '.' || grid[r + k][c] == '.' ||
                grid[r][c - k] == '.' || grid[r][c + k] == '.') {
                break;
            }
            k++;
        }
        // Return the last successful distance
        return k - 1;
    }

    /**
     * Marks all cells part of the cross (center and arms) as covered.
     */
    private static void markAsCovered(boolean[][] isCovered, int r, int c, int radius) {
        isCovered[r][c] = true;
        for (int k = 1; k <= radius; k++) {
            isCovered[r - k][c] = true;
            isCovered[r + k][c] = true;
            isCovered[r][c - k] = true;
            isCovered[r][c + k] = true;
        }
    }

    /**
     * Verifies that every '*' in the original grid has been marked as covered.
     */
    private static boolean checkAllStarsCovered(char[][] grid, boolean[][] isCovered, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*' && !isCovered[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Formats and prints the list of found crosses.
     */
    private static void printResults(List<Cross> crosses) {
        System.out.println(crosses.size());
        for (Cross cross : crosses) {
            System.out.println(cross);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solution to find if a grid of marked cells can be perfectly covered 
 * by a set of plus-shaped patterns.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = reader.nextInt();
            int m = reader.nextInt();

            GridSolver solver = new GridSolver(n, m);
            solver.solve(reader, out);
        } catch (Exception e) {
            // Handle potential input errors
        } finally {
            out.close();
        }
    }

    /**
     * Represents a plus-shaped pattern with a center and four arms of equal length.
     */
    static class PlusSign {
        final int row;
        final int col;
        final int armLength;

        PlusSign(int row, int col, int armLength) {
            this.row = row;
            this.col = col;
            this.armLength = armLength;
        }

        @Override
        public String toString() {
            // Convert to 1-based indexing for output
            return String.format("%d %d %d", row + 1, col + 1, armLength);
        }
    }

    /**
     * Handles the core logic of the grid problem.
     */
    static class GridSolver {
        private final int rows;
        private final int cols;
        private final boolean[][] grid;

        public GridSolver(int rows, int cols) {
            this.rows = rows;
            this.cols = cols;
            this.grid = new boolean[rows][cols];
        }

        public void solve(FastReader reader, PrintWriter out) throws IOException {
            List<int[]> markedCells = new ArrayList<>();

            // 1. Read the grid
            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                for (int j = 0; j < cols; j++) {
                    if (line.charAt(j) == '#') {
                        grid[i][j] = true;
                        markedCells.add(new int[]{i, j});
                    }
                }
            }

            // 2. Find potential plus signs centered at every marked cell
            List<PlusSign> solutions = findPotentialPlusSigns(markedCells);

            // 3. Verify if these plus signs cover exactly the marked cells
            if (isCoverageValid(solutions)) {
                out.println(solutions.size());
                for (PlusSign sign : solutions) {
                    out.println(sign);
                }
            } else {
                out.println("-1");
            }
        }

        private List<PlusSign> findPotentialPlusSigns(List<int[]> markedCells) {
            List<PlusSign> solutions = new ArrayList<>();
            for (int[] cell : markedCells) {
                int r = cell[0];
                int c = cell[1];
                int maxArm = calculateMaxArmLength(r, c);

                // Based on original logic, we only consider plus signs with arm length > 0
                if (maxArm > 0) {
                    solutions.add(new PlusSign(r, c, maxArm));
                }
            }
            return solutions;
        }

        private int calculateMaxArmLength(int r, int c) {
            int arm = 0;
            while (true) {
                int nextArm = arm + 1;
                if (isWithinBounds(r, c, nextArm) && 
                    grid[r - nextArm][c] && grid[r + nextArm][c] && 
                    grid[r][c - nextArm] && grid[r][c + nextArm]) {
                    arm = nextArm;
                } else {
                    break;
                }
            }
            return arm;
        }

        private boolean isWithinBounds(int r, int c, int dist) {
            return (r - dist >= 0) && (r + dist < rows) && 
                   (c - dist >= 0) && (c + dist < cols);
        }

        private boolean isCoverageValid(List<PlusSign> solutions) {
            boolean[][] coverageMap = new boolean[rows][cols];

            for (PlusSign sign : solutions) {
                coverageMap[sign.row][sign.col] = true;
                for (int k = 1; k <= sign.armLength; k++) {
                    coverageMap[sign.row + k][sign.col] = true;
                    coverageMap[sign.row - k][sign.col] = true;
                    coverageMap[sign.row][sign.col + k] = true;
                    coverageMap[sign.row][sign.col - k] = true;
                }
            }

            // Check if the coverage exactly matches the original grid
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] != coverageMap[i][j]) {
                        return false;
                    }
                }
            }
            return true;
        }
    }

    /**
     * Efficient reader for large inputs.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A solution to the Cross Coverage problem.
 * The goal is to cover all '*' cells in a grid using the minimum number of 
 * cross-shaped patterns through a greedy approach.
 */
public class CrossCoverageProblem {

    /**
     * Represents a cross pattern placed on the grid.
     * @param row The 1-based row index of the center.
     * @param col The 1-based column index of the center.
     * @param size The radius of the cross.
     */
    public record Cross(int row, int col, int size) {
        @Override
        public String toString() {
            return row + " " + col + " " + size;
        }
    }

    /**
     * A high-performance input reader.
     */
    public static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /**
     * Logic for solving the cross coverage problem.
     */
    public static class CrossCoverageSolver {
        private final int rowCount;
        private final int colCount;
        private final char[][] grid;
        private final boolean[][] isCovered;
        private final boolean[][] isCenter;

        // Precomputed distances of consecutive '*' in four directions
        private final int[][] consecutiveStarsUp;
        private final int[][] consecutiveStarsDown;
        private final int[][] consecutiveStarsLeft;
        private final int[][] consecutiveStarsRight;

        public CrossCoverageSolver(int rows, int cols, String[] inputGrid) {
            this.rowCount = rows;
            this.colCount = cols;
            this.grid = new char[rows][cols];
            this.isCovered = new boolean[rows][cols];
            this.isCenter = new boolean[rows][cols];

            this.consecutiveStarsUp = new int[rows][cols];
            this.consecutiveStarsDown = new int[rows][cols];
            this.consecutiveStarsLeft = new int[rows][cols];
            this.consecutiveStarsRight = new int[rows][cols];

            for (int i = 0; i < rows; i++) {
                grid[i] = inputGrid[i].toCharArray();
            }
            precomputeDirections();
        }

        private void precomputeDirections() {
            // Forward pass: Up and Left
            for (int r = 0; r < rowCount; r++) {
                for (int c = 0; c < colCount; c++) {
                    if (grid[r][c] == '*') {
                        consecutiveStarsUp[r][c] = 1 + (r > 0 ? consecutiveStarsUp[r - 1][c] : 0);
                        consecutiveStarsLeft[r][c] = 1 + (c > 0 ? consecutiveStarsLeft[r][c - 1] : 0);
                    }
                }
            }

            // Backward pass: Down and Right
            for (int r = rowCount - 1; r >= 0; r--) {
                for (int c = colCount - 1; c >= 0; c--) {
                    if (grid[r][c] == '*') {
                        consecutiveStarsDown[r][c] = 1 + (r + 1 < rowCount ? consecutiveStarsDown[r + 1][c] : 0);
                        consecutiveStarsRight[r][c] = 1 + (c + 1 < colCount ? consecutiveStarsRight[r][c + 1] : 0);
                    }
                }
            }
        }

        /**
         * Executes the greedy strategy to place crosses.
         * @return A list of placed Crosses, or null if coverage is impossible.
         */
        public List<Cross> solve() {
            List<Cross> placedCrosses = new ArrayList<>();
            int maxPossibleSize = Math.min((rowCount - 1) / 2, (colCount - 1) / 2);

            // Greedy: Try placing the largest possible crosses first
            for (int size = maxPossibleSize; size >= 1; size--) {
                for (int r = 0; r < rowCount; r++) {
                    for (int c = 0; c < colCount; c++) {
                        if (grid[r][c] == '*' && !isCenter[r][c]) {
                            if (canPlaceCross(r, c, size)) {
                                placeCross(r, c, size, placedCrosses);
                            }
                        }
                    }
                }
            }

            if (allStarsCovered()) {
                return placedCrosses;
            } else {
                return null;
            }
        }

        private boolean canPlaceCross(int r, int c, int size) {
            int requiredLength = size + 1;
            return consecutiveStarsUp[r][c] >= requiredLength &&
                   consecutiveStarsDown[r][c] >= requiredLength &&
                   consecutiveStarsLeft[r][c] >= requiredLength &&
                   consecutiveStarsRight[r][c] >= requiredLength;
        }

        private void placeCross(int r, int c, int size, List<Cross> placedCrosses) {
            isCenter[r][c] = true;
            isCovered[r][c] = true;
            placedCrosses.add(new Cross(r + 1, c + 1, size));

            for (int offset = 1; offset <= size; offset++) {
                isCovered[r + offset][c] = true;
                isCovered[r - offset][c] = true;
                isCovered[r][c + offset] = true;
                isCovered[r][c - offset] = true;
            }
        }

        private boolean allStarsCovered() {
            for (int r = 0; r < rowCount; r++) {
                for (int c = 0; c < colCount; c++) {
                    if (grid[r][c] == '*' && !isCovered[r][c]) {
                        return false;
                    }
                }
            }
            return true;
        }
    }

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            String firstLine = reader.next();
            if (firstLine == null) return;

            int m = Integer.parseInt(firstLine);
            int n = reader.nextInt();

            String[] gridInput = new String[m];
            for (int i = 0; i < m; i++) {
                gridInput[i] = reader.next();
            }

            CrossCoverageSolver solver = new CrossCoverageSolver(m, n, gridInput);
            List<Cross> results = solver.solve();

            if (results != null) {
                out.println(results.size());
                for (Cross cross : results) {
                    out.println(cross);
                }
            } else {
                out.println("-1");
            }
        } catch (Exception e) {
            // Handle or log exception
        } finally {
            out.close();
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * StarPatternSolver finds maximal star patterns in a grid of characters.
 * A star is defined by a center point and four arms of equal length forming a cross.
 * The program ensures that every '*' character in the grid is part of at least one star's pattern.
 */
public class StarPatternSolver {

    /**
     * Represents a star pattern found in the grid.
     */
    private static class Star {
        private final int row;
        private final int col;
        private final int radius;

        public Star(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }

        @Override
        public String toString() {
            return row + " " + col + " " + radius;
        }
    }

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            String firstLine = reader.readLine();
            if (firstLine == null || firstLine.trim().isEmpty()) {
                return;
            }

            // Parse grid dimensions
            String[] dimensions = firstLine.trim().split("\\s+");
            int rows = Integer.parseInt(dimensions[0]);
            int cols = Integer.parseInt(dimensions[1]);

            char[][] grid = new char[rows][cols];
            boolean[][] isCovered = new boolean[rows][cols];

            // Initialize grid and coverage tracking
            for (int i = 0; i < rows; i++) {
                String line = reader.readLine();
                if (line == null) break;

                // Remove spaces to handle both "###" and "# # #" input formats
                String cleanedLine = line.replace(" ", "");
                for (int j = 0; j < cols && j < cleanedLine.length(); j++) {
                    grid[i][j] = cleanedLine.charAt(j);
                    if (grid[i][j] == '*') {
                        isCovered[i][j] = false; // '*' cells are not covered by default
                    } else {
                        isCovered[i][j] = true;  // Non-star cells are considered "covered"
                    }
                }
            }

            List<Star> stars = new ArrayList<>();

            // Search for star patterns. 
            // Stars must have a radius >= 1, so centers cannot be on the boundary.
            for (int r = 1; r < rows - 1; r++) {
                for (int c = 1; c < cols - 1; c++) {
                    if (grid[r][c] == '*') {
                        Star star = findStarAt(r, c, grid, isCovered, rows, cols);
                        if (star != null) {
                            stars.add(star);
                        }
                    }
                }
            }

            // Validate that all '*' cells have been covered by at least one star pattern
            if (areAllStarsCovered(grid, isCovered, rows, cols)) {
                out.println(stars.size());
                for (Star star : stars) {
                    out.println(star);
                }
            } else {
                out.println("-1");
            }

        } catch (IOException | NumberFormatException e) {
            // In a real-world scenario, use a proper logging framework here.
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Checks for a star pattern centered at (r, c) and marks the star's components as covered.
     * 
     * @param r The row index of the center.
     * @param c The column index of the center.
     * @param grid The character grid.
     * @param isCovered The coverage tracking array.
     * @param rows Total rows in grid.
     * @param cols Total columns in grid.
     * @return A Star object if a pattern of radius >= 1 is found, otherwise null.
     */
    private static Star findStarAt(int r, int c, char[][] grid, boolean[][] isCovered, int rows, int cols) {
        int radius = 0;
        int step = 1;

        // Expand outwards to find the maximum radius for this center
        while (r - step >= 0 && r + step < rows && c - step >= 0 && c + step < cols) {
            if (grid[r - step][c] == '*' &&
                grid[r + step][c] == '*' &&
                grid[r][c - step] == '*' &&
                grid[r][c + step] == '*') {

                // Mark the tips of the current radius layer as covered
                isCovered[r - step][c] = true;
                isCovered[r + step][c] = true;
                isCovered[r][c - step] = true;
                isCovered[r][c + step] = true;

                radius++;
                step++;
            } else {
                break;
            }
        }

        if (radius > 0) {
            isCovered[r][c] = true; // Mark the center as covered
            return new Star(r + 1, c + 1, radius); // Return 1-based coordinates
        }
        return null;
    }

    /**
     * Checks if every '*' cell in the grid has been marked as covered.
     */
    private static boolean areAllStarsCovered(char[][] grid, boolean[][] isCovered, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*' && !isCovered[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Fast I/O utility.
     */
    private static class FastReader {
        private final BufferedReader br;

        public FastReader(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        public String readLine() throws IOException {
            return br.readLine();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver for identifying and validating star-shaped patterns in a grid.
 * A star is defined as a cross-shaped pattern of '*' characters.
 */
public class StarPatternSolver {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        int height = scanner.nextInt();
        int width = scanner.nextInt();

        boolean[][] board = new boolean[width][height];
        for (int y = 0; y < height; y++) {
            String line = scanner.next();
            for (int x = 0; x < width; x++) {
                board[x][y] = (line.charAt(x) == '*');
            }
        }

        Solver solver = new Solver(width, height, board);
        solver.solve();
    }

    /**
     * Represents a star pattern found in the grid.
     */
    static class Star {
        final int x;
        final int y;
        final int armLength;

        Star(int x, int y, int armLength) {
            this.x = x;
            this.y = y;
            this.armLength = armLength;
        }
    }

    static class Solver {
        private final int width;
        private final int height;
        private final boolean[][] board;
        private final List<Star> stars = new ArrayList<>();

        public Solver(int width, int height, boolean[][] board) {
            this.width = width;
            this.height = height;
            this.board = board;
        }

        public void solve() {
            int[][] leftCount = new int[width][height];
            int[][] rightCount = new int[width][height];
            int[][] upCount = new int[width][height];
            int[][] downCount = new int[width][height];

            // Compute consecutive star counts in all 4 directions using DP
            for (int y = 0; y < height; y++) {
                for (int x = 0; x < width; x++) {
                    if (board[x][y]) {
                        leftCount[x][y] = (x > 0) ? leftCount[x - 1][y] + 1 : 1;
                        upCount[x][y] = (y > 0) ? upCount[x][y - 1] + 1 : 1;
                    }
                }
            }

            for (int y = height - 1; y >= 0; y--) {
                for (int x = width - 1; x >= 0; x--) {
                    if (board[x][y]) {
                        rightCount[x][y] = (x < width - 1) ? rightCount[x + 1][y] + 1 : 1;
                        downCount[x][y] = (y < height - 1) ? downCount[x][y + 1] + 1 : 1;
                    }
                }
            }

            // Use difference arrays to track coverage efficiently (O(W*H))
            int[][] vertDiff = new int[width][height + 1];
            int[][] horizDiff = new int[height][width + 1];

            for (int x = 0; x < width; x++) {
                for (int y = 0; y < height; y++) {
                    int minArm = Math.min(Math.min(leftCount[x][y], rightCount[x][y]),
                                          Math.min(upCount[x][y], downCount[x][y]));

                    // A valid star must have a radius >= 2 (center + at least 1 arm cell)
                    if (minArm >= 2) {
                        int arm = minArm - 1;
                        stars.add(new Star(x, y, arm));

                        // Mark vertical coverage for this column
                        vertDiff[x][y - arm]++;
                        vertDiff[x][y + arm + 1]--;

                        // Mark horizontal coverage for this row
                        horizDiff[y][x - arm]++;
                        horizDiff[y][x + arm + 1]--;
                    }
                }
            }

            boolean[][] painted = new boolean[width][height];

            // Apply prefix sums to resolve vertical segments
            for (int x = 0; x < width; x++) {
                int activeSegments = 0;
                for (int y = 0; y < height; y++) {
                    activeSegments += vertDiff[x][y];
                    if (activeSegments > 0) painted[x][y] = true;
                }
            }

            // Apply prefix sums to resolve horizontal segments
            for (int y = 0; y < height; y++) {
                int activeSegments = 0;
                for (int x = 0; x < width; x++) {
                    activeSegments += horizDiff[y][x];
                    if (activeSegments > 0) painted[x][y] = true;
                }
            }

            // Validation: The set of stars must exactly match the original board
            for (int x = 0; x < width; x++) {
                for (int y = 0; y < height; y++) {
                    if (board[x][y] != painted[x][y]) {
                        System.out.println("-1");
                        return;
                    }
                }
            }

            printResults();
        }

        private void printResults() {
            PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
            out.println(stars.size());
            for (Star star : stars) {
                // Convert 0-indexed to 1-indexed for output: y x arm
                out.printf("%d %d %d\n", star.y + 1, star.x + 1, star.armLength);
            }
            out.flush();
            out.close();
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

/**
 * Solves the problem of covering all '*' cells in a grid using the minimum 
 * number of 'cross' shapes. A cross is defined by a center and four equal-length arms.
 */
public class CrossCoverageProblem {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            String[] gridRows = new String[rows];
            for (int i = 0; i < rows; i++) {
                gridRows[i] = reader.next();
            }

            GridSolver solver = new GridSolver(rows, cols, gridRows);
            solver.solve(writer);
        } catch (Exception e) {
            // In a real production environment, use a logging framework
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    /**
     * Represents a found cross with a center point and arm length.
     */
    static class Cross {
        int row, col, armLength;

        Cross(int row, int col, int armLength) {
            this.row = row;
            this.col = col;
            this.armLength = armLength;
        }

        @Override
        public String toString() {
            return (row + 1) + " " + (col + 1) + " " + armLength;
        }
    }

    static class GridSolver {
        private final int rows;
        private final int cols;
        private final boolean[][] isStar;
        private final List<Cross> foundCrosses = new ArrayList<>();

        public GridSolver(int rows, int cols, String[] gridRows) {
            this.rows = rows;
            this.cols = cols;
            this.isStar = new boolean[rows][cols];
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (gridRows[i].charAt(j) == '*') {
                        isStar[i][j] = true;
                    }
                }
            }
        }

        public void solve(PrintWriter writer) {
            int[][] up = computeConsecutive(true, true);
            int[][] down = computeConsecutive(true, false);
            int[][] left = computeConsecutive(false, true);
            int[][] right = computeConsecutive(false, false);

            // Difference arrays for verifying coverage
            // verticalDiff tracks vertical segments in a specific column
            int[][] verticalDiff = new int[rows + 1][cols];
            // horizontalDiff tracks horizontal segments in a specific row
            int[][] horizontalDiff = new int[rows][cols + 1];

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (isStar[i][j]) {
                        // The arm length is the minimum distance to a non-star cell in any direction - 1
                        int armLength = Math.min(Math.min(Math.min(up[i][j], down[i][j]), 
                                                         Math.min(left[i][j], right[i][j])) - 1, 
                                                 Math.min(i, rows - 1 - i));

                        // Re-calculating s based on original logic: min of star counts in all 4 directions - 1
                        int s = Math.min(Math.min(Math.min(up[i][j], down[i][j]), 
                                                  Math.min(left[i][j], right[i][j])) - 1, 
                                         Math.min(j, cols - 1 - j));

                        if (s > 0) {
                            foundCrosses.add(new Cross(i, j, s));

                            // Mark vertical coverage using difference array
                            verticalDiff[i - s][j]++;
                            verticalDiff[i + s + 1][j]--;

                            // Mark horizontal coverage using difference array
                            horizontalDiff[i][j - s]++;
                            horizontalDiff[i][j + s + 1]--;
                        }
                    }
                }
            }

            if (verifyCoverage(verticalDiff, horizontalDiff)) {
                writer.println(foundCrosses.size());
                for (Cross cross : foundCrosses) {
                    writer.println(cross.toString());
                }
            } else {
                writer.println("-1");
            }
        }

        /**
         * Computes consecutive star counts in a specific direction.
         * @param vertical If true, computes Up/Down; otherwise Left/Right.
         * @param forward If true, computes from start to end; otherwise end to start.
         */
        private int[][] computeConsecutive(boolean vertical, boolean forward) {
            int[][] counts = new int[rows][cols];
            if (vertical) {
                if (forward) { // Up
                    for (int j = 0; j < cols; j++) {
                        for (int i = 0; i < rows; i++) {
                            counts[i][j] = isStar[i][j] ? (i == 0 ? 1 : counts[i - 1][j] + 1) : 0;
                        }
                    }
                } else { // Down
                    for (int j = 0; j < cols; j++) {
                        for (int i = rows - 1; i >= 0; i--) {
                            counts[i][j] = isStar[i][j] ? (i == rows - 1 ? 1 : counts[i + 1][j] + 1) : 0;
                        }
                    }
                }
            } else {
                if (forward) { // Left
                    for (int i = 0; i < rows; i++) {
                        for (int j = 0; j < cols; j++) {
                            counts[i][j] = isStar[i][j] ? (j == 0 ? 1 : counts[i][j - 1] + 1) : 0;
                        }
                    }
                } else { // Right
                    for (int i = 0; i < rows; i++) {
                        for (int j = cols - 1; j >= 0; j--) {
                            counts[i][j] = isStar[i][j] ? (j == cols - 1 ? 1 : counts[i][j + 1] + 1) : 0;
                        }
                    }
                }
            }
            return counts;
        }

        private boolean verifyCoverage(int[][] vDiff, int[][] hDiff) {
            boolean[][] isCovered = new boolean[rows][cols];

            // Apply horizontal prefix sums
            for (int i = 0; i < rows; i++) {
                int currentCoverage = 0;
                for (int j = 0; j < cols; j++) {
                    currentCoverage += hDiff[i][j];
                    if (currentCoverage > 0) isCovered[i][j] = true;
                }
            }

            // Apply vertical prefix sums
            for (int j = 0; j < cols; j++) {
                int currentCoverage = 0;
                for (int i = 0; i < rows; i++) {
                    currentCoverage += vDiff[i][j];
                    if (currentCoverage > 0) isCovered[i][j] = true;
                }
            }

            // Check if every '*' is covered
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (isStar[i][j] && !isCovered[i][j]) {
                        return false;
                    }
                }
            }
            return true;
        }
    }

    /**
     * Utility class for fast I/O operations.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(java.io.InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * CrossCoverSolver solves the problem of covering all '*' cells in a grid
 * using the minimum number of "cross" shapes. A cross consists of a center 
 * cell and four arms of equal length.
 */
public class CrossCoverSolver {

    /**
     * Represents a cross shape found in the grid.
     */
    static class Cross {
        int row, col, armLength;

        Cross(int row, int col, int armLength) {
            this.row = row;
            this.col = col;
            this.armLength = armLength;
        }

        @Override
        public String toString() {
            // Convert 0-indexed to 1-indexed for output
            return (row + 1) + " " + (col + 1) + " " + armLength;
        }
    }

    public static void main(String[] args) {
        FastReader sc = new FastReader(System.in);
        PrintWriter pw = new PrintWriter(System.out);

        try {
            int rows = sc.nextInt();
            int cols = sc.nextInt();
            char[][] grid = new char[rows][cols];

            int starCount = 0;
            for (int i = 0; i < rows; i++) {
                String line = sc.nextLine();
                if (line == null) line = "";
                grid[i] = line.toCharArray();
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '*') {
                        starCount++;
                    }
                }
            }

            solve(rows, cols, grid, starCount, pw);

        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            pw.flush();
            pw.close();
        }
    }

    private static void solve(int rows, int cols, char[][] grid, int starCount, PrintWriter pw) {
        // If there are no stars, we need 0 crosses.
        if (starCount == 0) {
            pw.println(0);
            return;
        }

        // Pre-calculate consecutive stars in all 4 directions using DP
        int[][] up = new int[rows][cols];
        int[][] down = new int[rows][cols];
        int[][] left = new int[rows][cols];
        int[][] right = new int[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*') {
                    up[i][j] = (i > 0) ? up[i - 1][j] + 1 : 1;
                    left[i][j] = (j > 0) ? left[i][j - 1] + 1 : 1;
                }
            }
        }

        for (int i = rows - 1; i >= 0; i--) {
            for (int j = cols - 1; j >= 0; j--) {
                if (grid[i][j] == '*') {
                    down[i][j] = (i < rows - 1) ? down[i + 1][j] + 1 : 1;
                    right[i][j] = (j < cols - 1) ? right[i][j + 1] + 1 : 1;
                }
            }
        }

        List<Cross> foundCrosses = new ArrayList<>();
        boolean[][] isCovered = new boolean[rows][cols];

        // Identify all potential centers (cells that can form a cross with arm length >= 1)
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*') {
                    // Arm length is the minimum distance to a non-star cell in 4 directions minus the center
                    int arm = Math.min(Math.min(up[i][j], down[i][j]), 
                                       Math.min(left[i][j], right[i][j])) - 1;

                    if (arm >= 1) {
                        foundCrosses.add(new Cross(i, j, arm));
                        markCoverage(isCovered, i, j, arm);
                    }
                }
            }
        }

        // Validate if all stars are covered
        if (allStarsCovered(grid, isCovered, starCount)) {
            pw.println(foundCrosses.size());
            for (Cross cross : foundCrosses) {
                pw.println(cross.toString());
            }
        } else {
            // If stars exist but no valid crosses cover them, output -1
            pw.println(-1);
        }
    }

    private static void markCoverage(boolean[][] isCovered, int r, int c, int arm) {
        isCovered[r][c] = true;
        for (int i = 1; i <= arm; i++) {
            isCovered[r + i][c] = true;
            isCovered[r - i][c] = true;
            isCovered[r][c + i] = true;
            isCovered[r][c - i] = true;
        }
    }

    private static boolean allStarsCovered(char[][] grid, boolean[][] isCovered, int starCount) {
        int coveredStars = 0;
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[0].length; j++) {
                if (grid[i][j] == '*' && isCovered[i][j]) {
                    coveredStars++;
                }
            }
        }
        return coveredStars == starCount;
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream s) {
            br = new BufferedReader(new InputStreamReader(s));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public String nextLine() throws IOException {
            return br.readLine();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver for the Star Drawing problem.
 * The goal is to cover all '*' characters on a grid with 'star' shapes (crosses)
 * without overlapping any '.' characters.
 */
public class Main {

    public static void main(String[] args) {
        try (FastReader reader = new FastReader(System.in);
             PrintWriter writer = new PrintWriter(System.out)) {

            StarDrawingSolver solver = new StarDrawingSolver();
            solver.solve(reader, writer);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * Represents a star shape placed on the grid.
     * 
     * @param x      The row index of the center.
     * @param y      The column index of the center.
     * @param radius The reach of the star arms.
     */
    record Star(int x, int y, int radius) {}

    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            return next != null ? Integer.parseInt(next) : -1;
        }
    }

    static class StarDrawingSolver {

        public void solve(FastReader in, PrintWriter out) {
            int rows = in.nextInt();
            int cols = in.nextInt();
            if (rows == -1 || cols == -1) return;

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = in.next().toCharArray();
            }

            List<Star> placedStars = findStarPlacements(grid, rows, cols);

            if (isGridCleared(grid)) {
                out.println(placedStars.size());
                for (Star star : placedStars) {
                    // Convert 0-based indexing to 1-based indexing for output
                    out.printf("%d %d %d\n", star.x() + 1, star.y() + 1, star.radius());
                }
            } else {
                out.println("-1");
            }
        }

        /**
         * Greedily finds the largest possible stars to cover non-dot characters.
         */
        private List<Star> findStarPlacements(char[][] grid, int rows, int cols) {
            List<Star> stars = new ArrayList<>();
            int maxPossibleRadius = Math.max(rows, cols);

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    // If we find a character that needs covering (or is part of a star)
                    if (grid[r][c] != '.') {
                        // Try to place the largest possible star centered here
                        for (int radius = maxPossibleRadius; radius >= 1; radius--) {
                            if (canPlaceStar(grid, r, c, radius, rows, cols)) {
                                drawStar(grid, r, c, radius, '#');
                                stars.add(new Star(r, c, radius));
                                break;
                            }
                        }
                    }
                }
            }
            return stars;
        }

        /**
         * Validates if a star of the given radius can be placed at (centerX, centerY)
         * without hitting any '.' cells or going out of bounds.
         */
        private boolean canPlaceStar(char[][] grid, int centerX, int centerY, int radius, int rows, int cols) {
            // Check vertical arm
            for (int r = centerX - radius; r <= centerX + radius; r++) {
                if (r < 0 || r >= rows || grid[r][centerY] == '.') {
                    return false;
                }
            }
            // Check horizontal arm
            for (int c = centerY - radius; c <= centerY + radius; c++) {
                if (c < 0 || c >= cols || grid[centerX][c] == '.') {
                    return false;
                }
            }
            return true;
        }

        /**
         * Mutates the grid to reflect the placement of a star.
         */
        private void drawStar(char[][] grid, int centerX, int centerY, int radius, char symbol) {
            for (int r = centerX - radius; r <= centerX + radius; r++) {
                grid[r][centerY] = symbol;
            }
            for (int c = centerY - radius; c <= centerY + radius; c++) {
                grid[centerX][c] = symbol;
            }
        }

        /**
         * Checks if all original '*' characters have been covered (turned into '#').
         */
        private boolean isGridCleared(char[][] grid) {
            for (char[] row : grid) {
                for (char cell : row) {
                    if (cell == '*') {
                        return false;
                    }
                }
            }
            return true;
        }
    }
}

import java.util.*;

/**
 * Represents a star shape in the grid.
 * A star is defined by its center coordinates and its radius.
 */
class Star {
    private final int row;
    private final int col;
    private final int radius;

    public Star(int row, int col, int radius) {
        this.row = row;
        this.col = col;
        this.radius = radius;
    }

    public int getRow() { return row; }
    public int getCol() { return col; }
    public int getRadius() { return radius; }

    @Override
    public String toString() {
        // Convert back to 1-based indexing for output as per original requirement
        return (row + 1) + " " + (col + 1) + " " + radius;
    }
}

/**
 * Handles the logic of finding stars in a grid and verifying coverage.
 */
class StarSolver {
    private final int rows;
    private final int cols;
    private final char[][] grid;
    private static final char STAR_CHAR = '*';

    public StarSolver(char[][] grid) {
        this.grid = grid;
        this.rows = grid.length;
        this.cols = grid[0].length;
    }

    /**
     * Executes the star finding algorithm.
     * @return A list of Star objects, or null if the grid cannot be perfectly covered.
     */
    public List<Star> solve() {
        List<Star> stars = findMaximalStars();

        if (isAllStarsCovered(stars)) {
            return stars;
        } else {
            return null;
        }
    }

    /**
     * Iterates through the grid to find the largest possible star centered at each cell.
     */
    private List<Star> findMaximalStars() {
        List<Star> stars = new ArrayList<>();

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == STAR_CHAR) {
                    int maxRadius = calculateMaxRadius(r, c);
                    if (maxRadius > 0) {
                        stars.add(new Star(r, c, maxRadius));
                    }
                }
            }
        }
        return stars;
    }

    /**
     * Determines the maximum radius of a star centered at (r, c).
     */
    private int calculateMaxRadius(int r, int c) {
        int radius = 0;
        // Incrementally check if the next radius level is valid
        while (canExpand(r, c, radius + 1)) {
            radius++;
        }
        return radius;
    }

    /**
     * Checks if a star of a specific radius can be placed at (r, c).
     */
    private boolean canExpand(int r, int c, int radius) {
        // Check bounds
        if (r - radius < 0 || r + radius >= rows || c - radius < 0 || c + radius >= cols) {
            return false;
        }

        // Check the 4 tips of the cross at the new radius
        return grid[r - radius][c] == STAR_CHAR &&
               grid[r + radius][c] == STAR_CHAR &&
               grid[r][c - radius] == STAR_CHAR &&
               grid[r][c + radius] == STAR_CHAR;
    }

    /**
     * Verifies if every '*' in the grid is covered by at least one star.
     */
    private boolean isAllStarsCovered(List<Star> stars) {
        boolean[][] covered = new boolean[rows][cols];

        for (Star star : stars) {
            markStarCoverage(star, covered);
        }

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == STAR_CHAR && !covered[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    private void markStarCoverage(Star star, boolean[][] covered) {
        int r = star.getRow();
        int c = star.getCol();
        int rad = star.getRadius();

        covered[r][c] = true;
        for (int k = 1; k <= rad; k++) {
            covered[r - k][c] = true;
            covered[r + k][c] = true;
            covered[r][c - k] = true;
            covered[r][c + k] = true;
        }
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        scanner.nextLine(); // Consume the remaining newline

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String line = scanner.nextLine();
            for (int j = 0; j < m; j++) {
                grid[i][j] = line.charAt(j);
            }
        }

        StarSolver solver = new StarSolver(grid);
        List<Star> result = solver.solve();

        if (result == null) {
            System.out.println("-1");
        } else {
            System.out.println(result.size());
            for (Star star : result) {
                System.out.println(star);
            }
        }

        scanner.close();
    }
}

import java.util.*;
import java.io.*;

/**
 * Problem: Cover all '*' cells in a grid with the minimum number of 
 * plus-shaped patterns such that every '*' belongs to exactly one plus.
 * 
 * Complexity: 
 * Time: O(N * M * min(N, M)) in the worst case for selection, 
 *       though the DP is O(N * M).
 * Space: O(N * M) to store grid and auxiliary arrays.
 */
public class PlusShapeCoverer {

    // Represents a plus shape with a center (r, c) and arm length k
    static class Plus {
        int r, c, k;

        Plus(int r, int c, int k) {
            this.r = r;
            this.c = c;
            this.k = k;
        }

        @Override
        public String toString() {
            // Convert 0-indexed to 1-indexed for output
            return (r + 1) + " " + (c + 1) + " " + k;
        }
    }

    public static void main(String[] args) throws IOException {
        FastReader reader = new FastReader(System.in);

        int n = reader.nextInt();
        int m = reader.nextInt();
        char[][] grid = new char[n][m];
        int totalStars = 0;

        for (int i = 0; i < n; i++) {
            String line = reader.next();
            for (int j = 0; j < m; j++) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] == '*') {
                    totalStars++;
                }
            }
        }

        // 1. Precalculate the maximum possible radius (k) for each cell using DP
        int[][] maxK = calculateMaxRadii(grid, n, m);

        // 2. Greedily select plus shapes
        List<Plus> pluses = new ArrayList<>();
        boolean[][] isCovered = new boolean[n][m];
        int coveredStarsCount = 0;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                // If the cell is a candidate center and not yet covered
                if (maxK[i][j] > 0 && !isCovered[i][j]) {
                    int k = maxK[i][j];

                    // Check if this plus overlaps with any already covered cell
                    if (canPlacePlus(grid, isCovered, i, j, k)) {
                        pluses.add(new Plus(i, j, k));
                        // Mark cells as covered
                        coveredStarsCount += markAsCovered(isCovered, i, j, k);
                    }
                }
            }
        }

        // 3. Final Validation: Every star must be covered exactly once
        if (coveredStarsCount != totalStars) {
            System.out.println("-1");
        } else {
            System.out.println(pluses.size());
            for (Plus p : pluses) {
                System.out.println(p);
            }
        }
    }

    /**
     * Calculates the maximum radius k for each cell such that a plus fits.
     * k = min(consecutive stars up, down, left, right) - 1.
     */
    private static int[][] calculateMaxRadii(char[][] grid, int n, int m) {
        int[][] left = new int[n][m];
        int[][] right = new int[n][m];
        int[][] up = new int[n][m];
        int[][] down = new int[n][m];
        int[][] maxK = new int[n][m];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*') {
                    left[i][j] = (j > 0 ? left[i][j - 1] : 0) + 1;
                    up[i][j] = (i > 0 ? up[i - 1][j] : 0) + 1;
                }
            }
            for (int j = m - 1; j >= 0; j--) {
                if (grid[i][j] == '*') {
                    right[i][j] = (j < m - 1 ? right[i][j + 1] : 0) + 1;
                }
            }
        }

        for (int j = 0; j < m; j++) {
            for (int i = n - 1; i >= 0; i--) {
                if (grid[i][j] == '*') {
                    down[i][j] = (i < n - 1 ? down[i + 1][j] : 0) + 1;
                }
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*') {
                    maxK[i][j] = Math.min(Math.min(left[i][j], right[i][j]), 
                                          Math.min(up[i][j], down[i][j])) - 1;
                } else {
                    maxK[i][j] = -1;
                }
            }
        }
        return maxK;
    }

    /**
     * Verifies if the plus shape at (r, c) with radius k overlaps with already covered cells.
     */
    private static boolean canPlacePlus(char[][] grid, boolean[][] isCovered, int r, int c, int k) {
        if (isCovered[r][c]) return false;
        for (int d = 1; d <= k; d++) {
            if (isCovered[r - d][c] || isCovered[r + d][c] || 
                isCovered[r][c - d] || isCovered[r][c + d]) {
                return false;
            }
        }
        return true;
    }

    /**
     * Marks the cells of the plus shape as covered and returns the number of cells covered.
     */
    private static int markAsCovered(boolean[][] isCovered, int r, int c, int k) {
        isCovered[r][c] = true;
        int count = 1;
        for (int d = 1; d <= k; d++) {
            isCovered[r - d][c] = true;
            isCovered[r + d][c] = true;
            isCovered[r][c - d] = true;
            isCovered[r][c + d] = true;
            count += 4;
        }
        return count;
    }

    /**
     * Fast I/O helper class.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

/**
 * A solution to the Star Grid Covering problem.
 * The goal is to cover all '#' cells in a grid using the minimum number of "stars".
 * A star is defined by a center cell and four arms of equal radius extending in cardinal directions.
 */
public class Main {

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        StarCoveringSolver solver = new StarCoveringSolver(sc);
        solver.solve(out);

        out.close();
    }

    /**
     * Core logic for solving the star covering problem.
     */
    static class StarCoveringSolver {
        private final FastScanner scanner;
        private int rows;
        private int cols;
        private boolean[][] isTarget;
        private boolean[][] isCovered;

        public StarCoveringSolver(FastScanner scanner) {
            this.scanner = scanner;
        }

        /**
         * Executes the solving algorithm and prints the result to the provided PrintWriter.
         *
         * @param out The PrintWriter used to output the result.
         */
        public void solve(PrintWriter out) {
            rows = scanner.nextInt();
            cols = scanner.nextInt();

            isTarget = new boolean[rows][cols];
            isCovered = new boolean[rows][cols];

            // Initialize the grid based on input
            for (int i = 0; i < rows; i++) {
                String line = scanner.next();
                for (int j = 0; j < cols; j++) {
                    if (line.charAt(j) == '#') {
                        isTarget[i][j] = true;
                    }
                }
            }

            List<Star> foundStars = new ArrayList<>();

            // Greedy approach: For every target cell, if it can be a center of a star (radius > 0),
            // we create a star with the maximum possible radius.
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (isTarget[i][j]) {
                        int maxRadius = calculateMaxRadius(i, j);
                        if (maxRadius > 0) {
                            // Store star (using 1-based indexing for output as per original code)
                            foundStars.add(new Star(i + 1, j + 1, maxRadius));
                            markCoveredCells(i, j, maxRadius);
                        }
                    }
                }
            }

            // Verification: Ensure all '#' cells are covered
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (isTarget[i][j] && !isCovered[i][j]) {
                        out.println("-1");
                        return;
                    }
                }
            }

            // Output the number of stars and their details
            out.println(foundStars.size());
            for (Star star : foundStars) {
                out.println(star);
            }
        }

        /**
         * Calculates the maximum possible radius for a star centered at (r, c).
         * A star requires arms of equal length in all four directions.
         */
        private int calculateMaxRadius(int r, int c) {
            int up = 0, down = 0, left = 0, right = 0;

            // Check upwards
            for (int i = r - 1; i >= 0 && isTarget[i][c]; i--) {
                up++;
            }
            // Check downwards
            for (int i = r + 1; i < rows && isTarget[i][c]; i++) {
                down++;
            }
            // Check leftwards
            for (int j = c - 1; j >= 0 && isTarget[r][j]; j--) {
                left++;
            }
            // Check rightwards
            for (int j = c + 1; j < cols && isTarget[r][j]; j++) {
                right++;
            }

            return Math.min(Math.min(up, down), Math.min(left, right));
        }

        /**
         * Marks the center and all cells within the star's radius as covered.
         */
        private void markCoveredCells(int r, int c, int radius) {
            isCovered[r][c] = true; // Mark center
            for (int i = 1; i <= radius; i++) {
                isCovered[r - i][c] = true; // Up
                isCovered[r + i][c] = true; // Down
                isCovered[r][c - i] = true; // Left
                isCovered[r][c + i] = true; // Right
            }
        }
    }

    /**
     * Represents a star placement in the grid.
     */
    static class Star {
        final int row;
        final int col;
        final int radius;

        Star(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }

        @Override
        public String toString() {
            return row + " " + col + " " + radius;
        }
    }

    /**
     * Fast I/O utility for efficient reading of input.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the Cross-Shape Grid problem.
 * The goal is to identify all maximal crosses that perfectly reconstruct the given grid of stars.
 */
public class E501 {

    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int rows = in.nextInt();
            int cols = in.nextInt();
            boolean[][] board = new boolean[rows][cols];

            for (int i = 0; i < rows; i++) {
                String line = in.next();
                for (int j = 0; j < cols; j++) {
                    if (line.charAt(j) == '*') {
                        board[i][j] = true;
                    }
                }
            }

            GridSolver solver = new GridSolver(board);
            solver.solve(out);

        } catch (Exception e) {
            // In a production environment, use a logger
            out.println("-1");
        } finally {
            out.close();
        }
    }

    /**
     * Represents a cross shape found in the grid.
     */
    static class Cross {
        final int row;        // 1-based row index
        final int col;        // 1-based column index
        final int armLength;  // Length of the arms extending from the center

        public Cross(int row, int col, int armLength) {
            this.row = row;
            this.col = col;
            this.armLength = armLength;
        }

        @Override
        public String toString() {
            return row + " " + col + " " + armLength;
        }
    }

    /**
     * Handles the logic for finding and validating crosses within a grid.
     */
    static class GridSolver {
        private final boolean[][] board;
        private final int rows;
        private final int cols;

        public GridSolver(boolean[][] board) {
            this.board = board;
            this.rows = board.length;
            this.cols = board[0].length;
        }

        public void solve(PrintWriter out) {
            List<Cross> crosses = findCrosses();

            if (isReconstructionValid(crosses)) {
                out.println(crosses.size());
                for (Cross cross : crosses) {
                    out.println(cross);
                }
            } else {
                out.println("-1");
            }
        }

        /**
         * Finds all maximal crosses in the grid using dynamic programming.
         */
        private List<Cross> findCrosses() {
            int[][] upArms = new int[rows][cols];
            int[][] leftArms = new int[rows][cols];
            int[][] downArms = new int[rows][cols];
            int[][] rightArms = new int[rows][cols];

            // Calculate arms in top and left directions
            for (int i = 1; i < rows - 1; i++) {
                for (int j = 1; j < cols - 1; j++) {
                    if (board[i][j]) {
                        if (board[i - 1][j]) upArms[i][j] = upArms[i - 1][j] + 1;
                        if (board[i][j - 1]) leftArms[i][j] = leftArms[i][j - 1] + 1;
                    }
                }
            }

            // Calculate arms in bottom and right directions
            for (int i = rows - 2; i >= 1; i--) {
                for (int j = cols - 2; j >= 1; j--) {
                    if (board[i][j]) {
                        if (board[i + 1][j]) downArms[i][j] = downArms[i + 1][j] + 1;
                        if (board[i][j + 1]) rightArms[i][j] = rightArms[i][j + 1] + 1;
                    }
                }
            }

            List<Cross> crosses = new ArrayList<>();
            for (int i = 1; i < rows - 1; i++) {
                for (int j = 1; j < cols - 1; j++) {
                    // The arm length is the minimum of the four directions
                    int minArm = Math.min(Math.min(upArms[i][j], leftArms[i][j]),
                                          Math.min(downArms[i][j], rightArms[i][j]));

                    if (minArm > 0) {
                        // Convert to 1-based indexing for the requirement
                        crosses.add(new Cross(i + 1, j + 1, minArm));
                    }
                }
            }
            return crosses;
        }

        /**
         * Verifies if the set of found crosses exactly matches the original board.
         */
        private boolean isReconstructionValid(List<Cross> crosses) {
            boolean[][] reconstructed = new boolean[rows][cols];

            for (Cross cross : crosses) {
                int r = cross.row - 1; // Back to 0-based
                int c = cross.col - 1;
                int len = cross.armLength;

                reconstructed[r][c] = true;
                for (int i = 1; i <= len; i++) {
                    reconstructed[r - i][c] = true;
                    reconstructed[r + i][c] = true;
                    reconstructed[r][c - i] = true;
                    reconstructed[r][c + i] = true;
                }
            }

            // Check if reconstructed grid matches original board
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (board[i][j] != reconstructed[i][j]) {
                        return false;
                    }
                }
            }
            return true;
        }
    }

    /**
     * High-performance scanner for reading input.
     */
    public static class FastScanner {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public FastScanner(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (numChars == -1) throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) return -1;
            }
            return buf[curChar++];
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to solve the Star Painting problem.
 * Identifies cross-shaped star patterns in a grid and attempts to cover all stars.
 */
public class StarPainting {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            if (rows <= 0 || cols <= 0) {
                writer.close();
                return;
            }

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }

            StarSolver solver = new StarSolver(rows, cols, grid);
            StarSolver.Result result = solver.solve();

            if (result.isSuccessful()) {
                writer.println(result.getCount());
                for (StarSolver.Star star : result.getStars()) {
                    writer.println(star);
                }
            } else {
                writer.println("-1");
            }
        } catch (Exception e) {
            // In a production environment, use a logger
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Encapsulates the logic for finding and "painting" stars in the grid.
     */
    static class StarSolver {
        private final int rows;
        private final int cols;
        private final char[][] grid;

        public StarSolver(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
        }

        /**
         * Represents a star found in the grid.
         */
        public static class Star {
            private final int r, c, size;

            public Star(int r, int c, int size) {
                this.r = r;
                this.c = c;
                this.size = size;
            }

            @Override
            public String toString() {
                return r + " " + c + " " + size;
            }
        }

        /**
         * Encapsulates the result of the solver.
         */
        public static class Result {
            private final int count;
            private final List<Star> stars;
            private final boolean success;

            public Result(int count, List<Star> stars, boolean success) {
                this.count = count;
                this.stars = stars;
                this.success = success;
            }

            public int getCount() { return count; }
            public List<Star> getStars() { return stars; }
            public boolean isSuccessful() { return success; }
        }

        /**
         * Executes the star finding and painting algorithm.
         * @return A Result object containing the star count, list of stars, and success status.
         */
        public Result solve() {
            int[][] leftCounts = new int[rows][cols];
            int[][] rightCounts = new int[rows][cols];
            int[][] topCounts = new int[rows][cols];
            int[][] bottomCounts = new int[rows][cols];

            precalculateDirectionalCounts(leftCounts, rightCounts, topCounts, bottomCounts);

            List<Star> foundStars = new ArrayList<>();
            int starCount = 0;

            // Iterate through the grid, skipping boundaries as stars need 1-cell radius
            for (int i = 1; i < rows - 1; i++) {
                for (int j = 1; j < cols - 1; j++) {
                    int l = leftCounts[i][j];
                    int r = rightCounts[i][j];
                    int t = topCounts[i][j];
                    int b = bottomCounts[i][j];

                    // A star center must have at least one '*' in all four directions
                    if (l > 0 && r > 0 && t > 0 && b > 0) {
                        int size = Math.min(Math.min(l, r), Math.min(t, b));

                        // The problem uses 1-based indexing for output
                        foundStars.add(new Star(i + 1, j + 1, size));
                        starCount++;

                        applyStarPainting(i, j, size);
                    }
                }
            }

            if (isGridFullyCovered()) {
                return new Result(starCount, foundStars, true);
            } else {
                return new Result(0, null, false);
            }
        }

        private void precalculateDirectionalCounts(int[][] left, int[][] right, int[][] top, int[][] bottom) {
            // Pre-calculate continuous '*' counts in all 4 directions
            for (int i = 0; i < rows; i++) {
                for (int j = 1; j < cols; j++) {
                    if (grid[i][j] == '*' && grid[i][j - 1] == '*') {
                        left[i][j] = left[i][j - 1] + 1;
                    }
                }
                for (int j = cols - 2; j >= 0; j--) {
                    if (grid[i][j] == '*' && grid[i][j + 1] == '*') {
                        right[i][j] = right[i][j + 1] + 1;
                    }
                }
            }

            for (int j = 0; j < cols; j++) {
                for (int i = 1; i < rows; i++) {
                    if (grid[i][j] == '*' && grid[i - 1][j] == '*') {
                        top[i][j] = top[i - 1][j] + 1;
                    }
                }
                for (int i = rows - 2; i >= 0; i--) {
                    if (grid[i][j] == '*' && grid[i + 1][j] == '*') {
                        bottom[i][j] = bottom[i + 1][j] + 1;
                    }
                }
            }
        }

        private void applyStarPainting(int r, int c, int size) {
            // Mark the vertical arm of the star as covered
            for (int k = r - size; k <= r + size; k++) {
                grid[k][c] = '.';
            }
            // Mark the horizontal arm of the star as covered
            for (int k = c - size; k <= c + size; k++) {
                grid[r][k] = '.';
            }
        }

        private boolean isGridFullyCovered() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '*') return false;
                }
            }
            return true;
        }
    }

    /**
     * Fast I/O utility for efficient reading.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

/**
 * A program to find the maximum possible "plus" signs (crosses) 
 * that cover all star cells in a grid.
 */
public class Main {

    public static void main(String[] args) {
        try {
            Application app = new Application();
            app.run();
        } catch (IOException e) {
            System.err.println("An error occurred during execution: " + e.getMessage());
        }
    }
}

/**
 * Represents a single cross found in the grid.
 */
record Cross(int centerX, int centerY, int radius) {
    @Override
    public String toString() {
        // Converting to 1-based indexing for output
        return String.format("%d %d %d", centerX + 1, centerY + 1, radius);
    }
}

/**
 * Orchestrates the reading, solving, and writing processes.
 */
class Application {
    private final FastReader reader;
    private final PrintWriter writer;

    Application() {
        this.reader = new FastReader(System.in);
        this.writer = new PrintWriter(System.out);
    }

    public void run() throws IOException {
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        boolean[][] grid = new boolean[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = reader.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = (line.charAt(j) == '*');
            }
        }

        CrossFinder finder = new CrossFinder(rows, cols, grid);
        List<Cross> solution = finder.findCrosses();

        if (solution == null) {
            writer.println("-1");
        } else {
            writer.println(solution.size());
            for (Cross cross : solution) {
                writer.println(cross.toString());
            }
        }

        writer.flush();
        writer.close();
    }
}

/**
 * Contains the logic to calculate the optimal crosses.
 */
class CrossFinder {
    private final int rows;
    private final int cols;
    private final boolean[][] isStar;
    private final boolean[][] isCovered;

    CrossFinder(int rows, int cols, boolean[][] isStar) {
        this.rows = rows;
        this.cols = cols;
        this.isStar = isStar;
        this.isCovered = new boolean[rows][cols];
    }

    /**
     * Iterates through the grid to find crosses and ensures all stars are covered.
     * @return A list of crosses, or null if not all stars can be covered.
     */
    public List<Cross> findCrosses() {
        List<Cross> crosses = new ArrayList<>();

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (isStar[r][c]) {
                    int radius = calculateMaxRadiusAt(r, c);
                    if (radius > 0) {
                        crosses.add(new Cross(r, c, radius));
                        markCellsCovered(r, c, radius);
                    }
                }
            }
        }

        if (areAllStarsCovered()) {
            return crosses;
        } else {
            return null;
        }
    }

    /**
     * Checks how far a cross can expand from the given center.
     */
    private int calculateMaxRadiusAt(int r, int c) {
        int radius = 1;
        while (canExpand(r, c, radius)) {
            radius++;
        }
        return radius - 1;
    }

    private boolean canExpand(int r, int c, int radius) {
        return (r - radius >= 0 && r + radius < rows &&
                c - radius >= 0 && c + radius < cols &&
                isStar[r - radius][c] && isStar[r + radius][c] &&
                isStar[r][c - radius] && isStar[r][c + radius]);
    }

    /**
     * Marks the center and the arms of the cross as covered.
     */
    private void markCellsCovered(int r, int c, int radius) {
        isCovered[r][c] = true;
        for (int i = 1; i <= radius; i++) {
            isCovered[r - i][c] = true;
            isCovered[r + i][c] = true;
            isCovered[r][c - i] = true;
            isCovered[r][c + i] = true;
        }
    }

    private boolean areAllStarsCovered() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (isStar[r][c] && !isCovered[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }
}

/**
 * Utility class for fast input parsing.
 */
class FastReader {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    public FastReader(InputStream input) {
        reader = new BufferedReader(new InputStreamReader(input));
    }

    public String next() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreElements()) {
            String line = reader.readLine();
            if (line == null) return null;
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    public int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    public long nextLong() throws IOException {
        return Long.parseLong(next());
    }

    public double nextDouble() throws IOException {
        return Double.parseDouble(next().replace(',', '.'));
    }
}

import java.io.*;
import java.util.*;

/**
 * Represents a star pattern found in the grid.
 */
class Star {
    private final int row;
    private final int col;
    private final int radius;

    public Star(int row, int col, int radius) {
        this.row = row;
        this.col = col;
        this.radius = radius;
    }

    @Override
    public String toString() {
        // Returns 1-indexed coordinates and radius for output requirements
        return String.format("%d %d %d", row + 1, col + 1, radius);
    }
}

/**
 * Represents the game board/grid.
 */
class Grid {
    private final int rows;
    private final int cols;
    private final char[][] cells;
    private final boolean[][] covered;
    private int totalStarsCount = 0;

    public Grid(int rows, int cols) {
        this.rows = rows;
        this.cols = cols;
        this.cells = new char[rows][cols];
        this.covered = new boolean[rows][cols];
    }

    public void setCell(int r, int c, char value) {
        cells[r][c] = value;
        if (value == '*') {
            totalStarsCount++;
        }
    }

    public char getCell(int r, int c) {
        return cells[r][c];
    }

    public void markCovered(int r, int c) {
        covered[r][c] = true;
    }

    public boolean isCovered(int r, int c) {
        return covered[r][c];
    }

    public int getRows() { return rows; }
    public int getCols() { return cols; }
    public int getTotalStarsCount() { return totalStarsCount; }

    /**
     * Validates if a cell is within bounds.
     */
    public boolean isInBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

/**
 * Contains the core logic to solve the star pattern problem.
 */
class StarSolver {
    private final Grid grid;
    private final List<Star> foundStars;

    public StarSolver(Grid grid) {
        this.grid = grid;
        this.foundStars = new ArrayList<>();
    }

    /**
     * Executes the search for stars and verifies coverage.
     * @return A list of stars if all '*' are covered, otherwise null.
     */
    public List<Star> solve() {
        for (int r = 1; r < grid.getRows() - 1; r++) {
            for (int c = 1; c < grid.getCols() - 1; c++) {
                if (grid.getCell(r, c) == '*') {
                    int maxRadius = findMaximalRadius(r, c);
                    if (maxRadius >= 1) {
                        Star star = new Star(r, c, maxRadius);
                        foundStars.add(star);
                        markStarCellsAsCovered(r, c, maxRadius);
                    }
                }
            }
        }

        if (allStarsCovered()) {
            return foundStars;
        } else {
            return null;
        }
    }

    private int findMaximalRadius(int centerR, int centerC) {
        int radius = 0;
        // A star must have at least radius 1 to be considered based on original logic
        while (canExpand(centerR, centerC, radius + 1)) {
            radius++;
        }
        return radius;
    }

    private boolean canExpand(int r, int c, int radius) {
        return grid.isInBounds(r + radius, c) &&
               grid.isInBounds(r - radius, c) &&
               grid.isInBounds(r, c + radius) &&
               grid.isInBounds(r, c - radius) &&
               grid.getCell(r + radius, c) == '*' &&
               grid.getCell(r - radius, c) == '*' &&
               grid.getCell(r, c + radius) == '*' &&
               grid.getCell(r, c - radius) == '*';
    }

    private void markStarCellsAsCovered(int r, int c, int radius) {
        for (int i = 0; i <= radius; i++) {
            grid.markCovered(r + i, c);
            grid.markCovered(r - i, c);
            grid.markCovered(r, c + i);
            grid.markCovered(r, c - i);
        }
    }

    private boolean allStarsCovered() {
        int coveredCount = 0;
        for (int r = 0; r < grid.getRows(); r++) {
            for (int c = 0; c < grid.getCols(); c++) {
                if (grid.getCell(r, c) == '*' && grid.isCovered(r, c)) {
                    coveredCount++;
                }
            }
        }
        return coveredCount == grid.getTotalStarsCount();
    }
}

/**
 * Main entry point for the application.
 */
public class E501 {
    public static void main(String[] args) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(System.out)) {

            String firstLine = reader.readLine();
