import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Scanner;

/**
 * A program to identify diamond-shaped patterns in a grid of characters.
 * It finds all possible maximal diamonds and verifies if they perfectly
 * reconstruct the original grid.
 */
public class DiamondGridSolver {

    /**
     * Represents a diamond pattern with a center coordinate and a radius.
     * 
     * @param row    The zero-based row index of the diamond's center.
     * @param col    The zero-based column index of the diamond's center.
     * @param radius The radius of the diamond.
     */
    public record Diamond(int row, int col, int radius) {
        @Override
        public String toString() {
            // Output format: 1-based row, 1-based col, radius
            return String.format("%d %d %d", row + 1, col + 1, radius);
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        char[][] grid = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            grid[i] = line.toCharArray();
        }

        DiamondSolver solver = new DiamondSolver(rows, cols, grid);
        List<Diamond> diamonds = solver.findDiamonds();

        if (solver.isValidReconstruction(diamonds)) {
            System.out.println(diamonds.size());
            for (Diamond diamond : diamonds) {
                System.out.println(diamond);
            }
        } else {
            System.out.println("-1");
        }

        scanner.close();
    }

    /**
     * Logic handler for finding and verifying diamond patterns.
     */
    private static class DiamondSolver {
        private final int rows;
        private final int cols;
        private final char[][] grid;

        public DiamondSolver(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
        }

        /**
         * Iterates through the grid to find all maximal diamond patterns.
         * 
         * @return A list of discovered Diamond patterns.
         */
        public List<Diamond> findDiamonds() {
            List<Diamond> diamonds = new ArrayList<>();

            // Diamonds must have a center and radius, so we skip the outer boundary cells
            for (int r = 1; r < rows - 1; r++) {
                for (int c = 1; c < cols - 1; c++) {
                    if (grid[r][c] == '*') {
                        int radius = calculateMaxRadius(r, c);
                        if (radius > 0) {
                            diamonds.add(new Diamond(r, c, radius));
                        }
                    }
                }
            }
            return diamonds;
        }

        /**
         * Calculates the maximum possible radius for a diamond centered at (r, c)
         * by expanding outwards in four directions.
         */
        private int calculateMaxRadius(int r, int c) {
            int radius = 0;
            while (true) {
                int nextRadius = radius + 1;
                int up = r - nextRadius;
                int down = r + nextRadius;
                int left = c - nextRadius;
                int right = c + nextRadius;

                // Ensure the expansion stays within the grid boundaries
                if (up < 0 || down >= rows || left < 0 || right >= cols) {
                    break;
                }

                // Check if the four points at the new radius are all '*'
                if (grid[up][c] == '*' && grid[down][c] == '*' &&
                    grid[r][left] == '*' && grid[r][right] == '*') {
                    radius = nextRadius;
                } else {
                    break;
                }
            }
            return radius;
        }

        /**
         * Reconstructs a grid using the found diamonds and compares it with the original.
         * 
         * @param diamonds The list of diamonds to use for reconstruction.
         * @return True if the reconstructed grid matches the input grid, false otherwise.
         */
        public boolean isValidReconstruction(List<Diamond> diamonds) {
            char[][] reconstructed = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                Arrays.fill(reconstructed[i], '.');
            }

            for (Diamond diamond : diamonds) {
                applyDiamondToGrid(reconstructed, diamond);
            }

            return compareGrids(grid, reconstructed);
        }

        /**
         * Draws the outline and center of a diamond onto the target grid.
         */
        private void applyDiamondToGrid(char[][] target, Diamond diamond) {
            target[diamond.row][diamond.col] = '*';
            for (int k = 0; k < diamond.radius; k++) {
                target[diamond.row - k - 1][diamond.col] = '*';
                target[diamond.row + k + 1][diamond.col] = '*';
                target[diamond.row][diamond.col - k - 1] = '*';
                target[diamond.row][diamond.col + k + 1] = '*';
            }
        }

        /**
         * Performs a cell-by-cell comparison between two grids.
         */
        private boolean compareGrids(char[][] original, char[][] reconstructed) {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (original[r][c] != reconstructed[r][c]) {
                        return false;
                    }
                }
            }
            return true;
        }
    }
}

