/**
 * A solution to identify a set of "cross" shapes that cover all '*' cells in a grid.
 * A cross is defined by its center position and a minimum arm length in all four directions.
 */
public class Main {
    public static void main(String[] args) {
        try {
            FastReader reader = new FastReader(System.in);
            PrintWriter out = new PrintWriter(System.out);

            // Read the number of test cases
            String tcInput = reader.next();
            if (tcInput != null) {
                int testCases = Integer.parseInt(tcInput);
                for (int i = 0; i < testCases; i++) {
                    GridCrossSolver solver = new GridCrossSolver(reader);
                    solver.solve(out);
                }
            }

            out.flush();
            out.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
