}

/**
 * Handles the business logic for processing the grid.
 */
class GridCrossSolver {
    private final FastReader reader;

    public GridCrossSolver(FastReader reader) {
        this.reader = reader;
    }

    /**
     * Represents a detected cross shape.
     */
    private static class Cross {
        final int row, col, size;

        Cross(int row, int col, int size) {
            this.row = row;
            this.col = col;
            this.size = size;
        }

        @Override
        public String toString() {
            return row + " " + col + " " + size;
        }
    }

    /**
     * Executes the core logic for a single test case.
     */
    public void solve(PrintWriter out) throws IOException {
        int rows = reader.nextInt();
        int cols = reader.nextInt();
        char[][] grid = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            grid[i] = reader.next().toCharArray();
        }

        boolean[][] isCovered = new boolean[rows][cols];
        List<Cross> foundCrosses = new ArrayList<>();

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*') {
                    int minArmLength = calculateMinArmLength(grid, i, j, rows, cols);

                    // If this asterisk can act as a center for a cross
                    if (minArmLength > 0) {
                        foundCrosses.add(new Cross(i + 1, j + 1, minArmLength));
                        markCrossAsCovered(isCovered, i, j, minArmLength);
                    }
                }
            }
        }

        if (checkIfAllStarsAreCovered(grid, isCovered, rows, cols)) {
            out.println(foundCrosses.size());
            for (Cross cross : foundCrosses) {
                out.println(cross);
            }
        } else {
            out.println("-1");
        }
    }

    /**
     * Calculates the minimum number of consecutive '*' in the four cardinal directions.
     */
    private int calculateMinArmLength(char[][] grid, int r, int c, int rows, int cols) {
        int up = 0, down = 0, left = 0, right = 0;

        // Up
        for (int k = r - 1; k >= 0; k--) {
            if (grid[k][c] == '*') up++;
            else break;
        }
        // Down
        for (int k = r + 1; k < rows; k++) {
            if (grid[k][c] == '*') down++;
            else break;
        }
        // Left
        for (int k = c - 1; k >= 0; k--) {
            if (grid[r][k] == '*') left++;
            else break;
        }
        // Right
        for (int k = c + 1; k < cols; k++) {
            if (grid[r][k] == '*') right++;
            else break;
        }

        return Math.min(Math.min(up, down), Math.min(left, right));
    }

    /**
     * Marks the cells covered by a cross in the boolean mask.
     */
    private void markCrossAsCovered(boolean[][] isCovered, int r, int c, int armLength) {
        isCovered[r][c] = true;
        for (int k = 1; k <= armLength; k++) {
            isCovered[r - k][c] = true;
            isCovered[r + k][c] = true;
            isCovered[r][c - k] = true;
            isCovered[r][c + k] = true;
        }
    }

    /**
     * Validates if every '*' in the original grid has been covered by at least one cross.
     */
    private boolean checkIfAllStarsAreCovered(char[][] grid, boolean[][] isCovered, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*' && !isCovered[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }
}

