import java.util.*;
import java.io.*;

/**
 * This program solves a grid coverage problem.
 * Given a grid of '*' (stars) and '.' (empty), it finds the largest possible 
 * cross-shaped covers (a center cell with equal arms in all four directions) 
 * such that every '*' cell is covered by at least one cross.
 */
public class Main {

    public static void main(String[] args) {
        new Main().run();
    }

    /**
     * Entry point for the application.
     */
    public void run() {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        String tStr = reader.next();
        if (tStr != null) {
            int testCases = Integer.parseInt(tStr);
            while (testCases-- > 0) {
                solve(reader, writer);
            }
        }

        writer.flush();
        writer.close();
    }

    /**
     * Processes a single test case.
     */
    private void solve(FastReader reader, PrintWriter writer) {
        int rows = reader.nextInt();
        int cols = reader.nextInt();
        char[][] grid = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            String line = reader.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
            }
        }

        // Step 1: Calculate the maximum possible arm length for a cross centered at each cell
        int[][] armLengths = calculateMaxArmLengths(grid, rows, cols);

        // Step 2: Use difference arrays to mark coverage for horizontal and vertical arms
        // horizontalDiff[row][col] handles coverage across a specific row
        int[][] horizontalDiff = new int[rows][cols + 1];
        // verticalDiff[col][row] handles coverage across a specific column
        int[][] verticalDiff = new int[cols][rows + 1];

        StringBuilder resultBuilder = new StringBuilder();
        int shapeCount = 0;

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int arm = armLengths[i][j];
                if (arm > 0) {
                    shapeCount++;
                    // Mark horizontal segment: [j - arm, j + arm]
                    horizontalDiff[i][j - arm]++;
                    horizontalDiff[i][j + arm + 1]--;

                    // Mark vertical segment: [i - arm, i + arm]
                    verticalDiff[j][i - arm]++;
                    verticalDiff[j][i + arm + 1]--;

                    resultBuilder.append(i + 1).append(" ")
                                 .append(j + 1).append(" ")
                                 .append(arm).append("\n");
                }
            }
        }

        // Step 3: Apply prefix sums to resolve the difference arrays into actual coverage counts
        int[][] rowCoverage = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            int currentCoverage = 0;
            for (int j = 0; j < cols; j++) {
                currentCoverage += horizontalDiff[i][j];
                rowCoverage[i][j] = currentCoverage;
            }
        }

        int[][] colCoverage = new int[rows][cols];
        for (int j = 0; j < cols; j++) {
            int currentCoverage = 0;
            for (int i = 0; i < rows; i++) {
                currentCoverage += verticalDiff[j][i];
                colCoverage[i][j] = currentCoverage;
            }
        }

        // Step 4: Verify if all '*' cells are covered by at least one horizontal or vertical arm
        boolean allStarsCovered = true;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*' && rowCoverage[i][j] == 0 && colCoverage[i][j] == 0) {
                    allStarsCovered = false;
                    break;
                }
            }
            if (!allStarsCovered) break;
        }

        if (!allStarsCovered) {
            writer.println("-1");
        } else {
            writer.println(shapeCount);
            writer.print(resultBuilder.toString());
        }
    }

    /**
     * Computes the maximum possible arm length for a cross centered at (i, j).
     * An arm length of 'k' means the cross spans from center-k to center+k.
     */
    private int[][] calculateMaxArmLengths(char[][] grid, int rows, int cols) {
        int[][] up = new int[rows][cols];
        int[][] down = new int[rows][cols];
        int[][] left = new int[rows][cols];
        int[][] right = new int[rows][cols];

        // Calculate Up and Left directions using DP
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*') {
                    up[i][j] = (i > 0 ? up[i - 1][j] : 0) + 1;
                    left[i][j] = (j > 0 ? left[i][j - 1] : 0) + 1;
                }
            }
        }

        // Calculate Down and Right directions using DP
        for (int i = rows - 1; i >= 0; i--) {
            for (int j = cols - 1; j >= 0; j--) {
                if (grid[i][j] == '*') {
                    down[i][j] = (i < rows - 1 ? down[i + 1][j] : 0) + 1;
                    right[i][j] = (j < cols - 1 ? right[i][j + 1] : 0) + 1;
                }
            }
        }

        int[][] armLengths = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*') {
                    // The maximum arm is the minimum of the four cardinal directions minus the center cell
                    int minConsecutive = Math.min(Math.min(up[i][j], down[i][j]), 
                                                  Math.min(left[i][j], right[i][j]));
                    armLengths[i][j] = Math.max(0, minConsecutive - 1);
                }
            }
        }
        return armLengths;
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * Problem: Detect stars (diamond shapes) in a grid and verify if their 
 * center-cross patterns perfectly match the provided '*' pattern.
 */
public class StarProblem {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        StarProblemSolver solver = new StarProblemSolver(reader, out);
        solver.solve();

        out.flush();
        out.close();
    }

    static class Star {
        final int col;
        final int row;
        final int radius;

        Star(int col, int row, int radius) {
            this.col = col;
            this.row = row;
            this.radius = radius;
        }
    }

    static class StarProblemSolver {
        private final FastReader reader;
        private final PrintWriter out;

        public StarProblemSolver(FastReader reader, PrintWriter out) {
            this.reader = reader;
            this.out = out;
        }

        public void solve() {
            int height = reader.nextInt(); // Number of rows
            int width = reader.nextInt();  // Number of columns

            boolean[][] grid = new boolean[width][height];
            for (int y = 0; y < height; y++) {
                String line = reader.next();
                for (int x = 0; x < width; x++) {
                    grid[x][y] = line.charAt(x) == '*';
                }
            }

            List<Star> stars = findStars(width, height, grid);

            if (isValid(width, height, grid, stars)) {
                out.println(stars.size());
                for (Star star : stars) {
                    // Output format: row col (radius - 1)
                    out.println((star.row + 1) + " " + (star.col + 1) + " " + (star.radius - 1));
                }
            } else {
                out.println("-1");
            }
        }

        private List<Star> findStars(int width, int height, boolean[][] grid) {
            int[][] left = computeDistances(width, height, grid, 1, 0);   // Left
            int[][] right = computeDistances(width, height, grid, -1, 0); // Right
            int[][] up = computeDistances(width, height, grid, 0, 1);    // Up
            int[][] down = computeDistances(width, height, grid, 0, -1); // Down

            List<Star> stars = new ArrayList<>();
            for (int x = 0; x < width; x++) {
                for (int y = 0; y < height; y++) {
                    if (grid[x][y]) {
                        int radius = Math.min(
                            Math.min(left[x][y], right[x][y]),
                            Math.min(up[x][y], down[x][y])
                        );
                        // A star requires at least a 3x3 diamond (radius 2)
                        if (radius >= 2) {
                            stars.add(new Star(x, y, radius));
                        }
                    }
                }
            }
            return stars;
        }

        /**
         * Computes consecutive '*' counts in a specific direction.
         */
        private int[][] computeDistances(int width, int height, boolean[][] grid, int dx, int dy) {
            int[][] dist = new int[width][height];

            // Determine iteration order based on direction to allow single-pass DP
            int startX = (dx <= 0) ? 0 : width - 1;
            int endX = (dx <= 0) ? width : -1;
            int stepX = (dx <= 0) ? 1 : -1;

            int startY = (dy <= 0) ? 0 : height - 1;
            int endY = (dy <= 0) ? height : -1;
            int stepY = (dy <= 0) ? 1 : -1;

            // For simplicity in this refactor, we use explicit loops per direction
            if (dx == 1 && dy == 0) { // Right
                for (int y = 0; y < height; y++) {
                    for (int x = width - 1; x >= 0; x--) {
                        if (grid[x][y]) dist[x][y] = (x == width - 1) ? 1 : 1 + dist[x + 1][y];
                    }
                }
            } else if (dx == -1 && dy == 0) { // Left
                for (int y = 0; y < height; y++) {
                    for (int x = 0; x < width; x++) {
                        if (grid[x][y]) dist[x][y] = (x == 0) ? 1 : 1 + dist[x - 1][y];
                    }
                }
            } else if (dx == 0 && dy == 1) { // Up (looking from top to bottom, so moving down y)
                // In original code, starLineUp[x][y] checks upwards (y-1)
                // This means we process from y=0 to height-1
                for (int x = 0; x < width; x++) {
                    for (int y = 0; y < height; y++) {
                        if (grid[x][y]) dist[x][y] = (y == 0) ? 1 : 1 + dist[x][y - 1];
                    }
                }
            } else if (dx == 0 && dy == -1) { // Down
                for (int x = 0; x < width; x++) {
                    for (int y = height - 1; y >= 0; y--) {
                        if (grid[x][y]) dist[x][y] = (y == height - 1) ? 1 : 1 + dist[x][y + 1];
                    }
                }
            }
            return dist;
        }

        private boolean isValid(int width, int height, boolean[][] grid, List<Star> stars) {
            boolean[][] covered = new boolean[width][height];

            for (Star s : stars) {
                // The original logic marks the "cross" formed by the star's bounding box 
                // (center row and center column within the bounding box radius).

                // Mark center column (vertical part of the cross)
                int yStart = s.row - s.radius + 1;
                int yEnd = s.row + s.radius - 1;
                for (int y = yStart; y <= yEnd; y++) {
                    covered[s.col][y] = true;
                }

                // Mark center row (horizontal part of the cross)
                int xStart = s.col - s.radius + 1;
                int xEnd = s.col + s.radius - 1;
                for (int x = xStart; x <= xEnd; x++) {
                    covered[x][s.row] = true;
                }
            }

            // Verify if the union of these crosses matches the input grid exactly
            for (int x = 0; x < width; x++) {
                for (int y = 0; y < height; y++) {
                    if (grid[x][y] != covered[x][y]) {
                        return false;
                    }
                }
            }
            return true;
        }
    }

    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

/**
 * Solver for the Star Pattern problem.
 * Identifies cross-shaped star patterns in a grid of '*' characters.
 */
public class StarPatternSolver {

    /**
     * Represents a star found in the grid.
     * 
     * @param row   1-based row index of the center
     * @param col   1-based column index of the center
     * @param size  The number of layers extending from the center
     */
    private record Star(int row, int col, int size) {
        @Override
        public String toString() {
            return row + " " + col + " " + size;
        }
    }

    private final FastReader reader;
    private final PrintWriter writer;

    public StarPatternSolver(InputStream inputStream, java.io.OutputStream outputStream) {
        this.reader = new FastReader(inputStream);
        this.writer = new PrintWriter(outputStream);
    }

    /**
     * Main execution logic for solving the problem.
     */
    public void solve() {
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = reader.next().toCharArray();
        }

        List<Star> foundStars = new ArrayList<>();
        boolean[][] isCovered = new boolean[rows][cols];

        // Step 1: Identify all star patterns
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*') {
                    findAndMarkStars(grid, i, j, isCovered, foundStars);
                }
            }
        }

        // Step 2: Verify if all '*' characters are part of at least one star
        if (isEveryStarCovered(grid, isCovered)) {
            printResults(foundStars);
        } else {
            writer.println("-1");
        }
    }

    /**
     * Checks if the current cell (i, j) is the center of a star and expands to find its size.
     */
    private void findAndMarkStars(char[][] grid, int r, int c, boolean[][] isCovered, List<Star> stars) {
        int rows = grid.length;
        int cols = grid[0].length;

        int up = r - 1, down = r + 1, left = c - 1, right = c + 1;
        int size = 0;

        // Expand outward layer by layer to find the maximum star size
        while (up >= 0 && down < rows && left >= 0 && right < cols) {
            if (grid[up][c] == '*' && grid[down][c] == '*' && 
                grid[r][left] == '*' && grid[r][right] == '*') {

                size++;
                // Mark center and the four tips of the current layer as covered
                isCovered[r][c] = true;
                isCovered[up][c] = true;
                isCovered[down][c] = true;
                isCovered[r][left] = true;
                isCovered[r][right] = true;

                up--;
                down++;
                left--;
                right++;
            } else {
                break;
            }
        }

        if (size > 0) {
            stars.add(new Star(r + 1, c + 1, size));
        }
    }

    /**
     * Validates that every '*' in the grid has been marked as covered.
     */
    private boolean isEveryStarCovered(char[][] grid, boolean[][] isCovered) {
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[0].length; j++) {
                if (grid[i][j] == '*' && !isCovered[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    private void printResults(List<Star> stars) {
        writer.println(stars.size());
        for (Star star : stars) {
            writer.println(star);
        }
    }

    public void close() {
        writer.close();
    }

    /**
     * Optimized reader for fast I/O operations.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) {
        StarPatternSolver solver = new StarPatternSolver(System.in, System.out);
        try {
            solver.solve();
        } finally {
            solver.close();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to find and cover all '*' cells in a grid using the minimum number 
 * of star-shaped patterns using a greedy approach.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            String firstLine = reader.nextLine();
            if (firstLine == null) return;

            StringTokenizer st = new StringTokenizer(firstLine);
            int rows = Integer.parseInt(st.nextToken());
            int cols = Integer.parseInt(st.nextToken());

            boolean[][] grid = new boolean[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = reader.nextLine();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = (line.charAt(j) == '*');
                }
            }

            StarSolver solver = new StarSolver();
            SolverResult result = solver.solve(rows, cols, grid);

            if (!result.isPossible()) {
                out.println("-1");
            } else {
                out.println(result.getStars().size());
                for (Star star : result.getStars()) {
                    // Output is 1-indexed as per original requirement
                    out.println((star.getRow() + 1) + " " + (star.getCol() + 1) + " " + star.getRadius());
                }
            }
        } catch (Exception e) {
            // In a real-world scenario, use a proper logger
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Represents a star pattern found in the grid.
     */
    static class Star {
        private final int row;
        private final int col;
        private final int radius;

        public Star(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }

        public int getRow() { return row; }
        public int getCol() { return col; }
        public int getRadius() { return radius; }
    }

    /**
     * Holds the outcome of the StarSolver.
     */
    static class SolverResult {
        private final List<Star> stars;
        private final boolean possible;

        public SolverResult(List<Star> stars, boolean possible) {
            this.stars = stars;
            this.possible = possible;
        }

        public List<Star> getStars() { return stars; }
        public boolean isPossible() { return possible; }
    }

    /**
     * Contains the logic for finding stars and verifying grid coverage.
     */
    static class StarSolver {

        public SolverResult solve(int rows, int cols, boolean[][] grid) {
            List<Star> stars = new ArrayList<>();
            boolean[][] covered = new boolean[rows][cols];

            // Iterate through the grid, excluding boundaries as centers 
            // because a star must have arms of at least length 1.
            for (int r = 1; r < rows - 1; r++) {
                for (int c = 1; c < cols - 1; c++) {
                    if (!grid[r][c]) continue;

                    int maxRadius = findMaxStarRadius(r, c, rows, cols, grid);

                    if (maxRadius > 0) {
                        markAsCovered(r, c, maxRadius, covered);
                        stars.add(new Star(r, c, maxRadius));
                    }
                }
            }

            // Verify if all '*' cells in the original grid are covered
            boolean allCovered = true;
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] && !covered[r][c]) {
                        allCovered = false;
                        break;
                    }
                }
                if (!allCovered) break;
            }

            return new SolverResult(stars, allCovered);
        }

        private int findMaxStarRadius(int r, int c, int rows, int cols, boolean[][] grid) {
            int radius = 0;
            while (true) {
                int nextRadius = radius + 1;
                if (isWithinBounds(r, c, nextRadius, rows, cols) &&
                    grid[r - nextRadius][c] && grid[r + nextRadius][c] &&
                    grid[r][c - nextRadius] && grid[r][c + nextRadius]) {
                    radius = nextRadius;
                } else {
                    break;
                }
            }
            return radius;
        }

        private boolean isWithinBounds(int r, int c, int radius, int rows, int cols) {
            return (r - radius >= 0) && (r + radius < rows) &&
                   (c - radius >= 0) && (c + radius < cols);
        }

        private void markAsCovered(int r, int c, int radius, boolean[][] covered) {
            covered[r][c] = true;
            for (int k = 1; k <= radius; k++) {
                covered[r - k][c] = true;
                covered[r + k][c] = true;
                covered[r][c - k] = true;
                covered[r][c + k] = true;
            }
        }
    }

    /**
     * Faster input reader for efficient processing of large grids.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public String nextLine() {
            try {
                return reader.readLine();
            } catch (IOException e) {
                return null;
            }
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Main entry point for the Star Drawing problem.
 */
public class Main {

    public static void main(String[] args) {
        try (InputStream inputStream = System.in;
             PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)))) {

            InputReader in = new InputReader(inputStream);
            StarSolver solver = new StarSolver();
            solver.solve(in, out);
        } catch (Exception e) {
            // In a production environment, use a proper logging framework.
            e.printStackTrace();
        }
    }

    /**
     * Solver for the Stars Drawing problem.
     * Uses a greedy approach by selecting the largest possible stars first to cover all '*' cells.
     */
    static class StarSolver {

        /**
         * Executes the solving logic.
         * @param in Fast input reader.
         * @param out Fast output writer.
         */
        public void solve(InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();

            if (n <= 0 || m <= 0) {
                out.println(-1);
                return;
            }

            char[][] grid = new char[n][m];
            int remainingStars = 0;
            for (int i = 0; i < n; ++i) {
                String line = in.next();
                if (line == null) break;
                grid[i] = line.toCharArray();
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == '*') {
                        remainingStars++;
                    }
                }
            }

            // Pre-calculate all possible stars based on the initial grid.
            // We use a PriorityQueue to greedily pick stars with the largest radius.
            PriorityQueue<Star> starQueue = new PriorityQueue<>(
                    Comparator.comparingInt(Star::getRadius).reversed()
            );

            for (int i = 1; i < n - 1; ++i) {
                for (int j = 1; j < m - 1; ++j) {
                    if (isPotentialCenter(grid, i, j)) {
                        int radius = calculateMaxRadius(grid, i, j, n, m);
                        if (radius > 0) {
                            starQueue.add(new Star(i, j, radius));
                        }
                    }
                }
            }

            List<Star> selectedStars = new ArrayList<>();

            // Greedy selection: Pick the largest available star until no '*' remain.
            while (!starQueue.isEmpty() && remainingStars > 0) {
                Star star = starQueue.poll();

                // Apply the star to the grid and count how many '*' it actually covered.
                int coveredInThisStep = applyStar(grid, star);

                // If this star covers at least one new '*', add it to our result.
                if (coveredInThisStep > 0) {
                    selectedStars.add(star);
                    remainingStars -= coveredInThisStep;
                }
            }

            // Final Output
            if (remainingStars == 0) {
                out.println(selectedStars.size());
                for (Star s : selectedStars) {
                    // Converting 0-indexed to 1-indexed for output.
                    out.println((s.row + 1) + " " + (s.col + 1) + " " + s.radius);
                }
            } else {
                out.println(-1);
            }
        }

        /**
         * Checks if a cell is a valid center for a star (radius >= 1).
         */
        private boolean isPotentialCenter(char[][] grid, int r, int c) {
            return grid[r][c] == '*' &&
                   grid[r - 1][c] == '*' && grid[r + 1][c] == '*' &&
                   grid[r][c - 1] == '*' && grid[r][c + 1] == '*';
        }

        /**
         * Calculates the maximum radius a star centered at (r, c) can have.
         */
        private int calculateMaxRadius(char[][] grid, int r, int c, int n, int m) {
            int radius = 1;
            while (true) {
                int nextR = radius + 1;
                if (r - nextR >= 0 && r + nextR < n && c - nextR >= 0 && c + nextR < m &&
                    grid[r - nextR][c] == '*' && grid[r + nextR][c] == '*' &&
                    grid[r][c - nextR] == '*' && grid[r][c + nextR] == '*') {
                    radius++;
                } else {
                    break;
                }
            }
            return radius;
        }

        /**
         * Marks the star cells as '.' in the grid and returns the count of '*' cells cleared.
         */
        private int applyStar(char[][] grid, Star star) {
            int count = 0;
            int r = star.row;
            int c = star.col;
            int rad = star.radius;

            // Clear the center
            if (grid[r][c] == '*') {
                grid[r][c] = '.';
                count++;
            }

            // Clear the 4 arms
            for (int i = 1; i <= rad; i++) {
                int[][] directions = {{r + i, c}, {r - i, c}, {r, c + i}, {r, c - i}};
                for (int[] dir : directions) {
                    int nr = dir[0];
                    int nc = dir[1];
                    if (grid[nr][nc] == '*') {
                        grid[nr][nc] = '.';
                        count++;
                    }
                }
            }
            return count;
        }

        /**
         * Immutable representation of a Star.
         */
        private static class Star {
            final int row;
            final int col;
            final int radius;

            Star(int row, int col, int radius) {
                this.row = row;
                this.col = col;
                this.radius = radius;
            }

            int getRadius() {
                return radius;
            }
        }
    }

    /**
     * Fast I/O reader using a buffered byte stream.
     */
    static class InputReader {
        private final InputStream stream;
        private final byte[] buf = new byte[1 << 16];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (numChars == -1) return -1;
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    return -1;
                }
                if (numChars <= 0) return -1;
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (c != -1 && isSpaceChar(c)) c = read();
            if (c == -1) throw new NoSuchElementException();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            while (c >= '0' && c <= '9') {
                res = res * 10 + (c - '0');
                c = read();
            }
            return res * sgn;
        }

        public String next() {
            int c = read();
            while (c != -1 && isSpaceChar(c)) c = read();
            if (c == -1) return null;
            StringBuilder sb = new StringBuilder();
            while (c != -1 && !isSpaceChar(c)) {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * Refactored solution to find the set of stars required to cover all '*' cells in a grid.
 * A star is defined by a center and a radius (minimum consecutive '*' in 4 cardinal directions).
 */
public class Codeforces {

    /**
     * Represents a unique coordinate in the grid.
     * Implements equals and hashCode to be used as a key in a Map.
     */
    private static class Coordinate {
        private final int row;
        private final int col;

        public Coordinate(int row, int col) {
            this.row = row;
            this.col = col;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            Coordinate that = (Coordinate) o;
            return row == that.row && col == that.col;
        }

        @Override
        public int hashCode() {
            return Objects.hash(row, col);
        }
    }

    /**
     * Represents a star found in the grid.
     */
    private static class Star {
        private final int row;
        private final int col;
        private final int radius;

        public Star(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }

        @Override
        public String toString() {
            // The problem requires 1-based indexing for output.
            return String.format("%d %d %d", row + 1, col + 1, radius);
        }
    }

    public static void main(String[] args) {
        // Using try-with-resources to ensure BufferedReader and PrintWriter are closed automatically.
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter pw = new PrintWriter(System.out)) {

            String firstLine = br.readLine();
            if (firstLine == null) return;

            StringTokenizer st = new StringTokenizer(firstLine);
            int n = Integer.parseInt(st.nextToken());
            int m = Integer.parseInt(st.nextToken());

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                String rowString = br.readLine();
                if (rowString != null) {
                    grid[i] = rowString.toCharArray();
                }
            }

            List<Star> stars = findMaximalStars(grid, n, m);

            if (isEveryAsteriskCovered(grid, stars, n, m)) {
                pw.println(stars.size());
                for (Star star : stars) {
                    pw.println(star);
                }
            } else {
                pw.println("-1");
            }
            pw.flush();

        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /**
     * Scans the grid to identify all possible stars. 
     * If multiple stars share a center, it keeps only the one with the largest radius.
     */
    private static List<Star> findMaximalStars(char[][] grid, int n, int m) {
        Map<Coordinate, Integer> starMap = new HashMap<>();

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*') {
                    int radius = calculateStarRadius(grid, i, j, n, m);
                    // Only consider valid stars (radius > 0)
                    if (radius > 0) {
                        Coordinate coord = new Coordinate(i, j);
                        // Ensure we keep the largest star for this specific center
                        starMap.put(coord, Math.max(starMap.getOrDefault(coord, 0), radius));
                    }
                }
            }
        }

        List<Star> stars = new ArrayList<>();
        for (Map.Entry<Coordinate, Integer> entry : starMap.entrySet()) {
            stars.add(new Star(entry.getKey().row, entry.getKey().col, entry.getValue()));
        }
        return stars;
    }

    /**
     * Calculates the maximum possible radius for a star centered at (r, c).
     * The radius is the minimum number of consecutive '*' in the 4 cardinal directions.
     */
    private static int calculateStarRadius(char[][] grid, int r, int c, int n, int m) {
        int up = 0, down = 0, left = 0, right = 0;

        // Count consecutive '*' upwards
        for (int i = r - 1; i >= 0 && grid[i][c] == '*'; i--) up++;
        // Count consecutive '*' downwards
        for (int i = r + 1; i < n && grid[i][c] == '*'; i++) down++;
        // Count consecutive '*' to the left
        for (int j = c - 1; j >= 0 && grid[r][j] == '*'; j--) left++;
        // Count consecutive '*' to the right
        for (int j = c + 1; j < m && grid[r][j] == '*'; j++) right++;

        return Math.min(Math.min(up, down), Math.min(left, right));
    }

    /**
     * Validates if every '*' cell in the grid is covered by at least one star.
     */
    private static boolean isEveryAsteriskCovered(char[][] grid, List<Star> stars, int n, int m) {
        boolean[][] covered = new boolean[n][m];

        // Mark cells covered by each star
        for (Star star : stars) {
            int r = star.row;
            int c = star.col;
            int rad = star.radius;

            // Mark vertical arm
            for (int i = r - rad; i <= r + rad; i++) {
                covered[i][c] = true;
            }
            // Mark horizontal arm
            for (int j = c - rad; j <= c + rad; j++) {
                covered[r][j] = true;
            }
        }

        // Final verification
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*' && !covered[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to solve the "Cross Pattern" problem:
 * Finding the minimum set of cross patterns that exactly cover all '*' cells in a grid.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            CrossPatternSolver solver = new CrossPatternSolver();
            // The original code had a loop for 't' test cases, set to 1.
            int testCases = 1;
            for (int i = 1; i <= testCases; i++) {
                solver.solve(reader, writer);
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    /**
     * Represents a cross pattern with a center and a radius.
     */
    static class CrossPattern {
        final int row;
        final int col;
        final int radius;

        CrossPattern(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }

        @Override
        public String toString() {
            return row + " " + col + " " + radius;
        }
    }

    /**
     * Contains the core logic for finding and validating cross patterns.
     */
    static class CrossPatternSolver {

        public void solve(FastReader reader, PrintWriter writer) {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            if (rows <= 0 || cols <= 0) {
                writer.println(0);
                return;
            }

            boolean[][] isStar = new boolean[rows][cols];
            boolean[][] coveredGrid = new boolean[rows][cols];
            List<CrossPattern> patterns = new ArrayList<>();

            // Load the grid
            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                for (int j = 0; j < cols; j++) {
                    if (line.charAt(j) == '*') {
                        isStar[i][j] = true;
                    }
                }
            }

            // Find all maximal cross patterns
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (isStar[i][j]) {
                        int k = findMaxRadius(isStar, i, j);
                        if (k > 0) {
                            patterns.add(new CrossPattern(i + 1, j + 1, k));
                            markCovered(coveredGrid, i, j, k);
                        }
                    }
                }
            }

            // Validate if the combined crosses match the original grid exactly
            if (isValid(isStar, coveredGrid)) {
                writer.println(patterns.size());
                for (CrossPattern pattern : patterns) {
                    writer.println(pattern);
                }
            } else {
                writer.println("-1");
            }
        }

        /**
         * Finds the maximum radius k such that a cross of radius k can be formed at (r, c).
         */
        private int findMaxRadius(boolean[][] grid, int r, int c) {
            int k = 0;
            while (true) {
                int nextK = k + 1;
                if (isStarAt(grid, r + nextK, c) &&
                    isStarAt(grid, r - nextK, c) &&
                    isStarAt(grid, r, c + nextK) &&
                    isStarAt(grid, r, c - nextK)) {
                    k = nextK;
                } else {
                    break;
                }
            }
            return k;
        }

        private boolean isStarAt(boolean[][] grid, int r, int c) {
            return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length && grid[r][c];
        }

        /**
         * Marks cells in the coveredGrid as true for the given cross pattern.
         */
        private void markCovered(boolean[][] covered, int r, int c, int radius) {
            covered[r][c] = true;
            for (int k = 1; k <= radius; k++) {
                covered[r + k][c] = true;
                covered[r - k][c] = true;
                covered[r][c + k] = true;
                covered[r][c - k] = true;
            }
        }

        /**
         * Checks if the coverage matches the target grid.
         */
        private boolean isValid(boolean[][] target, boolean[][] covered) {
            for (int i = 0; i < target.length; i++) {
                for (int j = 0; j < target[0].length; j++) {
                    if (target[i][j] != covered[i][j]) {
                        return false;
                    }
                }
            }
            return true;
        }
    }

    /**
     * Utility class for fast input parsing.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.util.*;

/**
 * Solves the problem of covering all '*' cells on a grid using the minimum number 
 * of plus-shaped symbols.
 */
public class PlusSignSolver {

    /**
     * Represents a plus-shaped symbol on the grid.
     * 
     * @param row   The 1-based row index of the center.
     * @param col   The 1-based column index of the center.
     * @param size  The length of the arms.
     */
    public record PlusSign(int row, int col, int size) {}

    /**
     * Holds the result of the coverage attempt.
     */
    public static class SolverResult {
        private final List<PlusSign> pluses;
        private final boolean success;

        private SolverResult(List<PlusSign> pluses, boolean success) {
            this.pluses = pluses;
            this.success = success;
        }

        public static SolverResult success(List<PlusSign> pluses) {
            return new SolverResult(pluses, true);
        }

        public static SolverResult failure() {
            return new SolverResult(Collections.emptyList(), false);
        }

        public boolean isSuccess() { return success; }
        public List<PlusSign> getPluses() { return pluses; }
    }

    /**
     * Core logic for solving the grid coverage problem.
     */
    public static class GridSolver {

        public SolverResult solve(boolean[][] board) {
            int rows = board.length;
            if (rows == 0) return SolverResult.success(Collections.emptyList());
            int cols = board[0].length;

            boolean[][] isCovered = new boolean[rows][cols];
            List<PlusSign> foundPluses = new ArrayList<>();

            // Iterate through all possible centers (excluding edges)
            for (int i = 1; i < rows - 1; i++) {
                for (int j = 1; j < cols - 1; j++) {
                    if (!board[i][j]) continue;

                    int maxArmLength = findMaxArmLength(board, i, j, rows, cols);

                    if (maxArmLength > 0) {
                        // Store using 1-based indexing as per requirements
                        foundPluses.add(new PlusSign(i + 1, j + 1, maxArmLength));
                        markCoverage(isCovered, i, j, maxArmLength);
                    }
                }
            }

            return validateCoverage(board, isCovered) 
                ? SolverResult.success(foundPluses) 
                : SolverResult.failure();
        }

        private int findMaxArmLength(boolean[][] board, int r, int c, int rows, int cols) {
            // Calculate the maximum possible arm length constrained by grid boundaries
            int boundaryLimit = Math.min(Math.min(r, rows - r - 1), Math.min(c, cols - c - 1));
            int k = 0;

            // Expand arms as long as all four directions contain a '*'
            while (k + 1 <= boundaryLimit &&
                   board[r + k + 1][c] && board[r - k - 1][c] &&
                   board[r][c + k + 1] && board[r][c - k - 1]) {
                k++;
            }
            return k;
        }

        private void markCoverage(boolean[][] isCovered, int r, int c, int k) {
            isCovered[r][c] = true;
            for (int i = 1; i <= k; i++) {
                isCovered[r + i][c] = true;
                isCovered[r - i][c] = true;
                isCovered[r][c + i] = true;
                isCovered[r][c - i] = true;
            }
        }

        private boolean validateCoverage(boolean[][] board, boolean[][] isCovered) {
            for (int i = 0; i < board.length; i++) {
                for (int j = 0; j < board[0].length; j++) {
                    // If there's a star that isn't covered, the solution is invalid
                    if (board[i][j] && !isCovered[i][j]) {
                        return false;
                    }
                }
            }
            return true;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        if (!sc.hasNextInt()) {
            sc.close();
            return;
        }

        int n = sc.nextInt();
        int m = sc.nextInt();
        boolean[][] board = new boolean[n][m];

        for (int i = 0; i < n; i++) {
            String rowString = sc.next();
            for (int j = 0; j < m; j++) {
                board[i][j] = (rowString.charAt(j) == '*');
            }
        }

        GridSolver solver = new GridSolver();
        SolverResult result = solver.solve(board);

        if (result.isSuccess()) {
            System.out.println(result.getPluses().size());
            for (PlusSign p : result.getPluses()) {
                System.out.printf("%d %d %d%n", p.row(), p.col(), p.size());
            }
        } else {
            System.out.println("-1");
        }

        sc.close();
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to find a set of "cross" patterns in a grid of '#' and '.' 
 * such that every '#' is covered by exactly one cross and no '.' is covered.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            GridProblemSolver solver = new GridProblemSolver(reader);
            solver.solve(writer);
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    /**
     * Represents a single cross pattern found in the grid.
     */
    static class Cross {
        final int row;
        final int col;
        final int radius;

        Cross(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }

        @Override
        public String toString() {
            // Convert 0-indexed to 1-indexed for output
            return (row + 1) + " " + (col + 1) + " " + radius;
        }
    }

    /**
     * Core logic for solving the grid cross problem.
     */
    static class GridProblemSolver {
        private final FastReader reader;
        private int rows;
        private int cols;
        private int[][] grid;
        private int[][] rowPrefixSums;
        private int[][] colPrefixSums;

        public GridProblemSolver(FastReader reader) {
            this.reader = reader;
        }

        public void solve(PrintWriter writer) throws IOException {
            readInput();
            computePrefixSums();

            List<Cross> foundCrosses = findOptimalCrosses();

            if (validateCoverage(foundCrosses)) {
                writer.println(foundCrosses.size());
                for (Cross cross : foundCrosses) {
                    writer.println(cross.toString());
                }
            } else {
                writer.println("-1");
            }
        }

        private void readInput() throws IOException {
            this.rows = reader.nextInt();
            this.cols = reader.nextInt();
            this.grid = new int[rows][cols];

            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = (line.charAt(j) == '#') ? 1 : 0;
                }
            }
        }

        /**
         * Precomputes prefix sums for rows and columns to allow O(1) range sum queries.
         */
        private void computePrefixSums() {
            rowPrefixSums = new int[rows][cols + 1];
            colPrefixSums = new int[cols][rows + 1];

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    rowPrefixSums[i][j + 1] = rowPrefixSums[i][j] + grid[i][j];
                }
            }

            for (int j = 0; j < cols; j++) {
                for (int i = 0; i < rows; i++) {
                    colPrefixSums[j][i + 1] = colPrefixSums[j][i] + grid[i][j];
                }
            }
        }

        private int getRangeSum(int[] prefix, int start, int end) {
            // Clamp boundaries to ensure indices are within valid prefix array range
            int left = Math.max(0, start);
            int right = Math.min(prefix.length - 1, end + 1);
            if (left >= right) return 0;
            return prefix[right] - prefix[left];
        }

        /**
         * Finds the largest possible radius for a cross centered at (r, c).
         */
        private int findMaxRadius(int r, int c) {
            int low = 0;
            int high = Math.min(Math.min(r, rows - 1 - r), Math.min(c, cols - 1 - c));
            int bestRadius = 0;

            while (low <= high) {
                int mid = low + (high - low) / 2;

                // Check if all cells in the horizontal and vertical arms are '#'
                int rowSum = getRangeSum(rowPrefixSums[r], c - mid, c + mid);
                int colSum = getRangeSum(colPrefixSums[c], r - mid, r + mid);

                if (rowSum == (2 * mid + 1) && colSum == (2 * mid + 1)) {
                    bestRadius = mid;
                    low = mid + 1;
                } else {
                    high = mid - 1;
                }
            }
            return bestRadius;
        }

        private List<Cross> findOptimalCrosses() {
            List<Cross> crosses = new ArrayList<>();
            // Difference arrays to mark covered cells
            int[][] rowDiff = new int[rows][cols + 1];
            int[][] colDiff = new int[cols][rows + 1];

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == 1) {
                        int k = findMaxRadius(i, j);
                        if (k > 0) {
                            crosses.add(new Cross(i, j, k));
                            // Mark horizontal coverage [j-k, j+k]
                            rowDiff[i][j - k]++;
                            rowDiff[i][j + k + 1]--;
                            // Mark vertical coverage [i-k, i+k]
                            colDiff[j][i - k]++;
                            colDiff[j][i + k + 1]--;
                        }
                    }
                }
            }

            // Reconstruct coverage mask from difference arrays
            int[][] coverageMask = new int[rows][cols];
            for (int i = 0; i < rows; i++) {
                int current = 0;
                for (int j = 0; j < cols; j++) {
                    current += rowDiff[i][j];
                    if (current > 0) coverageMask[i][j] = 1;
                }
            }
            for (int j = 0; j < cols; j++) {
                int current = 0;
                for (int i = 0; i < rows; i++) {
                    current += colDiff[j][i];
                    if (current > 0) coverageMask[i][j] = 1;
                }
            }

            // We need to pass the mask to validate against the original grid
            this.applyCoverageMask(coverageMask); 
            // Note: In this refactored version, we store the mask in a way 
            // that validateCoverage can access it.
            this.lastCalculatedMask = coverageMask;

            return crosses;
        }

        private int[][] lastCalculatedMask;

        private void applyCoverageMask(int[][] mask) {
            this.lastCalculatedMask = mask;
        }

        /**
         * Ensures all '#' are covered and no '.' are covered.
         */
        private boolean validateCoverage(List<Cross> crosses) {
            if (lastCalculatedMask == null) return false;

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    boolean isCovered = (lastCalculatedMask[i][j] == 1);
                    boolean isTarget = (grid[i][j] == 1);

                    // If a target '#' is not covered, or a '.' is covered, return false
                    if (isTarget != isCovered) {
                        return false;
                    }
                }
            }
            return true;
        }
    }

    /**
     * Fast I/O utility for reading input efficiently.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

