/**
 * Handles the logic for calculating cross potentials and marking the grid.
 */
class CrossSolver {
    private final int rows;
    private final int cols;
    private final char[][] grid;

    // DP arrays to store consecutive '*' counts in four directions
    private final int[][] upCounts;
    private final int[][] downCounts;
    private final int[][] leftCounts;
    private final int[][] rightCounts;

    public CrossSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.upCounts = new int[rows][cols];
        this.downCounts = new int[rows][cols];
        this.leftCounts = new int[rows][cols];
        this.rightCounts = new int[rows][cols];
    }

    /**
     * Orchestrates the solving process.
     */
    public void solve() {
        calculateDirectionalCounts();
        List<Cross> discoveredCrosses = findAndApplyCrosses();

        if (hasUncoveredStars()) {
            System.out.println("-1");
        } else {
            printResults(discoveredCrosses);
        }
    }

    /**
     * Pre-calculates how many '*' are available in each direction for every cell.
     */
    private void calculateDirectionalCounts() {
        // Calculate Up and Left counts (Top-Down, Left-to-Right)
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (i > 0 && grid[i - 1][j] == '*') {
                    upCounts[i][j] = upCounts[i - 1][j] + 1;
                }
                if (j > 0 && grid[i][j - 1] == '*') {
                    leftCounts[i][j] = leftCounts[i][j - 1] + 1;
                }
            }
        }

        // Calculate Down and Right counts (Bottom-Up, Right-to-Left)
        for (int i = rows - 1; i >= 0; i--) {
            for (int j = cols - 1; j >= 0; j--) {
                if (i < rows - 1 && grid[i + 1][j] == '*') {
                    downCounts[i][j] = downCounts[i + 1][j] + 1;
                }
                if (j < cols - 1 && grid[i][j + 1] == '*') {
                    rightCounts[i][j] = rightCounts[i][j + 1] + 1;
                }
            }
        }
    }

    /**
     * Iterates through the grid to find the largest crosses and marks them on the grid.
     */
    private List<Cross> findAndApplyCrosses() {
        List<Cross> found = new ArrayList<>();

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                // A cell can be a center if it is '*' or already marked 'x'
                if (grid[i][j] == '*' || grid[i][j] == 'x') {
                    int radius = calculateMaxRadius(i, j);

                    if (radius > 0) {
                        found.add(new Cross(i + 1, j + 1, radius));
                        markGridAsCross(i, j, radius);
                    }
                }
            }
        }
        return found;
    }

    private int calculateMaxRadius(int r, int c) {
        int minUp = upCounts[r][c];
        int minDown = downCounts[r][c];
        int minLeft = leftCounts[r][c];
        int minRight = rightCounts[r][c];

        return Math.min(Math.min(minUp, minDown), Math.min(minLeft, minRight));
    }

    /**
     * Marks the cells covered by the cross with 'x'.
     */
    private void markGridAsCross(int r, int c, int radius) {
        // Vertical arm
        for (int i = r - radius; i <= r + radius; i++) {
            grid[i][c] = 'x';
        }
        // Horizontal arm
        for (int j = c - radius; j <= c + radius; j++) {
            grid[r][j] = 'x';
        }
    }

    /**
     * Checks if any '*' remains in the grid.
     */
    private boolean hasUncoveredStars() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*') {
                    return true;
                }
            }
        }
        return false;
    }

    private void printResults(List<Cross> crosses) {
        System.out.println(crosses.size());
        StringBuilder sb = new StringBuilder();
        for (Cross cross : crosses) {
            sb.append(cross.toString()).append("\n");
        }
        System.out.print(sb.toString());
    }
}

