/**
 * Encapsulates the logic for finding the optimal cross centers in a grid.
 */
class CrossSolver {
    private final int rows;
    private final int cols;
    private final char[][] grid;
    private static final char STAR = '*';

    public CrossSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
    }

    /**
     * Represents a center point of a cross.
     */
    public static class Center {
        private final int r, c, radius;

        public Center(int r, int c, int radius) {
            this.r = r;
            this.c = c;
            this.radius = radius;
        }

        public int getR() { return r; }
        public int getC() { return c; }
        public int getRadius() { return radius; }

        @Override
        public String toString() {
            return (r + 1) + " " + (c + 1) + " " + radius;
        }
    }

    /**
     * Holds the outcome of the solver.
     */
    public static class Result {
        private final List<Center> centers;
        private final boolean possible;

        public Result(List<Center> centers, boolean possible) {
            this.centers = centers;
            this.possible = possible;
        }

        public List<Center> getCenters() { return centers; }
        public boolean isPossible() { return possible; }

        public String getFormattedCenters() {
            StringBuilder sb = new StringBuilder();
            for (Center center : centers) {
                sb.append(center.toString()).append("\n");
            }
            return sb.toString();
        }
    }

    public Result solve() {
        int[][] maxRadii = computeMaxRadii();
        List<Center> centers = findPotentialCenters(maxRadii);

        if (validateCoverage(centers)) {
            return new Result(centers, true);
        } else {
            return new Result(Collections.emptyList(), false);
        }
    }

    /**
     * Calculates the maximum possible radius for a cross centered at each cell.
     * The radius is the distance to the nearest non-star cell in 4 directions.
     */
    private int[][] computeMaxRadii() {
        int[][] maxRadii = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            Arrays.fill(maxRadii[i], Integer.MAX_VALUE);
        }

        // Directions: Left-to-Right, Right-to-Left, Top-to-Bottom, Bottom-to-Top
        scanDirection(maxRadii, 1, 0);   // Left to Right
        scanDirection(maxRadii, -1, 0);  // Right to Left
        scanDirection(maxRadii, 0, 1);   // Top to Bottom
        scanDirection(maxRadii, 0, -1);  // Bottom to Top

        // Adjusting the result: the logic uses -1 as a sentinel for non-stars
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] != STAR) {
                    maxRadii[i][j] = -1;
                } else {
                    // The scan logic results in (radius + 1) relative to the count
                    // We transform the raw count to a meaningful radius
                    maxRadii[i][j] = maxRadii[i][j] - 1;
                }
            }
        }
        return maxRadii;
    }

    private void scanDirection(int[][] maxRadii, int dr, int dc) {
        // This is a simplified version of the original scan logic to maintain the same O(N*M) complexity
        // We iterate through the grid in a way that respects the direction.
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                // We need to iterate in order based on direction
                // To keep it clean, we use the logic from the original code's 4-pass structure
            }
        }
        // Re-implementing the original logic clearly
    }

    // Since the scan logic is specific to 4 directions, let's use the original 4-pass approach
    // but encapsulated and cleaned.
    private int[][] computeMaxRadiiRefactored() {
        int[][] max = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            int cnt = -1;
            for (int j = 0; j < cols; j++) {
