            for (int i = rows - 1; i >= 0; i--) {
                cnt = (grid[i][j] == STAR) ? cnt + 1 : -1;
                max[i][j] = Math.min(max[i][j], cnt);
            }
        }
        // Convert count to radius
        for (int i = 0; i < rows; i++) {
