    private List<Center> findPotentialCenters(int[][] maxRadii) {
        List<Center> centers = new ArrayList<>();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == STAR && maxRadii[i][j] >= 1) {
                    centers.add(new Center(i, j, maxRadii[i][j]));
                }
