    private boolean validateCoverage(List<Center> centers) {
        boolean[][] isCovered = new boolean[rows][cols];
        for (Center c : centers) {
            int r = c.getR();
            int col = c.getC();
            int rad = c.getRadius();
            isCovered[r][col] = true;
            for (int k = 1; k <= rad; k++) {
                isCovered[r - k][col] = true;
                isCovered[r + k][col] = true;
                isCovered[r][col - k] = true;
