import java.io.*;
import java.util.*;

/**
 * Refactored solution for Task E2.
 * The program identifies star-shaped patterns in a grid of '*' characters 
 * such that every star is covered by at least one pattern.
 */
public class Main {

    public static void main(String[] args) {
        FastReader in = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        StarSolver solver = new StarSolver(in, out);
        solver.solve();

        out.close();
    }

    /**
     * Encapsulates the logic for solving the star coverage problem.
     */
    static class StarSolver {
        private final FastReader in;
        private final PrintWriter out;

        public StarSolver(FastReader in, PrintWriter out) {
            this.in = in;
            this.out = out;
        }

        public void solve() {
            int rows = in.nextInt();
            int cols = in.nextInt();

            Grid grid = new Grid(rows, cols);
            grid.load(in);

            BoundaryMap boundaries = new BoundaryMap(grid);
            boundaries.computeBoundaries();

            List<Star> stars = calculateStars(grid, boundaries);

            if (checkCoverage(grid, stars)) {
                out.println(stars.size());
                for (Star star : stars) {
                    out.println(star);
                }
            } else {
                out.println("-1");
            }
        }

        private List<Star> calculateStars(Grid grid, BoundaryMap boundaries) {
            List<Star> stars = new ArrayList<>();

            for (int i = 1; i <= grid.rows; i++) {
                for (int j = 1; j <= grid.cols; j++) {
                    if (grid.isStar(i, j)) {
                        int distToHorizontalEdge = Math.min(j - boundaries.leftBound[i][j], 
                                                           boundaries.rightBound[i][j] - j);
                        int distToVerticalEdge = Math.min(i - boundaries.topBound[i][j], 
                                                         boundaries.bottomBound[i][j] - i);

                        int radius = Math.min(distToHorizontalEdge, distToVerticalEdge);

                        if (radius > 0) {
                            stars.add(new Star(i, j, radius));
                        }
                    }
                }
            }
            return stars;
        }

        private boolean checkCoverage(Grid grid, List<Star> stars) {
            // Use difference arrays to mark covered cells
            // rowCoverage tracks horizontal segments, colCoverage tracks vertical segments
            int[][] rowCoverage = new int[grid.rows + 2][grid.cols + 2];
            int[][] colCoverage = new int[grid.rows + 2][grid.cols + 2];

            for (Star star : stars) {
                // Apply horizontal coverage: [col - radius, col + radius]
                rowCoverage[star.row][star.col - star.radius] += 1;
                rowCoverage[star.row][star.col + star.radius + 1] -= 1;

                // Apply vertical coverage: [row - radius, row + radius]
                colCoverage[star.row - star.radius][star.col] += 1;
                colCoverage[star.row + star.radius + 1][star.col] -= 1;
            }

            // Prefix sums to resolve coverage
            for (int i = 1; i <= grid.rows; i++) {
                for (int j = 1; j <= grid.cols; j++) {
                    rowCoverage[i][j] += rowCoverage[i][j - 1];
                    colCoverage[i][j] += colCoverage[i - 1][j];

                    // If a star cell is not covered by any horizontal or vertical segment
                    if (grid.isStar(i, j) && rowCoverage[i][j] == 0 && colCoverage[i][j] == 0) {
                        return false;
                    }
                }
            }
            return true;
        }
    }

    /**
     * Represents the grid of characters.
     */
    static class Grid {
        final int rows;
        final int cols;
        final char[][] cells;

        Grid(int rows, int cols) {
            this.rows = rows;
            this.cols = cols;
            this.cells = new char[rows + 2][cols + 2];
        }

        void load(FastReader in) {
            for (int i = 1; i <= rows; i++) {
                String line = in.next();
                for (int j = 1; j <= cols; j++) {
                    cells[i][j] = line.charAt(j - 1);
                }
            }
        }

        boolean isStar(int r, int c) {
            return cells[r][c] == '*';
        }
    }

    /**
     * Computes the boundaries (edges of contiguous '*' segments) for each cell.
     */
    static class BoundaryMap {
        int[][] leftBound, rightBound, topBound, bottomBound;
        private final Grid grid;

        BoundaryMap(Grid grid) {
            this.grid = grid;
            int r = grid.rows;
            int c = grid.cols;
            leftBound = new int[r + 2][c + 2];
            rightBound = new int[r + 2][c + 2];
            topBound = new int[r + 2][c + 2];
            bottomBound = new int[r + 2][c + 2];
        }

        void computeBoundaries() {
            // Calculate Horizontal Boundaries (Left and Top)
            for (int i = 1; i <= grid.rows; i++) {
                for (int j = 1; j <= grid.cols; j++) {
                    if (grid.isStar(i, j)) {
                        leftBound[i][j] = (leftBound[i][j - 1] != 0) ? leftBound[i][j - 1] : j;
                        topBound[i][j] = (topBound[i - 1][j] != 0) ? topBound[i - 1][j] : i;
                    }
                }
            }

            // Calculate Horizontal Boundaries (Right and Bottom)
            for (int i = grid.rows; i >= 1; i--) {
                for (int j = grid.cols; j >= 1; j--) {
                    if (grid.isStar(i, j)) {
                        rightBound[i][j] = (rightBound[i][j + 1] != 0) ? rightBound[i][j + 1] : j;
                        bottomBound[i][j] = (bottomBound[i + 1][j] != 0) ? bottomBound[i + 1][j] : i;
                    }
                }
            }
        }
    }

    static class Star {
        final int row, col, radius;

        Star(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }

        @Override
        public String toString() {
            return row + " " + col + " " + radius;
        }
    }

    /**
     * Fast I/O utility.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * StarDrawingSolver determines if all '*' cells in a grid can be covered by symmetric stars.
 * Time Complexity: O(N * M)
 * Space Complexity: O(N * M)
 */
public class StarDrawingSolver {

    private static final char STAR = '*';

    private static class Star {
        int r, c, radius;
        Star(int r, int c, int radius) {
            this.r = r;
            this.c = c;
            this.radius = radius;
        }
    }

    public static void main(String[] args) {
        new StarDrawingSolver().run();
    }

    public void run() {
        FastReader sc = new FastReader(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();

        if (n <= 0 || m <= 0) return;

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = sc.next().toCharArray();
        }

        int[][] up = new int[n][m];
        int[][] down = new int[n][m];
        int[][] left = new int[n][m];
        int[][] right = new int[n][m];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == STAR) {
                    up[i][j] = (i > 0) ? up[i - 1][j] + 1 : 1;
                    left[i][j] = (j > 0) ? left[i][j - 1] + 1 : 1;
                }
            }
        }

        for (int i = n - 1; i >= 0; i--) {
            for (int j = m - 1; j >= 0; j--) {
                if (grid[i][j] == STAR) {
                    down[i][j] = (i < n - 1) ? down[i + 1][j] + 1 : 1;
                    right[i][j] = (j < m - 1) ? right[i][j + 1] + 1 : 1;
                }
            }
        }

        List<Star> stars = new ArrayList<>();
        boolean[][] covered = new boolean[n][m];

        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < m - 1; j++) {
                if (grid[i][j] == STAR) {
                    int minArm = Math.min(Math.min(up[i][j], down[i][j]), 
                                          Math.min(left[i][j], right[i][j]));
                    int radius = minArm - 1;

                    if (radius > 0) {
                        stars.add(new Star(i + 1, j + 1, radius));
                        covered[i][j] = true;
                        for (int k = 1; k <= radius; k++) {
                            covered[i - k][j] = true;
                            covered[i + k][j] = true;
                            covered[i][j - k] = true;
                            covered[i][j + k] = true;
                        }
                    }
                }
            }
        }

        boolean allCovered = true;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == STAR && !covered[i][j]) {
                    allCovered = false;
                    break;
                }
            }
            if (!allCovered) break;
        }

        if (allCovered) {
            System.out.println(stars.size());
            for (Star s : stars) {
                System.out.println(s.r + " " + s.c + " " + s.radius);
            }
        } else {
            System.out.println("-1");
        }
    }

    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() { return Integer.parseInt(next()); }
    }
}

import java.util.*;
import java.io.*;

/**
 * A program to identify "star" patterns in a grid and ensure all '*' cells are covered.
 * A star is defined as a center cell with arms extending equally in four directions.
 */
public class StarCoverageSolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        Solver solver = new Solver();
        solver.solve(reader, writer);

        writer.flush();
        writer.close();
    }

    /**
     * Represents a star center and its maximum expansion radius.
     */
    static class Star implements Comparable<Star> {
        private final int row;
        private final int col;
        private final int radius;

        public Star(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }

        public int getRow() { return row; }
        public int getCol() { return col; }
        public int getRadius() { return radius; }

        @Override
        public int compareTo(Star other) {
            if (this.row != other.row) {
                return Integer.compare(this.row, other.row);
            }
            return Integer.compare(this.col, other.col);
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Star)) return false;
            Star star = (Star) o;
            return row == star.row && col == star.col;
        }

        @Override
        public int hashCode() {
            return Objects.hash(row, col);
        }
    }

    /**
     * Contains the logic to process the grid and find star patterns.
     */
    static class Solver {

        public void solve(FastReader reader, PrintWriter writer) {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            boolean[][] grid = new boolean[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = (line.charAt(j) == '*');
                }
            }

            List<Star> stars = new ArrayList<>();
            boolean[][] isCovered = new boolean[rows][cols];

            // Step 1: Identify all valid star patterns
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j]) {
                        int radius = findStarRadius(grid, i, j, rows, cols);
                        if (radius > 0) {
                            stars.add(new Star(i, j, radius));
                            markCovered(isCovered, i, j, radius);
                        }
                    }
                }
            }

            // Step 2: Verify if every '*' cell in the grid is covered by at least one star
            if (isAllStarsCovered(grid, isCovered)) {
                writer.println(stars.size());
                for (Star star : stars) {
                    // Output using 1-based indexing
                    writer.printf("%d %d %d%n", star.getRow() + 1, star.getCol() + 1, star.getRadius());
                }
            } else {
                writer.println("-1");
            }
        }

        /**
         * Calculates the maximum radius of a star centered at (r, c).
         * A radius of 0 means the cell is not a center of a star (needs at least 4 neighbors).
         */
        private int findStarRadius(boolean[][] grid, int r, int c, int rows, int cols) {
            int maxPossibleRadius = Math.min(Math.min(rows - r - 1, cols - c - 1), Math.min(r, c));
            int radius = 0;
            for (int k = 1; k <= maxPossibleRadius; k++) {
                if (grid[r + k][c] && grid[r - k][c] && grid[r][c + k] && grid[r][c - k]) {
                    radius = k;
                } else {
                    break;
                }
            }
            return radius;
        }

        /**
         * Marks the center and the arms of a star as covered in the coverage map.
         */
        private void markCovered(boolean[][] isCovered, int r, int c, int radius) {
            isCovered[r][c] = true;
            for (int k = 1; k <= radius; k++) {
                isCovered[r + k][c] = true;
                isCovered[r - k][c] = true;
                isCovered[r][c + k] = true;
                isCovered[r][c - k] = true;
            }
        }

        /**
         * Checks if every '*' cell in the original grid has been marked in the isCovered array.
         */
        private boolean isAllStarsCovered(boolean[][] grid, boolean[][] isCovered) {
            for (int i = 0; i < grid.length; i++) {
                for (int j = 0; j < grid[0].length; j++) {
                    if (grid[i][j] && !isCovered[i][j]) {
                        return false;
                    }
                }
            }
            return true;
        }
    }

    /**
     * Fast I/O utility for efficient reading of input.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }
    }
}

import java.util.*;

/**
 * A program to find a set of "cross" shapes that cover all '*' characters in a grid.
 * Each cross is defined by a center and four equal-length arms.
 */
public class CrossCoverer {

    /**
     * Represents a cross found in the grid.
     */
    static class Cross {
        final int row;      // 1-based row index
        final int col;      // 1-based column index
        final int armLength; // Length of each arm

        Cross(int row, int col, int armLength) {
            this.row = row;
            this.col = col;
            this.armLength = armLength;
        }

        @Override
        public String toString() {
            return row + " " + col + " " + armLength;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        char[][] grid = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        solve(rows, cols, grid);
    }

    private static void solve(int rows, int cols, char[][] grid) {
        // DP tables to store consecutive '*' counts in four directions
        int[][] up = new int[rows][cols];
        int[][] down = new int[rows][cols];
        int[][] left = new int[rows][cols];
        int[][] right = new int[rows][cols];

        // Pre-calculate arm lengths using Dynamic Programming
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*') {
                    up[i][j] = (i > 0) ? up[i - 1][j] + 1 : 1;
                    left[i][j] = (j > 0) ? left[i][j - 1] + 1 : 1;
                }
            }
        }

        for (int i = rows - 1; i >= 0; i--) {
            for (int j = cols - 1; j >= 0; j--) {
                if (grid[i][j] == '*') {
                    down[i][j] = (i < rows - 1) ? down[i + 1][j] + 1 : 1;
                    right[i][j] = (j < cols - 1) ? right[i][j + 1] + 1 : 1;
                }
            }
        }

        boolean[][] isCovered = new boolean[rows][cols];
        List<Cross> foundCrosses = new ArrayList<>();

        // Iterate through potential centers (excluding borders as per original logic)
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (grid[i][j] == '*') {
                    // Calculate the maximum possible equal arm length
                    // Subtract 1 because DP includes the center cell itself
                    int minArm = Math.min(Math.min(up[i][j], down[i][j]), 
                                          Math.min(left[i][j], right[i][j])) - 1;

                    if (minArm > 0) {
                        foundCrosses.add(new Cross(i + 1, j + 1, minArm));
                        markCovered(isCovered, i, j, minArm);
                    }
                }
            }
        }

        // Verification: Check if every '*' is covered
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*' && !isCovered[i][j]) {
                    System.out.println("-1");
                    return;
                }
            }
        }

        // Final Output
        StringBuilder output = new StringBuilder();
        output.append(foundCrosses.size()).append("\n");
        for (Cross cross : foundCrosses) {
            output.append(cross.toString()).append("\n");
        }
        System.out.print(output.toString());
    }

    /**
     * Marks the center and the four arms of a cross as covered.
     */
    private static void markCovered(boolean[][] isCovered, int r, int c, int armLength) {
        isCovered[r][c] = true;
        for (int k = 1; k <= armLength; k++) {
            isCovered[r + k][c] = true;
            isCovered[r - k][c] = true;
            isCovered[r][c + k] = true;
            isCovered[r][c - k] = true;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solution for the Star Grid problem.
 * Finds the minimum number of stars (using a greedy approach) to cover all asterisks.
 */
public class P1015E2 {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] grid = new char[rows][];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.nextLine().toCharArray();
            }

            StarGridSolver solver = new StarGridSolver(rows, cols, grid);
            solver.solve(out);

        } catch (UncoverableAsteriskException e) {
            out.println("-1");
        } catch (IOException e) {
            // Handle potential IO errors
        } finally {
            out.close();
        }
    }

    /**
     * Custom exception to handle cases where an asterisk cannot be covered by any star.
     */
    static class UncoverableAsteriskException extends Exception {}

    /**
     * Represents a star placed on the grid.
     */
    static class Star {
        private final int row;
        private final int col;
        private final int radius;

        public Star(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }

        @Override
        public String toString() {
            // Converting to 1-based indexing for output
            return (row + 1) + " " + (col + 1) + " " + radius;
        }
    }

    /**
     * Core engine to solve the star placement problem.
     */
    static class StarGridSolver {
        private static final int[] ROW_DIRECTIONS = {-1, 1, 0, 0};
        private static final int[] COL_DIRECTIONS = {0, 0, -1, 1};

        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final boolean[][] isCovered;

        // Distance arrays to store how many consecutive '*' are in each direction
        private final int[][] upDist;
        private final int[][] downDist;
        private final int[][] leftDist;
        private final int[][] rightDist;

        public StarGridSolver(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            this.isCovered = new boolean[rows][cols];
            this.upDist = new int[rows][cols];
            this.downDist = new int[rows][cols];
            this.leftDist = new int[rows][cols];
            this.rightDist = new int[rows][cols];
        }

        public void solve(PrintWriter out) throws UncoverableAsteriskException {
            precomputeDistances();

            List<Star> stars = new ArrayList<>();
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '*') {
                        int maxRadius = calculateMaxRadius(r, c);
                        // Only place stars with radius >= 1 as per original logic
                        if (maxRadius >= 1) {
                            markCovered(r, c, maxRadius);
                            stars.add(new Star(r, c, maxRadius));
                        }
                    }
                }
            }

            validateCoverage();

            out.println(stars.size());
            for (Star star : stars) {
                out.println(star);
            }
        }

        /**
         * Precomputes the number of consecutive asterisks in all 4 directions for every cell.
         */
        private void precomputeDistances() {
            // Forward pass for Left and Up
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '*') {
                        leftDist[i][j] = (j > 0) ? leftDist[i][j - 1] + 1 : 1;
                        upDist[i][j] = (i > 0) ? upDist[i - 1][j] + 1 : 1;
                    }
                }
            }
            // Backward pass for Right and Down
            for (int i = rows - 1; i >= 0; i--) {
                for (int j = cols - 1; j >= 0; j--) {
                    if (grid[i][j] == '*') {
                        rightDist[i][j] = (j < cols - 1) ? rightDist[i][j + 1] + 1 : 1;
                        downDist[i][j] = (i < rows - 1) ? downDist[i + 1][j] + 1 : 1;
                    }
                }
            }
        }

        private int calculateMaxRadius(int r, int c) {
            int minLine = Math.min(Math.min(upDist[r][c], downDist[r][c]),
                                   Math.min(leftDist[r][c], rightDist[r][c]));
            return minLine - 1;
        }

        /**
         * Marks the star center and its rays as covered.
         */
        private void markCovered(int r, int c, int radius) {
            isCovered[r][c] = true;
            for (int dir = 0; dir < 4; dir++) {
                for (int step = 1; step <= radius; step++) {
                    int nr = r + ROW_DIRECTIONS[dir] * step;
                    int nc = c + COL_DIRECTIONS[dir] * step;
                    isCovered[nr][nc] = true;
                }
            }
        }

        private void validateCoverage() throws UncoverableAsteriskException {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '*' && !isCovered[i][j]) {
                        throw new UncoverableAsteriskException();
                    }
                }
            }
        }
    }

    /**
     * Utility class for high-performance input reading.
     */
    static class FastReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int curChar;
        private int numChars;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (numChars == -1) throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buffer);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) return -1;
            }
            return buffer[curChar++];
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        private boolean isEndline(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public String nextLine() {
            int c = read();
            while (isEndline(c)) c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isEndline(c));
            return res.toString();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to find a set of "crosses" (plus signs) that cover all '*' cells in a grid.
 * If no such set exists, it outputs -1.
 */
public class Main {

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);

        int height = sc.nextInt();
        int width = sc.nextInt();
        char[][] grid = new char[height][];
        for (int i = 0; i < height; i++) {
            grid[i] = sc.next().toCharArray();
        }

        GridSolver solver = new GridSolver(grid, height, width);
        Optional<List<Cross>> solution = solver.solve();

        try (PrintWriter pw = new PrintWriter(System.out)) {
            if (solution.isEmpty()) {
                pw.println("-1");
            } else {
                List<Cross> crosses = solution.get();
                pw.println(crosses.size());
                for (Cross cross : crosses) {
                    // Output uses 1-based indexing for coordinates
                    pw.printf("%d %d %d%n", cross.row() + 1, cross.col() + 1, cross.radius());
                }
            }
        }
    }

    /**
     * Represents a "cross" centered at (row, col) with a specific radius.
     */
    public record Cross(int row, int col, int radius) {}

    /**
     * Handles the logic for calculating coverage and finding optimal crosses.
     */
    static class GridSolver {
        private final char[][] grid;
        private final int height;
        private final int width;

        GridSolver(char[][] grid, int height, int width) {
            this.grid = grid;
            this.height = height;
            this.width = width;
        }

        public Optional<List<Cross>> solve() {
            int[][] upDist = computeDistances(true, true);
            int[][] downDist = computeDistances(true, false);
            int[][] leftDist = computeDistances(false, true);
            int[][] rightDist = computeDistances(false, false);

            List<Cross> crosses = new ArrayList<>();

            // Difference arrays for 1D coverage tracking on rows and columns
            int[][] rowCoverageDiff = new int[height][width + 1];
            int[][] colCoverageDiff = new int[height + 1][width];

            for (int r = 0; r < height; r++) {
                for (int c = 0; c < width; c++) {
                    if (grid[r][c] != '*') continue;

                    // The radius is the minimum distance to a non-'*' cell in all 4 directions
                    int radius = Math.min(
                        Math.min(leftDist[r][c], rightDist[r][c]),
                        Math.min(upDist[r][c], downDist[r][c])
                    );

                    if (radius >= 1) {
                        crosses.add(new Cross(r, c, radius));

                        // Mark horizontal coverage range [c - radius, c + radius]
                        rowCoverageDiff[r][c - radius]++;
                        rowCoverageDiff[r][c + radius + 1]--;

                        // Mark vertical coverage range [r - radius, r + radius]
                        colCoverageDiff[r - radius][c]++;
                        colCoverageDiff[r + radius + 1][c]--;
                    }
                }
            }

            // Apply prefix sums to difference arrays to reconstruct coverage counts
            applyPrefixSums(rowCoverageDiff, height, width, true);
            applyPrefixSums(colCoverageDiff, height, width, false);

            // Verify if every '*' cell is covered by at least one horizontal or vertical arm
            for (int r = 0; r < height; r++) {
                for (int c = 0; c < width; c++) {
                    if (grid[r][c] == '*' && rowCoverageDiff[r][c] == 0 && colCoverageDiff[r][c] == 0) {
                        return Optional.empty();
                    }
                }
            }

            return Optional.of(crosses);
        }

        private void applyPrefixSums(int[][] diffArray, int h, int w, boolean isRowBased) {
            if (isRowBased) {
                for (int r = 0; r < h; r++) {
                    for (int c = 1; c < w; c++) {
                        diffArray[r][c] += diffArray[r][c - 1];
                    }
                }
            } else {
                for (int c = 0; c < w; c++) {
                    for (int r = 1; r < h; r++) {
                        diffArray[r][c] += diffArray[r - 1][c];
                    }
                }
            }
        }

        /**
         * Calculates consecutive '*' counts in a specific direction.
         * @param vertical true if calculating up/down, false if left/right.
         * @param forward true if scanning from start to end (0 -> max), false otherwise.
         */
        private int[][] computeDistances(boolean vertical, boolean forward) {
            int[][] dists = new int[height][width];
            if (vertical) {
                for (int c = 0; c < width; c++) {
                    int count = 0;
                    int start = forward ? 0 : height - 1;
                    int end = forward ? height : -1;
                    int step = forward ? 1 : -1;
                    for (int r = start; r != end; r += step) {
                        dists[r][c] = count;
                        if (grid[r][c] == '*') count++;
                        else count = 0;
                    }
                }
            } else {
                for (int r = 0; r < height; r++) {
                    int count = 0;
                    int start = forward ? 0 : width - 1;
                    int end = forward ? width : -1;
                    int step = forward ? 1 : -1;
                    for (int c = start; c != end; c += step) {
                        dists[r][c] = count;
                        if (grid[r][c] == '*') count++;
                        else count = 0;
                    }
                }
            }
            return dists;
        }
    }

    /**
     * Efficient input reader for large datasets.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

/**
 * A utility class to ensure passwords meet specific complexity requirements:
 * at least one digit, one uppercase letter, and one lowercase letter.
 */
public class VasyaAndPassword {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int testCaseCount = scanner.nextInt();
        for (int i = 0; i < testCaseCount; i++) {
            if (scanner.hasNext()) {
                String password = scanner.next();
                System.out.println(strengthenPassword(password));
            }
        }

        scanner.close();
    }

    /**
     * Processes a password and modifies it to ensure it contains at least 
     * one digit, one uppercase letter, and one lowercase letter.
     *
     * @param password The original password string.
     * @return The strengthened password string.
     */
    public static String strengthenPassword(String password) {
        char[] chars = password.toCharArray();

        // Address each requirement sequentially.
        // We re-count after each modification to ensure we don't break 
        // a requirement we just fulfilled.
        if (countType(chars, "digit") == 0) {
            int index = findSafeIndexToReplace(chars, "digit");
            chars[index] = '0';
        }

        if (countType(chars, "upper") == 0) {
            int index = findSafeIndexToReplace(chars, "upper");
            chars[index] = 'A';
        }

        if (countType(chars, "lower") == 0) {
            int index = findSafeIndexToReplace(chars, "lower");
            chars[index] = 'a';
        }

        return new String(chars);
    }

    /**
     * Finds the first index in the array that can be replaced with the target type
     * without removing the last existing character of another required type.
     *
     * @param chars The current password character array.
     * @param targetType The type of character we want to add ("digit", "upper", or "lower").
     * @return The index to replace.
     */
    private static int findSafeIndexToReplace(char[] chars, String targetType) {
        int dCount = countType(chars, "digit");
        int uCount = countType(chars, "upper");
        int lCount = countType(chars, "lower");

        for (int i = 0; i < chars.length; i++) {
            char c = chars[i];
            boolean isDigit = Character.isDigit(c);
            boolean isUpper = Character.isUpperCase(c);
            boolean isLower = Character.isLowerCase(c);

            if (targetType.equals("digit")) {
                // Safe if: not already a digit AND (if it's upper, we have >1 upper) AND (if it's lower, we have >1 lower)
                if (!isDigit && (isUpper ? uCount > 1 : true) && (isLower ? lCount > 1 : true)) {
                    return i;
                }
            } else if (targetType.equals("upper")) {
                // Safe if: not already upper AND (if it's digit, we have >1 digit) AND (if it's lower, we have >1 lower)
                if (!isUpper && (isDigit ? dCount > 1 : true) && (isLower ? lCount > 1 : true)) {
                    return i;
                }
            } else if (targetType.equals("lower")) {
                // Safe if: not already lower AND (if it's digit, we have >1 digit) AND (if it's upper, we have >1 upper)
                if (!isLower && (isDigit ? dCount > 1 : true) && (isUpper ? uCount > 1 : true)) {
                    return i;
                }
            }
        }
        return 0; // Fallback to index 0 if no ideal index is found
    }

    /**
     * Counts occurrences of specific character types.
     * 
     * @param chars The character array.
     * @param type The type to count ("digit", "upper", or "lower").
     * @return The count of that type.
     */
    private static int countType(char[] chars, String type) {
        int count = 0;
        for (char c : chars) {
            switch (type) {
                case "digit":
                    if (Character.isDigit(c)) count++;
                    break;
                case "upper":
                    if (Character.isUpperCase(c)) count++;
                    break;
                case "lower":
                    if (Character.isLowerCase(c)) count++;
                    break;
            }
        }
        return count;
    }
}

import java.util.*;
import java.io.*;

/**
 * Main entry point for the program.
 * Handles input/output orchestration.
 */
public class Main {
    public static void main(String[] args) {
        FastReader reader = new FastReader();
        PrintWriter writer = new PrintWriter(System.out);

        int testCases = reader.nextInt();

        for (int i = 0; i < testCases; i++) {
            String input = reader.next();
            String result = StringTransformer.transform(input);
            writer.println(result);
        }

        writer.close();
    }

    /**
     * Holds the statistical analysis of a string's character types.
     */
    static class StringStatistics {
        final int lowerCount;
        final int upperCount;
        final int otherCount;
        final int lastLowerIdx;
        final int lastUpperIdx;
        final int lastOtherIdx;

        StringStatistics(String s) {
            int lower = 0, upper = 0, other = 0;
            int lastLower = -1, lastUpper = -1, lastOther = -1;

            for (int i = 0; i < s.length(); i++) {
                char c = s.charAt(i);
                if (c >= 'a' && c <= 'z') {
                    lower++;
                    lastLower = i;
                } else if (c >= 'A' && c <= 'Z') {
                    upper++;
                    lastUpper = i;
                } else {
                    other++;
                    lastOther = i;
                }
            }

            this.lowerCount = lower;
            this.upperCount = upper;
            this.otherCount = other;
            this.lastLowerIdx = lastLower;
            this.lastUpperIdx = lastUpper;
            this.lastOtherIdx = lastOther;
        }

        boolean hasLower() { return lowerCount > 0; }
        boolean hasUpper() { return upperCount > 0; }
        boolean hasOther() { return otherCount > 0; }
    }

    /**
     * Contains logic to transform strings based on character requirements.
     */
    static class StringTransformer {

        public static String transform(String s) {
            StringStatistics stats = new StringStatistics(s);

            // Case 1: All character types already present
            if (stats.hasLower() && stats.hasUpper() && stats.hasOther()) {
                return s;
            }

            // Case 2: Only lowercase present
            if (stats.hasLower() && !stats.hasUpper() && !stats.hasOther()) {
                return "A1" + s.substring(2);
            }

            // Case 3: Only uppercase present
            if (!stats.hasLower() && stats.hasUpper() && !stats.hasOther()) {
                return "a1" + s.substring(2);
            }

            // Case 4: Only "other" characters present
            if (!stats.hasLower() && !stats.hasUpper() && stats.hasOther()) {
                return "aA" + s.substring(2);
            }

            // Case 5: Uppercase and Other present
            if (!stats.hasLower() && stats.hasUpper() && stats.hasOther()) {
                if (stats.upperCount > 1) {
                    return replaceCharAt(s, stats.lastUpperIdx, 'a');
                } else if (stats.otherCount > 1) {
                    return replaceCharAt(s, stats.lastOtherIdx, 'a');
                }
            }

            // Case 6: Lowercase and Other present
            if (stats.hasLower() && !stats.hasUpper() && stats.hasOther()) {
                if (stats.lowerCount > 1) {
                    return replaceCharAt(s, stats.lastLowerIdx, 'A');
                } else if (stats.otherCount > 1) {
                    return replaceCharAt(s, stats.lastOtherIdx, 'A');
                }
            }

            // Case 7: Lowercase and Uppercase present
            if (stats.hasLower() && stats.hasUpper() && !stats.hasOther()) {
                if (stats.lowerCount > 1) {
                    return replaceCharAt(s, stats.lastLowerIdx, '1');
                } else if (stats.upperCount > 1) {
                    return replaceCharAt(s, stats.lastUpperIdx, '1');
                }
            }

            return s; // Fallback
        }

        private static String replaceCharAt(String s, int index, char newChar) {
            if (index < 0 || index >= s.length()) return s;
            return s.substring(0, index) + newChar + s.substring(index + 1);
        }
    }

    /**
     * Utility class for fast I/O operations.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solution to ensure a string contains at least one lowercase letter, 
 * one uppercase letter, and one digit.
 */
public class Codeforces {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int testCases = reader.nextInt();
            while (testCases-- > 0) {
                String input = reader.next();
                out.println(processString(input));
            }
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Processes the string to ensure it contains at least one lowercase letter,
     * one uppercase letter, and one digit by prepending missing required characters.
     *
     * @param s The input string.
     * @return A modified string satisfying the requirements.
     */
    private static String processString(String s) {
        boolean hasLower = false;
        boolean hasUpper = false;
        boolean hasDigit = false;

        // Single pass to check for required character types
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (Character.isLowerCase(c)) {
                hasLower = true;
            } else if (Character.isUpperCase(c)) {
                hasUpper = true;
            } else if (Character.isDigit(c)) {
                hasDigit = true;
            }
        }

        StringBuilder result = new StringBuilder();

        // Prepend missing types. Prepending is the most robust way to 
        // ensure requirements are met without complex replacement logic.
        if (!hasLower) {
            result.append('a');
        }
        if (!hasUpper) {
            result.append('A');
        }
        if (!hasDigit) {
            result.append('1');
        }

        result.append(s);
        return result.toString();
    }

    /**
     * Fast I/O utility class for efficient reading.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.io.*;
