/**
 * Entry point for the application.
 * Handles file-based I/O fallback and orchestrates the execution.
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;

        try {
            File inputFile = new File("input.txt");
            if (inputFile.exists()) {
                inputStream = new FileInputStream(inputFile);
                outputStream = new FileOutputStream("output.txt");
            }
        } catch (FileNotFoundException e) {
            // Fallback to System.in and System.out is already set
        }

        try (FastReader reader = new FastReader(inputStream);
             PrintWriter writer = new PrintWriter(new BufferedOutputStream(outputStream))) {

            int testCases = reader.nextInt();
            PasswordSolver solver = new PasswordSolver();

            for (int i = 0; i < testCases; i++) {
                String inputString = reader.next();
                if (inputString != null) {
                    writer.println(solver.solve(inputString));
                }
            }
            writer.flush();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

/**
 * Contains the domain logic for validating and transforming strings 
 * to meet password requirements.
 */
class PasswordSolver {
    private static final String[] SINGLE_REPLACEMENTS = {"0", "a", "A"};
    private static final String[] DOUBLE_REPLACEMENTS = {"0a", "0A", "Aa"};
    private static final String TRIPLE_REPLACEMENT = "0aA";

    /**
     * Finds the shortest transformation (via replacement) that satisfies 
     * the requirement of having at least one digit, one lowercase, and one uppercase letter.
     * 
     * @param s The input string.
     * @return The transformed string, or an empty string if no solution is found.
     */
    public String solve(String s) {
        String result;

        // 1. Check if already valid (0 substitutions)
        if ((result = tryZeroSubstitutions(s)) != null) return result;

        // 2. Try replacing 1 character
        if ((result = tryOneSubstitution(s)) != null) return result;

        // 3. Try replacing 2 characters
        if ((result = tryTwoSubstitutions(s)) != null) return result;

        // 4. Try replacing 3 characters
        return tryThreeSubstitutions(s);
    }

    private String tryZeroSubstitutions(String s) {
        return isValid(s) ? s : null;
    }

    private String tryOneSubstitution(String s) {
        for (int i = 0; i < s.length(); i++) {
            for (String replacement : SINGLE_REPLACEMENTS) {
                String candidate = replace(s, i, 1, replacement);
                if (isValid(candidate)) return candidate;
            }
        }
        return null;
    }

    private String tryTwoSubstitutions(String s) {
        for (int i = 0; i + 1 < s.length(); i++) {
            for (String replacement : DOUBLE_REPLACEMENTS) {
                String candidate = replace(s, i, 2, replacement);
                if (isValid(candidate)) return candidate;
            }
        }
        return null;
    }

    private String tryThreeSubstitutions(String s) {
        for (int i = 0; i + 2 < s.length(); i++) {
            String candidate = replace(s, i, 3, TRIPLE_REPLACEMENT);
            if (isValid(candidate)) return candidate;
        }
        return "";
    }

    /**
     * Checks if a string contains at least one digit, one lowercase, and one uppercase letter.
     */
    private boolean isValid(String s) {
        boolean hasDigit = false;
        boolean hasLower = false;
        boolean hasUpper = false;

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (Character.isDigit(c)) hasDigit = true;
            else if (Character.isLowerCase(c)) hasLower = true;
            else if (Character.isUpperCase(c)) hasUpper = true;

            if (hasDigit && hasLower && hasUpper) return true;
        }
        return false;
    }

    /**
     * Helper to replace a segment of a string.
     */
    private String replace(String original, int start, int length, String replacement) {
        return original.substring(0, start) + replacement + original.substring(start + length);
    }
}

