class StringComplexityFixer {

    /**
     * Applies transformation rules to a string to satisfy character type requirements.
     * 
     * @param input The original string.
     * @return The transformed string.
     */
    public String fixComplexity(String input) {
        StringMetrics metrics = new StringMetrics(input);

        // Rule Group 1: Missing two types (Replace prefix)
        if (metrics.lowerCount == 0 && metrics.upperCount == 0) {
            return "aA" + input.substring(2);
        }
        if (metrics.upperCount == 0 && metrics.digitCount == 0) {
            return "A1" + input.substring(2);
        }
        if (metrics.digitCount == 0 && metrics.lowerCount == 0) {
            return "a1" + input.substring(2);
        }

        // Rule Group 2: Missing one type where another type has a count of exactly 1
        // (Replace a specific character at its last known index)
        if (metrics.lowerCount == 0 && metrics.upperCount == 1) {
            return replaceChar(input, metrics.lastDigitIdx, 'a');
        }
        if (metrics.lowerCount == 1 && metrics.upperCount == 0) {
            return replaceChar(input, metrics.lastDigitIdx, 'A');
        }
        if (metrics.upperCount == 0 && metrics.digitCount == 1) {
            return replaceChar(input, metrics.lastLowerIdx, 'A');
        }
        if (metrics.upperCount == 1 && metrics.digitCount == 0) {
            return replaceChar(input, metrics.lastLowerIdx, '1');
        }
        if (metrics.digitCount == 0 && metrics.lowerCount == 1) {
            return replaceChar(input, metrics.lastUpperIdx, '1');
        }
        if (metrics.digitCount == 1 && metrics.lowerCount == 0) {
            return replaceChar(input, metrics.lastUpperIdx, 'a');
        }

        // Rule Group 3: Missing one type (Fallback replacement)
        if (metrics.lowerCount == 0) {
            return replaceChar(input, metrics.lastDigitIdx, 'a');
        }
        if (metrics.upperCount == 0) {
            return replaceChar(input, metrics.lastDigitIdx, 'A');
        }
        if (metrics.digitCount == 0) {
            return replaceChar(input, metrics.lastLowerIdx, '1');
        }

        return input;
    }

    private String replaceChar(String s, int index, char newChar) {
        StringBuilder sb = new StringBuilder(s);
        sb.setCharAt(index, newChar);
        return sb.toString();
    }

    /**
     * Helper class to encapsulate character statistics of a string.
     */
    private static class StringMetrics {
        final int lowerCount;
        final int upperCount;
        final int digitCount;
        final int lastLowerIdx;
        final int lastUpperIdx;
        final int lastDigitIdx;

        StringMetrics(String s) {
            int lc = 0, uc = 0, dc = 0;
            int li = 0, ui = 0, di = 0;

            for (int i = 0; i < s.length(); i++) {
                char c = s.charAt(i);
                if (Character.isLowerCase(c)) {
                    lc++;
                    li = i;
                } else if (Character.isUpperCase(c)) {
                    uc++;
                    ui = i;
                } else if (Character.isDigit(c)) {
                    dc++;
                    di = i;
                }
            }

            this.lowerCount = lc;
            this.upperCount = uc;
            this.digitCount = dc;
            this.lastLowerIdx = li;
            this.lastUpperIdx = ui;
            this.lastDigitIdx = di;
        }
    }
}

