/**
 * Handles the logic for finding a valid version of a password
 * by attempting specific pattern substitutions.
 */
class PasswordFixer {
    private static final String[] REPLACEMENT_PATTERNS = {
        "a", "A", "1", "aA", "a1", "A1", "aA1"
    };

    private final PasswordValidator validator;

    public PasswordFixer(PasswordValidator validator) {
        this.validator = validator;
    }

    /**
     * Returns the original password if valid, otherwise attempts to find 
     * a valid version using substitution patterns.
     * 
     * @param password The password to evaluate.
     * @return A valid version of the password, or null if no solution is found.
     */
    public String findValidPassword(String password) {
        if (validator.isValid(password)) {
            return password;
        }

        return attemptSubstitutions(password);
    }

    private String attemptSubstitutions(String password) {
        for (String pattern : REPLACEMENT_PATTERNS) {
            int patternLength = pattern.length();

            // Attempt to replace every possible substring of matching length with the pattern
            for (int i = 0; i <= password.length() - patternLength; i++) {
                String modified = substitute(password, i, pattern);
                if (validator.isValid(modified)) {
                    return modified;
                }
            }
        }
        return null;
    }

    private String substitute(String text, int startIndex, String replacement) {
        int lengthToReplace = replacement.length();
        String prefix = text.substring(0, startIndex);
        String suffix = text.substring(startIndex + lengthToReplace);
        return prefix + replacement + suffix;
    }
}

/**
 * Responsible for validating password complexity requirements.
 */
class PasswordValidator {

    /**
     * Checks if the password contains at least one lowercase letter, 
     * one uppercase letter, and one digit.
     * 
     * @param password The string to validate.
     * @return true if all requirements are met.
     */
    public boolean isValid(String password) {
        if (password == null || password.isEmpty()) {
            return false;
        }

        boolean hasLower = false;
        boolean hasUpper = false;
        boolean hasDigit = false;

        for (char c : password.toCharArray()) {
            if (Character.isLowerCase(c)) {
                hasLower = true;
            } else if (Character.isUpperCase(c)) {
                hasUpper = true;
            } else if (Character.isDigit(c)) {
                hasDigit = true;
            }

            // Optimization: If all conditions are met, we can stop checking early
            if (hasLower && hasUpper && hasDigit) {
                return true;
            }
        }

        return hasLower && hasUpper && hasDigit;
    }
}

import java.util.*;
import java.io.*;

/**
 * A utility to balance a string so that it contains at least one 
 * uppercase letter, one lowercase letter, and one digit.
 */
class StringTypeBalancer {

    private enum CharType {
        UPPERCASE, LOWERCASE, DIGIT
    }

    /**
     * Transforms the input string to ensure it contains at least one 
     * of each required category (Upper, Lower, Digit) using minimum changes.
     * 
     * @param input The original string.
     * @return A modified string meeting the requirements.
     */
    public String balance(String input) {
        if (input == null || input.isEmpty()) {
            return input;
        }

        char[] chars = input.toCharArray();
        List<Integer> upperIndices = new ArrayList<>();
        List<Integer> lowerIndices = new ArrayList<>();
        List<Integer> digitIndices = new ArrayList<>();

        // Categorize existing characters
        for (int i = 0; i < chars.length; i++) {
            char c = chars[i];
            if (Character.isUpperCase(c)) {
                upperIndices.add(i);
            } else if (Character.isLowerCase(c)) {
                lowerIndices.add(i);
            } else if (Character.isDigit(c)) {
                digitIndices.add(i);
            }
        }

        int typesPresent = 0;
        if (!upperIndices.isEmpty()) typesPresent++;
        if (!lowerIndices.isEmpty()) typesPresent++;
        if (!digitIndices.isEmpty()) typesPresent++;

        // Case 1: All types already present
        if (typesPresent == 3) {
            return input;
        }

        // Case 2: Only one type is present. 
        // We must replace the first two characters to satisfy the other two types.
        if (typesPresent == 1) {
            applyMissingTwoTypes(chars, upperIndices, lowerIndices, digitIndices);
        } 
        // Case 3: Two types are present.
        // We find a "redundant" character in one of the existing categories and replace it.
        else {
            applyMissingOneType(chars, upperIndices, lowerIndices, digitIndices);
        }

        return new String(chars);
    }

    private void applyMissingTwoTypes(char[] chars, List<Integer> upper, List<Integer> lower, List<Integer> digit) {
        if (!upper.isEmpty()) {
            // Missing Lower and Digit
            chars[0] = 'a';
            chars[1] = '0';
        } else if (!lower.isEmpty()) {
            // Missing Upper and Digit
            chars[0] = 'A';
            chars[1] = '0';
        } else {
            // Missing Upper and Lower
            chars[0] = 'A';
            chars[1] = 'a';
        }
    }

    private void applyMissingOneType(char[] chars, List<Integer> upper, List<Integer> lower, List<Integer> digit) {
        if (upper.isEmpty() || lower.isEmpty() || digit.isEmpty()) {
            // This part handles finding which single type is missing
            if (upper.isEmpty()) replaceOne(chars, 'A', lower, digit);
            else if (lower.isEmpty()) replaceOne(chars, 'a', upper, digit);
            else replaceOne(chars, '0', upper, lower);
        }
    }

    private void replaceOne(char[] chars, char replacement, List<Integer> primary, List<Integer> secondary) {
        // Search for a category that has more than one character to replace one without losing the category
        if (primary.size() > 1) {
            chars[primary.get(0)] = replacement;
        } else if (secondary.size() > 1) {
            chars[secondary.get(0)] = replacement;
        } else {
            // Fallback for very short strings (though problem logic implies N >= 3)
            chars[0] = replacement;
        }
    }
}

