import java.io.*;
import java.util.*;

/**
 * Main entry point for the String Transformation program.
 */
public class Main {
    public static void main(String[] args) {
        try (InputStream inputStream = System.in;
             PrintWriter out = new PrintWriter(System.out)) {

            InputReader in = new InputReader(inputStream);
            TaskA solver = new TaskA();
            solver.solve(in, out);
            out.flush();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * Handles the core logic of solving the task.
     */
    static class TaskA {

        public void solve(InputReader in, PrintWriter out) {
            int testCases = in.nextInt();
            while (testCases-- > 0) {
                String input = in.next();
                out.println(transformString(input));
            }
        }

        /**
         * Decides which transformation to apply based on character composition.
         */
        private String transformString(String str) {
            StringMetrics metrics = new StringMetrics(str);

            // Case 1: All three types (Upper, Lower, Other) are present
            if (metrics.hasAllTypes()) {
                return str;
            }

            // Case 2: Only one type is present
            if (metrics.isOnlyUpper()) return applyPrefix(str, "a3");
            if (metrics.isOnlyLower()) return applyPrefix(str, "A3");
            if (metrics.isOnlyOther()) return applyPrefix(str, "aA");

            // Case 3: Exactly two types are present
            if (metrics.isUpperLower()) {
                return handleUpperLower(str, metrics);
            }
            if (metrics.isLowerOther()) {
                return handleLowerOther(str, metrics);
            }
            if (metrics.isUpperOther()) {
                return handleUpperOther(str, metrics);
            }

            return str;
        }

        private String handleUpperLower(String str, StringMetrics m) {
            if (m.lowerCount < m.upperCount) {
                return replaceFirst(str, TaskA::isUpper, '1');
            } else {
                return replaceFirst(str, TaskA::isLower, '1');
            }
        }

        private String handleLowerOther(String str, StringMetrics m) {
            if (m.lowerCount > m.otherCount) {
                return replaceFirst(str, TaskA::isLower, 'A');
            } else {
                return replaceFirst(str, TaskA::isDigit, 'A');
            }
        }

        private String handleUpperOther(String str, StringMetrics m) {
            if (m.upperCount > m.otherCount) {
                return replaceFirst(str, TaskA::isUpper, 'a');
            } else {
                return replaceFirst(str, TaskA::isDigit, 'a');
            }
        }

        private String replaceFirst(String str, java.util.function.Predicate<Character> condition, char replacement) {
            StringBuilder sb = new StringBuilder(str);
            for (int i = 0; i < sb.length(); i++) {
                if (condition.test(sb.charAt(i))) {
                    sb.setCharAt(i, replacement);
                    break;
                }
            }
            return sb.toString();
        }

        private String applyPrefix(String str, String prefix) {
            StringBuilder sb = new StringBuilder(str);
            // Safety check for short strings to prevent IndexOutOfBounds
            int end = Math.min(sb.length(), 2);
            sb.replace(0, end, prefix);
            return sb.toString();
        }

        // Character type definitions based on original logic
        private static boolean isUpper(char c) { return c >= 'A' && c <= 'Z'; }
        private static boolean isLower(char c) { return c >= 'a' && c <= 'z'; }
        private static boolean isDigit(char c) { return c >= '0' && c <= '9'; }
    }

    /**
     * Data class to store and analyze character distribution.
     */
    static class StringMetrics {
        final int upperCount;
        final int lowerCount;
        final int otherCount;

        StringMetrics(String str) {
            int u = 0, l = 0, o = 0;
            for (char c : str.toCharArray()) {
                if (c >= 'A' && c <= 'Z') u++;
                else if (c >= 'a' && c <= 'z') l++;
                else o++;
            }
            this.upperCount = u;
            this.lowerCount = l;
            this.otherCount = o;
        }

        boolean hasAllTypes() { return upperCount > 0 && lowerCount > 0 && otherCount > 0; }
        boolean isOnlyUpper() { return upperCount > 0 && lowerCount == 0 && otherCount == 0; }
        boolean isOnlyLower() { return lowerCount > 0 && upperCount == 0 && otherCount == 0; }
        boolean isOnlyOther() { return otherCount > 0 && upperCount == 0 && lowerCount == 0; }
        boolean isUpperLower() { return upperCount > 0 && lowerCount > 0 && otherCount == 0; }
        boolean isLowerOther() { return lowerCount > 0 && otherCount > 0 && upperCount == 0; }
        boolean isUpperOther() { return upperCount > 0 && otherCount > 0 && lowerCount == 0; }
    }

    /**
     * Fast I/O utility class.
     */
    static class InputReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (numChars == -1) throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buffer);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) return -1;
            }
            return buffer[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res = res * 10 + (c & 15);
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.util.Scanner;

/**
 * A utility to ensure strings contain at least one digit, 
 * one lowercase letter, and one uppercase letter.
 */
public class StringDiversityFixer {

    private static final char DIGIT_REPLACEMENT = '0';
    private static final char LOWER_REPLACEMENT = 'a';
    private static final char UPPER_REPLACEMENT = 'A';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int testCases = scanner.nextInt();
        for (int t = 0; t < testCases; t++) {
            if (scanner.hasNext()) {
                String input = scanner.next();
                System.out.println(transformString(input));
            }
        }
        scanner.close();
    }

    /**
     * Transforms the input string to ensure it contains at least one 
     * digit, one lowercase, and one uppercase character.
     *
     * @param input The original string.
     * @return The modified string.
     */
    public static String transformString(String input) {
        if (input == null || input.isEmpty()) {
            return input;
        }

        char[] chars = input.toCharArray();
        StringStats stats = StringStats.analyze(chars);

        int presentTypeCount = stats.getPresentTypeCount();

        if (presentTypeCount == 3) {
            return input;
        } else if (presentTypeCount == 2) {
            return new String(fixMissingOneType(chars, stats));
        } else {
            return new String(fixMissingTwoTypes(chars, stats));
        }
    }

    /**
     * Handles cases where exactly one type of character is missing.
     */
    private static char[] fixMissingOneType(char[] chars, StringStats stats) {
        char targetChar;
        if (stats.digitCount == 0) {
            targetChar = DIGIT_REPLACEMENT;
            // Try to replace a character of an existing type that has more than one occurrence
            if (stats.lowerCount > 1) chars[stats.lastLowerIndex] = targetChar;
            else if (stats.upperCount > 1) chars[stats.lastUpperIndex] = targetChar;
            else chars[0] = targetChar; // Fallback: replace first char
        } else if (stats.lowerCount == 0) {
            targetChar = LOWER_REPLACEMENT;
            if (stats.digitCount > 1) chars[stats.lastDigitIndex] = targetChar;
            else if (stats.upperCount > 1) chars[stats.lastUpperIndex] = targetChar;
            else chars[0] = targetChar;
        } else { // upperCount == 0
            targetChar = UPPER_REPLACEMENT;
            if (stats.digitCount > 1) chars[stats.lastDigitIndex] = targetChar;
            else if (stats.lowerCount > 1) chars[stats.lastLowerIndex] = targetChar;
            else chars[0] = targetChar;
        }
        return chars;
    }

    /**
     * Handles cases where two types of characters are missing.
     */
    private static char[] fixMissingTwoTypes(char[] chars, StringStats stats) {
        // If string is too short to add two types, we can only add what we can fit
        if (chars.length < 2) {
            if (chars.length == 1) {
                chars[0] = (stats.digitCount > 0) ? LOWER_REPLACEMENT : DIGIT_REPLACEMENT;
            }
            return chars;
        }

        if (stats.digitCount > 0) {
            // Only digits present
            chars[0] = LOWER_REPLACEMENT;
            chars[1] = UPPER_REPLACEMENT;
        } else if (stats.lowerCount > 0) {
            // Only lowercase present
            chars[0] = DIGIT_REPLACEMENT;
            chars[1] = UPPER_REPLACEMENT;
        } else {
            // Only uppercase present
            chars[0] = DIGIT_REPLACEMENT;
            chars[1] = LOWER_REPLACEMENT;
        }
        return chars;
    }

    /**
     * Helper class to store character frequency and position metadata.
     */
    private static class StringStats {
        int digitCount = 0;
        int lowerCount = 0;
        int upperCount = 0;
        int lastDigitIndex = -1;
        int lastLowerIndex = -1;
        int lastUpperIndex = -1;

        static StringStats analyze(char[] chars) {
            StringStats stats = new StringStats();
            for (int i = 0; i < chars.length; i++) {
                char c = chars[i];
                if (Character.isDigit(c)) {
                    stats.digitCount++;
                    stats.lastDigitIndex = i;
                } else if (Character.isLowerCase(c)) {
                    stats.lowerCount++;
                    stats.lastLowerIndex = i;
                } else if (Character.isUpperCase(c)) {
                    stats.upperCount++;
                    stats.lastUpperIndex = i;
                }
            }
            return stats;
        }

        int getPresentTypeCount() {
            int count = 0;
            if (digitCount > 0) count++;
            if (lowerCount > 0) count++;
            if (upperCount > 0) count++;
            return count;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Solution to find the minimal modifications required to make a string "secure".
 * A secure string must contain at least one uppercase letter, one lowercase letter, and one digit.
 */
public class PasswordSecuritySolution {

    public static void main(String[] args) {
        PasswordSecuritySolution solution = new PasswordSecuritySolution();
        solution.run();
    }

    /**
     * Orchestrates the execution of the program.
     */
    public void run() {
        FastReader reader = new FastReader();
        try {
            int testCases = reader.nextInt();
            for (int t = 0; t < testCases; t++) {
                String input = reader.next();
                System.out.println(findSecureVersion(input));
            }
        } catch (Exception e) {
            // In a real application, use a logger.
            System.err.println("Error processing input: " + e.getMessage());
        }
    }

    /**
     * Checks if a string satisfies the security requirements:
     * Contains at least one uppercase, one lowercase, and one digit.
     *
     * @param s The string to validate.
     * @return true if secure, false otherwise.
     */
    private boolean isSecure(String s) {
        boolean hasUppercase = false;
        boolean hasLowercase = false;
        boolean hasDigit = false;

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (Character.isUpperCase(c)) hasUppercase = true;
            else if (Character.isLowerCase(c)) hasLowercase = true;
            else if (Character.isDigit(c)) hasDigit = true;

            // Optimization: Early return if all conditions are satisfied
            if (hasUppercase && hasLowercase && hasDigit) {
                return true;
            }
        }
        return false;
    }

    /**
     * Attempts to find a secure version of the string by making minimal modifications.
     * Priority is given to single-character replacements, then two-character replacements.
     *
     * @param s The original string.
     * @return The first secure variant found, or the original string if no modification works.
     */
    private String findSecureVersion(String s) {
        if (isSecure(s)) {
            return s;
        }

        // Strategy 1: Try replacing a single character with 'A', 'a', or '1'
        char[] singleCharReplacements = {'A', 'a', '1'};
        for (int i = 0; i < s.length(); i++) {
            for (char replacement : singleCharReplacements) {
                String candidate = replaceCharAt(s, i, replacement);
                if (isSecure(candidate)) {
                    return candidate;
                }
            }
        }

        // Strategy 2: Try replacing two adjacent characters with "Aa", "A1", or "a1"
        String[] doubleCharReplacements = {"Aa", "A1", "a1"};
        for (int i = 0; i < s.length() - 1; i++) {
            for (String replacement : doubleCharReplacements) {
                String candidate = replaceAtRange(s, i, i + 2, replacement);
                if (isSecure(candidate)) {
                    return candidate;
                }
            }
        }

        return s;
    }

    private String replaceCharAt(String s, int index, char replacement) {
        StringBuilder sb = new StringBuilder(s);
        sb.setCharAt(index, replacement);
        return sb.toString();
    }

    private String replaceAtRange(String s, int start, int end, String replacement) {
        StringBuilder sb = new StringBuilder(s);
        sb.replace(start, end, replacement);
        return sb.toString();
    }

    /**
     * Inner class for fast I/O operations.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader() {
            this.reader = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.util.Optional;
import java.util.Scanner;

/**
 * Responsible for validating if a string meets specific complexity requirements:
 * contains at least one lowercase letter, one uppercase letter, and one digit.
 */
class PasswordValidator {

    /**
     * Validates the complexity of the given sequence.
     *
     * @param sequence The character sequence to validate.
     * @return true if the sequence contains lowercase, uppercase, and a digit.
     */
    public boolean isValid(CharSequence sequence) {
        boolean hasLowercase = false;
        boolean hasUppercase = false;
        boolean hasDigit = false;

        for (int i = 0; i < sequence.length(); i++) {
            char c = sequence.charAt(i);
            if (Character.isLowerCase(c)) {
                hasLowercase = true;
            } else if (Character.isUpperCase(c)) {
                hasUppercase = true;
            } else if (Character.isDigit(c)) {
                hasDigit = true;
            }

            // Early exit if all requirements are satisfied
            if (hasLowercase && hasUppercase && hasDigit) {
                return true;
            }
        }
        return false;
    }
}

/**
 * Handles the logic for transforming a string to meet complexity requirements.
 */
class PasswordTransformationService {
    private final PasswordValidator validator;

    private static final char[] SINGLE_CHAR_REPLACEMENTS = {'a', 'A', '9'};
    private static final String[] DOUBLE_CHAR_REPLACEMENTS = {"aA", "a9", "A9"};

    public PasswordTransformationService(PasswordValidator validator) {
        this.validator = validator;
    }

    /**
     * Attempts to find a valid modification of the input string.
     * It first tries single-character replacements, then double-character replacements.
     *
     * @param sb The StringBuilder containing the input string.
     * @return An Optional containing the valid string if found, otherwise empty.
     */
    public Optional<String> findFirstValidTransformation(StringBuilder sb) {
        // 1. Check if the string is already valid
        if (validator.isValid(sb)) {
            return Optional.of(sb.toString());
        }

        // 2. Try single character replacements
        Optional<String> singleReplacement = trySingleCharReplacements(sb);
        if (singleReplacement.isPresent()) {
            return singleReplacement;
        }

        // 3. Try double character replacements
        return tryDoubleCharReplacements(sb);
    }

    private Optional<String> trySingleCharReplacements(StringBuilder sb) {
        for (int i = 0; i < sb.length(); i++) {
            char originalChar = sb.charAt(i);

            for (char replacement : SINGLE_CHAR_REPLACEMENTS) {
                sb.setCharAt(i, replacement);
                if (validator.isValid(sb)) {
                    return Optional.of(sb.toString());
                }
            }
            // Backtrack to original character before moving to next index
            sb.setCharAt(i, originalChar);
        }
        return Optional.empty();
    }

    private Optional<String> tryDoubleCharReplacements(StringBuilder sb) {
        for (int i = 0; i < sb.length() - 1; i++) {
            String originalSub = sb.substring(i, i + 2);

            for (String replacement : DOUBLE_CHAR_REPLACEMENTS) {
                sb.replace(i, i + 2, replacement);
                if (validator.isValid(sb)) {
                    return Optional.of(sb.toString());
                }
            }
            // Backtrack to original substring before moving to next index
            sb.replace(i, i + 2, originalSub);
        }
        return Optional.empty();
    }
}

public class Main {

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int testCases = scanner.nextInt();
            PasswordValidator validator = new PasswordValidator();
            PasswordTransformationService transformationService = new PasswordTransformationService(validator);

            while (testCases-- > 0) {
                if (scanner.hasNext()) {
                    String input = scanner.next();
                    StringBuilder sb = new StringBuilder(input);

                    transformationService.findFirstValidTransformation(sb)
                            .ifPresent(System.out::println);
                }
            }
        }
    }
}

import java.util.Scanner;

/**
 * A utility to transform strings to ensure they meet specific character requirements:
 * at least one lowercase letter, one uppercase letter, and one digit.
 */
public class Solution {

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int testCases = scanner.nextInt();
            scanner.nextLine(); // Consume the newline character

            for (int i = 0; i < testCases; i++) {
                if (scanner.hasNextLine()) {
                    String input = scanner.nextLine();
                    System.out.println(transformString(input));
                }
            }
        }
    }

    /**
     * Transforms the input string based on the presence of lowercase, uppercase, and digit characters.
     * 
     * @param input The original string.
     * @return The transformed string satisfying character requirements.
     */
    public static String transformString(String input) {
        if (input == null || input.isEmpty()) {
            return input;
        }

        StringStats stats = new StringStats(input);

        // Case 1: Missing both lowercase and uppercase characters
        if (stats.lowercaseCount == 0 && stats.uppercaseCount == 0) {
            return "aA" + getSafeSubstring(input, 2);
        }

        // Case 2: Missing both lowercase and digit characters
        if (stats.lowercaseCount == 0 && stats.digitCount == 0) {
            return "a1" + getSafeSubstring(input, 2);
        }

        // Case 3: Missing both uppercase and digit characters
        if (stats.digitCount == 0 && stats.uppercaseCount == 0) {
            return "1A" + getSafeSubstring(input, 2);
        }

        // Case 4: Missing lowercase characters
        if (stats.lowercaseCount == 0) {
            // Replace last digit if multiple exist, otherwise replace last uppercase
            int targetIdx = (stats.digitCount > 1) ? stats.lastDigitIdx : stats.lastUppercaseIdx;
            return replaceCharAt(input, targetIdx, 'a');
        }

        // Case 5: Missing uppercase characters
        if (stats.uppercaseCount == 0) {
            // Replace last digit if multiple exist, otherwise replace last lowercase
            int targetIdx = (stats.digitCount > 1) ? stats.lastDigitIdx : stats.lastLowercaseIdx;
            return replaceCharAt(input, targetIdx, 'A');
        }

        // Case 6: Missing digit characters
        if (stats.digitCount == 0) {
            // Replace last uppercase if multiple exist, otherwise replace last lowercase
            int targetIdx = (stats.uppercaseCount > 1) ? stats.lastUppercaseIdx : stats.lastLowercaseIdx;
            return replaceCharAt(input, targetIdx, '1');
        }

        // Default: Requirements already met
        return input;
    }

    /**
     * Returns a substring starting from the specified index, 
     * returning an empty string if the index is out of bounds.
     */
    private static String getSafeSubstring(String s, int start) {
        return (s.length() > start) ? s.substring(start) : "";
    }

    /**
     * Replaces a character at a specific index in a string.
     */
    private static String replaceCharAt(String s, int index, char replacement) {
        if (index < 0 || index >= s.length()) {
            return s;
        }
        char[] chars = s.toCharArray();
        chars[index] = replacement;
        return new String(chars);
    }

    /**
     * Helper class to analyze and store character distribution of a string.
     */
    private static class StringStats {
        final int lowercaseCount;
        final int uppercaseCount;
        final int digitCount;
        final int lastLowercaseIdx;
        final int lastUppercaseIdx;
        final int lastDigitIdx;

        StringStats(String s) {
            int low = 0, up = 0, dig = 0;
            int lastLow = -1, lastUp = -1, lastDig = -1;

            for (int i = 0; i < s.length(); i++) {
                char c = s.charAt(i);
                if (Character.isLowerCase(c)) {
                    low++;
                    lastLow = i;
                } else if (Character.isUpperCase(c)) {
                    up++;
                    lastUp = i;
                } else if (Character.isDigit(c)) {
                    dig++;
                    lastDig = i;
                }
            }

            this.lowercaseCount = low;
            this.uppercaseCount = up;
            this.digitCount = dig;
            this.lastLowercaseIdx = lastLow;
            this.lastUppercaseIdx = lastUp;
            this.lastDigitIdx = lastDig;
        }
    }
}

