/**
 * Handles the logic for validating and repairing passwords based on complexity rules.
 */
class PasswordFixer {
    // Pre-defined combinations of characters to attempt for repairs.
    // We attempt replacements of length 1, then 2, then 3 to find the minimal change.
    private static final String[][] REPLACEMENT_OPTIONS = {
            {"a", "A", "1"},         // Length 1
            {"aA", "a1", "A1"},      // Length 2
            {"aA1"}                  // Length 3
    };

    /**
     * Ensures the password contains at least one lowercase letter, 
     * one uppercase letter, and one digit.
     * 
     * @param password The string to validate.
     * @return The valid password, or a repaired version if the original was invalid.
     */
    public String fixPassword(String password) {
        if (isValid(password)) {
            return password;
        }

        // Attempt to replace substrings of increasing lengths (1 to 3)
        for (int lenIdx = 0; lenIdx < REPLACEMENT_OPTIONS.length; lenIdx++) {
            int targetLen = lenIdx + 1;
            String[] options = REPLACEMENT_OPTIONS[lenIdx];

            for (int i = 0; i <= password.length() - targetLen; i++) {
                for (String replacement : options) {
                    String candidate = buildCandidate(password, i, targetLen, replacement);
                    if (isValid(candidate)) {
                        return candidate;
                    }
                }
            }
        }

        return password;
    }

    /**
     * Checks if the password meets the security requirements.
     */
    private boolean isValid(String password) {
        return hasLowerCase(password) && 
               hasUpperCase(password) && 
               hasDigit(password);
    }

    private boolean hasLowerCase(String s) {
        return s.chars().anyMatch(Character::isLowerCase);
    }

    private boolean hasUpperCase(String s) {
        return s.chars().anyMatch(Character::isUpperCase);
    }

    private boolean hasDigit(String s) {
        return s.chars().anyMatch(Character::isDigit);
    }

    /**
     * Constructs a new string by replacing a specific segment of the original.
     */
    private String buildCandidate(String original, int startIndex, int lengthToRemove, String replacement) {
        return original.substring(0, startIndex) + 
               replacement + 
               original.substring(startIndex + lengthToRemove);
    }
}

/**
 * High-performance input reader for reading tokens from an InputStream.
 */
class FastReader {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    public FastReader(InputStream in) {
        this.reader = new BufferedReader(new InputStreamReader(in));
    }

    /**
     * Retrieves the next token from the input stream.
     * 
     * @return The next token, or null if end of stream is reached.
     */
    public String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            String line = readLine();
            if (line == null) return null;
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    private String readLine() {
        try {
            return reader.readLine();
        } catch (IOException e) {
            throw new RuntimeException("Error reading input stream", e);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solution to find the shortest substring replacement that ensures 
 * the resulting string contains at least one digit, one uppercase letter, 
 * and one lowercase letter.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        TaskSolver solver = new TaskSolver();
        solver.solve(reader, writer);

        writer.flush();
        writer.close();
    }

    /**
     * Fast I/O utility for efficient reading of large datasets.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            return next != null ? Integer.parseInt(next) : 0;
        }
    }

    /**
     * Encapsulates the problem-solving logic.
     */
    static class TaskSolver {

        /**
         * Processes all test cases.
         */
        public void solve(FastReader in, PrintWriter out) {
            int t = in.nextInt();
            while (t-- > 0) {
                String s = in.next();
                if (s != null) {
                    out.println(findOptimalString(s));
                }
            }
        }

        /**
         * Finds the optimal string by iterating through all possible substring windows.
         * Uses prefix sums to maintain O(N^2) complexity.
         *
         * @param s The input string.
         * @return The shortest resulting string after replacement.
         */
        private String findOptimalString(String s) {
            int n = s.length();

            // Prefix sum arrays to count character types in O(1) for any range.
            int[] digitPref = new int[n + 1];
            int[] upperPref = new int[n + 1];
            int[] lowerPref = new int[n + 1];

            for (int i = 0; i < n; i++) {
                char c = s.charAt(i);
                digitPref[i + 1] = digitPref[i] + (Character.isDigit(c) ? 1 : 0);
                upperPref[i + 1] = upperPref[i] + (Character.isUpperCase(c) ? 1 : 0);
                lowerPref[i + 1] = lowerPref[i] + (Character.isLowerCase(c) ? 1 : 0);
            }

            int totalDigits = digitPref[n];
            int totalUpper = upperPref[n];
            int totalLower = lowerPref[n];

            int minLen = Integer.MAX_VALUE;
            String bestString = "";

            // Iterate through all possible window starts and ends [start, end)
            for (int start = 0; start <= n; start++) {
                for (int end = start; end <= n; end++) {
                    int windowDist = end - start;

                    // Calculate character counts inside the current window
                    int digitsInWindow = digitPref[end] - digitPref[start];
                    int upperInWindow = upperPref[end] - upperPref[start];
                    int lowerInWindow = lowerPref[end] - lowerPref[start];

                    // Determine if characters are missing from the remaining parts of the string
                    boolean hasDigitOutside = (totalDigits - digitsInWindow) > 0;
                    boolean hasUpperOutside = (totalUpper - upperInWindow) > 0;
                    boolean hasLowerOutside = (totalLower - lowerInWindow) > 0;

                    // Construct the minimum required replacement characters
                    StringBuilder requiredChars = new StringBuilder();
                    if (!hasDigitOutside) requiredChars.append('1');
                    if (!hasUpperOutside) requiredChars.append('A');
                    if (!hasLowerOutside) requiredChars.append('a');

                    // If window can accommodate the necessary characters and is the shortest found
                    if (requiredChars.length() <= windowDist) {
                        if (windowDist < minLen) {
                            minLen = windowDist;
                            bestString = constructCandidate(s, start, end, requiredChars, windowDist);
                        }
                    }
                }
            }
            return bestString;
        }

        /**
         * Builds the final string for a successful window candidate.
         */
        private String constructCandidate(String s, int start, int end, StringBuilder req, int dist) {
            StringBuilder sb = new StringBuilder();
            // Add prefix
            sb.append(s, 0, start);
            // Add required characters
            sb.append(req);
            // Pad the rest of the window with '0'
            int paddingNeeded = dist - req.length();
            for (int i = 0; i < paddingNeeded; i++) {
                sb.append('0');
            }
            // Add suffix
            sb.append(s, end, s.length());
            return sb.toString();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Main entry point for the program.
 * Handles input and output operations.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int testCases = reader.nextInt();
            StringTransformer transformer = new StringTransformer();

            for (int i = 0; i < testCases; i++) {
                char[] input = reader.next().toCharArray();
                transformer.transform(input);
                writer.println(new String(input));
            }
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Logic for transforming strings to ensure they contain 
     * a specific diversity of character types.
     */
    static class StringTransformer {

        /**
         * Defines the three character categories: Lowercase, Uppercase, and Others.
         */
        enum CharType {
            LOWERCASE, UPPERCASE, OTHER;

            /**
             * Categorizes a character into one of the three types.
             */
            static CharType of(char c) {
                if (Character.isLowerCase(c)) return LOWERCASE;
                if (Character.isUpperCase(c)) return UPPERCASE;
                return OTHER;
            }

            /**
             * Returns a representative character for this type.
             */
            char getSampleChar() {
                switch (this) {
                    case LOWERCASE: return 'a';
                    case UPPERCASE: return 'A';
                    case OTHER:     return '1';
                    default:        return '?';
                }
            }
        }

        /**
         * Transforms the array to ensure the presence of three distinct character types 
         * if possible.
         * 
         * @param chars The character array to modify.
         */
        public void transform(char[] chars) {
            if (chars.length < 2) return;

            EnumMap<CharType, List<Integer>> typeMap = groupIndicesByType(chars);
            int uniqueTypeCount = typeMap.size();

            if (uniqueTypeCount == 3) {
                // Already has all three types.
                return;
            } else if (uniqueTypeCount == 1) {
                // Only one type present, add two others.
                handleSingleType(chars, typeMap.keySet().iterator().next());
            } else if (uniqueTypeCount == 2) {
                // Two types present, attempt to add the third.
                handleTwoTypes(chars, typeMap);
            }
        }

        private EnumMap<CharType, List<Integer>> groupIndicesByType(char[] chars) {
            EnumMap<CharType, List<Integer>> map = new EnumMap<>(CharType.class);
            for (int i = 0; i < chars.length; i++) {
                CharType type = CharType.of(chars[i]);
                map.computeIfAbsent(type, k -> new ArrayList<>()).add(i);
            }
            return map;
        }

        private void handleSingleType(char[] chars, CharType existingType) {
            // Based on the original logic's intent to introduce two new types.
            if (existingType == CharType.LOWERCASE) {
                chars[0] = CharType.UPPERCASE.getSampleChar();
                chars[1] = CharType.OTHER.getSampleChar();
            } else if (existingType == CharType.UPPERCASE) {
                chars[0] = CharType.LOWERCASE.getSampleChar();
                chars[1] = CharType.OTHER.getSampleChar();
            } else {
                chars[0] = CharType.LOWERCASE.getSampleChar();
                chars[1] = CharType.UPPERCASE.getSampleChar();
            }
        }

        private void handleTwoTypes(char[] chars, EnumMap<CharType, List<Integer>> typeMap) {
            CharType missingType = findMissingType(typeMap);
            if (missingType == null) return;

            // To add a third type without losing one of the existing two,
            // we must find a type that has more than one occurrence.
            for (Map.Entry<CharType, List<Integer>> entry : typeMap.entrySet()) {
                if (entry.getValue().size() > 1) {
                    int targetIndex = entry.getValue().get(0);
                    chars[targetIndex] = missingType.getSampleChar();
                    return;
                }
            }
            // If string length is 2 and both chars are different, we cannot add 
            // a third type without losing an existing one.
        }

        private CharType findMissingType(EnumMap<CharType, List<Integer>> typeMap) {
            for (CharType type : CharType.values()) {
                if (!typeMap.containsKey(type)) {
                    return type;
                }
            }
            return null;
        }
    }

    /**
     * Efficient reader for large input datasets.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream s) {
            br = new BufferedReader(new InputStreamReader(s));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
