import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * A utility class for efficient input reading.
 */
class InputReader {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    public InputReader() {
        this.reader = new BufferedReader(new InputStreamReader(System.in));
    }

    public String next() {
        while (tokenizer == null || !tokenizer.hasMoreElements()) {
            try {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                throw new RuntimeException("Error reading input", e);
            }
        }
        return tokenizer.nextToken();
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }

    /**
     * Consumes the remaining newline character after reading a number 
     * to prevent issues with subsequent nextLine() calls.
     */
    public void consumeNewline() {
        try {
            reader.readLine();
        } catch (IOException ignored) {
        }
    }

    public String nextLine() {
        try {
            // If tokenizer has content, we consume it; otherwise, read line directly
            if (tokenizer != null && tokenizer.hasMoreElements()) {
                StringBuilder sb = new StringBuilder();
                while (tokenizer.hasMoreElements()) {
                    sb.append(tokenizer.nextToken());
                    if (tokenizer.hasMoreElements()) sb.append(" ");
                }
                return sb.toString();
            }
            return reader.readLine();
        } catch (IOException e) {
            throw new RuntimeException("Error reading line", e);
        }
    }
}

/**
 * Handles the business logic for validating and enhancing string complexity.
 */
class StringComplexityManager {
    private static final char DEFAULT_UPPERCASE = 'A';
    private static final char DEFAULT_LOWERCASE = 'a';
    private static final char DEFAULT_DIGIT = '0';

    /**
     * Ensures the string contains at least one uppercase letter, 
     * one lowercase letter, and one digit.
     * 
     * @param input The original string.
     * @return A new string that meets all complexity requirements.
     */
    public String ensureComplexity(String input) {
        if (input == null) return "";

        boolean hasUppercase = false;
        boolean hasLowercase = false;
        boolean hasDigit = false;

        for (char ch : input.toCharArray()) {
            if (Character.isUpperCase(ch)) {
                hasUppercase = true;
            } else if (Character.isLowerCase(ch)) {
                hasLowercase = true;
            } else if (Character.isDigit(ch)) {
                hasDigit = true;
            }
        }

        StringBuilder enhancedString = new StringBuilder();

        // Prepend missing required characters
        if (!hasUppercase) {
            enhancedString.append(DEFAULT_UPPERCASE);
        }
        if (!hasLowercase) {
            enhancedString.append(DEFAULT_LOWERCASE);
        }
        if (!hasDigit) {
            enhancedString.append(DEFAULT_DIGIT);
        }

        enhancedString.append(input);
        return enhancedString.toString();
    }
}

