 * Main application entry point.
 */
public class Main {

    public static void main(String[] args) {
        InputReader reader = new InputReader();
        String testCasesInput = reader.next();

        if (testCasesInput == null) return;

        int testCaseCount = Integer.parseInt(testCasesInput);
        StringComplexityManager complexityManager = new StringComplexityManager();

        for (int i = 0; i < testCaseCount; i++) {
            // Read the next line for the string to process
            String inputString = reader.nextLine();

            // In case nextLine() was triggered by an empty buffer after nextInt()
            if (inputString == null || inputString.isEmpty()) {
                inputString = reader.nextLine();
            }

            if (inputString != null) {
                System.out.println(complexityManager.ensureComplexity(inputString));
            }
        }
    }
}

import java.io.BufferedReader;
