/**
 * An application that manages password security requirements.
 * A secure password must contain at least one uppercase letter, 
 * one lowercase letter, and one digit.
 */
public class PasswordSecurityApp {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PasswordSecurityManager manager = new PasswordSecurityManager();
        manager.execute(reader);
    }

    /**
     * Orchestrates the password processing flow.
     */
    public static class PasswordSecurityManager {
        private final PasswordValidator validator = new PasswordValidator();
        private final PasswordStrengthener strengthener = new PasswordStrengthener(validator);

        public void execute(FastReader reader) {
            try {
                int numberOfTestCases = reader.nextInt();
                for (int i = 0; i < numberOfTestCases; i++) {
                    String password = reader.next();
                    if (password != null) {
                        System.out.println(strengthener.findSecureVariation(password));
                    }
                }
            } catch (Exception e) {
                System.err.println("An error occurred during execution: " + e.getMessage());
            }
        }
    }

    /**
     * Logic for validating password security criteria.
     */
    public static class PasswordValidator {
        /**
         * Checks if the password contains at least one uppercase, one lowercase, and one digit.
         */
        public boolean isSecure(String password) {
            if (password == null) return false;

            boolean hasUpper = false;
            boolean hasLower = false;
            boolean hasDigit = false;

            for (char c : password.toCharArray()) {
                if (Character.isUpperCase(c)) hasUpper = true;
                else if (Character.isLowerCase(c)) hasLower = true;
                else if (Character.isDigit(c)) hasDigit = true;

                // Early exit if requirements are met
                if (hasUpper && hasLower && hasDigit) {
                    return true;
                }
            }
            return false;
        }
    }

    /**
     * Logic for attempting to transform an insecure password into a secure one.
     */
    public static class PasswordStrengthener {
        private static final String[] SINGLE_CHAR_REPLACEMENTS = {"A", "a", "1"};
        private static final String[] DOUBLE_CHAR_REPLACEMENTS = {"Aa", "A1", "a1"};

        private final PasswordValidator validator;

        public PasswordStrengthener(PasswordValidator validator) {
            this.validator = validator;
        }

        /**
         * Finds a secure variation of the password by attempting single-character 
         * and double-character replacements.
         * 
         * @param password The original password.
         * @return A secure version of the password, or an empty string if no variation is found.
         */
        public String findSecureVariation(String password) {
            if (validator.isSecure(password)) {
                return password;
            }

            // Strategy 1: Try replacing exactly one character at each position
            for (int i = 0; i < password.length(); i++) {
                for (String replacement : SINGLE_CHAR_REPLACEMENTS) {
                    String candidate = replaceAt(password, i, 1, replacement);
                    if (validator.isSecure(candidate)) {
                        return candidate;
                    }
                }
            }

            // Strategy 2: Try replacing two adjacent characters at each position
            for (int i = 0; i < password.length() - 1; i++) {
                for (String replacement : DOUBLE_CHAR_REPLACEMENTS) {
                    String candidate = replaceAt(password, i, 2, replacement);
                    if (validator.isSecure(candidate)) {
                        return candidate;
                    }
                }
            }

            return "";
        }

        /**
         * Helper to replace a substring of a specific length at a given index.
         */
        private String replaceAt(String original, int index, int length, String replacement) {
            return original.substring(0, index) + replacement + original.substring(index + length);
        }
    }

    /**
     * Utility for high-performance input reading.
     */
    public static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            this.reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            return next != null ? Integer.parseInt(next) : 0;
        }
    }
}

