/**
 * A program that ensures strings meet specific complexity requirements:
 * containing at least one uppercase letter, one lowercase letter, and one digit.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);
        StringTransformer transformer = new StringTransformer();

        try {
            int testCases = reader.nextInt();
            for (int i = 0; i < testCases; i++) {
                String input = reader.next();
                if (input != null) {
                    writer.println(transformer.transform(input));
                }
            }
        } catch (Exception e) {
            // In a real production app, use a logger
            System.err.println("Error processing input: " + e.getMessage());
        } finally {
            writer.close();
        }
    }

    /**
     * Handles the business logic for transforming strings.
     */
    static class StringTransformer {

        public String transform(String input) {
            char[] chars = input.toCharArray();
            int upperCount = 0;
            int lowerCount = 0;
            int digitCount = 0;

            for (char c : chars) {
                if (Character.isUpperCase(c)) upperCount++;
                else if (Character.isLowerCase(c)) lowerCount++;
                else if (Character.isDigit(c)) digitCount++;
            }

            // If already compliant, return original string
            if (upperCount > 0 && lowerCount > 0 && digitCount > 0) {
                return input;
            }

            // Case: Two types present, need the third
            if (upperCount > 0 && digitCount > 0) {
                if (upperCount > 1) replaceFirst(chars, Character::isUpperCase, 'a');
                else replaceFirst(chars, Character::isDigit, 'a');
            } 
            else if (upperCount > 0 && lowerCount > 0) {
                if (upperCount > 1) replaceFirst(chars, Character::isUpperCase, '0');
                else replaceFirst(chars, Character::isLowerCase, '0');
            } 
            else if (lowerCount > 0 && digitCount > 0) {
                if (digitCount > 1) replaceFirst(chars, Character::isDigit, 'A');
                else replaceFirst(chars, Character::isLowerCase, 'A');
            } 
            // Case: Only one type present, need two more
            else if (lowerCount > 0) {
                applyMultiReplace(chars, 'A', '0');
            } 
            else if (upperCount > 0) {
                applyMultiReplace(chars, 'a', '0');
            } 
            // Case: No compliant types present
            else {
                applyMultiReplace(chars, 'A', 'a');
            }

            return new String(chars);
        }

        /**
         * Finds the first character matching the predicate and replaces it.
         */
        private void replaceFirst(char[] chars, Predicate<Character> condition, char replacement) {
            for (int i = 0; i < chars.length; i++) {
                if (condition.test(chars[i])) {
                    chars[i] = replacement;
                    break;
                }
            }
        }

        /**
         * Replaces the first two characters with specific required types.
         * Safely handles strings with length < 2.
         */
        private void applyMultiReplace(char[] chars, char first, char second) {
            if (chars.length > 0) chars[0] = first;
            if (chars.length > 1) chars[1] = second;
        }
    }

    /**
     * High-performance input reader.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            this.reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            return next != null ? Integer.parseInt(next) : 0;
        }
    }
}

import java.util.Scanner;
import java.util.function.Predicate;

/**
 * A utility that processes strings to ensure they contain at least one 
 * lowercase letter, one uppercase letter, and one digit.
 */
public class DiversityStringProcessor {

    public static void main(String[] args) {
        DiversityStringProcessor processor = new DiversityStringProcessor();
        processor.run();
    }

    /**
     * Handles the standard input/output flow.
     */
    public void run() {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int testCases = scanner.nextInt();
        while (testCases-- > 0) {
            if (scanner.hasNext()) {
                String input = scanner.next();
                System.out.println(ensureDiversity(input));
            }
        }
        scanner.close();
    }

    /**
     * Ensures the input string contains at least one lowercase letter, 
     * one uppercase letter, and one digit. If not, it modifies the string.
     *
     * @param input The original string to process.
     * @return A string that satisfies the diversity requirements.
     */
    public String ensureDiversity(String input) {
        if (input == null || input.isEmpty()) {
            return input;
        }

        char[] characters = input.toCharArray();
        int lowerCount = 0;
        int upperCount = 0;
        int digitCount = 0;

        for (char c : characters) {
            if (Character.isLowerCase(c)) {
                lowerCount++;
            } else if (Character.isUpperCase(c)) {
                upperCount++;
            } else if (Character.isDigit(c)) {
                digitCount++;
            }
        }

        // If the string is already diverse, return it as is.
        if (lowerCount > 0 && upperCount > 0 && digitCount > 0) {
            return input;
        }

        applyTransformationRules(characters, lowerCount, upperCount, digitCount);
        return new String(characters);
    }

    /**
     * Routes the transformation logic based on which character type is missing.
     */
    private void applyTransformationRules(char[] chars, int lower, int upper, int digit) {
        if (digit == 0) {
            fixMissingDigit(chars, lower, upper);
        } else if (lower == 0) {
            fixMissingLower(chars, upper, digit);
        } else {
            // If we reach here, upper must be 0
            fixMissingUpper(chars, lower, digit);
        }
    }

    private void fixMissingDigit(char[] chars, int lower, int upper) {
        if (lower == 0) {
            // String is all uppercase
            chars[0] = 'a';
            if (chars.length > 1) chars[1] = '1';
        } else if (upper == 0) {
            // String is all lowercase
            chars[0] = 'A';
            if (chars.length > 1) chars[1] = '1';
        } else {
            // String has both lowercase and uppercase; sacrifice one to make a digit
            if (lower > 1) {
                replaceFirstMatching(chars, Character::isLowerCase, '1');
            } else {
                replaceFirstMatching(chars, Character::isUpperCase, '1');
            }
        }
    }

    private void fixMissingLower(char[] chars, int upper, int digit) {
        if (upper == 0) {
            // String is all digits
            chars[0] = 'a';
            if (chars.length > 1) chars[1] = 'A';
        } else if (upper == 1) {
            // String has one uppercase and some digits; sacrifice a digit
            replaceFirstMatching(chars, Character::isDigit, 'a');
        } else {
            // String has multiple uppercase; sacrifice an uppercase
            replaceFirstMatching(chars, Character::isUpperCase, 'a');
        }
    }

    private void fixMissingUpper(char[] chars, int lower, int digit) {
        if (lower == 1) {
            // String has one lowercase and some digits; sacrifice a digit
            replaceFirstMatching(chars, Character::isDigit, 'A');
        } else {
            // String has multiple lowercase; sacrifice a lowercase
            replaceFirstMatching(chars, Character::isLowerCase, 'A');
        }
    }

    /**
     * Finds the first character matching the condition and replaces it.
     */
    private void replaceFirstMatching(char[] chars, Predicate<Character> condition, char replacement) {
        for (int i = 0; i < chars.length; i++) {
            if (condition.test(chars[i])) {
                chars[i] = replacement;
                break;
            }
        }
    }
}

