/**
 * Refactored solution for the EducationalR51A problem.
 * This program processes strings to ensure they meet specific character 
 * requirements (lowercase, uppercase, and digits) by transforming 
 * existing characters.
 */
public class EducationalR51A {

    public static void main(String[] args) {
        StringProcessor processor = new StringProcessor(System.in, System.out);
        processor.run();
    }
}

/**
 * Orchestrates the reading of input and writing of output.
 */
class StringProcessor {
    private final FastReader reader;
    private final PrintWriter writer;

    public StringProcessor(InputStream inputStream, OutputStream outputStream) {
        this.reader = new FastReader(inputStream);
        this.writer = new PrintWriter(outputStream);
    }

    /**
     * Main execution loop.
     */
    public void run() {
        try {
            int testCases = reader.nextInt();
            for (int i = 0; i < testCases; i++) {
                String input = reader.nextString();
                String result = transformString(input);
                writer.println(result);
            }
        } catch (Exception e) {
            // In a production environment, use a logger.
            e.printStackTrace();
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Core logic: Analyzes the character composition of a string 
     * and modifies it to satisfy requirements based on specific rules.
     * 
     * @param input The original string.
     * @return The transformed string.
     */
    private String transformString(String input) {
        char[] chars = input.toCharArray();
        if (chars.length == 0) return input;

        int lowerCount = 0;
        int upperCount = 0;
        int digitCount = 0;

        // Step 1: Count character types
        for (char c : chars) {
            if (Character.isLowerCase(c)) {
                lowerCount++;
            } else if (Character.isUpperCase(c)) {
                upperCount++;
            } else if (Character.isDigit(c)) {
                digitCount++;
            }
        }

        // Step 2: Apply transformation rules based on priority
        // Note: We preserve the exact if-else hierarchy of the original code.
        if (lowerCount == 0 && upperCount == 0) {
            if (chars.length >= 2) {
                chars[0] = 'a';
                chars[1] = 'A';
            }
        } else if (lowerCount == 0 && digitCount == 0) {
            if (chars.length >= 2) {
                chars[0] = 'a';
                chars[1] = '1';
            }
        } else if (digitCount == 0 && upperCount == 0) {
            if (chars.length >= 2) {
                chars[0] = 'A';
                chars[1] = '1';
            }
        } else if (lowerCount == 0 && upperCount > 1) {
            replaceFirstOccurence(chars, "UPPERCASE", 'a');
        } else if (lowerCount > 1 && upperCount == 0) {
            replaceFirstOccurence(chars, "LOWERCASE", 'A');
        } else if (digitCount == 0 && upperCount > 1) {
            replaceFirstOccurence(chars, "UPPERCASE", '1');
        } else if (lowerCount == 0 && digitCount > 1) {
            replaceFirstOccurence(chars, "DIGIT", 'a');
        } else if (digitCount == 0 && lowerCount > 1) {
            replaceFirstOccurence(chars, "LOWERCASE", '1');
        } else if (digitCount > 1 && upperCount == 0) {
            replaceFirstOccurence(chars, "DIGIT", 'A');
        }

        return new String(chars);
    }

    /**
     * Helper to find and replace the first character of a specific category.
     */
    private void replaceFirstOccurence(char[] chars, String type, char replacement) {
        for (int i = 0; i < chars.length; i++) {
            boolean match = false;
            switch (type) {
                case "LOWERCASE":
                    match = Character.isLowerCase(chars[i]);
                    break;
                case "UPPERCASE":
                    match = Character.isUpperCase(chars[i]);
                    break;
                case "DIGIT":
                    match = Character.isDigit(chars[i]);
                    break;
            }

            if (match) {
                chars[i] = replacement;
                break;
            }
        }
    }
}

