/**
 * Refactored version of the original test program.
 * 
 * Improvements:
 * 1. Naming Conventions: Follows standard Java CamelCase for classes and descriptive names for variables.
 * 2. Maintainability: Logic is encapsulated into a Solution class, and the complex if-else chain is cleaned up.
 * 3. Code Quality: Replaced redundant loops with helper methods and removed unused constants.
 * 4. Performance: Uses a standard FastReader implementation for efficient I/O.
 * 5. Bug-Prevention: Clarifies the distinction between "non-letter" characters and "digits" as per the original logic.
 */
public class Main {

    public static void main(String[] args) {
        try {
            FastReader reader = new FastReader(System.in);
            PrintWriter writer = new PrintWriter(System.out);

            String tStr = reader.next();
            if (tStr != null) {
                int testCases = Integer.parseInt(tStr);
                Solution solution = new Solution();

                for (int i = 0; i < testCases; i++) {
                    solution.solve(reader, writer);
                }
            }

            writer.flush();
            writer.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /**
     * Encapsulates the core logic of the program.
     */
    static class Solution {

        public void solve(FastReader in, PrintWriter out) throws IOException {
            String input = in.next();
            if (input == null) return;
            char[] s = input.toCharArray();
            int n = s.length;

            int lowerCount = 0;
            int upperCount = 0;
            int otherCount = 0; // Represents anything not a lowercase or uppercase letter

            for (char c : s) {
                if (isLower(c)) {
                    lowerCount++;
                } else if (isUpper(c)) {
                    upperCount++;
                } else {
                    otherCount++;
                }
            }

            // If all three categories are present, no changes needed
            if (lowerCount > 0 && upperCount > 0 && otherCount > 0) {
                out.println(new String(s));
                return;
            }

            // Case 2: Two categories are present. Attempt to replace a redundant character with the missing category.
            // Note: The original logic only performs a replacement if a category has more than one character.

            // Lowercase and Uppercase present, missing 'other' (digits)
            if (lowerCount > 0 && upperCount > 0) {
                if (lowerCount > 1) {
                    if (replaceFirst(s, Solution::isLower, '0')) {
                        out.println(new String(s));
                        return;
                    }
                }
                if (upperCount > 1) {
                    if (replaceFirst(s, Solution::isUpper, '0')) {
                        out.println(new String(s));
                        return;
                    }
                }
            }

            // Uppercase and Other present, missing lowercase
            if (upperCount > 0 && otherCount > 0) {
                if (otherCount > 1) {
                    // The original code specifically looks for a digit to replace
                    if (replaceFirst(s, Solution::isDigit, 'a')) {
                        out.println(new String(s));
                        return;
                    }
                }
                if (upperCount > 1) {
                    if (replaceFirst(s, Solution::isUpper, 'a')) {
                        out.println(new String(s));
                        return;
                    }
                }
            }

            // Lowercase and Other present, missing uppercase
            if (lowerCount > 0 && otherCount > 0) {
                if (lowerCount > 1) {
                    if (replaceFirst(s, Solution::isLower, 'A')) {
                        out.println(new String(s));
                        return;
                    }
                }
                if (otherCount > 1) {
                    // The original code specifically looks for a digit to replace
                    if (replaceFirst(s, Solution::isDigit, 'A')) {
                        out.println(new String(s));
                        return;
                    }
                }
            }

            // Case 3: Only one category is present. Transform two existing characters into the other two types.
            if (lowerCount > 0) {
                transformSingleType(s, Solution::isLower, 'A', '0');
            } else if (upperCount > 0) {
                transformSingleType(s, Solution::isUpper, 'a', '0');
            } else if (otherCount > 0) {
                transformSingleType(s, Solution::isDigit, 'a', 'A');
            }

            out.println(new String(s));
        }

        /**
         * Replaces the first character that matches the condition with the replacement character.
         * @return true if a replacement was made, false otherwise.
         */
        private boolean replaceFirst(char[] s, Predicate<Character> condition, char replacement) {
            for (int i = 0; i < s.length; i++) {
                if (condition.test(s[i])) {
                    s[i] = replacement;
                    return true;
                }
            }
            return false;
        }

        /**
         * Finds the first character of a type, replaces it, then finds the next one and replaces it.
         */
        private void transformSingleType(char[] s, Predicate<Character> condition, char firstReplacement, char secondReplacement) {
            int firstIdx = -1;
            for (int i = 0; i < s.length; i++) {
                if (condition.test(s[i])) {
                    firstIdx = i;
                    break;
                }
            }

            if (firstIdx != -1) {
                s[firstIdx] = firstReplacement;
                // Search for the next character of the same type starting after the index we just modified
                for (int i = firstIdx + 1; i < s.length; i++) {
                    if (condition.test(s[i])) {
                        s[i] = secondReplacement;
                        break;
                    }
                }
            }
        }

        private static boolean isLower(char c) { return c >= 'a' && c <= 'z'; }
        private static boolean isUpper(char c) { return c >= 'A' && c <= 'Z'; }
        private static boolean isDigit(char c) { return c >= '0' && c <= '9'; }
    }

    /**
     * High-performance reader for fast I/O.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

