    /**
     * Logic for ensuring a string contains at least one lowercase letter,
     * one uppercase letter, and one digit.
     */
    static class PasswordFixer {

        public String fix(String s) {
            int lowercaseCount = 0;
            int uppercaseCount = 0;
            int digitCount = 0;

            char[] chars = s.toCharArray();

            // Count existing character types
            for (char c : chars) {
                if (Character.isLowerCase(c)) {
                    lowercaseCount++;
                } else if (Character.isUpperCase(c)) {
                    uppercaseCount++;
                } else if (Character.isDigit(c)) {
                    digitCount++;
                }
            }

            // If all requirements are met, return the original string
            if (lowercaseCount > 0 && uppercaseCount > 0 && digitCount > 0) {
                return s;
            }

            // Case 1: Two types are missing. 
            // We modify the first two characters to satisfy the missing types.
            // (Assumes string length >= 2 as per problem constraints)
            if (lowercaseCount == 0 && uppercaseCount == 0) {
                chars[0] = 'a';
                chars[1] = 'A';
            } else if (lowercaseCount == 0 && digitCount == 0) {
                chars[0] = 'a';
                chars[1] = '1';
            } else if (uppercaseCount == 0 && digitCount == 0) {
                chars[0] = 'A';
                chars[1] = '1';
            } 
            // Case 2: Only one type is missing.
            // We find the first character that isn't of the required type and convert it.
            else if (lowercaseCount == 0) {
                replaceFirstNonType(chars, Character::isLowerCase, 'a');
            } else if (uppercaseCount == 0) {
                replaceFirstNonType(chars, Character::isUpperCase, 'A');
            } else if (digitCount == 0) {
                replaceFirstNonType(chars, Character::isDigit, '1');
            }

            return new String(chars);
        }

        /**
         * Finds the first character that does NOT satisfy the predicate and replaces it.
         */
        private void replaceFirstNonType(char[] chars, java.util.function.Predicate<Character> typePredicate, char replacement) {
            for (int i = 0; i < chars.length; i++) {
                if (!typePredicate.test(chars[i])) {
                    chars[i] = replacement;
                    break;
                }
            }
        }
    }

    /**
     * Efficient reader for large input volumes.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            return next != null ? Integer.parseInt(next) : 0;
        }
    }
}

import java.util.Scanner;
import java.util.function.Predicate;

/**
 * StringTransformer encapsulates the logic for ensuring a string contains 
 * at least one lowercase letter, one uppercase letter, and one digit.
 */
class StringTransformer {

    private static final String MISSING_DIGIT_REPLACEMENT = "1";
    private static final String MISSING_UPPER_REPLACEMENT = "A";
    private static final String MISSING_LOWER_REPLACEMENT = "a";

    private static final String ONLY_DIGITS_REPLACEMENT = "aA";
    private static final String ONLY_UPPERCASE_REPLACEMENT = "a0";
    private static final String ONLY_LOWERCASE_REPLACEMENT = "A0";

    /**
     * Transforms the input string based on character type presence.
     * 
     * @param input The string to be processed.
     * @return The transformed string.
     */
    public String transform(String input) {
        if (input == null || input.isEmpty()) {
            return input;
        }

        int lowerCount = countType(input, Character::isLowerCase);
        int upperCount = countType(input, Character::isUpperCase);
        int digitCount = countType(input, Character::isDigit);

        // Case 1: All three required types are already present
        if (lowerCount > 0 && upperCount > 0 && digitCount > 0) {
            return input;
        }

        StringBuilder sb = new StringBuilder(input);

        // Case 2: Two types are present, one is missing
        if (lowerCount > 0 && upperCount > 0) {
            // Missing digits: replace first occurrence of the majority type with '1'
            int idx = findFirstIndex(input, lowerCount > upperCount ? Character::isLowerCase : Character::isUpperCase);
            replaceSingleChar(sb, idx, MISSING_DIGIT_REPLACEMENT);
        } else if (lowerCount > 0 && digitCount > 0) {
            // Missing uppercase: replace first occurrence of the majority type with 'A'
            int idx = findFirstIndex(input, lowerCount > digitCount ? Character::isLowerCase : Character::isDigit);
            replaceSingleChar(sb, idx, MISSING_UPPER_REPLACEMENT);
        } else if (upperCount > 0 && digitCount > 0) {
            // Missing lowercase: replace first occurrence of the majority type with 'a'
            int idx = findFirstIndex(input, upperCount > digitCount ? Character::isUpperCase : Character::isDigit);
            replaceSingleChar(sb, idx, MISSING_LOWER_REPLACEMENT);
        } 
        // Case 3: Only one type is present, two are missing
        else if (digitCount > 0) {
            replaceRange(sb, 0, ONLY_DIGITS_REPLACEMENT);
        } else if (upperCount > 0) {
            replaceRange(sb, 0, ONLY_UPPERCASE_REPLACEMENT);
        } else if (lowerCount > 0) {
            replaceRange(sb, 0, ONLY_LOWERCASE_REPLACEMENT);
        }

        return sb.toString();
    }

    private int countType(String str, Predicate<Character> condition) {
        int count = 0;
        for (char c : str.toCharArray()) {
            if (condition.test(c)) count++;
        }
        return count;
    }

    private int findFirstIndex(String str, Predicate<Character> condition) {
        for (int i = 0; i < str.length(); i++) {
            if (condition.test(str.charAt(i))) return i;
        }
        return 0;
    }

    /**
     * Safely replaces a single character at a specific index.
     */
    private void replaceSingleChar(StringBuilder sb, int index, String replacement) {
        if (index < sb.length()) {
            sb.replace(index, index + 1, replacement);
        } else {
            sb.insert(index, replacement);
        }
    }

    /**
     * Safely replaces up to two characters starting from the given index.
     * This prevents StringIndexOutOfBoundsException on short strings.
     */
    private void replaceRange(StringBuilder sb, int start, String replacement) {
        int end = Math.min(start + 2, sb.length());
        if (start >= sb.length()) {
            sb.append(replacement);
        } else {
            sb.replace(start, end, replacement);
        }
    }
}

