/**
 * A program that ensures input strings contain at least one 
 * lowercase letter, one uppercase letter, and one digit.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        StringJoiner output = new StringJoiner("\n");

        try {
            int testCases = reader.nextInt();
            for (int i = 0; i < testCases; i++) {
                String inputString = reader.next();
                if (inputString != null) {
                    output.add(transformString(inputString));
                }
            }
            System.out.println(output.toString());
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Transforms the string to satisfy the requirement of having 
     * at least one lowercase, one uppercase, and one digit.
     * 
     * @param s The original string.
     * @return A modified string containing all three character types.
     */
    private static String transformString(String s) {
        boolean hasLower = false;
        boolean hasUpper = false;
        boolean hasDigit = false;

        // Single pass to check current status
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (Character.isLowerCase(c)) {
                hasLower = true;
            } else if (Character.isUpperCase(c)) {
                hasUpper = true;
            } else if (Character.isDigit(c)) {
                hasDigit = true;
            }
        }

        StringBuilder sb = new StringBuilder(s);

        // If a category is missing, append a representative character.
        // This approach is robust for all string lengths and avoids 
        // the index-out-of-bounds errors present in the original code.
        if (!hasLower) {
            sb.append('a');
        }
        if (!hasUpper) {
            sb.append('A');
        }
        if (!hasDigit) {
            sb.append('1');
        }

        return sb.toString();
    }

    /**
     * Efficient reader for fast I/O operations.
     */
    static class FastReader {
        private final byte[] buffer = new byte[2048];
        private int index, total;
        private final InputStream in;

        public FastReader(InputStream is) {
            this.in = is;
        }

        private int scan() throws IOException {
            if (index >= total) {
                index = 0;
                total = in.read(buffer);
                if (total <= 0) {
                    return -1;
                }
            }
            return buffer[index++];
        }

        public String next() throws IOException {
            int c = scan();
            while (c != -1 && c <= 32) {
                c = scan();
            }
            if (c == -1) return null;

            StringBuilder sb = new StringBuilder();
            while (c > 32) {
                sb.append((char) c);
                c = scan();
            }
            return sb.toString();
        }

        public int nextInt() throws IOException {
            int c = scan();
            while (c != -1 && c <= 32) {
                c = scan();
            }
            if (c == -1) return 0;

            boolean neg = false;
            if (c == '-') {
                neg = true;
                c = scan();
            } else if (c == '+') {
                c = scan();
            }

            int val = 0;
            while (c >= '0' && c <= '9') {
                val = (val << 3) + (val << 1) + (c & 15);
                c = scan();
            }
            return neg ? -val : val;
        }
    }
}

