/**
 * StringTypeEnforcer ensures that every input string contains at least 
 * one digit, one uppercase letter, and one lowercase letter.
 * If the criteria are not met, it applies specific transformation rules.
 */
public class StringTypeEnforcer {

    public static void main(String[] args) {
        FastReader in = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        // Read the number of strings to process
        String firstLine = in.nextLine();
        if (firstLine == null || firstLine.trim().isEmpty()) {
            out.close();
            return;
        }

        try {
            int n = Integer.parseInt(firstLine.trim());
            for (int i = 0; i < n; i++) {
                String s = in.nextLine();
                if (s != null) {
                    out.println(processString(s));
                }
            }
        } catch (NumberFormatException e) {
            // Silently handle or log error in a real-world scenario
        }

        out.flush();
        out.close();
    }

    /**
     * Evaluates the string and applies transformation rules to ensure
     * it contains at least one digit, one uppercase, and one lowercase character.
     */
    private static String processString(String s) {
        int digitCount = 0;
        int upperCount = 0;
        int lowerCount = 0;
        boolean hasDigit = false;
        boolean hasUpper = false;
        boolean hasLower = false;

        // Single pass to count character types
        for (char c : s.toCharArray()) {
            if (Character.isDigit(c)) {
                hasDigit = true;
                digitCount++;
            } else if (Character.isUpperCase(c)) {
                hasUpper = true;
                upperCount++;
            } else if (Character.isLowerCase(c)) {
                hasLower = true;
                lowerCount++;
            }
        }

        // Rule 1: If all requirements are met, return original
        if (hasDigit && hasUpper && hasLower) {
            return s;
        }

        // Rule 2: Two types are missing
        if (!hasDigit && !hasUpper) {
            return "2A" + getSuffix(s);
        } else if (!hasDigit && !hasLower) {
            return "2a" + getSuffix(s);
        } else if (!hasUpper && !hasLower) {
            return "aA" + getSuffix(s);
        }

        // Rule 3: One type is missing
        if (!hasDigit) {
            // If only one upper exists, swap the first lowercase for a digit
            if (upperCount == 1) return replaceFirst(s, Character::isLowerCase, '1');
            // If only one lower exists, swap the first uppercase for a digit
            if (lowerCount == 1) return replaceFirst(s, Character::isUpperCase, '1');
            // Otherwise, prepend a digit
            return "1" + s;
        } else if (!hasUpper) {
            // If only one digit exists, swap the first lowercase for an uppercase
            if (digitCount == 1) return replaceFirst(s, Character::isLowerCase, 'A');
            // If only one lower exists, swap the first digit for an uppercase
            if (lowerCount == 1) return replaceFirst(s, Character::isDigit, 'A');
            // Otherwise, prepend an uppercase
            return "A" + s;
        } else if (!hasLower) {
            // If only one digit exists, swap the first uppercase for a lowercase
            if (digitCount == 1) return replaceFirst(s, Character::isUpperCase, 'a');
            // If only one upper exists, swap the first digit for a lowercase
            if (upperCount == 1) return replaceFirst(s, Character::isDigit, 'a');
            // Otherwise, prepend a lowercase
            return "a" + s;
        }

        return s;
    }

    /**
     * Mimics the original logic for skipping the first two characters.
     */
    private static String getSuffix(String s) {
        return s.length() > 2 ? s.substring(2) : "";
    }

    /**
     * Finds the first character satisfying the condition and replaces it.
     * Returns the original string if no character matches.
     */
    private static String replaceFirst(String s, Predicate<Character> condition, char replacement) {
        for (int i = 0; i < s.length(); i++) {
            if (condition.test(s.charAt(i))) {
                return s.substring(0, i) + replacement + s.substring(i + 1);
            }
        }
        return s;
    }

    /**
     * Optimized reader for large inputs.
     */
    static class FastReader {
        private final BufferedReader br;

        public FastReader(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        public String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                return null;
            }
        }
    }
}

