/**
 * Handles the business logic for validating and repairing strings.
 */
class StringProcessor {

    /**
     * Processes the input string by attempting to validate it or repair it.
     * 
     * @param str The input string.
     * @return A valid string based on the repair rules.
     */
    public String processString(String str) {
        CharacterStats stats = CharacterStats.fromString(str);

        // 1. If already valid, return as is
        if (stats.isValid()) {
            return str;
        }

        // 2. Attempt a single character replacement
        String modified = attemptSingleReplacement(str, stats);
        if (modified != null && CharacterStats.fromString(modified).isValid()) {
            return modified;
        }

        // 3. Fallback to the default replacement pattern
        return applyFallbackPattern(str);
    }

    /**
     * Attempts to replace one character to satisfy the requirement of having 
     * all three character types (digit, lowercase, uppercase).
     */
    private String attemptSingleReplacement(String str, CharacterStats stats) {
        int n = str.length();
        for (int i = 0; i < n; i++) {
            char ch = str.charAt(i);

            if (Character.isDigit(ch) && stats.digitCount > 1) {
                if (stats.lowercaseCount == 0) {
                    return replaceCharAt(str, i, 'a');
                } else if (stats.uppercaseCount == 0) {
                    return replaceCharAt(str, i, 'A');
                }
            } else if (Character.isLowerCase(ch) && stats.lowercaseCount > 1) {
                if (stats.digitCount == 0) {
                    return replaceCharAt(str, i, '0');
                } else if (stats.uppercaseCount == 0) {
                    return replaceCharAt(str, i, 'A');
                }
            } else if (Character.isUpperCase(ch) && stats.uppercaseCount > 1) {
                if (stats.digitCount == 0) {
                    return replaceCharAt(str, i, '0');
                } else if (stats.lowercaseCount == 0) {
                    return replaceCharAt(str, i, 'a');
                }
            }
        }
        return null;
    }

    /**
     * Applies the fallback logic provided in the original requirement.
     * Note: Original logic assumes string length >= 3. Added safety check.
     */
    private String applyFallbackPattern(String str) {
        if (str.length() < 3) {
            // Fallback for very short strings to prevent IndexOutOfBounds
            return "aA" + (str.length() > 0 ? str : "");
        }

        char thirdChar = str.charAt(2);
        if (Character.isLowerCase(thirdChar)) {
            return "A1" + str.substring(2);
        } else if (Character.isUpperCase(thirdChar)) {
            return "a1" + str.substring(2);
        } else {
            return "aA" + str.substring(2);
        }
    }

    private String replaceCharAt(String str, int index, char replacement) {
        return str.substring(0, index) + replacement + str.substring(index + 1);
    }
}

/**
 * Data class to hold counts of different character types.
 */
class CharacterStats {
    final int digitCount;
    final int lowercaseCount;
    final int uppercaseCount;

    private CharacterStats(int digits, int lower, int upper) {
        this.digitCount = digits;
        this.lowercaseCount = lower;
        this.uppercaseCount = upper;
    }

    public static CharacterStats fromString(String str) {
        int digits = 0;
        int lower = 0;
        int upper = 0;

        for (char ch : str.toCharArray()) {
            if (Character.isDigit(ch)) {
                digits++;
            } else if (Character.isLowerCase(ch)) {
                lower++;
            } else if (Character.isUpperCase(ch)) {
                upper++;
            }
        }
        return new CharacterStats(digits, lower, upper);
    }

    public boolean isValid() {
        return digitCount > 0 && lowercaseCount > 0 && uppercaseCount > 0;
    }
}

