            if (Character.isDigit(c)) hasDigit = true;
            else if (Character.isLowerCase(c)) hasLower = true;
            else if (Character.isUpperCase(c)) hasUpper = true;
        }

        EnumSet<CharType> missing = EnumSet.noneOf(CharType.class);
        if (!hasDigit) missing.add(CharType.DIGIT);
        if (!hasLower) missing.add(CharType.LOWER);
        if (!hasUpper) missing.add(CharType.UPPER);
        return missing;
    }

    /**
     * Handles the case where two types are missing by replacing the start of the string.
     */
    private static String fixTwoMissingTypes(String s, EnumSet<CharType> missingTypes) {
        char[] replacementChars = new char[2];
        int idx = 0;
        for (CharType type : missingTypes) {
            replacementChars[idx++] = getReplacementChar(type);
        }

        if (s.length() < 2) {
            return new String(replacementChars) + s;
        }
        return replacementChars[0] + "" + replacementChars[1] + s.substring(2);
    }

    /**
     * Finds the index of a character to replace that minimizes the distance 
     * to other character types, following the "smallest gap" logic.
     */
    private static int findBestReplacementIndex(String s, CharType missingType) {
        List<Integer> indicesA = new ArrayList<>();
        List<Integer> indicesB = new ArrayList<>();

        // Identify the two types that ARE present.
        CharType typeA = null, typeB = null;
        for (CharType t : CharType.values()) {
            if (t != missingType && typeA == null) typeA = t;
            else if (t != missingType && typeB == null) typeB = t;
        }

        // Collect indices for the present types.
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (isCharType(c, typeA)) indicesA.add(i);
            if (isCharType(c, typeB)) indicesB.add(i);
        }

        int bestIdx = 0;
        int minGap = Integer.MAX_VALUE;

        // Find the smallest gap between consecutive characters of Type A.
        for (int i = 1; i < indicesA.size(); i++) {
            int gap = indicesA.get(i) - indicesA.get(i - 1);
            if (gap < minGap) {
                minGap = gap;
                bestIdx = indicesA.get(i - 1);
            }
        }

        // Find the smallest gap between consecutive characters of Type B.
        for (int i = 1; i < indicesB.size(); i++) {
            int gap = indicesB.get(i) - indicesB.get(i - 1);
            if (gap < minGap) {
                minGap = gap;
                bestIdx = indicesB.get(i - 1);
            }
        }

        return bestIdx;
    }

    private static boolean isCharType(char c, CharType type) {
        if (type == null) return false;
        return switch (type) {
            case DIGIT -> Character.isDigit(c);
            case LOWER -> Character.isLowerCase(c);
            case UPPER -> Character.isUpperCase(c);
        };
    }

    private static char getReplacementChar(CharType type) {
        return switch (type) {
            case DIGIT -> '1';
            case LOWER -> 'a';
            case UPPER -> 'A';
        };
    }

    private static String replaceCharAt(String s, int index, char newChar) {
        if (index < 0 || index >= s.length()) return s;
        return s.substring(0, index) + newChar + s.substring(index + 1);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.EnumMap;
import java.util.StringTokenizer;

/**
 * A program that ensures strings contain at least one uppercase letter, 
 * one lowercase letter, and one digit by transforming at most one character.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        StringProcessor processor = new StringProcessor();

        int testCases = reader.nextInt();
        for (int t = 0; t < testCases; t++) {
            String input = reader.next();
            if (input != null) {
                System.out.println(processor.process(input));
            }
        }
    }

    /**
     * Represents the three required character categories.
     */
    enum CharCategory {
        UPPER, LOWER, DIGIT;

        /**
         * Determines the category of a character based on ASCII ranges.
         * 
         * @param c The character to categorize.
         * @return The corresponding CharCategory, or null if it doesn't fit.
         */
        static CharCategory fromChar(char c) {
            if (c >= 'A' && c <= 'Z') return UPPER;
            if (c >= 'a' && c <= 'z') return LOWER;
            if (c >= '0' && c <= '9') return DIGIT;
            return null;
        }

        /**
         * Returns a sample character belonging to this category for replacement.
         */
        char getSampleChar() {
            switch (this) {
                case UPPER: return 'A';
                case LOWER: return 'a';
                case DIGIT: return '1';
                default: throw new IllegalStateException("Unknown category");
            }
        }
    }

    /**
     * Encapsulates the logic for analyzing and transforming the input strings.
     */
    static class StringProcessor {

        /**
         * Orchestrates the analysis and transformation of a single string.
         * 
         * @param s The input string.
         * @return The transformed string.
         */
        public String process(String s) {
            EnumMap<CharCategory, Integer> counts = new EnumMap<>(CharCategory.class);
            for (CharCategory cat : CharCategory.values()) {
                counts.put(cat, 0);
            }

            // Count occurrences of each category
            for (char c : s.toCharArray()) {
                CharCategory cat = CharCategory.fromChar(c);
                if (cat != null) {
                    counts.put(cat, counts.get(cat) + 1);
                }
            }

            int categoriesPresent = 0;
            for (int count : counts.values()) {
                if (count > 0) categoriesPresent++;
            }

            // Decision logic based on how many categories are already present
            if (categoriesPresent == 3) {
                return s;
            } else if (categoriesPresent == 1) {
                return handleSingleCategory(s, counts);
            } else {
                return handleTwoCategories(s, counts);
            }
        }

        /**
         * Handles strings missing two categories.
         * Replaces the start of the string with characters from the missing categories.
         */
        private String handleSingleCategory(String s, EnumMap<CharCategory, Integer> counts) {
            StringBuilder missingPrefix = new StringBuilder();
            if (counts.get(CharCategory.UPPER) == 0) missingPrefix.append('A');
            if (counts.get(CharCategory.LOWER) == 0) missingPrefix.append('a');
            if (counts.get(CharCategory.DIGIT) == 0) missingPrefix.append('1');

            // Maintains original logic: replaces first two characters with missing categories
            String suffix = (s.length() >= 2) ? s.substring(2) : "";
            return missingPrefix.toString() + suffix;
        }

        /**
         * Handles strings missing exactly one category.
         * Searches for a redundant character (count > 1) in the present categories and replaces it.
         */
        private String handleTwoCategories(String s, EnumMap<CharCategory, Integer> counts) {
            CharCategory missing = findMissingCategory(counts);
            if (missing == null) return s;

            for (int i = 0; i < s.length(); i++) {
                char c = s.charAt(i);
                CharCategory currentCat = CharCategory.fromChar(c);

                // If character is part of a category that is present and has redundant characters
                if (currentCat != null && currentCat != missing && counts.get(currentCat) > 1) {
                    return s.substring(0, i) + missing.getSampleChar() + s.substring(i + 1);
                }
            }
            return s;
        }

        private CharCategory findMissingCategory(EnumMap<CharCategory, Integer> counts) {
            for (CharCategory cat : CharCategory.values()) {
                if (counts.get(cat) == 0) return cat;
            }
            return null;
        }
    }

    /**
     * Fast I/O utility for efficient reading from System.in.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(java.io.InputStream inputStream) {
            br = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

/**
 * A utility to process passwords and ensure they meet specific complexity requirements.
 * A valid password must contain at least one lowercase letter, 
 * one uppercase letter, and one digit.
 */
public class VasyaAndPassword {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int testCasesCount = scanner.nextInt();
        scanner.nextLine(); // Consume the newline character left by nextInt()

        for (int i = 0; i < testCasesCount; i++) {
            if (scanner.hasNextLine()) {
                String password = scanner.nextLine();
                System.out.println(refinePassword(password));
            }
        }

        scanner.close();
    }

    /**
     * Refines the given password by replacing a single character to satisfy 
     * any missing complexity requirements.
     * 
     * @param password The original password string.
     * @return A modified password string that meets all requirements.
     */
    public static String refinePassword(String password) {
        if (password == null || password.isEmpty()) {
            return password;
        }

        char[] chars = password.toCharArray();
        int lowerCount = 0;
        int upperCount = 0;
        int digitCount = 0;

        // Step 1: Count the existing occurrences of each character type
        for (char c : chars) {
            if (Character.isLowerCase(c)) {
                lowerCount++;
            } else if (Character.isUpperCase(c)) {
                upperCount++;
            } else if (Character.isDigit(c)) {
                digitCount++;
            }
        }

        // Step 2: Check for missing categories and perform replacements.
        // We use the counts calculated at the start to ensure we don't 
        // violate requirements during the replacement process.

        // Case: Missing lowercase letters
        if (lowerCount == 0) {
            for (int i = 0; i < chars.length; i++) {
                char c = chars[i];
                if ((Character.isUpperCase(c) && upperCount > 1) || 
                    (Character.isDigit(c) && digitCount > 1)) {
                    chars[i] = 'a';
                    break;
                }
            }
        }

        // Case: Missing uppercase letters
        if (upperCount == 0) {
            for (int i = 0; i < chars.length; i++) {
                char c = chars[i];
                if ((Character.isLowerCase(c) && lowerCount > 1) || 
                    (Character.isDigit(c) && digitCount > 1)) {
                    chars[i] = 'A';
                    break;
                }
            }
        }

        // Case: Missing digits
        if (digitCount == 0) {
            for (int i = 0; i < chars.length; i++) {
                char c = chars[i];
                if ((Character.isUpperCase(c) && upperCount > 1) || 
                    (Character.isLowerCase(c) && lowerCount > 1)) {
                    chars[i] = '0';
                    break;
                }
            }
        }

        return new String(chars);
    }
}

import java.util.*;
import java.io.*;

/**
 * A program designed to transform a string to ensure it contains 
 * at least one lowercase letter, one uppercase letter, and one non-alphabetic character.
 */
public class StringTransformer {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        StringTransformer transformer = new StringTransformer();
        transformer.run(reader, writer);

        writer.flush();
        writer.close();
    }

    /**
     * Main execution loop that processes the number of test cases.
     */
    public void run(FastReader reader, PrintWriter writer) {
        int testCases = reader.nextInt();
        while (testCases-- > 0) {
            String input = reader.next();
            if (input == null) break;

            char[] characters = input.toCharArray();
            processString(characters, writer);
        }
    }

    /**
     * Identifies character categories and applies transformations to satisfy requirements.
     */
    private void processString(char[] s, PrintWriter writer) {
        List<Integer> lowerIndices = new ArrayList<>();
        List<Integer> upperIndices = new ArrayList<>();
        List<Integer> otherIndices = new ArrayList<>();

        // Categorize indices based on character type
        for (int i = 0; i < s.length; i++) {
            if (Character.isLowerCase(s[i])) {
                lowerIndices.add(i);
            } else if (Character.isUpperCase(s[i])) {
                upperIndices.add(i);
            } else {
                otherIndices.add(i);
            }
        }

        applyTransformations(s, lowerIndices, upperIndices, otherIndices);
        writer.println(new String(s));
    }

    /**
     * Logic to ensure the string contains at least one of each required type.
     * Preserves the original logic priority and transformation patterns.
     */
    private void applyTransformations(char[] s, List<Integer> lower, 
                                      List<Integer> upper, List<Integer> other) {
        int n = s.length;

        if (lower.isEmpty()) {
            if (upper.isEmpty() && other.isEmpty()) {
                // Case: String is too short or contains no valid characters
                if (n > 0) s[0] = 'a';
                if (n > 1) s[1] = 'A';
            } else if (upper.isEmpty()) {
                // Missing both lowercase and uppercase
                s[0] = 'a';
                if (n > 1) s[1] = 'A';
            } else if (other.isEmpty()) {
                // Missing both lowercase and "others"
                s[0] = 'a';
                if (n > 1) s[1] = '1';
            } else {
                // Both uppercase and others exist; just need a lowercase
                // Original logic: if only one uppercase exists, replace an 'other' character
                if (upper.size() == 1) {
                    s[other.get(0)] = 'a';
                } else {
                    s[upper.get(0)] = 'a';
                }
            }
        } else if (upper.isEmpty()) {
            if (other.isEmpty()) {
                // Missing both uppercase and "others"
                s[0] = 'A';
                if (n > 1) s[1] = '1';
            } else {
                // Just need an uppercase
                if (lower.size() == 1) {
                    s[other.get(0)] = 'A';
                } else {
                    s[lower.get(0)] = 'A';
                }
            }
        } else if (other.isEmpty()) {
            // Just need an "other" (digit/symbol)
            if (upper.size() == 1) {
                s[lower.get(0)] = '1';
            } else {
                s[upper.get(0)] = '1';
            }
        }
    }

    /**
     * Fast I/O utility for reading large inputs efficiently.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            return (next == null) ? -1 : Integer.parseInt(next);
        }
    }
}

