/**
 * Logic handler for ensuring a string contains at least one 
 * uppercase letter, one lowercase letter, and one digit.
 */
class StringRequirementSatisfier {

    @Override
    public String toString() {
        return super.toString();
    }

    /**
     * Processes the input string to ensure it meets the character requirements.
     * 
     * @param input The original string.
     * @return The modified string if requirements are not met, otherwise the original.
     */
    public String process(String input) {
        char[] chars = input.toCharArray();
        int uppercaseCount = countUppercase(chars);
        int lowercaseCount = countLowercase(chars);
        int digitCount = countDigits(chars);

        // If all requirements are met, return original string
        if (uppercaseCount > 0 && lowercaseCount > 0 && digitCount > 0) {
            return input;
        }

        // Handle missing requirements
        if (uppercaseCount == 0) {
            handleMissingUppercase(chars, lowercaseCount, digitCount);
        } else if (lowercaseCount == 0) {
            handleMissingLowercase(chars, uppercaseCount, digitCount);
        } else {
            // If we reach here, it means di == 0 (digitCount)
            handleMissingDigit(chars, uppercaseCount, lowercaseCount);
        }

        return new String(chars);
    }

    private void handleMissingUppercase(char[] chars, int lowercaseCount, int digitCount) {
        if (lowercaseCount == 0) {
            // Needs both Upper and Lower
            chars[0] = 'a';
            chars[1] = 'A';
        } else if (digitCount == 0) {
            // Needs both Upper and Digit
            chars[0] = '0';
            chars[1] = 'A';
        } else {
            // Only Uppercase is missing
            if (digitCount == 1) {
                replaceFirstOfCategory(chars, this::isLowercase, 'A');
            } else if (lowercaseCount == 1) {
                replaceFirstOfCategory(chars, this::isDigit, 'A');
            } else {
                chars[0] = 'A';
            }
        }
    }

    private void handleMissingLowercase(char[] chars, int uppercaseCount, int digitCount) {
        if (digitCount == 0) {
            // Needs both Lower and Digit
            chars[0] = '0';
            chars[1] = 'a';
        } else {
            // Only Lowercase is missing
            if (digitCount == 1) {
                replaceFirstOfCategory(chars, this::isUppercase, 'a');
            } else if (uppercaseCount == 1) {
                replaceFirstOfCategory(chars, this::isDigit, 'a');
            } else {
                chars[0] = 'a';
            }
        }
    }

    private void handleMissingDigit(char[] chars, int uppercaseCount, int lowercaseCount) {
        if (lowercaseCount == 0) {
            // Needs both Digit and Lower
            chars[0] = 'a';
            chars[1] = '0';
        } else {
            // Only Digit is missing
            if (uppercaseCount == 1) {
                replaceFirstOfCategory(chars, this::isLowercase, '0');
            } else if (lowercaseCount == 1) {
                replaceFirstOfCategory(chars, this::isUppercase, '0');
            } else {
                chars[0] = '0';
            }
        }
    }

    // --- Helper Utilities ---

    private void replaceFirstOfCategory(char[] chars, CharacterPredicate predicate, char replacement) {
        for (int i = 0; i < chars.length; i++) {
            if (predicate.test(chars[i])) {
                chars[i] = replacement;
                break;
            }
        }
    }

    private int countUppercase(char[] chars) {
        int count = 0;
        for (char c : chars) if (isUppercase(c)) count++;
        return count;
    }

    private int countLowercase(char[] chars) {
        int count = 0;
        for (char c : chars) if (isLowercase(c)) count++;
        return count;
    }

    private int countDigits(char[] chars) {
        int count = 0;
        for (char c : chars) if (isDigit(c)) count++;
        return count;
    }

    private boolean isUppercase(char c) { return c >= 'A' && c <= 'Z'; }
    private boolean isLowercase(char c) { return c >= 'a' && c <= 'z'; }
    private boolean isDigit(char c) { return c >= '0' && c <= '9'; }

    @FunctionalInterface
    private interface CharacterPredicate {
        boolean test(char c);
    }
}

