/**
 * Refactored version of the VasyaPassword program.
 * This program ensures a password contains at least one lowercase letter,
 * one uppercase letter, and one non-letter character (digit/symbol).
 */
public class VasyaPasswordRefactorer {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int testCases = scanner.nextInt();
        PasswordManager passwordManager = new PasswordManager();

        while (testCases-- > 0) {
            String password = scanner.next();
            System.out.println(passwordManager.makeValid(password));
        }

        scanner.close();
    }
