class PasswordManager {

    /**
     * Transforms a password to ensure it meets the complexity requirements:
     * 1. At least one lowercase letter.
     * 2. At least one uppercase letter.
     * 3. At least one non-letter character.
     *
     * @param s The original password string.
     * @return A modified string that meets the requirements.
     */
    public String makeValid(String s) {
        char[] chars = s.toCharArray();
        int lowerCount = 0, upperCount = 0, otherCount = 0;
        int firstLower = -1, firstUpper = -1, firstOther = -1;

        // Step 1: Analyze the current state of the string
        for (int i = 0; i < chars.length; i++) {
            if (Character.isLowerCase(chars[i])) {
                lowerCount++;
                if (firstLower == -1) firstLower = i;
            } else if (Character.isUpperCase(chars[i])) {
                upperCount++;
                if (firstUpper == -1) firstUpper = i;
            } else {
                otherCount++;
                if (firstOther == -1) firstOther = i;
            }
        }

        boolean hasLower = lowerCount > 0;
        boolean hasUpper = upperCount > 0;
        boolean hasOther = otherCount > 0;

        // Step 2: Return if already valid
        if (hasLower && hasUpper && hasOther) {
            return s;
        }

        // Step 3: Apply transformation logic
        // Case: Only one type of character exists
        if (!hasUpper && !hasOther) { // Only lowercase
            chars[0] = '1';
            chars[1] = 'A';
        } else if (!hasLower && !hasOther) { // Only uppercase
            chars[0] = '1';
            chars[1] = 'a';
        } else if (!hasLower && !hasUpper) { // Only "other"
            chars[0] = 'a';
            chars[1] = 'A';
        } 
        // Case: Two types exist, one is missing
        else if (hasLower && hasUpper) { // Missing "other"
            // Replace a character from the type that has a surplus to avoid losing that type
            int targetIdx = (lowerCount > 1) ? firstLower : firstUpper;
            chars[targetIdx] = '1';
        } else if (hasUpper && hasOther) { // Missing lowercase
            int targetIdx = (upperCount > 1) ? firstUpper : firstOther;
            chars[targetIdx] = 'a';
        } else if (hasLower && hasOther) { // Missing uppercase
            int targetIdx = (lowerCount > 1) ? firstLower : firstOther;
            chars[targetIdx] = 'A';
        }

        return new String(chars);
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the string transformation task.
 * The goal is to ensure a string contains at least one uppercase letter,
 * one lowercase letter, and one digit by modifying at most two characters.
 */
public class Main {
    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        FastWriter writer = new FastWriter(System.out);
        ProblemSolver solver = new ProblemSolver();

        try {
            int testCases = reader.nextInt();
            while (testCases-- > 0) {
                String input = reader.next();
                writer.println(solver.solve(input));
            }
        } catch (Exception e) {
            // In a production environment, use a logger.
        } finally {
            writer.close();
        }
    }

    /**
     * Core logic for solving the string requirement problem.
     */
    static class ProblemSolver {

        /**
         * Analyzes the string and returns counts of uppercase, lowercase, and digits.
         */
        private StringStats analyze(String s) {
            int upper = 0, lower = 0, digit = 0;
            for (char c : s.toCharArray()) {
                if (Character.isUpperCase(c)) upper++;
                else if (Character.isLowerCase(c)) lower++;
                else if (Character.isDigit(c)) digit++;
            }
            return new StringStats(upper, lower, digit);
        }

        /**
         * Processes the input string and returns the modified (or original) string.
         */
        public String solve(String s) {
            StringStats stats = analyze(s);

            // Case 1: Requirement already satisfied
            if (stats.hasAllThree()) {
                return s;
            }

            StringBuilder sb = new StringBuilder(s);

            // Case 2: Two types are missing
            if (stats.isMissingTwo(0, 1, 2)) { // Logic for missing two types
                return fixTwoMissing(sb, stats);
            } 

            // Note: The original logic handles "two missing" specifically for 
            // (Upper/Digit), (Lower/Digit), or (Lower/Upper).
            if (stats.upper == 0 && stats.digit == 0) return fixTwoMissing(sb, stats, '1', 'A');
            if (stats.lower == 0 && stats.digit == 0) return fixTwoMissing(sb, stats, '1', 'a');
            if (stats.lower == 0 && stats.upper == 0) return fixTwoMissing(sb, stats, 'a', 'A');

            // Case 3: Exactly one type is missing
            return fixOneMissing(sb, stats);
        }

        private String fixTwoMissing(StringBuilder sb, StringStats stats, char c1, char c2) {
            if (sb.length() >= 2) {
                sb.setCharAt(0, c1);
                sb.setCharAt(1, c2);
            }
            return sb.toString();
        }

        private String fixTwoMissing(StringBuilder sb, StringStats stats) {
            // Fallback for the check used in the solve method structure
            return sb.toString();
        }

        private String fixOneMissing(StringBuilder sb, StringStats stats) {
            if (stats.digit == 0) {
                // Need a digit: replace an upper or lower depending on which has more surplus
                char target = (stats.upper > stats.lower) ? '0' : '0'; 
                // The original logic uses a specific replacement strategy:
                if (stats.upper > stats.lower) {
                    replaceFirstOfKind(sb, Character::isUpperCase, '0');
                } else {
                    replaceFirstOfKind(sb, Character::isLowerCase, '0');
                }
            } else if (stats.upper == 0) {
                // Need uppercase
                if (stats.digit > stats.lower) {
                    replaceFirstOfKind(sb, Character::isDigit, 'A');
                } else {
                    replaceFirstOfKind(sb, Character::isLowerCase, 'A');
                }
            } else if (stats.lower == 0) {
                // Need lowercase
                if (stats.upper > stats.digit) {
                    replaceFirstOfKind(sb, Character::isUpperCase, 'a');
                } else {
                    replaceFirstOfKind(sb, Character::isDigit, 'a');
                }
            }
            return sb.toString();
        }

        private void replaceFirstOfKind(StringBuilder sb, java.util.function.Predicate<Character> condition, char replacement) {
            for (int i = 0; i < sb.length(); i++) {
                if (condition.test(sb.charAt(i))) {
                    sb.setCharAt(i, replacement);
                    break;
                }
            }
        }
    }

    /**
     * Data holder for character type counts.
     */
    static class StringStats {
        final int upper;
        final int lower;
        final int digit;

        StringStats(int upper, int lower, int digit) {
            this.upper = upper;
            this.lower = lower;
            this.digit = digit;
        }

