/**
 * Domain model representing the three required character types.
 */
enum CharacterType {
    DIGIT, UPPER, LOWER;

    /**
     * Maps a character to its corresponding CharacterType.
     */
    public static CharacterType fromChar(char c) {
        if (Character.isDigit(c)) return DIGIT;
        if (Character.isUpperCase(c)) return UPPER;
        if (Character.isLowerCase(c)) return LOWER;
        return null;
    }
}

/**
 * Contains the core logic for validating and transforming strings 
 * to meet the requirement of having at least one Digit, one Uppercase, and one Lowercase letter.
 */
class StringProcessor {

    /**
     * Processes the input string to ensure it contains all three character types.
     * @param s The input string.
     * @return The valid string after transformation, or null if no solution found.
     */
    public String process(String s) {
        Set<CharacterType> presentTypes = getPresentTypes(s);

        if (presentTypes.size() == 3) {
            return s;
        } else if (presentTypes.size() == 2) {
            return attemptFixMissingOne(s, presentTypes);
        } else if (presentTypes.size() == 1) {
            return attemptFixMissingTwo(s, presentTypes);
        }
        return null;
    }

    private Set<CharacterType> getPresentTypes(String s) {
        Set<CharacterType> types = new HashSet<>();
        for (char c : s.toCharArray()) {
            CharacterType type = CharacterType.fromChar(c);
            if (type != null) {
                types.add(type);
            }
        }
        return types;
    }

    /**
     * Tries to replace one character with the missing type.
     */
    private String attemptFixMissingOne(String s, Set<CharacterType> presentTypes) {
        CharacterType missing = getMissingType(presentTypes);
        String replacement = getReplacementFor(missing);

        for (int i = 0; i < s.length(); i++) {
            String candidate = replaceAt(s, i, replacement, 1);
            if (getPresentTypes(candidate).size() == 3) {
                return candidate;
            }
        }
        return null;
    }

    /**
     * Tries to replace two adjacent characters with the two missing types.
     */
    private String attemptFixMissingTwo(String s, Set<CharacterType> presentTypes) {
        List<CharacterType> missing = getMissingTypes(presentTypes);
        // Create a string representing the two missing types (e.g., "Aa", "1a", or "1A")
        String replacement = getReplacementFor(missing.get(0)) + getReplacementFor(missing.get(1));

        for (int i = 0; i < s.length() - 1; i++) {
            String candidate = replaceAt(s, i, replacement, 2);
            if (getPresentTypes(candidate).size() == 3) {
                return candidate;
            }
        }
        return null;
    }

    private CharacterType getMissingType(Set<CharacterType> presentTypes) {
        for (CharacterType type : CharacterType.values()) {
            if (!presentTypes.contains(type)) return type;
        }
        return null;
    }

    private List<CharacterType> getMissingTypes(Set<CharacterType> presentTypes) {
        List<CharacterType> missing = new ArrayList<>();
        for (CharacterType type : CharacterType.values()) {
            if (!presentTypes.contains(type)) missing.add(type);
        }
        return missing;
    }

    private String getReplacementFor(CharacterType type) {
        return switch (type) {
            case DIGIT -> "1";
            case UPPER -> "A";
            case LOWER -> "a";
        };
    }

    private String replaceAt(String s, int index, String replacement, int charsToRemove) {
        StringBuilder sb = new StringBuilder(s);
        sb.replace(index, index + charsToRemove, replacement);
        return sb.toString();
    }
}

