/**
 * Refactored solution for CF1051A.
 * The goal is to ensure a string contains at least one lowercase letter,
 * one uppercase letter, and one digit by changing at most one character.
 */
public class CF1051A {

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int testCases = scanner.nextInt();
            while (testCases-- > 0) {
                String input = scanner.next();
                System.out.println(solve(input));
            }
        }
    }

    /**
     * Processes a single test case. If the string is already valid, returns it.
     * Otherwise, attempts to find a single character replacement that satisfies the condition.
     *
     * @param s The input string.
     * @return The modified string if a single change makes it valid, otherwise the original.
     */
    private static String solve(String s) {
        if (hasRequiredCharacters(s)) {
            return s;
        }

        char[] chars = s.toCharArray();
        char[] candidates = {'a', 'A', '8'};

        // Try replacing each character at every position with the possible candidates
        for (int i = 0; i < chars.length; i++) {
            char originalChar = chars[i];

            for (char candidate : candidates) {
                chars[i] = candidate;
                if (hasRequiredCharacters(new String(chars))) {
                    return new String(chars);
                }
            }

            // Backtrack to original character before trying the next position
            chars[i] = originalChar;
        }

        return s;
    }

    /**
     * Checks if the string contains at least one lowercase letter, 
     * one uppercase letter, and one digit.
     *
     * @param s The string to validate.
     * @return true if all three types are present, false otherwise.
     */
    private static boolean hasRequiredCharacters(String s) {
        boolean hasLower = false;
        boolean hasUpper = false;
        boolean hasDigit = false;

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (Character.isLowerCase(c)) {
                hasLower = true;
            } else if (Character.isUpperCase(c)) {
                hasUpper = true;
            } else if (Character.isDigit(c)) {
                hasDigit = true;
            }

            // Optimization: return early if condition is met
            if (hasLower && hasUpper && hasDigit) {
                return true;
            }
        }

        return false;
    }
}

import java.util.Scanner;

/**
 * A utility to ensure a password contains at least one lowercase letter,
 * one uppercase letter, and one digit.
 */
public class VasyaPassword {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int testCases = scanner.nextInt();
        scanner.nextLine(); // Consume the remaining newline character

        for (int i = 0; i < testCases; i++) {
            if (scanner.hasNextLine()) {
                String input = scanner.nextLine();
                System.out.println(processPassword(input));
            }
        }

        scanner.close();
    }

    /**
     * Validates the password requirements and modifies the string if necessary.
     * 
     * @param password The input password string.
     * @return A string that contains at least one lowercase, one uppercase, and one digit.
     */
    public static String processPassword(String password) {
        if (password == null || password.isEmpty()) {
            return password;
        }

        char[] chars = password.toCharArray();
        boolean hasLowercase = false;
        boolean hasUppercase = false;
        boolean hasDigit = false;

        int lastLowercaseIdx = -1;
        int lastUppercaseIdx = -1;
        int lastDigitIdx = -1;

        // Step 1: Analyze the current password to find existing required characters
        for (int i = 0; i < chars.length; i++) {
            if (Character.isLowerCase(chars[i])) {
                hasLowercase = true;
                lastLowercaseIdx = i;
            } else if (Character.isUpperCase(chars[i])) {
                hasUppercase = true;
                lastUppercaseIdx = i;
            } else if (Character.isDigit(chars[i])) {
                hasDigit = true;
                lastDigitIdx = i;
            }
        }

        // If all requirements are met, return the original password
        if (hasLowercase && hasUppercase && hasDigit) {
            return password;
        }

        // Step 2: Fix missing requirements
        // We prioritize replacing indices that are not the "last" occurrence 
        // of other required types to ensure we don't break existing requirements.

        if (!hasDigit) {
            int targetIdx = findSafeReplacementIndex(chars.length, lastLowercaseIdx, lastUppercaseIdx);
            chars[targetIdx] = '1';
            hasDigit = true;
            lastDigitIdx = targetIdx; // Update to ensure subsequent fixes respect this new digit
        }

        if (!hasLowercase) {
            int targetIdx = findSafeReplacementIndex(chars.length, lastUppercaseIdx, lastDigitIdx);
            chars[targetIdx] = 'a';
            hasLowercase = true;
            lastLowercaseIdx = targetIdx;
        }

        if (!hasUppercase) {
            int targetIdx = findSafeReplacementIndex(chars.length, lastLowercaseIdx, lastDigitIdx);
            chars[targetIdx] = 'A';
            hasUppercase = true;
            lastUppercaseIdx = targetIdx;
        }

        return new String(chars);
    }

    /**
     * Finds an index to replace that does not conflict with the indices 
     * of other required character types.
     *
     * @param length     The length of the character array.
     * @param excludeIdx1 An index that should not be overwritten.
     * @param excludeIdx2 An index that should not be overwritten.
     * @return A safe index for replacement.
     */
    private static int findSafeReplacementIndex(int length, int excludeIdx1, int excludeIdx2) {
        for (int i = 0; i < length; i++) {
            if (i != excludeIdx1 && i != excludeIdx2) {
                return i;
            }
        }
        // Fallback to index 0 if the string is too short to find a safe index
        return 0;
    }
}

