/**
 * Refactored solution to ensure a string contains at least one uppercase letter,
 * one lowercase letter, and one non-alphabetic character by modifying at most 
 * two adjacent characters.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        String tStr = reader.next();
        if (tStr == null) return;

        int testCases = Integer.parseInt(tStr);
        while (testCases-- > 0) {
