            String result = solve(input);
            if (result != null) {
                out.println(result);
            }
        }
        out.flush();
        out.close();
    }

    /**
     * Attempts to find a valid string by modifying at most two adjacent characters.
     * 
     * @param s The original input string.
     * @return The modified valid string, or null if no solution is found.
     */
    private static String solve(String s) {
        char[] chars = s.toCharArray();

        // 1. Check if the string is already valid
        if (isValid(chars)) {
            return s;
        }

        // Target characters to satisfy the three requirements:
        // 'a' (lowercase), 'A' (uppercase), '1' (digit/other)
        char[] targets = {'a', 'A', '1'};

        // 2. Try replacing exactly one character
        for (int i = 0; i < chars.length; i++) {
            char originalChar = chars[i];
            for (char target : targets) {
                chars[i] = target;
                if (isValid(chars)) {
                    return new String(chars);
                }
            }
            chars[i] = originalChar; // Backtrack
        }

        // 3. Try replacing two adjacent characters
        for (int i = 0; i < chars.length - 1; i++) {
            char originalChar1 = chars[i];
            char originalChar2 = chars[i + 1];

            for (char t1 : targets) {
                for (char t2 : targets) {
                    chars[i] = t1;
                    chars[i + 1] = t2;
                    if (isValid(chars)) {
                        return new String(chars);
                    }
                }
            }
            // Backtrack
            chars[i] = originalChar1;
            chars[i + 1] = originalChar2;
        }

        return null;
    }

    /**
     * Checks if the character array contains at least one uppercase,
     * one lowercase, and one non-alphabetic character.
     */
    private static boolean isValid(char[] arr) {
        boolean hasUpper = false;
        boolean hasLower = false;
        boolean hasOther = false;

        for (char c : arr) {
            if (Character.isUpperCase(c)) {
                hasUpper = true;
            } else if (Character.isLowerCase(c)) {
                hasLower = true;
            } else {
                hasOther = true;
            }

            // Optimization: return early if all conditions met
            if (hasUpper && hasLower && hasOther) {
                return true;
            }
        }
        return false;
    }

    /**
     * High-performance input reader.
     */
    static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }
    }
