/**
 * VasyaAndPassword ensures that a given password contains at least one 
 * lowercase letter, one uppercase letter, and one digit using the 
 * minimum number of character changes.
 */
public class VasyaAndPassword {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            String testCasesInput = reader.next();
            if (testCasesInput != null) {
                int t = Integer.parseInt(testCasesInput);
                while (t-- > 0) {
                    String password = reader.next();
                    if (password != null) {
                        writer.println(solve(password));
                    }
                }
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Determines the minimum changes needed to satisfy the password requirements.
     * 
     * @param s The original password string.
     * @return The modified password string.
     */
    private static String solve(String s) {
        char[] chars = s.trim().toCharArray();
        int n = chars.length;

        boolean hasLower = false;
        boolean hasUpper = false;
        boolean hasDigit = false;

        // Identify current character types present in the string
        for (char c : chars) {
            if (Character.isLowerCase(c)) {
                hasLower = true;
            } else if (Character.isUpperCase(c)) {
                hasUpper = true;
            } else if (Character.isDigit(c)) {
                hasDigit = true;
            }
        }

        // Case 1: All three types are already present. No changes needed.
        if (hasLower && hasUpper && hasDigit) {
            return s;
        }

        // Case 2: Exactly two types are present. One character needs to be changed.
        if (hasLower && hasUpper) { // Missing digit
            for (int i = 0; i < n; i++) {
                if (!Character.isDigit(chars[i])) {
                    chars[i] = '1';
                    break;
                }
            }
            return new String(chars);
        } 

        if (hasLower && hasDigit) { // Missing uppercase
            for (int i = 0; i < n; i++) {
                if (!Character.isUpperCase(chars[i])) {
                    chars[i] = 'A';
                    break;
                }
            }
            return new String(chars);
        } 

        if (hasUpper && hasDigit) { // Missing lowercase
            for (int i = 0; i < n; i++) {
                if (!Character.isLowerCase(chars[i])) {
                    chars[i] = 'a';
                    break;
                }
            }
            return new String(chars);
        }

        // Case 3: Only one type is present. Two characters need to be changed.
        // Note: Problem constraints typically assume n >= 2 for this case.
        if (hasLower) { // Missing upper and digit
            chars[0] = 'A';
            chars[1] = '1';
        } else if (hasUpper) { // Missing lower and digit
            chars[0] = 'a';
            chars[1] = '1';
        } else { // hasDigit, missing lower and upper
            chars[0] = 'a';
            chars[1] = 'A';
        }

        return new String(chars);
    }

    /**
     * A fast I/O utility class for efficient reading of input.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

