public class PasswordFixer {

    private static final char LOWER_CASE_REPLACEMENT = 'a';
    private static final char UPPER_CASE_REPLACEMENT = 'A';
    private static final char DIGIT_REPLACEMENT = '1';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;

        int testCases = scanner.nextInt();
        while (testCases-- > 0) {
            String password = scanner.next();
            System.out.println(solve(password));
        }
        scanner.close();
    }

    private static String solve(String password) {
        char[] chars = password.toCharArray();
        int lc = 0, uc = 0, d = 0;

        for (char c : chars) {
            if (Character.isLowerCase(c)) lc++;
            else if (Character.isUpperCase(c)) uc++;
            else if (Character.isDigit(c)) d++;
        }

        int missing = 0;
        if (lc == 0) missing++;
        if (uc == 0) missing++;
        if (d == 0) missing++;

        if (missing == 0) return password;

        if (missing > 1) {
            if (lc == 0 && uc == 0) { chars[0] = 'a'; chars[1] = 'A'; }
            else if (lc == 0 && d == 0) { chars[0] = 'a'; chars[1] = '1'; }
            else { chars[0] = 'A'; chars[1] = '1'; }
        } else {
            // Exactly one missing
            if (lc == 0) {
                if (uc > 1) replaceFirst(chars, Character::isUpperCase, 'a');
                else if (d > 1) replaceFirst(chars, Character::isDigit, 'a');
                else chars[0] = 'a';
            } else if (uc == 0) {
                if (lc > 1) replaceFirst(chars, Character::isLowerCase, 'A');
                else if (d > 1) replaceFirst(chars, Character::isDigit, 'A');
                else chars[0] = 'A';
            } else { // d == 0
                if (lc > 1) replaceFirst(chars, Character::isLowerCase, '1');
                else if (uc > 1) replaceFirst(chars, Character::isUpperCase, '1');
                else chars[0] = '1';
            }
        }
        return new String(chars);
    }

    private static void replaceFirst(char[] chars, java.util.function.Predicate<Character> predicate, char replacement) {
        for (int i = 0; i < chars.length; i++) {
            if (predicate.test(chars[i])) {
                chars[i] = replacement;
                break;
            }
        }
    }
}

