            }

            // Case 6: Lowercase and Digits present, but no uppercase
            if (lowerCount > 0 && digitCount > 0 && upperCount == 0) {
                if (lowerCount > 1) return replaceFirstMatch(str, Character::isLowerCase, 'A');
                if (digitCount > 1) return replaceFirstMatch(str, Character::isDigit, 'A');
            }

            // Case 7: Uppercase and Digits present, but no lowercase
            if (upperCount > 0 && digitCount > 0 && lowerCount == 0) {
                if (upperCount > 1) return replaceFirstMatch(str, Character::isUpperCase, 'a');
                if (digitCount > 1) return replaceFirstMatch(str, Character::isDigit, 'a');
            }

            return null;
        }

        /**
         * Replaces the first two characters of the string with specific values.
         */
        private static String applyTwoCharReplacement(String str, char first, char second) {
            if (str.length() < 2) return null;
            char[] chars = str.toCharArray();
            chars[0] = first;
            chars[1] = second;
            return new String(chars);
        }

        /**
         * Finds the first character matching the predicate and replaces it.
         */
        private static String replaceFirstMatch(String str, java.util.function.Predicate<Character> condition, char replacement) {
            char[] chars = str.toCharArray();
            for (int i = 0; i < chars.length; i++) {
                if (condition.test(chars[i])) {
                    chars[i] = replacement;
                    return new String(chars);
                }
            }
            return null;
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

