/**
 * A utility to ensure that a given string contains at least one digit,
 * one lowercase letter, and one uppercase letter.
 */
public class StringRequirementSolution {

    public static void main(String[] args) {
        StringRequirementSolution solution = new StringRequirementSolution();
        solution.run();
    }

    /**
     * Orchestrates the execution of the program.
     */
    public void run() {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            String firstLine = reader.next();
            if (firstLine == null) return;

            int testCases = Integer.parseInt(firstLine);
            while (testCases-- > 0) {
                solve(reader, writer);
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Processes a single test case.
     * 
     * @param reader The input reader.
     * @param writer The output writer.
     */
    private void solve(FastReader reader, PrintWriter writer) {
        String input = reader.next();
        if (input == null) return;

        writer.println(ensureRequirements(input));
    }

    /**
     * Analyzes the string and ensures it contains at least one digit, 
     * one lowercase letter, and one uppercase letter.
     * 
     * @param s The original input string.
     * @return A string satisfying the requirements.
     */
    private String ensureRequirements(String s) {
        boolean hasDigit = false;
        boolean hasLower = false;
        boolean hasUpper = false;

        // Single pass to check character composition
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (Character.isDigit(c)) {
                hasDigit = true;
            } else if (Character.isLowerCase(c)) {
                hasLower = true;
            } else if (Character.isUpperCase(c)) {
                hasUpper = true;
            }

            // Optimization: exit early if all requirements are met
            if (hasDigit && hasLower && hasUpper) {
                return s;
            }
        }

        // If requirements are not met, prepend necessary characters.
        // This approach is more robust than the original substring manipulation.
        StringBuilder sb = new StringBuilder();
        if (!hasDigit) sb.append('1');
        if (!hasLower) sb.append('a');
        if (!hasUpper) sb.append('A');
        sb.append(s);

        return sb.toString();
    }

    /**
     * Fast I/O class for efficient reading of large inputs.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }
    }
}

import java.util.Scanner;

/**
 * CharacterDiversityEnforcer ensures that a given string contains at least 
 * one lowercase letter, one uppercase letter, and one digit. 
 * If any are missing, it replaces redundant characters of other types 
 * to satisfy the requirement.
 */
public class CharacterDiversityEnforcer {

    /**
     * Represents the three required character categories and an 'OTHER' category.
     */
    private enum CharType {
        LOWERCASE,
        UPPERCASE,
        DIGIT,
        OTHER;

        /**
         * Categorizes a character into one of the CharTypes.
         * 
         * @param c The character to categorize.
         * @return The corresponding CharType.
         */
        public static CharType fromChar(char c) {
            if (c >= 'a' && c <= 'z') return LOWERCASE;
            if (c >= 'A' && c <= 'Z') return UPPERCASE;
            if (c >= '0' && c <= '9') return DIGIT;
            return OTHER;
        }
    }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int testCases = scanner.nextInt();
            while (testCases-- > 0) {
                if (scanner.hasNext()) {
                    String input = scanner.next();
                    System.out.println(processString(input));
                }
            }
        }
    }

    /**
     * Processes the input string to ensure it contains at least one lowercase,
     * one uppercase, and one digit.
     * 
     * @param input The original string.
     * @return The modified string.
     */
    private static String processString(String input) {
        int n = input.length();
        char[] chars = input.toCharArray();
        CharType[] originalTypes = new CharType[n];

        int lowerCount = 0;
        int upperCount = 0;
        int digitCount = 0;

        // Pass 1: Identify the type of every character and count frequencies
        for (int i = 0; i < n; i++) {
            CharType type = CharType.fromChar(chars[i]);
            originalTypes[i] = type;

            if (type == CharType.LOWERCASE) lowerCount++;
            else if (type == CharType.UPPERCASE) upperCount++;
            else if (type == CharType.DIGIT) digitCount++;
        }

        // Pass 2: Replace redundant characters to fill missing types
        for (int i = 0; i < n; i++) {
            // If all requirements are already met, stop transforming
            if (lowerCount > 0 && upperCount > 0 && digitCount > 0) {
                break;
            }

            CharType currentType = originalTypes[i];

            // Only attempt to replace characters that are "redundant" (count > 1)
            // and belong to one of our three target categories.
            if (currentType == CharType.LOWERCASE && lowerCount > 1) {
                if (upperCount == 0) {
                    chars[i] = 'A';
                    lowerCount--;
                    upperCount++;
                } else if (digitCount == 0) {
                    chars[i] = '0';
                    lowerCount--;
                    digitCount++;
                }
            } 
            else if (currentType == CharType.UPPERCASE && upperCount > 1) {
                if (lowerCount == 0) {
                    chars[i] = 'a';
                    upperCount--;
                    lowerCount++;
                } else if (digitCount == 0) {
                    chars[i] = '0';
                    upperCount--;
                    digitCount++;
                }
            } 
            else if (currentType == CharType.DIGIT && digitCount > 1) {
                if (lowerCount == 0) {
                    chars[i] = 'a';
                    digitCount--;
                    lowerCount++;
                } else if (upperCount == 0) {
                    chars[i] = 'A';
                    digitCount--;
                    upperCount++;
                }
            }
        }

        return new String(chars);
    }
}

