/**
 * A utility class to ensure strings contain at least one lowercase letter,
 * one uppercase letter, and one digit.
 */
class StringRequirementFixer {

    /**
     * Checks if the given string meets the requirements:
     * At least one lowercase, one uppercase, and one digit.
     */
    public boolean isRequirementMet(String s, int lowercaseCount, int uppercaseCount, int digitCount) {
        return lowercaseCount > 0 && uppercaseCount > 0 && digitCount > 0;
    }

    /**
     * Attempts to fix the string by changing characters to satisfy missing requirements.
     * If two categories are missing, it changes two characters.
     * If one category is missing, it changes one character.
     */
    public String fixString(String s, int lowercaseCount, int uppercaseCount, int digitCount) {
        char[] chars = s.toCharArray();

        // Case 1: Missing Uppercase and Digits (Only lowercase exists)
        if (uppercaseCount == 0 && digitCount == 0) {
            if (chars.length >= 2) {
                chars[0] = 'A';
                chars[1] = '1';
            }
            return new String(chars);
        }

        // Case 2: Missing Uppercase and Lowercase (Only digits exist)
        if (uppercaseCount == 0 && lowercaseCount == 0) {
            if (chars.length >= 2) {
                chars[0] = 'A';
                chars[1] = 'a';
            }
            return new String(chars);
        }

        // Case 3: Missing Lowercase and Digits (Only uppercase exists)
        if (lowercaseCount == 0 && digitCount == 0) {
            if (chars.length >= 2) {
                chars[0] = 'a';
                chars[1] = '1';
            }
            return new String(chars);
        }

        // Case 4: Exactly one category is missing.
        // We look for a character in a category that has more than one occurrence
        // to ensure we don't destroy the only existing character of that type.
        for (int i = 0; i < chars.length; i++) {
            char currentChar = chars[i];

            if (Character.isUpperCase(currentChar) && uppercaseCount > 1) {
                if (lowercaseCount == 0) {
                    chars[i] = 'a';
                    break;
                } else if (digitCount == 0) {
                    chars[i] = '1';
                    break;
                }
            } else if (Character.isLowerCase(currentChar) && lowercaseCount > 1) {
                if (uppercaseCount == 0) {
                    chars[i] = 'A';
                    break;
                } else if (digitCount == 0) {
                    chars[i] = '1';
                    break;
                }
            } else if (Character.isDigit(currentChar) && digitCount > 1) {
                if (uppercaseCount == 0) {
                    chars[i] = 'A';
                    break;
                } else if (lowercaseCount == 0) {
                    chars[i] = 'a';
                    break;
                }
            }
        }

        return new String(chars);
    }
}

