/**
 * Logic responsible for ensuring a string contains at least one 
 * digit, one lowercase letter, and one uppercase letter.
 */
class StringRequirementFixer {

    private static final char DIGIT_REPLACEMENT = '0';
    private static final char LOWERCASE_REPLACEMENT = 'a';
    private static final char UPPERCASE_REPLACEMENT = 'A';

    /**
     * Fixes the input string to satisfy character requirements.
     *
     * @param input The original string.
     * @return A modified string containing at least one digit, one lowercase, and one uppercase.
     */
    public String fix(String input) {
        char[] chars = input.toCharArray();
        List<Integer> digitIndices = new ArrayList<>();
        List<Integer> lowercaseIndices = new ArrayList<>();
        List<Integer> uppercaseIndices = new ArrayList<>();

        // Categorize indices of existing characters
        for (int i = 0; i < chars.length; i++) {
            if (Character.isDigit(chars[i])) {
                digitIndices.add(i);
            } else if (Character.isLowerCase(chars[i])) {
                lowercaseIndices.add(i);
            } else if (Character.isUpperCase(chars[i])) {
                uppercaseIndices.add(i);
            }
        }

        // Ensure a digit exists
        if (digitIndices.isEmpty()) {
            if (lowercaseIndices.size() > 1) {
                chars[lowercaseIndices.remove(0)] = DIGIT_REPLACEMENT;
            } else {
                chars[uppercaseIndices.remove(0)] = DIGIT_REPLACEMENT;
            }
        }

        // Ensure a lowercase letter exists
        if (lowercaseIndices.isEmpty()) {
            if (digitIndices.size() > 1) {
                chars[digitIndices.remove(0)] = LOWERCASE_REPLACEMENT;
            } else {
                chars[uppercaseIndices.remove(0)] = LOWERCASE_REPLACEMENT;
            }
        }

        // Ensure an uppercase letter exists
        if (uppercaseIndices.isEmpty()) {
            if (digitIndices.size() > 1) {
                chars[digitIndices.remove(0)] = UPPERCASE_REPLACEMENT;
            } else {
                chars[lowercaseIndices.remove(0)] = UPPERCASE_REPLACEMENT;
            }
        }

        return new String(chars);
    }
}

