import java.util.*;

/**
 * Solution to ensure a string contains at least one lowercase letter, 
 * one uppercase letter, and one digit.
 */
public class CharacterRequirementSolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);
        CharacterRequirementSolver solver = new CharacterRequirementSolver();

        try {
            int testCases = reader.nextInt();
            for (int i = 1; i <= testCases; i++) {
                solver.solve(reader, writer);
            }
        } catch (Exception e) {
            // In a production environment, use a logger
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    /**
     * Core logic to find the minimum changes required to satisfy character requirements.
     */
    public void solve(FastReader in, PrintWriter out) {
        String input = in.next();
        if (input == null) return;

        char[] s = input.toCharArray();

        // Case 1: String already satisfies requirements
        if (hasRequiredCharacters(s)) {
            out.println(new String(s));
            return;
        }

        int n = s.length;
        char[] targets = {'a', 'A', '0'};

        // Case 2: Try changing exactly one character
        for (int i = 0; i < n; i++) {
            char originalChar = s[i];
            for (char target : targets) {
                s[i] = target;
                if (hasRequiredCharacters(s)) {
                    out.println(new String(s));
                    return;
                }
            }
            s[i] = originalChar; // Backtrack
        }

        // Case 3: Try changing two adjacent characters
        for (int i = 0; i < n - 1; i++) {
            char originalI = s[i];
            char originalNext = s[i + 1];

            for (int j = 0; j < 3; j++) {
                s[i] = targets[j];
                s[i + 1] = targets[(j + 1) % 3];

                if (hasRequiredCharacters(s)) {
                    out.println(new String(s));
                    return;
                }
            }
            s[i] = originalI;    // Backtrack
            s[i + 1] = originalNext;
        }

        // Case 4: Fallback - Force the first three characters to satisfy requirements
        // Only possible if string length is at least 3
        if (n >= 3) {
            s[0] = 'a';
            s[1] = 'A';
            s[2] = '0';
        } else if (n == 2) {
            s[0] = 'a';
            s[1] = 'A';
            // Note: If n < 3, a string can never satisfy 3 distinct types
        } else if (n == 1) {
            s[0] = 'a';
        }

        out.println(new String(s));
    }

    /**
     * Checks if the character array contains at least one lowercase, one uppercase, and one digit.
     */
    private boolean hasRequiredCharacters(char[] s) {
        boolean hasLower = false;
        boolean hasUpper = false;
        boolean hasDigit = false;

        for (char c : s) {
            if (Character.isLowerCase(c)) hasLower = true;
            else if (Character.isUpperCase(c)) hasUpper = true;
            else if (Character.isDigit(c)) hasDigit = true;

            if (hasLower && hasUpper && hasDigit) {
                return true;
            }
        }
        return false;
    }

    /**
     * Optimized reader for fast I/O performance.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

