import java.util.function.Predicate;

/**
 * StringRequirementFixer ensures that a given string contains at least 
 * one lowercase letter, one uppercase letter, and one digit.
 * 
 * If the requirements are not met, it modifies the first two characters 
 * of the string to satisfy the missing requirements while attempting 
 * to preserve existing ones.
 */
public class StringRequirementFixer {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int testCases = scanner.nextInt();
        while (testCases-- > 0) {
            if (scanner.hasNext()) {
                String input = scanner.next();
                System.out.println(processString(input));
            }
        }
        scanner.close();
    }

    /**
     * Analyzes the string and applies transformations if requirements are missing.
     * 
     * @param s The input string.
     * @return The original or modified string.
     */
    public static String processString(String s) {
        char[] chars = s.toCharArray();

        // The original logic assumes the string has at least 2 characters 
        // to allow modifying index 0 and 1.
        if (chars.length < 2) {
            return s;
        }

        int lowerCount = countOccurrences(chars, Character::isLowerCase);
        int upperCount = countOccurrences(chars, Character::isUpperCase);
        int digitCount = countOccurrences(chars, Character::isDigit);

        // Requirement 1: All three types must exist.
        boolean allRequirementsMet = lowerCount > 0 && upperCount > 0 && digitCount > 0;
        if (allRequirementsMet) {
            return s;
        }

        // Case A: Exactly two requirements are met; we need to add the third.
        if (lowerCount > 0 && upperCount > 0) {
            // Missing digit: replace a character with '0'
            replaceCharacterToMaintain(chars, '0', Character::isLowerCase, Character::isUpperCase);
        } else if (lowerCount > 0 && digitCount > 0) {
            // Missing uppercase: replace a character with 'A'
            replaceCharacterToMaintain(chars, 'A', Character::isLowerCase, Character::isDigit);
        } else if (upperCount > 0 && digitCount > 0) {
            // Missing lowercase: replace a character with 'a'
            replaceCharacterToMaintain(chars, 'a', Character::isUpperCase, Character::isDigit);
        } 
        // Case B: Only one requirement is met; we need to add the other two.
        else if (lowerCount > 0) {
            // Only lowercase exists; add digit and uppercase.
            chars[0] = '0';
            chars[1] = 'A';
        } else if (upperCount > 0) {
            // Only uppercase exists; add lowercase and digit.
            chars[0] = 'a';
            chars[1] = '0';
        } 
        // Case C: Only digits exist, or no required characters exist.
        else {
            // Add lowercase and uppercase.
            chars[0] = 'a';
            chars[1] = 'A';
        }

        return new String(chars);
    }

    /**
     * Attempts to replace one of the first two characters with the replacement character.
     * It checks if index 0 is the only representative of an existing required type 
     * to avoid breaking current requirements.
     *
     * @param chars The character array to modify.
     * @param replacement The character to insert.
     * @param typeA Predicate for the first existing type.
     * @param typeB Predicate for the second existing type.
     */
    private static void replaceCharacterToMaintain(char[] chars, char replacement, 
                                                   Predicate<Character> typeA, 
                                                   Predicate<Character> typeB) {
        int countA = countOccurrences(chars, typeA);
        int countB = countOccurrences(chars, typeB);

        // Determine if chars[0] is "vital" (the only character of its type).
        boolean index0IsVital = (typeA.test(chars[0]) && countA == 1) || 
                                (typeB.test(chars[0]) && countB == 1);

        if (index0IsVital) {
            chars[1] = replacement;
        } else {
            chars[0] = replacement;
        }
    }

    /**
     * Counts how many characters in the array satisfy the given predicate.
     */
    private static int countOccurrences(char[] chars, Predicate<Character> predicate) {
        int count = 0;
        for (char c : chars) {
            if (predicate.test(c)) {
                count++;
            }
        }
        return count;
    }
}

import java.util.Scanner;
