/**
 * A utility class designed to ensure strings meet specific complexity requirements:
 * containing at least one lowercase letter, one uppercase letter, and one digit.
 */
class PasswordStrengthFixer {

    /**
     * Analyzes the input string and modifies it if it lacks any of the 
     * required character types (lowercase, uppercase, or digits).
     *
     * @param input The string to validate and potentially fix.
     * @return The original string if valid, or a modified version if invalid.
     */
    public String fixString(String input) {
        if (input == null || input.isEmpty()) {
            return input;
        }

        char[] characters = input.toCharArray();
        int lowercaseCount = countCharacters(characters, Character::isLowerCase);
        int uppercaseCount = countCharacters(characters, Character::isUpperCase);
        int digitCount = countCharacters(characters, Character::isDigit);

        // If all requirements are already met, return the original string.
        if (lowercaseCount > 0 && uppercaseCount > 0 && digitCount > 0) {
            return input;
        }

        applyRequiredFixes(characters, lowercaseCount, uppercaseCount, digitCount);
        return new String(characters);
    }

    /**
     * Determines which types are missing and routes to the appropriate fixing strategy.
     */
    private void applyRequiredFixes(char[] chars, int lc, int uc, int d) {
        // Case 1: Two types of characters are missing.
        // We overwrite the first two positions to ensure requirements are met.
        if (lc == 0 && uc == 0) {
            chars[0] = 'a';
            chars[1] = 'A';
        } else if (lc == 0 && d == 0) {
            chars[0] = 'a';
            chars[1] = '1';
        } else if (uc == 0 && d == 0) {
            chars[0] = 'A';
            chars[1] = '1';
        } 
        // Case 2: Only one type of character is missing.
        else if (lc == 0) {
            handleMissingLowercase(chars, d);
        } else if (uc == 0) {
            handleMissingUppercase(chars, d);
        } else if (d == 0) {
            handleMissingDigit(chars, uc);
        }
    }

    private void handleMissingLowercase(char[] chars, int digitCount) {
        // If we have multiple digits, we can safely convert one to lowercase.
        // Otherwise, we convert an uppercase letter to lowercase to preserve the digit.
        if (digitCount > 1) {
            replaceFirst(chars, Character::isDigit, 'a');
        } else {
            replaceFirst(chars, Character::isUpperCase, 'a');
        }
    }

    private void handleMissingUppercase(char[] chars, int digitCount) {
        if (digitCount > 1) {
            replaceFirst(chars, Character::isDigit, 'A');
        } else {
            replaceFirst(chars, Character::isLowerCase, 'A');
        }
    }

    private void handleMissingDigit(char[] chars, int uppercaseCount) {
        if (uppercaseCount > 1) {
            replaceFirst(chars, Character::isUpperCase, '1');
        } else {
            replaceFirst(chars, Character::isLowerCase, '1');
        }
    }

    /**
     * Counts how many characters in the array satisfy the given condition.
     */
    private int countCharacters(char[] chars, Predicate<Character> condition) {
        int count = 0;
        for (char c : chars) {
            if (condition.test(c)) {
                count++;
            }
        }
        return count;
    }

    /**
     * Finds the first character satisfying the condition and replaces it.
     */
    private void replaceFirst(char[] chars, Predicate<Character> condition, char replacement) {
        for (int i = 0; i < chars.length; i++) {
            if (condition.test(chars[i])) {
                chars[i] = replacement;
                break;
            }
        }
    }
}

