/**
 * Logic class responsible for ensuring strings contain 
 * at least one uppercase, one lowercase, and one digit.
 */
class PasswordFixer {

    /**
     * Analyzes the string and applies rules to ensure it contains
     * an uppercase letter, a lowercase letter, and a digit.
     *
     * @param input The string to process.
     * @return The processed string.
     */
    public String fixStringDiversity(String input) {
        int upperCount = countOccurrences(input, Character::isUpperCase);
        int lowerCount = countOccurrences(input, Character::isLowerCase);
        int digitCount = countOccurrences(input, Character::isDigit);

        // Case 1: Two categories are missing - Prepend required characters
        // Note: Based on original logic, we replace the first two characters
        if (upperCount == 0 && lowerCount == 0) {
            return patchMissingTwo(input, 'a', 'A');
        } else if (lowerCount == 0 && digitCount == 0) {
            return patchMissingTwo(input, '1', 'a');
        } else if (upperCount == 0 && digitCount == 0) {
            return patchMissingTwo(input, '1', 'A');
        }

        // Case 2: One category is missing - Replace an existing extra character
        if (upperCount == 0) {
            return tryReplaceMissingType(input, lowerCount, Character::isLowerCase, 'A', 
                                         digitCount, Character::isDigit, 'A');
        } else if (lowerCount == 0) {
            return tryReplaceMissingType(input, upperCount, Character::isUpperCase, 'a', 
                                         digitCount, Character::isDigit, 'a');
        } else if (digitCount == 0) {
            return tryReplaceMissingType(input, lowerCount, Character::isLowerCase, '1', 
                                         upperCount, Character::isUpperCase, '1');
        }

        return input;
    }

    private int countOccurrences(String s, Predicate<Character> condition) {
        int count = 0;
        for (char c : s.toCharArray()) {
            if (condition.test(c)) {
                count++;
            }
        }
        return count;
    }

    /**
     * Safely mimics the original "replace first two characters" logic.
     */
    private String patchMissingTwo(String s, char first, char second) {
        StringBuilder sb = new StringBuilder();
        sb.append(first).append(second);
        if (s.length() > 2) {
            sb.append(s.substring(2));
        }
        return sb.toString();
    }

    /**
     * Attempts to replace a character of type A with the missing type, 
     * or if type A is not abundant, tries type B.
     */
    private String tryReplaceMissingType(String s, 
                                         int typeACount, Predicate<Character> typeACond, char replacementA,
                                         int typeBCount, Predicate<Character> typeBCond, char replacementB) {
        if (typeACount > 1) {
            return replaceFirstMatching(s, typeACond, replacementA);
        } else if (typeBCount > 1) {
            return replaceFirstMatching(s, typeBCond, replacementB);
        }
        return s;
    }

    private String replaceFirstMatching(String s, Predicate<Character> condition, char replacement) {
        char[] chars = s.toCharArray();
        for (int i = 0; i < chars.length; i++) {
            if (condition.test(chars[i])) {
                chars[i] = replacement;
                return new String(chars);
            }
        }
        return s;
    }
}

