/**
 * A program that ensures a string contains at least one lowercase letter,
 * one uppercase letter, and one digit.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int testCases = reader.nextInt();
            while (testCases-- > 0) {
                String input = reader.next();
                out.println(ensureCharacterDiversity(input));
            }
        } catch (NoSuchElementException e) {
            // Handle unexpected end of input
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Transforms the input string to ensure it contains at least one lowercase,
     * one uppercase, and one digit.
     *
     * @param s The input string.
     * @return A modified string satisfying the requirements.
     */
    private static String ensureCharacterDiversity(String s) {
        if (s == null || s.isEmpty()) {
            return s;
        }

        char[] chars = s.toCharArray();
        int lowerCount = 0;
        int upperCount = 0;
        int digitCount = 0;

        // Count existing character types
        for (char c : chars) {
            if (Character.isLowerCase(c)) lowerCount++;
            else if (Character.isUpperCase(c)) upperCount++;
            else if (Character.isDigit(c)) digitCount++;
        }

        // Case 1: All requirements already met
        if (lowerCount > 0 && upperCount > 0 && digitCount > 0) {
            return s;
        }

        // Case 2: Two types are missing
        if (lowerCount == 0 && upperCount == 0) {
            if (chars.length >= 2) {
                chars[0] = 'a';
                chars[1] = 'A';
            }
        } else if (upperCount == 0 && digitCount == 0) {
            if (chars.length >= 2) {
                chars[0] = '0';
                chars[1] = 'A';
            }
        } else if (lowerCount == 0 && digitCount == 0) {
            if (chars.length >= 2) {
                chars[0] = 'a';
                chars[1] = '0';
            }
        } 
        // Case 3: One type is missing
        else if (lowerCount == 0) {
            // Attempt to replace an existing uppercase or digit character
            // ensuring we don't remove the last existing character of that type.
            for (int i = 0; i < chars.length; i++) {
                if (Character.isUpperCase(chars[i]) && upperCount >= 2) {
                    chars[i] = 'a';
                    break;
                } else if (Character.isDigit(chars[i]) && digitCount >= 2) {
                    chars[i] = 'a';
                    break;
                }
            }
        } else if (upperCount == 0) {
            for (int i = 0; i < chars.length; i++) {
                if (Character.isLowerCase(chars[i]) && lowerCount >= 2) {
                    chars[i] = 'A';
                    break;
                } else if (Character.isDigit(chars[i]) && digitCount >= 2) {
                    chars[i] = 'A';
                    break;
                }
            }
        } else if (digitCount == 0) {
            for (int i = 0; i < chars.length; i++) {
                if (Character.isUpperCase(chars[i]) && upperCount >= 2) {
                    chars[i] = '0';
                    break;
                } else if (Character.isLowerCase(chars[i]) && lowerCount >= 2) {
                    chars[i] = '0';
                    break;
                }
            }
        }

        return new String(chars);
    }

    /**
     * Fast I/O helper class for efficient reading of input data.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }
    }
}

