import java.io.*;

/**
 * Solution class to process strings and ensure they contain at least one 
 * uppercase letter, one lowercase letter, and one digit.
 */
public class Solution {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        String testCasesStr = reader.next();
        if (testCasesStr != null) {
            int testCases = Integer.parseInt(testCasesStr);
            while (testCases-- > 0) {
                processTestCase(reader, writer);
            }
        }

        writer.flush();
        writer.close();
    }

    /**
     * Reads a test case, applies transformation logic if necessary, 
     * and writes the result.
     */
    private static void processTestCase(FastReader reader, PrintWriter writer) {
        String input = reader.next();
        if (input == null) {
            return;
        }

        char[] characters = input.toCharArray();
        int upperCount = 0;
        int lowerCount = 0;
        int digitCount = 0;

        // Initial count of character types
        for (char c : characters) {
            if (Character.isUpperCase(c)) {
                upperCount++;
            } else if (Character.isLowerCase(c)) {
                lowerCount++;
            } else if (Character.isDigit(c)) {
                digitCount++;
            }
        }

        // If the string already satisfies the condition, print and return
        if (upperCount > 0 && lowerCount > 0 && digitCount > 0) {
            writer.println(input);
            return;
        }

        // Attempt to satisfy the condition by converting redundant characters
        for (int i = 0; i < characters.length; i++) {
            char current = characters[i];

            if (Character.isUpperCase(current) && upperCount > 1) {
                if (lowerCount == 0) {
                    characters[i] = Character.toLowerCase(current);
                    upperCount--;
                    lowerCount++;
                } else if (digitCount == 0) {
                    characters[i] = '1';
                    upperCount--;
                    digitCount++;
                }
            } else if (Character.isLowerCase(current) && lowerCount > 1) {
                if (upperCount == 0) {
                    characters[i] = Character.toUpperCase(current);
                    lowerCount--;
                    upperCount++;
                } else if (digitCount == 0) {
                    characters[i] = '1';
                    lowerCount--;
                    digitCount++;
                }
            } else if (Character.isDigit(current) && digitCount > 1) {
                if (lowerCount == 0) {
                    characters[i] = 'a';
                    digitCount--;
                    lowerCount++;
                } else if (upperCount == 0) {
                    characters[i] = 'A';
                    digitCount--;
                    upperCount++;
                }
            }

            // Optimization: stop early if requirements are met
            if (upperCount > 0 && lowerCount > 0 && digitCount > 0) {
                break;
            }
        }

        writer.println(new String(characters));
    }

    /**
     * FastReader class for efficient input parsing.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream inputStream) {
            br = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }
    }
}

import java.util.Scanner;
import java.util.function.Predicate;

/**
 * A utility to ensure strings contain at least one uppercase letter, 
 * one lowercase letter, and one digit.
 */
public class StringRequirementFixer {

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int testCases = scanner.nextInt();
            scanner.nextLine(); // Consume the leftover newline

            for (int i = 0; i < testCases; i++) {
                if (scanner.hasNextLine()) {
                    String input = scanner.nextLine();
                    System.out.println(processString(input));
                }
            }
        }
    }

    /**
     * Analyzes and modifies the input string to ensure it meets 
     * character type requirements.
     *
     * @param input The string to process.
     * @return The modified string, or the original if requirements were met.
     */
    public static String processString(String input) {
        if (input == null || input.isEmpty()) {
            return input;
        }

        StringBuilder sb = new StringBuilder(input);
        StringStats stats = new StringStats(sb.toString());

        // If all requirements are already met, return the string as-is
        if (stats.hasUppercase && stats.hasLowercase && stats.hasDigit) {
            return sb.toString();
        }

        // Scenario 1: Multiple requirements are missing
        if (!stats.hasLowercase && !stats.hasUppercase && !stats.hasDigit) {
            applyMultipleFixes(sb, 'a', 'A', '1');
        } else if (!stats.hasLowercase && !stats.hasUppercase) {
            applyMultipleFixes(sb, 'a', 'A', null);
        } else if (!stats.hasLowercase && !stats.hasDigit) {
            applyMultipleFixes(sb, 'a', null, '1');
        } else if (!stats.hasUppercase && !stats.hasDigit) {
            applyMultipleFixes(sb, null, 'A', '1');
        } 
        // Scenario 2: Only one requirement is missing
        else {
            if (!stats.hasLowercase) {
                ensureLowercase(sb, stats);
            } else if (!stats.hasUppercase) {
                ensureUppercase(sb, stats);
            } else if (!stats.hasDigit) {
                ensureDigit(sb, stats);
            }
        }

        return sb.toString();
    }

    /**
     * Sets the first few indices of the string to required characters.
     */
    private static void applyMultipleFixes(StringBuilder sb, Character c1, Character c2, Character c3) {
        if (sb.length() >= 1 && c1 != null) sb.setCharAt(0, c1);
        if (sb.length() >= 2 && c2 != null) sb.setCharAt(1, c2);
        if (sb.length() >= 3 && c3 != null) sb.setCharAt(2, c3);
    }

    private static void ensureLowercase(StringBuilder sb, StringStats stats) {
        // Priority 1: Replace a redundant digit
        if (stats.digitCount > 1) {
            replaceFirst(sb, Character::isDigit, 'a');
        } 
        // Priority 2: Replace a redundant uppercase
        else if (stats.uppercaseCount > 1) {
            replaceFirst(sb, Character::isUpperCase, 'a');
        } 
        // Fallback: Replace the first character that isn't lowercase
        else {
            replaceFirst(sb, c -> !Character.isLowerCase(c), 'a');
        }
    }

    private static void ensureUppercase(StringBuilder sb, StringStats stats) {
        if (stats.digitCount > 1) {
            replaceFirst(sb, Character::isDigit, 'A');
        } else if (stats.lowercaseCount > 1) {
            replaceFirst(sb, Character::isLowerCase, 'A');
        } else {
            replaceFirst(sb, c -> !Character.isUpperCase(c), 'A');
        }
    }

    private static void ensureDigit(StringBuilder sb, StringStats stats) {
        if (stats.uppercaseCount > 1) {
            replaceFirst(sb, Character::isUpperCase, '1');
        } else if (stats.lowercaseCount > 1) {
            replaceFirst(sb, Character::isLowerCase, '1');
        } else {
            replaceFirst(sb, c -> !Character.isDigit(c), '1');
        }
    }

    /**
     * Finds the first character in the StringBuilder that matches the 
     * given condition and replaces it.
     */
    private static void replaceFirst(StringBuilder sb, Predicate<Character> condition, char replacement) {
        for (int i = 0; i < sb.length(); i++) {
            if (condition.test(sb.charAt(i))) {
                sb.setCharAt(i, replacement);
                return;
            }
        }
    }

    /**
     * Data carrier for character type statistics.
     */
    private static class StringStats {
        final int uppercaseCount;
        final int lowercaseCount;
        final int digitCount;

        final boolean hasUppercase;
        final boolean hasLowercase;
        final boolean hasDigit;

        StringStats(String s) {
            int u = 0, l = 0, d = 0;
            for (char c : s.toCharArray()) {
                if (Character.isUpperCase(c)) u++;
                else if (Character.isLowerCase(c)) l++;
                else if (Character.isDigit(c)) d++;
            }
            this.uppercaseCount = u;
            this.lowercaseCount = l;
            this.digitCount = d;
            this.hasUppercase = u > 0;
            this.hasLowercase = l > 0;
            this.hasDigit = d > 0;
        }
    }
}

