/**
 * A utility to ensure strings meet specific character type requirements:
 * at least one uppercase letter, one lowercase letter, and one digit.
 */
public class StringRequirementFixer {

    /**
     * Represents the counts of different character types within a string.
     */
    private record CharacterCounts(int upperCaseCount, int lowerCaseCount, int digitCount) {}

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int testCaseCount = scanner.nextInt();
            StringRequirementFixer fixer = new StringRequirementFixer();

            for (int i = 0; i < testCaseCount; i++) {
                if (scanner.hasNext()) {
                    String input = scanner.next();
                    String result = fixer.processString(input);
                    System.out.println(result);
                }
            }
        }
    }

    /**
     * Processes a single string to ensure it contains at least one uppercase,
     * one lowercase, and one digit.
     *
     * @param input The original string.
     * @return The modified string meeting the requirements.
     */
    public String processString(String input) {
        char[] chars = input.toCharArray();
        CharacterCounts counts = countCharacterTypes(chars);

        // The original logic uses the initial counts to decide replacements,
        // even if the character array is modified mid-process.
        ensureLowercaseRequirement(chars, counts);
        ensureUppercaseRequirement(chars, counts);
        ensureDigitRequirement(chars, counts);

        return new String(chars);
    }

    private CharacterCounts countCharacterTypes(char[] chars) {
        int upper = 0;
        int lower = 0;
        int digit = 0;

        for (char c : chars) {
            if (Character.isUpperCase(c)) {
                upper++;
            } else if (Character.isLowerCase(c)) {
                lower++;
            } else if (Character.isDigit(c)) {
                digit++;
            }
        }
        return new CharacterCounts(upper, lower, digit);
    }

    private void ensureLowercaseRequirement(char[] chars, CharacterCounts counts) {
        if (counts.lowerCaseCount == 0) {
            if (counts.upperCaseCount > 1) {
                replaceFirstMatch(chars, Character::isUpperCase, 'a');
            } else {
                replaceFirstMatch(chars, Character::isDigit, 'a');
            }
        }
    }

    private void ensureUppercaseRequirement(char[] chars, CharacterCounts counts) {
        if (counts.upperCaseCount == 0) {
            if (counts.lowerCaseCount > 1) {
                replaceFirstMatch(chars, Character::isLowerCase, 'A');
            } else {
                replaceFirstMatch(chars, Character::isDigit, 'A');
            }
        }
    }

    private void ensureDigitRequirement(char[] chars, CharacterCounts counts) {
        if (counts.digitCount == 0) {
            if (counts.upperCaseCount > 1) {
                replaceFirstMatch(chars, Character::isUpperCase, '1');
            } else {
                replaceFirstMatch(chars, Character::isLowerCase, '1');
            }
        }
    }

    /**
     * Finds the first character in the array that matches the predicate 
     * and replaces it with the specified character.
     */
    private void replaceFirstMatch(char[] chars, Predicate<Character> condition, char replacement) {
        for (int i = 0; i < chars.length; i++) {
            if (condition.test(chars[i])) {
                chars[i] = replacement;
                break;
            }
        }
    }
}

