/**
 * Encapsulates the logic for transforming a string so that it 
 * contains at least one lowercase letter, one uppercase letter, and one digit.
 */
class ProblemSolver {

    /**
     * Processes the input string and returns a modified version that 
     * meets the character requirements.
     *
     * @param input The original string.
     * @return A valid string according to requirements.
     */
    public String solve(String input) {
        if (input == null || input.isEmpty()) {
            return input;
        }

        char[] chars = input.toCharArray();

        if (isComplete(chars)) {
            return input;
        }

        boolean hasLower = containsLower(chars);
        boolean hasUpper = containsUpper(chars);
        boolean hasDigit = containsDigit(chars);

        int missingCount = calculateMissingCount(hasLower, hasUpper, hasDigit);

        // If only one category is missing, try replacing one character at a time.
        if (missingCount == 1) {
            return trySingleReplacement(chars, hasLower, hasUpper, hasDigit);
        } else {
            // If multiple categories are missing, force-inject them.
            return applyForceFix(chars, hasLower, hasUpper, hasDigit);
        }
    }

    private int calculateMissingCount(boolean hasLower, boolean hasUpper, boolean hasDigit) {
        int count = 0;
        if (!hasLower) count++;
        if (!hasUpper) count++;
        if (!hasDigit) count++;
        return count;
    }

    /**
     * Attempts to satisfy the requirement by changing exactly one character.
     * This preserves existing character types in the string.
     */
    private String trySingleReplacement(char[] chars, boolean hasLower, boolean hasUpper, boolean hasDigit) {
        char replacement = getRequiredCharacter(hasLower, hasUpper, hasDigit);

        for (int i = 0; i < chars.length; i++) {
            char originalChar = chars[i];
            chars[i] = replacement;

            if (isComplete(chars)) {
                return new String(chars);
            }

            // Backtrack if this replacement didn't satisfy all conditions
            chars[i] = originalChar;
        }

        // Fallback to multi-replacement if a single swap isn't sufficient
        return applyForceFix(chars, hasLower, hasUpper, hasDigit);
    }

    private char getRequiredCharacter(boolean hasLower, boolean hasUpper, boolean hasDigit) {
        if (!hasLower) return 'a';
        if (!hasUpper) return 'A';
        return '1'; // must be digit
    }

    /**
     * Safely replaces characters at the beginning of the array to satisfy requirements.
     * This method is safe for strings of any length.
     */
    private String applyForceFix(char[] chars, boolean hasLower, boolean hasUpper, boolean hasDigit) {
        int pointer = 0;
        if (!hasLower && pointer < chars.length) {
            chars[pointer++] = 'a';
        }
        if (!hasUpper && pointer < chars.length) {
            chars[pointer++] = 'A';
        }
        if (!hasDigit && pointer < chars.length) {
            chars[pointer++] = '1';
        }
        return new String(chars);
    }

    // --- Validation Helpers ---

    private boolean isComplete(char[] chars) {
        return containsLower(chars) && containsUpper(chars) && containsDigit(chars);
    }

    private boolean containsLower(char[] chars) {
        for (char c : chars) {
            if (Character.isLowerCase(c)) return true;
        }
        return false;
    }

    private boolean containsUpper(char[] chars) {
        for (char c : chars) {
            if (Character.isUpperCase(c)) return true;
        }
        return false;
    }

    private boolean containsDigit(char[] chars) {
        for (char c : chars) {
            if (Character.isDigit(c)) return true;
        }
        return false;
    }
}

import java.util.*;

/**
 * A utility to ensure strings contain at least one uppercase letter, 
 * one lowercase letter, and one digit by replacing redundant characters.
 */
public class StringDiversityFixer {

    /**
     * Represents the three required character categories and their 
     * respective replacement characters.
     */
    enum CharType {
        UPPERCASE('A'),
        LOWERCASE('a'),
        DIGIT('1');

        final char replacementChar;

        CharType(char replacementChar) {
            this.replacementChar = replacementChar;
        }

        /**
         * Maps a character to its corresponding CharType.
         */
        static CharType getType(char c) {
            if (Character.isUpperCase(c)) return UPPERCASE;
            if (Character.isLowerCase(c)) return LOWERCASE;
            if (Character.isDigit(c)) return DIGIT;
            return null;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int testCases = scanner.nextInt();
        for (int t = 0; t < testCases; t++) {
            String input = scanner.next();
            System.out.println(processString(input));
        }

        scanner.close();
    }

    /**
     * Processes a single string to ensure diversity of character types.
     * 
     * @param input The original string.
     * @return The modified string containing at least one of each type if possible.
     */
    private static String processString(String input) {
        if (input == null || input.isEmpty()) {
            return input;
        }

        int n = input.length();
        Map<CharType, Integer> typeCounts = countCharacterTypes(input);
        List<CharType> missingTypes = findMissingTypes(typeCounts);

        StringBuilder sb = new StringBuilder(input);

        // Case 0: All types are already present
        if (missingTypes.isEmpty()) {
            return sb.toString();
        }

        // Case 1: Exactly one type is missing
        if (missingTypes.size() == 1) {
            CharType missing = missingTypes.get(0);
            replaceFirstRedundantChar(sb, typeCounts, missing);
        } 
        // Case 2: Two types are missing
        else if (missingTypes.size() == 2) {
            // Note: Assumes input length >= 2 based on original logic requirements
            if (n >= 2) {
                sb.setCharAt(0, missingTypes.get(0).replacementChar);
                sb.setCharAt(1, missingTypes.get(1).replacementChar);
            }
        }

        return sb.toString();
    }

    /**
     * Counts occurrences of each CharType in the string.
     */
    private static Map<CharType, Integer> countCharacterTypes(String input) {
        Map<CharType, Integer> counts = new EnumMap<>(CharType.class);
        for (CharType type : CharType.values()) {
            counts.put(type, 0);
        }

        for (char c : input.toCharArray()) {
            CharType type = CharType.getType(c);
            if (type != null) {
                counts.put(type, counts.get(type) + 1);
            }
        }
        return counts;
    }

    /**
     * Identifies which CharTypes have a count of zero.
     */
    private static List<CharType> findMissingTypes(Map<CharType, Integer> counts) {
        List<CharType> missing = new ArrayList<>();
        for (CharType type : CharType.values()) {
            if (counts.get(type) == 0) {
                missing.add(type);
            }
        }
        return missing;
    }

    /**
     * Replaces the first character found that belongs to a non-unique type 
     * with the missing type's replacement character.
     */
    private static void replaceFirstRedundantChar(StringBuilder sb, Map<CharType, Integer> counts, CharType missingType) {
        for (int i = 0; i < sb.length(); i++) {
            CharType currentType = CharType.getType(sb.charAt(i));
            // If this character's type has more than one occurrence, it's redundant
            if (currentType != null && counts.get(currentType) > 1) {
                sb.setCharAt(i, missingType.replacementChar);
                break;
            }
        }
    }
}

import java.util.Scanner;

/**
 * A utility class to ensure a string contains at least one digit, 
 * one lowercase letter, and one uppercase letter by modifying at most one character.
 */
public class StringDiversityManager {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int testCases = scanner.nextInt();
        StringDiversityManager manager = new StringDiversityManager();

        for (int i = 1; i <= testCases; i++) {
            if (scanner.hasNext()) {
                String input = scanner.next();
                String result = manager.solve(input);
                System.out.println("Case #" + i + ": " + result);
            }
        }
        scanner.close();
    }

    /**
     * Solves the diversity problem for a given input string.
     *
     * @param input The input string to process.
     * @return The modified string that maximizes character type diversity.
     */
    public String solve(String input) {
        char[] chars = input.toCharArray();
        int n = chars.length;

        int digitCount = 0;
        int lowerCount = 0;
        int upperCount = 0;

        for (char c : chars) {
            if (Character.isDigit(c)) {
                digitCount++;
            } else if (Character.isLowerCase(c)) {
                lowerCount++;
            } else if (Character.isUpperCase(c)) {
                upperCount++;
            }
        }

        // Logic to satisfy the requirement of having digits, lowercase, and uppercase.
        // We follow the priority of the original implementation.
        if (digitCount == 0) {
            handleMissingDigits(chars, n, lowerCount, upperCount);
        } else if (lowerCount == 0) {
            handleMissingLowercase(chars, n, upperCount);
        } else if (upperCount == 0) {
            handleMissingUppercase(chars, n, lowerCount, digitCount);
        }

        return new String(chars);
    }

    private void handleMissingDigits(char[] chars, int n, int lowerCount, int upperCount) {
        if (lowerCount == 0 && upperCount == 0) {
            // Case: No diversity at all, try to add two types if length allows
            if (n >= 2) {
                chars[0] = '1';
                chars[1] = 'a';
            } else if (n >= 1) {
                chars[0] = '1';
            }
        } else if (upperCount == 0) {
            // Case: No uppercase, try to add both digit and uppercase if length allows
            if (n >= 2) {
                chars[0] = '1';
                chars[1] = 'A';
            } else if (n >= 1) {
                chars[0] = '1';
            }
        } else if (lowerCount == 1) {
            // Case: Only one lowercase exists, replace an uppercase to avoid losing lowercase
            replaceFirstOfCategory(chars, Character::isUpperCase, '1');
        } else {
            // Case: Multiple lowercases exist, safely replace one with a digit
            replaceFirstOfCategory(chars, Character::isLowerCase, '1');
        }
    }

    private void handleMissingLowercase(char[] chars, int n, int upperCount) {
        if (upperCount == 0) {
            // Case: No uppercase, add both lowercase and uppercase if length allows
            if (n >= 2) {
                chars[0] = 'a';
                chars[1] = 'A';
            } else if (n >= 1) {
                chars[0] = 'a';
            }
        } else if (upperCount == 1) {
            // Case: Only one uppercase exists, replace a digit to avoid losing uppercase
            replaceFirstOfCategory(chars, Character::isDigit, 'a');
        } else {
            // Case: Multiple uppercases exist, safely replace one with a lowercase
            replaceFirstOfCategory(chars, Character::isUpperCase, 'a');
        }
    }

    private void handleMissingUppercase(char[] chars, int n, int lowerCount, int digitCount) {
        if (lowerCount == 1) {
            // Case: Only one lowercase exists, replace it with uppercase
            replaceFirstOfCategory(chars, Character::isLowerCase, 'A');
        } else {
            // Case: Replace a digit with an uppercase
            replaceFirstOfCategory(chars, Character::isDigit, 'A');
        }
    }

    /**
     * Helper to replace the first character that satisfies a condition.
     */
    private void replaceFirstOfCategory(char[] chars, java.util.function.Predicate<Character> condition, char replacement) {
        for (int i = 0; i < chars.length; i++) {
            if (condition.test(chars[i])) {
                chars[i] = replacement;
                break;
            }
        }
    }
}

