/**
 * Represents the three types of characters we are interested in.
 */
enum CharType {
    LOWER, UPPER, DIGIT;

    /**
     * Checks if a character matches the specified CharType.
     */
    public static boolean is(char c, CharType type) {
        switch (type) {
            case LOWER:
                return Character.isLowerCase(c);
            case UPPER:
                return Character.isUpperCase(c);
            case DIGIT:
                return Character.isDigit(c);
            default:
                return false;
        }
    }
}

/**
 * Service responsible for the business logic of diversifying a string.
 */
class StringDiversityService {

    /**
     * Diversifies the string so it contains at least one character of each type.
     * It uses a strategy of replacing redundant characters (characters of a type 
     * that appear more than once) to avoid destroying existing required types.
     *
     * @param input The original string.
     * @return A modified string containing at least one lowercase, one uppercase, and one digit.
     */
    public String diversify(String input) {
        if (input == null || input.isEmpty()) {
            return input;
        }

        char[] chars = input.toCharArray();

        // The requirement is to ensure all three types are present.
        // We attempt to fix up to two missing categories by replacing redundant characters.
        for (int attempt = 0; attempt < 2; attempt++) {
            int lowCount = countType(chars, CharType.LOWER);
            int upCount = countType(chars, CharType.UPPER);
            int digitCount = countType(chars, CharType.DIGIT);

            if (lowCount == 0) {
                // Missing lowercase: replace a redundant uppercase or digit.
                if (!tryReplace(chars, 'a', CharType.UPPER, CharType.DIGIT)) {
                    break;
                }
            } else if (upCount == 0) {
                // Missing uppercase: replace a redundant lowercase or digit.
                if (!tryReplace(chars, 'A', CharType.LOWER, CharType.DIGIT)) {
                    break;
                }
            } else if (digitCount == 0) {
                // Missing digit: replace a redundant lowercase or uppercase.
                if (!tryReplace(chars, '1', CharType.LOWER, CharType.UPPER)) {
                    break;
                }
            } else {
                // All required types are already present.
                break;
            }
        }

        return new String(chars);
    }

    /**
     * Attempts to replace a character of a redundant type with the specified replacement.
     * 
     * @param chars The character array to modify.
     * @param replacement The character to insert.
     * @param typeA The first type of character we are allowed to replace.
     * @param typeB The second type of character we are allowed to replace.
     * @return true if a replacement was successful, false otherwise.
     */
    private boolean tryReplace(char[] chars, char replacement, CharType typeA, CharType typeB) {
        int idxA = findRedundantIndex(chars, typeA);
        int idxB = findRedundantIndex(chars, typeB);

        // Choose the character that appears earliest in the string.
        int targetIdx = Math.min(idxA, idxB);

        // If targetIdx is Integer.MAX_VALUE, no redundant characters were found to replace.
        if (targetIdx == Integer.MAX_VALUE) {
            return false;
        }

        chars[targetIdx] = replacement;
        return true;
    }

    /**
     * Finds the index of the first occurrence of a character of the given type,
     * but only if that type has more than one occurrence (making it "redundant").
     *
     * @param chars The character array to search.
     * @param type The type of character to look for.
     * @return The index of the first redundant character, or Integer.MAX_VALUE if none exist.
     */
    private int findRedundantIndex(char[] chars, CharType type) {
        int count = countType(chars, type);

        // A character is only "safe" to replace if it's not the last one of its kind.
        if (count <= 1) {
            return Integer.MAX_VALUE;
        }

        for (int i = 0; i < chars.length; i++) {
            if (CharType.is(chars[i], type)) {
                return i;
            }
        }
        return Integer.MAX_VALUE;
    }

    /**
     * Counts how many characters of a specific type exist in the array.
     */
    private int countType(char[] chars, CharType type) {
        int count = 0;
        for (char c : chars) {
            if (CharType.is(c, type)) {
                count++;
            }
        }
        return count;
    }
}

