/**
 * StringBalancer ensures that a given string contains at least one lowercase letter,
 * one uppercase letter, and one digit by modifying existing characters.
 */
public class StringBalancer {

    private enum CharType {
        LOWER, UPPER, DIGIT
    }

    public static void main(String[] args) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String line = reader.readLine();
            if (line == null) return;

            int testCases = Integer.parseInt(line.trim());
            while (testCases-- > 0) {
                String input = reader.readLine();
                if (input != null) {
                    System.out.println(balanceString(input));
                }
            }
        } catch (IOException | NumberFormatException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Analyzes the string and returns a modified version that satisfies the
     * requirement of having at least one lowercase, one uppercase, and one digit.
     */
    private static String balanceString(String s) {
        int lowerCount = 0;
        int upperCount = 0;
        int digitCount = 0;

        // Count occurrences of each character type
        for (char c : s.toCharArray()) {
            if (Character.isLowerCase(c)) {
                lowerCount++;
            } else if (Character.isUpperCase(c)) {
                upperCount++;
            } else if (Character.isDigit(c)) {
                digitCount++;
            }
        }

        boolean hasLower = lowerCount > 0;
        boolean hasUpper = upperCount > 0;
        boolean hasDigit = digitCount > 0;

        // Case 1: All types are already present
        if (hasLower && hasUpper && hasDigit) {
            return s;
        }

        // Case 2: Two types are missing
        if (!hasLower && !hasUpper) {
            return applyTwoTypeReplacement(s, 'A', 'a');
        }
        if (!hasLower && !hasDigit) {
            return applyTwoTypeReplacement(s, 'a', '0');
        }
        if (!hasUpper && !hasDigit) {
            return applyTwoTypeReplacement(s, 'A', '0');
        }

        // Case 3: Only one type is missing
        CharType mostFrequent = getMostFrequentType(lowerCount, upperCount, digitCount);
        if (!hasLower) {
            return replaceFirstOccurrence(s, mostFrequent, 'a');
        } else if (!hasUpper) {
            return replaceFirstOccurrence(s, mostFrequent, 'A');
        } else { // !hasDigit
            return replaceFirstOccurrence(s, mostFrequent, '0');
        }
    }

    /**
     * Determines the most frequent character type based on counts.
     * Follows original tie-breaking logic.
     */
    private static CharType getMostFrequentType(int lower, int upper, int digit) {
        int maxCount = Math.max(lower, Math.max(upper, digit));

        if (maxCount == lower) {
            return CharType.LOWER;
        } else if (maxCount == upper) {
            return CharType.UPPER;
        } else {
            return CharType.DIGIT;
        }
    }

    /**
     * Replaces the first character of the target type with the specified replacement character.
     */
    private static String replaceFirstOccurrence(String s, CharType targetType, char replacement) {
        for (int i = 0; i < s.length(); i++) {
            if (isType(s.charAt(i), targetType)) {
                return s.substring(0, i) + replacement + s.substring(i + 1);
            }
        }
        return s;
    }

    /**
     * Helper to check if a character matches a specific CharType.
     */
    private static boolean isType(char c, CharType type) {
        switch (type) {
            case LOWER: return Character.isLowerCase(c);
            case UPPER: return Character.isUpperCase(c);
            case DIGIT: return Character.isDigit(c);
            default: return false;
        }
    }

    /**
     * Handles cases where two types are missing by replacing the first two characters.
     * Includes a safety check for string length.
     */
    private static String applyTwoTypeReplacement(String s, char first, char second) {
        if (s.length() < 2) {
            StringBuilder sb = new StringBuilder(s);
            if (sb.length() >= 1) sb.setCharAt(0, first);
            if (sb.length() >= 2) sb.setCharAt(1, second);
            return sb.toString();
        }
        return first + "" + second + s.substring(2);
    }
}

