/**
 * A program that ensures a given string contains at least one lowercase letter,
 * one uppercase letter, and one digit. If the requirements are not met,
 * it modifies the string by replacing existing characters.
 */
public class Codechef {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int testCases = scanner.nextInt();
        while (testCases-- > 0) {
            if (scanner.hasNext()) {
                String input = scanner.next();
                System.out.println(satisfyRequirements(input));
            }
        }

        scanner.close();
    }

    /**
     * Checks if the string contains at least one lowercase letter, one uppercase letter, 
     * and one digit. If not, it attempts to replace characters to satisfy the criteria.
     *
     * @param input The string to evaluate and potentially modify.
     * @return The original string if requirements are met, otherwise the modified string.
     */
    private static String satisfyRequirements(String input) {
        char[] resultChars = input.toCharArray();
        int length = resultChars.length;

        int lastLowerIdx = -1;
        int lastUpperIdx = -1;
        int lastDigitIdx = -1;

        // Step 1: Identify the last known positions of required character types
        for (int i = 0; i < length; i++) {
            char c = resultChars[i];
            if (Character.isLowerCase(c)) {
                lastLowerIdx = i;
            } else if (Character.isUpperCase(c)) {
                lastUpperIdx = i;
            } else if (Character.isDigit(c)) {
                lastDigitIdx = i;
            }
        }

        // Step 2: If all three requirements are met, return the original string
        if (lastLowerIdx != -1 && lastUpperIdx != -1 && lastDigitIdx != -1) {
            return input;
        }

        // Step 3: Attempt to satisfy missing requirements by replacing characters.
        // We iterate through the string and find the first available index that 
        // does not conflict with the 'protected' last indices of other types.
        for (int i = 0; i < length; i++) {
            if (lastLowerIdx == -1 && i != lastUpperIdx && i != lastDigitIdx) {
                resultChars[i] = 'a';
                lastLowerIdx = i;
            } else if (lastUpperIdx == -1 && i != lastLowerIdx && i != lastDigitIdx) {
                resultChars[i] = 'A';
                lastUpperIdx = i;
            } else if (lastDigitIdx == -1 && i != lastLowerIdx && i != lastUpperIdx) {
                resultChars[i] = '1';
                lastDigitIdx = i;
            }
        }

        return new String(resultChars);
    }
}

