/**
 * A utility to ensure strings contain at least one lowercase letter,
 * one uppercase letter, and one digit.
 */
public class StringComplexityFixer {

    public static void main(String[] args) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String firstLine = reader.readLine();
            if (firstLine == null) return;

            int testCases = Integer.parseInt(firstLine.trim());
            StringBuilder output = new StringBuilder();

            for (int t = 0; t < testCases; t++) {
                String input = reader.readLine();
                if (input != null) {
                    output.append(processString(input.trim())).append("\n");
                }
            }
            System.out.print(output);
        } catch (IOException | NumberFormatException e) {
            System.err.println("Error processing input: " + e.getMessage());
        }
    }

    /**
     * Processes a string to ensure it meets the complexity requirement:
     * contains at least one lowercase, one uppercase, and one digit.
     * 
     * @param input The original string.
     * @return The modified string.
     */
    private static String processString(String input) {
        char[] chars = input.toCharArray();
        StringMetrics metrics = new StringMetrics(chars);

        int typesPresent = metrics.getTypesPresentCount();

        if (typesPresent == 2) {
            // One type is missing. Replace one character of an existing type.
            applySingleSubstitution(chars, metrics);
        } else if (typesPresent == 1) {
            // Two types are missing. Replace first two characters to satisfy requirements.
            applyDoubleSubstitution(chars, metrics);
        }

        return new String(chars);
    }

    private static void applySingleSubstitution(char[] chars, StringMetrics metrics) {
        if (!metrics.hasLower) {
            // Missing lowercase: replace an uppercase or a digit
            if (metrics.upperCount > metrics.digitCount) {
                chars[metrics.lastUpperIdx] = 'a';
            } else {
                chars[metrics.lastDigitIdx] = 'a';
            }
        } else if (!metrics.hasUpper) {
            // Missing uppercase: replace a lowercase or a digit
            if (metrics.lowerCount > metrics.digitCount) {
                chars[metrics.lastLowerIdx] = 'A';
            } else {
                chars[metrics.lastDigitIdx] = 'A';
            }
        } else if (!metrics.hasDigit) {
            // Missing digit: replace a lowercase or an uppercase
            if (metrics.lowerCount > metrics.upperCount) {
                chars[metrics.lastLowerIdx] = '1';
            } else {
                chars[metrics.lastUpperIdx] = '1';
            }
        }
    }

    private static void applyDoubleSubstitution(char[] chars, StringMetrics metrics) {
        // Requirement: must have at least 2 characters to perform this specific logic.
        // This follows the original implementation's logic.
        if (metrics.hasLower) {
            // Only lowercase present: need uppercase and digit
            chars[0] = 'A';
            chars[1] = '1';
        } else if (metrics.hasUpper) {
            // Only uppercase present: need lowercase and digit
            chars[0] = 'a';
            chars[1] = '1';
        } else {
            // Only digits present: need lowercase and uppercase
            chars[0] = 'a';
            chars[1] = 'A';
        }
    }

    /**
     * Helper class to track character statistics of a string.
     */
    private static class StringMetrics {
        int lowerCount = 0, upperCount = 0, digitCount = 0;
        int lastLowerIdx = -1, lastUpperIdx = -1, lastDigitIdx = -1;
        boolean hasLower = false, hasUpper = false, hasDigit = false;

        StringMetrics(char[] chars) {
            for (int i = 0; i < chars.length; i++) {
                char c = chars[i];
                if (Character.isLowerCase(c)) {
                    lowerCount++;
                    hasLower = true;
                    lastLowerIdx = i;
                } else if (Character.isUpperCase(c)) {
                    upperCount++;
                    hasUpper = true;
                    lastUpperIdx = i;
                } else if (Character.isDigit(c)) {
                    digitCount++;
                    hasDigit = true;
                    lastDigitIdx = i;
                }
            }
        }

        int getTypesPresentCount() {
            int count = 0;
            if (hasLower) count++;
            if (hasUpper) count++;
            if (hasDigit) count++;
            return count;
        }
    }
}

