        // Using try-with-resources to ensure the PrintWriter is closed automatically
        try (PrintWriter out = new PrintWriter(System.out)) {
            int testCases = reader.nextInt();
            StringComplexityProcessor processor = new StringComplexityProcessor();

            for (int i = 0; i < testCases; i++) {
                String input = reader.next();
                out.println(processor.process(input));
            }
        } catch (Exception e) {
            System.err.println("An error occurred during execution: " + e.getMessage());
        }
    }

    /**
     * Orchestrates the transformation of the input string based on its complexity rules.
     *
     * @param s The input string.
     * @return The transformed string.
     */
    public String process(String s) {
        StringMetadata meta = analyzeString(s);
        char[] chars = s.toCharArray();

        // Rule 1: If all three types are present, the string is already "complex"
        if (meta.hasLowercase() && meta.hasUppercase() && meta.hasDigit()) {
            return s;
        }

        // Rule 2: Handle cases where lowercase characters are present
        if (meta.hasLowercase()) {
            return handleLowercasePresence(meta, chars);
        }

        // Rule 3: Handle cases where lowercase characters are NOT present
        return handleNoLowercasePresence(meta, chars);
    }

    /**
     * Logic for strings that contain at least one lowercase character.
     */
    private String handleLowercasePresence(StringMetadata meta, char[] chars) {
        if (meta.hasUppercase()) {
            // Case: Contains lowercase and uppercase (but no digits)
            // Note: The 'all three' case is handled by the caller
            chars[meta.lastRepeatIndex()] = '0';
            return new String(chars);
        } 

        if (meta.hasDigit()) {
            // Case: Contains lowercase and digits (but no uppercase)
            chars[meta.lastRepeatIndex()] = 'A';
            return new String(chars);
        }

        // Case: Contains only lowercase
        return applyPrefixReplacement(chars, 'A', '0');
    }

    /**
     * Logic for strings that do not contain any lowercase characters.
     */
    private String handleNoLowercasePresence(StringMetadata meta, char[] chars) {
        if (meta.hasUppercase()) {
            if (meta.hasDigit()) {
                // Case: Contains uppercase and digits
                chars[meta.lastRepeatIndex()] = 'a';
                return new String(chars);
            } else {
                // Case: Contains only uppercase
                return applyPrefixReplacement(chars, '0', 'a');
            }
        }

        // Case: Contains only digits (or is otherwise non-alphabetic)
        return applyPrefixReplacement(chars, 'a', 'A');
    }

    /**
     * Replaces the first two characters of the array with specific characters.
     */
    private String applyPrefixReplacement(char[] chars, char first, char second) {
        if (chars.length >= 2) {
            chars[0] = first;
            chars[1] = second;
        }
        return new String(chars);
    }

    /**
     * Scans the string to determine character composition and the last repeated type index.
     */
    private StringMetadata analyzeString(String s) {
        boolean hasLow = false;
        boolean hasCap = false;
        boolean hasDigit = false;
        int lastRepeatIndex = -1;

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c <= '9') {
                if (hasDigit) lastRepeatIndex = i;
                hasDigit = true;
            } else if (c <= 'Z') {
                if (hasCap) lastRepeatIndex = i;
                hasCap = true;
            } else {
                if (hasLow) lastRepeatIndex = i;
                hasLow = true;
            }
        }
        return new StringMetadata(hasLow, hasCap, hasDigit, lastRepeatIndex);
    }

    /**
     * Data carrier for string analysis results.
     */
    private static class StringMetadata {
        private final boolean lowercase;
        private final boolean uppercase;
        private final boolean digit;
        private final int lastRepeatIndex;

        public StringMetadata(boolean lowercase, boolean uppercase, boolean digit, int lastRepeatIndex) {
            this.lowercase = lowercase;
            this.uppercase = uppercase;
            this.digit = digit;
            this.lastRepeatIndex = lastRepeatIndex;
        }

        public boolean hasLowercase() { return lowercase; }
        public boolean hasUppercase() { return uppercase; }
        public boolean hasDigit() { return digit; }
        public int lastRepeatIndex() { return lastRepeatIndex; }
    }

    /**
     * Fast I/O utility class.
     */
    private static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 256000 * 4);
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A program that ensures a string contains at least one lowercase letter,
 * one uppercase letter, and one other character (digit/symbol) by 
 * replacing existing characters if necessary.
 */
public class StringComplexityBalancer {

    /**
     * Represents the three categories of characters required for a "complex" string.
     */
    private enum CharCategory {
        LOWERCASE, UPPERCASE, OTHER;

        /**
         * Classifies a character into one of the three categories.
         * 
         * @param c The character to classify.
         * @return The identified CharCategory.
         */
        public static CharCategory of(char c) {
            if (c >= 'a' && c <= 'z') {
                return LOWERCASE;
            } else if (c >= 'A' && c <= 'Z') {
                return UPPERCASE;
            } else {
                return OTHER;
            }
        }

        /**
         * Returns a sample character used to satisfy a missing category requirement.
         * 
         * @return A sample character of this category.
         */
        public char getSampleChar() {
            switch (this) {
                case LOWERCASE: return 'a';
                case UPPERCASE: return 'A';
                case OTHER:     return '1';
                default:        return '?';
            }
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        if (!scanner.hasNextInt()) {
            return;
        }

        int testCases = scanner.nextInt();
        scanner.nextLine(); // Consume the remaining newline after nextInt()

        while (testCases-- > 0) {
            if (!scanner.hasNextLine()) {
                break;
            }
            String input = scanner.nextLine();
            out.println(processString(input));
        }

        out.flush();
        out.close();
        scanner.close();
    }

    /**
     * Analyzes the string and ensures it meets the complexity requirements.
     * 
     * @param s The input string to process.
     * @return A string that contains at least one lowercase, one uppercase, and one other character.
     */
    private static String processString(String s) {
        if (s == null || s.isEmpty()) {
            return s;
        }

        // 1. Count the occurrences of each category
        int lowerCount = 0;
        int upperCount = 0;
        int otherCount = 0;

        for (char c : s.toCharArray()) {
            CharCategory category = CharCategory.of(c);
            if (category == CharCategory.LOWERCASE) lowerCount++;
            else if (category == CharCategory.UPPERCASE) upperCount++;
            else otherCount++;
        }

        // 2. Identify which categories are missing
        List<CharCategory> missingCategories = new ArrayList<>();
        if (lowerCount == 0) missingCategories.add(CharCategory.LOWERCASE);
        if (upperCount == 0) missingCategories.add(CharCategory.UPPERCASE);
        if (otherCount == 0) missingCategories.add(CharCategory.OTHER);

        // If all requirements are already met, return the string as-is
        if (missingCategories.isEmpty()) {
            return s;
        }

        // 3. Search for a window of characters that can be safely replaced.
        // A window is valid if replacing its characters won't reduce any 
        // existing category count to zero.
        int windowSize = missingCategories.size();
        int n = s.length();

        for (int i = 0; i <= n - windowSize; i++) {
            if (canReplaceWindow(s, i, windowSize, lowerCount, upperCount, otherCount)) {
                return applyReplacement(s, i, missingCategories);
            }
        }

        return s;
    }

    /**
     * Determines if a contiguous segment of characters can be replaced 
     * without violating the requirement that at least one of each type must exist.
     */
    private static boolean canReplaceWindow(String s, int start, int windowSize, 
                                           int low, int up, int other) {
        int tempLow = low;
        int tempUp = up;
        int tempOther = other;

        for (int j = start; j < start + windowSize; j++) {
            CharCategory category = CharCategory.of(s.charAt(j));
            if (category == CharCategory.LOWERCASE) {
                if (tempLow <= 1) return false;
                tempLow--;
            } else if (category == CharCategory.UPPERCASE) {
                if (tempUp <= 1) return false;
                tempUp--;
            } else {
                if (tempOther <= 1) return false;
                tempOther--;
            }
        }
        return true;
    }

    /**
     * Performs the character replacement in the identified window.
     */
    private static String applyReplacement(String s, int start, List<CharCategory> missing) {
        StringBuilder sb = new StringBuilder(s);
        for (int i = 0; i < missing.size(); i++) {
            char replacement = missing.get(i).getSampleChar();
            sb.setCharAt(start + i, replacement);
        }
        return sb.toString();
    }
}

import java.util.*;
import java.io.*;

/**
 * The Solve class provides a solution to find a string modification
 * that contains at least one uppercase letter, one lowercase letter, and one digit.
 */
public final class Solve {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            String tString = reader.next();
            if (tString != null) {
                int testCases = Integer.parseInt(tString);
                while (testCases-- > 0) {
                    String input = reader.next();
                    if (input != null) {
                        processTestCase(input.toCharArray(), out);
                    }
                }
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Core logic to transform the character array to meet the requirements.
     * 
     * @param chars The input character array.
     * @param out   The PrintWriter for output.
     */
    private static void processTestCase(char[] chars, PrintWriter out) {
        if (isValid(chars)) {
            out.println(new String(chars));
            return;
        }

        int n = chars.length;
        char[] replacements = {'1', 'a', 'A'};

        // Try modifying a single character to see if it satisfies all requirements
        for (int i = 0; i < n; i++) {
            char originalChar = chars[i];
            for (char replacement : replacements) {
                chars[i] = replacement;
                if (isValid(chars)) {
                    out.println(new String(chars));
                    return;
                }
            }
            // Backtrack: restore the original character before trying the next index
            chars[i] = originalChar;
        }

        // Fallback: If no single character modification works, modify the first two 
        // characters based on the type of the third character (assuming length >= 3).
        if (n >= 3) {
            if (Character.isUpperCase(chars[2])) {
                chars[0] = 'a';
                chars[1] = '1';
            } else if (Character.isLowerCase(chars[2])) {
                chars[0] = 'A';
                chars[1] = '1';
            } else {
                chars[0] = 'a';
                chars[1] = 'A';
            }
            out.println(new String(chars));
        }
    }

    /**
     * Checks if the character array contains at least one uppercase, 
     * one lowercase, and one digit.
     */
    private static boolean isValid(char[] chars) {
        boolean hasUpper = false;
        boolean hasLower = false;
        boolean hasDigit = false;

        for (char c : chars) {
            if (Character.isUpperCase(c)) hasUpper = true;
            else if (Character.isLowerCase(c)) hasLower = true;
            else if (Character.isDigit(c)) hasDigit = true;

            if (hasUpper && hasLower && hasDigit) {
                return true;
            }
        }
        return false;
    }

    /**
     * Fast I/O utility class for efficient reading of input.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }
    }
}

import java.util.Scanner;

/**
 * A utility class to ensure strings meet specific character requirements:
 * At least one uppercase letter, one lowercase letter, and one digit.
 */
public class StringRequirementSatisfier {

    public static void main(String[] args) {
        // Use try-with-resources for automatic management of the Scanner resource
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int testCases = scanner.nextInt();
            while (testCases-- > 0) {
                if (scanner.hasNext()) {
                    String input = scanner.next();
                    System.out.println(satisfyRequirements(input));
                }
            }
        }
    }

    /**
     * Processes a string to ensure it contains at least one uppercase,
     * one lowercase, and one digit.
     *
     * @param input The original string.
     * @return The modified string meeting all requirements.
     */
    public static String satisfyRequirements(String input) {
        if (input == null || input.isEmpty()) {
            return input;
        }

        StringBuilder sb = new StringBuilder(input);
        int upperCount = 0;
        int lowerCount = 0;
        int digitCount = 0;

        // Step 1: Analyze current character distribution
        for (int i = 0; i < sb.length(); i++) {
            char c = sb.charAt(i);
            if (Character.isUpperCase(c)) {
                upperCount++;
            } else if (Character.isLowerCase(c)) {
                lowerCount++;
            } else if (Character.isDigit(c)) {
                digitCount++;
            }
        }

        boolean hasUpper = upperCount > 0;
        boolean hasLower = lowerCount > 0;
        boolean hasDigit = digitCount > 0;

        // Step 2: Return if all requirements are already met
        if (hasUpper && hasLower && hasDigit) {
            return sb.toString();
        }

        // Step 3: Handle cases where two requirements are missing
        if (!hasUpper && !hasLower) {
            return applyDoubleFix(sb, 'a', 'A');
        }
        if (!hasUpper && !hasDigit) {
            return applyDoubleFix(sb, '1', 'A');
        }
        if (!hasLower && !hasDigit) {
            return applyDoubleFix(sb, 'a', '1');
        }

        // Step 4: Handle case where exactly one requirement is missing
        char missingTypeChar = getMissingTypeChar(hasUpper, hasLower, hasDigit);
        return applySingleFix(sb, upperCount, lowerCount, digitCount, missingTypeChar);
    }

    /**
     * Replaces the first two characters to satisfy two missing requirements.
     */
    private static String applyDoubleFix(StringBuilder sb, char first, char second) {
        sb.setCharAt(0, first);
        if (sb.length() > 1) {
            sb.setCharAt(1, second);
        }
        return sb.toString();
    }

    /**
     * Determines the character needed to satisfy the single missing requirement.
     */
    private static char getMissingTypeChar(boolean hasUpper, boolean hasLower, boolean hasDigit) {
        if (!hasUpper) return 'A';
        if (!hasLower) return 'a';
        return '1'; // Missing digit
    }

    /**
     * Replaces a single character to satisfy the missing requirement.
     * It attempts to find a character that is not the sole representative 
     * of an existing required category to minimize impact.
     */
    private static String applySingleFix(StringBuilder sb, int u, int l, int d, char replacement) {
        int targetIndex = 0;
        boolean foundSafeIndex = false;

        for (int i = 0; i < sb.length(); i++) {
            char c = sb.charAt(i);
            boolean isCritical = false;

            // A character is "critical" if it is the only one of its type currently present
            if (Character.isUpperCase(c) && u == 1) isCritical = true;
            else if (Character.isLowerCase(c) && l == 1) isCritical = true;
            else if (Character.isDigit(c) && d == 1) isCritical = true;

            if (!isCritical) {
                targetIndex = i;
                foundSafeIndex = true;
                break;
            }
        }

        // If no non-critical character exists, default to index 0
        if (!foundSafeIndex) {
            targetIndex = 0;
        }

        sb.setCharAt(targetIndex, replacement);
        return sb.toString();
    }
}

import java.util.Scanner;

/**
 * A utility class to ensure strings contain at least one digit, 
 * one uppercase letter, and one lowercase letter.
 */
public class StringCharacterFixer {

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int testCaseCount = scanner.nextInt();
            for (int i = 0; i < testCaseCount; i++) {
                if (scanner.hasNext()) {
                    String input = scanner.next();
                    System.out.println(processString(input));
                }
            }
        }
    }

    /**
     * Processes the input string to ensure it satisfies the requirement of 
     * having at least one digit, one uppercase, and one lowercase character.
     *
     * @param input The original string.
     * @return The modified string.
     */
    private static String processString(String input) {
        char[] chars = input.toCharArray();
        CharacterStats stats = new CharacterStats(chars);

        // If the string already contains all three types, return as is.
        if (stats.hasAllTypes()) {
            return input;
        }

        // Case 1: Two types are missing (only one type of character exists in the string)
        if (stats.isOnlyLowercase()) {
            applyReplacement(chars, 0, '1');
            applyReplacement(chars, 1, 'A');
        } else if (stats.isOnlyUppercase()) {
            applyReplacement(chars, 0, '1');
            applyReplacement(chars, 1, 'a');
        } else if (stats.isOnlyDigits()) {
            applyReplacement(chars, 0, 'A');
            applyReplacement(chars, 1, 'a');
        } 
        // Case 2: Exactly one type is missing
        else if (stats.isMissingAnyType()) {
            replaceRedundantCharacter(chars, stats);
        }

        return new String(chars);
    }

    /**
     * Finds a redundant character (one that appears more than once) 
     * and replaces it with a character of the missing type.
     */
    private static void replaceRedundantCharacter(char[] chars, CharacterStats stats) {
        for (int i = 0; i < chars.length; i++) {
            char currentChar = chars[i];
            if (isRedundant(currentChar, stats)) {
                if (stats.digitCount == 0) {
                    chars[i] = '1';
                } else if (stats.lowerCount == 0) {
                    chars[i] = 'a';
                } else if (stats.upperCount == 0) {
                    chars[i] = 'A';
                }
                break;
            }
        }
    }

    private static boolean isRedundant(char c, CharacterStats stats) {
        if (Character.isDigit(c)) return stats.digitCount > 1;
        if (Character.isUpperCase(c)) return stats.upperCount > 1;
        if (Character.isLowerCase(c)) return stats.lowerCount > 1;
        return false;
    }

    private static void applyReplacement(char[] chars, int index, char replacement) {
        if (index < chars.length) {
            chars[index] = replacement;
        }
    }

    /**
     * Helper class to track character type counts within a character array.
     */
    private static class CharacterStats {
        final int digitCount;
        final int upperCount;
        final int lowerCount;

        CharacterStats(char[] chars) {
            int digits = 0;
            int uppers = 0;
            int lowers = 0;

            for (char c : chars) {
                if (Character.isDigit(c)) {
                    digits++;
                } else if (Character.isUpperCase(c)) {
                    uppers++;
                } else if (Character.isLowerCase(c)) {
                    lowers++;
                }
            }
            this.digitCount = digits;
            this.upperCount = uppers;
            this.lowerCount = lowers;
        }

        boolean hasAllTypes() {
            return digitCount > 0 && upperCount > 0 && lowerCount > 0;
        }

        boolean isMissingAnyType() {
            return digitCount == 0 || upperCount == 0 || lowerCount == 0;
        }

        boolean isOnlyLowercase() {
            return digitCount == 0 && upperCount == 0;
        }

        boolean isOnlyUppercase() {
            return digitCount == 0 && lowerCount == 0;
        }

        boolean isOnlyDigits() {
            return upperCount == 0 && lowerCount == 0;
        }
    }
}

import java.util.Scanner;

/**
 * A refactored solution to find the minimum modification required to satisfy
 * specific character type requirements in a string.
 */
public class StringRequirementSolver {

    // Constants for replacement options to improve maintainability
    private static final char[] SINGLE_REPLACEMENT_OPTIONS = {'1', 'a', 'A'};
    private static final char[][] DOUBLE_REPLACEMENT_OPTIONS = {
            {'1', 'a'},
            {'1', 'A'},
            {'a', 'A'}
    };

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int testCases = scanner.nextInt();
        scanner.nextLine(); // Consume the newline character

        for (int t = 0; t < testCases; t++) {
            if (scanner.hasNextLine()) {
                String input = scanner.nextLine();
                System.out.println(findBestModifiedString(input));
            }
        }
        scanner.close();
    }

    /**
     * Determines the best version of the input string that satisfies the 
     * requirement of having at least one lowercase letter, one uppercase 
     * letter, and one other character (digit/symbol).
     *
     * @param input The original input string.
     * @return The modified string that satisfies the condition with minimum "cost".
     */
    private static String findBestModifiedString(String input) {
        char[] currentChars = input.toCharArray();

        // If the requirement is already met, return the original string.
        if (containsRequiredCharacters(currentChars)) {
            return input;
        }

        String bestString = input;
        int minCost = Integer.MAX_VALUE;

        // Attempt single-character replacements
        for (int i = 0; i < currentChars.length; i++) {
            char originalChar = currentChars[i];
            for (char replacement : SINGLE_REPLACEMENT_OPTIONS) {
                currentChars[i] = replacement;
                if (containsRequiredCharacters(currentChars)) {
                    int cost = calculateModificationCost(input.toCharArray(), currentChars);
                    if (cost < minCost) {
                        minCost = cost;
                        bestString = new String(currentChars);
                    }
                }
            }
            currentChars[i] = originalChar; // Backtrack
        }

        // Attempt double-character (adjacent) replacements
        for (int i = 0; i < currentChars.length - 1; i++) {
            char originalChar1 = currentChars[i];
            char originalChar2 = currentChars[i + 1];

            for (char[] replacementPair : DOUBLE_REPLACEMENT_OPTIONS) {
                currentChars[i] = replacementPair[0];
                currentChars[i + 1] = replacementPair[1];

                if (containsRequiredCharacters(currentChars)) {
                    int cost = calculateModificationCost(input.toCharArray(), currentChars);
                    if (cost < minCost) {
                        minCost = cost;
                        bestString = new String(currentChars);
                    }
                }
            }
            // Backtrack
            currentChars[i] = originalChar1;
            currentChars[i + 1] = originalChar2;
        }

        return bestString;
    }

    /**
     * Checks if the character array contains at least one lowercase,
     * one uppercase, and one non-letter character.
     */
    private static boolean containsRequiredCharacters(char[] chars) {
        boolean hasLower = false;
        boolean hasUpper = false;
        boolean hasOther = false;

        for (char c : chars) {
            if (c >= 'a' && c <= 'z') {
                hasLower = true;
            } else if (c >= 'A' && c <= 'Z') {
                hasUpper = true;
            } else {
                hasOther = true;
            }

            if (hasLower && hasUpper && hasOther) {
                return true;
            }
        }
        return false;
    }

    /**
     * Calculates the cost of modification based on the difference between 
     * the original and modified arrays.
     * 
     * To maintain compatibility with the original algorithm's logic, 
     * single changes result in a negative cost, effectively prioritizing 
     * them over double changes.
     */
    private static int calculateModificationCost(char[] original, char[] modified) {
        int firstDiffIndex = -1;
        int lastDiffIndex = -1;
        int diffCount = 0;

        for (int i = 0; i < original.length; i++) {
            if (original[i] != modified[i]) {
                if (firstDiffIndex == -1) {
                    firstDiffIndex = i;
                }
                lastDiffIndex = i;
                diffCount++;
            }
        }

        if (diffCount == 0) {
            return 0;
        }

        // Replicates the original: pos[1] - pos[0] logic.
        // If only 1 diff, pos[1] remains 0, resulting in (0 - firstDiffIndex).
        if (diffCount == 1) {
            return -firstDiffIndex;
        }

        return lastDiffIndex - firstDiffIndex;
    }
}

import java.util.Scanner;

/**
 * A program that ensures strings contain at least one uppercase letter, 
 * one lowercase letter, and one digit.
 */
public class Main {

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int testCases = scanner.nextInt();
            scanner.nextLine(); // Consume the newline character after nextInt()

            StringRequirementSatisfier satisfier = new StringRequirementSatisfier();

            for (int i = 0; i < testCases; i++) {
                if (scanner.hasNextLine()) {
                    String input = scanner.nextLine();
                    System.out.println(satisfier.ensureRequirements(input));
                }
            }
        }
    }

    /**
     * Service class responsible for validating and modifying strings 
     * to meet specific character requirements.
     */
    static class StringRequirementSatisfier {

        private static final char DEFAULT_UPPER = 'A';
        private static final char DEFAULT_LOWER = 'a';
        private static final char DEFAULT_DIGIT = '1';

        /**
         * Ensures the input string has at least one uppercase letter, 
         * one lowercase letter, and one digit.
         *
         * @param input The string to evaluate.
         * @return A modified string meeting all requirements.
         */
        public String ensureRequirements(String input) {
            if (input == null || input.isEmpty()) {
                return input;
            }

            char[] chars = input.toCharArray();
            int upperIdx = -1;
            int lowerIdx = -1;
            int digitIdx = -1;

            // Step 1: Identify the first occurrence of each required type
            for (int i = 0; i < chars.length; i++) {
                char c = chars[i];
                if (Character.isUpperCase(c) && upperIdx == -1) {
                    upperIdx = i;
                } else if (Character.isLowerCase(c) && lowerIdx == -1) {
                    lowerIdx = i;
                } else if (Character.isDigit(c) && digitIdx == -1) {
                    digitIdx = i;
                }
            }

            // Step 2: If a requirement is missing, find the first available index to replace.
            // We update the indices immediately to ensure subsequent checks don't 
            // overwrite the newly added characters.

            // Ensure Uppercase
            if (upperIdx == -1) {
                int targetIdx = findFirstAvailableIndex(upperIdx, lowerIdx, digitIdx, chars.length);
                if (targetIdx != -1) {
                    chars[targetIdx] = DEFAULT_UPPER;
                    upperIdx = targetIdx;
                }
            }

            // Ensure Lowercase
            if (lowerIdx == -1) {
                int targetIdx = findFirstAvailableIndex(upperIdx, lowerIdx, digitIdx, chars.length);
                if (targetIdx != -1) {
                    chars[targetIdx] = DEFAULT_LOWER;
                    lowerIdx = targetIdx;
                }
            }

            // Ensure Digit
            if (digitIdx == -1) {
                int targetIdx = findFirstAvailableIndex(upperIdx, lowerIdx, digitIdx, chars.length);
                if (targetIdx != -1) {
                    chars[targetIdx] = DEFAULT_DIGIT;
                    digitIdx = targetIdx;
                }
            }

            return new String(chars);
        }

        /**
         * Finds the first index in the array that is not currently serving as 
         * the representative for an existing required character type.
         *
         * @param u Index of an existing uppercase char (-1 if none)
         * @param l Index of an existing lowercase char (-1 if none)
         * @param d Index of an existing digit (-1 if none)
         * @param length Length of the character array
         * @return The first available index, or -1 if none found.
         */
        private int findFirstAvailableIndex(int u, int l, int d, int length) {
            for (int i = 0; i < length; i++) {
                if (i != u && i != l && i != d) {
                    return i;
                }
            }
            return -1;
        }
    }
}

