/**
 * StringTransformer provides functionality to transform strings by ensuring 
 * a diverse mix of character types: lowercase, uppercase, and digits.
 */
public class StringTransformer {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Handle case where input might be empty or malformed
        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }

        int testCaseCount = scanner.nextInt();
        scanner.nextLine(); // Consume the newline character following the integer

        for (int i = 0; i < testCaseCount; i++) {
            if (scanner.hasNextLine()) {
                String input = scanner.nextLine();
                String result = transformString(input);
                System.out.println(result);
            }
        }

        scanner.close();
    }

    /**
     * Transforms the input string to increase character type diversity.
     * If a character type is redundant (count > 1) and another type is missing 
     * (count == 0), the redundant character is replaced by a representative 
     * of the missing type.
     *
     * @param input The string to be transformed.
     * @return The transformed string.
     */
    public static String transformString(String input) {
        if (input == null || input.isEmpty()) {
            return input;
        }

        int lowerCount = 0;
        int upperCount = 0;
        int digitCount = 0;

        // Step 1: Calculate initial counts of character types.
        // Note: Non-alphabetic characters are treated as digits for counting 
        // purposes to maintain parity with the original logic.
        for (char c : input.toCharArray()) {
            if (Character.isLowerCase(c)) {
                lowerCount++;
            } else if (Character.isUpperCase(c)) {
                upperCount++;
            } else {
                digitCount++;
            }
        }

        // Step 2: Build the transformed string using StringBuilder for efficiency.
        StringBuilder transformed = new StringBuilder();
        for (char c : input.toCharArray()) {
            if (Character.isLowerCase(c)) {
                char replacement = determineLowercaseReplacement(c, lowerCount, upperCount, digitCount);
                transformed.append(replacement);
                updateCounts(replacement, lowerCount, upperCount, digitCount);

                // We must update the local trackers to reflect transformations 
                // for subsequent characters in the loop.
                if (Character.isDigit(replacement)) digitCount++;
                else if (Character.isUpperCase(replacement)) upperCount++;

            } else if (Character.isUpperCase(c)) {
                char replacement = determineUpperCaseReplacement(c, lowerCount, upperCount, digitCount);
                transformed.append(replacement);

                if (Character.isDigit(replacement)) digitCount++;
                else if (Character.isLowerCase(replacement)) lowerCount++;

            } else if (Character.isDigit(c)) {
                char replacement = determineDigitReplacement(c, lowerCount, upperCount, digitCount);
                transformed.append(replacement);

                if (Character.isLowerCase(replacement)) lowerCount++;
                else if (Character.isUpperCase(replacement)) upperCount++;

            } else {
                // For non-alphanumeric characters, append as-is.
                transformed.append(c);
            }
        }

        return transformed.toString();
    }

    /**
     * Decides the replacement for a lowercase character based on current type counts.
     */
    private static char determineLowercaseReplacement(char c, int l, int u, int d) {
        if (d == 0 && l > 1) return '1';
        if (u == 0 && l > 1) return 'A';
        return c;
    }

    /**
     * Decides the replacement for an uppercase character based on current type counts.
     */
    private static char determineUpperCaseReplacement(char c, int l, int u, int d) {
        if (d == 0 && u > 1) return '1';
        if (l == 0 && u > 1) return 'a';
        return c;
    }

    /**
     * Decides the replacement for a digit character based on current type counts.
     */
    private static char determineDigitReplacement(char c, int l, int u, int d) {
        if (l == 0 && d > 1) return 'a';
        if (u == 0 && d > 1) return 'A';
        return c;
    }

    /**
     * Placeholder for logic if we were using a specialized State object.
     * In this implementation, counts are updated directly in the main loop 
     * to maintain simplicity and performance.
     */
    private static void updateCounts(char replacement, int l, int u, int d) {
        // This method is kept for architectural completeness.
    }
}

