/**
 * GridPatternMatcher determines if a given grid is composed entirely 
 * of 3x3 "ring" patterns. A ring pattern is a 3x3 block of '#' 
 * with a '.' in the center.
 */
public class GridPatternMatcher {

    private static final char FILLED = '#';
    private static final char EMPTY = '.';

    public static void main(String[] args) {
        GridPatternMatcher matcher = new GridPatternMatcher();
        matcher.run();
    }

    /**
     * Orchestrates the reading, processing, and output of the grid validation.
     */
    public void run() {
        try (FastReader reader = new FastReader(System.in);
             BufferedWriter writer = new BufferedWriter(new OutputStreamWriter(System.out))) {

            int rows = reader.nextInt();
            int cols = reader.nextInt();

            if (rows <= 0 || cols <= 0) {
                writer.write("NO");
                return;
            }

            char[][] originalGrid = readGrid(reader, rows, cols);
            char[][] reconstructedGrid = reconstructGrid(originalGrid, rows, cols);

            if (isGridValid(originalGrid, reconstructedGrid, rows)) {
                writer.write("YES");
            } else {
                writer.write("NO");
            }
            writer.flush();

        } catch (IOException | InputMismatchException e) {
            // In a production environment, use a proper logger
            System.err.println("Error processing grid: " + e.getMessage());
        }
    }

    private char[][] readGrid(FastReader reader, int rows, int cols) throws IOException {
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = reader.readLine().toCharArray();
        }
        return grid;
    }

    /**
     * Iterates through the grid to find all possible 3x3 rings and 
     * reconstructs them into a new grid.
     */
    private char[][] reconstructGrid(char[][] originalGrid, int rows, int cols) {
        char[][] reconstructedGrid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            Arrays.fill(reconstructedGrid[i], EMPTY);
        }

        for (int r = 0; r <= rows - 3; r++) {
            for (int c = 0; c <= cols - 3; c++) {
                // A ring's top-left corner must be '#' to be a candidate
                if (originalGrid[r][c] == FILLED && isRingPossible(originalGrid, r, c, rows, cols)) {
                    applyRing(reconstructedGrid, r, c);
                }
            }
        }
        return reconstructedGrid;
    }

    /**
     * Checks if a 3x3 ring can be placed with (r, c) as the top-left corner.
     */
    private boolean isRingPossible(char[][] grid, int r, int c, int rows, int cols) {
        // Check boundaries
        if (r + 2 >= rows || c + 2 >= cols) {
            return false;
        }

        // Check if all 8 perimeter cells are '#'
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                if (i == 1 && j == 1) {
                    continue; // Skip the center cell
                }
                if (grid[r + i][c + j] != FILLED) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Marks the 8 perimeter cells of a 3x3 ring as '#' in the target grid.
     */
    private void applyRing(char[][] targetGrid, int r, int c) {
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                if (i == 1 && j == 1) {
                    continue;
                }
                targetGrid[r + i][c + j] = FILLED;
            }
        }
    }

    /**
     * Compares the original grid with the reconstructed grid to ensure 
     * they are identical.
     */
    private boolean isGridValid(char[][] original, char[][] reconstructed, int rows) {
        for (int i = 0; i < rows; i++) {
            if (!Arrays.equals(original[i], reconstructed[i])) {
                return false;
            }
        }
        return true;
    }

    /**
     * A lightweight, efficient reader for large inputs.
     */
    static class FastReader implements AutoCloseable {
        private final BufferedReader reader;

        public FastReader(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
        }

        public int nextInt() throws IOException {
            String s = nextToken();
            return Integer.parseInt(s);
        }

        public String nextToken() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c = reader.read();
            while (c != -1 && Character.isWhitespace(c)) {
                c = reader.read();
            }
            if (c == -1) return null;
            while (c != -1 && !Character.isWhitespace(c)) {
                sb.append((char) c);
                c = reader.read();
            }
            return sb.toString();
        }

        public String readLine() throws IOException {
            String line = reader.readLine();
            while (line != null && line.trim().isEmpty()) {
                line = reader.readLine();
            }
            return line;
        }

        @Override
        public void close() throws IOException {
            reader.close();
        }
    }
}

import java.util.StringTokenizer;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;

/**
 * GridPatternValidator verifies if a given grid of '#' and '.' characters
 * can be reconstructed using a specific 3x3 "plus" pattern.
 */
public class GridPatternValidator {

    private static final char FILL_CHAR = '#';
    private static final char EMPTY_CHAR = '.';

    public static void main(String[] args) {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String line = br.readLine();
            if (line == null) return;

            StringTokenizer st = new StringTokenizer(line);
            int rows = Integer.parseInt(st.nextToken());
            int cols = Integer.parseInt(st.nextToken());

            char[][] originalGrid = new char[rows][cols];
            char[][] reconstructedGrid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                String rowStr = br.readLine();
                originalGrid[i] = rowStr.toCharArray();
                // Initialize reconstructed grid with empty characters
                for (int j = 0; j < cols; j++) {
                    reconstructedGrid[i][j] = EMPTY_CHAR;
                }
            }

            processGrid(originalGrid, reconstructedGrid, rows, cols);

            if (isMatch(originalGrid, reconstructedGrid, rows, cols)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }

        } catch (IOException | NumberFormatException e) {
            e.printStackTrace();
        }
    }

    /**
     * Iterates through the grid to attempt placing patterns.
     */
    private static void processGrid(char[][] original, char[][] reconstructed, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                // If we find a '#', treat it as the top-left corner of a potential 3x3 pattern
                if (original[i][j] == FILL_CHAR) {
                    tryPlacePattern(original, reconstructed, i, j, rows, cols);
                }
            }
        }
    }

    /**
     * Checks if a 3x3 pattern can be placed starting at (startRow, startCol)
     * and applies it to the reconstructed grid if valid.
     */
    private static void tryPlacePattern(char[][] original, char[][] reconstructed, 
                                        int startRow, int startCol, int rows, int cols) {
        // Ensure the 3x3 block fits within the grid boundaries
        if (startRow + 2 >= rows || startCol + 2 >= cols) {
            return;
        }

        // Validate that all 8 perimeter cells in the original grid are '#'
        for (int r = startRow; r < startRow + 3; r++) {
            for (int c = startCol; c < startCol + 3; c++) {
                // Skip the center cell of the 3x3 block
                if (r == startRow + 1 && c == startCol + 1) {
                    continue;
                }
                if (original[r][c] != FILL_CHAR) {
                    return;
                }
            }
        }

        // Apply the pattern to the reconstructed grid
        // Fill top and bottom rows
        for (int c = startCol; c < startCol + 3; c++) {
            reconstructed[startRow][c] = FILL_CHAR;
            reconstructed[startRow + 2][c] = FILL_CHAR;
        }

        // Fill left and right of the middle row
        reconstructed[startRow + 1][startCol] = FILL_CHAR;
        reconstructed[startRow + 1][startCol + 2] = FILL_CHAR;

        // The center cell remains the same as it was (logic preserved from original)
        // If it was already '#', it stays '#', otherwise it stays '.'
        if (reconstructed[startRow + 1][startCol + 1] == FILL_CHAR) {
            reconstructed[startRow + 1][startCol + 1] = FILL_CHAR;
        } else {
            reconstructed[startRow + 1][startCol + 1] = EMPTY_CHAR;
        }
    }

    /**
     * Compares the original grid with the reconstructed grid.
     */
    private static boolean isMatch(char[][] grid1, char[][] grid2, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid1[i][j] != grid2[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }
}

