/**
 * A refactored solution for determining if every '#' cell in a grid 
 * is part of at least one 3x3 ring of '#' cells.
 */
public class Main {

    public static void main(String[] args) {
        // Using try-with-resources to ensure the Output stream is closed and flushed automatically
        try (FastReader reader = new FastReader(System.in);
             PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)))) {

            RingCoverageSolver solver = new RingCoverageSolver();
            solver.solve(reader, writer);

        } catch (IOException e) {
            System.err.println("Critical I/O error: " + e.getMessage());
        }
    }
}

/**
 * Handles the core logic of the grid problem.
 */
class RingCoverageSolver {

    /**
     * Executes the solving process: reads dimensions, processes the grid, 
     * and outputs the result.
     */
    public void solve(FastReader reader, PrintWriter writer) throws IOException {
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        // Edge case: If dimensions are too small to host a 3x3 ring
        if (rows < 3 || cols < 3) {
            char[][] grid = reader.readGrid(rows, cols);
            if (containsAnyHash(grid)) {
                writer.println("NO");
            } else {
                writer.println("YES");
            }
            return;
        }

        char[][] grid = reader.readGrid(rows, cols);
        boolean[][] isCovered = new boolean[rows][cols];

        // Step 1: Iterate through all possible 3x3 top-left corners.
        // If a valid ring is found, mark all its perimeter cells as "covered".
        for (int r = 0; r <= rows - 3; r++) {
            for (int c = 0; c <= cols - 3; c++) {
                if (isValidRing(grid, r, c)) {
                    markRingCells(isCovered, r, c);
                }
            }
        }

        // Step 2: Verify if any '#' cell remains uncovered.
        boolean allHashesCovered = true;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '#' && !isCovered[r][c]) {
                    allHashesCovered = false;
                    break;
                }
            }
            if (!allHashesCovered) break;
        }

        writer.println(allHashesCovered ? "YES" : "NO");
    }

    private boolean containsAnyHash(char[][] grid) {
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '#') return true;
            }
        }
        return false;
    }

    /**
     * Checks if the 3x3 area starting at (startR, startC) forms a valid ring.
     * A valid ring consists of '#' in all 8 perimeter positions.
     */
    private boolean isValidRing(char[][] grid, int startR, int startC) {
        for (int i = startR; i < startR + 3; i++) {
            for (int j = startC; j < startC + 3; j++) {
                // Skip the center cell of the 3x3 block
                if (i == startR + 1 && j == startC + 1) {
                    continue;
                }
                if (grid[i][j] != '#') {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Marks the 8 perimeter cells of a 3x3 block as covered.
     */
    private void markRingCells(boolean[][] isCovered, int startR, int startC) {
        for (int i = startR; i < startR + 3; i++) {
            for (int j = startC; j < startC + 3; j++) {
                if (i == startR + 1 && j == startC + 1) {
                    continue;
                }
                isCovered[i][j] = true;
            }
        }
    }
}

/**
 * High-performance input reader for large datasets.
 */
class FastReader {
    private final InputStream in;
    private final byte[] buffer = new byte[1024 * 16];
    private int pointer = 0;
    private int bufferLength = 0;

    public FastReader(InputStream in) {
        this.in = in;
    }

    private boolean fillBuffer() throws IOException {
        bufferLength = in.read(buffer);
        pointer = 0;
        return bufferLength > 0;
    }

    private byte readByte() throws IOException {
        if (pointer >= bufferLength) {
            if (!fillBuffer()) return -1;
        }
        return buffer[pointer++];
    }

    /**
     * Reads the next integer.
     */
    public int nextInt() throws IOException {
        byte b = readByte();
        while (b != -1 && b <= 32) b = readByte();
        if (b == -1) return 0;

        boolean negative = (b == '-');
        if (negative) b = readByte();

        int result = 0;
        while (b >= '0' && b <= '9') {
            result = result * 10 + (b - '0');
            b = readByte();
        }
        return negative ? -result : result;
    }

    /**
     * Reads the next non-whitespace character.
     */
    public char nextChar() throws IOException {
        byte b = readByte();
        while (b != -1 && b <= 32) b = readByte();
        return (char) b;
    }

    /**
     * Reads a 2D grid of characters.
     */
    public char[][] readGrid(int rows, int cols) throws IOException {
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                grid[i][j] = nextChar();
            }
        }
        return grid;
    }
}

import java.io.BufferedReader;
