import java.util.Arrays;
import java.util.StringTokenizer;

/**
 * Validates whether a grid of characters can be perfectly reconstructed
 * by tiling a specific 3x3 ring pattern.
 */
public class GridPatternMatcher {

    private static final char FILLED = '#';
    private static final char EMPTY = '.';

    // Defines the relative coordinates of the 8 cells forming a 3x3 ring (center missing)
    private static final int[] OFFSET_X = {0, 1, 2, 2, 2, 1, 0, 0};
    private static final int[] OFFSET_Y = {0, 0, 0, 1, 2, 2, 2, 1};

    public static void main(String[] args) {
        FastReader reader = new FastReader();

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            GridPatternMatcher matcher = new GridPatternMatcher();
            if (matcher.canReconstructGrid(grid)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        } catch (Exception e) {
            // In a real-world scenario, use a logger
            System.err.println("Error processing grid: " + e.getMessage());
        }
    }

    /**
     * Attempts to reconstruct the grid using the ring pattern.
     * Returns true if the reconstructed grid matches the input grid perfectly.
     * 
     * @param grid The input grid to validate.
     * @return true if the grid is a valid tiling of the pattern.
     */
    public boolean canReconstructGrid(char[][] grid) {
        int rows = grid.length;
        if (rows == 0) return true;
        int cols = grid[0].length;

        char[][] reconstructedGrid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            Arrays.fill(reconstructedGrid[i], EMPTY);
        }

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                // If we find a filled cell, it must be the top-left corner of a valid ring pattern
                if (grid[i][j] == FILLED) {
                    if (canPlacePattern(grid, i, j)) {
                        applyPattern(reconstructedGrid, i, j);
                    }
                }
            }
        }

        return areGridsEqual(grid, reconstructedGrid);
    }

    /**
     * Checks if a full 3x3 ring pattern can be placed starting at (startR, startC).
     */
    private boolean canPlacePattern(char[][] grid, int startR, int startC) {
        int rows = grid.length;
        int cols = grid[0].length;

        // Check if the 3x3 area is within bounds
        if (startR + 2 >= rows || startC + 2 >= cols) {
            return false;
        }

        // Check if all cells in the pattern are FILLED in the original grid
        for (int k = 0; k < OFFSET_X.length; k++) {
            if (grid[startR + OFFSET_X[k]][startC + OFFSET_Y[k]] != FILLED) {
                return false;
            }
        }
        return true;
    }

    /**
     * Marks the ring pattern cells in the reconstruction grid.
     */
    private void applyPattern(char[][] reconstructedGrid, int startR, int startC) {
        for (int k = 0; k < OFFSET_X.length; k++) {
            reconstructedGrid[startR + OFFSET_X[k]][startC + OFFSET_Y[k]] = FILLED;
        }
    }

    /**
     * Compares two 2D character arrays for equality.
     */
    private boolean areGridsEqual(char[][] grid1, char[][] grid2) {
        for (int i = 0; i < grid1.length; i++) {
            if (!Arrays.equals(grid1[i], grid2[i])) {
                return false;
            }
        }
        return true;
    }

    /**
     * Efficient reader for large inputs.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader() {
            reader = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A utility to validate if a grid of characters follows a specific 
 * pattern where every '#' must be a neighbor of a cell that is 
 * entirely surrounded by '#' characters.
 */
public class GridPatternValidator {

    // Offsets for the 8 possible directions (horizontal, vertical, and diagonal)
    private static final int[] ROW_OFFSETS = {1, -1, 0, 0, -1, 1, -1, 1};
    private static final int[] COL_OFFSETS = {0, 0, 1, -1, 1, -1, -1, 1};

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            String nStr = reader.next();
            String mStr = reader.next();

            if (nStr != null && mStr != null) {
                int rows = Integer.parseInt(nStr);
                int cols = Integer.parseInt(mStr);

                char[][] originalGrid = new char[rows][cols];
                for (int i = 0; i < rows; i++) {
                    String line = reader.next();
                    if (line != null) {
                        originalGrid[i] = line.toCharArray();
                    }
                }

                boolean isStable = isPatternStable(originalGrid);
                writer.println(isStable ? "YES" : "NO");
            }
        } catch (Exception e) {
            // In a production environment, use a logger.
            // For this context, we handle basic parsing errors gracefully.
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Determines if the provided grid is "stable" according to the rule:
     * A '#' exists in the reconstructed grid only if it is a neighbor 
     * of a cell whose 8 neighbors are all '#'.
     *
     * @param grid The input character grid.
     * @return true if the reconstructed grid matches the original grid.
     */
    public static boolean isPatternStable(char[][] grid) {
        int rows = grid.length;
        if (rows == 0) return true;
        int cols = grid[0].length;

        // Create a reconstructed grid initialized with '.'
        char[][] reconstructedGrid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            Arrays.fill(reconstructedGrid[i], '.');
        }

        // Step 1: Identify "centers" and mark their neighbors
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (isSurroundedByHash(grid, i, j)) {
                    markNeighbors(reconstructedGrid, i, j);
                }
            }
        }

        // Step 2: Compare the reconstructed grid with the original
        return compareGrids(grid, reconstructedGrid);
    }

    /**
     * Checks if all 8 neighbors of a specific cell are '#' characters.
     */
    private static boolean isSurroundedByHash(char[][] grid, int r, int c) {
        int rows = grid.length;
        int cols = grid[0].length;

        for (int k = 0; k < 8; k++) {
            int nr = r + ROW_OFFSETS[k];
            int nc = c + COL_OFFSETS[k];

            if (!isValidHash(grid, nr, nc, rows, cols)) {
                return false;
            }
        }
        return true;
    }

    /**
     * Helper to check if a coordinate is within bounds and contains a '#'.
     */
    private static boolean isValidHash(char[][] grid, int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] == '#';
    }

    /**
     * Marks the 8 neighbors of a cell as '#' in the reconstruction grid.
     */
    private static void markNeighbors(char[][] reconstructed, int r, int c) {
        for (int k = 0; k < 8; k++) {
            int nr = r + ROW_OFFSETS[k];
            int nc = c + COL_OFFSETS[k];
            // Boundary check is technically redundant here because isSurroundedByHash 
            // already verified that these 8 neighbors are within bounds.
            reconstructed[nr][nc] = '#';
        }
    }

    /**
     * Performs a deep comparison of two character grids.
     */
    private static boolean compareGrids(char[][] grid1, char[][] grid2) {
        int rows = grid1.length;
        int cols = grid1[0].length;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid1[i][j] != grid2[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Fast I/O reader for efficient handling of large datasets.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            return next != null ? Integer.parseInt(next) : 0;
        }
    }
}

import java.util.Scanner;

/**
 * GridObstacleClearer
 * 
 * This program processes a 2D grid of characters. It attempts to clear 
 * all obstacles ('#') by applying a 3x3 clearing operation. A 3x3 area 
 * can be cleared if it lies entirely within the grid boundaries.
 */
public class GridObstacleClearer {

    private static final char OBSTACLE = '#';
    private static final char EMPTY = '-';
    private static final int SQUARE_SIZE = 3;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        char[][] grid = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            if (scanner.hasNext()) {
                grid[i] = scanner.next().toCharArray();
            }
        }
        scanner.close();

        boolean success = solve(grid, rows, cols);
        System.out.println(success ? "YES" : "NO");
    }

    /**
     * Orchestrates the process of clearing obstacles and checking the result.
     *
     * @param grid The 2D grid to process.
     * @param rows Number of rows in the grid.
     * @param cols Number of columns in the grid.
     * @return true if all obstacles were cleared, false otherwise.
     */
    private static boolean solve(char[][] grid, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == OBSTACLE) {
                    // If an obstacle is found, try to find a valid 3x3 square that covers it.
                    tryToClearObstacle(grid, r, c, rows, cols);
                }
            }
        }

        return areAllObstaclesCleared(grid, rows, cols);
    }

    /**
     * Searches for any valid 3x3 square that includes the cell at (r, c).
     * If found, it clears that 3x3 area.
     */
    private static void tryToClearObstacle(char[][] grid, int r, int c, int rows, int cols) {
        // A 3x3 square covering cell (r, c) must have a top-left corner (tr, tc)
        // such that the cell (r, c) is within [tr, tr + 2] and [tc, tc + 2].
        // Therefore, tr must be in [r-2, r] and tc must be in [c-2, c].
        for (int tr = r - 2; tr <= r; tr++) {
            for (int tc = c - 2; tc <= c; tc++) {
                if (isSquareInBounds(tr, tc, rows, cols)) {
                    clearSquare(grid, tr, tc);
                    return; // Once the obstacle is cleared, move to the next cell.
                }
            }
        }
    }

    /**
     * Validates if a 3x3 square starting at (startRow, startCol) is within grid boundaries.
     */
    private static boolean isSquareInBounds(int startRow, int startCol, int rows, int cols) {
        return startRow >= 0 && 
               startCol >= 0 && 
               startRow + SQUARE_SIZE <= rows && 
               startCol + SQUARE_SIZE <= cols;
    }

    /**
     * Fills a 3x3 area starting at (startRow, startCol) with the EMPTY character.
     */
    private static void clearSquare(char[][] grid, int startRow, int startCol) {
        for (int i = startRow; i < startRow + SQUARE_SIZE; i++) {
            for (int j = startCol; j < startCol + SQUARE_SIZE; j++) {
                grid[i][j] = EMPTY;
            }
        }
    }

    /**
     * Final check to see if any obstacles remain in the grid.
     */
    private static boolean areAllObstaclesCleared(char[][] grid, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == OBSTACLE) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.util.*;

/**
 * Solves the problem of determining if a grid pattern of '#' can be 
 * reconstructed using only 3x3 blocks of '#' characters.
 */
public class GridPatternSolver {

    private static final char HASH_CHAR = '#';
    private static final char DOT_CHAR = '.';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] inputGrid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            inputGrid[i] = scanner.next().toCharArray();
        }

        PatternMatcher matcher = new PatternMatcher(rows, cols);
        boolean isPossible = matcher.canReconstruct(inputGrid);

        System.out.println(isPossible ? "YES" : "NO");
        scanner.close();
    }

    /**
     * Service class responsible for the logic of grid reconstruction.
     */
    static class PatternMatcher {
        private final int rows;
        private final int cols;

        public PatternMatcher(int rows, int cols) {
            this.rows = rows;
            this.cols = cols;
        }

        /**
         * Attempts to reconstruct the input grid using 3x3 blocks and 
         * checks if the result matches the input.
         * 
         * @param inputGrid The target grid pattern.
         * @return true if the grid can be perfectly reconstructed.
         */
        public boolean canReconstruct(char[][] inputGrid) {
            char[][] reconstructedGrid = createEmptyGrid();

            // We iterate through all possible centers of a 3x3 block.
            // A center cannot be on the outermost boundary of the grid.
            for (int r = 1; r < rows - 1; r++) {
                for (int c = 1; c < cols - 1; c++) {
                    if (isFull3x3Block(inputGrid, r, c)) {
                        fill3x3Block(reconstructedGrid, r, c);
                    }
                }
            }

            return areGridsEqual(inputGrid, reconstructedGrid);
        }

        private char[][] createEmptyGrid() {
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                Arrays.fill(grid[i], DOT_CHAR);
            }
            return grid;
        }

        /**
         * Checks if the 3x3 area centered at (row, col) consists entirely of HASH_CHAR.
         */
        private boolean isFull3x3Block(char[][] grid, int row, int col) {
            for (int i = row - 1; i <= row + 1; i++) {
                for (int j = col - 1; j <= col + 1; j++) {
                    if (grid[i][j] != HASH_CHAR) {
                        return false;
                    }
                }
            }
            return true;
        }

        /**
         * Fills the 3x3 area centered at (row, col) with HASH_CHAR.
         */
        private void fill3x3Block(char[][] grid, int row, int col) {
            for (int i = row - 1; i <= row + 1; i++) {
                for (int j = col - 1; j <= col + 1; j++) {
                    grid[i][j] = HASH_CHAR;
                }
            }
        }

        /**
         * Compares two 2D grids for equality.
         */
        private boolean areGridsEqual(char[][] grid1, char[][] grid2) {
            for (int i = 0; i < rows; i++) {
                if (!Arrays.equals(grid1[i], grid2[i])) {
                    return false;
                }
            }
            return true;
        }
    }
}

import java.util.Scanner;

/**
 * A utility to verify if a grid of '#' characters can be fully represented 
 * by the overlapping 3x3 neighborhoods of its internal cells.
 */
public class GridPatternMatcher {

    private final int rows;
    private final int cols;
    private final boolean[][] originalGrid;
    private final boolean[][] reconstructedGrid;

    public GridPatternMatcher(int rows, int cols, boolean[][] originalGrid) {
        this.rows = rows;
        this.cols = cols;
        this.originalGrid = originalGrid;
        this.reconstructedGrid = new boolean[rows][cols];
    }

    /**
     * Executes the core algorithm to reconstruct the grid and compare it.
     * @return true if the reconstructed grid matches the original, false otherwise.
     */
    public boolean isPatternValid() {
        // Iterate only through internal cells (excluding borders)
        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < cols - 1; c++) {
                if (isCellSurroundedByHash(r, c)) {
                    markSurroundingNeighbors(r, c);
                }
            }
        }
        return areGridsIdentical();
    }

    /**
     * Checks if all 8 neighbors of a specific cell are '#' (true).
     */
    private boolean isCellSurroundedByHash(int centerR, int centerC) {
        for (int r = centerR - 1; r <= centerR + 1; r++) {
            for (int c = centerC - 1; c <= centerC + 1; c++) {
                // Skip the center cell itself
                if (r == centerR && c == centerC) {
                    continue;
                }
                if (!originalGrid[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Marks the 8 neighbors of a cell as true in the reconstructed grid.
     */
    private void markSurroundingNeighbors(int centerR, int centerC) {
        for (int r = centerR - 1; r <= centerR + 1; r++) {
            for (int c = centerC - 1; c <= centerC + 1; c++) {
                if (r == centerR && c == centerC) {
                    continue;
                }
                reconstructedGrid[r][c] = true;
            }
        }
    }

    /**
     * Compares the original input grid with the reconstructed grid.
     */
    private boolean areGridsIdentical() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (originalGrid[r][c] != reconstructedGrid[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        boolean[][] grid = new boolean[n][m];

        for (int i = 0; i < n; i++) {
            String line = scanner.next();
            for (int j = 0; j < m; j++) {
                grid[i][j] = (line.charAt(j) == '#');
            }
        }

        GridPatternMatcher matcher = new GridPatternMatcher(n, m, grid);
        boolean result = matcher.isPatternValid();

        System.out.println(result ? "YES" : "NO");

        scanner.close();
    }
}

import java.io.*;
import java.util.*;

/**
 * A utility to check if all '#' characters in a grid are covered by 
 * the neighborhood of a complete 3x3 block of '#' characters.
 */
public class HashGridCoverageChecker {

    // Offsets representing the 8 neighbors around a central cell
    private static final int[] ROW_OFFSETS = {-1, -1, -1, 0, 0, 1, 1, 1};
    private static final int[] COL_OFFSETS = {-1, 0, 1, -1, 1, -1, 0, 1};

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int numRows = reader.nextInt();
            int numCols = reader.nextInt();

            char[][] grid = new char[numRows][numCols];
            for (int i = 0; i < numRows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            boolean[][] isCovered = new boolean[numRows][numCols];

            // Step 1: Identify cells that act as "centers" of a 3x3 hash neighborhood
            // and mark their neighbors as covered.
            for (int r = 0; r < numRows; r++) {
                for (int c = 0; c < numCols; c++) {
                    if (isSurroundedByHashes(r, c, grid, numRows, numCols)) {
                        markNeighborsAsCovered(r, c, isCovered);
                    }
                }
            }

            // Step 2: Verify if every '#' in the grid has been marked as covered.
            boolean allHashesCovered = checkAllHashesCovered(grid, isCovered, numRows, numCols);

            writer.println(allHashesCovered ? "YES" : "NO");

        } catch (IOException | NoSuchElementException e) {
            // In a production environment, use a logging framework.
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Checks if all 8 neighbors of the cell at (r, c) are '#' characters.
     */
    private static boolean isSurroundedByHashes(int r, int c, char[][] grid, int rows, int cols) {
        for (int i = 0; i < 8; i++) {
            int neighborRow = r + ROW_OFFSETS[i];
            int neighborCol = c + COL_OFFSETS[i];

            if (isOutOfBounds(neighborRow, neighborCol, rows, cols) || grid[neighborRow][neighborCol] != '#') {
                return false;
            }
        }
        return true;
    }

    /**
     * Marks the 8 neighbors of the cell at (r, c) as covered.
     */
    private static void markNeighborsAsCovered(int r, int c, boolean[][] isCovered) {
        for (int i = 0; i < 8; i++) {
            int neighborRow = r + ROW_OFFSETS[i];
            int neighborCol = c + COL_OFFSETS[i];
            // Bounds check is implicitly satisfied because isSurroundedByHashes returned true
            isCovered[neighborRow][neighborCol] = true;
        }
    }

    /**
     * Validates that every '#' cell in the grid is marked in the isCovered array.
     */
    private static boolean checkAllHashesCovered(char[][] grid, boolean[][] isCovered, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '#' && !isCovered[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    private static boolean isOutOfBounds(int r, int c, int rows, int cols) {
        return r < 0 || r >= rows || c < 0 || c >= cols;
    }

    /**
     * Fast I/O utility for reading large inputs.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) {
                    return null;
                }
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            String next = next();
            return (next == null) ? 0 : Integer.parseInt(next);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to determine if all '#' characters in a grid can be covered 
 * by a 3x3 pattern (excluding the center cell).
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            char[][] gridData = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                gridData[i] = reader.next().toCharArray();
            }

            Grid grid = new Grid(gridData);
            CoverageSolver solver = new CoverageSolver(grid);

            if (solver.canCoverAllWalls()) {
                writer.println("YES");
            } else {
                writer.println("NO");
            }
        } catch (Exception e) {
            // In a real-world application, use a logger
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    /**
     * Represents the 2D grid of characters.
     */
    static class Grid {
        private final int rows;
        private final int cols;
        private final char[][] cells;
        private static final char WALL_CHAR = '#';

        public Grid(char[][] cells) {
            this.cells = cells;
            this.rows = cells.length;
            this.cols = cells[0].length;
        }

        public int getRows() {
            return rows;
        }

        public int getCols() {
            return cols;
        }

        public char getCell(int r, int c) {
            return cells[r][c];
        }

        public boolean isWall(int r, int c) {
            return cells[r][c] == WALL_CHAR;
        }
    }

    /**
     * Contains the logic to solve the coverage problem.
     */
    static class CoverageSolver {
        private static final int PATTERN_SIZE = 3;
        private static final int CENTER_OFFSET = 1;

        private final Grid grid;
        private final boolean[][] covered;

        public CoverageSolver(Grid grid) {
            this.grid = grid;
            this.covered = new boolean[grid.getRows()][grid.getCols()];
        }

        /**
         * Orchestrates the coverage check.
         * @return true if all '#' cells are covered by valid 3x3 patterns.
         */
        public boolean canCoverAllWalls() {
            identifyCoverableAreas();
            return verifyAllWallsAreCovered();
        }

        private void identifyCoverableAreas() {
            int rows = grid.getRows();
            int cols = grid.getCols();

            // Iterate through every possible top-left corner of a 3x3 block
            for (int r = 0; r <= rows - PATTERN_SIZE; r++) {
                for (int c = 0; c <= cols - PATTERN_SIZE; c++) {
                    if (isPatternValid(r, c)) {
                        markPatternAsCovered(r, c);
                    }
                }
            }
        }

        /**
         * Checks if a 3x3 block starting at (startRow, startCol) 
         * has '#' in all perimeter positions.
         */
        private boolean isPatternValid(int startRow, int startCol) {
            for (int i = 0; i < PATTERN_SIZE; i++) {
                for (int j = 0; j < PATTERN_SIZE; j++) {
                    // Skip the center cell of the 3x3 block
                    if (i == CENTER_OFFSET && j == CENTER_OFFSET) {
                        continue;
                    }
                    if (!grid.isWall(startRow + i, startCol + j)) {
                        return false;
                    }
                }
            }
            return true;
        }

        private void markPatternAsCovered(int startRow, int startCol) {
            for (int i = 0; i < PATTERN_SIZE; i++) {
                for (int j = 0; j < PATTERN_SIZE; j++) {
                    if (i == CENTER_OFFSET && j == CENTER_OFFSET) {
                        continue;
                    }
                    covered[startRow + i][startCol + j] = true;
                }
            }
        }

        private boolean verifyAllWallsAreCovered() {
            for (int r = 0; r < grid.getRows(); r++) {
                for (int c = 0; c < grid.getCols(); c++) {
                    if (grid.isWall(r, c) && !covered[r][c]) {
                        return false;
                    }
                }
            }
            return true;
        }
    }

    /**
     * Utility class for fast input reading.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream), 1 << 15);
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

/**
 * A utility to validate specific grid patterns based on neighborhood rules.
 */
public class GridPatternValidator {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        scanner.nextLine(); // Consume the newline

        boolean[][] originalGrid = parseGrid(scanner, rows, cols);

        if (isPatternValid(originalGrid, rows, cols)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Core logic to determine if the grid follows the specified expansion rule.
     */
    private static boolean isPatternValid(boolean[][] grid, int rows, int cols) {
        boolean[][] interiorGrid = findInteriorCells(grid, rows, cols);
        boolean[][] expandedGrid = expandInteriorCells(interiorGrid, rows, cols);

        return compareGrids(grid, expandedGrid, rows, cols);
    }

    /**
     * Parses the input into a boolean grid.
     * '.' is treated as false (empty), everything else is true (filled).
     */
    private static boolean[][] parseGrid(Scanner scanner, int rows, int cols) {
        boolean[][] grid = new boolean[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.nextLine();
            for (int j = 0; j < cols; j++) {
                // Using the logic: '.' is 0 (false), others are 1 (true)
                grid[i][j] = (line.charAt(j) != '.');
            }
        }
        return grid;
    }

    /**
     * Identifies cells that are completely surrounded by filled cells.
     */
    private static boolean[][] findInteriorCells(boolean[][] grid, int rows, int cols) {
        boolean[][] interiorGrid = new boolean[rows][cols];

        // Interior cells must be at least 1 unit away from any boundary
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (isFullySurrounded(grid, i, j)) {
                    interiorGrid[i][j] = true;
                }
            }
        }
        return interiorGrid;
    }

    /**
     * Checks if all 8 neighbors of a cell are true.
     */
    private static boolean isFullySurrounded(boolean[][] grid, int r, int c) {
        for (int dr = -1; dr <= 1; dr++) {
            for (int dc = -1; dc <= 1; dc++) {
                if (dr == 0 && dc == 0) continue;
                if (!grid[r + dr][c + dc]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Expands the interior cells to their neighbors.
     * Note: Per the original logic, the interior cell itself is not marked true 
     * by its own existence, only its neighbors are.
     */
    private static boolean[][] expandInteriorCells(boolean[][] interiorGrid, int rows, int cols) {
        boolean[][] expandedGrid = new boolean[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (interiorGrid[i][j]) {
                    markNeighbors(expandedGrid, i, j);
                }
            }
        }
        return expandedGrid;
    }

    /**
     * Sets all 8 neighbors of a cell to true.
     */
    private static void markNeighbors(boolean[][] grid, int r, int c) {
        for (int dr = -1; dr <= 1; dr++) {
            for (int dc = -1; dc <= 1; dc++) {
                if (dr == 0 && dc == 0) continue;
                int nr = r + dr;
                int nc = c + dc;
                // Bounds check is safe because interiorGrid is only true for non-boundary cells
                grid[nr][nc] = true;
            }
        }
    }

    /**
     * Compares two grids for equality.
     */
    private static boolean compareGrids(boolean[][] grid1, boolean[][] grid2, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid1[i][j] != grid2[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }
}

