import java.util.StringTokenizer;

/**
 * Problem Solution: Determines if all '#' cells in a grid can be covered 
 * by 3x3 squares consisting entirely of '#' cells.
 */
public class CF1059B {

    private static final char HASH = '#';
    private static final char DOT = '.';

    // Directional offsets for the 8 neighbors (including diagonals)
    private static final int[] DX = {-1, -1, -1, 0, 0, 1, 1, 1};
    private static final int[] DY = {-1, 0, 1, -1, 1, -1, 0, 1};

    public static void main(String[] args) {
        FastReader reader = new FastReader();

        int rows = reader.nextInt();
        int cols = reader.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = reader.next().toCharArray();
        }

        if (solve(grid, rows, cols)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Core logic to determine if all hash cells are covered.
     */
    private static boolean solve(char[][] grid, int rows, int cols) {
        boolean[][] isCenter = findCenters(grid, rows, cols);

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == HASH) {
                    if (!isCoveredByCenter(isCenter, i, j, rows, cols)) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    /**
     * Identifies all cells that can act as the center of a 3x3 square of '#'.
     */
    private static boolean[][] findCenters(char[][] grid, int rows, int cols) {
        boolean[][] centers = new boolean[rows][cols];

        // A center cannot exist on the boundary of the grid
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (isValidCenter(grid, i, j, rows, cols)) {
                    centers[i][j] = true;
                }
            }
        }
        return centers;
    }

    /**
     * Checks if a 3x3 area centered at (r, c) is entirely composed of '#'.
     */
    private static boolean isValidCenter(char[][] grid, int r, int c, int rows, int cols) {
        // Check the cell itself and its 8 neighbors
        for (int i = -1; i <= 1; i++) {
            for (int j = -1; j <= 1; j++) {
                if (grid[r + i][c + j] != HASH) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Checks if the cell at (r, c) is covered by at least one identified center.
     */
    private static boolean isCoveredByCenter(boolean[][] isCenter, int r, int c, int rows, int cols) {
        // A cell is covered if it is a center itself or adjacent to one
        if (isCenter[r][c]) return true;

        for (int i = 0; i < 8; i++) {
            int nr = r + DX[i];
            int nc = c + DY[i];

            if (isInBounds(nr, nc, rows, cols) && isCenter[nr][nc]) {
                return true;
            }
        }
        return false;
    }

    private static boolean isInBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Optimized reader for fast I/O.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
