/**
 * A utility to determine if all '#' characters in a grid can be 
 * fully covered by 3x3 blocks of '#' characters.
 */
public class GridPatternChecker {

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final boolean[][] covered;

    public GridPatternChecker(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.covered = new boolean[rows][cols];
    }

    /**
     * Executes the coverage check algorithm.
     * 
     * @return true if all '#' cells are part of at least one 3x3 '#' block.
     */
    public boolean canCoverAllHashes() {
        findAndMarkAllBlocks();
        return verifyCoverage();
    }

    /**
     * Iterates through the grid to find every possible 3x3 area consisting 
     * entirely of '#' and marks those cells as covered.
     */
    private void findAndMarkAllBlocks() {
        // We only need to iterate up to (rows - 3) and (cols - 3) 
        // to ensure a 3x3 window fits within the bounds.
        for (int r = 0; r <= rows - 3; r++) {
            for (int c = 0; c <= cols - 3; c++) {
                if (isFullBlock(r, c)) {
                    markBlock(r, c);
                }
            }
        }
    }

    /**
     * Checks if a 3x3 block starting at (startR, startC) is entirely composed of '#'.
     */
    private boolean isFullBlock(int startR, int startC) {
        for (int r = startR; r < startR + 3; r++) {
            for (int c = startC; c < startC + 3; c++) {
                if (grid[r][c] != '#') {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Marks all cells in a 3x3 block starting at (startR, startC) as covered.
     */
    private void markBlock(int startR, int startC) {
        for (int r = startR; r < startR + 3; r++) {
            for (int c = startC; c < startC + 3; c++) {
                covered[r][c] = true;
            }
        }
    }

    /**
     * Verifies if any '#' cell in the grid remains uncovered.
     */
    private boolean verifyCoverage() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '#' && !covered[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    public static void main(String[] args) {
        FastReader reader = new FastReader();

        try {
            String nStr = reader.next();
            if (nStr == null) return;

            int n = Integer.parseInt(nStr);
            int m = Integer.parseInt(reader.next());

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                grid[i] = reader.next().toCharArray();
            }

            GridPatternChecker checker = new GridPatternChecker(n, m, grid);

            if (checker.canCoverAllHashes()) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        } catch (Exception e) {
            // In a production environment, use a logger.
            e.printStackTrace();
