import java.util.Scanner;

/**
 * GridValidator determines if every '#' cell in a grid is part of at least one 3x3 block of '#' cells.
 */
public class GridValidator {

    /**
     * Represents the grid and contains the logic for validating the pattern.
     */
    private static class Grid {
        private final char[][] cells;
        private final int rows;
        private final int cols;

        public Grid(int rows, int cols, char[][] cells) {
            this.rows = rows;
            this.cols = cols;
            this.cells = cells;
        }

        /**
         * Checks if a coordinate is within the grid boundaries.
         */
        private boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        /**
         * A cell is considered the "center" of a 3x3 block if all 9 cells 
         * in its 3x3 neighborhood are '#'.
         * 
         * @param r The row index
         * @param c The column index
         * @return true if the 3x3 area around (r, c) is entirely '#'
         */
        public boolean isCenterOf3x3(int r, int c) {
            // A center must be at least 1 cell away from any edge to accommodate a 3x3 block
            if (r < 1 || r >= rows - 1 || c < 1 || c >= cols - 1) {
                return false;
            }

            for (int i = r - 1; i <= r + 1; i++) {
                for (int j = c - 1; j <= c + 1; j++) {
                    if (cells[i][j] != '#') {
                        return false;
                    }
                }
            }
            return true;
        }

        /**
         * A cell is part of a 3x3 block if it is either a center itself 
         * or is adjacent to a center.
         * 
         * @param r The row index
         * @param c The column index
         * @return true if the cell belongs to at least one 3x3 block of '#'
         */
        public boolean isPartOf3x3Block(int r, int c) {
            // Check the 3x3 area around the current cell to see if any of those cells act as a center
            for (int i = r - 1; i <= r + 1; i++) {
                for (int j = c - 1; j <= c + 1; j++) {
                    if (isWithinBounds(i, j) && isCenterOf3x3(i, j)) {
                        return true;
                    }
                }
            }
            return false;
        }

        /**
         * Iterates through the entire grid to ensure every '#' cell satisfies the requirement.
         * 
         * @return true if all '#' cells are part of a 3x3 block, false otherwise.
         */
        public boolean validateAllHashes() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (cells[i][j] == '#' && !isPartOf3x3Block(i, j)) {
                        return false;
                    }
                }
            }
            return true;
        }
    }

    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            if (!sc.hasNextInt()) {
                return;
            }

            int rows = sc.nextInt();
            int cols = sc.nextInt();

            // Consume the remaining newline character after reading integers
            if (sc.hasNextLine()) {
                sc.nextLine();
            }

            char[][] gridArray = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                if (sc.hasNextLine()) {
                    String line = sc.nextLine();
                    for (int j = 0; j < cols; j++) {
                        // Safely handle lines that might be shorter than 'cols'
                        gridArray[i][j] = (j < line.length()) ? line.charAt(j) : ' ';
                    }
                }
            }

            Grid grid = new Grid(rows, cols, gridArray);

            if (grid.validateAllHashes()) {
                System.out.print("YES");
            } else {
                System.out.print("NO");
            }
        } catch (Exception e) {
            // In a real production environment, use a logger here.
            // For this refactor, we gracefully handle potential input errors.
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Analyzes a grid to determine if all '#' cells are adjacent to a 'center'.
 * A 'center' is defined as a non-boundary cell surrounded by eight '#' neighbors.
 */
public class GridAnalyzerTask {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] grid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                grid[i] = reader.readLine().toCharArray();
            }

            GridAnalyzer analyzer = new GridAnalyzer(grid);
            if (analyzer.isAllHashesNearCenter()) {
                writer.println("YES");
            } else {
                writer.println("NO");
            }
        } catch (Exception e) {
            // In a production environment, use a proper logger
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    /**
     * Handles the logic of analyzing the grid structure.
     */
    static class GridAnalyzer {
        private final char[][] grid;
        private final int rows;
        private final int cols;
        private final boolean[][] isCenter;

        // Direction vectors for the 8 neighbors (diagonal, horizontal, vertical)
        private static final int[] DR = {-1, -1, -1, 0, 0, 1, 1, 1};
        private static final int[] DC = {-1, 0, 1, -1, 1, -1, 0, 1};

        public GridAnalyzer(char[][] grid) {
            this.grid = grid;
            this.rows = grid.length;
            this.cols = grid[0].length;
            this.isCenter = new boolean[rows][cols];
            computeCenters();
        }

        /**
         * Identifies all cells that qualify as a 'center'.
         */
        private void computeCenters() {
            // A center cannot be on the boundary of the grid
            for (int r = 1; r < rows - 1; r++) {
                for (int c = 1; c < cols - 1; c++) {
                    if (isSurroundedByHashes(r, c)) {
                        isCenter[r][c] = true;
                    }
                }
            }
        }

        /**
         * Checks if all 8 neighbors of a specific cell are '#' characters.
         */
        private boolean isSurroundedByHashes(int r, int c) {
            for (int i = 0; i < 8; i++) {
                if (grid[r + DR[i]][c + DC[i]] != '#') {
                    return false;
                }
            }
            return true;
        }

        /**
         * Validates if every '#' cell in the grid is adjacent to at least one center.
         * 
         * @return true if all '#' cells satisfy the condition, false otherwise.
         */
        public boolean isAllHashesNearCenter() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '#') {
                        if (!isAdjacentToACenter(r, c)) {
                            return false;
                        }
                    }
                }
            }
            return true;
        }

        /**
         * Checks the 8 neighbors of a cell to see if any of them is a pre-computed center.
         */
        private boolean isAdjacentToACenter(int r, int c) {
            for (int i = 0; i < 8; i++) {
                int nr = r + DR[i];
                int nc = c + DC[i];

                if (isWithinBounds(nr, nc) && isCenter[nr][nc]) {
                    return true;
                }
            }
            return false;
        }

        private boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * High-performance input reader for large datasets.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public String readLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new RuntimeException("Error reading line", e);
            }
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * A program to validate if every '#' character in a grid is part of 
 * at least one solid 3x3 block of '#' characters.
 */
public class Main {

    public static void main(String[] args) {
        FastReader in = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        PatternValidator solver = new PatternValidator(in);
        solver.solve(out);

        out.flush();
        out.close();
    }

    /**
     * Logic handler for the grid pattern validation problem.
     */
    static class PatternValidator {
        private final FastReader reader;

        public PatternValidator(FastReader reader) {
            this.reader = reader;
        }

        /**
         * Reads the grid and determines if the pattern requirement is met.
         * 
         * @param out The PrintWriter to output the result.
         */
        public void solve(PrintWriter out) {
            String nInput = reader.next();
            String mInput = reader.next();

            if (nInput == null || mInput == null) {
                return;
            }

            int rows = Integer.parseInt(nInput);
            int cols = Integer.parseInt(mInput);

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                if (line != null) {
                    grid[i] = line.toCharArray();
                }
            }

            // Tracks which '#' cells are part of a valid 3x3 block
            boolean[][] isCovered = new boolean[rows][cols];

            // Step 1: Identify all valid 3x3 blocks and mark their cells
            for (int i = 0; i <= rows - 3; i++) {
                for (int j = 0; j <= cols - 3; j++) {
                    if (isSolid3x3Block(grid, i, j)) {
                        markCellsAsCovered(isCovered, i, j);
                    }
                }
            }

            // Step 2: Verify if every '#' cell is covered by at least one block
            boolean allHashesCovered = true;
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '#' && !isCovered[i][j]) {
                        allHashesCovered = false;
                        break;
                    }
                }
                if (!allHashesCovered) {
                    break;
                }
            }

            out.println(allHashesCovered ? "YES" : "NO");
        }

        /**
         * Checks if the 3x3 area starting at top-left corner (r, c) consists only of '#'.
         */
        private boolean isSolid3x3Block(char[][] grid, int r, int c) {
            for (int i = r; i < r + 3; i++) {
                for (int j = c; j < c + 3; j++) {
                    if (grid[i][j] != '#') {
                        return false;
                    }
                }
            }
            return true;
        }

        /**
         * Marks all cells in the 3x3 area starting at (r, c) as being part of a valid block.
         */
        private void markCellsAsCovered(boolean[][] isCovered, int r, int c) {
            for (int i = r; i < r + 3; i++) {
                for (int j = c; j < c + 3; j++) {
                    isCovered[i][j] = true;
                }
            }
        }
    }

    /**
     * High-performance input reader utility.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        /**
         * Reads the next space-delimited string.
         */
        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }
    }
}

import java.util.Arrays;
import java.util.Scanner;

/**
 * A utility to validate if a grid follows a specific pattern where '#' cells
 * are formed exclusively by the rings of 3x3 blocks where the top-left cell is '#'.
 */
public class PatternValidator {

    // Offsets representing the 8 cells in a 3x3 ring (excluding the center)
    private static final int[][] RING_OFFSETS = {
            {0, 0}, {0, 1}, {0, 2},
            {1, 0},         {1, 2},
            {2, 0}, {2, 1}, {2, 2}
    };

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int numRows = scanner.nextInt();
        int numCols = scanner.nextInt();

        char[][] inputGrid = new char[numRows][numCols];
        for (int i = 0; i < numRows; i++) {
            inputGrid[i] = scanner.next().toCharArray();
        }

        if (isValidPattern(numRows, numCols, inputGrid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Orchestrates the pattern validation process.
     */
    private static boolean isValidPattern(int rows, int cols, char[][] inputGrid) {
        char[][] patternGrid = initializeEmptyGrid(rows, cols);

        // Iterate through every possible 3x3 top-left corner
        for (int r = 0; r <= rows - 3; r++) {
            for (int c = 0; c <= cols - 3; c++) {

                // Pattern condition:
                // 1. Top-left cell must be '#'
                // 2. All 8 ring cells in the input must be '#'
                // 3. The ring has not been fully filled in our result grid yet (optimization)
                if (inputGrid[r][c] == '#' && 
                    isRingComplete(inputGrid, r, c) && 
                    hasEmptyCellInRing(patternGrid, r, c)) {

                    fillRing(patternGrid, r, c);
                }
            }
        }

        return areGridsIdentical(inputGrid, patternGrid, rows, cols);
    }

    private static char[][] initializeEmptyGrid(int rows, int cols) {
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            Arrays.fill(grid[i], '.');
        }
        return grid;
    }

    /**
     * Checks if all cells in the 3x3 ring are '#' in the provided grid.
     */
    private static boolean isRingComplete(char[][] grid, int r, int c) {
        for (int[] offset : RING_OFFSETS) {
            if (grid[r + offset[0]][c + offset[1]] != '#') {
                return false;
            }
        }
        return true;
    }

    /**
     * Checks if there is at least one '.' in the 3x3 ring of the provided grid.
     */
    private static boolean hasEmptyCellInRing(char[][] grid, int r, int c) {
        for (int[] offset : RING_OFFSETS) {
            if (grid[r + offset[0]][c + offset[1]] == '.') {
                return true;
            }
        }
        return false;
    }

    /**
     * Fills the 3x3 ring cells with '#' in the target grid.
     */
    private static void fillRing(char[][] grid, int r, int c) {
        for (int[] offset : RING_OFFSETS) {
            grid[r + offset[0]][c + offset[1]] = '#';
        }
    }

    /**
     * Compares two grids to see if they are exactly the same.
     */
    private static boolean areGridsIdentical(char[][] gridA, char[][] gridB, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (gridA[i][j] != gridB[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.util.*;
import java.io.*;

/**
 * This program determines if a grid is composed entirely of 3x3 '#' rings.
 * A 3x3 ring consists of '#' at the perimeter and a '.' (or any other character) at the center.
 */
public class GridPatternMatcher {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            char[][] originalGrid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                originalGrid[i] = reader.next().toCharArray();
            }

            if (solve(rows, cols, originalGrid)) {
                writer.println("YES");
            } else {
                writer.println("NO");
            }
        } catch (Exception e) {
            // In a production environment, use a logger
            writer.println("NO");
        } finally {
            writer.close();
        }
    }

    /**
     * Core logic to validate the grid pattern.
     * 
     * @param rows Number of rows in the grid
     * @param cols Number of columns in the grid
     * @param grid The input grid
     * @return true if the grid is perfectly composed of 3x3 rings, false otherwise
     */
    private static boolean solve(int rows, int cols, char[][] grid) {
        char[][] reconstructedGrid = initializeEmptyGrid(rows, cols);

        // Step 1: Identify all 3x3 rings in the original grid and mark them in the reconstructed grid
        for (int i = 0; i <= rows - 3; i++) {
            for (int j = 0; j <= cols - 3; j++) {
                if (isRingPattern(grid, i, j)) {
                    fillRingPattern(reconstructedGrid, i, j);
                }
            }
        }

        // Step 2: Compare the original grid with the reconstructed version
        return areGridsIdentical(grid, reconstructedGrid, rows, cols);
    }

    /**
     * Checks if a 3x3 area starting at (r, c) forms a '#' ring.
     */
    private static boolean isRingPattern(char[][] grid, int r, int c) {
        return grid[r][c] == '#' && grid[r][c + 1] == '#' && grid[r][c + 2] == '#' &&
               grid[r + 1][c] == '#' &&                         grid[r + 1][c + 2] == '#' &&
               grid[r + 2][c] == '#' && grid[r + 2][c + 1] == '#' && grid[r + 2][c + 2] == '#';
    }

    /**
     * Marks the perimeter of a 3x3 area as '#' in the target grid.
     */
    private static void fillRingPattern(char[][] target, int r, int c) {
        target[r][c] = '#'; target[r][c + 1] = '#'; target[r][c + 2] = '#';
        target[r + 1][c] = '#';                   target[r + 1][c + 2] = '#';
        target[r + 2][c] = '#'; target[r + 2][c + 1] = '#'; target[r + 2][c + 2] = '#';
    }

    /**
     * Creates a grid of the specified dimensions filled with '.'.
     */
    private static char[][] initializeEmptyGrid(int rows, int cols) {
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            Arrays.fill(grid[i], '.');
        }
        return grid;
    }

    /**
     * Compares two grids for exact equality.
     */
    private static boolean areGridsIdentical(char[][] grid1, char[][] grid2, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid1[i][j] != grid2[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Efficient input reader using BufferedReader and StringTokenizer.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.util.Scanner;

/**
 * SignValidator determines if a grid of characters follows specific pattern rules.
 * A grid is considered valid if every '#' character serves as an anchor for 
 * one of the predefined shape patterns.
 */
public class SignValidator {

    private static final char TARGET_CHAR = '#';

    /**
     * Relative coordinate offsets for the 8 valid patterns.
     * Each sub-array represents the (row_offset, col_offset) from an anchor cell (r, c).
     */
    private static final int[][][] PATTERN_OFFSETS = {
        {{0, 0}, {0, 1}, {0, 2}, {1, 0}, {2, 0}, {1, 2}, {2, 1}, {2, 2}}, // Pattern 1
        {{0, 0}, {0, 1}, {0, -1}, {1, 1}, {1, -1}, {2, 1}, {2, -1}, {2, 0}}, // Pattern 2
        {{0, 0}, {1, 0}, {2, 0}, {0, -1}, {0, -2}, {1, -2}, {2, -2}, {2, -1}}, // Pattern 3
        {{0, 0}, {1, 0}, {-1, 0}, {1, -1}, {-1, -1}, {1, -2}, {-1, -2}, {0, -2}}, // Pattern 4
        {{0, 0}, {0, -1}, {0, -2}, {-1, 0}, {-2, 0}, {-1, -2}, {-2, -1}, {-2, -2}}, // Pattern 5
        {{0, 0}, {0, -1}, {0, 1}, {-1, -1}, {-1, 1}, {-2, -1}, {-2, 1}, {-2, 0}}, // Pattern 6
        {{0, 0}, {-1, 0}, {0, 1}, {-2, 0}, {0, 2}, {-2, 1}, {-2, 2}}, // Pattern 7 (7-cell variant)
        {{0, 0}, {1, 0}, {-1, 0}, {1, 1}, {-1, 1}, {1, 2}, {-1, 2}, {0, 2}} // Pattern 8
    };

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        char[][] grid = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
            }
        }

        boolean isValid = validateGrid(grid, rows, cols);
        System.out.println(isValid ? "YES" : "NO");

        scanner.close();
    }

    /**
     * Iterates through the grid and ensures every target character is part of a valid pattern.
     *
     * @param grid The character grid to validate.
     * @param rows Number of rows in the grid.
     * @param cols Number of columns in the grid.
     * @return true if all '#' characters are valid anchors, false otherwise.
     */
    private static boolean validateGrid(char[][] grid, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == TARGET_CHAR) {
                    if (!matchesAnyPattern(grid, rows, cols, i, j)) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    /**
     * Checks if the current cell matches any of the defined patterns.
     */
    private static boolean matchesAnyPattern(char[][] grid, int rows, int cols, int r, int c) {
        for (int[][] pattern : PATTERN_OFFSETS) {
            if (checkPatternMatch(grid, rows, cols, r, c, pattern)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Validates a specific pattern against the grid.
     *
     * @param grid The character grid.
     * @param rows Grid height.
     * @param cols Grid width.
     * @param r Anchor row.
     * @param c Anchor column.
     * @param pattern Array of relative offsets.
     * @return true if all required cells in the pattern are within bounds and contain TARGET_CHAR.
     */
    private static boolean checkPatternMatch(char[][] grid, int rows, int cols, int r, int c, int[][] pattern) {
        for (int[] offset : pattern) {
            int targetRow = r + offset[0];
            int targetCol = c + offset[1];

            if (isOutOfBounds(targetRow, targetCol, rows, cols) || grid[targetRow][targetCol] != TARGET_CHAR) {
                return false;
            }
        }
        return true;
    }

    private static boolean isOutOfBounds(int r, int c, int rows, int cols) {
        return r < 0 || r >= rows || c < 0 || c >= cols;
    }
}

