/**
 * A refactored solution for processing grid patterns and interval calculations.
 */
public class Main {

    public static void main(String[] args) {
        try (FastReader reader = new FastReader(System.in);
             PrintWriter writer = new PrintWriter(System.out)) {

            // The original code specifically executes problemB.
            solveProblemB(reader, writer);

        } catch (IOException e) {
            System.err.println("An error occurred while processing input: " + e.getMessage());
        }
    }

    /**
     * Problem B: Validates if every '#' in the grid is adjacent to a 3x3 block of '#' cells.
     * 
     * @param in   The input reader.
     * @param out  The output writer.
     * @throws IOException If an I/O error occurs.
     */
    public static void solveProblemB(FastReader in, PrintWriter out) throws IOException {
        int rowCount = in.nextInt();
        int colCount = in.nextInt();
        char[][] grid = new char[rowCount][colCount];

        for (int i = 0; i < rowCount; i++) {
            String row = in.next();
            if (row != null) {
                grid[i] = row.toCharArray();
            }
        }

        if (isGridPatternValid(grid, rowCount, colCount)) {
            out.println("YES");
        } else {
            out.println("NO");
        }
    }

    /**
     * Checks if the grid follows the rule: every '#' must be a neighbor of a 3x3 block center.
     */
    private static boolean isGridPatternValid(char[][] grid, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '#') {
                    if (!hasNeighborThatIsCenter(r, c, grid, rows, cols)) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    /**
     * Checks if any of the 8 neighbors of cell (r, c) is the center of a 3x3 block of '#'.
     */
    private static boolean hasNeighborThatIsCenter(int r, int c, char[][] grid, int rows, int cols) {
        for (int dr = -1; dr <= 1; dr++) {
            for (int dc = -1; dc <= 1; dc++) {
                // Skip the current cell itself as per original logic (di != 0 || dj != 0)
                if (dr == 0 && dc == 0) continue;

                int neighborR = r + dr;
                int neighborC = c + dc;

                if (isWithinBounds(neighborR, neighborC, rows, cols)) {
                    if (isCenterOf3x3Block(neighborR, neighborC, grid, rows, cols)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Determines if the cell at (r, c) is the center of a 3x3 block of '#'.
     * Note: This follows the original logic of checking the 8 surrounding neighbors.
     */
    private static boolean isCenterOf3x3Block(int r, int c, char[][] grid, int rows, int cols) {
        for (int dr = -1; dr <= 1; dr++) {
            for (int dc = -1; dc <= 1; dc++) {
                if (dr == 0 && dc == 0) continue;

                int checkR = r + dr;
                int checkC = c + dc;

                if (!isWithinBounds(checkR, checkC, rows, cols) || grid[checkR][checkC] != '#') {
                    return false;
                }
            }
        }
        return true;
    }

    private static boolean isWithinBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Problem A: Calculates the number of intervals of length 'a' that fit between given segments.
     */
    public static void solveProblemA(FastReader in, PrintWriter out) throws IOException {
        int n = in.nextInt();
        int totalLength = in.nextInt();
        int intervalSize = in.nextInt();

        int lastEndTime = 0;
        long totalIntervals = 0;

        for (int i = 0; i < n; i++) {
            int startTime = in.nextInt();
            int duration = in.nextInt();

            totalIntervals += (startTime - lastEndTime) / intervalSize;
            lastEndTime = startTime + duration;
        }

        totalIntervals += (totalLength - lastEndTime) / intervalSize;
        out.println(totalIntervals);
    }

    /**
     * Efficient input reader using StringTokenizer.
     */
    static class FastReader implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            this.reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        public double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }

        @Override
        public void close() throws IOException {
            reader.close();
        }
    }
}

