/**
 * A program that determines if all '#' cells in a grid can be covered
 * by 3x3 squares consisting entirely of '#' cells.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            int[][] grid = new int[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = (line.charAt(j) == '#') ? GridCoverageSolver.CELL_HASH : GridCoverageSolver.CELL_EMPTY;
                }
            }

            GridCoverageSolver solver = new GridCoverageSolver(grid);
            boolean result = solver.solve();

            writer.println(result ? "YES" : "NO");
        } catch (NoSuchElementException e) {
            // Handle potential input errors
        } finally {
            writer.close();
        }
    }

    /**
     * Handles the logic for checking if the grid can be covered by 3x3 squares.
     */
    static class GridCoverageSolver {
        private static final int CELL_EMPTY = 0;
        private static final int CELL_HASH = 1;
        private static final int CELL_COVERED = 2;

        private final int[][] grid;
        private final int rows;
        private final int cols;

        public GridCoverageSolver(int[][] grid) {
            this.grid = grid;
            this.rows = grid.length;
            this.cols = grid[0].length;
        }

        /**
         * Executes the greedy algorithm to cover all '#' cells.
         * @return true if all '#' cells are covered, false otherwise.
         */
        public boolean solve() {
            // Iterate through all possible 3x3 square bottom-right corners
            for (int r = 2; r < rows; r++) {
                for (int c = 2; c < cols; c++) {
                    if (canPlaceSquare(r, c)) {
                        fillSquare(r, c);
                    }
                }
            }
            return areAllHashesCovered();
        }

        private boolean canPlaceSquare(int bottomRightR, int bottomRightC) {
            for (int r = bottomRightR - 2; r <= bottomRightR; r++) {
                for (int c = bottomRightC - 2; c <= bottomRightC; c++) {
                    // A square can be placed if all cells are either '#' or already covered
                    if (grid[r][c] == CELL_EMPTY) {
                        return false;
                    }
                }
            }
            return true;
        }

        private void fillSquare(int bottomRightR, int bottomRightC) {
            for (int r = bottomRightR - 2; r <= bottomRightR; r++) {
                for (int c = bottomRightC - 2; c <= bottomRightC; c++) {
                    grid[r][c] = CELL_COVERED;
                }
            }
        }

        private boolean areAllHashesCovered() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == CELL_HASH) {
                        return false;
                    }
                }
            }
            return true;
        }
    }

    /**
     * Optimized reader for fast competitive programming-style input.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.util.Scanner;

/**
 * A utility to validate if every filled cell ('#') in a grid 
 * acts as an anchor for at least one of eight predefined geometric patterns.
 */
public class GridPatternValidator {

    // Each pattern is defined as a set of 7 relative offsets (row, col) from an anchor cell.
    private static final int[][][] PATTERN_OFFSETS = {
        {{-1, 0}, {1, 0}, {-1, 1}, {1, 1}, {-1, 2}, {0, 2}, {1, 2}},   // Pattern 1
        {{-1, 0}, {1, 0}, {0, -2}, {-1, -1}, {-1, -2}, {1, -1}, {1, -2}}, // Pattern 2
        {{0, -1}, {0, 1}, {-1, -1}, {-1, 1}, {-2, 0}, {-2, 1}, {-2, -1}}, // Pattern 3
        {{0, -1}, {0, 1}, {1, -1}, {1, 1}, {2, -1}, {2, 0}, {2, 1}},   // Pattern 4
        {{0, 1}, {0, 2}, {1, 0}, {1, 2}, {2, 0}, {2, 1}, {2, 2}},     // Pattern 5
        {{0, -1}, {0, -2}, {1, 0}, {1, -2}, {2, 0}, {2, -1}, {2, -2}}, // Pattern 6
        {{0, -1}, {0, -2}, {-1, -1}, {-1, -2}, {-2, 0}, {-2, -1}, {-2, -2}}, // Pattern 7
        {{0, 1}, {0, 2}, {-1, 0}, {-1, 2}, {-2, 0}, {-2, 1}, {-2, 2}}  // Pattern 8
    };

    private final int rows;
    private final int cols;
    private final boolean[][] grid;

    public GridPatternValidator(int rows, int cols, boolean[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
    }

    /**
     * Validates if the grid meets the minimum size requirements 
     * and if all '#' cells follow the pattern rules.
     */
    public boolean isValid() {
        // Basic precondition: patterns require a minimum grid size to be contained.
        if (rows < 3 || cols < 3) {
            return false;
        }

        // Special case: In a 3x3 grid, if the center is filled, 
        // it cannot be an anchor because patterns extend to index -1 or 3.
        if (rows == 3 && cols == 3 && grid[1][1]) {
            return false;
        }

        return checkAllFilledCells();
    }

    private boolean checkAllFilledCells() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c]) {
                    if (!isCellPartOfAnyPattern(r, c)) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    private boolean isCellPartOfAnyPattern(int r, int c) {
        for (int[][] pattern : PATTERN_OFFSETS) {
            if (isPatternComplete(r, c, pattern)) {
                return true;
            }
        }
        return false;
    }

    private boolean isPatternComplete(int r, int c, int[][] pattern) {
        for (int[] offset : pattern) {
            int targetRow = r + offset[0];
            int targetCol = c + offset[1];

            if (!isInBounds(targetRow, targetCol) || !grid[targetRow][targetCol]) {
                return false;
            }
        }
        return true;
    }

    private boolean isInBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        if (!sc.hasNextInt()) {
            sc.close();
            return;
        }

        int n = sc.nextInt();
        int m = sc.nextInt();
        sc.nextLine(); // Consume newline

        boolean[][] grid = new boolean[n][m];
        for (int i = 0; i < n; i++) {
            String line = sc.nextLine();
            for (int j = 0; j < m; j++) {
                if (j < line.length() && line.charAt(j) == '#') {
                    grid[i][j] = true;
                }
            }
        }

        GridPatternValidator validator = new GridPatternValidator(n, m, grid);

        if (validator.isValid()) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        sc.close();
    }
}

import java.util.Scanner;

/**
 * Solution analyzes a grid of obstacles ('#') and empty spaces ('.').
 * 
 * The logic identifies cells that are completely surrounded by 8 obstacle neighbors.
 * If a cell is surrounded, all of its neighbors are "marked".
 * The program returns "YES" if the set of marked cells is identical to the set of obstacles,
 * and "NO" otherwise.
 */
public class Solution {

    // Offsets for the 8 possible directions (horizontal, vertical, and diagonal)
    private static final int[] ROW_OFFSETS = {1, -1, 0, 0, -1, 1, 1, -1};
    private static final int[] COL_OFFSETS = {0, 0, 1, -1, -1, -1, 1, 1};

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        // Load the grid. True represents an obstacle, false represents empty space.
        boolean[][] grid = new boolean[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            for (int j = 0; j < cols; j++) {
                // Following the original logic: anything that is not '.' is treated as an obstacle
                grid[i][j] = (line.charAt(j) != '.');
            }
        }

        if (isGridConsistencyValid(rows, cols, grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Core algorithm to determine if the marked neighbors match the original obstacle grid.
     */
    private static boolean isGridConsistencyValid(int rows, int cols, boolean[][] grid) {
        boolean[][] isMarked = new boolean[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (isSurroundedByObstacles(i, j, rows, cols, grid)) {
                    markNeighbors(i, j, isMarked);
                }
            }
        }

        return areGridsEqual(rows, cols, grid, isMarked);
    }

    /**
     * Checks if all 8 neighbors of a specific cell are within bounds and are obstacles.
     */
    private static boolean isSurroundedByObstacles(int r, int c, int rows, int cols, boolean[][] grid) {
        for (int k = 0; k < 8; k++) {
            int nr = r + ROW_OFFSETS[k];
            int nc = c + COL_OFFSETS[k];

            if (!isWithinBounds(nr, nc, rows, cols) || !grid[nr][nc]) {
                return false;
            }
        }
        return true;
    }

    /**
     * Marks the 8 neighbors of a cell in the provided boolean grid.
     * Assumes the cell is already validated to be surrounded by valid neighbors.
     */
    private static void markNeighbors(int r, int c, boolean[][] isMarked) {
        for (int k = 0; k < 8; k++) {
            int nr = r + ROW_OFFSETS[k];
            int nc = c + COL_OFFSETS[k];
            isMarked[nr][nc] = true;
        }
    }

    /**
     * Validates if the given coordinates are within the grid boundaries.
     */
    private static boolean isWithinBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Compares the original obstacle grid with the generated marked grid.
     */
    private static boolean areGridsEqual(int rows, int cols, boolean[][] grid, boolean[][] isMarked) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] != isMarked[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.util.Scanner;

/**
 * GridValidator determines if a provided character grid matches a specific
 * reconstruction rule based on neighbor patterns.
 */
public class GridValidator {

    private static final char DOT = '.';
    private static final char HASH = '#';

    // Offsets representing the 8 possible directions (neighbors) in a 2D grid
    private static final int[] ROW_OFFSETS = {-1, -1, -1, 0, 0, 1, 1, 1};
    private static final int[] COL_OFFSETS = {-1, 0, 1, -1, 1, -1, 0, 1};

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        if (isPatternValid(grid, rows, cols)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Validates the grid based on the following rule:
     * For every interior cell (not on the boundary), if all 8 of its neighbors 
     * are not '.', then all those neighbors must be marked as '#' in the 
     * reconstructed version of the grid.
     *
     * @param grid The input grid of characters.
     * @param rows Number of rows in the grid.
     * @param cols Number of columns in the grid.
     * @return true if the original grid matches the reconstructed grid, false otherwise.
     */
    private static boolean isPatternValid(char[][] grid, int rows, int cols) {
        char[][] reconstructed = new char[rows][cols];

        // Initialize the reconstructed grid with dots
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                reconstructed[i][j] = DOT;
            }
        }

        // Process only interior cells that have a full set of 8 neighbors
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (allNeighborsAreNotDot(grid, i, j)) {
                    applyHashToNeighbors(reconstructed, i, j);
                }
            }
        }

        return compareGrids(grid, reconstructed, rows, cols);
    }

    /**
     * Checks if all 8 neighbors of a specific cell are something other than a dot.
     */
    private static boolean allNeighborsAreNotDot(char[][] grid, int r, int c) {
        for (int k = 0; k < 8; k++) {
            int neighborRow = r + ROW_OFFSETS[k];
            int neighborCol = c + COL_OFFSETS[k];
            if (grid[neighborRow][neighborCol] == DOT) {
                return false;
            }
        }
        return true;
    }

    /**
     * Marks all 8 neighbors of a cell as '#' in the reconstruction grid.
     */
    private static void applyHashToNeighbors(char[][] reconstructed, int r, int c) {
        for (int k = 0; k < 8; k++) {
            int neighborRow = r + ROW_OFFSETS[k];
            int neighborCol = c + COL_OFFSETS[k];
            reconstructed[neighborRow][neighborCol] = HASH;
        }
    }

    /**
     * Compares two grids to see if they are identical.
     */
    private static boolean compareGrids(char[][] gridA, char[][] gridB, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (gridA[i][j] != gridB[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.util.Scanner;

/**
 * This program determines if all '#' characters in a grid can be covered
 * by 3x3 rings consisting of '#' characters. A ring is a 3x3 area 
 * where the 8 outer cells are '#' and the center cell can be anything.
 */
public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String rowString = scanner.next();
            grid[i] = rowString.toCharArray();
        }

        GridPatternSolver solver = new GridPatternSolver(grid);

        if (solver.canCoverAllHashes()) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }
}

/**
 * Logic handler for processing the grid pattern requirements.
 */
class GridPatternSolver {
    private static final int PATTERN_SIZE = 3;
    private final char[][] grid;
    private final int rows;
    private final int cols;

    public GridPatternSolver(char[][] grid) {
        this.grid = grid;
        this.rows = grid.length;
        this.cols = (rows > 0) ? grid[0].length : 0;
    }

    /**
     * Evaluates if every '#' in the grid is part of at least one 3x3 ring of '#' cells.
     * 
     * @return true if all '#' are covered by rings, false otherwise.
     */
    public boolean canCoverAllHashes() {
        if (rows == 0 || cols == 0) {
            return true;
        }

        boolean[][] isCovered = new boolean[rows][cols];

        // Step 1: Identify all valid 3x3 rings and mark their constituent '#' cells as covered.
        // We iterate through every possible top-left corner of a 3x3 block.
        for (int r = 0; r <= rows - PATTERN_SIZE; r++) {
            for (int c = 0; c <= cols - PATTERN_SIZE; c++) {
                if (isRingOfHashes(r, c)) {
                    markRingAsCovered(r, c, isCovered);
                }
            }
        }

        // Step 2: Verify if there are any '#' cells that were not covered by any identified ring.
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '#' && !isCovered[r][c]) {
                    return false;
                }
            }
        }

        return true;
    }

    /**
     * Checks if a 3x3 area starting at (startRow, startCol) forms a ring of '#'.
     * The center cell of the 3x3 area is ignored in the check.
     * 
     * @param startRow The starting row index of the 3x3 block.
     * @param startCol The starting column index of the 3x3 block.
     * @return true if all 8 outer cells are '#', false otherwise.
     */
    private boolean isRingOfHashes(int startRow, int startCol) {
        for (int r = startRow; r < startRow + PATTERN_SIZE; r++) {
            for (int c = startCol; c < startCol + PATTERN_SIZE; c++) {
                // Skip the center cell of the 3x3 block
                if (r == startRow + 1 && c == startCol + 1) {
                    continue;
                }
                if (grid[r][c] != '#') {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Marks the 8 outer cells of a 3x3 area as covered in the provided boolean mask.
     * 
     * @param startRow The starting row index of the 3x3 block.
     * @param startCol The starting column index of the 3x3 block.
     * @param isCovered The boolean array used to track covered '#' cells.
     */
    private void markRingAsCovered(int startRow, int startCol, boolean[][] isCovered) {
        for (int r = startRow; r < startRow + PATTERN_SIZE; r++) {
            for (int c = startCol; c < startCol + PATTERN_SIZE; c++) {
                // Skip the center cell
                if (r == startRow + 1 && c == startCol + 1) {
                    continue;
                }
                isCovered[r][c] = true;
            }
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A solver to determine if a grid of '#' characters can be perfectly tiled
 * by a specific set of 8-cell shapes.
 */
public class GridTiler {

    /**
     * Represents one of the 8 allowed shapes.
     * Each shape is defined by a set of relative offsets from an anchor cell.
     */
    private static class Shape {
        private final int[][] offsets;

        public Shape(int[][] offsets) {
            this.offsets = offsets;
        }

        /**
         * Checks if the shape can be placed on the grid with the given anchor.
         */
        public boolean canPlace(int r, int c, int rows, int cols, char[][] grid, boolean[][] visited) {
            for (int[] offset : offsets) {
                int nr = r + offset[0];
                int nc = c + offset[1];

                if (nr < 0 || nr >= rows || nc < 0 || nc >= cols || 
                    grid[nr][nc] != '#' || visited[nr][nc]) {
                    return false;
                }
            }
            return true;
        }

        /**
         * Marks all cells of this shape as visited on the grid.
         */
        public void place(int r, int c, boolean[][] visited) {
            for (int[] offset : offsets) {
                visited[r + offset[0]][c + offset[1]] = true;
            }
        }
    }

    // Pre-defined set of 8 shapes based on the original logic's patterns.
    private static final List<Shape> ALLOWED_SHAPES = Arrays.asList(
        new Shape(new int[][]{{0,0}, {1,0}, {2,0}, {0,1}, {0,2}, {1,2}, {2,1}, {2,2}}),
        new Shape(new int[][]{{0,0}, {0,-1}, {2,0}, {1,-1}, {2,-1}, {0,1}, {1,1}, {2,1}}),
        new Shape(new int[][]{{0,0}, {0,-1}, {0,-2}, {1,0}, {1,-2}, {2,0}, {2,-1}, {2,-2}}),
        new Shape(new int[][]{{0,0}, {-1,0}, {-1,1}, {-1,2}, {0,2}, {1,0}, {1,1}, {1,2}}),
        new Shape(new int[][]{{0,0}, {-1,0}, {-1,-1}, {-1,-2}, {0,-2}, {1,0}, {1,-1}, {1,-2}}),
        new Shape(new int[][]{{0,0}, {-1,0}, {-2,0}, {-2,1}, {0,1}, {-2,2}, {-1,2}, {0,2}}),
        new Shape(new int[][]{{0,0}, {0,-1}, {-1,-1}, {-2,-1}, {-2,0}, {-2,1}, {-1,1}, {0,1}}),
        new Shape(new int[][]{{0,0}, {-1,0}, {-2,0}, {-2,-1}, {0,-1}, {0,-2}, {-1,-2}, {-2,-2}})
    );

    public static void main(String[] args) {
        FastReader sc = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            int n = sc.nextInt();
            int m = sc.nextInt();
            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                grid[i] = sc.next().toCharArray();
            }

            out.println(isTilingPossible(n, m, grid) ? "YES" : "NO");
        } catch (Exception e) {
            // Handle potential parsing errors
        } finally {
            out.close();
        }
    }

    /**
     * Attempts to tile all '#' cells using the allowed shapes.
     */
    private static boolean isTilingPossible(int n, int m, char[][] grid) {
        boolean[][] visited = new boolean[n][m];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                // If we find an unvisited '#', it must be the start of a shape.
                // In row-major order, it must be the "first" cell of that shape.
                if (grid[i][j] == '#' && !visited[i][j]) {
                    boolean placed = false;
                    for (Shape shape : ALLOWED_SHAPES) {
                        if (shape.canPlace(i, j, n, m, grid, visited)) {
                            shape.place(i, j, visited);
                            placed = true;
                            break;
                        }
                    }
                    // If no shape can cover this unvisited '#', tiling is impossible.
                    if (!placed) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    /**
     * Efficient reader for large competitive programming inputs.
     */
    private static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Solution for the Grid Covering problem.
 * The goal is to determine if all '#' cells in a grid can be covered 
 * by 3x3 "rings" (a 3x3 area with the center cell removed).
 */
public class GridCoverSolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] grid = reader.readGrid(rows, cols);

            String result = solve(rows, cols, grid);
            out.println(result);
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        } finally {
            out.close();
        }
    }

    /**
     * Core logic to solve the grid coverage problem using a greedy approach.
     * 
     * @param rows Total number of rows in the grid.
     * @param cols Total number of columns in the grid.
     * @param grid The 2D character array representing the map.
     * @return "YES" if all '#' can be covered, otherwise "NO".
     */
    private static String solve(int rows, int cols, char[][] grid) {
        boolean[][] isCovered = new boolean[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                // If we find a '#' that hasn't been covered yet, we must place a ring
                if (grid[r][c] == '#' && !isCovered[r][c]) {
                    if (!tryToCoverCell(r, c, rows, cols, grid, isCovered)) {
                        return "NO";
                    }
                }
            }
        }

        return "YES";
    }

    /**
     * Attempts to find a valid 3x3 ring that covers the target cell (targetR, targetC).
     * A ring is valid if all 8 cells in the ring are '#'.
     */
    private static boolean tryToCoverCell(int targetR, int targetC, int rows, int cols, 
                                          char[][] grid, boolean[][] isCovered) {

        // A ring centered at (centerR, centerC) covers (targetR, targetC) 
        // if the distance in both dimensions is <= 1 and the center is not the target cell.
        for (int centerR = targetR - 1; centerR <= targetR + 1; centerR++) {
            for (int centerC = targetC - 1; centerC <= targetC + 1; centerC++) {

                // The target cell cannot be the center (hole) of the ring
                if (centerR == targetR && centerC == targetC) {
                    continue;
                }

                if (isWithinBounds(centerR, centerC, rows, cols) && isRingValid(centerR, centerC, rows, cols, grid)) {
                    markRing(centerR, centerC, isCovered);
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Checks if a 3x3 ring centered at (r, c) consists entirely of '#' characters.
     */
    private static boolean isRingValid(int r, int c, int rows, int cols, char[][] grid) {
        for (int i = r - 1; i <= r + 1; i++) {
            for (int j = c - 1; j <= c + 1; j++) {
                if (i == r && j == c) continue; // Skip the center hole

                if (!isWithinBounds(i, j, rows, cols) || grid[i][j] != '#') {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Marks the 8 cells of a ring centered at (r, c) as covered.
     */
    private static void markRing(int r, int c, boolean[][] isCovered) {
        for (int i = r - 1; i <= r + 1; i++) {
            for (int j = c - 1; j <= c + 1; j++) {
                if (i == r && j == c) continue;
                isCovered[i][j] = true;
            }
        }
    }

    private static boolean isWithinBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Efficient input reader for large datasets.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public char[][] readGrid(int rows, int cols) throws IOException {
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = next();
                grid[i] = line.toCharArray();
            }
            return grid;
        }
    }
}

