/**
 * A solution to determine if every inked cell ('#') in a grid is part of 
 * at least one 3x3 block of inked cells.
 */
public class Main {

    public static void main(String[] args) {
        try {
            FastReader reader = new FastReader(System.in);
            GridAnalyzer analyzer = new GridAnalyzer(reader);

            if (analyzer.isAllInkedCellsCovered()) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        } catch (IOException e) {
            System.err.println("Error processing input: " + e.getMessage());
        }
    }
