/**
 * Encapsulates the logic for analyzing the grid pattern.
 */
class GridAnalyzer {
    private final int rows;
    private final int cols;
    private final boolean[][] grid;

    public GridAnalyzer(FastReader reader) throws IOException {
        this.rows = reader.nextInt();
        this.cols = reader.nextInt();
        this.grid = new boolean[rows][cols];
        initializeGrid(reader);
    }

    /**
     * Populates the boolean grid based on input characters.
     */
    private void initializeGrid(FastReader reader) throws IOException {
        for (int i = 0; i < rows; i++) {
            String line = reader.next();
            if (line == null) break;
            for (int j = 0; j < cols; j++) {
                grid[i][j] = (line.charAt(j) == '#');
            }
        }
    }

    /**
     * Performs the core validation logic.
     * @return true if every '#' cell is part of a 3x3 block of '#' cells.
     */
    public boolean isAllInkedCellsCovered() {
        boolean[][] isCovered = new boolean[rows][cols];

        // A 3x3 block can only be centered at indices [1, rows-2] and [1, cols-2]
        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < cols - 1; c++) {
                if (isComplete3x3Block(r, c)) {
                    markBlockAsCovered(r, c, isCovered);
                }
            }
        }

        return validateConsistency(isCovered);
    }

    /**
     * Checks if the 3x3 area centered at (centerR, centerC) is entirely filled with '#'.
     */
    private boolean isComplete3x3Block(int centerR, int centerC) {
        for (int dr = -1; dr <= 1; dr++) {
            for (int dc = -1; dc <= 1; dc++) {
                if (!grid[centerR + dr][centerC + dc]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Marks all cells in a 3x3 block as being "covered" by a valid square.
     */
    private void markBlockAsCovered(int centerR, int centerC, boolean[][] isCovered) {
        for (int dr = -1; dr <= 1; dr++) {
            for (int dc = -1; dc <= 1; dc++) {
                isCovered[centerR + dr][centerC + dc] = true;
            }
        }
    }

    /**
     * Compares the original grid with the coverage map.
     * Every cell that was inked must be marked as covered.
     */
    private boolean validateConsistency(boolean[][] isCovered) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                // If an inked cell is not part of a 3x3 block, the condition fails.
                if (grid[r][c] != isCovered[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }
}

/**
 * High-performance reader for reading large inputs.
 */
class FastReader {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    public FastReader(InputStream input) {
        this.reader = new BufferedReader(new InputStreamReader(input));
    }

    /**
     * Fetches the next string token.
     */
    public String next() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreElements()) {
            String line = reader.readLine();
            if (line == null) {
                return null;
            }
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    /**
     * Fetches the next integer.
     */
    public int nextInt() throws IOException {
        String token = next();
        if (token == null) {
            throw new IOException("Unexpected end of input");
        }
        return Integer.parseInt(token);
    }
}

