            GridAnalyzer analyzer = new GridAnalyzer(grid, rowCount, colCount);
            boolean result = analyzer.allHashesAreCovered();

            writer.printLine(result ? "YES" : "NO");

        } catch (Exception e) {
            // In a production environment, use a logger.
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }
}

/**
 * Handles the core logic of analyzing the character grid.
 */
class GridAnalyzer {
    private final char[][] grid;
    private final int rows;
    private final int cols;

    public GridAnalyzer(char[][] grid, int rows, int cols) {
        this.grid = grid;
        this.rows = rows;
        this.cols = cols;
    }

    /**
     * Checks if every '#' character in the grid is part of the perimeter 
     * of at least one 3x3 block of '#' characters.
     * 
     * Note: The original logic specifically requires the top-left corner 
     * of the 3x3 block to be '#' to initiate the check.
     */
    public boolean allHashesAreCovered() {
        boolean[][] visited = new boolean[rows][cols];

        // Scan for valid 3x3 blocks
        for (int i = 0; i <= rows - 3; i++) {
            for (int j = 0; j <= cols - 3; j++) {
                // Based on original logic: only check if the top-left cell is '#'
                if (grid[i][j] == '#' && isPerimeterValid(i, j)) {
                    markPerimeterVisited(visited, i, j);
                }
            }
        }

        // Verify if all '#' cells were covered by at least one perimeter
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '#' && !visited[i][j]) {
                    return false;
                }
            }
        }

        return true;
    }

    /**
     * Checks if the 8 cells surrounding the center of a 3x3 block (starting at startR, startC)
     * are all '#'.
     */
    private boolean isPerimeterValid(int startR, int startC) {
        for (int r = 0; r < 3; r++) {
            for (int c = 0; c < 3; c++) {
                if (isCenterCell(r, c)) {
                    continue;
                }
                if (grid[startR + r][startC + c] == '.') {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Marks the 8 perimeter cells of the 3x3 block as visited.
     */
    private void markPerimeterVisited(boolean[][] visited, int startR, int startC) {
        for (int r = 0; r < 3; r++) {
            for (int c = 0; c < 3; c++) {
                if (!isCenterCell(r, c)) {
                    visited[startR + r][startC + c] = true;
                }
            }
        }
    }

    private boolean isCenterCell(int r, int c) {
        return r == 1 && c == 1;
    }
}

/**
 * Efficient input reader for large datasets.
 */
class FastReader {
    private final InputStream stream;
    private final byte[] buffer = new byte[8192];
    private int curChar;
    private int numChars;

    public FastReader(InputStream stream) {
        this.stream = stream;
    }

    private int read() {
        if (numChars == -1) throw new InputMismatchException();
        if (curChar >= numChars) {
            curChar = 0;
            try {
                numChars = stream.read(buffer);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (numChars <= 0) return -1;
        }
        return buffer[curChar++];
    }

    public int nextInt() {
        int c = read();
        while (isSpaceChar(c)) c = read();
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        int res = 0;
        do {
            if (c < '0' || c > '9') throw new InputMismatchException();
            res *= 10;
            res += c - '0';
            c = read();
        } while (!isSpaceChar(c));
        return res * sgn;
    }

    public String nextString() {
        int c = read();
        while (isSpaceChar(c)) c = read();
        StringBuilder res = new StringBuilder();
        do {
            res.appendCodePoint(c);
            c = read();
        } while (!isSpaceChar(c));
        return res.toString();
    }

    private boolean isSpaceChar(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }
}

