/**
 * ForgeryChecker identifies if all '#' characters in a grid are part of a 
 * valid 3x3 pattern where the '#' is a neighbor to a cell surrounded by '#'.
 */
public class ForgeryChecker {

    private static final char TARGET_CHAR = '#';

    public static void main(String[] args) {
        try {
            ForgeryChecker checker = new ForgeryChecker();
            checker.solve();
        } catch (IOException e) {
            System.err.println("An error occurred while reading input: " + e.getMessage());
        }
    }

    /**
     * Orchestrates the grid processing and pattern validation.
     */
    public void solve() throws IOException {
        FastReader reader = new FastReader();

        // Read dimensions
        String rowStr = reader.next();
        String colStr = reader.next();
        if (rowStr == null || colStr == null) return;

        int rows = Integer.parseInt(rowStr);
        int cols = Integer.parseInt(colStr);

        if (rows <= 0 || cols <= 0) {
            System.out.println("NO");
            return;
        }

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = reader.next().toCharArray();
        }

        boolean[][] isSafe = new boolean[rows][cols];

        // Step 1: Identify cells that are part of a valid 3x3 pattern.
        // We iterate through all possible 'center' cells that have 8 neighbors.
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (isSurroundedByTarget(grid, i, j)) {
                    markNeighborsAsSafe(isSafe, i, j);
                }
            }
        }

        // Step 2: Verify if every occurrence of the TARGET_CHAR in the grid is marked as safe.
        boolean allHashesAreSafe = checkAllTargetsSafe(grid, isSafe);

        System.out.println(allHashesAreSafe ? "YES" : "NO");
    }

    /**
     * Checks if all 8 neighbors of the specified cell are the target character.
     */
    private boolean isSurroundedByTarget(char[][] grid, int r, int c) {
        return grid[r + 1][c] == TARGET_CHAR &&
               grid[r - 1][c] == TARGET_CHAR &&
               grid[r][c + 1] == TARGET_CHAR &&
               grid[r][c - 1] == TARGET_CHAR &&
               grid[r + 1][c + 1] == TARGET_CHAR &&
               grid[r - 1][c - 1] == TARGET_CHAR &&
               grid[r - 1][c + 1] == TARGET_CHAR &&
               grid[r + 1][c - 1] == TARGET_CHAR;
    }

    /**
     * Marks the 8 neighbors of a cell as safe in the boolean tracking grid.
     */
    private void markNeighborsAsSafe(boolean[][] isSafe, int r, int c) {
        isSafe[r + 1][c] = true;
        isSafe[r - 1][c] = true;
        isSafe[r][c + 1] = true;
        isSafe[r][c - 1] = true;
        isSafe[r + 1][c + 1] = true;
        isSafe[r - 1][c - 1] = true;
        isSafe[r - 1][c + 1] = true;
        isSafe[r + 1][c - 1] = true;
    }

    /**
     * Iterates through the grid to ensure no target character was left unvalidated.
     */
    private boolean checkAllTargetsSafe(char[][] grid, boolean[][] isSafe) {
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                if (grid[i][j] == TARGET_CHAR && !isSafe[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * A high-performance input reader utility.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader() {
            this.reader = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input stream", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

