/**
 * A solution to determine if all '#' cells in a character grid 
 * can be covered by the perimeters of 3x3 'frames'.
 * A 3x3 frame is defined as the 8 cells surrounding a center cell.
 */
class GridCoveringSolver {
    private final char[][] grid;
    private final int rows;
    private final int cols;
    private final boolean[][] isCovered;

    /**
     * Initializes the solver with the provided grid.
     * 
     * @param grid The 2D character array representing the input grid.
     * @throws IllegalArgumentException if the grid is null or empty.
     */
    public GridCoveringSolver(char[][] grid) {
        if (grid == null || grid.length == 0 || grid[0].length == 0) {
            throw new IllegalArgumentException("Grid must be non-empty.");
        }
        this.grid = grid;
        this.rows = grid.length;
        this.cols = grid[0].length;
        this.isCovered = new boolean[rows][cols];
    }

    /**
     * Executes the logic to find all valid frames and check if all '#' are covered.
     * 
     * @return true if every '#' cell is covered by at least one frame perimeter, false otherwise.
     */
    public boolean solve() {
        // Step 1: Iterate through all possible top-left corners of a 3x3 area.
        // A 3x3 area can only exist if there are at least 3 rows and 3 columns remaining.
        for (int r = 0; r <= rows - 3; r++) {
            for (int c = 0; c <= cols - 3; c++) {
                if (isFrameValid(r, c)) {
                    markFramePerimeter(r, c);
                }
            }
        }

        // Step 2: Verify that no '#' cell has been left uncovered.
        return areAllHashesCovered();
    }

    /**
     * Checks if the 3x3 area starting at (startRow, startCol) forms a valid frame.
     * A frame is valid if all 8 perimeter cells are '#'.
     */
    private boolean isFrameValid(int startRow, int startCol) {
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                // Skip the center cell (1, 1) of the 3x3 area
                if (i == 1 && j == 1) {
                    continue;
                }
                if (grid[startRow + i][startCol + j] != '#') {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Marks the 8 perimeter cells of a 3x3 frame as covered.
     */
    private void markFramePerimeter(int startRow, int startCol) {
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                // Skip the center cell (1, 1) of the 3x3 area
                if (i == 1 && j == 1) {
                    continue;
                }
                isCovered[startRow + i][startCol + j] = true;
            }
        }
    }

    /**
     * Scans the grid to ensure all '#' characters are marked in the isCovered matrix.
     */
    private boolean areAllHashesCovered() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '#' && !isCovered[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }
}

