        private final int cols;
        private final char[][] grid;
        private final boolean[][] isCovered;

        // Relative coordinates of the '#' characters in the 3x3 pattern:
        // ###
        // #.#
        // ###
        private static final int[][] PATTERN_OFFSETS = {
            {0, 0}, {0, 1}, {0, 2},
            {1, 0},         {1, 2},
            {2, 0}, {2, 1}, {2, 2}
        };

        private static final int PATTERN_DIMENSION = 3;

        public GridCoverageSolver(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            this.isCovered = new boolean[rows][cols];
        }

        /**
         * Performs the coverage check.
         * @return true if every '#' in the grid is covered by at least one pattern match.
         */
        public boolean isAllHashesCovered() {
            // 1. Attempt to place the pattern at every valid top-left corner
            for (int r = 0; r <= rows - PATTERN_DIMENSION; r++) {
                for (int c = 0; c <= cols - PATTERN_DIMENSION; c++) {
                    if (canPlacePattern(r, c)) {
                        markPatternAsCovered(r, c);
                    }
                }
            }

            // 2. Verify if all '#' characters have been covered
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '#' && !isCovered[r][c]) {
                        return false;
                    }
                }
            }
            return true;
