        /**
         * Checks if the pattern can be placed with (r, c) as the top-left corner.
         * A pattern can be placed if all '#' in the pattern align with '#' in the grid.
         */
        private boolean canPlacePattern(int r, int c) {
            for (int[] offset : PATTERN_OFFSETS) {
                int targetR = r + offset[0];
                int targetC = c + offset[1];
                if (grid[targetR][targetC] != '#') {
                    return false;
                }
            }
            return true;
        }

        /**
         * Marks the cells covered by the pattern as true.
         */
        private void markPatternAsCovered(int r, int c) {
            for (int[] offset : PATTERN_OFFSETS) {
                isCovered[r + offset[0]][c + offset[1]] = true;
            }
        }
    }

