    static class GridSolver {
        private final int rowCount;
        private final int colCount;
        private final char[][] grid;

        // Directions for the 8 neighbors surrounding a cell
        private static final int[] DX = {1, 0, 1, 0, -1, -1, 1, -1};
        private static final int[] DY = {0, 1, 1, -1, 0, -1, -1, 1};

        public GridSolver(int rowCount, int colCount, char[][] grid) {
            this.rowCount = rowCount;
            this.colCount = colCount;
            this.grid = grid;
        }

        /**
         * Validates if all '#' cells are correctly marked according to the rules.
         * A '#' is valid if it is a neighbor of a cell that is entirely surrounded by '#'.
