import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Refactored solution for the BForgery problem.
 * The program determines if a grid can be reconstructed based on specific 3x3 patterns.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        GridSolver solver = new GridSolver();
        solver.solve(reader, writer);

        writer.flush();
        writer.close();
    }

    /**
     * Handles the core logic for solving the grid problem.
     */
    static class GridSolver {

        /**
         * Executes the solving algorithm.
         *
         * @param in   The fast reader for input.
         * @param out  The print writer for output.
         */
        public void solve(FastReader in, PrintWriter out) {
            int rows = in.nextInt();
            int cols = in.nextInt();

            if (rows <= 0 || cols <= 0) {
                out.println("YES");
                return;
            }

            int[][] originalGrid = new int[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = in.next();
                for (int j = 0; j < cols; j++) {
                    originalGrid[i][j] = (line.charAt(j) == '#') ? 1 : 0;
                }
            }

            int[][] reconstructedGrid = reconstructGrid(originalGrid, rows, cols);

            if (isReconstructionValid(originalGrid, reconstructedGrid, rows, cols)) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        }

        /**
         * Attempts to reconstruct the grid by identifying valid pattern centers.
         */
        private int[][] reconstructGrid(int[][] grid, int rows, int cols) {
            int[][] reconstructed = new int[rows][cols];

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (isPatternCenter(grid, r, c, rows, cols)) {
                        applyPattern(grid, reconstructed, r, c, rows, cols);
                    }
                }
            }
            return reconstructed;
        }

        /**
         * Determines if a cell (r, c) is the center of a valid pattern:
         * 1. A 3x3 area of all zeros.
         * 2. A 3x3 area where all 8 neighbors are ones.
         */
        private boolean isPatternCenter(int[][] grid, int r, int c, int rows, int cols) {
            int totalSum = 0;
            int neighborsSum = 0;

            for (int dr = -1; dr <= 1; dr++) {
                for (int dc = -1; dc <= 1; dc++) {
                    int nr = r + dr;
                    int nc = c + dc;

                    if (isValid(nr, nc, rows, cols)) {
                        int value = grid[nr][nc];
                        totalSum += value;
                        if (dr != 0 || dc != 0) {
                            neighborsSum += value;
                        }
                    }
                }
            }

            // Pattern 1: Entire 3x3 area is 0
            // Pattern 2: All 8 neighbors are 1
            return (totalSum == 0) || (neighborsSum == 8);
        }

        /**
         * Copies the neighbors of a valid pattern center into the reconstructed grid.
         */
        private void applyPattern(int[][] grid, int[][] target, int r, int c, int rows, int cols) {
            for (int dr = -1; dr <= 1; dr++) {
                for (int dc = -1; dc <= 1; dc++) {
                    int nr = r + dr;
                    int nc = c + dc;

                    if (isValid(nr, nc, rows, cols) && !(dr == 0 && dc == 0)) {
                        target[nr][nc] = grid[nr][nc];
                    }
                }
            }
        }

        /**
         * Compares the original grid with the reconstructed one.
         */
        private boolean isReconstructionValid(int[][] original, int[][] reconstructed, int rows, int cols) {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (original[i][j] != reconstructed[i][j]) {
                        return false;
                    }
                }
            }
            return true;
        }

        private boolean isValid(int r, int c, int rows, int cols) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * A fast I/O utility class using BufferedReader and StringTokenizer.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            this.reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            return next != null ? Integer.parseInt(next) : 0;
        }
    }
}

import java.io.BufferedReader;
