/**
 * A solver that determines if all '#' cells in a grid can be covered
 * by a 3x3 "ring" pattern (a 3x3 square excluding the center cell).
 */
public class GridPatternSolver {

    private final int rowCount;
    private final int columnCount;
    private final char[][] grid;

    public GridPatternSolver(int rowCount, int columnCount, char[][] grid) {
        this.rowCount = rowCount;
        this.columnCount = columnCount;
        this.grid = grid;
    }

    /**
     * Executes the logic to check if all '#' cells are part of at least one valid 3x3 ring.
     * 
     * @return true if all '#' cells are covered, false otherwise.
     */
    public boolean isAllPatternsCovered() {
        boolean[][] coveredGrid = new boolean[rowCount][columnCount];

        // Step 1: Identify all valid 3x3 rings and mark their cells as covered
        for (int r = 0; r < rowCount; r++) {
            for (int c = 0; c < columnCount; c++) {
                if (grid[r][c] == '#') {
                    tryMarkPattern(r, c, coveredGrid);
                }
            }
        }

        // Step 2: Verify if every '#' cell in the original grid is marked in coveredGrid
        for (int r = 0; r < rowCount; r++) {
            for (int c = 0; c < columnCount; c++) {
                if (grid[r][c] == '#' && !coveredGrid[r][c]) {
                    return false;
                }
            }
        }

        return true;
    }

    /**
     * Checks if a 3x3 ring exists starting at (startRow, startCol) as the top-left corner.
     * If it exists, marks those 8 cells in the coverage grid.
     */
    private void tryMarkPattern(int startRow, int startCol, boolean[][] coveredGrid) {
        // Check bounds for a 3x3 area
        if (startRow + 2 >= rowCount || startCol + 2 >= columnCount) {
            return;
        }

        // Check if the 8 cells forming the ring are all '#'
        if (isRingPresent(startRow, startCol)) {
            markRingCells(startRow, startCol, coveredGrid);
        }
    }

    private boolean isRingPresent(int r, int c) {
        return grid[r][c] == '#' &&
               grid[r][c + 1] == '#' &&
               grid[r][c + 2] == '#' &&
               grid[r + 1][c] == '#' &&
               grid[r + 1][c + 2] == '#' &&
               grid[r + 2][c] == '#' &&
               grid[r + 2][c + 1] == '#' &&
               grid[r + 2][c + 2] == '#';
    }

    private void markRingCells(int r, int c, boolean[][] coveredGrid) {
        coveredGrid[r][c] = true;
        coveredGrid[r][c + 1] = true;
        coveredGrid[r][c + 2] = true;
        coveredGrid[r + 1][c] = true;
        coveredGrid[r + 1][c + 2] = true;
        coveredGrid[r + 2][c] = true;
        coveredGrid[r + 2][c + 1] = true;
        coveredGrid[r + 2][c + 2] = true;
    }

    public static void main(String[] args) {
        FastReader reader = new FastReader();

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] grid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            GridPatternSolver solver = new GridPatternSolver(rows, cols, grid);

            if (solver.isAllPatternsCovered()) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        } catch (Exception e) {
            // In a real-world scenario, use a logger
            e.printStackTrace();
        }
    }

    /**
     * Fast I/O utility class for efficient reading.
     */
    static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
