/**
 * A program that determines if a grid of '#' characters can be perfectly 
 * covered by placing 3x3 "donut" patterns (a 3x3 square with a hole in the middle).
 */
public class Main {

    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int rows = in.nextInt();
            int columns = in.nextInt();

            boolean[][] grid = new boolean[rows][columns];
            for (int i = 0; i < rows; i++) {
                String line = in.next();
                for (int j = 0; j < columns; j++) {
                    grid[i][j] = (line.charAt(j) == '#');
                }
            }

            GridPatternSolver solver = new GridPatternSolver(rows, columns, grid);
            if (solver.canCoverAllPatterns()) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        } catch (Exception e) {
            // In a real-world scenario, use a proper logger
            e.printStackTrace();
        } finally {
            out.close();
        }
    }

    /**
     * Logic engine for solving the grid pattern problem.
     */
    static class GridPatternSolver {
        private static final int PATTERN_SIZE = 3;
        private static final int CENTER_OFFSET = 1;

        private final int rows;
        private final int cols;
        private final boolean[][] grid;
        private final boolean[][] covered;

        public GridPatternSolver(int rows, int cols, boolean[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            this.covered = new boolean[rows][cols];
        }

        /**
         * Orchestrates the greedy pattern placement and verification.
         * @return true if the grid matches the pattern coverage exactly.
         */
        public boolean canCoverAllPatterns() {
            // Step 1: Try to place patterns greedily
            for (int r = 0; r <= rows - PATTERN_SIZE; r++) {
                for (int c = 0; c <= cols - PATTERN_SIZE; c++) {
                    if (canApplyPatternAt(r, c)) {
                        markPatternCells(r, c);
                    }
                }
            }

            // Step 2: Verify if the covered cells match the input grid exactly
            return verifyCoverage();
        }

        /**
         * Checks if a 3x3 donut pattern can be placed with its top-left corner at (r, c).
         * A pattern can be placed if all 8 perimeter cells are '#' in the grid.
         */
        private boolean canApplyPatternAt(int r, int c) {
            for (int i = 0; i < PATTERN_SIZE; i++) {
                for (int j = 0; j < PATTERN_SIZE; j++) {
                    // Skip the center cell of the 3x3 area
                    if (i == CENTER_OFFSET && j == CENTER_OFFSET) {
                        continue;
                    }

                    if (!grid[r + i][c + j]) {
                        return false;
                    }
                }
            }
            return true;
        }

        /**
         * Marks the 8 perimeter cells of a 3x3 area as covered.
         */
        private void markPatternCells(int r, int c) {
            for (int i = 0; i < PATTERN_SIZE; i++) {
                for (int j = 0; j < PATTERN_SIZE; j++) {
                    if (i == CENTER_OFFSET && j == CENTER_OFFSET) {
                        continue;
                    }
                    covered[r + i][c + j] = true;
                }
            }
        }

        /**
         * Checks if every '#' in the grid is covered and no '.' is covered.
         */
        private boolean verifyCoverage() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] != covered[i][j]) {
                        return false;
                    }
                }
            }
            return true;
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream), 32768);
            this.tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

