/**
 * Represents a 2D grid of obstacles.
 */
class Grid {
    private final int rows;
    private final int cols;
    private final boolean[][] cells;

    public Grid(int rows, int cols) {
        this.rows = rows;
        this.cols = cols;
        this.cells = new boolean[rows][cols];
    }

    public void setObstacle(int r, int c, boolean isObstacle) {
        cells[r][c] = isObstacle;
    }

    public boolean isObstacle(int r, int c) {
        return cells[r][c];
    }

    public int getRows() {
        return rows;
    }

    public int getCols() {
        return cols;
    }

    public boolean equals(Grid other) {
        if (this.rows != other.rows || this.cols != other.cols) {
            return false;
        }
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (this.cells[i][j] != other.cells[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }
}

/**
 * Contains the business logic for solving the grid reconstruction problem.
 */
class GridSolver {
    private static final int PATTERN_SIZE = 3;
    private static final int CENTER_OFFSET = 1;

    public void solve(FastReader reader, PrintWriter writer) {
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        Grid originalGrid = readGrid(reader, rows, cols);
        Grid reconstructedGrid = reconstructGrid(originalGrid);

        if (originalGrid.equals(reconstructedGrid)) {
            writer.println("YES");
        } else {
            writer.println("NO");
        }
    }

    private Grid readGrid(FastReader reader, int rows, int cols) {
        Grid grid = new Grid(rows, cols);
        for (int i = 0; i < rows; i++) {
            String line = reader.next();
            for (int j = 0; j < cols; j++) {
                if (line.charAt(j) == '#') {
                    grid.setObstacle(i, j, true);
                }
            }
        }
        return grid;
    }

    private Grid reconstructGrid(Grid original) {
        Grid reconstructed = new Grid(original.getRows(), original.getCols());

        // Iterate through every possible top-left corner of a 3x3 block
        for (int r = 0; r <= original.getRows() - PATTERN_SIZE; r++) {
            for (int c = 0; c <= original.getCols() - PATTERN_SIZE; c++) {
                if (canPlacePattern(original, r, c)) {
                    applyPattern(reconstructed, r, c);
                }
            }
        }
        return reconstructed;
    }

    private boolean canPlacePattern(Grid grid, int topRow, int leftCol) {
        for (int r = topRow; r < topRow + PATTERN_SIZE; r++) {
            for (int c = leftCol; c < leftCol + PATTERN_SIZE; c++) {
                if (isCenter(r, c, topRow, leftCol)) {
                    continue;
                }
                if (!grid.isObstacle(r, c)) {
                    return false;
                }
            }
        }
        return true;
    }

    private void applyPattern(Grid grid, int topRow, int leftCol) {
        for (int r = topRow; r < topRow + PATTERN_SIZE; r++) {
            for (int c = leftCol; c < leftCol + PATTERN_SIZE; c++) {
                if (!isCenter(r, c, topRow, leftCol)) {
                    grid.setObstacle(r, c, true);
                }
            }
        }
    }

    private boolean isCenter(int r, int c, int topRow, int leftCol) {
        return r == topRow + CENTER_OFFSET && c == leftCol + CENTER_OFFSET;
    }
}

/**
 * Utility class for fast input parsing.
 */
class FastReader {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    public FastReader(InputStream inputStream) {
