        return Double.parseDouble(next());
    }
}

import java.io.PrintWriter;
import java.util.Scanner;

/**
 * A refactored solution to the signature forgery problem.
 * This program determines if a target signature grid can be recreated 
 * by applying specific neighborhood rules.
 */
public class Main {
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter writer = new PrintWriter(System.out)) {

            ForgerySolver solver = new ForgerySolver();
            solver.solve(scanner, writer);
        }
    }
}

class ForgerySolver {
    private static final char HASH = '#';
    private static final char DOT = '.';

    // Direction offsets for the 8 neighbors (horizontal, vertical, and diagonal)
    private static final int[] DR = {-1, -1, -1, 0, 0, 1, 1, 1};
    private static final int[] DC = {-1, 0, 1, -1, 1, -1, 0, 1};

    /**
     * Orchestrates the reading, solving, and outputting of the problem.
     */
    public void solve(Scanner scanner, PrintWriter writer) {
        if (!scanner.hasNextInt()) return;

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] signature = readGrid(scanner, rows, cols);
        char[][] forgery = createEmptyGrid(rows, cols);

        applyForgeryLogic(signature, forgery, rows, cols);

        if (isSignatureMatched(signature, forgery, rows, cols)) {
            writer.println("YES");
        } else {
            writer.println("NO");
        }
    }

    private char[][] readGrid(Scanner scanner, int rows, int cols) {
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.next().toCharArray();
        }
        return grid;
    }

    private char[][] createEmptyGrid(int rows, int cols) {
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                grid[i][j] = DOT;
            }
        }
        return grid;
    }

    /**
     * Iterates through the grid to identify cells that trigger the forgery rule.
     */
    private void applyForgeryLogic(char[][] signature, char[][] forgery, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                // Rule: If current cell is a '#' and hasn't been forged yet, check its neighbors.
                if (signature[r][c] == HASH && forgery[r][c] != HASH) {
                    processNeighbors(signature, forgery, r, c, rows, cols);
                }
            }
        }
    }

    /**
     * Checks the 8 neighbors of a cell to see if any can act as a center for a 3x3 hash block.
     */
    private void processNeighbors(char[][] sig, char[][] forge, int r, int c, int rows, int cols) {
        for (int i = 0; i < 8; i++) {
            int neighborRow = r + DR[i];
            int neighborCol = c + DC[i];

            if (isValidCenter(neighborRow, neighborCol, rows, cols)) {
                if (isNeighborhoodAllHashes(sig, neighborRow, neighborCol, rows, cols)) {
                    markNeighborsAsHash(forge, neighborRow, neighborCol, rows, cols);
                }
            }
        }
    }

    /**
     * Verifies if a cell can be a center (i.e., its 3x3 neighborhood is within bounds).
     */
    private boolean isValidCenter(int r, int c, int rows, int cols) {
        return r > 0 && r < rows - 1 && c > 0 && c < cols - 1;
    }

    /**
     * Checks if all 8 neighbors of the specified center are '#' in the signature.
     */
    private boolean isNeighborhoodAllHashes(char[][] sig, int r, int c, int rows, int cols) {
        for (int i = 0; i < 8; i++) {
            if (sig[r + DR[i]][c + DC[i]] != HASH) {
                return false;
            }
        }
        return true;
    }

    /**
     * Marks the 8 neighbors of the specified center as '#' in the forgery grid.
     */
    private void markNeighborsAsHash(char[][] forge, int r, int c, int rows, int cols) {
        for (int i = 0; i < 8; i++) {
            forge[r + DR[i]][c + DC[i]] = HASH;
        }
    }

    /**
     * Compares the target signature with the generated forgery.
     */
    private boolean isSignatureMatched(char[][] sig, char[][] forge, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (sig[i][j] != forge[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver for the grid coverage problem.
 * The goal is to determine if every '#' in a grid can be part of a 3x3 pattern
 * that specifically excludes the center cell.
 */
public class Contest {

    public static void main(String[] args) {
        try {
            FastReader reader = new FastReader(System.in);
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            boolean[][] grid = new boolean[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                for (int j = 0; j < cols; j++) {
                    if (line.charAt(j) == '#') {
                        grid[i][j] = true;
                    }
                }
            }

            ContestSolver solver = new ContestSolver(rows, cols, grid);
            if (solver.solve()) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Encapsulates the logic for solving the grid coverage problem.
     */
    private static class ContestSolver {
        private final int rows;
        private final int cols;
        private final boolean[][] grid;
        private final boolean[][] isCovered;

        /**
         * The patterns are defined as sets of 8 relative offsets from an "anchor" cell.
         * Each pattern represents a 3x3 block with the center cell missing.
         */
        private static final int[][][] PATTERNS = {
            // Pattern 1: Anchor is Bottom-Right (Missing Top-Left center)
            {{0, 0}, {0, -1}, {0, -2}, {-1, 0}, {-1, -2}, {-2, 0}, {-2, -1}, {-2, -2}},
            // Pattern 2: Anchor is Bottom-Left (Missing Top-Right center)
            {{0, 0}, {0, 1}, {0, 2}, {-1, 0}, {-1, 2}, {-2, 0}, {-2, 1}, {-2, 2}},
            // Pattern 3: Anchor is Top-Left (Missing Bottom-Right center)
            {{0, 0}, {0, 1}, {0, 2}, {1, 0}, {1, 2}, {2, 0}, {2, 1}, {2, 2}},
            // Pattern 4: Anchor is Top-Right (Missing Bottom-Left center)
            {{0, 0}, {0, -1}, {0, -2}, {1, 0}, {1, -2}, {2, 0}, {2, -1}, {2, -2}}
        };

        public ContestSolver(int rows, int cols, boolean[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            this.isCovered = new boolean[rows][cols];
        }

        /**
         * Executes the coverage algorithm.
         * @return true if all '#' cells are covered, false otherwise.
         */
        public boolean solve() {
            // Step 1: Iterate through every '#' and try to use it as an anchor for any pattern
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c]) {
                        tryApplyingPatterns(r, c);
                    }
                }
            }

            // Step 2: Validate that every '#' cell has been marked as covered
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] && !isCovered[r][c]) {
                        return false;
                    }
                }
            }
            return true;
        }

        private void tryApplyingPatterns(int r, int c) {
            for (int[][] pattern : PATTERNS) {
                if (canFitPattern(r, c, pattern)) {
                    applyPattern(r, c, pattern);
                }
            }
        }

        private boolean canFitPattern(int r, int c, int[][] pattern) {
            for (int[] offset : pattern) {
                int nr = r + offset[0];
                int nc = c + offset[1];
                if (isOutOfBounds(nr, nc) || !grid[nr][nc]) {
                    return false;
                }
            }
            return true;
        }

        private void applyPattern(int r, int c, int[][] pattern) {
            for (int[] offset : pattern) {
                isCovered[r + offset[0]][c + offset[1]] = true;
            }
        }

        private boolean isOutOfBounds(int r, int c) {
            return r < 0 || r >= rows || c < 0 || c >= cols;
        }
    }

    /**
     * Fast I/O utility class.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

/**
 * This program validates if every '#' character in a grid is part of 
 * at least one 3x3 square consisting entirely of '#' characters.
 */
public class GridPatternValidator {

    private static final char HASH = '#';
    private static final char DOT = '.';

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;

            int rowCount = scanner.nextInt();
            int colCount = scanner.nextInt();
            char[][] grid = readGrid(scanner, rowCount, colCount);

            if (isEveryHashCovered(grid, rowCount, colCount)) {
                System.out.print("YES");
            } else {
                System.out.print("NO");
            }
        }
    }

    /**
     * Reads the grid from the scanner.
     */
    private static char[][] readGrid(Scanner scanner, int rows, int cols) {
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
            }
        }
        return grid;
    }

    /**
     * Determines if all '#' characters are part of at least one 3x3 block of '#'.
     * 
     * @param grid The input character grid.
     * @param rows Number of rows.
     * @param cols Number of columns.
     * @return true if all '#' are covered by a 3x3 block, false otherwise.
     */
    private static boolean isEveryHashCovered(char[][] grid, int rows, int cols) {
        boolean[][] covered = new boolean[rows][cols];

        // Iterate through all possible centers of a 3x3 square
        // A center must be at least 1 unit away from any edge
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (isAllHashInSquare(grid, i, j)) {
                    markSquareAsCovered(covered, i, j);
                }
            }
        }

        // Final check: Is there any '#' that remains uncovered?
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == HASH && !covered[i][j]) {
                    return false;
                }
            }
        }

        return true;
    }

    /**
     * Checks if the 3x3 area centered at (row, col) consists only of HASH characters.
     */
    private static boolean isAllHashInSquare(char[][] grid, int row, int col) {
        for (int i = row - 1; i <= row + 1; i++) {
            for (int j = col - 1; j <= col + 1; j++) {
                if (grid[i][j] != HASH) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Marks all cells in the 3x3 area centered at (row, col) as covered.
     */
    private static void markSquareAsCovered(boolean[][] covered, int row, int col) {
        for (int i = row - 1; i <= row + 1; i++) {
            for (int j = col - 1; j <= col + 1; j++) {
                covered[i][j] = true;
            }
        }
    }
}

import java.util.Scanner;

/**
 * A program that simulates a pen placement logic on a grid 
 * and determines if any ink remains after processing.
 */
public class Solution {

    private static final char INK = '#';
    private static final char VOID = 'v';

    // Relative coordinates for the 8 neighbors surrounding a cell
    private static final int[] ROW_OFFSETS = {-1, -1, -1, 0, 0, 1, 1, 1};
    private static final int[] COL_OFFSETS = {-1, 0, 1, -1, 1, -1, 0, 1};

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            scanner.nextLine(); // Consume newline

            SignGrid grid = new SignGrid(rows, cols);

            for (int i = 0; i < rows; i++) {
                grid.setRow(i, scanner.nextLine().trim());
            }

            processGrid(grid);

            if (grid.hasRemainingInk()) {
                System.out.println("NO");
            } else {
                System.out.println("YES");
            }
        } catch (Exception e) {
            // In a real-world scenario, use a logger
            e.printStackTrace();
        }
    }

    /**
     * Iterates through the internal cells of the grid and applies the pen logic.
     */
    private static void processGrid(SignGrid grid) {
        int rows = grid.getRows();
        int cols = grid.getCols();

        // The logic only applies to cells not on the boundary
        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < cols - 1; c++) {
                applyPenLogic(grid, r, c);
            }
        }
    }

    /**
     * If all 8 neighbors of a cell are "inked", the neighbors are converted to "void".
     */
    private static void applyPenLogic(SignGrid grid, int r, int c) {
        if (areAllNeighborsInked(grid, r, c)) {
            for (int i = 0; i < 8; i++) {
                grid.setCell(r + ROW_OFFSETS[i], c + COL_OFFSETS[i], VOID);
            }
        }
    }

    private static boolean areAllNeighborsInked(SignGrid grid, int r, int c) {
        for (int i = 0; i < 8; i++) {
            if (!grid.isCellInked(r + ROW_OFFSETS[i], c + COL_OFFSETS[i])) {
                return false;
            }
        }
        return true;
    }

    /**
     * Inner class representing the grid and its domain-specific operations.
     */
    static class SignGrid {
        private final char[][] grid;
        private final int rows;
        private final int cols;

        public SignGrid(int rows, int cols) {
            this.rows = rows;
            this.cols = cols;
            this.grid = new char[rows][cols];
        }

        public void setRow(int rowIndex, String rowContent) {
            char[] chars = rowContent.toCharArray();
            // Ensure we don't exceed grid boundaries if input is malformed
            int limit = Math.min(chars.length, cols);
            for (int j = 0; j < limit; j++) {
                grid[rowIndex][j] = chars[j];
            }
        }

        public void setCell(int r, int c, char value) {
            grid[r][c] = value;
        }

        public boolean isCellInked(int r, int c) {
            char cell = grid[r][c];
            return cell == INK || cell == VOID;
        }

        public boolean hasRemainingInk() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == INK) {
                        return true;
                    }
                }
            }
            return false;
        }

        public int getRows() {
            return rows;
        }

        public int getCols() {
            return cols;
        }
    }
}

