import java.io.*;

/**
 * Solution for the grid processing problem.
 * The goal is to determine if all '#' characters in a grid can be "covered"
 * by 3x3 blocks of non-dot ('.') characters.
 */
public class Solution {

    private static final char DOT = '.';
    private static final char HASH = '#';

    public static void main(String[] args) {
        try (FastScanner scanner = new FastScanner(System.in);
             PrintWriter writer = new PrintWriter(System.out)) {

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            char[][] grid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                String line = scanner.next();
                if (line != null) {
                    grid[i] = line.toCharArray();
                }
            }

            GridSolver solver = new GridSolver(grid);
            if (solver.canCoverAllHashes()) {
                writer.println("YES");
            } else {
                writer.println("NO");
            }

        } catch (IOException | NoSuchElementException e) {
            // In a production environment, use a proper logger
            System.err.println("Error processing input: " + e.getMessage());
        }
    }

    /**
     * Encapsulates the logic for processing the grid.
     */
    static class GridSolver {
        private final int rows;
        private final int cols;
        private final char[][] grid;

        public GridSolver(char[][] grid) {
            this.grid = grid;
            this.rows = grid.length;
            this.cols = (rows > 0) ? grid[0].length : 0;
        }

        /**
         * Determines if all '#' cells are part of at least one valid 3x3 non-dot block.
         * 
         * @return true if all '#' are covered, false otherwise.
         */
        public boolean canCoverAllHashes() {
            if (rows == 0 || cols == 0) return true;

            boolean[][] isCovered = new boolean[rows][cols];

            // 1. Identify all valid 3x3 blocks and mark their cells as covered
            for (int i = 1; i < rows - 1; i++) {
                for (int j = 1; j < cols - 1; j++) {
                    if (isFull3x3Block(i, j)) {
                        markBlockAsCovered(isCovered, i, j);
                    }
                }
            }

            // 2. Check if any '#' character remains uncovered
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == HASH && !isCovered[i][j]) {
                        return false;
                    }
                }
            }

            return true;
        }

        /**
         * Checks if the 3x3 area centered at (r, c) contains no DOT characters.
         */
        private boolean isFull3x3Block(int r, int c) {
            for (int dr = -1; dr <= 1; dr++) {
                for (int dc = -1; dc <= 1; dc++) {
                    if (grid[r + dr][c + dc] == DOT) {
                        return false;
                    }
                }
            }
            return true;
        }

        /**
         * Marks all cells in the 3x3 area centered at (r, c) as covered.
         */
        private void markBlockAsCovered(boolean[][] isCovered, int r, int c) {
            for (int dr = -1; dr <= 1; dr++) {
                for (int dc = -1; dc <= 1; dc++) {
                    isCovered[r + dr][c + dc] = true;
                }
            }
        }
    }

    /**
     * Optimized scanner for fast I/O operations.
     */
    static class FastScanner implements Closeable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream inputStream) {
            this.reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) {
                    return null;
                }
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            String next = next();
            if (next == null) {
                throw new NoSuchElementException("Expected integer but reached end of input.");
            }
            return Integer.parseInt(next);
        }

        @Override
        public void close() throws IOException {
            reader.close();
        }
    }
}

import java.util.*;
