/**
 * A utility to validate if all '#' cells in a grid belong to a specific 8-cell shape pattern.
 * The pattern consists of a center cell and 7 specific neighbors forming a 3-row structure.
 */
public class Main {
    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            GridShapeValidator validator = new GridShapeValidator(rows, cols, grid);
            if (validator.canCoverAllHashes()) {
                writer.println("YES");
            } else {
                writer.println("NO");
            }
        } catch (IOException e) {
            writer.println("ERROR: " + e.getMessage());
        } finally {
            writer.flush();
            writer.close();
        }
    }
}

class GridShapeValidator {
    // Relative coordinates for the 7 neighbors of the anchor cell (the center of the shape)
    private static final int[] ROW_OFFSETS = {0, 0, 1, 1, 2, 2, 2};
    private static final int[] COL_OFFSETS = {-1, 1, -1, 1, -1, 1, 0};

    private final int rowCount;
    private final int colCount;
    private final char[][] grid;

    public GridShapeValidator(int rowCount, int colCount, char[][] grid) {
        this.rowCount = rowCount;
        this.colCount = colCount;
        this.grid = grid;
    }

    /**
     * Checks if every '#' in the grid is part of at least one valid 8-cell shape.
     * @return true if all '#' are covered, false otherwise.
     */
    public boolean canCoverAllHashes() {
        boolean[][] visited = new boolean[rowCount][colCount];

        // Step 1: Identify all anchor points and mark their entire shape as visited
        for (int r = 0; r < rowCount; r++) {
            for (int c = 0; c < colCount; c++) {
                if (isAnchorPoint(r, c)) {
                    markShapeAsVisited(r, c, visited);
                }
            }
        }

        // Step 2: Verify that no '#' exists that hasn't been visited
        for (int r = 0; r < rowCount; r++) {
            for (int c = 0; c < colCount; c++) {
                if (grid[r][c] == '#' && !visited[r][c]) {
                    return false;
                }
            }
        }

        return true;
    }

    /**
     * Determines if the cell at (r, c) can serve as the top-center anchor of the shape.
     */
    private boolean isAnchorPoint(int r, int c) {
        // An anchor cannot be on the leftmost/rightmost column or in the last two rows
        if (c <= 0 || c >= colCount - 1 || r > rowCount - 3) {
            return false;
        }

        // The anchor itself must be a '#'
        if (grid[r][c] != '#') {
            return false;
        }

        // All 7 neighbors must also be '#'
        for (int k = 0; k < ROW_OFFSETS.length; k++) {
            int nr = r + ROW_OFFSETS[k];
            int nc = c + COL_OFFSETS[k];

            if (grid[nr][nc] != '#') {
                return false;
            }
        }

        return true;
    }

    /**
     * Marks the anchor cell and its 7 neighbors as part of a valid shape.
     */
    private void markShapeAsVisited(int r, int c, boolean[][] visited) {
        visited[r][c] = true;
        for (int k = 0; k < ROW_OFFSETS.length; k++) {
            visited[r + ROW_OFFSETS[k]][c + COL_OFFSETS[k]] = true;
        }
    }
}

/**
 * Efficient reader for large input datasets.
 */
class FastReader {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    public FastReader(InputStream input) {
        reader = new BufferedReader(new InputStreamReader(input));
    }

