/**
 * A program to determine if a grid of characters can be perfectly reconstructed
 * by placing 3x3 squares of '#' ink.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            // Read dimensions
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            // Read the input grid
            char[][] inputGrid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                inputGrid[i] = reader.next().toCharArray();
            }

            // Solve the problem
            GridProblemSolver solver = new GridProblemSolver(rows, cols, inputGrid);
            boolean result = solver.solve();

            writer.println(result ? "YES" : "NO");
        } catch (Exception e) {
            // Handle potential input errors
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Logic class responsible for solving the grid reconstruction problem.
     */
    static class GridProblemSolver {
        private final int rows;
        private final int cols;
        private final char[][] inputGrid;

        public GridProblemSolver(int rows, int cols, char[][] inputGrid) {
            this.rows = rows;
            this.cols = cols;
            this.inputGrid = inputGrid;
        }

        /**
         * Attempts to reconstruct the grid using 3x3 ink blocks.
         * @return true if the reconstructed grid matches the input grid.
         */
        public boolean solve() {
            char[][] reconstructedGrid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                Arrays.fill(reconstructedGrid[i], '.');
            }

            // Iterate through all possible centers of a 3x3 square
            // A center must have at least one neighbor on all sides.
            for (int r = 1; r < rows - 1; r++) {
                for (int c = 1; c < cols - 1; c++) {
                    if (canPlaceInkAt(r, c)) {
                        applyInk(reconstructedGrid, r, c);
                    }
                }
            }

            return isGridsIdentical(inputGrid, reconstructedGrid);
        }

        /**
         * Checks if a 3x3 block centered at (r, c) consists entirely of '#'.
         */
        private boolean canPlaceInkAt(int r, int c) {
            for (int i = r - 1; i <= r + 1; i++) {
                for (int j = c - 1; j <= c + 1; j++) {
                    if (inputGrid[i][j] != '#') {
                        return false;
                    }
                }
            }
            return true;
        }

        /**
         * Fills a 3x3 block centered at (r, c) in the target grid.
         */
        private void applyInk(char[][] grid, int r, int c) {
            for (int i = r - 1; i <= r + 1; i++) {
                for (int j = c - 1; j <= c + 1; j++) {
                    grid[i][j] = '#';
                }
            }
        }

        /**
         * Compares two 2D grids for equality.
         */
        private boolean isGridsIdentical(char[][] grid1, char[][] grid2) {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid1[i][j] != grid2[i][j]) {
                        return false;
                    }
                }
            }
            return true;
        }
    }

    /**
     * High-performance input reader.
     */
    static class FastReader {
