import java.io.*;
import java.util.*;

/**
 * A program to determine if a grid of '#' characters can be perfectly formed
 * by the union of 3x3 "rings" (a 3x3 square with an empty center).
 */
public class GridPatternMatcher {

    private static final int PATTERN_SIZE = 3;

    public static void main(String[] args) {
        try (FastReader reader = new FastReader(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            int rows = reader.nextInt();
            int cols = reader.nextInt();

            if (rows <= 0 || cols <= 0) {
                out.println("YES");
                return;
            }

            boolean[][] inputGrid = readInputGrid(reader, rows, cols);
            boolean[][] constructedGrid = new boolean[rows][cols];

            // Traverse the grid to find all possible 3x3 pattern matches
            for (int r = 0; r <= rows - PATTERN_SIZE; r++) {
                for (int c = 0; c <= cols - PATTERN_SIZE; c++) {
                    if (isPatternMatch(inputGrid, r, c)) {
                        applyRing(constructedGrid, r, c);
                    }
                }
            }

            // The grid is valid if the union of all found rings matches the input exactly
            if (areGridsIdentical(inputGrid, constructedGrid, rows, cols)) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Reads the grid from the input source.
     */
    private static boolean[][] readInputGrid(FastReader reader, int rows, int cols) throws IOException {
        boolean[][] grid = new boolean[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = reader.next();
            for (int j = 0; j < cols; j++) {
                if (line.charAt(j) == '#') {
                    grid[i][j] = true;
                }
            }
        }
        return grid;
    }

    /**
     * Checks if the 3x3 area starting at (startRow, startCol) matches the ring pattern.
     * A match occurs if all perimeter cells are '#' (true). 
     * The center cell is not strictly required to be empty here, as the final 
     * verification ensures the input grid's center must remain empty.
     */
    private static boolean isPatternMatch(boolean[][] grid, int startRow, int startCol) {
        for (int i = 0; i < PATTERN_SIZE; i++) {
            for (int j = 0; j < PATTERN_SIZE; j++) {
                // Skip the center cell of the 3x3 window
                if (i == 1 && j == 1) {
                    continue;
                }
                // If any perimeter cell is not a wall, this window is not a ring
                if (!grid[startRow + i][startCol + j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Marks the perimeter of a 3x3 area as true in the target grid.
     */
    private static void applyRing(boolean[][] grid, int startRow, int startCol) {
        for (int i = 0; i < PATTERN_SIZE; i++) {
            for (int j = 0; j < PATTERN_SIZE; j++) {
                if (i == 1 && j == 1) {
                    continue;
                }
                grid[startRow + i][startCol + j] = true;
            }
        }
    }

    /**
     * Compares two boolean grids to see if they are identical.
     */
    private static boolean areGridsIdentical(boolean[][] grid1, boolean[][] grid2, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid1[i][j] != grid2[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Fast I/O utility for efficient reading of large inputs.
     */
    static class FastReader implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            this.reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            String next = next();
            return (next == null) ? 0 : Integer.parseInt(next);
        }

        @Override
        public void close() throws IOException {
            reader.close();
        }
    }
}

