/**
 * A program to determine if all wall segments ('#') in a grid can be 
 * covered by 3x3 blocks of walls.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            Grid grid = new Grid(rows, cols);
            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                if (line == null) break;
                for (int j = 0; j < cols; j++) {
                    if (j < line.length() && line.charAt(j) == '#') {
                        grid.setCell(i, j, Grid.State.WALL);
                    } else {
                        grid.setCell(i, j, Grid.State.EMPTY);
                    }
                }
            }

            GridSolver solver = new GridSolver();
            if (solver.solve(grid)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }

        } catch (Exception e) {
            // In a production environment, use a logger.
            // For this refactor, we handle potential parsing errors gracefully.
        }
    }

    /**
     * Represents the grid and its cell states.
     */
    static class Grid {
        enum State {
            EMPTY,
            WALL,
            COVERED
        }

        private final int rows;
        private final int cols;
        private final State[][] cells;

        public Grid(int rows, int cols) {
            this.rows = rows;
            this.cols = cols;
            this.cells = new State[rows][cols];
        }

        public void setCell(int r, int c, State state) {
            cells[r][c] = state;
        }

        public State getCell(int r, int c) {
            return cells[r][c];
        }

        public int getRows() {
            return rows;
        }

        public int getCols() {
            return cols;
        }

        public boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * Contains the business logic for solving the grid covering problem.
     */
    static class GridSolver {

        /**
         * Iterates through the grid and attempts to cover all uncovered walls.
         * 
         * @param grid The grid to process.
         * @return true if all walls are covered, false otherwise.
         */
        public boolean solve(Grid grid) {
            for (int i = 0; i < grid.getRows(); i++) {
                for (int j = 0; j < grid.getCols(); j++) {
                    if (grid.getCell(i, j) == Grid.State.WALL) {
                        if (canCoverWith3x3(grid, i, j)) {
                            markAsCovered(grid, i, j);
                        } else {
                            return false;
                        }
                    }
                }
            }
            return true;
        }

        /**
         * Checks if a 3x3 block of walls can be placed with (r, c) as the top-left corner.
         */
        private boolean canCoverWith3x3(Grid grid, int r, int c) {
            if (r + 2 >= grid.getRows() || c + 2 >= grid.getCols()) {
                return false;
            }

            for (int i = r; i < r + 3; i++) {
                for (int j = c; j < c + 3; j++) {
                    if (grid.getCell(i, j) == Grid.State.EMPTY) {
                        return false;
                    }
                }
            }
            return true;
        }

        /**
         * Marks a 3x3 area as covered.
         */
        private void markAsCovered(Grid grid, int r, int c) {
            for (int i = r; i < r + 3; i++) {
                for (int j = c; j < c + 3; j++) {
                    grid.setCell(i, j, Grid.State.COVERED);
                }
            }
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            return next != null ? Integer.parseInt(next) : 0;
        }
    }
}

import java.util.Scanner;

/**
 * The Forgery class determines if all '#' (wall) cells in a grid 
 * are "covered" by being part of a 3x3 ring of '#' cells.
 */
public class Forgery {

    private static final char WALL = '#';
    private static final char EMPTY = '.';

    // Offsets used to traverse the 3x3 neighborhood around a cell
    private static final int[] NEIGHBOR_OFFSETS = {-1, 0, 1};

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        if (isAllWallsCovered(rows, cols, grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Validates if every '#' cell in the grid is marked as covered.
     * 
     * @param rows Number of rows in the grid
     * @param cols Number of columns in the grid
     * @param grid The character grid
     * @return true if all walls are covered, false otherwise
     */
    private static boolean isAllWallsCovered(int rows, int cols, char[][] grid) {
        boolean[][] isCovered = new boolean[rows][cols];

        // Step 1: Identify all 3x3 rings of '#' and mark their neighbors as covered
        // We only check from index 1 to n-2 because a 3x3 ring requires 
        // a center with neighbors on all sides.
        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < cols - 1; c++) {
                if (isRingFullOfWalls(grid, r, c)) {
                    markRingAsCovered(isCovered, r, c);
                }
            }
        }

        // Step 2: Verify if any '#' cell remains uncovered
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == WALL && !isCovered[r][c]) {
                    return false;
                }
            }
        }

        return true;
    }

    /**
     * Checks if the 8 cells surrounding the given center (r, c) are all walls.
     */
    private static boolean isRingFullOfWalls(char[][] grid, int r, int c) {
        for (int dr : NEIGHBOR_OFFSETS) {
            for (int dc : NEIGHBOR_OFFSETS) {
                // Skip the center cell itself
                if (dr == 0 && dc == 0) {
                    continue;
                }

                if (grid[r + dr][c + dc] != WALL) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Marks the 8 neighbors of the center (r, c) as covered in the boolean mask.
     */
    private static void markRingAsCovered(boolean[][] isCovered, int r, int c) {
        for (int dr : NEIGHBOR_OFFSETS) {
            for (int dc : NEIGHBOR_OFFSETS) {
                // Skip the center cell itself per original logic
                if (dr == 0 && dc == 0) {
                    continue;
                }
                isCovered[r + dr][c + dc] = true;
            }
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to determine if every '#' cell in a grid is part of a 3x3 "ring" pattern.
 * A 3x3 ring pattern is defined as a 3x3 block of '#' where the center cell is ignored.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        FastWriter writer = new FastWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            boolean[][] grid = new boolean[rows][cols];
            for (int i = 0; i < rows; i++) {
                String rowString = reader.next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = rowString.charAt(j) == '#';
                }
            }

            GridPatternSolver solver = new GridPatternSolver(rows, cols, grid);
            if (solver.isEveryHashCovered()) {
                writer.print("YES");
            } else {
                writer.print("NO");
            }

        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    /**
     * Logic for solving the grid pattern problem.
     */
    static class GridPatternSolver {
        private final int rows;
        private final int cols;
        private final boolean[][] grid;

        public GridPatternSolver(int rows, int cols, boolean[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
        }

        /**
         * Checks if every '#' cell is part of at least one 3x3 ring.
         * @return true if all '#' are covered, false otherwise.
         */
        public boolean isEveryHashCovered() {
            // A 3x3 ring center cannot exist on the boundary of the grid.
            boolean[][] isValidRingCenter = new boolean[rows][cols];

            // Step 1: Identify all valid ring centers.
            // A center (r, c) is valid if all 8 neighbors are '#'.
            for (int r = 1; r < rows - 1; r++) {
                for (int c = 1; c < cols - 1; c++) {
                    if (checkIsRingCenter(r, c)) {
                        isValidRingCenter[r][c] = true;
                    }
                }
            }

            // Step 2: Verify every '#' cell is covered.
            // A '#' cell is covered if at least one of its 8 neighbors is a valid ring center.
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c]) {
                        if (!isAdjacentToValidCenter(r, c, isValidRingCenter)) {
                            return false;
                        }
                    }
                }
            }

            return true;
        }

        private boolean checkIsRingCenter(int r, int c) {
            for (int dr = -1; dr <= 1; dr++) {
                for (int dc = -1; dc <= 1; dc++) {
                    if (dr == 0 && dc == 0) continue; // Skip the center itself
                    if (!grid[r + dr][c + dc]) {
                        return false;
                    }
                }
            }
            return true;
        }

        private boolean isAdjacentToValidCenter(int r, int c, boolean[][] isValidRingCenter) {
            for (int dr = -1; dr <= 1; dr++) {
                for (int dc = -1; dc <= 1; dc++) {
                    if (dr == 0 && dc == 0) continue;
                    int nr = r + dr;
                    int nc = c + dc;

                    if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
                        if (isValidRingCenter[nr][nc]) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }
    }

    /**
     * High-performance input reader for fast I/O.
     */
    static class FastReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int pointer = 0;
        private int bytesRead = 0;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() throws IOException {
            if (pointer >= bytesRead) {
                pointer = 0;
                bytesRead = stream.read(buffer);
                if (bytesRead <= 0) return -1;
            }
            return buffer[pointer++];
        }

        public int nextInt() throws IOException {
            int c = readByte();
            while (c != -1 && isWhitespace(c)) c = readByte();
            if (c == -1) throw new InputMismatchException();

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }

            int res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res = res * 10 + (c - '0');
                c = readByte();
            } while (c != -1 && !isWhitespace(c));

            return res * sign;
        }

        public String next() throws IOException {
            int c = readByte();
            while (c != -1 && isWhitespace(c)) c = readByte();
            if (c == -1) return "";

            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = readByte();
            } while (c != -1 && !isWhitespace(c));
            return sb.toString();
        }

        private boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }

    /**
     * High-performance output writer for fast I/O.
     */
    static class FastWriter implements AutoCloseable {
        private final PrintWriter writer;

        public FastWriter(OutputStream outputStream) {
            this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public void print(String s) {
            writer.print(s);
        }

        @Override
        public void close() {
            writer.close();
        }
    }
}

import java.util.Scanner;

/**
 * A utility to analyze grid patterns to determine if they follow a specific
 * neighbor-based consistency rule.
 */
public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        scanner.nextLine(); // Consume newline

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.nextLine();
            grid[i] = line.toCharArray();
        }

        GridPatternAnalyzer analyzer = new GridPatternAnalyzer(rows, cols, grid);

        if (analyzer.isPatternConsistent()) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }
}

class GridPatternAnalyzer {
    private final int rows;
    private final int cols;
    private final char[][] grid;

    // Direction vectors for the 8 neighbors (horizontal, vertical, and diagonal)
    private static final int[] DX = {0, 0, 1, 1, -1, -1, 1, -1};
    private static final int[] DY = {1, -1, 1, -1, -1, 1, 0, 0};

    /**
     * @param rows Total number of rows in the grid.
     * @param cols Total number of columns in the grid.
     * @param grid The 2D character array representing the pattern.
     */
    public GridPatternAnalyzer(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
    }

    /**
     * Validates if the pattern is consistent.
     * A pattern is consistent if the set of '#' cells is exactly equal to the 
     * set of neighbors of all cells that are entirely surrounded by '#'.
     * 
     * @return true if the pattern matches the rule, false otherwise.
     */
    public boolean isPatternConsistent() {
        boolean[][] targetGrid = new boolean[rows][cols];

        // Step 1: Identify cells that are surrounded by '#' and mark their neighbors
        // We iterate from 1 to rows-2 to ensure neighbors are always within bounds
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (isSurroundedByHash(i, j)) {
                    markNeighborsInTarget(i, j, targetGrid);
                }
            }
        }

        // Step 2: Compare the original grid with the generated target grid
        return compareGridToTarget(targetGrid);
    }

    /**
     * Checks if all 8 neighbors of the specified cell are '#' characters.
     */
    private boolean isSurroundedByHash(int r, int c) {
        for (int i = 0; i < 8; i++) {
            int neighborRow = r + DX[i];
            int neighborCol = c + DY[i];

            if (grid[neighborRow][neighborCol] != '#') {
                return false;
            }
        }
        return true;
    }

    /**
     * Marks all 8 neighbors of a cell as true in the target boolean grid.
     */
    private void markNeighborsInTarget(int r, int c, boolean[][] targetGrid) {
        for (int i = 0; i < 8; i++) {
            int neighborRow = r + DX[i];
            int neighborCol = c + DY[i];
            targetGrid[neighborRow][neighborCol] = true;
        }
    }

    /**
     * Compares the input grid (where '#' is true) against the calculated target grid.
     */
    private boolean compareGridToTarget(boolean[][] targetGrid) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                boolean isHash = (grid[i][j] == '#');
                if (isHash != targetGrid[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * A utility class for fast input reading.
 */
class FastReader {
    private BufferedReader reader;
    private StringTokenizer tokenizer;

    public FastReader(java.io.InputStream inputStream) {
        reader = new BufferedReader(new InputStreamReader(inputStream));
    }

    public String next() {
        while (tokenizer == null || !tokenizer.hasMoreElements()) {
            try {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                throw new RuntimeException("Error reading input", e);
            }
        }
        return tokenizer.nextToken();
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }

    public char[][] nextGrid(int rows, int cols) {
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = next().toCharArray();
        }
        return grid;
    }
}

/**
 * Logic to solve the grid pattern validation problem.
 */
class GridPatternSolver {
    private static final char FILLED_CELL = '#';
    private static final char EMPTY_CELL = '.';

    /**
     * Processes the grid and determines if it matches the generated pattern.
     * 
     * @param rowCount number of rows in the grid
     * @param colCount number of columns in the grid
     * @param reader the input reader
     * @return "YES" if the grid matches the rule-based reconstruction, "NO" otherwise
     */
    public String solve(int rowCount, int colCount, FastReader reader) {
        char[][] originalGrid = reader.nextGrid(rowCount, colCount);
        char[][] reconstructedGrid = initializeEmptyGrid(rowCount, colCount);

        // Only iterate through inner cells as boundary cells cannot be "surrounded"
        for (int r = 1; r < rowCount - 1; r++) {
            for (int c = 1; c < colCount - 1; c++) {
                applyPatternRule(r, c, originalGrid, reconstructedGrid);
            }
        }

        return areGridsIdentical(originalGrid, reconstructedGrid) ? "YES" : "NO";
    }

    private char[][] initializeEmptyGrid(int rows, int cols) {
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                grid[i][j] = EMPTY_CELL;
            }
        }
        return grid;
    }

    /**
     * If a cell is surrounded by 8 filled cells, mark all its neighbors 
     * as filled in the reconstructed grid.
     */
    private void applyPatternRule(int row, int col, char[][] original, char[][] reconstructed) {
        if (countFilledNeighbors(row, col, original) == 8) {
            markNeighborsAsFilled(row, col, reconstructed);
        }
    }

    private int countFilledNeighbors(int row, int col, char[][] grid) {
        int count = 0;
        for (int dr = -1; dr <= 1; dr++) {
            for (int dc = -1; dc <= 1; dc++) {
                if (dr == 0 && dc == 0) continue;

                int nr = row + dr;
                int nc = col + dc;

                if (grid[nr][nc] == FILLED_CELL) {
                    count++;
                }
            }
        }
        return count;
    }

    private void markNeighborsAsFilled(int row, int col, char[][] reconstructed) {
        for (int dr = -1; dr <= 1; dr++) {
            for (int dc = -1; dc <= 1; dc++) {
                if (dr == 0 && dc == 0) continue;

                int nr = row + dr;
                int nc = col + dc;
                reconstructed[nr][nc] = FILLED_CELL;
            }
        }
    }

    private boolean areGridsIdentical(char[][] gridA, char[][] gridB) {
        int rows = gridA.length;
        int cols = gridA[0].length;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (gridA[i][j] != gridB[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }
}

/**
 * Main entry point of the application.
 */
public class Main {
    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        GridPatternSolver solver = new GridPatternSolver();

        try {
            String firstLine = reader.next();
            if (firstLine == null) return;

            // The logic expects N and M. 
            // Since FastReader.next() consumed the first integer, 
            // we need to handle the fact that nextInt() uses next().
            // However, to keep the interface clean, we'll adjust the logic 
            // to read N and M normally.

            // Re-implementing logic for reading N and M using the reader's next()
            // to avoid consuming the first integer manually.
            int rows = Integer.parseInt(firstLine);
            int cols = reader.nextInt();

            System.out.println(solver.solve(rows, cols, reader));
        } catch (Exception e) {
            // In a real application, use a logger.
            e.printStackTrace();
        }
    }
}

import java.util.Scanner;

/**
 * A solver that determines if all '#' cells in a grid can be covered 
 * by placing 3x3 "frames" (perimeters) around cells.
 */
public class FrameCoveringSolver {

    private static final char EMPTY_CELL = '.';
    private static final char OBSTACLE = '#';
    private static final char COVERED_CELL = '|';
    private static final int FRAME_SIZE = 3;
    private static final int CENTER_OFFSET = 1;

    private final int rows;
    private final int cols;
    private final char[][] grid;

    public FrameCoveringSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
    }

    /**
     * Executes the core algorithm: tries to place frames to cover all obstacles.
     * @return true if all obstacles are covered, false otherwise.
     */
    public boolean solve() {
        // Iterate through the grid to find potential centers for the 3x3 frames.
        // A center (i, j) must have at least one neighbor in every direction.
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                // The top-left corner of a 3x3 area centered at (i, j) is (i-1, j-1)
                int topLeftRow = i - CENTER_OFFSET;
                int topLeftCol = j - CENTER_OFFSET;

                if (isFrameValid(topLeftRow, topLeftCol)) {
                    applyFrame(topLeftRow, topLeftCol);
                }
            }
        }

        return !hasRemainingObstacles();
    }

    /**
     * Checks if a 3x3 frame can be placed with the given top-left corner.
     * A frame can be placed if none of the perimeter cells are empty ('.').
     */
    private boolean isFrameValid(int startRow, int startCol) {
        for (int i = 0; i < FRAME_SIZE; i++) {
            for (int j = 0; j < FRAME_SIZE; j++) {
                // Skip the center cell of the 3x3 area
                if (i == CENTER_OFFSET && j == CENTER_OFFSET) {
                    continue;
                }
                if (grid[startRow + i][startCol + j] == EMPTY_CELL) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Marks the perimeter of the 3x3 area as covered.
     */
    private void applyFrame(int startRow, int startCol) {
        for (int i = 0; i < FRAME_SIZE; i++) {
            for (int j = 0; j < FRAME_SIZE; j++) {
                if (i == CENTER_OFFSET && j == CENTER_OFFSET) {
                    continue;
                }
                grid[startRow + i][startCol + j] = COVERED_CELL;
            }
        }
    }

    /**
     * Scans the grid to see if any '#' obstacles remain uncovered.
     */
    private boolean hasRemainingObstacles() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == OBSTACLE) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Main entry point for the application.
     */
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String rowInput = scanner.next();
            for (int j = 0; j < m; j++) {
                grid[i][j] = rowInput.charAt(j);
            }
        }

        FrameCoveringSolver solver = new FrameCoveringSolver(n, m, grid);

        if (solver.solve()) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }
}

import java.io.BufferedReader;
