/**
 * A utility to validate if a grid pattern matches a specific 
 * configuration based on 3x3 neighbor rules.
 */
public class GridPatternMatcher {

    public static void main(String[] args) {
        new GridPatternMatcher().execute();
    }

    /**
     * Orchestrates the input reading, pattern processing, and output.
     */
    public void execute() {
        FastReader reader = new FastReader();
        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            boolean[][] grid = new boolean[rows][cols];
            for (int r = 0; r < rows; r++) {
                String line = reader.nextLine();
                for (int c = 0; c < cols; c++) {
                    if (c < line.length() && line.charAt(c) == '#') {
                        grid[r][c] = true;
                    }
                }
            }

            boolean[][] coverageGrid = processPattern(grid, rows, cols);

            if (isMatching(grid, coverageGrid)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }

        } catch (IOException | RuntimeException e) {
            // Maintaining the original behavior of printing NO on input errors
            System.out.println("NO");
        }
    }

    /**
     * Processes the grid to find cells that are part of a valid 3x3 neighbor set.
     * 
     * @param grid The original input grid.
     * @param rows Number of rows.
     * @param cols Number of columns.
     * @return A grid representing the coverage of the pattern.
     */
    private boolean[][] processPattern(boolean[][] grid, int rows, int cols) {
        boolean[][] coverageGrid = new boolean[rows][cols];

        // The original logic skips the boundary cells for the "center" check
        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < cols - 1; c++) {
                if (hasAllNeighborsPresent(grid, r, c)) {
                    markNeighbors(coverageGrid, r, c);
                }
            }
        }
        return coverageGrid;
    }

    /**
     * Checks if all 8 neighbors of a given cell are '#' (true).
     */
    private boolean hasAllNeighborsPresent(boolean[][] grid, int r, int c) {
        for (int dr = -1; dr <= 1; dr++) {
            for (int dc = -1; dc <= 1; dc++) {
                if (dr == 0 && dc == 0) {
                    continue; // Skip the center cell itself
                }
                if (!grid[r + dr][c + dc]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Marks the 8 neighbors of a cell as true in the coverage grid.
     */
    private void markNeighbors(boolean[][] coverageGrid, int r, int c) {
        for (int dr = -1; dr <= 1; dr++) {
            for (int dc = -1; dc <= 1; dc++) {
                if (dr == 0 && dc == 0) {
                    continue; // Skip the center cell itself
                }
                coverageGrid[r + dr][c + dc] = true;
            }
        }
    }

    /**
     * Compares the original grid with the generated coverage grid.
     */
    private boolean isMatching(boolean[][] grid, boolean[][] coverageGrid) {
        int rows = grid.length;
        int cols = grid[0].length;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] != coverageGrid[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Fast I/O helper class for efficient reading.
     */
    private static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader() {
            this.reader = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line.trim());
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public String nextLine() throws IOException {
            return reader.readLine();
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * GridAnalyzer solves a specific grid-based pattern problem.
 * It identifies if any '#' cells are "trapped" by being surrounded 
 * by boundary edges or cells adjacent to '.' cells.
 */
public class GridAnalyzer {

    public static void main(String[] args) {
        new GridAnalyzer().solve();
    }

    /**
     * Orchestrates the input reading and problem-solving process.
     */
    public void solve() {
        FastReader reader = new FastReader();

        int rows = reader.nextInt();
        int cols = reader.nextInt();

        // Using 1-based indexing for the grid to match original logic 
        // and simplify neighbor checking with padding.
        char[][] grid = new char[rows + 2][cols + 2];
        int hashCount = 0;

        for (int i = 1; i <= rows; i++) {
            String line = reader.next();
            for (int j = 1; j <= cols; j++) {
                grid[i][j] = line.charAt(j - 1);
                if (grid[i][j] == '#') {
                    hashCount++;
                }
            }
        }

        if (hashCount == rows * cols) {
            // Special case: if the entire grid is '#', 
            // only a 3x3 grid is considered "NO".
            if (rows == 3 && cols == 3) {
                System.out.println("NO");
            } else {
                System.out.println("YES");
            }
        } else {
            if (hasTrappedHash(grid, rows, cols)) {
                System.out.println("NO");
            } else {
                System.out.println("YES");
            }
        }
    }

    /**
     * Determines if any '#' cell in the grid is surrounded entirely by 
     * safe cells (boundary or neighbors of '.').
     */
    private boolean hasTrappedHash(char[][] grid, int rows, int cols) {
        boolean[][] isSafe = initializeSafetyMap(grid, rows, cols);

        for (int i = 1; i <= rows; i++) {
            for (int j = 1; j <= cols; j++) {
                if (grid[i][j] == '#') {
                    if (isCellTrapped(i, j, isSafe)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Creates a safety map where a cell is 'true' if it is on the grid boundary
     * or adjacent to a '.' cell.
     */
    private boolean[][] initializeSafetyMap(char[][] grid, int rows, int cols) {
        boolean[][] isSafe = new boolean[rows + 2][cols + 2];

        // 1. Mark the external padding as safe
        for (int i = 0; i < rows + 2; i++) {
            isSafe[i][0] = true;
            isSafe[i][cols + 1] = true;
        }
        for (int j = 0; j < cols + 2; j++) {
            isSafe[0][j] = true;
            isSafe[rows + 1][j] = true;
        }

        // 2. Mark the grid boundaries as safe
        for (int i = 1; i <= rows; i++) {
            isSafe[i][1] = true;
            isSafe[i][cols] = true;
        }
        for (int j = 1; j <= cols; j++) {
            isSafe[1][j] = true;
            isSafe[rows][j] = true;
        }

        // 3. Mark neighbors of '.' cells as safe
        for (int i = 1; i <= rows; i++) {
            for (int j = 1; j <= cols; j++) {
                if (grid[i][j] == '.') {
                    markNeighborsSafe(i, j, isSafe);
                }
            }
        }
        return isSafe;
    }

    private void markNeighborsSafe(int r, int c, boolean[][] isSafe) {
        for (int dr = -1; dr <= 1; dr++) {
            for (int dc = -1; dc <= 1; dc++) {
                if (dr == 0 && dc == 0) continue;
                isSafe[r + dr][c + dc] = true;
            }
        }
    }

    /**
     * A cell is trapped if all its 8 neighbors in the safety map are marked true.
     */
    private boolean isCellTrapped(int r, int c, boolean[][] isSafe) {
        for (int dr = -1; dr <= 1; dr++) {
            for (int dc = -1; dc <= 1; dc++) {
                if (dr == 0 && dc == 0) continue;
                if (!isSafe[r + dr][c + dc]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Utility class for fast input reading.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A validator that checks if all non-empty cells in a grid belong to the 
 * perimeter of at least one "complete" 3x3 block.
 * 
 * A 3x3 block is considered "complete" if all its 8 perimeter cells 
 * are non-empty (not '.'). The center cell of such a block can be anything.
 */
public class GridPatternValidator {

    private final char[][] grid;
    private final int rows;
    private final int cols;

    public GridPatternValidator(char[][] grid) {
        this.grid = grid;
        this.rows = grid.length;
        this.cols = grid[0].length;
    }

    /**
     * Checks if a 3x3 block starting at the given top-left coordinates 
     * has a perimeter consisting entirely of non-'.' characters.
     *
     * @param startRow The starting row index of the 3x3 block.
     * @param startCol The starting column index of the 3x3 block.
     * @return true if the perimeter is complete, false otherwise.
     */
    private boolean isBlockPerimeterComplete(int startRow, int startCol) {
        // Boundary check for the 3x3 block
        if (startRow < 0 || startCol < 0 || startRow + 2 >= rows || startCol + 2 >= cols) {
            return false;
        }

        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                // Skip the center cell of the 3x3 block
                if (i == 1 && j == 1) {
                    continue;
                }

                if (grid[startRow + i][startCol + j] == '.') {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Determines if a cell is "covered" by being part of a perimeter 
     * of a complete 3x3 block.
     * 
     * Note: Based on the original logic, a cell is only considered covered 
     * if it is part of the perimeter of a block. If a cell is the center 
     * of a complete block, it does not count as being covered by that block.
     *
     * @param r The row index of the cell.
     * @param c The column index of the cell.
     * @return true if the cell is on the perimeter of a complete block.
     */
    private boolean isCellCovered(int r, int c) {
        // A cell (r, c) can be any of the 8 perimeter positions for several 3x3 blocks.
        // We iterate through all possible top-left corners that could form a block containing (r, c).
        for (int startRow = r - 2; startRow <= r; startRow++) {
            for (int startCol = c - 2; startCol <= c; startCol++) {

                // Skip the case where (r, c) is the center of the current 3x3 block.
                // The original algorithm specifically excludes the center cell from 
                // being covered by its own block.
                if (r == startRow + 1 && c == startCol + 1) {
                    continue;
                }

                if (isBlockPerimeterComplete(startRow, startCol)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Validates the entire grid.
     * 
     * @return true if every non-'.' cell is covered, false otherwise.
     */
    public boolean validate() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] != '.' && !isCellCovered(r, c)) {
                    return false;
                }
            }
        }
        return true;
    }

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        try {
            String nStr = reader.next();
            if (nStr == null) return;
            int n = Integer.parseInt(nStr);

            int m = reader.nextInt();
            char[][] grid = new char[n][m];

            for (int i = 0; i < n; i++) {
                grid[i] = reader.next().toCharArray();
            }

            GridPatternValidator validator = new GridPatternValidator(grid);
            System.out.println(validator.validate() ? "YES" : "NO");

        } catch (IOException | NumberFormatException e) {
            // In a production environment, use a logger
            e.printStackTrace();
        }
    }

    /**
     * Utility class for fast I/O operations.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

/**
 * This program validates if all '#' characters in a grid are part of 
 * the perimeter of 3x3 "hollow square" patterns.
 */
public class Solution {

    // Relative coordinates for the 8 cells forming the perimeter of a 3x3 square.
    // Note: The center cell (1, 1) is intentionally omitted.
    private static final int[][] PATTERN_OFFSETS = {
        {0, 0}, {0, 1}, {0, 2},
        {1, 0},         {1, 2},
        {2, 0}, {2, 1}, {2, 2}
    };

    private static final char TARGET_CHAR = '#';
    private static final char EMPTY_CHAR = '.';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        boolean[][] grid = readGrid(scanner, rows, cols);
        boolean[][] isCovered = new boolean[rows][cols];

        findAndMarkPatterns(grid, isCovered, rows, cols);

        if (isAllHashesCovered(grid, isCovered, rows, cols)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Reads the grid from standard input.
     */
    private static boolean[][] readGrid(Scanner scanner, int rows, int cols) {
        boolean[][] grid = new boolean[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = (line.charAt(j) == TARGET_CHAR);
            }
        }
        return grid;
    }

    /**
     * Iterates through the grid to find 3x3 hollow patterns and marks them as covered.
     */
    private static void findAndMarkPatterns(boolean[][] grid, boolean[][] isCovered, int rows, int cols) {
        // A 3x3 pattern can only start if there are at least 2 more rows and columns available.
        for (int r = 0; r <= rows - 3; r++) {
            for (int c = 0; c <= cols - 3; c++) {
                if (isPatternAt(grid, r, c)) {
                    markPatternAsCovered(isCovered, r, c);
                }
            }
        }
    }

    /**
     * Checks if the 3x3 area starting at (startRow, startCol) matches the hollow square pattern.
     */
    private static boolean isPatternAt(boolean[][] grid, int startRow, int startCol) {
        for (int[] offset : PATTERN_OFFSETS) {
            int targetR = startRow + offset[0];
            int targetC = startCol + offset[1];
            if (!grid[targetR][targetC]) {
                return false;
            }
        }
        return true;
    }

    /**
     * Marks the cells of a detected pattern as covered.
     */
    private static void markPatternAsCovered(boolean[][] isCovered, int startRow, int startCol) {
        for (int[] offset : PATTERN_OFFSETS) {
            isCovered[startRow + offset[0]][startCol + offset[1]] = true;
        }
    }

    /**
     * Ensures that every '#' cell in the grid has been marked as covered.
     */
    private static boolean isAllHashesCovered(boolean[][] grid, boolean[][] isCovered, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                // If the cell is a '#' but was not part of any pattern perimeter, validation fails.
                if (grid[r][c] && !isCovered[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }
}

