/**
 * Contains the logic for solving the grid coverage problem.
 */
class GridSolver {
    // Cell state constants to replace magic numbers
    private static final int EMPTY = 0;
    private static final int COVERED = 1;
    private static final int TARGET = 2;

    /**
     * Processes the grid and determines if all '#' cells can be covered by rings.
     * 
     * @param in  The input reader
     * @param out The output writer
     * @throws IOException if an I/O error occurs
     */
    public void solve(FastReader in, FastWriter out) throws IOException {
        int rows = in.nextInt();
        int cols = in.nextInt();

        int[][] grid = new int[rows][cols];

        // Initialize the grid
        for (int i = 0; i < rows; i++) {
            String line = in.next();
            for (int j = 0; j < cols; j++) {
                if (line.charAt(j) == '#') {
                    grid[i][j] = TARGET;
                } else {
                    grid[i][j] = EMPTY;
                }
            }
        }

        // Greedy algorithm: attempt to place rings starting from each non-empty cell
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] > EMPTY && canPlaceRing(grid, i, j, rows, cols)) {
                    applyRing(grid, i, j);
                }
            }
        }

        // Final check: are there any uncovered targets left?
        boolean allCovered = true;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == TARGET) {
                    allCovered = false;
                    break;
                }
            }
            if (!allCovered) break;
        }

        out.println(allCovered ? "YES" : "NO");
    }

    /**
     * Checks if a 3x3 ring (excluding the center) can be placed with 
     * (top, left) at (row, col).
     */
    private boolean canPlaceRing(int[][] grid, int row, int col, int rows, int cols) {
        // Check bounds for a 3x3 area
        if (row + 2 >= rows || col + 2 >= cols) {
            return false;
        }

        // Check if all 8 cells in the ring are not EMPTY
        for (int r = row; r < row + 3; r++) {
            for (int c = col; c < col + 3; c++) {
                // Skip the center cell of the 3x3 area
                if (r == row + 1 && c == col + 1) {
                    continue;
                }

                if (grid[r][c] == EMPTY) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Marks the 8 cells of the 3x3 ring as COVERED.
     */
    private void applyRing(int[][] grid, int row, int col) {
        for (int r = row; r < row + 3; r++) {
            for (int c = col; c < col + 3; c++) {
                if (r == row + 1 && c == col + 1) {
                    continue;
                }
                grid[r][c] = COVERED;
            }
        }
    }
}

