/**
 * This program verifies if a given grid of characters consists exactly 
 * of the union of all possible 3x3 hollow square patterns.
 */
public class Duel1 {

    public static void main(String[] args) {
        try {
            FastReader reader = new FastReader(System.in);

            int rows = reader.nextInt();
            int cols = reader.nextInt();

            boolean[][] grid = new boolean[rows][cols];
            for (int i = 0; i < rows; i++) {
                char[] rowChars = reader.next().toCharArray();
                for (int j = 0; j < cols; j++) {
                    // We treat '#' as true and any other character as false
                    grid[i][j] = (rowChars[j] == '#');
                }
            }

            PatternAnalyzer analyzer = new PatternAnalyzer(grid);
            if (analyzer.isGridConsistentWithPatterns()) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }

        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Logic component responsible for analyzing grid patterns.
     */
    static class PatternAnalyzer {
        private static final int PATTERN_SIZE = 3;
        private final boolean[][] grid;
        private final int rows;
        private final int cols;

        public PatternAnalyzer(boolean[][] grid) {
            this.grid = grid;
            this.rows = grid.length;
            this.cols = grid[0].length;
        }

        /**
         * Checks if the grid is composed exactly of all possible 3x3 hollow square patterns.
         */
        public boolean isGridConsistentWithPatterns() {
            boolean[][] patternOverlay = new boolean[rows][cols];

            // Step 1: Identify all valid 3x3 hollow squares and mark them on an overlay grid
            for (int i = 0; i <= rows - PATTERN_SIZE; i++) {
                for (int j = 0; j <= cols - PATTERN_SIZE; j++) {
                    if (isValidPattern(i, j)) {
                        markPattern(patternOverlay, i, j);
                    }
                }
            }

            // Step 2: Compare the overlay (what should be #) with the actual grid
            return compareGrids(grid, patternOverlay);
        }

        /**
         * Validates if a 3x3 hollow square exists starting at (startRow, startCol).
         */
        private boolean isValidPattern(int startRow, int startCol) {
            for (int k = 0; k < PATTERN_SIZE; k++) {
                // Check the four sides of the 3x3 square
                if (!grid[startRow][startCol + k]) return false;             // Top edge
                if (!grid[startRow + k][startCol]) return false;             // Left edge
                if (!grid[startRow + PATTERN_SIZE - 1][startCol + k]) return false; // Bottom edge
                if (!grid[startRow + k][startCol + PATTERN_SIZE - 1]) return false; // Right edge
            }
            return true;
        }

        /**
         * Marks the cells of a 3x3 hollow square on the provided overlay grid.
         */
        private void markPattern(boolean[][] overlay, int startRow, int startCol) {
            for (int k = 0; k < PATTERN_SIZE; k++) {
                overlay[startRow][startCol + k] = true;
                overlay[startRow + k][startCol] = true;
                overlay[startRow + PATTERN_SIZE - 1][startCol + k] = true;
                overlay[startRow + k][startCol + PATTERN_SIZE - 1] = true;
            }
        }

        /**
         * Returns true if the two grids are identical.
         */
        private boolean compareGrids(boolean[][] grid1, boolean[][] grid2) {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid1[i][j] != grid2[i][j]) {
                        return false;
                    }
                }
            }
            return true;
        }
    }

    /**
     * Utility class for fast I/O operations.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) {
                    throw new IOException("Unexpected end of input");
                }
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        public double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }
}

