/**
 * A solver for the grid coverage problem.
 * The logic determines if every '#' in a grid is "covered" by being 
 * a neighbor of a 3x3 block of '#' (excluding the center of that block).
 */
public class GridProblemSolver {

    private static final int[] DIRECTION_X = {0, 0, 1, 1, 1, -1, -1, -1};
    private static final int[] DIRECTION_Y = {1, -1, 0, 1, -1, 0, 1, -1};

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        try (PrintWriter out = new PrintWriter(System.out)) {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            boolean result = solve(grid, rows, cols);
            out.println(result ? "YES" : "NO");
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * Core logic to determine if the grid satisfies the coverage condition.
     */
    private static boolean solve(char[][] grid, int rows, int cols) {
        boolean[][] isCovered = new boolean[rows][cols];

        // Iterate through internal cells that can act as the center of a 3x3 block
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (isAllNeighborsHash(grid, i, j, rows, cols)) {
                    markNeighborsAsCovered(isCovered, i, j);
                }
            }
        }

        return validateAllHashesAreCovered(grid, isCovered, rows, cols);
    }

    /**
     * Checks if all 8 neighbors of a specific cell are '#'.
     */
    private static boolean isAllNeighborsHash(char[][] grid, int r, int c, int rows, int cols) {
        for (int k = 0; k < 8; k++) {
            int nr = r + DIRECTION_X[k];
            int nc = c + DIRECTION_Y[k];

            // Safety check for bounds and character verification
            if (nr < 0 || nr >= rows || nc < 0 || nc >= cols || grid[nr][nc] == '.') {
                return false;
            }
        }
        return true;
    }

    /**
     * Marks the 8 neighbors of a cell as covered.
     */
    private static void markNeighborsAsCovered(boolean[][] isCovered, int r, int c) {
        for (int k = 0; k < 8; k++) {
            int nr = r + DIRECTION_X[k];
            int nc = c + DIRECTION_Y[k];
            isCovered[nr][nc] = true;
        }
    }

    /**
     * Ensures that every '#' cell in the grid has been marked as covered.
     */
    private static boolean validateAllHashesAreCovered(char[][] grid, boolean[][] isCovered, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '#' && !isCovered[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

