/**
 * A solver that determines if a grid pattern can be perfectly formed 
 * by placing 3x3 "rings" of '#' characters around a center cell.
 */
public class GridRingPatternMatcher {

    private static final char RING_CHARACTER = '#';
    private static final char EMPTY_CHARACTER = '.';
    private static final int RING_SIZE = 3;
    private static final int CENTER_OFFSET = 1;

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        try {
            String rowsStr = reader.next();
            if (rowsStr == null) return;

            int rows = Integer.parseInt(rowsStr);
            int cols = reader.nextInt();

            char[][] inputGrid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                inputGrid[i] = reader.next().toCharArray();
            }

            if (isPatternValid(rows, cols, inputGrid)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        } catch (Exception e) {
            // In a production environment, use a proper logging framework.
            System.err.println("Error processing input: " + e.getMessage());
        }
    }

    /**
     * Core logic to verify if the input grid matches the reconstructed grid.
     * 
     * @param rows Number of rows in the grid.
     * @param cols Number of columns in the grid.
     * @param inputGrid The grid provided by the user.
     * @return true if the grid can be perfectly reconstructed by 3x3 rings.
     */
    private static boolean isPatternValid(int rows, int cols, char[][] inputGrid) {
        char[][] reconstructedGrid = new char[rows][cols];

        // Initialize the reconstructed grid with empty characters
        for (int i = 0; i < rows; i++) {
            Arrays.fill(reconstructedGrid[i], EMPTY_CHARACTER);
        }

        // Scan the grid for every possible 3x3 window top-left corner
        for (int r = 0; r <= rows - RING_SIZE; r++) {
            for (int c = 0; c <= cols - RING_SIZE; c++) {
                if (canPlaceRingAt(r, c, inputGrid)) {
                    fillRingAt(r, c, reconstructedGrid);
                }
            }
        }

        return areGridsIdentical(inputGrid, reconstructedGrid, rows, cols);
    }

    /**
     * Checks if a 3x3 ring can be placed at the given coordinates.
     * A ring is valid if none of its perimeter cells contain the empty character.
     */
    private static boolean canPlaceRingAt(int startRow, int startCol, char[][] inputGrid) {
        for (int i = 0; i < RING_SIZE; i++) {
            for (int j = 0; j < RING_SIZE; j++) {
                // Skip the center cell of the 3x3 block
                if (i == CENTER_OFFSET && j == CENTER_OFFSET) {
                    continue;
                }
                if (inputGrid[startRow + i][startCol + j] == EMPTY_CHARACTER) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Fills the perimeter of a 3x3 area in the target grid with the ring character.
     */
    private static void fillRingAt(int startRow, int startCol, char[][] targetGrid) {
        for (int i = 0; i < RING_SIZE; i++) {
            for (int j = 0; j < RING_SIZE; j++) {
                // Skip the center cell of the 3x3 block
                if (i == CENTER_OFFSET && j == CENTER_OFFSET) {
                    continue;
                }
                targetGrid[startRow + i][startCol + j] = RING_CHARACTER;
            }
        }
    }

    /**
     * Compares two 2D character arrays for equality.
     */
    private static boolean areGridsIdentical(char[][] grid1, char[][] grid2, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid1[i][j] != grid2[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Fast I/O utility for efficient reading of large input datasets.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            return next != null ? Integer.parseInt(next) : 0;
        }
    }
}

