/**
 * A program to verify if a grid pattern can be perfectly reconstructed 
 * using overlapping 3x3 'frames' (a 3x3 block of '#' with a '.' in the center).
 */
public class Main {

    public static void main(String[] args) {
        // Using try-with-resources for automatic resource management
        try (FastReader reader = new FastReader(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            PatternSolver solver = new PatternSolver();
            solver.solve(reader, out);

            out.flush();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * Contains the core logic for solving the grid pattern problem.
     */
    static class PatternSolver {

        /**
         * Reads input, processes the grid, and writes the result.
         * 
         * @param in FastReader for optimized input reading
         * @param out PrintWriter for optimized output writing
         */
        public void solve(FastReader in, PrintWriter out) {
            int rows = in.nextInt();
            int cols = in.nextInt();

            if (rows <= 0 || cols <= 0) {
                out.println("YES");
                return;
            }

            char[][] inputGrid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                inputGrid[i] = in.next().toCharArray();
            }

            char[][] reconstructedGrid = createEmptyGrid(rows, cols);

            // Scan the grid for all possible 3x3 frame starting positions
            for (int i = 0; i <= rows - 3; i++) {
                for (int j = 0; j <= cols - 3; j++) {
                    if (isFrameAt(inputGrid, i, j)) {
                        applyFrame(reconstructedGrid, i, j);
                    }
                }
            }

            // Determine if the reconstructed grid matches the original input exactly
            if (isMatch(inputGrid, reconstructedGrid)) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        }

        private char[][] createEmptyGrid(int rows, int cols) {
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                Arrays.fill(grid[i], '.');
            }
            return grid;
        }

        /**
         * Checks if a 3x3 block starting at (r, c) forms a valid frame.
         * A valid frame has '#' on its perimeter and can have anything in the center.
         */
        private boolean isFrameAt(char[][] grid, int r, int c) {
            for (int i = 0; i < 3; i++) {
                for (int j = 0; j < 3; j++) {
                    // The center of a 3x3 frame is at relative offset (1, 1)
                    if (i == 1 && j == 1) {
                        continue;
                    }
                    if (grid[r + i][c + j] != '#') {
                        return false;
                    }
                }
            }
            return true;
        }

        /**
         * Marks the perimeter of a 3x3 block starting at (r, c) with '#'.
         */
        private void applyFrame(char[][] grid, int r, int c) {
            for (int i = 0; i < 3; i++) {
                for (int j = 0; j < 3; j++) {
                    if (i == 1 && j == 1) {
                        continue;
                    }
                    grid[r + i][c + j] = '#';
                }
            }
        }

        private boolean isMatch(char[][] grid1, char[][] grid2) {
            for (int i = 0; i < grid1.length; i++) {
                for (int j = 0; j < grid1[0].length; j++) {
                    if (grid1[i][j] != grid2[i][j]) {
                        return false;
                    }
                }
            }
            return true;
        }
    }

    /**
     * High-performance input reader for handling large datasets efficiently.
     */
    static class FastReader implements AutoCloseable {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int pointer = 0;
        private int bufferLength = 0;

        public FastReader(InputStream in) {
            this.in = in;
        }

        private int readByte() {
            if (pointer >= bufferLength) {
                pointer = 0;
                try {
                    bufferLength = in.read(buffer);
                } catch (IOException e) {
                    return -1;
                }
                if (bufferLength <= 0) return -1;
            }
            return buffer[pointer++] & 0xFF;
        }

        public int nextInt() {
            int c = readByte();
            while (c != -1 && c <= 32) c = readByte();
            if (c == -1) return 0;

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }

            int res = 0;
            while (c >= '0' && c <= '9') {
                res = res * 10 + (c - '0');
                c = readByte();
            }
            return res * sign;
        }

        public String next() {
            int c = readByte();
            while (c != -1 && c <= 32) c = readByte();
            if (c == -1) return "";

            StringBuilder sb = new StringBuilder();
            while (c > 32) {
                sb.append((char) c);
                c = readByte();
            }
            return sb.toString();
        }

        @Override
        public void close() throws IOException {
            in.close();
        }
    }
}

