/**
 * Solves the problem of constructing a symmetric matrix given a set of integers.
 * The symmetry required is: matrix[i][j] = matrix[n-1-i][j] = matrix[i][n-1-j] = matrix[n-1-i][n-1-j].
 */
public class ProblemC {

    public static void main(String[] args) throws IOException {
        FastReader sc = new FastReader(System.in);
        PrintWriter pw = new PrintWriter(System.out);

        int n = sc.nextInt();
        Map<Integer, Integer> counts = new HashMap<>();
        for (int i = 0; i < n * n; i++) {
            int val = sc.nextInt();
            counts.put(val, counts.getOrDefault(val, 0) + 1);
        }

        SymmetrySolver solver = new SymmetrySolver(n, counts);
        solver.solve(pw);

        pw.flush();
        pw.close();
    }

    static class SymmetrySolver {
        private final int n;
        private final Map<Integer, Integer> counts;

        public SymmetrySolver(int n, Map<Integer, Integer> counts) {
            this.n = n;
            this.counts = counts;
        }

        public void solve(PrintWriter pw) {
            int[][] matrix = new int[n][n];

            if (n % 2 == 0) {
                if (!tryFillEvenMatrix(matrix)) {
                    pw.println("NO");
                    return;
                }
            } else {
                if (!tryFillOddMatrix(matrix)) {
                    pw.println("NO");
                    return;
                }
            }

            pw.println("YES");
            printMatrix(matrix, pw);
        }

        private boolean tryFillEvenMatrix(int[][] matrix) {
            Deque<Integer> quads = new ArrayDeque<>();
            for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
                int val = entry.getKey();
                int count = entry.getValue();
                if (count % 4 != 0) return false;
                for (int i = 0; i < count / 4; i++) {
                    quads.add(val);
                }
            }
            fillCorners(matrix, quads);
            return true;
        }

        private boolean tryFillOddMatrix(int[][] matrix) {
            int centerVal = -1;
            List<Integer> mandatoryPairs = new ArrayList<>();
            Deque<Integer> quadValues = new ArrayDeque<>();

            for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
                int val = entry.getKey();
                int count = entry.getValue();
                int remCount = count;

                // Rule: One number can be the center (count % 4 is 1 or 3)
                if (count % 4 == 1 || count % 4 == 3) {
                    if (centerVal != -1) return false;
                    centerVal = val;
                    remCount -= 1;
                }

                // Rule: Remaining counts must be multiples of 2 or 4
                if (remCount % 4 == 2) {
                    mandatoryPairs.add(val);
                    remCount -= 2;
                }

                for (int i = 0; i < remCount / 4; i++) {
                    quadValues.add(val);
                }
            }

            if (centerVal == -1) return false;

            // For odd N, the middle row/col needs (N-1) pairs.
            // Mandatory pairs must be even to allow symmetric distribution.
            int requiredPairs = n - 1;
            if (mandatoryPairs.size() > requiredPairs || (requiredPairs - mandatoryPairs.size()) % 2 != 0) {
                return false;
            }

            int neededFromQuads = (requiredPairs - mandatoryPairs.size()) / 2;
            if (quadValues.size() < neededFromQuads) return false;

            matrix[n / 2][n / 2] = centerVal;

            // 1. Fill Middle Row/Col using quad-derived pairs
            List<Integer> rowPairs = new ArrayList<>();
            List<Integer> colPairs = new ArrayList<>();
            for (int i = 0; i < neededFromQuads; i++) {
                int val = quadValues.pollFirst();
                rowPairs.add(val);
                colPairs.add(val);
            }

            // 2. Distribute mandatory pairs between row and column
            int half = mandatoryPairs.size() / 2;
            for (int i = 0; i < half; i++) rowPairs.add(mandatoryPairs.get(i));
            for (int i = half; i < mandatoryPairs.size(); i++) colPairs.add(mandatoryPairs.get(i));

            // Fill middle row
            for (int i = 0; i < rowPairs.size(); i++) {
                int val = rowPairs.get(i);
                matrix[n / 2][i] = val;
                matrix[n / 2][n - 1 - i] = val;
            }
            // Fill middle col
            for (int i = 0; i < colPairs.size(); i++) {
                int val = colPairs.get(i);
                matrix[i][n / 2] = val;
                matrix[n - 1 - i][n / 2] = val;
            }

            // 3. Fill corners
            fillCorners(matrix, quadValues);
            return true;
        }

        private void fillCorners(int[][] matrix, Deque<Integer> quads) {
            int n = matrix.length;
            for (int i = 0; i < n / 2; i++) {
                for (int j = 0; j < n / 2; j++) {
                    // Skip cells already filled by middle row/col (for odd N)
                    if (matrix[i][j] != 0 || matrix[i][n - 1 - j] != 0) continue;

                    if (quads.isEmpty()) return; 
                    int val = quads.pollFirst();
                    matrix[i][j] = val;
                    matrix[n - 1 - i][j] = val;
                    matrix[i][n - 1 - j] = val;
                    matrix[n - 1 - i][n - 1 - j] = val;
                }
            }
        }

        private void printMatrix(int[][] matrix, PrintWriter pw) {
            for (int[] row : matrix) {
                for (int j = 0; j < row.length; j++) {
                    pw.print(row[j] + (j == row.length - 1 ? "" : " "));
                }
                pw.println();
            }
        }
    }

    static class FastReader {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int pointer = 0;
        private int bytesRead = 0;

        public FastReader(InputStream in) {
            this.in = in;
        }

        public int nextInt() throws IOException {
            int ret = 0;
            byte c = read();
            while (c <= ' ') c = read();
            boolean neg = (c == '-');
            if (neg) c = read();
            do {
                ret = ret * 10 + c - '0';
            } while ((c = read()) >= '0' && c <= '9');
            return neg ? -ret : ret;
        }

        private byte read() throws IOException {
            if (pointer == bytesRead) fillBuffer();
            return buffer[pointer++];
        }

        private void fillBuffer() throws IOException {
            bytesRead = in.read(buffer, pointer = 0, buffer.length);
            if (bytesRead == -1) buffer[0] = -1;
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A program that attempts to arrange a given set of numbers into an n x n grid
 * such that the grid maintains 4-way symmetric properties.
 */
public class SymmetricGridConstructor {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            // Read the dimension of the grid
            int n = reader.nextInt();
            if (n < 0) return;

            int totalElements = n * n;
            TreeMap<Integer, Integer> frequencyMap = new TreeMap<>();

            // Count the occurrences of each number provided
            for (int i = 0; i < totalElements; i++) {
                int val = reader.nextInt();
                frequencyMap.put(val, frequencyMap.getOrDefault(val, 0) + 1);
            }

            // Solve the symmetry problem
            Solver solver = new Solver(n, frequencyMap);
            solver.solve();
            solver.printResult(writer);

        } catch (Exception e) {
            // Graceful handling of unexpected input issues
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Logic handler for the symmetric grid construction.
     */
    private static class Solver {
        private final int size;
        private final TreeMap<Integer, Integer> frequencyMap;
        private final int[][] grid;
        private boolean isPossible = true;

        public Solver(int size, TreeMap<Integer, Integer> frequencyMap) {
            this.size = size;
            this.frequencyMap = frequencyMap;
            this.grid = new int[size][size];
        }

        /**
         * Determines whether to use even-sized or odd-sized logic.
         */
        public void solve() {
            if (size % 2 == 0) {
                solveEvenSize();
            } else {
                solveOddSize();
            }
        }

        /**
         * Logic for even-sized grids where every number must appear in groups of 4.
         */
        private void solveEvenSize() {
            for (int count : frequencyMap.values()) {
                if (count % 4 != 0) {
                    isPossible = false;
                    return;
                }
            }

            for (int r = 0; r < size; r++) {
                for (int c = 0; c < size; c++) {
                    if (grid[r][c] != 0) continue;

                    int val = frequencyMap.firstKey();
                    fillSymmetricGroup(r, c, val);
                    decrementFrequency(val, 4);
                }
            }
        }

        /**
         * Logic for odd-sized grids where one number is at the center 
         * and others are placed in symmetric pairs or quadruplets.
         */
        private void solveOddSize() {
            int oddFrequencyCount = 0;
            int centerValue = -1;

            // A valid odd grid must have exactly one number with an odd frequency
            for (Map.Entry<Integer, Integer> entry : frequencyMap.entrySet()) {
                if (entry.getValue() % 2 != 0) {
                    oddFrequencyCount++;
                    centerValue = entry.getKey();
                }
            }

            if (oddFrequencyCount != 1) {
                isPossible = false;
                return;
            }

            // Place center element
            grid[size / 2][size / 2] = centerValue;
            decrementFrequency(centerValue, 1);

            // Identify elements that can form pairs for the middle cross (count % 4 == 2)
            TreeMap<Integer, Integer> crossPairsMap = new TreeMap<>();
            for (Map.Entry<Integer, Integer> entry : frequencyMap.entrySet()) {
                if (entry.getValue() % 4 == 2) {
                    crossPairsMap.put(entry.getKey(), entry.getValue());
                }
            }

            // Replicate the original constraints for the cross construction
            // We move the 'dv' elements from frequencyMap to a separate management map
            TreeMap<Integer, Integer> dv = new TreeMap<>(crossPairsMap);
            for (Integer key : dv.keySet()) {
                frequencyMap.remove(key);
            }

            if (dv.size() >= size || dv.size() % 2 != 0) {
                isPossible = false;
                return;
            }

            int mid = size / 2;

            // Fill middle column cross
            fillCross(mid, true, dv);
            // Fill middle row cross
            fillCross(mid, false, dv);

            // Fill the remaining cells in the grid using quadruplets
            for (int r = 0; r < size; r++) {
                for (int c = 0; c < size; c++) {
                    if (grid[r][c] != 0) continue;

                    int val = frequencyMap.firstKey();
                    fillSymmetricGroup(r, c, val);
                    decrementFrequency(val, 4);
                }
            }
        }

        private void fillCross(int mid, boolean isColumn, TreeMap<Integer, Integer> dv) {
            for (int i = 0; i < size; i++) {
                int r = isColumn ? i : mid;
                int c = isColumn ? mid : i;

                if (grid[r][c] != 0) continue;

                if (dv.isEmpty()) {
                    int firstKey = frequencyMap.firstKey();
                    dv.put(firstKey, frequencyMap.get(firstKey));
                }

                int val = dv.firstKey();
                // Symmetrically fill the cross
                if (isColumn) {
                    grid[r][c] = grid[size - r - 1][c] = grid[r][size - mid - 1] = grid[size - r - 1][size - mid - 1] = val;
                } else {
                    grid[r][c] = grid[r][size - c - 1] = grid[size - mid - 1][c] = grid[size - mid - 1][size - c - 1] = val;
                }

                // Update the management map
                if (dv.get(val) % 4 == 0) {
                    dv.put(val, dv.get(val) - 2);
                    if (dv.get(val) == 0) dv.remove(val);
                } else {
                    int remaining = dv.get(val) - 2;
                    if (remaining > 0) frequencyMap.put(val, remaining);
                    dv.remove(val);
                }
            }
        }

        private void fillSymmetricGroup(int r, int c, int val) {
            grid[r][c] = grid[size - r - 1][c] = grid[r][size - c - 1] = grid[size - r - 1][size - c - 1] = val;
        }

        private void decrementFrequency(int val, int amount) {
            int current = frequencyMap.get(val);
            if (current == amount) {
                frequencyMap.remove(val);
            } else {
                frequencyMap.put(val, current - amount);
            }
        }

        public void printResult(PrintWriter writer) {
            if (!isPossible) {
                writer.println("NO");
            } else {
                writer.println("YES");
                for (int r = 0; r < size; r++) {
                    for (int c = 0; c < size; c++) {
                        writer.print(grid[r][c] + (c == size - 1 ? "" : " "));
                    }
                    writer.println();
                }
            }
        }
    }

    /**
     * Fast I/O utility for efficient reading.
     */
    private static class FastReader {
        private final InputStream in;
        private final byte[] buffer = new byte[1024];
        private int pointer = 0;
        private int bufferLength = 0;

        public FastReader(InputStream in) {
            this.in = in;
        }

        private int readByte() {
            if (pointer >= bufferLength) {
                pointer = 0;
                try {
                    bufferLength = in.read(buffer);
                } catch (IOException e) {
                    return -1;
                }
                if (bufferLength <= 0) return -1;
            }
            return buffer[pointer++];
        }

        public int nextInt() {
            int b = skipSpaces();
            if (b == -1) return -1;
            boolean negative = false;
            if (b == '-') {
                negative = true;
                b = readByte();
            }
            int res = 0;
            while (b >= '0' && b <= '9') {
                res = res * 10 + (b - '0');
                b = readByte();
            }
            return negative ? -res : res;
        }

        private int skipSpaces() {
            int b = readByte();
            while (b != -1 && b <= 32) {
                b = readByte();
            }
            return b;
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A utility class for high-performance input reading.
 */
class FastReader {
    private final InputStream inputStream;
    private final byte[] buffer = new byte[1024];
    private int currentChar;
    private int numChars;

    public FastReader(InputStream is) {
        this.inputStream = is;
    }

    public FastReader() {
        this(System.in);
    }

    private int read() {
        if (numChars == -1) throw new NoSuchElementException();
        if (currentChar >= numChars) {
            currentChar = 0;
            try {
                numChars = inputStream.read(buffer);
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
            if (numChars <= 0) return -1;
        }
        return buffer[currentChar++];
    }

    public int nextInt() {
        int c = read();
        while (isSpaceChar(c)) c = read();
        int sign = 1;
        if (c == '-') {
            sign = -1;
            c = read();
        }
        int res = 0;
        do {
            if (c < '0' || c > '9') throw new InputMismatchException();
            res *= 10;
            res += c - '0';
            c = read();
        } while (!isSpaceChar(c));
        return res * sign;
    }

    public int[] nextIntArray(int n) {
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = nextInt();
        }
        return arr;
    }

    private boolean isSpaceChar(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }
}

/**
 * Represents the outcome of the matrix construction process.
 */
class ConstructionResult {
    private final boolean success;
    private final int[][] matrix;

    public ConstructionResult(boolean success, int[][] matrix) {
        this.success = success;
        this.matrix = matrix;
    }

    public boolean isSuccess() { return success; }
    public int[][] getMatrix() { return matrix; }
}

/**
 * Logic for constructing an n x n matrix with rotational symmetry.
 */
class MatrixSymmetrySolver {
    private final int n;
    private final Map<Integer, Integer> frequencyMap;
    private final int[][] matrix;

    public MatrixSymmetrySolver(int n, Map<Integer, Integer> frequencyMap) {
        this.n = n;
        this.frequencyMap = frequencyMap;
        this.matrix = new int[n][n];
    }

    public ConstructionResult solve() {
        if (n % 2 == 0) {
            return solveEven();
        } else {
            return solveOdd();
        }
    }

    private ConstructionResult solveEven() {
        int currentRow = 0;
        int currentCol = 0;

        // For even n, every number must appear in multiples of 4
        for (Map.Entry<Integer, Integer> entry : frequencyMap.entrySet()) {
            int value = entry.getKey();
            int count = entry.getValue();

            if (count % 4 != 0) {
                return new ConstructionResult(false, null);
            }

            while (count > 0) {
                count -= 4;
                matrix[currentRow][currentCol] = value;
                matrix[currentRow][n - currentCol - 1] = value;
                matrix[n - currentRow - 1][n - currentCol - 1] = value;
                matrix[n - currentRow - 1][currentCol] = value;

                if (currentCol == n / 2 - 1) {
                    currentRow++;
                    currentCol = 0;
                } else {
                    currentCol++;
                }
            }
        }
        return new ConstructionResult(true, matrix);
    }

    private ConstructionResult solveOdd() {
        int cornerRow = 0;
        int cornerCol = 0;
        int midLineIdx = 0;
        boolean isMiddleColumnMode = false;

        // We use a copy of the keys to avoid ConcurrentModificationException 
        // when modifying frequencies during iteration.
        List<Integer> keys = new ArrayList<>(frequencyMap.keySet());

        for (int value : keys) {
            int count = frequencyMap.get(value);

            // 1. Handle Center (must have count % 4 == 1 or 3)
            if (count % 4 == 1 || count % 4 == 3) {
                if (matrix[n / 2][n / 2] != 0) return new ConstructionResult(false, null);
                matrix[n / 2][n / 2] = value;
                count--;
                frequencyMap.put(value, count);
            }

            // 2. Handle Mid-line Pairs (remaining count % 4 == 2)
            if (count % 4 == 2 && count > 0) {
                count -= 2;
                if (!isMiddleColumnMode) {
                    matrix[midLineIdx][n / 2] = value;
                    matrix[n - midLineIdx - 1][n / 2] = value;
                    midLineIdx++;
                    if (midLineIdx == n / 2) {
                        isMiddleColumnMode = true;
                        midLineIdx = 0;
                    }
                } else {
                    if (midLineIdx == n / 2) return new ConstructionResult(false, null);
                    matrix[n / 2][midLineIdx] = value;
                    matrix[n / 2][n - midLineIdx - 1] = value;
                    midLineIdx++;
                }
                frequencyMap.put(value, count);
            }

            // 3. Handle 4-way Symmetric Corners
            if (count > 0 && count % 4 == 0) {
                while (count > 0) {
                    // If we are currently trying to fill the middle lines but logic dictates corners
                    if (cornerRow == n / 2) {
                        count -= 2;
                        if (!isMiddleColumnMode) {
                            matrix[midLineIdx][n / 2] = value;
                            matrix[n - midLineIdx - 1][n / 2] = value;
                            midLineIdx++;
                            if (midLineIdx == n / 2) {
                                isMiddleColumnMode = true;
                                midLineIdx = 0;
                            }
                        } else {
                            if (midLineIdx == n / 2) return new ConstructionResult(false, null);
                            matrix[n / 2][midLineIdx] = value;
                            matrix[n / 2][n - midLineIdx - 1] = value;
                            midLineIdx++;
                        }
                    } else {
                        count -= 4;
                        matrix[cornerRow][cornerCol] = value;
                        matrix[cornerRow][n - cornerCol - 1] = value;
                        matrix[n - cornerRow - 1][n - cornerCol - 1] = value;
                        matrix[n - cornerRow - 1][cornerCol] = value;

                        if (cornerCol == n / 2 - 1) {
                            cornerRow++;
                            cornerCol = 0;
                        } else {
                            cornerCol++;
                        }
                    }
                }
                frequencyMap.put(value, 0);
            }

            // Final Validation
            if (frequencyMap.get(value) != 0) {
                return new ConstructionResult(false, null);
            }
        }
        return new ConstructionResult(true, matrix);
    }
}

public class Main {
    public static void main(String[] args) {
        FastReader sc = new FastReader();
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = sc.nextInt();
            int[] elements = sc.nextIntArray(n * n);

            Map<Integer, Integer> frequencyMap = new HashMap<>();
            for (int val : elements) {
                frequencyMap.put(val, frequencyMap.getOrDefault(val, 0) + 1);
            }

            MatrixSymmetrySolver solver = new MatrixSymmetrySolver(n, frequencyMap);
            ConstructionResult result = solver.solve();

            if (result.isSuccess()) {
                out.println("YES");
                int[][] matrix = result.getMatrix();
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < n; j++) {
                        out.print(matrix[i][j] + (j == n - 1 ? "" : " "));
                    }
                    out.println();
                }
            } else {
                out.println("NO");
            }
        } catch (Exception e) {
            // In competitive programming context, we handle or ignore
        } finally {
            out.flush();
            out.close();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A utility to construct an n x n matrix that is symmetric with respect to its center.
 * The construction ensures that elements are placed in sets of 4 (corners), 
 * 2 (middle edges), or 1 (center) to satisfy the symmetry requirements.
 */
public class SymmetricMatrixBuilder {

    private static final int MAX_VALUE_RANGE = 1001;

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            solve(reader, writer);
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    private static void solve(FastReader reader, PrintWriter writer) throws IOException {
        int n = reader.nextInt();
        if (n <= 0) return;

        int[] frequencies = new int[MAX_VALUE_RANGE];
        for (int i = 0; i < n * n; i++) {
            int val = reader.nextInt();
            if (val < MAX_VALUE_RANGE) {
                frequencies[val]++;
            }
        }

        int[][] matrix = new int[n][n];

        // 1. Fill the four quadrants (sets of 4 symmetric cells)
        for (int i = 0; i < n / 2; i++) {
            for (int j = 0; j < n / 2; j++) {
                if (!fillSymmetricGroup(matrix, frequencies, n, i, j, 4)) {
                    writer.println("NO");
                    return;
                }
            }
        }

        // 2. If n is odd, handle the middle row, middle column, and center
        if (n % 2 != 0) {
            int mid = n / 2;

            // Fill middle row (excluding the center)
            for (int j = 0; j < mid; j++) {
                if (!fillSymmetricGroup(matrix, frequencies, n, mid, j, 2)) {
                    writer.println("NO");
                    return;
                }
            }

            // Fill middle column (excluding the center)
            for (int i = 0; i < mid; i++) {
                if (!fillSymmetricGroup(matrix, frequencies, n, i, mid, 2)) {
                    writer.println("NO");
                    return;
                }
            }

            // Fill the single center cell
            if (!fillSymmetricGroup(matrix, frequencies, n, mid, mid, 1)) {
                writer.println("NO");
                return;
            }
        }

        // Output the successful matrix
        writer.println("YES");
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                writer.print(matrix[i][j]);
                writer.print(' ');
            }
            writer.println();
        }
    }

    /**
     * Finds a number with enough frequency and places it in its symmetric counterparts.
     * 
     * @param matrix The target 2D array.
     * @param frequencies The array containing counts of each number.
     * @param n Size of the matrix.
     * @param r Row index.
     * @param c Column index.
     * @param required The number of occurrences required (1, 2, or 4).
     * @return true if a number was found and placed; false otherwise.
     */
    private static boolean fillSymmetricGroup(int[][] matrix, int[] frequencies, int n, int r, int c, int required) {
        for (int val = 1; val < MAX_VALUE_RANGE; val++) {
            if (frequencies[val] >= required) {
                frequencies[val] -= required;

                // Calculate symmetric indices. 
                // If r or c is the middle index (for odd n), these indices will overlap,
                // effectively reducing the number of cells written to (e.g., 2 instead of 4).
                matrix[r][c] = val;
                matrix[n - 1 - r][c] = val;
                matrix[r][n - 1 - c] = val;
                matrix[n - 1 - r][n - 1 - c] = val;

                return true;
            }
        }
        return false;
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A refactored solution for constructing a rotationally symmetric matrix.
 * The matrix satisfies the property: mat[i][j] = mat[n-1-i][j] = mat[i][n-1-j] = mat[n-1-i][n-1-j].
 */
public class MatrixSymmetrySolver {

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        new MatrixSymmetrySolver().solve(sc, out);
        out.flush();
        out.close();
    }

    /**
     * Orchestrates the input reading, solving, and outputting.
     */
    public void solve(FastScanner sc, PrintWriter out) {
        String firstToken = sc.next();
        if (firstToken == null) return;

        int n = Integer.parseInt(firstToken);
        int[] counts = new int[1001];
        for (int i = 0; i < n * n; i++) {
            counts[sc.nextInt()]++;
        }

        int[][] matrix;
        if (n % 2 == 0) {
            matrix = solveEvenCase(n, counts);
        } else {
            matrix = solveOddCase(n, counts);
        }

        if (matrix == null) {
            out.println("NO");
        } else {
            out.println("YES");
            for (int i = 0; i < n; i++) {
                StringBuilder sb = new StringBuilder();
                for (int j = 0; j < n; j++) {
                    sb.append(matrix[i][j]);
                    if (j < n - 1) sb.append(" ");
                }
                out.println(sb.toString());
            }
        }
    }

    /**
     * Handles the construction for even-sized matrices.
     * For an even n, all element counts must be multiples of 4 to maintain symmetry.
     */
    private int[][] solveEvenCase(int n, int[] counts) {
        for (int count : counts) {
            if (count % 4 != 0) {
                return null;
            }
        }

        int[][] matrix = new int[n][n];
        int quadrantSide = n / 2;
        int pos = 0;

        for (int val = 0; val <= 1000; val++) {
            if (counts[val] == 0) continue;
            for (int j = 0; j < counts[val]; j += 4) {
                int r = pos / quadrantSide;
                int c = pos % quadrantSide;

                // Place the value in all 4 symmetric quadrants
                matrix[r][c] = val;
                matrix[n - 1 - r][c] = val;
                matrix[r][n - 1 - c] = val;
                matrix[n - 1 - r][n - 1 - c] = val;
                pos++;
            }
        }
        return matrix;
    }

    /**
     * Handles the construction for odd-sized matrices.
     * For an odd n, exactly one element must occupy the center (requiring an odd count).
     * The remaining counts must be distributable into symmetric axis pairs and quadrant quadruplets.
     */
    private int[][] solveOddCase(int n, int[] counts) {
        int centerValue = -1;
        for (int i = 0; i <= 1000; i++) {
            if (counts[i] % 2 != 0) {
                if (centerValue != -1) return null; // Multiple odd frequencies found
                centerValue = i;
            }
        }

        if (centerValue == -1) return null;

        // Reserve the center element
        counts[centerValue]--;

        Deque<Integer> pairList = new ArrayDeque<>(); // Elements with count % 4 == 2
        Deque<Integer> quadList = new ArrayDeque<>(); // Elements with count % 4 == 0

        for (int i = 0; i <= 1000; i++) {
            if (counts[i] == 0) continue;
            if (counts[i] % 4 == 2) {
                pairList.add(i);
            } else if (counts[i] % 4 == 0) {
                quadList.add(i);
            } else {
                return null;
            }
        }

        int numPairsInList = pairList.size();
        int numQuadsInList = quadList.size();
        int totalPairsNeeded = n - 1;

        // To satisfy symmetry, we need P + 2k = totalPairsNeeded, 
        // where P is the number of pair-only elements and k is elements used to form both row/col pairs.
        if (numPairsInList > totalPairsNeeded || (totalPairsNeeded - numPairsInList) % 2 != 0) {
            return null;
        }
        int k = (totalPairsNeeded - numPairsInList) / 2;
        if (k > numQuadsInList) {
            return null;
        }

        int[][] matrix = new int[n][n];
        int mid = n / 2;
        matrix[mid][mid] = centerValue;

        // 1. Use k elements from quadList to provide both a row-pair and a column-pair
        for (int i = 0; i < k; i++) {
            int val = quadList.pollFirst();
            matrix[mid][i] = matrix[mid][n - 1 - i] = val;
            matrix[i][mid] = matrix[n - 1 - i][mid] = val;
            counts[val] -= 4;
        }

        // 2. Use remaining pairList elements to fill the remaining axis slots
        int pairsPerSide = (totalPairsNeeded - 2 * k) / 2;
        for (int i = 0; i < pairsPerSide; i++) {
            int val = pairList.pollFirst();
            matrix[mid][k + i] = matrix[mid][n - 1 - (k + i)] = val;
            counts[val] -= 2;
        }
        for (int i = 0; i < pairsPerSide; i++) {
            int val = pairList.pollFirst();
            matrix[k + i][mid] = matrix[n - 1 - (k + i)][mid] = val;
            counts[val] -= 2;
        }

        // 3. Fill the 4 quadrant areas with the remaining counts
        int quadrantSide = n / 2;
        int pos = 0;
        for (int i = 0; i <= 1000; i++) {
            if (counts[i] == 0) continue;
            if (counts[i] % 4 != 0) return null; 
            for (int j = 0; j < counts[i]; j += 4) {
                int r = pos / quadrantSide;
                int c = pos % quadrantSide;
                matrix[r][c] = matrix[n - 1 - r][c] = matrix[r][n - 1 - c] = matrix[n - 1 - r][n - 1 - c] = i;
                pos++;
            }
        }

        return matrix;
    }

    /**
     * Fast I/O helper class for efficient reading of large datasets.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * Refactored solution for the grid symmetry problem.
 * The objective is to arrange n*n numbers into an n*n grid such that the grid 
 * satisfies specific reflectional symmetry properties.
 */
public class Solution {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        // Read the dimension of the grid
        int n = reader.nextInt();
        if (n <= 0) {
            writer.close();
            return;
        }

        // Frequency map for the input numbers (values range 0-1000)
        int[] counts = new int[1001];
        for (int i = 0; i < n * n; i++) {
            int val = reader.nextInt();
            if (val >= 0 && val <= 1000) {
                counts[val]++;
            }
        }

        GridSolver solver = new GridSolver(n, counts);
        if (solver.canSolve()) {
            writer.println("YES");
            solver.printGrid(writer);
        } else {
            writer.println("NO");
        }

        writer.flush();
        writer.close();
    }

    /**
     * Logic handler for validating and constructing the symmetric grid.
     */
    static class GridSolver {
        private final int n;
        private final int[] counts;
        private final int[][] grid;

        public GridSolver(int n, int[] counts) {
            this.n = n;
            this.counts = counts.clone();
            this.grid = new int[n][n];
        }

        /**
         * Validates if the given frequencies can form the required symmetric grid.
         * 
         * Symmetry logic:
         * - For even n: All elements must appear in groups of 4 to satisfy 
         *   the cell requirements (i, j), (i, n-1-j), (n-1-i, j), and (n-1-i, n-1-j).
         * - For odd n: One element is placed in the center. The remaining elements 
         *   must be able to fill the corners (groups of 4) and the middle cross 
         *   (groups of 2).
         */
        public boolean canSolve() {
            if (n % 2 == 0) {
                for (int count : counts) {
                    if (count % 4 != 0) return false;
                }
                return true;
            } else {
                int oddIdx = -1;
                for (int i = 0; i < 1001; i++) {
                    if (counts[i] % 2 != 0) {
                        if (oddIdx != -1) return false; // Only one element can have odd frequency
                        oddIdx = i;
                    }
                }
                if (oddIdx == -1) return false;

                // Temporarily use one instance for the center to check the rest
                counts[oddIdx]--;

                // The cross-shaped symmetry in the middle row/column requires n-1 pairs.
                // We count how many elements provide a single '2' remainder (4k + 2).
                int remainderPairs = 0;
                for (int i = 0; i < 1001; i++) {
                    if (counts[i] % 4 == 2) {
                        remainderPairs++;
                    }
                }

                // The number of remainder elements must be even (to pair with each other 
                // if needed) and cannot exceed the number of pairs required by the cross.
                return (remainderPairs % 2 == 0 && remainderPairs <= n - 1);
            }
        }

        /**
         * Constructs and prints the grid.
         */
        public void printGrid(PrintWriter writer) {
            if (n % 2 == 0) {
                fillEvenGrid();
            } else {
                fillOddGrid();
            }

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    writer.print(grid[i][j] + (j == n - 1 ? "" : " "));
                }
                writer.println();
            }
        }

        private void fillEvenGrid() {
            for (int i = 0; i < n / 2; i++) {
                for (int j = 0; j < n / 2; j++) {
                    int val = takeElements(4);
                    placeFourWaySymmetric(i, j, val);
                }
            }
        }

        private void fillOddGrid() {
            int mid = n / 2;

            // 1. Place the center element
            for (int i = 0; i < 1001; i++) {
                if (counts[i] % 2 != 0) {
                    grid[mid][mid] = i;
                    counts[i]--;
                    break;
                }
            }

            // 2. Fill the 4-way symmetric corner cells
            for (int i = 0; i < mid; i++) {
                for (int j = 0; j < mid; j++) {
                    int val = takeElements(4);
                    placeFourWaySymmetric(i, j, val);
                }
            }

            // 3. Fill the cross (middle row and middle column)
            for (int i = 0; i < mid; i++) {
                int valRow = takeElements(2);
                grid[mid][i] = valRow;
                grid[mid][n - 1 - i] = valRow;

                int valCol = takeElements(2);
                grid[i][mid] = valCol;
                grid[n - 1 - i][mid] = valCol;
            }
        }

        private void placeFourWaySymmetric(int i, int j, int val) {
            grid[i][j] = val;
            grid[i][n - 1 - j] = val;
            grid[n - 1 - i][j] = val;
            grid[n - 1 - i][n - 1 - j] = val;
        }

        private int takeElements(int quantity) {
            for (int i = 0; i < 1001; i++) {
                if (counts[i] >= quantity) {
                    counts[i] -= quantity;
                    return i;
                }
            }
            return 0;
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private final InputStream in;
        private final byte[] buffer = new byte[1024];
        private int pointer = 0;
        private int bytesRead = 0;

        public FastReader(InputStream in) {
            this.in = in;
        }

        private int readByte() {
            if (pointer >= bytesRead) {
                pointer = 0;
                try {
                    bytesRead = in.read(buffer);
                } catch (IOException e) {
                    return -1;
                }
                if (bytesRead <= 0) return -1;
            }
            return buffer[pointer++] & 0xFF;
        }

        public int nextInt() {
            int b = readByte();
            while (b != -1 && b <= 32) b = readByte();
            if (b == -1) return 0;
            boolean neg = false;
            if (b == '-') {
                neg = true;
                b = readByte();
            }
            int res = 0;
            while (b >= '0' && b <= '9') {
                res = res * 10 + (b - '0');
                b = readByte();
            }
            return neg ? -res : res;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solution to arrange n^2 integers into an n x n grid such that 
 * the grid is symmetric across its middle axes.
 */
public class Solution {

    public static void main(String[] args) {
        FastReader fr = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            String line1 = fr.readLine();
            if (line1 == null) return;
            int n = Integer.parseInt(line1.trim());

            String line2 = fr.readLine();
            if (line2 == null) return;
            StringTokenizer st = new StringTokenizer(line2);

            // Step 1: Count frequencies of all input numbers
            Map<Integer, Integer> frequencyMap = new HashMap<>();
            for (int i = 0; i < n * n; i++) {
                if (st.hasMoreTokens()) {
                    int val = Integer.parseInt(st.nextToken());
                    frequencyMap.put(val, frequencyMap.getOrDefault(val, 0) + 1);
                }
            }

            // Step 2: Attempt to build the symmetric grid
            int[][] grid = buildSymmetricGrid(n, frequencyMap);

            // Step 3: Output results
            if (grid == null) {
                out.println("NO");
            } else {
                out.println("YES");
                printGrid(grid, out);
            }
        } catch (Exception e) {
            // In a production environment, use a logging framework.
        } finally {
            out.close();
        }
    }

    /**
     * Builds a symmetric grid using a greedy approach.
     * 
     * @param n The dimension of the grid.
     * @param frequencyMap Map containing the counts of each number.
     * @return A 2D array representing the grid, or null if construction is impossible.
     */
    private static int[][] buildSymmetricGrid(int n, Map<Integer, Integer> frequencyMap) {
        int[][] grid = new int[n][n];

        // Pools to store numbers based on their available symmetry groups.
        // pool4: numbers available to form 4-way symmetric sets.
        // pool2: numbers available to form 2-way symmetric sets.
        // pool1: numbers available for the single center element.
        List<Integer> pool4 = new ArrayList<>();
        List<Integer> pool2 = new ArrayList<>();
        List<Integer> pool1 = new ArrayList<>();

        // Greedy allocation: prioritize higher-order symmetry requirements.
        for (Map.Entry<Integer, Integer> entry : frequencyMap.entrySet()) {
            int val = entry.getKey();
            int count = entry.getValue();

            int num4 = count / 4;
            for (int i = 0; i < num4; i++) pool4.add(val);

            int remaining = count % 4;
            int num2 = remaining / 2;
            for (int i = 0; i < num2; i++) pool2.add(val);

            int num1 = remaining % 2;
            for (int i = 0; i < num1; i++) pool1.add(val);
        }

        // Calculate exact requirements for the symmetry pattern.
        int quadrantsNeeded = (n / 2) * (n / 2);
        int linesNeeded = (n % 2 == 0) ? 0 : (n - 1); // (n-1)/2 for row + (n-1)/2 for column
        int centerNeeded = (n % 2 == 0) ? 0 : 1;

        // Validate if sufficient elements exist in the pools.
        if (pool4.size() < quadrantsNeeded || 
            pool2.size() < linesNeeded || 
            pool1.size() < centerNeeded) {
            return null;
        }

        // 1. Fill the four quadrants (4-way symmetry)
        int p4Idx = 0;
        for (int i = 0; i < n / 2; i++) {
            for (int j = 0; j < n / 2; j++) {
                int val = pool4.get(p4Idx++);
                grid[i][j] = grid[n - 1 - i][j] = grid[i][n - 1 - j] = grid[n - 1 - i][n - 1 - j] = val;
            }
        }

        // 2. Handle odd-dimensioned grids (middle row, middle column, and center)
        if (n % 2 != 0) {
            int mid = n / 2;
            int p2Idx = 0;

            // Fill middle row (2-way symmetry)
            for (int j = 0; j < mid; j++) {
                int val = pool2.get(p2Idx++);
                grid[mid][j] = grid[mid][n - 1 - j] = val;
            }

            // Fill middle column (2-way symmetry)
            for (int i = 0; i < mid; i++) {
                int val = pool2.get(p2Idx++);
                grid[i][mid] = grid[n - 1 - i][mid] = val;
            }

            // Fill central element (1-way symmetry)
            grid[mid][mid] = pool1.get(0);
        }

        return grid;
    }

    /**
     * Prints the 2D grid to the provided PrintWriter.
     */
    private static void printGrid(int[][] grid, PrintWriter out) {
        for (int[] row : grid) {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < row.length; i++) {
                sb.append(row[i]);
                if (i < row.length - 1) sb.append(" ");
            }
            out.println(sb.toString());
        }
    }

    /**
     * Fast I/O wrapper for efficient reading.
     */
    static class FastReader {
        private final BufferedReader reader;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String readLine() {
            try {
                return reader.readLine();
            } catch (IOException e) {
                return null;
            }
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solution to construct a symmetric grid based on the frequencies of provided integers.
 * The grid follows 4-way, 2-way, or 1-way symmetry depending on the input N.
 */
public class Solution {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            String nStr = reader.next();
            if (nStr == null) return;

            int n = Integer.parseInt(nStr);
            TreeMap<Integer, Integer> frequencyMap = new TreeMap<>();

            // Populate frequency map from N*N inputs
            for (int i = 0; i < n * n; i++) {
                int val = reader.nextInt();
                frequencyMap.put(val, frequencyMap.getOrDefault(val, 0) + 1);
            }

            SymmetricGridSolver solver = new SymmetricGridSolver(n, frequencyMap);
            solver.solve(out);

        } catch (Exception e) {
            // In a production environment, use a logging framework
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Encapsulates the logic for building and validating the symmetric grid.
     */
    static class SymmetricGridSolver {
        private final int n;
        private final TreeMap<Integer, Integer> frequencyMap;
        private final int[][] grid;

        public SymmetricGridSolver(int n, TreeMap<Integer, Integer> frequencyMap) {
            this.n = n;
            this.frequencyMap = frequencyMap;
            this.grid = new int[n][n];
        }

        /**
         * Executes the grid construction algorithm.
         * @param out The PrintWriter used to output results.
         */
        public void solve(PrintWriter out) {
            int mid = n / 2;

            // 1. Fill 4-way symmetric quadrants (applies to both even and odd N)
            for (int i = 0; i < mid; i++) {
                for (int j = 0; j < mid; j++) {
                    Integer val = consumeFrequency(4);
                    if (val == null) {
                        out.println("NO");
                        return;
                    }
                    setFourWaySymmetry(i, j, val);
                }
            }

            // 2. If N is odd, handle the middle row, middle column, and center cell
            if (n % 2 != 0) {
                // Handle vertical middle symmetry (2-way)
                for (int i = 0; i < mid; i++) {
                    Integer val = consumeFrequency(2);
                    if (val == null) {
                        out.println("NO");
                        return;
                    }
                    grid[i][mid] = grid[n - 1 - i][mid] = val;
                }

                // Handle horizontal middle symmetry (2-way)
                for (int j = 0; j < mid; j++) {
                    Integer val = consumeFrequency(2);
                    if (val == null) {
                        out.println("NO");
                        return;
                    }
                    grid[mid][j] = grid[mid][n - 1 - j] = val;
                }

                // Handle the single center cell (1-way)
                Integer centerVal = consumeFrequency(1);
                if (centerVal == null) {
                    out.println("NO");
                    return;
                }
                grid[mid][mid] = centerVal;
            }

            // 3. If all symmetric requirements are met, output the grid
            out.println("YES");
            printGrid(out);
        }

        private void setFourWaySymmetry(int r, int c, int val) {
            grid[r][c] = val;
            grid[r][n - 1 - c] = val;
            grid[n - 1 - r][c] = val;
            grid[n - 1 - r][n - 1 - c] = val;
        }

        /**
         * Finds the smallest available number that meets the required frequency count.
         * 
         * @param required The number of occurrences needed.
         * @return The number used, or null if no such number exists.
         */
        private Integer consumeFrequency(int required) {
            Iterator<Map.Entry<Integer, Integer>> iterator = frequencyMap.entrySet().iterator();
            while (iterator.hasNext()) {
                Map.Entry<Integer, Integer> entry = iterator.next();
                if (entry.getValue() >= required) {
                    int val = entry.getKey();
                    int remaining = entry.getValue() - required;
                    if (remaining == 0) {
                        iterator.remove();
                    } else {
                        entry.setValue(remaining);
                    }
                    return val;
                }
            }
            return null;
        }

        private void printGrid(PrintWriter out) {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < n; i++) {
                sb.setLength(0);
                for (int j = 0; j < n; j++) {
                    sb.append(grid[i][j]);
                    if (j < n - 1) sb.append(" ");
                }
                out.println(sb.toString());
            }
        }
    }

    /**
     * Fast utility for reading input.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * SymmetryMatrixSolver solves the problem of filling an n x n matrix 
 * such that the matrix is symmetric across both its horizontal and 
 * vertical axes using a given set of numbers.
 */
public class SymmetryMatrixSolver {

    public static void main(String[] args) {
        try {
            new SymmetryMatrixSolver().run();
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    public void run() throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter writer = new PrintWriter(System.out);

        // Read matrix size
        String line = reader.readLine();
        if (line == null) return;
        int n = Integer.parseInt(line.trim());

        // Read n*n integers and store their frequencies in a sorted map
        TreeMap<Integer, Integer> frequencyMap = readFrequencies(reader, n * n);

        int[][] matrix = new int[n][n];
        boolean possible = fillSymmetricMatrix(n, frequencyMap, matrix);

        if (possible) {
            writer.println("YES");
            printMatrix(writer, matrix);
        } else {
            writer.println("NO");
        }

        writer.flush();
        writer.close();
    }

    /**
     * Reads n*n integers from the input stream and maps their frequencies.
     */
    private TreeMap<Integer, Integer> readFrequencies(BufferedReader reader, int totalCount) throws IOException {
        TreeMap<Integer, Integer> frequencies = new TreeMap<>();
        StringTokenizer st = null;
        int count = 0;

        while (count < totalCount) {
            String line = reader.readLine();
            if (line == null) break;
            st = new StringTokenizer(line);
            while (st.hasMoreTokens() && count < totalCount) {
                int val = Integer.parseInt(st.nextToken());
                frequencies.put(val, frequencies.getOrDefault(val, 0) + 1);
                count++;
            }
        }
        return frequencies;
    }

    /**
     * Fills the matrix using a greedy approach, picking the smallest available
     * number that satisfies the symmetry group requirement.
     * 
     * @return true if the matrix was successfully filled, false otherwise.
     */
    private boolean fillSymmetricMatrix(int n, TreeMap<Integer, Integer> frequencies, int[][] matrix) {
        // We only need to iterate through the top-left quadrant to cover all symmetry groups
        for (int i = 0; i <= (n - 1) / 2; i++) {
            for (int j = 0; j <= (n - 1) / 2; j++) {

                // Identify the unique cells in this symmetry group
                Set<Integer> uniqueCellIndices = getSymmetryGroupIndices(i, j, n);
                int requiredCount = uniqueCellIndices.size();

                // Find the smallest number in the map that has enough frequency
                int chosenValue = findSmallestAvailable(frequencies, requiredCount);

                if (chosenValue == -1) {
                    return false; // Cannot satisfy this group requirement
                }

                // Update frequency map
                int currentFreq = frequencies.get(chosenValue);
                if (currentFreq == requiredCount) {
                    frequencies.remove(chosenValue);
                } else {
                    frequencies.put(chosenValue, currentFreq - requiredCount);
                }

                // Fill the matrix at the identified indices
                for (int index : uniqueCellIndices) {
                    int r = index / n;
                    int c = index % n;
                    matrix[r][c] = chosenValue;
                }
            }
        }
        return true;
    }

    /**
     * Calculates the flattened indices of the symmetric group for a given cell (i, j).
     */
    private Set<Integer> getSymmetryGroupIndices(int i, int j, int n) {
        Set<Integer> indices = new HashSet<>();
        int[] rows = {i, n - 1 - i};
        int[] cols = {j, n - 1 - j};

        for (int r : rows) {
            for (int c : cols) {
                indices.add(r * n + c);
            }
        }
        return indices;
    }

    /**
     * Finds the smallest key in the TreeMap whose value is >= requiredCount.
     */
    private int findSmallestAvailable(TreeMap<Integer, Integer> frequencies, int requiredCount) {
        for (Map.Entry<Integer, Integer> entry : frequencies.entrySet()) {
            if (entry.getValue() >= requiredCount) {
                return entry.getKey();
            }
        }
        return -1;
    }

    /**
     * Helper to print the matrix to the output stream.
     */
    private void printMatrix(PrintWriter writer, int[][] matrix) {
        for (int[] row : matrix) {
            for (int j = 0; j < row.length; j++) {
                writer.print(row[j] + (j == row.length - 1 ? "" : " "));
            }
            writer.println();
        }
    }
}

import java.io.*;
