/**
 * SymmetryGridSolver solves the problem of arranging N^2 integers in an N x N grid
 * such that the grid exhibits rotational symmetry.
 */
public class SymmetryGridSolver {

    /**
     * FastReader provides efficient input parsing using StringTokenizer.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String next = next();
            return next == null ? -1 : Integer.parseInt(next);
        }
    }

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        String nInput = reader.next();
        if (nInput != null) {
            int n = Integer.parseInt(nInput);
            TreeMap<Integer, Integer> counts = new TreeMap<>();

            // Read n*n elements and store their frequencies
            for (int i = 0; i < n * n; i++) {
                int val = reader.nextInt();
                counts.put(val, counts.getOrDefault(val, 0) + 1);
            }

            solve(n, counts, writer);
        }

        writer.flush();
        writer.close();
    }

    /**
     * Orchestrates the grid generation based on the parity of N.
     */
    private static void solve(int n, TreeMap<Integer, Integer> counts, PrintWriter writer) {
        if (n == 1) {
            writer.println("YES");
            writer.println(counts.firstKey());
            return;
        }

        int[][] grid = new int[n][n];
        boolean isPossible;

        if (n % 2 == 0) {
            isPossible = fillEvenGrid(n, counts, grid);
        } else {
            isPossible = fillOddGrid(n, counts, grid);
        }

        if (isPossible) {
            writer.println("YES");
            printGrid(grid, writer);
        } else {
            writer.println("NO");
        }
    }

    /**
     * Fills an even-sized grid where every cell must belong to a symmetric group of 4.
     */
    private static boolean fillEvenGrid(int n, TreeMap<Integer, Integer> counts, int[][] grid) {
        // In an even grid, every cell (i, j) has three symmetric counterparts.
        // Therefore, every number must appear in a multiple of 4.
        for (int count : counts.values()) {
            if (count % 4 != 0) return false;
        }

        List<Integer> availableQuads = new ArrayList<>();
        for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
            int numGroups = entry.getValue() / 4;
            for (int i = 0; i < numGroups; i++) {
                availableQuads.add(entry.getKey());
            }
        }

        int half = n / 2;
        if (availableQuads.size() != half * half) return false;

        int quadIdx = 0;
        for (int i = 0; i < half; i++) {
            for (int j = 0; j < half; j++) {
                int val = availableQuads.get(quadIdx++);
                grid[i][j] = val;
                grid[n - 1 - i][j] = val;
                grid[i][n - 1 - j] = val;
                grid[n - 1 - i][n - 1 - j] = val;
            }
        }
        return true;
    }

    /**
     * Fills an odd-sized grid handling the center (1-way), middle axes (2-way), 
     * and quadrants (4-way) symmetry.
     */
    private static boolean fillOddGrid(int n, TreeMap<Integer, Integer> counts, int[][] grid) {
        int half = n / 2;

        // 1. Fill the 4-way symmetric quadrants
        for (int i = 0; i < half; i++) {
            for (int j = 0; j < half; j++) {
                int val = findAndDecrement(counts, 4);
                if (val == -1) return false;
                grid[i][j] = grid[n - 1 - i][j] = grid[i][n - 1 - j] = grid[n - 1 - i][n - 1 - j] = val;
            }
        }

        // 2. Fill the 2-way symmetric middle row (excluding center)
        for (int j = 0; j < half; j++) {
            int val = findAndDecrement(counts, 2);
            if (val == -1) return false;
            grid[half][j] = grid[half][n - 1 - j] = val;
        }

        // 3. Fill the 2-way symmetric middle column (excluding center)
        for (int i = 0; i < half; i++) {
            int val = findAndDecrement(counts, 2);
            if (val == -1) return false;
            grid[i][half] = grid[n - 1 - i][half] = val;
        }

        // 4. Fill the single center cell
        int centerVal = findAndDecrement(counts, 1);
        if (centerVal == -1) return false;
        grid[half][half] = centerVal;

        return true;
    }

    /**
     * Helper to find the first available number that can satisfy the required frequency.
     * 
     * @param counts The frequency map.
     * @param amount The required count (1, 2, or 4).
     * @return The value found, or -1 if no such value exists.
     */
    private static int findAndDecrement(TreeMap<Integer, Integer> counts, int amount) {
        for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
            if (entry.getValue() >= amount) {
                int val = entry.getKey();
                int newCount = entry.getValue() - amount;
                if (newCount == 0) {
                    counts.remove(val);
                } else {
                    counts.put(val, newCount);
                }
                return val;
            }
        }
        return -1;
    }

    /**
     * Outputs the grid to the provided PrintWriter.
     */
    private static void printGrid(int[][] grid, PrintWriter writer) {
        int n = grid.length;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                writer.print(grid[i][j]);
                if (j < n - 1) writer.print(" ");
            }
            writer.println();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to arrange n*n elements into an n x n matrix 
 * such that it possesses both horizontal and vertical reflectional symmetry.
 */
public class Main {

    private static final int MAX_VALUE_LIMIT = 1010;

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = reader.nextInt();
        int[] elements = reader.nextIntArray(n * n);

        SymmetrySolver solver = new SymmetrySolver(n, elements);
        if (solver.solve()) {
            out.println("YES");
            solver.printMatrix(out);
        } else {
            out.println("NO");
        }
        out.flush();
    }

    static class SymmetrySolver {
        private final int n;
        private final int[][] matrix;
        private final int[] frequencies;

        public SymmetrySolver(int n, int[] elements) {
            this.n = n;
            this.matrix = new int[n][n];
            this.frequencies = new int[MAX_VALUE_LIMIT];
            for (int val : elements) {
                if (val < MAX_VALUE_LIMIT) {
                    frequencies[val]++;
                }
            }
        }

        public boolean solve() {
            if (n % 2 == 0) {
                return solveEven();
            } else {
                return solveOdd();
            }
        }

        /**
         * For even n, every number must appear in multiples of 4 to maintain 
         * 4-way symmetry across the quadrants.
         */
        private boolean solveEven() {
            for (int i = 0; i < MAX_VALUE_LIMIT; i++) {
                if (frequencies[i] % 4 != 0) {
                    return false;
                }
            }

            int count = 0;
            int totalGroupsOfFour = (n * n) / 4;
            int valIdx = 0;

            while (count < totalGroupsOfFour && valIdx < MAX_VALUE_LIMIT) {
                if (frequencies[valIdx] == 0) {
                    valIdx++;
                    continue;
                }

                int h = count / (n / 2);
                int w = count % (n / 2);

                matrix[h][w] = valIdx;
                matrix[n - 1 - h][w] = valIdx;
                matrix[h][n - 1 - w] = valIdx;
                matrix[n - 1 - h][n - 1 - w] = valIdx;

                frequencies[valIdx] -= 4;
                count++;
            }

            return count == totalGroupsOfFour;
        }

        /**
         * For odd n, one element occupies the center. The middle row and column 
         * (excluding center) require pairs, and the quadrants require quadruplets.
         */
        private boolean solveOdd() {
            int centerValue = -1;
            int oddCountFound = 0;

            // 1. Identify the center element (must have an odd frequency)
            for (int i = 0; i < MAX_VALUE_LIMIT; i++) {
                if (frequencies[i] % 2 != 0) {
                    oddCountFound++;
                    centerValue = i;
                }
            }

            if (oddCountFound != 1) {
                return false;
            }

            // Place center
            matrix[n / 2][n / 2] = centerValue;
            frequencies[centerValue]--;

            // 2. Fill the quadrants with quadruplets
            int quadrantsNeeded = (n / 2) * (n / 2);
            int quadrantsFilled = 0;
            int valIdx = 0;

            while (quadrantsFilled < quadrantsNeeded && valIdx < MAX_VALUE_LIMIT) {
                if (frequencies[valIdx] < 4) {
                    valIdx++;
                    continue;
                }

                int h = quadrantsFilled / (n / 2);
                int w = quadrantsFilled % (n / 2);

                matrix[h][w] = valIdx;
                matrix[n - 1 - h][w] = valIdx;
                matrix[h][n - 1 - w] = valIdx;
                matrix[n - 1 - h][n - 1 - w] = valIdx;

                frequencies[valIdx] -= 4;
                quadrantsFilled++;
            }

            if (quadrantsFilled != quadrantsNeeded) {
                return false;
            }

            // 3. Fill the middle row (excluding center) with pairs
            int middleRowPairsNeeded = n / 2;
            int middleRowPairsFilled = 0;
            valIdx = 0;

            while (middleRowPairsFilled < middleRowPairsNeeded && valIdx < MAX_VALUE_LIMIT) {
                if (frequencies[valIdx] < 2) {
                    valIdx++;
                    continue;
                }

                int w = middleRowPairsFilled;
                matrix[n / 2][w] = valIdx;
                matrix[n / 2][n - 1 - w] = valIdx;

                frequencies[valIdx] -= 2;
                middleRowPairsFilled++;
            }

            if (middleRowPairsFilled != middleRowPairsNeeded) {
                return false;
            }

            // 4. Fill the middle column (excluding center) with pairs
            int middleColPairsNeeded = n / 2;
            int middleColPairsFilled = 0;
            valIdx = 0;

            while (middleColPairsFilled < middleColPairsNeeded && valIdx < MAX_VALUE_LIMIT) {
                if (frequencies[valIdx] < 2) {
                    valIdx++;
                    continue;
                }

                int h = middleColPairsFilled;
                matrix[h][n / 2] = valIdx;
                matrix[n - 1 - h][n / 2] = valIdx;

                frequencies[valIdx] -= 2;
                middleColPairsFilled++;
            }

            return middleColPairsFilled == middleColPairsNeeded;
        }

        public void printMatrix(PrintWriter out) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    out.print(matrix[i][j] + (j == n - 1 ? "" : " "));
                }
                out.println();
            }
        }
    }

    /**
     * Optimized reader for fast input processing.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public int[] nextIntArray(int size) {
            int[] arr = new int[size];
            for (int i = 0; i < size; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }
    }
}

import java.util.*;

/**
 * The Matrices class provides functionality to arrange n*n integers into 
 * an n x n matrix that exhibits horizontal and vertical reflection symmetry.
 */
public class Matrices {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) return;

        int n = scanner.nextInt();
        int totalElements = n * n;
        TreeMap<Integer, Integer> frequencyMap = new TreeMap<>();

        for (int i = 0; i < totalElements; i++) {
            int val = scanner.nextInt();
            frequencyMap.put(val, frequencyMap.getOrDefault(val, 0) + 1);
        }

        solve(n, frequencyMap);
        scanner.close();
    }

    /**
     * Orchestrates the matrix construction process.
     */
    private static void solve(int n, TreeMap<Integer, Integer> frequencyMap) {
        int[][] matrix = new int[n][n];

        if (n % 2 == 0) {
            if (fillEven(n, frequencyMap, matrix)) {
                System.out.println("Yes");
                printMatrix(matrix);
            } else {
                System.out.println("No");
            }
        } else {
            if (fillOdd(n, frequencyMap, matrix)) {
                System.out.println("Yes");
                printMatrix(matrix);
            } else {
                System.out.println("No");
            }
        }
    }

    /**
     * Fills an even-sized matrix using only quartets (4-way symmetry).
     */
    private static boolean fillEven(int n, TreeMap<Integer, Integer> map, int[][] matrix) {
        int half = n / 2;
        // Every element in an even symmetric matrix must appear in multiples of 4
        for (int i = 0; i < half; i++) {
            for (int j = 0; j < half; j++) {
                Integer val = findAndConsume(map, 4);
                if (val == null) return false;
                fillQuartet(matrix, i, j, n, val);
            }
        }
        return true;
    }

    /**
     * Fills an odd-sized matrix using 1 center, n-1 pairs, and (n/2)^2 quartets.
     */
    private static boolean fillOdd(int n, TreeMap<Integer, Integer> map, int[][] matrix) {
        int half = n / 2;

        // 1. Fill the Center
        Integer centerVal = null;
        for (Map.Entry<Integer, Integer> entry : map.entrySet()) {
            if (entry.getValue() % 2 != 0) {
                centerVal = entry.getKey();
                break;
            }
        }
        if (centerVal == null) return false;
        matrix[half][half] = centerVal;
        consume(map, centerVal, 1);

        // 2. Fill the Cross (Middle Row and Middle Column)
        // We need (n-1) pairs total: (n-1)/2 for the row and (n-1)/2 for the column 
        // results in 2*(n-1) cells, which is n-1 pairs.
        // However, the symmetry logic requires pairs at (half, i)/(half, n-1-i) 
        // and (i, half)/(n-1-i, half).

        // Fill middle row pairs
        for (int i = 0; i < half; i++) {
            Integer pairVal = findAndConsume(map, 2);
            if (pairVal == null) return false;
            matrix[half][i] = matrix[half][n - 1 - i] = pairVal;
        }

        // Fill middle column pairs
        for (int i = 0; i < half; i++) {
            Integer pairVal = findAndConsume(map, 2);
            if (pairVal == null) return false;
            matrix[i][half] = matrix[n - 1 - i][half] = pairVal;
        }

        // 3. Fill the Quadrants
        for (int i = 0; i < half; i++) {
            for (int j = 0; j < half; j++) {
                Integer quartVal = findAndConsume(map, 4);
                if (quartVal == null) return false;
                fillQuartet(matrix, i, j, n, quartVal);
            }
        }

        return true;
    }

    /**
     * Helper to find a value with at least 'count' occurrences and decrement it.
     */
    private static Integer findAndConsume(TreeMap<Integer, Integer> map, int count) {
        for (Map.Entry<Integer, Integer> entry : map.entrySet()) {
            if (entry.getValue() >= count) {
                int val = entry.getKey();
                consume(map, val, count);
                return val;
            }
        }
        return null;
    }

    private static void consume(TreeMap<Integer, Integer> map, int val, int count) {
        int newCount = map.get(val) - count;
        if (newCount == 0) {
            map.remove(val);
        } else {
            map.put(val, newCount);
        }
    }

    /**
     * Applies 4-way reflection symmetry to a single cell.
     */
    private static void fillQuartet(int[][] matrix, int i, int j, int n, int val) {
        matrix[i][j] = val;
        matrix[n - 1 - i][j] = val;
        matrix[i][n - 1 - j] = val;
        matrix[n - 1 - i][n - 1 - j] = val;
    }

    private static void printMatrix(int[][] matrix) {
        StringBuilder sb = new StringBuilder();
        for (int[] row : matrix) {
            for (int val : row) {
                sb.append(val).append(" ");
            }
            sb.append("\n");
        }
        System.out.print(sb.toString());
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored Symmetric Matrix Builder.
 * This program takes n and n^2 integers, and constructs an n x n matrix 
 * that is symmetric across both its horizontal and vertical axes.
 */
public class SymmetricMatrixSolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            String firstToken = reader.next();
            if (firstToken == null) return;
            int n = Integer.parseInt(firstToken);

            Map<Integer, Integer> freq = new HashMap<>();
            for (int i = 0; i < n * n; i++) {
                int val = reader.nextInt();
                freq.put(val, freq.getOrDefault(val, 0) + 1);
            }

            if (n % 2 == 0) {
                if (isPossibleEven(freq)) {
                    int[][] matrix = new int[n][n];
                    fillEven(n, freq, matrix);
                    printMatrix(matrix, out);
                } else {
                    out.println("NO");
                }
            } else {
                if (isPossibleOdd(n, freq)) {
                    int[][] matrix = new int[n][n];
                    fillOdd(n, freq, matrix);
                    printMatrix(matrix, out);
                } else {
                    out.println("NO");
                }
            }
        } catch (Exception e) {
            // Silently handle input mismatches
        } finally {
            out.close();
        }
    }

    private static boolean isPossibleEven(Map<Integer, Integer> freq) {
        for (int count : freq.values()) {
            if (count % 4 != 0) return false;
        }
        return true;
    }

    private static boolean isPossibleOdd(int n, Map<Integer, Integer> freq) {
        int oddCount = 0;
        for (int count : freq.values()) {
            if (count % 2 != 0) oddCount++;
        }
        if (oddCount != 1) return false;

        int numPairs = 0;
        for (Map.Entry<Integer, Integer> entry : freq.entrySet()) {
            int c = entry.getValue();
            if (c % 2 != 0) c--; // Exclude center element's extra count
            numPairs += (c % 4) / 2;
        }
        return numPairs <= (n - 1);
    }

    private static void fillEven(int n, Map<Integer, Integer> freq, int[][] matrix) {
        int r = 0, c = 0;
        for (Map.Entry<Integer, Integer> entry : freq.entrySet()) {
            int val = entry.getKey();
            int count = entry.getValue();
            while (count > 0) {
                matrix[r][c] = matrix[n - 1 - r][c] = matrix[r][n - 1 - c] = matrix[n - 1 - r][n - 1 - c] = val;
                count -= 4;
                c++;
                if (c == n / 2) {
                    c = 0;
                    r++;
                }
            }
        }
    }

    private static void fillOdd(int n, Map<Integer, Integer> freq, int[][] matrix) {
        int centerVal = -1;
        for (Map.Entry<Integer, Integer> entry : freq.entrySet()) {
            if (entry.getValue() % 2 != 0) {
                centerVal = entry.getKey();
                break;
            }
        }
        matrix[n / 2][n / 2] = centerVal;
        freq.put(centerVal, freq.get(centerVal) - 1);

        // Fill axis pairs: Middle row then Middle column
        // We prioritize elements with count % 4 == 2 for the axes.
        for (int j = 0; j < n / 2; j++) {
            int val = findAndDecrement(freq, 2, true);
            matrix[n / 2][j] = matrix[n / 2][n - 1 - j] = val;
        }
        for (int i = 0; i < n / 2; i++) {
            int val = findAndDecrement(freq, 2, true);
            matrix[i][n / 2] = matrix[n - 1 - i][n / 2] = val;
        }

        // Fill quads
        for (int i = 0; i < n / 2; i++) {
            for (int j = 0; j < n / 2; j++) {
                int val = findAndDecrement(freq, 4, false);
                matrix[i][j] = matrix[n - 1 - i][j] = matrix[i][n - 1 - j] = matrix[n - 1 - i][n - 1 - j] = val;
            }
        }
    }

    private static int findAndDecrement(Map<Integer, Integer> freq, int amount, boolean prioritizeMod2) {
        if (prioritizeMod2) {
            for (Map.Entry<Integer, Integer> entry : freq.entrySet()) {
                if (entry.getValue() >= amount && entry.getValue() % 4 == 2) {
                    int val = entry.getKey();
                    entry.setValue(entry.getValue() - amount);
                    return val;
                }
            }
        }
        for (Map.Entry<Integer, Integer> entry : freq.entrySet()) {
            if (entry.getValue() >= amount) {
                int val = entry.getKey();
                entry.setValue(entry.getValue() - amount);
                return val;
            }
        }
        return 0;
    }

    private static void printMatrix(int[][] matrix, PrintWriter out) {
        for (int i = 0; i < matrix.length; i++) {
            for (int j = 0; j < matrix[i].length; j++) {
                out.print(matrix[i][j] + (j == matrix[i].length - 1 ? "" : " "));
            }
            out.println();
        }
    }

    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Problem: Arrange N^2 numbers in an N x N grid with symmetry.
 * If N is even, all numbers must form groups of 4 (quadrant symmetry).
 * If N is odd, one number can be the center, others must form groups of 2 or 4.
 */
public class Main {

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        int n = sc.nextInt();
        int[] elements = new int[n * n];
        for (int i = 0; i < n * n; i++) {
            elements[i] = sc.nextInt();
        }

        GridSolver solver = new GridSolver(n, elements);
        solver.solve();
    }

    static class GridSolver {
        private final int n;
        private final Map<Integer, Integer> counts = new TreeMap<>();

        public GridSolver(int n, int[] elements) {
            this.n = n;
            for (int e : elements) {
                counts.put(e, counts.getOrDefault(e, 0) + 1);
            }
        }

        /**
         * Orchestrates the solving process.
         */
        public void solve() {
            int[][] grid = new int[n][n];
            boolean success;

            if (n % 2 == 0) {
                success = solveEven(grid);
            } else {
                success = solveOdd(grid);
            }

            if (success) {
                printGrid(grid);
            } else {
                System.out.println("NO");
            }
        }

        /**
         * Logic for even N: All numbers must be in multiples of 4 to form quadrant symmetry.
         */
        private boolean solveEven(int[][] grid) {
            for (int count : counts.values()) {
                if (count % 4 != 0) return false;
            }

            List<int[][]> quadGroups = generateQuadGroups(n);
            int groupIdx = 0;

            for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
                int val = entry.getKey();
                int numQuads = entry.getValue() / 4;
                for (int i = 0; i < numQuads; i++) {
                    fillGroup(grid, quadGroups.get(groupIdx++), val);
                }
            }
            return true;
        }

        /**
         * Logic for odd N: One center element, (n-1) pairs in middle row/col, rest are quads.
         */
        private boolean solveOdd(int[][] grid) {
            // 1. Find the center element (must have an odd count)
            int centerVal = -1;
            for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
                if (entry.getValue() % 2 != 0) {
                    if (centerVal != -1) return false; // Only one odd count allowed
                    centerVal = entry.getKey();
                }
            }
            if (centerVal == -1) return false;

            // 2. Place center
            grid[n / 2][n / 2] = centerVal;
            counts.put(centerVal, counts.get(centerVal) - 1);

            // 3. Prepare containers
            List<int[][]> quadGroups = generateQuadGroups(n);
            List<int[][]> pairGroups = generatePairGroups(n);

            int requiredQuads = quadGroups.size();
            int requiredPairs = pairGroups.size();

            // 4. Calculate available 4-packs and 2-packs
            int currentQuads = 0;
            int currentPairs = 0;
            for (int count : counts.values()) {
                currentQuads += count / 4;
                currentPairs += (count % 4) / 2;
            }

            // 5. Check feasibility using the conversion logic: 
            // One 4-pack can be converted into two 2-packs.
            if (currentQuads < requiredQuads) return false;
            int diff = currentQuads - requiredQuads;
            if (currentPairs + (2 * diff) != requiredPairs) return false;

            // 6. Distribute elements
            int quadIdx = 0;
            int pairIdx = 0;
            int conversionLeft = diff;

            for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
                int val = entry.getKey();
                int count = entry.getValue();
                if (count == 0) continue;

                int numQ = count / 4;
                int numP = (count % 4) / 2;

                // Convert some 4-packs to 2-packs if we have excess quads
                if (conversionLeft > 0 && numQ > 0) {
                    int take = Math.min(conversionLeft, numQ);
                    numQ -= take;
                    numP += 2 * take;
                    conversionLeft -= take;
                }

                for (int i = 0; i < numQ; i++) {
                    fillGroup(grid, quadGroups.get(quadIdx++), val);
                }
                for (int i = 0; i < numP; i++) {
                    fillGroup(grid, pairGroups.get(pairIdx++), val);
                }
            }

            return true;
        }

        private List<int[][]> generateQuadGroups(int n) {
            List<int[][]> groups = new ArrayList<>();
            for (int r = 0; r < n / 2; r++) {
                for (int c = 0; c < n / 2; c++) {
                    groups.add(new int[][]{
                        {r, c}, {r, n - 1 - c}, {n - 1 - r, c}, {n - 1 - r, n - 1 - c}
                    });
                }
            }
            return groups;
        }

        private List<int[][]> generatePairGroups(int n) {
            List<int[][]> groups = new ArrayList<>();
            // Middle row pairs
            for (int c = 0; c < n / 2; c++) {
                groups.add(new int[][]{ {n / 2, c}, {n / 2, n - 1 - c} });
            }
            // Middle column pairs
            for (int r = 0; r < n / 2; r++) {
                groups.add(new int[][]{ {r, n / 2}, {n - 1 - r, n / 2} });
            }
            return groups;
        }

        private void fillGroup(int[][] grid, int[][] cells, int val) {
            for (int[] cell : cells) {
                grid[cell[0]][cell[1]] = val;
            }
        }

        private void printGrid(int[][] grid) {
            StringBuilder sb = new StringBuilder();
            sb.append("YES\n");
            for (int[] row : grid) {
                for (int cell : row) {
                    sb.append(cell).append(" ");
                }
                sb.append("\n");
            }
            System.out.print(sb);
        }
    }

    /**
     * Efficient input reader.
     */
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int buflen = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private boolean hasNextByte() {
            if (ptr < buflen) return true;
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                return false;
            }
            return buflen > 0;
        }

        private int readByte() {
            if (hasNextByte()) return buffer[ptr++];
            else return -1;
        }

        private static boolean isPrintableChar(int c) {
            return 33 <= c && c <= 126;
        }

        private void skipUnprintable() {
            while (hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++;
        }

        public String next() {
            if (!hasNextByte()) throw new NoSuchElementException();
            StringBuilder sb = new StringBuilder();
            int b = readByte();
            while (isPrintableChar(b)) {
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }

        public int nextInt() {
            return (int) nextLong();
        }

        public long nextLong() {
            if (!hasNextByte()) throw new NoSuchElementException();
            long n = 0;
            boolean minus = false;
            int b = readByte();
            if (b == '-') {
                minus = true;
                b = readByte();
            }
            if (b < '0' || '9' < b) throw new NumberFormatException();
            while (true) {
                if ('0' <= b && b <= '9') {
                    n *= 10;
                    n += b - '0';
                } else if (b == -1 || !isPrintableChar(b)) {
                    return minus ? -n : n;
                } else {
                    throw new NumberFormatException();
                }
                b = readByte();
            }
        }
    }
}

import java.util.*;

/**
 * A solver that arranges N*N numbers into an N x N grid with rotational symmetry.
 * For even N, all numbers must appear in multiples of 4.
 * For odd N, one number must appear an odd number of times (for the center),
 * and others must satisfy specific pair/quad requirements.
 */
public class GridSymmetrySolver {

    private final int n;
    private final Map<Integer, Integer> frequencyMap;
    private final int[][] grid;

    public GridSymmetrySolver(int n, Map<Integer, Integer> frequencyMap) {
        this.n = n;
        // TreeMap keeps keys sorted for deterministic output
        this.frequencyMap = new TreeMap<>(frequencyMap);
        this.grid = new int[n][n];
    }

    /**
     * Orchestrates the solving process based on whether N is even or odd.
     */
    public void solve() {
        if (n % 2 == 0) {
            solveEven();
        } else {
            solveOdd();
        }
    }

    /**
     * Logic for even-sized grids. Requires every number to appear in groups of 4.
     */
    private void solveEven() {
        List<Integer> quadValues = new ArrayList<>();

        for (Map.Entry<Integer, Integer> entry : frequencyMap.entrySet()) {
            int val = entry.getKey();
            int count = entry.getValue();

            if (count % 4 != 0) {
                printResult(false);
                return;
            }

            for (int i = 0; i < count / 4; i++) {
                quadValues.add(val);
            }
        }

        fillQuadSymmetry(quadValues);
        printResult(true);
    }

    /**
     * Logic for odd-sized grids. Requires one center element and specific 
     * pairing for the middle row/column cross.
     */
    private void solveOdd() {
        int oddCount = 0;
        int centerVal = -1;

        // Identify the single number with an odd frequency for the center
        for (Map.Entry<Integer, Integer> entry : frequencyMap.entrySet()) {
            if (entry.getValue() % 2 != 0) {
                oddCount++;
                centerVal = entry.getKey();
            }
        }

        if (oddCount != 1) {
            printResult(false);
            return;
        }

        // Place center element and reduce its count
        grid[n / 2][n / 2] = centerVal;
        frequencyMap.put(centerVal, frequencyMap.get(centerVal) - 1);

        List<Integer> list2 = new ArrayList<>(); // Numbers with count % 4 == 2
        List<Integer> list0 = new ArrayList<>(); // Numbers with count % 4 == 0

        for (Map.Entry<Integer, Integer> entry : frequencyMap.entrySet()) {
            int count = entry.getValue();
            if (count <= 0) continue;

            if (count % 4 == 2) {
                list2.add(entry.getKey());
            } else {
                list0.add(entry.getKey());
            }
        }

        int pairsNeededForCross = n - 1;
        // Check if we have enough numbers with '2' remainder to fill the cross
        if (list2.size() > pairsNeededForCross || (pairsNeededForCross - list2.size()) % 2 != 0) {
            printResult(false);
            return;
        }

        // Prepare the values for the middle row and column pairs
        List<Integer> crossPairs = new ArrayList<>(list2);
        int remainingPairsNeeded = pairsNeededForCross - list2.size();
        int list0Idx = 0;

        // If we need more pairs for the cross, take them from numbers that have multiples of 4
        while (remainingPairsNeeded > 0) {
            int val = list0.get(list0Idx++);
            crossPairs.add(val);
            crossPairs.add(val);
            frequencyMap.put(val, frequencyMap.get(val) - 4);
            remainingPairsNeeded -= 2;
        }

        // Prepare the values for the 4-way symmetric quadrants
        List<Integer> quadValues = new ArrayList<>();
        for (Map.Entry<Integer, Integer> entry : frequencyMap.entrySet()) {
            int val = entry.getKey();
            int count = entry.getValue();
            while (count >= 4) {
                quadValues.add(val);
                count -= 4;
                frequencyMap.put(val, count);
            }
        }

        fillCrossSymmetry(crossPairs);
        fillQuadSymmetry(quadValues);
        printResult(true);
    }

    private void fillQuadSymmetry(List<Integer> quadValues) {
        int quadIdx = 0;
        for (int i = 0; i < n / 2; i++) {
            for (int j = 0; j < n / 2; j++) {
                int val = quadValues.get(quadIdx++);
                grid[i][j] = val;
                grid[i][n - 1 - j] = val;
                grid[n - 1 - i][j] = val;
                grid[n - 1 - i][n - 1 - j] = val;
            }
        }
    }

    private void fillCrossSymmetry(List<Integer> crossPairs) {
        int cpIdx = 0;
        // Fill vertical middle column
        for (int i = 0; i < n / 2; i++) {
            int val = crossPairs.get(cpIdx++);
            grid[i][n / 2] = val;
            grid[n - 1 - i][n / 2] = val;
        }
        // Fill horizontal middle row
        for (int i = 0; i < n / 2; i++) {
            int val = crossPairs.get(cpIdx++);
            grid[n / 2][i] = val;
            grid[n / 2][n - 1 - i] = val;
        }
    }

    private void printResult(boolean possible) {
        if (!possible) {
            System.out.println("NO");
            return;
        }

        System.out.println("YES");
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                sb.append(grid[i][j]);
                if (j < n - 1) sb.append(" ");
            }
            sb.append("\n");
        }
        System.out.print(sb.toString());
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) return;

        int n = scanner.nextInt();
        Map<Integer, Integer> frequencies = new HashMap<>();

        for (int i = 0; i < n * n; i++) {
            int val = scanner.nextInt();
            frequencies.put(val, frequencies.getOrDefault(val, 0) + 1);
        }

        new GridSymmetrySolver(n, frequencies).solve();
        scanner.close();
    }
}

import java.util.*;
import java.io.*;

/**
 * A refactored solution for the grid symmetry problem.
 * The program determines if a given set of numbers can form an n x n grid
 * that is symmetric across both the horizontal and vertical midlines.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            String firstLine = reader.readLine();
            if (firstLine == null) return;
            int n = Integer.parseInt(firstLine.trim());

            // Frequency array for numbers 1-1000
            int[] counts = new int[1001];
            for (int i = 0; i < n * n; i++) {
                int v = reader.nextInt();
                if (v >= 0 && v <= 1000) {
                    counts[v]++;
                }
            }

            SymmetrySolver solver = new SymmetrySolver(n, counts);
            if (solver.solve()) {
                out.println("YES");
                solver.printGrid(out);
            } else {
                out.println("NO");
            }
        } catch (Exception e) {
            // Silently handle or log error
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Encapsulates the logic for determining if a symmetric grid can be constructed.
     */
    static class SymmetrySolver {
        private final int n;
        private final int[] counts;
        private final int[][] grid;
        private final List<Integer> existingNumbers;

        public SymmetrySolver(int n, int[] counts) {
            this.n = n;
            this.counts = counts;
            this.grid = new int[n][n];
            this.existingNumbers = new ArrayList<>();
            // Pre-collect numbers that actually appear to optimize search time
            for (int i = 1; i <= 1000; i++) {
                if (counts[i] > 0) {
                    existingNumbers.add(i);
                }
            }
        }

        /**
         * Orchestrates the solving process based on grid parity.
         * @return true if a valid grid was constructed.
         */
        public boolean solve() {
            boolean success = (n % 2 == 0) ? solveEven() : solveOdd();
            return success && validateAllUsed();
        }

        private boolean solveEven() {
            // For even n, every number must be used in groups of 4.
            // We fill the four quadrants of the grid.
            for (int i = 0; i < n / 2; i++) {
                for (int j = 0; j < n / 2; j++) {
                    int v = findAndDecrement(4);
                    if (v == -1) return false;
                    fillFourWay(i, j, v);
                }
            }
            return true;
        }

        private boolean solveOdd() {
            int mid = n / 2;

            // 1. Fill 4-way symmetry groups (quadrants)
            for (int i = 0; i < mid; i++) {
                for (int j = 0; j < mid; j++) {
                    int v = findAndDecrement(4);
                    if (v == -1) return false;
                    fillFourWay(i, j, v);
                }
            }

            // 2. Fill 2-way symmetry groups (middle row and middle column)
            // Middle row (excluding center)
            for (int j = 0; j < mid; j++) {
                int v = findAndDecrement(2);
                if (v == -1) return false;
                fillTwoWayRow(mid, j, v);
            }
            // Middle column (excluding center)
            for (int i = 0; i < mid; i++) {
                int v = findAndDecrement(2);
                if (v == -1) return false;
                fillTwoWayCol(i, mid, v);
            }

            // 3. Fill 1-way symmetry group (the exact center)
            int vCenter = findAndDecrement(1);
            if (vCenter == -1) return false;
            grid[mid][mid] = vCenter;

            return true;
        }

        private void fillFourWay(int i, int j, int v) {
            grid[i][j] = v;
            grid[n - 1 - i][j] = v;
            grid[i][n - 1 - j] = v;
            grid[n - 1 - i][n - 1 - j] = v;
        }

        private void fillTwoWayRow(int r, int c, int v) {
            grid[r][c] = v;
            grid[r][n - 1 - c] = v;
        }

        private void fillTwoWayCol(int r, int c, int v) {
            grid[r][c] = v;
            grid[n - 1 - r][c] = v;
        }

        /**
         * Finds a number with at least the required count and decrements it.
         */
        private int findAndDecrement(int needed) {
            for (int v : existingNumbers) {
                if (counts[v] >= needed) {
                    counts[v] -= needed;
                    return v;
                }
            }
            return -1;
        }

        /**
         * Ensures that every single number from the input was placed in the grid.
         */
        private boolean validateAllUsed() {
            for (int i = 1; i <= 1000; i++) {
                if (counts[i] != 0) return false;
            }
            return true;
        }

        public void printGrid(PrintWriter out) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    out.print(grid[i][j] + (j == n - 1 ? "" : " "));
                }
                out.println();
            }
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String readLine() throws IOException {
            return reader.readLine();
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver for the Palindromic Matrix problem.
 * The goal is to arrange n*n elements into a matrix where for every cell (i, j),
 * the value is the same as its symmetric counterparts:
 * (i, n-1-j), (n-1-i, j), and (n-1-i, n-1-j).
 */
public class Main {
    public static void main(String[] args) {
        FastReader in = new FastReader(System.in);
        FastWriter out = new FastWriter(System.out);

        int n = in.nextInt();
        if (n <= 0) {
            out.close();
            return;
        }

        int[] elements = in.nextIntArray(n * n);
        PalindromicMatrixSolver solver = new PalindromicMatrixSolver(n, elements);

        if (solver.solve()) {
            out.println("YES");
            out.printMatrix(solver.getResultMatrix());
        } else {
            out.println("NO");
        }

        out.close();
    }

    static class PalindromicMatrixSolver {
        private final int n;
        private final int[][] matrix;
        private final Deque<Integer> ones = new ArrayDeque<>();
        private final Deque<Integer> twos = new ArrayDeque<>();
        private final Deque<Integer> fours = new ArrayDeque<>();

        public PalindromicMatrixSolver(int n, int[] elements) {
            this.n = n;
            this.matrix = new int[n][n];
            decomposeFrequencies(elements);
        }

        /**
         * Counts frequencies and breaks them into units of 4, 2, and 1.
         */
        private void decomposeFrequencies(int[] elements) {
            int[] frequencies = new int[1001];
            for (int val : elements) {
                if (val >= 0 && val <= 1000) {
                    frequencies[val]++;
                }
            }

            for (int i = 1; i <= 1000; i++) {
                int count = frequencies[i];
                while (count >= 4) {
                    fours.addLast(i);
                    count -= 4;
                }
                while (count >= 2) {
                    twos.addLast(i);
                    count -= 2;
                }
                while (count >= 1) {
                    ones.addLast(i);
                    count -= 1;
                }
            }
        }

        public boolean solve() {
            // 1. Fill the quartets (the 4-way symmetric cells)
            for (int i = 0; i < n / 2; i++) {
                for (int j = 0; j < n / 2; j++) {
                    int val = useFour();
                    if (val == -1) return false;
                    fillQuartet(i, j, val);
                }
            }

            // 2. If n is odd, handle the center and the axes
            if (n % 2 == 1) {
                int mid = n / 2;

                // Center cell (1 unit)
                int centerVal = useOne();
                if (centerVal == -1) return false;
                matrix[mid][mid] = centerVal;

                // Middle row (excluding center) (pairs)
                for (int j = 0; j < n / 2; j++) {
                    int val = useTwo();
                    if (val == -1) return false;
                    matrix[mid][j] = matrix[mid][n - 1 - j] = val;
                }

                // Middle column (excluding center) (pairs)
                for (int i = 0; i < n / 2; i++) {
                    int val = useTwo();
                    if (val == -1) return false;
                    matrix[i][mid] = matrix[n - 1 - i][mid] = val;
                }
            }

            return true;
        }

        private void fillQuartet(int i, int j, int val) {
            matrix[i][j] = val;
            matrix[i][n - 1 - j] = val;
            matrix[n - 1 - i][j] = val;
            matrix[n - 1 - i][n - 1 - j] = val;
        }

        private int useOne() {
            return ones.isEmpty() ? -1 : ones.removeLast();
        }

        private int useTwo() {
            if (!twos.isEmpty()) {
                return twos.removeLast();
            } else if (!fours.isEmpty()) {
                // A quartet can be used as two pairs
                int val = fours.removeLast();
                twos.addLast(val); 
                return twos.removeLast();
            }
            return -1;
        }

        private int useFour() {
            return fours.isEmpty() ? -1 : fours.removeLast();
        }

        public int[][] getResultMatrix() {
            return matrix;
        }
    }

    /**
     * Fast I/O implementation for efficient reading.
     */
    static class FastReader {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (numChars == -1) throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) return -1;
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isWhitespace(c)) c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res = res * 10 + (c - '0');
                c = read();
            } while (!isWhitespace(c));
            return res * sgn;
        }

        public int[] nextIntArray(int n) {
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) arr[i] = nextInt();
            return arr;
        }

        private boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }

    /**
     * Fast I/O implementation for efficient writing.
     */
    static class FastWriter {
        private final PrintWriter writer;

        public FastWriter(OutputStream outputStream) {
            this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public void println(Object obj) {
            writer.println(obj);
        }

        public void printMatrix(int[][] matrix) {
            for (int[] row : matrix) {
                for (int j = 0; j < row.length; j++) {
                    writer.print(row[j]);
                    if (j < row.length - 1) writer.print(" ");
                }
                writer.println();
            }
        }

        public void close() {
            writer.close();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solution to construct an n x n matrix such that the values are placed 
 * according to specific symmetry requirements (4-way, 2-way, or center).
 */
public class Solution {

    private static final int MAX_VALUE = 1000;
    private static final int FREQUENCY_ARRAY_SIZE = MAX_VALUE + 1;

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            String nStr = reader.next();
            if (nStr == null) return;

            int n = Integer.parseInt(nStr);
            int[] frequencies = new int[FREQUENCY_ARRAY_SIZE];

            // Read n*n integers and count their occurrences
            for (int i = 0; i < n * n; i++) {
                int val = reader.nextInt();
                if (val >= 0 && val < FREQUENCY_ARRAY_SIZE) {
                    frequencies[val]++;
                }
            }

            MatrixSymmetrySolver solver = new MatrixSymmetrySolver(n, frequencies);
            solver.solve(out);

        } catch (Exception e) {
            // Standard error handling for competitive programming environments
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Encapsulates the logic for constructing the symmetric matrix.
     */
    static class MatrixSymmetrySolver {
        private final int size;
        private final int[] frequencies;
        private final int[][] matrix;

        public MatrixSymmetrySolver(int size, int[] frequencies) {
            this.size = size;
            this.frequencies = frequencies;
            this.matrix = new int[size][size];
        }

        /**
         * Orchestrates the construction steps.
         */
        public void solve(PrintWriter out) {
            if (!fillFourWaySymmetry()) {
                out.println("NO");
                return;
            }

            // If n is odd, we must fill the middle cross and the center cell
            if (size % 2 != 0) {
                if (!fillTwoWaySymmetry() || !fillCenterCell()) {
                    out.println("NO");
                    return;
                }
            }

            out.println("YES");
            printMatrix(out);
        }

        /**
         * Fills cells that require 4-way symmetry: (i, j), (n-1-i, j), (i, n-1-j), (n-1-i, n-1-j).
         */
        private boolean fillFourWaySymmetry() {
            int half = size / 2;
            for (int i = 0; i < half; i++) {
                for (int j = 0; j < half; j++) {
                    int val = findAndConsume(4);
                    if (val == -1) return false;

                    matrix[i][j] = val;
                    matrix[size - 1 - i][j] = val;
                    matrix[i][size - 1 - j] = val;
                    matrix[size - 1 - i][size - 1 - j] = val;
                }
            }
            return true;
        }

        /**
         * Fills the middle row and middle column for odd-sized matrices.
         * These cells require 2-way symmetry.
         */
        private boolean fillTwoWaySymmetry() {
            int mid = size / 2;

            // Fill middle row (excluding center)
            for (int j = 0; j < mid; j++) {
                int val = findAndConsume(2);
                if (val == -1) return false;
                matrix[mid][j] = val;
                matrix[mid][size - 1 - j] = val;
            }

            // Fill middle column (excluding center)
            for (int i = 0; i < mid; i++) {
                int val = findAndConsume(2);
                if (val == -1) return false;
                matrix[i][mid] = val;
                matrix[size - 1 - i][mid] = val;
            }
            return true;
        }

        /**
         * Fills the single center cell for odd-sized matrices.
         */
        private boolean fillCenterCell() {
            int mid = size / 2;
            int val = findAndConsume(1);
            if (val == -1) return false;
            matrix[mid][mid] = val;
            return true;
        }

        /**
         * Searches for the first value that has enough remaining occurrences.
         * @param required The number of occurrences needed.
         * @return The value found, or -1 if no valid value exists.
         */
        private int findAndConsume(int required) {
            for (int i = 0; i < frequencies.length; i++) {
                if (frequencies[i] >= required) {
                    frequencies[i] -= required;
                    return i;
                }
            }
            return -1;
        }

        private void printMatrix(PrintWriter out) {
            for (int i = 0; i < size; i++) {
                for (int j = 0; j < size; j++) {
                    out.print(matrix[i][j]);
                    if (j < size - 1) {
                        out.print(" ");
                    }
                }
                out.println();
            }
        }
    }

    /**
     * Efficient reader for large input volumes.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String s = next();
            return (s == null) ? 0 : Integer.parseInt(s);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver for the symmetry puzzle problem.
 * The goal is to arrange N*N numbers into a matrix such that:
 * A[i][j] == A[N-1-i][j] == A[i][N-1-j] == A[N-1-i][N-1-j]
 */
public class Main {

    public static void main(String[] args) {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             BufferedWriter bw = new BufferedWriter(new OutputStreamWriter(System.out))) {

            String line = br.readLine();
            if (line == null) return;
            int n = Integer.parseInt(line.trim());

            Map<Integer, Integer> counts = new TreeMap<>();
            StringTokenizer st = new StringTokenizer(br.readLine());
            for (int i = 0; i < n * n; i++) {
                int val = Integer.parseInt(st.nextToken());
                counts.put(val, counts.getOrDefault(val, 0) + 1);
            }

            SymmetrySolver solver = new SymmetrySolver(n, counts);
            if (solver.solve()) {
                bw.write("YES\n");
                solver.printMatrix(bw);
            } else {
                bw.write("NO\n");
            }
            bw.flush();

        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /**
     * Represents a coordinate in the quadrant matrix.
     */
    private static class Point {
        final int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Handles the logic of placing numbers into a quadrant to satisfy global symmetry.
     */
    private static class SymmetrySolver {
        private final int n;
        private final int quadrantSize;
        private final Map<Integer, Integer> counts;
        private final int[][] quadrant;
        private final boolean isOdd;

        private final Queue<Point> quadSlots = new LinkedList<>();
        private final Queue<Point> pairSlots = new LinkedList<>();
        private Point centerSlot = null;

        public SymmetrySolver(int n, Map<Integer, Integer> counts) {
            this.n = n;
            this.counts = counts;
            this.isOdd = (n % 2 != 0);
            this.quadrantSize = (n + 1) / 2;
            this.quadrant = new int[quadrantSize][quadrantSize];
            initializeSlots();
        }

        /**
         * Identifies available symmetric positions in the quadrant.
         */
        private void initializeSlots() {
            if (isOdd) {
                // For odd N, the center is unique.
                // The middle row and column (excluding center) form pairs.
                // The remaining cells form quads.
                centerSlot = new Point(quadrantSize - 1, quadrantSize - 1);

                for (int i = 0; i < quadrantSize - 1; i++) {
                    pairSlots.add(new Point(quadrantSize - 1, i));
                    pairSlots.add(new Point(i, quadrantSize - 1));
                }

                for (int i = 0; i < quadrantSize - 1; i++) {
                    for (int j = 0; j < quadrantSize - 1; j++) {
                        quadSlots.add(new Point(i, j));
                    }
                }
            } else {
                // For even N, everything is a quad.
                for (int i = 0; i < quadrantSize; i++) {
                    for (int j = 0; j < quadrantSize; j++) {
                        quadSlots.add(new Point(i, j));
                    }
                }
            }
        }

        /**
         * Greedy algorithm to place numbers into slots.
         * Prioritizes quad slots, then pair slots, then center.
         */
        public boolean solve() {
            for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
                int val = entry.getKey();
                int remaining = entry.getValue();

                // 1. Fill quad slots
                while (remaining >= 4 && !quadSlots.isEmpty()) {
                    remaining -= 4;
                    Point p = quadSlots.poll();
                    quadrant[p.r][p.c] = val;
                }

                // 2. Fill pair slots
                while (remaining >= 2 && !pairSlots.isEmpty()) {
                    remaining -= 2;
                    Point p = pairSlots.poll();
                    quadrant[p.r][p.c] = val;
                }

                // 3. Fill center slot
                if (remaining >= 1 && centerSlot != null) {
                    remaining -= 1;
                    quadrant[centerSlot.r][centerSlot.c] = val;
                    centerSlot = null;
                }

                if (remaining > 0) return false;
            }

            // Ensure all required slots were filled
            return quadSlots.isEmpty() && pairSlots.isEmpty() && (isOdd ? centerSlot == null : true);
        }

        /**
         * Constructs and prints the full N*N matrix from the quadrant.
         */
        public void printMatrix(BufferedWriter bw) throws IOException {
            if (isOdd) {
                // Print top half and middle row
                for (int i = 0; i < quadrantSize; i++) {
                    printRow(bw, i, true);
                }
                // Print bottom half (mirroring middle row)
                for (int i = quadrantSize - 2; i >= 0; i--) {
                    printRow(bw, i, true);
                }
            } else {
                // Print top half
                for (int i = 0; i < quadrantSize; i++) {
                    printRow(bw, i, false);
                }
                // Print bottom half
                for (int i = quadrantSize - 1; i >= 0; i--) {
                    printRow(bw, i, false);
                }
            }
        }

        private void printRow(BufferedWriter bw, int r, boolean oddStyle) throws IOException {
            if (oddStyle) {
                // Row: [0...L-1] then [L-2...0]
                for (int j = 0; j < quadrantSize; j++) {
                    bw.write(quadrant[r][j] + " ");
                }
                for (int j = quadrantSize - 2; j >= 0; j--) {
                    bw.write(quadrant[r][j] + " ");
                }
            } else {
                // Row: [0...L-1] then [L-1...0]
                for (int j = 0; j < quadrantSize; j++) {
                    bw.write(quadrant[r][j] + " ");
                }
                for (int j = quadrantSize - 1; j >= 0; j--) {
                    bw.write(quadrant[r][j] + " ");
                }
            }
            bw.write("\n");
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A program to arrange a given set of numbers into an n x n grid 
 * with specific rotational/reflectional symmetry.
 * 
 * For even n: The grid is built using 4-way symmetry (quadrants are mirrors).
 * For odd n: The grid uses a center element (1), a middle-row/column cross (pairs), 
 * and the remaining corners (quads).
 */
public class SymmetryGridSolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = reader.nextInt();
        if (n <= 0) {
            out.close();
            return;
        }

        Map<Integer, Integer> frequencyMap = new HashMap<>();
        for (int i = 0; i < n * n; i++) {
            int val = reader.nextInt();
            frequencyMap.put(val, frequencyMap.getOrDefault(val, 0) + 1);
        }

        if (n % 2 == 0) {
            solveEven(n, frequencyMap, out);
        } else {
            solveOdd(n, frequencyMap, out);
        }

        out.flush();
        out.close();
    }

    /**
     * Handles the case where n is even.
     * All elements must come in sets of 4 to maintain the required symmetry.
     */
    private static void solveEven(int n, Map<Integer, Integer> frequencyMap, PrintWriter out) {
        List<Integer> quadList = new ArrayList<>();

        for (Map.Entry<Integer, Integer> entry : frequencyMap.entrySet()) {
            int val = entry.getKey();
            int count = entry.getValue();

            if (count % 4 != 0) {
                out.println("NO");
                return;
            }

            for (int i = 0; i < count / 4; i++) {
                quadList.add(val);
            }
        }

        // Check if we have enough quad sets to fill the n/2 * n/2 quadrants
        if (quadList.size() < (n / 2) * (n / 2)) {
            out.println("NO");
            return;
        }

        int[][] grid = new int[n][n];
        int quadIdx = 0;
        for (int i = 0; i < n / 2; i++) {
            for (int j = 0; j < n / 2; j++) {
                int val = quadList.get(quadIdx++);
                grid[i][j] = val;
                grid[n - 1 - i][j] = val;
                grid[i][n - 1 - j] = val;
                grid[n - 1 - i][n - 1 - j] = val;
            }
        }

        printGrid(grid, out);
    }

    /**
     * Handles the case where n is odd.
     * Requires 1 center element, (n-1) pairs for the cross, and (n/2)^2 quads for corners.
     */
    private static void solveOdd(int n, Map<Integer, Integer> frequencyMap, PrintWriter out) {
        List<Integer> ones = new ArrayList<>();
        List<Integer> twos = new ArrayList<>();
        List<Integer> quads = new ArrayList<>();

        for (Map.Entry<Integer, Integer> entry : frequencyMap.entrySet()) {
            int val = entry.getKey();
            int freq = entry.getValue();

            int qCount = freq / 4;
            int remainder = freq % 4;

            for (int i = 0; i < qCount; i++) {
                quads.add(val);
            }

            if (remainder == 1) {
                ones.add(val);
            } else if (remainder == 2) {
                twos.add(val);
            } else if (remainder == 3) {
                ones.add(val);
                twos.add(val);
            }
        }

        // Validation for odd n
        // 1. Must have exactly one candidate for the center
        if (ones.size() != 1) {
            out.println("NO");
            return;
        }

        int requiredQuads = (n / 2) * (n / 2);
        int requiredTwos = n - 1;

        // If we have too many quads, we can break them into pairs
        if (quads.size() > requiredQuads) {
            int excess = quads.size() - requiredQuads;
            for (int i = 0; i < excess; i++) {
                int val = quads.remove(0);
                twos.add(val);
                twos.add(val);
            }
        }

        // After potential conversion, check if we satisfy counts
        if (quads.size() < requiredQuads || twos.size() < requiredTwos) {
            out.println("NO");
            return;
        }

        int[][] grid = new int[n][n];
        int quadIdx = 0;
        int twoIdx = 0;

        // Fill Corners
        for (int i = 0; i < n / 2; i++) {
            for (int j = 0; j < n / 2; j++) {
                int val = quads.get(quadIdx++);
                grid[i][j] = val;
                grid[n - 1 - i][j] = val;
                grid[i][n - 1 - j] = val;
                grid[n - 1 - i][n - 1 - j] = val;
            }
        }

        // Fill Center
        grid[n / 2][n / 2] = ones.get(0);

        // Fill Middle Row Cross
        for (int i = 0; i < n / 2; i++) {
            int val = twos.get(twoIdx++);
            grid[n / 2][i] = val;
            grid[n / 2][n - 1 - i] = val;
        }

        // Fill Middle Column Cross
        for (int i = 0; i < n / 2; i++) {
            int val = twos.get(twoIdx++);
            grid[i][n / 2] = val;
            grid[n - 1 - i][n / 2] = val;
        }

        out.println("YES");
        printGrid(grid, out);
    }

    private static void printGrid(int[][] grid, PrintWriter out) {
        out.println("YES");
        for (int[] row : grid) {
            for (int i = 0; i < row.length; i++) {
                out.print(row[i] + (i == row.length - 1 ? "" : " "));
            }
            out.println();
        }
    }

    /**
     * Utility class for faster input reading.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

