/**
 * A solver for the Palindromic Matrix problem.
 * A matrix is palindromic if it is symmetric across its middle axes.
 */
public class Main {
    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        PalindromicMatrixSolver solver = new PalindromicMatrixSolver();
        solver.solve(in, out);

        out.close();
    }
}

class PalindromicMatrixSolver {

    /**
     * Represents the result of the solving attempt.
     */
    private static class SolutionResult {
        final boolean success;
        final int[][] matrix;

        SolutionResult(boolean success, int[][] matrix) {
            this.success = success;
            this.matrix = matrix;
        }
    }

    public void solve(InputReader in, PrintWriter out) {
        int n = in.nextInt();
        int[][] matrix = new int[n][n];
        Map<Integer, Integer> frequencyMap = new HashMap<>();

        for (int i = 0; i < n * n; i++) {
            int val = in.nextInt();
            frequencyMap.put(val, frequencyMap.getOrDefault(val, 0) + 1);
        }

        SolutionResult result = computePalindromicMatrix(n, frequencyMap);

        if (result.success) {
            out.println("YES");
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    sb.append(result.matrix[i][j]).append(j == n - 1 ? "" : " ");
                }
                sb.append("\n");
            }
            out.print(sb.toString());
        } else {
            out.println("NO");
        }
    }

    private SolutionResult computePalindromicMatrix(int n, Map<Integer, Integer> frequencyMap) {
        List<Integer> pool4 = new ArrayList<>();
        List<Integer> pool2 = new ArrayList<>();
        List<Integer> pool1 = new ArrayList<>();

        // Categorize frequencies into initial pools
        for (Map.Entry<Integer, Integer> entry : frequencyMap.entrySet()) {
            int val = entry.getKey();
            int freq = entry.getValue();

            int fours = freq / 4;
            int twos = (freq % 4) / 2;
            int ones = freq % 2;

            for (int i = 0; i < fours; i++) pool4.add(val);
            for (int i = 0; i < twos; i++) pool2.add(val);
            for (int i = 0; i < ones; i++) pool1.add(val);
        }

        // Requirements calculation
        int needed4 = (n / 2) * (n / 2);
        int needed2 = (n % 2 == 0) ? 0 : 2 * (n / 2);
        int needed1 = (n % 2 == 0) ? 0 : 1;

        // 1. Process 4-groups
        if (pool4.size() < needed4) return new SolutionResult(false, null);

        int[][] matrix = new int[n][n];
        int p4Idx = 0;
        for (int i = 0; i < n / 2; i++) {
            for (int j = 0; j < n / 2; j++) {
                int val = pool4.get(p4Idx++);
                fillSymmetric4(matrix, i, j, n, val);
            }
        }

        // 2. Demote remaining 4s into 2s
        for (int i = needed4; i < pool4.size(); i++) {
            int val = pool4.get(i);
            pool2.add(val);
            pool2.add(val);
        }

        // 3. Process 2-groups
        if (pool2.size() < needed2) return new SolutionResult(false, null);

        int p2Idx = 0;
        // Fill middle row (if n is odd)
        if (n % 2 != 0) {
            for (int i = 0; i < n / 2; i++) {
                int val = pool2.get(p2Idx++);
                matrix[i][n / 2] = matrix[n - 1 - i][n / 2] = val;
            }
            // Fill middle column (if n is odd)
            for (int j = 0; j < n / 2; j++) {
                int val = pool2.get(p2Idx++);
                matrix[n / 2][j] = matrix[n / 2][n - 1 - j] = val;
            }
        }

        // 4. Demote remaining 2s into 1s
        for (int i = needed2; i < pool2.size(); i++) {
            int val = pool2.get(i);
            pool1.add(val);
            pool1.add(val);
        }

        // 5. Process 1-group (center)
        if (n % 2 != 0) {
            if (pool1.isEmpty()) return new SolutionResult(false, null);
            matrix[n / 2][n / 2] = pool1.get(0);
        }

        return new SolutionResult(true, matrix);
    }

    private void fillSymmetric4(int[][] matrix, int i, int j, int n, int val) {
        matrix[i][j] = val;
        matrix[n - 1 - i][j] = val;
        matrix[i][n - 1 - j] = val;
        matrix[n - 1 - i][n - 1 - j] = val;
    }
}

