import java.util.*;

/**
 * A utility to solve the Palindromic Matrix problem.
 * A palindromic matrix is symmetric both horizontally and vertically.
 */
public class PalindromicMatrixSolver {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int size = scanner.nextInt();
        Map<Integer, Integer> frequencyMap = new TreeMap<>();

        for (int i = 0; i < size * size; i++) {
            if (scanner.hasNextInt()) {
                int num = scanner.nextInt();
                frequencyMap.put(num, frequencyMap.getOrDefault(num, 0) + 1);
            }
        }

        solve(size, frequencyMap);
        scanner.close();
    }

    /**
     * Orchestrates the logic to determine if a palindromic matrix can be formed.
     * 
     * @param n The dimension of the n x n matrix.
     * @param counts A map containing the frequency of each number.
     */
    private static void solve(int n, Map<Integer, Integer> counts) {
        if (n % 2 == 0) {
            handleEvenMatrix(n, counts);
        } else {
            handleOddMatrix(n, counts);
        }
    }

    /**
     * Logic for even-sized matrices. 
     * All numbers must appear in multiples of 4 to satisfy 4-way symmetry.
     */
    private static void handleEvenMatrix(int n, Map<Integer, Integer> counts) {
        for (int count : counts.values()) {
            if (count % 4 != 0) {
                System.out.println("NO");
                return;
            }
        }

        int[][] matrix = new int[n][n];
        int halfSize = n / 2;
        int cornerIdx = 0;

        for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
            int val = entry.getKey();
            int freq = entry.getValue();

            while (freq > 0) {
                int r = cornerIdx / halfSize;
                int c = cornerIdx % halfSize;

                fillFourCorners(matrix, r, c, n, val);

                cornerIdx++;
                freq -= 4;
            }
        }

        printResult(true, matrix);
    }

    /**
     * Logic for odd-sized matrices.
     * One number must have an odd frequency (for the center).
     * All other numbers must have even frequencies.
     */
    private static void handleOddMatrix(int n, Map<Integer, Integer> counts) {
        int oddCount = 0;
        int centerValue = -1;

        for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
            if (entry.getValue() % 2 != 0) {
                oddCount++;
                centerValue = entry.getKey();
            }
        }

        // In an odd n*n matrix, exactly one element must have an odd frequency
        if (oddCount != 1) {
            System.out.println("NO");
            return;
        }

        int[][] matrix = new int[n][n];
        int halfSize = n / 2;

        // Place the center element
        matrix[halfSize][halfSize] = centerValue;
        counts.put(centerValue, counts.get(centerValue) - 1);

        // 1. Fill the corner quadrants (4-way symmetry)
        int cornerIdx = 0;
        for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
            int val = entry.getKey();
            int freq = entry.getValue();
            while (freq >= 4 && cornerIdx < halfSize * halfSize) {
                int r = cornerIdx / halfSize;
                int c = cornerIdx % halfSize;
                fillFourCorners(matrix, r, c, n, val);
                freq -= 4;
                cornerIdx++;
            }
            entry.setValue(freq);
        }

        // 2. Fill the middle row (2-way symmetry)
        int rowIdx = 0;
        for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
            int val = entry.getKey();
            int freq = entry.getValue();
            while (freq >= 2 && rowIdx < halfSize) {
                matrix[halfSize][rowIdx] = val;
                matrix[halfSize][n - 1 - rowIdx] = val;
                freq -= 2;
                rowIdx++;
            }
            entry.setValue(freq);
        }

        // 3. Fill the middle column (2-way symmetry)
        int colIdx = 0;
        for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
            int val = entry.getKey();
            int freq = entry.getValue();
            while (freq >= 2 && colIdx < halfSize) {
                matrix[colIdx][halfSize] = val;
                matrix[n - 1 - colIdx][halfSize] = val;
                freq -= 2;
                colIdx++;
            }
            entry.setValue(freq);
        }

        // Validate that all numbers were used perfectly
        for (int remaining : counts.values()) {
            if (remaining != 0) {
                System.out.println("NO");
                return;
            }
        }

        printResult(true, matrix);
    }

    /**
     * Fills the four symmetric positions in a matrix for a single value.
     */
    private static void fillFourCorners(int[][] matrix, int r, int c, int n, int val) {
        matrix[r][c] = val;
        matrix[n - 1 - r][c] = val;
        matrix[r][n - 1 - c] = val;
        matrix[n - 1 - r][n - 1 - c] = val;
    }

    /**
     * Prints the matrix to standard output.
     */
    private static void printResult(boolean success, int[][] matrix) {
        if (!success) {
            System.out.println("NO");
            return;
        }

        System.out.println("YES");
        StringBuilder sb = new StringBuilder();
        for (int[] row : matrix) {
            for (int cell : row) {
                sb.append(cell).append(" ");
            }
            sb.append("\n");
        }
        System.out.print(sb.toString());
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to determine if a given set of numbers can form an NxN palindromic matrix.
 * A palindromic matrix is symmetric across both the horizontal and vertical axes.
 */
public class PalindromicMatrix {

    public static void main(String[] args) {
        PalindromicMatrix solver = new PalindromicMatrix();
        solver.run();
    }

    public void run() {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = reader.nextInt();
        if (n <= 0) {
            out.close();
            return;
        }

        Map<Integer, Integer> frequencyMap = new HashMap<>();
        for (int i = 0; i < n * n; i++) {
            int num = reader.nextInt();
            frequencyMap.put(num, frequencyMap.getOrDefault(num, 0) + 1);
        }

        int[][] matrix = new int[n][n];
        if (tryFillMatrix(n, frequencyMap, matrix)) {
            out.println("YES");
            printMatrix(matrix, out);
        } else {
            out.println("NO");
        }
        out.flush();
        out.close();
    }

    /**
     * Attempts to fill an NxN matrix following palindromic symmetry rules.
     * 
     * @param n The dimension of the matrix.
     * @param frequencyMap The available counts of each number.
     * @param matrix The matrix to be filled.
     * @return true if the matrix was successfully filled, false otherwise.
     */
    private boolean tryFillMatrix(int n, Map<Integer, Integer> frequencyMap, int[][] matrix) {
        List<List<int[]>> slots4 = new ArrayList<>();
        List<List<int[]>> slots2 = new ArrayList<>();
        List<List<int[]>> slots1 = new ArrayList<>();

        // Step 1: Generate symmetry slots based on coordinate groups
        boolean[][] visited = new boolean[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (!visited[i][j]) {
                    List<int[]> group = new ArrayList<>();
                    // A cell (i, j) is part of a group including its mirror images
                    int[][] targets = {
                        {i, j},
                        {i, n - 1 - j},
                        {n - 1 - i, j},
                        {n - 1 - i, n - 1 - j}
                    };

                    for (int[] target : targets) {
                        int r = target[0];
                        int c = target[1];
                        if (!visited[r][c]) {
                            visited[r][c] = true;
                            group.add(new int[]{r, c});
                        }
                    }

                    // Sort to ensure consistent group identification
                    group.sort((a, b) -> a[0] == b[0] ? a[1] - b[1] : a[0] - b[0]);

                    if (group.size() == 4) slots4.add(group);
                    else if (group.size() == 2) slots2.add(group);
                    else if (group.size() == 1) slots1.add(group);
                }
            }
        }

        // Step 2: Greedily fill the slots
        // We prioritize larger slots because they are harder to satisfy.
        for (Map.Entry<Integer, Integer> entry : frequencyMap.entrySet()) {
            int val = entry.getKey();
            int count = entry.getValue();

            // Use 4-sized slots
            while (count >= 4 && !slots4.isEmpty()) {
                fillGroup(matrix, slots4.remove(slots4.size() - 1), val);
                count -= 4;
            }
            // Use 2-sized slots (remaining count or leftovers from 4s)
            while (count >= 2 && !slots2.isEmpty()) {
                fillGroup(matrix, slots2.remove(slots2.size() - 1), val);
                count -= 2;
            }
            // Use 1-sized slots
            while (count >= 1 && !slots1.isEmpty()) {
                fillGroup(matrix, slots1.remove(slots1.size() - 1), val);
                count -= 1;
            }

            if (count > 0) return false; // Remaining numbers cannot form complete groups
        }

        // Check if all required symmetry slots were filled
        return slots4.isEmpty() && slots2.isEmpty() && slots1.isEmpty();
    }

    private void fillGroup(int[][] matrix, List<int[]> group, int val) {
        for (int[] pos : group) {
            matrix[pos[0]][pos[1]] = val;
        }
    }

    private void printMatrix(int[][] matrix, PrintWriter out) {
        StringBuilder sb = new StringBuilder();
        for (int[] row : matrix) {
            for (int cell : row) {
                sb.append(cell).append(" ");
            }
            sb.append("\n");
        }
        out.print(sb.toString());
    }

    /**
     * Fast I/O utility.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;

/**
 * A tool to construct a centrosymmetric matrix from a given set of integers.
 * A matrix is centrosymmetric if elements are symmetric relative to the center.
 */
public class CentrosymmetricMatrixBuilder {

    /**
     * Represents the result of a matrix construction attempt.
     */
    private static class ConstructionResult {
        private final int[][] matrix;
        private final boolean success;

        public ConstructionResult(int[][] matrix, boolean success) {
            this.matrix = matrix;
            this.success = success;
        }

        public boolean isPossible() {
            return success;
        }

        public int[][] getMatrix() {
            return matrix;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int n = scanner.nextInt();
        int totalElements = n * n;
        int[] elements = new int[totalElements];

        for (int i = 0; i < totalElements; i++) {
            if (scanner.hasNextInt()) {
                elements[i] = scanner.nextInt();
            }
        }
        scanner.close();

        ConstructionResult result = solve(n, elements);

        if (result.isPossible()) {
            System.out.println("YES");
            printMatrix(result.getMatrix());
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Orchestrates the logic to build the centrosymmetric matrix.
     *
     * @param n        The dimension of the n x n matrix.
     * @param elements The array of integers to be placed in the matrix.
     * @return A ConstructionResult containing the matrix or a failure status.
     */
    private static ConstructionResult solve(int n, int[] elements) {
        Map<Integer, Integer> frequencyMap = new HashMap<>();
        for (int val : elements) {
            frequencyMap.put(val, frequencyMap.getOrDefault(val, 0) + 1);
        }

        // Grouping elements into available sets of 4, 2, and 1
        List<Integer> pool4 = new LinkedList<>();
        List<Integer> pool2 = new LinkedList<>();
        List<Integer> pool1 = new LinkedList<>();

        for (Map.Entry<Integer, Integer> entry : frequencyMap.entrySet()) {
            int value = entry.getKey();
            int count = entry.getValue();

            int setsOfFour = count / 4;
            for (int i = 0; i < setsOfFour; i++) pool4.add(value);

            int remainingAfterFour = count % 4;
            int setsOfTwo = remainingAfterFour / 2;
            for (int i = 0; i < setsOfTwo; i++) pool2.add(value);

            int remainingAfterTwo = remainingAfterFour % 2;
            if (remainingAfterTwo == 1) pool1.add(value);
        }

        int[][] matrix = new int[n][n];
        int cornersNeeded = (n / 2) * (n / 2);

        if (pool4.size() < cornersNeeded) {
            return new ConstructionResult(null, false);
        }

        // 1. Fill the four-corner symmetry groups
        for (int i = 0; i < n / 2; i++) {
            for (int j = 0; j < n / 2; j++) {
                int val = pool4.remove(0);
                matrix[i][j] = val;
                matrix[i][n - 1 - j] = val;
                matrix[n - 1 - i][j] = val;
                matrix[n - 1 - i][n - 1 - j] = val;
            }
        }

        // 2. Handle middle axis for odd-sized matrices
        if (n % 2 != 0) {
            // Convert any leftover 4-groups into 2-groups
            while (!pool4.isEmpty()) {
                int val = pool4.remove(0);
                pool2.add(val);
                pool2.add(val);
            }

            // Fill the middle row and middle column symmetry groups
            int axisGroupsNeeded = n - 1; 
            if (pool2.size() < axisGroupsNeeded) {
                return new ConstructionResult(null, false);
            }

            // Fill middle row (excluding center)
            for (int i = 0; i < n / 2; i++) {
                int val = pool2.remove(0);
                matrix[n / 2][i] = val;
                matrix[n / 2][n - 1 - i] = val;
            }

            // Fill middle column (excluding center)
            for (int i = 0; i < n / 2; i++) {
                int val = pool2.remove(0);
                matrix[i][n / 2] = val;
                matrix[n - 1 - i][n / 2] = val;
            }

            // Fill the center cell
            if (pool1.size() != 1) {
                return new ConstructionResult(null, false);
            }
            matrix[n / 2][n / 2] = pool1.remove(0);

            // Ensure no elements are left over
            if (!pool2.isEmpty() || !pool1.isEmpty()) {
                return new ConstructionResult(null, false);
            }
        }

        return new ConstructionResult(matrix, true);
    }

    /**
     * Efficiently prints the matrix using StringBuilder.
     */
    private static void printMatrix(int[][] matrix) {
        StringBuilder sb = new StringBuilder();
        for (int[] row : matrix) {
            for (int i = 0; i < row.length; i++) {
                sb.append(row[i]);
                if (i < row.length - 1) {
                    sb.append(" ");
                }
            }
            sb.append("\n");
        }
        System.out.print(sb.toString());
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to solve the symmetric grid problem.
 * The goal is to arrange n*n numbers into an n x n grid such that
 * the grid is symmetric across its horizontal, vertical, and diagonal axes.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int gridSize = reader.nextInt();
            int[] inputNumbers = new int[gridSize * gridSize];
            for (int i = 0; i < gridSize * gridSize; i++) {
                inputNumbers[i] = reader.nextInt();
            }

            SymmetricGridSolver solver = new SymmetricGridSolver(gridSize, inputNumbers);
            SymmetricGridSolver.Result result = solver.solve();

            if (result.isSuccess()) {
                writer.println("YES");
                result.printGrid(writer);
            } else {
                writer.println("NO");
            }
        } catch (Exception e) {
            // In a competitive programming context, we might just print nothing or error.
            // In a production context, we would use a logger.
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Core logic for solving the symmetric grid problem.
     */
    static class SymmetricGridSolver {
        private static final int MAX_VAL = 1000;
        private final int gridSize;
        private final int[] counts;
        private final int[][] grid;

        public SymmetricGridSolver(int gridSize, int[] inputNumbers) {
            this.gridSize = gridSize;
            this.counts = new int[MAX_VAL + 1];
            this.grid = new int[gridSize][gridSize];

            for (int num : inputNumbers) {
                if (num >= 0 && num <= MAX_VAL) {
                    counts[num]++;
                }
            }
        }

        /**
         * Represents the outcome of the solver.
         */
        public static class Result {
            private final boolean success;
            private final int[][] grid;

            public Result(boolean success, int[][] grid) {
                this.success = success;
                this.grid = grid;
            }

            public boolean isSuccess() {
                return success;
            }

            public void printGrid(PrintWriter out) {
                for (int[] row : grid) {
                    for (int i = 0; i < row.length; i++) {
                        out.print(row[i] + (i == row.length - 1 ? "" : " "));
                    }
                    out.println();
                }
            }
        }

        public Result solve() {
            // 1. Fill 4-way symmetric cells (Quadrants)
            // These cells have 4 symmetric counterparts (or are the same cell if n=0).
            for (int i = 0; i < gridSize / 2; i++) {
                for (int j = 0; j < gridSize / 2; j++) {
                    if (!fillQuadrant(i, j)) return new Result(false, null);
                }
            }

            // 2. Handle the middle row/column if the dimension is odd
            if (gridSize % 2 != 0) {
                int mid = gridSize / 2;

                // Fill middle row pairs (excluding the center cell)
                for (int j = 0; j < mid; j++) {
                    if (!fillPair(mid, j, mid, gridSize - 1 - j)) return new Result(false, null);
                }

                // Fill middle column pairs (excluding the center cell)
                for (int i = 0; i < mid; i++) {
                    if (!fillPair(i, mid, gridSize - 1 - i, mid)) return new Result(false, null);
                }

                // Fill the absolute center cell
                if (!fillSingle(mid, mid)) return new Result(false, null);
            }

            // 3. Final Validation: Ensure all input numbers were used exactly
            for (int count : counts) {
                if (count != 0) return new Result(false, null);
            }

            return new Result(true, grid);
        }

        private boolean fillQuadrant(int i, int j) {
            int val = findAndConsume(4);
            if (val == -1) return false;

            int mirrorI = gridSize - 1 - i;
            int mirrorJ = gridSize - 1 - j;

            grid[i][j] = val;
            grid[i][mirrorJ] = val;
            grid[mirrorI][j] = val;
            grid[mirrorI][mirrorJ] = val;
            return true;
        }

        private boolean fillPair(int r1, int c1, int r2, int c2) {
            int val = findAndConsume(2);
            if (val == -1) return false;

            grid[r1][c1] = val;
            grid[r2][c2] = val;
            return true;
        }

        private boolean fillSingle(int r, int c) {
            int val = findAndConsume(1);
            if (val == -1) return false;

            grid[r][c] = val;
            return true;
        }

        /**
         * Greedily finds the first available number with enough frequency.
         * @param amount The required count of the number.
         * @return The number found, or -1 if no such number exists.
         */
        private int findAndConsume(int amount) {
            for (int k = 0; k <= MAX_VAL; k++) {
                if (counts[k] >= amount) {
                    counts[k] -= amount;
                    return k;
                }
            }
            return -1;
        }
    }

    /**
     * Utility class for fast I/O.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A solver for constructing an n x n matrix where for every cell (i, j),
 * the values at (i, j), (n-1-i, j), (i, n-1-j), and (n-1-i, n-1-j) are identical.
 */
public class SymmetricMatrixBuilder {

    private static final int MAX_VALUE = 1005;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) return;

        int n = scanner.nextInt();
        int[] counts = new int[MAX_VALUE];
        for (int i = 0; i < n * n; i++) {
            counts[scanner.nextInt()]++;
        }

        SymmetricMatrixSolver solver = new SymmetricMatrixSolver(n, counts);
        if (solver.solve()) {
            solver.printMatrix();
        } else {
            System.out.println("NO");
        }
    }

    static class Matrix {
        private final int n;
        private final int[][] grid;

        public Matrix(int n) {
            this.n = n;
            this.grid = new int[n][n];
        }

        public void setCell(int r, int c, int val) {
            grid[r][c] = val;
        }

        public void setQuad(int r, int c, int val) {
            grid[r][c] = val;
            grid[n - 1 - r][c] = val;
            grid[r][n - 1 - c] = val;
            grid[n - 1 - r][n - 1 - c] = val;
        }

        public void setPairVertical(int r, int c, int val) {
            grid[r][c] = val;
            grid[n - 1 - r][c] = val;
        }

        public void setPairHorizontal(int r, int c, int val) {
            grid[r][c] = val;
            grid[r][n - 1 - c] = val;
        }

        public void print() {
            StringBuilder sb = new StringBuilder();
            for (int[] row : grid) {
                for (int cell : row) {
                    sb.append(cell).append(" ");
                }
                sb.append("\n");
            }
            System.out.print(sb.toString());
        }
    }

    static class SymmetricMatrixSolver {
        private final int n;
        private final int[] counts;
        private Matrix matrix;

        public SymmetricMatrixSolver(int n, int[] counts) {
            this.n = n;
            this.counts = counts.clone();
            this.matrix = new Matrix(n);
        }

        public boolean solve() {
            if (n % 2 == 0) {
                return solveEven();
            } else {
                return solveOdd();
            }
        }

        private boolean solveEven() {
            // For even n, every number must appear in multiples of 4
            for (int count : counts) {
                if (count % 4 != 0) return false;
            }

            fillQuads();
            return true;
        }

        private boolean solveOdd() {
            int centerVal = -1;
            int oddCount = 0;

            // 1. Find the center element (must be the only odd frequency)
            for (int i = 0; i < MAX_VALUE; i++) {
                if (counts[i] % 2 != 0) {
                    oddCount++;
                    centerVal = i;
                }
            }

            if (oddCount != 1) return false;

            counts[centerVal]--;
            matrix.setCell(n / 2, n / 2, centerVal);

            // 2. Prepare pools for axes (pairs) and quadrants (quads)
            // After subtracting center, all counts are even. 
            // k[i] is the number of pairs available for number i.
            int[] k = new int[MAX_VALUE];
            List<Integer> oddKIndices = new ArrayList<>();
            List<Integer> evenKIndices = new ArrayList<>();

            for (int i = 0; i < MAX_VALUE; i++) {
                k[i] = counts[i] / 2;
                if (k[i] == 0) continue;

                if (k[i] % 2 != 0) {
                    oddKIndices.add(i);
                } else {
                    evenKIndices.add(i);
                }
            }

            // 3. Validate axis pair requirements
            // We need n-1 pairs for the axes (n/2 vertical + n/2 horizontal)
            int requiredAxisPairs = n - 1;
            if (oddKIndices.size() > requiredAxisPairs) return false;

            // If the remaining required pairs are not even, we can't form them from even K's
            int remainingNeeded = requiredAxisPairs - oddKIndices.size();
            if (remainingNeeded % 2 != 0) return false;

            if (evenKIndices.size() < (remainingNeeded / 2)) return false;

            // 4. Fill the axes
            int axisCount = 0;
            // Fill using odd K elements
            for (int idx : oddKIndices) {
                fillAxisPair(idx, axisCount++);
                k[idx]--;
            }
            // Fill using even K elements (taking 2 pairs/1 quad at a time to keep remainder even)
            for (int i = 0; i < remainingNeeded / 2; i++) {
                int idx = evenKIndices.get(i);
                fillAxisPair(idx, axisCount++);
                fillAxisPair(idx, axisCount++);
                k[idx] -= 2;
            }

            // 5. Fill the rest with quads
            fillRemainingQuads(k);
            return true;
        }

        private void fillAxisPair(int val, int pairIndex) {
            // Standard axis mapping: first half vertical, second half horizontal
            int half = n / 2;
            if (pairIndex < half) {
                matrix.setPairVertical(pairIndex, half, val);
            } else {
                int j = pairIndex - half;
                matrix.setPairHorizontal(half, j, val);
            }
        }

        private void fillQuads() {
            int[] k = new int[MAX_VALUE];
            for (int i = 0; i < MAX_VALUE; i++) k[i] = counts[i] / 4;
            fillRemainingQuads(k);
        }

        private void fillRemainingQuads(int[] k) {
            // Fill quadrants (all 4-way symmetric cells)
            for (int i = 0; i < n / 2; i++) {
                for (int j = 0; j < n / 2; j++) {
                    // Find next available quad
                    boolean found = false;
                    for (int v = 0; v < MAX_VALUE; v++) {
                        if (k[v] > 0) {
                            matrix.setQuad(i, j, v);
                            k[v]--;
                            found = true;
                            break;
                        }
                    }
                    if (!found) return; // Should not happen if logic is correct
                }
            }
        }

        public void printMatrix() {
            System.out.println("YES");
            matrix.print();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver to construct a symmetric n x n grid from a given set of numbers.
 * The grid is constructed such that elements are placed symmetrically around the center.
 */
public class Main {

    public static void main(String[] args) {
        new SymmetricGridSolver().solve();
    }
}

class SymmetricGridSolver {

    private final FastReader reader = new FastReader(System.in);
    private final PrintWriter writer = new PrintWriter(System.out);

    /**
     * Represents a group of identical numbers that will be placed in the grid together.
     */
    private static class NumberBlock implements Comparable<NumberBlock> {
        final int value;
        int remainingCount;
        final int priority;

        NumberBlock(int value, int count) {
            this.value = value;
            this.remainingCount = count;
            // Priority: 1-blocks (0), 2-blocks (1), 4+-blocks (2)
            if (count % 4 == 0) {
                this.priority = 2;
            } else if (count % 2 == 0) {
                this.priority = 1;
            } else {
                this.priority = 0;
            }
        }

        @Override
        public int compareTo(NumberBlock other) {
            return Integer.compare(this.priority, other.priority);
        }
    }

    public void solve() {
        try {
            int n = reader.nextInt();
            if (n == 1) {
                int val = reader.nextInt();
                writer.println("YES");
                writer.println(val);
                writer.flush();
                return;
            }

            // 1. Count frequencies of all input numbers
            Map<Integer, Integer> frequencyMap = new HashMap<>();
            int totalElements = n * n;
            for (int i = 0; i < totalElements; i++) {
                int val = reader.nextInt();
                frequencyMap.put(val, frequencyMap.getOrDefault(val, 0) + 1);
            }

            // 2. Decompose frequencies into blocks of 1, 2, and 4+
            List<NumberBlock> blocks = new ArrayList<>();
            int oneBlockCount = 0;
            int twoBlockCount = 0;

            for (Map.Entry<Integer, Integer> entry : frequencyMap.entrySet()) {
                int val = entry.getKey();
                int count = entry.getValue();

                if (count % 2 != 0) {
                    blocks.add(new NumberBlock(val, 1));
                    oneBlockCount++;
                    count--;
                }
                if (count % 4 != 0) {
                    blocks.add(new NumberBlock(val, 2));
                    twoBlockCount++;
                    count -= 2;
                }
                if (count > 0) {
                    blocks.add(new NumberBlock(val, count));
                }
            }

            // 3. Validate if the blocks satisfy the symmetry requirements
            // For even n: only 4-blocks are allowed.
            // For odd n: exactly one 1-block and 2*(n/2) 2-blocks are required.
            boolean possible = true;
            if (n % 2 == 0) {
                if (oneBlockCount != 0 || twoBlockCount != 0) {
                    possible = false;
                }
            } else {
                int requiredTwoBlocks = 2 * (n / 2);
                if (oneBlockCount != 1 || twoBlockCount != requiredTwoBlocks) {
                    possible = false;
                }
            }

            if (!possible) {
                writer.println("NO");
                writer.flush();
                return;
            }

            // 4. Sort blocks by priority (1s, then 2s, then 4s) to fill the grid symmetrically
            Collections.sort(blocks);
            int blockIndex = 0;

            // Helper to consume a block of size 't'
            // Using an array to allow modification within the lambda if needed, 
            // though here we just use the blockIndex and update the object.
            int[][] grid = new int[n][n];

            // Fill grid mapping logic
            // Symmetry pattern: center (1), middle row/col (2), the rest (4)
            int halfSize = n / 2 + n % 2;

            // Fill 4-blocks (the bulk of the grid)
            for (int i = 0; i < n / 2; i++) {
                for (int j = 0; j < n / 2; j++) {
                    grid[i][j] = consumeBlock(blocks, blockIndex++, 4);
                }
            }

            // Fill 2-blocks (middle row/col for odd n)
            if (n % 2 != 0) {
                // Center cell
                grid[halfSize - 1][halfSize - 1] = consumeBlock(blocks, blockIndex++, 1);
                // Middle row and column
                for (int i = 0; i < n / 2; i++) {
                    grid[halfSize - 1][i] = consumeBlock(blocks, blockIndex++, 2);
                    grid[i][halfSize - 1] = consumeBlock(blocks, blockIndex++, 2);
                }
            }

            // Note: The consumeBlock logic above needs careful mapping. 
            // Let's use a more direct approach to fill the grid based on the symmetry indices.
            // We re-initialize to ensure we don't have order-of-operation issues.
            grid = new int[n][n];
            blockIndex = 0;
            // Re-sort is redundant but keeps it clean
            Collections.sort(blocks);

            // Filling Strategy:
            // 1. Fill 1-blocks if n is odd
            // 2. Fill 2-blocks if n is odd
            // 3. Fill 4-blocks

            // Re-calculating assignments to match the specific cell group requirements
            if (n % 2 != 0) {
                int center = halfSize - 1;
                grid[center][center] = consumeBlock(blocks, blockIndex++, 1);
                for (int i = 0; i < n / 2; i++) {
                    int val = consumeBlock(blocks, blockIndex++, 2);
                    grid[center][i] = val;
                    grid[i][center] = val;
                }
            }

            // Fill the remaining 4-blocks in the top-left quadrant
            for (int i = 0; i < n / 2; i++) {
                for (int j = 0; j < n / 2; j++) {
                    grid[i][j] = consumeBlock(blocks, blockIndex++, 4);
                }
            }

            // 5. Output the completed grid with symmetry expansion
            writer.println("YES");
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    // Mirror indices to build the full grid from the quadrant/middle logic
                    int x = (i >= halfSize) ? (n - 1 - i) : i;
                    int y = (j >= halfSize) ? (n - 1 - j) : j;
                    writer.print(grid[x][y] + (j == n - 1 ? "" : " "));
                }
                writer.println();
            }

        } catch (Exception e) {
            // In a real production environment, use proper logging
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Safely consumes 't' units from the current block in the list.
     */
    private int consumeBlock(List<NumberBlock> blocks, int index, int t) {
        NumberBlock block = blocks.get(index);
        int value = block.value;
        block.remainingCount -= t;
        return value;
    }

    /**
     * Efficient input reader for competitive programming patterns.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to arrange integers in an n x n grid such that they satisfy
 * specific symmetry requirements.
 */
public class Main {
    private static final int MAX_VALUE = 1000;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = sc.nextInt();
        int totalElements = n * n;
        int[] counts = new int[MAX_VALUE + 1];

        for (int i = 0; i < totalElements; i++) {
            int val = sc.nextInt();
            if (val <= MAX_VALUE) {
                counts[val]++;
            }
        }

        SymmetrySolver solver = new SymmetrySolver(n, counts);
        if (solver.solve()) {
            out.println("YES");
            solver.printGrid(out);
        } else {
            out.println("NO");
        }
        out.flush();
        out.close();
    }

    /**
     * Handles the core logic of determining if a symmetric grid can be formed.
     */
    static class SymmetrySolver {
        private final int n;
        private final int[] counts;
        private final SymmetryGrid grid;

        public SymmetrySolver(int n, int[] counts) {
            this.n = n;
            this.counts = counts;
            this.grid = new SymmetryGrid(n);
        }

        public boolean solve() {
            if (n % 2 == 0) {
                return solveEven();
            } else {
                return solveOdd();
            }
        }

        private boolean solveEven() {
            int qRow = 0;
            int qCol = 0;
            int quadLimit = n / 2;

            for (int i = 1; i <= MAX_VALUE; i++) {
                if (counts[i] == 0) continue;
                if (counts[i] % 4 != 0) return false;

                int groupsOfFour = counts[i] / 4;
                for (int g = 0; g < groupsOfFour; g++) {
                    if (qRow >= quadLimit) return false;
                    grid.fillQuad(qRow, qCol, i);
                    qCol++;
                    if (qCol == quadLimit) {
                        qCol = 0;
                        qRow++;
                    }
                }
            }
            return true;
        }

        private boolean solveOdd() {
            int centerVal = -1;
            int centerCount = 0;

            // 1. Identify the center element
            for (int i = 1; i <= MAX_VALUE; i++) {
                if (counts[i] % 2 != 0) {
                    centerCount++;
                    centerVal = i;
                }
            }

            if (centerCount != 1) return false;

            // 2. Prepare to fill slots
            int axisPairsAvailable = n - 1;
            int axisIdx = 0;
            int qRow = 0;
            int qCol = 0;
            int quadLimit = n / 2;

            // Place center
            grid.fillCenter(centerVal);
            counts[centerVal]--;

            // 3. Fill the grid
            for (int i = 1; i <= MAX_VALUE; i++) {
                while (counts[i] > 0) {
                    if (counts[i] % 4 == 2) {
                        // Must use an axis pair
                        if (axisIdx >= axisPairsAvailable) return false;
                        grid.fillAxisPair(axisIdx, n);
                        // We need to find which value to put in that pair. 
                        // However, the grid.fillAxisPair implementation below 
                        // is generalized, so we pass the value i.
                        grid.setAxisPairValue(axisIdx, n, i);

                        axisIdx++;
                        counts[i] -= 2;
                    } else {
                        // Must use quad slots
                        if (qRow >= quadLimit) return false;
                        grid.fillQuad(qRow, qCol, i);
                        qCol++;
                        if (qCol == quadLimit) {
                            qCol = 0;
                            qRow++;
                        }
                        counts[i] -= 4;
                    }
                }
            }
            return true;
        }

        public void printGrid(PrintWriter out) {
            grid.print(out);
        }
    }

    /**
     * Manages the 2D array and handles symmetric placement patterns.
     */
    static class SymmetryGrid {
        private final int n;
        private final int[][] data;

        public SymmetryGrid(int n) {
            this.n = n;
            this.data = new int[n][n];
        }

        public void fillQuad(int r, int c, int val) {
            data[r][c] = val;
            data[n - 1 - r][c] = val;
            data[r][n - 1 - c] = val;
            data[n - 1 - r][n - 1 - c] = val;
        }

        public void setAxisPairValue(int axisIdx, int n, int val) {
            int half = n / 2;
            if (axisIdx < half) {
                // Vertical axis pairs
                data[axisIdx][half] = val;
                data[n - 1 - axisIdx][half] = val;
            } else {
                // Horizontal axis pairs
                int hIdx = axisIdx - half;
                data[half][hIdx] = val;
                data[half][n - 1 - hIdx] = val;
            }
        }

        // This is a helper to bridge the solver logic
        public void fillAxisPair(int axisIdx, int n) {
            // Not used directly by solver anymore, logic moved to setAxisPairValue
        }

        public void fillCenter(int val) {
            data[n / 2][n / 2] = val;
        }

        public void print(PrintWriter out) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    out.print(data[i][j] + (j == n - 1 ? "" : " "));
                }
                out.println();
            }
        }
    }

    /**
     * Fast I/O utility.
     */
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int buflen = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private boolean hasNextByte() {
            if (ptr < buflen) return true;
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                return false;
            }
            return buflen > 0;
        }

        private int readByte() {
            if (hasNextByte()) return buffer[ptr++];
            else return -1;
        }

        private static boolean isPrintableChar(int c) {
            return 33 <= c && c <= 126;
        }

        private void skipUnprintable() {
            while (hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++;
        }

        public String next() {
            if (!hasNextByte()) throw new NoSuchElementException();
            StringBuilder sb = new StringBuilder();
            int b = readByte();
            while (isPrintableChar(b)) {
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * This program determines if a given set of numbers can form an N x N matrix 
 * with specific symmetric properties and constructs that matrix if possible.
 */
public class Main {
    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        SymmetrySolver solver = new SymmetrySolver(reader, writer);
        solver.solve();

        writer.flush();
        writer.close();
    }

    static class SymmetrySolver {
        private final FastReader reader;
        private final PrintWriter writer;

        private int matrixSize;
        private List<Integer> quadruplets = new ArrayList<>();
        private List<Integer> pairs = new ArrayList<>();
        private List<Integer> singles = new ArrayList<>();
        private int[][] resultMatrix;

        public SymmetrySolver(FastReader reader, PrintWriter writer) {
            this.reader = reader;
            this.writer = writer;
        }

        public void solve() {
            matrixSize = reader.nextInt();
            Map<Integer, Integer> frequencyMap = new HashMap<>();

            // 1. Count frequencies of all elements in the N x N grid
            for (int i = 0; i < matrixSize * matrixSize; i++) {
                int value = reader.nextInt();
                frequencyMap.put(value, frequencyMap.getOrDefault(value, 0) + 1);
            }

            // 2. Categorize numbers into groups of 4, 2, or 1
            categorizeFrequencies(frequencyMap);

            // 3. Calculate requirements based on matrix size
            int requiredQuadruplets = (matrixSize / 2) * (matrixSize / 2);
            int requiredPairs = (matrixSize % 2 == 0) ? 0 : (matrixSize - 1);
            int requiredSingles = (matrixSize % 2 == 0) ? 0 : 1;

            // 4. Balance groups: Convert 4-groups into two 2-groups if we have too many 4-groups
            // This helps satisfy the 'pairs' requirement for odd-sized matrices.
            while (quadruplets.size() > requiredQuadruplets) {
                int val = quadruplets.remove(quadruplets.size() - 1);
                pairs.add(val);
                pairs.add(val);
            }

            // 5. Validation
            if (quadruplets.size() == requiredQuadruplets &&
                pairs.size() == requiredPairs &&
                singles.size() == requiredSingles) {

                writer.println("YES");
                constructMatrix();
                printMatrix();
            } else {
                writer.println("NO");
            }
        }

        private void categorizeFrequencies(Map<Integer, Integer> frequencyMap) {
            for (Map.Entry<Integer, Integer> entry : frequencyMap.entrySet()) {
                int val = entry.getKey();
                int count = entry.getValue();

                int numQuads = count / 4;
                int remainder = count % 4;

                for (int i = 0; i < numQuads; i++) {
                    quadruplets.add(val);
                }

                if (remainder == 1) {
                    singles.add(val);
                } else if (remainder == 2) {
                    pairs.add(val);
                } else if (remainder == 3) {
                    pairs.add(val);
                    singles.add(val);
                }
            }
        }

        /**
         * Fills the matrix using the symmetric layers logic.
         * The pattern fills corners of concentric squares, the middle cross, and the center.
         */
        private void constructMatrix() {
            resultMatrix = new int[matrixSize][matrixSize];
            int quadIdx = 0;
            int pairIdx = 0;
            int singleIdx = 0;

            for (int c1 = 0, c2 = matrixSize - 1; c1 <= c2; c1++, c2--) {
                for (int r1 = 0, r2 = matrixSize - 1; r1 <= r2; r1++, r2--) {

                    if (r1 != r2 && c1 != c2) {
                        // Fill 4-way symmetric corners
                        int val = quadruplets.get(quadIdx++);
                        resultMatrix[r1][c1] = resultMatrix[r1][c2] = 
                        resultMatrix[r2][c1] = resultMatrix[r2][c2] = val;
                    } else if (r1 == r2 && c1 == c2) {
                        // Fill the single center element (for odd N)
                        resultMatrix[r1][c1] = singles.get(singleIdx++);
                    } else if (r1 == r2) {
                        // Fill 2-way symmetric horizontal elements
                        int val = pairs.get(pairIdx++);
                        resultMatrix[r1][c1] = resultMatrix[r1][c2] = val;
                    } else if (c1 == c2) {
                        // Fill 2-way symmetric vertical elements
                        int val = pairs.get(pairIdx++);
                        resultMatrix[r1][c1] = resultMatrix[r2][c1] = val;
                    }
                }
            }
        }

        private void printMatrix() {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < matrixSize; i++) {
                for (int j = 0; j < matrixSize; j++) {
                    sb.append(resultMatrix[i][j]).append(j == matrixSize - 1 ? "" : " ");
                }
                sb.append("\n");
            }
            writer.print(sb.toString());
        }
    }

    /**
     * Fast I/O utility for efficient reading of large input datasets.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * SymmetricMatrix solves the problem of constructing a rotationally/reflectionally
 * symmetric matrix using a given set of numbers.
 */
public class SymmetricMatrix {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = reader.nextInt();
            int totalElements = n * n;
            int[] elements = new int[totalElements];
            for (int i = 0; i < totalElements; i++) {
                elements[i] = reader.nextInt();
            }

            solve(n, elements, out);
        } catch (Exception e) {
            // Handle or log exception as per application requirements
        } finally {
            out.flush();
            out.close();
        }
    }

    private static void solve(int n, int[] elements, PrintWriter out) {
        TreeMap<Integer, Integer> frequencyMap = new TreeMap<>();
        for (int val : elements) {
            frequencyMap.put(val, frequencyMap.getOrDefault(val, 0) + 1);
        }

        Deque<Integer> quads = new ArrayDeque<>();
        Deque<Integer> pairs = new ArrayDeque<>();
        Deque<Integer> singles = new ArrayDeque<>();

        // Categorize numbers based on their counts
        for (Map.Entry<Integer, Integer> entry : frequencyMap.entrySet()) {
            int val = entry.getKey();
            int count = entry.getValue();

            int qCount = count / 4;
            int remainder = count % 4;
            int pCount = remainder / 2;
            int sCount = remainder % 2;

            for (int i = 0; i < qCount; i++) quads.add(val);
            for (int i = 0; i < pCount; i++) pairs.add(val);
            for (int i = 0; i < sCount; i++) singles.add(val);
        }

        if (n % 2 == 0) {
            handleEvenCase(n, quads, pairs, singles, out);
        } else {
            handleOddCase(n, quads, pairs, singles, out);
        }
    }

    private static void handleEvenCase(int n, Deque<Integer> quads, Deque<Integer> pairs, 
                                       Deque<Integer> singles, PrintWriter out) {
        int requiredQuads = (n * n) / 4;

        // For even N, we can only use groups of 4 to maintain symmetry
        if (pairs.isEmpty() && singles.isEmpty() && quads.size() == requiredQuads) {
            int[][] matrix = constructEvenMatrix(n, quads);
            out.println("YES");
            printMatrix(matrix, out);
        } else {
            out.println("NO");
        }
    }

    private static void handleOddCase(int n, Deque<Integer> quads, Deque<Integer> pairs, 
                                      Deque<Integer> singles, PrintWriter out) {
        int requiredSingles = 1;
        int requiredPairs = n - 1; // (n-1)/2 for mid-row + (n-1)/2 for mid-col
        int requiredQuads = (n - 1) * (n - 1) / 4;

        if (singles.size() != requiredSingles) {
            out.println("NO");
            return;
        }

        // Convert quads to pairs if we don't have enough pairs
        while (pairs.size() < requiredPairs && !quads.isEmpty()) {
            int q = quads.pollFirst();
            pairs.add(q);
            pairs.add(q);
        }

        if (pairs.size() == requiredPairs && quads.size() == requiredQuads) {
            int[][] matrix = constructOddMatrix(n, quads, pairs, singles);
            out.println("YES");
            printMatrix(matrix, out);
        } else {
            out.println("NO");
        }
    }

    private static int[][] constructEvenMatrix(int n, Deque<Integer> quads) {
        int[][] matrix = new int[n][n];
        int half = n / 2;
        for (int i = 0; i < half; i++) {
            for (int j = 0; j < half; j++) {
                int val = quads.pollFirst();
                matrix[i][j] = val;
                matrix[n - 1 - i][j] = val;
                matrix[i][n - 1 - j] = val;
                matrix[n - 1 - i][n - 1 - j] = val;
            }
        }
        return matrix;
    }

    private static int[][] constructOddMatrix(int n, Deque<Integer> quads, Deque<Integer> pairs, 
                                              Deque<Integer> singles) {
        int[][] matrix = new int[n][n];
        int mid = n / 2;

        // 1. Fill Center
        matrix[mid][mid] = singles.pollFirst();

        // 2. Fill Middle Row and Middle Column (Symmetric Pairs)
        for (int i = 0; i < mid; i++) {
            int rowPair = pairs.pollFirst();
            matrix[mid][i] = rowPair;
            matrix[mid][n - 1 - i] = rowPair;

            int colPair = pairs.pollFirst();
            matrix[i][mid] = colPair;
            matrix[n - 1 - i][mid] = colPair;
        }

        // 3. Fill the rest (Symmetric Quadrants)
        for (int i = 0; i < mid; i++) {
            for (int j = 0; j < mid; j++) {
                int val = quads.pollFirst();
                matrix[i][j] = val;
                matrix[n - 1 - i][j] = val;
                matrix[i][n - 1 - j] = val;
                matrix[n - 1 - i][n - 1 - j] = val;
            }
        }
        return matrix;
    }

    private static void printMatrix(int[][] matrix, PrintWriter out) {
        for (int[] row : matrix) {
            for (int j = 0; j < row.length; j++) {
                out.print(row[j] + (j == row.length - 1 ? "" : " "));
            }
            out.println();
        }
    }

    /**
     * FastReader implementation for efficient input reading.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;

/**
 * A utility to construct a palindromic matrix from a given set of integers.
 * A palindromic matrix is one where elements at symmetric positions 
 * (relative to the center) are identical.
 */
public class PalindromicMatrix {

    private final int n;
    private final int[][] matrix;
    private final Map<Integer, Integer> frequencyMap;

    public PalindromicMatrix(int n, int[] elements) {
        this.n = n;
        this.matrix = new int[n][n];
        this.frequencyMap = new HashMap<>();
        for (int val : elements) {
            frequencyMap.put(val, frequencyMap.getOrDefault(val, 0) + 1);
        }
    }

    /**
     * Attempts to build the palindromic matrix.
     * @return true if a valid matrix was constructed, false otherwise.
     */
    public boolean build() {
        // Pools to store available symmetric groups
        Deque<Integer> pool4 = new ArrayDeque<>();
        Deque<Integer> pool2 = new ArrayDeque<>();
        Deque<Integer> pool1 = new ArrayDeque<>();

        // Pre-process frequencies into pools
        for (Map.Entry<Integer, Integer> entry : frequencyMap.entrySet()) {
            int val = entry.getKey();
            int count = entry.getValue();

            while (count >= 4) {
                pool4.addLast(val);
                count -= 4;
            }
            while (count >= 2) {
                pool2.addLast(val);
                count -= 2;
            }
            while (count >= 1) {
                pool1.addLast(val);
                count -= 1;
            }
        }

        // 1. Fill the quadrants (groups of 4)
        for (int i = 0; i < n / 2; i++) {
            for (int j = 0; j < n / 2; j++) {
                Integer val = pool4.pollFirst();
                if (val == null) return false;
                fillFourCells(i, j, val);
            }
        }

        // 2. If n is odd, fill the middle row and middle column (groups of 2)
        if (n % 2 != 0) {
            int mid = n / 2;

            // Fill middle row pairs
            for (int j = 0; j < mid; j++) {
                Integer val = getNextFromPool(pool2, pool4, 2);
                if (val == null) return false;
                matrix[mid][j] = matrix[mid][n - 1 - j] = val;
            }

            // Fill middle column pairs
            for (int i = 0; i < mid; i++) {
                Integer val = getNextFromPool(pool2, pool4, 2);
                if (val == null) return false;
                matrix[i][mid] = matrix[n - 1 - i][mid] = val;
            }

            // 3. Fill the center cell (group of 1)
            Integer centerVal = getNextFromPool(pool1, pool2, 2); // Try pool 1, then pool 2
            if (centerVal == null) {
                // Final attempt: try to split a group of 4 into 1s
                centerVal = getNextFromPool(pool1, pool4, 4);
            }
            if (centerVal == null) return false;
            matrix[mid][mid] = centerVal;
        }

        return true;
    }

    /**
     * Helper to get a value from a target pool, or split a larger pool if necessary.
     * 
     * @param target The primary pool to draw from.
     * @param fallback The pool to split if target is empty.
     * @param splitFactor How many units of the target a fallback unit produces.
     * @return The number to use, or null if no numbers are available.
     */
    private Integer getNextFromPool(Deque<Integer> target, Deque<Integer> fallback, int splitFactor) {
        if (!target.isEmpty()) {
            return target.pollFirst();
        }
        if (fallback.isEmpty()) {
            return null;
        }
        int val = fallback.pollFirst();
        // Split the larger unit into multiple smaller units
        for (int i = 0; i < splitFactor; i++) {
            target.addLast(val);
        }
        return target.pollFirst();
    }

    private void fillFourCells(int r, int c, int val) {
        matrix[r][c] = val;
        matrix[r][n - 1 - c] = val;
        matrix[n - 1 - r][c] = val;
        matrix[n - 1 - r][n - 1 - c] = val;
    }

    public void printResult() {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                sb.append(matrix[i][j]).append(" ");
            }
            sb.append("\n");
        }
        System.out.print(sb.toString());
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextInt()) return;

        int n = sc.nextInt();
        int[] elements = new int[n * n];
        for (int i = 0; i < n * n; i++) {
            elements[i] = sc.nextInt();
        }

        PalindromicMatrix builder = new PalindromicMatrix(n, elements);
        if (builder.build()) {
            System.out.println("YES");
            builder.printResult();
        } else {
            System.out.println("NO");
        }
        sc.close();
    }
}

import java.util.*;
import java.io.*;

/**
 * Represents the frequency of a specific number in the input.
 * Implements Comparable to handle the specific greedy priority requirements:
 * 1. Odd counts are prioritized (for the center cell).
 * 2. Counts that are 2, 6, 10... are prioritized next (for the middle cross).
 * 3. Counts divisible by 4 are prioritized last (for the quadrants).
 */
class Frequency implements Comparable<Frequency> {
    private final int value;
    private int count;

    public Frequency(int value, int count) {
        this.value = value;
        this.count = count;
    }

    public int getValue() {
        return value;
    }

    public int getCount() {
        return count;
    }

    public void decrement(int amount) {
        this.count -= amount;
    }

    private int getPriority() {
        if (count % 2 != 0) {
            return 0;
        } else if (count % 4 == 0) {
            return 400 * count;
        } else {
            return count;
        }
    }

    @Override
    public int compareTo(Frequency other) {
        return Integer.compare(this.getPriority(), other.getPriority());
    }
}

/**
 * Handles the logic of constructing an n x n matrix with symmetric properties.
 */
class SymmetryMatrixBuilder {
    private final int n;
    private final int[][] matrix;
    private final List<Frequency> frequencies;
    private boolean isPossible = true;

    public SymmetryMatrixBuilder(int n, List<Frequency> frequencies) {
        this.n = n;
        this.frequencies = frequencies;
        this.matrix = new int[n][n];
    }

    public void build() {
        if (n % 2 != 0) {
            fillCenter();
            if (isPossible) fillMiddleCross();
        }
        if (isPossible) fillQuadrants();
    }

    private void fillCenter() {
        int middle = n / 2;
        int index = findFirstAvailable(1);
        if (index == -1) {
            isPossible = false;
            return;
        }

        Frequency f = frequencies.get(index);
        matrix[middle][middle] = f.getValue();
        f.decrement(1);
    }

    private void fillMiddleCross() {
        int middle = n / 2;

        // Fill vertical middle column
        for (int i = 0; i < middle; i++) {
            int index = findFirstAvailable(2);
            if (index == -1) {
                isPossible = false;
                return;
            }
            Frequency f = frequencies.get(index);
            int val = f.getValue();

            matrix[i][middle] = val;
            matrix[n - 1 - i][middle] = val;
            f.decrement(2);
        }

        // Fill horizontal middle row
        for (int j = 0; j < middle; j++) {
            int index = findFirstAvailable(2);
            if (index == -1) {
                isPossible = false;
                return;
            }
            Frequency f = frequencies.get(index);
            int val = f.getValue();

            matrix[middle][j] = val;
            matrix[middle][n - 1 - j] = val;
            f.decrement(2);
        }
    }

    private void fillQuadrants() {
        int middle = n / 2;
        for (int i = 0; i < middle; i++) {
            for (int j = 0; j < middle; j++) {
                int index = findFirstAvailable(4);
                if (index == -1) {
                    isPossible = false;
                    return;
                }
                Frequency f = frequencies.get(index);
                int val = f.getValue();

                matrix[i][j] = val;
                matrix[i][n - 1 - j] = val;
                matrix[n - 1 - i][j] = val;
                matrix[n - 1 - i][n - 1 - j] = val;
                f.decrement(4);
            }
        }
    }

    private int findFirstAvailable(int minCount) {
        for (int i = 0; i < frequencies.size(); i++) {
            if (frequencies.get(i).getCount() >= minCount) {
                return i;
            }
        }
        return -1;
    }

    public boolean isPossible() {
        return isPossible;
    }

    public int[][] getMatrix() {
        return matrix;
    }
}

/**
 * Main entry point for the application.
 */
public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }

        int n = scanner.nextInt();
        Map<Integer, Integer> counts = new HashMap<>();

        // Read n^2 elements
        for (int i = 0; i < n * n; i++) {
            if (scanner.hasNextInt()) {
                int val = scanner.nextInt();
                counts.put(val, counts.getOrDefault(val, 0) + 1);
            }
        }

        // Convert map to sorted list of Frequency objects
        List<Frequency> frequencies = new ArrayList<>();
        for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
            frequencies.add(new Frequency(entry.getKey(), entry.getValue()));
        }
        Collections.sort(frequencies);

        // Construct the matrix
        SymmetryMatrixBuilder builder = new SymmetryMatrixBuilder(n, frequencies);
        builder.build();

        // Output results
        if (builder.isPossible()) {
            System.out.println("YES");
            printMatrix(builder.getMatrix(), n);
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    private static void printMatrix(int[][] matrix, int n) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                sb.append(matrix[i][j]).append(" ");
            }
            sb.append("\n");
        }
        System.out.print(sb.toString());
    }
}

import java.util.*;
import java.io.*;

/**
 * Solves the Symmetric Matrix problem.
 * The goal is to arrange n^2 numbers into an n x n matrix such that 
 * the matrix is symmetric across its horizontal, vertical, and central axes.
 */
public class SymmetricMatrixSolver {

    public static void main(String[] args) {
        new SymmetricMatrixSolver().run();
    }

    /**
     * Entry point for the program. Handles input/output setup and error boundaries.
     */
    public void run() {
        FastReader sc = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            String firstToken = sc.next();
            if (firstToken == null) return;

            int n = Integer.parseInt(firstToken);
            solve(n, sc, out);
        } catch (Exception e) {
            // In a production environment, replace with a proper logging framework.
        } finally {
            out.close();
        }
    }

    /**
     * Core logic to solve the symmetry problem.
     * 
     * @param n Dimension of the matrix.
     * @param sc Fast reader for input.
     * @param out PrintWriter for output.
     */
    private void solve(int n, FastReader sc, PrintWriter out) {
        int totalElements = n * n;
        Map<Integer, Integer> counts = new TreeMap<>();

        for (int i = 0; i < totalElements; i++) {
            int val = sc.nextInt();
            counts.put(val, counts.getOrDefault(val, 0) + 1);
        }

        int[][] matrix = new int[n][n];

        if (n % 2 == 0) {
            // Case: Even N
            // For a 4-way symmetric matrix, every element must appear in multiples of 4.
            if (!validateEvenSymmetry(counts)) {
                out.println("NO");
                return;
            }
            fillEvenMatrix(n, counts, matrix);
        } else {
            // Case: Odd N
            // Exactly one element must have an odd frequency to occupy the center cell.
            int oddValue = findOddFrequencyElement(counts);
            if (oddValue == -1) {
                out.println("NO");
                return;
            }
            fillOddMatrix(n, counts, oddValue, matrix);
        }

        printMatrix(n, matrix, out);
    }

    private boolean validateEvenSymmetry(Map<Integer, Integer> counts) {
        for (int count : counts.values()) {
            if (count % 4 != 0) return false;
        }
        return true;
    }

    private int findOddFrequencyElement(Map<Integer, Integer> counts) {
        int oddValue = -1;
        int oddCount = 0;
        for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
            if (entry.getValue() % 2 != 0) {
                oddValue = entry.getKey();
                oddCount++;
            }
        }
        // For odd N, we must have exactly one element with an odd count.
        return (oddCount == 1) ? oddValue : -1;
    }

    private void fillEvenMatrix(int n, Map<Integer, Integer> counts, int[][] matrix) {
        List<Integer> allPairs = new ArrayList<>();
        for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
            int val = entry.getKey();
            int count = entry.getValue();
            // Every count is a multiple of 4, so count/2 is even.
            for (int i = 0; i < count / 2; i++) {
                allPairs.add(val);
            }
        }

        int k = n / 2;
        int pairIdx = 0;
        for (int i = 0; i < k; i++) {
            for (int j = 0; j < k; j++) {
                // A quadruplet is formed by taking two identical "pairs" from our list.
                int val = allPairs.get(pairIdx++);
                pairIdx++; // Consume the second half of the quad.
                matrix[i][j] = matrix[i][n - 1 - j] = 
                              matrix[n - 1 - i][j] = matrix[n - 1 - i][n - 1 - j] = val;
            }
        }
    }

    private void fillOddMatrix(int n, Map<Integer, Integer> counts, int oddValue, int[][] matrix) {
        matrix[n / 2][n / 2] = oddValue;

        List<Integer> allPairs = new ArrayList<>();
        for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
            int val = entry.getKey();
            int count = entry.getValue();
            if (val == oddValue) count--; // Account for the center element.

            for (int i = 0; i < count / 2; i++) {
                allPairs.add(val);
            }
        }

        int k = n / 2;
        int pairIdx = 0;

        // 1. Fill middle row (symmetric pairs)
        for (int j = 0; j < k; j++) {
            int val = allPairs.get(pairIdx++);
            matrix[n / 2][j] = matrix[n / 2][n - 1 - j] = val;
        }

        // 2. Fill middle column (symmetric pairs)
        for (int i = 0; i < k; i++) {
            int val = allPairs.get(pairIdx++);
            matrix[i][n / 2] = matrix[n - 1 - i][n / 2] = val;
        }

        // 3. Fill corners (quadruplets)
        for (int i = 0; i < k; i++) {
            for (int j = 0; j < k; j++) {
                int val = allPairs.get(pairIdx++);
                pairIdx++; // Consume second half of the quad.
                matrix[i][j] = matrix[i][n - 1 - j] = 
                              matrix[n - 1 - i][j] = matrix[n - 1 - i][n - 1 - j] = val;
            }
        }
    }

    private void printMatrix(int n, int[][] matrix, PrintWriter out) {
        out.println("YES");
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            sb.setLength(0);
            for (int j = 0; j < n; j++) {
                sb.append(matrix[i][j]).append(j == n - 1 ? "" : " ");
            }
            out.println(sb.toString());
        }
    }

    /**
     * Efficient helper class for fast I/O operations.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the Palindromic Matrix problem.
 * The goal is to construct an n x n matrix that is symmetric 
 * across both the horizontal and vertical axes using the provided numbers.
 */
public class Main {
    public static void main(String[] args) {
        FastReader in = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        PalindromicMatrixSolver solver = new PalindromicMatrixSolver();
        solver.solve(in, out);

        out.close();
    }

    static class PalindromicMatrixSolver {

        public void solve(FastReader in, PrintWriter out) {
            int n = in.nextInt();
            if (n <= 0) return;

            int totalElements = n * n;
            int[] inputNumbers = in.nextIntArray(totalElements);

            // Handle the trivial case
            if (n == 1) {
                out.println("YES");
                out.println(inputNumbers[0]);
                return;
            }

            // 1. Count frequencies of each number
            Map<Integer, Integer> frequencyMap = new TreeMap<>();
            for (int num : inputNumbers) {
                frequencyMap.put(num, frequencyMap.getOrDefault(num, 0) + 1);
            }

            // 2. Prepare for greedy construction
            int[][] matrix = new int[n][n];
            int[] distinctValues = frequencyMap.keySet().stream().mapToInt(i -> i).toArray();
            int pointer = 0;

            // 3. Fill the 4-way symmetric quadrants
            // These cells require 4 identical numbers: (i, j), (n-1-i, j), (i, n-1-j), (n-1-i, n-1-j)
            for (int i = 0; i < n / 2; i++) {
                for (int j = 0; j < n / 2; j++) {
                    int val = findAndReduce(frequencyMap, distinctValues, pointer, 4);
                    if (val == -1) {
                        out.println("NO");
                        return;
                    }
                    // Update the pointer to the current value to avoid re-scanning from the start
                    pointer = findPointer(distinctValues, val);

                    matrix[i][j] = matrix[n - 1 - i][j] = matrix[i][n - 1 - j] = matrix[n - 1 - i][n - 1 - j] = val;
                }
            }

            // 4. Handle the middle row/column if n is odd
            if (n % 2 != 1) {
                // If n is even, we are already done with the symmetry requirements
            } else {
                // Fill middle row pairs: (n/2, j) and (n/2, n-1-j)
                for (int j = 0; j < n / 2; j++) {
                    int val = findAndReduce(frequencyMap, distinctValues, pointer, 2);
                    if (val == -1) {
                        out.println("NO");
                        return;
                    }
                    pointer = findPointer(distinctValues, val);
                    matrix[n / 2][j] = matrix[n / 2][n - 1 - j] = val;
                }

                // Fill middle column pairs: (i, n/2) and (n-1-i, n/2)
                for (int i = 0; i < n / 2; i++) {
                    int val = findAndReduce(frequencyMap, distinctValues, pointer, 2);
                    if (val == -1) {
                        out.println("NO");
                        return;
                    }
                    pointer = findPointer(distinctValues, val);
                    matrix[i][n / 2] = matrix[n - 1 - i][n / 2] = val;
                }

                // Fill the very center cell: (n/2, n/2)
                int centerVal = findAndReduce(frequencyMap, distinctValues, pointer, 1);
                if (centerVal == -1) {
                    out.println("NO");
                    return;
                }
                pointer = findPointer(distinctValues, centerVal);
                matrix[n / 2][n / 2] = centerVal;
            }

            // 5. Final validation: Ensure all provided numbers were used
            for (int count : frequencyMap.values()) {
                if (count != 0) {
                    out.println("NO");
                    return;
                }
            }

            out.println("YES");
            printMatrix(out, matrix);
        }

        /**
         * Finds a value in the frequency map that has at least 'requiredCount' occurrences.
         * Decrements the count and returns the value.
         */
        private int findAndReduce(Map<Integer, Integer> map, int[] distinctValues, int startPointer, int requiredCount) {
            for (int i = startPointer; i < distinctValues.length; i++) {
                int val = distinctValues[i];
                int currentFreq = map.get(val);
                if (currentFreq >= requiredCount) {
                    map.put(val, currentFreq - requiredCount);
                    return val;
                }
            }
            return -1;
        }

        /**
         * Helper to find the index of a value in the distinctValues array.
         */
        private int findPointer(int[] arr, int target) {
            // Since we use this to update the pointer, in a real-world scenario 
            // we'd want this to be O(1), but given N is up to 1000, O(D) is acceptable.
            // To be truly efficient, we could pass the current index from findAndReduce.
            for (int i = 0; i < arr.length; i++) {
                if (arr[i] == target) return i;
            }
            return 0;
        }

        private void printMatrix(PrintWriter out, int[][] matrix) {
            for (int[] row : matrix) {
                for (int j = 0; j < row.length; j++) {
                    out.print(row[j] + (j == row.length - 1 ? "" : " "));
                }
                out.println();
            }
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private final InputStream stream;
        private final byte[] buf = new byte[8192];
        private int curChar;
        private int numChars;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (numChars == -1) throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) return -1;
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res = res * 10 + (c - '0');
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public int[] nextIntArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++) {
                a[i] = nextInt();
            }
            return a;
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * SymmetricGridSolver
 * 
 * This program takes an N x N grid of numbers and attempts to rearrange them 
 * into a grid that satisfies specific reflectional/rotational symmetries.
 * 
 * Symmetries:
 * - If N is even: Every number must appear in groups of 4 (mirrored across axes).
 * - If N is odd: Numbers must form groups of 4 (corners/quadrants), 
 *   groups of 2 (middle row/column), and exactly one single element (center).
 */
public class SymmetricGridSolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            String line = reader.nextLine();
            if (line == null || line.isEmpty()) {
                return;
            }
            int n = Integer.parseInt(line.trim());
            Map<Integer, Integer> frequencyMap = new HashMap<>();

            // Read N*N elements and build frequency map
            for (int i = 0; i < n * n; i++) {
                int val = reader.nextInt();
                frequencyMap.put(val, frequencyMap.getOrDefault(val, 0) + 1);
            }

            solve(n, frequencyMap, writer);
        } catch (Exception e) {
            // Silent catch for competitive programming context
        } finally {
            writer.flush();
            writer.close();
        }
    }

    private static void solve(int n, Map<Integer, Integer> frequencyMap, PrintWriter writer) {
        if (n % 2 == 0) {
            handleEvenGrid(n, frequencyMap, writer);
        } else {
            handleOddGrid(n, frequencyMap, writer);
        }
    }

    private static void handleEvenGrid(int n, Map<Integer, Integer> frequencyMap, PrintWriter writer) {
        int subN = n / 2;
        int neededQuads = subN * subN;
        List<Integer> quads = new ArrayList<>();

        // Collect available groups of 4
        for (Map.Entry<Integer, Integer> entry : frequencyMap.entrySet()) {
            int val = entry.getKey();
            int count = entry.getValue();
            int setsOf4 = count / 4;
            for (int i = 0; i < setsOf4 && quads.size() < neededQuads; i++) {
                quads.add(val);
            }
        }

        if (quads.size() < neededQuads) {
            writer.println("NO");
        } else {
            writer.println("YES");
            int[][] grid = new int[n][n];
            int quadIdx = 0;
            for (int i = 0; i < subN; i++) {
                for (int j = 0; j < subN; j++) {
                    int val = quads.get(quadIdx++);
                    fillFourWay(grid, i, j, val, n);
                }
            }
            printGrid(grid, writer);
        }
    }

    private static void handleOddGrid(int n, Map<Integer, Integer> frequencyMap, PrintWriter writer) {
        int subN = (n - 1) / 2;
        int neededQuads = subN * subN;
        int neededPairs = 2 * subN;
        int neededSingles = 1;

        List<Integer> quads = new ArrayList<>();
        List<Integer> pairs = new ArrayList<>();
        List<Integer> singles = new ArrayList<>();

        // Step 1: Greedily extract all possible 4-groups, 2-groups, and 1-groups
        for (Map.Entry<Integer, Integer> entry : frequencyMap.entrySet()) {
            int val = entry.getKey();
            int count = entry.getValue();

            int num4s = count / 4;
            quads.addAll(Collections.nCopies(num4s, val));

            int remainder = count % 4;
            int num2s = remainder / 2;
            pairs.addAll(Collections.nCopies(num2s, val));

            if (remainder % 2 == 1) {
                singles.add(val);
            }
        }

        // Step 2: If we have excess 4-groups, convert them into 2-groups to meet requirements
        if (quads.size() > neededQuads) {
            int excess = quads.size() - neededQuads;
            for (int i = 0; i < excess; i++) {
                int val = quads.remove(quads.size() - 1);
                pairs.add(val);
                pairs.add(val);
            }
        }

        // Step 3: Verify requirements are met
        if (quads.size() == neededQuads && pairs.size() >= neededPairs && !singles.isEmpty()) {
            writer.println("YES");
            int[][] grid = new int[n][n];
            int qIdx = 0;
            int pIdx = 0;

            // Fill corner quadrants
            for (int i = 0; i < subN; i++) {
                for (int j = 0; j < subN; j++) {
                    int val = quads.get(qIdx++);
                    fillFourWay(grid, i, j, val, n);
                }
            }

            // Fill middle row pairs
            for (int i = 0; i < subN; i++) {
                int val = pairs.get(pIdx++);
                grid[subN][i] = val;
                grid[subN][n - 1 - i] = val;
            }

            // Fill middle column pairs
            for (int i = 0; i < subN; i++) {
                int val = pairs.get(pIdx++);
                grid[i][subN] = val;
                grid[n - 1 - i][subN] = val;
            }

            // Fill center
            grid[subN][subN] = singles.get(0);

            printGrid(grid, writer);
        } else {
            writer.println("NO");
        }
    }

    private static void fillFourWay(int[][] grid, int r, int c, int val, int n) {
        grid[r][c] = val;
        grid[r][n - 1 - c] = val;
        grid[n - 1 - r][c] = val;
        grid[n - 1 - r][n - 1 - c] = val;
    }

    private static void printGrid(int[][] grid, PrintWriter writer) {
        for (int[] row : grid) {
            for (int j = 0; j < row.length; j++) {
                writer.print(row[j] + (j == row.length - 1 ? "" : " "));
            }
            writer.println();
        }
    }

    /**
     * FastReader class for efficient input processing.
     */
    static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                return null;
            }
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver that fills an n x n grid with numbers such that symmetric cells 
 * are filled using the most frequent numbers available.
 */
public class SymmetryGridSolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int n = reader.nextInt();
            Map<Integer, Integer> frequencyMap = new HashMap<>();

            // Count the frequency of each input number
            for (int i = 0; i < n * n; i++) {
                int value = reader.nextInt();
                frequencyMap.put(value, frequencyMap.getOrDefault(value, 0) + 1);
            }

            SymmetryGrid grid = new SymmetryGrid(n, frequencyMap);

            if (grid.solve()) {
                grid.print(writer);
            } else {
                writer.println("NO");
            }
        } catch (IOException e) {
            // In a production environment, use a logger
            System.err.println("Error reading input: " + e.getMessage());
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Represents a number and its remaining frequency count.
     */
    static class FrequencyPair {
        int value;
        int frequency;

        FrequencyPair(int value, int frequency) {
            this.value = value;
            this.frequency = frequency;
        }
    }

    /**
     * Logic for managing the grid and the symmetric filling process.
     */
    static class SymmetryGrid {
        private final int size;
        private final int[][] grid;
        private final PriorityQueue<FrequencyPair> frequencyQueue;

        public SymmetryGrid(int size, Map<Integer, Integer> frequencyMap) {
            this.size = size;
            this.grid = new int[size][size];
            for (int[] row : grid) {
                Arrays.fill(row, -1);
            }

            // Priority Queue to always pick the number with the highest frequency
            this.frequencyQueue = new PriorityQueue<>((a, b) -> Integer.compare(b.frequency, a.frequency));
            for (Map.Entry<Integer, Integer> entry : frequencyMap.entrySet()) {
                frequencyQueue.add(new FrequencyPair(entry.getKey(), entry.getValue()));
            }
        }

        /**
         * Attempts to fill a specific cell with the given value pair.
         * @return true if successful, false if not enough frequency remains.
         */
        private boolean fillCell(int r, int c, FrequencyPair pair) {
            if (grid[r][c] == -1) {
                if (pair.frequency <= 0) {
                    return false;
                }
                grid[r][c] = pair.value;
                pair.frequency--;
            }
            return true;
        }

        /**
         * Executes the symmetric filling algorithm.
         * @return true if the grid was filled successfully, false otherwise.
         */
        public boolean solve() {
            // 1. Fill the four corners of each quadrant
            for (int i = 0; i < size / 2; i++) {
                for (int j = 0; j < size / 2; j++) {
                    if (frequencyQueue.isEmpty()) return false;
                    FrequencyPair p = frequencyQueue.poll();

                    boolean ok = fillCell(i, size - 1 - j, p) &&
                                 fillCell(i, j, p) &&
                                 fillCell(size - 1 - i, j, p) &&
                                 fillCell(size - 1 - i, size - 1 - j, p);

                    if (!ok) return false;
                    if (p.frequency > 0) frequencyQueue.add(p);
                }
            }

            // 2. Handle the middle row and column if n is odd
            if (size % 2 != 0) {
                int mid = size / 2;

                // Vertical center column
                for (int i = 0; i < mid; i++) {
                    if (frequencyQueue.isEmpty()) return false;
                    FrequencyPair p = frequencyQueue.poll();

                    boolean ok = fillCell(i, mid, p) && 
                                 fillCell(size - 1 - i, mid, p);

                    if (!ok) return false;
                    if (p.frequency > 0) frequencyQueue.add(p);
                }

                // Horizontal center row (including the center cell)
                for (int i = 0; i <= mid; i++) {
                    if (frequencyQueue.isEmpty()) return false;
                    FrequencyPair p = frequencyQueue.poll();

                    boolean ok = fillCell(mid, i, p) && 
                                 fillCell(mid, size - 1 - i, p);

                    if (!ok) return false;
                    if (p.frequency > 0) frequencyQueue.add(p);
                }
            }

            return true;
        }

        public void print(PrintWriter writer) {
            writer.println("YES");
            for (int i = 0; i < size; i++) {
                for (int j = 0; j < size; j++) {
                    writer.print(grid[i][j] + (j == size - 1 ? "" : " "));
                }
                writer.println();
            }
        }
    }

    /**
     * Fast I/O reader to handle large datasets efficiently.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

