/**
 * Handles the logic of determining if a symmetric grid can be formed.
 */
class SymmetrySolver {
    private final int n;
    private final Map<Integer, Integer> counts;

    public SymmetrySolver(int n, Map<Integer, Integer> counts) {
        this.n = n;
        this.counts = counts;
    }

    public Optional<Grid> solve() {
        if (n % 2 == 0) {
            return solveEven();
        } else {
            return solveOdd();
        }
    }

    private Optional<Grid> solveEven() {
        Deque<Integer> quads = new ArrayDeque<>();

        for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
            int val = entry.getKey();
            int count = entry.getValue();

            if (count % 4 != 0) return Optional.empty();
            for (int i = 0; i < count / 4; i++) {
                quads.add(val);
            }
        }

        return Optional.of(buildEvenGrid(quads));
    }

    private Optional<Grid> solveOdd() {
        Deque<Integer> quads = new ArrayDeque<>();
        Deque<Integer> pairs = new ArrayDeque<>();
        Integer centerValue = null;

        for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
            int val = entry.getKey();
            int count = entry.getValue();
            int remainder = count % 4;

            if (remainder == 1 || remainder == 3) {
                if (centerValue != null) return Optional.empty(); // Only one center allowed
                centerValue = val;

                int numPairs = (remainder == 3) ? 1 : 0;
                for (int i = 0; i < numPairs; i++) pairs.add(val);
                for (int i = 0; i < (count - 1 - (2 * numPairs)) / 4; i++) quads.add(val);
            } else if (remainder == 2) {
                pairs.add(val);
                for (int i = 0; i < (count - 2) / 4; i++) quads.add(val);
            } else if (remainder == 0) {
                for (int i = 0; i < count / 4; i++) quads.add(val);
            } else {
                return Optional.empty();
            }
        }

        if (centerValue == null) return Optional.empty();

        // We need exactly (n-1) pairs for the middle row/col.
        // If we have fewer, we split quads into two pairs each.
        int requiredPairs = n - 1;
        while (pairs.size() < requiredPairs) {
            if (quads.isEmpty()) return Optional.empty();
            int val = quads.poll();
            pairs.add(val);
            pairs.add(val);
        }

        // If we have more pairs than needed, it's an impossible configuration 
        // (as pairs cannot be merged into quads without losing count integrity).
        if (pairs.size() > requiredPairs) return Optional.empty();

        return Optional.of(buildOddGrid(quads, pairs, centerValue));
    }

    private Grid buildEvenGrid(Deque<Integer> quads) {
        Grid grid = new Grid(n);
        int half = n / 2;
        for (int i = 0; i < half; i++) {
            for (int j = 0; j < half; j++) {
                int val = quads.poll();
                fillQuad(grid, i, j, val);
            }
        }
        return grid;
    }

    private Grid buildOddGrid(Deque<Integer> quads, Deque<Integer> pairs, int center) {
        Grid grid = new Grid(n);
        int half = n / 2;

        // 1. Fill the 4-way symmetric quads
        for (int i = 0; i < half; i++) {
            for (int j = 0; j < half; j++) {
                fillQuad(grid, i, j, quads.poll());
            }
        }

        // 2. Fill the 2-way symmetric middle row and middle column
        // Middle row pairs
        for (int j = 0; j < half; j++) {
            int val = pairs.poll();
            grid.set(half, j, val);
            grid.set(half, n - 1 - j, val);
        }
        // Middle column pairs
        for (int i = 0; i < half; i++) {
            int val = pairs.poll();
            grid.set(i, half, val);
            grid.set(n - 1 - i, half, val);
        }

        // 3. Fill the center
        grid.set(half, half, center);

        return grid;
    }

    private void fillQuad(Grid grid, int r, int c, int val) {
        grid.set(r, c, val);
        grid.set(n - 1 - r, c, val);
        grid.set(r, n - 1 - c, val);
        grid.set(n - 1 - r, n - 1 - c, val);
    }
}

