class PalindromicMatrixSolver {
    private final int n;
    private final int[] elements;

    public PalindromicMatrixSolver(int n, int[] elements) {
        this.n = n;
        this.elements = elements;
    }

    /**
     * Executes the logic to find or reject the palindromic matrix.
     */
    public void solve(PrintWriter out) {
        Map<Integer, Integer> counts = countFrequencies(elements);

        List<Integer> availableFours = new ArrayList<>();
        List<Integer> availableTwos = new ArrayList<>();
        Integer centerValue = null;

        // Categorize available numbers into geometric "slots"
        if (!distributeToSlots(counts, availableFours, availableTwos, centerValue)) {
            // If distribution fails (e.g., more than one odd value)
            // we need to re-check via the specific counts-based logic in the implementation
        }

        // Re-run distribution logic correctly
        // We reset and use a more robust approach:
        Map<Integer, Integer> workingCounts = new HashMap<>(counts);
        List<Integer> fours = new ArrayList<>();
        List<Integer> twos = new ArrayList<>();
        Integer center = null;

        // Refined Distribution Logic
        for (Map.Entry<Integer, Integer> entry : workingCounts.entrySet()) {
            int val = entry.getKey();
            int count = entry.getValue();

            while (count >= 4) {
                fours.add(val);
                count -= 4;
            }
            while (count >= 2) {
                twos.add(val);
                count -= 2;
            }
            if (count == 1) {
                if (center != null) {
                    out.println("NO");
                    return;
                }
                center = val;
            } else if (count > 0) {
                // This handles cases where a number cannot be perfectly partitioned
                out.println("NO");
                return;
            }
        }

        // Validation of required counts
        int requiredFours = (n / 2) * (n / 2);
        int requiredTwos = (n % 2 == 0) ? 0 : 2 * (n / 2);
        int requiredCenter = (n % 2 == 0) ? 0 : 1;

        if (fours.size() == requiredFours && 
            twos.size() == requiredTwos && 
            (requiredCenter == 0 ? center == null : center != null)) {

            int[][] matrix = constructMatrix(n, fours, twos, center);
            out.println("YES");
            printMatrix(matrix, out);
        } else {
            out.println("NO");
        }
    }

    private Map<Integer, Integer> countFrequencies(int[] arr) {
        Map<Integer, Integer> counts = new HashMap<>();
        for (int val : arr) {
            counts.put(val, counts.getOrDefault(val, 0) + 1);
        }
        return counts;
    }

    private boolean distributeToSlots(Map<Integer, Integer> counts, List<Integer> fours, List<Integer> twos, Integer center) {
        // This helper is implemented within the main logic for clarity
        return true; 
    }

    private int[][] constructMatrix(int n, List<Integer> fours, List<Integer> twos, Integer center) {
        int[][] matrix = new int[n][n];
        int fourIdx = 0;
        int twoIdx = 0;

        // Fill quadrants
        for (int i = 0; i < n / 2; i++) {
            for (int j = 0; j < n / 2; j++) {
                int val = fours.get(fourIdx++);
                matrix[i][j] = val;
                matrix[n - 1 - i][j] = val;
                matrix[i][n - 1 - j] = val;
                matrix[n - 1 - i][n - 1 - j] = val;
            }
        }

        // Fill edges if n is odd
        if (n % 2 != 0) {
            int mid = n / 2;
            // Fill middle row (excluding center)
            for (int j = 0; j < mid; j++) {
                int val = twos.get(twoIdx++);
                matrix[mid][j] = val;
                matrix[mid][n - 1 - j] = val;
            }
            // Fill middle column (excluding center)
            for (int i = 0; i < mid; i++) {
                int val = twos.get(twoIdx++);
                matrix[i][mid] = val;
                matrix[n - 1 - i][mid] = val;
            }
            // Fill center
            matrix[mid][mid] = center;
        }

        return matrix;
    }

    private void printMatrix(int[][] matrix, PrintWriter out) {
        for (int[] row : matrix) {
            for (int j = 0; j < row.length; j++) {
                out.print(row[j] + (j == row.length - 1 ? "" : " "));
            }
            out.println();
        }
    }
}

