/**
 * Refactored solution for generating a symmetric matrix.
 * The matrix satisfies the condition: grid[i][j] == grid[n-1-i][n-1-j].
 * Specifically, this implementation handles 4-way symmetry for quadrants.
 */
public class CodeForces540C {

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        int n = reader.nextInt();
        if (n <= 0) return;

        int[] counts = new int[1001];
