import java.util.*;

/**
 * A program that constructs a palindromic matrix from a given set of integers.
 * A palindromic matrix is defined such that for every cell (i, j), 
 * the cells (i, n-1-j), (n-1-i, j), and (n-1-i, n-1-j) have the same value.
 */
public class PalindromicMatrix {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) {
            return;
        }

        int n = scanner.nextInt();
        int[] elements = new int[n * n];
        for (int i = 0; i < n * n; i++) {
            elements[i] = scanner.nextInt();
        }

        PalindromicMatrix solver = new PalindromicMatrix();
        solver.solve(n, elements);
    }

    /**
     * Coordinates the logic of counting, slot identification, and matrix filling.
     */
    public void solve(int n, int[] elements) {
        Map<Integer, Integer> countsMap = new HashMap<>();
        for (int x : elements) {
            countsMap.put(x, countsMap.getOrDefault(x, 0) + 1);
        }

        List<Frequency> freqList = new ArrayList<>();
        for (var entry : countsMap.entrySet()) {
            freqList.add(new Frequency(entry.getKey(), entry.getValue()));
        }

        int[][] matrix = new int[n][n];
        List<int[][]> quadSlots = new ArrayList<>();
        List<int[][]> pairSlots = new ArrayList<>();
        int[][] singleSlot = null;

        // 1. Identify Symmetry Groups
        // Quad slots: (i, j), (i, n-1-j), (n-1-i, j), (n-1-i, n-1-j)
        for (int i = 0; i < n / 2; i++) {
            for (int j = 0; j < n / 2; j++) {
                quadSlots.add(new int[][]{
                    {i, j}, {i, n - 1 - j}, {n - 1 - i, j}, {n - 1 - i, n - 1 - j}
                });
            }
        }

        // If n is odd, we have middle-row/column pairs and a center single
        if (n % 2 != 0) {
            int mid = n / 2;
            // Middle row pairs (excluding center)
            for (int j = 0; j < mid; j++) {
                pairSlots.add(new int[][]{{mid, j}, {mid, n - 1 - j}});
            }
            // Middle column pairs (excluding center)
            for (int i = 0; i < mid; i++) {
                pairSlots.add(new int[][]{{i, mid}, {n - 1 - i, mid}});
            }
            // Center single slot
            singleSlot = new int[][]{{mid, mid}};
        }

        // 2. Greedy Filling Strategy
        // Priority: Fill 4-slots, then 2-slots, then 1-slots.

        // Fill Quads
        if (!fillSymmetryGroups(quadSlots, freqList, matrix, 4)) {
            System.out.println("NO");
            return;
        }

        // Fill Pairs
        if (!fillSymmetryGroups(pairSlots, freqList, matrix, 2)) {
            System.out.println("NO");
            return;
        }

        // Fill Single (if applicable)
        if (singleSlot != null) {
            if (!fillSymmetryGroups(Collections.singletonList(singleSlot), freqList, matrix, 1)) {
                System.out.println("NO");
                return;
            }
        }

        // 3. Output Result
        printMatrix(n, matrix);
    }

    /**
     * Attempts to fill the provided symmetry slots using the available frequency list.
     * 
     * @param slots The list of coordinate groups to be filled.
     * @param freqList The list of available numbers and their remaining counts.
     * @param matrix The target matrix.
     * @param needed How many of the same number are required for one slot (4, 2, or 1).
     * @return true if all slots were successfully filled, false otherwise.
     */
    private boolean fillSymmetryGroups(List<int[][]> slots, List<Frequency> freqList, int[][] matrix, int needed) {
        int freqIdx = 0;
        for (int[][] slot : slots) {
            boolean filled = false;
            while (freqIdx < freqList.size()) {
                Frequency f = freqList.get(freqIdx);
                if (f.count >= needed) {
                    for (int[] coord : slot) {
                        matrix[coord[0]][coord[1]] = f.num;
                    }
                    f.count -= needed;
                    filled = true;
                    break;
                } else {
                    // Move to the next number if the current one cannot satisfy the requirement
                    freqIdx++;
                }
            }
            if (!filled) {
                return false;
            }
        }
        return true;
    }

    private void printMatrix(int n, int[][] matrix) {
        System.out.println("YES");
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                sb.append(matrix[i][j]).append(j == n - 1 ? "" : " ");
            }
            sb.append("\n");
        }
        System.out.print(sb.toString());
    }

    /**
     * Helper class to keep track of number frequencies.
     */
    private static class Frequency {
        int num;
        int count;

        Frequency(int num, int count) {
            this.num = num;
            this.count = count;
        }
    }
}

import java.util.*;

/**
 * A utility to construct a symmetric n x n matrix from a provided set of integers.
 * A matrix is symmetric if matrix[i][j] == matrix[n-1-i][j] == matrix[i][n-1-j] == matrix[n-1-i][n-1-j].
 */
public class SymmetricMatrixBuilder {

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int n = scanner.nextInt();
            Map<Integer, Integer> frequencyMap = new HashMap<>();

            // Read n*n elements and count occurrences
            for (int i = 0; i < n * n; i++) {
                if (scanner.hasNextInt()) {
                    int value = scanner.nextInt();
                    frequencyMap.put(value, frequencyMap.getOrDefault(value, 0) + 1);
                }
            }

            solve(n, frequencyMap);
        }
    }

    /**
     * Attempts to build a symmetric matrix. If successful, prints YES and the matrix.
     * Otherwise, prints NO.
     *
     * @param n              The dimension of the matrix.
     * @param frequencyMap   A map containing the counts of each integer provided.
     */
    private static void solve(int n, Map<Integer, Integer> frequencyMap) {
        int[][] matrix = new int[n][n];

        // We decompose the available numbers into "symmetry packs"
        // fours: packs of 4 for corner-based symmetry
        // twos:  packs of 2 for axis-based symmetry (middle row/column)
        // ones:  single items for center-point symmetry
        List<Integer> fourPacks = new ArrayList<>();
        List<Integer> twoPacks = new ArrayList<>();
        List<Integer> onePacks = new ArrayList<>();

        for (Map.Entry<Integer, Integer> entry : frequencyMap.entrySet()) {
            int val = entry.getKey();
            int count = entry.getValue();

            int fCount = count / 4;
            for (int i = 0; i < fCount; i++) fourPacks.add(val);
            count %= 4;

            int tCount = count / 2;
            for (int i = 0; i < tCount; i++) twoPacks.add(val);
            count %= 2;

            if (count == 1) {
                onePacks.add(val);
            }
        }

        // 1. Fill the Quadrants (4-way symmetry)
        // This fills the cells (i, j), (i, n-1-j), (n-1-i, j), and (n-1-i, n-1-j)
        int quadrantSize = n / 2;
        for (int i = 0; i < quadrantSize; i++) {
            for (int j = 0; j < quadrantSize; j++) {
                if (fourPacks.isEmpty()) {
                    System.out.println("NO");
                    return;
                }
                int val = fourPacks.remove(0);
                matrix[i][j] = val;
                matrix[i][n - 1 - j] = val;
                matrix[n - 1 - i][j] = val;
                matrix[n - 1 - i][n - 1 - j] = val;
            }
        }

        // 2. Handle odd dimensions (Middle row, Middle column, and Center)
        if (n % 2 != 0) {
            int mid = n / 2;

            // Any leftover 4-packs can be downgraded to two 2-packs to satisfy axis symmetry
            while (!fourPacks.isEmpty()) {
                int val = fourPacks.remove(0);
                twoPacks.add(val);
                twoPacks.add(val);
            }

            // Fill middle row (excluding center)
            for (int i = 0; i < mid; i++) {
                if (twoPacks.isEmpty()) {
                    System.out.println("NO");
                    return;
                }
                int val = twoPacks.remove(0);
                matrix[i][mid] = val;
                matrix[n - 1 - i][mid] = val;
            }

            // Fill middle column (excluding center)
            for (int j = 0; j < mid; j++) {
                if (twoPacks.isEmpty()) {
                    System.out.println("NO");
                    return;
                }
                int val = twoPacks.remove(0);
                matrix[mid][j] = val;
                matrix[mid][n - 1 - j] = val;
            }

            // Downgrade remaining 2-packs to 1-packs to potentially fill the center
            while (!twoPacks.isEmpty()) {
                int val = twoPacks.remove(0);
                onePacks.add(val);
            }

            // Fill the center cell
            if (onePacks.isEmpty()) {
                System.out.println("NO");
                return;
            }
            matrix[mid][mid] = onePacks.remove(0);

            // If we still have leftovers in onePacks, we have used more than n*n numbers 
            // or the symmetry cannot be completed.
            if (!onePacks.isEmpty()) {
                System.out.println("NO");
                return;
            }
        }

        System.out.println("YES");
        printMatrix(matrix);
    }

    /**
     * Efficiently prints the matrix using StringBuilder.
     *
     * @param matrix The 2D array to print.
     */
    private static void printMatrix(int[][] matrix) {
        StringBuilder sb = new StringBuilder();
        for (int[] row : matrix) {
            for (int j = 0; j < row.length; j++) {
                sb.append(row[j]);
                if (j < row.length - 1) {
                    sb.append(" ");
                }
            }
            sb.append("\n");
        }
        System.out.print(sb.toString());
    }
}

import java.io.*;
import java.util.*;

/**
 * A solution to arrange numbers in an n x n grid such that they satisfy
 * specific symmetry requirements: center is a singleton (if n is odd),
 * mid-lines are pairs (if n is odd), and others are quads.
 */
public class Solution {

    private static final int MAX_VALUE = 1000;

    public static void main(String[] args) throws IOException {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        int n = reader.nextInt();
        int[] inputCounts = new int[MAX_VALUE + 1];
        for (int i = 0; i < n * n; i++) {
            inputCounts[reader.nextInt()]++;
        }

        GridSolver solver = new GridSolver(n, inputCounts);
        SolveResult result = solver.solve();

        if (result.isSuccess()) {
            writer.println("YES");
            printGrid(result.getGrid(), writer);
        } else {
            writer.println("NO");
        }

        writer.flush();
        writer.close();
    }

    private static void printGrid(int[][] grid, PrintWriter writer) {
        for (int[] row : grid) {
            for (int j = 0; j < row.length; j++) {
                writer.print(row[j] + (j == row.length - 1 ? "" : " "));
            }
            writer.println();
        }
    }

    /**
     * Represents the outcome of the grid construction attempt.
     */
    static class SolveResult {
        private final boolean success;
        private final int[][] grid;

        public SolveResult(boolean success, int[][] grid) {
            this.success = success;
            this.grid = grid;
        }

        public boolean isSuccess() { return success; }
        public int[][] getGrid() { return grid; }
    }

    /**
     * Manages the categorized frequency of numbers into usable pools.
     */
    static class FrequencyPool {
        final Deque<Integer> quads = new ArrayDeque<>();
        final Deque<Integer> pairs = new ArrayDeque<>();
        final Deque<Integer> singletons = new ArrayDeque<>();

        public FrequencyPool(int[] counts) {
            for (int i = 0; i <= MAX_VALUE; i++) {
                int count = counts[i];
                int q = count / 4;
                int remainder = count % 4;
                int p = remainder / 2;
                int s = remainder % 2;

                for (int j = 0; j < q; j++) quads.push(i);
                for (int j = 0; j < p; j++) pairs.push(i);
                for (int j = 0; j < s; j++) singletons.push(i);
            }
        }
    }

    /**
     * Contains the logic for validating and constructing the symmetric grid.
     */
    static class GridSolver {
        private final int n;
        private final FrequencyPool pool;

        public GridSolver(int n, int[] counts) {
            this.n = n;
            this.pool = new FrequencyPool(counts);
        }

        public SolveResult solve() {
            if (!canSolve()) {
                return new SolveResult(false, null);
            }

            int[][] grid = new int[n][n];
            int mid = n / 2;

            try {
                // Iterate through the "top-left" quadrant to fill the whole grid via symmetry
                for (int i = 0; i < (n + 1) / 2; i++) {
                    for (int j = 0; j < (n + 1) / 2; j++) {

                        if (n % 2 != 0 && i == mid && j == mid) {
                            // 1. Handle Center (Odd n)
                            grid[i][j] = pool.singletons.pop();
                        } 
                        else if (n % 2 != 0 && (i == mid || j == mid)) {
                            // 2. Handle Mid-lines (Odd n)
                            int val = getPair();
                            if (i == mid) {
                                grid[i][j] = grid[i][n - 1 - j] = val;
                            } else {
                                grid[i][j] = grid[n - 1 - i][j] = val;
                            }
                        } 
                        else {
                            // 3. Handle Quads (Even n or non-mid cells in Odd n)
                            int val = pool.quads.pop();
                            grid[i][j] = grid[n - 1 - i][j] = 
                                    grid[n - 1 - i][n - 1 - j] = grid[i][n - 1 - j] = val;
                        }
                    }
                }
                return new SolveResult(true, grid);
            } catch (NoSuchElementException e) {
                return new SolveResult(false, null);
            }
        }

        private boolean canSolve() {
            if (n % 2 == 0) {
                // Even n: requires only groups of 4
                return pool.singletons.isEmpty() && pool.pairs.isEmpty();
            } else {
                // Odd n: requires exactly one singleton and specific pair count
                int requiredPairs = n - 1; 
                return pool.singletons.size() == 1 && pool.pairs.size() <= requiredPairs;
            }
        }

        private int getPair() {
            if (pool.pairs.isEmpty()) {
                // If no pairs available, break a quad into two pairs
                int quadVal = pool.quads.pop();
                pool.pairs.push(quadVal);
                pool.pairs.push(quadVal);
            }
            return pool.pairs.pop();
        }
    }

    /**
     * Efficient input reader for large datasets.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * ProblemC refactored for maintainability and clarity.
 * This program solves the problem of arranging numbers into a symmetric n x n matrix.
 */
public class ProblemC {

    private static final int MAX_VALUE = 1000;

    public static void main(String[] args) {
        FastReader scanner = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            String nInput = scanner.next();
            if (nInput == null) return;

            int n = Integer.parseInt(nInput);
            int[] frequencies = new int[MAX_VALUE + 1];

            // Fill the frequency map with the input numbers
            for (int i = 0; i < n * n; i++) {
                int val = scanner.nextInt();
                if (val <= MAX_VALUE) {
                    frequencies[val]++;
                }
            }

            SymmetrySolver solver = new SymmetrySolver(n, frequencies);

            if (solver.solve()) {
                out.println("YES");
                solver.printMatrix(out);
            } else {
                out.println("NO");
            }
        } catch (Exception e) {
            // In a real-world scenario, use a logger
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Handles the logic for arranging numbers into a symmetric matrix.
     */
    static class SymmetrySolver {
        private final int n;
        private final int[] frequencies;
        private final int[][] matrix;
        private static final int MAX_VAL = 1000;

        public SymmetrySolver(int n, int[] frequencies) {
            this.n = n;
            this.frequencies = frequencies;
            this.matrix = new int[n][n];
        }

        /**
         * Executes the placement strategy: Corners (4-way), then Edges (2-way), then Center (1-way).
         * @return true if the matrix was successfully filled, false otherwise.
         */
        public boolean solve() {
            if (!fillCorners()) return false;

            if (n % 2 != 0) {
                if (!fillEdges()) return false;
                if (!fillCenter()) return false;
            }
            return true;
        }

        private boolean fillCorners() {
            int pointer = 1;
            for (int i = 0; i < n / 2; i++) {
                for (int j = 0; j < n / 2; j++) {
                    // Find the next available number that appears at least 4 times
                    while (pointer <= MAX_VAL && frequencies[pointer] < 4) {
                        pointer++;
                    }

                    if (pointer > MAX_VAL) return false;

                    int value = pointer;
                    matrix[i][j] = value;
                    matrix[i][n - 1 - j] = value;
                    matrix[n - 1 - i][j] = value;
                    matrix[n - 1 - i][n - 1 - j] = value;
                    frequencies[value] -= 4;
                }
            }
            return true;
        }

        private boolean fillEdges() {
            int pointer = 1;

            // Fill vertical center column (2-way symmetry)
            for (int i = 0; i < n / 2; i++) {
                while (pointer <= MAX_VAL && frequencies[pointer] < 2) {
                    pointer++;
                }
                if (pointer > MAX_VAL) return false;

                int value = pointer;
                matrix[i][n / 2] = value;
                matrix[n - 1 - i][n / 2] = value;
                frequencies[value] -= 2;
            }

            // Reset pointer to find next available numbers for horizontal center row
            pointer = 1;
            for (int i = 0; i < n / 2; i++) {
                while (pointer <= MAX_VAL && frequencies[pointer] < 2) {
                    pointer++;
                }
                if (pointer > MAX_VAL) return false;

                int value = pointer;
                matrix[n / 2][i] = value;
                matrix[n / 2][n - 1 - i] = value;
                frequencies[value] -= 2;
            }
            return true;
        }

        private boolean fillCenter() {
            for (int i = 1; i <= MAX_VAL; i++) {
                if (frequencies[i] >= 1) {
                    matrix[n / 2][n / 2] = i;
                    frequencies[i] -= 1;
                    return true;
                }
            }
            return false;
        }

        public void printMatrix(PrintWriter out) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    out.print(matrix[i][j] + (j == n - 1 ? "" : " "));
                }
                out.println();
            }
        }
    }

    /**
     * High-performance utility for reading input.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            return next == null ? 0 : Integer.parseInt(next);
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * Problem: Arrange n^2 numbers in an n x n matrix such that the pattern 
 * is symmetric around the center. 
 * - Even n: Every number must appear in multiples of 4.
 * - Odd n: One number can be at the center (odd count), 
 *   others must satisfy symmetry (multiples of 4 or pairs on middle lines).
 */
public class Main {
    public static void main(String[] args) {
        try {
            new SymmetricMatrixSolver().solve();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

class SymmetricMatrixSolver {
    private static final int MAX_VAL = 1001;

    private final FastReader input = new FastReader();
    private final PrintWriter output = new PrintWriter(System.out);

    private int n;
    private final int[] frequencies = new int[MAX_VAL];
    private final int[][] matrix;

    public SymmetricMatrixSolver() {
        // We can't initialize matrix here because n is read during solve()
        this.matrix = null; 
    }

    // Note: In Java, we can't change the size of an array once initialized.
    // We'll handle matrix initialization inside solve().

    public void solve() throws IOException {
        n = input.nextInt();

        // Initialize matrix with size n x n
        int[][] mat = new int[n][n];

        // Read n^2 numbers and update frequencies
        for (int i = 0; i < n * n; i++) {
            frequencies[input.nextInt()]++;
        }

        if (isPossible()) {
            buildMatrix(mat);
            printResult(mat);
        } else {
            output.println("NO");
        }
        output.flush();
    }

    /**
     * Validates if the input frequencies allow for a symmetric matrix.
     */
    private boolean isPossible() {
        int oddCount = 0;
        int twoModuloFourCount = 0;

        for (int i = 0; i < MAX_VAL; i++) {
            if (frequencies[i] % 2 != 0) {
                oddCount++;
            }
            if (frequencies[i] % 4 == 2) {
                twoModuloFourCount++;
            }
        }

        if (n % 2 == 0) {
            // For even n, every number must have a count divisible by 4
            return oddCount == 0 && twoModuloFourCount == 0;
        } else {
            // For odd n, at most one number can have an odd count (the center)
            // and the number of elements requiring 2-way symmetry (twoModuloFourCount)
            // must fit within the middle row/column pairs (n-1).
            return oddCount <= 1 && twoModuloFourCount <= (n - 1);
        }
    }

    /**
     * Constructs the matrix based on the symmetry rules.
     */
    private void buildMatrix(int[][] mat) {
        // 1. Fill 4-way symmetry (corners)
        // We use numbers that have at least 4 occurrences.
        for (int i = 0; i < n / 2; i++) {
            for (int j = 0; j < n / 2; j++) {
                int val = findValueWithCount(4);
                mat[i][j] = val;
                mat[i][n - j - 1] = val;
                mat[n - i - 1][j] = val;
                mat[n - i - 1][n - j - 1] = val;
                frequencies[val] -= 4;
            }
        }

        // 2. If n is odd, fill middle lines and center
        if (n % 2 != 0) {
            fillMiddleLinesAndCenter(mat);
        }
    }

    private void fillMiddleLinesAndCenter(int[][] mat) {
        Queue<Integer> availablePairs = new LinkedList<>();
        for (int i = 0; i < MAX_VAL; i++) {
            if (frequencies[i] >= 2) {
                availablePairs.add(i);
            }
        }

        // Fill middle row pairs
        for (int j = 0; j < n / 2; j++) {
            int val = findValueWithCountInQueue(availablePairs, 2);
            mat[n / 2][j] = val;
            mat[n / 2][n - j - 1] = val;
            frequencies[val] -= 2;
        }

        // Fill middle column pairs
        for (int i = 0; i < n / 2; i++) {
            int val = findValueWithCountInQueue(availablePairs, 2);
            mat[i][n / 2] = val;
            mat[n - i - 1][n / 2] = val;
            frequencies[val] -= 2;
        }

        // Fill the center cell
        for (int i = 0; i < MAX_VAL; i++) {
            if (frequencies[i] > 0) {
                mat[n / 2][n / 2] = i;
                frequencies[i]--;
                break;
            }
        }
    }

    private int findValueWithCount(int required) {
        for (int i = 0; i < MAX_VAL; i++) {
            if (frequencies[i] >= required) {
                return i;
            }
        }
        return 0; // Should not reach here if isPossible() was true
    }

    private int findValueWithCountInQueue(Queue<Integer> queue, int required) {
        while (!queue.isEmpty() && frequencies[queue.peek()] < required) {
            queue.poll();
        }
        return queue.isEmpty() ? 0 : queue.peek();
    }

    private void printResult(int[][] mat) {
        output.println("YES");
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                output.print(mat[i][j] + (j == n - 1 ? "" : " "));
            }
            output.println();
        }
    }

    /**
     * Efficient input reader for competitive programming tasks.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A utility to solve the Palindromic Matrix puzzle.
 * A palindromic matrix is an n x n matrix that is symmetric 
 * across both the horizontal and vertical axes.
 */
public class PalindromicMatrix {

    public static void main(String[] args) {
        try {
            FastReader reader = new FastReader(System.in);
            int n = reader.nextInt();
            int[] nums = new int[n * n];
            for (int i = 0; i < n * n; i++) {
                nums[i] = reader.nextInt();
            }

            PalindromicMatrixSolver solver = new PalindromicMatrixSolver();
            MatrixResult result = solver.solve(n, nums);

            if (result.isPossible()) {
                System.out.println("YES");
                printMatrix(result.getMatrix());
            } else {
                System.out.println("NO");
            }
        } catch (Exception e) {
            // In a production environment, use a proper logging framework
            System.err.println("An error occurred: " + e.getMessage());
        }
    }

    private static void printMatrix(int[][] matrix) {
        StringBuilder sb = new StringBuilder();
        for (int[] row : matrix) {
            for (int j = 0; j < row.length; j++) {
                sb.append(row[j]).append(j == row.length - 1 ? "" : " ");
            }
            sb.append("\n");
        }
        System.out.print(sb.toString());
    }

    /**
     * Represents the result of the solving attempt.
     */
    static class MatrixResult {
        private final boolean possible;
        private final int[][] matrix;

        public MatrixResult(boolean possible, int[][] matrix) {
            this.possible = possible;
            this.matrix = matrix;
        }

        public boolean isPossible() { return possible; }
        public int[][] getMatrix() { return matrix; }
    }

    /**
     * Core logic for constructing the palindromic matrix.
     */
    static class PalindromicMatrixSolver {

        public MatrixResult solve(int n, int[] nums) {
            Map<Integer, Integer> frequencies = countFrequencies(nums);

            int req4 = calculateRequiredFourBlocks(n);
            int req2 = calculateRequiredTwoBlocks(n);
            int req1 = calculateRequiredOneBlocks(n);

            Deque<Integer> fourBlocks = new ArrayDeque<>();
            Deque<Integer> twoBlocks = new ArrayDeque<>();
            Deque<Integer> oneBlocks = new ArrayDeque<>();

            // Greedily fulfill requirements
            int fourBlocksNeeded = req4;
            for (Map.Entry<Integer, Integer> entry : frequencies.entrySet()) {
                int val = entry.getKey();
                int count = entry.getValue();

                // Use as many 4-blocks as needed/possible
                int take4 = Math.min(count / 4, fourBlocksNeeded);
                for (int i = 0; i < take4; i++) {
                    fourBlocks.add(val);
                }
                count -= (take4 * 4);
                fourBlocksNeeded -= take4;

                // Use remaining counts for 2-blocks and 1-blocks
                while (count >= 2) {
                    twoBlocks.add(val);
                    count -= 2;
                }
                while (count >= 1) {
                    oneBlocks.add(val);
                    count -= 1;
                }
            }

            // Validation
            if (fourBlocksNeeded > 0 || twoBlocks.size() != req2 || oneBlocks.size() != req1) {
                return new MatrixResult(false, null);
            }

            return new MatrixResult(true, constructMatrix(n, fourBlocks, twoBlocks, oneBlocks));
        }

        private Map<Integer, Integer> countFrequencies(int[] nums) {
            Map<Integer, Integer> counts = new HashMap<>();
            for (int num : nums) {
                counts.put(num, counts.getOrDefault(num, 0) + 1);
            }
            return counts;
        }

        private int calculateRequiredFourBlocks(int n) {
            int quadrantSide = n / 2;
            return quadrantSide * quadrantSide;
        }

        private int calculateRequiredTwoBlocks(int n) {
            if (n % 2 == 0) return 0;
            // For odd n, we have (n-1)/2 pairs in the middle row 
            // and (n-1)/2 pairs in the middle column.
            return n - 1;
        }

        private int calculateRequiredOneBlocks(int n) {
            return (n % 2 == 0) ? 0 : 1;
        }

        private int[][] constructMatrix(int n, Deque<Integer> fourBlocks, Deque<Integer> twoBlocks, Deque<Integer> oneBlocks) {
            int[][] matrix = new int[n][n];
            int mid = n / 2;

            // 1. Fill the 4-block quadrant symmetry
            int quadrantSide = n / 2;
            for (int r = 0; r < quadrantSide; r++) {
                for (int c = 0; c < quadrantSide; c++) {
                    int val = fourBlocks.pollFirst();
                    matrix[r][c] = val;
                    matrix[n - 1 - r][c] = val;
                    matrix[r][n - 1 - c] = val;
                    matrix[n - 1 - r][n - 1 - c] = val;
                }
            }

            // 2. Fill the 2-block symmetry (only if n is odd)
            if (n % 2 != 0) {
                // Middle Row pairs
                for (int c = 0; c < mid; c++) {
                    int val = twoBlocks.pollFirst();
                    matrix[mid][c] = val;
                    matrix[mid][n - 1 - c] = val;
                }
                // Middle Column pairs
                for (int r = 0; r < mid; r++) {
                    int val = twoBlocks.pollFirst();
                    matrix[r][mid] = val;
                    matrix[n - 1 - r][mid] = val;
                }
                // Center piece
                matrix[mid][mid] = oneBlocks.pollFirst();
            }

            return matrix;
        }
    }

    /**
     * Faster input reader for handling large datasets efficiently.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver for the Symmetric Grid problem.
 * The goal is to arrange N^2 numbers into an N x N grid such that 
 * elements at symmetric positions (i, j), (i, n-1-j), (n-1-i, j), 
 * and (n-1-i, n-1-j) are identical.
 */
public class SymmetricGridSolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            int n = reader.nextInt();
            if (n <= 0) {
                writer.println("NO");
            } else {
                SymmetricGridProblem problem = new SymmetricGridProblem(n, reader);
                problem.solve(writer);
            }
        } catch (NoSuchElementException e) {
            // Handle unexpected end of input
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Inner class to handle the core logic of the problem.
     */
    static class SymmetricGridProblem {
        private final int n;
        private final int[][] grid;
        private final Map<Integer, Integer> frequencyMap;

        public SymmetricGridProblem(int n, FastReader reader) {
            this.n = n;
            this.grid = new int[n][n];
            this.frequencyMap = new HashMap<>();

            // Initialize grid with -1 to indicate unassigned cells
            for (int i = 0; i < n; i++) {
                Arrays.fill(grid[i], -1);
            }

            // Populate frequency map from input
            for (int i = 0; i < n * n; i++) {
                int val = reader.nextInt();
                frequencyMap.merge(val, 1, Integer::sum);
            }
        }

        public void solve(PrintWriter out) {
            fillGroupsOfFour();

            if (n % 2 != 0) {
                fillGroupsOfTwo();
                fillCenter();
            }

            if (isGridComplete()) {
                out.println("YES");
                printGrid(out);
            } else {
                out.println("NO");
            }
        }

        /**
         * Fills the 4-way symmetric positions.
         */
        private void fillGroupsOfFour() {
            int half = n / 2;
            for (int i = 0; i < half; i++) {
                for (int j = 0; j < half; j++) {
                    Integer value = findAndDecrement(4);
                    if (value != null) {
                        grid[i][j] = value;
                        grid[i][n - 1 - j] = value;
                        grid[n - 1 - i][j] = value;
                        grid[n - 1 - i][n - 1 - j] = value;
                    }
                }
            }
        }

        /**
         * Fills the 2-way symmetric positions (middle row and column) for odd N.
         */
        private void fillGroupsOfTwo() {
            int mid = n / 2;

            // Middle row (excluding center)
            for (int j = 0; j < mid; j++) {
                Integer value = findAndDecrement(2);
                if (value != null) {
                    grid[mid][j] = value;
                    grid[mid][n - 1 - j] = value;
                }
            }

            // Middle column (excluding center)
            for (int i = 0; i < mid; i++) {
                Integer value = findAndDecrement(2);
                if (value != null) {
                    grid[i][mid] = value;
                    grid[n - 1 - i][mid] = value;
                }
            }
        }

        /**
         * Fills the single center position for odd N.
         */
        private void fillCenter() {
            Integer value = findAndDecrement(1);
            if (value != null) {
                grid[n / 2][n / 2] = value;
            }
        }

        /**
         * Helper to find a number in the map with at least 'required' occurrences.
         * @return The number if found, otherwise null.
         */
        private Integer findAndDecrement(int required) {
            for (Map.Entry<Integer, Integer> entry : frequencyMap.entrySet()) {
                if (entry.getValue() >= required) {
                    int val = entry.getKey();
                    entry.setValue(entry.getValue() - required);
                    return val;
                }
            }
            return null;
        }

        private boolean isGridComplete() {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (grid[i][j] == -1) return false;
                }
            }
            return true;
        }

        private void printGrid(PrintWriter out) {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    sb.append(grid[i][j]).append(j == n - 1 ? "" : " ");
                }
                sb.append("\n");
            }
            out.print(sb.toString());
        }
    }

    /**
     * Efficient reader for large input datasets.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver to arrange integers into an n x n matrix that exhibits 
 * reflectional symmetry across both the vertical and horizontal axes.
 */
public class SymmetricMatrixSolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            // Read the dimension of the matrix
            String nInput = reader.next();
            if (nInput == null) return;
            int n = Integer.parseInt(nInput);

            // Read the n^2 elements and count their frequencies
            Map<Integer, Integer> frequencyMap = new HashMap<>();
            for (int i = 0; i < n * n; i++) {
                int val = reader.nextInt();
                frequencyMap.put(val, frequencyMap.getOrDefault(val, 0) + 1);
            }

            SymmetryLogic logic = new SymmetryLogic(n, frequencyMap);
            logic.solve(writer);

        } catch (Exception e) {
            // In a production environment, use a proper logger
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Contains the core logic for constructing the symmetric matrix.
     */
    static class SymmetryLogic {
        private final int n;
        private final Map<Integer, Integer> counts;
        private final List<Integer> distinctValues;
        private final int[][] matrix;

        public SymmetryLogic(int n, Map<Integer, Integer> counts) {
            this.n = n;
            this.counts = counts;
            this.matrix = new int[n][n];
            // Sort distinct values to ensure deterministic greedy selection
            this.distinctValues = new ArrayList<>(counts.keySet());
            Collections.sort(this.distinctValues);
        }

        public void solve(PrintWriter writer) {
            // 1. Fill 4-cell symmetric groups (corners of rectangles)
            // These cells are (i, j), (n-1-i, j), (i, n-1-j), (n-1-i, n-1-j)
            for (int i = 0; i < n / 2; i++) {
                for (int j = 0; j < n / 2; j++) {
                    int val = findAndDecrement(4);
                    if (val == -1) {
                        writer.println("NO");
                        return;
                    }
                    fillFourWay(i, j, val);
                }
            }

            // 2. If n is odd, handle the middle row, middle column, and center cell
            if (n % 2 == 1) {
                int mid = n / 2;

                // Fill vertical pairs in the middle column
                for (int i = 0; i < n / 2; i++) {
                    int val = findAndDecrement(2);
                    if (val == -1) {
                        writer.println("NO");
                        return;
                    }
                    matrix[i][mid] = val;
                    matrix[n - 1 - i][mid] = val;
                }

                // Fill horizontal pairs in the middle row
                for (int j = 0; j < n / 2; j++) {
                    int val = findAndDecrement(2);
                    if (val == -1) {
                        writer.println("NO");
                        return;
                    }
                    matrix[mid][j] = val;
                    matrix[mid][n - 1 - j] = val;
                }

                // Fill the single center cell
                int centerVal = findAndDecrement(1);
                if (centerVal == -1) {
                    writer.println("NO");
                    return;
                }
                matrix[mid][mid] = centerVal;
            }

            // 3. If all requirements met, print the result
            printMatrix(writer);
        }

        private void fillFourWay(int i, int j, int val) {
            matrix[i][j] = val;
            matrix[n - 1 - i][j] = val;
            matrix[i][n - 1 - j] = val;
            matrix[n - 1 - i][n - 1 - j] = val;
        }

        /**
         * Finds the first available number that appears at least 'amount' times.
         * @param amount The required frequency.
         * @return The value found, or -1 if no such value exists.
         */
        private int findAndDecrement(int amount) {
            for (int val : distinctValues) {
                int currentCount = counts.get(val);
                if (currentCount >= amount) {
                    counts.put(val, currentCount - amount);
                    return val;
                }
            }
            return -1;
        }

        private void printMatrix(PrintWriter writer) {
            writer.println("YES");
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    writer.print(matrix[i][j] + (j == n - 1 ? "" : " "));
                }
                writer.println();
            }
        }
    }

    /**
     * Utility class for fast I/O operations.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            return next != null ? Integer.parseInt(next) : 0;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the Palindromic Matrix problem.
 * Constructs an n x n matrix that is symmetric both horizontally and vertically.
 */
public class Main {

    public static void main(String[] args) {
        try {
            FastReader reader = new FastReader(System.in);
            PrintWriter writer = new PrintWriter(System.out);
            PalindromicMatrixSolver solver = new PalindromicMatrixSolver(reader, writer);
            solver.solve();
            writer.flush();
            writer.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    static class PalindromicMatrixSolver {
        private static final int MAX_VALUE = 1000;
        private final FastReader reader;
        private final PrintWriter writer;

        public PalindromicMatrixSolver(FastReader reader, PrintWriter writer) {
            this.reader = reader;
            this.writer = writer;
        }

        /**
         * Main orchestration method to determine if n is even or odd and solve accordingly.
         */
        public void solve() throws IOException {
            int n = reader.nextInt();
            if (n <= 0) return;

            int[] counts = new int[MAX_VALUE + 1];
            for (int i = 0; i < n * n; i++) {
                int val = reader.nextInt();
                if (val != -1) {
                    counts[val]++;
                }
            }

            if (n % 2 == 0) {
                solveEven(n, counts);
            } else {
                solveOdd(n, counts);
            }
        }

        private void solveEven(int n, int[] counts) {
            // For an even-sized palindromic matrix, every element must appear in multiples of 4.
            for (int i = 1; i <= MAX_VALUE; i++) {
                if (counts[i] % 4 != 0) {
                    writer.println("NO");
                    return;
                }
            }

            int[][] matrix = new int[n][n];
            int k = n / 2;
            int currentVal = 1;

            // Fill the quadrants using groups of 4
            for (int i = 0; i < k; i++) {
                for (int j = 0; j < k; j++) {
                    while (currentVal <= MAX_VALUE && counts[currentVal] < 4) {
                        currentVal++;
                    }
                    if (currentVal > MAX_VALUE) {
                        writer.println("NO");
                        return;
                    }

                    int val = currentVal;
                    matrix[i][j] = val;
                    matrix[n - 1 - i][j] = val;
                    matrix[i][n - 1 - j] = val;
                    matrix[n - 1 - i][n - 1 - j] = val;
                    counts[val] -= 4;
                }
            }

            printMatrix(n, matrix);
        }

        private void solveOdd(int n, int[] counts) {
            int centerVal = -1;
            int oddCount = 0;

            // In an odd-sized symmetric matrix, exactly one element must have an odd frequency (the center).
            for (int i = 1; i <= MAX_VALUE; i++) {
                if (counts[i] % 2 != 0) {
                    oddCount++;
                    centerVal = i;
                }
            }

            if (oddCount != 1) {
                writer.println("NO");
                return;
            }

            int[][] matrix = new int[n][n];
            int k = n / 2;

            // Reserve the center element
            counts[centerVal]--;

            // 1. Fill the quadrants (groups of 4)
            int quadValPtr = 1;
            for (int i = 0; i < k; i++) {
                for (int j = 0; j < k; j++) {
                    while (quadValPtr <= MAX_VALUE && counts[quadValPtr] < 4) {
                        quadValPtr++;
                    }
                    if (quadValPtr > MAX_VALUE) {
                        writer.println("NO");
                        return;
                    }
                    int val = quadValPtr;
                    matrix[i][j] = val;
                    matrix[n - 1 - i][j] = val;
                    matrix[i][n - 1 - j] = val;
                    matrix[n - 1 - i][n - 1 - j] = val;
                    counts[val] -= 4;
                }
            }

            // 2. Fill the central axes (excluding the center) using groups of 2
            int pairValPtr = 1;
            // Horizontal axis (middle row)
            for (int j = 0; j < k; j++) {
                while (pairValPtr <= MAX_VALUE && counts[pairValPtr] < 2) {
                    pairValPtr++;
                }
                if (pairValPtr > MAX_VALUE) {
                    writer.println("NO");
                    return;
                }
                int val = pairValPtr;
                matrix[k][j] = val;
                matrix[k][n - 1 - j] = val;
                counts[val] -= 2;
            }
            // Vertical axis (middle column)
            for (int i = 0; i < k; i++) {
                while (pairValPtr <= MAX_VALUE && counts[pairValPtr] < 2) {
                    pairValPtr++;
                }
                if (pairValPtr > MAX_VALUE) {
                    writer.println("NO");
                    return;
                }
                int val = pairValPtr;
                matrix[i][k] = val;
                matrix[n - 1 - i][k] = val;
                counts[val] -= 2;
            }

            // 3. Fill the single center cell
            matrix[k][k] = centerVal;

            printMatrix(n, matrix);
        }

        private void printMatrix(int n, int[][] matrix) {
            writer.println("YES");
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < n; i++) {
                sb.setLength(0);
                for (int j = 0; j < n; j++) {
                    sb.append(matrix[i][j]);
                    if (j < n - 1) sb.append(" ");
                }
                writer.println(sb.toString());
            }
        }
    }

    /**
     * High-performance input reader for handling large datasets.
     */
    static class FastReader {
        private final InputStream in;
        private final byte[] buffer = new byte[65536];
        private int pointer = 0;
        private int bufferLength = 0;

        public FastReader(InputStream in) {
            this.in = in;
        }

        private boolean fillBuffer() throws IOException {
            bufferLength = in.read(buffer);
            pointer = 0;
            return bufferLength > 0;
        }

        private byte read() throws IOException {
            if (pointer >= bufferLength) {
                if (!fillBuffer()) return -1;
            }
            return buffer[pointer++];
        }

        public int nextInt() throws IOException {
            byte c = read();
            while (c >= 0 && c <= 32) c = read();
            if (c == -1) return -1;
            int neg = 1;
            if (c == '-') {
                neg = -1;
                c = read();
            }
            int res = 0;
            while (c >= '0' && c <= '9') {
                res = res * 10 + (c - '0');
                c = read();
            }
            return res * neg;
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A solver that attempts to construct an n x n matrix based on frequency constraints
 * where the matrix exhibits specific symmetries.
 */
public class SymmetryMatrixSolver {

    private static final int MAX_VALUE = 1000;
    private static final int FREQUENCY_ARRAY_SIZE = MAX_VALUE + 1;

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            solve(reader, writer);
        } finally {
            writer.close();
        }
    }

    /**
     * Core logic to read input, construct the matrix, and output the result.
     */
    private static void solve(FastReader reader, PrintWriter writer) {
        int n = reader.nextInt();
        if (n <= 0) return;

        int[] counts = new int[FREQUENCY_ARRAY_SIZE];
        for (int i = 0; i < n * n; i++) {
            int val = reader.nextInt();
            if (val >= 0 && val <= MAX_VALUE) {
                counts[val]++;
            }
        }

        int[][] matrix = new int[n][n];

        // 1. Fill the 4-way symmetric quadrants
        int currentValue = 0;
        int halfN = n / 2;
        for (int i = 0; i < halfN; i++) {
            int symRow = (n - 1) - i;
            for (int j = 0; j < halfN; j++) {
                int symCol = (n - 1) - j;

                currentValue = findNextAvailableValue(counts, 4, currentValue);
                if (currentValue == -1) {
                    printFailure(writer);
                    return;
                }

                matrix[i][j] = matrix[symRow][j] = matrix[i][symCol] = matrix[symRow][symCol] = currentValue;
                counts[currentValue] -= 4;
            }
        }

        // 2. Handle the middle row and column if n is odd
        if (n % 2 == 1) {
            int mid = n / 2;
            // Reset search index for middle elements to find usable frequencies from the start
            currentValue = 0;

            for (int i = 0; i < mid; i++) {
                int symIndex = (n - 1) - i;

                // Fill middle row (horizontal symmetry)
                currentValue = findNextAvailableValue(counts, 2, currentValue);
                if (currentValue == -1) {
                    printFailure(writer);
                    return;
                }
                matrix[mid][i] = matrix[mid][symIndex] = currentValue;
                counts[currentValue] -= 2;

                // Fill middle column (vertical symmetry)
                currentValue = findNextAvailableValue(counts, 2, currentValue);
                if (currentValue == -1) {
                    printFailure(writer);
                    return;
                }
                matrix[i][mid] = matrix[symIndex][mid] = currentValue;
                counts[currentValue] -= 2;
            }

            // Fill the very center cell
            int centerValue = findNextAvailableValue(counts, 1, 0);
            if (centerValue == -1) {
                printFailure(writer);
                return;
            }
            matrix[mid][mid] = centerValue;
        }

        printSuccess(writer, matrix);
    }

    /**
     * Finds the next integer in the range [0, MAX_VALUE] that has at least 'minFrequency' remaining.
     * 
     * @param counts The frequency array.
     * @param minFrequency The minimum required count.
     * @param startSearchIndex The index to start searching from to optimize.
     * @return The found value, or -1 if no such value exists.
     */
    private static int findNextAvailableValue(int[] counts, int minFrequency, int startSearchIndex) {
        for (int i = startSearchIndex; i <= MAX_VALUE; i++) {
            if (counts[i] >= minFrequency) {
                return i;
            }
        }
        return -1;
    }

    private static void printSuccess(PrintWriter writer, int[][] matrix) {
        writer.println("YES");
        for (int[] row : matrix) {
            for (int i = 0; i < row.length; i++) {
                writer.print(row[i] + (i == row.length - 1 ? "" : " "));
            }
            writer.println();
        }
    }

    private static void printFailure(PrintWriter writer) {
        writer.println("NO");
    }

    /**
     * Optimized Reader for fast integer input.
     */
    static class FastReader {
        private final InputStream in;
        private final byte[] buffer = new byte[1024 * 8];
        private int pointer = 0;
        private int bufferLength = 0;

        public FastReader(InputStream in) {
            this.in = in;
        }

        private int readByte() {
            if (pointer >= bufferLength) {
                pointer = 0;
                try {
                    bufferLength = in.read(buffer);
                } catch (IOException e) {
                    return -1;
                }
                if (bufferLength <= 0) return -1;
            }
            return buffer[pointer++];
        }

        public int nextInt() {
            int c = readByte();
            while (c >= 0 && c <= 32) c = readByte();
            if (c == -1) return -1;
            int neg = 1;
            if (c == '-') {
                neg = -1;
                c = readByte();
            }
            int res = 0;
            while (c >= '0' && c <= '9') {
                res = res * 10 + (c - '0');
                c = readByte();
            }
            return res * neg;
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * Solves the problem of constructing a matrix with specific rotational/reflective symmetry.
 * The construction requires elements to be placed in sets of 1 (center), 2 (middle cross), 
 * or 4 (quadrants) to maintain symmetry across both axes.
 */
public class SymmetricMatrixConstructor {

    private static final int MAX_VALUE = 1000;

    public static void main(String[] args) {
        FastReader sc = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = sc.nextInt();
            int[] counts = new int[MAX_VALUE + 1];

            // Read n*n elements and count frequencies
            for (int i = 0; i < n * n; i++) {
                int val = sc.nextInt();
                if (val <= MAX_VALUE) {
                    counts[val]++;
                }
            }

            int[][] result = constructSymmetricMatrix(n, counts);

            if (result == null) {
                out.println("NO");
            } else {
                out.println("YES");
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < n; j++) {
                        out.print(result[i][j]);
                        if (j < n - 1) {
                            out.print(" ");
                        }
                    }
                    out.println();
                }
            }
        } catch (Exception e) {
            // Handle potential input errors
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Attempts to construct a symmetric matrix based on the provided counts.
     * 
     * @param n The dimension of the square matrix.
     * @param counts Frequency array of the numbers.
     * @return A 2D array representing the matrix, or null if construction is impossible.
     */
    private static int[][] constructSymmetricMatrix(int n, int[] counts) {
        int oddCount = 0;
        int oddVal = -1;

        // Count how many numbers have odd frequencies
        for (int i = 1; i <= MAX_VALUE; i++) {
            if (counts[i] % 2 != 0) {
                oddCount++;
                oddVal = i;
            }
        }

        // Validation: If n is even, no number can have an odd frequency.
        // If n is odd, exactly one number must have an odd frequency (for the center).
        if (n % 2 == 0) {
            if (oddCount != 0) return null;
        } else {
            if (oddCount != 1) return null;
        }

        int[][] matrix = new int[n][n];
        int halfSize = n / 2;

        // 1. Place the center element for odd-sized matrices
        if (n % 2 != 0) {
            matrix[halfSize][halfSize] = oddVal;
            counts[oddVal]--;
        }

        int currentVal = 1;
        boolean preferPairs = true;

        // 2. Fill the middle cross (column and row) for odd-sized matrices
        if (n % 2 != 0) {
            // Fill vertical middle column pairs: (i, m) and (n-1-i, m)
            for (int i = 0; i < halfSize; i++) {
                if (preferPairs) {
                    while (currentVal <= MAX_VALUE && counts[currentVal] % 4 != 2) {
                        currentVal++;
                    }
                    if (currentVal > MAX_VALUE) {
                        currentVal = 1;
                        preferPairs = false;
                    }
                }
                while (currentVal <= MAX_VALUE && counts[currentVal] == 0) {
                    currentVal++;
                }
                if (currentVal > MAX_VALUE) return null;

                matrix[i][halfSize] = matrix[n - 1 - i][halfSize] = currentVal;
                counts[currentVal] -= 2;
            }

            // Fill horizontal middle row pairs: (m, j) and (m, n-1-j)
            for (int j = 0; j < halfSize; j++) {
                if (preferPairs) {
                    while (currentVal <= MAX_VALUE && counts[currentVal] % 4 != 2) {
                        currentVal++;
                    }
                    if (currentVal > MAX_VALUE) {
                        currentVal = 1;
                        preferPairs = false;
                    }
                }
                while (currentVal <= MAX_VALUE && counts[currentVal] == 0) {
                    currentVal++;
                }
                if (currentVal > MAX_VALUE) return null;

                matrix[halfSize][j] = matrix[halfSize][n - 1 - j] = currentVal;
                counts[currentVal] -= 2;
            }
        }

        // 3. Fill the remaining quadrants using sets of 4
        currentVal = 1;
        for (int i = 0; i < halfSize; i++) {
            for (int j = 0; j < halfSize; j++) {
                while (currentVal <= MAX_VALUE && counts[currentVal] == 0) {
                    currentVal++;
                }
                if (currentVal > MAX_VALUE || counts[currentVal] % 4 != 0) {
                    return null;
                }

                int val = currentVal;
                matrix[i][j] = matrix[n - 1 - i][j] = 
                               matrix[i][n - 1 - j] = matrix[n - 1 - i][n - 1 - j] = val;
                counts[val] -= 4;
            }
        }

        return matrix;
    }

    /**
     * Fast I/O helper class.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

/**
 * A solver that attempts to fill an N x N grid using values provided in the input.
 * The strategy is to greedily use the most frequent values to fill larger 
 * geometric patterns (4-cell blocks, 2-cell strips, and 1-cell centers) 
 * to ensure the grid is filled symmetrically.
 */
public class GridPatternSolver {

    private static final int MAX_VALUE_RANGE = 1001;

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        Solver solver = new Solver();
        solver.solve(reader, writer);

        writer.flush();
        writer.close();
        reader.close();
    }

    static class Solver {

        /**
         * Executes the solving logic.
         * 
         * @param reader The input reader.
         * @param out    The output writer.
         */
        void solve(FastReader reader, PrintWriter out) {
            int gridSize = reader.nextInt();
            int[] inputValues = reader.nextIntArray(gridSize * gridSize);

            // Count frequencies of each value
            int[] frequencyMap = new int[MAX_VALUE_RANGE];
            for (int val : inputValues) {
                frequencyMap[val]++;
            }

            // Priority Queue to process values with highest frequency first
            PriorityQueue<Integer> valuePriorityQueue = new PriorityQueue<>(
                    (a, b) -> Integer.compare(frequencyMap[b], frequencyMap[a])
            );

            for (int i = 0; i < MAX_VALUE_RANGE; i++) {
                if (frequencyMap[i] > 0) {
                    valuePriorityQueue.add(i);
                }
            }

            // Generate geometric patterns available for filling
            Deque<int[][]> fourCellPatterns = new ArrayDeque<>();
            Deque<int[][]> twoCellPatterns = new ArrayDeque<>();
            Deque<int[][]> oneCellPatterns = new ArrayDeque<>();
            preparePatterns(gridSize, fourCellPatterns, twoCellPatterns, oneCellPatterns);

            int[][] grid = new int[gridSize][gridSize];
            boolean possible = true;

            // Greedy allocation of patterns
            while (!valuePriorityQueue.isEmpty()) {
                int currentValue = valuePriorityQueue.poll();
                int remainingCount = frequencyMap[currentValue];

                if (remainingCount <= 0) continue;

                while (remainingCount > 0) {
                    if (remainingCount >= 4 && !fourCellPatterns.isEmpty()) {
                        fillPattern(grid, fourCellPatterns.poll(), currentValue);
                        remainingCount -= 4;
                    } else if (remainingCount >= 2 && !twoCellPatterns.isEmpty()) {
                        fillPattern(grid, twoCellPatterns.poll(), currentValue);
                        remainingCount -= 2;
                    } else if (remainingCount >= 1 && !oneCellPatterns.isEmpty()) {
                        fillPattern(grid, oneCellPatterns.poll(), currentValue);
                        remainingCount -= 1;
                    } else {
                        // Cannot satisfy the current value's count with available patterns
                        possible = false;
                        break;
                    }
                }

                if (!possible) break;
            }

            if (possible) {
                out.println("YES");
                printGrid(grid, out);
            } else {
                out.println("NO");
            }
        }

        private void preparePatterns(int n, Deque<int[][]> fours, Deque<int[][]> twos, Deque<int[][]> ones) {
            // Fill 4-cell patterns (quadrants)
            for (int i = 0, ii = n - 1; i < n / 2; i++, ii--) {
                for (int j = 0, jj = n - 1; j < n / 2; j++, jj--) {
                    fours.add(new int[][]{{i, j}, {ii, j}, {i, jj}, {ii, jj}});
                }
            }

            // If N is odd, handle the middle row, middle column, and center cell
            if (n % 2 == 1) {
                int mid = n / 2;
                for (int i = 0, ii = n - 1; i < n / 2; i++, ii--) {
                    // Vertical strips in the middle column
                    twos.add(new int[][]{{i, mid}, {ii, mid}});
                    // Horizontal strips in the middle row
                    twos.add(new int[][]{{mid, i}, {mid, ii}});
                }
                // The single center cell
                ones.add(new int[][]{{mid, mid}});
            }
        }

        private void fillPattern(int[][] grid, int[][] pattern, int value) {
            for (int[] coord : pattern) {
                grid[coord[0]][coord[1]] = value;
            }
        }

        private void printGrid(int[][] grid, PrintWriter out) {
            for (int[] row : grid) {
                for (int i = 0; i < row.length; i++) {
                    out.print(row[i] + (i == row.length - 1 ? "" : " "));
                }
                out.println();
            }
        }
    }

    /**
     * High-performance input reader for large datasets.
     */
    static class FastReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1 << 22];
        private int curChar;
        private int numChars;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        public FastReader(String s) {
            this.stream = new ByteArrayInputStream(s.getBytes(StandardCharsets.UTF_8));
        }

        public void close() {
            try {
                stream.close();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }

        private int read() {
            if (numChars == -1) throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buffer);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) return -1;
            }
            return buffer[curChar++];
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res = res * 10 + (c - '0');
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public int[] nextIntArray(int n) {
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }
    }
}

