/**
 * Handles the core logic of grouping cells and greedily assigning numbers.
 */
class PalindromeMatrixSolver {
    private static final int MAX_VAL_RANGE = 1000;
    private final int n;
    private final int[] numbers;

    public PalindromeMatrixSolver(int n, int[] numbers) {
        this.n = n;
        this.numbers = numbers;
    }

    /**
     * Solves the problem using a greedy approach.
     * Groups are sorted by size (descending) to satisfy larger symmetry constraints first.
     */
    public SolverResult solve() {
        int[] frequencies = new int[MAX_VAL_RANGE + 1];
        for (int num : numbers) {
            if (num <= MAX_VAL_RANGE) {
                frequencies[num]++;
            }
        }

        List<List<Coordinate>> groups = createSymmetricGroups();
        // Sort groups by size descending
        groups.sort((a, b) -> Integer.compare(b.size(), a.size()));

        int[][] matrix = new int[n][n];

        for (List<Coordinate> group : groups) {
            int groupSize = group.size();
            boolean assigned = false;

            for (int val = 0; val <= MAX_VAL_RANGE; val++) {
                if (frequencies[val] >= groupSize) {
                    for (Coordinate coord : group) {
                        matrix[coord.row][coord.col] = val;
                    }
                    frequencies[val] -= groupSize;
                    assigned = true;
                    break;
                }
            }

            if (!assigned) {
                return new SolverResult(false, null);
            }
        }

        return new SolverResult(true, matrix);
    }

    /**
     * Identifies groups of cells that must contain the same value to maintain symmetry.
     */
    private List<List<Coordinate>> createSymmetricGroups() {
        List<List<Coordinate>> groups = new ArrayList<>();
        boolean[][] visited = new boolean[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (visited[i][j]) continue;

                // A cell (i, j) belongs to a group of up to 4 symmetric cells
                Set<Coordinate> groupSet = new HashSet<>();
                groupSet.add(new Coordinate(i, j));
                groupSet.add(new Coordinate(i, n - 1 - j));
                groupSet.add(new Coordinate(n - 1 - i, j));
                groupSet.add(new Coordinate(n - 1 - i, n - 1 - j));

                List<Coordinate> group = new ArrayList<>(groupSet);
                groups.add(group);

                for (Coordinate coord : group) {
                    visited[coord.row][coord.col] = true;
                }
            }
        }
        return groups;
    }
}

/**
 * Represents a 2D coordinate in the matrix.
 */
class Coordinate {
    final int row;
    final int col;

    Coordinate(int row, int col) {
        this.row = row;
        this.col = col;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof Coordinate)) return false;
        Coordinate that = (Coordinate) o;
        return row == that.row && col == that.col;
    }

    @Override
    public int hashCode() {
        return Objects.hash(row, col);
    }
}

/**
 * High-performance input reader using a buffered byte stream.
 */
class FastReader {
    private final InputStream in;
    private final byte[] buffer = new byte[1024];
    private int pointer = 0;
    private int bufferLength = 0;

    public FastReader(InputStream in) {
        this.in = in;
    }

    private int readByte() throws IOException {
        if (pointer >= bufferLength) {
            pointer = 0;
            bufferLength = in.read(buffer);
            if (bufferLength <= 0) return -1;
        }
        return buffer[pointer++];
    }

    public int readInt() throws IOException {
        int c = readByte();
        while (c >= 0 && c <= 32) c = readByte();
        if (c == -1) throw new IOException("EOF");

        int sign = 1;
        if (c == '-') {
            sign = -1;
            c = readByte();
        }

        int res = 0;
        while (c >= '0' && c <= '9') {
            res = res * 10 + (c - '0');
            c = readByte();
        }
        return res * sign;
    }

    public int[] readIntArray(int size) throws IOException {
        int[] array = new int[size];
        for (int i = 0; i < size; i++) {
            array[i] = readInt();
        }
        return array;
    }
}

