import java.io.*;
import java.util.StringTokenizer;

/**
 * A solution to construct an n x n matrix that is symmetric both horizontally and vertically
 * using a provided set of numbers.
 */
public class Main {

    public static void main(String[] args) {
        // Using try-with-resources to ensure automatic closing of I/O streams.
        try (FastReader in = new FastReader(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            PalindromicMatrixSolver solver = new PalindromicMatrixSolver();
            solver.solve(in, out);

        } catch (Exception e) {
            // In production, use a professional logging framework.
            e.printStackTrace();
        }
    }

    /**
     * Contains the core logic for calculating the palindromic matrix.
     */
    static class PalindromicMatrixSolver {
        private static final int MAX_VAL_LIMIT = 1000;

        /**
         * Orchestrates the process of reading input, solving the matrix, and printing output.
         */
        public void solve(FastReader in, PrintWriter out) {
            int n = in.nextInt();
            if (n <= 0) return;

            int[] frequencies = new int[MAX_VAL_LIMIT + 1];
            for (int i = 0; i < n * n; i++) {
                int val = in.nextInt();
                if (val >= 0 && val <= MAX_VAL_LIMIT) {
                    frequencies[val]++;
                }
            }

            int[][] matrix = new int[n][n];

            // Step 1: Fill the 4-way symmetric cells (corners and quadrants).
            // These require 4 identical numbers.
            fillSymmetricFour(matrix, frequencies, n);

            // Step 2: If the dimension is odd, handle the middle row and column.
            if (n % 2 != 0) {
                int mid = n / 2;
                // Middle row and column require 2 identical numbers.
                fillSymmetricTwoRow(matrix, frequencies, n, mid);
                fillSymmetricTwoCol(matrix, frequencies, n, mid);

                // Step 3: The center cell requires 1 number.
                fillCenter(matrix, frequencies, n, mid);
            }

            // Validate the construction and output result.
            if (isMatrixFullyPopulated(matrix)) {
                out.println("YES");
                printMatrix(matrix, out);
            } else {
                out.println("NO");
            }
        }

        private void fillSymmetricFour(int[][] matrix, int[] frequencies, int n) {
            int currentVal = 1;
            for (int i = 0; i < n / 2; i++) {
                for (int j = 0; j < n / 2; j++) {
                    while (currentVal <= MAX_VAL_LIMIT && frequencies[currentVal] < 4) {
                        currentVal++;
                    }

                    if (currentVal <= MAX_VAL_LIMIT) {
                        matrix[i][j] = currentVal;
                        matrix[i][n - 1 - j] = currentVal;
                        matrix[n - 1 - i][j] = currentVal;
                        matrix[n - 1 - i][n - 1 - j] = currentVal;
                        frequencies[currentVal] -= 4;
                    }
                }
            }
        }

        private void fillSymmetricTwoRow(int[][] matrix, int[] frequencies, int n, int mid) {
            int currentVal = 0;
            for (int j = 0; j < n / 2; j++) {
                while (currentVal <= MAX_VAL_LIMIT && frequencies[currentVal] < 2) {
                    currentVal++;
                }
                if (currentVal <= MAX_VAL_LIMIT) {
                    matrix[mid][j] = currentVal;
                    matrix[mid][n - 1 - j] = currentVal;
                    frequencies[currentVal] -= 2;
                }
            }
        }

        private void fillSymmetricTwoCol(int[][] matrix, int[] frequencies, int n, int mid) {
            int currentVal = 0;
            for (int i = 0; i < n / 2; i++) {
                while (currentVal <= MAX_VAL_LIMIT && frequencies[currentVal] < 2) {
                    currentVal++;
                }
                if (currentVal <= MAX_VAL_LIMIT) {
                    matrix[i][mid] = currentVal;
                    matrix[n - 1 - i][mid] = currentVal;
                    frequencies[currentVal] -= 2;
                }
            }
        }

        private void fillCenter(int[][] matrix, int[] frequencies, int n, int mid) {
            int currentVal = 0;
            while (currentVal <= MAX_VAL_LIMIT && frequencies[currentVal] < 1) {
                currentVal++;
            }
            if (currentVal <= MAX_VAL_LIMIT) {
                matrix[mid][mid] = currentVal;
                frequencies[currentVal]--;
            }
        }

        private boolean isMatrixFullyPopulated(int[][] matrix) {
            for (int[] row : matrix) {
                for (int cell : row) {
                    if (cell == 0) return false;
                }
            }
            return true;
        }

        private void printMatrix(int[][] matrix, PrintWriter out) {
            for (int[] row : matrix) {
                for (int j = 0; j < row.length; j++) {
                    out.print(row[j]);
                    if (j < row.length - 1) {
                        out.print(" ");
                    }
                }
                out.println();
            }
        }
    }

    /**
     * Utility class for fast input parsing.
     */
    static class FastReader implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            this.reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }

        @Override
        public void close() throws IOException {
            reader.close();
        }
    }
}

import java.util.*;
import java.io.*;

public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            String nStr = reader.next();
            if (nStr == null) return;
            int n = Integer.parseInt(nStr);
            int[] elements = new int[n * n];
            for (int i = 0; i < elements.length; i++) {
                elements[i] = reader.nextInt();
            }

            MatrixBuilder builder = new MatrixBuilder(n);
            MatrixResult result = builder.build(elements);

            if (result.isSuccess()) {
                out.println("YES");
                result.print(out);
            } else {
                out.println("NO");
            }
        } catch (Exception e) {
            // Silent catch for competitive programming style
        } finally {
            out.flush();
            out.close();
        }
    }

    static class MatrixResult {
        private final boolean success;
        private final int[][] matrix;

        public MatrixResult(boolean success, int[][] matrix) {
            this.success = success;
            this.matrix = matrix;
        }

        public boolean isSuccess() { return success; }

        public void print(PrintWriter out) {
            if (matrix == null) return;
            for (int[] row : matrix) {
                StringBuilder sb = new StringBuilder();
                for (int j = 0; j < row.length; j++) {
                    sb.append(row[j]).append(j == row.length - 1 ? "" : " ");
                }
                out.println(sb.toString());
            }
        }
    }

    static class MatrixBuilder {
        private final int n;

        public MatrixBuilder(int n) {
            this.n = n;
        }

        public MatrixResult build(int[] elements) {
            if (n == 1) {
                return new MatrixResult(true, new int[][]{{elements[0]}});
            }

            TreeMap<Integer, Integer> frequencies = new TreeMap<>();
            for (int val : elements) {
                frequencies.put(val, frequencies.getOrDefault(val, 0) + 1);
            }

            if (n % 2 == 1) return solveOdd(frequencies);
            else return solveEven(frequencies);
        }

        private MatrixResult solveOdd(TreeMap<Integer, Integer> frequencies) {
            int[][] matrix = new int[n][n];
            int center = n / 2;
            int centerValue = -1;
            int oddCount = 0;

            for (Map.Entry<Integer, Integer> entry : frequencies.entrySet()) {
                if (entry.getValue() % 2 != 0) {
                    centerValue = entry.getKey();
                    oddCount++;
                    frequencies.put(entry.getKey(), entry.getValue() - 1);
                }
            }

            if (oddCount != 1) return new MatrixResult(false, null);
            matrix[center][center] = centerValue;

            int row = 0, col = 0;
            int half = n / 2;

            // 4-way symmetry
            for (Map.Entry<Integer, Integer> entry : frequencies.entrySet()) {
                int val = entry.getKey();
                int count = entry.getValue();
                while (count >= 4 && row < half) {
                    matrix[row][col] = matrix[row][n - 1 - col] = 
                    matrix[n - 1 - row][col] = matrix[n - 1 - row][n - 1 - col] = val;
                    count -= 4;
                    frequencies.put(val, count);
                    col++;
                    if (col == half) { row++; col = 0; }
                }
            }

            if (row != half) return new MatrixResult(false, null);

            // 2-way symmetry
            int hori = 0, vert = 0;
            for (Map.Entry<Integer, Integer> entry : frequencies.entrySet()) {
                int val = entry.getKey();
                int count = entry.getValue();
                while (count > 0) {
                    if (count < 2) return new MatrixResult(false, null);
                    count -= 2;
                    frequencies.put(val, count);
                    if (hori < half) {
                        matrix[center][hori] = matrix[center][n - 1 - hori] = val;
                        hori++;
                    } else {
                        matrix[vert][center] = matrix[n - 1 - vert][center] = val;
                        vert++;
                    }
                }
            }
            return new MatrixResult(true, matrix);
        }

        private MatrixResult solveEven(TreeMap<Integer, Integer> frequencies) {
            int[][] matrix = new int[n][n];
            int half = n / 2;
            for (int count : frequencies.values()) {
                if (count % 4 != 0) return new MatrixResult(false, null);
            }

            int row = 0, col = 0;
            for (Map.Entry<Integer, Integer> entry : frequencies.entrySet()) {
                int val = entry.getKey();
                int count = entry.getValue();
                while (count > 0) {
                    matrix[row][col] = matrix[row][n - 1 - col] = 
                    matrix[n - 1 - row][col] = matrix[n - 1 - row][n - 1 - col] = val;
                    count -= 4;
                    col++;
                    if (col == half) { row++; col = 0; }
                }
            }
            return new MatrixResult(true, matrix);
        }
    }

    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) { return null; }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() { return Integer.parseInt(next()); }
    }
}

import java.util.*;
import java.io.*;

/**
 * Solution for constructing a symmetric n x n grid from a given set of integers.
 * The grid must satisfy rotational/reflectional symmetry based on the value groups.
 */
public class Codeforces {

    private static final int MAX_ELEMENT_VALUE = 1000;

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            int n = reader.nextInt();
            int[] elements = reader.nextIntArray(n * n);

            SymmetryGridSolver solver = new SymmetryGridSolver(n, elements);
            GridResult result = solver.solve();

            if (result.isPossible()) {
                out.println("YES");
                printMatrix(out, result.getGrid());
            } else {
                out.println("NO");
            }
        } catch (Exception e) {
            // In competitive programming, standard practice is to fail silently 
            // or handle IO errors specifically.
        } finally {
            out.close();
        }
    }

    private static void printMatrix(PrintWriter out, int[][] grid) {
        for (int[] row : grid) {
            for (int i = 0; i < row.length; i++) {
                out.print(row[i] + (i == row.length - 1 ? "" : " "));
            }
            out.println();
        }
    }

    /**
     * Encapsulates the result of the symmetry solver.
     */
    static class GridResult {
        private final boolean possible;
        private final int[][] grid;

        public GridResult(boolean possible, int[][] grid) {
            this.possible = possible;
            this.grid = grid;
        }

        public boolean isPossible() {
            return possible;
        }

        public int[][] getGrid() {
            return grid;
        }
    }

    /**
     * Core logic to solve the symmetric grid construction problem.
     */
    static class SymmetryGridSolver {
        private final int n;
        private final int[] frequencyMap;
        private final Deque<Integer> availableElements;

        public SymmetryGridSolver(int n, int[] elements) {
            this.n = n;
            this.frequencyMap = new int[MAX_ELEMENT_VALUE + 1];
            this.availableElements = new ArrayDeque<>();
            for (int val : elements) {
                if (val <= MAX_ELEMENT_VALUE) {
                    frequencyMap[val]++;
                }
            }
        }

        public GridResult solve() {
            int[][] grid = new int[n][n];
            int half = n / 2;

            // 1. Fill Quadrants: Requires groups of 4
            int quadrantSetsNeeded = half * half;
            if (!extractElements(quadrantSetsNeeded, 4)) {
                return new GridResult(false, null);
            }

            for (int i = 0; i < half; i++) {
                for (int j = 0; j < half; j++) {
                    int val = availableElements.removeFirst();
                    grid[i][j] = grid[n - 1 - i][j] = grid[i][n - 1 - j] = grid[n - 1 - i][n - 1 - j] = val;
                }
            }

            // If n is even, we are done.
            if (n % 2 == 0) {
                return new GridResult(true, grid);
            }

            // 2. Fill Middle Row and Column: Requires groups of 2
            // Middle column (excluding center) and Middle row (excluding center)
            int middlePairsNeeded = (half * 2); // 2 pairs for column, 2 pairs for row
            if (!extractElements(middlePairsNeeded, 2)) {
                return new GridResult(false, null);
            }

            // Fill middle column
            for (int i = 0; i < half; i++) {
                int val = availableElements.removeFirst();
                grid[i][half] = grid[n - 1 - i][half] = val;
            }
            // Fill middle row
            for (int j = 0; j < half; j++) {
                int val = availableElements.removeFirst();
                grid[half][j] = grid[half][n - 1 - j] = val;
            }

            // 3. Fill Center Cell: Requires 1 single element
            if (!extractElements(1, 1)) {
                return new GridResult(false, null);
            }
            grid[half][half] = availableElements.removeFirst();

            return new GridResult(true, grid);
        }

        /**
         * Attempts to pull the required number of sets of a specific size from the frequency map.
         * 
         * @param setsNeeded How many sets of elements we need.
         * @param setSize How many identical elements make up one set.
         * @return true if successfully extracted, false otherwise.
         */
        private boolean extractElements(int setsNeeded, int setSize) {
            int extracted = 0;
            for (int i = 1; i <= MAX_ELEMENT_VALUE && extracted < setsNeeded; i++) {
                while (frequencyMap[i] >= setSize && extracted < setsNeeded) {
                    availableElements.add(i);
                    frequencyMap[i] -= setSize;
                    extracted++;
                }
            }
            return extracted == setsNeeded;
        }
    }

    /**
     * Fast I/O utility for reading input.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public int[] nextIntArray(int size) {
            int[] arr = new int[size];
            for (int i = 0; i < size; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * ProblemC: Solves the symmetric matrix construction problem.
 * A symmetric matrix is constructed such that for every cell (i, j),
 * the values at (i, j), (n-1-i, j), (i, n-1-j), and (n-1-i, n-1-j) are identical.
 */
public class ProblemC {

    public static void main(String[] args) throws IOException {
        FastReader sc = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        // Read n and handle potential empty input
        String firstLine = sc.next();
        if (firstLine == null) {
            out.close();
            return;
        }
        int n = Integer.parseInt(firstLine);
        int totalCells = n * n;

        // Step 1: Count frequencies of each number provided in the input
        Map<Integer, Integer> frequencies = new HashMap<>();
        for (int i = 0; i < totalCells; i++) {
            int val = sc.nextInt();
            frequencies.put(val, frequencies.getOrDefault(val, 0) + 1);
        }

        // Step 2: Identify required symmetric groups (4-way, 2-way, or 1-way symmetry)
        List<List<int[]>> groupsOf4 = new ArrayList<>();
        List<List<int[]>> groupsOf2 = new ArrayList<>();
        List<int[]> groupOf1 = new ArrayList<>();
        boolean[][] visited = new boolean[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (visited[i][j]) continue;

                // Identify unique symmetric coordinates for the current cell
                Set<Integer> uniqueCellIndices = new HashSet<>();
                uniqueCellIndices.add(i * n + j);
                uniqueCellIndices.add((n - 1 - i) * n + j);
                uniqueCellIndices.add(i * n + (n - 1 - j));
                uniqueCellIndices.add((n - 1 - i) * n + (n - 1 - j));

                List<int[]> currentGroup = new ArrayList<>();
                for (int index : uniqueCellIndices) {
                    int r = index / n;
                    int c = index % n;
                    currentGroup.add(new int[]{r, c});
                    visited[r][c] = true;
                }

                // Categorize the group by its size
                int size = currentGroup.size();
                if (size == 4) {
                    groupsOf4.add(currentGroup);
                } else if (size == 2) {
                    groupsOf2.add(currentGroup);
                } else if (size == 1) {
                    groupOf1.add(currentGroup.get(0));
                }
            }
        }

        // Step 3: Decompose input frequencies into available groups
        List<Integer> available4 = new ArrayList<>();
        List<Integer> available2 = new ArrayList<>();
        List<Integer> available1 = new ArrayList<>();

        for (Map.Entry<Integer, Integer> entry : frequencies.entrySet()) {
            int val = entry.getKey();
            int freq = entry.getValue();

            for (int i = 0; i < freq / 4; i++) available4.add(val);
            int rem = freq % 4;
            for (int i = 0; i < rem / 2; i++) available2.add(val);
            int rem2 = rem % 2;
            for (int i = 0; i < rem2; i++) available1.add(val);
        }

        // Step 4: Greedily allocate resources to the required slots
        int[][] matrix = new int[n][n];

        // Fill groups of 4
        if (available4.size() < groupsOf4.size()) {
            out.println("NO");
            out.close();
            return;
        }
        for (int i = 0; i < groupsOf4.size(); i++) {
            int val = available4.get(i);
            for (int[] cell : groupsOf4.get(i)) {
                matrix[cell[0]][cell[1]] = val;
            }
        }

        // Downgrade leftover 4-count groups to 2-count groups
        for (int i = groupsOf4.size(); i < available4.size(); i++) {
            available2.add(available4.get(i));
            available2.add(available4.get(i));
        }

        // Fill groups of 2
        if (available2.size() < groupsOf2.size()) {
            out.println("NO");
            out.close();
            return;
        }
        for (int i = 0; i < groupsOf2.size(); i++) {
            int val = available2.get(i);
            for (int[] cell : groupsOf2.get(i)) {
                matrix[cell[0]][cell[1]] = val;
            }
        }

        // Downgrade leftover 2-count groups to 1-count groups
        for (int i = groupsOf2.size(); i < available2.size(); i++) {
            available1.add(available2.get(i));
            available1.add(available2.get(i));
        }

        // Fill groups of 1
        if (available1.size() < groupOf1.size()) {
            out.println("NO");
            out.close();
            return;
        }
        for (int i = 0; i < groupOf1.size(); i++) {
            int[] cell = groupOf1.get(i);
            matrix[cell[0]][cell[1]] = available1.get(i);
        }

        // Step 5: Output the result
        out.println("YES");
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                sb.append(matrix[i][j]);
                if (j < n - 1) sb.append(" ");
            }
            sb.append("\n");
        }
        out.print(sb.toString());
        out.close();
    }

    /**
     * FastReader class for efficient input parsing.
     */
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;

/**
 * A tool to arrange a set of integers into an n x n grid 
 * such that the grid satisfies central symmetry requirements.
 */
public class SymmetricGridSolver {

    /**
     * Represents a coordinate in the grid.
     */
    private static class Point {
        final int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Point)) return false;
            Point point = (Point) o;
            return r == point.r && c == point.c;
        }

        @Override
        public int hashCode() {
            return Objects.hash(r, c);
        }
    }

    private final int n;
    private final int[][] grid;
    private final TreeMap<Integer, Integer> frequencyMap;

    public SymmetricGridSolver(int n, int[] inputNums) {
        this.n = n;
        this.grid = new int[n][n];
        this.frequencyMap = new TreeMap<>();
        for (int num : inputNums) {
            frequencyMap.put(num, frequencyMap.getOrDefault(num, 0) + 1);
        }
    }

    /**
     * Executes the symmetry-based grid filling algorithm.
     */
    public void solve() {
        // Categorize sets of coordinates that must share the same value.
        Deque<Set<Point>> setsOf4 = new ArrayDeque<>();
        Deque<Set<Point>> setsOf2 = new ArrayDeque<>();
        Deque<Set<Point>> setsOf1 = new ArrayDeque<>();

        boolean[][] visited = new boolean[n][n];

        // Step 1: Identify all unique sets of coordinates under central symmetry.
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (!visited[r][c]) {
                    Set<Point> symmetrySet = new HashSet<>();

                    // A cell (r, c) is part of a symmetry set consisting of:
                    // (r, c), (r, n-1-c), (n-1-r, c), and (n-1-r, n-1-c)
                    int[][] potentialPoints = {
                        {r, c},
                        {r, n - 1 - c},
                        {n - 1 - r, c},
                        {n - 1 - r, n - 1 - c}
                    };

                    for (int[] p : potentialPoints) {
                        symmetrySet.add(new Point(p[0], p[1]));
                    }

                    // Mark all points in this symmetry set as visited to avoid duplicates.
                    for (Point pt : symmetrySet) {
                        visited[pt.r][pt.c] = true;
                    }

                    // Group sets by size (1, 2, or 4).
                    int size = symmetrySet.size();
                    if (size == 4) {
                        setsOf4.addLast(symmetrySet);
                    } else if (size == 2) {
                        setsOf2.addLast(symmetrySet);
                    } else if (size == 1) {
                        setsOf1.addLast(symmetrySet);
                    }
                }
            }
        }

        // Step 2: Fill the sets using available number frequencies.
        // We iterate through sorted keys to maintain deterministic behavior.
        List<Integer> sortedValues = new ArrayList<>(frequencyMap.keySet());

        // Fill sets requiring 4 identical numbers first.
        for (int val : sortedValues) {
            while (!setsOf4.isEmpty() && frequencyMap.get(val) >= 4) {
                Set<Point> set = setsOf4.pollFirst();
                fillSet(set, val);
                frequencyMap.put(val, frequencyMap.get(val) - 4);
            }
        }

        // Fill sets requiring 2 identical numbers.
        for (int val : sortedValues) {
            while (!setsOf2.isEmpty() && frequencyMap.get(val) >= 2) {
                Set<Point> set = setsOf2.pollFirst();
                fillSet(set, val);
                frequencyMap.put(val, frequencyMap.get(val) - 2);
            }
        }

        // Fill sets requiring 1 number (center of an odd-sized grid).
        for (int val : sortedValues) {
            while (!setsOf1.isEmpty() && frequencyMap.get(val) >= 1) {
                Set<Point> set = setsOf1.pollFirst();
                fillSet(set, val);
                frequencyMap.put(val, frequencyMap.get(val) - 1);
            }
        }

        // Step 3: Validation.
        // If all sets are filled and all input numbers are consumed, the grid is valid.
        if (setsOf4.isEmpty() && setsOf2.isEmpty() && setsOf1.isEmpty() && allCountsZero()) {
            printResult(true);
        } else {
            printResult(false);
        }
    }

    private void fillSet(Set<Point> set, int value) {
        for (Point p : set) {
            grid[p.r][p.c] = value;
        }
    }

    private boolean allCountsZero() {
        for (int count : frequencyMap.values()) {
            if (count > 0) return false;
        }
        return true;
    }

    private void printResult(boolean success) {
        if (success) {
            System.out.println("YES");
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    sb.append(grid[i][j]);
                    if (j < n - 1) sb.append(" ");
                }
                sb.append("\n");
            }
            System.out.print(sb.toString());
        } else {
            System.out.println("NO");
        }
    }

    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            if (!sc.hasNextInt()) return;

            int n = sc.nextInt();
            int[] nums = new int[n * n];
            for (int i = 0; i < n * n; i++) {
                nums[i] = sc.nextInt();
            }

            SymmetricGridSolver solver = new SymmetricGridSolver(n, nums);
            solver.solve();
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A program to determine if an N x N matrix can be constructed 
 * to satisfy palindromic symmetry requirements using a given set of numbers.
 */
public class PalindromicMatrix {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = scanner.nextInt();
            int[] inputNumbers = scanner.readIntArray(n * n);

            MatrixSolver solver = new MatrixSolver(n, inputNumbers);
            if (solver.solve()) {
                out.println("YES");
                printMatrix(out, solver.getMatrix());
            } else {
                out.println("NO");
            }
        } catch (NoSuchElementException e) {
            // Handle potential empty input
        } finally {
            out.flush();
            out.close();
        }
    }

    private static void printMatrix(PrintWriter out, int[][] matrix) {
        for (int[] row : matrix) {
            for (int j = 0; j < row.length; j++) {
                out.print(row[j] + (j == row.length - 1 ? "" : " "));
            }
            out.println();
        }
    }

    /**
     * Core logic class for solving the Palindromic Matrix problem.
     */
    static class MatrixSolver {
        private final int n;
        private final int[][] matrix;
        private final PriorityQueue<NumberFrequency> frequencyQueue;

        public MatrixSolver(int n, int[] inputNumbers) {
            this.n = n;
            this.matrix = new int[n][n];
            this.frequencyQueue = new PriorityQueue<>(Collections.reverseOrder());
            buildFrequencyQueue(inputNumbers);
        }

        private void buildFrequencyQueue(int[] inputNumbers) {
            Map<Integer, Integer> counts = new HashMap<>();
            for (int num : inputNumbers) {
                counts.put(num, counts.getOrDefault(num, 0) + 1);
            }
            for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
                frequencyQueue.offer(new NumberFrequency(entry.getKey(), entry.getValue()));
            }
        }

        /**
         * Attempts to fill the matrix according to symmetry rules.
         * @return true if the matrix was successfully constructed, false otherwise.
         */
        public boolean solve() {
            // 1. Fill the four-way symmetric quadrants
            if (!fillFourWaySymmetry()) {
                return false;
            }

            // 2. If N is odd, fill the middle row, middle column, and center
            if (n % 2 != 0) {
                if (!fillMiddleAxisSymmetry() || !fillCenter()) {
                    return false;
                }
            }

            return true;
        }

        private boolean fillFourWaySymmetry() {
            int half = n / 2;
            for (int i = 0; i < half; i++) {
                for (int j = 0; j < half; j++) {
                    NumberFrequency element = tryPollWithCount(4);
                    if (element == null) return false;

                    int val = element.value;
                    matrix[i][j] = val;
                    matrix[n - 1 - i][j] = val;
                    matrix[n - 1 - i][n - 1 - j] = val;
                    matrix[i][n - 1 - j] = val;

                    element.decrement(4);
                    if (element.count > 0) {
                        frequencyQueue.offer(element);
                    }
                }
            }
            return true;
        }

        private boolean fillMiddleAxisSymmetry() {
            int half = n / 2;
            int mid = n / 2;

            // Fill middle row (excluding center)
            for (int j = 0; j < half; j++) {
                NumberFrequency element = tryPollWithCount(2);
                if (element == null) return false;

                int val = element.value;
                matrix[mid][j] = val;
                matrix[mid][n - 1 - j] = val;

                element.decrement(2);
                if (element.count > 0) {
                    frequencyQueue.offer(element);
                }
            }

            // Fill middle column (excluding center)
            for (int i = 0; i < half; i++) {
                NumberFrequency element = tryPollWithCount(2);
                if (element == null) return false;

                int val = element.value;
                matrix[i][mid] = val;
                matrix[n - 1 - i][mid] = val;

                element.decrement(2);
                if (element.count > 0) {
                    frequencyQueue.offer(element);
                }
            }
            return true;
        }

        private boolean fillCenter() {
            if (frequencyQueue.isEmpty()) return false;

            NumberFrequency element = frequencyQueue.poll();
            matrix[n / 2][n / 2] = element.value;
            element.decrement(1);
            // We don't strictly need to put it back as it's the last cell
            return true;
        }

        private NumberFrequency tryPollWithCount(int required) {
            if (frequencyQueue.isEmpty() || frequencyQueue.peek().count < required) {
                return null;
            }
            return frequencyQueue.poll();
        }

        public int[][] getMatrix() {
            return matrix;
        }
    }

    /**
     * Helper class to track number values and their remaining frequencies.
     */
    static class NumberFrequency implements Comparable<NumberFrequency> {
        int value;
        int count;

        public NumberFrequency(int value, int count) {
            this.value = value;
            this.count = count;
        }

        public void decrement(int amount) {
            this.count -= amount;
        }

        @Override
        public int compareTo(NumberFrequency other) {
            return Integer.compare(this.count, other.count);
        }
    }

    /**
     * Fast I/O utility.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream in) {
            this.reader = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public int[] readIntArray(int size) {
            int[] array = new int[size];
            for (int i = 0; i < size; i++) {
                array[i] = nextInt();
            }
            return array;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A utility to solve the problem of arranging numbers in an N x N grid
 * such that the grid is symmetric under 180-degree rotation and 
 * horizontal/vertical reflections.
 */
public class SymmetricGridSolver {

    private static final int MAX_VALUE = 1000;

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int n = reader.nextInt();
            if (n <= 0) {
                writer.println("NO");
                return;
            }

            int[] counts = new int[MAX_VALUE + 1];
            for (int i = 0; i < n * n; i++) {
                int val = reader.nextInt();
                if (val <= MAX_VALUE) {
                    counts[val]++;
                }
            }

            SymmetrySolver solver = new SymmetrySolver(n, counts);
            int[][] resultGrid = solver.solve();

            if (resultGrid == null) {
                writer.println("NO");
            } else {
                writer.println("YES");
                printGrid(writer, resultGrid);
            }
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    private static void printGrid(PrintWriter writer, int[][] grid) {
        for (int[] row : grid) {
            for (int j = 0; j < row.length; j++) {
                writer.print(row[j] + (j == row.length - 1 ? "" : " "));
            }
            writer.println();
        }
    }

    /**
     * Core logic to attempt to build the symmetric grid.
     */
    static class SymmetrySolver {
        private final int gridSize;
        private final Queue<Integer> fourSetQueue = new LinkedList<>();
        private final Queue<Integer> twoSetQueue = new LinkedList<>();
        private final Queue<Integer> oneSetQueue = new LinkedList<>();

        public SymmetrySolver(int n, int[] counts) {
            this.gridSize = n;
            distributeCounts(counts);
        }

        /**
         * Categorizes available numbers into groups of 4, 2, and 1.
         */
        private void distributeCounts(int[] counts) {
            for (int i = 0; i <= MAX_VALUE; i++) {
                int remaining = counts[i];

                // Extract as many groups of 4 as possible
                while (remaining >= 4) {
                    fourSetQueue.add(i);
                    remaining -= 4;
                }
                // Extract a group of 2 if possible
                if (remaining >= 2) {
                    twoSetQueue.add(i);
                    remaining -= 2;
                }
                // Extract a group of 1 if possible
                if (remaining >= 1) {
                    oneSetQueue.add(i);
                }
            }
        }

        /**
         * Attempts to fill the grid following the symmetry constraints.
         * @return The filled grid, or null if no valid arrangement exists.
         */
        public int[][] solve() {
            int[][] grid = new int[gridSize][gridSize];

            // Step 1: Handle the center and axes for odd-sized grids
            if (gridSize % 2 != 0) {
                if (!fillOddGridAxes(grid)) {
                    return null;
                }
            }

            // Step 2: Fill all remaining empty cells in symmetric quadruplets
            if (!fillRemainingCells(grid)) {
                return null;
            }

            return grid;
        }

        private boolean fillOddGridAxes(int[][] grid) {
            int mid = gridSize / 2;

            // Fill center element
            if (oneSetQueue.isEmpty()) return false;
            grid[mid][mid] = oneSetQueue.poll();

            // Fill the middle row and middle column (the "axes")
            for (int j = 0; j < mid; j++) {
                // Check if we can use two groups of 2 for the 4 symmetric axis cells
                if (twoSetQueue.size() >= 2) {
                    int val1 = twoSetQueue.poll();
                    grid[mid][j] = val1;
                    grid[mid][gridSize - j - 1] = val1;

                    int val2 = twoSetQueue.poll();
                    grid[j][mid] = val2;
                    grid[gridSize - j - 1][mid] = val2;
                } 
                // Otherwise, use one group of 4
                else if (!fourSetQueue.isEmpty()) {
                    int val = fourSetQueue.poll();
                    grid[mid][j] = val;
                    grid[mid][gridSize - j - 1] = val;
                    grid[j][mid] = val;
                    grid[gridSize - j - 1][mid] = val;
                } else {
                    return false;
                }
            }
            return true;
        }

        private boolean fillRemainingCells(int[][] grid) {
            for (int i = 0; i < gridSize; i++) {
                for (int j = 0; j < gridSize; j++) {
                    if (grid[i][j] != 0) continue;

                    // We need a group of 4 for (i, j), (i, revCol), (revRow, j), (revRow, revCol)
                    if (fourSetQueue.isEmpty()) {
                        return false;
                    }

                    int val = fourSetQueue.poll();
                    int revRow = gridSize - i - 1;
                    int revCol = gridSize - j - 1;

                    grid[i][j] = val;
                    grid[i][revCol] = val;
                    grid[revRow][j] = val;
                    grid[revRow][revCol] = val;
                }
            }
            return true;
        }
    }

    /**
     * Fast I/O reader for competitive programming scenarios.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * SymmetricGridSolver attempts to arrange a set of numbers into an N x N grid
 * such that the grid maintains specific symmetries (4-way, 2-way, and 1-way).
 */
public class SymmetricGridSolver {

    /**
     * Represents a group of identical numbers and their occurrences.
     */
    private static class NumberGroup implements Comparable<NumberGroup> {
        final int value;
        int count;

        NumberGroup(int value, int count) {
            this.value = value;
            this.count = count;
        }

        @Override
        public int compareTo(NumberGroup other) {
            // Primary sort: Frequency descending
            int freqCompare = Integer.compare(other.count, this.count);
            if (freqCompare != 0) {
                return freqCompare;
            }
            // Secondary sort: Value ascending
            return Integer.compare(this.value, other.value);
        }
    }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;

            int n = scanner.nextInt();
            int totalElements = n * n;
            int[] inputValues = new int[totalElements];

            for (int i = 0; i < totalElements; i++) {
                inputValues[i] = scanner.nextInt();
            }

            SymmetricGridSolver solver = new SymmetricGridSolver();
            solver.solve(n, inputValues);

        } catch (Exception e) {
            // In a production environment, use a proper logger
            e.printStackTrace();
        }
    }

    /**
     * Coordinates the process of calculating frequencies, filling the grid, and printing the result.
     */
    public void solve(int gridSize, int[] inputValues) {
        PriorityQueue<NumberGroup> frequencyQueue = buildFrequencyQueue(inputValues);
        int[][] grid = new int[gridSize][gridSize];

        if (tryFillGrid(gridSize, grid, frequencyQueue)) {
            printGrid("YES", grid);
        } else {
            printGrid("NO", null);
        }
    }

    /**
     * Counts frequencies of numbers and returns a PriorityQueue sorted by frequency.
     * Complexity: O(N^2) where N is the grid dimension.
     */
    private PriorityQueue<NumberGroup> buildFrequencyQueue(int[] nums) {
        Map<Integer, Integer> frequencyMap = new HashMap<>();
        for (int num : nums) {
            frequencyMap.put(num, frequencyMap.getOrDefault(num, 0) + 1);
        }

        PriorityQueue<NumberGroup> pq = new PriorityQueue<>();
        for (Map.Entry<Integer, Integer> entry : frequencyMap.entrySet()) {
            pq.add(new NumberGroup(entry.getKey(), entry.getValue()));
        }
        return pq;
    }

    /**
     * Attempts to fill the grid following the symmetry rules.
     * Returns true if successful, false otherwise.
     */
    private boolean tryFillGrid(int n, int[][] grid, PriorityQueue<NumberGroup> pq) {
        // 1. Fill 4-way symmetric corners
        if (!fillFourWaySymmetry(n, grid, pq)) {
            return false;
        }

        // 2. If N is odd, fill 2-way symmetric edges and 1-way center
        if (n % 2 != 0) {
            if (!fillTwoWaySymmetry(n, grid, pq)) {
                return false;
            }
            if (!fillCenter(n, grid, pq)) {
                return false;
            }
        }

        return true;
    }

    /**
     * Fills the quadrants of the grid (4-way symmetry).
     */
    private boolean fillFourWaySymmetry(int n, int[][] grid, PriorityQueue<NumberGroup> pq) {
        int half = n / 2;
        for (int i = 0; i < half; i++) {
            for (int j = 0; j < half; j++) {
                NumberGroup group = pq.poll();
                if (group == null || group.count < 4) {
                    return false;
                }

                grid[i][j] = group.value;
                grid[n - 1 - i][j] = group.value;
                grid[i][n - 1 - j] = group.value;
                grid[n - 1 - i][n - 1 - j] = group.value;

                group.count -= 4;
                if (group.count > 0) {
                    pq.add(group);
                }
            }
        }
        return true;
    }

    /**
     * Fills the middle row and column (2-way symmetry).
     */
    private boolean fillTwoWaySymmetry(int n, int[][] grid, PriorityQueue<NumberGroup> pq) {
        int mid = n / 2;

        // Fill middle row edges
        for (int i = 0; i < mid; i++) {
            NumberGroup group = pq.poll();
            if (group == null || group.count < 2) {
                return false;
            }
            grid[mid][i] = group.value;
            grid[mid][n - 1 - i] = group.value;

            group.count -= 2;
            if (group.count > 0) {
                pq.add(group);
            }
        }

        // Fill middle column edges
        for (int i = 0; i < mid; i++) {
            NumberGroup group = pq.poll();
            if (group == null || group.count < 2) {
                return false;
            }
            grid[i][mid] = group.value;
            grid[n - 1 - i][mid] = group.value;

            group.count -= 2;
            if (group.count > 0) {
                pq.add(group);
            }
        }
        return true;
    }

    /**
     * Fills the exact center cell.
     */
    private boolean fillCenter(int n, int[][] grid, PriorityQueue<NumberGroup> pq) {
        int mid = n / 2;
        NumberGroup group = pq.poll();
        if (group == null) {
            return false;
        }
        grid[mid][mid] = group.value;
        return true;
    }

    /**
     * Handles formatted output of the result.
     */
    private void printGrid(String status, int[][] grid) {
        StringBuilder sb = new StringBuilder();
        sb.append(status).append("\n");

        if (grid != null) {
            for (int[] row : grid) {
                for (int i = 0; i < row.length; i++) {
                    sb.append(row[i]);
                    if (i < row.length - 1) {
                        sb.append(" ");
                    }
                }
                sb.append("\n");
            }
        }
        System.out.print(sb.toString());
    }
}

import java.util.*;
import java.io.*;

/**
 * A utility to construct an n x n matrix from a given set of numbers 
 * such that symmetric positions in the matrix contain the same value.
 */
public class SymmetricMatrixBuilder {

    /**
     * Represents a coordinate in the matrix.
     */
    private static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Point point)) return false;
            return row == point.row && col == point.col;
        }

        @Override
        public int hashCode() {
            return Objects.hash(row, col);
        }
    }

    /**
     * Tracks the frequency of a specific number.
     */
    private static class FrequencyCounter {
        int value;
        int remainingCount;

        FrequencyCounter(int value, int count) {
            this.value = value;
            this.remainingCount = count;
        }
    }

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        int matrixSize = reader.nextInt();

        if (matrixSize <= 0) {
            System.out.println("NO");
            return;
        }

        // Step 1: Count frequencies of all input numbers
        Map<Integer, Integer> frequencyMap = new HashMap<>();
        int totalElements = matrixSize * matrixSize;
        for (int i = 0; i < totalElements; i++) {
            int val = reader.nextInt();
            frequencyMap.put(val, frequencyMap.getOrDefault(val, 0) + 1);
        }

        // Step 2: Prepare elements for greedy selection
        // We sort by frequency ascending to use the least "flexible" numbers first
        List<FrequencyCounter> elements = new ArrayList<>();
        for (var entry : frequencyMap.entrySet()) {
            elements.add(new FrequencyCounter(entry.getKey(), entry.getValue()));
        }
        elements.sort(Comparator.comparingInt(e -> e.remainingCount));

        // Step 3: Group symmetric cells together
        // Every cell (r, c) belongs to a set of symmetric points:
        // (r, c), (r, n-1-c), (n-1-r, c), (n-1-r, n-1-c)
        List<List<Point>> symmetricGroups = new ArrayList<>();
        boolean[][] visited = new boolean[matrixSize][matrixSize];

        for (int r = 0; r < matrixSize; r++) {
            for (int c = 0; c < matrixSize; c++) {
                if (visited[r][c]) continue;

                Set<Point> groupSet = new LinkedHashSet<>();
                groupSet.add(new Point(r, c));
                groupSet.add(new Point(r, matrixSize - 1 - c));
                groupSet.add(new Point(matrixSize - 1 - r, c));
                groupSet.add(new Point(matrixSize - 1 - r, matrixSize - 1 - c));

                List<Point> group = new ArrayList<>(groupSet);
                symmetricGroups.add(group);

                for (Point p : group) {
                    visited[p.row][p.col] = true;
                }
            }
        }

        // Step 4: Sort groups by size descending (process largest groups first)
        symmetricGroups.sort((a, b) -> Integer.compare(b.size(), a.size()));

        // Step 5: Fill the matrix
        int[][] matrix = new int[matrixSize][matrixSize];
        boolean possible = true;

        for (List<Point> group : symmetricGroups) {
            int requiredSize = group.size();
            FrequencyCounter selectedElement = null;

            // Find the first available number that can satisfy this group's size
            for (FrequencyCounter element : elements) {
                if (element.remainingCount >= requiredSize) {
                    selectedElement = element;
                    break;
                }
            }

            if (selectedElement == null) {
                possible = false;
                break;
            }

            // Consume the required amount from the chosen element
            selectedElement.remainingCount -= requiredSize;
            for (Point p : group) {
                matrix[p.row][p.col] = selectedElement.value;
            }
        }

        // Step 6: Output results
        if (possible) {
            printMatrix(matrix, matrixSize);
        } else {
            System.out.println("NO");
        }
    }

    private static void printMatrix(int[][] matrix, int n) {
        System.out.println("YES");
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                sb.append(matrix[i][j]).append(" ");
            }
            sb.append("\n");
        }
        System.out.print(sb.toString());
    }

    /**
     * Fast I/O helper class.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A solver that reconstructs an N x N grid satisfying rotational and reflective symmetry
 * based on a provided set of numbers.
 */
public final class SymmetryGridSolver {

    /**
     * Represents a value and its remaining occurrence count in the frequency pool.
     */
    private static class FrequencyNode implements Comparable<FrequencyNode> {
        int value;
        int count;

        public FrequencyNode(int value, int count) {
            this.value = value;
            this.count = count;
        }

        @Override
        public int compareTo(FrequencyNode other) {
            // Max-heap: higher counts come first
            return Integer.compare(other.count, this.count);
        }
    }

    /**
     * Efficient input reader for large datasets.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }

    private final int n;
    private final int[][] grid;
    private final PriorityQueue<FrequencyNode> frequencyQueue;

    public SymmetryGridSolver(int n, Map<Integer, Integer> frequencies) {
        this.n = n;
        this.grid = new int[n][n];
        this.frequencyQueue = new PriorityQueue<>();

        for (Map.Entry<Integer, Integer> entry : frequencies.entrySet()) {
            frequencyQueue.add(new FrequencyNode(entry.getKey(), entry.getValue()));
        }
    }

    /**
     * Attempts to retrieve a value from the pool that has at least 'required' occurrences.
     * @param required The number of times this value must be used to satisfy symmetry.
     * @return The value if successful, null otherwise.
     */
    private Integer getNextValue(int required) {
        if (frequencyQueue.isEmpty()) {
            return null;
        }

        FrequencyNode top = frequencyQueue.poll();
        if (top.count < required) {
            // Put it back and fail if we can't satisfy the symmetry requirement
            frequencyQueue.add(top);
            return null;
        }

        int value = top.value;
        top.count -= required;
        if (top.count > 0) {
            frequencyQueue.add(top);
        }
        return value;
    }

    /**
     * Executes the core logic to fill the grid and prints the result.
     */
    public void solve() {
        PrintWriter out = new PrintWriter(System.out);

        // 1. Fill the quadrants (groups of 4)
        for (int i = 0; i < n / 2; i++) {
            for (int j = 0; j < n / 2; j++) {
                Integer val = getNextValue(4);
                if (val == null) {
                    out.println("NO");
                    out.flush();
                    return;
                }
                grid[i][j] = val;
                grid[i][n - 1 - j] = val;
                grid[n - 1 - i][j] = val;
                grid[n - 1 - i][n - 1 - j] = val;
            }
        }

        // 2. Handle middle row and column for odd N (groups of 2)
        if (n % 2 != 0) {
            int mid = n / 2;

            // Middle Row
            for (int j = 0; j < mid; j++) {
                Integer val = getNextValue(2);
                if (val == null) {
                    out.println("NO");
                    out.flush();
                    return;
                }
                grid[mid][j] = val;
                grid[mid][n - 1 - j] = val;
            }

            // Middle Column
            for (int i = 0; i < mid; i++) {
                Integer val = getNextValue(2);
                if (val == null) {
                    out.println("NO");
                    out.flush();
                    return;
                }
                grid[i][mid] = val;
                grid[n - 1 - i][mid] = val;
            }

            // 3. Handle the absolute center (group of 1)
            Integer centerVal = getNextValue(1);
            if (centerVal == null) {
                out.println("NO");
                out.flush();
                return;
            }
            grid[mid][mid] = centerVal;
        }

        // Success: Print the grid
        out.println("YES");
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                out.print(grid[i][j] + (j == n - 1 ? "" : " "));
            }
            out.println();
        }
        out.flush();
    }

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        String nInput = reader.next();
        if (nInput == null) return;

        int n = Integer.parseInt(nInput);
        Map<Integer, Integer> freqMap = new HashMap<>();

        // Read N*N elements and build frequency map
        for (int i = 0; i < n * n; i++) {
            int val = reader.nextInt();
            freqMap.put(val, freqMap.getOrDefault(val, 0) + 1);
        }

        SymmetryGridSolver solver = new SymmetryGridSolver(n, freqMap);
        solver.solve();
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to arrange n*n numbers into a symmetric grid.
 * A symmetric grid requires elements to appear in groups of 4 (corners/quadrants),
 * groups of 2 (middle axes), or 1 (center).
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int n = reader.nextInt();
            int[] inputs = new int[n * n];
            for (int i = 0; i < n * n; i++) {
                inputs[i] = reader.nextInt();
            }

            SymmetryGridSolver solver = new SymmetryGridSolver(n, inputs);
            solver.solve(writer);
        } catch (IOException e) {
            writer.println("Error reading input: " + e.getMessage());
        } finally {
            writer.flush();
            writer.close();
        }
    }

    static class SymmetryGridSolver {
        private static final int MAX_VALUE = 1000;

        private final int n;
        private final int[] frequencyMap;
        private final Deque<Integer> quadruplets = new ArrayDeque<>();
        private final Deque<Integer> pairs = new ArrayDeque<>();
        private final Deque<Integer> singles = new ArrayDeque<>();

        private final int neededFours;
        private final int neededTwos;
        private final int neededOnes;

        public SymmetryGridSolver(int n, int[] inputs) {
            this.n = n;
            this.frequencyMap = new int[MAX_VALUE + 1];

            // Calculate symmetry requirements
            this.neededFours = (n / 2) * (n / 2);
            this.neededTwos = (n % 2 == 0) ? 0 : 2 * (n / 2);
            this.neededOnes = (n % 2 == 0) ? 0 : 1;

            countFrequencies(inputs);
            categorizeNumbers();
        }

        private void countFrequencies(int[] inputs) {
            for (int val : inputs) {
                if (val <= MAX_VALUE) {
                    frequencyMap[val]++;
                }
            }
        }

        private void categorizeNumbers() {
            for (int i = 0; i <= MAX_VALUE; i++) {
                int count = frequencyMap[i];

                int numQuads = count / 4;
                for (int j = 0; j < numQuads; j++) quadruplets.add(i);
                count %= 4;

                int numPairs = count / 2;
                for (int j = 0; j < numPairs; j++) pairs.add(i);
                count %= 2;

                if (count > 0) singles.add(i);
            }
        }

        public void solve(PrintWriter out) {
            redistributeFoursToTwos();

            if (canFormGrid()) {
                out.println("YES");
                int[][] grid = buildGrid();
                printGrid(grid, out);
            } else {
                out.println("NO");
            }
        }

        /**
         * If we lack enough pairs to satisfy symmetry, we break down quadruplets.
         */
        private void redistributeFoursToTwos() {
            while (pairs.size() < neededTwos && !quadruplets.isEmpty()) {
                int val = quadruplets.pollLast();
                pairs.add(val);
                pairs.add(val);
            }
        }

        private boolean canFormGrid() {
            return quadruplets.size() == neededFours &&
                   pairs.size() == neededTwos &&
                   singles.size() == neededOnes;
        }

        private int[][] buildGrid() {
            int[][] grid = new int[n][n];

            // Fill quadrants (4-way symmetry)
            for (int i = 0; i < n / 2; i++) {
                for (int j = 0; j < n / 2; j++) {
                    int val = quadruplets.pollLast();
                    grid[i][j] = val;
                    grid[n - 1 - i][j] = val;
                    grid[n - 1 - i][n - 1 - j] = val;
                    grid[i][n - 1 - j] = val;
                }
            }

            // Fill middle axis (2-way symmetry) for odd n
            if (n % 2 != 0) {
                // Middle Column
                for (int i = 0; i < n / 2; i++) {
                    int val = pairs.pollLast();
                    grid[i][n / 2] = val;
                    grid[n - 1 - i][n / 2] = val;
                }
                // Middle Row
                for (int i = 0; i < n / 2; i++) {
                    int val = pairs.pollLast();
                    grid[n / 2][i] = val;
                    grid[n / 2][n - 1 - i] = val;
                }
                // Center Point
                grid[n / 2][n / 2] = singles.pollFirst();
            }

            return grid;
        }

        private void printGrid(int[][] grid, PrintWriter out) {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
