/**
 * Main entry point for the Grid Symmetry Solver.
 */
public class Main {
    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int n = reader.nextInt();
            if (n <= 0) {
                writer.close();
                return;
            }

            // Frequency array for numbers 0-1000
            int[] counts = new int[1001];
            int totalElements = n * n;
            for (int i = 0; i < totalElements; i++) {
                int val = reader.nextInt();
                if (val >= 0 && val <= 1000) {
                    counts[val]++;
                }
            }

            SymmetrySolver solver = new SymmetrySolver(n, counts);
            solver.solve(writer);

        } catch (Exception e) {
            // In a real-world scenario, log this error.
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Utility class for fast input parsing.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            return next != null ? Integer.parseInt(next) : 0;
        }
    }

    /**
     * Represents a group of cells in the grid that must share the same value 
     * due to symmetry constraints.
     */
    static class SymmetryGroup {
        final int size;
        final List<int[]> coordinates;

        SymmetryGroup(int size) {
            this.size = size;
            this.coordinates = new ArrayList<>();
        }

        void add(int r, int c) {
            coordinates.add(new int[]{r, c});
        }
    }

    /**
     * Encapsulates the logic to solve the grid symmetry problem.
     */
    static class SymmetrySolver {
        private static final int MAX_VAL = 1000;
        private final int n;
        private final int[] counts;
        private final int[][] grid;

        public SymmetrySolver(int n, int[] counts) {
            this.n = n;
            this.counts = counts.clone();
            this.grid = new int[n][n];
        }

        /**
         * Executes the greedy algorithm to fill the grid.
         */
        public void solve(PrintWriter out) {
            List<SymmetryGroup> groupsOf4 = new ArrayList<>();
            List<SymmetryGroup> groupsOf2 = new ArrayList<>();
            List<SymmetryGroup> groupsOf1 = new ArrayList<>();

            generateSymmetryGroups(groupsOf4, groupsOf2, groupsOf1);

            // Greedy approach: satisfy the largest requirements (4) first, then 2, then 1.
            if (!processGroups(groupsOf4, 4, out)) return;
            if (!processGroups(groupsOf2, 2, out)) return;
            if (!processGroups(groupsOf1, 1, out)) return;

            out.println("YES");
            printGrid(out);
        }

        private void generateSymmetryGroups(List<SymmetryGroup> g4, List<SymmetryGroup> g2, List<SymmetryGroup> g1) {
            // We only need to iterate through one quadrant of the grid to find unique symmetry groups.
            for (int i = 0; i < (n + 1) / 2; i++) {
                for (int j = 0; j < (n + 1) / 2; j++) {
                    boolean isHorizontalMidline = (i == n - 1 - i);
                    boolean isVerticalMidline = (j == n - 1 - j);

                    int size;
                    if (!isHorizontalMidline && !isVerticalMidline) {
                        size = 4;
                    } else if (isHorizontalMidline ^ isVerticalMidline) {
                        size = 2;
                    } else {
                        size = 1;
                    }

                    SymmetryGroup group = new SymmetryGroup(size);
                    group.add(i, j);
                    if (!isHorizontalMidline) group.add(n - 1 - i, j);
                    if (!isVerticalMidline) group.add(i, n - 1 - j);
                    if (!isHorizontalMidline && !isVerticalMidline) group.add(n - 1 - i, n - 1 - j);

                    if (size == 4) g4.add(group);
                    else if (size == 2) g2.add(group);
                    else g1.add(group);
                }
            }
        }

        private boolean processGroups(List<SymmetryGroup> groups, int requiredSize, PrintWriter out) {
            int smallestAvailableIdx = 1;
            for (SymmetryGroup group : groups) {
                int foundValue = -1;
                // Find the smallest number that has enough frequency to satisfy this group
                while (smallestAvailableIdx <= MAX_VAL) {
                    if (counts[smallestAvailableIdx] >= requiredSize) {
                        foundValue = smallestAvailableIdx;
                        break;
                    }
                    smallestAvailableIdx++;
                }

                // If no number can satisfy this group, the configuration is impossible
                if (foundValue == -1) {
                    out.println("NO");
                    return false;
                }

                // Assign value and decrement available count
                for (int[] coord : group.coordinates) {
                    grid[coord[0]][coord[1]] = foundValue;
                }
                counts[foundValue] -= requiredSize;

                // Resetting the pointer is not necessary for the same size group, 
                // but we must ensure we don't skip numbers that might still have enough 
                // after subtraction. However, the greedy logic works because we use 
                // the smallest number available.
                smallestAvailableIdx = 1; 
            }
            return true;
        }

        private void printGrid(PrintWriter out) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    out.print(grid[i][j] + (j == n - 1 ? "" : " "));
                }
                out.println();
            }
        }
    }
}

