/**
 * A program to reconstruct a palindromic matrix from a given set of numbers.
 * A palindromic matrix is symmetric across both horizontal and vertical axes.
 */
public class PalindromicMatrix {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = reader.nextInt();
            int[] elements = new int[n * n];
            Map<Integer, Integer> frequencyMap = new HashMap<>();

            for (int i = 0; i < n * n; i++) {
                elements[i] = reader.nextInt();
                frequencyMap.put(elements[i], frequencyMap.getOrDefault(elements[i], 0) + 1);
            }

            PalindromicMatrix solver = new PalindromicMatrix(n, frequencyMap);
            solver.solve(elements, out);

        } catch (Exception e) {
            // In a competitive programming context, we usually don't catch generic exceptions,
            // but here we ensure the program exits gracefully.
        } finally {
            out.close();
        }
    }

    private final int n;
    private final Map<Integer, Integer> frequencyMap;

    public PalindromicMatrix(int n, Map<Integer, Integer> frequencyMap) {
        this.n = n;
        this.frequencyMap = frequencyMap;
    }

    /**
     * Orchestrates the construction of the palindromic matrix.
     */
    public void solve(int[] elements, PrintWriter out) {
        int[][] matrix = new int[n][n];
        PriorityQueue<FrequencyBucket> frequencyQueue = new PriorityQueue<>(Collections.reverseOrder());

        // Initialize priority queue with available number frequencies
        for (Map.Entry<Integer, Integer> entry : frequencyMap.entrySet()) {
            frequencyQueue.add(new FrequencyBucket(entry.getKey(), entry.getValue()));
        }

        List<List<Coordinate>> symmetryGroups = generateSymmetryGroups();

        // To maximize success, we must satisfy the largest symmetry groups first
        // The current generation logic naturally produces 4-cell groups, then 2-cell, then 1-cell.
        for (List<Coordinate> group : symmetryGroups) {
            int requiredCount = group.size();
            FrequencyBucket topBucket = frequencyQueue.poll();

            if (topBucket == null || topBucket.count < requiredCount) {
                out.println("NO");
                return;
            }

            // Fill the matrix with the most frequent available number
            for (Coordinate coord : group) {
                matrix[coord.row][coord.col] = topBucket.value;
            }

            // Update the frequency and push back if there are remaining counts
            topBucket.count -= requiredCount;
            if (topBucket.count > 0) {
                frequencyQueue.add(topBucket);
            }
        }

        // If we successfully filled all groups
        out.println("YES");
        printMatrix(matrix, out);
    }

    /**
     * Groups cell coordinates that must share the same value due to symmetry.
     */
    private List<List<Coordinate>> generateSymmetryGroups() {
        List<List<Coordinate>> groups = new ArrayList<>();

        // 1. Generate 4-cell symmetry groups (Quadrants)
        for (int i = 0; i < n / 2; i++) {
            for (int j = 0; j < n / 2; j++) {
                groups.add(Arrays.asList(
                        new Coordinate(i, j),
                        new Coordinate(i, n - 1 - j),
                        new Coordinate(n - 1 - i, j),
                        new Coordinate(n - 1 - i, n - 1 - j)
                ));
            }
        }

        // 2. Handle odd-sized matrices (Middle row, middle column, and center)
        if (n % 2 != 0) {
            int mid = n / 2;
            // 2-cell groups for middle row and middle column
            for (int i = 0; i < mid; i++) {
                // Horizontal middle line (excluding center)
                groups.add(Arrays.asList(new Coordinate(i, mid), new Coordinate(n - 1 - i, mid)));
                // Vertical middle line (excluding center)
                groups.add(Arrays.asList(new Coordinate(mid, i), new Coordinate(mid, n - 1 - i)));
            }
            // 1-cell group for the absolute center
            groups.add(Collections.singletonList(new Coordinate(mid, mid)));
        }

        return groups;
    }

    private void printMatrix(int[][] matrix, PrintWriter out) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                out.print(matrix[i][j] + (j == n - 1 ? "" : " "));
            }
            out.println();
        }
    }

    /**
     * Data class representing a cell in the matrix.
     */
    private static class Coordinate {
        final int row;
        final int col;

        Coordinate(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Data class to track how many of a specific value are available.
     */
    private static class FrequencyBucket implements Comparable<FrequencyBucket> {
        int value;
        int count;

        FrequencyBucket(int value, int count) {
            this.value = value;
            this.count = count;
        }

        @Override
        public int compareTo(FrequencyBucket other) {
            return Integer.compare(this.count, other.count);
        }
    }

    /**
     * High-performance input reader.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A solution to fill an n x n grid with given numbers such that the grid 
 * maintains axial and 4-way symmetry.
 */
public class Solution {

    private static final int MAX_VALUE = 1001;

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            String firstLine = reader.next();
            if (firstLine == null) return;

            int n = Integer.parseInt(firstLine);
            int[] counts = new int[MAX_VALUE];

            // Read n*n numbers and populate frequency map
            for (int i = 0; i < n * n; i++) {
                counts[reader.nextInt()]++;
            }

            if (n % 2 == 0) {
                solveEvenGrid(n, counts, out);
            } else {
                solveOddGrid(n, counts, out);
            }
        } catch (Exception e) {
            // Handle or log potential parsing errors
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Logic for even-sized grids.
     * All elements must appear in multiples of 4 to maintain 4-way symmetry.
     */
    private static void solveEvenGrid(int n, int[] counts, PrintWriter out) {
        for (int i = 0; i < MAX_VALUE; i++) {
            if (counts[i] % 4 != 0) {
                out.println("NO");
                return;
            }
        }

        int[][] grid = new int[n][n];
        int row = 0;
        int col = 0;

        for (int i = 0; i < MAX_VALUE; i++) {
            while (counts[i] > 0) {
                // Fill 4 symmetric positions
                grid[row][col] = i;
                grid[n - 1 - row][col] = i;
                grid[row][n - 1 - col] = i;
                grid[n - 1 - row][n - 1 - col] = i;

                counts[i] -= 4;
                col++;

                // Move to next row in the quadrant when column limit is reached
                if (col == n / 2) {
                    col = 0;
                    row++;
                }
            }
        }

        out.println("YES");
        printGrid(grid, out);
    }

    /**
     * Logic for odd-sized grids.
     * Requires exactly one element with an odd frequency (for the center).
     * Other elements must be even and satisfy axial/quad constraints.
     */
    private static void solveOddGrid(int n, int[] counts, PrintWriter out) {
        int oddFreqCount = 0;
        int centerValue = -1;

        for (int i = 0; i < MAX_VALUE; i++) {
            if (counts[i] % 2 != 0) {
                oddFreqCount++;
                centerValue = i;
            }
        }

        if (oddFreqCount != 1) {
            out.println("NO");
            return;
        }

        // Prepare counts by placing the center element
        counts[centerValue]--;

        // Elements with counts % 4 == 2 are 'forced' into axis-pair positions
        int forcedPairs = 0;
        for (int i = 0; i < MAX_VALUE; i++) {
            if (counts[i] % 4 == 2) {
                forcedPairs++;
            }
        }

        // There are (n-1) available slots for pairs on the middle axes
        if (forcedPairs > n - 1) {
            out.println("NO");
            return;
        }

        int[][] grid = new int[n][n];
        grid[n / 2][n / 2] = centerValue;

        // Collect all available pairs to be distributed
        List<Integer> availablePairs = new ArrayList<>();
        for (int i = 0; i < MAX_VALUE; i++) {
            while (counts[i] >= 2) {
                availablePairs.add(i);
                counts[i] -= 2;
            }
        }

        int pairIdx = 0;
        // 1. Fill middle row pairs
        for (int j = 0; j < n / 2; j++) {
            int val = availablePairs.get(pairIdx++);
            grid[n / 2][j] = val;
            grid[n / 2][n - 1 - j] = val;
        }
        // 2. Fill middle column pairs
        for (int i = 0; i < n / 2; i++) {
            int val = availablePairs.get(pairIdx++);
            grid[i][n / 2] = val;
            grid[n - 1 - i][n / 2] = val;
        }

        // 3. Fill the remaining quadrants using remaining pairs in groups of two (to make quads)
        int r = 0;
        int c = 0;
        for (int k = pairIdx; k < availablePairs.size(); k += 2) {
            int val = availablePairs.get(k);

            // Every quad requires two identical pairs
            if (k + 1 >= availablePairs.size() || availablePairs.get(k + 1) != val) {
                out.println("NO");
                return;
            }

            grid[r][c] = val;
            grid[r][n - 1 - c] = val;
            grid[n - 1 - r][c] = val;
            grid[n - 1 - r][n - 1 - c] = val;

            c++;
            if (c == n / 2) {
                c = 0;
                r++;
            }
        }

        out.println("YES");
        printGrid(grid, out);
    }

    private static void printGrid(int[][] grid, PrintWriter out) {
        StringBuilder sb = new StringBuilder();
        for (int[] row : grid) {
            sb.setLength(0);
            for (int j = 0; j < row.length; j++) {
                sb.append(row[j]);
                if (j < row.length - 1) sb.append(" ");
            }
            out.println(sb.toString());
        }
    }

    /**
     * Efficient input reader for large datasets.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
