/**
 * Solution to arrange numbers in an n x n grid based on their frequency.
 * The arrangement follows a symmetrical pattern: 
 * 4-way symmetry for quadrants, 2-way symmetry for middle rows/columns, 
 * and 1-way for the center.
 */
public class Solution {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int n = reader.nextInt();
            Map<Integer, Integer> frequencyMap = new HashMap<>();
            for (int i = 0; i < n * n; i++) {
                int num = reader.nextInt();
                frequencyMap.put(num, frequencyMap.getOrDefault(num, 0) + 1);
            }

            GridSolver solver = new GridSolver(n, frequencyMap);
            int[][] result = solver.solve();

            if (result == null) {
                writer.println("NO");
            } else {
                writer.println("YES");
                printGrid(result, writer);
            }
        } catch (Exception e) {
            writer.println("NO");
        } finally {
            writer.flush();
            writer.close();
        }
    }

    private static void printGrid(int[][] grid, PrintWriter writer) {
        for (int[] row : grid) {
            for (int i = 0; i < row.length; i++) {
                writer.print(row[i] + (i == row.length - 1 ? "" : " "));
            }
            writer.println();
        }
    }

    /**
     * Manages the selection of numbers based on their remaining frequency.
     */
    static class FrequencyManager {
        private final PriorityQueue<FrequencyRecord> frequencyQueue;

        public FrequencyManager(Map<Integer, Integer> counts) {
            // Sort by frequency descending
            this.frequencyQueue = new PriorityQueue<>(
                Comparator.comparingInt((FrequencyRecord r) -> r.count).reversed()
            );
            for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
                frequencyQueue.add(new FrequencyRecord(entry.getKey(), entry.getValue()));
            }
        }

        /**
         * Attempts to consume a specific amount of a number's frequency.
         * @param amount Number of cells to fill.
         * @return The value used, or null if insufficient frequency is available.
         */
        public Integer consume(int amount) {
            if (frequencyQueue.isEmpty()) {
                return null;
            }
            FrequencyRecord record = frequencyQueue.poll();
            if (record.count < amount) {
                return null;
            }
            record.count -= amount;
            int value = record.value;
            if (record.count > 0) {
                frequencyQueue.add(record);
            }
            return value;
        }
    }

    /**
     * Represents a number and its remaining count.
     */
    static class FrequencyRecord {
        int value;
        int count;

        FrequencyRecord(int value, int count) {
            this.value = value;
            this.count = count;
        }
    }

    /**
     * Encapsulates the geometric logic of the grid arrangement.
     */
    static class GridSolver {
        private final int n;
        private final FrequencyManager frequencyManager;

        public GridSolver(int n, Map<Integer, Integer> frequencyMap) {
            this.n = n;
            this.frequencyManager = new FrequencyManager(frequencyMap);
        }

        public int[][] solve() {
            int[][] grid = new int[n][n];

            // 1. Handle Quadrants (4-way symmetry)
            for (int j = 0; j < n / 2; j++) {
                for (int k = 0; k < n / 2; k++) {
                    Integer val = frequencyManager.consume(4);
                    if (val == null) return null;
                    grid[j][k] = val;
                    grid[n - 1 - j][k] = val;
                    grid[n - 1 - j][n - 1 - k] = val;
                    grid[j][n - 1 - k] = val;
                }
            }

            // 2. Handle Even cases (all quadrants filled)
            if (n % 2 == 0) {
                return grid;
            }

            // 3. Handle Odd cases: Middle Row edges (2-way symmetry)
            for (int i = 0; i < n / 2; i++) {
                Integer val = frequencyManager.consume(2);
                if (val == null) return null;
                grid[n / 2][i] = val;
                grid[n / 2][n - 1 - i] = val;
            }

            // 4. Handle Odd cases: Middle Column edges (2-way symmetry)
            for (int i = 0; i < n / 2; i++) {
                Integer val = frequencyManager.consume(2);
                if (val == null) return null;
                grid[i][n / 2] = val;
                grid[n - 1 - i][n / 2] = val;
            }

            // 5. Handle Odd cases: Center (1-way symmetry)
            Integer centerVal = frequencyManager.consume(1);
            if (centerVal == null) return null;
            grid[n / 2][n / 2] = centerVal;

            return grid;
        }
    }

    /**
     * Efficient input reader.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

