    /**
     * Tracks the count of a specific number to be placed in the matrix.
     */
    static class Frequency implements Comparable<Frequency> {
        int count;
        final int value;

        Frequency(int count, int value) {
            this.count = count;
            this.value = value;
        }

        @Override
        public int compareTo(Frequency other) {
            // Max-heap: highest frequency first
            return Integer.compare(other.count, this.count);
        }
    }

    static class PalindromicMatrixSolver {
        private final int size;
        private final FastReader reader;
        private final int[][] matrix;
        private final PriorityQueue<Frequency> frequencyQueue;

        public PalindromicMatrixSolver(int size, FastReader reader) {
            this.size = size;
            this.reader = reader;
            this.matrix = new int[size][size];
            this.frequencyQueue = new PriorityQueue<>();
        }

        public void solve(PrintWriter out) {
            Map<Integer, Integer> counts = new HashMap<>();

            // Step 1: Read input and count frequencies
            for (int i = 0; i < size * size; i++) {
                int val = reader.nextInt();
                counts.put(val, counts.getOrDefault(val, 0) + 1);
            }

            // Step 2: Prepare priority queue for greedy placement
            for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
                frequencyQueue.add(new Frequency(entry.getValue(), entry.getKey()));
            }

            // Step 3: Generate symmetry groups and attempt to fill the matrix
            List<List<Point>> symmetryGroups = generateSymmetryGroups();
            boolean possible = true;

            for (List<Point> group : symmetryGroups) {
                if (!fillGroup(group)) {
                    possible = false;
                    break;
                }
            }

            // Step 4: Output results
            if (possible) {
                out.println("YES");
                printMatrix(out);
            } else {
                out.println("NO");
            }
        }

        /**
         * Determines the groups of cells that must share the same value to maintain symmetry.
         */
        private List<List<Point>> generateSymmetryGroups() {
            List<List<Point>> groups = new ArrayList<>();

            // Corners and quadrants (groups of 4)
            for (int i = 0; i < size / 2; i++) {
                for (int j = 0; j < size / 2; j++) {
                    groups.add(Arrays.asList(
                            new Point(i, j),
                            new Point(i, getMirrorIndex(j)),
                            new Point(getMirrorIndex(i), j),
                            new Point(getMirrorIndex(i), getMirrorIndex(j))
                    ));
                }
            }

            // Middle row/column for odd-sized matrices (groups of 2 or 1)
            if (size % 2 != 0) {
                int mid = size / 2;
                for (int i = 0; i < mid; i++) {
                    // Vertical symmetry on middle column
                    groups.add(Arrays.asList(new Point(i, mid), new Point(getMirrorIndex(i), mid)));
                    // Horizontal symmetry on middle row
                    groups.add(Arrays.asList(new Point(mid, i), new Point(mid, getMirrorIndex(i))));
                }
                // The absolute center cell
                groups.add(Collections.singletonList(new Point(mid, mid)));
            }

            return groups;
        }

        /**
         * Greedily fills a symmetry group with the most frequent available number.
         */
        private boolean fillGroup(List<Point> group) {
            Frequency top = frequencyQueue.poll();
            if (top == null || top.count < group.size()) {
                return false;
            }

            for (Point p : group) {
                matrix[p.r][p.c] = top.value;
            }

            top.count -= group.size();
            if (top.count > 0) {
                frequencyQueue.add(top);
            }
            return true;
        }

        private int getMirrorIndex(int index) {
            return size - 1 - index;
        }

        private void printMatrix(PrintWriter out) {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < size; i++) {
                for (int j = 0; j < size; j++) {
                    sb.append(matrix[i][j]).append(j == size - 1 ? "" : " ");
                }
                sb.append("\n");
            }
            out.print(sb.toString());
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A program that arranges a given set of integers into an N x N grid 
 * based on symmetric requirements: 
 * - Most elements are placed in groups of 4 (corners of symmetric rectangles).
 * - If N is odd, elements are placed in groups of 2 (middle row/column) and 1 (center).
 */
public class SymmetricGridBuilder {

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        int n = sc.nextInt();

        if (n <= 0) return;

        // Read all input values and count their frequencies
        int totalElements = n * n;
        TreeMap<Integer, Integer> frequencies = new TreeMap<>();
        for (int i = 0; i < totalElements; i++) {
            int val = sc.nextInt();
            frequencies.put(val, frequencies.getOrDefault(val, 0) + 1);
        }

        SymmetryResult result = constructSymmetricGrid(n, frequencies);

        // Output result
        if (result.isPossible()) {
            System.out.println("YES");
            System.out.print(result.getGridAsString());
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Core logic to construct the grid based on available symmetric groups.
     */
    private static SymmetryResult constructSymmetricGrid(int n, TreeMap<Integer, Integer> frequencies) {
        int[][] grid = new int[n][n];

        // Pre-process frequencies into available groups
        // available4s contains values that can form a group of 4 symmetric cells
        Deque<Integer> available4s = new ArrayDeque<>();
        // available2s contains values that can form a group of 2 symmetric cells
        Deque<Integer> available2s = new ArrayDeque<>();
        // available1s contains values that can form a single center cell
        Deque<Integer> available1s = new ArrayDeque<>();

        for (Map.Entry<Integer, Integer> entry : frequencies.entrySet()) {
            int val = entry.getKey();
            int freq = entry.getValue();

            while (freq >= 4) {
                available4s.add(val);
                freq -= 4;
            }
            while (freq >= 2) {
                available2s.add(val);
                freq -= 2;
            }
            while (freq >= 1) {
                available1s.add(val);
                freq -= 1;
            }
        }

        // 1. Fill 4-way symmetric quadrants
        for (int i = 0; i < n / 2; i++) {
            for (int j = 0; j < n / 2; j++) {
                if (available4s.isEmpty()) return SymmetryResult.failure();
                int val = available4s.pollFirst();
                int mirrorI = n - 1 - i;
                int mirrorJ = n - 1 - j;
                grid[i][j] = val;
                grid[i][mirrorJ] = val;
                grid[mirrorI][j] = val;
                grid[mirrorI][mirrorJ] = val;
            }
        }

        // 2. If N is odd, handle the middle row, middle column, and center
        if (n % 2 != 0) {
            int mid = n / 2;

            // Middle row (excluding center)
            for (int j = 0; j < mid; j++) {
                if (available2s.isEmpty()) return SymmetryResult.failure();
                int val = available2s.pollFirst();
                grid[mid][j] = val;
                grid[mid][n - 1 - j] = val;
            }

            // Middle column (excluding center)
            for (int i = 0; i < mid; i++) {
                if (available2s.isEmpty()) return SymmetryResult.failure();
                int val = available2s.pollFirst();
                grid[i][mid] = val;
                grid[n - 1 - i][mid] = val;
            }

            // Center element
            if (available1s.isEmpty()) return SymmetryResult.failure();
            grid[mid][mid] = available1s.pollFirst();
        }

        return SymmetryResult.success(grid);
    }

    /**
     * Wrapper class to return the construction result.
     */
    static class SymmetryResult {
        private final int[][] grid;
        private final boolean possible;

        private SymmetryResult(int[][] grid, boolean possible) {
            this.grid = grid;
            this.possible = possible;
        }

        public static SymmetryResult success(int[][] grid) {
            return new SymmetryResult(grid, true);
        }

        public static SymmetryResult failure() {
            return new SymmetryResult(null, false);
        }

        public boolean isPossible() {
            return possible;
        }

        public String getGridAsString() {
            if (grid == null) return "";
            StringBuilder sb = new StringBuilder();
            for (int[] row : grid) {
                for (int val : row) {
                    sb.append(val).append(" ");
                }
                sb.append("\n");
            }
            return sb.toString();
        }
    }

    /**
     * Fast I/O utility for reading input.
     */
    static class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver for the matrix symmetry problem.
 * The goal is to arrange n^2 numbers into an n x n matrix such that 
 * the matrix is symmetric across both the horizontal and vertical axes.
 */
public class MatrixSymmetrySolver {

    public static void main(String[] args) {
        new MatrixSymmetrySolver().run();
    }

    private void run() {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        int n = reader.nextInt();
        Map<Integer, Integer> frequencyMap = new HashMap<>();
        for (int i = 0; i < n * n; i++) {
            int val = reader.nextInt();
            frequencyMap.put(val, frequencyMap.getOrDefault(val, 0) + 1);
        }

        int[][] matrix = new int[n][n];
        boolean success = false;

        if (n % 2 == 0) {
            success = fillEvenMatrix(n, frequencyMap, matrix);
        } else {
            success = fillOddMatrix(n, frequencyMap, matrix);
        }

        if (success) {
            writer.println("YES");
            printMatrix(writer, matrix);
        } else {
            writer.println("NO");
        }
        writer.flush();
        writer.close();
    }

    /**
     * Fills an even-sized matrix. Every element must appear in multiples of 4.
     */
    private boolean fillEvenMatrix(int n, Map<Integer, Integer> counts, int[][] matrix) {
        for (int count : counts.values()) {
            if (count % 4 != 0) return false;
        }

        List<Integer> quadPool = new ArrayList<>();
        for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
            int numQuads = entry.getValue() / 4;
            for (int i = 0; i < numQuads; i++) {
                quadPool.add(entry.getKey());
            }
        }

        int half = n / 2;
        int quadIdx = 0;
        for (int i = 0; i < half; i++) {
            for (int j = 0; j < half; j++) {
                if (quadIdx >= quadPool.size()) return false;
                int val = quadPool.get(quadIdx++);
                matrix[i][j] = matrix[i][n - 1 - j] = matrix[n - 1 - i][j] = matrix[n - 1 - i][n - 1 - j] = val;
            }
        }
        return true;
    }

    /**
     * Fills an odd-sized matrix.
     * 1 center element, (n-1) elements used in pairs for axes, 
     * and the rest used in groups of 4 for quadrants.
     */
    private boolean fillOddMatrix(int n, Map<Integer, Integer> counts, int[][] matrix) {
        // 1. Identify and place the center element (must have an odd frequency)
        int centerVal = -1;
        for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
            if (entry.getValue() % 2 != 0) {
                centerVal = entry.getKey();
                break;
            }
        }

        if (centerVal == -1) return false;
        matrix[n / 2][n / 2] = centerVal;
        counts.put(centerVal, counts.get(centerVal) - 1);

        // 2. Pre-calculate pools of quads and pairs for O(N^2) construction
        List<Integer> quadPool = new ArrayList<>();
        List<Integer> pairPool = new ArrayList<>();

        for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
            int val = entry.getValue();
            int numQuads = val / 4;
            int numPairs = (val % 4) / 2;

            for (int i = 0; i < numQuads; i++) quadPool.add(entry.getKey());
            for (int i = 0; i < numPairs; i++) pairPool.add(entry.getKey());
        }

        // 3. Fill Quadrants (the most restrictive part)
        int requiredQuads = (n / 2) * (n / 2);
        if (quadPool.size() < requiredQuads) return false;

        int half = n / 2;
        int quadIdx = 0;
        for (int i = 0; i < half; i++) {
            for (int j = 0; j < half; j++) {
                int val = quadPool.get(quadIdx++);
                matrix[i][j] = matrix[i][n - 1 - j] = matrix[n - 1 - i][j] = matrix[n - 1 - i][n - 1 - j] = val;
            }
        }

        // 4. Remaining quads can be used as two pairs each
        for (int i = quadIdx; i < quadPool.size(); i++) {
            pairPool.add(quadPool.get(i));
            pairPool.add(quadPool.get(i));
        }

        // 5. Fill Axes (middle row and column)
        int requiredPairs = n - 1; // (n-1)/2 for row + (n-1)/2 for col
        if (pairPool.size() < requiredPairs) return false;

        int pairIdx = 0;
        // Middle row
        for (int j = 0; j < half; j++) {
            int val = pairPool.get(pairIdx++);
            matrix[n / 2][j] = matrix[n / 2][n - 1 - j] = val;
        }
        // Middle column
        for (int i = 0; i < half; i++) {
            int val = pairPool.get(pairIdx++);
            matrix[i][n / 2] = matrix[n - 1 - i][n / 2] = val;
        }

        return true;
    }

    private void printMatrix(PrintWriter writer, int[][] matrix) {
        for (int[] row : matrix) {
            for (int j = 0; j < row.length; j++) {
                writer.print(row[j] + (j == row.length - 1 ? "" : " "));
            }
            writer.println();
        }
    }

    /**
     * Utility class for fast I/O.
     */
    static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver that attempts to arrange N^2 integers into an N x N grid 
 * with rotational and reflectional symmetry.
 */
public class SymmetryGridSolver {

    public static void main(String[] args) {
        try {
            // The solver attempts to use input.txt and output.txt, 
            // falling back to System.in/out if files are not found.
            new SymmetryGridSolver().run();
        } catch (IOException e) {
            System.err.println("An I/O error occurred: " + e.getMessage());
        }
    }

    /**
     * Orchestrates the reading, solving, and writing process.
     */
    public void run() throws IOException {
        FastReader reader = new FastReader("input.txt");
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        // Attempt to switch to file output if input.txt was used
        File inputFile = new File("input.txt");
        if (inputFile.exists()) {
            out.close(); // Close stdout wrapper
            out = new PrintWriter(new BufferedWriter(new FileWriter("output.txt")));
        }

        try {
            GridResult result = solve(reader);
            if (result.isSuccess()) {
                out.println("Yes");
                printGrid(out, result.getGrid());
            } else {
                out.println("NO");
            }
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Core logic to solve the symmetry problem.
     */
    private GridResult solve(FastReader reader) throws IOException {
        int n = reader.nextInt();
        if (n <= 0) return GridResult.fail();

        Map<Integer, Integer> frequencyMap = new HashMap<>();
        int totalElements = n * n;
        for (int i = 0; i < totalElements; i++) {
            int val = reader.nextInt();
            frequencyMap.put(val, frequencyMap.getOrDefault(val, 0) + 1);
        }

        // Calculate how many groups of 4, 2, and 1 we need to satisfy symmetry
        int needed4 = (n / 2) * (n / 2);
        int needed2 = (n % 2 != 0) ? 2 * (n / 2) : 0;
        int needed1 = (n % 2 != 0) ? 1 : 0;

        Deque<Integer> pool4 = new ArrayDeque<>();
        Deque<Integer> pool2 = new ArrayDeque<>();
        Deque<Integer> pool1 = new ArrayDeque<>();

        // Distribute available numbers into requirement pools
        for (Map.Entry<Integer, Integer> entry : frequencyMap.entrySet()) {
            int val = entry.getKey();
            int count = entry.getValue();

            while (count >= 4 && pool4.size() < needed4) {
                pool4.add(val);
                count -= 4;
            }
            while (count >= 2 && pool2.size() < needed2) {
                pool2.add(val);
                count -= 2;
            }
            while (count >= 1 && pool1.size() < needed1) {
                pool1.add(val);
                count -= 1;
            }
        }

        // Validation: Check if we successfully gathered enough numbers
        if (pool4.size() < needed4 || pool2.size() < needed2 || pool1.size() < needed1) {
            return GridResult.fail();
        }

        int[][] grid = new int[n][n];

        // 1. Fill 4-way symmetric quadrants
        for (int i = 0; i < n / 2; i++) {
            for (int j = 0; j < n / 2; j++) {
                int val = pool4.poll();
                grid[i][j] = val;
                grid[n - i - 1][j] = val;
                grid[i][n - j - 1] = val;
                grid[n - i - 1][n - j - 1] = val;
            }
        }

        // 2. Fill 2-way symmetric middle row/column if N is odd
        if (n % 2 != 0) {
            int mid = n / 2;
            // Vertical pairs in middle column
            for (int i = 0; i < mid; i++) {
                int val = pool2.poll();
                grid[i][mid] = val;
                grid[n - i - 1][mid] = val;
            }
            // Horizontal pairs in middle row
            for (int i = 0; i < mid; i++) {
                int val = pool2.poll();
                grid[mid][i] = val;
                grid[mid][n - i - 1] = val;
            }
            // 3. Fill the single center element
            grid[mid][mid] = pool1.poll();
        }

        return GridResult.success(grid);
    }

    private void printGrid(PrintWriter out, int[][] grid) {
        for (int[] row : grid) {
            for (int i = 0; i < row.length; i++) {
                out.print(row[i] + (i == row.length - 1 ? "" : " "));
            }
            out.println();
        }
    }

    /**
     * Wrapper for the result of the solve operation.
     */
    private static class GridResult {
        private final boolean success;
        private final int[][] grid;

        private GridResult(boolean success, int[][] grid) {
            this.success = success;
            this.grid = grid;
        }

        public static GridResult success(int[][] grid) {
            return new GridResult(true, grid);
        }

        public static GridResult fail() {
            return new GridResult(false, null);
        }

        public boolean isSuccess() {
            return success;
        }

        public int[][] getGrid() {
            return grid;
        }
    }

    /**
     * High-performance input reader.
     */
    private static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(String fileName) throws IOException {
            File file = new File(fileName);
            if (file.exists()) {
                reader = new BufferedReader(new FileReader(file));
            } else {
                reader = new BufferedReader(new InputStreamReader(System.in));
            }
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver for constructing a symmetric matrix based on provided element frequencies.
 * The matrix must satisfy specific symmetry properties:
 * - Even n: All elements must form 4-way symmetric quadrants.
 * - Odd n: One single element at center, n-1 pairs forming a cross, and the rest forming quadrants.
 */
public class SymmetryMatrixSolver {

    public static void main(String[] args) {
        InputReader reader = new InputReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int n = reader.nextInt();
            int[] elements = reader.readArray(n * n);

            SymmetryMatrixSolver solver = new SymmetryMatrixSolver();
            SolutionResult result = solver.solve(n, elements);

            if (result.isSuccess()) {
                writer.println("YES");
                writer.printMatrix(result.getMatrix());
            } else {
                writer.println("NO");
            }
        } catch (Exception e) {
            // In a real-world production environment, use a logger.
            // For competitive programming/utilities, standard error is acceptable.
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    private final Deque<Integer> singles = new ArrayDeque<>();
    private final Deque<Integer> pairs = new ArrayDeque<>();
    private final Deque<Integer> quads = new ArrayDeque<>();

    /**
     * Executes the core logic to solve the matrix symmetry problem.
     * 
     * @param n The dimension of the n x n matrix.
     * @param elements The flat array of n*n elements provided.
     * @return A SolutionResult containing success status and the resulting matrix.
     */
    public SolutionResult solve(int n, int[] elements) {
        Map<Integer, Integer> frequencyMap = countFrequencies(elements);
        groupElementsBySymmetry(frequencyMap);

        int[][] matrix = new int[n][n];

        if (n % 2 == 0) {
            return solveEvenCase(n, matrix);
        } else {
            return solveOddCase(n, matrix);
        }
    }

    private Map<Integer, Integer> countFrequencies(int[] elements) {
        Map<Integer, Integer> counts = new HashMap<>();
        for (int val : elements) {
            counts.put(val, counts.getOrDefault(val, 0) + 1);
        }
        return counts;
    }

    private void groupElementsBySymmetry(Map<Integer, Integer> frequencyMap) {
        singles.clear();
        pairs.clear();
        quads.clear();

        for (Map.Entry<Integer, Integer> entry : frequencyMap.entrySet()) {
            int val = entry.getKey();
            int count = entry.getValue();

            int quadCount = count / 4;
            int remainingAfterQuads = count % 4;
            int pairCount = remainingAfterQuads / 2;
            int singleCount = remainingAfterQuads % 2;

            for (int i = 0; i < quadCount; i++) quads.offer(val);
            for (int i = 0; i < pairCount; i++) pairs.offer(val);
            for (int i = 0; i < singleCount; i++) singles.offer(val);
        }
    }

    private SolutionResult solveEvenCase(int n, int[][] matrix) {
        // In even n, we cannot have any singles or pairs leftover.
        if (!singles.isEmpty() || !pairs.isEmpty()) {
            return SolutionResult.failure();
        }

        // Total quads needed is (n*n)/4
        if (quads.size() != (n * n) / 4) {
            return SolutionResult.failure();
        }

        for (int i = 0; i < n / 2; i++) {
            for (int j = 0; j < n / 2; j++) {
                fillQuadrant(matrix, i, j, quads.poll(), n);
            }
        }

        return SolutionResult.success(matrix);
    }

    private SolutionResult solveOddCase(int n, int[][] matrix) {
        // For odd n, we must have exactly one single element for the center.
        if (singles.size() != 1) {
            return SolutionResult.failure();
        }

        matrix[n / 2][n / 2] = singles.poll();

        // We need n-1 pairs to fill the middle row and column (the cross).
        int requiredPairs = n - 1;

        // If we don't have enough pairs, we must split quads into two pairs.
        while (pairs.size() < requiredPairs) {
            if (quads.isEmpty()) return SolutionResult.failure();
            int quadVal = quads.poll();
            pairs.offer(quadVal);
            pairs.offer(quadVal);
        }

        // If we have more pairs than needed, those extra pairs cannot be used 
        // as they are not quads.
        if (pairs.size() > requiredPairs) {
            return SolutionResult.failure();
        }

        // Fill middle column cross
        for (int i = 0; i < n / 2; i++) {
            int val = pairs.poll();
            matrix[i][n / 2] = matrix[n - i - 1][n / 2] = val;
        }

        // Fill middle row cross
        for (int i = 0; i < n / 2; i++) {
            int val = pairs.poll();
            matrix[n / 2][i] = matrix[n / 2][n - i - 1] = val;
        }

        // Fill the four quadrants
        for (int i = 0; i < n / 2; i++) {
            for (int j = 0; j < n / 2; j++) {
                if (quads.isEmpty()) return SolutionResult.failure();
                fillQuadrant(matrix, i, j, quads.poll(), n);
            }
        }

        return SolutionResult.success(matrix);
    }

    private void fillQuadrant(int[][] matrix, int r, int c, int val, int n) {
        matrix[r][c] = val;
        matrix[n - r - 1][c] = val;
        matrix[r][n - c - 1] = val;
        matrix[n - r - 1][n - c - 1] = val;
    }

    /**
     * Data class to encapsulate the result of the matrix construction.
     */
    private static class SolutionResult {
        private final boolean success;
        private final int[][] matrix;

        private SolutionResult(boolean success, int[][] matrix) {
            this.success = success;
            this.matrix = matrix;
        }

        public static SolutionResult success(int[][] matrix) {
            return new SolutionResult(true, matrix);
        }

        public static SolutionResult failure() {
            return new SolutionResult(false, null);
        }

        public boolean isSuccess() { return success; }
        public int[][] getMatrix() { return matrix; }
    }

    /**
     * High-performance input reader.
     */
    private static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public int[] readArray(int size) {
            int[] arr = new int[size];
            for (int i = 0; i < size; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }
    }

    /**
     * Helper class to encapsulate output logic.
     */
    private static class PrintWriter {
        private final BufferedWriter writer;

        public PrintWriter(OutputStream out) {
            this.writer = new BufferedWriter(new OutputStreamWriter(out));
        }

        public void println(String s) throws IOException {
            writer.write(s + "\n");
        }

        public void printMatrix(int[][] matrix) throws IOException {
            for (int[] row : matrix) {
                for (int i = 0; i < row.length; i++) {
                    writer.write(row[i] + (i == row.length - 1 ? "" : " "));
                }
                writer.write("\n");
            }
        }

        public void close() {
            try {
                writer.flush();
                writer.close();
            } catch (IOException ignored) {}
        }
    }
}

import java.util.*;

/**
 * SymmetricGridGenerator solves the problem of arranging a set of numbers 
 * into an N x N grid such that the grid is symmetric across both the 
 * horizontal and vertical center axes.
 */
public class SymmetricGridGenerator {

    private final int gridSize;
    private final Map<Integer, Integer> frequencyMap;
    private final int[][] grid;

    public SymmetricGridGenerator(int gridSize, Map<Integer, Integer> frequencyMap) {
        this.gridSize = gridSize;
        this.frequencyMap = frequencyMap;
        this.grid = new int[gridSize][gridSize];
    }

    /**
     * Represents the requirements for a symmetric grid.
     */
    private static class SymmetryRequirements {
        final int targetQuads;
        final int targetPairs;
        final int targetSingles;

        SymmetryRequirements(int n) {
            this.targetQuads = (n / 2) * (n / 2);
            this.targetPairs = (n % 2 == 0) ? 0 : (n - 1);
            this.targetSingles = (n % 2 == 0) ? 0 : 1;
        }
    }

    public void solve() {
        SymmetryRequirements reqs = new SymmetryRequirements(gridSize);

        // Organize input numbers into available groups
        List<Integer> availableQuads = new ArrayList<>();
        List<Integer> availablePairs = new ArrayList<>();
        List<Integer> availableSingles = new ArrayList<>();

        for (Map.Entry<Integer, Integer> entry : frequencyMap.entrySet()) {
            int val = entry.getKey();
            int count = entry.getValue();

            while (count >= 4) {
                availableQuads.add(val);
                count -= 4;
            }
            while (count >= 2) {
                availablePairs.add(val);
                count -= 2;
            }
            while (count >= 1) {
                availableSingles.add(val);
                count -= 1;
            }
        }

        // Validation: Can we satisfy the symmetry requirements?
        if (!canSatisfyRequirements(reqs, availableQuads, availablePairs, availableSingles)) {
            System.out.println("NO");
            return;
        }

        // Construction: Fill the grid using the required slots
        System.out.println("YES");
        constructGrid(reqs, availableQuads, availablePairs, availableSingles);
        printGrid();
    }

    private boolean canSatisfyRequirements(SymmetryRequirements reqs, 
                                          List<Integer> quads, 
                                          List<Integer> pairs, 
                                          List<Integer> singles) {

        if (quads.size() < reqs.targetQuads) return false;

        // Excess quads can be used as pairs (1 quad = 2 pairs)
        int extraQuads = quads.size() - reqs.targetQuads;
        int totalPairsAvailable = pairs.size() + (extraQuads * 2);

        if (totalPairsAvailable < reqs.targetPairs) return false;

        // Excess pairs can be used as singles (1 pair = 2 singles)
        int extraPairs = totalPairsAvailable - reqs.targetPairs;
        int totalSinglesAvailable = singles.size() + (extraPairs * 2);

        return totalSinglesAvailable >= reqs.targetSingles;
    }

    private void constructGrid(SymmetryRequirements reqs, 
                               List<Integer> quads, 
                               List<Integer> pairs, 
                               List<Integer> singles) {

        int quadIdx = 0;
        int pairIdx = 0;
        int singleIdx = 0;

        // 1. Fill Quadrant Slots (4-way symmetry)
        for (int i = 0; i < reqs.targetQuads; i++) {
            int val = quads.get(quadIdx++);
            int r = i / (gridSize / 2);
            int c = i % (gridSize / 2);
            grid[r][c] = val;
            grid[gridSize - 1 - r][c] = val;
            grid[r][gridSize - 1 - c] = val;
            grid[gridSize - 1 - r][gridSize - 1 - c] = val;
        }

        // 2. Fill Axis Slots (2-way symmetry)
        if (gridSize % 2 != 0) {
            int mid = (gridSize - 1) / 2;

            // Flatten all available pair-capable units (existing pairs + broken quads)
            List<Integer> effectivePairs = new ArrayList<>(pairs);
            for (int i = quadIdx; i < quads.size(); i++) {
                effectivePairs.add(quads.get(i));
                effectivePairs.add(quads.get(i));
            }

            // Fill middle row pairs
            for (int c = 0; c < mid; c++) {
                int val = effectivePairs.get(pairIdx++);
                grid[mid][c] = val;
                grid[mid][gridSize - 1 - c] = val;
            }

            // Fill middle column pairs
            for (int r = 0; r < mid; r++) {
                int val = effectivePairs.get(pairIdx++);
                grid[r][mid] = val;
                grid[gridSize - 1 - r][mid] = val;
            }

            // 3. Fill Center Slot (1-way symmetry)
            if (singleIdx < singles.size()) {
                grid[mid][mid] = singles.get(singleIdx++);
            } else if (pairIdx < effectivePairs.size()) {
                grid[mid][mid] = effectivePairs.get(pairIdx++);
            } else {
                grid[mid][mid] = quads.get(quadIdx++); 
            }
        }
    }

    private void printGrid() {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < gridSize; i++) {
            for (int j = 0; j < gridSize; j++) {
                sb.append(grid[i][j]).append(" ");
            }
            sb.append("\n");
        }
        System.out.print(sb.toString());
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextInt()) return;

        int n = sc.nextInt();
        Map<Integer, Integer> counts = new HashMap<>();
        for (int i = 0; i < n * n; i++) {
            if (sc.hasNextInt()) {
                int val = sc.nextInt();
                counts.put(val, counts.getOrDefault(val, 0) + 1);
            }
        }

        SymmetricGridGenerator solver = new SymmetricGridGenerator(n, counts);
        solver.solve();
        sc.close();
    }
}

import java.util.*;
import java.io.*;

/**
 * A solver for generating a symmetric grid based on specific count requirements.
 * For even n: All numbers must appear in multiples of 4 to satisfy 4-way symmetry.
 * For odd n: One number acts as a center, others form a cross in pairs, and the rest form 4-way symmetry.
 */
public class SymmetryGridSolver {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) return;

        int n = scanner.nextInt();
        Map<Integer, Integer> frequencies = new TreeMap<>();
        for (int i = 0; i < n * n; i++) {
            int val = scanner.nextInt();
            frequencies.put(val, frequencies.getOrDefault(val, 0) + 1);
        }

        GridResult result = solve(n, frequencies);

        if (result.isSuccess()) {
            System.out.println("YES");
            printGrid(result.getGrid());
        } else {
            System.out.println("NO");
        }
    }

    private static GridResult solve(int n, Map<Integer, Integer> frequencies) {
        if (n % 2 == 0) {
            return solveEvenCase(n, frequencies);
        } else {
            return solveOddCase(n, frequencies);
        }
    }

    private static GridResult solveEvenCase(int n, Map<Integer, Integer> frequencies) {
        int[][] grid = new int[n][n];
        List<Integer> quadrupletElements = new ArrayList<>();

        for (Map.Entry<Integer, Integer> entry : frequencies.entrySet()) {
            int val = entry.getKey();
            int count = entry.getValue();

            if (count % 4 != 0) {
                return GridResult.failure();
            }

            for (int i = 0; i < count / 4; i++) {
                quadrupletElements.add(val);
            }
        }

        if (quadrupletElements.size() != (n / 2) * (n / 2)) {
            return GridResult.failure();
        }

        // Fill the four symmetric quadrants
        int index = 0;
        for (int i = 0; i < n / 2; i++) {
            for (int j = 0; j < n / 2; j++) {
                int val = quadrupletElements.get(index++);
                grid[i][j] = val;
                grid[n - 1 - i][j] = val;
                grid[i][n - 1 - j] = val;
                grid[n - 1 - i][n - 1 - j] = val;
            }
        }

        return GridResult.success(grid);
    }

    private static GridResult solveOddCase(int n, Map<Integer, Integer> frequencies) {
        int[][] grid = new int[n][n];
        int centerVal = -1;
        int oddCount = 0;

        // 1. Identify the center element (must have an odd frequency)
        for (Map.Entry<Integer, Integer> entry : frequencies.entrySet()) {
            if (entry.getValue() % 2 != 0) {
                centerVal = entry.getKey();
                oddCount++;
            }
        }

        if (oddCount != 1) {
            return GridResult.failure();
        }

        // Create a mutable copy of frequencies to work with
        Map<Integer, Integer> remainingFreqs = new TreeMap<>(frequencies);
        remainingFreqs.put(centerVal, remainingFreqs.get(centerVal) - 1);
        grid[n / 2][n / 2] = centerVal;

        // 2. Prepare requirements for cross (pairs) and quadrants (quadruplets)
        int neededQuadruplets = (n - 1) * (n - 1) / 4;
        int neededPairs = n - 1;

        List<Integer> l4 = new ArrayList<>();
        List<Integer> l2 = new ArrayList<>();

        // 3. Greedy allocation: extract quadruplets first, then pairs
        for (Map.Entry<Integer, Integer> entry : remainingFreqs.entrySet()) {
            int val = entry.getKey();
            int count = entry.getValue();
            int pairsAvailable = count / 2;

            // Extract quadruplets (sets of 2 pairs)
            int take4 = Math.min(pairsAvailable / 2, neededQuadruplets);
            for (int i = 0; i < take4; i++) l4.add(val);
            neededQuadruplets -= take4;
            pairsAvailable -= (take4 * 2);

            // Extract pairs (sets of 1 pair)
            int take2 = Math.min(pairsAvailable, neededPairs);
            for (int i = 0; i < take2; i++) l2.add(val);
            neededPairs -= take2;
            pairsAvailable -= take2;

            // If there are leftover pairs, this distribution is invalid
            if (pairsAvailable > 0) return GridResult.failure();
        }

        if (neededQuadruplets > 0 || neededPairs > 0) {
            return GridResult.failure();
        }

        // 4. Fill the grid
        // Fill Cross
        for (int i = 0; i < l2.size(); i++) {
            int val = l2.get(i);
            if (i < n / 2) {
                grid[i][n / 2] = val;
                grid[n - 1 - i][n / 2] = val;
            } else {
                grid[n / 2][i - n / 2] = val;
                grid[n / 2][n - 1 - i + n / 2] = val;
            }
        }

        // Fill Quadrants
        int idx = 0;
        for (int i = 0; i < n / 2; i++) {
            for (int j = 0; j < n / 2; j++) {
                int val = l4.get(idx++);
                grid[i][j] = val;
                grid[n - 1 - i][j] = val;
                grid[i][n - 1 - j] = val;
                grid[n - 1 - i][n - 1 - j] = val;
            }
        }

        return GridResult.success(grid);
    }

    private static void printGrid(int[][] grid) {
        StringBuilder sb = new StringBuilder();
        for (int[] row : grid) {
            for (int val : row) {
                sb.append(val).append(" ");
            }
            sb.append("\n");
        }
        System.out.print(sb.toString());
    }

    /**
     * Wrapper class to hold the result of the solver.
     */
    private static class GridResult {
        private final boolean success;
        private final int[][] grid;

        private GridResult(boolean success, int[][] grid) {
            this.success = success;
            this.grid = grid;
        }

        public static GridResult success(int[][] grid) {
            return new GridResult(true, grid);
        }

        public static GridResult failure() {
            return new GridResult(false, null);
        }

        public boolean isSuccess() {
            return success;
        }

        public int[][] getGrid() {
            return grid;
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A program to determine if a grid contains exactly one connected "plus" shape.
 * A plus shape is defined by a center '*' with four neighbors, and all '*' 
 * in the grid must belong to the continuous arms of this single plus.
 */
public class Exam {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            String nStr = reader.next();
            String mStr = reader.next();
            if (nStr == null || mStr == null) return;

            int rows = Integer.parseInt(nStr);
            int cols = Integer.parseInt(mStr);

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            if (isSinglePlusShape(grid, rows, cols)) {
                writer.println("YES");
            } else {
                writer.println("NO");
            }
        } catch (Exception e) {
            writer.println("NO");
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Validates if the grid contains exactly one plus shape and no other asterisks.
     */
    private static boolean isSinglePlusShape(char[][] grid, int rows, int cols) {
        List<int[]> centers = findPlusCenters(grid, rows, cols);

        // A valid shape must have exactly one center '*' that has 4 immediate '*' neighbors
        if (centers.size() != 1) {
            return false;
        }

        int[] center = centers.get(0);
        int centerRow = center[0];
        int centerCol = center[1];

        // Check if the total number of '*' in the grid matches the number of '*' 
        // connected to the center in a crosshair pattern.
        int totalAsterisks = countAllAsterisks(grid, rows, cols);
        int crosshairAsterisks = countConnectedCrosshairAsterisks(grid, rows, cols, centerRow, centerCol);

        return totalAsterisks == crosshairAsterisks;
    }

    /**
     * Finds all cells that act as a center of a 3x3 cross.
     */
    private static List<int[]> findPlusCenters(char[][] grid, int rows, int cols) {
        List<int[]> centers = new ArrayList<>();
        // A center must have neighbors on all sides, so it cannot be on the grid boundary.
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (isPlusCenter(grid, i, j)) {
                    centers.add(new int[]{i, j});
                }
            }
        }
        return centers;
    }

    private static boolean isPlusCenter(char[][] grid, int r, int c) {
        return grid[r][c] == '*' &&
               grid[r - 1][c] == '*' &&
               grid[r + 1][c] == '*' &&
               grid[r][c - 1] == '*' &&
               grid[r][c + 1] == '*';
    }

    private static int countAllAsterisks(char[][] grid, int rows, int cols) {
        int count = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*') {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Counts '*' connected to the center in the four cardinal directions.
     * This naturally handles gaps; if there is a '.' in an arm, the loop stops.
     */
    private static int countConnectedCrosshairAsterisks(char[][] grid, int rows, int cols, int r, int c) {
        int count = 1; // Start with the center itself

        // Traverse Up
        for (int i = r - 1; i >= 0 && grid[i][c] == '*'; i--) count++;
        // Traverse Down
        for (int i = r + 1; i < rows && grid[i][c] == '*'; i++) count++;
        // Traverse Left
        for (int j = c - 1; j >= 0 && grid[r][j] == '*'; j--) count++;
        // Traverse Right
        for (int j = c + 1; j < cols && grid[r][j] == '*'; j++) count++;

        return count;
    }

    /**
     * Efficient reader for large inputs.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A program to determine if all stars ('*') in a grid form a single cross shape.
 * A cross is defined as a set of cells forming a single continuous horizontal 
 * and vertical line intersecting at a single center point.
 */
public class GridCrossChecker {

    public static void main(String[] args) {
        try {
            Scanner sc = new Scanner(System.in);
            if (!sc.hasNextInt()) return;

            int rows = sc.nextInt();
            int cols = sc.nextInt();
            char[][] grid = new char[rows][cols];

            int minRow = rows, maxRow = -1;
            int minCol = cols, maxCol = -1;
            int starCount = 0;

            // Step 1: Read the grid and find the bounding box of all stars
            for (int i = 0; i < rows; i++) {
                String line = sc.next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                    if (grid[i][j] == '*') {
                        starCount++;
                        minRow = Math.min(minRow, i);
                        maxRow = Math.max(maxRow, i);
                        minCol = Math.min(minCol, j);
                        maxCol = Math.max(maxCol, j);
                    }
                }
            }

            System.out.println(isSingleCross(grid, rows, cols, starCount, minRow, maxRow, minCol, maxCol) ? "YES" : "NO");

        } catch (Exception e) {
            // In competitive programming, we usually handle errors silently or output NO
            System.out.println("NO");
        }
    }

    /**
     * Determines if the stars in the grid form exactly one cross.
     */
    private static boolean isSingleCross(char[][] grid, int rows, int cols, int starCount, 
                                         int minR, int maxR, int minC, int maxC) {
        // Case 1: No stars is technically a valid (empty) cross or trivial case
        if (starCount == 0) return true;

        // Case 2: Check if the star count matches the expected count for a cross spanning the bounding box.
        // A cross spanning [minR, maxR] and [minC, maxC] must have exactly:
        // (height of span) + (width of span) - 1 (the intersection) cells.
        int expectedCount = (maxR - minR + 1) + (maxC - minC + 1) - 1;
        if (starCount != expectedCount) {
            return false;
        }

        // Case 3: If the bounding box is a single point or a single line, it's a valid cross.
        if (minR == maxR || minC == maxC) {
            return true;
        }

        // Case 4: General cross. Find the potential center (r, c).
        // The center row 'r' is the unique row containing stars in different columns.
        // The center column 'c' is the unique column containing stars in different rows.
        int centerRow = -1;
        int centerCol = -1;

        // Find the center row
        for (int i = minR; i <= maxR; i++) {
            int rowMinCol = cols, rowMaxCol = -1;
            for (int j = minC; j <= maxC; j++) {
                if (grid[i][j] == '*') {
                    rowMinCol = Math.min(rowMinCol, j);
                    rowMaxCol = Math.max(rowMaxCol, j);
                }
            }
            if (rowMaxCol > rowMinCol) {
                if (centerRow != -1) return false; // More than one row has multiple columns
                centerRow = i;
            }
        }

        // Find the center column
        for (int j = minC; j <= maxC; j++) {
            int colMinRow = rows, colMaxRow = -1;
            for (int i = minR; i <= maxR; i++) {
                if (grid[i][j] == '*') {
                    colMinRow = Math.min(colMinRow, i);
                    colMaxRow = Math.max(colMaxRow, i);
                }
            }
            if (colMaxRow > colMinRow) {
                if (centerCol != -1) return false; // More than one column has multiple rows
                centerCol = j;
            }
        }

        // If we are in a 2D bounding box, we MUST have found a center row and column.
        if (centerRow == -1 || centerCol == -1) {
            return false;
        }

        // Final validation: The intersection must be a star, 
        // and every star must lie on either the center row or center column.
        if (grid[centerRow][centerCol] != '*') {
            return false;
        }

        for (int i = minR; i <= maxR; i++) {
            for (int j = minC; j <= maxC; j++) {
                if (grid[i][j] == '*') {
                    if (i != centerRow && j != centerCol) {
                        return false;
                    }
                }
            }
        }

        return true;
    }
}

import java.util.Scanner;

/**
 * This program determines if a grid contains exactly one "plus" shape
 * of stars (*) that accounts for all star characters present in the grid.
 */
public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Basic input validation for dimensions
        if (!scanner.hasNextInt()) {
            return;
        }
        int rows = scanner.nextInt();
        if (!scanner.hasNextInt()) {
            return;
        }
        int cols = scanner.nextInt();

        boolean[][] grid = readGrid(scanner, rows, cols);

        if (isSinglePlusPattern(grid, rows, cols)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Reads the grid from standard input.
     * 
     * @param scanner The Scanner instance to read from.
     * @param rows    The number of rows in the grid.
     * @param cols    The number of columns in the grid.
     * @return A 2D boolean array where true represents a star (*).
     */
    private static boolean[][] readGrid(Scanner scanner, int rows, int cols) {
        boolean[][] grid = new boolean[rows][cols];
        for (int i = 0; i < rows; i++) {
            String rowLine = scanner.next();
            for (int j = 0; j < cols; j++) {
                if (j < rowLine.length() && rowLine.charAt(j) == '*') {
                    grid[i][j] = true;
                }
            }
        }
        return grid;
    }

    /**
     * Determines if the grid consists of exactly one plus-shaped pattern.
     * 
     * @param grid The boolean grid.
     * @param rows Number of rows.
     * @param cols Number of columns.
     * @return true if exactly one plus shape covers all stars, false otherwise.
     */
    private static boolean isSinglePlusPattern(boolean[][] grid, int rows, int cols) {
        int centerRow = -1;
        int centerCol = -1;
        boolean foundCenter = false;

        // Step 1: Locate the center of a potential plus shape.
        // A valid center must have neighbors in all four cardinal directions.
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (isCenterOfPlus(grid, i, j)) {
                    centerRow = i;
                    centerCol = j;
                    foundCenter = true;
                    // Note: If multiple centers exist, the last one found is used,
                    // preserving the original logic's behavior.
                }
            }
        }

        // If no valid center was found, the requirement for a plus shape is not met.
        if (!foundCenter) {
            return false;
        }

        // Step 2: "Consume" the identified plus shape by clearing its cells.
        clearPlusShape(grid, centerRow, centerCol);

        // Step 3: Verify no star characters are left unaccounted for.
        return !hasRemainingStars(grid);
    }

    /**
     * Checks if the cell at (r, c) is the center of a plus shape.
     */
    private static boolean isCenterOfPlus(boolean[][] grid, int r, int c) {
        return grid[r][c] 
            && grid[r - 1][c] 
            && grid[r + 1][c] 
            && grid[r][c - 1] 
            && grid[r][c + 1];
    }

    /**
     * Clears the center and all continuous arms of the plus shape from the grid.
     */
    private static void clearPlusShape(boolean[][] grid, int r, int c) {
        int rows = grid.length;
        int cols = grid[0].length;

        // Direction vectors: Up, Down, Left, Right
        int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

        // Remove the center star
        grid[r][c] = false;

        // Remove the arms in each of the four directions
        for (int[] dir : directions) {
            int nextR = r + dir[0];
            int nextC = c + dir[1];

            // Continue clearing as long as we encounter stars
            while (nextR >= 0 && nextR < rows && nextC >= 0 && nextC < cols && grid[nextR][nextC]) {
                grid[nextR][nextC] = false;
                nextR += dir[0];
                nextC += dir[1];
            }
        }
    }

    /**
     * Scans the grid to see if any stars (*) remain.
     */
    private static boolean hasRemainingStars(boolean[][] grid) {
        for (boolean[] row : grid) {
            for (boolean isStar : row) {
                if (isStar) {
                    return true;
                }
            }
        }
        return false;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * ContestSolver identifies if a grid of '*' characters can be completely cleared
 * by finding a single "pivot" star that forms a cross with its neighbors.
 */
public class ContestSolver {

    public static void main(String[] args) {
        // Using try-with-resources to ensure the PrintWriter is flushed and closed automatically
        try (FastReader reader = new FastReader();
             PrintWriter writer = new PrintWriter(System.out)) {

            ContestSolver solver = new ContestSolver();
            solver.solve(reader, writer);

        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * Coordinates the input reading, processing, and output.
     * 
     * @param reader The utility to read input efficiently.
     * @param writer The utility to write output efficiently.
     * @throws IOException If an I/O error occurs.
     */
    public void solve(FastReader reader, PrintWriter writer) throws IOException {
        int height = reader.nextInt();
        int width = reader.nextInt();

        // A cross requires at least a 3x3 area to have a center with 4 neighbors.
        if (width < 3 || height < 3) {
            writer.println("NO");
            return;
        }

        char[][] grid = new char[height][width];
        for (int i = 0; i < height; i++) {
            String line = reader.next();
            if (line == null) break;
            grid[i] = line.toCharArray();
        }

        if (tryClearGrid(grid, height, width)) {
            writer.println("YES");
        } else {
            writer.println("NO");
        }
    }

    /**
     * Attempts to find a pivot star, clear its cross, and verify if the grid is empty.
     *
     * @param grid The 2D grid.
     * @param height Grid height.
     * @param width Grid width.
     * @return true if a cross was found and all '*' were cleared; false otherwise.
     */
    private boolean tryClearGrid(char[][] grid, int height, int width) {
        // Iterate through the inner grid to find a valid pivot point
        for (int i = 1; i < height - 1; i++) {
            for (int j = 1; j < width - 1; j++) {
                if (isPivot(grid, i, j)) {
                    clearCross(grid, i, j, height, width);
                    // After clearing the cross, the grid is valid only if no '*' remain
                    return !hasRemainingStars(grid, height, width);
                }
            }
        }
        return false;
    }

    /**
     * Checks if the cell at (r, c) is a '*' and has '*' neighbors in all four cardinal directions.
     */
    private boolean isPivot(char[][] grid, int r, int c) {
        return grid[r][c] == '*' &&
               grid[r - 1][c] == '*' &&
               grid[r + 1][c] == '*' &&
               grid[r][c - 1] == '*' &&
               grid[r][c + 1] == '*';
    }

    /**
     * Replaces the connected '*' characters in the row and column of the pivot with '-'.
     */
    private void clearCross(char[][] grid, int r, int c, int height, int width) {
        grid[r][c] = '-';

        // Clear left
        for (int j = c - 1; j >= 0 && grid[r][j] == '*'; j--) {
            grid[r][j] = '-';
        }
        // Clear right
        for (int j = c + 1; j < width && grid[r][j] == '*'; j++) {
            grid[r][j] = '-';
        }
        // Clear up
        for (int i = r - 1; i >= 0 && grid[i][c] == '*'; i--) {
            grid[i][c] = '-';
        }
        // Clear down
        for (int i = r + 1; i < height && grid[i][c] == '*'; i++) {
            grid[i][c] = '-';
        }
    }

    /**
     * Scans the grid to check if any '*' characters are left.
     */
    private boolean hasRemainingStars(char[][] grid, int height, int width) {
        for (int i = 0; i < height; i++) {
            for (int j = 0; j < width; j++) {
                if (grid[i][j] == '*') {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Efficient input reader using BufferedReader and StringTokenizer.
     */
    static class FastReader implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader() {
            this.reader = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            String next = next();
            return next != null ? Integer.parseInt(next) : 0;
        }

        @Override
        public void close() throws IOException {
            reader.close();
        }
    }
}

import java.util.Scanner;

/**
 * GridPatternSolver identifies if a single "cross" pattern clearing operation
 * can remove all '*' characters from a given grid.
 * 
 * A cross pattern consists of a center cell and its four immediate cardinal neighbors.
 * When a center is chosen, the entire continuous line of '*' in all four 
 * cardinal directions is cleared.
 */
public class GridPatternSolver {

    // Cardinal directions: Up, Left, Right, Down
    private static final int[][] DIRECTIONS = {
        {-1, 0}, 
        {0, -1}, 
        {0, 1}, 
        {1, 0}
    };

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }

        int height = scanner.nextInt();
        int width = scanner.nextInt();
        char[][] grid = new char[height][width];

        for (int i = 0; i < height; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        boolean isSuccessful = solve(grid, height, width);
        System.out.println(isSuccessful ? "YES" : "NO");

        scanner.close();
    }

    /**
     * Orchestrates the logic to determine if the grid can be cleared.
     * 
     * @param grid The 2D grid of characters.
     * @param height Height of the grid.
     * @param width Width of the grid.
     * @return true if exactly one cross pattern clears all '*' cells.
     */
    private static boolean solve(char[][] grid, int height, int width) {
        // Step 1: Attempt to find and clear the first valid cross pattern found
        boolean patternFound = findAndClearFirstCross(grid, height, width);

        // Step 2: If a pattern was found, check if any '*' remain in the grid
        return patternFound && !hasRemainingStars(grid, height, width);
    }

    /**
     * Iterates through the grid to find the first cell that can act as a cross center.
     * If found, it clears that pattern and returns true.
     */
    private static boolean findAndClearFirstCross(char[][] grid, int height, int width) {
        // A cross center cannot be on the boundary because it requires 4 neighbors
        for (int r = 1; r < height - 1; r++) {
            for (int c = 1; c < width - 1; c++) {
                if (isCrossCenter(grid, r, c, height, width)) {
                    clearCrossPattern(grid, r, c, height, width);
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Checks if the cell at (r, c) is a '*' and has '*' neighbors in all 4 directions.
     */
    private static boolean isCrossCenter(char[][] grid, int r, int c, int height, int width) {
        if (grid[r][c] != '*') {
            return false;
        }

        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            // Bounds check and neighbor validation
            if (nr < 0 || nr >= height || nc < 0 || nc >= width || grid[nr][nc] != '*') {
                return false;
            }
        }
        return true;
    }

    /**
     * Clears the center cell and extends the clearing process along the 4 cardinal directions
     * until a non-star cell or the grid boundary is encountered.
     */
    private static void clearCrossPattern(char[][] grid, int r, int c, int height, int width) {
        grid[r][c] = '-';

        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            // Traverse and clear the line of '*' in the current direction
            while (nr >= 0 && nr < height && nc >= 0 && nc < width && grid[nr][nc] == '*') {
                grid[nr][nc] = '-';
                nr += dir[0];
                nc += dir[1];
            }
        }
    }

    /**
     * Scans the entire grid to see if any '*' characters remain.
     */
    private static boolean hasRemainingStars(char[][] grid, int height, int width) {
        for (int r = 0; r < height; r++) {
            for (int c = 0; c < width; c++) {
                if (grid[r][c] == '*') {
                    return true;
                }
            }
        }
        return false;
    }
}

import java.util.Scanner;

/**
 * Application to determine if a given grid of characters forms a single, 
 * perfect plus shape consisting of all available asterisks.
 */
public class PlusShapeApp {

    private static final String RESULT_YES = "YES";
    private static final String RESULT_NO = "NO";

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            System.out.println(RESULT_NO);
            return;
        }

        int height = scanner.nextInt();
        int width = scanner.nextInt();
        scanner.nextLine(); // Consume newline

        Grid grid = new Grid(height, width, scanner);

        if (isPerfectPlus(grid)) {
            System.out.println(RESULT_YES);
        } else {
            System.out.println(RESULT_NO);
        }

        scanner.close();
    }

    /**
     * Logic to determine if the grid contains exactly one plus shape 
     * that accounts for all asterisks in the grid.
     * 
     * @param grid The grid containing the asterisks.
     * @return true if a perfect plus shape is found.
     */
    private static boolean isPerfectPlus(Grid grid) {
        int totalAsterisks = grid.getTotalAsterisks();

        // A plus shape requires at least a center and 4 neighbors (5 total)
        if (totalAsterisks < 5) {
            return false;
        }

        // Iterate through potential centers (excluding edges as a center must have neighbors)
        for (int r = 1; r < grid.getHeight() - 1; r++) {
            for (int c = 1; c < grid.getWidth() - 1; c++) {

                if (grid.isAsteriskAt(r, c) && isPotentialCenter(grid, r, c)) {
                    int plusSize = calculatePlusSize(grid, r, c);
                    // If the detected plus shape matches the total count, it's a perfect plus
                    return plusSize == totalAsterisks;
                }
            }
        }

        return false;
    }

    /**
     * Checks if the cell at (row, col) has immediate asterisk neighbors in all four directions.
     */
    private static boolean isPotentialCenter(Grid grid, int row, int col) {
        return grid.isAsteriskAt(row - 1, col) &&
               grid.isAsteriskAt(row + 1, col) &&
               grid.isAsteriskAt(row, col - 1) &&
               grid.isAsteriskAt(row, col + 1);
    }

    /**
     * Calculates the total number of asterisks belonging to the plus shape centered at (row, col).
     */
    private static int calculatePlusSize(Grid grid, int row, int col) {
        int count = 1; // Start with the center cell

        // Extend arms in all four cardinal directions
        count += countArmLength(grid, row, col, -1, 0);  // Up
        count += countArmLength(grid, row, col, 1, 0);   // Down
        count += countArmLength(grid, row, col, 0, -1);  // Left
        count += countArmLength(grid, row, col, 0, 1);   // Right

        return count;
    }

    /**
     * Traverses in a specific direction to count consecutive asterisks.
     */
    private static int countArmLength(Grid grid, int row, int col, int dRow, int dCol) {
        int length = 0;
        int currentRow = row + dRow;
        int currentCol = col + dCol;

        while (grid.isAsteriskAt(currentRow, currentCol)) {
            length++;
            currentRow += dRow;
            currentCol += dCol;
        }
        return length;
    }
}

/**
 * Represents the 2D grid and provides helper methods for cell access.
 */
class Grid {
    private static final char ASTERISK = '*';
    private final int height;
    private final int width;
    private final boolean[][] cells;
    private int totalAsterisks = 0;

    public Grid(int height, int width, Scanner scanner) {
        this.height = height;
        this.width = width;
        this.cells = new boolean[height][width];
        initializeGrid(scanner);
    }

    private void initializeGrid(Scanner scanner) {
        for (int i = 0; i < height; i++) {
            String line = scanner.nextLine();
            for (int j = 0; j < width; j++) {
                if (j < line.length() && line.charAt(j) == ASTERISK) {
                    cells[i][j] = true;
                    totalAsterisks++;
                }
            }
        }
    }

    public boolean isAsteriskAt(int row, int col) {
        if (row < 0 || row >= height || col < 0 || col >= width) {
            return false;
        }
        return cells[row][col];
    }

    public int getHeight() {
        return height;
    }

    public int getWidth() {
        return width;
    }

    public int getTotalAsterisks() {
        return totalAsterisks;
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * A utility to determine if a grid consists of exactly one "plus" shape.
 * A plus shape is defined as a central '*' with four arms extending 
 * in cardinal directions.
 */
public class PlusFromPicture {

    /**
     * Represents a position within the 2D grid.
     */
    private static class Coordinate {
        final int row;
        final int col;

        Coordinate(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    private static final char STAR = '*';
    private static final char EMPTY = '.';

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;
            int rowCount = scanner.nextInt();

            if (!scanner.hasNextInt()) return;
            int colCount = scanner.nextInt();

            char[][] grid = new char[rowCount][colCount];
            for (int i = 0; i < rowCount; i++) {
                grid[i] = scanner.next().toCharArray();
            }

            if (isSinglePlusShape(grid, rowCount, colCount)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /**
     * Validates if the grid contains exactly one plus shape and nothing else.
     */
    private static boolean isSinglePlusShape(char[][] grid, int rowCount, int colCount) {
        List<Coordinate> centers = findPlusCenters(grid, rowCount, colCount);

        // The problem logic requires exactly one identified center
        if (centers.size() != 1) {
            return false;
        }

        Coordinate center = centers.get(0);

        // Attempt to "remove" the plus shape from the grid
        erasePlusPattern(grid, center, rowCount, colCount);

        // If the grid is now completely empty (only contains '.'), it was a perfect plus
        return !hasRemainingStars(grid, rowCount, colCount);
    }

    /**
     * Scans the grid to find all cells that act as the center of a minimal plus.
     */
    private static List<Coordinate> findPlusCenters(char[][] grid, int rowCount, int colCount) {
        List<Coordinate> centers = new ArrayList<>();

        // A plus center cannot exist on the boundary of the grid
        for (int r = 1; r < rowCount - 1; r++) {
            for (int c = 1; c < colCount - 1; c++) {
                if (isMinimalPlusAt(grid, r, c)) {
                    centers.add(new Coordinate(r, c));
                }
            }
        }
        return centers;
    }

    /**
     * Checks if the cell at (r, c) is the center of a '*' plus (center + 4 neighbors).
     */
    private static boolean isMinimalPlusAt(char[][] grid, int r, int c) {
        return grid[r][c] == STAR &&
               grid[r - 1][c] == STAR &&
               grid[r + 1][c] == STAR &&
               grid[r][c - 1] == STAR &&
               grid[r][c + 1] == STAR;
    }

    /**
     * Clears the plus pattern by erasing the center and all contiguous arms.
     */
    private static void erasePlusPattern(char[][] grid, Coordinate center, int rowCount, int colCount) {
        int r = center.row;
        int c = center.col;

        // Erase the center
        grid[r][c] = EMPTY;

        // Erase Upward arm
        int row = r - 1;
        while (row >= 0 && grid[row][c] == STAR) {
            grid[row][c] = EMPTY;
            row--;
        }

        // Erase Downward arm
        row = r + 1;
        while (row < rowCount && grid[row][c] == STAR) {
            grid[row][c] = EMPTY;
            row++;
        }

        // Erase Leftward arm
        int col = c - 1;
        while (col >= 0 && grid[r][col] == STAR) {
            grid[r][col] = EMPTY;
            col--;
        }

        // Erase Rightward arm
        col = c + 1;
        while (col < colCount && grid[r][col] == STAR) {
            grid[r][col] = EMPTY;
            col++;
        }
    }

    /**
     * Checks if there are any '*' characters left in the grid.
     */
    private static boolean hasRemainingStars(char[][] grid, int rowCount, int colCount) {
        for (int r = 0; r < rowCount; r++) {
            for (int c = 0; c < colCount; c++) {
                if (grid[r][c] == STAR) {
                    return true;
                }
            }
        }
        return false;
    }
}

import java.util.Scanner;

/**
 * A program to determine if a single cross-shaped pattern of '*' can remove 
 * all stars from a given 2D grid.
 */
public class StarPatternSolver {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        char[][] grid = new char[rows][];

        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        if (canClearAllStars(rows, cols, grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Core logic to find the first cross pattern and check if its removal 
     * clears the entire grid.
     *
     * @param rows Total number of rows in the grid.
     * @param cols Total number of columns in the grid.
     * @param grid The 2D character array representing the grid.
     * @return true if a cross was found and all '*' were removed; false otherwise.
     */
    private static boolean canClearAllStars(int rows, int cols, char[][] grid) {
        int centerRow = -1;
        int centerCol = -1;

        // 1. Search for the first occurrence of a cross pattern.
        // A cross requires a center and four adjacent '*' neighbors.
        // We skip the boundary rows/cols because a cross center cannot exist there.
        findCrossCenter:
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (isCrossCenter(grid, i, j)) {
                    centerRow = i;
                    centerCol = j;
                    break findCrossCenter;
                }
            }
        }

        // If no cross pattern was found, the condition cannot be met.
        if (centerRow == -1) {
            return false;
        }

        // 2. Perform the clearing operation on the found cross.
        clearCross(grid, centerRow, centerCol);

        // 3. Validate if any '*' remains in the grid.
        return !hasRemainingStars(grid);
    }

    /**
     * Checks if the cell at (r, c) is the center of a '+' shaped cross.
     */
    private static boolean isCrossCenter(char[][] grid, int r, int c) {
        return grid[r][c] == '*' &&
               grid[r - 1][c] == '*' &&
               grid[r + 1][c] == '*' &&
               grid[r][c - 1] == '*' &&
               grid[r][c + 1] == '*';
    }

    /**
     * Clears the center star and the continuous line of stars 
     * extending in all four cardinal directions.
     */
    private static void clearCross(char[][] grid, int r, int c) {
        int rows = grid.length;
        int cols = grid[0].length;

        grid[r][c] = '.';

        // Clear vertical line (Up)
        for (int i = r - 1; i >= 0 && grid[i][c] == '*'; i--) {
            grid[i][c] = '.';
        }
        // Clear vertical line (Down)
        for (int i = r + 1; i < rows && grid[i][c] == '*'; i++) {
            grid[i][c] = '.';
        }
        // Clear horizontal line (Left)
        for (int j = c - 1; j >= 0 && grid[r][j] == '*'; j--) {
            grid[r][j] = '.';
        }
        // Clear horizontal line (Right)
        for (int j = c + 1; j < cols && grid[r][j] == '*'; j++) {
            grid[r][j] = '.';
        }
    }

    /**
     * Iterates through the grid to check for any remaining '*' characters.
     */
    private static boolean hasRemainingStars(char[][] grid) {
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '*') {
                    return true;
                }
            }
        }
        return false;
    }
}

import java.util.*;
import java.io.*;

/**
 * A program to validate if a grid of characters contains exactly one 
 * specific T-shaped/Cross-shaped pattern of '*' characters.
 */
public class Codechef {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] grid = reader.readGrid(rows, cols);

            ShapeValidator validator = new ShapeValidator(grid, rows, cols);
            if (validator.isValidShape()) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        } catch (IOException e) {
            out.println("NO");
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Encapsulates the logic for validating the specific '*' shape.
     */
    static class ShapeValidator {
        private final char[][] grid;
        private final int rows;
        private final int cols;
        private final boolean[][] visited;

        public ShapeValidator(char[][] grid, int rows, int cols) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
            this.visited = new boolean[rows][cols];
        }

        public boolean isValidShape() {
            // 1. Find the first star in the grid (top-most, then left-most)
            int[] startPos = findFirstStar();
            if (startPos == null) {
                return false;
            }

            int startRow = startPos[0];
            int startCol = startPos[1];

            // 2. Validate that the first star is a valid top of a vertical stem
            // It shouldn't be on a boundary and shouldn't have horizontal neighbors
            if (isInvalidTop(startRow, startCol)) {
                return false;
            }

            // 3. Trace the vertical stem downwards
            int intersectionRow = traceVerticalStem(startRow, startCol);

            // 4. Validate the intersection and the continuation of the stem
            // The intersection must exist, and the stem must continue below the intersection row
            if (intersectionRow == -1 || !isStemContinuingBelow(intersectionRow, startCol)) {
                return false;
            }

            // 5. Trace the horizontal bar at the intersection row
            traceHorizontalBar(intersectionRow, startCol);

            // 6. Ensure no other '*' characters exist in the grid that weren't part of our shape
            return validateAllStarsVisited();
        }

        private int[] findFirstStar() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '*') {
                        return new int[]{r, c};
                    }
                }
            }
            return null;
        }

        private boolean isInvalidTop(int r, int c) {
            if (c <= 0 || c >= cols - 1) return true;
            return grid[r][c - 1] == '*' || grid[r][c + 1] == '*';
        }

        private int traceVerticalStem(int startRow, int startCol) {
            int lastIntersectionRow = -1;
            int r = startRow;

            while (r < rows && grid[r][startCol] == '*') {
                visited[r][startCol] = true;

                // Check if this row could be the intersection (has left and right neighbors)
                if (r >= 1 && r < rows - 1 && 
                    grid[r][startCol - 1] == '*' && grid[r][startCol + 1] == '*') {
                    lastIntersectionRow = r;
                }
                r++;
            }
            return lastIntersectionRow;
        }

        private boolean isStemContinuingBelow(int intersectionRow, int col) {
            int nextRow = intersectionRow + 1;
            return nextRow < rows && visited[nextRow][col];
        }

        private void traceHorizontalBar(int r, int startCol) {
            // Trace left
            int c = startCol;
            while (c >= 0 && grid[r][c] == '*') {
                visited[r][c] = true;
                c--;
            }
            // Trace right
            c = startCol;
            while (c < cols && grid[r][c] == '*') {
                visited[r][c] = true;
                c++;
            }
        }

        private boolean validateAllStarsVisited() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '*' && !visited[r][c]) {
                        return false;
                    }
                }
            }
            return true;
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public char[][] readGrid(int rows, int cols) throws IOException {
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = reader.reader.readLine();
                // Handle potential empty lines from nextInt() usage
                while (line == null || line.isEmpty()) {
                    line = reader.reader.readLine();
                }
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }
            return grid;
        }
    }
}

import java.util.Scanner;

/**
 * A utility to analyze whether a grid of characters contains 
 * a single cross-shaped pattern of '*' characters that covers all stars.
 */
public class StarGridPatternMatcher {

    private static final char STAR = '*';
    private static final char EMPTY = '.';

    private final int rows;
    private final int cols;
    private final char[][] grid;

    public StarGridPatternMatcher(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
    }

    /**
     * Entry point of the program. Handles input and output.
     */
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }

        int n = scanner.nextInt();
        int m = scanner.nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String rowString = scanner.next();
            for (int j = 0; j < rowString.length() && j < m; j++) {
                grid[i][j] = rowString.charAt(j);
            }
        }

        StarGridPatternMatcher matcher = new StarGridPatternMatcher(n, m, grid);

        if (matcher.isPatternValid()) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Orchestrates the validation logic.
     * 
     * @return true if a valid cross pattern is found and it accounts for all stars.
     */
    public boolean isPatternValid() {
        int[] center = findCrossCenter();

        if (center == null) {
            return false;
        }

        int centerRow = center[0];
        int centerCol = center[1];

        clearLinesFromCenter(centerRow, centerCol);

        return !hasRemainingStars();
    }

    /**
     * Searches for a cell that acts as a center of a cross.
     * A center is defined as a star with four star neighbors (up, down, left, right).
     * 
     * @return an array containing [row, col] of the center, or null if not found.
     */
    private int[] findCrossCenter() {
        // A cross center cannot exist on the boundary of the grid
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (isCrossCenter(i, j)) {
                    return new int[]{i, j};
                }
            }
        }
        return null;
    }

    /**
     * Predicate to check if a specific coordinate is the center of a cross.
     */
    private boolean isCrossCenter(int r, int c) {
        return grid[r][c] == STAR &&
               grid[r + 1][c] == STAR &&
               grid[r - 1][c] == STAR &&
               grid[r][c + 1] == STAR &&
               grid[r][c - 1] == STAR;
    }

    /**
     * Clears the continuous line of stars passing through the center point 
     * horizontally and vertically.
     */
    private void clearLinesFromCenter(int cx, int cy) {
        // Clear Rightward axis
        for (int j = cy; j < cols; j++) {
            if (grid[cx][j] == EMPTY) break;
            grid[cx][j] = EMPTY;
        }
        // Clear Leftward axis
        for (int j = cy - 1; j >= 0; j--) {
            if (grid[cx][j] == EMPTY) break;
            grid[cx][j] = EMPTY;
        }
        // Clear Downward axis
        for (int i = cx + 1; i < rows; i++) {
            if (grid[i][cy] == EMPTY) break;
            grid[i][cy] = EMPTY;
        }
        // Clear Upward axis
        for (int i = cx - 1; i >= 0; i--) {
            if (grid[i][cy] == EMPTY) break;
            grid[i][cy] = EMPTY;
        }
    }

    /**
     * Scans the grid to check if any stars remain.
     * 
     * @return true if there is at least one '*' left in the grid.
     */
    private boolean hasRemainingStars() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == STAR) {
                    return true;
                }
            }
        }
        return false;
    }
}

import java.util.Scanner;

/**
 * CrossPatternSolver identifies if a grid of stars can be completely cleared
 * by removing exactly one cross-shaped pattern.
 */
public class CrossPatternSolver {

    private static final char STAR = '*';
    private static final char DOT = '.';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int height = scanner.nextInt();
        int width = scanner.nextInt();

        // A cross pattern requires at least a 3x3 area to have an interior center.
        if (height < 3 || width < 3) {
            System.out.println("NO");
            return;
        }

        char[][] grid = new char[height][width];
        for (int i = 0; i < height; i++) {
            String rowInput = scanner.next();
            for (int j = 0; j < width; j++) {
                grid[i][j] = rowInput.charAt(j);
            }
        }

        if (canClearGridWithSingleCross(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Attempts to find a single cross center that, when cleared, 
     * leaves no stars remaining in the grid.
     * 
     * @param grid The 2D grid of characters.
     * @return true if exactly one cross clears the grid, false otherwise.
     */
    private static boolean canClearGridWithSingleCross(char[][] grid) {
        int height = grid.length;
        int width = grid[0].length;
        boolean patternFound = false;

        // Search for the first valid center of a cross.
        // A center must be at least 1 unit away from every edge.
        searchLoop:
        for (int i = 1; i < height - 1; i++) {
            for (int j = 1; j < width - 1; j++) {
                if (isCenterOfCross(grid, i, j)) {
                    clearCrossPattern(grid, i, j);
                    patternFound = true;
                    break searchLoop;
                }
            }
        }

        // If no center was found, or if stars remain after clearing, return false.
        return patternFound && containsNoStars(grid);
    }

    /**
     * Checks if the cell at (r, c) and its four cardinal neighbors are stars.
     */
    private static boolean isCenterOfCross(char[][] grid, int r, int c) {
        return grid[r][c] == STAR &&
               grid[r - 1][c] == STAR &&
               grid[r + 1][c] == STAR &&
               grid[r][c - 1] == STAR &&
               grid[r][c + 1] == STAR;
    }

    /**
     * Clears the cross pattern by turning the center and its continuous 
     * horizontal and vertical lines of stars into dots.
     */
    private static void clearCrossPattern(char[][] grid, int r, int c) {
        int height = grid.length;
        int width = grid[0].length;

        // Clear the center
        grid[r][c] = DOT;

        // Clear vertical line (Up and Down)
        for (int i = r + 1; i < height && grid[i][c] == STAR; i++) {
            grid[i][c] = DOT;
        }
        for (int i = r - 1; i >= 0 && grid[i][c] == STAR; i--) {
            grid[i][c] = DOT;
        }

        // Clear horizontal line (Left and Right)
        for (int j = c + 1; j < width && grid[r][j] == STAR; j++) {
            grid[r][j] = DOT;
        }
        for (int j = c - 1; j >= 0 && grid[r][j] == STAR; j--) {
            grid[r][j] = DOT;
        }
    }

    /**
     * Scans the grid to ensure no stars are left.
     */
    private static boolean containsNoStars(char[][] grid) {
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == STAR) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

/**
 * A utility to determine if the '*' characters in a grid form a single, 
 * contiguous, 1-pixel wide cross shape.
 */
public class CrossShapeValidator {

    /**
     * Represents a coordinate in the 2D grid.
     */
    static class Point {
        int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }

        @Override
        public boolean equals(Object obj) {
            if (this == obj) return true;
            if (!(obj instanceof Point)) return false;
            Point other = (Point) obj;
            return r == other.r && c == other.c;
        }
    }

    /**
     * Fast I/O class for efficient input reading.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) {
        FastReader reader = new FastReader();

        String hStr = reader.next();
        if (hStr == null) return;
        int height = Integer.parseInt(hStr);
        int width = reader.nextInt();

        char[][] grid = new char[height][width];
        List<Point> starPositions = new ArrayList<>();

        for (int i = 0; i < height; i++) {
            String row = reader.next();
            for (int j = 0; j < width; j++) {
                grid[i][j] = row.charAt(j);
                if (grid[i][j] == '*') {
                    starPositions.add(new Point(i, j));
                }
            }
        }

        if (isSingleCross(grid, starPositions, height, width)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Validates if the stars form exactly one 1-pixel wide cross.
     */
    private static boolean isSingleCross(char[][] grid, List<Point> stars, int h, int w) {
        if (stars.size() < 5) {
            return false;
        }

        // 1. Identify potential centers. 
        // A center must be a star and have four immediate neighbors.
        List<Point> centers = new ArrayList<>();
        for (Point p : stars) {
            if (isCenter(grid, p, h, w)) {
                centers.add(p);
            }
        }

        // A single 1-pixel wide cross must have exactly one center.
        if (centers.size() != 1) {
            return false;
        }

        Point center = centers.get(0);

        // 2. Verify all stars lie on the horizontal or vertical axis of the center.
        int countInRow = 0;
        int countInCol = 0;
        int minRow = h, maxRow = -1, minCol = w, maxCol = -1;

        for (Point p : stars) {
            boolean onRow = (p.r == center.r);
            boolean onCol = (p.c == center.c);

            if (!onRow && !onCol) {
                return false; // Star is floating somewhere else
            }

            if (onRow) {
                countInRow++;
                minCol = Math.min(minCol, p.c);
                maxCol = Math.max(maxCol, p.c);
            }
            if (onCol) {
                countInCol++;
                minRow = Math.min(minRow, p.r);
                maxRow = Math.max(maxRow, p.r);
            }
        }

        // 3. Verify contiguity.
        // The number of stars on an axis must equal the distance between the furthest stars.
        // (e.g., if stars are at col 1, 2, 3, then maxCol-minCol+1 = 3-1+1 = 3)
        boolean rowIsContiguous = (maxCol - minCol + 1 == countInRow);
        boolean colIsContiguous = (maxRow - minRow + 1 == countInCol);

        if (!rowIsContiguous || !colIsContiguous) {
            return false;
        }

        // 4. Verify total star count matches the cross structure.
        // Total = stars in row + stars in column - 1 (to avoid double-counting the center).
        return stars.size() == (countInRow + countInCol - 1);
    }

    /**
     * Checks if a star at (r, c) is a center (has 4 immediate neighbors).
     */
    private static boolean isCenter(char[][] grid, Point p, int h, int w) {
        if (p.r <= 0 || p.r >= h - 1 || p.c <= 0 || p.c >= w - 1) {
            return false;
        }
        return grid[p.r - 1][p.c] == '*' &&
               grid[p.r + 1][p.c] == '*' &&
               grid[p.r][p.c - 1] == '*' &&
               grid[p.r][p.c + 1] == '*';
    }
}

import java.util.Scanner;

/**
 * A program to detect if a grid contains a single "cross" pattern.
 * A cross pattern consists of exactly one horizontal line and one vertical line
 * of stars ('*') that intersect at a point that is not an endpoint for either line.
 */
public class CrossPatternDetector {

    private static final char STAR = '*';

    /**
     * Represents the result of analyzing a single row or column.
     */
    private enum LineType {
        NONE,       // No stars found
        SINGLE,     // Exactly one contiguous block of stars found
        MULTIPLE    // More than one block of stars found
    }

    private static class LineResult {
        final LineType type;
        final int start;
        final int end;

        private LineResult(LineType type, int start, int end) {
            this.type = type;
            this.start = start;
            this.end = end;
        }

        static LineResult none() {
            return new LineResult(LineType.NONE, -1, -1);
        }

        static LineResult single(int start, int end) {
            return new LineResult(LineType.SINGLE, start, end);
        }

        static LineResult multiple() {
            return new LineResult(LineType.MULTIPLE, -1, -1);
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int height = scanner.nextInt();
        int width = scanner.nextInt();
        char[][] grid = new char[height][width];

        for (int i = 0; i < height; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        if (isCrossPattern(grid, height, width)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Core logic to determine if the grid matches the required cross pattern.
     */
    private static boolean isCrossPattern(char[][] grid, int height, int width) {
        // 1. Identify the horizontal segment (the unique row containing a star block)
        int rowIdx = -1;
        int rowStart = -1, rowEnd = -1;

        for (int i = 0; i < height; i++) {
            LineResult res = analyzeLine(grid[i]);
            if (res.type == LineType.MULTIPLE) return false;

            // A valid cross requires a segment with length > 1 to allow intersection
            if (res.type == LineType.SINGLE && res.start != res.end) {
                if (rowIdx != -1) return false; // More than one segment-carrying row found
                rowIdx = i;
                rowStart = res.start;
                rowEnd = res.end;
            }
        }

        // 2. Identify the vertical segment (the unique column containing a star block)
        int colIdx = -1;
        int colStart = -1, colEnd = -1;

        for (int j = 0; j < width; j++) {
            char[] column = new char[height];
            for (int i = 0; i < height; i++) {
                column[i] = grid[i][j];
            }

            LineResult res = analyzeLine(column);
            if (res.type == LineType.MULTIPLE) return false;

            if (res.type == LineType.SINGLE && res.start != res.end) {
                if (colIdx != -1) return false; // More than one segment-carrying column found
                colIdx = j;
                colStart = res.start;
                colEnd = res.end;
            }
        }

        // 3. Validation: We must have exactly one row segment and one column segment
        if (rowIdx == -1 || colIdx == -1) {
            return false;
        }

        // 4. Intersection Check: The perpendicular line must cross through the interior of the segment
        // (The intersection point cannot be the first or last star of either line)
        boolean intersectsProperly = (colIdx > rowStart && colIdx < rowEnd) &&
                                     (rowIdx > colStart && rowIdx < colEnd);

        if (!intersectsProperly) {
            return false;
        }

        // 5. Final Integrity Check: Ensure there are no "stray" stars elsewhere in the grid.
        // If the pattern is a perfect cross, the total star count must equal 
        // (stars in row) + (stars in column) - (1 for the intersection point).
        int actualStarCount = countStars(grid, height, width);
        int expectedStarCount = (rowEnd - rowStart + 1) + (colEnd - colStart + 1) - 1;

        return actualStarCount == expectedStarCount;
    }

    /**
     * Scans a 1D array to find contiguous blocks of stars.
     */
    private static LineResult analyzeLine(char[] line) {
        int first = -1;
        int last = -1;
        int blockCount = 0;
        boolean inBlock = false;

        for (int i = 0; i < line.length; i++) {
            if (line[i] == STAR) {
                if (!inBlock) {
                    blockCount++;
                    inBlock = true;
                    first = i;
                }
                last = i;
            } else {
                inBlock = false;
            }
        }

        if (blockCount == 0) return LineResult.none();
        if (blockCount > 1) return LineResult.multiple();
        return LineResult.single(first, last);
    }

    /**
     * Counts total number of stars in the grid.
     */
    private static int countStars(char[][] grid, int height, int width) {
        int count = 0;
        for (int i = 0; i < height; i++) {
            for (int j = 0; j < width; j++) {
                if (grid[i][j] == STAR) {
                    count++;
                }
            }
        }
        return count;
    }
}

import java.util.Scanner;

/**
 * The ChessboardSolver class determines if all '*' characters in a grid
 * can be covered by a single cross-shaped pattern.
 */
public class ChessboardSolver {

    private static final char STAR = '*';
    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final boolean[][] visited;

    public ChessboardSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.visited = new boolean[rows][cols];
        initializeVisited();
    }

    /**
     * Initializes the visited array. 
     * Cells containing '*' are marked as false (not visited),
     * while other cells are marked as true (effectively ignored).
     */
    private void initializeVisited() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                visited[i][j] = (grid[i][j] != STAR);
            }
        }
    }

    /**
     * Orchestrates the logic to solve the chessboard problem.
     * @return "YES" if all stars are covered by one cross, "NO" otherwise.
     */
    public String solve() {
        if (!containsAnyStar()) {
            return "NO";
        }

        int[] center = findFirstCrossCenter();

        if (center != null) {
            markCross(center[0], center[1]);
        }

        return areAllStarsVisited() ? "YES" : "NO";
    }

    private boolean containsAnyStar() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == STAR) return true;
            }
        }
        return false;
    }

    /**
     * Finds the first cell that can act as the center of a cross.
     * A cross center must be surrounded by '*' in all four cardinal directions.
     */
    private int[] findFirstCrossCenter() {
        // A center cannot be on the edge because it needs neighbors on all sides
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (isCrossCenter(i, j)) {
                    return new int[]{i, j};
                }
            }
        }
        return null;
    }

    private boolean isCrossCenter(int r, int c) {
        return grid[r - 1][c] == STAR &&
               grid[r + 1][c] == STAR &&
               grid[r][c - 1] == STAR &&
               grid[r][c + 1] == STAR;
    }

    /**
     * Expands from the center in four directions, marking all 
     * connected '*' characters as visited.
     */
    private void markCross(int r, int c) {
        // Mark the center itself if it is a star
        if (grid[r][c] == STAR) {
            visited[r][c] = true;
        }

        // Directions: Up, Down, Left, Right
        int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

        for (int[] dir : directions) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            // Move in the current direction as long as we hit '*'
            while (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == STAR) {
                visited[nr][nc] = true;
                nr += dir[0];
                nc += dir[1];
            }
        }
    }

    private boolean areAllStarsVisited() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (!visited[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;

            int h = scanner.nextInt();
            int w = scanner.nextInt();
            scanner.nextLine(); // Consume newline

            char[][] grid = new char[h][w];
            for (int i = 0; i < h; i++) {
                String line = scanner.nextLine();
                for (int j = 0; j < w; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }

            ChessboardSolver solver = new ChessboardSolver(h, w, grid);
            System.out.print(solver.solve());
        } catch (Exception e) {
            // In a production environment, use a logger
            System.err.println("Error processing input: " + e.getMessage());
        }
    }
}

