/**
 * A program to detect if a grid of characters forms a specific cross-shaped pattern.
 * A valid pattern consists of a single horizontal bar and a single vertical bar 
 * whose intersection accounts for all non-dot characters in the grid.
 */
public class CrossShapeDetector {

    public static void main(String[] args) {
        try (FastScanner scanner = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

