            }

        } catch (IOException e) {
            // Handle potential I/O errors
        }
    }

    /**
     * Orchestrates the search for a valid cross pattern within the grid.
     * 
     * @param grid The 2D integer representation of the grid (1 for point, 0 for empty).
     * @param h Height of the grid.
     * @param w Width of the grid.
     * @param totalPoints Total number of non-empty cells in the grid.
     * @param rowCounts Count of points in each row.
     * @return true if a valid cross pattern is found.
     */
    private static boolean isCrossPatternPresent(int[][] grid, int h, int w, int totalPoints, int[] rowCounts) {
        // 1. Identify a potential center row.
        // A center row must not be an edge and must contain at least 3 points to form a cross.
        int centerRow = -1;
        for (int i = 1; i < h - 1; i++) {
            if (rowCounts[i] >= 3) {
                centerRow = i;
                break;
            }
        }

        if (centerRow == -1) {
            return false;
        }

        // 2. Find the first contiguous segment of points in the candidate center row.
        int segmentStart = -1;
        int segmentEnd = -1;

        for (int j = 0; j < w; j++) {
            if (grid[centerRow][j] == 1) {
                int start = j;
                while (j < w && grid[centerRow][j] == 1) {
                    j++;
                }
                segmentStart = start;
                segmentEnd = j - 1;

                // 3. Check if any column in this horizontal segment forms a valid vertical intersection.
                if (validateIntersection(grid, h, w, segmentStart, segmentEnd, centerRow, totalPoints)) {
                    return true;
                }

                // We only consider the first contiguous segment found, mirroring original logic.
                break;
            }
        }

        return false;
    }

    /**
     * Checks if a vertical bar passing through a specific column within a horizontal segment
     * accounts for all the points in the grid.
     */
    private static boolean validateIntersection(int[][] grid, int h, int w, int start, int end, int row, int totalPoints) {
        int horizontalLength = end - start + 1;

        for (int col = start; col <= end; col++) {
            int verticalAbove = 0;
            for (int r = row - 1; r >= 0; r--) {
                if (grid[r][col] == 1) verticalAbove++;
                else break;
            }

            int verticalBelow = 0;
            for (int r = row + 1; r < h; r++) {
                if (grid[r][col] == 1) verticalBelow++;
                else break;
            }

            // A valid cross must extend both above and below the intersection point.
            if (verticalAbove > 0 && verticalBelow > 0) {
                // Total points = width of horizontal bar + height of vertical bar - 1 (intersection)
                if (horizontalLength + verticalAbove + verticalBelow == totalPoints) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Utility class for fast input reading.
     */
    static class FastScanner implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        @Override
        public void close() throws IOException {
            reader.close();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to determine if a grid of characters contains exactly one 
 * cross-shaped pattern made of '*' characters and no other '*' characters.
 */
public class Main {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);

        int rowCount = scanner.nextInt();
        int colCount = scanner.nextInt();

        char[][] grid = new char[rowCount][colCount];
        for (int i = 0; i < rowCount; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        CrossPatternChecker checker = new CrossPatternChecker(grid);
        System.out.println(checker.isCrossPattern() ? "YES" : "NO");
    }

    /**
     * Represents the four cardinal directions for grid traversal.
     */
    enum Direction {
        UP(-1, 0),
        DOWN(1, 0),
        LEFT(0, -1),
        RIGHT(0, 1);

        final int dr;
        final int dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }
    }

    /**
     * Logic handler for validating the cross pattern within a grid.
     */
    static class CrossPatternChecker {
        private final char[][] grid;
        private final int rows;
        private final int cols;
        private static final char TARGET_CHAR = '*';

        public CrossPatternChecker(char[][] grid) {
            this.grid = grid;
            this.rows = grid.length;
            this.cols = grid[0].length;
        }

        /**
         * Validates if the grid contains exactly one cross pattern and no other stars.
         */
        public boolean isCrossPattern() {
            int totalStarCount = countTotalStars();

            // Find potential center(s) of the cross
            List<int[]> centers = findCenters();

            // A valid cross must have exactly one center
            if (centers.size() != 1) {
                return false;
            }

            int[] center = centers.get(0);
            int centerRow = center[0];
            int centerCol = center[1];

            // Calculate how many stars are part of the cross arms
            // We start with 1 to account for the center itself
            int starsInCross = 1;
            for (Direction dir : Direction.values()) {
                starsInCross += countStarsInDirection(centerRow, centerCol, dir);
            }

            // The pattern is valid if the number of stars in the cross 
            // matches the total number of stars in the grid.
            return starsInCross == totalStarCount;
        }

        private int countTotalStars() {
            int count = 0;
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == TARGET_CHAR) {
                        count++;
                    }
                }
            }
            return count;
        }

        private List<int[]> findCenters() {
            List<int[]> centers = new ArrayList<>();
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (isCenter(r, c)) {
                        centers.add(new int[]{r, c});
                    }
                }
            }
            return centers;
        }

        private boolean isCenter(int r, int c) {
            if (grid[r][c] != TARGET_CHAR) {
                return false;
            }

            // A center must have a neighbor in all 4 directions
            for (Direction dir : Direction.values()) {
                int nr = r + dir.dr;
                int nc = c + dir.dc;
                if (!isInRange(nr, nc) || grid[nr][nc] != TARGET_CHAR) {
                    return false;
                }
            }
            return true;
        }

        private int countStarsInDirection(int startR, int startC, Direction dir) {
            int count = 0;
            int currR = startR + dir.dr;
            int currC = startC + dir.dc;

            while (isInRange(currR, currC) && grid[currR][currC] == TARGET_CHAR) {
                count++;
                currR += dir.dr;
                currC += dir.dc;
            }
            return count;
        }

        private boolean isInRange(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * Efficient input reader for large datasets.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solution for the grid cross-clearing problem.
 * The goal is to find a '*' that forms a cross and clear its entire horizontal 
 * and vertical arms, then check if any '*' remain.
 */
public class GridProblemSolver {

    private static final char STAR = '*';
    private static final char EMPTY = '.';

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int height = reader.nextInt();
            int width = reader.nextInt();
            char[][] grid = reader.readGrid(height);

            if (solve(grid, height, width)) {
                writer.println("YES");
            } else {
                writer.println("NO");
            }
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Processes the grid to determine if it can be cleared by a single cross.
     * 
     * @param grid The 2D character array representing the grid.
     * @param height Height of the grid.
     * @param width Width of the grid.
     * @return true if the grid is cleared successfully, false otherwise.
     */
    private static boolean solve(char[][] grid, int height, int width) {
        int centerX = -1;
        int centerY = -1;

        // 1. Find the center of a cross
        // We iterate from h-2 down to 1 to match the original logic's search order
        search:
        for (int r = height - 2; r > 0; r--) {
            for (int c = width - 2; c > 0; c--) {
                if (isCrossCenter(grid, r, c)) {
                    centerX = r;
                    centerY = c;
                    break search;
                }
            }
        }

        // If no cross center is found, we cannot clear the grid
        if (centerX == -1) {
            return false;
        }

        // 2. Clear the cross and its arms
        clearCross(grid, centerX, centerY, height, width);

        // 3. Verify if any stars remain
        return !hasRemainingStars(grid, height, width);
    }

    /**
     * Checks if the cell at (r, c) is the center of a cross of stars.
     */
    private static boolean isCrossCenter(char[][] grid, int r, int c) {
        return grid[r][c] == STAR &&
               grid[r - 1][c] == STAR &&
               grid[r + 1][c] == STAR &&
               grid[r][c - 1] == STAR &&
               grid[r][c + 1] == STAR;
    }

    /**
     * Clears the center and the continuous lines of stars in four directions.
     */
    private static void clearCross(char[][] grid, int r, int c, int height, int width) {
        grid[r][c] = EMPTY;

        int[][] directions = {
            {0, 1},  // Right
            {0, -1}, // Left
            {1, 0},  // Down
            {-1, 0}  // Up
        };

        for (int[] dir : directions) {
            int nextR = r + dir[0];
            int nextC = c + dir[1];

            // Continue clearing in the direction as long as we find stars
            while (isValid(nextR, nextC, height, width) && grid[nextR][nextC] == STAR) {
                grid[nextR][nextC] = EMPTY;
                nextR += dir[0];
                nextC += dir[1];
            }
        }
    }

    private static boolean hasRemainingStars(char[][] grid, int height, int width) {
        for (int r = 0; r < height; r++) {
            for (int c = 0; c < width; c++) {
                if (grid[r][c] == STAR) {
                    return true;
                }
            }
        }
        return false;
    }

    private static boolean isValid(int r, int c, int height, int width) {
        return r >= 0 && r < height && c >= 0 && c < width;
    }

    /**
     * Fast I/O Utility class.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public char[][] readGrid(int rows) throws IOException {
            char[][] grid = new char[rows][];
            for (int i = 0; i < rows; i++) {
                grid[i] = next().toCharArray();
            }
            return grid;
        }
    }
}

import java.util.Scanner;

/**
 * A utility class to detect if a 2D grid contains a valid "Plus" shape.
 * A valid plus is defined as a single contiguous cross of '*' characters,
 * with no other '*' characters present anywhere else in the grid.
 */
public class PlusFinder {

    private static final char STAR = '*';
    private static final char EMPTY = '.';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        char[][] grid = new char[rows][cols];
        int totalStarsInGrid = 0;

        // Read grid and pre-calculate total stars for O(1) cross-validation
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            grid[i] = line.toCharArray();
            for (char cell : grid[i]) {
                if (cell == STAR) {
                    totalStarsInGrid++;
                }
            }
        }

        if (findPlus(grid, rows, cols, totalStarsInGrid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Orchestrates the search for a valid plus shape in the grid.
     */
    private static boolean findPlus(char[][] grid, int rows, int cols, int totalStars) {
        // A plus shape requires at least a 3x3 area
        if (rows < 3 || cols < 3) {
            return false;
        }

        // Iterate through all possible center points (excluding boundaries)
        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < cols - 1; c++) {
                // Optimization: Check for a minimal 3x3 core before performing heavy validation
                if (isCorePresent(grid, r, c)) {
                    if (isValidPlus(grid, r, c, rows, cols, totalStars)) {
                        return true;
                    }
                }
            }
        }

        return false;
    }

    /**
     * Checks if the 3x3 cross pattern exists at the given center.
     */
    private static boolean isCorePresent(char[][] grid, int r, int c) {
        return grid[r][c] == STAR &&
               grid[r - 1][c] == STAR &&
               grid[r + 1][c] == STAR &&
               grid[r][c - 1] == STAR &&
               grid[r][c + 1] == STAR;
    }

    /**
     * Validates if the star pattern at (r, c) is the only plus in the grid.
     */
    private static boolean isValidPlus(char[][] grid, int r, int c, int rows, int cols, int totalStars) {
        // 1. Ensure no stars exist outside the central row and column
        if (countStarsOnCross(grid, r, c, rows, cols) != totalStars) {
            return false;
        }

        // 2. Ensure the arms of the cross are contiguous (no gaps like * . *)
        return areArmsContinuous(grid, r, c, rows, cols);
    }

    /**
     * Counts how many stars are located on the horizontal and vertical lines crossing at (r, c).
     */
    private static int countStarsOnCross(char[][] grid, int r, int c, int rows, int cols) {
        int count = 1; // The center star

        // Count stars in the row
        for (int j = 0; j < cols; j++) {
            if (j != c && grid[r][j] == STAR) {
                count++;
            }
        }

        // Count stars in the column
        for (int i = 0; i < rows; i++) {
            if (i != r && grid[i][c] == STAR) {
                count++;
            }
        }

        return count;
    }

    /**
     * Checks all four directions to ensure stars form a solid block from the center.
     */
    private static boolean areArmsContinuous(char[][] grid, int r, int c, int rows, int cols) {
        return isDirectionContinuous(grid, r, c, -1, 0, rows, cols) && // Up
               isDirectionContinuous(grid, r, c, 1, 0, rows, cols) &&  // Down
               isDirectionContinuous(grid, r, c, 0, -1, rows, cols) && // Left
               isDirectionContinuous(grid, r, c, 0, 1, rows, cols);    // Right
    }

    /**
     * Traverses in a specific direction to ensure no star appears after an empty cell.
     */
    private static boolean isDirectionContinuous(char[][] grid, int r, int c, int dr, int dc, int rows, int cols) {
        int currR = r + dr;
        int currC = c + dc;
        boolean foundEmptyCell = false;

        while (currR >= 0 && currR < rows && currC >= 0 && currC < cols) {
            if (grid[currR][currC] == STAR) {
                // If we find a star after having already encountered an empty cell, it's not a valid arm
                if (foundEmptyCell) {
                    return false;
                }
            } else {
                foundEmptyCell = true;
            }
            currR += dr;
            currC += dc;
        }
        return true;
    }
}

