/**
 * A utility to determine if a grid of characters contains a single "plus" shape.
 * A plus shape is defined as a central '*' with four arms of '*' extending 
 * upwards, downwards, leftwards, and rightwards, such that all '*' in the 
 * grid are part of this single shape.
 */
public class PlusFromPicture {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
