        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.nextLine();
            grid[i] = line.toCharArray();
        }

        PlusShapeDetector detector = new PlusShapeDetector(grid);
        if (detector.isSinglePlusShapePresent()) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }
}

class PlusShapeDetector {
    private final char[][] grid;
    private final int rows;
    private final int cols;

    // Direction vectors for Up, Down, Left, Right
    private static final int[][] DIRECTIONS = {
        {-1, 0}, // Up
        {1, 0},  // Down
        {0, -1}, // Left
        {0, 1}   // Right
    };

    public PlusShapeDetector(char[][] grid) {
        this.grid = grid;
        this.rows = grid.length;
        this.cols = (rows > 0) ? grid[0].length : 0;
    }

    /**
     * Checks if the grid contains exactly one plus shape and no other stars.
     */
    public boolean isSinglePlusShapePresent() {
        int totalStars = countTotalStars();

        // A plus shape must have at least 5 stars (center + 4 arms)
        if (totalStars < 5) {
            return false;
        }

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*' && isPotentialCenter(r, c)) {
                    // If we find a center, check if the stars in its arms 
                    // account for all stars in the grid.
                    if (countStarsInPlus(r, c) == totalStars) {
                        return true;
                    }
                }
            }
        }

        return false;
    }

    private int countTotalStars() {
        int count = 0;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*') {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * A cell is a potential center if it and its four immediate neighbors are stars.
     */
    private boolean isPotentialCenter(int r, int c) {
        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            if (!isWithinBounds(nr, nc) || grid[nr][nc] != '*') {
                return false;
            }
        }
        return true;
    }

    /**
     * Counts all stars belonging to the plus shape centered at (r, c) 
     * by traversing the four arms.
     */
    private int countStarsInPlus(int r, int c) {
        int count = 1; // Start with the center star

        for (int[] dir : DIRECTIONS) {
            int currR = r + dir[0];
            int currC = c + dir[1];

            // Walk along the arm in the current direction
            while (isWithinBounds(currR, currC) && grid[currR][currC] == '*') {
                count++;
                currR += dir[0];
                currC += dir[1];
            }
        }
        return count;
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

import java.util.Scanner;

/**
 * A utility to detect if a grid contains a single "plus" shape 
 * formed by '*' characters that encompasses all '*' characters in the grid.
 */
public class PlusShapeDetector {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }
        int height = scanner.nextInt();

        if (!scanner.hasNextInt()) {
            return;
        }
        int width = scanner.nextInt();

        char[][] grid = new char[height][width];
        int totalAsterisks = 0;

        // Parse grid and count total asterisks
        for (int i = 0; i < height; i++) {
            if (!scanner.hasNext()) break;
            String row = scanner.next();
            for (int j = 0; j < width; j++) {
                grid[i][j] = row.charAt(j);
                if (grid[i][j] == '*') {
                    totalAsterisks++;
                }
            }
        }
        scanner.close();

        // Execute detection logic and output result
        if (containsPerfectPlus(grid, height, width, totalAsterisks)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Searches the grid for a center point that forms a plus shape 
     * using exactly the total number of asterisks found in the grid.
     *
     * @param grid            The 2D character array representing the grid.
     * @param height          The height of the grid.
     * @param width           The width of the grid.
     * @param totalAsterisks  The total count of '*' characters in the grid.
     * @return true if a plus shape uses all asterisks, false otherwise.
     */
    private static boolean containsPerfectPlus(char[][] grid, int height, int width, int totalAsterisks) {
        // A plus shape requires at least 5 asterisks (center + 4 neighbors).
        if (totalAsterisks < 5) {
            return false;
        }

        // A center of a plus cannot be on the edge of the grid.
        for (int r = 1; r < height - 1; r++) {
            for (int c = 1; c < width - 1; c++) {
                if (grid[r][c] == '*' && isPotentialCenter(grid, r, c)) {
                    int plusSize = calculatePlusSize(grid, r, c, height, width);

                    if (plusSize == totalAsterisks) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if the immediate neighbors (top, bottom, left, right) of a cell are all asterisks.
     */
    private static boolean isPotentialCenter(char[][] grid, int r, int c) {
        return grid[r - 1][c] == '*' &&
               grid[r + 1][c] == '*' &&
               grid[r][c - 1] == '*' &&
               grid[r][c + 1] == '*';
    }

    /**
     * Calculates the total number of '*' characters forming a plus shape 
     * centered at the specified coordinates.
     */
    private static int calculatePlusSize(char[][] grid, int r, int c, int height, int width) {
        int count = 1; // Start with the center cell

        // Traverse Up
        for (int i = r - 1; i >= 0 && grid[i][c] == '*'; i--) {
            count++;
        }
        // Traverse Down
        for (int i = r + 1; i < height && grid[i][c] == '*'; i++) {
            count++;
        }
        // Traverse Left
        for (int j = c - 1; j >= 0 && grid[r][j] == '*'; j--) {
            count++;
        }
        // Traverse Right
        for (int j = c + 1; j < width && grid[r][j] == '*'; j++) {
            count++;
        }

        return count;
    }
}

