/**
 * Represents the game board/grid and provides safe access to cell data.
 */
class Grid {
    private final char[][] cells;
    private final int height;
    private final int width;

    public Grid(char[][] cells) {
        this.cells = cells;
        this.height = cells.length;
        this.width = cells[0].length;
    }

    public int getHeight() {
        return height;
    }

    public int getWidth() {
        return width;
    }

    /**
     * Safely checks if a specific coordinate contains a star.
     * Bounds checking is handled internally.
     */
    public boolean isStar(int row, int col) {
        return row >= 0 && row < height && 
               col >= 0 && col < width && 
               cells[row][col] == '*';
    }

    /**
     * Counts the total number of '*' characters in the grid.
     */
    public int countTotalStars() {
        int count = 0;
        for (int r = 0; r < height; r++) {
            for (int c = 0; c < width; c++) {
                if (cells[r][c] == '*') {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Calculates the number of stars forming a cross shape centered at (row, col).
     */
    public int countStarsInCross(int row, int col) {
        int total = 1; // Start with the center star
        for (Direction dir : Direction.values()) {
            total += getRayLength(row, col, dir);
        }
        return total;
    }

    private int getRayLength(int row, int col, Direction direction) {
        int length = 0;
        int currR = row + direction.getDeltaRow();
        int currC = col + direction.getDeltaCol();

        while (isStar(currR, currC)) {
            length++;
            currR += direction.getDeltaRow();
            currC += direction.getDeltaCol();
        }
        return length;
    }
}

/**
 * Defines the possible directions for ray traversal.
 */
enum Direction {
    UP(-1, 0),
    DOWN(1, 0),
    LEFT(0, -1),
    RIGHT(0, 1);

    private final int deltaRow;
    private final int deltaCol;

    Direction(int deltaRow, int deltaCol) {
        this.deltaRow = deltaRow;
        this.deltaCol = deltaCol;
    }

    public int getDeltaRow() {
        return deltaRow;
    }

    public int getDeltaCol() {
        return deltaCol;
    }
}

/**
 * Contains the algorithm to identify if the grid contains a perfect star pattern.
 */
class StarPatternSolver {

    /**
     * Checks if the grid contains a single star pattern that accounts for all stars in the grid.
     */
    public boolean solve(Grid grid) {
        int totalStars = grid.countTotalStars();
        if (totalStars == 0) {
            return false;
        }

        // We iterate from 1 to height-2 because a center must have neighbors on all sides
        for (int r = 1; r < grid.getHeight() - 1; r++) {
            for (int c = 1; c < grid.getWidth() - 1; c++) {
                if (isPotentialCenter(grid, r, c)) {
                    // If this center accounts for all stars in the grid, we found the pattern
                    if (grid.countStarsInCross(r, c) == totalStars) {
                        return true;
                    }
                }
            }
        }

        return false;
    }

    /**
     * A potential center is a star that has immediate neighbors in all four directions.
     */
    private boolean isPotentialCenter(Grid grid, int r, int c) {
        return grid.isStar(r, c) &&
               grid.isStar(r - 1, c) &&
               grid.isStar(r + 1, c) &&
               grid.isStar(r, c - 1) &&
               grid.isStar(r, c + 1);
    }
}

import java.util.*;

/**
 * A utility to validate if a grid of characters contains a single, 
 * continuous cross shape made of '*' characters.
 */
public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        char[][] grid = new char[rows][cols];
        List<Point> allStars = new ArrayList<>();

        // Read input and collect all star coordinates
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] == '*') {
                    allStars.add(new Point(i, j));
                }
            }
        }

        CrossPatternValidator validator = new CrossPatternValidator(grid, rows, cols, allStars);
        if (validator.isValidCross()) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Represents a coordinate in the 2D grid.
     */
    private static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Logic for validating the cross pattern.
     */
    private static class CrossPatternValidator {
        private final char[][] grid;
        private final int rows;
        private final int cols;
        private final List<Point> allStars;

        public CrossPatternValidator(char[][] grid, int rows, int cols, List<Point> allStars) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
            this.allStars = allStars;
        }

        /**
         * Validates if the stars form exactly one continuous cross.
         */
        public boolean isValidCross() {
            if (allStars.isEmpty()) {
                return false;
            }

            Point center = findCenter();
            if (center == null) {
                return false;
            }

            return validateConnectivity(center);
        }

        /**
         * Finds the center of the cross. 
         * A center is defined as a '*' with four '*' neighbors.
         */
        private Point findCenter() {
            // A cross requires at least a 3x3 area to have a center with 4 neighbors
            for (int i = 1; i < rows - 1; i++) {
                for (int j = 1; j < cols - 1; j++) {
                    if (isCenterAt(i, j)) {
                        return new Point(i, j);
                    }
                }
            }
            return null;
        }

        private boolean isCenterAt(int r, int c) {
            return grid[r][c] == '*' &&
                   grid[r - 1][c] == '*' &&
                   grid[r + 1][c] == '*' &&
                   grid[r][c - 1] == '*' &&
                   grid[r][c + 1] == '*';
        }

        /**
         * Ensures all stars lie on the center axes and form a single continuous segment.
         */
        private boolean validateConnectivity(Point center) {
            int centerX = center.row;
            int centerY = center.col;

            int minRowInCol = centerX;
            int maxRowInCol = centerX;
            int minColInRow = centerY;
            int maxColInRow = centerY;

            for (Point star : allStars) {
                // 1. Every star must lie on the same row or same column as the center
                if (star.row != centerX && star.col != centerY) {
                    return false;
                }

                // 2. Track the bounds of the stars on the horizontal and vertical axes
                if (star.row == centerX) {
                    minColInRow = Math.min(minColInRow, star.col);
                    maxColInRow = Math.max(maxColInRow, star.col);
                }
                if (star.col == centerY) {
                    minRowInCol = Math.min(minRowInCol, star.row);
                    maxRowInCol = Math.max(maxRowInCol, star.row);
                }
            }

            // 3. Calculate how many stars a continuous cross with these bounds should have.
            // Formula: (width of horizontal segment) + (height of vertical segment) - 1 (overlap at center)
            long expectedStarCount = (long) (maxColInRow - minColInRow + 1) + 
                                     (long) (maxRowInCol - minRowInCol + 1) - 1;

            // If the actual count matches the expected count, the shape is continuous and contains no gaps.
            return allStars.size() == expectedStarCount;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solution to find if a grid contains a "star cross" that encompasses all '*' characters.
 * A star cross is defined by a center '*' with at least one '*' extending 
 * in all four cardinal directions, such that all '*' in the grid belong to this cross.
 */
public class Solution {

    private static final char STAR = '*';
    private static final char EMPTY = '.';

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        int rowCount = reader.nextInt();
        int colCount = reader.nextInt();

        // Edge case: A cross requires at least a 3x3 area to have a center and 4 arms
        if (rowCount < 3 || colCount < 3) {
            // Consume the grid to prevent input residue if this were part of a larger system
            for (int i = 0; i < rowCount; i++) reader.next();
            System.out.println("NO");
            return;
        }

        char[][] grid = new char[rowCount][colCount];
        int totalStars = 0;

        for (int i = 0; i < rowCount; i++) {
            String line = reader.next();
            grid[i] = line.toCharArray();
            for (int j = 0; j < colCount; j++) {
                if (grid[i][j] == STAR) {
                    totalStars++;
                }
            }
        }

        if (solve(grid, rowCount, colCount, totalStars)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Determines if a valid star cross exists in the grid.
     * Uses Dynamic Programming to achieve O(N*M) time complexity.
     */
    private static boolean solve(char[][] grid, int rows, int cols, int totalStars) {
        if (totalStars == 0) return false;

        // DP tables to store the number of consecutive stars in each direction
        int[][] up = new int[rows][cols];
        int[][] down = new int[rows][cols];
        int[][] left = new int[rows][cols];
        int[][] right = new int[rows][cols];

        // Fill DP tables
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == STAR) {
                    up[i][j] = (i > 0) ? up[i - 1][j] + 1 : 1;
                    left[i][j] = (j > 0) ? left[i][j - 1] + 1 : 1;
                }
            }
        }

        for (int i = rows - 1; i >= 0; i--) {
            for (int j = cols - 1; j >= 0; j--) {
                if (grid[i][j] == STAR) {
                    down[i][j] = (i < rows - 1) ? down[i + 1][j] + 1 : 1;
                    right[i][j] = (j < cols - 1) ? right[i][j + 1] + 1 : 1;
                }
            }
        }

        // Check every cell (excluding edges) to see if it can be the center of the cross
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (grid[i][j] == STAR) {
                    // Count stars in each arm (excluding the center itself)
                    int u = up[i - 1][j];
                    int d = down[i + 1][j];
                    int l = left[i][j - 1];
                    int r = right[i][j + 1];

                    // Condition 1: All four arms must have at least one star
                    // Condition 2: The sum of center + 4 arms must equal total stars in grid
                    if (u > 0 && d > 0 && l > 0 && r > 0) {
                        if (1 + u + d + l + r == totalStars) {
                            return true;
                        }
                    }
                }
            }
        }

        return false;
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

/**
 * Analyzes a grid to determine if all asterisks form a single "plus" shape.
 */
class PlusShapeFinder {
    private final char[][] grid;
    private final int height;
    private final int width;
    private final int totalAsterisks;

    public PlusShapeFinder(char[][] grid, int height, int width, int totalAsterisks) {
        this.grid = grid;
        this.height = height;
        this.width = width;
        this.totalAsterisks = totalAsterisks;
    }

    /**
     * Determines if there is a cell in the grid that acts as the center of 
     * a plus shape containing all the asterisks in the grid.
     * 
     * @return true if a valid plus shape encompassing all asterisks exists.
     */
    public boolean containsCompletePlusShape() {
        for (int r = 0; r < height; r++) {
            for (int c = 0; c < width; c++) {
                if (isCenterOfCompletePlus(r, c)) {
                    return true;
                }
            }
        }
        return false;
    }

    private boolean isCenterOfCompletePlus(int row, int col) {
        // A plus shape center must be an asterisk
        if (grid[row][col] != '*') {
            return false;
        }

        // Count asterisks in all four directions from the center
        int up = countConsecutiveAsterisks(row, col, -1, 0);
        int down = countConsecutiveAsterisks(row, col, 1, 0);
        int left = countConsecutiveAsterisks(row, col, 0, -1);
        int right = countConsecutiveAsterisks(row, col, 0, 1);

        // Total asterisks in this plus shape: center (1) + the four arms
        int plusShapeSize = 1 + up + down + left + right;

        // Check if this shape accounts for every asterisk in the grid
        return plusShapeSize == totalAsterisks;
    }

    /**
     * Counts consecutive asterisks in a specific direction.
     * 
     * @param startRow The starting row index.
     * @param startCol The starting column index.
     * @param rowDir   The direction of movement for rows (-1, 0, or 1).
     * @param colDir   The direction of movement for columns (-1, 0, or 1).
     * @return The number of consecutive asterisks found in that direction.
     */
    private int countConsecutiveAsterisks(int startRow, int startCol, int rowDir, int colDir) {
        int count = 0;
        int currentRow = startRow + rowDir;
        int currentCol = startCol + colDir;

        while (isWithinBounds(currentRow, currentCol) && grid[currentRow][currentCol] == '*') {
            count++;
            currentRow += rowDir;
            currentCol += colDir;
        }

        return count;
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < height && c >= 0 && c < width;
    }
}

public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int height = scanner.nextInt();

        if (!scanner.hasNextInt()) return;
        int width = scanner.nextInt();

        char[][] grid = new char[height][width];
        int totalAsterisks = 0;

        for (int i = 0; i < height; i++) {
            String line = scanner.next();
            grid[i] = line.toCharArray();

            // Count asterisks as we read the input
            for (char ch : grid[i]) {
                if (ch == '*') {
                    totalAsterisks++;
                }
            }
        }

        PlusShapeFinder finder = new PlusShapeFinder(grid, height, width, totalAsterisks);

        if (finder.containsCompletePlusShape()) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }
}

import java.io.*;
import java.util.*;

/**
 * This program determines if the '*' characters in a grid form a single '+' shape.
 * A '+' shape is defined by a central cell and four arms extending up, down, left, and right.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        PlusShapeDetector detector = new PlusShapeDetector();
        detector.solve(reader, writer);

        writer.flush();
        writer.close();
    }

    /**
     * Encapsulates the logic for detecting the plus shape within a grid.
     */
    static class PlusShapeDetector {

        public void solve(FastReader reader, PrintWriter writer) {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            if (rows <= 0 || cols <= 0) {
                writer.println("NO");
                return;
            }

            boolean[][] grid = new boolean[rows][cols];
            int totalStars = 0;

            // Load grid and count total stars
            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                for (int j = 0; j < cols; j++) {
                    if (line.charAt(j) == '*') {
                        grid[i][j] = true;
                        totalStars++;
                    }
                }
            }

            // A plus shape must have at least a center and 4 neighbors (5 stars minimum)
            if (totalStars < 5) {
                writer.println("NO");
                return;
            }

            // Step 1: Find a potential center. 
            // A center must have immediate neighbors in all 4 directions.
            int centerRow = -1;
            int centerCol = -1;

            for (int i = 1; i < rows - 1; i++) {
                for (int j = 1; j < cols - 1; j++) {
                    if (isCenter(grid, i, j)) {
                        centerRow = i;
                        centerCol = j;
                        break;
                    }
                }
                if (centerRow != -1) break;
            }

            // If no center is found, it cannot be a plus shape
            if (centerRow == -1) {
                writer.println("NO");
                return;
            }

            // Step 2: Trace the arms of the found center and count the stars in the plus
            int starsInPlus = countStarsInPlus(grid, centerRow, centerCol, rows, cols);

            // Step 3: If the stars in the plus equal the total stars in the grid, 
            // it means the shape is exactly one plus and nothing else.
            if (starsInPlus == totalStars) {
                writer.println("YES");
            } else {
                writer.println("NO");
            }
        }

        private boolean isCenter(boolean[][] grid, int r, int c) {
            return grid[r][c] && 
                   grid[r - 1][c] && grid[r + 1][c] && 
                   grid[r][c - 1] && grid[r][c + 1];
        }

        private int countStarsInPlus(boolean[][] grid, int r, int c, int rows, int cols) {
            int count = 1; // Start with the center cell

            // Trace Up
            for (int i = r - 1; i >= 0 && grid[i][c]; i--) count++;
            // Trace Down
            for (int i = r + 1; i < rows && grid[i][c]; i++) count++;
            // Trace Left
            for (int j = c - 1; j >= 0 && grid[r][j]; j--) count++;
            // Trace Right
            for (int j = c + 1; j < cols && grid[r][j]; j++) count++;

            return count;
        }
    }

    /**
     * Fast I/O utility for efficient reading of large inputs.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            return next != null ? Integer.parseInt(next) : 0;
        }
    }
}

import java.util.Scanner;

/**
 * This program determines if all '*' characters in a 2D grid form a single 
 * continuous "plus" shape.
 */
public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rowCount = scanner.nextInt();
        int colCount = scanner.nextInt();
        char[][] grid = new char[rowCount][colCount];

        for (int i = 0; i < rowCount; i++) {
            String inputLine = scanner.next();
            grid[i] = inputLine.toCharArray();
        }

        PlusShapeSolver solver = new PlusShapeSolver(grid);
        System.out.println(solver.solve());

        scanner.close();
    }
}

class PlusShapeSolver {

    private static final char TARGET_CHAR = '*';
    private static final String RESULT_YES = "YES";
    private static final String RESULT_NO = "NO";

    // Direction vectors for Up, Right, Down, Left
    private static final int[] ROW_OFFSETS = {-1, 0, 1, 0};
    private static final int[] COL_OFFSETS = {0, 1, 0, -1};

    private final char[][] grid;
    private final int rowCount;
    private final int colCount;

    public PlusShapeSolver(char[][] grid) {
        this.grid = grid;
        this.rowCount = grid.length;
        this.colCount = (rowCount > 0) ? grid[0].length : 0;
    }

    /**
     * Orchestrates the logic to check if all target characters form a single plus shape.
     */
    public String solve() {
        // A plus shape requires at least a 3x3 area to have a center and 4 neighbors
        if (rowCount < 3 || colCount < 3) {
            return RESULT_NO;
        }

        boolean[][] visited = new boolean[rowCount][colCount];
        boolean foundCenter = findAndMarkFirstPlusCenter(visited);

        if (!foundCenter) {
            return RESULT_NO;
        }

        return areAllStarsCovered(visited) ? RESULT_YES : RESULT_NO;
    }

    /**
     * Searches for the first cell that can act as the center of a plus shape
     * and marks its connected shape in the visited array.
     */
    private boolean findAndMarkFirstPlusCenter(boolean[][] visited) {
        for (int r = 0; r < rowCount; r++) {
            for (int c = 0; c < colCount; c++) {
                if (grid[r][c] == TARGET_CHAR && isPotentialCenter(r, c)) {
                    markPlusShape(r, c, visited);
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Checks if a cell is a valid center (has target neighbors in all 4 directions).
     */
    private boolean isPotentialCenter(int r, int c) {
        for (int i = 0; i < 4; i++) {
            int nr = r + ROW_OFFSETS[i];
            int nc = c + COL_OFFSETS[i];

            if (!isInBounds(nr, nc) || grid[nr][nc] != TARGET_CHAR) {
                return false;
            }
        }
        return true;
    }

    /**
     * Marks the center and all contiguous target characters in a straight line 
     * along the four cardinal directions.
     */
    private void markPlusShape(int centerR, int centerC, boolean[][] visited) {
        visited[centerR][centerC] = true;

        for (int i = 0; i < 4; i++) {
            int currR = centerR + ROW_OFFSETS[i];
            int currC = centerC + COL_OFFSETS[i];

            // Traverse in the current direction as long as we hit target characters
            while (isInBounds(currR, currC) && grid[currR][currC] == TARGET_CHAR) {
                visited[currR][currC] = true;
                currR += ROW_OFFSETS[i];
                currC += COL_OFFSETS[i];
            }
        }
    }

    /**
     * Verifies if every target character in the grid was reached by the marking process.
     */
    private boolean areAllStarsCovered(boolean[][] visited) {
        for (int r = 0; r < rowCount; r++) {
            for (int c = 0; c < colCount; c++) {
                if (grid[r][c] == TARGET_CHAR && !visited[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    private boolean isInBounds(int r, int c) {
        return r >= 0 && r < rowCount && c >= 0 && c < colCount;
    }
}

import java.util.Scanner;

/**
 * A utility to determine if a grid of cells contains exactly one star pattern
 * that covers all existing active cells (represented by 1).
 */
public class StarPatternSolver {

    private static final int CELL_ACTIVE = 1;
    private static final int CELL_EMPTY = 0;

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            scanner.nextLine(); // Consume newline

            int[][] grid = new int[rows][cols];
            boolean hasAnyActiveCells = false;

            for (int i = 0; i < rows; i++) {
                String line = scanner.nextLine();
                for (int j = 0; j < cols; j++) {
                    // Assuming '.' is empty and any other char is active (1)
                    grid[i][j] = (line.charAt(j) == '.') ? CELL_EMPTY : CELL_ACTIVE;
                    if (grid[i][j] == CELL_ACTIVE) {
                        hasAnyActiveCells = true;
                    }
                }
            }

            if (!hasAnyActiveCells) {
                System.out.println("NO");
                return;
            }

            if (isFullStarPattern(grid, rows, cols)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /**
     * Core logic to determine if the grid forms a single valid star.
     */
    private static boolean isFullStarPattern(int[][] grid, int rows, int cols) {
        boolean[][] visited = new boolean[rows][cols];
        boolean starFound = false;

        // 1. Find the first valid star center
        // A star center must have 4 neighbors and not be on the boundary
        outerLoop:
        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < cols - 1; c++) {
                if (isStarCenter(grid, r, c)) {
                    markStarArms(grid, r, c, visited);
                    starFound = true;
                    break outerLoop; // We only look for the first star as per original logic
                }
            }
        }

        // If no star was found, it's not a valid star pattern
        if (!starFound) {
            return false;
        }

        // 2. Verify if all active cells were part of the star
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == CELL_ACTIVE && !visited[r][c]) {
                    return false;
                }
            }
        }

        return true;
    }

    /**
     * Checks if the cell at (r, c) is the center of a '+' shape.
     */
    private static boolean isStarCenter(int[][] grid, int r, int c) {
        return grid[r][c] == CELL_ACTIVE &&
               grid[r - 1][c] == CELL_ACTIVE &&
               grid[r + 1][c] == CELL_ACTIVE &&
               grid[r][c - 1] == CELL_ACTIVE &&
               grid[r][c + 1] == CELL_ACTIVE;
    }

    /**
     * Marks the center and the four arms of the star as visited.
     */
    private static void markStarArms(int[][] grid, int r, int c, boolean[][] visited) {
        int rows = grid.length;
        int cols = grid[0].length;

        // Mark center
        visited[r][c] = true;

        // Directions: Up, Right, Down, Left
        int[] dr = {-1, 0, 1, 0};
        int[] dc = {0, 1, 0, -1};

        for (int i = 0; i < 4; i++) {
            int currR = r + dr[i];
            int currC = c + dc[i];

            // Traverse in the direction until we hit an empty cell or boundary
            while (isValid(grid, currR, currC) && grid[currR][currC] == CELL_ACTIVE) {
                visited[currR][currC] = true;
                currR += dr[i];
                currC += dc[i];
            }
        }
    }

    private static boolean isValid(int[][] grid, int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to determine if a grid contains a "star cross" pattern.
 * A star cross is a single star '*' such that all other stars in the grid 
 * lie on the same row or the same column as that star, forming a cross shape.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] gridData = reader.readGrid(rows, cols);

            StarGrid starGrid = new StarGrid(gridData);

            if (starGrid.hasPerfectStarCross()) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        } catch (IOException | NoSuchElementException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Represents the grid of characters and contains the logic to analyze star patterns.
     */
    static class StarGrid {
        private final char[][] grid;
        private final int rowCount;
        private final int colCount;
        private final int totalStars;

        // Directional offsets: {rowOffset, colOffset} for Up, Down, Left, Right
        private static final int[][] DIRECTIONS = {
            {-1, 0}, // Up
            {1, 0},  // Down
            {0, -1}, // Left
            {0, 1}   // Right
        };

        public StarGrid(char[][] grid) {
            this.grid = grid;
            this.rowCount = grid.length;
            this.colCount = grid[0].length;
            this.totalStars = countTotalStars();
        }

        /**
         * Scans the grid to find if any star forms a cross that accounts for all stars.
         * @return true if a perfect star cross is found.
         */
        public boolean hasPerfectStarCross() {
            // A cross requires at least one star in each direction, 
            // so the center cannot be on the edge.
            for (int r = 1; r < rowCount - 1; r++) {
                for (int c = 1; c < colCount - 1; c++) {
                    if (grid[r][c] == '*') {
                        if (isPerfectCross(r, c)) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        private boolean isPerfectCross(int centerRow, int centerCol) {
            int starsInCross = 1; // Count the center star itself
            boolean allDirectionsFilled = true;

            for (int[] dir : DIRECTIONS) {
                int countInDirection = countStarsInDirection(centerRow, centerCol, dir[0], dir[1]);

                if (countInDirection == 0) {
                    allDirectionsFilled = false;
                    break;
                }
                starsInCross += countInDirection;
            }

            // The pattern is perfect if all 4 directions have stars AND the 
            // total stars in the cross equals the total stars in the grid.
            return allDirectionsFilled && starsInCross == totalStars;
        }

        private int countStarsInDirection(int startRow, int startCol, int dRow, int dCol) {
            int count = 0;
            int currentRow = startRow + dRow;
            int currentCol = startCol + dCol;

            while (isWithinBounds(currentRow, currentCol) && grid[currentRow][currentCol] == '*') {
                count++;
                currentRow += dRow;
                currentCol += dCol;
            }
            return count;
        }

        private boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < rowCount && c >= 0 && c < colCount;
        }

        private int countTotalStars() {
            int count = 0;
            for (char[] row : grid) {
                for (char cell : row) {
                    if (cell == '*') count++;
                }
            }
            return count;
        }
    }

    /**
     * Utility class for fast I/O operations.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public char[][] readGrid(int rows, int cols) throws IOException {
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = next().toCharArray();
            }
            return grid;
        }
    }
}

import java.util.Scanner;

/**
 * A utility to detect if a grid contains exactly one cross pattern 
 * that, when removed, leaves the grid empty.
 */
public class CrossPatternDetector {

    /**
     * Represents a coordinate point in the 2D grid.
     */
    private static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        CrossPatternDetector detector = new CrossPatternDetector();
        System.out.println(detector.solve(grid) ? "YES" : "NO");

        scanner.close();
    }

    /**
     * Determines if the grid follows the specific cross-pattern rule.
     * 
     * @param grid The 2D character array to analyze.
     * @return true if exactly one cross pattern exists and its removal clears the grid.
     */
    public boolean solve(char[][] grid) {
        if (grid == null || grid.length == 0) return false;

        Point center = findSingleCrossCenter(grid);

        // The problem requires exactly one cross center to be valid
        if (center == null) {
            return false;
        }

        eraseCrossPattern(grid, center);

        return isGridEmptyOfStars(grid);
    }

    /**
     * Searches for a '*' that is surrounded by '*' in all four cardinal directions.
     * 
     * @param grid The grid to search.
     * @return A Point representing the center if exactly one is found, otherwise null.
     */
    private Point findSingleCrossCenter(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        int centerCount = 0;
        Point foundCenter = null;

        // Iterate through non-border cells as a center must have neighbors
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (isCrossCenter(grid, i, j)) {
                    centerCount++;
                    foundCenter = new Point(i, j);
                }
            }
        }

        return (centerCount == 1) ? foundCenter : null;
    }

    /**
     * Checks if a specific cell is the center of a cross pattern.
     */
    private boolean isCrossCenter(char[][] grid, int r, int c) {
        return grid[r][c] == '*' &&
               grid[r - 1][c] == '*' &&
               grid[r + 1][c] == '*' &&
               grid[r][c - 1] == '*' &&
               grid[r][c + 1] == '*';
    }

    /**
     * Erases the stars forming the cross pattern starting from the center.
     * The erasure continues in each direction as long as '*' characters are encountered.
     */
    private void eraseCrossPattern(char[][] grid, Point center) {
        int r = center.row;
        int c = center.col;
        int rows = grid.length;
        int cols = grid[0].length;

        grid[r][c] = '.';

        // Erase Left
        for (int j = c - 1; j >= 0 && grid[r][j] == '*'; j--) {
            grid[r][j] = '.';
        }
        // Erase Right
        for (int j = c + 1; j < cols && grid[r][j] == '*'; j++) {
            grid[r][j] = '.';
        }
        // Erase Up
        for (int i = r - 1; i >= 0 && grid[i][c] == '*'; i--) {
            grid[i][c] = '.';
        }
        // Erase Down
        for (int i = r + 1; i < rows && grid[i][c] == '*'; i++) {
            grid[i][c] = '.';
        }
    }

    /**
     * Checks if there are any '*' characters remaining in the grid.
     */
    private boolean isGridEmptyOfStars(char[][] grid) {
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '*') {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.io.*;
import java.util.*;

/**
 * CrossPatternSolver determines if all '*' cells in a grid can be covered 
 * by a single cross-shaped pattern (a center cell and its four straight arms).
 */
public class CrossPatternSolver {

    // Cardinal directions: Down, Up, Left, Right
    private static final int[] ROW_DIRS = {1, -1, 0, 0};
    private static final int[] COL_DIRS = {0, 0, -1, 1};

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final boolean[][] isCovered;

    public CrossPatternSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.isCovered = new boolean[rows][cols];
    }

    /**
     * Executes the logic to solve the grid problem.
     */
    public void solve() {
        boolean foundCenter = false;

        // 1. Search for the first valid cross center.
        // A valid center must be a '*' and have '*' neighbors in all 4 directions.
        outer:
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (isCrossCenter(i, j)) {
                    foundCenter = true;
                    markCrossPattern(i, j);
                    break outer;
                }
            }
        }

        // 2. If no center was found, we cannot cover the stars.
        // (Note: If the grid has no '*' at all, the original logic returns NO).
        if (!foundCenter) {
            System.out.println("NO");
            return;
        }

        // 3. Verify if all '*' cells in the grid were covered by the cross.
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (isStarCell(i, j) && !isCovered[i][j]) {
                    System.out.println("NO");
                    return;
                }
            }
        }

        System.out.println("YES");
    }

    /**
     * Checks if the given coordinates are within bounds and contain a '*' cell.
     */
    private boolean isStarCell(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] == '*';
    }

    /**
     * Checks if a cell is a valid center for a cross (it and its 4 neighbors are '*').
     */
    private boolean isCrossCenter(int r, int c) {
        if (!isStarCell(r, c)) {
            return false;
        }
        for (int i = 0; i < 4; i++) {
            if (!isStarCell(r + ROW_DIRS[i], c + COL_DIRS[i])) {
                return false;
            }
        }
        return true;
    }

    /**
     * Marks the center cell and the straight-line arms of the cross as covered.
     */
    private void markCrossPattern(int r, int c) {
        isCovered[r][c] = true;
        for (int i = 0; i < 4; i++) {
            int currR = r + ROW_DIRS[i];
            int currC = c + COL_DIRS[i];

            // Traverse in one direction as long as we find '*' cells.
            while (isStarCell(currR, currC)) {
                if (isCovered[currR][currC]) {
                    break; // Stop if we hit an already covered path
                }
                isCovered[currR][currC] = true;
                currR += ROW_DIRS[i];
                currC += COL_DIRS[i];
            }
        }
    }

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        String nStr = reader.next();
        if (nStr == null) return;

        int n = Integer.parseInt(nStr);
        int m = reader.nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = reader.next().toCharArray();
        }

        CrossPatternSolver solver = new CrossPatternSolver(n, m, grid);
        solver.solve();
    }

    /**
     * Fast I/O utility for reading input.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.PrintWriter;
import java.util.Scanner;

/**
 * A program to determine if all '*' characters in a grid form exactly one plus shape.
 */
public class Solution {

    private static final char ASTERISK = '*';

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter writer = new PrintWriter(System.out)) {

            if (!scanner.hasNextInt()) {
                return;
            }

            int height = scanner.nextInt();
            int width = scanner.nextInt();

            char[][] gridData = new char[height][width];
            for (int i = 0; i < height; i++) {
                gridData[i] = scanner.next().toCharArray();
            }

            Grid grid = new Grid(gridData);
            PlusAnalyzer analyzer = new PlusAnalyzer(grid);

            String result = analyzer.isSinglePlusShapePresent() ? "YES" : "NO";
            writer.println(result);
        }
    }

    /**
     * Represents the grid of characters and provides utility methods for inspection.
     */
    static class Grid {
        private final char[][] cells;
        private final int height;
        private final int width;
        private final int totalAsteriskCount;

        Grid(char[][] cells) {
            this.cells = cells;
            this.height = cells.length;
            this.width = cells.length > 0 ? cells[0].length : 0;
            this.totalAsteriskCount = countAsterisks();
        }

        private int countAsterisks() {
            int count = 0;
            for (int r = 0; r < height; r++) {
                for (int c = 0; c < width; c++) {
                    if (cells[r][c] == ASTERISK) {
                        count++;
                    }
                }
            }
            return count;
        }

        /**
         * Safely checks if a specific coordinate contains an asterisk.
         */
        boolean isAsterisk(int r, int c) {
            return r >= 0 && r < height && c >= 0 && c < width && cells[r][c] == ASTERISK;
        }

        int getHeight() { return height; }
        int getWidth() { return width; }
        int getTotalAsteriskCount() { return totalAsteriskCount; }
    }

    /**
     * Contains the logic to analyze the grid for a single plus shape.
     */
    static class PlusAnalyzer {
        private final Grid grid;

        PlusAnalyzer(Grid grid) {
            this.grid = grid;
        }

        /**
         * Validates if the entire set of asterisks in the grid forms exactly one plus.
         */
        boolean isSinglePlusShapePresent() {
            int centerR = -1;
            int centerC = -1;

            // 1. Find the first potential center (a cell with 4 immediate asterisk neighbors)
            outerLoop:
            for (int r = 1; r < grid.getHeight() - 1; r++) {
                for (int c = 1; c < grid.getWidth() - 1; c++) {
                    if (isValidCenter(r, c)) {
                        centerR = r;
                        centerC = c;
                        break outerLoop;
                    }
                }
            }

            // If no valid center is found, it's not a plus shape
            if (centerR == -1) {
                return false;
            }

            // 2. Calculate the size of the plus shape originating from this center
            int starsInPlus = calculatePlusSize(centerR, centerC);

            // 3. If the plus shape contains exactly the same number of stars as the grid,
            // then there are no extra stars and no other shapes.
            return starsInPlus == grid.getTotalAsteriskCount();
        }

        private boolean isValidCenter(int r, int c) {
            return grid.isAsterisk(r, c) &&
                   grid.isAsterisk(r - 1, c) &&
                   grid.isAsterisk(r + 1, c) &&
                   grid.isAsterisk(r, c - 1) &&
                   grid.isAsterisk(r, c + 1);
        }

        private int calculatePlusSize(int r, int c) {
            // The plus consists of the center + the length of 4 arms
            int up = countArmLength(r, c, -1, 0);
            int down = countArmLength(r, c, 1, 0);
            int left = countArmLength(r, c, 0, -1);
            int right = countArmLength(r, c, 0, 1);

            return 1 + up + down + left + right;
        }

        /**
         * Counts how many asterisks extend in a specific direction from the center.
         */
        private int countArmLength(int r, int c, int deltaR, int deltaC) {
            int count = 0;
            int currR = r + deltaR;
            int currC = c + deltaC;

            while (grid.isAsterisk(currR, currC)) {
                count++;
                currR += deltaR;
                currC += deltaC;
            }
            return count;
        }
    }
}

import java.util.Scanner;

/**
 * Analyzes a grid of characters to determine if all stars ('*') 
 * form a single, continuous cross shape.
 */
public class Div2_566B {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int rowCount = scanner.nextInt();
        int colCount = scanner.nextInt();

