/**
 * Contains the business logic for solving the star grid problem.
 */
class GridSolver {
    private final char[][] grid;
    private final int rowCount;
    private final int colCount;
    private final int totalStarCount;

    public GridSolver(char[][] grid, int rowCount, int colCount, int totalStarCount) {
        this.grid = grid;
        this.rowCount = rowCount;
        this.colCount = colCount;
        this.totalStarCount = totalStarCount;
    }

    /**
     * Determines if the grid contains a valid star cross.
     * @return true if a valid cross exists that accounts for all stars.
     */
    public boolean solve() {
        // A cross must have at least 5 stars (center + 4 directions)
        if (totalStarCount < 5) {
            return false;
        }

        for (int r = 0; r < rowCount; r++) {
            for (int c = 0; c < colCount; c++) {
                if (grid[r][c] == '*' && isCenterOfValidCross(r, c)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Checks if the star at (row, col) is the center of a cross that
     * includes every star present in the grid.
     */
    private boolean isCenterOfValidCross(int row, int col) {
        int upCount = countStarsInDirection(row, col, -1, 0);
        int downCount = countStarsInDirection(row, col, 1, 0);
        int leftCount = countStarsInDirection(row, col, 0, -1);
        int rightCount = countStarsInDirection(row, col, 0, 1);

        int starsInCross = 1 + upCount + downCount + leftCount + rightCount;

        boolean accountsForAllStars = (starsInCross == totalStarCount);
        boolean hasFourArms = (upCount > 0 && downCount > 0 && leftCount > 0 && rightCount > 0);

        return accountsForAllStars && hasFourArms;
    }

    /**
     * Counts consecutive stars starting from (startRow, startCol) in a specific direction.
     * 
     * @param startRow The starting row index.
     * @param startCol The starting column index.
     * @param rowDelta The direction of movement for the row (-1, 0, or 1).
     * @param colDelta The direction of movement for the column (-1, 0, or 1).
     * @return The number of consecutive stars found in that direction.
     */
    private int countStarsInDirection(int startRow, int startCol, int rowDelta, int colDelta) {
        int count = 0;
        int currentRow = startRow + rowDelta;
        int currentCol = startCol + colDelta;

        while (isWithinBounds(currentRow, currentCol) && grid[currentRow][currentCol] == '*') {
            count++;
            currentRow += rowDelta;
            currentCol += colDelta;
        }
        return count;
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rowCount && c >= 0 && c < colCount;
    }
}

