/**
 * Contains the domain logic for identifying a single star pattern.
 */
class StarPatternValidator {
    /**
     * Validates if the provided set of points forms exactly one star.
     * A star is defined as a center point and its four immediate cardinal neighbors.
     * 
     * @param points The set of all '*' coordinates found in the grid.
     * @return true if the points form exactly one star, false otherwise.
     */
    public boolean isExactlyOneStar(Set<Point> points) {
        // A single star pattern must consist of exactly 5 points.
        if (points.size() != 5) {
            return false;
        }

        // A valid star has one point that acts as a center for the other four.
        for (Point p : points) {
            if (isCenter(p, points)) {
                return true;
            }
        }

        return false;
    }

    /**
     * Checks if a specific point is the center of a 5-point cross.
     */
    private boolean isCenter(Point center, Set<Point> points) {
        int neighborsFound = 0;
        int[][] directions = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

        for (int[] dir : directions) {
            Point neighbor = new Point(center.getRow() + dir[0], center.getCol() + dir[1]);
            if (points.contains(neighbor)) {
                neighborsFound++;
            }
        }

        return neighborsFound == 4;
    }
}

