/**
 * This program analyzes a grid of stars ('*') to determine if there exists
 * a central star that forms a "cross" pattern (up, down, left, right) 
 * which accounts for all stars present in the grid.
 */
public class Main {

    public static void main(String[] args) {
        StarPatternApp app = new StarPatternApp();
        app.run();
    }
}

class StarPatternApp {
    private final FastReader reader = new FastReader(System.in);
    private final PrintWriter writer = new PrintWriter(System.out);

    /**
     * Orchestrates the execution of the program.
     */
    public void run() {
        try {
            int height = reader.nextInt();
            int width = reader.nextInt();

            GridPatternAnalyzer analyzer = new GridPatternAnalyzer(height, width, reader);
            boolean isPatternFound = analyzer.findCrossPattern();

            writer.println(isPatternFound ? "YES" : "NO");
        } catch (IOException | NoSuchElementException e) {
            writer.println("Error reading input: " + e.getMessage());
        } finally {
            writer.flush();
            writer.close();
        }
    }
}

/**
 * Handles the core business logic for analyzing the grid.
 */
class GridPatternAnalyzer {
    private final int height;
    private final int width;
    private final boolean[][] grid;
    private final int totalStarCount;

    public GridPatternAnalyzer(int height, int width, FastReader reader) throws IOException {
        this.height = height;
        this.width = width;
        this.grid = new boolean[height][width];
        int count = 0;

        for (int i = 0; i < height; i++) {
            String row = reader.next();
            for (int j = 0; j < width; j++) {
                if (row.charAt(j) == '*') {
                    grid[i][j] = true;
                    count++;
                }
            }
        }
        this.totalStarCount = count;
    }

    /**
     * Iterates through every star to see if it serves as the center of a perfect cross.
     * A perfect cross must have arms of length >= 1 in all four directions and
     * encompass all stars in the grid.
     */
    public boolean findCrossPattern() {
        for (int i = 0; i < height; i++) {
            for (int j = 0; j < width; j++) {
                if (grid[i][j]) {
                    if (isCenterOfFullCross(i, j)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    private boolean isCenterOfFullCross(int row, int col) {
        int up = countContiguousStars(row, col, -1, 0);
        int down = countContiguousStars(row, col, 1, 0);
        int left = countContiguousStars(row, col, 0, -1);
        int right = countContiguousStars(row, col, 0, 1);

        // Check if all arms have at least one star
        boolean allArmsExist = (up >= 1 && down >= 1 && left >= 1 && right >= 1);

        // Check if the total number of stars in the cross equals the total stars in the grid
        // The +1 accounts for the center star itself
        boolean coversAllStars = (up + down + left + right + 1 == totalStarCount);

        return allArmsExist && coversAllStars;
    }

    /**
     * Counts how many stars are contiguous in a specific direction from a starting point.
     */
    private int countContiguousStars(int startRow, int startCol, int rowDir, int colDir) {
        int count = 0;
        int r = startRow + rowDir;
        int c = startCol + colDir;

        while (r >= 0 && r < height && c >= 0 && c < width && grid[r][c]) {
            count++;
            r += rowDir;
            c += colDir;
        }
        return count;
    }
}

