/**
 * A program to determine if a grid of '*' characters can be completely cleared
 * by finding a single "center" point that clears its connected horizontal and vertical lines.
 */
public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        char[][] grid = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        GridSolver solver = new GridSolver(rows, cols, grid);
        if (solver.canClearGrid()) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }
}

class GridSolver {
    private final int rows;
    private final int cols;
    private final char[][] grid;

    public GridSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
    }

    /**
     * Attempts to find a center point that, when cleared, leaves no stars in the grid.
     * 
     * @return true if a center is found and the grid becomes empty; false otherwise.
     */
    public boolean canClearGrid() {
        // A center must have neighbors, so we skip the outer boundaries.
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (isCenter(i, j)) {
                    clearCrossPattern(i, j);
                    return isGridEmpty();
                }
            }
        }
        return false;
    }

    /**
     * Checks if the cell at (r, c) is a '*' and has '*' neighbors in all 4 cardinal directions.
     */
    private boolean isCenter(int r, int c) {
        return grid[r][c] == '*' &&
               grid[r - 1][c] == '*' &&
               grid[r + 1][c] == '*' &&
               grid[r][c - 1] == '*' &&
               grid[r][c + 1] == '*';
    }

    /**
     * Clears the continuous line of '*' characters in all four directions 
     * starting from the given center (r, c).
     */
    private void clearCrossPattern(int r, int c) {
        grid[r][c] = '.';

        // Clear Up
        for (int i = r - 1; i >= 0 && grid[i][c] == '*'; i--) {
            grid[i][c] = '.';
        }
        // Clear Down
        for (int i = r + 1; i < rows && grid[i][c] == '*'; i++) {
            grid[i][c] = '.';
        }
        // Clear Left
        for (int j = c - 1; j >= 0 && grid[r][j] == '*'; j--) {
            grid[r][j] = '.';
        }
        // Clear Right
        for (int j = c + 1; j < cols && grid[r][j] == '*'; j++) {
            grid[r][j] = '.';
        }
    }

    /**
     * Checks if there are any '*' characters remaining in the grid.
     */
    private boolean isGridEmpty() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*') {
                    return false;
                }
            }
        }
        return true;
    }
}

