/**
 * The Picture class represents the grid and contains the logic 
 * for identifying and manipulating star patterns.
 */
class Picture {
    private static final int[][] DIRECTIONS = {
        {-1, 0}, // Up
        {1, 0},  // Down
        {0, -1}, // Left
        {0, 1}   // Right
    };

    private final char[][] grid;
    private final int rowCount;
    private final int colCount;

    public Picture(int rows, int cols) {
        this.rowCount = rows;
        this.colCount = cols;
        this.grid = new char[rows][cols];
        initializeGrid('.');
    }

    private void initializeGrid(char defaultChar) {
        for (int i = 0; i < rowCount; i++) {
            for (int j = 0; j < colCount; j++) {
                grid[i][j] = defaultChar;
            }
        }
    }

    /**
     * Populates a specific row in the grid.
     * @param rowIndex The index of the row to set.
     * @param rowData The string content of the row.
     */
    public void setRow(int rowIndex, String rowData) {
        if (rowIndex < 0 || rowIndex >= rowCount) {
            return;
        }
        char[] chars = rowData.toCharArray();
        for (int j = 0; j < colCount && j < chars.length; j++) {
            grid[rowIndex][j] = chars[j];
        }
    }

    /**
     * Iterates through the grid to find all plus shapes.
     * When a plus is found, it is removed from the grid.
     * 
     * @return The number of plus shapes found.
     */
    public int findAndRemovePluses() {
        int count = 0;
        for (int r = 0; r < rowCount; r++) {
            for (int c = 0; c < colCount; c++) {
                if (isCenterOfPlus(r, c)) {
                    count++;
                    clearPlusShape(r, c);
                }
            }
        }
        return count;
    }

    /**
     * Scans the grid to see if any stars ('*') remain.
     * @return true if stars remain, false otherwise.
     */
    public boolean hasRemainingStars() {
        for (int r = 0; r < rowCount; r++) {
            for (int c = 0; c < colCount; c++) {
                if (grid[r][c] == '*') {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * A plus center is defined as a star that has immediate star neighbors 
     * in all four cardinal directions.
     */
    private boolean isCenterOfPlus(int r, int c) {
        return isStar(r, c) &&
               isStar(r - 1, c) &&
               isStar(r + 1, c) &&
               isStar(r, c - 1) &&
               isStar(r, c + 1);
    }

    /**
     * Removes the center star and all connected stars in the four cardinal directions.
     */
    private void clearPlusShape(int r, int c) {
        grid[r][c] = '.'; // Remove the center
        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            // Traverse and remove the entire arm in this direction
            while (isStar(nr, nc)) {
                grid[nr][nc] = '.';
                nr += dir[0];
                nc += dir[1];
            }
        }
    }

    /**
     * Helper to check if a coordinate is within bounds and contains a star.
     */
    private boolean isStar(int r, int c) {
        return r >= 0 && r < rowCount && 
               c >= 0 && c < colCount && 
               grid[r][c] == '*';
    }
}

