/**
 * Solves the problem of determining if all stars in a grid can be covered
 * by a single point radiating in four directions.
 */
class StarCoverageSolver {
    private static final int[][] DIRECTIONS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    private final FastReader reader;
    private final FastWriter writer;

    public StarCoverageSolver(FastReader reader, FastWriter writer) {
        this.reader = reader;
        this.writer = writer;
    }

    public void solve() {
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        boolean[][] grid = new boolean[rows][cols];
        boolean[][] visited = new boolean[rows][cols];
        int starCount = 0;

        // Read the grid
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (reader.nextChar() == '*') {
                    grid[i][j] = true;
                    starCount++;
                }
            }
        }

        // Attempt to find a "seed" cell that can cover stars in 4 directions
        findAndMarkCoverage(rows, cols, grid, visited);

        // Check if any star remains unvisited
        if (hasUncoveredStars(rows, cols, grid, visited)) {
            writer.println("NO");
            return;
        }

        // The original logic requires at least one star to return YES
        if (starCount > 0) {
            writer.println("YES");
        } else {
            writer.println("NO");
        }
    }

    private void findAndMarkCoverage(int rows, int cols, boolean[][] grid, boolean[][] visited) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                // Only attempt to use a star cell as a potential seed
                if (grid[i][j] && !visited[i][j]) {
                    if (isPotentialSeed(i, j, rows, cols, grid)) {
                        markRadiatingCoverage(i, j, rows, cols, grid, visited);
                        return; // Found the seed, no need to check other cells
                    }
                }
            }
        }
    }

    private boolean isPotentialSeed(int r, int c, int rows, int cols, boolean[][] grid) {
        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            if (isOutOfBounds(nr, nc, rows, cols) || !grid[nr][nc]) {
                return false;
            }
        }
        return true;
    }

    private void markRadiatingCoverage(int r, int c, int rows, int cols, boolean[][] grid, boolean[][] visited) {
        visited[r][c] = true;
        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            // Continue moving in the direction while we encounter stars
            while (!isOutOfBounds(nr, nc, rows, cols) && grid[nr][nc]) {
                visited[nr][nc] = true;
                nr += dir[0];
                nc += dir[1];
            }
        }
    }

    private boolean hasUncoveredStars(int rows, int cols, boolean[][] grid, boolean[][] visited) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] && !visited[i][j]) {
                    return true;
                }
            }
        }
        return false;
    }

    private boolean isOutOfBounds(int r, int c, int rows, int cols) {
        return r < 0 || r >= rows || c < 0 || c >= cols;
    }
}

/**
 * Optimized reader for fast input processing.
 */
class FastReader {
    private final InputStream stream;
    private final byte[] buffer = new byte[1024];
    private int curChar;
    private int numChars;

    public FastReader(InputStream stream) {
        this.stream = stream;
    }

    private int read() {
        if (numChars == -1) throw new InputMismatchException();
        if (curChar >= numChars) {
            curChar = 0;
            try {
                numChars = stream.read(buffer);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (numChars <= 0) return -1;
        }
        return buffer[curChar++];
    }

    public int nextInt() {
        int c = read();
        while (isWhitespace(c)) c = read();
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        int res = 0;
        do {
            if (c < '0' || c > '9') throw new InputMismatchException();
            res = res * 10 + (c - '0');
            c = read();
        } while (!isWhitespace(c));
        return res * sgn;
    }

    public char nextChar() {
        int c = read();
        while (isWhitespace(c)) c = read();
        return (char) c;
    }

    private boolean isWhitespace(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }
}

