import java.util.*;
import java.io.*;

/**
 * The CrossShapeDetector class determines if all '*' characters in a given 2D grid
 * form a single, continuous cross shape. A cross is defined as a central 
 * cell with four arms extending up, down, left, and right.
 */
public class CrossShapeDetector {

    private static final String YES = "YES";
    private static final String NO = "NO";

    public static void main(String[] args) {
        new CrossShapeDetector().solve();
    }

    /**
     * Reads input and executes the core logic to detect a cross shape.
     */
    public void solve() {
        FastReader sc = new FastReader();

        int rows = sc.nextInt();
        int cols = sc.nextInt();

        // Basic validation for dimensions
        if (rows <= 0 || cols <= 0) {
            System.out.println(NO);
            return;
        }

        int[][] grid = new int[rows][cols];
        int totalStarsCount = 0;

        // Populate the grid and count the total number of '*' characters
        for (int i = 0; i < rows; i++) {
            String line = sc.next();
            for (int j = 0; j < cols; j++) {
                if (line.charAt(j) == '*') {
                    grid[i][j] = 1;
                    totalStarsCount++;
                }
            }
        }

        int centerRow = -1;
        int centerCol = -1;

        // Find the center of the potential cross.
        // According to the logic, a center cannot be on the grid boundary 
        // and must have 4 adjacent '*' neighbors.
        findCenter:
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (grid[i][j] == 1 &&
                    grid[i - 1][j] == 1 && grid[i + 1][j] == 1 &&
                    grid[i][j - 1] == 1 && grid[i][j + 1] == 1) {
                    centerRow = i;
                    centerCol = j;
                    break findCenter;
                }
            }
        }

        // If no cell satisfies the center condition, it's not a valid cross.
        if (centerRow == -1) {
            System.out.println(NO);
            return;
        }

        // Count the number of '*' cells that belong to the continuous cross arms
        // starting from the identified center.
        int crossStarsCount = 1; // Start with the center cell itself

        // Expand and count stars in the 4 cardinal directions
        // Up
        for (int i = centerRow - 1; i >= 0 && grid[i][centerCol] == 1; i--) {
            crossStarsCount++;
        }
        // Down
        for (int i = centerRow + 1; i < rows && grid[i][centerCol] == 1; i++) {
            crossStarsCount++;
        }
        // Left
        for (int j = centerCol - 1; j >= 0 && grid[centerRow][j] == 1; j--) {
            crossStarsCount++;
        }
        // Right
        for (int j = centerCol + 1; j < cols && grid[centerRow][j] == 1; j++) {
            crossStarsCount++;
        }

        // If the count of stars in this continuous cross matches the total stars
        // found in the grid, then all stars form exactly one cross shape.
        if (crossStarsCount == totalStarsCount) {
            System.out.println(YES);
        } else {
            System.out.println(NO);
        }
    }

    /**
     * FastReader provides efficient input parsing using BufferedReader and StringTokenizer.
     */
    static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

