/**
 * Application to validate if a grid of characters forms a specific 
 * geometric pattern of stars.
 */
public class ShapeValidatorApp {

    private static final char STAR = '*';
    private static final char EMPTY = '.';

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        try {
            int rows = reader.nextInt();
            int columns = reader.nextInt();

            Grid grid = new Grid(rows, columns, reader);
            ShapeAnalyzer analyzer = new ShapeAnalyzer(grid);

            if (analyzer.isValidPattern()) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        } catch (IOException | IllegalArgumentException e) {
            System.out.println("NO");
        }
    }

    /**
     * Handles the core logic for analyzing the star pattern in the grid.
     */
    static class ShapeAnalyzer {
        private final Grid grid;
        private int junctionRow = -1;
        private int junctionCol = -1;
        private boolean junctionFound = false;
        private boolean hasStarsBelowJunction = false;

        public ShapeAnalyzer(Grid grid) {
            this.grid = grid;
        }

        public boolean isValidPattern() {
            // 1. Find the first star in the grid (row-major order)
            int[] firstStar = grid.findFirstStar();
            if (firstStar == null) {
                return false;
            }

            int firstStarRow = firstStar[0];
            int firstStarCol = firstStar[1];

            // 2. Validate initial boundary and structural constraints
            if (!isWithinValidBounds(firstStarRow, firstStarCol)) {
                return false;
            }

            if (grid.hasStarsToTheRight(firstStarRow, firstStarCol)) {
                return false;
            }

            if (!grid.isStarAt(firstStarRow + 1, firstStarCol)) {
                return false;
            }

            // 3. Clear the first star and analyze the vertical stem
            grid.setCell(firstStarRow, firstStarCol, EMPTY);
            if (!processVerticalStem(firstStarRow + 1, firstStarCol)) {
                return false;
            }

            // 4. Validate the horizontal bar if a junction was found
            if (junctionFound) {
                if (!processHorizontalBar(junctionRow, junctionCol)) {
                    return false;
                }
            }

            // 5. Final check: ensure no stray stars remain in the grid
            return !grid.hasAnyStarsLeft() && hasStarsBelowJunction;
        }

        private boolean isWithinValidBounds(int r, int c) {
            // Logic preserved from original: check if star is on boundary 
            // or on the second to last row.
            return r > 0 && r < grid.getRows() - 1 && 
                   c > 0 && c < grid.getCols() - 1 && 
                   r != grid.getRows() - 2;
        }

        private boolean processVerticalStem(int startRow, int col) {
            boolean gapInStemFound = false;

            for (int r = startRow; r < grid.getRows(); r++) {
                if (grid.isStarAt(r, col)) {
                    // If we found a star after a gap, the stem is broken
                    if (gapInStemFound) return false;

                    // Check if this star acts as a junction (has left and right neighbors)
                    if (grid.isJunction(r, col)) {
                        if (junctionFound) return false; // Only one junction allowed

                        junctionRow = r;
                        junctionCol = col;
                        junctionFound = true;
                    } else if (grid.isSingleSideStar(r, col)) {
                        // If it has only one neighbor, it's an invalid junction type
                        return false;
                    }

                    // If we encounter a star after the junction has been established, 
                    // set the blue flag logic
                    if (junctionFound && r > junctionRow) {
                        hasStarsBelowJunction = true;
                    }

                    grid.setCell(r, col, EMPTY);
                } else {
                    gapInStemFound = true;
                }
            }
            return true;
        }

        private boolean processHorizontalBar(int row, int col) {
            // Validate Left side of the bar
            boolean gapLeft = false;
            for (int c = col - 1; c >= 0; c--) {
                if (grid.isStarAt(row, c)) {
                    if (gapLeft) return false;
                    grid.setCell(row, c, EMPTY);
                } else {
                    gapLeft = true;
                }
            }

            // Validate Right side of the bar
            boolean gapRight = false;
            for (int c = col + 1; c < grid.getCols(); c++) {
                if (grid.isStarAt(row, c)) {
                    if (gapRight) return false;
                    grid.setCell(row, c, EMPTY);
                } else {
                    gapRight = true;
                }
            }
            return true;
        }
    }

    /**
     * Represents the 2D grid of characters.
     */
    static class Grid {
        private final int rows;
        private final int cols;
        private final char[][] matrix;

        public Grid(int rows, int cols, FastReader reader) throws IOException {
            this.rows = rows;
            this.cols = cols;
            this.matrix = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                matrix[i] = reader.next().toCharArray();
            }
        }

        public int getRows() { return rows; }
        public int getCols() { return cols; }

        public boolean isStarAt(int r, int c) {
            if (r < 0 || r >= rows || c < 0 || c >= cols) return false;
            return matrix[r][c] == STAR;
        }

        public void setCell(int r, int c, char val) {
            matrix[r][c] = val;
        }

        public int[] findFirstStar() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (matrix[i][j] == STAR) return new int[]{i, j};
                }
            }
            return null;
        }

        public boolean hasStarsToTheRight(int r, int c) {
            for (int j = c + 1; j < cols; j++) {
                if (matrix[r][j] == STAR) return true;
            }
            return false;
        }

        public boolean isJunction(int r, int c) {
            return isStarAt(r, c - 1) && isStarAt(r, c + 1);
        }

        public boolean isSingleSideStar(int r, int c) {
            boolean left = isStarAt(r, c - 1);
            boolean right = isStarAt(r, c + 1);
            return (left ^ right); // XOR: true if exactly one is true
        }

        public boolean hasAnyStarsLeft() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (matrix[i][j] == STAR) return true;
                }
            }
            return false;
        }
    }

    /**
     * Utility class for fast input reading.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            this.reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return "";
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * Main class that orchestrates the execution of the Grid Problem solver.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        try {
            // Read grid dimensions
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            if (rows <= 0 || cols <= 0) {
                System.out.println("NO");
                return;
            }

            // Read the grid layout
            char[][] grid = reader.readGrid(rows, cols);

            // Execute the solver logic
            GridSolver solver = new GridSolver(grid);
            if (solver.solve()) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }

        } catch (Exception e) {
            // In a production environment, use a logger. 
            // For this logic, we exit gracefully.
        }
    }

    /**
     * Handles high-performance input reading.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            return next == null ? -1 : Integer.parseInt(next);
        }

        public char[][] readGrid(int rows, int cols) {
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = next();
                if (line != null) {
                    grid[i] = line.toCharArray();
                }
            }
            return grid;
        }
    }

    /**
     * Contains the business logic for solving the grid problem.
     */
    static class GridSolver {
        private final char[][] grid;
        private final int rows;
        private final int cols;

        // Constants for grid cell types
        private static final char STAR = '*';
        private static final char DOT = '.';
        private static final char FILLED = '#';

        public GridSolver(char[][] grid) {
            this.grid = grid;
            this.rows = grid.length;
            this.cols = grid[0].length;
        }

        /**
         * Solves the problem: finds the first star surrounded by non-dots,
         * fills its cross, and checks if all stars are converted.
         */
        public boolean solve() {
            // Search for a star in the interior that is surrounded by non-dots
            for (int i = 1; i < rows - 1; i++) {
                for (int j = 1; j < cols - 1; j++) {
                    if (grid[i][j] == STAR && isSurroundedByNonDots(i, j)) {
                        fillCross(i, j);
                        return isAllStarsConverted();
                    }
                }
            }
            return false;
        }

        /**
         * Checks if the cardinal neighbors (Up, Down, Left, Right) are not empty spaces.
         */
        private boolean isSurroundedByNonDots(int r, int c) {
            return grid[r - 1][c] != DOT &&
                   grid[r + 1][c] != DOT &&
                   grid[r][c - 1] != DOT &&
                   grid[r][c + 1] != DOT;
        }

        /**
         * Converts the horizontal and vertical cross containing (r, c) into FILLED cells.
         */
        private void fillCross(int r, int c) {
            // Directions: Up, Down, Left, Right
            fillDirection(r, c, -1, 0);
            fillDirection(r, c, 1, 0);
            fillDirection(r, c, 0, -1);
            fillDirection(r, c, 0, 1);
        }

        /**
         * Travels in a given direction and converts stars to filled cells until a dot is hit.
         */
        private void fillDirection(int r, int c, int dr, int dc) {
            int currR = r;
            int currC = c;

            while (currR >= 0 && currR < rows && currC >= 0 && currC < cols) {
                if (grid[currR][currC] == DOT) {
                    break;
                }
                if (grid[currR][currC] == STAR) {
                    grid[currR][currC] = FILLED;
                }
                // If cell is already FILLED, we simply continue through it
                currR += dr;
                currC += dc;
            }
        }

        /**
         * Validates if the entire grid has been cleared of all '*' characters.
         */
        private boolean isAllStarsConverted() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == STAR) {
                        return false;
                    }
                }
            }
            return true;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * A utility to detect if all '*' characters in a grid form a single, perfect cross shape.
 * A perfect cross is defined as a center star with at least one star extending 
 * in all four cardinal directions, such that all stars in the grid are part of this cross.
 */
public class CrossPatternSolver {

    // Direction vectors for Up, Down, Left, and Right movements
    private static final int[] ROW_DIRECTIONS = {-1, 1, 0, 0};
    private static final int[] COL_DIRECTIONS = {0, 0, -1, 1};

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        CrossPatternSolver solver = new CrossPatternSolver();
        solver.run(reader);
    }

    /**
     * Orchestrates the reading, processing, and output of the program.
     */
    public void run(FastReader reader) {
        int height = reader.nextInt();
        int width = reader.nextInt();

        if (height <= 0 || width <= 0) {
            System.out.println("NO");
            return;
        }

        boolean[][] grid = new boolean[height][width];
        int totalStars = 0;

        // Parse the grid and count total stars
        for (int i = 0; i < height; i++) {
            String rowString = reader.next();
            if (rowString == null) break;
            for (int j = 0; j < width; j++) {
                if (rowString.charAt(j) == '*') {
                    grid[i][j] = true;
                    totalStars++;
                }
            }
        }

        if (isCrossPattern(grid, height, width, totalStars)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Iterates through the grid to find if any star acts as the center of a perfect cross.
     */
    private boolean isCrossPattern(boolean[][] grid, int height, int width, int totalStars) {
        // A cross requires at least a center and 4 arms (minimum 5 stars)
        if (totalStars < 5) {
            return false;
        }

        for (int i = 0; i < height; i++) {
            for (int j = 0; j < width; j++) {
                if (grid[i][j]) {
                    if (checkIfStarIsCenter(grid, i, j, height, width, totalStars)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Validates if the star at (row, col) is the center of a cross containing all stars in the grid.
     */
    private boolean checkIfStarIsCenter(boolean[][] grid, int row, int col, int height, int width, int totalStars) {
        int totalArmStars = 0;

        for (int d = 0; d < 4; d++) {
            int armLength = countConsecutiveStars(grid, row, col, ROW_DIRECTIONS[d], COL_DIRECTIONS[d], height, width);

            // A perfect cross must have arms in all four directions
            if (armLength == 0) {
                return false;
            }
            totalArmStars += armLength;
        }

        // The star is a valid center if the center + all arm stars account for all stars in the grid
        return (1 + totalArmStars) == totalStars;
    }

    /**
     * Counts how many consecutive stars exist in a specific direction.
     */
    private int countConsecutiveStars(boolean[][] grid, int row, int col, int dr, int dc, int height, int width) {
        int count = 0;
        int r = row + dr;
        int c = col + dc;

        while (r >= 0 && r < height && c >= 0 && c < width && grid[r][c]) {
            count++;
            r += dr;
            c += dc;
        }
        return count;
    }

    /**
     * Fast I/O utility for efficient reading of large input datasets.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            return next != null ? Integer.parseInt(next) : 0;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver to determine if a grid of characters can be cleared by 
 * identifying a single "cross" pattern and removing its contiguous 
 * horizontal and vertical lines.
 */
public class GridPatternSolver {

    private static final int EMPTY = 0;
    private static final int FILLED = 1;

    public static void main(String[] args) {
        FastReader in = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            int rows = in.nextInt();
            int cols = in.nextInt();
            int[][] grid = new int[rows][cols];

            // Initialize grid based on input
            for (int i = 0; i < rows; i++) {
                String line = in.next();
                if (line == null) break;
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = (line.charAt(j) == '.') ? EMPTY : FILLED;
                }
            }

            if (solve(grid, rows, cols)) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.close();
        }
    }

    /**
     * Orchestrates the logic to find a cross, clear it, and verify if the grid is empty.
     * 
     * @return true if a cross was found and the entire grid was cleared.
     */
    private static boolean solve(int[][] grid, int rows, int cols) {
        int centerRow = -1;
        int centerCol = -1;
        boolean crossFound = false;

        // 1. Search for the first occurrence of a cross pattern
        // A cross requires at least one cell of padding on all sides
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (isCrossCenter(grid, i, j)) {
                    crossFound = true;
                    centerRow = i;
                    centerCol = j;
                    break;
                }
            }
            if (crossFound) break;
        }

        // If no cross pattern exists, the grid cannot be cleared via this rule
        if (!crossFound) {
            return false;
        }

        // 2. Clear the contiguous horizontal and vertical lines containing the center
        clearContiguousLines(grid, centerRow, centerCol, rows, cols);

        // 3. Return true only if no filled cells remain in the grid
        return !hasRemainingFilledCells(grid, rows, cols);
    }

    /**
     * Checks if the cell at (r, c) is the center of a '+' shaped pattern.
     */
    private static boolean isCrossCenter(int[][] grid, int r, int c) {
        return grid[r][c] == FILLED &&
               grid[r - 1][c] == FILLED &&
               grid[r + 1][c] == FILLED &&
               grid[r][c - 1] == FILLED &&
               grid[r][c + 1] == FILLED;
    }

    /**
     * Finds the contiguous segment of FILLED cells in the same row and column 
     * as the center and sets them to EMPTY.
     */
    private static void clearContiguousLines(int[][] grid, int r, int c, int rows, int cols) {
        // Determine horizontal range of the contiguous line
        int cStart = c;
        while (cStart > 0 && grid[r][cStart - 1] == FILLED) {
            cStart--;
        }
        int cEnd = c;
        while (cEnd < cols - 1 && grid[r][cEnd + 1] == FILLED) {
            cEnd++;
        }

        // Determine vertical range of the contiguous line
        int rStart = r;
        while (rStart > 0 && grid[rStart - 1][c] == FILLED) {
            rStart--;
        }
        int rEnd = r;
        while (rEnd < rows - 1 && grid[rEnd + 1][c] == FILLED) {
            rEnd++;
        }

        // Clear the horizontal line
        for (int j = cStart; j <= cEnd; j++) {
            grid[r][j] = EMPTY;
        }
        // Clear the vertical line
        for (int i = rStart; i <= rEnd; i++) {
            grid[i][c] = EMPTY;
        }
    }

    /**
     * Scans the grid to see if any FILLED cells remain.
     */
    private static boolean hasRemainingFilledCells(int[][] grid, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == FILLED) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Utility class for fast input reading.
     */
    static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

/**
 * A program that detects if a grid contains exactly one "asterisk pattern" center.
 * A valid center is the middle of a '+' shape of asterisks where all asterisks 
 * in the grid are confined to that center's row and column, and both the row 
 * and column segments are contiguous.
 */
public class AsteriskPatternDetector {

    private static final char TARGET = '*';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        char[][] grid = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        int validCenterCount = countValidCenters(grid, rows, cols);

        // The problem requires exactly one valid pattern center to return YES
        System.out.println(validCenterCount == 1 ? "YES" : "NO");

        scanner.close();
    }

    /**
     * Iterates through the grid to find cells that satisfy the pattern requirements.
     */
    private static int countValidCenters(char[][] grid, int rows, int cols) {
        int count = 0;

        // A center must not be on the boundary to form a '+' shape
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (isPartOfPlusShape(grid, i, j)) {
                    if (isValidCenter(grid, i, j, rows, cols)) {
                        count++;
                    }
                }
            }
        }
        return count;
    }

    /**
     * Checks if the cell (r, c) is the center of a '+' shape of asterisks.
     */
    private static boolean isPartOfPlusShape(char[][] grid, int r, int c) {
        return grid[r][c] == TARGET &&
               grid[r - 1][c] == TARGET &&
               grid[r + 1][c] == TARGET &&
               grid[r][c - 1] == TARGET &&
               grid[r][c + 1] == TARGET;
    }

    /**
     * Validates if a candidate center (r, c) meets the global grid constraints:
     * 1. All asterisks in the grid must lie on either row 'r' or column 'c'.
     * 2. Asterisks in row 'r' must be contiguous.
     * 3. Asterisks in column 'c' must be contiguous.
     */
    private static boolean isValidCenter(char[][] grid, int r, int c, int rows, int cols) {
        // Rule 1: All '*' must be in either row r or column c
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == TARGET && i != r && j != c) {
                    return false;
                }
            }
        }

        // Rule 2: Asterisks in the center row must be contiguous
        if (!isContiguous(grid[r])) {
            return false;
        }

        // Rule 3: Asterisks in the center column must be contiguous
        char[] column = new char[rows];
        for (int i = 0; i < rows; i++) {
            column[i] = grid[i][c];
        }
        return isContiguous(column);
    }

    /**
     * Helper method to check if all occurrences of the TARGET character 
     * in a given array form a single contiguous block.
     */
    private static boolean isContiguous(char[] line) {
        int firstIndex = -1;
        int lastIndex = -1;
        int targetCount = 0;

        for (int i = 0; i < line.length; i++) {
            if (line[i] == TARGET) {
                if (firstIndex == -1) {
                    firstIndex = i;
                }
                lastIndex = i;
                targetCount++;
            }
        }

        // If no asterisks are found, it is technically contiguous
        if (targetCount == 0) {
            return true;
        }

        // If the distance between first and last index matches the count, 
        // there are no gaps.
        return (lastIndex - firstIndex + 1) == targetCount;
    }
}

import java.util.Scanner;

/**
 * A utility to detect if a grid of characters contains a single, 
 * perfect "cross" pattern that accounts for all '*' characters.
 */
public class CrossPatternChecker {

    private static final char STAR = '*';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        char[][] grid = new char[rows][cols];
        int totalStars = 0;

        // Read the grid and count the total number of '*' characters
        for (int i = 0; i < rows; i++) {
            String rowString = scanner.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = rowString.charAt(j);
                if (grid[i][j] == STAR) {
                    totalStars++;
                }
            }
        }

        // Check if the stars form a perfect, single cross
        if (isAllStarsPartOfSingleCross(grid, rows, cols, totalStars)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Determines if the grid contains a single cross pattern that accounts 
     * for every '*' character present in the grid.
     *
     * @param grid       The character grid.
     * @param rows       Number of rows in the grid.
     * @param cols       Number of columns in the grid.
     * @param totalStars The total number of '*' characters found in the grid.
     * @return true if a single cross consumes all stars; false otherwise.
     */
    private static boolean isAllStarsPartOfSingleCross(char[][] grid, int rows, int cols, int totalStars) {
        // A center of a cross must have neighbors on all sides, 
        // so it cannot be located on the boundary of the grid.
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (isPotentialCenter(grid, i, j)) {
                    int crossSize = calculateCrossSize(grid, i, j);

                    // If we find a potential center, we check if its cross size 
                    // matches the total star count. The original logic stops 
                    // at the first valid center found.
                    return crossSize == totalStars;
                }
            }
        }
        return false;
    }

    /**
     * Checks if a specific cell is a center of a cross (has 4 immediate '*' neighbors).
     */
    private static boolean isPotentialCenter(char[][] grid, int r, int c) {
        return grid[r][c] == STAR &&
               grid[r - 1][c] == STAR &&
               grid[r + 1][c] == STAR &&
               grid[r][c - 1] == STAR &&
               grid[r][c + 1] == STAR;
    }

    /**
     * Calculates the total number of '*' characters in a cross shape centered at (r, c).
     */
    private static int calculateCrossSize(char[][] grid, int r, int c) {
        int size = 1; // Start with the center star
        size += countArmLength(grid, r, c, -1, 0); // Up
        size += countArmLength(grid, r, c, 1, 0);  // Down
        size += countArmLength(grid, r, c, 0, -1); // Left
        size += countArmLength(grid, r, c, 0, 1);  // Right
        return size;
    }

    /**
     * Traverses in a specific direction to count how many consecutive '*' exist.
     *
     * @param dr The change in row index (direction).
     * @param dc The change in column index (direction).
     * @return The number of consecutive '*' characters in that direction.
     */
    private static int countArmLength(char[][] grid, int r, int c, int dr, int dc) {
        int length = 0;
        int currR = r + dr;
        int currC = c + dc;

        while (isValid(grid, currR, currC) && grid[currR][currC] == STAR) {
            length++;
            currR += dr;
            currC += dc;
        }
        return length;
    }

    /**
     * Validates if the given coordinates are within the grid boundaries.
     */
    private static boolean isValid(char[][] grid, int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }
}

import java.util.*;
import java.io.*;

/**
 * GridAnalyzer identifies if a given grid of characters forms a specific
 * "plus-sign" shape pattern based on star ('*') connectivity and distribution.
 */
public class GridAnalyzer {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);

        try {
            int height = scanner.nextInt();
            int width = scanner.nextInt();
            char[][] grid = new char[height][width];

            for (int i = 0; i < height; i++) {
                grid[i] = scanner.next().toCharArray();
            }

            if (isValidShape(height, width, grid)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        } catch (Exception e) {
            // In a production environment, use a proper logger.
            System.out.println("NO");
        }
    }

    /**
     * Orchestrates the validation process for the grid.
     */
    private static boolean isValidShape(int h, int w, char[][] grid) {
        // 1. Basic dimension and star count requirements
        if (h <= 1 || w <= 1) {
            return false;
        }

        int totalStars = 0;
        int[] rowCounts = new int[h];
        int[] colCounts = new int[w];

        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                if (grid[i][j] == '*') {
                    totalStars++;
                    rowCounts[i]++;
                    colCounts[j]++;
                }
            }
        }

        if (totalStars < 4) {
            return false;
        }

        // 2. Connectivity check: All stars must form a single connected component
        if (!hasSingleConnectedComponent(grid, h, w, totalStars)) {
            return false;
        }

        // 3. Profile check: Row and Column counts must follow a specific unimodal pattern
        if (!isValidSequence(rowCounts) || !isValidSequence(colCounts)) {
            return false;
        }

        return true;
    }

    /**
     * Validates that all '*' characters are connected using Breadth-First Search.
     */
    private static boolean hasSingleConnectedComponent(char[][] grid, int h, int w, int totalStars) {
        boolean[][] visited = new boolean[h][w];
        int starsFound = 0;
        boolean firstComponentFound = false;

        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                if (grid[i][j] == '*' && !visited[i][j]) {
                    // If we find a second component, it's invalid
                    if (firstComponentFound) return false;

                    firstComponentFound = true;
                    int componentSize = performBFS(grid, h, w, i, j, visited);

                    // If the component doesn't include all stars, it's invalid
                    if (componentSize != totalStars) return false;
                    starsFound = componentSize;
                }
            }
        }
        return starsFound == totalStars;
    }

    private static int performBFS(char[][] grid, int h, int w, int startR, int startC, boolean[][] visited) {
        int count = 0;
        Deque<int[]> queue = new ArrayDeque<>();

        queue.offer(new int[]{startR, startC});
        visited[startR][startC] = true;

        int[] dr = {1, 0, -1, 0};
        int[] dc = {0, 1, 0, -1};

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            count++;

            for (int k = 0; k < 4; k++) {
                int nr = current[0] + dr[k];
                int nc = current[1] + dc[k];

                if (nr >= 0 && nr < h && nc >= 0 && nc < w && 
                    grid[nr][nc] == '*' && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    queue.offer(new int[]{nr, nc});
                }
            }
        }
        return count;
    }

    /**
     * Checks if the distribution of stars follows the specific sequence rule:
     * A sequence of 1s that can transition into a single value > 1, 
     * then transition back to 1s.
     */
    private static boolean isValidSequence(int[] counts) {
        boolean isIncreasingPhase = true;

        for (int i = 1; i < counts.length; i++) {
            if (isIncreasingPhase) {
                // Cannot decrease while in the increasing/1s phase
                if (counts[i] < counts[i - 1]) return false;
                // If previous was > 1, next must be 1 (cannot have plateau of > 1)
                if (counts[i - 1] > 1 && counts[i] != 1) return false;
                // If we hit a value > 1, we leave the increasing phase
                if (counts[i] > 1) isIncreasingPhase = false;
            } else {
                // In the decreasing phase
                if (counts[i - 1] > 1 && counts[i] != 1) return false;
                if (counts[i] > 1) return false;
                if (counts[i] > counts[i - 1]) return false;
            }
        }
        // The sequence must have contained at least one value > 1
        return !isIncreasingPhase;
    }

    /**
     * Optimized scanner for fast I/O operations.
     */
    public static class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

