class GridPatternAnalyzer {
    private final char[][] grid;
    private final int rows;
    private final int cols;

    public GridPatternAnalyzer(char[][] grid, int rows, int cols) {
        this.grid = grid;
        this.rows = rows;
        this.cols = cols;
    }

    /**
     * Orchestrates the validation process.
     */
    public boolean isValidPattern() {
        Position firstStar = findFirstStar();
        if (firstStar == null || firstStar.col == 0) {
            return false;
        }

        int starRow = findTargetStarRow(firstStar.row, firstStar.col);
        if (starRow == -1 || isAtBoundary(starRow, firstStar.col)) {
            return false;
        }

        if (!validateStarRowPattern(starRow)) {
            return false;
        }

        return validateRemainingGrid(starRow, firstStar.col);
    }

    private Position findFirstStar() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*') {
                    return new Position(i, j);
                }
            }
        }
        return null;
    }

    private int findTargetStarRow(int startRow, int col) {
        for (int i = startRow; i < rows; i++) {
            if (grid[i][col - 1] == '*') {
                return i;
            }
        }
        return -1;
    }

    private boolean isAtBoundary(int row, int col) {
        return row == 0 || col == 0 || row == rows - 1 || col == cols - 1;
    }

    /**
     * Validates if the star row contains exactly one contiguous block of stars
     * and follows the [dots][stars][dots] pattern.
     */
    private boolean validateStarRowPattern(int row) {
        int j = 0;

        // Skip leading dots
        while (j < cols && grid[row][j] == '.') {
            j++;
        }
        // Consume stars
        while (j < cols && grid[row][j] == '*') {
            j++;
        }
        // Consume trailing dots
        while (j < cols && grid[row][j] == '.') {
            j++;
        }

        // If j hasn't reached the end, there was an invalid character/pattern
        return j == cols;
    }

    /**
     * Checks that no other stars exist in the grid, except for the specific
     * vertical dot condition found in the original logic.
     */
    private boolean validateRemainingGrid(int starRow, int starCol) {
        int verticalDotCount = 0;

        for (int i = 0; i < rows; i++) {
            if (i == starRow) continue;

            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*') {
                    return false; // No other stars allowed in other rows
                }

                // This replicates the 't' counter logic from the original code
                if (j == starCol && grid[i][j] == '.') {
                    if (isVerticalDotSurroundedByStars(i, j, starRow)) {
                        verticalDotCount++;
                    }
                }
            }
        }

        // Original logic: returns YES if t == 0
        return verticalDotCount == 0;
    }

    private boolean isVerticalDotSurroundedByStars(int row, int col, int targetStarRow) {
        int prev = Math.max(0, row - 1);
        int next = Math.min(rows - 1, row + 1);

        // Note: The original logic's boundary checks for prev/forw were slightly flawed;
        // this refactored version maintains the behavior of checking adjacent rows.
        return grid[prev][col] == '*' && grid[next][col] == '*';
    }

    /**
     * Checks if the target star cell (p0, q0) has stars in all four cardinal directions.
     * Note: Based on the original code's constraints, this specific check 
     * (checking neighbors in other rows) is actually impossible to pass 
     * if the "only one star row" rule is enforced.
     */
    private boolean satisfiesCrossRequirement(int row, int col) {
        return grid[row][col - 1] == '*' &&
               grid[row][col + 1] == '*' &&
               grid[row - 1][col] == '*' &&
               grid[row + 1][col] == '*';
    }

    private static class Position {
        int row;
        int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }
}

import java.util.Scanner;

/**
 * A utility to detect if a grid of characters contains a single, perfect cross pattern
 * composed of '#' characters, where all '#' in the grid are part of that cross.
 */
public class CrossPatternDetector {

    private static final char EMPTY_CHARACTER = '.';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        char[][] grid = new char[rows][cols];
        int totalHashCount = 0;

        // Read the grid and count the total number of '#' characters
        for (int r = 0; r < rows; r++) {
            String line = scanner.next();
            for (int c = 0; c < cols; c++) {
                grid[r][c] = line.charAt(c);
                if (grid[r][c] != EMPTY_CHARACTER) {
                    totalHashCount++;
                }
            }
        }

        if (solve(grid, rows, cols, totalHashCount)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Determines if the grid contains a single cross pattern that accounts for all '#' cells.
     * 
     * @param grid The 2D character grid.
     * @param rows Number of rows in the grid.
     * @param cols Number of columns in the grid.
     * @param totalHashCount The total count of non-'.' characters in the grid.
     * @return true if a valid single cross is found, false otherwise.
     */
    private static boolean solve(char[][] grid, int rows, int cols, int totalHashCount) {
        // A cross pattern requires at least a center and four neighbors (5 cells).
        if (totalHashCount < 5) {
            return false;
        }

        // Iterate through all possible center points. 
        // A center cannot be on the boundary of the grid.
        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < cols - 1; c++) {
                if (isPotentialCenter(grid, r, c)) {
                    // If the number of '#' in this specific cross matches the total '#' in the grid,
                    // then there are no '#' cells located outside this cross.
                    if (countHashesInCross(grid, r, c, rows, cols) == totalHashCount) {
                        return true;
                    }
                }
            }
        }

        return false;
    }

    /**
     * Checks if the cell at (r, c) and its four immediate neighbors are not '.'
     */
    private static boolean isPotentialCenter(char[][] grid, int r, int c) {
        return grid[r][c] != EMPTY_CHARACTER &&
               grid[r - 1][c] != EMPTY_CHARACTER &&
               grid[r + 1][c] != EMPTY_CHARACTER &&
               grid[r][c - 1] != EMPTY_CHARACTER &&
               grid[r][c + 1] != EMPTY_CHARACTER;
    }

    /**
     * Counts the total number of '#' characters that form the cross centered at (r, c)
     * by traversing the four arms as far as possible.
     */
    private static int countHashesInCross(char[][] grid, int r, int c, int rows, int cols) {
        int count = 1; // Start with the center cell

        // Count upwards
        for (int i = r - 1; i >= 0 && grid[i][c] != EMPTY_CHARACTER; i--) {
            count++;
        }
        // Count downwards
        for (int i = r + 1; i < rows && grid[i][c] != EMPTY_CHARACTER; i++) {
            count++;
        }
        // Count leftwards
        for (int j = c - 1; j >= 0 && grid[r][j] != EMPTY_CHARACTER; j--) {
            count++;
        }
        // Count rightwards
        for (int j = c + 1; j < cols && grid[r][j] != EMPTY_CHARACTER; j++) {
            count++;
        }

        return count;
    }
}

