/**
 * Represents a 2D character grid.
 */
class Grid {
    private final int rows;
    private final int cols;
    private final char[][] cells;

    public Grid(int rows, int cols) {
        this.rows = rows;
        this.cols = cols;
        this.cells = new char[rows][cols];
    }

    public void setCell(int r, int c, char value) {
        cells[r][c] = value;
    }

    public char getCell(int r, int c) {
        return cells[r][c];
    }

    public int getRows() {
        return rows;
    }

    public int getCols() {
        return cols;
    }

    /**
     * Creates a deep copy of the current grid.
     */
    public Grid copy() {
        Grid newGrid = new Grid(this.rows, this.cols);
        for (int i = 0; i < rows; i++) {
            System.arraycopy(this.cells[i], 0, newGrid.cells[i], 0, cols);
        }
        return newGrid;
    }

    public int countStars(char starChar) {
        int count = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (cells[i][j] == starChar) {
                    count++;
                }
            }
        }
        return count;
    }
}

/**
 * Represents a coordinate point in the grid.
 */
record Point(int row, int col) {}

/**
 * Handles the logic for detecting a valid "Plus Sign" pattern.
 */
class PlusSignValidator {
    private static final char STAR = '*';
    private static final char EMPTY = '.';

    /**
     * Validates if the grid contains exactly one plus sign and no other stars.
     */
    public boolean isValidPlusSign(Grid grid) {
        List<Point> centers = findPotentialCenters(grid);

        // A valid pattern must have exactly one center
        if (centers.size() != 1) {
            return false;
        }

        Point center = centers.get(0);
        return verifyPattern(grid.copy(), center);
    }

    private List<Point> findPotentialCenters(Grid grid) {
        List<Point> centers = new ArrayList<>();
        int rows = grid.getRows();
        int cols = grid.getCols();

        // A center cannot be on the edge
        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < cols - 1; c++) {
                if (isCenter(grid, r, c)) {
                    centers.add(new Point(r, c));
                }
            }
        }
        return centers;
    }

    private boolean isCenter(Grid grid, int r, int c) {
        return grid.getCell(r, c) == STAR &&
               grid.getCell(r - 1, c) == STAR &&
               grid.getCell(r + 1, c) == STAR &&
               grid.getCell(r, c - 1) == STAR &&
               grid.getCell(r, c + 1) == STAR;
    }

    private boolean verifyPattern(Grid workingGrid, Point center) {
        int r = center.row();
        int c = center.col();

        // Erase the arms extending from the center
        eraseArm(workingGrid, r, c, -1, 0);  // Up
        eraseArm(workingGrid, r, c, 1, 0);   // Down
        eraseArm(workingGrid, r, c, 0, -1);  // Left
        eraseArm(workingGrid, r, c, 0, 1);   // Right

        // After erasing the arms, only the center star should remain
        return workingGrid.countStars(STAR) == 1;
    }

    private void eraseArm(Grid grid, int r, int c, int dr, int dc) {
        int currR = r + dr;
        int currC = c + dc;

        while (currR >= 0 && currR < grid.getRows() && 
               currC >= 0 && currC < grid.getCols() && 
               grid.getCell(currR, currC) == STAR) {

            grid.setCell(currR, currC, EMPTY);
            currR += dr;
            currC += dc;
        }
    }
}

/**
 * Fast I/O utility for efficient reading.
 */
class FastReader {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    public FastReader(InputStream input) {
        reader = new BufferedReader(new InputStreamReader(input));
    }

    public String next() {
        while (tokenizer == null || !tokenizer.hasMoreElements()) {
            try {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                return null;
            }
        }
        return tokenizer.nextToken();
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }

    public Grid nextGrid(int h, int w) {
        Grid grid = new Grid(h, w);
        for (int i = 0; i < h; i++) {
            String line = next();
            for (int j = 0; j < w; j++) {
                grid.setCell(i, j, line.charAt(j));
            }
        }
        return grid;
    }
}

