/**
 * Application to detect if a grid contains exactly one contiguous cross pattern.
 */
public class CrossPatternApp {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            CrossPatternSolver solver = new CrossPatternSolver();
            solver.solve(reader, writer);
        } catch (IOException e) {
            System.err.println("An error occurred while reading input: " + e.getMessage());
        } finally {
            writer.close();
        }
    }

    /**
     * Logic for analyzing the grid to find a valid cross pattern.
     */
    static class CrossPatternSolver {

        private record Point(int row, int col) {}

        public void solve(FastReader in, PrintWriter out) throws IOException {
            int height = in.nextInt();
            int width = in.nextInt();
            char[][] grid = new char[height][width];

            for (int i = 0; i < height; i++) {
                grid[i] = in.next().toCharArray();
            }

            Point center = findCrossCenter(grid, height, width);

            if (center == null) {
                out.println("NO");
                return;
            }

            if (isValidCross(grid, height, width, center)) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        }

        /**
         * Searches for the center of a cross (a '*' with '*' neighbors in all 4 directions).
         */
        private Point findCrossCenter(char[][] grid, int height, int width) {
            for (int r = 1; r < height - 1; r++) {
                for (int c = 1; c < width - 1; c++) {
                    if (isCenterCandidate(grid, r, c)) {
                        return new Point(r, c);
                    }
                }
            }
            return null;
        }

        private boolean isCenterCandidate(char[][] grid, int r, int c) {
            return grid[r][c] == '*' &&
                   grid[r - 1][c] == '*' &&
                   grid[r + 1][c] == '*' &&
                   grid[r][c - 1] == '*' &&
                   grid[r][c + 1] == '*';
        }

        /**
         * Validates that the identified center forms the only valid cross in the grid.
         */
        private boolean isValidCross(char[][] grid, int height, int width, Point center) {
            // 1. Check if the cross lines are continuous (no '*' after a '.')
            if (hasGapsInDirections(grid, height, width, center)) {
                return false;
            }

            // 2. Check if there are any stars that do not belong to the cross lines
            if (hasExtraStars(grid, height, width, center)) {
                return false;
            }

            return true;
        }

        /**
         * Checks the 4 directions from the center to ensure no stars are separated by dots.
         */
        private boolean hasGapsInDirections(char[][] grid, int height, int width, Point center) {
            // Directions: Up, Down, Left, Right
            int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

            for (int[] dir : directions) {
                int dr = dir[0];
                int dc = dir[1];
                boolean foundDot = false;

                int r = center.row + dr;
                int c = center.col + dc;

                while (r >= 0 && r < height && c >= 0 && c < width) {
                    if (grid[r][c] == '.') {
                        foundDot = true;
                    } else if (grid[r][c] == '*' && foundDot) {
                        // A star was found after a dot in this direction
                        return true;
                    }
                    r += dr;
                    c += dc;
                }
            }
            return false;
        }

        /**
         * Checks if any '*' exists in the grid that is not on the cross's row or column.
         */
        private boolean hasExtraStars(char[][] grid, int height, int width, Point center) {
            for (int r = 0; r < height; r++) {
                for (int c = 0; c < width; c++) {
                    if (grid[r][c] == '*' && r != center.row && c != center.col) {
                        return true;
                    }
                }
            }
            return false;
        }
    }

    /**
     * Fast I/O utility for efficient reading.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

