/**
 * Logic handler for analyzing the grid of stars.
 */
class GridAnalyzer {
    private static final char STAR = '*';
    private static final char CLEARED = '#';

    private final int rows;
    private final int cols;
    private final char[][] grid;

    public GridAnalyzer(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
    }

    /**
     * Attempts to find the first valid cross pattern and clear the grid.
     * Returns true if all stars are cleared, false otherwise.
     */
    public boolean canClearAllStars() {
        boolean crossFound = false;

        // Search for the first valid center of a cross pattern
        // A cross requires at least one cell of padding, so we loop from 1 to length-2
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (isCrossCenter(i, j)) {
                    applyCrossClearance(i, j);
                    crossFound = true;
                    break;
                }
            }
            if (crossFound) break;
        }

        if (!crossFound) {
            return false;
        }

        return !hasRemainingStars();
    }

    private boolean isCrossCenter(int r, int c) {
        return grid[r][c] == STAR &&
               grid[r][c + 1] == STAR &&
               grid[r][c - 1] == STAR &&
               grid[r - 1][c] == STAR &&
               grid[r + 1][c] == STAR;
    }

    private void applyCrossClearance(int r, int c) {
        grid[r][c] = CLEARED;

        // Clear contiguous stars downwards
        for (int k = r + 1; k < rows; k++) {
            if (grid[k][c] == STAR) grid[k][c] = CLEARED;
            else break;
        }

        // Clear contiguous stars upwards
        for (int k = r - 1; k >= 0; k--) {
            if (grid[k][c] == STAR) grid[k][c] = CLEARED;
            else break;
        }

        // Clear contiguous stars rightwards
        for (int k = c + 1; k < cols; k++) {
            if (grid[r][k] == STAR) grid[r][k] = CLEARED;
            else break;
        }

        // Clear contiguous stars leftwards
        for (int k = c - 1; k >= 0; k--) {
            if (grid[r][k] == STAR) grid[r][k] = CLEARED;
            else break;
        }
    }

    private boolean hasRemainingStars() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == STAR) {
                    return true;
                }
            }
        }
        return false;
    }
}

public class Solution {
    public static void main(String[] args) {
        FastReader reader = new FastReader();

        try {
            int rowCount = reader.nextInt();
            int colCount = reader.nextInt();

            // Consume the leftover newline character from nextInt() 
            // to ensure nextLine() works correctly for the grid.
            reader.nextLine();

            char[][] grid = new char[rowCount][colCount];
            for (int i = 0; i < rowCount; i++) {
                String line = reader.nextLine();
                // Handle potential empty lines or mismatched input
                for (int j = 0; j < colCount; j++) {
                    grid[i][j] = (j < line.length()) ? line.charAt(j) : ' ';
                }
            }

            GridAnalyzer analyzer = new GridAnalyzer(rowCount, colCount, grid);

            if (analyzer.canClearAllStars()) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }

        } catch (Exception e) {
            // In a production environment, use a proper logging framework.
            // For algorithmic problems, printing the error is acceptable.
            e.printStackTrace();
        }
    }
}

