/**
 * A solution to determine if a given grid of stars forms a single, 
 * connected cross shape.
 */
public class Main {
    public static void main(String[] args) {
        try {
            CrossGridSolver solver = new CrossGridSolver(System.in);
            solver.solve();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

class CrossGridSolver {
    private final FastReader reader;
    private final PrintWriter writer;

    private int rows;
    private int cols;
    private char[][] grid;
    private int totalStarCount;

    // Directions for 4-connectivity: up, down, left, right
    private static final int[][] DIRECTIONS = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

    public CrossGridSolver(InputStream inputStream) {
        this.reader = new FastReader(inputStream);
        this.writer = new PrintWriter(System.out);
    }

    public void solve() throws IOException {
        this.rows = reader.nextInt();
        this.cols = reader.nextInt();
        this.grid = new char[rows][cols];
        this.totalStarCount = 0;

        for (int i = 0; i < rows; i++) {
            String line = reader.next();
            grid[i] = line.toCharArray();
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*') {
                    totalStarCount++;
                }
            }
        }

        if (totalStarCount == 0) {
            printResult(false);
            return;
        }

        // 1. Identify the center of the potential cross.
        // A center must be a '*' with 4 '*' neighbors.
        int[] center = findCrossCenter();
        if (center == null) {
            printResult(false);
            return;
        }

        int centerX = center[0];
        int centerY = center[1];

        // 2. Verify all '*' stars lie on the cross axes (same row or same column as center).
        if (!areAllStarsOnAxes(centerX, centerY)) {
            printResult(false);
            return;
        }

        // 3. Verify all stars are part of a single connected component.
        if (countConnectedStars(centerX, centerY) != totalStarCount) {
            printResult(false);
            return;
        }

        printResult(true);
    }

    private int[] findCrossCenter() {
        // A center must have 4 neighbors, so it cannot be on the grid boundary.
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (grid[i][j] == '*' && hasFourNeighbors(i, j)) {
                    return new int[]{i, j};
                }
            }
        }
        return null;
    }

    private boolean hasFourNeighbors(int r, int c) {
        for (int[] dir : DIRECTIONS) {
            if (grid[r + dir[0]][c + dir[1]] != '*') {
                return false;
            }
        }
        return true;
    }

    private boolean areAllStarsOnAxes(int centerX, int centerY) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*') {
                    // If a star is not on the center's row and not on the center's column, it's not a cross.
                    if (i != centerX && j != centerY) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    private int countConnectedStars(int startR, int startC) {
        boolean[][] visited = new boolean[rows][cols];
        Queue<int[]> queue = new ArrayDeque<>();

        queue.offer(new int[]{startR, startC});
        visited[startR][startC] = true;
        int count = 0;

        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            count++;

            for (int[] dir : DIRECTIONS) {
                int nr = curr[0] + dir[0];
                int nc = curr[1] + dir[1];

                if (isValid(nr, nc) && grid[nr][nc] == '*' && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    queue.offer(new int[]{nr, nc});
                }
            }
        }
        return count;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private void printResult(boolean isCross) {
        writer.println(isCross ? "YES" : "NO");
        writer.flush();
    }

    /**
     * Helper class for fast input reading.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }
}

import java.util.Scanner;

/**
 * A program to detect if a grid contains exactly one "plus" shape.
 * A plus shape consists of a center cell and its four immediate neighbors (up, down, left, right)
 * being stars ('*'), with no other stars present in the grid.
 */
public class PlusShapeDetector {

    private static final char STAR = '*';
    private static final int REQUIRED_STAR_COUNT = 5;

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            if (rows < 3 || cols < 3) {
                System.out.println("NO");
                return;
            }

            char[][] grid = new char[rows][cols];
            int totalStars = 0;

            // Read the grid and count total star characters
            for (int i = 0; i < rows; i++) {
                String line = scanner.next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                    if (grid[i][j] == STAR) {
                        totalStars++;
                    }
                }
            }

            if (isValidPlus(grid, rows, cols, totalStars)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /**
     * Validates if the grid contains exactly one plus shape.
     * 
     * @param grid The 2D grid of characters.
     * @param rows Number of rows in the grid.
     * @param cols Number of columns in the grid.
     * @param totalStars Total number of stars found in the grid.
     * @return true if a single plus shape exists, false otherwise.
     */
    private static boolean isValidPlus(char[][] grid, int rows, int cols, int totalStars) {
        // A plus shape must consist of exactly 5 stars.
        if (totalStars != REQUIRED_STAR_COUNT) {
            return false;
        }

        // Search for a cell that acts as the center of a plus shape.
        // The center cannot be on the edge of the grid.
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (grid[i][j] == STAR && isCenterOfPlus(grid, i, j)) {
                    return true;
                }
            }
        }

        return false;
    }

    /**
     * Checks if a specific cell is the center of a plus shape.
     * 
     * @param grid The 2D grid.
     * @param r The row index of the potential center.
     * @param c The column index of the potential center.
     * @return true if the four adjacent cells are also stars.
     */
    private static boolean isCenterOfPlus(char[][] grid, int r, int c) {
        return grid[r - 1][c] == STAR && // Up
               grid[r + 1][c] == STAR && // Down
               grid[r][c - 1] == STAR && // Left
               grid[r][c + 1] == STAR;   // Right
    }
}

import java.util.*;
import java.io.*;

/**
 * A program to determine if all '*' cells in a grid form exactly one '+' shaped cross.
 * A valid cross must have a center cell and four arms, each with a length of at least 1.
 * All '*' cells in the grid must be part of this single cross.
 */
public class CrossPatternSolver {

    /**
     * Fast I/O utility to handle large inputs efficiently.
     */
    private static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            return next != null ? Integer.parseInt(next) : 0;
        }
    }

    public void run() {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        // Read dimensions
        String nStr = reader.next();
        if (nStr == null) {
            out.close();
            return;
        }
        int rows = Integer.parseInt(nStr);
        int cols = reader.nextInt();

        boolean[][] isStar = new boolean[rows][cols];
        int totalStarsCount = 0;

        // Populate grid and count total star cells
        for (int i = 0; i < rows; i++) {
            String line = reader.next();
            for (int j = 0; j < cols; j++) {
                if (line != null && line.charAt(j) == '*') {
                    isStar[i][j] = true;
                    totalStarsCount++;
                }
            }
        }

        // A cross requires at least a center and 4 arm cells
        if (totalStarsCount < 5) {
            out.println("NO");
        } else {
            processGrid(isStar, rows, cols, totalStarsCount, out);
        }

        out.close();
    }

    private void processGrid(boolean[][] isStar, int rows, int cols, int totalStars, PrintWriter out) {
        int[] center = findCrossCenter(isStar, rows, cols);

        if (center[0] == -1) {
            out.println("NO");
        } else {
            if (isValidCross(isStar, rows, cols, center[0], center[1], totalStars)) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        }
    }

    /**
     * Searches for a cell that acts as a valid center of a cross.
     * A center must be a '*' and have '*' neighbors in all four cardinal directions.
     */
    private int[] findCrossCenter(boolean[][] isStar, int rows, int cols) {
        // Based on original logic, a center cannot be on the grid boundary
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (isStar[i][j] && isStar[i - 1][j] && isStar[i + 1][j] 
                    && isStar[i][j - 1] && isStar[i][j + 1]) {
                    return new int[]{i, j};
                }
            }
        }
        return new int[]{-1, -1};
    }

    /**
     * Validates if the cross centered at (r, c) covers all '*' cells in the grid.
     */
    private boolean isValidCross(boolean[][] isStar, int rows, int cols, int r, int c, int totalStars) {
        int crossCellsCount = 1; // Start with the center cell

        // Directional vectors: Up, Down, Left, Right
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int i = 0; i < 4; i++) {
            int nr = r + dr[i];
            int nc = c + dc[i];
            int armLength = 0;

            // Expand in the current direction as long as we encounter '*'
            while (nr >= 0 && nr < rows && nc >= 0 && nc < cols && isStar[nr][nc]) {
                armLength++;
                crossCellsCount++;
                nr += dr[i];
                nc += dc[i];
            }

            // A valid cross must have arms of length at least 1 in all 4 directions
            if (armLength == 0) {
                return false;
            }
        }

        // The pattern is valid only if the number of cells in the cross 
        // matches the total number of '*' cells found in the grid.
        return crossCellsCount == totalStars;
    }

    public static void main(String[] args) {
        new CrossPatternSolver().run();
    }
}

