/**
 * Core logic for detecting if a grid contains exactly one plus shape.
 */
class PlusShapeSolver {
    private static final char STAR_CHAR = '*';

    /**
     * Determines if the provided grid contains exactly one plus shape and no other stars.
     * 
     * @param grid The 2D character array representing the picture.
     * @param rows Number of rows in the grid.
     * @param cols Number of columns in the grid.
     * @return true if exactly one plus shape is found using all stars; false otherwise.
     */
    public boolean isSinglePlusShape(char[][] grid, int rows, int cols) {
        int totalStars = countTotalStars(grid, rows, cols);

        // A plus shape must have at least 5 stars (center + 4 neighbors)
        if (totalStars < 5) {
            return false;
        }

        // Iterate through the grid, excluding boundaries, to find a potential center
        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < cols - 1; c++) {
                if (isPotentialCenter(grid, r, c)) {
                    // If a center is found, count all stars that belong to this specific plus
                    if (countPlusStarsAtCenter(grid, r, c, rows, cols) == totalStars) {
                        return true;
                    }
                }
            }
        }

        return false;
    }

    private int countTotalStars(char[][] grid, int rows, int cols) {
        int count = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == STAR_CHAR) {
                    count++;
                }
            }
        }
        return count;
    }

    private boolean isPotentialCenter(char[][] grid, int r, int c) {
        return grid[r][c] == STAR_CHAR &&
               grid[r - 1][c] == STAR_CHAR &&
               grid[r + 1][c] == STAR_CHAR &&
               grid[r][c - 1] == STAR_CHAR &&
               grid[r][c + 1] == STAR_CHAR;
    }

    private int countPlusStarsAtCenter(char[][] grid, int r, int c, int rows, int cols) {
        int plusStarCount = 1; // Start with the center star

        // Expand Up
        for (int i = r - 1; i >= 0 && grid[i][c] == STAR_CHAR; i--) {
            plusStarCount++;
        }
        // Expand Down
        for (int i = r + 1; i < rows && grid[i][c] == STAR_CHAR; i++) {
            plusStarCount++;
        }
        // Expand Left
        for (int j = c - 1; j >= 0 && grid[r][j] == STAR_CHAR; j--) {
            plusStarCount++;
        }
        // Expand Right
        for (int j = c + 1; j < cols && grid[r][j] == STAR_CHAR; j++) {
            plusStarCount++;
        }

        return plusStarCount;
    }
}

