/**
 * Logic for determining if the set of '*' characters in a grid forms a single cross shape.
 */
class CrossShapeSolver {

    private static final char STAR = '*';

    /**
     * Orchestrates the solving process.
     */
    public void solve(FastReader reader, PrintWriter writer) {
        int height = reader.nextInt();
        int width = reader.nextInt();

        char[][] grid = new char[height][width];
        int totalStarCount = 0;

        for (int i = 0; i < height; i++) {
            String row = reader.next();
            for (int j = 0; j < width; j++) {
                grid[i][j] = row.charAt(j);
                if (grid[i][j] == STAR) {
                    totalStarCount++;
                }
            }
        }

        if (isCrossShape(grid, height, width, totalStarCount)) {
            writer.println("YES");
        } else {
            writer.println("NO");
        }
    }

    /**
     * Validates if the grid forms a single valid cross.
     */
    private boolean isCrossShape(char[][] grid, int height, int width, int totalStarCount) {
        // A cross requires at least a 3x3 area to have a center with 4 neighbors
        if (height < 3 || width < 3 || totalStarCount == 0) {
            return false;
        }

        Point center = findCrossCenter(grid, height, width);
        if (center == null) {
            return false;
        }

        int starsInCross = countStarsOnCross(grid, height, width, center);

        // The shape is a perfect cross if the number of stars forming the cross
        // matches the total number of stars found in the grid.
        return starsInCross == totalStarCount;
    }

    /**
     * Finds a cell that acts as the center of a cross (has '*' neighbors in all 4 directions).
     */
    private Point findCrossCenter(char[][] grid, int height, int width) {
        for (int i = 1; i < height - 1; i++) {
            for (int j = 1; j < width - 1; j++) {
                if (isCenter(grid, i, j)) {
                    return new Point(i, j);
                }
            }
        }
        return null;
    }

    /**
     * Checks if a specific cell is a valid cross center.
     */
    private boolean isCenter(char[][] grid, int r, int c) {
        return grid[r][c] == STAR &&
               grid[r - 1][c] == STAR &&
               grid[r + 1][c] == STAR &&
               grid[r][c - 1] == STAR &&
               grid[r][c + 1] == STAR;
    }

    /**
     * Counts all '*' characters that lie on the horizontal and vertical lines passing through the center.
     */
    private int countStarsOnCross(char[][] grid, int height, int width, Point center) {
        int count = 1; // Start with the center cell itself

        // Count Up
        for (int i = center.row - 1; i >= 0 && grid[i][center.col] == STAR; i--) count++;
        // Count Down
        for (int i = center.row + 1; i < height && grid[i][center.col] == STAR; i++) count++;
        // Count Left
        for (int j = center.col - 1; j >= 0 && grid[center.row][j] == STAR; j--) count++;
        // Count Right
        for (int j = center.col + 1; j < width && grid[center.row][j] == STAR; j++) count++;

        return count;
    }

    /**
     * Simple data carrier for coordinates.
     */
    private static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }
}

