import java.util.Scanner;

/**
 * A utility to detect if a grid contains exactly one "plus" shape made of stars ('*').
 * A valid plus shape is defined as a single row and a single column of stars 
 * that intersect at a center, with all other cells being dots ('.').
 */
public class PlusShapeDetector {

    private static final char STAR = '*';
    private static final char DOT = '.';

    public static void main(String[] args) {
        PlusShapeDetector detector = new PlusShapeDetector();
        detector.run();
    }

    /**
     * Orchestrates the execution of the program.
     */
    public void run() {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            char[][] grid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                grid[i] = scanner.next().toCharArray();
            }

            if (isValidPlusShape(grid, rows, cols)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        } catch (Exception e) {
            System.err.println("An error occurred: " + e.getMessage());
        }
    }

    /**
     * Validates if the grid contains exactly one plus shape.
     */
    private boolean isValidPlusShape(char[][] grid, int rows, int cols) {
        int[] center = findPotentialCenter(grid, rows, cols);

        // If no potential center (3x3 cross) is found, it's not a valid plus.
        if (center == null) {
            return false;
        }

        int centerRow = center[0];
        int centerCol = center[1];

        // 1. Verify that the entire crosshair (row and column of center) consists of '*'
        // 2. Verify that every other cell in the grid consists of '.'
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                boolean isOnCrosshair = (i == centerRow || j == centerCol);

                if (isOnCrosshair) {
                    if (grid[i][j] != STAR) {
                        return false;
                    }
                } else {
                    if (grid[i][j] != DOT) {
                        return false;
                    }
                }
            }
        }

        return true;
    }

    /**
     * Searches for a '*' that is surrounded by 4 '*' neighbors.
     * Returns an array containing {row, col} if found, otherwise null.
     */
    private int[] findPotentialCenter(char[][] grid, int rows, int cols) {
        // A plus center must be at least 1 cell away from any boundary to have 4 neighbors
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (isCenterOfThreeByThreeCross(grid, i, j)) {
                    return new int[]{i, j};
                }
            }
        }
        return null;
    }

    /**
     * Checks if the cell at (r, c) and its 4 immediate neighbors are stars.
     */
    private boolean isCenterOfThreeByThreeCross(char[][] grid, int r, int c) {
        return grid[r][c] == STAR &&
               grid[r - 1][c] == STAR &&
               grid[r + 1][c] == STAR &&
               grid[r][c - 1] == STAR &&
               grid[r][c + 1] == STAR;
    }
}

import java.util.Scanner;

/**
 * StarGridSolver analyzes a grid of stars ('*') and dots ('.').
 * It attempts to find a "clearing star" that can remove all stars from the grid
 * by clearing its connected horizontal and vertical segments.
 */
public class StarGridSolver {

    private static final char STAR = '*';
    private static final char DOT = '.';

    private final int rows;
    private final int cols;
    private final char[][] grid;

    public StarGridSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
    }

    /**
     * Executes the core logic of the program and prints the result.
     */
    public void solve() {
        int[] clearingStarCoordinate = findFirstClearingStar();

        // If no star satisfies the clearing criteria, it's impossible.
        if (clearingStarCoordinate == null) {
            System.out.println("NO");
            return;
        }

        // Perform the clearing operation.
        clearConnectedStars(clearingStarCoordinate[0], clearingStarCoordinate[1]);

        // If the grid is empty after clearing, we succeeded.
        if (hasAnyStars()) {
            System.out.println("NO");
        } else {
            System.out.println("YES");
        }
    }

    /**
     * Searches for the first star that is not on the border and has no adjacent dots.
     * 
     * @return The [row, col] of the star, or null if none is found.
     */
    private int[] findFirstClearingStar() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == STAR && isClearingStar(r, c)) {
                    return new int[]{r, c};
                }
            }
        }
        return null;
    }

    /**
     * Determines if a star at (r, c) is eligible to be a clearing star.
     */
    private boolean isClearingStar(int r, int c) {
        // A clearing star cannot be on the boundary of the grid.
        if (r == 0 || r == rows - 1 || c == 0 || c == cols - 1) {
            return false;
        }

        // A clearing star must not be adjacent to any dots.
        return grid[r - 1][c] == STAR &&
               grid[r + 1][c] == STAR &&
               grid[r][c - 1] == STAR &&
               grid[r][c + 1] == STAR;
    }

    /**
     * Clears the star at (r, c) and all continuous stars in its 4 cardinal directions.
     */
    private void clearConnectedStars(int r, int c) {
        grid[r][c] = DOT;

        // Clear vertically upwards
        for (int i = r - 1; i >= 0 && grid[i][c] == STAR; i--) {
            grid[i][c] = DOT;
        }
        // Clear vertically downwards
        for (int i = r + 1; i < rows && grid[i][c] == STAR; i++) {
            grid[i][c] = DOT;
        }
        // Clear horizontally left
        for (int j = c - 1; j >= 0 && grid[r][j] == STAR; j--) {
            grid[r][j] = DOT;
        }
        // Clear horizontally right
        for (int j = c + 1; j < cols && grid[r][j] == STAR; j++) {
            grid[r][j] = DOT;
        }
    }

    /**
     * Checks if there are any stars remaining in the grid.
     */
    private boolean hasAnyStars() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == STAR) {
                    return true;
                }
            }
        }
        return false;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int n = scanner.nextInt();
        int m = scanner.nextInt();
        char[][] grid = new char[n][m];

        for (int i = 0; i < n; i++) {
            String rowInput = scanner.next();
            grid[i] = rowInput.toCharArray();
        }

        StarGridSolver solver = new StarGridSolver(n, m, grid);
        solver.solve();

        scanner.close();
    }
}

import java.io.*;
import java.util.*;

/**
 * Solution for the PlusPicture problem.
 * The goal is to find a 'plus' shape made of '*' characters, 
 * replace it with '#', and determine if any '*' characters remain.
 */
public class PlusPicture {

    private static final char STAR = '*';
    private static final char CROSS_MARK = '#';

    public static void main(String[] args) {
        InputReader reader = new InputReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int height = reader.nextInt();
            int width = reader.nextInt();

            char[][] gridData = new char[height][width];
            for (int i = 0; i < height; i++) {
                gridData[i] = reader.next().toCharArray();
            }

            Grid grid = new Grid(gridData);
            PlusSolver solver = new PlusSolver(grid);

            writer.println(solver.solve());
        } catch (Exception e) {
            // In a real production environment, use a proper logger.
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    /**
     * Represents the grid structure and operations performed on it.
     */
    static class Grid {
        private final char[][] cells;
        private final int rows;
        private final int cols;

        public Grid(char[][] cells) {
            this.cells = cells;
            this.rows = cells.length;
            this.cols = (rows > 0) ? cells[0].length : 0;
        }

        public char getCell(int r, int c) {
            return cells[r][c];
        }

        public void setCell(int r, int c, char value) {
            cells[r][c] = value;
        }

        public int getRows() {
            return rows;
        }

        public int getCols() {
            return cols;
        }

        public boolean hasRemainingStars() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (cells[i][j] == STAR) {
                        return true;
                    }
                }
            }
            return false;
        }
    }

    /**
     * Handles the business logic of finding and erasing the plus shape.
     */
    static class PlusSolver {
        private final Grid grid;

        public PlusSolver(Grid grid) {
            this.grid = grid;
        }

        /**
         * The core logic: find a plus, erase it, and check for remaining stars.
         * @return "YES" if the grid is cleared, "NO" otherwise.
         */
        public String solve() {
            Optional<Coordinate> center = findPlusCenter();

            if (center.isEmpty()) {
                return "NO";
            }

            erasePlusShape(center.get());

            return grid.hasRemainingStars() ? "NO" : "YES";
        }

        private Optional<Coordinate> findPlusCenter() {
            int rows = grid.getRows();
            int cols = grid.getCols();

            // A plus requires at least a 3x3 area to have a center with 4 neighbors
            for (int i = 1; i < rows - 1; i++) {
                for (int j = 1; j < cols - 1; j++) {
                    if (isCenterOfPlus(i, j)) {
                        return Optional.of(new Coordinate(i, j));
                    }
                }
            }
            return Optional.empty();
        }

        private boolean isCenterOfPlus(int r, int c) {
            return grid.getCell(r, c) == STAR &&
                   grid.getCell(r - 1, c) == STAR &&
                   grid.getCell(r + 1, c) == STAR &&
                   grid.getCell(r, c - 1) == STAR &&
                   grid.getCell(r, c + 1) == STAR;
        }

        private void erasePlusShape(Coordinate center) {
            int r = center.row;
            int c = center.col;

            grid.setCell(r, c, CROSS_MARK);

            // Erase Up
            for (int i = r - 1; i >= 0 && grid.getCell(i, c) == STAR; i--) {
                grid.setCell(i, c, CROSS_MARK);
            }
            // Erase Down
            for (int i = r + 1; i < grid.getRows() && grid.getCell(i, c) == STAR; i++) {
                grid.setCell(i, c, CROSS_MARK);
            }
            // Erase Left
            for (int j = c - 1; j >= 0 && grid.getCell(r, j) == STAR; j--) {
                grid.setCell(r, j, CROSS_MARK);
            }
            // Erase Right
            for (int j = c + 1; j < grid.getCols() && grid.getCell(r, j) == STAR; j++) {
                grid.setCell(r, j, CROSS_MARK);
            }
        }
    }

    /**
     * Simple data transfer object for coordinates.
     */
    static class Coordinate {
        final int row;
        final int col;

        Coordinate(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Utility class for fast input reading.
     */
    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;

/**
 * A program that validates if a given grid of '*' characters forms a single,
 * contiguous cross shape.
 */
public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int numRows = scanner.nextInt();

        if (!scanner.hasNextInt()) return;
        int numCols = scanner.nextInt();

        char[][] gridData = new char[numRows][numCols];
        for (int i = 0; i < numRows; i++) {
            if (scanner.hasNext()) {
                gridData[i] = scanner.next().toCharArray();
            }
        }

        Grid grid = new Grid(gridData);
        CrossShapeValidator validator = new CrossShapeValidator(grid);

        if (validator.isValidCross()) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Represents the grid and provides bounds-safe access to cell data.
     */
    static class Grid {
        private final int rows;
        private final int cols;
        private final char[][] cells;

        public Grid(char[][] cells) {
            this.rows = cells.length;
            this.cols = cells.length > 0 ? cells[0].length : 0;
            this.cells = cells;
        }

        public int getRows() { return rows; }
        public int getCols() { return cols; }

        public boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        public boolean isStar(int r, int c) {
            return isWithinBounds(r, c) && cells[r][c] == '*';
        }

        public char getCell(int r, int c) {
            return cells[r][c];
        }
    }

    /**
     * Holds coordinate information.
     */
    static class Point {
        final int r, c;
        Point(int r, int c) { this.r = r; this.c = c; }
    }

    /**
     * Contains the logic to validate if the '*' cells form a single valid cross.
     */
    static class CrossShapeValidator {
        private final Grid grid;
        private static final int[] DR = {-1, 1, 0, 0};
        private static final int[] DC = {0, 0, -1, 1};

        public CrossShapeValidator(Grid grid) {
            this.grid = grid;
        }

        public boolean isValidCross() {
            if (grid.getRows() < 3 || grid.getCols() < 3) {
                return false;
            }

            if (!hasExactlyOneConnectedComponent()) {
                return false;
            }

            List<Point> centers = findCenterCandidates();
            if (centers.size() != 1) {
                return false;
            }

            Point center = centers.get(0);
            return allStarsAreOnAxes(center);
        }

        /**
         * Uses DFS to ensure all '*' cells form a single connected component.
         */
        private boolean hasExactlyOneConnectedComponent() {
            boolean[][] visited = new boolean[grid.getRows()][grid.getCols()];
            int componentCount = 0;

            for (int r = 0; r < grid.getRows(); r++) {
                for (int c = 0; c < grid.getCols(); c++) {
                    if (grid.isStar(r, c) && !visited[r][c]) {
                        componentCount++;
                        if (componentCount > 1) return false;
                        performDFS(r, c, visited);
                    }
                }
            }
            return componentCount == 1;
        }

        private void performDFS(int r, int c, boolean[][] visited) {
            visited[r][c] = true;
            for (int i = 0; i < 4; i++) {
                int nr = r + DR[i];
                int nc = c + DC[i];
                if (grid.isStar(nr, nc) && !visited[nr][nc]) {
                    performDFS(nr, nc, visited);
                }
            }
        }

        /**
         * A center candidate is a '*' cell that has 4 '*' neighbors.
         */
        private List<Point> findCenterCandidates() {
            List<Point> candidates = new ArrayList<>();
            for (int r = 1; r < grid.getRows() - 1; r++) {
                for (int c = 1; c < grid.getCols() - 1; c++) {
                    if (isCenter(r, c)) {
                        candidates.add(new Point(r, c));
                    }
                }
            }
            return candidates;
        }

        private boolean isCenter(int r, int c) {
            return grid.isStar(r, c) &&
                   grid.isStar(r - 1, c) &&
                   grid.isStar(r + 1, c) &&
                   grid.isStar(r, c - 1) &&
                   grid.isStar(r, c + 1);
        }

        /**
         * Ensures every '*' in the grid lies on the same row or column as the center.
         */
        private boolean allStarsAreOnAxes(Point center) {
            for (int r = 0; r < grid.getRows(); r++) {
                for (int c = 0; c < grid.getCols(); c++) {
                    if (grid.isStar(r, c)) {
                        boolean onSameRow = (r == center.r);
                        boolean onSameCol = (c == center.c);
                        if (!onSameRow && !onSameCol) {
                            return false;
                        }
                    }
                }
            }
            return true;
        }
    }
}

import java.util.*;

/**
 * A program to detect if a specific star pattern exists in a grid.
 * The pattern consists of:
 * 1. A single star in a row.
 * 2. A horizontal bar of 3+ contiguous stars in the next row that spans the column of the first star.
 * 3. A single star in the next row, in the same column as the first star.
 */
public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int height = scanner.nextInt();
        int width = scanner.nextInt();
        scanner.nextLine(); // Consume the newline character

        String[] grid = new String[height];
        for (int i = 0; i < height; i++) {
            if (scanner.hasNextLine()) {
                grid[i] = scanner.nextLine();
            } else {
                grid[i] = "";
            }
        }

        PatternMatcher matcher = new PatternMatcher();
        if (matcher.isValidPattern(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }
}

/**
 * Analyzes a single row of the grid to provide metadata about the stars present.
 */
class RowMetrics {
    final int starCount;
    final boolean isContiguous;
    final int firstStarIndex;
    final int lastStarIndex;

    RowMetrics(String row) {
        int first = -1;
        int last = -1;
        int count = 0;
        int maxGap = 0;
        int prevIdx = -1;

        for (int i = 0; i < row.length(); i++) {
            if (row.charAt(i) == '*') {
                if (first == -1) {
                    first = i;
                }
                if (prevIdx != -1) {
                    maxGap = Math.max(maxGap, i - prevIdx);
                }
                last = i;
                prevIdx = i;
                count++;
            }
        }

        this.starCount = count;
        this.firstStarIndex = first;
        this.lastStarIndex = last;
        // A row is contiguous if the gap between any two adjacent stars is exactly 1
        this.isContiguous = (count > 0 && maxGap <= 1);
    }
}

/**
 * Encapsulates the logic for detecting the specific pattern within the grid.
 */
class PatternMatcher {

    private enum DetectionState {
        SEARCHING_FOR_TOP,
        SEARCHING_FOR_BAR,
        SEARCHING_FOR_BOTTOM,
        PATTERN_COMPLETE,
        INVALID
    }

    /**
     * Validates the grid against the T-shape pattern.
     * 
     * @param grid The 2D array of characters representing the grid.
     * @return true if the pattern is found and no other stray stars violate the pattern.
     */
    public boolean isValidPattern(String[] grid) {
        DetectionState state = DetectionState.SEARCHING_FOR_TOP;
        int topStarColumn = -1;
        int lastSignificantRowIndex = -1;

        for (int i = 0; i < grid.length; i++) {
            RowMetrics row = new RowMetrics(grid[i]);

            // Skip empty rows; they do not affect the pattern state
            if (row.starCount == 0) {
                continue;
            }

            switch (state) {
                case SEARCHING_FOR_TOP:
                    if (row.starCount == 1) {
                        topStarColumn = row.firstStarIndex;
                        lastSignificantRowIndex = i;
                        state = DetectionState.SEARCHING_FOR_BAR;
                    } else {
                        // If we find multiple stars before the top star, it's invalid
                        return false;
                    }
                    break;

                case SEARCHING_FOR_BAR:
                    // A bar must have 3+ stars, be contiguous, and strictly contain the top star column
                    if (row.starCount >= 3 && row.isContiguous &&
                            topStarColumn > row.firstStarIndex && topStarColumn < row.lastStarIndex) {
                        lastSignificantRowIndex = i;
                        state = DetectionState.SEARCHING_FOR_BOTTOM;
                    } else {
                        // Any other row with stars during this phase is invalid
                        return false;
                    }
                    break;

                case SEARCHING_FOR_BOTTOM:
                    // The bottom star must be a single star, in the same column, 
                    // and immediately follow the bar row
                    if (row.starCount == 1 && row.firstStarIndex == topStarColumn && i == lastSignificantRowIndex + 1) {
                        state = DetectionState.PATTERN_COMPLETE;
                        lastSignificantRowIndex = i;
                    } else {
                        return false;
                    }
                    break;

                case PATTERN_COMPLETE:
                    // If the pattern is already complete, any further stars are invalid
                    return false;

                default:
                    return false;
            }
        }

        return state == DetectionState.PATTERN_COMPLETE;
    }
}

import java.io.*;
import java.util.*;

/**
 * A utility to analyze a grid of characters to determine if all '*' characters 
 * form a single contiguous cross pattern.
 */
public class GridPatternFinder {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            char[][] grid = new char[rows][cols];
            int totalStars = 0;

            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                if (line == null) break;
                grid[i] = line.toCharArray();
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '*') {
                        totalStars++;
                    }
                }
            }

            if (hasSingleCrossPattern(rows, cols, grid, totalStars)) {
                out.println("YES");
            } else {
                out.println("NO");
            }

        } catch (Exception e) {
            // In a production environment, use a logger.
        } finally {
            out.close();
        }
    }

    /**
     * Determines if the entire set of '*' in the grid forms a single contiguous cross.
     *
     * @param rows        Number of rows in the grid.
     * @param cols        Number of columns in the grid.
     * @param grid        The character grid.
     * @param totalStars  The total count of '*' characters in the grid.
     * @return true if all '*' form a single cross, false otherwise.
     */
    private static boolean hasSingleCrossPattern(int rows, int cols, char[][] grid, int totalStars) {
        // A cross pattern (center + 4 neighbors) requires at least 5 stars.
        if (totalStars < 5) {
            return false;
        }

        // A cross center cannot be on the boundary of the grid.
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (isCrossCenter(i, j, grid)) {
                    int crossStarCount = countStarsInCross(i, j, rows, cols, grid);

                    // If the number of stars in this specific cross equals the total stars in the grid,
                    // then all stars are part of this single cross.
                    if (crossStarCount == totalStars) {
                        return true;
                    }
                }
            }
        }

        return false;
    }

    /**
     * Checks if the cell at (r, c) is a '*' and has '*' as its immediate cardinal neighbors.
     */
    private static boolean isCrossCenter(int r, int c, char[][] grid) {
        return grid[r][c] == '*' &&
               grid[r - 1][c] == '*' &&
               grid[r + 1][c] == '*' &&
               grid[r][c - 1] == '*' &&
               grid[r][c + 1] == '*';
    }

    /**
     * Counts the number of '*' connected to the center (r, c) in a cross shape.
     */
    private static int countStarsInCross(int r, int c, int rows, int cols, char[][] grid) {
        int count = 1; // Count the center star

        // Traverse Up
        for (int i = r - 1; i >= 0 && grid[i][c] == '*'; i--) {
            count++;
        }
        // Traverse Down
        for (int i = r + 1; i < rows && grid[i][c] == '*'; i++) {
            count++;
        }
        // Traverse Left
        for (int j = c - 1; j >= 0 && grid[r][j] == '*'; j--) {
            count++;
        }
        // Traverse Right
        for (int j = c + 1; j < cols && grid[r][j] == '*'; j++) {
            count++;
        }

        return count;
    }

    /**
     * Fast I/O class to handle large input efficiently.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
