import java.util.*;
import java.io.*;

/**
 * This program detects if a grid of characters contains exactly one "plus" shape 
 * made of stars ('*') and no other stars elsewhere in the grid.
 */
public class Codechef {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            // Read dimensions
            String firstLine = reader.nextLine();
            if (firstLine == null) {
                return;
            }
            StringTokenizer st = new StringTokenizer(firstLine);
            int rows = Integer.parseInt(st.nextToken());
            int cols = Integer.parseInt(st.nextToken());

            boolean[][] grid = new boolean[rows][cols];
            int totalStarCount = 0;

            // Parse grid and count total stars
            for (int i = 0; i < rows; i++) {
                String line = reader.nextLine();
                if (line != null) {
                    for (int j = 0; j < cols; j++) {
                        if (j < line.length() && line.charAt(j) == '*') {
                            grid[i][j] = true;
                            totalStarCount++;
                        }
                    }
                }
            }

            // Determine if the star distribution forms a perfect plus shape
            if (isPerfectPlusShape(grid, rows, cols, totalStarCount)) {
                out.println("YES");
            } else {
                out.println("NO");
            }

        } catch (Exception e) {
            out.println("NO");
        } finally {
            out.close();
        }
    }

    /**
     * Checks if the grid contains exactly one plus shape and no other stars.
     * 
     * @param grid The boolean representation of the star grid.
     * @param rows Total rows in the grid.
     * @param cols Total columns in the grid.
     * @param totalStars Total number of stars present in the grid.
     * @return true if the grid is a perfect plus shape, false otherwise.
     */
    private static boolean isPerfectPlusShape(boolean[][] grid, int rows, int cols, int totalStars) {
        // A plus shape requires at least 5 stars and a minimum 3x3 area
        if (totalStars < 5 || rows < 3 || cols < 3) {
            return false;
        }

        // Iterate through possible centers (excluding edges)
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                // A center must be a star and have immediate star neighbors in all 4 directions
                if (grid[i][j] && grid[i - 1][j] && grid[i + 1][j] && 
                    grid[i][j - 1] && grid[i][j + 1]) {

                    int plusSize = calculatePlusSize(grid, rows, cols, i, j);

                    // If the stars in this plus shape equal the total stars in the grid, it's a perfect plus.
                    // Due to the structure of a plus shape, there can only be one such center.
                    return plusSize == totalStars;
                }
            }
        }

        return false;
    }

    /**
     * Calculates the total number of stars that make up a plus shape centered at (r, c).
     */
    private static int calculatePlusSize(boolean[][] grid, int rows, int cols, int r, int c) {
        int count = 1; // Start with the center star

        // Add lengths of the four arms
        count += countArmLength(grid, rows, cols, r, c, -1, 0); // Up
        count += countArmLength(grid, rows, cols, r, c, 1, 0);  // Down
        count += countArmLength(grid, rows, cols, r, c, 0, -1); // Left
        count += countArmLength(grid, rows, cols, r, c, 0, 1);  // Right

        return count;
    }

    /**
     * Counts how many consecutive stars exist in a specific direction.
     */
    private static int countArmLength(boolean[][] grid, int rows, int cols, int r, int c, int dr, int dc) {
        int length = 0;
        int currR = r + dr;
        int currC = c + dc;

        while (currR >= 0 && currR < rows && currC >= 0 && currC < cols && grid[currR][currC]) {
            length++;
            currR += dr;
            currC += dc;
        }
        return length;
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private BufferedReader reader;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String nextLine() {
            try {
                return reader.readLine();
            } catch (IOException e) {
                return null;
            }
        }
    }
}

