/**
 * Handles the logic of determining if the star pattern forms exactly one plus shape.
 */
class PlusShapeSolver {
    private final char[][] grid;
    private final int numRows;
    private final int numCols;
    private int totalStarsCount;

    public PlusShapeSolver(char[][] grid, int numRows, int numCols) {
        this.grid = grid;
        this.numRows = numRows;
        this.numCols = numCols;
        this.totalStarsCount = countTotalStars();
    }

    /**
     * Orchestrates the verification process.
     * @return "YES" if the grid contains exactly one plus shape and no other stars, else "NO".
     */
    public String solve() {
        if (totalStarsCount == 0) {
            return "NO";
        }

        List<int[]> centers = findPlusCenters();

        // A valid single plus must have exactly one center.
        if (centers.size() != 1) {
            return "NO";
        }

        int[] center = centers.get(0);
        int starsInPlus = countStarsInPlus(center[0], center[1]);

        // If the stars covered by the plus match the total star count, it's a valid shape.
        return (starsInPlus == totalStarsCount) ? "YES" : "NO";
    }

    private int countTotalStars() {
        int count = 0;
        for (int i = 0; i < numRows; i++) {
            for (int j = 0; j < numCols; j++) {
                if (grid[i][j] == '*') {
                    count++;
                }
            }
        }
        return count;
    }

    private List<int[]> findPlusCenters() {
        List<int[]> centers = new ArrayList<>();
        // A center cannot be on the edge because it needs 4 neighbors.
        for (int i = 1; i < numRows - 1; i++) {
            for (int j = 1; j < numCols - 1; j++) {
                if (isCenter(i, j)) {
                    centers.add(new int[]{i, j});
                }
            }
        }
        return centers;
    }

    private boolean isCenter(int r, int c) {
        return grid[r][c] == '*' &&
               grid[r - 1][c] == '*' &&
               grid[r + 1][c] == '*' &&
               grid[r][c - 1] == '*' &&
               grid[r][c + 1] == '*';
    }

    private int countStarsInPlus(int r, int c) {
        int count = 1; // Start with the center star
        int[][] directions = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

        for (int[] dir : directions) {
            count += countArmLength(r + dir[0], c + dir[1], dir[0], dir[1]);
        }
        return count;
    }

    private int countArmLength(int r, int c, int dr, int dc) {
        int length = 0;
        while (r >= 0 && r < numRows && c >= 0 && c < numCols && grid[r][c] == '*') {
            length++;
            r += dr;
            c += dc;
        }
        return length;
    }
}

/**
 * Optimized reader for fast character and integer input.
 */
class FastReader implements AutoCloseable {
    private final InputStream inputStream;
    private final byte[] buffer = new byte[1024];
    private int curChar;
    private int numChars;

    public FastReader(InputStream inputStream) {
        this.inputStream = inputStream;
    }

    private int read() throws IOException {
        if (numChars == -1) return -1;
        if (curChar >= numChars) {
            curChar = 0;
            numChars = inputStream.read(buffer);
            if (numChars <= 0) return -1;
        }
        return buffer[curChar++];
    }

    public int nextInt() throws IOException {
        int c = read();
        while (c != -1 && isSpaceChar(c)) c = read();
        if (c == -1) throw new InputMismatchException();
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        int res = 0;
        do {
            if (c < '0' || c > '9') throw new InputMismatchException();
            res = res * 10 + (c - '0');
            c = read();
        } while (c != -1 && !isSpaceChar(c));
        return res * sgn;
    }

    public char nextChar() throws IOException {
        int c = read();
        while (c != -1 && isSpaceChar(c)) c = read();
        if (c == -1) throw new InputMismatchException();
        return (char) c;
    }

    private boolean isSpaceChar(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    @Override
    public void close() throws IOException {
        inputStream.close();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * A utility to validate if a given grid of characters forms a single, 
 * contiguous "+" (plus) shape.
 */
public class PlusShapeValidator {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        try {
            int height = reader.nextInt();
            int width = reader.nextInt();

            if (height <= 0 || width <= 0) {
                System.out.println("NO");
                return;
            }

            boolean[][] grid = new boolean[height][width];
            for (int i = 0; i < height; i++) {
                String line = reader.next();
                for (int j = 0; j < width; j++) {
                    grid[i][j] = (line.charAt(j) == '*');
                }
            }

            if (isValidPlusShape(height, width, grid)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }

        } catch (IOException | NumberFormatException e) {
            // In a production environment, use a logger.
            System.out.println("NO");
        }
    }

    /**
     * Orchestrates the validation of the plus shape.
     */
    private static boolean isValidPlusShape(int height, int width, boolean[][] grid) {
        int[] intersection = findIntersectionPoint(height, width, grid);

        // If no cell is found that is surrounded by 4 stars, it cannot be a plus shape.
        if (intersection == null) {
            return false;
        }

        int r = intersection[0];
        int c = intersection[1];

        // 1. Verify that every '*' in the grid lies strictly on the intersection's row or column.
        for (int i = 0; i < height; i++) {
            for (int j = 0; j < width; j++) {
                if (grid[i][j] && i != r && j != c) {
                    return false;
                }
            }
        }

        // 2. Verify that the stars in the intersection row form exactly one contiguous segment.
        if (!isRowContiguous(grid, r)) {
            return false;
        }

        // 3. Verify that the stars in the intersection column form exactly one contiguous segment.
        if (!isColumnContiguous(grid, c)) {
            return false;
        }

        return true;
    }

    /**
     * Searches for the center of the plus shape (a '*' surrounded by 4 '*' neighbors).
     * @return An array containing {row, col} if found, otherwise null.
     */
    private static int[] findIntersectionPoint(int height, int width, boolean[][] grid) {
        int[] rowOffsets = {1, -1, 0, 0};
        int[] colOffsets = {0, 0, 1, -1};

        // Intersection must be at least 1 cell away from any boundary to have 4 neighbors.
        for (int i = 1; i < height - 1; i++) {
            for (int j = 1; j < width - 1; j++) {
                if (grid[i][j]) {
                    boolean isSurrounded = true;
                    for (int k = 0; k < 4; k++) {
                        if (!grid[i + rowOffsets[k]][j + colOffsets[k]]) {
                            isSurrounded = false;
                            break;
                        }
                    }
                    if (isSurrounded) {
                        return new int[]{i, j};
                    }
                }
            }
        }
        return null;
    }

    /**
     * Checks if the '*' cells in a specific row form one continuous block.
     */
    private static boolean isRowContiguous(boolean[][] grid, int row) {
        int first = -1, last = -1, count = 0;
        int width = grid[0].length;

        for (int j = 0; j < width; j++) {
            if (grid[row][j]) {
                if (first == -1) first = j;
                last = j;
                count++;
            }
        }
        // A segment is contiguous if the distance between first and last matches the count.
        return count > 0 && (last - first + 1) == count;
    }

    /**
     * Checks if the '*' cells in a specific column form one continuous block.
     */
    private static boolean isColumnContiguous(boolean[][] grid, int col) {
        int first = -1, last = -1, count = 0;
        int height = grid.length;

        for (int i = 0; i < height; i++) {
            if (grid[i][col]) {
                if (first == -1) first = i;
                last = i;
                count++;
            }
        }
        return count > 0 && (last - first + 1) == count;
    }

    /**
     * High-performance reader for large inputs.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A program that detects if the '*' characters in a grid form a single "+" shape.
 * A "+" shape is defined as a single connected component where exactly one 
 * central star has four neighbors and all other stars in that component 
 * have exactly one neighbor.
 */
public class StarPatternDetector {

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final boolean[][] visited;

    private int componentCount = 0;
    private int fourNeighborCount = 0;
    private int multiNeighborCount = 0;

    // Directional offsets for exploring adjacent cells (Up, Down, Left, Right)
    private static final int[] ROW_OFFSETS = {1, 0, -1, 0};
    private static final int[] COL_OFFSETS = {0, 1, 0, -1};

    /**
     * Constructs a detector for a specific grid.
     *
     * @param rows Number of rows in the grid.
     * @param cols Number of columns in the grid.
     * @param grid The character grid containing '*' and '.'.
     */
    public StarPatternDetector(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.visited = new boolean[rows][cols];
    }

    /**
     * Analyzes the grid to determine if the '+' pattern exists.
     *
     * @return true if exactly one '+' shaped component is found, false otherwise.
     */
    public boolean isPlusPatternPresent() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (isStar(i, j) && !visited[i][j]) {
                    componentCount++;
                    performDFS(i, j);
                }
            }
        }

        // The pattern matches if:
        // 1. There is exactly one connected component of stars.
        // 2. Exactly one star has 4 neighbors (the center).
        // 3. Exactly one star has more than 1 neighbor (the center itself).
        return componentCount == 1 && fourNeighborCount == 1 && multiNeighborCount == 1;
    }

    /**
     * Performs a Depth First Search to traverse a connected component of stars.
     */
    private void performDFS(int r, int c) {
        visited[r][c] = true;
        int neighbors = countAdjacentStars(r, c);

        if (neighbors == 4) {
            fourNeighborCount++;
        }

        if (neighbors > 1) {
            multiNeighborCount++;
        }

        for (int i = 0; i < 4; i++) {
            int nextR = r + ROW_OFFSETS[i];
            int nextC = c + COL_OFFSETS[i];

            if (isStar(nextR, nextC) && !visited[nextR][nextC]) {
                performDFS(nextR, nextC);
            }
        }
    }

    /**
     * Counts how many adjacent cells (Up, Down, Left, Right) contain a star.
     */
    private int countAdjacentStars(int r, int c) {
        int count = 0;
        for (int i = 0; i < 4; i++) {
            if (isStar(r + ROW_OFFSETS[i], c + COL_OFFSETS[i])) {
                count++;
            }
        }
        return count;
    }

    /**
     * Helper to check if a coordinate is within bounds and contains a star.
     */
    private boolean isStar(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] == '*';
    }

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        try {
            String nInput = reader.next();
            if (nInput == null) return;

            int n = Integer.parseInt(nInput);
            int m = reader.nextInt();

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                grid[i] = reader.next().toCharArray();
            }

            StarPatternDetector detector = new StarPatternDetector(n, m, grid);

            if (detector.isPlusPatternPresent()) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        } catch (Exception e) {
            // In production, use a logger
            System.err.println("Error processing input: " + e.getMessage());
        }
    }

    /**
     * Optimized reader for fast input processing.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

/**
 * Represents a grid of characters and provides logic to identify 
 * and process specific star patterns.
 */
class StarGrid {
    private final int rows;
    private final int cols;
    private final char[][] grid;

    public StarGrid(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
    }

    /**
     * Determines if the grid contains exactly one cross pattern that, 
     * when cleared, leaves no other stars in the grid.
     * 
     * @return true if the condition is met, false otherwise.
     */
    public boolean isValidPattern() {
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (isCrossCenter(i, j)) {
                    clearCrossLines(i, j);
                    return !hasRemainingStars();
                }
            }
        }
        return false;
    }

    /**
     * Checks if the cell at (r, c) is the center of a '+' shaped cross.
     */
    private boolean isCrossCenter(int r, int c) {
        return grid[r][c] == '*' &&
               grid[r + 1][c] == '*' &&
               grid[r - 1][c] == '*' &&
               grid[r][c - 1] == '*' &&
               grid[r][c + 1] == '*';
    }

    /**
     * Clears the continuous vertical and horizontal lines of stars 
     * extending from the given center point.
     */
    private void clearCrossLines(int r, int c) {
        grid[r][c] = '.';

        // Clear vertical line (Up and Down)
        for (int i = r + 1; i < rows && grid[i][c] == '*'; i++) {
            grid[i][c] = '.';
        }
        for (int i = r - 1; i >= 0 && grid[i][c] == '*'; i--) {
            grid[i][c] = '.';
        }

        // Clear horizontal line (Left and Right)
        for (int j = c + 1; j < cols && grid[r][j] == '*'; j++) {
            grid[r][j] = '.';
        }
        for (int j = c - 1; j >= 0 && grid[r][j] == '*'; j--) {
            grid[r][j] = '.';
        }
    }

    /**
     * Scans the entire grid to see if any stars remain.
     */
    private boolean hasRemainingStars() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*') {
                    return true;
                }
            }
        }
        return false;
    }
}

public class Main {
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;

            int height = scanner.nextInt();
            int width = scanner.nextInt();
            scanner.nextLine(); // Consume leftover newline

            char[][] grid = new char[height][width];
            for (int i = 0; i < height; i++) {
                String line = scanner.nextLine();
                // Convert string to char array safely
                grid[i] = line.toCharArray();
            }

            StarGrid starGrid = new StarGrid(height, width, grid);

            if (starGrid.isValidPattern()) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        } catch (Exception e) {
            // In a real production environment, use a logging framework
            System.err.println("An error occurred during processing: " + e.getMessage());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * A utility to determine if the stars (*) in a grid form a single, continuous cross shape.
 */
public class CrossShapeChecker {

    /**
     * Represents a coordinate in the grid.
     */
    private record Point(int row, int col) {}

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        // Read grid dimensions
        String nStr = reader.next();
        String mStr = reader.next();
        if (nStr == null || mStr == null) return;

        int rows = Integer.parseInt(nStr);
        int cols = Integer.parseInt(mStr);

        char[][] grid = new char[rows][cols];
        int totalStarsCount = 0;

        // Populate grid and count total stars
        for (int i = 0; i < rows; i++) {
            String line = reader.next();
            if (line == null) break;
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] == '*') {
                    totalStarsCount++;
                }
            }
        }

        // A valid cross must have at least 5 stars and a 3x3 minimum area
        if (totalStarsCount < 5 || rows < 3 || cols < 3) {
            System.out.println("NO");
            return;
        }

        // 1. Find the center of the cross
        Point center = findCrossCenter(grid, rows, cols);
        if (center == null) {
            System.out.println("NO");
            return;
        }

        // 2. Validate the horizontal segment of the cross
        int rowStarsCount = 0;
        int minCol = cols, maxCol = -1;
        for (int j = 0; j < cols; j++) {
            if (grid[center.row][j] == '*') {
                rowStarsCount++;
                minCol = Math.min(minCol, j);
                maxCol = Math.max(maxCol, j);
            }
        }

        // 3. Validate the vertical segment of the cross
        int colStarsCount = 0;
        int minRow = rows, maxRow = -1;
        for (int i = 0; i < rows; i++) {
            if (grid[i][center.col] == '*') {
                colStarsCount++;
                minRow = Math.min(minRow, i);
                maxRow = Math.max(maxRow, i);
            }
        }

        // 4. Final Validation
        // - The row stars must form a single contiguous block
        // - The column stars must form a single contiguous block
        // - The total number of stars in the grid must exactly equal the stars in the cross
        //   (Note: the center star is counted in both rowStarsCount and colStarsCount, so we subtract 1)
        boolean isRowContiguous = (maxCol - minCol + 1 == rowStarsCount);
        boolean isColContiguous = (maxRow - minRow + 1 == colStarsCount);
        boolean isAllStarsAccountedFor = (rowStarsCount + colStarsCount - 1 == totalStarsCount);

        if (isRowContiguous && isColContiguous && isAllStarsAccountedFor) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Searches for a center point that has four immediate star neighbors.
     */
    private static Point findCrossCenter(char[][] grid, int rows, int cols) {
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (isCenter(grid, i, j)) {
                    return new Point(i, j);
                }
            }
        }
        return null;
    }

    private static boolean isCenter(char[][] grid, int r, int c) {
        return grid[r][c] == '*' &&
               grid[r - 1][c] == '*' &&
               grid[r + 1][c] == '*' &&
               grid[r][c - 1] == '*' &&
               grid[r][c + 1] == '*';
    }

    /**
     * Efficient reader for large input.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }
    }
}

import java.util.Scanner;

/**
 * The CrossPatternDetector class determines if the '*' characters in a 2D grid 
 * form a single, perfect cross shape.
 * 
 * A perfect cross is defined as:
 * 1. Having a central '*' character.
 * 2. Having arms of '*' characters extending in all four cardinal directions (Up, Down, Left, Right).
 * 3. Every '*' in the grid must be part of this single cross shape.
 * 4. Each arm must contain at least one '*' character.
 */
public class CrossPatternDetector {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        scanner.nextLine(); // Consume the remaining newline character

        String[] grid = new String[rows];
        int totalStars = 0;

        // Read the grid and count the total number of '*' characters
        for (int i = 0; i < rows; i++) {
            if (scanner.hasNextLine()) {
                grid[i] = scanner.nextLine();
                for (int j = 0; j < grid[i].length(); j++) {
                    if (grid[i].charAt(j) == '*') {
                        totalStars++;
                    }
                }
            }
        }

        if (isPerfectCrossPresent(grid, rows, cols, totalStars)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Iterates through the grid to find if any '*' character serves as the center of a perfect cross.
     *
     * @param grid       The 2D grid of characters.
     * @param rows       The number of rows in the grid.
     * @param cols       The number of columns in the grid.
     * @param totalStars The total count of '*' characters in the entire grid.
     * @return true if a perfect cross is found, false otherwise.
     */
    private static boolean isPerfectCrossPresent(String[] grid, int rows, int cols, int totalStars) {
        // A perfect cross requires at least 5 stars (1 center + 4 arms of at least 1 star each)
        if (totalStars < 5) {
            return false;
        }

        for (int r = 0; r < rows; r++) {
            if (grid[r] == null) continue;

            for (int c = 0; c < Math.min(cols, grid[r].length()); c++) {
                if (grid[r].charAt(c) == '*') {
                    if (checkIfCenterOfCross(grid, r, c, rows, cols, totalStars)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if the star at the specified coordinates is the center of a cross 
     * that accounts for all stars in the grid.
     *
     * @param grid       The 2D grid.
     * @param r          The row index of the candidate center.
     * @param c          The column index of the candidate center.
     * @param rows       Total rows in the grid.
     * @param cols       Total columns in the grid.
     * @param totalStars The total number of stars present in the grid.
     * @return true if the star is a valid center for a perfect cross.
     */
    private static boolean checkIfCenterOfCross(String[] grid, int r, int c, int rows, int cols, int totalStars) {
        int left = countConsecutiveStars(grid, r, c, 0, -1, rows, cols);
        int right = countConsecutiveStars(grid, r, c, 0, 1, rows, cols);
        int up = countConsecutiveStars(grid, r, c, -1, 0, rows, cols);
        int down = countConsecutiveStars(grid, r, c, 1, 0, rows, cols);

        // Requirement: All four arms must have at least one '*' character.
        if (left > 0 && right > 0 && up > 0 && down > 0) {
            // Requirement: The sum of stars in the cross must equal the total stars in the grid.
            int starsInThisCross = 1 + left + right + up + down;
            return starsInThisCross == totalStars;
        }

        return false;
    }

    /**
     * Counts the number of consecutive '*' characters in a specific direction.
     *
     * @param grid    The 2D grid.
     * @param r       Starting row index.
     * @param c       Starting column index.
     * @param dr      Row direction offset (-1, 0, or 1).
     * @param dc      Column direction offset (-1, 0, or 1).
     * @param rows    Total rows in the grid.
     * @param cols    Total columns in the grid.
     * @return The number of consecutive stars in the direction (dr, dc).
     */
    private static int countConsecutiveStars(String[] grid, int r, int c, int dr, int dc, int rows, int cols) {
        int count = 0;
        int currentR = r + dr;
        int currentC = c + dc;

        while (currentR >= 0 && currentR < rows && 
               currentC >= 0 && currentC < cols && 
               grid[currentR] != null && 
               currentC < grid[currentR].length() && 
               grid[currentR].charAt(currentC) == '*') {
            count++;
            currentR += dr;
            currentC += dc;
        }
        return count;
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.InputMismatchException;

/**
 * Main entry point for the application.
 */
public class Main {
    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            PlusShapeSolver solver = new PlusShapeSolver();
            solver.solve(reader, writer);
        } finally {
            writer.close();
        }
    }

    /**
     * Logic to determine if the provided grid contains a plus shape 
     * that encompasses all '*' characters in the grid.
     */
    static class PlusShapeSolver {

        public void solve(FastReader in, PrintWriter out) {
            int height = in.nextInt();
            int width = in.nextInt();

            boolean[][] grid = new boolean[height][width];
            int totalStarCount = 0;

            // Parse the grid and count total '*' characters
            for (int i = 0; i < height; i++) {
                String row = in.next();
                for (int j = 0; j < width; j++) {
                    if (row.charAt(j) == '*') {
                        grid[i][j] = true;
                        totalStarCount++;
                    }
                }
            }

            if (isPlusShapePresent(grid, height, width, totalStarCount)) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        }

        private boolean isPlusShapePresent(boolean[][] grid, int h, int w, int totalStars) {
            // A plus shape must have at least 5 stars (center + 4 arms of length 1)
            if (totalStars < 5) return false;

            for (int r = 0; r < h; r++) {
                for (int c = 0; c < w; c++) {
                    // A potential center must be a '*'
                    if (grid[r][c]) {
                        if (isValidPlusCenter(grid, r, c, h, w, totalStars)) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        private boolean isValidPlusCenter(boolean[][] grid, int r, int c, int h, int w, int totalStars) {
            // Directions: Up, Down, Left, Right
            int up = countConsecutive(grid, r, c, -1, 0, h, w);
            int down = countConsecutive(grid, r, c, 1, 0, h, w);
            int left = countConsecutive(grid, r, c, 0, -1, h, w);
            int right = countConsecutive(grid, r, c, 0, 1, h, w);

            // A valid plus must have arms in all four directions (length >= 1)
            // and the sum of arms + center must equal the total number of '*' in the grid.
            boolean hasAllArms = (up > 0 && down > 0 && left > 0 && right > 0);
            boolean usesAllStars = (up + down + left + right + 1 == totalStars);

            return hasAllArms && usesAllStars;
        }

        /**
         * Counts consecutive '*' in a specific direction from (row, col).
         * Does not include the starting cell (row, col) itself.
         */
        private int countConsecutive(boolean[][] grid, int row, int col, int dr, int dc, int h, int w) {
            int count = 0;
            int currR = row + dr;
            int currC = col + dc;

            while (currR >= 0 && currR < h && currC >= 0 && currC < w && grid[currR][currC]) {
                count++;
                currR += dr;
                currC += dc;
            }
            return count;
        }
    }

    /**
     * High-performance custom reader for fast I/O operations.
     */
    static class FastReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int curChar;
        private int numChars;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (numChars == -1) throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buffer);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) return -1;
            }
            return buffer[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res = res * 10 + (c - '0');
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.util.Scanner;

/**
 * A program to determine if a character grid contains exactly one cross pattern
 * made of '*' characters, and no other '*' characters elsewhere in the grid.
 */
public class Solution {

    private static final char TARGET_CHAR = '*';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        try {
            if (!scanner.hasNextInt()) return;
            int rows = scanner.nextInt();

            if (!scanner.hasNextInt()) return;
            int cols = scanner.nextInt();

            char[][] grid = new char[rows][cols];
            int totalStarCount = 0;

            // Read the grid and count total occurrences of the target character
            for (int i = 0; i < rows; i++) {
                String rowString = scanner.next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = rowString.charAt(j);
                    if (grid[i][j] == TARGET_CHAR) {
                        totalStarCount++;
                    }
                }
            }

            if (isSingleCrossPattern(grid, rows, cols, totalStarCount)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        } catch (Exception e) {
            // In case of unexpected input format, default to NO
            System.out.println("NO");
        } finally {
            scanner.close();
        }
    }

    /**
     * Determines if the grid contains exactly one valid cross pattern that
     * accounts for every target character found in the grid.
     *
     * @param grid           The 2D character grid.
     * @param rows           Number of rows in the grid.
     * @param cols           Number of columns in the grid.
     * @param totalStarCount The total number of '*' found in the grid.
     * @return true if exactly one cross pattern is found covering all stars.
     */
    private static boolean isSingleCrossPattern(char[][] grid, int rows, int cols, int totalStarCount) {
        int centerRow = -1;
        int centerCol = -1;
        int centerCandidateCount = 0;

        // A cross center must be in the interior (not on the edge) to have 4 neighbors.
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (isCandidateCenter(grid, i, j)) {
                    centerRow = i;
                    centerCol = j;
                    centerCandidateCount++;
                }
            }
        }

        // If there isn't exactly one center, it cannot be a single valid cross pattern.
        if (centerCandidateCount != 1) {
            return false;
        }

        return verifyCrossCoversAllStars(grid, rows, cols, centerRow, centerCol, totalStarCount);
    }

    /**
     * A cell is a candidate center if all four of its cardinal neighbors are the target character.
     */
    private static boolean isCandidateCenter(char[][] grid, int r, int c) {
        return grid[r - 1][c] == TARGET_CHAR &&
               grid[r + 1][c] == TARGET_CHAR &&
               grid[r][c - 1] == TARGET_CHAR &&
               grid[r][c + 1] == TARGET_CHAR;
    }

    /**
     * Verifies if all '*' characters in the grid belong to the cross centered at (r, c).
     *
     * @param grid           The 2D character grid.
     * @param rows           Number of rows.
     * @param cols           Number of columns.
     * @param r              The row index of the potential center.
     * @param c              The column index of the potential center.
     * @param totalStarCount The total number of '*' in the grid.
     * @return true if the stars in the cross match the total star count.
     */
    private static boolean verifyCrossCoversAllStars(char[][] grid, int rows, int cols, int r, int c, int totalStarCount) {
        int remainingStars = totalStarCount;

        // Subtract stars in the vertical line (starting from center and going up)
        for (int i = r; i >= 0 && grid[i][c] == TARGET_CHAR; i--) {
            remainingStars--;
        }
        // Subtract stars in the vertical line (going down)
        for (int i = r + 1; i < rows && grid[i][c] == TARGET_CHAR; i++) {
            remainingStars--;
        }

        // Subtract stars in the horizontal line (going left)
        for (int j = c - 1; j >= 0 && grid[r][j] == TARGET_CHAR; j--) {
            remainingStars--;
        }
        // Subtract stars in the horizontal line (going right)
        for (int j = c + 1; j < cols && grid[r][j] == TARGET_CHAR; j++) {
            remainingStars--;
        }

        // If remainingStars is 0, every star in the grid was part of the identified cross.
        return remainingStars == 0;
    }
}

import java.io.*;
import java.util.*;

/**
 * This program validates if the '*' characters in a grid form exactly one 
 * single-pixel wide cross shape.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        // Read grid dimensions
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        // Handle edge cases for empty or invalid dimensions
        if (rows <= 0 || cols <= 0) {
            System.out.println("NO");
            return;
        }

        char[][] grid = new char[rows][cols];
        int totalStars = 0;

        // Read the grid and count total stars present
        for (int i = 0; i < rows; i++) {
            String line = reader.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] == '*') {
                    totalStars++;
                }
            }
        }

        // A cross must have stars; if no stars, it's not a cross
        if (totalStars == 0) {
            System.out.println("NO");
            return;
        }

        // Find the potential center of the cross.
        // A center is defined as a '*' with four immediate '*' neighbors.
        int centerX = -1;
        int centerY = -1;

        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (isPotentialCenter(grid, i, j)) {
                    centerX = i;
                    centerY = j;
                    break;
                }
            }
            if (centerX != -1) break;
        }

        // If no center is found, it cannot be a single cross
        if (centerX == -1) {
            System.out.println("NO");
            return;
        }

        // Calculate the number of stars that belong to the cross centered at (centerX, centerY)
        int crossStarsCount = countCrossStars(grid, centerX, centerY, rows, cols);

        // If the number of stars in the detected cross matches the total stars in the grid,
        // it means there are no extra stars elsewhere.
        if (crossStarsCount == totalStars) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Checks if a cell is a valid center (star with 4 star neighbors).
     */
    private static boolean isPotentialCenter(char[][] grid, int r, int c) {
        return grid[r][c] == '*' &&
               grid[r - 1][c] == '*' &&
               grid[r + 1][c] == '*' &&
               grid[r][c - 1] == '*' &&
               grid[r][c + 1] == '*';
    }

    /**
     * Counts all '*' stars that form the cross structure from the given center.
     */
    private static int countCrossStars(char[][] grid, int r, int c, int rows, int cols) {
        int count = 1; // Count the center star

        // Check Up
        for (int i = r - 1; i >= 0 && grid[i][c] == '*'; i--) count++;
        // Check Down
        for (int i = r + 1; i < rows && grid[i][c] == '*'; i++) count++;
        // Check Left
        for (int j = c - 1; j >= 0 && grid[r][j] == '*'; j--) count++;
        // Check Right
        for (int j = c + 1; j < cols && grid[r][j] == '*'; j++) count++;

        return count;
    }

    /**
     * Fast I/O utility class for efficient reading.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;

/**
 * A program to determine if a grid of characters contains exactly one cross pattern
 * that accounts for all '*' characters in the grid.
 */
public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Ensure input exists before reading
        if (!scanner.hasNextInt()) {
            return;
        }

        int height = scanner.nextInt();
        int width = scanner.nextInt();

        // A cross requires at least a 3x3 area to exist
        if (height < 3 || width < 3) {
            System.out.println("NO");
            return;
        }

        boolean[][] grid = new boolean[height][width];
        int totalStars = 0;

        // Consume the remaining newline character after nextInt() to prevent empty line reads
        if (scanner.hasNextLine()) {
            scanner.nextLine();
        }

        // Populate the grid and count total stars
        for (int i = 0; i < height; i++) {
            if (scanner.hasNextLine()) {
                String line = scanner.nextLine();
                for (int j = 0; j < width; j++) {
                    if (j < line.length() && line.charAt(j) == '*') {
                        grid[i][j] = true;
                        totalStars++;
                    }
                }
            }
        }

        if (isSingleCross(grid, height, width, totalStars)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Evaluates whether the grid contains exactly one cross pattern 
     * that encompasses all stars present in the grid.
     *
     * @param grid       The 2D boolean grid representing the stars.
     * @param height     The height of the grid.
     * @param width      The width of the grid.
     * @param totalStars The total number of '*' characters found in the grid.
     * @return true if a single cross accounts for all stars, false otherwise.
     */
    private static boolean isSingleCross(boolean[][] grid, int height, int width, int totalStars) {
        // A cross must consist of at least 5 stars (center + 4 neighbors)
        if (totalStars < 5) {
            return false;
        }

        // Search for a cross center (cannot be on the boundary)
        for (int r = 1; r < height - 1; r++) {
            for (int c = 1; c < width - 1; c++) {
                if (isCrossCenter(grid, r, c)) {
                    // If a cross is found, check if it is the ONLY thing in the grid
                    if (doesCrossAccountForAllStars(grid, r, c, height, width, totalStars)) {
                        return true;
                    }
                }
            }
        }

        return false;
    }

    /**
     * Checks if the cell at (r, c) acts as the center of a 5-star cross.
     */
    private static boolean isCrossCenter(boolean[][] grid, int r, int c) {
        return grid[r][c] &&           // Center
               grid[r - 1][c] &&       // Up
               grid[r + 1][c] &&       // Down
               grid[r][c - 1] &&       // Left
               grid[r][c + 1];         // Right
    }

    /**
     * Validates if all stars in the grid lie on the row or column of the given center.
     *
     * @param grid       The grid.
     * @param r          Row index of the cross center.
     * @param c          Column index of the cross center.
     * @param height     Grid height.
     * @param width      Grid width.
     * @param totalStars Total '*' count in the grid.
     * @return true if the stars in the cross's row and column equal the total star count.
     */
    private static boolean doesCrossAccountForAllStars(boolean[][] grid, int r, int c, 
                                                       int height, int width, int totalStars) {
        int starsInRow = 0;
        for (int j = 0; j < width; j++) {
            if (grid[r][j]) {
                starsInRow++;
            }
        }

        int starsInCol = 0;
        for (int i = 0; i < height; i++) {
            if (grid[i][c]) {
                starsInCol++;
            }
        }

        // The number of stars covered by the cross is the stars in its row 
        // plus the stars in its column. We subtract 1 to avoid double-counting 
        // the center cell (r, c).
        int coveredStars = starsInRow + starsInCol - 1;

        return coveredStars == totalStars;
    }
}

import java.util.*;
