/**
 * A program that detects if all '*' characters in a grid form a single, 
 * continuous cross shape with straight orthogonal arms.
 */
public class CrossShapeDetector {

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);

        int height;
        int width;
        try {
            height = sc.nextInt();
            width = sc.nextInt();
        } catch (Exception e) {
            return;
        }

        char[][] grid = new char[height][width];
        for (int i = 0; i < height; i++) {
            grid[i] = sc.next().toCharArray();
        }

        if (isValidCrossShape(height, width, grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Core logic to determine if the grid forms a valid cross.
     */
    private static boolean isValidCrossShape(int h, int w, char[][] grid) {
        int centerCount = 0;
        int centerX = -1;
        int centerY = -1;

        // 1. Find the potential center of the cross
        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                if (isPotentialCenter(grid, i, j, h, w)) {
                    centerCount++;
                    centerX = i;
                    centerY = j;
                }
            }
        }

        // A valid cross must have exactly one unique center point
        if (centerCount != 1) {
            return false;
        }

        // 2. Mark all cells that belong to the arms of this center
        boolean[][] isPartOfCross = new boolean[h][w];
        markArms(grid, isPartOfCross, centerX, centerY, h, w);

        // 3. Verify that every '*' in the grid was marked as part of the cross
        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                if (grid[i][j] == '*' && !isPartOfCross[i][j]) {
                    return false;
                }
            }
        }

        return true;
    }

    /**
     * Checks if a cell (r, c) is a valid center: 
     * 4 orthogonal neighbors are '*' and 4 diagonal neighbors are NOT '*'.
     */
    private static boolean isPotentialCenter(char[][] grid, int r, int c, int h, int w) {
        if (grid[r][c] != '*') {
            return false;
        }

        // Check orthogonal neighbors (must be '*' and within bounds)
        boolean hasOrthogonalNeighbors = 
            isInside(r - 1, c, h, w) && grid[r - 1][c] == '*' &&
            isInside(r + 1, c, h, w) && grid[r + 1][c] == '*' &&
            isInside(r, c - 1, h, w) && grid[r][c - 1] == '*' &&
            isInside(r, c + 1, h, w) && grid[r][c + 1] == '*';

        if (!hasOrthogonalNeighbors) {
            return false;
        }

        // Check diagonal neighbors (must NOT be '*')
        // Since orthogonal neighbors are validated, diagonals are guaranteed to be in bounds
        if (grid[r - 1][c - 1] == '*' || grid[r - 1][c + 1] == '*' ||
            grid[r + 1][c - 1] == '*' || grid[r + 1][c + 1] == '*') {
            return false;
        }

        return true;
    }

    /**
     * Traverses in four directions from the center and marks '*' cells as part of the cross.
     */
    private static void markArms(char[][] grid, boolean[][] marked, int r, int c, int h, int w) {
        int[] dr = {-1, 1, 0, 0}; // Up, Down, Left, Right
        int[] dc = {0, 0, -1, 1};

        for (int i = 0; i < 4; i++) {
            int currR = r;
            int currC = c;
            // Traverse the arm until we hit a boundary or a non-'*' cell
            while (isInside(currR, currC, h, w) && grid[currR][currC] == '*') {
                marked[currR][currC] = true;
                currR += dr[i];
                currC += dc[i];
            }
        }
    }

    private static boolean isInside(int r, int c, int h, int w) {
        return r >= 0 && r < h && c >= 0 && c < w;
    }

    /**
     * Fast I/O utility class.
     */
    static class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }
    }
}

import java.util.Scanner;

/**
 * StarGridAnalyzer identifies if a grid of characters contains exactly one 
 * star-shaped pattern that accounts for all '*' characters in the grid.
 * A star pattern is defined as a center '*' with arms extending in four 
 * cardinal directions.
 */
public class StarGridAnalyzer {

    private static final char STAR = '*';

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            // The original code treats the first input as number of rows 
            // and the second as the length of each row.
            int rowCount = scanner.nextInt();
            int colCount = scanner.nextInt();

            char[][] grid = new char[rowCount][colCount];
            int totalStarCount = 0;

            for (int i = 0; i < rowCount; i++) {
                String rowString = scanner.next();
                for (int j = 0; j < colCount; j++) {
                    grid[i][j] = rowString.charAt(j);
                    if (grid[i][j] == STAR) {
                        totalStarCount++;
                    }
                }
            }

            if (isStarPatternComplete(grid, rowCount, colCount, totalStarCount)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /**
     * Evaluates whether the grid contains exactly one star shape that 
     * encompasses every '*' character present in the grid.
     *
     * @param grid            The 2D grid of characters.
     * @param rows            Number of rows in the grid.
     * @param cols            Number of columns in the grid.
     * @param totalStarCount  The total number of '*' characters found in the grid.
     * @return true if a single star shape covers all stars, false otherwise.
     */
    private static boolean isStarPatternComplete(char[][] grid, int rows, int cols, int totalStarCount) {
        // A star shape requires at least a 3x3 area and at least one star.
        if (rows < 3 || cols < 3 || totalStarCount == 0) {
            return false;
        }

        // Iterate through the grid, excluding edges, to find a potential center.
        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < cols - 1; c++) {
                if (isPotentialCenter(grid, r, c)) {
                    int starShapeSize = calculateStarSize(grid, r, c, rows, cols);

                    // If the star shape found accounts for all stars in the grid, we are done.
                    if (starShapeSize == totalStarCount) {
                        return true;
                    }
                }
            }
        }

        return false;
    }

    /**
     * Checks if the specified cell and its four immediate neighbors are stars.
     */
    private static boolean isPotentialCenter(char[][] grid, int r, int c) {
        return grid[r][c] == STAR &&
               grid[r - 1][c] == STAR &&
               grid[r + 1][c] == STAR &&
               grid[r][c - 1] == STAR &&
               grid[r][c + 1] == STAR;
    }

    /**
     * Calculates the total number of '*' in a star pattern centered at (r, c).
     * The pattern expands as far as possible in all four cardinal directions.
     */
    private static int calculateStarSize(char[][] grid, int r, int c, int rows, int cols) {
        // Start with 5 (the center + 4 immediate neighbors).
        int count = 5;

        // Expand arms in all four directions, starting from the second cell away from the center.
        count += countArmLength(grid, r - 2, c, -1, 0, rows, cols); // Up
        count += countArmLength(grid, r + 2, c, 1, 0, rows, cols);  // Down
        count += countArmLength(grid, r, c - 2, 0, -1, rows, cols); // Left
        count += countArmLength(grid, r, c + 2, 0, 1, rows, cols);  // Right

        return count;
    }

    /**
     * Traverses in a direction from a starting point and counts consecutive stars.
     *
     * @param grid  The 2D grid.
     * @param r     Starting row.
     * @param c     Starting column.
     * @param dr    Row direction (-1, 0, or 1).
     * @param dc    Column direction (-1, 0, or 1).
     * @param rows  Total rows.
     * @param cols  Total columns.
     * @return The number of consecutive stars found.
     */
    private static int countArmLength(char[][] grid, int r, int c, int dr, int dc, int rows, int cols) {
        int length = 0;
        while (r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] == STAR) {
            length++;
            r += dr;
            c += dc;
        }
        return length;
    }
}

import java.io.BufferedReader;
