import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * A utility to detect if a given grid of characters contains exactly one 
 * plus-shaped pattern consisting of all '*' characters.
 */
public class PlusShapeFinder {

    public static void main(String[] args) {
        FastReader reader = new FastReader();

        int rows = reader.nextInt();
        int cols = reader.nextInt();

        boolean[][] grid = new boolean[rows][cols];
        int starCount = 0;

        for (int i = 0; i < rows; i++) {
            String line = reader.next();
            for (int j = 0; j < cols; j++) {
                if (line.charAt(j) == '*') {
                    grid[i][j] = true;
                    starCount++;
                }
            }
        }

        if (isPlusPatternFound(grid, starCount)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Determines if the stars in the grid form a single, perfect plus shape.
     * 
     * @param grid The 2D boolean array representing the grid.
     * @param totalStars The total number of '*' characters found in the grid.
     * @return true if a single plus shape uses all stars; false otherwise.
     */
    private static boolean isPlusPatternFound(boolean[][] grid, int totalStars) {
        int rows = grid.length;
        if (rows == 0) return false;
        int cols = grid[0].length;

        // A plus shape requires at least a center and 4 arms (minimum 5 stars)
        // and the grid must be at least 3x3.
        if (totalStars < 5 || rows < 3 || cols < 3) {
            return false;
        }

        // Iterate through potential centers (avoiding boundaries)
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (isMinimumPlusCenter(grid, i, j)) {
                    if (calculatePlusSize(grid, i, j) == totalStars) {
                        return true;
                    }
                }
            }
        }

        return false;
    }

    /**
     * Checks if a cell is the center of a minimum 5-cell plus shape.
     */
    private static boolean isMinimumPlusCenter(boolean[][] grid, int r, int c) {
        return grid[r][c] &&
               grid[r - 1][c] &&
               grid[r + 1][c] &&
               grid[r][c - 1] &&
               grid[r][c + 1];
    }

    /**
     * Calculates the total number of cells in the plus shape centered at (row, col).
     */
    private static int calculatePlusSize(boolean[][] grid, int row, int col) {
        int size = 1; // Start with the center cell
        int[][] directions = {
            {0, 1},  // Right
            {0, -1}, // Left
            {1, 0},  // Down
            {-1, 0}  // Up
        };

        for (int[] dir : directions) {
            int r = row + dir[0];
            int c = col + dir[1];

            while (isValid(grid, r, c) && grid[r][c]) {
                size++;
                r += dir[0];
                c += dir[1];
            }
        }

        return size;
    }

    private static boolean isValid(boolean[][] grid, int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }

    /**
     * Fast I/O reader for efficient input processing.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Analyzes a grid to determine if it contains a single valid cross pattern.
 * A valid cross pattern is defined by:
 * 1. Exactly one "center" point (a cell whose four immediate neighbors are '*').
 * 2. All '*' characters in the grid must lie on the row or column of that center.
 * 3. The '*' characters in the center's row must form a single contiguous segment.
 * 4. The '*' characters in the center's column must form a single contiguous segment.
 */
public class CrossPatternAnalyzer {

    private final int rows;
    private final int cols;
    private final char[][] grid;

    /**
     * Represents a coordinate point in the grid.
     */
    private static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    public CrossPatternAnalyzer(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
    }

    /**
     * Main logic to validate the cross pattern.
     * 
     * @return true if the grid contains a valid cross, false otherwise.
     */
    public boolean isValidCross() {
        List<Point> centers = findCenters();

        // Rule 1: There must be exactly one center point
        if (centers.size() != 1) {
            return false;
        }

        Point center = centers.get(0);

        // Rule 2: All '*' in the grid must lie on the center's row or column
        if (!allAsterisksAreOnCross(center)) {
            return false;
        }

        // Rule 3: The '*' in the center's row must be a single contiguous block
        if (!isContiguousInRow(center.row)) {
            return false;
        }

        // Rule 4: The '*' in the center's column must be a single contiguous block
        if (!isContiguousInCol(center.col)) {
            return false;
        }

        return true;
    }

    /**
     * Scans the grid for points that satisfy the "center" definition.
     */
    private List<Point> findCenters() {
        List<Point> centers = new ArrayList<>();
        // A center cannot exist on the boundary of the grid
        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < cols - 1; c++) {
                if (isCenterPoint(r, c)) {
                    centers.add(new Point(r, c));
                }
            }
        }
        return centers;
    }

    /**
     * Checks if the four immediate neighbors of a cell are all asterisks.
     */
    private boolean isCenterPoint(int r, int c) {
        return grid[r - 1][c] == '*' &&
               grid[r + 1][c] == '*' &&
               grid[r][c - 1] == '*' &&
               grid[r][c + 1] == '*';
    }

    /**
     * Ensures no '*' exists outside of the cross formed by the center.
     */
    private boolean allAsterisksAreOnCross(Point center) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*') {
                    if (r != center.row && c != center.col) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    private boolean isContiguousInRow(int row) {
        List<Integer> starColumnIndices = new ArrayList<>();
        for (int c = 0; c < cols; c++) {
            if (grid[row][c] == '*') {
                starColumnIndices.add(c);
            }
        }
        return isContiguous(starColumnIndices);
    }

    private boolean isContiguousInCol(int col) {
        List<Integer> starRowIndices = new ArrayList<>();
        for (int r = 0; r < rows; r++) {
            if (grid[r][col] == '*') {
                starRowIndices.add(r);
            }
        }
        return isContiguous(starRowIndices);
    }

    /**
     * Checks if a list of indices represents a continuous sequence.
     */
    private boolean isContiguous(List<Integer> indices) {
        if (indices.isEmpty()) {
            return false;
        }
        for (int i = 0; i < indices.size() - 1; i++) {
            if (indices.get(i + 1) != indices.get(i) + 1) {
                return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;
            int rows = scanner.nextInt();
            if (!scanner.hasNextInt()) return;
            int cols = scanner.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = scanner.next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }

            CrossPatternAnalyzer analyzer = new CrossPatternAnalyzer(rows, cols, grid);
            System.out.println(analyzer.isValidCross() ? "YES" : "NO");
        }
    }
}

import java.io.BufferedOutputStream;
