/**
 * Problem: Determine if the grid contains exactly one cross shape formed by '*' characters.
 * A cross consists of a center '*' and its four immediate neighbors (up, down, left, right).
 */
public class Round566Div2B {

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            solve(reader, out);
        } finally {
            out.close();
        }
    }

    /**
     * Orchestrates the reading of input and the output of the result.
     */
    private static void solve(FastReader reader, PrintWriter out) {
        int height = reader.nextInt();
        int width = reader.nextInt();

        String[] grid = new String[height];
        int totalAsterisks = 0;

        for (int i = 0; i < height; i++) {
            grid[i] = reader.next();
            // Count asterisks while reading the grid to optimize performance
            for (int j = 0; j < width; j++) {
                if (grid[i].charAt(j) == '*') {
                    totalAsterisks++;
                }
            }
        }

        // A single cross must consist of exactly 5 asterisks.
        // If there are more or fewer, it cannot be exactly one cross.
        if (totalAsterisks != 5) {
            out.println("NO");
            return;
        }

        if (containsCross(grid, height, width)) {
            out.println("YES");
        } else {
            out.println("NO");
        }
    }

    /**
     * Iterates through the grid to find if any cell acts as a center of a cross.
     */
    private static boolean containsCross(String[] grid, int height, int width) {
        // A cross center cannot be on the boundary of the grid.
        for (int i = 1; i < height - 1; i++) {
            for (int j = 1; j < width - 1; j++) {
                if (isCenterOfCross(grid, i, j)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Checks if the cell at (row, col) and its 4 neighbors are all asterisks.
     */
    private static boolean isCenterOfCross(String[] grid, int row, int col) {
        return grid[row].charAt(col) == '*' &&
               grid[row - 1].charAt(col) == '*' &&
               grid[row + 1].charAt(col) == '*' &&
               grid[row].charAt(col - 1) == '*' &&
               grid[row].charAt(col + 1) == '*';
    }

    /**
     * Efficient utility class for reading input.
     */
    public static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (Exception e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.util.Scanner;

/**
 * A solver for finding if a single "cross" pattern of stars can clear a grid.
 */
public class CrossGridSolver {

    private static final char STAR = '*';
    private static final char EMPTY = '.';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int height = scanner.nextInt();
        int width = scanner.nextInt();
        char[][] grid = readGrid(scanner, height, width);

        if (canClearGridWithSingleCross(grid, height, width)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Reads the grid from the scanner.
     */
    private static char[][] readGrid(Scanner scanner, int height, int width) {
        char[][] grid = new char[height][width];
        for (int i = 0; i < height; i++) {
            String rowString = scanner.next();
            for (int j = 0; j < width; j++) {
                grid[i][j] = rowString.charAt(j);
            }
        }
        return grid;
    }

    /**
     * Iterates through the grid to find a potential cross center and tests it.
     * 
     * @return true if a cross is found that clears all stars in the grid.
     */
    private static boolean canClearGridWithSingleCross(char[][] grid, int height, int width) {
        // A center cannot be on the boundary because it needs 4 neighbors
        for (int r = 1; r < height - 1; r++) {
            for (int c = 1; c < width - 1; c++) {
                if (isPotentialCenter(grid, r, c)) {
                    return testCrossClearing(grid, r, c, height, width);
                }
            }
        }
        return false;
    }

    /**
     * Checks if the cell (r, c) and its four cardinal neighbors are all stars.
     */
    private static boolean isPotentialCenter(char[][] grid, int r, int c) {
        return grid[r][c] == STAR &&
               grid[r - 1][c] == STAR &&
               grid[r + 1][c] == STAR &&
               grid[r][c - 1] == STAR &&
               grid[r][c + 1] == STAR;
    }

    /**
     * Simulates clearing the grid using a cross at (centerR, centerC) 
     * and checks if any stars remain.
     */
    private static boolean testCrossClearing(char[][] grid, int centerR, int centerC, int height, int width) {
        char[][] gridCopy = copyGrid(grid, height, width);

        applyCrossTransformation(gridCopy, centerR, centerC, height, width);

        return !hasRemainingStars(gridCopy, height, width);
    }

    /**
     * Performs the ray-casting logic to clear stars in a cross shape.
     */
    private static void applyCrossTransformation(char[][] grid, int r, int c, int height, int width) {
        grid[r][c] = EMPTY;

        // Clear Up
        for (int i = r - 1; i >= 0 && grid[i][c] == STAR; i--) {
            grid[i][c] = EMPTY;
        }
        // Clear Down
        for (int i = r + 1; i < height && grid[i][c] == STAR; i++) {
            grid[i][c] = EMPTY;
        }
        // Clear Left
        for (int j = c - 1; j >= 0 && grid[r][j] == STAR; j--) {
            grid[r][j] = EMPTY;
        }
        // Clear Right
        for (int j = c + 1; j < width && grid[r][j] == STAR; j++) {
            grid[r][j] = EMPTY;
        }
    }

    /**
     * Checks if the grid still contains any '*' characters.
     */
    private static boolean hasRemainingStars(char[][] grid, int height, int width) {
        for (int i = 0; i < height; i++) {
            for (int j = 0; j < width; j++) {
                if (grid[i][j] == STAR) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Utility to create a deep copy of the 2D char array.
     */
    private static char[][] copyGrid(char[][] original, int height, int width) {
        char[][] copy = new char[height][width];
        for (int i = 0; i < height; i++) {
            System.arraycopy(original[i], 0, copy[i], 0, width);
        }
        return copy;
    }
}

import java.io.*;
import java.util.*;

/**
 * This program determines if a grid contains exactly one "plus" shape pattern
 * made of filled cells ('#') and no other filled cells.
 */
public class GridPatternMatcher {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            solve(reader, writer);
        } catch (Exception e) {
            // In a real-world application, use a logger.
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    private static void solve(FastReader reader, PrintWriter writer) {
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        Grid grid = new Grid(rows, cols, reader);

        if (grid.containsSingleCrossPattern()) {
            writer.print("YES");
        } else {
            writer.print("NO");
        }
    }

    /**
     * Represents the 2D grid and the logic to manipulate/query it.
     */
    static class Grid {
        private final int rows;
        private final int cols;
        private final boolean[][] cells; // true if '#', false if '.'

        public Grid(int rows, int cols, FastReader reader) {
            this.rows = rows;
            this.cols = cols;
            this.cells = new boolean[rows][cols];
            initializeGrid(reader);
        }

        private void initializeGrid(FastReader reader) {
            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                for (int j = 0; j < cols; j++) {
                    cells[i][j] = (line.charAt(j) == '#');
                }
            }
        }

        /**
         * Searches for a cross pattern. If found, clears it and checks if
         * any filled cells remain.
         */
        public boolean containsSingleCrossPattern() {
            for (int i = 1; i < rows - 1; i++) {
                for (int j = 1; j < cols - 1; j++) {
                    if (isCenterOfCross(i, j)) {
                        clearCrossArms(i, j);
                        return !hasAnyFilledCells();
                    }
                }
            }
            return false;
        }

        private boolean isCenterOfCross(int r, int c) {
            return cells[r][c] && 
                   cells[r - 1][c] && 
                   cells[r + 1][c] && 
                   cells[r][c - 1] && 
                   cells[r][c + 1];
        }

        /**
         * Wipes out the connected arms of the cross starting from the center.
         */
        private void clearCrossArms(int r, int c) {
            cells[r][c] = false;

            // Clear Up
            for (int k = r - 1; k >= 0 && cells[k][c]; k--) {
                cells[k][c] = false;
            }
            // Clear Down
            for (int k = r + 1; k < rows && cells[k][c]; k++) {
                cells[k][c] = false;
            }
            // Clear Left
            for (int k = c - 1; k >= 0 && cells[r][k]; k--) {
                cells[r][k] = false;
            }
            // Clear Right
            for (int k = c + 1; k < cols && cells[r][k]; k++) {
                cells[r][k] = false;
            }
        }

        private boolean hasAnyFilledCells() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (cells[i][j]) return true;
                }
            }
            return false;
        }
    }

    /**
     * Fast I/O utility class for efficient reading.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * A utility class to detect if a grid contains a valid "plus" shape.
 * A valid plus shape consists of exactly one row and one column of stars 
 * that intersect at a center point not located on the grid boundary.
 */
public class PlusPatternMatcher {

    /**
     * Represents a coordinate in the 2D grid.
     */
    private static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int height = scanner.nextInt();
        int width = scanner.nextInt();
        char[][] grid = new char[height][width];
        List<Point> starPositions = new ArrayList<>();

        // Read grid and record positions of all stars ('*')
        for (int i = 0; i < height; i++) {
            String rowString = scanner.next();
            for (int j = 0; j < width; j++) {
                grid[i][j] = rowString.charAt(j);
                if (grid[i][j] == '*') {
                    starPositions.add(new Point(i, j));
                }
            }
        }

        if (detectPlusShape(height, width, grid, starPositions)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Orchestrates the detection of the plus shape by finding potential
     * intersection points and validating them.
     *
     * @return true if a valid plus shape is found, false otherwise.
     */
    private static boolean detectPlusShape(int h, int w, char[][] grid, List<Point> stars) {
        Point p1 = null;
        Point p2 = null;

        // A plus shape must have stars in different rows and columns.
        // We find the first two stars that do not share a row or a column.
        for (Point s : stars) {
            if (p1 == null) {
                p1 = s;
            } else if (p2 == null) {
                if (s.row != p1.row && s.col != p1.col) {
                    p2 = s;
                    break;
                }
            }
        }

        // If we cannot find two stars that define a potential intersection, no plus exists.
        if (p1 == null || p2 == null) {
            return false;
        }

        // The two possible intersection points of the rows and columns of our two stars.
        Point candidate1 = new Point(p1.row, p2.col);
        Point candidate2 = new Point(p2.row, p1.col);

        // Check if either candidate forms a valid, complete plus shape.
        return isValidPlusCenter(h, w, grid, candidate1) || 
               isValidPlusCenter(h, w, grid, candidate2);
    }

    /**
     * Validates if a specific point is the center of a valid plus shape.
     * A valid center must not be on the grid boundary, must be a star, 
     * and must form a cross that spans the entire row and column.
     */
    private static boolean isValidPlusCenter(int h, int w, char[][] grid, Point center) {
        // 1. The center cannot be on the boundary of the grid.
        if (center.row <= 0 || center.row >= h - 1 || 
            center.col <= 0 || center.col >= w - 1) {
            return false;
        }

        // 2. The candidate center must actually be a star.
        if (grid[center.row][center.col] != '*') {
            return false;
        }

        // 3. Verify the entire grid:
        //    - Every cell in the center's row and column must be a star.
        //    - Every other cell in the grid must be a dot ('.').
        for (int r = 0; r < h; r++) {
            for (int c = 0; c < w; c++) {
                boolean isPartOfCross = (r == center.row || c == center.col);

                if (isPartOfCross) {
                    if (grid[r][c] != '*') {
                        return false;
                    }
                } else {
                    if (grid[r][c] == '*') {
                        return false;
                    }
                }
            }
        }

        return true;
    }
}

import java.util.Scanner;

/**
 * This program determines if all '*' characters in a grid form a single 
 * continuous cross shape (horizontal and vertical lines) without any 
 * disconnected '*' characters.
 */
public class Main {

    private static final char STAR = '*';
    private static final char EMPTY = '.';

    // Direction vectors for moving: Right, Left, Down, Up
    private static final int[][] DIRECTIONS = {
        {0, 1}, {0, -1}, {1, 0}, {-1, 0}
    };

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int height = scanner.nextInt();
        int width = scanner.nextInt();

        char[][] grid = new char[height][width];
        for (int i = 0; i < height; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        if (solve(grid, height, width)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Core logic to determine if the grid satisfies the cross pattern requirement.
     */
    private static boolean solve(char[][] grid, int height, int width) {
        Point center = findCrossCenter(grid, height, width);

        // If no center of a cross exists, the pattern cannot be valid
        if (center == null) {
            return false;
        }

        boolean[][] isCovered = markCrossCells(grid, height, width, center);

        return validateAllStarsCovered(grid, height, width, isCovered);
    }

    /**
     * Searches for a '*' that has '*' neighbors in all four cardinal directions.
     */
    private static Point findCrossCenter(char[][] grid, int height, int width) {
        // A center must have neighbors, so we skip the boundary rows and columns
        for (int i = 1; i < height - 1; i++) {
            for (int j = 1; j < width - 1; j++) {
                if (grid[i][j] == STAR &&
                    grid[i - 1][j] == STAR &&
                    grid[i + 1][j] == STAR &&
                    grid[i][j - 1] == STAR &&
                    grid[i][j + 1] == STAR) {
                    return new Point(i, j);
                }
            }
        }
        return null;
    }

    /**
     * Traces the arms of the cross from the center and marks all connected '*' cells.
     */
    private static boolean[][] markCrossCells(char[][] grid, int height, int width, Point center) {
        boolean[][] isCovered = new boolean[height][width];
        isCovered[center.row][center.col] = true;

        for (int[] dir : DIRECTIONS) {
            int r = center.row + dir[0];
            int c = center.col + dir[1];

            // Continue moving in the current direction as long as we hit '*'
            while (isValid(r, c, height, width) && grid[r][c] == STAR) {
                isCovered[r][c] = true;
                r += dir[0];
                c += dir[1];
            }
        }

        return isCovered;
    }

    /**
     * Checks if every '*' in the grid has been marked as part of the cross.
     */
    private static boolean validateAllStarsCovered(char[][] grid, int height, int width, boolean[][] isCovered) {
        for (int i = 0; i < height; i++) {
            for (int j = 0; j < width; j++) {
                if (grid[i][j] == STAR && !isCovered[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    private static boolean isValid(int r, int c, int height, int width) {
        return r >= 0 && r < height && c >= 0 && c < width;
    }

    /**
     * Simple data holder for grid coordinates.
     */
    private static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }
}

import java.util.Scanner;

/**
 * Application to detect if a grid contains a valid "plus" shape.
 * A valid plus shape consists of exactly one horizontal line of stars
 * and one vertical line of stars intersecting at a single center point,
 * with no other stars present in the grid.
 */
public class Contest {

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int height = scanner.nextInt();
            int width = scanner.nextInt();

            boolean[][] grid = new boolean[height][width];
            for (int i = 0; i < height; i++) {
                String rowString = scanner.next();
                for (int j = 0; j < width; j++) {
                    if (j < rowString.length() && rowString.charAt(j) == '*') {
                        grid[i][j] = true;
                    }
                }
            }

            PlusShapeValidator validator = new PlusShapeValidator(grid, height, width);
            if (validator.isValid()) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }
}

class PlusShapeValidator {
    private final boolean[][] grid;
    private final int height;
    private final int width;

    public PlusShapeValidator(boolean[][] grid, int height, int width) {
        this.grid = grid;
        this.height = height;
        this.width = width;
    }

    /**
     * Validates if the grid contains exactly one plus shape.
     * 
     * @return true if a valid plus is found, false otherwise.
     */
    public boolean isValid() {
        int totalStars = countTotalStars();

        // A minimum plus shape (center + 4 arms of length 1) requires 5 stars.
        if (totalStars < 5) {
            return false;
        }

        int rowWithMultipleStars = findRowWithMultipleStars();
        int colWithMultipleStars = findColWithMultipleStars();

        // A plus must have exactly one row and one column containing multiple stars.
        // findRow... returns -1 if none found, or -2 if multiple candidates found.
        if (rowWithMultipleStars <= 0 || colWithMultipleStars <= 0) {
            return false;
        }

        // The intersection (center) cannot be on the boundary of the grid.
        if (rowWithMultipleStars == height - 1 || colWithMultipleStars == width - 1) {
            return false;
        }

        // The intersection point must actually contain a star.
        if (!grid[rowWithMultipleStars][colWithMultipleStars]) {
            return false;
        }

        int starsInRow = countStarsInRow(rowWithMultipleStars);
        int starsInCol = countStarsInCol(colWithMultipleStars);

        // All stars in the grid must belong to the cross formed by the intersection.
        // Total stars = (stars in row) + (stars in col) - 1 (to not double-count the center).
        if (totalStars != (starsInRow + starsInCol - 1)) {
            return false;
        }

        // Ensure the arms of the plus are contiguous (no gaps).
        return isRowContiguous(rowWithMultipleStars) && isColContiguous(colWithMultipleStars);
    }

    private int countTotalStars() {
        int count = 0;
        for (int r = 0; r < height; r++) {
            for (int c = 0; c < width; c++) {
                if (grid[r][c]) count++;
            }
        }
        return count;
    }

    private int findRowWithMultipleStars() {
        int foundRow = -1;
        for (int r = 0; r < height; r++) {
            int count = 0;
            for (int c = 0; c < width; c++) {
                if (grid[r][c]) count++;
            }
            if (count > 1) {
                if (foundRow != -1) return -2; // Multiple candidate rows found
                foundRow = r;
            }
        }
        return foundRow;
    }

    private int findColWithMultipleStars() {
        int foundCol = -1;
        for (int c = 0; c < width; c++) {
            int count = 0;
            for (int r = 0; r < height; r++) {
                if (grid[r][c]) count++;
            }
            if (count > 1) {
                if (foundCol != -1) return -2; // Multiple candidate columns found
                foundCol = c;
            }
        }
        return foundCol;
    }

    private int countStarsInRow(int r) {
        int count = 0;
        for (int c = 0; c < width; c++) {
            if (grid[r][c]) count++;
        }
        return count;
    }

    private int countStarsInCol(int c) {
        int count = 0;
        for (int r = 0; r < height; r++) {
            if (grid[r][c]) count++;
        }
        return count;
    }

    private boolean isRowContiguous(int r) {
        int first = -1;
        int last = -1;
        int count = 0;
        for (int c = 0; c < width; c++) {
            if (grid[r][c]) {
                if (first == -1) first = c;
                last = c;
                count++;
            }
        }
        return count > 0 && (last - first + 1 == count);
    }

    private boolean isColContiguous(int c) {
        int first = -1;
        int last = -1;
        int count = 0;
        for (int r = 0; r < height; r++) {
            if (grid[r][c]) {
                if (first == -1) first = r;
                last = r;
                count++;
            }
        }
        return count > 0 && (last - first + 1 == count);
    }
}

import java.util.Scanner;

/**
 * A utility to detect if a grid contains exactly one cross pattern 
 * and no other star characters.
 */
public class CrossPatternSolver {

    private static final char STAR = '*';
    private static final char EMPTY = '.';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rowCount = scanner.nextInt();
        int colCount = scanner.nextInt();
        char[][] grid = new char[rowCount][colCount];

        for (int i = 0; i < rowCount; i++) {
            String rowString = scanner.next();
            grid[i] = rowString.toCharArray();
        }

        if (isValidCrossPattern(grid, rowCount, colCount)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Determines if the grid contains exactly one cross pattern and no other stars.
     */
    private static boolean isValidCrossPattern(char[][] grid, int rows, int cols) {
        boolean crossFound = false;

        // 1. Search for the first center of a cross
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == STAR && isCenter(grid, r, c, rows, cols)) {
                    clearCross(grid, r, c, rows, cols);
                    crossFound = true;
                    break;
                }
            }
            if (crossFound) break;
        }

        // If no cross was ever found, it's an invalid pattern
        if (!crossFound) {
            return false;
        }

        // 2. If a cross was found, ensure no other stars remain in the grid
        return !hasAnyStarsRemaining(grid, rows, cols);
    }

    /**
     * Checks if the cell at (row, col) is the center of a cross.
     * A center must have star neighbors in all four cardinal directions.
     */
    private static boolean isCenter(char[][] grid, int row, int col, int rows, int cols) {
        // Check bounds for neighbors
        if (row <= 0 || row >= rows - 1 || col <= 0 || col >= cols - 1) {
            return false;
        }

        return grid[row + 1][col] == STAR &&
               grid[row - 1][col] == STAR &&
               grid[row][col - 1] == STAR &&
               grid[row][col + 1] == STAR;
    }

    /**
     * Clears the horizontal and vertical lines of stars originating from the center.
     */
    private static void clearCross(char[][] grid, int row, int col, int rows, int cols) {
        // Clear horizontal line
        int c = col;
        while (c < cols && grid[row][c] == STAR) {
            grid[row][c] = EMPTY;
            c++;
        }
        c = col - 1;
        while (c >= 0 && grid[row][c] == STAR) {
            grid[row][c] = EMPTY;
            c--;
        }

        // Clear vertical line
        int r = row;
        while (r < rows && grid[r][col] == STAR) {
            grid[r][col] = EMPTY;
            r++;
        }
        r = row - 1;
        while (r >= 0 && grid[r][col] == STAR) {
            grid[r][col] = EMPTY;
            r--;
        }
    }

    /**
     * Scans the grid to see if any star characters are left.
     */
    private static boolean hasAnyStarsRemaining(char[][] grid, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == STAR) {
                    return true;
                }
            }
        }
        return false;
    }
}

import java.util.*;

/**
 * A utility to validate if a grid of characters contains exactly one 
 * continuous cross shape formed by '*' characters.
 */
public class CrossShapeValidator {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int height = scanner.nextInt();
        int width = scanner.nextInt();
        scanner.nextLine(); // Consume newline

        char[][] grid = new char[height][width];
        for (int i = 0; i < height; i++) {
            String line = scanner.nextLine();
            grid[i] = line.toCharArray();
        }

        if (isValidCross(grid, height, width)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Orchestrates the validation logic.
     */
    public static boolean isValidCross(char[][] grid, int height, int width) {
        Optional<Point> center = findCrossCenter(grid, height, width);

        if (center.isEmpty()) {
            return false;
        }

        Point cp = center.get();
        Extent verticalExtent = findVerticalExtent(grid, height, width, cp.row(), cp.col());
        Extent horizontalExtent = findHorizontalExtent(grid, height, width, cp.row(), cp.col());

        return validateAllStars(grid, height, width, cp, verticalExtent, horizontalExtent);
    }

    /**
     * Finds a '*' that has four '*' neighbors (up, down, left, right).
     */
    private static Optional<Point> findCrossCenter(char[][] grid, int height, int width) {
        for (int r = 1; r < height - 1; r++) {
            for (int c = 1; c < width - 1; c++) {
                if (isCenterAt(grid, r, c)) {
                    return Optional.of(new Point(r, c));
                }
            }
        }
        return Optional.empty();
    }

    private static boolean isCenterAt(char[][] grid, int r, int c) {
        return grid[r][c] == '*' &&
               grid[r - 1][c] == '*' &&
               grid[r + 1][c] == '*' &&
               grid[r][c - 1] == '*' &&
               grid[r][c + 1] == '*';
    }

    /**
     * Calculates the continuous range of '*' in the vertical column of the center.
     */
    private static Extent findVerticalExtent(char[][] grid, int height, int width, int row, int col) {
        int top = row;
        while (top > 0 && grid[top - 1][col] == '*') {
            top--;
        }
        int bottom = row;
        while (bottom < height - 1 && grid[bottom + 1][col] == '*') {
            bottom++;
        }
        return new Extent(top, bottom);
    }

    /**
     * Calculates the continuous range of '*' in the horizontal row of the center.
     */
    private static Extent findHorizontalExtent(char[][] grid, int height, int width, int row, int col) {
        int left = col;
        while (left > 0 && grid[row][left - 1] == '*') {
            left--;
        }
        int right = col;
        while (right < width - 1 && grid[row][right + 1] == '*') {
            right++;
        }
        return new Extent(left, right);
    }

    /**
     * Ensures that every '*' in the grid lies within the identified cross structure.
     */
    private static boolean validateAllStars(char[][] grid, int height, int width, 
                                            Point center, Extent vExtent, Extent hExtent) {
        for (int r = 0; r < height; r++) {
            for (int c = 0; c < width; c++) {
                if (grid[r][c] == '*') {
                    boolean onVerticalBar = (c == center.col() && r >= vExtent.min() && r <= vExtent.max());
                    boolean onHorizontalBar = (r == center.row() && c >= hExtent.min() && c <= hExtent.max());

                    if (!onVerticalBar && !onHorizontalBar) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    /**
     * Represents a coordinate in the grid.
     */
    private record Point(int row, int col) {}

    /**
     * Represents a range of indices.
     */
    private record Extent(int min, int max) {}
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.Optional;
import java.util.StringTokenizer;

/**
 * Solves the problem of determining if all '*' characters in a grid 
 * form a single, perfect cross shape.
 */
public class Codeforces {

    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int height = in.nextInt();
            int width = in.nextInt();

            char[][] grid = new char[height][width];
            for (int i = 0; i < height; i++) {
                grid[i] = in.next().toCharArray();
            }

            boolean isCross = CrossShapeValidator.isValidCross(grid, height, width);
            out.println(isCross ? "YES" : "NO");

        } catch (Exception e) {
            // In a production environment, use a logger.
            e.printStackTrace();
        } finally {
            out.close();
        }
    }

    /**
     * Logic component responsible for validating the cross shape.
     */
    static class CrossShapeValidator {

        private static final char TARGET_CHAR = '*';

        // Direction vectors for Up, Down, Left, Right
        private static final int[] DR = {-1, 1, 0, 0};
        private static final int[] DC = {0, 0, -1, 1};

        public static boolean isValidCross(char[][] grid, int height, int width) {
            return findCenter(grid, height, width)
                    .map(center -> verifyCross(grid, height, width, center))
                    .orElse(false);
        }

        /**
         * Finds the center of the potential cross.
         * A center is a '*' with four '*' neighbors.
         */
        private static Optional<Point> findCenter(char[][] grid, int height, int width) {
            for (int r = 1; r < height - 1; r++) {
                for (int c = 1; c < width - 1; c++) {
                    if (isPotentialCenter(grid, r, c)) {
                        return Optional.of(new Point(r, c));
                    }
                }
            }
            return Optional.empty();
        }

        private static boolean isPotentialCenter(char[][] grid, int r, int c) {
            return grid[r][c] == TARGET_CHAR &&
                   grid[r + 1][c] == TARGET_CHAR &&
                   grid[r - 1][c] == TARGET_CHAR &&
                   grid[r][c + 1] == TARGET_CHAR &&
                   grid[r][c - 1] == TARGET_CHAR;
        }

        /**
         * Validates that all '*' characters are part of the cross arms
         * stemming from the identified center.
         */
        private static boolean verifyCross(char[][] grid, int height, int width, Point center) {
            boolean[][] used = new boolean[height][width];

            // Mark the center
            used[center.row()][center.col()] = true;

            // Mark the four arms of the cross
            for (int i = 0; i < 4; i++) {
                int currR = center.row() + DR[i];
                int currC = center.col() + DC[i];

                while (isValid(currR, currC, height, width) && grid[currR][currC] == TARGET_CHAR) {
                    used[currR][currC] = true;
                    currR += DR[i];
                    currC += DC[i];
                }
            }

            // Ensure no '*' exists that wasn't marked as part of the cross
            for (int r = 0; r < height; r++) {
                for (int c = 0; c < width; c++) {
                    if (grid[r][c] == TARGET_CHAR && !used[r][c]) {
                        return false;
                    }
                }
            }

            return true;
        }

