/**
 * Represents the 2D grid structure.
 */
class Grid {
    private final int height;
    private final int width;
    private final char[][] cells;

    public Grid(int height, int width, char[][] cells) {
        this.height = height;
        this.width = width;
        this.cells = cells;
    }

    public int getHeight() { return height; }
    public int getWidth() { return width; }

    public char getCell(int row, int col) {
        if (isOutOfBounds(row, col)) {
            return ' ';
        }
        return cells[row][col];
    }

    public boolean isOutOfBounds(int row, int col) {
        return row < 0 || row >= height || col < 0 || col >= width;
    }
}

/**
 * Represents a coordinate point in the grid.
 */
class Point {
    final int row;
    final int col;

    Point(int row, int col) {
        this.row = row;
        this.col = col;
    }
}

/**
 * Contains the logic to validate if the grid follows the specific star pattern.
 */
class PatternValidator {
    private final Grid grid;

    public PatternValidator(Grid grid) {
        this.grid = grid;
    }

    /**
     * Validates the pattern based on the identified pivot and intersection points.
     * @return true if pattern is valid, false otherwise.
     */
    public boolean validate() {
        Optional<Point> firstStar = findFirstStar();
        if (firstStar.isEmpty()) return false;

        Point pivot = firstStar.get();
        if (isAtEdge(pivot)) return false;

        Optional<Point> secondStar = findSecondStar(pivot);
        if (secondStar.isEmpty()) return false;

        Point intersection = secondStar.get();
        if (isInvalidIntersection(intersection, pivot)) return false;

        return isVerticalLineIntact(pivot.col, intersection.row) &&
               isHorizontalLineIntact(intersection.row, intersection.col);
    }

    private Optional<Point> findFirstStar() {
        for (int r = 0; r < grid.getHeight(); r++) {
            for (int c = 0; c < grid.getWidth(); c++) {
                if (grid.getCell(r, c) == '*') {
                    return Optional.of(new Point(r, c));
                }
            }
        }
        return Optional.empty();
    }

    private Optional<Point> findSecondStar(Point firstStar) {
        // We search starting from the first star's position to find the next star
        for (int r = firstStar.row; r < grid.getHeight(); r++) {
            // If we are on the same row as the first star, start from the next column
            int startCol = (r == firstStar.row) ? firstStar.col + 1 : 0;
            for (int c = startCol; c < grid.getWidth(); c++) {
                if (grid.getCell(r, c) == '*') {
                    return Optional.of(new Point(r, c));
                }
            }
        }
        return Optional.empty();
    }

    private boolean isAtEdge(Point p) {
        return p.col == 0 || p.col == grid.getWidth() - 1;
    }

    private boolean isInvalidIntersection(Point intersection, Point pivot) {
        // Check boundaries and relative positioning logic from original implementation
        return intersection.row == grid.getHeight() - 1 || 
               intersection.col > pivot.col ||
               intersection.row == 0;
    }

    /**
     * Ensures the vertical line at the pivot column is continuous down to the intersection row.
     */
    private boolean isVerticalLineIntact(int col, int intersectionRow) {
        for (int r = 0; r <= intersectionRow; r++) {
            if (grid.getCell(r, col) != '*') {
                // The original logic allowed a break if it occurred after the intersection row
                return false;
            }
        }
        return true;
    }

    /**
     * Ensures the horizontal line segment starting from the intersection is continuous.
     */
    private boolean isHorizontalLineIntact(int row, int startCol) {
        boolean foundGap = false;
        for (int c = startCol; c < grid.getWidth(); c++) {
            if (grid.getCell(row, c) == '*') {
                if (foundGap) return false; // Found a second disconnected segment
            } else {
                // If we hit a non-star, we mark that we've entered a gap
                // But we only care if more stars appear later
                foundGap = true;
            }
        }
        // Note: The original code's logic for horizontal segments was quite specific;
        // This ensures only one contiguous block of stars exists in that segment.
        return true; 
    }
}

