/**
 * A utility class to determine if all '*' characters in a grid form a single, 
 * contiguous cross pattern.
 */
public final class CrossPatternChecker {

    private static final char STAR = '*';
    private static final char DOT = '.';

    public static void main(String[] args) {
        try {
            FastReader reader = new FastReader(System.in);

            int rows = reader.nextInt();
            int cols = reader.nextInt();

            if (rows <= 0 || cols <= 0) {
                System.out.println("NO");
                return;
            }

            char[][] grid = new char[rows][cols];
            int starCount = 0;

            for (int i = 0; i < rows; i++) {
                String line = reader.nextLine();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                    if (grid[i][j] == STAR) {
                        starCount++;
                    }
                }
            }

            System.out.println(solve(rows, cols, grid, starCount));

        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Core logic to validate the cross pattern.
     */
    private static String solve(int rows, int cols, char[][] grid, int starCount) {
        // The original logic returns "NO" if no stars are present.
        if (starCount == 0) {
            return "NO";
        }

        int[] center = findFirstCenter(rows, cols, grid);

        // If no cell exists that can act as a center of a cross
        if (center == null) {
            return "NO";
        }

        boolean[][] visited = new boolean[rows][cols];
        markCrossCells(rows, cols, grid, center[0], center[1], visited);

        return areAllStarsCovered(rows, cols, grid, visited) ? "YES" : "NO";
    }

    /**
     * Finds the first '*' that has four immediate neighbors also being '*'.
     * A center cannot be on the boundary.
     */
    private static int[] findFirstCenter(int rows, int cols, char[][] grid) {
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (grid[i][j] == STAR &&
                    grid[i - 1][j] == STAR &&
                    grid[i + 1][j] == STAR &&
                    grid[i][j - 1] == STAR &&
                    grid[i][j + 1] == STAR) {
                    return new int[]{i, j};
                }
            }
        }
        return null;
    }

    /**
     * Expands from the center in all four cardinal directions and marks 
     * all connected '*' cells as visited.
     */
    private static void markCrossCells(int rows, int cols, char[][] grid, int r, int c, boolean[][] visited) {
        visited[r][c] = true;

        int[][] directions = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

        for (int[] dir : directions) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            // Extend the arm as far as possible
            while (isValid(nr, nc, rows, cols) && grid[nr][nc] == STAR) {
                visited[nr][nc] = true;
                nr += dir[0];
                nc += dir[1];
            }
        }
    }

    /**
     * Verifies if every '*' in the original grid has been marked as visited.
     */
    private static boolean areAllStarsCovered(int rows, int cols, char[][] grid, boolean[][] visited) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == STAR && !visited[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Efficient reader for competitive programming style input.
     */
    static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }
}

