/**
 * Encapsulates the logic for validating the character pattern in the grid.
 */
class PatternValidator {

    private enum PatternState {
        START,
        TRANSITION,
        END
    }

    private final char[][] grid;
    private final int rowCount;
    private final int colCount;

    // State tracking variables
    private PatternState currentState = PatternState.START;
    private boolean starFound = false;
    private int firstStarCol = -1;
    private int transitionRow = -1;
    private int endColIndex = -1;

    public PatternValidator(char[][] grid, int rowCount, int colCount) {
        this.grid = grid;
        this.rowCount = rowCount;
        this.colCount = colCount;
    }

    /**
     * Executes the pattern validation algorithm.
     * @return true if the pattern is valid, false otherwise.
     */
    public boolean isValid() {
        // Initial requirement check
        if (rowCount < 3 || colCount < 3) {
            return false;
        }

        for (int i = 0; i < rowCount; i++) {
            // Transition state at the beginning of a new row
            if (currentState == PatternState.TRANSITION) {
                currentState = PatternState.END;
            }

            for (int j = 0; j < colCount; j++) {
                char currentChar = grid[i][j];

                if (currentChar == '*') {
                    starFound = true;
                }

                if (!processCell(i, j, currentChar)) {
                    return false;
                }
            }
        }

        return starFound && currentState == PatternState.END;
    }

    /**
     * Processes a single cell based on the current state machine logic.
     * 
     * @param row The current row index.
     * @param col The current column index.
     * @param ch The character at the current cell.
     * @return true if the cell does not violate the pattern, false otherwise.
     */
    private boolean processCell(int row, int col, char ch) {
        // Handle State: START
        if (currentState == PatternState.START) {
            if (firstStarCol == -1 && ch == '*') {
                firstStarCol = col;
                // Note: we don't 'continue' because the original code 
                // allows state progression within the same cell logic
            }

            if (firstStarCol != -1) {
                if (col < firstStarCol && ch == '*') {
                    return false;
                }
                if (col > firstStarCol && ch == '*') {
                    currentState = PatternState.TRANSITION;
                }
                if (col == firstStarCol && ch != '*') {
                    return false;
                }
            }
        }

        // Handle State: TRANSITION
        // This block can be entered immediately after state changes in START
        if (currentState == PatternState.TRANSITION) {
            transitionRow = row;
            if (ch != '*') {
                if (col <= firstStarCol + 1) {
                    return false;
                } else if (endColIndex == -1) {
                    endColIndex = col;
                }
            } else if (endColIndex != -1) {
                return false;
            }
        }

        // Handle State: END
        // This block can be entered immediately after state changes in TRANSITION
        if (currentState == PatternState.END) {
            if (ch == '*' && firstStarCol != -1 && col != firstStarCol) {
                return false;
            }
            if (ch == '.' && firstStarCol != -1 && col == firstStarCol) {
                if (transitionRow + 1 == row) {
                    return false;
                } else {
                    firstStarCol = -1; // Reset for next potential segment
                }
            }
            if (firstStarCol == -1 && ch == '*') {
                return false;
            }
        }

        return true;
    }
}

