/**
 * A program to determine if a given grid of characters contains exactly one 
 * "plus" shape made of '*' characters and no other '*' characters.
 */
public class Plus {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            String rowsStr = reader.next();
            if (rowsStr == null) return;

            int rows = Integer.parseInt(rowsStr);
            int cols = reader.nextInt();

            char[][] gridData = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                if (line != null) {
                    gridData[i] = line.toCharArray();
                }
            }

            Grid grid = new Grid(gridData);
            PlusDetector detector = new PlusDetector(grid);

            if (detector.isPlusShape()) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        } catch (Exception e) {
            // In a production environment, use a logger
            out.println("NO");
        } finally {
            out.close();
        }
    }

    /**
     * Represents the coordinate of a cell in the grid.
     */
    record Point(int r, int c) {}

    /**
     * Encapsulates the grid data and provides bounds-safe access.
     */
    static class Grid {
        private final char[][] data;
        private final int rows;
        private final int cols;

        public Grid(char[][] data) {
            this.data = data;
            this.rows = data.length;
            this.cols = data[0].length;
        }

        public int getRows() { return rows; }
        public int getCols() { return cols; }

        public boolean isStar(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols && data[r][c] == '*';
        }
    }

    /**
     * Contains the business logic for detecting the plus pattern.
     */
    static class PlusDetector {
        private final Grid grid;

        public PlusDetector(Grid grid) {
            this.grid = grid;
        }

        /**
         * Validates if the grid contains exactly one plus shape.
         */
        public boolean isPlusShape() {
            return findCenter().map(this::validatePlus).orElse(false);
        }

        /**
         * Finds the first '*' that could serve as the center of a plus.
         * A center must have '*' neighbors in all four cardinal directions.
         */
        private Optional<Point> findCenter() {
            for (int r = 1; r < grid.getRows() - 1; r++) {
                for (int c = 1; c < grid.getCols() - 1; c++) {
                    if (grid.isStar(r, c) &&
                        grid.isStar(r + 1, c) && grid.isStar(r - 1, c) &&
                        grid.isStar(r, c + 1) && grid.isStar(r, c - 1)) {
                        return Optional.of(new Point(r, c));
                    }
                }
            }
            return Optional.empty();
        }

        /**
         * Validates that all '*' in the grid belong to the arms of the plus
         * centered at the given point.
         */
        private boolean validatePlus(Point center) {
            int minRow = findBoundary(center, -1, 0); // Up
            int maxRow = findBoundary(center, 1, 0);  // Down
            int minCol = findBoundary(center, 0, -1); // Left
            int maxCol = findBoundary(center, 0, 1);  // Right

            for (int r = 0; r < grid.getRows(); r++) {
                for (int c = 0; c < grid.getCols(); c++) {
                    if (grid.isStar(r, c)) {
                        boolean onVerticalArm = (c == center.c() && r >= minRow && r <= maxRow);
                        boolean onHorizontalArm = (r == center.r() && c >= minCol && c <= maxCol);

                        if (!onVerticalArm && !onHorizontalArm) {
                            return false;
                        }
                    }
                }
            }
            return true;
        }

        /**
         * Helper to expand the arm of the plus in a specific direction.
         */
        private int findBoundary(Point center, int dr, int dc) {
            int r = center.r();
            int c = center.c();
            if (dr != 0) {
                // Searching vertically
                while (grid.isStar(r + dr, c)) {
                    r += dr;
                }
            } else {
                // Searching horizontally
                while (grid.isStar(r, c + dc)) {
                    c += dc;
                }
            }
            return (dr != 0) ? r : c;
        }
    }

    /**
     * Utility class for fast input parsing.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

