/**
 * A program to validate if a given grid of characters forms a single '+' (cross) shape.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] grid = reader.nextCharGrid(rows, cols);

            CrossShapeValidator validator = new CrossShapeValidator(grid, rows, cols);
            if (validator.isValid()) {
                writer.println("YES");
            } else {
                writer.println("NO");
            }
        } catch (Exception e) {
            // In a production environment, use a logger.
            writer.println("NO");
        } finally {
            writer.close();
        }
    }

    /**
     * Logic for determining if the '*' characters form exactly one cross shape.
     */
    static class CrossShapeValidator {
        private final char[][] grid;
        private final int rows;
        private final int cols;
        private int totalAsterisks = 0;

        public CrossShapeValidator(char[][] grid, int rows, int cols) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
            countTotalAsterisks();
        }

        private void countTotalAsterisks() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '*') {
                        totalAsterisks++;
                    }
                }
            }
        }

        /**
         * Validates the cross shape.
         * @return true if all '*' form a single cross, false otherwise.
         */
        public boolean isValid() {
            if (totalAsterisks == 0) return false;

            // Find the center of the potential cross.
            // A center must have '*' in all 4 cardinal directions.
            int centerRow = -1;
            int centerCol = -1;

            for (int i = 1; i < rows - 1; i++) {
                for (int j = 1; j < cols - 1; j++) {
                    if (isCenter(i, j)) {
                        centerRow = i;
                        centerCol = j;
                        break;
                    }
                }
                if (centerRow != -1) break;
            }

            // If no center is found, it's not a valid cross.
            if (centerRow == -1) {
                return false;
            }

            // Expand from the center to count how many '*' are part of this cross.
            return countCrossAsterisks(centerRow, centerCol) == totalAsterisks;
        }

        private boolean isCenter(int r, int c) {
            return grid[r][c] == '*' &&
                   grid[r - 1][c] == '*' &&
                   grid[r + 1][c] == '*' &&
                   grid[r][c - 1] == '*' &&
                   grid[r][c + 1] == '*';
        }

        private int countCrossAsterisks(int r, int c) {
            boolean[][] visited = new boolean[rows][cols];
            int count = 0;

            // Traverse Up
            for (int i = r; i >= 0 && grid[i][c] == '*'; i--) {
                if (!visited[i][c]) {
                    visited[i][c] = true;
                    count++;
                }
            }
            // Traverse Down
            for (int i = r + 1; i < rows && grid[i][c] == '*'; i++) {
                if (!visited[i][c]) {
                    visited[i][c] = true;
                    count++;
                }
            }
            // Traverse Left
            for (int j = c - 1; j >= 0 && grid[r][j] == '*'; j--) {
                if (!visited[r][j]) {
                    visited[r][j] = true;
                    count++;
                }
            }
            // Traverse Right
            for (int j = c + 1; j < cols && grid[r][j] == '*'; j++) {
                if (!visited[r][j]) {
                    visited[r][j] = true;
                    count++;
                }
            }

            // Include the center itself
            if (!visited[r][c]) {
                count++;
            }

            return count;
        }
    }

    /**
     * Fast I/O utility for efficient reading.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public char[][] nextCharGrid(int rows, int cols) {
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = next();
                if (line == null) break;
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }
            return grid;
        }
    }
}

