        }

        Grid grid = new Grid(gridData);
        PatternSolver solver = new PatternSolver(grid);

        if (solver.solve()) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Represents the grid structure and provides utility methods for manipulation.
     */
    static class Grid {
        private static final char STAR = '*';
        private static final char EMPTY = '.';

        private final char[][] matrix;
        private final int rows;
        private final int cols;

        public Grid(char[][] matrix) {
            this.matrix = matrix;
            this.rows = matrix.length;
            this.cols = matrix[0].length;
        }

        public int getRows() { return rows; }
        public int getCols() { return cols; }

        public char getCell(int r, int c) {
            return matrix[r][c];
        }

        public void setCell(int r, int c, char value) {
            matrix[r][c] = value;
        }

        public boolean isStar(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols && matrix[r][c] == STAR;
        }

        public boolean isEmpty() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (matrix[r][c] == STAR) {
                        return false;
                    }
                }
            }
            return true;
        }
    }

    /**
     * Contains the business logic for pattern recognition and grid clearing.
     */
    static class PatternSolver {
        private static final char STAR = '*';
        private static final char EMPTY = '.';

        private final Grid grid;

        public PatternSolver(Grid grid) {
            this.grid = grid;
        }

        /**
         * Orchestrates the solving process.
         * @return true if a pattern was found and all stars were cleared, false otherwise.
         */
        public boolean solve() {
            boolean patternFound = findAndClearPattern();

            if (patternFound) {
                return grid.isEmpty();
            }

            return false;
        }

        private boolean findAndClearPattern() {
            // The pattern center cannot be on the boundary edges
            for (int r = 1; r < grid.getRows() - 1; r++) {
                for (int c = 1; c < grid.getCols() - 1; c++) {
                    if (isCenterOfCross(r, c)) {
                        clearCrossPattern(r, c);
                        return true;
                    }
                }
            }
            return false;
        }

        private boolean isCenterOfCross(int r, int c) {
            return grid.getCell(r, c) == STAR &&
                   grid.isStar(r - 1, c) &&
                   grid.isStar(r + 1, c) &&
                   grid.isStar(r, c - 1) &&
                   grid.isStar(r, c + 1);
        }

        /**
         * Clears the star pattern in a cross shape (up, down, left, right) 
         * starting from the center.
         */
        private void clearCrossPattern(int r, int c) {
            grid.setCell(r, c, EMPTY);

            // Clear Up
            int currR = r;
            while (currR > 0 && grid.getCell(currR - 1, c) != EMPTY) {
                grid.setCell(currR - 1, c, EMPTY);
                currR--;
            }

            // Clear Down
            currR = r;
            while (currR < grid.getRows() - 1 && grid.getCell(currR + 1, c) != EMPTY) {
                grid.setCell(currR + 1, c, EMPTY);
                currR++;
            }

            // Clear Left
            int currC = c;
            while (currC > 0 && grid.getCell(r, currC - 1) != EMPTY) {
                grid.setCell(r, currC - 1, EMPTY);
                currC--;
            }

            // Clear Right
            currC = c;
            while (currC < grid.getCols() - 1 && grid.getCell(r, currC + 1) != EMPTY) {
                grid.setCell(r, currC + 1, EMPTY);
                currC++;
            }
        }
    }

    /**
     * High-performance input reader.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

