    /**
     * Represents a coordinate on the grid.
     */
    private record Coordinate(int row, int col) {}

    /**
     * Manages the grid logic, including finding plus shapes and validating star coverage.
     */
    static class StarGrid {
        private final String[] board;
        private final int height;
        private final int width;
        private final boolean[][] covered;

        public StarGrid(String[] board, int height, int width) {
            this.board = board;
            this.height = height;
            this.width = width;
            this.covered = new boolean[height][width];
        }

        /**
         * Validates if there is exactly one plus shape that covers all '*' characters.
         * @return true if the condition is met, false otherwise.
         */
        public boolean isValidPlusConfiguration() {
            List<Coordinate> centers = findPlusCenters();

            // The problem requires exactly one plus shape.
            if (centers.size() != 1) {
                return false;
            }

            Coordinate center = centers.get(0);
            markPlusShape(center.row, center.col);

            return allStarsAreCovered();
        }

        /**
         * Identifies all coordinates that act as the center of a plus shape.
         */
        private List<Coordinate> findPlusCenters() {
            List<Coordinate> centers = new ArrayList<>();
            for (int r = 0; r < height; r++) {
                for (int c = 0; c < width; c++) {
                    if (isPlusCenter(r, c)) {
                        centers.add(new Coordinate(r, c));
                    }
                }
            }
            return centers;
        }

        private boolean isPlusCenter(int r, int c) {
            return isStar(r, c) &&
                   isStar(r - 1, c) &&
                   isStar(r + 1, c) &&
                   isStar(r, c - 1) &&
                   isStar(r, c + 1);
        }

        /**
         * Marks the center and the four arms of the plus shape as covered.
         */
        private void markPlusShape(int r, int c) {
            covered[r][c] = true;
            int[][] directions = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

            for (int[] dir : directions) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                // Move in the direction until we hit a boundary or a '.'
                while (isStar(nr, nc)) {
                    covered[nr][nc] = true;
                    nr += dir[0];
                    nc += dir[1];
                }
            }
        }

        /**
         * Ensures every '*' in the original board has been marked as covered.
         */
        private boolean allStarsAreCovered() {
            for (int r = 0; r < height; r++) {
                for (int c = 0; c < width; c++) {
                    if (isStar(r, c) && !covered[r][c]) {
                        return false;
                    }
                }
            }
            return true;
        }

        private boolean isStar(int r, int c) {
            if (r < 0 || r >= height || c < 0 || c >= width) {
                return false;
            }
            return board[r].charAt(c) == '*';
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
