                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

/**
 * A program to validate if a grid contains a specific "cross" shape 
 * formed by '*' characters. The shape must consist of a vertical line 
 * and a horizontal line that intersect at a single point, where the 
 * intersection point has at least one '*' above, below, to the left, 
 * and to the right of it.
 */
public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        String[] grid = new String[rows];

        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.next();
        }

        if (isValidCrossShape(rows, cols, grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Validates the grid based on the specific logic:
     * 1. Finds the first '*' (anchor).
     * 2. Finds the first '*' that does not share a column with the anchor.
     * 3. Ensures all other '*' belong to the vertical line of the anchor 
     *    or the horizontal line of the second anchor.
     * 4. Checks that both lines extend in both directions relative to the intersection.
     *
     * @param rows Number of rows in the grid.
     * @param cols Number of columns in the grid.
     * @param grid The 2D grid of characters.
     * @return true if the shape matches the criteria, false otherwise.
     */
    private static boolean isValidCrossShape(int rows, int cols, String[] grid) {
        int anchorRow = -1;
        int anchorCol = -1;
        int intersectionRow = -1;
        int intersectionCol = -1;

        boolean isVerticalLineActive = false;
        boolean isHorizontalLineActive = false;

        // Phase 1: Identify the lines and ensure no stray '*' exist
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r].charAt(c) == '*') {
                    if (anchorRow == -1) {
                        // First star found: becomes the vertical line anchor
                        anchorRow = r;
                        anchorCol = c;
                        isVerticalLineActive = true;
                    } else if (isVerticalLineActive && c == anchorCol) {
                        // Continuing the vertical line
                        continue;
                    } else if (intersectionRow == -1) {
                        // First star found not in the anchor column: becomes the horizontal line anchor
                        intersectionRow = r;
                        intersectionCol = c;
                        isHorizontalLineActive = true;
                    } else if (isHorizontalLineActive && r == intersectionRow) {
                        // Continuing the horizontal line
                        continue;
                    } else {
                        // A '*' was found that doesn't belong to either line
                        return false;
                    }
                } else {
                    // Character is '.' - check if it breaks the continuity of active lines
                    if (isVerticalLineActive && anchorCol == c) {
                        isVerticalLineActive = false;
                    }
                    if (isHorizontalLineActive && intersectionRow == r) {
                        isHorizontalLineActive = false;
                    }
                }
            }
        }

        // Ensure we actually found both parts of the cross
        if (anchorRow == -1 || intersectionRow == -1) {
            return false;
        }

        // Phase 2: Validate vertical line continuity and arm lengths
        // The vertical line is at anchorCol. The intersection is at (intersectionRow, anchorCol).
        int verticalAbove = 0;
        int verticalBelow = 0;
        for (int r = anchorRow; r < rows; r++) {
            if (grid[r].charAt(anchorCol) != '*') {
                break;
            }
            if (r < intersectionRow) {
                verticalAbove++;
            } else if (r > intersectionRow) {
                verticalBelow++;
            } else {
                // This is the intersection point (r == intersectionRow)
                // We don't increment x/y here, but it's the pivot for y counting
            }
        }

        // The original code logic requirement: 
        // x (verticalAbove) >= 1 AND y (verticalBelow + 1) >= 1
        // Given the original loop: if (i >= tw) y++ (where y starts at -1), 
        // it requires at least one '*' at i == intersectionRow and one '*' at i > intersectionRow.
        if (verticalAbove < 1 || verticalBelow < 1) {
            return false;
        }

        // Phase 3: Validate horizontal line continuity and arm lengths
        // The horizontal line is at intersectionRow. The intersection is at (intersectionRow, anchorCol).
        int horizontalLeft = 0;
        int horizontalRight = 0;
        for (int c = intersectionCol; c < cols; c++) {
            if (grid[intersectionRow].charAt(c) != '*') {
                break;
            }
            if (c < anchorCol) {
                horizontalLeft++;
            } else if (c > anchorCol) {
                horizontalRight++;
            }
        }

        // Same requirement as vertical: needs stars on both sides of the intersection anchorCol
        if (horizontalLeft < 1 || horizontalRight < 1) {
            return false;
        }

        return true;
    }
}

