/**
 * Logic to analyze a grid of characters to detect a specific star pattern.
 */
class StarPatternAnalyzer {
    private static final char STAR_CHARACTER = '*';

    private final int height;
    private final int width;
    private final char[][] grid;
    private final int totalStarCount;

    public StarPatternAnalyzer(int height, int width, char[][] grid) {
        this.height = height;
        this.width = width;
        this.grid = grid;
        this.totalStarCount = countTotalStars();
    }

    private int countTotalStars() {
        int count = 0;
        for (int i = 0; i < height; i++) {
            for (int j = 0; j < width; j++) {
                if (grid[i][j] == STAR_CHARACTER) {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Checks if there is a star that acts as a center of a cross 
     * which contains all the stars in the grid.
     */
    public boolean hasCompleteCrossPattern() {
        if (totalStarCount == 0) {
            return false;
        }

        for (int i = 0; i < height; i++) {
            for (int j = 0; j < width; j++) {
                if (grid[i][j] == STAR_CHARACTER) {
                    if (isCenterOfCross(i, j)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    private boolean isCenterOfCross(int row, int col) {
        // Count consecutive stars in all 4 directions
        int up = countConsecutiveStars(row, col, -1, 0);
        int down = countConsecutiveStars(row, col, 1, 0);
        int left = countConsecutiveStars(row, col, 0, -1);
        int right = countConsecutiveStars(row, col, 0, 1);

        // A valid cross in this context requires arms in all four directions
        if (up > 0 && down > 0 && left > 0 && right > 0) {
            int crossTotal = up + down + left + right + 1;
            return crossTotal == totalStarCount;
        }

        return false;
    }

    /**
     * Helper to count stars in a specific direction.
     */
    private int countConsecutiveStars(int startRow, int startCol, int rowDir, int colDir) {
        int count = 0;
        int currentRow = startRow + rowDir;
        int currentCol = startCol + colDir;

        while (isWithinBounds(currentRow, currentCol) && grid[currentRow][currentCol] == STAR_CHARACTER) {
            count++;
            currentRow += rowDir;
            currentCol += colDir;
        }
        return count;
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < height && c >= 0 && c < width;
    }
}

/**
 * Main entry point for the application.
 */
public class StarPatternDetector {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();

        try {
            int height = scanner.nextInt();
            int width = scanner.nextInt();
            char[][] grid = new char[height][width];

            for (int i = 0; i < height; i++) {
                String rowString = scanner.next();
                for (int j = 0; j < width; j++) {
                    grid[i][j] = rowString.charAt(j);
                }
            }

            StarPatternAnalyzer analyzer = new StarPatternAnalyzer(height, width, grid);

            if (analyzer.hasCompleteCrossPattern()) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }

        } catch (Exception e) {
            // In a real application, handle or log exceptions appropriately
            System.err.println("An error occurred during execution: " + e.getMessage());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * Solves a grid pattern problem where a "cross" pattern (an obstacle surrounded 
 * by obstacles on all four cardinal sides) can be removed.
 * The goal is to determine if removing exactly one such cross clears the entire grid.
 */
public class GridPatternSolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        ProblemSolver solver = new ProblemSolver();
        solver.solve(reader, writer);

        writer.close();
    }

    static class ProblemSolver {

        /**
         * Orchestrates the reading, processing, and output of the grid problem.
         */
        public void solve(FastReader in, PrintWriter out) {
            int height = in.nextInt();
            int width = in.nextInt();
            boolean[][] grid = readGrid(in, height, width);

            boolean patternFound = findAndClearFirstCross(grid, height, width);

            if (!patternFound) {
                out.println("NO");
            } else {
                boolean leftovers = hasRemainingObstacles(grid, height, width);
                out.println(leftovers ? "NO" : "YES");
            }
        }

        private boolean[][] readGrid(FastReader in, int height, int width) {
            boolean[][] grid = new boolean[height][width];
            for (int i = 0; i < height; i++) {
                String line = in.next();
                for (int j = 0; j < width; j++) {
                    // true represents an obstacle (#), false represents empty (.)
                    grid[i][j] = (line.charAt(j) == '#');
                }
            }
            return grid;
        }

        /**
         * Searches the grid for the first instance of a cross pattern.
         * If found, it clears the cross and returns true.
         */
        private boolean findAndClearFirstCross(boolean[][] grid, int rows, int cols) {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (isCrossCenter(grid, r, c, rows, cols)) {
                        clearCross(grid, r, c, rows, cols);
                        return true;
                    }
                }
            }
            return false;
        }

        /**
         * Checks if the cell at (r, c) is the center of a cross pattern.
         */
        private boolean isCrossCenter(boolean[][] grid, int r, int c, int rows, int cols) {
            return grid[r][c] 
                && r > 0 && grid[r - 1][c]          // Up
                && r < rows - 1 && grid[r + 1][c]   // Down
                && c > 0 && grid[r][c - 1]          // Left
                && c < cols - 1 && grid[r][c + 1];  // Right
        }

        /**
         * Removes the cross pattern by setting connected cardinal cells to false.
         */
        private void clearCross(boolean[][] grid, int r, int c, int rows, int cols) {
            grid[r][c] = false;

            // Clear Up
            for (int i = r - 1; i >= 0 && grid[i][c]; i--) {
                grid[i][c] = false;
            }
            // Clear Down
            for (int i = r + 1; i < rows && grid[i][c]; i++) {
                grid[i][c] = false;
            }
            // Clear Left
            for (int j = c - 1; j >= 0 && grid[r][j]; j--) {
                grid[r][j] = false;
            }
            // Clear Right
            for (int j = c + 1; j < cols && grid[r][j]; j++) {
                grid[r][j] = false;
            }
        }

        /**
         * Checks if any obstacles remain in the grid.
         */
        private boolean hasRemainingObstacles(boolean[][] grid, int rows, int cols) {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j]) return true;
                }
            }
            return false;
        }
    }

    /**
     * Fast I/O utility for efficient reading of large inputs.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }
    }
}

