/**
 * Main class to orchestrate the execution of the Plus Shape Validator.
 */
public class Main {
    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                // Using next() instead of nextLine() to avoid issues with trailing newlines
                grid[i] = reader.next().toCharArray();
            }

            PlusShapeValidator validator = new PlusShapeValidator(rows, cols, grid);

            if (validator.isValid()) {
                writer.println("YES");
            } else {
                writer.println("NO");
            }
        } catch (Exception e) {
            // In a real application, use a logger
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    /**
     * Logic class responsible for determining if a grid contains exactly one 
     * plus shape and no other '*' characters.
     */
    static class PlusShapeValidator {
        private final int rows;
        private final int cols;
        private final char[][] grid;

        public PlusShapeValidator(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
        }

        /**
         * Validates if the grid contains exactly one plus shape that accounts for all '*' characters.
         * @return true if valid, false otherwise.
         */
        public boolean isValid() {
            Coordinate center = findSinglePlusCenter();

            // If no plus is found or more than one plus is found, it's invalid
            if (center == null) {
                return false;
            }

            clearCross(center.row, center.col);

            return !hasRemainingStars();
        }

        /**
         * Searches for a single '*' character that acts as the center of a plus shape.
         * @return The coordinates of the center, or null if 0 or >1 centers are found.
         */
        private Coordinate findSinglePlusCenter() {
            Coordinate foundCenter = null;

            for (int r = 1; r < rows - 1; r++) {
                for (int c = 1; c < cols - 1; c++) {
                    if (isPlusCenter(r, c)) {
                        if (foundCenter != null) {
                            // Found a second plus shape; invalid
                            return null;
                        }
                        foundCenter = new Coordinate(r, c);
                    }
                }
            }
            return foundCenter;
        }

        private boolean isPlusCenter(int r, int c) {
            return grid[r][c] == '*' &&
                   grid[r - 1][c] == '*' &&
                   grid[r + 1][c] == '*' &&
                   grid[r][c - 1] == '*' &&
                   grid[r][c + 1] == '*';
        }

        /**
         * Clears the vertical and horizontal lines of the plus shape from the grid.
         */
        private void clearCross(int r, int c) {
            // Clear Vertical Line
            for (int i = r; i >= 0 && grid[i][c] == '*'; i--) {
                grid[i][c] = '.';
            }
            for (int i = r + 1; i < rows && grid[i][c] == '*'; i++) {
                grid[i][c] = '.';
            }

            // Clear Horizontal Line
            for (int j = c; j >= 0 && grid[r][j] == '*'; j--) {
                grid[r][j] = '.';
            }
            for (int j = c + 1; j < cols && grid[r][j] == '*'; j++) {
                grid[r][j] = '.';
            }
        }

        private boolean hasRemainingStars() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '*') {
                        return true;
                    }
                }
            }
            return false;
        }

        /**
         * Simple data holder for grid coordinates.
         */
        private static class Coordinate {
            final int row;
            final int col;

            Coordinate(int row, int col) {
                this.row = row;
                this.col = col;
            }
        }
    }

    /**
     * Fast I/O reader for efficient input processing.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Problem: Determine if a grid of '*' characters forms a perfect cross shape.
 * A perfect cross has a center point with four contiguous arms (up, down, left, right)
 * and no other '*' characters in the grid.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        try {
            int height = reader.nextInt();
            int width = reader.nextInt();
            char[][] gridInput = new char[height][width];

            for (int i = 0; i < height; i++) {
                gridInput[i] = reader.next().toCharArray();
            }

            CrossPatternSolver solver = new CrossPatternSolver(height, width, gridInput);
            if (solver.isPerfectCross()) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }

        } catch (Exception e) {
            // In a production environment, use a logger. 
            // For algorithmic challenges, we output NO on unexpected input errors.
            System.out.println("NO");
        }
    }

    /**
     * Logic engine to validate the cross pattern.
     */
    static class CrossPatternSolver {
        private final int rows;
        private final int cols;
        private final boolean[][] grid;

        // Direction vectors for Up, Down, Left, Right
        private static final int[] DR = {-1, 1, 0, 0};
        private static final int[] DC = {0, 0, -1, 1};

        public CrossPatternSolver(int rows, int cols, char[][] input) {
            this.rows = rows;
            this.cols = cols;
            this.grid = new boolean[rows][cols];
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (input[i][j] == '*') {
                        grid[i][j] = true;
                    }
                }
            }
        }

        public boolean isPerfectCross() {
            int[] rowCounts = new int[rows];
            int[] colCounts = new int[cols];

            // 1. Calculate star counts per row and column
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c]) {
                        rowCounts[r]++;
                        colCounts[c]++;
                    }
                }
            }

            // 2. Identify the potential center (the intersection of rows/cols with > 1 star)
            int centerX = -1;
            int centerY = -1;

            for (int i = 0; i < rows; i++) {
                if (rowCounts[i] > 1) {
                    if (centerX != -1) return false; // More than one row has multiple stars
                    centerX = i;
                }
            }

            for (int j = 0; j < cols; j++) {
                if (colCounts[j] > 1) {
                    if (centerY != -1) return false; // More than one col has multiple stars
                    centerY = j;
                }
            }

            // 3. Validate center point existence and property
            if (centerX == -1 || centerY == -1 || !grid[centerX][centerY]) {
                return false;
            }

            // 4. Clear the center and all four arms
            grid[centerX][centerY] = false;
            for (int i = 0; i < 4; i++) {
                if (!clearArmInDirection(centerX, centerY, DR[i], DC[i])) {
                    return false; // An arm was missing or non-contiguous
                }
            }

            // 5. Ensure no stray stars remain
            return !hasRemainingStars();
        }

        /**
         * Traverses in a direction, clearing continuous '*' characters.
         * @return true if at least one star was found and cleared in this direction.
         */
        private boolean clearArmInDirection(int startR, int startC, int dr, int dc) {
            int currR = startR + dr;
            int currC = startC + dc;
            boolean foundStar = false;

            while (isValid(currR, currC) && grid[currR][currC]) {
                grid[currR][currC] = false;
                currR += dr;
                currC += dc;
                foundStar = true;
            }

            return foundStar;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        private boolean hasRemainingStars() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j]) return true;
                }
            }
            return false;
        }
    }

    /**
     * Efficient input reader.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;

/**
 * A program to determine if a given grid of characters forms a perfect, 
 * contiguous cross shape.
 */
public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        scanner.nextLine(); // Consume the leftover newline

        Grid grid = new Grid(rows, cols, scanner);

        if (isPerfectCross(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Validates if the grid forms a perfect cross.
     * A perfect cross is defined as a single contiguous row and a single 
     * contiguous column intersecting at a center point, with no other stars.
     */
    private static boolean isPerfectCross(Grid grid) {
        Point center = grid.findCenter();
        if (center == null) {
            return false;
        }

        int totalStars = grid.getTotalStars();

        // Validate the horizontal component
        RowInfo rowInfo = grid.getRowInfo(center.row);
        if (!rowInfo.isContiguous) {
            return false;
        }

        // Validate the vertical component
        ColInfo colInfo = grid.getColInfo(center.col);
        if (!colInfo.isContiguous) {
            return false;
        }

        // A cross is valid if the sum of stars in the row and column (minus the center)
        // matches the total number of stars in the entire grid.
        int crossStarCount = rowInfo.starCount + colInfo.starCount - 1;
        return crossStarCount == totalStars;
    }

    /**
     * Represents the grid of cells.
     */
    static class Grid {
        private final int rows;
        private final int cols;
        private final boolean[][] cells;
        private int totalStars = 0;

        public Grid(int rows, int cols, Scanner scanner) {
            this.rows = rows;
            this.cols = cols;
            this.cells = new boolean[rows][cols];
            parseGrid(scanner);
        }

        private void parseGrid(Scanner scanner) {
            for (int i = 0; i < rows; i++) {
                String line = scanner.nextLine();
                for (int j = 0; j < cols; j++) {
                    if (j < line.length() && line.charAt(j) == '*') {
                        cells[i][j] = true;
                        totalStars++;
                    }
                }
            }
        }

        public boolean isStar(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols && cells[r][c];
        }

        public int getTotalStars() {
            return totalStars;
        }

        /**
         * Finds a star that has four cardinal neighbors.
         */
        public Point findCenter() {
            // The center must be at least 1 cell away from edges to have 4 neighbors
            for (int i = 1; i < rows - 1; i++) {
                for (int j = 1; j < cols - 1; j++) {
                    if (cells[i][j] && 
                        cells[i - 1][j] && cells[i + 1][j] && 
                        cells[i][j - 1] && cells[i][j + 1]) {
                        return new Point(i, j);
                    }
                }
            }
            return null;
        }

        public RowInfo getRowInfo(int r) {
            int minCol = -1, maxCol = -1, count = 0;
            for (int j = 0; j < cols; j++) {
                if (cells[r][j]) {
                    if (minCol == -1) minCol = j;
                    maxCol = j;
                    count++;
                }
            }
            boolean contiguous = (count > 0) && (maxCol - minCol + 1 == count);
            return new RowInfo(count, contiguous);
        }

        public ColInfo getColInfo(int c) {
            int minRow = -1, maxRow = -1, count = 0;
            for (int i = 0; i < rows; i++) {
                if (cells[i][c]) {
                    if (minRow == -1) minRow = i;
                    maxRow = i;
                    count++;
                }
            }
            boolean contiguous = (count > 0) && (maxRow - minRow + 1 == count);
            return new ColInfo(count, contiguous);
        }
    }

    static class Point {
        final int row, col;
        Point(int row, int col) { this.row = row; this.col = col; }
    }

    static class RowInfo {
        final int starCount;
        final boolean isContiguous;
        RowInfo(int starCount, boolean isContiguous) {
            this.starCount = starCount;
            this.isContiguous = isContiguous;
        }
    }

    static class ColInfo {
        final int starCount;
        final boolean isContiguous;
        ColInfo(int starCount, boolean isContiguous) {
            this.starCount = starCount;
            this.isContiguous = isContiguous;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Main class to execute the plus-shape detection program.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            PlusShapeDetector detector = new PlusShapeDetector();
            boolean isPlus = detector.solve(reader);
            writer.println(isPlus ? "YES" : "NO");
        } catch (Exception e) {
            // In a real-world production scenario, use a proper logging framework.
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    /**
     * Class responsible for detecting if a grid contains a valid "plus" shape.
     * A plus shape is defined as a single row and a single column of contiguous 
     * stars that intersect at a non-endpoint position.
     */
    static class PlusShapeDetector {

        public boolean solve(FastReader reader) throws IOException {
            int height = reader.nextInt();
            int width = reader.nextInt();

            boolean[][] grid = new boolean[height][width];
            int totalStars = 0;

            for (int i = 0; i < height; i++) {
                String rowString = reader.next();
                for (int j = 0; j < width; j++) {
                    if (rowString.charAt(j) == '*') {
                        grid[i][j] = true;
                        totalStars++;
                    }
                }
            }

            return isValidPlusShape(grid, height, width, totalStars);
        }

        private boolean isValidPlusShape(boolean[][] grid, int height, int width, int totalStars) {
            int[] rowStarCounts = new int[height];
            int[] colStarCounts = new int[width];

            // Step 1: Count stars in each row and column
            for (int i = 0; i < height; i++) {
                for (int j = 0; j < width; j++) {
                    if (grid[i][j]) {
                        rowStarCounts[i]++;
                        colStarCounts[j]++;
                    }
                }
            }

            // Step 2: Identify the candidate row and column
            // A plus shape requires exactly one row and one column to have more than 1 star.
            int candidateRowIndex = findSingleLineIndex(rowStarCounts);
            int candidateColIndex = findSingleLineIndex(colStarCounts);

            if (candidateRowIndex == -1 || candidateColIndex == -1) {
                return false;
            }

            // Step 3: Validate row contiguity and get bounds
            LineStats rowStats = getLineStats(grid, candidateRowIndex, true, width);
            if (!isContiguous(rowStats)) {
                return false;
            }

            // Step 4: Validate column contiguity and get bounds
            LineStats colStats = getLineStats(grid, candidateColIndex, false, height);
            if (!isContiguous(colStats)) {
                return false;
            }

            // Step 5: Validate the intersection properties
            // Intersection must not be an endpoint (to ensure it's a plus, not a T or L shape)
            if (candidateColIndex == rowStats.minIndex || candidateColIndex == rowStats.maxIndex) {
                return false;
            }
            if (candidateRowIndex == colStats.minIndex || candidateRowIndex == colStats.maxIndex) {
                return false;
            }

            // Step 6: Verify total star count to ensure no stray stars exist elsewhere
            // Total stars in a perfect plus = starsInRow + starsInCol - 1 (for the intersection)
            int expectedStars = rowStats.count + colStats.count - 1;
            return totalStars == expectedStars;
        }

        private int findSingleLineIndex(int[] counts) {
            int index = -1;
            for (int i = 0; i < counts.length; i++) {
                if (counts[i] > 1) {
                    if (index != -1) return -1; // More than one line with > 1 star
                    index = i;
                }
            }
            return index;
        }

        private LineStats getLineStats(boolean[][] grid, int lineIndex, boolean isRow, int length) {
            int min = -1, max = -1, count = 0;

            for (int k = 0; k < length; k++) {
                boolean hasStar = isRow ? grid[lineIndex][k] : grid[k][lineIndex];
                if (hasStar) {
                    if (count == 0) min = k;
                    max = k;
                    count++;
                }
            }
            return new LineStats(min, max, count);
        }

        private boolean isContiguous(LineStats stats) {
            if (stats.count == 0) return false;
            return (stats.maxIndex - stats.minIndex + 1) == stats.count;
        }

        /**
         * Helper class to hold metadata about a line of stars.
         */
        private static class LineStats {
            final int minIndex;
            final int maxIndex;
            final int count;

            LineStats(int minIndex, int maxIndex, int count) {
                this.minIndex = minIndex;
                this.maxIndex = maxIndex;
                this.count = count;
            }
        }
    }

    /**
     * Fast I/O utility for reading input.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * CrossShapeDetector analyzes a grid of characters to determine if all 
 * '*' characters form exactly one continuous cross shape.
 */
public class CrossShapeDetector {

    public static void main(String[] args) {
        CrossShapeDetector detector = new CrossShapeDetector();
        detector.execute();
    }

    /**
     * Handles the orchestration of reading input, processing the grid, 
     * and printing the output.
     */
    public void execute() {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String firstLine = reader.readLine();
            if (firstLine == null) return;

            StringTokenizer st = new StringTokenizer(firstLine);
            if (!st.hasMoreTokens()) return;

            int height = Integer.parseInt(st.nextToken());
            int width = Integer.parseInt(st.nextToken());

            char[][] grid = new char[height][width];
            int totalStarsInGrid = 0;

            for (int i = 0; i < height; i++) {
                String row = reader.readLine();
                if (row == null) break;
                for (int j = 0; j < width; j++) {
                    // Safety check for short rows
                    char cell = (j < row.length()) ? row.charAt(j) : ' ';
                    grid[i][j] = cell;
                    if (cell == '*') {
                        totalStarsInGrid++;
                    }
                }
            }

            boolean result = checkIsSingleCross(grid, height, width, totalStarsInGrid);
            System.out.println(result ? "YES" : "NO");

        } catch (IOException | NumberFormatException e) {
            // In a production environment, use a logging framework.
            System.err.println("An error occurred while processing input: " + e.getMessage());
        }
    }

    /**
     * Determines if the '*' characters in the grid form a single, valid cross.
     * A cross is valid if it consists of a center and four arms, and the total 
     * number of stars in the cross equals the total stars in the grid.
     *
     * @param grid            The 2D character grid.
     * @param height          Number of rows.
     * @param width           Number of columns.
     * @param totalStarsInGrid The total count of '*' characters found in the grid.
     * @return true if the grid contains exactly one cross, false otherwise.
     */
    private boolean checkIsSingleCross(char[][] grid, int height, int width, int totalStarsInGrid) {
        // A cross requires at least a center and 4 immediate neighbors (minimum 5 stars).
        if (totalStarsInGrid < 5) {
            return false;
        }

        // We iterate through all potential center points. 
        // A center cannot be on the edge because a cross requires neighbors in all 4 directions.
        for (int r = 1; r < height - 1; r++) {
            for (int c = 1; c < width - 1; c++) {
                if (isCenterOfCross(grid, r, c)) {
                    int crossStarCount = calculateCrossStarCount(grid, r, c, height, width);

                    // If the cross discovered uses exactly the amount of stars available in the grid,
                    // it means no other '*' characters exist outside this single cross.
                    if (crossStarCount == totalStarsInGrid) {
                        return true;
                    }
                }
            }
        }

        return false;
    }

    /**
     * Checks if the specified cell is a valid center for a cross (contains '*' 
     * and has '*' neighbors in all four cardinal directions).
     */
    private boolean isCenterOfCross(char[][] grid, int r, int c) {
        return grid[r][c] == '*' &&
               grid[r - 1][c] == '*' &&
               grid[r + 1][c] == '*' &&
               grid[r][c - 1] == '*' &&
               grid[r][c + 1] == '*';
    }

    /**
     * Calculates the total number of '*' characters that belong to the 
     * cross centered at (r, c).
     */
    private int calculateCrossStarCount(char[][] grid, int r, int c, int height, int width) {
        int count = 1; // Start with the center star

        // Add the lengths of the four arms
        count += countArmLength(grid, r, c, -1, 0, height, width); // Up
        count += countArmLength(grid, r, c, 1, 0, height, width);  // Down
        count += countArmLength(grid, r, c, 0, -1, height, width); // Left
        count += countArmLength(grid, r, c, 0, 1, height, width);  // Right

        return count;
    }

    /**
     * Traverses in a given direction from a starting point and counts 
     * consecutive '*' characters.
     *
     * @param dr Direction row offset.
     * @param dc Direction column offset.
     * @return The number of consecutive '*' found.
     */
    private int countArmLength(char[][] grid, int r, int c, int dr, int dc, int height, int width) {
        int length = 0;
        int currR = r + dr;
        int currC = c + dc;

        while (currR >= 0 && currR < height && currC >= 0 && currC < width && grid[currR][currC] == '*') {
            length++;
            currR += dr;
            currC += dc;
        }
        return length;
    }
}

import java.util.Scanner;

/**
 * A utility to determine if the stars in a grid form a single, complete cross pattern.
 */
public class StarPatternChecker {

    private final int height;
    private final int width;
    private final char[][] grid;
    private final int totalStarsInGrid;

    /**
     * Constructs a new checker for a given grid.
     *
     * @param height The number of rows in the grid.
     * @param width  The number of columns in the grid.
     * @param grid   The 2D character array representing the grid.
     */
    public StarPatternChecker(int height, int width, char[][] grid) {
        this.height = height;
        this.width = width;
        this.grid = grid;
        this.totalStarsInGrid = countTotalStars();
    }

    /**
     * Validates if the stars in the grid form a cross pattern that accounts for all stars.
     *
     * @return true if the stars form exactly one cross pattern; false otherwise.
     */
    public boolean isCrossPattern() {
        // A cross requires at least a center and 4 arms (minimum 5 stars)
        // and must have a grid size of at least 3x3.
        if (height < 3 || width < 3 || totalStarsInGrid < 5) {
            return false;
        }

        // Iterate through the inner grid (excluding borders) to find a potential center
        for (int r = 1; r < height - 1; r++) {
            for (int c = 1; c < width - 1; c++) {
                if (isPotentialCenter(r, c)) {
                    if (calculateCrossStarCount(r, c) == totalStarsInGrid) {
                        return true;
                    }
                }
            }
        }

        return false;
    }

    /**
     * Counts the total number of '*' characters in the grid.
     */
    private int countTotalStars() {
        int count = 0;
        for (int i = 0; i < height; i++) {
            for (int j = 0; j < width; j++) {
                if (grid[i][j] == '*') {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Checks if the star at (r, c) has immediate neighbors in all four directions.
     */
    private boolean isPotentialCenter(int r, int c) {
        return grid[r][c] == '*' &&
               grid[r - 1][c] == '*' &&
               grid[r + 1][c] == '*' &&
               grid[r][c - 1] == '*' &&
               grid[r][c + 1] == '*';
    }

    /**
     * Calculates the total number of stars belonging to a cross centered at (r, c).
     */
    private int calculateCrossStarCount(int r, int c) {
        int count = 1; // Start with the center star
        count += countArmLength(r, c, -1, 0); // Up
        count += countArmLength(r, c, 1, 0);  // Down
        count += countArmLength(r, c, 0, -1); // Left
        count += countArmLength(r, c, 0, 1);  // Right
        return count;
    }

    /**
     * Iteratively counts stars in a specific direction from a starting point.
     *
     * @param r Starting row.
     * @param c Starting column.
     * @param dr Direction row offset.
     * @param dc Direction column offset.
     * @return The number of consecutive stars in that direction.
     */
    private int countArmLength(int r, int c, int dr, int dc) {
        int length = 0;
        int currR = r + dr;
        int currC = c + dc;

        while (isValidPosition(currR, currC) && grid[currR][currC] == '*') {
            length++;
            currR += dr;
            currC += dc;
        }
        return length;
    }

    private boolean isValidPosition(int r, int c) {
        return r >= 0 && r < height && c >= 0 && c < width;
    }

    /**
     * Entry point of the application.
     */
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        try {
            if (!scanner.hasNextInt()) return;

            int h = scanner.nextInt();
            int w = scanner.nextInt();
            char[][] grid = new char[h][w];

            for (int i = 0; i < h; i++) {
                String line = scanner.next();
                for (int j = 0; j < w; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }

            StarPatternChecker checker = new StarPatternChecker(h, w, grid);

            if (checker.isCrossPattern()) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        } catch (Exception e) {
            // In a production environment, use a proper logging framework
            System.err.println("Error processing input: " + e.getMessage());
        } finally {
            scanner.close();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Application to determine if a grid of characters contains a "perfect plus" shape.
 * A perfect plus shape consists of a center '*' and arms extending in all four 
 * cardinal directions such that the sum of all '*' in the arms and the center 
 * equals the total number of '*' in the entire grid.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int height = reader.nextInt();
            int width = reader.nextInt();

            char[][] grid = new char[height][width];
            for (int i = 0; i < height; i++) {
                grid[i] = reader.next().toCharArray();
            }

            AsteriskGrid asteriskGrid = new AsteriskGrid(grid);
            if (asteriskGrid.hasPerfectPlusShape()) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        } catch (IOException | NoSuchElementException e) {
            out.println("Error reading input: " + e.getMessage());
        } finally {
            out.flush();
            out.close();
        }
    }
}

class AsteriskGrid {
    private final char[][] grid;
    private final int height;
    private final int width;
    private final int totalAsterisks;

    // Direction vectors for: Up, Down, Left, Right
    private static final int[][] DIRECTIONS = {
        {-1, 0}, // Up
        {1, 0},  // Down
        {0, -1}, // Left
        {0, 1}   // Right
    };

    public AsteriskGrid(char[][] grid) {
        this.grid = grid;
        this.height = grid.length;
        this.width = (height > 0) ? grid[0].length : 0;
        this.totalAsterisks = countTotalAsterisks();
    }

    /**
     * Checks if there is a '*' that serves as a center for a plus shape 
     * that consumes all '*' in the grid.
     */
    public boolean hasPerfectPlusShape() {
        // A plus shape requires at least a center and 4 arms (total 5 stars)
        if (totalAsterisks < 5) {
            return false;
        }

        // Iterate through the grid, skipping the edges as a center 
        // cannot be on the edge and have 4 arms.
        for (int r = 1; r < height - 1; r++) {
            for (int c = 1; c < width - 1; c++) {
                if (grid[r][c] == '*') {
                    if (isPerfectPlusAt(r, c)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    private boolean isPerfectPlusAt(int row, int col) {
        int armSum = 0;
        boolean allDirectionsHaveArms = true;

        for (int[] dir : DIRECTIONS) {
            int armLength = countArmLength(row, col, dir[0], dir[1]);

            // The problem implies arms must exist in all 4 directions
            if (armLength == 0) {
                allDirectionsHaveArms = false;
                break;
            }
            armSum += armLength;
        }

        if (!allDirectionsHaveArms) {
            return false;
        }

        // Total count = center (1) + sum of all arm lengths
        return (armSum + 1) == totalAsterisks;
    }

    private int countArmLength(int row, int col, int dRow, int dCol) {
        int count = 0;
        int currentRow = row + dRow;
        int currentCol = col + dCol;

        while (isWithinBounds(currentRow, currentCol) && grid[currentRow][currentCol] == '*') {
            count++;
            currentRow += dRow;
            currentCol += dCol;
        }
        return count;
    }

    private int countTotalAsterisks() {
        int count = 0;
        for (int i = 0; i < height; i++) {
            for (int j = 0; j < width; j++) {
                if (grid[i][j] == '*') {
                    count++;
                }
            }
        }
        return count;
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < height && c >= 0 && c < width;
    }
}

/**
 * Fast I/O utility class.
 */
class FastReader {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    public FastReader(InputStream input) {
        this.reader = new BufferedReader(new InputStreamReader(input));
    }

    public String next() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreElements()) {
            String line = reader.readLine();
            if (line == null) return null;
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    public int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    public long nextLong() throws IOException {
        return Long.parseLong(next());
    }

    public double nextDouble() throws IOException {
        return Double.parseDouble(next());
    }
}

import java.util.Scanner;
import java.util.Optional;

/**
 * A program to analyze a grid of stars and determine if the stars
 * form a single, continuous, valid cross pattern.
 */
public class StarGridPattern {

    private static final char STAR = '*';
    private static final char EMPTY = '.';

    private final int height;
    private final int width;
    private final char[][] grid;

    /**
     * Represents a coordinate point within the grid.
     */
    private static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    public StarGridPattern(int height, int width, char[][] grid) {
        this.height = height;
        this.width = width;
        this.grid = grid;
    }

    /**
     * Validates if the grid contains a single valid star cross.
     *
     * @return true if a valid cross pattern is found, false otherwise.
     */
    public boolean isValidPattern() {
        return findCenter().map(this::validateCross).orElse(false);
    }

    /**
     * Searches for the first star that qualifies as a "center" 
     * (a star with immediate neighbors in all four cardinal directions).
     */
    private Optional<Point> findCenter() {
        // A center must have neighbors, so we iterate from the inner bounds
        for (int r = 1; r < height - 1; r++) {
            for (int c = 1; c < width - 1; c++) {
                if (isStar(r, c) &&
                    isStar(r - 1, c) && isStar(r + 1, c) &&
                    isStar(r, c - 1) && isStar(r, c + 1)) {
                    return Optional.of(new Point(r, c));
                }
            }
        }
        return Optional.empty();
    }

    /**
     * Validates the cross pattern relative to a found center.
     */
    private boolean validateCross(Point center) {
        return isExclusivityMaintained(center) &&
               isRowContinuous(center.row) &&
               isColumnContinuous(center.col);
    }

    /**
     * Ensures that no stars exist in the grid outside of the 
     * horizontal and vertical lines formed by the center.
     */
    private boolean isExclusivityMaintained(Point center) {
        for (int r = 0; r < height; r++) {
            for (int c = 0; c < width; c++) {
                if (isStar(r, c)) {
                    // If a star is not on the center's row AND not on the center's column, 
                    // it's an invalid star for this cross.
                    if (r != center.row && c != center.col) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    /**
     * Checks if all stars on the specified row are contiguous (no gaps).
     */
    private boolean isRowContinuous(int row) {
        int firstCol = -1;
        int lastCol = -1;

        for (int c = 0; c < width; c++) {
            if (isStar(row, c)) {
                if (firstCol == -1) firstCol = c;
                lastCol = c;
            }
        }

        if (firstCol == -1) return true;

        for (int c = firstCol; c <= lastCol; c++) {
            if (!isStar(row, c)) return false;
        }
        return true;
    }

    /**
     * Checks if all stars on the specified column are contiguous (no gaps).
     */
    private boolean isColumnContinuous(int col) {
        int firstRow = -1;
        int lastRow = -1;

        for (int r = 0; r < height; r++) {
            if (isStar(r, col)) {
                if (firstRow == -1) firstRow = r;
                lastRow = r;
            }
        }

        if (firstRow == -1) return true;

        for (int r = firstRow; r <= lastRow; r++) {
            if (!isStar(r, col)) return false;
        }
        return true;
    }

    private boolean isStar(int r, int c) {
        return grid[r][c] == STAR;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int h = scanner.nextInt();
        if (!scanner.hasNextInt()) return;
        int w = scanner.nextInt();

        char[][] grid = new char[h][w];
        for (int i = 0; i < h; i++) {
            String rowString = scanner.next();
            for (int j = 0; j < w; j++) {
                grid[i][j] = rowString.charAt(j);
            }
        }

        StarGridPattern analyzer = new StarGridPattern(h, w, grid);
        if (analyzer.isValidPattern()) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }
}

import java.util.Scanner;

/**
 * A utility to determine if a grid of characters contains exactly one "plus" shape
 * that accounts for all non-empty cells in the grid.
 */
public class PlusFromPicture {

    private static final int EMPTY = 0;
    private static final int FILLED = 1;
    private static final char TARGET_EMPTY_CHAR = '.';

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int height = scanner.nextInt();
            int width = scanner.nextInt();

            // Consume the remaining newline character after reading integers
            if (scanner.hasNextLine()) {
                scanner.nextLine();
            }

            int[][] grid = parseGrid(scanner, height, width);
            System.out.println(solve(height, width, grid));
        }
    }

    /**
     * Orchestrates the logic to determine if the grid represents a single valid plus.
     */
    private static String solve(int height, int width, int[][] grid) {
        // If there are no filled cells at all, it doesn't form a plus.
        if (isGridEmpty(grid, height, width)) {
            return "NO";
        }

        int[] center = findPlusCenter(grid, height, width);
        if (center == null) {
            return "NO";
        }

        // If a plus is found, clear the entire cross-shaped structure.
        clearPlusShape(grid, center[0], center[1], height, width);

        // If clearing the plus leaves no other filled cells, the answer is YES.
        return isGridEmpty(grid, height, width) ? "YES" : "NO";
    }

    /**
     * Parses the input scanner into a 2D integer grid.
     */
    private static int[][] parseGrid(Scanner scanner, int height, int width) {
        int[][] grid = new int[height][width];
        for (int r = 0; r < height; r++) {
            if (scanner.hasNextLine()) {
                String line = scanner.nextLine();
                for (int c = 0; c < width; c++) {
                    // If the character is not the empty char, mark as FILLED
                    if (c < line.length() && line.charAt(c) != TARGET_EMPTY_CHAR) {
                        grid[r][c] = FILLED;
                    } else {
                        grid[r][c] = EMPTY;
                    }
                }
            }
        }
        return grid;
    }

    /**
     * Searches for a cell that acts as the center of a 3x3 plus shape.
     * @return An array containing {row, col} of the center, or null if none found.
     */
    private static int[] findPlusCenter(int[][] grid, int height, int width) {
        // A plus center must have at least one cell of padding on all sides.
        for (int r = 1; r < height - 1; r++) {
            for (int c = 1; c < width - 1; c++) {
                if (isCenterOfMinimalPlus(grid, r, c)) {
                    return new int[]{r, c};
                }
            }
        }
        return null;
    }

    /**
     * Checks if a specific cell and its 4 immediate neighbors are all FILLED.
     */
    private static boolean isCenterOfMinimalPlus(int[][] grid, int r, int c) {
        return grid[r][c] == FILLED &&
               grid[r + 1][c] == FILLED &&
               grid[r - 1][c] == FILLED &&
               grid[r][c + 1] == FILLED &&
               grid[r][c - 1] == FILLED;
    }

    /**
     * Erases the plus shape and its entire continuous arms from the grid.
     */
    private static void clearPlusShape(int[][] grid, int r, int c, int height, int width) {
        grid[r][c] = EMPTY;

        // Clear vertical arm (downwards)
        int currentRow = r;
        while (currentRow + 1 < height && grid[currentRow + 1][c] == FILLED) {
            grid[currentRow + 1][c] = EMPTY;
            currentRow++;
        }

        // Clear vertical arm (upwards)
        currentRow = r;
        while (currentRow - 1 >= 0 && grid[currentRow - 1][c] == FILLED) {
            grid[currentRow - 1][c] = EMPTY;
            currentRow--;
        }

        // Clear horizontal arm (rightwards)
        int currentCol = c;
        while (currentCol + 1 < width && grid[r][currentCol + 1] == FILLED) {
            grid[r][currentCol + 1] = EMPTY;
            currentCol++;
        }

        // Clear horizontal arm (leftwards)
        currentCol = c;
        while (currentCol - 1 >= 0 && grid[r][currentCol - 1] == FILLED) {
            grid[r][currentCol - 1] = EMPTY;
            currentCol--;
        }
    }

    /**
     * Checks if the entire grid consists only of EMPTY cells.
     */
    private static boolean isGridEmpty(int[][] grid, int height, int width) {
        for (int r = 0; r < height; r++) {
            for (int c = 0; c < width; c++) {
                if (grid[r][c] == FILLED) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Problem Solver: Determines if a single "cross" pattern of stars ('*') 
 * can be removed from a grid to leave it completely empty.
 */
public class CrossPatternSolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        // Read dimensions
        String hStr = reader.next();
        String wStr = reader.next();
        if (hStr == null || wStr == null) return;

        int height = Integer.parseInt(hStr);
        int width = Integer.parseInt(wStr);

        char[][] grid = new char[height][width];
        int totalStars = 0;

        // Read grid and count total stars
        for (int i = 0; i < height; i++) {
            String row = reader.next();
            for (int j = 0; j < width; j++) {
                grid[i][j] = row.charAt(j);
                if (grid[i][j] == '*') {
                    totalStars++;
                }
            }
        }

        // Handle edge case: no stars in grid
        if (totalStars == 0) {
            System.out.println("NO");
            return;
        }

        // Iterate through the grid (excluding borders) to find a cross center
        for (int i = 1; i < height - 1; i++) {
            for (int j = 1; j < width - 1; j++) {
                if (isCrossCenter(grid, i, j)) {
                    // If a cross is found, attempt to clear it and check if all stars are gone
                    if (tryClearCross(grid, i, j, totalStars)) {
                        System.out.println("YES");
                    } else {
                        System.out.println("NO");
                    }
                    return;
                }
            }
        }

        // No valid cross found that satisfies the condition
        System.out.println("NO");
    }

    /**
     * Checks if the cell at (r, c) is a star and has four immediate star neighbors.
     */
    private static boolean isCrossCenter(char[][] grid, int r, int c) {
        return grid[r][c] == '*' &&
               grid[r - 1][c] == '*' &&
               grid[r + 1][c] == '*' &&
               grid[r][c - 1] == '*' &&
               grid[r][c + 1] == '*';
    }

    /**
     * Clears the cross pattern starting from the center and counts how many stars were removed.
     * Returns true if the number of removed stars equals the initial total star count.
     */
    private static boolean tryClearCross(char[][] grid, int r, int c, int totalStars) {
        int starsRemoved = 0;
        int height = grid.length;
        int width = grid[0].length;

        // Directions: Up, Down, Left, Right
        int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

        // Clear the center
        grid[r][c] = '.';
        starsRemoved++;

        // Clear the arms of the cross
        for (int[] dir : directions) {
            int nextR = r + dir[0];
            int nextC = c + dir[1];

            while (nextR >= 0 && nextR < height && nextC >= 0 && nextC < width && grid[nextR][nextC] == '*') {
                grid[nextR][nextC] = '.';
                starsRemoved++;
                nextR += dir[0];
                nextC += dir[1];
            }
        }

        return starsRemoved == totalStars;
    }

    /**
     * Efficient utility class for reading input.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

/**
 * A utility class to validate if a grid of characters contains exactly one T-shaped pattern.
 * A T-shape consists of a vertical stem and a horizontal bar intersecting it.
 */
public class TeeShapeValidator {

    private static final char TARGET_CHAR = '*';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        // Read dimensions
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        scanner.nextLine(); // Consume the trailing newline character after nextInt()

        // Initialize and populate the grid
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.nextLine();
            for (int j = 0; j < cols; j++) {
                // Safety check for lines shorter than expected width
                grid[i][j] = (j < line.length()) ? line.charAt(j) : ' ';
            }
        }

        // Perform validation and output result
        if (isValidTeeShape(grid, rows, cols)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Validates if the provided grid contains exactly one T-shape made of '*' characters.
     *
     * @param grid The 2D character array representing the grid.
     * @param rows Number of rows in the grid.
     * @param cols Number of columns in the grid.
     * @return true if exactly one T-shape is found and no other '*' exist, false otherwise.
     */
    private static boolean isValidTeeShape(char[][] grid, int rows, int cols) {
        // 1. Find the first asterisk in the grid to identify the potential stem start
        int startRow = -1;
        int startCol = -1;

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == TARGET_CHAR) {
                    startRow = i;
                    startCol = j;
                    break;
                }
            }
            if (startRow != -1) break;
        }

        // If no asterisks are found, it is not a valid T-shape
        if (startRow == -1) {
            return false;
        }

        // 2. Validate constraints for the top of the stem
        // The first asterisk cannot have horizontal neighbors
        if (isTarget(grid, startRow, startCol - 1, rows, cols) ||
            isTarget(grid, startRow, startCol + 1, rows, cols)) {
            return false;
        }

        // The first asterisk cannot be on the last row or on the edge columns
        if (startRow == rows - 1 || startCol == 0 || startCol == cols - 1) {
            return false;
        }

        // 3. Trace the vertical stem and identify the junction row
        int stemLength = 0;
        int junctionRow = -1;
        int stemEndRow = -1;
        boolean junctionFound = false;

        for (int r = startRow; r < rows; r++) {
            if (grid[r][startCol] == TARGET_CHAR) {
                stemLength++;
                stemEndRow = r;

                // Check if this row is a junction (has horizontal neighbors)
                if (!junctionFound) {
                    if (isTarget(grid, r, startCol - 1, rows, cols) ||
                        isTarget(grid, r, startCol + 1, rows, cols)) {
                        junctionRow = r;
                        junctionFound = true;
                    }
                }
            } else {
                // The vertical continuity of the stem is broken
                break;
            }
        }

        // 4. Validate T-shape structural requirements
        // Requirement: stem length must be at least 3, a junction must exist, 
        // and the junction cannot be the very last cell of the stem.
        if (stemLength < 3 || !junctionFound || junctionRow == stemEndRow) {
            return false;
        }

        // 5. Validate the horizontal bar at the junction row
        int leftBarWidth = 0;
        int rightBarWidth = 0;

        // Count contiguous '*' to the left of the junction
        for (int c = startCol - 1; c >= 0; c--) {
            if (grid[junctionRow][c] == TARGET_CHAR) {
                leftBarWidth++;
            } else {
                break;
            }
        }

        // Count contiguous '*' to the right of the junction
        for (int c = startCol + 1; c < cols; c++) {
            if (grid[junctionRow][c] == TARGET_CHAR) {
                rightBarWidth++;
            } else {
                break;
            }
        }

        // The junction must extend both left and right to be a valid bar
        if (leftBarWidth == 0 || rightBarWidth == 0) {
            return false;
        }

        // 6. Verify that every '*' in the grid is part of this single identified T-shape
        return verifyAllAsterisksCovered(grid, rows, cols, startRow, startCol, 
                                        stemEndRow, junctionRow, leftBarWidth, rightBarWidth);
    }

    /**
     * Helper to check if a specific cell contains the target character while respecting bounds.
     */
    private static boolean isTarget(char[][] grid, int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] == TARGET_CHAR;
    }

    /**
     * Ensures that no '*' characters exist in the grid outside of the identified T-shape.
     */
    private static boolean verifyAllAsterisksCovered(char[][] grid, int rows, int cols,
                                                     int startRow, int startCol, int stemEndRow,
                                                     int junctionRow, int leftWidth, int rightWidth) {
        boolean[][] visited = new boolean[rows][cols];

        // Mark the vertical stem as visited
        for (int r = startRow; r <= stemEndRow; r++) {
            visited[r][startCol] = true;
        }

        // Mark the horizontal bar as visited
        for (int c = startCol - leftWidth; c <= startCol + rightWidth; c++) {
            visited[junctionRow][c] = true;
        }

        // Scan the entire grid; if any '*' is not visited, the pattern is invalid
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == TARGET_CHAR && !visited[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.io.*;
import java.util.*;

/**
 * A program that determines if a grid contains exactly one cross-shaped pattern
 * such that removing its arms leaves only the center star.
 */
public class CrossPatternSolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] grid = reader.readGrid(rows, cols);

            if (solve(rows, cols, grid)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        } catch (Exception e) {
            // In a real-world scenario, use a logger
            e.printStackTrace();
        }
    }

    /**
     * Orchestrates the logic of finding a cross and checking the remaining stars.
     * 
     * @param rows Number of rows in the grid
     * @param cols Number of columns in the grid
     * @param grid The 2D character grid
     * @return true if a cross is found and only its center remains, false otherwise
     */
    private static boolean solve(int rows, int cols, char[][] grid) {
        boolean crossFound = false;

        // Search for a cell that acts as a center of a cross
        // We skip the boundary rows and columns as a center must have neighbors
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (isCrossCenter(i, j, grid)) {
                    crossFound = true;
                    eraseCrossArms(i, j, grid, rows, cols);
                    // According to original logic, we stop after finding the first cross
                    break;
                }
            }
            if (crossFound) break;
        }

        int remainingStars = countStars(grid, rows, cols);

        // The pattern is valid if we found a cross and only the center star remains
        return crossFound && remainingStars == 1;
    }

    /**
     * Checks if the cell at (r, c) is a '*' and has '*' neighbors in all four directions.
     */
    private static boolean isCrossCenter(int r, int c, char[][] grid) {
        return grid[r][c] == '*' &&
               grid[r - 1][c] == '*' &&
               grid[r + 1][c] == '*' &&
               grid[r][c - 1] == '*' &&
               grid[r][c + 1] == '*';
    }

    /**
     * Erases the horizontal and vertical arms of the cross, leaving the center intact.
     */
    private static void eraseCrossArms(int r, int c, char[][] grid, int rows, int cols) {
        // Erase Upward arm
        int currR = r;
        while (currR > 0 && grid[currR - 1][c] == '*') {
            grid[currR - 1][c] = '.';
            currR--;
        }

        // Erase Downward arm
        currR = r;
        while (currR < rows - 1 && grid[currR + 1][c] == '*') {
            grid[currR + 1][c] = '.';
            currR++;
        }

        // Erase Leftward arm
        int currC = c;
        while (currC > 0 && grid[r][currC - 1] == '*') {
            grid[r][currC - 1] = '.';
            currC--;
        }

        // Erase Rightward arm
        currC = c;
        while (currC < cols - 1 && grid[r][currC + 1] == '*') {
            grid[r][currC + 1] = '.';
            currC++;
        }
    }

    /**
     * Counts the number of '*' characters remaining in the grid.
     */
    private static int countStars(char[][] grid, int rows, int cols) {
        int count = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*') {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Optimized reader for fast input processing.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public char[][] readGrid(int rows, int cols) {
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = next().toCharArray();
            }
            return grid;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * CrossPatternChecker identifies if a grid contains exactly one "plus" shape
 * consisting of '*' characters that covers all non-'.' characters in the grid.
 */
public class CrossPatternChecker {

    private static final char EMPTY_CHAR = '.';
    private static final char TARGET_CHAR = '*';

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        // Read grid dimensions
        String nStr = reader.next();
        String mStr = reader.next();

        if (nStr == null || mStr == null) {
            return;
        }

        int rows = Integer.parseInt(nStr);
        int cols = Integer.parseInt(mStr);

        // Read the grid content
        char[][] grid = reader.readGrid(rows, cols);

        // Execute validation and output result
        if (isCrossPatternValid(grid, rows, cols)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Orchestrates the validation process: finding the center, expanding arms, 
     * and verifying the coverage.
     */
    private static boolean isCrossPatternValid(char[][] grid, int rows, int cols) {
        int centerRow = -1;
        int centerCol = -1;
        int centersFound = 0;

        // 1. Find the potential center of the cross.
        // According to original logic, a center is a '*' that has 
        // non-empty neighbors above and to the left.
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (grid[i][j] == TARGET_CHAR && 
                    grid[i - 1][j] != EMPTY_CHAR && 
                    grid[i][j - 1] != EMPTY_CHAR) {

                    centersFound++;
                    centerRow = i;
                    centerCol = j;
                }
            }
        }

        // Requirement: Exactly one such center must exist.
        if (centersFound != 1) {
            return false;
        }

        // 2. Expand arms from the center to mark all cells belonging to the cross.
        boolean[][] visited = new boolean[rows][cols];
        if (!expandArms(grid, visited, centerRow, centerCol, rows, cols)) {
            return false;
        }

        // 3. Verify that every non-empty cell in the grid was part of the cross.
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] != EMPTY_CHAR && !visited[i][j]) {
                    return false;
                }
            }
        }

        return true;
    }

    /**
     * Expands in four directions from the center to mark the cross arms.
     * Returns false if any arm is too short (must be at least length 1 excluding center).
     */
    private static boolean expandArms(char[][] grid, boolean[][] visited, int r, int c, int rows, int cols) {
        visited[r][c] = true;

        // Directions: Down, Up, Right, Left
        int[][] directions = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

        for (int[] dir : directions) {
            int nextR = r + dir[0];
            int nextC = c + dir[1];

            // Rule: Each arm must extend at least one cell beyond the center.
            if (isOutOfBounds(nextR, nextC, rows, cols) || grid[nextR][nextC] != TARGET_CHAR) {
                return false;
            }

            // Continue expanding the arm as long as we encounter target characters.
            while (!isOutOfBounds(nextR, nextC, rows, cols) && grid[nextR][nextC] == TARGET_CHAR) {
                visited[nextR][nextC] = true;
                nextR += dir[0];
                nextC += dir[1];
            }
        }
        return true;
    }

    private static boolean isOutOfBounds(int r, int c, int rows, int cols) {
        return r < 0 || r >= rows || c < 0 || c >= cols;
    }

    /**
     * Efficient input reader for handling large datasets.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public char[][] readGrid(int rows, int cols) {
            char[][] grid = new char[rows][cols];
            try {
                for (int i = 0; i < rows; i++) {
                    String line = reader.readLine();
                    if (line != null) {
                        char[] rowChars = line.toCharArray();
                        for (int j = 0; j < cols && j < rowChars.length; j++) {
                            grid[i][j] = rowChars[j];
                        }
                    }
                }
            } catch (IOException e) {
                // Log error if necessary
            }
            return grid;
        }
    }
}

import java.util.Scanner;
import java.io.PrintWriter;
import java.io.OutputStream;

/**
 * Represents the visual grid of the picture.
 */
class Grid {
    private final char[][] cells;
    private final int height;
    private final int width;
    private final int totalStarCount;

    public Grid(int height, int width, Scanner scanner) {
        this.height = height;
        this.width = width;
        this.cells = new char[height][width];
        this.totalStarCount = countStarsAndFill(scanner);
    }

    private int countStarsAndFill(Scanner scanner) {
        int count = 0;
        for (int i = 0; i < height; i++) {
            if (scanner.hasNext()) {
                String rowData = scanner.next();
                for (int j = 0; j < width; j++) {
                    cells[i][j] = rowData.charAt(j);
                    if (cells[i][j] == '*') {
                        count++;
                    }
                }
            }
        }
        return count;
    }

    public char getCell(int row, int col) {
        return cells[row][col];
    }

    public int getHeight() {
        return height;
    }

    public int getWidth() {
        return width;
    }

    public int getTotalStarCount() {
        return totalStarCount;
    }
}

/**
 * Contains the logic to detect if the stars in a Grid form exactly one plus shape.
 */
class PlusShapeDetector {

    // Direction vectors for: Up, Down, Left, Right
    private static final int[][] DIRECTIONS = {
            {-1, 0}, // Up
            {1, 0},  // Down
            {0, -1}, // Left
            {0, 1}   // Right
    };

    /**
     * Checks if the grid contains a single plus shape that accounts for all '*' characters.
     */
    public boolean containsExactPlusShape(Grid grid) {
        for (int i = 1; i < grid.getHeight() - 1; i++) {
            for (int j = 1; j < grid.getWidth() - 1; j++) {
                if (grid.getCell(i, j) == '*') {
                    if (isPlusAt(grid, i, j)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    private boolean isPlusAt(Grid grid, int row, int col) {
        int totalPlusStars = 1; // Start with the center star
        int[] armLengths = new int[4];

        for (int d = 0; d < 4; d++) {
            armLengths[d] = countConsecutiveStars(grid, row, col, DIRECTIONS[d][0], DIRECTIONS[d][1]);

            // A valid plus must extend at least one star in every direction
            if (armLengths[d] == 0) {
                return false;
            }
            totalPlusStars += armLengths[d];
        }

        // The plus is valid only if its size matches the total star count in the grid
        return totalPlusStars == grid.getTotalStarCount();
    }

    private int countConsecutiveStars(Grid grid, int row, int col, int rowDir, int colDir) {
        int count = 0;
        int currR = row + rowDir;
        int currC = col + colDir;

        while (isValidPosition(grid, currR, currC) && grid.getCell(currR, currC) == '*') {
            count++;
            currR += rowDir;
            currC += colDir;
        }
        return count;
    }

    private boolean isValidPosition(Grid grid, int r, int c) {
        return r >= 0 && r < grid.getHeight() && c >= 0 && c < grid.getWidth();
    }
}

public class Main {
    public static void main(String[] args) {
        // Using try-with-resources for automatic stream management
        try (Scanner in = new Scanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            if (!in.hasNextInt()) return;

            int height = in.nextInt();
            if (!in.hasNextInt()) return;
            int width = in.nextInt();

            Grid grid = new Grid(height, width, in);
            PlusShapeDetector detector = new PlusShapeDetector();

            if (detector.containsExactPlusShape(grid)) {
                out.println("YES");
            } else {
                out.println("NO");
            }
            out.flush();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A utility to validate if the asterisks in a grid form a perfect cross shape.
 */
public class CrossShapeValidator {

    private static final char ASTERISK = '*';
    private static final char MARKED = '@';

    // Direction vectors for Up, Right, Down, Left
    private static final int[] ROW_DIRECTIONS = {1, 0, -1, 0};
    private static final int[] COL_DIRECTIONS = {0, 1, 0, -1};

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int n = reader.nextInt();
            int m = reader.nextInt();
            char[][] grid = new char[n][m];

            for (int i = 0; i < n; i++) {
                grid[i] = reader.next().toCharArray();
            }

            if (isValidCross(grid, n, m)) {
                writer.println("YES");
            } else {
                writer.println("NO");
            }
        } catch (Exception e) {
            // In a competitive programming context, we might just exit. 
            // In production, we would log this.
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Determines if the provided grid contains exactly one perfect cross shape made of asterisks.
     */
    private static boolean isValidCross(char[][] grid, int rows, int cols) {
        int[] center = findPotentialCenter(grid, rows, cols);
        int centerRow = center[0];
        int centerCol = center[1];

        // If no center was found or the center itself is not an asterisk
        if (centerRow == -1 || centerCol == -1 || grid[centerRow][centerCol] != ASTERISK) {
            return false;
        }

        // Mark the center
        grid[centerRow][centerCol] = MARKED;

        // Attempt to expand in all 4 directions
        for (int i = 0; i < 4; i++) {
            if (!expandAndMark(grid, rows, cols, centerRow, centerCol, i)) {
                return false;
            }
        }

        // If the cross is valid, no asterisks should be left in the grid
        return !hasRemainingAsterisks(grid, rows, cols);
    }

    /**
     * Finds the intersection of the row and column containing the maximum number of asterisks.
     * @return An array [row, col] or [-1, -1] if no asterisks exist.
     */
    private static int[] findPotentialCenter(char[][] grid, int rows, int cols) {
        int maxRowIdx = -1;
        int maxColIdx = -1;
        int maxRowAsterisks = 0;
        int maxColAsterisks = 0;

        // Find row with most asterisks
        for (int i = 0; i < rows; i++) {
            int count = 0;
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == ASTERISK) count++;
            }
            if (count > maxRowAsterisks) {
                maxRowAsterisks = count;
                maxRowIdx = i;
            }
        }

        // Find column with most asterisks
        for (int j = 0; j < cols; j++) {
            int count = 0;
            for (int i = 0; i < rows; i++) {
                if (grid[i][j] == ASTERISK) count++;
            }
            if (count > maxColAsterisks) {
                maxColAsterisks = count;
                maxColIdx = j;
            }
        }

        if (maxRowAsterisks == 0 || maxColAsterisks == 0) {
            return new int[]{-1, -1};
        }

        return new int[]{maxRowIdx, maxColIdx};
    }

    /**
     * Traverses in a specific direction from the center and marks asterisks.
     * @return true if at least one asterisk was found in that direction.
     */
    private static boolean expandAndMark(char[][] grid, int rows, int cols, int r, int c, int direction) {
        int count = 0;
        int currR = r + ROW_DIRECTIONS[direction];
        int currC = c + COL_DIRECTIONS[direction];

        while (isValidBounds(currR, currC, rows, cols) && grid[currR][currC] == ASTERISK) {
            grid[currR][currC] = MARKED;
            count++;
            currR += ROW_DIRECTIONS[direction];
            currC += COL_DIRECTIONS[direction];
        }

        // A valid cross must have at least one star in every cardinal direction
        return count > 0;
    }

    private static boolean isValidBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private static boolean hasRemainingAsterisks(char[][] grid, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == ASTERISK) return true;
            }
        }
        return false;
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * This program determines if all '*' characters in a grid form a single 
 * continuous cross shape (a center cell with horizontal and vertical arms).
 */
public class Solution {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            char[][] grid = new char[rows][cols];
            boolean hasStars = false;

            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                    if (grid[i][j] == CrossPatternValidator.STAR_CHARACTER) {
                        hasStars = true;
                    }
                }
            }

            CrossPatternValidator validator = new CrossPatternValidator(grid, rows, cols);
            boolean isValid = validator.isValidCrossPattern(hasStars);

            System.out.println(isValid ? "YES" : "NO");

        } catch (IOException | NoSuchElementException e) {
            System.out.println("NO");
        }
    }

    /**
     * Custom exception for handling input errors gracefully.
     */
    private static class NoSuchElementException extends RuntimeException {}

    /**
     * Logic handler for validating the cross pattern in the grid.
     */
    static class CrossPatternValidator {
        public static final char STAR_CHARACTER = '*';

        private final char[][] grid;
        private final int rows;
        private final int cols;

        public CrossPatternValidator(char[][] grid, int rows, int cols) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
        }

        /**
         * Validates if all stars in the grid are part of a single cross.
         * 
         * @param hasStars Boolean indicating if any stars exist in the grid.
         * @return true if all stars are covered by a single cross, false otherwise.
         */
        public boolean isValidCrossPattern(boolean hasStars) {
            if (!hasStars) {
                return false;
            }

            CrossCenter center = findFirstCrossCenter();
            if (center == null) {
                return false;
            }

            boolean[][] isCovered = markCrossArms(center.row, center.col);
            return areAllStarsCovered(isCovered);
        }

        /**
         * Searches for the first cell that acts as a center of a cross.
         */
        private CrossCenter findFirstCrossCenter() {
            for (int i = 1; i < rows - 1; i++) {
                for (int j = 1; j < cols - 1; j++) {
                    if (isCenterOfCross(i, j)) {
                        return new CrossCenter(i, j);
                    }
                }
            }
            return null;
        }

        private boolean isCenterOfCross(int r, int c) {
            return grid[r][c] == STAR_CHARACTER &&
                   grid[r - 1][c] == STAR_CHARACTER &&
                   grid[r + 1][c] == STAR_CHARACTER &&
                   grid[r][c - 1] == STAR_CHARACTER &&
                   grid[r][c + 1] == STAR_CHARACTER;
        }

        /**
         * Marks all cells belonging to the horizontal and vertical arms of the cross.
         */
        private boolean[][] markCrossArms(int centerRow, int centerCol) {
            boolean[][] isCovered = new boolean[rows][cols];

            // Mark vertical arm
            for (int k = centerRow; k < rows && grid[k][centerCol] == STAR_CHARACTER; k++) {
                isCovered[k][centerCol] = true;
            }
            for (int k = centerRow; k >= 0 && grid[k][centerCol] == STAR_CHARACTER; k--) {
                isCovered[k][centerCol] = true;
            }

            // Mark horizontal arm
            for (int k = centerCol; k < cols && grid[centerRow][k] == STAR_CHARACTER; k++) {
                isCovered[centerRow][k] = true;
            }
            for (int k = centerCol; k >= 0 && grid[centerRow][k] == STAR_CHARACTER; k--) {
                isCovered[centerRow][k] = true;
            }

            return isCovered;
        }

        /**
         * Checks if there are any '*' cells that were not covered by the cross arms.
         */
        private boolean areAllStarsCovered(boolean[][] isCovered) {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == STAR_CHARACTER && !isCovered[i][j]) {
                        return false;
                    }
                }
            }
            return true;
        }

        private static class CrossCenter {
            final int row;
            final int col;

            CrossCenter(int row, int col) {
                this.row = row;
                this.col = col;
            }
        }
    }

    /**
     * Optimized reader for fast I/O operations.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            if (next == null) throw new NoSuchElementException();
            return Integer.parseInt(next);
        }
    }
}

import java.util.Scanner;

/**
 * A utility to analyze a grid of characters to determine if it contains
 * exactly one "star" pattern that covers all '*' characters in the grid.
 * A star pattern is defined as a '*' cell with four '*' neighbors, 
 * and the pattern consists of all contiguous '*' cells in the same 
 * row and column as the center.
 */
public class StarPatternChecker {

    private static final char STAR_CHAR = '*';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int height = scanner.nextInt();
        int width = scanner.nextInt();
        char[][] grid = new char[height][width];

        for (int i = 0; i < height; i++) {
            String rowInput = scanner.next();
            grid[i] = rowInput.toCharArray();
        }

        if (isValidStarPattern(grid, height, width)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Performs the main logic to check if the grid meets the star criteria.
     * 
     * @param grid The 2D character array.
     * @param h Height of the grid.
     * @param w Width of the grid.
     * @return true if exactly one star pattern covers all '*' in the grid.
     */
    private static boolean isValidStarPattern(char[][] grid, int h, int w) {
        int centerRow = -1;
        int centerCol = -1;
        int centersFound = 0;

        // 1. Find all potential star centers
        // A center cannot be on the edge because it requires 4 neighbors.
        for (int r = 1; r < h - 1; r++) {
            for (int c = 1; c < w - 1; c++) {
                if (isStarCenter(grid, r, c)) {
                    centersFound++;
                    centerRow = r;
                    centerCol = c;
                }
            }
        }

        // Requirement: There must be exactly one center found.
        if (centersFound != 1) {
            return false;
        }

        // 2. Mark the star's cross (all contiguous '*' in the 4 directions)
        boolean[][] covered = new boolean[h][w];
        markStarCross(grid, covered, centerRow, centerCol, h, w);

        // 3. Verify that every '*' in the grid was part of that star's cross.
        for (int r = 0; r < h; r++) {
            for (int c = 0; c < w; c++) {
                if (grid[r][c] == STAR_CHAR && !covered[r][c]) {
                    return false;
                }
            }
        }

        return true;
    }

    /**
     * Checks if a specific cell is a star center (has 4 '*' neighbors).
     */
    private static boolean isStarCenter(char[][] grid, int r, int c) {
        return grid[r][c] == STAR_CHAR &&
               grid[r - 1][c] == STAR_CHAR &&
               grid[r + 1][c] == STAR_CHAR &&
               grid[r][c - 1] == STAR_CHAR &&
               grid[r][c + 1] == STAR_CHAR;
    }

    /**
     * Marks the center and all contiguous '*' in the four cardinal directions.
     */
    private static void markStarCross(char[][] grid, boolean[][] covered, int r, int c, int h, int w) {
        covered[r][c] = true;

        // Directions: Up, Down, Left, Right
        int[][] directions = {
            {-1, 0}, {1, 0}, {0, -1}, {0, 1}
        };

        for (int[] dir : directions) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            // Continue moving in the current direction as long as we hit '*'
            while (nr >= 0 && nr < h && nc >= 0 && nc < w && grid[nr][nc] == STAR_CHAR) {
                covered[nr][nc] = true;
                nr += dir[0];
                nc += dir[1];
            }
        }
    }
}

