class GridPatternSolver {
    private static final char STAR = '*';
    private static final char DOT = '.';
    private static final char FILLED = 'O';

    private final char[][] grid;
    private final int rows;
    private final int cols;

    public GridPatternSolver(char[][] grid, int rows, int cols) {
        this.grid = grid;
        this.rows = rows;
        this.cols = cols;
    }

    /**
     * Executes the logic to trace the vertical and horizontal paths.
     * @return true if all stars are cleared by the defined pattern.
     */
    public boolean solve() {
        int startRow = -1;
        int startCol = -1;

        // 1. Find the first occurrence of a star to begin the vertical path
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == STAR) {
                    startRow = i;
                    startCol = j;
                    break;
                }
            }
            if (startRow != -1) break;
        }

        // If no star is found, we cannot form a path
        if (startRow == -1) {
            return false;
        }

        int verticalPathLength = 0;
        int horizontalRow = -1;
        int horizontalStartCol = -1;

        // 2. Trace the vertical path downwards
        int currentRow = startRow;
        int currentCol = startCol;

        while (currentRow >= 0 && currentRow < rows && grid[currentRow][currentCol] == STAR) {
            verticalPathLength++;
            grid[currentRow][currentCol] = FILLED;

            // Check if this specific star position qualifies as the "pivot" for a horizontal line
            // Conditions: Has stars to its left and right, and no empty dots above or below it.
            if (horizontalRow == -1 && isPivotCandidate(currentRow, currentCol)) {
                if (!hasAdjacentVerticalEmptySpace(currentRow, currentCol)) {
                    horizontalRow = currentRow;
                    horizontalStartCol = 0;
                }
            }
            currentRow++;
        }

        // 3. Trace the horizontal path if a pivot was found
        int horizontalPathLength = 0;
        if (horizontalRow != -1) {
            int currentColIdx = horizontalStartCol;
            while (currentColIdx < cols) {
                char cell = grid[horizontalRow][currentColIdx];

                if (cell == STAR || cell == FILLED) {
                    grid[horizontalRow][currentColIdx] = FILLED;
                    horizontalPathLength++;
                }

                // Stop if we hit an empty dot
                if (horizontalPathLength > 0 && grid[horizontalRow][currentColIdx] == DOT) {
                    break;
                }
                currentColIdx++;
            }
        }

        // 4. Validate final state
        return isPatternSuccessful(verticalPathLength, horizontalPathLength);
    }

    /**
     * Checks if the current cell has neighbors that could form a horizontal bar.
     */
    private boolean isPivotCandidate(int r, int c) {
        return c > 0 && (c + 1) < cols && 
               grid[r][c - 1] == STAR && 
               grid[r][c + 1] == STAR;
    }

    /**
     * Checks if there is a '.' immediately above or below the cell.
     */
    private boolean hasAdjacentVerticalEmptySpace(int r, int c) {
        if (r + 1 < rows && grid[r + 1][c] == DOT) return true;
        if (r - 1 >= 0 && grid[r - 1][c] == DOT) return true;
        return false;
    }

    /**
     * Final check to ensure all stars are gone and both paths were validly formed.
     */
    private boolean isPatternSuccessful(int vLen, int hLen) {
        return !containsStar() && containsFilled() && vLen > 0 && hLen > 0;
    }

    private boolean containsStar() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == STAR) return true;
            }
        }
        return false;
    }

    private boolean containsFilled() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == FILLED) return true;
            }
        }
        return false;
    }
}

import java.util.Scanner;

/**
 * A program that determines if a grid consists of exactly one cross-shaped pattern.
 * A cross-shaped pattern is defined as a central '#' cell with four cardinal '#' neighbors,
 * which extends in all four directions until a '.' is encountered.
 */
public class GridPatternMatcher {

    private static final int CELL_EMPTY = 0;
    private static final int CELL_FILLED = 1;

    /**
     * Represents a coordinate in the grid.
     */
    private static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }

        int height = scanner.nextInt();
        int width = scanner.nextInt();
        String[] inputRows = new String[height];

        for (int i = 0; i < height; i++) {
            inputRows[i] = scanner.next();
        }

        if (analyzeGrid(height, width, inputRows)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Orchestrates the grid analysis logic.
     * 
     * @return true if the grid contains exactly one cross pattern and nothing else.
     */
    private static boolean analyzeGrid(int height, int width, String[] inputRows) {
        int[][] grid = initializeGrid(height, width, inputRows);

        // 1. Locate the first instance of a cross pattern center
        Point crossCenter = findFirstCrossCenter(grid, height, width);

        // If no center is found, the condition fails
        if (crossCenter == null) {
            return false;
        }

        // 2. Remove the cross pattern found
        removeCrossPattern(grid, crossCenter, height, width);

        // 3. Check if there are any '#' characters left in the grid
        return isGridEmpty(grid, height, width);
    }

    /**
     * Converts the input strings into a 2D integer array with padding.
     * Padding helps prevent ArrayOutOfBounds exceptions when checking neighbors.
     */
    private static int[][] initializeGrid(int height, int width, String[] inputRows) {
        int[][] grid = new int[height + 2][width + 2];
        for (int i = 1; i <= height; i++) {
            String row = inputRows[i - 1];
            for (int j = 1; j <= width; j++) {
                grid[i][j] = (row.charAt(j - 1) == '#') ? CELL_FILLED : CELL_EMPTY;
            }
        }
        return grid;
    }

    /**
     * Searches the grid for the first cell that acts as a cross center.
     */
    private static Point findFirstCrossCenter(int[][] grid, int height, int width) {
        for (int i = 1; i <= height; i++) {
            for (int j = 1; j <= width; j++) {
                if (isCrossCenter(grid, i, j)) {
                    return new Point(i, j);
                }
            }
        }
        return null;
    }

    /**
     * Checks if a specific cell and its four cardinal neighbors are all filled.
     */
    private static boolean isCrossCenter(int[][] grid, int r, int c) {
        return grid[r][c] == CELL_FILLED
                && grid[r - 1][c] == CELL_FILLED
                && grid[r + 1][c] == CELL_FILLED
                && grid[r][c - 1] == CELL_FILLED
                && grid[r][c + 1] == CELL_FILLED;
    }

    /**
     * Clears the cross pattern from the grid starting from the given center.
     */
    private static void removeCrossPattern(int[][] grid, Point center, int height, int width) {
        int r = center.row;
        int c = center.col;

        // Clear center
        grid[r][c] = CELL_EMPTY;

        // Clear Right
        int currentCol = c + 1;
        while (currentCol <= width && grid[r][currentCol] == CELL_FILLED) {
            grid[r][currentCol] = CELL_EMPTY;
            currentCol++;
        }

        // Clear Left
        currentCol = c - 1;
        while (currentCol >= 1 && grid[r][currentCol] == CELL_FILLED) {
            grid[r][currentCol] = CELL_EMPTY;
            currentCol--;
        }

        // Clear Down
        int currentRow = r + 1;
        while (currentRow <= height && grid[currentRow][c] == CELL_FILLED) {
            grid[currentRow][c] = CELL_EMPTY;
            currentRow++;
        }

        // Clear Up
        currentRow = r - 1;
        while (currentRow >= 1 && grid[currentRow][c] == CELL_FILLED) {
            grid[currentRow][c] = CELL_EMPTY;
            currentRow--;
        }
    }

    /**
     * Scans the grid to see if any '#' cells remain.
     */
    private static boolean isGridEmpty(int[][] grid, int height, int width) {
        for (int i = 1; i <= height; i++) {
            for (int j = 1; j <= width; j++) {
                if (grid[i][j] == CELL_FILLED) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.util.Scanner;

/**
 * A utility to detect if a grid contains exactly one cross pattern 
 * and no other arbitrary '*' characters.
 */
public class CrossPatternMatcher {

    private final int height;
    private final int width;
    private final boolean[][] grid;

    public CrossPatternMatcher(int height, int width, boolean[][] grid) {
        this.height = height;
        this.width = width;
        this.grid = grid;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int h = scanner.nextInt();
        int w = scanner.nextInt();

        boolean[][] inputGrid = new boolean[h][w];
        for (int i = 0; i < h; i++) {
            String rowString = scanner.next();
            for (int j = 0; j < w; j++) {
                inputGrid[i][j] = (rowString.charAt(j) == '*');
            }
        }

        CrossPatternMatcher matcher = new CrossPatternMatcher(h, w, inputGrid);
        System.out.println(matcher.solve() ? "YES" : "NO");

        scanner.close();
    }

    /**
     * Orchestrates the logic to determine if the grid matches a perfect cross.
     * @return true if a single cross is found and it matches the grid exactly.
     */
    public boolean solve() {
        int[] center = findFirstCrossCenter();

        // If no valid cross center is found, it's not a valid cross grid.
        if (center == null) {
            return false;
        }

        boolean[][] crossMask = generateCrossMask(center[0], center[1]);

        return isGridIdentical(grid, crossMask);
    }

    /**
     * Searches for the first cell that can act as the center of a cross.
     * @return int array [row, col] if found, otherwise null.
     */
    private int[] findFirstCrossCenter() {
        for (int r = 0; r < height; r++) {
            for (int c = 0; c < width; c++) {
                if (isCenterOfCross(r, c)) {
                    return new int[]{r, c};
                }
            }
        }
        return null;
    }

    /**
     * Checks if the cell at (row, col) is the center of a cross.
     * A center must have '*' neighbors in all four cardinal directions.
     */
    private boolean isCenterOfCross(int r, int c) {
        return grid[r][c] 
                && isWithinBounds(r - 1, c) && grid[r - 1][c] // Up
                && isWithinBounds(r + 1, c) && grid[r + 1][c] // Down
                && isWithinBounds(r, c - 1) && grid[r][c - 1] // Left
                && isWithinBounds(r, c + 1) && grid[r][c + 1]; // Right
    }

    /**
     * Creates a boolean grid representing only the cross formed by the center.
     */
    private boolean[][] generateCrossMask(int centerRow, int centerCol) {
        boolean[][] mask = new boolean[height][width];
        mask[centerRow][centerCol] = true;

        // Mark vertical line
        for (int r = centerRow; r >= 0 && grid[r][centerCol]; r--) {
            mask[r][centerCol] = true;
        }
        for (int r = centerRow + 1; r < height && grid[r][centerCol]; r++) {
            mask[r][centerCol] = true;
        }

        // Mark horizontal line
        for (int c = centerCol; c >= 0 && grid[centerRow][c]; c--) {
            mask[centerRow][c] = true;
        }
        for (int c = centerCol + 1; c < width && grid[centerRow][c]; c++) {
            mask[centerRow][c] = true;
        }

        return mask;
    }

    /**
     * Compares two boolean grids for equality.
     */
    private boolean isGridIdentical(boolean[][] grid1, boolean[][] grid2) {
        for (int r = 0; r < height; r++) {
            for (int c = 0; c < width; c++) {
                if (grid1[r][c] != grid2[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < height && c >= 0 && c < width;
    }
}

import java.util.*;
import java.io.*;

/**
 * This class determines if all '*' characters in a grid can be covered 
 * by a single '+' shaped pattern. A '+' shape is defined by a center '*' 
 * and its four immediate cardinal neighbors being '*'.
 */
public class GridPatternMatcher {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        // Note: Defaulting to single test case logic as per original structure.
        // To support multiple test cases, wrap solve() in a loop in main.
        solve(reader);
    }

    /**
     * Orchestrates the logic to read the grid and determine if a single 
     * plus sign can cover all '*' cells.
     */
    static void solve(FastReader reader) {
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = reader.next().toCharArray();
        }

        boolean[][] isCovered = new boolean[rows][cols];
        boolean isPlusFound = false;

        // 1. Find the first valid '+' center and mark its coverage
        // A '+' center cannot be on the edge of the grid.
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (canBePlusCenter(grid, i, j)) {
                    markPlusSign(grid, isCovered, i, j);
                    isPlusFound = true;
                    break; // We only look for one plus sign as per original logic
                }
            }
            if (isPlusFound) break;
        }

        // 2. Validate if the found plus sign covers all '*' cells
        if (isPlusFound && allStarsCovered(grid, isCovered)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Checks if the cell at (r, c) can act as the center of a '+' shape.
     */
    private static boolean canBePlusCenter(char[][] grid, int r, int c) {
        return grid[r][c] == '*' &&
               grid[r - 1][c] == '*' &&
               grid[r + 1][c] == '*' &&
               grid[r][c - 1] == '*' &&
               grid[r][c + 1] == '*';
    }

    /**
     * Expands from the center (r, c) in all four directions and marks
     * cells as covered in the boolean array.
     */
    private static void markPlusSign(char[][] grid, boolean[][] isCovered, int r, int c) {
        int rows = grid.length;
        int cols = grid[0].length;

        // Mark center
        isCovered[r][c] = true;

        // Expand Up
        for (int i = r - 1; i >= 0 && grid[i][c] == '*'; i--) {
            isCovered[i][c] = true;
        }
        // Expand Down
        for (int i = r + 1; i < rows && grid[i][c] == '*'; i++) {
            isCovered[i][c] = true;
        }
        // Expand Left
        for (int j = c - 1; j >= 0 && grid[r][j] == '*'; j--) {
            isCovered[r][j] = true;
        }
        // Expand Right
        for (int j = c + 1; j < cols && grid[r][j] == '*'; j++) {
            isCovered[r][j] = true;
        }
    }

    /**
     * Verifies that every '*' cell in the original grid has been marked as covered.
     */
    private static boolean allStarsCovered(char[][] grid, boolean[][] isCovered) {
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[0].length; j++) {
                if (grid[i][j] == '*' && !isCovered[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Optimized reader for fast I/O operations.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A program to determine if a grid of characters contains exactly one 
 * plus-shaped pattern composed of all '*' characters.
 */
public class PlusFromPicture {

    public static void main(String[] args) {
        // Using try-with-resources for automatic resource management of I/O streams
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out))) {

            if (!scanner.hasNextInt()) {
                return;
            }

            int height = scanner.nextInt();
            int width = scanner.nextInt();

            Grid grid = new Grid(height, width, scanner);
            PlusAnalyzer analyzer = new PlusAnalyzer(grid);

            if (analyzer.isValidPlusPattern()) {
                out.println("YES");
            } else {
                out.println("NO");
            }

        } catch (Exception e) {
            // In a real-world application, use a logging framework like SLF4J.
            System.err.println("An error occurred while processing the grid: " + e.getMessage());
        }
    }

    /**
     * Represents the 2D character grid and provides spatial query operations.
     */
    static class Grid {
        private final int height;
        private final int width;
        private final char[][] cells;

        public Grid(int height, int width, Scanner scanner) {
            this.height = height;
            this.width = width;
            this.cells = new char[height][width];
            for (int i = 0; i < height; i++) {
                String row = scanner.next();
                for (int j = 0; j < width; j++) {
                    cells[i][j] = row.charAt(j);
                }
            }
        }

        public int getHeight() {
            return height;
        }

        public int getWidth() {
            return width;
        }

        /**
         * Checks if a specific coordinate contains a star and is within bounds.
         */
        public boolean isStar(int r, int c) {
            return r >= 0 && r < height && c >= 0 && c < width && cells[r][c] == '*';
        }

        /**
         * Counts the total number of '*' characters in the entire grid.
         */
        public int countTotalStars() {
            int count = 0;
            for (int i = 0; i < height; i++) {
                for (int j = 0; j < width; j++) {
                    if (cells[i][j] == '*') {
                        count++;
                    }
                }
            }
            return count;
        }

        /**
         * Identifies all cells that could act as the center of a plus shape.
         * A center must be a '*' with '*' neighbors in all four cardinal directions.
         */
        public List<Point> findPotentialCenters() {
            List<Point> centers = new ArrayList<>();
            // A center cannot exist on the outermost boundary of the grid
            for (int i = 1; i < height - 1; i++) {
                for (int j = 1; j < width - 1; j++) {
                    if (isStar(i, j) &&
                        isStar(i - 1, j) && isStar(i + 1, j) &&
                        isStar(i, j - 1) && isStar(i, j + 1)) {
                        centers.add(new Point(i, j));
                    }
                }
            }
            return centers;
        }

        /**
         * Calculates how many '*' cells are part of the plus shape centered at the given point.
         */
        public int countStarsInPlus(Point center) {
            int count = 1; // Start with the center cell
            int r = center.row;
            int c = center.col;

            // Expand Up
            for (int i = r - 1; i >= 0 && isStar(i, c); i--) count++;
            // Expand Down
            for (int i = r + 1; i < height && isStar(i, c); i++) count++;
            // Expand Left
            for (int j = c - 1; j >= 0 && isStar(r, j); j--) count++;
            // Expand Right
            for (int j = c + 1; j < width && isStar(r, j); j++) count++;

            return count;
        }
    }

    /**
     * Encapsulates the business logic to validate the plus pattern.
     */
    static class PlusAnalyzer {
        private final Grid grid;

        public PlusAnalyzer(Grid grid) {
            this.grid = grid;
        }

        /**
         * Validates if the grid contains exactly one plus shape that 
         * encompasses every single '*' in the grid.
         */
        public boolean isValidPlusPattern() {
            int totalStars = grid.countTotalStars();

            // A plus shape requires at least 5 stars (center + 4 directions)
            if (totalStars < 5) {
                return false;
            }

            List<Point> centers = grid.findPotentialCenters();

            // To form a single, non-overlapping plus shape, there must be exactly one center.
            if (centers.size() != 1) {
                return false;
            }

            Point center = centers.get(0);
            // If the number of stars in the identified plus matches the total stars, 
            // then the pattern is valid.
            return grid.countStarsInPlus(center) == totalStars;
        }
    }

    /**
     * Simple immutable data carrier for grid coordinates.
     */
    static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }
}

import java.util.Scanner;

/**
 * A utility to detect if a grid contains exactly one "cross" shape 
 * that encompasses all the active cells ('#') in the grid.
 */
public class CrossPatternDetector {

    private static final int CELL_ON = 1;
    private static final int CELL_OFF = 0;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int height = scanner.nextInt();
        int width = scanner.nextInt();

        int[][] grid = new int[height][width];
        int totalOnesCount = 0;

        // Parse the grid from input
        for (int i = 0; i < height; i++) {
            String row = scanner.next();
            for (int j = 0; j < width; j++) {
                if (row.charAt(j) == '#') {
                    grid[i][j] = CELL_ON;
                    totalOnesCount++;
                } else {
                    grid[i][j] = CELL_OFF;
                }
            }
        }

        if (isSingleCrossShape(grid, height, width, totalOnesCount)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Determines if all active cells in the grid form a single cross pattern.
     * 
     * @param grid The 2D representation of the grid.
     * @param height Height of the grid.
     * @param width Width of the grid.
     * @param totalOnesCount The total number of '1' cells found in the grid.
     * @return true if a single cross contains all active cells, false otherwise.
     */
    public static boolean isSingleCrossShape(int[][] grid, int height, int width, int totalOnesCount) {
        // If there are no active cells, the pattern requirements aren't met.
        if (totalOnesCount == 0) {
            return false;
        }

        // Directions for expansion: Down, Up, Right, Left
        int[] dr = {1, -1, 0, 0};
        int[] dc = {0, 0, 1, -1};

        // Search for a potential center of the cross.
        // A center must have 4 immediate neighbors that are also active cells.
        for (int i = 1; i < height - 1; i++) {
            for (int j = 1; j < width - 1; j++) {
                if (isPotentialCenter(grid, i, j)) {
                    int crossSize = countCrossCells(grid, i, j, height, width, dr, dc);

                    // If the number of cells in this specific cross matches 
                    // the total active cells in the grid, it's a valid single cross.
                    if (crossSize == totalOnesCount) {
                        return true;
                    }
                }
            }
        }

        return false;
    }

    /**
     * Checks if a specific cell is a valid center for a cross.
     */
    private static boolean isPotentialCenter(int[][] grid, int r, int c) {
        return grid[r][c] == CELL_ON &&
               grid[r + 1][c] == CELL_ON &&
               grid[r - 1][c] == CELL_ON &&
               grid[r][c + 1] == CELL_ON &&
               grid[r][c - 1] == CELL_ON;
    }

    /**
     * Calculates the total number of cells belonging to a cross centered at (startR, startC).
     */
    private static int countCrossCells(int[][] grid, int startR, int startC, 
                                       int height, int width, int[] dr, int[] dc) {
        int count = 1; // Start with the center cell

        // Expand in all four cardinal directions
        for (int i = 0; i < 4; i++) {
            int currentRow = startR + dr[i];
            int currentCol = startC + dc[i];

            while (isWithinBounds(currentRow, currentCol, height, width) 
                   && grid[currentRow][currentCol] == CELL_ON) {
                count++;
                currentRow += dr[i];
                currentCol += dc[i];
            }
        }
        return count;
    }

    private static boolean isWithinBounds(int r, int c, int height, int width) {
        return r >= 0 && r < height && c >= 0 && c < width;
    }
}

import java.util.Scanner;

/**
 * A solver that determines if a grid can be entirely cleared by removing 
 * a single cross-shaped pattern.
 */
public class CrossPatternSolver {

    private static final char TARGET_CHAR = '*';
    private static final char EMPTY_CHAR = '.';

    private final int height;
    private final int width;
    private final char[][] grid;

    public CrossPatternSolver(int height, int width, char[][] grid) {
        this.height = height;
        this.width = width;
        this.grid = grid;
    }

    /**
     * Orchestrates the logic to solve the grid puzzle.
     * @return "YES" if the grid is cleared by removing one cross, "NO" otherwise.
     */
    public String solve() {
        // A cross pattern requires at least a 3x3 area to exist
        if (height < 3 || width < 3) {
            return "NO";
        }

        for (int r = 1; r < height - 1; r++) {
            for (int c = 1; c < width - 1; c++) {
                if (isCrossCenter(r, c)) {
                    clearCrossPattern(r, c);
                    return isGridEmpty() ? "YES" : "NO";
                }
            }
        }

        return "NO";
    }

    /**
     * Checks if the cell at (row, col) is the center of a cross pattern.
     */
    private boolean isCrossCenter(int row, int col) {
        return grid[row][col] == TARGET_CHAR &&
               grid[row][col + 1] == TARGET_CHAR &&
               grid[row][col - 1] == TARGET_CHAR &&
               grid[row - 1][col] == TARGET_CHAR &&
               grid[row + 1][col] == TARGET_CHAR;
    }

    /**
     * Clears the cross pattern and its continuous arms extending from the center.
     */
    private void clearCrossPattern(int row, int col) {
        grid[row][col] = EMPTY_CHAR;

        // Directions: Right, Left, Down, Up
        int[][] directions = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

        for (int[] dir : directions) {
            int dr = dir[0];
            int dc = dir[1];
            int r = row + dr;
            int c = col + dc;

            // Traverse in the given direction until a boundary or non-target character is hit
            while (isValid(r, c) && grid[r][c] == TARGET_CHAR) {
                grid[r][c] = EMPTY_CHAR;
                r += dr;
                c += dc;
            }
        }
    }

    /**
     * Checks if there are any target characters left in the grid.
     */
    private boolean isGridEmpty() {
        for (int r = 0; r < height; r++) {
            for (int c = 0; c < width; c++) {
                if (grid[r][c] == TARGET_CHAR) {
                    return false;
                }
            }
        }
        return true;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < height && c >= 0 && c < width;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int h = scanner.nextInt();
        int w = scanner.nextInt();
        scanner.nextLine(); // Consume newline

        char[][] grid = new char[h][w];
        for (int i = 0; i < h; i++) {
            String line = scanner.nextLine();
            for (int j = 0; j < w; j++) {
                grid[i][j] = line.charAt(j);
            }
        }

        CrossPatternSolver solver = new CrossPatternSolver(h, w, grid);
        System.out.println(solver.solve());

        scanner.close();
    }
}

import java.util.Scanner;

/**
 * A program to determine if a grid of characters forms a single cross shape.
 * A cross shape is defined as a central '*' cell with four arms extending 
 * horizontally and vertically.
 */
public class Main {

    private static final char STAR = '*';
    private static final char EMPTY = '.';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int height = scanner.nextInt();
        int width = scanner.nextInt();

        // A cross pattern requires at least a 3x3 area
        if (height < 3 || width < 3) {
            System.out.println("NO");
            return;
        }

        char[][] grid = new char[height][width];
        for (int i = 0; i < height; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        if (isValidSingleCross(grid, height, width)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Validates if the grid contains exactly one connected cross shape.
     * 
     * @param grid The 2D character array.
     * @param h    Grid height.
     * @param w    Grid width.
     * @return true if the grid forms exactly one cross, false otherwise.
     */
    private static boolean isValidSingleCross(char[][] grid, int h, int w) {
        int centerRow = -1;
        int centerCol = -1;

        // 1. Search for the center of a potential cross
        // A center must have '*' neighbors at top, bottom, left, and right.
        outerLoop:
        for (int i = 1; i < h - 1; i++) {
            for (int j = 1; j < w - 1; j++) {
                if (isCrossCenter(grid, i, j)) {
                    centerRow = i;
                    centerCol = j;
                    break outerLoop;
                }
            }
        }

        // If no cross center was found, the pattern is invalid
        if (centerRow == -1) {
            return false;
        }

        // 2. Remove the identified cross and its continuous arms from the grid
        clearCrossArms(grid, centerRow, centerCol, h, w);

        // 3. If any '*' remains, it means there was more than one shape or extra stars
        return isGridEmptyOfStars(grid, h, w);
    }

    /**
     * Checks if the cell at (r, c) is the center of a '+' shape.
     */
    private static boolean isCrossCenter(char[][] grid, int r, int c) {
        return grid[r][c] == STAR &&
               grid[r - 1][c] == STAR &&
               grid[r + 1][c] == STAR &&
               grid[r][c - 1] == STAR &&
               grid[r][c + 1] == STAR;
    }

    /**
     * Clears the star cells that form the arms of the cross starting from the center.
     */
    private static void clearCrossArms(char[][] grid, int r, int c, int h, int w) {
        grid[r][c] = EMPTY;

        // Clear Vertical Arm (Up)
        int i = r - 1;
        while (i >= 0 && grid[i][c] == STAR) {
            grid[i][c] = EMPTY;
            i--;
        }

        // Clear Vertical Arm (Down)
        i = r + 1;
        while (i < h && grid[i][c] == STAR) {
            grid[i][c] = EMPTY;
            i++;
        }

        // Clear Horizontal Arm (Left)
        int j = c - 1;
        while (j >= 0 && grid[r][j] == STAR) {
            grid[r][j] = EMPTY;
            j--;
        }

        // Clear Horizontal Arm (Right)
        j = c + 1;
        while (j < w && grid[r][j] == STAR) {
            grid[r][j] = EMPTY;
            j++;
        }
    }

    /**
     * Iterates through the grid to ensure no '*' characters remain.
     */
    private static boolean isGridEmptyOfStars(char[][] grid, int h, int w) {
        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                if (grid[i][j] == STAR) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.io.*;
import java.util.*;

/**
 * Analyzes a grid of cells to find the optimal k x k window that maximizes 
 * the sum of "contained" rows and "contained" columns.
 * A row/column is "contained" if all its 'B' cells fall within the window's bounds.
 */
public class Solution {

    public static void main(String[] args) {
        try {
            FastReader reader = new FastReader(System.in);

            int gridSize = reader.nextInt();
            int windowSize = reader.nextInt();

            if (gridSize <= 0) {
                System.out.println(0);
                return;
            }

            boolean[][] grid = readGrid(reader, gridSize);

            GridAnalyzer analyzer = new GridAnalyzer(gridSize, windowSize, grid);
            long result = analyzer.solve();

            System.out.println(result);

        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Reads the n x n grid from the input.
     */
    private static boolean[][] readGrid(FastReader reader, int n) throws IOException {
        boolean[][] grid = new boolean[n][n];
        for (int i = 0; i < n; i++) {
            String line = reader.nextLine();
            for (int j = 0; j < Math.min(line.length(), n); j++) {
                if (line.charAt(j) == 'B') {
                    grid[i][j] = true;
                }
            }
        }
        return grid;
    }

    /**
     * Represents the boundaries of 'B' cells within a single row or column.
     */
    private static class Bounds {
        final int minIndex;
        final int maxIndex;
        final boolean isEmpty;

        Bounds(int minIndex, int maxIndex, boolean isEmpty) {
            this.minIndex = minIndex;
            this.maxIndex = maxIndex;
            this.isEmpty = isEmpty;
        }
    }

    /**
     * Encapsulates the mathematical logic for the grid analysis.
     */
    private static class GridAnalyzer {
        private final int n;
        private final int k;
        private final boolean[][] grid;

        GridAnalyzer(int n, int k, boolean[][] grid) {
            this.n = n;
            this.k = k;
            this.grid = grid;
        }

        public long solve() {
            Bounds[] rowBounds = computeRowBounds();
            Bounds[] colBounds = computeColBounds();

            int emptyRowsAndColsCount = countEmptyRowsAndCols(rowBounds, colBounds);
            int maxContainedInWindow = findMaxContainedInWindow(rowBounds, colBounds);

            return (long) emptyRowsAndColsCount + maxContainedInWindow;
        }

        private Bounds[] computeRowBounds() {
            Bounds[] bounds = new Bounds[n];
            for (int i = 0; i < n; i++) {
                int min = n;
                int max = -1;
                for (int j = 0; j < n; j++) {
                    if (grid[i][j]) {
                        if (j < min) min = j;
                        if (j > max) max = j;
                    }
                }
                bounds[i] = new Bounds(min, max, min == n);
            }
            return bounds;
        }

        private Bounds[] computeColBounds() {
            Bounds[] bounds = new Bounds[n];
            for (int j = 0; j < n; j++) {
                int min = n;
                int max = -1;
                for (int i = 0; i < n; i++) {
                    if (grid[i][j]) {
                        if (i < min) min = i;
                        if (i > max) max = i;
                    }
                }
                bounds[j] = new Bounds(min, max, min == n);
            }
            return bounds;
        }

        private int countEmptyRowsAndCols(Bounds[] rowBounds, Bounds[] colBounds) {
            int count = 0;
            for (Bounds b : rowBounds) if (b.isEmpty) count++;
            for (Bounds b : colBounds) if (b.isEmpty) count++;
            return count;
        }

        private int findMaxContainedInWindow(Bounds[] rowBounds, Bounds[] colBounds) {
            // rowSt[i][j] stores how many rows in vertical range [i, i+k-1] 
            // are horizontally contained within [j, j+k-1]
            int[][] rowSt = calculateContainedCounts(rowBounds, true);

            // colSt[i][j] stores how many cols in horizontal range [j, j+k-1] 
            // are vertically contained within [i, i+k-1]
            int[][] colSt = calculateContainedCounts(colBounds, false);

            int maxContained = 0;
            for (int i = 0; i <= n - k; i++) {
                for (int j = 0; j <= n - k; j++) {
                    maxContained = Math.max(maxContained, rowSt[i][j] + colSt[i][j]);
                }
            }
            return maxContained;
        }

        /**
         * Uses a sliding window approach to count how many rows or columns 
         * are fully contained within a k x k window.
         */
        private int[][] calculateContainedCounts(Bounds[] bounds, boolean isRowAnalysis) {
            int[][] counts = new int[n - k + 1][n - k + 1];

            if (isRowAnalysis) {
                // Analyze rows: window slides vertically (i) for every column offset (j)
                for (int j = 0; j <= n - k; j++) {
                    int currentCount = 0;
                    int colStart = j;
                    int colEnd = j + k - 1;

                    for (int i = 0; i < k; i++) {
                        if (isContained(bounds[i], colStart, colEnd)) currentCount++;
                    }
                    counts[0][j] = currentCount;

                    for (int i = 1; i <= n - k; i++) {
                        if (isContained(bounds[i - 1], colStart, colEnd)) currentCount--;
                        if (isContained(bounds[i + k - 1], colStart, colEnd)) currentCount++;
                        counts[i][j] = currentCount;
                    }
                }
            } else {
                // Analyze columns: window slides horizontally (j) for every row offset (i)
                for (int i = 0; i <= n - k; i++) {
                    int currentCount = 0;
                    int rowStart = i;
                    int rowEnd = i + k - 1;

                    for (int j = 0; j < k; j++) {
                        if (isContained(bounds[j], rowStart, rowEnd)) currentCount++;
                    }
                    counts[i][0] = currentCount;

                    for (int j = 1; j <= n - k; j++) {
                        if (isContained(bounds[j - 1], rowStart, rowEnd)) currentCount--;
                        if (isContained(bounds[j + k - 1], rowStart, rowEnd)) currentCount++;
                        counts[i][j] = currentCount;
                    }
                }
            }
            return counts;
        }

        private boolean isContained(Bounds b, int start, int end) {
            return !b.isEmpty && b.minIndex >= start && b.maxIndex <= end;
        }
    }

    /**
     * High-performance custom reader for competitive programming style input.
     */
    private static class FastReader {
        private final InputStream in;
        private final byte[] buffer = new byte[2048];
        private int index, total;

        FastReader(InputStream is) {
            this.in = is;
        }

        private int scan() throws IOException {
            if (index >= total) {
                index = 0;
                total = in.read(buffer);
                if (total <= 0) return -1;
            }
            return buffer[index++];
        }

        String nextLine() throws IOException {
            int c = scan();
            while (c != -1 && c <= 32) c = scan(); // Skip leading whitespace
            if (c == -1) return "";
            StringBuilder sb = new StringBuilder();
            while (c != -1 && c != 10 && c != 13) {
                sb.append((char) c);
                c = scan();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            int c = scan();
            while (c != -1 && c <= 32) c = scan();
            if (c == -1) return 0;
            boolean neg = (c == '-');
            if (neg || c == '+') c = scan();
            int val = 0;
            while (c >= '0' && c <= '9') {
                val = (val << 3) + (val << 1) + (c & 15);
                c = scan();
            }
            return neg ? -val : val;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the grid problem.
 * Finds the maximum number of white lines (rows or columns) 
 * that can be obtained by maximizing a k x k window.
 */
public class Main {
    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = in.nextInt();
            int k = in.nextInt();
            char[][] gridData = new char[n][n];
            for (int i = 0; i < n; i++) {
                gridData[i] = in.nextLine().toCharArray();
            }

            GridSolver solver = new GridSolver(n, k, gridData);
            out.println(solver.solve());
        } catch (Exception e) {
            // Handle or log exceptions
        } finally {
            out.close();
        }
    }

    /**
     * Encapsulates the grid and provides 2D prefix sum capabilities.
     */
    static class Grid {
        private final int n;
        private final char[][] data;
        private final int[][] prefixSum;

        public Grid(int n, char[][] data) {
            this.n = n;
            this.data = data;
            this.prefixSum = new int[n + 1][n + 1];
            precomputePrefixSums();
        }

        private void precomputePrefixSums() {
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    int val = (data[i - 1][j - 1] == 'B') ? 1 : 0;
                    prefixSum[i][j] = val + prefixSum[i - 1][j] + prefixSum[i][j - 1] - prefixSum[i - 1][j - 1];
                }
            }
        }

        public int getSum(int r1, int c1, int r2, int c2) {
            if (r1 > r2 || c1 > c2) return 0;
            // Convert to 1-based indexing for internal prefix sum logic
            return prefixSum[r2 + 1][c2 + 1] - prefixSum[r1][c2 + 1] - prefixSum[r2 + 1][c1] + prefixSum[r1][c1];
        }

        public int getColSum(int col, int r1, int r2) {
            return getSum(r1, col, r2, col);
        }

        public int getRowSum(int row, int c1, int c2) {
            return getSum(row, c1, row, c2);
        }

        public int getTotalColSum(int col) {
            return getColSum(col, 0, n - 1);
        }

        public int getTotalRowSum(int row) {
            return getRowSum(row, 0, n - 1);
        }

        public int getN() {
            return n;
        }
    }

    /**
     * Contains the core logic for calculating existing and additional white lines.
     */
    static class GridSolver {
        private final int n;
        private final int k;
        private final Grid grid;

        public GridSolver(int n, int k, char[][] data) {
            this.n = n;
            this.k = k;
            this.grid = new Grid(n, data);
        }

        public long solve() {
            int oldLines = countExistingWhiteLines();
            int maxAdditional = calculateMaxAdditionalWhiteLines();
            return (long) oldLines + maxAdditional;
        }

        private int countExistingWhiteLines() {
            int count = 0;
            for (int i = 0; i < n; i++) {
                if (grid.getTotalRowSum(i) == 0) count++;
            }
            for (int j = 0; j < n; j++) {
                if (grid.getTotalColSum(j) == 0) count++;
            }
            return count;
        }

        private int calculateMaxAdditionalWhiteLines() {
            int[] rowMin = new int[n];
            int[] rowMax = new int[n];
            boolean[] rowIsWhite = new boolean[n];

            for (int i = 0; i < n; i++) {
                int min = Integer.MAX_VALUE;
                int max = Integer.MIN_VALUE;
                int totalB = grid.getTotalRowSum(i);
                if (totalB == 0) {
                    rowIsWhite[i] = true;
                } else {
                    for (int j = 0; j < n; j++) {
                        if (grid.getSum(i, j, i, j) == 1) {
                            min = Math.min(min, j);
                            max = Math.max(max, j);
                        }
                    }
                    rowMin[i] = min;
                    rowMax[i] = max;
                    rowIsWhite[i] = false;
                }
            }

            int maxAdditional = 0;

            // Iterate through every possible row-window of height k
            for (int rStart = 0; rStart <= n - k; rStart++) {
                int rEnd = rStart + k - 1;

                // 1. Track Newly White Rows using a Difference Array
                // A row is "newly white" if it's not white and its B-span is within the column window
                int[] rowDiff = new int[n + 1];
                for (int i = rStart; i <= rEnd; i++) {
                    if (!rowIsWhite[i]) {
                        int span = rowMax[i] - rowMin[i] + 1;
                        if (span <= k) {
                            // Row is contained in col-window [cStart, cEnd] if:
                            // cStart <= rowMin AND rowMax <= cEnd
                            // With window size k: cStart >= rowMax - k + 1
                            // So: max(0, rowMax - k + 1) <= cStart <= rowMin
                            int L = Math.max(0, rowMax[i] - k + 1);
                            int R = rowMin[i];
                            if (L <= R) {
                                rowDiff[L]++;
                                if (R + 1 < n) rowDiff[R + 1]--;
                            }
                        }
                    }
                }

                int[] newlyWhiteRowsAtEndCol = new int[n];
                int currentRows = 0;
                for (int c = 0; c < n; c++) {
                    currentRows += rowDiff[c];
                    newlyWhiteRowsAtEndCol[c] = currentRows;
                }

                // 2. Track Newly White Columns 
                // A column is "newly white" if it wasn't white but all its B's are in the row window
                int[] colNewlyWhitePrefixSum = new int[n + 1];
                for (int j = 0; j < n; j++) {
                    boolean isColWhite = grid.getTotalColSum(j) == 0;
                    boolean isColNewlyWhite = !isColWhite && (grid.getColSum(j, rStart, rEnd) == grid.getTotalColSum(j));
                    colNewlyWhitePrefixSum[j + 1] = colNewlyWhitePrefixSum[j] + (isColNewlyWhite ? 1 : 0);
                }

                // 3. Sliding Window over columns to find max sum
                for (int cEnd = 0; cEnd < n; cEnd++) {
                    int cStart = Math.max(0, cEnd - k + 1);

                    // Count newly white columns in [cStart, cEnd]
                    int newlyWhiteCols = colNewlyWhitePrefixSum[cEnd + 1] - colNewlyWhitePrefixSum[cStart];

                    // Count newly white rows in current column window ending at cEnd
                    // The difference array logic already accounts for the width k requirement
                    int newlyWhiteRows = newlyWhiteRowsAtEndCol[cEnd];

                    maxAdditional = Math.max(maxAdditional, newlyWhiteRows + newlyWhiteCols);
                }
            }

            return maxAdditional;
        }
    }

    /**
     * High-performance input reader.
     */
    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public String nextLine() {
            String str = "";
            try {
                str = reader.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * This program calculates the maximum number of "contained" rows and columns 
 * within any k x k subgrid of an n x n grid, where a row or column is "contained" 
 * if all its 'B' characters fall within the subgrid's boundaries. 
 * It also accounts for rows and columns that contain no 'B' characters.
 */
public class GridAnalyzer {

    public static void main(String[] args) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String firstLine = reader.readLine();
            if (firstLine == null) return;

            StringTokenizer st = new StringTokenizer(firstLine);
            int n = Integer.parseInt(st.nextToken());
            int k = Integer.parseInt(st.nextToken());

            String[] grid = new String[n];
            for (int i = 0; i < n; i++) {
                grid[i] = reader.readLine();
            }

            System.out.println(calculateMaxContainedElements(grid, n, k));
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Calculates the result based on the grid configuration.
     * 
     * @param grid The n x n character grid.
     * @param n    The dimension of the grid.
     * @param k    The size of the subgrid window.
     * @return The maximum sum of contained rows, columns, and empty rows/cols.
     */
    private static int calculateMaxContainedElements(String[] grid, int n, int k) {
        if (n == 0 || k <= 0) return 0;

        // Bounding boxes for 'B's in each row and column
        int[] rowMinCol = new int[n];
        int[] rowMaxCol = new int[n];
        int[] colMinRow = new int[n];
        int[] colMaxRow = new int[n];
        boolean[] rowHasB = new boolean[n];
        boolean[] colHasB = new boolean[n];

        Arrays.fill(rowMinCol, Integer.MAX_VALUE);
        Arrays.fill(rowMaxCol, Integer.MIN_VALUE);
        Arrays.fill(colMinRow, Integer.MAX_VALUE);
        Arrays.fill(colMaxRow, Integer.MIN_VALUE);

        // Step 1: Pre-calculate bounding boxes and presence of 'B'
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i].charAt(j) == 'B') {
                    rowHasB[i] = true;
                    colHasB[j] = true;

                    rowMinCol[i] = Math.min(rowMinCol[i], j);
                    rowMaxCol[i] = Math.max(rowMaxCol[i], j);

                    colMinRow[j] = Math.min(colMinRow[j], i);
                    colMaxRow[j] = Math.max(colMaxRow[j], i);
                }
            }
        }

        // Step 2: Count rows and columns that contain no 'B's
        int emptyRowsCount = 0;
        for (int i = 0; i < n; i++) {
            if (!rowHasB[i]) emptyRowsCount++;
        }
        int emptyColsCount = 0;
        for (int j = 0; j < n; j++) {
            if (!colHasB[j]) emptyColsCount++;
        }

        // Step 3: numColContained[i][j] = number of columns c in window [j, j+k-1]
        // that are vertically contained within the row window [i, i+k-1].
        int[][] numColContained = new int[n][n];
        for (int i = 0; i <= n - k; i++) {
            int currentWindowCount = 0;
            // Initialize window for first k columns
            for (int c = 0; c < k; c++) {
                if (colHasB[c] && colMinRow[c] >= i && colMaxRow[c] <= i + k - 1) {
                    currentWindowCount++;
                }
            }
            numColContained[i][0] = currentWindowCount;

            // Slide the column window across the grid
            for (int j = 1; j <= n - k; j++) {
                if (colHasB[j - 1] && colMinRow[j - 1] >= i && colMaxRow[j - 1] <= i + k - 1) {
                    currentWindowCount--;
                }
                if (colHasB[j + k - 1] && colMinRow[j + k - 1] >= i && colMaxRow[j + k - 1] <= i + k - 1) {
                    currentWindowCount++;
                }
                numColContained[i][j] = currentWindowCount;
            }
        }

        // Step 4: numRowContained[i][j] = number of rows r in window [i, i+k-1]
        // that are horizontally contained within the column window [j, j+k-1].
        int[][] numRowContained = new int[n][n];
        for (int j = 0; j <= n - k; j++) {
            int currentWindowCount = 0;
            // Initialize window for first k rows
            for (int r = 0; r < k; r++) {
                if (rowHasB[r] && rowMinCol[r] >= j && rowMaxCol[r] <= j + k - 1) {
                    currentWindowCount++;
                }
            }
            numRowContained[0][j] = currentWindowCount;

            // Slide the row window across the grid
            for (int i = 1; i <= n - k; i++) {
                if (rowHasB[i - 1] && rowMinCol[i - 1] >= j && rowMaxCol[i - 1] <= j + k - 1) {
                    currentWindowCount--;
                }
                if (rowHasB[i + k - 1] && rowMinCol[i + k - 1] >= j && rowMaxCol[i + k - 1] <= j + k - 1) {
                    currentWindowCount++;
                }
                numRowContained[i][j] = currentWindowCount;
            }
        }

        // Step 5: Find the maximum sum of contained elements in any k x k subgrid
        int maxContained = 0;
        for (int i = 0; i <= n - k; i++) {
            for (int j = 0; j <= n - k; j++) {
                int totalInWindow = numColContained[i][j] + numRowContained[i][j];
                if (totalInWindow > maxContained) {
                    maxContained = totalInWindow;
                }
            }
        }

        return maxContained + emptyRowsCount + emptyColsCount;
    }
}

import java.io.*;
import java.util.*;

/**
 * GridCoverageSolver solves a grid-based coverage problem.
 * It calculates the maximum coverage provided by a k*k window, 
 * accounting for rows and columns that are fully contained within the window's spans.
 */
public class GridCoverageSolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        // The original logic processed a single test case
        int testCases = 1;
        for (int i = 0; i < testCases; i++) {
            GridSolver solver = new GridSolver();
            solver.solve(reader, writer);
        }

        writer.flush();
        writer.close();
    }

    /**
     * Core logic for solving the grid problem.
     */
    static class GridSolver {
        private int gridSize;
        private int windowSize;
        private char[][] grid;

        /**
         * Represents the boundaries (minimum and maximum index) of 'B' cells 
         * in a specific row or column.
         */
        private static class Range {
            int min = Integer.MAX_VALUE;
            int max = Integer.MIN_VALUE;

            void update(int index) {
                min = Math.min(min, index);
                max = Math.max(max, index);
            }

            boolean isEmpty() {
                return min == Integer.MAX_VALUE;
            }

            /**
             * Checks if the 'B' cells in this range are fully contained 
             * within the span [start, start + windowSize - 1].
             */
            boolean isContained(int start, int windowSize) {
                if (isEmpty()) return false;
                return min >= start && max < start + windowSize;
            }
        }

        public void solve(FastReader in, PrintWriter out) {
            this.gridSize = in.nextInt();
            this.windowSize = in.nextInt();
            this.grid = new char[gridSize][gridSize];

            for (int i = 0; i < gridSize; i++) {
                grid[i] = in.next().toCharArray();
            }

            Range[] rowRanges = new Range[gridSize];
            Range[] colRanges = new Range[gridSize];
            for (int i = 0; i < gridSize; i++) {
                rowRanges[i] = new Range();
                colRanges[i] = new Range();
            }

            int emptyRowsAndColsCount = 0;

            // 1. Determine 'B' boundaries for every row and count empty rows
            for (int i = 0; i < gridSize; i++) {
                for (int j = 0; j < gridSize; j++) {
                    if (grid[i][j] == 'B') {
                        rowRanges[i].update(j);
                    }
                }
                if (rowRanges[i].isEmpty()) {
                    emptyRowsAndColsCount++;
                }
            }

            // 2. Determine 'B' boundaries for every column and count empty columns
            for (int j = 0; j < gridSize; j++) {
                for (int i = 0; i < gridSize; i++) {
                    if (grid[i][j] == 'B') {
                        colRanges[j].update(i);
                    }
                }
                if (colRanges[j].isEmpty()) {
                    emptyRowsAndColsCount++;
                }
            }

            // 3. Calculate coverage arrays using a sliding window approach
            // rowCoverage[r][c] = number of rows in vertical span [r, r+k-1] 
            // that are horizontally contained in column span [c, c+k-1]
            int[][] rowCoverage = computeCoverage(gridSize, windowSize, rowRanges, true);

            // colCoverage[c][r] = number of columns in horizontal span [c, c+k-1] 
            // that are vertically contained in row span [r, r+k-1]
            int[][] colCoverage = computeCoverage(gridSize, windowSize, colRanges, false);

            // 4. Find the maximum coverage based on the original asymmetric logic
            int maxCoverage = 0;
            for (int i = 0; i < gridSize; i++) {
                for (int j = 0; j < gridSize; j++) {
                    // The original code calculates coverage using indices:
                    // ans = max(ansForCol[i][j] + ansForRow[i][j])
                    maxCoverage = Math.max(maxCoverage, colCoverage[i][j] + rowCoverage[i][j]);
                }
            }

            out.println(maxCoverage + emptyRowsAndColsCount);
        }

        /**
         * Computes coverage using a sliding window.
         * 
         * @param isRow If true, we slide a window vertically over rows for a fixed column window.
         *              If false, we slide a window horizontally over columns for a fixed row window.
         */
        private int[][] computeCoverage(int n, int k, Range[] ranges, boolean isRow) {
            int[][] coverage = new int[n][n];

            if (isRow) {
                for (int colStart = 0; colStart + k - 1 < n; colStart++) {
                    int currentCount = 0;
                    // Initialize the first vertical window [0, k-1]
                    for (int rowIdx = 0; rowIdx < k; rowIdx++) {
                        if (ranges[rowIdx].isContained(colStart, k)) {
                            currentCount++;
                        }
                    }
                    coverage[0][colStart] = currentCount;

                    // Slide the window down through the rows
                    for (int rowStart = 1; rowStart + k - 1 < n; rowStart++) {
                        if (ranges[rowStart - 1].isContained(colStart, k)) {
                            currentCount--;
                        }
                        if (ranges[rowStart + k - 1].isContained(colStart, k)) {
                            currentCount++;
                        }
                        coverage[rowStart][colStart] = currentCount;
                    }
                }
            } else {
                for (int rowStart = 0; rowStart + k - 1 < n; rowStart++) {
                    int currentCount = 0;
                    // Initialize the first horizontal window [0, k-1]
                    for (int colIdx = 0; colIdx < k; colIdx++) {
                        if (ranges[colIdx].isContained(rowStart, k)) {
                            currentCount++;
                        }
                    }
                    coverage[rowStart][0] = currentCount;

                    // Slide the window across the columns
                    for (int colStart = 1; colStart + k - 1 < n; colStart++) {
                        if (ranges[colStart - 1].isContained(rowStart, k)) {
                            currentCount--;
                        }
                        if (ranges[colStart + k - 1].isContained(rowStart, k)) {
                            currentCount++;
                        }
                        coverage[rowStart][colStart] = currentCount;
                    }
                }
            }
            return coverage;
        }
    }

    /**
     * High-performance reader for fast input processing.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * This program calculates the maximum number of empty rows and columns 
 * achievable by clearing a k x k subgrid in an n x n grid of 'B' (Black) and 'W' (White) cells.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader();

        int gridSize = reader.nextInt();
        int windowSize = reader.nextInt();

        if (gridSize <= 0 || windowSize <= 0) {
            System.out.println(0);
            return;
        }

        String[] grid = new String[gridSize];
        for (int i = 0; i < gridSize; i++) {
            grid[i] = reader.next();
        }

        GridOptimizer optimizer = new GridOptimizer(gridSize, windowSize, grid);
        System.out.println(optimizer.solve());
    }

    /**
     * Encapsulates the logic for processing the grid and finding the optimal window.
     */
    static class GridOptimizer {
        private final int n;
        private final int k;
        private final int[] rowMinCol;
        private final int[] rowMaxCol;
        private final int[] colMinRow;
        private final int[] colMaxRow;
        private final boolean[] rowHasBlack;
        private final boolean[] colHasBlack;
        private final int initialEmptyCount;

        public GridOptimizer(int n, int k, String[] grid) {
            this.n = n;
            this.k = k;
            this.rowMinCol = new int[n];
            this.rowMaxCol = new int[n];
            this.colMinRow = new int[n];
            this.colMaxRow = new int[n];
            this.rowHasBlack = new boolean[n];
            this.colHasBlack = new boolean[n];

            // Initialize bounds
            for (int i = 0; i < n; i++) {
                rowMinCol[i] = n;
                rowMaxCol[i] = -1;
                colMinRow[i] = n;
                colMaxRow[i] = -1;
            }

            // Parse grid to find bounding boxes of black cells for each row and column
            for (int r = 0; r < n; r++) {
                String rowStr = grid[r];
                for (int c = 0; c < n; c++) {
                    if (rowStr.charAt(c) == 'B') {
                        rowHasBlack[r] = true;
                        colHasBlack[c] = true;

                        rowMinCol[r] = Math.min(rowMinCol[r], c);
                        rowMaxCol[r] = Math.max(rowMaxCol[r], c);

                        colMinRow[c] = Math.min(colMinRow[c], r);
                        colMaxRow[c] = Math.max(colMaxRow[c], r);
                    }
                }
            }

            // Pre-calculate how many rows/cols are already empty
            int emptyRows = 0;
            int emptyCols = 0;
            for (int i = 0; i < n; i++) {
                if (!rowHasBlack[i]) emptyRows++;
                if (!colHasBlack[i]) emptyCols++;
            }
            this.initialEmptyCount = emptyRows + emptyCols;
        }

        /**
         * Solves the problem using an O(N^2) sliding window approach with difference arrays.
         * @return The maximum total number of empty rows and columns.
         */
        public int solve() {
            int maxNewlyCleared = 0;
            int maxPossibleStartIdx = n - k;

            // Iterate through every possible top-row index 'r' of the k x k window
            for (int r = 0; r <= maxPossibleStartIdx; r++) {
                // rowDiff and colDiff act as difference arrays to calculate coverage for window column index 'c'
                int[] rowDiff = new int[maxPossibleStartIdx + 2];
                int[] colDiff = new int[maxPossibleStartIdx + 2];

                // 1. Identify rows within the window [r, r + k - 1] that will become empty
                for (int i = r; i < r + k; i++) {
                    if (rowHasBlack[i]) {
                        // A row becomes empty if its entire black cell range is within [c, c + k - 1]
                        // c <= minCol AND maxCol <= c + k - 1  =>  c >= maxCol - k + 1
                        int leftC = Math.max(0, rowMaxCol[i] - k + 1);
                        int rightC = Math.min(maxPossibleStartIdx, rowMinCol[i]);

                        if (leftC <= rightC) {
                            rowDiff[leftC]++;
                            rowDiff[rightC + 1]--;
                        }
                    }
                }

                // 2. Identify columns within the window [c, c + k - 1] that will become empty
                for (int j = 0; j < n; j++) {
                    if (colHasBlack[j]) {
                        // A column becomes empty if its entire black cell range is within [r, r + k - 1]
                        if (colMinRow[j] >= r && colMaxRow[j] <= r + k - 1) {
                            // The column itself must also be within the window's horizontal range [c, c + k - 1]
                            // c <= j <= c + k - 1  =>  j - k + 1 <= c <= j
                            int leftC = Math.max(0, j - k + 1);
                            int rightC = Math.min(maxPossibleStartIdx, j);

                            if (leftC <= rightC) {
                                colDiff[leftC]++;
                                colDiff[rightC + 1]--;
                            }
                        }
                    }
                }

                // 3. Sweep the difference arrays to find the best 'c' for the current 'r'
                int currentRowsCleared = 0;
                int currentColsCleared = 0;
                for (int c = 0; c <= maxPossibleStartIdx; c++) {
                    currentRowsCleared += rowDiff[c];
                    currentColsCleared += colDiff[c];
                    maxNewlyCleared = Math.max(maxNewlyCleared, currentRowsCleared + currentColsCleared);
                }
            }

            return initialEmptyCount + maxNewlyCleared;
        }
    }

    /**
     * Utility class for fast I/O operations.
     */
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solution to find the maximum score achievable by placing a k x k window on a grid.
 * The score is defined by the number of empty rows/cols plus the number of non-empty 
 * rows/cols entirely contained within the window.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        FastWriter writer = new FastWriter(System.out);

        try {
            GridProblemSolver solver = new GridProblemSolver(reader);
            solver.solve(writer);
        } catch (Exception e) {
            // In a production environment, use a proper logging framework
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    /**
     * Logic for solving the specific grid problem.
     */
    static class GridProblemSolver {
        private final FastReader reader;
        private int gridSize;
        private int windowSize;
        private char[][] grid;

        // Bounds of 'B' characters for each row and column (1-based indexing)
        private int[] rowMinColIdx;
        private int[] rowMaxColIdx;
        private int[] colMinRowIdx;
        private int[] colMaxRowIdx;

        public GridProblemSolver(FastReader reader) {
            this.reader = reader;
        }

        public void solve(FastWriter writer) throws IOException {
            this.gridSize = reader.nextInt();
            this.windowSize = reader.nextInt();
            this.grid = new char[gridSize][gridSize];

            initializeBounds();

            int emptyRowsAndColsCount = calculateEmptyRowsAndCols();
            int[][] extraMatches = calculateExtraMatches();

            int maxExtra = 0;
            for (int i = 0; i < gridSize; i++) {
                for (int j = 0; j < gridSize; j++) {
                    maxExtra = Math.max(maxExtra, extraMatches[i][j]);
                }
            }

            writer.println(emptyRowsAndColsCount + maxExtra);
        }

        private void initializeBounds() throws IOException {
            grid = new char[gridSize][gridSize];
            rowMinColIdx = new int[gridSize];
            rowMaxColIdx = new int[gridSize];
            colMinRowIdx = new int[gridSize];
            colMaxRowIdx = new int[gridSize];

            Arrays.fill(rowMinColIdx, gridSize + 1);
            Arrays.fill(colMinRowIdx, gridSize + 1);
            Arrays.fill(rowMaxColIdx, 0);
            Arrays.fill(colMaxRowIdx, 0);

            for (int i = 0; i < gridSize; i++) {
                grid[i] = reader.readCharArray(gridSize);
                for (int j = 0; j < gridSize; j++) {
                    if (grid[i][j] == 'B') {
                        // 1-based indexing for bounds logic consistency
                        int colPos = j + 1;
                        int rowPos = i + 1;

                        rowMaxColIdx[i] = Math.max(rowMaxColIdx[i], colPos);
                        rowMinColIdx[i] = Math.min(rowMinColIdx[i], colPos);

                        colMaxRowIdx[j] = Math.max(colMaxRowIdx[j], rowPos);
                        colMinRowIdx[j] = Math.min(colMinRowIdx[j], rowPos);
                    }
                }
            }
        }

        private int calculateEmptyRowsAndCols() {
            int count = 0;
            for (int i = 0; i < gridSize; i++) {
                if (rowMaxColIdx[i] == 0) count++;
                if (colMaxRowIdx[i] == 0) count++;
            }
            return count;
        }

        private int[][] calculateExtraMatches() {
            int[][] extraMatches = new int[gridSize][gridSize];

            // 1. Calculate contribution of rows to the window
            // For every column window, how many rows (within the row-window) fit inside it?
            for (int colStart = 0; colStart <= gridSize - windowSize; colStart++) {
                int colL = colStart + 1;
                int colR = colStart + windowSize;

                int satisfiedRowsInWindow = 0;
                // Initial row window [0, windowSize - 1]
                for (int i = 0; i < windowSize; i++) {
                    if (isRowContainedInColRange(i, colL, colR)) {
                        satisfiedRowsInWindow++;
                    }
                }
                extraMatches[0][colStart] += satisfiedRowsInWindow;

                // Slide the row window
                for (int i = 1; i <= gridSize - windowSize; i++) {
                    if (isRowContainedInColRange(i + windowSize - 1, colL, colR)) {
                        satisfiedRowsInWindow++;
                    }
                    if (isRowContainedInColRange(i - 1, colL, colR)) {
                        satisfiedRowsInWindow--;
                    }
                    extraMatches[i][colStart] += satisfiedRowsInWindow;
                }
            }

            // 2. Calculate contribution of columns to the window
            // For every row window, how many columns (within the col-window) fit inside it?
            for (int rowStart = 0; rowStart <= gridSize - windowSize; rowStart++) {
                int rowL = rowStart + 1;
                int rowR = rowStart + windowSize;

                int satisfiedColsInWindow = 0;
                // Initial column window [0, windowSize - 1]
                for (int j = 0; j < windowSize; j++) {
                    if (isColContainedInRowRange(j, rowL, rowR)) {
                        satisfiedColsInWindow++;
                    }
                }
                extraMatches[rowStart][0] += satisfiedColsInWindow;

                // Slide the column window
                for (int j = 1; j <= gridSize - windowSize; j++) {
                    if (isColContainedInRowRange(j + windowSize - 1, rowL, rowR)) {
                        satisfiedColsInWindow++;
                    }
                    if (isColContainedInRowRange(j - 1, rowL, rowR)) {
                        satisfiedColsInWindow--;
                    }
                    extraMatches[rowStart][j] += satisfiedColsInWindow;
                }
            }

            return extraMatches;
        }

        private boolean isRowContainedInColRange(int rowIndex, int colL, int colR) {
            return rowMaxColIdx[rowIndex] != 0 && 
                   rowMaxColIdx[rowIndex] <= colR && 
                   rowMinColIdx[rowIndex] >= colL;
        }

        private boolean isColContainedInRowRange(int colIndex, int rowL, int rowR) {
            return colMaxRowIdx[colIndex] != 0 && 
                   colMaxRowIdx[colIndex] <= rowR && 
                   colMinRowIdx[colIndex] >= rowL;
        }
    }

    /**
     * Fast I/O reader for performance.
     */
    static class FastReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int curChar;
        private int numChars;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() throws IOException {
            if (numChars == -1) throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                numChars = stream.read(buffer);
                if (numChars <= 0) return -1;
            }
            return buffer[curChar++];
        }

        public int nextInt() throws IOException {
            int c = read();
            while (isWhitespace(c)) c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res = res * 10 + (c - '0');
                c = read();
            } while (!isWhitespace(c));
            return res * sgn;
        }

        public char[] readCharArray(int size) throws IOException {
            char[] array = new char[size];
            for (int i = 0; i < size; i++) {
                array[i] = (char) readCharacter();
            }
            return array;
        }

        public char readCharacter() throws IOException {
            int c = read();
            while (isWhitespace(c)) c = read();
            return (char) c;
        }

        private boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }

    /**
     * Fast I/O writer for performance.
     */
    static class FastWriter {
        private final PrintWriter writer;

        public FastWriter(OutputStream outputStream) {
            this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public void println(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                writer.print(objects[i]);
                if (i < objects.length - 1) writer.print(' ');
            }
            writer.println();
        }

        public void close() {
            writer.close();
        }
    }
}

