        PatternAnalyzer analyzer = new PatternAnalyzer();

        // The original code used a loop for 't' test cases.
        // For this refactor, we assume t=1 as per the original logic.
        int testCases = 1;
        for (int i = 0; i < testCases; i++) {
            analyzer.solve(in, out);
        }

        out.flush();
        out.close();
    }

    /**
     * Analyzes a grid of characters to find specific patterns of 'B' characters.
     */
    static class PatternAnalyzer {
        private int gridSize;
        private int windowSize;
        private int[][] bCountPrefixSum;

        /**
         * Performs the core logic of the problem.
         * 
         * @param in  The fast reader for input.
         * @param out The print writer for output.
         */
        public void solve(FastReader in, PrintWriter out) {
            this.gridSize = in.nextInt();
            this.windowSize = in.nextInt();

            char[][] grid = new char[gridSize][];
            for (int i = 0; i < gridSize; i++) {
                grid[i] = in.next().toCharArray();
            }

            computePrefixSums(grid);

            int emptyLinesCount = countEmptyRowsAndCols(grid);
            int maxPatternScore = calculateMaxPatternScore(grid);

            out.println(emptyLinesCount + maxPatternScore);
        }

        /**
         * Computes a 2D prefix sum array for the character 'B'.
         */
        private void computePrefixSums(char[][] grid) {
            bCountPrefixSum = new int[gridSize + 1][gridSize + 1];
            for (int i = 1; i <= gridSize; i++) {
                for (int j = 1; j <= gridSize; j++) {
                    int isB = (grid[i - 1][j - 1] == 'B' ? 1 : 0);
                    bCountPrefixSum[i][j] = bCountPrefixSum[i - 1][j] + 
                                            bCountPrefixSum[i][j - 1] - 
                                            bCountPrefixSum[i - 1][j - 1] + isB;
                }
            }
        }

        /**
         * Calculates the number of rows and columns that contain zero 'B' characters.
         */
        private int countEmptyRowsAndCols(char[][] grid) {
            int count = 0;
            for (int i = 1; i <= gridSize; i++) {
                // Check row i
                if (getRectangularSum(i, 1, i, gridSize) == 0) {
                    count++;
                }
                // Check column i
                if (getRectangularSum(1, i, gridSize, i) == 0) {
                    count++;
                }
            }
            return count;
        }

        /**
         * Finds the maximum score based on patterns where a window of size k 
         * contains all 'B's of its respective row or column.
         */
        private int calculateMaxPatternScore(char[][] grid) {
            int[][] rowPatterns = new int[gridSize + 1][gridSize + 1];
            int[][] colPatterns = new int[gridSize + 1][gridSize + 1];

            for (int i = 1; i <= gridSize; i++) {
                for (int j = 1; j <= gridSize; j++) {
                    // Check if a horizontal segment of length k starting at (i, j) contains all 'B's in row i
                    int rowTotalB = getRectangularSum(i, 1, i, gridSize);
                    if (rowTotalB != 0 && getRectangularSum(i, j, i, j + windowSize - 1) == rowTotalB) {
                        rowPatterns[i][j] = 1;
                    }

                    // Check if a vertical segment of length k starting at (i, j) contains all 'B's in col j
                    int colTotalB = getRectangularSum(1, j, gridSize, j);
                    if (colTotalB != 0 && getRectangularSum(i, j, i + windowSize - 1, j) == colTotalB) {
                        colPatterns[i][j] = 1;
                    }
                }
            }

            // Transform patterns into 1D prefix sums for quick range querying
            // rowPatterns becomes a vertical prefix sum per column
            // colPatterns becomes a horizontal prefix sum per row
            for (int i = 1; i <= gridSize; i++) {
                for (int j = 1; j <= gridSize; j++) {
                    rowPatterns[i][j] += rowPatterns[i - 1][j];
                    colPatterns[i][j] += colPatterns[i][j - 1];
                }
            }

            int maxScore = 0;
            for (int i = 1; i <= gridSize; i++) {
                for (int j = 1; j <= gridSize; j++) {
                    // Query the vertical range of row-patterns and horizontal range of col-patterns
                    int verticalSum = rowPatterns[Math.min(gridSize, i + windowSize - 1)][j] - rowPatterns[i - 1][j];
                    int horizontalSum = colPatterns[i][Math.min(gridSize, j + windowSize - 1)] - colPatterns[i][j - 1];
                    maxScore = Math.max(maxScore, verticalSum + horizontalSum);
                }
            }
            return maxScore;
        }

        /**
         * Returns the number of 'B' characters in the specified rectangle.
         */
        private int getRectangularSum(int row1, int col1, int row2, int col2) {
            // Clamp boundaries to prevent IndexOutOfBounds
            int r2 = Math.min(row2, gridSize);
            int c2 = Math.min(col2, gridSize);
            int r1 = Math.max(1, row1);
            int c1 = Math.max(1, col1);

            if (r1 > r2 || c1 > c2) return 0;

            return bCountPrefixSum[r2][c2] - 
                   bCountPrefixSum[r1 - 1][c2] - 
                   bCountPrefixSum[r2][c1 - 1] + 
                   bCountPrefixSum[r1 - 1][c1 - 1];
        }
    }

    /**
     * High-performance reader for fast I/O operations.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Problem: Maximize the number of White ('W') cells in an N x N grid 
 * by choosing a K x K subgrid and replacing all its cells with 'W'.
 * 
 * Approach: 
 * 1. Count the initial number of 'W' cells.
 * 2. Use 2D Prefix Sums to efficiently calculate the number of Black ('B') 
 *    cells in any K x K subgrid.
 * 3. Find the K x K subgrid that contains the maximum number of 'B' cells.
 * 4. Total 'W' cells = (Initial 'W' cells) + (Max 'B' cells found in a K x K area).
 */
public class BeautifulGridSolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        BeautifulGridSolver solver = new BeautifulGridSolver();
        solver.solve(reader);
    }

    /**
     * Core logic to solve the grid problem.
     * 
     * @param reader The utility for fast input reading.
     */
    public void solve(FastReader reader) {
        int n = reader.nextInt();
        int k = reader.nextInt();

        if (n <= 0) {
            System.out.println(0);
            return;
        }

        // pref[i][j] stores the count of 'B' cells in the rectangle from (0,0) to (i-1, j-1)
        int[][] prefixSum = new int[n + 1][n + 1];
        int initialWhiteCount = 0;

        for (int i = 0; i < n; i++) {
            String row = reader.next();
            for (int j = 0; j < n; j++) {
                boolean isBlack = (row.charAt(j) == 'B');

                if (!isBlack) {
                    initialWhiteCount++;
                }

                // Build the 2D prefix sum array
                int val = isBlack ? 1 : 0;
                prefixSum[i + 1][j + 1] = val 
                                        + prefixSum[i][j + 1] 
                                        + prefixSum[i + 1][j] 
                                        - prefixSum[i][j];
            }
        }

        int maxBlackInSubgrid = 0;

        // Iterate through all possible top-left corners of a K x K subgrid
        // We use the prefix sum to get the sum in O(1)
        for (int i = k; i <= n; i++) {
            for (int j = k; j <= n; j++) {
                int currentBlackCount = prefixSum[i][j] 
                                      - prefixSum[i - k][j] 
                                      - prefixSum[i][j - k] 
                                      + prefixSum[i - k][j - k];

                if (currentBlackCount > maxBlackInSubgrid) {
                    maxBlackInSubgrid = currentBlackCount;
                }
            }
        }

        // The maximum number of white cells is the initial white cells 
        // plus the black cells we converted to white in the chosen K x K subgrid.
        System.out.println(initialWhiteCount + maxBlackInSubgrid);
    }

    /**
     * Fast I/O utility class for efficient reading of large inputs.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the grid coverage problem.
 * The goal is to find the maximum number of rows and columns that can be covered
 * by a single KxK square, given certain constraints on where 'B' characters are located.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            GridProblemSolver solver = new GridProblemSolver(reader);
            solver.solve(writer);
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    /**
     * Core logic for solving the grid constraint problem.
     */
    static class GridProblemSolver {
        private final FastReader reader;

        public GridProblemSolver(FastReader reader) {
            this.reader = reader;
        }

        public void solve(PrintWriter out) throws IOException {
            int n = reader.nextInt();
            int k = reader.nextInt();
            char[][] grid = new char[n][n];

            for (int i = 0; i < n; i++) {
                grid[i] = reader.next().toCharArray();
            }

            Bounds rowBounds = calculateBounds(grid, n, true);
            Bounds colBounds = calculateBounds(grid, n, false);

            int freeCount = 0;
            // A 2D difference array (represented as 1D difference arrays per row) 
            // to track how many constraints cover a specific top-left corner (r, c).
            int[][] coverageMap = new int[n][n + 1];

            // Process Row Constraints
            for (int i = 0; i < n; i++) {
                if (rowBounds.minIdx[i] == -1) {
                    freeCount++;
                } else if (rowBounds.maxIdx[i] - rowBounds.minIdx[i] < k) {
                    // Any KxK square starting at row r and col c covers this row's 'B's if:
                    // r is in [i - k + 1, i] AND c is in [maxIdx - k + 1, minIdx]
                    int rStart = Math.max(0, i - k + 1);
                    int rEnd = i;
                    int cStart = Math.max(0, rowBounds.maxIdx[i] - k + 1);
                    int cEnd = rowBounds.minIdx[i];

                    applyRowRangeUpdate(coverageMap, rStart, rEnd, cStart, cEnd, n);
                }
            }

            // Process Column Constraints
            for (int i = 0; i < n; i++) {
                if (colBounds.minIdx[i] == -1) {
                    freeCount++;
                } else if (colBounds.maxIdx[i] - colBounds.minIdx[i] < k) {
                    // Any KxK square starting at row r and col c covers this col's 'B's if:
                    // c is in [i - k + 1, i] AND r is in [maxIdx - k + 1, minIdx]
                    int cStart = Math.max(0, i - k + 1);
                    int cEnd = i;
                    int rStart = Math.max(0, colBounds.maxIdx[i] - k + 1);
                    int rEnd = colBounds.minIdx[i];

                    applyRowRangeUpdate(coverageMap, rStart, rEnd, cStart, cEnd, n);
                }
            }

            out.println(freeCount + calculateMaxOverlap(coverageMap, n));
        }

        /**
         * Updates the coverage map using a 1D difference array approach for each row.
         */
        private void applyRowRangeUpdate(int[][] map, int rStart, int rEnd, int cStart, int cEnd, int n) {
            for (int r = rStart; r <= rEnd; r++) {
                if (r >= 0 && r < n) {
                    map[r][cStart]++;
                    if (cEnd + 1 < n) {
                        map[r][cEnd + 1]--;
                    }
                }
            }
        }

        /**
         * Calculates the maximum value in the coverage map after performing prefix sums.
         */
        private int calculateMaxOverlap(int[][] map, int n) {
            int maxVal = 0;
            for (int i = 0; i < n; i++) {
                int currentLineSum = 0;
                for (int j = 0; j < n; j++) {
                    currentLineSum += map[i][j];
                    if (currentLineSum > maxVal) {
                        maxVal = currentLineSum;
                    }
                }
            }
            return maxVal;
        }

        /**
         * Finds the min and max index of 'B' characters for rows or columns.
         */
        private Bounds calculateBounds(char[][] grid, int n, boolean isRow) {
            int[] minIndices = new int[n];
            int[] maxIndices = new int[n];
            Arrays.fill(minIndices, -1);
            Arrays.fill(maxIndices, -1);

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    char target = isRow ? grid[i][j] : grid[j][i];
                    if (target == 'B') {
                        int pos = isRow ? j : i;
                        if (minIndices[i] == -1 || pos < minIndices[i]) minIndices[i] = pos;
                        if (maxIndices[i] == -1 || pos > maxIndices[i]) maxIndices[i] = pos;
                    }
                }
            }
            return new Bounds(minIndices, maxIndices);
        }

        private static class Bounds {
            final int[] minIdx;
            final int[] maxIdx;

            Bounds(int[] minIdx, int[] maxIdx) {
                this.minIdx = minIdx;
                this.maxIdx = maxIdx;
            }
        }
    }

    /**
     * High-performance input reader.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Solves the problem of maximizing the number of complete (all black) rows and columns
 * by placing a K x K square of black cells on an N x N grid.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int n = reader.nextInt();
            int k = reader.nextInt();
            char[][] grid = new char[n][n];

            for (int i = 0; i < n; i++) {
                grid[i] = reader.next().toCharArray();
            }

            GridSolver solver = new GridSolver(n, k, grid);
            writer.println(solver.solve());
        } catch (Exception e) {
            // In a production environment, use a logger.
        } finally {
            writer.close();
        }
    }

    static class GridSolver {
        private final int n;
        private final int k;
        private final char[][] grid;

        public GridSolver(int n, int k, char[][] grid) {
            this.n = n;
            this.k = k;
            this.grid = grid;
        }

        /**
         * Orchestrates the calculation of the maximum possible complete lines.
         */
        public long solve() {
            int[] rowBlackCounts = new int[n];
            int[] colBlackCounts = new int[n];

            // 1. Count black cells in each row and column
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (grid[i][j] == 'B') {
                        rowBlackCounts[i]++;
                        colBlackCounts[j]++;
                    }
                }
            }

            // 2. Count lines that are already "complete" (contain zero black cells)
            int alreadyCompleteLines = 0;
            for (int i = 0; i < n; i++) {
                if (rowBlackCounts[i] == 0) alreadyCompleteLines++;
                if (colBlackCounts[i] == 0) alreadyCompleteLines++;
            }

            // 3. Determine if a sliding window of size K in a row/column covers all its original black cells
            boolean[][] rowCoverage = calculateCoverage(rowBlackCounts, true);
            boolean[][] colCoverage = calculateCoverage(colBlackCounts, false);

            // 4. Calculate the "benefit" (how many rows/cols are completed) for any KxK square top-left (r, c)
            // rowBenefit[r][c]: number of rows in range [r, r+k-1] that are completed by window starting at column c
            int[][] rowBenefit = calculateVerticalBenefit(rowCoverage);
            // colBenefit[r][c]: number of columns in range [c, c+k-1] that are completed by window starting at row r
            int[][] colBenefit = calculateHorizontalBenefit(colCoverage);

            // 5. Find the maximum benefit
            long maxExtraLines = 0;
            for (int r = 0; r <= n - k; r++) {
                for (int c = 0; c <= n - k; c++) {
                    maxExtraLines = Math.max(maxExtraLines, (long) rowBenefit[r][c] + colBenefit[r][c]);
                }
            }

            return maxExtraLines + alreadyCompleteLines;
        }

        /**
         * Calculates whether a sliding window of size K covers all existing black cells in a line.
         * @param blackCounts Precomputed counts of 'B' in each line.
         * @param isRow True if calculating for rows, false for columns.
         * @return A 2D boolean array where [lineIndex][windowStartIndex] is true if coverage is complete.
         */
        private boolean[][] calculateCoverage(int[] blackCounts, boolean isRow) {
            boolean[][] coverage = new boolean[n][n];
            for (int i = 0; i < n; i++) {
                if (blackCounts[i] == 0) continue;

                int currentWindowBlacks = 0;
                // Initial window of size K
                for (int j = 0; j < k; j++) {
                    if (isRow ? grid[i][j] == 'B' : grid[j][i] == 'B') {
                        currentWindowBlacks++;
                    }
                }

                if (currentWindowBlacks == blackCounts[i]) {
                    coverage[i][0] = true;
                }

                // Sliding window
                for (int j = 1; j <= n - k; j++) {
                    // Remove element exiting window
                    if (isRow ? grid[i][j - 1] == 'B' : grid[j - 1][i] == 'B') {
                        currentWindowBlacks--;
                    }
                    // Add element entering window
                    if (isRow ? grid[i][j + k - 1] == 'B' : grid[j + k - 1][i] == 'B') {
                        currentWindowBlacks++;
                    }

                    if (currentWindowBlacks == blackCounts[i]) {
                        coverage[i][j] = true;
                    }
                }
            }
            return coverage;
        }

        /**
         * Calculates how many 'true' values exist in a vertical segment of length K.
         */
        private int[][] calculateVerticalBenefit(boolean[][] coverage) {
            int[][] benefit = new int[n][n];
            for (int j = 0; j <= n - k; j++) {
                int currentSum = 0;
                for (int i = 0; i < k; i++) {
                    if (coverage[i][j]) currentSum++;
                }
                benefit[0][j] = currentSum;
                for (int i = 1; i <= n - k; i++) {
                    if (coverage[i - 1][j]) currentSum--;
                    if (coverage[i + k - 1][j]) currentSum++;
                    benefit[i][j] = currentSum;
                }
            }
            return benefit;
        }

        /**
         * Calculates how many 'true' values exist in a horizontal segment of length K.
         */
        private int[][] calculateHorizontalBenefit(boolean[][] coverage) {
            int[][] benefit = new int[n][n];
            for (int i = 0; i < n; i++) {
                int currentSum = 0;
                for (int j = 0; j < k; j++) {
                    if (coverage[i][j]) currentSum++;
                }
                benefit[i][0] = currentSum;
                for (int j = 1; j <= n - k; j++) {
                    if (coverage[i][j - 1]) currentSum--;
                    if (coverage[i][j + k - 1]) currentSum++;
                    benefit[i][j] = currentSum;
                }
            }
            return benefit;
        }
    }

    /**
     * Utility class for fast I/O operations.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * GridAnalyzer solves the problem of finding a KxK subgrid that maximizes 
 * the number of "covered" rows and columns. A row/column is covered if 
 * it contains no 'B' characters outside the chosen KxK window.
 */
public class GridAnalyzer {

    private final int gridSize;
    private final int windowSize;
    private final int[] rowMin;
    private final int[] rowMax;
    private final int[] colMin;
    private final int[] colMax;

    private static final int INF = Integer.MAX_VALUE;

    public GridAnalyzer(int gridSize, int windowSize, String[] grid) {
        this.gridSize = gridSize;
        this.windowSize = windowSize;
        this.rowMin = new int[gridSize];
        this.rowMax = new int[gridSize];
        this.colMin = new int[gridSize];
        this.colMax = new int[gridSize];

        initializeBounds();
        parseGrid(grid);
    }

    private void initializeBounds() {
        for (int i = 0; i < gridSize; i++) {
            rowMin[i] = colMin[i] = gridSize;
            rowMax[i] = colMax[i] = -1;
        }
    }

    private void parseGrid(String[] grid) {
        for (int r = 0; r < gridSize; r++) {
            String line = grid[r];
            for (int c = 0; c < gridSize; c++) {
                if (line.charAt(c) == 'B') {
                    rowMin[r] = Math.min(rowMin[r], c);
                    rowMax[r] = Math.max(rowMax[r], c);
                    colMin[c] = Math.min(colMin[c], r);
                    colMax[c] = Math.max(colMax[c], r);
                }
            }
        }
    }

    /**
     * Calculates how many items (rows or columns) within a sliding window of 
     * size K are fully contained within the orthogonal window of size K.
     * 
     * @param mins The minimum boundary of each item.
     * @param maxs The maximum boundary of each item.
     * @return A 2D array where result[i][j] is the count for window starting at (i, j).
     */
    private int[][] getContainedCounts(int[] mins, int[] maxs) {
        int numWindows = gridSize - windowSize + 1;
        int[][] counts = new int[numWindows][numWindows];

        for (int orthogonalStart = 0; orthogonalStart < numWindows; orthogonalStart++) {
            int orthogonalEnd = orthogonalStart + windowSize - 1;

            // Determine which items are contained within the orthogonal window
            boolean[] isContained = new boolean[gridSize];
            for (int i = 0; i < gridSize; i++) {
                if (mins[i] < gridSize && mins[i] >= orthogonalStart && maxs[i] <= orthogonalEnd) {
                    isContained[i] = true;
                }
            }

            // Sliding window over the items themselves
            int currentCount = 0;
            for (int i = 0; i < windowSize; i++) {
                if (isContained[i]) currentCount++;
            }
            counts[0][orthogonalStart] = currentCount;

            for (int i = 1; i < numWindows; i++) {
                if (isContained[i - 1]) currentCount--;
                if (isContained[i + windowSize - 1]) currentCount++;
                counts[i][orthogonalStart] = currentCount;
            }
        }
        return counts;
    }

    public int solve() {
        // Edge case: If window is the whole grid, all rows and columns are covered.
        if (gridSize == windowSize) {
            return 2 * gridSize;
        }

        int emptyRows = 0;
        int emptyCols = 0;
        for (int i = 0; i < gridSize; i++) {
            if (rowMin[i] == gridSize) emptyRows++;
            if (colMin[i] == gridSize) emptyCols++;
        }

        int[][] containedRows = getContainedCounts(rowMin, rowMax);
        int[][] containedCols = getContainedCounts(colMin, colMax);

        int maxCovered = 0;
        int numWindows = gridSize - windowSize + 1;
        for (int r = 0; r < numWindows; r++) {
            for (int c = 0; c < numWindows; c++) {
                // Total covered = (All empty rows + Non-empty rows in window) 
                //                + (All empty cols + Non-empty cols in window)
                int currentCovered = emptyRows + emptyCols + containedRows[r][c] + containedCols[r][c];
                maxCovered = Math.max(maxCovered, currentCovered);
            }
        }

        return maxCovered;
    }

    public static void main(String[] args) throws IOException {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = reader.nextInt();
        int k = reader.nextInt();
        String[] grid = new String[n];
        for (int i = 0; i < n; i++) {
            grid[i] = reader.next();
        }

        GridAnalyzer analyzer = new GridAnalyzer(n, k, grid);
        out.println(analyzer.solve());
        out.close();
    }

    /**
     * Efficient input reader for large datasets.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * GridPatternAnalyzer calculates the maximum number of "complete" rows and columns
 * within any k x k subgrid of a given n x n grid. A row or column is "complete" 
 * if all 'B' characters present in that row/column are contained within the k x k window.
 */
public class GridPatternAnalyzer {

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int n = reader.nextInt();
            int k = reader.nextInt();
            reader.nextLine(); // Consume the remaining newline character

            char[][] grid = new char[n][n];
            for (int i = 0; i < n; i++) {
                String line = reader.nextLine();
                if (line != null) {
                    grid[i] = line.toCharArray();
                }
            }

            GridSolver solver = new GridSolver(n, k, grid);
            long result = solver.solve();
            writer.println(result);

        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    static class GridSolver {
        private final int n;
        private final int k;
        private final char[][] grid;

        public GridSolver(int n, int k, char[][] grid) {
            this.n = n;
            this.k = k;
            this.grid = grid;
        }

        public long solve() {
            int[][] colPrefixSums = computeColumnPrefixSums();
            int[][] rowPrefixSums = computeRowPrefixSums();

            long emptyRowsAndColsCount = countEmptyRowsAndCols(colPrefixSums, rowPrefixSums);

            // rowMatchPrefixSums[i][j] = prefix sum of columns in row i that 
            // satisfy the vertical completeness condition ending at row i.
            int[][] rowMatchPrefixSums = computeRowMatchPrefixSums(colPrefixSums);

            // colMatchPrefixSums[i][j] = prefix sum of rows in column j that 
            // satisfy the horizontal completeness condition ending at column j.
            int[][] colMatchPrefixSums = computeColMatchPrefixSums(rowPrefixSums);

            return findMaxPatternCount(emptyRowsAndColsCount, rowMatchPrefixSums, colMatchPrefixSums);
        }

        private int[][] computeColumnPrefixSums() {
            int[][] dpv = new int[n][n];
            for (int j = 0; j < n; j++) {
                for (int i = 0; i < n; i++) {
                    if (grid[i][j] == 'B') {
                        dpv[i][j] = (i > 0 ? dpv[i - 1][j] : 0) + 1;
                    } else {
                        dpv[i][j] = (i > 0 ? dpv[i - 1][j] : 0);
                    }
                }
            }
            return dpv;
        }

        private int[][] computeRowPrefixSums() {
            int[][] dph = new int[n][n];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (grid[i][j] == 'B') {
                        dph[i][j] = (j > 0 ? dph[i][j - 1] : 0) + 1;
                    } else {
                        dph[i][j] = (j > 0 ? dph[i][j - 1] : 0);
                    }
                }
            }
            return dph;
        }

        private long countEmptyRowsAndCols(int[][] colPrefixSums, int[][] rowPrefixSums) {
            long count = 0;
            // Count columns with no 'B's
            for (int j = 0; j < n; j++) {
                if (colPrefixSums[n - 1][j] == 0) count++;
            }
            // Count rows with no 'B's
            for (int i = 0; i < n; i++) {
                if (rowPrefixSums[i][n - 1] == 0) count++;
            }
            return count;
        }

        private int[][] computeRowMatchPrefixSums(int[][] colPrefixSums) {
            int[][] rowMatchPrefixSums = new int[n][n];
            for (int i = k - 1; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    int isMatch = 0;
                    int totalInCol = colPrefixSums[n - 1][j];
                    if (totalInCol > 0) {
                        int countInWindow = (i - k >= 0) 
                                ? (colPrefixSums[i][j] - colPrefixSums[i - k][j]) 
                                : colPrefixSums[i][j];
                        if (countInWindow == totalInCol) {
                            isMatch = 1;
                        }
                    }
                    rowMatchPrefixSums[i][j] = (j > 0 ? rowMatchPrefixSums[i][j - 1] : 0) + isMatch;
                }
            }
            return rowMatchPrefixSums;
        }

        private int[][] computeColMatchPrefixSums(int[][] rowPrefixSums) {
            int[][] colMatchPrefixSums = new int[n][n];
            for (int j = k - 1; j < n; j++) {
                for (int i = 0; i < n; i++) {
                    int isMatch = 0;
                    int totalInRow = rowPrefixSums[i][n - 1];
                    if (totalInRow > 0) {
                        int countInWindow = (j - k >= 0) 
                                ? (rowPrefixSums[i][j] - rowPrefixSums[i][j - k]) 
                                : rowPrefixSums[i][j];
                        if (countInWindow == totalInRow) {
                            isMatch = 1;
                        }
                    }
                    colMatchPrefixSums[i][j] = (i > 0 ? colMatchPrefixSums[i - 1][j] : 0) + isMatch;
                }
            }
            return colMatchPrefixSums;
        }

        private long findMaxPatternCount(long baseCount, int[][] rowMatchPrefixSums, int[][] colMatchPrefixSums) {
            long maxCount = baseCount;

            for (int i = k - 1; i < n; i++) {
                for (int j = k - 1; j < n; j++) {
                    long verticalMatchesInWindow = rowMatchPrefixSums[i][j] 
                            - (j - k >= 0 ? rowMatchPrefixSums[i][j - k] : 0);

                    long horizontalMatchesInWindow = colMatchPrefixSums[i][j] 
                            - (i - k >= 0 ? colMatchPrefixSums[i - k][j] : 0);

                    maxCount = Math.max(maxCount, baseCount + verticalMatchesInWindow + horizontalMatchesInWindow);
                }
            }
            return maxCount;
        }
    }

    /**
     * FastReader provides efficient reading of input data using BufferedReader and StringTokenizer.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * GridAnalyzer calculates the maximum coverage score for a k-sized window in a grid.
 * The score is defined by the number of rows and columns within the window that 
 * satisfy a specific coverage condition, plus the count of entirely empty rows and columns.
 */
public class GridAnalyzer {

    private final int gridSize;
    private final int windowSize;
    private final int[][] grid;

    public GridAnalyzer(int gridSize, int windowSize, int[][] grid) {
        this.gridSize = gridSize;
        this.windowSize = windowSize;
        this.grid = grid;
    }

    /**
     * Orchestrates the calculation process.
     * @return The maximum coverage score.
     */
    public int solve() {
        int emptyRowsAndColsCount = countEmptyRowsAndCols();
        int[][] rowCoverage = computeRowCoverage();
        int[][] colCoverage = computeColCoverage();

        // verticalWindowSums[i][j] = sum of rowCoverage[r][j] for r in [i, i + windowSize - 1]
        int[][] verticalWindowSums = computeVerticalWindowSums(rowCoverage);

        // horizontalWindowSums[i][j] = sum of colCoverage[i][c] for c in [j, j + windowSize - 1]
        int[][] horizontalWindowSums = computeHorizontalWindowSums(colCoverage);

        int maxWindowScore = 0;
        int numWindows = gridSize - windowSize + 1;

        for (int i = 0; i < numWindows; i++) {
            for (int j = 0; j < numWindows; j++) {
                int currentScore = verticalWindowSums[i][j] + horizontalWindowSums[i][j];
                if (currentScore > maxWindowScore) {
                    maxWindowScore = currentScore;
                }
            }
        }

        return maxWindowScore + emptyRowsAndColsCount;
    }

    private int countEmptyRowsAndCols() {
        int count = 0;
        // Count empty rows
        for (int i = 0; i < gridSize; i++) {
            boolean hasBlackCell = false;
            for (int j = 0; j < gridSize; j++) {
                if (grid[i][j] == 1) {
                    hasBlackCell = true;
                    break;
                }
            }
            if (!hasBlackCell) count++;
        }
        // Count empty columns
        for (int j = 0; j < gridSize; j++) {
            boolean hasBlackCell = false;
            for (int i = 0; i < gridSize; i++) {
                if (grid[i][j] == 1) {
                    hasBlackCell = true;
                    break;
                }
            }
            if (!hasBlackCell) count++;
        }
        return count;
    }

    /**
     * Identifies rows where a window of length k covers all existing 'B' cells.
     */
    private int[][] computeRowCoverage() {
        int numWindows = gridSize - windowSize + 1;
        int[][] rowCoverage = new int[gridSize][numWindows];

        for (int i = 0; i < gridSize; i++) {
            int firstBlack = -1;
            int lastBlack = -1;

            for (int j = 0; j < gridSize; j++) {
                if (grid[i][j] == 1) {
                    if (firstBlack == -1) firstBlack = j;
                    lastBlack = j;
                }
            }

            if (firstBlack != -1) {
                for (int j = 0; j < numWindows; j++) {
                    int windowEnd = j + windowSize - 1;
                    if (j <= firstBlack && windowEnd >= lastBlack) {
                        rowCoverage[i][j] = 1;
                    }
                }
            }
        }
        return rowCoverage;
    }

    /**
     * Identifies columns where a window of length k covers all existing 'B' cells.
     */
    private int[][] computeColCoverage() {
        int numWindows = gridSize - windowSize + 1;
        int[][] colCoverage = new int[numWindows][gridSize];

        for (int j = 0; j < gridSize; j++) {
            int firstBlack = -1;
            int lastBlack = -1;

            for (int i = 0; i < gridSize; i++) {
                if (grid[i][j] == 1) {
                    if (firstBlack == -1) firstBlack = i;
                    lastBlack = i;
                }
            }

            if (firstBlack != -1) {
                for (int i = 0; i < numWindows; i++) {
                    int windowEnd = i + windowSize - 1;
                    if (i <= firstBlack && windowEnd >= lastBlack) {
                        colCoverage[i][j] = 1;
                    }
                }
            }
        }
        return colCoverage;
    }

    private int[][] computeVerticalWindowSums(int[][] rowCoverage) {
        int numWindows = gridSize - windowSize + 1;
        int[][] verticalWindowSums = new int[numWindows][numWindows];

        for (int j = 0; j < numWindows; j++) {
            // Initialize first window
            int currentSum = 0;
            for (int i = 0; i < windowSize; i++) {
                currentSum += rowCoverage[i][j];
            }
            verticalWindowSums[0][j] = currentSum;

            // Slide window vertically
            for (int i = 1; i < numWindows; i++) {
                currentSum = currentSum - rowCoverage[i - 1][j] + rowCoverage[i + windowSize - 1][j];
                verticalWindowSums[i][j] = currentSum;
            }
        }
        return verticalWindowSums;
    }

    private int[][] computeHorizontalWindowSums(int[][] colCoverage) {
        int numWindows = gridSize - windowSize + 1;
        int[][] horizontalWindowSums = new int[numWindows][numWindows];

        for (int i = 0; i < numWindows; i++) {
            // Initialize first window
            int currentSum = 0;
            for (int j = 0; j < windowSize; j++) {
                currentSum += colCoverage[i][j];
            }
            horizontalWindowSums[i][0] = currentSum;

            // Slide window horizontally
            for (int j = 1; j < numWindows; j++) {
                currentSum = currentSum - colCoverage[i][j - 1] + colCoverage[i][j + windowSize - 1];
                horizontalWindowSums[i][j] = currentSum;
            }
        }
        return horizontalWindowSums;
    }

    public static void main(String[] args) {
        FastReader sc = new FastReader(System.in);
        try {
            int n = sc.nextInt();
            int k = sc.nextInt();
            int[][] grid = new int[n][n];

            for (int i = 0; i < n; i++) {
                String rowStr = sc.next();
                for (int j = 0; j < n; j++) {
                    grid[i][j] = (rowStr.charAt(j) == 'B') ? 1 : 0;
                }
            }

            GridAnalyzer analyzer = new GridAnalyzer(n, k, grid);
            System.out.println(analyzer.solve());
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * Refactored solution for finding a k x k subgrid that maximizes the number of 
 * "unbroken" white lines (rows or columns) that are either entirely 'W' or 
 * have their '0' (non-'W') characters contained within the subgrid.
 */
public class Main {
    public static void main(String[] args) {
        new Solver().solve();
    }
}

class Solver {
    private FastReader in;
    private PrintWriter out;

    private static final int NOT_FOUND = -1;
    private static final int INF = 1_000_000_000;

    public Solver() {
        this.in = new FastReader();
        this.out = new PrintWriter(System.out);
    }

    public void solve() {
        int n = in.nextInt();
        int k = in.nextInt();
        if (n == 0) {
            out.println(0);
            out.flush();
            return;
        }

        char[][] grid = new char[n][n];
        for (int i = 0; i < n; i++) {
            grid[i] = in.next().toCharArray();
        }

        // Find the boundaries of non-'W' characters in each row and column
        int[] firstZeroInRow = new int[n];
        int[] lastZeroInRow = new int[n];
        int[] firstZeroInCol = new int[n];
        int[] lastZeroInCol = new int[n];

        // Precompute Row boundaries
        for (int i = 0; i < n; i++) {
            int first = INF;
            int last = NOT_FOUND;
            for (int j = 0; j < n; j++) {
                if (grid[i][j] != 'W') {
                    if (first == INF) first = j;
                    last = j;
                }
            }
            firstZeroInRow[i] = (first == INF) ? n : first;
            lastZeroInRow[i] = last;
        }

        // Precompute Column boundaries
        for (int j = 0; j < n; j++) {
            int first = INF;
            int last = NOT_FOUND;
            for (int i = 0; i < n; i++) {
                if (grid[i][j] != 'W') {
                    if (first == INF) first = i;
                    last = i;
                }
            }
            firstZeroInCol[j] = (first == INF) ? n : first;
            lastZeroInCol[j] = last;
        }

        // Prefix sums for all-white rows and columns
        int[] prefixSumAllWhiteRows = new int[n + 1];
        int[] prefixSumAllWhiteCols = new int[n + 1];

        for (int i = 0; i < n; i++) {
            boolean isRowAllWhite = (firstZeroInRow[i] == n);
            prefixSumAllWhiteRows[i + 1] = prefixSumAllWhiteRows[i] + (isRowAllWhite ? 1 : 0);
        }
        for (int j = 0; j < n; j++) {
            boolean isColAllWhite = (firstZeroInCol[j] == n);
            prefixSumAllWhiteCols[j + 1] = prefixSumAllWhiteCols[j] + (isColAllWhite ? 1 : 0);
        }

        // dp1[i][j] = count of rows in [i, i+k-1] whose non-'W's are within col range [j, j+k-1]
        // dp2[i][j] = count of cols in [j, j+k-1] whose non-'W's are within row range [i, i+k-1]
        int[][] dp1 = new int[n][n];
        int[][] dp2 = new int[n][n];

        // Compute dp1 using a sliding window over rows for each column j
        for (int j = 0; j < n; j++) {
            int windowSum = 0;
            int colEnd = j + k - 1;
            // Initial window [0, k-1]
            for (int r = 0; r < k && r < n; r++) {
                if (firstZeroInRow[r] >= j && lastZeroInRow[r] <= colEnd) {
                    windowSum++;
                }
            }
            if (k <= n) dp1[0][j] = windowSum;

            // Sliding window for remaining possible subgrid start rows i
            for (int i = 1; i <= n - k; i++) {
                if (firstZeroInRow[i - 1] >= j && lastZeroInRow[i - 1] <= colEnd) {
                    windowSum--;
                }
                if (firstZeroInRow[i + k - 1] >= j && lastZeroInRow[i + k - 1] <= colEnd) {
                    windowSum++;
                }
                dp1[i][j] = windowSum;
            }
        }

        // Compute dp2 using a sliding window over columns for each row i
        for (int i = 0; i < n; i++) {
            int windowSum = 0;
            int rowEnd = i + k - 1;
            // Initial window [0, k-1]
            for (int c = 0; c < k && c < n; c++) {
                if (firstZeroInCol[c] >= i && lastZeroInCol[c] <= rowEnd) {
                    windowSum++;
                }
            }
            if (k <= n) dp2[i][0] = windowSum;

            // Sliding window for remaining possible subgrid start columns j
            for (int j = 1; j <= n - k; j++) {
                if (firstZeroInCol[j - 1] >= i && lastZeroInCol[j - 1] <= rowEnd) {
                    windowSum--;
                }
                if (firstZeroInCol[j + k - 1] >= i && lastZeroInCol[j + k - 1] <= rowEnd) {
                    windowSum++;
                }
                dp2[i][j] = windowSum;
            }
        }

        int maxScore = 0;
        // Iterate through all valid k x k subgrids
        for (int i = 0; i <= n - k; i++) {
            for (int j = 0; j <= n - k; j++) {
                int u = i;
                int d = i + k - 1;
                int l = j;
                int r = j + k - 1;

                // Count all-white rows/cols completely outside the k x k subgrid
                int whiteRowsAbove = prefixSumAllWhiteRows[u];
                int whiteRowsBelow = prefixSumAllWhiteRows[n] - prefixSumAllWhiteRows[d + 1];
                int whiteColsLeft = prefixSumAllWhiteCols[l];
                int whiteColsRight = prefixSumAllWhiteCols[n] - prefixSumAllWhiteCols[r + 1];

                int currentScore = dp1[i][j] + dp2[i][j] + whiteRowsAbove + whiteRowsBelow + whiteColsLeft + whiteColsRight;
                if (currentScore > maxScore) {
                    maxScore = currentScore;
                }
            }
        }

        out.println(maxScore);
        out.flush();
    }

    /**
     * Fast I/O utility class.
     */
    private static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A solver for the White Lines problem.
 * The goal is to find a k x k square that, when chosen, maximizes the number
 * of rows and columns that become "all white".
 */
public class WhiteLines {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = scanner.nextInt();
            int k = scanner.nextInt();
            boolean[][] grid = new boolean[n][n];

            for (int i = 0; i < n; i++) {
                String line = scanner.next();
                for (int j = 0; j < n; j++) {
                    grid[i][j] = (line.charAt(j) == 'W');
                }
            }

            WhiteLinesSolver solver = new WhiteLinesSolver(grid, n, k);
            out.println(solver.solve());
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    static class WhiteLinesSolver {
        private final boolean[][] grid;
        private final int size;
        private final int windowSize;

        public WhiteLinesSolver(boolean[][] grid, int size, int windowSize) {
            this.grid = grid;
            this.size = size;
            this.windowSize = windowSize;
        }

        public int solve() {
            int[] nonWhiteInRows = new int[size];
            int[] nonWhiteInCols = new int[size];
            int initialWhiteLinesCount = 0;

            // 1. Calculate how many non-white cells exist in each row and column
            for (int i = 0; i < size; i++) {
                for (int j = 0; j < size; j++) {
                    if (!grid[i][j]) {
                        nonWhiteInRows[i]++;
                        nonWhiteInCols[j]++;
                    }
                }
            }

            // 2. Count rows/cols that are already entirely white.
            // We mark them with a value higher than any possible k-segment to avoid double counting.
            for (int i = 0; i < size; i++) {
                if (nonWhiteInRows[i] == 0) {
                    initialWhiteLinesCount++;
                    nonWhiteInRows[i] = size + 1; 
                }
                if (nonWhiteInCols[i] == 0) {
                    initialWhiteLinesCount++;
                    nonWhiteInCols[i] = size + 1;
                }
            }

            // 3. Identify valid segments of length K that would "fix" a row or column
            boolean[][] validColSegments = findValidSegmentsInColumns(nonWhiteInCols);
            boolean[][] validRowSegments = findValidSegmentsInRows(nonWhiteInRows);

            // 4. Aggregate the bonus counts into a 2D grid representing potential k x k squares
            int[][] bonusGrid = calculateBonusGrid(validColSegments, validRowSegments);

            int maxBonus = 0;
            for (int i = 0; i <= size - windowSize; i++) {
                for (int j = 0; j <= size - windowSize; j++) {
                    maxBonus = Math.max(maxBonus, bonusGrid[i][j]);
                }
            }

            return initialWhiteLinesCount + maxBonus;
        }

        /**
         * Determines which column segments of length K contain all non-white cells of that column.
         * returns [column_index][start_row_index]
         */
        private boolean[][] findValidSegmentsInColumns(int[] nonWhiteInCols) {
            boolean[][] validCols = new boolean[size][size - windowSize + 1];
            for (int col = 0; col < size; col++) {
                int currentNonWhiteCount = 0;
                // Initial window
                for (int row = 0; row < windowSize; row++) {
                    if (!grid[row][col]) currentNonWhiteCount++;
                }
                if (currentNonWhiteCount == nonWhiteInCols[col]) {
