import java.util.*;

/**
 * Problem Solver for finding the maximum number of rows and columns 
 * that can be "cleared" (all non-white cells covered) using a k x k window.
 */
public class Solution {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        if (!sc.hasNextInt()) return;
        int n = sc.nextInt();
        int k = sc.nextInt();

        char[][] grid = new char[n][n];
        for (int i = 0; i < n; i++) {
            String rowString = sc.next();
            grid[i] = rowString.toCharArray();
        }

        GridCoverageSolver solver = new GridCoverageSolver(n, k, grid);
        System.out.println(solver.solve());

        sc.close();
    }
}

class GridCoverageSolver {
    private final int n;
    private final int k;
    private final char[][] grid;

    // Stores the first and last index of a non-'W' cell in each row/column
    private final int[] rowMinIdx;
    private final int[] rowMaxIdx;
    private final int[] colMinIdx;
    private final int[] colMaxIdx;

    private static final int UNSET = -1;

    public GridCoverageSolver(int n, int k, char[][] grid) {
        this.n = n;
        this.k = k;
        this.grid = grid;
        this.rowMinIdx = new int[n];
        this.rowMaxIdx = new int[n];
        this.colMinIdx = new int[n];
        this.colMaxIdx = new int[n];

        Arrays.fill(rowMinIdx, Integer.MAX_VALUE);
        Arrays.fill(rowMaxIdx, Integer.MIN_VALUE);
        Arrays.fill(colMinIdx, Integer.MAX_VALUE);
        Arrays.fill(colMaxIdx, Integer.MIN_VALUE);
    }

    public int solve() {
        findZeroBoundaries();

        int emptyRows = countEmptyRows();
        int emptyCols = countEmptyCols();

        // Precompute which rows/cols can be fully covered by a window of size k
        boolean[][] rowCoverable = computeRowCoverability();
        boolean[][] colCoverable = computeColCoverability();

        // Use sliding window to find how many rows/cols are covered in a k-sized block
        int[][] rowCountInWindow = computeRowCoverageSum(rowCoverable);
        int[][] colCountInWindow = computeColCoverageSum(colCoverable);

        int maxCoveredDirty = 0;
        int windowCount = n - k + 1;

        for (int i = 0; i < windowCount; i++) {
            for (int j = 0; j < windowCount; j++) {
                // The total cleared is rows covered + columns covered + already empty ones
                int currentCoverage = rowCountInWindow[i][j] + colCountInWindow[i][j];
                maxCoveredDirty = Math.max(maxCoveredDirty, currentCoverage);
            }
        }

        return maxCoveredDirty + emptyRows + emptyCols;
    }

    /**
     * Identifies the first and last position of a non-'W' cell in every row and column.
     */
    private void findZeroBoundaries() {
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] != 'W') {
                    rowMinIdx[r] = Math.min(rowMinIdx[r], c);
                    rowMaxIdx[r] = Math.max(rowMaxIdx[r], c);
                    colMinIdx[c] = Math.min(colMinIdx[c], r);
                    colMaxIdx[c] = Math.max(colMaxIdx[c], r);
                }
            }
        }
    }

    private int countEmptyRows() {
        int count = 0;
        for (int i = 0; i < n; i++) {
            if (rowMinIdx[i] == Integer.MAX_VALUE) count++;
        }
        return count;
    }

    private int countEmptyCols() {
        int count = 0;
        for (int i = 0; i < n; i++) {
            if (colMinIdx[i] == Integer.MAX_VALUE) count++;
        }
        return count;
    }

    /**
     * rowCoverable[r][j] is true if row 'r' can be covered by a horizontal window starting at column 'j'.
     */
    private boolean[][] computeRowCoverability() {
        boolean[][] coverable = new boolean[n][n - k + 1];
        for (int r = 0; r < n; r++) {
            if (rowMinIdx[r] == Integer.MAX_VALUE) continue;
            for (int j = 0; j <= n - k; j++) {
                if (rowMinIdx[r] >= j && rowMaxIdx[r] <= j + k - 1) {
                    coverable[r][j] = true;
                }
            }
        }
        return coverable;
    }

    /**
     * colCoverable[c][i] is true if column 'c' can be covered by a vertical window starting at row 'i'.
     */
    private boolean[][] computeColCoverability() {
        boolean[][] coverable = new boolean[n][n - k + 1];
        for (int c = 0; c < n; c++) {
            if (colMinIdx[c] == Integer.MAX_VALUE) continue;
            for (int i = 0; i <= n - k; i++) {
                if (colMinIdx[c] >= i && colMaxIdx[c] <= i + k - 1) {
                    coverable[c][i] = true;
                }
            }
        }
        return coverable;
    }

    /**
     * Calculates for every possible window start (i, j), 
     * how many rows in range [i, i+k-1] are covered by the horizontal segment [j, j+k-1].
     */
    private int[][] computeRowCoverageSum(boolean[][] rowCoverable) {
        int windowCount = n - k + 1;
        int[][] coverageSum = new int[windowCount][windowCount];

        for (int j = 0; j < windowCount; j++) {
            int currentSum = 0;
            // Initial window for the first 'k' rows
            for (int r = 0; r < k; r++) {
                if (rowCoverable[r][j]) currentSum++;
            }
            coverageSum[0][j] = currentSum;

            // Sliding the window vertically down the rows
            for (int i = 1; i < windowCount; i++) {
                if (rowCoverable[i + k - 1][j]) currentSum++;
                if (rowCoverable[i - 1][j]) currentSum--;
                coverageSum[i][j] = currentSum;
            }
        }
        return coverageSum;
    }

    /**
     * Calculates for every possible window start (i, j),
     * how many columns in range [j, j+k-1] are covered by the vertical segment [i, i+k-1].
     */
    private int[][] computeColCoverageSum(boolean[][] colCoverable) {
        int windowCount = n - k + 1;
        int[][] coverageSum = new int[windowCount][windowCount];

        for (int i = 0; i < windowCount; i++) {
            int currentSum = 0;
            // Initial window for the first 'k' columns
            for (int c = 0; c < k; c++) {
                if (colCoverable[c][i]) currentSum++;
            }
            coverageSum[i][0] = currentSum;

            // Sliding the window horizontally across the columns
            for (int j = 1; j < windowCount; j++) {
                if (colCoverable[j + k - 1][i]) currentSum++;
                if (colCoverable[j - 1][i]) currentSum--;
                coverageSum[i][j] = currentSum;
            }
        }
        return coverageSum;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Main entry point for the grid analysis program.
 */
public class Main {
    public static void main(String[] args) {
        FastReader reader = new FastReader();

        int gridSize;
        int windowSize;

        try {
            gridSize = reader.nextInt();
            windowSize = reader.nextInt();
        } catch (Exception e) {
            return;
        }

        char[][] grid = new char[gridSize][gridSize];
        for (int i = 0; i < gridSize; i++) {
            String rowString = reader.next();
            for (int j = 0; j < gridSize; j++) {
                grid[i][j] = rowString.charAt(j);
            }
        }

        GridProblemSolver solver = new GridProblemSolver(grid, gridSize, windowSize);
        System.out.println(solver.solve());
    }

    /**
     * Utility class for high-performance input reading.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /**
     * Represents a contiguous segment of 'B' characters in a row or column.
     */
    static class Segment {
        final int start;
        final int end;
        final boolean isEmpty;

        Segment(int start, int end, boolean isEmpty) {
            this.start = start;
            this.end = end;
            this.isEmpty = isEmpty;
        }

        /**
         * Checks if this segment is fully contained within the specified range.
         */
        boolean isContainedWithin(int min, int max) {
            if (isEmpty) return false;
            return start >= min && end <= max;
        }
    }

    /**
     * Handles the core logic of calculating the maximum score for the grid.
     */
    static class GridProblemSolver {
        private final char[][] grid;
        private final int n;
        private final int k;
        private int emptyLinesCount = 0;

        public GridProblemSolver(char[][] grid, int n, int k) {
            this.grid = grid;
            this.n = n;
            this.k = k;
        }

        public int solve() {
            Segment[] rowSegments = findSegments(true);
            Segment[] colSegments = findSegments(false);

            // dp[r][c] will store the score for a KxK window starting at (r, c)
            int[][] scoreTable = new int[n][n];

            // 1. Calculate column containment score via sliding window
            // For every possible vertical range [r, r+k-1], count how many columns 
            // have segments contained within that vertical range.
            for (int r = 0; r <= n - k; r++) {
                int currentCount = 0;
                // Initial window for columns [0, k-1]
                for (int j = 0; j < k; j++) {
                    if (colSegments[j].isContainedWithin(r, r + k - 1)) {
                        currentCount++;
                    }
                }
                scoreTable[r][0] = currentCount;

                // Slide the horizontal window across columns
                for (int c = 1; c <= n - k; c++) {
                    // Remove the column that left the window
                    if (colSegments[c - 1].isContainedWithin(r, r + k - 1)) {
                        currentCount--;
                    }
                    // Add the column that entered the window
                    if (colSegments[c + k - 1].isContainedWithin(r, r + k - 1)) {
                        currentCount++;
                    }
                    scoreTable[r][c] = currentCount;
                }
            }

            // 2. Add row containment score via sliding window
            // For every possible horizontal range [c, c+k-1], count how many rows 
            // have segments contained within that horizontal range.
            for (int c = 0; c <= n - k; c++) {
                int currentCount = 0;
                // Initial window for rows [0, k-1]
                for (int i = 0; i < k; i++) {
                    if (rowSegments[i].isContainedWithin(c, c + k - 1)) {
                        currentCount++;
                    }
                }
                scoreTable[0][c] += currentCount;

                // Slide the vertical window across rows
                for (int r = 1; r <= n - k; r++) {
                    if (rowSegments[r - 1].isContainedWithin(c, c + k - 1)) {
                        currentCount--;
                    }
                    if (rowSegments[r + k - 1].isContainedWithin(c, c + k - 1)) {
                        currentCount++;
                    }
                    scoreTable[r][c] += currentCount;
                }
            }

            int maxContainedSegments = 0;
            for (int i = 0; i <= n - k; i++) {
                for (int j = 0; j <= n - k; j++) {
                    maxContainedSegments = Math.max(maxContainedSegments, scoreTable[i][j]);
                }
            }

            return maxContainedSegments + emptyLinesCount;
        }

        /**
         * Finds segments of 'B' in either rows or columns.
         * 
         * @param isRowMode if true, finds segments in rows (bounds are column indices).
         *                  if false, finds segments in columns (bounds are row indices).
         * @return An array of Segment objects.
         */
        private Segment[] findSegments(boolean isRowMode) {
            Segment[] segments = new Segment[n];
            int emptyCount = 0;

            for (int i = 0; i < n; i++) {
                int start = -1;
                int end = -1;

                for (int j = 0; j < n; j++) {
                    char val = isRowMode ? grid[i][j] : grid[j][i];
                    if (val == 'B') {
                        if (start == -1) start = j;
                        end = j;
                    }
                }

                if (start == -1) {
                    emptyCount++;
                    segments[i] = new Segment(-1, -1, true);
                } else {
                    segments[i] = new Segment(start, end, false);
                }
            }

            this.emptyLinesCount += emptyCount;
            return segments;
        }
    }
}

