            if (n <= 0) {
                writer.println(0);
                return;
            }

            char[][] grid = new char[n][n];
            for (int i = 0; i < n; i++) {
                grid[i] = reader.next().toCharArray();
            }

            // rowStarts[i][j] is true if row i has a valid segment of length k starting at column j
            boolean[][] rowStarts = new boolean[n][n];
            int freeRows = 0;

            for (int i = 0; i < n; i++) {
                int firstB = -1;
                int lastB = -1;
                for (int j = 0; j < n; j++) {
                    if (grid[i][j] == 'B') {
                        if (firstB == -1) firstB = j;
                        lastB = j;
                    }
                }

                if (firstB == -1) {
                    freeRows++;
                } else if (lastB - firstB + 1 <= k) {
                    // A segment starting at 's' covers columns [s, s + k - 1].
                    // To cover all B's (from firstB to lastB):
                    // s <= firstB AND s + k - 1 >= lastB => s >= lastB - k + 1
                    int startMin = Math.max(0, lastB - k + 1);
                    int startMax = Math.min(n - 1, firstB);
                    for (int s = startMin; s <= startMax; s++) {
                        rowStarts[i][s] = true;
                    }
                }
            }

            // colStarts[i][j] is true if column j has a valid segment of length k starting at row i
            boolean[][] colStarts = new boolean[n][n];
            int freeCols = 0;

            for (int j = 0; j < n; j++) {
                int firstB = -1;
                int lastB = -1;
                for (int i = 0; i < n; i++) {
                    if (grid[i][j] == 'B') {
                        if (firstB == -1) firstB = i;
                        lastB = i;
                    }
                }

                if (firstB == -1) {
                    freeCols++;
                } else if (lastB - firstB + 1 <= k) {
                    int startMin = Math.max(0, lastB - k + 1);
                    int startMax = Math.min(n - 1, firstB);
                    for (int s = startMin; s <= startMax; s++) {
                        colStarts[s][j] = true;
                    }
                }
            }

            // verticalCounts[i][j] counts how many rows in the window [i, i + k - 1] 
            // have a valid row-segment starting at column j.
            int[][] verticalCounts = new int[n][n];
            for (int j = 0; j < n; j++) {
                int windowSum = 0;
                for (int i = n - 1; i >= 0; i--) {
                    if (rowStarts[i][j]) windowSum++;
                    if (i + k < n) {
                        if (rowStarts[i + k][j]) windowSum--;
                    }
                    verticalCounts[i][j] = windowSum;
                }
            }

            // horizontalCounts[i][j] counts how many columns in the window [j, j + k - 1] 
            // have a valid column-segment starting at row i.
            int[][] horizontalCounts = new int[n][n];
            for (int i = 0; i < n; i++) {
                int windowSum = 0;
                for (int j = n - 1; j >= 0; j--) {
                    if (colStarts[i][j]) windowSum++;
                    if (j + k < n) {
                        if (colStarts[i][j + k]) windowSum--;
                    }
                    horizontalCounts[i][j] = windowSum;
                }
            }

            int maxIntersection = 0;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    maxIntersection = Math.max(maxIntersection, verticalCounts[i][j] + horizontalCounts[i][j]);
                }
            }

            // The result is the maximum intersection found at any cell + count of empty lines
            writer.println(maxIntersection + freeRows + freeCols);
        }
    }

    /**
     * FastReader for efficient parsing of input streams.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A class to analyze a grid and calculate a maximum score based on the distribution 
 * of 'B' characters and empty rows/columns.
 */
public class GridScoreOptimizer {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        try {
            int n = reader.nextInt();
            int k = reader.nextInt();
            char[][] grid = new char[n][n];
            for (int i = 0; i < n; i++) {
                grid[i] = reader.readLine().toCharArray();
            }

            GridScoreAnalyzer analyzer = new GridScoreAnalyzer(n, k, grid);
            System.out.println(analyzer.calculateMaxScore());
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Performs the heavy lifting of analyzing the grid.
     */
    private static class GridScoreAnalyzer {
        private final int n;
        private final int k;
        private final char[][] grid;

        // Line properties
        private final boolean[] isRowEmpty;
        private final boolean[] isColEmpty;
        private final int[] emptyRowsPrefixSum;
        private final int[] emptyRowsSuffixSum;
        private final int[] emptyColsPrefixSum;
        private final int[] emptyColsSuffixSum;

        // B-character distribution (Prefix sums for rows and columns)
        private final int[][] bCountLeft;
        private final int[][] bCountRight;
        private final int[][] bCountUp;
        private final int[][] bCountDown;

        // Segment availability
        // Segment exists if all 'B's in that row/column are contained within the k-length window
        private final boolean[][] hasRowSegmentOnlyInWindow;
        private final boolean[][] hasColSegmentOnlyInWindow;

        // Window-based sums
        private final int[][] verticalSegmentsInRowWindow;
        private final int[][] horizontalSegmentsInColWindow;

        public GridScoreAnalyzer(int n, int k, char[][] grid) {
            this.n = n;
            this.k = k;
            this.grid = grid;

            this.isRowEmpty = new boolean[n];
            this.isColEmpty = new boolean[n];
            this.emptyRowsPrefixSum = new int[n];
            this.emptyRowsSuffixSum = new int[n];
            this.emptyColsPrefixSum = new int[n];
            this.emptyColsSuffixSum = new int[n];

            this.bCountLeft = new int[n][n];
            this.bCountRight = new int[n][n];
            this.bCountUp = new int[n][n];
            this.bCountDown = new int[n][n];

            this.hasRowSegmentOnlyInWindow = new boolean[n][n];
            this.hasColSegmentOnlyInWindow = new boolean[n][n];

            this.verticalSegmentsInRowWindow = new int[n][n];
            this.horizontalSegmentsInColWindow = new int[n][n];

            computeEmptyLines();
            computeBCounts();
            computeSegmentAvailability();
            computeWindowSums();
        }

        private void computeEmptyLines() {
            Arrays.fill(isRowEmpty, true);
            Arrays.fill(isColEmpty, true);

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (grid[i][j] == 'B') {
                        isRowEmpty[i] = false;
                        isColEmpty[j] = false;
                    }
                }
            }

            // Prefix and suffix sums for empty rows/cols
            int rowAcc = 0;
            for (int i = 0; i < n; i++) {
                if (isRowEmpty[i]) rowAcc++;
                emptyRowsPrefixSum[i] = rowAcc;
            }
            rowAcc = 0;
            for (int i = n - 1; i >= 0; i--) {
                if (isRowEmpty[i]) rowAcc++;
                emptyRowsSuffixSum[i] = rowAcc;
            }

            int colAcc = 0;
            for (int j = 0; j < n; j++) {
                if (isColEmpty[j]) colAcc++;
                emptyColsPrefixSum[j] = colAcc;
            }
            colAcc = 0;
            for (int j = n - 1; j >= 0; j--) {
                if (isColEmpty[j]) colAcc++;
                emptyColsSuffixSum[j] = colAcc;
            }
        }

        private void computeBCounts() {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    bCountLeft[i][j] = (j > 0 ? bCountLeft[i][j - 1] : 0) + (grid[i][j] == 'B' ? 1 : 0);
                }
                for (int j = n - 1; j >= 0; j--) {
                    bCountRight[i][j] = (j < n - 1 ? bCountRight[i][j + 1] : 0) + (grid[i][j] == 'B' ? 1 : 0);
                }
            }

            for (int j = 0; j < n; j++) {
                for (int i = 0; i < n; i++) {
                    bCountUp[i][j] = (i > 0 ? bCountUp[i - 1][j] : 0) + (grid[i][j] == 'B' ? 1 : 0);
                }
                for (int i = n - 1; i >= 0; i--) {
                    bCountDown[i][j] = (i < n - 1 ? bCountDown[i + 1][j] : 0) + (grid[i][j] == 'B' ? 1 : 0);
                }
            }
        }

        private void computeSegmentAvailability() {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    // A horizontal segment is valid if no 'B' exists outside the [j, j+k-1] window in that row
                    boolean noBToRight = (j + k >= n || bCountRight[i][j + k] == 0);
                    boolean noBToLeft = (j == 0 || bCountLeft[i][j - 1] == 0);
                    if (noBToRight && noBToLeft) {
                        hasRowSegmentOnlyInWindow[i][j] = true;
                    }

                    // A vertical segment is valid if no 'B' exists outside the [i, i+k-1] window in that column
                    boolean noBBelow = (i + k >= n || bCountDown[i + k][j] == 0);
                    boolean noBAbove = (i == 0 || bCountUp[i - 1][j] == 0);
                    if (noBBelow && noBAbove) {
                        hasColSegmentOnlyInWindow[i][j] = true;
                    }
                }
            }
        }

        private void computeWindowSums() {
            // Summing valid vertical segments across a horizontal row window
            for (int i = 0; i < n; i++) {
                int windowSum = 0;
                for (int j = n - 1; j >= 0; j--) {
                    windowSum += (hasColSegmentOnlyInWindow[i][j] ? 1 : 0);
                    if (j + k < n) {
                        windowSum -= (hasColSegmentOnlyInWindow[i][j + k] ? 1 : 0);
                    }
                    verticalSegmentsInRowWindow[i][j] = windowSum;
                }
            }

            // Summing valid horizontal segments across a vertical column window
            for (int j = 0; j < n; j++) {
                int windowSum = 0;
                for (int i = n - 1; i >= 0; i--) {
                    windowSum += (hasRowSegmentOnlyInWindow[i][j] ? 1 : 0);
                    if (i + k < n) {
                        windowSum -= (hasRowSegmentOnlyInWindow[i + k][j] ? 1 : 0);
                    }
                    horizontalSegmentsInColWindow[i][j] = windowSum;
                }
            }
        }

        public int calculateMaxScore() {
            int maxScore = 0;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    int currentScore = horizontalSegmentsInColWindow[i][j] + verticalSegmentsInRowWindow[i][j];

                    // Add empty rows/cols outside the k-range
                    if (i > 0) currentScore += emptyRowsPrefixSum[i - 1];
                    if (i + k < n) currentScore += emptyRowsSuffixSum[i + k];
                    if (j > 0) currentScore += emptyColsPrefixSum[j - 1];
                    if (j + k < n) currentScore += emptyColsSuffixSum[j + k];

                    maxScore = Math.max(maxScore, currentScore);
                }
            }
            return maxScore;
        }
    }

    /**
     * Utility class for fast I/O.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String readLine() throws IOException {
            return reader.readLine();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver for finding the maximum number of all-white rows and columns 
 * possible by selecting a k x k square to "fill" with white cells.
 */
public class Main {
    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = scanner.scanInt();
            int k = scanner.scanInt();
            char[][] grid = new char[n][n];
            for (int i = 0; i < n; i++) {
                grid[i] = scanner.scanString().toCharArray();
            }

            WhiteLineSolver solver = new WhiteLineSolver(n, k, grid);
            out.println(solver.solve());
        } catch (Exception e) {
            // In a real production environment, use a logger
            e.printStackTrace();
        } finally {
            out.close();
        }
    }

    static class WhiteLineSolver {
        private final int n;
        private final int k;
        private final char[][] grid;

        // Prefix sums for rows and columns that are ALREADY all white
        private final int[] allWhiteRowsPrefixSum;
        private final int[] allWhiteColsPrefixSum;

        // Prefix sums for the count of 'W' characters in rows/cols to check window validity
        private final int[][] rowWhitePrefixSum;
        private final int[][] colWhitePrefixSum;

        // Count of rows/cols that become all-white within a k-length window
        private final int[][] effectiveWhiteRowsInWindow;
        private final int[][] effectiveWhiteColsInWindow;

        public WhiteLineSolver(int n, int k, char[][] grid) {
            this.n = n;
            this.k = k;
            this.grid = grid;
            this.allWhiteRowsPrefixSum = new int[n + 1];
            this.allWhiteColsPrefixSum = new int[n + 1];
            this.rowWhitePrefixSum = new int[n + 1][n + 1];
            this.colWhitePrefixSum = new int[n + 1][n + 1];
            this.effectiveWhiteRowsInWindow = new int[n + 1][n + 1];
            this.effectiveWhiteColsInWindow = new int[n + 1][n + 1];
        }

        public long solve() {
            precomputeAllWhitePrefixSums();
            precomputeCharacterPrefixSums();
            precomputeEffectiveWindowCounts();
            return calculateMaxLines();
        }

        /**
         * Identifies rows and columns that are composed entirely of 'W'.
         */
        private void precomputeAllWhitePrefixSums() {
            for (int i = 0; i < n; i++) {
                boolean isAllWhite = true;
                for (int j = 0; j < n; j++) {
                    if (grid[i][j] != 'W') {
                        isAllWhite = false;
                        break;
                    }
                }
                allWhiteRowsPrefixSum[i + 1] = allWhiteRowsPrefixSum[i] + (isAllWhite ? 1 : 0);
            }

            for (int j = 0; j < n; j++) {
                boolean isAllWhite = true;
                for (int i = 0; i < n; i++) {
                    if (grid[i][j] != 'W') {
                        isAllWhite = false;
                        break;
                    }
                }
                allWhiteColsPrefixSum[j + 1] = allWhiteColsPrefixSum[j] + (isAllWhite ? 1 : 0);
            }
        }

        /**
         * Computes prefix sums of 'W' characters for every row and column.
         */
        private void precomputeCharacterPrefixSums() {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    rowWhitePrefixSum[i + 1][j + 1] = rowWhitePrefixSum[i + 1][j] + (grid[i][j] == 'W' ? 1 : 0);
                }
            }
            for (int j = 0; j < n; j++) {
                for (int i = 0; i < n; i++) {
                    colWhitePrefixSum[i + 1][j + 1] = colWhitePrefixSum[i][j + 1] + (grid[i][j] == 'W' ? 1 : 0);
                }
            }
        }

        /**
         * For every possible k-length window, precalculates how many 
         * rows/cols would become all-white if that window were all 'W'.
         */
        private void precomputeEffectiveWindowCounts() {
            // Rows
            for (int j = 0; j < n - k + 1; j++) {
                int windowStart = j;
                int windowEnd = j + k; // non-inclusive for prefix math

                // Identify which rows are "effectively white" for this column window
                int[] isRowEffective = new int[n];
                for (int i = 0; i < n; i++) {
                    int whitesOutsideWindow = rowWhitePrefixSum[i + 1][n] - (rowWhitePrefixSum[i + 1][windowEnd] - rowWhitePrefixSum[i + 1][windowStart]);
                    if (whitesOutsideWindow + k == n) {
                        isRowEffective[i] = 1;
                    }
                }

                // Use sliding window to fill effectiveWhiteRowsInWindow[i][j]
                int currentWindowSum = 0;
                for (int i = 0; i < k; i++) currentWindowSum += isRowEffective[i];
                effectiveWhiteRowsInWindow[0][j] = currentWindowSum;

                for (int i = 1; i <= n - k; i++) {
                    currentWindowSum -= isRowEffective[i - 1];
                    currentWindowSum += isRowEffective[i + k - 1];
                    effectiveWhiteRowsInWindow[i][j] = currentWindowSum;
                }
            }

            // Columns
            for (int i = 0; i < n - k + 1; i++) {
                int windowStart = i;
                int windowEnd = i + k;

                int[] isColEffective = new int[n];
                for (int j = 0; j < n; j++) {
                    int whitesOutsideWindow = colWhitePrefixSum[n][j + 1] - (colWhitePrefixSum[windowEnd][j + 1] - colWhitePrefixSum[windowStart][j + 1]);
                    if (whitesOutsideWindow + k == n) {
                        isColEffective[j] = 1;
                    }
                }

                int currentWindowSum = 0;
                for (int j = 0; j < k; j++) currentWindowSum += isColEffective[j];
                effectiveWhiteColsInWindow[i][0] = currentWindowSum;

                for (int j = 1; j <= n - k; j++) {
                    currentWindowSum -= isColEffective[j - 1];
                    currentWindowSum += isColEffective[j + k - 1];
                    effectiveWhiteColsInWindow[i][j] = currentWindowSum;
                }
            }
        }

        /**
         * Iterates through all possible top-left corners of the k x k square.
         */
        private long calculateMaxLines() {
            long maxLines = 0;
            for (int i = 0; i <= n - k; i++) {
                for (int j = 0; j <= n - k; j++) {
                    long currentTotal = 0;

                    // Rows: (White rows above) + (White rows below) + (Rows in window that become white)
                    currentTotal += countRange(allWhiteRowsPrefixSum, 0, i - 1);
                    currentTotal += countRange(allWhiteRowsPrefixSum, i + k, n - 1);
                    currentTotal += effectiveWhiteRowsInWindow[i][j];

                    // Cols: (White cols left) + (White cols right) + (Cols in window that become white)
                    currentTotal += countRange(allWhiteColsPrefixSum, 0, j - 1);
                    currentTotal += countRange(allWhiteColsPrefixSum, j + k, n - 1);
                    currentTotal += effectiveWhiteColsInWindow[i][j];

                    maxLines = Math.max(maxLines, currentTotal);
                }
            }
            return maxLines;
        }

        private int countRange(int[] prefixSum, int l, int r) {
            if (l > r) return 0;
            // prefixSum is 1-indexed relative to the logic above
            return prefixSum[r + 1] - prefixSum[l];
        }
    }

    /**
     * High-performance scanner for fast I/O.
     */
    static class FastScanner {
        private final BufferedInputStream in;
        private final byte[] buffer = new byte[1024 * 8];
        private int pointer = 0;
        private int bufferLength = 0;

        public FastScanner(InputStream inputStream) {
            this.in = new BufferedInputStream(inputStream);
        }

        private int readByte() throws IOException {
            if (pointer >= bufferLength) {
                pointer = 0;
                bufferLength = in.read(buffer);
                if (bufferLength <= 0) return -1;
            }
            return buffer[pointer++] & 0xFF;
        }

        public int scanInt() throws IOException {
            int c = readByte();
            while (c >= 0 && c <= 32) c = readByte();
            if (c == -1) return -1;
            int neg = 1;
            if (c == '-') {
                neg = -1;
                c = readByte();
            }
            int res = 0;
            while (c > 32) {
                res = res * 10 + (c - '0');
                c = readByte();
            }
            return res * neg;
        }

        public String scanString() throws IOException {
            int c = readByte();
            while (c >= 0 && c <= 32) c = readByte();
            if (c == -1) return "";
            StringBuilder sb = new StringBuilder();
            while (c > 32) {
                sb.append((char) c);
                c = readByte();
            }
            return sb.toString();
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * WhiteLines solver to maximize the number of all-white rows and columns
 * by placing one horizontal and one vertical segment of length k.
 */
public class WhiteLines {

    static class GridInfo {
        int n, k;
        int[][] grid;

        // Rows and Columns metadata
        boolean[] rowAlreadyWhite;
        boolean[] colAlreadyWhite;
        boolean[] rowCanBeMadeWhite;
        boolean[] colCanBeMadeWhite;

        // For lines with exactly one black cell
        int[] rowOneBlackCol; // index of the only black cell in row i
        int[] colOneBlackRow; // index of the only black cell in col j

        // Prefix sums to count 'one-black-cell' lines covered by segments
        int[][] rowOneBlackPrefix; // rowOneBlackPrefix[i][j] = count of c in [0, j] where col c is R1 at row i
        int[][] colOneBlackPrefix; // colOneBlackPrefix[j][i] = count of r in [0, i] where row r is R1 at col j

        public GridInfo(int n, int k, int[][] grid) {
            this.n = n;
            this.k = k;
            this.grid = grid;

            rowAlreadyWhite = new boolean[n];
            colAlreadyWhite = new boolean[n];
            rowCanBeMadeWhite = new boolean[n];
            colCanBeMadeWhite = new boolean[n];
            rowOneBlackCol = new int[n];
            colOneBlackRow = new int[n];
            Arrays.fill(rowOneBlackCol, -1);
            Arrays.fill(colOneBlackRow, -1);

            precompute();
        }

        private void precompute() {
            // Row precomputation
            for (int i = 0; i < n; i++) {
                int minC = Integer.MAX_VALUE, maxC = Integer.MIN_VALUE, count = 0;
                for (int j = 0; j < n; j++) {
                    if (grid[i][j] == 1) {
                        count++;
                        minC = Math.min(minC, j);
                        maxC = Math.max(maxC, j);
                    }
                }
                if (count == 0) rowAlreadyWhite[i] = true;
                else if (maxC - minC + 1 <= k) rowCanBeMadeWhite[i] = true;

                if (count == 1) rowOneBlackCol[i] = minC;
            }

            // Column precomputation
            for (int j = 0; j < n; j++) {
                int minR = Integer.MAX_VALUE, maxR = Integer.MIN_VALUE, count = 0;
                for (int i = 0; i < n; i++) {
                    if (grid[i][j] == 1) {
                        count++;
                        minR = Math.min(minR, i);
                        maxR = Math.max(maxR, i);
                    }
                }
                if (count == 0) colAlreadyWhite[j] = true;
                else if (maxR - minR + 1 <= k) colCanBeMadeWhite[j] = true;

                if (count == 1) colOneBlackRow[j] = minR;
            }

            // Prefix sums for O(1) segment range queries
            rowOneBlackPrefix = new int[n][n + 1];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    rowOneBlackPrefix[i][j + 1] = rowOneBlackPrefix[i][j];
                    // Check if column j is R1 at row i
                    if (isColR1AtRow(j, i)) rowOneBlackPrefix[i][j + 1]++;
                }
            }

            colOneBlackPrefix = new int[n][n + 1];
            for (int j = 0; j < n; j++) {
                for (int i = 0; i < n; i++) {
                    colOneBlackPrefix[j][i + 1] = colOneBlackPrefix[j][i];
                    // Check if row i is R1 at col j
                    if (isRowR1AtCol(i, j)) colOneBlackPrefix[j][i + 1]++;
                }
            }
        }

        private boolean isColR1AtRow(int c, int r) {
            return colOneBlackRow[c] != -1 && colOneBlackRow[c] == r;
        }

        private boolean isRowR1AtCol(int r, int c) {
            return rowOneBlackCol[r] != -1 && rowOneBlackCol[r] == c;
        }

        public int solve() {
            int baseWhiteLines = 0;
            for (boolean b : rowAlreadyWhite) if (b) baseWhiteLines++;
            for (boolean b : colAlreadyWhite) if (b) baseWhiteLines++;

            // Precompute segment benefits
            // h_benefit[i][j] = (row i becomes white) + (new columns made white by this segment)
            // v_benefit[j][i] = (col j becomes white) + (new rows made white by this segment)

            int maxExtra = 0;

            // Since the choice of horizontal segment s_h and vertical segment s_v can be 
            // independent, we calculate the best possible extra lines for any s_h and s_v.
            // To handle the intersection correctly, we calculate the max sum of:
            // (New Rows from s_h and s_v) + (New Cols from s_h and s_v)

            // To optimize, we iterate over all possible intersections (i, j)
            // and consider the segments that pass through it.
            // However, a simpler O(n^2) is to find max contribution for any s_h and any s_v
            // and adjust for the overlap at intersection (i, j).

            int[] max_h_at_row = new int[n];
            int[] max_v_at_col = new int[n];

            // best_h[i][j] = contribution of segment (row i, start col j)
            // best_v[j][i] = contribution of segment (col j, start row i)

            // We must find max(h_benefit(i, j) + v_benefit(j, i) - overlap)
            // overlap occurs if:
            // 1. s_h makes col j white AND s_v makes col j white
            // 2. s_v makes row i white AND s_h makes row i white

            // Note: the formulas below ensure that 'row i' and 'col j' are only counted 
            // once per segment type.

            for (int i = 0; i < n; i++) {
                for (int j = 0; j <= n - k; j++) {
                    // Horizontal segment in row i starting at j
                    int h_row_new = (rowCanBeMadeWhite[i] && j <= getMinCol(i) && j + k - 1 >= getMaxCol(i)) ? 1 : 0;
                    // If row i is already white, h_row_new is 0 (not 'new')
                    if (rowAlreadyWhite[i]) h_row_new = 0;

                    int h_cols_new_count = rowOneBlackPrefix[i][j + k] - rowOneBlackPrefix[i][j];
                    // We count all columns c in [j, j+k-1] that are R1 at row i.
                    // One of these might be column j. We'll handle that in the overlap.

                    // To make this O(n^2), we only iterate i and j for segments.
                    // There are O(n^2) segments.
                }
            }

            // Re-simplified logic:
            // For every possible horizontal segment s_h and vertical segment s_v:
            // Extra = (row i newly white) + (cols newly white by s_h) + (col j newly white) + (rows newly white by s_v)
            // We must ensure no double counting of 'row i' or 'col j'.

            // Let's precompute:
            // row_benefit[i][j]: (1 if s_h(i,j) makes row i white and i not in R0) + (count c in [j, j+k-1] where c in C1 at row i)
            // col_benefit[j][i]: (1 if s_v(j,i) makes col j white and j not in C0) + (count r in [i, i+k-1] where r in R1 at col j, and r != i)

            int[][] row_benefit = new int[n][n]; 
            int[][] col_benefit = new int[n][n];
            boolean[][] h_makes_col_j_white = new boolean[n][n]; // h(i, j) makes col j white
            boolean[][] v_makes_row_i_white = new boolean[n][n]; // v(j, i) makes row i white

            for (int i = 0; i < n; i++) {
                int minC = getMinCol(i), maxC = getMaxCol(i);
                for (int j = 0; j <= n - k; j++) {
                    int r_new = (rowCanBeMadeWhite[i] && j <= minC && j + k - 1 >= maxC && !rowAlreadyWhite[i]) ? 1 : 0;
                    int c_new = rowOneBlackPrefix[i][j + k] - rowOneBlackPrefix[i][j];
                    row_benefit[i][j] = r_new + c_new;
                    // Check if this segment makes its own column j white
                    if (isColR1AtRow(j, i) && j >= j && j <= j + k - 1) {
                        h_makes_col_j_white[i][j] = true;
                    }
                }
            }

            for (int j = 0; j < n; j++) {
                int minR = getMinRow(j), maxR = getMaxRow(j);
                for (int i = 0; i <= n - k; i++) {
                    int c_new = (colCanBeMadeWhite[j] && i <= minR && i + k - 1 >= maxR && !colAlreadyWhite[j]) ? 1 : 0;
                    int r_new = (colOneBlackPrefix[j][i + k] - colOneBlackPrefix[j][i]);
                    // The r_new includes row i if row i is R1 at col j. We must exclude it to avoid double counting row i.
                    if (isRowR1AtCol(i, j)) r_new--;
                    col_benefit[j][i] = c_new + r_new;
                    if (isRowR1AtCol(i, j) && i >= i && i <= i + k - 1) {
                        v_makes_row_i_white[j][i] = true;
                    }
                }
            }

            // Now find max(row_benefit[i][j] + col_benefit[j][i] - overlap)
            // Overlap is 1 if: (h_makes_col_j_white[i][j] && col_j_becomes_white_via_sv)
            // Or if: (v_makes_row_i_white[j][i] && row_i_becomes_white_via_sh)
            // Wait, the r_new and c_new logic already prevents row i / col j double counting!
            // The only overlap is if s_h makes col j white AND s_v makes col j white.

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    // We need to test all combinations of s_h starting at i, j_h and s_v starting at j, i_v
                    // But we can just maximize independently and check the intersection.
                    // Actually, let's just iterate over all i, j as the intersection points.
                    // For a fixed intersection (i, j), we pick the best s_h in row i containing j
                    // and the best s_v in col j containing i.
                }
            }

            // Efficient O(n^2) approach:
            // 1. For each row i, find max_{j: j <= col_j_in_s_h <= j+k-1} row_benefit[i][j]
            // 2. For each col j, find max_{i: i <= row_i_in_s_v <= i+k-1} col_benefit[j][i]
            // But the intersection is the only thing that links them.

            // Let's simplify: The segments don't have to intersect.
            // Total Max = Base + Max(Row_Benefit) + Max(Col_Benefit) - (maybe 1 if overlap)
            // But the most robust way is to iterate all s_h (n^2) and all s_v (n^2).
            // To make it O(n^2), we notice:
            // Score = (RowPart_sh + ColPart_sh) + (ColPart_sv + RowPart_sv)
            // where ColPart_sh is number of columns c != j made white by sh.
            // We can precompute max(ColPart_sv + RowPart_sv) for all j and i.

            int[] max_v_for_col = new int[n];
            for (int j = 0; j < n; j++) {
                int best_v = 0;
                for (int i = 0; i <= n - k; i++) {
                    best_v = Math.max(best_v, col_benefit[j][i]);
                }
                max_v_for_col[j] = best_v;
            }

            for (int i = 0; i < n; i++) {
                for (int j = 0; j <= n - k; j++) {
                    // We choose s_h(i, j). What's the best s_v?
                    // The best s_v could be anywhere, but its benefit might be affected if it's in col j.
                    // However, the max benefit of ANY s_v is max_v_for_col[j] or others.
                    // Let's just iterate all s_h and s_v. To stay O(n^2), we pick:
                    // max_sh (row_benefit[i][j] + max_sv_not_in_col_j OR max_sv_in_col_j_with_overlap)

                    // To be safe and stay within time, let's use the fact that the intersection
                    // is only relevant for the column j and row i.
                    // Let's precalculate max_v_for_col[j].
                    // For a fixed s_h(i, j), the best s_v is:
                    // max( max_{s_v in col c != j} col_benefit[c][i_v], max_{s_v in col j} (col_benefit[j][i_v] - overlap) )

                    // This is getting complex. Let's use the property that we can just 
                    // iterate all i, j as the "intersection" and use precomputed maxes.

                    int current_h = row_benefit[i][j];
                    int current_v = max_v_for_col[j]; // This is not quite right, but close.
                    // The max_v_for_col[j] is the max benefit of a vertical segment in column j.
                    // If we pick s_h(i, j), the only thing that can overlap is column j.
                    // If s_h makes col j white, we subtract 1 from (current_v + current_h).

                    int overlap = 0;
                    if (h_makes_col_j_white[i][j]) {
                        // check if the best s_v in column j also makes column j white
                        // To do this perfectly, we'd need to know which s_v gives max_v_for_col[j].
                        // But we can just check all s_v in column j in O(k) or O(n).
                        // Actually, just iterate all s_v in column j.
                        for (int i_v = 0; i_v <= n - k; i_v++) {
                            boolean v_makes_col_j_white = (colCanBeMadeWhite[j] && i_v <= getMinRow(j) && i_v + k - 1 >= getMaxRow(j));
                            if (v_makes_col_j_white) {
                                // If this s_v is the one that provides max_v_for_col[j], we'd subtract 1.
                                // But we can just compute the score for each s_v in column j.
                                int score = current_h + col_benefit[j][i_v];
                                if (v_makes_col_j_white) score--; 
                                maxExtra = Math.max(maxExtra, score);
                            } else {
                                maxExtra = Math.max(maxExtra, current_h + col_benefit[j][i_v]);
                            }
                        }
                    } else {
                        maxExtra = Math.max(maxExtra, current_h + current_v);
                    }
                }
            }

            // Final attempt at O(n^2) logic:
            // The max extra lines can be found by:
            // 1. Maxing (row_benefit[i][j] + col_benefit[c][r]) where c != j.
            // 2. Maxing (row_benefit[i][j] + col_benefit[j][r] - overlap).

            // Let's use the simpler O(n^2) that covers both.
            int max_row_benefit = 0;
            for (int i = 0; i < n; i++) for (int j = 0; j <= n - k; j++) max_row_benefit = Math.max(max_row_benefit, row_benefit[i][j]);
            int max_col_benefit = 0;
            for (int j = 0; j < n; j++) for (int i = 0; i <= n - k; i++) max_col_benefit = Math.max(max_col_benefit, col_benefit[j][i]);

            maxExtra = max_row_benefit + max_col_benefit;
            // Check if any s_h and s_v can overlap to reduce this. 
            // But overlap only reduces, so we look for the maximum possible.
            // The only way the max is not just the sum of two maximums is if 
            // all the best s_h and s_v happen to overlap.
            // Given the constraints and problem type, the sum of maxes is a very strong candidate.
            // Let's refine the search to handle the intersection more carefully.

            // We can iterate all s_h and for each, find the best s_v in O(1) using precomputed maxes.
            // Let's precompute:
            // max_v_except_col[j] = max { col_benefit[c][i_v] | c != j }
            // This is not quite right because i_v also matters.

            // Let's use the most robust O(n^2):
            int overall_max_extra = 0;
            // Precompute best_v_in_col[j] = max_{i_v} col_benefit[j][i_v]
            // Precompute best_v_not_in_col[j] = max_{c != j, i_v} col_benefit[c][i_v]
            int[] best_v_in_col = new int[n];
            int[] best_v_not_in_col = new int[n];
            for (int j = 0; j < n; j++) {
                int m1 = 0, m2 = 0;
                for (int i_v = 0; i_v <= n - k; i_v++) {
                    int val = col_benefit[j][i_v];
                    if (val > m1) { m2 = m1; m1 = val; }
                    else if (val > m2) { m2 = val; }
                }
                best_v_in_col[j] = m1;
                // This is still not quite right, let's just iterate over all s_h and s_v.
                // Since we can't do n^4, we use:
                // max_{s_h, s_v} (h_benefit + v_benefit - overlap)
            }

            // The real O(n^2) is:
            // For each s_h(i, j), we want max_{s_v(c, r)} (h_benefit + v_benefit - overlap)
            // If c != j, overlap = 0. If c == j, overlap = 1 if (h_makes_col_j_white and v_makes_col_j_white).
            // So: max( (max_{c != j} max_{r} v_benefit[c][r]) + h_benefit, 
            //          (max_{r} (v_benefit[j][r] - (v_makes_col_j_white ? 1 : 0))) + h_benefit )

            // Let's implement this!
            int[] max_v_any_col_except = new int[n];
            // To find max_{c != j} max_{r} v_benefit[c][r]
            // We can use prefix and suffix maximums of the max_v_in_col array.
            int[] max_v_in_col = new int[n];
            for (int j = 0; j < n; j++) {
                for (int i = 0; i <= n - k; i++) max_v_in_col[j] = Math.max(max_v_in_col[j], col_benefit[j][i]);
            }
            int[] pref_max_v = new int[n + 1];
            int[] suff_max_v = new int[n + 1];
            for (int j = 0; j < n; j++) pref_max_v[j + 1] = Math.max(pref_max_v[j], max_v_in_col[j]);
            for (int j = n - 1; j >= 0; j--) suff_max_v[j] = Math.max(suff_max_v[j + 1], max_v_in_col[j]);

            for (int i = 0; i < n; i++) {
                for (int j = 0; j <= n - k; j++) {
                    int h_ben = row_benefit[i][j];
                    // Option 1: s_v is in a different column
                    int best_v_other = Math.max(pref_max_v[j], suff_max_v[j + 1]);
                    overall_max_extra = Math.max(overall_max_extra, h_ben + best_v_other);

                    // Option 2: s_v is in column j
                    for (int i_v = 0; i_v <= n - k; i_v++) {
                        int v_ben = col_benefit[j][i_v];
                        int overlap = 0;
                        // overlap if h makes col j white AND v makes col j white
                        if (h_makes_col_j_white[i][j]) {
                            // Check if v makes col j white
                            if (colCanBeMadeWhite[j] && i_v <= getMinRow(j) && i_v + k - 1 >= getMaxRow(j)) {
                                overlap = 1;
                            }
                        }
                        overall_max_extra = Math.max(overall_max_extra, h_ben + v_ben - overlap);
                    }
                }
            }

            return baseWhiteLines + overall_max_extra;
        }

        private int getMinCol(int r) {
            int min = Integer.MAX_VALUE;
            for (int j = 0; j < n; j++) if (grid[r][j] == 1) min = Math.min(min, j);
            return min == Integer.MAX_VALUE ? 0 : min;
        }

        private int getMaxCol(int r) {
            int max = Integer.MIN_VALUE;
            for (int j = 0; j < n; j++) if (grid[r][j] == 1) max = Math.max(max, j);
            return max == Integer.MIN_VALUE ? 0 : max;
        }

        private int getMinRow(int c) {
            int min = Integer.MAX_VALUE;
            for (int i = 0; i < n; i++) if (grid[i][c] == 1) min = Math.min(min, i);
            return min == Integer.MAX_VALUE ? 0 : min;
        }

        private int getMaxRow(int c) {
            int max = Integer.MIN_VALUE;
            for (int i = 0; i < n; i++) if (grid[i][c] == 1) max = Math.max(max, i);
            return max == Integer.MIN_VALUE ? 0 : max;
        }
    }

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextInt()) return;
        int n = sc.nextInt();
        int k = sc.nextInt();
        int[][] grid = new int[n][n];
        for (int i = 0; i < n; i++) {
            String line = sc.next();
            for (int j = 0; j < n; j++) {
                grid[i][j] = (line.charAt(j) == 'W') ? 1 : 0;
            }
        }
        GridInfo gi = new GridInfo(n, k, grid);
        System.out.println(gi.solve());
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for TaskD.
 * This program calculates a maximum score based on grid row and column boundaries
 * relative to a sliding window.
 */
public class TaskD {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int gridSize = reader.nextInt();
            int windowSize = reader.nextInt();

            // Initialize the grid with size (windowSize + gridSize)
            boolean[][] grid = new boolean[windowSize + gridSize][windowSize + gridSize];

            // Populate the grid based on input
            for (int i = 0; i < gridSize; i++) {
                String rowString = reader.next();
                for (int j = 0; j < gridSize; j++) {
                    if (rowString.charAt(j) == 'B') {
                        grid[windowSize + i][windowSize + j] = true;
                    }
                }
            }

            TaskSolver solver = new TaskSolver(gridSize, windowSize, grid);
            writer.println(solver.solve());

        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    /**
     * Represents the starting and ending indices of a contiguous segment of 'B's.
     */
    private static class Boundary {
        final int start;
        final int end;
        final boolean isEmpty;

        Boundary(int start, int end) {
            this.start = start;
            this.end = end;
            this.isEmpty = (start == -1);
        }
    }

    /**
     * Handles the core algorithmic logic.
     */
    private static class TaskSolver {
        private final int gridSize;
        private final int windowSize;
        private final boolean[][] grid;
        private final Boundary[] rowBoundaries;
        private final Boundary[] colBoundaries;

        public TaskSolver(int gridSize, int windowSize, boolean[][] grid) {
            this.gridSize = gridSize;
            this.windowSize = windowSize;
            this.grid = grid;
            this.rowBoundaries = calculateAllBoundaries(true);
            this.colBoundaries = calculateAllBoundaries(false);
        }

        /**
         * Calculates boundaries for all rows or all columns.
         * @param isRowWise true if calculating row boundaries, false for column boundaries.
         */
        private Boundary[] calculateAllBoundaries(boolean isRowWise) {
            int totalDim = windowSize + gridSize;
            Boundary[] boundaries = new Boundary[totalDim];

            for (int i = 0; i < totalDim; i++) {
                int start = -1;
                int end = -1;
                for (int j = 0; j < totalDim; j++) {
                    boolean isCellFilled = isRowWise ? grid[i][j] : grid[j][i];
                    if (isCellFilled) {
                        if (start == -1) start = j;
                        end = j;
                    }
                }
                boundaries[i] = new Boundary(start, end);
            }
            return boundaries;
        }

        /**
         * Executes the main scoring algorithm.
         */
        public int solve() {
            int totalDim = windowSize + gridSize;
            int[][] rowScoreTable = new int[totalDim][totalDim];
            int[][] colScoreTable = new int[totalDim][totalDim];
            int maxScore = 0;

            // Calculate scores using 2D dynamic programming approach
            for (int i = 1; i <= gridSize; i++) {
                for (int j = 1; j <= gridSize; j++) {
                    // Row-based score calculation
                    rowScoreTable[i][j] = rowScoreTable[i - 1][j];
                    if (isBoundaryWithinWindow(rowBoundaries[i - 1], j, windowSize)) {
                        rowScoreTable[i][j]--;
                    }
                    if (isBoundaryWithinWindow(rowBoundaries[windowSize + i - 1], j, windowSize)) {
                        rowScoreTable[i][j]++;
                    }

                    // Column-based score calculation
                    colScoreTable[i][j] = colScoreTable[i][j - 1];
                    if (isBoundaryWithinWindow(colBoundaries[j - 1], i, windowSize)) {
                        colScoreTable[i][j]--;
                    }
                    if (isBoundaryWithinWindow(colBoundaries[windowSize + j - 1], i, windowSize)) {
                        colScoreTable[i][j]++;
                    }

                    maxScore = Math.max(maxScore, rowScoreTable[i][j] + colScoreTable[i][j]);
                }
            }

            // Add bonus points for empty rows/columns in the target range
            for (int i = windowSize; i < totalDim; i++) {
                if (rowBoundaries[i].isEmpty) maxScore++;
                if (colBoundaries[i].isEmpty) maxScore++;
            }

            return maxScore;
        }

        /**
         * Checks if the range of a boundary is fully contained within the window [windowStart, windowStart + windowSize).
         */
        private boolean isBoundaryWithinWindow(Boundary b, int windowStart, int windowSize) {
            if (b.isEmpty) return false;
            return b.start >= windowStart && b.end < windowStart + windowSize;
        }
    }

    /**
     * Efficient utility for reading input.
     */
    private static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

/**
 * DWhiteLines finds the maximum number of "white lines" (rows or columns) 
 * that can be captured within a k x k window, added to the total count 
 * of already white lines in the grid.
 */
public class DWhiteLines {

    private static final int NOT_FOUND = Integer.MAX_VALUE;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int n = scanner.nextInt();
        int k = scanner.nextInt();
        scanner.nextLine(); // Consume newline

        char[][] board = new char[n][n];
        for (int i = 0; i < n; i++) {
            String line = scanner.nextLine();
            board[i] = line.toCharArray();
        }

        DWhiteLines solver = new DWhiteLines();
        int result = solver.solve(n, k, board);
        System.out.println(result);

        scanner.close();
    }

    /**
     * Orchestrates the calculation of white lines.
     */
    public int solve(int n, int k, char[][] board) {
        int[] firstBlackInRow = new int[n];
        int[] lastBlackInRow = new int[n];
        int[] firstBlackInCol = new int[n];
        int[] lastBlackInCol = new int[n];

        int globalWhiteRows = 0;
        int globalWhiteCols = 0;

        // Initialize boundary arrays
        for (int i = 0; i < n; i++) {
            firstBlackInRow[i] = NOT_FOUND;
            lastBlackInRow[i] = -1;
            firstBlackInCol[i] = NOT_FOUND;
            lastBlackInCol[i] = -1;
        }

        // Step 1: Pre-calculate boundaries of black cells and count globally white lines
        for (int i = 0; i < n; i++) {
            // Process Rows
            boolean rowHasBlack = false;
            for (int j = 0; j < n; j++) {
                if (board[i][j] == 'B') {
                    if (firstBlackInRow[i] == NOT_FOUND) firstBlackInRow[i] = j;
                    lastBlackInRow[i] = j;
                    rowHasBlack = true;
                }
            }
            if (!rowHasBlack) globalWhiteRows++;

            // Process Columns
            boolean colHasBlack = false;
            for (int j = 0; j < n; j++) {
                if (board[j][i] == 'B') {
                    if (firstBlackInCol[i] == NOT_FOUND) firstBlackInCol[i] = j;
                    lastBlackInCol[i] = j;
                    colHasBlack = true;
                }
            }
            if (!colHasBlack) globalWhiteCols++;
        }

        // Step 2: Calculate how many non-white lines become "white" within a k x k window.
        // rowExtra[i][j] counts rows in window [i, i+k-1] whose black cells fall within col window [j, j+k-1]
        int[][] rowExtra = computeExtraLines(n, k, firstBlackInRow, lastBlackInRow);

        // colExtra[j][i] counts cols in window [j, j+k-1] whose black cells fall within row window [i, i+k-1]
        int[][] colExtra = computeExtraLines(n, k, firstBlackInCol, lastBlackInCol);

        int maxExtraLines = 0;
        for (int i = 0; i <= n - k; i++) {
            for (int j = 0; j <= n - k; j++) {
                // Combine extra rows and extra columns for the same k x k window
                int currentExtra = rowExtra[i][j] + colExtra[j][i];
                maxExtraLines = Math.max(maxExtraLines, currentExtra);
            }
        }

        return globalWhiteRows + globalWhiteCols + maxExtraLines;
    }

    /**
     * Uses a sliding window to compute a 2D array where result[i][j] is the count 
     * of lines in the primary window [i, i+k-1] that are fully contained 
     * within the secondary window [j, j+k-1].
     */
    private int[][] computeExtraLines(int n, int k, int[] firsts, int[] lasts) {
        int[][] extra = new int[n - k + 1][n - k + 1];

        // Calculate initial window for the primary dimension (i = 0)
        for (int j = 0; j <= n - k; j++) {
            int count = 0;
            for (int idx = 0; idx < k; idx++) {
                if (isLineContained(firsts[idx], lasts[idx], j, j + k - 1)) {
                    count++;
                }
            }
            extra[0][j] = count;
        }

        // Slide the primary dimension window from index i-1 to i
        for (int i = 1; i <= n - k; i++) {
            for (int j = 0; j <= n - k; j++) {
                extra[i][j] = extra[i - 1][j];

                // Remove the line that is sliding out of the window
                if (isLineContained(firsts[i - 1], lasts[i - 1], j, j + k - 1)) {
                    extra[i][j]--;
                }

                // Add the line that is sliding into the window
                if (isLineContained(firsts[i + k - 1], lasts[i + k - 1], j, j + k - 1)) {
                    extra[i][j]++;
                }
            }
        }

        return extra;
    }

    /**
     * Helper to check if all black cells in a line fall within the specified window.
     */
    private boolean isLineContained(int first, int last, int windowStart, int windowEnd) {
        return first != NOT_FOUND && first >= windowStart && last <= windowEnd;
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to solve the grid window problem by finding a KxK subgrid 
 * that maximizes the number of "satisfied" rows and columns.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        try {
            int n = reader.nextInt();
            int k = reader.nextInt();
            char[][] grid = reader.readGrid(n);

            GridProblemSolver solver = new GridProblemSolver(n, k, grid);
            int result = solver.solve();

            System.out.println(result);
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Handles the core logic of calculating satisfied rows and columns within windows.
     */
    static class GridProblemSolver {
        private final int n;
        private final int k;
        private final boolean[][] isBlack;

        public GridProblemSolver(int n, int k, char[][] grid) {
            this.n = n;
            this.k = k;
            this.isBlack = new boolean[n][n];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    this.isBlack[i][j] = (grid[i][j] == 'B');
                }
            }
        }

        public int solve() {
            int emptyLinesCount = countEmptyLines();
            int[][] satisfiedRowsInWindow = calculateSatisfiedRowsInWindow();
            int[][] satisfiedColsInWindow = calculateSatisfiedColsInWindow();

            int maxSatisfiedCount = 0;
            int windowLimit = n - k + 1;

            for (int i = 0; i < windowLimit; i++) {
                for (int j = 0; j < windowLimit; j++) {
                    int currentSatisfied = satisfiedRowsInWindow[i][j] + satisfiedColsInWindow[i][j];
                    maxSatisfiedCount = Math.max(maxSatisfiedCount, currentSatisfied);
                }
            }

            return maxSatisfiedCount + emptyLinesCount;
        }

        private int countEmptyLines() {
            int emptyRows = 0;
            for (int i = 0; i < n; i++) {
                boolean hasBlack = false;
                for (int j = 0; j < n; j++) {
                    if (isBlack[i][j]) {
                        hasBlack = true;
                        break;
                    }
                }
                if (!hasBlack) emptyRows++;
            }

            int emptyCols = 0;
            for (int j = 0; j < n; j++) {
                boolean hasBlack = false;
                for (int i = 0; i < n; i++) {
                    if (isBlack[i][j]) {
                        hasBlack = true;
                        break;
                    }
                }
                if (!hasBlack) emptyCols++;
            }

            return emptyRows + emptyCols;
        }

        private int[][] calculateSatisfiedRowsInWindow() {
            int[][] rowSatisfiedPrefixSum = new int[n + 1][n];
            int windowLimit = n - k + 1;

            for (int i = 0; i < n; i++) {
                int totalBlackInRow = 0;
                for (int j = 0; j < n; j++) if (isBlack[i][j]) totalBlackInRow++;

                for (int j = 0; j < windowLimit; j++) {
                    int blacksInWindow = 0;
                    for (int l = 0; l < k; l++) {
                        if (isBlack[i][j + l]) blacksInWindow++;
                    }

                    boolean satisfied = (totalBlackInRow > 0 && blacksInWindow == totalBlackInRow);
                    rowSatisfiedPrefixSum[i + 1][j] = rowSatisfiedPrefixSum[i][j] + (satisfied ? 1 : 0);
                }
                // Fill remaining columns for the prefix sum array
                for (int j = windowLimit; j < n; j++) {
                    rowSatisfiedPrefixSum[i + 1][j] = rowSatisfiedPrefixSum[i][j];
                }
            }

            int[][] satisfiedRowsInWindow = new int[windowLimit][windowLimit];
            for (int i = 0; i < windowLimit; i++) {
                for (int j = 0; j < windowLimit; j++) {
                    satisfiedRowsInWindow[i][j] = rowSatisfiedPrefixSum[i + k][j] - rowSatisfiedPrefixSum[i][j];
                }
            }
            return satisfiedRowsInWindow;
        }

        private int[][] calculateSatisfiedColsInWindow() {
            int[][] colSatisfiedPrefixSum = new int[n][n + 1];
            int windowLimit = n - k + 1;

            for (int j = 0; j < n; j++) {
                int totalBlackInCol = 0;
                for (int i = 0; i < n; i++) if (isBlack[i][j]) totalBlackInCol++;

                for (int i = 0; i < windowLimit; i++) {
                    int blacksInWindow = 0;
                    for (int l = 0; l < k; l++) {
                        if (isBlack[i + l][j]) blacksInWindow++;
                    }

                    boolean satisfied = (totalBlackInCol > 0 && blacksInWindow == totalBlackInCol);
                    colSatisfiedPrefixSum[i][j + 1] = colSatisfiedPrefixSum[i][j] + (satisfied ? 1 : 0);
                }
                // Fill remaining columns for the prefix sum array
                for (int i = windowLimit; i < n; i++) {
                    colSatisfiedPrefixSum[i][n] = colSatisfiedPrefixSum[i][n - 1]; // Placeholder
                }
                // Correcting the prefix sum logic for columns
                for (int i = 0; i < n; i++) {
                    for (int c = j + 1; c <= n; c++) {
                        // This is actually handled better by re-structuring the loop
                    }
                }
            }

            // Redoing Col Logic to match the prefix-sum logic cleanly
            int[][] colSatisfied = new int[n][n + 1];
            for (int j = 0; j < n; j++) {
                int totalBlackInCol = 0;
                for (int i = 0; i < n; i++) if (isBlack[i][j]) totalBlackInCol++;

                for (int i = 0; i < n; i++) {
                    boolean satisfied = false;
                    if (totalBlackInCol > 0 && i <= n - k) {
                        int blacksInWindow = 0;
                        for (int l = 0; l < k; l++) {
                            if (isBlack[i + l][j]) blacksInWindow++;
                        }
                        if (blacksInWindow == totalBlackInCol) satisfied = true;
                    }
                    colSatisfied[i][j + 1] = colSatisfied[i][j] + (satisfied ? 1 : 0);
                }
            }

            int[][] satisfiedColsInWindow = new int[windowLimit][windowLimit];
            for (int i = 0; i < windowLimit; i++) {
                for (int j = 0; j < windowLimit; j++) {
                    satisfiedColsInWindow[i][j] = colSatisfied[i][j + k] - colSatisfied[i][j];
                }
            }
            return satisfiedColsInWindow;
        }
    }

    /**
     * Optimized utility for reading input from a stream.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public char[][] readGrid(int n) throws IOException {
            char[][] grid = new char[n][n];
            for (int i = 0; i < n; i++) {
                String row = next();
                for (int j = 0; j < n; j++) {
                    grid[i][j] = row.charAt(j);
                }
            }
            return grid;
        }
    }
}

import java.util.Scanner;

/**
 * Represents the range of 'B' characters within a single row or column.
 */
class LineRange {
    private final int firstBlockIndex;
    private final int lastBlockIndex;
    private final boolean isEmpty;

    public LineRange(int firstBlockIndex, int lastBlockIndex, boolean isEmpty) {
        this.firstBlockIndex = firstBlockIndex;
        this.lastBlockIndex = lastBlockIndex;
        this.isEmpty = isEmpty;
    }

    public boolean isEmpty() {
        return isEmpty;
    }

    /**
     * Checks if the blocks in this line are entirely contained within the given range.
     * Empty lines are not handled here as they are accounted for separately 
     * via the total empty count.
     */
    public boolean isContainedInRange(int rangeStart, int rangeEnd) {
        if (isEmpty) {
            return false;
        }
        return firstBlockIndex >= rangeStart && lastBlockIndex <= rangeEnd;
    }
}

/**
 * Handles the logic for calculating the maximum number of lines (rows/cols)
 * covered by a k x k window.
 */
class GridSolver {
    private final int gridSize;
    private final int windowSize;
    private final String[] grid;

    public GridSolver(int gridSize, int windowSize, String[] grid) {
        this.gridSize = gridSize;
        this.windowSize = windowSize;
        this.grid = grid;
    }

    public int solve() {
        int[][] coverageMatrix = new int[gridSize][gridSize];

        LineRange[] rowRanges = computeLineRanges(true);
        LineRange[] colRanges = computeLineRanges(false);

        // Calculate row contributions to the coverage matrix
        calculateContributions(rowRanges, coverageMatrix, true);

        // Calculate column contributions to the coverage matrix
        calculateContributions(colRanges, coverageMatrix, false);

        return findMaxInMatrix(coverageMatrix);
    }

    /**
     * Precomputes the boundaries of 'B' characters for all rows or all columns.
     */
    private LineRange[] computeLineRanges(boolean computeRows) {
        LineRange[] ranges = new LineRange[gridSize];
        for (int i = 0; i < gridSize; i++) {
            int first = -1;
            int last = -1;

            for (int j = 0; j < gridSize; j++) {
                char c = computeRows ? grid[i].charAt(j) : grid[j].charAt(i);
                if (c == 'B') {
                    if (first == -1) first = j;
                    last = j;
                }
            }
            ranges[i] = new LineRange(first, last, first == -1);
        }
        return ranges;
    }

    /**
     * Uses a sliding window to calculate how many lines are covered by a window of size k.
     * 
     * @param lines The precomputed LineRange array for the dimension being processed.
     * @param matrix The 2D matrix to accumulate coverage counts.
     * @param isRow True if we are calculating row coverage, false for column coverage.
     */
    private void calculateContributions(LineRange[] lines, int[][] matrix, boolean isRow) {
        int totalEmptyLines = 0;
        for (LineRange line : lines) {
            if (line.isEmpty()) totalEmptyLines++;
        }

        // If isRow is true, the window moves across columns (j) and slides through rows (i)
        // If isRow is false, the window moves across rows (i) and slides through columns (j)
        if (isRow) {
            for (int colStart = 0; colStart <= gridSize - windowSize; colStart++) {
                int colEnd = colStart + windowSize - 1;
                int currentWindowCoverage = totalEmptyLines;

                // Initial window for rows [0, windowSize-1]
                for (int i = 0; i < windowSize; i++) {
                    if (!lines[i].isEmpty() && lines[i].isContainedInRange(colStart, colEnd)) {
                        currentWindowCoverage++;
                    }
                }
                matrix[0][colStart] += currentWindowCoverage;

                // Slide the row window
                for (int rowStart = 1; rowStart <= gridSize - windowSize; rowStart++) {
                    int exitingRow = rowStart - 1;
                    int enteringRow = rowStart + windowSize - 1;

                    if (!lines[enteringRow].isEmpty() && lines[enteringRow].isContainedInRange(colStart, colEnd)) {
                        currentWindowCoverage++;
                    }
                    if (!lines[exitingRow].isEmpty() && lines[exitingRow].isContainedInRange(colStart, colEnd)) {
                        currentWindowCoverage--;
                    }
                    matrix[rowStart][colStart] += currentWindowCoverage;
                }
            }
        } else {
            for (int rowStart = 0; rowStart <= gridSize - windowSize; rowStart++) {
                int rowEnd = rowStart + windowSize - 1;
                int currentWindowCoverage = totalEmptyLines;

                // Initial window for columns [0, windowSize-1]
                for (int j = 0; j < windowSize; j++) {
                    if (!lines[j].isEmpty() && lines[j].isContainedInRange(rowStart, rowEnd)) {
                        currentWindowCoverage++;
                    }
                }
                matrix[rowStart][0] += currentWindowCoverage;

                // Slide the column window
                for (int colStart = 1; colStart <= gridSize - windowSize; colStart++) {
                    int exitingCol = colStart - 1;
                    int enteringCol = colStart + windowSize - 1;

                    if (!lines[enteringCol].isEmpty() && lines[enteringCol].isContainedInRange(rowStart, rowEnd)) {
                        currentWindowCoverage++;
                    }
                    if (!lines[exitingCol].isEmpty() && lines[exitingCol].isContainedInRange(rowStart, rowEnd)) {
                        currentWindowCoverage--;
                    }
                    matrix[rowStart][colStart] += currentWindowCoverage;
                }
            }
        }
    }

    private int findMaxInMatrix(int[][] matrix) {
        int max = 0;
        for (int[] row : matrix) {
            for (int val : row) {
                max = Math.max(max, val);
            }
        }
        return max;
    }
}

