import java.util.Scanner;

/**
 * A utility class to handle prefix sum queries on a 1D array.
 */
class PrefixSum {
    private final int[] prefixSums;

    public PrefixSum(int[] values) {
        int n = values.length;
        this.prefixSums = new int[n];
        if (n > 0) {
            this.prefixSums[0] = values[0];
            for (int i = 1; i < n; i++) {
                this.prefixSums[i] = this.prefixSums[i - 1] + values[i];
            }
        }
    }

    /**
     * Returns the sum of elements in the range [l, r] inclusive.
     */
    public int query(int l, int r) {
        if (l > r || l < 0 || r >= prefixSums.length) {
            return 0;
        }
        if (l == 0) {
            return prefixSums[r];
        }
        return prefixSums[r] - prefixSums[l - 1];
    }
}

/**
 * Represents the grid and encapsulates all necessary prefix sum data.
 */
class Grid {
    private final int n;
    private final int k;
    private final int[][] grid;

    // Prefix sums for existing 'W' cells in rows and columns
    private final PrefixSum[] rowWCounts;
    private final PrefixSum[] colWCounts;

    // Prefix sums for rows and columns that are already full
    private final PrefixSum fullRows;
    private final PrefixSum fullCols;

    // Prefix sums for rows that become full if a specific column-cut is applied
    private final PrefixSum[] rowCompletableByColCut;

    // Prefix sums for columns that become full if a specific row-cut is applied
    private final PrefixSum[] colCompletableByRowCut;

    public Grid(int n, int k, char[][] charGrid) {
        this.n = n;
        this.k = k;
        this.grid = new int[n][n];
        this.rowWCounts = new PrefixSum[n];
        this.colWCounts = new PrefixSum[n];

        for (int i = 0; i < n; i++) {
            int[] rowData = new int[n];
            for (int j = 0; j < n; j++) {
                grid[i][j] = (charGrid[i][j] == 'W') ? 1 : 0;
                rowData[j] = grid[i][j];
            }
            rowWCounts[i] = new PrefixSum(rowData);
        }

        for (int j = 0; j < n; j++) {
            int[] colData = new int[n];
            for (int i = 0; i < n; i++) {
                colData[i] = grid[i][j];
            }
            colWCounts[j] = new PrefixSum(colData);
        }

        this.fullRows = precomputeFullRows();
        this.fullCols = precomputeFullCols();
        this.rowCompletableByColCut = precomputeRowCompletableByColCut();
        this.colCompletableByRowCut = precomputeColCompletableByRowCut();
    }

    private PrefixSum precomputeFullRows() {
        int[] isFull = new int[n];
        for (int i = 0; i < n; i++) {
            if (rowWCounts[i].query(0, n - 1) == n) {
                isFull[i] = 1;
            }
        }
        return new PrefixSum(isFull);
    }

    private PrefixSum precomputeFullCols() {
        int[] isFull = new int[n];
        for (int j = 0; j < n; j++) {
            if (colWCounts[j].query(0, n - 1) == n) {
                isFull[j] = 1;
            }
        }
        return new PrefixSum(isFull);
    }

    private PrefixSum[] precomputeRowCompletableByColCut() {
        PrefixSum[] completeness = new PrefixSum[n - k + 1];
        for (int colCutStart = 0; colCutStart <= n - k; colCutStart++) {
            int[] rowCompletable = new int[n];
            for (int r = 0; r < n; r++) {
                // A row is completable if the 'W's outside the cut plus the k cells in the cut equal n
                int wOutsideCut = rowWCounts[r].query(0, colCutStart - 1) + 
                                 rowWCounts[r].query(colCutStart + k, n - 1);
                if (wOutsideCut + k == n) {
                    rowCompletable[r] = 1;
                }
            }
            completeness[colCutStart] = new PrefixSum(rowCompletable);
        }
        return completeness;
    }

    private PrefixSum[] precomputeColCompletableByRowCut() {
        PrefixSum[] completeness = new PrefixSum[n - k + 1];
        for (int rowCutStart = 0; rowCutStart <= n - k; rowCutStart++) {
            int[] colCompletable = new int[n];
            for (int c = 0; c < n; c++) {
                int wOutsideCut = colWCounts[c].query(0, rowCutStart - 1) + 
                                 colWCounts[c].query(rowCutStart + k, n - 1);
                if (wOutsideCut + k == n) {
                    colCompletable[c] = 1;
                }
            }
            completeness[rowCutStart] = new PrefixSum(colCompletable);
        }
        return completeness;
    }

    // Getters for the Solver
    public int getN() { return n; }
    public int getK() { return k; }
    public PrefixSum getFullRows() { return fullRows; }
    public PrefixSum getFullCols() { return fullCols; }
    public PrefixSum[] getRowCompletableByColCut() { return rowCompletableByColCut; }
    public PrefixSum[] getColCompletableByRowCut() { return colCompletableByRowCut; }
}

/**
 * Orchestrates the logic to find the maximum number of full rows and columns.
 */
class GridAnalyzer {
    private final Grid grid;

    public GridAnalyzer(Grid grid) {
        this.grid = grid;
    }

    public int findMaxFullRowsAndCols() {
        int n = grid.getN();
        int k = grid.getK();
        int maxCount = 0;

        for (int i = 0; i <= n - k; i++) { // Row-cut start index
            for (int j = 0; j <= n - k; j++) { // Column-cut start index
                int currentCount = 0;

                // 1. Rows in the row-cut range that become full due to the column-cut
                currentCount += grid.getRowCompletableByColCut()[j].query(i, i + k - 1);

                // 2. Columns in the column-cut range that become full due to the row-cut
                currentCount += grid.getColCompletableByRowCut()[i].query(j, j + k - 1);

                // 3. Rows outside the row-cut range that were already full
                currentCount += grid.getFullRows().query(0, i - 1);
                currentCount += grid.getFullRows().query(i + k, n - 1);

                // 4. Columns outside the column-cut range that were already full
                currentCount += grid.getFullCols().query(0, j - 1);
                currentCount += grid.getFullCols().query(j + k, n - 1);

                maxCount = Math.max(maxCount, currentCount);
            }
        }
        return maxCount;
    }
}

public class Generator {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextInt()) return;

        int n = sc.nextInt();
        int k = sc.nextInt();
        char[][] charGrid = new char[n][n];

        for (int i = 0; i < n; i++) {
            String line = sc.next();
            for (int j = 0; j < n; j++) {
                charGrid[i][j] = line.charAt(j);
            }
        }

        Grid grid = new Grid(n, k, charGrid);
        GridAnalyzer analyzer = new GridAnalyzer(grid);

        System.out.println(analyzer.findMaxFullRowsAndCols());
        sc.close();
    }
}

import java.util.*;
import java.io.*;

/**
 * Problem: Maximize the number of "clean" rows and columns by placing a k x k window.
 * A row/column is clean if it has no 'B' characters OR all its 'B' characters 
 * can be covered by the k x k window.
 */
public class Solution {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        // Read n and k
        String nStr = reader.next();
        if (nStr == null) return;
        int n = Integer.parseInt(nStr);
        int k = reader.nextInt();

        // Read the grid
        char[][] grid = new char[n][n];
        for (int i = 0; i < n; i++) {
            grid[i] = reader.next().toCharArray();
        }

        // Process the grid to find the maximum coverage
        GridAnalyzer analyzer = new GridAnalyzer(n, k, grid);
        int result = analyzer.solve();

        System.out.println(result);
    }

    /**
     * Encapsulates the logic for analyzing the grid and calculating 
     * the maximum number of clean rows and columns.
     */
    static class GridAnalyzer {
        private final int n;
        private final int k;
        private final int[] rowMinCol;
        private final int[] rowMaxCol;
        private final int[] colMinRow;
        private final int[] colMaxRow;

        public GridAnalyzer(int n, int k, char[][] grid) {
            this.n = n;
            this.k = k;
            this.rowMinCol = new int[n];
            this.rowMaxCol = new int[n];
            this.colMinRow = new int[n];
            this.colMaxRow = new int[n];

            Arrays.fill(rowMinCol, -1);
            Arrays.fill(rowMaxCol, -1);
            Arrays.fill(colMinRow, -1);
            Arrays.fill(colMaxRow, -1);

            // Pre-calculate the boundaries of 'B' characters for each row and column
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (grid[i][j] == 'B') {
                        if (rowMinCol[i] == -1) rowMinCol[i] = j;
                        rowMaxCol[i] = j;

                        if (colMinRow[j] == -1) colMinRow[j] = i;
                        colMaxRow[j] = i;
                    }
                }
            }
        }

        /**
         * Solves the problem using a 2D Difference Array to find the optimal window position.
         */
        public int solve() {
            int baseCount = 0;

            // The top-left corner (r, c) of a k x k window can range from [0, n-k]
            int limit = n - k + 1;
            // diff array handles 2D range updates (Difference Array technique)
            int[][] diff = new int[limit + 1][limit + 1];

            // 1. Analyze Rows: Count empty rows and identify rows that can be "fixed"
            for (int i = 0; i < n; i++) {
                if (rowMinCol[i] == -1) {
                    baseCount++;
                } else {
                    int span = rowMaxCol[i] - rowMinCol[i] + 1;
                    if (span <= k) {
                        // A k x k window covers row i and all its 'B's if its top-left (r, c) satisfies:
                        // i - k + 1 <= r <= i
                        // rowMaxCol[i] - k + 1 <= c <= rowMinCol[i]
                        int rStart = Math.max(0, i - k + 1);
                        int rEnd = Math.min(n - k, i);
                        int cStart = Math.max(0, rowMaxCol[i] - k + 1);
                        int cEnd = Math.min(n - k, rowMinCol[i]);

                        if (rStart <= rEnd && cStart <= cEnd) {
                            applyRectUpdate(diff, rStart, cStart, rEnd, cEnd);
                        }
                    }
                }
            }

            // 2. Analyze Columns: Count empty columns and identify columns that can be "fixed"
            for (int j = 0; j < n; j++) {
                if (colMinRow[j] == -1) {
                    baseCount++;
                } else {
                    int span = colMaxRow[j] - colMinRow[j] + 1;
                    if (span <= k) {
                        // A k x k window covers col j and all its 'B's if its top-left (r, c) satisfies:
                        // j - k + 1 <= c <= j
                        // colMaxRow[j] - k + 1 <= r <= colMinRow[j]
                        int cStart = Math.max(0, j - k + 1);
                        int cEnd = Math.min(n - k, j);
                        int rStart = Math.max(0, colMaxRow[j] - k + 1);
                        int rEnd = Math.min(n - k, colMinRow[j]);

                        if (rStart <= rEnd && cStart <= cEnd) {
                            applyRectUpdate(diff, rStart, cStart, rEnd, cEnd);
                        }
                    }
                }
            }

            // 3. Compute 2D Prefix Sum to find the maximum number of additional rows/cols fixed
            int maxAdditional = 0;
            for (int i = 0; i < limit; i++) {
                for (int j = 0; j < limit; j++) {
                    if (i > 0) diff[i][j] += diff[i - 1][j];
                    if (j > 0) diff[i][j] += diff[i][j - 1];
                    if (i > 0 && j > 0) diff[i][j] -= diff[i - 1][j - 1];

                    maxAdditional = Math.max(maxAdditional, diff[i][j]);
                }
            }

            return baseCount + maxAdditional;
        }

        /**
         * Adds 1 to a sub-rectangle in the 2D difference array.
         */
        private void applyRectUpdate(int[][] diff, int r1, int c1, int r2, int c2) {
            diff[r1][c1]++;
            if (c2 + 1 < diff[0].length) diff[r1][c2 + 1]--;
            if (r2 + 1 < diff.length) diff[r2 + 1][c1]--;
            if (r2 + 1 < diff.length && c2 + 1 < diff[0].length) diff[r2 + 1][c2 + 1]++;
        }
    }

    /**
     * Utility class for fast I/O operations.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * A refactored solution for processing a grid of characters to find 
 * optimal window-based containment sums.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        GridProblemSolver solver = new GridProblemSolver();
        solver.solve(reader, writer);

        writer.flush();
        writer.close();
    }

    /**
     * Core logic class for the grid problem.
     */
    static class GridProblemSolver {

        /**
         * Represents the range of 'B' characters in a row or column.
         */
        private static class Bounds {
            final int minIdx;
            final int maxIdx;
            final boolean hasB;

            Bounds(int minIdx, int maxIdx, boolean hasB) {
                this.minIdx = minIdx;
                this.maxIdx = maxIdx;
                this.hasB = hasB;
            }

            boolean isContained(int start, int end) {
                return hasB && minIdx >= start && maxIdx <= end;
            }
        }

        public void solve(FastReader in, PrintWriter out) {
            int n = in.nextInt();
            int k = in.nextInt();
            String[] grid = new String[n];
            for (int i = 0; i < n; i++) {
                grid[i] = in.next();
            }

            // 1. Calculate bounds for rows and columns
            Bounds[] rowBounds = calculateRowBounds(grid, n);
            Bounds[] colBounds = calculateColBounds(grid, n);

            // 2. Count rows and columns that contain no 'B'
            int emptyCount = countEmptyLines(rowBounds) + countEmptyLines(colBounds);

            // 3. Calculate the 2D window matrices
            // vr[i][j] = number of rows in window [i, i+k-1] contained in column window [j, j+k-1]
            int[][] rowWindowMatrix = calculateWindowMatrix(n, k, rowBounds, true);
            // vc[i][j] = number of columns in window [j, j+k-1] contained in row window [i, i+k-1]
            int[][] colWindowMatrix = calculateWindowMatrix(n, k, colBounds, false);

            // 4. Find the maximum sum of the two matrices
            int maxCombinedSum = 0;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    maxCombinedSum = Math.max(maxCombinedSum, rowWindowMatrix[i][j] + colWindowMatrix[i][j]);
                }
            }

            out.print(maxCombinedSum + emptyCount);
        }

        private Bounds[] calculateRowBounds(String[] grid, int n) {
            Bounds[] bounds = new Bounds[n];
            for (int i = 0; i < n; i++) {
                int first = -1;
                int last = -1;
                for (int j = 0; j < n; j++) {
                    if (grid[i].charAt(j) == 'B') {
                        if (first == -1) first = j;
                        last = j;
                    }
                }
                bounds[i] = new Bounds(first, last, first != -1);
            }
            return bounds;
        }

        private Bounds[] calculateColBounds(String[] grid, int n) {
            Bounds[] bounds = new Bounds[n];
            for (int j = 0; j < n; j++) {
                int first = -1;
                int last = -1;
                for (int i = 0; i < n; i++) {
                    if (grid[i].charAt(j) == 'B') {
                        if (first == -1) first = i;
                        last = i;
                    }
                }
                bounds[j] = new Bounds(first, last, first != -1);
            }
            return bounds;
        }

        private int countEmptyLines(Bounds[] bounds) {
            int count = 0;
            for (Bounds b : bounds) {
                if (!b.hasB) count++;
            }
            return count;
        }

        /**
         * Computes a window sum matrix.
         * If isRowMode is true: returns vr[row_window_start][col_window_start]
         * If isRowMode is false: returns vc[row_window_start][col_window_start]
         */
        private int[][] calculateWindowMatrix(int n, int k, Bounds[] bounds, boolean isRowMode) {
            int[][] matrix = new int[n][n];

            if (isRowMode) {
                // Process column-by-column windowing
                for (int colWinStart = 0; colWinStart <= n - k; colWinStart++) {
                    int colWinEnd = colWinStart + k - 1;
                    int[] rowContained = new int[n];
                    for (int r = 0; r < n; r++) {
                        rowContained[r] = bounds[r].isContained(colWinStart, colWinEnd) ? 1 : 0;
                    }
                    fillSlidingWindow(matrix, rowContained, colWinStart, n, k, true);
                }
            } else {
                // Process row-by-row windowing
                for (int rowWinStart = 0; rowWinStart <= n - k; rowWinStart++) {
                    int rowWinEnd = rowWinStart + k - 1;
                    int[] colContained = new int[n];
                    for (int c = 0; c < n; c++) {
                        colContained[c] = bounds[c].isContained(rowWinStart, rowWinEnd) ? 1 : 0;
                    }
                    fillSlidingWindow(matrix, colContained, rowWinStart, n, k, false);
                }
            }
            return matrix;
        }

        private void fillSlidingWindow(int[][] matrix, int[] containedFlags, int fixedIdx, int n, int k, boolean isRowMode) {
            int currentSum = 0;
            // Initialize first window
            for (int i = 0; i < k - 1; i++) {
                currentSum += containedFlags[i];
            }
            // Slide the window
            for (int i = 0; i <= n - k; i++) {
                currentSum += containedFlags[i + k - 1];
                if (isRowMode) {
                    matrix[i][fixedIdx] = currentSum;
                } else {
                    matrix[fixedIdx][i] = currentSum;
                }
                currentSum -= containedFlags[i];
            }
        }
    }

    /**
     * High-performance input reader.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedOutputStream;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Problem: Maximize the number of full rows and columns by painting a k x k square black.
 * Approach: O(n^2) using prefix sums and sliding windows.
 */
public class Round578D {

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        PrintWriter writer = new PrintWriter(new BufferedOutputStream(System.out));

        int n = reader.nextInt();
        int k = reader.nextInt();
        char[][] grid = new char[n][n];
        for (int i = 0; i < n; i++) {
            grid[i] = reader.next().toCharArray();
        }

        FencePainter solver = new FencePainter(n, k, grid);
        writer.println(solver.solve());
        writer.close();
    }

    static class FencePainter {
        private final int n;
        private final int k;
        private final char[][] grid;

        public FencePainter(int n, int k, char[][] grid) {
            this.n = n;
            this.k = k;
            this.grid = grid;
        }

        public int solve() {
            int[][] rowPrefixSums = computePrefixSums(grid, true);
            int[][] colPrefixSums = computePrefixSums(grid, false);

            boolean[] isRowFull = new boolean[n];
            boolean[] isColFull = new boolean[n];
            int alreadyFullRows = 0;
            int alreadyFullCols = 0;

            for (int i = 0; i < n; i++) {
                if (rowPrefixSums[i][n] == n) {
                    isRowFull[i] = true;
                    alreadyFullRows++;
                }
                if (colPrefixSums[i][n] == n) {
                    isColFull[i] = true;
                    alreadyFullCols++;
                }
            }

            // rowGain[i][c] = 1 if row i becomes full when the k-width window is at [c, c+k-1]
            // and row i was not already full.
            int[][] rowGain = new int[n][n - k + 1];
            for (int i = 0; i < n; i++) {
                if (!isRowFull[i]) {
                    int totalBlackInRow = rowPrefixSums[i][n];
                    for (int c = 0; c <= n - k; c++) {
                        int blackInWindow = rowPrefixSums[i][c + k] - rowPrefixSums[i][c];
                        if (blackInWindow == totalBlackInRow) {
                            rowGain[i][c] = 1;
                        }
                    }
                }
            }

            // colGain[j][r] = 1 if col j becomes full when the k-height window is at [r, r+k-1]
            // and col j was not already full.
            int[][] colGain = new int[n][n - k + 1];
            for (int j = 0; j < n; j++) {
                if (!isColFull[j]) {
                    int totalBlackInCol = colPrefixSums[j][n];
                    for (int r = 0; r <= n - k; r++) {
                        int blackInWindow = colPrefixSums[j][r + k] - colPrefixSums[j][r];
                        if (blackInWindow == totalBlackInCol) {
                            colGain[j][r] = 1;
                        }
                    }
                }
            }

            int maxScore = 0;
            // For every possible top-left corner (r, c) of the k x k square
            for (int c = 0; c <= n - k; c++) {
                // Calculate additional rows gained for this column window 'c'
                // using a sliding window over the rows 'r'
                int currentAdditionalRows = 0;
                for (int i = 0; i < k; i++) {
                    currentAdditionalRows += rowGain[i][c];
                }

                for (int r = 0; r <= n - k; r++) {
                    // We also need to calculate additional columns gained for this row window 'r'
                    // This part is slightly trickier to do in the same loop without increasing complexity.
                    // However, we can calculate the column gain separately or pre-calculate.
                    // Let's use a pre-calculated column-gain sum.
                }
            }

            // To keep it O(n^2), let's refine the iteration
            int[][] scoreMatrix = new int[n - k + 1][n - k + 1];

            // Add row gains to scoreMatrix
            for (int c = 0; c <= n - k; c++) {
                int windowSum = 0;
                for (int i = 0; i < k; i++) windowSum += rowGain[i][c];
                scoreMatrix[0][c] += windowSum;
                for (int r = 1; r <= n - k; r++) {
                    windowSum = windowSum - rowGain[r - 1][c] + rowGain[r + k - 1][c];
                    scoreMatrix[r][c] += windowSum;
                }
            }

            // Add col gains to scoreMatrix
            for (int r = 0; r <= n - k; r++) {
                int windowSum = 0;
                for (int j = 0; j < k; j++) windowSum += colGain[j][r];
                scoreMatrix[r][0] += windowSum;
                for (int c = 1; c <= n - k; c++) {
                    windowSum = windowSum - colGain[c - 1][r] + colGain[c + k - 1][r];
                    scoreMatrix[r][c] += windowSum;
                }
            }

            // Find max in scoreMatrix
            for (int r = 0; r <= n - k; r++) {
                for (int c = 0; c <= n - k; c++) {
                    maxScore = Math.max(maxScore, scoreMatrix[r][c] + alreadyFullRows + alreadyFullCols);
                }
            }

            return maxScore;
        }

        /**
         * Computes prefix sums for rows or columns.
         * @param isRow If true, computes row-wise prefix sums. If false, column-wise.
         * @return 2D array where result[i][j] is sum of black cells in range [0, j)
         */
        private int[][] computePrefixSums(char[][] grid, boolean isRow) {
            int[][] prefixSums = new int[n][n + 1];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    int val = 0;
                    if (isRow) {
                        val = (grid[i][j] == 'B') ? 1 : 0;
                    } else {
                        val = (grid[j][i] == 'B') ? 1 : 0;
                    }
                    prefixSums[i][j + 1] = prefixSums[i][j] + val;
                }
            }
            return prefixSums;
        }
    }

    static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (Exception e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * GridWindowMaximizer solves a problem where we need to find a k x k subgrid 
 * that maximizes the number of "effectively complete" rows and columns.
 * 
 * A row or column is considered "effectively complete" if:
 * 1. It consists entirely of 'W' (walls).
 * 2. All of its non-'W' cells are contained within the boundaries of the k x k window.
 * 
 * The complexity is O(N^2) time and O(N^2) space.
 */
public class GridWindowMaximizer {

    private static final char WALL_CHAR = 'W';

    public static void main(String[] args) {
        FastReader reader = new FastReader();

        try {
            int n = reader.nextInt();
            int k = reader.nextInt();

            char[][] grid = new char[n][n];
            for (int i = 0; i < n; i++) {
                String line = reader.next();
                grid[i] = line.toCharArray();
            }

            System.out.println(solve(n, k, grid));
        } catch (Exception e) {
            // In a real production environment, use a logger.
            e.printStackTrace();
        }
    }

    /**
     * Core logic to find the maximum score for any k x k window.
     */
    private static int solve(int n, int k, char[][] grid) {
        int[] rowMinCol = new int[n];
        int[] rowMaxCol = new int[n];
        int[] colMinRow = new int[n];
        int[] colMaxRow = new int[n];

        // Initialize boundaries
        for (int i = 0; i < n; i++) {
            rowMinCol[i] = -1;
            rowMaxCol[i] = -1;
            colMinRow[i] = -1;
            colMaxRow[i] = -1;
        }

        // Step 1: Identify the boundaries of non-wall cells for every row and column
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] != WALL_CHAR) {
                    // Update Row boundaries
                    if (rowMinCol[i] == -1) rowMinCol[i] = j;
                    rowMaxCol[i] = j;

                    // Update Column boundaries
                    if (colMinRow[j] == -1) colMinRow[j] = i;
                    colMaxRow[j] = i;
                }
            }
        }

        // Step 2: Count existing "entirely-wall" rows and columns
        int emptyRowsAndColsBaseScore = 0;
        for (int i = 0; i < n; i++) {
            if (rowMinCol[i] == -1) emptyRowsAndColsBaseScore++;
            if (colMinRow[i] == -1) emptyRowsAndColsBaseScore++;
        }

        // Step 3: Calculate coverage scores using suffix sums.
        // rowScoreSum[i][j] stores the number of rows in range [i, N-1] 
        // that are fully contained within the column window starting at j.
        int[][] rowScoreSum = new int[n + 1][n];
        // colScoreSum[j][i] stores the number of columns in range [j, N-1] 
        // that are fully contained within the row window starting at i.
        int[][] colScoreSum = new int[n][n + 1];

        // Pre-calculate rowScoreSum (rows contained in a width k window)
        for (int j = 0; j <= n - k; j++) {
            for (int i = n - 1; i >= 0; i--) {
                int isContained = 0;
                if (rowMinCol[i] != -1 && rowMinCol[i] >= j && rowMaxCol[i] < j + k) {
                    isContained = 1;
                }
                rowScoreSum[i][j] = isContained + rowScoreSum[i + 1][j];
            }
        }

        // Pre-calculate colScoreSum (cols contained in a height k window)
        for (int i = 0; i <= n - k; i++) {
            for (int j = n - 1; j >= 0; j--) {
                int isContained = 0;
                if (colMinRow[j] != -1 && colMinRow[j] >= i && colMaxRow[j] < i + k) {
                    isContained = 1;
                }
                colScoreSum[j][i] = isContained + (j == n - 1 ? 0 : colScoreSum[j + 1][i]);
            }
        }

        // Step 4: Find the k x k window that maximizes the additional score
        int maxWindowScore = 0;
        for (int i = 0; i <= n - k; i++) {
            for (int j = 0; j <= n - k; j++) {
                // rowsInWindow: number of non-empty rows in row-range [i, i+k-1] 
                // that fit in column-range [j, j+k-1]
                int rowsInWindow = rowScoreSum[i][j] - rowScoreSum[i + k][j];

                // colsInWindow: number of non-empty columns in col-range [j, j+k-1] 
                // that fit in row-range [i, i+k-1]
                int colsInWindow = colScoreSum[j][i] - (j + k < n ? colScoreSum[j + k][i] : 0);

                maxWindowScore = Math.max(maxWindowScore, rowsInWindow + colsInWindow);
            }
        }

        return maxWindowScore + emptyRowsAndColsBaseScore;
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Problem Solver for the "White Lines" problem.
 * The goal is to find a k x k window that maximizes the number of "white" lines.
 * A line (row or column) is white if it either contains no black cells ('B')
 * or if all its black cells are contained within the k-length window.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int n = reader.nextInt();
            int k = reader.nextInt();
            char[][] gridData = new char[n][n];

            for (int i = 0; i < n; i++) {
                String line = reader.next();
                for (int j = 0; j < n; j++) {
                    gridData[i][j] = line.charAt(j);
                }
            }

            ProblemSolver solver = new ProblemSolver(n, k, new Grid(gridData));
            writer.println(solver.solve());
        } catch (Exception e) {
            // In a production environment, use a proper logging framework
        } finally {
            writer.close();
        }
    }

    /**
     * Represents the game grid and provides utility methods for prefix sums.
     */
    static class Grid {
        private final int n;
        private final char[][] cells;
        private final int[][] rowPrefixSums;
        private final int[][] colPrefixSums;
        private final int[] rowHasBlackCount;
        private final int[] colHasBlackCount;

        public Grid(char[][] cells) {
            this.n = cells.length;
            this.cells = cells;
            this.rowPrefixSums = new int[n][n + 1];
            this.colPrefixSums = new int[n + 1][n];
            this.rowHasBlackCount = new int[n + 1];
            this.colHasBlackCount = new int[n + 1];
            computePrefixSums();
        }

        private void computePrefixSums() {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    boolean isBlack = (cells[i][j] == 'B');
                    rowPrefixSums[i][j + 1] = rowPrefixSums[i][j] + (isBlack ? 1 : 0);
                    colPrefixSums[i + 1][j] = colPrefixSums[i][j] + (isBlack ? 1 : 0);
                }
                rowHasBlackCount[i + 1] = rowHasBlackCount[i] + (rowPrefixSums[i][n] > 0 ? 1 : 0);
            }

            for (int j = 0; j < n; j++) {
                colHasBlackCount[j + 1] = colHasBlackCount[j] + (colPrefixSums[n][j] > 0 ? 1 : 0);
            }
        }

        public int getN() { return n; }

        public int getRowBlackCountInRange(int row, int colStart, int colEnd) {
            return rowPrefixSums[row][colEnd + 1] - rowPrefixSums[row][colStart];
        }

        public int getTotalRowBlackCount(int row) {
            return rowPrefixSums[row][n];
        }

        public int getColBlackCountInRange(int col, int rowStart, int rowEnd) {
            return colPrefixSums[rowEnd + 1][col] - colPrefixSums[rowStart][col];
        }

        public int getTotalColBlackCount(int col) {
            return colPrefixSums[n][col + 1] - colPrefixSums[0][col + 1]; // Equivalent to colPrefixSums[n][col] check logic
        }

        // The original logic used the total sum in a column via cpre[n][j].
        // In 0-indexed, that's colPrefixSums[n][j] - colPrefixSums[0][j].
        public int getTotalBlackInColumn(int col) {
            return colPrefixSums[n][col];
        }

        public int getRowsWithBlackUpTo(int index) {
            return rowHasBlackCount[index + 1];
        }

        public int getRowsWithBlackUpTo(int index, boolean inclusive) {
            return rowHasBlackCount[index];
        }

        public int getRowsWithBlackInRange(int start, int end) {
            if (start > end) return 0;
            return rowHasBlackCount[end + 1] - rowHasBlackCount[start];
        }

        public int getColsWithBlackInRange(int start, int end) {
            if (start > end) return 0;
            return colHasBlackCount[end + 1] - colHasBlackCount[start];
        }

        public int getRowsWithBlackCount() {
            return rowHasBlackCount[n];
        }

        public int getColsWithBlackCount() {
            return colHasBlackCount[n];
        }
    }

    /**
     * Contains the algorithm to solve the problem.
     */
    static class ProblemSolver {
        private final int n;
        private final int k;
        private final Grid grid;

        public ProblemSolver(int n, int k, Grid grid) {
            this.n = n;
            this.k = k;
            this.grid = grid;
        }

        public long solve() {
            int[][] invalidRowsInWindow = calculateInvalidRowsInWindow();
            int[][] invalidColsInWindow = calculateInvalidColsInWindow();

            long maxScore = 0;
            for (int i = k - 1; i < n; i++) {
                for (int j = k - 1; j < n; j++) {
                    // Calculate how many rows are "good"
                    // Good rows = (Rows in window that are valid) + (Rows outside window that have no 'B')
                    int validRowsInWindow = k - invalidRowsInWindow[i][j];
                    int rowsOutsideWithBlack = grid.getRowsWithBlackInRange(0, i - k) 
                                             + grid.getRowsWithBlackInRange(i + 1, n - 1);
                    int rowsOutsideWithoutBlack = (n - k) - rowsOutsideWithBlack;
                    // Wait, the original logic used: (n - invalid_in_window) - (black_rows_outside_window)
                    // Let's replicate that logic exactly to maintain correctness.
                    long rowScore = (long) n - invalidRowsInWindow[i][j] - rowsOutsideWithBlack;

                    // Calculate how many columns are "good"
                    int invalidColsInWindowCount = invalidColsInWindow[i][j];
                    int colsOutsideWithBlack = grid.getColsWithBlackInRange(0, j - k) 
                                             + grid.getColsWithBlackInRange(j + 1, n - 1);
                    long colScore = (long) n - invalidColsInWindowCount - colsOutsideWithBlack;

                    maxScore = Math.max(maxScore, rowScore + colScore);
                }
            }
            return maxScore;
        }

        private int[][] calculateInvalidRowsInWindow() {
            int[][] dp = new int[n][n];
            for (int j = k - 1; j < n; j++) {
                int currentInvalidCount = 0;
                // Initial window for rows [0, k-1]
                for (int i = 0; i < k; i++) {
                    if (grid.getRowBlackCountInRange(i, j - k + 1, j) != grid.getTotalRowBlackCount(i)) {
                        currentInvalidCount++;
                    }
                }
                dp[k - 1][j] = currentInvalidCount;

                // Sliding window for subsequent rows
                for (int i = k; i < n; i++) {
                    boolean newRowInvalid = grid.getRowBlackCountInRange(i, j - k + 1, j) != grid.getTotalRowBlackCount(i);
                    boolean oldRowInvalid = grid.getRowBlackCountInRange(i - k, j - k + 1, j) != grid.getTotalRowBlackCount(i - k);

                    dp[i][j] = dp[i - 1][j] + (newRowInvalid ? 1 : 0) - (oldRowInvalid ? 1 : 0);
                }
            }
            return dp;
        }

        private int[][] calculateInvalidColsInWindow() {
            int[][] dp = new int[n][n];
            for (int i = k - 1; i < n; i++) {
                int currentInvalidCount = 0;
                // Initial window for cols [0, k-1]
                for (int j = 0; j < k; j++) {
                    if (grid.getColBlackCountInRange(j, i - k + 1, i) != grid.getTotalBlackInColumn(j)) {
                        currentInvalidCount++;
                    }
                }
                dp[i][k - 1] = currentInvalidCount;

                // Sliding window for subsequent columns
                for (int j = k; j < n; j++) {
                    boolean newColInvalid = grid.getColBlackCountInRange(j, i - k + 1, i) != grid.getTotalBlackInColumn(j);
                    boolean oldColInvalid = grid.getColBlackCountInRange(j - k, i - k + 1, i) != grid.getTotalBlackInColumn(j - k);

                    dp[i][j] = dp[i][j - 1] + (newColInvalid ? 1 : 0) - (oldColInvalid ? 1 : 0);
                }
            }
            return dp;
        }
    }

    /**
     * High-performance input reader.
     */
    static class FastReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int pointer = 0;
        private int bufferLength = 0;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() {
            if (pointer >= bufferLength) {
                pointer = 0;
                try {
                    bufferLength = stream.read(buffer);
                } catch (IOException e) {
                    return -1;
                }
                if (bufferLength <= 0) return -1;
            }
            return buffer[pointer++];
        }

        public int nextInt() {
            int c = readByte();
            while (c != -1 && c <= 32) c = readByte();
            if (c == -1) return 0;
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            int res = 0;
            while (c > 32) {
                res = res * 10 + (c - '0');
                c = readByte();
            }
            return res * sign;
        }

        public String next() {
            int c = readByte();
            while (c != -1 && c <= 32) c = readByte();
            if (c == -1) return null;
            StringBuilder sb = new StringBuilder();
            while (c > 32) {
                sb.append((char) c);
                c = readByte();
            }
            return sb.toString();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solution for Codeforces 1200D.
 * The problem asks to find a k x k square that maximizes the number of covered rows and columns.
 * A row/column is covered if all its black cells ('B') are contained within the square's range.
 * Empty rows/columns are always considered covered.
 */
public class Codeforces1200D {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        int n = reader.nextInt();
        int k = reader.nextInt();

        if (n == 0) {
            System.out.println(0);
            return;
        }

        boolean[][] isWhite = readGrid(reader, n);
        solve(n, k, isWhite);
    }

    private static boolean[][] readGrid(FastReader reader, int n) {
        boolean[][] grid = new boolean[n][n];
        for (int i = 0; i < n; i++) {
            String line = reader.next();
            for (int j = 0; j < n; j++) {
                if (line.charAt(j) == 'W') {
                    grid[i][j] = true;
                }
            }
        }
        return grid;
    }

    private static void solve(int n, int k, boolean[][] isWhite) {
        int emptyCount = 0;

        // rowCoverage[i][j] == 1 if the segment of length k in row i starting at column j covers all 'B's
        int[][] rowCoverage = new int[n][n - k + 1];
        for (int i = 0; i < n; i++) {
            int firstBlack = -1;
            int lastBlack = -1;
            for (int j = 0; j < n; j++) {
                if (!isWhite[i][j]) { // It's a black cell
                    if (firstBlack == -1) firstBlack = j;
                    lastBlack = j;
                }
            }

            if (firstBlack == -1) {
                emptyCount++; // Row has no black cells, always covered
            } else {
                // A segment starting at 'j' covers all black cells if:
                // j <= firstBlack AND j + k - 1 >= lastBlack
                int startRange = Math.max(0, lastBlack - k + 1);
                int endRange = Math.min(n - k, firstBlack);
                for (int j = startRange; j <= endRange; j++) {
                    rowCoverage[i][j] = 1;
                }
            }
        }

        // colCoverage[i][j] == 1 if the segment of length k in column j starting at row i covers all 'B's
        int[][] colCoverage = new int[n - k + 1][n];
        for (int j = 0; j < n; j++) {
            int firstBlack = -1;
            int lastBlack = -1;
            for (int i = 0; i < n; i++) {
                if (!isWhite[i][j]) {
                    if (firstBlack == -1) firstBlack = i;
                    lastBlack = i;
                }
            }

            if (firstBlack == -1) {
                emptyCount++; // Column has no black cells, always covered
            } else {
                int startRange = Math.max(0, lastBlack - k + 1);
                int endRange = Math.min(n - k, firstBlack);
                for (int i = startRange; i <= endRange; i++) {
                    colCoverage[i][j] = 1;
                }
            }
        }

        // rowWindowSum[i][j] = number of rows in the k-range [i, i+k-1] covered by column-segment starting at j
        int[][] rowWindowSum = new int[n - k + 1][n - k + 1];
        for (int col = 0; col < n - k + 1; col++) {
            int currentSum = 0;
            for (int row = 0; row < k; row++) {
                currentSum += rowCoverage[row][col];
            }
            rowWindowSum[0][col] = currentSum;
            for (int row = 1; row < n - k + 1; row++) {
                currentSum = currentSum - rowCoverage[row - 1][col] + rowCoverage[row + k - 1][col];
                rowWindowSum[row][col] = currentSum;
            }
        }

        // colWindowSum[i][j] = number of columns in the k-range [j, j+k-1] covered by row-segment starting at i
        int[][] colWindowSum = new int[n - k + 1][n - k + 1];
        for (int row = 0; row < n - k + 1; row++) {
            int currentSum = 0;
            for (int col = 0; col < k; col++) {
                currentSum += colCoverage[row][col];
            }
            colWindowSum[row][0] = currentSum;
            for (int col = 1; col < n - k + 1; col++) {
                currentSum = currentSum - colCoverage[row][col - 1] + colCoverage[row][col + k - 1];
                colWindowSum[row][col] = currentSum;
            }
        }

        int maxCovered = 0;
        for (int i = 0; i < n - k + 1; i++) {
            for (int j = 0; j < n - k + 1; j++) {
                maxCovered = Math.max(maxCovered, rowWindowSum[i][j] + colWindowSum[i][j]);
            }
        }

        System.out.println(maxCovered + emptyCount);
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A solver for the grid satisfaction problem.
 * The goal is to find a square of size m x m that maximizes the number of 
 * "satisfied" rows and columns. A row or column is satisfied if it contains 
 * no 'B' characters, or if all 'B' characters in it are contained within 
 * the window of the square.
 */
public class GridSatisfier {

    private final int gridSize;
    private final int windowSize;
    private final char[][] grid;

    public GridSatisfier(int gridSize, int windowSize, char[][] grid) {
        this.gridSize = gridSize;
        this.windowSize = windowSize;
        this.grid = grid;
    }

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = reader.nextInt();
            int m = reader.nextInt();
            char[][] grid = new char[n][n];

            for (int i = 0; i < n; i++) {
                grid[i] = reader.readLine().trim().toCharArray();
            }

            GridSatisfier solver = new GridSatisfier(n, m, grid);
            out.println(solver.solve());
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        } finally {
            out.close();
        }
    }

    /**
     * Solves the problem by calculating empty rows/cols and the maximum
     * non-empty rows/cols that can be satisfied by a single m x m square.
     * 
     * @return The maximum number of satisfied rows and columns.
     */
    public int solve() {
        int emptyCount = 0;
        int[][] rowSatisfaction = new int[gridSize][gridSize + 1];
        int[][] colSatisfaction = new int[gridSize][gridSize + 1];

        // 1. Process Rows
        for (int r = 0; r < gridSize; r++) {
            int firstB = -1;
            int lastB = -1;

            for (int c = 0; c < gridSize; c++) {
                if (grid[r][c] == 'B') {
                    if (firstB == -1) firstB = c;
                    lastB = c;
                }
            }

            if (firstB == -1) {
                emptyCount++; // Row is always satisfied
            } else if (lastB - firstB < windowSize) {
                // Row can be satisfied if the square's column window covers [firstB, lastB]
                int startColWindow = Math.max(0, lastB - windowSize + 1);
                int endColWindow = Math.min(gridSize - windowSize, firstB);

                // If such a window exists, any square starting at row [r-m+1, r] 
                // and column [startColWindow, endColWindow] satisfies this row.
                int startRowWindow = Math.max(0, r - windowSize + 1);
                int endRowWindow = r;

                for (int sqR = startRowWindow; sqR <= endRowWindow; sqR++) {
                    rowSatisfaction[sqR][startColWindow]++;
                    rowSatisfaction[sqR][endColWindow + 1]--;
                }
            }
        }

        // 2. Process Columns
        for (int c = 0; c < gridSize; c++) {
            int firstB = -1;
            int lastB = -1;

            for (int r = 0; r < gridSize; r++) {
                if (grid[r][c] == 'B') {
                    if (firstB == -1) firstB = r;
                    lastB = r;
                }
            }

            if (firstB == -1) {
                emptyCount++; // Column is always satisfied
            } else if (lastB - firstB < windowSize) {
                int startRowWindow = Math.max(0, lastB - windowSize + 1);
                int endRowWindow = Math.min(gridSize - windowSize, firstB);

                int startColWindow = Math.max(0, c - windowSize + 1);
                int endColWindow = c;

                for (int sqC = startColWindow; sqC <= endColWindow; sqC++) {
                    colSatisfaction[sqC][startRowWindow]++;
                    colSatisfaction[sqC][endRowWindow + 1]--;
                }
            }
        }

        // 3. Compute prefix sums for the difference arrays
        for (int i = 0; i < gridSize; i++) {
            for (int j = 1; j < gridSize; j++) {
                rowSatisfaction[i][j] += rowSatisfaction[i][j - 1];
                colSatisfaction[i][j] += colSatisfaction[i][j - 1];
            }
        }

        // 4. Find the maximum satisfaction
        int maxNonEmptySatisfied = 0;
        for (int r = 0; r <= gridSize - windowSize; r++) {
            for (int c = 0; c <= gridSize - windowSize; c++) {
                // Satisfaction at square (r, c) is rows satisfied + columns satisfied
                int currentSatisfaction = rowSatisfaction[r][c] + colSatisfaction[c][r];
                maxNonEmptySatisfied = Math.max(maxNonEmptySatisfied, currentSatisfaction);
            }
        }

        return emptyCount + maxNonEmptySatisfied;
    }

    /**
     * Fast I/O Utility.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String readLine() throws IOException {
            return reader.readLine();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A refactored solution for the "White Lines" problem.
 * The goal is to find a k x k window in a grid of 'W' (White) and other characters
 * that maximizes a specific scoring metric based on white lines (rows and columns).
 */
public class Main {

    public static void main(String[] args) {
        try (InputStream inputStream = System.in;
             OutputStream outputStream = System.out) {

            FastReader reader = new FastReader(inputStream);
            FastWriter writer = new FastWriter(outputStream);

            int n = reader.readInt();
            int k = reader.readInt();
            String[] grid = reader.readStringArray(n);

            WhiteLinesSolver solver = new WhiteLinesSolver(n, k, grid);
            writer.printLine(solver.solve());

        } catch (IOException e) {
            // In a real-world scenario, use a logger
        }
    }

    /**
     * Encapsulates the logic for solving the White Lines problem.
     */
    static class WhiteLinesSolver {
        private final int n;
        private final int k;
        private final String[] grid;

        private int totalAllWhiteRowsAndCols = 0;
        private int[] rowAllWhitePrefixSum;
        private int[] colAllWhitePrefixSum;

        // Prefix AND arrays to check if segments are all 'W'
        private boolean[][] rowPrefixWhite;
        private boolean[][] rowSuffixWhite;
        private boolean[][] colPrefixWhite;
        private boolean[][] colSuffixWhite;

        // Prefix sum arrays for "mostly white" rows and columns within windows
        private int[][] rowMostlyWhitePrefixSumByCol; // [column][row]
        private int[][] colMostlyWhitePrefixSumByRow; // [row][column]

        public WhiteLinesSolver(int n, int k, String[] grid) {
            this.n = n;
            this.k = k;
            this.grid = grid;
        }

        public int solve() {
            computeAllWhiteRowsAndCols();
            computePrefixAnds();
            computeMostlyWhitePrefixSums();

            return findMaxWindowScore();
        }

        /**
         * Precomputes the total count of all-white rows and columns in the entire grid,
         * along with their respective prefix sums for O(1) range queries.
         */
        private void computeAllWhiteRowsAndCols() {
            rowAllWhitePrefixSum = new int[n + 1];
            colAllWhitePrefixSum = new int[n + 1];

            for (int i = 0; i < n; i++) {
                boolean allWhiteRow = true;
                for (int j = 0; j < n; j++) {
                    if (grid[i].charAt(j) != 'W') {
                        allWhiteRow = false;
                        break;
                    }
                }
                if (allWhiteRow) {
                    rowAllWhitePrefixSum[i + 1] = 1;
                    totalAllWhiteRowsAndCols++;
                }
            }

            for (int j = 0; j < n; j++) {
                boolean allWhiteCol = true;
                for (int i = 0; i < n; i++) {
                    if (grid[i].charAt(j) != 'W') {
                        allWhiteCol = false;
                        break;
                    }
                }
                if (allWhiteCol) {
                    colAllWhitePrefixSum[j + 1] = 1;
                    totalAllWhiteRowsAndCols++;
                }
            }

            for (int i = 1; i <= n; i++) {
                rowAllWhitePrefixSum[i] += rowAllWhitePrefixSum[i - 1];
                colAllWhitePrefixSum[i] += colAllWhitePrefixSum[i - 1];
            }
        }

        /**
         * Precomputes prefix and suffix ANDs to determine if any segment in a row or column is all 'W'.
         */
        private void computePrefixAnds() {
            // We use padding (n+2) to simplify boundary checks
            rowPrefixWhite = new boolean[n + 2][n + 2];
            rowSuffixWhite = new boolean[n + 2][n + 2];
            colPrefixWhite = new boolean[n + 2][n + 2];
            colSuffixWhite = new boolean[n + 2][n + 2];

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    boolean isWhite = grid[i].charAt(j) == 'W';
                    rowPrefixWhite[i + 1][j + 1] = isWhite;
                    colPrefixWhite[j + 1][i + 1] = isWhite;
                }
            }

            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    rowPrefixWhite[i][j] &= rowPrefixWhite[i][j - 1];
                    colPrefixWhite[j][i] &= colPrefixWhite[j][i - 1];
                }
            }

            // Suffix ANDs (Right-to-Left and Bottom-to-Top)
            for (int i = 1; i <= n; i++) {
                for (int j = n; j >= 1; j--) {
                    rowSuffixWhite[i][j] = rowPrefixWhite[i][j] && (j == n || rowSuffixWhite[i][j + 1]);
                    // Note: The original logic used suffix logic, let's replicate it more cleanly.
                }
            }
            // Re-calculating suffix correctly
            for (int i = 1; i <= n; i++) {
                for (int j = n; j >= 1; j--) {
                    boolean isWhite = grid[i - 1].charAt(j - 1) == 'W';
                    rowSuffixWhite[i][j] = isWhite && (j == n ? true : rowSuffixWhite[i][j + 1]);
                }
            }
            for (int j = 1; j <= n; j++) {
                for (int i = n; i >= 1; i--) {
                    boolean isWhite = grid[i - 1].charAt(j - 1) == 'W';
                    colSuffixWhite[j][i] = isWhite && (i == n ? true : colSuffixWhite[j][i + 1]);
                }
            }
        }

        /**
         * Precomputes prefix sums of rows/cols that are "mostly white" (white outside the k-length segment).
         */
        private void computeMostlyWhitePrefixSums() {
            rowMostlyWhitePrefixSumByCol = new int[n + 2][n + 2];
            colMostlyWhitePrefixSumByRow = new int[n + 2][n + 2];

            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    if (j + k <= n + 1) {
                        // Row i is white on [1, j-1] AND on [j+k, n]
                        if (rowPrefixWhite[i][j - 1] && rowSuffixWhite[i][j + k]) {
                            rowMostlyWhitePrefixSumByCol[j][i] = 1;
                        }
                        // Col j is white on [1, i-1] AND on [i+k, n]
                        if (colPrefixWhite[j][i - 1] && colSuffixWhite[j][i + k]) {
                            colMostlyWhitePrefixSumByRow[i][j] = 1;
                        }
                    }
                }
            }

            // Prefix sum over rows for each column
            for (int j = 1; j <= n; j++) {
                for (int i = 1; i <= n; i++) {
                    rowMostlyWhitePrefixSumByCol[j][i] += rowMostlyWhitePrefixSumByCol[j][i - 1];
                }
            }
            // Prefix sum over rows for each column (for colMostlyWhite)
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    colMostlyWhitePrefixSumByRow[i][j] += colMostlyWhitePrefixSumByRow[i][j - 1];
                }
            }
            // Note: Based on the original code's specific indexing, we need to be careful.
            // Let's re-implement the prefix sum logic exactly as the original:
            // Original cnt[0] is prefix-summed over row index i.
            // Original cnt[1] is prefix-summed over col index j.
            // Re-doing the prefix sum step to be 100% sure.

            // Resetting and doing exactly what the original code did to ensure logic parity
            rowMostlyWhitePrefixSumByCol = new int[n + 2][n + 2];
            colMostlyWhitePrefixSumByRow = new int[n + 2][n + 2];

            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    if (j + k < n + 2) {
                        if (rowPrefixWhite[i][j - 1] && rowSuffixWhite[i][j + k]) {
                            rowMostlyWhitePrefixSumByCol[i][j] = 1;
                        }
                        if (colPrefixWhite[j][i - 1] && colSuffixWhite[j][i + k]) {
                            colMostlyWhitePrefixSumByRow[j][i] = 1;
                        }
                    }
                }
            }

            // Original cnt[0][j+1][i] += cnt[0][j][i] (where j is row, i is col)
            // This is: rowMostlyWhitePrefixSumByCol[row+1][col] += rowMostlyWhitePrefixSumByCol[row][col]
            for (int i = 0; i < n + 2; i++) {
                for (int j = 0; j < n + 1; j++) {
                    rowMostlyWhitePrefixSumByCol[j + 1][i] += rowMostlyWhitePrefixSumByCol[j][i];
                }
            }
            // Original cnt[1][i][j+1] += cnt[1][i][j] (where i is col, j is row)
            // This is: colMostlyWhitePrefixSumByRow[col][row+1] += colMostlyWhitePrefixSumByRow[col][row]
            for (int i = 0; i < n + 2; i++) {
                for (int j = 0; j < n + 1; j++) {
                    colMostlyWhitePrefixSumByRow[i][j + 1] += colMostlyWhitePrefixSumByRow[i][j];
                }
            }
        }

        /**
         * Iterates through all possible k x k windows to find the maximum score.
         */
        private int findMaxWindowScore() {
            int maxScore = 0;
            for (int i = 1; i <= n - k + 1; i++) {
                for (int j = 1; j <= n - k + 1; j++) {
                    // Score = (All white lines in grid) 
                    //         - (All white lines inside window) 
                    //         + (Mostly white rows in window) 
                    //         + (Mostly white cols in window)
                    int currentScore = totalAllWhiteRowsAndCols 
                                     - (rowAllWhitePrefixSum[i + k - 1] - rowAllWhitePrefixSum[i - 1] 
                                        + colAllWhitePrefixSum[j + k - 1] - colAllWhitePrefixSum[j - 1]);

                    currentScore += rowMostlyWhitePrefixSumByCol[i + k - 1][j] - rowMostlyWhitePrefixSumByCol[i - 1][j];
                    currentScore += colMostlyWhitePrefixSumByRow[i][j + k - 1] - colMostlyWhitePrefixSumByRow[i][j - 1];

                    maxScore = Math.max(maxScore, currentScore);
                }
            }
            return maxScore;
        }
    }

    /**
     * Efficient input reader for fast I/O.
     */
    static class FastReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int curChar;
        private int numChars;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (numChars == -1) throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buffer);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) return -1;
            }
            return buffer[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res = res * 10 + (c - '0');
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public String readString() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public String[] readStringArray(int size) {
            String[] arr = new String[size];
            for (int i = 0; i < size; i++) arr[i] = readString();
            return arr;
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }

    /**
     * Efficient output writer for fast I/O.
     */
    static class FastWriter {
        private final PrintWriter writer;

        public FastWriter(OutputStream outputStream) {
            this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public void printLine(int val) {
            writer.println(val);
            writer.flush();
        }

        public void close() {
            writer.close();
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A solver that calculates the maximum overlap of specific geometric constraints 
 * within a character grid using a 2D difference array approach.
 */
public class GridOverlapSolver {

    private static final char TARGET_CHAR = 'B';

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            int gridSize = reader.nextInt();
            int threshold = reader.nextInt();

            char[][] grid = new char[gridSize][gridSize];
            for (int i = 0; i < gridSize; i++) {
                grid[i] = reader.next().toCharArray();
            }

            GridOverlapSolver solver = new GridOverlapSolver(gridSize, threshold, grid);
            writer.println(solver.solve());

        } catch (Exception e) {
            // In a production environment, use a proper logging framework.
            e.printStackTrace();
        } finally {
            writer.flush();
            writer.close();
        }
    }

    private final int gridSize;
    private final int threshold;
    private final char[][] grid;
    private final int[][] differenceArray;

    public GridOverlapSolver(int gridSize, int threshold, char[][] grid) {
        this.gridSize = gridSize;
        this.threshold = threshold;
        this.grid = grid;
        // We use (n+1)x(n+1) to handle the boundary conditions of the 2D difference array.
        this.differenceArray = new int[gridSize + 1][gridSize + 1];
    }

    /**
     * Executes the main logic of the solver.
     * @return The maximum overlap value found in the grid.
     */
    public int solve() {
        applyRowConstraints();
        applyColumnConstraints();
        return computeMaxOverlap();
    }

    /**
     * Processes each row to find spans of the target character and updates the difference array.
     */
    private void applyRowConstraints() {
        for (int i = 0; i < gridSize; i++) {
            int firstOccurrence = gridSize;
            int lastOccurrence = -1;

            for (int j = 0; j < gridSize; j++) {
                if (grid[i][j] == TARGET_CHAR) {
                    lastOccurrence = j;
                    if (firstOccurrence == gridSize) {
                        firstOccurrence = j;
                    }
                }
            }

            if (firstOccurrence == gridSize) {
                // If no target character is found in the row, update the entire grid.
                updateRectangle(0, 0, gridSize - 1, gridSize - 1);
            } else {
                // If the span is within the threshold, apply the constraint to the valid region.
                if (lastOccurrence - firstOccurrence < threshold) {
                    int r1 = Math.max(0, i - threshold + 1);
                    int r2 = i;
                    int c1 = Math.max(0, lastOccurrence - threshold + 1);
                    int c2 = firstOccurrence;
                    updateRectangle(r1, c1, r2, c2);
                }
            }
        }
    }

    /**
     * Processes each column to find spans of the target character and updates the difference array.
     */
    private void applyColumnConstraints() {
        for (int j = 0; j < gridSize; j++) {
            int firstOccurrence = gridSize;
            int lastOccurrence = -1;

            for (int i = 0; i < gridSize; i++) {
                if (grid[i][j] == TARGET_CHAR) {
                    lastOccurrence = i;
                    if (firstOccurrence == gridSize) {
                        firstOccurrence = i;
                    }
                }
            }

            if (firstOccurrence == gridSize) {
                updateRectangle(0, 0, gridSize - 1, gridSize - 1);
            } else {
                if (lastOccurrence - firstOccurrence < threshold) {
                    int r1 = Math.max(0, lastOccurrence - threshold + 1);
                    int r2 = firstOccurrence;
                    int c1 = Math.max(0, j - threshold + 1);
                    int c2 = j;
                    updateRectangle(r1, c1, r2, c2);
                }
            }
        }
    }

    /**
     * Updates a rectangular region in the 2D difference array.
     */
    private void updateRectangle(int r1, int c1, int r2, int c2) {
        if (r1 > r2 || c1 > c2) return;

        differenceArray[r1][c1]++;
        if (c2 + 1 < gridSize + 1) differenceArray[r1][c2 + 1]--;
        if (r2 + 1 < gridSize + 1) differenceArray[r2 + 1][c1]--;
        if (r2 + 1 < gridSize + 1 && c2 + 1 < gridSize + 1) {
            differenceArray[r2 + 1][c2 + 1]++;
        }
    }

    /**
     * Computes the 2D prefix sum of the difference array and finds the maximum value.
     */
    private int computeMaxOverlap() {
        int maxVal = 0;
        for (int i = 0; i < gridSize; i++) {
            for (int j = 0; j < gridSize; j++) {
                int currentVal = differenceArray[i][j];
                if (i > 0) currentVal += differenceArray[i - 1][j];
                if (j > 0) currentVal += differenceArray[i][j - 1];
                if (i > 0 && j > 0) currentVal -= differenceArray[i - 1][j - 1];

                differenceArray[i][j] = currentVal;
                if (currentVal > maxVal) {
                    maxVal = currentVal;
                }
            }
        }
        return maxVal;
    }

    /**
     * Fast I/O helper class.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * This program finds the maximum number of rows and columns that can be 
 * fully "covered" by a square window of size K. 
 * A row or column is covered if all its 'B' characters fall within the window 
 * and the row/column index itself is within the window.
 */
public class GridWindowOptimizer {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        int gridSize = reader.nextInt();
        int windowSize = reader.nextInt();

        if (gridSize <= 0) {
            System.out.println(0);
            return;
        }

        char[][] grid = new char[gridSize][gridSize];
        for (int i = 0; i < gridSize; i++) {
            grid[i] = reader.next().toCharArray();
        }

        GridAnalyzer analyzer = new GridAnalyzer(gridSize, windowSize, grid);
        System.out.println(analyzer.calculateMaxCovered());
    }

    /**
     * Handles the core logic of analyzing the grid and calculating the optimal window.
     */
    static class GridAnalyzer {
        private final int n;
        private final int k;
        private final int[] rowMinCol;
        private final int[] rowMaxCol;
        private final int[] colMinRow;
        private final int[] colMaxRow;
        private int emptyRowsAndColsCount = 0;

        public GridAnalyzer(int n, int k, char[][] grid) {
            this.n = n;
            this.k = k;
            this.rowMinCol = new int[n];
            this.rowMaxCol = new int[n];
            this.colMinRow = new int[n];
            this.colMaxRow = new int[n];

            Arrays.fill(rowMinCol, Integer.MAX_VALUE);
            Arrays.fill(rowMaxCol, Integer.MIN_VALUE);
            Arrays.fill(colMinRow, Integer.MAX_VALUE);
            Arrays.fill(colMaxRow, Integer.MIN_VALUE);

            analyzeGrid(grid);
        }

        /**
         * Scans the grid to find the bounding boxes for 'B' characters in every row and column.
         */
        private void analyzeGrid(char[][] grid) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (grid[i][j] == 'B') {
                        rowMinCol[i] = Math.min(rowMinCol[i], j);
                        rowMaxCol[i] = Math.max(rowMaxCol[i], j);
                        colMinRow[j] = Math.min(colMinRow[j], i);
                        colMaxRow[j] = Math.max(colMaxRow[j], i);
                    }
                }
            }

            // Rows and columns with no 'B' are always "covered" by any window.
            for (int i = 0; i < n; i++) {
                if (rowMinCol[i] == Integer.MAX_VALUE) {
                    emptyRowsAndColsCount++;
                }
                if (colMinRow[i] == Integer.MAX_VALUE) {
                    emptyRowsAndColsCount++;
                }
            }
        }

        /**
         * Uses a difference array to find the window index [i, i+k-1] that 
         * maximizes the sum of contained rows and columns.
         */
        public int calculateMaxCovered() {
            // diffArray[i] tracks how many rows/cols are contained by a window starting at index i.
            // Size is n - k + 2 to handle the boundary when doing diffArray[end + 1]--.
            int[] diffArray = new int[n - k + 2];

            // A row 'r' is contained in window [i, i+k-1] if:
            // 1. i <= r <= i+k-1  =>  r-k+1 <= i <= r
            // 2. i <= minCol[r]   =>  i <= minCol[r]
            // 3. maxCol[r] <= i+k-1 => i >= maxCol[r]-k+1

            // Process Rows
            for (int r = 0; r < n; r++) {
                if (rowMinCol[r] != Integer.MAX_VALUE) {
                    int start = Math.max(0, Math.max(r - k + 1, rowMaxCol[r] - k + 1));
                    int end = Math.min(n - k, Math.min(r, rowMinCol[r]));
                    if (start <= end) {
                        diffArray[start]++;
                        diffArray[end + 1]--;
                    }
                }
            }

            // Process Columns
            for (int c = 0; c < n; c++) {
                if (colMinRow[c] != Integer.MAX_VALUE) {
                    int start = Math.max(0, Math.max(c - k + 1, colMaxRow[c] - k + 1));
                    int end = Math.min(n - k, Math.min(c, colMinRow[c]));
                    if (start <= end) {
                        diffArray[start]++;
                        diffArray[end + 1]--;
                    }
                }
            }

            int maxCovered = 0;
            int currentWindowSum = 0;
            for (int i = 0; i <= n - k; i++) {
                currentWindowSum += diffArray[i];
                maxCovered = Math.max(maxCovered, currentWindowSum);
            }

            return maxCovered + emptyRowsAndColsCount;
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

/**
 * Application to find the maximum number of white lines (entirely white rows or columns)
 * achievable by placing a k x k square on an n x n grid.
 */
public class WhiteLinesApp {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int n = scanner.nextInt();
        int k = scanner.nextInt();
        scanner.nextLine(); // Consume newline

        GridData gridData = new GridData(n, k);
        gridData.parseGrid(scanner);

        WhiteLinesSolver solver = new WhiteLinesSolver(gridData);
        System.out.println(solver.solve());
    }
}

/**
 * Represents the state and properties of the n x n grid.
 */
class GridData {
    private final int n;
    private final int k;

    private final boolean[] rowContainsBlack;
    private final boolean[] colContainsBlack;

    // The range [min, max] of the top-left corner index (x or y) 
    // for a k-length window that covers all black cells in a specific row/column.
    private final int[] rowStartRangeMin;
    private final int[] rowStartRangeMax;
    private final int[] colStartRangeMin;
    private final int[] colStartRangeMax;

    private int initialWhiteLinesCount = 0;

    public GridData(int n, int k) {
        this.n = n;
        this.k = k;
        this.rowContainsBlack = new boolean[n];
        this.colContainsBlack = new boolean[n];
        this.rowStartRangeMin = new int[n];
        this.rowStartRangeMax = new int[n];
        this.colStartRangeMin = new int[n];
        this.colStartRangeMax = new int[n];

        // Initialize ranges to full possible span
        for (int i = 0; i < n; i++) {
            rowStartRangeMin[i] = 0;
            rowStartRangeMax[i] = n - k;
            colStartRangeMin[i] = 0;
            colStartRangeMax[i] = n - k;
        }
    }

    public void parseGrid(Scanner scanner) {
        for (int y = 0; y < n; y++) {
            String line = scanner.nextLine();
            for (int x = 0; x < n; x++) {
                if (line.charAt(x) == 'B') {
                    rowContainsBlack[y] = true;
                    colContainsBlack[x] = true;

                    // A window starting at 'start' covers index 'i' if: start <= i <= start + k - 1
                    // Therefore, start must be >= i - k + 1 and start must be <= i.
                    rowStartRangeMin[y] = Math.max(rowStartRangeMin[y], x - k + 1);
                    rowStartRangeMax[y] = Math.min(rowStartRangeMax[y], x);
                    colStartRangeMin[x] = Math.max(colStartRangeMin[x], y - k + 1);
                    colStartRangeMax[x] = Math.min(colStartRangeMax[x], y);
                }
            }
        }
        calculateInitialWhiteLines();
    }

    private void calculateInitialWhiteLines() {
        for (int i = 0; i < n; i++) {
            if (!rowContainsBlack[i]) initialWhiteLinesCount++;
            if (!colContainsBlack[i]) initialWhiteLinesCount++;
        }
    }

    // Getters
    public int getN() { return n; }
    public int getK() { return k; }
    public boolean isRowContainsBlack(int y) { return rowContainsBlack[y]; }
    public boolean isColContainsBlack(int x) { return colContainsBlack[x]; }
    public int getRowStartRangeMin(int y) { return rowStartRangeMin[y]; }
    public int getRowStartRangeMax(int y) { return rowStartRangeMax[y]; }
    public int getColStartRangeMin(int x) { return colStartRangeMin[x]; }
    public int getColStartRangeMax(int x) { return colStartRangeMax[x]; }
    public int getInitialWhiteLinesCount() { return initialWhiteLinesCount; }
}

/**
 * Contains the algorithmic logic to solve the problem.
 */
class WhiteLinesSolver {
    private final GridData grid;

    public WhiteLinesSolver(GridData grid) {
        this.grid = grid;
    }

    /**
     * Uses a sliding window approach to find the maximum number of white lines.
     * Complexity: O(n^2)
     */
    public int solve() {
        int n = grid.getN();
        int k = grid.getK();
        int maxWhiteLines = grid.getInitialWhiteLinesCount();

        // Iterate through every possible top row 'y' of the k x k square
        for (int y = 0; y <= n - k; y++) {
            int currentWhiteLines = grid.getInitialWhiteLinesCount();

            // 1. Calculate columns that become white if the square starts at (y, 0)
            for (int x = 0; x < k; x++) {
                if (isColumnCovered(x, y)) {
                    currentWhiteLines++;
                }
            }

            // 2. Use a difference array to track how many rows in the current y-span
            // become white as we slide the square horizontally across x.
            int[] rowDiffArray = new int[n + 1];
            for (int rowIdx = y; rowIdx < y + k; rowIdx++) {
                if (grid.isRowContainsBlack(rowIdx)) {
                    int minStart = grid.getRowStartRangeMin(rowIdx);
                    int maxStart = grid.getRowStartRangeMax(rowIdx);
                    if (minStart <= maxStart) {
                        rowDiffArray[Math.max(0, minStart)]++;
                        rowDiffArray[Math.min(n, maxStart + 1)]--;
                    }
                }
            }

            // Apply the difference array to the current starting x = 0
            currentWhiteLines += rowDiffArray[0];
            maxWhiteLines = Math.max(maxWhiteLines, currentWhiteLines);

            // 3. Slide the k x k square from x = 1 to n - k
            for (int x = 1; x <= n - k; x++) {
                // Update rows using the difference array
                currentWhiteLines += rowDiffArray[x];

                // Update columns: remove the column that just left the k-width window
                if (isColumnCovered(x - 1, y)) {
                    currentWhiteLines--;
                }
                // Update columns: add the column that just entered the k-width window
                if (isColumnCovered(x + k - 1, y)) {
                    currentWhiteLines++;
                }

                maxWhiteLines = Math.max(maxWhiteLines, currentWhiteLines);
            }
        }

        return maxWhiteLines;
    }

    /**
     * Checks if all black cells in column 'x' are covered by a k x k square starting at row 'y'.
     */
    private boolean isColumnCovered(int x, int y) {
        return grid.isColContainsBlack(x) && 
               y >= grid.getColStartRangeMin(x) && 
               y <= grid.getColStartRangeMax(x);
    }
}

import java.io.*;
import java.util.*;

/**
 * A solution to find the maximum coverage in a k x k subgrid.
 * Coverage is defined as the sum of:
 * 1. Columns within the k x k subgrid whose 'B' cells are entirely contained within the subgrid's row range.
 * 2. Rows within the k x k subgrid whose 'B' cells are entirely contained within the subgrid's column range.
 */
public class GridCoverageSolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            String line = reader.readLine();
            if (line == null || line.isEmpty()) return;

            StringTokenizer st = new StringTokenizer(line);
            int n = Integer.parseInt(st.nextToken());
            int k = Integer.parseInt(st.nextToken());

            char[][] grid = new char[n][n];
            for (int i = 0; i < n; i++) {
                String rowStr = reader.readLine();
                if (rowStr != null) {
                    grid[i] = rowStr.toCharArray();
                }
            }

            GridCoverageSolver solver = new GridCoverageSolver();
            int result = solver.solve(n, k, grid);
            writer.println(result);

        } catch (Exception e) {
            // In a real-world application, use a logger.
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Orchestrates the computation of the maximum coverage.
     */
    public int solve(int n, int k, char[][] grid) {
        // Precompute bounds for rows and columns
        int[] minRowInCol = new int[n];
        int[] maxRowInCol = new int[n];
        boolean[] hasBInCol = new boolean[n];

        int[] minColInRow = new int[n];
        int[] maxColInRow = new int[n];
        boolean[] hasBInRow = new boolean[n];

        Arrays.fill(minRowInCol, Integer.MAX_VALUE);
        Arrays.fill(maxRowInCol, Integer.MIN_VALUE);
        Arrays.fill(minColInRow, Integer.MAX_VALUE);
        Arrays.fill(maxColInRow, Integer.MIN_VALUE);

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 'B') {
                    // Update Column properties
                    minRowInCol[j] = Math.min(minRowInCol[j], i);
                    maxRowInCol[j] = Math.max(maxRowInCol[j], i);
                    hasBInCol[j] = true;

                    // Update Row properties
                    minColInRow[i] = Math.min(minColInRow[i], j);
                    maxColInRow[i] = Math.max(maxColInRow[i], j);
                    hasBInRow[i] = true;
                }
            }
        }

        // colCoverage[r][c] is the count of valid columns for row-range [r, r+k-1] in column-window [c, c+k-1]
        int[][] colCoverage = computeCoverage(n, k, minRowInCol, maxRowInCol, hasBInCol);

        // rowCoverage[c][r] is the count of valid rows for col-range [c, c+k-1] in row-window [r, r+k-1]
        int[][] rowCoverage = computeCoverage(n, k, minColInRow, maxColInRow, hasBInRow);

        int maxTotalCoverage = 0;
        for (int i = 0; i <= n - k; i++) {
            for (int j = 0; j <= n - k; j++) {
                // colCoverage index: [row_start][col_start]
                // rowCoverage index: [col_start][row_start]
                maxTotalCoverage = Math.max(maxTotalCoverage, colCoverage[i][j] + rowCoverage[j][i]);
            }
        }

        return maxTotalCoverage;
    }

    /**
     * Uses a sliding window approach to compute coverage for all possible subgrids.
     *
     * @param n       Grid dimension
     * @param k       Subgrid dimension
     * @param mins    Minimum index of 'B' in each unit (row or column)
     * @param maxs    Maximum index of 'B' in each unit (row or column)
     * @param hasB    Whether the unit contains any 'B'
     * @return A 2D array where [constraintStart][windowStart] stores the coverage count.
     */
    private int[][] computeCoverage(int n, int k, int[] mins, int[] maxs, boolean[] hasB) {
        int[][] coverage = new int[n][n];

        for (int constraintStart = 0; constraintStart <= n - k; constraintStart++) {
            int constraintEnd = constraintStart + k - 1;

            // 1. Determine which units are valid for this constraint range
            int[] isValid = new int[n];
            for (int i = 0; i < n; i++) {
                if (!hasB[i] || (mins[i] >= constraintStart && maxs[i] <= constraintEnd)) {
                    isValid[i] = 1;
                }
            }

            // 2. Use sliding window to count valid units in the window dimension
            int currentWindowSum = 0;
            for (int i = 0; i < k; i++) {
                currentWindowSum += isValid[i];
            }
            coverage[constraintStart][0] = currentWindowSum;

            for (int windowStart = 1; windowStart <= n - k; windowStart++) {
                currentWindowSum = currentWindowSum - isValid[windowStart - 1] + isValid[windowStart + k - 1];
                coverage[constraintStart][windowStart] = currentWindowSum;
            }
        }
        return coverage;
    }

    /**
     * Utility class for fast input reading.
     */
    static class FastReader {
        private final BufferedReader reader;

        public FastReader(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String readLine() throws IOException {
            return reader.readLine();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A refactored version of the Grid Range Solver.
 * This program calculates the maximum value in a 2D grid after applying 
 * specific range updates based on the positions of 'B' characters.
 */
public class Main {
    public static void main(String[] args) throws IOException {
        Solver solver = new Solver();
        solver.solve();
    }
}

class Solver {
    private final FastScanner scanner;
    private final PrintWriter out;

    public Solver() {
        this.scanner = new FastScanner(System.in);
        this.out = new PrintWriter(System.out);
    }

    /**
     * Orchestrates the logic of reading input, processing the grid, 
     * calculating prefix sums, and outputting the result.
     */
    public void solve() throws IOException {
        int n = scanner.nextInt();
        int k = scanner.nextInt();

        // Data structures to track the boundaries of 'B' characters
        int[] firstRowInCol = new int[n];
        int[] lastRowInCol = new int[n];
        int[] firstColInRow = new int[n];
        int[] lastColInRow = new int[n];

        Arrays.fill(firstRowInCol, -1);
        Arrays.fill(lastRowInCol, -1);
        Arrays.fill(firstColInRow, -1);
        Arrays.fill(lastColInRow, -1);

        // Read grid and identify 'B' character boundaries
        for (int i = 0; i < n; i++) {
            String rowStr = scanner.next();
            if (rowStr == null) break;
            for (int j = 0; j < rowStr.length(); j++) {
                if (rowStr.charAt(j) == 'B') {
                    if (firstRowInCol[j] == -1) firstRowInCol[j] = i;
                    if (firstColInRow[i] == -1) firstColInRow[i] = j;
                    lastColInRow[i] = j;
                    lastRowInCol[j] = i;
                }
            }
        }

        // diffArray used for 2D range updates. 
        // Based on the original logic, the first dimension represents columns.
        int[][] diffArray = new int[n + 1][n + 1];

        // Process vertical segments (Column-based updates)
        for (int col = 0; col < n; col++) {
            if (firstRowInCol[col] == -1) {
                applyFullGridUpdate(diffArray, n);
            } else if (lastRowInCol[col] - firstRowInCol[col] + 1 <= k) {
                int r1 = Math.max(col - k + 1, 0);
                int c1 = Math.max(lastRowInCol[col] - k + 1, 0);
                int r2 = col + 1;
                int c2 = firstRowInCol[col] + 1;
                applyRectUpdate(diffArray, r1, c1, r2, c2);
            }
        }

        // Process horizontal segments (Row-based updates)
        for (int row = 0; row < n; row++) {
            if (firstColInRow[row] == -1) {
                applyFullGridUpdate(diffArray, n);
            } else if (lastColInRow[row] - firstColInRow[row] + 1 <= k) {
                int r1 = Math.max(lastColInRow[row] - k + 1, 0);
                int c1 = Math.max(row - k + 1, 0);
                int r2 = firstColInRow[row] + 1;
                int c2 = row + 1;
                applyRectUpdate(diffArray, r1, c1, r2, c2);
            }
        }

        // Calculate 2D Prefix Sums
        // 1. Prefix sum over the second dimension (rows)
        for (int i = 0; i < n + 1; i++) {
            for (int j = 1; j < n + 1; j++) {
                diffArray[i][j] += diffArray[i][j - 1];
            }
        }
        // 2. Prefix sum over the first dimension (columns)
        for (int j = 0; j < n + 1; j++) {
            for (int i = 1; i < n + 1; i++) {
                diffArray[i][j] += diffArray[i - 1][j];
            }
        }

        // Find the maximum value in the processed grid
        int maxVal = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                maxVal = Math.max(maxVal, diffArray[i][j]);
            }
        }

        out.println(maxVal);
        out.flush();
        out.close();
    }

    /**
     * Updates the entire grid within the bounds [0, n-1].
     */
    private void applyFullGridUpdate(int[][] arr, int n) {
        arr[0][0]++;
        arr[0][n]--;
        arr[n][0]--;
        arr[n][n]++;
    }

    /**
     * Standard 2D difference array update for a rectangle defined by (r1, c1) and (r2, c2).
     */
    private void applyRectUpdate(int[][] arr, int r1, int c1, int r2, int c2) {
        arr[r1][c1]++;
        arr[r2][c1]--;
        arr[r1][c2]--;
        arr[r2][c2]++;
    }

    /**
     * Helper class for fast I/O operations.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String s = br.readLine();
                if (s == null) return null;
                st = new StringTokenizer(s);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A solver for finding the maximum score of a KxK window in a grid.
 * The score is calculated based on continuous white ('W') cells and full rows/columns.
 */
public class Main {
    public static void main(String[] args) throws IOException {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = in.nextInt();
        int k = in.nextInt();
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = in.next().toCharArray();
        }

        GridScoreSolver solver = new GridScoreSolver(n, k);
        long maxScore = solver.solve(grid);

        out.println(maxScore);
        out.close();
    }

    static class GridScoreSolver {
        private final int n;
        private final int k;

        public GridScoreSolver(int n, int k) {
            this.n = n;
            this.k = k;
        }

        /**
         * Solves the problem by calculating row and column contributions separately.
         */
        public long solve(char[][] grid) {
            // Calculate contribution of rows to each window (i, j)
            int[][] rowContributions = calculateRowContributions(grid);

            // Transpose the grid to reuse row logic for column contributions
            char[][] transposedGrid = transpose(grid);
            int[][] colContributionsTransposed = calculateRowContributions(transposedGrid);

            int maxScore = 0;

            // The window at (i, j) in the original grid 
            // corresponds to (i, j) in rowContributions 
            // and (j, i) in colContributionsTransposed
            for (int i = 0; i <= n - k; i++) {
                for (int j = 0; j <= n - k; j++) {
                    int currentScore = rowContributions[i][j] + colContributionsTransposed[j][i];
                    maxScore = Math.max(maxScore, currentScore);
                }
            }

            return maxScore;
        }

        /**
         * Computes the score contribution of rows for every possible KxK window.
         * 
         * @param grid The input grid.
         * @return A 2D array where result[i][j] is the row-based score for window starting at (i, j).
         */
        private int[][] calculateRowContributions(char[][] grid) {
            int[] suffixWhiteStart = new int[n];
            int[] prefixWhiteEnd = new int[n];
            int[] fullRowPrefixSum = new int[n + 1];

            // Pre-calculate white block boundaries and full-row prefix sums
            for (int i = 0; i < n; i++) {
                // Find the leftmost index such that all cells from [index...N-1] are 'W'
                int left = n;
                for (int j = n - 1; j >= 0 && grid[i][j] == 'W'; j--) {
                    left = j;
                }
                suffixWhiteStart[i] = left;

                // Find the rightmost index such that all cells from [0...index] are 'W'
                int right = -1;
                for (int j = 0; j < n && grid[i][j] == 'W'; j++) {
                    right = j;
                }
                prefixWhiteEnd[i] = right;

                // A row is "full white" if the suffix white block starts at index 0
                fullRowPrefixSum[i + 1] = fullRowPrefixSum[i] + (left == 0 ? 1 : 0);
            }

            int[][] scores = new int[n][n];

            // Slide window across columns
            for (int j = 0; j <= n - k; j++) {
                int whiteBlockCountInWindow = 0;

                // Initialize sliding window for the first K rows (i=0)
                for (int i = 0; i < k - 1; i++) {
                    if (isWhiteBlockOverlapping(suffixWhiteStart[i], prefixWhiteEnd[i], j)) {
                        whiteBlockCountInWindow++;
                    }
                }

                // Slide the window down the rows
                for (int i = 0; i <= n - k; i++) {
                    int nextRowIdx = i + k - 1;

                    // Add the new row entering the window
                    if (isWhiteBlockOverlapping(suffixWhiteStart[nextRowIdx], prefixWhiteEnd[nextRowIdx], j)) {
                        whiteBlockCountInWindow++;
                    }

                    // Remove the row leaving the window
                    if (i > 0 && isWhiteBlockOverlapping(suffixWhiteStart[i - 1], prefixWhiteEnd[i - 1], j)) {
                        whiteBlockCountInWindow--;
                    }

                    // Calculate total row contribution for window (i, j)
                    // score = (white blocks within window) + (full white rows above) + (full white rows below)
                    int rowsAbove = fullRowPrefixSum[i];
                    int rowsBelow = fullRowPrefixSum[n] - fullRowPrefixSum[i + k];
                    scores[i][j] = whiteBlockCountInWindow + rowsAbove + rowsBelow;
                }
            }

            return scores;
        }

        /**
         * Checks if the continuous white blocks of a row overlap with the window's column range.
         * This preserves the original logic: (l[i] <= j+K && r[i] >= j-1)
         */
        private boolean isWhiteBlockOverlapping(int suffixStart, int prefixEnd, int colStart) {
            // j + k is the index immediately after the window end
            // j - 1 is the index immediately before the window start
            int colEndPlusOne = colStart + k; 
            int colStartMinusOne = colStart - 1;
            return suffixStart <= colEndPlusOne && prefixEnd >= colStartMinusOne;
        }

        private char[][] transpose(char[][] grid) {
            char[][] transposed = new char[n][n];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    transposed[j][i] = grid[i][j];
                }
            }
            return transposed;
        }
    }

    /**
     * Fast I/O utility.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A refactored solution for the grid problem.
 * The problem calculates the number of empty rows/cols plus the maximum 
 * number of "satisfied" rows and columns that can be covered by a k*k window.
 */
public class Main {
    public static void main(String[] args) {
        FastReader sc = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));

        try {
            String firstLine = sc.nextLine();
            if (firstLine == null) return;

            String[] parts = firstLine.split("\\s+");
            int gridSize = Integer.parseInt(parts[0]);
            int windowSize = Integer.parseInt(parts[1]);

            int[][] grid = new int[gridSize][gridSize];
            for (int i = 0; i < gridSize; i++) {
                String line = sc.nextLine();
                for (int j = 0; j < gridSize; j++) {
                    // 'B' represents 1, any other character represents 0
                    grid[i][j] = (line.charAt(j) == 'B') ? 1 : 0;
                }
            }

            GridProblemSolver solver = new GridProblemSolver(gridSize, windowSize, grid);
            out.println(solver.solve());

        } catch (Exception e) {
            // Handle potential parsing errors
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Handles the core logic of the grid problem.
     */
    static class GridProblemSolver {
        private final int n;
        private final int k;
        private final int[][] prefixSum;

        public GridProblemSolver(int n, int k, int[][] grid) {
            this.n = n;
            this.k = k;
            this.prefixSum = new int[n + 1][n + 1];
            computePrefixSums(grid);
        }

        private void computePrefixSums(int[][] grid) {
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    prefixSum[i][j] = grid[i - 1][j - 1]
                            + prefixSum[i - 1][j]
                            + prefixSum[i][j - 1]
                            - prefixSum[i - 1][j - 1];
                }
            }
        }

        /**
         * Calculates the sum of 'B' cells in the rectangle from (r1, c1) to (r2, c2).
         * Coordinates are 1-indexed.
         */
        private int getRectSum(int r1, int c1, int r2, int c2) {
            r2 = Math.min(r2, n);
            c2 = Math.min(c2, n);
            if (r1 > r2 || c1 > c2) return 0;
            return prefixSum[r2][c2] - prefixSum[r1 - 1][c2] - prefixSum[r2][c1 - 1] + prefixSum[r1 - 1][c1 - 1];
        }

        public long solve() {
            int emptyLinesCount = 0;

            // Count rows and columns that contain zero 'B's
            for (int i = 1; i <= n; i++) {
                if (getRectSum(i, 1, i, n) == 0) emptyLinesCount++; // Row i
                if (getRectSum(1, i, n, i) == 0) emptyLinesCount++; // Col i
            }

            // rowFlags[i][j] == 1 if row i's 'B's are all contained within a k-length segment starting at column j
            int[][] rowFlags = new int[n + 1][n + 1];
            // colFlags[i][j] == 1 if col j's 'B's are all contained within a k-length segment starting at row i
            int[][] colFlags = new int[n + 1][n + 1];

            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    // Check if segment of length k in column j contains all 'B's of that column
                    int colTotal = getRectSum(1, j, n, j);
                    if (colTotal > 0 && getRectSum(i, j, i + k - 1, j) == colTotal) {
                        colFlags[i][j] = 1;
                    }

                    // Check if segment of length k in row i contains all 'B's of that row
                    int rowTotal = getRectSum(i, 1, i, n);
                    if (rowTotal > 0 && getRectSum(i, j, i, j + k - 1) == rowTotal) {
                        rowFlags[i][j] = 1;
                    }
                }
            }

            // Transform flags into prefix sums for range queries
            // rowFlags becomes a column-wise prefix sum: rowFlags[i][j] = sum of rowFlags[1...i][j]
            // colFlags becomes a row-wise prefix sum: colFlags[i][j] = sum of colFlags[i][1...j]
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    rowFlags[i][j] += rowFlags[i - 1][j];
                    colFlags[i][j] += colFlags[i][j - 1];
                }
            }

            int maxSatisfiedLines = 0;
            // Find the maximum sum of satisfied rows and columns within a k*k window
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    int satisfiedRows = rowFlags[Math.min(i + k - 1, n)][j] - rowFlags[i - 1][j];
                    int satisfiedCols = colFlags[i][Math.min(j + k - 1, n)] - colFlags[i][j - 1];
                    maxSatisfiedLines = Math.max(maxSatisfiedLines, satisfiedRows + satisfiedCols);
                }
            }

            return (long) emptyLinesCount + maxSatisfiedLines;
        }
    }

    /**
     * Efficient input reader.
     */
    static class FastReader {
        private BufferedReader reader;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String nextLine() {
            try {
                return reader.readLine();
            } catch (IOException e) {
                return null;
            }
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves the problem of finding a k x k square that maximizes the number of 
 * satisfied rows and columns. A row/column is satisfied if all its 'B' 
 * cells are contained within the k x k window.
 */
public class BMatrixSolver {

    public static void main(String[] args) {
        try {
            GridScanner scanner = new GridScanner(System.in);
            int n = scanner.nextInt();
            int k = scanner.nextInt();
            char[][] grid = scanner.readGrid(n);

            Solver solver = new Solver(n, k, grid);
            int result = solver.solve();

            System.out.println(result);
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Represents a range [start, end].
     */
    private static class Range {
        final int start;
        final int end;
        final boolean empty;

        Range(int start, int end, boolean empty) {
            this.start = start;
            this.end = end;
            this.empty = empty;
        }

        static Range empty() {
            return new Range(0, 0, true);
        }
    }

    /**
     * Logic engine for calculating the maximum satisfied rows and columns.
     */
    private static class Solver {
        private final int n;
        private final int k;
        private final char[][] grid;

        Solver(int n, int k, char[][] grid) {
            this.n = n;
            this.k = k;
            this.grid = grid;
        }

        public int solve() {
            Range[] rowRanges = findRanges(true);
            Range[] colRanges = findRanges(false);

            int emptyRowsCount = 0;
            int emptyColsCount = 0;

            for (Range r : rowRanges) if (r.empty) emptyRowsCount++;
            for (Range c : colRanges) if (c.empty) emptyColsCount++;

            // diff array for 2D range updates (2D Difference Array)
            // score[i][j] will store how many additional rows/cols are satisfied
            // if the k x k window starts at top-left corner (i, j).
            int[][] diff = new int[n + 2][n + 2];

            // Add valid intervals for rows
            for (int r = 0; r < n; r++) {
                Range range = rowRanges[r];
                if (!range.empty) {
                    // A row r is satisfied by window top-left (i, j) if:
                    // 1. Window covers row r: i <= r < i + k  =>  r - k + 1 <= i <= r
                    // 2. Window covers 'B's in row r: j <= firstB and lastB <= j + k - 1
                    //    => lastB - k + 1 <= j <= firstB
                    int iStart = Math.max(0, r - k + 1);
                    int iEnd = Math.min(n - k, r);
                    int jStart = Math.max(0, range.end - k + 1);
                    int jEnd = Math.min(n - k, range.start);

                    addRectangle(diff, iStart, iEnd, jStart, jEnd);
                }
            }

            // Add valid intervals for columns
            for (int c = 0; c < n; c++) {
                Range range = colRanges[c];
                if (!range.empty) {
                    // A column c is satisfied by window top-left (i, j) if:
                    // 1. Window covers column c: j <= c < j + k  =>  c - k + 1 <= j <= c
                    // 2. Window covers 'B's in col c: i <= firstC and lastC <= i + k - 1
                    //    => lastC - k + 1 <= i <= firstC
                    int jStart = Math.max(0, c - k + 1);
                    int jEnd = Math.min(n - k, c);
                    int iStart = Math.max(0, range.end - k + 1);
                    int iEnd = Math.min(n - k, range.start);

                    addRectangle(diff, iStart, iEnd, jStart, jEnd);
                }
            }

            int maxAdditional = 0;
            // Compute 2D prefix sums to recover actual scores
            for (int i = 0; i <= n - k; i++) {
                for (int j = 0; j <= n - k; j++) {
                    if (i > 0) diff[i][j] += diff[i - 1][j];
                    if (j > 0) diff[i][j] += diff[i][j - 1];
                    if (i > 0 && j > 0) diff[i][j] -= diff[i - 1][j - 1];

                    maxAdditional = Math.max(maxAdditional, diff[i][j]);
                }
            }

            // Final answer is (always satisfied) + (max newly satisfied)
            // Note: The 2D prefix sum above is a slightly simplified version.
            // For a standard 2D prefix sum, we should compute the whole array first.
            return calculateMaxFromDiff(diff, n - k) + emptyRowsCount + emptyColsCount;
        }

        private void addRectangle(int[][] diff, int r1, int r2, int c1, int c2) {
            if (r1 > r2 || c1 > c2) return;
            diff[r1][c1]++;
            diff[r1][c2 + 1]--;
            diff[r2 + 1][c1]--;
            diff[r2 + 1][c2 + 1]++;
        }

        private int calculateMaxFromDiff(int[][] diff, int limit) {
            int max = 0;
            // The logic in solve() already accumulated prefix sums partially.
            // To ensure correctness, we reconstruct the score array fully.
            int[][] score = new int[n + 1][n + 1];
            for (int i = 0; i <= n; i++) {
                for (int j = 0; j <= n; j++) {
                    int val = diff[i][j];
                    if (i > 0) val += score[i - 1][j];
                    if (j > 0) val += score[i][j - 1];
                    if (i > 0 && j > 0) val -= score[i - 1][j - 1];
                    score[i][j] = val;
                    if (i <= limit && j <= limit) {
                        max = Math.max(max, val);
                    }
                }
            }
            return max;
        }

        /**
         * Finds the first and last occurrence of 'B' for each row or column.
         */
        private Range[] findRanges(boolean isRow) {
            Range[] ranges = new Range[n];
            for (int i = 0; i < n; i++) {
                int first = -1;
                int last = -1;

                for (int j = 0; j < n; j++) {
                    char cell = isRow ? grid[i][j] : grid[j][i];
                    if (cell == 'B') {
                        if (first == -1) first = j;
                        last = j;
                    }
                }

                if (first == -1) {
                    ranges[i] = Range.empty();
                } else {
                    ranges[i] = new Range(first, last, false);
                }
            }
            return ranges;
        }
    }

    /**
     * Fast I/O utility for efficient reading.
     */
    private static class GridScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public GridScanner(InputStream inputStream) {
            this.reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public char[][] readGrid(int n) throws IOException {
            char[][] grid = new char[n][n];
            for (int i = 0; i < n; i++) {
                grid[i] = next().toCharArray();
            }
            return grid;
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A solution to the White Lines problem that calculates the maximum 
 * score based on valid row/column segments and empty rows/columns.
 */
public class WhiteLines {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        // Read grid size and segment offset
        int gridSize = reader.nextInt();
        // The original logic subtracts 1 from k to use it as a 0-indexed offset
        int segmentOffset = reader.nextInt() - 1;

        int[][] grid = new int[gridSize][gridSize];
        for (int i = 0; i < gridSize; i++) {
            String rowString = reader.next();
            for (int j = 0; j < gridSize; j++) {
                if (rowString.charAt(j) == 'B') {
                    grid[i][j] = 1;
                }
            }
        }

        WhiteLinesSolver solver = new WhiteLinesSolver(gridSize, segmentOffset, grid);
        System.out.println(solver.solve());
    }

    /**
     * Encapsulates 2D prefix sum calculations for efficient range queries.
     */
    static class PrefixSumMatrix {
        private final int[][] prefixSum;
        private final int rows;
        private final int cols;

        public PrefixSumMatrix(int[][] matrix) {
            this.rows = matrix.length;
            this.cols = matrix[0].length;
            this.prefixSum = new int[rows][cols];
            buildPrefixSum(matrix);
        }

        private void buildPrefixSum(int[][] matrix) {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    int val = matrix[i][j];
                    int above = (i > 0) ? prefixSum[i - 1][j] : 0;
                    int left = (j > 0) ? prefixSum[i][j - 1] : 0;
                    int diagonal = (i > 0 && j > 0) ? prefixSum[i - 1][j - 1] : 0;
                    prefixSum[i][j] = val + above + left - diagonal;
                }
            }
        }

        /**
         * Returns the sum of elements in the rectangle from (r1, c1) to (r2, c2) inclusive.
         */
        public int getSum(int r1, int c1, int r2, int c2) {
            if (r1 > r2 || c1 > c2) return 0;
            int res = prefixSum[r2][c2];
            if (r1 > 0) res -= prefixSum[r1 - 1][c2];
            if (c1 > 0) res -= prefixSum[r2][c1 - 1];
            if (r1 > 0 && c1 > 0) res += prefixSum[r1 - 1][c1 - 1];
            return res;
        }
    }

    /**
     * Contains the core logic for solving the White Lines problem.
     */
    static class WhiteLinesSolver {
        private final int gridSize;
        private final int k;
        private final PrefixSumMatrix blackCells;

        public WhiteLinesSolver(int gridSize, int k, int[][] grid) {
            this.gridSize = gridSize;
            this.k = k;
            this.blackCells = new PrefixSumMatrix(grid);
        }

        public int solve() {
            int[][] rowSegments = new int[gridSize][gridSize];
            int[][] colSegments = new int[gridSize][gridSize];
            int perfectCount = 0;

            // Identify rows where a segment of length k+1 contains all 'B's 
            // and identify rows that are entirely empty.
            for (int i = 0; i < gridSize; i++) {
                int totalInRow = blackCells.getSum(i, 0, i, gridSize - 1);
                if (totalInRow == 0) {
                    perfectCount++;
                } else {
                    for (int j = 0; j <= gridSize - 1 - k; j++) {
                        if (blackCells.getSum(i, j, i, j + k) == totalInRow) {
                            rowSegments[i][j] = 1;
                        }
                    }
                }
            }

            // Identify columns where a segment of length k+1 contains all 'B's 
            // and identify columns that are entirely empty.
            for (int j = 0; j < gridSize; j++) {
                int totalInCol = blackCells.getSum(0, j, gridSize - 1, j);
                if (totalInCol == 0) {
                    perfectCount++;
                } else {
                    for (int i = 0; i <= gridSize - 1 - k; i++) {
                        if (blackCells.getSum(i, j, i + k, j) == totalInCol) {
                            colSegments[i][j] = 1;
                        }
                    }
                }
            }

            PrefixSumMatrix rowSegmentPSM = new PrefixSumMatrix(rowSegments);
            PrefixSumMatrix colSegmentPSM = new PrefixSumMatrix(colSegments);

            int maxScore = 0;
            // Iterate through all possible top-left corners (i, j) of a (k+1)x(k+1) window
            for (int i = 0; i <= gridSize - 1 - k; i++) {
                for (int j = 0; j <= gridSize - 1 - k; j++) {
                    // Count how many valid row segments fall in the vertical strip of the window
                    int rowSegCount = rowSegmentPSM.getSum(i, j, i + k, j);
                    // Count how many valid col segments fall in the horizontal strip of the window
                    int colSegCount = colSegmentPSM.getSum(i, j, i, j + k);

                    maxScore = Math.max(maxScore, rowSegCount + colSegCount + perfectCount);
                }
            }

            return maxScore;
        }
    }

    /**
     * Utility class for fast input reading.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
