                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solution to find the maximum number of white lines (rows or columns) 
 * possible in a grid by repainting a k x k square area.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = reader.nextInt();
            int k = reader.nextInt();
            char[][] grid = reader.readCharGrid(n, n);

            GridProblemSolver solver = new GridProblemSolver(n, k, grid);
            out.println(solver.solve());
        } catch (Exception e) {
            // Standard error handling for competitive programming/tools
        } finally {
            out.close();
        }
    }

    /**
     * Orchestrates the grid problem solving process.
     */
    static class GridProblemSolver {
        private final int n;
        private final int k;
        private final int[][] binaryGrid; // 0 represents 'W', 1 represents others

        public GridProblemSolver(int n, int k, char[][] grid) {
            this.n = n;
            this.k = k;
            this.binaryGrid = convertToBinaryGrid(grid);
        }

        private int[][] convertToBinaryGrid(char[][] grid) {
            int[][] binary = new int[n][n];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    binary[i][j] = (grid[i][j] == 'W') ? 0 : 1;
                }
            }
            return binary;
        }

        public int solve() {
            // Analyze rows
            DimensionAnalyzer rowAnalyzer = new DimensionAnalyzer(binaryGrid, k);

            // Analyze columns by transposing the grid and treating columns as rows
            DimensionAnalyzer colAnalyzer = new DimensionAnalyzer(transpose(binaryGrid), k);

            int initialWhiteLines = rowAnalyzer.getExistingWhiteLinesCount() + colAnalyzer.getExistingWhiteLinesCount();
            int maxWhiteLines = initialWhiteLines;

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    // A k x k square starting at (i, j) in the original grid 
                    // corresponds to a square starting at (j, i) in the transposed grid.
                    int newRows = rowAnalyzer.getNewWhiteLines(i, j);
                    int newCols = colAnalyzer.getNewWhiteLines(j, i);

                    maxWhiteLines = Math.max(maxWhiteLines, initialWhiteLines + newRows + newCols);
                }
            }

            return maxWhiteLines;
        }

        private int[][] transpose(int[][] matrix) {
            int size = matrix.length;
            int[][] transposed = new int[size][size];
            for (int i = 0; i < size; i++) {
                for (int j = 0; j < size; j++) {
                    transposed[j][i] = matrix[i][j];
                }
            }
            return transposed;
        }
    }

    /**
     * Analyzes a dimension (rows or columns) to calculate existing white lines 
     * and the potential increase in white lines when a k-length segment is painted.
     */
    static class DimensionAnalyzer {
        private final int size;
        private final int k;
        private final int existingWhiteLinesCount;
        private final int[][] newWhiteLinesMap; 

        public DimensionAnalyzer(int[][] grid, int k) {
            this.size = grid.length;
            this.k = k;
            this.newWhiteLinesMap = new int[size][size];

            int existingCount = 0;
            // whitable[r][c] is 1 if painting segment [c, c+k-1] in row r makes the whole row 'W'
            int[][] whitable = new int[size][size];

            for (int i = 0; i < size; i++) {
                int[] row = grid[i];
                int rowSum = 0;
                for (int val : row) rowSum += val;

                if (rowSum == 0) {
                    existingCount++;
                } else {
                    int[] pref = new int[size + 1];
                    for (int j = 0; j < size; j++) {
                        pref[j + 1] = pref[j] + row[j];
                    }

                    // A row is whitable at segment [j, j+k-1] if all elements outside that segment are already 0 ('W')
                    for (int j = 0; j <= size - k; j++) {
                        if (pref[j] == 0 && (pref[size] - pref[j + k]) == 0) {
                            whitable[i][j] = 1;
                        }
                    }
                }
            }
            this.existingWhiteLinesCount = existingCount;

            // Calculate how many rows in the window [i, i+k-1] become whitable at column j
            for (int j = 0; j < size; j++) {
                int[] colPref = new int[size + 1];
                for (int i = 0; i < size; i++) {
                    colPref[i + 1] = colPref[i] + whitable[i][j];
                }
                for (int i = 0; i <= size - k; i++) {
                    newWhiteLinesMap[i][j] = colPref[i + k] - colPref[i];
                }
            }
        }

        public int getExistingWhiteLinesCount() {
            return existingWhiteLinesCount;
        }

        /**
         * Returns the number of new white lines created if the segment 
         * starting at [row, col] is painted.
         */
        public int getNewWhiteLines(int row, int col) {
            if (row < 0 || row >= size || col < 0 || col >= size) return 0;
            // Check if the starting index allows for a full k-length window
            if (col > size - k || row > size - k) return 0; 
            return newWhiteLinesMap[row][col];
        }
    }

    /**
     * High-performance input reader for large data sets.
     */
    static class FastReader {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (numChars == -1) throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) return -1;
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res = res * 10 + (c - '0');
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public char[][] readCharGrid(int rows, int cols) {
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = nextChar();
                }
            }
            return grid;
        }

        public char nextChar() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            return (char) c;
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

