/**
 * A Segment Tree implementation supporting range additions and range maximum queries.
 * Uses lazy propagation for efficiency.
 */
class SegmentTree {
    private final int[] maxValues;
    private final int[] lazyUpdates;
    private final int size;

    public SegmentTree(int n) {
        this.size = n;
        this.maxValues = new int[4 * n];
        this.lazyUpdates = new int[4 * n];
    }

    private void pushDown(int node) {
        if (lazyUpdates[node] != 0) {
            int left = 2 * node + 1;
            int right = 2 * node + 2;

            lazyUpdates[left] += lazyUpdates[node];
            maxValues[left] += lazyUpdates[node];

            lazyUpdates[right] += lazyUpdates[node];
            maxValues[right] += lazyUpdates[node];

            lazyUpdates[node] = 0;
        }
    }

    public void updateRange(int left, int right, int delta) {
        updateRange(0, 0, size - 1, left, right, delta);
    }

    private void updateRange(int node, int nodeL, int nodeR, int queryL, int queryR, int delta) {
        if (queryL > nodeR || queryR < nodeL) {
            return;
        }
        if (queryL <= nodeL && nodeR <= queryR) {
            maxValues[node] += delta;
            lazyUpdates[node] += delta;
            return;
        }
        pushDown(node);
        int mid = (nodeL + nodeR) / 2;
        updateRange(2 * node + 1, nodeL, mid, queryL, queryR, delta);
        updateRange(2 * node + 2, mid + 1, nodeR, queryL, queryR, delta);
        maxValues[node] = Math.max(maxValues[2 * node + 1], maxValues[2 * node + 2]);
    }

    public int getMax() {
        return maxValues[0];
    }
}

/**
 * Logic to solve the grid problem.
 */
class GridProblemSolver {
    private static final int INF = (int) 1e9;

    private final int gridSize;
    private final int windowSize;
    private final int[] minRowInCol;
    private final int[] maxRowInCol;
    private final int[] minColInRow;
    private final int[] maxColInRow;
    private int baseMissingLinesCount = 0;

    public GridProblemSolver(int gridSize, int windowSize, char[][] grid) {
        this.gridSize = gridSize;
        this.windowSize = windowSize;
        this.minRowInCol = new int[gridSize];
        this.maxRowInCol = new int[gridSize];
        this.minColInRow = new int[gridSize];
        this.maxColInRow = new int[gridSize];

        Arrays.fill(minRowInCol, INF);
        Arrays.fill(maxRowInCol, -INF);
        Arrays.fill(minColInRow, INF);
        Arrays.fill(maxColInRow, -INF);

        preprocessBoundaries(grid);
    }

    private void preprocessBoundaries(char[][] grid) {
        for (int i = 0; i < gridSize; i++) {
            boolean rowHasLand = false;
            for (int j = 0; j < gridSize; j++) {
                if (grid[i][j] == 'L') { // Assuming 'L' for land based on logic 'W' for water
                    minColInRow[i] = Math.min(minColInRow[i], j);
                    maxColInRow[i] = Math.max(maxColInRow[i], j);
                    rowHasLand = true;
                }
            }
            if (!rowHasLand) baseMissingLinesCount++;

            boolean colHasLand = false;
            for (int j = 0; j < gridSize; j++) {
                if (grid[j][i] == 'L') {
                    minRowInCol[i] = Math.min(minRowInCol[i], j);
                    maxRowInCol[i] = Math.max(maxRowInCol[i], j);
                    colHasLand = true;
                }
            }
            if (!colHasLand) baseMissingLinesCount++;
        }
    }

    public int solve() {
        int maxCoverage = 0;

        // Iterate through all possible top-row positions of the vertical window
        for (int i = 0; i <= gridSize - windowSize; i++) {
            SegmentTree st = new SegmentTree(gridSize);
            int[] colContainedInWindow = new int[gridSize];

            // Identify columns where land is entirely contained within the vertical window [i, i + k - 1]
            for (int j = 0; j < gridSize; j++) {
                if (maxRowInCol[j] < i + windowSize && minRowInCol[j] >= i) {
                    colContainedInWindow[j] = 1;
                }
            }

            // Use a sliding window to find the initial number of contained columns in any width-k window
            int currentWindowSum = 0;
            for (int j = 0; j < windowSize; j++) {
                currentWindowSum += colContainedInWindow[j];
            }
            st.updateRange(0, 0, currentWindowSum);

            for (int j = windowSize; j < gridSize; j++) {
                currentWindowSum += colContainedInWindow[j] - colContainedInWindow[j - windowSize];
                st.updateRange(j - windowSize + 1, j - windowSize + 1, currentWindowSum);
            }

            // Add bonus for horizontal segments that fit within the window
            for (int j = i; j < i + windowSize; j++) {
                int span = maxColInRow[j] - minColInRow[j];
                if (span < windowSize) {
                    // The starting column 'c' must satisfy: c <= minCol and c + k - 1 >= maxCol
                    // Therefore: maxCol - k + 1 <= c <= minCol
                    int rangeStart = maxColInRow[j] - windowSize + 1;
                    int rangeEnd = minColInRow[j];
                    if (rangeStart <= rangeEnd) {
                        st.updateRange(Math.max(0, rangeStart), Math.min(gridSize - 1, rangeEnd), 1);
                    }
                }
            }

            maxCoverage = Math.max(maxCoverage, baseMissingLinesCount + st.getMax());
        }

        return maxCoverage;
    }
}

public class Main {
    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            String firstLine = reader.next();
            if (firstLine == null) return;

            int n = Integer.parseInt(firstLine);
            int k = reader.nextInt();

            char[][] grid = new char[n][n];
            for (int i = 0; i < n; i++) {
                String row = reader.next();
                for (int j = 0; j < n; j++) {
                    // The original code logic: 'W' is water (0), 'L' (or anything else) is land (1)
                    // We normalize input: 'W' -> 'W', everything else -> 'L'
                    grid[i][j] = (row.charAt(j) == 'W') ? 'W' : 'L';
                }
            }

            GridProblemSolver solver = new GridProblemSolver(n, k, grid);
            out.println(solver.solve());

        } catch (Exception e) {
            // In a real-world application, use a proper logging framework
            e.printStackTrace();
        } finally {
            out.close();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the grid coverage problem.
 * The problem involves finding a k x k subgrid that maximizes the sum of 
 * rows and columns that are fully "contained" within that subgrid.
 */
public class Main {

    public static void main(String[] args) {
        try (InputStream inputStream = System.in;
             PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)))) {

            FastReader sc = new FastReader(inputStream);
            GridSolver solver = new GridSolver(sc);
            solver.solve(out);

        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * Encapsulates the logic for solving the grid problem.
     */
    static class GridSolver {
        private final FastReader reader;
        private int n;
        private int k;
        private char[][] grid;

        // Metadata to store the range of 'B' cells in each row and column
        private int[] firstBInRow;
        private int[] lastBInRow;
        private int[] firstBInCol;
        private int[] lastBInCol;

        public GridSolver(FastReader reader) {
            this.reader = reader;
        }

        /**
         * Main execution flow.
         */
        public void solve(PrintWriter out) {
            if (!readInput()) return;

            computeBounds();
            int emptyCount = countAndNeutralizeEmptyLines();

            int[][] rowCoverage = computeRowCoverageDP();
            int[][] colCoverage = computeColCoverageDP();

            int maxCoverage = findMaxCoverage(rowCoverage, colCoverage);

            out.println(maxCoverage + emptyCount);
        }

        private boolean readInput() {
            try {
                n = reader.nextInt();
                k = reader.nextInt();
                grid = new char[n + 1][n + 1];
                for (int i = 1; i <= n; i++) {
                    String rowStr = reader.next();
                    // Using 1-based indexing to match the original logic
                    for (int j = 1; j <= n; j++) {
                        grid[i][j] = rowStr.charAt(j - 1);
                    }
                }
                return true;
            } catch (Exception e) {
                return false;
            }
        }

        /**
         * Finds the first and last occurrence of 'B' in every row and column.
         */
        private void computeBounds() {
            firstBInRow = new int[n + 1];
            lastBInRow = new int[n + 1];
            firstBInCol = new int[n + 1];
            lastBInCol = new int[n + 1];

            Arrays.fill(firstBInRow, Integer.MAX_VALUE);
            Arrays.fill(firstBInCol, Integer.MAX_VALUE);
            Arrays.fill(lastBInRow, 0);
            Arrays.fill(lastBInCol, 0);

            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    if (grid[i][j] == 'B') {
                        firstBInRow[i] = Math.min(firstBInRow[i], j);
                        lastBInRow[i] = Math.max(lastBInRow[i], j);
                        firstBInCol[j] = Math.min(firstBInCol[j], i);
                        lastBInCol[j] = Math.max(lastBInCol[j], i);
                    }
                }
            }
        }

        /**
         * Counts empty rows and columns and modifies their bounds so they 
         * do not satisfy the "contained" condition in the DP phase.
         */
        private int countAndNeutralizeEmptyLines() {
            int count = 0;
            for (int i = 1; i <= n; i++) {
                // Check if row is empty
                if (firstBInRow[i] == Integer.MAX_VALUE && lastBInRow[i] == 0) {
                    count++;
                    firstBInRow[i] = -1; // Out of bounds for window [j, j+k-1]
                    lastBInRow[i] = n + 1;
                }
                // Check if column is empty
                if (firstBInCol[i] == Integer.MAX_VALUE && lastBInCol[i] == 0) {
                    count++;
                    firstBInCol[i] = -1;
                    lastBInCol[i] = n + 1;
                }
            }
            return count;
        }

        /**
         * dp1[i][j] = number of rows in the vertical range [i, i+k-1] 
         * whose 'B' cells are all within the horizontal window [j, j+k-1].
         */
        private int[][] computeRowCoverageDP() {
            int[][] dp = new int[n + 1][n + 1];
            int maxStartIdx = n - k + 1;

            for (int j = 1; j <= maxStartIdx; j++) {
                // Base case: window starts at row 1
                int currentCount = 0;
                for (int i = 1; i <= k; i++) {
                    if (isRowContained(i, j, j + k - 1)) {
                        currentCount++;
                    }
                }
                dp[1][j] = currentCount;

                // Sliding window for subsequent rows
                for (int i = 2; i <= maxStartIdx; i++) {
                    int delta = 0;
                    if (isRowContained(i - 1, j, j + k - 1)) delta--;
                    if (isRowContained(i + k - 1, j, j + k - 1)) delta++;
                    dp[i][j] = dp[i - 1][j] + delta;
                }
            }
            return dp;
        }

        /**
         * dp2[i][j] = number of columns in the horizontal range [j, j+k-1] 
         * whose 'B' cells are all within the vertical window [i, i+k-1].
         */
        private int[][] computeColCoverageDP() {
            int[][] dp = new int[n + 1][n + 1];
            int maxStartIdx = n - k + 1;

            for (int i = 1; i <= maxStartIdx; i++) {
                // Base case: window starts at column 1
                int currentCount = 0;
                for (int j = 1; j <= k; j++) {
                    if (isColContained(j, i, i + k - 1)) {
                        currentCount++;
                    }
                }
                dp[i][1] = currentCount;

                // Sliding window for subsequent columns
                for (int j = 2; j <= maxStartIdx; j++) {
                    int delta = 0;
                    if (isColContained(j - 1, i, i + k - 1)) delta--;
                    if (isColContained(j + k - 1, i, i + k - 1)) delta++;
                    dp[i][j] = dp[i][j - 1] + delta;
                }
            }
            return dp;
        }

        private boolean isRowContained(int row, int minCol, int maxCol) {
            return firstBInRow[row] >= minCol && lastBInRow[row] <= maxCol;
        }

        private boolean isColContained(int col, int minRow, int maxRow) {
            return firstBInCol[col] >= minRow && lastBInCol[col] <= maxRow;
        }

        private int findMaxCoverage(int[][] rowCoverage, int[][] colCoverage) {
            int maxVal = 0;
            int maxStartIdx = n - k + 1;
            for (int i = 1; i <= maxStartIdx; i++) {
                for (int j = 1; j <= maxStartIdx; j++) {
                    maxVal = Math.max(maxVal, rowCoverage[i][j] + colCoverage[i][j]);
                }
            }
            return maxVal;
        }
    }

