     * Optimized input reader for faster processing.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * A program to solve the White Lines problem by calculating optimal 
 * coverage of black cells using k-length segments.
 */
public class Main {
    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            WhiteLineSolver solver = new WhiteLineSolver(reader);
            int result = solver.solve();
            writer.println(result);
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    /**
     * Core logic for solving the White Lines problem.
     */
    static class WhiteLineSolver {
        private final FastReader reader;

        public WhiteLineSolver(FastReader reader) {
            this.reader = reader;
        }

        public int solve() {
            int gridSize = reader.nextInt();
            int lineLength = reader.nextInt();

            boolean[][] grid = readGrid(gridSize);

            // Calculate scores for horizontal segments
            int[][] horizontalScores = computeCoverageScores(grid, lineLength);

            // Transpose the grid to calculate vertical segment scores using the same logic
            boolean[][] transposedGrid = transpose(grid);
            int[][] verticalScores = computeCoverageScores(transposedGrid, lineLength);

            // Find max score by combining horizontal and vertical coverage
            // scores[i][j] is vertical coverage at col j, rows [i, i+k-1]
            // verticalScores[j][i] is horizontal coverage at row i, cols [j, j+k-1]
            int maxScore = 0;
            int segmentCount = gridSize - lineLength + 1;
            for (int i = 0; i < segmentCount; i++) {
                for (int j = 0; j < segmentCount; j++) {
                    maxScore = Math.max(maxScore, horizontalScores[i][j] + verticalScores[j][i]);
                }
            }

            // Add bonus for rows and columns that contain no black cells
            maxScore += countEmptyRowsAndCols(grid);

            return maxScore;
        }

        private boolean[][] readGrid(int n) {
            boolean[][] grid = new boolean[n][n];
            for (int i = 0; i < n; i++) {
                String row = reader.next();
                for (int j = 0; j < n; j++) {
                    grid[i][j] = (row.charAt(j) == 'B');
                }
            }
            return grid;
        }

        /**
         * Computes a score matrix where score[i][j] represents the number of rows 
         * in the vertical window [i, i + k - 1] where the segment at column j 
         * covers all black cells in that row.
         */
        private int[][] computeCoverageScores(boolean[][] grid, int k) {
            int n = grid.length;
            int segmentCount = n - k + 1;
            int[][] isValidSegmentInRow = new int[n][segmentCount];

            for (int i = 0; i < n; i++) {
                int firstBlack = -1;
                int lastBlack = -1;

                // Find the bounds of black cells in this row
                for (int j = 0; j < n; j++) {
                    if (grid[i][j]) {
                        if (firstBlack == -1) firstBlack = j;
                        lastBlack = j;
                    }
                }

                // If row has black cells, mark which segments cover them all
                if (firstBlack != -1) {
                    for (int j = 0; j < segmentCount; j++) {
                        if (j <= firstBlack && lastBlack <= j + k - 1) {
                            isValidSegmentInRow[i][j] = 1;
                        }
                    }
                }
            }

            int[][] scores = new int[segmentCount][segmentCount];
            for (int j = 0; j < segmentCount; j++) {
                // Use prefix sums for efficient sliding window vertical calculation
                int[] colPrefixSum = new int[n + 1];
                for (int i = 0; i < n; i++) {
                    colPrefixSum[i + 1] = colPrefixSum[i] + isValidSegmentInRow[i][j];
                }

                for (int i = 0; i < segmentCount; i++) {
                    scores[i][j] = colPrefixSum[i + k] - colPrefixSum[i];
                }
            }
            return scores;
        }

        private boolean[][] transpose(boolean[][] grid) {
            int n = grid.length;
            boolean[][] transposed = new boolean[n][n];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    transposed[i][j] = grid[j][i];
                }
            }
            return transposed;
        }

        private int countEmptyRowsAndCols(boolean[][] grid) {
            int n = grid.length;
            boolean[] rowHasBlack = new boolean[n];
            boolean[] colHasBlack = new boolean[n];

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (grid[i][j]) {
                        rowHasBlack[i] = true;
                        colHasBlack[j] = true;
                    }
                }
            }

            int emptyCount = 0;
            for (boolean hasBlack : rowHasBlack) {
                if (!hasBlack) emptyCount++;
            }
            for (boolean hasBlack : colHasBlack) {
                if (!hasBlack) emptyCount++;
            }
            return emptyCount;
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.StringTokenizer;

/**
 * GridPatternAnalyzer solves a grid-based problem determining the maximum coverage
 * of rows and columns given specific constraints on 'B' character placement.
 */
public class GridPatternAnalyzer {

    private static final int INF = Integer.MAX_VALUE;

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        int gridSize = reader.nextInt();
        int windowSize = reader.nextInt();

        char[][] grid = new char[gridSize][];
        for (int i = 0; i < gridSize; i++) {
            grid[i] = reader.next().toCharArray();
        }

        GridPatternAnalyzer analyzer = new GridPatternAnalyzer();
        long result = analyzer.solve(gridSize, windowSize, grid);
        System.out.println(result);
    }

    /**
     * Core logic to process the grid and find the maximum possible score.
     */
    public long solve(int n, int k, char[][] grid) {
        int[] minRowInCol = new int[n];
        int[] maxRowInCol = new int[n];
        int[] minColInRow = new int[n];
        int[] maxColInRow = new int[n];

        Arrays.fill(minRowInCol, INF);
        Arrays.fill(maxRowInCol, -1);
        Arrays.fill(minColInRow, INF);
        Arrays.fill(maxColInRow, -1);

        // Step 1: Find the bounding boxes of 'B' characters for every row and column
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 'B') {
                    minRowInCol[j] = Math.min(minRowInCol[j], i);
                    maxRowInCol[j] = Math.max(maxRowInCol[j], i);
                    minColInRow[i] = Math.min(minColInRow[i], j);
                    maxColInRow[i] = Math.max(maxColInRow[i], j);
                }
            }
        }

        // Step 2: Use difference arrays to track how many rows/cols can be satisfied
        // We use n + 2 to prevent index out of bounds during prefix sum operations
        int[][] rowCoverage = new int[n][n + 2];
        int[][] colCoverage = new int[n][n + 2];
        int emptyLinesAndColsCount = 0;

        for (int i = 0; i < n; i++) {
            // Count rows and columns that contain no 'B' characters
            if (maxRowInCol[i] == -1) emptyLinesAndColsCount++;
            if (maxColInRow[i] == -1) emptyLinesAndColsCount++;

            // If the vertical span of 'B's in column i fits within window k, 
            // calculate the range of rows it can potentially satisfy.
            if (maxRowInCol[i] != -1 && (maxRowInCol[i] - minRowInCol[i] + 1) <= k) {
                int diff = k - (maxRowInCol[i] - minRowInCol[i] + 1);
                int startRange = Math.max(0, minRowInCol[i] - diff);
                int endRange = minRowInCol[i] + diff; // Logic derived from original code

                // The original logic updates rows j in [i-k+1, i]
                // This effectively applies a sliding window/difference array approach
                for (int j = i; j >= 0 && j > i - k; j--) {
                    colCoverage[j][startRange]++;
                    colCoverage[j][minRowInCol[i] + 1]--;
                }
            }

            // Repeat similar logic for the horizontal span of 'B's in row i
            if (maxColInRow[i] != -1 && (maxColInRow[i] - minColInRow[i] + 1) <= k) {
                int diff = k - (maxColInRow[i] - minColInRow[i] + 1);
                int startRange = Math.max(0, minColInRow[i] - diff);

                for (int j = i; j >= 0 && j > i - k; j--) {
                    rowCoverage[j][startRange]++;
                    rowCoverage[j][minColInRow[i] + 1]--;
                }
            }
        }

        // Step 3: Convert difference arrays into actual coverage counts using prefix sums
        for (int i = 0; i < n; i++) {
            for (int j = 1; j < n + 2; j++) {
                rowCoverage[i][j] += rowCoverage[i][j - 1];
                colCoverage[i][j] += colCoverage[i][j - 1];
            }
        }

        // Step 4: Find the maximum combined coverage
        long maxScore = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                maxScore = Math.max(maxScore, (long) rowCoverage[i][j] + colCoverage[j][i]);
            }
        }

        return maxScore + emptyLinesAndColsCount;
    }

    /**
     * FastReader class for efficient input parsing.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * This program solves a grid-based optimization problem.
 * It calculates the maximum sum of full rows, full columns, and specific 
 * "gap" patterns within a k x k block in an n x n grid of characters.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        try {
            int n = reader.nextInt();
            int k = reader.nextInt();
            char[][] grid = new char[n][n];
            for (int i = 0; i < n; i++) {
                grid[i] = reader.next().toCharArray();
            }

            Solver solver = new Solver(n, k, grid);
            System.out.println(solver.solve());
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    static class Solver {
        private final int n;
        private final int k;
        private final char[][] grid;

        // Prefix/Suffix sums for counting 'W' (white cells) in rows and columns
        private final int[][] rowWhiteCount;
        private final int[][] rowWhiteCountSuffix;
        private final int[][] colWhiteCount;
        private final int[][] colWhiteCountSuffix;

        // Pattern counters: Counting rows/cols that are "full" (all 'W')
        private final int[] fullRowPrefixSum;
        private final int[] fullRowSuffixSum;
        private final int[] fullColPrefixSum;
        private final int[] fullColSuffixSum;

        // 2D Prefix sums for counting specific "gap" patterns
        // rowGapCountInColumn[i][j]: number of rows up to i in column j that satisfy the row-gap pattern
        private final int[][] rowGapCountInColumn;
        // colGapCountInRow[i][j]: number of columns up to j in row i that satisfy the col-gap pattern
        private final int[][] colGapCountInRow;

        public Solver(int n, int k, char[][] grid) {
            this.n = n;
            this.k = k;
            this.grid = grid;

            this.rowWhiteCount = new int[n + 1][n + 1];
            this.rowWhiteCountSuffix = new int[n + 1][n + 2];
            this.colWhiteCount = new int[n + 1][n + 1];
            this.colWhiteCountSuffix = new int[n + 2][n + 1];

            this.fullRowPrefixSum = new int[n + 1];
            this.fullRowSuffixSum = new int[n + 2];
            this.fullColPrefixSum = new int[n + 1];
            this.fullColSuffixSum = new int[n + 2];

            this.rowGapCountInColumn = new int[n + 1][n + 1];
            this.colGapCountInRow = new int[n + 1][n + 1];

            preprocessWhiteCounts();
            preprocessFullLines();
            preprocessGapPatterns();
        }

        /**
         * Precalculates the number of 'W' characters in every row and column 
         * using prefix and suffix sums.
         */
        private void preprocessWhiteCounts() {
            // Column-wise prefix and suffix sums
            for (int j = 1; j <= n; j++) {
                for (int i = 1; i <= n; i++) {
                    colWhiteCount[i][j] = colWhiteCount[i - 1][j];
                    if (grid[i - 1][j - 1] == 'W') colWhiteCount[i][j]++;
                }
                for (int i = n; i >= 1; i--) {
                    colWhiteCountSuffix[i][j] = colWhiteCountSuffix[i + 1][j];
                    if (grid[i - 1][j - 1] == 'W') colWhiteCountSuffix[i][j]++;
                }
            }

            // Row-wise prefix and suffix sums
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    rowWhiteCount[i][j] = rowWhiteCount[i][j - 1];
                    if (grid[i - 1][j - 1] == 'W') rowWhiteCount[i][j]++;
                }
                for (int j = n; j >= 1; j--) {
                    rowWhiteCountSuffix[i][j] = rowWhiteCountSuffix[i][j + 1];
                    if (grid[i - 1][j - 1] == 'W') rowWhiteCountSuffix[i][j]++;
                }
            }
        }

        /**
         * Identifies lines (rows or columns) that consist entirely of 'W'.
         */
        private void preprocessFullLines() {
            for (int i = 1; i <= n; i++) {
                fullRowPrefixSum[i] = fullRowPrefixSum[i - 1];
                if (rowWhiteCount[i][n] == n) fullRowPrefixSum[i]++;

                fullRowSuffixSum[i] = (i == n) ? 0 : fullRowSuffixSum[i + 1]; // Placeholder logic
            }
            // Correct suffix sum for rows
            for (int i = n; i >= 1; i--) {
                fullRowSuffixSum[i] = fullRowSuffixSum[i + 1] + (rowWhiteCount[i][n] == n ? 1 : 0);
            }

            for (int j = 1; j <= n; j++) {
                fullColPrefixSum[j] = fullColPrefixSum[j - 1];
                if (colWhiteCount[n][j] == n) fullColPrefixSum[j]++;
            }
            for (int j = n; j >= 1; j--) {
                fullColSuffixSum[j] = fullColSuffixSum[j + 1] + (colWhiteCount[n][j] == n ? 1 : 0);
            }
        }

        /**
         * Detects rows or columns that are "almost full", meaning they are all 'W'
         * except for a gap of size 'k'.
         */
        private void preprocessGapPatterns() {
            // 1. Identify column gaps: column j is all 'W' except for a block of k rows ending at i
            for (int j = 1; j <= n; j++) {
                for (int i = k; i <= n; i++) {
                    boolean topIsWhite = colWhiteCount[i - k][j] == (i - k);
                    boolean bottomIsWhite = colWhiteCountSuffix[i + 1][j] == (n - i);
                    if (topIsWhite && bottomIsWhite) {
                        colGapCountInRow[i][j] = 1;
                    }
                }
            }

            // 2. Identify row gaps: row i is all 'W' except for a block of k columns ending at j
            for (int i = 1; i <= n; i++) {
                for (int j = k; j <= n; j++) {
                    boolean leftIsWhite = rowWhiteCount[i][j - k] == (j - k);
                    boolean rightIsWhite = rowWhiteCountSuffix[i][j + 1] == (n - j);
                    if (leftIsWhite && rightIsWhite) {
                        rowGapCountInColumn[i][j] = 1;
                    }
                }
            }

            // Convert markers into 2D prefix sums for range queries
            // colGapCountInRow becomes prefix sum across columns for each row
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    colGapCountInRow[i][j] += colGapCountInRow[i][j - 1];
                }
            }
            // rowGapCountInColumn becomes prefix sum across rows for each column
            for (int j = 1; j <= n; j++) {
                for (int i = 1; i <= n; i++) {
                    rowGapCountInColumn[i][j] += rowGapCountInColumn[i - 1][j];
                }
            }
        }

        /**
         * Computes the final answer by iterating through all possible k x k blocks.
         */
        public int solve() {
            // Base answer: sum of all full rows and full columns
            int maxScore = fullRowPrefixSum[n] + fullColPrefixSum[n];

            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    int startRow = i - k + 1;
                    int startCol = j - k + 1;

                    // Block must be within grid boundaries
                    if (startRow <= 0 || startCol <= 0) continue;

                    // Calculate score: 
                    // (full rows before block) + (full rows after block) + 
                    // (full columns before block) + (full columns after block) +
                    // (count of row-gap patterns in column j intersecting block) +
                    // (count of col-gap patterns in row i intersecting block)
                    int currentScore = fullRowPrefixSum[startRow - 1]
                                     + fullRowSuffixSum[i + 1]
                                     + fullColPrefixSum[startCol - 1]
                                     + fullColSuffixSum[j + 1]
                                     + (rowGapCountInColumn[i][j] - rowGapCountInColumn[startRow - 1][j])
                                     + (colGapCountInRow[i][j] - colGapCountInRow[i][startCol - 1]);

                    maxScore = Math.max(maxScore, currentScore);
                }
            }

            return maxScore;
        }
    }

    /**
     * High-performance input reader.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }
}

import java.io.BufferedInputStream;
import java.io.IOException;
import java.util.Scanner;

/**
 * GridBonusSolver calculates the maximum "bonus" achievable in a grid 
 * based on the concentration of specific characters ('B') within 
 * sliding windows of a given size.
 */
public class GridBonusSolver {

    public static void main(String[] args) {
        try {
            GridBonusSolver solver = new GridBonusSolver();
            solver.run();
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    public void run() throws IOException {
        // Use a large buffer for efficient reading of large grids
        Scanner sc = new Scanner(new BufferedInputStream(System.in, 1 << 19));

        if (!sc.hasNextInt()) return;
        int gridSize = sc.nextInt();

        if (!sc.hasNextInt()) return;
        int kOriginal = sc.nextInt();
        // The window size used in calculation is kOriginal. 
        // We use kOffset = kOriginal - 1 to define the range [i, i + kOffset].
        int kOffset = kOriginal - 1;

        char[][] grid = new char[gridSize][gridSize];
        for (int i = 0; i < gridSize; i++) {
            grid[i] = sc.next().toCharArray();
        }

        // 1. Compute Prefix Sums for rows and columns
        int[][] rowPrefixSum = computeRowPrefixSums(grid, gridSize);
        int[][] colPrefixSum = computeColPrefixSums(grid, gridSize);

        // 2. Calculate initial bonus from empty rows and columns
        int emptyRowsAndColsCount = countEmptyRowsAndCols(rowPrefixSum, colPrefixSum, gridSize);

        // 3. Calculate bonuses for vertical and horizontal segments
        int[][] verticalBonus = computeVerticalBonuses(colPrefixSum, gridSize, kOffset);
        int[][] horizontalBonus = computeHorizontalBonuses(rowPrefixSum, gridSize, kOffset);

        // 4. Create 2D prefix sums of the bonuses to allow O(1) range queries
        int[][] rowPrefixSumOfVerticalBonuses = computeRowPrefixSumOfBonuses(verticalBonus, gridSize);
        int[][] colPrefixSumOfHorizontalBonuses = computeColPrefixSumOfBonuses(horizontalBonus, gridSize);

        // 5. Find the maximum bonus within the allowed subgrid dimensions
        int maxBonus = findMaxBonus(rowPrefixSumOfVerticalBonuses, colPrefixSumOfHorizontalBonuses, gridSize, kOffset);

        System.out.println(maxBonus + emptyRowsAndColsCount);
    }

    private int[][] computeRowPrefixSums(char[][] grid, int n) {
        int[][] rowPrefixSum = new int[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int val = (grid[i][j] == 'B') ? 1 : 0;
                rowPrefixSum[i][j] = (j > 0 ? rowPrefixSum[i][j - 1] : 0) + val;
            }
        }
        return rowPrefixSum;
    }

    private int[][] computeColPrefixSums(char[][] grid, int n) {
        int[][] colPrefixSum = new int[n][n];
        for (int j = 0; j < n; j++) {
            for (int i = 0; i < n; i++) {
                int val = (grid[i][j] == 'B') ? 1 : 0;
                colPrefixSum[i][j] = (i > 0 ? colPrefixSum[i - 1][j] : 0) + val;
            }
        }
        return colPrefixSum;
    }

    private int countEmptyRowsAndCols(int[][] rowPrefixSum, int[][] colPrefixSum, int n) {
        int count = 0;
        for (int i = 0; i < n; i++) {
            if (colPrefixSum[n - 1][i] == 0) count++; // Column i is empty
            if (rowPrefixSum[i][n - 1] == 0) count++; // Row i is empty
        }
        return count;
    }

    private int[][] computeVerticalBonuses(int[][] colPrefixSum, int n, int kOffset) {
        int[][] verticalBonus = new int[n][n];
        for (int i = 0; i <= n - (kOffset + 1); i++) {
            for (int j = 0; j < n; j++) {
                int totalBsInCol = colPrefixSum[n - 1][j];
                int bsInWindow = colPrefixSum[i + kOffset][j] - (i > 0 ? colPrefixSum[i - 1][j] : 0);

                // A column gives a bonus if all its 'B's are contained within the window
                if (totalBsInCol > 0 && bsInWindow == totalBsInCol) {
                    verticalBonus[i][j] = 1;
                } else if (totalBsInCol == 0) {
                    // Following original logic: if col is empty, bonus is 0
                    verticalBonus[i][j] = 0;
                }
            }
        }
        return verticalBonus;
    }

    private int[][] computeHorizontalBonuses(int[][] rowPrefixSum, int n, int kOffset) {
        int[][] horizontalBonus = new int[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j <= n - (kOffset + 1); j++) {
                int totalBsInRow = rowPrefixSum[i][n - 1];
                int bsInWindow = rowPrefixSum[i][j + kOffset] - (j > 0 ? rowPrefixSum[i][j - 1] : 0);

                if (totalBsInRow > 0 && bsInWindow == totalBsInRow) {
                    horizontalBonus[i][j] = 1;
                } else if (totalBsInRow == 0) {
                    horizontalBonus[i][j] = 0;
                }
            }
        }
        return horizontalBonus;
    }

    private int[][] computeRowPrefixSumOfBonuses(int[][] bonusGrid, int n) {
        int[][] prefixSum = new int[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                prefixSum[i][j] = (j > 0 ? prefixSum[i][j - 1] : 0) + bonusGrid[i][j];
            }
        }
        return prefixSum;
    }

    private int[][] computeColPrefixSumOfBonuses(int[][] bonusGrid, int n) {
        int[][] prefixSum = new int[n][n];
        for (int j = 0; j < n; j++) {
            for (int i = 0; i < n; i++) {
                prefixSum[i][j] = (i > 0 ? prefixSum[i - 1][j] : 0) + bonusGrid[i][j];
            }
        }
        return prefixSum;
    }

    private int findMaxBonus(int[][] rowPrefixSumV, int[][] colPrefixSumH, int n, int kOffset) {
        int maxBonus = 0;
        // Search through all possible top-left corners (i, j) of the subgrid
        for (int i = 0; i < n - kOffset; i++) {
            for (int j = 0; j < n - kOffset; j++) {
                int verticalBonusInWindow = rowPrefixSumV[i][j + kOffset] - (j > 0 ? rowPrefixSumV[i][j - 1] : 0);
                int horizontalBonusInWindow = colPrefixSumH[i + kOffset][j] - (i > 0 ? colPrefixSumH[i - 1][j] : 0);

                maxBonus = Math.max(maxBonus, verticalBonusInWindow + horizontalBonusInWindow);
            }
        }
        return maxBonus;
    }
}

