/**
 * Handles high-performance grid overlap calculations using 2D difference arrays.
 */
class GridOverlapSolver {
    private int gridSize;
    private int squareSize;
    private int[][] differenceArray;

    /**
     * Solves the grid problem based on the provided input.
     * 
     * @param in  The fast input reader.
     * @param out The fast output writer.
     * @throws IOException If an I/O error occurs.
     */
    public void solve(FastReader in, FastWriter out) throws IOException {
        gridSize = in.nextInt();
        squareSize = in.nextInt();

        if (gridSize <= 0) {
            out.println(0);
            return;
        }

        int[][] grid = new int[gridSize + 1][gridSize + 1];
        for (int i = 1; i <= gridSize; i++) {
            for (int j = 1; j <= gridSize; j++) {
                grid[i][j] = (in.nextChar() == 'B') ? 1 : 0;
            }
        }

        differenceArray = new int[gridSize + 1][gridSize + 1];

        // Process rows: Find the range of top-left corners of KxK squares 
        // that cover all 'B's in each row.
        for (int i = 1; i <= gridSize; i++) {
            int minCol = gridSize + 1;
            int maxCol = 0;
            for (int j = 1; j <= gridSize; j++) {
                if (grid[i][j] == 1) {
                    minCol = Math.min(minCol, j);
                    maxCol = Math.max(maxCol, j);
                }
            }

            if (minCol > maxCol) {
                // If no 'B' is found in the row, increment the global coverage.
                differenceArray[1][1]++;
            } else {
                // Column range: [maxCol - K + 1, minCol]
                // Row range: [i - K + 1, i]
                updateDifferenceArray(maxCol - squareSize + 1, minCol, i - squareSize + 1, i);
            }
        }

        // Process columns: Find the range of top-left corners of KxK squares 
        // that cover all 'B's in each column.
        for (int j = 1; j <= gridSize; j++) {
            int minRow = gridSize + 1;
            int maxRow = 0;
            for (int i = 1; i <= gridSize; i++) {
                if (grid[i][j] == 1) {
                    minRow = Math.min(minRow, i);
                    maxRow = Math.max(maxRow, i);
                }
            }

            if (minRow > maxRow) {
                differenceArray[1][1]++;
            } else {
                // Column range: [j - K + 1, j]
                // Row range: [maxRow - K + 1, minRow]
                updateDifferenceArray(j - squareSize + 1, j, maxRow - squareSize + 1, minRow);
            }
        }

        // Compute 2D prefix sum to find the maximum overlap
        int maxOverlap = 0;
        for (int i = 1; i <= gridSize; i++) {
            for (int j = 1; j <= gridSize; j++) {
                differenceArray[i][j] += differenceArray[i - 1][j] 
                                       + differenceArray[i][j - 1] 
                                       - differenceArray[i - 1][j - 1];
                maxOverlap = Math.max(maxOverlap, differenceArray[i][j]);
            }
        }

        out.println(maxOverlap);
    }

    /**
     * Applies a rectangular update to the 2D difference array.
     */
    private void updateDifferenceArray(int colStart, int colEnd, int rowStart, int rowEnd) {
        int c1 = Math.max(colStart, 1);
        int c2 = Math.min(colEnd, gridSize);
        int r1 = Math.max(rowStart, 1);
        int r2 = Math.min(rowEnd, gridSize);

        if (c1 > c2 || r1 > r2) {
            return;
        }

        differenceArray[r1][c1]++;
        if (r2 + 1 <= gridSize) {
            differenceArray[r2 + 1][c1]--;
        }
        if (c2 + 1 <= gridSize) {
            differenceArray[r1][c2 + 1]--;
        }
        if (r2 + 1 <= gridSize && c2 + 1 <= gridSize) {
            differenceArray[r2 + 1][c2 + 1]++;
        }
    }
}

/**
 * High-performance input reader.
 */
class FastReader implements AutoCloseable {
    private final InputStream inputStream;
    private final byte[] buffer = new byte[1 << 16];
    private int bufferPointer = 0;
    private int bytesRead = 0;

    public FastReader(InputStream is) {
        this.inputStream = is;
    }

    private int readByte() throws IOException {
        if (bufferPointer == bytesRead) {
            fillBuffer();
            if (bytesRead == -1) return -1;
        }
        return buffer[bufferPointer++] & 0xFF;
    }

    private void fillBuffer() throws IOException {
        bytesRead = inputStream.read(buffer, 0, buffer.length);
        bufferPointer = 0;
    }

    public int nextInt() throws IOException {
        int c = readByte();
        while (c != -1 && c <= 32) c = readByte();
        if (c == -1) return -1;

        int sign = 1;
        if (c == '-') {
            sign = -1;
            c = readByte();
        }

        int res = 0;
        while (c >= '0' && c <= '9') {
            res = res * 10 + (c - '0');
            c = readByte();
        }
        return res * sign;
    }

    public char nextChar() throws IOException {
        int c = readByte();
        while (c != -1 && c <= 32) c = readByte();
        return (char) c;
    }

    @Override
    public void close() throws IOException {
        inputStream.close();
    }
}

/**
 * High-performance output writer.
 */
class FastWriter implements AutoCloseable {
    private final PrintWriter writer;

    public FastWriter(OutputStream os) {
        this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(os)));
    }

    public void println(int val) {
        writer.println(val);
    }

    @Override
    public void close() {
        writer.flush();
        writer.close();
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to solve the problem of finding the maximum number of rows and columns 
 * that can be covered by a single KxK square such that all black cells in those 
 * rows/columns are contained within the square.
 */
public class GridCoverageProblem {

    public static void main(String[] args) {
        try {
            FastReader reader = new FastReader(System.in);
            GridSolver solver = new GridSolver(reader);
            solver.solve();
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }
}

class GridSolver {
    private final FastReader reader;
    private int gridSize;
    private int segmentLength;
    private boolean[][] isBlackCell;
    private int[][] differenceArray;

    public GridSolver(FastReader reader) {
        this.reader = reader;
    }

    /**
     * Orchestrates the solving process.
     */
    public void solve() throws IOException {
        readInput();

        processRows();
        processColumns();

        computePrefixSums();

        int maxCoverage = findMaximumValue();
        System.out.println(maxCoverage);
    }

    private void readInput() throws IOException {
        gridSize = reader.nextInt();
        segmentLength = reader.nextInt();
        isBlackCell = new boolean[gridSize][gridSize];
        differenceArray = new int[gridSize][gridSize];

        for (int i = 0; i < gridSize; i++) {
            String rowString = reader.next();
            for (int j = 0; j < gridSize; j++) {
                isBlackCell[i][j] = (rowString.charAt(j) == 'B');
            }
        }
    }

    /**
     * Identifies rows where all 'B' cells can be covered by a K-length segment.
     * Updates the difference array with the valid top-left corner ranges.
     */
    private void processRows() {
        for (int i = 0; i < gridSize; i++) {
            int firstBlackCol = Integer.MAX_VALUE;
            int lastBlackCol = Integer.MIN_VALUE;

            for (int j = 0; j < gridSize; j++) {
                if (isBlackCell[i][j]) {
                    firstBlackCol = Math.min(firstBlackCol, j);
                    lastBlackCol = Math.max(lastBlackCol, j);
                }
            }

            if (lastBlackCol == Integer.MIN_VALUE) {
                // No black cells in this row: any square covers "all" black cells.
                applyRangeUpdate(0, 0, gridSize - 1, gridSize - 1);
            } else if (lastBlackCol - firstBlackCol < segmentLength) {
                // Valid row: calculate range of top-left corners (R, C) 
                // that cover all 'B' cells in this row.
                int r1 = Math.max(0, i - segmentLength + 1);
                int r2 = i;
                int c1 = Math.max(0, lastBlackCol - segmentLength + 1);
                int c2 = firstBlackCol;
                applyRangeUpdate(r1, c1, r2, c2);
            }
        }
    }

    /**
     * Identifies columns where all 'B' cells can be covered by a K-length segment.
     */
    private void processColumns() {
        for (int j = 0; j < gridSize; j++) {
            int firstBlackRow = Integer.MAX_VALUE;
            int lastBlackRow = Integer.MIN_VALUE;

            for (int i = 0; i < gridSize; i++) {
                if (isBlackCell[i][j]) {
                    firstBlackRow = Math.min(firstBlackRow, i);
                    lastBlackRow = Math.max(lastBlackRow, i);
                }
            }

            if (lastBlackRow == Integer.MIN_VALUE) {
                applyRangeUpdate(0, 0, gridSize - 1, gridSize - 1);
            } else if (lastBlackRow - firstBlackRow < segmentLength) {
                // Valid column: calculate range of top-left corners (R, C)
                int r1 = Math.max(0, lastBlackRow - segmentLength + 1);
                int r2 = firstBlackRow;
                int c1 = Math.max(0, j - segmentLength + 1);
                int c2 = j;
                applyRangeUpdate(r1, c1, r2, c2);
            }
        }
    }

    /**
     * Standard 2D Difference Array update to allow range additions in O(1).
     */
    private void applyRangeUpdate(int r1, int c1, int r2, int c2) {
        r1 = Math.max(r1, 0);
        r2 = Math.min(r2, gridSize - 1);
        c1 = Math.max(c1, 0);
        c2 = Math.min(c2, gridSize - 1);

        if (r1 <= r2 && c1 <= c2) {
            differenceArray[r1][c1]++;
            if (r2 + 1 < gridSize) {
                differenceArray[r2 + 1][c1]--;
            }
            if (c2 + 1 < gridSize) {
                differenceArray[r1][c2 + 1]--;
            }
            if (r2 + 1 < gridSize && c2 + 1 < gridSize) {
                differenceArray[r2 + 1][c2 + 1]++;
            }
        }
    }

    /**
     * Converts the difference array into a prefix sum array (the actual coverage counts).
     */
    private void computePrefixSums() {
        // Horizontal prefix sum
        for (int i = 0; i < gridSize; i++) {
            for (int j = 1; j < gridSize; j++) {
                differenceArray[i][j] += differenceArray[i][j - 1];
            }
        }
        // Vertical prefix sum
        for (int j = 0; j < gridSize; j++) {
            for (int i = 1; i < gridSize; i++) {
                differenceArray[i][j] += differenceArray[i - 1][j];
            }
        }
    }

    private int findMaximumValue() {
        int maxVal = 0;
        for (int i = 0; i < gridSize; i++) {
            for (int j = 0; j < gridSize; j++) {
                maxVal = Math.max(maxVal, differenceArray[i][j]);
            }
        }
        return maxVal;
    }
}

