import java.util.*;

/**
 * A program to find the maximum number of "cleared" rows and columns 
 * within a k x k subgrid. A row is "cleared" if all 'B' characters 
 * in that row fall within the horizontal range of the k x k subgrid.
 */
public class GridAnalyzer {

    private static class Boundaries {
        int min = Integer.MAX_VALUE;
        int max = Integer.MIN_VALUE;
        boolean isEmpty = true;

        void update(int index) {
            isEmpty = false;
            min = Math.min(min, index);
            max = Math.max(max, index);
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextInt()) return;

        int n = sc.nextInt();
        int k = sc.nextInt();
        char[][] grid = new char[n][n];

        for (int i = 0; i < n; i++) {
            String line = sc.next();
            grid[i] = line.toCharArray();
        }

        // Edge case: If k is larger than or equal to n, all rows and columns 
        // are considered cleared by the single available n x n window.
        if (k >= n) {
            System.out.println(2 * n);
            return;
        }

        System.out.println(solve(n, k, grid));
    }

    private static int solve(int n, int k, char[][] grid) {
        Boundaries[] rowBounds = new Boundaries[n];
        Boundaries[] colBounds = new Boundaries[n];

        for (int i = 0; i < n; i++) {
            rowBounds[i] = new Boundaries();
            colBounds[i] = new Boundaries();
        }

        // Preprocess: Find the first and last occurrence of 'B' in every row and column
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 'B') {
                    rowBounds[r].update(c);
                    colBounds[c].update(r);
                }
            }
        }

        // colClearedCount[i][j] stores how many columns in the window [j, j+k-1]
        // are "cleared" (all 'B's fall within the vertical window [i, i+k-1]).
        int[][] colClearedCount = new int[n][n];

        for (int i = 0; i <= n - k; i++) {
            int[] colOk = new int[n];
            int rowWindowStart = i;
            int rowWindowEnd = i + k - 1;

            for (int c = 0; c < n; c++) {
                if (colBounds[c].isEmpty || 
                   (colBounds[c].min >= rowWindowStart && colBounds[c].max <= rowWindowEnd)) {
                    colOk[c] = 1;
                } else {
                    colOk[c] = 0;
                }
            }

            // Use sliding window to fill colClearedCount for row-window i
            int currentWindowSum = 0;
            for (int c = 0; c < k; c++) {
                currentWindowSum += colOk[c];
            }
            colClearedCount[i][0] = currentWindowSum;

            for (int j = 1; j <= n - k; j++) {
                currentWindowSum = currentWindowSum - colOk[j - 1] + colOk[j + k - 1];
                colClearedCount[i][j] = currentWindowSum;
            }
        }

        int maxCleared = 0;

        // For every column window j, calculate how many rows are cleared by it
        // and combine with the precomputed column counts.
        for (int j = 0; j <= n - k; j++) {
            int[] rowOk = new int[n];
            int colWindowStart = j;
            int colWindowEnd = j + k - 1;

            for (int r = 0; r < n; r++) {
                if (rowBounds[r].isEmpty || 
                   (rowBounds[r].min >= colWindowStart && rowBounds[r].max <= colWindowEnd)) {
                    rowOk[r] = 1;
                } else {
                    rowOk[r] = 0;
                }
            }

            // Sliding window to find rows cleared in window [i, i+k-1]
            int currentWindowSum = 0;
            for (int r = 0; r < k; r++) {
                currentWindowSum += rowOk[r];
            }
            maxCleared = Math.max(maxCleared, currentWindowSum + colClearedCount[0][j]);

            for (int i = 1; i <= n - k; i++) {
                currentWindowSum = currentWindowSum - rowOk[i - 1] + rowOk[i + k - 1];
                maxCleared = Math.max(maxCleared, currentWindowSum + colClearedCount[i][j]);
            }
        }

        return maxCleared;
    }
}

import java.io.*;
import java.util.*;

/**
 * Solver for finding the maximum coverage of a grid using k x k squares,
 * considering the influence of empty rows and columns.
 */
public class GridCoverageSolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int gridSize = reader.nextInt();
            int squareSize = reader.nextInt();

            boolean[][] grid = new boolean[gridSize][gridSize];
            for (int i = 0; i < gridSize; i++) {
                String row = reader.next();
                for (int j = 0; j < gridSize; j++) {
                    grid[i][j] = (row.charAt(j) == 'B');
                }
            }

            GridProblemEngine engine = new GridProblemEngine(gridSize, squareSize, grid);
            int result = engine.solve();

            writer.println(result);
        } catch (IOException e) {
            writer.println("Error reading input: " + e.getMessage());
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Core engine containing the logic for the grid problem.
     */
    static class GridProblemEngine {
        private final int n;
        private final int k;
        private final boolean[][] grid;
        private final int[][] differenceArray;
        private int emptyLineCount = 0;

        public GridProblemEngine(int n, int k, boolean[][] grid) {
            this.n = n;
            this.k = k;
            this.grid = grid;
            // Use n+2 to prevent index out of bounds when applying 2D difference array updates
            this.differenceArray = new int[n + 2][n + 2];
        }

        public int solve() {
            processRows();
            processColumns();
            return calculateMaxCoverage() + emptyLineCount;
        }

        /**
         * Processes each row to find the range of k x k squares that cover the black cells.
         */
        private void processRows() {
            for (int i = 0; i < n; i++) {
                List<Integer> blackCellIndices = new ArrayList<>();
                for (int j = 0; j < n; j++) {
                    if (grid[i][j]) {
                        blackCellIndices.add(j);
                    }
                }

                if (blackCellIndices.isEmpty()) {
                    emptyLineCount++;
                } else {
                    // The range of row-starts that cover this entire row span
                    int rowStartLimit = Math.max(0, i - k + 1);
                    int rowEndLimit = i;

                    // The range of col-starts that cover the entire span of black cells in this row
                    int colStartLimit = Math.max(0, blackCellIndices.get(blackCellIndices.size() - 1) - k + 1);
                    int colEndLimit = blackCellIndices.get(0);

                    if (colEndLimit >= colStartLimit) {
                        applyDifferenceUpdate(rowStartLimit, rowEndLimit, colStartLimit, colEndLimit);
                    }
                }
            }
        }

        /**
         * Processes each column to find the range of k x k squares that cover the black cells.
         */
        private void processColumns() {
            for (int j = 0; j < n; j++) {
                List<Integer> blackCellIndices = new ArrayList<>();
                for (int i = 0; i < n; i++) {
                    if (grid[i][j]) {
                        blackCellIndices.add(i);
                    }
                }

                if (blackCellIndices.isEmpty()) {
                    emptyLineCount++;
                } else {
                    // The range of col-starts that cover this entire column span
                    int colStartLimit = Math.max(0, j - k + 1);
                    int colEndLimit = j;

                    // The range of row-starts that cover the entire span of black cells in this column
                    int rowStartLimit = Math.max(0, blackCellIndices.get(blackCellIndices.size() - 1) - k + 1);
                    int rowEndLimit = blackCellIndices.get(0);

                    if (rowEndLimit >= rowStartLimit) {
                        applyDifferenceUpdate(rowStartLimit, rowEndLimit, colStartLimit, colEndLimit);
                    }
                }
            }
        }

        /**
         * Updates the 2D difference array for a specific rectangular region.
         */
        private void applyDifferenceUpdate(int r1, int r2, int c1, int c2) {
            differenceArray[r1][c1]++;
            differenceArray[r1][c2 + 1]--;
            differenceArray[r2 + 1][c1]--;
            differenceArray[r2 + 1][c2 + 1]++;
        }

        /**
         * Converts the difference array into a 2D prefix sum and finds the maximum value.
         */
        private int calculateMaxCoverage() {
            int maxVal = 0;
            int[][] prefixSum = new int[n + 1][n + 1];

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    int current = differenceArray[i][j];
                    if (i > 0) current += prefixSum[i - 1][j];
                    if (j > 0) current += prefixSum[i][j - 1];
                    if (i > 0 && j > 0) current -= prefixSum[i - 1][j - 1];

                    prefixSum[i][j] = current;
                    maxVal = Math.max(maxVal, current);
                }
            }
            return maxVal;
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * A solver for calculating the maximum number of k*k squares that can be 
 * placed based on the distribution of 'B' characters in an N*N grid.
 */
public class GridOptimizationSolver {

    /**
     * Represents a range of valid top-left corners for a k*k square.
     */
    private static class Rectangle {
        final int x1, x2, y1, y2;

        Rectangle(int x1, int x2, int y1, int y2, int maxBound) {
            // Clamp coordinates to ensure they stay within the valid range [0, n-k]
            this.x1 = Math.max(0, x1);
            this.x2 = Math.min(maxBound, x2);
            this.y1 = Math.max(0, y1);
            this.y2 = Math.min(maxBound, y2);
        }

        boolean isValid() {
            return x1 <= x2 && y1 <= y2;
        }
    }

    private final int n;
    private final int k;
    private final boolean[][] grid;

    public GridOptimizationSolver(int n, int k, boolean[][] grid) {
        this.n = n;
        this.k = k;
        this.grid = grid;
    }

    /**
     * Executes the core logic of the solver.
     * @return The result of max overlaps plus the count of empty lines.
     */
    public int solve() {
        int emptyLineCount = 0;
        List<Rectangle> rectangles = new ArrayList<>();
        int maxPossibleTopLeftCoord = n - k;

        // 1. Process Rows: Find rows where 'B' characters are contained within a k-span
        for (int i = 0; i < n; i++) {
            int firstCol = -1;
            int lastCol = -1;

            for (int j = 0; j < n; j++) {
                if (grid[i][j]) {
                    if (firstCol == -1) firstCol = j;
                    lastCol = j;
                }
            }

            if (firstCol == -1) {
                emptyLineCount++;
            } else if (lastCol - firstCol < k) {
                // A k*k square starting at (r, c) covers this row if:
                // r is in [i - k + 1, i] AND c is in [lastCol - k + 1, firstCol]
                rectangles.add(new Rectangle(i - k + 1, i, lastCol - k + 1, firstCol, maxPossibleTopLeftCoord));
            }
        }

        // 2. Process Columns: Find columns where 'B' characters are contained within a k-span
        for (int j = 0; j < n; j++) {
            int firstRow = -1;
            int lastRow = -1;

            for (int i = 0; i < n; i++) {
                if (grid[i][j]) {
                    if (firstRow == -1) firstRow = i;
                    lastRow = i;
                }
            }

            if (firstRow == -1) {
                emptyLineCount++;
            } else if (lastRow - firstRow < k) {
                // A k*k square starting at (r, c) covers this column if:
                // r is in [lastRow - k + 1, firstRow] AND c is in [j - k + 1, j]
                rectangles.add(new Rectangle(lastRow - k + 1, firstRow, j - k + 1, j, maxPossibleTopLeftCoord));
            }
        }

        return calculateMaxOverlap(rectangles) + emptyLineCount;
    }

    /**
     * Uses a 2D difference array and prefix sum to find the coordinate 
     * covered by the maximum number of rectangles.
     */
    private int calculateMaxOverlap(List<Rectangle> rectangles) {
        if (rectangles.isEmpty()) {
            return 0;
        }

        int[][] differenceArray = new int[n + 1][n + 1];

        for (Rectangle rect : rectangles) {
            if (rect.isValid()) {
                differenceArray[rect.x1][rect.y1]++;
                differenceArray[rect.x1][rect.y2 + 1]--;
                differenceArray[rect.x2 + 1][rect.y1]--;
                differenceArray[rect.x2 + 1][rect.y2 + 1]++;
            }
        }

        int maxOverlap = 0;
        int[][] prefixSumArray = new int[n + 1][n + 1];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                prefixSumArray[i + 1][j + 1] = prefixSumArray[i + 1][j] 
                                             + prefixSumArray[i][j + 1] 
                                             - prefixSumArray[i][j] 
                                             + differenceArray[i][j];
                maxOverlap = Math.max(maxOverlap, prefixSumArray[i + 1][j + 1]);
            }
        }

        return maxOverlap;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int n = scanner.nextInt();
        int k = scanner.nextInt();
        boolean[][] grid = new boolean[n][n];

        for (int i = 0; i < n; i++) {
            String rowString = scanner.next();
            for (int j = 0; j < n; j++) {
                if (rowString.charAt(j) == 'B') {
                    grid[i][j] = true;
                }
            }
        }

        GridOptimizationSolver solver = new GridOptimizationSolver(n, k, grid);
        System.out.println(solver.solve());

        scanner.close();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * A program to calculate the maximum score of a k x k window in a grid.
 * The score is defined by the number of 'clean' rows/columns within the window
 * plus the number of 'empty' rows/columns outside the window.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = reader.nextInt();
            int m = n; // The problem assumes a square grid
            int k = reader.nextInt();

            int[][] grid = new int[n][m];
            for (int i = 0; i < n; i++) {
                String rowString = reader.next();
                for (int j = 0; j < m; j++) {
                    // 'B' represents a black cell (1), others represent white cells (0)
                    grid[i][j] = (rowString.charAt(j) == 'B') ? 1 : 0;
                }
            }

            GridAnalyzer analyzer = new GridAnalyzer(grid, n, m, k);
            out.println(analyzer.calculateMaxScore());

        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Encapsulates the logic for analyzing the grid.
     */
    static class GridAnalyzer {
        private final int[][] grid;
        private final int rows;
        private final int cols;
        private final int k;

        public GridAnalyzer(int[][] grid, int rows, int cols, int k) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
            this.k = k;
        }

        public int calculateMaxScore() {
            int[][] rowPrefixSums = computeRowPrefixSums();
            int[][] colPrefixSums = computeColPrefixSums();
            int[] emptyRowCumulativeCounts = computeEmptyRowCounts(rowPrefixSums);
            int[] emptyColCumulativeCounts = computeEmptyColCounts(colPrefixSums);

            int[][] ans = new int[rows][cols];

            // Step 1: Calculate scores based on row properties
            // cleanRowsInWindowPrefixSum[i][j] stores prefix sum of "clean" rows 
            // (rows where all black cells are within the current column window)
            int[][] cleanRowsInWindowPrefixSum = new int[rows][cols];
            for (int j = 0; j <= cols - k; j++) {
                for (int i = 0; i < rows; i++) {
                    if (isRowCleanInWindow(i, j, rowPrefixSums)) {
                        cleanRowsInWindowPrefixSum[i][j] = 1;
                    }
                    if (i > 0) {
                        cleanRowsInWindowPrefixSum[i][j] += cleanRowsInWindowPrefixSum[i - 1][j];
                    }
                }

                for (int i = 0; i <= rows - k; i++) {
                    int cleanRowsInWindow = cleanRowsInWindowPrefixSum[i + k - 1][j] - (i > 0 ? cleanRowsInWindowPrefixSum[i - 1][j] : 0);
                    int emptyRowsBefore = (i > 0) ? emptyRowCumulativeCounts[i - 1] : 0;
                    int emptyRowsAfter = emptyRowCumulativeCounts[rows - 1] - emptyRowCumulativeCounts[i + k - 1];

                    ans[i][j] = cleanRowsInWindow + emptyRowsBefore + emptyRowsAfter;
                }
            }

            // Step 2: Calculate scores based on column properties and add to existing scores
            int[][] cleanColsInWindowPrefixSum = new int[rows][cols];
            for (int i = 0; i <= rows - k; i++) {
                for (int j = 0; j < cols; j++) {
                    if (isColCleanInWindow(j, i, colPrefixSums)) {
                        cleanColsInWindowPrefixSum[i][j] = 1;
                    }
                    if (j > 0) {
                        cleanColsInWindowPrefixSum[i][j] += cleanColsInWindowPrefixSum[i][j - 1];
                    }
                }

                for (int j = 0; j <= cols - k; j++) {
                    int cleanColsInWindow = cleanColsInWindowPrefixSum[i][j + k - 1] - (j > 0 ? cleanColsInWindowPrefixSum[i][j - 1] : 0);
                    int emptyColsBefore = (j > 0) ? emptyColCumulativeCounts[j - 1] : 0;
                    int emptyColsAfter = emptyColCumulativeCounts[cols - 1] - emptyColCumulativeCounts[j + k - 1];

                    ans[i][j] += (cleanColsInWindow + emptyColsBefore + emptyColsAfter);
                }
            }

            return findMax(ans);
        }

        private boolean isRowCleanInWindow(int row, int colStart, int[][] rowPrefixSums) {
            int colEnd = colStart + k - 1;
            int blackCellsInsideWindow = rowPrefixSums[row][colEnd] - (colStart > 0 ? rowPrefixSums[row][colStart - 1] : 0);
            int totalBlackCellsInRow = rowPrefixSums[row][cols - 1];
            return blackCellsInsideWindow == totalBlackCellsInRow;
        }

        private boolean isColCleanInWindow(int col, int rowStart, int[][] colPrefixSums) {
            int rowEnd = rowStart + k - 1;
            int blackCellsInsideWindow = colPrefixSums[rowEnd][col] - (rowStart > 0 ? colPrefixSums[rowStart - 1][col] : 0);
            int totalBlackCellsInCol = colPrefixSums[rows - 1][col];
            return blackCellsInsideWindow == totalBlackCellsInCol;
        }

        private int[][] computeRowPrefixSums() {
            int[][] rowPrefixSums = new int[rows][cols];
            for (int i = 0; i < rows; i++) {
                int sum = 0;
                for (int j = 0; j < cols; j++) {
                    sum += grid[i][j];
                    rowPrefixSums[i][j] = sum;
                }
            }
            return rowPrefixSums;
        }

        private int[][] computeColPrefixSums() {
            int[][] colPrefixSums = new int[rows][cols];
            for (int j = 0; j < cols; j++) {
                int sum = 0;
                for (int i = 0; i < rows; i++) {
                    sum += grid[i][j];
                    colPrefixSums[i][j] = sum;
                }
            }
            return colPrefixSums;
        }

        private int[] computeEmptyRowCounts(int[][] rowPrefixSums) {
            int[] counts = new int[rows];
            int cumulative = 0;
            for (int i = 0; i < rows; i++) {
                if (rowPrefixSums[i][cols - 1] == 0) {
                    cumulative++;
                }
                counts[i] = cumulative;
            }
            return counts;
        }

        private int[] computeEmptyColCounts(int[][] colPrefixSums) {
            int[] counts = new int[cols];
            int cumulative = 0;
            for (int j = 0; j < cols; j++) {
                if (colPrefixSums[rows - 1][j] == 0) {
                    cumulative++;
                }
                counts[j] = cumulative;
            }
            return counts;
        }

        private int findMax(int[][] matrix) {
            int max = 0;
            for (int[] row : matrix) {
                for (int val : row) {
                    max = Math.max(max, val);
                }
            }
            return max;
        }
    }

    /**
     * Fast I/O helper class.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * GridPatternAnalyzer identifies specific patterns of 'B' characters in an N x N grid.
 * It calculates the number of rows and columns that are either empty or contain 
 * all their 'B' characters within a specific k x k window.
 */
public class GridPatternAnalyzer {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            int n = reader.nextInt();
            int k = reader.nextInt();

            GridAnalyzer analyzer = new GridAnalyzer(n, k);
            analyzer.readGrid(reader);
            long result = analyzer.solve();

            writer.println(result);
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    /**
     * Handles the core logic of the grid analysis.
     */
    private static class GridAnalyzer {
        private final int n;
        private final int k;
        private final long[][] prefixSumGrid;
        private final long[][] rowMatchPrefixSum;
        private final long[][] colMatchPrefixSum;

        public GridAnalyzer(int n, int k) {
            this.n = n;
            this.k = k;
            this.prefixSumGrid = new long[n + 1][n + 1];
            this.rowMatchPrefixSum = new long[n + 1][n + 1];
            this.colMatchPrefixSum = new long[n + 1][n + 1];
        }

        /**
         * Reads the grid and computes the 2D prefix sum of 'B' characters.
         */
        public void readGrid(FastReader reader) {
            for (int i = 1; i <= n; i++) {
                String line = reader.next();
                char[] rowChars = line.toCharArray();
                for (int j = 1; j <= n; j++) {
                    int isB = (rowChars[j - 1] == 'B') ? 1 : 0;
                    prefixSumGrid[i][j] = isB 
                                        + prefixSumGrid[i - 1][j] 
                                        + prefixSumGrid[i][j - 1] 
                                        - prefixSumGrid[i - 1][j - 1];
                }
            }
        }

        /**
         * Executes the pattern analysis.
         * @return The total count of empty rows/cols plus the maximum windowed matches.
         */
        public long solve() {
            long baseCount = countEmptyRowsAndColumns();
            calculateMatchPrefixSums();
            long maxWindowMatches = findMaxWindowedMatches();

            return baseCount + maxWindowMatches;
        }

        private long countEmptyRowsAndColumns() {
            long count = 0;
            for (int i = 1; i <= n; i++) {
                // Check if row i is empty of 'B'
                if (getRectSum(i, 1, i, n) == 0) count++;
                // Check if column i is empty of 'B'
                if (getRectSum(1, i, n, i) == 0) count++;
            }
            return count;
        }

        private void calculateMatchPrefixSums() {
            // Identify rows where all 'B's are contained within a segment of length k
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    int segmentEnd = Math.min(n, j + k - 1);
                    long rowTotalBs = getRectSum(i, 1, i, n);

                    if (rowTotalBs > 0 && getRectSum(i, j, i, segmentEnd) == rowTotalBs) {
                        rowMatchPrefixSum[i][j] = 1;
                    }
                }
            }

            // Identify columns where all 'B's are contained within a segment of length k
            for (int j = 1; j <= n; j++) {
                for (int i = 1; i <= n; i++) {
                    int segmentEnd = Math.min(n, i + k - 1);
                    long colTotalBs = getRectSum(1, j, n, j);

                    if (colTotalBs > 0 && getRectSum(i, j, segmentEnd, j) == colTotalBs) {
                        colMatchPrefixSum[i][j] = 1;
                    }
                }
            }

            // Create vertical prefix sums for row matches (for efficient range querying in columns)
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    rowMatchPrefixSum[i][j] += rowMatchPrefixSum[i - 1][j];
                }
            }

            // Create horizontal prefix sums for column matches (for efficient range querying in rows)
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    colMatchPrefixSum[i][j] += colMatchPrefixSum[i][j - 1];
                }
            }
        }

        private long findMaxWindowedMatches() {
            long maxMatches = 0;
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    int rowEnd = Math.min(n, i + k - 1);
                    int colEnd = Math.min(n, j + k - 1);

                    // Calculate how many rows in this window satisfy the row match condition at col j
                    long currentRows = rowMatchPrefixSum[rowEnd][j] - rowMatchPrefixSum[i - 1][j];
                    // Calculate how many columns in this window satisfy the col match condition at row i
                    long currentColMatches = colMatchPrefixSum[i][colEnd] - colMatchPrefixSum[i][j - 1];

                    maxMatches = Math.max(maxMatches, currentRows + currentColMatches);
                }
            }
            return maxMatches;
        }

        /**
         * Returns the sum of values in the rectangle defined by (r1, c1) and (r2, c2).
         */
        private long getRectSum(int r1, int c1, int r2, int c2) {
            int endR = Math.min(r2, n);
            int endC = Math.min(c2, n);
            if (r1 > endR || c1 > endC) return 0;
            return prefixSumGrid[endR][endC] 
                 - prefixSumGrid[r1 - 1][endC] 
                 - prefixSumGrid[endR][c1 - 1] 
                 + prefixSumGrid[r1 - 1][c1 - 1];
        }
    }

    /**
     * Efficient reader for large input datasets.
     */
    private static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solution to find the maximum coverage in a grid based on segment constraints.
 * This implementation uses a 2D difference array (prefix sum technique) to 
 * efficiently calculate the overlap of valid row and column segments.
 */
public class Task1200D {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        // The current problem constraints assume a single test case.
        int testCases = 1;
        while (testCases-- > 0) {
            try {
                int gridSize = reader.nextInt();
                int maxSegmentLength = reader.nextInt();
                char[][] grid = new char[gridSize][gridSize];

                for (int i = 0; i < gridSize; i++) {
                    grid[i] = reader.next().toCharArray();
                }

                GridSegmentSolver solver = new GridSegmentSolver(gridSize, maxSegmentLength, grid);
                writer.println(solver.solve());
            } catch (NoSuchElementException e) {
                break;
            }
        }

        writer.flush();
        writer.close();
    }

    /**
     * Handles the algorithmic logic for solving the grid problem.
     */
    static class GridSegmentSolver {
        private final int gridSize;
        private final int maxSegmentLength;
        private final char[][] grid;
        private final int[][] differenceArray;

        public GridSegmentSolver(int gridSize, int maxSegmentLength, char[][] grid) {
            this.gridSize = gridSize;
            this.maxSegmentLength = maxSegmentLength;
            this.grid = grid;
            // The difference array is size (n+1)x(n+1) to accommodate boundary updates safely.
            this.differenceArray = new int[gridSize + 1][gridSize + 1];
        }

        /**
         * Executes the solver logic.
         * @return The maximum coverage value found.
         */
        public int solve() {
            processRowConstraints();
            processColumnConstraints();
            return computeMaxCoverageFromDifferenceArray();
        }

        private void processRowConstraints() {
            for (int i = 0; i < gridSize; i++) {
                int leftmost = 0;
                while (leftmost < gridSize && grid[i][leftmost] == 'W') {
                    leftmost++;
                }

                // If the entire row is water, it's treated as a trivial segment at the origin.
                if (leftmost == gridSize) {
                    updateDifferenceArray(0, 1, 0, 1);
                    continue;
                }

                int rightmost = gridSize - 1;
                while (rightmost >= 0 && grid[i][rightmost] == 'W') {
                    rightmost--;
                }

                int actualSegmentWidth = rightmost - leftmost + 1;
                if (actualSegmentWidth <= maxSegmentLength) {
                    // Calculate the range of cells that can "cover" this row segment
                    int rowStart = Math.max(i - maxSegmentLength + 1, 0);
                    int rowEnd = i + 1;
                    int colStart = Math.max(rightmost - maxSegmentLength + 1, 0);
                    int colEnd = leftmost + 1;
                    updateDifferenceArray(rowStart, rowEnd, colStart, colEnd);
                }
            }
        }

        private void processColumnConstraints() {
            for (int j = 0; j < gridSize; j++) {
                int topmost = 0;
                while (topmost < gridSize && grid[topmost][j] == 'W') {
                    topmost++;
                }

                if (topmost == gridSize) {
                    updateDifferenceArray(0, 1, 0, 1);
                    continue;
                }

                int bottommost = gridSize - 1;
                while (bottommost >= 0 && grid[bottommost][j] == 'W') {
                    bottommost--;
                }

                int actualSegmentHeight = bottommost - topmost + 1;
                if (actualSegmentHeight <= maxSegmentLength) {
                    // Calculate the range of cells that can "cover" this column segment
                    int colStart = Math.max(j - maxSegmentLength + 1, 0);
                    int colEnd = j + 1;
                    int rowStart = Math.max(bottommost - maxSegmentLength + 1, 0);
                    int rowEnd = topmost + 1;
                    updateDifferenceArray(rowStart, rowEnd, colStart, colEnd);
                }
            }
        }

        /**
         * Updates the 2D difference array for a given rectangular range.
         * Standard 2D difference array update:
         * [r1, r2-1] x [c1, c2-1]
         */
        private void updateDifferenceArray(int r1, int r2, int c1, int c2) {
            // Ensure indices are within the bounds [0, gridSize]
            int startR = Math.max(0, Math.min(gridSize, r1));
            int endR = Math.max(0, Math.min(gridSize, r2));
            int startC = Math.max(0, Math.min(gridSize, c1));
            int endC = Math.max(0, Math.min(gridSize, c2));

            if (startR < endR && startC < endC) {
                differenceArray[startR][startC]++;
                differenceArray[startR][endC]--;
                differenceArray[endR][startC]--;
                differenceArray[endR][endC]++;
            }
        }

        private int computeMaxCoverageFromDifferenceArray() {
            // Convert the difference array into a 2D prefix sum array

            // 1. Row-wise prefix sums
            for (int i = 0; i < gridSize; i++) {
                for (int j = 0; j < gridSize; j++) {
                    differenceArray[i][j + 1] += differenceArray[i][j];
                }
            }

            // 2. Column-wise prefix sums
            for (int j = 0; j < gridSize; j++) {
                for (int i = 0; i < gridSize; i++) {
                    differenceArray[i + 1][j] += differenceArray[i][j];
                }
            }

            // Find the maximum value in the resulting grid
            int maxVal = 0;
            for (int i = 0; i < gridSize; i++) {
                for (int j = 0; j < gridSize; j++) {
                    maxVal = Math.max(maxVal, differenceArray[i][j]);
                }
            }
            return maxVal;
        }
    }

    /**
     * High-performance input reader.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

