/**
 * A high-performance reader for fast I/O operations.
 */
class FastReader {
    private final InputStream in;
    private final byte[] buffer = new byte[8192];
    private int pointer = 0;
    private int bufferLength = 0;

    public FastReader(InputStream in) {
        this.in = in;
    }

    private int read() throws IOException {
        if (pointer >= bufferLength) {
            pointer = 0;
            bufferLength = in.read(buffer);
            if (bufferLength <= 0) return -1;
        }
        return buffer[pointer++];
    }

    public int nextInt() throws IOException {
        int c = read();
        while (c != -1 && c <= 32) c = read();
        if (c == -1) return 0;
        int neg = 1;
        if (c == '-') {
            neg = -1;
            c = read();
        }
        int res = 0;
        while (c >= '0' && c <= '9') {
            res = res * 10 + (c - '0');
            c = read();
        }
        return res * neg;
    }

    public char nextChar() throws IOException {
        int c = read();
        while (c != -1 && c <= 32) c = read();
        return (char) c;
    }
}

/**
 * A utility class for handling 2D prefix sum queries efficiently.
 */
class PrefixSum2D {
    private final int[][] table;
    private final int maxR, maxC;

    public PrefixSum2D(int maxR, int maxC) {
        this.maxR = maxR;
        this.maxC = maxC;
        this.table = new int[maxR + 1][maxC + 1];
    }

    public void set(int r, int c, int val) {
        if (r >= 0 && r <= maxR && c >= 0 && c <= maxC) {
            table[r][c] = val;
        }
    }

    public void build() {
        for (int i = 1; i <= maxR; i++) {
            for (int j = 1; j <= maxC; j++) {
                table[i][j] += table[i - 1][j] + table[i][j - 1] - table[i - 1][j - 1];
            }
        }
    }

    public int query(int r1, int c1, int r2, int c2) {
        int row1 = Math.max(1, r1);
        int col1 = Math.max(1, c1);
        int row2 = Math.min(maxR, r2);
        int col2 = Math.min(maxC, c2);

        if (row1 > row2 || col1 > col2) return 0;
        return table[row2][col2] - table[row1 - 1][col2] - table[row2][col1 - 1] + table[row1 - 1][col1 - 1];
    }
}

/**
 * Core logic for solving the "White Lines" problem.
 */
class WhiteLineSolver {

    public void solve() throws IOException {
        FastReader in = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = in.nextInt();
        int k = in.nextInt();

        if (n == 0) {
            out.println(0);
            out.close();
            return;
        }

        int[][] grid = new int[n + 1][n + 1];
        int[] rowAllWhiteCount = new int[n + 1];
        int[] colAllWhiteCount = new int[n + 1];
        int[] rowBlackCellCount = new int[n + 1];
        int[] colBlackCellCount = new int[n + 1];

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                grid[i][j] = (in.nextChar() == 'B' ? 1 : 0);
                if (grid[i][j] == 0) {
                    rowBlackCellCount[i]++;
                    colBlackCellCount[j]++;
                }
            }
        }

        // Determine which rows/columns are entirely white
        for (int i = 1; i <= n; i++) {
            rowAllWhiteCount[i] = (rowBlackCellCount[i] == 0) ? 1 : 0;
            colAllWhiteCount[i] = (colBlackCellCount[i] == 0) ? 1 : 0;
        }

        // Convert row/column indicators to 1D prefix sums
        for (int i = 1; i <= n; i++) {
            rowAllWhiteCount[i] += rowAllWhiteCount[i - 1];
            colAllWhiteCount[i] += colAllWhiteCount[i - 1];
        }

        // Build 2D prefix sum for the grid
        PrefixSum2D gridSum = new PrefixSum2D(n, n);
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                gridSum.set(i, j, grid[i][j]);
            }
        }
        gridSum.build();

        // Calculate vertical boundary prefix sums
        PrefixSum2D verticalBoundary = new PrefixSum2D(n + 1, n + 1);
        for (int i = 1; i <= n + 1; i++) {
            for (int j = 1; j <= n + 1; j++) {
                if (i - k - 1 >= 0) {
                    // Check if column j is all white in the segments above and below the k-length gap
                    boolean upperIsWhite = gridSum.query(1, j, i - k - 1, j) == 0;
                    boolean lowerIsWhite = gridSum.query(i + 1, j, n, j) == 0;
                    if (upperIsWhite && lowerIsWhite) {
                        verticalBoundary.set(i, j, 1);
                    }
                }
            }
        }
        verticalBoundary.build();

        // Calculate horizontal boundary prefix sums
        PrefixSum2D horizontalBoundary = new PrefixSum2D(n + 1, n + 1);
        for (int i = 1; i <= n + 1; i++) {
            for (int j = 1; j <= n + 1; j++) {
                if (j - k - 1 >= 0) {
                    // Check if row i is all white in the segments left and right of the k-length gap
                    boolean leftIsWhite = gridSum.query(i, 1, i, j - k - 1) == 0;
                    boolean rightIsWhite = gridSum.query(i, j + 1, i, n) == 0;
                    if (leftIsWhite && rightIsWhite) {
                        horizontalBoundary.set(i, j, 1);
                    }
                }
            }
        }
        horizontalBoundary.build();

        int maxScore = 0;
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                // Check if a k x k square can fit starting at (i, j)
                if (i + k - 1 <= n && j + k - 1 <= n) {
                    int currentScore = rowAllWhiteCount[n] + colAllWhiteCount[n];
                    // Subtract white lines that are contained within the k x k window
                    currentScore -= (rowAllWhiteCount[i + k - 1] - rowAllWhiteCount[i - 1]);
                    currentScore -= (colAllWhiteCount[j + k - 1] - colAllWhiteCount[j - 1]);
                    // Add white lines at the boundaries of the window
                    currentScore += verticalBoundary.query(i + k, j, i + k, j + k - 1);
                    currentScore += horizontalBoundary.query(i, j + k, i + k - 1, j + k);

                    maxScore = Math.max(maxScore, currentScore);
                }
            }
        }

        out.println(maxScore);
        out.close();
    }
}

import java.io.*;
import java.util.*;

/**
 * GridCoverageSolver finds a k x k square in an n x n grid that maximizes the sum 
 * of "covered" rows and "covered" columns. 
 * A row/column is considered "covered" if all 'B' characters in that row/column 
 * fall within the span of the window.
 */
public class GridCoverageSolver {

    /**
     * Fast I/O utility class to handle large datasets efficiently.
     */
    private static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }

    public static void main(String[] args) {
        FastReader sc = new FastReader();
        PrintWriter out = new PrintWriter(System.out);

        String nStr = sc.next();
        if (nStr == null) return;

        int n = Integer.parseInt(nStr);
        int k = sc.nextInt();
        sc.nextLine(); // Consume trailing newline

        char[][] grid = new char[n][n];
        for (int i = 0; i < n; i++) {
            String line = sc.nextLine();
            grid[i] = line.toCharArray();
        }

        // Calculate coverage for rows (horizontal windows) and columns (vertical windows)
        int[][] rowCoverage = calculateCoverage(grid, n, k);
        char[][] transposedGrid = transpose(grid, n);
        int[][] colCoverage = calculateCoverage(transposedGrid, n, k);

        // Find the maximum sum of covered rows and covered columns for any k x k square
        int maxCovered = 0;
        for (int i = 0; i <= n - k; i++) {
            for (int j = 0; j <= n - k; j++) {
                // rowCoverage[i][j] is number of rows in vertical span [i, i+k-1] 
                // covered by a horizontal window starting at j.
                // colCoverage[j][i] is number of columns in horizontal span [j, j+k-1] 
                // covered by a vertical window starting at i.
                maxCovered = Math.max(maxCovered, rowCoverage[i][j] + colCoverage[j][i]);
            }
        }

        // Add the constant count of rows and columns that contain no 'B's
        int emptyCount = countEmptyRowsAndCols(grid, n);
        out.println(maxCovered + emptyCount);

        out.flush();
        out.close();
    }

    /**
     * Transposes an n x n character grid.
     */
    private static char[][] transpose(char[][] grid, int n) {
        char[][] transposed = new char[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                transposed[j][i] = grid[i][j];
            }
        }
        return transposed;
    }

    /**
     * Calculates how many rows (or columns) in a sliding window of size k are "covered".
     * A row is covered if all its 'B' characters are within the window's span.
     * 
     * @return A 2D array where res[start_idx][other_idx] is the count of covered 
     *         elements in a window starting at start_idx.
     */
    private static int[][] calculateCoverage(char[][] grid, int n, int k) {
        // isCovered[i][j] is true if row i is fully covered by a window starting at column j
        boolean[][] isCovered = new boolean[n][n];

        for (int i = 0; i < n; i++) {
            int firstB = -1;
            int lastB = -1;
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 'B') {
                    if (firstB == -1) firstB = j;
                    lastB = j;
                }
            }

            // If row contains 'B's, find the range of window-start-positions that cover them
            if (firstB != -1) {
                // Window [j, j + k - 1] covers all 'B's if j <= firstB and j + k - 1 >= lastB
                int startWindowPos = Math.max(0, lastB - k + 1);
                int endWindowPos = Math.min(n - k, firstB);
                for (int j = startWindowPos; j <= endWindowPos; j++) {
                    isCovered[i][j] = true;
                }
            }
        }

        // res[start_idx][other_idx] stores the sliding window sum
        int[][] res = new int[n][n];
        for (int otherIdx = 0; otherIdx < n; otherIdx++) {
            int currentWindowSum = 0;

            // Initialize first window sum for the given column/row
            for (int r = 0; r < k; r++) {
                if (isCovered[r][otherIdx]) {
                    currentWindowSum++;
                }
            }
            res[0][otherIdx] = currentWindowSum;

            // Slide the window across the indices
            for (int startIdx = 1; startIdx <= n - k; startIdx++) {
                if (isCovered[startIdx - 1][otherIdx]) {
                    currentWindowSum--;
                }
                if (isCovered[startIdx + k - 1][otherIdx]) {
                    currentWindowSum++;
                }
                res[startIdx][otherIdx] = currentWindowSum;
            }
        }
        return res;
    }

    /**
     * Counts rows and columns that do not contain any 'B' characters.
     */
    private static int countEmptyRowsAndCols(char[][] grid, int n) {
        int emptyCount = 0;
        for (int i = 0; i < n; i++) {
            boolean rowHasB = false;
            boolean colHasB = false;
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 'B') rowHasB = true;
                if (grid[j][i] == 'B') colHasB = true;
            }
            if (!rowHasB) emptyCount++;
            if (!colHasB) emptyCount++;
        }
        return emptyCount;
    }
}

import java.util.*;
import java.io.*;

/**
 * A solution to find the maximum number of rows and columns that can be made "white"
 * (containing no black cells 'B') by choosing a K x K subgrid and clearing it.
 */
public class GridProblemSolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        Integer nVal = reader.nextInt();
        Integer kVal = reader.nextInt();

        if (nVal == null || kVal == null) {
            return;
        }

        int n = nVal;
        int k = kVal;

        char[][] grid = new char[n][n];
        for (int i = 0; i < n; i++) {
            String line = reader.next();
            if (line != null) {
                grid[i] = line.toCharArray();
            }
        }

        // Step 1: Calculate how many black cells are in each row and each column.
        int[] rowBlackCounts = new int[n];
        int[] colBlackCounts = new int[n];

        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 'B') {
                    rowBlackCounts[r]++;
                    colBlackCounts[c]++;
                }
            }
        }

        // Step 2: Count rows and columns that are already white (zero black cells).
        int alreadyWhiteCount = 0;
        for (int i = 0; i < n; i++) {
            if (rowBlackCounts[i] == 0) alreadyWhiteCount++;
            if (colBlackCounts[i] == 0) alreadyWhiteCount++;
        }

        // Step 3: Create prefix sums for rows and columns to allow O(1) range queries.
        int[][] rowPrefixSums = new int[n][n];
        int[][] colPrefixSums = new int[n][n];

        for (int r = 0; r < n; r++) {
            int runningSum = 0;
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 'B') runningSum++;
                rowPrefixSums[r][c] = runningSum;
            }
        }

        for (int c = 0; c < n; c++) {
            int runningSum = 0;
            for (int r = 0; r < n; r++) {
                if (grid[r][c] == 'B') runningSum++;
                colPrefixSums[r][c] = runningSum;
            }
        }

        // Step 4: Use a score grid to track how many additional lines are covered by a KxK window.
        // scoreGrid[r][c] will store the number of rows/cols that become white if 
        // the KxK window starts at (r, c).
        int[][] scoreGrid = new int[n][n];

        // Sub-problem A: For every possible row-window [rStart, rStart + K - 1],
        // find which columns become white within a sliding column-window.
        for (int rStart = 0; rStart <= n - k; rStart++) {
            int rEnd = rStart + k - 1;
            int currentCoveredColsInWindow = 0;

            // Initial column window [0, k-1]
            for (int c = 0; c < k; c++) {
                if (colBlackCounts[c] > 0 && isColumnCovered(c, rStart, rEnd, colPrefixSums, colBlackCounts)) {
                    currentCoveredColsInWindow++;
                }
            }
            scoreGrid[rStart][0] += currentCoveredColsInWindow;

            // Slide the column window across the row-window
            for (int cStart = 1; cStart <= n - k; cStart++) {
                // Remove the column that is sliding out
                if (colBlackCounts[cStart - 1] > 0 && isColumnCovered(cStart - 1, rStart, rEnd, colPrefixSums, colBlackCounts)) {
                    currentCoveredColsInWindow--;
                }
                // Add the column that is sliding in
                int newC = cStart + k - 1;
                if (colBlackCounts[newC] > 0 && isColumnCovered(newC, rStart, rEnd, colPrefixSums, colBlackCounts)) {
                    currentCoveredColsInWindow++;
                }
                scoreGrid[rStart][cStart] += currentCoveredColsInWindow;
            }
        }

        // Sub-problem B: For every possible column-window [cStart, cStart + K - 1],
        // find which rows become white within a sliding row-window.
        for (int cStart = 0; cStart <= n - k; cStart++) {
            int cEnd = cStart + k - 1;
            int currentCoveredRowsInWindow = 0;

            // Initial row window [0, k-1]
            for (int r = 0; r < k; r++) {
                if (rowBlackCounts[r] > 0 && isRowCovered(r, cStart, cEnd, rowPrefixSums, rowBlackCounts)) {
                    currentCoveredRowsInWindow++;
                }
            }
            scoreGrid[0][cStart] += currentCoveredRowsInWindow;

            // Slide the row window across the column-window
            for (int rStart = 1; rStart <= n - k; rStart++) {
                // Remove the row that is sliding out
                if (rowBlackCounts[rStart - 1] > 0 && isRowCovered(rStart - 1, cStart, cEnd, rowPrefixSums, rowBlackCounts)) {
                    currentCoveredRowsInWindow--;
                }
                // Add the row that is sliding in
                int newR = rStart + k - 1;
                if (rowBlackCounts[newR] > 0 && isRowCovered(newR, cStart, cEnd, rowPrefixSums, rowBlackCounts)) {
                    currentCoveredRowsInWindow++;
                }
                scoreGrid[rStart][cStart] += currentCoveredRowsInWindow;
            }
        }

        // Step 5: Find the maximum value in the scoreGrid and add the already white lines.
        int maxAdditionalWhite = 0;
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (scoreGrid[r][c] > maxAdditionalWhite) {
                    maxAdditionalWhite = scoreGrid[r][c];
                }
            }
        }

        System.out.println(maxAdditionalWhite + alreadyWhiteCount);
    }

    /**
     * Checks if all black cells in a specific column fall within the given row range.
     */
    private static boolean isColumnCovered(int col, int rStart, int rEnd, int[][] colPrefixSums, int[] colBlackCounts) {
        int countInWindow = colPrefixSums[rEnd][col] - (rStart > 0 ? colPrefixSums[rStart - 1][col] : 0);
        return countInWindow == colBlackCounts[col];
    }

    /**
     * Checks if all black cells in a specific row fall within the given column range.
     */
    private static boolean isRowCovered(int row, int cStart, int cEnd, int[][] rowPrefixSums, int[] rowBlackCounts) {
        int countInWindow = rowPrefixSums[row][cEnd] - (cStart > 0 ? rowPrefixSums[row][cStart - 1] : 0);
        return countInWindow == rowBlackCounts[row];
    }

    /**
     * Helper class for efficient input reading.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public Integer nextInt() {
            String s = next();
            return s == null ? null : Integer.parseInt(s);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * GridSolver calculates the maximum number of white rows and columns 
 * possible after applying a k x k square of white cells to an n x n grid.
 */
public class Main {
    public static void main(String[] args) {
        new GridSolver().run();
    }
}

class GridSolver {
    private static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }

    public void run() {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        String nStr = reader.next();
        if (nStr == null) {
            out.close();
            return;
        }

        int n = Integer.parseInt(nStr);
        int k = reader.nextInt();
        char[][] grid = new char[n][n];

        for (int i = 0; i < n; i++) {
            grid[i] = reader.next().toCharArray();
        }

        solve(n, k, grid, out);
        out.close();
    }

    private void solve(int n, int k, char[][] grid, PrintWriter out) {
        int initialWhiteCount = 0;

        // Tracks if row i can be made entirely white if a k-length segment 
        // starts at column j.
        boolean[][] rowCanBeCleared = new boolean[n][n];
        for (int i = 0; i < n; i++) {
            int firstBlack = -1;
            int lastBlack = -1;
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 'B') {
                    if (firstBlack == -1) firstBlack = j;
                    lastBlack = j;
                }
            }

            if (firstBlack == -1) {
                initialWhiteCount++; // Row is already all white
            } else {
                // A segment [j, j+k-1] clears the row if it covers [firstBlack, lastBlack]
                int rangeStart = Math.max(0, lastBlack - k + 1);
                int rangeEnd = firstBlack;
                for (int j = rangeStart; j <= rangeEnd; j++) {
                    rowCanBeCleared[i][j] = true;
                }
            }
        }

        // Tracks if column i can be made entirely white if a k-length segment 
        // starts at row j.
        boolean[][] colCanBeCleared = new boolean[n][n];
        for (int j = 0; j < n; j++) {
            int firstBlack = -1;
            int lastBlack = -1;
            for (int i = 0; i < n; i++) {
                if (grid[i][j] == 'B') {
                    if (firstBlack == -1) firstBlack = i;
                    lastBlack = i;
                }
            }

            if (firstBlack == -1) {
                initialWhiteCount++; // Column is already all white
            } else {
                int rangeStart = Math.max(0, lastBlack - k + 1);
                int rangeEnd = firstBlack;
                for (int i = rangeStart; i <= rangeEnd; i++) {
                    colCanBeCleared[i][j] = true;
                }
            }
        }

        // rowWindowSum[i][j] = count of rows in [i, i+k-1] that become white 
        // if a k-length horizontal segment is placed at (row, j).
        int[][] rowWindowSum = computeWindowSums(rowCanBeCleared, n, k, true);

        // colWindowSum[i][j] = count of columns in [j, j+k-1] that become white 
        // if a k-length vertical segment is placed at (i, col).
        int[][] colWindowSum = computeWindowSums(colCanBeCleared, n, k, false);

        int maxWhiteCount = initialWhiteCount;
        for (int i = 0; i <= n - k; i++) {
            for (int j = 0; j <= n - k; j++) {
                int currentTotal = initialWhiteCount + rowWindowSum[i][j] + colWindowSum[i][j];
                maxWhiteCount = Math.max(maxWhiteCount, currentTotal);
            }
        }

        out.println(maxWhiteCount);
    }

    /**
     * Computes sliding window sums over the boolean coverage maps.
     * 
     * @param coverage The boolean coverage map.
     * @param n Dimension of the grid.
     * @param k The size of the segment.
     * @param isRowMode If true, slides window over rows; if false, slides over columns.
     * @return A 2D array of window sums.
     */
    private int[][] computeWindowSums(boolean[][] coverage, int n, int k, boolean isRowMode) {
        int[][] windowSums = new int[n - k + 1][n - k + 1];

        if (isRowMode) {
            // Sliding window over rows (dim 0), fixed column (dim 1)
            for (int j = 0; j <= n - k; j++) {
                int currentSum = 0;
                for (int i = 0; i < k; i++) {
                    if (coverage[i][j]) currentSum++;
                }
                windowSums[0][j] = currentSum;
                for (int i = 1; i <= n - k; i++) {
                    if (coverage[i - 1][j]) currentSum--;
                    if (coverage[i + k - 1][j]) currentSum++;
                    windowSums[i][j] = currentSum;
                }
            }
        } else {
            // Sliding window over columns (dim 1), fixed row (dim 0)
            for (int i = 0; i <= n - k; i++) {
                int currentSum = 0;
                for (int j = 0; j < k; j++) {
                    if (coverage[i][j]) currentSum++;
                }
                windowSums[i][0] = currentSum;
                for (int j = 1; j <= n - k; j++) {
                    if (coverage[i][j - 1]) currentSum--;
                    if (coverage[i][j + k - 1]) currentSum++;
                    windowSums[i][j] = currentSum;
                }
            }
        }
        return windowSums;
    }
}

import java.io.*;
import java.util.*;

/**
 * Problem Solver for finding the maximum number of clear rows and columns 
 * achievable by selecting a k x k subgrid.
 */
public class P1200D_Refactored {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        try {
            int n = reader.nextInt();
            int k = reader.nextInt();
            char[][] grid = new char[n][n];
            for (int i = 0; i < n; i++) {
                grid[i] = reader.next().toCharArray();
            }

            GridSolver solver = new GridSolver(n, k, grid);
            System.out.println(solver.solve());
        } catch (NoSuchElementException e) {
            // Handle empty input gracefully
        }
    }

    /**
     * Contains the business logic for calculating the grid clearance.
     */
    static class GridSolver {
        private final int n;
        private final int k;
        private final char[][] grid;

        // Boundary arrays to track the range of 'B' cells in each row and column
        private final int[] minRowPerCol;
        private final int[] maxRowPerCol;
        private final int[] minColPerRow;
        private final int[] maxColPerRow;

        public GridSolver(int n, int k, char[][] grid) {
            this.n = n;
            this.k = k;
            this.grid = grid;
            this.minRowPerCol = new int[n];
            this.maxRowPerCol = new int[n];
            this.minColPerRow = new int[n];
            this.maxColPerRow = new int[n];

            Arrays.fill(minRowPerCol, n);
            Arrays.fill(maxRowPerCol, -1);
            Arrays.fill(minColPerRow, n);
            Arrays.fill(maxColPerRow, -1);

            computeBoundaries();
        }

        private void computeBoundaries() {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (grid[i][j] == 'B') {
                        minRowPerCol[j] = Math.min(minRowPerCol[j], i);
                        maxRowPerCol[j] = Math.max(maxRowPerCol[j], i);
                        minColPerRow[i] = Math.min(minColPerRow[i], j);
                        maxColPerRow[i] = Math.max(maxColPerRow[i], j);
                    }
                }
            }
        }

        public int solve() {
            int initialClearLines = countInitialClearLines();

            // benefitsCol[r][c] = number of columns in window [c, c+k-1] 
            // that are fully contained within row range [r, r+k-1]
            int[][] benefitsCol = computeColumnBenefits();

            // benefitsRow[r][c] = number of rows in window [r, r+k-1] 
            // that are fully contained within column range [c, c+k-1]
            int[][] benefitsRow = computeRowBenefits();

            int maxAddedBenefit = 0;
            for (int r = 0; r <= n - k; r++) {
                for (int c = 0; c <= n - k; c++) {
                    maxAddedBenefit = Math.max(maxAddedBenefit, benefitsCol[r][c] + benefitsRow[r][c]);
                }
            }

            return initialClearLines + maxAddedBenefit;
        }

        private int countInitialClearLines() {
            int clearRows = 0;
            for (int i = 0; i < n; i++) {
                if (maxColPerRow[i] < minColPerRow[i]) clearRows++;
            }

            int clearCols = 0;
            for (int j = 0; j < n; j++) {
                if (maxRowPerCol[j] < minRowPerCol[j]) clearCols++;
            }
            return clearRows + clearCols;
        }

        /**
         * Calculates how many columns in a k-width window are "contained" 
         * within a specific row-range.
         */
        private int[][] computeColumnBenefits() {
            int[][] benefits = new int[n - k + 1][n - k + 1];
            for (int r = 0; r <= n - k; r++) {
                int rowStart = r;
                int rowEnd = r + k - 1;
                int currentWindowCount = 0;

                // Initial window for columns [0, k-1]
                for (int c = 0; c < k; c++) {
                    if (isColumnContained(c, rowStart, rowEnd)) {
                        currentWindowCount++;
                    }
                }
                benefits[r][0] = currentWindowCount;

                // Sliding window for columns [c, c+k-1]
                for (int c = 1; c <= n - k; c++) {
                    if (isColumnContained(c - 1, rowStart, rowEnd)) {
                        currentWindowCount--;
                    }
                    if (isColumnContained(c + k - 1, rowStart, rowEnd)) {
                        currentWindowCount++;
                    }
                    benefits[r][c] = currentWindowCount;
                }
            }
            return benefits;
        }

        private boolean isColumnContained(int col, int rStart, int rEnd) {
            return minRowPerCol[col] <= maxRowPerCol[col] && 
                   minRowPerCol[col] >= rStart && 
                   maxRowPerCol[col] <= rEnd;
        }

        /**
         * Calculates how many rows in a k-height window are "contained" 
         * within a specific column-range.
         */
        private int[][] computeRowBenefits() {
            int[][] benefits = new int[n - k + 1][n - k + 1];
            for (int c = 0; c <= n - k; c++) {
                int colStart = c;
                int colEnd = c + k - 1;
                int currentWindowCount = 0;

                // Initial window for rows [0, k-1]
                for (int r = 0; r < k; r++) {
                    if (isRowContained(r, colStart, colEnd)) {
                        currentWindowCount++;
                    }
                }
                benefits[0][c] = currentWindowCount;

                // Sliding window for rows [r, r+k-1]
                for (int r = 1; r <= n - k; r++) {
                    if (isRowContained(r - 1, colStart, colEnd)) {
                        currentWindowCount--;
                    }
                    if (isRowContained(r + k - 1, colStart, colEnd)) {
                        currentWindowCount++;
                    }
                    benefits[r][c] = currentWindowCount;
                }
            }
            return benefits;
        }

        private boolean isRowContained(int row, int cStart, int cEnd) {
            return minColPerRow[row] <= maxColPerRow[row] && 
                   minColPerRow[row] >= cStart && 
                   maxColPerRow[row] <= cEnd;
        }
    }

    /**
     * Optimized reader for large inputs.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solution to find a k x k window in an n x n grid that maximizes the number 
 * of "satisfied" rows and columns, plus the total number of empty rows and columns.
 * A row/column is satisfied if all its 'B' characters are contained within the window.
 */
public class Solution {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        String nStr = reader.next();
        if (nStr == null) return;
        int n = Integer.parseInt(nStr);
        int k = reader.nextInt();

        char[][] grid = new char[n + 1][n + 1];
        for (int i = 1; i <= n; i++) {
            String line = reader.next();
            for (int j = 1; j <= n; j++) {
                grid[i][j] = line.charAt(j - 1);
            }
        }

        GridSolver solver = new GridSolver(n, k, grid);
        System.out.println(solver.solve());
    }

    /**
     * Fast I/O reader using BufferedReader and StringTokenizer.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /**
     * Logic engine for analyzing the grid.
     */
    static class GridSolver {
        private final int gridSize;
        private final int windowSize;
        private final char[][] grid;

        private final int[] rowBCount;
        private final int[] colBCount;
        private final int emptyRowsAndCols;

        public GridSolver(int n, int k, char[][] grid) {
            this.gridSize = n;
            this.windowSize = k;
            this.grid = grid;
            this.rowBCount = new int[n + 1];
            this.colBCount = new int[n + 1];

            int emptyRows = 0;
            for (int i = 1; i <= n; i++) {
                int count = 0;
                for (int j = 1; j <= n; j++) {
                    if (grid[i][j] == 'B') count++;
                }
                rowBCount[i] = count;
                if (count == 0) emptyRows++;
            }

            int emptyCols = 0;
            for (int j = 1; j <= n; j++) {
                int count = 0;
                for (int i = 1; i <= n; i++) {
                    if (grid[i][j] == 'B') count++;
                }
                colBCount[j] = count;
                if (count == 0) emptyCols++;
            }

            this.emptyRowsAndCols = emptyRows + emptyCols;
        }

        /**
         * Orchestrates the calculation of satisfied segments and finds the maximum score.
         */
        public int solve() {
            if (windowSize > gridSize) {
                return emptyRowsAndCols;
            }

            // rowSatisfiedPrefixSum[i][j] counts how many non-empty rows in 1..i 
            // are satisfied by a horizontal window of size k starting at column j.
            int[][] rowSatisfiedPrefixSum = calculateRowPrefixSums();

            // colSatisfiedPrefixSum[i][j] counts how many non-empty columns in 1..j 
            // are satisfied by a vertical window of size k starting at row i.
            int[][] colSatisfiedPrefixSum = calculateColPrefixSums();

            int maxScore = emptyRowsAndCols;

            // Iterate through every possible top-left corner (i, j) of a k x k window.
            for (int i = 1; i <= gridSize - windowSize + 1; i++) {
                for (int j = 1; j <= gridSize - windowSize + 1; j++) {
                    // Rows in window [i, i+k-1] satisfied by column range [j, j+k-1]
                    int satisfiedRows = rowSatisfiedPrefixSum[i + windowSize - 1][j] 
                                      - rowSatisfiedPrefixSum[i - 1][j];

                    // Columns in window [j, j+k-1] satisfied by row range [i, i+k-1]
                    int satisfiedCols = colSatisfiedPrefixSum[i][j + windowSize - 1] 
                                      - colSatisfiedPrefixSum[i][j - 1];

                    maxScore = Math.max(maxScore, satisfiedRows + satisfiedCols + emptyRowsAndCols);
                }
            }

            return maxScore;
        }

        private int[][] calculateRowPrefixSums() {
            int[][] prefixSum = new int[gridSize + 1][gridSize + 1];
            for (int i = 1; i <= gridSize; i++) {
                if (rowBCount[i] == 0) {
                    // If row is empty, it is handled by emptyRowsAndCols constant.
                    // We just carry over the prefix sum for consistency.
                    for (int j = 1; j <= gridSize; j++) {
                        prefixSum[i][j] = prefixSum[i - 1][j];
                    }
                    continue;
                }

                int currentBInWindow = 0;
                for (int j = 1; j <= windowSize; j++) {
                    if (grid[i][j] == 'B') currentBInWindow++;
                }

                for (int j = 1; j <= gridSize - windowSize + 1; j++) {
                    boolean isSatisfied = (currentBInWindow == rowBCount[i]);
                    prefixSum[i][j] = prefixSum[i - 1][j] + (isSatisfied ? 1 : 0);

                    // Slide the window to the right
                    if (j <= gridSize - windowSize) {
                        if (grid[i][j] == 'B') currentBInWindow--;
                        if (grid[i][j + windowSize] == 'B') currentBInWindow++;
                    }
                }
            }
            return prefixSum;
        }

        private int[][] calculateColPrefixSums() {
            int[][] prefixSum = new int[gridSize + 1][gridSize + 1];
            for (int j = 1; j <= gridSize; j++) {
                if (colBCount[j] == 0) {
                    for (int i = 1; i <= gridSize; i++) {
                        prefixSum[i][j] = prefixSum[i][j - 1];
                    }
                    continue;
                }

                int currentBInWindow = 0;
                for (int i = 1; i <= windowSize; i++) {
                    if (grid[i][j] == 'B') currentBInWindow++;
                }

                for (int i = 1; i <= gridSize - windowSize + 1; i++) {
                    boolean isSatisfied = (currentBInWindow == colBCount[j]);
                    prefixSum[i][j] = prefixSum[i][j - 1] + (isSatisfied ? 1 : 0);

                    // Slide the window down
                    if (i <= gridSize - windowSize) {
                        if (grid[i][j] == 'B') currentBInWindow--;
                        if (grid[i + windowSize][j] == 'B') currentBInWindow++;
                    }
                }
            }
            return prefixSum;
        }
    }
}

import java.io.DataInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * The Garland class serves as the entry point for the application.
 * It handles input reading and orchestrates the solving process.
 */
public class Garland {

    public static void main(String[] args) {
        try {
            FastReader reader = new FastReader(System.in);
            int n = reader.nextInt();
            int[] sequence = new int[n];
            boolean allZeros = true;

            for (int i = 0; i < n; i++) {
                sequence[i] = reader.nextInt();
                if (sequence[i] != 0) {
                    allZeros = false;
                }
            }

            if (allZeros) {
                if (n == 1) {
                    System.out.println(0);
                } else {
                    System.out.println(1);
                }
                return;
            }

            GarlandSolver solver = new GarlandSolver(sequence);
            System.out.println(solver.solve());

        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * FastReader provides high-performance input reading.
     */
    static class FastReader {
        private final int BUFFER_SIZE = 1 << 16;
        private final DataInputStream din;
        private final byte[] buffer;
        private int bufferPointer, bytesRead;

        public FastReader(InputStream in) {
            din = new DataInputStream(in);
            buffer = new byte[BUFFER_SIZE];
            bufferPointer = bytesRead = 0;
        }

        public int nextInt() throws IOException {
            int ret = 0;
            byte c = read();
            while (c <= ' ') {
                c = read();
            }
            boolean neg = (c == '-');
            if (neg) {
                c = read();
            }
            do {
                ret = ret * 10 + c - '0';
            } while ((c = read()) >= '0' && c <= '9');

            return neg ? -ret : ret;
        }

        private void fillBuffer() throws IOException {
            bytesRead = din.read(buffer, bufferPointer = 0, BUFFER_SIZE);
            if (bytesRead == -1) {
                buffer[0] = -1;
            }
        }

        private byte read() throws IOException {
            if (bufferPointer == bytesRead) {
                fillBuffer();
            }
            return buffer[bufferPointer++];
        }
    }

    /**
     * GarlandSolver encapsulates the core business logic for calculating
     * the garland's configuration.
     */
    static class GarlandSolver {
        private final int[] sequence;
        private final int length;
        private int availableEven;
        private int availableOdd;
        private int zeroSegmentCount = 0;
        private int parityChangeCount = 0;

        private final List<Integer> gapSizesRequiringOdd = new ArrayList<>();
        private final List<Integer> gapSizesRequiringEven = new ArrayList<>();

        public GarlandSolver(int[] sequence) {
            this.sequence = sequence;
            this.length = sequence.length;
            calculateMissingParityCounts();
        }

        private void calculateMissingParityCounts() {
            boolean[] isNumberPresent = new boolean[length + 1];
            for (int val : sequence) {
                if (val != 0) {
                    isNumberPresent[val] = true;
                }
            }

            for (int i = 1; i <= length; i++) {
                if (!isNumberPresent[i]) {
                    if (i % 2 == 0) {
                        availableEven++;
                    } else {
                        availableOdd++;
                    }
                }
            }
        }

        public int solve() {
            processMiddleZeroGaps();
            processEdgeZeroGaps();
            calculateExistingParityChanges();

            // Calculate how many "needed" gaps were actually satisfied
            int usedOddGaps = 0;
            for (int i = 0; i < gapSizesRequiringOdd.size(); i++) {
                int size = gapSizesRequiringOdd.get(i);
                if (size != -1 && size <= availableOdd) {
                    availableOdd -= size;
                    zeroSegmentCount--;
                    gapSizesRequiringOdd.set(i, -1);
                    usedOddGaps++;
                }
            }

            int usedEvenGaps = 0;
            for (int i = 0; i < gapSizesRequiringEven.size(); i++) {
                int size = gapSizesRequiringEven.get(i);
                if (size != -1 && size <= availableEven) {
                    availableEven -= size;
                    zeroSegmentCount--;
                    gapSizesRequiringEven.set(i, -1);
                    usedEvenGaps++;
                }
            }

            // Count gaps that were not satisfied
            int unusedOddGaps = 0;
            for (int s : gapSizesRequiringOdd) {
                if (s != -1) unusedOddGaps++;
            }

            int unusedEvenGaps = 0;
            for (int s : gapSizesRequiringEven) {
                if (s != -1) unusedEvenGaps++;
            }

            // The logic follows the original formula for final segment/change calculation
            zeroSegmentCount -= unusedOddGaps;
            zeroSegmentCount -= unusedEvenGaps;

            return parityChangeCount + (unusedOddGaps + unusedEvenGaps) * 2 + zeroSegmentCount;
        }

        private void processMiddleZeroGaps() {
            for (int i = 0; i < length; i++) {
                if (sequence[i] == 0) {
                    zeroSegmentCount++;
                    int start = i;
                    while (i < length && sequence[i] == 0) {
                        i++;
                    }
                    int end = i; // This is the index of the next non-zero element

                    // We are at a gap of zeros from [start, end-1]
                    if (start > 0 && end < length) {
                        boolean prevIsOdd = (sequence[start - 1] % 2 != 0);
                        boolean nextIsOdd = (sequence[end] % 2 != 0);
                        int gapSize = end - start;

                        if (prevIsOdd && nextIsOdd) {
                            gapSizesRequiringOdd.add(gapSize);
                        } else if (!prevIsOdd && !nextIsOdd) {
                            gapSizesRequiringEven.add(gapSize);
                        }
                    }
                    i--; // Adjust for loop increment
                }
            }
        }

        private void processEdgeZeroGaps() {
            // Process Leading Zeros
            if (sequence[0] == 0) {
                int firstNonZeroIdx = 0;
                while (firstNonZeroIdx < length && sequence[firstNonZeroIdx] == 0) {
                    firstNonZeroIdx++;
                }
                zeroSegmentCount--;

                if (firstNonZeroIdx < length) {
                    int gapSize = firstNonZeroIdx;
                    if (sequence[firstNonZeroIdx] % 2 == 0) {
                        if (availableEven >= gapSize) {
                            availableEven -= gapSize;
                        } else {
                            availableOdd -= (gapSize - availableEven);
                            parityChangeCount++;
                        }
                    } else {
                        if (availableOdd >= gapSize) {
                            availableOdd -= gapSize;
                        } else {
                            availableEven -= (gapSize - availableOdd);
                            parityChangeCount++;
                        }
                    }
                }
            }

            // Process Trailing Zeros
            if (sequence[length - 1] == 0) {
                int lastNonZeroIdx = length - 1;
                while (lastNonZeroIdx >= 0 && sequence[lastNonZeroIdx] == 0) {
                    lastNonZeroIdx--;
                }
                zeroSegmentCount--;

                if (lastNonZeroIdx >= 0) {
                    int gapSize = (length - 1) - lastNonZeroIdx;
                    if (sequence[lastNonZeroIdx] % 2 == 0) {
                        if (availableEven >= gapSize) {
                            availableEven -= gapSize;
                        } else {
                            availableOdd -= (gapSize - availableEven);
                            parityChangeCount++;
                        }
                    } else {
                        if (availableOdd >= gapSize) {
                            availableOdd -= gapSize;
                        } else {
                            availableEven -= (gapSize - availableOdd);
                            parityChangeCount++;
                        }
                    }
                }
            }
        }

        private void calculateExistingParityChanges() {
            for (int i = 0; i < length - 1; i++) {
                if (sequence[i] != 0 && sequence[i + 1] != 0) {
                    if (sequence[i] % 2 != sequence[i + 1] % 2) {
                        parityChangeCount++;
                    }
                }
            }
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * Solves the garland coloring problem.
 * The goal is to assign colors (0 or 1) to a garland of length N such that:
 * 1. The total number of 'odd' colors (1) is (N+1)/2.
 * 2. The total number of 'even' colors (0) is N/2.
 * 3. The constraints provided in the input are respected.
 * 4. The number of transitions between different adjacent colors is minimized.
 */
public class GarlandColoringProblem {

    private static final int INF = 100_000_000;

    private final int n;
    private final int[] constraints;
    private final int targetOdds;
    private final int targetEvens;
    private final int[][][] memo;

    /**
     * @param n Total number of elements in the garland.
     * @param constraints Array where constraints[i] is 1 (must be odd), 0 (must be even), or -1 (any).
     */
    public GarlandColoringProblem(int n, int[] constraints) {
        this.n = n;
        this.constraints = constraints;
        this.targetOdds = (n + 1) / 2;
        this.targetEvens = n / 2;

        // DP state: memo[current_index][current_odd_count][previous_color]
        this.memo = new int[n + 1][targetOdds + 1][2];
        for (int[][] layer : memo) {
            for (int[] row : layer) {
                Arrays.fill(row, -1);
            }
        }
    }

    /**
     * Initiates the recursive solver.
     * @return The minimum number of color transitions.
     */
    public int solve() {
        if (n == 0) return 0;
        if (n == 1) return 0;

        int minTransitions = INF;

        // Try starting the garland with color 0 (Even)
        if (canUseColor(1, 0, 0, 0)) {
            minTransitions = Math.min(minTransitions, solveRecursive(2, 0, 0));
        }

        // Try starting the garland with color 1 (Odd)
        if (canUseColor(1, 1, 0, 0)) {
            minTransitions = Math.min(minTransitions, solveRecursive(2, 1, 1));
        }

        return minTransitions;
    }

    /**
     * Helper to check if a specific color can be assigned to the current index.
     */
    private boolean canUseColor(int idx, int color, int currentOdds, int currentEvens) {
        // Check if color matches the input constraint (-1 is a wildcard)
        if (constraints[idx] != -1 && constraints[idx] != color) {
            return false;
        }
        // Check if we would exceed the allowed total count for this color
        if (color == 1 && currentOdds + 1 > targetOdds) {
            return false;
        }
        if (color == 0 && currentEvens + 1 > targetEvens) {
            return false;
        }
        return true;
    }

    /**
     * Core recursive function with memoization.
     */
    private int solveRecursive(int idx, int currentOdds, int prevColor) {
        // Base case: All elements have been assigned colors
        if (idx > n) {
            return 0;
        }

        if (memo[idx][currentOdds][prevColor] != -1) {
            return memo[idx][currentOdds][prevColor];
        }

        int minTransitions = INF;
        int currentEvens = (idx - 1) - currentOdds;

        // Option 1: Try assigning color 0 (Even)
        if (canUseColor(idx, 0, currentOdds, currentEvens)) {
            int transitionCost = (prevColor != 0 ? 1 : 0);
            int cost = transitionCost + solveRecursive(idx + 1, currentOdds, 0);
            minTransitions = Math.min(minTransitions, cost);
        }

        // Option 2: Try assigning color 1 (Odd)
        if (canUseColor(idx, 1, currentOdds, currentEvens)) {
            int transitionCost = (prevColor != 1 ? 1 : 0);
            int cost = transitionCost + solveRecursive(idx + 1, currentOdds + 1, 1);
            minTransitions = Math.min(minTransitions, cost);
        }

        return memo[idx][currentOdds][prevColor] = minTransitions;
    }

    public static void main(String[] args) throws IOException {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        // Read N
        String nStr = reader.next();
        if (nStr == null) return;
        int n = Integer.parseInt(nStr);

        // Read constraints
        int[] constraints = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            int x = reader.nextInt();
            // Map input to constraint format: 0 -> wildcard (-1), 1 -> odd (1), 2 -> even (0)
            constraints[i] = (x == 0) ? -1 : (x % 2);
        }

        GarlandColoringProblem solver = new GarlandColoringProblem(n, constraints);
        out.println(solver.solve());
        out.flush();
        out.close();
    }

    /**
     * Efficient utility for reading input.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;

/**
 * Problem: Minimize the number of parity switches in an array given a target
 * number of odd and even elements. Wildcards (0) can be assigned any parity.
 */
public class Solution {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int n = scanner.nextInt();
        int[] inputArray = new int[n];
        int existingOdds = 0;
        int existingEvens = 0;

        for (int i = 0; i < n; i++) {
            inputArray[i] = scanner.nextInt();
            if (inputArray[i] != 0) {
                if (inputArray[i] % 2 != 0) {
                    existingOdds++;
                } else {
                    existingEvens++;
                }
            }
        }

        // Determine the target count of odds and evens required to maintain an alternating pattern.
        int targetOdds, targetEvens;
        if (n % 2 == 0) {
            targetOdds = n / 2;
            targetEvens = n / 2;
        } else {
            targetOdds = n / 2 + 1;
            targetEvens = n / 2;
        }

        // Calculate how many odds and evens we MUST assign to the '0' (wildcard) slots.
        int oddsToAssign = targetOdds - existingOdds;
        int evensToAssign = targetEvens - existingEvens;

        // If the existing array already exceeds the target counts, the requirement is impossible.
        if (oddsToAssign < 0 || evensToAssign < 0) {
            // In a real competition, this might output a specific value; here we handle gracefully.
            System.out.println("-1"); 
        } else {
            ParityMinimizer minimizer = new ParityMinimizer(inputArray, oddsToAssign, evensToAssign);
            System.out.println(minimizer.solve());
        }

        scanner.close();
    }
}

class ParityMinimizer {
    private enum Parity {
        EVEN(0), ODD(1), NONE(2);

        final int value;
        Parity(int value) { this.value = value; }
    }

    private static final int INF = 10000;
    private final int[] array;
    private final int totalOddsToAssign;
    private final int totalEvensToAssign;
    private final int n;

    // Memoization table: [remOdds][remEvens][index][lastParity]
    private final int[][][][] memo;

    public ParityMinimizer(int[] array, int oddsToAssign, int evensToAssign) {
        this.array = array;
        this.totalOddsToAssign = oddsToAssign;
        this.totalEvensToAssign = evensToAssign;
        this.n = array.length;
        this.memo = new int[oddsToAssign + 1][evensToAssign + 1][n][Parity.values().length];

        for (int[][][] d1 : memo) {
            for (int[][] d2 : d1) {
                for (int[] d3 : d2) {
                    Arrays.fill(d3, -1);
                }
            }
        }
    }

    public int solve() {
        return computeMinSwitches(totalOddsToAssign, totalEvensToAssign, 0, Parity.NONE);
    }

    /**
     * Recursive DP function to find the minimum parity switches.
     * 
     * @param remOdds Remaining odd numbers needed to be assigned to wildcards.
     * @param remEvens Remaining even numbers needed to be assigned to wildcards.
     * @param idx Current index in the array being processed.
     * @param lastParity Parity of the previous element.
     * @return Minimum switches from current state to the end.
     */
    private int computeMinSwitches(int remOdds, int remEvens, int idx, Parity lastParity) {
        // Base case: end of array reached.
        if (idx == n) {
            return 0;
        }

        // Check memoization table.
        if (memo[remOdds][remEvens][idx][lastParity.value] != -1) {
            return memo[remOdds][remEvens][idx][lastParity.value];
        }

        int minCost = INF;

        if (array[idx] == 0) {
            // Option 1: Assign an ODD number to this wildcard.
            if (remOdds > 0) {
                int cost = calculateSwitchCost(lastParity, Parity.ODD);
                minCost = Math.min(minCost, cost + computeMinSwitches(remOdds - 1, remEvens, idx + 1, Parity.ODD));
            }

            // Option 2: Assign an EVEN number to this wildcard.
            if (remEvens > 0) {
                int cost = calculateSwitchCost(lastParity, Parity.EVEN);
                minCost = Math.min(minCost, cost + computeMinSwitches(remOdds, remEvens - 1, idx + 1, Parity.EVEN));
            }
        } else {
            // Element is fixed.
            Parity currentParity = (array[idx] % 2 != 0) ? Parity.ODD : Parity.EVEN;
            int cost = calculateSwitchCost(lastParity, currentParity);
            minCost = cost + computeMinSwitches(remOdds, remEvens, idx + 1, currentParity);
        }

        return memo[remOdds][remEvens][idx][lastParity.value] = minCost;
    }

    /**
     * Calculates cost: 1 if parity changes, 0 if same (or if no previous parity exists).
     */
    private int calculateSwitchCost(Parity last, Parity current) {
        if (last == Parity.NONE || last == current) {
            return 0;
        }
        return 1;
    }
}

import java.util.*;

/**
 * A professional refactoring of the ParityGapSolver.
 * This class calculates the minimum/maximum parity changes in a sequence 
 * by intelligently filling gaps of zeros.
 */
public class ParityGapSolver {

    private static class Gap implements Comparable<Gap> {
        final int length;
        final int leftNeighbor;
        final int rightNeighbor;
        boolean isProcessed = false;

        Gap(int length, int leftNeighbor, int rightNeighbor) {
            this.length = length;
            this.leftNeighbor = leftNeighbor;
            this.rightNeighbor = rightNeighbor;
        }

        @Override
        public int compareTo(Gap other) {
            return Integer.compare(this.length, other.length);
        }

        boolean isEdgeGap() {
            return leftNeighbor == -1 || rightNeighbor == -1;
        }

        boolean isMiddleGap() {
            return leftNeighbor != -1 && rightNeighbor != -1;
        }
    }

    public static void main(String[] args) {
        new ParityGapSolver().execute();
    }

    public void execute() {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextInt()) return;

        int n = sc.nextInt();
        int[] array = new int[n];
        boolean[] isNumberPresent = new boolean[n + 1];

        for (int i = 0; i < n; i++) {
            array[i] = sc.nextInt();
            if (array[i] != 0) {
                isNumberPresent[array[i]] = true;
            }
        }
        sc.close();

        int oddCount = 0;
        int evenCount = 0;
        for (int i = 1; i <= n; i++) {
            if (!isNumberPresent[i]) {
                if (i % 2 == 0) evenCount++;
                else oddCount++;
            }
        }

        List<Gap> gaps = findGaps(array);
        Collections.sort(gaps);

        // Step 1: Process Middle Gaps (Matching parity on both sides)
        for (Gap gap : gaps) {
            if (gap.isMiddleGap()) {
                if (isEven(gap.leftNeighbor) && isEven(gap.rightNeighbor)) {
                    if (evenCount >= gap.length) {
                        evenCount -= gap.length;
                        gap.isProcessed = true;
                    }
                } else if (!isEven(gap.leftNeighbor) && !isEven(gap.rightNeighbor)) {
                    if (oddCount >= gap.length) {
                        oddCount -= gap.length;
                        gap.isProcessed = true;
                    }
                }
            }
        }

        // Step 2: Process Edge Gaps
        for (Gap gap : gaps) {
            if (!gap.isProcessed && gap.isEdgeGap()) {
                if (gap.leftNeighbor == -1) {
                    if (isEven(gap.rightNeighbor)) {
                        if (evenCount >= gap.length) {
                            evenCount -= gap.length;
                            gap.isProcessed = true;
                        }
                    } else {
                        if (oddCount >= gap.length) {
                            oddCount -= gap.length;
                            gap.isProcessed = true;
                        }
                    }
                } else if (gap.rightNeighbor == -1) {
                    if (!isEven(gap.leftNeighbor)) {
                        if (oddCount >= gap.length) {
                            oddCount -= gap.length;
                            gap.isProcessed = true;
                        }
                    } else {
                        if (evenCount >= gap.length) {
                            evenCount -= gap.length;
                            gap.isProcessed = true;
                        }
                    }
                }
            }
        }

        // Step 3: Calculate costs for remaining gaps
        int ans = 0;
        for (Gap gap : gaps) {
            if (!gap.isProcessed) {
                if (gap.isMiddleGap()) {
                    if (isEven(gap.leftNeighbor) != isEven(gap.rightNeighbor)) {
                        ans += 1;
                    } else {
                        ans += 2;
                    }
                } else {
                    ans += 1; // Edge gaps cost 1
                }
            }
        }

        // Step 4: Calculate cost for existing neighbors
        for (int i = 0; i < n - 1; i++) {
            if (array[i] != 0 && array[i + 1] != 0) {
                if (isEven(array[i]) != isEven(array[i + 1])) {
                    ans++;
                }
            }
        }

        System.out.println(ans);
    }

    private List<Gap> findGaps(int[] array) {
        List<Gap> gaps = new ArrayList<>();
        int n = array.length;
        for (int i = 0; i < n; i++) {
            if (array[i] == 0) {
                int start = i;
                while (i < n && array[i] == 0) {
                    i++;
                }
                int end = i;
                int leftVal = (start > 0) ? array[start - 1] : -1;
                int rightVal = (end < n) ? array[end] : -1;
                gaps.add(new Gap(end - start, leftVal, rightVal));
            }
        }
        return gaps;
    }

    private boolean isEven(int value) {
        // Handles negative values (like -1) correctly for parity checks
        return value % 2 == 0;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.HashSet;
import java.util.Set;
import java.util.StringTokenizer;

/**
 * A solver to find the minimum number of parity transitions (odd-to-even or even-to-odd)
 * in an array by filling in zero-valued positions with remaining numbers from 1 to N.
 */
public class ParityTransitionSolver {

    private static final int PARITY_EVEN = 0;
    private static final int PARITY_ODD = 1;
    private static final int PARITY_NONE = 2;
    private static final int INF = 100_000_000;

    private final int arrayLength;
    private final int[] numbers;
    private final int[][][] memo;

    public ParityTransitionSolver(int n, int[] numbers) {
        this.arrayLength = n;
        this.numbers = numbers;
        // memo[index][remainingOdds][remainingEvens][lastParity]
        // lastParity: 0=Even, 1=Odd, 2=None
        this.memo = new int[n][n + 1][n + 1][3];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j <= n; j++) {
                for (int k = 0; k <= n; k++) {
                    for (int l = 0; l < 3; l++) {
                        memo[i][j][k][l] = -1;
                    }
                }
            }
        }
    }

    /**
     * Core recursive method using memoization to find the minimum transitions.
     *
     * @param index          Current index in the array being processed.
     * @param remOdd         Count of available odd numbers left in the pool.
     * @param remEven        Count of available even numbers left in the pool.
     * @param lastParity     The parity of the previously processed number.
     * @return The minimum transitions from the current index to the end.
     */
    private int calculateMinTransitions(int index, int remOdd, int remEven, int lastParity) {
        if (index == arrayLength) {
            return 0;
        }

        if (memo[index][remOdd][remEven][lastParity] != -1) {
            return memo[index][remOdd][remEven][lastParity];
        }

        int result;
        if (numbers[index] != 0) {
            // Case 1: Number is fixed
            int currentParity = (numbers[index] % 2 == 0) ? PARITY_EVEN : PARITY_ODD;
            int transitionCost = (lastParity != PARITY_NONE && lastParity != currentParity) ? 1 : 0;
            result = transitionCost + calculateMinTransitions(index + 1, remOdd, remEven, currentParity);
        } else {
            // Case 2: Number is zero, must pick from the available pool
            result = INF;

            // Try picking an odd number
            if (remOdd > 0) {
                int transitionCost = (lastParity != PARITY_NONE && lastParity != PARITY_ODD) ? 1 : 0;
                result = Math.min(result, transitionCost + calculateMinTransitions(index + 1, remOdd - 1, remEven, PARITY_ODD));
            }

            // Try picking an even number
            if (remEven > 0) {
                int transitionCost = (lastParity != PARITY_NONE && lastParity != PARITY_EVEN) ? 1 : 0;
                result = Math.min(result, transitionCost + calculateMinTransitions(index + 1, remOdd, remEven - 1, PARITY_EVEN));
            }
        }

        return memo[index][remOdd][remEven][lastParity] = result;
    }

    public int solve(int initialOdd, int initialEven) {
        return calculateMinTransitions(0, initialOdd, initialEven, PARITY_NONE);
    }

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        try {
            int n = reader.nextInt();
            int[] arr = new int[n];
            Set<Integer> seenNumbers = new HashSet<>();

            for (int i = 0; i < n; i++) {
                arr[i] = reader.nextInt();
                if (arr[i] != 0) {
                    seenNumbers.add(arr[i]);
                }
            }

            // Calculate how many odds and evens are available to fill the zeros
            int availableOdds = 0;
            int availableEvens = 0;
            for (int i = 1; i <= n; i++) {
                if (!seenNumbers.contains(i)) {
                    if (i % 2 != 0) {
                        availableOdds++;
                    } else {
                        availableEvens++;
                    }
                }
            }

            ParityTransitionSolver solver = new ParityTransitionSolver(n, arr);
            System.out.println(solver.solve(availableOdds, availableEvens));

        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Utility class for high-performance input reading.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer tokenizer;

        public FastReader(java.io.InputStream inputStream) {
            br = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * ParityGapSolver solves the problem of calculating minimum changes 
 * required to satisfy specific parity constraints in an array 
 * containing non-zero integers and zero "wildcards".
 */
public class ParityGapSolver {

    private static final PrintWriter out = new PrintWriter(System.out);

    public static void main(String[] args) throws IOException {
        FastReader sc = new FastReader(System.in);
        solve(sc);
        out.close();
    }

    private static void solve(FastReader sc) throws IOException {
        int n = sc.nextInt();
        if (n == 0) {
            out.println(0);
            return;
        }

        int[] elements = new int[n + 2]; // 1-based indexing with padding
        int evenCapacity = n / 2;
        int oddCapacity = (n + 1) / 2;

        for (int i = 1; i <= n; i++) {
            elements[i] = sc.nextInt();
            if (elements[i] != 0) {
                if (elements[i] % 2 == 0) {
                    evenCapacity--;
                } else {
                    oddCapacity--;
                }
            }
        }

        int firstNonNullIdx = 0;
        int lastNonNullIdx = 0;

        // Find the boundaries of non-zero elements
        for (int i = 1; i <= n; i++) {
            if (elements[i] != 0) {
                firstNonNullIdx = i;
                break;
            }
        }

        for (int i = n; i >= 1; i--) {
            if (elements[i] != 0) {
                lastNonNullIdx = i;
                break;
            }
        }

        // Case: All elements are zero
        if (firstNonNullIdx == 0 && lastNonNullIdx == 0) {
            out.println(n > 1 ? 1 : 0);
            return;
        }

        int totalParityChanges = 0;
        List<Gap> gaps = new ArrayList<>();

        // Identify gaps between non-zero elements
        int leftIdx = firstNonNullIdx;
        for (int i = firstNonNullIdx + 1; i <= lastNonNullIdx; i++) {
            if (elements[i] != 0) {
                boolean currentIsEven = (elements[i] % 2 == 0);
                boolean leftIsEven = (elements[leftIdx] % 2 == 0);

                if (currentIsEven != leftIsEven) {
                    // Different parity: immediate transition required
                    totalParityChanges++;
                } else if (i - leftIdx > 1) {
                    // Same parity with a gap of zeros in between
                    gaps.add(new Gap(i - leftIdx - 1, leftIdx, i, leftIsEven));
                }
                leftIdx = i;
            }
        }

        // Sort gaps by size to process them greedily
        Collections.sort(gaps, Comparator.comparingInt(g -> g.size));

        // Process gaps within the non-zero range
        for (Gap gap : gaps) {
            if (gap.isLeftEven) {
                if (evenCapacity >= gap.size) {
                    evenCapacity -= gap.size;
                } else {
                    // If we cannot fill the gap, we incur 2 changes (switch out and switch in)
                    // The original logic treats all internal gaps as requiring 2 changes.
                    totalParityChanges += 2;
                }
            } else {
                if (oddCapacity >= gap.size) {
                    oddCapacity -= gap.size;
                } else {
                    totalParityChanges += 2;
                }
            }
        }

        // Process leading zeros (before the first non-zero element)
        if (firstNonNullIdx > 1) {
            int leadingZeros = firstNonNullIdx - 1;
            if (elements[firstNonNullIdx] % 2 == 0) {
                if (evenCapacity < leadingZeros) totalParityChanges++;
                else evenCapacity -= leadingZeros;
            } else {
                if (oddCapacity < leadingZeros) totalParityChanges++;
                else oddCapacity -= leadingZeros;
            }
        }

        // Process trailing zeros (after the last non-zero element)
        if (lastNonNullIdx < n) {
            int trailingZeros = n - lastNonNullIdx;
            if (elements[lastNonNullIdx] % 2 == 0) {
                if (evenCapacity < trailingZeros) totalParityChanges++;
                else evenCapacity -= trailingZeros;
            } else {
                if (oddCapacity < trailingZeros) totalParityChanges++;
                else oddCapacity -= trailingZeros;
            }
        }

        out.println(totalParityChanges);
    }

    /**
     * Represents a gap of zeros between two non-zero elements of the same parity.
     */
    private static class Gap {
        final int size;
        final int leftIndex;
        final int rightIndex;
        final boolean isLeftEven;

        Gap(int size, int leftIndex, int rightIndex, boolean isLeftEven) {
            this.size = size;
            this.leftIndex = leftIndex;
            this.rightIndex = rightIndex;
            this.isLeftEven = isLeftEven;
        }
    }

    /**
     * Fast I/O reader for competitive programming performance.
     */
    static class FastReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[8192];
        private int curChar;
        private int numChars;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (numChars == -1) throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buffer);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) return -1;
            }
            return buffer[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res = res * 10 + (c - '0');
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to minimize the number of parity transitions in an array 
 * by filling in zeros with available odd and even numbers.
 */
public class Day9 {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int n = reader.nextInt();
            int[] elements = new int[n];
            for (int i = 0; i < n; i++) {
                elements[i] = reader.nextInt();
            }

            ParityMinimizer solver = new ParityMinimizer(n, elements);
            writer.println(solver.solve());
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    static class ParityMinimizer {
        private final int n;
        private final int[] elements;
        private final TreeSet<Integer> oddPool = new TreeSet<>();
        private final TreeSet<Integer> evenPool = new TreeSet<>();

        /**
         * Represents a segment of zeros between two fixed indices.
         */
        private static class Interval implements Comparable<Interval> {
            final int start;
            final int end;
            final int width;

            Interval(int start, int end) {
                this.start = start;
                this.end = end;
                this.width = end - start - 1;
            }

            @Override
            public int compareTo(Interval other) {
                return Integer.compare(this.width, other.width);
            }
        }

        public ParityMinimizer(int n, int[] elements) {
            this.n = n;
            this.elements = elements;
            initializePools();
        }

        /**
         * populates the pools with available numbers from 1 to n 
         * that are not already present in the input array.
         */
        private void initializePools() {
            for (int i = 1; i <= n; i++) {
                if (i % 2 != 0) oddPool.add(i);
                else evenPool.add(i);
            }
            for (int val : elements) {
                if (val != 0) {
                    if (val % 2 != 0) oddPool.remove(val);
                    else evenPool.remove(val);
                }
            }
        }

        public int solve() {
            // 1. Fill gaps between even numbers
            fillGaps(true);
            // 2. Fill gaps between odd numbers
            fillGaps(false);
            // 3. Handle prefix/suffix edge cases
            fillEdges();
            // 4. Fill any remaining zeros greedily
            fillRemaining();
            // 5. Count parity transitions
            return countTransitions();
        }

        /**
         * Finds gaps between consecutive numbers of the same parity 
         * that are not interrupted by the opposite parity.
         */
        private void fillGaps(boolean fillEven) {
            TreeSet<Integer> pool = fillEven ? evenPool : oddPool;
            List<Interval> intervals = new ArrayList<>();
            int prevIdx = -1;

            for (int i = 0; i < n; i++) {
                boolean isFixed = elements[i] != 0;
                boolean isTargetParity = isFixed && (fillEven ? (elements[i] % 2 == 0) : (elements[i] % 2 != 0));
                boolean isOppositeParity = isFixed && (fillEven ? (elements[i] % 2 != 0) : (elements[i] % 2 == 0));

                if (isTargetParity) {
                    if (prevIdx != -1) {
                        intervals.add(new Interval(prevIdx, i));
                    }
                    prevIdx = i;
                } else if (isOppositeParity) {
                    prevIdx = -1;
                }
            }

            Collections.sort(intervals);

            for (Interval interval : intervals) {
                if (pool.size() >= interval.width) {
                    for (int j = interval.start + 1; j < interval.end; j++) {
                        elements[j] = pool.pollFirst();
                    }
                } else {
                    break; // Stop if we can't fill the smallest remaining gap
                }
            }
        }

        private void fillEdges() {
            // Prefix
            if (elements[0] == 0) {
                for (int i = 0; i < n; i++) {
                    if (elements[i] != 0) {
                        boolean isEven = elements[i] % 2 == 0;
                        TreeSet<Integer> pool = isEven ? evenPool : oddPool;
                        if (pool.size() >= i) {
                            for (int j = 0; j < i; j++) elements[j] = pool.pollFirst();
                        }
                        break;
                    }
                }
            }
            // Suffix
            if (elements[n - 1] == 0) {
                for (int i = n - 1; i >= 0; i--) {
                    if (elements[i] != 0) {
                        boolean isEven = elements[i] % 2 == 0;
                        TreeSet<Integer> pool = isEven ? evenPool : oddPool;
                        int dist = n - 1 - i;
                        if (pool.size() >= dist) {
                            for (int j = n - 1; j > i; j--) elements[j] = pool.pollFirst();
                        }
                        break;
                    }
                }
            }
            // Special case: all elements were zero
            if (oddPool.size() + evenPool.size() == n && elements[0] == 0) {
                elements[0] = oddPool.pollFirst();
            }
        }

        private void fillRemaining() {
            for (int i = 0; i < n; i++) {
                if (elements[i] == 0) {
                    // Attempt to match left neighbor
                    if (i > 0 && elements[i - 1] != 0) {
                        if (!tryFillWithParity(i, elements[i - 1] % 2 == 0)) continue;
                    }
                    // Attempt to match right neighbor
                    if (i < n - 1 && elements[i + 1] != 0) {
                        if (!tryFillWithParity(i, elements[i + 1] % 2 == 0)) continue;
                    }
                    // Fallback: fill with whatever is available
                    if (!oddPool.isEmpty()) elements[i] = oddPool.pollFirst();
                    else if (!evenPool.isEmpty()) elements[i] = evenPool.pollFirst();
                }
            }
        }

        private boolean tryFillWithParity(int index, boolean targetEven) {
            TreeSet<Integer> pool = targetEven ? evenPool : oddPool;
            if (!pool.isEmpty()) {
                elements[index] = pool.pollFirst();
                return true;
            }
            return false;
        }

        private int countTransitions() {
            int transitions = 0;
            for (int i = 0; i < n - 1; i++) {
                if (elements[i] != 0 && elements[i + 1] != 0) {
                    if (Math.abs(elements[i] % 2) != Math.abs(elements[i + 1] % 2)) {
                        transitions++;
                    }
                }
            }
            return transitions;
        }
    }

    /**
     * Helper class for fast I/O operations.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;

/**
 * A refactored solution for the Parity Balancing problem.
 * The program calculates the minimum number of operations required to 
 * achieve a target count of even and odd numbers in an array, 
 * where zeros act as wildcards.
 */
public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int n = scanner.nextInt();
        int[] numbers = new int[n];

        // Target counts for even and odd numbers
        int targetEvenCount = n / 2;
        int targetOddCount = n - targetEvenCount;

        // How many more evens/odds we need to reach the target
        int evenNeeded = targetEvenCount;
        int oddNeeded = targetOddCount;

        for (int i = 0; i < n; i++) {
            numbers[i] = scanner.nextInt();
            if (numbers[i] != 0) {
                if (numbers[i] % 2 == 0) {
                    evenNeeded--;
                } else {
                    oddNeeded--;
                }
            }
        }

        int operationsCount = 0;
        int isInsideZeroSequence = 0; // 0: normal, 1: inside a sequence of zeros
        int lastNonZeroIndex = -1;

        List<Integer> evenGaps = new ArrayList<>();
        List<Integer> oddGaps = new ArrayList<>();
        List<Integer> specialEvenGaps = new ArrayList<>();
        List<Integer> specialOddGaps = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            if (numbers[i] == 0) {
                if (isInsideZeroSequence == 0) {
                    isInsideZeroSequence = 1;
                    lastNonZeroIndex = i - 1;
                }
            } else {
                if (isInsideZeroSequence == 1) {
                    isInsideZeroSequence = 0;
                    if (lastNonZeroIndex == -1) {
                        // Case: Leading zeros
                        if (numbers[i] % 2 == 0) {
                            specialEvenGaps.add(i);
                        } else {
                            specialOddGaps.add(i);
                        }
                    } else {
                        // Case: Zero gap between two non-zero segments
                        if (numbers[i] % 2 == 0 && numbers[lastNonZeroIndex] % 2 == 0) {
                            evenGaps.add(i - lastNonZeroIndex - 1);
                        } else if (Math.abs(numbers[i] % 2) == 1 && Math.abs(numbers[lastNonZeroIndex] % 2) == 1) {
                            oddGaps.add(i - lastNonZeroIndex - 1);
                        } else {
                            // Parity switch across a zero gap costs 1
                            operationsCount++;
                        }
                    }
                } else {
                    // Case: Continuous non-zero block - count internal parity switches
                    if (i > 0 && (Math.abs(numbers[i] % 2) != Math.abs(numbers[i - 1] % 2))) {
                        operationsCount++;
                    }
                }
            }
        }

        // Handle trailing zeros
        if (isInsideZeroSequence == 1) {
            if (lastNonZeroIndex < 0) {
                // Entire array consists of zeros
                if (n > 1) {
                    System.out.println(1);
                } else {
                    System.out.println(0);
                }
                return;
            } else {
                int trailingZerosCount = n - lastNonZeroIndex - 1;
                if (numbers[lastNonZeroIndex] % 2 == 0) {
                    specialEvenGaps.add(trailingZerosCount);
                } else {
                    specialOddGaps.add(trailingZerosCount);
                }
            }
        }

        // Sort gaps to greedily apply them to the requirements
        Collections.sort(evenGaps);
        Collections.sort(oddGaps);
        Collections.sort(specialEvenGaps);
        Collections.sort(specialOddGaps);

        // Process regular even gaps
        for (int gap : evenGaps) {
            if (gap <= evenNeeded) {
                evenNeeded -= gap;
            } else {
                operationsCount += 2;
            }
        }

        // Process special even gaps (limited to top 2 as per original logic)
        int processedSpecialEven = 0;
        for (int gap : specialEvenGaps) {
            if (processedSpecialEven < 2) {
                if (gap <= evenNeeded) {
                    evenNeeded -= gap;
                } else {
                    operationsCount++;
                }
                processedSpecialEven++;
            }
        }

        // Process regular odd gaps
        for (int gap : oddGaps) {
            if (gap <= oddNeeded) {
                oddNeeded -= gap;
            } else {
                operationsCount += 2;
            }
        }

        // Process special odd gaps (limited to top 2 as per original logic)
        int processedSpecialOdd = 0;
        for (int gap : specialOddGaps) {
            if (processedSpecialOdd < 2) {
                if (gap <= oddNeeded) {
                    oddNeeded -= gap;
                } else {
                    operationsCount++;
                }
                processedSpecialOdd++;
            }
        }

        System.out.println(operationsCount);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.StringTokenizer;

/**
 * WorkFile calculates the minimum number of parity transitions in an array 
 * by optimally filling zero-valued positions with a required number of even 
 * and odd integers.
 */
public class WorkFile {

    public static void main(String[] args) {
        FastReader sc = new FastReader();
        try {
            String nLine = sc.nextLine();
            if (nLine == null || nLine.trim().isEmpty()) return;
            int n = Integer.parseInt(nLine.trim());

            String arrLine = sc.nextLine();
            if (arrLine == null) return;
            StringTokenizer st = new StringTokenizer(arrLine);
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                if (st.hasMoreTokens()) {
                    arr[i] = Integer.parseInt(st.nextToken());
                }
            }

            ParityTransitionSolver solver = new ParityTransitionSolver(n, arr);
            System.out.println(solver.solve());

        } catch (NumberFormatException e) {
            // In a production environment, use a proper logging framework
        }
    }

    /**
     * Utility class for efficient input reading.
     */
    private static class FastReader {
        private final BufferedReader reader;

        public FastReader() {
            reader = new BufferedReader(new InputStreamReader(System.in));
        }

        public String nextLine() {
            try {
                return reader.readLine();
            } catch (IOException e) {
                return null;
            }
        }
    }

    /**
     * Encapsulates the logic for solving the parity transition problem.
     */
    private static class ParityTransitionSolver {
        private final int n;
        private final int[] arr;
        private final int targetEvenCount;
        private final int targetOddCount;

        private static final int INF = 1_000_000_000;

        public ParityTransitionSolver(int n, int[] arr) {
            this.n = n;
            this.arr = arr;
            // The total parity budget for the final array
            this.targetEvenCount = n / 2;
            this.targetOddCount = (n / 2) + (n % 2);
        }

        /**
         * Executes the core solver logic.
         * @return The minimum number of parity transitions.
         */
        public int solve() {
            int initialTransitions = 0;
            int evenCountInArr = 0;
            int oddCountInArr = 0;
            List<Integer> nonZeroIndices = new ArrayList<>();

            // Step 1: Analyze the existing array
            for (int i = 0; i < n; i++) {
                if (arr[i] != 0) {
                    nonZeroIndices.add(i);
                    if (isEven(arr[i])) evenCountInArr++;
                    else oddCountInArr++;

                    if (i > 0 && arr[i - 1] != 0) {
                        if (isParityDifferent(arr[i - 1], arr[i])) {
                            initialTransitions++;
                        }
                    }
                }
            }

            // Handle edge case: no non-zero elements present
            if (nonZeroIndices.isEmpty()) {
                return (n == 1) ? 0 : 1;
            }

            int evenNeeded = targetEvenCount - evenCountInArr;
            int oddNeeded = targetOddCount - oddCountInArr;

            // Step 2: DP to minimize cost of filling zero gaps
            // dp[e][o] represents the minimum cost using 'e' even and 'o' odd numbers
            int[][] dp = new int[evenNeeded + 1][oddNeeded + 1];
            for (int[] row : dp) {
                Arrays.fill(row, INF);
            }
            dp[0][0] = 0;

            // Process segment before the first non-zero element
            int firstIdx = nonZeroIndices.get(0);
            if (firstIdx > 0) {
                applyGapUpdate(dp, evenNeeded, oddNeeded, firstIdx, 
                    (k, m) -> calculateBoundaryGapCost(k, m, arr[firstIdx]));
            }

            // Process segments between non-zero elements
            for (int i = 0; i < nonZeroIndices.size() - 1; i++) {
                int startIdx = nonZeroIndices.get(i);
                int endIdx = nonZeroIndices.get(i + 1);
                int gapSize = endIdx - startIdx - 1;
                if (gapSize > 0) {
                    int startVal = arr[startIdx];
                    int endVal = arr[endIdx];
                    applyGapUpdate(dp, evenNeeded, oddNeeded, gapSize, 
                        (k, m) -> calculateMiddleGapCost(k, m, startVal, endVal));
                }
            }

            // Process segment after the last non-zero element
            int lastIdx = nonZeroIndices.get(nonZeroIndices.size() - 1);
            int endGapSize = n - 1 - lastIdx;
            if (endGapSize > 0) {
                applyGapUpdate(dp, evenNeeded, oddNeeded, endGapSize, 
                    (k, m) -> calculateBoundaryGapCost(k, m, arr[lastIdx]));
            }

            return initialTransitions + dp[evenNeeded][oddNeeded];
        }

        private boolean isEven(int val) {
            return val % 2 == 0;
        }

        private boolean isParityDifferent(int a, int b) {
            return isEven(a) != isEven(b);
        }

        /**
         * Updates the DP table by considering all possible ways to fill a gap of a given size.
         */
        private void applyGapUpdate(int[][] dp, int evenLimit, int oddLimit, int gapSize, GapCostCalculator costCalc) {
            // Iterate backwards through the DP table to treat this segment as a single item (Knapsack style)
            for (int i = evenLimit; i >= 0; i--) {
                for (int j = oddLimit; j >= 0; j--) {
                    for (int k = 0; k <= gapSize; k++) {
                        int m = gapSize - k; // number of odds
                        if (k <= i && m <= j) {
                            int prevCost = dp[i - k][j - m];
                            if (prevCost != INF) {
                                int currentGapCost = costCalc.calculate(k, m);
                                dp[i][j] = Math.min(dp[i][j], prevCost + currentGapCost);
                            }
                        }
                    }
                }
            }
        }

        /**
         * Cost for gaps at the start or end of the array.
         */
        private int calculateBoundaryGapCost(int k, int m, int adjacentVal) {
            int gapSize = k + m;
            if (gapSize == 0) return 0;
            int cost = 1;
            if (k == gapSize && isEven(adjacentVal)) cost = 0;
            if (k == 0 && !isEven(adjacentVal)) cost = 0;
            return cost;
        }

        /**
         * Cost for gaps between two non-zero elements.
         */
        private int calculateMiddleGapCost(int k, int m, int startVal, int endVal) {
            int gapSize = k + m;
            if (gapSize == 0) return 0;
            int cost = 2;
            if (isParityDifferent(startVal, endVal)) cost = 1;

            // Special case: if all inserted elements match the parity of both boundaries
            if (isEven(startVal) && isEven(endVal) && k == gapSize) cost = 0;
            if (!isEven(startVal) && !isEven(endVal) && k == 0) cost = 0;

            return cost;
        }

        @FunctionalInterface
        private interface GapCostCalculator {
            int calculate(int k, int m);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution to calculate the minimum operations required 
 * to fill parity-based constraints in an array.
 */
public class Main {

    public static void main(String[] args) {
        FastReader in = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        solve(in, out);

        out.close();
    }

    private static void solve(FastReader in, PrintWriter out) {
        int n = in.nextInt();
        if (n <= 0) return;

        int[] p = new int[n];
        for (int i = 0; i < n; i++) {
            p[i] = in.nextInt();
        }

        // Step 1: Calculate available even and odd numbers to fill the zeros
        int availableEven = n / 2;
        int availableOdd = (n / 2) + (n % 2);

        for (int val : p) {
            if (val != 0) {
                if (val % 2 == 0) {
                    availableEven--;
                } else {
                    availableOdd--;
                }
            }
        }

        // Edge Case: If all elements are zero
        if (availableEven + availableOdd == n) {
            out.println(n == 1 ? 0 : 1);
            return;
        }

        // Step 2: Categorize segments of zeros (gaps)
        PriorityQueue<Integer> evenEvenGaps = new PriorityQueue<>();
        PriorityQueue<Integer> oddOddGaps = new PriorityQueue<>();
        int differentParityGapsCount = 0;
        int adjacencyTransitions = 0;

        int prefixGapLenEven = 0;
        int prefixGapLenOdd = 0;
        int suffixGapLenEven = 0;
        int suffixGapLenOdd = 0;

        for (int i = 0; i < n; i++) {
            if (p[i] == 0) {
                int start = i;
                while (i < n && p[i] == 0) {
                    i++;
                }
                int end = i; // The index of the first non-zero element or n
                int gapLen = end - start;

                if (start == 0) {
                    // Gap at the beginning of the array
                    if (end < n) {
                        if (p[end] % 2 == 0) prefixGapLenEven = gapLen;
                        else prefixGapLenOdd = gapLen;
                    }
                } else if (end == n) {
                    // Gap at the end of the array
                    if (p[start - 1] % 2 == 0) suffixGapLenEven = gapLen;
                    else suffixGapLenOdd = gapLen;
                } else {
                    // Gap between two non-zero elements
                    int leftParity = Math.abs(p[start - 1] % 2);
                    int rightParity = Math.abs(p[end] % 2);

                    if (leftParity == rightParity) {
                        if (leftParity == 0) evenEvenGaps.add(gapLen);
                        else oddOddGaps.add(gapLen);
                    } else {
                        // Different parity endpoints cost 1 operation per gap
                        differentParityGapsCount++;
                    }
                }
                // Adjust index for the for-loop increment
                i--;
            } else {
                // Check for parity transitions between adjacent non-zero elements
                if (i > 0 && p[i - 1] != 0) {
                    if ((Math.abs(p[i - 1] % 2) + Math.abs(p[i] % 2)) % 2 == 1) {
                        adjacencyTransitions++;
                    }
                }
            }
        }

        // Step 3: Greedy calculation of total cost
        int totalCost = adjacencyTransitions + differentParityGapsCount;

        // Process middle gaps with same-parity endpoints greedily (smallest first)
        // Even-Even gaps: Cost 0 if we have enough even numbers, else cost 2
        while (!evenEvenGaps.isEmpty()) {
            int gapLen = evenEvenGaps.poll();
            if (availableEven >= gapLen) {
                availableEven -= gapLen;
            } else {
                totalCost += 2;
            }
        }

        // Odd-Odd gaps: Cost 0 if we have enough odd numbers, else cost 2
        while (!oddOddGaps.isEmpty()) {
            int gapLen = oddOddGaps.poll();
            if (availableOdd >= gapLen) {
                availableOdd -= gapLen;
            } else {
                totalCost += 2;
            }
        }

        // Process prefix gaps: Cost 0 if correct parity available, else cost 1
        if (prefixGapLenEven > 0) {
            if (availableEven >= prefixGapLenEven) availableEven -= prefixGapLenEven;
            else totalCost++;
        } else if (prefixGapLenOdd > 0) {
            if (availableOdd >= prefixGapLenOdd) availableOdd -= prefixGapLenOdd;
            else totalCost++;
        }

        // Process suffix gaps: Cost 0 if correct parity available, else cost 1
        if (suffixGapLenEven > 0) {
            if (availableEven >= suffixGapLenEven) availableEven -= suffixGapLenEven;
            else totalCost++;
        } else if (suffixGapLenOdd > 0) {
            if (availableOdd >= suffixGapLenOdd) availableOdd -= suffixGapLenOdd;
            else totalCost++;
        }

        out.println(totalCost);
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the Codeforces problem.
 * The goal is to find the minimum number of operations to fill gaps in an array
 * while maintaining a specific parity pattern.
 */
public class Codeforces {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int n = reader.nextInt();
            int[] array = reader.nextIntArray(n);

            CodeforcesSolver solver = new CodeforcesSolver();
            int result = solver.solve(n, array);

            writer.println(result);
        } catch (Exception e) {
            // In a production environment, use a logger
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    enum Parity {
        EVEN, ODD
    }

    /**
     * Represents a contiguous block of zeros (a gap) in the array.
     */
    static class Gap implements Comparable<Gap> {
        private final Parity parity;
        private final int length;

        public Gap(Parity parity, int length) {
            this.parity = parity;
            this.length = length;
        }

        public Parity getParity() {
            return parity;
        }

        public int getLength() {
            return length;
        }

        @Override
        public int compareTo(Gap other) {
            return Integer.compare(this.length, other.length);
        }
    }

    /**
     * Holds the results of the gap analysis phase.
     */
    static class GapAnalysis {
        int initialTransitions;
        List<Gap> closedGaps = new ArrayList<>();
        List<Gap> openGaps = new ArrayList<>();

        public GapAnalysis(int initialTransitions) {
            this.initialTransitions = initialTransitions;
        }
    }

    /**
     * Orchestrates the calculation logic.
     */
    static class CodeforcesSolver {

        public int solve(int n, int[] array) {
            ParityCounts missing = countMissingParities(array, n);

            // Special case: if the array is entirely empty
            if (missing.isEntirelyMissing(n)) {
                return (n == 1) ? 0 : 1;
            }

            GapAnalysis analysis = analyzeGaps(array, n);
            return calculateMinOperations(analysis, missing);
        }

        private ParityCounts countMissingParities(int[] array, int n) {
            boolean[] present = new boolean[n + 1];
            for (int val : array) {
                if (val != 0) {
                    present[val] = true;
                }
            }

            int even = 0;
            int odd = 0;
            for (int i = 1; i <= n; i++) {
                if (!present[i]) {
                    if (i % 2 == 0) even++;
                    else odd++;
                }
            }
            return new ParityCounts(even, odd);
        }

        private GapAnalysis analyzeGaps(int[] array, int n) {
            GapAnalysis analysis = new GapAnalysis(0);
            List<Integer> nonZeroIndices = new ArrayList<>();

            for (int i = 0; i < n; i++) {
                if (array[i] != 0) {
                    nonZeroIndices.add(i);
                }
            }

            // 1. Analyze transitions and closed gaps between non-zero elements
            for (int k = 0; k < nonZeroIndices.size() - 1; k++) {
                int idx1 = nonZeroIndices.get(k);
                int idx2 = nonZeroIndices.get(k + 1);

                if (array[idx1] % 2 != array[idx2] % 2) {
                    analysis.initialTransitions++;
                } else if (idx2 - idx1 > 1) {
                    // A gap exists between two elements of the same parity
                    analysis.closedGaps.add(new Gap(getParity(array[idx1]), idx2 - idx1 - 1));
                }
            }

            // 2. Analyze open gaps at the boundaries
            if (!nonZeroIndices.isEmpty()) {
                int firstIdx = nonZeroIndices.get(0);
                if (firstIdx > 0) {
                    analysis.openGaps.add(new Gap(getParity(array[firstIdx]), firstIdx));
                }

                int lastIdx = nonZeroIndices.get(nonZeroIndices.size() - 1);
                if (lastIdx < n - 1) {
                    analysis.openGaps.add(new Gap(getParity(array[lastIdx]), n - 1 - lastIdx));
                }
            }

            return analysis;
        }

        private int calculateMinOperations(GapAnalysis analysis, ParityCounts missing) {
            int res = analysis.initialTransitions;
            int evenAvailable = missing.evenCount;
            int oddAvailable = missing.oddCount;

            // Process closed gaps: they are more "expensive" to fix if they can't be filled
            Collections.sort(analysis.closedGaps);
            for (Gap gap : analysis.closedGaps) {
                if (gap.getParity() == Parity.EVEN) {
                    if (evenAvailable >= gap.getLength()) {
                        evenAvailable -= gap.getLength();
                    } else {
                        res += 2;
                    }
                } else {
                    if (oddAvailable >= gap.getLength()) {
                        oddAvailable -= gap.getLength();
                    } else {
                        res += 2;
                    }
                }
            }

            // Process open gaps: they are cheaper to fix
            for (Gap gap : analysis.openGaps) {
                if (gap.getParity() == Parity.EVEN) {
                    if (evenAvailable < gap.getLength()) {
                        res++;
                    }
                } else {
                    if (oddAvailable < gap.getLength()) {
                        res++;
                    }
                }
            }

            return res;
        }

        private Parity getParity(int value) {
            return (value % 2 == 0) ? Parity.EVEN : Parity.ODD;
        }
    }

    static class ParityCounts {
        final int evenCount;
        final int oddCount;

        ParityCounts(int even, int odd) {
            this.evenCount = even;
            this.oddCount = odd;
        }

        boolean isEntirelyMissing(int n) {
            return (evenCount + oddCount) == n;
        }
    }

    /**
     * Efficient I/O utility.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public int[] nextIntArray(int n) {
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }
    }
}

import java.util.Scanner;

/**
 * Refactored Garland program to minimize/manage parity transitions
 * in a sequence of odd and even numbers.
 */
public class Garland {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int n = scanner.nextInt();
        int[] inputArr = new int[n];
        for (int i = 0; i < n; i++) {
            inputArr[i] = scanner.nextInt();
        }

        GarlandProcessor processor = new GarlandProcessor(n, inputArr);
        System.out.println(processor.solve());

        scanner.close();
    }

    /**
     * Logic handler for processing the garland.
     */
    private static class GarlandProcessor {
        private static final int EMPTY = 0;
        private static final int ODD = 1;
        private static final int EVEN = 2;

        private final int size;
        private final int[] garland;
        private int oddRemaining;
        private int evenRemaining;
        private int firstNonZeroIndex = -1;
        private int lastNonZeroIndex = -1;

        public GarlandProcessor(int n, int[] input) {
            this.size = n;
            this.garland = input.clone();

            // Initialize the budget of available Odd and Even numbers
            // The original logic assumes an alternating pattern is the baseline
            this.oddRemaining = (n % 2 == 0) ? (n / 2) : (n / 2) + 1;
            this.evenRemaining = n / 2;

            identifyNonZeroBoundaries();
        }

        /**
         * Finds the first and last non-zero indices and updates the remaining budget.
         */
        private void identifyNonZeroBoundaries() {
            for (int i = 0; i < size; i++) {
                if (garland[i] != EMPTY) {
                    if (firstNonZeroIndex == -1) {
                        firstNonZeroIndex = i;
                    }
                    lastNonZeroIndex = i;

                    if (isEven(garland[i])) {
                        evenRemaining--;
                    } else {
                        oddRemaining--;
                    }
                }
            }
        }

        /**
         * Orchestrates the filling process and returns the final transition count.
         */
        public int solve() {
            // Edge case: no numbers are placed in the garland
            if (firstNonZeroIndex == -1) {
                return (size == 1) ? 0 : 1;
            }

            fillInternalGapsWithSameParity();
            fillSuffix();
            fillPrefix();
            fillRemainingZeros();

            return countParityTransitions();
        }

        /**
         * Phase 1: Fills gaps between two numbers of the same parity 
         * if the budget allows, to prevent unnecessary transitions.
         */
        private void fillInternalGapsWithSameParity() {
            boolean[] gapDistancesExist = new boolean[size];
            int lastIdx = -1;

            // Identify all gap distances currently present in the garland
            for (int i = 0; i < size; i++) {
                if (garland[i] != EMPTY) {
                    if (lastIdx != -1) {
                        int gapSize = i - lastIdx - 1;
                        if (gapSize > 0) {
                            gapDistancesExist[gapSize] = true;
                        }
                    }
                    lastIdx = i;
                }
            }

            // Iterate through identified gap distances to fill them
            for (int dist = 1; dist < size; dist++) {
                if (!gapDistancesExist[dist]) continue;

                for (int j = 0; j < size - dist - 1; j++) {
                    int k = j + dist + 1;
                    if (garland[j] != EMPTY && garland[k] != EMPTY &&
                            hasSameParity(j, k) && isGapAllZeros(j, dist)) {

                        if (isEven(garland[j]) && evenRemaining >= dist) {
                            fillRange(j + 1, dist, EVEN);
                            evenRemaining -= dist;
                        } else if (isOdd(garland[j]) && oddRemaining >= dist) {
                            fillRange(j + 1, dist, ODD);
                            oddRemaining -= dist;
                        }
                    }
                }
            }
        }

        /**
         * Phase 2: Fills the trailing zeros after the last non-zero element.
         */
        private void fillSuffix() {
            if (lastNonZeroIndex < size - 1) {
                int suffixLen = size - lastNonZeroIndex - 1;
                int fillValue = EMPTY;

                if (isEven(garland[lastNonZeroIndex]) && evenRemaining >= suffixLen) {
                    fillValue = EVEN;
                    evenRemaining -= suffixLen;
                } else if (isOdd(garland[lastNonZeroIndex]) && oddRemaining >= suffixLen) {
                    fillValue = ODD;
                    oddRemaining -= suffixLen;
                }

                if (fillValue != EMPTY) {
                    fillRange(lastNonZeroIndex + 1, suffixLen, fillValue);
                }
            }
        }

        /**
         * Phase 3: Fills the leading zeros before the first non-zero element.
         */
        private void fillPrefix() {
            for (int i = firstNonZeroIndex - 1; i >= 0; i--) {
                // Try to match the parity of the element to its right
                if (isEven(garland[i + 1])) {
                    if (evenRemaining > 0) {
                        evenRemaining--;
                        garland[i] = EVEN;
                    } else {
                        oddRemaining--;
                        garland[i] = ODD;
                    }
                } else {
                    if (oddRemaining > 0) {
                        oddRemaining--;
                        garland[i] = ODD;
                    } else {
                        evenRemaining--;
                        garland[i] = EVEN;
                    }
                }
            }
        }

        /**
         * Phase 4: Fills any remaining zeros with a default parity.
         */
        private void fillRemainingZeros() {
            for (int i = firstNonZeroIndex + 1; i < size; i++) {
                if (garland[i] == EMPTY) {
                    garland[i] = ODD;
                }
            }
        }

        private int countParityTransitions() {
            int transitions = 0;
            for (int i = 0; i < size - 1; i++) {
                if (hasDifferentParity(i, i + 1)) {
                    transitions++;
                }
            }
            return transitions;
        }

        // --- Helper Methods ---

        private boolean isEven(int val) {
            return val != EMPTY && val % 2 == 0;
        }

        private boolean isOdd(int val) {
            return val != EMPTY && val % 2 != 0;
        }

        private boolean hasSameParity(int idx1, int idx2) {
            return (isEven(garland[idx1]) && isEven(garland[idx2])) ||
                   (isOdd(garland[idx1]) && isOdd(garland[idx2]));
        }

        private boolean hasDifferentParity(int idx1, int idx2) {
            return (isEven(garland[idx1]) && isOdd(garland[idx2])) ||
                   (isOdd(garland[idx1]) && isEven(garland[idx2]));
        }

        private boolean isGapAllZeros(int startIdx, int gapSize) {
            for (int i = startIdx + 1; i <= startIdx + gapSize; i++) {
                if (garland[i] != EMPTY) return false;
            }
            return true;
        }

        private void fillRange(int startIdx, int length, int value) {
            for (int i = startIdx; i < startIdx + length; i++) {
                garland[i] = value;
            }
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * This program solves the problem of finding the minimum number of parity switches 
 * (even to odd or odd to even) in a sequence, given a fixed number of 
 * even and odd elements required.
 */
public class ParitySequenceMinimizer {

    // Constants to replace magic numbers
    private static final int PARITY_EVEN = 0;
    private static final int PARITY_ODD = 1;
    private static final int PARITY_UNKNOWN = -1;
    private static final int NO_PREVIOUS_PARITY = 2;

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            // The original code had a loop for t=1, kept for structure
            int testCases = 1;
            while (testCases-- > 0) {
                int n = scanner.nextInt();
                solve(n, scanner, out);
            }
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        } finally {
            out.flush();
            out.close();
        }
    }

    private static void solve(int n, FastScanner scanner, PrintWriter out) throws IOException {
        int totalOddsNeeded = n / 2;
        int totalEvensNeeded = n / 2;
        if (n % 2 != 0) {
            totalOddsNeeded++;
        }

        int[] paritySequence = new int[n];
        int remainingOdds = totalOddsNeeded;
        int remainingEvens = totalEvensNeeded;

        for (int i = 0; i < n; i++) {
            int num = scanner.nextInt();
            if (num == 0) {
                paritySequence[i] = PARITY_UNKNOWN;
            } else {
                if (num % 2 == 0) {
                    remainingEvens--;
                    paritySequence[i] = PARITY_EVEN;
                } else {
                    remainingOdds--;
                    paritySequence[i] = PARITY_ODD;
                }
            }
        }

        ParitySequenceOptimizer optimizer = new ParitySequenceOptimizer(n, paritySequence, remainingOdds, remainingEvens);
        out.println(optimizer.computeMinSwitches());
    }

    /**
     * Logic engine for calculating the minimum parity switches using Dynamic Programming.
     */
    static class ParitySequenceOptimizer {
        private final int n;
        private final int[] paritySequence;
        private final int targetOdds;
        private final int targetEvens;
        private final int[][][][] memo;

        // Large value to represent infinity for minimization
        private static final int INF = 1_000_000;

        public ParitySequenceOptimizer(int n, int[] paritySequence, int targetOdds, int targetEvens) {
            this.n = n;
            this.paritySequence = paritySequence;
            this.targetOdds = targetOdds;
            this.targetEvens = targetEvens;
            // DP State: [index][remainingOdds][remainingEvens][previousParity]
            this.memo = new int[n][targetOdds + 1][targetEvens + 1][3];
            initializeMemo();
        }

        private void initializeMemo() {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j <= targetOdds; j++) {
                    for (int k = 0; k <= targetEvens; k++) {
                        Arrays.fill(memo[i][j][k], -1);
                    }
                }
            }
        }

        public int computeMinSwitches() {
            return recurse(0, targetOdds, targetEvens, NO_PREVIOUS_PARITY);
        }

        /**
         * Recursive DP function with memoization.
         * 
         * @param index Current element index being processed
         * @param odds Remaining odd numbers to place
         * @param evens Remaining even numbers to place
         * @param prevParity Parity of the previous element (0: even, 1: odd, 2: none)
         * @return Minimum switches from this state to the end
         */
        private int recurse(int index, int odds, int evens, int prevParity) {
            // Base case: reached the end of the sequence
            if (index == n) {
                return 0;
            }

            // Return memoized result if available
            if (memo[index][odds][evens][prevParity] != -1) {
                return memo[index][odds][evens][prevParity];
            }

            int result;

            if (paritySequence[index] != PARITY_UNKNOWN) {
                // Current element is fixed
                int currentParity = paritySequence[index];
                int switchPenalty = (isSwitch(currentParity, prevParity)) ? 1 : 0;
                result = switchPenalty + recurse(index + 1, odds, evens, currentParity);
            } else {
                // Current element is unknown, try both odd and even
                int minSwitchesIfOdd = INF;
                int minSwitchesIfEven = INF;

                // Option 1: Try placing an Odd number
                if (odds > 0) {
                    int switchPenalty = (isSwitch(PARITY_ODD, prevParity)) ? 1 : 0;
                    minSwitchesIfOdd = switchPenalty + recurse(index + 1, odds - 1, evens, PARITY_ODD);
                }

                // Option 2: Try placing an Even number
                if (evens > 0) {
                    int switchPenalty = (isSwitch(PARITY_EVEN, prevParity)) ? 1 : 0;
                    minSwitchesIfEven = switchPenalty + recurse(index + 1, odds, evens - 1, PARITY_EVEN);
                }

                result = Math.min(minSwitchesIfOdd, minSwitchesIfEven);
            }

            memo[index][odds][evens][prevParity] = result;
            return result;
        }

        private boolean isSwitch(int currentParity, int prevParity) {
            if (prevParity == NO_PREVIOUS_PARITY) return false;
            return currentParity != prevParity;
        }
    }

    /**
     * Utility class for fast input reading.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream is) {
            reader = new BufferedReader(new InputStreamReader(is));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * ParityGapSolver calculates the minimum number of operations required to satisfy 
 * parity constraints in an array by filling gaps with available even or odd numbers.
 */
public class ParityGapSolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            String firstLine = reader.next();
            if (firstLine == null) {
                return;
            }
            int n = Integer.parseInt(firstLine);

            // Data structures to track the input and the pool of available numbers
            int[] nums = new int[n];
            List<Integer> positiveIndices = new ArrayList<>();
            Set<Integer> missingValues = new HashSet<>();

            // Initialize the set of values from 1 to N that could potentially fill gaps
            for (int i = 1; i <= n; i++) {
                missingValues.add(i);
            }

            // Read input and identify indices of positive numbers
            for (int i = 0; i < n; i++) {
                nums[i] = reader.nextInt();
                if (nums[i] > 0) {
                    missingValues.remove(nums[i]);
                    positiveIndices.add(i);
                }
            }

            // Calculate how many even and odd numbers are available in the 'missing' pool
            int evenPoolCount = 0;
            int oddPoolCount = 0;
            for (int val : missingValues) {
                if (val % 2 == 0) {
                    evenPoolCount++;
                } else {
                    oddPoolCount++;
                }
            }

            // Solve and output the result
            int result = calculateMinOperations(n, nums, positiveIndices, evenPoolCount, oddPoolCount);
            out.println(result);

        } catch (Exception e) {
            // In a production environment, use a logger
        } finally {
            out.close();
        }
    }

    /**
     * Core algorithm to determine the minimum operations.
     * 
     * @param n Total size of the array.
     * @param nums The input array.
     * @param positiveIndices List of indices where nums[i] > 0.
     * @param evenPool Number of available even integers from the missing set.
     * @param oddPool Number of available odd integers from the missing set.
     * @return The minimum number of operations.
     */
    private static int calculateMinOperations(int n, int[] nums, List<Integer> positiveIndices, int evenPool, int oddPool) {
        if (n == 1) {
            return 0;
        }
        // If no positive numbers are present, it requires one operation to establish parity.
        if (positiveIndices.isEmpty()) {
            return 1;
        }

        int operations = 0;

        // 1. Count operations required by adjacent positive numbers with different parities.
        for (int i = 1; i < n; i++) {
            if (nums[i] > 0 && nums[i - 1] > 0 && (nums[i] % 2 != nums[i - 1] % 2)) {
                operations++;
            }
        }

        // 2. Categorize gaps between positive numbers or array boundaries.
        // We use -1 and n as virtual boundaries to treat edges as gaps.
        List<Integer> gapBoundaries = new ArrayList<>();
        gapBoundaries.add(-1);
        gapBoundaries.addAll(positiveIndices);
        gapBoundaries.add(n);

        List<Integer> evenInternalGaps = new ArrayList<>();
        List<Integer> oddInternalGaps = new ArrayList<>();
        List<Integer> evenEdgeGaps = new ArrayList<>();
        List<Integer> oddEdgeGaps = new ArrayList<>();

        for (int i = 1; i < gapBoundaries.size(); i++) {
            int prevIdx = gapBoundaries.get(i - 1);
            int currIdx = gapBoundaries.get(i);
            int gapSize = currIdx - prevIdx - 1;

            if (gapSize <= 0) {
                continue;
            }

            if (i == 1) {
                // Edge Gap: Gap at the very beginning of the array.
                // Parity is determined by the first positive number encountered.
                if (nums[gapBoundaries.get(1)] % 2 == 0) {
                    evenEdgeGaps.add(gapSize);
                } else {
                    oddEdgeGaps.add(gapSize);
                }
            } else if (i == gapBoundaries.size() - 1) {
                // Edge Gap: Gap at the very end of the array.
                // Parity is determined by the last positive number encountered.
                if (nums[gapBoundaries.get(i - 1)] % 2 == 0) {
                    evenEdgeGaps.add(gapSize);
                } else {
                    oddEdgeGaps.add(gapSize);
                }
            } else {
                // Internal Gap: Gap between two existing positive numbers.
                int valBefore = nums[gapBoundaries.get(i - 1)];
                int valAfter = nums[gapBoundaries.get(i)];

                if (valBefore % 2 == 0 && valAfter % 2 == 0) {
                    evenInternalGaps.add(gapSize);
                } else if (valBefore % 2 != 0 && valAfter % 2 != 0) {
                    oddInternalGaps.add(gapSize);
                } else {
                    // Different parities on either side of a gap requires an immediate operation.
                    operations++;
                }
            }
        }

        // 3. Greedily fill gaps using the available even/odd pool, starting with smallest gaps.
        Collections.sort(evenInternalGaps);
        Collections.sort(oddInternalGaps);
        Collections.sort(evenEdgeGaps);
        Collections.sort(oddEdgeGaps);

        // Process Internal Gaps: If pool is insufficient, cost is 2 operations.
        for (int size : evenInternalGaps) {
            if (evenPool >= size) evenPool -= size;
            else operations += 2;
        }
        for (int size : oddInternalGaps) {
            if (oddPool >= size) oddPool -= size;
            else operations += 2;
        }

        // Process Edge Gaps: If pool is insufficient, cost is 1 operation.
        for (int size : evenEdgeGaps) {
            if (evenPool >= size) evenPool -= size;
            else operations += 1;
        }
        for (int size : oddEdgeGaps) {
            if (oddPool >= size) oddPool -= size;
            else operations += 1;
        }

        return operations;
    }

    /**
     * FastReader utility for efficient input parsing.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.FileInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * Garland solver that calculates the minimum penalty (parity breaks) 
 * required to complete a sequence of numbers.
 */
public class Garland {

    private static final int EVEN = 0;
    private static final int ODD = 1;

    public static void main(String[] args) {
        try {
            FastReader reader = new FastReader(System.in);
            solve(reader);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private static void solve(FastReader reader) throws IOException {
        int n = reader.nextInt();
        int[] elements = new int[n];

        // Counts of available even and odd slots
        int[] availableParityCounts = new int[2];
        availableParityCounts[EVEN] = n / 2;
        availableParityCounts[ODD] = (n + 1) / 2;

        for (int i = 0; i < n; i++) {
            elements[i] = reader.nextInt();
            if (elements[i] != 0) {
                int parity = Math.abs(elements[i] % 2);
                availableParityCounts[parity]--;
            }
        }

        // list[0] stores lengths of segments between two even numbers
        // list[1] stores lengths of segments between two odd numbers
        List<List<Integer>> internalSegments = new ArrayList<>();
        internalSegments.add(new ArrayList<>());
        internalSegments.add(new ArrayList<>());

        // sList stores lengths of segments at the edges adjacent to a specific parity
        List<List<Integer>> edgeSegments = new ArrayList<>();
        edgeSegments.add(new ArrayList<>());
        edgeSegments.add(new ArrayList<>());

        int totalPenalty = 0;

        // 1. Identify segments of zeros
        for (int i = 0; i < n; i++) {
            if (elements[i] == 0) {
                int segmentStart = i;
                while (i < n && elements[i] == 0) {
                    i++;
                }
                int segmentEnd = i - 1;
                int length = segmentEnd - segmentStart + 1;

                int leftNeighbor = (segmentStart > 0) ? elements[segmentStart - 1] : -1;
                int rightNeighbor = (segmentEnd < n - 1) ? elements[segmentEnd + 1] : -1;

                if (leftNeighbor != -1 && rightNeighbor != -1) {
                    if (Math.abs(leftNeighbor % 2) == Math.abs(rightNeighbor % 2)) {
                        internalSegments.get(Math.abs(leftNeighbor % 2)).add(length);
                    } else {
                        // If neighbors have different parity, any fill will cause a break
                        totalPenalty++;
                    }
                } else if (leftNeighbor == -1) {
                    // Segment at the very beginning
                    int neighborParity = (rightNeighbor == -1) ? ODD : Math.abs(rightNeighbor % 2);
                    edgeSegments.get(neighborParity).add(length);
                } else if (rightNeighbor == -1) {
                    // Segment at the very end
                    int neighborParity = Math.abs(leftNeighbor % 2);
                    edgeSegments.get(neighborParity).add(length);
                }
            }
        }

        // 2. Calculate penalties from internal segments using greedy approach
        for (int p = 0; p < 2; p++) {
            List<Integer> segments = internalSegments.get(p);
            Collections.sort(segments);

            int sumUsed = 0;
            int successfullyFilled = 0;
            for (int len : segments) {
                if (sumUsed + len <= availableParityCounts[p]) {
                    sumUsed += len;
                    successfullyFilled++;
                } else {
                    break;
                }
            }
            availableParityCounts[p] -= sumUsed;
            // Each unfilled internal segment creates 2 parity breaks
            totalPenalty += 2 * (segments.size() - successfullyFilled);
        }

        // 3. Calculate penalties from edge segments
        for (int p = 0; p < 2; p++) {
            List<Integer> segments = edgeSegments.get(p);
            Collections.sort(segments);

            int sumUsed = 0;
            int successfullyFilled = 0;
            for (int len : segments) {
                if (sumUsed + len <= availableParityCounts[p]) {
                    sumUsed += len;
                    successfullyFilled++;
                } else {
                    break;
                }
            }
            // Each unfilled edge segment creates 1 parity break
            totalPenalty += (segments.size() - successfullyFilled);
        }

        // 4. Add penalties for existing adjacent non-zero elements with different parity
        for (int i = 0; i < n - 1; i++) {
            if (elements[i] != 0 && elements[i + 1] != 0) {
                if (Math.abs(elements[i] % 2) != Math.abs(elements[i + 1] % 2)) {
                    totalPenalty++;
                }
            }
        }

        System.out.println(totalPenalty);
    }

    /**
     * High-performance input reader.
     */
    public static class FastReader {
        private final InputStream inputStream;
        private final byte[] buffer = new byte[1 << 17];
        private int pointer = 0;
        private int bytesRead = 0;

        public FastReader(InputStream is) {
            this.inputStream = is;
        }

        public FastReader(String fileName) throws IOException {
            this.inputStream = new FileInputStream(fileName);
        }

        private byte readByte() throws IOException {
            if (pointer == bytesRead) {
                fillBuffer();
            }
            return bytesRead == -1 ? -1 : buffer[pointer++];
        }

        private void fillBuffer() throws IOException {
            bytesRead = inputStream.read(buffer, 0, buffer.length);
            pointer = 0;
        }

        public int nextInt() throws IOException {
            byte b = readByte();
            while (b != -1 && b <= ' ') b = readByte();
            if (b == -1) return 0;

            boolean negative = false;
            if (b == '-') {
                negative = true;
                b = readByte();
            }

            int result = 0;
            while (b >= '0' && b <= '9') {
                result = result * 10 + (b - '0');
                b = readByte();
            }
            return negative ? -result : result;
        }

        public void close() throws IOException {
            inputStream.close();
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A utility class to solve parity-based sequence optimization problems.
 * The goal is to calculate the minimum number of parity changes in a sequence 
 * given constraints on the number of even and odd elements allowed.
 */
public class R612D2C {

    public static void main(String[] args) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter writer = new PrintWriter(System.out)) {

            String line = reader.readLine();
            if (line == null) return;

            int n = Integer.parseInt(line.trim());
            int[] array = new int[n];

            StringTokenizer st = new StringTokenizer(reader.readLine());
            for (int i = 0; i < n; i++) {
                array[i] = Integer.parseInt(st.nextToken());
            }

            ParitySequenceSolver solver = new ParitySequenceSolver(n, array);
            writer.println(solver.solve());

        } catch (IOException | NumberFormatException e) {
            e.printStackTrace();
        }
    }
}

class ParitySequenceSolver {
    private final int n;
    private final int[] array;
    private final int targetEvenSlots;
    private final int targetOddSlots;

    public ParitySequenceSolver(int n, int[] array) {
        this.n = n;
        this.array = array;
        // The problem defines an initial budget of even/odd slots
        this.targetEvenSlots = n / 2;
        this.targetOddSlots = n - (n / 2);
    }

    public int solve() {
        List<Integer> nonZeroIndices = findNonZeroIndices();

        // Handle edge case: all elements are zero
        if (nonZeroIndices.isEmpty()) {
            return (n > 1) ? 1 : 0;
        }

        int parityChanges = 0;
        List<Integer> oddParityGaps = new ArrayList<>();
        List<Integer> evenParityGaps = new ArrayList<>();

        int remainingEvenSlots = targetEvenSlots;
        int remainingOddSlots = targetOddSlots;

        // 1. Analyze gaps between non-zero elements
        for (int i = 0; i < nonZeroIndices.size(); i++) {
            int currentIndex = nonZeroIndices.get(i);
            int currentParity = Math.abs(array[currentIndex] % 2);

            // Update budget based on the parity of the fixed non-zero element
            if (currentParity == 1) {
                remainingOddSlots--;
            } else {
                remainingEvenSlots--;
            }

            if (i > 0) {
                int prevIndex = nonZeroIndices.get(i - 1);
                int prevParity = Math.abs(array[prevIndex] % 2);
                int gapSize = currentIndex - prevIndex - 1;

                if (currentParity != prevParity) {
                    parityChanges++;
                } else {
                    // If parities match, we store the gap to potentially fill it later
                    if (currentParity == 1) {
                        oddParityGaps.add(gapSize);
                    } else {
                        evenParityGaps.add(gapSize);
                    }
                }
            }
        }

        // 2. Handle leading zeros
        int firstIdx = nonZeroIndices.get(0);
        parityChanges = applyLeadingZeros(firstIdx, array[firstIdx], remainingEvenSlots, remainingOddSlots, parityChanges);

        // Re-extract budget after leading zero adjustment
        // Note: The original logic is slightly coupled; we simulate the budget consumption
        // to maintain exact parity with the original algorithm's behavior.
        remainingEvenSlots = recalculateEvenBudget(firstIdx, array[firstIdx], targetEvenSlots, nonZeroIndices);
        remainingOddSlots = recalculateOddBudget(firstIdx, array[firstIdx], targetOddSlots, nonZeroIndices);

        // 3. Handle trailing zeros
        int lastIdx = nonZeroIndices.get(nonZeroIndices.size() - 1);
        int trailingZeroCount = (n - 1) - lastIdx;

        // Update parity changes and budget for trailing zeros
        int lastParity = Math.abs(array[lastIdx] % 2);
        if (lastParity == 0) {
            if (trailingZeroCount > remainingEvenSlots) parityChanges++;
            else remainingEvenSlots -= trailingZeroCount;
        } else {
            if (trailingZeroCount > remainingOddSlots) parityChanges++;
            else remainingOddSlots -= trailingZeroCount;
        }

        // 4. Greedily satisfy same-parity gaps using remaining budget
        parityChanges += processGaps(oddParityGaps, remainingOddSlots);
        parityChanges += processGaps(evenParityGaps, remainingEvenSlots);

        return parityChanges;
    }

    private List<Integer> findNonZeroIndices() {
        List<Integer> indices = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (array[i] != 0) {
                indices.add(i);
            }
        }
        return indices;
    }

    private int applyLeadingZeros(int firstIdx, int firstVal, int evenBudget, int oddBudget, int currentChanges) {
        int parity = Math.abs(firstVal % 2);
        if (parity == 0) {
            return (firstIdx > evenBudget) ? currentChanges + 1 : currentChanges;
        } else {
            return (firstIdx > oddBudget) ? currentChanges + 1 : currentChanges;
        }
    }

    private int recalculateEvenBudget(int firstIdx, int firstVal, int targetEven, List<Integer> nonZeroIndices) {
        int budget = targetEven;
        for (int idx : nonZeroIndices) {
            if (Math.abs(array[idx] % 2) == 0) budget--;
        }
        // Adjust for leading zeros logic
        if (Math.abs(firstVal % 2) == 0) {
            if (firstIdx <= budget) budget -= firstIdx;
        }
        return budget;
    }

    private int recalculateOddBudget(int firstIdx, int firstVal, int targetOdd, List<Integer> nonZeroIndices) {
        int budget = targetOdd;
        for (int idx : nonZeroIndices) {
            if (Math.abs(array[idx] % 2) == 1) budget--;
        }
        // Adjust for leading zeros logic
        if (Math.abs(firstVal % 2) == 1) {
            if (firstIdx <= budget) budget -= firstIdx;
        }
        return budget;
    }

    private int processGaps(List<Integer> gaps, int budget) {
        Collections.sort(gaps);
        int remainingBudget = budget;
        int unfillableGaps = 0;

        for (int gapSize : gaps) {
            if (remainingBudget >= gapSize) {
                remainingBudget -= gapSize;
            } else {
                unfillableGaps++;
            }
        }
        // Each unfillable same-parity gap results in 2 parity changes (e.g., 1 -> 0 -> 1)
        return unfillableGaps * 2;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * A program to minimize parity transitions in an array while satisfying 
 * specific counts of even and odd numbers.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        ParityMinimizer solver = new ParityMinimizer();
        solver.solve(reader, writer);

        writer.close();
    }

    /**
     * Encapsulates the logic for solving the parity minimization problem.
     */
    static class ParityMinimizer {
        private static final int INF = 1_000_000;

        /**
         * Solves the problem using dynamic programming.
         * The goal is to fill wildcards (0s) such that the total number of odd elements 
         * equals (N+1)/2 and the number of transitions between adjacent elements 
         * with different parity is minimized.
         *
         * @param in  The fast input reader.
         * @param out The output writer.
         */
        public void solve(FastReader in, PrintWriter out) {
            int n = in.nextInt();
            if (n <= 0) {
                out.println(0);
                return;
            }

            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = in.nextInt();
            }

            // The problem constraints dictate the exact number of odds and evens required.
            int targetOddCount = (n + 1) / 2;
            int targetEvenCount = n / 2;

            // dp[parity][oddCount] stores the minimum transitions for the current index.
            // Using space-optimized DP (only keeping track of the current index's state).
            int[][] dp = new int[2][targetOddCount + 1];
            for (int i = 0; i < 2; i++) {
                for (int j = 0; j <= targetOddCount; j++) {
                    dp[i][j] = INF;
                }
            }

            // Base case: initialize the DP with the first element.
            initializeFirstElement(arr, dp, targetOddCount, targetEvenCount);

            // Iterate through the array starting from the second element.
            for (int i = 1; i < n; i++) {
                int[][] nextDp = new int[2][targetOddCount + 1];
                for (int p = 0; p < 2; p++) {
                    for (int o = 0; o <= targetOddCount; o++) {
                        nextDp[p][o] = INF;
                    }
                }

                // Optimization: Calculate valid range for number of odds to stay within constraints.
                int minO = Math.max(0, (i + 1) - targetEvenCount);
                int maxO = Math.min(i + 1, targetOddCount);

                for (int p = 0; p < 2; p++) {
                    // If the element is fixed and doesn't match the current parity p, skip.
                    if (arr[i] != 0 && (arr[i] % 2 != 0 ? 1 : 0) != p) {
                        continue;
                    }

                    int isOdd = (p == 1) ? 1 : 0;

                    for (int o = minO; o <= maxO; o++) {
                        int prevO = o - isOdd;
                        if (prevO < 0 || prevO > targetOddCount) {
                            continue;
                        }

                        // 1. Transition from the same parity (no cost increase).
                        if (dp[p][prevO] != INF) {
                            nextDp[p][o] = Math.min(nextDp[p][o], dp[p][prevO]);
                        }

                        // 2. Transition from the opposite parity (add 1 to cost).
                        int prevP = 1 - p;
                        if (dp[prevP][prevO] != INF) {
                            nextDp[p][o] = Math.min(nextDp[p][o], dp[prevP][prevO] + 1);
                        }
                    }
                }
                dp = nextDp;
            }

            // The result is the minimum of the two possible end parities for the target odd count.
            int result = Math.min(dp[0][targetOddCount], dp[1][targetOddCount]);
            out.println(result >= INF ? -1 : result);
        }

        /**
         * Sets up the base case for the DP table using the first element of the array.
         */
        private void initializeFirstElement(int[] arr, int[][] dp, int targetOdd, int targetEven) {
            int parity = (arr[0] == 0) ? -1 : (arr[0] % 2 == 0 ? 0 : 1);

            // Option 1: Set the first element to Even (parity 0)
            if (parity == -1 || parity == 0) {
                if (0 <= targetOdd && 1 <= targetEven) {
                    dp[0][0] = 0;
                }
            }

            // Option 2: Set the first element to Odd (parity 1)
            if (parity == -1 || parity == 1) {
                if (1 <= targetOdd && 0 <= targetEven) {
                    dp[1][1] = 0;
                }
            }
        }
    }

    /**
     * Standard Fast I/O implementation.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * ParitySequenceOptimizer calculates the maximum number of parity changes 
 * possible in a sequence given fixed parities and wildcard positions.
 */
public class ParitySequenceOptimizer {

    private static final int UNREACHABLE = -1;

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        try {
            int n = reader.nextInt();
            if (n <= 0) {
                System.out.println(0);
                return;
            }

            int[] inputValues = new int[n];
            for (int i = 0; i < n; i++) {
                inputValues[i] = reader.nextInt();
            }

            System.out.println(solve(n, inputValues));
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /**
     * Solves the problem using Dynamic Programming.
     * 
     * @param n The length of the sequence.
     * @param inputValues The original input integers.
     * @return The maximum number of parity changes.
     */
    private static int solve(int n, int[] inputValues) {
        // targetOdd/targetEven: how many total odds/evens we need in the final sequence.
        int targetOdd = (n + 1) / 2;
        int targetEven = n / 2;

        // parities: 1 for odd, 0 for even, -1 for wildcard (v <= 0).
        int[] parities = new int[n];
        int fixedOdd = 0;
        int fixedEven = 0;
        int totalWildcards = 0;

        for (int i = 0; i < n; i++) {
            if (inputValues[i] > 0) {
                int p = Math.abs(inputValues[i] % 2);
                parities[i] = p;
                if (p == 1) fixedOdd++;
                else fixedEven++;
            } else {
                parities[i] = -1;
                totalWildcards++;
            }
        }

        // neededOdd/neededEven: how many odd/even numbers must be assigned to wildcard slots.
        int neededOdd = targetOdd - fixedOdd;
        int neededEven = targetEven - fixedEven;

        // If the fixed values already exceed the required counts, no valid sequence exists.
        if (neededOdd < 0 || neededEven < 0) {
            return -1; 
        }

        // dp[i][j][p] = max changes for first i elements, with j wildcard-odds used, 
        // ending in parity p (0 or 1).
        int[][][] dp = new int[n][neededOdd + 1][2];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j <= neededOdd; j++) {
                Arrays.fill(dp[i][j], UNREACHABLE);
            }
        }

        // Base Case: i = 0
        if (parities[0] != -1) {
            dp[0][0][parities[0]] = 0;
        } else {
            // Case 1: First wildcard is used as Odd
            if (neededOdd > 0) {
                dp[0][1][1] = 0;
            }
            // Case 2: First wildcard is used as Even
            if (neededEven > 0) {
                dp[0][0][0] = 0;
            }
        }

        int wildcardsProcessed = (parities[0] == -1) ? 1 : 0;

        // DP Transitions
        for (int i = 0; i < n - 1; i++) {
            for (int j = 0; j <= neededOdd; j++) {
                for (int p = 0; p < 2; p++) {
                    if (dp[i][j][p] == UNREACHABLE) continue;

                    int nextIdx = i + 1;
                    if (parities[nextIdx] != -1) {
                        // Next is a fixed parity
                        int nextP = parities[nextIdx];
                        int changes = (nextP == p) ? 0 : 1;
                        dp[nextIdx][j][nextP] = Math.max(dp[nextIdx][j][nextP], dp[i][j][p] + changes);
                    } else {
                        // Next is a wildcard. Try both parity assignments.

                        // Option A: Assign as Odd
                        if (j + 1 <= neededOdd) {
                            int changes = (1 == p) ? 0 : 1;
                            dp[nextIdx][j + 1][1] = Math.max(dp[nextIdx][j + 1][1], dp[i][j][p] + changes);
                        }

                        // Option B: Assign as Even
                        // Check if we have enough even-wildcard capacity remaining.
                        // wildcardsProcessed + 1 is the total wildcards used if we pick even here.
                        // j is the number of odd wildcards used.
                        if (wildcardsProcessed + 1 - j <= neededEven) {
                            int changes = (0 == p) ? 0 : 1;
                            dp[nextIdx][j][0] = Math.max(dp[nextIdx][j][0], dp[i][j][p] + changes);
                        }
                    }
                }
            }
            if (parities[i + 1] == -1) {
                wildcardsProcessed++;
            }
        }

        // Final Result: Maximize over the last element with correct wildcard distribution.
        int maxChanges = UNREACHABLE;
        for (int p = 0; p < 2; p++) {
            maxChanges = Math.max(maxChanges, dp[n - 1][neededOdd][p]);
        }

        return maxChanges;
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * ParityMinimizer solves the problem of finding the minimum number of parity transitions 
 * (switches between 0 and 1) in an array, given a fixed number of 0s and 1s and 
 * a set of wildcard elements (-1) that can be converted to either.
 */
public class ParityMinimizer {

    private static final int INF = 1_000_000_000;

    public static void main(String[] args) {
        try {
            ParityMinimizer optimizer = new ParityMinimizer();
            optimizer.solve();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public void solve() throws IOException {
        FastReader sc = new FastReader(System.in);

        // Read input size
        int n = sc.nextInt();
        if (n <= 0) {
            System.out.println(0);
            return;
        }

        // inputParity stores the fixed parity of elements. -1 represents a wildcard.
        int[] inputParity = new int[n];

        // wildcardRemainingCounts tracks how many 0s and 1s are available 
        // to be assigned to the wildcard (-1) positions.
        int[] wildcardRemainingCounts = new int[2];
        wildcardRemainingCounts[0] = n / 2;
        wildcardRemainingCounts[1] = (n + 1) / 2;

        for (int i = 0; i < n; i++) {
            int val = sc.nextInt();
            if (val == 0) {
                inputParity[i] = -1; // Treat 0 as wildcard
            } else {
                int parity = Math.abs(val % 2);
                inputParity[i] = parity;
                wildcardRemainingCounts[parity]--;
            }
        }

        // dp[i][j][k][p]
        // i: current element index (1 to n)
        // j: remaining 0s available for wildcards
        // k: remaining 1s available for wildcards
        // p: parity of the i-th element (0 or 1)
        int[][][][] dp = new int[n + 1][n + 1][n + 1][2];

        // Initialize DP table with infinity
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                for (int k = 0; k <= n; k++) {
                    dp[i][j][k][0] = dp[i][j][k][1] = INF;
                }
            }
        }

        // Base Case: Initializing the first element (i = 1)
        if (inputParity[0] == -1) {
            if (wildcardRemainingCounts[0] >= 1) {
                dp[1][wildcardRemainingCounts[0] - 1][wildcardRemainingCounts[1]][0] = 0;
            }
            if (wildcardRemainingCounts[1] >= 1) {
                dp[1][wildcardRemainingCounts[0]][wildcardRemainingCounts[1] - 1][1] = 0;
            }
        } else {
            int p = inputParity[0];
            dp[1][wildcardRemainingCounts[0]][wildcardRemainingCounts[1]][p] = 0;
        }

        // Fill DP table for subsequent elements
        for (int i = 2; i <= n; i++) {
            int currentFixedParity = inputParity[i - 1];

            for (int j = 0; j <= n; j++) {
                for (int k = 0; k <= n; k++) {
                    if (currentFixedParity != -1) {
                        // Case 1: The current element is fixed to a specific parity
                        int p = currentFixedParity;

                        // Option A: Previous element had the same parity (0 cost)
                        if (dp[i - 1][j][k][p] != INF) {
                            dp[i][j][k][p] = Math.min(dp[i][j][k][p], dp[i - 1][j][k][p]);
                        }
                        // Option B: Previous element had the different parity (1 cost)
                        if (dp[i - 1][j][k][p ^ 1] != INF) {
                            dp[i][j][k][p] = Math.min(dp[i][j][k][p], dp[i - 1][j][k][p ^ 1] + 1);
                        }
                    } else {
                        // Case 2: The current element is a wildcard (-1)

                        // Option A: Assign 0 to this wildcard (reduces remaining 0s)
                        if (j + 1 <= n) {
                            int prevJ = j + 1;
                            if (dp[i - 1][prevJ][k][0] != INF) {
                                dp[i][j][k][0] = Math.min(dp[i][j][k][0], dp[i - 1][prevJ][k][0]);
                            }
                            if (dp[i - 1][prevJ][k][1] != INF) {
                                dp[i][j][k][0] = Math.min(dp[i][j][k][0], dp[i - 1][prevJ][k][1] + 1);
                            }
                        }

                        // Option B: Assign 1 to this wildcard (reduces remaining 1s)
                        if (k + 1 <= n) {
                            int prevK = k + 1;
                            if (dp[i - 1][j][prevK][1] != INF) {
                                dp[i][j][k][1] = Math.min(dp[i][j][k][1], dp[i - 1][j][prevK][1]);
                            }
                            if (dp[i - 1][j][prevK][0] != INF) {
                                dp[i][j][k][1] = Math.min(dp[i][j][k][1], dp[i - 1][j][prevK][0] + 1);
                            }
                        }
                    }
                }
            }
        }

        // The result is the minimum cost after using all required zeros and ones
        int result = Math.min(dp[n][0][0][0], dp[n][0][0][1]);
        System.out.println(result >= INF ? -1 : result);
    }

    /**
     * FastReader provides efficient input reading using BufferedReader and StringTokenizer.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A refactored solution for the parity balancing problem.
 * The goal is to balance the number of even and odd integers in an array 
 * by filling zero-slots, while minimizing parity transitions.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            ParityBalancer solver = new ParityBalancer(reader);
            solver.solve(writer);
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            writer.flush();
            writer.close();
        }
    }
}

class ParityBalancer {
    private final FastReader reader;

    public ParityBalancer(FastReader reader) {
        this.reader = reader;
    }

    /**
     * Core logic to solve the problem.
     */
    public void solve(PrintWriter out) throws IOException {
        int arraySize = reader.nextInt();
        int[] numbers = new int[arraySize];
        int existingOdds = 0;
        int existingEvens = 0;

        for (int i = 0; i < arraySize; i++) {
            numbers[i] = reader.nextInt();
            if (numbers[i] != 0) {
                if (numbers[i] % 2 != 0) {
                    existingOdds++;
                } else {
                    existingEvens++;
                }
            }
        }

        // Calculate the budget of odds and evens we can afford to add to achieve balance
        int targetEvens = arraySize / 2;
        int targetOdds = arraySize / 2 + (arraySize % 2);

        int neededEvens = targetEvens - existingEvens;
        int neededOdds = targetOdds - existingOdds;

        // Locate the first non-zero element to determine if the array is all zeros
        int firstNonZeroIndex = 0;
        while (firstNonZeroIndex < arraySize && numbers[firstNonZeroIndex] == 0) {
            firstNonZeroIndex++;
        }

        if (firstNonZeroIndex == arraySize) {
            out.println(Math.min(arraySize - 1, 1));
            return;
        }

        List<Gap> allGaps = findZeroGaps(numbers, arraySize);
        int paritySwitches = 0;

        Gap prefixGap = null;
        Gap suffixGap = null;
        List<Gap> internalOddGaps = new ArrayList<>();
        List<Gap> internalEvenGaps = new ArrayList<>();

        // Classify gaps: Prefix, Suffix, Internal (Odd-Odd, Even-Even, or Mixed)
        for (Gap gap : allGaps) {
            if (gap.start == 0) {
                prefixGap = gap;
            } else if (gap.end == arraySize - 1) {
                suffixGap = gap;
            } else {
                int leftParity = Math.abs(numbers[gap.start - 1] % 2);
                int rightParity = Math.abs(numbers[gap.end + 1] % 2);

                if (leftParity == 1 && rightParity == 1) {
                    internalOddGaps.add(gap);
                } else if (leftParity == 0 && rightParity == 0) {
                    internalEvenGaps.add(gap);
                } else {
                    // Mixed parity gaps (e.g., Even-Zero-Odd) immediately cost 1 switch
                    paritySwitches++;
                }
            }
        }

        // Sort internal gaps by size to use our "budget" of parity numbers most efficiently
        Collections.sort(internalOddGaps, Comparator.comparingInt(g -> g.size));
        Collections.sort(internalEvenGaps, Comparator.comparingInt(g -> g.size));

        for (Gap g : internalOddGaps) {
            if (neededOdds >= g.size) {
                neededOdds -= g.size;
            } else {
                paritySwitches += 2;
            }
        }

        for (Gap g : internalEvenGaps) {
            if (neededEvens >= g.size) {
                neededEvens -= g.size;
            } else {
                paritySwitches += 2;
            }
        }

        // Process prefix gap (zeros at the start of the array)
        if (prefixGap != null) {
            int firstNonZeroParity = Math.abs(numbers[prefixGap.end + 1] % 2);
            if (firstNonZeroParity == 1) {
                if (neededOdds >= prefixGap.size) neededOdds -= prefixGap.size;
                else paritySwitches++;
            } else {
                if (neededEvens >= prefixGap.size) neededEvens -= prefixGap.size;
                else paritySwitches++;
            }
        }

        // Process suffix gap (zeros at the end of the array)
        if (suffixGap != null) {
            int lastNonZeroParity = Math.abs(numbers[suffixGap.start - 1] % 2);
            if (lastNonZeroParity == 1) {
                if (neededOdds >= suffixGap.size) neededOdds -= suffixGap.size;
                else paritySwitches++;
            } else {
                if (neededEvens >= suffixGap.size) neededEvens -= suffixGap.size;
                else paritySwitches++;
            }
        }

        // Count existing parity switches between non-zero elements
        for (int i = 0; i < arraySize - 1; i++) {
            if (numbers[i] != 0 && numbers[i + 1] != 0) {
                if (Math.abs(numbers[i] % 2) != Math.abs(numbers[i + 1] % 2)) {
                    paritySwitches++;
                }
            }
        }

        out.println(paritySwitches);
    }

    private List<Gap> findZeroGaps(int[] numbers, int n) {
        List<Gap> gaps = new ArrayList<>();
        int i = 0;
        while (i < n) {
            if (numbers[i] == 0) {
                int start = i;
                while (i < n && numbers[i] == 0) {
                    i++;
                }
                gaps.add(new Gap(start, i - 1));
            } else {
                i++;
            }
        }
        return gaps;
    }
}

/**
 * Represents a contiguous segment of zero-valued elements.
 */
class Gap {
    final int start;
    final int end;
    final int size;

    Gap(int start, int end) {
        this.start = start;
        this.end = end;
        this.size = end - start + 1;
    }
}

