import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * A program to find the minimum number of transitions between even and odd numbers
 * in a sequence, where some elements (zeros) can be replaced by either an even or an odd number.
 */
public class Main {

    public static void main(String[] args) {
        // Use a separate thread with a larger stack size to prevent StackOverflowError 
        // during deep recursion in the Dynamic Programming process.
        Thread solverThread = new Thread(null, () -> {
            try {
                new SequenceSolver().solve();
            } catch (Exception e) {
                e.printStackTrace();
            }
        }, "SolverThread", 1 << 26);

        solverThread.start();
    }

    /**
     * Represents the type of element at a specific index in the sequence.
     */
    enum ElementType {
        ZERO,
        ODD,
        EVEN,
        NONE // Used for the initial state before any element is placed
    }

    /**
     * Handles the core logic of the problem, including input processing and DP.
     */
    static class SequenceSolver {
        private int totalElements;
        private ElementType[] elementTypes;
        private int[] zerosRemaining;
        private int targetEvenZeros;
        private int[][][] memo;

        public void solve() {
            FastReader fr = new FastReader();
            PrintWriter out = new PrintWriter(System.out);

            String firstToken = fr.next();
            if (firstToken == null) return;

            totalElements = Integer.parseInt(firstToken);

            if (totalElements == 1) {
                out.println("0");
                out.close();
                return;
            }

            elementTypes = new ElementType[totalElements];
            int totalEvensNeeded = totalElements / 2;
            int totalOddsNeeded = (int) Math.ceil(totalElements / 2.0);

            int fixedEvens = 0;
            int fixedOdds = 0;

            for (int i = 0; i < totalElements; i++) {
                int val = fr.nextInt();
                if (val == 0) {
                    elementTypes[i] = ElementType.ZERO;
                } else if (val % 2 == 0) {
                    elementTypes[i] = ElementType.EVEN;
                    fixedEvens++;
                } else {
                    elementTypes[i] = ElementType.ODD;
                    fixedOdds++;
                }
            }

            // Calculate how many zeros must be turned into even numbers to meet the target.
            targetEvenZeros = totalEvensNeeded - fixedEvens;

            // Pre-calculate how many zero-type elements remain from each index to the end.
            zerosRemaining = new int[totalElements + 1];
            for (int i = totalElements - 1; i >= 0; i--) {
                zerosRemaining[i] = zerosRemaining[i + 1] + (elementTypes[i] == ElementType.ZERO ? 1 : 0);
            }

            // Memoization table: [index][remainingEvenZeros][previousElementType]
            // previousElementType mapping: 0: NONE, 1: ODD, 2: EVEN
            memo = new int[totalElements][targetEvenZeros + 1][3];
            for (int i = 0; i < totalElements; i++) {
                for (int j = 0; j <= targetEvenZeros; j++) {
                    for (int k = 0; k < 3; k++) {
                        memo[i][j][k] = -1;
                    }
                }
            }

            out.println(calculateMinSwitches(0, targetEvenZeros, ElementType.NONE));
            out.close();
        }

        /**
         * Recursive DP function with memoization to find the minimum number of switches.
         *
         * @param idx              Current index in the sequence.
         * @param remEvenZeros     Number of even numbers still needed to be placed in zero slots.
         * @param lastType         The type of the previously placed number.
         * @return                 The minimum switches from this state to the end.
         */
        private int calculateMinSwitches(int idx, int remEvenZeros, ElementType lastType) {
            if (idx == totalElements) {
                return 0;
            }

            int lastTypeIdx = lastType.ordinal();
            if (memo[idx][remEvenZeros][lastTypeIdx] != -1) {
                return memo[idx][remEvenZeros][lastTypeIdx];
            }

            int result = Integer.MAX_VALUE / 2; // Use a large value to avoid overflow during addition

            if (elementTypes[idx] == ElementType.ZERO) {
                int remOddZeros = zerosRemaining[idx] - remEvenZeros;

                // Option 1: Place an EVEN number in this zero slot
                if (remEvenZeros > 0) {
                    int switchCost = (lastType == ElementType.ODD) ? 1 : 0;
                    result = Math.min(result, calculateMinSwitches(idx + 1, remEvenZeros - 1, ElementType.EVEN) + switchCost);
                }

                // Option 2: Place an ODD number in this zero slot
                if (remOddZeros > 0) {
                    int switchCost = (lastType == ElementType.EVEN) ? 1 : 0;
                    result = Math.min(result, calculateMinSwitches(idx + 1, remEvenZeros, ElementType.ODD) + switchCost);
                }
            } else {
                // The element is fixed as EVEN or ODD
                ElementType currentType = elementTypes[idx];
                int switchCost = 0;
                if (lastType == ElementType.ODD && currentType == ElementType.EVEN) {
                    switchCost = 1;
                } else if (lastType == ElementType.EVEN && currentType == ElementType.ODD) {
                    switchCost = 1;
                }
                result = calculateMinSwitches(idx + 1, remEvenZeros, currentType) + switchCost;
            }

            memo[idx][remEvenZeros][lastTypeIdx] = result;
            return result;
        }
    }

    /**
     * Utility class for fast input reading.
     */
    static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solution class serves as the entry point for the program.
 */
public class Solution {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        // Read input n
        int n = reader.nextInt();
        if (n <= 0) {
            System.out.println(0);
            return;
        }

        // Read the sequence array
        int[] sequence = reader.readArray(n);

        // Solve the problem using the ProblemSolver logic
        ProblemSolver solver = new ProblemSolver(n, sequence);
        System.out.println(solver.solve());
    }

    /**
     * ProblemSolver encapsulates the core logic of the algorithm.
     */
    static class ProblemSolver {
        private final int n;
        private final int[] sequence;

        private int neededEvenCount;
        private int neededOddCount;
        private int mismatchCount = 0;

        private final List<Integer> internalBlocksEven = new ArrayList<>();
        private final List<Integer> internalBlocksOdd = new ArrayList<>();
        private final List<Integer> edgeBlocksEven = new ArrayList<>();
        private final List<Integer> edgeBlocksOdd = new ArrayList<>();

        public ProblemSolver(int n, int[] sequence) {
            this.n = n;
            this.sequence = sequence;
            initializeCounts();
        }

        private void initializeCounts() {
            // Initial available even and odd numbers in a range 1..n
            this.neededEvenCount = n / 2;
            this.neededOddCount = (n + 1) / 2;

            // Subtract counts of numbers already present in the sequence
            for (int val : sequence) {
                if (val != 0) {
                    if (val % 2 == 0) {
                        neededEvenCount--;
                    } else {
                        neededOddCount--;
                    }
                }
            }
        }

        public int solve() {
            findZeroSegments();
            processInternalBlocks();
            processEdgeBlocks();
            countExistingParityMismatches();
            return mismatchCount;
        }

        /**
         * Identifies contiguous blocks of zeros and categorizes them.
         */
        private void findZeroSegments() {
            for (int i = 0; i < n; i++) {
                if (sequence[i] == 0) {
                    int start = i;
                    while (i < n - 1 && sequence[i + 1] == 0) {
                        i++;
                    }
                    int end = i;
                    int length = end - start + 1;

                    int leftNeighbor = (start > 0) ? sequence[start - 1] : -1;
                    int rightNeighbor = (end < n - 1) ? sequence[end + 1] : -1;

                    classifySegment(length, leftNeighbor, rightNeighbor);
                }
            }
        }

        private void classifySegment(int length, int left, int right) {
            if (left != -1 && right != -1) {
                // Segment is between two non-zero numbers
                if (left % 2 == right % 2) {
                    // If both neighbors have the same parity, add to that parity's list
                    if (left % 2 == 0) {
                        internalBlocksEven.add(length);
                    } else {
                        internalBlocksOdd.add(length);
                    }
                } else {
                    // If neighbors have different parity, it's a direct mismatch
                    mismatchCount++;
                }
            } else if (left == -1) {
                // Segment is at the start
                if (right != -1) {
                    addBlockToEdgeList(length, right);
                } else {
                    // Special case: entire array is zero (handled by original logic via left==-1)
                    edgeBlocksOdd.add(length); 
                }
            } else if (right == -1) {
                // Segment is at the end
                addBlockToEdgeList(length, left);
            }
        }

        private void addBlockToEdgeList(int length, int neighbor) {
            if (neighbor % 2 == 0) {
                edgeBlocksEven.add(length);
            } else {
                edgeBlocksOdd.add(length);
            }
        }

        private void processInternalBlocks() {
            // Process Even Internal Blocks
            int sumEven = 0;
            int takenEven = 0;
            Collections.sort(internalBlocksEven);
            for (int len : internalBlocksEven) {
                if (sumEven + len <= neededEvenCount) {
                    sumEven += len;
                    takenEven++;
                } else {
                    break;
                }
            }
            neededEvenCount -= sumEven;
            mismatchCount += 2 * (internalBlocksEven.size() - takenEven);

            // Process Odd Internal Blocks
            int sumOdd = 0;
            int takenOdd = 0;
            Collections.sort(internalBlocksOdd);
            for (int len : internalBlocksOdd) {
                if (sumOdd + len <= neededOddCount) {
                    sumOdd += len;
                    takenOdd++;
                } else {
                    break;
                }
            }
            neededOddCount -= sumOdd;
            mismatchCount += 2 * (internalBlocksOdd.size() - takenOdd);
        }

        private void processEdgeBlocks() {
            // Edge blocks incur a penalty of 1 if they cannot be accommodated
            mismatchCount += calculateEdgePenalty(edgeBlocksEven, neededEvenCount);
            mismatchCount += calculateEdgePenalty(edgeBlocksOdd, neededOddCount);
        }

        private int calculateEdgePenalty(List<Integer> blocks, int available) {
            Collections.sort(blocks);
            int sum = 0;
            int taken = 0;
            for (int len : blocks) {
                if (sum + len <= available) {
                    sum += len;
                    taken++;
                } else {
                    break;
                }
            }
            return blocks.size() - taken;
        }

        private void countExistingParityMismatches() {
            for (int i = 0; i < n - 1; i++) {
                if (sequence[i] != 0 && sequence[i + 1] != 0) {
                    if (sequence[i] % 2 != sequence[i + 1] % 2) {
                        mismatchCount++;
                    }
                }
            }
        }
    }

    /**
     * FastReader provides efficient parsing of input streams.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public int[] readArray(int n) {
            int[] array = new int[n];
            for (int i = 0; i < n; i++) {
                array[i] = nextInt();
            }
            return array;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver for determining the minimum/maximum parity transitions in a sequence 
 * containing wildcards (zeros). The algorithm uses a greedy approach to fill 
 * wildcard intervals to maintain parity continuity.
 */
public class ParitySequenceSolver {

    private static final int WILDCARD = -1;

    /**
     * Represents a contiguous block of wildcard (0) values within the sequence.
     */
    private static final class Interval implements Comparable<Interval> {
        final int start;
        final int end;
        final int length;

        Interval(int start, int end) {
            this.start = start;
            this.end = end;
            this.length = end - start;
        }

        @Override
        public int compareTo(Interval other) {
            return Integer.compare(this.length, other.length);
        }
    }

    public static void main(String[] args) {
        try {
            new ParitySequenceSolver().run();
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Entry point for the solver logic.
     */
    public void run() throws IOException {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        int totalElements = reader.nextInt();

        // Edge case: A single element cannot have transitions.
        if (totalElements == 1) {
            writer.println(0);
            writer.close();
            return;
        }

        int[] parities = new int[totalElements];
        // availableParityCounts tracks how many 0s and 1s we can afford to use 
        // based on a balanced parity requirement.
        int[] availableParityCounts = {totalElements / 2, (totalElements + 1) / 2};
        List<Interval> intervals = new ArrayList<>();

        int currentStreakStart = -1;
        int transitionCount = 0;

        // Phase 1: Parse input and identify initial transitions and wildcard intervals.
        for (int i = 0; i < totalElements; i++) {
            int value = reader.nextInt();
            if (value == 0) {
                parities[i] = WILDCARD;
                if (currentStreakStart == -1) {
                    currentStreakStart = i;
                }
            } else {
                parities[i] = value % 2;
                availableParityCounts[parities[i]]--;

                // If we were tracking a streak of wildcards, close that interval.
                if (currentStreakStart != -1) {
                    intervals.add(new Interval(currentStreakStart, i));
                    currentStreakStart = -1;
                }

                // Count transitions between fixed parity values.
                if (i > 0 && parities[i - 1] != WILDCARD && parities[i] != parities[i - 1]) {
                    transitionCount++;
                }
            }
        }

        // Close any trailing wildcard streak.
        if (currentStreakStart != -1) {
            intervals.add(new Interval(currentStreakStart, totalElements));
        }

        // Phase 2: Greedy Filling.
        // Sort intervals by length so we attempt to fill smaller gaps first.
        Collections.sort(intervals);

        // Try to fill intervals in the middle (surrounded by existing numbers).
        fillMatchingIntervals(intervals, availableParityCounts, parities, totalElements);

        // Try to fill intervals at the boundaries.
        fillEdgeIntervals(intervals, availableParityCounts, parities, totalElements);

        // Phase 3: Calculate final transitions for remaining unfilled intervals.
        for (Interval interval : intervals) {
            int requiredParity = getRequiredParity(interval, parities, totalElements);
            if (requiredParity != WILDCARD && isMiddleInterval(interval, totalElements)) {
                // If neighbors are the same but we couldn't fill the gap, we add two transitions.
                transitionCount += 2;
            } else {
                // If neighbors are different or it's an edge, we add one transition.
                transitionCount++;
            }
        }

        writer.println(transitionCount);
        writer.close();
    }

    private void fillMatchingIntervals(List<Interval> intervals, int[] counts, int[] parities, int n) {
        Iterator<Interval> it = intervals.iterator();
        while (it.hasNext()) {
            Interval interval = it.next();
            int requiredParity = getRequiredParity(interval, parities, n);

            if (requiredParity != WILDCARD && isMiddleInterval(interval, n)) {
                if (interval.length <= counts[requiredParity]) {
                    counts[requiredParity] -= interval.length;
                    it.remove();
                }
            }
        }
    }

    private void fillEdgeIntervals(List<Interval> intervals, int[] counts, int[] parities, int n) {
        Iterator<Interval> it = intervals.iterator();
        while (it.hasNext()) {
            Interval interval = it.next();
            int requiredParity = getRequiredParity(interval, parities, n);

            if (requiredParity != WILDCARD && isEdgeInterval(interval, n)) {
                if (interval.length <= counts[requiredParity]) {
                    counts[requiredParity] -= interval.length;
                    it.remove();
                }
            }
        }
    }

    private boolean isMiddleInterval(Interval interval, int n) {
        return interval.start != 0 && interval.end != n;
    }

    private boolean isEdgeInterval(Interval interval, int n) {
        return interval.start == 0 || interval.end == n;
    }

    /**
     * Determines which parity an interval should adopt to match its neighbors.
     * Returns WILDCARD if no single parity can satisfy the neighbors.
     */
    private int getRequiredParity(Interval interval, int[] parities, int n) {
        if (interval.start == 0 && interval.end == n) {
            return WILDCARD;
        } else if (interval.start == 0) {
            // Boundary: Match the parity of the element following the gap.
            return parities[interval.end];
        } else if (interval.end == n) {
            // Boundary: Match the parity of the element preceding the gap.
            return parities[interval.start - 1];
        } else {
            // Middle: Only return a parity if both neighbors are the same.
            int leftNeighbor = parities[interval.start - 1];
            int rightNeighbor = parities[interval.end];
            if (leftNeighbor != WILDCARD && leftNeighbor == rightNeighbor) {
                return leftNeighbor;
            }
            return WILDCARD;
        }
    }

    /**
     * Optimized reader for fast input processing.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream is) {
            this.reader = new BufferedReader(new InputStreamReader(is));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * ParityMinimizer solves the problem of finding the minimum number of parity switches
 * (even to odd or odd to even) in a sequence of numbers from 1 to N, where some 
 * positions in the sequence are pre-filled.
 */
public class ParityMinimizer {

    private static final int PARITY_NONE = 0;
    private static final int PARITY_EVEN = 1;
    private static final int PARITY_ODD = 2;
    private static final int INF = Integer.MAX_VALUE;

    private final int n;
    private final int[] sequenceParity;
    private final int[][][][] memo;

    public ParityMinimizer(int n, int[] inputSequence) {
        this.n = n;
        this.sequenceParity = new int[n];
        this.memo = new int[n + 1][3][n + 1][n + 1];

        initializeSequence(inputSequence);
        initializeMemo();
    }

    /**
     * Translates the input sequence into parities.
     * 0 represents a placeholder, 1 represents even, 2 represents odd.
     */
    private void initializeSequence(int[] input) {
        boolean[] isPresent = new boolean[n + 1];
        for (int i = 0; i < n; i++) {
            int val = input[i];
            if (val != 0) {
                sequenceParity[i] = (val % 2 == 0) ? PARITY_EVEN : PARITY_ODD;
                isPresent[val] = true;
            }
        }

        // Note: The original logic counted missing numbers from 1 to N.
        // We don't actually need the 'isPresent' array here, but we need 
        // the count of remaining evens and odds to pass to the DP.
    }

    private void initializeMemo() {
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j < 3; j++) {
                for (int k = 0; k <= n; k++) {
                    Arrays.fill(memo[i][j][k], -1);
                }
            }
        }
    }

    /**
     * Calculates the minimum parity switches using top-down dynamic programming.
     *
     * @param index          Current index in the sequence
     * @param prevParity     Parity of the previous element (0: none, 1: even, 2: odd)
     * @param evenRemaining  Count of even numbers still available to be placed
     * @param oddRemaining   Count of odd numbers still available to be placed
     * @return Minimum switches from this state to the end
     */
    public int solve(int index, int prevParity, int evenRemaining, int oddRemaining) {
        // Base case: reached the end of the sequence
        if (index == n) {
            return (evenRemaining == 0 && oddRemaining == 0) ? 0 : INF;
        }

        // Memoization lookup
        if (memo[index][prevParity][evenRemaining][oddRemaining] != -1) {
            return memo[index][prevParity][evenRemaining][oddRemaining];
        }

        int result = INF;

        if (sequenceParity[index] == 0) {
            // Scenario 1: Current position is a placeholder. Try placing Even or Odd.

            // Try placing Even
            if (evenRemaining > 0) {
                int res = solve(index + 1, PARITY_EVEN, evenRemaining - 1, oddRemaining);
                if (res != INF) {
                    int cost = res + (prevParity != 0 && prevParity != PARITY_EVEN ? 1 : 0);
                    result = Math.min(result, cost);
                }
            }

            // Try placing Odd
            if (oddRemaining > 0) {
                int res = solve(index + 1, PARITY_ODD, evenRemaining, oddRemaining - 1);
                if (res != INF) {
                    int cost = res + (prevParity != 0 && prevParity != PARITY_ODD ? 1 : 0);
                    result = Math.min(result, cost);
                }
            }
        } else {
            // Scenario 2: Current position is fixed.
            int currentParity = sequenceParity[index];
            int res = solve(index + 1, currentParity, evenRemaining, oddRemaining);
            if (res != INF) {
                result = res + (prevParity != 0 && prevParity != currentParity ? 1 : 0);
            }
        }

        return memo[index][prevParity][evenRemaining][oddRemaining] = result;
    }

    public static void main(String[] args) throws IOException {
        FastReader sc = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = sc.nextInt();
        int[] input = new int[n];
        boolean[] presentInInput = new boolean[n + 1];

        for (int i = 0; i < n; i++) {
            input[i] = sc.nextInt();
            if (input[i] != 0) {
                presentInInput[input[i]] = true;
            }
        }

        // Calculate how many even and odd numbers are available to fill placeholders
        int availableEvens = 0;
        int availableOdds = 0;
        for (int i = 1; i <= n; i++) {
            if (!presentInInput[i]) {
                if (i % 2 == 0) availableEvens++;
                else availableOdds++;
            }
        }

        ParityMinimizer solver = new ParityMinimizer(n, input);
        int minSwitches = solver.solve(0, PARITY_NONE, availableEvens, availableOdds);

        out.println(minSwitches);
        out.flush();
        out.close();
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A solution to find the minimum number of parity switches in an array
 * when filling zero-valued slots with missing numbers from 1 to n.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        solve(reader, writer);

        writer.flush();
        writer.close();
    }

    private static void solve(FastReader reader, PrintWriter writer) {
        int n = reader.nextInt();
        if (n <= 0) {
            writer.println(0);
            return;
        }

        int[] elements = new int[n];
        boolean[] isNumberUsed = new boolean[n + 1];

        for (int i = 0; i < n; i++) {
            elements[i] = reader.nextInt();
            if (elements[i] != 0) {
                isNumberUsed[elements[i]] = true;
            }
        }

        int oddAvailable = 0;
        int evenAvailable = 0;
        for (int i = 1; i <= n; i++) {
            if (!isNumberUsed[i]) {
                if (i % 2 != 0) {
                    oddAvailable++;
                } else {
                    evenAvailable++;
                }
            }
        }

        // Pre-calculate how many zeros are left from each index to the end
        int[] zerosRemaining = new int[n];
        int currentZeros = 0;
        for (int i = n - 1; i >= 0; i--) {
            if (elements[i] == 0) {
                currentZeros++;
            }
            zerosRemaining[i] = currentZeros;
        }

        // memo[index][remainingOddCount][lastParity]
        // lastParity: 0 for even, 1 for odd
        int[][][] memo = new int[n][oddAvailable + 1][2];
        for (int[][] layer : memo) {
            for (int[] row : layer) {
                Arrays.fill(row, -1);
            }
        }

        if (elements[0] != 0) {
            // If the first element is fixed, start DP from index 1
            writer.println(calculateMinSwitches(1, oddAvailable, elements[0] % 2, elements, zerosRemaining, memo));
        } else {
            int minSwitches = Integer.MAX_VALUE;

            // Option 1: Fill the first element with an odd number
            if (oddAvailable > 0) {
                minSwitches = Math.min(minSwitches, calculateMinSwitches(1, oddAvailable - 1, 1, elements, zerosRemaining, memo));
            }

            // Option 2: Fill the first element with an even number
            if (evenAvailable > 0) {
                minSwitches = Math.min(minSwitches, calculateMinSwitches(1, oddAvailable, 0, elements, zerosRemaining, memo));
            }

            writer.println(minSwitches);
        }
    }

    /**
     * Recursive DP function to calculate the minimum parity switches.
     * 
     * @param idx             Current index in the array
     * @param remOdd          Remaining odd numbers available to fill zeros
     * @param lastParity      The parity of the previous element (0=even, 1=odd)
     * @param elements        The original array
     * @param zerosRemaining  Pre-calculated counts of zeros remaining
     * @param memo            DP memoization table
     * @return Minimum switches from current index to end
     */
    private static int calculateMinSwitches(int idx, int remOdd, int lastParity, int[] elements, int[] zerosRemaining, int[][][] memo) {
        if (idx == elements.length) {
            return 0;
        }

        if (memo[idx][remOdd][lastParity] != -1) {
            return memo[idx][remOdd][lastParity];
        }

        int result = 1_000_000_000; // Use a large constant to prevent overflow on addition

        if (elements[idx] != 0) {
            // Case: Current element is fixed
            int currentParity = Math.abs(elements[idx] % 2);
            int switchCost = (currentParity == lastParity) ? 0 : 1;
            result = switchCost + calculateMinSwitches(idx + 1, remOdd, currentParity, elements, zerosRemaining, memo);
        } else {
            // Case: Current element is a zero, we must choose to fill it with odd or even

            // Try filling with an odd number
            if (remOdd > 0) {
                int switchCost = (lastParity == 1) ? 0 : 1;
                int res = switchCost + calculateMinSwitches(idx + 1, remOdd - 1, 1, elements, zerosRemaining, memo);
                result = Math.min(result, res);
            }

            // Try filling with an even number
            // The number of even numbers remaining is (total zeros left at this index) - (odd numbers left)
            int remEven = zerosRemaining[idx] - remOdd;
            if (remEven > 0) {
                int switchCost = (lastParity == 0) ? 0 : 1;
                int res = switchCost + calculateMinSwitches(idx + 1, remOdd, 0, elements, zerosRemaining, memo);
                result = Math.min(result, res);
            }
        }

        return memo[idx][remOdd][lastParity] = result;
    }

    /**
     * Fast I/O helper class.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Problem Solver: Calculates the minimum parity changes required to achieve
 * a specific count of even numbers in an array, handling zeros as wildcards.
 */
public class Main {

    private static final long INF = 1_000_000_007L;

    public static void main(String[] args) {
        FastReader sc = new FastReader();

        try {
            int totalElements = sc.nextInt();
            if (totalElements < 0) return;

            int[] numbers = new int[totalElements];
            for (int i = 0; i < totalElements; i++) {
                numbers[i] = sc.nextInt();
            }

            int targetEvenCount = totalElements / 2;
            long result = solve(numbers, totalElements, targetEvenCount);
            System.out.println(result);

        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Uses Dynamic Programming to find the minimum cost to reach the target even count.
     * 
     * DP State: dp[i][j][k]
     * i: index of the current element being processed
     * j: current count of even numbers encountered
     * k: parity of the previous element (0 for even, 1 for odd)
     *
     * @param numbers          The input array.
     * @param n                Size of the array.
     * @param targetEvenCount  The required number of even integers.
     * @return                 The minimum cost (parity switches).
     */
    private static long solve(int[] numbers, int n, int targetEvenCount) {
        // dp[index][even_count][last_parity]
        // last_parity: 0 = even, 1 = odd
        long[][][] dp = new long[n + 1][n + 1][2];

        // Initialize DP table with Infinity
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                dp[i][j][0] = INF;
                dp[i][j][1] = INF;
            }
        }

        // Base case: 0 elements processed, 0 even count, 0 cost
        // We initialize both parities at index 0 to allow the first element to transition
        dp[0][0][0] = 0;
        dp[0][0][1] = 0;

        for (int i = 1; i <= n; i++) {
            int currentNum = numbers[i - 1];

            for (int j = 0; j < i; j++) {
                for (int prevParity = 0; prevParity < 2; prevParity++) {
                    long prevCost = dp[i - 1][j][prevParity];

                    if (prevCost >= INF) continue;

                    if (currentNum != 0) {
                        // Case 1: Number is fixed (either even or odd)
                        int currentParity = (currentNum % 2 == 0) ? 0 : 1;
                        int nextEvenCount = (currentParity == 0) ? j + 1 : j;

                        // Cost increases if parity switches
                        int costIncrement = (currentParity == prevParity) ? 0 : 1;

                        // Correction for the very first element (index 0 base case)
                        // If i=1, we don't care about the switch from the dummy prevParity
                        if (i == 1) costIncrement = 0;

                        if (nextEvenCount <= n) {
                            dp[i][nextEvenCount][currentParity] = Math.min(
                                dp[i][nextEvenCount][currentParity], 
                                prevCost + costIncrement
                            );
                        }
                    } else {
                        // Case 2: Number is zero (Wildcard), can be even or odd
                        for (int currentParity = 0; currentParity < 2; currentParity++) {
                            int nextEvenCount = (currentParity == 0) ? j + 1 : j;
                            int costIncrement = (currentParity == prevParity) ? 0 : 1;

                            if (i == 1) costIncrement = 0;

                            if (nextEvenCount <= n) {
                                dp[i][nextEvenCount][currentParity] = Math.min(
                                    dp[i][nextEvenCount][currentParity], 
                                    prevCost + costIncrement
                                );
                            }
                        }
                    }
                }
            }
        }

        return Math.min(dp[n][targetEvenCount][0], dp[n][targetEvenCount][1]);
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader() {
            reader = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.StringTokenizer;

/**
 * A program to find the minimum number of parity switches required to 
 * transform an array by replacing zeros such that the array meets a 
 * specific count of odd and even numbers.
 */
public class Main {

    public static void main(String[] args) {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();
        int[] numbers = fs.nextIntArray(n);

        ParityMinimizer minimizer = new ParityMinimizer(n, numbers);
        System.out.println(minimizer.solve());
    }

    static class ParityMinimizer {
        private final int n;
        private final int[] numbers;
        private static final int INF = 1_000_000;

        public ParityMinimizer(int n, int[] numbers) {
            this.n = n;
            this.numbers = numbers;
        }

        /**
         * Solves the minimization problem using dynamic programming.
         * Time Complexity: O(n * oddsNeeded * evensNeeded)
         * Space Complexity: O(oddsNeeded * evensNeeded)
         */
        public int solve() {
            int existingOdds = 0;
            int existingEvens = 0;

            for (int num : numbers) {
                if (num != 0) {
                    if (isOdd(num)) existingOdds++;
                    else existingEvens++;
                }
            }

            // Calculate target number of odds and evens
            int targetOdds = (n + 1) / 2;
            int targetEvens = n / 2;

            // Calculate how many zeros must be turned into odds vs evens
            int oddsNeeded = Math.max(0, targetOdds - existingOdds);
            int evensNeeded = Math.max(0, targetEvens - existingEvens);

            // dp[oddsUsed][evensUsed][lastParity]
            // lastParity: 0 for even, 1 for odd
            int[][][] dp = new int[oddsNeeded + 1][evensNeeded + 1][2];

            for (int[][] layer : dp) {
                for (int[] row : layer) {
                    Arrays.fill(row, INF);
                }
            }

            // Base case: Initialize the first element
            initializeBaseCase(dp, oddsNeeded, evensNeeded);

            // DP transitions
            for (int i = 1; i < n; i++) {
                int[][][] nextDp = new int[oddsNeeded + 1][evensNeeded + 1][2];
                for (int[][] layer : nextDp) {
                    for (int[] row : layer) {
                        Arrays.fill(row, INF);
                    }
                }

                if (numbers[i] != 0) {
                    int currentParity = isOdd(numbers[i]) ? 1 : 0;
                    processFixedParity(dp, nextDp, oddsNeeded, evensNeeded, currentParity);
                } else {
                    processFlexibleParity(dp, nextDp, oddsNeeded, evensNeeded);
                }
                dp = nextDp;
            }

            return Math.min(dp[oddsNeeded][evensNeeded][0], dp[oddsNeeded][evensNeeded][1]);
        }

        private void initializeBaseCase(int[][][] dp, int oddsNeeded, int evensNeeded) {
            if (numbers[0] != 0) {
                int parity = isOdd(numbers[0]) ? 1 : 0;
                dp[0][0][parity] = 0;
            } else {
                if (oddsNeeded > 0) dp[1][0][1] = 0;
                if (evensNeeded > 0) dp[0][1][0] = 0;
            }
        }

        private void processFixedParity(int[][][] dp, int[][][] nextDp, int maxOdds, int maxEvens, int parity) {
            for (int j = 0; j <= maxOdds; j++) {
                for (int k = 0; k <= maxEvens; k++) {
                    // Transitions from previous parity 0 (even)
                    if (dp[j][k][0] != INF) {
                        int cost = (parity == 1) ? 1 : 0;
                        nextDp[j][k][parity] = Math.min(nextDp[j][k][parity], dp[j][k][0] + cost);
                    }
                    // Transitions from previous parity 1 (odd)
                    if (dp[j][k][1] != INF) {
                        int cost = (parity == 0) ? 1 : 0;
                        nextDp[j][k][parity] = Math.min(nextDp[j][k][parity], dp[j][k][1] + cost);
                    }
                }
            }
        }

        private void processFlexibleParity(int[][][] dp, int[][][] nextDp, int maxOdds, int maxEvens) {
            for (int j = 0; j <= maxOdds; j++) {
                for (int k = 0; k <= maxEvens; k++) {
                    // Option 1: Turn current 0 into an Odd number
                    if (j + 1 <= maxOdds) {
                        if (dp[j][k][0] != INF) nextDp[j + 1][k][1] = Math.min(nextDp[j + 1][k][1], dp[j][k][0] + 1);
                        if (dp[j][k][1] != INF) nextDp[j + 1][k][1] = Math.min(nextDp[j + 1][k][1], dp[j][k][1]);
                    }
                    // Option 2: Turn current 0 into an Even number
                    if (k + 1 <= maxEvens) {
                        if (dp[j][k][0] != INF) nextDp[j][k + 1][0] = Math.min(nextDp[j][k + 1][0], dp[j][k][0]);
                        if (dp[j][k][1] != INF) nextDp[j][k + 1][0] = Math.min(nextDp[j][k + 1][0], dp[j][k][1] + 1);
                    }
                }
            }
        }

        private boolean isOdd(int num) {
            return Math.abs(num % 2) == 1;
        }
    }

    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public int[] nextIntArray(int n) {
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the parity minimization problem.
 * The goal is to fill zero values with even or odd numbers to minimize parity flips,
 * while respecting the total counts of even and odd numbers.
 */
public class CF1286A {

    private static final int UNKNOWN = -1;
    private static final int EVEN = 0;
    private static final int ODD = 1;

    public static void main(String[] args) throws IOException {
        FastReader reader = new FastReader(System.in);
        int n = reader.nextInt();

        if (n <= 0) {
            System.out.println(0);
            return;
        }

        int[] initialValues = new int[n];
        for (int i = 0; i < n; i++) {
            initialValues[i] = reader.nextInt();
        }

        Solver solver = new Solver(n, initialValues);
        System.out.println(solver.solve());
    }

    static class Solver {
        private final int n;
        private final int[] parityArray;
        private int evenQuota;
        private int oddQuota;

        public Solver(int n, int[] initialValues) {
            this.n = n;
            this.parityArray = new int[n];

            // Initial target counts for even and odd numbers
            this.evenQuota = n / 2;
            this.oddQuota = (n + 1) / 2;

            for (int i = 0; i < n; i++) {
                int val = initialValues[i];
                if (val == 0) {
                    parityArray[i] = UNKNOWN;
                } else {
                    int parity = val % 2;
                    parityArray[i] = parity;
                    if (parity == ODD) {
                        oddQuota--;
                    } else {
                        evenQuota--;
                    }
                }
            }
        }

        public int solve() {
            // Handle base case
            if (n == 1) return 0;

            int currentFlips = 0;

            // 1. Calculate initial flips between fixed (non-zero) elements
            for (int i = 1; i < n; i++) {
                if (parityArray[i] != UNKNOWN && parityArray[i - 1] != UNKNOWN) {
                    if (parityArray[i] != parityArray[i - 1]) {
                        currentFlips++;
                    }
                }
            }

            // 2. Group blocks of UNKNOWN parities
            int totalEvenPotential = 0;
            int totalOddPotential = 0;

            List<Integer> evenInternalBlocks = new ArrayList<>();
            List<Integer> evenBoundaryBlocks = new ArrayList<>();
            List<Integer> oddInternalBlocks = new ArrayList<>();
            List<Integer> oddBoundaryBlocks = new ArrayList<>();

            for (int i = 0; i < n; ) {
                if (parityArray[i] == UNKNOWN) {
                    int start = i;
                    while (i < n && parityArray[i] == UNKNOWN) {
                        i++;
                    }
                    int length = i - start;

                    int leftVal = (start > 0) ? parityArray[start - 1] : UNKNOWN;
                    int rightVal = (i < n) ? parityArray[i] : UNKNOWN;

                    boolean isBoundary = (leftVal == UNKNOWN || rightVal == UNKNOWN);
                    boolean isSameParity = (leftVal != UNKNOWN && leftVal == rightVal);

                    // If block is at boundaries or between identical parities, it's "easy" to fill
                    if (isBoundary || isSameParity) {
                        // If adjacent to an Odd number, it's "Odd-friendly"
                        if (leftVal == ODD || rightVal == ODD) {
                            totalOddPotential += length;
                            if (isBoundary) oddBoundaryBlocks.add(length);
                            else oddInternalBlocks.add(length);
                        } else {
                            // Otherwise, it's "Even-friendly"
                            totalEvenPotential += length;
                            if (isBoundary) evenBoundaryBlocks.add(length);
                            else evenInternalBlocks.add(length);
                        }
                    } else {
                        // If block is between different parities (e.g., 0, [unknown], 1), 
                        // it will always create at least one flip.
                        currentFlips++;
                    }
                } else {
                    i++;
                }
            }

            // 3. Adjust flips based on available Even/Odd quota
            if (totalEvenPotential > evenQuota) {
                currentFlips += calculatePenalty(evenInternalBlocks, evenBoundaryBlocks, evenQuota, 2, 1);
            } else if (totalOddPotential > oddQuota) {
                currentFlips += calculatePenalty(oddInternalBlocks, oddBoundaryBlocks, oddQuota, 2, 1);
            }

            return currentFlips;
        }

        /**
         * Calculates the penalty added when we cannot satisfy the quota for a specific parity.
         * It assumes a worst-case penalty and then subtracts based on how many blocks 
         * we can actually satisfy with the available quota.
         */
        private int calculatePenalty(List<Integer> internal, List<Integer> boundary, 
                                     int quota, int internalPenalty, int boundaryPenalty) {

            int penalty = (internal.size() * internalPenalty) + (boundary.size() * boundaryPenalty);

            Collections.sort(internal);
            Collections.sort(boundary);

            int remainingQuota = quota;

            // Try to satisfy internal blocks first (highest impact on penalty)
            for (int len : internal) {
                if (remainingQuota >= len) {
                    penalty -= internalPenalty;
                    remainingQuota -= len;
                } else {
                    break;
                }
            }

            // Try to satisfy boundary blocks
            for (int len : boundary) {
                if (remainingQuota >= len) {
                    penalty -= boundaryPenalty;
                    remainingQuota -= len;
                } else {
                    break;
                }
            }

            return penalty;
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the parity sequence problem.
 */
public class Main {

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        ProblemSolver solver = new ProblemSolver(sc, out);
        solver.solve();

        out.close();
    }

    /**
     * Contains the core logic for solving the problem.
     */
    static class ProblemSolver {
        private final FastScanner sc;
        private final PrintWriter out;

        public ProblemSolver(FastScanner sc, PrintWriter out) {
            this.sc = sc;
            this.out = out;
        }

        public void solve() {
            int n = sc.nextInt();
            int[] sequence = new int[n + 1];
            boolean allZeros = true;

            for (int i = 1; i <= n; i++) {
                sequence[i] = sc.nextInt();
                if (sequence[i] != 0) {
                    allZeros = false;
                }
            }

            // Edge case: If the entire sequence is zeros
            if (allZeros) {
                out.println(n == 1 ? 0 : 1);
                return;
            }

            // 1. Identify boundaries (first and last non-zero elements)
            int startIdx = 1;
            while (startIdx <= n && sequence[startIdx] == 0) {
                startIdx++;
            }

            int endIdx = n;
            while (endIdx >= 1 && sequence[endIdx] == 0) {
                endIdx--;
            }

            // 2. Calculate leading and trailing gaps based on parity
            int leadingZerosCount = startIdx - 1;
            int firstNonZeroParity = Math.abs(sequence[startIdx] % 2);
            int leadingEvenGap = (firstNonZeroParity == 0) ? leadingZerosCount : 0;
            int leadingOddGap = (firstNonZeroParity != 0) ? leadingZerosCount : 0;

            int trailingZerosCount = n - endIdx;
            int lastNonZeroParity = Math.abs(sequence[endIdx] % 2);
            int trailingEvenGap = (lastNonZeroParity == 0) ? trailingZerosCount : 0;
            int trailingOddGap = (lastNonZeroParity != 0) ? trailingZerosCount : 0;

            // 3. Process the middle section (between first and last non-zero elements)
            int moves = 0;
            // The budget represents the number of odd/even index slots available
            int oddBudget = (n + 1) / 2;
            int evenBudget = n - oddBudget;

            List<Integer> evenGaps = new ArrayList<>();
            List<Integer> oddGaps = new ArrayList<>();

            int prevParity = firstNonZeroParity;
            int currentGapLen = 0;

            for (int i = startIdx; i <= endIdx; i++) {
                if (sequence[i] == 0) {
                    currentGapLen++;
                } else {
                    int currentParity = Math.abs(sequence[i] % 2);

                    // Every non-zero element consumes one budget slot
                    if (currentParity == 0) {
                        evenBudget--;
                    } else {
                        oddBudget--;
                    }

                    if (currentParity == prevParity) {
                        if (currentGapLen > 0) {
                            if (currentParity == 0) evenGaps.add(currentGapLen);
                            else oddGaps.add(currentGapLen);
                        }
                    } else {
                        // Parity transition requires a move
                        moves++;
                    }
                    prevParity = currentParity;
                    currentGapLen = 0;
                }
            }

            // 4. Greedy strategy to satisfy gaps using remaining budget

            // Handle even-parity gaps (filling same-parity gaps with the other parity)
            Collections.sort(evenGaps);
            for (int gap : evenGaps) {
                if (evenBudget >= gap) {
                    evenBudget -= gap;
                } else {
                    moves += 2;
                }
            }
            if (leadingEvenGap > 0) {
                if (evenBudget >= leadingEvenGap) evenBudget -= leadingEvenGap;
                else moves++;
            }
            if (trailingEvenGap > 0) {
                if (evenBudget >= trailingEvenGap) evenBudget -= trailingEvenGap;
                else moves++;
            }

            // Handle odd-parity gaps
            Collections.sort(oddGaps);
            for (int gap : oddGaps) {
                if (oddBudget >= gap) {
                    oddBudget -= gap;
                } else {
                    moves += 2;
                }
            }
            if (leadingOddGap > 0) {
                if (oddBudget >= leadingOddGap) oddBudget -= leadingOddGap;
                else moves++;
            }
            if (trailingOddGap > 0) {
                if (oddBudget >= trailingOddGap) oddBudget -= trailingOddGap;
                else moves++;
            }

            out.println(moves);
        }
    }

    /**
     * Efficient input reader.
     */
    static class FastScanner {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public FastScanner(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (numChars == -1) return -1;
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    return -1;
                }
                if (numChars <= 0) return -1;
            }
            return buf[curChar++];
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res = res * 10 + (c - '0');
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * Problem: Fill the zero-slots in an array with missing numbers from the set {1, 2, ..., N}
 * such that the total number of parity transitions in the final array is minimized.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        // Read the input size
        int n = reader.nextInt();
        if (n <= 0) {
            System.out.println(0);
            return;
        }

        // arr: contains the input numbers (0 represents a placeholder)
        // isPresent: tracks which numbers from 1 to N are already in the array
        int[] arr = new int[n];
        boolean[] isPresent = new boolean[n + 1];

        for (int i = 0; i < n; i++) {
            arr[i] = reader.nextInt();
            if (arr[i] > 0 && arr[i] <= n) {
                isPresent[arr[i]] = true;
            }
        }

        // Count how many even and odd numbers from the set {1...N} are missing
        int evenMissing = 0;
        int oddMissing = 0;
        for (int i = 1; i <= n; i++) {
            if (!isPresent[i]) {
                if (i % 2 == 0) {
                    evenMissing++;
                } else {
                    oddMissing++;
                }
            }
        }

        // Execute the solver
        ParityMinimizer solver = new ParityMinimizer(arr, evenMissing, oddMissing);
        System.out.println(solver.calculateMinimumTransitions());
    }

    /**
     * Encapsulates the logic for minimizing parity transitions using Dynamic Programming.
     */
    static class ParityMinimizer {
        private final int[] arr;
        private final int size;
        private final int totalEvenMissing;
        private final int totalOddMissing;

        // Memoization table: [index][evenRemaining][oddRemaining][lastParity]
        // lastParity: 0 = even, 1 = odd, 2 = none (for the start of the array)
        private final Integer[][][][] memo;

        public ParityMinimizer(int[] arr, int evenMissing, int oddMissing) {
            this.arr = arr;
            this.size = arr.length;
            this.totalEvenMissing = evenMissing;
            this.totalOddMissing = oddMissing;
            this.memo = new Integer[size][evenMissing + 1][oddMissing + 1][3];
        }

        /**
         * Entry point for the DP calculation.
         */
        public int calculateMinimumTransitions() {
            return solve(0, totalEvenMissing, totalOddMissing, 2);
        }

        /**
         * Recursive DP function with memoization.
         * 
         * @param idx Current index in the array being processed.
         * @param eRem Number of even numbers still available to be placed.
         * @param oRem Number of odd numbers still available to be placed.
         * @param lastParity Parity of the previous element (0=even, 1=odd, 2=start).
         * @return Minimum transitions from the current state to the end.
         */
        private int solve(int idx, int eRem, int oRem, int lastParity) {
            // Base case: processed all elements
            if (idx == size) {
                return 0;
            }

            // Return memoized result if we have already calculated this state
            if (memo[idx][eRem][oRem][lastParity] != null) {
                return memo[idx][eRem][oRem][lastParity];
            }

            int minTransitions = Integer.MAX_VALUE;

            if (arr[idx] != 0) {
                // CASE 1: The number is already fixed in the array
                int currentParity = arr[idx] % 2;
                int cost = (lastParity != 2 && currentParity != lastParity) ? 1 : 0;

                int result = solve(idx + 1, eRem, oRem, currentParity);
                if (result != Integer.MAX_VALUE) {
                    minTransitions = cost + result;
                }
            } else {
                // CASE 2: The current element is 0, we must choose to place an even or odd number

                // Option A: Try placing an even number
                if (eRem > 0) {
                    int currentParity = 0; // even
                    int cost = (lastParity != 2 && currentParity != lastParity) ? 1 : 0;
                    int result = solve(idx + 1, eRem - 1, oRem, currentParity);
                    if (result != Integer.MAX_VALUE) {
                        minTransitions = Math.min(minTransitions, cost + result);
                    }
                }

                // Option B: Try placing an odd number
                if (oRem > 0) {
                    int currentParity = 1; // odd
                    int cost = (lastParity != 2 && currentParity != lastParity) ? 1 : 0;
                    int result = solve(idx + 1, eRem, oRem - 1, currentParity);
                    if (result != Integer.MAX_VALUE) {
                        minTransitions = Math.min(minTransitions, cost + result);
                    }
                }
            }

            return memo[idx][eRem][oRem][lastParity] = minTransitions;
        }
    }

    /**
     * High-performance reader for standard input.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            if (next == null) return -1;
            return Integer.parseInt(next);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored version of the Parity Segment Solver.
 * The goal is to find the minimum operations to satisfy a specific parity distribution.
 */
public class ParitySegmentSolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        ParitySegmentSolver solver = new ParitySegmentSolver();
        solver.solve(reader, out);
        out.flush();
        out.close();
    }

    /**
     * Main execution logic.
     */
    public void solve(FastReader fr, PrintWriter out) {
        int n = fr.nextInt();
        int[] parities = new int[n]; // -1: wildcard, 0: even, 1: odd
        int evenCount = 0;
        int oddCount = 0;

        for (int i = 0; i < n; i++) {
            int p = fr.nextInt();
            if (p == 0) {
                parities[i] = -1;
            } else {
                parities[i] = p % 2;
                if (parities[i] == 0) evenCount++;
                else oddCount++;
            }
        }

        int evenTarget = n / 2;
        int oddTarget = (n + 1) / 2;
        int evenDeficit = evenTarget - evenCount;
        int oddDeficit = oddTarget - oddCount;

        // Special case: If the array is composed entirely of wildcards
        if (evenCount == 0 && oddCount == 0) {
            out.println(n == 1 ? 0 : 1);
            return;
        }

        // Segment storage
        List<Integer> evenEndSegments = new ArrayList<>();
        List<Integer> evenInternalSegments = new ArrayList<>();
        List<Integer> oddEndSegments = new ArrayList<>();
        List<Integer> oddInternalSegments = new ArrayList<>();
        List<Integer> alternatingSegments = new ArrayList<>();

        int switches = 0;
        int lastNonWildcardIdx = -1;

        for (int i = 0; i < n; i++) {
            if (parities[i] == -1) continue;

            int gap = i - lastNonWildcardIdx - 1;
            if (gap > 0) {
                if (parities[i] == 0) { // Current is even
                    if (lastNonWildcardIdx == -1) {
                        evenEndSegments.add(gap);
                    } else if (parities[lastNonWildcardIdx] == 0) {
                        evenInternalSegments.add(gap);
                    } else {
                        alternatingSegments.add(gap);
                    }
                } else { // Current is odd
                    if (lastNonWildcardIdx == -1) {
                        oddEndSegments.add(gap);
                    } else if (parities[lastNonWildcardIdx] == 1) {
                        oddInternalSegments.add(gap);
                    } else {
                        alternatingSegments.add(gap);
                    }
                }
            }

            if (lastNonWildcardIdx != -1 && parities[lastNonWildcardIdx] != parities[i]) {
                switches++;
            }
            lastNonWildcardIdx = i;
        }

        // Handle the final gap after the last non-wildcard element
        int finalGap = n - lastNonWildcardIdx - 1;
        if (finalGap > 0 && lastNonWildcardIdx != -1) {
            if (parities[lastNonWildcardIdx] == 0) evenEndSegments.add(finalGap);
            else oddEndSegments.add(finalGap);
        }

        // If no elements need to be added to meet parity requirements
        if (evenDeficit <= 0 && oddDeficit <= 0) {
            out.println(switches);
            return;
        }

        int totalSwitches = switches;
        int evenInternalSum = sumList(evenInternalSegments);
        int evenEndSum = sumList(evenEndSegments);
        int oddInternalSum = sumList(oddInternalSegments);
        int oddEndSum = sumList(oddEndSegments);
        int alternatingSum = sumList(alternatingSegments);

        // Greedy logic to satisfy deficits
        if (evenDeficit > (evenInternalSum + evenEndSum)) {
            int remainingEvenDeficit = evenDeficit - (evenInternalSum + evenEndSum);
            if (remainingEvenDeficit > alternatingSum) {
                int afterAlternatingDeficit = remainingEvenDeficit - alternatingSum;
                totalSwitches += calculateMinStepsWithTransitions(
                        afterAlternatingDeficit, oddEndSegments, oddInternalSegments);
            }
        } else if (oddDeficit > (oddInternalSum + oddEndSum)) {
            int remainingOddDeficit = oddDeficit - (oddInternalSum + oddEndSum);
            if (remainingOddDeficit > alternatingSum) {
                int afterAlternatingDeficit = remainingOddDeficit - alternatingSum;
                totalSwitches += calculateMinStepsWithTransitions(
                        afterAlternatingDeficit, evenEndSegments, evenInternalSegments);
            }
        }

        out.println(totalSwitches);
    }

    private int sumList(List<Integer> list) {
        int sum = 0;
        for (int val : list) sum += val;
        return sum;
    }

    /**
     * Calculates the number of steps needed to cover a deficit using segments of the opposite parity.
     */
    private int calculateMinStepsWithTransitions(int deficit, List<Integer> endSegments, List<Integer> internalSegments) {
        Collections.sort(endSegments);
        Collections.sort(internalSegments);

        int ans;
        if (!endSegments.isEmpty() && deficit <= endSegments.get(endSegments.size() - 1)) {
            ans = 1;
        } else if (endSegments.size() == 2 && deficit <= (endSegments.get(0) + endSegments.get(1))) {
            ans = 2;
        } else {
            ans = deficit * 2;
            int internalSum = sumList(internalSegments);

            if (deficit <= internalSum) {
                ans = Math.min(ans, calculateGreedySteps(deficit, internalSegments) * 2);
            }
            if (!endSegments.isEmpty() && deficit - endSegments.get(0) <= internalSum) {
                ans = Math.min(ans, 1 + calculateGreedySteps(deficit - endSegments.get(0), internalSegments) * 2);
            }
            if (endSegments.size() == 2) {
                if (deficit - endSegments.get(1) <= internalSum) {
                    ans = Math.min(ans, 1 + calculateGreedySteps(deficit - endSegments.get(1), internalSegments) * 2);
                }
                if (deficit - endSegments.get(0) - endSegments.get(1) <= internalSum) {
                    ans = Math.min(ans, 2 + calculateGreedySteps(deficit - endSegments.get(0) - endSegments.get(1), internalSegments) * 2);
                }
            }
        }
        return ans;
    }

    /**
     * Greedy approach to see how many segments are required to cover the remaining deficit.
     */
    private int calculateGreedySteps(int deficit, List<Integer> sortedSegments) {
        int steps = 0;
        int remaining = deficit;
        // We use segments from largest to smallest
        for (int i = sortedSegments.size() - 1; i >= 0 && remaining > 0; i--) {
            steps++;
            remaining -= sortedSegments.get(i);
        }
        return steps;
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;

/**
 * Solution to calculate the minimum changes required to balance 
 * the parity of an array containing wildcards (zeros).
 */
public class Solution {

    public static void main(String[] args) {
        Solution solver = new Solution();
        solver.run();
    }

    /**
     * Orchestrates the test case execution.
     */
    public void run() {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) return;

        int testCases = scanner.nextInt();
        for (int t = 1; t <= testCases; t++) {
            if (scanner.hasNextInt()) {
                int n = scanner.nextInt();
                int[] numbers = new int[n];
                for (int i = 0; i < n; i++) {
                    numbers[i] = scanner.nextInt();
                }
                System.out.println(calculateMinChanges(numbers));
            }
        }
        scanner.close();
    }

    /**
     * Core logic to calculate the minimum number of parity changes.
     * 
     * @param numbers The input array where 0 represents a wildcard.
     * @return The minimum changes required.
     */
    private int calculateMinChanges(int[] numbers) {
        int n = numbers.length;
        if (n <= 1) {
            return allZeros(numbers) ? (n == 1 ? 0 : 1) : 0; 
            // Note: Based on original logic for n=1 and all zeros
        }

        int currentOdd = 0;
        int currentEven = 0;

        // 1. Count existing parities
        for (int num : numbers) {
            if (num > 0) {
                if (num % 2 == 0) currentEven++;
                else currentOdd++;
            }
        }

        // 2. Determine how many more of each parity we need to reach the target
        int targetEven = n / 2;
        int targetOdd = n - targetEven;
        int neededOdd = targetOdd - currentOdd;
        int neededEven = targetEven - currentEven;

        // 3. Identify gaps of zeros between non-zero elements
        int[] oddGapFreq = new int[n];
        int[] evenGapFreq = new int[n];
        int changes = 0;

        int lastNonZeroIdx = -1;
        for (int i = 0; i < n; i++) {
            if (numbers[i] != 0) {
                if (lastNonZeroIdx != -1) {
                    int gapLen = i - lastNonZeroIdx - 1;
                    if (gapLen > 0) {
                        changes += processInternalGap(numbers[lastNonZeroIdx], numbers[i], gapLen, oddGapFreq, evenGapFreq);
                    }
                }
                lastNonZeroIdx = i;
            }
        }

        // If the entire array is zeros
        if (lastNonZeroIdx == -1) {
            return (n == 1) ? 0 : 1;
        }

        // 4. Greedy approach to fill gaps using the required parity counts
        changes += satisfyGapRequirements(oddGapFreq, evenGapFreq, n, neededOdd, neededEven);

        // 5. Handle leading and trailing zeros
        changes += handleEdgeZeros(numbers, neededOdd, neededEven);

        return changes;
    }

    private boolean allZeros(int[] numbers) {
        for (int num : numbers) if (num != 0) return false;
        return true;
    }

    /**
     * Processes a gap between two non-zero numbers.
     * If they have different parities, a change is mandatory.
     * If they have the same parity, the gap is recorded for the greedy filler.
     */
    private int processInternalGap(int leftVal, int rightVal, int gapLen, int[] oddFreq, int[] evenFreq) {
        boolean leftIsEven = leftVal % 2 == 0;
        boolean rightIsEven = rightVal % 2 == 0;

        if (leftIsEven == rightIsEven) {
            if (leftIsEven) {
                evenFreq[gapLen]++;
            } else {
                oddFreq[gapLen]++;
            }
            return 0;
        } else {
            // Parity mismatch requires a direct change
            return 1;
        }
    }

    /**
     * Uses the needed parity counts to satisfy as many gaps as possible.
     */
    private int satisfyGapRequirements(int[] oddFreq, int[] evenFreq, int n, int neededOdd, int neededEven) {
        int changes = 0;
        int currentNeededOdd = neededOdd;
        int currentNeededEven = neededEven;

        for (int i = 1; i < n; i++) {
            // Handle Odd gaps
            long oddReq = (long) i * oddFreq[i];
            if (oddReq <= currentNeededOdd) {
                currentNeededOdd -= oddReq;
            } else {
                int canSatisfy = currentNeededOdd / i;
                oddFreq[i] -= canSatisfy;
                changes += (oddFreq[i] * 2);
                currentNeededOdd -= (canSatisfy * i);
            }

            // Handle Even gaps
            long evenReq = (long) i * evenFreq[i];
            if (evenReq <= currentNeededEven) {
                currentNeededEven -= evenReq;
            } else {
                int canSatisfy = currentNeededEven / i;
                evenFreq[i] -= canSatisfy;
                changes += (evenFreq[i] * 2);
                currentNeededEven -= (canSatisfy * i);
            }
        }
        return changes;
    }

    /**
     * Calculates changes needed for leading and trailing zero sequences.
     */
    private int handleEdgeZeros(int[] numbers, int neededOdd, int neededEven) {
        int n = numbers.length;
        int changes = 0;

        // Leading zeros
        int firstNonZero = 0;
        while (firstNonZero < n && numbers[firstNonZero] == 0) {
            firstNonZero++;
        }

        if (firstNonZero > 0) {
            if (numbers[firstNonZero] % 2 == 0) {
                if (firstNonZero <= neededEven) {
                    // logic conceptually consumes neededEven, but not strictly needed for final sum
                } else {
                    changes++;
                }
            } else {
                if (firstNonZero <= neededOdd) {
                    // logic conceptually consumes neededOdd
                } else {
                    changes++;
                }
            }
        }

        // Trailing zeros
        int lastNonZero = n - 1;
        while (lastNonZero >= 0 && numbers[lastNonZero] == 0) {
            lastNonZero--;
        }

        int trailingZerosCount = n - 1 - lastNonZero;
        if (trailingZerosCount > 0) {
            if (numbers[lastNonZero] % 2 == 0) {
                if (trailingZerosCount > neededEven) {
                    changes++;
                }
            } else {
                if (trailingZerosCount > neededOdd) {
                    changes++;
                }
            }
        }

        return changes;
    }
}

import java.util.Scanner;

/**
 * The Garland class serves as the entry point for the application.
 * It handles user input and outputs the final result.
 */
public class Garland {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int n = scanner.nextInt();
        int[] inputArr = new int[n];
        for (int i = 0; i < n; i++) {
            if (scanner.hasNextInt()) {
                inputArr[i] = scanner.nextInt();
            }
        }

        GarlandSolver solver = new GarlandSolver(inputArr, n);
        System.out.println(solver.solve());

        scanner.close();
    }
}

/**
 * GarlandSolver encapsulates the logic for filling gaps in a sequence
 * of numbers while respecting parity budgets and minimizing transitions.
 */
class GarlandSolver {

    private static final int EMPTY = 0;
    private static final int ODD = 1;
    private static final int EVEN = 2;

    private final int[] sequence;
    private final int n;
    private int oddBudget;
    private int evenBudget;

    public GarlandSolver(int[] input, int n) {
        this.sequence = input;
        this.n = n;
        calculateInitialBudgets();
    }

    /**
     * Calculates the maximum number of odd and even numbers allowed based on N.
     */
    private void calculateInitialBudgets() {
        this.oddBudget = (n % 2 == 0) ? (n / 2) : (n / 2) + 1;
        this.evenBudget = n / 2;

        // Subtract existing non-zero elements from the budget
        for (int val : sequence) {
            if (val != EMPTY) {
                if (val % 2 == 0) {
                    evenBudget--;
                } else {
                    oddBudget--;
                }
            }
        }
    }

    /**
     * Orchestrates the filling process and returns the count of parity transitions.
     */
    public int solve() {
        int firstNonZero = findFirstNonZero();
        int lastNonZero = findLastNonZero();

        // Case: Array is entirely empty
        if (firstNonZero == -1) {
            return (n == 1) ? 0 : 1;
        }

        fillInternalGaps(firstNonZero, lastNonZero);
        fillTail(lastNonZero);
        fillHead(firstNonZero);
        fillMiddleRemaining(firstNonZero);
        fillRemainingWithDefault();

        return countParityTransitions();
    }

    /**
     * Fills gaps located between two existing numbers if the budget allows
     * maintaining the same parity.
     */
    private void fillInternalGaps(int first, int last) {
        for (int i = 0; i < n; i++) {
            if (sequence[i] != EMPTY) continue;

            // Find the extent of the current zero-gap
            int gapStart = i;
            while (i < n && sequence[i] == EMPTY) {
                i++;
            }
            int gapEnd = i - 1;

            // If this is an internal gap (not at the very start or end of bounds)
            if (gapStart > first && gapEnd < last) {
                int leftVal = sequence[gapStart - 1];
                int rightVal = sequence[gapEnd + 1];
                int gapLength = (gapEnd - gapStart) + 1;

                // If boundaries have the same parity, try to fill the gap with that parity
                if (isSameParity(leftVal, rightVal) && canAfford(leftVal, gapLength)) {
                    int parityToFill = (leftVal % 2 == 0) ? EVEN : ODD;
                    for (int k = gapStart; k <= gapEnd; k++) {
                        sequence[k] = parityToFill;
                    }
                    updateBudget(parityToFill, gapLength);
                }
            }
        }
    }

    /**
     * Fills zeros at the end of the array if the budget allows matching the last number.
     */
    private void fillTail(int lastNonZero) {
        if (lastNonZero < n - 1) {
            int gapLength = (n - 1) - lastNonZero;
            int lastVal = sequence[lastNonZero];

            if (canAfford(lastVal, gapLength)) {
                int parityToFill = (lastVal % 2 == 0) ? EVEN : ODD;
                for (int i = lastNonZero + 1; i < n; i++) {
                    sequence[i] = parityToFill;
                }
                updateBudget(parityToFill, gapLength);
            }
        }
    }

    /**
     * Fills zeros at the start of the array using a greedy matching approach.
     */
    private void fillHead(int firstNonZero) {
        for (int i = firstNonZero - 1; i >= 0; i--) {
            insertGreedy(i, sequence[i + 1]);
        }
    }

    /**
     * Fills remaining middle gaps, avoiding gaps that would force a parity switch.
     */
    private void fillMiddleRemaining(int firstNonZero) {
        for (int i = firstNonZero + 1; i < n; i++) {
            if (sequence[i] != EMPTY) continue;

            // Check if neighbors have different parities; if so, skip to avoid immediate transition
            if (i < n - 1 && sequence[i - 1] != EMPTY && sequence[i + 1] != EMPTY) {
                if (!isSameParity(sequence[i - 1], sequence[i + 1])) {
                    continue;
                }
            }
            insertGreedy(i, sequence[i - 1]);
        }
    }

    /**
     * Final pass to ensure no zeros remain, defaulting to ODD.
     */
    private void fillRemainingWithDefault() {
        for (int i = 0; i < n; i++) {
            if (sequence[i] == EMPTY) {
                sequence[i] = ODD;
            }
        }
    }

    /**
     * Inserts a value at the specified index, attempting to respect the preferred parity.
     */
    private void insertGreedy(int index, int preferredVal) {
        int preferredParity = (preferredVal % 2 == 0) ? EVEN : ODD;
        if (canAfford(preferredVal, 1)) {
            sequence[index] = preferredParity;
            updateBudget(preferredParity, 1);
        } else {
            // Fallback to the other parity
            int fallbackParity = (preferredParity == EVEN) ? ODD : EVEN;
            sequence[index] = fallbackParity;
            updateBudget(fallbackParity, 1);
        }
    }

    private int countParityTransitions() {
        int transitions = 0;
        for (int i = 0; i < n - 1; i++) {
            if (!isSameParity(sequence[i], sequence[i + 1])) {
                transitions++;
            }
        }
        return transitions;
    }

    private boolean isSameParity(int a, int b) {
        return (a % 2) == (b % 2);
    }

    private boolean canAfford(int val, int amount) {
        if (val % 2 == 0) {
            return evenBudget >= amount;
        } else {
            return oddBudget >= amount;
        }
    }

    private void updateBudget(int parity, int amount) {
        if (parity == EVEN) {
            evenBudget -= amount;
        } else {
            oddBudget -= amount;
        }
    }

    private int findFirstNonZero() {
        for (int i = 0; i < n; i++) {
            if (sequence[i] != EMPTY) return i;
        }
        return -1;
    }

    private int findLastNonZero() {
        for (int i = n - 1; i >= 0; i--) {
            if (sequence[i] != EMPTY) return i;
        }
        return -1;
    }
}

import java.util.*;
import java.io.*;

/**
 * A solver for the permutation parity minimization problem.
 * The goal is to fill missing elements (0s) in a sequence to form a permutation
 * of 1 to N, minimizing the number of parity switches between adjacent elements.
 */
public class Main {

    public static void main(String[] args) {
        try {
            Solver solver = new Solver();
            solver.solve();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    static class Solver {
        private static final int INF = 1_000_000_000;

        public void solve() throws IOException {
            FastReader reader = new FastReader(System.in);
            PrintWriter out = new PrintWriter(System.out);

            int n = reader.nextInt();
            if (n <= 0) {
                out.println(0);
                out.flush();
                return;
            }

            int[] sequence = new int[n + 1];
            boolean[] isPresent = new boolean[n + 1];

            for (int i = 1; i <= n; i++) {
                sequence[i] = reader.nextInt();
                if (sequence[i] != 0) {
                    isPresent[sequence[i]] = true;
                }
            }

            // Count how many even and odd numbers are missing from the 1..N range
            int missingEven = 0;
            int missingOdd = 0;
            for (int i = 1; i <= n; i++) {
                if (!isPresent[i]) {
                    if (i % 2 == 0) missingEven++;
                    else missingOdd++;
                }
            }

            // dp[2][remEven][remOdd][lastParity]
            // Using a rolling array for the first dimension to save memory: O(N^2) instead of O(N^3)
            int[][][][] dp = new int[2][missingEven + 1][missingOdd + 1][2];

            // Initialize DP table with INF
            for (int i = 0; i < 2; i++) {
                for (int j = 0; j <= missingEven; j++) {
                    for (int k = 0; k <= missingOdd; k++) {
                        Arrays.fill(dp[i][j][k], INF);
                    }
                }
            }

            // Base Case: First element
            int curr = 1 % 2;
            int prev = 0 % 2;

            if (sequence[1] == 0) {
                // If first element is a placeholder, try using a missing even or odd number
                if (missingEven > 0) {
                    dp[curr][missingEven - 1][missingOdd][0] = 0;
                }
                if (missingOdd > 0) {
                    dp[curr][missingEven][missingOdd - 1][1] = 0;
                }
            } else {
                // If first element is fixed, use its parity
                int parity = sequence[1] % 2;
                dp[curr][missingEven][missingOdd][parity] = 0;
            }

            // DP Transitions
            for (int i = 2; i <= n; i++) {
                curr = i % 2;
                prev = (i - 1) % 2;

                // Reset current layer
                for (int j = 0; j <= missingEven; j++) {
                    for (int k = 0; k <= missingOdd; k++) {
                        Arrays.fill(dp[curr][j][k], INF);
                    }
                }

                for (int e = 0; e <= missingEven; e++) {
                    for (int o = 0; o <= missingOdd; o++) {
                        if (sequence[i] == 0) {
                            // Case: current element is a placeholder (must use a missing number)

                            // Option A: Use an even number
                            if (e + 1 <= missingEven) {
                                // Same parity (even -> even)
                                dp[curr][e][o][0] = Math.min(dp[curr][e][o][0], dp[prev][e + 1][o][0]);
                                // Switch parity (odd -> even)
                                dp[curr][e][o][0] = Math.min(dp[curr][e][o][0], 1 + dp[prev][e + 1][o][1]);
                            }

                            // Option B: Use an odd number
                            if (o + 1 <= missingOdd) {
                                // Same parity (odd -> odd)
                                dp[curr][e][o][1] = Math.min(dp[curr][e][o][1], dp[prev][e][o + 1][1]);
                                // Switch parity (even -> odd)
                                dp[curr][e][o][1] = Math.min(dp[curr][e][o][1], 1 + dp[prev][e][o + 1][0]);
                            }
                        } else {
                            // Case: current element is fixed
                            int p = sequence[i] % 2;
                            // Same parity (p -> p)
                            dp[curr][e][o][p] = Math.min(dp[curr][e][o][p], dp[prev][e][o][p]);
                            // Switch parity (1-p -> p)
                            dp[curr][e][o][p] = Math.min(dp[curr][e][o][p], 1 + dp[prev][e][o][1 - p]);
                        }
                    }
                }
            }

            int result = Math.min(dp[n % 2][0][0][0], dp[n % 2][0][0][1]);
            out.println(result >= INF ? -1 : result);
            out.flush();
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Main entry point for the application.
 */
public class Main {
    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        ProblemSolver solver = new ProblemSolver();
        solver.solve(reader, writer);

        writer.close();
    }

    /**
     * Handles the core logic of the problem using dynamic programming.
     */
    static class ProblemSolver {
        private static final int INF = 1_000_000;

        // DP State constants for the last element's parity/type
        private static final int STATE_EVEN = 0;
        private static final int STATE_ODD = 1;
        private static final int STATE_FIXED = 2;

        public void solve(FastReader reader, PrintWriter writer) {
            int n = reader.nextInt();
            int[] sequence = new int[n + 1];
            int[] existingParityCounts = new int[2];

            for (int i = 1; i <= n; i++) {
                sequence[i] = reader.nextInt();
                if (sequence[i] != 0) {
                    existingParityCounts[sequence[i] % 2]++;
                }
            }

            // Calculate how many even and odd numbers we still need to place
            int neededEven = (n / 2) - existingParityCounts[0];
            int neededOdd = ((n + 1) / 2) - existingParityCounts[1];

            // dp[index][oddCount][evenCount][lastParityState]
            int[][][][] minCostTable = new int[n + 1][neededOdd + 1][neededEven + 1][3];

            // Initialize DP table with Infinity
            for (int i = 0; i <= n; i++) {
                for (int j = 0; j <= neededOdd; j++) {
                    for (int k = 0; k <= neededEven; k++) {
                        for (int s = 0; s < 3; s++) {
                            minCostTable[i][j][k][s] = INF;
                        }
                    }
                }
            }

            for (int i = 1; i <= n; i++) {
                int currentVal = sequence[i];

                if (currentVal != 0) {
                    // Case 1: The element at this position is fixed by the input
                    int currentParity = currentVal % 2;

                    if (i == 1) {
                        minCostTable[i][0][0][STATE_FIXED] = 0;
                        continue;
                    }

                    int prevVal = sequence[i - 1];
                    for (int j = 0; j <= neededOdd; j++) {
                        for (int k = 0; k <= neededEven; k++) {
                            if (prevVal == 0) {
                                // Transition from a previously filled (0) slot
                                // If current is odd, cost is 1 if prev was even, 0 if prev was odd
                                int costIfPrevEven = (currentParity == 1) ? 1 : 0;
                                int costIfPrevOdd = (currentParity == 0) ? 1 : 0;

                                minCostTable[i][j][k][STATE_FIXED] = Math.min(
                                    minCostTable[i - 1][j][k][STATE_EVEN] + costIfPrevEven,
                                    minCostTable[i - 1][j][k][STATE_ODD] + costIfPrevOdd
                                );
                            } else {
                                // Transition from a fixed element
                                int parityFlip = (currentParity != (prevVal % 2)) ? 1 : 0;
                                minCostTable[i][j][k][STATE_FIXED] = minCostTable[i - 1][j][k][STATE_FIXED] + parityFlip;
                            }
                        }
                    }
                } else {
                    // Case 2: The element at this position is a placeholder (0)
                    if (i == 1) {
                        if (neededOdd > 0) minCostTable[i][1][0][STATE_ODD] = 0;
                        if (neededEven > 0) minCostTable[i][0][1][STATE_EVEN] = 0;
                        continue;
                    }

                    int prevVal = sequence[i - 1];
                    for (int j = 0; j <= neededOdd; j++) {
                        for (int k = 0; k <= neededEven; k++) {
                            if (prevVal != 0) {
                                // Previous was a fixed element, we are choosing to fill this one
                                // Fill with Odd
                                if (j + 1 <= neededOdd) {
                                    minCostTable[i][j + 1][k][STATE_ODD] = Math.min(
                                        minCostTable[i][j + 1][k][STATE_ODD], 
                                        minCostTable[i - 1][j][k][STATE_FIXED] + (prevVal % 2 == 0 ? 1 : 0)
                                    );
                                }
                                // Fill with Even
                                if (k + 1 <= neededEven) {
                                    minCostTable[i][j][k + 1][STATE_EVEN] = Math.min(
                                        minCostTable[i][j][k + 1][STATE_EVEN], 
                                        minCostTable[i - 1][j][k][STATE_FIXED] + (prevVal % 2 == 1 ? 1 : 0)
                                    );
                                }
                            } else {
                                // Previous was also a placeholder (0)
                                // Fill with Odd
                                if (j + 1 <= neededOdd) {
                                    int costFromEven = minCostTable[i - 1][j][k][STATE_EVEN] + 1;
                                    int costFromOdd = minCostTable[i - 1][j][k][STATE_ODD];
                                    minCostTable[i][j + 1][k][STATE_ODD] = Math.min(minCostTable[i][j + 1][k][STATE_ODD], Math.min(costFromEven, costFromOdd));
                                }
                                // Fill with Even
                                if (k + 1 <= neededEven) {
                                    int costFromEven = minCostTable[i - 1][j][k][STATE_EVEN];
                                    int costFromOdd = minCostTable[i - 1][j][k][STATE_ODD] + 1;
                                    minCostTable[i][j][k + 1][STATE_EVEN] = Math.min(minCostTable[i][j][k + 1][STATE_EVEN], Math.min(costFromEven, costFromOdd));
                                }
                            }
                        }
                    }
                }
            }

            int result = Math.min(minCostTable[n][neededOdd][neededEven][STATE_EVEN],
                         Math.min(minCostTable[n][neededOdd][neededEven][STATE_ODD], 
                                  minCostTable[n][neededOdd][neededEven][STATE_FIXED]));
            writer.println(result);
        }
    }

    /**
     * Fast I/O utility for efficient reading.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A refactored solution to a parity-based partitioning problem.
 * The goal is to find the minimum number of parity switches required to partition
 * an array into two subsets with specific target counts of even and odd numbers.
 */
public class Main {

    public static void main(String[] args) {
        // Use try-with-resources to ensure streams are closed automatically
        try (FastReader in = new FastReader(System.in);
             FastWriter out = new FastWriter(System.out)) {

            ParitySplitSolver solver = new ParitySplitSolver();
            solver.solve(in, out);

        } catch (IOException e) {
            System.err.println("Error processing input/output: " + e.getMessage());
        }
    }

    /**
     * Core logic for solving the parity partitioning problem using Dynamic Programming.
     */
    static class ParitySplitSolver {
        private static final int INF = 1_000_000_000;

        public void solve(FastReader in, FastWriter out) throws IOException {
            int n = in.nextInt();
            if (n <= 0) {
                out.printLine(0);
                return;
            }

            int targetZeroCount = n / 2;
            int targetOneCount = n - targetZeroCount;

            int[] constraints = new int[n];
            for (int i = 0; i < n; i++) {
                int val = in.nextInt();
                // Transform: 0 is a wildcard (-1), otherwise use parity (0 or 1)
                if (val == 0) {
                    constraints[i] = -1;
                } else {
                    constraints[i] = Math.abs(val % 2);
                }
            }

            // dp[lastParity][remainingZeros][remainingOnes]
            int[][][] currentDp = new int[2][targetZeroCount + 1][targetOneCount + 1];
            int[][][] nextDp = new int[2][targetZeroCount + 1][targetOneCount + 1];

            // Initialize DP tables with Infinity
            initializeTable(currentDp, targetZeroCount, targetOneCount);
            initializeTable(nextDp, targetZeroCount, targetOneCount);

            // Base Case: Before any elements are processed, we assume a starting state
            // where no cost is incurred regardless of the first element's parity.
            currentDp[0][targetZeroCount][targetOneCount] = 0;
            currentDp[1][targetZeroCount][targetOneCount] = 0;

            for (int elementIdx = 0; elementIdx < n; elementIdx++) {
                initializeTable(nextDp, targetZeroCount, targetOneCount);
                int constraint = constraints[elementIdx];

                for (int lastParity = 0; lastParity < 2; lastParity++) {
                    for (int rem0 = 0; rem0 <= targetZeroCount; rem0++) {
                        for (int rem1 = 0; rem1 <= targetOneCount; rem1++) {

                            int currentCost = currentDp[lastParity][rem0][rem1];
                            if (currentCost >= INF) {
                                continue;
                            }

                            // Try assigning the current element to parity 0 or 1
                            for (int currentParity = 0; currentParity < 2; currentParity++) {
                                // Check if assignment is allowed by constraints
                                if (constraint != -1 && constraint != currentParity) {
                                    continue;
                                }

                                // Calculate switch cost (1 if parity changes, 0 otherwise)
                                int switchCost = (currentParity == lastParity) ? 0 : 1;
                                int totalCost = currentCost + switchCost;

                                int nextRem0 = (currentParity == 0) ? rem0 - 1 : rem0;
                                int nextRem1 = (currentParity == 1) ? rem1 - 1 : rem1;

                                // Validate bounds
                                if (nextRem0 >= 0 && nextRem1 >= 0) {
                                    if (nextDp[currentParity][nextRem0][nextRem1] > totalCost) {
                                        nextDp[currentParity][nextRem0][nextRem1] = totalCost;
                                    }
                                }
                            }
                        }
                    }
                }

                // Swap buffers: move nextDp to currentDp for the next iteration
                int[][][] temp = currentDp;
                currentDp = nextDp;
                nextDp = temp;
            }

            int result = Math.min(currentDp[0][0][0], currentDp[1][0][0]);
            out.printLine(result);
        }

        private void initializeTable(int[][][] table, int max0, int max1) {
            for (int i = 0; i < 2; i++) {
                for (int j = 0; j <= max0; j++) {
                    Arrays.fill(table[i][j], INF);
                }
            }
        }
    }

    /**
     * High-performance input reader using a buffered byte stream.
     */
    static class FastReader implements AutoCloseable {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024 * 16];
        private int pointer = 0;
        private int bytesRead = 0;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() throws IOException {
            if (pointer >= bytesRead) {
                pointer = 0;
                bytesRead = stream.read(buffer);
                if (bytesRead <= 0) return -1;
            }
            return buffer[pointer++] & 0xFF;
        }

        public int nextInt() throws IOException {
            int c = readByte();
            while (c != -1 && isSpace(c)) c = readByte();
            if (c == -1) throw new EOFException();

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }

            int res = 0;
            while (c >= '0' && c <= '9') {
                res = res * 10 + (c - '0');
                c = readByte();
            }
            return res * sign;
        }

        private boolean isSpace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        @Override
        public void close() throws IOException {
            stream.close();
        }
    }

    /**
     * High-performance output writer using buffered PrintWriter.
     */
    static class FastWriter implements AutoCloseable {
        private final PrintWriter writer;

        public FastWriter(OutputStream outputStream) {
            this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public void printLine(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                writer.print(objects[i]);
                if (i < objects.length - 1) writer.print(" ");
            }
            writer.println();
        }

        @Override
        public void close() {
            writer.close();
        }
    }
}

import java.util.Arrays;
import java.util.Scanner;

/**
 * A solution to minimize parity transitions in a sequence where some elements are fixed
 * and others (represented by 0) can be either even or odd, given a fixed budget
 * of even and odd numbers.
 */
public class ParityTransitionMinimizer {

    private static final int INF = 1_000_000;
    private final int[] numbers;
    private final int[][][][] memo;

    /**
     * Initializes the solver with the input array and sets up the memoization table.
     *
     * @param numbers The array of integers where 0 represents a wildcard.
     */
    public ParityTransitionMinimizer(int[] numbers) {
        this.numbers = numbers;
        int n = numbers.length;

        // memo[index][evenRemaining][oddRemaining][lastWasEven]
        // Dimensions are based on n to ensure all possible states are covered.
        this.memo = new int[n + 1][n + 1][n + 1][2];

        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                for (int k = 0; k <= n; k++) {
                    Arrays.fill(memo[i][j][k], -1);
                }
            }
        }
    }

    /**
     * Solves the problem by trying both starting parity possibilities.
     *
     * @return The minimum number of parity transitions required.
     */
    public int solve() {
        int n = numbers.length;

        // Calculate initial availability of even and odd numbers
        int evenAvailable = n / 2;
        int oddAvailable = (n + 1) / 2;

        for (int num : numbers) {
            if (num != 0) {
                if (num % 2 == 0) {
                    evenAvailable--;
                } else {
                    oddAvailable--;
                }
            }
        }

        // We attempt starting the sequence by assuming the 'previous' number 
        // was Even (true) or Odd (false). This allows the first element 
        // to be assigned its parity without an initial transition penalty.
        return Math.min(
            compute(0, evenAvailable, oddAvailable, true),
            compute(0, evenAvailable, oddAvailable, false)
        );
    }

    /**
     * Recursive DP function with memoization to calculate minimum transitions.
     *
     * @param index       Current position in the array.
     * @param evenRem     Remaining count of even numbers to be used.
     * @param oddRem      Remaining count of odd numbers to be used.
     * @param lastWasEven Boolean indicating if the previous number was even.
     * @return The minimum transitions from this state to the end.
     */
    private int compute(int index, int evenRem, int oddRem, boolean lastWasEven) {
        // Base case: reached the end of the array successfully
        if (index == numbers.length) {
            return 0;
        }

        // If we have exhausted our budget of even or odd numbers, this path is invalid
        if (evenRem < 0 || oddRem < 0) {
            return INF;
        }

        int lastParityIdx = lastWasEven ? 1 : 0;
        if (memo[index][evenRem][oddRem][lastParityIdx] != -1) {
            return memo[index][evenRem][oddRem][lastParityIdx];
        }

        int minTransitions = INF;

        if (numbers[index] == 0) {
            // Case 1: Wildcard number (0). We try both even and odd.

            // Option A: Use an even number
            if (evenRem > 0) {
                int cost = lastWasEven ? 0 : 1;
                minTransitions = Math.min(minTransitions, cost + compute(index + 1, evenRem - 1, oddRem, true));
            }

            // Option B: Use an odd number
            if (oddRem > 0) {
                int cost = lastWasEven ? 1 : 0;
                minTransitions = Math.min(minTransitions, cost + compute(index + 1, evenRem, oddRem - 1, false));
            }
        } else {
            // Case 2: Fixed number. Parity is predetermined.
            boolean isEven = (numbers[index] % 2 == 0);
            if (isEven) {
                int cost = lastWasEven ? 0 : 1;
                minTransitions = cost + compute(index + 1, evenRem, oddRem, true);
            } else {
                int cost = lastWasEven ? 1 : 0;
                minTransitions = cost + compute(index + 1, evenRem, oddRem, false);
            }
        }

        return memo[index][evenRem][oddRem][lastParityIdx] = minTransitions;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        if (!sc.hasNextInt()) {
            sc.close();
            return;
        }

        int n = sc.nextInt();
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = sc.nextInt();
        }
        sc.close();

        ParityTransitionMinimizer solver = new ParityTransitionMinimizer(arr);
        System.out.println(solver.solve());
    }
}

