    /**
     * Fast I/O Reader.
     */
    static class FastReader {
        private final InputStream in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int buflen = 0;

        public FastReader(InputStream in) {
            this.in = in;
        }

        private boolean hasNextByte() {
            if (ptr < buflen) return true;
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                return false;
            }
            return buflen > 0;
        }

        private int readByte() {
            return hasNextByte() ? buffer[ptr++] : -1;
        }

        private static boolean isPrintableChar(int c) {
            return 33 <= c && c <= 126;
        }

        private void skipUnprintable() {
            while (hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++;
        }

        public boolean hasNext() {
            skipUnprintable();
            return hasNextByte();
        }

        public String next() {
            if (!hasNext()) throw new NoSuchElementException();
            StringBuilder sb = new StringBuilder();
            int b = readByte();
            while (isPrintableChar(b)) {
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }

        public int nextInt() {
            return (int) nextLong();
        }

        public long nextLong() {
            if (!hasNext()) throw new NoSuchElementException();
            long n = 0;
            boolean minus = false;
            int b = readByte();
            if (b == '-') {
                minus = true;
                b = readByte();
            }
            while (true) {
                if ('0' <= b && b <= '9') {
                    n = n * 10 + (b - '0');
                } else if (b == -1 || !isPrintableChar(b)) {
                    return minus ? -n : n;
                }
                b = readByte();
            }
        }
    }

    /**
     * Improved PrintWriter wrapper for cleaner output.
     */
    static class PrintWriterWrapper extends PrintWriter {
        public PrintWriterWrapper(PrintStream ps) {
            super(ps);
        }

        public void printArray(int[] a, String separator) {
            for (int i = 0; i < a.length; i++) {
                print(i == 0 ? "" : separator + a[i]);
            }
            println();
        }

        public void printArray(long[] a, String separator) {
            for (int i = 0; i < a.length; i++) {
                print(i == 0 ? "" : separator + a[i]);
            }
            println();
        }

        public <T> void printList(List<T> list, String separator) {
            for (int i = 0; i < list.size(); i++) {
                print(i == 0 ? "" : separator + list.get(i));
            }
            println();
        }
    }
}

