/**
 * Solver class containing the core logic for the parity balancing problem.
 */
class ParitySolver {

    private static final int INF = 1_000_000_000;

    /**
     * Solves the problem by calculating the minimum cost to balance even and odd numbers.
     * 
     * NOTE: The current implementation uses an O(N^3) Dynamic Programming approach.
     * For large N (e.g., N=300,000), this will exceed memory and time limits.
     * This refactoring preserves the original logic while improving code quality.
     */
    public void solve(FastReader in, PrintWriter out) {
        int testCases = 1; 
        while (testCases-- > 0) {
            int n = in.nextInt();
            int[] elements = new int[n];
            int currentEvenCount = 0;
            int currentOddCount = 0;

            for (int i = 0; i < n; i++) {
                elements[i] = in.nextInt();
                if (elements[i] != 0) {
                    if (elements[i] % 2 == 0) {
                        currentEvenCount++;
                    } else {
                        currentOddCount++;
                    }
                }
            }

            // Calculate how many even/odd numbers we need to "fill in" the zeros
            int evenNeeded = n / 2 - currentEvenCount;
            int oddNeeded = (n + 1) / 2 - currentOddCount;

            // If requirements are negative, the input already has too many of one parity
            if (evenNeeded < 0 || oddNeeded < 0) {
                out.println(0);
                continue;
            }

            // dp[i][j][k][parity]
            // i: number of elements processed
            // j: number of even numbers used from wildcards (0)
            // k: number of odd numbers used from wildcards (0)
            // parity: 0 for even, 1 for odd
            int[][][][] dp = new int[n + 1][evenNeeded + 1][oddNeeded + 1][2];

            // Initialize DP table with a large value
            for (int i = 0; i <= n; i++) {
                for (int j = 0; j <= evenNeeded; j++) {
                    for (int k = 0; k <= oddNeeded; k++) {
                        Arrays.fill(dp[i][j][k], INF);
                    }
                }
            }

            // Base case: before processing any elements
            dp[0][0][0][0] = 0;
            dp[0][0][0][1] = 0;

            for (int i = 1; i <= n; i++) {
                int val = elements[i - 1];
                for (int j = 0; j <= evenNeeded; j++) {
                    for (int k = 0; k <= oddNeeded; k++) {
                        for (int currentParity = 0; currentParity < 2; currentParity++) {

                            if (val == 0) {
                                // Case: The number is a wildcard (0)
                                int minCost = INF;

                                // Try assigning even parity to this wildcard
                                if (currentParity == 0 && j > 0) {
                                    // Previous could have been even (0) or odd (1)
                                    minCost = Math.min(minCost, dp[i - 1][j - 1][k][0] + 0);
                                    minCost = Math.min(minCost, dp[i - 1][j - 1][k][1] + 1);
                                } 
                                // Try assigning odd parity to this wildcard
                                else if (currentParity == 1 && k > 0) {
                                    minCost = Math.min(minCost, dp[i - 1][j][k - 1][0] + 1);
                                    minCost = Math.min(minCost, dp[i - 1][j][k - 1][1] + 0);
                                }

                                // The original logic used a slightly different transition:
                                // min = Math.min(dp[i-1][j-1][k][0] + l, dp[i-1][j][k-1][1] + 1-l)
                                // Re-implementing the exact logic provided in the snippet:
                                int logicMin = INF;
                                if (currentParity == 0 && j > 0) {
                                    logicMin = Math.min(logicMin, dp[i - 1][j - 1][k][0] + 0);
                                    if (k > 0) logicMin = Math.min(logicMin, dp[i - 1][j][k - 1][1] + 1);
                                } else if (currentParity == 1 && k > 0) {
                                    logicMin = Math.min(logicMin, dp[i - 1][j][k - 1][1] + 0);
                                    if (j > 0) logicMin = Math.min(logicMin, dp[i - 1][j - 1][k][0] + 1);
                                }
                                // Note: To perfectly match original logic's structure:
                                if (val == 0) {
                                    int m = INF;
                                    if (currentParity == 0 && j > 0) m = Math.min(m, dp[i-1][j-1][k][0] + 0);
                                    // This part of original logic was slightly non-standard; 
                                    // applying the literal interpretation for consistency:
                                    if (currentParity == 0 && k > 0) m = Math.min(m, dp[i-1][j][k-1][1] + 1);
                                    if (currentParity == 1 && j > 0) m = Math.min(m, dp[i-1][j-1][k][0] + 1);
                                    if (currentParity == 1 && k > 0) m = Math.min(m, dp[i-1][j][k-1][1] + 0);
                                    dp[i][j][k][currentParity] = m;
                                }
                            } else {
                                // Case: The number is fixed
                                int fixedParity = Math.abs(val % 2);
                                // Cost is added if the desired parity l differs from the fixed parity
                                dp[i][j][k][currentParity] = dp[i - 1][j][k][fixedParity] + Math.abs(fixedParity - currentParity);
                            }
                        }
                    }
                }
            }

            int result = Math.min(dp[n][evenNeeded][oddNeeded][0], dp[n][evenNeeded][oddNeeded][1]);
            out.println(result >= INF ? 0 : result);
        }
    }
}

