import java.util.*;
import java.io.*;

/**
 * ParitySequenceSolver
 * 
 * This program calculates the minimum number of changes required to transform
 * a sequence of even, odd, or unknown numbers into a sequence with a 
 * specific count of even and odd numbers.
 */
public class ParitySequenceSolver {

    // Constants for parity and state representation
    private static final int EVEN = 0;
    private static final int ODD = 1;
    private static final int UNKNOWN = -1;
    private static final int INF = 1_000_000;

    public static void main(String[] args) {
        FastReader sc = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        // Read the size of the sequence
        String nStr = sc.next();
        if (nStr == null) {
            out.close();
            return;
        }
        int n = Integer.parseInt(nStr);

        if (n <= 0) {
            out.close();
            return;
        }

        // 1-indexed array to store parities: EVEN, ODD, or UNKNOWN
        int[] parities = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            int val = sc.nextInt();
            if (val == 0) {
                parities[i] = UNKNOWN;
            } else if (val % 2 == 0) {
                parities[i] = EVEN;
            } else {
                parities[i] = ODD;
            }
        }

        // Determine target counts for even and odd numbers based on problem rules
        int targetEven = (n % 2 == 0) ? n / 2 : (n - 1) / 2;
        int targetOdd = n - targetEven;

        /* 
         * dp[i][j][p] represents the minimum changes for the first 'i' elements,
         * containing exactly 'j' even numbers, where the 'i'-th element has parity 'p'.
         * p=0 for EVEN, p=1 for ODD.
         */
        int[][][] dp = new int[n + 1][targetEven + 1][2];

        // Initialize DP table with a high value representing infinity
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= targetEven; j++) {
                Arrays.fill(dp[i][j], INF);
            }
        }

        // Base case: Processing the first element (i = 1)
        // Handle targetEven/targetOdd bounds to avoid out-of-bounds errors
        if (targetEven >= 1) {
            int costToEven = (parities[1] == ODD) ? 1 : 0;
            dp[1][1][EVEN] = costToEven;
        }
        if (targetOdd >= 1) {
            int costToOdd = (parities[1] == EVEN) ? 1 : 0;
            dp[1][0][ODD] = costToOdd;
        }

        // DP State Transitions: Fill the table from i = 2 to n
        for (int i = 2; i <= n; i++) {
            for (int j = 0; j <= targetEven; j++) {
                int k = i - j; // Current count of odd elements

                // Ensure the current state is valid within the target constraints
                if (k < 0 || k > targetOdd) {
                    continue;
                }

                // Transition 1: The i-th element is assigned EVEN parity
                if (j > 0) {
                    int costToEven = (parities[i] == ODD) ? 1 : 0;
                    int prevMin = Math.min(dp[i - 1][j - 1][EVEN], dp[i - 1][j - 1][ODD]);
                    if (prevMin != INF) {
                        dp[i][j][EVEN] = prevMin + costToEven;
                    }
                }

                // Transition 2: The i-th element is assigned ODD parity
                if (k > 0) {
                    int costToOdd = (parities[i] == EVEN) ? 1 : 0;
                    int prevMin = Math.min(dp[i - 1][j][EVEN], dp[i - 1][j][ODD]);
                    if (prevMin != INF) {
                        dp[i][j][ODD] = prevMin + costToOdd;
                    }
                }
            }
        }

        // The result is the minimum cost to reach the desired target state at index n
        int result = Math.min(dp[n][targetEven][EVEN], dp[n][targetEven][ODD]);

        if (result >= INF) {
            out.println(-1); 
        } else {
            out.println(result);
        }

        out.close();
    }

    /**
     * FastReader class for efficient input parsing.
     */
    static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String next = next();
            return (next == null) ? 0 : Integer.parseInt(next);
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.util.*;

/**
 * ParityMatcher calculates the minimum number of parity changes (alternations)
 * required in an array to reach a target parity distribution, given that 
 * only elements with value 0 can be changed.
 */
public class ParityMatcher {

    private static int arraySize;
    private static long[] numbers;
    private static Integer[][][] memo;
    private static int targetEven;
    private static int targetOdd;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        arraySize = scanner.nextInt();
        numbers = new long[arraySize];

        int currentEvenCount = 0;
        int currentOddCount = 0;

        for (int i = 0; i < arraySize; i++) {
            numbers[i] = scanner.nextLong();
            if (numbers[i] != 0) {
                if (numbers[i] % 2 == 0) {
                    currentEvenCount++;
                } else {
                    currentOddCount++;
                }
            }
        }

        // Determine target distribution of even and odd numbers.
        // Target: n/2 evens, and the rest as odds.
        targetEven = arraySize / 2;
        targetOdd = arraySize - targetEven;

        // Calculate how many even/odd numbers we need to provide using the 0s.
        int neededEven = targetEven - currentEvenCount;
        int neededOdd = targetOdd - currentOddCount;

        // memo[index][evenRemaining][lastParity]
        // lastParity: 0 for even, 1 for odd
        memo = new Integer[arraySize + 1][arraySize + 1][2];

        int maxSameParityAdjacencies = 0;

        if (numbers[0] == 0) {
            // If the first element is a wildcard, we try both starting with Even or Odd.

            // Case 1: Start with Even
            if (neededEven > 0) {
                maxSameParityAdjacencies = Math.max(maxSameParityAdjacencies, 
                    solve(1, 0, neededEven - 1, neededOdd));
            }

            // Case 2: Start with Odd
            if (neededOdd > 0) {
                maxSameParityAdjacencies = Math.max(maxSameParityAdjacencies, 
                    solve(1, 1, neededEven, neededOdd - 1));
            }

            // Corner cases where one type of number is already exhausted
            if (neededEven <= 0 && neededOdd > 0) {
                maxSameParityAdjacencies = Math.max(maxSameParityAdjacencies, solve(1, 1, 0, neededOdd - 1));
            } else if (neededOdd <= 0 && neededEven > 0) {
                maxSameParityAdjacencies = Math.max(maxSameParityAdjacencies, solve(1, 0, neededEven - 1, 0));
            }
        } else {
            // If the first element is fixed, start from the second element with its parity.
            int firstParity = (numbers[0] % 2 == 0) ? 0 : 1;
            maxSameParityAdjacencies = solve(1, firstParity, neededEven, neededOdd);
        }

        // The result is total possible adjacencies minus the maximum matches.
        // This represents the minimum number of parity changes.
        System.out.println((arraySize - 1) - maxSameParityAdjacencies);

        scanner.close();
    }

    /**
     * Recursive DP function to find the maximum number of adjacent elements 
     * with the same parity.
     * 
     * @param idx Current index being processed.
     * @param lastParity Parity of the previous element (0 for even, 1 for odd).
     * @param e Remaining even numbers to be placed in 0-slots.
     * @param o Remaining odd numbers to be placed in 0-slots.
     * @return Maximum number of same-parity adjacencies from idx to arraySize-1.
     */
    private static int solve(int idx, int lastParity, int e, int o) {
        if (idx == arraySize) {
            return 0;
        }

        if (memo[idx][e][lastParity] != null) {
            return memo[idx][e][lastParity];
        }

        int maxMatches = 0;

        if (numbers[idx] == 0) {
            // Option 1: Fill this 0 with an Even number
            if (e > 0) {
                int match = (lastParity == 0) ? 1 : 0;
                maxMatches = Math.max(maxMatches, match + solve(idx + 1, 0, e - 1, o));
            }
            // Option 2: Fill this 0 with an Odd number
            if (o > 0) {
                int match = (lastParity == 1) ? 1 : 0;
                maxMatches = Math.max(maxMatches, match + solve(idx + 1, 1, e, o - 1));
            }
        } else {
            // Current element is fixed
            int currentParity = (numbers[idx] % 2 == 0) ? 0 : 1;
            int match = (lastParity == currentParity) ? 1 : 0;
            maxMatches = match + solve(idx + 1, currentParity, e, o);
        }

        return memo[idx][e][lastParity] = maxMatches;
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to solve the parity sequence problem: 
 * Minimizing the number of adjacent elements with different parities 
 * when filling placeholders (0s) with a set of unused numbers.
 */
public class Main {
    public static void main(String[] args) {
        try (FastReader reader = new FastReader(System.in);
             PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)))) {

            int n = reader.nextInt();
            if (n <= 0) {
                writer.println(0);
                return;
            }

            int[] sequence = new int[n];
            for (int i = 0; i < n; i++) {
                sequence[i] = reader.nextInt();
            }

            ParityMinimizer solver = new ParityMinimizer(sequence);
            writer.println(solver.solve());
            writer.flush();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /**
     * Logic class to solve the parity transition minimization problem using Dynamic Programming.
     */
    static class ParityMinimizer {
        private static final long INF = 1_000_000_000L;
        private static final int PARITY_NONE = 2;
        private static final int PARITY_EVEN = 0;
        private static final int PARITY_ODD = 1;

        private final int[] sequence;
        private final int sequenceLength;
        private final int totalOddAvailable;
        private final int totalEvenAvailable;

        // memo[index][remainingOdd][lastParity]
        private long[][][] memo;

        public ParityMinimizer(int[] sequence) {
            this.sequence = sequence;
            this.sequenceLength = sequence.length;

            // Calculate how many odd and even numbers are available to fill the 0s
            Set<Integer> usedNumbers = new HashSet<>();
            for (int num : sequence) {
                if (num != 0) {
                    usedNumbers.add(num);
                }
            }

            int oddCount = 0;
            int evenCount = 0;
            for (int i = 1; i <= sequenceLength; i++) {
                if (!usedNumbers.contains(i)) {
                    if (i % 2 == 0) evenCount++;
                    else oddCount++;
                }
            }
            this.totalOddAvailable = oddCount;
            this.totalEvenAvailable = evenCount;
        }

        public long solve() {
            // Initialize memoization table with -1
            memo = new long[sequenceLength][totalOddAvailable + 1][3];
            for (int i = 0; i < sequenceLength; i++) {
                for (int j = 0; j <= totalOddAvailable; j++) {
                    Arrays.fill(memo[i][j], -1);
                }
            }

            return calculateMinTransitions(0, totalOddAvailable, totalEvenAvailable, PARITY_NONE);
        }

        /**
         * Recursive DP function with memoization.
         * 
         * @param idx Current index in the sequence
         * @param remOdd Remaining odd numbers available to fill 0s
         * @param remEven Remaining even numbers available to fill 0s
         * @param lastParity Parity of the previous element (0=even, 1=odd, 2=none)
         * @return Minimum parity transitions from this state to the end
         */
        private long calculateMinTransitions(int idx, int remOdd, int remEven, int lastParity) {
            if (idx == sequenceLength) {
                return 0;
            }

            if (memo[idx][remOdd][lastParity] != -1) {
                return memo[idx][remOdd][lastParity];
            }

            long minTransitions = INF;

            if (sequence[idx] != 0) {
                // Current element is fixed
                int currentParity = (sequence[idx] % 2 != 0) ? PARITY_ODD : PARITY_EVEN;
                int cost = (lastParity == PARITY_NONE) ? 0 : (currentParity == lastParity ? 0 : 1);
                minTransitions = cost + calculateMinTransitions(idx + 1, remOdd, remEven, currentParity);
            } else {
                // Current element is a placeholder (0), try both even and odd

                // Option 1: Place an even number
                if (remEven > 0) {
                    int cost = (lastParity == PARITY_NONE) ? 0 : (PARITY_EVEN == lastParity ? 0 : 1);
                    minTransitions = Math.min(minTransitions, cost + calculateMinTransitions(idx + 1, remOdd, remEven - 1, PARITY_EVEN));
                }

                // Option 2: Place an odd number
                if (remOdd > 0) {
                    int cost = (lastParity == PARITY_NONE) ? 0 : (PARITY_ODD == lastParity ? 0 : 1);
                    minTransitions = Math.min(minTransitions, cost + calculateMinTransitions(idx + 1, remOdd - 1, remEven, PARITY_ODD));
                }
            }

            return memo[idx][remOdd][lastParity] = minTransitions;
        }
    }

    /**
     * High-performance custom reader for faster integer parsing.
     */
    static class FastReader implements AutoCloseable {
        private final BufferedInputStream bis;

        public FastReader(InputStream is) {
            this.bis = new BufferedInputStream(is);
        }

        public int nextInt() throws IOException {
            int c = read();
            while (c != -1 && c <= 32) c = read();
            if (c == -1) return 0;

            int neg = 1;
            if (c == '-') {
                neg = -1;
                c = read();
            }

            int res = 0;
            while (c > 32) {
                res = res * 10 + (c - '0');
                c = read();
            }
            return res * neg;
        }

        private int read() throws IOException {
            return bis.read();
        }

        @Override
        public void close() throws IOException {
            bis.close();
        }
    }
}

