/**
 * Represents a contiguous block of missing values (EMPTY) in the array.
 */
class Segment implements Comparable<Segment> {
    private final int start;
    private final int end;
    private final int penalty;
    private final int length;

    public Segment(int start, int end, int penalty) {
        this.start = start;
        this.end = end;
        this.penalty = penalty;
        this.length = end - start + 1;
    }

    public int getLength() {
        return length;
    }

    public int getPenalty() {
        return penalty;
    }

    @Override
    public int compareTo(Segment other) {
        // Sort by penalty descending (highest penalty first to prioritize saving them)
        if (this.penalty != other.penalty) {
            return Integer.compare(other.penalty, this.penalty);
        }
        // If penalties are equal, sort by length ascending
        return Integer.compare(this.length, other.length);
    }
}

/**
 * Contains the business logic to solve the optimization problem.
 */
class ProblemSolver {
    public static final int EMPTY = -1;
    private static final int TYPE_0 = 0;
    private static final int TYPE_1 = 1;

    private final int n;
    private final int[] elements;

    public ProblemSolver(int n, int[] elements) {
        this.n = n;
        this.elements = elements;
    }

    /**
     * Executes the solving algorithm.
     * @return The minimum cost calculated.
     */
    public int solve() {
        int[] remainingCapacity = new int[2];
        remainingCapacity[0] = n / 2;
        remainingCapacity[1] = n / 2 + (n % 2);

        int totalCost = 0;

        // 1. Calculate initial cost based on existing transitions and update capacity
        for (int i = 0; i < n; i++) {
            if (elements[i] != EMPTY) {
                remainingCapacity[elements[i]]--;
                if (i > 0 && elements[i - 1] != EMPTY && elements[i] != elements[i - 1]) {
                    totalCost++;
                }
            }
        }

        // 2. Handle the special case where all elements are empty
        if (remainingCapacity[0] + remainingCapacity[1] == n) {
            return 1;
        }

        // 3. Identify and categorize segments of EMPTY values
        List<Segment>[] segmentsByType = new ArrayList[2];
        segmentsByType[0] = new ArrayList<>();
        segmentsByType[1] = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            if (elements[i] != EMPTY) {
                continue;
            }

            int start = i;
            int end = i;
            // Find the end of the current empty block
            for (int j = i + 1; j < n; j++) {
                if (elements[j] == EMPTY) {
                    end = j;
                } else {
                    break;
                }
            }

            categorizeSegment(start, end, segmentsByType, totalCost);

            // If the segment was between different values, the cost is incremented immediately
            if (start > 0 && end < n - 1 && elements[start - 1] != elements[end + 1]) {
                totalCost++;
            }

            // Skip to the end of this block
            i = end;
        }

        // 4. Apply greedy strategy to minimize cost using available capacity
        for (int i = 0; i < 2; i++) {
            Collections.sort(segmentsByType[i]);
            for (Segment segment : segmentsByType[i]) {
                if (remainingCapacity[i] >= segment.getLength()) {
                    remainingCapacity[i] -= segment.getLength();
                } else {
                    totalCost += segment.getPenalty();
                }
            }
        }

        return totalCost;
    }

    private void categorizeSegment(int start, int end, List<Segment>[] segmentsByType, int currentCost) {
        if (start > 0 && end < n - 1) {
            // Segment is sandwiched between two elements
            if (elements[start - 1] == elements[end + 1]) {
                // Neighbors match: potential to fill with the same type
                int type = elements[start - 1];
                segmentsByType[type].add(new Segment(start, end, 2));
            }
            // If neighbors differ, the cost is handled in the main loop (totalCost++)
        } else {
            // Segment is at an edge (start or end of array)
            int type = (start > 0) ? elements[start - 1] : elements[end + 1];
            segmentsByType[type].add(new Segment(start, end, 1));
        }
    }
}

