import java.util.*;

/**
 * Refactored Garland program to minimize the number of parity switches
 * in a sequence of even and odd numbers, subject to parity and count constraints.
 */
public class Garland {
    private static final int INF = 1000;
    private static final int IMPOSSIBLE_RESULT = 100;

    private final int n;
    private final int[] arr;
    private final int maxEvens;
    private final int maxOdds;
    private final int[][][][] memo;

    /**
     * Initializes the solver with the input array and calculates constraints.
     * 
     * @param n   The length of the garland.
     * @param arr The input array where 0 represents any parity and non-zero represents a fixed value.
     */
    public Garland(int n, int[] arr) {
        this.n = n;
        this.arr = arr;

        // The problem requires a balanced sequence where the number of evens and odds 
        // are approximately n/2.
        if (n % 2 == 0) {
            this.maxEvens = n / 2;
            this.maxOdds = n / 2;
        } else {
            this.maxEvens = n / 2;
            this.maxOdds = n / 2 + 1;
        }

        // memo[index][evensCount][oddsCount][lastParity]
        // lastParity: 0 for even, 1 for odd.
        this.memo = new int[n + 1][n + 1][n + 1][2];
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                for (int k = 0; k <= n; k++) {
                    Arrays.fill(memo[i][j][k], -1);
                }
            }
        }
    }

    /**
     * Recursive DP function to find the minimum number of parity switches.
     * 
     * @param index      The current index in the sequence being decided.
     * @param evensCount Total even numbers used up to this point.
     * @param oddsCount  Total odd numbers used up to this point.
     * @param lastParity The parity of the previous element (0 for even, 1 for odd).
     * @return The minimum switches from the current state to the end.
     */
    private int solve(int index, int evensCount, int oddsCount, int lastParity) {
        // Base case: All elements have been successfully placed.
        if (index == n) {
            return 0;
        }

        // Return memoized result if available.
        if (memo[index][evensCount][oddsCount][lastParity] != -1) {
            return memo[index][evensCount][oddsCount][lastParity];
        }

        int minSwitches = INF;

        // Option 1: Try placing an Even number (parity 0).
        // Valid if arr[index] is 0 or an even number.
        if (arr[index] == 0 || arr[index] % 2 == 0) {
            int nextEvens = evensCount + 1;
            int nextOdds = oddsCount;

            if (nextEvens <= maxEvens && nextOdds <= maxOdds) {
                // A switch occurs if the current parity (0) is different from lastParity.
                int switchCost = (lastParity == 0) ? 0 : 1;
                int result = solve(index + 1, nextEvens, nextOdds, 0);
                if (result != INF) {
                    minSwitches = Math.min(minSwitches, switchCost + result);
                }
            }
        }

        // Option 2: Try placing an Odd number (parity 1).
        // Valid if arr[index] is 0 or an odd number.
        if (arr[index] == 0 || arr[index] % 2 != 0) {
            int nextEvens = evensCount;
            int nextOdds = oddsCount + 1;

            if (nextEvens <= maxEvens && nextOdds <= maxOdds) {
                // A switch occurs if the current parity (1) is different from lastParity.
                int switchCost = (lastParity == 1) ? 0 : 1;
                int result = solve(index + 1, nextEvens, nextOdds, 1);
                if (result != INF) {
                    minSwitches = Math.min(minSwitches, switchCost + result);
                }
            }
        }

        return memo[index][evensCount][oddsCount][lastParity] = minSwitches;
    }

    /**
     * Orchestrates the calculation by trying both possible starting parities.
     */
    public void solveAndPrint() {
        int minTotalSwitches = INF;

        // The first element (index 0) is special because it doesn't have a "previous" 
        // element to cause a switch. We handle this by initializing the first 
        // element and starting the recursion from index 1.

        // Scenario A: Start with an Even number.
        if (arr[0] == 0 || arr[0] % 2 == 0) {
            if (1 <= maxEvens) {
                int res = solve(1, 1, 0, 0);
                minTotalSwitches = Math.min(minTotalSwitches, res);
            }
        }

        // Scenario B: Start with an Odd number.
        if (arr[0] == 0 || arr[0] % 2 != 0) {
            if (1 <= maxOdds) {
                int res = solve(1, 0, 1, 1);
                minTotalSwitches = Math.min(minTotalSwitches, res);
            }
        }

        // If no valid sequence was found, return the designated impossible value.
        if (minTotalSwitches >= INF) {
            System.out.println(IMPOSSIBLE_RESULT);
        } else {
            System.out.println(minTotalSwitches);
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        if (!sc.hasNextInt()) {
            sc.close();
            return;
        }

        int n = sc.nextInt();
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = sc.nextInt();
        }
        sc.close();

        Garland garland = new Garland(n, arr);
        garland.solveAndPrint();
    }
}

import java.util.*;
import java.io.*;

/**
 * A solver to find the minimum number of parity transitions (odd-to-even or even-to-odd)
 * in an array by filling in the gaps (represented by 0) to meet specific parity requirements.
 */
public class ParityTransitionSolver {

    private enum Parity {
        NONE,
        ODD,
        EVEN
    }

    public static void main(String[] args) {
        try {
            FastReader reader = new FastReader(System.in);
            int totalElements = reader.nextInt();
            if (totalElements <= 0) {
                System.out.println(0);
                return;
            }

            int[] numbers = reader.nextIntArray(totalElements);

            ParityTransitionSolver solver = new ParityTransitionSolver();
            int result = solver.solve(numbers, totalElements);
            System.out.println(result);

        } catch (Exception e) {
            System.err.println("Error processing input: " + e.getMessage());
        }
    }

    /**
     * Orchestrates the calculation of the minimum parity transitions.
     */
    public int solve(int[] numbers, int n) {
        int existingOdds = 0;
        int existingEvens = 0;

        for (int num : numbers) {
            if (num != 0) {
                if (num % 2 == 0) existingEvens++;
                else existingOdds++;
            }
        }

        // Target parity distribution based on original problem logic
        int targetOdds = (n + 1) / 2;
        int targetEvens = n / 2;

        int oddsNeeded = targetOdds - existingOdds;

        // If existing numbers already exceed targets, the requirement is effectively 0
        // though based on problem logic, the 0s will fill the remaining slots.
        oddsNeeded = Math.max(0, oddsNeeded);

        // Initialize memoization table: [index][remaining_odds][last_parity_enum]
        // Parity.NONE is index 0, ODD is 1, EVEN is 2.
        int[][][] memo = new int[n][oddsNeeded + 1][3];
        for (int[][] layer : memo) {
            for (int[] row : layer) {
                Arrays.fill(row, -1);
            }
        }

        return computeMinTransitions(numbers, 0, oddsNeeded, Parity.NONE, memo);
    }

    /**
     * Recursive DP function with memoization to find minimum transitions.
     */
    private int computeMinTransitions(int[] numbers, int index, int oddsRemaining, Parity lastParity, int[][][] memo) {
        // Base case: reached end of array
        if (index == numbers.length) {
            return 0;
        }

        // Check memoization table
        int parityIdx = lastParity.ordinal();
        if (memo[index][oddsRemaining][parityIdx] != -1) {
            return memo[index][oddsRemaining][parityIdx];
        }

        int minTransitions = Integer.MAX_VALUE / 2; // Avoid overflow on addition

        if (numbers[index] != 0) {
            // Case 1: Number is already provided
            Parity currentParity = (numbers[index] % 2 == 0) ? Parity.EVEN : Parity.ODD;
            int transitionCost = (lastParity != Parity.NONE && currentParity != lastParity) ? 1 : 0;

            minTransitions = transitionCost + computeMinTransitions(numbers, index + 1, oddsRemaining, currentParity, memo);
        } else {
            // Case 2: Number is a gap (0), try placing ODD
            if (oddsRemaining > 0) {
                int cost = (lastParity != Parity.NONE && lastParity != Parity.ODD) ? 1 : 0;
                minTransitions = Math.min(minTransitions, cost + computeMinTransitions(numbers, index + 1, oddsRemaining - 1, Parity.ODD, memo));
            }

            // Case 3: Number is a gap (0), try placing EVEN
            // We calculate if we can place an even based on the remaining slots and required odds
            int zerosRemaining = (numbers.length - index);
            int evensNeeded = (numbers.length - countNonZero(numbers)) - oddsRemaining; // conceptual
            // Simpler check: can we afford to place an even? 
            // We can place an even if the remaining slots can still satisfy the remaining odds.
            if (zerosRemaining > oddsRemaining) {
                int cost = (lastParity != Parity.NONE && lastParity != Parity.EVEN) ? 1 : 0;
                minTransitions = Math.min(minTransitions, cost + computeMinTransitions(numbers, index + 1, oddsRemaining, Parity.EVEN, memo));
            }
        }

        return memo[index][oddsRemaining][parityIdx] = minTransitions;
    }

    private int countNonZero(int[] arr) {
        int count = 0;
        for (int i : arr) if (i != 0) count++;
        return count;
    }

    /**
     * Utility class for efficient input reading.
     */
    private static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public int[] nextIntArray(int n) {
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }
    }
}

