import java.util.*;

/**
 * A program to find the minimum number of parity changes in a sequence
 * where some elements are unknown (represented by 0).
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int n = reader.nextInt();
            if (n <= 0) {
                writer.println(0);
            } else {
                int[] sequence = new int[n + 1];
                for (int i = 1; i <= n; i++) {
                    sequence[i] = reader.nextInt();
                }

                SequenceParitySolver solver = new SequenceParitySolver(n, sequence);
                writer.println(solver.solve());
            }
        } catch (Exception e) {
            // In a real-world production environment, use a logger.
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    /**
     * Solver class containing the dynamic programming logic.
     */
    static class SequenceParitySolver {
        private static final int INF = 1_000_000_000;

        private final int n;
        private final int[] sequence;

        public SequenceParitySolver(int n, int[] sequence) {
            this.n = n;
            this.sequence = sequence;
        }

        /**
         * Solves the problem using Dynamic Programming.
         * 
         * @return The minimum number of parity changes, or n + 1 if impossible.
         */
        public int solve() {
            boolean[] isPresent = new boolean[n + 1];
            int[] zeroCountPrefixSum = new int[n + 1];

            // Pre-process: identify present numbers and count zeros
            for (int i = 1; i <= n; i++) {
                if (sequence[i] > 0 && sequence[i] <= n) {
                    isPresent[sequence[i]] = true;
                }
                zeroCountPrefixSum[i] = zeroCountPrefixSum[i - 1] + (sequence[i] == 0 ? 1 : 0);
            }

            // Calculate how many even/odd numbers from the set {1...n} are missing
            int missingEvenCount = 0;
            int missingOddCount = 0;
            for (int i = 1; i <= n; i++) {
                if (!isPresent[i]) {
                    if (i % 2 == 0) {
                        missingEvenCount++;
                    } else {
                        missingOddCount++;
                    }
                }
            }

            // dp[index][evensUsedFromMissingSet][currentParity]
            // index: current position in the sequence (1 to n)
            // evensUsed: how many even numbers from the 'missing' set we've used
            // currentParity: 0 for even, 1 for odd
            int[][][] dp = new int[n + 1][missingEvenCount + 1][2];
            for (int i = 0; i <= n; i++) {
                for (int j = 0; j <= missingEvenCount; j++) {
                    Arrays.fill(dp[i][j], INF);
                }
            }

            // Base Case: Initialize the first element
            initializeFirstElement(dp, missingEvenCount, missingOddCount);

            // DP Transitions
            for (int i = 1; i < n; i++) {
                for (int j = 0; j <= missingEvenCount; j++) {
                    for (int currentParity = 0; currentParity < 2; currentParity++) {
                        if (dp[i][j][currentParity] == INF) {
                            continue;
                        }

                        if (sequence[i + 1] == 0) {
                            handleWildcard(dp, i, j, currentParity, missingEvenCount, missingOddCount, zeroCountPrefixSum);
                        } else {
                            handleFixedValue(dp, i, j, currentParity, sequence[i + 1]);
                        }
                    }
                }
            }

            return extractMinimumChanges(dp, missingEvenCount);
        }

        private void initializeFirstElement(int[][][] dp, int missingEvenCount, int missingOddCount) {
            if (sequence[1] == 0) {
                if (missingEvenCount > 0) dp[1][1][0] = 0;
                if (missingOddCount > 0) dp[1][0][1] = 0;
            } else {
                dp[1][0][sequence[1] % 2] = 0;
            }
        }

        private void handleWildcard(int[][][] dp, int i, int j, int currentParity, 
                                    int missingEvenCount, int missingOddCount, int[] zeroCountPrefixSum) {
            // Option 1: Fill wildcard with an even number from the missing set
            if (j + 1 <= missingEvenCount) {
                int cost = currentParity ^ 0;
                dp[i + 1][j + 1][0] = Math.min(dp[i + 1][j + 1][0], dp[i][j][currentParity] + cost);
            }

            // Option 2: Fill wildcard with an odd number from the missing set
            int oddsUsedSoFar = zeroCountPrefixSum[i] - j;
            if (oddsUsedSoFar + 1 <= missingOddCount) {
                int cost = currentParity ^ 1;
                dp[i + 1][j][1] = Math.min(dp[i + 1][j][1], dp[i][j][currentParity] + cost);
            }
        }

        private void handleFixedValue(int[][][] dp, int i, int j, int currentParity, int nextValue) {
            int nextParity = nextValue % 2;
            int cost = currentParity ^ nextParity;
            dp[i + 1][j][nextParity] = Math.min(dp[i + 1][j][nextParity], dp[i][j][currentParity] + cost);
        }

        private int extractMinimumChanges(int[][][] dp, int missingEvenCount) {
            int minChanges = n + 1;
            for (int j = 0; j <= missingEvenCount; j++) {
                minChanges = Math.min(minChanges, dp[n][j][0]);
                minChanges = Math.min(minChanges, dp[n][j][1]);
            }
            return minChanges;
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

