/**
 * SequenceSolver solves the problem of finding the minimum number of transitions 
 * (0 to 1 or 1 to 0) required to satisfy sequence constraints and parity counts.
 */
class SequenceSolver {
    private static final int INF = 1_000_000;

    /**
     * Reads input, computes the minimum transitions using dynamic programming,
     * and prints the result.
     *
     * @param reader The fast I/O reader.
     * @param writer The fast I/O writer.
     */
    public void solve(FastReader reader, PrintWriter writer) {
        int n = reader.nextInt();
        if (n <= 0) {
            writer.println(0);
            return;
        }

        // Target counts for 0s and 1s
        int targetZeros = n / 2;
        int targetOnes = (n + 1) / 2;

        // constraints[i] stores the required value at index i:
        // -1: Wildcard (can be 0 or 1)
        //  0: Must be 0
        //  1: Must be 1
        int[] constraints = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            int val = reader.nextInt();
            if (val == 0) {
                constraints[i] = -1; // Wildcard
            } else {
                constraints[i] = val % 2;
            }
        }

        // dp[i][j][lastVal]
        // i: number of elements processed (1 to n)
        // j: total number of 0s used so far
        // lastVal: the value of the i-th element (0 or 1)
        int[][][] dp = new int[n + 1][targetZeros + 1][2];

        // Initialize DP table with infinity
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= targetZeros; j++) {
                Arrays.fill(dp[i][j], INF);
            }
        }

        // Base case: At index 0, no transitions have occurred.
        // We initialize both lastVal states to 0 so the first element (i=1) 
        // doesn't incur a transition cost.
        dp[0][0][0] = 0;
        dp[0][0][1] = 0;

        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= targetZeros; j++) {
                int k = i - j; // Number of 1s used

                // Check if the current count of 1s is valid
                if (k < 0 || k > targetOnes) {
                    continue;
                }

                // Option 1: Set the i-th element to 0
                if (constraints[i] == -1 || constraints[i] == 0) {
                    if (j > 0) {
                        // Transition from previous 0 (no cost) or previous 1 (cost +1)
                        int fromZero = dp[i - 1][j - 1][0];
                        int fromOne = dp[i - 1][j - 1][1] + 1;
                        dp[i][j][0] = Math.min(fromZero, fromOne);
                    }
                }

                // Option 2: Set the i-th element to 1
                if (constraints[i] == -1 || constraints[i] == 1) {
                    if (k > 0) {
                        // Transition from previous 1 (no cost) or previous 0 (cost +1)
                        int fromOne = dp[i - 1][j][1];
                        int fromZero = dp[i - 1][j][0] + 1;
                        dp[i][j][1] = Math.min(fromOne, fromZero);
                    }
                }
            }
        }

        // The result is the minimum cost to reach the target counts ending in either 0 or 1
        int result = Math.min(dp[n][targetZeros][0], dp[n][targetZeros][1]);
        writer.println(result >= INF ? -1 : result);
    }
}

/**
 * FastReader provides a high-performance way to read integers from an InputStream.
 */
class FastReader {
    private final InputStream stream;
    private final byte[] buffer = new byte[1024];
    private int pointer = 0;
    private int bufferLength = 0;

    public FastReader(InputStream stream) {
        this.stream = stream;
    }

    private byte read() {
        if (pointer >= bufferLength) {
            pointer = 0;
            try {
                bufferLength = stream.read(buffer);
            } catch (IOException e) {
                return -1;
            }
            if (bufferLength <= 0) return -1;
        }
        return buffer[pointer++];
    }

    public int nextInt() {
        byte c = read();
        while (c != -1 && c <= 32) c = read(); // skip whitespace
        if (c == -1) return 0;

        int sign = 1;
        if (c == '-') {
            sign = -1;
            c = read();
        }

        int res = 0;
        while (c >= '0' && c <= '9') {
            res = res * 10 + (c - '0');
            c = read();
        }
        return res * sign;
    }
}

import java.util.*;

/**
 * A solution to calculate the minimum operations required to satisfy 
 * parity constraints within a given array.
 */
public class Solution {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int arraySize = scanner.nextInt();
        int[] numbers = new int[arraySize];

        for (int i = 0; i < arraySize; i++) {
            numbers[i] = scanner.nextInt();
        }

        System.out.println(calculateMinimumOperations(arraySize, numbers));
        scanner.close();
    }

    /**
     * Calculates the minimum number of operations required.
     * 
     * @param n       The size of the input array.
     * @param numbers The input array containing integers (0 represents a placeholder).
     * @return The total minimum operations required.
     */
    public static int calculateMinimumOperations(int n, int[] numbers) {
        Set<Integer> usedNumbers = new HashSet<>();
        List<Integer> nonZeroIndices = new ArrayList<>();

        // Identify all non-zero elements and their positions
        for (int i = 0; i < n; i++) {
            if (numbers[i] != 0) {
                usedNumbers.add(numbers[i]);
                nonZeroIndices.add(i);
            }
        }

        // Base case: If no elements are non-zero
        if (nonZeroIndices.isEmpty()) {
            return (n == 1) ? 0 : 1;
        }

        // Count available even and odd numbers from the set {1...n} that are not in the array
        int availableEvenCount = 0;
        int availableOddCount = 0;
        for (int i = 1; i <= n; i++) {
            if (!usedNumbers.contains(i)) {
                if (i % 2 == 0) {
                    availableEvenCount++;
                } else {
                    availableOddCount++;
                }
            }
        }

        int totalOperations = 0;
        List<Integer> evenParityGaps = new ArrayList<>();
        List<Integer> oddParityGaps = new ArrayList<>();

        // 1. Process gaps between adjacent non-zero elements
        for (int i = 1; i < nonZeroIndices.size(); i++) {
            int currentIndex = nonZeroIndices.get(i);
            int prevIndex = nonZeroIndices.get(i - 1);

            if (numbers[currentIndex] % 2 == numbers[prevIndex] % 2) {
                int gapSize = currentIndex - prevIndex - 1;
                if (numbers[currentIndex] % 2 == 0) {
                    evenParityGaps.add(gapSize);
                } else {
                    oddParityGaps.add(gapSize);
                }
            } else {
                // If parities alternate, no immediate operation needed for this pair
                totalOperations++;
            }
        }

        // Sort gaps to prioritize filling the smallest gaps first (Greedy approach)
        Collections.sort(evenParityGaps);
        Collections.sort(oddParityGaps);

        // 2. Resolve gaps between even numbers using available even numbers
        for (int gapSize : evenParityGaps) {
            if (availableEvenCount >= gapSize) {
                availableEvenCount -= gapSize;
            } else {
                totalOperations += 2;
            }
        }

        // 3. Resolve gaps between odd numbers using available odd numbers
        for (int gapSize : oddParityGaps) {
            if (availableOddCount >= gapSize) {
                availableOddCount -= gapSize;
            } else {
                totalOperations += 2;
            }
        }

        // 4. Handle the leading gap (from index 0 to the first non-zero element)
        int firstNonZeroIndex = nonZeroIndices.get(0);
        int leadingGapSize = firstNonZeroIndex;
        if (numbers[firstNonZeroIndex] % 2 == 0) {
            if (availableEvenCount >= leadingGapSize) {
                availableEvenCount -= leadingGapSize;
            } else {
                totalOperations += 1;
            }
        } else {
            if (availableOddCount >= leadingGapSize) {
                availableOddCount -= leadingGapSize;
            } else {
                totalOperations += 1;
            }
        }

        // 5. Handle the trailing gap (from the last non-zero element to the end)
        int lastNonZeroIndex = nonZeroIndices.get(nonZeroIndices.size() - 1);
        int trailingGapSize = n - 1 - lastNonZeroIndex;
        if (numbers[lastNonZeroIndex] % 2 == 0) {
            if (availableEvenCount >= trailingGapSize) {
                availableEvenCount -= trailingGapSize;
            } else {
                totalOperations += 1;
            }
        } else {
            if (availableOddCount >= trailingGapSize) {
                availableOddCount -= trailingGapSize;
            } else {
                totalOperations += 1;
            }
        }

        return totalOperations;
    }
}

import java.io.*;
import java.util.*;

/**
 * A solution to minimize parity transitions in a sequence by filling in blanks.
 */
public class Main {
    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int n = reader.nextInt();
            int[] sequence = reader.nextIntArray(n);

            ParityMinimizer solver = new ParityMinimizer(sequence);
            writer.println(solver.solve());
        } catch (Exception e) {
            // In competitive programming, we usually handle or ignore input errors.
        } finally {
            writer.close();
        }
    }

    /**
     * Core logic for solving the parity transition minimization problem.
     */
    static class ParityMinimizer {
        private static final int INF = 1_000_000_000;

        private final int[] sequence;
        private final int n;
        private final int[][][] memo;
        private final int[] suffixZeroCount;

        public ParityMinimizer(int[] sequence) {
            this.sequence = sequence;
            this.n = sequence.length;
            this.memo = new int[n + 1][n + 1][2];
            this.suffixZeroCount = new int[n + 1];

            // Precompute suffix sums of zeros to derive 'remainingOdd' from 'remainingEven'
            for (int i = n - 1; i >= 0; i--) {
                suffixZeroCount[i] = suffixZeroCount[i + 1] + (sequence[i] == 0 ? 1 : 0);
            }

            // Initialize memo table with -1
            for (int[][] layer : memo) {
                for (int[] row : layer) {
                    Arrays.fill(row, -1);
                }
            }
        }

        /**
         * Solves the problem by trying both possible starting parities to avoid
         * a transition cost on the very first element.
         */
        public int solve() {
            int[] availableParities = countMissingParities();
            int totalEven = availableParities[0];
            int totalOdd = availableParities[1];

            // We try starting with 'even' (0) and 'odd' (1) as a virtual previous parity.
            // The logic in computeMinTransitions ensures the first real element doesn't 
            // incur a penalty relative to this dummy state.
            int costIfStartedEven = computeMinTransitions(0, totalEven, 0);
            int costIfStartedOdd = computeMinTransitions(0, totalEven, 1);

            return Math.min(costIfStartedEven, costIfStartedOdd);
        }

        /**
         * Counts how many even and odd numbers from [1, n] are missing from the sequence.
         */
        private int[] countMissingParities() {
            boolean[] present = new boolean[n + 1];
            for (int val : sequence) {
                if (val != 0) {
                    present[val] = true;
                }
            }

            int evenCount = 0;
            int oddCount = 0;
            for (int i = 1; i <= n; i++) {
                if (!present[i]) {
                    if (i % 2 == 0) evenCount++;
                    else oddCount++;
                }
            }
            return new int[]{evenCount, oddCount};
        }

        /**
         * Recursive DP function with memoization.
         * 
         * @param idx            Current index in the sequence.
         * @param remainingEven  Count of even numbers available to fill blanks.
         * @param lastParity     Parity of the previous element (0 for even, 1 for odd).
         * @return Minimum transitions from this state.
         */
        private int computeMinTransitions(int idx, int remainingEven, int lastParity) {
            if (idx == n) {
                return 0;
            }

            if (memo[idx][remainingEven][lastParity] != -1) {
                return memo[idx][remainingEven][lastParity];
            }

            int result;
            if (sequence[idx] != 0) {
                // Element is fixed
                int currentParity = sequence[idx] % 2;
                int cost = (currentParity == lastParity) ? 0 : 1;

                // Special case: If it's the first element, we don't count transition from dummy parity.
                // However, the solve() method's min(0, 1) approach handles this.
                // But for idx 0, the cost is only added if the dummy parity differs.
                // To perfectly replicate original behavior:
                result = cost + computeMinTransitions(idx + 1, remainingEven, currentParity);

                // Correction for index 0: the original logic treats the first element 
                // as having no transition cost if we pick the 'matching' dummy parity.
                // The solve() method handles this.
            } else {
                // Element is a blank (0)
                result = INF;
                int remainingOdd = suffixZeroCount[idx] - remainingEven;

                // Option 1: Place an even number
                if (remainingEven > 0) {
                    int cost = (lastParity == 1) ? 1 : 0;
                    result = Math.min(result, cost + computeMinTransitions(idx + 1, remainingEven - 1, 0));
                }

                // Option 2: Place an odd number
                if (remainingOdd > 0) {
                    int cost = (lastParity == 0) ? 1 : 0;
                    result = Math.min(result, cost + computeMinTransitions(idx + 1, remainingEven, 1));
                }
            }

            return memo[idx][remainingEven][lastParity] = result;
        }
    }

    /**
     * High-performance input reader for large datasets.
     */
    static class FastReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int curChar;
        private int numChars;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (numChars == -1) return -1;
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buffer);
                } catch (IOException e) {
                    return -1;
                }
                if (numChars <= 0) return -1;
            }
            return buffer[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isWhitespace(c)) c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') break;
                res = res * 10 + (c - '0');
                c = read();
            } while (!isWhitespace(c));
            return res * sgn;
        }

        public int[] nextIntArray(int size) {
            int[] array = new int[size];
            for (int i = 0; i < size; i++) {
                array[i] = nextInt();
            }
            return array;
        }

        private boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

