/**
 * A solution to minimize the number of parity changes in an array 
 * by filling zero-valued positions with even or odd numbers.
 */
public class ParityMinimizer {

    private static final int INF = 1_000_000_000;
    private static final int EVEN = 0;
    private static final int ODD = 1;

    private final int[] inputArray;
    private final int n;
    private final int[][][][] memo;

    public ParityMinimizer(int n, int[] inputArray) {
        this.n = n;
        this.inputArray = inputArray;
        // memo[index][evenRemaining][oddRemaining][previousParity]
        this.memo = new int[n + 1][n + 1][n + 1][2];
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                for (int k = 0; k <= n; k++) {
                    Arrays.fill(memo[i][j][k], -1);
                }
            }
        }
    }

    /**
     * Solves the problem using dynamic programming with memoization.
     * 
     * @param index Current index in the array being processed.
     * @param evenRemaining Number of even numbers still needed to be placed in zero slots.
     * @param oddRemaining Number of odd numbers still needed to be placed in zero slots.
     * @param prevParity The parity of the previous element (0 for even, 1 for odd).
     * @return The minimum number of parity changes from this state to the end.
     */
    private int computeMinParityChanges(int index, int evenRemaining, int oddRemaining, int prevParity) {
        if (index == n) {
            return 0;
        }

        if (memo[index][evenRemaining][oddRemaining][prevParity] != -1) {
            return memo[index][evenRemaining][oddRemaining][prevParity];
        }

        int result;

        if (inputArray[index] != 0) {
            // Element is pre-filled
            int currentParity = Math.abs(inputArray[index] % 2);
            int cost = (index > 0 && currentParity != prevParity) ? 1 : 0;
            result = computeMinParityChanges(index + 1, evenRemaining, oddRemaining, currentParity) + cost;
        } else {
            // Element is 0, we must decide whether to place an even or odd number
            result = INF;

            // Option 1: Place an even number
            if (evenRemaining > 0) {
                int cost = (index > 0 && prevParity != EVEN) ? 1 : 0;
                int subProblem = computeMinParityChanges(index + 1, evenRemaining - 1, oddRemaining, EVEN);
                if (subProblem != INF) {
                    result = Math.min(result, subProblem + cost);
                }
            }

            // Option 2: Place an odd number
            if (oddRemaining > 0) {
                int cost = (index > 0 && prevParity != ODD) ? 1 : 0;
                int subProblem = computeMinParityChanges(index + 1, evenRemaining, oddRemaining - 1, ODD);
                if (subProblem != INF) {
                    result = Math.min(result, subProblem + cost);
                }
            }
        }

        return memo[index][evenRemaining][oddRemaining][prevParity] = result;
    }

    public int solve() {
        // We start with prevParity = 0, but the cost logic handles index 0 correctly
        return computeMinParityChanges(0, 0, 0, EVEN); // This is a placeholder; logic is called below
    }

    public static void main(String[] args) {
        // Increase stack size for deep recursion using a new Thread
        Thread solverThread = new Thread(null, () -> {
            try {
                run();
            } catch (Exception e) {
                e.printStackTrace();
            }
        }, "SolverThread", 1 << 28);
        solverThread.start();
    }

    private static void run() throws IOException {
        InputReader sc = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = sc.nextInt();
        int[] arr = new int[n];

        int totalTargetOdd = (n + 1) / 2;
        int totalTargetEven = n / 2;

        int currentOddCount = 0;
        int currentEvenCount = 0;

        for (int i = 0; i < n; i++) {
            arr[i] = sc.nextInt();
            if (arr[i] != 0) {
                if (Math.abs(arr[i] % 2) == 1) {
                    currentOddCount++;
                } else {
                    currentEvenCount++;
                }
            }
        }

        // The number of zeros we must fill with odds/evens
        int requiredOddCount = totalTargetOdd - currentOddCount;
        int requiredEvenCount = totalTargetEven - currentEvenCount;

        ParityMinimizer solver = new ParityMinimizer(n, arr);

        // Re-running the calculation with correct initial remaining counts
        // We bypass the dummy solve() and call the logic directly via a wrapper or specialized method
        // For clean refactoring, we define the entry logic in the constructor or a specific start method.
        // Here, we'll use a simplified approach:
        int result = solver.computeMinParityChanges(0, requiredEvenCount, requiredOddCount, EVEN);

        // If index 0 is odd, the very first parity check shouldn't count as a change.
        // The original logic `(idx > 0 ? ... : 0)` handles this.
        // However, if the first element is 0, we need to ensure it doesn't cost 1 if we pick ODD.
        // The original code handles this by checking `idx > 0`.

        out.println(result);
        out.flush();
        out.close();
    }

    /**
     * Fast I/O utility class.
     */
    static class InputReader {
        private final DataInputStream din;
        private final byte[] buffer = new byte[1 << 16];
        private int bufferPointer, bytesRead;

        public InputReader(InputStream in) {
            din = new DataInputStream(in);
        }

        public int nextInt() throws IOException {
            int ret = 0;
            byte c = read();
            while (c <= ' ') c = read();
            boolean neg = (c == '-');
            if (neg) c = read();
            do {
                ret = ret * 10 + c - '0';
            } while ((c = read()) >= '0' && c <= '9');
            return neg ? -ret : ret;
        }

        private void fillBuffer() throws IOException {
            bytesRead = din.read(buffer, bufferPointer = 0, buffer.length);
            if (bytesRead == -1) buffer[0] = -1;
        }

        private byte read() throws IOException {
            if (bufferPointer == bytesRead) fillBuffer();
            return buffer[bufferPointer++];
        }
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;
import java.util.Arrays;

/**
 * A class to solve the sequence cost minimization problem using Dynamic Programming.
 * The goal is to replace wildcard elements (0) with either odd (1) or even (2) numbers
 * such that the sum of absolute differences between adjacent elements is minimized,
 * while maintaining a specific count of odd and even numbers.
 */
public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int n = scanner.nextInt();
        List<Integer> inputSequence = new ArrayList<>();

        // The problem implies a target distribution: 
        // (n+1)/2 odd numbers and n/2 even numbers.
        int remainingOddBudget = (n + 1) / 2;
        int remainingEvenBudget = n / 2;

        for (int i = 0; i < n; i++) {
            int inputVal = scanner.nextInt();
            if (inputVal == 0) {
                // 0 represents a wildcard that must be filled later
                inputSequence.add(SequenceCostOptimizer.TYPE_WILDCARD);
            } else if (inputVal % 2 != 0) {
                // An odd number is provided
                remainingOddBudget--;
                inputSequence.add(SequenceCostOptimizer.TYPE_ODD);
            } else {
                // An even number is provided
                remainingEvenBudget--;
                inputSequence.add(SequenceCostOptimizer.TYPE_EVEN);
            }
        }

        SequenceCostOptimizer optimizer = new SequenceCostOptimizer(inputSequence, remainingOddBudget, remainingEvenBudget);
        System.out.println(optimizer.solve());

        scanner.close();
    }
}

class SequenceCostOptimizer {
    public static final int TYPE_WILDCARD = 0;
    public static final int TYPE_ODD = 1;
    public static final int TYPE_EVEN = 2;
    private static final int INF = 1_000_000_000;

    private final List<Integer> sequence;
    private final int totalElements;
    private final int initialOddBudget;
    private final int initialEvenBudget;

    // Memoization table: [index][remaining_odds][remaining_evens][last_value]
    private final int[][][][] memo;

    public SequenceCostOptimizer(List<Integer> sequence, int oddBudget, int evenBudget) {
        this.sequence = sequence;
        this.totalElements = sequence.size();
        this.initialOddBudget = oddBudget;
        this.initialEvenBudget = evenBudget;

        // Size 102 to accommodate n up to 100 safely
        this.memo = new int[totalElements + 1][oddBudget + 1][evenBudget + 1][3];
        for (int[][][] dim1 : memo) {
            for (int[][] dim2 : dim1) {
                for (int[] dim3 : dim2) {
                    Arrays.fill(dim3, -1);
                }
            }
        }
    }

    /**
     * Entry point for the optimization solver.
     * @return The minimum possible sum of absolute differences.
     */
    public int solve() {
        // Initial call: index 0, full budgets, and last value is 0 (neutral for first element)
        return calculateMinimumCost(0, initialOddBudget, initialEvenBudget, 0);
    }

    /**
     * Recursive function with memoization to find the minimum cost.
     *
     * @param index          Current position in the sequence.
     * @param oddBudget      Remaining count of odd numbers we can use to fill wildcards.
     * @param evenBudget     Remaining count of even numbers we can use to fill wildcards.
     * @param lastValue      The type (1 or 2) of the previous element in the sequence.
     * @return               The minimum cost from this state to the end.
     */
    private int calculateMinimumCost(int index, int oddBudget, int evenBudget, int lastValue) {
        // Base case: reached the end of the sequence
        if (index == totalElements) {
            return 0;
        }

        // Check memoization table
        if (memo[index][oddBudget][evenBudget][lastValue] != -1) {
            return memo[index][oddBudget][evenBudget][lastValue];
        }

        int currentType = sequence.get(index);
        int minCost = INF;

        if (currentType == TYPE_WILDCARD) {
            // Option 1: Treat wildcard as an Odd number
            if (oddBudget > 0) {
                int costToTransition = (index == 0) ? 0 : Math.abs(lastValue - TYPE_ODD);
                int total = costToTransition + calculateMinimumCost(index + 1, oddBudget - 1, evenBudget, TYPE_ODD);
                minCost = Math.min(minCost, total);
            }

            // Option 2: Treat wildcard as an Even number
            if (evenBudget > 0) {
                int costToTransition = (index == 0) ? 0 : Math.abs(lastValue - TYPE_EVEN);
                int total = costToTransition + calculateMinimumCost(index + 1, oddBudget, evenBudget - 1, TYPE_EVEN);
                minCost = Math.min(minCost, total);
            }
        } else {
            // The current type is fixed (either Odd or Even)
            int costToTransition = (index == 0) ? 0 : Math.abs(lastValue - currentType);
            minCost = costToTransition + calculateMinimumCost(index + 1, oddBudget, evenBudget, currentType);
        }

        memo[index][oddBudget][evenBudget][lastValue] = minCost;
        return minCost;
    }
}

import java.io.*;
import java.util.*;

/**
 * This program finds the minimum number of transitions (flips) required to fill 
 * wildcards in an array such that the final array satisfies a specific count 
 * of 0s and 1s.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            int n = reader.nextInt();
            if (n <= 0) {
                writer.println(0);
            } else if (n == 1) {
                // For a single element, there are 0 transitions regardless of the value.
                // We must still consume the input.
                reader.nextInt(); 
                writer.println(0);
            } else {
                solve(n, reader, writer);
            }
        } catch (Exception e) {
            // Handle or log exception
        } finally {
            writer.close();
        }
    }

    private static void solve(int n, FastReader reader, PrintWriter writer) {
        int[] elements = new int[n];

        // The problem defines the required counts based on the length n.
        // Total 1s: (n+1)/2, Total 0s: n/2
        int targetZero = n / 2;
        int targetOne = (n + 1) / 2;

        int budgetZero = targetZero;
        int budgetOne = targetOne;

        for (int i = 0; i < n; i++) {
            int val = reader.nextInt();
            if (val == 0) {
                // Input 0 represents a wildcard
                elements[i] = -1;
            } else {
                // Input non-zero represents a fixed bit (val % 2)
                int bit = val & 1;
                elements[i] = bit;
                if (bit == 1) {
                    budgetOne--;
                } else {
                    budgetZero--;
                }
            }
        }

        Solver solver = new Solver(n, elements, budgetZero, budgetOne);
        writer.println(solver.getMinimumTransitions());
    }

    /**
     * Solver encapsulates the Dynamic Programming logic.
     */
    static class Solver {
        private final int n;
        private final int[] elements;
        private final int initialBudgetZero;
        private final int initialBudgetOne;
        private final int[][][] memo;
        private final int[] wildcardsRemaining;
        private static final int INF = 1_000_000_007;

        public Solver(int n, int[] elements, int budgetZero, int budgetOne) {
            this.n = n;
            this.elements = elements;
            this.initialBudgetZero = budgetZero;
            this.initialBudgetOne = budgetOne;

            // State: [current_index][remaining_zero_budget][previous_value]
            // Space complexity: O(N^2)
            this.memo = new int[n + 1][budgetZero + 1][2];
            for (int[][] layer : memo) {
                for (int[] row : layer) {
                    Arrays.fill(row, -1);
                }
            }

            // Pre-calculate suffix sums of wildcards to derive budgetOne in O(1)
            this.wildcardsRemaining = new int[n + 1];
            int count = 0;
            for (int i = n - 1; i >= 0; i--) {
                if (elements[i] == -1) {
                    count++;
                }
                wildcardsRemaining[i] = count;
            }
        }

        /**
         * Returns the minimum transitions by trying both possible starting dummy values.
         */
        public int getMinimumTransitions() {
            return Math.min(compute(0, initialBudgetZero, 0), 
                            compute(0, initialBudgetZero, 1));
        }

        private int compute(int idx, int b0, int prev) {
            if (idx == n) {
                return 0;
            }

            if (memo[idx][b0][prev] != -1) {
                return memo[idx][b0][prev];
            }

            int result = INF;

            if (elements[idx] != -1) {
                // Element is fixed.
                int val = elements[idx];
                int transitionCost = (val == prev) ? 0 : 1;
                result = transitionCost + compute(idx + 1, b0, val);
            } else {
                // Element is a wildcard. We decide to place 0 or 1.
                // Calculate current budget for 1s based on wildcards remaining.
                int b1 = wildcardsRemaining[idx] - b0;

                // Option 1: Place a 0
                if (b0 > 0) {
                    int transitionCost = (prev == 1) ? 1 : 0;
                    result = Math.min(result, transitionCost + compute(idx + 1, b0 - 1, 0));
                }

                // Option 2: Place a 1
                if (b1 > 0) {
                    int transitionCost = (prev == 0) ? 1 : 0;
                    result = Math.min(result, transitionCost + compute(idx + 1, b0, 1));
                }
            }

            return memo[idx][b0][prev] = result;
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

