            }

            int[] parity = new int[n + 1];
            // targetEvens[0] is the target count for even numbers, targetEvens[1] for odd.
            int[] targetCounts = {n / 2, n - n / 2};

            for (int i = 1; i <= n; i++) {
                int x = in.readInt();
                parity[i] = x;
                if (x != 0) {
                    // If the parity is already fixed, decrement the requirement for that parity
                    targetCounts[x % 2]--;
                }
            }

            // dp[i][j][k]
            // i: number of elements processed
            // j: number of '0' (unknown) elements assigned to even parity
            // k: parity of the i-th element (0 for even, 1 for odd)
            int[][][] dp = new int[n + 1][n + 1][2];
            for (int i = 0; i <= n; i++) {
                for (int j = 0; j <= n; j++) {
                    Arrays.fill(dp[i][j], INF);
                }
            }

            // Base case: 0 elements processed, 0 unknowns used as even, cost is 0
            dp[0][0][0] = 0;
            dp[0][0][1] = 0;

            for (int i = 1; i <= n; i++) {
                int x = parity[i];
                for (int j = 0; j <= n; j++) {
                    for (int k = 0; k < 2; k++) {
                        if (x == 0) {
                            // Case: Element is unknown
                            if (k == 0) { 
                                // Assign as even: requires using one 'j' slot
                                if (j > 0) {
                                    dp[i][j][0] = Math.min(dp[i - 1][j - 1][0], dp[i - 1][j - 1][1] + 1);
                                }
                            } else { 
                                // Assign as odd: 'j' (even count) does not increase
                                dp[i][j][1] = Math.min(dp[i - 1][j][1], dp[i - 1][j][0] + 1);
                            }
                        } else {
                            // Case: Element is fixed
                            if (x % 2 == k) {
                                // Parity matches, no flip cost
                                dp[i][j][k] = Math.min(dp[i][j][k], dp[i - 1][j][k]);
                                // Parity was opposite, flip cost +1
                                dp[i][j][k] = Math.min(dp[i][j][k], dp[i - 1][j][1 - k] + 1);
                            }
                        }
                    }
                }
            }

            int targetEvens = targetCounts[0];
            int result = Math.min(dp[n][targetEvens][0], dp[n][targetEvens][1]);
            out.println(result);
        }
    }

    /**
     * High-performance reader for fast integer input.
     */
    static class FastReader implements AutoCloseable {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 13];
        private int pointer = 0;
        private int bufferLength = 0;
        private int nextByte;

        public FastReader(InputStream in) throws IOException {
            this.in = in;
            this.nextByte = read();
        }

        private int read() throws IOException {
            if (pointer >= bufferLength) {
                pointer = 0;
                bufferLength = in.read(buffer);
                if (bufferLength <= 0) return -1;
            }
            return buffer[pointer++] & 0xFF;
        }

        public int readInt() throws IOException {
            int c = nextByte;
            while (c != -1 && c <= 32) c = read();
            if (c == -1) return 0;

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            } else if (c == '+') {
                c = read();
            }

            int res = 0;
            while (c >= '0' && c <= '9') {
                res = res * 10 + (c - '0');
                c = read();
            }
            nextByte = c;
            return res * sign;
        }

        @Override
        public void close() throws IOException {
            in.close();
        }
    }

    /**
     * High-performance writer for efficient output.
     */
    static class FastWriter implements AutoCloseable {
        private final PrintWriter writer;

        public FastWriter(OutputStream out) {
            this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(out)));
        }

        public void println(int val) {
            writer.println(val);
        }

        @Override
        public void close() {
            writer.flush();
            writer.close();
        }
    }
}

import java.io.*;
import java.nio.charset.Charset;
import java.util.*;
import java.util.stream.IntStream;

/**
 * Refactored version of the Garland solver.
 * Improved maintainability, variable naming, and performance of utility methods.
 */
public class Main {

    public static void main(String[] args) {
        try (FastReader reader = new FastReader(System.in);
             FastWriter writer = new FastWriter(System.out)) {

            GarlandSolver solver = new GarlandSolver();
            solver.solve(reader, writer);

        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /**
     * Solves the Garland problem using dynamic programming.
     */
    static class GarlandSolver {

        private static final int INF = 1_000_000;

        public void solve(FastReader in, FastWriter out) throws IOException {
            int n = in.nextInt();
            if (n <= 0) {
                out.println(0);
                return;
            }

            int[] inputElements = in.nextIntArray(n);
            boolean[] isIndexFixedByValue = new boolean[n];

            // Determine which indices are "fixed" based on the input values
            for (int value : inputElements) {
                if (value != 0) {
                    isIndexFixedByValue[value - 1] = true;
                }
            }

            // Count required even/odd parity slots based on fixed index availability
            int targetEvenCount = 0;
            int targetOddCount = 0;
            for (int i = 0; i < n; i++) {
                if (isIndexFixedByValue[i]) {
                    continue;
                }
                // Logic follows original: even indices are treated as 'odd' and vice versa
                if (i % 2 == 0) {
                    targetOddCount++;
                } else {
                    targetEvenCount++;
                }
            }

            // dp[parity][index][evenCount][oddCount]
            // parity: 0 for even, 1 for odd
            int[][][][] dp = new int[2][n + 1][n + 1][n + 1];

            // Initialize DP table with a large value
            for (int p = 0; p < 2; p++) {
                for (int i = 0; i <= n; i++) {
                    for (int e = 0; e <= n; e++) {
                        Arrays.fill(dp[p][i][e], INF);
                    }
                }
            }

            // Base case: 0 elements processed, 0 even, 0 odd, cost 0
            dp[0][0][0][0] = 0;
            dp[1][0][0][0] = 0;

            for (int i = 0; i < n; i++) {
                int fixedParity = inputElements[i] % 2;

                if (inputElements[i] == 0) {
                    // Case 1: Current element is flexible (0)
                    for (int odd = 0; odd <= n; odd++) {
                        for (int even = 0; even <= n; even++) {
                            // Option A: Assign Even parity (0)
                            if (even + 1 <= n) {
                                int costFromEven = dp[0][i][even][odd];
                                int costFromOdd = dp[1][i][even][odd] + 1;
                                dp[0][i + 1][even + 1][odd] = Math.min(dp[0][i + 1][even + 1][odd], Math.min(costFromEven, costFromOdd));
                            }
                            // Option B: Assign Odd parity (1)
                            if (odd + 1 <= n) {
                                int costFromEven = dp[0][i][even][odd] + 1;
                                int costFromOdd = dp[1][i][even][odd];
                                dp[1][i + 1][even][odd + 1] = Math.min(dp[1][i + 1][even][odd + 1], Math.min(costFromEven, costFromOdd));
                            }
                        }
                    }
                } else {
                    // Case 2: Current element is fixed to a specific parity
                    for (int even = 0; even <= n; even++) {
                        for (int odd = 0; odd <= n; odd++) {
                            int costFromSame = dp[fixedParity][i][even][odd];
                            int costFromDiff = dp[1 - fixedParity][i][even][odd] + 1;
                            dp[fixedParity][i + 1][even][odd] = Math.min(dp[fixedParity][i + 1][even][odd], Math.min(costFromSame, costFromDiff));
                        }
                    }
                }
            }

            int result = Math.min(dp[0][n][targetEvenCount][targetOddCount], 
                                  dp[1][n][targetEvenCount][targetOddCount]);
            out.printAns(result).println();
        }
    }

    /**
     * Fast I/O reader for efficient integer and string processing.
     */
    static class FastReader implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream in) {
            this.reader = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public int[] nextIntArray(int length) {
            int[] array = new int[length];
            for (int i = 0; i < length; i++) {
                array[i] = nextInt();
            }
            return array;
        }

        @Override
        public void close() throws IOException {
            reader.close();
        }
    }

    /**
     * Fast I/O writer with support for space-separated outputs.
     */
    static class FastWriter implements AutoCloseable {
        private final Writer writer;
        private boolean needsSpace = true;

        public FastWriter(OutputStream out) {
            this.writer = new OutputStreamWriter(new BufferedOutputStream(out), Charset.defaultCharset());
        }

        public FastWriter printAns(int value) throws IOException {
            return printAns(String.valueOf(value));
        }

        public FastWriter printAns(String s) throws IOException {
            if (!needsSpace) {
                writer.write(" ");
            }
            writer.write(s);
            needsSpace = false;
            return this;
        }

        public FastWriter println() throws IOException {
            writer.write(System.lineSeparator());
            needsSpace = true;
            writer.flush();
            return this;
        }

        @Override
        public void close() throws IOException {
            writer.close();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.StringTokenizer;

/**
 * The Garland class serves as the entry point for the application.
 * It coordinates the input reading and triggers the solution process.
 */
public class Garland {

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        try {
            int sequenceLength = reader.nextInt();
            int[] sequence = reader.nextIntArray(sequenceLength);

            GarlandSolver solver = new GarlandSolver();
            int minTransitions = solver.solve(sequenceLength, sequence);

            System.out.println(minTransitions);
        } catch (Exception e) {
            // In a production environment, use a logging framework
            System.err.println("An error occurred during execution: " + e.getMessage());
        }
    }

    /**
     * Contains the core logic for solving the Garland problem using Dynamic Programming.
     */
    private static class GarlandSolver {
        private static final int EVEN = 0;
        private static final int ODD = 1;
        private static final int INF = Integer.MAX_VALUE / 2;

        /**
         * Orchestrates the calculation of missing numbers and the DP solution.
         * 
         * @param n The length of the sequence.
         * @param sequence The input array of integers.
         * @return The minimum number of parity transitions.
         */
        public int solve(int n, int[] sequence) {
            MissingCounts counts = calculateMissingCounts(n, sequence);
            return computeMinTransitions(n, sequence, counts.oddCount, counts.evenCount);
        }

        /**
         * Identifies which numbers from 1 to n are missing from the input sequence.
         */
        private MissingCounts calculateMissingCounts(int n, int[] sequence) {
            boolean[] isNumberPresent = new boolean[n + 1];
            for (int val : sequence) {
                // 0 is a wildcard and not a number from the 1..n range
                if (val >= 1 && val <= n) {
                    isNumberPresent[val] = true;
                }
            }

            int oddCount = 0;
            int evenCount = 0;
            for (int i = 1; i <= n; i++) {
                if (!isNumberPresent[i]) {
                    if (i % 2 == 0) {
                        evenCount++;
                    } else {
                        oddCount++;
                    }
                }
            }
            return new MissingCounts(oddCount, evenCount);
        }

        /**
         * Performs the Dynamic Programming to find the minimum cost.
         * 
         * DP State: dp[i][j][k][parity]
         * i: elements processed so far
         * j: count of missing odd numbers used
         * k: count of missing even numbers used
         * parity: the parity of the i-th element (0 for even, 1 for odd)
         */
        private int computeMinTransitions(int n, int[] sequence, int missingOdd, int missingEven) {
            int[][][][] dp = new int[n + 1][missingOdd + 1][missingEven + 1][2];

            // Initialize DP table with infinity
            for (int i = 0; i <= n; i++) {
                for (int j = 0; j <= missingOdd; j++) {
                    for (int k = 0; k <= missingEven; k++) {
                        Arrays.fill(dp[i][j][k], INF);
                    }
                }
            }

            // Base case: before any elements are processed, no cost is incurred.
            // We set both parities to 0 to allow the first element to pick any parity without a "transition" cost.
            dp[0][0][0][EVEN] = 0;
            dp[0][0][0][ODD] = 0;

            for (int i = 1; i <= n; i++) {
                int currentValue = sequence[i - 1];

                for (int j = 0; j <= missingOdd; j++) {
                    for (int k = 0; k <= missingEven; k++) {
                        if (currentValue == 0) {
                            // Case 1: Wildcard (0). We can choose to treat it as a missing odd or even number.

                            // Option: Treat as Odd
                            if (j >= 1) {
                                dp[i][j][k][ODD] = Math.min(dp[i - 1][j - 1][k][EVEN] + 1, 
                                                            dp[i - 1][j - 1][k][ODD]);
                            }
                            // Option: Treat as Even
                            if (k >= 1) {
                                dp[i][j][k][EVEN] = Math.min(dp[i - 1][j][k - 1][EVEN], 
                                                             dp[i - 1][j][k - 1][ODD] + 1);
                            }
                        } else {
                            // Case 2: Fixed value. We must respect the value's parity.
                            if (currentValue % 2 == 0) {
                                // Value is even: parity is 0. Transition cost is 1 if previous was odd.
                                dp[i][j][k][EVEN] = Math.min(dp[i - 1][j][k][EVEN], 
                                                             dp[i - 1][j][k][ODD] + 1);
                            } else {
                                // Value is odd: parity is 1. Transition cost is 1 if previous was even.
                                dp[i][j][k][ODD] = Math.min(dp[i - 1][j][k][ODD], 
                                                            dp[i - 1][j][k][EVEN] + 1);
                            }
                        }
                    }
                }
            }

            return Math.min(dp[n][missingOdd][missingEven][EVEN], 
                            dp[n][missingOdd][missingEven][ODD]);
        }

        /**
         * Small data carrier for missing number counts.
         */
        private static class MissingCounts {
            final int oddCount;
            final int evenCount;

            MissingCounts(int oddCount, int evenCount) {
                this.oddCount = oddCount;
                this.evenCount = evenCount;
            }
        }
    }

    /**
     * Utility class for high-performance input reading.
     */
    private static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader() {
            reader = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public int[] nextIntArray(int n) {
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver for finding the minimum number of parity transitions in a sequence
 * given a fixed number of required odd and even elements.
 */
public class Main {
    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        ParitySolver solver = new ParitySolver();
        solver.solve(reader, writer);

        writer.flush();
        writer.close();
    }

    static class ParitySolver {
        private static final int EVEN = 0;
        private static final int ODD = 1;
        private static final int UNKNOWN = -1;
        private static final int AMBIGUOUS = 3;

        // Result stores the minimum transitions from this state and the parity chosen at this step.
        private static class Result {
            final int minTransitions;
            final int parity;

            Result(int minTransitions, int parity) {
                this.minTransitions = minTransitions;
                this.parity = parity;
            }
        }

        private Result[][][] memo;

        public void solve(FastReader reader, PrintWriter writer) {
            int n = reader.nextInt();
            int[] originalArray = reader.nextIntArray(n);

            // The target number of odd and even elements
            int targetOdd = (n + 1) / 2;
            int targetEven = n / 2;

            int[] parities = new int[n];
            int currentOdd = 0;
            int currentEven = 0;

            // Map input to parity values: 0 (even), 1 (odd), -1 (wildcard)
            for (int i = 0; i < n; i++) {
                if (originalArray[i] == 0) {
                    parities[i] = UNKNOWN;
                } else if (originalArray[i] % 2 == 0) {
                    parities[i] = EVEN;
                    currentEven++;
                } else {
                    parities[i] = ODD;
                    currentOdd++;
                }
            }

            // Calculate how many more odd/even elements we need to satisfy target requirements
            // using only the wildcard slots.
            int requiredOddWildcards = targetOdd - currentOdd;
            int requiredEvenWildcards = targetEven - currentEven;

            memo = new Result[requiredOddWildcards + 1][requiredEvenWildcards + 1][n];

            Result finalResult = computeMinTransitions(requiredOddWildcards, requiredEvenWildcards, 0, parities);
            writer.println(finalResult.minTransitions);
        }

        /**
         * Recursive DP function with memoization.
         * 
         * @param remOdd Wildcards remaining that must be turned into ODD.
         * @param remEven Wildcards remaining that must be turned into EVEN.
         * @param pos The current index in the array.
         * @param parities The parity map of the original array.
         * @return Result containing min transitions and the parity chosen at the current position.
         */
        private Result computeMinTransitions(int remOdd, int remEven, int pos, int[] parities) {
            int n = parities.length;

            // Base case: Last element
            if (pos == n - 1) {
                if (parities[pos] != UNKNOWN) {
                    return new Result(0, parities[pos]);
                } else {
                    // If wildcard, it must satisfy the remaining budget
                    int forcedParity = (remEven > 0) ? EVEN : ODD;
                    return new Result(0, forcedParity);
                }
            }

            if (memo[remOdd][remEven][pos] != null) {
                return memo[remOdd][remEven][pos];
            }

            Result best;

            if (parities[pos] != UNKNOWN) {
                // Case 1: Current element's parity is fixed.
                int current = parities[pos];
                // Fixed elements don't consume the "wildcard budget".
                Result next = computeMinTransitions(remOdd, remEven, pos + 1, parities);

                int transitionCost = (next.parity == current || next.parity == AMBIGUOUS) ? 0 : 1;
                best = new Result(next.minTransitions + transitionCost, current);
            } else {
                // Case 2: Current element is a wildcard. We can choose ODD or EVEN.
                Result resOdd = null;
                if (remOdd > 0) {
                    Result next = computeMinTransitions(remOdd - 1, remEven, pos + 1, parities);
                    int cost = next.minTransitions + (next.parity == ODD || next.parity == AMBIGUOUS ? 0 : 1);
                    resOdd = new Result(cost, ODD);
                }

                Result resEven = null;
                if (remEven > 0) {
                    Result next = computeMinTransitions(remOdd, remEven - 1, pos + 1, parities);
                    int cost = next.minTransitions + (next.parity == EVEN || next.parity == AMBIGUOUS ? 0 : 1);
                    resEven = new Result(cost, EVEN);
                }

                // Compare the outcomes of choosing ODD vs EVEN
                if (resOdd != null && resEven != null) {
                    if (resOdd.minTransitions < resEven.minTransitions) {
                        best = resOdd;
                    } else if (resEven.minTransitions < resOdd.minTransitions) {
                        best = resEven;
                    } else {
                        // If both choices lead to the same transition count, we mark as AMBIGUOUS
                        best = new Result(resOdd.minTransitions, AMBIGUOUS);
                    }
                } else {
                    best = (resOdd != null) ? resOdd : resEven;
                }
            }

            return memo[remOdd][remEven][pos] = best;
        }
    }

    /**
     * Utility class for high-performance input reading.
     */
    static class FastReader {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (numChars == -1) throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) return -1;
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isWhitespace(c)) c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res = res * 10 + (c - '0');
                c = read();
            } while (!isWhitespace(c));
            return res * sgn;
        }

        public int[] nextIntArray(int n) {
            int[] array = new int[n];
            for (int i = 0; i < n; i++) {
                array[i] = nextInt();
            }
            return array;
        }

        private boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.util.Scanner;

/**
 * ParityMinimizer solves the problem of minimizing parity changes in an array
 * where some elements are fixed and others are wildcards (zeros).
 */
public class ParityMinimizer {

    private static final int INF = 1_000_000_007;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int totalElements = scanner.nextInt();
        int[] elements = new int[totalElements + 1]; // 1-based indexing to match original logic

        for (int i = 1; i <= totalElements; i++) {
            elements[i] = scanner.nextInt();
        }

        int result = solve(totalElements, elements);
        System.out.println(result);

        scanner.close();
    }

    /**
     * Computes the minimum number of parity changes required to satisfy the 
     * even/odd distribution requirements.
     *
     * @param n       Total number of elements in the array.
     * @param p       The array of elements (1-indexed).
     * @return        The minimum number of parity transitions.
     */
    public static int solve(int n, int[] p) {
        // Initial target counts based on total elements
        int targetEvenCount = n / 2;
        int targetOddCount = (n + 1) / 2;

        // m and k represent the number of zeros that MUST be turned into evens or odds
        int evenZerosNeeded = targetEvenCount;
        int oddZerosNeeded = targetOddCount;

        for (int i = 1; i <= n; i++) {
            if (p[i] > 0) {
                if (p[i] % 2 == 0) {
                    evenZerosNeeded--;
                } else {
                    oddZerosNeeded--;
                }
            }
        }

        // Ensure we don't have negative requirements due to existing numbers
        evenZerosNeeded = Math.max(0, evenZerosNeeded);
        oddZerosNeeded = Math.max(0, oddZerosNeeded);

        // dp[i][j][parity]
        // i: current element index (1 to n)
        // j: number of zero-elements converted to even numbers
        // parity: 0 for even, 1 for odd
        int[][][] dp = new int[n + 1][evenZerosNeeded + 1][2];

        // Initialize DP table with infinity
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= evenZerosNeeded; j++) {
                dp[i][j][0] = dp[i][j][1] = INF;
            }
        }

        int zerosSeen = 0;

        // Base Case: First element
        if (p[1] == 0) {
            zerosSeen++;
            // Option: First element is even
            if (1 <= evenZerosNeeded) {
                dp[1][1][0] = 0;
            }
            // Option: First element is odd
            if (1 <= oddZerosNeeded) {
                dp[1][0][1] = 0;
            }
        } else {
            int parity = Math.abs(p[1] % 2);
            dp[1][0][parity] = 0;
        }

        // DP Transitions
        for (int i = 2; i <= n; i++) {
            if (p[i] != 0) {
                // Current element is fixed
                int currentParity = Math.abs(p[i] % 2);
                for (int j = 0; j <= evenZerosNeeded; j++) {
                    // Reset the other parity for this state
                    dp[i][j][1 - currentParity] = INF;
                    // Minimum of: (same parity as previous) OR (different parity + 1 flip)
                    dp[i][j][currentParity] = Math.min(
                        dp[i - 1][j][currentParity], 
                        dp[i - 1][j][1 - currentParity] + 1
                    );
                }
            } else {
                // Current element is a wildcard (0)
                zerosSeen++;
                for (int j = 0; j <= evenZerosNeeded; j++) {
                    // Option 1: Make this zero EVEN
                    if (j > 0 && j <= zerosSeen) {
                        dp[i][j][0] = Math.min(
                            dp[i - 1][j - 1][0], 
                            dp[i - 1][j - 1][1] + 1
                        );
                    } else {
                        dp[i][j][0] = INF;
                    }

                    // Option 2: Make this zero ODD
                    int oddZerosUsed = zerosSeen - j;
                    if (j <= zerosSeen && oddZerosUsed >= 0 && oddZerosUsed <= oddZerosNeeded) {
                        dp[i][j][1] = Math.min(
                            dp[i - 1][j][0] + 1, 
                            dp[i - 1][j][1]
                        );
                    } else {
                        dp[i][j][1] = INF;
                    }
                }
            }
        }

        // The result is the minimum cost at the last element with the required even-zero count
        int finalResult = Math.min(dp[n][evenZerosNeeded][0], dp[n][evenZerosNeeded][1]);
        return finalResult >= INF ? -1 : finalResult;
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to solve the minimum transitions problem.
 * Given a sequence where some elements are fixed and others are wildcards,
 * find the minimum number of adjacent elements that differ, given a target
 * count of zeros and ones.
 */
public class Main {

    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);

        int n = in.nextInt();

        // Edge case: A single element has no adjacent transitions.
        if (n <= 1) {
            System.out.println(0);
            return;
        }

        // Target distribution of bits
        int targetZeros = n / 2;
        int targetOnes = n - targetZeros;

        // Constraints: -1 for wildcard, 0 or 1 for fixed bits
        int[] constraints = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            int val = in.nextInt();
            if (val == 0) {
                constraints[i] = -1; // Wildcard
            } else {
                constraints[i] = val % 2;
            }
        }

        int result = solve(n, constraints, targetZeros, targetOnes);
        System.out.println(result);
    }

    /**
     * Computes the minimum number of transitions using Dynamic Programming.
     * 
     * @param n Total number of elements.
     * @param constraints Array of fixed bits or -1 for wildcards.
     * @param targetZeros The required total count of zeros.
     * @param targetOnes The required total count of ones.
     * @return Minimum transitions, or a large value if impossible.
     */
    private static int solve(int n, int[] constraints, int targetZeros, int targetOnes) {
        final int INF = 1_000_000_007;

        // dp[i][j][bit] represents:
        // i: index of the element being considered (1 to n)
        // j: number of zeros used so far (0 to targetZeros)
        // bit: the value assigned to the i-th element (0 or 1)
        int[][][] dp = new int[n + 1][targetZeros + 1][2];

        // Initialize DP table with infinity
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= targetZeros; j++) {
                Arrays.fill(dp[i][j], INF);
            }
        }

        // Base Case: First element (i = 1)
        // If we assign 0 to the first element
        if (constraints[1] != 1 && targetZeros >= 1) {
            dp[1][1][0] = 0;
        }
        // If we assign 1 to the first element
        if (constraints[1] != 0 && targetOnes >= 1) {
            dp[1][0][1] = 0;
        }

        // Transition through the sequence
        for (int i = 2; i <= n; i++) {
            for (int j = 0; j <= targetZeros; j++) {
                int onesUsed = i - j;

                // Ensure current distribution of j zeros and (i-j) ones is valid
                if (onesUsed < 0 || onesUsed > targetOnes) {
                    continue;
                }

                // Case 1: Current element is assigned 0
                if (constraints[i] != 1 && j > 0) {
                    int fromZero = dp[i - 1][j - 1][0];
                    int fromOne = dp[i - 1][j - 1][1] + 1;
                    dp[i][j][0] = Math.min(fromZero, fromOne);
                    if (dp[i][j][0] > INF) dp[i][j][0] = INF;
                }

                // Case 2: Current element is assigned 1
                if (constraints[i] != 0 && onesUsed > 0) {
                    int fromOne = dp[i - 1][j][1];
                    int fromZero = dp[i - 1][j][0] + 1;
                    dp[i][j][1] = Math.min(fromOne, fromZero);
                    if (dp[i][j][1] > INF) dp[i][j][1] = INF;
                }
            }
        }

        // The answer is the minimum transitions ending in either 0 or 1 at index n
        int result = Math.min(dp[n][targetZeros][0], dp[n][targetZeros][1]);
        return result >= INF ? -1 : result;
    }

    /**
     * Fast I/O reader for efficient integer parsing.
     */
    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = nextLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        private String nextLine() {
            try {
                return reader.readLine();
            } catch (IOException e) {
                return null;
            }
        }
    }
}

import java.util.Scanner;

/**
 * A solver to find the minimum number of parity switches required to satisfy 
 * a specific distribution of even and odd numbers in a sequence.
 */
class ParitySequenceSolver {
    private static final int INF = 1_000_000;

    /**
     * Solves the parity switch problem using Dynamic Programming.
     * 
     * @param inputNumbers The array of integers where 0 acts as a wildcard.
     * @return The minimum number of parity transitions (switches).
     */
    public int solve(int[] inputNumbers) {
        int n = inputNumbers.length;
        int evenTarget = n / 2;
        int oddTarget = n / 2 + n % 2;

        // dpTable[i][j][k][p]
        // i: number of elements processed
        // j: current count of even numbers
        // k: current count of odd numbers
        // p: parity of the i-th element (0 for even, 1 for odd)
        int[][][][] dpTable = new int[n + 1][evenTarget + 1][oddTarget + 1][2];

        // Initialize DP table with a large value (Infinity)
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= evenTarget; j++) {
                for (int k = 0; k <= oddTarget; k++) {
                    dpTable[i][j][k][0] = INF;
                    dpTable[i][j][k][1] = INF;
                }
            }
        }

        // Base case: 0 elements processed has 0 switches
        dpTable[0][0][0][0] = 0;
        dpTable[0][0][0][1] = 0;

        for (int i = 1; i <= n; i++) {
            int val = inputNumbers[i - 1];
            boolean isWildcard = (val == 0);
            boolean isEven = !isWildcard && (val % 2 == 0);
            boolean isOdd = !isWildcard && (val % 2 != 0);

            for (int j = 0; j <= evenTarget; j++) {
                for (int k = 0; k <= oddTarget; k++) {

                    // Attempt to treat current element as EVEN
                    if (isWildcard || isEven) {
                        if (j > 0) {
                            // Cost is 0 if previous was even, 1 if previous was odd
                            int prevEven = dpTable[i - 1][j - 1][k][0];
                            int prevOdd = dpTable[i - 1][j - 1][k][1] + 1;
                            dpTable[i][j][k][0] = Math.min(prevEven, prevOdd);
                        }
                    }

                    // Attempt to treat current element as ODD
                    if (isWildcard || isOdd) {
                        if (k > 0) {
                            // Cost is 1 if previous was even, 0 if previous was odd
                            int prevEven = dpTable[i - 1][j][k - 1][0] + 1;
                            int prevOdd = dpTable[i - 1][j][k - 1][1];
                            dpTable[i][j][k][1] = Math.min(prevEven, prevOdd);
                        }
                    }
                }
            }
        }

        int result = Math.min(dpTable[n][evenTarget][oddTarget][0], 
                              dpTable[n][evenTarget][oddTarget][1]);

        return result >= INF ? -1 : result;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int n = scanner.nextInt();
        int[] inputNumbers = new int[n];
        for (int i = 0; i < n; i++) {
            inputNumbers[i] = scanner.nextInt();
        }

        ParitySequenceSolver solver = new ParitySequenceSolver();
        int minSwitches = solver.solve(inputNumbers);

        System.out.println(minSwitches);

        scanner.close();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.StringTokenizer;

/**
 * A solver that calculates the minimum number of parity transitions 
 * required in a sequence such that the total number of even elements 
 * matches the number of even-indexed positions in the original array.
 */
class ParityTransitionSolver {

    private static final int INF = 1_000_000_000;
    private static final int EVEN = 0;
    private static final int ODD = 1;

    /**
     * Solves the parity transition minimization problem.
     * 
     * @param inputArray The input array where 0 represents a wildcard.
     * @return The minimum number of parity switches.
     */
    public int solve(int[] inputArray) {
        int n = inputArray.length;
        int targetEvenCount = calculateTargetEvenCount(n);

        // dp[i][j][k] represents:
        // i: number of elements processed so far
        // j: count of even numbers used so far
        // k: parity of the last element processed (0 for even, 1 for odd)
        int[][][] dp = new int[n + 1][n + 1][2];

        // Initialize DP table with infinity
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                Arrays.fill(dp[i][j], INF);
            }
        }

        // Base case: 0 elements processed, 0 even elements, 0 cost.
        // We set both parity states to 0 to ensure the first element 
        // does not incur a "switch" cost.
        dp[0][0][EVEN] = 0;
        dp[0][0][ODD] = 0;

        for (int i = 1; i <= n; i++) {
            int val = inputArray[i - 1];

            for (int j = 0; j < i; j++) {
                for (int prevParity = 0; prevParity < 2; prevParity++) {
                    int prevTransitions = dp[i - 1][j][prevParity];

                    if (prevTransitions == INF) {
                        continue;
                    }

                    if (val != 0) {
                        // Case: Element is fixed (not a wildcard)
                        int currentParity = (val % 2 == 0) ? EVEN : ODD;
                        int nextEvenCount = (currentParity == EVEN) ? j + 1 : j;
                        int transitionCost = (prevParity != currentParity) ? 1 : 0;

                        // Special handling for the first element to avoid unnecessary transition cost
                        if (i == 1) transitionCost = 0;

                        dp[i][nextEvenCount][currentParity] = Math.min(
                            dp[i][nextEvenCount][currentParity], 
                            prevTransitions + transitionCost
                        );
                    } else {
                        // Case: Element is a wildcard (0), can be even or odd
                        for (int currentParity = 0; currentParity < 2; currentParity++) {
                            int nextEvenCount = (currentParity == EVEN) ? j + 1 : j;
                            int transitionCost = (i == 1) ? 0 : ((prevParity != currentParity) ? 1 : 0);

                            dp[i][nextEvenCount][currentParity] = Math.min(
                                dp[i][nextEvenCount][currentParity], 
                                prevTransitions + transitionCost
                            );
                        }
                    }
                }
            }
        }

        int result = Math.min(dp[n][targetEvenCount][EVEN], dp[n][targetEvenCount][ODD]);
        return result;
    }

    private int calculateTargetEvenCount(int n) {
        int count = 0;
        for (int i = 1; i <= n; i++) {
            if (i % 2 == 0) {
                count++;
            }
        }
        return count;
    }
}

/**
 * Fast I/O utility class.
 */
class FastReader {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    public FastReader(BufferedReader reader) {
        this.reader = reader;
    }

    public String next() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreElements()) {
            String line = reader.readLine();
            if (line == null) return null;
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    public int nextInt() throws IOException {
        return Integer.parseInt(next());
    }
}

public class Main {

    public static void main(String[] args) {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter pw = new PrintWriter(System.out)) {

            FastReader fr = new FastReader(br);

            String firstToken = fr.next();
            if (firstToken == null) return;

            int n = Integer.parseInt(firstToken);
            int[] inputArray = new int[n];
            for (int i = 0; i < n; i++) {
                inputArray[i] = fr.nextInt();
            }

            ParityTransitionSolver solver = new ParityTransitionSolver();
            int result = solver.solve(inputArray);

            pw.println(result);
            pw.flush();

        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
            System.exit(1);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * ParitySequenceOptimizer
 * 
 * This program calculates the minimum number of parity switches required to transform 
 * a sequence into one that meets a specific target distribution of even and odd numbers.
 * Certain elements (represented by 0) act as wildcards that can be either even or odd.
 */
public class ParitySequenceOptimizer {

    private static final int EVEN = 0;
    private static final int ODD = 1;

    /**
     * FastReader provides an efficient way to read input from the standard input stream,
     * which is essential for large datasets in competitive programming contexts.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader() {
            reader = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }

    public static void main(String[] args) {
        FastReader sc = new FastReader();

        String input = sc.next();
        if (input == null) return;

        int totalElements = Integer.parseInt(input);
        int[] numbers = new int[totalElements + 1];
        for (int i = 1; i <= totalElements; i++) {
            numbers[i] = sc.nextInt();
        }

        System.out.println(calculateMinimumSwitches(totalElements, numbers));
    }

    /**
     * Solves the parity distribution problem using Dynamic Programming.
     * 
     * Complexity:
     * Time: O(n^3) - Due to the initialization of the 4D array.
     * Space: O(n^3) - To store the DP table.
     *
     * @param n Total number of elements in the sequence.
     * @param numbers The sequence of integers (0 is a wildcard).
     * @return The minimum number of parity switches to satisfy the target distribution.
     */
    private static int calculateMinimumSwitches(int n, int[] numbers) {
        // dp[index][evenCount][oddCount][lastParity]
        // Represents the minimum cost to have specific counts of even/odd numbers 
        // up to 'index', ending with a specific parity.
        int[][][][] dp = new int[n + 1][n + 1][n + 1][2];
        int infinity = n + 1;

        // Initialize DP table with infinity to represent unreachable states.
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                for (int k = 0; k <= n; k++) {
                    dp[i][j][k][EVEN] = infinity;
                    dp[i][j][k][ODD] = infinity;
                }
            }
        }

        // Base case: 0 elements processed, 0 even/odd count, 0 cost.
        // We initialize both parities to 0 to allow the first element to transition seamlessly.
        dp[0][0][0][EVEN] = 0;
        dp[0][0][0][ODD] = 0;

        for (int i = 1; i <= n; i++) {
            for (int j = 0; j < i; j++) {
                // j = number of even elements in previous step (i-1)
                // oddCount = number of odd elements in previous step (i-1)
                int oddCount = i - j - 1;

                boolean isWildcard = (numbers[i] == 0);
                boolean isEven = !isWildcard && (numbers[i] % 2 == 0);
                boolean isOdd = !isWildcard && (numbers[i] % 2 != 0);

                // Option 1: The current element is treated as EVEN
                if (isWildcard || isEven) {
                    // Cost to end in EVEN: 
                    // min(previous was EVEN [no cost], previous was ODD [cost +1 switch])
                    dp[i][j + 1][oddCount][EVEN] = Math.min(
                        dp[i - 1][j][oddCount][EVEN], 
                        dp[i - 1][j][oddCount][ODD] + 1
                    );
                }

                // Option 2: The current element is treated as ODD
                if (isWildcard || isOdd) {
                    // Cost to end in ODD:
                    // min(previous was ODD [no cost], previous was EVEN [cost +1 switch])
                    dp[i][j][oddCount + 1][ODD] = Math.min(
                        dp[i - 1][j][oddCount][ODD], 
                        dp[i - 1][j][oddCount][EVEN] + 1
                    );
                }
            }
        }

        // The target is to have roughly half even and half odd.
        int targetEvenCount = n / 2;
        int targetOddCount = n - targetEvenCount;

        return Math.min(
            dp[n][targetEvenCount][targetOddCount][EVEN],
            dp[n][targetEvenCount][targetOddCount][ODD]
        );
    }
}

import java.io.*;
import java.util.*;

/**
 * A solution to minimize the number of parity changes in an array
 * given constraints on the total number of odd and even elements.
 */
public class ParityMinimizer {

    private static final int INF = 1_000_000;

    private final int n;
    private final int[] constraints;
    private final int targetOdd;
    private final int targetEven;
    private final int[] dp;
    private final int maxOdd;
    private final int maxEven;

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int n = reader.nextInt();
            int[] constraints = reader.nextIntArray(n);

            ParityMinimizer solver = new ParityMinimizer(n, constraints);
            writer.println(solver.solve());
        } catch (Exception e) {
            // Handle or log exception as per requirements
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Initializes the solver with problem constraints.
     * 
     * @param n The size of the array.
     * @param constraints The array containing fixed parities (non-zero) or flexible values (zero).
     */
    public ParityMinimizer(int n, int[] constraints) {
        this.n = n;
        this.constraints = constraints;
        this.targetOdd = (n + 1) / 2;
        this.targetEven = n / 2;
        this.maxOdd = targetOdd;
        this.maxEven = targetEven;

        // We use a 1D array for the DP table to prevent the massive object overhead 
        // of a 4D array (int[][][][]) in Java, ensuring memory stability.
        // Dimensions: [index][remainingOdd][remainingEven][lastParity]
        int size = n * (maxOdd + 1) * (maxEven + 1) * 2;
        this.dp = new int[size];
        Arrays.fill(this.dp, -1);
    }

    /**
     * Computes the minimum parity changes needed.
     * @return Minimum changes.
     */
    public int solve() {
        // We initiate the recursion with both parity possibilities (0 and 1) for the "previous" element.
        // This mathematical trick ensures the very first element's parity does not incur a cost,
        // as min(P ^ 0, P ^ 1) is always 0 for any P in {0, 1}.
        return Math.min(
            computeMinChanges(n - 1, targetOdd, targetEven, 0),
            computeMinChanges(n - 1, targetOdd, targetEven, 1)
        );
    }

    /**
     * Recursive DP function with memoization.
     *
     * @param idx Current index in the array being processed.
     * @param remOdd Remaining number of odd elements required.
     * @param remEven Remaining number of even elements required.
     * @param lastParity Parity of the element at index idx + 1.
     * @return Minimum parity changes from index idx down to 0.
     */
    private int computeMinChanges(int idx, int remOdd, int remEven, int lastParity) {
        // Base case: Exceeded required counts
        if (remOdd < 0 || remEven < 0) {
            return INF;
        }
        // Base case: Successfully processed all elements
        if (idx < 0) {
            return 0;
        }

        // Memoization lookup
        int dpIdx = getFlattenedIndex(idx, remOdd, remEven, lastParity);
        if (dp[dpIdx] != -1) {
            return dp[dpIdx];
        }

        int result;
        if (constraints[idx] > 0) {
            // Element parity is fixed by the input constraint
            int currentParity = constraints[idx] % 2;
            if (currentParity == 0) {
                result = computeMinChanges(idx - 1, remOdd, remEven - 1, 0) + (0 ^ lastParity);
            } else {
                result = computeMinChanges(idx - 1, remOdd - 1, remEven, 1) + (1 ^ lastParity);
            }
        } else {
            // Element parity is flexible; minimize between choosing even or odd
            int chooseEven = computeMinChanges(idx - 1, remOdd, remEven - 1, 0) + (0 ^ lastParity);
            int chooseOdd = computeMinChanges(idx - 1, remOdd - 1, remEven, 1) + (1 ^ lastParity);
            result = Math.min(chooseEven, chooseOdd);
        }

        // Cap the result to prevent overflow and maintain consistency
        if (result > INF) {
            result = INF;
        }

        return dp[dpIdx] = result;
    }

    /**
     * Flattens 4D coordinates into a 1D index for the DP array.
     */
    private int getFlattenedIndex(int i, int o, int e, int p) {
        return (((i * (maxOdd + 1) + o) * (maxEven + 1) + e) * 2 + p);
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public int[] nextIntArray(int n) {
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to solve the minimum parity change problem in a sequence.
 * The goal is to fill placeholders (0s) with missing numbers from 1 to N 
 * to minimize the number of times the parity changes between adjacent elements.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        FastWriter writer = new FastWriter(System.out);

        ParitySequenceSolver solver = new ParitySequenceSolver();
        solver.solve(reader, writer);

        writer.close();
    }

    /**
     * Solves the specific task of minimizing parity changes.
     */
    static class ParitySequenceSolver {
        private static final int INF = 1_000_000_000;
        private static final int PARITY_EVEN = 0;
        private static final int PARITY_ODD = 1;
        private static final int PARITY_NONE = 2;

        private int[][][][] memo;
        private int[] elements;
        private int n;

        public void solve(FastReader in, FastWriter out) {
            n = in.nextInt();
            if (n <= 0) {
                out.printLine(0);
                return;
            }

            elements = new int[n];
            Set<Integer> presentNumbers = new HashSet<>();
            for (int i = 0; i < n; i++) {
                elements[i] = in.nextInt();
                if (elements[i] != 0) {
                    presentNumbers.add(elements[i]);
                }
            }

            // Calculate how many even and odd numbers are missing from the set {1...N}
            int evenMissing = 0;
            int oddMissing = 0;
            for (int i = 1; i <= n; i++) {
                if (!presentNumbers.contains(i)) {
                    if (i % 2 == 0) {
                        evenMissing++;
                    } else {
                        oddMissing++;
                    }
                }
            }

            // Initialize memoization table: [index][evenRemaining][oddRemaining][lastParity]
            // lastParity: 0=Even, 1=Odd, 2=None
            memo = new int[n][evenMissing + 1][oddMissing + 1][3];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j <= evenMissing; j++) {
                    for (int k = 0; k <= oddMissing; k++) {
                        Arrays.fill(memo[i][j][k], -1);
                    }
                }
            }

            int minChanges = computeMinParityChanges(0, evenMissing, oddMissing, PARITY_NONE);
            out.printLine(minChanges);
        }

        /**
         * Recursive DP function with memoization to find minimum parity changes.
         * 
         * @param index          Current index in the sequence.
         * @param evenRemaining  Count of even numbers available to fill 0s.
         * @param oddRemaining   Count of odd numbers available to fill 0s.
         * @param lastParity     Parity of the previous element (0: Even, 1: Odd, 2: None).
         * @return               The minimum parity changes from this state to the end.
         */
        private int computeMinParityChanges(int index, int evenRemaining, int oddRemaining, int lastParity) {
            if (index == n) {
                return 0;
            }

            if (memo[index][evenRemaining][oddRemaining][lastParity] != -1) {
                return memo[index][evenRemaining][oddRemaining][lastParity];
            }

            int minCost = INF;

            if (elements[index] == 0) {
                // Option 1: Fill placeholder with an even number
                if (evenRemaining > 0) {
                    int cost = computeMinParityChanges(index + 1, evenRemaining - 1, oddRemaining, PARITY_EVEN);
                    if (cost != INF) {
                        int penalty = (lastParity != PARITY_NONE && lastParity != PARITY_EVEN) ? 1 : 0;
                        minCost = Math.min(minCost, cost + penalty);
                    }
                }
                // Option 2: Fill placeholder with an odd number
                if (oddRemaining > 0) {
                    int cost = computeMinParityChanges(index + 1, evenRemaining, oddRemaining - 1, PARITY_ODD);
                    if (cost != INF) {
                        int penalty = (lastParity != PARITY_NONE && lastParity != PARITY_ODD) ? 1 : 0;
                        minCost = Math.min(minCost, cost + penalty);
                    }
                }
            } else {
                // Option 3: Use the existing number
                int currentParity = elements[index] % 2;
                int cost = computeMinParityChanges(index + 1, evenRemaining, oddRemaining, currentParity);
                if (cost != INF) {
                    int penalty = (lastParity != PARITY_NONE && lastParity != currentParity) ? 1 : 0;
                    minCost = Math.min(minCost, cost + penalty);
                }
            }

            return memo[index][evenRemaining][oddRemaining][lastParity] = minCost;
        }
    }

    /**
     * Fast I/O reader for efficient input processing.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            return next == null ? 0 : Integer.parseInt(next);
        }
    }

    /**
     * Fast I/O writer for efficient output processing.
     */
    static class FastWriter {
        private final PrintWriter writer;

        public FastWriter(OutputStream outputStream) {
            this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) writer.print(' ');
                writer.print(objects[i]);
            }
        }

        public void printLine(Object... objects) {
            print(objects);
            writer.println();
        }

        public void close() {
