import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.StringTokenizer;

/**
 * ParitySequenceOptimizer finds the minimum number of parity switches required 
 * to complete a sequence by filling in zeros with missing numbers from the range [1, n].
 */
public class ParitySequenceOptimizer {

    private static final int INF = 1_000_000_000;

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        try {
            int n = reader.nextInt();
            if (n <= 0) {
                System.out.println(0);
                return;
            }

            int[] sequence = new int[n];
            boolean[] isPresent = new boolean[n + 1];

            for (int i = 0; i < n; i++) {
                int val = reader.nextInt();
                sequence[i] = val;
                // Track which numbers from 1 to n are present in the input
                if (val >= 1 && val <= n) {
                    isPresent[val] = true;
                }
            }

            int missingOddCount = 0;
            int missingEvenCount = 0;

            for (int i = 1; i <= n; i++) {
                if (!isPresent[i]) {
                    if (i % 2 != 0) {
                        missingOddCount++;
                    } else {
                        missingEvenCount++;
                    }
                }
            }

            ParitySolver solver = new ParitySolver(sequence, missingOddCount, missingEvenCount);
            System.out.println(solver.findMinSwitches());

        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * Logic encapsulated to separate computation from I/O.
     */
    private static class ParitySolver {
        private final int[] sequence;
        private final int initialOdd;
        private final int initialEven;
        private final int n;

        // memo[lastWasOdd][index][remainingOdd][remainingEven]
        // lastWasOdd: 1 for true, 0 for false
        private final int[][][][] memo;

        public ParitySolver(int[] sequence, int missingOdd, int missingEven) {
            this.sequence = sequence;
            this.initialOdd = missingOdd;
            this.initialEven = missingEven;
            this.n = sequence.length;

            this.memo = new int[2][n][missingOdd + 1][missingEven + 1];
            for (int i = 0; i < 2; i++) {
                for (int j = 0; j < n; j++) {
                    for (int k = 0; k <= missingOdd; k++) {
                        Arrays.fill(memo[i][j][k], -1);
                    }
                }
            }
        }

        /**
         * Calculates the minimum switches by trying two different parity assumptions 
         * for the virtual element preceding the first index.
         */
        public int findMinSwitches() {
            int startAsOdd = computeMinSwitches(true, 0, initialOdd, initialEven);
            int startAsEven = computeMinSwitches(false, 0, initialOdd, initialEven);

            return Math.min(startAsOdd, startAsEven);
        }

        private int computeMinSwitches(boolean lastWasOdd, int idx, int remOdd, int remEven) {
            if (idx == n) {
                return 0;
            }

            int parityIdx = lastWasOdd ? 1 : 0;
            if (memo[parityIdx][idx][remOdd][remEven] != -1) {
                return memo[parityIdx][idx][remOdd][remEven];
            }

            int minCost = INF;

            if (sequence[idx] == 0) {
                // The current element is a placeholder (0), try filling with available numbers

                // Option 1: Fill with an Odd number
                if (remOdd > 0) {
                    int cost = lastWasOdd ? 0 : 1;
                    int res = computeMinSwitches(true, idx + 1, remOdd - 1, remEven);
                    if (res != INF) {
                        minCost = Math.min(minCost, cost + res);
                    }
                }

                // Option 2: Fill with an Even number
                if (remEven > 0) {
                    int cost = lastWasOdd ? 1 : 0;
                    int res = computeMinSwitches(false, idx + 1, remOdd, remEven - 1);
                    if (res != INF) {
                        minCost = Math.min(minCost, cost + res);
                    }
                }
            } else {
                // The current element is fixed
                boolean currentIsOdd = (sequence[idx] % 2 != 0);
                int cost = (lastWasOdd == currentIsOdd) ? 0 : 1;
                int res = computeMinSwitches(currentIsOdd, idx + 1, remOdd, remEven);
                if (res != INF) {
                    minCost = cost + res;
                }
            }

            return memo[parityIdx][idx][remOdd][remEven] = minCost;
        }
    }

    /**
     * Fast I/O utility class for efficient data reading.
     */
    private static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String next = next();
            return next == null ? 0 : Integer.parseInt(next);
        }
    }
}

