/**
 * A program to find the minimum number of parity switches required to fill 
 * missing values in an array using a specific set of available numbers.
 */
public class Codechef {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = scanner.nextInt();
            int[] inputArray = new int[n];
            Set<Integer> existingElements = new HashSet<>();

            for (int i = 0; i < n; i++) {
                inputArray[i] = scanner.nextInt();
                if (inputArray[i] != 0) {
                    existingElements.add(inputArray[i]);
                }
            }

            // Count how many even and odd numbers from the range [1, n] are missing
            int missingEvenCount = 0;
            int missingOddCount = 0;
            for (int i = 1; i <= n; i++) {
                if (!existingElements.contains(i)) {
                    if (i % 2 == 0) {
                        missingEvenCount++;
                    } else {
                        missingOddCount++;
                    }
                }
            }

            // Normalize the input array to represent parities:
            // 0: placeholder (to be filled), 1: odd, 2: even
            for (int i = 0; i < n; i++) {
                if (inputArray[i] != 0) {
                    inputArray[i] = (inputArray[i] % 2 == 0) ? 2 : 1;
                }
            }

            ParitySequenceSolver solver = new ParitySequenceSolver(n, inputArray, missingEvenCount, missingOddCount);
            out.println(solver.solve());

        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.close();
        }
    }

    /**
     * Solver class that encapsulates the Dynamic Programming logic.
     */
    static class ParitySequenceSolver {
        private final int n;
        private final int[] parityArray;
        private final int missingEven;
        private final int missingOdd;
        private final int[][][][] memo;
        private static final int INF = 1_000_000; // Large enough constant to avoid overflow

        public ParitySequenceSolver(int n, int[] parityArray, int missingEven, int missingOdd) {
            this.n = n;
            this.parityArray = parityArray;
            this.missingEven = missingEven;
            this.missingOdd = missingOdd;
            // DP Table: [index][remainingEven][remainingOdd][lastParity]
            this.memo = new int[n + 1][missingEven + 1][missingOdd + 1][2];
            initializeMemo();
        }

        private void initializeMemo() {
            for (int i = 0; i <= n; i++) {
                for (int j = 0; j <= missingEven; j++) {
                    for (int k = 0; k <= missingOdd; k++) {
                        Arrays.fill(memo[i][j][k], -1);
                    }
                }
            }
        }

        public int solve() {
            // Start recursion from index 0, with all missing numbers available
            return computeMinSwitches(0, missingEven, missingOdd, 0);
        }

        /**
         * Recursive DP function to find minimum parity switches.
         * 
         * @param idx          Current index in the array
         * @param remEven      Remaining even numbers available to fill 0s
         * @param remOdd       Remaining odd numbers available to fill 0s
         * @param lastParity   Parity of the previous element (0 for even, 1 for odd)
         * @return             Minimum switches from this state to the end
         */
        private int computeMinSwitches(int idx, int remEven, int remOdd, int lastParity) {
            // Base case: reached the end of the array
            if (idx == n) {
                return 0;
            }

            // Return cached result if available
            if (memo[idx][remEven][remOdd][lastParity] != -1) {
                return memo[idx][remEven][remOdd][lastParity];
            }

            int result;

            if (idx == 0) {
                // First element: no parity switch cost incurred
                if (parityArray[idx] == 0) {
                    result = INF;
                    if (remEven > 0) {
                        result = Math.min(result, computeMinSwitches(idx + 1, remEven - 1, remOdd, 0));
                    }
                    if (remOdd > 0) {
                        result = Math.min(result, computeMinSwitches(idx + 1, remEven, remOdd - 1, 1));
                    }
                } else {
                    result = computeMinSwitches(idx + 1, remEven, remOdd, parityArray[idx] % 2);
                }
            } else {
                // Subsequent elements: cost is 1 if parity changes, 0 otherwise
                if (parityArray[idx] == 0) {
                    result = INF;
                    if (remEven > 0) {
                        int cost = (lastParity + 0) % 2;
                        result = Math.min(result, computeMinSwitches(idx + 1, remEven - 1, remOdd, 0) + cost);
                    }
                    if (remOdd > 0) {
                        int cost = (lastParity + 1) % 2;
                        result = Math.min(result, computeMinSwitches(idx + 1, remEven, remOdd - 1, 1) + cost);
                    }
                } else {
                    int currentParity = parityArray[idx] % 2;
                    int cost = (lastParity + currentParity) % 2;
                    result = computeMinSwitches(idx + 1, remEven, remOdd, currentParity) + cost;
                }
            }

            return memo[idx][remEven][remOdd][lastParity] = result;
        }
    }

    /**
     * Utility class for high-performance input reading.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A refactored solution to minimize parity-related costs using dynamic programming.
 */
public class Main {

    /**
     * Solver class that encapsulates the dynamic programming state and logic.
     */
    static class ParitySolver {
        private final int[] numbers;
        private final int n;
        private final int[][][][] memo;

        /**
         * Initializes the solver with the input array.
         * 
         * @param numbers The array of integers to process.
         */
        public ParitySolver(int[] numbers) {
            this.numbers = numbers;
            this.n = numbers.length;
            // memo[index][evenBudget][oddBudget][prevParity]
            // Size is (n+1) to prevent out-of-bounds and allow index up to n.
            this.memo = new int[n + 1][n + 1][n + 1][2];
        }

        /**
         * Resets the memoization table to -1.
         */
        public void resetMemo() {
            for (int i = 0; i <= n; i++) {
                for (int j = 0; j <= n; j++) {
                    for (int k = 0; k <= n; k++) {
                        memo[i][j][k][0] = -1;
                        memo[i][j][k][1] = -1;
                    }
                }
            }
        }

        /**
         * Recursively computes the minimum cost using memoization.
         *
         * @param index       Current index in the numbers array.
         * @param evenBudget  Remaining available even numbers.
         * @param oddBudget   Remaining available odd numbers.
         * @param prevParity  The parity (0 or 1) of the previous number.
         * @return The minimum cost from the current state.
         */
        public int solve(int index, int evenBudget, int oddBudget, int prevParity) {
            // Base Case: Reached end of array
            if (index >= n) {
                return 0;
            }

            // Check if result is already computed
            if (memo[index][evenBudget][oddBudget][prevParity] != -1) {
                return memo[index][evenBudget][oddBudget][prevParity];
            }

            int result;
            int currentVal = numbers[index];

            // Case 1: The number is non-zero OR we have no budgets left to manipulate parity
            if (currentVal > 0 || (evenBudget <= 0 && oddBudget <= 0)) {
                int nextParity = Math.abs(currentVal % 2);
                result = ((prevParity + currentVal) % 2) + solve(index + 1, evenBudget, oddBudget, nextParity);
            } 
            // Case 2: Even budget is exhausted, must treat current as an odd flip
            else if (evenBudget <= 0) {
                result = solve(index + 1, evenBudget, oddBudget - 1, 1) + ((prevParity + 1) % 2);
            } 
            // Case 3: Odd budget is exhausted, must treat current as an even flip
            else if (oddBudget <= 0) {
                result = solve(index + 1, evenBudget - 1, oddBudget, 0) + (prevParity % 2);
            } 
            // Case 4: Both budgets are available; decide the minimum cost path
            else {
                if (prevParity % 2 == 0) {
                    int useEven = solve(index + 1, evenBudget - 1, oddBudget, 0);
                    int useOdd = solve(index + 1, evenBudget, oddBudget - 1, 1) + 1;
                    result = Math.min(useEven, useOdd);
                } else {
                    int useEven = solve(index + 1, evenBudget - 1, oddBudget, 0) + 1;
                    int useOdd = solve(index + 1, evenBudget, oddBudget - 1, 1);
                    result = Math.min(useEven, useOdd);
                }
            }

            return memo[index][evenBudget][oddBudget][prevParity] = result;
        }
    }

    /**
     * Fast I/O class for efficient reading.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) {
        FastReader sc = new FastReader(System.in);
        String firstToken = sc.next();
        if (firstToken == null) return;

        int n = Integer.parseInt(firstToken);
        int[] numbers = new int[n];

        // Initial budget calculation
        int evenBudget = n / 2;
        int oddBudget = n - (n / 2);

        for (int i = 0; i < n; i++) {
            numbers[i] = sc.nextInt();
            // If number is non-zero, it consumes part of the starting budget
            if (numbers[i] != 0) {
                if (numbers[i] % 2 == 0) {
                    evenBudget--;
                } else {
                    oddBudget--;
                }
            }
        }

        ParitySolver solver = new ParitySolver(numbers);

        // Solve for both possible starting parities (0 and 1) and find the minimum
        solver.resetMemo();
        int minCostStartingZero = solver.solve(0, evenBudget, oddBudget, 0);

        solver.resetMemo();
        int minCostStartingOne = solver.solve(0, evenBudget, oddBudget, 1);

        System.out.println(Math.min(minCostStartingZero, minCostStartingOne));
    }
}

import java.util.Arrays;
import java.util.Scanner;

/**
 * A refactored solution for calculating the minimum cost to satisfy 
 * parity constraints using Dynamic Programming.
 */
public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // The original code logic implies a single test case per run.
        int testCases = 1;

        while (testCases-- > 0) {
            if (!scanner.hasNextInt()) {
                break;
            }

            int n = scanner.nextInt();
            int[] elements = new int[n];

            // Initial budgets for even and odd parity assignments.
            // These represent how many "free" or "transformable" slots we have.
            int evenBudget = n / 2;
            int oddBudget = n - (n / 2);

            for (int i = 0; i < n; i++) {
                elements[i] = scanner.nextInt();
                // If the element is non-zero, it consumes the budget for its own parity.
                if (elements[i] != 0) {
                    if (elements[i] % 2 == 0) {
                        evenBudget--;
                    } else {
                        oddBudget--;
                    }
                }
            }

            ParitySolver solver = new ParitySolver(elements, n);

            // We solve for both possible starting parities (0 and 1) 
            // and choose the minimum resulting cost.
            int costStartingEven = solver.solve(evenBudget, oddBudget, 0);
            int costStartingOdd = solver.solve(evenBudget, oddBudget, 1);

            System.out.println(Math.min(costStartingEven, costStartingOdd));
        }
        scanner.close();
    }
}

/**
 * Solver class encapsulating the dynamic programming logic.
 */
class ParitySolver {
    private final int[] elements;
    private final int n;
    private final int[][][] memo;

    private static final int EVEN = 0;
    private static final int ODD = 1;

    /**
     * @param elements The input array of integers.
     * @param n The size of the array.
     */
    public ParitySolver(int[] elements, int n) {
        this.elements = elements;
        this.n = n;
        // memo[index][evenBudget][prevParity]
        this.memo = new int[n + 1][n + 1][2];
        initializeMemo();
    }

    /**
     * Fills the memoization table with -1 to indicate uncomputed states.
     */
    private void initializeMemo() {
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                Arrays.fill(memo[i][j], -1);
            }
        }
    }

    /**
     * Entry point for the recursive computation.
     *
     * @param evenBudget Remaining capacity for even parity assignments.
     * @param oddBudget  Remaining capacity for odd parity assignments.
     * @param initialParity The parity of the preceding element.
     * @return The minimum transformation cost.
     */
    public int solve(int evenBudget, int oddBudget, int initialParity) {
        return compute(0, evenBudget, oddBudget, initialParity);
    }

    /**
     * Recursive method using memoization to find the minimum cost.
     */
    private int compute(int index, int evenBudget, int oddBudget, int prevParity) {
        // Base case: reached the end of the array.
        if (index >= n) {
            return 0;
        }

        // Return the result if it has already been calculated.
        if (memo[index][evenBudget][prevParity] != -1) {
            return memo[index][evenBudget][prevParity];
        }

        int currentVal = elements[index];
        int result;

        // Case 1: Element is non-zero or we have run out of both budgets.
        // We simply calculate the cost of the current parity and move forward.
        if (currentVal > 0 || (evenBudget <= 0 && oddBudget <= 0)) {
            int currentParity = Math.abs(currentVal % 2);
            int transitionCost = (prevParity + currentParity) % 2;
            result = transitionCost + compute(index + 1, evenBudget, oddBudget, currentParity);
        } 
        // Case 2: Even budget exhausted, must use the odd budget.
        else if (evenBudget <= 0) {
            int transitionCost = (prevParity + 1) % 2;
            result = transitionCost + compute(index + 1, evenBudget, oddBudget - 1, ODD);
        } 
        // Case 3: Odd budget exhausted, must use the even budget.
        else if (oddBudget <= 0) {
            int transitionCost = (prevParity) % 2;
            result = transitionCost + compute(index + 1, evenBudget - 1, oddBudget, EVEN);
        } 
        // Case 4: Both budgets available, choose the path with the minimum cost.
        else {
            int optionUseEven = compute(index + 1, evenBudget - 1, oddBudget, EVEN);
            int optionUseOdd = compute(index + 1, evenBudget, oddBudget - 1, ODD);

            if (prevParity == EVEN) {
                // If current is even, we take the minimum of continuing even or switching to odd (+1 cost).
                result = Math.min(optionUseEven, optionUseOdd + 1);
            } else {
                // If current is odd, we take the minimum of continuing odd or switching to even (+1 cost).
                result = Math.min(optionUseEven + 1, optionUseOdd);
            }
        }

        return memo[index][evenBudget][prevParity] = result;
    }
}

import java.io.BufferedReader;
