import java.util.List;
import java.util.PriorityQueue;
import java.util.StringTokenizer;

/**
 * A refactored solution to process parity-based gap matching in a permutation with placeholders.
 */
public class TaskSolver {

    private static final int EVEN = 0;
    private static final int ODD = 1;

    public static void main(String[] args) {
        try {
            FastReader reader = new FastReader(System.in);
            int n = reader.nextInt();
            int[] nums = reader.readIntArray(n);

            System.out.println(solve(n, nums));
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Calculates the minimum operations required based on missing parity counts
     * and the distribution of zero-gaps between existing numbers.
     *
     * @param n    The size of the array.
     * @param nums The input array containing numbers 1..n or 0 as placeholders.
     * @return The calculated result as a string.
     */
    public static String solve(int n, int[] nums) {
        if (n == 1) {
            return "0";
        }

        int[] missingParityCounts = calculateMissingParityCounts(n, nums);
        List<Integer> nonZeroIndices = findNonZeroIndices(nums);

        // If the array is entirely composed of zeros
        if (nonZeroIndices.isEmpty()) {
            return "1";
        }

        int diff = 0;
        PriorityQueue<Integer> internalGapsEven = new PriorityQueue<>();
        PriorityQueue<Integer> internalGapsOdd = new PriorityQueue<>();
        PriorityQueue<Integer> edgeGapsEven = new PriorityQueue<>();
        PriorityQueue<Integer> edgeGapsOdd = new PriorityQueue<>();

        // 1. Process edge gaps (gaps before the first and after the last non-zero element)
        int firstIdx = nonZeroIndices.get(0);
        int lastIdx = nonZeroIndices.get(nonZeroIndices.size() - 1);

        if (firstIdx > 0) {
            addGapToQueue(edgeGapsEven, edgeGapsOdd, nums[firstIdx], firstIdx);
        }
        if (lastIdx < n - 1) {
            addGapToQueue(edgeGapsEven, edgeGapsOdd, nums[lastIdx], n - 1 - lastIdx);
        }

        // 2. Process internal gaps (gaps between non-zero elements)
        for (int i = 0; i < nonZeroIndices.size() - 1; i++) {
            int currIdx = nonZeroIndices.get(i);
            int nextIdx = nonZeroIndices.get(i + 1);
            int gapSize = nextIdx - currIdx - 1;

            if (gapSize > 0) {
                if (nums[currIdx] % 2 != nums[nextIdx] % 2) {
                    // Different parity on both sides of the gap
                    diff++;
                } else {
                    // Same parity on both sides
                    addGapToQueue(internalGapsEven, internalGapsOdd, nums[currIdx], gapSize);
                }
            } else if (nextIdx == currIdx + 1) {
                // Even if gap is 0, if parities differ, they contribute to diff
                if (nums[currIdx] % 2 != nums[nextIdx] % 2) {
                    diff++;
                }
            }
        }

        // 3. Greedy optimization: Use gaps to satisfy missing numbers
        // Process Even parity
        diff += optimizeGaps(internalGapsEven, edgeGapsEven, missingParityCounts[EVEN]);
        // Process Odd parity
        diff += optimizeGaps(internalGapsOdd, edgeGapsOdd, missingParityCounts[ODD]);

        return String.valueOf(diff);
    }

    private static int[] calculateMissingParityCounts(int n, int[] nums) {
        boolean[] present = new boolean[n + 1];
        for (int num : nums) {
            if (num != 0) {
                present[num] = true;
            }
        }

        int[] counts = new int[2]; // counts[0] = even missing, counts[1] = odd missing
        for (int i = 1; i <= n; i++) {
            if (!present[i]) {
                counts[i % 2]++;
            }
        }
        return counts;
    }

    private static List<Integer> findNonZeroIndices(int[] nums) {
        List<Integer> indices = new ArrayList<>();
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] != 0) {
                indices.add(i);
            }
        }
        return indices;
    }

    private static void addGapToQueue(PriorityQueue<Integer> evenQ, PriorityQueue<Integer> oddQ, int val, int size) {
        if (val % 2 == EVEN) evenQ.add(size);
        else oddQ.add(size);
    }

    private static void addGapToQueue(PriorityQueue<Integer> evenQ, PriorityQueue<Integer> oddQ, int val, int size, boolean isEdge) {
        // This is a helper for the specific logic where parity is determined by the non-zero element
        if (val % 2 == EVEN) evenQ.add(size);
        else oddQ.add(size);
    }

    // Overloaded to match original logic usage
    private static void addGapToQueue(PriorityQueue<Integer> eQ, PriorityQueue<Integer> oQ, int val, int size) {
        if (val % 2 == EVEN) eQ.add(size);
        else oQ.add(size);
    }

    private static int optimizeGaps(PriorityQueue<Integer> internal, PriorityQueue<Integer> edge, int availableCount) {
        int currentAvailable = availableCount;

        // Use internal gaps (cost 2 in final diff, but consumes missing count)
        while (!internal.isEmpty() && internal.peek() <= currentAvailable) {
            currentAvailable -= internal.poll();
        }

        // Use edge gaps (cost 1 in final diff, but consumes missing count)
        while (!edge.isEmpty() && edge.peek() <= currentAvailable) {
            currentAvailable -= edge.poll();
        }

        return (internal.size() * 2) + edge.size();
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(Reader input) {
            this.reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public int[] readIntArray(int n) throws IOException {
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * This program calculates the minimum number of parity transitions 
 * (even to odd or odd to even) in a permutation of numbers from 1 to N,
 * given that some elements in the sequence are already fixed.
 */
public class ParityTransitionOptimizer {

    private static final int INF = 1_000_000_000;
    private static final int PARITY_EVEN = 0;
    private static final int PARITY_ODD = 1;
    private static final int PARITY_NONE = 2;

    private final int arraySize;
    private final int[] sequence;
    private final int[][][][] memo;

    /**
     * Initializes the optimizer with the given sequence.
     *
     * @param n        The size of the sequence.
     * @param sequence The sequence where 0 represents a placeholder for a missing number.
     */
    public ParityTransitionOptimizer(int n, int[] sequence) {
        this.arraySize = n;
        this.sequence = sequence;
        // memo state: [previous_parity][even_pool_count][odd_pool_count][current_index]
        this.memo = new int[3][n + 1][n + 1][n + 1];
        initializeMemo();
    }

    private void initializeMemo() {
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j <= arraySize; j++) {
                for (int k = 0; k <= arraySize; k++) {
                    Arrays.fill(memo[i][j][k], -1);
                }
            }
        }
    }

    /**
     * Starts the dynamic programming process to find the minimum transitions.
     *
     * @param availableEven The count of even numbers available to fill placeholders.
     * @param availableOdd  The count of odd numbers available to fill placeholders.
     * @return The minimum number of parity transitions.
     */
    public int solve(int availableEven, int availableOdd) {
        return computeMinimumTransitions(availableEven, availableOdd, 0, PARITY_NONE);
    }

    private int computeMinimumTransitions(int even, int odd, int idx, int prevParity) {
        // Base case: reached the end of the sequence
        if (idx == arraySize) {
            return 0;
        }

        // Return memoized result if available
        if (memo[prevParity][even][odd][idx] != -1) {
            return memo[prevParity][even][odd][idx];
        }

        int minTransitions = INF;
        int fixedValue = sequence[idx];

        if (fixedValue != 0) {
            // Scenario 1: The current element is already fixed
            int currentParity = fixedValue % 2;
            int cost = (prevParity != PARITY_NONE && currentParity != prevParity) ? 1 : 0;
            int result = computeMinimumTransitions(even, odd, idx + 1, currentParity);

            if (result != INF) {
                minTransitions = result + cost;
            }
        } else {
            // Scenario 2: The current element is a placeholder (0), try both parities

            // Try placing an even number from the available pool
            if (even > 0) {
                int cost = (prevParity == PARITY_ODD) ? 1 : 0;
                int result = computeMinimumTransitions(even - 1, odd, idx + 1, PARITY_EVEN);
                if (result != INF) {
                    minTransitions = Math.min(minTransitions, result + cost);
                }
            }

            // Try placing an odd number from the available pool
            if (odd > 0) {
                int cost = (prevParity == PARITY_EVEN) ? 1 : 0;
                int result = computeMinimumTransitions(even, odd - 1, idx + 1, PARITY_ODD);
                if (result != INF) {
                    minTransitions = Math.min(minTransitions, result + cost);
                }
            }
        }

        return memo[prevParity][even][odd][idx] = minTransitions;
    }

    public static void main(String[] args) throws IOException {
        FastReader reader = new FastReader(System.in);

        String firstToken = reader.next();
        if (firstToken == null) return;

        int n = Integer.parseInt(firstToken);
        int[] arr = new int[n];
        boolean[] isPresent = new boolean[n + 1];

        for (int i = 0; i < n; i++) {
            arr[i] = reader.nextInt();
            // Track which numbers from 1..N are already present in the sequence
            if (arr[i] > 0 && arr[i] <= n) {
                isPresent[arr[i]] = true;
            }
        }

        // Calculate how many even and odd numbers are available to fill the 0s
        int availableEven = 0;
        int availableOdd = 0;
        for (int i = 1; i <= n; i++) {
            if (!isPresent[i]) {
                if (i % 2 == 0) {
                    availableEven++;
                } else {
                    availableOdd++;
                }
            }
        }

        ParityTransitionOptimizer optimizer = new ParityTransitionOptimizer(n, arr);
        System.out.println(optimizer.solve(availableEven, availableOdd));
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

/**
 * The ParityMinimizer class provides a solution to minimize the number of changes
 * required in an array to satisfy a specific count of even and odd elements.
 *
 * Problem constraints:
 * - Total even numbers required: n / 2
 * - Total odd numbers required: (n + 1) / 2
 * - Wildcards (0) can be any parity at no cost.
 * - Changing a non-zero element's parity incurs a cost of 1.
 */
public class ParityMinimizer {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int n = scanner.nextInt();
        int[] array = new int[n];
        for (int i = 0; i < n; i++) {
            if (scanner.hasNextInt()) {
                array[i] = scanner.nextInt();
            }
        }

        int minChanges = calculateMinChanges(n, array);
        System.out.println(minChanges);

        scanner.close();
    }

    /**
     * Calculates the minimum number of changes required to satisfy parity counts.
     * 
     * The logic follows a greedy approach: 
     * 1. Count how many even and odd numbers are already present (excluding zeros).
     * 2. Compare these counts to the required target counts.
     * 3. If we have more of one parity than the target allows, the surplus must be changed.
     *
     * @param n     The total size of the array.
     * @param array The input array where 0 represents a wildcard.
     * @return The minimum number of non-zero elements that must change parity.
     */
    public static int calculateMinChanges(int n, int[] array) {
        int currentEvenCount = 0;
        int currentOddCount = 0;

        // Count existing non-zero even and odd elements
        for (int value : array) {
            if (value != 0) {
                if (value % 2 == 0) {
                    currentEvenCount++;
                } else {
                    currentOddCount++;
                }
            }
        }

        // Calculate target counts based on problem rules
        int targetEvenCount = n / 2;
        int targetOddCount = (n + 1) / 2;

        int changes = 0;

        /* 
         * It is mathematically impossible to have both a surplus of even numbers 
         * AND a surplus of odd numbers simultaneously, because:
         * currentEven + currentOdd <= n  AND  targetEven + targetOdd = n.
         */
        if (currentEvenCount > targetEvenCount) {
            // We have too many even numbers; change the surplus to odd.
            changes = currentEvenCount - targetEvenCount;
        } else if (currentOddCount > targetOddCount) {
            // We have too many odd numbers; change the surplus to even.
            changes = currentOddCount - targetOddCount;
        }

        return changes;
    }
}

import java.util.*;
import java.io.*;

/**
 * This program solves the problem of finding the minimum number of parity transitions
 * in a sequence of length N, where some elements are pre-filled and others (zeros)
 * must be filled using the remaining numbers from the set {1, ..., N}.
 */
public class ParitySequenceOptimizer {

    private static final int INF = 1_000_000_000;

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            String nStr = reader.next();
            if (nStr == null) return;

            int n = Integer.parseInt(nStr);
            int[] sequence = new int[n];
            boolean[] usedInSequence = new boolean[n + 1];

            for (int i = 0; i < n; i++) {
                sequence[i] = reader.nextInt();
                // Only mark numbers as used if they are within the valid range [1, n]
                if (sequence[i] != 0 && sequence[i] <= n) {
                    usedInSequence[sequence[i]] = true;
                }
            }

            if (n <= 1) {
                out.println(0);
            } else {
                // Calculate how many even and odd numbers are available to fill the zeros
                int availableEven = 0;
                int availableOdd = 0;
                for (int i = 1; i <= n; i++) {
                    if (!usedInSequence[i]) {
                        if (i % 2 == 0) {
                            availableEven++;
                        } else {
                            availableOdd++;
                        }
                    }
                }

                ParitySolver solver = new ParitySolver(n, sequence, availableEven, availableOdd);
                out.println(solver.solve());
            }
        } catch (IOException e) {
            // In a real-world scenario, use a logger
            e.printStackTrace();
        } finally {
            out.close();
        }
    }

    /**
     * Handles the dynamic programming logic to find the minimum parity transitions.
     */
    private static class ParitySolver {
        private final int n;
        private final int[] sequence;
        private final int initialEvenCount;
        private final int initialOddCount;
        private final int[][][][] memo;

        public ParitySolver(int n, int[] sequence, int availableEven, int availableOdd) {
            this.n = n;
            this.sequence = sequence;
            this.initialEvenCount = availableEven;
            this.initialOddCount = availableOdd;
            // Memoization table: [index][even_remaining][odd_remaining][last_parity]
            this.memo = new int[n + 1][availableEven + 1][availableOdd + 1][2];
            initializeMemo();
        }

        private void initializeMemo() {
            for (int i = 0; i <= n; i++) {
                for (int j = 0; j <= initialEvenCount; j++) {
                    for (int k = 0; k <= initialOddCount; k++) {
                        Arrays.fill(memo[i][j][k], -1);
                    }
                }
            }
        }

        public int solve() {
            // If the first element is fixed, start recursion from the second element
            if (sequence[0] != 0) {
                return compute(1, initialEvenCount, initialOddCount, sequence[0] % 2);
            } else {
                int minTransitions = INF;
                // Try filling the first position with an even number
                if (initialEvenCount > 0) {
                    minTransitions = Math.min(minTransitions, compute(1, initialEvenCount - 1, initialOddCount, 0));
                }
                // Try filling the first position with an odd number
                if (initialOddCount > 0) {
                    minTransitions = Math.min(minTransitions, compute(1, initialEvenCount, initialOddCount - 1, 1));
                }
                return minTransitions == INF ? 0 : minTransitions;
            }
        }

        /**
         * Recursive DP function with memoization.
         * 
         * @param index The current index in the sequence we are processing.
         * @param e Remaining even numbers available to use.
         * @param o Remaining odd numbers available to use.
         * @param lastParity The parity of the previously placed number (0 for even, 1 for odd).
         * @return The minimum number of transitions from this state to the end.
         */
        private int compute(int index, int e, int o, int lastParity) {
            if (index == n) {
                return 0;
            }

            if (memo[index][e][o][lastParity] != -1) {
                return memo[index][e][o][lastParity];
            }

            int minTransitions = INF;

            if (sequence[index] != 0) {
                // Current element is fixed
                int currentParity = sequence[index] % 2;
                int cost = (currentParity == lastParity) ? 0 : 1;
                int res = compute(index + 1, e, o, currentParity);
                if (res != INF) {
                    minTransitions = cost + res;
                }
            } else {
                // Current element is a zero, try both even and odd
                // Option 1: Use an even number
                if (e > 0) {
                    int cost = (lastParity == 0) ? 0 : 1;
                    int res = compute(index + 1, e - 1, o, 0);
                    if (res != INF) {
                        minTransitions = Math.min(minTransitions, cost + res);
                    }
                }
                // Option 2: Use an odd number
                if (o > 0) {
                    int cost = (lastParity == 1) ? 0 : 1;
                    int res = compute(index + 1, e, o - 1, 1);
                    if (res != INF) {
                        minTransitions = Math.min(minTransitions, cost + res);
                    }
                }
            }

            return memo[index][e][o][lastParity] = minTransitions;
        }
    }

    /**
     * Fast I/O utility class.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * ParitySequenceOptimizer calculates the minimum number of parity switches 
 * required to fill missing values (represented by 0) in a sequence using 
 * the numbers from 1 to N that are not already present.
 */
public class ParitySequenceOptimizer {

    private static final int INF = 1_000_000_000;
    private static final int PARITY_EVEN = 0;
    private static final int PARITY_ODD = 1;
    private static final int PARITY_NONE = 2;

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        Integer n = reader.nextInt();
        if (n == null) return;

        int[] inputArray = new int[n];
        boolean[] isPresent = new boolean[n + 1];

        for (int i = 0; i < n; i++) {
            int val = reader.nextInt();
            inputArray[i] = val;
            if (val > 0 && val <= n) {
                isPresent[val] = true;
            }
        }

        int totalMissingOdds = 0;
        int totalMissingEvens = 0;
        for (int i = 1; i <= n; i++) {
            if (!isPresent[i]) {
                if (i % 2 != 0) {
                    totalMissingOdds++;
                } else {
                    totalMissingEvens++;
                }
            }
        }

        int result = computeMinParitySwitches(n, inputArray, totalMissingOdds, totalMissingEvens);
        System.out.println(result);
    }

    /**
     * Uses iterative Dynamic Programming to find the minimum parity switches.
     * 
     * Time Complexity: O(N^2) where N is the sequence length.
     * Space Complexity: O(N^2) to store the DP table.
     *
     * @param n The length of the array.
     * @param arr The input array (0 represents a missing value).
     * @param totalMissingOdds Total number of odd integers available to fill zeros.
     * @param totalMissingEvens Total number of even integers available to fill zeros.
     * @return The minimum number of parity switches.
     */
    private static int computeMinParitySwitches(int n, int[] arr, int totalMissingOdds, int totalMissingEvens) {
        // dp[i][j][p] represents:
        // i: current index in the array (0 to n)
        // j: number of missing odd integers used so far
        // p: parity of the last element (0: even, 1: odd, 2: none/start)
        int[][][] dp = new int[n + 1][totalMissingOdds + 1][3];

        // Initialize DP table with infinity
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= totalMissingOdds; j++) {
                Arrays.fill(dp[i][j], INF);
            }
        }

        // Base case: At index 0, 0 odds used, no previous parity
        dp[0][0][PARITY_NONE] = 0;

        int zerosEncountered = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j <= totalMissingOdds; j++) {
                for (int lastParity = 0; lastParity < 3; lastParity++) {
                    if (dp[i][j][lastParity] == INF) continue;

                    if (arr[i] != 0) {
                        // Case 1: Current element is fixed
                        int currentParity = arr[i] % 2;
                        int switchCost = calculateSwitchCost(lastParity, currentParity);
                        updateMin(dp, i + 1, j, currentParity, dp[i][j][lastParity] + switchCost);
                    } else {
                        // Case 2: Current element is a placeholder (0)

                        // Try filling with an odd number
                        if (j + 1 <= totalMissingOdds) {
                            int switchCost = calculateSwitchCost(lastParity, PARITY_ODD);
                            updateMin(dp, i + 1, j + 1, PARITY_ODD, dp[i][j][lastParity] + switchCost);
                        }

                        // Try filling with an even number
                        int usedEvens = zerosEncountered - j;
                        if (usedEvens + 1 <= totalMissingEvens) {
                            int switchCost = calculateSwitchCost(lastParity, PARITY_EVEN);
                            updateMin(dp, i + 1, j, PARITY_EVEN, dp[i][j][lastParity] + switchCost);
                        }
                    }
                }
            }
            // Increment zeros count after processing the current index for the next iteration
            if (arr[i] == 0) {
                zerosEncountered++;
            }
        }

        // The answer is the minimum switches recorded at index n with all missing odds used
        return Math.min(dp[n][totalMissingOdds][PARITY_EVEN], dp[n][totalMissingOdds][PARITY_ODD]);
    }

    private static int calculateSwitchCost(int lastParity, int currentParity) {
        if (lastParity == PARITY_NONE) return 0;
        return (lastParity == currentParity) ? 0 : 1;
    }

    private static void updateMin(int[][][] dp, int i, int j, int p, int val) {
        if (val < dp[i][j][p]) {
            dp[i][j][p] = val;
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
            tokenizer = null;
        }

        public Integer nextInt() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return Integer.parseInt(tokenizer.nextToken());
        }
    }
}

import java.util.Arrays;
import java.util.Scanner;

/**
 * Garland solver minimizes the number of parity changes in an array
 * by filling zero-valued slots with even or odd numbers such that
 * the total count of even and odd numbers meets specific requirements.
 */
public class Garland {

    private static final int INF = 1_000_000;

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;

            int n = scanner.nextInt();
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = scanner.nextInt();
            }

            GarlandSolver solver = new GarlandSolver(n, arr);
            int result = solver.solve();
            System.out.println(result >= INF ? -1 : result);
        }
    }

    private static class GarlandSolver {
        private final int n;
        private final int[] arr;
        private final int availableEven;
        private final int[] suffixZeros;
        private final int[][][] memo;

        // Parity constants
        private static final int EVEN = 0;
        private static final int ODD = 1;
        private static final int NO_PREVIOUS = 2;

        /**
         * @param n Total number of elements.
         * @param arr The input array where 0 represents a flexible slot.
         */
        public GarlandSolver(int n, int[] arr) {
            this.n = n;
            this.arr = arr;

            int totalEvenRequired = n / 2;
            int totalOddRequired = n - totalEvenRequired;

            int fixedEven = 0;
            int fixedOdd = 0;
            int[] zeros = new int[n];
            int zeroCount = 0;

            for (int i = 0; i < n; i++) {
                if (arr[i] > 0) {
                    if (arr[i] % 2 == 0) fixedEven++;
                    else fixedOdd++;
                } else {
                    zeros[i] = 1;
                    zeroCount++;
                }
            }

            this.availableEven = totalEvenRequired - fixedEven;
            this.availableOdd = totalOddRequired - fixedOdd;

            // Precompute suffix sums of zeros to calculate remaining odd slots in O(1)
            this.suffixZeros = new int[n + 1];
            for (int i = n - 1; i >= 0; i--) {
                this.suffixZeros[i] = this.suffixZeros[i + 1] + (arr[i] == 0 ? 1 : 0);
            }

            // memo[index][remainingEven][prevParity]
            // prevParity: 0=Even, 1=Odd, 2=None
            this.memo = new int[n + 1][Math.max(0, totalEvenRequired) + 1][3];
            for (int[][] layer : memo) {
                for (int[] row : layer) {
                    Arrays.fill(row, -1);
                }
            }
        }

        /**
         * Solves the problem and returns the minimum parity changes.
         */
        public int solve() {
            // If the fixed numbers already exceed required counts
            if (availableEven < 0 || (n - (n / 2) - (countFixedOdd())) < 0) {
                return INF;
            }
            return compute(0, availableEven, NO_PREVIOUS);
        }

        private int countFixedOdd() {
            int count = 0;
            for (int x : arr) {
                if (x > 0 && x % 2 != 0) count++;
            }
            return count;
        }

        /**
         * Recursive DP function with memoization.
         *
         * @param idx          Current index in the array.
         * @param remEven      Number of even numbers left to place in zero slots.
         * @param prevParity   The parity of the previous element.
         * @return             Minimum parity changes from this state onwards.
         */
        private int compute(int idx, int remEven, int prevParity) {
            if (idx == n) {
                return 0;
            }

            if (memo[idx][remEven][prevParity] != -1) {
                return memo[idx][remEven][prevParity];
            }

            int result = INF;

            if (arr[idx] > 0) {
                // Fixed element
                int currentParity = arr[idx] % 2;
                int cost = (prevParity != NO_PREVIOUS && currentParity != prevParity) ? 1 : 0;
                result = cost + compute(idx + 1, remEven, currentParity);
            } else {
                // Flexible element (zero)
                int remOdd = suffixZeros[idx] - remEven;

                // Try placing an even number
                if (remEven > 0) {
                    int cost = (prevParity != NO_PREVIOUS && prevParity != EVEN) ? 1 : 0;
                    result = Math.min(result, cost + compute(idx + 1, remEven - 1, EVEN));
                }

                // Try placing an odd number
                if (remOdd > 0) {
                    int cost = (prevParity != NO_PREVIOUS && prevParity != ODD) ? 1 : 0;
                    result = Math.min(result, cost + compute(idx + 1, remEven, ODD));
                }
            }

            return memo[idx][remEven][prevParity] = result;
        }
    }
}

import java.io.*;
import java.util.Arrays;
import java.util.StringTokenizer;

/**
 * This program calculates the minimum number of parity switches required 
 * to complete a sequence of numbers given some pre-filled values.
 */
public class ParitySequenceMinimizer {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int n = reader.nextInt();
            ParitySequenceSolver solver = new ParitySequenceSolver(n, reader);
            writer.println(solver.solve());
        } catch (Exception e) {
            // In a real-world application, use a logger
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    /**
     * Solver class responsible for the dynamic programming logic.
     */
    static class ParitySequenceSolver {
        private static final int PARITY_NONE = 2;
        private static final int PARITY_EVEN = 0;
        private static final int PARITY_ODD = 1;

        private final int n;
        private final int[] sequence;
        private final int[][][][] memo;
        private final int initialEvenCount;
        private final int initialOddCount;

        public ParitySequenceSolver(int n, FastReader reader) {
            this.n = n;
            this.sequence = new int[n];
            boolean[] isNumberUsed = new boolean[n + 1];

            for (int i = 0; i < n; i++) {
                int val = reader.nextInt();
                sequence[i] = val;
                if (val != 0) {
                    isNumberUsed[val] = true;
                }
            }

            // Count how many even/odd numbers are still available to be placed
            int evenAvailable = 0;
            int oddAvailable = 0;
            for (int i = 1; i <= n; i++) {
                if (!isNumberUsed[i]) {
                    if (i % 2 == 0) {
                        evenAvailable++;
                    } else {
                        oddAvailable++;
                    }
                }
            }

            this.initialEvenCount = evenAvailable;
            this.initialOddCount = oddAvailable;

            // memo[index][remainingEvens][remainingOdds][lastParity]
            this.memo = new int[n][evenAvailable + 1][oddAvailable + 1][3];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j <= evenAvailable; j++) {
                    for (int k = 0; k <= oddAvailable; k++) {
                        Arrays.fill(memo[i][j][k], -1);
                    }
                }
            }
        }

        public int solve() {
            return computeMinSwitches(0, initialEvenCount, initialOddCount, PARITY_NONE);
        }

        /**
         * Recursive DP function with memoization.
         * 
         * @param index           Current index in the sequence being processed.
         * @param remainingEvens  Count of even numbers still available to use.
         * @param remainingOdds   Count of odd numbers still available to use.
         * @param lastParity      The parity of the previously placed number.
         * @return                The minimum parity switches from this state forward.
         */
        private int computeMinSwitches(int index, int remainingEvens, int remainingOdds, int lastParity) {
            if (index >= n) {
                return 0;
            }

            if (memo[index][remainingEvens][remainingOdds][lastParity] != -1) {
                return memo[index][remainingEvens][remainingOdds][lastParity];
            }

            int result;
            if (sequence[index] != 0) {
                // Number is pre-filled
                int currentParity = sequence[index] % 2;
                int switchPenalty = (lastParity != PARITY_NONE && lastParity != currentParity) ? 1 : 0;
                result = switchPenalty + computeMinSwitches(index + 1, remainingEvens, remainingOdds, currentParity);
            } else {
                // Number is a placeholder (0), we must choose an available parity
                int optionEven = Integer.MAX_VALUE;
                int optionOdd = Integer.MAX_VALUE;

                // Try placing an even number
                if (remainingEvens > 0) {
                    int switchPenalty = (lastParity != PARITY_NONE && lastParity != PARITY_EVEN) ? 1 : 0;
                    int res = computeMinSwitches(index + 1, remainingEvens - 1, remainingOdds, PARITY_EVEN);
                    if (res != Integer.MAX_VALUE) {
                        optionEven = switchPenalty + res;
                    }
                }

                // Try placing an odd number
                if (remainingOdds > 0) {
                    int switchPenalty = (lastParity != PARITY_NONE && lastParity != PARITY_ODD) ? 1 : 0;
                    int res = computeMinSwitches(index + 1, remainingEvens, remainingOdds - 1, PARITY_ODD);
                    if (res != Integer.MAX_VALUE) {
                        optionOdd = switchPenalty + res;
                    }
                }

                result = Math.min(optionEven, optionOdd);
            }

            return memo[index][remainingEvens][remainingOdds][lastParity] = result;
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the alternating array problem.
 * The goal is to minimize operations to make the array follow an alternating parity pattern.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        OutputWriter writer = new OutputWriter(System.out);

        Solver solver = new Solver(reader);
        solver.solve(writer);

        writer.close();
    }

    /**
     * Encapsulates the logic for solving the problem.
     */
    static class Solver {
        private final FastReader reader;
        private int n;
        private int[] a;
        private int availableOddSlots;
        private int availableEvenSlots;

        public Solver(FastReader reader) {
            this.reader = reader;
        }

        /**
         * Main solve method that reads input and iterates through potential parity patterns.
         */
        public void solve(OutputWriter out) {
            n = reader.nextInt();
            // a is size n + 2 to allow dummy boundaries at index 0 and n + 1
            a = new int[n + 2];

            for (int i = 1; i <= n; i++) {
                a[i] = reader.nextInt();
            }

            // We calculate the 'budget' of odd and even numbers available in the 0-slots
            // based on a fixed parity pattern (e.g., 1, 0, 1, 0...).
            int totalPatternOdds = (n + 1) / 2;
            int totalPatternEvens = n - totalPatternOdds;

            int fixedOdds = 0;
            int fixedEvens = 0;
            for (int i = 1; i <= n; i++) {
                if (a[i] != 0) {
                    if (a[i] % 2 != 0) {
                        fixedOdds++;
                    } else {
                        fixedEvens++;
                    }
                }
            }

            availableOddSlots = totalPatternOdds - fixedOdds;
            availableEvenSlots = totalPatternEvens - fixedEvens;

            int minOperations = Integer.MAX_VALUE;

            // We test 4 boundary parity combinations for a[0] and a[n+1] 
            // to cover all possible alternating parity starts and ends.
            int[][] boundaryParities = {
                {1, 1}, {2, 1}, {1, 2}, {2, 2}
            };

            for (int[] b : boundaryParities) {
                a[0] = b[0];
                a[n + 1] = b[1];
                minOperations = Math.min(minOperations, calculateMinOperations());
            }

            out.println(minOperations);
        }

        /**
         * Calculates the operations needed for the current configuration of dummy boundaries.
         */
        private int calculateMinOperations() {
            int mismatchCount = 0;
            int currentOddSlots = availableOddSlots;
            int currentEvenSlots = availableEvenSlots;

            List<Segment> sameParitySegments = new ArrayList<>();

            // Identify segments of zeros between non-zero elements
            int left = 0;
            for (int right = 1; right <= n + 1; right++) {
                if (a[right] != 0) {
                    if (a[left] % 2 != a[right] % 2) {
                        // If parities of boundaries are different, it's a forced transition
                        mismatchCount++;
                    } else {
                        // If parities are the same, we group the gap as a Segment
                        int gapLength = right - left - 1;
                        int parity = a[left] % 2;
                        sameParitySegments.add(new Segment(gapLength, parity));
                    }
                    left = right;
                }
            }

            // Sort segments by length to greedily use our parity budget
            Collections.sort(sameParitySegments);

            int extraOps = 0;
            for (Segment segment : sameParitySegments) {
                if (segment.parity != 0) { // Odd segment
                    if (segment.length <= currentOddSlots) {
                        currentOddSlots -= segment.length;
                    } else {
                        // If we can't fit the segment into the remaining odd budget, 
                        // it costs 2 operations to correct.
                        extraOps += 2;
                    }
                } else { // Even segment
                    if (segment.length <= currentEvenSlots) {
                        currentEvenSlots -= segment.length;
                    } else {
                        extraOps += 2;
                    }
                }
            }

            return mismatchCount + extraOps;
        }
    }

    /**
     * Represents a contiguous segment of zeros between two non-zero elements.
     */
    static class Segment implements Comparable<Segment> {
        final int length;
        final int parity;

        Segment(int length, int parity) {
            this.length = length;
            this.parity = parity;
        }

        @Override
        public int compareTo(Segment other) {
            if (this.length != other.length) {
                return Integer.compare(this.length, other.length);
            }
            return Integer.compare(this.parity, other.parity);
        }
    }

    /**
     * Efficient Input Reader using BufferedReader and StringTokenizer.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /**
     * Wrapper for PrintWriter for convenient output management.
     */
    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public void println(int val) {
            writer.println(val);
        }

        public void close() {
            writer.close();
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A solver that calculates the minimum number of parity switches (even to odd or vice versa)
 * in a sequence, where some elements are pre-filled and others are placeholders (0) 
 * to be filled by missing numbers from the range [1, n].
 */
public class ParitySwitchMinimizer {

    private static final int PARITY_EVEN = 0;
    private static final int PARITY_ODD = 1;
    private static final int PARITY_NONE = 2;
    private static final int INF = 1_000_000; // Sufficiently large value to avoid overflow

    private int arraySize;
    private int[] elements;
    private int[][][][] memo;

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        int n = reader.nextInt();
        if (n <= 0) {
            System.out.println(0);
            return;
        }

        int[] arr = new int[n];
        boolean[] isNumberPresent = new boolean[n + 1];
        for (int i = 0; i < n; i++) {
            arr[i] = reader.nextInt();
            if (arr[i] > 0 && arr[i] <= n) {
                isNumberPresent[arr[i]] = true;
            }
        }

        // Determine how many even and odd numbers are available to fill the '0' slots
        int evenAvailable = 0;
        int oddAvailable = 0;
        for (int i = 1; i <= n; i++) {
            if (!isNumberPresent[i]) {
                if (i % 2 == 0) {
                    evenAvailable++;
                } else {
                    oddAvailable++;
                }
            }
        }

        ParitySwitchMinimizer solver = new ParitySwitchMinimizer(n, arr, evenAvailable, oddAvailable);
        System.out.println(solver.solve());
    }

    public ParitySwitchMinimizer(int n, int[] arr, int evenAvailable, int oddAvailable) {
        this.arraySize = n;
        this.elements = arr;
        // DP Table dimensions: [index][even_remaining][odd_remaining][last_parity]
        this.memo = new int[n + 1][evenAvailable + 1][oddAvailable + 1][3];

        // Initialize memoization table with -1
        for (int[][][] layer3 : memo) {
            for (int[][] layer2 : layer3) {
                for (int[] layer1 : layer2) {
                    Arrays.fill(layer1, -1);
                }
            }
        }
    }

    public int solve() {
        return computeMinSwitches(0, getEvenAvailableCount(), getOddAvailableCount(), PARITY_NONE);
    }

    /**
     * Helper to get initial counts from the memo table structure.
     * This is just for determining table bounds.
     */
    private int getEvenAvailableCount() {
        return memo[0].length - 1;
    }

    private int getOddAvailableCount() {
        return memo[0][0].length - 1;
    }

    /**
     * Recursive DP function to find the minimum parity switches.
     *
     * @param idx            Current index in the sequence.
     * @param evensLeft      Count of even numbers still available to use.
     * @param oddsLeft       Count of odd numbers still available to use.
     * @param lastParity     The parity of the previous element (0=E, 1=O, 2=None).
     * @return               Minimum switches from this state to the end.
     */
    private int computeMinSwitches(int idx, int evensLeft, int oddsLeft, int lastParity) {
        if (idx == arraySize) {
            return 0;
        }

        if (memo[idx][evensLeft][oddsLeft][lastParity] != -1) {
            return memo[idx][evensLeft][oddsLeft][lastParity];
        }

        int result = INF;

        if (elements[idx] != 0) {
            // Case 1: The number is already provided
            int currentParity = elements[idx] % 2;
            int switchCost = calculateSwitchCost(lastParity, currentParity);
            result = switchCost + computeMinSwitches(idx + 1, evensLeft, oddsLeft, currentParity);
        } else {
            // Case 2: The number is a placeholder (0)
            // Try placing an even number
            if (evensLeft > 0) {
                int switchCost = calculateSwitchCost(lastParity, PARITY_EVEN);
                result = Math.min(result, switchCost + computeMinSwitches(idx + 1, evensLeft - 1, oddsLeft, PARITY_EVEN));
            }
            // Try placing an odd number
            if (oddsLeft > 0) {
                int switchCost = calculateSwitchCost(lastParity, PARITY_ODD);
                result = Math.min(result, switchCost + computeMinSwitches(idx + 1, evensLeft, oddsLeft - 1, PARITY_ODD));
            }
        }

        return memo[idx][evensLeft][oddsLeft][lastParity] = result;
    }

    /**
     * Calculates if a parity switch occurred.
     * A switch is only counted if there was a previous element and its parity differs.
     */
    private int calculateSwitchCost(int lastParity, int currentParity) {
        if (lastParity == PARITY_NONE) {
            return 0;
        }
        return (lastParity == currentParity) ? 0 : 1;
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }
    }
}

import java.util.Arrays;
import java.util.Scanner;

/**
 * A utility class to find the minimum number of parity changes required 
 * to satisfy a specific distribution of even and odd numbers in a sequence.
 */
public class ParitySequenceOptimizer {

    private static final int INF = 1_000_000; // Large constant to avoid overflow during addition
    private final int n;
    private final int[] numbers;
    private final int[][][][] memo;

    /**
     * @param n The total number of elements in the sequence.
     * @param numbers The input array where 0 represents a placeholder to be filled.
     */
    public ParitySequenceOptimizer(int n, int[] numbers) {
        this.n = n;
        this.numbers = numbers;
        // memo[index][evensLeft][oddsLeft][lastParity]
        // lastParity: 0 for even, 1 for odd
        this.memo = new int[n + 1][n + 1][n + 1][2];
        initializeMemo();
    }

    private void initializeMemo() {
        for (int[][][] d1 : memo) {
            for (int[][] d2 : d1) {
                for (int[] d3 : d2) {
                    Arrays.fill(d3, -1);
                }
            }
        }
    }

    /**
     * Initiates the recursive solver to find the minimum parity changes.
     * 
     * @param remainingEvens The number of even slots still required.
     * @param remainingOdds The number of odd slots still required.
     * @return The minimum number of parity changes.
     */
    public int findMinimumChanges(int remainingEvens, int remainingOdds) {
        // We pass 0 as the initial 'lastParity' because the idx == 0 check 
        // inside solve() ensures the first element never triggers a change cost.
        return solve(0, remainingEvens, remainingOdds, 0);
    }

    /**
     * Recursive DP function with memoization.
     */
    private int solve(int idx, int evensLeft, int oddsLeft, int lastParity) {
        // Base Case: If we've used more even/odd numbers than allowed
        if (evensLeft < 0 || oddsLeft < 0) {
            return INF;
        }

        // Base Case: Reached the end of the array
        if (idx == n) {
            return 0;
        }

        // Check memoization table
        if (memo[idx][evensLeft][oddsLeft][lastParity] != -1) {
            return memo[idx][evensLeft][oddsLeft][lastParity];
        }

        int result;

        if (numbers[idx] != 0) {
            // Fixed number: calculate its parity and add cost if it differs from lastParity
            int currentParity = Math.abs(numbers[idx] % 2);
            int cost = (idx == 0 || currentParity == lastParity) ? 0 : 1;
            result = cost + solve(idx + 1, evensLeft, oddsLeft, currentParity);
        } else {
            // Placeholder (0): Try both filling with an even number and an odd number

            // Option 1: Fill with Even (parity 0)
            int costEven = (idx == 0 || 0 == lastParity) ? 0 : 1;
            int evenRes = costEven + solve(idx + 1, evensLeft - 1, oddsLeft, 0);

            // Option 2: Fill with Odd (parity 1)
            int costOdd = (idx == 0 || 1 == lastParity) ? 0 : 1;
            int oddRes = costOdd + solve(idx + 1, evensLeft, oddsLeft - 1, 1);

            result = Math.min(evenRes, oddRes);
        }

        return memo[idx][evensLeft][oddsLeft][lastParity] = result;
    }

    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            if (!sc.hasNextInt()) {
                return;
            }

            int n = sc.nextInt();
            int[] a = new int[n];

            // Calculate target distribution
            int targetEvens = n / 2;
            int targetOdds = n - (n / 2);

            for (int i = 0; i < n; i++) {
                a[i] = sc.nextInt();
                // If the number is already fixed, reduce our target count
                if (a[i] != 0) {
                    if (Math.abs(a[i] % 2) == 0) {
                        targetEvens--;
                    } else {
                        targetOdds--;
                    }
                }
            }

            ParitySequenceOptimizer optimizer = new ParitySequenceOptimizer(n, a);
            int result = optimizer.findMinimumChanges(targetEvens, targetOdds);

            // If result is INF, it means no valid sequence can be formed
            if (result >= INF) {
                System.out.println("-1");
            } else {
                System.out.println(result);
            }
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * GarlandSolver calculates the minimum number of parity transitions 
 * required to complete a sequence using missing numbers.
 */
public class Garland implements Closeable {

    private static final int INF = 1_000_000;
    private final FastReader reader;
    private final PrintWriter writer;

    public Garland() {
        this.reader = new FastReader(System.in);
        this.writer = new PrintWriter(System.out);
    }

    /**
     * Main execution logic.
     */
    public void solve() {
        int sequenceLength = reader.nextInt();
        int[] inputSequence = new int[sequenceLength];
        boolean[] isNumberPresent = new boolean[sequenceLength + 1];

        for (int i = 0; i < sequenceLength; i++) {
            int val = reader.nextInt();
            inputSequence[i] = val;
            if (val > 0 && val <= sequenceLength) {
                isNumberPresent[val] = true;
            }
        }

        int missingOddCount = 0;
        int missingEvenCount = 0;

        for (int i = 1; i <= sequenceLength; i++) {
            if (!isNumberPresent[i]) {
                if (i % 2 == 0) {
                    missingEvenCount++;
                } else {
                    missingOddCount++;
                }
            }
        }

        // memo[currentIndex][prevParity][remainingOdd][remainingEven]
        // Using primitive int to avoid massive memory overhead of Integer objects
        int[][][][] memo = new int[sequenceLength][2][missingOddCount + 1][missingEvenCount + 1];
        for (int i = 0; i < sequenceLength; i++) {
            for (int j = 0; j < 2; j++) {
                for (int k = 0; k <= missingOddCount; k++) {
                    for (int l = 0; l <= missingEvenCount; l++) {
                        memo[i][j][k][l] = -1;
                    }
                }
            }
        }

        int result = calculateMinTransitions(
                inputSequence, 
                memo, 
                0, 
                0, // placeholder for prevParity before index 0
                missingOddCount, 
                missingEvenCount, 
                true // isFirstElement flag
        );

        writer.println(result >= INF ? -1 : result);
    }

    /**
     * Recursive method with memoization to find the minimum parity changes.
     * 
     * @param seq          The input array.
     * @param memo         Memoization table.
     * @param index        Current index in the sequence.
     * @param prevParity   Parity of the previous element (0 for even, 1 for odd).
     * @param oddRem       Remaining odd numbers available to use.
     * @param evenRem      Remaining even numbers available to use.
     * @param isFirst      Boolean flag to handle the lack of a "previous" element at index 0.
     * @return Minimum transitions.
     */
    private int calculateMinTransitions(int[] seq, int[][][][] memo, int index, int prevParity, int oddRem, int evenRem, boolean isFirst) {
        if (index == seq.length) {
            return 0;
        }

        // Use memoization if not the first element (first element doesn't have a 'prevParity' dependency)
        if (!isFirst && memo[index][prevParity][oddRem][evenRem] != -1) {
            return memo[index][prevParity][oddRem][evenRem];
        }

        int minCost = INF;

        if (seq[index] != 0) {
            // Case 1: The number is pre-determined in the sequence
            int currentParity = seq[index] % 2;
            int cost = isFirst ? 0 : (currentParity == prevParity ? 0 : 1);
            minCost = cost + calculateMinTransitions(seq, memo, index + 1, currentParity, oddRem, evenRem, false);
        } else {
            // Case 2: We must pick a missing number (0 represents a placeholder)

            // Try picking an odd number
            if (oddRem > 0) {
                int currentParity = 1;
                int cost = isFirst ? 0 : (currentParity == prevParity ? 0 : 1);
                minCost = Math.min(minCost, cost + calculateMinTransitions(seq, memo, index + 1, currentParity, oddRem - 1, evenRem, false));
            }

            // Try picking an even number
            if (evenRem > 0) {
                int currentParity = 0;
                int cost = isFirst ? 0 : (currentParity == prevParity ? 0 : 1);
                minCost = Math.min(minCost, cost + calculateMinTransitions(seq, memo, index + 1, currentParity, oddRem, evenRem - 1, false));
            }
        }

        if (!isFirst) {
            memo[index][prevParity][oddRem][evenRem] = minCost;
        }
        return minCost;
    }

    @Override
    public void close() throws IOException {
        reader.close();
        writer.close();
    }

    public static void main(String[] args) {
        try (Garland solver = new Garland()) {
            solver.solve();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /**
     * Utility class for fast I/O operations.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public void close() throws IOException {
            reader.close();
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * Refactored solution for the Grid Reachability problem.
 * The goal is to determine if all Green cells can reach the target cell (bottom-right)
 * without passing through or being adjacent to Blue cells.
 */
public class Solution {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int testCases = reader.nextInt();
            while (testCases-- > 0) {
                GridProblemSolver solver = new GridProblemSolver(reader);
                writer.println(solver.solve() ? "Yes" : "No");
            }
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            writer.flush();
            writer.close();
        }
    }

    static class CellType {
        static final int EMPTY = 0;
        static final int BLUE = 1;
        static final int GREEN = 2;
        static final int OBSTACLE = -1;
    }

    static class Cell {
        final int r, c;
        Cell(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    static class GridProblemSolver {
        private final FastReader reader;
        private static final int[][] DIRECTIONS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

        private int rows;
        private int cols;
        private int[][] grid;
        private int greenCellCount = 0;

        public GridProblemSolver(FastReader reader) {
            this.reader = reader;
        }

        public boolean solve() throws IOException {
            this.rows = reader.nextInt();
            this.cols = reader.nextInt();
            this.grid = new int[rows][cols];
            this.greenCellCount = 0;

            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                for (int j = 0; j < cols; j++) {
                    char ch = line.charAt(j);
                    if (ch == '.') {
                        grid[i][j] = CellType.EMPTY;
                    } else if (ch == 'G') {
                        grid[i][j] = CellType.GREEN;
                        greenCellCount++;
                    } else if (ch == 'B') {
                        grid[i][j] = CellType.BLUE;
                    } else {
                        grid[i][j] = CellType.OBSTACLE;
                    }
                }
            }

            // Edge case: No green cells and target is not Blue
            if (greenCellCount == 0 && grid[rows - 1][cols - 1] != CellType.BLUE) {
                return true;
            }

            // Step 1: Mark empty cells adjacent to Blue cells as obstacles
            markDangerZones();

            // Step 2: Check if the target cell is immediately invalid
            if (grid[rows - 1][cols - 1] == CellType.OBSTACLE || grid[rows - 1][cols - 1] == CellType.BLUE) {
                return false;
            }

            // Step 3: Perform BFS from the exit to find all reachable cells
            boolean[][] reachable = getReachabilityMap(rows - 1, cols - 1);

            // Step 4: Validate constraints
            return validatePathConstraints(reachable);
        }

        private void markDangerZones() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == CellType.BLUE) {
                        for (int[] dir : DIRECTIONS) {
                            int nr = i + dir[0];
                            int nc = j + dir[1];
                            if (isValid(nr, nc) && grid[nr][nc] == CellType.EMPTY) {
                                grid[nr][nc] = CellType.OBSTACLE;
                            }
                        }
                    }
                }
            }
        }

        private boolean[][] getReachabilityMap(int startR, int startC) {
            boolean[][] reachable = new boolean[rows][cols];
            boolean[][] visited = new boolean[rows][cols];
            Queue<Cell> queue = new LinkedList<>();

            queue.add(new Cell(startR, startC));
            visited[startR][startC] = true;
            reachable[startR][startC] = true;

            while (!queue.isEmpty()) {
                Cell current = queue.poll();

                for (int[] dir : DIRECTIONS) {
                    int nr = current.r + dir[0];
                    int nc = current.c + dir[1];

                    if (isValid(nr, nc) && !visited[nr][nc] && grid[nr][nc] != CellType.OBSTACLE) {
                        visited[nr][nc] = true;
                        reachable[nr][nc] = true;
                        queue.add(new Cell(nr, nc));
                    }
                }
            }
            return reachable;
        }

        private boolean validatePathConstraints(boolean[][] reachable) {
            // Constraint 1: All Green cells must be reachable from the target
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == CellType.GREEN && !reachable[i][j]) {
                        return false;
                    }
                }
            }

            // Constraint 2: No cell adjacent to a Blue cell should be part of the reachable path
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == CellType.BLUE) {
                        for (int[] dir : DIRECTIONS) {
                            int nr = i + dir[0];
                            int nc = j + dir[1];
                            if (isValid(nr, nc) && reachable[nr][nc]) {
                                return false;
                            }
                        }
                    }
                }
            }

            return true;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        public double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver for grid-based pathfinding problems involving blockers and goals.
 */
public class Main {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int testCases = scanner.nextInt();
        while (testCases-- > 0) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            char[][] grid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                grid[i] = scanner.next().toCharArray();
            }

            GridSolver solver = new GridSolver(grid, rows, cols);
            if (solver.solve()) {
                out.println("Yes");
            } else {
                out.println("No");
            }
        }
        out.flush();
        out.close();
    }

    /**
     * Contains the core logic for solving the grid problem.
     */
    static class GridSolver {
        private static final char GOAL = 'G';
        private static final char BLOCKER = 'B';
        private static final char WALL = '#';
        private static final char EMPTY = '.';

        private static final int[][] DIRECTIONS = {
            {-1, 0}, {1, 0}, {0, -1}, {0, 1}
        };

        private final char[][] grid;
        private final int rows;
        private final int cols;

        public GridSolver(char[][] grid, int rows, int cols) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
        }

        /**
         * Orchestrates the validation and reachability checks.
         * @return true if the grid configuration is valid and all goals are reachable.
         */
        public boolean solve() {
            boolean goalExists = false;
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == GOAL) {
                        goalExists = true;
                    }
                }
            }

            // Step 1: Apply blocker effects and check for immediate invalidity
            if (!applyBlockerEffects()) {
                return false;
            }

            // Step 2: Check special condition (exit blocked while goal exists)
            if (grid[rows - 1][cols - 1] == WALL && goalExists) {
                return false;
            }

            // Step 3: Check if all goal cells are reachable from the exit
            return checkAllGoalsReachable();
        }

        /**
         * Processes 'B' cells. If a 'B' is adjacent to a 'G', the configuration is invalid.
         * If a 'B' is adjacent to an empty '.', it turns it into a '#'.
         * @return true if no immediate invalidity is found.
         */
        private boolean applyBlockerEffects() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == BLOCKER) {
                        if (!processBlockerNeighbors(i, j)) {
                            return false;
                        }
                    }
                }
            }
            return true;
        }

        private boolean processBlockerNeighbors(int r, int c) {
            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                if (isWithinBounds(nr, nc)) {
                    if (grid[nr][nc] == GOAL) {
                        return false;
                    }
                    if (grid[nr][nc] == EMPTY) {
                        grid[nr][nc] = WALL;
                    }
                }
            }
            return true;
        }

        /**
         * Performs a DFS from the bottom-right corner to find all reachable cells.
         * @return true if every GOAL cell in the grid was visited.
         */
        private boolean checkAllGoalsReachable() {
            boolean[][] visited = new boolean[rows][cols];
            performDFS(rows - 1, cols - 1, visited);

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == GOAL && !visited[i][j]) {
                        return false;
                    }
                }
            }
            return true;
        }

        private void performDFS(int r, int c, boolean[][] visited) {
            if (!isWithinBounds(r, c) || grid[r][c] == WALL || visited[r][c]) {
                return;
            }

            visited[r][c] = true;

            for (int[] dir : DIRECTIONS) {
                performDFS(r + dir[0], c + dir[1], visited);
            }
        }

        private boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * High-performance scanner for fast I/O.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver for a maze-based puzzle where "danger" cells affect the surroundings
 * and all "goal" cells must be reachable from the exit (bottom-right corner).
 */
public class MazeSolver {

    private static final int[] ROW_DIRECTIONS = {1, -1, 0, 0};
    private static final int[] COL_DIRECTIONS = {0, 0, 1, -1};

    /**
     * Represents the possible types of cells in the maze.
     */
    enum CellType {
        EMPTY,
        WALL,
        GOAL,
        DANGER
    }

    public static void main(String[] args) throws IOException {
        InputReader reader = new InputReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        int testCases = reader.nextInt();
        while (testCases-- > 0) {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            String[] gridData = new String[rows];
            for (int i = 0; i < rows; i++) {
                gridData[i] = reader.next();
            }

            MazeProblem problem = new MazeProblem(rows, cols, gridData);
            writer.println(problem.solve() ? "Yes" : "No");
        }

        writer.close();
    }

    /**
     * Encapsulates the maze logic and state.
     */
    static class MazeProblem {
        private final int rows;
        private final int cols;
        private final CellType[][] grid;

        public MazeProblem(int rows, int cols, String[] gridData) {
            this.rows = rows;
            this.cols = cols;
            this.grid = new CellType[rows][cols];
            parseGrid(gridData);
        }

        private void parseGrid(String[] gridData) {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    char symbol = gridData[r].charAt(c);
                    if (symbol == '.') {
                        grid[r][c] = CellType.EMPTY;
                    } else if (symbol == '#') {
                        grid[r][c] = CellType.WALL;
                    } else if (symbol == 'G') {
                        grid[r][c] = CellType.GOAL;
                    } else {
                        grid[r][c] = CellType.DANGER;
                    }
                }
            }
        }

        /**
         * Executes the core logic to determine if the maze is solvable.
         * @return true if all goal cells are reachable from the exit.
         */
        public boolean solve() {
            // 1. Immediate failure if the exit is a danger zone
            if (grid[rows - 1][cols - 1] == CellType.DANGER) {
                return false;
            }

            // 2. Pre-process danger zones: 
            // Danger zones turn adjacent empty cells into walls and cannot be next to goals.
            if (!applyDangerZoneRules()) {
                return false;
            }

            // 3. Traverse the maze from the exit using BFS
            boolean[][] visited = performBFS();

            // 4. Check if all goal cells were reached during traversal
            return areAllGoalsReached(visited);
        }

        private boolean applyDangerZoneRules() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == CellType.DANGER) {
                        for (int i = 0; i < 4; i++) {
                            int nr = r + ROW_DIRECTIONS[i];
                            int nc = c + COL_DIRECTIONS[i];

                            if (isWithinBounds(nr, nc)) {
                                if (grid[nr][nc] == CellType.GOAL) {
                                    return false; // Danger next to goal is invalid
                                }
                                if (grid[nr][nc] == CellType.EMPTY) {
                                    grid[nr][nc] = CellType.WALL; // Danger turns empty to wall
                                }
                            }
                        }
                    }
                }
            }
            return true;
        }

        private boolean[][] performBFS() {
            boolean[][] visited = new boolean[rows][cols];
            int startR = rows - 1;
            int startC = cols - 1;

            // Only start traversal if the exit is not a wall
            if (grid[startR][startC] != CellType.WALL) {
                Deque<int[]> queue = new ArrayDeque<>();
                queue.add(new int[]{startR, startC});
                visited[startR][startC] = true;

                while (!queue.isEmpty()) {
                    int[] current = queue.poll();
                    int r = current[0];
                    int c = current[1];

                    for (int i = 0; i < 4; i++) {
                        int nr = r + ROW_DIRECTIONS[i];
                        int nc = c + COL_DIRECTIONS[i];

                        if (isWithinBounds(nr, nc) && !visited[nr][nc] && grid[nr][nc] != CellType.WALL) {
                            visited[nr][nc] = true;
                            queue.add(new int[]{nr, nc});
                        }
                    }
                }
            }
            return visited;
        }

        private boolean areAllGoalsReached(boolean[][] visited) {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == CellType.GOAL && !visited[r][c]) {
                        return false;
                    }
                }
            }
            return true;
        }

        private boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * Fast I/O utility for reading input.
     */
    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A refactored solution for the grid connectivity problem.
 * The algorithm processes a grid where 'B' (Blockers) can turn adjacent '.' paths into '#' (Walls).
 * It then checks if all 'G' (Goals) are reachable from the bottom-right corner of the grid.
 */
public class GridConnectivitySolver {

    private static final int[][] DIRECTIONS = {
        {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int testCases = reader.nextInt();
            while (testCases-- > 0) {
                out.println(solve(reader));
            }
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Processes a single test case.
     * 
     * @param reader The input reader.
     * @return "Yes" if all goals are reachable and configuration is valid, otherwise "No".
     * @throws IOException if input reading fails.
     */
    private static String solve(FastReader reader) throws IOException {
        int rows = reader.nextInt();
        int cols = reader.nextInt();
        char[][] grid = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            grid[i] = reader.next().toCharArray();
        }

        int totalGoals = countGoals(grid, rows, cols);

        // Step 1: Apply Blocker rules and check for immediate invalidity
        if (!applyBlockerRules(grid, rows, cols)) {
            return "No";
        }

        // Step 2: Check reachability of all goals from the bottom-right corner
        int remainingGoals = totalGoals;
        int startRow = rows - 1;
        int startCol = cols - 1;

        // If the exit itself is a wall, no goals can be reached (unless there were 0 goals)
        if (grid[startRow][startCol] != '#') {
            remainingGoals = calculateUnreachableGoals(grid, startRow, startCol, rows, cols, totalGoals);
        }

        return (remainingGoals == 0) ? "Yes" : "No";
    }

    private static int countGoals(char[][] grid, int rows, int cols) {
        int count = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 'G') {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Converts '.' adjacent to 'B' into '#'.
     * Returns false if a 'B' is adjacent to a 'G' (invalid configuration).
     */
    private static boolean applyBlockerRules(char[][] grid, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 'B') {
                    for (int[] dir : DIRECTIONS) {
                        int ni = i + dir[0];
                        int nj = j + dir[1];

                        if (isWithinBounds(ni, nj, rows, cols)) {
                            if (grid[ni][nj] == 'G') {
                                return false; 
                            } else if (grid[ni][nj] == '.') {
                                grid[ni][nj] = '#';
                            }
                        }
                    }
                }
            }
        }
        return true;
    }

    /**
     * Performs a BFS to find all reachable 'G' cells.
     * 
     * @return The number of goals that could NOT be reached.
     */
    private static int calculateUnreachableGoals(char[][] grid, int startR, int startC, int rows, int cols, int totalGoals) {
        int goalsFound = 0;
        boolean[][] visited = new boolean[rows][cols];
        Queue<int[]> queue = new ArrayDeque<>();

        queue.offer(new int[]{startR, startC});
        visited[startR][startC] = true;

        if (grid[startR][startC] == 'G') {
            goalsFound++;
        }

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int r = current[0];
            int c = current[1];

            for (int[] dir : DIRECTIONS) {
                int ni = r + dir[0];
                int nj = c + dir[1];

                if (isWithinBounds(ni, nj, rows, cols) && !visited[ni][nj] && grid[ni][nj] != '#') {
                    visited[ni][nj] = true;
                    if (grid[ni][nj] == 'G') {
                        goalsFound++;
                    }
                    queue.offer(new int[]{ni, nj});
                }
            }
        }

        return totalGoals - goalsFound;
    }

    private static boolean isWithinBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

