import java.util.*;

/**
 * A solver for grid-based pathfinding problems.
 * The goal is to determine if all 'G' (Goal) cells are reachable from the 
 * bottom-right corner after 'B' (Barrier) cells expand to adjacent empty cells.
 */
public class GridPathfinder {

    private static final int[] ROW_DIRS = {-1, 1, 0, 0};
    private static final int[] COL_DIRS = {0, 0, -1, 1};

    /**
     * Represents a coordinate in the 2D grid.
     */
    private record Point(int r, int c) {}

    public static void main(String[] args) throws IOException {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int testCases = reader.nextInt();
        for (int i = 0; i < testCases; i++) {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] grid = new char[rows][cols];

            for (int r = 0; r < rows; r++) {
                grid[r] = reader.next().toCharArray();
            }

            GridSolver solver = new GridSolver(grid, rows, cols);
            out.println(solver.solve() ? "Yes" : "No");
        }
        out.flush();
    }

    /**
     * Core logic handler for a single grid test case.
     */
    private static class GridSolver {
        private final char[][] grid;
        private final int rows;
        private final int cols;

        public GridSolver(char[][] grid, int rows, int cols) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
        }

        public boolean solve() {
            int totalGoals = 0;
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == 'G') {
                        totalGoals++;
                    }
                }
            }

            if (totalGoals == 0) {
                return true;
            }

            // 1. Process 'B' (Barriers) expansion and check validity
            if (applyBarrierExpansion()) {
                return false;
            }

            // 2. Check if the starting point is a wall
            if (grid[rows - 1][cols - 1] == '#') {
                return false;
            }

            // 3. BFS to count reachable goals from the bottom-right corner
            int reachableGoals = countReachableGoals(rows - 1, cols - 1);

            return reachableGoals == totalGoals;
        }

        /**
         * Expands 'B' cells to adjacent non-'B' and non-'G' cells.
         * Returns true if a 'B' cell is adjacent to a 'G' cell (invalid state).
         */
        private boolean applyBarrierExpansion() {
            boolean invalid = false;
            // We iterate through a copy or handle carefully to mimic original logic 
            // of modifying the grid in-place during iteration.
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == 'B') {
                        for (int i = 0; i < 4; i++) {
                            int nr = r + ROW_DIRS[i];
                            int nc = c + COL_DIRS[i];

                            if (isWithinBounds(nr, nc)) {
                                if (grid[nr][nc] == 'G') {
                                    invalid = true;
                                } else if (grid[nr][nc] != 'B') {
                                    grid[nr][nc] = '#';
                                }
                            }
                        }
                    }
                }
            }
            return invalid;
        }

        /**
         * Performs BFS starting from (startR, startC) to count how many 'G' cells can be reached.
         */
        private int countReachableGoals(int startR, int startC) {
            Queue<Point> queue = new LinkedList<>();
            boolean[][] visited = new boolean[rows][cols];
            int reachableCount = 0;

            queue.add(new Point(startR, startC));
            visited[startR][startC] = true;

            // If the starting cell itself is a goal, count it
            if (grid[startR][startC] == 'G') {
                reachableCount++;
            }

            while (!queue.isEmpty()) {
                Point current = queue.poll();

                for (int i = 0; i < 4; i++) {
                    int nr = current.r() + ROW_DIRS[i];
                    int nc = current.c() + COL_DIRS[i];

                    if (isWithinBounds(nr, nc) && !visited[nr][nc] && grid[nr][nc] != '#') {
                        visited[nr][nc] = true;
                        if (grid[nr][nc] == 'G') {
                            reachableCount++;
                        }
                        queue.add(new Point(nr, nc));
                    }
                }
            }
            return reachableCount;
        }

        private boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * Fast I/O utility class.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
            tokenizer = new StringTokenizer("");
        }

        public String next() throws IOException {
            while (!tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Main entry point for the Maze Solver application.
 */
public class Main {
    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            MazeSolver solver = new MazeSolver();
            solver.solve(reader, writer);
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        } finally {
            writer.close();
        }
    }

    /**
     * Represents a coordinate in the 2D grid.
     */
    static class Point {
        final int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Handles the logic for solving the maze puzzle.
     */
    static class MazeSolver {
        private static final char GOOD = 'G';
        private static final char BAD = 'B';
        private static final char EMPTY = '.';
        private static final char WALL = '#';

        private static final int[][] DIRECTIONS = {
            {0, -1}, {-1, 0}, {1, 0}, {0, 1}
        };

        public void solve(FastReader in, PrintWriter out) throws IOException {
            int testCases = in.nextInt();
            while (testCases-- > 0) {
                int rows = in.nextInt();
                int cols = in.nextInt();
                char[][] grid = new char[rows][];
                for (int i = 0; i < rows; i++) {
                    grid[i] = in.next().toCharArray();
                }

                boolean result = solveSingleMaze(rows, cols, grid);
                out.println(result ? "Yes" : "No");
            }
        }

        private boolean solveSingleMaze(int rows, int cols, char[][] grid) {
            // 1. Apply the "bomb" effect: Bad cells turn adjacent empty cells into walls.
            applyBombEffect(rows, cols, grid);

            // 2. Perform BFS from the bottom-right corner.
            boolean[][] visited = performBFS(rows, cols, grid);

            // 3. Validate if the path meets the requirements.
            return isPathValid(rows, cols, grid, visited);
        }

        private void applyBombEffect(int rows, int cols, char[][] grid) {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == BAD) {
                        for (int[] dir : DIRECTIONS) {
                            int nr = r + dir[0];
                            int nc = c + dir[1];
                            if (isWithinBounds(rows, cols, nr, nc) && grid[nr][nc] == EMPTY) {
                                grid[nr][nc] = WALL;
                            }
                        }
                    }
                }
            }
        }

        private boolean[][] performBFS(int rows, int cols, char[][] grid) {
            boolean[][] visited = new boolean[rows][cols];
            Queue<Point> queue = new LinkedList<>();

            // Start BFS from the bottom-right corner (r-1, c-1)
            int startR = rows - 1;
            int startC = cols - 1;

            if (isWithinBounds(rows, cols, startR, startC) && grid[startR][startC] != WALL) {
                visited[startR][startC] = true;
                queue.offer(new Point(startR, startC));
            }

            while (!queue.isEmpty()) {
                Point current = queue.poll();

                for (int[] dir : DIRECTIONS) {
                    int nr = current.r + dir[0];
                    int nc = current.c + dir[1];

                    if (isWithinBounds(rows, cols, nr, nc) 
                            && grid[nr][nc] != WALL 
                            && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        queue.offer(new Point(nr, nc));
                    }
                }
            }
            return visited;
        }

        private boolean isPathValid(int rows, int cols, char[][] grid, boolean[][] visited) {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    // Condition 1: No 'Bad' cell should be reachable.
                    if (grid[r][c] == BAD && visited[r][c]) {
                        return false;
                    }
                    // Condition 2: All 'Good' cells must be reachable.
                    if (grid[r][c] == GOOD && !visited[r][c]) {
                        return false;
                    }
                }
            }
            return true;
        }

        private boolean isWithinBounds(int rows, int cols, int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * High-performance input reader.
     */
    static class FastReader {
        private final InputStream in;
        private final byte[] buffer = new byte[1024];
        private int pointer = 0;
        private int bufferLength = 0;

        public FastReader(InputStream in) {
            this.in = in;
        }

        private int readByte() throws IOException {
            if (pointer >= bufferLength) {
                pointer = 0;
                bufferLength = in.read(buffer);
                if (bufferLength <= 0) return -1;
            }
            return buffer[pointer++];
        }

        public int nextInt() throws IOException {
            int c = readByte();
            while (c != -1 && isWhitespace(c)) c = readByte();
            if (c == -1) throw new InputMismatchException();

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }

            int res = 0;
            while (c != -1 && !isWhitespace(c)) {
                if (c >= '0' && c <= '9') {
                    res = res * 10 + (c - '0');
                } else {
                    throw new InputMismatchException();
                }
                c = readByte();
            }
            return res * sign;
        }

        public String next() throws IOException {
            int c = readByte();
            while (c != -1 && isWhitespace(c)) c = readByte();
            if (c == -1) return null;

            StringBuilder sb = new StringBuilder();
            while (c != -1 && !isWhitespace(c)) {
                sb.append((char) c);
                c = readByte();
            }
            return sb.toString();
        }

        private boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver for the grid reachability problem.
 * The goal is to determine if all 'Good' cells can reach the bottom-right corner
 * without passing through walls created by 'Bad' cells.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        int testCases = reader.nextInt();
        while (testCases-- > 0) {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] grid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            GridSolver solver = new GridSolver(rows, cols, grid);
            writer.println(solver.solve() ? "Yes" : "No");
        }
        writer.flush();
        writer.close();
    }

    /**
     * Represents a coordinate in the 2D grid.
     */
    record Point(int row, int col) {}

    /**
     * Handles the core logic of the grid processing and reachability analysis.
     */
    static class GridSolver {
        private final int rows;
        private final int cols;
        private final char[][] grid;

        private static final int[] DR = {0, 0, 1, -1};
        private static final int[] DC = {1, -1, 0, 0};

        private static final char GOOD = 'G';
        private static final char BAD = 'B';
        private static final char WALL = '#';

        public GridSolver(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
        }

        public boolean solve() {
            Set<Point> goodPoints = new HashSet<>();

            // 1. Identify all good points and validate initial grid state
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == GOOD) {
                        goodPoints.add(new Point(r, c));
                    }
                }
            }

            // 2. Pre-process the grid based on 'Bad' cell constraints
            if (!applyBadCellConstraints()) {
                return false;
            }

            // 3. Perform a single BFS from the destination to find all reachable cells
            return verifyReachability(goodPoints);
        }

        /**
         * Marks neighbors of 'Bad' cells as walls. 
         * If a 'Good' cell is adjacent to a 'Bad' cell, the configuration is invalid.
         * @return true if the grid is valid, false otherwise.
         */
        private boolean applyBadCellConstraints() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == BAD) {
                        for (int i = 0; i < 4; i++) {
                            int nr = r + DR[i];
                            int nc = c + DC[i];

                            if (isWithinBounds(nr, nc)) {
                                if (grid[nr][nc] == GOOD) {
                                    return false; // Good cell adjacent to Bad cell is invalid
                                }
                                if (grid[nr][nc] != BAD) {
                                    grid[nr][nc] = WALL;
                                }
                            }
                        }
                    }
                }
            }
            return true;
        }

        /**
         * Uses BFS starting from the target (bottom-right) to see which cells can reach it.
         * @param goodPoints the set of points that must be able to reach the target.
         * @return true if all good points are in the reachable set.
         */
        private boolean verifyReachability(Set<Point> goodPoints) {
            Point target = new Point(rows - 1, cols - 1);

            // If the target itself is a wall, nothing can reach it
            if (grid[target.row()][target.col()] == WALL) {
                return goodPoints.isEmpty();
            }

            boolean[][] reachable = new boolean[rows][cols];
            Deque<Point> queue = new ArrayDeque<>();

            queue.add(target);
            reachable[target.row()][target.col()] = true;

            while (!queue.isEmpty()) {
                Point curr = queue.poll();

                for (int i = 0; i < 4; i++) {
                    int nr = curr.row() + DR[i];
                    int nc = curr.col() + DC[i];

                    if (isWithinBounds(nr, nc) && !reachable[nr][nc] && grid[nr][nc] != WALL) {
                        reachable[nr][nc] = true;
                        queue.add(new Point(nr, nc));
                    }
                }
            }

            // Ensure every 'Good' point was marked as reachable
            for (Point p : goodPoints) {
                if (!reachable[p.row()][p.col()]) {
                    return false;
                }
            }

            return true;
        }

        private boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to solve a maze-based logic problem involving 'Bad' cells, 
 * 'Good' cells, and traversable paths.
 */
public class ProbD {

    public static void main(String[] args) {
        InputReader reader = new InputReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        MazeSolver solver = new MazeSolver();
        solver.solve(reader, writer);

        writer.flush();
        writer.close();
    }

    /**
     * Represents a coordinate in the 2D grid.
     */
    record Point(int row, int col) {}

    /**
     * Encapsulates the maze grid and its dimensions.
     */
    static class Maze {
        private final char[][] grid;
        private final int rows;
        private final int cols;

        static final char CELL_EMPTY = '.';
        static final char CELL_WALL = '#';
        static final char CELL_BAD = 'B';
        static final char CELL_GOOD = 'G';

        public Maze(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
        }

        public int getRows() { return rows; }
        public int getCols() { return cols; }
        public char getCell(int r, int c) { return grid[r][c]; }
        public void setCell(int r, int c, char value) { grid[r][c] = value; }

        public boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    static class MazeSolver {
        private static final int[][] DIRECTIONS = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

        public void solve(InputReader in, PrintWriter out) {
            int testCases = in.nextInt();
            for (int t = 0; t < testCases; t++) {
                out.println(processTestCase(in) ? "Yes" : "No");
            }
        }

        private boolean processTestCase(InputReader in) {
            int rows = in.nextInt();
            int cols = in.nextInt();
            char[][] gridData = new char[rows][cols];
            List<Point> badCells = new ArrayList<>();
            List<Point> goodCells = new ArrayList<>();

            for (int r = 0; r < rows; r++) {
                String line = in.nextToken();
                gridData[r] = line.toCharArray();
                for (int c = 0; c < cols; c++) {
                    char cell = gridData[r][c];
                    if (cell == Maze.CELL_BAD) {
                        badCells.add(new Point(r, c));
                    } else if (cell == Maze.CELL_GOOD) {
                        goodCells.add(new Point(r, c));
                    }
                }
            }

            Maze maze = new Maze(rows, cols, gridData);
            boolean[][] visited = new boolean[rows][cols];

            // 1. Check if any Bad cell can reach a Good cell
            for (Point bad : badCells) {
                if (!visited[bad.row()][bad.col()]) {
                    if (canBadReachGood(maze, bad.row(), bad.col(), visited)) {
                        return false;
                    }
                }
            }

            // 2. Check if the exit can reach all Good cells
            // We use the same visited array as per original logic requirements
            traverseFromExit(maze, rows - 1, cols - 1, visited);

            for (Point good : goodCells) {
                if (!visited[good.row()][good.col()]) {
                    return false;
                }
            }

            // 3. Edge case: If exit is a wall, it's only okay if there are no Good cells
            if (maze.getCell(rows - 1, cols - 1) == Maze.CELL_WALL) {
                return goodCells.isEmpty();
            }

            return true;
        }

        /**
         * DFS to simulate the spread of 'Bad' cells. 
         * It converts empty paths into walls to block them.
         */
        private boolean canBadReachGood(Maze maze, int r, int c, boolean[][] visited) {
            visited[r][c] = true;

            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                if (maze.isWithinBounds(nr, nc) && !visited[nr][nc]) {
                    char neighbor = maze.getCell(nr, nc);

                    if (neighbor == Maze.CELL_GOOD) {
                        return true; // Found a way for Bad to hit Good
                    } else if (neighbor == Maze.CELL_EMPTY) {
                        // Turn empty path into a wall and mark visited
                        maze.setCell(nr, nc, Maze.CELL_WALL);
                        visited[nr][nc] = true;
                    } else if (neighbor != Maze.CELL_WALL) {
                        // It's another Bad cell, recurse
                        if (canBadReachGood(maze, nr, nc, visited)) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        /**
         * DFS to check reachability from the exit.
         */
        private void traverseFromExit(Maze maze, int r, int c, boolean[][] visited) {
            if (!maze.isWithinBounds(r, c) || visited[r][c] || maze.getCell(r, c) == Maze.CELL_WALL) {
                return;
            }

            visited[r][c] = true;
            for (int[] dir : DIRECTIONS) {
                traverseFromExit(maze, r + dir[0], c + dir[1], visited);
            }
        }
    }

    /**
     * Fast I/O utility.
     */
    static class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public InputReader(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
        }

        public String nextToken() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(nextToken());
        }

        public long nextLong() {
            return Long.parseLong(nextToken());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * MazeSolver determines if all goal points in a maze can reach the exit.
 * It also processes obstacles that spread from specific source points.
 */
public class MazeSolver {

    // Constants for cell types to avoid magic characters
    private static final char WALL = '#';
    private static final char OBSTACLE_SOURCE = 'B';
    private static final char GOAL = 'G';
    private static final char PATH = '.';

    private char[][] grid;
    private boolean[][] visited;
    private int rows;
    private int cols;

    /**
     * Main execution loop for the solver.
     */
    public void solve() {
        InputReader in = new InputReader(System.in);
        OutputWriter out = new OutputWriter(System.out);

        int testCases = in.readInt();
        while (testCases-- > 0) {
            rows = in.readInt();
            cols = in.readInt();
            grid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                grid[i] = in.readString().toCharArray();
            }

            // If the exit is an obstacle source or a wall, it's immediately impossible.
            if (isExitBlocked(rows - 1, cols - 1)) {
                out.printLine("No");
                continue;
            }

            processObstacles();

            boolean isPossible = checkAllGoalsReachable();
            out.printLine(isPossible ? "Yes" : "No");
        }
        out.flush();
    }

    private boolean isExitBlocked(int r, int c) {
        return grid[r][c] == OBSTACLE_SOURCE || grid[r][c] == WALL;
    }

    /**
     * Finds all 'B' sources and expands the obstacles based on specific rules.
     */
    private void processObstacles() {
        visited = new boolean[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == OBSTACLE_SOURCE) {
                    expandObstacles(i, j);
                }
            }
        }
    }

    private void expandObstacles(int r, int c) {
        if (isOutOfBounds(r, c) || grid[r][c] == WALL || visited[r][c]) {
            return;
        }

        if (grid[r][c] == PATH) {
            // Rules state that if an obstacle hits a path, it turns it into a wall
            // and the expansion stops for that branch.
            grid[r][c] = WALL;
        } else {
            // If it hits a 'B' or 'G', it continues to spread.
            visited[r][c] = true;
            expandObstacles(r - 1, c);
            expandObstacles(r + 1, c);
            expandObstacles(r, c - 1);
            expandObstacles(r, c + 1);
        }
    }

    /**
     * Ensures every 'G' cell can find a path to the exit (bottom-right corner).
     */
    private boolean checkAllGoalsReachable() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == GOAL) {
                    // Reset visited array for each goal check
                    visited = new boolean[rows][cols];
                    if (!canReachExit(i, j)) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    private boolean canReachExit(int r, int c) {
        if (isOutOfBounds(r, c) || grid[r][c] == WALL || visited[r][c]) {
            return false;
        }

        // Target reached
        if (r == rows - 1 && c == cols - 1) {
            return grid[r][c] == GOAL || grid[r][c] == PATH;
        }

        visited[r][c] = true;

        // Explore neighbors
        return canReachExit(r + 1, c) ||
               canReachExit(r - 1, c) ||
               canReachExit(r, c + 1) ||
               canReachExit(r, c - 1);
    }

    private boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= rows || c < 0 || c >= cols;
    }

    public static void main(String[] args) {
        new MazeSolver().solve();
    }

    /**
     * Fast I/O implementation for reading large inputs efficiently.
     */
    static class InputReader {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (numChars == -1) throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) return -1;
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public String readString() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }

    /**
     * Fast I/O implementation for writing large outputs efficiently.
     */
    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public void printLine(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) writer.print(' ');
                writer.print(objects[i]);
            }
            writer.println();
        }

        public void flush() {
            writer.flush();
        }

        public void close() {
            writer.close();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A refactored solution for the grid-based connectivity problem.
 * The logic evaluates grid stability based on 'B' (bombs), 'G' (goals),
 * '.' (empty spaces), and '#' (walls) after bombs affect adjacent empty spaces.
 */
public class GridProblemSolver {

    private static final int[][] DIRECTIONS = {
            {0, 1}, {0, -1}, {1, 0}, {-1, 0}
    };

    public static void main(String[] args) {
        new GridProblemSolver().run();
    }

    /**
     * Entry point for the application.
     */
    public void run() {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            String firstLine = reader.readLine();
            if (firstLine == null || firstLine.trim().isEmpty()) return;

            int testCases = Integer.parseInt(firstLine.trim());

            while (testCases-- > 0) {
                processTestCase(reader, out);
            }
        } catch (Exception e) {
            // In a real-world scenario, use a logger instead of empty catch
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Orchestrates the logic for a single test case.
     */
    private void processTestCase(FastReader reader, PrintWriter out) throws IOException {
        String line = reader.readLine();
        if (line == null) return;

        StringTokenizer st = new StringTokenizer(line);
        int rows = Integer.parseInt(st.nextToken());
        int cols = Integer.parseInt(st.nextToken());

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String rowString = reader.readLine();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = rowString.charAt(j);
            }
        }

        // 1. Apply the bomb effect: 'B' turns adjacent '.' into '#'
        applyBombEffects(grid, rows, cols);

        // 2. Verify constraints: 
        //    - All 'G' components must reach the bottom-right corner.
        //    - No 'B' components should reach the bottom-right corner.
        boolean isPossible = checkGComponents(grid, rows, cols) && checkBComponents(grid, rows, cols);

        out.println(isPossible ? "Yes" : "No");
    }

    /**
     * Modifies the grid: any '.' adjacent to a 'B' becomes a wall '#'.
     */
    private void applyBombEffects(char[][] grid, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 'B') {
                    for (int[] dir : DIRECTIONS) {
                        int ni = i + dir[0];
                        int nj = j + dir[1];
                        if (ni >= 0 && ni < rows && nj >= 0 && nj < cols) {
                            if (grid[ni][nj] == '.') {
                                grid[ni][nj] = '#';
                            }
                        }
                    }
                }
            }
        }
    }

    /**
     * Validates that every connected component containing a 'G' cell 
     * can reach the destination (bottom-right corner).
     */
    private boolean checkGComponents(char[][] grid, int rows, int cols) {
        boolean[][] visitedG = new boolean[rows][cols];
        int targetR = rows - 1;
        int targetC = cols - 1;

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 'G' && !visitedG[i][j]) {
                    boolean reachesTarget = bfs(grid, i, j, targetR, targetC, visitedG);
                    if (!reachesTarget) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    /**
     * Validates that no connected component containing a 'B' cell 
     * can reach the destination (bottom-right corner).
     */
    private boolean checkBComponents(char[][] grid, int rows, int cols) {
        boolean[][] visitedB = new boolean[rows][cols];
        int targetR = rows - 1;
        int targetC = cols - 1;

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 'B' && !visitedB[i][j]) {
                    boolean reachesTarget = bfs(grid, i, j, targetR, targetC, visitedB);
                    if (reachesTarget) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    /**
     * Performs a Breadth-First Search to explore a connected component.
     * 
     * @return true if the target (targetR, targetC) is part of this component.
     */
    private boolean bfs(char[][] grid, int startR, int startC, int targetR, int targetC, boolean[][] visited) {
        int rows = grid.length;
        int cols = grid[0].length;
        Queue<int[]> queue = new LinkedList<>();

        queue.offer(new int[]{startR, startC});
        visited[startR][startC] = true;

        boolean targetFound = (startR == targetR && startC == targetC);

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int r = current[0];
            int c = current[1];

            if (r == targetR && c == targetC) {
                targetFound = true;
            }

            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols 
                        && grid[nr][nc] != '#' && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    queue.offer(new int[]{nr, nc});
                }
            }
        }
        return targetFound;
    }

    /**
     * Helper class for efficient input reading.
     */
    private static class FastReader {
        private final BufferedReader reader;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String readLine() throws IOException {
            return reader.readLine();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solution for the Maze Escape problem.
 * The goal is to determine if all 'Good' people can reach the exit at the bottom-right corner
 * after 'Beasts' have blocked adjacent empty paths.
 */
public class MazeEscapeSolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            int testCases = reader.nextInt();
            while (testCases-- > 0) {
                int rows = reader.nextInt();
                int cols = reader.nextInt();
                char[][] grid = reader.readGrid(rows, cols);

                MazeSolver solver = new MazeSolver(grid, rows, cols);
                writer.println(solver.solve() ? "Yes" : "No");
            }
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Encapsulates the logic for solving a single maze instance.
     */
    static class MazeSolver {
        private static final char BEAST = 'B';
        private static final char GOOD = 'G';
        private static final char EMPTY = '.';
        private static final char WALL = '#';

        private static final int[][] DIRECTIONS = {
            {0, 1}, {0, -1}, {1, 0}, {-1, 0}
        };

        private final char[][] grid;
        private final int rows;
        private final int cols;

        public MazeSolver(char[][] grid, int rows, int cols) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
        }

        public boolean solve() {
            // 1. Process beast effects: they turn adjacent empty spaces into walls.
            // If a beast is adjacent to a 'Good' person, they cannot escape.
            if (!applyBeastEffects()) {
                return false;
            }

            // 2. Count how many 'Good' people are in the maze.
            int totalGoodPeople = countTotalGoodPeople();
            if (totalGoodPeople == 0) {
                return true;
            }

            // 3. Use BFS starting from the exit (bottom-right) to see how many 'Good' people can reach it.
            int reachableGoodPeople = countReachableGoodPeople();

            return reachableGoodPeople == totalGoodPeople;
        }

        private boolean applyBeastEffects() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == BEAST) {
                        if (isBeastNearGoodPerson(r, c)) {
                            return false;
                        }
                        blockAdjacentEmptySpaces(r, c);
                    }
                }
            }
            return true;
        }

        private boolean isBeastNearGoodPerson(int r, int c) {
            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (isValid(nr, nc) && grid[nr][nc] == GOOD) {
                    return true;
                }
            }
            return false;
        }

        private void blockAdjacentEmptySpaces(int r, int c) {
            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (isValid(nr, nc) && grid[nr][nc] == EMPTY) {
                    grid[nr][nc] = WALL;
                }
            }
        }

        private int countTotalGoodPeople() {
            int count = 0;
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == GOOD) count++;
                }
            }
            return count;
        }

        private int countReachableGoodPeople() {
            // If the exit itself is a wall, no one can escape.
            if (grid[rows - 1][cols - 1] == WALL) {
                return 0;
            }

            Deque<Point> queue = new ArrayDeque<>();
            boolean[][] visited = new boolean[rows][cols];

            Point exit = new Point(rows - 1, cols - 1);
            queue.addLast(exit);
            visited[exit.r][exit.c] = true;

            int reachableGoodCount = 0;

            while (!queue.isEmpty()) {
                Point curr = queue.removeFirst();

                if (grid[curr.r][curr.c] == GOOD) {
                    reachableGoodCount++;
                }

                for (int[] dir : DIRECTIONS) {
                    int nr = curr.r + dir[0];
                    int nc = curr.c + dir[1];

                    if (isValid(nr, nc) && !visited[nr][nc] && grid[nr][nc] != WALL) {
                        visited[nr][nc] = true;
                        queue.addLast(new Point(nr, nc));
                    }
                }
            }

            return reachableGoodCount;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        private record Point(int r, int c) {}
    }

    /**
     * Utility class for fast I/O operations.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public char[][] readGrid(int rows, int cols) throws IOException {
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = next().toCharArray();
            }
            return grid;
        }
    }
}

import java.util.*;

/**
 * GridConnectivitySolver determines if all "Good" (G) cells in a grid are reachable 
 * from the exit (bottom-right corner), given that "Bad" (B) cells turn adjacent 
 * empty ('.') cells into walls ('#') and cannot be adjacent to "Good" cells.
 */
public class GridConnectivitySolver {

    private static final char WALL = '#';
    private static final char BAD = 'B';
    private static final char GOOD = 'G';
    private static final char EMPTY = '.';

    private static final int[][] DIRECTIONS = {
        {1, 0}, {-1, 0}, {0, 1}, {0, -1}
    };

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (scanner.hasNextInt()) {
            int testCases = scanner.nextInt();
            while (testCases-- > 0) {
                processTestCase(scanner);
            }
        }
        scanner.close();
    }

    /**
     * Orchestrates the logic for a single test case.
     */
    private static void processTestCase(Scanner scanner) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        char[][] grid = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        // Rule 1: Bad cells and Good cells cannot be adjacent.
        if (hasImmediateConflict(grid, rows, cols)) {
            System.out.println("No");
            return;
        }

        // Rule 2: Bad cells turn adjacent empty paths into walls.
        applyBadCellObstacles(grid, rows, cols);

        // Rule 3: Check if all Good cells are reachable from the exit.
        if (isAllGoodCellsReachable(grid, rows, cols)) {
            System.out.println("Yes");
        } else {
            System.out.println("No");
        }
    }

    /**
     * Checks if any 'B' cell is immediately adjacent to a 'G' cell.
     */
    private static boolean hasImmediateConflict(char[][] grid, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == BAD) {
                    for (int[] dir : DIRECTIONS) {
                        int nr = r + dir[0];
                        int nc = c + dir[1];
                        if (isWithinBounds(nr, nc, rows, cols) && grid[nr][nc] == GOOD) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Transforms adjacent '.' cells to '#' if they are next to a 'B' cell.
     */
    private static void applyBadCellObstacles(char[][] grid, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == BAD) {
                    for (int[] dir : DIRECTIONS) {
                        int nr = r + dir[0];
                        int nc = c + dir[1];
                        if (isWithinBounds(nr, nc, rows, cols) && grid[nr][nc] == EMPTY) {
                            grid[nr][nc] = WALL;
                        }
                    }
                }
            }
        }
    }

    /**
     * Performs connectivity analysis using BFS from the bottom-right corner.
     */
    private static boolean isAllGoodCellsReachable(char[][] grid, int rows, int cols) {
        boolean[][] visited = new boolean[rows][cols];
        int exitR = rows - 1;
        int exitC = cols - 1;

        // Start BFS from the exit if it's not a wall
        if (grid[exitR][exitC] != WALL) {
            performBFS(grid, rows, cols, exitR, exitC, visited);
        }

        // Verify if every 'G' cell was reached during BFS
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == GOOD && !visited[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Standard iterative BFS to find all reachable non-wall cells.
     */
    private static void performBFS(char[][] grid, int rows, int cols, int startR, int startC, boolean[][] visited) {
        Queue<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[]{startR, startC});
        visited[startR][startC] = true;

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int r = current[0];
            int c = current[1];

            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                if (isWithinBounds(nr, nc, rows, cols) && !visited[nr][nc] && grid[nr][nc] != WALL) {
                    visited[nr][nc] = true;
                    queue.offer(new int[]{nr, nc});
                }
            }
        }
    }

    /**
     * Helper to ensure coordinate access is within grid boundaries.
     */
    private static boolean isWithinBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to determine if all goal locations in a grid are reachable 
 * from the exit, considering barrier expansion rules.
 */
public class Main {

    // Constants representing the possible cell states in the grid
    private static final char GOAL = 'G';
    private static final char BARRIER = 'B';
    private static final char PATH = '.';
    private static final char WALL = '#';

    // Direction vectors for 4-way movement (Right, Down, Left, Up)
    private static final int[] ROW_DIRECTIONS = {0, 1, 0, -1};
    private static final int[] COL_DIRECTIONS = {1, 0, -1, 0};

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int testCases = reader.nextInt();
            while (testCases-- > 0) {
                int rows = reader.nextInt();
                int cols = reader.nextInt();
                char[][] grid = reader.readGrid(rows, cols);

                MazeSolver solver = new MazeSolver(grid);
                out.println(solver.solve());
            }
        } catch (IOException e) {
            // In a production environment, use a logging framework
            System.err.println("Error reading input: " + e.getMessage());
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Encapsulates the maze solving logic.
     */
    static class MazeSolver {
        private final char[][] grid;
        private final int rows;
        private final int cols;
        private boolean hasGoalsPresent = false;

        public MazeSolver(char[][] grid) {
            this.grid = grid;
            this.rows = grid.length;
            this.cols = grid[0].length;
        }

        /**
         * Orchestrates the logic to determine the outcome.
         * @return "Yes" if the conditions are met, "No" otherwise.
         */
        public String solve() {
            // 1. Check if any goal is immediately adjacent to a barrier
            if (checkImmediateDanger()) {
                return "No";
            }

            // 2. If no goals exist in the grid, the condition is trivially satisfied
            if (!hasGoalsPresent) {
                return "Yes";
            }

            // 3. Barriers spread to adjacent path cells
            expandBarriers();

            // 4. Check if the exit (bottom-right corner) is blocked
            if (grid[rows - 1][cols - 1] == WALL) {
                return "No";
            }

            // 5. Check if all goal cells are reachable from the exit via non-wall cells
            return canAllGoalsBeReached() ? "Yes" : "No";
        }

        /**
         * Scans for 'G' cells and checks if they are touching 'B' cells.
         * @return true if a goal is adjacent to a barrier.
         */
        private boolean checkImmediateDanger() {
            hasGoalsPresent = false;
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == GOAL) {
                        hasGoalsPresent = true;
                        if (isAdjacentTo(r, c, BARRIER)) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        /**
         * Converts adjacent '.' cells to '#' for every existing 'B' cell.
         */
        private void expandBarriers() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == BARRIER) {
                        for (int i = 0; i < 4; i++) {
                            int nr = r + ROW_DIRECTIONS[i];
                            int nc = c + COL_DIRECTIONS[i];
                            if (isWithinBounds(nr, nc) && grid[nr][nc] == PATH) {
                                grid[nr][nc] = WALL;
                            }
                        }
                    }
                }
            }
        }

        /**
         * Performs a BFS starting from the exit to find all reachable cells.
         * @return true if all 'G' cells were visited.
         */
        private boolean canAllGoalsBeReached() {
            boolean[][] visited = new boolean[rows][cols];
            Queue<Point> queue = new LinkedList<>();

            // BFS start point: bottom-right corner
            int startR = rows - 1;
            int startC = cols - 1;

            visited[startR][startC] = true;
            queue.add(new Point(startR, startC));

            while (!queue.isEmpty()) {
                Point current = queue.poll();

                for (int i = 0; i < 4; i++) {
                    int nr = current.row + ROW_DIRECTIONS[i];
                    int nc = current.col + COL_DIRECTIONS[i];

                    if (isWithinBounds(nr, nc) && !visited[nr][nc] && grid[nr][nc] != WALL) {
                        visited[nr][nc] = true;
                        queue.add(new Point(nr, nc));
                    }
                }
            }

            // Validate that all 'G' cells were marked as visited
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == GOAL && !visited[r][c]) {
                        return false;
                    }
                }
            }
            return true;
        }

        private boolean isAdjacentTo(int r, int c, char target) {
            for (int i = 0; i < 4; i++) {
                int nr = r + ROW_DIRECTIONS[i];
                int nc = c + COL_DIRECTIONS[i];
                if (isWithinBounds(nr, nc) && grid[nr][nc] == target) {
                    return true;
                }
            }
            return false;
        }

        private boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        /**
         * Simple immutable coordinate representation.
         */
        private static class Point {
            final int row, col;
            Point(int row, int col) {
                this.row = row;
                this.col = col;
            }
        }
    }

    /**
     * Efficient input reader for large datasets.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public char[][] readGrid(int rows, int cols) throws IOException {
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = next().toCharArray();
            }
            return grid;
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * MazeSolver solves a maze problem where bombs ('B') can destroy adjacent 
 * empty cells ('.'), and goals ('G') must remain reachable from the exit.
 */
public class MazeSolver {

    // Standard direction offsets for 4-way movement: Up, Down, Left, Right
    private static final int[] ROW_OFFSETS = {-1, 1, 0, 0};
    private static final int[] COL_OFFSETS = {0, 0, -1, 1};

    /**
     * Represents a coordinate in the 2D maze.
     */
    private static class Point {
        int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Fast I/O utility for efficient reading of large inputs.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        PrintWriter writer = new PrintWriter(System.out);

        int testCases = reader.nextInt();
        while (testCases-- > 0) {
            MazeSolver solver = new MazeSolver();
            writer.println(solver.solve(reader));
        }

        writer.flush();
        writer.close();
    }

    /**
     * Orchestrates the solving logic for a single test case.
     */
    public String solve(FastReader reader) {
        int rows = reader.nextInt();
        int cols = reader.nextInt();
        char[][] grid = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            String line = reader.next();
            grid[i] = line.toCharArray();
        }

        boolean isPossible = processBombs(grid, rows, cols);

        // If a bomb is directly adjacent to a goal, it's impossible to satisfy requirements
        if (!isPossible) {
            return "No";
        }

        // Check reachability from the exit (bottom-right corner)
        if (canReachAllGoals(grid, rows, cols)) {
            return "Yes";
        } else {
            return "No";
        }
    }

    /**
     * Processes bombs by converting adjacent empty cells ('.') into walls ('#').
     * If a bomb is next to a goal ('G'), it returns false immediately.
     */
    private boolean processBombs(char[][] grid, int rows, int cols) {
        boolean bombDestroyedGoal = false;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 'B') {
                    for (int i = 0; i < 4; i++) {
                        int nr = r + ROW_OFFSETS[i];
                        int nc = c + COL_OFFSETS[i];

                        if (isValid(nr, nc, rows, cols)) {
                            if (grid[nr][nc] == '.') {
                                grid[nr][nc] = '#';
                            } else if (grid[nr][nc] == 'G') {
                                bombDestroyedGoal = true;
                            }
                        }
                    }
                }
            }
        }
        return !bombDestroyedGoal;
    }

    /**
     * Uses BFS to determine if all goal cells ('G') are reachable from the exit (bottom-right).
     */
    private boolean canReachAllGoals(char[][] grid, int rows, int cols) {
        boolean[][] visited = new boolean[rows][cols];
        Queue<Point> queue = new LinkedList<>();

        // Start BFS from the exit (bottom-right)
        int startR = rows - 1;
        int startC = cols - 1;

        // The exit must be an empty cell or a goal to be a valid starting point
        if (grid[startR][startC] == '.' || grid[startR][startC] == 'G') {
            visited[startR][startC] = true;
            queue.add(new Point(startR, startC));
        }

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            for (int i = 0; i < 4; i++) {
                int nr = current.r + ROW_OFFSETS[i];
                int nc = current.c + COL_OFFSETS[i];

                if (isValid(nr, nc, rows, cols) && !visited[nr][nc]) {
                    // We can move through empty cells or goals
                    if (grid[nr][nc] == '.' || grid[nr][nc] == 'G') {
                        visited[nr][nc] = true;
                        queue.add(new Point(nr, nc));
                    }
                }
            }
        }

        // Verify if all 'G' cells were visited during BFS
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 'G' && !visited[r][c]) {
                    return false;
                }
            }
        }

        return true;
    }

    private boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

import java.io.*;
import java.util.*;

/**
 * A refactored solution for the Maze problem.
 * The goal is to determine if all goal cells ('G') are reachable from 
 * a starting point (bottom-right corner) given specific obstacle rules.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        MazeSolver solver = new MazeSolver(reader, writer);
        solver.solve();

        writer.flush();
        writer.close();
    }

    /**
     * Represents a coordinate in the 2D grid.
     */
    record Point(int row, int col) {}

    /**
     * Encapsulates the maze grid, its dimensions, and its traversal rules.
     */
    static class Maze {
        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final boolean[][] isObstacle;

        private static final int[] DR = {0, 1, 0, -1};
        private static final int[] DC = {1, 0, -1, 0};

        public Maze(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            this.isObstacle = new boolean[rows][cols];
            initializeObstacles();
        }

        private void initializeObstacles() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '#') {
                        isObstacle[r][c] = true;
                    } else if (grid[r][c] == 'B') {
                        markPoisonedNeighbors(r, c);
                    }
                }
            }
        }

        private void markPoisonedNeighbors(int r, int c) {
            for (int i = 0; i < 4; i++) {
                int nr = r + DR[i];
                int nc = c + DC[i];

                if (isValid(nr, nc)) {
                    // Neighbors become obstacles unless they are Goal ('G') or Bad ('B') cells
                    if (grid[nr][nc] != 'G' && grid[nr][nc] != 'B') {
                        isObstacle[nr][nc] = true;
                    }
                }
            }
        }

        public boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        public boolean isObstacle(int r, int c) {
            return isObstacle[r][c];
        }

        public char getCell(int r, int c) {
            return grid[r][c];
        }

        public int getRows() { return rows; }
        public int getCols() { return cols; }

        public List<Point> getGoalCells() {
            List<Point> goals = new ArrayList<>();
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == 'G') {
                        goals.add(new Point(r, c));
                    }
                }
            }
            return goals;
        }

        public boolean isAdjacentToBad(int r, int c) {
            for (int i = 0; i < 4; i++) {
                int nr = r + DR[i];
                int nc = c + DC[i];
                if (isValid(nr, nc) && grid[nr][nc] == 'B') {
                    return true;
                }
            }
            return false;
        }
    }

    /**
     * Contains the core logic to solve the maze problem.
     */
    static class MazeSolver {
        private final FastReader reader;
        private final PrintWriter writer;

        public MazeSolver(FastReader reader, PrintWriter writer) {
            this.reader = reader;
            this.writer = writer;
        }

        public void solve() {
            int totalTestCases = reader.nextInt();
            while (totalTestCases-- > 0) {
                processTestCase();
            }
        }

        private void processTestCase() {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] gridData = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                gridData[i] = line.toCharArray();
            }

            Maze maze = new Maze(rows, cols, gridData);

            if (isInvalid(maze)) {
                writer.println("No");
            } else {
                boolean allGoalsReachable = checkReachability(maze);
                writer.println(allGoalsReachable ? "Yes" : "No");
            }
        }

        /**
         * A configuration is invalid if any 'B' cell is directly adjacent to a 'G' cell.
         */
        private boolean isInvalid(Maze maze) {
            for (int r = 0; r < maze.getRows(); r++) {
                for (int c = 0; c < maze.getCols(); c++) {
                    if (maze.getCell(r, c) == 'G' && maze.isAdjacentToBad(r, c)) {
                        return true;
                    }
                }
            }
            return false;
        }

        /**
         * Uses BFS to determine if all 'G' cells can be reached from the bottom-right corner.
         */
        private boolean checkReachability(Maze maze) {
            int startR = maze.getRows() - 1;
            int startC = maze.getCols() - 1;

            // If starting point is an obstacle, no cells are reachable
            if (maze.isObstacle(startR, startC)) {
                return maze.getGoalCells().isEmpty();
            }

            boolean[][] visited = new boolean[maze.getRows()][maze.getCols()];
            Queue<Point> queue = new ArrayDeque<>();

            queue.add(new Point(startR, startC));
            visited[startR][startC] = true;

            int[] dr = {0, 1, 0, -1};
            int[] dc = {1, 0, -1, 0};

            while (!queue.isEmpty()) {
                Point curr = queue.poll();

                for (int i = 0; i < 4; i++) {
                    int nr = curr.row() + dr[i];
                    int nc = curr.col() + dc[i];

                    if (maze.isValid(nr, nc) && !visited[nr][nc] && !maze.isObstacle(nr, nc)) {
                        visited[nr][nc] = true;
                        queue.add(new Point(nr, nc));
                    }
                }
            }

            // Check if every Goal cell was visited during the traversal
            for (Point goal : maze.getGoalCells()) {
                if (!visited[goal.row()][goal.col()]) {
                    return false;
                }
            }

            return true;
        }
    }

    /**
     * Optimized reader for faster input processing.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            this.reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A program to solve a grid reachability problem.
 * The goal is to determine if all 'Good' cells can be reached from a target cell
 * without passing through 'Bad' cells or cells 'contaminated' by them.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        int testCases = reader.nextInt();
        while (testCases-- > 0) {
            int n = reader.nextInt();
            int m = reader.nextInt();

            char[][] grid = new char[n][m];
            List<Point> goodPoints = new ArrayList<>();

            for (int i = 0; i < n; i++) {
                String row = reader.next();
                for (int j = 0; j < m; j++) {
                    grid[i][j] = row.charAt(j);
                    if (grid[i][j] == GridSolver.CELL_GOOD) {
                        goodPoints.add(new Point(i, j));
                    }
                }
            }

            GridSolver solver = new GridSolver(n, m, grid, goodPoints);
            if (solver.solve()) {
                out.println("Yes");
            } else {
                out.println("No");
            }
        }
        out.flush();
        out.close();
    }

    /**
     * Represents a coordinate in the 2D grid.
     */
    record Point(int row, int col) {}

    /**
     * Handles the logic for solving the grid problem.
     */
    static class GridSolver {
        public static final char CELL_GOOD = 'G';
        public static final char CELL_BAD = 'B';
        public static final char CELL_EMPTY = '.';
        public static final char CELL_WALL = '#';

        private static final int[][] DIRECTIONS = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final List<Point> goodPoints;

        public GridSolver(int rows, int cols, char[][] grid, List<Point> goodPoints) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            this.goodPoints = goodPoints;
        }

        /**
         * Executes the two-phase algorithm.
         * @return true if the conditions are met, false otherwise.
         */
        public boolean solve() {
            // Phase 1: Spread "contamination" from Bad cells.
            // If a Bad cell can reach the target, the result is immediately "No".
            if (isTargetCorruptedByBad()) {
                return false;
            }

            // Phase 2: Check if all Good cells are reachable from the target 
            // while avoiding walls created in Phase 1.
            return areAllGoodCellsReachable();
        }

        private boolean isTargetCorruptedByBad() {
            Queue<Point> queue = new ArrayDeque<>();
            boolean[][] visited = new boolean[rows][cols];

            // Initialize queue with all Bad cells
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == CELL_BAD) {
                        queue.add(new Point(r, c));
                    }
                }
            }

            while (!queue.isEmpty()) {
                Point curr = queue.poll();

                if (visited[curr.row()][curr.col()]) {
                    continue;
                }
                visited[curr.row()][curr.col()] = true;

                // If a Bad cell reaches the bottom-right target
                if (curr.row() == rows - 1 && curr.col() == cols - 1) {
                    return true;
                }

                for (int[] dir : DIRECTIONS) {
                    int nr = curr.row() + dir[0];
                    int nc = curr.col() + dir[1];

                    if (isValid(nr, nc) && !visited[nr][nc]) {
                        char neighborCell = grid[nr][nc];
                        if (neighborCell == CELL_GOOD || neighborCell == CELL_BAD) {
                            queue.add(new Point(nr, nc));
                        } else if (neighborCell == CELL_EMPTY) {
                            // Mark empty cells adjacent to Bad paths as Walls
                            grid[nr][nc] = CELL_WALL;
                        }
                    }
                }
            }
            return false;
        }

        private boolean areAllGoodCellsReachable() {
            Queue<Point> queue = new ArrayDeque<>();
            boolean[][] visited = new boolean[rows][cols];

            Point target = new Point(rows - 1, cols - 1);

            // Start BFS from the target cell
            if (grid[target.row()][target.col()] != CELL_WALL) {
                queue.add(target);
            }

            while (!queue.isEmpty()) {
                Point curr = queue.poll();

                if (visited[curr.row()][curr.col()]) {
                    continue;
                }
                visited[curr.row()][curr.col()] = true;

                for (int[] dir : DIRECTIONS) {
                    int nr = curr.row() + dir[0];
                    int nc = curr.col() + dir[1];

                    if (isValid(nr, nc) && !visited[nr][nc] && grid[nr][nc] != CELL_WALL) {
                        queue.add(new Point(nr, nc));
                    }
                }
            }

            // Check if every Good cell was reached during the BFS
            for (Point p : goodPoints) {
                if (!visited[p.row()][p.col()]) {
                    return false;
                }
            }
            return true;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * Fast I/O utility for competitive programming style inputs.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A refactored solution for solving the Maze problem.
 * The logic determines if a path exists from the exit to the goal 
 * without passing through any bomb cells ('B').
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        FastWriter writer = new FastWriter(System.out);
        MazeSolver solver = new MazeSolver();

        try {
            int testCases = reader.nextInt();
            while (testCases-- > 0) {
                int rows = reader.nextInt();
                int cols = reader.nextInt();
                char[][] grid = new char[rows][cols];

                for (int i = 0; i < rows; i++) {
                    grid[i] = reader.next().toCharArray();
                }

                if (solver.solve(rows, cols, grid)) {
                    writer.println("Yes");
                } else {
                    writer.println("No");
                }
            }
        } catch (Exception e) {
            // Handle potential input errors
        } finally {
            writer.close();
        }
    }

    static class MazeSolver {
        private static final int[] DR = {0, 0, 1, -1};
        private static final int[] DC = {1, -1, 0, 0};

        /**
         * Solves the maze and returns true if the configuration is valid.
         */
        public boolean solve(int rows, int cols, char[][] grid) {
            applyBombEffects(rows, cols, grid);
            int[] distances = performBFS(rows, cols, grid);

            return validateSolution(rows, cols, grid, distances);
        }

        /**
         * Marks neighbors of 'B' (bombs) as impassable ('#') if they are currently empty ('.').
         */
        private void applyBombEffects(int rows, int cols, char[][] grid) {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == 'B') {
                        for (int i = 0; i < 4; i++) {
                            int nr = r + DR[i];
                            int nc = c + DC[i];
                            if (isValid(rows, cols, nr, nc) && grid[nr][nc] == '.') {
                                grid[nr][nc] = '#';
                            }
                        }
                    }
                }
            }
        }

        /**
         * Performs BFS starting from the exit (bottom-right cell).
         * @return An array of distances from the exit to every cell.
         */
        private int[] performBFS(int rows, int cols, char[][] grid) {
            int[] distances = new int[rows * cols];
            Arrays.fill(distances, -1);

            Deque<Integer> queue = new ArrayDeque<>();
            int exitIdx = (rows * cols) - 1;

            // The BFS starts from the bottom-right corner
            distances[exitIdx] = 0;
            queue.addLast(exitIdx);

            while (!queue.isEmpty()) {
                int curr = queue.removeFirst();
                int r = curr / cols;
                int c = curr % cols;

                for (int i = 0; i < 4; i++) {
                    int nr = r + DR[i];
                    int nc = c + DC[i];

                    if (isValid(rows, cols, nr, nc) && grid[nr][nc] != '#') {
                        int nextIdx = nr * cols + nc;
                        if (distances[nextIdx] == -1) {
                            distances[nextIdx] = distances[curr] + 1;
                            queue.addLast(nextIdx);
                        }
                    }
                }
            }
            return distances;
        }

        /**
         * Checks if the bomb and goal conditions are met.
         */
        private boolean validateSolution(int rows, int cols, char[][] grid, int[] distances) {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    int idx = r * cols + c;
                    // If a bomb is reachable from the exit
                    if (grid[r][c] == 'B' && distances[idx] != -1) {
                        return false;
                    }
                    // If the goal is not reachable from the exit
                    if (grid[r][c] == 'G' && distances[idx] == -1) {
                        return false;
                    }
                }
            }
            return true;
        }

        private boolean isValid(int rows, int cols, int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * Fast I/O implementation for high-performance reading.
     */
    static class FastReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int curChar;
        private int numChars;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (numChars == -1) throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buffer);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) return -1;
            }
            return buffer[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res *= 10;
                res += c & 15;
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }

    /**
     * Fast I/O implementation for high-performance writing.
     */
    static class FastWriter {
        private final PrintWriter writer;

        public FastWriter(OutputStream outputStream) {
            this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public void println(Object obj) {
            writer.println(obj);
        }

        public void close() {
            writer.close();
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * Solution to determine reachability of goals in a grid subject to 
 * blocking effects from specific source cells.
 */
public class Solution {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int testCases = scanner.nextInt();
        while (testCases-- > 0) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            char[][] gridData = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                gridData[i] = scanner.next().toCharArray();
            }

            Grid grid = new Grid(gridData);
            ReachabilitySolver solver = new ReachabilitySolver(grid);

            boolean isPossible = solver.solve();
            out.println(isPossible ? "Yes" : "No");
        }
        out.flush();
        out.close();
    }

    /**
     * Represents a coordinate in the grid.
     */
    private static class Point {
        final int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Manages the grid data and its transformations.
     */
    private static class Grid {
        private static final char PATH = '.';
        private static final char WALL = '#';
        private static final char BLOCK_SOURCE = 'B';
        private static final char GOAL = 'G';

        private static final int[][] DIRECTIONS = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

        private final char[][] cells;
        private final int rows;
        private final int cols;

        Grid(char[][] cells) {
            this.cells = cells;
            this.rows = cells.length;
            this.cols = cells[0].length;
        }

        public int getRows() { return rows; }
        public int getCols() { return cols; }

        public char getCell(int r, int c) {
            return cells[r][c];
        }

        public void setCell(int r, int c, char value) {
            cells[r][c] = value;
        }

        public boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        /**
         * Applies the blocking effect: neighbors of 'B' that are paths '.' 
         * turn into walls '#'.
         */
        public void applyBlockingEffect() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (cells[r][c] == BLOCK_SOURCE) {
                        blockNeighbors(r, c);
                    }
                }
            }
        }

        private void blockNeighbors(int r, int c) {
            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (isWithinBounds(nr, nc) && cells[nr][nc] == PATH) {
                    cells[nr][nc] = WALL;
                }
            }
        }

        public static int[][] getDirections() {
            return DIRECTIONS;
        }

        // Constants for access in Solver
        public static final char PATH_CHAR = PATH;
        public static final char WALL_CHAR = WALL;
        public static final char BLOCK_SOURCE_CHAR = BLOCK_SOURCE;
        public static final char GOAL_CHAR = GOAL;
    }

    /**
     * Contains the algorithm to check reachability.
     */
    private static class ReachabilitySolver {
        private final Grid grid;

        ReachabilitySolver(Grid grid) {
            this.grid = grid;
        }

        public boolean solve() {
            grid.applyBlockingEffect();
            boolean[][] visited = performBFS();
            return validateResults(visited);
        }

        private boolean[][] performBFS() {
            int rows = grid.getRows();
            int cols = grid.getCols();
            boolean[][] visited = new boolean[rows][cols];
            Queue<Point> queue = new LinkedList<>();

            // The starting point is the bottom-right corner.
            // Note: Per original logic, the BFS only expands if the starting cell is a PATH.
            int startR = rows - 1;
            int startC = cols - 1;

            if (grid.getCell(startR, startC) == Grid.PATH_CHAR) {
                queue.add(new Point(startR, startC));
            }

            // The starting cell is marked visited regardless of its type.
            visited[startR][startC] = true;

            while (!queue.isEmpty()) {
                Point current = queue.poll();

                for (int[] dir : Grid.getDirections()) {
                    int nr = current.r + dir[0];
                    int nc = current.c + dir[1];

                    if (grid.isWithinBounds(nr, nc) 
                            && !visited[nr][nc] 
                            && grid.getCell(nr, nc) != Grid.WALL_CHAR) {

                        visited[nr][nc] = true;
                        queue.add(new Point(nr, nc));
                    }
                }
            }
            return visited;
        }

        private boolean validateResults(boolean[][] visited) {
            for (int r = 0; r < grid.getRows(); r++) {
                for (int c = 0; c < grid.getCols(); c++) {
                    char cell = grid.getCell(r, c);

                    // All goals must be visited
                    if (cell == Grid.GOAL_CHAR && !visited[r][c]) {
                        return false;
                    }
                    // No block sources should be visited
                    if (cell == Grid.BLOCK_SOURCE_CHAR && visited[r][c]) {
                        return false;
                    }
                }
            }
            return true;
        }
    }

    /**
     * Fast I/O utility for efficient reading.
     */
    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A high-performance reader to handle large inputs efficiently.
 */
class FastReader {
    private final InputStream inputStream;
    private final byte[] buffer = new byte[8192];
    private int pointer = 0;
    private int bytesRead = 0;

    public FastReader(InputStream inputStream) {
        this.inputStream = inputStream;
    }

    private int readByte() {
        if (pointer >= bytesRead) {
            pointer = 0;
            try {
                bytesRead = inputStream.read(buffer);
            } catch (IOException e) {
                return -1;
            }
            if (bytesRead <= 0) return -1;
        }
        return buffer[pointer++] & 0xFF;
    }

    public int nextInt() {
        int c = readByte();
        while (c != -1 && c <= 32) c = readByte();
        if (c == -1) return 0;
        boolean neg = (c == '-');
        if (neg) c = readByte();
        int res = 0;
        while (c >= '0' && c <= '9') {
            res = res * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -res : res;
    }

    public String nextString() {
        int c = readByte();
        while (c != -1 && c <= 32) c = readByte();
        if (c == -1) return "";
        StringBuilder sb = new StringBuilder();
        while (c > 32) {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public char[] nextCharArray(int length) {
        int c = readByte();
        while (c != -1 && c <= 32) c = readByte();
        char[] arr = new char[length];
        for (int i = 0; i < length; i++) {
            arr[i] = (char) c;
            c = readByte();
        }
        return arr;
    }
}

/**
 * Contains the core logic for the Grid reachability problem.
 */
class GridProblemSolver {
    private static final int[] ROW_OFFSETS = {1, 0, -1, 0};
    private static final int[] COL_OFFSETS = {0, 1, 0, -1};

    private static final char CELL_EMPTY = '.';
    private static final char CELL_BLOCKER = 'B';
    private static final char CELL_GOAL = 'G';
    private static final char CELL_WALL = '#';

    private final int rows;
    private final int cols;
    private final char[][] grid;

    public GridProblemSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
    }

    public boolean solve() {
        int totalGoals = countGoals();
        if (totalGoals == 0) return true;

        if (!applyBlockerRules()) {
            return false;
        }

        // Check if target destination is blocked or invalid
        if (grid[rows - 1][cols - 1] == CELL_WALL) {
            return false;
        }

        return checkReachabilityOfAllGoals();
    }

    private int countGoals() {
        int count = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == CELL_GOAL) count++;
            }
        }
        return count;
    }

    /**
     * Rules: Neighbors of 'B' become walls. 
     * If a neighbor of 'B' is a Goal 'G', the configuration is invalid.
     */
    private boolean applyBlockerRules() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == CELL_BLOCKER) {
                    for (int i = 0; i < 4; i++) {
                        int nr = r + ROW_OFFSETS[i];
                        int nc = c + COL_OFFSETS[i];

                        if (isValid(nr, nc)) {
                            if (grid[nr][nc] == CELL_GOAL) {
                                return false; // Goal is immediately blocked by a Blocker
                            } else if (grid[nr][nc] == CELL_EMPTY) {
                                grid[nr][nc] = CELL_WALL;
                            }
                        }
                    }
                }
            }
        }
        return true;
    }

    /**
     * Uses BFS to traverse from the bottom-right corner to verify connectivity.
     */
    private boolean checkReachabilityOfAllGoals() {
        boolean[][] visited = new boolean[rows][cols];
        Queue<Integer> rowQueue = new ArrayDeque<>();
        Queue<Integer> colQueue = new ArrayDeque<>();

        rowQueue.add(rows - 1);
        colQueue.add(cols - 1);
        visited[rows - 1][cols - 1] = true;

        while (!rowQueue.isEmpty()) {
            int r = rowQueue.poll();
            int c = colQueue.poll();

            for (int i = 0; i < 4; i++) {
                int nr = r + ROW_OFFSETS[i];
                int nc = c + COL_OFFSETS[i];

                if (isValid(nr, nc) && !visited[nr][nc]) {
                    if (grid[nr][nc] == CELL_GOAL || grid[nr][nc] == CELL_EMPTY) {
                        visited[nr][nc] = true;
                        rowQueue.add(nr);
                        colQueue.add(nc);
                    } else if (grid[nr][nc] == CELL_BLOCKER) {
                        // If we hit a blocker during traversal, this path is invalid
                        return false;
                    }
                }
            }
        }

        // Final validation: Ensure all 'G' cells were visited
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == CELL_GOAL && !visited[i][j]) {
                    return false;
                }
            }
        }

        return true;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

/**
 * Main driver class.
 */
public class Main {
    public static void main(String[] args) {
        FastReader fr = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int testCases = fr.nextInt();
            for (int t = 0; t < testCases; t++) {
                int n = fr.nextInt();
                int m = fr.nextInt();
                char[][] grid = new char[n][m];
                for (int i = 0; i < n; i++) {
                    grid[i] = fr.nextCharArray(m);
                }

                GridProblemSolver solver = new GridProblemSolver(n, m, grid);
                if (solver.solve()) {
                    out.println("Yes");
                } else {
                    out.println("No");
                }
            }
        } catch (Exception e) {
            // Handle unexpected input errors
        } finally {
            out.flush();
            out.close();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver for the grid reachability problem.
 * The goal is to determine if all goal cells ('G') are reachable from the 
 * bottom-right corner without passing through walls ('#') or blockades ('B').
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        GridReachabilitySolver solver = new GridReachabilitySolver();
        solver.solve(reader, writer);

        writer.close();
    }

    static class GridReachabilitySolver {
        private static final char GOAL = 'G';
        private static final char BLOCKADE = 'B';
        private static final char WALL = '#';
        private static final char EMPTY = '.';

        // Direction vectors for 4-connectivity (Up, Down, Left, Right)
        private static final int[] DX = {-1, 1, 0, 0};
        private static final int[] DY = {0, 0, -1, 1};

        /**
         * Represents a coordinate in the 2D grid.
         */
        private record Point(int r, int c) {}

        public void solve(FastReader reader, PrintWriter writer) {
            int testCases = reader.nextInt();
            while (testCases-- > 0) {
                int rows = reader.nextInt();
                int cols = reader.nextInt();
                char[][] grid = new char[rows][cols];

                for (int i = 0; i < rows; i++) {
                    grid[i] = reader.next().toCharArray();
                }

                processGridWalls(grid, rows, cols);
                boolean[][] visited = performBFS(grid, rows, cols);

                if (isValidPath(grid, visited, rows, cols)) {
                    writer.println("Yes");
                } else {
                    writer.println("No");
                }
            }
        }

        /**
         * Turns adjacent empty cells into walls if they are next to a Blockade ('B').
         */
        private void processGridWalls(char[][] grid, int rows, int cols) {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == BLOCKADE) {
                        for (int d = 0; d < 4; d++) {
                            int ni = i + DX[d];
                            int nj = j + DY[d];
                            if (isWithinBounds(ni, nj, rows, cols) && grid[ni][nj] == EMPTY) {
                                grid[ni][nj] = WALL;
                            }
                        }
                    }
                }
            }
        }

        /**
         * Performs BFS starting from the bottom-right corner to find all reachable cells.
         */
        private boolean[][] performBFS(char[][] grid, int rows, int cols) {
            boolean[][] visited = new boolean[rows][cols];
            Deque<Point> queue = new ArrayDeque<>();

            // Starting point is the bottom-right corner
            int startR = rows - 1;
            int startC = cols - 1;

            // The BFS can only start if the starting cell is not a wall or blockade
            if (isWithinBounds(startR, startC, rows, cols) && grid[startR][startC] == EMPTY) {
                visited[startR][startC] = true;
                queue.addLast(new Point(startR, startC));
            }

            while (!queue.isEmpty()) {
                Point current = queue.removeFirst();

                for (int i = 0; i < 4; i++) {
                    int nr = current.r + DX[i];
                    int nc = current.c + DY[i];

                    if (isWithinBounds(nr, nc, rows, cols) 
                            && !visited[nr][nc] 
                            && grid[nr][nc] != WALL 
                            && grid[nr][nc] != BLOCKADE) {

                        visited[nr][nc] = true;
                        queue.addLast(new Point(nr, nc));
                    }
                }
            }
            return visited;
        }

        /**
         * Validates if the traversal satisfies the problem requirements:
         * 1. All 'G' cells must be visited.
         * 2. No 'B' cells should have been visited.
         */
        private boolean isValidPath(char[][] grid, boolean[][] visited, int rows, int cols) {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    // Condition 1: If it's a Goal, it MUST be visited
                    if (grid[i][j] == GOAL && !visited[i][j]) {
                        return false;
                    }
                    // Condition 2: If it's a Blockade, it MUST NOT be visited
                    if (grid[i][j] == BLOCKADE && visited[i][j]) {
                        return false;
                    }
                }
            }
            return true;
        }

        private boolean isWithinBounds(int r, int c, int rows, int cols) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            this.reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.*;

/**
 * GridPathfinder solves the problem of determining if all 'G' (Gold) cells 
 * are reachable from the bottom-right corner of a grid after applying 
 * specific obstacle rules based on 'B' (Bad) cells.
 */
public class GridPathfinder {

    private static final char GOLD = 'G';
    private static final char BAD = 'B';
    private static final char OBSTACLE = '#';
    private static final int[] ROW_DIRS = {-1, 1, 0, 0};
    private static final int[] COL_DIRS = {0, 0, -1, 1};

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            String tStr = reader.readLine();
            if (tStr == null) return;
            int testCases = Integer.parseInt(tStr);

            for (int i = 0; i < testCases; i++) {
                String[] dimensions = reader.readLine().split(" ");
                int rows = Integer.parseInt(dimensions[0]);
                int cols = Integer.parseInt(dimensions[1]);

                char[][] grid = new char[rows][cols];
                for (int r = 0; r < rows; r++) {
                    grid[r] = reader.readLine().toCharArray();
                }

                out.println(solve(rows, cols, grid) ? "Yes" : "No");
            }
        } catch (IOException | NumberFormatException e) {
            // Handle potential parsing errors
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Orchestrates the logic for a single test case.
     * 
     * @param rows Number of rows in the grid.
     * @param cols Number of columns in the grid.
     * @param grid The character grid.
     * @return true if all 'G' cells are reachable from (rows-1, cols-1), false otherwise.
     */
    private static boolean solve(int rows, int cols, char[][] grid) {
        // Step 1: Apply rules regarding 'B' cells.
        // If a 'B' is adjacent to a 'G', the condition fails immediately.
        if (hasInvalidBadNeighbor(rows, cols, grid)) {
            return false;
        }

        // Step 2: Perform BFS to find all reachable cells from the bottom-right.
        boolean[][] reachable = performPathfinding(rows, cols, grid, rows - 1, cols - 1);

        // Step 3: Verify if all 'G' cells were reached.
        return areAllGoldCellsReached(rows, cols, grid, reachable);
    }

    /**
     * Modifies the grid based on 'B' cells.
     * Neighbors of 'B' (that are not 'B') become obstacles ('#').
     * Returns true if a 'B' cell is adjacent to a 'G' cell.
     */
    private static boolean hasInvalidBadNeighbor(int rows, int cols, char[][] grid) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == BAD) {
                    for (int i = 0; i < 4; i++) {
                        int nr = r + ROW_DIRS[i];
                        int nc = c + COL_DIRS[i];

                        if (isValid(rows, cols, nr, nc)) {
                            if (grid[nr][nc] == GOLD) {
                                return true;
                            }
                            if (grid[nr][nc] != BAD) {
                                grid[nr][nc] = OBSTACLE;
                            }
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Uses iterative BFS to find all cells reachable from the starting coordinates.
     */
    private static boolean[][] performPathfinding(int rows, int cols, char[][] grid, int startR, int startC) {
        boolean[][] reachable = new boolean[rows][cols];

        // If starting cell is an obstacle, nothing is reachable
        if (!isValid(rows, cols, startR, startC) || grid[startR][startC] == OBSTACLE) {
            return reachable;
        }

        Deque<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[]{startR, startC});
        reachable[startR][startC] = true;

        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            int r = curr[0];
            int c = curr[1];

            for (int i = 0; i < 4; i++) {
                int nr = r + ROW_DIRS[i];
                int nc = c + COL_DIRS[i];

                if (isValid(rows, cols, nr, nc) 
                        && !reachable[nr][nc] 
                        && grid[nr][nc] != OBSTACLE) {
                    reachable[nr][nc] = true;
                    queue.offer(new int[]{nr, nc});
                }
            }
        }
        return reachable;
    }

    private static boolean areAllGoldCellsReached(int rows, int cols, char[][] grid, boolean[][] reachable) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == GOLD && !reachable[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    private static boolean isValid(int rows, int cols, int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Helper class for efficient input reading.
     */
    static class FastReader {
        private BufferedReader reader;

        public FastReader(java.io.InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String readLine() throws IOException {
            return reader.readLine();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver that determines if a path exists from the bottom-right corner of a grid 
 * to all 'Goal' cells without touching 'Obstacle' cells or walls created by obstacles.
 */
public class GridPathFinder {

    // Cell type constants
    private static final char EMPTY = '.';
    private static final char OBSTACLE = 'B';
    private static final char GOAL = 'G';
    private static final char WALL = '#';

    public static void main(String[] args) {
        new GridPathFinder().run();
    }

    /**
     * Main execution loop handling multiple test cases.
     */
    public void run() {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int testCases = scanner.nextInt();
        while (testCases-- > 0) {
            out.println(solve(scanner));
        }
        out.flush();
        out.close();
    }

    /**
     * Orchestrates the logic for a single test case.
     */
    private String solve(FastScanner scanner) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        char[][] grid = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        // Step 1: Any empty cell adjacent to an obstacle becomes a wall.
        markObstacleZones(grid, rows, cols);

        // Step 2: Perform BFS to find all reachable cells from the bottom-right corner.
        boolean[][] visited = performBFS(grid, rows, cols);

        // Step 3: Validate if the reachability meets the problem constraints.
        return isPathValid(grid, visited, rows, cols) ? "Yes" : "No";
    }

    /**
     * Marks empty cells adjacent to obstacles as walls.
     */
    private void markObstacleZones(char[][] grid, int rows, int cols) {
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == OBSTACLE) {
                    for (int i = 0; i < 4; i++) {
                        int nr = r + dr[i];
                        int nc = c + dc[i];
                        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
                            if (grid[nr][nc] == EMPTY) {
                                grid[nr][nc] = WALL;
                            }
                        }
                    }
                }
            }
        }
    }

    /**
     * Iterative BFS to find all reachable cells from (rows-1, cols-1).
     * Using BFS avoids StackOverflowError on large grids.
     */
    private boolean[][] performBFS(char[][] grid, int rows, int cols) {
        boolean[][] visited = new boolean[rows][cols];
        Deque<int[]> queue = new ArrayDeque<>();

        int startR = rows - 1;
        int startC = cols - 1;

        // If starting point is a wall, no cells are reachable.
        if (grid[startR][startC] != WALL) {
            visited[startR][startC] = true;
            queue.add(new int[]{startR, startC});
        }

        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int r = current[0];
            int c = current[1];

            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i];
                int nc = c + dc[i];

                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols 
                    && !visited[nr][nc] && grid[nr][nc] != WALL) {
                    visited[nr][nc] = true;
                    queue.add(new int[]{nr, nc});
                }
            }
        }
        return visited;
    }

    /**
     * Checks the two conditions:
     * 1. No obstacle ('B') was visited.
     * 2. All goal cells ('G') were visited.
     */
    private boolean isPathValid(char[][] grid, boolean[][] visited, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == OBSTACLE && visited[r][c]) {
                    return false;
                }
                if (grid[r][c] == GOAL && !visited[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Efficient input reader.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.util.*;

/**
 * A professional refactoring of the Maze Solver problem.
 * This class solves the problem of determining if all gold in a maze 
 * is reachable from the exit point, given that bombs can turn 
 * adjacent paths into walls.
 */
public class MazeSolverProgram {

    // Maze Character Constants
    private static final char GOLD = 'G';
    private static final char BOMB = 'B';
    private static final char PATH = '.';
    private static final char WALL = '#';

    // Directional vectors for 4-connectivity (Up, Down, Left, Right)
    private static final int[] ROW_DIRECTIONS = {-1, 1, 0, 0};
    private static final int[] COL_DIRECTIONS = {0, 0, -1, 1};

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int testCases = scanner.nextInt();
        while (testCases-- > 0) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            char[][] maze = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                String line = scanner.next();
                maze[i] = line.toCharArray();
            }

            MazeSolver solver = new MazeSolver(maze, rows, cols);
            System.out.println(solver.solve() ? "Yes" : "No");
        }
        scanner.close();
    }

    /**
     * Encapsulates the logic for solving a single maze instance.
     */
    static class MazeSolver {
        private final char[][] maze;
        private final int rows;
        private final int cols;

        public MazeSolver(char[][] maze, int rows, int cols) {
            this.maze = maze;
            this.rows = rows;
            this.cols = cols;
        }

        /**
         * Orchestrates the maze solving process.
         * @return true if all gold is reachable and no gold is adjacent to a bomb.
         */
        public boolean solve() {
            int totalGoldCount = countTotalGold();
            boolean isGoldInDanger = processBombs();

            // If a bomb is adjacent to gold, the condition fails immediately.
            if (isGoldInDanger) {
                return false;
            }

            int reachableGoldCount = countReachableGoldFromExit();
            return totalGoldCount == reachableGoldCount;
        }

        private int countTotalGold() {
            int count = 0;
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (maze[r][c] == GOLD) {
                        count++;
                    }
                }
            }
            return count;
        }

        /**
         * Processes bombs: turns adjacent '.' into walls and checks if any 'G' is adjacent.
         * @return true if any gold is adjacent to a bomb.
         */
        private boolean processBombs() {
            boolean goldAdjacentToBomb = false;

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (maze[r][c] == BOMB) {
                        for (int i = 0; i < 4; i++) {
                            int nr = r + ROW_DIRECTIONS[i];
                            int nc = c + COL_DIRECTIONS[i];

                            if (isValidMove(nr, nc)) {
                                if (maze[nr][nc] == GOLD) {
                                    goldAdjacentToBomb = true;
                                } else if (maze[nr][nc] == PATH) {
                                    maze[nr][nc] = WALL;
                                }
                            }
                        }
                    }
                }
            }
            return goldAdjacentToBomb;
        }

        /**
         * Uses Breadth-First Search to count how many gold pieces are reachable from the exit.
         * Exit is assumed to be at (rows-1, cols-1).
         */
        private int countReachableGoldFromExit() {
            int startR = rows - 1;
            int startC = cols - 1;

            // If the exit itself is a wall, no gold can be reached.
            if (!isValidMove(startR, startC) || maze[startR][startC] == WALL) {
                return 0;
            }

            int reachableGoldCount = 0;
            boolean[][] visited = new boolean[rows][cols];
            Queue<int[]> queue = new LinkedList<>();

            queue.offer(new int[]{startR, startC});
            visited[startR][startC] = true;

            while (!queue.isEmpty()) {
                int[] current = queue.poll();
                int r = current[0];
                int c = current[1];

                if (maze[r][c] == GOLD) {
                    reachableGoldCount++;
                }

                for (int i = 0; i < 4; i++) {
                    int nr = r + ROW_DIRECTIONS[i];
                    int nc = c + COL_DIRECTIONS[i];

                    if (isValidMove(nr, nc) && !visited[nr][nc] && maze[nr][nc] != WALL) {
                        visited[nr][nc] = true;
                        queue.offer(new int[]{nr, nc});
                    }
                }
            }

            return reachableGoldCount;
        }

        private boolean isValidMove(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }
}

