/**
 * Handles the logic for solving the grid reachability problem.
 */
class GridSolver {
    private static final int[][] DIRECTIONS = {
        {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    private final int rows;
    private final int cols;
    private final char[][] grid;

    public GridSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
    }

    /**
     * Executes the main logic: 
     * 1. Process 'B' (bombs) that turn adjacent '.' into '#'.
     * 2. Perform a DFS from the bottom-right corner.
     * 3. Verify if all 'G' (goals) are reached and no 'B' (bombs) are reached.
     */
    public boolean solve() {
        applyBombEffects();
        boolean[][] visited = performDepthFirstSearch();
        return validateSolution(visited);
    }

    /**
     * If a cell contains 'B', all adjacent '.' cells become '#' (walls).
     */
    private void applyBombEffects() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 'B') {
                    explodeBomb(r, c);
                }
            }
        }
    }

    private void explodeBomb(int r, int c) {
        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            if (isWithinBounds(nr, nc) && grid[nr][nc] == '.') {
                grid[nr][nc] = '#';
            }
        }
    }

    /**
     * Traverses the grid starting from the bottom-right corner (n-1, m-1).
     * Only traverses cells that are not walls ('#').
     */
    private boolean[][] performDepthFirstSearch() {
        boolean[][] visited = new boolean[rows][cols];
        Deque<Position> stack = new ArrayDeque<>();

        // Start from the exit point (bottom-right)
        int startR = rows - 1;
        int startC = cols - 1;

        if (isWithinBounds(startR, startC) && grid[startR][startC] != '#') {
            stack.push(new Position(startR, startC));
            visited[startR][startC] = true;
        }

        while (!stack.isEmpty()) {
            Position current = stack.pop();

            for (int[] dir : DIRECTIONS) {
                int nr = current.row() + dir[0];
                int nc = current.col() + dir[1];

                if (isWithinBounds(nr, nc) && grid[nr][nc] != '#' && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    stack.push(new Position(nr, nc));
                }
            }
        }
        return visited;
    }

    /**
     * Checks if the traversal meets the conditions:
     * - All 'G' cells must be visited.
     * - No 'B' cells must be visited.
     */
    private boolean validateSolution(boolean[][] visited) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                char cellType = grid[r][c];
                boolean wasVisited = visited[r][c];

                if (cellType == 'G' && !wasVisited) {
                    return false; // A goal was not reached
                }
                if (cellType == 'B' && wasVisited) {
                    return false; // A bomb was triggered
                }
            }
        }
        return true;
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

