import java.util.*;

/**
 * A program to determine if all 'Good' cells in a grid are reachable 
 * from the bottom-right corner without being adjacent to 'Bad' cells.
 */
public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int testCases = scanner.nextInt();

        while (testCases-- > 0) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            char[][] grid = new char[rows][cols];
            int totalGoodCells = 0;
            List<Point> badCells = new ArrayList<>();

            for (int i = 0; i < rows; i++) {
                String rowString = scanner.next();
                for (int j = 0; j < cols; j++) {
                    char cell = rowString.charAt(j);
                    grid[i][j] = cell;
                    if (cell == GridSolver.GOOD) {
                        totalGoodCells++;
                    } else if (cell == GridSolver.BAD) {
                        badCells.add(new Point(i, j));
                    }
                }
            }

            GridSolver solver = new GridSolver(grid, rows, cols, totalGoodCells, badCells);
            System.out.println(solver.solve() ? "Yes" : "No");
        }
        scanner.close();
    }

    /**
     * Represents a coordinate in the grid.
     */
    static class Point {
        final int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Encapsulates the logic for solving the grid problem.
     */
    static class GridSolver {
        public static final char GOOD = 'G';
        public static final char BAD = 'B';
        public static final char BLOCKED = '#';

        private static final int[][] DIRECTIONS = {
            {0, 1}, {0, -1}, {1, 0}, {-1, 0}
        };

        private final char[][] grid;
        private final int rows;
        private final int cols;
        private final int totalGoodCells;
        private final List<Point> badCells;

        public GridSolver(char[][] grid, int rows, int cols, int totalGoodCells, List<Point> badCells) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
            this.totalGoodCells = totalGoodCells;
            this.badCells = badCells;
        }

        /**
         * Orchestrates the solving steps.
         * @return true if all GOOD cells are reachable from bottom-right.
         */
        public boolean solve() {
            // If starting point is a BAD cell, it's impossible.
            if (grid[rows - 1][cols - 1] == BAD) {
                return false;
            }

            // Mark neighbors of BAD cells and check for proximity violations.
            if (!applyProximityRules()) {
                return false;
            }

            // If there are no GOOD cells, the condition is vacuously true.
            if (totalGoodCells == 0) {
                return true;
            }

            // Count how many GOOD cells can be reached via DFS.
            int reachedGoodCells = countReachableGoodCells();

            return reachedGoodCells == totalGoodCells;
        }

        /**
         * Marks cells adjacent to BAD cells as BLOCKED.
         * If a GOOD cell is adjacent to a BAD cell, the condition is violated.
         */
        private boolean applyProximityRules() {
            for (Point bad : badCells) {
                for (int[] dir : DIRECTIONS) {
                    int nr = bad.r + dir[0];
                    int nc = bad.c + dir[1];

                    if (isWithinBounds(nr, nc)) {
                        if (grid[nr][nc] == GOOD) {
                            return false; // A GOOD cell cannot be adjacent to a BAD cell.
                        } else if (grid[nr][nc] != BAD) {
                            grid[nr][nc] = BLOCKED; // Mark non-bad neighbors as unusable.
                        }
                    }
                }
            }
            return true;
        }

        /**
         * Performs an iterative DFS to count reachable GOOD cells.
         */
        private int countReachableGoodCells() {
            // If the starting point was marked BLOCKED by proximity rules.
            if (grid[rows - 1][cols - 1] == BLOCKED) {
                return 0;
            }

            int count = 0;
            Deque<Point> stack = new ArrayDeque<>();
            boolean[][] visited = new boolean[rows][cols];

            stack.push(new Point(rows - 1, cols - 1));

            while (!stack.isEmpty()) {
                Point curr = stack.pop();

                if (isInvalid(curr.r, curr.c, visited)) {
                    continue;
                }

                visited[curr.r][curr.c] = true;

                if (grid[curr.r][curr.c] == GOOD) {
                    count++;
                }

                for (int[] dir : DIRECTIONS) {
                    int nr = curr.r + dir[0];
                    int nc = curr.c + dir[1];
                    if (isWithinBounds(nr, nc) && !visited[nr][nc]) {
                        stack.push(new Point(nr, nc));
                    }
                }
            }
            return count;
        }

        private boolean isInvalid(int r, int c, boolean[][] visited) {
            return r < 0 || r >= rows || c < 0 || c >= cols 
                || visited[r][c] 
                || grid[r][c] == BLOCKED 
                || grid[r][c] == BAD;
        }

        private boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }
}

import java.util.*;

/**
 * MazeSolver solves a grid-based reachability problem.
 * It determines if all goal ('G') cells can be reached from the bottom-right destination,
 * even after certain 'B' cells are interacted with (which turns adjacent '.' cells into walls).
 */
public class MazeSolver {

    private static final int[] ROW_OFFSETS = {-1, 0, 1, 0};
    private static final int[] COL_OFFSETS = {0, 1, 0, -1};

    private final char[][] grid;
    private final int rows;
    private final int cols;

    public MazeSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
    }

    /**
     * Executes the logic for a single maze instance.
     * @return true if the maze satisfies the criteria, false otherwise.
     */
    public boolean solve() {
        // Initial check: Can we reach all goals from the destination?
        boolean[][] reachableFromEnd = new boolean[rows][cols];
        markReachableFrom(rows - 1, cols - 1, reachableFromEnd);

        if (!allGoalsAreReachable(reachableFromEnd)) {
            return false;
        }

        // Iterate through the grid to find 'B' cells that are currently reachable
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 'B' && reachableFromEnd[r][c]) {
                    // Interacting with 'B' modifies the maze
                    blockPathViaB(r, c);

                    // Re-calculate reachability after modification
                    reachableFromEnd = new boolean[rows][cols];
                    markReachableFrom(rows - 1, cols - 1, reachableFromEnd);

                    // If the 'B' cell is still reachable OR goals are no longer reachable, it's invalid
                    if (reachableFromEnd[r][c] || !allGoalsAreReachable(reachableFromEnd)) {
                        return false;
                    }
                }
            }
        }

        return true;
    }

    /**
     * Iterative DFS to mark all cells reachable from a starting coordinate.
     */
    private void markReachableFrom(int startR, int startC, boolean[][] reachable) {
        if (!isValid(startR, startC) || grid[startR][startC] == '#') {
            return;
        }

        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{startR, startC});
        reachable[startR][startC] = true;

        while (!stack.isEmpty()) {
            int[] current = stack.pop();
            int r = current[0];
            int c = current[1];

            for (int d = 0; d < 4; d++) {
                int nr = r + ROW_OFFSETS[d];
                int nc = c + COL_OFFSETS[d];

                if (isValid(nr, nc) && !reachable[nr][nc] && grid[nr][nc] != '#') {
                    reachable[nr][nc] = true;
                    stack.push(new int[]{nr, nc});
                }
            }
        }
    }

    /**
     * Iterative DFS that performs the side-effect of turning '.' into '#'
     * when traversing from a 'B' cell.
     */
    private void blockPathViaB(int startR, int startC) {
        boolean[][] visitedInBPath = new boolean[rows][cols];
        Deque<int[]> stack = new ArrayDeque<>();

        stack.push(new int[]{startR, startC});
        visitedInBPath[startR][startC] = true;

        while (!stack.isEmpty()) {
            int[] current = stack.pop();
            int r = current[0];
            int c = current[1];

            for (int d = 0; d < 4; d++) {
                int nr = r + ROW_OFFSETS[d];
                int nc = c + COL_OFFSETS[d];

                if (isValid(nr, nc) && grid[nr][nc] != '#') {
                    if (grid[nr][nc] == '.') {
                        // Side effect: turns empty path into a wall
                        grid[nr][nc] = '#';
                    } else if (!visitedInBPath[nr][nc]) {
                        visitedInBPath[nr][nc] = true;
                        stack.push(new int[]{nr, nc});
                    }
                }
            }
        }
    }

    /**
     * Checks if every 'G' cell in the grid is marked as reachable.
     */
    private boolean allGoalsAreReachable(boolean[][] reachable) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 'G' && !reachable[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        if (!sc.hasNextInt()) {
            return;
        }

        int testCases = sc.nextInt();
        while (testCases-- > 0) {
            int n = sc.nextInt();
            int m = sc.nextInt();
            char[][] mazeGrid = new char[n][m];

            for (int i = 0; i < n; i++) {
                mazeGrid[i] = sc.next().toCharArray();
            }

            MazeSolver solver = new MazeSolver(n, m, mazeGrid);
            if (solver.solve()) {
                System.out.println("Yes");
            } else {
                System.out.println("No");
            }
        }

        sc.close();
    }
}

import java.io.*;
import java.util.*;

/**
 * MazeSolver encapsulates the logic for determining if a path exists 
 * in a grid containing Bombs (B), Goals (G), and Paths (.).
 */
public class MazeSolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        try (PrintWriter writer = new PrintWriter(new BufferedOutputStream(System.out))) {
            int testCases = reader.nextInt();

            while (testCases-- > 0) {
                int rows = reader.nextInt();
                int cols = reader.nextInt();
                char[][] gridData = new char[rows][cols];

                for (int i = 0; i < rows; i++) {
                    gridData[i] = reader.next().toCharArray();
                }

                Maze maze = new Maze(gridData);
                writer.println(maze.solve() ? "Yes" : "No");
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * Represents a coordinate in the grid.
     */
    private record Point(int row, int col) {}

    /**
     * Handles the grid operations and pathfinding logic.
     */
    private static class Maze {
        private static final int[][] DIRECTIONS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

        private final char[][] grid;
        private final int rows;
        private final int cols;

        public Maze(char[][] grid) {
            this.grid = grid;
            this.rows = grid.length;
            this.cols = grid[0].length;
        }

        /**
         * Orchestrates the steps to solve the maze.
         */
        public boolean solve() {
            applyBombImpact();

            // The original logic specifically starts BFS only if the bottom-right is a path '.'
            boolean[][] visited = new boolean[rows][cols];
            if (isValid(rows - 1, cols - 1) && grid[rows - 1][cols - 1] == '.') {
                computeReachability(rows - 1, cols - 1, visited);
            }

            return validatePath(visited);
        }

        /**
         * Marks neighbors of 'B' (Bombs) as '#' (Blocked) if they are currently '.' (Paths).
         */
        private void applyBombImpact() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == 'B') {
                        for (int[] dir : DIRECTIONS) {
                            int nr = r + dir[0];
                            int nc = c + dir[1];
                            if (isValid(nr, nc) && grid[nr][nc] == '.') {
                                grid[nr][nc] = '#';
                            }
                        }
                    }
                }
            }
        }

        /**
         * Standard BFS to find all reachable non-blocked cells.
         */
        private void computeReachability(int startRow, int startCol, boolean[][] visited) {
            Queue<Point> queue = new LinkedList<>();
            queue.add(new Point(startRow, startCol));
            visited[startRow][startCol] = true;

            while (!queue.isEmpty()) {
                Point current = queue.poll();

                for (int[] dir : DIRECTIONS) {
                    int nr = current.row() + dir[0];
                    int nc = current.col() + dir[1];

                    if (isValid(nr, nc) && !visited[nr][nc] && grid[nr][nc] != '#') {
                        visited[nr][nc] = true;
                        queue.add(new Point(nr, nc));
                    }
                }
            }
        }

        /**
         * Checks if the solution meets requirements:
         * 1. All 'G' (Goals) must be visited.
         * 2. No 'B' (Bombs) must be visited.
         */
        private boolean validatePath(boolean[][] visited) {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == 'G' && !visited[r][c]) {
                        return false;
                    }
                    if (grid[r][c] == 'B' && visited[r][c]) {
                        return false;
                    }
                }
            }
            return true;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * Fast I/O utility for efficient reading.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Entry point for the application.
 * Handles input/output orchestration.
 */
public class Main {

    public static void main(String[] args) {
        try (InputReader input = new InputReader(System.in);
             PrintWriter output = new PrintWriter(System.out)) {

            int testCount = input.nextInt();
            for (int t = 0; t < testCount; t++) {
                solve(input, output);
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private static void solve(InputReader in, PrintWriter out) throws IOException {
        int rows = in.nextInt();
        int cols = in.nextInt();

        Grid grid = new Grid(rows, cols);
        for (int r = 0; r < rows; r++) {
            grid.setRow(r, in.next());
        }

        boolean possible = grid.canBlockAllBadPositions() && grid.areAllGoodPositionsReachable();
        out.println(possible ? "Yes" : "No");
    }

    /**
     * Represents a coordinate on the grid.
     */
    private record Position(int row, int col) {}

    /**
     * Manages the game board, including blocking logic and reachability checks.
     */
    private static class Grid {
        private static final char CHAR_BAD = 'B';
        private static final char CHAR_GOOD = 'G';
        private static final char CHAR_DEST = 'D';
        private static final char CHAR_WALL = '#';

        private final int rows;
        private final int cols;
        private final char[][] cells;
        private final Set<Position> badPositions = new HashSet<>();
        private final Set<Position> goodPositions = new HashSet<>();

        public Grid(int rows, int cols) {
            this.rows = rows;
            this.cols = cols;
            this.cells = new char[rows][cols];
        }

        public void setRow(int r, String rowData) {
            for (int c = 0; c < cols; c++) {
                char val = rowData.charAt(c);
                cells[r][c] = val;
                if (val == CHAR_BAD) {
                    badPositions.add(new Position(r, c));
                } else if (val == CHAR_GOOD) {
                    goodPositions.add(new Position(r, c));
                }
            }
        }

        /**
         * Attempts to block all 'B' positions using a cross pattern of walls.
         * @return true if all bad positions can be blocked without hitting G or D.
         */
        public boolean canBlockAllBadPositions() {
            // The destination is at the bottom-right
            cells[rows - 1][cols - 1] = CHAR_DEST;

            for (Position pos : badPositions) {
                if (!tryBlock(pos)) {
                    return false;
                }
            }
            return true;
        }

        private boolean tryBlock(Position pos) {
            List<Position> toBlock = new ArrayList<>();

            // Identify cells in the vertical cross
            for (int r = pos.row() - 1; r <= pos.row() + 1; r++) {
                if (isValid(r, pos.col())) {
                    if (isProtected(r, pos.col())) return false;
                    toBlock.add(new Position(r, pos.col()));
                }
            }

            // Identify cells in the horizontal cross
            for (int c = pos.col() - 1; c <= pos.col() + 1; c++) {
                if (isValid(pos.row(), c)) {
                    if (isProtected(pos.row(), c)) return false;
                    toBlock.add(new Position(pos.row(), c));
                }
            }

            // Apply walls after verifying the entire cross is valid
            for (Position p : toBlock) {
                cells[p.row()][p.col()] = CHAR_WALL;
            }
            return true;
        }

        private boolean isProtected(int r, int c) {
            return cells[r][c] == CHAR_GOOD || cells[r][c] == CHAR_DEST;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        /**
         * Performs an iterative DFS to see if all 'G' positions are reachable from the destination.
         */
        public boolean areAllGoodPositionsReachable() {
            if (goodPositions.isEmpty()) return true;

            boolean[][] reachable = new boolean[rows][cols];
            Deque<Position> stack = new ArrayDeque<>();

            // Start flood fill from the bottom-right destination
            Position start = new Position(rows - 1, cols - 1);
            stack.push(start);
            reachable[start.row()][start.col()] = true;

            int[] dRow = {-1, 1, 0, 0};
            int[] dCol = {0, 0, -1, 1};

            while (!stack.isEmpty()) {
                Position curr = stack.pop();

                for (int i = 0; i < 4; i++) {
                    int nr = curr.row() + dRow[i];
                    int nc = curr.col() + dCol[i];

                    if (isValid(nr, nc) && !reachable[nr][nc] && cells[nr][nc] != CHAR_WALL) {
                        reachable[nr][nc] = true;
                        stack.push(new Position(nr, nc));
                    }
                }
            }

            for (Position goodPos : goodPositions) {
                if (!reachable[goodPos.row()][goodPos.col()]) {
                    return false;
                }
            }
            return true;
        }
    }

    /**
     * Robust utility for reading input.
     */
    public static class InputReader implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream input) {
            this.reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        @Override
        public void close() throws IOException {
            reader.close();
        }
    }
}

