/**
 * Represents a point in the 2D grid.
 */
record Coordinate(int row, int col) {}

/**
 * Manages the grid state, including processing input characters and pathfinding.
 */
class Grid {
    private final int rows;
    private final int cols;
    private final char[][] matrix;
    private final Set<Coordinate> goodPeople = new HashSet<>();

    // Directions: Up, Down, Left, Right
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public Grid(int rows, int cols) {
        this.rows = rows;
        this.cols = cols;
        this.matrix = new char[rows][cols];
    }

    /**
     * Populates the grid row by row based on input characters.
     */
    public void populateRow(int r, String rowData) {
        for (int c = 0; c < cols; c++) {
            processCell(r, c, rowData.charAt(c));
        }
    }

    private void processCell(int r, int c, char type) {
        switch (type) {
            case 'G' -> {
                // Good person: cell becomes traversable unless it's a wall
                if (matrix[r][c] != '#') {
                    matrix[r][c] = '.';
                }
                goodPeople.add(new Coordinate(r, c));
            }
            case 'B' -> {
                // Bomb: adjacent cells become walls
                markNeighborsAsWalls(r, c);
            }
            default -> {
                // Other characters (like '.'): set cell unless it's already a wall
                if (matrix[r][c] != '#') {
                    matrix[r][c] = type;
                }
            }
        }
    }

    private void markNeighborsAsWalls(int r, int c) {
        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];
            if (isValid(nr, nc)) {
                matrix[nr][nc] = '#';
            }
        }
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Determines if all good people are reachable from the bottom-right corner.
     */
    public boolean canReachAllGoodPeople() {
        // If the exit itself is blocked, we only succeed if there are no good people to find
        if (matrix[rows - 1][cols - 1] == '#') {
            return goodPeople.isEmpty();
        }

        return performBFS();
    }

    private boolean performBFS() {
        Queue<Coordinate> queue = new LinkedList<>();
        Set<Coordinate> visited = new HashSet<>();
        int foundGoodPeopleCount = 0;

        Coordinate start = new Coordinate(rows - 1, cols - 1);
        queue.offer(start);
        visited.add(start);

        // Check if the starting position itself is a good person
        if (goodPeople.contains(start)) {
            foundGoodPeopleCount++;
        }

        while (!queue.isEmpty()) {
            Coordinate current = queue.poll();

            for (int i = 0; i < 4; i++) {
                int nr = current.row() + DR[i];
                int nc = current.col() + DC[i];
                Coordinate neighbor = new Coordinate(nr, nc);

                if (isValid(nr, nc) 
                        && !visited.contains(neighbor) 
                        && matrix[nr][nc] == '.') {

                    visited.add(neighbor);
                    queue.offer(neighbor);

                    if (goodPeople.contains(neighbor)) {
                        foundGoodPeopleCount++;
                    }
                }
            }
        }

        return foundGoodPeopleCount == goodPeople.size();
    }
}

import java.util.*;

/**
 * A solver for the grid reachability problem.
 * The problem involves navigating a grid where 'B' cells create boundaries,
 * and 'G' cells must be reached from a starting exit point.
 */
public class GridProblemSolver {

    /**
     * Represents a coordinate point in the grid.
     */
    private static class Coordinate {
        final int row;
        final int col;

        Coordinate(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    private static final int[] ROW_DIRECTIONS = {-1, 0, 1, 0};
    private static final int[] COL_DIRECTIONS = {0, 1, 0, -1};
    private static final char WALL = '#';
    private static final char BOUNDARY_CELL = 'B';
    private static final char GOAL_CELL = 'G';
    private static final char EMPTY_CELL = '.';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int testCases = scanner.nextInt();

        while (testCases-- > 0) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            char[][] grid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                grid[i] = scanner.next().toCharArray();
            }

            GridProblem problem = new GridProblem(grid, rows, cols);
            System.out.println(problem.solve());
        }
        scanner.close();
    }

    /**
     * Encapsulates the logic for a single grid instance.
     */
    static class GridProblem {
        private final char[][] grid;
        private final int rows;
        private final int cols;
        private int goalCount = 0;

        public GridProblem(char[][] grid, int rows, int cols) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
        }

        public String solve() {
            // 1. Process 'B' cells to expand their boundaries
            expandBoundariesAroundB();

            // 2. Count 'G' cells
            countGoals();

            // 3. If no goals exist, the condition is vacuously true
            if (goalCount == 0) {
                return "Yes";
            }

            // 4. If the starting/exit point is a wall, it's impossible
            if (grid[rows - 1][cols - 1] == WALL) {
                return "No";
            }

            // 5. Perform BFS to find all reachable cells from the exit (bottom-right)
            boolean[][] reachable = computeReachability(rows - 1, cols - 1);

            // 6. Validate if all 'G' are reached and no 'B' are reached
            return validateReachability(reachable) ? "Yes" : "No";
        }

        private void expandBoundariesAroundB() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == BOUNDARY_CELL) {
                        applyBoundaryEffects(r, c);
                    }
                }
            }
        }

        private void applyBoundaryEffects(int r, int c) {
            for (int i = 0; i < 4; i++) {
                int nr = r + ROW_DIRECTIONS[i];
                int nc = c + COL_DIRECTIONS[i];

                if (isWithinBounds(nr, nc) && grid[nr][nc] == EMPTY_CELL) {
                    grid[nr][nc] = WALL;
                }
            }
        }

        private void countGoals() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == GOAL_CELL) {
                        goalCount++;
                    }
                }
            }
        }

        private boolean[][] computeReachability(int startR, int startC) {
            boolean[][] visited = new boolean[rows][cols];
            Queue<Coordinate> queue = new LinkedList<>();

            queue.add(new Coordinate(startR, startC));
            visited[startR][startC] = true;

            while (!queue.isEmpty()) {
                Coordinate current = queue.poll();

                for (int i = 0; i < 4; i++) {
                    int nr = current.row + ROW_DIRECTIONS[i];
                    int nc = current.col + COL_DIRECTIONS[i];

                    if (isValidMove(nr, nc, visited)) {
                        visited[nr][nc] = true;
                        queue.add(new Coordinate(nr, nc));
                    }
                }
            }
            return visited;
        }

        private boolean isValidMove(int r, int c, boolean[][] visited) {
            return isWithinBounds(r, c) && !visited[r][c] && grid[r][c] != WALL;
        }

        private boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        private boolean validateReachability(boolean[][] reachable) {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    // If a Boundary cell is reachable, it's an invalid path
                    if (grid[r][c] == BOUNDARY_CELL && reachable[r][c]) {
                        return false;
                    }
                    // If a Goal cell is NOT reachable, it's an invalid path
                    if (grid[r][c] == GOAL_CELL && !reachable[r][c]) {
                        return false;
                    }
                }
            }
            return true;
        }
    }
}

