import java.util.*;

/**
 * A refactored solution for the Maze problem.
 * The goal is to determine if all Gold ('G') can be reached from the exit (n-1, m-1)
 * without passing through any Bombs ('B') or obstacles ('#').
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        FastWriter writer = new FastWriter(System.out);
        MazeSolver solver = new MazeSolver();

        try {
            int testCases = reader.nextInt();
            while (testCases-- > 0) {
                int rows = reader.nextInt();
                int cols = reader.nextInt();
                char[][] gridData = reader.readGrid(rows, cols);

                String result = solver.solve(rows, cols, gridData);
                writer.println(result);
            }
        } catch (Exception e) {
            // In a real-world scenario, use a proper logger
        } finally {
            writer.close();
        }
    }

    /**
     * Core logic for solving the maze problem.
     */
    static class MazeSolver {
        private static final int[] DX = {-1, 0, 1, 0};
        private static final int[] DY = {0, 1, 0, -1};

        public String solve(int rows, int cols, char[][] gridData) {
            Grid grid = new Grid(rows, cols, gridData);

            if (grid.getGoldCount() == 0) {
                return "Yes";
            }

            preprocessBombs(grid);
            performBFS(grid);

            return isSolutionValid(grid) ? "Yes" : "No";
        }

        /**
         * Marks cells adjacent to bombs as obstacles if they are empty paths.
         */
        private void preprocessBombs(Grid grid) {
            int rows = grid.getRows();
            int cols = grid.getCols();
            char[][] mat = grid.getMatrix();

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (mat[r][c] == 'B') {
                        for (int i = 0; i < 4; i++) {
                            int nr = r + DX[i];
                            int nc = c + DY[i];
                            if (grid.isValid(nr, nc) && mat[nr][nc] == '.') {
                                mat[nr][nc] = '#';
                            }
                        }
                    }
                }
            }

            // If the exit is a path, treat it as blocked to initiate BFS correctly
            if (mat[rows - 1][cols - 1] == '.') {
                mat[rows - 1][cols - 1] = '#';
            }
        }

        /**
         * Performs BFS starting from the exit (bottom-right corner).
         */
        private void performBFS(Grid grid) {
            int rows = grid.getRows();
            int cols = grid.getCols();
            int startR = rows - 1;
            int startC = cols - 1;

            // If the exit was blocked or is an obstacle, BFS won't traverse
            if (!grid.isValid(startR, startC) || grid.getMatrix()[startR][startC] == '#') {
                // We mark the exit as visited even if it's blocked to satisfy BFS logic
                // if the problem implies the exit itself is where we start.
                // However, based on original logic, we only BFS if it's not '#'.
                // But we must check if the exit is 'G' or 'B' itself.
                // If mat[n-1][m-1] was '.', we turned it to '#'. 
                // Let's follow the original logic: BFS from (n-1, m-1) only if it wasn't '#'.
                // Actually, the original code calls bfs(n-1, m-1) regardless.
            }

            Deque<int[]> queue = new ArrayDeque<>();
            queue.add(new int[]{startR, startC});
            grid.setVisited(startR, startC, true);

            char[][] mat = grid.getMatrix();

            while (!queue.isEmpty()) {
                int[] curr = queue.poll();
                int r = curr[0];
                int c = curr[1];

                for (int i = 0; i < 4; i++) {
                    int nr = r + DX[i];
                    int nc = c + DY[i];

                    if (grid.isValid(nr, nc) && mat[nr][nc] != '#' && !grid.isVisited(nr, nc)) {
                        grid.setVisited(nr, nc, true);
                        queue.add(new int[]{nr, nc});
                    }
                }
            }
        }

        /**
         * Verifies if all 'G' are visited and no 'B' are visited.
         */
        private boolean isSolutionValid(Grid grid) {
            int rows = grid.getRows();
            int cols = grid.getCols();
            char[][] mat = grid.getMatrix();

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (mat[r][c] == 'G' && !grid.isVisited(r, c)) {
                        return false;
                    }
                    if (mat[r][c] == 'B' && grid.isVisited(r, c)) {
                        return false;
                    }
                }
            }
            return true;
        }
    }

    /**
     * Represents the maze grid.
     */
    static class Grid {
        private final int rows;
        private final int cols;
        private final char[][] matrix;
        private final boolean[][] visited;
        private int goldCount = 0;
        private int bombCount = 0;

        public Grid(int rows, int cols, char[][] matrix) {
            this.rows = rows;
            this.cols = cols;
            this.matrix = matrix;
            this.visited = new boolean[rows][cols];
            calculateCounts();
        }

        private void calculateCounts() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (matrix[i][j] == 'G') goldCount++;
                    if (matrix[i][j] == 'B') bombCount++;
                }
            }
        }

        public boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        public int getRows() { return rows; }
        public int getCols() { return cols; }
        public char[][] getMatrix() { return matrix; }
        public boolean isVisited(int r, int c) { return visited[r][c]; }
        public void setVisited(int r, int c, boolean v) { visited[r][c] = v; }
        public int getGoldCount() { return goldCount; }
        public int getBombCount() { return bombCount; }
    }

    /**
     * High-performance Input Reader.
     */
    static class FastReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int curChar;
        private int numChars;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (numChars == -1) throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buffer);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) return -1;
            }
            return buffer[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isWhitespace(c)) c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res = res * 10 + (c - '0');
                c = read();
            } while (!isWhitespace(c));
            return res * sgn;
        }

        public char[][] readGrid(int rows, int cols) {
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = nextChar();
                }
            }
            return grid;
        }

        public char nextChar() {
            int c = read();
            while (isWhitespace(c)) c = read();
            return (char) c;
        }

        private boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }

    /**
     * High-performance Output Writer.
     */
    static class FastWriter {
        private final PrintWriter writer;

        public FastWriter(OutputStream outputStream) {
            this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public void println(Object obj) {
            writer.println(obj);
        }

        public void close() {
            writer.close();
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A program to solve a grid-based maze reachability problem.
 * The goal is to determine if all 'G' (Goal) cells are reachable from 
 * the bottom-right corner, given that 'B' (Bomb) cells turn their 
 * neighbors into '#' (Walls).
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int testCases = reader.nextInt();
            while (testCases-- > 0) {
                MazeSolver solver = new MazeSolver(reader);
                out.println(solver.solve() ? "Yes" : "No");
            }
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    static class MazeSolver {
        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final boolean[][] visited;

        private static final int[][] DIRECTIONS = {
            {1, 0}, {-1, 0}, {0, 1}, {0, -1}
        };

        public MazeSolver(FastReader reader) throws IOException {
            this.rows = reader.nextInt();
            this.cols = reader.nextInt();
            this.grid = new char[rows][cols];
            this.visited = new boolean[rows][cols];

            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }
        }

        /**
         * Executes the core logic: 
         * 1. Process Bomb effects.
         * 2. Perform BFS from the bottom-right corner.
         * 3. Validate if all Goals are visited.
         */
        public boolean solve() {
            if (!applyBombEffects()) {
                return false;
            }

            performBFS(rows - 1, cols - 1);

            return verifyAllGoalsReached();
        }

        /**
         * Processes 'B' cells. If a 'B' is adjacent to a 'G', the path is blocked.
         * Otherwise, neighbors of 'B' are turned into walls ('#').
         * @return false if a 'B' is adjacent to a 'G', true otherwise.
         */
        private boolean applyBombEffects() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == 'B') {
                        for (int[] dir : DIRECTIONS) {
                            int nr = r + dir[0];
                            int nc = c + dir[1];

                            if (isWithinBounds(nr, nc)) {
                                if (grid[nr][nc] == 'G') {
                                    return false;
                                }
                                // Turn neighbor into a wall unless it's already a 'B'
                                if (grid[nr][nc] != 'B') {
                                    grid[nr][nc] = '#';
                                }
                            }
                        }
                    }
                }
            }
            return true;
        }

        /**
         * Iterative BFS to find all reachable cells from the start point.
         */
        private void performBFS(int startR, int startC) {
            // If the starting cell is a wall or a bomb, we cannot move anywhere.
            // Note: According to original logic, 'B' is only traversable if it's the start.
            if (!isTraversable(startR, startC)) {
                // If the starting cell is specifically a 'B', we mark it visited 
                // but the isTraversable check prevents moving to its neighbors.
                if (grid[startR][startC] == 'B') {
                    visited[startR][startC] = true;
                }
                return;
            }

            Queue<int[]> queue = new LinkedList<>();
            queue.add(new int[]{startR, startC});
            visited[startR][startC] = true;

            while (!queue.isEmpty()) {
                int[] current = queue.poll();
                int r = current[0];
                int c = current[1];

                for (int[] dir : DIRECTIONS) {
                    int nr = r + dir[0];
                    int nc = c + dir[1];

                    if (isWithinBounds(nr, nc) && !visited[nr][nc] && isTraversable(nr, nc)) {
                        visited[nr][nc] = true;
                        queue.add(new int[]{nr, nc});
                    }
                }
            }
        }

        private boolean isTraversable(int r, int c) {
            // A cell is traversable if it's not a wall and not a bomb.
            return grid[r][c] != '#' && grid[r][c] != 'B';
        }

        private boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        private boolean verifyAllGoalsReached() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == 'G' && !visited[r][c]) {
                        return false;
                    }
                }
            }
            return true;
        }
    }

    /**
     * Optimized reader for fast input processing.
     */
    static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

