/**
 * Encapsulates the logic for solving the grid-based task.
 */
class GridSolver {
    private static final char BLACK = 'B';
    private static final char GREEN = 'G';
    private static final char WALL = '#';

    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    private int rows;
    private int cols;
    private char[][] grid;
    private boolean[][] visited;
    private boolean[][] memo;

    /**
     * Executes the logic for a single test case.
     */
    public void solve(Scanner in, PrintWriter out) {
        this.rows = in.nextInt();
        this.cols = in.nextInt();
        this.grid = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            grid[i] = in.next().toCharArray();
        }

        // 1. Process all Black components.
        // If a black component is adjacent to a green cell, the configuration is invalid.
        // Otherwise, the black component (and its non-green neighbors) are turned into walls.
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == BLACK) {
                    this.visited = new boolean[rows][cols];
                    if (!clearBlackComponent(i, j)) {
                        out.println("No");
                        return;
                    }
                }
            }
        }

        // 2. Process all Green cells.
        // Every green cell must be able to reach the bottom-right corner (rows-1, cols-1)
        // through cells that are not walls.
        this.memo = new boolean[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == GREEN) {
                    // We reset visited for every green cell to allow independent pathfinding,
                    // but we keep the memoization to optimize repeating paths.
                    this.visited = new boolean[rows][cols];
                    if (!canReachTarget(i, j)) {
                        out.println("No");
                        return;
                    }
                }
            }
        }

        out.println("Yes");
    }

    /**
     * A DFS that clears out black components and their non-green neighbors.
     * Returns false if a green cell is found adjacent to a black component.
     */
    private boolean clearBlackComponent(int r, int c) {
        if (visited[r][c]) {
            return true;
        }
        visited[r][c] = true;

        for (int d = 0; d < 4; d++) {
            int nr = r + DR[d];
            int nc = c + DC[d];

            if (isValid(nr, nc)) {
                if (grid[nr][nc] == GREEN) {
                    return false;
                } else if (grid[nr][nc] == BLACK) {
                    if (!clearBlackComponent(nr, nc)) {
                        return false;
                    }
                }
                // Following the original logic: neighbors of black cells 
                // (that aren't green) are converted to walls.
                grid[nr][nc] = WALL;
            }
        }
        return true;
    }

    /**
     * A DFS with memoization to check if a path exists from (r, c) to the bottom-right corner.
     */
    private boolean canReachTarget(int r, int c) {
        // Target reached
        if (r == rows - 1 && c == cols - 1) {
            return true;
        }

        // Memoization: if we've already proven this cell leads to the target
        if (memo[r][c]) {
            return true;
        }

        // Avoid cycles in the current path
        if (visited[r][c]) {
            return false;
        }

        visited[r][c] = true;

        for (int d = 0; d < 4; d++) {
            int nr = r + DR[d];
            int nc = c + DC[d];

            if (isValid(nr, nc) && grid[nr][nc] != WALL) {
                if (canReachTarget(nr, nc)) {
                    memo[r][c] = true; // Mark as a successful path cell
                    return true;
                }
            }
        }

        return false;
    }

    /**
     * Checks if the given coordinates are within the grid boundaries.
     */
    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

import java.io.BufferedReader;
