/**
 * Represents the grid structure and provides safe access to its elements.
 */
class Maze {
    private static final char WALL = '#';
    private static final char PATH = '.';
    private static final char B_CELL = 'B';
    private static final char GOAL = 'G';

    private final int rows;
    private final int cols;
    private final char[][] grid;

    public Maze(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
    }

    public int getRows() { return rows; }
    public int getCols() { return cols; }
    public char getCell(int r, int c) { return grid[r][c]; }
    public void setCell(int r, int c, char value) { grid[r][c] = value; }

    public boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    public boolean isWall(int r, int c) {
        return grid[r][c] == WALL;
    }

    public boolean isGoal(int r, int c) {
        return grid[r][c] == GOAL;
    }

    public boolean isBCell(int r, int c) {
        return grid[r][c] == B_CELL;
    }

    public boolean isPath(int r, int c) {
        return grid[r][c] == PATH;
    }
}

/**
 * Contains the logic to solve the maze constraints and reachability.
 */
class MazeSolver {
    private static final char WALL = '#';

    /**
     * Executes the core logic: 
     * 1. Applies constraints based on 'B' cells.
     * 2. Checks if all 'G' cells can reach the bottom-right exit.
     */
    public boolean solve(Maze maze) {
        if (!applyBConstraints(maze)) {
            return false;
        }

        return checkGoalReachability(maze);
    }

    /**
     * For every 'B' cell, all adjacent 'G' cells make the configuration impossible.
     * All adjacent '.' cells are converted into walls ('#').
     */
    private boolean applyBConstraints(Maze maze) {
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int r = 0; r < maze.getRows(); r++) {
            for (int c = 0; c < maze.getCols(); c++) {
                if (maze.isBCell(r, c)) {
                    for (int i = 0; i < 4; i++) {
                        int nr = r + dr[i];
                        int nc = c + dc[i];

                        if (maze.isWithinBounds(nr, nc)) {
                            if (maze.isGoal(nr, nc)) {
                                return false; // Adjacent to a goal, impossible
                            }
                            if (maze.isPath(nr, nc)) {
                                maze.setCell(nr, nc, WALL); // Path becomes a wall
                            }
                        }
                    }
                }
            }
        }
        return true;
    }

    /**
     * Uses BFS to determine if all 'G' cells can reach the exit at (rows-1, cols-1).
     */
    private boolean checkGoalReachability(Maze maze) {
        int rows = maze.getRows();
        int cols = maze.getCols();
        boolean[][] reachable = new boolean[rows][cols];
        Queue<int[]> queue = new LinkedList<>();

        int exitR = rows - 1;
        int exitC = cols - 1;

        // The exit cell is always considered reachable (as per original logic)
        reachable[exitR][exitC] = true;

        // If exit is not a wall, start BFS from the exit moving backwards
        if (!maze.isWall(exitR, exitC)) {
            queue.add(new int[]{exitR, exitC});
        }

        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            int r = curr[0];
            int c = curr[1];

            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i];
                int nc = c + dc[i];

                if (maze.isWithinBounds(nr, nc) && !reachable[nr][nc] && !maze.isWall(nr, nc)) {
                    reachable[nr][nc] = true;
                    queue.add(new int[]{nr, nc});
                }
            }
        }

        // Check if any 'G' cell is unreachable
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (maze.isGoal(r, c) && !reachable[r][c]) {
                    return false;
                }
            }
        }

        return true;
    }
}

