import java.util.*;

/**
 * A solver for the Grid Gold Reachability problem.
 * The goal is to determine if all 'Gold' cells can be reached from the exit (bottom-right)
 * after 'Blocker' cells have expanded into adjacent empty spaces.
 */
public class Main {

    private static final char GOLD = 'G';
    private static final char BLOCKER = 'B';
    private static final char EMPTY = '.';
    private static final char WALL = '#';

    private static final int[][] DIRECTIONS = {
        {0, 1}, {0, -1}, {1, 0}, {-1, 0}
    };

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (scanner.hasNextInt()) {
            int testCases = scanner.nextInt();
            while (testCases-- > 0) {
                solve(scanner);
            }
        }
        scanner.close();
    }

    private static void solve(Scanner scanner) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] grid = new char[rows][cols];
        int totalGoldCount = 0;

        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] == GOLD) {
                    totalGoldCount++;
                }
            }
        }

        boolean blockerNearGold = applyBlockerEffects(grid, rows, cols);
        boolean exitIsBlocked = (grid[rows - 1][cols - 1] == WALL);

        // If a blocker touches gold or the exit is walled off, 
        // we only succeed if there was no gold to begin with.
        if (blockerNearGold || exitIsBlocked) {
            System.out.println(totalGoldCount == 0 ? "Yes" : "No");
            return;
        }

        // Perform BFS from the exit to see how many gold cells are reachable
        boolean allGoldFound = isAllGoldReachable(grid, rows, cols, totalGoldCount);
        System.out.println(allGoldFound ? "Yes" : "No");
    }

    /**
     * Expands 'Blocker' cells into adjacent empty '.' cells.
     * If a blocker is adjacent to a 'Gold' cell, the configuration is invalid.
     * 
     * @return true if a blocker is adjacent to gold, false otherwise.
     */
    private static boolean applyBlockerEffects(char[][] grid, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == BLOCKER) {
                    for (int[] dir : DIRECTIONS) {
                        int nr = r + dir[0];
                        int nc = c + dir[1];

                        if (isValid(nr, nc, rows, cols)) {
                            if (grid[nr][nc] == GOLD) {
                                return true; // Blocker touches Gold
                            } else if (grid[nr][nc] == EMPTY) {
                                grid[nr][nc] = WALL; // Blocker expands into empty space
                            }
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Uses BFS to traverse the grid starting from the bottom-right exit.
     * 
     * @return true if the number of reached gold cells equals the total gold cells.
     */
    private static boolean isAllGoldReachable(char[][] grid, int rows, int cols, int totalGold) {
        int reachedGoldCount = 0;
        Queue<Point> queue = new ArrayDeque<>();

        // Start BFS from the exit (bottom-right corner)
        int startR = rows - 1;
        int startC = cols - 1;

        // Check if the starting cell itself is gold
        if (grid[startR][startC] == GOLD) {
            reachedGoldCount++;
        }

        // Mark as visited by turning it into a wall
        grid[startR][startC] = WALL;
        queue.add(new Point(startR, startC));

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            for (int[] dir : DIRECTIONS) {
                int nr = current.r + dir[0];
                int nc = current.c + dir[1];

                if (isValid(nr, nc, rows, cols) && grid[nr][nc] != WALL) {
                    if (grid[nr][nc] == GOLD) {
                        reachedGoldCount++;
                    }
                    grid[nr][nc] = WALL; // Mark visited
                    queue.add(new Point(nr, nc));
                }
            }
        }

        return reachedGoldCount == totalGold;
    }

    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Simple data carrier for coordinates.
     */
    private static class Point {
        final int r;
        final int c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.*;

/**
 * A solver that determines if all 'G' (starting points) in a grid
 * can reach the bottom-right corner without hitting blocked cells.
 */
public class GridPathSolver {

    private static final int[] ROW_DIRECTIONS = {-1, 1, 0, 0};
    private static final int[] COL_DIRECTIONS = {0, 0, -1, 1};

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        try {
            String line = reader.readLine();
            if (line == null) return;

            int testCases = Integer.parseInt(line.trim());
            while (testCases-- > 0) {
                solve(reader);
            }
        } catch (IOException | NumberFormatException e) {
            System.err.println("Error processing input: " + e.getMessage());
        }
    }

    private static void solve(FastReader reader) throws IOException {
        String dimensionsLine = reader.readLine();
        if (dimensionsLine == null) return;

        StringTokenizer st = new StringTokenizer(dimensionsLine);
        int rows = Integer.parseInt(st.nextToken());
        int cols = Integer.parseInt(st.nextToken());

        char[][] grid = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            grid[r] = reader.readLine().toCharArray();
        }

        boolean[][] blocked = computeBlockedCells(grid, rows, cols);
        boolean[][] reachableFromExit = computeReachableFromExit(blocked, rows, cols);

        boolean allGCanReachExit = checkAllGReachExit(grid, reachableFromExit, rows, cols);
        System.out.println(allGCanReachExit ? "Yes" : "No");
    }

    /**
     * Identifies which cells are blocked by '#' or 'B' (and 'B's neighbors).
     */
    private static boolean[][] computeBlockedCells(char[][] grid, int rows, int cols) {
        boolean[][] blocked = new boolean[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '#') {
                    blocked[r][c] = true;
                } else if (grid[r][c] == 'B') {
                    blocked[r][c] = true;
                    // Mark neighbors of bomb as blocked
                    for (int i = 0; i < 4; i++) {
                        int nr = r + ROW_DIRECTIONS[i];
                        int nc = c + COL_DIRECTIONS[i];
                        if (isValid(nr, nc, rows, cols)) {
                            blocked[nr][nc] = true;
                        }
                    }
                }
            }
        }
        return blocked;
    }

    /**
     * Performs a BFS starting from the exit (bottom-right) to find all reachable cells.
     * This is the reverse of finding a path from 'G' to the exit.
     */
    private static boolean[][] computeReachableFromExit(boolean[][] blocked, int rows, int cols) {
        boolean[][] reachable = new boolean[rows][cols];
        Queue<int[]> queue = new LinkedList<>();

        int targetR = rows - 1;
        int targetC = cols - 1;

        // If the exit itself is blocked, nothing can reach it
        if (!blocked[targetR][targetC]) {
            reachable[targetR][targetC] = true;
            queue.add(new int[]{targetR, targetC});
        }

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int r = current[0];
            int c = current[1];

            for (int i = 0; i < 4; i++) {
                int nr = r + ROW_DIRECTIONS[i];
                int nc = c + COL_DIRECTIONS[i];

                if (isValid(nr, nc, rows, cols) && !blocked[nr][nc] && !reachable[nr][nc]) {
                    reachable[nr][nc] = true;
                    queue.add(new int[]{nr, nc});
                }
            }
        }
        return reachable;
    }

    /**
     * Validates if every 'G' cell in the grid is marked as reachable.
     */
    private static boolean checkAllGReachExit(char[][] grid, boolean[][] reachable, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 'G') {
                    if (!reachable[r][c]) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private final BufferedReader reader;

        public FastReader() {
            reader = new BufferedReader(new InputStreamReader(System.in));
        }

        public String readLine() throws IOException {
            return reader.readLine();
        }
    }
}

