/**
 * Refactored solution for the grid reachability problem.
 * The goal is to determine if all 'G' (Good) cells are reachable from the 
 * bottom-right corner without passing through '#' (Obstacles) or 'X' (Special) cells.
 */
public class D1365 {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int testCases = scanner.nextInt();
        while (testCases-- > 0) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            String[] gridData = new String[rows];

            for (int i = 0; i < rows; i++) {
                gridData[i] = scanner.next();
            }

            MazeSolver solver = new MazeSolver(rows, cols, gridData);
            System.out.println(solver.isPathValid() ? "Yes" : "No");
        }
        scanner.close();
    }

    /**
     * Represents the different types of cells in the grid.
     */
    enum CellType {
        EMPTY,      // '.'
        OBSTACLE,   // '#'
        GOOD,       // 'G'
        SPECIAL     // 'X'
    }

    /**
     * A simple data carrier for coordinate points.
     */
    record Point(int r, int c) {}

    /**
     * Logic handler for the Maze problem.
     */
    static class MazeSolver {
        private static final int[][] DIRECTIONS = {
            {1, 0}, {-1, 0}, {0, 1}, {0, -1}
        };

        private final int rows;
        private final int cols;
        private final CellType[][] grid;
        private int totalGoodCells = 0;

        public MazeSolver(int rows, int cols, String[] inputRows) {
            this.rows = rows;
            this.cols = cols;
            this.grid = new CellType[rows][cols];
            initializeGrid(inputRows);
            applySpecialCellRules();
        }

        /**
         * Parses the input strings into a structured grid of CellTypes.
         */
        private void initializeGrid(String[] inputRows) {
            for (int i = 0; i < rows; i++) {
                String rowStr = inputRows[i];
                for (int j = 0; j < cols; j++) {
                    char ch = rowStr.charAt(j);
                    grid[i][j] = mapCharToCellType(ch);
                    if (grid[i][j] == CellType.GOOD) {
                        totalGoodCells++;
                    }
                }
            }
        }

        private CellType mapCharToCellType(char ch) {
            return switch (ch) {
                case '.' -> CellType.EMPTY;
                case '#' -> CellType.OBSTACLE;
                case 'G' -> CellType.GOOD;
                default  -> CellType.SPECIAL; // Handles 'X'
            };
        }

        /**
         * Applies the rule: If a cell is 'SPECIAL', all adjacent 'EMPTY' cells 
         * become 'OBSTACLE'.
         */
        private void applySpecialCellRules() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == CellType.SPECIAL) {
                        for (int[] dir : DIRECTIONS) {
                            int nr = i + dir[0];
                            int nc = j + dir[1];
                            if (isWithinBounds(nr, nc) && grid[nr][nc] == CellType.EMPTY) {
                                grid[nr][nc] = CellType.OBSTACLE;
                            }
                        }
                    }
                }
            }
        }

        private boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        /**
         * Determines if the path requirement is met.
         * 
         * @return true if all Good cells are reachable from the bottom-right corner
         *         without hitting an Obstacle or a Special cell.
         */
        public boolean isPathValid() {
            int startR = rows - 1;
            int startC = cols - 1;

            // If the starting cell itself is an obstacle, we can only succeed if there were no Good cells to find.
            if (grid[startR][startC] == CellType.OBSTACLE) {
                return totalGoodCells == 0;
            }

            // If the starting cell is a Special cell, the path is immediately invalid.
            if (grid[startR][startC] == CellType.SPECIAL) {
                return false;
            }

            return performBreadthFirstSearch(startR, startC);
        }

        private boolean performBreadthFirstSearch(int startR, int startC) {
            Queue<Point> queue = new LinkedList<>();
            boolean[][] visited = new boolean[rows][cols];
            int reachableGoodCount = 0;

            queue.add(new Point(startR, startC));
            visited[startR][startC] = true;

            if (grid[startR][startC] == CellType.GOOD) {
                reachableGoodCount++;
            }

            while (!queue.isEmpty()) {
                Point current = queue.poll();

                for (int[] dir : DIRECTIONS) {
                    int nr = current.r() + dir[0];
                    int nc = current.c() + dir[1];

                    if (isWithinBounds(nr, nc) && !visited[nr][nc]) {
                        CellType neighborType = grid[nr][nc];

                        // If we encounter a special cell, the path is considered "bad" per problem rules.
                        if (neighborType == CellType.SPECIAL) {
                            return false;
                        }

                        if (neighborType == CellType.OBSTACLE) {
                            continue;
                        }

                        // Valid path to Empty or Good cell
                        visited[nr][nc] = true;
                        if (neighborType == CellType.GOOD) {
                            reachableGoodCount++;
                        }
                        queue.add(new Point(nr, nc));
                    }
                }
            }

            return reachableGoodCount == totalGoodCells;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Main entry point for the grid traversal program.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int testCases = reader.nextInt();
            while (testCases-- > 0) {
                int rows = reader.nextInt();
                int cols = reader.nextInt();
                char[][] grid = new char[rows][cols];

                for (int i = 0; i < rows; i++) {
                    grid[i] = reader.next().toCharArray();
                }

                GridSolver solver = new GridSolver(rows, cols, grid);
                if (solver.canReachAllGoals()) {
                    out.println("Yes");
                } else {
                    out.println("No");
                }
            }
        } catch (Exception e) {
            // In competitive programming, we often swallow or print errors
            // depending on the environment requirements.
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Encapsulates the logic for traversing the grid and counting reachable goal cells.
     */
    static class GridSolver {
        private final int rows;
        private final int cols;
        private final char[][] grid;
        private int reachableGoalCount = 0;

        public GridSolver(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
        }

        /**
         * Determines if all 'G' cells in the grid are reachable from the bottom-right corner.
         * 
         * @return true if all goal cells are reachable, false otherwise.
         */
        public boolean canReachAllGoals() {
            int totalGoals = countTotalGoals();

            // If there are no goals, technically all goals (zero) are reached.
            if (totalGoals == 0) {
                return true;
            }

            boolean[][] visited = new boolean[rows][cols];
            // Start traversal from the bottom-right corner (n-1, m-1)
            performDfs(rows - 1, cols - 1, visited);

            return reachableGoalCount == totalGoals;
        }

        private int countTotalGoals() {
            int count = 0;
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == 'G') {
                        count++;
                    }
                }
            }
            return count;
        }

        private void performDfs(int r, int c, boolean[][] visited) {
            // 1. Basic boundary and validity checks
            if (!isInBounds(r, c) || grid[r][c] == '#' || visited[r][c]) {
                return;
            }

            // 2. The original logic specifies: if a neighbor is a barrier 'B', 
            // the current path is blocked/invalid for this cell.
            if (hasBarrierNeighbor(r, c)) {
                return;
            }

            // 3. If the cell is a goal, increment the reachable count
            if (grid[r][c] == 'G') {
                reachableGoalCount++;
            }

            // 4. Mark current cell as visited
            visited[r][c] = true;

            // 5. Recursively visit neighbors
            performDfs(r + 1, c, visited);
            performDfs(r - 1, c, visited);
            performDfs(r, c + 1, visited);
            performDfs(r, c - 1, visited);
        }

        private boolean isInBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        private boolean hasBarrierNeighbor(int r, int c) {
            int[] dr = {1, -1, 0, 0};
            int[] dc = {0, 0, 1, -1};

            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i];
                int nc = c + dc[i];
                if (isInBounds(nr, nc) && grid[nr][nc] == 'B') {
                    return true;
                }
            }
            return false;
        }
    }

    /**
     * High-performance input reader for large datasets.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * A refactored solution for the Maze problem.
 * The goal is to determine if a path exists from the bottom-right corner 
 * to cover all goals 'G' without hitting blocks 'B' or their adjacent areas.
 */
public class CF1365D {

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        int testCases = reader.nextInt();

        for (int t = 0; t < testCases; t++) {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] grid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            MazeSolver solver = new MazeSolver(grid, rows, cols);
            boolean isPossible = solver.solve();

            System.out.println(isPossible ? "yes" : "No");
        }
    }

    /**
     * Handles the core logic of the maze traversal.
     */
    static class MazeSolver {
        private static final char EMPTY = '.';
        private static final char BLOCK = 'B';
        private static final char OBSTACLE = '#';
        private static final char GOAL = 'G';
        private static final char VISITED = '$';

        private static final int[] ROW_DIRECTIONS = {-1, 1, 0, 0};
        private static final int[] COL_DIRECTIONS = {0, 0, -1, 1};

        private final char[][] maze;
        private final int rows;
        private final int cols;
        private boolean possible = true;

        public MazeSolver(char[][] maze, int rows, int cols) {
            this.maze = maze;
            this.rows = rows;
            this.cols = cols;
        }

        /**
         * Executes the solving algorithm.
         * @return true if the path is valid and meets requirements, false otherwise.
         */
        public boolean solve() {
            expandBlockers();
            startTraversal();
            verifyGoals();
            return possible;
        }

        /**
         * Marks cells adjacent to 'B' as obstacles '#'.
         */
        private void expandBlockers() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (maze[r][c] == BLOCK) {
                        for (int i = 0; i < 4; i++) {
                            int nr = r + ROW_DIRECTIONS[i];
                            int nc = c + COL_DIRECTIONS[i];
                            if (isValid(nr, nc) && maze[nr][nc] == EMPTY) {
                                maze[nr][nc] = OBSTACLE;
                            }
                        }
                    }
                }
            }
        }

        /**
         * Initiates DFS from the bottom-right corner.
         */
        private void startTraversal() {
            int startR = rows - 1;
            int startC = cols - 1;

            if (maze[startR][startC] == EMPTY || maze[startR][startC] == GOAL) {
                performDFS(startR, startC);
            }
        }

        /**
         * Recursive DFS to traverse the maze and mark visited cells.
         */
        private void performDFS(int r, int c) {
            if (!isValid(r, c)) {
                return;
            }

            char currentCell = maze[r][c];

            // If we hit a block, the path is invalid
            if (currentCell == BLOCK) {
                possible = false;
                return;
            }

            // If it's an obstacle or already visited, stop this branch
            if (currentCell == OBSTACLE || currentCell == VISITED) {
                return;
            }

            // Mark current cell as visited
            maze[r][c] = VISITED;

            // Explore neighbors
            for (int i = 0; i < 4; i++) {
                performDFS(r + ROW_DIRECTIONS[i], c + COL_DIRECTIONS[i]);
            }
        }

        /**
         * Checks if any 'G' (Goal) cells remain unvisited.
         */
        private void verifyGoals() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (maze[r][c] == GOAL) {
                        possible = false;
                        return;
                    }
                }
            }
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * Fast I/O utility for efficient reading of large inputs.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader() {
            reader = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * GridPathfinder solves a grid-based reachability problem.
 * 
 * Constraints:
 * 1. Black cells ('B') cannot be adjacent to Green cells ('G').
 * 2. Any cell adjacent to a Black cell that isn't Black itself becomes an obstacle ('#').
 * 3. Every Green cell ('G') must be able to reach the bottom-right corner of the grid.
 */
public class GridPathfinder {

    private static final char BLACK = 'B';
    private static final char GREEN = 'G';
    private static final char OBSTACLE = '#';

    // Direction vectors for 4-way connectivity (Up, Down, Left, Right)
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int testCases = sc.nextInt();
        while (testCases-- > 0) {
            out.println(solve(sc));
        }

        out.flush();
        out.close();
    }

    /**
     * Orchestrates the solving process for a single test case.
     */
    private static String solve(FastScanner sc) {
        int rows = sc.nextInt();
        int cols = sc.nextInt();
        char[][] grid = new char[rows][cols];

        for (int r = 0; r < rows; r++) {
            grid[r] = sc.next().toCharArray();
        }

        // Step 1: Apply Black cell constraints and check for immediate conflicts
        if (hasBlackCellConflict(grid, rows, cols)) {
            return "No";
        }

        // Step 2: Check if all Green cells can reach the target (bottom-right)
        if (hasGreenCellIsolation(grid, rows, cols)) {
            return "No";
        }

        return "Yes";
    }

    /**
     * Scans the grid for Black cells. 
     * If a Black cell is next to a Green cell, returns true (invalid).
     * Otherwise, converts non-Black neighbors of Black cells into obstacles.
     */
    private static boolean hasBlackCellConflict(char[][] grid, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == BLACK) {
                    for (int i = 0; i < 4; i++) {
                        int nr = r + DR[i];
                        int nc = c + DC[i];

                        if (isInBounds(nr, nc, rows, cols)) {
                            if (grid[nr][nc] == GREEN) {
                                return true;
                            } else if (grid[nr][nc] != BLACK) {
                                grid[nr][nc] = OBSTACLE;
                            }
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Iterates through all Green cells to ensure reachability to the bottom-right.
     * Uses 'outvisited' to optimize: if a Green cell is part of a successful 
     * path to the target, it is marked so we don't re-run BFS from it.
     */
    private static boolean hasGreenCellIsolation(char[][] grid, int rows, int cols) {
        boolean[][] outvisited = new boolean[rows][cols];
        int targetR = rows - 1;
        int targetC = cols - 1;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == GREEN && !outvisited[r][c]) {
                    if (!canReachTarget(grid, rows, cols, r, c, targetR, targetC, outvisited)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Performs BFS to find if a path exists from (startR, startC) to (targetR, targetC).
     */
    private static boolean canReachTarget(char[][] grid, int rows, int cols, 
                                          int startR, int startC, 
                                          int targetR, int targetC, 
                                          boolean[][] outvisited) {
        Queue<Point> queue = new ArrayDeque<>();
        boolean[][] visited = new boolean[rows][cols];

        queue.add(new Point(startR, startC));
        visited[startR][startC] = true;

        // If the starting cell is Green, mark it as 'outvisited' in case this BFS succeeds
        if (grid[startR][startC] == GREEN) {
            outvisited[startR][startC] = true;
        }

        while (!queue.isEmpty()) {
            Point curr = queue.poll();

            if (curr.r == targetR && curr.c == targetC) {
                return true;
            }

            for (int i = 0; i < 4; i++) {
                int nr = curr.r + DR[i];
                int nc = curr.c + DC[i];

                if (isInBounds(nr, nc, rows, cols) && !visited[nr][nc] && grid[nr][nc] != OBSTACLE) {
                    visited[nr][nc] = true;

                    // Optimization: If this Green cell is reachable, it's part of a valid path
                    if (grid[nr][nc] == GREEN) {
                        outvisited[nr][nc] = true;
                    }

                    queue.add(new Point(nr, nc));
                }
            }
        }
        return false;
    }

    private static boolean isInBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Simple immutable Point class for grid coordinates.
     */
    private static class Point {
        final int r, c;
        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Fast I/O utility.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A refactored solution for solving a maze problem.
 * The goal is to determine if all 'G' (Goal) cells are reachable 
 * from the exit (bottom-right corner) after 'B' (Bomb) cells 
 * have modified adjacent '.' (Path) cells to '#' (Wall) cells.
 */
public class SolveTheMaze {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int numTestCases = reader.nextInt();
        for (int i = 0; i < numTestCases; i++) {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] grid = reader.readGrid(rows, cols);

            MazeSolver solver = new MazeSolver(rows, cols, grid);
            out.println(solver.solve() ? "Yes" : "No");
        }
        out.flush();
        out.close();
    }

    /**
     * Represents the logic for solving a single maze instance.
     */
    static class MazeSolver {
        private static final int[][] DIRECTIONS = {
            {0, 1}, {1, 0}, {0, -1}, {-1, 0}
        };

        private final int rows;
        private final int cols;
        private final char[][] grid;

        public MazeSolver(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
        }

        /**
         * Orchestrates the maze solving process.
         * @return true if all goals are reachable, false otherwise.
         */
        public boolean solve() {
            if (!processBombs()) {
                return false;
            }

            boolean[][] visited = performFloodFillFromExit();
            return areAllGoalsReached(visited);
        }

        /**
         * Processes bombs. A bomb 'B' turns adjacent '.' into '#'.
         * If a bomb is adjacent to a 'G', the maze is immediately invalid.
         */
        private boolean processBombs() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == 'B') {
                        for (int[] dir : DIRECTIONS) {
                            int nr = r + dir[0];
                            int nc = c + dir[1];

                            if (isWithinBounds(nr, nc)) {
                                if (grid[nr][nc] == 'G') {
                                    return false;
                                } else if (grid[nr][nc] == '.') {
                                    grid[nr][nc] = '#';
                                }
                            }
                        }
                    }
                }
            }
            return true;
        }

        /**
         * Performs an iterative BFS starting from the bottom-right corner.
         * @return A 2D boolean array indicating visited cells.
         */
        private boolean[][] performFloodFillFromExit() {
            boolean[][] visited = new boolean[rows][cols];
            int exitR = rows - 1;
            int exitC = cols - 1;

            // If the exit is blocked, no flood fill is possible.
            if (grid[exitR][exitC] == '#') {
                return visited;
            }

            Queue<Point> queue = new LinkedList<>();
            visited[exitR][exitC] = true;
            queue.add(new Point(exitR, exitC));

            while (!queue.isEmpty()) {
                Point current = queue.poll();

                for (int[] dir : DIRECTIONS) {
                    int nr = current.row + dir[0];
                    int nc = current.col + dir[1];

                    if (isWithinBounds(nr, nc) && !visited[nr][nc] && grid[nr][nc] != '#') {
                        visited[nr][nc] = true;
                        queue.add(new Point(nr, nc));
                    }
                }
            }
            return visited;
        }

        /**
         * Checks if all 'G' cells in the grid were marked as visited.
         */
        private boolean areAllGoalsReached(boolean[][] visited) {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == 'G' && !visited[r][c]) {
                        return false;
                    }
                }
            }
            return true;
        }

        private boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * Data structure to hold coordinate information.
     */
    static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Efficient reader for handling large inputs.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public char[][] readGrid(int rows, int cols) {
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }
            return grid;
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * Solve class handles the orchestration of the maze problem.
 * It parses input, invokes the solver, and prints the results.
 */
public class Solve {

    private static final char CELL_EMPTY = '.';
    private static final char CELL_BAD = 'B';
    private static final char CELL_GOOD = 'G';
    private static final char CELL_WALL = '#';

    private static final int[] ROW_OFFSETS = {0, 0, -1, 1};
    private static final int[] COL_OFFSETS = {1, -1, 0, 0};

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        int testCaseCount = reader.nextInt();
        while (testCaseCount-- > 0) {
            MazeSolver solver = new MazeSolver(reader);
            writer.println(solver.solve() ? "Yes" : "No");
        }

        writer.flush();
        writer.close();
    }

    /**
     * Represents a coordinate in the 2D grid.
     */
    private record Point(int row, int col) {}

    /**
     * MazeSolver encapsulates the logic for a single test case.
     */
    private static class MazeSolver {
        private final FastReader reader;

        public MazeSolver(FastReader reader) {
            this.reader = reader;
        }

        public boolean solve() {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] maze = new char[rows][cols];

            for (int r = 0; r < rows; r++) {
                maze[r] = reader.next().toCharArray();
            }

            int totalGoodCells = 0;
            // Step 1: Pre-process the maze (Bad cells turn adjacent empty cells into walls)
            // and count the total number of 'Good' cells.
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (maze[r][c] == CELL_BAD) {
                        applyBadCellEffect(maze, r, c, rows, cols);
                    } else if (maze[r][c] == CELL_GOOD) {
                        totalGoodCells++;
                    }
                }
            }

            // Step 2: Perform BFS from the exit (bottom-right corner)
            return runBfs(maze, rows, cols, totalGoodCells);
        }

        /**
         * Transforms adjacent empty cells to walls if they are near a 'Bad' cell.
         */
        private void applyBadCellEffect(char[][] maze, int r, int c, int rows, int cols) {
            for (int i = 0; i < 4; i++) {
                int nr = r + ROW_OFFSETS[i];
                int nc = c + COL_OFFSETS[i];
                if (isWithinBounds(nr, nc, rows, cols) && maze[nr][nc] == CELL_EMPTY) {
                    maze[nr][nc] = CELL_WALL;
                }
            }
        }

        /**
         * Executes BFS to find all reachable Good and Bad cells.
         */
        private boolean runBfs(char[][] maze, int rows, int cols, int expectedGood) {
            int foundGood = 0;
            int foundBad = 0;

            // The original logic specifically starts BFS only if the exit is a path ('.').
            // If the exit is not '.', the BFS queue remains empty.
            if (maze[rows - 1][cols - 1] == CELL_EMPTY) {
                Deque<Point> queue = new ArrayDeque<>();
                boolean[][] visited = new boolean[rows][cols];

                queue.add(new Point(rows - 1, cols - 1));
                visited[rows - 1][cols - 1] = true;

                while (!queue.isEmpty()) {
                    Point current = queue.poll();
                    char cellValue = maze[current.row][current.col];

                    if (cellValue == CELL_GOOD) {
                        foundGood++;
                    } else if (cellValue == CELL_BAD) {
                        foundBad++;
                    }

                    for (int i = 0; i < 4; i++) {
                        int nr = current.row + ROW_OFFSETS[i];
                        int nc = current.col + COL_OFFSETS[i];

                        if (isWithinBounds(nr, nc, rows, cols) 
                                && !visited[nr][nc] 
                                && maze[nr][nc] != CELL_WALL) {

                            visited[nr][nc] = true;
                            queue.add(new Point(nr, nc));
                        }
                    }
                }
            }

            // The requirement is to reach all good cells and zero bad cells.
            return foundGood == expectedGood && foundBad == 0;
        }

        private boolean isWithinBounds(int r, int c, int rows, int cols) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * Optimized reader for faster input parsing.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            this.reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * Represents a coordinate point in the grid.
 */
record Point(int row, int col) {}

/**
 * Represents the grid and its associated rules.
 */
class Grid {
    private final int rows;
    private final int cols;
    private final char[][] cells;
    private final List<Point> goalPoints;

    public Grid(int rows, int cols, char[][] inputCells) {
        this.rows = rows;
        this.cols = cols;
        this.cells = inputCells;
        this.goalPoints = new ArrayList<>();
        identifyGoals();
    }

    private void identifyGoals() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (cells[r][c] == 'G') {
                    goalPoints.add(new Point(r, c));
                }
            }
        }
    }

    public int getRows() { return rows; }
    public int getCols() { return cols; }
    public char getCell(int r, int c) { return cells[r][c]; }
    public void setCell(int r, int c, char val) { cells[r][c] = val; }
    public List<Point> getGoalPoints() { return goalPoints; }

    public boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

/**
 * Handles the logic for determining if goals are reachable.
 */
class PathfindingSolver {
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public String solve(Grid grid) {
        if (!applyBlockerRules(grid)) {
            return "No";
        }

        return canReachAllGoals(grid) ? "Yes" : "No";
    }

    /**
     * Processes 'B' (Blocker) cells. 
     * If a 'B' is adjacent to a 'G', it's impossible (No).
     * If a 'B' is adjacent to a '.', it turns that '.' into a wall '#'.
     */
    private boolean applyBlockerRules(Grid grid) {
        for (int r = 0; r < grid.getRows(); r++) {
            for (int c = 0; c < grid.getCols(); c++) {
                if (grid.getCell(r, c) == 'B') {
                    for (int i = 0; i < 4; i++) {
                        int nr = r + DR[i];
                        int nc = c + DC[i];

                        if (grid.isWithinBounds(nr, nc)) {
                            char neighbor = grid.getCell(nr, nc);
                            if (neighbor == 'G') {
                                return false; // Goal is immediately blocked/invalid
                            } else if (neighbor == '.') {
                                grid.setCell(nr, nc, '#');
                            }
                        }
                    }
                }
            }
        }
        return true;
    }

    /**
     * Performs BFS starting from the bottom-right corner to see if all 'G' cells are reachable.
     */
    private boolean canReachAllGoals(Grid grid) {
        int lastR = grid.getRows() - 1;
        int lastC = grid.getCols() - 1;

        // If the exit/start point is a wall
        if (grid.getCell(lastR, lastC) == '#') {
            return grid.getGoalPoints().isEmpty();
        }

        Deque<Point> queue = new ArrayDeque<>();
        boolean[][] visited = new boolean[grid.getRows()][grid.getCols()];

        Point start = new Point(lastR, lastC);
        queue.add(start);
        visited[lastR][lastC] = true;

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            for (int i = 0; i < 4; i++) {
                int nr = current.row() + DR[i];
                int nc = current.col() + DC[i];

                if (grid.isWithinBounds(nr, nc) && !visited[nr][nc] && grid.getCell(nr, nc) != '#') {
                    visited[nr][nc] = true;
                    queue.add(new Point(nr, nc));
                }
            }
        }

        // Check if all goal points were visited
        for (Point goal : grid.getGoalPoints()) {
            if (!visited[goal.row()][goal.col()]) {
                return false;
            }
        }

        return true;
    }
}

public class Main {
    public static void main(String[] args) {
        try (Scanner sc = new Scanner(new BufferedReader(new InputStreamReader(System.in)))) {
            if (!sc.hasNextInt()) return;

            int testCases = sc.nextInt();
            PathfindingSolver solver = new PathfindingSolver();

            for (int t = 0; t < testCases; t++) {
                int rows = sc.nextInt();
                int cols = sc.nextInt();
                char[][] map = new char[rows][cols];

                for (int i = 0; i < rows; i++) {
                    map[i] = sc.next().toCharArray();
                }

                Grid grid = new Grid(rows, cols, map);
                System.out.println(solver.solve(grid));
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver for the Maze Challenge problem.
 * The problem involves two stages: 
 * 1. A flood spreading from block cells ('B') that turns empty cells ('.') into walls ('#').
 * 2. A player attempting to reach all goal cells ('G') from a starting position without hitting blocks.
 */
public class MazeChallenge {

    private static final char EMPTY_CELL = '.';
    private static final char WALL = '#';
    private static final char GOAL = 'G';
    private static final char BLOCK = 'B';

    private static final int[] DIRECTION_X = {1, -1, 0, 0};
    private static final int[] DIRECTION_Y = {0, 0, 1, -1};

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int testCases = reader.nextInt();
        while (testCases-- > 0) {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] grid = reader.readMaze(rows, cols);

            MazeSolver solver = new MazeSolver(rows, cols, grid);
            out.println(solver.solve() ? "Yes" : "No");
        }
        out.flush();
        out.close();
    }

    /**
     * Encapsulates the logic for a single maze test case.
     */
    static class MazeSolver {
        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final boolean[][] visited;

        public MazeSolver(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            // Padding included in grid from FastReader (N+2 x M+2)
            this.visited = new boolean[rows + 2][cols + 2];
        }

        public boolean solve() {
            // Step 1: Spread the flood from all block cells.
            // This might turn some empty cells into walls.
            if (!applyFlood()) {
                return false;
            }

            // Step 2: Check if the player can reach all goals from the bottom-right corner.
            // The player must avoid block cells.
            return verifyPlayerReachability(rows, cols);
        }

        /**
         * Simulates the flood spreading from 'B' cells.
         * Floods turn '.' into '#' and fail if they hit a 'G'.
         */
        private boolean applyFlood() {
            Queue<Point> queue = new LinkedList<>();

            // Find all unvisited blocks to start the flood
            for (int r = 1; r <= rows; r++) {
                for (int c = 1; c <= cols; c++) {
                    if (grid[r][c] == BLOCK && !visited[r][c]) {
                        if (!floodFrom(new Point(r, c), queue)) {
                            return false;
                        }
                    }
                }
            }
            return true;
        }

        private boolean floodFrom(Point start, Queue<Point> queue) {
            visited[start.x][start.y] = true;
            queue.offer(start);

            while (!queue.isEmpty()) {
                Point current = queue.poll();

                for (int i = 0; i < 4; i++) {
                    int nextR = current.x + DIRECTION_X[i];
                    int nextC = current.y + DIRECTION_Y[i];

                    if (visited[nextR][nextC]) {
                        continue;
                    }

                    switch (grid[nextR][nextC]) {
                        case EMPTY_CELL:
                            grid[nextR][nextC] = WALL;
                            // We don't mark visited here because the original logic 
                            // relies on the cell turning into a '#' to stop traversal.
                            break;
                        case WALL:
                            break;
                        case GOAL:
                            return false; // Flood hit a goal
                        case BLOCK:
                            visited[nextR][nextC] = true;
                            queue.offer(new Point(nextR, nextC));
                            break;
                    }
                }
            }
            return true;
        }

        /**
         * Checks if a player starting at the designated point can visit all 'G' cells
         * without stepping on a 'B' cell.
         */
        private boolean verifyPlayerReachability(int startR, int startC) {
            // Reset visited for the second BFS pass
            for (int i = 0; i <= rows + 1; i++) {
                Arrays.fill(visited[i], false);
            }

            Point startPoint = new Point(startR, startC);

            // If the starting point was turned into a wall by the flood
            if (grid[startR][startC] == WALL) {
                return areAllGoalsVisited();
            }

            Queue<Point> queue = new LinkedList<>();
            visited[startR][startC] = true;
            queue.offer(startPoint);

            while (!queue.isEmpty()) {
                Point current = queue.poll();

                for (int i = 0; i < 4; i++) {
                    int nextR = current.x + DIRECTION_X[i];
                    int nextC = current.y + DIRECTION_Y[i];

                    if (visited[nextR][nextC]) {
                        continue;
                    }

                    char cell = grid[nextR][nextC];
                    if (cell == BLOCK) {
                        return false; // Player hit a block
                    } else if (cell == EMPTY_CELL || cell == GOAL) {
                        visited[nextR][nextC] = true;
                        queue.offer(new Point(nextR, nextC));
                    }
                }
            }

            return areAllGoalsVisited();
        }

        private boolean areAllGoalsVisited() {
            for (int r = 1; r <= rows; r++) {
                for (int c = 1; c <= cols; c++) {
                    if (grid[r][c] == GOAL && !visited[r][c]) {
                        return false;
                    }
                }
            }
            return true;
        }
    }

    static class Point {
        final int x, y;
        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    /**
     * Efficient input reader for large datasets.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = nextLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public String nextLine() {
            try {
                return reader.readLine();
            } catch (IOException e) {
                return null;
            }
        }

        /**
         * Reads the maze and applies padding to handle boundary checks gracefully.
         */
        public char[][] readMaze(int rows, int cols) {
            char[][] grid = new char[rows + 2][cols + 2];
            // Fill border with walls
            for (int i = 0; i < rows + 2; i++) {
                Arrays.fill(grid[i], WALL);
            }

            for (int i = 1; i <= rows; i++) {
                String line = nextLine();
                for (int j = 1; j <= cols; j++) {
                    grid[i][j] = line.charAt(j - 1);
                }
            }
            return grid;
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A solver for grid-based reachability problems.
 * The goal is to determine if all Goal cells (G) are reachable from the bottom-right corner
 * and no Special cells (other characters) are reachable.
 */
public class GridProblemSolver {

    private static final int EMPTY_CELL = 0;
    private static final int WALL_CELL = 1;
    private static final int GOAL_CELL = 100;
    private static final int SPECIAL_CELL = -1;

    private static final int[][] DIRECTIONS = {
            {0, 1}, {0, -1}, {1, 0}, {-1, 0}
    };

    private int rows;
    private int cols;
    private int[][] grid;
    private boolean[][] visited;

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        int testCases = reader.nextInt();
        while (testCases-- > 0) {
            GridProblemSolver solver = new GridProblemSolver();
            solver.solve(reader, writer);
        }
        writer.flush();
        writer.close();
    }

    public void solve(FastReader reader, PrintWriter writer) {
        this.rows = reader.nextInt();
        this.cols = reader.nextInt();

        // Use padding (size + 2) to avoid boundary checks during DFS
        initializeGrid();
        parseGrid(reader);
        applyBlockingRules();
        runDfs();

        if (validateSolution()) {
            writer.println("Yes");
        } else {
            writer.println("No");
        }
    }

    private void initializeGrid() {
        grid = new int[rows + 2][cols + 2];
        visited = new boolean[rows + 2][cols + 2];
        for (int i = 0; i < rows + 2; i++) {
            Arrays.fill(grid[i], WALL_CELL);
        }
    }

    private void parseGrid(FastReader reader) {
        for (int i = 1; i <= rows; i++) {
            String rowString = reader.next();
            for (int j = 1; j <= cols; j++) {
                char c = rowString.charAt(j - 1);
                if (c == '.') {
                    grid[i][j] = EMPTY_CELL;
                } else if (c == '#') {
                    grid[i][j] = WALL_CELL;
                } else if (c == 'G') {
                    grid[i][j] = GOAL_CELL;
                } else {
                    grid[i][j] = SPECIAL_CELL;
                }
            }
        }
    }

    /**
     * If a cell is SPECIAL, its neighbors (that are not SPECIAL or GOAL) 
     * become WALLS.
     */
    private void applyBlockingRules() {
        for (int i = 1; i <= rows; i++) {
            for (int j = 1; j <= cols; j++) {
                if (grid[i][j] == SPECIAL_CELL) {
                    blockNeighbors(i, j);
                }
            }
        }
    }

    private void blockNeighbors(int r, int c) {
        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            if (grid[nr][nc] != SPECIAL_CELL && grid[nr][nc] != GOAL_CELL) {
                grid[nr][nc] = WALL_CELL;
            }
        }
    }

    private void runDfs() {
        // Start DFS from the bottom-right corner if it's not a wall
        if (grid[rows][cols] != WALL_CELL) {
            dfs(rows, cols);
        }
    }

    private void dfs(int r, int c) {
        visited[r][c] = true;
        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            if (isValidTraversal(nr, nc)) {
                dfs(nr, nc);
            }
        }
    }

    private boolean isValidTraversal(int r, int c) {
        return grid[r][c] != WALL_CELL && !visited[r][c];
    }

    private boolean validateSolution() {
        for (int i = 1; i <= rows; i++) {
            for (int j = 1; j <= cols; j++) {
                // Condition 1: All Goals must be visited
                if (grid[i][j] == GOAL_CELL && !visited[i][j]) {
                    return false;
                }
                // Condition 2: No Special cells should be visited
                if (grid[i][j] == SPECIAL_CELL && visited[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.StringTokenizer;

/**
 * Solves the grid reachability problem where certain cells are blocked 
 * or act as "bombs" that block surrounding cells.
 */
public class Main {

    public static void main(String[] args) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String firstLine = reader.readLine();
            if (firstLine == null) return;

            int testCases = Integer.parseInt(firstLine.trim());

            while (testCases-- > 0) {
                GridReachabilitySolver solver = new GridReachabilitySolver(reader);
                System.out.println(solver.solve() ? "Yes" : "No");
            }
        } catch (IOException | NumberFormatException e) {
            System.err.println("Error processing input: " + e.getMessage());
        }
    }
}

class GridReachabilitySolver {

    private static final int[] ROW_DIRECTION = {-1, 1, 0, 0};
    private static final int[] COL_DIRECTION = {0, 0, -1, 1};

    private final BufferedReader reader;

    public GridReachabilitySolver(BufferedReader reader) {
        this.reader = reader;
    }

    /**
     * Executes the core logic for a single test case.
     * @return true if all 'G' (Good) cells are reachable from the bottom-right corner.
     */
    public boolean solve() throws IOException {
        StringTokenizer st = new StringTokenizer(reader.readLine());
        int rows = Integer.parseInt(st.nextToken());
        int cols = Integer.parseInt(st.nextToken());

        char[][] grid = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            grid[r] = reader.readLine().toCharArray();
        }

        boolean[][] isBlocked = computeBlockedMatrix(grid, rows, cols);
        int totalGoodCells = countTotalGoodCells(grid, rows, cols);

        // If there are no good cells, the condition is vacuously true.
        if (totalGoodCells == 0) {
            return true;
        }

        int reachableGoodCells = countReachableGoodCells(grid, isBlocked, rows, cols);

        return reachableGoodCells == totalGoodCells;
    }

    /**
     * Creates a map of blocked cells. 
     * '#' is blocked. 'B' blocks itself and its 4 immediate neighbors.
     */
    private boolean[][] computeBlockedMatrix(char[][] grid, int rows, int cols) {
        boolean[][] blocked = new boolean[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '#') {
                    blocked[r][c] = true;
                } else if (grid[r][c] == 'B') {
                    blocked[r][c] = true;
                    // Mark neighbors as blocked
                    for (int i = 0; i < 4; i++) {
                        int nr = r + ROW_DIRECTION[i];
                        int nc = c + COL_DIRECTION[i];
                        if (isValid(nr, nc, rows, cols)) {
                            blocked[nr][nc] = true;
                        }
                    }
                }
            }
        }
        return blocked;
    }

    private int countTotalGoodCells(char[][] grid, int rows, int cols) {
        int count = 0;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 'G') {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Performs a Breadth-First Search starting from the bottom-right corner
     * to count how many 'G' cells are reachable.
     */
    private int countReachableGoodCells(char[][] grid, boolean[][] isBlocked, int rows, int cols) {
        int reachableCount = 0;
        boolean[][] visited = new boolean[rows][cols];
        Deque<int[]> queue = new ArrayDeque<>();

        int startRow = rows - 1;
        int startCol = cols - 1;

        // Check if start position is valid and not blocked
        if (!isValid(startRow, startCol, rows, cols) || isBlocked[startRow][startCol]) {
            return 0;
        }

        queue.add(new int[]{startRow, startCol});
        visited[startRow][startCol] = true;

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int r = current[0];
            int c = current[1];

            if (grid[r][c] == 'G') {
                reachableCount++;
            }

            for (int i = 0; i < 4; i++) {
                int nr = r + ROW_DIRECTION[i];
                int nc = c + COL_DIRECTION[i];

                if (isValid(nr, nc, rows, cols) && !visited[nr][nc] && !isBlocked[nr][nc]) {
                    visited[nr][nc] = true;
                    queue.add(new int[]{nr, nc});
                }
            }
        }

        return reachableCount;
    }

    private boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

import java.util.*;
import java.io.*;

/**
 * A solver for the Maze Escape problem.
 * The goal is to determine if all 'G' (Goal) cells are reachable from the exit (bottom-right)
 * after bombs ('B') have blocked adjacent paths ('.').
 */
public class MazeEscapeSolver {

    private static final int[][] DIRECTIONS = {
        {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        int testCases = scanner.nextInt();
        for (int t = 0; t < testCases; t++) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            char[][] grid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                grid[i] = scanner.next().toCharArray();
            }

            if (solve(grid, rows, cols)) {
                writer.println("Yes");
            } else {
                writer.println("No");
            }
        }
        writer.close();
    }

    /**
     * Orchestrates the logic for a single maze test case.
     */
    private static boolean solve(char[][] grid, int rows, int cols) {
        // 1. Process bombs: Bombs block adjacent '.' and destroy adjacent 'G'
        if (!applyBombEffects(grid, rows, cols)) {
            return false;
        }

        // 2. Check reachability: Verify all 'G' cells can be reached from the exit
        return isAllGoalsReachable(grid, rows, cols);
    }

    /**
     * Handles the impact of bombs on the maze.
     * If a bomb is adjacent to a Goal ('G'), the escape is impossible.
     * If a bomb is adjacent to a Path ('.'), that path becomes a Wall ('#').
     * 
     * @return false if a bomb destroys a goal, true otherwise.
     */
    private static boolean applyBombEffects(char[][] grid, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 'B') {
                    for (int[] dir : DIRECTIONS) {
                        int nr = r + dir[0];
                        int nc = c + dir[1];

                        if (isValid(nr, nc, rows, cols)) {
                            if (grid[nr][nc] == 'G') {
                                return false; // Bomb hits a Goal
                            } else if (grid[nr][nc] == '.') {
                                grid[nr][nc] = '#'; // Bomb blocks a path
                            }
                        }
                    }
                }
            }
        }
        return true;
    }

    /**
     * Uses BFS to check if all 'G' cells are reachable from the exit (bottom-right).
     */
    private static boolean isAllGoalsReachable(char[][] grid, int rows, int cols) {
        boolean[][] visited = new boolean[rows][cols];

        // The original logic specifies BFS starts only if the exit itself is a path '.'
        if (grid[rows - 1][cols - 1] == '.') {
            performBFS(grid, rows, cols, visited);
        }

        // Verify if any 'G' remains unvisited
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 'G' && !visited[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Standard Breadth-First Search to mark all reachable cells from the exit.
     */
    private static void performBFS(char[][] grid, int rows, int cols, boolean[][] visited) {
        Queue<Point> queue = new LinkedList<>();
        Point exit = new Point(rows - 1, cols - 1);

        queue.add(exit);
        visited[exit.row][exit.col] = true;

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            for (int[] dir : DIRECTIONS) {
                int nr = current.row + dir[0];
                int nc = current.col + dir[1];

                if (isValid(nr, nc, rows, cols) && !visited[nr][nc]) {
                    // Can travel through paths ('.') or goals ('G')
                    if (grid[nr][nc] == '.' || grid[nr][nc] == 'G') {
                        visited[nr][nc] = true;
                        queue.add(new Point(nr, nc));
                    }
                }
            }
        }
    }

    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Represents a coordinate in the 2D grid.
     */
    private record Point(int row, int col) {}

    /**
     * Fast I/O utility class.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream s) {
            br = new BufferedReader(new InputStreamReader(s));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A refactored solution for the grid traversal problem.
 * The goal is to determine if all 'G' (Green) cells can be reached from the bottom-right
 * corner after certain 'B' (Black) cells and their neighbors are "blocked".
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int testCases = reader.nextInt();
        while (testCases-- > 0) {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            GridSolver solver = new GridSolver(rows, cols, grid);
            out.println(solver.solve() ? "Yes" : "No");
        }
        out.flush();
        out.close();
    }

    /**
     * Represents a single coordinate in the grid.
     */
    static class Point {
        final int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Handles the logic for a single test case.
     */
    static class GridSolver {
        private static final int[] DX = {-1, 0, 1, 0};
        private static final int[] DY = {0, -1, 0, 1};

        private final int rows;
        private final int cols;
        private final char[][] originalGrid;
        private final char[][] modifiedGrid;
        private int totalGreenCount = 0;

        public GridSolver(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.originalGrid = grid;
            this.modifiedGrid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    this.modifiedGrid[i][j] = grid[i][j];
                    if (grid[i][j] == 'G') {
                        totalGreenCount++;
                    }
                }
            }
        }

        public boolean solve() {
            // If there are no green cells, the condition is satisfied immediately.
            if (totalGreenCount == 0) {
                return true;
            }

            // 1. Find all 'B' cells reachable from the bottom-right corner (n-1, m-1) 
            // using the original grid (respecting '#' blockers).
            List<Point> reachableBlackCells = findReachableBlackCells();

            // 2. Apply "damage": Mark reachable 'B' cells and their neighbors as '#' in modifiedGrid.
            // If a 'B' cell is adjacent to a 'G', the scenario becomes impossible.
            boolean possible = applyDamage(reachableBlackCells);

            // If the starting point (bottom-right) was blocked during damage, it's impossible.
            if (modifiedGrid[rows - 1][cols - 1] == '#') {
                possible = false;
            }

            if (!possible) {
                return false;
            }

            // 3. Perform a BFS from the bottom-right corner on the modified grid 
            // to see how many 'G' cells can still be reached.
            int greenReached = countReachableGreenCells();

            return greenReached == totalGreenCount;
        }

        private List<Point> findReachableBlackCells() {
            List<Point> blackPoints = new ArrayList<>();
            Queue<Point> queue = new ArrayDeque<>();
            boolean[][] visited = new boolean[rows][cols];

            // Starting BFS from the bottom-right corner
            Point start = new Point(rows - 1, cols - 1);
            queue.add(start);
            visited[start.r][start.c] = true;

            while (!queue.isEmpty()) {
                Point curr = queue.poll();

                if (originalGrid[curr.r][curr.c] == 'B') {
                    blackPoints.add(curr);
                }

                for (int i = 0; i < 4; i++) {
                    int nr = curr.r + DX[i];
                    int nc = curr.c + DY[i];

                    if (isValid(nr, nc) && !visited[nr][nc] && originalGrid[nr][nc] != '#') {
                        visited[nr][nc] = true;
                        queue.add(new Point(nr, nc));
                    }
                }
            }
            return blackPoints;
        }

        private boolean applyDamage(List<Point> blackPoints) {
            boolean possible = true;
            for (Point p : blackPoints) {
                for (int i = 0; i < 4; i++) {
                    int nr = p.r + DX[i];
                    int nc = p.c + DY[i];

                    if (isValid(nr, nc) && originalGrid[nr][nc] != '#') {
                        if (originalGrid[nr][nc] == 'G') {
                            possible = false;
                            // We continue to process damage even if possible becomes false
                        } else {
                            modifiedGrid[nr][nc] = '#';
                        }
                    }
                }
                // Mark the black cell itself as blocked
                modifiedGrid[p.r][p.c] = '#';
            }
            return possible;
        }

        private int countReachableGreenCells() {
            int count = 0;
            Queue<Point> queue = new ArrayDeque<>();
            boolean[][] visited = new boolean[rows][cols];

            Point start = new Point(rows - 1, cols - 1);
            queue.add(start);
            visited[start.r][start.c] = true;

            while (!queue.isEmpty()) {
                Point curr = queue.poll();

                // If this cell is a green cell, count it
                if (modifiedGrid[curr.r][curr.c] == 'G') {
                    count++;
                }

                // If the current cell is a blocker, we cannot pass through it
                if (modifiedGrid[curr.r][curr.c] == '#') {
                    continue;
                }

                for (int i = 0; i < 4; i++) {
                    int nr = curr.r + DX[i];
                    int nc = curr.c + DY[i];

                    if (isValid(nr, nc) && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        queue.add(new Point(nr, nc));
                    }
                }
            }
            return count;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solution to determine if all goal cells in a grid are reachable from the exit,
 * considering the spreading effects of bombs.
 */
public class Solution {

    // Constants for cell types to avoid magic characters
    private static final char CELL_PATH = '.';
    private static final char CELL_BOMB = 'B';
    private static final char CELL_GOAL = 'G';
    private static final char CELL_OBSTACLE = '#';

    /**
     * Represents a 2D coordinate in the grid.
     */
    private record Point(int row, int col) {}

    /**
     * Handles the logic for solving the maze.
     */
    private static class MazeSolver {
        private final char[][] grid;
        private final int rows;
        private final int cols;

        private static final int[][] DIRECTIONS = {
            {1, 0}, {-1, 0}, {0, 1}, {0, -1}
        };

        public MazeSolver(char[][] grid) {
            this.grid = grid;
            this.rows = grid.length;
            this.cols = grid[0].length;
        }

        /**
         * Executes the game logic.
         * @return true if all goals are reachable and no bombs are adjacent to goals.
         */
        public boolean isPossible() {
            if (!applyBombEffects()) {
                return false;
            }
            return areAllGoalsReachable();
        }

        /**
         * Simulates the bomb effect: bombs turn adjacent paths into obstacles.
         * If a bomb is adjacent to a goal, the mission fails immediately.
         * 
         * @return false if a bomb is next to a goal, true otherwise.
         */
        private boolean applyBombEffects() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == CELL_BOMB) {
                        if (!processBombNeighbors(r, c)) {
                            return false;
                        }
                    }
                }
            }
            return true;
        }

        private boolean processBombNeighbors(int r, int c) {
            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                if (isWithinBounds(nr, nc)) {
                    if (grid[nr][nc] == CELL_GOAL) {
                        return false; // Immediate failure if bomb touches a goal
                    }
                    if (grid[nr][nc] == CELL_PATH) {
                        grid[nr][nc] = CELL_OBSTACLE; // Path becomes an obstacle
                    }
                }
            }
            return true;
        }

        /**
         * Uses BFS to find all reachable cells from the exit (bottom-right corner).
         * 
         * @return true if every 'G' cell in the grid was visited.
         */
        private boolean areAllGoalsReachable() {
            boolean[][] visited = new boolean[rows][cols];
            Queue<Point> queue = new LinkedList<>();

            int startR = rows - 1;
            int startC = cols - 1;

            // Start BFS if the exit is not an obstacle
            if (isWithinBounds(startR, startC) && isTraversable(startR, startC)) {
                queue.add(new Point(startR, startC));
                visited[startR][startC] = true;
            }

            while (!queue.isEmpty()) {
                Point current = queue.poll();

                for (int[] dir : DIRECTIONS) {
                    int nr = current.row() + dir[0];
                    int nc = current.col() + dir[1];

                    if (isWithinBounds(nr, nc) && !visited[nr][nc] && isTraversable(nr, nc)) {
                        visited[nr][nc] = true;
                        queue.add(new Point(nr, nc));
                    }
                }
            }

            return verifyGoalReachability(visited);
        }

        private boolean verifyGoalReachability(boolean[][] visited) {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == CELL_GOAL && !visited[r][c]) {
                        return false;
                    }
                }
            }
            return true;
        }

        private boolean isTraversable(int r, int c) {
            return grid[r][c] != CELL_OBSTACLE;
        }

        private boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String firstLine = reader.readLine();
        if (firstLine == null) return;

        int testCases = Integer.parseInt(firstLine.trim());
        StringBuilder output = new StringBuilder();

        for (int t = 0; t < testCases; t++) {
            StringTokenizer st = new StringTokenizer(reader.readLine());
            int n = Integer.parseInt(st.nextToken());
            int m = Integer.parseInt(st.nextToken());

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                grid[i] = reader.readLine().toCharArray();
            }

            MazeSolver solver = new MazeSolver(grid);
            output.append(solver.isPossible() ? "Yes\n" : "No\n");
        }

        System.out.print(output.toString());
    }
}

import java.util.*;
import java.io.*;

/**
 * Refactored solution for the Grid Connectivity problem.
 * This program determines if all 'Good' cells are reachable from the bottom-right 
 * corner of a grid, considering constraints imposed by 'Bad' cells.
 */
public class GridConnectivityProblem {

    // Constants for direction traversal (Up, Down, Left, Right)
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    // Constants for cell types
    private static final char BAD_CELL = 'B';
    private static final char GOOD_CELL = 'G';
    private static final char BLOCKED_CELL = '#';

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            String tStr = reader.next();
            if (tStr == null) return;
            int testCases = Integer.parseInt(tStr);

            while (testCases-- > 0) {
                int rows = reader.nextInt();
                int cols = reader.nextInt();
                char[][] grid = new char[rows][cols];

                for (int i = 0; i < rows; i++) {
                    String line = reader.next();
                    for (int j = 0; j < cols; j++) {
                        grid[i][j] = line.charAt(j);
                    }
                }

                GridSolver solver = new GridSolver(grid, rows, cols);
                out.println(solver.solve() ? "Yes" : "No");
            }
        } catch (Exception e) {
            // In a production environment, use a proper logger.
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Encapsulates the logic for solving a single grid instance.
     */
    static class GridSolver {
        private final char[][] grid;
        private final int rows;
        private final int cols;

        public GridSolver(char[][] grid, int rows, int cols) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
        }

        /**
         * Executes the core algorithm:
         * 1. Checks if any 'Bad' cell is adjacent to a 'Good' cell.
         * 2. Marks non-essential cells adjacent to 'Bad' cells as blocked.
         * 3. Uses BFS to check connectivity from the bottom-right corner.
         * 
         * @return true if all 'Good' cells are reachable and valid.
         */
        public boolean solve() {
            char[][] processedGrid = createProcessedGrid();
            boolean badAdjacentToGood = checkBadCellProximity(processedGrid);

            if (badAdjacentToGood) {
                return false;
            }

            boolean[][] visited = performBFS(processedGrid);

            return verifyAllGoodCellsVisited(visited);
        }

        private char[][] createProcessedGrid() {
            char[][] copy = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                copy[i] = grid[i].clone();
            }
            return copy;
        }

        private boolean checkBadCellProximity(char[][] processedGrid) {
            boolean invalid = false;
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == BAD_CELL) {
                        for (int d = 0; d < 4; d++) {
                            int ni = i + DR[d];
                            int nj = j + DC[d];

                            if (isWithinBounds(ni, nj)) {
                                if (grid[ni][nj] == GOOD_CELL) {
                                    invalid = true;
                                } else if (grid[ni][nj] != BAD_CELL) {
                                    processedGrid[ni][nj] = BLOCKED_CELL;
                                }
                            }
                        }
                    }
                }
            }
            return invalid;
        }

        private boolean[][] performBFS(char[][] processedGrid) {
            boolean[][] visited = new boolean[rows][cols];
            Queue<int[]> queue = new ArrayDeque<>();

            int startR = rows - 1;
            int startC = cols - 1;

            if (isWithinBounds(startR, startC) && processedGrid[startR][startC] != BLOCKED_CELL) {
                visited[startR][startC] = true;
                queue.add(new int[]{startR, startC});
            }

            while (!queue.isEmpty()) {
                int[] current = queue.poll();
                int r = current[0];
                int c = current[1];

                for (int d = 0; d < 4; d++) {
                    int nr = r + DR[d];
                    int nc = c + DC[d];

                    if (isWithinBounds(nr, nc) && !visited[nr][nc] && processedGrid[nr][nc] != BLOCKED_CELL) {
                        visited[nr][nc] = true;
                        queue.add(new int[]{nr, nc});
                    }
                }
            }
            return visited;
        }

        private boolean verifyAllGoodCellsVisited(boolean[][] visited) {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == GOOD_CELL && !visited[i][j]) {
                        return false;
                    }
                }
            }
            return true;
        }

        private boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * High-performance input reader.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to solve a grid-based reachability problem.
 * Determines if all goals ('G') are reachable from the bottom-right corner.
 */
public class MazeSolver {

    private static final int WALL = 1;
    private static final int GOAL = 2;
    private static final int EMPTY = 0;

    private static final int[] ROW_OFFSETS = {1, 0, -1, 0};
    private static final int[] COL_OFFSETS = {0, 1, 0, -1};

    private final int rows;
    private final int cols;
    private final int[][] grid;
    private int totalGoals = 0;

    /**
     * Represents a coordinate in the grid.
     */
    private record Point(int r, int c) {}

    public MazeSolver(int rows, int cols) {
        this.rows = rows;
        this.cols = cols;
        // Padding the grid with +2 to account for boundaries (index 0 and index max+1)
        this.grid = new int[rows + 2][cols + 2];
        initializeGrid();
    }

    private void initializeGrid() {
        // Fill the entire grid with walls (the boundary)
        for (int i = 0; i < grid.length; i++) {
            Arrays.fill(grid[i], WALL);
        }
    }

    /**
     * Populates the grid based on the input strings.
     * 
     * @param inputRows A list of strings representing the maze rows.
     */
    public void loadMaze(List<String> inputRows) {
        for (int r = 0; r < rows; r++) {
            String currentRow = inputRows.get(r);
            for (int c = 0; c < cols; c++) {
                char cell = currentRow.charAt(c);
                int gridR = r + 1;
                int gridC = c + 1;

                // Set cell to empty before processing character types
                grid[gridR][gridC] = EMPTY;

                if (cell == '#') {
                    grid[gridR][gridC] = WALL;
                } else if (cell == 'G') {
                    grid[gridR][gridC] = GOAL;
                    totalGoals++;
                } else if (cell == 'B') {
                    applyBomb(gridR, gridC);
                }
            }
        }
    }

    private void applyBomb(int r, int c) {
        for (int i = 0; i < 4; i++) {
            int nr = r + ROW_OFFSETS[i];
            int nc = c + COL_OFFSETS[i];
            // Ensure we stay within the padded grid boundaries
            if (nr >= 0 && nr < grid.length && nc >= 0 && nc < grid[0].length) {
                grid[nr][nc] = WALL;
            }
        }
    }

    /**
     * Uses BFS to determine if all goals are reachable from the start position.
     * 
     * @return true if all goals are reachable, false otherwise.
     */
    public boolean solve() {
        // The start position is defined as the bottom-right corner of the input area
        int startR = rows;
        int startC = cols;

        // If the starting position is a wall, we cannot move anywhere
        if (grid[startR][startC] == WALL) {
            return false;
        }

        int reachableGoals = 0;
        boolean[][] visited = new boolean[rows + 2][cols + 2];
        Queue<Point> queue = new ArrayDeque<>();

        queue.add(new Point(startR, startC));
        visited[startR][startC] = true;

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            if (grid[current.r][current.c] == GOAL) {
                reachableGoals++;
            }

            for (int i = 0; i < 4; i++) {
                int nextR = current.r + ROW_OFFSETS[i];
                int nextC = current.c + COL_OFFSETS[i];

                if (isValidMove(nextR, nextC, visited)) {
                    visited[nextR][nextC] = true;
                    queue.add(new Point(nextR, nextC));
                }
            }
        }

        return reachableGoals == totalGoals;
    }

    private boolean isValidMove(int r, int c, boolean[][] visited) {
        return r >= 0 && r < grid.length && 
               c >= 0 && c < grid[0].length && 
               grid[r][c] != WALL && 
               !visited[r][c];
    }

    /**
     * Entry point for the application.
     */
    public static void main(String[] args) {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             BufferedWriter bw = new BufferedWriter(new OutputStreamWriter(System.out))) {

            String firstLine = br.readLine();
            if (firstLine == null) return;

            int testCases = Integer.parseInt(firstLine.trim());

            for (int t = 0; t < testCases; t++) {
                String[] dims = br.readLine().split("\\s+");
                int r = Integer.parseInt(dims[0]);
                int c = Integer.parseInt(dims[1]);

                List<String> mazeData = new ArrayList<>();
                for (int i = 0; i < r; i++) {
                    mazeData.add(br.readLine());
                }

                MazeSolver solver = new MazeSolver(r, c);
                solver.loadMaze(mazeData);

                if (solver.solve()) {
                    bw.write("Yes\n");
                } else {
                    bw.write("No\n");
                }
            }
            bw.flush();

        } catch (IOException | NumberFormatException e) {
            System.err.println("Error processing input: " + e.getMessage());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * Solution to the Grid Pathfinding problem.
 * The goal is to determine if all 'Goal' cells are reachable from the bottom-right exit
 * given certain movement restrictions imposed by 'Block' cells.
 */
public class Solution {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int numTestCases = reader.nextInt();
            while (numTestCases-- > 0) {
                int rows = reader.nextInt();
                int cols = reader.nextInt();
                char[][] gridData = reader.readGrid(rows, cols);

                PathfindingSolver solver = new PathfindingSolver(gridData);
                out.println(solver.solve() ? "Yes" : "No");
            }
        } catch (Exception e) {
            // In a production environment, use a logger.
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Encapsulates the logic for validating the grid and checking reachability.
     */
    static class PathfindingSolver {
        private static final int[][] DIRECTIONS = {
            {-1, 0}, {1, 0}, {0, -1}, {0, 1}
        };

        private static final char CELL_BLOCK = 'B';
        private static final char CELL_GOAL = 'G';
        private static final char CELL_EMPTY = '.';
        private static final char CELL_OBSTACLE = '#';

        private final char[][] grid;
        private final int rows;
        private final int cols;

        public PathfindingSolver(char[][] grid) {
            this.grid = grid;
            this.rows = grid.length;
            this.cols = grid[0].length;
        }

        public boolean solve() {
            int totalGoals = 0;

            // Step 1: Pre-process the grid
            // 'B' cells turn adjacent '.' cells into '#' obstacles.
            // If 'B' is adjacent to 'G', the configuration is invalid.
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == CELL_GOAL) {
                        totalGoals++;
                    } else if (grid[r][c] == CELL_BLOCK) {
                        if (isAdjacentToGoal(r, c)) {
                            return false; // Immediate failure
                        }
                        applyObstaclesAroundBlock(r, c);
                    }
                }
            }

            if (totalGoals == 0) {
                return true;
            }

            // Step 2: Check if exit is blocked
            if (grid[rows - 1][cols - 1] == CELL_OBSTACLE) {
                return false;
            }

            // Step 3: Use BFS to count how many goals are reachable from the exit
            return countReachableGoalsFromExit(rows - 1, cols - 1) == totalGoals;
        }

        private boolean isAdjacentToGoal(int r, int c) {
            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (isValid(nr, nc) && grid[nr][nc] == CELL_GOAL) {
                    return true;
                }
            }
            return false;
        }

        private void applyObstaclesAroundBlock(int r, int c) {
            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (isValid(nr, nc) && grid[nr][nc] == CELL_EMPTY) {
                    grid[nr][nc] = CELL_OBSTACLE;
                }
            }
        }

        private int countReachableGoalsFromExit(int startR, int startC) {
            int reachableGoals = 0;
            boolean[][] visited = new boolean[rows][cols];
            Deque<int[]> queue = new ArrayDeque<>();

            queue.offer(new int[]{startR, startC});
            visited[startR][startC] = true;

            while (!queue.isEmpty()) {
                int[] curr = queue.poll();
                int r = curr[0];
                int c = curr[1];

                if (grid[r][c] == CELL_GOAL) {
                    reachableGoals++;
                }

                for (int[] dir : DIRECTIONS) {
                    int nr = r + dir[0];
                    int nc = c + dir[1];

                    if (isValid(nr, nc) && !visited[nr][nc] && grid[nr][nc] != CELL_OBSTACLE) {
                        visited[nr][nc] = true;
                        queue.offer(new int[]{nr, nc});
                    }
                }
            }
            return reachableGoals;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * High-performance input reader for handling large datasets.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public char[][] readGrid(int rows, int cols) {
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }
            return grid;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Represents a coordinate point in the grid.
 */
class Point {
    final int r;
    final int c;

    Point(int r, int c) {
        this.r = r;
        this.c = c;
    }
}

/**
 * Holds the results of a grid component traversal.
 */
class ComponentResult {
    final int greenCount;
    final List<Point> blueCells;

    ComponentResult(int greenCount, List<Point> blueCells) {
        this.greenCount = greenCount;
        this.blueCells = blueCells;
    }
}

/**
 * Encapsulates the grid data and provides safe access to its cells.
 */
class Grid {
    public static final char GREEN = 'G';
    public static final char BLUE = 'B';
    public static final char EMPTY = '.';
    public static final char WALL = '#';

    private final int rows;
    private final int cols;
    private final char[][] cells;

    public Grid(int rows, int cols) {
        this.rows = rows;
        this.cols = cols;
        this.cells = new char[rows][cols];
    }

    public void setCell(int r, int c, char type) {
        cells[r][c] = type;
    }

    public char getCell(int r, int c) {
        return cells[r][c];
    }

    public int getRows() {
        return rows;
    }

    public int getCols() {
        return cols;
    }

    public boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    public int countTotalCellsOfType(char type) {
        int count = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (cells[i][j] == type) count++;
            }
        }
        return count;
    }
}

/**
 * Contains the logic to solve the grid problem.
 */
class GridSolver {
    private static final int[][] DIRECTIONS = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};
    private final Grid grid;

    public GridSolver(Grid grid) {
        this.grid = grid;
    }

    public String solve() {
        int totalGreenCount = grid.countTotalCellsOfType(Grid.GREEN);

        // First pass: Check if all green cells are in the component reachable from the bottom-right
        ComponentResult firstPass = performDFS(grid.getRows() - 1, grid.getCols() - 1);

        if (firstPass.greenCount != totalGreenCount) {
            return "No";
        }

        // Attempt to isolate blue cells by turning adjacent empty cells into walls
        for (Point blueCell : firstPass.blueCells) {
            for (int[] dir : DIRECTIONS) {
                int nr = blueCell.r + dir[0];
                int nc = blueCell.c + dir[1];

                if (grid.isWithinBounds(nr, nc)) {
                    char neighbor = grid.getCell(nr, nc);
                    if (neighbor == Grid.GREEN) {
                        return "No"; // Blue cannot be adjacent to Green
                    } else if (neighbor == Grid.EMPTY) {
                        grid.setCell(nr, nc, Grid.WALL);
                    }
                }
            }
        }

        // Second pass: Verify that the component now contains only green cells and no blue cells
        ComponentResult secondPass = performDFS(grid.getRows() - 1, grid.getCols() - 1);

        if (secondPass.greenCount == totalGreenCount && secondPass.blueCells.isEmpty()) {
            return "Yes";
        }

        return "No";
    }

    private ComponentResult performDFS(int startR, int startC) {
        int greenCount = 0;
        List<Point> blueCells = new ArrayList<>();
        boolean[][] visited = new boolean[grid.getRows()][grid.getCols()];

        if (grid.isWithinBounds(startR, startC) && grid.getCell(startR, startC) != Grid.WALL) {
            // Using an explicit stack to prevent StackOverflowError on large grids
            Deque<Point> stack = new ArrayDeque<>();
            stack.push(new Point(startR, startC));
            visited[startR][startC] = true;

            while (!stack.isEmpty()) {
                Point curr = stack.pop();

                if (grid.getCell(curr.r, curr.c) == Grid.GREEN) {
                    greenCount++;
                } else if (grid.getCell(curr.r, curr.c) == Grid.BLUE) {
                    blueCells.add(curr);
                }

                for (int[] dir : DIRECTIONS) {
                    int nr = curr.r + dir[0];
                    int nc = curr.c + dir[1];

                    if (grid.isWithinBounds(nr, nc) && !visited[nr][nc] && grid.getCell(nr, nc) != Grid.WALL) {
                        visited[nr][nc] = true;
                        stack.push(new Point(nr, nc));
                    }
                }
            }
        }

        return new ComponentResult(greenCount, blueCells);
    }
}

/**
 * Fast I/O utility.
 */
class FastReader {
    private final BufferedReader br;
    private StringTokenizer st;

    public FastReader(InputStream in) {
        br = new BufferedReader(new InputStreamReader(in));
    }

    public String next() {
        while (st == null || !st.hasMoreElements()) {
            try {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            } catch (IOException e) {
                return null;
            }
        }
        return st.nextToken();
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }

    public String nextLine() {
        try {
            return br.readLine();
        } catch (IOException e) {
            return null;
        }
    }
}

public class Main {
    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        String tStr = reader.next();
        if (tStr != null) {
            int t = Integer.parseInt(tStr);
            while (t-- > 0) {
                int n = reader.nextInt();
                int m = reader.nextInt();
                Grid grid = new Grid(n, m);

                for (int i = 0; i < n; i++) {
                    String line = reader.nextLine();
                    // Handle cases where nextLine might return empty due to nextInt() trailing newline
                    if (line == null || line.isEmpty()) {
                        line = reader.nextLine();
                    }
                    for (int j = 0; j < m; j++) {
                        grid.setCell(i, j, line.charAt(j));
                    }
                }

                GridSolver solver = new GridSolver(grid);
                out.println(solver.solve());
            }
        }
        out.close();
    }
}

import java.util.*;
import java.io.*;

/**
 * Represents the different types of cells present in the maze.
 */
enum CellType {
    EMPTY,    // '.'
    WALL,     // '#'
    BARRIER,  // 'B'
    GOAL      // 'G'
}

/**
 * A high-performance reader for parsing input efficiently.
 */
class FastReader {
    private BufferedReader reader;
    private StringTokenizer tokenizer;

    public FastReader(InputStream input) {
        reader = new BufferedReader(new InputStreamReader(input));
    }

    public String next() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreElements()) {
            String line = reader.readLine();
            if (line == null) return null;
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    public int nextInt() throws IOException {
        return Integer.parseInt(next());
    }
}

/**
 * Logic handler for solving the maze puzzle.
 */
class MazeSolver {
    private final int rows;
    private final int cols;
    private final CellType[][] grid;
    private final boolean[][] visited;

    private int totalGoals = 0;
    private int goalsFound = 0;
    private boolean reachedEnd = false;
    private int startRow = -1;
    private int startCol = -1;

    public MazeSolver(int rows, int cols, CellType[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.visited = new boolean[rows][cols];
    }

    /**
     * Executes the main logic: barrier validation, grid transformation, and goal reachability.
     * @return "Yes" if the conditions are met, otherwise "No".
     */
    public String solve() {
        // Phase 1: Identify goals and validate barriers
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == CellType.GOAL) {
                    totalGoals++;
                    if (startRow == -1) {
                        startRow = i;
                        startCol = j;
                    }
                }

                if (grid[i][j] == CellType.BARRIER) {
                    if (!applyBarrierEffect(i, j)) {
                        return "No"; // Barrier is adjacent to a goal
                    }
                }
            }
        }

        if (totalGoals == 0) {
            return "Yes";
        }

        if (startRow == -1) {
            return "No";
        }

        // Phase 2: DFS to check if we can visit all goals and reach the bottom-right corner
        performDfs(startRow, startCol);

        return (reachedEnd && goalsFound == totalGoals) ? "Yes" : "No";
    }

    /**
     * Replicates the original logic: if a barrier is adjacent to an empty cell, 
     * that cell becomes a wall. If adjacent to a goal, the configuration is invalid.
     */
    private boolean applyBarrierEffect(int r, int c) {
        int[] dr = {1, -1, 0, 0};
        int[] dc = {0, 0, 1, -1};

        for (int i = 0; i < 4; i++) {
            int nr = r + dr[i];
            int nc = c + dc[i];

            if (isValid(nr, nc)) {
                if (grid[nr][nc] == CellType.GOAL) {
                    return false;
                }
                if (grid[nr][nc] == CellType.EMPTY) {
                    grid[nr][nc] = CellType.WALL;
                }
            }
        }
        return true;
    }

    private void performDfs(int r, int c) {
        visited[r][c] = true;

        if (grid[r][c] == CellType.GOAL) {
            goalsFound++;
        }

        // Check if we reached the exit (bottom-right corner)
        if (r == rows - 1 && c == cols - 1) {
            reachedEnd = true;
        }

        int[] dr = {0, 0, 1, -1};
        int[] dc = {1, -1, 0, 0};

        for (int i = 0; i < 4; i++) {
            int nr = r + dr[i];
            int nc = c + dc[i];

            if (isTraversable(nr, nc)) {
                performDfs(nr, nc);
            }
        }
    }

    private boolean isTraversable(int r, int c) {
        return isValid(r, c) && !visited[r][c] && 
               grid[r][c] != CellType.WALL && grid[r][c] != CellType.BARRIER;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

public class Main {
    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        try {
            String tStr = reader.next();
            if (tStr == null) return;
            int t = Integer.parseInt(tStr);

            while (t-- > 0) {
                int n = reader.nextInt();
                int m = reader.nextInt();
                CellType[][] grid = new CellType[n][m];

                for (int i = 0; i < n; i++) {
                    String rowString = reader.next();
                    for (int j = 0; j < m; j++) {
                        grid[i][j] = parseCell(rowString.charAt(j));
                    }
                }

                MazeSolver solver = new MazeSolver(n, m, grid);
                System.out.println(solver.solve());
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private static CellType parseCell(char c) {
        switch (c) {
            case '.': return CellType.EMPTY;
            case '#': return CellType.WALL;
            case 'B': return CellType.BARRIER;
            case 'G': return CellType.GOAL;
            default: return CellType.WALL;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solution for the maze reachability problem.
 * The goal is to determine if all 'G' (Goal) cells can be reached from 
 * the bottom-right corner without hitting a 'X' (Trap) or a '#' (Wall).
 */
public class Solution {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        int testCases = reader.nextInt();

        while (testCases-- > 0) {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            String[] gridData = new String[rows];
            for (int i = 0; i < rows; i++) {
                gridData[i] = reader.next();
            }

            MazeSolver solver = new MazeSolver(rows, cols, gridData);
            System.out.println(solver.solve() ? "Yes" : "No");
        }
    }

    /**
     * Represents the different types of cells in the grid.
     */
    enum CellType {
        EMPTY, WALL, GOAL, TRAP;

        static CellType fromChar(char c) {
            return switch (c) {
                case '.' -> EMPTY;
                case '#' -> WALL;
                case 'G' -> GOAL;
                default -> TRAP; // Any other character is treated as a trap
            };
        }
    }

    /**
     * A simple immutable coordinate representation.
     */
    record Point(int r, int c) {}

    /**
     * Handles the grid state, parsing, and the application of environmental rules.
     */
    static class Maze {
        private final int rows;
        private final int cols;
        private final CellType[][] grid;
        private int totalGoals = 0;

        public Maze(int rows, int cols, String[] data) {
            this.rows = rows;
            this.cols = cols;
            this.grid = new CellType[rows][cols];
            parseGrid(data);
            applyTrapRules();
        }

        private void parseGrid(String[] data) {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    CellType type = CellType.fromChar(data[r].charAt(c));
                    grid[r][c] = type;
                    if (type == CellType.GOAL) {
                        totalGoals++;
                    }
                }
            }
        }

        /**
         * Traps ('X') make adjacent non-goal cells impassable ('#').
         */
        private void applyTrapRules() {
            int[] dr = {-1, 1, 0, 0};
            int[] dc = {0, 0, -1, 1};

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == CellType.TRAP) {
                        for (int i = 0; i < 4; i++) {
                            int nr = r + dr[i];
                            int nc = c + dc[i];
                            if (isValid(nr, nc) && isPassable(nr, nc)) {
                                grid[nr][nc] = CellType.WALL;
                            }
                        }
                    }
                }
            }
        }

        private boolean isPassable(int r, int c) {
            // Cells are passable if they are EMPTY or GOAL. 
            // (TRAP is also technically "passable" in the sense that BFS can enter it, 
            // but we treat it as a failure condition in the solver).
            return grid[r][c] == CellType.EMPTY || grid[r][c] == CellType.GOAL || grid[r][c] == CellType.TRAP;
        }

        public boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        public CellType getCell(int r, int c) {
            return grid[r][c];
        }

        public int getTotalGoals() {
            return totalGoals;
        }

        public int getRows() { return rows; }
        public int getCols() { return cols; }
    }

    /**
     * Executes the search algorithm to find reachable goals.
     */
    static class MazeSolver {
        private final Maze maze;

        public MazeSolver(int rows, int cols, String[] data) {
            this.maze = new Maze(rows, cols, data);
        }

        public boolean solve() {
            int startR = maze.getRows() - 1;
            int startC = maze.getCols() - 1;

            // If the starting point is a wall, we can only succeed if there are zero goals.
            if (maze.getCell(startR, startC) == CellType.WALL) {
                return maze.getTotalGoals() == 0;
            }

            Queue<Point> queue = new ArrayDeque<>();
            boolean[][] visited = new boolean[maze.getRows()][maze.getCols()];

            queue.add(new Point(startR, startC));
            visited[startR][startC] = true;

            int reachableGoals = 0;
            boolean trapEncountered = false;

            int[] dr = {-1, 1, 0, 0};
            int[] dc = {0, 0, -1, 1};

            while (!queue.isEmpty()) {
                Point curr = queue.poll();

                CellType type = maze.getCell(curr.r(), curr.c());
                if (type == CellType.GOAL) {
                    reachableGoals++;
                } else if (type == CellType.TRAP) {
                    trapEncountered = true;
                }

                for (int i = 0; i < 4; i++) {
                    int nr = curr.r() + dr[i];
                    int nc = curr.c() + dc[i];

                    if (maze.isValid(nr, nc) && !visited[nr][nc] && maze.getCell(nr, nc) != CellType.WALL) {
                        visited[nr][nc] = true;
                        queue.add(new Point(nr, nc));
                    }
                }
            }

            return !trapEncountered && (reachableGoals == maze.getTotalGoals());
        }
    }

    /**
     * High-performance input reader.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver for the Maze problem that determines if all gold cells ('G') 
 * are reachable from the exit (bottom-right corner) after bombs ('B') 
 * have destroyed adjacent empty paths ('.').
 */
public class MazeProblem {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int testCases = reader.nextInt();
            while (testCases-- > 0) {
                MazeSolver solver = new MazeSolver(reader);
                out.println(solver.solve() ? "Yes" : "No");
            }
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            out.close();
        }
    }

    /**
     * Encapsulates the logic for solving a single maze test case.
     */
    static class MazeSolver {
        private final FastReader reader;
        private int rows;
        private int cols;
        private char[][] grid;

        // Direction vectors for 4-connectivity (Up, Down, Left, Right)
        private static final int[] DR = {0, 0, 1, -1};
        private static final int[] DC = {1, -1, 0, 0};

        public MazeSolver(FastReader reader) {
            this.reader = reader;
        }

        public boolean solve() throws IOException {
            this.rows = reader.nextInt();
            this.cols = reader.nextInt();
            this.grid = new char[rows][cols];

            int totalGoldCount = 0;

            // 1. Load grid and count total Gold cells
            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                grid[i] = line.toCharArray();
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == 'G') {
                        totalGoldCount++;
                    }
                }
            }

            // 2. Process Bombs: Bombs destroy adjacent '.' cells.
            // If a bomb is adjacent to a 'G', the result is immediately "No".
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == 'B') {
                        if (!processBomb(r, c)) {
                            return false;
                        }
                    }
                }
            }

            // 3. Check reachability of all 'G' cells from the starting point (bottom-right)
            int reachableGoldCount = countReachableGold();

            return reachableGoldCount == totalGoldCount;
        }

        /**
         * Handles the logic for a bomb at (r, c).
         * @return false if a bomb is adjacent to a Gold cell, true otherwise.
         */
        private boolean processBomb(int r, int c) {
            for (int i = 0; i < 4; i++) {
                int nr = r + DR[i];
                int nc = c + DC[i];

                if (isInBounds(nr, nc)) {
                    if (grid[nr][nc] == 'G') {
                        return false; // Bomb adjacent to gold is invalid
                    } else if (grid[nr][nc] == '.') {
                        grid[nr][nc] = '#'; // Bomb destroys empty path
                    }
                }
            }
            return true;
        }

        /**
         * Performs a BFS to count how many 'G' cells are reachable from (rows-1, cols-1).
         */
        private int countReachableGold() {
            int startR = rows - 1;
            int startC = cols - 1;

            // If start is a wall or bomb, we can't move anywhere
            if (!isInBounds(startR, startC) || grid[startR][startC] == '#' || grid[startR][startC] == 'B') {
                return 0;
            }

            int reachableCount = 0;
            boolean[][] visited = new boolean[rows][cols];
            Queue<Point> queue = new LinkedList<>();

            queue.add(new Point(startR, startC));
            visited[startR][startC] = true;

            while (!queue.isEmpty()) {
                Point current = queue.poll();

                if (grid[current.r][current.c] == 'G') {
                    reachableCount++;
                }

                for (int i = 0; i < 4; i++) {
                    int nr = current.r + DR[i];
                    int nc = current.c + DC[i];

                    if (isInBounds(nr, nc) && !visited[nr][nc] 
                            && grid[nr][nc] != '#' && grid[nr][nc] != 'B') {
                        visited[nr][nc] = true;
                        queue.add(new Point(nr, nc));
                    }
                }
            }

            return reachableCount;
        }

        private boolean isInBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * Simple data structure to represent a coordinate in the grid.
     */
    static class Point {
        int r, c;
        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Efficient input reader for competitive programming.
     */
    static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;

/**
 * A solution to the Maze problem that determines if all goal cells ('G') 
 * are reachable from the bottom-right corner of a grid, considering 
 * constraints imposed by blockers ('B') and walls ('#').
 */
public class SolveTheMaze {

    private static final char GOAL = 'G';
    private static final char BLOCKER = 'B';
    private static final char WALL = '#';
    private static final char PATH = '.';

    // Direction vectors for navigating Up, Down, Left, Right
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    /**
     * Represents a coordinate point in the grid.
     */
    private record Point(int row, int col) {}

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int testCases = scanner.nextInt();

        while (testCases-- > 0) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            char[][] grid = new char[rows][cols];
            int totalGoals = 0;

            for (int i = 0; i < rows; i++) {
                String line = scanner.next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                    if (grid[i][j] == GOAL) {
                        totalGoals++;
                    }
                }
            }

            System.out.println(solveMaze(grid, rows, cols, totalGoals) ? "Yes" : "No");
        }
        scanner.close();
    }

    /**
     * Orchestrates the logic to determine if the maze is solvable.
     */
    private static boolean solveMaze(char[][] grid, int rows, int cols, int totalGoals) {
        // Rule: If there are no goals, it's vacuously true.
        if (totalGoals == 0) {
            return true;
        }

        // 1. Pre-process the grid based on Blocker ('B') rules.
        if (!preprocessBlockers(grid, rows, cols)) {
            return false;
        }

        // 2. Check if the exit is blocked by a wall.
        if (grid[rows - 1][cols - 1] == WALL) {
            return false;
        }

        // 3. Count how many goals are reachable from the bottom-right exit using BFS.
        int reachableGoals = countReachableGoals(grid, rows, cols);

        return reachableGoals == totalGoals;
    }

    /**
     * Processes blockers. If a 'B' is next to a 'G', the maze is impossible.
     * If a 'B' is next to a '.', that path becomes a wall.
     * 
     * @return true if preprocessing completed without violating 'G' adjacency, false otherwise.
     */
    private static boolean preprocessBlockers(char[][] grid, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == BLOCKER) {
                    for (int i = 0; i < 4; i++) {
                        int nr = r + DR[i];
                        int nc = c + DC[i];

                        if (isValid(nr, nc, rows, cols)) {
                            if (grid[nr][nc] == GOAL) {
                                return false; // Blocker adjacent to Goal is impossible
                            } else if (grid[nr][nc] == PATH) {
                                grid[nr][nc] = WALL; // Blocker turns adjacent path into wall
                            }
                        }
                    }
                }
            }
        }
        return true;
    }

    /**
     * Uses Breadth-First Search to count reachable 'G' cells starting from the exit.
     */
    private static int countReachableGoals(char[][] grid, int rows, int cols) {
        int startR = rows - 1;
        int startC = cols - 1;

        // If start is a blocker, we can't move (per original logic behavior)
        if (grid[startR][startC] == BLOCKER) {
            return -1;
        }

        Queue<Point> queue = new LinkedList<>();
        boolean[][] visited = new boolean[rows][cols];

        queue.add(new Point(startR, startC));
        visited[startR][startC] = true;

        int goalCount = 0;

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            // Note: original code returns -1 if current is B, 
            // but BFS prevents adding B to queue.
            if (grid[current.row][current.col] == GOAL) {
                goalCount++;
            }

            for (int i = 0; i < 4; i++) {
                int nr = current.row + DR[i];
                int nc = current.col + DC[i];

                if (isValid(nr, nc, rows, cols) 
                        && !visited[nr][nc] 
                        && grid[nr][nc] != WALL 
                        && grid[nr][nc] != BLOCKER) {

                    visited[nr][nc] = true;
                    queue.add(new Point(nr, nc));
                }
            }
        }

        return goalCount;
    }

    /**
     * Helper to check if a coordinate is within grid boundaries.
     */
    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.*;

/**
 * An expert implementation of a Maze Solver that processes bombs 
 * and calculates reachability for specific targets.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        int testCases = reader.nextInt();
        StringBuilder output = new StringBuilder();

        for (int t = 0; t < testCases; t++) {
            MazeSolver solver = new MazeSolver(reader);
            output.append(solver.solve()).append(System.lineSeparator());
        }

        System.out.print(output);
    }

    /**
     * Represents a coordinate in the 2D grid.
     */
    record Point(int r, int c) {}

    /**
     * Handles the logic for a single maze test case.
     */
    static class MazeSolver {
        private static final int[] DR = {-1, 1, 0, 0};
        private static final int[] DC = {0, 0, -1, 1};

        private final FastReader reader;
        private int rows;
        private int cols;
        private char[][] grid;
        private int[][] distanceMap;

        public MazeSolver(FastReader reader) {
            this.reader = reader;
        }

        /**
         * Orchestrates the solving process.
         * @return "Yes" if the maze conditions are met, "No" otherwise.
         */
        public String solve() {
            if (!initializeGrid()) {
                return "No";
            }

            neutralizeBombs();
            runBreadthFirstSearch(rows, cols); // Start from bottom-right (n, m)

            return validateSolution() ? "Yes" : "No";
        }

        /**
         * Reads grid dimensions and populates the grid with padding to simplify boundary checks.
         */
        private boolean initializeGrid() {
            try {
                this.rows = reader.nextInt();
                this.cols = reader.nextInt();
                // Use padding (size + 2) to avoid array index out of bounds during neighbor checks
                this.grid = new char[rows + 2][cols + 2];

                // Fill borders with walls
                for (int i = 0; i < rows + 2; i++) {
                    Arrays.fill(grid[i], '#');
                }

                for (int i = 1; i <= rows; i++) {
                    String line = reader.next();
                    for (int j = 1; j <= cols; j++) {
                        grid[i][j] = line.charAt(j - 1);
                    }
                }
                return true;
            } catch (Exception e) {
                return false;
            }
        }

        /**
         * Processes bombs ('B'). If a cell is a bomb, its adjacent '.' paths become walls '#'.
         */
        private void neutralizeBombs() {
            for (int r = 1; r <= rows; r++) {
                for (int c = 1; c <= cols; c++) {
                    if (grid[r][c] == 'B') {
                        for (int i = 0; i < 4; i++) {
                            int nr = r + DR[i];
                            int nc = c + DC[i];
                            if (grid[nr][nc] == '.') {
                                grid[nr][nc] = '#';
                            }
                        }
                    }
                }
            }
        }

        /**
         * Performs BFS to find shortest distance from the starting point (rows, cols).
         */
        private void runBreadthFirstSearch(int startR, int startC) {
            distanceMap = new int[rows + 2][cols + 2];
            for (int[] row : distanceMap) {
                Arrays.fill(row, -1);
            }

            Deque<Point> queue = new ArrayDeque<>();

            // Start BFS from the specified bottom-right corner
            if (grid[startR][startC] != '#') {
                distanceMap[startR][startC] = 0;
                queue.add(new Point(startR, startC));
            }

            while (!queue.isEmpty()) {
                Point current = queue.poll();

                for (int i = 0; i < 4; i++) {
                    int nr = current.r() + DR[i];
                    int nc = current.c() + DC[i];

                    if (isTraversable(nr, nc) && distanceMap[nr][nc] == -1) {
                        distanceMap[nr][nc] = distanceMap[current.r()][current.c()] + 1;
                        queue.add(new Point(nr, nc));
                    }
                }
            }
        }

        private boolean isTraversable(int r, int c) {
            return grid[r][c] != '#';
        }

        /**
         * Validates the solution based on requirements:
         * 1. All Goals ('G') must be reachable.
         * 2. No Bombs ('B') should be reachable.
         */
        private boolean validateSolution() {
            for (int r = 1; r <= rows; r++) {
                for (int c = 1; c <= cols; c++) {
                    char cell = grid[r][c];
                    int dist = distanceMap[r][c];

                    if (cell == 'G' && dist == -1) {
                        return false; // Goal not reached
                    }
                    if (cell == 'B' && dist != -1) {
                        return false; // Bomb reached
                    }
                }
            }
            return true;
        }
    }

    /**
     * Optimized input reader for competitive programming performance.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader() {
            reader = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;

/**
 * Represents the possible types of cells in the grid.
 */
enum CellType {
    EMPTY,
    WALL,
    GOAL,
    BAD_NODE
}

/**
 * A simple data carrier for coordinates.
 */
record Point(int row, int col) {}

/**
 * Handles the logic for traversing the grid and determining if the path requirements are met.
 */
class GridPathfinder {
    private final CellType[][] grid;
    private final int rows;
    private final int cols;
    private int totalGoals = 0;

    private static final int[][] DIRECTIONS = {
        {1, 0}, {-1, 0}, {0, 1}, {0, -1}
    };

    public GridPathfinder(char[][] inputGrid, int rows, int cols) {
        this.rows = rows;
        this.cols = cols;
        this.grid = new CellType[rows][cols];
        List<Point> badNodes = new ArrayList<>();

        // 1. Parse the input characters into CellType enums
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                char ch = inputGrid[r][c];
                switch (ch) {
                    case '.' -> grid[r][c] = CellType.EMPTY;
                    case '#' -> grid[r][c] = CellType.WALL;
                    case 'G' -> {
                        grid[r][c] = CellType.GOAL;
                        totalGoals++;
                    }
                    default -> {
                        grid[r][c] = CellType.BAD_NODE;
                        badNodes.add(new Point(r, c));
                    }
                }
            }
        }

        // 2. Apply the "Bad Node" constraint: 
        // Neighbors of a BAD_NODE that are EMPTY become WALLs.
        applyBadNodeConstraints(badNodes);
    }

    private void applyBadNodeConstraints(List<Point> badNodes) {
        for (Point p : badNodes) {
            for (int[] dir : DIRECTIONS) {
                int nr = p.row() + dir[0];
                int nc = p.col() + dir[1];
                if (isWithinBounds(nr, nc) && grid[nr][nc] == CellType.EMPTY) {
                    grid[nr][nc] = CellType.WALL;
                }
            }
        }
    }

    /**
     * Executes the search starting from the bottom-right corner.
     * @return true if all goals are reached without touching a bad node.
     */
    public boolean solve() {
        int startRow = rows - 1;
        int startCol = cols - 1;

        // If the starting position is a wall, no path is possible.
        if (grid[startRow][startCol] == CellType.WALL) {
            return false;
        }

        Deque<Point> stack = new ArrayDeque<>();
        stack.push(new Point(startRow, startCol));

        boolean hitBadNode = false;
        int goalsFound = 0;
        boolean[][] visited = new boolean[rows][cols];

        while (!stack.isEmpty()) {
            Point current = stack.pop();
            int r = current.row();
            int c = current.col();

            if (visited[r][c]) {
                continue;
            }
            visited[r][c] = true;

            // Process the current cell
            if (grid[r][c] == CellType.BAD_NODE) {
                hitBadNode = true;
            } else if (grid[r][c] == CellType.GOAL) {
                goalsFound++;
            }

            // Explore adjacent cells
            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                if (isValidMove(nr, nc, visited)) {
                    stack.push(new Point(nr, nc));
                }
            }
        }

        return !hitBadNode && (goalsFound == totalGoals);
    }

    private boolean isValidMove(int r, int c, boolean[][] visited) {
        return isWithinBounds(r, c) && !visited[r][c] && grid[r][c] != CellType.WALL;
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int testCases = scanner.nextInt();
        while (testCases-- > 0) {
            int n = scanner.nextInt();
            int m = scanner.nextInt();
            char[][] inputGrid = new char[n][m];

            for (int i = 0; i < n; i++) {
                String rowString = scanner.next();
                inputGrid[i] = rowString.toCharArray();
            }

            GridPathfinder pathfinder = new GridPathfinder(inputGrid, n, m);
            if (pathfinder.solve()) {
                System.out.println("Yes");
            } else {
                System.out.println("No");
            }
        }
        scanner.close();
    }
}

import java.io.*;
import java.util.*;

/**
 * Represents a coordinate in the 2D grid.
 */
final class Point {
    private final int r;
    private final int c;

    public Point(int r, int c) {
        this.r = r;
        this.c = c;
    }

    public int getR() { return r; }
    public int getC() { return c; }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof Point)) return false;
        Point point = (Point) o;
        return r == point.r && c == point.c;
    }

    @Override
    public int hashCode() {
        return Objects.hash(r, c);
    }

    @Override
    public String toString() {
        return r + "," + c;
    }
}

/**
 * Encapsulates the maze grid and provides boundary-safe access.
 */
class Maze {
    private final int rows;
    private final int cols;
    private final char[][] grid;

    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public Maze(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
    }

    public int getRows() { return rows; }
    public int getCols() { return cols; }

    public char getCell(int r, int c) {
        return grid[r][c];
    }

    public void setCell(int r, int c, char val) {
        grid[r][c] = val;
    }

    public boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Returns valid adjacent neighbors based on a predicate.
     */
    public List<Point> getValidNeighbors(int r, int c, java.util.function.BiPredicate<Integer, Integer> condition) {
        List<Point> neighbors = new ArrayList<>();
        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];
            if (isWithinBounds(nr, nc) && condition.test(nr, nc)) {
                neighbors.add(new Point(nr, nc));
            }
        }
        return neighbors;
    }
}

/**
 * Contains the core logic for solving the maze task.
 */
class MazeSolver {
    public void solve(FastReader in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();
        char[][] rawGrid = in.readCharMatrix(n, m);
        Maze maze = new Maze(n, m, rawGrid);

        List<Point> goodPeople = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (rawGrid[i][j] == 'G') {
                    goodPeople.add(new Point(i, j));
                }
            }
        }

        // Step 1: Process Blockers ('B')
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (maze.getCell(i, j) == 'B') {
                    // Check neighbors of 'B'
                    List<Point> neighbors = maze.getValidNeighbors(i, j, (r, c) -> {
                        char cell = maze.getCell(r, c);
                        return cell == '.' || cell == 'G';
                    });

                    for (Point p : neighbors) {
                        if (maze.getCell(p.getR(), p.getC()) == 'G') {
                            out.println("No");
                            return;
                        }
                        // Mark empty cells next to 'B' as blocked
                        if (maze.getCell(p.getR(), p.getC()) == '.') {
                            maze.setCell(p.getR(), p.getC(), '#');
                        }
                    }
                }
            }
        }

        // Step 2: Check reachability from the exit (n-1, m-1) using BFS
        boolean[][] visited = new boolean[n][m];
        Queue<Point> queue = new LinkedList<>();

        int exitR = n - 1;
        int exitC = m - 1;

        if (maze.getCell(exitR, exitC) != '#') {
            queue.add(new Point(exitR, exitC));
            visited[exitR][exitC] = true;
        }

        while (!queue.isEmpty()) {
            Point curr = queue.poll();
            List<Point> neighbors = maze.getValidNeighbors(curr.getR(), curr.getC(), (r, c) -> 
                !visited[r][c] && maze.getCell(r, c) != '#'
            );

            for (Point next : neighbors) {
                visited[next.getR()][next.getC()] = true;
                queue.add(next);
            }
        }

        // Step 3: Verify if all 'G' were reached
        for (Point p : goodPeople) {
            if (!visited[p.getR()][p.getC()]) {
                out.println("No");
                return;
            }
        }

        out.println("Yes");
    }
}

/**
 * Efficient input reader for large datasets.
 */
class FastReader {
    private BufferedReader reader;
    private StringTokenizer tokenizer;

    public FastReader(InputStream is) {
        reader = new BufferedReader(new InputStreamReader(is));
    }

    public String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
        return tokenizer.nextToken();
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }

    public char[][] readCharMatrix(int n, int m) {
        char[][] matrix = new char[n][m];
        for (int i = 0; i < n; i++) {
            String line = next();
            for (int j = 0; j < m; j++) {
                matrix[i][j] = line.charAt(j);
            }
        }
        return matrix;
    }
}

