/**
 * A solver for the maze reachability problem.
 * The goal is to determine if all 'G' (Good) cells are reachable from the 
 * bottom-right cell (n, m) through '.' (Empty) cells, considering that 
 * 'B' (Block) cells turn adjacent '.' cells into '#' (Walls) and 
 * cannot be adjacent to 'G' cells.
 */
public class MazeSolver {

    // Constants for maze cell types to avoid "magic characters"
    private static final char CELL_GOOD = 'G';
    private static final char CELL_BLOCK = 'B';
    private static final char CELL_EMPTY = '.';
    private static final char CELL_WALL = '#';

    /**
     * Represents a coordinate in the 2D maze.
     */
    private static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) {
            return;
        }

        int testCases = scanner.nextInt();
        StringBuilder resultCollector = new StringBuilder();

        for (int t = 0; t < testCases; t++) {
            resultCollector.append(solveTestCase(scanner)).append("\n");
        }

        System.out.print(resultCollector);
        scanner.close();
    }

    /**
     * Handles the logic for a single test case.
     */
    private static String solveTestCase(Scanner scanner) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        // Initialize maze with a boundary of walls ('#') to prevent out-of-bounds.
        // Dimensions are (rows+2) x (cols+2) to accommodate 1-based indexing and padding.
        char[][] maze = new char[rows + 2][cols + 2];
        for (int i = 0; i < rows + 2; i++) {
            Arrays.fill(maze[i], CELL_WALL);
        }

        int totalGoodCells = 0;
        for (int i = 1; i <= rows; i++) {
            String rowString = scanner.next();
            for (int j = 1; j <= cols; j++) {
                char cell = rowString.charAt(j - 1);
                maze[i][j] = cell;
                if (cell == CELL_GOOD) {
                    totalGoodCells++;
                }
            }
        }

        // 1. Process Block ('B') constraints
        // 'B' cells turn adjacent '.' to '#' and cannot be adjacent to 'G'.
        for (int i = 1; i <= rows; i++) {
            for (int j = 1; j <= cols; j++) {
                if (maze[i][j] == CELL_BLOCK) {
                    if (!applyBlockConstraints(maze, i, j)) {
                        return "No";
                    }
                }
            }
        }

        // 2. Verify starting point accessibility
        // If the starting cell (n, m) is a wall and there are 'G' cells to reach, it's impossible.
        if (maze[rows][cols] == CELL_WALL && totalGoodCells > 0) {
            return "No";
        }

        // 3. Perform BFS to find all reachable 'G' cells from the starting point (rows, cols).
        int reachableGoodCells = performFloodFill(maze, rows, cols);

        return (reachableGoodCells == totalGoodCells) ? "Yes" : "No";
    }

    /**
     * Applies the rules for 'B' cells:
     * - If 'B' is adjacent to 'G', the configuration is invalid.
     * - If 'B' is adjacent to '.', that '.' becomes a wall.
     * @return true if the placement is valid, false if 'B' is adjacent to 'G'.
     */
    private static boolean applyBlockConstraints(char[][] maze, int r, int c) {
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int i = 0; i < 4; i++) {
            int nr = r + dr[i];
            int nc = c + dc[i];

            if (maze[nr][nc] == CELL_GOOD) {
                return false; 
            }
            if (maze[nr][nc] == CELL_EMPTY) {
                maze[nr][nc] = CELL_WALL;
            }
        }
        return true;
    }

    /**
     * Uses Breadth-First Search to find all 'G' cells reachable from the starting point.
     * Marks visited cells as '#' to prevent infinite loops.
     */
    private static int performFloodFill(char[][] maze, int startR, int startC) {
        int goodFoundCount = 0;
        Queue<Point> queue = new LinkedList<>();

        // Check if the starting cell is traversable
        if (maze[startR][startC] == CELL_GOOD || maze[startR][startC] == CELL_EMPTY) {
            if (maze[startR][startC] == CELL_GOOD) {
                goodFoundCount++;
            }
            // Mark as visited by turning it into a wall
            maze[startR][startC] = CELL_WALL;
            queue.add(new Point(startR, startC));
        }

        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            for (int i = 0; i < 4; i++) {
                int nr = current.row + dr[i];
                int nc = current.col + dc[i];

                // Bounds check is handled by the padding, but we verify for safety
                if (nr >= 0 && nr < maze.length && nc >= 0 && nc < maze[0].length) {
                    if (maze[nr][nc] == CELL_GOOD) {
                        goodFoundCount++;
                        maze[nr][nc] = CELL_WALL; // Mark visited
                        queue.add(new Point(nr, nc));
                    } else if (maze[nr][nc] == CELL_EMPTY) {
                        maze[nr][nc] = CELL_WALL; // Mark visited
                        queue.add(new Point(nr, nc));
                    }
                }
            }
        }

        return goodFoundCount;
    }
}

