class GridEscapeSolver {
    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final boolean[][] processedGoodPerson;

    private static final int[] DX = {1, 0, -1, 0};
    private static final int[] DY = {0, -1, 0, 1};

    /**
     * Represents a coordinate in the grid.
     */
    private record Point(int r, int c) {}

    public GridEscapeSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.processedGoodPerson = new boolean[rows][cols];
    }

    /**
     * Executes the main logic to determine if all 'G' can escape.
     * @return true if all 'G' can reach the exit, false otherwise.
     */
    public boolean solve() {
        // 1. Apply obstacles created by Bad Persons (B)
        if (!applyObstaclesAndValidate()) {
            return false;
        }

        // 2. Check if every 'G' can reach the exit (bottom-right corner)
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 'G' && !processedGoodPerson[i][j]) {
                    if (!canReachExit(new Point(i, j))) {
                        return false;
                    }
                }
            }
        }

        return true;
    }

    /**
     * Marks paths around 'B' as blocked ('#').
     * Returns false if a 'B' is directly adjacent to a 'G'.
     */
    private boolean applyObstaclesAndValidate() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 'B') {
                    for (int k = 0; k < 4; k++) {
                        int nextR = i + DX[k];
                        int nextC = j + DY[k];

                        if (isWithinBounds(nextR, nextC)) {
                            if (grid[nextR][nextC] == 'G') {
                                return false; // Bad person is too close to a Good person
                            } else if (grid[nextR][nextC] == '.') {
                                grid[nextR][nextC] = '#'; // Block the path
                            }
                        }
                    }
                }
            }
        }
        return true;
    }

    /**
     * Performs BFS to find if a path exists from the start to the exit.
     * Marks 'G' cells encountered during BFS as processed to avoid redundant searches.
     */
    private boolean canReachExit(Point start) {
        Deque<Point> queue = new ArrayDeque<>();
        boolean[][] visited = new boolean[rows][cols];

        queue.add(start);
        visited[start.r][start.c] = true;

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            // Check if we reached the exit
            if (current.r == rows - 1 && current.c == cols - 1) {
                return true;
            }

            for (int k = 0; k < 4; k++) {
                int nextR = current.r + DX[k];
                int nextC = current.c + DY[k];

                if (isWithinBounds(nextR, nextC) && !visited[nextR][nextC]) {
                    char cellType = grid[nextR][nextC];

                    if (cellType != '#') {
                        if (cellType == 'G') {
                            processedGoodPerson[nextR][nextC] = true;
                        }
                        visited[nextR][nextC] = true;
                        queue.add(new Point(nextR, nextC));
                    }
                }
            }
        }
        return false;
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

