/**
 * Encapsulates the logic for solving the maze problem.
 */
class MazeSolver {
    // Cell type constants
    private static final char CELL_BLOCKER = 'B';
    private static final char CELL_GOAL = 'G';
    private static final char CELL_WALL = '#';
    private static final char CELL_EMPTY = '.';

    // Directional vectors for movement (Up, Down, Left, Right)
    private static final int[][] DIRECTIONS = {
        {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    private final char[][] maze;
    private final int rows;
    private final int cols;

    public MazeSolver(char[][] maze) {
        this.maze = maze;
        this.rows = maze.length;
        this.cols = maze[0].length;
    }

    /**
     * Executes the solving algorithm.
     * @return true if all goals are reachable from the bottom-right corner.
     */
    public boolean solve() {
        // 1. Process blockers that turn adjacent empty spaces into walls.
        // If a blocker is adjacent to a goal, the condition fails immediately.
        if (!expandBlockers()) {
            return false;
        }

        // 2. Count total goals present in the maze.
        int totalGoals = countTotalGoals();

        // 3. Count how many goals can be reached from the bottom-right corner.
        int reachableGoals = countReachableGoals();

        return totalGoals == reachableGoals;
    }

    /**
     * Iterates through the maze and expands 'B' cells into adjacent '.' cells.
     * Returns false if any 'B' cell is adjacent to a 'G' cell.
     */
    private boolean expandBlockers() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (maze[i][j] == CELL_BLOCKER) {
                    for (int[] dir : DIRECTIONS) {
                        int ni = i + dir[0];
                        int nj = j + dir[1];

                        if (isWithinBounds(ni, nj)) {
                            if (maze[ni][nj] == CELL_GOAL) {
                                return false;
                            } else if (maze[ni][nj] == CELL_EMPTY) {
                                maze[ni][nj] = CELL_WALL;
                            }
                        }
                    }
                }
            }
        }
        return true;
    }

    /**
     * Scans the maze to count the total number of 'G' cells.
     */
    private int countTotalGoals() {
        int count = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (maze[i][j] == CELL_GOAL) {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Uses Breadth-First Search (BFS) to count reachable 'G' cells 
     * starting from the bottom-right corner (n-1, m-1).
     */
    private int countReachableGoals() {
        int startRow = rows - 1;
        int startCol = cols - 1;

        // If the starting point is a wall or out of bounds, no goals are reachable.
        if (!isWithinBounds(startRow, startCol) || maze[startRow][startCol] == CELL_WALL) {
            return 0;
        }

        int reachableCount = 0;
        boolean[][] visited = new boolean[rows][cols];
        Queue<int[]> queue = new LinkedList<>();

        queue.offer(new int[]{startRow, startCol});
        visited[startRow][startCol] = true;

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int r = current[0];
            int c = current[1];

            if (maze[r][c] == CELL_GOAL) {
                reachableCount++;
            }

            for (int[] dir : DIRECTIONS) {
                int ni = r + dir[0];
                int nj = c + dir[1];

                if (isWithinBounds(ni, nj) && !visited[ni][nj] && maze[ni][nj] != CELL_WALL) {
                    visited[ni][nj] = true;
                    queue.offer(new int[]{ni, nj});
                }
            }
        }

        return reachableCount;
    }

    /**
     * Helper to verify if coordinates are within the grid boundaries.
     */
    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

