/**
 * MazeSolver solves a maze problem where bombs ('B') can destroy paths ('.')
 * and potentially invalidate goals ('G').
 */
public class MazeSolver {

    private static final int[][] DIRECTIONS = {
        {-1, 0}, // Up
        {0, 1},  // Right
        {1, 0},  // Down
        {0, -1}  // Left
    };

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int testCases = reader.nextInt();
        while (testCases-- > 0) {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] grid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            if (solveMaze(grid, rows, cols)) {
                out.println("Yes");
            } else {
                out.println("No");
            }
        }
        out.flush();
        out.close();
    }

    /**
     * Coordinates in the grid.
     */
    private static class Point {
        final int r, c;
        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Orchestrates the maze solving logic.
     */
    private static boolean solveMaze(char[][] grid, int rows, int cols) {
        // Phase 1: Process bombs
        // Bombs transform adjacent '.' into '#' and invalidate if adjacent to 'G'
        if (!applyBombEffects(grid, rows, cols)) {
            return false;
        }

        // Phase 2: BFS to find all reachable cells starting from the bottom-right
        boolean[][] visited = performBFS(grid, rows, cols);

        // Phase 3: Verify if all goals 'G' are reachable
        return allGoalsVisited(grid, visited, rows, cols);
    }

    /**
     * Iterates through the grid and applies effects of bomb cells.
     * Returns false if a bomb is adjacent to a goal.
     */
    private static boolean applyBombEffects(char[][] grid, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 'B') {
                    for (int[] dir : DIRECTIONS) {
                        int nr = i + dir[0];
                        int nc = j + dir[1];

                        if (isWithinBounds(nr, nc, rows, cols)) {
                            if (grid[nr][nc] == 'G') {
                                return false; // Bomb hits a goal
                            }
                            if (grid[nr][nc] == '.') {
                                grid[nr][nc] = '#'; // Bomb blocks a path
                            }
                        }
                    }
                }
            }
        }
        return true;
    }

    /**
     * Performs BFS starting from the bottom-right corner (N-1, M-1).
     * Returns a 2D boolean array of visited cells.
     */
    private static boolean[][] performBFS(char[][] grid, int rows, int cols) {
        boolean[][] visited = new boolean[rows][cols];
        Queue<Point> queue = new LinkedList<>();

        int startR = rows - 1;
        int startC = cols - 1;

        if (grid[startR][startC] != '#') {
            visited[startR][startC] = true;
            queue.add(new Point(startR, startC));
        }

        while (!queue.isEmpty()) {
            Point curr = queue.poll();

            for (int[] dir : DIRECTIONS) {
                int nr = curr.r + dir[0];
                int nc = curr.c + dir[1];

                if (isWithinBounds(nr, nc, rows, cols) 
                    && grid[nr][nc] != '#' 
                    && !visited[nr][nc]) {

                    visited[nr][nc] = true;
                    queue.add(new Point(nr, nc));
                }
            }
        }
        return visited;
    }

    /**
     * Checks if all 'G' cells in the grid were marked as visited.
     */
    private static boolean allGoalsVisited(char[][] grid, boolean[][] visited, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 'G' && !visited[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    private static boolean isWithinBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Utility class for fast input reading.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

