class GridSolver {
    // Cell constants
    private static final char GOAL = 'G';
    private static final char BARRIER = 'B';
    private static final char WALL = '#';
    private static final char EMPTY = '.';

    // Direction vectors for 4-way movement (Right, Left, Down, Up)
    private static final int[] DR = {0, 0, 1, -1};
    private static final int[] DC = {1, -1, 0, 0};

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final boolean[][] visited;

    private int totalGoalsInGrid = 0;
    private int goalsReached = 0;
    private boolean isPathPossible = true;

    public GridSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.visited = new boolean[rows][cols];
    }

    /**
     * Orchestrates the solution process.
     * @return true if all goals are reached under the problem constraints.
     */
    public boolean solve() {
        preprocessGrid();

        // Start DFS from the bottom-right corner (n-1, m-1)
        int startRow = rows - 1;
        int startCol = cols - 1;

        // If the starting point is valid, begin traversal
        if (isWithinBounds(startRow, startCol)) {
            dfs(startRow, startCol);
        }

        // Final constraint: if goals exist, the starting cell must not be adjacent to a barrier
        if (totalGoalsInGrid > 0 && isAdjacentTo(startRow, startCol, BARRIER)) {
            isPathPossible = false;
        }

        return isPathPossible && (goalsReached == totalGoalsInGrid);
    }

    /**
     * Counts total goals and converts empty cells adjacent to barriers into walls.
     */
    private void preprocessGrid() {
        // Count total goals
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == GOAL) {
                    totalGoalsInGrid++;
                }
            }
        }

        // Apply barrier rule: empty cells adjacent to 'B' become walls '#'
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == BARRIER) {
                    for (int i = 0; i < 4; i++) {
                        int nr = r + DR[i];
                        int nc = c + DC[i];
                        if (isWithinBounds(nr, nc) && grid[nr][nc] == EMPTY) {
                            grid[nr][nc] = WALL;
                        }
                    }
                }
            }
        }
    }

    /**
     * Depth First Search to explore reachable cells.
     */
    private void dfs(int r, int c) {
        if (!isPathPossible) {
            return;
        }

        visited[r][c] = true;

        // Handle goal cell logic
        if (grid[r][c] == GOAL) {
            goalsReached++;
            // If a goal is adjacent to a barrier, the whole path is invalid
            if (isAdjacentTo(r, c, BARRIER)) {
                isPathPossible = false;
                return;
            }
        }

        // Explore adjacent cells
        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];

            if (isWithinBounds(nr, nc) 
                    && !visited[nr][nc] 
                    && grid[nr][nc] != BARRIER 
                    && grid[nr][nc] != WALL) {
                dfs(nr, nc);
            }
        }
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private boolean isAdjacentTo(int r, int c, char target) {
        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];
            if (isWithinBounds(nr, nc) && grid[nr][nc] == target) {
                return true;
            }
        }
        return false;
    }
}

import java.util.Scanner;

/**
 * MazeSolver encapsulates the logic for traversing a grid to find reachable goals.
 * It follows specific rules regarding obstacles ('#') and blockers ('B').
 */
class MazeSolver {
    // Direction vectors for moving: Right, Down, Left, Up
    private static final int[] ROW_OFFSETS = {0, 1, 0, -1};
    private static final int[] COL_OFFSETS = {1, 0, -1, 0};

    private final String[] grid;
    private final int rows;
    private final int cols;
    private final boolean[][] visited;
    private int reachableGoalsCount;

    public MazeSolver(String[] grid, int rows, int cols) {
        this.grid = grid;
        this.rows = rows;
        this.cols = cols;
        this.visited = new boolean[rows][cols];
        this.reachableGoalsCount = 0;
    }

    /**
     * Starts the depth-first search from the bottom-right corner.
     * 
     * @return The number of 'G' (goal) cells reachable from the starting point.
     */
    public int countReachableGoals() {
        // The problem specifies starting traversal from the bottom-right corner (n-1, m-1)
        performDFS(rows - 1, cols - 1);
        return reachableGoalsCount;
    }

    /**
     * Core DFS logic implementing the grid traversal rules.
     */
    private void performDFS(int r, int c) {
        // 1. Check if the current cell is within bounds, not visited, and not a hard obstacle '#'
        if (!isTraversable(r, c)) {
            return;
        }

        // 2. Mark the current cell as visited to prevent infinite recursion
        visited[r][c] = true;

        // 3. Rule: If any adjacent cell is a blocker 'B', this specific path is terminated immediately.
        // Note: This preserves the original logic where 'B' prevents further traversal from the current cell.
        if (isAdjacentToBlocker(r, c)) {
            return;
        }

        // 4. If the current cell is a goal 'G', increment our reachable count
        if (grid[r].charAt(c) == 'G') {
            reachableGoalsCount++;
        }

        // 5. Recursively visit all four adjacent neighbors
        for (int i = 0; i < 4; i++) {
            performDFS(r + ROW_OFFSETS[i], c + COL_OFFSETS[i]);
        }
    }

    /**
     * Determines if a cell is a valid candidate for traversal.
     */
    private boolean isTraversable(int r, int c) {
        return r >= 0 && r < rows && 
               c >= 0 && c < cols && 
               !visited[r][c] && 
               grid[r].charAt(c) != '#';
    }

    /**
     * Checks if any valid neighboring cell is a blocker ('B').
     */
    private boolean isAdjacentToBlocker(int r, int c) {
        for (int i = 0; i < 4; i++) {
            int neighborRow = r + ROW_OFFSETS[i];
            int neighborCol = c + COL_OFFSETS[i];

            // Check bounds before looking at the neighbor's value
            if (neighborRow >= 0 && neighborRow < rows && 
                neighborCol >= 0 && neighborCol < cols) {
                if (grid[neighborRow].charAt(neighborCol) == 'B') {
                    return true;
                }
            }
        }
        return false;
    }
}

