import java.util.*;

/**
 * Represents the different types of cells in the underground system.
 */
enum CellType {
    EMPTY('.'),
    BAD('B'),
    GOAL('G'),
    WALL('#');

    private final char symbol;

    CellType(char symbol) {
        this.symbol = symbol;
    }

    public static CellType fromChar(char c) {
        for (CellType type : values()) {
            if (type.symbol == c) return type;
        }
        throw new IllegalArgumentException("Unknown cell type: " + c);
    }
}

/**
 * A simple data carrier for grid coordinates.
 */
record Point(int row, int col) {}

/**
 * Solves the Underground System puzzle logic.
 */
class GridSolver {
    private static final int[][] DIRECTIONS = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

    private final int rows;
    private final int cols;
    private final CellType[][] grid;

    public GridSolver(int rows, int cols, char[][] inputGrid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = new CellType[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                this.grid[r][c] = CellType.fromChar(inputGrid[r][c]);
            }
        }
    }

    /**
     * Orchestrates the logic to determine if the grid configuration is valid.
     * @return true if the system is valid, false otherwise.
     */
    public boolean solve() {
        if (!prepareGrid()) {
            return false;
        }

        Set<Point> reachable = findReachableCells(new Point(rows - 1, cols - 1));
        return validateConstraints(reachable);
    }

    /**
     * Processes 'Bad' cells: 
     * 1. If a 'Bad' cell is adjacent to a 'Goal', the system is invalid.
     * 2. 'Bad' cells turn adjacent 'Empty' cells into 'Walls'.
     */
    private boolean prepareGrid() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == CellType.BAD) {
                    if (!applyBadCellEffects(r, c)) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    private boolean applyBadCellEffects(int r, int c) {
        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            if (isWithinBounds(nr, nc)) {
                if (grid[nr][nc] == CellType.GOAL) {
                    return false; // Invalid: Bad cell next to Goal
                }
                if (grid[nr][nc] == CellType.EMPTY) {
                    grid[nr][nc] = CellType.WALL;
                }
            }
        }
        return true;
    }

    /**
     * Performs a BFS to find all cells reachable from the starting point.
     */
    private Set<Point> findReachableCells(Point start) {
        Set<Point> reachable = new HashSet<>();
        if (!isWithinBounds(start.row(), start.col()) || grid[start.row()][start.col()] == CellType.WALL) {
            return reachable;
        }

        Queue<Point> queue = new LinkedList<>();
        queue.add(start);
        reachable.add(start);

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            for (int[] dir : DIRECTIONS) {
                int nr = current.row() + dir[0];
                int nc = current.col() + dir[1];
                Point neighbor = new Point(nr, nc);

                if (isWithinBounds(nr, nc) 
                        && !reachable.contains(neighbor) 
                        && grid[nr][nc] != CellType.WALL) {
                    reachable.add(neighbor);
                    queue.add(neighbor);
                }
            }
        }
        return reachable;
    }

    /**
     * Ensures all 'Goal' cells are reachable and no 'Bad' cells are reachable.
     */
    private boolean validateConstraints(Set<Point> reachable) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                Point current = new Point(r, c);
                if (grid[r][c] == CellType.GOAL && !reachable.contains(current)) {
                    return false;
                }
                if (grid[r][c] == CellType.BAD && reachable.contains(current)) {
                    return false;
                }
            }
        }
        return true;
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

