/**
 * Handles the logic for solving the maze based on the specific cell rules.
 */
class MazeSolver {
    private final char[][] grid;
    private final int rows;
    private final int cols;

    // Directional offsets for moving Up, Down, Left, and Right
    private static final int[][] DIRECTIONS = {
        {1, 0},  // Down
        {-1, 0}, // Up
        {0, 1},  // Right
        {0, -1}  // Left
    };

    public MazeSolver(char[][] grid, int rows, int cols) {
        this.grid = grid;
        this.rows = rows;
        this.cols = cols;
    }

    /**
     * Executes the full solving process.
     * @return true if the conditions are met, false otherwise.
     */
    public boolean solve() {
        applyBlackCellEffects();
        boolean[][] visited = performBFS();
        return validateResult(visited);
    }

    /**
     * Converts adjacent empty spaces ('.') into walls ('#') if they are next to a 'B' cell.
     */
    private void applyBlackCellEffects() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 'B') {
                    for (int[] dir : DIRECTIONS) {
                        int nr = r + dir[0];
                        int nc = c + dir[1];
                        if (isValidCoordinate(nr, nc) && grid[nr][nc] == '.') {
                            grid[nr][nc] = '#';
                        }
                    }
                }
            }
        }
    }

    /**
     * Performs a Breadth-First Search starting from the bottom-right corner.
     * @return A 2D boolean array indicating which cells were reachable.
     */
    private boolean[][] performBFS() {
        boolean[][] visited = new boolean[rows][cols];
        Queue<Point> queue = new LinkedList<>();

        // The original logic specifies BFS only starts if the exit cell is an empty space '.'
        int startR = rows - 1;
        int startC = cols - 1;

        if (isValidCoordinate(startR, startC) && grid[startR][startC] == '.') {
            visited[startR][startC] = true;
            queue.add(new Point(startR, startC));
        }

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            for (int[] dir : DIRECTIONS) {
                int nr = current.row + dir[0];
                int nc = current.col + dir[1];

                if (isValidCoordinate(nr, nc) && !visited[nr][nc] && grid[nr][nc] != '#') {
                    visited[nr][nc] = true;
                    queue.add(new Point(nr, nc));
                }
            }
        }
        return visited;
    }

    /**
     * Validates if the reachability map satisfies the problem constraints.
     * Constraints: No 'B' cells should be visited, and all 'G' cells must be visited.
     */
    private boolean validateResult(boolean[][] visited) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                // If a Black cell is visited, the path is invalid
                if (grid[r][c] == 'B' && visited[r][c]) {
                    return false;
                }
                // If a Green cell is NOT visited, the path is invalid
                if (grid[r][c] == 'G' && !visited[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    private boolean isValidCoordinate(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Represents a coordinate in the grid.
     */
    private static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }
}

