/**
 * NeighborGrid validates if a given grid adheres to spatial constraints:
 * - Corners (intersection of boundaries) have a maximum value of 2.
 * - Edges (boundaries excluding corners) have a maximum value of 3.
 * - Interior cells have a maximum value of 4.
 * 
 * If valid, it prints the maximum possible value for every cell in the grid.
 */
public class NeighborGrid {

    // Constants to replace magic numbers
    private static final int CORNER_LIMIT = 2;
    private static final int EDGE_LIMIT = 3;
    private static final int INTERIOR_LIMIT = 4;

    public static void main(String[] args) {
        FastReader input = new FastReader();
        PrintWriter output = new PrintWriter(System.out);

        int testCases = input.nextInt();
        for (int i = 0; i < testCases; i++) {
            processTestCase(input, output);
        }

        output.flush();
        output.close();
    }

    /**
     * Handles the logic for a single test case.
     */
    private static void processTestCase(FastReader input, PrintWriter output) {
        int rows = input.nextInt();
        int cols = input.nextInt();
        int[][] grid = new int[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                grid[r][c] = input.nextInt();
            }
        }

        if (isGridValid(grid, rows, cols)) {
            output.println("YES");
            printMaxPossibleGrid(rows, cols, output);
        } else {
            output.println("NO");
        }
    }

    /**
     * Checks if every cell in the grid is within its allowed limit.
     */
    private static boolean isGridValid(int[][] grid, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] > getMaxAllowedValue(r, c, rows, cols)) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Prints the grid filled with the maximum allowed values for each position.
     */
    private static void printMaxPossibleGrid(int rows, int cols, PrintWriter output) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                output.print(getMaxAllowedValue(r, c, rows, cols) + " ");
            }
            output.println();
        }
    }

    /**
     * Logic to determine the maximum value allowed at a specific coordinate.
     * 
     * @param r Current row
     * @param c Current column
     * @param rows Total rows
     * @param cols Total columns
     * @return The maximum allowed value (2, 3, or 4)
     */
    private static int getMaxAllowedValue(int r, int c, int rows, int cols) {
        boolean isRowBoundary = (r == 0 || r == rows - 1);
        boolean isColBoundary = (c == 0 || c == cols - 1);

        if (isRowBoundary && isColBoundary) {
            return CORNER_LIMIT;
        } else if (isRowBoundary || isColBoundary) {
            return EDGE_LIMIT;
        } else {
            return INTERIOR_LIMIT;
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }
}

