/**
 * A refactored solution for the matrix construction problem.
 * The goal is to validate if a provided matrix can be transformed into a pattern
 * where corners are 2, borders are 3, and the interior is 4.
 */
public class MatrixProblemSolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        int testCases = reader.nextInt();
        MatrixProblemSolver solver = new MatrixProblemSolver();

        while (testCases-- > 0) {
            solver.solve(reader, writer);
        }

        writer.flush();
        writer.close();
    }

    /**
     * Handles the logic for a single test case.
     */
    public void solve(FastReader reader, PrintWriter writer) {
        int rows = reader.nextInt();
        int cols = reader.nextInt();
        int[][] inputMatrix = new int[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                inputMatrix[i][j] = reader.nextInt();
            }
        }

        if (!isValid(inputMatrix, rows, cols)) {
            writer.println("NO");
        } else {
            writer.println("YES");
            printConstructedMatrix(rows, cols, writer);
        }
    }

    /**
     * Validates the input matrix based on the problem constraints:
     * 1. No element should be greater than 4.
     * 2. Corners cannot have a value greater than 2.
     * 3. Border elements cannot be 4.
     */
    private boolean isValid(int[][] matrix, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int val = matrix[i][j];

                // Only validate positive values as per original logic
                if (val <= 0) continue;

                if (val > 4) return false;

                if (isCorner(i, j, rows, cols) && val > 2) {
                    return false;
                }

                if (isBorder(i, j, rows, cols) && val == 4) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Prints the target matrix pattern:
     * Corners: 2, Borders: 3, Interior: 4.
     */
    private void printConstructedMatrix(int rows, int cols, PrintWriter writer) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int value;
                if (isCorner(i, j, rows, cols)) {
                    value = 2;
                } else if (isBorder(i, j, rows, cols)) {
                    value = 3;
                } else {
                    value = 4;
                }
                writer.print(value + (j == cols - 1 ? "" : " "));
            }
            writer.println();
        }
    }

    private boolean isCorner(int r, int c, int rows, int cols) {
        return (r == 0 || r == rows - 1) && (c == 0 || c == cols - 1);
    }

    private boolean isBorder(int r, int c, int rows, int cols) {
        return r == 0 || r == rows - 1 || c == 0 || c == cols - 1;
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

