        }
    }

    /**
     * Orchestrates the reading, processing, and output for a single test case.
     */
    private static void processTestCase(Scanner scanner) {
        if (!scanner.hasNextInt()) return;
        int rows = scanner.nextInt();
        if (!scanner.hasNextInt()) return;
        int columns = scanner.nextInt();

        int[][] matrix = new int[rows][columns];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < columns; j++) {
                if (scanner.hasNextInt()) {
                    matrix[i][j] = scanner.nextInt();
                }
            }
        }

        MatrixResult result = validateAndTransform(matrix, rows, columns);

        if (result.isSuccess()) {
            System.out.println("YES");
            printMatrix(result.getMatrix());
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Validates the matrix against boundary rules and returns a transformed version.
     * 
     * @param matrix The original input matrix.
     * @param rows Number of rows.
     * @param cols Number of columns.
     * @return A MatrixResult containing the success status and the transformed matrix.
     */
    private static MatrixResult validateAndTransform(int[][] matrix, int rows, int cols) {
        int[][] transformed = new int[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int limit = getLimitForCell(i, j, rows, cols);

                if (matrix[i][j] > limit) {
                    return MatrixResult.failure();
                }
                // According to original logic, we replace the value with the limit
                transformed[i][j] = limit;
            }
        }
        return MatrixResult.success(transformed);
    }

    /**
     * Determines the maximum allowed value for a cell based on its position.
     */
    private static int getLimitForCell(int r, int c, int rows, int cols) {
        boolean isRowEdge = (r == 0 || r == rows - 1);
        boolean isColEdge = (c == 0 || c == cols - 1);

        if (isRowEdge && isColEdge) {
            return CORNER_LIMIT;
        } else if (isRowEdge || isColEdge) {
            return EDGE_LIMIT;
        } else {
            return INTERIOR_LIMIT;
        }
    }

    /**
     * Efficiently prints the matrix to standard output.
     */
    private static void printMatrix(int[][] matrix) {
        StringBuilder sb = new StringBuilder();
        for (int[] row : matrix) {
            for (int val : row) {
                sb.append(val).append(" ");
            }
            sb.append("\n");
        }
        System.out.print(sb.toString());
    }

    /**
     * Data carrier class to represent the outcome of the validation process.
     */
    private static class MatrixResult {
        private final boolean success;
        private final int[][] matrix;

        private MatrixResult(boolean success, int[][] matrix) {
            this.success = success;
            this.matrix = matrix;
        }

        public static MatrixResult success(int[][] matrix) {
            return new MatrixResult(true, matrix);
        }

        public static MatrixResult failure() {
            return new MatrixResult(false, null);
        }

        public boolean isSuccess() {
            return success;
        }

        public int[][] getMatrix() {
            return matrix;
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A solution to determine if a given grid adheres to a specific pattern:
 * - Corners must be <= 2
 * - Edges must be <= 3
 * - Interior cells must be <= 4
 * 
 * If the pattern is valid, the program outputs "YES" and the required pattern grid.
 * Otherwise, it outputs "NO".
 */
public class GridPatternSolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int testCaseCount = reader.nextInt();
            for (int t = 0; t < testCaseCount; t++) {
                solve(reader, writer);
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Processes a single test case.
     */
    private static void solve(FastReader reader, PrintWriter writer) {
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        int[][] inputGrid = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                inputGrid[i][j] = reader.nextInt();
            }
        }

        int[][] targetGrid = generateTargetGrid(rows, cols);

        if (isGridValid(inputGrid, targetGrid)) {
            writer.println("YES");
            printGrid(targetGrid, writer);
        } else {
            writer.println("NO");
        }
    }

    /**
     * Generates the required pattern grid based on position.
     */
    private static int[][] generateTargetGrid(int rows, int cols) {
        int[][] target = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (isCorner(i, j, rows, cols)) {
                    target[i][j] = 2;
                } else if (isEdge(i, j, rows, cols)) {
                    target[i][j] = 3;
                } else {
                    target[i][j] = 4;
                }
            }
        }
        return target;
    }

    private static boolean isCorner(int r, int c, int rows, int cols) {
        return (r == 0 || r == rows - 1) && (c == 0 || c == cols - 1);
    }

    private static boolean isEdge(int r, int c, int rows, int cols) {
        return r == 0 || r == rows - 1 || c == 0 || c == cols - 1;
    }

    /**
     * Checks if every cell in the input grid is less than or equal to the target pattern.
     */
    private static boolean isGridValid(int[][] input, int[][] target) {
        for (int i = 0; i < input.length; i++) {
            for (int j = 0; j < input[0].length; j++) {
                if (input[i][j] > target[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Prints the grid to the provided PrintWriter.
     */
    private static void printGrid(int[][] grid, PrintWriter writer) {
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                writer.print(grid[i][j]);
                if (j < grid[i].length - 1) {
                    writer.print(" ");
                }
            }
            writer.println();
        }
    }

    /**
     * Fast I/O utility class for efficient reading of large inputs.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }
    }
}

