/**
 * A utility to validate if a grid of integers satisfies the constraint that 
 * each cell's value does not exceed its number of adjacent neighbors.
 */
public class GridNeighborValidator {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int testCaseCount = scanner.nextInt();

            while (testCaseCount-- > 0) {
                processTestCase(scanner, writer);
            }
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Handles the logic for a single test case.
     */
    private static void processTestCase(FastScanner scanner, PrintWriter writer) throws IOException {
        int rowCount = scanner.nextInt();
        int colCount = scanner.nextInt();
        int[][] inputGrid = new int[rowCount][colCount];
        boolean isGridValid = true;

        // Read the grid and check constraints
        for (int i = 0; i < rowCount; i++) {
            for (int j = 0; j < colCount; j++) {
                inputGrid[i][j] = scanner.nextInt();

                int maxAllowedNeighbors = calculateMaxNeighbors(i, j, rowCount, colCount);
                if (inputGrid[i][j] > maxAllowedNeighbors) {
                    isGridValid = false;
                }
            }
        }

        if (!isGridValid) {
            writer.println("NO");
        } else {
            writer.println("YES");
            printMaxNeighborGrid(rowCount, colCount, writer);
        }
    }

    /**
     * Calculates the maximum possible neighbors for a cell at (row, col).
     * A cell can have up to 4 neighbors, minus constraints from being on the edge.
     */
    private static int calculateMaxNeighbors(int row, int col, int totalRows, int totalCols) {
        int neighbors = 4;
        if (row == 0 || row == totalRows - 1) {
            neighbors--;
        }
        if (col == 0 || col == totalCols - 1) {
            neighbors--;
        }
        return neighbors;
    }

    /**
     * Prints the grid representing the maximum possible neighbors for each cell.
     */
    private static void printMaxNeighborGrid(int rows, int cols, PrintWriter writer) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                writer.print(calculateMaxNeighbors(i, j, rows, cols) + (j == cols - 1 ? "" : " "));
            }
            writer.println();
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(java.io.InputStream inputStream) {
            this.reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        public double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * Problem Solver for Grid Neighbor Validation.
 * The goal is to verify if every cell in a grid contains a value less than or equal 
 * to the number of its adjacent neighbors. If valid, the grid is transformed 
 * such that each cell value becomes its neighbor count.
 */
public class GridProblemSolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int testCases = reader.nextInt();
            GridProblemSolver solver = new GridProblemSolver();

            while (testCases-- > 0) {
                solver.processTestCase(reader, writer);
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Handles the lifecycle of a single test case.
     */
    private void processTestCase(FastReader reader, PrintWriter writer) throws IOException {
        int rowCount = reader.nextInt();
        int colCount = reader.nextInt();
        int[][] grid = new int[rowCount][colCount];

        for (int i = 0; i < rowCount; i++) {
            for (int j = 0; j < colCount; j++) {
                grid[i][j] = reader.nextInt();
            }
        }

        if (validateAndTransformGrid(grid, rowCount, colCount)) {
            writer.println("YES");
            printGrid(grid, writer);
        } else {
            writer.println("NO");
        }
    }

    /**
     * Validates the grid constraints and transforms the grid values in-place.
     * 
     * @param grid The 2D array representing the grid.
     * @param rows Number of rows.
     * @param cols Number of columns.
     * @return true if all cells are valid, false otherwise.
     */
    private boolean validateAndTransformGrid(int[][] grid, int rows, int cols) {
        // Direction arrays for Up, Down, Left, Right movement
        int[] dx = {-1, 1, 0, 0};
        int[] dy = {0, 0, -1, 1};

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int neighborCount = countNeighbors(grid, i, j, rows, cols, dx, dy);

                if (grid[i][j] > neighborCount) {
                    return false;
                }

                // Transformation step: update cell to its neighbor count
                grid[i][j] = neighborCount;
            }
        }
        return true;
    }

    /**
     * Calculates the number of valid adjacent neighbors for a given cell.
     */
    private int countNeighbors(int[][] grid, int r, int c, int rows, int cols, int[] dx, int[] dy) {
        int count = 0;
        for (int i = 0; i < 4; i++) {
            int ni = r + dx[i];
            int nj = c + dy[i];

            if (ni >= 0 && ni < rows && nj >= 0 && nj < cols) {
                count++;
            }
        }
        return count;
    }

    /**
     * Helper to print the 2D grid.
     */
    private void printGrid(int[][] grid, PrintWriter writer) {
        for (int[] row : grid) {
            for (int j = 0; j < row.length; j++) {
                writer.print(row[j] + (j == row.length - 1 ? "" : " "));
            }
            writer.println();
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream inputStream) {
            br = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.util.Scanner;

/**
 * Solution class to handle the execution of the grid neighbor validation problem.
 */
public class Solution {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int testCases = scanner.nextInt();

        while (testCases-- > 0) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            int[][] matrix = new int[rows][cols];

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    matrix[i][j] = scanner.nextInt();
                }
            }

            processTestCase(matrix, rows, cols);
        }
        scanner.close();
    }

    /**
     * Orchestrates the processing and printing of a single test case.
     */
    private static void processTestCase(int[][] matrix, int rows, int cols) {
        GridProcessor processor = new GridProcessor(matrix, rows, cols);
        GridResult result = processor.calculateNeighborGrid();

        if (result.isPossible()) {
            System.out.println("YES");
            System.out.print(result.getFormattedGrid());
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Data carrier for the result of the grid processing.
     */
    private static class GridResult {
        private final boolean possible;
        private final String formattedGrid;

        public GridResult(boolean possible, String formattedGrid) {
            this.possible = possible;
            this.formattedGrid = formattedGrid;
        }

        public boolean isPossible() {
            return possible;
        }

        public String getFormattedGrid() {
            return formattedGrid;
        }
    }

    /**
     * Logic provider for grid validation and transformation.
     */
    private static class GridProcessor {
        private final int[][] matrix;
        private final int rows;
        private final int cols;

        public GridProcessor(int[][] matrix, int rows, int cols) {
            this.matrix = matrix;
            this.rows = rows;
            this.cols = cols;
        }

        /**
         * Validates if each cell value is <= its neighbor count.
         * If valid, returns a grid containing the neighbor counts for every cell.
         */
        public GridResult calculateNeighborGrid() {
            int[][] neighborGrid = new int[rows][cols];
            boolean isPossible = true;

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    int neighbors = countNeighbors(i, j);

                    if (matrix[i][j] > neighbors) {
                        isPossible = false;
                        break;
                    }
                    neighborGrid[i][j] = neighbors;
                }
                if (!isPossible) break;
            }

            return new GridResult(isPossible, formatGrid(neighborGrid));
        }

        /**
         * Calculates the number of adjacent cells (up, down, left, right).
         */
        private int countNeighbors(int r, int c) {
            int count = 0;
            if (r > 0) count++;             // Top
            if (r < rows - 1) count++;      // Bottom
            if (c > 0) count++;             // Left
            if (c < cols - 1) count++;      // Right
            return count;
        }

        /**
         * Converts the 2D array into a single formatted String for efficient output.
         */
        private String formatGrid(int[][] grid) {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    sb.append(grid[i][j]);
                    if (j < cols - 1) {
                        sb.append(" ");
                    }
                }
                sb.append("\n");
            }
            return sb.toString();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves the grid pattern problem where a target pattern must be 
 * satisfied by the input grid. 
 * 
 * The target pattern consists of:
 * - Corners: 2
 * - Edges: 3
 * - Interior: 4
 */
public class GridPatternSolver {

    private static final int CORNER_VALUE = 2;
    private static final int EDGE_VALUE = 3;
    private static final int INTERIOR_VALUE = 4;

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        int testCases = reader.nextInt();
        for (int t = 0; t < testCases; t++) {
            solve(reader, writer);
        }

        writer.flush();
        writer.close();
    }

    /**
     * Handles a single test case.
     */
    private static void solve(FastReader reader, PrintWriter writer) {
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        int[][] inputGrid = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                inputGrid[i][j] = reader.nextInt();
            }
        }

        int[][] targetPattern = generatePattern(rows, cols);

        if (isFeasible(inputGrid, targetPattern)) {
            writer.println("YES");
            printGrid(targetPattern, writer);
        } else {
            writer.println("NO");
        }
    }

    /**
     * Generates the required pattern grid based on row and column indices.
     */
    private static int[][] generatePattern(int rows, int cols) {
        int[][] pattern = new int[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                boolean isRowEdge = (i == 0 || i == rows - 1);
                boolean isColEdge = (j == 0 || j == cols - 1);

                if (isRowEdge && isColEdge) {
                    pattern[i][j] = CORNER_VALUE;
                } else if (isRowEdge || isColEdge) {
                    pattern[i][j] = EDGE_VALUE;
                } else {
                    pattern[i][j] = INTERIOR_VALUE;
                }
            }
        }
        return pattern;
    }

    /**
     * Checks if the input grid meets or exceeds the target pattern values.
     */
    private static boolean isFeasible(int[][] inputGrid, int[][] targetPattern) {
        for (int i = 0; i < inputGrid.length; i++) {
            for (int j = 0; j < inputGrid[0].length; j++) {
                if (inputGrid[i][j] < targetPattern[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Utility to print the 2D grid to the provided PrintWriter.
     */
    private static void printGrid(int[][] grid, PrintWriter writer) {
        for (int[] row : grid) {
            for (int cell : row) {
                writer.print(cell + " ");
            }
            writer.println();
        }
    }

    /**
     * Fast I/O class to handle large inputs efficiently.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
