import java.util.StringTokenizer;

/**
 * A solver for the Grid Neighbor Task.
 * The task involves validating if each cell's value is less than or equal to 
 * its number of adjacent neighbors, and if so, transforming the cell to that count.
 */
public class TaskB {

    public static void main(String[] args) {
        try (FastReader reader = new FastReader();
             PrintWriter writer = new PrintWriter(System.out)) {

            int testCases = reader.nextInt();
            while (testCases-- > 0) {
                solve(reader, writer);
            }

        } catch (IOException | NumberFormatException e) {
            System.err.println("Error processing input: " + e.getMessage());
        }
    }

    /**
     * Orchestrates the logic for a single test case.
     */
    private static void solve(FastReader reader, PrintWriter writer) throws IOException {
        int rowCount = reader.nextInt();
        int columnCount = reader.nextInt();
        int[][] grid = reader.readGrid(rowCount, columnCount);

        GridProcessor processor = new GridProcessor(grid, rowCount, columnCount);

        if (processor.isTransformable()) {
            writer.println("YES");
            processor.printGrid(writer);
        } else {
            writer.println("NO");
        }
    }

    /**
     * Handles the business logic for grid validation and transformation.
     */
    private static class GridProcessor {
        private final int[][] grid;
        private final int rows;
        private final int cols;

        public GridProcessor(int[][] grid, int rows, int cols) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
        }

        /**
         * Validates if all cells satisfy the condition and transforms them if possible.
         * @return true if the grid can be transformed, false otherwise.
         */
        public boolean isTransformable() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    int neighborCount = countAdjacentNeighbors(i, j);

                    if (grid[i][j] > neighborCount) {
                        return false;
                    }
                    // Transform the cell value to the neighbor count as per original logic
                    grid[i][j] = neighborCount;
                }
            }
            return true;
        }

        /**
         * Calculates the number of valid adjacent neighbors (Up, Down, Left, Right).
         */
        private int countAdjacentNeighbors(int r, int c) {
            int count = 0;
            if (r - 1 >= 0) count++; // Up
            if (r + 1 < rows) count++; // Down
            if (c - 1 >= 0) count++; // Left
            if (c + 1 < cols) count++; // Right
            return count;
        }

        /**
         * Prints the grid to the provided PrintWriter.
         */
        public void printGrid(PrintWriter writer) {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    writer.print(grid[i][j]);
                    if (j < cols - 1) {
                        writer.print(" ");
                    }
                }
                writer.println();
            }
        }
    }

    /**
     * Helper class for fast I/O operations.
     */
    private static class FastReader implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader() {
            this.reader = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public int[][] readGrid(int rows, int cols) throws IOException {
            int[][] grid = new int[rows][cols];
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = nextInt();
