import java.util.*;
import java.io.*;

/**
 * NeighborGrid solves the problem of determining if a grid of values
 * can be represented by the number of neighbors each cell has in a 2D grid.
 */
public class NeighborGrid {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int testCases = reader.nextInt();
            while (testCases-- > 0) {
                solve(reader, out);
            }
        } catch (Exception e) {
            // In a real-world scenario, use a logger
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Orchestrates the logic for a single test case.
     */
    private static void solve(FastReader reader, PrintWriter out) throws IOException {
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        int[][] inputGrid = reader.readGrid(rows, cols);
        int[][] neighborGrid = calculateNeighborGrid(rows, cols);

        if (isPossible(inputGrid, neighborGrid)) {
            out.println("YES");
            printGrid(neighborGrid, out);
        } else {
            out.println("NO");
        }
    }

    /**
     * Calculates the number of neighbors (up, down, left, right) for each cell.
     * 
     * @param rows Number of rows in the grid
     * @param cols Number of columns in the grid
     * @return A 2D array containing the neighbor counts
     */
    private static int[][] calculateNeighborGrid(int rows, int cols) {
        int[][] neighborGrid = new int[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int neighbors = 4;

                // Check boundaries to adjust neighbor count
                if (r == 0) neighbors--;             // Top boundary
                if (r == rows - 1) neighbors--;      // Bottom boundary
                if (c == 0) neighbors--;             // Left boundary
                if (c == cols - 1) neighbors--;      // Right boundary

                // Note: For a 1x1 grid, the logic above correctly results in 0 neighbors.
                // However, if rows=1, r==0 and r==rows-1 are both true, resulting in -2.
                // To maintain exact parity with the original logic:
                neighborGrid[r][c] = recalculateCorrectly(r, c, rows, cols);
            }
        }
        return neighborGrid;
    }

    /**
     * Refined neighbor calculation to precisely match the original boundary logic.
     */
    private static int recalculateCorrectly(int r, int c, int rows, int cols) {
        int count = 4;
        if (r - 1 < 0) count--;
        if (c - 1 < 0) count--;
        if (r + 1 >= rows) count--;
        if (c + 1 >= cols) count--;
        return count;
    }

    /**
     * Validates if the input grid values are all less than or equal to 
     * the available neighbors in the calculated grid.
     */
    private static boolean isPossible(int[][] inputGrid, int[][] neighborGrid) {
        for (int i = 0; i < inputGrid.length; i++) {
            for (int j = 0; j < inputGrid[0].length; j++) {
                if (inputGrid[i][j] > neighborGrid[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Prints the grid to the output stream efficiently.
     */
    private static void printGrid(int[][] grid, PrintWriter out) {
        StringBuilder sb = new StringBuilder();
        for (int[] row : grid) {
            sb.setLength(0);
            for (int cell : row) {
                sb.append(cell).append(" ");
            }
            out.println(sb.toString().trim());
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public int[][] readGrid(int rows, int cols) throws IOException {
            int[][] grid = new int[rows][cols];
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = nextInt();
                }
            }
            return grid;
        }
    }
}

