/**
 * A program to validate if an input matrix respects specific boundary constraints.
 * Constraints: Corners <= 2, Edges <= 3, Interior <= 4.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        String testCasesInput = reader.next();
        if (testCasesInput == null) {
            return;
        }

        int testCases = Integer.parseInt(testCasesInput);

        while (testCases-- > 0) {
            try {
                int rows = reader.nextInt();
                int cols = reader.nextInt();
                int[][] inputMatrix = new int[rows][cols];

                for (int i = 0; i < rows; i++) {
                    for (int j = 0; j < cols; j++) {
                        inputMatrix[i][j] = reader.nextInt();
                    }
                }

                MatrixSolver.solve(rows, cols, inputMatrix);
            } catch (Exception e) {
                // In a production environment, use a logger.
                // For competitive programming, we break or continue.
                break;
            }
        }
    }

    /**
     * FastReader provides efficient parsing of input streams using BufferedReader.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            this.reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }

    /**
     * MatrixSolver encapsulates the logic for calculating limits and validating matrices.
     */
    static class MatrixSolver {
        private static final int CORNER_LIMIT = 2;
        private static final int EDGE_LIMIT = 3;
        private static final int INTERIOR_LIMIT = 4;

        /**
         * Main entry point for solving a single test case.
         */
        public static void solve(int rows, int cols, int[][] inputMatrix) {
            int[][] limitMatrix = generateLimitMatrix(rows, cols);

            if (isValid(inputMatrix, limitMatrix, rows, cols)) {
                printOutput(true, limitMatrix, rows, cols);
            } else {
                printOutput(false, null, 0, 0);
            }
        }

        /**
         * Generates a matrix containing the maximum allowed values for each cell.
         */
        private static int[][] generateLimitMatrix(int rows, int cols) {
            int[][] matrix = new int[rows][cols];
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    matrix[r][c] = calculateLimit(r, c, rows, cols);
                }
            }
            return matrix;
        }

        /**
         * Determines the limit for a specific coordinate based on its position.
         */
        private static int calculateLimit(int r, int c, int rows, int cols) {
            boolean isRowEdge = (r == 0 || r == rows - 1);
            boolean isColEdge = (c == 0 || c == cols - 1);

            if (isRowEdge && isColEdge) {
                return CORNER_LIMIT;
            } else if (isRowEdge || isColEdge) {
                return EDGE_LIMIT;
            } else {
                return INTERIOR_LIMIT;
            }
        }

        /**
         * Checks if every cell in the input matrix is within the allowed limits.
         */
        private static boolean isValid(int[][] input, int[][] limits, int rows, int cols) {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (input[i][j] > limits[i][j]) {
                        return false;
                    }
                }
            }
            return true;
        }

        /**
         * Handles the formatted output for the problem.
         */
        private static void printOutput(boolean success, int[][] matrix, int rows, int cols) {
            if (!success) {
                System.out.println("NO");
            } else {
                System.out.println("YES");
                StringBuilder sb = new StringBuilder();
                for (int i = 0; i < rows; i++) {
                    for (int j = 0; j < cols; j++) {
                        sb.append(matrix[i][j]).append(" ");
                    }
                    sb.append("\n");
                }
                System.out.print(sb.toString());
            }
        }
    }
}

