            return Integer.parseInt(next());
        }
    }

    /**
     * Contains the logic to solve the grid constraint problem.
     */
    static class GridConstraintSolver {

        /**
         * Solves the problem for all test cases provided in the input.
         * 
         * @param in  The input reader.
         * @param out The output writer.
         */
        public void solve(FastReader in, PrintWriter out) {
            int testCases = in.nextInt();

            while (testCases-- > 0) {
                processTestCase(in, out);
            }
        }

        private void processTestCase(FastReader in, PrintWriter out) {
            int rows = in.nextInt();
            int cols = in.nextInt();

            int[][] neighborGrid = new int[rows][cols];
            boolean isInvalid = false;

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    int inputVal = in.nextInt();
                    int possibleNeighbors = calculateNeighborCount(i, j, rows, cols);

                    // If the input value exceeds the number of available neighbors, 
                    // the condition cannot be satisfied.
                    if (inputVal > possibleNeighbors) {
                        isInvalid = true;
                    }
                    neighborGrid[i][j] = possibleNeighbors;
                }
            }

            if (isInvalid) {
                out.println("NO");
            } else {
                out.println("YES");
                printGrid(neighborGrid, out);
            }
        }

        /**
         * Calculates the number of adjacent cells (up, down, left, right) for a given cell.
         */
        private int calculateNeighborCount(int r, int c, int maxR, int maxC) {
            int count = 0;
            if (r > 0) count++;             // Up
            if (r < maxR - 1) count++;      // Down
            if (c > 0) count++;             // Left
            if (c < maxC - 1) count++;      // Right
            return count;
        }

        /**
         * Helper method to print the 2D grid to the output stream.
         */
        private void printGrid(int[][] grid, PrintWriter out) {
            for (int[] row : grid) {
                for (int j = 0; j < row.length; j++) {
                    out.print(row[j]);
                    if (j < row.length - 1) {
                        out.print(" ");
                    }
                }
                out.println();
            }
        }
    }
}

