/**
 * GridProcessor handles the validation and transformation of a 2D grid based 
 * on the number of adjacent neighbors for each cell.
 */
public class Main {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int testCaseCount = scanner.nextInt();
            while (testCaseCount-- > 0) {
                processTestCase(scanner, writer);
            }
        } catch (Exception e) {
            // In a production environment, use a logger
            e.printStackTrace();
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Reads input for a single test case and directs the output.
     */
    private static void processTestCase(FastScanner scanner, PrintWriter writer) {
        int rowCount = scanner.nextInt();
        int colCount = scanner.nextInt();
        int[][] grid = scanner.readIntArray2D(rowCount, colCount);

        int[][] transformedGrid = new int[rowCount][colCount];
        boolean isValid = true;

        for (int r = 0; r < rowCount; r++) {
            for (int c = 0; c < colCount; c++) {
                int neighborCount = countNeighbors(r, c, rowCount, colCount);

                // If the cell value exceeds its possible neighbors, the configuration is invalid
                if (grid[r][c] > neighborCount) {
                    isValid = false;
                    break;
                }
                transformedGrid[r][c] = neighborCount;
            }
            if (!isValid) break;
        }

        if (isValid) {
            writer.println("YES");
            printGrid(transformedGrid, writer);
        } else {
            writer.println("NO");
        }
    }

    /**
     * Calculates the number of valid adjacent neighbors (Up, Down, Left, Right) 
     * for a cell at (row, col).
     */
    private static int countNeighbors(int row, int col, int rowCount, int colCount) {
        int count = 0;
        if (row > 0) count++;                 // Top
        if (row < rowCount - 1) count++;      // Bottom
        if (col > 0) count++;                 // Left
        if (col < colCount - 1) count++;      // Right
        return count;
    }

    /**
     * Prints the 2D array to the provided PrintWriter.
     */
    private static void printGrid(int[][] grid, PrintWriter writer) {
        for (int[] row : grid) {
            for (int j = 0; j < row.length; j++) {
                writer.print(row[j]);
                if (j < row.length - 1) {
                    writer.print(" ");
