/**
 * A solver for the Grid Neighbor Constraint problem.
 * The goal is to determine if every cell in a grid contains a value 
 * less than or equal to the number of its immediate neighbors (up, down, left, right).
 */
public class GridNeighborSolver {

    // Directions for 4-connectivity (Right, Up, Left, Down)
    private static final int[] ROW_DIRECTIONS = {0, -1, 0, 1};
    private static final int[] COL_DIRECTIONS = {1, 0, -1, 0};

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);
        GridNeighborSolver solver = new GridNeighborSolver();

        try {
            int testCases = reader.nextInt();
            for (int t = 1; t <= testCases; t++) {
                solver.solveTestCase(reader, writer);
            }
        } catch (Exception e) {
            // In a production environment, use a logger.
            e.printStackTrace();
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Orchestrates the logic for a single test case.
     */
    private void solveTestCase(FastReader reader, PrintWriter writer) {
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        int[][] inputGrid = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                inputGrid[i][j] = reader.nextInt();
            }
        }

        int[][] neighborCountGrid = calculateNeighborCounts(rows, cols);
        boolean isPossible = validateConstraints(inputGrid, neighborCountGrid, rows, cols);

        if (isPossible) {
            writer.println("YES");
            printGrid(neighborCountGrid, rows, cols, writer);
        } else {
            writer.println("NO");
        }
    }

    /**
     * Calculates the number of valid neighbors for every cell in a grid of given dimensions.
     */
    private int[][] calculateNeighborCounts(int rows, int cols) {
        int[][] neighborCounts = new int[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int count = 0;
                for (int d = 0; d < 4; d++) {
                    int neighborRow = r + ROW_DIRECTIONS[d];
                    int neighborCol = c + COL_DIRECTIONS[d];

                    if (isWithinBounds(neighborRow, neighborCol, rows, cols)) {
                        count++;
                    }
                }
                neighborCounts[r][c] = count;
            }
        }
        return neighborCounts;
    }

    /**
     * Validates if every cell in the input grid satisfies the condition: 
     * cellValue <= neighborCount.
     */
    private boolean validateConstraints(int[][] input, int[][] neighbors, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (input[r][c] > neighbors[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    private boolean isWithinBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private void printGrid(int[][] grid, int rows, int cols, PrintWriter writer) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                writer.print(grid[i][j]);
                if (j < cols - 1) {
                    writer.print(" ");
                }
            }
            writer.println();
        }
    }

    /**
     * Fast I/O utility class for efficient reading of large inputs.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }
    }
