/**
 * Handles the execution logic of the problem.
 */
class Solver {
    private final FastScanner scanner;
    private final PrintWriter writer;

    public Solver(InputStream inputStream, OutputStream outputStream) {
        this.scanner = new FastScanner(inputStream);
        this.writer = new PrintWriter(outputStream);
    }

    /**
     * Entry point for the solving process.
     */
    public void solve() {
        int testCaseCount = scanner.nextInt();
        while (testCaseCount-- > 0) {
            processTestCase();
        }
        writer.flush();
        writer.close();
    }

    /**
     * Orchestrates the logic for a single test case.
     */
    private void processTestCase() {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        int[][] originalGrid = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                originalGrid[i][j] = scanner.nextInt();
            }
        }

        int[][] neighborGrid = calculateNeighborCountGrid(rows, cols);

        if (isPossible(originalGrid, neighborGrid)) {
            writer.println("YES");
            printGrid(neighborGrid);
        } else {
            writer.println("NO");
        }
    }

    /**
     * Generates a grid representing the maximum possible neighbors for each cell.
     * 
     * @param rows Number of rows in the grid.
     * @param cols Number of columns in the grid.
     * @return A 2D array containing the neighbor counts.
     */
    private int[][] calculateNeighborCountGrid(int rows, int cols) {
        int[][] grid = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int neighbors = 4;
                // Deduct if on the top or bottom boundary
                if (i == 0 || i == rows - 1) {
                    neighbors--;
                }
                // Deduct if on the left or right boundary
                if (j == 0 || j == cols - 1) {
                    neighbors--;
                }
                grid[i][j] = neighbors;
            }
        }
        return grid;
    }

    /**
     * Verifies if the generated neighbor grid satisfies the condition 
     * that every cell value is >= the original input value.
     */
    private boolean isPossible(int[][] original, int[][] neighbors) {
        for (int i = 0; i < original.length; i++) {
            for (int j = 0; j < original[i].length; j++) {
                if (original[i][j] > neighbors[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Prints the grid to the output stream.
     */
    private void printGrid(int[][] grid) {
        for (int[] row : grid) {
            for (int cell : row) {
                writer.print(cell + " ");
            }
            writer.println();
        }
    }
}

