     * the grid is transformed and printed.
     *
     * @param grid The 2D array to process.
     * @param rows Total rows in the grid.
     * @param cols Total columns in the grid.
     */
    private static void processAndPrintGrid(int[][] grid, int rows, int cols) {
        boolean allCellsValid = true;

        // Iterate through the grid to check conditions and transform values
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int neighborCount = countOrthogonalNeighbors(i, j, rows, cols);

                // Condition: cell value must be <= number of valid neighbors
                if (grid[i][j] <= neighborCount) {
                    grid[i][j] = neighborCount;
                } else {
                    // If any cell fails the condition, the entire grid fails
                    allCellsValid = false;
                }
            }
        }

        if (allCellsValid) {
            printResult(grid, rows, cols);
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Calculates the number of valid orthogonal neighbors (Up, Down, Left, Right) 
     * for a given cell.
     *
     * @param row The current row index.
     * @param col The current column index.
     * @param totalRows Total rows in the grid.
     * @param totalCols Total columns in the grid.
     * @return The count of valid adjacent cells.
     */
    private static int countOrthogonalNeighbors(int row, int col, int totalRows, int totalCols) {
        int count = 0;

        if (row > 0) count++;               // Up
        if (row < totalRows - 1) count++;    // Down
        if (col > 0) count++;               // Left
        if (col < totalCols - 1) count++;    // Right

        return count;
    }

    /**
     * Prints the "YES" message and the transformed grid using a StringBuilder 
     * for optimized output performance.
     *
     * @param grid The transformed grid.
     * @param rows Total rows in the grid.
     * @param cols Total columns in the grid.
     */
    private static void printResult(int[][] grid, int rows, int cols) {
        System.out.println("YES");
        StringBuilder output = new StringBuilder();

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                output.append(grid[i][j]);
                if (j < cols - 1) {
                    output.append(" ");
                }
            }
            output.append("\n");
        }
        System.out.print(output.toString());
    }
}

