/**
 * Refactored program to process a grid based on neighbor counts.
 * The logic: If every cell's value is less than or equal to its number of 
 * adjacent neighbors, replace the cell's value with that neighbor count.
 * Otherwise, the grid is invalid.
 */
public class Main {

    public static void main(String[] args) {
        try (FastScanner scanner = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            String firstLine = scanner.next();
            if (firstLine == null) return;

            int testCases = Integer.parseInt(firstLine);

            for (int t = 0; t < testCases; t++) {
                int rows = scanner.nextInt();
                int cols = scanner.nextInt();

                int[][] grid = new int[rows][cols];
                for (int i = 0; i < rows; i++) {
                    for (int j = 0; j < cols; j++) {
                        grid[i][j] = scanner.nextInt();
                    }
                }

                GridProcessor.Result result = GridProcessor.process(grid);

                if (result.isSuccess()) {
                    out.println("YES");
                    printGrid(out, result.getProcessedGrid());
                } else {
                    out.println("NO");
                }
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * Prints the 2D array to the provided PrintWriter.
     */
    private static void printGrid(PrintWriter out, int[][] grid) {
        for (int[] row : grid) {
            for (int i = 0; i < row.length; i++) {
                out.print(row[i] + (i == row.length - 1 ? "" : " "));
            }
            out.println();
        }
    }

    /**
     * Contains the domain logic for grid processing.
     */
    static class GridProcessor {

        /**
         * Processes the grid. Returns a Result object containing success status 
         * and the transformed grid.
         */
        public static Result process(int[][] grid) {
            int rows = grid.length;
            int cols = grid[0].length;
            int[][] processedGrid = new int[rows][cols];

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    int neighbors = countAdjacentNeighbors(rows, cols, r, c);

                    if (grid[r][c] > neighbors) {
                        return Result.failure();
                    }
                    processedGrid[r][c] = neighbors;
                }
            }

            return Result.success(processedGrid);
        }

        /**
         * Calculates the number of valid 4-connectivity neighbors (Up, Down, Left, Right).
         */
        private static int countAdjacentNeighbors(int rows, int cols, int r, int c) {
            int count = 0;
            if (r > 0) count++;            // Up
            if (r < rows - 1) count++;     // Down
            if (c > 0) count++;            // Left
            if (c < cols - 1) count++;     // Right
            return count;
        }

        /**
         * Encapsulates the outcome of the GridProcessor logic.
         */
        static class Result {
            private final boolean success;
            private final int[][] processedGrid;

            private Result(boolean success, int[][] processedGrid) {
                this.success = success;
                this.processedGrid = processedGrid;
            }

            public static Result success(int[][] grid) {
                return new Result(true, grid);
            }

            public static Result failure() {
                return new Result(false, null);
            }

            public boolean isSuccess() {
                return success;
            }

            public int[][] getProcessedGrid() {
                return processedGrid;
            }
        }
    }

    /**
     * High-performance scanner for reading input efficiently.
     */
    static class FastScanner implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream input) {
            this.reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            if (next == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(next);
        }

        @Override
        public void close() throws IOException {
            reader.close();
        }
    }
}

import java.io.PrintWriter;
import java.util.Scanner;

/**
 * The Contest class processes grid-based challenges to determine if a 
 * provided input grid satisfies a specific boundary and interior value pattern.
 */
public class Contest {

    private static final int CORNER_VALUE = 2;
    private static final int EDGE_VALUE = 3;
    private static final int INTERIOR_VALUE = 4;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        if (sc.hasNextInt()) {
            int testCases = sc.nextInt();
            Contest contest = new Contest();

            while (testCases-- > 0) {
                contest.processTestCase(sc, out);
            }
        }

        out.flush();
        out.close();
        sc.close();
    }

    /**
     * Orchestrates the processing of a single test case.
     */
    private void processTestCase(Scanner sc, PrintWriter out) {
        int rows = sc.nextInt();
        int cols = sc.nextInt();
        int[][] inputGrid = new int[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                inputGrid[i][j] = sc.nextInt();
            }
        }

        int[][] targetGrid = generateTargetGrid(rows, cols);

        if (isPossible(inputGrid, targetGrid)) {
            out.println("YES");
            printGrid(targetGrid, out);
        } else {
            out.println("NO");
        }
    }

    /**
     * Generates the required pattern grid based on row and column counts.
     */
    private int[][] generateTargetGrid(int rows, int cols) {
        int[][] target = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                target[r][c] = calculateCellValue(r, c, rows, cols);
            }
        }
        return target;
    }

    /**
     * Determines the value for a specific cell based on its position:
     * Corner cells = 2, Edge cells = 3, Interior cells = 4.
     */
    private int calculateCellValue(int r, int c, int rows, int cols) {
        boolean isRowEdge = (r == 0 || r == rows - 1);
        boolean isColEdge = (c == 0 || c == cols - 1);

        if (isRowEdge && isColEdge) {
            return CORNER_VALUE;
        } else if (isRowEdge || isColEdge) {
            return EDGE_VALUE;
        } else {
            return INTERIOR_VALUE;
        }
    }

    /**
     * Checks if every cell in the input grid is less than or equal 
     * to the corresponding cell in the target grid.
     */
    private boolean isPossible(int[][] input, int[][] target) {
        for (int i = 0; i < input.length; i++) {
            for (int j = 0; j < input[i].length; j++) {
                if (input[i][j] > target[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Prints the grid to the output stream with space-separated values.
     */
    private void printGrid(int[][] grid, PrintWriter out) {
        for (int[] row : grid) {
            for (int j = 0; j < row.length; j++) {
                out.print(row[j]);
                if (j < row.length - 1) {
                    out.print(" ");
                }
            }
            out.println();
        }
    }
}

