/**
 * A program that validates if each cell in a grid contains a value 
 * less than or equal to its number of neighbors, and transforms 
 * the grid to show the neighbor counts.
 */
public class NeighborGridApp {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        GridProcessor processor = new GridProcessor();

        if (!scanner.hasNextInt()) return;

        int testCases = scanner.nextInt();

        while (testCases-- > 0) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            int[][] grid = readGrid(scanner, rows, cols);

            ValidationResult result = processor.validateAndTransform(grid);
            printResult(result);
        }

        scanner.close();
    }

    private static int[][] readGrid(Scanner scanner, int rows, int cols) {
        int[][] grid = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                grid[i][j] = scanner.nextInt();
            }
        }
        return grid;
    }

    private static void printResult(ValidationResult result) {
        if (result.isValid()) {
            System.out.println("YES");
            System.out.println(result.getTransformedGridAsString());
        } else {
            System.out.println("NO");
        }
    }
}

/**
 * Handles the business logic for grid validation and transformation.
 */
class GridProcessor {
    // Direction vectors for Up, Down, Left, Right neighbors
    private static final int[][] DIRECTIONS = {
        {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    /**
     * Validates the grid and returns a result containing the transformed grid.
     * 
     * @param inputGrid The original grid values.
     * @return A ValidationResult indicating success and containing the new grid.
     */
    public ValidationResult validateAndTransform(int[][] inputGrid) {
        int rows = inputGrid.length;
        int cols = inputGrid[0].length;
        int[][] transformedGrid = new int[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int possibleNeighbors = countPossibleNeighbors(r, c, rows, cols);

                if (inputGrid[r][c] > possibleNeighbors) {
                    return ValidationResult.failure();
                }

                // Transform the cell to the neighbor count as per original logic
                transformedGrid[r][c] = possibleNeighbors;
            }
        }

        return ValidationResult.success(transformedGrid);
    }

    private int countPossibleNeighbors(int row, int col, int rows, int cols) {
        int count = 0;
        for (int[] dir : DIRECTIONS) {
            int newRow = row + dir[0];
            int newCol = col + dir[1];

            if (isValidCoordinate(newRow, newCol, rows, cols)) {
                count++;
            }
        }
        return count;
    }

    private boolean isValidCoordinate(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

/**
 * Data Transfer Object (DTO) to hold the result of the grid validation.
 */
class ValidationResult {
    private final boolean valid;
    private final int[][] transformedGrid;

    private ValidationResult(boolean valid, int[][] transformedGrid) {
        this.valid = valid;
        this.transformedGrid = transformedGrid;
    }

    public static ValidationResult success(int[][] grid) {
        return new ValidationResult(true, grid);
    }

    public static ValidationResult failure() {
        return new ValidationResult(false, null);
    }

    public boolean isValid() {
        return valid;
    }

    /**
     * Formats the transformed grid into a string for output.
     */
    public String getTransformedGridAsString() {
        if (transformedGrid == null) return "";

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < transformedGrid.length; i++) {
            StringJoiner rowJoiner = new StringJoiner(" ");
            for (int j = 0; j < transformedGrid[i].length; j++) {
                rowJoiner.add(String.valueOf(transformedGrid[i][j]));
            }
            sb.append(rowJoiner.toString());
            if (i < transformedGrid.length - 1) {
                sb.append("\n");
            }
        }
        // The original code added a trailing space to every element. 
        // Here we use StringJoiner for cleaner output without trailing spaces, 
        // which is standard practice.
        return sb.toString();
    }
}

