/**
 * A program that validates if each cell in a grid contains a value 
 * less than or equal to its possible neighbor count, then transforms 
 * the grid to reflect the maximum possible neighbors for each cell.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            String testsInput = reader.next();
            if (testsInput != null) {
                int testCases = Integer.parseInt(testsInput);
                while (testCases-- > 0) {
                    processTestCase(reader, writer);
                }
