            // For competitive programming, we handle errors gracefully.
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Reads input for a single test case, validates the grid, and prints the result.
     */
    private static void processTestCase(FastReader reader, PrintWriter writer) throws IOException {
        int rows = reader.nextInt();
        int cols = reader.nextInt();
        int[][] grid = new int[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                grid[i][j] = reader.nextInt();
            }
        }

        if (isValidAndTransformGrid(grid, rows, cols)) {
            writer.println("YES");
            printGrid(grid, writer);
        } else {
            writer.println("NO");
        }
