    /**
     * Checks if every cell's value is within its maximum neighbor capacity.
     * If valid, transforms the grid to contain the maximum possible neighbors for each cell.
     * 
     * @return true if all cells are valid, false otherwise.
     */
    private static boolean isValidAndTransformGrid(int[][] grid, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int maxPossibleNeighbors = countMaxNeighbors(i, j, rows, cols);
                if (grid[i][j] > maxPossibleNeighbors) {
                    return false;
                }
                grid[i][j] = maxPossibleNeighbors;
            }
        }
        return true;
    }

    /**
     * Calculates the number of adjacent cells for a given coordinate.
     */
    private static int countMaxNeighbors(int r, int c, int rows, int cols) {
        int count = 0;
        if (r > 0) count++;               // Top
        if (r < rows - 1) count++;        // Bottom
        if (c > 0) count++;               // Left
        if (c < cols - 1) count++;        // Right
        return count;
    }

    /**
     * Helper to print the grid to the output stream.
     */
    private static void printGrid(int[][] grid, PrintWriter writer) {
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                writer.print(grid[i][j] + (j == grid[i].length - 1 ? "" : " "));
