import java.util.Scanner;

/**
 * A program that validates a grid based on specific boundary constraints 
 * and outputs a maximal valid grid if the input is valid.
 */
public class Main {

    // Constants defining the maximum allowed values for different cell types
    private static final int MAX_CORNER_VALUE = 2;
    private static final int MAX_EDGE_VALUE = 3;
    private static final int MAX_INTERIOR_VALUE = 4;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int testCases = scanner.nextInt();
        while (testCases-- > 0) {
            processTestCase(scanner);
        }

        scanner.close();
    }

    /**
     * Handles the lifecycle of a single test case.
     */
    private static void processTestCase(Scanner scanner) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        int[][] grid = new int[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                grid[i][j] = scanner.nextInt();
            }
        }

        if (isGridValid(grid, rows, cols)) {
            System.out.println("YES");
            printMaximalGrid(rows, cols);
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Validates if the provided grid adheres to the corner, edge, and interior constraints.
     */
    private static boolean isGridValid(int[][] grid, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (isCorner(i, j, rows, cols)) {
                    if (grid[i][j] > MAX_CORNER_VALUE) return false;
                } else if (isEdge(i, j, rows, cols)) {
                    if (grid[i][j] > MAX_EDGE_VALUE) return false;
                } else {
                    if (grid[i][j] > MAX_INTERIOR_VALUE) return false;
                }
            }
        }
        return true;
    }

    /**
     * Prints the maximal allowed values for a grid of given dimensions.
     */
    private static void printMaximalGrid(int rows, int cols) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (isCorner(i, j, rows, cols)) {
                    sb.append(MAX_CORNER_VALUE);
                } else if (isEdge(i, j, rows, cols)) {
                    sb.append(MAX_EDGE_VALUE);
                } else {
                    sb.append(MAX_INTERIOR_VALUE);
                }
                sb.append(" ");
            }
            sb.append("\n");
        }
        System.out.print(sb.toString());
    }

    /**
     * Logic to identify if a cell coordinate is a corner.
     */
    private static boolean isCorner(int r, int c, int rows, int cols) {
        return (r == 0 || r == rows - 1) && (c == 0 || c == cols - 1);
    }

    /**
     * Logic to identify if a cell coordinate is on the boundary (edge).
     */
    private static boolean isEdge(int r, int c, int rows, int cols) {
        return (r == 0 || r == rows - 1 || c == 0 || c == cols - 1);
    }
}

