    /**
     * Handles the logic for a single grid test case.
     */
    static class GridProblemSolver {

        /**
         * Solves the grid problem: checks if each cell value is less than or equal 
         * to the count of its adjacent neighbors.
         *
         * @param in   The input reader.
         * @param out  The output writer.
         */
        public void solve(FastReader in, PrintWriter out) {
            int rows = in.nextInt();
            int cols = in.nextInt();

            int[][] inputGrid = new int[rows][cols];
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    inputGrid[i][j] = in.nextInt();
                }
            }

            int[][] neighborCountGrid = new int[rows][cols];
            boolean isPossible = true;

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    int neighbors = countNeighbors(i, j, rows, cols);

                    // If any cell value exceeds its possible neighbors, the condition fails.
                    if (inputGrid[i][j] > neighbors) {
                        isPossible = false;
                    }
                    neighborCountGrid[i][j] = neighbors;
                }
            }

            if (isPossible) {
                out.println("YES");
                printGrid(out, neighborCountGrid);
            } else {
                out.println("NO");
            }
        }

        /**
         * Calculates the number of adjacent neighbors (Up, Down, Left, Right) for a cell.
         */
        private int countNeighbors(int r, int c, int maxR, int maxC) {
            int count = 0;
            if (r > 0) count++;             // Up
            if (r < maxR - 1) count++;      // Down
            if (c > 0) count++;             // Left
            if (c < maxC - 1) count++;      // Right
            return count;
        }

        /**
         * Helper to print the 2D grid to the output stream.
         */
        private void printGrid(PrintWriter out, int[][] grid) {
            for (int[] row : grid) {
                for (int j = 0; j < row.length; j++) {
                    out.print(row[j] + (j == row.length - 1 ? "" : " "));
                }
                out.println();
            }
        }
    }

