/**
 * A solution to determine if every cell in a grid can be updated to its 
 * number of valid neighbors, provided its current value is less than 
 * or equal to that count.
 */
public class GridNeighborSolver {

    public static void main(String[] args) {
        try {
            App runner = new App();
            runner.run();
        } catch (IOException e) {
            System.err.println("An error occurred while processing input: " + e.getMessage());
        }
    }

    /**
     * Orchestrates the execution of the program.
     */
    static class App {
        private final FastReader reader = new FastReader(System.in);
        private final PrintWriter writer = new PrintWriter(System.out);

        public void run() throws IOException {
            int testCases = reader.nextInt();
            while (testCases-- > 0) {
                solve();
            }
            writer.flush();
            writer.close();
        }

        private void solve() throws IOException {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            int[][] grid = new int[rows][cols];

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = reader.nextInt();
                }
            }

            GridLogic logic = new GridLogic(rows, cols);
            SolverResult result = logic.process(grid);

            if (result.isSuccess()) {
                writer.println("YES");
                printGrid(writer, result.getTransformedGrid());
            } else {
                writer.println("NO");
            }
        }

        private void printGrid(PrintWriter pw, int[][] grid) {
            for (int[] row : grid) {
                for (int j = 0; j < row.length; j++) {
                    pw.print(row[j] + (j == row.length - 1 ? "" : " "));
                }
                pw.println();
            }
        }
    }

    /**
     * Contains the core algorithmic logic.
     */
    static class GridLogic {
        private final int rows;
        private final int cols;

        private static final int[] DX = {0, 0, -1, 1};
        private static final int[] DY = {-1, 1, 0, 0};

        public GridLogic(int rows, int cols) {
            this.rows = rows;
            this.cols = cols;
        }

        public SolverResult process(int[][] grid) {
            int[][] transformedGrid = new int[rows][cols];

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    int neighborCount = countValidNeighbors(i, j);

                    if (grid[i][j] <= neighborCount) {
                        transformedGrid[i][j] = neighborCount;
                    } else {
                        // If any cell violates the constraint, the whole process fails
                        return SolverResult.failure();
                    }
                }
            }
            return SolverResult.success(transformedGrid);
        }

        private int countValidNeighbors(int x, int y) {
            int count = 0;
            for (int i = 0; i < 4; i++) {
                int nx = x + DX[i];
                int ny = y + DY[i];
                if (isInBounds(nx, ny)) {
                    count++;
                }
            }
            return count;
        }

        private boolean isInBounds(int x, int y) {
            return x >= 0 && x < rows && y >= 0 && y < cols;
        }
    }

    /**
     * Data carrier for the result of the grid processing.
     */
    static class SolverResult {
        private final boolean success;
        private final int[][] transformedGrid;

        private SolverResult(boolean success, int[][] grid) {
            this.success = success;
            this.transformedGrid = grid;
        }

        public static SolverResult success(int[][] grid) {
            return new SolverResult(true, grid);
        }

        public static SolverResult failure() {
            return new SolverResult(false, null);
        }

        public boolean isSuccess() {
            return success;
        }

        public int[][] getTransformedGrid() {
            return transformedGrid;
        }
    }

    /**
     * High-performance input reader.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

