/**
 * Handles the business logic for transforming the grid.
 */
class GridProcessor {

    /**
     * Processes the grid according to the rules:
     * - Corners must be <= 2, then set to 2.
     * - Edges (non-corner) must be <= 3, then set to 3.
     * - Interior cells must be <= 4, then set to 4.
     *
     * @param inputGrid The original 2D array.
     * @return A GridSolution containing success status and the modified grid.
     */
    public GridSolution processGrid(int[][] inputGrid) {
        int rows = inputGrid.length;
        int cols = inputGrid[0].length;
        int[][] resultGrid = new int[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int targetValue = getTargetValue(r, c, rows, cols);

                if (inputGrid[r][c] > targetValue) {
                    return GridSolution.failure();
                }
                resultGrid[r][c] = targetValue;
            }
        }

        return GridSolution.success(resultGrid);
    }

    private int getTargetValue(int r, int c, int rows, int cols) {
        boolean isCorner = (r == 0 || r == rows - 1) && (c == 0 || c == cols - 1);
        if (isCorner) {
            return 2;
        }

        boolean isEdge = (r == 0 || r == rows - 1 || c == 0 || c == cols - 1);
        if (isEdge) {
            return 3;
        }

        return 4; // Interior
    }
}

