/**
 * TaskSolver manages the execution of multiple test cases.
 */
class TaskSolver {
    // Constants defining the requirements for the matrix transformation
    private static final int BOUNDARY_ROW_EDGE_VALUE = 2;
    private static final int BOUNDARY_ROW_INNER_VALUE = 3;
    private static final int INTERIOR_ROW_EDGE_VALUE = 3;
    private static final int INTERIOR_ROW_INNER_VALUE = 4;

    /**
     * Orchestrates the reading of test cases and outputting results.
     */
    public void run(Scanner sc, PrintWriter out) {
        if (!sc.hasNextInt()) {
            return;
        }

        int testCases = sc.nextInt();
        while (testCases-- > 0) {
            solveTestCase(sc, out);
        }
    }

    /**
     * Processes a single test case: reads the matrix, attempts transformation, 
     * and prints the result.
     */
    private void solveTestCase(Scanner sc, PrintWriter out) {
        int rows = sc.nextInt();
        int cols = sc.nextInt();
        int[][] matrix = readMatrix(sc, rows, cols);

        if (tryTransformMatrix(matrix, rows, cols)) {
            out.println("YES");
            printMatrix(matrix, out);
        } else {
            out.println("NO");
        }
    }

    /**
     * Reads the matrix data from the scanner.
     */
    private int[][] readMatrix(Scanner sc, int rows, int cols) {
        int[][] matrix = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                matrix[i][j] = sc.nextInt();
            }
        }
        return matrix;
    }

    /**
     * Validates and transforms the matrix according to the required boundary rules.
     * 
     * @return true if the matrix satisfies the constraints and is transformed; 
     *         false otherwise.
     */
    private boolean tryTransformMatrix(int[][] matrix, int rows, int cols) {
        // 1. Process the top row
        if (!applyRowConstraints(matrix, 0, cols, BOUNDARY_ROW_EDGE_VALUE, BOUNDARY_ROW_INNER_VALUE)) {
            return false;
        }

        // 2. Process the bottom row (if it is distinct from the top row)
        if (rows > 1) {
            if (!applyRowConstraints(matrix, rows - 1, cols, BOUNDARY_ROW_EDGE_VALUE, BOUNDARY_ROW_INNER_VALUE)) {
                return false;
            }
        }

        // 3. Process all interior rows
        for (int i = 1; i < rows - 1; i++) {
            if (!applyRowConstraints(matrix, i, cols, INTERIOR_ROW_EDGE_VALUE, INTERIOR_ROW_INNER_VALUE)) {
                return false;
            }
        }

        return true;
    }

    /**
     * Applies transformation rules to a specific row.
     * 
     * @param matrix The 2D array to modify.
     * @param row The index of the row to process.
     * @param cols The number of columns in the matrix.
     * @param edgeVal The required value for the first and last column.
     * @param innerVal The required value for middle columns.
     * @return true if the row is valid and transformed; false if any cell exceeds the allowed value.
     */
    private boolean applyRowConstraints(int[][] matrix, int row, int cols, int edgeVal, int innerVal) {
        // Validate and update the first column
        if (matrix[row][0] > edgeVal) {
            return false;
        }
        matrix[row][0] = edgeVal;

        // Validate and update the last column
        if (matrix[row][cols - 1] > edgeVal) {
            return false;
        }
        matrix[row][cols - 1] = edgeVal;

        // Validate and update the interior columns
        for (int col = 1; col < cols - 1; col++) {
            if (matrix[row][col] > innerVal) {
                return false;
            }
            matrix[row][col] = innerVal;
        }

        return true;
    }

    /**
     * Prints the matrix to the provided PrintWriter.
     */
    private void printMatrix(int[][] matrix, PrintWriter out) {
        for (int[] row : matrix) {
            for (int j = 0; j < row.length; j++) {
                out.print(row[j]);
                if (j < row.length - 1) {
                    out.print(" ");
                }
            }
            out.println();
        }
    }
}

