class GridSolver {
    private final FastReader reader;

    public GridSolver(FastReader reader) {
        this.reader = reader;
    }

    /**
     * Processes a single test case.
     */
    public void solve(PrintWriter out) throws IOException {
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        int[][] grid = new int[rows][cols];
        int[][] neighborCounts = new int[rows][cols];
        boolean isValid = true;

        // Read grid and calculate neighbor counts
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                grid[i][j] = reader.nextInt();
                int count = getNeighborCount(i, j, rows, cols);
                neighborCounts[i][j] = count;

                // Check if the current cell value exceeds the number of its neighbors
                if (grid[i][j] > count) {
                    isValid = false;
                }
            }
        }

        if (!isValid) {
            out.println("NO");
        } else {
            out.println("YES");
            printGrid(neighborCounts, out);
        }
    }

    /**
     * Calculates the number of adjacent neighbors (up, down, left, right) for a cell.
     */
    private int getNeighborCount(int r, int c, int rows, int cols) {
        int count = 0;
        if (r > 0) count++;             // Up
        if (r < rows - 1) count++;      // Down
        if (c > 0) count++;             // Left
        if (c < cols - 1) count++;      // Right
        return count;
    }

    /**
     * Efficiently prints the 2D array using a StringBuilder.
     */
    private void printGrid(int[][] grid, PrintWriter out) {
        StringBuilder sb = new StringBuilder();
        for (int[] row : grid) {
            for (int j = 0; j < row.length; j++) {
                sb.append(row[j]);
                if (j < row.length - 1) {
                    sb.append(" ");
                }
            }
            sb.append("\n");
        }
        out.print(sb.toString());
    }
}

