import java.io.*;
import java.util.*;

/**
 * A program that validates and transforms a grid based on cell positions.
 * Corners must be <= 2, edges <= 3, and interior cells <= 4.
 */
public class GridValidator {

    private static final int CORNER_LIMIT = 2;
    private static final int EDGE_LIMIT = 3;
    private static final int INTERIOR_LIMIT = 4;

    public static void main(String[] args) {
        // Using a larger stack size via a thread to prevent StackOverflowError on deep recursions,
        // though not strictly necessary for this specific iterative logic.
        Thread thread = new Thread(null, () -> {
            try {
                solve();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }, "SolverThread", 1 << 27);
        thread.start();
    }

    private static void solve() throws IOException {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int testCases = reader.nextInt();

        while (testCases-- > 0) {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            int[][] grid = new int[rows][cols];
            boolean isValid = true;

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    int currentValue = reader.nextInt();
                    int limit = getLimit(i, j, rows, cols);

                    if (currentValue > limit) {
                        isValid = false;
                    }
                    // Transform cell to its maximum allowed value
                    grid[i][j] = limit;
                }
            }

            if (!isValid) {
                out.println("NO");
            } else {
                out.println("YES");
                printGrid(out, grid);
            }
        }
        out.flush();
        out.close();
    }

    /**
     * Determines the maximum allowed value for a cell based on its position.
     */
    private static int getLimit(int r, int c, int rows, int cols) {
        boolean isCorner = (r == 0 || r == rows - 1) && (c == 0 || c == cols - 1);
        if (isCorner) {
            return CORNER_LIMIT;
        }

        boolean isEdge = (r == 0 || r == rows - 1 || c == 0 || c == cols - 1);
        if (isEdge) {
            return EDGE_LIMIT;
        }

        return INTERIOR_LIMIT;
    }

    private static void printGrid(PrintWriter out, int[][] grid) {
        for (int[] row : grid) {
            for (int j = 0; j < row.length; j++) {
                out.print(row[j] + (j == row.length - 1 ? "" : " "));
            }
            out.println();
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

