            return grid;
        }
    }

    /**
     * Contains the business logic for solving the grid problem.
     */
    static class GridSolver {
        private static final int[] ROW_OFFSETS = {1, -1, 0, 0};
        private static final int[] COL_OFFSETS = {0, 0, 1, -1};

        /**
         * Processes the grid. If valid, returns a new grid where each cell 
         * contains the count of its neighbors.
         *
         * @param grid The input 2D grid.
         * @return A SolverResult indicating success or failure.
         */
        public SolverResult solve(int[][] grid) {
            int rows = grid.length;
            int cols = grid[0].length;
            int[][] transformedGrid = new int[rows][cols];

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    int neighborCount = countValidNeighbors(r, c, rows, cols);

                    // Validation: If current cell value > available neighbors
                    if (grid[r][c] > neighborCount) {
                        return SolverResult.failure();
                    }

                    transformedGrid[r][c] = neighborCount;
                }
            }

            return SolverResult.success(transformedGrid);
        }

        private int countValidNeighbors(int row, int col, int maxRows, int maxCols) {
            int count = 0;
            for (int i = 0; i < 4; i++) {
                int newRow = row + ROW_OFFSETS[i];
                int newCol = col + COL_OFFSETS[i];

                if (isValidPosition(newRow, newCol, maxRows, maxCols)) {
                    count++;
                }
            }
            return count;
        }

        private boolean isValidPosition(int r, int c, int maxRows, int maxCols) {
            return r >= 0 && r < maxRows && c >= 0 && c < maxCols;
        }
    }

