/**
 * Solution to the Neighbor Grid problem.
 * The goal is to verify if every cell value is less than or equal to its 
 * number of adjacent neighbors, and if so, transform the grid into a 
 * grid of neighbor counts.
 */
public class NeighborGrid {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        int testCases = reader.nextInt();

        for (int t = 0; t < testCases; t++) {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            int[][] inputGrid = new int[rows][cols];

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    inputGrid[i][j] = reader.nextInt();
                }
            }

            GridProcessor processor = new GridProcessor(inputGrid, rows, cols);
            GridResult result = processor.process();

            if (result.isValid()) {
                writer.println("YES");
                printGrid(result.getTransformedGrid(), writer);
            } else {
                writer.println("NO");
            }
        }
        writer.flush();
        writer.close();
    }

    private static void printGrid(int[][] grid, PrintWriter writer) {
        for (int[] row : grid) {
            for (int cell : row) {
                writer.print(cell).print(" ");
            }
            writer.println();
        }
    }

    /**
     * Handles the core logic of validating and transforming the grid.
     */
    static class GridProcessor {
        private static final int[] ROW_OFFSETS = {0, 0, 1, -1};
        private static final int[] COL_OFFSETS = {1, -1, 0, 0};

        private final int[][] originalGrid;
        private final int rows;
        private final int cols;

        public GridProcessor(int[][] originalGrid, int rows, int cols) {
            this.originalGrid = originalGrid;
            this.rows = rows;
            this.cols = cols;
        }

        public GridResult process() {
            int[][] transformedGrid = new int[rows][cols];

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    int neighborCount = countValidNeighbors(r, c);
                    int originalValue = originalGrid[r][c];

                    if (originalValue > neighborCount) {
                        return GridResult.invalid();
                    }
                    transformedGrid[r][c] = neighborCount;
                }
            }

            return GridResult.success(transformedGrid);
        }

        private int countValidNeighbors(int r, int c) {
            int count = 0;
            for (int i = 0; i < 4; i++) {
                int nr = r + ROW_OFFSETS[i];
                int nc = c + COL_OFFSETS[i];

                if (isWithinBounds(nr, nc)) {
                    count++;
                }
            }
            return count;
        }

        private boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * Data Transfer Object to hold the outcome of the GridProcessor.
     */
    static class GridResult {
        private final boolean valid;
        private final int[][] transformedGrid;

        private GridResult(boolean valid, int[][] transformedGrid) {
            this.valid = valid;
            this.transformedGrid = transformedGrid;
        }

        public static GridResult success(int[][] grid) {
            return new GridResult(true, grid);
        }

        public static GridResult invalid() {
            return new GridResult(false, null);
        }

        public boolean isValid() {
            return valid;
        }

        public int[][] getTransformedGrid() {
            return transformedGrid;
        }
    }

    /**
     * Fast I/O utility for efficient reading of large inputs.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(java.io.InputStream inputStream) {
            br = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

