/**
 * Refactored NeighborGrid program.
 * This program validates if each cell in a grid has a value less than or equal 
 * to its number of adjacent neighbors. If valid, it transforms the cell 
 * value to its neighbor count.
 */
public class NeighborGrid {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        if (scanner.hasNextInt()) {
            int testCases = scanner.nextInt();
            for (int i = 0; i < testCases; i++) {
                processTestCase(scanner, writer);
            }
        }

        writer.close();
        scanner.close();
    }

    /**
     * Orchestrates the reading, processing, and output for a single test case.
     */
    private static void processTestCase(Scanner scanner, PrintWriter writer) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        int[][] matrix = new int[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                matrix[r][c] = scanner.nextInt();
            }
        }

        Grid grid = new Grid(matrix, rows, cols);

        if (grid.validateAndTransform()) {
            writer.println("YES");
            grid.print(writer);
        } else {
            writer.println("NO");
        }
    }

    /**
     * Represents the grid structure and contains logic for neighbor validation.
     */
    static class Grid {
        private final int[][] matrix;
        private final int rows;
        private final int cols;

        // Directions for traversing neighbors: Up, Down, Left, Right
        private static final int[][] DIRECTIONS = {
            {-1, 0}, {1, 0}, {0, -1}, {0, 1}
        };

        public Grid(int[][] matrix, int rows, int cols) {
            this.matrix = matrix;
            this.rows = rows;
            this.cols = cols;
        }

        /**
         * Checks if every cell value is <= number of neighbors.
         * If true, transforms the cell value to the number of neighbors.
         * 
         * @return true if the entire grid is valid, false otherwise.
         */
        public boolean validateAndTransform() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    int neighborCount = countNeighbors(r, c);

                    if (matrix[r][c] > neighborCount) {
                        return false;
                    }

                    // Per original requirement: update cell value to neighbor count
                    matrix[r][c] = neighborCount;
                }
            }
            return true;
        }

        /**
         * Calculates the number of valid adjacent neighbors for a given cell.
         */
        private int countNeighbors(int r, int c) {
            int count = 0;
            for (int[] dir : DIRECTIONS) {
                int newRow = r + dir[0];
                int newCol = c + dir[1];

                if (isValidIndex(newRow, newCol)) {
                    count++;
                }
            }
            return count;
        }

        private boolean isValidIndex(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        /**
         * Prints the grid to the provided PrintWriter.
         */
        public void print(PrintWriter writer) {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    writer.print(matrix[r][c]);
                    if (c < cols - 1) {
                        writer.print(" ");
                    }
                }
                writer.println();
            }
        }
    }
}

