/**
 * A solution to validate and transform a grid based on positional constraints.
 * Constraints:
 * - Corners must be <= 2
 * - Edges must be <= 3
 * - Interior cells must be <= 4
 */
public class GridProblemSolver {

    // Constants representing the maximum allowed values for different cell positions
    private static final int CORNER_LIMIT = 2;
    private static final int EDGE_LIMIT = 3;
    private static final int INTERIOR_LIMIT = 4;

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int testCases = reader.nextInt();

        while (testCases-- > 0) {
            solve(reader, out);
        }

        out.flush();
        out.close();
    }

    /**
     * Orchestrates the solving process for a single test case.
     */
    private static void solve(FastReader reader, PrintWriter out) {
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        int[][] matrix = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                matrix[i][j] = reader.nextInt();
            }
        }

        if (isValid(matrix, rows, cols)) {
            out.println("YES");
            out.println(generateMaximalGrid(rows, cols));
        } else {
            out.println("NO");
        }
    }

    /**
     * Checks if the input matrix satisfies the positional constraints.
     */
    private static boolean isValid(int[][] matrix, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (matrix[i][j] > getCellLimit(i, j, rows, cols)) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Returns the maximum allowed value for a cell based on its coordinates.
     * 
     * @param r Current row
     * @param c Current column
     * @param rows Total rows
     * @param cols Total columns
     * @return The limit value (2 for corners, 3 for edges, 4 for interior)
     */
    private static int getCellLimit(int r, int c, int rows, int cols) {
        boolean isCorner = (r == 0 || r == rows - 1) && (c == 0 || c == cols - 1);
        if (isCorner) {
            return CORNER_LIMIT;
        }

        boolean isEdge = (r == 0 || r == rows - 1 || c == 0 || c == cols - 1);
        if (isEdge) {
            return EDGE_LIMIT;
        }

        return INTERIOR_LIMIT;
    }

    /**
     * Generates a string representation of the maximal valid grid.
     */
    private static String generateMaximalGrid(int rows, int cols) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                sb.append(getCellLimit(i, j, rows, cols));
                if (j < cols - 1) {
                    sb.append(" ");
                }
            }
            sb.append("\n");
        }
        return sb.toString().trim();
    }

    /**
     * Fast I/O class for efficient reading of input.
     */
    static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

