/**
 * Refactored solution for the grid validation and generation problem.
 * The goal is to validate if a grid adheres to specific constraints for 
 * corners, edges, and interior cells, and then generate a standard grid.
 */
public class Main {

    // Constraints for validation
    private static final int MAX_CORNER_VALUE = 2;
    private static final int MAX_EDGE_VALUE = 3;
    private static final int MAX_INNER_VALUE = 4;

    // Standard values for the generated grid
    private static final int CORNER_VAL = 2;
    private static final int EDGE_VAL = 3;
    private static final int INNER_VAL = 4;

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            String testCasesStr = reader.next();
            if (testCasesStr == null) return;

            int testCases = Integer.parseInt(testCasesStr);

            while (testCases-- > 0) {
                int rows = reader.nextInt();
                int cols = reader.nextInt();
                int[][] grid = new int[rows][cols];

                for (int i = 0; i < rows; i++) {
                    for (int j = 0; j < cols; j++) {
                        grid[i][j] = reader.nextInt();
                    }
                }

                solve(rows, cols, grid, writer);
            }
        } catch (Exception e) {
            // In production, replace with a logging framework like SLF4J
            e.printStackTrace();
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Processes a single test case.
     */
    private static void solve(int rows, int cols, int[][] grid, PrintWriter writer) {
        if (isValid(rows, cols, grid)) {
            writer.println("YES");
            printResultGrid(rows, cols, writer);
        } else {
            writer.println("NO");
        }
    }

    /**
     * Validates the grid based on corner, edge, and interior constraints.
     */
    private static boolean isValid(int rows, int cols, int[][] grid) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int val = grid[i][j];
                if (isCorner(i, j, rows, cols)) {
                    if (val > MAX_CORNER_VALUE) return false;
                } else if (isEdge(i, j, rows, cols)) {
                    if (val > MAX_EDGE_VALUE) return false;
                } else {
                    if (val > MAX_INNER_VALUE) return false;
                }
            }
        }
        return true;
    }

    /**
     * Prints the standard grid values based on the cell's position.
     */
    private static void printResultGrid(int rows, int cols, PrintWriter writer) {
        for (int i = 0; i < rows; i++) {
            StringBuilder rowBuilder = new StringBuilder();
            for (int j = 0; j < cols; j++) {
                if (isCorner(i, j, rows, cols)) {
                    rowBuilder.append(CORNER_VAL);
                } else if (isEdge(i, j, rows, cols)) {
                    rowBuilder.append(EDGE_VAL);
                } else {
                    rowBuilder.append(INNER_VAL);
                }

                if (j < cols - 1) {
                    rowBuilder.append(" ");
                }
            }
            writer.println(rowBuilder.toString());
        }
    }

    private static boolean isCorner(int r, int c, int rows, int cols) {
        return (r == 0 || r == rows - 1) && (c == 0 || c == cols - 1);
    }

    private static boolean isEdge(int r, int c, int rows, int cols) {
        return (r == 0 || r == rows - 1 || c == 0 || c == cols - 1);
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

