import java.util.Scanner;

/**
 * NeighborGrid validates if a grid of integers conforms to specific constraints 
 * regarding corner, edge, and interior cell values, and prints a maximal 
 * valid grid if the input is valid.
 */
public class NeighborGrid {

    private enum CellType {
        CORNER,
        EDGE,
        INTERIOR
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (scanner.hasNextInt()) {
            int testCases = scanner.nextInt();
            for (int i = 0; i < testCases; i++) {
                processTestCase(scanner);
            }
        }
        scanner.close();
    }

    private static void processTestCase(Scanner scanner) {
        // Note: Maintaining original input order where n=cols and m=rows
        int numCols = scanner.nextInt();
        int numRows = scanner.nextInt();

        int[][] grid = readGrid(scanner, numRows, numCols);

        if (isValidGrid(grid, numRows, numCols)) {
            System.out.println("YES");
            printMaximalGrid(numRows, numCols);
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Reads the grid from the scanner. 
     * Note: The original logic used Column-Major order for input.
     */
    private static int[][] readGrid(Scanner scanner, int rows, int cols) {
        int[][] grid = new int[rows][cols];
        for (int j = 0; j < cols; j++) {
            for (int i = 0; i < rows; i++) {
                grid[i][j] = scanner.nextInt();
            }
        }
        return grid;
    }

    /**
     * Validates the grid based on cell constraints:
     * Corners <= 2, Edges <= 3, Interior <= 4.
     */
    private static boolean isValidGrid(int[][] grid, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                CellType type = getCellType(i, j, rows, cols);
                int value = grid[i][j];

                if (type == CellType.CORNER && value > 2) return false;
                if (type == CellType.EDGE && value > 3) return false;
                if (type == CellType.INTERIOR && value > 4) return false;
            }
        }
        return true;
    }

    /**
     * Determines the type of a cell based on its coordinates.
     */
    private static CellType getCellType(int r, int c, int rows, int cols) {
        boolean isRowEdge = (r == 0 || r == rows - 1);
        boolean isColEdge = (c == 0 || c == cols - 1);

        if (isRowEdge && isColEdge) {
            return CellType.CORNER;
        } else if (isRowEdge || isColEdge) {
            return CellType.EDGE;
        } else {
            return CellType.INTERIOR;
        }
    }

    /**
     * Prints the maximum possible valid values for the given grid dimensions.
     */
    private static void printMaximalGrid(int rows, int cols) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                CellType type = getCellType(i, j, rows, cols);
                switch (type) {
                    case CORNER:
                        sb.append("2 ");
                        break;
                    case EDGE:
                        sb.append("3 ");
                        break;
                    case INTERIOR:
                        sb.append("4 ");
                        break;
                }
            }
            sb.append("\n");
        }
        System.out.print(sb.toString());
    }
}

