 * - Interior: 4
 */
public class NeighbourGrid {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int testCases = reader.nextInt();
        while (testCases-- > 0) {
            solve(reader, out);
        }
        out.flush();
        out.close();
    }

