     * Processes a single test case.
     */
    private static void solve(FastReader reader, PrintWriter out) {
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        int[][] neighborGrid = new int[rows][cols];
        boolean isPossible = true;

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int requiredNeighbors = reader.nextInt();
                int actualNeighbors = getNeighborValue(i, j, rows, cols);

                // If the input requirement exceeds the theoretical capacity of the cell
                if (actualNeighbors < requiredNeighbors) {
                    isPossible = false;
                }
                neighborGrid[i][j] = actualNeighbors;
            }
        }

        if (isPossible) {
            out.println("YES");
            printGrid(neighborGrid, out);
        } else {
            out.println("NO");
        }
    }

