     * @param c Current column index
     * @param rows Total rows in the grid
     * @param cols Total columns in the grid
     * @return 2 for corners, 3 for edges, 4 for interior
     */
    private static int getNeighborValue(int r, int c, int rows, int cols) {
        boolean isCorner = (r == 0 || r == rows - 1) && (c == 0 || c == cols - 1);
        if (isCorner) {
            return 2;
        }

        boolean isEdge = (r == 0 || r == rows - 1 || c == 0 || c == cols - 1);
        if (isEdge) {
            return 3;
        }

