/**
 * A solution to validate and transform a matrix based on position-based constraints.
 * 
 * Rules:
 * - Corner cells: maximum allowed value is 2.
 * - Border cells (non-corner): maximum allowed value is 3.
 * - Interior cells: maximum allowed value is 4.
 * 
 * If all cells satisfy their constraints, the matrix is transformed by 
 * setting each cell to its maximum allowed value and "YES" is printed.
 * Otherwise, "NO" is printed.
 */
public class Solution {

    private static final int MAX_CORNER_VALUE = 2;
    private static final int MAX_BORDER_VALUE = 3;
    private static final int MAX_INTERIOR_VALUE = 4;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int testCases = scanner.nextInt();
        while (testCases-- > 0) {
            processTestCase(scanner);
        }

        scanner.close();
    }

    /**
     * Reads input for a single test case, validates/transforms the matrix, 
     * and outputs the result.
     */
    private static void processTestCase(Scanner scanner) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        int[][] matrix = new int[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                matrix[i][j] = scanner.nextInt();
            }
        }

        if (validateAndTransform(matrix, rows, cols)) {
            System.out.println("YES");
            printMatrix(matrix, rows, cols);
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Validates if matrix elements respect positional constraints.
     * If valid, transforms each element to its maximum allowed capacity.
     *
     * @param matrix The 2D array to validate.
     * @param rows   Number of rows.
     * @param cols   Number of columns.
     * @return true if the matrix is valid, false otherwise.
     */
    private static boolean validateAndTransform(int[][] matrix, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int limit = getMaxAllowedValue(i, j, rows, cols);

                if (matrix[i][j] > limit) {
                    return false;
                }

                // Transform cell to its maximum capacity
                matrix[i][j] = limit;
            }
        }
        return true;
    }

    /**
     * Determines the maximum allowed value for a cell based on its location.
     * Priority: Corner > Border > Interior.
     */
    private static int getMaxAllowedValue(int r, int c, int rows, int cols) {
        boolean isCorner = (r == 0 || r == rows - 1) && (c == 0 || c == cols - 1);
        if (isCorner) {
            return MAX_CORNER_VALUE;
        }

        boolean isBorder = (r == 0 || r == rows - 1 || c == 0 || c == cols - 1);
        if (isBorder) {
            return MAX_BORDER_VALUE;
        }

        return MAX_INTERIOR_VALUE;
    }

    /**
     * Prints the matrix to the standard output.
     */
    private static void printMatrix(int[][] matrix, int rows, int cols) {
        StringBuilder output = new StringBuilder();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                output.append(matrix[i][j]).append(" ");
            }
            output.append("\n");
        }
        System.out.print(output.toString());
    }
}

