    /**
     * Validates if the provided grid satisfies the boundary constraints.
     */
    private static boolean isGridValid(int[][] grid, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] > getMaxAllowedValue(i, j, rows, cols)) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Generates a string representation of the maximized allowed grid.
     */
    private static String generateMaximizedGridString(int rows, int cols) {
        StringBuilder outputBuilder = new StringBuilder();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                outputBuilder.append(getMaxAllowedValue(i, j, rows, cols));
                if (j < cols - 1) {
                    outputBuilder.append(" ");
                }
            }
            outputBuilder.append("\n");
        }
        return outputBuilder.toString().trim();
    }

    /**
     * Determines the maximum allowed value for a cell based on its position.
     * 
     * @param r current row index
     * @param c current column index
     * @param rows total row count
     * @param cols total column count
     * @return the maximum allowed integer value for that cell
     */
    private static int getMaxAllowedValue(int r, int c, int rows, int cols) {
        if (isCorner(r, c, rows, cols)) {
            return 2;
        } else if (isEdge(r, c, rows, cols)) {
            return 3;
        } else {
            return 4;
        }
