/**
 * Refactored Grid program to validate and generate a requirement grid.
 * The requirement grid follows specific rules for corners, edges, and interior cells.
 */
public class Grid {

    // Constants for the requirement grid values
    private static final long CORNER_VALUE = 2;
    private static final long EDGE_VALUE = 3;
    private static final long INTERIOR_VALUE = 4;

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int testCases = reader.nextInt();
            while (testCases-- > 0) {
                solve(reader, out);
            }
        } catch (Exception e) {
            // Handle potential parsing errors
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Orchestrates the logic for a single test case.
     */
    private static void solve(FastReader reader, PrintWriter out) {
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        long[][] inputGrid = new long[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                inputGrid[i][j] = reader.nextLong();
            }
        }

        long[][] requiredGrid = generateRequiredGrid(rows, cols);

        if (isGridValid(inputGrid, requiredGrid, rows, cols)) {
            out.println("YES");
            printGrid(requiredGrid, rows, cols, out);
        } else {
            out.println("NO");
        }
    }

    /**
     * Generates the grid based on the corner/edge/interior rules.
     */
    private static long[][] generateRequiredGrid(int rows, int cols) {
        long[][] grid = new long[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                grid[i][j] = getRequiredValue(i, j, rows, cols);
            }
        }
        return grid;
    }

    /**
     * Determines the value for a specific cell based on its position.
     */
    private static long getRequiredValue(int r, int c, int rows, int cols) {
        boolean isRowEdge = (r == 0 || r == rows - 1);
        boolean isColEdge = (c == 0 || c == cols - 1);

        if (isRowEdge && isColEdge) {
            return CORNER_VALUE;
        } else if (isRowEdge || isColEdge) {
            return EDGE_VALUE;
        } else {
            return INTERIOR_VALUE;
        }
    }

    /**
     * Validates if every cell in the input grid is less than or equal to the required grid.
     */
    private static boolean isGridValid(long[][] input, long[][] required, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                // The original logic: if input > required, it is invalid
                if (input[i][j] > required[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Prints the grid to the provided PrintWriter.
     */
    private static void printGrid(long[][] grid, int rows, int cols, PrintWriter out) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                out.print(grid[i][j]);
                if (j < cols - 1) {
                    out.print(" ");
                }
            }
            out.println();
        }
    }

    /**
     * Fast I/O utility for efficient reading of large inputs.
     */
    static class FastReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int curChar;
        private int numChars;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (numChars == -1) throw new RuntimeException("End of stream");
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buffer);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
                if (numChars <= 0) return -1;
            }
            return buffer[curChar++];
        }

        private int peek() {
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buffer);
                } catch (IOException e) {
                    return -1;
                }
                if (numChars <= 0) return -1;
            }
            return buffer[curChar];
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (c != -1 && !isSpaceChar(c));
            return res.toString();
        }

        public double nextDouble() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            double res = 0;
            while (!isSpaceChar(c) && c != '.') {
                if (c == 'e' || c == 'E') return res * Math.pow(10, nextInt());
                if (c < '0' || c > '9') throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            }
            if (c == '.') {
                c = read();
                double m = 1;
                while (!isSpaceChar(c)) {
                    if (c == 'e' || c == 'E') return res * Math.pow(10, nextInt());
                    if (c < '0' || c > '9') throw new InputMismatchException();
                    m /= 10;
                    res += (c - '0') * m;
                    c = read();
                }
            }
            return res * sgn;
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

