 * Handles the transformation logic for the grid.
 */
class GridProcessor {
    private static final int CORNER_MAX_VALUE = 2;
    private static final int EDGE_MAX_VALUE = 3;
    private static final int INTERIOR_MAX_VALUE = 4;

    /**
     * Processes the grid based on the rules:
     * 1. If no positive elements exist, return original.
     * 2. Otherwise, transform every cell to its max allowed value, 
     *    provided the original value doesn't exceed that limit.
     */
    public GridResult process(int[][] grid, boolean hasPositiveElement) {
        int rows = grid.length;
        int cols = grid[0].length;

        if (!hasPositiveElement) {
            return new GridResult(true, grid);
        }

        int[][] transformedGrid = new int[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int limit = getMaxAllowedValue(i, j, rows, cols);

                if (grid[i][j] > limit) {
                    return new GridResult(false, null);
                }
                transformedGrid[i][j] = limit;
            }
        }

        return new GridResult(true, transformedGrid);
    }

    private int getMaxAllowedValue(int r, int c, int rows, int cols) {
        boolean isCorner = (r == 0 || r == rows - 1) && (c == 0 || c == cols - 1);
        if (isCorner) {
            return CORNER_MAX_VALUE;
        }

        boolean isEdge = (r == 0 || r == rows - 1 || c == 0 || c == cols - 1);
        if (isEdge) {
            return EDGE_MAX_VALUE;
        }

        return INTERIOR_MAX_VALUE;
    }
}

/**
 * Data carrier for the result of a grid processing operation.
 */
class GridResult {
    private final boolean possible;
    private final int[][] grid;

    public GridResult(boolean possible, int[][] grid) {
        this.possible = possible;
        this.grid = grid;
    }

    public boolean isPossible() {
        return possible;
    }

    public int[][] getGrid() {
        return grid;
    }
}

