/**
 * GridConstraintManager validates if a given matrix satisfies specific boundary constraints:
 * - Corners must be <= 2
 * - Edges must be <= 3
 * - Interior cells must be <= 4
 * 
 * If valid, it outputs a maximal grid satisfying these constraints.
 */
public class GridConstraintManager {

    // Boundary constraints constants
    private static final int CORNER_MAX = 2;
    private static final int EDGE_MAX = 3;
    private static final int INTERIOR_MAX = 4;

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        PrintWriter out = new PrintWriter(System.out);

        try {
            int testCases = reader.nextInt();
            while (testCases-- > 0) {
                processTestCase(reader, out);
            }
        } catch (Exception e) {
            // Handle or log potential input errors
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Processes a single test case: reads the grid, validates it, and prints results.
     */
    private static void processTestCase(FastReader reader, PrintWriter out) throws IOException {
        int rowCount = reader.nextInt();
        int colCount = reader.nextInt();
        int[][] grid = new int[rowCount][colCount];

        for (int i = 0; i < rowCount; i++) {
            for (int j = 0; j < colCount; j++) {
                grid[i][j] = reader.nextInt();
            }
        }

        if (isGridValid(grid, rowCount, colCount)) {
            out.println("YES");
            printMaximalGrid(grid, rowCount, colCount, out);
        } else {
            out.println("NO");
        }
    }

    /**
     * Checks if the provided grid respects the boundary constraints.
     */
    private static boolean isGridValid(int[][] grid, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] > getConstraintValue(i, j, rows, cols)) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Determines the maximum allowed value for a cell at position (r, c).
     */
    private static int getConstraintValue(int r, int c, int rows, int cols) {
        boolean isRowEdge = (r == 0 || r == rows - 1);
        boolean isColEdge = (c == 0 || c == cols - 1);

        if (isRowEdge && isColEdge) {
            return CORNER_MAX;
        } else if (isRowEdge || isColEdge) {
            return EDGE_MAX;
        } else {
            return INTERIOR_MAX;
        }
    }

    /**
     * Prints a grid filled with the maximum possible values for each cell type.
     */
    private static void printMaximalGrid(int[][] grid, int rows, int cols, PrintWriter out) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                out.print(getConstraintValue(i, j, rows, cols) + (j == cols - 1 ? "" : " "));
            }
            out.println();
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader() {
            reader = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

/**
 * NeighbourGrid determines if a given matrix adheres to specific neighbor constraints:
 * - Corners must be <= 2
 * - Edges must be <= 3
 * - Interior cells must be <= 4
 * 
 * If valid, it prints a "standard" grid following those exact limits.
 */
public class NeighbourGrid {

    private static final int MAX_CORNER_VALUE = 2;
    private static final int MAX_EDGE_VALUE = 3;
    private static final int MAX_INTERIOR_VALUE = 4;

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;

            int numberOfTestcases = scanner.nextInt();

            while (numberOfTestcases-- > 0) {
                processTestCase(scanner);
            }
        }
    }

    /**
     * Orchestrates the reading, validation, and output for a single test case.
     */
    private static void processTestCase(Scanner scanner) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        int[][] grid = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                grid[i][j] = scanner.nextInt();
            }
        }

        if (isInvalid(grid)) {
            System.out.println("NO");
        } else {
            System.out.println("YES");
            printStandardGrid(rows, cols);
        }
    }

    /**
     * Validates if the matrix violates the constraints.
     * Logic hierarchy: Corner -> Edge -> Interior.
     */
    private static boolean isInvalid(int[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int value = grid[r][c];

                if (isCorner(r, c, rows, cols)) {
                    if (value > MAX_CORNER_VALUE) return true;
                } else if (isEdge(r, c, rows, cols)) {
                    if (value > MAX_EDGE_VALUE) return true;
                } else {
                    if (value > MAX_INTERIOR_VALUE) return true;
                }
            }
        }
        return false;
    }

    /**
     * Prints a standardized matrix based on the input dimensions.
     */
    private static void printStandardGrid(int rows, int cols) {
        StringBuilder sb = new StringBuilder();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (isCorner(r, c, rows, cols)) {
                    sb.append(MAX_CORNER_VALUE);
                } else if (isEdge(r, c, rows, cols)) {
                    sb.append(MAX_EDGE_VALUE);
                } else {
                    sb.append(MAX_INTERIOR_VALUE);
                }
                sb.append(" ");
            }
            sb.append("\n");
        }
        System.out.print(sb.toString());
    }

    private static boolean isCorner(int r, int c, int rows, int cols) {
        return (r == 0 || r == rows - 1) && (c == 0 || c == cols - 1);
    }

    private static boolean isEdge(int r, int c, int rows, int cols) {
        return (r == 0 || r == rows - 1 || c == 0 || c == cols - 1);
    }
}

import java.util.Scanner;
import java.io.PrintWriter;

/**
 * A program to validate and transform a grid based on cell position constraints.
 * Corners must be <= 2, edges <= 3, and interior cells <= 4.
 */
public class Main {

    // Constants representing the maximum allowed values for different cell types
    private static final int MAX_CORNER_VALUE = 2;
    private static final int MAX_EDGE_VALUE = 3;
    private static final int MAX_INTERIOR_VALUE = 4;

    public static void main(String[] args) {
        // Use try-with-resources for automatic management of I/O streams
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter writer = new PrintWriter(System.out)) {

            if (!scanner.hasNextInt()) {
                return;
            }

            int testCases = scanner.nextInt();
            while (testCases-- > 0) {
                processTestCase(scanner, writer);
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * Orchestrates the logic for a single test case.
     */
    private static void processTestCase(Scanner scanner, PrintWriter writer) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        int[][] grid = new int[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                grid[i][j] = scanner.nextInt();
            }
        }

        if (validateAndTransformGrid(grid, rows, cols)) {
            writer.println("YES");
            printGrid(grid, writer);
        } else {
            writer.println("NO");
        }
    }

    /**
     * Validates the grid against position-based constraints and transforms values.
     * @return true if the entire grid is valid, false otherwise.
     */
    private static boolean validateAndTransformGrid(int[][] grid, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (!applyConstraint(grid, r, c, rows, cols)) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Checks if a specific cell meets its position-based constraint and updates it.
     */
    private static boolean applyConstraint(int[][] grid, int r, int c, int rows, int cols) {
        boolean isCorner = isCorner(r, c, rows, cols);
        boolean isEdge = isEdge(r, c, rows, cols);

        if (isCorner) {
            return updateCellValue(grid, r, c, MAX_CORNER_VALUE);
        } else if (isEdge) {
            return updateCellValue(grid, r, c, MAX_EDGE_VALUE);
        } else {
            return updateCellValue(grid, r, c, MAX_INTERIOR_VALUE);
        }
    }

    private static boolean isCorner(int r, int c, int rows, int cols) {
        return (r == 0 || r == rows - 1) && (c == 0 || c == cols - 1);
    }

    private static boolean isEdge(int r, int c, int rows, int cols) {
        return (r == 0 || r == rows - 1 || c == 0 || c == cols - 1);
    }

    private static boolean updateCellValue(int[][] grid, int r, int c, int maxValue) {
        if (grid[r][c] <= maxValue) {
            grid[r][c] = maxValue;
            return true;
        }
        return false;
    }

    /**
     * Helper to print the grid in a formatted manner.
     */
    private static void printGrid(int[][] grid, PrintWriter writer) {
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                writer.print(grid[i][j]);
                if (j < grid[i].length - 1) {
                    writer.print(" ");
                }
            }
            writer.println();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver for grid-based constraint satisfaction problems.
 * The program ensures that cell values do not violate corner/edge constraints
 * and that every cell has sufficient adjacent non-zero neighbors.
 */
public class GridConstraintSolver {

    private static final int[] ROW_OFFSETS = {-1, 0, 1, 0};
    private static final int[] COL_OFFSETS = {0, -1, 0, 1};
    private static final String DEFAULT_INPUT_FILE = "B.in";

    public static void main(String[] args) {
        try {
            new GridConstraintSolver().execute();
        } catch (IOException e) {
            System.err.println("An error occurred during execution: " + e.getMessage());
        }
    }

    /**
     * Entry point for the application logic.
     */
    public void execute() throws IOException {
        try (BufferedReader reader = createReader();
             PrintWriter writer = createWriter()) {

            String firstLine = reader.readLine();
            if (firstLine == null) return;

            int testCases = Integer.parseInt(firstLine.trim());
            while (testCases-- > 0) {
                processTestCase(reader, writer);
            }
        }
    }

    /**
     * Reads and parses a single test case from the reader.
     */
    private void processTestCase(BufferedReader reader, PrintWriter writer) throws IOException {
        String line = reader.readLine();
        if (line == null || line.trim().isEmpty()) return;

        StringTokenizer st = new StringTokenizer(line);
        int rows = Integer.parseInt(st.nextToken());
        int cols = Integer.parseInt(st.nextToken());

        int[][] grid = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            st = new StringTokenizer(reader.readLine());
            for (int j = 0; j < cols; j++) {
                grid[i][j] = Integer.parseInt(st.nextToken());
            }
        }

        solve(rows, cols, grid, writer);
    }

    /**
     * The core logic that processes the grid until it stabilizes or violates a constraint.
     */
    private void solve(int rows, int cols, int[][] grid, PrintWriter writer) {
        boolean isPossible = true;
        boolean changed = true;

        while (changed) {
            changed = false;

            // Traverse the grid to check constraints and update values
            gridLoop:
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    // 1. Check if current cell violates boundary-value constraints
                    if (isViolatingConstraints(rows, cols, grid, r, c)) {
                        isPossible = false;
                        break gridLoop;
                    }

                    // 2. If the cell has a value, ensure it has enough neighbors
                    if (grid[r][c] > 0) {
                        if (applyExpansionRules(rows, cols, grid, r, c)) {
                            changed = true;
                        }
                    }
                }
            }
        }

        outputResult(isPossible, grid, writer);
    }

    /**
     * Checks if a cell's value exceeds the allowed limit for its position.
     */
    private boolean isViolatingConstraints(int rows, int cols, int[][] grid, int r, int c) {
        int val = grid[r][c];
        if (val > 4) return true;

        boolean isCorner = (r == 0 || r == rows - 1) && (c == 0 || c == cols - 1);
        boolean isEdge = (r == 0 || r == rows - 1 || c == 0 || c == cols - 1);

        if (isCorner && val > 2) return true;
        if (isEdge && val > 3) return true;

        return false;
    }

    /**
     * Updates the grid based on neighbor counts. 
     * Returns true if the grid was modified in a way that requires another iteration.
     */
    private boolean applyExpansionRules(int rows, int cols, int[][] grid, int r, int c) {
        int currentValue = grid[r][c];
        int neighborCount = 0;
        List<Integer> emptyNeighborIndices = new ArrayList<>();

        // Identify adjacent neighbors
        for (int i = 0; i < 4; i++) {
            int nr = r + ROW_OFFSETS[i];
            int nc = c + COL_OFFSETS[i];

            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
                if (grid[nr][nc] > 0) {
                    neighborCount++;
                } else {
                    emptyNeighborIndices.add(i);
                }
            }
        }

        if (neighborCount < currentValue) {
            // Expansion: Fill empty neighboring cells with 1s to satisfy the requirement
            int needed = currentValue - neighborCount;
            for (int k = 0; k < needed; k++) {
                int dirIdx = emptyNeighborIndices.get(k);
                grid[r + ROW_OFFSETS[dirIdx]][c + COL_OFFSETS[dirIdx]] = 1;
            }
            return true;
        } else if (neighborCount > currentValue) {
            // Shrinkage: Update current cell to match the neighbor count
            grid[r][c] = neighborCount;
            // Following original logic: shrinking does not trigger a 'changed' flag
            return false;
        }

        return false;
    }

    private void outputResult(boolean isPossible, int[][] grid, PrintWriter writer) {
        if (isPossible) {
            writer.println("YES");
            printGrid(grid, writer);
        } else {
            writer.println("NO");
        }
    }

    private void printGrid(int[][] grid, PrintWriter writer) {
        for (int[] row : grid) {
            StringBuilder sb = new StringBuilder();
            for (int j = 0; j < row.length; j++) {
                sb.append(row[j]);
                if (j < row.length - 1) {
                    sb.append(" ");
                }
            }
            writer.println(sb.toString());
        }
    }

    private BufferedReader createReader() throws IOException {
        File inputFile = new File(DEFAULT_INPUT_FILE);
        if (inputFile.exists()) {
            return new BufferedReader(new FileReader(inputFile));
        }
        return new BufferedReader(new InputStreamReader(System.in));
    }

    private PrintWriter createWriter() {
        return new PrintWriter(System.out);
    }
}

import java.util.*;
import java.io.*;

/**
 * A program to validate and generate a grid pattern based on neighbor constraints.
 * Rules:
 * - Corners must be <= 2
 * - Edges must be <= 3
 * - Interior cells must be <= 4
 */
public class NeighbourGrid {

    /**
     * Represents the different roles a cell can play in the grid.
     * Each type defines the maximum value allowed for that cell.
     */
    enum CellType {
        CORNER(2),
        EDGE(3),
        INTERIOR(4);

        final int maxValue;

        CellType(int maxValue) {
            this.maxValue = maxValue;
        }
    }

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        int testCases = reader.nextInt();
        GridSolver solver = new GridSolver(reader, writer);

        while (testCases-- > 0) {
            solver.solve();
        }

        writer.flush();
        writer.close();
    }

    /**
     * Handles the logic for a single test case.
     */
    static class GridSolver {
        private final FastReader reader;
        private final PrintWriter writer;

        public GridSolver(FastReader reader, PrintWriter writer) {
            this.reader = reader;
            this.writer = writer;
        }

        public void solve() {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            int[][] grid = new int[rows][cols];
            boolean isValid = true;

            // Read grid and validate constraints in a single pass
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    grid[r][c] = reader.nextInt();

                    CellType type = getCellType(r, c, rows, cols);
                    if (grid[r][c] > type.maxValue) {
                        isValid = false;
                    }
                }
            }

            if (isValid) {
                printPattern(rows, cols);
            } else {
                writer.println("NO");
            }
        }

        /**
         * Determines the type of a cell based on its coordinates.
         */
        private CellType getCellType(int r, int c, int rows, int cols) {
            boolean isRowEdge = (r == 0 || r == rows - 1);
            boolean isColEdge = (c == 0 || c == cols - 1);

            if (isRowEdge && isColEdge) {
                return CellType.CORNER;
            } else if (isRowEdge || isColEdge) {
                return CellType.EDGE;
            } else {
                return CellType.INTERIOR;
            }
        }

        /**
         * Prints the valid pattern requested by the problem.
         */
        private void printPattern(int rows, int cols) {
            writer.println("YES");
            for (int r = 0; r < rows; r++) {
                StringBuilder rowOutput = new StringBuilder();
                for (int c = 0; c < cols; c++) {
                    CellType type = getCellType(r, c, rows, cols);
                    rowOutput.append(type.maxValue).append(" ");
                }
                writer.println(rowOutput.toString().trim());
            }
        }
    }

    /**
     * Optimized reader for fast I/O operations.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream inputStream) {
            br = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * GridConsistencySolver determines if a grid can be made consistent 
 * where each non-zero cell equals the number of its non-zero neighbors.
 */
public class GridConsistencySolver {

    private static final int[][] DIRECTIONS = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

    public static void main(String[] args) throws IOException {
        FastReader reader = new FastReader(System.in);
        int testCases = reader.nextInt();
        StringBuilder output = new StringBuilder();

        while (testCases-- > 0) {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            int[][] grid = new int[rows][cols];

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = reader.nextInt();
                }
            }

            processTestCase(rows, cols, grid, output);
        }
        System.out.print(output.toString());
    }

    /**
     * Orchestrates the logic for a single test case.
     */
    private static void processTestCase(int rows, int cols, int[][] grid, StringBuilder output) {
        List<CellRequirement> mismatchedCells = new ArrayList<>();
        boolean isImpossible = false;

        // 1. Identify cells that don't match their neighbor count and check for impossibility
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 0) continue;

                int maxPossibleNeighbors = 0;
                int activeNeighbors = 0;

                for (int[] dir : DIRECTIONS) {
                    int nr = r + dir[0];
                    int nc = c + dir[1];
                    if (isInside(nr, nc, rows, cols)) {
                        maxPossibleNeighbors++;
                        if (grid[nr][nc] > 0) {
                            activeNeighbors++;
                        }
                    }
                }

                // If a cell's value exceeds its potential neighbors, it's impossible
                if (grid[r][c] > maxPossibleNeighbors) {
                    isImpossible = true;
                    break;
                }

                // If current active neighbors don't match the cell value, mark for repair
                if (grid[r][c] != activeNeighbors) {
                    mismatchedCells.add(new CellRequirement(r, c, activeNeighbors));
                }
            }
            if (isImpossible) break;
        }

        if (isImpossible) {
            output.append("NO\n");
            return;
        }

        // 2. Attempt to repair the grid by filling zeros to satisfy requirements
        for (CellRequirement cell : mismatchedCells) {
            int r = cell.row;
            int c = cell.col;

            // If the grid value is less than what it currently has, normalize it
            if (grid[r][c] < cell.requiredCount) {
                grid[r][c] = cell.requiredCount;
                continue;
            }

            int currentActiveCount = countActiveNeighbors(r, c, rows, cols, grid);
            int remainingNeeded = grid[r][c] - currentActiveCount;

            if (remainingNeeded <= 0) continue;

            // Find adjacent zeros to activate them
            for (int[] dir : DIRECTIONS) {
                if (remainingNeeded <= 0) break;

                int nr = r + dir[0];
                int nc = c + dir[1];

                if (isInside(nr, nc, rows, cols) && grid[nr][nc] == 0) {
                    grid[nr][nc] = countActiveNeighbors(nr, nc, rows, cols, grid);
                    remainingNeeded--;
                }
            }
        }

        // 3. Final reconciliation: recalculate all non-zero cells based on final neighbor counts
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] != 0) {
                    grid[r][c] = countActiveNeighbors(r, c, rows, cols, grid);
                }
            }
        }

        // 4. Format Output
        output.append("YES\n");
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                output.append(grid[r][c]).append(" ");
            }
            output.append("\n");
        }
    }

    private static boolean isInside(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private static int countActiveNeighbors(int r, int c, int rows, int cols, int[][] grid) {
        int count = 0;
        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            if (isInside(nr, nc, rows, cols) && grid[nr][nc] > 0) {
                count++;
            }
        }
        return count;
    }

    /**
     * Represents a cell that needs its neighbor count reconciled.
     */
    static class CellRequirement {
        final int row;
        final int col;
        final int requiredCount;

        CellRequirement(int row, int col, int requiredCount) {
            this.row = row;
            this.col = col;
            this.requiredCount = requiredCount;
        }
    }

    /**
     * Fast I/O utility for efficient reading of large input sets.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * Solve handles the processing of grid-based validation and optimization.
 * The goal is to determine if a grid adheres to specific boundary constraints
 * and, if so, output an optimized version of that grid.
 */
public class Solve {

    // Constants for optimized grid values
    private static final int VALUE_CORNER = 2;
    private static final int VALUE_EDGE = 3;
    private static final int VALUE_INTERIOR = 4;

    // Constants for maximum allowed values in the input grid
    private static final int MAX_CORNER_ALLOWED = 2;
    private static final int MAX_EDGE_ALLOWED = 3;
    private static final int MAX_INTERIOR_ALLOWED = 4;

    /**
     * Represents the three possible functional areas of a cell in the grid.
     */
    private enum CellType {
        CORNER, EDGE, INTERIOR
    }

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int testCases = reader.nextInt();
            while (testCases-- > 0) {
                int rowCount = reader.nextInt();
                int colCount = reader.nextInt();
                int[][] grid = reader.readIntMatrix(rowCount, colCount);

                processGrid(grid, rowCount, colCount, out);
            }
        } catch (Exception e) {
            // In a production environment, use a proper logger.
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Orchestrates the validation and printing of the grid results.
     */
    private static void processGrid(int[][] grid, int rows, int cols, PrintWriter out) {
        if (isGridInvalid(grid, rows, cols)) {
            out.println("NO");
        } else {
            out.println("YES");
            printOptimizedGrid(rows, cols, out);
        }
    }

    /**
     * Checks if the provided grid violates any boundary-based value constraints.
     */
    private static boolean isGridInvalid(int[][] grid, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                CellType type = getCellType(i, j, rows, cols);
                int value = grid[i][j];

                if (type == CellType.CORNER && value > MAX_CORNER_ALLOWED) return true;
                if (type == CellType.EDGE && value > MAX_EDGE_ALLOWED) return true;
                if (type == CellType.INTERIOR && value > MAX_INTERIOR_ALLOWED) return true;
            }
        }
        return false;
    }

    /**
     * Prints the optimized grid based on the cell types.
     */
    private static void printOptimizedGrid(int rows, int cols, PrintWriter out) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                CellType type = getCellType(i, j, rows, cols);
                switch (type) {
                    case CORNER:
                        out.print(VALUE_CORNER + " ");
                        break;
                    case EDGE:
                        out.print(VALUE_EDGE + " ");
                        break;
                    case INTERIOR:
                        out.print(VALUE_INTERIOR + " ");
                        break;
                }
            }
            out.println();
        }
    }

    /**
     * Determines whether a specific coordinate is a Corner, Edge, or Interior cell.
     */
    private static CellType getCellType(int r, int c, int rows, int cols) {
        boolean isRowBoundary = (r == 0 || r == rows - 1);
        boolean isColBoundary = (c == 0 || c == cols - 1);

        if (isRowBoundary && isColBoundary) {
            return CellType.CORNER;
        } else if (isRowBoundary || isColBoundary) {
            return CellType.EDGE;
        } else {
            return CellType.INTERIOR;
        }
    }

    /**
     * FastReader provides high-performance input reading using BufferedReader and StringTokenizer.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        /**
         * Helper to read a full 2D integer array.
         */
        public int[][] readIntMatrix(int rows, int cols) {
            int[][] matrix = new int[rows][cols];
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    matrix[i][j] = nextInt();
                }
            }
            return matrix;
        }
    }
}

