/**
 * Result carrier for grid processing operations.
 */
class GridResult {
    private final int[][] grid;
    private final boolean valid;

    public GridResult(int[][] grid, boolean valid) {
        this.grid = grid;
        this.valid = valid;
    }

    public int[][] getGrid() { return grid; }
    public boolean isValid() { return valid; }
}

/**
 * Contains the business logic for validating and transforming the grid.
 */
class GridSolver {
    private static final int CORNER_MAX_VAL = 2;
    private static final int EDGE_MAX_VAL = 3;
    private static final int INTERIOR_MAX_VAL = 4;

    /**
     * Processes the grid based on position-based capacity constraints.
     * 
     * @param grid The input grid.
     * @param n Rows.
     * @param m Columns.
     * @return A GridResult containing the transformed grid and success status.
     */
    public GridResult processGrid(int[][] grid, int n, int m) {
        boolean ok = true;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int maxAllowed = getCapacityAt(i, j, n, m);

                if (grid[i][j] > maxAllowed) {
                    ok = false;
                    break;
                } else {
                    grid[i][j] = maxAllowed;
                }
            }
            if (!ok) break;
        }

        return new GridResult(grid, ok);
    }

    private int getCapacityAt(int r, int c, int n, int m) {
        if (isCorner(r, c, n, m)) {
            return CORNER_MAX_VAL;
        } else if (isEdge(r, c, n, m)) {
            return EDGE_MAX_VAL;
        } else {
            return INTERIOR_MAX_VAL;
        }
    }

    private boolean isCorner(int r, int c, int n, int m) {
        return (r == 0 || r == n - 1) && (c == 0 || c == m - 1);
    }

    private boolean isEdge(int r, int c, int n, int m) {
        return (r == 0 || r == n - 1 || c == 0 || c == m - 1);
    }
}

/**
 * High-performance input reader for large data sets.
 */
class FastReader implements AutoCloseable {
    private final InputStream stream;
    private final byte[] buffer = new byte[1024];
    private int curChar;
    private int numChars;

    public FastReader(InputStream stream) {
        this.stream = stream;
    }

    private int read() {
        if (numChars == -1) throw new InputMismatchException();
        if (curChar >= numChars) {
            curChar = 0;
            try {
                numChars = stream.read(buffer);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (numChars <= 0) return -1;
        }
        return buffer[curChar++];
    }

    public int nextInt() {
        int c = read();
        while (isWhitespace(c)) c = read();
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        int res = 0;
        do {
            if (c < '0' || c > '9') throw new InputMismatchException();
            res = res * 10 + (c - '0');
            c = read();
        } while (!isWhitespace(c));
        return res * sgn;
    }

    public int[][] readGrid(int n, int m) {
        int[][] grid = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                grid[i][j] = nextInt();
            }
        }
        return grid;
    }

    private boolean isWhitespace(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    @Override
    public void close() throws IOException {
        stream.close();
    }
}

/**
 * High-performance output writer.
 */
class FastWriter implements AutoCloseable {
    private final PrintWriter writer;

    public FastWriter(OutputStream outputStream) {
        this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
    }

    public void println(String s) {
        writer.println(s);
    }

    public void printGrid(int[][] grid) {
        for (int[] row : grid) {
            for (int j = 0; j < row.length; j++) {
                writer.print(row[j]);
                if (j < row.length - 1) {
                    writer.print(" ");
                }
            }
            writer.println();
        }
    }

    @Override
    public void close() {
        writer.close();
    }
}

