/**
 * A utility to validate and transform a grid based on specific geometric constraints.
 * Corners are limited to 2, edges to 3, and interior cells to 4.
 */
public class GridPatternProcessor {

    private static final int CORNER_LIMIT = 2;
    private static final int EDGE_LIMIT = 3;
    private static final int INTERIOR_LIMIT = 4;

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;

            int testCases = scanner.nextInt();
            while (testCases-- > 0) {
                processTestCase(scanner);
            }
        }
    }

    /**
     * Orchestrates the logic for a single test case.
     */
    private static void processTestCase(Scanner scanner) {
        int rowCount = scanner.nextInt();
        int colCount = scanner.nextInt();
        long[][] grid = new long[rowCount][colCount];

        for (int i = 0; i < rowCount; i++) {
            for (int j = 0; j < colCount; j++) {
                grid[i][j] = scanner.nextLong();
            }
        }

        boolean isValid = validateAndTransformGrid(grid, rowCount, colCount);

        if (isValid) {
            System.out.println("YES");
            printGrid(grid);
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Validates if the grid values respect the geometric limits and 
     * transforms them to the maximum allowed value if they are within bounds.
     * 
     * @return true if the grid is valid according to the rules, false otherwise.
     */
    private static boolean validateAndTransformGrid(long[][] grid, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int limit = getRequiredLimit(i, j, rows, cols);

                if (grid[i][j] > limit) {
                    return false;
                }
                // Transform the value to the limit as per original requirement
                grid[i][j] = limit;
            }
        }
        return true;
    }

    /**
     * Determines the maximum allowed value for a cell based on its position.
     */
    private static int getRequiredLimit(int r, int c, int rows, int cols) {
        boolean isRowEdge = (r == 0 || r == rows - 1);
        boolean isColEdge = (c == 0 || c == cols - 1);

        if (isRowEdge && isColEdge) {
            return CORNER_LIMIT;
        } else if (isRowEdge || isColEdge) {
            return EDGE_LIMIT;
        } else {
            return INTERIOR_LIMIT;
        }
    }

    /**
     * Efficiently prints the grid using StringBuilder.
     */
    private static void printGrid(long[][] grid) {
        StringBuilder sb = new StringBuilder();
        for (long[] row : grid) {
            for (int j = 0; j < row.length; j++) {
                sb.append(row[j]);
                if (j < row.length - 1) {
                    sb.append(" ");
                }
            }
            sb.append("\n");
        }
        System.out.print(sb.toString());
    }
}

import java.util.Scanner;

/**
 * Solution class to process grid constraints.
 * The goal is to verify if a grid meets specific boundary constraints:
 * - Corners must be <= 2
 * - Edges must be <= 3
 * - Inner cells must be <= 4
 * If valid, the grid is transformed to these maximum allowed values.
 */
public class Solution {

    // Constants to replace "magic numbers" for better readability
    private static final int CORNER_LIMIT = 2;
    private static final int EDGE_LIMIT = 3;
    private static final int INNER_LIMIT = 4;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int testCases = scanner.nextInt();

        while (testCases-- > 0) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            int[][] grid = readGrid(scanner, rows, cols);

            GridResult result = processGrid(grid, rows, cols);
            printResult(result, rows, cols);
        }

        scanner.close();
    }

    /**
     * Reads the grid dimensions from the scanner.
     */
    private static int[][] readGrid(Scanner scanner, int rows, int cols) {
        int[][] grid = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                grid[i][j] = scanner.nextInt();
            }
        }
        return grid;
    }

    /**
     * Processes the grid by checking against constraints and applying transformations.
     * 
     * @param grid The input grid.
     * @param rows Number of rows.
     * @param cols Number of columns.
     * @return A GridResult object containing the validity and the modified grid.
     */
    private static GridResult processGrid(int[][] grid, int rows, int cols) {
        boolean isValid = true;

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int limit = getLimitForCell(i, j, rows, cols);

                if (grid[i][j] > limit) {
                    isValid = false;
                }
                // Transform the cell to its maximum allowed value
                grid[i][j] = limit;
            }
        }

        return new GridResult(isValid, grid);
    }

    /**
     * Determines the maximum allowed value for a cell based on its position.
     */
    private static int getLimitForCell(int r, int c, int rows, int cols) {
        boolean isCorner = (r == 0 || r == rows - 1) && (c == 0 || c == cols - 1);
        if (isCorner) {
            return CORNER_LIMIT;
        }

        boolean isEdge = (r == 0 || r == rows - 1 || c == 0 || c == cols - 1);
        if (isEdge) {
            return EDGE_LIMIT;
        }

        return INNER_LIMIT;
    }

    /**
     * Formats and prints the output for a single test case.
     */
    private static void printResult(GridResult result, int rows, int cols) {
        if (!result.isValid) {
            System.out.println("NO");
        } else {
            StringBuilder sb = new StringBuilder();
            sb.append("YES\n");
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    sb.append(result.grid[i][j]);
                    if (j < cols - 1) {
                        sb.append(" ");
                    }
                }
                sb.append("\n");
            }
            System.out.print(sb.toString());
        }
    }

    /**
     * Data carrier to hold the result of grid processing.
     */
    private static class GridResult {
        final boolean isValid;
        final int[][] grid;

        GridResult(boolean isValid, int[][] grid) {
            this.isValid = isValid;
            this.grid = grid;
        }
    }
}

