/**
 * A program that validates and transforms a grid based on cell position limits.
 * Corners are limited to 2, edges to 3, and interior cells to 4.
 */
public class GridProcessor {

    private static final int CORNER_LIMIT = 2;
    private static final int EDGE_LIMIT = 3;
    private static final int INTERIOR_LIMIT = 4;

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            int testCases = reader.nextInt();
            while (testCases-- > 0) {
                processTestCase(reader, writer);
            }
        } finally {
            writer.close();
        }
    }

    /**
     * Orchestrates the reading, validation, and printing for a single test case.
     */
    private static void processTestCase(FastReader reader, PrintWriter writer) {
        int rows = reader.nextInt();
        int cols = reader.nextInt();
        int[][] grid = readGrid(rows, cols, reader);

        if (!validateAndTransformGrid(grid, rows, cols)) {
            writer.println("NO");
        } else {
            writer.println("YES");
            printGrid(grid, writer);
        }
    }

    /**
     * Reads the grid dimensions and values from the input source.
     */
    private static int[][] readGrid(int rows, int cols, FastReader reader) {
        int[][] grid = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                grid[i][j] = reader.nextInt();
            }
        }
        return grid;
    }

    /**
     * Checks if every cell in the grid adheres to its positional limit.
     * If valid, it transforms the cell value to its maximum allowed limit.
     * 
     * @return true if all cells are valid, false otherwise.
     */
    private static boolean validateAndTransformGrid(int[][] grid, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int limit = getLimit(i, j, rows, cols);
                if (grid[i][j] > limit) {
                    return false;
                }
                grid[i][j] = limit;
            }
        }
        return true;
    }

    /**
     * Determines the maximum allowed value for a cell based on its coordinates.
     */
    private static int getLimit(int row, int col, int totalRows, int totalCols) {
        boolean isCorner = (row == 0 || row == totalRows - 1) && 
                           (col == 0 || col == totalCols - 1);
        if (isCorner) {
            return CORNER_LIMIT;
        }

        boolean isEdge = (row == 0 || row == totalRows - 1 || 
                          col == 0 || col == totalCols - 1);
        if (isEdge) {
            return EDGE_LIMIT;
        }

        return INTERIOR_LIMIT;
    }

    /**
     * Efficiently prints the grid to the output writer.
     */
    private static void printGrid(int[][] grid, PrintWriter writer) {
        StringBuilder sb = new StringBuilder();
        for (int[] row : grid) {
            for (int cell : row) {
                sb.append(cell).append(" ");
            }
            sb.append("\n");
        }
        writer.print(sb.toString());
    }

    /**
     * High-performance input reader for large datasets.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream inputStream) {
            br = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * MatrixProblemSolver handles the transformation of a grid based on cell positions.
 * Rules:
 * - Corner cells must be <= 2 (transformed to 2)
 * - Edge cells must be <= 3 (transformed to 3)
 * - Interior cells must be <= 4 (transformed to 4)
 */
public class MatrixProblemSolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        int testCases = reader.nextInt();
        while (testCases-- > 0) {
            solve(reader, writer);
        }

        writer.flush();
        writer.close();
    }

    /**
     * Orchestrates the logic for a single test case.
     */
    private static void solve(FastReader reader, PrintWriter writer) {
        int rows = reader.nextInt();
        int cols = reader.nextInt();
        int[][] grid = new int[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                grid[i][j] = reader.nextInt();
            }
        }

        if (tryTransformGrid(grid, rows, cols)) {
            writer.println("YES");
            printGrid(grid, rows, cols, writer);
        } else {
            writer.println("NO");
        }
    }

    /**
     * Validates and transforms the grid according to position-based rules.
     * 
     * @param grid The input matrix.
     * @param rows Number of rows.
     * @param cols Number of columns.
     * @return true if transformation is valid, false if any cell exceeds its limit.
     */
    private static boolean tryTransformGrid(int[][] grid, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int cellValue = grid[i][j];
                int limit = getTargetLimit(i, j, rows, cols);

                if (cellValue > limit) {
                    return false;
                }
                grid[i][j] = limit;
            }
        }
        return true;
    }

    /**
     * Returns the target value allowed for a specific cell position.
     */
    private static int getTargetLimit(int r, int c, int rows, int cols) {
        if (isCorner(r, c, rows, cols)) {
            return 2;
        } else if (isEdge(r, c, rows, cols)) {
            return 3;
        } else {
            return 4;
        }
    }

    private static boolean isCorner(int r, int c, int rows, int cols) {
        return (r == 0 || r == rows - 1) && (c == 0 || c == cols - 1);
    }

    private static boolean isEdge(int r, int c, int rows, int cols) {
        return (r == 0 || r == rows - 1 || c == 0 || c == cols - 1);
    }

    /**
     * Outputs the grid to the provided PrintWriter.
     */
    private static void printGrid(int[][] grid, int rows, int cols, PrintWriter writer) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                writer.print(grid[i][j]);
                if (j < cols - 1) {
                    writer.print(" ");
                }
            }
            writer.println();
        }
    }

    /**
     * Efficient input reader for competitive programming style inputs.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * GridConstraintSolver solves a problem where a grid must be transformed
 * based on specific constraints for corners, edges, and interior cells.
 */
public class GridConstraintSolver {

    // Constraints for cell values based on their position in the grid
    private static final int CORNER_LIMIT = 2;
    private static final int EDGE_LIMIT = 3;
    private static final int INTERIOR_LIMIT = 4;

    // Values assigned to cells in the output grid
    private static final int CORNER_VALUE = 2;
    private static final int EDGE_VALUE = 3;
    private static final int INTERIOR_VALUE = 4;

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int testCases = reader.nextInt();
            while (testCases-- > 0) {
                processTestCase(reader, writer);
            }
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Processes a single test case: reads grid dimensions, validates cell values,
     * and prints the resulting grid or "NO".
     */
    private static void processTestCase(FastReader reader, PrintWriter writer) throws IOException {
        int rowCount = reader.nextInt();
        int colCount = reader.nextInt();

        int[][] grid = new int[rowCount][colCount];
        boolean isValid = true;

        for (int r = 0; r < rowCount; r++) {
            for (int c = 0; c < colCount; c++) {
                int cellValue = reader.nextInt();

                if (isCorner(r, c, rowCount, colCount)) {
                    if (cellValue > CORNER_LIMIT) {
                        isValid = false;
                    }
                    grid[r][c] = CORNER_VALUE;
                } else if (isEdge(r, c, rowCount, colCount)) {
                    if (cellValue > EDGE_LIMIT) {
                        isValid = false;
                    }
                    grid[r][c] = EDGE_VALUE;
                } else {
                    if (cellValue > INTERIOR_LIMIT) {
                        isValid = false;
                    }
                    grid[r][c] = INTERIOR_VALUE;
                }
            }
        }

        if (isValid) {
            writer.println("YES");
            printGrid(grid, writer);
        } else {
            writer.println("NO");
        }
    }

    private static boolean isCorner(int r, int c, int rows, int cols) {
        return (r == 0 || r == rows - 1) && (c == 0 || c == cols - 1);
    }

    private static boolean isEdge(int r, int c, int rows, int cols) {
        return r == 0 || r == rows - 1 || c == 0 || c == cols - 1;
    }

    private static void printGrid(int[][] grid, PrintWriter writer) {
        for (int[] row : grid) {
            for (int j = 0; j < row.length; j++) {
                writer.print(row[j] + (j == row.length - 1 ? "" : " "));
            }
            writer.println();
        }
    }

    /**
     * FastReader class for efficient I/O operations.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }
}

