/**
 * MatrixGridSolution processes a grid of integers, validating them against 
 * specific boundary constraints:
 * - Corners must be <= 2
 * - Edges must be <= 3
 * - Interior cells must be <= 4
 * 
 * If valid, it outputs the matrix where values are normalized to their limits.
 */
public class MatrixGridSolution {

    private static final int CORNER_LIMIT = 2;
    private static final int EDGE_LIMIT = 3;
    private static final int INTERIOR_LIMIT = 4;

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        PrintWriter out = new PrintWriter(System.out);

        try {
            String tStr = reader.next();
            if (tStr != null) {
                int testCases = Integer.parseInt(tStr);
                while (testCases-- > 0) {
                    solve(reader, out);
                }
            }
        } catch (Exception e) {
            // Handle or log potential parsing errors
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Reads dimensions and matrix data for a single test case,
     * validates the constraints, and prints the result.
     */
    private static void solve(FastReader reader, PrintWriter out) {
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        int[][] matrix = new int[rows][cols];
        boolean isValid = true;

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int value = reader.nextInt();
                int limit = getLimit(i, j, rows, cols);

                if (value > limit) {
                    isValid = false;
                } else {
                    // The problem requirement dictates that if valid,
                    // values are set to the maximum allowed limit for that position.
                    matrix[i][j] = limit;
                }
            }
        }

        if (!isValid) {
            out.println("NO");
        } else {
            out.println("YES");
            printMatrix(matrix, out);
        }
    }

    /**
     * Determines the maximum allowed value for a cell based on its position.
     */
    private static int getLimit(int r, int c, int rows, int cols) {
        boolean isCorner = (r == 0 || r == rows - 1) && (c == 0 || c == cols - 1);
        if (isCorner) {
            return CORNER_LIMIT;
        }

        boolean isEdge = (r == 0 || r == rows - 1 || c == 0 || c == cols - 1);
        if (isEdge) {
            return EDGE_LIMIT;
        }

        return INTERIOR_LIMIT;
    }

    /**
     * Helper to print the matrix to the output stream.
     */
    private static void printMatrix(int[][] matrix, PrintWriter out) {
        for (int[] row : matrix) {
            for (int cell : row) {
                out.print(cell + " ");
            }
            out.println();
        }
    }

    /**
     * Fast I/O utility for efficient reading of large input datasets.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String next = next();
            return next != null ? Integer.parseInt(next) : 0;
        }

        public long nextLong() {
            String next = next();
            return next != null ? Long.parseLong(next) : 0L;
        }

        public double nextDouble() {
            String next = next();
            return next != null ? Double.parseDouble(next) : 0.0;
        }
    }
}

