/**
 * Main entry point for the Grid Neighbor Problem.
 */
public class Main {

    public static void main(String[] args) {
        // Use try-with-resources for automatic resource management of the output stream
        try (InputStream inputStream = System.in;
             PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)))) {

            FastReader reader = new FastReader(inputStream);
            GridSolver solver = new GridSolver(reader, out);

            solver.solve();

            out.flush();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * Encapsulates the business logic for processing grid-based test cases.
     */
    static class GridSolver {
        private final FastReader reader;
        private final PrintWriter out;

        public GridSolver(FastReader reader, PrintWriter out) {
            this.reader = reader;
            this.out = out;
        }

        /**
         * Orchestrates the execution of all test cases.
         */
        public void solve() {
            String tStr = reader.next();
            if (tStr == null) return;

            int testCases = Integer.parseInt(tStr);
            while (testCases-- > 0) {
                processTestCase();
            }
        }

        /**
         * Reads input, calculates neighbor counts, and validates constraints for a single case.
         */
        private void processTestCase() {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            int[][] inputGrid = readGrid(rows, cols);
            int[][] neighborGrid = new int[rows][cols];
            boolean isPossible = true;

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    int neighbors = countAdjacentCells(r, c, rows, cols);
                    neighborGrid[r][c] = neighbors;

                    // Check if the required value exceeds the available neighbors
                    if (inputGrid[r][c] > neighbors) {
                        isPossible = false;
                    }
                }
            }

            if (isPossible) {
                out.println("YES");
                printGrid(neighborGrid);
            } else {
                out.println("NO");
            }
        }

        private int[][] readGrid(int rows, int cols) {
            int[][] grid = new int[rows][cols];
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    grid[r][c] = reader.nextInt();
                }
            }
            return grid;
        }

        /**
         * Calculates the number of 4-connectivity neighbors for a cell at (r, c).
         */
        private int countAdjacentCells(int r, int c, int rows, int cols) {
            int count = 0;
            if (r > 0) count++;             // Top neighbor
            if (r < rows - 1) count++;      // Bottom neighbor
            if (c > 0) count++;             // Left neighbor
            if (c < cols - 1) count++;      // Right neighbor
            return count;
        }

        private void printGrid(int[][] grid) {
            StringBuilder sb = new StringBuilder();
            for (int[] row : grid) {
                sb.setLength(0);
                for (int i = 0; i < row.length; i++) {
                    sb.append(row[i]);
                    if (i < row.length - 1) {
                        sb.append(" ");
                    }
                }
                out.println(sb.toString());
            }
        }
    }

    /**
     * A fast input reader using BufferedReader and StringTokenizer for efficiency.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

