/**
 * A solution to determine if a grid can be transformed into a specific 
 * pattern of 2s (corners), 3s (edges), and 4s (interior) based on 
 * provided upper-bound constraints.
 */
public class GridValidator {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            String tStr = reader.next();
            if (tStr == null) return;

            int testCaseCount = Integer.parseInt(tStr);

            for (int t = 0; t < testCaseCount; t++) {
                solve(reader, out);
            }
        } catch (Exception e) {
            // In a real-world application, use a logger.
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Processes a single test case: reads the grid, validates constraints,
     * and prints either "NO" or "YES" followed by the transformed grid.
     */
    private static void solve(FastReader reader, PrintWriter out) {
        int rows = reader.nextInt();
        int cols = reader.nextInt();
        int[][] grid = new int[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                grid[i][j] = reader.nextInt();
            }
        }

        if (isValid(rows, cols, grid)) {
            out.println("YES");
            printTransformedGrid(rows, cols, out);
        } else {
            out.println("NO");
        }
    }

    /**
     * Validates if the grid satisfies the following:
     * - Corners: <= 2
     * - Edges: <= 3
     * - Interior: <= 4
     */
    private static boolean isValid(int rows, int cols, int[][] grid) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int value = grid[i][j];
                boolean isCorner = (i == 0 || i == rows - 1) && (j == 0 || j == cols - 1);
                boolean isEdge = (i == 0 || i == rows - 1 || j == 0 || j == cols - 1);

                if (isCorner) {
                    if (value > 2) return false;
                } else if (isEdge) {
                    if (value > 3) return false;
                } else {
                    if (value > 4) return false;
                }
            }
        }
        return true;
    }

    /**
     * Prints the grid transformed to the maximum allowed values:
     * 2 for corners, 3 for edges, and 4 for the interior.
     */
    private static void printTransformedGrid(int rows, int cols, PrintWriter out) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                boolean isCorner = (i == 0 || i == rows - 1) && (j == 0 || j == cols - 1);
                boolean isEdge = (i == 0 || i == rows - 1 || j == 0 || j == cols - 1);

                if (isCorner) {
                    sb.append(2);
                } else if (isEdge) {
                    sb.append(3);
                } else {
                    sb.append(4);
                }

                if (j < cols - 1) {
                    sb.append(" ");
                }
            }
            sb.append("\n");
        }
        out.print(sb.toString());
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

