/**
 * Contains the core logic for solving the grid imbalance problem.
 */
class GridSolver {

    private static final int MAX_ALLOWED_VALUE_SUM = 4;

    // Direction vectors for Up, Down, Left, Right traversal
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    private enum UpdateStatus {
        CHANGED,
        NO_CHANGE,
        INVALID_SOLUTION
    }

    private final int[][] grid;
    private final int rows;
    private final int cols;

    public GridSolver(int[][] grid) {
        this.grid = grid;
        this.rows = grid.length;
        this.cols = grid[0].length;
    }

    /**
     * Iteratively corrects the grid until no more changes are needed 
     * or an invalid state is detected.
     */
    public SolverResult solve() {
        boolean isCorrected;

        do {
            isCorrected = false;
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    UpdateStatus status = processCell(r, c);

                    if (status == UpdateStatus.INVALID_SOLUTION) {
                        return new SolverResult(false, null);
                    }
                    if (status == UpdateStatus.CHANGED) {
                        isCorrected = true;
                    }
                }
            }
        } while (isCorrected);

        return new SolverResult(true, grid);
    }

    /**
     * Checks the validity of a cell and applies corrections based on neighbor values.
     */
    private UpdateStatus processCell(int r, int c) {
        int currentValue = grid[r][c];

        // 1. Check if the current cell violates the edge/value constraint
        if (currentValue + countEdgeTouches(r, c) > MAX_ALLOWED_VALUE_SUM) {
            return UpdateStatus.INVALID_SOLUTION;
        }

        // 2. Calculate imbalance: difference between cell value and non-zero neighbors
        int nonZeroNeighbors = countNonZeroNeighbors(r, c);
        int imbalance = currentValue - nonZeroNeighbors;

        // 3. Handle Negative Imbalance (Cell value is too low relative to neighbors)
        if (imbalance < 0) {
            // Condition preserved from original: only change if not -1 or if cell is non-zero
            if (imbalance != -1 || currentValue != 0) {
                grid[r][c] -= imbalance;
                return UpdateStatus.CHANGED;
            }
        } 
        // 4. Handle Positive Imbalance (Cell value is too high, requires more neighbors)
        else if (imbalance > 0) {
            return distributeValueToNeighbors(r, c, imbalance);
        }

        return UpdateStatus.NO_CHANGE;
    }

    private int countEdgeTouches(int r, int c) {
        int touches = 0;
        if (r == 0 || r == rows - 1) touches++;
        if (c == 0 || c == cols - 1) touches++;
        return touches;
    }

    private int countNonZeroNeighbors(int r, int c) {
        int count = 0;
        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];
            if (isInBounds(nr, nc) && grid[nr][nc] > 0) {
                count++;
            }
        }
        return count;
    }

    private UpdateStatus distributeValueToNeighbors(int r, int c, int imbalance) {
        boolean changed = false;
        int remainingToDistribute = imbalance;

        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];

            if (isInBounds(nr, nc) && grid[nr][nc] == 0) {
                grid[nr][nc]++;
                changed = true;
                remainingToDistribute--;

                // If we've satisfied the cell's requirement, stop
                if (remainingToDistribute == 0) {
                    break;
                }
            }
        }
        return changed ? UpdateStatus.CHANGED : UpdateStatus.NO_CHANGE;
    }

    private boolean isInBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

import java.util.*;
import java.io.*;

/**
 * A solver for the Grid Problem.
 * The goal is to validate if a given grid meets specific boundary and interior constraints,
 * and if so, output a standardized grid of values (2 for corners, 3 for edges, 4 for interior).
 */
public class Main {

    public static void main(String[] args) {
        InputReader reader = new InputReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        int testCases = reader.nextInt();
        GridProblemSolver solver = new GridProblemSolver();

        while (testCases-- > 0) {
            solver.solve(reader, writer);
        }

        writer.flush();
        writer.close();
    }

    /**
     * Contains the core logic for validating and solving the grid constraints.
     */
    static class GridProblemSolver {

        /**
         * Orchestrates the validation and printing for a single test case.
         */
        public void solve(InputReader reader, PrintWriter writer) {
            int height = reader.nextInt();
            int width = reader.nextInt();

            int[][] grid = new int[width][height];
            for (int y = 0; y < height; y++) {
                for (int x = 0; x < width; x++) {
                    grid[x][y] = reader.nextInt();
                }
            }

            if (isGridValid(grid, width, height)) {
                writer.println("YES");
                printStandardizedGrid(writer, width, height);
            } else {
                writer.println("NO");
            }
        }

        /**
         * Validates the grid against the following constraints:
         * - Corner cells must be <= 2
         * - Edge cells must be <= 3
         * - Interior cells must be <= 4
         */
        private boolean isGridValid(int[][] grid, int width, int height) {
            for (int x = 0; x < width; x++) {
                for (int y = 0; y < height; y++) {
                    int value = grid[x][y];

                    // Constraint: No cell can exceed 4
                    if (value > 4) {
                        return false;
                    }

                    boolean isCorner = (x == 0 || x == width - 1) && (y == 0 || y == height - 1);
                    boolean isEdge = (x == 0 || x == width - 1 || y == 0 || y == height - 1);

                    // Constraint: Corner cells must be <= 2
                    if (isCorner && value > 2) {
                        return false;
                    }

                    // Constraint: Edge cells must be <= 3
                    if (isEdge && value > 3) {
                        return false;
                    }
                }
            }
            return true;
        }

        /**
         * Prints the required standardized grid:
         * Corners: 2, Edges: 3, Interior: 4
         */
        private void printStandardizedGrid(PrintWriter writer, int width, int height) {
            for (int y = 0; y < height; y++) {
                for (int x = 0; x < width; x++) {
                    int value = 4;
                    if (x == 0 || x == width - 1) {
                        value--;
                    }
                    if (y == 0 || y == height - 1) {
                        value--;
                    }
                    writer.print(value + (x == width - 1 ? "" : " "));
                }
                writer.println();
            }
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
