import java.io.*;
import java.util.*;

/**
 * A solution to the Grid Degree problem.
 * The logic checks if each cell's value is within the bounds of its possible neighbors,
 * transforms the grid, and fills zero-value cells based on non-zero neighbors.
 */
public class GlobalRound9B {

    public static void main(String[] args) {
        // Using a thread with a larger stack size to handle potential deep recursion 
        // or high-memory requirements, common in competitive programming.
        Thread solverThread = new Thread(null, () -> {
            try (FastReader reader = new FastReader(System.in);
                 PrintWriter writer = new PrintWriter(new BufferedOutputStream(System.out))) {

                GridSolver solver = new GridSolver(reader, writer);
                solver.solve();

            } catch (Exception e) {
                e.printStackTrace();
                System.exit(1);
            }
        }, "SolverThread", 1 << 27);

        solverThread.start();
    }

    /**
     * Contains the core business logic for processing the grid.
     */
    static class GridSolver {
        private static final int[][] DIRECTIONS = {
            {-1, 0}, {1, 0}, {0, -1}, {0, 1}
        };

        private final FastReader reader;
        private final PrintWriter writer;

        public GridSolver(FastReader reader, PrintWriter writer) {
            this.reader = reader;
            this.writer = writer;
        }

        public void solve() throws IOException {
            int testCases = reader.nextInt();
            while (testCases-- > 0) {
                processTestCase();
            }
        }

        private void processTestCase() throws IOException {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            int[][] matrix = new int[rows][cols];

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    matrix[i][j] = reader.nextInt();
                }
            }

            boolean isValid = validateAndTransform(matrix, rows, cols);

            if (!isValid) {
                writer.println("NO");
                return;
            }

            fillZeroCells(matrix, rows, cols);

            writer.println("YES");
            printMatrix(matrix, rows, cols);
        }

        /**
         * Pass 1: Checks if input grid[i][j] > possible neighbors.
         * If valid, transforms the grid cell to the maximum possible neighbor count.
         */
        private boolean validateAndTransform(int[][] matrix, int rows, int cols) {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    int neighborCount = countNeighbors(i, j, rows, cols);
                    if (matrix[i][j] > neighborCount) {
                        return false;
                    }
                    matrix[i][j] = neighborCount;
                }
            }
            return true;
        }

        /**
         * Pass 2: For cells that are 0, fills them with the count of non-zero neighbors.
         */
        private void fillZeroCells(int[][] matrix, int rows, int cols) {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (matrix[i][j] == 0) {
                        matrix[i][j] = countNonZeroNeighbors(matrix, i, j, rows, cols);
                    }
                }
            }
        }

        private int countNeighbors(int r, int c, int rows, int cols) {
            int count = 0;
            for (int[] dir : DIRECTIONS) {
                if (isWithinBounds(r + dir[0], c + dir[1], rows, cols)) {
                    count++;
                }
            }
            return count;
        }

        private int countNonZeroNeighbors(int[][] matrix, int r, int c, int rows, int cols) {
            int count = 0;
            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (isWithinBounds(nr, nc, rows, cols) && matrix[nr][nc] != 0) {
                    count++;
                }
            }
            return count;
        }

        private boolean isWithinBounds(int r, int c, int rows, int cols) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        private void printMatrix(int[][] matrix, int rows, int cols) {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    sb.append(matrix[i][j]).append(j == cols - 1 ? "" : " ");
                }
                sb.append("\n");
            }
            writer.print(sb.toString());
        }
    }

    /**
     * High-performance input reader.
     */
    static class FastReader implements AutoCloseable {
        private final InputStream inputStream;
        private final byte[] buffer = new byte[1024 * 16];
        private int pointer = 0;
        private int bufferLength = 0;

        public FastReader(InputStream inputStream) {
            this.inputStream = inputStream;
        }

        private byte read() throws IOException {
            if (pointer == bufferLength) {
                bufferLength = inputStream.read(buffer);
                pointer = 0;
                if (bufferLength == -1) return -1;
            }
            return buffer[pointer++];
        }

        public int nextInt() throws IOException {
            byte b = read();
            while (b != -1 && b <= 32) b = read();
            if (b == -1) return 0;

            boolean negative = false;
            if (b == '-') {
                negative = true;
                b = read();
            }

            int result = 0;
            while (b >= '0' && b <= '9') {
                result = result * 10 + (b - '0');
                b = read();
            }
            return negative ? -result : result;
        }

        @Override
        public void close() throws IOException {
            inputStream.close();
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A utility to validate if a grid's cell values are less than or equal 
 * to the number of their immediate neighbors (up, down, left, right).
 * If valid, it outputs the grid where each cell is replaced by its neighbor count.
 */
public class GridNeighborValidator {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int testCases = reader.nextInt();
            while (testCases-- > 0) {
                processTestCase(reader, out);
            }
        } catch (Exception e) {
            // In a production environment, use a logging framework
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Handles the logic for a single test case.
     */
    private static void processTestCase(FastReader reader, PrintWriter out) throws IOException {
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        int[][] grid = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                grid[i][j] = reader.nextInt();
            }
        }

        if (validateAndTransformGrid(grid, rows, cols)) {
            out.println("YES");
            printGrid(grid, rows, cols, out);
        } else {
            out.println("NO");
        }
    }

    /**
     * Validates that every cell in the grid is <= the number of its neighbors.
     * If valid, the grid is transformed in-place to store the neighbor counts.
     * 
     * @return true if all cells satisfy the condition, false otherwise.
     */
    private static boolean validateAndTransformGrid(int[][] grid, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int neighborCount = countNeighbors(i, j, rows, cols);

                if (grid[i][j] > neighborCount) {
                    return false;
                }
                // Update grid with neighbor count as per original logic
                grid[i][j] = neighborCount;
            }
        }
        return true;
    }

    /**
     * Calculates the number of neighbors for a cell at (r, c) in a grid of size (rows x cols).
     */
    private static int countNeighbors(int r, int c, int rows, int cols) {
        int count = 0;
        if (r > 0) count++;           // Up
        if (r < rows - 1) count++;    // Down
        if (c > 0) count++;           // Left
        if (c < cols - 1) count++;    // Right
        return count;
    }

    private static void printGrid(int[][] grid, int rows, int cols, PrintWriter out) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                out.print(grid[i][j]);
                if (j < cols - 1) {
                    out.print(" ");
                }
            }
            out.println();
        }
    }

    /**
     * Fast I/O Reader class for efficient parsing of large inputs.
     */
    static class FastReader {
        private final InputStream inputStream;
        private final byte[] buffer = new byte[1024];
        private int currentChar;
        private int numChars;

        public FastReader(InputStream is) {
            this.inputStream = is;
        }

        private int read() {
            if (numChars == -1) throw new InputMismatchException();
            if (currentChar >= numChars) {
                currentChar = 0;
                try {
                    numChars = inputStream.read(buffer);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) return -1;
            }
            return buffer[currentChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public long nextLong() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public String nextString() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Main class to orchestrate the grid processing application.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int testCases = reader.nextInt();
        GridSolver solver = new GridSolver();

        while (testCases-- > 0) {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            int[][] grid = new int[rows][cols];
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = reader.nextInt();
                }
            }

            GridResult result = solver.solve(grid);

            if (result.isSuccess()) {
                out.println("YES");
                printGrid(out, result.getGrid());
            } else {
                out.println("NO");
            }
        }
        out.flush();
        out.close();
    }

    /**
     * Helper method to print the grid with a trailing space per element,
     * matching the original implementation's format.
     */
    private static void printGrid(PrintWriter out, int[][] grid) {
        for (int[] row : grid) {
            for (int cell : row) {
                out.print(cell + " ");
            }
            out.println();
        }
    }

    /**
     * Logic handler for validating and transforming the grid.
     */
    static class GridSolver {
        private static final int CORNER_VAL = 2;
        private static final int BORDER_VAL = 3;
        private static final int INTERIOR_VAL = 4;

        /**
         * Processes the grid based on layer-based constraints.
         * @param grid The input 2D array.
         * @return A GridResult containing success status and the modified grid.
         */
        public GridResult solve(int[][] grid) {
            int rows = grid.length;
            int cols = grid[0].length;

            if (!processCorners(grid, rows, cols)) {
                return GridResult.fail();
            }

            if (!processVerticalBorders(grid, rows, cols)) {
                return GridResult.fail();
            }

            if (!processHorizontalBorders(grid, rows, cols)) {
                return GridResult.fail();
            }

            if (!processInterior(grid, rows, cols)) {
                return GridResult.fail();
            }

            return GridResult.success(grid);
        }

        private boolean processCorners(int[][] grid, int rows, int cols) {
            if (grid[0][0] > CORNER_VAL || 
                grid[rows - 1][cols - 1] > CORNER_VAL || 
                grid[rows - 1][0] > CORNER_VAL || 
                grid[0][cols - 1] > CORNER_VAL) {
                return false;
            }
            grid[0][0] = CORNER_VAL;
            grid[rows - 1][cols - 1] = CORNER_VAL;
            grid[rows - 1][0] = CORNER_VAL;
            grid[0][cols - 1] = CORNER_VAL;
            return true;
        }

        private boolean processVerticalBorders(int[][] grid, int rows, int cols) {
            for (int i = 1; i < rows - 1; i++) {
                if (grid[i][0] > BORDER_VAL || grid[i][cols - 1] > BORDER_VAL) {
                    return false;
                }
                grid[i][0] = BORDER_VAL;
                grid[i][cols - 1] = BORDER_VAL;
            }
            return true;
        }

        private boolean processHorizontalBorders(int[][] grid, int rows, int cols) {
            for (int j = 1; j < cols - 1; j++) {
                if (grid[0][j] > BORDER_VAL || grid[rows - 1][j] > BORDER_VAL) {
                    return false;
                }
                grid[0][j] = BORDER_VAL;
                grid[rows - 1][j] = BORDER_VAL;
            }
            return true;
        }

        private boolean processInterior(int[][] grid, int rows, int cols) {
            for (int i = 1; i < rows - 1; i++) {
                for (int j = 1; j < cols - 1; j++) {
                    if (grid[i][j] > INTERIOR_VAL) {
                        return false;
                    }
                    grid[i][j] = INTERIOR_VAL;
                }
            }
            return true;
        }
    }

    /**
     * Data Transfer Object to encapsulate the result of the solver.
     */
    static class GridResult {
        private final boolean success;
        private final int[][] grid;

        private GridResult(boolean success, int[][] grid) {
            this.success = success;
            this.grid = grid;
        }

        public static GridResult success(int[][] grid) {
            return new GridResult(true, grid);
        }

        public static GridResult fail() {
            return new GridResult(false, null);
        }

        public boolean isSuccess() {
            return success;
        }

        public int[][] getGrid() {
            return grid;
        }
    }

    /**
     * High-performance input reader.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * MatrixConstraintSolver processes matrices to ensure they meet specific 
 * boundary and interior constraints. 
 * 
 * Constraints:
 * - Corners must be <= 2 (transformed to 2)
 * - Edges must be <= 3 (transformed to 3)
 * - Interior elements must be <= 4 (transformed to 4)
 */
public class MatrixConstraintSolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        int testCases = reader.nextInt();

        while (testCases-- > 0) {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            int[][] matrix = reader.readIntMatrix(rows, cols);

            ValidationResult result = processMatrix(rows, cols, matrix);

            if (result.isValid()) {
                writer.println("YES");
                writer.println(formatMatrix(result.getMatrix()));
            } else {
                writer.println("NO");
            }
        }

        writer.flush();
        writer.close();
    }

    /**
     * Validates and transforms the matrix according to the rules.
     * 
     * @param n Number of rows
     * @param m Number of columns
     * @param matrix The input matrix
     * @return A ValidationResult containing success status and the modified matrix
     */
    private static ValidationResult processMatrix(int n, int m, int[][] matrix) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int limit = getLimitForPosition(i, j, n, m);

                if (matrix[i][j] > limit) {
                    return ValidationResult.failure();
                }
                // Transform the element to the required boundary/interior value
                matrix[i][j] = limit;
            }
        }
        return ValidationResult.success(matrix);
    }

    private static int getLimitForPosition(int i, int j, int n, int m) {
        if (isCorner(i, j, n, m)) {
            return 2;
        } else if (isEdge(i, j, n, m)) {
            return 3;
        } else {
            return 4;
        }
    }

    private static boolean isCorner(int i, int j, int n, int m) {
        return (i == 0 || i == n - 1) && (j == 0 || j == m - 1);
    }

    private static boolean isEdge(int i, int j, int n, int m) {
        return i == 0 || i == n - 1 || j == 0 || j == m - 1;
    }

    private static String formatMatrix(int[][] matrix) {
        StringBuilder sb = new StringBuilder();
        for (int[] row : matrix) {
            for (int val : row) {
                sb.append(val).append(" ");
            }
            sb.append("\n");
        }
        return sb.toString().trim();
    }

    /**
     * Data carrier for the result of matrix processing.
     */
    static class ValidationResult {
        private final boolean valid;
        private final int[][] matrix;

        private ValidationResult(boolean valid, int[][] matrix) {
            this.valid = valid;
            this.matrix = matrix;
        }

        public static ValidationResult success(int[][] matrix) {
            return new ValidationResult(true, matrix);
        }

        public static ValidationResult failure() {
            return new ValidationResult(false, null);
        }

        public boolean isValid() {
            return valid;
        }

        public int[][] getMatrix() {
            return matrix;
        }
    }

    /**
     * Optimized reader for fast I/O operations.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public int[][] readIntMatrix(int rows, int cols) {
            int[][] matrix = new int[rows][cols];
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    matrix[i][j] = nextInt();
                }
            }
            return matrix;
        }
    }
}

import java.util.Scanner;
import java.io.PrintWriter;

/**
 * Represents the core logic for processing a 2D grid based on cellular automaton rules.
 */
class GridProcessor {

    // Direction vectors for neighbors: Down, Right, Left, Up
    // The order is preserved from the original implementation to maintain behavior.
    private static final int[][] DIRECTIONS = {
        {1, 0},  // Down
        {0, 1},  // Right
        {0, -1}, // Left
        {-1, 0}  // Up
    };

    /**
     * Updates the grid based on the neighbor-based redistribution rules.
     * 
     * @param grid The 2D grid to process.
     * @param rows The number of rows in the grid.
     * @param cols The number of columns in the grid.
     * @return The updated grid, or an empty array if the process fails.
     */
    public int[][] updateGrid(int[][] grid, int rows, int cols) {
        // Pass 1: Validate cells and distribute surplus to adjacent zero-cells
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] > 0) {
                    if (!processCellSurplus(grid, r, c, rows, cols)) {
                        // Return an empty array to signal failure (matches original logic)
                        return new int[0][0];
                    }
                }
            }
        }

        // Pass 2: Finalize values by setting them to the count of active neighbors
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] > 0) {
                    int surplus = calculateSurplus(grid, r, c, rows, cols);
                    grid[r][c] -= surplus;
                }
            }
        }

        return grid;
    }

    /**
     * Determines if a cell's surplus can be distributed to neighboring zero-cells.
     */
    private boolean processCellSurplus(int[][] grid, int r, int c, int rows, int cols) {
        int surplus = calculateSurplus(grid, r, c, rows, cols);

        if (surplus > 4) {
            return false;
        }

        if (surplus < 0) {
            // If surplus is negative, increment the current cell by the absolute value
            grid[r][c] -= surplus;
            return true;
        }

        // Try to spend the positive surplus by turning adjacent 0-cells into 1-cells
        for (int[] dir : DIRECTIONS) {
            if (surplus <= 0) break;

            int nr = r + dir[0];
            int nc = c + dir[1];

            if (isWithinBounds(nr, nc, rows, cols) && grid[nr][nc] == 0) {
                grid[nr][nc] = 1;
                surplus--;
            }
        }

        return surplus == 0;
    }

    /**
     * Calculates the "surplus": current cell value minus the count of neighbors > 0.
     */
    private int calculateSurplus(int[][] grid, int r, int c, int rows, int cols) {
        int surplus = grid[r][c];
        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            if (isWithinBounds(nr, nc, rows, cols) && grid[nr][nc] > 0) {
                surplus--;
            }
        }
        return surplus;
    }

    private boolean isWithinBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

/**
 * Main entry point to handle I/O and orchestration.
 */
public class Grid {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        GridProcessor processor = new GridProcessor();

        if (!sc.hasNextInt()) {
            return;
        }

        int testCases = sc.nextInt();

        while (testCases-- > 0) {
            int rows = sc.nextInt();
            int cols = sc.nextInt();
            int[][] grid = new int[rows][cols];

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    grid[r][c] = sc.nextInt();
                }
            }

            int[][] result = processor.updateGrid(grid, rows, cols);

            if (result.length == 0) {
                out.println("NO");
            } else {
                out.println("YES");
                for (int r = 0; r < rows; r++) {
                    for (int c = 0; c < cols; c++) {
                        out.print(result[r][c]);
                        if (c < cols - 1) {
                            out.print(" ");
                        }
                    }
                    out.println();
                }
            }
        }

        out.flush();
        out.close();
        sc.close();
    }
}

