/**
 * The GridValidator class processes a grid of integers and determines if it 
 * adheres to specific boundary constraints. If valid, it outputs a "maximal" 
 * version of the grid.
 */
public class GridValidator {

    private static final int CORNER_MAX_VALUE = 2;
    private static final int EDGE_MAX_VALUE = 3;
    private static final int INTERIOR_MAX_VALUE = 4;

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            GridValidator validator = new GridValidator();
            validator.solve(reader, writer);
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Main logic loop that iterates through all test cases.
     */
    public void solve(FastReader reader, PrintWriter writer) throws IOException {
        int testCases = reader.nextInt();

        for (int t = 0; t < testCases; t++) {
            processTestCase(reader, writer);
        }
    }

    /**
     * Reads a single test case, validates the grid, and prints the result.
     */
    private void processTestCase(FastReader reader, PrintWriter writer) throws IOException {
        int rows = reader.nextInt();
        int cols = reader.nextInt();
        int[][] grid = new int[rows][cols];
        boolean isValid = true;

        // Read input and validate against constraints immediately
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                grid[r][c] = reader.nextInt();
                if (isValid && grid[r][c] > getMaxAllowedValue(r, c, rows, cols)) {
                    isValid = false;
                }
            }
        }

        if (!isValid) {
            writer.println("NO");
        } else {
            writer.println("YES");
            printMaximalGrid(grid, rows, cols, writer);
        }
    }

    /**
     * Determines the maximum allowed value for a cell based on its position.
     * Corners: 2, Edges: 3, Interior: 4.
     */
    private int getMaxAllowedValue(int r, int c, int rows, int cols) {
        boolean isRowEdge = (r == 0 || r == rows - 1);
        boolean isColEdge = (c == 0 || c == cols - 1);

        if (isRowEdge && isColEdge) {
            return CORNER_MAX_VALUE;
        } else if (isRowEdge || isColEdge) {
            return EDGE_MAX_VALUE;
        } else {
            return INTERIOR_MAX_VALUE;
        }
    }

    /**
     * Generates and prints the maximal valid grid.
     */
    private void printMaximalGrid(int[][] grid, int rows, int cols, PrintWriter writer) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                grid[r][c] = getMaxAllowedValue(r, c, rows, cols);
                writer.print(grid[r][c] + (c == cols - 1 ? "" : " "));
            }
            writer.println();
        }
    }

    /**
     * Fast I/O utility class for efficient reading.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
            tokenizer = null;
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        public double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }
}

