/**
 * A solution to the Neighbor Grid problem.
 * Determines if a given grid of values fits within the capacities of a grid
 * where corners have capacity 2, edges have 3, and interior cells have 4.
 */
public class B_Neighbor_Grid {

    // Constants representing the capacity of different cell types
    private static final int CORNER_CAPACITY = 2;
    private static final int EDGE_CAPACITY = 3;
    private static final int INTERIOR_CAPACITY = 4;

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int testCases = reader.nextInt();
        while (testCases-- > 0) {
            solve(reader, out);
        }
        out.flush();
        out.close();
    }

    /**
     * Processes a single test case.
     */
    private static void solve(FastReader reader, PrintWriter out) {
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        int[][] grid = new int[rows][cols];
        boolean isPossible = true;

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int inputValue = reader.nextInt();
                int capacity = getCellCapacity(i, j, rows, cols);

                grid[i][j] = capacity;

                // If any input value exceeds the capacity of its position, the grid is invalid
                if (inputValue > capacity) {
                    isPossible = false;
                }
            }
        }

        if (isPossible) {
            out.println("YES");
            printGrid(grid, out);
        } else {
            out.println("NO");
        }
    }

    /**
     * Determines the capacity of a cell based on its coordinates.
     * 
     * @param r Current row index
     * @param c Current column index
     * @param totalRows Total rows in the grid
     * @param totalCols Total columns in the grid
     * @return The capacity (2 for corner, 3 for edge, 4 for interior)
     */
    private static int getCellCapacity(int r, int c, int totalRows, int totalCols) {
        boolean isRowBoundary = (r == 0 || r == totalRows - 1);
        boolean isColBoundary = (c == 0 || c == totalCols - 1);

        if (isRowBoundary && isColBoundary) {
            return CORNER_CAPACITY;
        } else if (isRowBoundary || isColBoundary) {
            return EDGE_CAPACITY;
        } else {
            return INTERIOR_CAPACITY;
        }
    }

    /**
     * Prints the grid to the provided output stream.
     */
    private static void printGrid(int[][] grid, PrintWriter out) {
        for (int[] row : grid) {
            for (int j = 0; j < row.length; j++) {
                out.print(row[j] + (j == row.length - 1 ? "" : " "));
            }
            out.println();
        }
    }

    /**
     * Optimized reader for fast input processing.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
