/**
 * Logic for validating if a grid configuration is possible 
 * based on neighbor constraints.
 */
class GridValidator {
    private static final int CORNER_LIMIT = 2;
    private static final int EDGE_LIMIT = 3;
    private static final int INTERIOR_LIMIT = 4;

    /**
     * Validates the grid. A grid is valid if every cell's value is 
     * less than or equal to the number of its neighbors.
     *
     * @param inputGrid The original input grid.
     * @return A ValidationResult containing the status and the boundary grid.
     */
    public ValidationResult validate(int[][] inputGrid) {
        int rows = inputGrid.length;
        int cols = inputGrid[0].length;
        int[][] boundaryGrid = new int[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int limit = calculateMaxNeighbors(i, j, rows, cols);

                if (inputGrid[i][j] > limit) {
                    return new ValidationResult(false, null);
                }
                boundaryGrid[i][j] = limit;
            }
        }

        return new ValidationResult(true, boundaryGrid);
    }

    private int calculateMaxNeighbors(int row, int col, int totalRows, int totalCols) {
        boolean isRowEdge = (row == 0 || row == totalRows - 1);
        boolean isColEdge = (col == 0 || col == totalCols - 1);

        if (isRowEdge && isColEdge) {
            return CORNER_LIMIT;
        } else if (isRowEdge || isColEdge) {
            return EDGE_LIMIT;
        } else {
            return INTERIOR_LIMIT;
        }
    }
}

