/**
 * Handles the logic for validating and transforming the neighbor grid.
 */
class GridProcessor {
    private static final int CORNER_VALUE = 2;
    private static final int CORNER_LIMIT = 2;
    private static final int BOUNDARY_VALUE = 3;
    private static final int BOUNDARY_LIMIT = 3;
    private static final int INNER_VALUE = 4;
    private static final int INNER_LIMIT = 4;

    /**
     * Processes the input grid based on specific neighbor constraints.
     * 
     * @param matrix The input grid.
     * @param rows   Number of rows.
     * @param cols   Number of columns.
     * @return A GridResult containing success status and the new grid.
     */
    public GridResult process(int[][] matrix, int rows, int cols) {
        int[][] newMatrix = new int[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (isCorner(r, c, rows, cols)) {
                    if (matrix[r][c] > CORNER_LIMIT) {
                        return new GridResult(false, null);
                    }
                    newMatrix[r][c] = CORNER_VALUE;
                } else if (isBoundary(r, c, rows, cols)) {
                    if (matrix[r][c] > BOUNDARY_LIMIT) {
                        return new GridResult(false, null);
                    }
                    newMatrix[r][c] = BOUNDARY_VALUE;
                } else {
                    if (matrix[r][c] > INNER_LIMIT) {
                        return new GridResult(false, null);
                    }
                    newMatrix[r][c] = INNER_VALUE;
                }
            }
        }

        return new GridResult(true, newMatrix);
    }

    private boolean isCorner(int r, int c, int rows, int cols) {
        return (r == 0 || r == rows - 1) && (c == 0 || c == cols - 1);
    }

    private boolean isBoundary(int r, int c, int rows, int cols) {
        return r == 0 || r == rows - 1 || c == 0 || c == cols - 1;
    }
}

/**
 * Main entry point for the NeighborGrid application.
 */
public class NeighborGrid {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        GridProcessor processor = new GridProcessor();

        if (!scanner.hasNextInt()) return;

        int testCases = scanner.nextInt();

        while (testCases-- > 0) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            int[][] matrix = new int[rows][cols];

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    matrix[i][j] = scanner.nextInt();
                }
            }

            GridResult result = processor.process(matrix, rows, cols);
            printResult(result, rows, cols);
        }

        scanner.close();
    }

    /**
     * Formats and prints the result of the grid processing.
     */
    private static void printResult(GridResult result, int rows, int cols) {
        if (!result.isSuccess()) {
            System.out.println("NO");
            return;
        }

        StringBuilder sb = new StringBuilder();
        sb.append("YES\n");
        int[][] grid = result.getProcessedGrid();

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                sb.append(grid[i][j]);
                if (j < cols - 1) {
                    sb.append(" ");
                }
            }
            sb.append("\n");
        }
        System.out.print(sb.toString());
    }
}

