/**
 * Handles the logic of validating and transforming the grid based on cell positions.
 */
class GridTransformer {
    private static final int CORNER_LIMIT = 2;
    private static final int CORNER_VALUE = 2;

    private static final int EDGE_LIMIT = 3;
    private static final int EDGE_VALUE = 3;

    private static final int INNER_LIMIT = 4;
    private static final int INNER_VALUE = 4;

    private final int rows;
    private final int cols;
    private final int[][] transformedGrid;
    private boolean isValid;

    public GridTransformer(int rows, int cols) {
        this.rows = rows;
        this.cols = cols;
        this.transformedGrid = new int[rows][cols];
        this.isValid = true;
    }

    /**
     * Reads input from the FastReader and performs the transformation logic.
     * 
     * @param reader The utility to read input tokens.
     * @throws IOException if an I/O error occurs.
     */
    public void readAndProcess(FastReader reader) throws IOException {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int value = reader.nextInt();
                applyTransformation(i, j, value);
            }
        }
    }

    /**
     * Determines the cell type (corner, edge, or inner) and validates the input value.
     */
    private void applyTransformation(int r, int c, int value) {
        if (isCorner(r, c)) {
            validate(value, CORNER_LIMIT, CORNER_VALUE, r, c);
        } else if (isEdge(r, c)) {
            validate(value, EDGE_LIMIT, EDGE_VALUE, r, c);
        } else {
            validate(value, INNER_LIMIT, INNER_VALUE, r, c);
        }
    }

    private void validate(int value, int limit, int replacement, int r, int c) {
        if (value > limit) {
            isValid = false;
        } else {
            transformedGrid[r][c] = replacement;
        }
    }

    private boolean isCorner(int r, int c) {
        return (r == 0 || r == rows - 1) && (c == 0 || c == cols - 1);
    }

    private boolean isEdge(int r, int c) {
        return (r == 0 || r == rows - 1 || c == 0 || c == cols - 1);
    }

    public boolean isValid() {
        return isValid;
    }

    /**
     * Prints the transformed grid to the provided PrintWriter.
     */
    public void printGrid(PrintWriter writer) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                writer.print(transformedGrid[i][j]);
                if (j < cols - 1) {
                    writer.print(" ");
                }
            }
            writer.println();
        }
    }
}

