/**
 * A utility to validate and output a maximized grid based on specific 
 * positional constraints (corners, edges, and interior).
 */
public class GridConstraintSolver {

    private static final int CORNER_LIMIT = 2;
    private static final int EDGE_LIMIT = 3;
    private static final int INTERIOR_LIMIT = 4;

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int testCases = scanner.nextInt();
            for (int i = 0; i < testCases; i++) {
                processTestCase(scanner);
            }
        }
    }

    /**
     * Reads the input for a single test case and triggers the validation logic.
     */
    private static void processTestCase(Scanner scanner) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        int[][] grid = new int[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                grid[i][j] = scanner.nextInt();
            }
        }

        if (isValid(grid, rows, cols)) {
            System.out.println("YES");
            printMaximizedGrid(rows, cols);
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Validates if every cell in the grid satisfies the positional constraints.
     */
    private static boolean isValid(int[][] grid, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] > getLimitForCell(r, c, rows, cols)) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Determines the maximum allowed value for a cell based on its coordinates.
     * 
     * @param r Current row index
     * @param c Current column index
     * @param rows Total rows in grid
     * @param cols Total columns in grid
     * @return The limit allowed for this specific cell type
     */
    private static int getLimitForCell(int r, int c, int rows, int cols) {
        boolean isRowBoundary = (r == 0 || r == rows - 1);
        boolean isColBoundary = (c == 0 || c == cols - 1);

        if (isRowBoundary && isColBoundary) {
            return CORNER_LIMIT;
        } else if (isRowBoundary || isColBoundary) {
            return EDGE_LIMIT;
        } else {
            return INTERIOR_LIMIT;
        }
    }

    /**
     * Prints the grid containing the maximum possible values for each cell.
     */
    private static void printMaximizedGrid(int rows, int cols) {
        StringBuilder output = new StringBuilder();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                output.append(getLimitForCell(r, c, rows, cols))
                      .append(" ");
            }
            output.append("\n");
        }
        System.out.print(output.toString());
    }
}

import java.util.Scanner;

/**
 * A program to validate and transform a grid based on the number 
 * of adjacent neighbors for each cell.
 */
public class NeighborhoodGrid {

    private static final int CORNER_NEIGHBORS = 2;
    private static final int EDGE_NEIGHBORS = 3;
    private static final int INNER_NEIGHBORS = 4;

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;

            int testCaseCount = scanner.nextInt();

            for (int i = 0; i < testCaseCount; i++) {
                processTestCase(scanner);
            }
        }
    }

    /**
     * Reads grid dimensions and data, processes the grid, and prints the result.
     */
    private static void processTestCase(Scanner scanner) {
        int rowCount = scanner.nextInt();
        int colCount = scanner.nextInt();
        long[][] grid = new long[rowCount][colCount];

        for (int r = 0; r < rowCount; r++) {
            for (int c = 0; c < colCount; c++) {
                grid[r][c] = scanner.nextLong();
            }
        }

        if (tryTransformGrid(grid, rowCount, colCount)) {
            System.out.println("YES");
            printGrid(grid);
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Validates if the grid values can be transformed to match their neighbor capacity.
     * 
     * @return true if all cells can be updated, false if any cell exceeds its capacity.
     */
    private static boolean tryTransformGrid(long[][] grid, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int capacity = getNeighborCapacity(r, c, rows, cols);

                if (grid[r][c] > capacity) {
                    return false;
                }

                // Update the cell to its maximum possible neighbor capacity
                grid[r][c] = capacity;
            }
        }
        return true;
    }

    /**
     * Determines the number of neighbors a cell has based on its position.
     */
    private static int getNeighborCapacity(int r, int c, int rows, int cols) {
        boolean isCorner = (r == 0 || r == rows - 1) && (c == 0 || c == cols - 1);
        if (isCorner) {
            return CORNER_NEIGHBORS;
        }

        boolean isEdge = (r == 0 || r == rows - 1 || c == 0 || c == cols - 1);
        if (isEdge) {
            return EDGE_NEIGHBORS;
        }

        return INNER_NEIGHBORS;
    }

    /**
     * Prints the grid elements line by line.
     */
    private static void printGrid(long[][] grid) {
        for (long[] row : grid) {
            for (long value : row) {
                System.out.println(value);
            }
        }
    }
}

