    /**
     * Reads a single test case, processes the grid, and outputs the result.
     * 
     * @param scn The scanner instance for input.
     */
    private static void processTestCase(Scanner scn) {
        if (!scn.hasNextInt()) return;

        int rows = scn.nextInt();
        int cols = scn.nextInt();
        int[][] grid = new int[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                grid[i][j] = scn.nextInt();
            }
        }

        if (tryTransformGrid(grid, rows, cols)) {
            printGrid(grid);
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Validates if the grid values respect the positional limits and 
     * transforms them to the maximum allowed values.
     * 
     * @return true if the grid is valid, false otherwise.
     */
    private static boolean tryTransformGrid(int[][] grid, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int limit = getRequiredValue(i, j, rows, cols);

                if (grid[i][j] > limit) {
                    return false;
                }

                grid[i][j] = limit;
            }
        }
        return true;
    }

    /**
     * Determines the maximum allowed value for a cell based on its coordinates.
     * 
     * @param r Current row index.
     * @param c Current column index.
     * @param maxR Total number of rows.
     * @param maxC Total number of columns.
     * @return The limit (2 for corners, 3 for edges, 4 for interior).
     */
    private static int getRequiredValue(int r, int c, int maxR, int maxC) {
        boolean isRowEdge = (r == 0 || r == maxR - 1);
        boolean isColEdge = (c == 0 || c == maxC - 1);

        if (isRowEdge && isColEdge) {
            return CORNER_LIMIT;
        } else if (isRowEdge || isColEdge) {
            return EDGE_LIMIT;
        } else {
            return INTERIOR_LIMIT;
        }
    }

    /**
     * Prints the grid in the specified format.
     * 
     * @param grid The 2D array to print.
     */
    private static void printGrid(int[][] grid) {
        System.out.println("YES");
        StringBuilder sb = new StringBuilder();
        for (int[] row : grid) {
            for (int cell : row) {
                sb.append(cell).append(" ");
            }
            sb.append("\n");
        }
        System.out.print(sb.toString());
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to solve a grid constraint problem.
 * The objective is to ensure:
 * - Corners are at most 2.
 * - Edges (excluding corners) are at most 3.
 * - Interior cells are at most 4.
 * 
 * If the grid satisfies these conditions, it returns "YES" and the modified grid.
 * Otherwise, it returns "NO".
 */
public class GridConstraintSolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            String tStr = reader.next();
            if (tStr == null) return;
            int testCases = Integer.parseInt(tStr);

            while (testCases-- > 0) {
                int rows = reader.nextInt();
                int cols = reader.nextInt();
                int[][] grid = new int[rows][cols];

                for (int i = 0; i < rows; i++) {
                    for (int j = 0; j < cols; j++) {
                        grid[i][j] = reader.nextInt();
                    }
                }

                processGrid(grid, rows, cols, out);
            }
        } catch (Exception e) {
            // In a real-world scenario, use a logger
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Checks if the grid satisfies the constraints and modifies it if possible.
     * 
     * @param grid The input 2D array.
     * @param rows Number of rows.
     * @param cols Number of columns.
     * @param out PrintWriter for output.
     */
    private static void processGrid(int[][] grid, int rows, int cols, PrintWriter out) {
        boolean isPossible = true;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int limit = getLimit(r, c, rows, cols);

                if (grid[r][c] > limit) {
                    isPossible = false;
                    break;
                }
                // Update cell to its maximum allowed value
                grid[r][c] = limit;
            }
            if (!isPossible) {
                break;
            }
        }

        if (isPossible) {
            out.println("YES");
            printGrid(grid, rows, cols, out);
        } else {
            out.println("NO");
        }
    }

    /**
     * Determines the maximum allowed value for a cell based on its position.
     * 
     * @param r Current row index.
     * @param c Current column index.
     * @param rows Total rows in the grid.
     * @param cols Total columns in the grid.
     * @return The maximum allowed value (2 for corner, 3 for edge, 4 for interior).
     */
    private static int getLimit(int r, int c, int rows, int cols) {
        boolean isCorner = (r == 0 || r == rows - 1) && (c == 0 || c == cols - 1);
        if (isCorner) {
            return 2;
        }

        boolean isEdge = (r == 0 || r == rows - 1 || c == 0 || c == cols - 1);
        if (isEdge) {
            return 3;
        }

        return 4;
    }

    /**
     * Utility to print the grid.
     */
    private static void printGrid(int[][] grid, int rows, int cols, PrintWriter out) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                out.print(grid[r][c]);
                if (c < cols - 1) {
                    out.print(" ");
                }
            }
            out.println();
        }
    }

    /**
     * Fast I/O utility class for efficient reading.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        return null;
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            return next == null ? 0 : Integer.parseInt(next);
        }
    }
}

