/**
 * Refactored solution to validate and output a grid pattern based on cell positions.
 */
public class Main {

    private static final int CORNER_VALUE = 2;
    private static final int EDGE_VALUE = 3;
    private static final int INTERIOR_VALUE = 4;

    public static void main(String[] args) {
        FastReader sc = new FastReader();
        PrintWriter pw = new PrintWriter(System.out);

        try {
            int testCases = sc.nextInt();
            while (testCases-- > 0) {
                solve(sc, pw);
            }
        } catch (Exception e) {
            // In a competitive programming context, we typically don't catch exceptions,
            // but for maintainability, we ensure the stream closes.
        } finally {
            pw.flush();
            pw.close();
        }
    }

    /**
     * Processes a single test case.
     */
    private static void solve(FastReader sc, PrintWriter pw) throws IOException {
        int n = sc.nextInt();
        int m = sc.nextInt();
        long[][] grid = new long[n][m];
        boolean isValid = true;

        // Read input and validate against constraints simultaneously
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                grid[i][j] = sc.nextLong();
                if (isValid && grid[i][j] > getRequiredValue(i, j, n, m)) {
                    isValid = false;
                }
            }
        }

        if (!isValid) {
            pw.println("NO");
        } else {
            pw.println("YES");
            printPattern(pw, n, m);
        }
    }

    /**
     * Determines the maximum allowed value for a cell at (r, c) in an n x m grid.
     * 
     * @param r Row index
     * @param c Column index
     * @param rows Total rows
     * @param cols Total columns
     * @return The maximum allowed value (2 for corners, 3 for edges, 4 for interior)
     */
    private static int getRequiredValue(int r, int c, int rows, int cols) {
        boolean isCorner = (r == 0 || r == rows - 1) && (c == 0 || c == cols - 1);
        if (isCorner) {
            return CORNER_VALUE;
        }

        boolean isEdge = (r == 0 || r == rows - 1 || c == 0 || c == cols - 1);
        if (isEdge) {
            return EDGE_VALUE;
        }

        return INTERIOR_VALUE;
    }

    /**
     * Prints the required pattern for a valid grid.
     */
    private static void printPattern(PrintWriter pw, int n, int m) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                pw.print(getRequiredValue(i, j, n, m));
                if (j < m - 1) {
                    pw.print(" ");
                }
            }
            pw.println();
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
