/**
 * GridValidator processes a grid of integers to determine if each cell's 
 * value is less than or equal to the number of its adjacent neighbors.
 */
public class GridValidator {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int testCases = reader.nextInt();
            while (testCases-- > 0) {
                solve(reader, out);
            }
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Processes a single test case.
     * 
     * @param reader The fast input reader.
     * @param out    The fast output writer.
     * @throws IOException if an I/O error occurs.
     */
    private static void solve(FastReader reader, PrintWriter out) throws IOException {
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        int[][] inputGrid = new int[rows][cols];
        int[][] neighborCountGrid = new int[rows][cols];
        boolean isValid = true;

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                inputGrid[i][j] = reader.nextInt();
                int neighbors = countNeighbors(i, j, rows, cols);
                neighborCountGrid[i][j] = neighbors;

                // If the cell requirement exceeds the physical neighbors available, it's invalid
                if (inputGrid[i][j] > neighbors) {
                    isValid = false;
                }
            }
        }

        if (isValid) {
            out.println("YES");
            printMatrix(neighborCountGrid, out);
        } else {
            out.println("NO");
        }
    }

    /**
     * Calculates the number of adjacent cells (up, down, left, right) for a given cell.
     */
    private static int countNeighbors(int row, int col, int maxRows, int maxCols) {
        int count = 0;
        if (row > 0) count++;             // Up
        if (row < maxRows - 1) count++;   // Down
        if (col > 0) count++;             // Left
        if (col < maxCols - 1) count++;   // Right
        return count;
    }

    /**
     * Helper method to print a 2D array to the output stream.
     */
    private static void printMatrix(int[][] matrix, PrintWriter out) {
        for (int[] row : matrix) {
            for (int j = 0; j < row.length; j++) {
                out.print(row[j]);
                if (j < row.length - 1) {
                    out.print(" ");
                }
            }
            out.println();
        }
    }

    /**
     * FastReader class using BufferedReader and StringTokenizer for high-performance I/O.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) {
                    return null;
                }
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }
}

import java.util.Scanner;

/**
 * The GridValidator class provides functionality to validate a grid based on 
 * specific boundary constraints and generates a maximum-value grid if valid.
 */
public class GridValidator {

    private static final int MAX_CELL_VALUE = 4;
    private static final int MAX_EDGE_VALUE = 3;
    private static final int MAX_CORNER_VALUE = 2;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int testCases = scanner.nextInt();
        while (testCases-- > 0) {
            processTestCase(scanner);
        }

        scanner.close();
    }

    /**
     * Orchestrates the logic for a single test case.
     */
    private static void processTestCase(Scanner scanner) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        int[][] grid = new int[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                grid[i][j] = scanner.nextInt();
            }
        }

        if (isInputValid(grid, rows, cols)) {
            System.out.println("YES");
            System.out.println(generateMaximizedGrid(rows, cols));
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Validates the input grid against specific rules:
     * 1. No cell value can exceed 4.
     * 2. Corner cells cannot exceed 2.
     * 3. Edge cells (excluding corners) cannot exceed 3.
     */
    private static boolean isInputValid(int[][] grid, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int value = grid[r][c];

                // Rule 1: Global maximum check
                if (value > MAX_CELL_VALUE) {
                    return false;
                }

                boolean isCorner = isCorner(r, c, rows, cols);
                boolean isEdge = isEdge(r, c, rows, cols);

                // Rule 2: Corner constraint
                if (isCorner && value > MAX_CORNER_VALUE) {
                    return false;
                }

                // Rule 3: Edge constraint
                if (isEdge && value > MAX_EDGE_VALUE) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Generates a string representation of a grid where:
     * - Corners are 2
     * - Edges are 3
     * - Interior cells are 4
     */
    private static String generateMaximizedGrid(int rows, int cols) {
        StringBuilder sb = new StringBuilder();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int value = MAX_CELL_VALUE;

                if (isCorner(r, c, rows, cols)) {
                    value = MAX_CORNER_VALUE;
                } else if (isEdge(r, c, rows, cols)) {
                    value = MAX_EDGE_VALUE;
                }

                sb.append(value).append(" ");
            }
            sb.append("\n");
        }
        return sb.toString().trim();
    }

    private static boolean isCorner(int r, int c, int rows, int cols) {
        return (r == 0 || r == rows - 1) && (c == 0 || c == cols - 1);
    }

    private static boolean isEdge(int r, int c, int rows, int cols) {
        return (r == 0 || r == rows - 1 || c == 0 || c == cols - 1);
    }
}

import java.io.*;
import java.util.*;

/**
 * A utility class for high-performance input reading.
 * Encapsulates the byte-level reading logic to keep the main logic clean.
 */
class FastReader {
    private final InputStream inputStream;
    private final byte[] buffer = new byte[1024];
    private int pointer = 0;
    private int bytesRead = 0;

    public FastReader(InputStream inputStream) {
        this.inputStream = inputStream;
    }

    private int readByte() {
        if (pointer >= bytesRead) {
            pointer = 0;
            try {
                bytesRead = inputStream.read(buffer);
            } catch (IOException e) {
                return -1;
            }
            if (bytesRead <= 0) return -1;
        }
        return buffer[pointer++] & 0xFF;
    }

    public int nextInt() {
        int c = readByte();
        while (c != -1 && c <= 32) c = readByte();
        if (c == -1) return 0;

        boolean negative = false;
        if (c == '-') {
            negative = true;
            c = readByte();
        }

        int res = 0;
        while (c >= '0' && c <= '9') {
            res = res * 10 + (c - '0');
            c = readByte();
        }
        return negative ? -res : res;
    }

    public long nextLong() {
        int c = readByte();
        while (c != -1 && c <= 32) c = readByte();
        if (c == -1) return 0L;

        boolean negative = false;
        if (c == '-') {
            negative = true;
            c = readByte();
        }

        long res = 0;
        while (c >= '0' && c <= '9') {
            res = res * 10 + (c - '0');
            c = readByte();
        }
        return negative ? -res : res;
    }
}

/**
 * Contains the core logic for the grid neighbor-count problem.
 */
class GridProblemSolver {
    // Directions for adjacent cells: Up, Down, Left, Right
    private static final int[] DX = {-1, 1, 0, 0};
    private static final int[] DY = {0, 0, -1, 1};

    private final FastReader reader;
    private final PrintWriter writer;

    public GridProblemSolver(FastReader reader, PrintWriter writer) {
        this.reader = reader;
        this.writer = writer;
    }

    public void solve() {
        int testCases = reader.nextInt();
        while (testCases-- > 0) {
            processTestCase();
        }
    }

    private void processTestCase() {
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        int[][] requirementMatrix = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                requirementMatrix[i][j] = reader.nextInt();
            }
        }

        int[][] neighborCountMatrix = calculateNeighborCountMatrix(rows, cols);

        if (isValid(requirementMatrix, neighborCountMatrix)) {
            writer.println("YES");
            printMatrix(neighborCountMatrix);
        } else {
            writer.println("NO");
        }
    }

    /**
     * Calculates a matrix where each cell contains the count of its adjacent neighbors.
     */
    private int[][] calculateNeighborCountMatrix(int rows, int cols) {
        int[][] counts = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int neighbors = 0;
                for (int i = 0; i < 4; i++) {
                    int nr = r + DX[i];
                    int nc = c + DY[i];
                    if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
                        neighbors++;
                    }
                }
                counts[r][c] = neighbors;
            }
        }
        return counts;
    }

    private boolean isValid(int[][] requirements, int[][] actual) {
        for (int i = 0; i < requirements.length; i++) {
            for (int j = 0; j < requirements[0].length; j++) {
                if (actual[i][j] < requirements[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    private void printMatrix(int[][] matrix) {
        StringBuilder sb = new StringBuilder();
        for (int[] row : matrix) {
            for (int val : row) {
                sb.append(val).append(" ");
            }
        }
        writer.println(sb.toString().trim());
    }
}

/**
 * Entry point of the application.
 */
public class Main {
    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        // Using try-with-resources for automatic flushing and closing of the PrintWriter
        try (PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)))) {
            GridProblemSolver solver = new GridProblemSolver(reader, writer);
            solver.solve();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}

import java.util.Scanner;

/**
 * A program that transforms a matrix based on specific boundary and interior constraints.
 * Corners must be < 3 (set to 2), edges < 4 (set to 3), and interior < 5 (set to 4).
 */
public class MatrixTransformationApp {

    // Constants to eliminate "magic numbers" and improve readability
    private static final int CORNER_TARGET = 2;
    private static final int CORNER_MAX_ALLOWED = 3;
    private static final int EDGE_TARGET = 3;
    private static final int EDGE_MAX_ALLOWED = 4;
    private static final int INTERIOR_TARGET = 4;
    private static final int INTERIOR_MAX_ALLOWED = 5;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int testCases = scanner.nextInt();
        for (int i = 0; i < testCases; i++) {
            solve(scanner);
        }

        scanner.close();
    }

    /**
     * Handles the lifecycle of a single test case.
     */
    private static void solve(Scanner scanner) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        int[][] grid = new int[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                grid[r][c] = scanner.nextInt();
            }
        }

        TransformationResult result = MatrixTransformer.transform(grid);

        if (result.isSuccess()) {
            System.out.println("YES");
            System.out.print(formatGrid(result.getGrid()));
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Converts the 2D array into a single string for efficient printing.
     */
    private static String formatGrid(int[][] grid) {
        StringBuilder sb = new StringBuilder();
        for (int[] row : grid) {
            for (int cell : row) {
                sb.append(cell).append(" ");
            }
            sb.append("\n");
        }
        return sb.toString();
    }

    /**
     * Logic engine for transforming the matrix.
     */
    static class MatrixTransformer {

        /**
         * Transforms the grid if all constraints are met.
         * @param grid The input matrix.
         * @return A TransformationResult containing success status and the modified grid.
         */
        public static TransformationResult transform(int[][] grid) {
            int rows = grid.length;
            int cols = grid[0].length;

            // We iterate through the grid once, determining the role of each cell by its coordinates.
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (isCorner(r, c, rows, cols)) {
                        if (grid[r][c] >= CORNER_MAX_ALLOWED) {
                            return TransformationResult.failure();
                        }
                        grid[r][c] = CORNER_TARGET;
                    } else if (isEdge(r, c, rows, cols)) {
                        if (grid[r][c] >= EDGE_MAX_ALLOWED) {
                            return TransformationResult.failure();
                        }
                        grid[r][c] = EDGE_TARGET;
                    } else {
                        if (grid[r][c] >= INTERIOR_MAX_ALLOWED) {
                            return TransformationResult.failure();
                        }
                        grid[r][c] = INTERIOR_TARGET;
                    }
                }
            }
            return TransformationResult.success(grid);
        }

        private static boolean isCorner(int r, int c, int rows, int cols) {
            return (r == 0 || r == rows - 1) && (c == 0 || c == cols - 1);
        }

        private static boolean isEdge(int r, int c, int rows, int cols) {
            return (r == 0 || r == rows - 1 || c == 0 || c == cols - 1);
        }
    }

    /**
     * Data transfer object to hold the result of a transformation attempt.
     */
    static class TransformationResult {
        private final boolean success;
        private final int[][] grid;

        private TransformationResult(boolean success, int[][] grid) {
            this.success = success;
            this.grid = grid;
        }

        public static TransformationResult success(int[][] grid) {
            return new TransformationResult(true, grid);
        }

        public static TransformationResult failure() {
            return new TransformationResult(false, null);
