/**
 * Logic handler for the Grid Transformation problem.
 */
class GridTransformer {
    private final int rows;
    private final int cols;
    private final int[][] grid;

    public GridTransformer(int rows, int cols, int[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
    }

    /**
     * Result object to hold transformation outcome.
     */
    public static class Result {
        public final boolean success;
        public final int[][] transformedGrid;

        public Result(boolean success, int[][] transformedGrid) {
            this.success = success;
            this.transformedGrid = transformedGrid;
        }
    }

    /**
     * Attempts to transform the grid into the target pattern:
     * Corners = 2, Edges = 3, Interior = 4.
     * Transformation is only possible if original value <= target value.
     */
    public Result transform() {
        int[][] targetGrid = new int[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int targetValue = getTargetValue(i, j);

                // If the current value is already greater than the required 
                // target, the transformation is impossible.
                if (grid[i][j] > targetValue) {
                    return new Result(false, null);
                }
                targetGrid[i][j] = targetValue;
            }
        }

        return new Result(true, targetGrid);
    }

    private int getTargetValue(int r, int c) {
        boolean isRowEdge = (r == 0 || r == rows - 1);
        boolean isColEdge = (c == 0 || c == cols - 1);

        if (isRowEdge && isColEdge) {
            return 2; // Corner
        } else if (isRowEdge || isColEdge) {
            return 3; // Boundary
        } else {
            return 4; // Interior
        }
    }
}

public class Main {
    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            String testCasesStr = reader.next();
            if (testCasesStr == null) return;
            int testCases = Integer.parseInt(testCasesStr);

            while (testCases-- > 0) {
                int n = reader.nextInt();
                int m = reader.nextInt();
                int[][] grid = new int[n][m];

                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < m; j++) {
                        grid[i][j] = reader.nextInt();
                    }
                }

                processTestCase(n, m, grid, writer);
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    private static void processTestCase(int n, int m, int[][] grid, PrintWriter writer) {
        GridTransformer transformer = new GridTransformer(n, m, grid);
        GridTransformer.Result result = transformer.transform();

        if (result.success) {
            writer.println("YES");
            printGrid(result.transformedGrid, writer);
        } else {
            writer.println("NO");
        }
    }

    private static void printGrid(int[][] grid, PrintWriter writer) {
        for (int[] row : grid) {
            for (int i = 0; i < row.length; i++) {
