/**
 * The Main class serves as the entry point for the application.
 * It orchestrates the high-level flow: reading the number of test cases,
 * invoking the solver, and managing I/O streams.
 */
public class Main {
    public static void main(String[] args) {
        // Using try-with-resources to ensure streams are closed properly.
        try (InputStream inputStream = System.in;
             PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)))) {

            InputReader in = new InputReader(inputStream);
            GridSolver solver = new GridSolver();

            solver.solve(in, out);
            out.flush();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * GridSolver contains the core business logic for validating 
     * and constructing the neighbor grid.
     */
    static class GridSolver {
        private static final int CORNER_VALUE = 2;
        private static final int EDGE_VALUE = 3;
        private static final int INTERIOR_VALUE = 4;

        /**
         * Iterates through all test cases provided in the input.
         */
        public void solve(InputReader in, PrintWriter out) {
            int testCases = in.nextInt();
            while (testCases-- > 0) {
                int rows = in.nextInt();
                int cols = in.nextInt();
                int[][] board = readBoard(in, rows, cols);

                GridResult result = validateAndConstruct(rows, cols, board);

                if (result.isPossible()) {
                    out.println("YES");
                    printGrid(result.getGrid(), out);
                } else {
                    out.println("NO");
                }
            }
        }

        private int[][] readBoard(InputReader in, int rows, int cols) {
            int[][] board = new int[rows][cols];
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    board[i][j] = in.nextInt();
                }
            }
            return board;
        }

        /**
         * Validates the input board against the rules and constructs 
         * the target grid if valid.
         */
        private GridResult validateAndConstruct(int rows, int cols, int[][] board) {
            // First pass: Validate if the current board meets the threshold requirements.
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    int maxAllowed = getMaxAllowedValue(i, j, rows, cols);
                    if (board[i][j] > maxAllowed) {
                        return GridResult.failure();
                    }
                }
            }

            // Second pass: Construct the optimized grid.
            return GridResult.success(constructGrid(rows, cols));
        }

        private int getMaxAllowedValue(int r, int c, int rows, int cols) {
            if (isCorner(r, c, rows, cols)) {
                return CORNER_VALUE;
            } else if (isEdge(r, c, rows, cols)) {
                return EDGE_VALUE;
            } else {
                return INTERIOR_VALUE;
            }
        }

        private boolean isCorner(int r, int c, int rows, int cols) {
            return (r == 0 || r == rows - 1) && (c == 0 || c == cols - 1);
        }

        private boolean isEdge(int r, int c, int rows, int cols) {
            return (r == 0 || r == rows - 1 || c == 0 || c == cols - 1);
        }

        private int[][] constructGrid(int rows, int cols) {
            int[][] grid = new int[rows][cols];
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (isCorner(i, j, rows, cols)) {
                        grid[i][j] = CORNER_VALUE;
                    } else if (isEdge(i, j, rows, cols)) {
                        grid[i][j] = EDGE_VALUE;
                    } else {
                        grid[i][j] = INTERIOR_VALUE;
                    }
                }
            }
            return grid;
        }

        private void printGrid(int[][] grid, PrintWriter out) {
            for (int[] row : grid) {
                for (int value : row) {
                    out.println(value);
                }
            }
        }
    }

    /**
     * Data Transfer Object representing the result of the grid processing.
     */
    static class GridResult {
        private final boolean possible;
        private final int[][] grid;

        private GridResult(boolean possible, int[][] grid) {
            this.possible = possible;
            this.grid = grid;
        }

        public static GridResult success(int[][] grid) {
            return new GridResult(true, grid);
        }

        public static GridResult failure() {
            return new GridResult(false, null);
        }

        public boolean isPossible() {
            return possible;
        }

        public int[][] getGrid() {
            return grid;
        }
    }

    /**
     * Optimized reader for fast input processing.
     */
    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            if (next == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(next);
        }
    }
