/**
 * A solution to solve the grid constraint problem.
 * The problem requires verifying if a grid's elements meet specific limits:
 * - Corners: max 2
 * - Edges (Sides): max 3
 * - Middle: max 4
 * If valid, the grid is transformed into its maximum possible values.
 */
public class Codeforces {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int testCases = reader.nextInt();
            GridSolver solver = new GridSolver();

            while (testCases-- > 0) {
                solver.solve(reader, writer);
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Contains the business logic for processing the grid.
     */
    static class GridSolver {
        private static final int CORNER_LIMIT = 2;
        private static final int SIDE_LIMIT = 3;
        private static final int MIDDLE_LIMIT = 4;

        /**
         * Processes a single test case.
         * 
         * @param reader The input reader.
         * @param writer The output writer.
         */
        public void solve(FastReader reader, PrintWriter writer) {
            int rowCount = reader.nextInt();
            int colCount = reader.nextInt();

            int[][] grid = new int[rowCount][colCount];
            boolean isValid = true;

            for (int i = 0; i < rowCount; i++) {
                for (int j = 0; j < colCount; j++) {
                    int currentValue = reader.nextInt();
                    int requiredValue = getRequiredValue(i, j, rowCount, colCount);

                    if (currentValue > requiredValue) {
                        isValid = false;
                    }
                    // We store the required value as per the problem's requirement for "YES" output
                    grid[i][j] = requiredValue;
                }
            }

            if (isValid) {
                writer.println("YES");
                printGrid(grid, writer);
            } else {
                writer.println("NO");
            }
        }

        /**
         * Determines the required cell value based on its position.
         */
        private int getRequiredValue(int r, int c, int rows, int cols) {
            boolean isCorner = (r == 0 || r == rows - 1) && (c == 0 || c == cols - 1);
            if (isCorner) {
                return CORNER_LIMIT;
            }

            boolean isEdge = (r == 0 || r == rows - 1 || c == 0 || c == cols - 1);
            if (isEdge) {
                return SIDE_LIMIT;
            }

            return MIDDLE_LIMIT;
        }

        private void printGrid(int[][] grid, PrintWriter writer) {
            for (int[] row : grid) {
                for (int j = 0; j < row.length; j++) {
                    writer.print(row[j] + (j == row.length - 1 ? "" : " "));
                }
                writer.println();
            }
        }
    }

    /**
     * Optimized reader for fast I/O operations.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

/**
 * GridTransformer processes a grid and validates whether its elements 
 * meet specific constraints based on their position (corners, edges, or interior).
 * If valid, it transforms the elements to specific values.
 */
public class GridTransformer {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int testCases = scanner.nextInt();

        while (testCases-- > 0) {
            processTestCase(scanner);
        }

        scanner.close();
    }

    /**
     * Reads the dimensions and grid for a single test case and triggers processing.
     */
    private static void processTestCase(Scanner scanner) {
        if (!scanner.hasNextInt()) return;
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        int[][] grid = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                grid[i][j] = scanner.nextInt();
            }
        }

        if (isValidAndTransform(grid, rows, cols)) {
            System.out.println("YES");
            printGrid(grid, rows, cols);
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Validates the grid based on position-based constraints and transforms it.
     * 
     * Constraints:
     * - Corners must be <= 2 (transformed to 2)
     * - Edges must be <= 3 (transformed to 3)
     * - Interior cells must be <= 4 (transformed to 4)
     * 
     * @return true if the grid is valid and transformed, false otherwise.
     */
    private static boolean isValidAndTransform(int[][] grid, int rows, int cols) {
        // 1. Validate and transform Corners
        if (grid[0][0] > 2 || grid[0][cols - 1] > 2 || 
            grid[rows - 1][0] > 2 || grid[rows - 1][cols - 1] > 2) {
            return false;
        }
        grid[0][0] = 2;
        grid[0][cols - 1] = 2;
        grid[rows - 1][0] = 2;
        grid[rows - 1][cols - 1] = 2;

        // 2. Validate and transform Horizontal Edges (excluding corners)
        for (int j = 1; j < cols - 1; j++) {
            if (grid[0][j] > 3 || grid[rows - 1][j] > 3) {
                return false;
            }
            grid[0][j] = 3;
            grid[rows - 1][j] = 3;
        }

        // 3. Validate and transform Vertical Edges (excluding corners)
        for (int i = 1; i < rows - 1; i++) {
            if (grid[i][0] > 3 || grid[i][cols - 1] > 3) {
                return false;
            }
            grid[i][0] = 3;
            grid[i][cols - 1] = 3;
        }

        // 4. Validate and transform Interior cells
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (grid[i][j] > 4) {
                    return false;
                }
                grid[i][j] = 4;
            }
        }

        return true;
    }

    /**
     * Prints the grid to the console efficiently using StringBuilder.
     */
    private static void printGrid(int[][] grid, int rows, int cols) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                sb.append(grid[i][j]).append(" ");
            }
            sb.append("\n");
        }
        System.out.print(sb.toString());
    }
}

