/**
 * Solution refactored for maintainability and performance.
 * The program determines if a grid can satisfy specific constraints 
 * based on cell positions (corners, edges, or interior).
 */
public class Solution {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int testCases = reader.nextInt();
            while (testCases-- > 0) {
                GridSolver solver = new GridSolver(reader, out);
                solver.solve();
            }
        } catch (Exception e) {
            // In a production environment, use a logger.
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Handles the core logic for a single grid problem instance.
     */
    static class GridSolver {
        private final FastReader reader;
        private final PrintWriter out;

        // Constraints based on cell position
        private static final int CORNER_LIMIT = 2;
        private static final int EDGE_LIMIT = 3;
        private static final int INTERIOR_LIMIT = 4;

        public GridSolver(FastReader reader, PrintWriter out) {
            this.reader = reader;
            this.out = out;
        }

        public void solve() {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            int[][] grid = new int[rows][cols];
            boolean hasPositiveValue = false;

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = reader.nextInt();
                    if (grid[i][j] > 0) {
                        hasPositiveValue = true;
                    }
                }
            }

            if (!hasPositiveValue) {
                printResult(true, grid);
            } else {
                processConstraints(grid, rows, cols);
            }
        }

        private void processConstraints(int[][] grid, int rows, int cols) {
            boolean isValid = true;

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    int limit = getCellLimit(i, j, rows, cols);
                    if (grid[i][j] > limit) {
                        isValid = false;
                        break;
                    }
                    // If valid, the cell is updated to its maximum allowed value
                    grid[i][j] = limit;
                }
                if (!isValid) break;
            }

            printResult(isValid, grid);
        }

        /**
         * Calculates the maximum allowed value for a cell based on its position.
         */
        private int getCellLimit(int r, int c, int rows, int cols) {
            boolean isCorner = (r == 0 || r == rows - 1) && (c == 0 || c == cols - 1);
            if (isCorner) {
                return CORNER_LIMIT;
            }

            boolean isEdge = (r == 0 || r == rows - 1 || c == 0 || c == cols - 1);
            if (isEdge) {
                return EDGE_LIMIT;
            }

            return INTERIOR_LIMIT;
        }

        private void printResult(boolean success, int[][] grid) {
            out.println(success ? "YES" : "NO");
            if (success) {
                for (int[] row : grid) {
                    for (int i = 0; i < row.length; i++) {
                        out.print(row[i] + (i == row.length - 1 ? "" : " "));
                    }
                    out.println();
                }
            }
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

