 * The goal is to replace matrix elements with specific boundary values:
 * - Corners: 2
 * - Edges: 3
 * - Interior: 4
 * If any original element exceeds its designated boundary value, the transformation is impossible.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        StringBuilder outputBuilder = new StringBuilder();

        int testCases = reader.nextInt();
        for (int i = 0; i < testCases; i++) {
            solveTestCase(reader, outputBuilder);
        }

        System.out.print(outputBuilder.toString());
    }

    private static void solveTestCase(FastReader reader, StringBuilder output) {
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        int[][] matrix = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            matrix[i] = reader.nextIntArray(cols);
        }

        if (isTransformationPossible(matrix, rows, cols)) {
            output.append("YES\n");
            appendMatrixToOutput(matrix, rows, cols, output);
        } else {
            output.append("NO\n");
        }
    }

    /**
     * Validates if the matrix can be transformed and performs the transformation.
     * Returns true if successful, false otherwise.
     */
    private static boolean isTransformationPossible(int[][] matrix, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int limit = getBoundaryLimit(i, j, rows, cols);
                if (matrix[i][j] > limit) {
                    return false;
                }
                matrix[i][j] = limit;
            }
        }
        return true;
    }

    /**
     * Determines the maximum allowed value for a cell based on its position.
     */
    private static int getBoundaryLimit(int r, int c, int rows, int cols) {
        boolean isRowEdge = (r == 0 || r == rows - 1);
        boolean isColEdge = (c == 0 || c == cols - 1);

        if (isRowEdge && isColEdge) {
            return 2; // Corner
        } else if (isRowEdge || isColEdge) {
            return 3; // Edge
        } else {
            return 4; // Interior
        }
    }

    private static void appendMatrixToOutput(int[][] matrix, int rows, int cols, StringBuilder output) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                output.append(matrix[i][j]);
                if (j < cols - 1) {
                    output.append(" ");
                }
            }
            output.append("\n");
