/**
 * Problem: Validate if a given grid satisfies specific boundary constraints.
 * Constraints:
 * - Corners must be <= 2
 * - Edges must be <= 3
 * - Interior cells must be <= 4
 */
public class GridBoundaryValidator {

    private static final int CORNER_VALUE = 2;
    private static final int EDGE_VALUE = 3;
    private static final int INTERIOR_VALUE = 4;

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            int testCases = reader.nextInt();
            while (testCases-- > 0) {
                solve(reader, out);
            }
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Processes a single test case.
     */
    private static void solve(FastReader reader, PrintWriter out) throws IOException {
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        int[][] boundaryGrid = generateBoundaryGrid(rows, cols);
        boolean isPossible = true;

        // We must iterate through the entire input to ensure the reader 
        // stays in sync for the next test case, even if we find a violation early.
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int currentCellValue = reader.nextInt();
                if (currentCellValue > boundaryGrid[i][j]) {
                    isPossible = false;
                }
            }
        }

        if (!isPossible) {
            out.println("NO");
        } else {
            out.println("YES");
            printGrid(boundaryGrid, out);
        }
    }

    /**
     * Creates a grid populated with the maximum allowed values for 
     * corners, edges, and interior cells.
     */
    private static int[][] generateBoundaryGrid(int rows, int cols) {
        int[][] grid = new int[rows][cols];

        // Fill with default interior value
        for (int i = 0; i < rows; i++) {
            Arrays.fill(grid[i], INTERIOR_VALUE);
        }

        // Set edges
        for (int i = 0; i < rows; i++) {
            grid[i][0] = EDGE_VALUE;
            grid[i][cols - 1] = EDGE_VALUE;
        }
        for (int j = 0; j < cols; j++) {
            grid[0][j] = EDGE_VALUE;
            grid[rows - 1][j] = EDGE_VALUE;
        }

        // Set corners (overwrites edge values at indices 0,0 etc.)
        grid[0][0] = CORNER_VALUE;
        grid[0][cols - 1] = CORNER_VALUE;
        grid[rows - 1][0] = CORNER_VALUE;
        grid[rows - 1][cols - 1] = CORNER_VALUE;

        return grid;
    }

    /**
     * Efficiently prints the 2D grid to the output stream.
     */
    private static void printGrid(int[][] grid, PrintWriter out) {
        for (int[] row : grid) {
            for (int i = 0; i < row.length; i++) {
                out.print(row[i]);
                if (i < row.length - 1) {
                    out.print(" ");
                }
            }
            out.println();
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        public double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }
