import java.util.Scanner;

/**
 * A program to validate and transform a matrix based on specific 
 * boundary and interior constraints.
 */
public class MatrixPatternProcessor {

    private static final int CORNER_VALUE = 2;
    private static final int EDGE_VALUE = 3;
    private static final int INTERIOR_VALUE = 4;

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;

            int testCases = scanner.nextInt();
            while (testCases-- > 0) {
                processTestCase(scanner);
            }
        }
    }

    /**
     * Orchestrates the logic for a single test case.
     */
    private static void processTestCase(Scanner scanner) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        int[][] matrix = new int[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                matrix[i][j] = scanner.nextInt();
            }
        }

        if (isMatrixValid(matrix, rows, cols)) {
            applyStandardPattern(matrix, rows, cols);
            System.out.println("YES");
            printMatrix(matrix);
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Validates if the matrix adheres to the boundary and interior rules.
     * Corners must be <= 2, Edges <= 3, and Interior <= 4.
     */
    private static boolean isMatrixValid(int[][] matrix, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (isCorner(i, j, rows, cols)) {
                    if (matrix[i][j] > CORNER_VALUE) return false;
                } else if (isEdge(i, j, rows, cols)) {
                    if (matrix[i][j] > EDGE_VALUE) return false;
                } else {
                    if (matrix[i][j] > INTERIOR_VALUE) return false;
                }
            }
        }
        return true;
    }

    /**
     * Overwrites the matrix with the standard pattern values.
     */
    private static void applyStandardPattern(int[][] matrix, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (isCorner(i, j, rows, cols)) {
                    matrix[i][j] = CORNER_VALUE;
                } else if (isEdge(i, j, rows, cols)) {
                    matrix[i][j] = EDGE_VALUE;
                } else {
                    matrix[i][j] = INTERIOR_VALUE;
                }
            }
        }
    }

    private static boolean isCorner(int r, int c, int rows, int cols) {
        return (r == 0 || r == rows - 1) && (c == 0 || c == cols - 1);
    }

    private static boolean isEdge(int r, int c, int rows, int cols) {
        return (r == 0 || r == rows - 1 || c == 0 || c == cols - 1);
    }

    /**
     * Prints the matrix using StringBuilder for better performance.
     */
    private static void printMatrix(int[][] matrix) {
        StringBuilder sb = new StringBuilder();
        for (int[] row : matrix) {
            for (int val : row) {
                sb.append(val).append(" ");
            }
            sb.append("\n");
        }
        System.out.print(sb.toString());
    }
}

import java.util.*;

/**
 * A solver for the Grid Constraint Problem.
 * The goal is to adjust a grid such that:
 * - Corner cells have a maximum value of 2.
 * - Edge cells have a maximum value of 3.
 * - Interior cells have a maximum value of 4.
 */
public class GridConstraintSolver {

    private static final int CORNER_LIMIT = 2;
    private static final int EDGE_LIMIT = 3;
    private static final int INTERIOR_LIMIT = 4;

    /**
     * Represents the outcome of a single test case.
     */
    private static class Result {
        private final boolean isPossible;
        private final int[][] grid;

        private Result(boolean isPossible, int[][] grid) {
            this.isPossible = isPossible;
            this.grid = grid;
        }

        public static Result failure() {
            return new Result(false, null);
        }

        public static Result success(int[][] grid) {
            return new Result(true, grid);
        }

        public boolean isPossible() {
            return isPossible;
        }

        public int[][] getGrid() {
            return grid;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        StringBuilder outputBuilder = new StringBuilder();

        if (!scanner.hasNextInt()) return;

        int testCases = scanner.nextInt();

        for (int t = 0; t < testCases; t++) {
            int rowCount = scanner.nextInt();
            int colCount = scanner.nextInt();
            int[][] grid = readGrid(scanner, rowCount, colCount);

            Result result = solve(grid, rowCount, colCount);

            if (result.isPossible()) {
                outputBuilder.append("YES\n");
                appendGridToOutput(outputBuilder, result.getGrid(), rowCount, colCount);
            } else {
                outputBuilder.append("NO\n");
            }
        }

        System.out.print(outputBuilder);
        scanner.close();
    }

    /**
     * Reads the grid values from the scanner.
     */
    private static int[][] readGrid(Scanner scanner, int rows, int cols) {
        int[][] grid = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                grid[i][j] = scanner.nextInt();
            }
        }
        return grid;
    }

    /**
     * Processes the grid logic to check if constraints are met and adjust values.
     */
    private static Result solve(int[][] grid, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int allowedLimit = getConstraintLimit(i, j, rows, cols);

                if (grid[i][j] > allowedLimit) {
                    return Result.failure();
                }
                // Adjust the value to the maximum allowed limit as per original logic
                grid[i][j] = allowedLimit;
            }
        }
        return Result.success(grid);
    }

    /**
     * Determines the maximum allowed value for a cell based on its position.
     */
    private static int getConstraintLimit(int r, int c, int rows, int cols) {
        boolean isRowEdge = (r == 0 || r == rows - 1);
        boolean isColEdge = (c == 0 || c == cols - 1);

        if (isRowEdge && isColEdge) {
            return CORNER_LIMIT;
        } else if (isRowEdge || isColEdge) {
            return EDGE_LIMIT;
        } else {
            return INTERIOR_LIMIT;
        }
    }

    /**
     * Appends the grid content to the StringBuilder.
     */
    private static void appendGridToOutput(StringBuilder sb, int[][] grid, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                sb.append(grid[i][j]);
                if (j < cols - 1) {
                    sb.append(" ");
                }
            }
            sb.append("\n");
        }
    }
}

