/**
 * A solution to determine if a grid can be satisfied by cell degrees.
 * If valid, it prints a grid where each cell contains its neighbor count.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            int testCases = reader.nextInt();
            while (testCases-- > 0) {
                GridSolver solver = new GridSolver(reader);
                solver.solve(writer);
            }
        } catch (Exception e) {
            // In a production environment, use a logger.
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Efficient input reader to handle large datasets.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            return next == null ? 0 : Integer.parseInt(next);
        }

        public long nextLong() {
            String next = next();
            return next == null ? 0L : Long.parseLong(next);
        }
    }

    /**
     * Encapsulates the grid logic and validation.
     */
    static class GridSolver {
        private static final int[][] DIRECTIONS = {
            {0, 1},  // Right
            {0, -1}, // Left
            {1, 0},  // Down
            {-1, 0}  // Up
        };

        private final FastReader reader;

        public GridSolver(FastReader reader) {
            this.reader = reader;
        }

        /**
         * Orchestrates the reading, validation, and printing for one test case.
         */
        public void solve(PrintWriter out) {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            long[][] inputGrid = new long[rows][cols];
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    inputGrid[i][j] = reader.nextLong();
                }
            }

            if (isGridPossible(inputGrid, rows, cols)) {
                out.println("YES");
                printDegreeGrid(rows, cols, out);
            } else {
                out.println("NO");
            }
        }

        /**
         * Checks if every cell's value is less than or equal to its neighbor count.
         */
        private boolean isGridPossible(long[][] grid, int rows, int cols) {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] > 0) {
                        if (grid[r][c] > countNeighbors(r, c, rows, cols)) {
                            return false;
                        }
                    }
                }
            }
            return true;
        }

        /**
         * Generates and prints a grid where every cell equals its degree.
         */
        private void printDegreeGrid(int rows, int cols, PrintWriter out) {
            for (int r = 0; r < rows; r++) {
                StringBuilder sb = new StringBuilder();
                for (int c = 0; c < cols; c++) {
                    sb.append(countNeighbors(r, c, rows, cols));
                    if (c < cols - 1) {
                        sb.append(" ");
                    }
                }
                out.println(sb.toString());
            }
        }

        /**
         * Calculates how many neighbors a cell at (r, c) has within the grid boundaries.
         */
        private int countNeighbors(int r, int c, int rows, int cols) {
            int neighbors = 0;
            for (int[] direction : DIRECTIONS) {
                int neighborRow = r + direction[0];
                int neighborCol = c + direction[1];

                if (isWithinBounds(neighborRow, neighborCol, rows, cols)) {
                    neighbors++;
                }
            }
            return neighbors;
        }

        private boolean isWithinBounds(int r, int c, int rows, int cols) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }
}

