/**
 * Contains the core logic for validating and modifying the grid based on 
 * position-based threshold rules.
 */
class GridSolver {
    private static final int CORNER_LIMIT = 2;
    private static final int EDGE_LIMIT = 3;
    private static final int INTERIOR_LIMIT = 4;

    private final int rows;
    private final int cols;
    private final int[][] grid;

    public GridSolver(int rows, int cols, int[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
    }

    /**
     * Iterates through the grid once, applying limits and checking for violations.
     * 
     * @return A GridResult containing the modified grid and whether it met constraints.
     */
    public GridResult solve() {
        boolean isValid = true;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int limit = calculateLimit(r, c);

                if (grid[r][c] > limit) {
                    isValid = false;
                    break;
                }
                // Set the cell to the limit if it is below the threshold
                grid[r][c] = limit;
            }
            if (!isValid) {
                break;
            }
        }

        return new GridResult(isValid, grid);
    }

    /**
     * Determines the maximum allowed value for a cell based on its position.
     */
    private int calculateLimit(int r, int c) {
        if (isCorner(r, c)) {
            return CORNER_LIMIT;
        } else if (isEdge(r, c)) {
            return EDGE_LIMIT;
        } else {
            return INTERIOR_LIMIT;
        }
    }

    private boolean isCorner(int r, int c) {
        return (r == 0 || r == rows - 1) && (c == 0 || c == cols - 1);
    }

    private boolean isEdge(int r, int c) {
        return r == 0 || r == rows - 1 || c == 0 || c == cols - 1;
    }
}

