            for (int j = 0; j < cols; j++) {
                grid[i][j] = scanner.nextInt();
            }
        }

        TransformationResult result = transformGrid(grid, rows, cols);

        if (result.isPossible()) {
            System.out.println("YES");
            System.out.print(result.getFormattedGrid());
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Represents the outcome of the grid transformation attempt.
     */
    private static class TransformationResult {
        private final boolean possible;
        private final String formattedGrid;

        public TransformationResult(boolean possible, String formattedGrid) {
            this.possible = possible;
            this.formattedGrid = formattedGrid;
        }

        public boolean isPossible() {
            return possible;
        }

        public String getFormattedGrid() {
            return formattedGrid;
        }
    }

    /**
     * Transforms the grid based on the target pattern:
     * Corners: 2, Edges: 3, Interior: 4.
     * If any cell in the original grid is greater than its target value, 
     * the transformation is impossible.
     * 
     * @param grid The original 2D array.
     * @param rows Number of rows.
     * @param cols Number of columns.
     * @return A TransformationResult containing success status and the new grid string.
     */
    private static TransformationResult transformGrid(int[][] grid, int rows, int cols) {
        boolean isPossible = true;
        StringBuilder outputBuilder = new StringBuilder();

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int targetValue = getTargetValue(r, c, rows, cols);

                if (grid[r][c] > targetValue) {
                    isPossible = false;
                }

                // Update the grid with the target value
                grid[r][c] = targetValue;
                outputBuilder.append(grid[r][c]).append(" ");
            }
            outputBuilder.append("\n");
        }

        return new TransformationResult(isPossible, outputBuilder.toString());
    }

    /**
     * Determines the required value for a cell based on its position.
     * 
     * @param r Current row index.
     * @param c Current column index.
     * @param rows Total row count.
     * @param cols Total column count.
     * @return The target integer value (2, 3, or 4).
     */
    private static int getTargetValue(int r, int c, int rows, int cols) {
        boolean isRowEdge = (r == 0 || r == rows - 1);
        boolean isColEdge = (c == 0 || c == cols - 1);

        if (isRowEdge && isColEdge) {
            return 2; // Corner
        } else if (isRowEdge || isColEdge) {
            return 3; // Edge
        } else {
            return 4; // Interior
        }
    }
}

