/**
 * A program that transforms a grid based on cell positions.
 * Corners must be <= 2, edges <= 3, and interior cells <= 4.
 */
public class Main {

    // Constants representing the maximum allowed values for different cell types
    private static final int CORNER_LIMIT = 2;
    private static final int EDGE_LIMIT = 3;
    private static final int INTERIOR_LIMIT = 4;

    public static void main(String[] args) {
        new Main().run();
    }

    /**
     * Orchestrates the execution of the program.
     */
    private void run() {
        FastReader reader = new FastReader(System.in);
