        try {
            String testCaseInput = reader.next();
            if (testCaseInput != null) {
                int testCases = Integer.parseInt(testCaseInput);
                for (int tc = 0; tc < testCases; tc++) {
                    processTestCase(reader, out);
                }
            }
        } catch (IOException | NumberFormatException e) {
            // Silently handle or log errors as per requirement
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Reads data for a single test case, performs the transformation, and outputs the result.
     *
     * @param reader The fast input reader.
     * @param out    The output writer.
     * @throws IOException If an I/O error occurs.
     */
    private void processTestCase(FastReader reader, PrintWriter out) throws IOException {
        int rows = reader.nextInt();
        int cols = reader.nextInt();
        int[][] matrix = new int[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                matrix[i][j] = reader.nextInt();
            }
        }

        TransformationResult result = transformMatrix(matrix, rows, cols);

        if (result.isValid) {
            out.println("YES");
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    out.print(result.matrix[i][j] + " ");
                }
                out.println();
            }
        } else {
            out.println("NO");
        }
    }

    /**
     * Validates and transforms the matrix according to the boundary rules.
     *
     * @param matrix The input matrix.
     * @param rows   Number of rows.
     * @param cols   Number of columns.
     * @return A result object containing the success status and the modified matrix.
     */
    private TransformationResult transformMatrix(int[][] matrix, int rows, int cols) {
        boolean isValid = true;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int limit = getLimitForCell(r, c, rows, cols);

                if (matrix[r][c] > limit) {
                    isValid = false;
                }
                // The requirement is to update the matrix with the limit value
                matrix[r][c] = limit;
            }
        }

        return new TransformationResult(isValid, matrix);
    }

    /**
     * Determines the rule-based limit for a specific cell based on its location.
     */
    private int getLimitForCell(int r, int c, int rows, int cols) {
        boolean isRowBoundary = (r == 0 || r == rows - 1);
        boolean isColBoundary = (c == 0 || c == cols - 1);

        if (isRowBoundary && isColBoundary) {
            return CORNER_LIMIT;
        } else if (isRowBoundary || isColBoundary) {
            return EDGE_LIMIT;
        } else {
            return INTERIOR_LIMIT;
        }
    }

    /**
     * Data Transfer Object to carry the result of the matrix transformation.
     */
    private static class TransformationResult {
        final boolean isValid;
        final int[][] matrix;

        TransformationResult(boolean isValid, int[][] matrix) {
            this.isValid = isValid;
            this.matrix = matrix;
        }
    }

    /**
     * Fast I/O utility class for efficient reading of input.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

/**
 * MatrixProcessor validates a grid based on specific positional constraints
 * and generates a maximum-value grid if the constraints are met.
 * 
 * Constraints:
 * - Corner cells: maximum allowed value is 2
 * - Edge cells: maximum allowed value is 3
 * - Interior cells: maximum allowed value is 4
 */
public class Main {

    private static final int CORNER_MAX_VALUE = 2;
    private static final int EDGE_MAX_VALUE = 3;
    private static final int INTERIOR_MAX_VALUE = 4;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int testCases = scanner.nextInt();
        while (testCases-- > 0) {
            processTestCase(scanner);
        }

        scanner.close();
    }

    /**
     * Reads input for a single test case and orchestrates validation and output.
     */
    private static void processTestCase(Scanner scanner) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        int[][] matrix = new int[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                matrix[i][j] = scanner.nextInt();
            }
        }

        if (isMatrixValid(matrix, rows, cols)) {
            System.out.println("YES");
            printMaximizedMatrix(matrix, rows, cols);
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Checks if the provided matrix satisfies the positional constraints.
     */
    private static boolean isMatrixValid(int[][] matrix, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (matrix[r][c] > getMaxAllowedValue(r, c, rows, cols)) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Generates and prints a matrix of the same dimensions filled with 
     * the maximum possible allowed values.
     */
    private static void printMaximizedMatrix(int[][] matrix, int rows, int cols) {
        StringBuilder sb = new StringBuilder();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                sb.append(getMaxAllowedValue(r, c, rows, cols));
                if (c < cols - 1) {
                    sb.append(" ");
                }
            }
            sb.append("\n");
        }
        System.out.print(sb.toString());
    }

    /**
     * Determines the maximum allowed value for a cell based on its position.
     * 
     * @param r current row index
     * @param c current column index
     * @param rows total number of rows
     * @param cols total number of columns
     * @return the maximum allowed integer for that position
     */
    private static int getMaxAllowedValue(int r, int c, int rows, int cols) {
        if (isCorner(r, c, rows, cols)) {
            return CORNER_MAX_VALUE;
        } else if (isEdge(r, c, rows, cols)) {
            return EDGE_MAX_VALUE;
        } else {
            return INTERIOR_MAX_VALUE;
        }
    }

    private static boolean isCorner(int r, int c, int rows, int cols) {
        return (r == 0 || r == rows - 1) && (c == 0 || c == cols - 1);
    }

    private static boolean isEdge(int r, int c, int rows, int cols) {
        return (r == 0 || r == rows - 1 || c == 0 || c == cols - 1);
    }
}

import java.util.*;
import java.io.*;

/**
 * MatrixPatternApp processes a grid of numbers to determine if they can be 
 * transformed into a specific pattern:
 * - Corners: 2
 * - Edges (excluding corners): 3
 * - Interior: 4
 */
public class MatrixPatternApp {

    private static final int CORNER_VALUE = 2;
    private static final int EDGE_VALUE = 3;
    private static final int INTERIOR_VALUE = 4;

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            String line = reader.readLine();
            if (line == null || line.isEmpty()) {
                return;
            }

            int numCases = Integer.parseInt(line.trim());

            for (int caseIdx = 0; caseIdx < numCases; caseIdx++) {
                MatrixProblem problem = reader.readNextProblem();
                if (problem == null) break;

                MatrixPatternService service = new MatrixPatternService(problem.matrix);

                if (service.isPatternPossible()) {
                    out.println("YES");
                    service.applyPattern();
                    printMatrix(out, problem.matrix);
                } else {
                    out.println("NO");
                }
            }
        } catch (Exception e) {
            // In a production environment, use a logging framework
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Helper to print the matrix efficiently using StringBuilder.
     */
    private static void printMatrix(PrintWriter out, int[][] matrix) {
        for (int[] row : matrix) {
            StringBuilder sb = new StringBuilder();
            for (int j = 0; j < row.length; j++) {
                sb.append(row[j]);
                if (j < row.length - 1) {
                    sb.append(" ");
                }
            }
            out.println(sb.toString());
        }
    }

    /**
     * Data container for the matrix input.
     */
    private static class MatrixProblem {
        final int[][] matrix;

        MatrixProblem(int[][] matrix) {
            this.matrix = matrix;
        }
    }

    /**
     * Service class containing the core business logic for the matrix pattern.
     */
    private static class MatrixPatternService {
        private final int[][] matrix;
        private final int rows;
        private final int cols;

        MatrixPatternService(int[][] matrix) {
            this.matrix = matrix;
            this.rows = matrix.length;
            this.cols = matrix[0].length;
        }

        /**
         * Validates if every cell in the matrix is less than or equal to 
         * the value required by the pattern.
         */
        public boolean isPatternPossible() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (matrix[i][j] > getExpectedValue(i, j)) {
                        return false;
                    }
                }
            }
            return true;
        }

        /**
         * Fills the matrix with the pattern values.
         */
        public void applyPattern() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    matrix[i][j] = getExpectedValue(i, j);
                }
            }
        }

        /**
         * Determines the pattern value for a specific coordinate.
         */
        private int getExpectedValue(int r, int c) {
            boolean isCorner = (r == 0 || r == rows - 1) && (c == 0 || c == cols - 1);
            if (isCorner) {
                return CORNER_VALUE;
            }

            boolean isEdge = (r == 0 || r == rows - 1 || c == 0 || c == cols - 1);
            if (isEdge) {
                return EDGE_VALUE;
            }

            return INTERIOR_VALUE;
        }
    }

    /**
     * Utility class for fast input parsing.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String readLine() throws IOException {
            return reader.readLine();
        }

        public MatrixProblem readNextProblem() throws IOException {
            String line = reader.readLine();
            if (line == null) return null;

            StringTokenizer st = new StringTokenizer(line);
            if (!st.hasMoreTokens()) return null;

            int rows = Integer.parseInt(st.nextToken());
            int cols = Integer.parseInt(st.nextToken());

            int[][] matrix = new int[rows][cols];
            for (int i = 0; i < rows; i++) {
                st = new StringTokenizer(reader.readLine());
                for (int j = 0; j < cols; j++) {
                    matrix[i][j] = Integer.parseInt(st.nextToken());
                }
            }
            return new MatrixProblem(matrix);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solution to process a grid based on neighbor-count constraints.
 * The logic ensures that non-zero cells match the count of their non-zero neighbors,
 * potentially by converting adjacent zero-cells into ones.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int testCases = reader.nextInt();
            while (testCases-- > 0) {
                GridSolver solver = new GridSolver(reader);
                solver.solve(out);
            }
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Core logic for solving the grid problem.
     */
    static class GridSolver {
        private final int rows;
        private final int cols;
        private final int[][] grid;
        private final FastReader reader;

        public GridSolver(FastReader reader) throws IOException {
            this.reader = reader;
            this.rows = reader.nextInt();
            this.cols = reader.nextInt();
            this.grid = new int[rows][cols];
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = reader.nextInt();
                }
            }
        }

        /**
         * Executes the primary transformation logic and prints the result.
         */
        public void solve(PrintWriter out) {
            if (processGrid()) {
                out.println("YES");
                applyFinalCorrection();
                printGrid(out);
            } else {
                out.println("NO");
            }
        }

        /**
         * Iterates through the grid and attempts to satisfy neighbor constraints.
         * @return true if the grid can be made valid, false otherwise.
         */
        private boolean processGrid() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == 0) {
                        continue;
                    }

                    int nonZeroNeighbors = countNonZeroNeighbors(i, j);
                    int diff = grid[i][j] - nonZeroNeighbors;

                    if (diff == 0) {
                        continue;
                    } else if (diff < 0) {
                        // If current cell is less than neighbors, update it to match neighbors
                        grid[i][j] = nonZeroNeighbors;
                    } else {
                        // If current cell is greater than neighbors, try to convert adjacent zeros to ones
                        if (!tryFillAdjacentZeros(i, j, diff)) {
                            return false;
                        }
                    }
                }
            }
            return true;
        }

        /**
         * Final pass to ensure the 'diff < 0' rule is applied to the final state of the grid.
         */
        private void applyFinalCorrection() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == 0) continue;
                    int nonZeroNeighbors = countNonZeroNeighbors(i, j);
                    int diff = grid[i][j] - nonZeroNeighbors;
                    if (diff < 0) {
                        grid[i][j] = nonZeroNeighbors;
                    }
                }
            }
        }

        /**
         * Attempts to turn 'amount' number of adjacent zero-cells into ones.
         * Order of check: Up, Left, Down, Right.
         */
        private boolean tryFillAdjacentZeros(int r, int c, int amount) {
            int remaining = amount;

            // Directional offsets: Up, Left, Down, Right
            int[] dr = {-1, 0, 1, 0};
            int[] dc = {0, -1, 0, 1};

            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i];
                int nc = c + dc[i];

                if (isValid(nr, nc) && grid[nr][nc] == 0) {
                    grid[nr][nc] = 1;
                    remaining--;
                    if (remaining == 0) return true;
                }
            }
            return remaining == 0;
        }

        private int countNonZeroNeighbors(int r, int c) {
            int count = 0;
            int[] dr = {-1, 1, 0, 0};
            int[] dc = {0, 0, -1, 1};

            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i];
                int nc = c + dc[i];
                if (isValid(nr, nc) && grid[nr][nc] != 0) {
                    count++;
                }
            }
            return count;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        private void printGrid(PrintWriter out) {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    sb.append(grid[i][j]).append(" ");
                }
                sb.append("\n");
            }
            out.print(sb.toString());
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

/**
 * This program validates whether a given grid of integers represents a 
 * valid distribution of neighbor counts for a rectangular grid graph.
 * In a grid:
 * - Corners have 2 neighbors.
 * - Edges (non-corner) have 3 neighbors.
 * - Interior cells have 4 neighbors.
 */
public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int testCases = scanner.nextInt();

        while (testCases-- > 0) {
            processTestCase(scanner);
        }

        scanner.close();
    }

    /**
     * Reads input for a single test case, validates the grid, and prints the result.
     * 
     * @param scanner The scanner instance to read from.
     */
    private static void processTestCase(Scanner scanner) {
        if (!scanner.hasNextInt()) return;

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        int[][] inputGrid = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                inputGrid[i][j] = scanner.nextInt();
            }
        }

        int[][] maxNeighborsGrid = new int[rows][cols];
        boolean isValid = true;

        // Validate every cell in the input grid
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int maxAllowed = getMaxNeighbors(i, j, rows, cols);
                maxNeighborsGrid[i][j] = maxAllowed;

                if (inputGrid[i][j] > maxAllowed) {
                    isValid = false;
                    // We continue to fill maxNeighborsGrid to maintain 
                    // consistency, though we could break early for performance.
                }
            }
        }

        if (isValid) {
            System.out.println("YES");
            printGrid(maxNeighborsGrid);
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Determines the maximum number of neighbors a cell can have based on its position.
     *
     * @param r The current row index.
     * @param c The current column index.
     * @param totalRows Total number of rows in the grid.
     * @param totalCols Total number of columns in the grid.
     * @return The maximum allowed neighbors (2 for corners, 3 for edges, 4 for interior).
     */
    private static int getMaxNeighbors(int r, int c, int totalRows, int totalCols) {
        boolean isRowEdge = (r == 0 || r == totalRows - 1);
        boolean isColEdge = (c == 0 || c == totalCols - 1);

        if (isRowEdge && isColEdge) {
            return 2; // Corner
        } else if (isRowEdge || isColEdge) {
            return 3; // Edge
        } else {
            return 4; // Interior
        }
    }

    /**
     * Efficiently prints the 2D grid to standard output.
     *
     * @param grid The 2D array to print.
     */
    private static void printGrid(int[][] grid) {
        StringBuilder sb = new StringBuilder();
        for (int[] row : grid) {
            for (int val : row) {
                sb.append(val).append(" ");
            }
            sb.append("\n");
        }
        System.out.print(sb.toString());
    }
}

import java.util.Scanner;

/**
 * A solver for grid validation and reconstruction based on specific 
 * boundary and interior constraints.
 */
public class GridSolver {

    // Constants to replace "magic numbers" for better maintainability
    private static final int MAX_ALLOWED_VALUE = 4;
    private static final int MAX_EDGE_VALUE = 3;
    private static final int MAX_CORNER_VALUE = 2;

    private static final int INTERIOR_VALUE = 4;
    private static final int EDGE_VALUE = 3;
    private static final int CORNER_VALUE = 2;

    private static final String YES = "YES";
    private static final String NO = "NO";

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (scanner.hasNextInt()) {
            int testCases = scanner.nextInt();
            for (int i = 0; i < testCases; i++) {
                processTestCase(scanner);
            }
        }
        scanner.close();
    }

    /**
     * Reads the dimensions and grid for a single test case,
     * validates it, and prints the result.
     */
    private static void processTestCase(Scanner scanner) {
        if (!scanner.hasNextInt()) return;
        int rowCount = scanner.nextInt();
        if (!scanner.hasNextInt()) return;
        int colCount = scanner.nextInt();

        int[][] grid = new int[rowCount][colCount];
        for (int i = 0; i < rowCount; i++) {
            for (int j = 0; j < colCount; j++) {
                grid[i][j] = scanner.nextInt();
            }
        }

        if (isValidGrid(grid, rowCount, colCount)) {
            printResult(YES, grid, rowCount, colCount);
        } else {
            printResult(NO, null, 0, 0);
        }
    }

    /**
     * Validates the grid based on the rules:
     * 1. All cells must be <= 4.
     * 2. Corner cells must be <= 2.
     * 3. Edge cells (non-corners) must be <= 3.
     */
    private static boolean isValidGrid(int[][] grid, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int value = grid[r][c];

                if (value > MAX_ALLOWED_VALUE) {
                    return false;
                }

                if (isCorner(r, c, rows, cols)) {
                    if (value > MAX_CORNER_VALUE) return false;
                } else if (isEdge(r, c, rows, cols)) {
                    if (value > MAX_EDGE_VALUE) return false;
                }
            }
        }
        return true;
    }

    private static boolean isCorner(int r, int c, int rows, int cols) {
        return (r == 0 || r == rows - 1) && (c == 0 || c == cols - 1);
    }

    private static boolean isEdge(int r, int c, int rows, int cols) {
        return (r == 0 || r == rows - 1 || c == 0 || c == cols - 1);
    }

    /**
     * Prints either "YES" followed by the reconstructed grid, or "NO".
     */
    private static void printResult(String status, int[][] originalGrid, int rows, int cols) {
        if (status.equals(NO)) {
            System.out.println(NO);
            return;
        }

        StringBuilder output = new StringBuilder();
        output.append(YES).append("\n");

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                output.append(getTargetValue(r, c, rows, cols));
                if (c < cols - 1) {
                    output.append(" ");
                }
            }
            output.append("\n");
        }
        System.out.print(output.toString());
    }

    /**
     * Determines the value a cell should have in the reconstructed grid.
     */
    private static int getTargetValue(int r, int c, int rows, int cols) {
        if (isCorner(r, c, rows, cols)) {
            return CORNER_VALUE;
        } else if (isEdge(r, c, rows, cols)) {
            return EDGE_VALUE;
        } else {
            return INTERIOR_VALUE;
        }
    }
}

import java.util.*;
