/**
 * GridProblemSolver handles the logic for validating and transforming
 * a matrix based on specific positional constraints.
 * 
 * Constraints:
 * - Corners must be <= 2 (Target: 2)
 * - Borders (non-corner) must be <= 3 (Target: 3)
 * - Interior cells must be <= 4 (Target: 4)
 */
public class GridProblemSolver {

    private static final int CORNER_VALUE = 2;
    private static final int BORDER_VALUE = 3;
    private static final int INTERIOR_VALUE = 4;

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int testCases = reader.nextInt();
            for (int t = 0; t < testCases; t++) {
                solve(reader, out);
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Processes a single test case.
     */
    private static void solve(FastReader reader, PrintWriter out) throws IOException {
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        int[][] originalGrid = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                originalGrid[i][j] = reader.nextInt();
            }
        }

        int[][] targetGrid = new int[rows][cols];
        boolean isValid = true;

        // Validate the original grid against the target values required by position
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int targetValue = getTargetValueForPosition(rows, cols, i, j);

                // If the original value exceeds the allowed capacity for that position
                if (originalGrid[i][j] > targetValue) {
                    isValid = false;
                }
                targetGrid[i][j] = targetValue;
            }
        }

        if (isValid) {
            out.println("YES");
            printMatrix(targetGrid, out);
        } else {
            out.println("NO");
        }
    }

    /**
     * Determines the required value for a cell based on its coordinates.
     */
    private static int getTargetValueForPosition(int rows, int cols, int r, int c) {
        boolean isCorner = (r == 0 || r == rows - 1) && (c == 0 || c == cols - 1);
        if (isCorner) {
            return CORNER_VALUE;
        }

        boolean isBorder = (r == 0 || r == rows - 1 || c == 0 || c == cols - 1);
        if (isBorder) {
            return BORDER_VALUE;
        }

        return INTERIOR_VALUE;
    }

    /**
     * Helper method to print the matrix efficiently.
     */
    private static void printMatrix(int[][] matrix, PrintWriter out) {
        for (int[] row : matrix) {
            for (int j = 0; j < row.length; j++) {
                out.print(row[j]);
                if (j < row.length - 1) {
                    out.print(" ");
                }
            }
            out.println();
        }
    }

    /**
     * Fast I/O utility class for efficient reading of large input sets.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream inputStream) {
            br = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

