/**
 * Contains the business logic for solving the NeighborGrid problem.
 */
class GridSolver {

    // Direction vectors for traversing adjacent neighbors (Up, Down, Left, Right)
    private static final int[] ROW_DIRECTIONS = {-1, 1, 0, 0};
    private static final int[] COL_DIRECTIONS = {0, 0, -1, 1};

    /**
     * Determines if every cell in the grid is less than or equal 
     * to its count of adjacent neighbors.
     * 
     * @param grid The input grid.
     * @return true if the condition holds for all cells, false otherwise.
     */
    public boolean isPossible(int[][] grid) {
        int rows = grid.length;
        if (rows == 0) return true;
        int cols = grid[0].length;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] > countNeighbors(grid, r, c)) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Creates a new grid where each cell contains the number of 
     * neighbors that cell has in the original grid dimensions.
     * 
     * @param grid The input grid.
     * @return A grid of neighbor counts.
     */
    public int[][] generateNeighborGrid(int[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        int[][] neighborGrid = new int[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                neighborGrid[r][c] = countNeighbors(grid, r, c);
            }
        }
        return neighborGrid;
    }

    /**
     * Calculates the number of valid adjacent neighbors for a cell.
     * A neighbor is valid if it is within the grid boundaries.
     * 
     * @param grid The grid to check boundaries against.
     * @param row The row index of the target cell.
     * @param col The column index of the target cell.
     * @return The count of adjacent neighbors.
     */
    private int countNeighbors(int[][] grid, int row, int col) {
        int rows = grid.length;
        int cols = grid[0].length;
        int count = 0;

        for (int i = 0; i < 4; i++) {
            int neighborRow = row + ROW_DIRECTIONS[i];
            int neighborCol = col + COL_DIRECTIONS[i];

            if (isWithinBounds(neighborRow, neighborCol, rows, cols)) {
                count++;
            }
        }
        return count;
    }

    private boolean isWithinBounds(int r, int c, int maxR, int maxC) {
        return r >= 0 && r < maxR && c >= 0 && c < maxC;
    }
}

