/**
 * A program to validate if a grid of values satisfies the condition:
 * every cell value must be less than or equal to its number of adjacent neighbors.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int testCases = reader.nextInt();
            while (testCases-- > 0) {
                GridSolver.solve(reader, writer);
            }
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Contains the logic for processing the grid problem.
     */
    static class GridSolver {
        private static final int[] DX = {1, -1, 0, 0};
        private static final int[] DY = {0, 0, 1, -1};

        public static void solve(FastReader reader, PrintWriter writer) throws IOException {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            int[][] grid = new int[rows][cols];

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = reader.nextInt();
                }
            }

            int[][] neighborCount = new int[rows][cols];
            boolean isValid = true;

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    int neighbors = countNeighbors(i, j, rows, cols);
                    neighborCount[i][j] = neighbors;

                    // If the provided value is greater than the possible neighbors, it's invalid
                    if (grid[i][j] > neighbors) {
                        isValid = false;
                    }
                }
            }

            if (!isValid) {
                writer.println("NO");
            } else {
                writer.println("YES");
                printGrid(neighborCount, writer);
            }
        }

        private static int countNeighbors(int r, int c, int maxR, int maxC) {
            int count = 0;
            for (int i = 0; i < 4; i++) {
                int nextR = r + DX[i];
                int nextC = c + DY[i];

                if (nextR >= 0 && nextR < maxR && nextC >= 0 && nextC < maxC) {
                    count++;
                }
            }
            return count;
        }

        private static void printGrid(int[][] matrix, PrintWriter writer) {
            for (int[] row : matrix) {
                for (int j = 0; j < row.length; j++) {
                    writer.print(row[j] + (j == row.length - 1 ? "" : " "));
                }
                writer.println();
            }
        }
    }

