/**
 * Solves the grid validation and transformation problem.
 * The goal is to check if a grid's values respect specific boundary constraints
 * and, if so, output a standardized grid based on cell positions.
 */
public class GridProblemSolver {

    public static void main(String[] args) {
        InputReader reader = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int testCases = reader.nextInt();
            for (int t = 0; t < testCases; t++) {
                processTestCase(reader, out);
            }
        } catch (Exception e) {
            // In a production environment, use a logger.
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Orchestrates the logic for a single test case.
     */
    private static void processTestCase(InputReader reader, PrintWriter out) {
        int rowCount = reader.nextInt();
        int colCount = reader.nextInt();
        int[][] grid = reader.readGrid(rowCount, colCount);

        if (isValid(grid, rowCount, colCount)) {
            out.println("YES");
            printResultGrid(grid, rowCount, colCount, out);
        } else {
            out.println("NO");
        }
    }

    /**
     * Validates if the grid adheres to the following constraints:
     * - Corners must be <= 2
     * - Edges (excluding corners) must be <= 3
     * - Interior cells must be <= 4
     */
    private static boolean isValid(int[][] grid, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int value = grid[i][j];
                boolean isCorner = (i == 0 || i == rows - 1) && (j == 0 || j == cols - 1);
                boolean isEdge = (i == 0 || i == rows - 1 || j == 0 || j == cols - 1);

                if (isCorner && value > 2) return false;
                if (isEdge && !isCorner && value > 3) return false;
                if (!isEdge && value > 4) return false;
            }
        }
        return true;
    }

    /**
     * Prints the transformed grid.
     * The transformation logic:
     * - Corner: 2
     * - Edge: 3
     * - Interior: 4
     */
    private static void printResultGrid(int[][] grid, int rows, int cols, PrintWriter out) {
        for (int i = 0; i < rows; i++) {
            StringBuilder rowBuilder = new StringBuilder();
            for (int j = 0; j < cols; j++) {
                int cellValue = 4;
                if (i == 0 || i == rows - 1) cellValue--;
                if (j == 0 || j == cols - 1) cellValue--;

                rowBuilder.append(cellValue);
                if (j < cols - 1) {
                    rowBuilder.append(" ");
                }
            }
            out.println(rowBuilder.toString());
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = new StringTokenizer("");
        }

        public String next() {
            while (!tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public int[][] readGrid(int rows, int cols) {
            int[][] grid = new int[rows][cols];
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = nextInt();
                }
            }
            return grid;
        }
    }
}

import java.util.Scanner;

/**
 * A program that validates a grid based on specific boundary and interior constraints
 * and prints a standardized grid if the input is valid.
 */
public class GridValidator {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int testCases = scanner.nextInt();

        while (testCases-- > 0) {
            processTestCase(scanner);
        }

        scanner.close();
    }

    /**
     * Handles the logic for a single test case.
     */
    private static void processTestCase(Scanner scanner) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        int[][] grid = new int[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                grid[i][j] = scanner.nextInt();
            }
        }

        if (isValidGrid(grid, rows, cols)) {
            System.out.println("YES");
            printResultGrid(rows, cols);
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Validates if the grid adheres to the following rules:
     * - Corners must be <= 2
     * - Edges must be <= 3
     * - Interior cells must be <= 4
     */
    private static boolean isValidGrid(int[][] grid, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int value = grid[r][c];

                if (isCorner(r, c, rows, cols)) {
                    if (value > 2) return false;
                } else if (isEdge(r, c, rows, cols)) {
                    if (value > 3) return false;
                } else {
                    if (value > 4) return false;
                }
            }
        }
        return true;
    }

    /**
     * Checks if a cell is a corner of the grid.
     */
    private static boolean isCorner(int r, int c, int rows, int cols) {
        return (r == 0 || r == rows - 1) && (c == 0 || c == cols - 1);
    }

    /**
     * Checks if a cell is on the boundary (edge) but not a corner.
     */
    private static boolean isEdge(int r, int c, int rows, int cols) {
        return r == 0 || r == rows - 1 || c == 0 || c == cols - 1;
    }

    /**
     * Prints the standardized grid pattern:
     * 2 for corners, 3 for edges, 4 for interior.
     */
    private static void printResultGrid(int rows, int cols) {
        StringBuilder output = new StringBuilder();

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (isCorner(r, c, rows, cols)) {
                    output.append(2);
                } else if (isEdge(r, c, rows, cols)) {
                    output.append(3);
                } else {
                    output.append(4);
                }

                // Add space between numbers, but not at the end of the line
                if (c < cols - 1) {
                    output.append(" ");
                }
            }
            output.append("\n");
        }
        System.out.print(output.toString());
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the grid requirement problem.
 * The goal is to produce a 0/1 grid such that every cell (i, j) 
 * has exactly grid[i][j] neighbors that are 1.
 */
public class GridRequirementSolver {

    private static final int[][] DIRECTIONS = {
            {0, 1}, {0, -1}, {1, 0}, {-1, 0}
    };

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int testCases = reader.nextInt();
        while (testCases-- > 0) {
            solve(reader, out);
        }
        out.flush();
        out.close();
    }

    private static void solve(FastReader reader, PrintWriter out) {
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        int[][] requirements = new int[rows][cols];
        int[][] resultGrid = new int[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                requirements[i][j] = reader.nextInt();
                // If a cell has a requirement > 0, it must be a 1 in the final grid
                if (requirements[i][j] > 0) {
                    resultGrid[i][j] = 1;
                }
            }
        }

        if (tryBuildValidGrid(rows, cols, requirements, resultGrid)) {
            out.println("YES");
            printGrid(resultGrid, out);
        } else {
            out.println("NO");
        }
    }

    /**
     * Attempts to fill the result grid to satisfy all requirements.
     */
    private static boolean tryBuildValidGrid(int rows, int cols, int[][] req, int[][] res) {
        // Step 1: Satisfy requirements by adding 1s to neighbors
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (req[r][c] > 0) {
                    int currentNeighbors = countNonZeroNeighbors(r, c, rows, cols, res);

                    if (currentNeighbors > req[r][c]) {
                        return false; // Already too many neighbors
                    }

                    if (currentNeighbors < req[r][c]) {
                        int needed = req[r][c] - currentNeighbors;
                        if (!fillRequiredNeighbors(r, c, needed, rows, cols, res)) {
                            return false; // Not enough neighbors available to fill
                        }
                    }
                }
            }
        }

        // Step 2: Final validation pass
        // Ensure every single cell (including 0-requirement cells) matches exactly
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (countNonZeroNeighbors(r, c, rows, cols, res) != req[r][c]) {
                    return false;
                }
            }
        }

        return true;
    }

    private static boolean fillRequiredNeighbors(int r, int c, int needed, int rows, int cols, int[][] res) {
        int added = 0;
        for (int[] dir : DIRECTIONS) {
            if (added == needed) break;

            int nr = r + dir[0];
            int nc = c + dir[1];

            if (isValid(nr, nc, rows, cols) && res[nr][nc] == 0) {
                res[nr][nc] = 1;
                added++;
            }
        }
        return added == needed;
    }

    private static int countNonZeroNeighbors(int r, int c, int rows, int cols, int[][] grid) {
        int count = 0;
        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            if (isValid(nr, nc, rows, cols) && grid[nr][nc] != 0) {
                count++;
            }
        }
        return count;
    }

    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private static void printGrid(int[][] grid, PrintWriter out) {
        for (int[] row : grid) {
            for (int j = 0; j < row.length; j++) {
                out.print(row[j] + (j == row.length - 1 ? "" : " "));
            }
            out.println();
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

