        } catch (NumberFormatException | IOException e) {
            // In a production environment, use a logger
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Handles a single test case.
     */
    private static void solve(FastReader reader, PrintWriter out) throws IOException {
        String line = reader.readLine();
        if (line == null) return;

        StringTokenizer st = new StringTokenizer(line);
        int rows = Integer.parseInt(st.nextToken());
        int cols = Integer.parseInt(st.nextToken());

        int[][] grid = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            st = new StringTokenizer(reader.readLine());
            for (int j = 0; j < cols; j++) {
                grid[i][j] = Integer.parseInt(st.nextToken());
            }
        }

        if (processGrid(grid, rows, cols)) {
            out.println("YES");
            printGrid(grid, rows, cols, out);
        } else {
            out.println("NO");
        }
    }

    /**
     * Performs the two-pass transformation and validation logic.
     * 
     * @return true if the grid satisfies the conditions, false otherwise.
     */
    private static boolean processGrid(int[][] grid, int rows, int cols) {
        // Pass 1: Replace all zeros with the count of their positive neighbors
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 0) {
                    grid[r][c] = countPositiveNeighbors(grid, r, c, rows, cols);
                }
            }
        }

        // Pass 2: Validate existing positive values and update them
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] > 0) {
                    int neighborCount = countPositiveNeighbors(grid, r, c, rows, cols);

                    // If the current value is greater than the actual neighbor count, it's invalid
                    if (neighborCount < grid[r][c]) {
                        return false;
                    }
                    // Update cell with the count as per original logic
                    grid[r][c] = neighborCount;
                }
            }
        }
        return true;
    }

    /**
     * Counts how many adjacent cells (Up, Down, Left, Right) have a value > 0.
     */
    private static int countPositiveNeighbors(int[][] grid, int r, int c, int rows, int cols) {
        int count = 0;
        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];

            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
                if (grid[nr][nc] > 0) {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Utility to print the grid to the output stream.
     */
    private static void printGrid(int[][] grid, int rows, int cols, PrintWriter out) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                sb.append(grid[i][j]);
                if (j < cols - 1) {
                    sb.append(" ");
                }
            }
            sb.append("\n");
        }
        out.print(sb.toString());
    }

    /**
     * Fast I/O class for efficient reading of large inputs.
     */
    static class FastReader {
        private BufferedReader reader;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String readLine() throws IOException {
            return reader.readLine();
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A program to validate if a grid of integers can exist such that each cell
 * contains a value less than or equal to its number of neighbors.
 */
public class GridNeighborProblem {

    // Direction vectors for adjacent cells (Right, Left, Down, Up)
    private static final int[] ROW_OFFSETS = {0, 0, 1, -1};
    private static final int[] COL_OFFSETS = {1, -1, 0, 0};

    public static void main(String[] args) {
        try (FastReader reader = new FastReader(System.in);
             PrintWriter writer = new PrintWriter(System.out)) {

            int testCases = reader.nextInt();
            while (testCases-- > 0) {
                processTestCase(reader, writer);
            }
            writer.flush();
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Handles the logic for a single test case.
     */
    private static void processTestCase(FastReader reader, PrintWriter writer) throws IOException {
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        int[][] inputGrid = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            inputGrid[i] = reader.nextIntArray(cols);
        }

        int[][] neighborCounts = computeMaxNeighbors(rows, cols);

        if (isConfigurationPossible(inputGrid, neighborCounts)) {
            writer.println("YES");
            printGrid(writer, neighborCounts);
        } else {
            writer.println("NO");
        }
    }

    /**
     * Calculates the physical number of neighbors available for every cell in the grid.
     */
    private static int[][] computeMaxNeighbors(int rows, int cols) {
        int[][] neighborCounts = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int count = 0;
                for (int i = 0; i < 4; i++) {
                    int nr = r + ROW_OFFSETS[i];
                    int nc = c + COL_OFFSETS[i];
                    if (isWithinBounds(nr, nc, rows, cols)) {
                        count++;
                    }
                }
                neighborCounts[r][c] = count;
            }
        }
        return neighborCounts;
    }

    /**
     * Checks if the input grid values are all within the physical bounds of available neighbors.
     */
    private static boolean isConfigurationPossible(int[][] grid, int[][] maxNeighbors) {
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[0].length; j++) {
                if (grid[i][j] > maxNeighbors[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    private static boolean isWithinBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Prints the 2D array in the required space-separated format.
     */
    private static void printGrid(PrintWriter writer, int[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                writer.print(grid[i][j] + (j == cols - 1 ? "" : " "));
            }
            writer.println();
        }
    }

    /**
     * Fast I/O utility class.
     */
    public static class FastReader implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            this.reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public int[] nextIntArray(int n) throws IOException {
            int[] array = new int[n];
            for (int i = 0; i < n; i++) {
                array[i] = nextInt();
            }
            return array;
        }

        @Override
        public void close() throws IOException {
            reader.close();
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A solution to validate if a grid adheres to specific boundary constraints.
 * Constraints:
 * - Corners must be 2
 * - Edges (excluding corners) must be 3
 * - Interior cells must be 4
 * - Input values must not exceed these values.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        int testCases = reader.nextInt();

        while (testCases-- > 0) {
            int rowCount = reader.nextInt();
            int colCount = reader.nextInt();

            GridValidator validator = new GridValidator(rowCount, colCount);
            validator.process(reader);
        }
    }

    /**
     * Handles the logic for validating the input grid and printing the result.
     */
    static class GridValidator {
        private final int rows;
        private final int cols;

        public GridValidator(int rows, int cols) {
            this.rows = rows;
            this.cols = cols;
        }

        /**
         * Reads the input grid and determines if it matches the expected template.
         * @param reader The fast input reader.
         */
        public void process(FastReader reader) {
            boolean isInputValid = true;

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    int inputValue = reader.nextInt();
                    if (inputValue > getExpectedValue(i, j)) {
                        isInputValid = false;
                    }
                }
            }

            if (!isInputValid) {
                System.out.println("NO");
            } else {
                System.out.println("YES");
                System.out.println(generateTemplateString());
            }
        }

        /**
         * Calculates the expected value for a specific cell based on its position.
         * 
         * @param r current row index
         * @param c current column index
         * @return 2 for corners, 3 for edges, 4 for interior
         */
        private int getExpectedValue(int r, int c) {
            boolean isRowEdge = (r == 0 || r == rows - 1);
            boolean isColEdge = (c == 0 || c == cols - 1);

            if (isRowEdge && isColEdge) {
                return 2; // Corner
            } else if (isRowEdge || isColEdge) {
                return 3; // Edge
            } else {
                return 4; // Interior
            }
        }

        /**
         * Generates the entire valid template grid as a single String.
         * Using StringBuilder is significantly faster than multiple System.out.print calls.
         */
        private String generateTemplateString() {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    sb.append(getExpectedValue(i, j));
                    if (j < cols - 1) {
                        sb.append(" ");
                    }
                }
                sb.append("\n");
            }
            return sb.toString();
        }
    }

    /**
     * Optimized reader for fast input processing.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A program to validate and generate a grid of constraints based on position.
 * Corners must be <= 2, edges <= 3, and interior cells <= 4.
 */
public class Main {

    public static void main(String[] args) {
        new Main().run();
    }

    public void run() {
        File inputFile = new File("input.txt");
        File outputFile = new File("output.txt");

        // Use try-with-resources for automatic management of IO streams
        try (
            FastReader reader = new FastReader(inputFile);
            PrintWriter writer = (outputFile.exists()) 
                ? new PrintWriter(new BufferedWriter(new FileWriter(outputFile))) 
                : new PrintWriter(System.out)
        ) {
            String firstToken = reader.next();
            if (firstToken == null) return;

            int testCases = Integer.parseInt(firstToken);

            while (testCases-- > 0) {
                processTestCase(reader, writer);
            }

            writer.flush();
        } catch (Exception e) {
            System.err.println("Critical Error: " + e.getMessage());
        }
    }

    private void processTestCase(FastReader reader, PrintWriter writer) throws IOException {
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        int[][] grid = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                grid[i][j] = reader.nextInt();
            }
        }

        GridSolver solver = new GridSolver(grid);
        GridResult result = solver.solve();

        if (result.isSuccess()) {
            writer.println("YES");
            printMatrix(result.getMatrix(), writer);
        } else {
            writer.println("NO");
        }
    }

    private void printMatrix(int[][] matrix, PrintWriter writer) {
        for (int[] row : matrix) {
            for (int j = 0; j < row.length; j++) {
                writer.print(row[j] + (j == row.length - 1 ? "" : " "));
            }
            writer.println();
        }
    }

    /**
     * Domain logic for solving the Grid problem.
     */
    static class GridSolver {
        private static final int CORNER_LIMIT = 2;
        private static final int EDGE_LIMIT = 3;
        private static final int INTERIOR_LIMIT = 4;

        private final int[][] inputGrid;
        private final int rows;
        private final int cols;

        public GridSolver(int[][] inputGrid) {
            this.inputGrid = inputGrid;
            this.rows = inputGrid.length;
            this.cols = inputGrid[0].length;
        }

        public GridResult solve() {
            int[][] resultMatrix = new int[rows][cols];

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    int limit = calculateLimit(r, c);
                    if (inputGrid[r][c] > limit) {
                        return GridResult.failure();
                    }
                    resultMatrix[r][c] = limit;
                }
            }
            return GridResult.success(resultMatrix);
        }

        private int calculateLimit(int r, int c) {
            boolean isRowEdge = (r == 0 || r == rows - 1);
            boolean isColEdge = (c == 0 || c == cols - 1);

            if (isRowEdge && isColEdge) return CORNER_LIMIT;
            if (isRowEdge || isColEdge) return EDGE_LIMIT;
            return INTERIOR_LIMIT;
        }
    }

    /**
     * Result wrapper to avoid returning null or multiple values.
     */
    static class GridResult {
        private final boolean success;
        private final int[][] matrix;

        private GridResult(boolean success, int[][] matrix) {
            this.success = success;
            this.matrix = matrix;
        }

        public static GridResult success(int[][] matrix) {
            return new GridResult(true, matrix);
        }

        public static GridResult failure() {
            return new GridResult(false, null);
        }

        public boolean isSuccess() { return success; }
        public int[][] getMatrix() { return matrix; }
    }

    /**
     * Utility for fast input reading.
     */
    static class FastReader implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(File file) throws FileNotFoundException {
            if (file.exists()) {
                this.reader = new BufferedReader(new FileReader(file));
            } else {
                this.reader = new BufferedReader(new InputStreamReader(System.in));
            }
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String val = next();
            return val == null ? 0 : Integer.parseInt(val);
        }

        @Override
        public void close() throws IOException {
            reader.close();
        }
    }
}

import java.io.*;
