/**
 * Solution for the Grid Validation and Pattern Generation problem.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            int testCases = reader.nextInt();
            GridSolver solver = new GridSolver();

            while (testCases-- > 0) {
                int rows = reader.nextInt();
                int cols = reader.nextInt();
                int[][] grid = new int[rows][cols];

                for (int i = 0; i < rows; i++) {
                    for (int j = 0; j < cols; j++) {
                        grid[i][j] = reader.nextInt();
                    }
                }

                GridSolution solution = solver.solve(rows, cols, grid);
                writer.println(solution.isPossible() ? "YES" : "NO");
                if (solution.isPossible()) {
                    writer.print(solution.getGridOutput());
                }
            }
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    /**
     * Handles high-performance input reading.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    /**
     * Represents the outcome of a single test case.
     */
    static class GridSolution {
        private final boolean possible;
        private final String gridOutput;

        public GridSolution(boolean possible, String gridOutput) {
            this.possible = possible;
            this.gridOutput = gridOutput;
        }

        public boolean isPossible() {
            return possible;
        }

        public String getGridOutput() {
            return gridOutput;
        }
    }

    /**
     * Contains the business logic for validating the grid and generating the pattern.
     */
    static class GridSolver {
        // Threshold constants for validation
        private static final int CORNER_LIMIT = 2;
        private static final int EDGE_LIMIT = 3;
        private static final int INNER_LIMIT = 4;

        // Values for the output pattern
        private static final int CORNER_VAL = 2;
        private static final int EDGE_VAL = 3;
        private static final int INNER_VAL = 4;

        public GridSolution solve(int rows, int cols, int[][] grid) {
            if (!isValid(rows, cols, grid)) {
                return new GridSolution(false, "");
            }
            return new GridSolution(true, generatePattern(rows, cols));
        }

        private boolean isValid(int rows, int cols, int[][] grid) {
            // 1. Validate Corners
            if (grid[0][0] > CORNER_LIMIT || grid[0][cols - 1] > CORNER_LIMIT ||
                grid[rows - 1][0] > CORNER_LIMIT || grid[rows - 1][cols - 1] > CORNER_LIMIT) {
                return false;
            }

            // 2. Validate Edges (Top and Bottom)
            for (int j = 1; j < cols - 1; j++) {
                if (grid[0][j] > EDGE_LIMIT || grid[rows - 1][j] > EDGE_LIMIT) {
                    return false;
                }
            }

            // 3. Validate Edges (Left and Right)
            for (int i = 1; i < rows - 1; i++) {
                if (grid[i][0] > EDGE_LIMIT || grid[i][cols - 1] > EDGE_LIMIT) {
                    return false;
                }
            }

            // 4. Validate Interior
            for (int i = 1; i < rows - 1; i++) {
                for (int j = 1; j < cols - 1; j++) {
                    if (grid[i][j] > INNER_LIMIT) {
                        return false;
                    }
                }
            }

            return true;
        }

        private String generatePattern(int rows, int cols) {
            StringBuilder sb = new StringBuilder();

            // Generate Top Row
            sb.append(CORNER_VAL);
            for (int j = 1; j < cols - 1; j++) {
                sb.append(" ").append(EDGE_VAL);
            }
            sb.append(" ").append(CORNER_VAL).append("\n");

            // Generate Middle Rows
            for (int i = 1; i < rows - 1; i++) {
                sb.append(EDGE_VAL);
                for (int j = 1; j < cols - 1; j++) {
                    sb.append(" ").append(INNER_VAL);
                }
                sb.append(" ").append(EDGE_VAL).append("\n");
            }

            // Generate Bottom Row
            sb.append(CORNER_VAL);
            for (int j = 1; j < cols - 1; j++) {
                sb.append(" ").append(EDGE_VAL);
            }
            sb.append(" ").append(CORNER_VAL).append("\n");

            return sb.toString();
        }
    }
}

import java.util.Scanner;

/**
 * A utility to validate if a grid's values are within the limits 
 * of their physical neighbor counts.
 */
public class GridNeighborValidator {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int testCases = scanner.nextInt();

        while (testCases-- > 0) {
            processTestCase(scanner);
        }

        scanner.close();
    }

    /**
     * Handles the logic for a single test case.
     */
    private static void processTestCase(Scanner scanner) {
        if (!scanner.hasNextInt()) return;

        int cols = scanner.nextInt();
        int rows = scanner.nextInt();

        int[][] grid = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                grid[r][c] = scanner.nextInt();
            }
        }

        int[][] neighborGrid = new int[rows][cols];
        boolean isPossible = true;

        // Validate grid and prepare the neighbor count grid
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int neighbors = getNeighborCount(r, c, rows, cols);
                neighborGrid[r][c] = neighbors;

                // If the cell value exceeds the number of possible neighbors, it's invalid
                if (grid[r][c] > neighbors) {
                    isPossible = false;
                }
            }
        }

        if (isPossible) {
            System.out.println("YES");
            printGrid(neighborGrid);
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Calculates the number of adjacent neighbors (Up, Down, Left, Right) 
     * for a given cell.
     */
    private static int getNeighborCount(int row, int col, int totalRows, int totalCols) {
        int count = 0;
        if (row > 0) count++;             // Up
        if (row < totalRows - 1) count++; // Down
        if (col > 0) count++;             // Left
        if (col < totalCols - 1) count++; // Right
        return count;
    }

    /**
     * Prints the grid in a standard row-major format.
     */
    private static void printGrid(int[][] grid) {
        StringBuilder sb = new StringBuilder();
        int rows = grid.length;
        int cols = grid[0].length;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                sb.append(grid[r][c]);
                if (c < cols - 1) {
                    sb.append(" ");
                }
            }
            sb.append("\n");
        }
        System.out.print(sb.toString());
    }
}

import java.util.*;
import java.io.*;

/**
 * A utility class to solve grid-based constraint problems.
 * The goal is to determine if a grid can be transformed into a specific pattern 
 * (corners=2, edges=3, interior=4) based on provided upper bounds.
 */
public class GridSolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int testCases = reader.nextInt();
            while (testCases-- > 0) {
                solve(reader, writer);
            }
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Processes a single test case.
     */
    private static void solve(FastReader reader, PrintWriter writer) throws IOException {
        int rows = reader.nextInt();
        int cols = reader.nextInt();
        int[][] grid = new int[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                grid[i][j] = reader.nextInt();
            }
        }

        if (isConfigurationValid(grid, rows, cols)) {
            writer.println("YES");
            printResultGrid(grid, rows, cols, writer);
        } else {
            writer.println("NO");
        }
    }

    /**
     * Validates if the input grid meets the specific constraints:
     * 1. All cells must be <= 4.
     * 2. Corners must be < 3.
     * 3. Edge cells (excluding corners) must be < 4.
     */
    private static boolean isConfigurationValid(int[][] grid, int rows, int cols) {
        // 1. General constraint: all cells must be <= 4
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] > 4) {
                    return false;
                }
            }
        }

        // 2. Corner constraints: (0,0), (0, col-1), (row-1, col-1), (row-1, 0)
        if (grid[0][0] >= 3 || 
            grid[0][cols - 1] >= 3 || 
            grid[rows - 1][cols - 1] >= 3 || 
            grid[rows - 1][0] >= 3) {
            return false;
        }

        // 3. Edge constraints (excluding corners)
        // Top and Bottom edges
        for (int j = 1; j < cols - 1; j++) {
            if (grid[0][j] >= 4 || grid[rows - 1][j] >= 4) {
                return false;
            }
        }
        // Left and Right edges
        for (int i = 1; i < rows - 1; i++) {
            if (grid[i][0] >= 4 || grid[i][cols - 1] >= 4) {
                return false;
            }
        }

        return true;
    }

    /**
     * Constructs and prints the target pattern grid:
     * Corners = 2, Edges = 3, Interior = 4.
     */
    private static void printResultGrid(int[][] grid, int rows, int cols, PrintWriter writer) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int value;
                if (isCorner(i, j, rows, cols)) {
                    value = 2;
                } else if (isEdge(i, j, rows, cols)) {
                    value = 3;
                } else {
                    value = 4;
                }
                writer.print(value + (j == cols - 1 ? "" : " "));
            }
            writer.println();
        }
    }

    private static boolean isCorner(int r, int c, int rows, int cols) {
        return (r == 0 || r == rows - 1) && (c == 0 || c == cols - 1);
    }

    private static boolean isEdge(int r, int c, int rows, int cols) {
        return (r == 0 || r == rows - 1 || c == 0 || c == cols - 1);
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

