/**
 * Logic for constructing a palindrome with a specific count of zeros and ones.
 */
class PalindromeConstructor {

    /**
     * Attempts to construct a palindrome of length (targetZeros + targetOnes) 
     * that matches the provided sequence pattern.
     * 
     * @param targetZeros The exact number of '0' characters required.
     * @param targetOnes  The exact number of '1' characters required.
     * @param sequence    The input pattern containing '0', '1', or '?'.
     * @return A valid palindrome string, or "-1" if no such palindrome exists.
     */
    public String construct(int targetZeros, int targetOnes, String sequence) {
        int n = sequence.length();
        char[] chars = sequence.toCharArray();

        // Phase 1: Enforce palindrome symmetry and validate existing characters
        for (int i = 0; i < n / 2; i++) {
            int oppositeIndex = n - 1 - i;
            if (chars[i] != '?' && chars[oppositeIndex] != '?') {
                if (chars[i] != chars[oppositeIndex]) {
                    return "-1"; // Conflict: fixed characters are not symmetric
                }
            } else if (chars[i] != '?') {
                chars[oppositeIndex] = chars[i];
            } else if (chars[oppositeIndex] != '?') {
                chars[i] = chars[oppositeIndex];
            }
        }

        // Phase 2: Count existing fixed characters
        int currentZeros = 0;
        int currentOnes = 0;
        for (char c : chars) {
            if (c == '0') currentZeros++;
            else if (c == '1') currentOnes++;
        }

        int remainingZeros = targetZeros - currentZeros;
        int remainingOnes = targetOnes - currentOnes;

        // If we already exceeded the target counts
        if (remainingZeros < 0 || remainingOnes < 0) {
            return "-1";
        }

        // Phase 3: Handle the middle element for odd-length palindromes
        if (n % 2 != 0) {
            int midIndex = n / 2;
            if (chars[midIndex] == '?') {
                // The middle element must resolve the parity so remaining counts are even (for pairs)
                if (remainingZeros > 0 && (remainingZeros - 1) % 2 == 0 && remainingOnes % 2 == 0) {
                    chars[midIndex] = '0';
                    remainingZeros--;
                } else if (remainingOnes > 0 && remainingZeros % 2 == 0 && (remainingOnes - 1) % 2 == 0) {
                    chars[midIndex] = '1';
                    remainingOnes--;
                } else {
                    return "-1";
                }
            }
        }

        // Phase 4: Fill the remaining '?' pairs
        for (int i = 0; i < n / 2; i++) {
            int oppositeIndex = n - 1 - i;
            if (chars[i] == '?') {
                // We must fill in pairs of '0's or '1's to maintain symmetry
                if (remainingZeros >= 2) {
                    chars[i] = chars[oppositeIndex] = '0';
                    remainingZeros -= 2;
                } else if (remainingOnes >= 2) {
                    chars[i] = chars[oppositeIndex] = '1';
                    remainingOnes -= 2;
                } else {
                    return "-1"; // Not enough characters to form a symmetric pair
                }
            }
        }

        // Phase 5: Final verification
        if (remainingZeros != 0 || remainingOnes != 0) {
            return "-1";
        }

        return new String(chars);
    }
}

