/**
 * A refactored solution to solve the palindrome construction problem.
 * The goal is to construct a palindrome of a given length using a specific
 * number of '0's and '1's, replacing '?' characters in the input string.
 */
public final class Solution {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        int testCases = reader.nextInt();
        while (testCases-- > 0) {
            solve(reader, writer);
        }

        writer.flush();
        writer.close();
    }

    /**
     * Processes a single test case.
     *
     * @param reader The fast input reader.
     * @param writer The output writer.
     */
    private static void solve(FastReader reader, PrintWriter writer) {
        int zerosNeeded = reader.nextInt();
        int onesNeeded = reader.nextInt();
        String input = reader.next();
        int n = input.length();

        // The problem logic only processes if the sum of required characters 
        // matches the string length.
        if (zerosNeeded + onesNeeded != n) {
            return;
        }

        String result = constructPalindrome(zerosNeeded, onesNeeded, input);
        writer.println(result);
    }

    /**
     * Logic to construct the palindrome based on the given constraints.
     *
     * @param targetZeros Total zeros required in the final string.
     * @param targetOnes  Total ones required in the final string.
     * @param s           The input string containing '0', '1', and '?'.
     * @return The constructed palindrome or "-1" if impossible.
     */
    private static String constructPalindrome(int targetZeros, int targetOnes, String s) {
        int n = s.length();
        char[] res = s.toCharArray();

        int remZ = targetZeros;
        int remO = targetOnes;

        // Step 1: Subtract existing '0's and '1's from the required counts.
        for (int i = 0; i < n; i++) {
            if (res[i] == '0') {
                remZ--;
            } else if (res[i] == '1') {
                remO--;
            }
        }

        // If existing characters exceed requirements, it's impossible.
        if (remZ < 0 || remO < 0) {
            return "-1";
        }

        // Step 2: Handle fixed characters and '?' forced by a fixed counterpart.
        for (int i = 0; i < n / 2; i++) {
            int left = i;
            int right = n - i - 1;
            char l = res[left];
            char r = res[right];

            if (l != '?' && r != '?') {
                // Both are fixed: they must match for a palindrome.
                if (l != r) return "-1";
            } else if (l == '?' && r != '?') {
                // Left is '?', right is fixed: left must match right.
                res[left] = r;
                if (r == '0') remZ--;
                else remO--;
            } else if (r == '?' && l != '?') {
                // Right is '?', left is fixed: right must match left.
                res[right] = l;
                if (l == '0') remZ--;
                else remO--;
            }

            // If requirements are violated during this step.
            if (remZ < 0 || remO < 0) return "-1";
        }

        // Step 3: Handle pairs where both characters are '?'.
        for (int i = 0; i < n / 2; i++) {
            int left = i;
            int right = n - i - 1;
            if (res[left] == '?' && res[right] == '?') {
                if (remZ >= 2) {
                    res[left] = res[right] = '0';
                    remZ -= 2;
                } else if (remO >= 2) {
                    res[left] = res[right] = '1';
                    remO -= 2;
                } else {
                    return "-1";
                }
            }
        }

        // Step 4: Handle the middle character for odd-length strings.
        if (n % 2 != 0) {
            int mid = n / 2;
            if (res[mid] == '?') {
                if (remZ > 0) {
                    res[mid] = '0';
                    remZ--;
                } else if (remO > 0) {
                    res[mid] = '1';
                    remO--;
                } else {
                    return "-1";
                }
            }
        }

        // Step 5: Final verification that all required characters were used.
        if (remZ != 0 || remO != 0) {
            return "-1";
        }

        return new String(res);
    }

