/**
 * A solver for the symmetry string problem.
 * The goal is to fill '?' characters in a sequence with '0' or '1' to satisfy 
 * specific counts of zeros and ones while maintaining symmetric properties.
 */
public class SymmetryStringSolver {

    private final FastReader reader;
    private final PrintWriter writer;

    public SymmetryStringSolver(InputStream inputStream, OutputStream outputStream) {
        this.reader = new FastReader(inputStream);
        this.writer = new PrintWriter(outputStream);
    }

    /**
     * Main logic to process each test case.
     */
    public void solve() {
        int zerosTarget = reader.nextInt();
        int onesTarget = reader.nextInt();
        char[] sequence = reader.next().toCharArray();
        int length = sequence.length;

        int zerosRemaining = zerosTarget;
        int onesRemaining = onesTarget;

        // 1. Initial Pass: Count existing characters and subtract from targets
        for (char c : sequence) {
            if (c == '0') zerosRemaining--;
            else if (c == '1') onesRemaining--;
        }

        // 2. Symmetry Enforcement: 
        // Ensure that if sequence[i] is fixed, sequence[n-1-i] is compatible.
        for (int i = 0; i < length / 2; i++) {
            int j = length - 1 - i;

            if (sequence[i] != '?' && sequence[j] != '?') {
                if (sequence[i] != sequence[j]) {
                    writer.println("-1");
                    return;
                }
            } else if (sequence[i] != '?' && sequence[j] == '?') {
                sequence[j] = sequence[i];
                if (sequence[i] == '0') zerosRemaining--;
                else onesRemaining--;
            } else if (sequence[i] == '?' && sequence[j] != '?') {
                sequence[i] = sequence[j];
                if (sequence[j] == '0') zerosRemaining--;
                else onesRemaining--;
            }
        }

        // 3. Fill Remaining Wildcard Pairs:
        // Handle cases where both symmetric positions are '?'
        for (int i = 0; i < length / 2; i++) {
            int j = length - 1 - i;
            if (sequence[i] == '?' && sequence[j] == '?') {
                // Greedy approach: fill the one with the higher remaining requirement
                if (zerosRemaining > onesRemaining) {
                    sequence[i] = sequence[j] = '0';
                    zerosRemaining -= 2;
                } else {
                    sequence[i] = sequence[j] = '1';
                    onesRemaining -= 2;
                }
            }
        }

        // 4. Handle Middle Element:
        // If the string length is odd, the middle element has no symmetric partner.
        if (length % 2 != 0) {
            int mid = length / 2;
            if (sequence[mid] == '?') {
                if (zerosRemaining > 0) {
                    sequence[mid] = '0';
                    zerosRemaining--;
                } else if (onesRemaining > 0) {
                    sequence[mid] = '1';
                    onesRemaining--;
                }
            }
        }

        // 5. Final Validation:
        // Check if the counts match exactly and no negative counts occurred.
        if (zerosRemaining != 0 || onesRemaining != 0) {
            writer.println("-1");
        } else {
            writer.println(new String(sequence));
        }
    }

    public void run() {
        int testCases = reader.nextInt();
        while (testCases-- > 0) {
            solve();
            writer.flush();
        }
    }

    public static void main(String[] args) {
        SymmetryStringSolver solver = new SymmetryStringSolver(System.in, System.out);
        solver.run();
    }

    /**
     * High-performance input reader for large datasets.
     */
    static class FastReader {
        private final InputStream inputStream;
        private final byte[] buffer = new byte[1024];
        private int pointer = 0;
        private int bytesRead = 0;

        public FastReader(InputStream inputStream) {
            this.inputStream = inputStream;
        }

        private int readByte() {
            if (pointer >= bytesRead) {
                pointer = 0;
                try {
                    bytesRead = inputStream.read(buffer);
                } catch (IOException e) {
                    return -1;
                }
                if (bytesRead <= 0) return -1;
            }
            return buffer[pointer++] & 0xFF;
        }

        public String next() {
            int b = skipWhitespace();
            StringBuilder sb = new StringBuilder();
            while (b != -1 && !isWhitespace(b)) {
                sb.append((char) b);
                b = readByte();
            }
            return sb.toString();
        }

        public int nextInt() {
            int b = skipWhitespace();
            boolean negative = false;
            if (b == '-') {
                negative = true;
                b = readByte();
            }
            int res = 0;
            while (b >= '0' && b <= '9') {
                res = res * 10 + (b - '0');
                b = readByte();
            }
            return negative ? -res : res;
        }

        private int skipWhitespace() {
            int b = readByte();
            while (b != -1 && isWhitespace(b)) {
                b = readByte();
            }
            return b;
        }

        private boolean isWhitespace(int b) {
            return b <= 32;
        }
    }
}

