/**
 * Solution to construct a palindrome of a specific length using 
 * an exact count of '0's and '1's, given a template with '?' wildcards.
 */
public class Solution {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int testCases = scanner.nextInt();
        Solution solver = new Solution();

        for (int i = 1; i <= testCases; i++) {
            System.out.println(solver.solve(scanner));
        }

        scanner.close();
    }

    /**
     * Solves a single test case.
     * 
     * @param scanner The input scanner.
     * @return A valid palindrome string, or "-1" if impossible.
     */
    public String solve(Scanner scanner) {
        int zerosTarget = scanner.nextInt();
        int onesTarget = scanner.nextInt();
        String template = scanner.next();

        char[] palindromeChars = template.toCharArray();
        int n = palindromeChars.length;

        // Phase 1: Ensure symmetry and fill '?' where the opposite side is a digit
        for (int i = 0; i < n / 2; i++) {
            int left = i;
            int right = n - 1 - i;

            if (palindromeChars[left] != '?' && palindromeChars[right] != '?') {
                // If both are digits, they must match to form a palindrome
                if (palindromeChars[left] != palindromeChars[right]) {
                    return "-1";
                }
            } else if (palindromeChars[left] != '?') {
                // If only the left is a digit, mirror it to the right
                palindromeChars[right] = palindromeChars[left];
            } else if (palindromeChars[right] != '?') {
                // If only the right is a digit, mirror it to the left
                palindromeChars[left] = palindromeChars[right];
            }
        }

        // Phase 2: Calculate remaining budget for '0's and '1's
        int zerosRemaining = zerosTarget;
        int onesRemaining = onesTarget;

        for (char c : palindromeChars) {
            if (c == '0') {
                zerosRemaining--;
            } else if (c == '1') {
                onesRemaining--;
            }
        }

        // If we already exceeded the target counts, it's impossible
        if (zerosRemaining < 0 || onesRemaining < 0) {
            return "-1";
        }

        // Phase 3: Fill the remaining '?' wildcards
        for (int i = 0; i < (n + 1) / 2; i++) {
            int left = i;
            int right = n - 1 - i;

            if (left == right) {
                // Handle the middle element of an odd-length string
                if (palindromeChars[left] == '?') {
                    if (zerosRemaining > 0 && onesRemaining == 0) {
                        palindromeChars[left] = '0';
                        zerosRemaining--;
                    } else if (onesRemaining > 0 && zerosRemaining == 0) {
                        palindromeChars[left] = '1';
                        onesRemaining--;
                    } else {
                        return "-1";
                    }
                }
            } else {
                // Handle pairs of symmetric elements
                if (palindromeChars[left] == '?') {
                    if (zerosRemaining >= 2) {
                        palindromeChars[left] = '0';
                        palindromeChars[right] = '0';
                        zerosRemaining -= 2;
                    } else if (onesRemaining >= 2) {
                        palindromeChars[left] = '1';
                        palindromeChars[right] = '1';
                        onesRemaining -= 2;
                    } else {
                        // Not enough budget to fill a pair symmetrically
                        return "-1";
                    }
                }
            }
        }

        // Final Validation: Ensure all required counts are exactly met
        if (zerosRemaining == 0 && onesRemaining == 0) {
            return new String(palindromeChars);
        } else {
            return "-1";
        }
    }
}

