/**
 * This program solves the problem of constructing a palindrome from a given string 
 * containing '0', '1', and '?' such that the total count of '0's and '1's 
 * matches the specified requirements.
 */
public class PalindromeConstruction {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int testCases = reader.nextInt();
        PalindromeBuilder builder = new PalindromeBuilder();

        for (int t = 0; t < testCases; t++) {
            int requiredZeros = reader.nextInt();
            int requiredOnes = reader.nextInt();
            String inputString = reader.next();

            String result = builder.build(requiredZeros, requiredOnes, inputString);
            out.println(result);
        }

        out.flush();
        out.close();
    }

    /**
     * Core logic class responsible for constructing the palindrome.
     */
    static class PalindromeBuilder {

        private static final char ZERO = '0';
        private static final char ONE = '1';
        private static final char QUESTION = '?';

        public String build(int targetZeros, int targetOnes, String s) {
            int n = s.length();
            char[] result = new char[n];
            Arrays.fill(result, QUESTION);

            int currentZeros = 0;
            int currentOnes = 0;
            boolean isPossible = true;

            // Step 1: Fill characters that are already determined by the input string
            // and check for initial palindromic consistency.
            for (int i = 0, j = n - 1; i <= j; i++, j--) {
                if (i == j) {
                    // Handle middle element for odd-length strings
                    char c = s.charAt(i);
                    if (c != QUESTION) {
                        if (c == ZERO) currentZeros++;
                        else currentOnes++;
                        result[i] = c;
                    }
                } else {
                    char c1 = s.charAt(i);
                    char c2 = s.charAt(j);

                    if (c1 != QUESTION && c2 != QUESTION) {
                        if (c1 != c2) {
                            isPossible = false;
                            break;
                        }
                        result[i] = result[j] = c1;
                        int countToAdd = 2;
                        if (c1 == ZERO) currentZeros += countToAdd;
                        else currentOnes += countToAdd;
                    } else if (c1 != QUESTION) {
                        result[i] = result[j] = c1;
                        int countToAdd = 2;
                        if (c1 == ZERO) currentZeros += countToAdd;
                        else currentOnes += countToAdd;
                    } else if (c2 != QUESTION) {
                        result[i] = result[j] = c2;
                        int countToAdd = 2;
                        if (c2 == ZERO) currentZeros += countToAdd;
                        else currentOnes += countToAdd;
                    }
                }

                // Early exit if constraints are already violated
                if (currentZeros > targetZeros || currentOnes > targetOnes) {
                    isPossible = false;
                    break;
                }
            }

            if (!isPossible) return "-1";

            // Step 2: Greedily fill the remaining '?' pairs
            for (int i = 0, j = n - 1; i < j; i++, j--) {
                if (result[i] == QUESTION) {
                    if (currentZeros + 2 <= targetZeros) {
                        result[i] = result[j] = ZERO;
                        currentZeros += 2;
                    } else if (currentOnes + 2 <= targetOnes) {
                        result[i] = result[j] = ONE;
                        currentOnes += 2;
                    } else {
                        isPossible = false;
                        break;
                    }
                }
            }

            // Step 3: Fill the middle element if it is still a '?'
            if (isPossible && n % 2 != 0 && result[n / 2] == QUESTION) {
                if (currentZeros < targetZeros) {
                    result[n / 2] = ZERO;
                    currentZeros++;
                } else if (currentOnes < targetOnes) {
                    result[n / 2] = ONE;
                    currentOnes++;
                } else {
                    isPossible = false;
                }
            }

            // Step 4: Final validation of the total counts
            if (isPossible && currentZeros == targetZeros && currentOnes == targetOnes) {
                return new String(result);
            } else {
                return "-1";
            }
        }
    }

    /**
     * Utility class for fast input reading.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
