 */
public class Main {

    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int testCases = in.nextInt();
        PalindromeTaskSolver solver = new PalindromeTaskSolver();

        while (testCases-- > 0) {
            solver.solve(in, out);
        }

        out.close();
    }

    static class PalindromeTaskSolver {

        /**
         * Solves a single test case.
         */
        public void solve(InputReader in, PrintWriter out) {
            int targetZero = in.nextInt();
            int targetOne = in.nextInt();
            char[] arr = in.next().toCharArray();
            int n = arr.length;

            // 1. Ensure the string can be a palindrome by matching known characters
            if (!enforceSymmetry(arr, n)) {
                out.println("-1");
                return;
            }

            // 2. Count current fixed characters
            int currentZero = 0;
            int currentOne = 0;
            for (char c : arr) {
                if (c == '0') currentZero++;
                else if (c == '1') currentOne++;
            }

            // 3. Determine how many '0's and '1's we still need to place
            int remZero = targetZero - currentZero;
            int remOne = targetOne - currentOne;

            // If we already exceeded the budget, it's impossible
            if (remZero < 0 || remOne < 0) {
                out.println("-1");
                return;
            }

            // 4. Identify remaining '?' slots available for filling
            int numQuestionPairs = 0;
            for (int i = 0; i < n / 2; i++) {
                if (arr[i] == '?') {
                    numQuestionPairs++;
                }
            }
            boolean middleIsQuestion = (n % 2 != 0 && arr[n / 2] == '?');
            int totalQuestionSlots = (2 * numQuestionPairs) + (middleIsQuestion ? 1 : 0);

            // Check if the remaining budget exactly matches the number of '?' slots
            if (remZero + remOne != totalQuestionSlots) {
                out.println("-1");
                return;
            }

            // 5. Parity validation: 
            // Question pairs use 2 slots, so they don't change parity.
            // A middle '?' (if exists) changes the parity of the count.
            if (n % 2 == 0) {
                // In even length, all '?' are in pairs. remZero and remOne must be even.
                if (remZero % 2 != 0 || remOne % 2 != 0) {
                    out.println("-1");
                    return;
                }
            } else {
                if (middleIsQuestion) {
                    // In odd length with a middle '?', one count must be odd, one must be even.
                    if (remZero % 2 == remOne % 2) {
                        out.println("-1");
                        return;
                    }
                } else {
                    // Middle is already fixed, so all '?' are in pairs.
                    if (remZero % 2 != 0 || remOne % 2 != 0) {
                        out.println("-1");
                        return;
                    }
                }
            }

            // 6. Fill the '?' characters
            // Fill middle element first if applicable
            if (middleIsQuestion) {
                if (remZero % 2 != 0) {
                    arr[n / 2] = '0';
                    remZero--;
                } else {
                    arr[n / 2] = '1';
                    remOne--;
                }
            }

            // Fill remaining pairs
            for (int i = 0; i < n / 2; i++) {
                int j = n - 1 - i;
                if (arr[i] == '?') {
                    if (remZero >= 2) {
                        arr[i] = arr[j] = '0';
                        remZero -= 2;
                    } else {
                        arr[i] = arr[j] = '1';
                        remOne -= 2;
                    }
                }
            }

            out.println(new String(arr));
        }

        /**
         * Fills '?' where the symmetric partner is known. 
         * Returns false if a contradiction is found.
         */
        private boolean enforceSymmetry(char[] arr, int n) {
            for (int i = 0; i < n / 2; i++) {
                int j = n - 1 - i;
                if (arr[i] != '?' && arr[j] != '?') {
                    if (arr[i] != arr[j]) return false;
                } else if (arr[i] != '?') {
                    arr[j] = arr[i];
                } else if (arr[j] != '?') {
                    arr[i] = arr[j];
                }
            }
            return true;
        }
    }

    /**
     * Fast I/O reader for efficient integer and string parsing.
     */
    static class InputReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
