import java.util.Scanner;

/**
 * A utility class to solve the problem of generating a palindrome 
 * by replacing '?' characters with '0' or '1' based on specific counts.
 */
public class PalindromeGenerator {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int testCases = scanner.nextInt();
        while (testCases-- > 0) {
            int requiredZeros = scanner.nextInt();
            int requiredOnes = scanner.nextInt();
            String pattern = scanner.next();

            System.out.println(generatePalindrome(requiredZeros, requiredOnes, pattern));
        }

        scanner.close();
    }

    /**
     * Attempts to construct a palindrome from the given pattern.
     * 
     * @param targetZeros The exact number of '0's required in the final string.
     * @param targetOnes  The exact number of '1's required in the final string.
     * @param pattern     The input string containing '0', '1', or '?'.
     * @return The valid palindrome string, or "-1" if no such string exists.
     */
    public static String generatePalindrome(int targetZeros, int targetOnes, String pattern) {
        int n = pattern.length();
        char[] chars = pattern.toCharArray();

        // Phase 1: Enforce palindrome symmetry
        // If one side of the pair is fixed, the other side MUST match it.
        if (!enforceSymmetry(chars, n)) {
            return "-1";
        }

        // Phase 2: Count current character distribution
        int currentZeros = 0;
        int currentOnes = 0;
        for (char c : chars) {
            if (c == '0') currentZeros++;
            else if (c == '1') currentOnes++;
        }

        // If we already exceeded the requirements, it's impossible
        if (currentZeros > targetZeros || currentOnes > targetOnes) {
            return "-1";
        }

        int remainingZeros = targetZeros - currentZeros;
        int remainingOnes = targetOnes - currentOnes;

        // Phase 3: Fill remaining '?' characters
        // We iterate through pairs to fill '??' or single middle '?'
        if (!fillRemainingQuestions(chars, n, remainingZeros, remainingOnes)) {
            return "-1";
        }

        // Final validation to ensure we used exactly the required amount
        if (isTargetMet(chars, targetZeros, targetOnes)) {
            return new String(chars);
        }

        return "-1";
    }

    /**
     * Ensures that existing characters in the pattern do not violate palindrome rules.
     * If one character in a pair is fixed, the other is updated to match.
     */
    private static boolean enforceSymmetry(char[] chars, int n) {
        for (int i = 0; i < n / 2; i++) {
            int left = i;
            int right = n - 1 - i;

            if (chars[left] != '?' && chars[right] != '?') {
                if (chars[left] != chars[right]) {
                    return false;
                }
            } else if (chars[left] != '?' && chars[right] == '?') {
                chars[right] = chars[left];
            } else if (chars[left] == '?' && chars[right] != '?') {
                chars[left] = chars[right];
            }
        }
        return true;
    }

    /**
     * Greedily fills the '?' pairs and the middle element.
     */
    private static boolean fillRemainingQuestions(char[] chars, int n, int remZeros, int remOnes) {
        // Note: remZeros and remOnes are local copies, we need to track changes.
        // Using an array to simulate pass-by-reference for the counts.
        int[] counts = {remZeros, remOnes};

        for (int i = 0; i < (n + 1) / 2; i++) {
            int left = i;
            int right = n - 1 - i;

            if (left == right) {
                // Handle middle element for odd-length strings
                if (chars[left] == '?') {
                    if (counts[0] == 1) {
                        chars[left] = '0';
                        counts[0]--;
                    } else if (counts[1] == 1) {
                        chars[left] = '1';
                        counts[1]--;
                    } else {
                        return false;
                    }
                }
            } else {
                // Handle pairs
                if (chars[left] == '?' && chars[right] == '?') {
                    if (counts[0] >= 2) {
                        chars[left] = '0';
                        chars[right] = '0';
                        counts[0] -= 2;
                    } else if (counts[1] >= 2) {
                        chars[left] = '1';
                        chars[right] = '1';
                        counts[1] -= 2;
                    } else {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    /**
     * Final verification to ensure the resulting string matches the required counts.
     */
    private static boolean isTargetMet(char[] chars, int targetZeros, int targetOnes) {
        int z = 0, o = 0;
        for (char c : chars) {
            if (c == '0') z++;
            else if (c == '1') o++;
        }
        return z == targetZeros && o == targetOnes;
    }
}

