/**
 * A solver for the Palindrome construction problem.
 * The goal is to form a palindrome of length N using exactly 'availZeros' zeros and 'availOnes' ones,
 * filling in '?' characters from the input string.
 */
public class Main {

    public static void main(String[] args) {
        FastReader in = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int t = in.nextInt();
        while (t-- > 0) {
            out.println(solve(in));
        }
        out.flush();
        out.close();
    }

    private static String solve(FastReader in) {
        int targetZeros = in.nextInt();
        int targetOnes = in.nextInt();
        int n = targetZeros + targetOnes;
        char[] chars = in.next().toCharArray();

        int usedZeros = 0;
        int usedOnes = 0;
        List<Integer> freePairIndices = new ArrayList<>();
        boolean middleIsFree = false;

        // Step 1: Validate existing characters and propagate required palindrome symmetry
        for (int i = 0; i < n / 2; i++) {
            int complementIdx = n - 1 - i;
            char a = chars[i];
            char b = chars[complementIdx];

            if (a != '?' && b != '?') {
                if (a != b) return "-1"; // Palindrome property violated
                if (a == '0') usedZeros += 2;
                else usedOnes += 2;
            } else if (a != '?') {
                // b must match a
                chars[complementIdx] = a;
                if (a == '0') usedZeros += 2;
                else usedOnes += 2;
            } else if (b != '?') {
                // a must match b
                chars[i] = b;
                if (b == '0') usedZeros += 2;
                else usedOnes += 2;
            } else {
                // Both are '?'
                freePairIndices.add(i);
            }
        }

        // Step 2: Handle the middle element for odd-length strings
        if (n % 2 != 0) {
            int mid = n / 2;
            if (chars[mid] == '0') {
                usedZeros++;
            } else if (chars[mid] == '1') {
                usedOnes++;
            } else {
                middleIsFree = true;
            }
        }

        int remZeros = targetZeros - usedZeros;
        int remOnes = targetOnes - usedOnes;

        // Step 3: Basic feasibility check
        if (remZeros < 0 || remOnes < 0) return "-1";

        // Step 4: Distribute remaining characters into free pairs and middle slot
        int freePairsCount = freePairIndices.size();

        if (middleIsFree) {
            // Total slots to fill: 2 * freePairsCount + 1
            if (remZeros + remOnes != 2 * freePairsCount + 1) return "-1";

            // Try setting middle to '0'
            if (remZeros >= 1 && (remZeros - 1) % 2 == 0 && remOnes % 2 == 0) {
                chars[n / 2] = '0';
                remZeros--;
            } 
            // Try setting middle to '1'
            else if (remOnes >= 1 && remZeros % 2 == 0 && (remOnes - 1) % 2 == 0) {
                chars[n / 2] = '1';
                remOnes--;
            } else {
                return "-1";
            }
        } else {
            // Total slots to fill: 2 * freePairsCount
            if (remZeros + remOnes != 2 * freePairsCount || remZeros % 2 != 0 || remOnes % 2 != 0) {
                return "-1";
            }
        }

        // Step 5: Fill free pairs greedily
        for (int idx : freePairIndices) {
            if (remZeros >= 2) {
                chars[idx] = chars[n - 1 - idx] = '0';
                remZeros -= 2;
            } else {
                chars[idx] = chars[n - 1 - idx] = '1';
                remOnes -= 2;
            }
        }

        return new String(chars);
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

