/**
 * A program to construct a palindrome from a string containing '0', '1', and '?'
 * such that the total count of '0's and '1's matches the given requirements.
 */
public class PalindromeConstructor {

    private static final char ZERO = '0';
    private static final char ONE = '1';
    private static final char QUESTION = '?';

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int testCases = reader.nextInt();
        while (testCases-- > 0) {
            int targetZeroCount = reader.nextInt();
            int targetOneCount = reader.nextInt();
            String inputString = reader.next();

            PalindromeSolver solver = new PalindromeSolver(targetZeroCount, targetOneCount, inputString);
            String result = solver.solve();

            out.println(result);
        }
        out.flush();
        out.close();
    }

    /**
     * Handles the logic for constructing the palindrome.
     */
    static class PalindromeSolver {
        private final int targetZeroCount;
        private final int targetOneCount;
        private final char[] characters;
        private final int totalLength;

        public PalindromeSolver(int targetZeroCount, int targetOneCount, String inputString) {
            this.targetZeroCount = targetZeroCount;
            this.targetOneCount = targetOneCount;
            this.characters = inputString.toCharArray();
            this.totalLength = targetZeroCount + targetOneCount;
        }

        public String solve() {
            // 1. Parity Check
            // If total length is even, both zero and one counts must be even for a palindrome.
            // If total length is odd, one must be even and one must be odd.
            if (targetZeroCount % 2 != 0 && targetOneCount % 2 != 0) {
                return "-1";
            }

            // 2. Initial count validation
            int currentZeros = 0;
            int currentOnes = 0;
            for (char c : characters) {
                if (c == ZERO) currentZeros++;
                else if (c == ONE) currentOnes++;
            }

            if (currentZeros > targetZeroCount || currentOnes > targetOneCount) {
                return "-1";
            }

            // The "budget" of zeros and ones we have left to fill '?'
            int remainingZeros = targetZeroCount - currentZeros;
            int remainingOnes = targetOneCount - currentOnes;

            // 3. Pass 1: Match existing characters with their symmetric counterparts
            for (int i = 0; i < totalLength / 2; i++) {
                int j = totalLength - 1 - i;

                if (characters[i] != QUESTION && characters[j] != QUESTION) {
                    if (characters[i] != characters[j]) return "-1";
                } else if (characters[i] != QUESTION) {
                    // characters[j] is '?'
                    if (characters[i] == ZERO) {
                        characters[j] = ZERO;
                        remainingZeros--;
                    } else {
                        characters[j] = ONE;
                        remainingOnes--;
                    }
                } else if (characters[j] != QUESTION) {
                    // characters[i] is '?'
                    if (characters[j] == ZERO) {
                        characters[i] = ZERO;
                        remainingZeros--;
                    } else {
                        characters[i] = ONE;
                        remainingOnes--;
                    }
                }

                if (remainingZeros < 0 || remainingOnes < 0) return "-1";
            }

            // 4. Pass 2: Fill remaining '?' pairs
            for (int i = 0; i < totalLength / 2; i++) {
                int j = totalLength - 1 - i;
                if (characters[i] == QUESTION && characters[j] == QUESTION) {
                    if (remainingZeros >= 2) {
                        characters[i] = characters[j] = ZERO;
                        remainingZeros -= 2;
                    } else if (remainingOnes >= 2) {
                        characters[i] = characters[j] = ONE;
                        remainingOnes -= 2;
                    } else {
                        return "-1";
                    }
                }
            }

            // 5. Pass 3: Handle the middle element for odd-length strings
            if (totalLength % 2 != 0) {
                int mid = totalLength / 2;
                if (characters[mid] == QUESTION) {
                    if (remainingZeros >= 1) {
                        characters[mid] = ZERO;
                        remainingZeros--;
                    } else if (remainingOnes >= 1) {
                        characters[mid] = ONE;
                        remainingOnes--;
                    } else {
                        return "-1";
                    }
                }
            }

            // Final check to ensure we used exactly the budget provided
            if (remainingZeros != 0 || remainingOnes != 0) {
                return "-1";
            }

            return new String(characters);
        }
    }

    /**
     * Efficient reader for fast I/O operations.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
