/**
 * Handles the core logic of constructing the palindrome.
 */
class PalindromeSolver {

    /**
     * Processes a single test case.
     * 
     * @param reader The input reader.
     * @return The constructed palindrome string or "-1" if impossible.
     * @throws IOException if an I/O error occurs.
     */
    public String solve(FastReader reader) throws IOException {
        int zeroBudget = reader.nextInt();
        int oneBudget = reader.nextInt();
        char[] sequence = reader.next().toCharArray();
        int len = sequence.length;

        int unfilledQuestionMarks = 0;

        // Step 1: Account for existing characters and identify question marks
        for (char c : sequence) {
            if (c == '0') {
                zeroBudget--;
            } else if (c == '1') {
                oneBudget--;
            } else {
                unfilledQuestionMarks++;
            }
        }

        // Initial impossibility check
        if (unfilledQuestionMarks > (zeroBudget + oneBudget)) {
            return "-1";
        }

        // Step 2: Enforce symmetry by filling '?' where the opposite side is known
        for (int i = 0; i < len; i++) {
            int opposite = len - i - 1;
            if (sequence[i] != '?' && sequence[opposite] == '?') {
                sequence[opposite] = sequence[i];
                if (sequence[i] == '0') {
                    zeroBudget--;
                } else {
                    oneBudget--;
                }
                unfilledQuestionMarks--;
            }
        }

        // Check if symmetry enforcement exceeded budget
        if (unfilledQuestionMarks > (zeroBudget + oneBudget)) {
            return "-1";
        }

        // Step 3: Fill remaining '?' pairs or middle elements greedily
        for (int i = 0; i < len; i++) {
            if (sequence[i] == '?') {
                int opposite = len - i - 1;
                int cost = (opposite == i) ? 1 : 2;

                // Check if we have enough budget for the character that is more abundant
                if (zeroBudget > oneBudget) {
                    if (zeroBudget >= cost) {
                        fillSequence(sequence, i, opposite, '0');
                        zeroBudget -= cost;
                        unfilledQuestionMarks -= cost;
                    } else {
                        return "-1";
                    }
                } else {
                    if (oneBudget >= cost) {
                        fillSequence(sequence, i, opposite, '1');
                        oneBudget -= cost;
                        unfilledQuestionMarks -= cost;
                    } else {
                        return "-1";
                    }
                }
            }
        }

        // Final validation: check budget, remaining marks, and palindrome property
        if (unfilledQuestionMarks != 0 || zeroBudget != 0 || oneBudget != 0 || !isPalindrome(sequence)) {
            return "-1";
        }

        return new String(sequence);
    }

    private void fillSequence(char[] arr, int i, int opposite, char val) {
        arr[i] = val;
        arr[opposite] = val;
    }

    private boolean isPalindrome(char[] arr) {
        int start = 0;
        int end = arr.length - 1;
        while (start < end) {
            if (arr[start++] != arr[end--]) {
                return false;
            }
        }
        return true;
    }
}

