     * 
     * @param target0 The exact number of '0's required in the final string.
     * @param target1 The exact number of '1's required in the final string.
     * @param s       The input string containing '0', '1', and '?'.
     * @return        The resulting palindrome string, or "-1" if no such string exists.
     */
    private static String solve(int target0, int target1, String s) {
        int n = s.length();
        char[] chars = s.toCharArray();

        // rem0 and rem1 track how many '0's and '1's are needed to fill the '?' slots.
        int rem0 = target0;
        int rem1 = target1;

        // Step 1: Deduct characters already present in the string.
        for (char c : chars) {
