                rem0--;
            } else if (c == '1') {
                rem1--;
            }
        }

        // If the input string already contains more '0's or '1's than allowed.
        if (rem0 < 0 || rem1 < 0) {
            return "-1";
        }

        // Step 2: Use two-pointer approach to satisfy palindrome requirements.
        int left = 0;
        int right = n - 1;

        while (left <= right) {
            if (left < right) {
                if (chars[left] == '?' && chars[right] == '?') {
                    // Case 1: Both are '?', must fill with the same character to maintain palindrome.
                    if (rem0 >= 2) {
                        chars[left] = '0';
                        chars[right] = '0';
                        rem0 -= 2;
                    } else if (rem1 >= 2) {
                        chars[left] = '1';
                        chars[right] = '1';
                        rem1 -= 2;
                    } else {
                        return "-1"; // Not enough budget to form a pair.
                    }
                } else if (chars[left] == '?') {
                    // Case 2: Left is '?', must match the existing character on the right.
                    if (chars[right] == '0') {
                        chars[left] = '0';
                        rem0--;
                    } else {
                        chars[left] = '1';
                        rem1--;
                    }
                } else if (chars[right] == '?') {
                    // Case 3: Right is '?', must match the existing character on the left.
                    if (chars[left] == '0') {
                        chars[right] = '0';
                        rem0--;
                    } else {
                        chars[right] = '1';
                        rem1--;
                    }
                } else {
                    // Case 4: Both are fixed characters, must be equal to form a palindrome.
                    if (chars[left] != chars[right]) {
                        return "-1";
                    }
                }

                // Check if we exceeded the budget during character assignment.
                if (rem0 < 0 || rem1 < 0) return "-1";

            } else {
                // Case 5: Single middle character (if n is odd).
                if (chars[left] == '?') {
                    if (rem0 > 0) {
                        chars[left] = '0';
                        rem0--;
                    } else if (rem1 > 0) {
                        chars[left] = '1';
                        rem1--;
                    } else {
                        return "-1";
                    }
                }
            }
            left++;
            right--;
        }

        // Step 3: Final validation to ensure all required characters were used.
        if (rem0 != 0 || rem1 != 0) {
            return "-1";
        }

        return new String(chars);
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A solution to construct a palindrome of a given length using 
 * an exact number of '0's and '1's, given a template with '?'.
 */
public class PalindromeBuilder {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int testCases = reader.nextInt();
        while (testCases-- > 0) {
            out.println(solve(reader));
        }
        out.flush();
        out.close();
    }

    /**
     * Processes a single test case.
     * 
     * @param reader The FastReader instance for input.
     * @return The constructed palindrome string or "-1" if impossible.
     */
    private static String solve(FastReader reader) {
        int targetZeroCount = reader.nextInt();
        int targetOneCount = reader.nextInt();
        char[] sequence = reader.next().toCharArray();
        int n = sequence.length;

        // 1. Ensure existing non-'?' characters satisfy the palindrome property
        for (int i = 0; i < n / 2; i++) {
            int left = i;
            int right = n - 1 - i;
            if (sequence[left] != '?' && sequence[right] != '?') {
                if (sequence[left] != sequence[right]) {
                    return "-1";
                }
            } else if (sequence[left] != '?') {
                sequence[right] = sequence[left];
            } else if (sequence[right] != '?') {
                sequence[left] = sequence[right];
            }
        }

        // 2. Count how many '0's and '1's are already fixed in the sequence
        int currentZeroCount = 0;
        int currentOneCount = 0;
        for (char c : sequence) {
            if (c == '0') currentZeroCount++;
            else if (c == '1') currentOneCount++;
        }

        // 3. Calculate how many more of each we need to add
        int remainingZeroNeeded = targetZeroCount - currentZeroCount;
        int remainingOneNeeded = targetOneCount - currentOneCount;

        // If we already exceeded the target counts, it's impossible
        if (remainingZeroNeeded < 0 || remainingOneNeeded < 0) {
            return "-1";
        }

        // 4. Handle the middle element for odd-length sequences
        // The middle element must satisfy the parity requirements of the remaining counts
        if (n % 2 != 0 && sequence[n / 2] == '?') {
            if (remainingZeroNeeded % 2 != 0) {
                sequence[n / 2] = '0';
                remainingZeroNeeded--;
            } else if (remainingOneNeeded % 2 != 0) {
                sequence[n / 2] = '1';
                remainingOneNeeded--;
            } else {
                // This occurs if neither count can satisfy the parity needed for an odd length
                return "-1";
            }
        }

        // 5. Parity validation: all remaining characters must be placed in pairs
        if (remainingZeroNeeded % 2 != 0 || remainingOneNeeded % 2 != 0) {
            return "-1";
        }

        // 6. Fill the remaining '?' pairs greedily
        for (int i = 0; i < n / 2; i++) {
            int left = i;
            int right = n - 1 - i;
            if (sequence[left] == '?') {
                if (remainingZeroNeeded >= 2) {
                    sequence[left] = '0';
                    sequence[right] = '0';
                    remainingZeroNeeded -= 2;
                } else if (remainingOneNeeded >= 2) {
                    sequence[left] = '1';
                    sequence[right] = '1';
                    remainingOneNeeded -= 2;
                } else {
                    return "-1";
                }
            }
        }

        // 7. Final check: Ensure we used exactly the required amount of characters
        if (remainingZeroNeeded != 0 || remainingOneNeeded != 0) {
            return "-1";
        }

        return new String(sequence);
    }

    /**
     * Efficient reader for fast I/O operations.
     */
    static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
