import java.util.Scanner;

/**
 * A utility to solve the problem of constructing a palindrome from a pattern
 * with a specific number of '0's and '1's.
 */
public class PalindromeSolver {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int testCases = scanner.nextInt();
        while (testCases-- > 0) {
            int targetZeros = scanner.nextInt();
            int targetOnes = scanner.nextInt();
            String pattern = scanner.next();

            String result = solve(targetZeros, targetOnes, pattern);
            System.out.println(result);
        }
        scanner.close();
    }

    /**
     * Attempts to construct a palindrome based on target counts and existing characters.
     * 
     * @param targetZeros The exact number of '0' characters required.
     * @param targetOnes  The exact number of '1' characters required.
     * @param pattern     The input string containing '0', '1', or '?'.
     * @return A valid palindrome string, or "-1" if no such palindrome exists.
     */
    public static String solve(int targetZeros, int targetOnes, String pattern) {
        int n = pattern.length();
        char[] sequence = pattern.toCharArray();

        int currentZeros = 0;
        int currentOnes = 0;

        // 1. Count existing characters and check for immediate impossibility
        for (char c : sequence) {
            if (c == '0') currentZeros++;
            else if (c == '1') currentOnes++;
        }

        if (currentZeros > targetZeros || currentOnes > targetOnes) {
            return "-1";
        }

        // 2. Match existing fixed characters with their symmetric counterparts
        for (int i = 0; i < n / 2; i++) {
            int left = i;
            int right = n - 1 - i;

            if (sequence[left] != '?' && sequence[right] != '?') {
                if (sequence[left] != sequence[right]) {
                    return "-1";
                }
            } else if (sequence[left] != '?') {
                // Right is '?', so make it match Left
                sequence[right] = sequence[left];
                if (sequence[left] == '0') currentZeros++;
                else currentOnes++;
            } else if (sequence[right] != '?') {
                // Left is '?', so make it match Right
                sequence[left] = sequence[right];
                if (sequence[right] == '0') currentZeros++;
                else currentOnes++;
            }
        }

        // Re-verify counts after symmetric filling
        if (currentZeros > targetZeros || currentOnes > targetOnes) {
            return "-1";
        }

        // 3. Fill remaining '?' pairs
        for (int i = 0; i < n / 2; i++) {
            int left = i;
            int right = n - 1 - i;

            if (sequence[left] == '?') {
                int remainingZerosNeeded = targetZeros - currentZeros;
                int remainingOnesNeeded = targetOnes - currentOnes;

                if (remainingZerosNeeded >= 2) {
                    sequence[left] = '0';
                    sequence[right] = '0';
                    currentZeros += 2;
                } else if (remainingOnesNeeded >= 2) {
                    sequence[left] = '1';
                    sequence[right] = '1';
                    currentOnes += 2;
                } else {
                    return "-1";
                }
            }
        }

        // 4. Handle the middle element for odd-length strings
        if (n % 2 != 0) {
            int mid = n / 2;
            if (sequence[mid] == '?') {
                if (currentZeros < targetZeros) {
                    sequence[mid] = '0';
                    currentZeros++;
                } else if (currentOnes < targetOnes) {
                    sequence[mid] = '1';
                    currentOnes++;
                } else {
                    return "-1";
                }
            }
        }

        // 5. Final Validation
        if (currentZeros == targetZeros && currentOnes == targetOnes && isPalindrome(sequence)) {
            return new String(sequence);
        } else {
            return "-1";
        }
    }

    /**
     * Checks if the character array forms a palindrome.
     */
    private static boolean isPalindrome(char[] s) {
        int left = 0;
        int right = s.length - 1;
        while (left < right) {
            if (s[left] != s[right]) {
                return false;
            }
            left++;
            right--;
        }
        return true;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Main class to handle execution and I/O.
 */
public class Main {

    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);
        PalindromeSolver solver = new PalindromeSolver();

        int testCases = sc.nextInt();
        while (testCases-- > 0) {
            int targetZeros = sc.nextInt();
            int targetOnes = sc.nextInt();
            String inputString = sc.next();

            out.println(solver.solve(targetZeros, targetOnes, inputString));
        }
        out.flush();
        out.close();
    }

    /**
     * Logic provider for solving the palindrome construction problem.
     */
    static class PalindromeSolver {

        /**
         * Attempts to construct a palindrome with exactly targetZeros '0's and targetOnes '1's.
         * 
         * @param targetZeros The required number of '0' characters.
         * @param targetOnes  The required number of '1' characters.
         * @param s           The input string containing '0', '1', or '?'.
         * @return The constructed palindrome string, or "-1" if impossible.
         */
        public String solve(int targetZeros, int targetOnes, String s) {
            int n = s.length();

            // Basic validity check: total characters must match the sum of targets
            if (targetZeros + targetOnes != n) {
                return "-1";
            }

            // Calculate how many '0's and '1's are already fixed in the string
            int existingZeros = 0;
            int existingOnes = 0;
            for (int i = 0; i < n; i++) {
                char c = s.charAt(i);
                if (c == '0') existingZeros++;
                else if (c == '1') existingOnes++;
            }

            // remZeros/remOnes represent the number of '?' we must convert to 0 or 1
            int remZeros = targetZeros - existingZeros;
            int remOnes = targetOnes - existingOnes;

            // If the string already contains more 0s or 1s than allowed
            if (remZeros < 0 || remOnes < 0) {
                return "-1";
            }

            char[] result = new char[n];

            // Iterate through the first half of the string to handle pairs (i, j)
            for (int i = 0; i < (n + 1) / 2; i++) {
                int j = n - 1 - i;

                if (i < j) {
                    // Case 1: Dealing with a pair of different indices
                    char left = s.charAt(i);
                    char right = s.charAt(j);

                    if (left != '?' && right != '?') {
                        if (left != right) return "-1"; // Palindrome violation
                        result[i] = left;
                        result[j] = right;
                    } else if (left != '?' && right == '?') {
                        result[i] = left;
                        result[j] = left;
                        if (left == '0') remZeros--; else remOnes--;
                    } else if (left == '?' && right != '?') {
                        result[i] = right;
                        result[j] = right;
                        if (right == '0') remZeros--; else remOnes--;
                    } else {
                        // Case: Both are '?' - must pick a digit to satisfy palindrome property
                        if (remZeros >= 2) {
                            result[i] = result[j] = '0';
                            remZeros -= 2;
                        } else if (remOnes >= 2) {
                            result[i] = result[j] = '1';
                            remOnes -= 2;
                        } else {
                            return "-1"; // Cannot satisfy palindrome with remaining budget
                        }
                    }
                } else {
                    // Case 2: Dealing with the middle character (i == j)
                    if (s.charAt(i) == '?') {
                        if (remZeros > 0) {
                            result[i] = '0';
                            remZeros--;
                        } else if (remOnes > 0) {
                            result[i] = '1';
                            remOnes--;
                        } else {
                            return "-1";
                        }
                    } else {
                        result[i] = s.charAt(i);
                    }
                }

                // Early exit if budget is exceeded
                if (remZeros < 0 || remOnes < 0) return "-1";
            }

            // Final check to ensure all required characters were used exactly
            if (remZeros == 0 && remOnes == 0) {
                return new String(result);
            } else {
                return "-1";
            }
        }
    }

    /**
     * Efficient utility for reading input.
     */
    static class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Problem: Construct a palindrome of length N using exactly 'a' zeros and 'b' ones,
 * matching a given pattern string where '?' can be either '0' or '1'.
 */
public class Solution {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int testCases = reader.nextInt();
            PalindromeSolver solver = new PalindromeSolver();

            for (int t = 0; t < testCases; t++) {
                int targetZeroCount = reader.nextInt();
                int targetOneCount = reader.nextInt();
                String pattern = reader.next();

                out.println(solver.solve(targetZeroCount, targetOneCount, pattern));
            }
        } catch (Exception e) {
            // In a production environment, use a logger.
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Encapsulates the logic for solving the palindrome construction problem.
     */
    static class PalindromeSolver {

        public String solve(int targetZero, int targetOne, String pattern) {
            int n = pattern.length();
            char[] chars = pattern.toCharArray();

            // 1. Synchronize existing digits to maintain palindrome property
            if (!syncPalindrome(chars, n)) {
                return "-1";
            }

            // 2. Count existing fixed digits
            int currentZeros = 0;
            int currentOnes = 0;
            for (char c : chars) {
                if (c == '0') currentZeros++;
                else if (c == '1') currentOnes++;
            }

            // If fixed digits already exceed targets, it's impossible
            if (currentZeros > targetZero || currentOnes > targetOne) {
                return "-1";
            }

            // 3. Identify available wildcard slots
            List<Integer> wildcardPairIndices = new ArrayList<>();
            Integer middleWildcardIndex = null;

            for (int i = 0; i < n / 2; i++) {
                if (chars[i] == '?') {
                    wildcardPairIndices.add(i);
                }
            }
            if (n % 2 == 1 && chars[n / 2] == '?') {
                middleWildcardIndex = n / 2;
            }

            // 4. Solve for wildcard distribution
            // We need to solve: 
            // 2 * p0 + m0 = targetZero - currentZeros
            // 2 * p1 + m1 = targetOne - currentOnes
            // where p0 + p1 = total wildcard pairs, and m0 + m1 = middle element status
            return fillWildcards(chars, n, targetZero, targetOne, currentZeros, currentOnes, 
                                wildcardPairIndices, middleWildcardIndex);
        }

        private boolean syncPalindrome(char[] chars, int n) {
            for (int i = 0; i < n / 2; i++) {
                int j = n - 1 - i;
                if (chars[i] != '?' && chars[j] != '?' && chars[i] != chars[j]) {
                    return false; // Conflict found
                }
                if (chars[i] != '?') {
                    chars[j] = chars[i];
                } else if (chars[j] != '?') {
                    chars[i] = chars[j];
                }
            }
            return true;
        }

        private String fillWildcards(char[] chars, int n, int targetZero, int targetOne, 
                                     int curZero, int curOne, List<Integer> pairIndices, 
                                     Integer middleIdx) {
            int pCount = pairIndices.size();
            int mCount = (middleIdx == null) ? 0 : 1;

            // Try both possibilities for the middle element if it exists
            for (int m0 = 0; m0 <= mCount; m0++) {
                int m1 = mCount - m0;
                int remZ = targetZero - curZero - m0;
                int remO = targetOne - curOne - m1;

                // Check if remaining counts can be satisfied by pairs
                if (remZ >= 0 && remZ % 2 == 0 && remO >= 0 && remO % 2 == 0) {
                    int p0 = remZ / 2;
                    int p1 = remO / 2;

                    if (p0 + p1 == pCount) {
                        // Valid distribution found! Apply to char array
                        applyDistribution(chars, n, pairIndices, middleIdx, p0, m0);
                        return new String(chars);
                    }
                }
            }

            return "-1";
        }

        private void applyDistribution(char[] chars, int n, List<Integer> pairIndices, 
                                       Integer middleIdx, int p0, int m0) {
            int count0 = 0;
            for (int idx : pairIndices) {
                if (count0 < p0) {
                    chars[idx] = chars[n - 1 - idx] = '0';
                    count0++;
                } else {
                    chars[idx] = chars[n - 1 - idx] = '1';
                }
            }
            if (middleIdx != null) {
                chars[middleIdx] = (m0 == 1) ? '0' : '1';
            }
        }
    }

    /**
     * Fast I/O utility for efficient reading.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Optional;
import java.util.Scanner;

/**
 * A utility to generate a palindrome string from a pattern containing '0', '1', and '?'.
 * The resulting string must respect the provided counts of '0's and '1's.
 */
public class PalindromeGenerator {

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int testCases = scanner.nextInt();
            while (testCases-- > 0) {
                processTestCase(scanner);
            }
        }
    }

    /**
     * Reads input for a single test case and prints the result.
     */
    private static void processTestCase(Scanner scanner) {
        int zeroBudget = scanner.nextInt();
        int oneBudget = scanner.nextInt();
        String pattern = scanner.next();

        Optional<String> result = generatePalindrome(zeroBudget, oneBudget, pattern);

        if (result.isPresent()) {
            System.out.println(result.get());
        } else {
            System.out.println("-1");
        }
    }

    /**
     * Attempts to fill the '?' in the pattern to create a palindrome
     * using the provided budget of zeros and ones.
     *
     * @param zeroBudget Total number of '0's allowed in the final string.
     * @param oneBudget  Total number of '1's allowed in the final string.
     * @param pattern    The input string containing '0', '1', or '?'.
     * @return An Optional containing the palindrome string, or empty if impossible.
     */
    private static Optional<String> generatePalindrome(int zeroBudget, int oneBudget, String pattern) {
        char[] chars = pattern.toCharArray();
        int n = chars.length;

        int remainingZeros = zeroBudget;
        int remainingOnes = oneBudget;

        // Step 1: Deduct existing characters from the budget
        for (char c : chars) {
            if (c == '0') {
                remainingZeros--;
            } else if (c == '1') {
                remainingOnes--;
            }
        }

        // If existing characters already exceed the budget
        if (remainingZeros < 0 || remainingOnes < 0) {
            return Optional.empty();
        }

        // Step 2: Pass 1 - Handle '?' paired with a fixed character ('0' or '1')
        for (int i = 0; i < n / 2; i++) {
            int oppositeIndex = n - 1 - i;
            char left = chars[i];
            char right = chars[oppositeIndex];

            if (left == '?' && right != '?') {
                if (right == '0') {
                    chars[i] = '0';
                    remainingZeros--;
                } else {
                    chars[i] = '1';
                    remainingOnes--;
                }
            } else if (left != '?' && right == '?') {
                if (left == '0') {
                    chars[oppositeIndex] = '0';
                    remainingZeros--;
                } else {
                    chars[oppositeIndex] = '1';
                    remainingOnes--;
                }
            } else if (left != '?' && right != '?' && left != right) {
                // Conflict: fixed characters do not match
                return Optional.empty();
            }

            if (remainingZeros < 0 || remainingOnes < 0) {
                return Optional.empty();
            }
        }

        // Step 3: Pass 2 - Handle remaining '??' pairs greedily
        for (int i = 0; i < n / 2; i++) {
            int oppositeIndex = n - 1 - i;
            if (chars[i] == '?' && chars[oppositeIndex] == '?') {
                if (remainingZeros >= 2) {
                    chars[i] = '0';
                    chars[oppositeIndex] = '0';
                    remainingZeros -= 2;
                } else if (remainingOnes >= 2) {
                    chars[i] = '1';
                    chars[oppositeIndex] = '1';
                    remainingOnes -= 2;
                } else {
                    return Optional.empty();
                }
            }
        }

        // Step 4: Pass 3 - Handle the middle character for odd-length strings
        if (n % 2 != 0 && chars[n / 2] == '?') {
            if (remainingZeros >= 1) {
                chars[n / 2] = '0';
                remainingZeros--;
            } else if (remainingOnes >= 1) {
                chars[n / 2] = '1';
                remainingOnes--;
            } else {
                return Optional.empty();
            }
        }

        return Optional.of(new String(chars));
    }
}

import java.util.*;

/**
 * A utility to solve the palindrome construction problem.
 * The goal is to replace '?' characters in a string with '0' or '1' 
 * such that the total counts of '0's and '1's match the targets
 * and the resulting string is a palindrome.
 */
public class PalindromeSolution {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int testCases = scanner.nextInt();
        for (int t = 0; t < testCases; t++) {
            solve(scanner);
        }

        scanner.close();
    }

    /**
     * Orchestrates the logic for a single test case.
     */
    private static void solve(Scanner scanner) {
        int targetZeroCount = scanner.nextInt();
        int targetOneCount = scanner.nextInt();
        char[] sequence = scanner.next().toCharArray();
        int length = sequence.length;

        String result = constructPalindrome(sequence, targetZeroCount, targetOneCount);
        System.out.println(result);
    }

    /**
     * Attempts to construct a palindrome based on target counts.
     * 
     * @param sequence The character array containing '0', '1', or '?'.
     * @param targetZeros Total number of '0's required.
     * @param targetOnes Total number of '1's required.
     * @return The constructed palindrome string, or "-1" if impossible.
     */
    private static String constructPalindrome(char[] sequence, int targetZeros, int targetOnes) {
        int length = sequence.length;
        int currentZeros = 0;
        int currentOnes = 0;

        // Step 1: Count existing characters and calculate remaining needs
        for (char c : sequence) {
            if (c == '0') currentZeros++;
            else if (c == '1') currentOnes++;
        }

        int remZeros = targetZeros - currentZeros;
        int remOnes = targetOnes - currentOnes;

        // If existing counts already exceed targets, it's impossible
        if (remZeros < 0 || remOnes < 0) {
            return "-1";
        }

        int halfLength = length / 2;

        // Step 2: Pass 1 - Resolve symmetry where one side is already a digit
        for (int i = 0; i < halfLength; i++) {
            int left = i;
            int right = length - 1 - i;

            if (sequence[left] != '?' && sequence[right] != '?') {
                if (sequence[left] != sequence[right]) {
                    return "-1"; // Symmetrical digits don't match
                }
            } else if (sequence[left] != '?' && sequence[right] == '?') {
                // Fill right side to match left
                char match = sequence[left];
                if (match == '0') remZeros--; else remOnes--;
                sequence[right] = match;
            } else if (sequence[left] == '?' && sequence[right] != '?') {
                // Fill left side to match right
                char match = sequence[right];
                if (match == '0') remZeros--; else remOnes--;
                sequence[left] = match;
            }

            if (remZeros < 0 || remOnes < 0) return "-1";
        }

        // Step 3: Pass 2 - Resolve symmetric pairs where both are '?'
        for (int i = 0; i < halfLength; i++) {
            int left = i;
            int right = length - 1 - i;

            if (sequence[left] == '?' && sequence[right] == '?') {
                if (remZeros >= 2) {
                    sequence[left] = sequence[right] = '0';
                    remZeros -= 2;
                } else if (remOnes >= 2) {
                    sequence[left] = sequence[right] = '1';
                    remOnes -= 2;
                } else {
                    return "-1"; // Cannot satisfy symmetry with remaining counts
                }
            }
        }

        // Step 4: Pass 3 - Handle the middle element for odd-length strings
        if (length % 2 != 0) {
            int mid = length / 2;
            if (sequence[mid] == '?') {
                if (remZeros >= 1) {
                    sequence[mid] = '0';
                    remZeros--;
                } else if (remOnes >= 1) {
                    sequence[mid] = '1';
                    remOnes--;
                } else {
                    return "-1";
                }
            }
        }

        // Final Validation: Ensure all requested counts were used and palindrome is valid
        if (remZeros == 0 && remOnes == 0 && isPalindrome(sequence)) {
            return new String(sequence);
        }

        return "-1";
    }

    /**
     * Verifies if the character array is a palindrome.
     */
    private static boolean isPalindrome(char[] sequence) {
        int left = 0;
        int right = sequence.length - 1;
        while (left < right) {
            if (sequence[left++] != sequence[right--]) {
                return false;
            }
        }
        return true;
    }
}

import java.io.*;
import java.util.*;

/**
 * A utility to construct a palindrome string from a pattern of '0', '1', and '?'
 * such that the resulting string contains a specific number of '0's and '1's.
 */
public class PalindromeConstructor {

    private static final String IMPOSSIBLE = "-1";

    public static void main(String[] args) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String firstLine = reader.readLine();
            if (firstLine == null) return;

            int testCases = Integer.parseInt(firstLine.trim());
            StringBuilder totalOutput = new StringBuilder();

            for (int t = 0; t < testCases; t++) {
                totalOutput.append(solveTestCase(reader)).append("\n");
            }

            // Single print operation for efficiency
            System.out.print(totalOutput);
        } catch (IOException | NumberFormatException e) {
            // In a production environment, use a proper logging framework
            System.err.println("Error processing input: " + e.getMessage());
        }
    }

    /**
     * Reads and processes a single test case.
     *
     * @param reader The BufferedReader to read input from.
     * @return The constructed palindrome or "-1" if impossible.
     * @throws IOException If an I/O error occurs.
     */
    private static String solveTestCase(BufferedReader reader) throws IOException {
        String line = reader.readLine();
        if (line == null) return IMPOSSIBLE;

        StringTokenizer tokenizer = new StringTokenizer(line);
        if (!tokenizer.hasMoreTokens()) return IMPOSSIBLE;

        int targetZeros = Integer.parseInt(tokenizer.nextToken());
        int targetOnes = Integer.parseInt(tokenizer.nextToken());
        String pattern = reader.readLine();

        if (pattern == null) return IMPOSSIBLE;

        return constructPalindrome(targetZeros, targetOnes, pattern);
    }

    /**
     * Core algorithm to construct a palindrome satisfying character count constraints.
     *
     * @param targetZeros Total number of '0's required in the final string.
     * @param targetOnes  Total number of '1's required in the final string.
     * @param pattern     The input string containing '0', '1', or '?'.
     * @return The constructed palindrome or "-1".
     */
    private static String constructPalindrome(int targetZeros, int targetOnes, String pattern) {
        int n = pattern.length();

        // Basic validation: the requested counts must match the string length
        if (targetZeros + targetOnes != n) {
            return IMPOSSIBLE;
        }

        char[] chars = pattern.toCharArray();

        // Phase 1: Satisfy fixed palindrome constraints.
        // If one side of the palindrome is fixed, the mirror side must match it.
        for (int i = 0; i < (n + 1) / 2; i++) {
            int mirrorIndex = n - 1 - i;
            if (i != mirrorIndex) {
                if (chars[i] != '?' && chars[mirrorIndex] != '?') {
                    if (chars[i] != chars[mirrorIndex]) {
                        return IMPOSSIBLE; // Contradicting fixed characters
                    }
                } else if (chars[i] != '?') {
                    chars[mirrorIndex] = chars[i];
                } else if (chars[mirrorIndex] != '?') {
                    chars[i] = chars[mirrorIndex];
                }
            }
        }

        // Phase 2: Calculate remaining character requirements.
        int currentZeros = 0;
        int currentOnes = 0;
        for (char c : chars) {
            if (c == '0') currentZeros++;
            else if (c == '1') currentOnes++;
        }

        int remainingZeros = targetZeros - currentZeros;
        int remainingOnes = targetOnes - currentOnes;

        // If fixed characters already exceeded requested counts
        if (remainingZeros < 0 || remainingOnes < 0) {
            return IMPOSSIBLE;
        }

        // Phase 3: Fill remaining '?' characters greedily.
        for (int i = 0; i < (n + 1) / 2; i++) {
            int mirrorIndex = n - 1 - i;

            if (chars[i] == '?') {
                if (i == mirrorIndex) {
                    // Case: Middle element in an odd-length string
                    if (remainingZeros > 0) {
                        chars[i] = '0';
                        remainingZeros--;
                    } else if (remainingOnes > 0) {
                        chars[i] = '1';
                        remainingOnes--;
                    } else {
                        return IMPOSSIBLE;
                    }
                } else {
                    // Case: A pair of '?' characters at mirror positions
                    if (remainingZeros >= 2) {
                        chars[i] = chars[mirrorIndex] = '0';
                        remainingZeros -= 2;
                    } else if (remainingOnes >= 2) {
                        chars[i] = chars[mirrorIndex] = '1';
                        remainingOnes -= 2;
                    } else {
                        // Cannot satisfy palindrome with a pair if count is only 1
                        return IMPOSSIBLE;
                    }
                }
            }
        }

        // Final validation: Check if all required characters were used exactly
        if (remainingZeros == 0 && remainingOnes == 0) {
            return new String(chars);
        } else {
            return IMPOSSIBLE;
        }
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * A utility class to solve the problem of filling a string with '0's and '1's
 * to make it a palindrome with specific character counts.
 */
class PalindromeResolver {

    private static final String IMPOSSIBLE = "-1";

    /**
     * Attempts to resolve the palindrome string.
     *
     * @param targetZeroCount The required number of '0' characters.
     * @param targetOneCount  The required number of '1' characters.
     * @param inputString     The string containing '0', '1', and '?'.
     * @return The completed palindrome string, or "-1" if impossible.
     */
    public String resolve(int targetZeroCount, int targetOneCount, String inputString) {
        int n = inputString.length();
        char[] chars = inputString.toCharArray();

        // 1. Basic validation: Total length must match the sum of counts
        if (targetZeroCount + targetOneCount != n) {
            return IMPOSSIBLE;
        }

        // 2. Fill forced characters (where one side of a palindrome pair is known)
        for (int i = 0; i < n / 2; i++) {
            int mirrorIdx = n - 1 - i;
            if (chars[i] != '?' && chars[mirrorIdx] != '?') {
                if (chars[i] != chars[mirrorIdx]) {
                    return IMPOSSIBLE;
                }
            } else if (chars[i] != '?') {
                chars[mirrorIdx] = chars[i];
            } else if (chars[mirrorIdx] != '?') {
                chars[i] = chars[mirrorIdx];
            }
        }

        // 3. Count current characters and identify remaining needs
        int currentZeros = 0;
        int currentOnes = 0;
        for (char c : chars) {
            if (c == '0') currentZeros++;
            else if (c == '1') currentOnes++;
        }

        int remA = targetZeroCount - currentZeros;
        int remB = targetOneCount - currentOnes;

        if (remA < 0 || remB < 0) {
            return IMPOSSIBLE;
        }

        // 4. Identify flexible components: pairs of ?? and the middle char (if odd length)
        List<Integer> flexiblePairIndices = new ArrayList<>();
        for (int i = 0; i < n / 2; i++) {
            if (chars[i] == '?') {
                flexiblePairIndices.add(i);
            }
        }

        Integer middleIdx = (n % 2 != 0 && chars[n / 2] == '?') ? n / 2 : null;

        // 5. Determine how to fill flexible components using parity logic
        boolean possible = false;
        char chosenMiddleChar = ' ';

        if (middleIdx != null) {
            // Case: Middle '?' exists. Try setting it to '0' or '1'.
            // Try '0'
            if (remA >= 1 && (remA - 1) % 2 == 0 && remB % 2 == 0 
                && (remA - 1) / 2 + remB / 2 == flexiblePairIndices.size()) {
                possible = true;
                chosenMiddleChar = '0';
            } 
            // Try '1'
            else if (remB >= 1 && (remB - 1) % 2 == 0 && remA % 2 == 0 
                && remA / 2 + (remB - 1) / 2 == flexiblePairIndices.size()) {
                possible = true;
                chosenMiddleChar = '1';
            }
        } else {
            // Case: No middle '?' (either even length or middle is already fixed)
            if (remA % 2 == 0 && remB % 2 == 0 
                && remA / 2 + remB / 2 == flexiblePairIndices.size()) {
                possible = true;
            }
        }

        if (!possible) {
            return IMPOSSIBLE;
        }

        // 6. Execute the filling
        if (middleIdx != null) {
            chars[middleIdx] = chosenMiddleChar;
        }

        // Calculate how many pairs must be '0's
        int zeroPairsNeeded;
        if (middleIdx != null && chosenMiddleChar == '0') {
            zeroPairsNeeded = (remA - 1) / 2;
        } else {
            zeroPairsNeeded = remA / 2;
        }

        for (int i = 0; i < flexiblePairIndices.size(); i++) {
            int idx = flexiblePairIndices.get(i);
            char fillChar = (i < zeroPairsNeeded) ? '0' : '1';
            chars[idx] = fillChar;
            chars[n - 1 - idx] = fillChar;
        }

        return new String(chars);
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        PalindromeResolver resolver = new PalindromeResolver();

        if (!scanner.hasNextInt()) return;
        int testCases = scanner.nextInt();

        while (testCases-- > 0) {
            int targetZeroCount = scanner.nextInt();
            int targetOneCount = scanner.nextInt();
            String inputString = scanner.next();

            String result = resolver.resolve(targetZeroCount, targetOneCount, inputString);
            System.out.println(result);
        }
        scanner.close();
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to transform a string containing '0', '1', and '?' into a palindrome
 * using exactly a specified number of '0's and '1's.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            String testCountStr = reader.next();
            if (testCountStr != null) {
                int testCount = Integer.parseInt(testCountStr);
                PalindromeSolver solver = new PalindromeSolver();

                for (int i = 0; i < testCount; i++) {
                    int targetZeros = reader.nextInt();
                    int targetOnes = reader.nextInt();
                    String s = reader.next();

                    writer.println(solver.solve(targetZeros, targetOnes, s));
                }
            }
        } catch (Exception e) {
            // In a production environment, use a proper logger.
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Logic for solving the Palindrome construction problem.
     */
    static class PalindromeSolver {

        /**
         * Solves the problem for a single test case.
         *
         * @param targetZeros Total number of '0' characters required.
         * @param targetOnes  Total number of '1' characters required.
         * @param s           The initial string containing '0', '1', or '?'.
         * @return The constructed palindrome string, or "-1" if impossible.
         */
        public String solve(int targetZeros, int targetOnes, String s) {
            int n = s.length();
            char[] arr = s.toCharArray();

            // 1. Synchronize existing characters and check for immediate conflicts
            if (!synchronizeSymmetricChars(arr, n)) {
                return "-1";
            }

            // 2. Count current characters and question marks
            int currentZeros = 0;
            int currentOnes = 0;
            int qCount = 0;
            for (char c : arr) {
                if (c == '0') currentZeros++;
                else if (c == '1') currentOnes++;
                else qCount++;
            }

            // 3. Calculate remaining characters needed to fulfill targets
            int remZeros = targetZeros - currentZeros;
            int remOnes = targetOnes - currentOnes;

            // 4. Feasibility check: can we satisfy the count using available '?'?
            if (remZeros < 0 || remOnes < 0 || (remZeros + remOnes) != qCount) {
                return "-1";
            }

            // 5. Handle the middle element for odd-length strings
            // If the middle is '?', it must be used to make the remaining counts even.
            if (n % 2 != 0 && arr[n / 2] == '?') {
                if (remZeros % 2 != 0) {
                    arr[n / 2] = '0';
                    remZeros--;
                } else if (remOnes % 2 != 0) {
                    arr[n / 2] = '1';
                    remOnes--;
                } else {
                    // Mathematically, if qCount is odd, one of remZeros/remOnes must be odd.
                    return "-1";
                }
            } else {
                // If middle is not '?', the remaining counts must already be even to form pairs.
                if (remZeros % 2 != 0 || remOnes % 2 != 0) {
                    return "-1";
                }
            }

            // 6. Fill the remaining '?' in symmetric pairs
            for (int i = 0; i < n / 2; i++) {
                int j = n - 1 - i;
                if (arr[i] == '?') {
                    // Because of synchronization, arr[i] == '?' implies arr[j] == '?'
                    if (remZeros >= 2) {
                        arr[i] = arr[j] = '0';
                        remZeros -= 2;
                    } else if (remOnes >= 2) {
                        arr[i] = arr[j] = '1';
                        remOnes -= 2;
                    } else {
                        return "-1";
                    }
                }
            }

            // Final safeguard check
            if (remZeros != 0 || remOnes != 0) {
                return "-1";
            }

            return new String(arr);
        }

        private boolean synchronizeSymmetricChars(char[] arr, int n) {
            for (int i = 0; i < n / 2; i++) {
                int j = n - 1 - i;
                if (arr[i] != '?' && arr[j] != '?') {
                    if (arr[i] != arr[j]) return false;
                } else if (arr[i] != '?') {
                    arr[j] = arr[i];
                } else if (arr[j] != '?') {
                    arr[i] = arr[j];
                }
            }
            return true;
        }
    }

    /**
     * Efficient input reader for handling large datasets.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored program to solve the palindrome construction problem.
 * The goal is to fill '?' in a string to make it a palindrome
 * using a specific number of '0's and '1's.
 */
public class Main {

    public static void main(String[] args) {
        // Using try-with-resources to ensure streams are closed properly
        try (InputStream inputStream = System.in;
             PrintWriter out = new PrintWriter(System.out)) {

            InputReader in = new InputReader(inputStream);
            Solver solver = new Solver();

            String testCountStr = in.next();
            if (testCountStr == null) return;

            int testCount = Integer.parseInt(testCountStr);
            for (int i = 0; i < testCount; i++) {
                solver.solve(in, out);
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    static class Solver {
        private static final char ZERO = '0';
        private static final char ONE = '1';
        private static final char QUESTION = '?';

        /**
         * Solves a single test case.
         */
        public void solve(InputReader in, PrintWriter out) {
            int zeroBudget = in.readInt();
            int oneBudget = in.readInt();
            int n = zeroBudget + oneBudget;
            char[] s = in.readCharArray(n);

            int count0 = 0;
            int count1 = 0;

            // Phase 1: Enforce symmetry using existing digits
            // We iterate through the first half of the string and match it with the second half.
            for (int i = 0; i < n / 2; i++) {
                int j = n - 1 - i;

                if (s[i] != QUESTION && s[j] != QUESTION) {
                    // Both are digits: they must be identical to form a palindrome
                    if (s[i] != s[j]) {
                        out.println("-1");
                        return;
                    }
                    if (s[i] == ZERO) count0 += 2; else count1 += 2;
                } else if (s[i] != QUESTION) {
                    // Only s[i] is a digit: s[j] must become that digit
                    s[j] = s[i];
                    if (s[i] == ZERO) count0 += 2; else count1 += 2;
                } else if (s[j] != QUESTION) {
                    // Only s[j] is a digit: s[i] must become that digit
                    s[i] = s[j];
                    if (s[j] == ZERO) count0 += 2; else count1 += 2;
                }
                // If both are '?', we leave them for Phase 2
            }

            // Handle the middle element for odd-lengthed strings
            if (n % 2 != 0) {
                int mid = n / 2;
                if (s[mid] != QUESTION) {
                    if (s[mid] == ZERO) count0 += 1; else count1 += 1;
                }
            }

            // Check if existing digits already exceed the allowed budget
            if (count0 > zeroBudget || count1 > oneBudget) {
                out.println("-1");
                return;
            }

            // Remaining budget for '?' characters
            int rem0 = zeroBudget - count0;
            int rem1 = oneBudget - count1;

            // Phase 2: Fill symmetric '?' pairs
            for (int i = 0; i < n / 2; i++) {
                int j = n - 1 - i;
                if (s[i] == QUESTION) {
                    // Since Phase 1 matched all fixed digits, s[i] == '?' implies s[j] == '?'
                    if (rem1 >= 2) {
                        s[i] = s[j] = ONE;
                        rem1 -= 2;
                    } else if (rem0 >= 2) {
                        s[i] = s[j] = ZERO;
                        rem0 -= 2;
                    } else {
                        out.println("-1");
                        return;
                    }
                }
            }

            // Phase 3: Fill the middle '?' if it exists
            if (n % 2 != 0) {
                int mid = n / 2;
                if (s[mid] == QUESTION) {
                    if (rem1 >= 1) {
                        s[mid] = ONE;
                        rem1 -= 1;
                    } else if (rem0 >= 1) {
                        s[mid] = ZERO;
                        rem0 -= 1;
                    } else {
                        out.println("-1");
                        return;
                    }
                }
            }

            // Final check: Due to n = zeroBudget + oneBudget, 
            // if we filled all n slots without returning -1, 
            // the budget is naturally exhausted.
            out.println(new String(s));
        }
    }

    /**
     * Fast I/O reader class for efficient input processing.
     */
    static class InputReader {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (numChars == -1) throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) return -1;
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res = res * 10 + (c - '0');
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public char[] readCharArray(int size) {
            char[] array = new char[size];
            for (int i = 0; i < size; i++) {
                array[i] = (char) readCharacter();
            }
            return array;
        }

        public char readCharacter() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            return (char) c;
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A utility class to solve the palindrome construction problem.
 * The goal is to replace '?' in a string to form a palindrome 
 * such that the total count of '0's is targetZeroCount and '1's is targetOneCount.
 */
class PalindromeSolver {

    private static final String IMPOSSIBLE = "-1";

    public String solve(int targetZeroCount, int targetOneCount, String input) {
        int n = input.length();

        // Basic sanity check: total characters must match requested counts
        if (targetZeroCount + targetOneCount != n) {
            return IMPOSSIBLE;
        }

        char[] arr = input.toCharArray();

        // Pass 1: Enforce existing palindrome constraints
        if (!applySymmetryConstraints(arr)) {
            return IMPOSSIBLE;
        }

        // Pass 2: Calculate remaining requirements
        int currentZeroCount = 0;
        int currentOneCount = 0;
        for (char c : arr) {
            if (c == '0') currentZeroCount++;
            else if (c == '1') currentOneCount++;
        }

        int remainingZeroNeeded = targetZeroCount - currentZeroCount;
        int remainingOneNeeded = targetOneCount - currentOneCount;

        if (remainingZeroNeeded < 0 || remainingOneNeeded < 0) {
            return IMPOSSIBLE;
        }

        // Pass 3: Identify flexible components (pairs and middle element)
        int questionMarkPairs = 0;
        int middleIndex = (n % 2 != 0) ? n / 2 : -1;
        boolean middleIsQuestionMark = (middleIndex != -1 && arr[middleIndex] == '?');

        for (int i = 0; i < n / 2; i++) {
            if (arr[i] == '?' && arr[n - 1 - i] == '?') {
                questionMarkPairs++;
            }
        }

        // Pass 4: Distribute remaining digits
        // If middle is '?', it must satisfy the parity of the remaining counts
        if (middleIsQuestionMark) {
            if (remainingZeroNeeded % 2 != 0) {
                // Middle must be '0' to make the rest of the zeros even
                arr[middleIndex] = '0';
                remainingZeroNeeded--;
            } else if (remainingOneNeeded % 2 != 0) {
                // Middle must be '1' to make the rest of the ones even
                arr[middleIndex] = '1';
                remainingOneNeeded--;
            } else {
                // If both are even, the total sum (remZero + remOne) would be even,
                // but for an odd middle, the sum must be odd.
                return IMPOSSIBLE;
            }
        }

        // Verify remaining counts are even (as they must fill pairs)
        if (remainingZeroNeeded % 2 != 0 || remainingOneNeeded % 2 != 0) {
            return IMPOSSIBLE;
        }

        // Fill pairs
        int pairsOfZeros = remainingZeroNeeded / 2;
        int pairsOfOnes = remainingOneNeeded / 2;

        // Check if we have enough '??' pairs to satisfy the requirement
        if (pairsOfZeros + pairsOfOnes != questionMarkPairs) {
            return IMPOSSIBLE;
        }

        for (int i = 0; i < n / 2; i++) {
            int j = n - 1 - i;
            if (arr[i] == '?' && arr[j] == '?') {
                if (pairsOfZeros > 0) {
                    arr[i] = arr[j] = '0';
                    pairsOfZeros--;
                } else {
                    arr[i] = arr[j] = '1';
                    pairsOfOnes--;
                }
            }
        }

        return new String(arr);
    }

    /**
     * Ensures that existing '0's and '1's do not violate palindrome rules.
     * Also fills in '?' that are forced by a digit on the opposite side.
     */
    private boolean applySymmetryConstraints(char[] arr) {
        int n = arr.length;
        for (int i = 0; i < n / 2; i++) {
            int j = n - 1 - i;
            if (arr[i] != '?' && arr[j] != '?') {
                if (arr[i] != arr[j]) return false;
            } else if (arr[i] != '?') {
                arr[j] = arr[i];
            } else if (arr[j] != '?') {
                arr[i] = arr[j];
            }
        }
        return true;
    }
}

/**
 * Optimized input reader for fast performance.
 */
class FastReader {
    private BufferedReader reader;
    private StringTokenizer tokenizer;

    public FastReader(InputStream input) {
        reader = new BufferedReader(new InputStreamReader(input));
        tokenizer = null;
    }

    public String next() {
        while (tokenizer == null || !tokenizer.hasMoreElements()) {
            try {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                return null;
            }
        }
        return tokenizer.nextToken();
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }
}

