/**
 * A solver for finding a palindromic string that satisfies specific 
 * counts of '0's and '1's.
 */
class PalindromeSolver {

    private static final char ZERO = '0';
    private static final char ONE = '1';
    private static final char UNKNOWN = '?';

    /**
     * Attempts to construct a palindrome based on the given constraints.
     * 
     * @param zeroBudget Total number of '0's required in the final string.
     * @param oneBudget  Total number of '1's required in the final string.
     * @param sequence   The initial string containing '0', '1', and '?'.
     * @return A valid palindrome string, or null if no such string exists.
     */
    public String solve(int zeroBudget, int oneBudget, String sequence) {
        int n = sequence.length();

        // Basic constraint: Total budget must match string length
        if (zeroBudget + oneBudget != n) {
            return null;
        }

        char[] chars = sequence.toCharArray();

        // Step 1: Ensure palindrome consistency for already defined characters
        if (!synchronizeSymmetry(chars)) {
            return null;
        }

        // Step 2: Count current characters and calculate remaining budget
        int currentZeros = 0;
        int currentOnes = 0;
        for (char c : chars) {
            if (c == ZERO) currentZeros++;
            else if (c == ONE) currentOnes++;
        }

        if (currentZeros > zeroBudget || currentOnes > oneBudget) {
            return null;
        }

        int remainingZeros = zeroBudget - currentZeros;
        int remainingOnes = oneBudget - currentOnes;

        // Step 3: Fill the remaining '?' placeholders
        if (!fillRemainingPlaceholders(chars, remainingZeros, remainingOnes)) {
            return null;
        }

        return new String(chars);
    }

    /**
     * Fills '?' where the symmetric counterpart is already defined.
     * Also checks if existing characters already violate the palindrome property.
     */
    private boolean synchronizeSymmetry(char[] chars) {
        int n = chars.length;
        for (int i = 0; i < n / 2; i++) {
            int j = n - 1 - i;
            if (chars[i] != UNKNOWN && chars[j] != UNKNOWN) {
                if (chars[i] != chars[j]) return false;
            } else if (chars[i] != UNKNOWN) {
                chars[j] = chars[i];
            } else if (chars[j] != UNKNOWN) {
                chars[i] = chars[j];
            }
        }
        return true;
    }

    /**
     * Uses the remaining budget to fill in the remaining '?' pairs or single middle elements.
     */
    private boolean fillRemainingPlaceholders(char[] chars, int rem0, int rem1) {
        int n = chars.length;
        for (int i = 0; i <= (n - 1) / 2; i++) {
            int j = n - 1 - i;

            if (chars[i] == UNKNOWN) {
                if (i == j) {
                    // Middle element in an odd-length string
                    if (rem0 > 0) {
                        chars[i] = ZERO;
                        rem0--;
                    } else if (rem1 > 0) {
                        chars[i] = ONE;
                        rem1--;
                    } else {
                        return false;
                    }
                } else {
                    // Symmetric pair
                    if (rem0 >= 2) {
                        chars[i] = chars[j] = ZERO;
                        rem0 -= 2;
                    } else if (rem1 >= 2) {
                        chars[i] = chars[j] = ONE;
                        rem1 -= 2;
                    } else {
                        // Not enough budget to satisfy a symmetric pair
                        return false;
                    }
                }
            }
        }
        return rem0 == 0 && rem1 == 0;
    }
}

