/**
 * A utility class to solve the palindrome construction problem.
 * The goal is to fill '?' in a string to make it a palindrome 
 * while satisfying specific counts of '0's and '1's.
 */
class PalindromeSolver {

    /**
     * Attempts to construct a palindrome given the required counts of '0' and '1'.
     * 
     * @param countZeros The required total number of '0' characters.
     * @param countOnes  The required total number of '1' characters.
     * @param input      The input string containing '0', '1', or '?'.
     * @return The constructed palindrome string, or "-1" if impossible.
     */
    public String solve(int countZeros, int countOnes, String input) {
        char[] chars = input.toCharArray();
        int n = chars.length;
        List<Integer> flexiblePairIndices = new ArrayList<>();

        // 1. Process fixed pairs and mandatory fills
        for (int i = 0; i < n / 2; i++) {
            int j = n - 1 - i;

            if (chars[i] == '?' && chars[j] == '?') {
                // Both are flexible; we will decide their value later
                flexiblePairIndices.add(i);
            } else if (chars[i] == '?' || chars[j] == '?') {
                // One is fixed, the other must match it
                char fixedChar = (chars[i] == '?') ? chars[j] : chars[i];
                if (fixedChar == '0') {
                    countZeros -= 2;
                } else {
                    countOnes -= 2;
                }
                chars[i] = chars[j] = fixedChar;
            } else {
                // Both are fixed; they must be identical to form a palindrome
                if (chars[i] != chars[j]) {
                    return "-1";
                }
                if (chars[i] == '0') {
                    countZeros -= 2;
                } else {
                    countOnes -= 2;
                }
            }

            // If at any point we exceed our budget, it's impossible
            if (countZeros < 0 || countOnes < 0) {
                return "-1";
            }
        }

        // 2. Process the middle character for odd-length strings
        if (n % 2 != 0) {
            int mid = n / 2;
            if (chars[mid] == '?') {
                // For odd strings, the middle '?' must satisfy the parity of the remaining counts
                if (countZeros % 2 != 0) {
                    chars[mid] = '0';
                    countZeros--;
                } else if (countOnes % 2 != 0) {
                    chars[mid] = '1';
                    countOnes--;
                } else {
                    // If both counts are even, a middle '?' cannot satisfy the total count requirement
                    // because an odd-length string requires an odd sum of characters.
                    return "-1";
                }
            } else {
                if (chars[mid] == '0') {
                    countZeros--;
                } else {
                    countOnes--;
                }
            }
        }

        // 3. Validate if the remaining counts can perfectly fill the flexible slots
        if (countZeros < 0 || countOnes < 0 || countZeros % 2 != 0 || countOnes % 2 != 0) {
            return "-1";
        }

        int requiredFlexiblePairs = countZeros / 2 + countOnes / 2;
        if (requiredFlexiblePairs != flexiblePairIndices.size()) {
            return "-1";
        }

        // 4. Fill the flexible '?' pairs
        for (int index : flexiblePairIndices) {
            int partnerIndex = n - 1 - index;
            if (countZeros > 0) {
                chars[index] = chars[partnerIndex] = '0';
                countZeros -= 2;
            } else {
                chars[index] = chars[partnerIndex] = '1';
                countOnes -= 2;
            }
        }

        return new String(chars);
    }
}

