/**
 * A utility to construct a binary palindrome string from a pattern of '0', '1', and '?'.
 * The resulting palindrome must contain an exact specified count of '0's and '1's.
 */
public class PalindromeConstructor {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }

        int testCases = scanner.nextInt();
        StringBuilder outputBuffer = new StringBuilder();

        for (int t = 0; t < testCases; t++) {
            int targetZeros = scanner.nextInt();
            int targetOnes = scanner.nextInt();
            String pattern = scanner.next();

            outputBuffer.append(solve(targetZeros, targetOnes, pattern)).append("\n");
        }

        System.out.print(outputBuffer.toString());
        scanner.close();
    }

    /**
     * Orchestrates the solution for a single test case.
     *
     * @param targetZeros The required total number of '0' characters.
     * @param targetOnes  The required total number of '1' characters.
     * @param pattern     The input pattern containing '0', '1', and '?'.
     * @return The constructed palindrome string, or "-1" if impossible.
     */
    public static String solve(int targetZeros, int targetOnes, String pattern) {
        return constructPalindrome(targetZeros, targetOnes, pattern);
    }

    /**
     * Core logic to transform the pattern into a palindrome using the target counts.
     *
     * @param targetZeros The required total number of '0' characters.
     * @param targetOnes  The required total number of '1' characters.
     * @param pattern     The input pattern containing '0', '1', and '?'.
     * @return The constructed palindrome string, or "-1" if impossible.
     */
    private static String constructPalindrome(int targetZeros, int targetOnes, String pattern) {
        int n = pattern.length();
        char[] chars = pattern.toCharArray();

        int currentZeros = 0;
        int currentOnes = 0;

        // 1. Count characters already present in the pattern
        for (char c : chars) {
            if (c == '0') {
                currentZeros++;
            } else if (c == '1') {
                currentOnes++;
            }
        }

        // 2. Calculate how many more of each character we need to add
        int neededZeros = targetZeros - currentZeros;
        int neededOnes = targetOnes - currentOnes;

        // If the pattern already exceeds target counts, it's impossible
        if (neededZeros < 0 || neededOnes < 0) {
            return "-1";
        }

        // 3. Iterate through the string to fill '?' characters
        // We only need to iterate up to the middle of the string
        for (int i = 0; i < (n + 1) / 2; i++) {
            int j = n - 1 - i;

            if (i < j) {
                // Case: Symmetrical pair (two distinct indices)
                if (chars[i] != '?' && chars[j] != '?') {
                    // Both are already fixed; they must be equal to form a palindrome
                    if (chars[i] != chars[j]) {
                        return "-1";
                    }
                } else if (chars[i] == '?' && chars[j] == '?') {
                    // Both are unknown: greedily use pairs of the same character
                    if (neededZeros >= 2) {
                        chars[i] = chars[j] = '0';
                        neededZeros -= 2;
                    } else if (neededOnes >= 2) {
                        chars[i] = chars[j] = '1';
                        neededOnes -= 2;
                    } else {
                        return "-1";
                    }
                } else {
                    // One character is '?' and the other is fixed
                    char fixedChar = (chars[i] != '?') ? chars[i] : chars[j];

                    // Apply the fixed character to the '?' position
                    if (chars[i] == '?') {
                        chars[i] = fixedChar;
                    } else {
                        chars[j] = fixedChar;
                    }

                    // Update requirements
                    if (fixedChar == '0') {
                        neededZeros--;
                    } else {
                        neededOnes--;
                    }

                    if (neededZeros < 0 || neededOnes < 0) {
                        return "-1";
                    }
                }
            } else if (i == j) {
                // Case: Middle element (for odd-length strings)
                if (chars[i] == '?') {
                    if (neededZeros >= 1) {
                        chars[i] = '0';
                        neededZeros--;
                    } else if (neededOnes >= 1) {
                        chars[i] = '1';
                        neededOnes--;
                    } else {
                        return "-1";
                    }
                }
            }
        }

        // 4. Final Validation: ensure all requirements are met exactly
        if (neededZeros == 0 && neededOnes == 0 && isPalindrome(chars)) {
            return new String(chars);
        } else {
            return "-1";
        }
    }

    /**
     * Validates if the given character array forms a palindrome.
     *
     * @param chars The character array to check.
     * @return true if it is a palindrome, false otherwise.
     */
    private static boolean isPalindrome(char[] chars) {
        int left = 0;
        int right = chars.length - 1;
        while (left < right) {
            if (chars[left++] != chars[right--]) {
                return false;
            }
        }
        return true;
    }
}

