/**
 * A utility to solve the palindrome construction problem:
 * Given a string of '0', '1', and '?', and a fixed number of '0's and '1's available,
 * construct a palindrome using exactly all available digits.
 */
public class PalindromeGenerator {

    private static final char ZERO = '0';
    private static final char ONE = '1';
    private static final char QUESTION = '?';

    public static void main(String[] args) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String line = reader.readLine();
            if (line == null) return;

            int testCaseCount = Integer.parseInt(line.trim());

            for (int t = 0; t < testCaseCount; t++) {
                processTestCase(reader);
            }
        } catch (IOException | NumberFormatException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    private static void processTestCase(BufferedReader reader) throws IOException {
        String[] counts = reader.readLine().trim().split("\\s+");
        int zerosAvailable = Integer.parseInt(counts[0]);
        int onesAvailable = Integer.parseInt(counts[1]);

        String inputString = reader.readLine().trim();
        String result = solve(inputString, zerosAvailable, onesAvailable);
        System.out.println(result);
    }

    /**
     * Attempts to construct a palindrome using the provided counts of 0s and 1s.
     * 
     * @param s The input string containing '0', '1', or '?'.
     * @param zerosAvailable Total number of '0's to be used.
     * @param onesAvailable Total number of '1's to be used.
     * @return The constructed palindrome, or "-1" if impossible.
     */
    public static String solve(String s, int zerosAvailable, int onesAvailable) {
        int n = s.length();
        char[] chars = s.toCharArray();

        // Pass 1: Handle fixed characters and symmetry requirements
        for (int i = 0; i < n / 2; i++) {
            int left = i;
            int right = n - 1 - i;

            if (chars[left] != QUESTION && chars[right] != QUESTION) {
                // Both are digits: must be identical
                if (chars[left] != chars[right]) {
                    return "-1";
                }
                // Subtract the pair from available counts
                if (chars[left] == ZERO) {
                    zerosAvailable -= 2;
                } else {
                    onesAvailable -= 2;
                }
            } else if (chars[left] != QUESTION && chars[right] == QUESTION) {
                // Left is digit, right is ?: fill right with left
                chars[right] = chars[left];
                if (chars[left] == ZERO) {
                    zerosAvailable -= 2;
                } else {
                    onesAvailable -= 2;
                }
            } else if (chars[left] == QUESTION && chars[right] != QUESTION) {
                // Right is digit, left is ?: fill left with right
                chars[left] = chars[right];
                if (chars[right] == ZERO) {
                    zerosAvailable -= 2;
                } else {
                    onesAvailable -= 2;
                }
            }
            // If both are '?', we leave them to be handled in Pass 3
        }

        // Handle the middle element for odd lengths if it's already a digit
        if (n % 2 != 0) {
            int mid = n / 2;
            if (chars[mid] != QUESTION) {
                if (chars[mid] == ZERO) {
                    zerosAvailable -= 1;
                } else {
                    onesAvailable -= 1;
                }
            }
        }

        // If we've already used more than available, it's impossible
        if (zerosAvailable < 0 || onesAvailable < 0) {
            return "-1";
        }

        // Pass 2: Handle the middle '?' for odd-length strings
        // The middle must resolve the parity of the remaining counts
        if (n % 2 != 0) {
            int mid = n / 2;
            if (chars[mid] == QUESTION) {
                if (zerosAvailable % 2 != 0 && onesAvailable % 2 == 0) {
                    chars[mid] = ZERO;
                    zerosAvailable -= 1;
                } else if (onesAvailable % 2 != 0 && zerosAvailable % 2 == 0) {
                    chars[mid] = ONE;
                    onesAvailable -= 1;
                } else {
                    // If both are even or both are odd, we can't satisfy the exact counts
                    return "-1";
                }
            }
        }

        // Pass 3: Fill remaining '?' pairs
        for (int i = 0; i < n / 2; i++) {
            int left = i;
            int right = n - 1 - i;

            if (chars[left] == QUESTION) {
                if (zerosAvailable >= 2) {
                    chars[left] = chars[right] = ZERO;
                    zerosAvailable -= 2;
                } else if (onesAvailable >= 2) {
                    chars[left] = chars[right] = ONE;
                    onesAvailable -= 2;
                } else {
                    return "-1";
                }
            }
        }

        // Final Validation: Did we use exactly all available digits?
        if (zerosAvailable == 0 && onesAvailable == 0) {
            return new String(chars);
        } else {
            return "-1";
        }
    }
}

