    /**
     * Attempts to construct a palindrome based on the target counts.
     * 
     * @param targetZero The exact number of '0' characters required.
     * @param targetOne  The exact number of '1' characters required.
     * @param s          The input string containing '0', '1', or '?'.
     * @return The constructed palindrome string, or "-1" if impossible.
     */
    private static String solvePalindrome(int targetZero, int targetOne, String s) {
        int n = s.length();
        char[] charArray = s.toCharArray();

        // Basic validation: total characters must match the requirements
        if (targetZero + targetOne != n) {
            return "-1";
        }

        List<Integer> unassignedPairs = new ArrayList<>();
        int middleUnassignedIndex = -1;

        // Pass 1: Resolve forced symmetry
        // If one side is a digit and the other is '?', the '?' must become that digit.
        for (int i = 0; i <= (n - 1) / 2; i++) {
            int j = n - 1 - i;

            if (i == j) {
                // Handle the middle element in odd-length strings
                if (charArray[i] == '?') {
                    middleUnassignedIndex = i;
                }
            } else {
                if (charArray[i] != '?' && charArray[j] != '?') {
                    // If both are digits, they must match to be a palindrome
                    if (charArray[i] != charArray[j]) {
                        return "-1";
                    }
                } else if (charArray[i] != '?' && charArray[j] == '?') {
                    charArray[j] = charArray[i];
                } else if (charArray[i] == '?' && charArray[j] != '?') {
                    charArray[i] = charArray[j];
                } else {
                    // Both are '?', mark for greedy filling later
                    unassignedPairs.add(i);
                }
            }
        }

        // Pass 2: Count current distribution
        int currentZeroCount = 0;
        int currentOneCount = 0;
        for (char c : charArray) {
            if (c == '0') currentZeroCount++;
            else if (c == '1') currentOneCount++;
        }

        int remainingZeroNeeded = targetZero - currentZeroCount;
        int remainingOneNeeded = targetOne - currentOneCount;

        // If we already exceeded the requirements, it's impossible
        if (remainingZeroNeeded < 0 || remainingOneNeeded < 0) {
            return "-1";
        }

        // Pass 3: Fill remaining '??' pairs greedily
        for (int idx : unassignedPairs) {
            int oppositeIdx = n - 1 - idx;
            if (remainingOneNeeded >= 2) {
                charArray[idx] = '1';
                charArray[oppositeIdx] = '1';
                remainingOneNeeded -= 2;
            } else if (remainingZeroNeeded >= 2) {
                charArray[idx] = '0';
                charArray[oppositeIdx] = '0';
                remainingZeroNeeded -= 2;
            } else {
                // Cannot satisfy a pair requirement with only 1 character left
                return "-1";
            }
        }

        // Pass 4: Fill the middle '?' if it exists
        if (middleUnassignedIndex != -1) {
            if (remainingOneNeeded == 1) {
                charArray[middleUnassignedIndex] = '1';
                remainingOneNeeded -= 1;
            } else if (remainingZeroNeeded == 1) {
                charArray[middleUnassignedIndex] = '0';
                remainingZeroNeeded -= 1;
            } else {
                return "-1";
            }
        }

        // Final validation: Ensure all requirements are met exactly
        if (remainingZeroNeeded == 0 && remainingOneNeeded == 0) {
            return new String(charArray);
        } else {
            return "-1";
        }
    }
}

