/**
 * A utility class to solve the problem of transforming a string containing '0', '1', or '?'
 * into a palindrome with a specific count of '0's and '1's.
 */
class PalindromeSolver {

    private static final char ZERO = '0';
    private static final char ONE = '1';
    private static final char UNKNOWN = '?';

    /**
     * Attempts to construct a palindrome from the input string.
     *
     * @param targetZeros The required number of '0' characters.
     * @param targetOnes  The required number of '1' characters.
     * @param input       The string containing '0', '1', and '?'.
     * @return The resulting palindrome string, or null if no valid palindrome exists.
     */
    public String solve(int targetZeros, int targetOnes, String input) {
        if (input == null) return null;

        int n = input.length();
        char[] chars = input.toCharArray();

        // Step 1: Fill '?' where the mirrored position has a fixed character
        if (!fillKnownCharacters(chars, n)) {
            return null;
        }

        // Step 2: Count existing characters and determine how many more we need
        int currentZeros = 0;
        int currentOnes = 0;
        for (char c : chars) {
            if (c == ZERO) currentZeros++;
            else if (c == ONE) currentOnes++;
        }

        int remainingZeros = targetZeros - currentZeros;
        int remainingOnes = targetOnes - currentOnes;

        // If we already exceeded the target, it's impossible
        if (remainingZeros < 0 || remainingOnes < 0) {
            return null;
        }

        // Step 3: Fill remaining '?' pairs and middle elements
        if (!fillRemainingQuestions(chars, n, remainingZeros, remainingOnes)) {
            return null;
        }

        // Step 4: Final verification of counts and palindrome property
        if (isSolutionValid(chars, targetZeros, targetOnes)) {
            return new String(chars);
        }

        return null;
    }

    /**
     * Ensures that existing characters don't already violate the palindrome property
     * and fills '?' that have a fixed counterpart.
     */
    private boolean fillKnownCharacters(char[] chars, int n) {
        for (int i = 0; i < n / 2; i++) {
            int j = n - 1 - i;
            if (chars[i] != UNKNOWN && chars[j] != UNKNOWN) {
                if (chars[i] != chars[j]) return false;
            } else if (chars[i] != UNKNOWN) {
                chars[j] = chars[i];
            } else if (chars[j] != UNKNOWN) {
                chars[i] = chars[j];
            }
        }
        return true;
    }

    /**
     * Fills the remaining '?' characters using the required budget of zeros and ones.
     */
    private boolean fillRemainingQuestions(char[] chars, int n, int rem0, int rem1) {
        // We iterate through the first half, including the middle element
        for (int i = 0; i <= (n - 1) / 2; i++) {
            int j = n - 1 - i;

            if (i == j) { 
                // Case: Middle element in an odd-length string
                if (chars[i] == UNKNOWN) {
                    if (rem0 >= 1) {
                        chars[i] = ZERO;
                        rem0--;
                    } else if (rem1 >= 1) {
                        chars[i] = ONE;
                        rem1--;
                    } else {
                        return false;
                    }
                }
            } else { 
                // Case: A pair of mirrored positions
                if (chars[i] == UNKNOWN) {
                    if (rem0 >= 2) {
                        chars[i] = chars[j] = ZERO;
                        rem0 -= 2;
                    } else if (rem1 >= 2) {
                        chars[i] = chars[j] = ONE;
                        rem1 -= 2;
                    } else {
                        return false;
                    }
                }
            }
        }
        // Check if we used exactly the required counts
        return rem0 == 0 && rem1 == 0;
    }

    /**
     * Final validation to ensure the string is a palindrome and counts are exact.
     */
    private boolean isSolutionValid(char[] chars, int targetZeros, int targetOnes) {
        int count0 = 0;
        int count1 = 0;
        int n = chars.length;

        for (int i = 0; i < n; i++) {
            if (chars[i] == ZERO) count0++;
            else if (chars[i] == ONE) count1++;

            // Palindrome check
            if (chars[i] != chars[n - 1 - i]) return false;
        }

        return count0 == targetZeros && count1 == targetOnes;
    }
}

