/**
 * A program to construct a palindrome of length (a + b) containing exactly
 * 'a' zeros and 'b' ones, given a pattern string with '?' as wildcards.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        int testCases = reader.nextInt();
        while (testCases-- > 0) {
            writer.println(solve(reader));
        }

        writer.flush();
        writer.close();
    }

    /**
     * Orchestrates the input reading and calls the solver.
     */
    private static String solve(FastReader reader) {
        int a = reader.nextInt();
        int b = reader.nextInt();
        String pattern = reader.next();

        if (pattern == null) return "-1";

        return PalindromeSolver.constructPalindrome(a, b, pattern);
    }

    /**
     * Contains the business logic for constructing the palindrome.
     */
    static class PalindromeSolver {

        public static String constructPalindrome(int targetA, int targetB, String pattern) {
            int n = targetA + targetB;
            char[] res = pattern.toCharArray();

            int neededA = targetA;
            int neededB = targetB;

            List<Integer> flexiblePairs = new ArrayList<>();
            int middleIdx = -1;

            // Step 1: Handle fixed characters and mandatory symmetric matches
            for (int i = 0; i <= (n - 1) / 2; i++) {
                int j = n - 1 - i;

                if (i == j) {
                    // Handle the middle character in an odd-length string
                    if (res[i] == '0') {
                        neededA--;
                    } else if (res[i] == '1') {
                        neededB--;
                    } else {
                        middleIdx = i;
                    }
                } else {
                    if (res[i] == '?' && res[j] == '?') {
                        // Both are wildcards, save for later
                        flexiblePairs.add(i);
                    } else if (res[i] != '?' && res[j] != '?') {
                        // Both are fixed: they must match
                        if (res[i] != res[j]) return "-1";
                        if (res[i] == '0') neededA -= 2;
                        else neededB -= 2;
                    } else {
                        // One is '?' and the other is fixed: the '?' must match the fixed one
                        char fixedChar = (res[i] == '?') ? res[j] : res[i];
                        res[i] = res[j] = fixedChar;
                        if (fixedChar == '0') neededA -= 2;
                        else neededB -= 2;
                    }
                }
            }

            // If we already exceeded the required counts
            if (neededA < 0 || neededB < 0) return "-1";

            // Step 2: Use flexible '?' pairs to satisfy target counts
            for (int idx : flexiblePairs) {
                int j = n - 1 - idx;
                if (neededA >= 2) {
                    res[idx] = res[j] = '0';
                    neededA -= 2;
                } else if (neededB >= 2) {
                    res[idx] = res[j] = '1';
                    neededB -= 2;
                } else {
                    // Cannot satisfy the requirement with even pairs
                    return "-1";
                }
            }

            // Step 3: Use the middle character to satisfy the final requirement
            if (middleIdx != -1) {
                if (res[middleIdx] == '?') {
                    if (neededA >= 1) {
                        res[middleIdx] = '0';
                        neededA--;
                    } else if (neededB >= 1) {
                        res[middleIdx] = '1';
                        neededB--;
                    } else {
                        return "-1";
                    }
                }
            }

            // Final Validation: Ensure all characters were assigned correctly
            return (neededA == 0 && neededB == 0) ? new String(res) : "-1";
        }
    }

    /**
     * Optimized reader for fast input parsing.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

