/**
 * A solver for constructing a palindrome string from a template containing '0', '1', and '?'.
 */
class PalindromeSolver {

    /**
     * Attempts to construct a palindrome string that satisfies specific digit counts.
     *
     * @param targetZeroCount The required number of '0' characters.
     * @param targetOneCount  The required number of '1' characters.
     * @param inputString     The template string containing '0', '1', and '?'.
     * @return The constructed palindrome string, or "-1" if impossible.
     */
    public String solve(int targetZeroCount, int targetOneCount, String inputString) {
        int length = inputString.length();

        // Base validation: the total requested characters must match the string length.
        if (targetZeroCount + targetOneCount != length) {
            return "-1";
        }

        char[] resultArr = inputString.toCharArray();

        // Step 1: Symmetrize the string.
        // If one side of a symmetric pair is a digit, the other must match it.
        if (!applySymmetry(resultArr, length)) {
            return "-1";
        }

        // Step 2: Count existing digits to determine how many more we need.
        int currentZeroCount = 0;
        int currentOneCount = 0;
        for (char c : resultArr) {
            if (c == '0') {
                currentZeroCount++;
            } else if (c == '1') {
                currentOneCount++;
            }
        }

        int remainingZerosNeeded = targetZeroCount - currentZeroCount;
        int remainingOnesNeeded = targetOneCount - currentOneCount;

        // If we have already exceeded the target counts, it's impossible.
        if (remainingZerosNeeded < 0 || remainingOnesNeeded < 0) {
            return "-1";
        }

        // Step 3: Fill symmetric '?' pairs.
        // Since it must be a palindrome, '?' pairs must be filled with the same digit.
        for (int i = 0; i < length / 2; i++) {
            int oppositeIndex = length - 1 - i;
            if (resultArr[i] == '?') {
                // Because of Step 1, if resultArr[i] is '?', resultArr[oppositeIndex] is also '?'.
                if (remainingZerosNeeded >= 2) {
                    resultArr[i] = resultArr[oppositeIndex] = '0';
                    remainingZerosNeeded -= 2;
                } else if (remainingOnesNeeded >= 2) {
                    resultArr[i] = resultArr[oppositeIndex] = '1';
                    remainingOnesNeeded -= 2;
                } else {
                    // Cannot fulfill a pair with the remaining budget.
                    return "-1";
                }
            }
        }

        // Step 4: Handle the middle element for odd-length strings.
        if (length % 2 == 1) {
            int middleIndex = length / 2;
            if (resultArr[middleIndex] == '?') {
                if (remainingZerosNeeded >= 1) {
                    resultArr[middleIndex] = '0';
                    remainingZerosNeeded -= 1;
                } else if (remainingOnesNeeded >= 1) {
                    resultArr[middleIndex] = '1';
                    remainingOnesNeeded -= 1;
                } else {
                    return "-1";
                }
            }
        }

        // Step 5: Final Validation.
        // Ensure all requirements were met exactly and the palindrome property holds.
        if (remainingZerosNeeded == 0 && remainingOnesNeeded == 0 && isPalindrome(resultArr)) {
            return new String(resultArr);
        } else {
            return "-1";
        }
    }

    private boolean applySymmetry(char[] arr, int n) {
        for (int i = 0; i < n / 2; i++) {
            int j = n - 1 - i;
            if (arr[i] != '?' && arr[j] != '?') {
                if (arr[i] != arr[j]) return false;
            } else if (arr[i] != '?') {
                arr[j] = arr[i];
            } else if (arr[j] != '?') {
                arr[i] = arr[j];
            }
        }
        return true;
    }

    private boolean isPalindrome(char[] arr) {
        int left = 0;
        int right = arr.length - 1;
        while (left < right) {
            if (arr[left] != arr[right]) return false;
            left++;
            right--;
        }
        return true;
    }
}

