            } else if (sequence[i] != '?') {
                sequence[j] = sequence[i];
            } else if (sequence[j] != '?') {
                sequence[i] = sequence[j];
            }
        }

        // Step 2: Count current fixed characters.
        int currentZeros = 0;
        int currentOnes = 0;
        for (char c : sequence) {
            if (c == '0') currentZeros++;
            else if (c == '1') currentOnes++;
        }

        // If we already exceeded the allowed counts, it's impossible.
        if (currentZeros > targetZeroCount || currentOnes > targetOneCount) {
            return "-1";
        }

        int neededZeros = targetZeroCount - currentZeros;
        int neededOnes = targetOneCount - currentOnes;

        // Step 3: Fill remaining '?' characters.
        // To maintain the palindrome, we must fill pairs of '?' with the same character.
        for (int i = 0; i <= n / 2; i++) {
            int j = n - 1 - i;
            if (i > j) break; // Safety break

            if (sequence[i] == '?') {
                if (i == j) {
                    // Handle the middle element in odd-length sequences.
                    if (neededZeros >= 1) {
                        sequence[i] = '0';
                        neededZeros--;
                    } else if (neededOnes >= 1) {
                        sequence[i] = '1';
                        neededOnes--;
                    } else {
                        return "-1";
                    }
                } else {
                    // Handle a symmetric pair.
                    if (neededZeros >= 2) {
                        sequence[i] = sequence[j] = '0';
                        neededZeros -= 2;
                    } else if (neededOnes >= 2) {
                        sequence[i] = sequence[j] = '1';
                        neededOnes -= 2;
                    } else {
                        // Cannot fulfill a pair with only 1 remaining character.
                        return "-1";
                    }
                }
            }
        }

        // Verify if all required characters were used exactly.
        if (neededZeros == 0 && neededOnes == 0) {
            return new String(sequence);
        } else {
            return "-1";
        }
    }
}

