/**
 * A solution to construct a palindrome of a specific length given a target 
 * number of '0's and '1's, while respecting existing characters in a string.
 */
public class PalindromeSolver {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int testCases = scanner.nextInt();
        while (testCases-- > 0) {
            out.println(solve(scanner));
        }

        out.flush();
        out.close();
    }

    /**
     * Processes a single test case.
     * 
     * @param sc The FastScanner instance for input.
     * @return The constructed palindrome string, or "-1" if no such palindrome exists.
     */
    private static String solve(FastScanner sc) {
        int targetZeroCount = sc.nextInt();
        int targetOneCount = sc.nextInt();
        int totalLength = targetZeroCount + targetOneCount;
        char[] chars = sc.next().toCharArray();

        // 1. Symmetry Pass: Match symmetric characters
        // If both characters in a symmetric pair are known and different, it's impossible.
        for (int i = 0; i < totalLength / 2; i++) {
            int j = totalLength - 1 - i;
            if (chars[i] != '?' && chars[j] != '?') {
                if (chars[i] != chars[j]) {
                    return "-1";
                }
            } else if (chars[i] != '?') {
                chars[j] = chars[i];
            } else if (chars[j] != '?') {
                chars[i] = chars[j];
            }
        }

        // 2. Middle Element Pass (for odd-length strings)
        // In a palindrome, if the total count of a character is odd, 
        // that character must occupy the middle position in an odd-length string.
        if (totalLength % 2 == 1) {
            int midIndex = totalLength / 2;
            // If targetZeroCount is odd, the middle character MUST be '0'.
            char requiredMid = (targetZeroCount % 2 == 1) ? '0' : '1';

            if (chars[midIndex] != '?' && chars[midIndex] != requiredMid) {
                return "-1";
            }
            chars[midIndex] = requiredMid;
        }

        // 3. Counting Pass: Count current state of the array
        int currentZeroCount = 0;
        int currentOneCount = 0;
        for (char c : chars) {
            if (c == '0') {
                currentZeroCount++;
            } else if (c == '1') {
                currentOneCount++;
            }
        }

        // 4. Validation: Check if existing counts exceed targets or parity is impossible
        int remainingZerosNeeded = targetZeroCount - currentZeroCount;
        int remainingOnesNeeded = targetOneCount - currentOneCount;

        // All characters are added in pairs (except the middle one, which we handled).
        // Therefore, remaining counts must be non-negative and even.
        if (remainingZerosNeeded < 0 || remainingOnesNeeded < 0 || 
            remainingZerosNeeded % 2 != 0 || remainingOnesNeeded % 2 != 0) {
            return "-1";
        }

        // 5. Filling Pass: Fill remaining '?' pairs
        for (int i = 0; i < totalLength / 2; i++) {
            int j = totalLength - 1 - i;
            if (chars[i] == '?') {
                if (remainingZerosNeeded > 0) {
                    chars[i] = '0';
                    chars[j] = '0';
                    remainingZerosNeeded -= 2;
                } else {
                    chars[i] = '1';
                    chars[j] = '1';
                    remainingOnesNeeded -= 2;
                }
            }
        }

        // Final check to ensure all requirements were met exactly
        if (remainingZerosNeeded != 0 || remainingOnesNeeded != 0) {
            return "-1";
        }

        return new String(chars);
    }

    /**
     * Fast I/O utility for high-performance reading.
     */
    static class FastScanner {
