public class ABPalindrome {

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        try {
            String firstLine = reader.readLine();
            if (firstLine == null) return;
            int testCases = Integer.parseInt(firstLine.trim());
            while (testCases-- > 0) {
                process(reader);
            }
        } catch (Exception e) {
            // Silently fail or log
        }
    }

    private static void process(FastReader reader) throws IOException {
        String line = reader.readLine();
        if (line == null) return;
        StringTokenizer st = new StringTokenizer(line);
        int targetZeros = Integer.parseInt(st.nextToken());
        int targetOnes = Integer.parseInt(st.nextToken());
        char[] arr = reader.readLine().toCharArray();

        System.out.println(new Solver(arr, targetZeros, targetOnes).solve());
    }

    static class Solver {
        private final char[] arr;
        private final int n;
        private int rem0;
        private int rem1;

        public Solver(char[] arr, int target0, int target1) {
            this.arr = arr;
            this.n = arr.length;
            this.rem0 = target0;
            this.rem1 = target1;
        }

        public String solve() {
            if (rem0 + rem1 != n) return "-1";

            // 1. Handle fixed chars and forced palindromic symmetry
            for (int i = 0; i < n / 2; i++) {
                int j = n - 1 - i;
                if (arr[i] != '?' && arr[j] != '?') {
                    if (arr[i] != arr[j]) return "-1";
                    updateCounts(arr[i]);
                } else if (arr[i] != '?') {
                    arr[j] = arr[i];
                    updateCounts(arr[i]);
                } else if (arr[j] != '?') {
                    arr[i] = arr[j];
                    updateCounts(arr[j]);
                }
            }

            // Handle middle element if fixed
            if (n % 2 != 0 && arr[n / 2] != '?') {
                updateCounts(arr[n / 2]);
            }

            if (rem0 < 0 || rem1 < 0) return "-1";

            // 2. Count remaining flexible pairs and middle question mark
            int questionPairs = 0;
            for (int i = 0; i < n / 2; i++) {
                if (arr[i] == '?') questionPairs++;
            }
            boolean middleIsQuestion = (n % 2 != 0 && arr[n / 2] == '?');

            // 3. Try to solve for middle element
            if (middleIsQuestion) {
                // Try '0'
                if (canFill(questionPairs, rem0 - 1, rem1)) {
                    fill(questionPairs, rem0 - 1, rem1, '0');
                    arr[n / 2] = '0';
                    return new String(arr);
                }
                // Try '1'
                if (canFill(questionPairs, rem0, rem1 - 1)) {
                    fill(questionPairs, rem0, rem1 - 1, '1');
                    arr[n / 2] = '1';
                    return new String(arr);
                }
            } else {
                if (canFill(questionPairs, rem0, rem1)) {
                    fill(questionPairs, rem0, rem1, ' ');
                    return new String(arr);
                }
            }

            return "-1";
        }

        private void updateCounts(char c) {
            if (c == '0') rem0--;
            else if (c == '1') rem1--;
        }

        private boolean canFill(int pairs, int z, int o) {
            return z >= 0 && o >= 0 && z % 2 == 0 && o % 2 == 0 && (z / 2 + o / 2 == pairs);
        }

        private void fill(int pairs, int z, int o, char mid) {
            int zeroPairs = z / 2;
            int onePairs = o / 2;
            int currentPair = 0;

            for (int i = 0; i < n / 2; i++) {
                int j = n - 1 - i;
                if (arr[i] == '?') {
                    if (currentPair < zeroPairs) {
                        arr[i] = arr[j] = '0';
                    } else {
                        arr[i] = arr[j] = '1';
                    }
                    currentPair++;
                }
            }
        }
    }

    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader() {
            reader = new BufferedReader(new InputStreamReader(System.in));
        }

        public String readLine() throws IOException {
            return reader.readLine();
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
            return tokenizer.nextToken();
        }
    }
}

