/**
 * A utility class to solve the palindrome construction problem.
 * The goal is to replace '?' characters in a string with '0' or '1'
 * to form a palindrome that meets exact counts of '0's and '1's.
 */
public class PalindromeTaskSolver {

    public static void main(String[] args) {
        // Use try-with-resources to ensure the Scanner is closed automatically
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int numTestCases = scanner.nextInt();

            for (int t = 0; t < numTestCases; t++) {
                int targetZeros = scanner.nextInt();
                int targetOnes = scanner.nextInt();
                String inputString = scanner.next();

                System.out.println(solvePalindrome(inputString, targetZeros, targetOnes));
            }
        }
    }

    /**
     * Determines if a palindrome can be formed by replacing '?' with '0' or '1'
     * such that the resulting string has exactly the specified number of 0s and 1s.
     *
     * @param s           The input string containing '0', '1', and '?'.
     * @param targetZeros The required number of '0' characters.
     * @param targetOnes  The required number of '1' characters.
     * @return The constructed palindrome string, or "-1" if it's impossible.
     */
    public static String solvePalindrome(String s, int targetZeros, int targetOnes) {
        int n = s.length();

        // Basic validation: the sum of target counts must equal the string length
        if (targetZeros + targetOnes != n) {
            return "-1";
        }

        char[] chars = s.toCharArray();
        int currentZeros = 0;
        int currentOnes = 0;

        // Count existing fixed characters
        for (char c : chars) {
            if (c == '0') currentZeros++;
            else if (c == '1') currentOnes++;
        }

        // Calculate how many more 0s and 1s we need to place
        int neededZeros = targetZeros - currentZeros;
        int neededOnes = targetOnes - currentOnes;

        // If we already have more 0s or 1s than allowed, it's impossible
        if (neededZeros < 0 || neededOnes < 0) {
            return "-1";
        }

        /*
         * Pass 1: Handle symmetry for fixed characters.
         * If one character in a symmetric pair is fixed and the other is '?',
         * the '?' must take the value of the fixed character.
         */
        for (int i = 0; i < n / 2; i++) {
            int left = i;
            int right = n - 1 - i;

            if (chars[left] != '?' && chars[right] != '?') {
                // Both are fixed: they must be equal to maintain a palindrome
                if (chars[left] != chars[right]) {
                    return "-1";
                }
            } else if (chars[left] == '?' && chars[right] != '?') {
                // Left is '?', Right is fixed
                chars[left] = chars[right];
                if (chars[left] == '0') neededZeros--;
                else neededOnes--;
            } else if (chars[right] == '?' && chars[left] != '?') {
                // Right is '?', Left is fixed
                chars[right] = chars[left];
                if (chars[right] == '0') neededZeros--;
                else neededOnes--;
            }

            // Check if filling these '?' made us exceed our required counts
            if (neededZeros < 0 || neededOnes < 0) {
                return "-1";
            }
        }

        /*
         * Pass 2: Fill remaining '?' positions.
         * This includes pairs where both are '?' and the middle element of odd-length strings.
         */
        for (int i = 0; i <= n / 2; i++) {
            int left = i;
            int right = n - 1 - i;

            // Safety break for the loop
            if (left > right) break;

            if (left < right && chars[left] == '?' && chars[right] == '?') {
                // Both are '?' - we must use characters in pairs to maintain symmetry
                if (neededZeros >= 2) {
                    chars[left] = '0';
                    chars[right] = '0';
                    neededZeros -= 2;
                } else if (neededOnes >= 2) {
                    chars[left] = '1';
                    chars[right] = '1';
                    neededOnes -= 2;
                } else {
                    // Not enough of either to form a symmetric pair
                    return "-1";
                }
            } else if (left == right && chars[left] == '?') {
                // This is the middle element of an odd-length string
                if (neededZeros >= 1) {
                    chars[left] = '0';
                    neededZeros--;
                } else if (neededOnes >= 1) {
                    chars[left] = '1';
                    neededOnes--;
                } else {
                    return "-1";
                }
            }
        }

        // Final validation: check if we used exactly the required number of 0s and 1s
        if (neededZeros == 0 && neededOnes == 0) {
            return new String(chars);
        } else {
            return "-1";
        }
    }
}

