/**
 * A utility to solve the palindrome construction problem where a given string 
 * must be transformed into a palindrome with specific counts of '0' and '1'.
 */
public class PalindromeBuilder {

    private static final char ZERO = '0';
    private static final char ONE = '1';
    private static final char UNKNOWN = '?';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int testCases = scanner.nextInt();

        while (testCases-- > 0) {
            int targetZeroCount = scanner.nextInt();
            int targetOneCount = scanner.nextInt();
            String inputString = scanner.next();

            String result = solve(targetZeroCount, targetOneCount, inputString);
            System.out.println(result == null ? -1 : result);
        }
        scanner.close();
    }

    /**
     * Attempts to construct a palindrome based on the provided constraints.
     * 
     * @param targetZeroCount The required number of '0' characters.
     * @param targetOneCount  The required number of '1' characters.
     * @param sequence        The initial string containing '0', '1', or '?'.
     * @return A valid palindrome string, or null if no such palindrome exists.
     */
    public static String solve(int targetZeroCount, int targetOneCount, String sequence) {
        char[] s = sequence.toCharArray();
        int n = s.length;

        // Phase 1: Symmetrize existing characters
        if (!symmetrize(s, n)) {
            return null;
        }

        // Phase 2: Count current characters
        int currentZeroCount = 0;
        int currentOneCount = 0;
        for (char c : s) {
            if (c == ZERO) currentZeroCount++;
            else if (c == ONE) currentOneCount++;
        }

        // Phase 3: Validate if current counts already exceed targets
        int neededZero = targetZeroCount - currentZeroCount;
        int neededOne = targetOneCount - currentOneCount;

        if (neededZero < 0 || neededOne < 0) {
            return null;
        }

        // Phase 4: Fill remaining '?' to meet targets
        if (!fillRemaining(s, n, neededZero, neededOne)) {
            return null;
        }

        // Phase 5: Final Verification
        // Re-verify that the counts match exactly (handles edge cases with odd lengths)
        int finalZero = 0;
        int finalOne = 0;
        for (char c : s) {
            if (c == ZERO) finalZero++;
            else if (c == ONE) finalOne++;
        }

        if (finalZero == targetZeroCount && finalOne == targetOneCount) {
            return new String(s);
        } else {
            return null;
        }
    }

    /**
     * Ensures that for every index i, s[i] == s[n-1-i].
     * If one is set and the other is '?', the '?' is filled.
     * If both are set and different, returns false.
     */
    private static boolean symmetrize(char[] s, int n) {
        for (int i = 0; i < (n + 1) / 2; i++) {
            int j = n - 1 - i;
            if (s[i] != UNKNOWN && s[j] != UNKNOWN) {
                if (s[i] != s[j]) return false;
            } else if (s[i] != UNKNOWN) {
                s[j] = s[i];
            } else if (s[j] != UNKNOWN) {
                s[i] = s[j];
            }
        }
        return true;
    }

    /**
     * Fills the remaining '?' characters using the required counts.
     */
    private static boolean fillRemaining(char[] s, int n, int neededZero, int neededOne) {
        for (int i = 0; i < (n + 1) / 2; i++) {
            int j = n - 1 - i;

            if (s[i] == UNKNOWN) {
                if (i == j) {
                    // Handle the middle element in odd-length strings
                    if (neededZero > 0) {
                        s[i] = ZERO;
                        neededZero--;
                    } else if (neededOne > 0) {
                        s[i] = ONE;
                        neededOne--;
                    } else {
                        return false;
                    }
                } else {
                    // Handle symmetric pairs
                    if (neededZero >= 2) {
                        s[i] = s[j] = ZERO;
                        neededZero -= 2;
                    } else if (neededOne >= 2) {
                        s[i] = s[j] = ONE;
                        neededOne -= 2;
                    } else {
                        // Cannot satisfy a pair with only 1 character remaining
                        return false;
                    }
                }
            }
        }
        return true;
    }
}

