/**
 * Core logic for solving the palindrome construction problem.
 */
class PalindromeSolver {
    private final FastReader reader;

    public PalindromeSolver(FastReader reader) {
        this.reader = reader;
    }

    /**
     * Solves a single test case.
     * @param out PrintWriter for efficient output.
     */
    public void solve(PrintWriter out) {
        int targetZeros = reader.nextInt();
        int targetOnes = reader.nextInt();
        char[] characters = reader.next().toCharArray();
        int n = characters.length;

        // Basic validation
        if (targetZeros + targetOnes != n) {
            out.println("-1");
            return;
        }

        // Step 1: Handle symmetry for existing characters
        for (int i = 0; i < n / 2; i++) {
            int left = i;
            int right = n - 1 - i;

            if (characters[left] != '?' && characters[right] != '?') {
                if (characters[left] != characters[right]) {
                    out.println("-1");
                    return;
                }
            } else if (characters[left] == '?' && characters[right] != '?') {
                characters[left] = characters[right];
            } else if (characters[right] == '?' && characters[left] != '?') {
                characters[right] = characters[left];
            }
        }

        // Step 2: Count current distribution
        int currentZeros = 0;
        int currentOnes = 0;
        for (char c : characters) {
            if (c == '0') currentZeros++;
            else if (c == '1') currentOnes++;
        }

        // Step 3: Check if current characters already exceed targets
        if (currentZeros > targetZeros || currentOnes > targetOnes) {
            out.println("-1");
            return;
        }

        // Step 4: Fill remaining '?' based on target requirements
        int remainingZeros = targetZeros - currentZeros;
        int remainingOnes = targetOnes - currentOnes;

        for (int i = 0; i <= (n - 1) / 2; i++) {
            int left = i;
            int right = n - 1 - i;

            if (characters[left] == '?') {
                if (left == right) { // Middle element in odd length
                    if (remainingZeros > 0) {
                        characters[left] = '0';
                        remainingZeros--;
                    } else if (remainingOnes > 0) {
                        characters[left] = '1';
                        remainingOnes--;
                    } else {
                        out.println("-1");
                        return;
                    }
                } else { // A pair of elements
                    if (remainingZeros >= 2) {
                        characters[left] = characters[right] = '0';
                        remainingZeros -= 2;
                    } else if (remainingOnes >= 2) {
                        characters[left] = characters[right] = '1';
                        remainingOnes -= 2;
                    } else {
                        out.println("-1");
                        return;
                    }
                }
            }
        }

        // Step 5: Final validation
        if (isPalindrome(characters) && remainingZeros == 0 && remainingOnes == 0) {
            out.println(new String(characters));
        } else {
            out.println("-1");
        }
    }

    private boolean isPalindrome(char[] chars) {
        int l = 0;
        int r = chars.length - 1;
        while (l < r) {
            if (chars[l] != chars[r]) return false;
            l++;
            r--;
        }
        return true;
    }
}

/**
 * Utility class for Mathematical operations.
 */
class MathUtils {
    public static final int MOD = 1_000_000_007;

    public static long factorial(int n) {
        long fact = 1L;
        for (int i = 2; i <= n; i++) fact = (fact * i) % MOD;
        return fact;
    }

    public static int nCr(int n, int r) {
        if (r > n) return 0;
        if (r == 0 || r == n) return 1;

        long[] inv = new long[r + 1];
        inv[1] = 1;
        for (int i = 2; i <= r; i++) {
            inv[i] = MOD - (long) (MOD / i) * inv[(int) (MOD % i)] % MOD;
        }

        long ans = 1;
        for (int i = 2; i <= r; i++) {
            ans = (ans * inv[i]) % MOD;
        }
        for (int i = n; i >= (n - r + 1); i--) {
            ans = (ans * i) % MOD;
        }
        return (int) ans;
    }

    public static long findFirstFactor(int n) {
        for (long i = 2; i * i <= n; i++) {
            if (n % i == 0) return i;
        }
        return -1;
    }
}

/**
 * Utility class for Array manipulations.
 */
class ArrayUtils {
    public static void sort(int[] arr, boolean isAscending) {
        Integer[] boxed = Arrays.stream(arr).boxed().toArray(Integer[]::new);
        Arrays.sort(boxed, isAscending ? Comparator.naturalOrder() : Comparator.reverseOrder());
        for (int i = 0; i < arr.length; i++) arr[i] = boxed[i];
    }

    public static void reverse(int[] arr) {
        int left = 0, right = arr.length - 1;
        while (left < right) {
            int temp = arr[left];
            arr[left++] = arr[right];
            arr[right--] = temp;
        }
    }
}

