/**
 * A solution to find a palindrome string of a given length containing
 * a specific number of '0's and '1's, matching a given template.
 */
public class C1512 {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int testCases = reader.nextInt();
        while (testCases-- > 0) {
