            int onesRequired = reader.nextInt();
            String template = reader.next();

            String result = solve(zerosRequired, onesRequired, template);
            out.println(result);
        }
        out.flush();
        out.close();
    }

    /**
     * Core logic to solve the palindrome requirements.
     * 
     * @param zerosRequired Number of '0's needed in the final string.
     * @param onesRequired  Number of '1's needed in the final string.
     * @param template      The initial string containing '0', '1', or '?'.
     * @return The valid palindrome string, or "-1" if no solution exists.
     */
    private static String solve(int zerosRequired, int onesRequired, String template) {
        int n = zerosRequired + onesRequired;
        char[] sequence = template.toCharArray();

        // Step 1: Enforce the palindrome property using existing fixed values
        for (int i = 0; i < n / 2; i++) {
            int mirrorIndex = n - 1 - i;

            if (sequence[i] != '?' && sequence[mirrorIndex] != '?') {
                if (sequence[i] != sequence[mirrorIndex]) {
                    return "-1"; // Conflict in template
                }
            } else if (sequence[i] != '?') {
                sequence[mirrorIndex] = sequence[i];
            } else if (sequence[mirrorIndex] != '?') {
                sequence[i] = sequence[mirrorIndex];
            }
        }

        // Step 2: Count current fixed characters
        int currentZeros = 0;
        int currentOnes = 0;
        for (char c : sequence) {
            if (c == '0') currentZeros++;
            else if (c == '1') currentOnes++;
        }

        // If fixed characters already exceed requirements, it's impossible
        if (currentZeros > zerosRequired || currentOnes > onesRequired) {
            return "-1";
        }

        int remainingZeros = zerosRequired - currentZeros;
        int remainingOnes = onesRequired - currentOnes;

        // Step 3: Fill in the remaining '?' pairs and single middle element
        for (int i = 0; i <= n / 2; i++) {
            int mirrorIndex = n - 1 - i;

            // Only process if we are at a '?'
            if (sequence[i] == '?') {
                if (i == mirrorIndex) {
                    // Middle element in an odd-length string
                    if (remainingZeros > 0) {
                        sequence[i] = '0';
                        remainingZeros--;
                    } else if (remainingOnes > 0) {
                        sequence[i] = '1';
                        remainingOnes--;
                    } else {
                        return "-1";
                    }
                } else {
                    // A pair of indices (i, mirrorIndex) that are both '?'
                    if (remainingZeros >= 2) {
                        sequence[i] = '0';
                        sequence[mirrorIndex] = '0';
                        remainingZeros -= 2;
                    } else if (remainingOnes >= 2) {
                        sequence[i] = '1';
                        sequence[mirrorIndex] = '1';
                        remainingOnes -= 2;
                    } else {
                        // Cannot fill a pair with only 1 remaining character
                        return "-1";
                    }
                }
            }
        }

        // Final validation
        if (remainingZeros != 0 || remainingOnes != 0) {
            return "-1";
        }

        // Final check for palindrome (redundant but safe) and character counts
        for (int i = 0; i < n / 2; i++) {
            if (sequence[i] != sequence[n - 1 - i]) return "-1";
        }

        return new String(sequence);
    }

