    /**
     * Attempts to construct a valid palindrome based on target counts.
     *
     * @param targetZero The required number of '0' characters.
     * @param targetOne  The required number of '1' characters.
     * @param s          The input string containing '0', '1', or '?'.
     * @return The resulting palindrome string, or "-1" if impossible.
     */
    public static String solve(int targetZero, int targetOne, String s) {
        int n = s.length();

        // Basic constraint: total characters must match the sum of target counts
        if (n != targetZero + targetOne) {
            return "-1";
        }

        char[] resultChars = s.toCharArray();
        int currentZeroCount = 0;
        int currentOneCount = 0;

        // Step 1: Handle fixed constraints and mirror non-question marks
        // We iterate to the middle of the string to handle pairs and the middle element.
        for (int i = 0; i <= (n - 1) / 2; i++) {
            int j = n - 1 - i;

            if (i == j) { // Middle element in an odd-length string
                if (resultChars[i] == '0') {
                    currentZeroCount++;
                } else if (resultChars[i] == '1') {
                    currentOneCount++;
                }
            } else {
                if (resultChars[i] != '?' && resultChars[j] != '?') {
                    // Both are fixed: must be identical
                    if (resultChars[i] != resultChars[j]) {
                        return "-1";
                    }
                    if (resultChars[i] == '0') {
                        currentZeroCount += 2;
                    } else {
                        currentOneCount += 2;
                    }
                } else if (resultChars[i] != '?' && resultChars[j] == '?') {
                    // Mirror the fixed character to the question mark
                    resultChars[j] = resultChars[i];
                    if (resultChars[i] == '0') {
                        currentZeroCount++;
                    } else {
                        currentOneCount++;
                    }
                } else if (resultChars[i] == '?' && resultChars[j] != '?') {
                    // Mirror the fixed character to the question mark
                    resultChars[i] = resultChars[j];
                    if (resultChars[j] == '0') {
                        currentZeroCount++;
                    } else {
                        currentOneCount++;
                    }
                }
            }
        }

        // Check if the fixed characters already exceed our target counts
        if (currentZeroCount > targetZero || currentOneCount > targetOne) {
            return "-1";
        }

        // Step 2: Identify remaining "question mark" pairs and potential middle '?'
        int questionMarkPairs = 0;
        boolean middleIsQuestion = false;

        for (int i = 0; i <= (n - 1) / 2; i++) {
            int j = n - 1 - i;
            if (i == j) {
                if (resultChars[i] == '?') {
                    middleIsQuestion = true;
                }
            } else {
                if (resultChars[i] == '?' && resultChars[j] == '?') {
                    questionMarkPairs++;
                }
            }
        }

        int remainingZeroNeeded = targetZero - currentZeroCount;
        int remainingOneNeeded = targetOne - currentOneCount;

        // Step 3: Solve for the remaining counts using math
        // We must satisfy: 2 * pairsZero + (1 if middle is '0') == remainingZeroNeeded
        // And: 2 * pairsOne + (1 if middle is '1') == remainingOneNeeded

        if (middleIsQuestion) {
            // Case A: Try assigning '0' to the middle element
            if (remainingZeroNeeded >= 1 && (remainingZeroNeeded - 1) % 2 == 0 && 
                remainingOneNeeded % 2 == 0 && 
                ((remainingZeroNeeded - 1 + remainingOneNeeded) / 2 == questionMarkPairs)) {

                resultChars[n / 2] = '0';
                return fillQuestionMarks(resultChars, remainingZeroNeeded - 1, remainingOneNeeded);
            }

            // Case B: Try assigning '1' to the middle element
            if (remainingOneNeeded >= 1 && (remainingOneNeeded - 1) % 2 == 0 && 
                remainingZeroNeeded % 2 == 0 && 
                ((remainingZeroNeeded + remainingOneNeeded - 1) / 2 == questionMarkPairs)) {

                resultChars[n / 2] = '1';
                return fillQuestionMarks(resultChars, remainingZeroNeeded, remainingOneNeeded - 1);
            }
        } else {
            // No middle question mark: both remaining counts must be even
            if (remainingZeroNeeded % 2 == 0 && remainingOneNeeded % 2 == 0 && 
                (remainingZeroNeeded + remainingOneNeeded) / 2 == questionMarkPairs) {
                return fillQuestionMarks(resultChars, remainingZeroNeeded, remainingOneNeeded);
            }
        }

        return "-1";
    }

    /**
     * Fills the remaining '?' pairs in the character array.
     *
     * @param chars           The array to modify.
     * @param remainingZeros  How many '0's are left to place (must be even).
     * @param remainingOnes   How many '1's are left to place (must be even).
     * @return The completed palindrome string.
     */
    private static String fillQuestionMarks(char[] chars, int remainingZeros, int remainingOnes) {
        int pairsOfZeros = remainingZeros / 2;
        int n = chars.length;

        for (int i = 0; i < n / 2; i++) {
            int j = n - 1 - i;
            if (chars[i] == '?') {
                if (pairsOfZeros > 0) {
                    chars[i] = chars[j] = '0';
                    pairsOfZeros--;
                } else {
                    chars[i] = chars[j] = '1';
                }
            }
        }
        return new String(chars);
    }
}

