/**
 * A utility to solve the palindrome construction problem.
 * Given a pattern of '0', '1', and '?', and a budget of 0s and 1s,
 * it attempts to form a palindrome using the exact budget.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        int testCases = reader.nextInt();
        StringBuilder outputBuilder = new StringBuilder();

        PalindromeSolver solver = new PalindromeSolver();

        while (testCases-- > 0) {
            int targetZeros = reader.nextInt();
            int targetOnes = reader.nextInt();
            String pattern = reader.next();

            String result = solver.solve(targetZeros, targetOnes, pattern);
            outputBuilder.append(result).append("\n");
        }

        System.out.print(outputBuilder);
    }

    /**
     * Handles the core logic of constructing the palindrome.
     */
    static class PalindromeSolver {

        /**
         * Attempts to construct a palindrome based on the provided constraints.
         * 
         * @param targetZeros Number of '0's available.
         * @param targetOnes  Number of '1's available.
         * @param pattern     The input string containing '0', '1', or '?'.
         * @return The constructed palindrome string, or "-1" if impossible.
         */
        public String solve(int targetZeros, int targetOnes, String pattern) {
            int n = pattern.length();
            char[] workingChars = pattern.toCharArray();

            // Use an array to track remaining budget for mutability within methods
            int[] remaining = {targetZeros, targetOnes};

            // 1. Deduct existing characters from the budget
            if (!deductExisting(workingChars, remaining)) {
                return "-1";
            }

            // 2. Match '?' with existing characters at symmetric positions
            matchSymmetricCharacters(workingChars, remaining);

            // 3. Fill remaining '?' pairs greedily
            fillRemainingPairs(workingChars, remaining);

            // 4. Fill the middle character for odd-length strings
            fillMiddleCharacter(workingChars, remaining, n);

            // 5. Final Validation
            if (isValidSolution(workingChars, remaining)) {
                return new String(workingChars);
            } else {
                return "-1";
            }
        }

        private boolean deductExisting(char[] arr, int[] remaining) {
            for (char c : arr) {
                if (c == '0') remaining[0]--;
                else if (c == '1') remaining[1]--;
            }
            return true; 
        }

        private void matchSymmetricCharacters(char[] arr, int[] remaining) {
            int n = arr.length;
            for (int i = 0, j = n - 1; i < j; ++i, --j) {
                if (arr[i] == '?' && arr[j] != '?') {
                    arr[i] = arr[j];
                    updateBudget(arr[i], remaining);
                } else if (arr[j] == '?' && arr[i] != '?') {
                    arr[j] = arr[i];
                    updateBudget(arr[j], remaining);
                }
            }
        }

        private void fillRemainingPairs(char[] arr, int[] remaining) {
            int n = arr.length;
            for (int i = 0, j = n - 1; i < j; ++i, --j) {
                if (arr[i] == '?' && arr[j] == '?') {
                    // Greedy approach: use the character that has a higher remaining count
                    if (remaining[0] > remaining[1]) {
                        arr[i] = arr[j] = '0';
                        remaining[0] -= 2;
                    } else {
                        arr[i] = arr[j] = '1';
                        remaining[1] -= 2;
                    }
                }
            }
        }

        private void fillMiddleCharacter(char[] arr, int[] remaining, int n) {
            if (n % 2 == 1) {
                int mid = n / 2;
                if (arr[mid] == '?') {
                    if (remaining[0] > remaining[1]) {
                        arr[mid] = '0';
                        remaining[0]--;
                    } else {
                        arr[mid] = '1';
                        remaining[1]--;
                    }
                }
            }
        }

        private void updateBudget(char c, int[] remaining) {
            if (c == '0') remaining[0]--;
            else if (c == '1') remaining[1]--;
        }

        private boolean isValidSolution(char[] arr, int[] remaining) {
            return remaining[0] == 0 && 
                   remaining[1] == 0 && 
                   isPalindrome(arr);
        }

        private boolean isPalindrome(char[] arr) {
            int i = 0, j = arr.length - 1;
            while (i < j) {
                if (arr[i] != arr[j]) return false;
                i++;
                j--;
            }
            return true;
        }
    }

    /**
     * Fast I/O reader for competitive programming environments.
     */
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

