/**
 * A solution to construct a palindrome of a given length using a specific 
 * number of '0's and '1's, matching a provided pattern containing '?' wildcards.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int testCases = reader.nextInt();
        PalindromeSolver solver = new PalindromeSolver();

        while (testCases-- > 0) {
            int targetZero = reader.nextInt();
            int targetOne = reader.nextInt();
            String pattern = reader.next();

            String result = solver.solve(targetZero, targetOne, pattern);
            out.println(result);
        }
        out.flush();
    }

    /**
     * Logic engine for solving the palindrome construction problem.
     */
    static class PalindromeSolver {

        /**
         * Attempts to construct a palindrome matching the pattern and counts.
         * 
         * @param targetZero Total number of '0' characters required.
         * @param targetOne  Total number of '1' characters required.
         * @param pattern    The input pattern containing '0', '1', or '?'.
         * @return The constructed palindrome string, or "-1" if impossible.
         */
        public String solve(int targetZero, int targetOne, String pattern) {
            int n = pattern.length();

            // Basic feasibility check: sum of counts must equal string length
            if (targetZero + targetOne != n) {
                return "-1";
            }

            char[] chars = pattern.toCharArray();

            // Step 1: Enforce palindrome symmetry based on non-wildcard characters
            if (!applySymmetry(chars, n)) {
                return "-1";
            }

            // Step 2: Calculate how many '0's and '1's are already placed
            int currentZero = 0;
            int currentOne = 0;
            for (char c : chars) {
                if (c == '0') currentZero++;
                else if (c == '1') currentOne++;
            }

            int remainingZero = targetZero - currentZero;
            int remainingOne = targetOne - currentOne;

            // If existing characters already exceed target counts
            if (remainingZero < 0 || remainingOne < 0) {
                return "-1";
            }

            // Step 3: Fill remaining '?' pairs symmetrically
            for (int i = 0; i < n / 2; i++) {
                int j = n - 1 - i;
                if (chars[i] == '?') {
                    if (remainingZero >= 2) {
                        chars[i] = chars[j] = '0';
                        remainingZero -= 2;
                    } else if (remainingOne >= 2) {
                        chars[i] = chars[j] = '1';
                        remainingOne -= 2;
                    } else {
                        return "-1";
                    }
                }
            }

            // Step 4: Handle the middle character if the length is odd
            if (n % 2 != 0) {
                int mid = n / 2;
                if (chars[mid] == '?') {
                    if (remainingZero >= 1) {
                        chars[mid] = '0';
                        remainingZero -= 1;
                    } else if (remainingOne >= 1) {
                        chars[mid] = '1';
                        remainingOne -= 1;
                    } else {
                        return "-1";
                    }
                }
            }

            // Step 5: Final validation - ensure all budget was used exactly
            if (remainingZero == 0 && remainingOne == 0) {
                return new String(chars);
            } else {
                return "-1";
            }
        }

        /**
         * Fills '?' at symmetric positions if the opposite position is a digit.
         * Returns false if existing digits at symmetric positions do not match.
         */
        private boolean applySymmetry(char[] chars, int n) {
            for (int i = 0; i < n / 2; i++) {
                int j = n - 1 - i;
                if (chars[i] != '?' && chars[j] != '?') {
                    if (chars[i] != chars[j]) return false;
                } else if (chars[i] != '?' && chars[j] == '?') {
                    chars[j] = chars[i];
                } else if (chars[i] == '?' && chars[j] != '?') {
                    chars[i] = chars[j];
                }
            }
            return true;
        }
    }

    /**
     * Optimized reader for fast I/O operations.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }
    }
}

import java.util.*;
