/**
 * A utility class to solve the palindrome construction problem.
 */
class PalindromeSolver {

    private static final char ZERO = '0';
    private static final char ONE = '1';
    private static final char QUESTION = '?';

    /**
     * Attempts to construct a palindrome using the specified number of 0s and 1s.
     * 
     * @param targetZeroCount The required total number of '0' characters.
     * @param targetOneCount  The required total number of '1' characters.
     * @param sequence        The input string containing '0', '1', and '?'.
     * @return A valid palindrome string, or "-1" if impossible.
     */
    public String solve(int targetZeroCount, int targetOneCount, String sequence) {
        int length = sequence.length();

        // Basic validation: target counts must sum to the total length
        if (targetZeroCount + targetOneCount != length) {
            return "-1";
        }

        char[] result = sequence.toCharArray();

        // Step 1: Enforce symmetry for existing non-question characters.
        // If one side of a pair is fixed, the other must match.
        if (!enforceSymmetry(result, length)) {
            return "-1";
        }

        // Step 2: Calculate how many 0s and 1s are still needed.
        int currentZeroCount = 0;
        int currentOneCount = 0;
        for (char c : result) {
            if (c == ZERO) currentZeroCount++;
            else if (c == ONE) currentOneCount++;
        }

        // If we already exceeded the target, it's impossible.
        if (currentZeroCount > targetZeroCount || currentOneCount > targetOneCount) {
            return "-1";
        }

        int neededZero = targetZeroCount - currentZeroCount;
        int neededOne = targetOneCount - currentOneCount;

        // Step 3: Fill the remaining '?' characters greedily.
        if (!fillRemainingQuestions(result, length, neededZero, neededOne)) {
            return "-1";
        }

        // Final check to ensure all requirements are met exactly.
        return (neededZero == 0 && neededOne == 0) ? new String(result) : "-1";
    }

    private boolean enforceSymmetry(char[] arr, int n) {
        for (int i = 0; i < n / 2; i++) {
            int j = n - 1 - i;
            if (arr[i] != QUESTION && arr[j] != QUESTION) {
                if (arr[i] != arr[j]) return false;
            } else if (arr[i] != QUESTION) {
                arr[j] = arr[i];
            } else if (arr[j] != QUESTION) {
                arr[i] = arr[j];
            }
        }
        return true;
    }

    private boolean fillRemainingQuestions(char[] arr, int n, int neededZero, int neededOne) {
        // We iterate through the first half (including middle if odd) to fill pairs and center.
        for (int i = 0; i <= (n - 1) / 2; i++) {
            int j = n - 1 - i;

            if (arr[i] == QUESTION) {
                if (i == j) { // Middle element in an odd-length string
                    if (neededZero > 0) {
                        arr[i] = ZERO;
                        neededZero--;
                    } else if (neededOne > 0) {
                        arr[i] = ONE;
                        neededOne--;
                    } else {
                        return false;
                    }
                } else { // A symmetric pair of '?'
                    if (neededZero >= 2) {
                        arr[i] = arr[j] = ZERO;
                        neededZero -= 2;
                    } else if (neededOne >= 2) {
                        arr[i] = arr[j] = ONE;
                        neededOne -= 2;
                    } else {
                        // Cannot satisfy a pair requirement with only 1 character left
                        return false;
                    }
                }
            }
        }
        return true;
    }
}

