class PalindromeProblemSolver {

    private static final String IMPOSSIBLE = "-1";

    /**
     * Attempts to construct a palindrome string based on the provided constraints.
     * 
     * @param targetZeros Total count of '0's required in the final string.
     * @param targetOnes  Total count of '1's required in the final string.
     * @param s           The input string containing '0', '1', or '?'.
     * @return The constructed palindrome or "-1" if impossible.
     */
    public String solve(int targetZeros, int targetOnes, String s) {
        char[] chars = s.toCharArray();
        int n = chars.length;

        // 1. Enforce symmetry based on existing digits
        if (!enforceSymmetry(chars, n)) {
            return IMPOSSIBLE;
        }

        // 2. Count current digits and calculate remaining budget
        int currentZeros = countOccurrences(chars, '0');
        int currentOnes = countOccurrences(chars, '1');

        int remZeros = targetZeros - currentZeros;
        int remOnes = targetOnes - currentOnes;

        // If we've already exceeded the budget
        if (remZeros < 0 || remOnes < 0) {
            return IMPOSSIBLE;
        }

        // 3. Handle the middle character for odd-length strings to ensure parity
        if (n % 2 != 0) {
            int mid = n / 2;
            if (chars[mid] == '?') {
                if (remZeros % 2 != 0 && remOnes % 2 == 0) {
                    chars[mid] = '0';
                    remZeros--;
                } else if (remOnes % 2 != 0 && remZeros % 2 == 0) {
                    chars[mid] = '1';
                    remOnes--;
                } else {
                    // If neither parity works, it's impossible
                    return IMPOSSIBLE;
                }
            } else {
                // If middle is already a digit, the remaining budget for pairs must be even
                if (remZeros % 2 != 0 || remOnes % 2 != 0) {
                    return IMPOSSIBLE;
                }
            }
        } else {
            // For even length, all remaining budget must be even to form pairs
            if (remZeros % 2 != 0 || remOnes % 2 != 0) {
                return IMPOSSIBLE;
            }
        }

        // 4. Fill the remaining symmetric '?' pairs
        if (!fillRemainingPairs(chars, n, remZeros, remOnes)) {
            return IMPOSSIBLE;
        }

        // Final verification that budget is exactly exhausted
        if (remZeros != 0 && remOnes != 0) {
            // This part is handled by the logic in fillRemainingPairs, 
            // but we check counts for safety.
        }

        return new String(chars);
    }

    /**
     * Synchronizes '?' with their symmetric partners.
     * Returns false if there is a conflict (e.g., '0' at index i and '1' at index N-1-i).
     */
    private boolean enforceSymmetry(char[] chars, int n) {
        for (int i = 0; i < n / 2; i++) {
            int partnerIdx = n - 1 - i;
            char left = chars[i];
            char right = chars[partnerIdx];

            if (left != '?' && right != '?') {
                if (left != right) return false;
            } else if (left != '?' && right == '?') {
                chars[partnerIdx] = left;
            } else if (left == '?' && right != '?') {
                chars[i] = right;
            }
        }
        return true;
    }

    /**
     * Fills remaining '?' pairs using the remaining budget.
     */
    private boolean fillRemainingPairs(char[] chars, int n, int remZeros, int remOnes) {
        for (int i = 0; i < n / 2; i++) {
            int partnerIdx = n - 1 - i;
            if (chars[i] == '?') {
                if (remZeros >= 2) {
                    chars[i] = chars[partnerIdx] = '0';
                    remZeros -= 2;
                } else if (remOnes >= 2) {
                    chars[i] = chars[partnerIdx] = '1';
                    remOnes -= 2;
                } else {
                    return false;
                }
            }
        }
        // Final check to ensure the entire budget was used
        return remZeros == 0 && remOnes == 0;
    }

    private int countOccurrences(char[] chars, char target) {
        int count = 0;
        for (char c : chars) {
            if (c == target) count++;
        }
        return count;
    }
}

