        for (char c : sequence) {
            if (c == '0') currentZeros++;
            else if (c == '1') currentOnes++;
        }

        // Phase 3: Fill remaining '?' pairs greedily
        for (int i = 0; i < n / 2; i++) {
            int j = n - 1 - i;
            if (sequence[i] == '?') {
                // Both sequence[i] and sequence[j] must be '?' due to Phase 1
                if (currentZeros + 2 <= targetZeros) {
                    sequence[i] = sequence[j] = '0';
                    currentZeros += 2;
                } else {
                    sequence[i] = sequence[j] = '1';
                    currentOnes += 2;
                }
            }
        }

        // Phase 4: Fill the middle element if the length is odd
        if (n % 2 == 1) {
            int mid = n / 2;
            if (sequence[mid] == '?') {
                if (currentZeros < targetZeros) {
                    sequence[mid] = '0';
                    currentZeros++;
                } else {
                    sequence[mid] = '1';
                    currentOnes++;
                }
            }
        }

        // Phase 5: Final Validation
        if (currentZeros == targetZeros && currentOnes == targetOnes) {
            return new String(sequence);
        } else {
            return "-1";
        }
    }

