import java.util.Scanner;

/**
 * A utility to solve the problem of constructing a palindrome 
 * using a specific number of '0's and '1's from a template containing '?'.
 */
class PalindromeSolver {

    private static final String IMPOSSIBLE = "-1";

    /**
     * Attempts to construct a palindrome based on the provided constraints.
     *
     * @param targetZeros The exact number of '0' characters required.
     * @param targetOnes  The exact number of '1' characters required.
     * @param template    The string containing '0', '1', and '?'.
     * @return The resulting palindrome string, or "-1" if impossible.
     */
    public String solve(int targetZeros, int targetOnes, String template) {
        char[] word = template.toCharArray();
        int n = word.length;

        // 1. Symmetrically fill '?' where the mirror character is known
        fillKnownSymmetry(word, n);

        // 2. Count existing '0's and '1's and validate palindrome property
        if (!isPotentiallyPalindrome(word) || isCountExceeded(word, targetZeros, targetOnes)) {
            return IMPOSSIBLE;
        }

        int remainingZeros = targetZeros - countOccurrences(word, '0');
        int remainingOnes = targetOnes - countOccurrences(word, '1');

        // 3. Fill remaining '?' pairs or single middle elements
        if (!fillRemainingGaps(word, n, remainingZeros, remainingOnes)) {
            return IMPOSSIBLE;
        }

        // 4. Final validation: Ensure all required counts were used exactly
        return (remainingZeros == 0 && remainingOnes == 0) ? new String(word) : IMPOSSIBLE;
    }

    private void fillKnownSymmetry(char[] word, int n) {
        for (int i = 0; i < n / 2; i++) {
            int j = n - 1 - i;
            if (word[i] != '?' && word[j] == '?') {
                word[j] = word[i];
            } else if (word[i] == '?' && word[j] != '?') {
                word[i] = word[j];
            }
        }
    }

    private boolean isPotentiallyPalindrome(char[] word) {
        for (int i = 0, j = word.length - 1; i < j; i++, j--) {
            if (word[i] != '?' && word[j] != '?' && word[i] != word[j]) {
                return false;
            }
        }
        return true;
    }

    private boolean isCountExceeded(char[] word, int targetZeros, int targetOnes) {
        int currentZeros = 0;
        int currentOnes = 0;
        for (char c : word) {
            if (c == '0') currentZeros++;
            else if (c == '1') currentOnes++;
        }
        return currentZeros > targetZeros || currentOnes > targetOnes;
    }

    private int countOccurrences(char[] word, char target) {
        int count = 0;
        for (char c : word) {
            if (c == target) count++;
        }
        return count;
    }

    private boolean fillRemainingGaps(char[] word, int n, int rem0, int rem1) {
        for (int i = 0; i <= (n - 1) / 2; i++) {
            int j = n - 1 - i;

            if (word[i] == '?') {
                if (i == j) {
                    // Handle middle element for odd-length strings
                    if (rem0 > 0) {
                        word[i] = '0';
                        rem0--;
                    } else if (rem1 > 0) {
                        word[i] = '1';
                        rem1--;
                    } else {
                        return false;
                    }
                } else {
                    // Handle symmetric pairs
                    if (rem0 >= 2) {
                        word[i] = word[j] = '0';
                        rem0 -= 2;
                    } else if (rem1 >= 2) {
                        word[i] = word[j] = '1';
                        rem1 -= 2;
                    } else {
                        return false;
                    }
                }
            }
        }
        return true;
    }
}

