    /**
     * Core logic to construct the palindrome.
     * 
     * @param n Target number of zeros.
     * @param m Target number of ones.
     * @param s  The template string containing '0', '1', or '?'.
     * @return The constructed palindrome or "-1" if impossible.
     */
    public static String solve(int n, int m, String s) {
        char[] arr = s.toCharArray();
        int len = arr.length;

        // Pass 1: Enforce symmetry requirements
        for (int i = 0; i < len / 2; i++) {
            int j = len - 1 - i;
            if (arr[i] != '?' && arr[j] != '?') {
                if (arr[i] != arr[j]) return "-1"; // Symmetry broken by fixed digits
            } else if (arr[i] != '?') {
                arr[j] = arr[i];
            } else if (arr[j] != '?') {
                arr[i] = arr[j];
            }
        }

        // Pass 2: Count current digits and identify remaining requirements
        int currentZeros = 0;
        int currentOnes = 0;
        int questionMarks = 0;

        for (char c : arr) {
            if (c == '0') currentZeros++;
            else if (c == '1') currentOnes++;
            else questionMarks++;
        }

        int remZeros = n - currentZeros;
        int remOnes = m - currentOnes;

        // Validation: Check if requirements are mathematically possible
        if (remZeros < 0 || remOnes < 0 || (remZeros + remOnes != questionMarks)) {
            return "-1";
        }

        // Pass 3: Fill remaining '?' using greedy approach
        for (int i = 0; i <= len / 2; i++) {
            int j = len - 1 - i;

            // Case: Middle element of an odd-length string
            if (i == j) {
                if (arr[i] == '?') {
                    if (remZeros % 2 != 0) {
                        arr[i] = '0';
                        remZeros--;
                    } else if (remOnes % 2 != 0) {
                        arr[i] = '1';
                        remOnes--;
                    } else {
                        return "-1"; // Middle '?' must satisfy an odd requirement
                    }
                }
            } 
            // Case: Standard pairs
            else if (arr[i] == '?') {
                if (remZeros >= 2) {
                    arr[i] = arr[j] = '0';
                    remZeros -= 2;
                } else if (remOnes >= 2) {
                    arr[i] = arr[j] = '1';
                    remOnes -= 2;
                } else {
                    return "-1";
                }
            }
        }

        // Final Verification
        if (remZeros == 0 && remOnes == 0) {
            return new String(arr);
        } else {
            return "-1";
        }
    }

