    static class PalindromeSolver {

        /**
         * Attempts to construct a palindrome based on target counts of 0s and 1s.
         * 
         * @param targetZeros The required number of '0' characters.
         * @param targetOnes  The required number of '1' characters.
         * @param pattern     The input string containing '0', '1', or '?'.
         * @return The constructed palindrome string, or "-1" if impossible.
         */
        public static String solve(int targetZeros, int targetOnes, String pattern) {
            int n = pattern.length();
            char[] chars = pattern.toCharArray();

            // Phase 1: Enforce Symmetry
            // If one side of the palindrome is fixed, the other must match it.
            for (int i = 0; i < n / 2; i++) {
                int j = n - 1 - i;
                if (chars[i] != '?' && chars[j] != '?') {
                    if (chars[i] != chars[j]) {
                        return "-1";
                    }
                } else if (chars[i] != '?') {
                    chars[j] = chars[i];
                } else if (chars[j] != '?') {
                    chars[i] = chars[j];
                }
            }

            // Phase 2: Calculate current counts and remaining requirements
            int currentZeros = countOccurrences(chars, '0');
            int currentOnes = countOccurrences(chars, '1');

            int remZeros = targetZeros - currentZeros;
            int remOnes = targetOnes - currentOnes;

            if (remZeros < 0 || remOnes < 0) {
                return "-1";
            }

            // Phase 3: Handle the middle element (for odd-length strings)
            if (n % 2 == 1) {
                int mid = n / 2;
                if (chars[mid] == '?') {
                    // The middle element must resolve the parity of the remaining counts
                    if (remZeros % 2 != 0 && remZeros > 0) {
                        chars[mid] = '0';
                        remZeros--;
                    } else if (remOnes % 2 != 0 && remOnes > 0) {
                        chars[mid] = '1';
                        remOnes--;
                    } else {
                        // If neither can resolve parity, it's impossible
                        return "-1";
                    }
                }
            }

            // Phase 4: Fill remaining '?' pairs
            for (int i = 0; i < n / 2; i++) {
                int j = n - 1 - i;
                if (chars[i] == '?') {
                    if (remZeros >= 2) {
                        chars[i] = chars[j] = '0';
                        remZeros -= 2;
                    } else if (remOnes >= 2) {
                        chars[i] = chars[j] = '1';
                        remOnes -= 2;
                    } else {
                        // Cannot fill a pair with only 1 character remaining
                        return "-1";
                    }
                }
            }

            // Phase 5: Final Validation
            if (validate(chars, targetZeros, targetOnes)) {
                return new String(chars);
            } else {
                return "-1";
            }
        }

        private static int countOccurrences(char[] chars, char target) {
            int count = 0;
            for (char c : chars) {
                if (c == target) count++;
            }
            return count;
        }

        private static boolean validate(char[] chars, int targetZeros, int targetOnes) {
            int c0 = 0, c1 = 0;
            for (char c : chars) {
                if (c == '0') c0++;
                else if (c == '1') c1++;
                else return false; // Should not contain '?'
            }
            return c0 == targetZeros && c1 == targetOnes;
        }
    }

