import java.io.*;
import java.util.StringTokenizer;

/**
 * Solves the problem of constructing a palindrome using a specific number of 0s and 1s.
 */
public class ABPalindrome {

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        int testCases = sc.nextInt();
        while (testCases-- > 0) {
            int targetZeros = sc.nextInt();
            int targetOnes = sc.nextInt();
            String s = sc.next();

            out.println(solve(targetZeros, targetOnes, s));
        }
        out.close();
    }

    /**
     * Orchestrates the logic to find a valid palindrome.
     */
    private static String solve(int targetZeros, int targetOnes, String s) {
        PalindromeTask task = new PalindromeTask(targetZeros, targetOnes, s);
        return task.execute();
    }

    /**
     * Encapsulates the state and logic for a single palindrome construction task.
     */
    private static class PalindromeTask {
        private final int targetZeros;
        private final int targetOnes;
        private final char[] chars;
        private int remainingZeros;
        private int remainingOnes;
        private final int n;

        public PalindromeTask(int targetZeros, int targetOnes, String s) {
            this.targetZeros = targetZeros;
            this.targetOnes = targetOnes;
            this.chars = s.toCharArray();
            this.n = s.length();
            calculateRemainingCounts();
        }

        private void calculateRemainingCounts() {
            int currentZeros = 0;
            int currentOnes = 0;
            for (char c : chars) {
                if (c == '0') currentZeros++;
                else if (c == '1') currentOnes++;
            }
            this.remainingZeros = targetZeros - currentZeros;
            this.remainingOnes = targetOnes - currentOnes;
        }

        public String execute() {
            // Basic feasibility check
            if (remainingZeros < 0 || remainingOnes < 0) {
                return "-1";
            }

            // Phase 1: Fill '?' where the symmetric counterpart is a fixed character
            if (!fillSymmetricFixedPositions()) {
                return "-1";
            }

            // Phase 2: Fill remaining '?' where both counterparts are '?'
            if (!fillDoubleQuestions()) {
                return "-1";
            }

            // Phase 3: Final validation of counts and palindrome property
            if (isValid()) {
                return new String(chars);
            } else {
                return "-1";
            }
        }

        private boolean fillSymmetricFixedPositions() {
            for (int i = 0; i < n / 2; i++) {
                int left = i;
                int right = n - 1 - i;

                char leftChar = chars[left];
                char rightChar = chars[right];

                if (leftChar != '?' && rightChar != '?') {
                    if (leftChar != rightChar) return false;
                } else if (leftChar != '?' && rightChar == '?') {
                    chars[right] = leftChar;
                    updateRemainingCounts(leftChar);
                } else if (leftChar == '?' && rightChar != '?') {
                    chars[left] = rightChar;
                    updateRemainingCounts(rightChar);
                }

                if (remainingZeros < 0 || remainingOnes < 0) return false;
            }
            return true;
        }

        private void updateRemainingCounts(char c) {
            if (c == '0') remainingZeros--;
            else if (c == '1') remainingOnes--;
        }

        private boolean fillDoubleQuestions() {
            for (int i = 0; i < (n + 1) / 2; i++) {
                int left = i;
                int right = n - 1 - i;

                if (chars[left] == '?') {
                    // Middle element in odd-length string
                    if (left == right) {
                        if (remainingZeros > 0) {
                            chars[left] = '0';
                            remainingZeros--;
                        } else if (remainingOnes > 0) {
                            chars[left] = '1';
                            remainingOnes--;
                        } else {
                            return false;
                        }
                    } else {
                        // Symmetric pair of '?'
                        if (remainingZeros >= 2) {
                            chars[left] = chars[right] = '0';
                            remainingZeros -= 2;
                        } else if (remainingOnes >= 2) {
                            chars[left] = chars[right] = '1';
                            remainingOnes -= 2;
                        } else {
                            return false;
                        }
                    }
                }
            }
            return true;
        }

        private boolean isValid() {
            if (remainingZeros != 0 || remainingOnes != 0) {
                return false;
            }
            return isPalindrome(new String(chars));
        }

        private boolean isPalindrome(String s) {
            int left = 0, right = s.length() - 1;
            while (left < right) {
                if (s.charAt(left++) != s.charAt(right--)) return false;
            }
            return true;
        }
    }

    /**
     * High-performance input reader.
     */
    public static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

/**
 * A utility to solve the palindrome construction problem.
 */
class PalindromeSolver {

    private static final char ZERO = '0';
    private static final char ONE = '1';
    private static final char QUESTION_MARK = '?';
    private static final String IMPOSSIBLE = "-1";

    /**
     * Attempts to construct a palindrome using exactly the specified number of 0s and 1s.
     *
     * @param targetZeros The exact number of '0' characters required.
     * @param targetOnes  The exact number of '1' characters required.
     * @param input       The template string containing '0', '1', or '?'.
     * @return The constructed palindrome string, or "-1" if impossible.
     */
    public String solve(int targetZeros, int targetOnes, String input) {
        int length = input.length();
        char[] chars = input.toCharArray();

        // Step 1: Resolve existing character constraints (matching non-'?' partners)
        if (!matchExistingCharacters(chars, length)) {
            return IMPOSSIBLE;
        }

        // Step 2: Count current distribution of characters
        int currentZeros = countOccurrences(chars, ZERO);
        int currentOnes = countOccurrences(chars, ONE);

        // Step 3: Check if existing characters already exceed the budget
        if (currentZeros > targetZeros || currentOnes > targetOnes) {
            return IMPOSSIBLE;
        }

        // Step 4: Fill remaining '?' characters using the remaining budget
        int remainingZeros = targetZeros - currentZeros;
        int remainingOnes = targetOnes - currentOnes;

        if (!fillRemainingQuestions(chars, length, remainingZeros, remainingOnes)) {
            return IMPOSSIBLE;
        }

        return new String(chars);
    }

    /**
     * Ensures that for every pair in the palindrome, if one character is set, 
     * the other is updated to match. If both are set and differ, it's invalid.
     */
    private boolean matchExistingCharacters(char[] chars, int n) {
        for (int i = 0; i < n / 2; i++) {
            int j = n - 1 - i;
            if (chars[i] != QUESTION_MARK && chars[j] != QUESTION_MARK) {
                if (chars[i] != chars[j]) {
                    return false;
                }
            } else if (chars[i] != QUESTION_MARK) {
                chars[j] = chars[i];
            } else if (chars[j] != QUESTION_MARK) {
                chars[i] = chars[j];
            }
        }
        return true;
    }

    /**
     * Fills the '?' slots greedily. A pair of '?' must consume 2 of a character,
     * while a middle '?' (in odd-length strings) consumes 1.
     */
    private boolean fillRemainingQuestions(char[] chars, int n, int remZeros, int remOnes) {
        // Use an array to allow mutable updates to the remaining counts within the method
        int[] counts = {remZeros, remOnes};

        for (int i = 0; i <= n / 2; i++) {
            int j = n - 1 - i;
            if (i > j) break; // Prevent double processing

            if (chars[i] == QUESTION_MARK) {
                if (i == j) {
                    // Case: Middle element of an odd-length string
                    if (counts[0] >= 1) {
                        chars[i] = ZERO;
                        counts[0]--;
                    } else if (counts[1] >= 1) {
                        chars[i] = ONE;
                        counts[1]--;
                    } else {
                        return false;
                    }
                } else {
                    // Case: A pair of symmetric indices
                    if (counts[0] >= 2) {
                        chars[i] = chars[j] = ZERO;
                        counts[0] -= 2;
                    } else if (counts[1] >= 2) {
                        chars[i] = chars[j] = ONE;
                        counts[1] -= 2;
                    } else {
                        return false;
                    }
                }
            }
        }
        // The palindrome is only valid if the entire budget was used exactly
        return counts[0] == 0 && counts[1] == 0;
    }

    private int countOccurrences(char[] chars, char target) {
        int count = 0;
        for (char c : chars) {
            if (c == target) count++;
        }
        return count;
    }
}

