     * @param pattern     The initial string containing '0', '1', or '?'.
     * @return The resulting palindrome string, or "-1" if impossible.
     */
    private static String solve(int targetZeros, int targetOnes, String pattern) {
        int n = pattern.length();

        // Basic validation: Total characters must match the sum of requested digits.
        if (targetZeros + targetOnes != n) {
            return "-1";
        }

        char[] chars = pattern.toCharArray();

        // Step 1: Enforce symmetry for existing characters.
        // If one side of the pair is a digit and the other is '?', fill the '?'.
        for (int i = 0; i < n; i++) {
            int opposite = n - 1 - i;
            if (chars[i] == '?' && chars[opposite] != '?') {
                chars[i] = chars[opposite];
            } else if (chars[i] != '?' && chars[opposite] == '?') {
                chars[opposite] = chars[i];
            } else if (chars[i] != '?' && chars[opposite] != '?' && chars[i] != chars[opposite]) {
                // If both are digits but they don't match, a palindrome is impossible.
                return "-1";
            }
        }

        // Step 2: Count existing digits to determine how many more are needed.
        int currentZeros = 0;
        int currentOnes = 0;
        for (char c : chars) {
            if (c == '0') currentZeros++;
            else if (c == '1') currentOnes++;
        }

        int remainingZeros = targetZeros - currentZeros;
        int remainingOnes = targetOnes - currentOnes;

        // If we already exceeded the target counts, it's impossible.
        if (remainingZeros < 0 || remainingOnes < 0) {
            return "-1";
        }

        // Step 3: Fill remaining '?' pairs or the middle element.
        for (int i = 0; i <= (n - 1) / 2; i++) {
            int opposite = n - 1 - i;

            if (chars[i] == '?') {
                if (i == opposite) {
                    // Case: Middle element in an odd-length string.
                    if (remainingZeros > 0) {
                        chars[i] = '0';
                        remainingZeros--;
                    } else if (remainingOnes > 0) {
                        chars[i] = '1';
                        remainingOnes--;
                    } else {
                        return "-1";
                    }
                } else {
                    // Case: A pair of symmetric indices.
                    // We must use two of the same digit to maintain the palindrome.
                    if (remainingZeros >= 2) {
                        chars[i] = chars[opposite] = '0';
                        remainingZeros -= 2;
                    } else if (remainingOnes >= 2) {
                        chars[i] = chars[opposite] = '1';
                        remainingOnes -= 2;
                    } else {
                        // Not enough remaining digits to satisfy the pair.
                        return "-1";
                    }
                }
            }
        }

        // Final check: Ensure all requirements are met and result is a valid palindrome.
        if (remainingZeros == 0 && remainingOnes == 0 && isPalindrome(chars)) {
            return new String(chars);
        } else {
            return "-1";
        }
    }

    /**
     * Validates if the character array forms a palindrome.
     */
    private static boolean isPalindrome(char[] chars) {
        int left = 0;
        int right = chars.length - 1;
        while (left < right) {
            if (chars[left] != chars[right]) {
                return false;
            }
            left++;
            right--;
        }
        return true;
    }
}

