/**
 * A solution to the AB Palindrome problem.
 * Given a string of '0', '1', and '?', determine if it can be turned into a palindrome
 * containing exactly 'a' zeroes and 'b' ones.
 */
public class ABPalindrome {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int testCases = scanner.nextInt();
        PalindromeSolver solver = new PalindromeSolver();

        for (int t = 0; t < testCases; t++) {
            int targetZeroes = scanner.nextInt();
            int targetOnes = scanner.nextInt();
            String pattern = scanner.next();

            System.out.println(solver.solve(targetZeroes, targetOnes, pattern));
        }

        scanner.close();
    }

    /**
     * Logic encapsulated within a service class to separate concerns.
     */
    private static class PalindromeSolver {
        private static final char ZERO = '0';
        private static final char ONE = '1';
        private static final char UNKNOWN = '?';
        private static final String IMPOSSIBLE = "-1";

        /**
         * Orchestrates the solving process.
         *
         * @param targetZeroes The required number of '0' characters.
         * @param targetOnes   The required number of '1' characters.
         * @param pattern      The input string containing '0', '1', or '?'.
         * @return The resulting palindrome string or "-1" if impossible.
         */
        public String solve(int targetZeroes, int targetOnes, String pattern) {
            int n = pattern.length();

            // Basic constraint: total characters must match requested counts
            if (targetZeroes + targetOnes != n) {
                return IMPOSSIBLE;
            }

            char[] arr = pattern.toCharArray();

            // Step 1: Ensure existing characters satisfy symmetry
            if (!ensureSymmetry(arr, n)) {
                return IMPOSSIBLE;
            }

            // Step 2: Calculate how many zeroes and ones are already fixed
            int currentZeroes = countOccurrences(arr, ZERO);
            int currentOnes = countOccurrences(arr, ONE);

            // If existing characters already exceed the targets, it's impossible
            if (currentZeroes > targetZeroes || currentOnes > targetOnes) {
                return IMPOSSIBLE;
            }

            // Step 3: Fill remaining '?' greedily
            int remainingZeroes = targetZeroes - currentZeroes;
            int remainingOnes = targetOnes - currentOnes;

            if (!fillRemaining(arr, n, remainingZeroes, remainingOnes)) {
                return IMPOSSIBLE;
            }

            return new String(arr);
        }

        /**
         * Validates that non-'?' characters are symmetric and fills '?' 
         * where the symmetric counterpart is already defined.
         */
        private boolean ensureSymmetry(char[] arr, int n) {
            for (int i = 0; i < (n + 1) / 2; i++) {
                int left = i;
                int right = n - 1 - i;

                if (arr[left] != UNKNOWN && arr[right] != UNKNOWN) {
                    if (arr[left] != arr[right]) {
                        return false;
                    }
                } else if (arr[left] != UNKNOWN) {
                    arr[right] = arr[left];
                } else if (arr[right] != UNKNOWN) {
                    arr[left] = arr[right];
                }
            }
            return true;
        }

        /**
         * Fills the remaining '?' characters based on the required counts.
         */
        private boolean fillRemaining(char[] arr, int n, int remZeroes, int remOnes) {
            for (int i = 0; i < (n + 1) / 2; i++) {
                int left = i;
                int right = n - 1 - i;

                if (arr[left] == UNKNOWN) {
                    if (left == right) {
                        // Case: Middle element of an odd-length string
                        if (remZeroes > 0) {
                            arr[left] = ZERO;
                            remZeroes--;
                        } else if (remOnes > 0) {
                            arr[left] = ONE;
                            remOnes--;
                        } else {
                            return false;
                        }
                    } else {
                        // Case: A symmetric pair of '?'
                        if (remZeroes >= 2) {
                            arr[left] = ZERO;
                            arr[right] = ZERO;
                            remZeroes -= 2;
                        } else if (remOnes >= 2) {
                            arr[left] = ONE;
                            arr[right] = ONE;
                            remOnes -= 2;
                        } else {
                            // Cannot satisfy a pair with only 1 remaining character
                            return false;
                        }
                    }
                }
            }
            // Final check to ensure all required counts were used exactly
            return remZeroes == 0 && remOnes == 0;
        }

        private int countOccurrences(char[] arr, char target) {
            int count = 0;
            for (char c : arr) {
                if (c == target) {
                    count++;
                }
            }
            return count;
        }
    }
}

