        char[] charArray = input.toCharArray();

        // Calculate the remaining budget of '0's and '1's needed
        int remainingZeros = targetZeroCount;
        int remainingOnes = targetOneCount;

        // First pass: Account for existing characters
        for (char c : charArray) {
            if (c == '0') remainingZeros--;
            else if (c == '1') remainingOnes--;
        }

        // If initial counts already exceed targets, it's impossible
        if (remainingZeros < 0 || remainingOnes < 0) {
            return null;
        }

