                // Both are '?', must pick a pair of '0's or '1's to maintain palindrome
                if (remainingZeros >= 2) {
                    charArray[left] = charArray[right] = '0';
                    remainingZeros -= 2;
                } else if (remainingOnes >= 2) {
                    charArray[left] = charArray[right] = '1';
                    remainingOnes -= 2;
                } else {
                    return null; // Cannot satisfy symmetry with available counts
                }
            } else if (charArray[left] == '?' || charArray[right] == '?') {
                // One is '?', the other is a digit. '?' must match the digit.
                char existingDigit = (charArray[left] != '?') ? charArray[left] : charArray[right];

                if (existingDigit == '0') {
                    if (remainingZeros > 0) {
                        charArray[left] = charArray[right] = '0';
                        remainingZeros--;
                    } else {
                        return null;
                    }
                } else { // existingDigit == '1'
                    if (remainingOnes > 0) {
                        charArray[left] = charArray[right] = '1';
                        remainingOnes--;
                    } else {
                        return null;
                    }
                }
            } else {
                // Both are digits, they must match
                if (charArray[left] != charArray[right]) {
                    return null;
                }
            }
        }

        // Handle the middle character for odd-length strings
        if (n % 2 == 1) {
            int mid = n / 2;
            if (charArray[mid] == '?') {
                if (remainingZeros > 0) {
                    charArray[mid] = '0';
                    remainingZeros--;
                } else if (remainingOnes > 0) {
                    charArray[mid] = '1';
                    remainingOnes--;
                } else {
                    return null;
                }
            }
        }

        // Final validation: ensure all required characters are used and no extras remain
        if (remainingZeros != 0 || remainingOnes != 0) {
