         * @param targetOnes  The exact number of '1's required in the final string.
         * @param input       The input string containing '0', '1', and '?'.
         * @return The constructed palindrome string, or "-1" if impossible.
         */
        public String solve(int targetZeros, int targetOnes, String input) {
            int n = input.length();
            char[] chars = input.toCharArray();

            // Calculate how many '0's and '1's we still need to place into '?' slots
            int zerosNeeded = targetZeros;
            int onesNeeded = targetOnes;

            // First pass: Deduct existing characters from the required counts
            for (char c : chars) {
                if (c == '0') {
                    zerosNeeded--;
                } else if (c == '1') {
                    onesNeeded--;
                }
            }

            // If the input string already exceeds the required counts, it's impossible
            if (zerosNeeded < 0 || onesNeeded < 0) {
                return "-1";
            }

            // Second pass: Handle symmetry and '?' that have a fixed partner
            for (int i = 0; i < n / 2; i++) {
                int leftIdx = i;
                int rightIdx = n - 1 - i;
                char leftChar = chars[leftIdx];
                char rightChar = chars[rightIdx];

                if (leftChar != '?' && rightChar != '?') {
                    // If both are digits, they must match to be a palindrome
                    if (leftChar != rightChar) return "-1";
                } else if (leftChar != '?' && rightChar == '?') {
                    // If only left is a digit, right must match it
                    chars[rightIdx] = leftChar;
                    if (leftChar == '0') zerosNeeded--;
                    else onesNeeded--;
                } else if (leftChar == '?' && rightChar != '?') {
