                    chars[leftIdx] = rightChar;
                    if (rightChar == '0') zerosNeeded--;
                    else onesNeeded--;
                }

                // Check if we exceeded the budget of 0s or 1s
                if (zerosNeeded < 0 || onesNeeded < 0) return "-1";
            }

            // Third pass: Handle '?' pairs where both sides are wildcards
            for (int i = 0; i < n / 2; i++) {
                int leftIdx = i;
                int rightIdx = n - 1 - i;

                if (chars[leftIdx] == '?' && chars[rightIdx] == '?') {
                    if (zerosNeeded >= 2) {
