    /**
     * Logic handler for solving the symmetry problem.
     */
    static class SymmetrySolver {

        public String solve(int zeroBudget, int oneBudget, String inputString) {
            int n = inputString.length();
            char[] chars = inputString.toCharArray();

            // Validation: Total budget must match string length
            if (zeroBudget + oneBudget != n) {
                return "-1";
            }

            List<Integer> flexiblePairIndices = new ArrayList<>();

            // Step 1: Process existing characters and handle fixed symmetric pairs
            for (int i = 0; i < n / 2; i++) {
                int j = n - 1 - i;
                char left = chars[i];
                char right = chars[j];

                if (left != '?' && right != '?' && left != right) {
                    return "-1"; // Symmetry broken by fixed characters
                }

                if (left != '?' && right != '?') {
                    // Both are fixed and equal
                    if (left == '0') zeroBudget -= 2;
                    else oneBudget -= 2;
                } else if (left != '?' && right == '?') {
                    // Left is fixed, right must match
                    chars[j] = left;
                    if (left == '0') zeroBudget -= 2;
                    else oneBudget -= 2;
                } else if (left == '?' && right != '?') {
                    // Right is fixed, left must match
                    chars[i] = right;
                    if (right == '0') zeroBudget -= 2;
                    else oneBudget -= 2;
                } else {
                    // Both are '?' - save for later
                    flexiblePairIndices.add(i);
                }

                // Early exit if budget is exceeded
                if (zeroBudget < 0 || oneBudget < 0) return "-1";
            }

            // Step 2: Fill remaining symmetric '?' pairs
            for (int index : flexiblePairIndices) {
                int oppositeIndex = n - 1 - index;
                if (zeroBudget >= 2) {
                    chars[index] = '0';
                    chars[oppositeIndex] = '0';
                    zeroBudget -= 2;
                } else if (oneBudget >= 2) {
                    chars[index] = '1';
                    chars[oppositeIndex] = '1';
                    oneBudget -= 2;
                } else {
                    return "-1";
                }
            }

            // Step 3: Handle the middle element for odd-length strings
            if (n % 2 != 0) {
                int mid = n / 2;
                if (chars[mid] == '?') {
                    if (zeroBudget >= 1) {
                        chars[mid] = '0';
                        zeroBudget -= 1;
                    } else if (oneBudget >= 1) {
                        chars[mid] = '1';
                        oneBudget -= 1;
                    } else {
                        return "-1";
                    }
                } else {
                    // Middle element was already fixed
                    if (chars[mid] == '0') zeroBudget -= 1;
                    else oneBudget -= 1;
                }
            }

            // Final Validation: Budget must be exactly exhausted
            if (zeroBudget == 0 && oneBudget == 0) {
                return new String(chars);
            } else {
                return "-1";
            }
        }
    }

