    /**
     * Attempts to construct a palindrome using exactly the specified number of 0s and 1s.
     * 
     * @param targetZeros The exact number of '0' characters required.
     * @param targetOnes  The exact number of '1' characters required.
     * @param pattern     The initial string containing '0', '1', or '?'.
     * @return The constructed palindrome, or "-1" if impossible.
     */
    public String constructPalindrome(int targetZeros, int targetOnes, String pattern) {
        int n = pattern.length();
        char[] chars = pattern.toCharArray();

        // Phase 1: Enforce symmetry for already provided characters
        for (int i = 0; i < n / 2; i++) {
            int j = n - 1 - i;
            if (chars[i] != '?' && chars[j] != '?') {
                if (chars[i] != chars[j]) {
                    return "-1";
                }
            } else if (chars[i] != '?') {
                chars[j] = chars[i];
            } else if (chars[j] != '?') {
                chars[i] = chars[j];
            }
        }

        // Phase 2: Count the characters we have already fixed
        int currentZeros = 0;
        int currentOnes = 0;
        for (char c : chars) {
            if (c == '0') {
                currentZeros++;
            } else if (c == '1') {
                currentOnes++;
            }
        }

        // Phase 3: Preliminary validation
        if (currentZeros > targetZeros || currentOnes > targetOnes) {
            return "-1";
        }

        int rem0 = targetZeros - currentZeros;
        int rem1 = targetOnes - currentOnes;

        // Phase 4: Fill symmetric question mark pairs
        for (int i = 0; i < n / 2; i++) {
            int j = n - 1 - i;
            if (chars[i] == '?') {
                if (rem0 >= 2) {
                    chars[i] = chars[j] = '0';
                    rem0 -= 2;
                } else if (rem1 >= 2) {
                    chars[i] = chars[j] = '1';
                    rem1 -= 2;
                } else {
                    return "-1";
                }
            }
        }

        // Phase 5: Handle the middle element for odd-length strings
        if (n % 2 == 1) {
            int mid = n / 2;
            if (chars[mid] == '?') {
                if (rem0 == 1) {
                    chars[mid] = '0';
                    rem0 = 0;
                } else if (rem1 == 1) {
                    chars[mid] = '1';
                    rem1 = 0;
                } else {
                    return "-1";
                }
            }
        }

        // Phase 6: Final validation to ensure all requirements were met exactly
        if (rem0 != 0 || rem1 != 0) {
            return "-1";
        }

        return new String(chars);
    }

