import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * PalindromeSolver provides functionality to transform a string pattern
 * into a palindrome given a required count of '0's and '1's.
 */
public class PalindromeSolver {

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int testCases = scanner.nextInt();

            for (int t = 0; t < testCases; t++) {
                int targetZeros = scanner.nextInt();
                int targetOnes = scanner.nextInt();
                String pattern = scanner.next();

                System.out.println(constructPalindrome(targetZeros, targetOnes, pattern));
            }
        }
    }

    /**
     * Attempts to construct a palindrome from the given pattern that meets the target counts.
     *
     * @param targetZeros The exact number of '0' characters required in the result.
     * @param targetOnes  The exact number of '1' characters required in the result.
     * @param pattern     The input pattern containing '0', '1', or '?'.
     * @return The constructed palindrome string, or "-1" if no such palindrome exists.
     */
    public static String constructPalindrome(int targetZeros, int targetOnes, String pattern) {
        int n = pattern.length();
        char[] characters = pattern.toCharArray();
        int currentZeros = 0;
        int currentOnes = 0;

        // 1. Count existing fixed digits
        for (char c : characters) {
            if (c == '0') {
                currentZeros++;
            } else if (c == '1') {
                currentOnes++;
            }
        }

        // 2. Validate if existing digits already violate the palindrome property
        for (int i = 0; i < n / 2; i++) {
            int j = n - 1 - i;
            if (characters[i] != '?' && characters[j] != '?' && characters[i] != characters[j]) {
                return "-1";
            }
        }

        // 3. Fill '?' characters that are forced by their symmetric counterpart
        int freeQuestionPairs = 0;
        boolean middleIsQuestion = false;

        for (int i = 0; i < (n + 1) / 2; i++) {
            int j = n - 1 - i;
            if (i == j) {
                if (characters[i] == '?') {
                    middleIsQuestion = true;
                }
            } else {
                if (characters[i] == '?' && characters[j] == '?') {
                    freeQuestionPairs++;
                } else if (characters[i] == '?') {
                    // i is unknown, j is fixed
                    characters[i] = characters[j];
                    if (characters[i] == '0') currentZeros++; else currentOnes++;
                } else if (characters[j] == '?') {
                    // j is unknown, i is fixed
                    characters[j] = characters[i];
                    if (characters[j] == '0') currentZeros++; else currentOnes++;
                }
            }
        }

        // 4. Check if forced assignments exceeded the provided targets
        if (currentZeros > targetZeros || currentOnes > targetOnes) {
            return "-1";
        }

        int neededZeros = targetZeros - currentZeros;
        int neededOnes = targetOnes - currentOnes;

        // 5. Solve for "free" question marks (pairs and middle element)
        // A Scenario represents: [remaining zeros needed, remaining ones needed, middle char to use]
        List<int[]> scenarios = new ArrayList<>();
        if (middleIsQuestion) {
            // Scenario A: Fill middle with '0'
            if (neededZeros >= 1) {
                scenarios.add(new int[]{neededZeros - 1, neededOnes, '0'});
            }
            // Scenario B: Fill middle with '1'
            if (neededOnes >= 1) {
                scenarios.add(new int[]{neededZeros, neededOnes - 1, '1'});
            }
        } else {
            // No middle '?' to fill
            scenarios.add(new int[]{neededZeros, neededOnes, '?'});
        }

        for (int[] scenario : scenarios) {
            int rem0 = scenario[0];
            int rem1 = scenario[1];
            char midChar = (char) scenario[2];

            // Check if the remaining counts can be distributed into even pairs
            if (rem0 >= 0 && rem1 >= 0 && rem0 % 2 == 0 && rem1 % 2 == 0) {
                if ((rem0 / 2) + (rem1 / 2) == freeQuestionPairs) {
                    // This scenario is valid!
                    if (midChar != '?') {
                        characters[n / 2] = midChar;
                    }

                    int zerosPairsToFill = rem0 / 2;
                    for (int i = 0; i < n / 2; i++) {
                        int j = n - 1 - i;
                        if (characters[i] == '?') {
                            if (zerosPairsToFill > 0) {
                                characters[i] = characters[j] = '0';
                                zerosPairsToFill--;
                            } else {
                                characters[i] = characters[j] = '1';
                            }
                        }
                    }
                    return new String(characters);
                }
            }
        }

        return "-1";
    }
}

