/**
 * A utility to construct a palindrome from a pattern of '0', '1', and '?' 
 * such that the resulting string has an exact count of zeros and ones.
 */
public class PalindromeGenerator {

    public static void main(String[] args) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)))) {

            String firstLine = reader.readLine();
            if (firstLine == null) return;

            int testCases = Integer.parseInt(firstLine.trim());
            while (testCases-- > 0) {
                processTestCase(reader, writer);
            }
        } catch (IOException | NumberFormatException e) {
            // In a production environment, use a logger. 
            // For competitive programming, standard error is acceptable.
            System.err.println("Error processing input: " + e.getMessage());
        }
    }

    /**
     * Reads input for a single test case and writes the result.
     */
    private static void processTestCase(BufferedReader reader, PrintWriter writer) throws IOException {
        String line = reader.readLine();
        if (line == null) return;

        StringTokenizer st = new StringTokenizer(line);
        int targetZeros = Integer.parseInt(st.nextToken());
        int targetOnes = Integer.parseInt(st.nextToken());
        String pattern = reader.readLine();

        writer.println(constructPalindrome(targetZeros, targetOnes, pattern));
    }

    /**
     * Core logic to construct the palindrome.
     * 
     * @param targetZeros The required number of '0's.
     * @param targetOnes  The required number of '1's.
     * @param pattern     The input string containing '0', '1', or '?'.
     * @return The constructed palindrome string, or "-1" if impossible.
     */
    public static String constructPalindrome(int targetZeros, int targetOnes, String pattern) {
        int n = pattern.length();
        char[] result = pattern.toCharArray();

        // 1. Calculate how many 0s and 1s we still need to place
        int currentZeros = 0;
        int currentOnes = 0;
        for (char c : result) {
            if (c == '0') currentZeros++;
            else if (c == '1') currentOnes++;
        }

        int remainingZeros = targetZeros - currentZeros;
        int remainingOnes = targetOnes - currentOnes;

        // If the pattern already contains more 0s or 1s than requested
        if (remainingZeros < 0 || remainingOnes < 0) {
            return "-1";
        }

        // 2. Iterate through the first half of the string to fill '?'
        // The loop goes up to the middle, handling both pairs and the single center element.
        for (int i = 0; i < (n + 1) / 2; i++) {
            int left = i;
            int right = n - 1 - i;

            if (left == right) {
                // Case: Middle element in an odd-length string
                if (result[left] == '?') {
                    if (remainingZeros > 0) {
                        result[left] = '0';
                        remainingZeros--;
                    } else if (remainingOnes > 0) {
                        result[left] = '1';
                        remainingOnes--;
                    } else {
                        return "-1";
                    }
                }
            } else {
                // Case: Symmetric pair
                if (result[left] != '?' && result[right] != '?') {
                    // Both are fixed; they must match to be a palindrome
                    if (result[left] != result[right]) {
                        return "-1";
                    }
                } else if (result[left] != '?') {
                    // Left is fixed, right is '?'
                    result[right] = result[left];
                    if (result[left] == '0') remainingZeros--;
                    else remainingOnes--;
                } else if (result[right] != '?') {
                    // Right is fixed, left is '?'
                    result[left] = result[right];
                    if (result[right] == '0') remainingZeros--;
                    else remainingOnes--;
                } else {
                    // Both are '?'
                    if (remainingZeros >= 2) {
                        result[left] = '0';
                        result[right] = '0';
                        remainingZeros -= 2;
                    } else if (remainingOnes >= 2) {
                        result[left] = '1';
                        result[right] = '1';
                        remainingOnes -= 2;
                    } else {
                        // Cannot satisfy the palindrome requirement with remaining counts
                        return "-1";
                    }
                }
            }

            // Early exit if we've used more than available
            if (remainingZeros < 0 || remainingOnes < 0) {
                return "-1";
            }
        }

        // 3. Final validation: Ensure all requested characters were used exactly
        if (remainingZeros == 0 && remainingOnes == 0) {
            return new String(result);
        } else {
            return "-1";
        }
    }
}

import java.io.*;
