/**
 * A program to generate a palindrome string of a specific length 
 * with a given number of '0's and '1's, filling in '?' characters.
 */
public class KayseeKay {

    public static void main(String[] args) {
        FastReader input = new FastReader(System.in);
        PrintWriter output = new PrintWriter(System.out);

        PalindromeSolver solver = new PalindromeSolver();
        solver.solve(input, output);

        output.flush();
        output.close();
    }

    static class PalindromeSolver {

        private static final char CHAR_ZERO = '0';
        private static final char CHAR_ONE = '1';
        private static final char CHAR_UNKNOWN = '?';

        /**
         * Orchestrates the execution of multiple test cases.
         */
        public void solve(FastReader in, PrintWriter out) {
            int testCases = in.nextInt();
            while (testCases-- > 0) {
                int targetZeros = in.nextInt();
                int targetOnes = in.nextInt();
                String pattern = in.next();

                String result = findPalindrome(targetZeros, targetOnes, pattern);
                out.println(result);
            }
        }

        /**
         * Core logic to construct the palindrome or return "-1" if impossible.
         */
        private String findPalindrome(int targetZeros, int targetOnes, String pattern) {
            int n = pattern.length();
            char[] chars = pattern.toCharArray();

            // Phase 1: Enforce palindrome symmetry for existing characters
            for (int i = 0; i < n / 2; i++) {
                int j = n - 1 - i;
                if (chars[i] != CHAR_UNKNOWN && chars[j] != CHAR_UNKNOWN) {
                    if (chars[i] != chars[j]) return "-1";
                } else if (chars[i] != CHAR_UNKNOWN) {
                    chars[j] = chars[i];
                } else if (chars[j] != CHAR_UNKNOWN) {
                    chars[i] = chars[j];
                }
            }

            // Phase 2: Count currently placed characters and identify available slots
            int currentZeros = 0;
            int currentOnes = 0;
            for (char c : chars) {
                if (c == CHAR_ZERO) currentZeros++;
                else if (c == CHAR_ONE) currentOnes++;
            }

            int neededZeros = targetZeros - currentZeros;
            int neededOnes = targetOnes - currentOnes;

            if (neededZeros < 0 || neededOnes < 0) return "-1";

            int questionMarkPairs = 0;
            for (int i = 0; i < n / 2; i++) {
                if (chars[i] == CHAR_UNKNOWN) questionMarkPairs++;
            }

            boolean hasMiddleChar = (n % 2 != 0);
            boolean middleIsQuestion = hasMiddleChar && (chars[n / 2] == CHAR_UNKNOWN);

            // Phase 3: Determine valid assignment for middle char and question mark pairs
            char middleAssignment = CHAR_UNKNOWN;
            boolean success = false;

            if (middleIsQuestion) {
                // Try assigning '0' to the middle
                if (canSatisfy(neededZeros - 1, neededOnes, questionMarkPairs)) {
                    middleAssignment = CHAR_ZERO;
                    success = true;
                } 
                // Try assigning '1' to the middle
                else if (canSatisfy(neededZeros, neededOnes - 1, questionMarkPairs)) {
                    middleAssignment = CHAR_ONE;
                    success = true;
                }
            } else {
                // No middle '?' exists, middle char is either fixed or length is even
                if (canSatisfy(neededZeros, neededOnes, questionMarkPairs)) {
                    success = true;
                }
            }

            if (!success) return "-1";

            // Final Construction
            return constructResult(chars, middleAssignment, neededZeros, neededOnes, questionMarkPairs);
        }

        /**
         * Validates if the remaining requirements can be met by symmetric pairs.
         */
        private boolean canSatisfy(int rem0, int rem1, int pairs) {
            // Both requirements must be even because they are filled in pairs (left/right)
            if (rem0 < 0 || rem1 < 0 || rem0 % 2 != 0 || rem1 % 2 != 0) return false;
            return (rem0 / 2) + (rem1 / 2) == pairs;
        }

        /**
         * Fills the character array with the calculated values.
         */
        private String constructResult(char[] chars, char midChar, int rem0, int rem1, int pairs) {
            int n = chars.length;
            int p0 = rem0 / 2;

            for (int i = 0; i < n / 2; i++) {
                int j = n - 1 - i;
                if (chars[i] == CHAR_UNKNOWN) {
                    if (p0 > 0) {
                        chars[i] = chars[j] = CHAR_ZERO;
                        p0--;
                    } else {
                        chars[i] = chars[j] = CHAR_ONE;
                    }
                }
            }

            if (n % 2 != 0 && midChar != CHAR_UNKNOWN) {
                chars[n / 2] = midChar;
            }

            return new String(chars);
        }
    }

    /**
     * Fast I/O utility for high-performance input reading.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * A utility class to solve the palindrome construction problem.
 * The goal is to replace '?' in a string with '0' or '1' to create a palindrome
 * containing exactly targetZeroCount '0's and targetOneCount '1's.
 */
class PalindromeSolver {

    /**
     * Attempts to construct a palindrome based on the provided constraints.
     *
     * @param inputString       The initial string containing '0', '1', or '?'.
     * @param targetZeroCount   The required number of '0' characters.
     * @param targetOneCount    The required number of '1' characters.
     * @return The constructed palindrome string, or "-1" if impossible.
     */
    public String solve(String inputString, int targetZeroCount, int targetOneCount) {
        char[] characters = inputString.toCharArray();
        int n = characters.length;

        // Step 1: Fill '?' where the symmetric position is already a fixed character
        for (int i = 0; i <= n / 2; i++) {
            int symmetricIndex = n - i - 1;
            if (characters[i] != '?' && characters[symmetricIndex] == '?') {
                characters[symmetricIndex] = characters[i];
            } else if (characters[i] == '?' && characters[symmetricIndex] != '?') {
                characters[i] = characters[symmetricIndex];
            }
        }

        // Step 2: Count currently placed characters
        int currentZeroCount = 0;
        int currentOneCount = 0;
        for (char c : characters) {
            if (c == '0') currentZeroCount++;
            else if (c == '1') currentOneCount++;
        }

        // Step 3: Fill remaining '?' pairs greedily
        for (int i = 0; i <= n / 2; i++) {
            int symmetricIndex = n - i - 1;

            if (characters[i] == '?' && characters[symmetricIndex] == '?') {
                // Determine if this is a single middle element or a pair
                int cost = (i == symmetricIndex) ? 1 : 2;

                // Try to satisfy targetZeroCount first
                if (currentZeroCount + cost <= targetZeroCount) {
                    characters[i] = '0';
                    characters[symmetricIndex] = '0';
                    currentZeroCount += cost;
                } else {
                    characters[i] = '1';
                    characters[symmetricIndex] = '1';
                    currentOneCount += cost;
                }
            }
        }

        // Step 4: Final Validation
        if (isValid(characters, targetZeroCount, targetOneCount)) {
            return new String(characters);
        } else {
            return "-1";
        }
    }

    private boolean isValid(char[] characters, int targetZeroCount, int targetOneCount) {
        int zeroCount = 0;
        int oneCount = 0;
        int n = characters.length;

        for (int i = 0; i < n; i++) {
            if (characters[i] == '0') zeroCount++;
            else if (characters[i] == '1') oneCount++;

            // Check palindrome property during counting
            if (characters[i] != characters[n - 1 - i]) {
                return false;
            }
        }

        return zeroCount == targetZeroCount && oneCount == targetOneCount;
    }
}

