import java.io.*;
import java.util.*;

public class SymmetrySequenceSolver {

    private static final int WILDCARD_VALUE = 15;

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            String tStr = reader.next();
            if (tStr != null) {
                int t = Integer.parseInt(tStr);
                while (t-- > 0) {
                    solve(reader, writer);
                }
            }
        } catch (Exception e) {
            // Handle parsing errors
        } finally {
            writer.flush();
            writer.close();
        }
    }

    private static void solve(FastReader reader, PrintWriter writer) {
        int targetZeros = reader.nextInt();
        int targetOnes = reader.nextInt();
        String patternString = reader.next();
        int[] sequence = parseSequence(patternString);
        int n = targetZeros + targetOnes;

        // 1. Check for symmetry conflicts and synchronize wildcards
        for (int i = 0; i < n / 2; i++) {
            int p = n - i - 1;
            if ((sequence[i] == 0 && sequence[p] == 1) || (sequence[i] == 1 && sequence[p] == 0)) {
                writer.println("-1");
                return;
            }
            if (sequence[i] == WILDCARD_VALUE && sequence[p] != WILDCARD_VALUE) {
                sequence[i] = sequence[p];
            } else if (sequence[p] == WILDCARD_VALUE && sequence[i] != WILDCARD_VALUE) {
                sequence[p] = sequence[i];
            }
        }

        // 2. Count currently assigned 0s and 1s
        int remZeros = targetZeros;
        int remOnes = targetOnes;
        for (int val : sequence) {
            if (val == 0) remZeros--;
            else if (val == 1) remOnes--;
        }

        // 3. Fill the remaining wildcards
        // Process pairs
        for (int i = 0; i < n / 2; i++) {
            int p = n - i - 1;
            if (sequence[i] == WILDCARD_VALUE) {
                if (remZeros >= 2) {
                    sequence[i] = 0;
                    sequence[p] = 0;
                    remZeros -= 2;
                } else {
                    sequence[i] = 1;
                    sequence[p] = 1;
                    remOnes -= 2;
                }
            }
        }

        // Process middle element
        if (n % 2 == 1) {
            int mid = n / 2;
            if (sequence[mid] == WILDCARD_VALUE) {
                if (remZeros >= 1) {
                    sequence[mid] = 0;
                    remZeros--;
                } else {
                    sequence[mid] = 1;
                    remOnes--;
                }
            }
        }

        // 4. Validate feasibility and output
        if (remZeros < 0 || remOnes < 0) {
            writer.println("-1");
        } else {
            for (int val : sequence) {
                writer.print(val);
            }
            writer.println();
        }
    }

    private static int[] parseSequence(String s) {
        if (s == null || s.isEmpty()) return new int[0];
        char first = s.charAt(0);
        char offset = '0';
        if (first >= 'a' && first <= 'z') offset = 'a';
        else if (first >= 'A' && first <= 'Z') offset = 'A';

        int[] res = new int[s.length()];
        for (int i = 0; i < s.length(); i++) {
            res[i] = s.charAt(i) - offset;
        }
        return res;
    }

    static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
