/**
 * PalindromeBuilder refactors the original code to follow software engineering best practices:
 * 
 * 1. Improved Naming: Short, cryptic variables like 'a', 'b', 'l', 'r' are replaced with 
 *    descriptive names like 'targetZeros', 'remainingOnes', 'leftIndex', etc.
 * 2. Separation of Concerns: The program logic is divided into input reading (FastScanner), 
 *    the core algorithm (solve), and the orchestration (main).
 * 3. Removal of Dead Code: Unused helper classes (Pair), unused static variables (mod, flag, d), 
 *    and unused methods (debug) have been removed to reduce cognitive load.
 * 4. Improved Maintainability: The algorithm is structured into two clear logical passes: 
 *    one to resolve fixed characters and one to fill the remaining gaps.
 * 5. Robustness: Added explicit checks for total counts, parity, and resource exhaustion.
 */
public class PalindromeBuilder {

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        String testCasesInput = sc.next();
        if (testCasesInput != null) {
            int t = Integer.parseInt(testCasesInput);
            while (t-- > 0) {
                out.println(solve(sc));
            }
        }
        out.flush();
        out.close();
    }

    /**
     * Solves a single test case by constructing a palindrome string based on target counts.
     *
     * @param sc The FastScanner for efficient input reading.
     * @return The resulting palindrome string, or "-1" if a palindrome cannot be formed.
     */
    private static String solve(FastScanner sc) {
        int targetZeros = sc.nextInt();
        int targetOnes = sc.nextInt();
        String sStr = sc.next();

        if (sStr == null) {
            return "-1";
        }

        char[] s = sStr.toCharArray();
        int n = s.length;

        // Fundamental requirement: the sum of target counts must match the string length.
        if (targetZeros + targetOnes != n) {
            return "-1";
        }

        // Parity Check:
        // In a palindrome, characters are added in pairs, with at most one single middle element.
        // Therefore, it is impossible to have two odd counts (e.g., targetZeros=1 and targetOnes=1 for N=2).
        if (targetZeros % 2 != 0 && targetOnes % 2 != 0) {
            return "-1";
        }

        int currentZeros = 0;
        int currentOnes = 0;

        // FIRST PASS:
        // Resolve characters that are already determined or partially determined.
        // If one side of a pair is '?' and the other is a fixed value, we mirror that value.
        for (int i = 0; i < (n + 1) / 2; i++) {
            int left = i;
            int right = n - 1 - i;

            if (left == right) {
                // Handle the single middle character for odd-length strings.
                if (s[left] == '0') {
                    currentZeros++;
                } else if (s[left] == '1') {
                    currentOnes++;
                }
            } else {
                if (s[left] != '?' && s[right] != '?') {
                    // Both characters are known: they must match to form a palindrome.
                    if (s[left] != s[right]) {
                        return "-1";
                    }
                    if (s[left] == '0') {
                        currentZeros += 2;
                    } else {
                        currentOnes += 2;
                    }
                } else if (s[left] != '?' || s[right] != '?') {
                    // One character is known, the other is '?'. Mirror the known value.
                    char fixed = (s[left] != '?') ? s[left] : s[right];
                    s[left] = s[right] = fixed;
                    if (fixed == '0') {
                        currentZeros += 2;
                    } else {
                        currentOnes += 2;
                    }
                }
                // If both are '?', we leave them as '?' to be decided in the second pass.
            }
        }

        // If pre-existing fixed characters already exceed the requested counts, return failure.
        if (currentZeros > targetZeros || currentOnes > targetOnes) {
            return "-1";
        }

        // SECOND PASS:
        // Fill the remaining '?' gaps using the remaining counts required.
        int remainingZeros = targetZeros - currentZeros;
        int remainingOnes = targetOnes - currentOnes;

        for (int i = 0; i < (n + 1) / 2; i++) {
            int left = i;
            int right = n - 1 - i;

            if (left == right) {
                if (s[left] == '?') {
                    if (remainingZeros > 0) {
                        s[left] = '0';
                        remainingZeros--;
                    } else if (remainingOnes > 0) {
                        s[left] = '1';
                        remainingOnes--;
                    } else {
                        return "-1";
                    }
                }
            } else {
                if (s[left] == '?') {
                    // Because it must be a palindrome, '?' must be filled as a symmetric pair.
                    if (remainingZeros >= 2) {
                        s[left] = s[right] = '0';
                        remainingZeros -= 2;
                    } else if (remainingOnes >= 2) {
                        s[left] = s[right] = '1';
                        remainingOnes -= 2;
                    } else {
                        // We cannot satisfy the required count using symmetric pairs.
                        return "-1";
                    }
                }
            }
        }

        // Final check: Ensure all requirements were met exactly.
        if (remainingZeros != 0 || remainingOnes != 0) {
            return "-1";
        }

        return new String(s);
    }

    /**
     * FastScanner provides optimized input reading using BufferedReader and StringTokenizer.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        return null;
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            return (next == null) ? 0 : Integer.parseInt(next);
        }
    }
}

import java.util.*;

/**
 * A utility class to construct a palindrome pattern from a string containing '0', '1', and '?'.
 * The construction must satisfy specific target counts for '0' and '1' characters.
 */
public class PalindromeGenerator {

    private static final String NOT_FOUND = "-1";
    private static final char ZERO = '0';
    private static final char ONE = '1';
    private static final char UNKNOWN = '?';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int testCases = scanner.nextInt();
        for (int i = 0; i < testCases; i++) {
            int targetZeroCount = scanner.nextInt();
            int targetOneCount = scanner.nextInt();
            String pattern = scanner.next();

            System.out.println(generatePalindrome(pattern, targetZeroCount, targetOneCount));
        }
        scanner.close();
    }

    /**
     * Attempts to create a palindrome string based on the provided pattern and target counts.
     *
     * @param pattern           The input string containing '0', '1', or '?'.
     * @param targetZeroCount   The exact number of '0's required in the final string.
     * @param targetOneCount    The exact number of '1's required in the final string.
     * @return                  The constructed palindrome string, or "-1" if it is impossible.
     */
    public static String generatePalindrome(String pattern, int targetZeroCount, int targetOneCount) {
        int length = pattern.length();
        char[] chars = pattern.toCharArray();
        int[] remainingCounts = {targetZeroCount, targetOneCount};

        // List to keep track of indices where both symmetrical positions are '?'
        List<Integer> questionMarkPairs = new ArrayList<>();

        // Pass 1: Handle existing fixed characters and match them with their symmetrical counterparts
        for (int i = 0; i < length / 2; i++) {
            int left = i;
            int right = length - 1 - i;

            if (chars[left] != UNKNOWN && chars[right] != UNKNOWN) {
                // Both sides are fixed: they must be identical
                if (chars[left] != chars[right]) {
                    return NOT_FOUND;
                }
                remainingCounts[chars[left] - ZERO] -= 2;
            } else if (chars[left] != UNKNOWN) {
                // Left is fixed, right is '?': fill right with left's value
                chars[right] = chars[left];
                remainingCounts[chars[left] - ZERO] -= 2;
            } else if (chars[right] != UNKNOWN) {
                // Right is fixed, left is '?': fill left with right's value
                chars[left] = chars[right];
                remainingCounts[chars[right] - ZERO] -= 2;
            } else {
                // Both are '?'
                questionMarkPairs.add(left);
            }
        }

        // Pass 2: Fill the pairs of '?' that were found in Pass 1
        for (int leftIdx : questionMarkPairs) {
            int rightIdx = length - 1 - leftIdx;
            if (remainingCounts[0] >= 2) {
                chars[leftIdx] = ZERO;
                chars[rightIdx] = ZERO;
                remainingCounts[0] -= 2;
            } else if (remainingCounts[1] >= 2) {
                chars[leftIdx] = ONE;
                chars[rightIdx] = ONE;
                remainingCounts[1] -= 2;
            } else {
                return NOT_FOUND;
            }
        }

        // Pass 3: Handle the middle character for odd-length strings
        if (length % 2 != 0) {
            int mid = length / 2;
            if (chars[mid] == UNKNOWN) {
                if (remainingCounts[0] > 0) {
                    chars[mid] = ZERO;
                    remainingCounts[0]--;
                } else if (remainingCounts[1] > 0) {
                    chars[mid] = ONE;
                    remainingCounts[1]--;
                } else {
                    return NOT_FOUND;
                }
            } else {
                // If the middle character was already fixed, decrement its count
                remainingCounts[chars[mid] - ZERO]--;
            }
        }

        // Final Validation: Check if the character counts match the requirements exactly
        if (remainingCounts[0] == 0 && remainingCounts[1] == 0) {
            return new String(chars);
        }

        return NOT_FOUND;
    }
}

import java.util.*;
