/**
 * A solution to construct a palindrome of a specific length with a given number
 * of '0's and '1's, given a string containing '0', '1', and '?' (wildcards).
 */
public class PalindromeProblem {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        StringBuilder output = new StringBuilder();

        int testCases = reader.nextInt();
        while (testCases-- > 0) {
            int targetZeroCount = reader.nextInt();
            int targetOneCount = reader.nextInt();
            String pattern = reader.next();

            PalindromeSolver solver = new PalindromeSolver(targetZeroCount, targetOneCount, pattern);
            output.append(solver.solve()).append("\n");
        }

        System.out.print(output);
    }

    /**
     * Handles the logic for constructing the palindrome.
     */
    static class PalindromeSolver {
        private final int targetZeroCount;
        private final int targetOneCount;
        private final char[] patternArray;
        private final int n;

        public PalindromeSolver(int targetZeroCount, int targetOneCount, String pattern) {
            this.targetZeroCount = targetZeroCount;
            this.targetOneCount = targetOneCount;
            this.patternArray = pattern.toCharArray();
            this.n = pattern.length();
        }

        public String solve() {
            // 1. Basic length validation
            if (targetZeroCount + targetOneCount != n) {
                return "-1";
            }

            // 2. Initial pass: enforce palindrome constraints and identify conflicts
            if (!enforcePalindromeConstraints()) {
                return "-1";
            }

            // 3. Calculate remaining counts needed after fixed characters are placed
            int currentZeroCount = 0;
            int currentOneCount = 0;
            for (char c : patternArray) {
                if (c == '0') currentZeroCount++;
                else if (c == '1') currentOneCount++;
            }

            int remainingZero = targetZeroCount - currentZeroCount;
            int remainingOne = targetOneCount - currentOneCount;

            // If we already exceeded the target counts, it's impossible
            if (remainingZero < 0 || remainingOne < 0) {
                return "-1";
            }

            // 4. Second pass: Fill remaining '?' based on required counts
            if (!fillWildcards(remainingZero, remainingOne)) {
                return "-1";
            }

            // 5. Final validation
            String result = new String(patternArray);
            if (isPalindrome(result) && countOccurrences(result, '0') == targetZeroCount 
                && countOccurrences(result, '1') == targetOneCount) {
                return result;
            }

            return "-1";
        }

        private boolean enforcePalindromeConstraints() {
            for (int i = 0; i < (n + 1) / 2; i++) {
                int j = n - 1 - i;
                char left = patternArray[i];
                char right = patternArray[j];

                if (left != '?' && right != '?' && left != right) {
                    return false; // Contradicting fixed characters
                }

                // If one is '?' and the other is fixed, fill the '?'
                if (left != '?' && right == '?') {
                    patternArray[j] = left;
                } else if (left == '?' && right != '?') {
                    patternArray[i] = right;
                }
            }
            return true;
        }

        private boolean fillWildcards(int remZero, int remOne) {
            // Handle pairs first
            for (int i = 0; i < n / 2; i++) {
                int j = n - 1 - i;
                if (patternArray[i] == '?') {
                    // Since it's a pair, we must use 2 of the same character
                    if (remZero >= 2) {
                        patternArray[i] = patternArray[j] = '0';
                        remZero -= 2;
                    } else if (remOne >= 2) {
                        patternArray[i] = patternArray[j] = '1';
                        remOne -= 2;
                    } else {
                        return false;
                    }
                }
            }

            // Handle the middle element for odd-length strings
            if (n % 2 == 1) {
                int mid = n / 2;
                if (patternArray[mid] == '?') {
                    if (remZero >= 1) {
                        patternArray[mid] = '0';
                        remZero--;
                    } else if (remOne >= 1) {
                        patternArray[mid] = '1';
                        remOne--;
                    } else {
                        return false;
                    }
                }
            }

            // Check if we perfectly exhausted the required counts
            return remZero == 0 && remOne == 0;
        }

        private boolean isPalindrome(String s) {
            int i = 0, j = s.length() - 1;
            while (i < j) {
                if (s.charAt(i++) != s.charAt(j--)) return false;
            }
            return true;
        }

        private int countOccurrences(String s, char target) {
            int count = 0;
            for (int i = 0; i < s.length(); i++) {
                if (s.charAt(i) == target) count++;
            }
            return count;
        }
    }

    /**
     * Fast I/O utility for efficient reading.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

