/**
 * A utility class to generate a palindrome string from a pattern of '0', '1', and '?'.
 * The goal is to replace '?' such that the resulting string is a palindrome 
 * and contains exactly 'a' zeros and 'b' ones.
 */
public class PalindromeGenerator {

    private static final String IMPOSSIBLE = "-1";

    /**
     * Attempts to construct a palindrome based on the given constraints.
     *
     * @param targetZeroCount The exact number of '0' characters required.
     * @param targetOneCount  The exact number of '1' characters required.
     * @param pattern         The input string containing '0', '1', or '?'.
     * @return A valid palindrome string, or "-1" if impossible.
     */
    public String generate(int targetZeroCount, int targetOneCount, String pattern) {
        if (pattern == null || pattern.length() != (targetZeroCount + targetOneCount)) {
            return IMPOSSIBLE;
        }

        int n = pattern.length();
        char[] result = pattern.toCharArray();

        // Step 1: Fill '?' that are forced by existing digits to maintain palindrome property
        for (int i = 0; i < n / 2; i++) {
            int j = n - 1 - i;
            char left = result[i];
            char right = result[j];

            if (left != '?' && right != '?') {
                // If both are digits, they must be identical for a palindrome
                if (left != right) {
                    return IMPOSSIBLE;
                }
            } else if (left != '?') {
                // If left is digit, right must match it
                result[j] = left;
            } else if (right != '?') {
                // If right is digit, left must match it
                result[i] = right;
            }
        }

        // Step 2: Count current '0's and '1's after forced assignments
        int currentZeroCount = 0;
        int currentOneCount = 0;
        for (char c : result) {
            if (c == '0') {
                currentZeroCount++;
            } else if (c == '1') {
                currentOneCount++;
            }
        }

        int remainingZero = targetZeroCount - currentZeroCount;
        int remainingOne = targetOneCount - currentOneCount;

        // If we have already exceeded the allowed count for '0' or '1'
        if (remainingZero < 0 || remainingOne < 0) {
            return IMPOSSIBLE;
        }

        // Step 3: Fill remaining '?' pairs and the middle element (if exists)
        // We iterate up to the middle of the array
        for (int i = 0; i <= (n - 1) / 2; i++) {
            int j = n - 1 - i;

            if (i < j) {
                // Case: Symmetric pair of '?'
                if (result[i] == '?') {
                    if (remainingZero >= 2) {
                        result[i] = result[j] = '0';
                        remainingZero -= 2;
                    } else if (remainingOne >= 2) {
                        result[i] = result[j] = '1';
                        remainingOne -= 2;
                    } else {
                        return IMPOSSIBLE;
                    }
                }
            } else {
                // Case: Middle element in an odd-length string (i == j)
                if (result[i] == '?') {
                    if (remainingZero >= 1) {
                        result[i] = '0';
                        remainingZero -= 1;
                    } else if (remainingOne >= 1) {
                        result[i] = '1';
                        remainingOne -= 1;
                    } else {
                        return IMPOSSIBLE;
                    }
                }
            }
        }

        // Step 4: Final validation to ensure all requirements are exactly met
        if (remainingZero == 0 && remainingOne == 0) {
            return new String(result);
        } else {
            return IMPOSSIBLE;
        }
    }

    public static void main(String[] args) {
        PalindromeGenerator generator = new PalindromeGenerator();

        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String line = br.readLine();
            if (line == null) return;

            int testCases = Integer.parseInt(line.trim());
            while (testCases-- > 0) {
                String lineParams = br.readLine();
                if (lineParams == null) break;

                StringTokenizer st = new StringTokenizer(lineParams);
                int a = Integer.parseInt(st.nextToken());
                int b = Integer.parseInt(st.nextToken());
                String pattern = br.readLine();

                System.out.println(generator.generate(a, b, pattern));
            }
        } catch (IOException | NumberFormatException e) {
            // Standard error handling for production-grade code
            System.err.println("Error processing input: " + e.getMessage());
        }
    }
}

