    /**
     * Fast I/O reader for competitive programming scenarios.
     */
    static class FastReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[8192];
        private int pointer = 0;
        private int bytesRead = 0;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (pointer >= bytesRead) {
                pointer = 0;
                try {
                    bytesRead = stream.read(buffer);
                } catch (IOException e) {
                    return -1;
                }
                if (bytesRead <= 0) return -1;
            }
            return buffer[pointer++];
        }

        public int nextInt() {
            int c = read();
            while (c != -1 && c <= 32) c = read();
            if (c == -1) return 0;
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            while (c >= '0' && c <= '9') {
                res = res * 10 + (c - '0');
                c = read();
            }
            return res * sgn;
        }

        public String next() {
            int c = read();
            while (c != -1 && c <= 32) c = read();
            if (c == -1) return "";
            StringBuilder sb = new StringBuilder();
            while (c > 32) {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * Represents a point in the 2D grid.
 */
record Point(int r, int c) {}

/**
 * Represents a node in the BFS traversal containing a point and its distance from the source.
 */
record Node(Point point, int distance) {}

/**
 * Encapsulates the Maze grid and its properties.
 */
class Maze {
    private final char[][] grid;
    private final int rows;
    private final int cols;
    private Point startPos;
    private Point endPos;

    public Maze(int rows, int cols) {
        this.rows = rows;
        this.cols = cols;
        this.grid = new char[rows][cols];
    }

    public void setCell(int r, int c, char value) {
        grid[r][c] = value;
        if (value == 'S') {
            startPos = new Point(r, c);
        } else if (value == 'E') {
            endPos = new Point(r, c);
        }
    }

    public char getCell(int r, int c) {
        return grid[r][c];
    }

    public int getRows() { return rows; }
    public int getCols() { return cols; }
    public Point getStartPos() { return startPos; }
    public Point getEndPos() { return endPos; }

    public boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Checks if a cell is a traversable path (not a wall 'T').
     */
    public boolean isTraversable(int r, int c) {
        return isWithinBounds(r, c) && grid[r][c] != 'T';
    }

    /**
     * Specifically for the second BFS: checks if a cell is a digit.
     * The original logic excludes 'S', 'E', and 'T'.
     */
    public boolean isDigit(int r, int c) {
        if (!isWithinBounds(r, c)) return false;
        char val = grid[r][c];
        return Character.isDigit(val);
    }
}

/**
 * Contains the logic to solve the maze problem.
 */
class MazeSolver {
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};
    private final Maze maze;

    public MazeSolver(Maze maze) {
        this.maze = maze;
    }

    /**
     * Calculates the shortest distance from Start to End using BFS.
     */
    public int findShortestDistance() {
        Point start = maze.getStartPos();
        Point end = maze.getEndPos();

        if (start == null || end == null) return -1;

        Queue<Node> queue = new ArrayDeque<>();
        boolean[][] visited = new boolean[maze.getRows()][maze.getCols()];

        queue.add(new Node(start, 0));
        visited[start.r()][start.c()] = true;

        while (!queue.isEmpty()) {
            Node current = queue.poll();

            if (current.point().equals(end)) {
                return current.distance();
            }

            for (int i = 0; i < 4; i++) {
                int nr = current.point().r() + DR[i];
                int nc = current.point().c() + DC[i];

                if (maze.isTraversable(nr, nc) && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    queue.add(new Node(new Point(nr, nc), current.distance() + 1));
                }
            }
        }
        return -1;
    }

    /**
     * Calculates the sum of digits reachable from End within the shortestDistance constraint.
     */
    public int sumDigitsWithinDistance(int maxDistance) {
        Point end = maze.getEndPos();
        if (end == null || maxDistance == -1) return 0;

        Queue<Node> queue = new ArrayDeque<>();
        boolean[][] visited = new boolean[maze.getRows()][maze.getCols()];
        int digitSum = 0;

        // The second BFS starts from 'E'
        queue.add(new Node(end, 0));
        // Note: 'E' is not added to visited here so we can control traversal logic carefully
        // based on the original code's behavior.

        while (!queue.isEmpty()) {
            Node current = queue.poll();
            int r = current.point().r();
            int c = current.point().c();
            int dist = current.distance();

            if (dist > maxDistance) continue;
            if (visited[r][c]) continue;

            // Logic from original code: if it's not 'E', add its value to sum
            if (maze.getCell(r, c) != 'E') {
                // The original code checks if it's a digit before adding to sum implicitly 
                // via the neighbor check, but we'll be explicit.
                if (Character.isDigit(maze.getCell(r, c))) {
                    digitSum += Character.getNumericValue(maze.getCell(r, c));
                }
                visited[r][c] = true;
            }

            // Explore neighbors
            for (int i = 0; i < 4; i++) {
                int nr = r + DR[i];
                int nc = c + DC[i];

                // Original constraint: neighbors must be digits (not E, S, or T)
                if (maze.isDigit(nr, nc) && !visited[nr][nc]) {
                    queue.add(new Node(new Point(nr, nc), dist + 1));
                }
            }
        }

        return digitSum;
    }
}

public class Main {
    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            if (!sc.hasNextInt()) return;
            int n = sc.nextInt();
            int m = sc.nextInt();

            Maze maze = new Maze(n, m);

            for (int i = 0; i < n; i++) {
                String rowStr = sc.next();
                for (int j = 0; j < m; j++) {
                    maze.setCell(i, j, rowStr.charAt(j));
                }
            }

            MazeSolver solver = new MazeSolver(maze);
            int shortestDist = solver.findShortestDistance();
            int result = solver.sumDigitsWithinDistance(shortestDist);

            out.println(result);
            out.flush();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Queue;
import java.util.StringTokenizer;

/**
 * Solution for the Breeder problem.
 * The goal is to calculate the sum of quantities of breeders reachable from the exit
 * in a distance less than or equal to the distance from the start to the exit.
 */
public class BreederSolution {

    // Represents a coordinate in the grid
    private record Point(int row, int col) {}

    // Represents a breeder found in the grid
    private record Breeder(int distance, int quantity) {}

    // Possible movement directions: Down, Up, Right, Left
    private static final int[][] DIRECTIONS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        solve(scanner);
    }

    private static void solve(FastScanner scanner) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] grid = new char[rows][cols];
        int exitRow = -1;
        int exitCol = -1;

        // Parse the grid and locate the exit 'E'
        for (int r = 0; r < rows; r++) {
            String line = scanner.next();
            if (line == null) break;
            grid[r] = line.toCharArray();
            int eIdx = grid[r].length == 0 ? -1 : indexOf(grid[r], 'E');
            if (eIdx != -1) {
                exitRow = r;
                exitCol = eIdx;
            }
        }

        if (exitRow == -1) {
            System.out.println(0);
            return;
        }

        // BFS variables
        int[][] distances = new int[rows][cols];
        for (int[] rowDist : distances) {
            Arrays.fill(rowDist, -1);
        }

        List<Breeder> breeders = new ArrayList<>();
        int startDistance = -1;

        // Perform BFS starting from the exit
        Queue<Point> queue = new ArrayDeque<>();
        distances[exitRow][exitCol] = 0;
        queue.add(new Point(exitRow, exitCol));

        while (!queue.isEmpty()) {
            Point current = queue.poll();
            int r = current.row();
            int c = current.col();
            int d = distances[r][c];
            char cellType = grid[r][c];

            // If current cell is a breeder (digit), record it
            if (Character.isDigit(cellType)) {
                breeders.add(new Breeder(d, cellType - '0'));
            } 
            // If current cell is the starting position 'S', record its distance
            else if (cellType == 'S') {
                startDistance = d;
            }

            // Explore neighbors only if the current cell is not a Trap ('T')
            // Note: Based on original logic, 'T' is a sink (can enter, but not leave)
            if (cellType != 'T') {
                for (int[] dir : DIRECTIONS) {
                    int nr = r + dir[0];
                    int nc = c + dir[1];

                    if (isValidMove(nr, nc, rows, cols) && distances[nr][nc] == -1) {
                        distances[nr][nc] = d + 1;
                        queue.add(new Point(nr, nc));
                    }
                }
            }
        }

        // Calculate result: sum of quantities of breeders where dist <= startDistance
        long totalBreedersCount = 0;
        for (Breeder breeder : breeders) {
            if (startDistance != -1 && breeder.distance() <= startDistance) {
                totalBreedersCount += breeder.quantity();
            }
        }

        System.out.println(totalBreedersCount);
    }

    private static boolean isValidMove(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private static int indexOf(char[] array, char target) {
        for (int i = 0; i < array.length; i++) {
            if (array[i] == target) return i;
        }
        return -1;
    }

    /**
     * Fast I/O utility class.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream inputStream) {
            this.reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            return next == null ? 0 : Integer.parseInt(next);
        }

        public long nextLong() {
            String next = next();
            return next == null ? 0L : Long.parseLong(next);
        }

        public double nextDouble() {
            String next = next();
            return next == null ? 0.0 : Double.parseDouble(next);
        }
    }
}

