/**
 * Represents a coordinate in the 2D grid.
 */
record Coordinate(int row, int col) {}

/**
 * Represents the grid structure and provides utility methods for cell access.
 */
class GridMap {
    public static final char EXIT_CELL = 'E';
    public static final char START_CELL = 'S';
    public static final char WALL_CELL = 'T';

    private final char[][] grid;
    private final int rows;
    private final int cols;

    public GridMap(int rows, int cols, Scanner scanner) {
        this.rows = rows;
        this.cols = cols;
        this.grid = new char[rows][cols];
        fillGrid(scanner);
    }

    private void fillGrid(Scanner scanner) {
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
            }
        }
    }

    public boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    public char getCell(int r, int c) {
        return grid[r][c];
    }

    public int getRows() { return rows; }
    public int getCols() { return cols; }

    /**
     * Converts a cell character to its numeric value.
     * Returns 0 if the character is not a digit.
     */
    public int getTrainerValue(int r, int c) {
        char val = grid[r][c];
        if (Character.isDigit(val)) {
            return val - '0';
        }
        return 0;
    }
}

/**
 * Handles the logic for calculating trainers using a traversal algorithm.
 */
class TrainerSolver {
    private static final int[][] DIRECTIONS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    private final GridMap gridMap;
    private final int[][] distances;

    public TrainerSolver(GridMap gridMap) {
        this.gridMap = gridMap;
        this.distances = new int[gridMap.getRows()][gridMap.getCols()];
    }

    public int solve() {
        Coordinate exitCoord = findExit();
        if (exitCoord == null) return 0;

        int totalTrainers = 0;
        Deque<Coordinate> queue = new ArrayDeque<>();

        queue.add(exitCoord);
        distances[exitCoord.row()][exitCoord.col()] = 0;

        while (!queue.isEmpty()) {
            Coordinate current = queue.poll();
            int r = current.row();
            int c = current.col();
            int currentDist = distances[r][c];

            // Special logic: If we hit the start cell 'S', process remaining nodes in queue
            if (gridMap.getCell(r, c) == GridMap.START_CELL) {
                totalTrainers += processRemainingNodes(queue, currentDist);
                break;
            }

            // Add current cell's trainers if it's not the exit
            if (gridMap.getCell(r, c) != GridMap.EXIT_CELL) {
                totalTrainers += gridMap.getTrainerValue(r, c);
            }

            // Explore neighbors
            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                if (isTraversable(nr, nc)) {
                    queue.add(new Coordinate(nr, nc));
                    distances[nr][nc] = currentDist + 1;
                }
            }
        }

        return totalTrainers;
    }

    private boolean isTraversable(int r, int c) {
        return gridMap.isValid(r, c) 
                && gridMap.getCell(r, c) != GridMap.WALL_CELL 
                && gridMap.getCell(r, c) != GridMap.EXIT_CELL 
                && distances[r][c] == 0;
    }

    private int processRemainingNodes(Deque<Coordinate> queue, int thresholdDist) {
        int extraTrainers = 0;
        while (!queue.isEmpty()) {
            Coordinate node = queue.poll();
            if (distances[node.row()][node.col()] <= thresholdDist) {
                extraTrainers += gridMap.getTrainerValue(node.row(), node.col());
            }
        }
        return extraTrainers;
    }

    private Coordinate findExit() {
        for (int i = 0; i < gridMap.getRows(); i++) {
            for (int j = 0; j < gridMap.getCols(); j++) {
                if (gridMap.getCell(i, j) == GridMap.EXIT_CELL) {
                    return new Coordinate(i, j);
                }
            }
        }
        return null;
    }
}

