/**
 * Logic for solving the treasure grid problem.
 */
class TreasureGridSolver {
    private static final int OBSTACLE = -1;
    private static final int UNREACHABLE = Integer.MAX_VALUE;
    private static final int[][] DIRECTIONS = {
        {0, 1}, {0, -1}, {1, 0}, {-1, 0}
    };

    /**
     * Reads the grid, performs BFS to find distances, and calculates the sum.
     */
    public void solve(FastReader reader, PrintWriter out) {
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        int[][] grid = new int[rows][cols];
        int startR = -1, startC = -1;
        int exitR = -1, exitC = -1;

        // Parse the grid
        for (int i = 0; i < rows; i++) {
            String line = reader.next();
            for (int j = 0; j < cols; j++) {
                char ch = line.charAt(j);
                if (ch == 'T') {
                    grid[i][j] = OBSTACLE;
                } else if (ch == 'S') {
                    grid[i][j] = 0;
                    startR = i;
                    startC = j;
                } else if (ch == 'E') {
                    grid[i][j] = 0;
                    exitR = i;
                    exitC = j;
                } else {
                    // Convert digit character to integer
                    grid[i][j] = Character.getNumericValue(ch);
                }
            }
        }

        // Find distances from the Exit to all other points using BFS
        int[][] distances = computeDistancesFrom(grid, exitR, exitC, rows, cols);

        // Calculate the total treasure reachable within the start-to-exit distance
        long totalTreasure = 0;
        int pathLen = distances[startR][startC];

        // If the start is unreachable from the exit, pathLen will be UNREACHABLE
        if (pathLen != UNREACHABLE) {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] > 0 && distances[i][j] <= pathLen) {
                        totalTreasure += grid[i][j];
                    }
                }
            }
        }

        out.println(totalTreasure);
    }

    /**
     * Performs BFS to find the shortest distance from a source cell to all reachable cells.
     */
    private int[][] computeDistancesFrom(int[][] grid, int startR, int startC, int rows, int cols) {
        int[][] distances = new int[rows][cols];
        for (int[] row : distances) {
            Arrays.fill(row, UNREACHABLE);
        }

        Deque<Point> queue = new ArrayDeque<>();
        distances[startR][startC] = 0;
        queue.add(new Point(startR, startC));

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            for (int[] dir : DIRECTIONS) {
                int nr = current.r + dir[0];
                int nc = current.c + dir[1];

                // Boundary and obstacle check
                if (isValidMove(nr, nc, rows, cols, grid) && distances[nr][nc] == UNREACHABLE) {
                    distances[nr][nc] = distances[current.r][current.c] + 1;
                    queue.add(new Point(nr, nc));
                }
            }
        }
        return distances;
    }

    private boolean isValidMove(int r, int c, int rows, int cols, int[][] grid) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] != OBSTACLE;
    }

    /**
     * Simple data structure to represent a cell coordinate.
     */
    private static class Point {
        final int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }
}

