import java.io.DataInputStream;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.LinkedList;
import java.util.Queue;

/**
 * Solves a grid-based pathfinding problem where we find the sum of numeric 
 * values in cells reachable within a certain distance from a starting point.
 */
public class GridPathSolver {

    private static final int INFINITY = 1_000_000_07;

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        PrintWriter out = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            Grid grid = new Grid(rows, cols, reader);

            // Perform BFS to find shortest distances from the starting point 'E'
            int[][] distances = calculateDistances(grid);

            int targetDist = distances[grid.targetX][grid.targetY];
            int totalSum = 0;

            // If the target 'S' is unreachable, the distance remains INFINITY.
            // We only sum digits in cells reachable within targetDist.
            if (targetDist != INFINITY) {
                for (int r = 0; r < grid.rows; r++) {
                    for (int c = 0; c < grid.cols; c++) {
                        char cellValue = grid.cells[r][c];
                        if (Character.isDigit(cellValue) && distances[r][c] <= targetDist) {
                            totalSum += Character.getNumericValue(cellValue);
                        }
                    }
                }
            }

            out.println(totalSum);

        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            out.close();
        }
    }

    /**
     * Represents the game grid and its metadata.
     */
    private static class Grid {
        final int rows;
        final int cols;
        final char[][] cells;
        int startX, startY; // Location of 'E'
        int targetX, targetY; // Location of 'S'

        Grid(int rows, int cols, FastReader reader) throws IOException {
            this.rows = rows;
            this.cols = cols;
            this.cells = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                String line = reader.readString();
                for (int j = 0; j < cols; j++) {
                    cells[i][j] = line.charAt(j);
                    if (cells[i][j] == 'E') {
                        startX = i;
                        startY = j;
                    } else if (cells[i][j] == 'S') {
                        targetX = i;
                        targetY = j;
                    }
                }
            }
        }
    }

    /**
     * Standard Breadth-First Search to calculate shortest distance from 'E' to all reachable cells.
     */
    private static int[][] calculateDistances(Grid grid) {
        int[][] dist = new int[grid.rows][grid.cols];
        for (int[] row : dist) {
            Arrays.fill(row, INFINITY);
        }

        Queue<Point> queue = new LinkedList<>();
        dist[grid.startX][grid.startY] = 0;
        queue.add(new Point(grid.startX, grid.startY));

        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            for (int i = 0; i < 4; i++) {
                int nr = current.r + dr[i];
                int nc = current.c + dc[i];

                if (isValidMove(grid, nr, nc) && dist[nr][nc] == INFINITY) {
                    dist[nr][nc] = dist[current.r][current.c] + 1;
                    queue.add(new Point(nr, nc));
                }
            }
        }
        return dist;
    }

    private static boolean isValidMove(Grid grid, int r, int c) {
        return r >= 0 && r < grid.rows && c >= 0 && c < grid.cols && grid.cells[r][c] != 'T';
    }

    private static class Point {
        final int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Optimized Fast I/O reader.
     */
    private static class FastReader {
        private final int BUFFER_SIZE = 1 << 16;
        private final DataInputStream din;
        private final byte[] buffer;
        private int bufferPointer, bytesRead;

        public FastReader() {
            this.din = new DataInputStream(System.in);
            this.buffer = new byte[BUFFER_SIZE];
            this.bufferPointer = bytesRead = 0;
        }

        public String readString() throws IOException {
            int c = read();
            while (isSpaceChar(c)) c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.append((char) c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public int nextInt() throws IOException {
            int ret = 0;
            byte c = read();
            while (c <= ' ') c = read();
            boolean neg = (c == '-');
            if (neg) c = read();
            do {
                ret = ret * 10 + c - '0';
            } while ((c = read()) >= '0' && c <= '9');
            return neg ? -ret : ret;
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        private void fillBuffer() throws IOException {
            bytesRead = din.read(buffer, bufferPointer = 0, BUFFER_SIZE);
            if (bytesRead == -1) buffer[0] = -1;
        }

        private byte read() throws IOException {
            if (bufferPointer == bytesRead) fillBuffer();
            return buffer[bufferPointer++];
        }

        public void close() throws IOException {
            din.close();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the Biridian Forest pathfinding problem.
 * The goal is to find the shortest path from an end point 'E' to a start point 'S'
 * and sum the values of all non-obstacle cells reachable within that shortest distance.
 */
public class Main {

    public static void main(String[] args) {
        FastReader input = new FastReader(System.in);
        PrintWriter output = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        BiridianForestSolver solver = new BiridianForestSolver(input);
        solver.solve(output);

        output.flush();
        output.close();
    }

    /**
     * Orchestrates the problem-solving process.
     */
    static class BiridianForestSolver {
        private final FastReader reader;

        public BiridianForestSolver(FastReader reader) {
            this.reader = reader;
        }

        public void solve(PrintWriter out) {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            if (rows <= 0 || cols <= 0) {
                out.println(0);
                return;
            }

            Grid grid = new Grid(rows, cols);
            Point startPoint = null;
            Point endPoint = null;

            // Parse the grid and identify start ('S') and end ('E') positions
            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                for (int j = 0; j < cols; j++) {
                    char cellChar = line.charAt(j);
                    if (cellChar == 'T') {
                        grid.setValue(i, j, -1); // Obstacle
                    } else if (cellChar == 'S') {
                        startPoint = new Point(i, j);
                        grid.setValue(i, j, 0);
                    } else if (cellChar == 'E') {
                        endPoint = new Point(i, j);
                        grid.setValue(i, j, 0);
                    } else {
                        grid.setValue(i, j, Character.getNumericValue(cellChar));
                    }
                }
            }

            if (startPoint == null || endPoint == null) {
                out.println(0);
                return;
            }

            // Calculate shortest distances from 'E' to all other reachable cells using BFS
            int[][] distanceMap = computeShortestDistances(grid, endPoint);

            int distanceToStart = distanceMap[startPoint.row][startPoint.col];

            // If 'S' is unreachable from 'E', the sum is 0
            if (distanceToStart == Integer.MAX_VALUE) {
                out.println(0);
                return;
            }

            // Calculate the sum of values of cells reachable within the shortest path distance to 'S'
            long totalSum = 0;
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    int cellValue = grid.getValue(i, j);
                    if (cellValue != -1 && distanceMap[i][j] <= distanceToStart) {
                        totalSum += cellValue;
                    }
                }
            }

            out.println(totalSum);
        }

        /**
         * Performs BFS to find the shortest distance from the source point to all reachable cells.
         */
        private int[][] computeShortestDistances(Grid grid, Point source) {
            int rows = grid.getRows();
            int cols = grid.getCols();
            int[][] distances = new int[rows][cols];

            for (int i = 0; i < rows; i++) {
                Arrays.fill(distances[i], Integer.MAX_VALUE);
            }

            Deque<Point> queue = new ArrayDeque<>();
            distances[source.row][source.col] = 0;
            queue.add(source);

            // Directional vectors for 4-way movement (Up, Down, Left, Right)
            int[] dRow = {1, -1, 0, 0};
            int[] dCol = {0, 0, 1, -1};

            while (!queue.isEmpty()) {
                Point current = queue.poll();

                for (int i = 0; i < 4; i++) {
                    int nextR = current.row + dRow[i];
                    int nextC = current.col + dCol[i];

                    if (grid.isValid(nextR, nextC) && grid.getValue(nextR, nextC) != -1) {
                        if (distances[nextR][nextC] == Integer.MAX_VALUE) {
                            distances[nextR][nextC] = distances[current.row][current.col] + 1;
                            queue.add(new Point(nextR, nextC));
                        }
                    }
                }
            }
            return distances;
        }
    }

    /**
     * Represents the grid map and provides access to its dimensions and values.
     */
    static class Grid {
        private final int rows;
        private final int cols;
        private final int[][] values;

        public Grid(int rows, int cols) {
            this.rows = rows;
            this.cols = cols;
            this.values = new int[rows][cols];
        }

        public void setValue(int r, int c, int val) {
            values[r][c] = val;
        }

        public int getValue(int r, int c) {
            return values[r][c];
        }

        public boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        public int getRows() { return rows; }
        public int getCols() { return cols; }
    }

    /**
     * A simple coordinate pair.
     */
    static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Utility class for fast input reading.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A solver that calculates the sum of all numeric values in a grid
 * that are reachable from the 'End' point within the distance 
 * required to reach the 'Start' point.
 */
public class MazeSumSolver {

    // Constants for grid cell types
    private static final char START_CHAR = 'S';
    private static final char END_CHAR = 'E';
    private static final char OBSTACLE_CHAR = 'T';

    /**
     * Represents a coordinate in the 2D grid.
     */
    private record Point(int row, int col) {}

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] grid = reader.readGrid(rows, cols);

            MazeSolver solver = new MazeSolver(grid, rows, cols);
            long result = solver.solve();

            out.println(result);
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        } finally {
            out.close();
        }
    }

    /**
     * Encapsulates the logic for traversing the maze and calculating the sum.
     */
    static class MazeSolver {
        private final char[][] grid;
        private final int rows;
        private final int cols;

        private Point startPos;
        private Point endPos;

        public MazeSolver(char[][] grid, int rows, int cols) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
            findSpecialPoints();
        }

        /**
         * Scans the grid to locate the 'S' (Start) and 'E' (End) positions.
         */
        private void findSpecialPoints() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == START_CHAR) {
                        startPos = new Point(i, j);
                    } else if (grid[i][j] == END_CHAR) {
                        endPos = new Point(i, j);
                    }
                }
            }
        }

        /**
         * Orchestrates the BFS and the summation calculation.
         * @return The sum of reachable numbers.
         */
        public long solve() {
            if (startPos == null || endPos == null) {
                return 0;
            }

            int[][] distanceMap = computeDistancesFromEnd();
            int distanceToStart = distanceMap[startPos.row()][startPos.col()];

            // If start is unreachable from end, return 0
            if (distanceToStart == -1) {
                return 0;
            }

            return calculateSumWithinDistance(distanceToStart, distanceMap);
        }

        /**
         * Performs a BFS starting from the 'End' point to find shortest paths to all cells.
         * @return A 2D array where each cell contains the distance from 'End', or -1 if unreachable.
         */
        private int[][] computeDistancesFromEnd() {
            int[][] distances = new int[rows][cols];
            for (int[] row : distances) {
                Arrays.fill(row, -1);
            }

            Queue<Point> queue = new LinkedList<>();

            distances[endPos.row()][endPos.col()] = 0;
            queue.add(endPos);

            int[] dr = {1, 0, -1, 0};
            int[] dc = {0, 1, 0, -1};

            while (!queue.isEmpty()) {
                Point current = queue.poll();

                for (int i = 0; i < 4; i++) {
                    int nextR = current.row() + dr[i];
                    int nextC = current.col() + dc[i];

                    if (isValidMove(nextR, nextC, distances)) {
                        distances[nextR][nextC] = distances[current.row()][current.col()] + 1;
                        queue.add(new Point(nextR, nextC));
                    }
                }
            }
            return distances;
        }

        private boolean isValidMove(int r, int c, int[][] distances) {
            return r >= 0 && r < rows && 
                   c >= 0 && c < cols && 
                   distances[r][c] == -1 && 
                   grid[r][c] != OBSTACLE_CHAR;
        }

        /**
         * Sums all digit characters in the grid that satisfy the distance constraint.
         */
        private long calculateSumWithinDistance(int maxDistance, int[][] distances) {
            long totalSum = 0;
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    char cell = grid[i][j];
                    if (Character.isDigit(cell)) {
                        int dist = distances[i][j];
                        if (dist != -1 && dist <= maxDistance) {
                            totalSum += Character.getNumericValue(cell);
                        }
                    }
                }
            }
            return totalSum;
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public char[][] readGrid(int rows, int cols) throws IOException {
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String rowString = next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = rowString.charAt(j);
                }
            }
            return grid;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * BattleMapGame calculates the sum of "battle" values (digits) on a map 
 * that are reachable from the start 'S' within the same distance it takes 
 * to reach the exit 'E'.
 */
public class BattleMapGame {

    // Constants for grid cell types
    private static final char START_CHAR = 'S';
    private static final char EXIT_CHAR = 'E';
    private static final char TRAP_CHAR = 'T';

    // Direction vectors for 4-connectivity (Up, Down, Left, Right)
    private static final int[][] DIRECTIONS = {
        {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    public static void main(String[] args) {
        try {
            if (args.length > 0 && args[0].equals("file")) {
                runFileMode();
            } else {
                runConsoleMode();
            }
        } catch (IOException e) {
            System.err.println("An error occurred during execution: " + e.getMessage());
        }
    }

    private static void runConsoleMode() throws IOException {
        try (FastReader in = new FastReader(System.in);
             PrintWriter out = new PrintWriter(new OutputStreamWriter(System.out))) {
            solve(in, out, new Logger(false));
        }
    }

    private static void runFileMode() throws IOException {
        File inputFile = new File("input.txt");
        if (!inputFile.exists()) {
            System.err.println("input.txt not found.");
            return;
        }

        try (FastReader in = new FastReader(new BufferedReader(new FileReader(inputFile)));
             PrintWriter out = new PrintWriter(new FileWriter("output.txt"))) {

            Logger debug = new Logger(true);
            int sampleNumber = 1;

            while (in.hasMore()) {
                String sampleHeader = "Sample #" + (sampleNumber++) + ": ";
                out.println(sampleHeader);
                debug.println(sampleHeader);

                solve(in, out, debug);

                out.println("");
                debug.println("");
            }
        }
    }

    /**
     * The core logic of the problem.
     */
    public static void solve(FastReader in, PrintWriter out, Logger logger) throws IOException {
        int rows = in.nextInt();
        int cols = in.nextInt();

        Grid grid = new Grid(rows, cols);
        for (int i = 0; i < rows; i++) {
            grid.setRow(i, in.next());
        }

        // Perform BFS starting from the Exit to find shortest paths to all reachable cells
        grid.computeDistancesFromExit();

        // Debugging output
        logger.printGridDistances(grid);

        int lenToExit = grid.getDistanceAt(grid.getStartPos());
        logger.println("LenToExit: " + lenToExit);

        // Calculate the sum of digits within the distance constraint
        long totalBattleCount = grid.calculateBattleSum(lenToExit);

        out.println(totalBattleCount);
    }

    /**
     * Represents the game board and its spatial logic.
     */
    static class Grid {
        private final int rows;
        private final int cols;
        private final char[][] map;
        private final int[][] distances;
        private int startR = -1, startC = -1;
        private int endR = -1, endC = -1;

        public Grid(int rows, int cols) {
            this.rows = rows;
            this.cols = cols;
            this.map = new char[rows][cols];
            this.distances = new int[rows][cols];
            for (int i = 0; i < rows; i++) {
                Arrays.fill(distances[i], -1);
            }
        }

        public void setRow(int r, String rowData) {
            for (int c = 0; c < cols; c++) {
                char ch = rowData.charAt(c);
                map[r][c] = ch;
                if (ch == START_CHAR) {
                    startR = r;
                    startC = c;
                } else if (ch == EXIT_CHAR) {
                    endR = r;
                    endC = c;
                }
            }
        }

        public void computeDistancesFromExit() {
            if (endR == -1) return;

            Queue<Cell> queue = new ArrayDeque<>();
            queue.add(new Cell(endR, endC));
            distances[endR][endC] = 0;

            while (!queue.isEmpty()) {
                Cell curr = queue.poll();

                for (int[] dir : DIRECTIONS) {
                    int nr = curr.r + dir[0];
                    int nc = curr.c + dir[1];

                    if (isValidMove(nr, nc)) {
                        distances[nr][nc] = distances[curr.r][curr.c] + 1;
                        queue.add(new Cell(nr, nc));
                    }
                }
            }
        }

        private boolean isValidMove(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols 
                && map[r][c] != TRAP_CHAR 
                && distances[r][c] == -1;
        }

        public long calculateBattleSum(int maxDist) {
            if (maxDist < 0) return 0;

            long sum = 0;
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    int d = distances[i][j];
                    if (d >= 0 && d <= maxDist && Character.isDigit(map[i][j])) {
                        sum += Character.getNumericValue(map[i][j]);
                    }
                }
            }
            return sum;
        }

        public int getDistanceAt(Cell cell) {
            if (cell == null) return -1;
            return distances[cell.r][cell.c];
        }

        public Cell getStartPos() {
            return (startR != -1) ? new Cell(startR, startC) : null;
        }

        public int getRows() { return rows; }
        public int getCols() { return cols; }
        public int[][] getDistances() { return distances; }
        public char[][] getMap() { return map; }
    }

    /**
     * Helper class to represent a coordinate in the grid.
     */
    static class Cell {
        final int r, c;
        Cell(int r, int c) { this.r = r; this.c = c; }
    }

    /**
     * Improved Fast I/O reader.
     */
    static class FastReader implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream is) {
            this(new BufferedReader(new InputStreamReader(is)));
        }

        public FastReader(Reader reader) {
            this.reader = new BufferedReader(reader);
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            String next = next();
            return next == null ? 0 : Integer.parseInt(next);
        }

        public boolean hasMore() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return false;
                tokenizer = new StringTokenizer(line);
            }
            return true;
        }

        @Override
        public void close() throws IOException {
            reader.close();
        }
    }

    /**
     * Encapsulates logging functionality.
     */
    static class Logger {
        private final boolean enabled;

        public Logger(boolean enabled) {
            this.enabled = enabled;
        }

        public void println(Object o) {
            if (enabled) System.out.println(o);
        }

        public void print(Object o) {
            if (enabled) System.out.print(o);
        }

        public void printGridDistances(Grid grid) {
            if (!enabled) return;
            int[][] dists = grid.getDistances();
            for (int i = 0; i < grid.getRows(); i++) {
                for (int j = 0; j < grid.getCols(); j++) {
                    if (dists[i][j] >= 0) {
                        print(dists[i][j] + " ");
                    } else {
                        print("* ");
                    }
                }
                println("");
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Queue;
import java.util.StringTokenizer;

/**
 * A solver that calculates the sum of digit values in a grid based on 
 * their proximity to an end point relative to a start point.
 */
public class GridPathSolver {

    private static final int[][] DIRECTIONS = {
        {0, 1}, {1, 0}, {0, -1}, {-1, 0}
    };

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int[][] distances;

    private Position startPos;
    private Position endPos;

    /**
     * Represents a coordinate in the grid.
     */
    private record Position(int r, int c) {}

    public GridPathSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.distances = new int[rows][cols];
        for (int[] row : distances) {
            Arrays.fill(row, -1);
        }
    }

    public void solve() {
        findSpecialPoints();
        if (startPos == null || endPos == null) {
            return;
        }

        performBFS();
        int result = calculateSum();
        System.out.println(result);
    }

    /**
     * Locates the 'S' (Start) and 'E' (End) positions in the grid.
     */
    private void findSpecialPoints() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 'S') {
                    startPos = new Position(r, c);
                } else if (grid[r][c] == 'E') {
                    endPos = new Position(r, c);
                }
            }
        }
    }

    /**
     * Performs a Breadth-First Search starting from the End position 
     * to find the shortest distance to all reachable cells.
     */
    private void performBFS() {
        Queue<Position> queue = new ArrayDeque<>();

        distances[endPos.r()][endPos.c()] = 0;
        queue.add(endPos);

        while (!queue.isEmpty()) {
            Position curr = queue.poll();

            for (int[] dir : DIRECTIONS) {
                int nextR = curr.r() + dir[0];
                int nextC = curr.c() + dir[1];

                if (isValidMove(nextR, nextC)) {
                    if (distances[nextR][nextC] == -1) {
                        distances[nextR][nextC] = distances[curr.r()][curr.c()] + 1;
                        queue.add(new Position(nextR, nextC));
                    }
                }
            }
        }
    }

    private boolean isValidMove(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols 
                && grid[r][c] != 'T';
    }

    /**
     * Sums up the digits of cells that are reachable and closer to 
     * the end than the start is.
     */
    private int calculateSum() {
        int sum = 0;
        int maxAllowedDist = distances[startPos.r()][startPos.c()];

        // If the start is unreachable, maxAllowedDist is -1
        if (maxAllowedDist == -1) {
            return 0;
        }

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (isEligibleForSum(r, c, maxAllowedDist)) {
                    sum += Character.getNumericValue(grid[r][c]);
                }
            }
        }
        return sum;
    }

    private boolean isEligibleForSum(int r, int c, int maxDist) {
        // Rule: Not the Start, Not the End, is reachable, and dist <= dist(Start, End)
        boolean isNotStart = (r != startPos.r() || c != startPos.c());
        boolean isNotEnd = (grid[r][c] != 'E');
        boolean isReachable = distances[r][c] != -1;
        boolean withinDistance = distances[r][c] <= maxDist;

        return isNotStart && isNotEnd && isReachable && withinDistance;
    }

    public static void main(String[] args) {
        FastReader sc = new FastReader();
        try {
            int r = sc.nextInt();
            int c = sc.nextInt();
            char[][] grid = new char[r][c];

            for (int i = 0; i < r; i++) {
                String line = sc.next();
                grid[i] = line.toCharArray();
            }

            GridPathSolver solver = new GridPathSolver(r, c, grid);
            solver.solve();
        } catch (Exception e) {
            // In a real production environment, use a proper Logger
            e.printStackTrace();
        }
    }

    /**
     * High-performance input reader.
     */
    static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A solver for the grid-based enemy proximity problem.
 * The goal is to find the sum of all enemy values that are closer to the 
 * Exit ('E') than the Player ('S') is to the Exit.
 */
public class Main {

    private static final char EXIT_CHAR = 'E';
    private static final char START_CHAR = 'S';
    private static final char TRAP_CHAR = 'T';
    private static final int UNREACHABLE = -1;

    private static final int[] ROW_OFFSETS = {1, -1, 0, 0};
    private static final int[] COL_OFFSETS = {0, 0, 1, -1};

    public static void main(String[] args) {
        new Main().run();
    }

    public void run() {
        FastReader reader = new FastReader(System.in);
        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            solve(rows, cols, grid);
        } catch (IOException | NoSuchElementException e) {
            // In a real-world scenario, use a logger. 
            // For competitive programming, we simply terminate.
        }
    }

    private void solve(int rows, int cols, char[][] grid) {
        int[][] distances = calculateDistancesFromExit(rows, cols, grid);

        int playerDistance = findPlayerDistance(rows, cols, grid, distances);
        int totalEnemyValue = calculateEnemySum(rows, cols, grid, distances, playerDistance);

        System.out.println(totalEnemyValue);
    }

    /**
     * Performs a Breadth-First Search starting from the Exit ('E') 
     * to find the shortest distance to all reachable cells.
     */
    private int[][] calculateDistancesFromExit(int rows, int cols, char[][] grid) {
        int[][] distances = new int[rows][cols];
        for (int[] row : distances) {
            Arrays.fill(row, UNREACHABLE);
        }

        Deque<Point> queue = new ArrayDeque<>();

        // Find the exit and initialize BFS
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == EXIT_CHAR) {
                    distances[r][c] = 0;
                    queue.add(new Point(r, c));
                }
            }
        }

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            for (int i = 0; i < 4; i++) {
                int nextR = current.row + ROW_OFFSETS[i];
                int nextC = current.col + COL_OFFSETS[i];

                if (isValidMove(nextR, nextC, rows, cols, grid) && distances[nextR][nextC] == UNREACHABLE) {
                    distances[nextR][nextC] = distances[current.row][current.col] + 1;
                    queue.add(new Point(nextR, nextC));
                }
            }
        }

        return distances;
    }

    private boolean isValidMove(int r, int c, int rows, int cols, char[][] grid) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] != TRAP_CHAR;
    }

    /**
     * Finds the distance from the Exit to the Player's starting position.
     */
    private int findPlayerDistance(int rows, int cols, char[][] grid, int[][] distances) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == START_CHAR) {
                    return distances[r][c];
                }
            }
        }
        return 0;
    }

    /**
     * Sums the values of enemies that are within the player's distance to the exit.
     */
    private int calculateEnemySum(int rows, int cols, char[][] grid, int[][] distances, int playerDistance) {
        int totalSum = 0;
        // If player is unreachable, playerDistance will be UNREACHABLE (-1).
        // Based on original logic, if playerDistance is -1, sum remains 0.
        if (playerDistance == UNREACHABLE) {
            return 0;
        }

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (isEnemyCell(grid[r][c])) {
                    int enemyValue = grid[r][c] - '0';
                    if (distances[r][c] != UNREACHABLE && distances[r][c] <= playerDistance) {
                        totalSum += enemyValue;
                    }
                }
            }
        }
        return totalSum;
    }

    private boolean isEnemyCell(char cell) {
        return cell != TRAP_CHAR && cell != EXIT_CHAR && cell != START_CHAR && Character.isDigit(cell);
    }

    /**
     * Helper class to represent a coordinate in the grid.
     */
    private static class Point {
