import java.io.*;
import java.util.*;

/**
 * GridPathSolver calculates the sum of values in a grid that are reachable 
 * within a certain distance threshold from a designated end point.
 */
public class GridPathSolver {

    // Constants for grid cell types
    private static final int WALL = -1;
    private static final int START_CELL_MARKER = 11;
    private static final int END_CELL_MARKER = 0;
    private static final int UNREACHABLE = Integer.MAX_VALUE;

    // Movement vectors for 4-directional movement (Up, Down, Left, Right)
    private static final int[][] DIRECTIONS = {
        {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    /**
     * Represents a coordinate in the 2D grid.
     */
    private record Point(int row, int col) {}

    /**
     * Utility class for fast I/O operations.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) {
        try {
            new GridPathSolver().solve();
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    public void solve() throws IOException {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out, true);

        int rows = reader.nextInt();
        int cols = reader.nextInt();

        int[][] grid = new int[rows][cols];
        Point startPos = null;
        Point endPos = null;

        // Parse the grid and locate special cells
        for (int i = 0; i < rows; i++) {
            String line = reader.next();
            for (int j = 0; j < cols; j++) {
                char c = line.charAt(j);
                if (c == 'T') {
                    grid[i][j] = WALL;
                } else if (c == 'S') {
                    grid[i][j] = START_CELL_MARKER;
                    startPos = new Point(i, j);
                } else if (c == 'E') {
                    grid[i][j] = END_CELL_MARKER;
                    endPos = new Point(i, j);
                } else {
                    grid[i][j] = Character.getNumericValue(c);
                }
            }
        }

        if (endPos == null || startPos == null) {
            out.println(0);
            return;
        }

        // Compute distances from the end point to all other cells
        int[][] distances = computeDistances(grid, endPos, rows, cols);

        // Calculate the result based on the problem requirements
        int totalSum = calculateTargetSum(grid, distances, startPos);
        out.println(totalSum);
    }

    /**
     * Standard Breadth-First Search to find the shortest path from a starting point 
     * to all reachable cells in the grid.
     */
    private int[][] computeDistances(int[][] grid, Point start, int rows, int cols) {
        int[][] distances = new int[rows][cols];
        for (int[] row : distances) {
            Arrays.fill(row, UNREACHABLE);
        }

        boolean[][] visited = new boolean[rows][cols];
        Queue<Point> queue = new ArrayDeque<>();

        distances[start.row()][start.col()] = 0;
        visited[start.row()][start.col()] = true;
        queue.add(start);

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            for (int[] dir : DIRECTIONS) {
                int nextR = current.row() + dir[0];
                int nextC = current.col() + dir[1];

                if (isValidMove(nextR, nextC, rows, cols, grid, visited)) {
                    visited[nextR][nextC] = true;
                    distances[nextR][nextC] = distances[current.row()][current.col()] + 1;
                    queue.add(new Point(nextR, nextC));
                }
            }
        }
        return distances;
    }

    private boolean isValidMove(int r, int c, int rows, int cols, int[][] grid, boolean[][] visited) {
        return r >= 0 && r < rows && 
               c >= 0 && c < cols && 
               grid[r][c] != WALL && 
               !visited[r][c];
    }

    /**
     * Sums up the values of cells whose distance from 'E' is <= the distance from 'E' to 'S'.
     */
    private int calculateTargetSum(int[][] grid, int[][] distances, Point startPos) {
        int sum = 0;
        int distToStart = distances[startPos.row()][startPos.col()];

        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[0].length; j++) {
                int val = grid[i][j];

                // Based on original logic: consider only digits 1-9
                if (val > 0 && val < 10) {
                    if (distances[i][j] <= distToStart) {
                        sum += val;
                    }
                }
            }
        }
        return sum;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.StringTokenizer;

/**
 * MazeSolver finds the sum of all digits located on any shortest path 
 * between the start ('S') and end ('E') points in a grid.
 */
public class MazeSolver {

    private static final int[] DR = {0, 0, 1, -1};
    private static final int[] DC = {1, -1, 0, 0};
    private static final char WALL = 'T';
    private static final char START = 'S';
    private static final char END = 'E';

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] grid = new char[rows][cols];

            int startR = -1, startC = -1;
            int endR = -1, endC = -1;

            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                grid[i] = line.toCharArray();
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == START) {
                        startR = i;
                        startC = j;
                    } else if (grid[i][j] == END) {
                        endR = i;
                        endC = j;
                    }
                }
            }

            if (startR == -1 || endR == -1) {
                System.out.println(0);
                return;
            }

            MazeSolver solver = new MazeSolver();
            long result = solver.solve(grid, rows, cols, startR, startC, endR, endC);
            System.out.println(result);

        } catch (Exception e) {
            // In a production environment, use a logger
            e.printStackTrace();
        }
    }

    /**
     * Solves the maze using a two-way BFS to identify all cells on any shortest path.
     */
    public long solve(char[][] grid, int rows, int cols, int startR, int startC, int endR, int endC) {
        int[][] distFromStart = computeDistanceMap(grid, rows, cols, startR, startC);
        int[][] distFromEnd = computeDistanceMap(grid, rows, cols, endR, endC);

        int shortestDistance = distFromStart[endR][endC];

        // If end is unreachable
        if (shortestDistance == Integer.MAX_VALUE) {
            return 0;
        }

        long digitSum = 0;

        // A cell is on a shortest path if:
        // distFromStart[r][c] + distFromEnd[r][c] == shortestDistance
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (distFromStart[r][c] != Integer.MAX_VALUE && 
                    distFromEnd[r][c] != Integer.MAX_VALUE &&
                    distFromStart[r][c] + distFromEnd[r][c] == shortestDistance) {

                    if (Character.isDigit(grid[r][c])) {
                        digitSum += (grid[r][c] - '0');
                    }
                }
            }
        }

        return digitSum;
    }

    /**
     * Standard BFS to compute shortest distance from a source to all reachable cells.
     */
    private int[][] computeDistanceMap(char[][] grid, int rows, int cols, int startR, int startC) {
        int[][] distances = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                distances[i][j] = Integer.MAX_VALUE;
            }
        }

        Deque<Node> queue = new ArrayDeque<>();
        distances[startR][startC] = 0;
        queue.offer(new Node(startR, startC));

        while (!queue.isEmpty()) {
            Node current = queue.poll();

            for (int i = 0; i < 4; i++) {
                int nr = current.r + DR[i];
                int nc = current.c + DC[i];

                if (isValidMove(grid, rows, cols, nr, nc) && distances[nr][nc] == Integer.MAX_VALUE) {
                    distances[nr][nc] = distances[current.r][current.c] + 1;
                    queue.offer(new Node(nr, nc));
                }
            }
        }

        return distances;
    }

    private boolean isValidMove(char[][] grid, int rows, int cols, int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] != WALL;
    }

    /**
     * Immutable representation of a cell in the grid.
     */
    private static class Node {
        final int r, c;

        Node(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Optimized input reader for high-performance I/O.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader() {
            this.reader = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

