/**
 * ProblemB Solver
 * Finds the sum of digits in grid cells that are within a certain distance 
 * from the nearest 'E' (End) cells, where that distance is no greater than 
 * the distance from the 'S' (Start) cell to the nearest 'E' cell.
 */
public class ProblemB {

    public static void main(String[] args) {
        try {
            GridSolver solver = new GridSolver(new FastReader(System.in));
            solver.solve();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /**
     * Represents a coordinate on the grid.
     */
    private static class Cell {
        final int row;
        final int col;

        Cell(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Encapsulates the core logic of the grid problem.
     */
    private static class GridSolver {
        private final FastReader reader;
        private final PrintWriter writer;

        private static final int INF = 1 << 20;
        private static final int[] ROW_DIRECTIONS = {-1, 1, 0, 0};
        private static final int[] COL_DIRECTIONS = {0, 0, -1, 1};

        public GridSolver(FastReader reader) {
            this.reader = reader;
            this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
        }

        public void solve() throws IOException {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            char[][] grid = new char[rows][cols];
            int[][] minDistances = new int[rows][cols];
            Queue<Cell> queue = new ArrayDeque<>();

            int startRow = -1;
            int startCol = -1;

            // Initialize distances and find Start/End positions
            for (int r = 0; r < rows; r++) {
                String line = reader.next();
                grid[r] = line.toCharArray();
                for (int c = 0; c < cols; c++) {
                    minDistances[r][c] = INF;
                    if (grid[r][c] == 'E') {
                        minDistances[r][c] = 0;
                        queue.add(new Cell(r, c));
                    } else if (grid[r][c] == 'S') {
                        startRow = r;
                        startCol = c;
                    }
                }
            }

            // Multi-source BFS to find shortest distance from any 'E' to all cells
            performBFS(grid, minDistances, queue, rows, cols);

            // Calculate the result
            int totalScore = calculateScore(grid, minDistances, startRow, startCol, rows, cols);

            writer.println(totalScore);
            writer.flush();
        }

        private void performBFS(char[][] grid, int[][] dist, Queue<Cell> queue, int rows, int cols) {
            while (!queue.isEmpty()) {
                Cell current = queue.poll();

                for (int i = 0; i < 4; i++) {
                    int nextR = current.row + ROW_DIRECTIONS[i];
                    int nextC = current.col + COL_DIRECTIONS[i];

                    if (isValidMove(nextR, nextC, rows, cols, grid) && dist[nextR][nextC] > dist[current.row][current.col] + 1) {
                        dist[nextR][nextC] = dist[current.row][current.col] + 1;
                        queue.add(new Cell(nextR, nextC));
                    }
                }
            }
        }

        private boolean isValidMove(int r, int c, int rows, int cols, char[][] grid) {
            return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] != 'T';
        }

        private int calculateScore(char[][] grid, int[][] dist, int startR, int startC, int rows, int cols) {
            int thresholdDistance = dist[startR][startC];
            int score = 0;

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    char cellVal = grid[r][c];
                    if (isDigit(cellVal) && dist[r][c] <= thresholdDistance) {
                        score += (cellVal - '0');
                    }
                }
            }
            return score;
        }

        private boolean isDigit(char c) {
            return c >= '0' && c <= '9';
        }
    }

    /**
     * High-performance input reader.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            this.reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }
    }
}

import java.util.*;

/**
 * GridResourceCalculator solves the problem of calculating total collectable resources 
 * in a grid. A resource is collectable if the distance from the end point to the 
 * resource cell is less than or equal to the distance from the end point to the start point.
 */
public class GridResourceCalculator {

    /**
     * Represents a coordinate on the grid.
     */
    private record Point(int row, int col) {}

    /**
     * Encapsulates the grid state and metadata.
     */
    private record GridContext(
            int[][] gridValues,
            Point startPoint,
            Point endPoint,
            int rows,
            int cols
    ) {}

    private static final int OBSTACLE = -1;
    private static final int[][] DIRECTIONS = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int numRows = scanner.nextInt();
        int numCols = scanner.nextInt();

        try {
            GridContext context = parseGrid(scanner, numRows, numCols);
            int totalResources = calculateTotalResources(context);
            System.out.println(totalResources);
        } catch (Exception e) {
            System.err.println("Error processing grid: " + e.getMessage());
        } finally {
            scanner.close();
        }
    }

    /**
     * Parses the input stream into a structured GridContext.
     */
    private static GridContext parseGrid(Scanner scanner, int rows, int cols) {
        int[][] gridValues = new int[rows][cols];
        Point startPoint = null;
        Point endPoint = null;

        for (int r = 0; r < rows; r++) {
            String rowString = scanner.next();
            for (int c = 0; c < cols; c++) {
                char cellChar = rowString.charAt(c);

                if (Character.isDigit(cellChar)) {
                    gridValues[r][c] = cellChar - '0';
                } else if (cellChar == 'T') {
                    gridValues[r][c] = OBSTACLE;
                } else if (cellChar == 'E') {
                    endPoint = new Point(r, c);
                    gridValues[r][c] = 0;
                } else {
                    // Any non-digit, non-obstacle, non-end character is treated as the start point.
                    startPoint = new Point(r, c);
                    gridValues[r][c] = 0;
                }
            }
        }

        return new GridContext(gridValues, startPoint, endPoint, rows, cols);
    }

    /**
     * Calculates the sum of resources that meet the distance criteria.
     */
    private static int calculateTotalResources(GridContext context) {
        int[][] distancesFromEnd = computeDistancesFromEnd(context);

        int startDistFromEnd = Integer.MAX_VALUE;
        if (context.startPoint != null) {
            startDistFromEnd = distancesFromEnd[context.startPoint.row()][context.startPoint.col()];
        }

        int totalResources = 0;
        for (int r = 0; r < context.rows; r++) {
            for (int c = 0; c < context.cols; c++) {
                int cellValue = context.gridValues[r][c];
                int distToCellFromEnd = distancesFromEnd[r][c];

                // Logic: Collect resource if cell has value > 0 and distance requirement is met.
                // Note: if start is unreachable, startDistFromEnd is Integer.MAX_VALUE.
                if (cellValue > 0 && startDistFromEnd >= distToCellFromEnd) {
                    totalResources += cellValue;
                }
            }
        }

        return totalResources;
    }

    /**
     * Uses Breadth-First Search to calculate the shortest distance from the 
     * end point to all reachable cells in the grid.
     */
    private static int[][] computeDistancesFromEnd(GridContext context) {
        int[][] distances = new int[context.rows][context.cols];
        for (int[] row : distances) {
            Arrays.fill(row, Integer.MAX_VALUE);
        }

        if (context.endPoint == null) {
            return distances;
        }

        Queue<Point> queue = new LinkedList<>();
        queue.add(context.endPoint);
        distances[context.endPoint.row()][context.endPoint.col()] = 0;

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            for (int[] dir : DIRECTIONS) {
                int nextRow = current.row() + dir[0];
                int nextCol = current.col() + dir[1];

                if (isTraversable(nextRow, nextCol, context, distances)) {
                    distances[nextRow][nextCol] = distances[current.row()][current.col()] + 1;
                    queue.add(new Point(nextRow, nextCol));
                }
            }
        }

        return distances;
    }

    /**
     * Validates if a coordinate is within bounds, is not an obstacle, and hasn't been visited.
     */
    private static boolean isTraversable(int r, int c, GridContext context, int[][] distances) {
        return r >= 0 && r < context.rows && 
               c >= 0 && c < context.cols && 
               context.gridValues[r][c] != OBSTACLE && 
               distances[r][c] == Integer.MAX_VALUE;
    }
}

