/**
 * Represents a coordinate in the 2D grid.
 */
record Point(int row, int col) {}

/**
 * Solves the grid problem: Find the sum of digits in cells reachable 
 * within the time it takes to reach the target 'S' from any exit 'E'.
 */
class GridPathSolver {
    private static final char EXIT_CHAR = 'E';
    private static final char TARGET_CHAR = 'S';
    private static final char TRAP_CHAR = 'T';

    private static final int[] ROW_DIRECTIONS = {1, 0, -1, 0};
    private static final int[] COL_DIRECTIONS = {0, 1, 0, -1};

    private final FastReader reader;

    public GridPathSolver(FastReader reader) {
        this.reader = reader;
    }

    public void solve(PrintWriter out) throws IOException {
        int rows = reader.nextInt();
        int cols = reader.nextInt();
        char[][] grid = reader.readGrid(rows, cols);

        int[][] distances = computeShortestDistances(grid, rows, cols);
        int targetDistance = findTargetDistance(grid, distances, rows, cols);

        if (targetDistance == Integer.MAX_VALUE) {
            out.println("-1");
        } else {
            out.println(calculateScore(grid, distances, targetDistance, rows, cols));
        }
    }

    /**
     * Performs a Multi-Source Breadth-First Search (BFS) starting from all 'E' cells.
     */
    private int[][] computeShortestDistances(char[][] grid, int rows, int cols) {
        int[][] distances = new int[rows][cols];
        for (int[] row : distances) {
            Arrays.fill(row, Integer.MAX_VALUE);
        }

        Deque<Point> queue = new ArrayDeque<>();

        // Initialize BFS with all exit points
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == EXIT_CHAR) {
                    distances[r][c] = 0;
                    queue.add(new Point(r, c));
                }
            }
        }

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            for (int i = 0; i < 4; i++) {
                int nextR = current.row() + ROW_DIRECTIONS[i];
                int nextC = current.col() + COL_DIRECTIONS[i];

                if (isValidMove(grid, nextR, nextC, rows, cols, distances)) {
                    distances[nextR][nextC] = distances[current.row()][current.col()] + 1;
                    queue.add(new Point(nextR, nextC));
                }
            }
        }
        return distances;
    }

    private boolean isValidMove(char[][] grid, int r, int c, int rows, int cols, int[][] distances) {
        return r >= 0 && r < rows && 
               c >= 0 && c < cols && 
               grid[r][c] != TRAP_CHAR && 
               distances[r][c] == Integer.MAX_VALUE;
    }

    /**
     * Finds the distance to the 'S' (Target) cell.
     */
    private int findTargetDistance(char[][] grid, int[][] distances, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == TARGET_CHAR) {
                    return distances[r][c];
                }
            }
        }
        return Integer.MAX_VALUE;
    }

    /**
     * Calculates the sum of numeric digits reachable within the target distance.
     */
    private long calculateScore(char[][] grid, int[][] distances, int targetDistance, int rows, int cols) {
        long score = 0;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (Character.isDigit(grid[r][c]) && distances[r][c] <= targetDistance) {
                    score += Character.getNumericValue(grid[r][c]);
                }
            }
        }
        return score;
    }
}

