/**
 * Represents a coordinate on the 2D grid.
 */
record Position(int row, int col) {}

/**
 * Manages the grid data and provides utility methods for traversal.
 */
class Grid {
    private final char[][] cells;
    private final int rows;
    private final int cols;

    public Grid(char[][] cells) {
        this.cells = cells;
        this.rows = cells.length;
        this.cols = cells[0].length;
    }

    public int getRows() { return rows; }
    public int getCols() { return cols; }

    public char getCharAt(int r, int c) {
        return cells[r][c];
    }

    public boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    public boolean isTraversable(int r, int c) {
        return isValid(r, c) && cells[r][c] != 'T';
    }

    public boolean isDigit(int r, int c) {
        char ch = cells[r][c];
        return ch >= '0' && ch <= '9';
    }

    public int getDigitValue(int r, int c) {
        return Character.getNumericValue(cells[r][c]);
    }

    public List<Position> findPositionsByChar(char target) {
        List<Position> positions = new ArrayList<>();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (cells[r][c] == target) {
                    positions.add(new Position(r, c));
                }
            }
        }
        return positions;
    }
}

/**
 * Contains the logic for solving the Biridian puzzle.
 */
class BiridianSolver {
    private static final int INF = 1_000_000_000;
    private static final int[][] DIRECTIONS = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

    private final Grid grid;

    public BiridianSolver(Grid grid) {
        this.grid = grid;
    }

    /**
     * Solves the puzzle and returns the total collected value.
     */
    public int solve() {
        int[][] distanceMap = computeDistancesFromExits();

        // Find the player's starting position 'S'
        List<Position> startPositions = grid.findPositionsByChar('S');
        if (startPositions.isEmpty()) {
            return 0;
        }

        Position startPos = startPositions.get(0);
        int playerMaxMoves = distanceMap[startPos.row()][startPos.col()];

        // If 'S' cannot reach any 'E', playerMaxMoves will be INF
        if (playerMaxMoves >= INF) {
            return 0;
        }

        return calculateScore(distanceMap, playerMaxMoves);
    }

    /**
     * Performs BFS starting from all 'E' (Exit) cells to calculate 
     * shortest distance from every cell to the nearest exit.
     */
    private int[][] computeDistancesFromExits() {
        int rows = grid.getRows();
        int cols = grid.getCols();
        int[][] distances = new int[rows][cols];

        for (int[] row : distances) {
            Arrays.fill(row, INF);
        }

        Queue<Position> queue = new LinkedList<>();
        List<Position> exits = grid.findPositionsByChar('E');

        for (Position exit : exits) {
            distances[exit.row()][exit.col()] = 0;
            queue.add(exit);
        }

        while (!queue.isEmpty()) {
            Position current = queue.poll();

            for (int[] dir : DIRECTIONS) {
                int nextR = current.row() + dir[0];
                int nextC = current.col() + dir[1];

                if (grid.isTraversable(nextR, nextC) && distances[nextR][nextC] == INF) {
                    distances[nextR][nextC] = distances[current.row()][current.col()] + 1;
                    queue.add(new Position(nextR, nextC));
                }
            }
        }

        return distances;
    }

    /**
     * Sums up digits that are reachable within the player's move limit.
     */
    private int calculateScore(int[][] distanceMap, int maxMoves) {
        int totalScore = 0;
        for (int r = 0; r < grid.getRows(); r++) {
            for (int c = 0; c < grid.getCols(); c++) {
                if (grid.isDigit(r, c)) {
                    if (distanceMap[r][c] <= maxMoves) {
                        totalScore += grid.getDigitValue(r, c);
                    }
                }
            }
        }
        return totalScore;
    }
}

public class Biridian {

    public static void main(String[] args) {
        try {
            Grid grid = parseInput();
            if (grid == null) return;

            BiridianSolver solver = new BiridianSolver(grid);
            System.out.println(solver.solve());
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    private static Grid parseInput() throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String line = reader.readLine();
        if (line == null) return null;

        String[] dims = line.trim().split("\\s+");
        int R = Integer.parseInt(dims[0]);
        int C = Integer.parseInt(dims[1]);

        char[][] gridData = new char[R][C];
        for (int i = 0; i < R; i++) {
            String rowStr = reader.readLine();
            if (rowStr == null) break;
            gridData[i] = rowStr.toCharArray();
        }

        return new Grid(gridData);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Queue;
import java.util.StringTokenizer;

/**
 * BiridianForest calculates the sum of digits in a grid that are reachable 
 * within the shortest distance from the starting point to the end point.
 */
public class BiridianForest {

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        try {
            ForestSolver solver = new ForestSolver(reader);
            solver.solve();
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Represents a coordinate in the grid.
     */
    static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Handles the logic of parsing the forest and calculating the required sum.
     */
    static class ForestSolver {
        private final FastReader reader;
        private int rows;
        private int cols;
        private char[][] grid;
        private int[][] distances;
        private Point startPoint;
        private Point endPoint;

        private static final int[] ROW_OFFSETS = {-1, 1, 0, 0};
        private static final int[] COL_OFFSETS = {0, 0, -1, 1};
        private static final int INF = Integer.MAX_VALUE;

        public ForestSolver(FastReader reader) {
            this.reader = reader;
        }

        public void solve() throws IOException {
            parseInput();
            performBreadthFirstSearch();
            int result = calculateDigitSum();
            System.out.println(result);
        }

        private void parseInput() throws IOException {
            String firstLine = reader.readLine();
            if (firstLine == null) return;

            StringTokenizer st = new StringTokenizer(firstLine);
            rows = Integer.parseInt(st.nextToken());
            cols = Integer.parseInt(st.nextToken());

            grid = new char[rows][cols];
            distances = new int[rows][cols];

            for (int r = 0; r < rows; r++) {
                String line = reader.readLine();
                for (int c = 0; c < cols; c++) {
                    grid[r][c] = line.charAt(c);
                    distances[r][c] = INF;

                    if (grid[r][c] == 'S') {
                        startPoint = new Point(r, c);
                    } else if (grid[r][c] == 'E') {
                        endPoint = new Point(r, c);
                    }
                }
            }
        }

        /**
         * Performs BFS starting from the End point ('E') to find the 
         * shortest distance to all other reachable cells.
         */
        private void performBreadthFirstSearch() {
            if (endPoint == null) return;

            Queue<Point> queue = new ArrayDeque<>();
            distances[endPoint.row][endPoint.col] = 0;
            queue.add(endPoint);

            while (!queue.isEmpty()) {
                Point current = queue.poll();

                for (int i = 0; i < 4; i++) {
                    int nextRow = current.row + ROW_OFFSETS[i];
                    int nextCol = current.col + COL_OFFSETS[i];

                    if (isValidMove(nextRow, nextCol)) {
                        if (distances[nextRow][nextCol] == INF) {
                            distances[nextRow][nextCol] = distances[current.row][current.col] + 1;
                            queue.add(new Point(nextRow, nextCol));
                        }
                    }
                }
            }
        }

        private boolean isValidMove(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols 
                    && grid[r][c] != 'T';
        }

        /**
         * Sums the digits of all cells whose distance from 'E' is less than 
         * or equal to the distance from 'E' to 'S'.
         */
        private int calculateDigitSum() {
            if (startPoint == null || endPoint == null) return 0;

            int threshold = distances[startPoint.row][startPoint.col];
            int sum = 0;

            // If start is unreachable, threshold remains INF, which is acceptable 
            // based on original logic.
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    char cell = grid[r][c];
                    if (cell != 'S' && cell != 'E' && Character.isDigit(cell)) {
                        if (distances[r][c] <= threshold) {
                            sum += Character.getNumericValue(cell);
                        }
                    }
                }
            }
            return sum;
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String readLine() throws IOException {
            return br.readLine();
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;

/**
 * ForestPathfinder calculates the sum of numeric values in a grid that are 
 * reachable within the same distance required to reach a specific target cell 'S'.
 */
public class ForestPathfinder {

    // Constants representing specific cell types in the forest
    private static final char START_NODE = 'E';
    private static final char TARGET_NODE = 'S';
    private static final char OBSTACLE = 'T';

    // Direction vectors for 4-way movement (Down, Up, Right, Left)
    private static final int[] ROW_DIRECTIONS = {1, -1, 0, 0};
    private static final int[] COL_DIRECTIONS = {0, 0, 1, -1};

    /**
     * Represents a single point in the 2D grid.
     */
    private static class Coordinate {
        final int row;
        final int col;

        Coordinate(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] grid = new char[rows][cols];
        Coordinate startCoord = null;

        // Parse the grid and identify the starting position 'E'
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] == START_NODE) {
                    startCoord = new Coordinate(i, j);
                }
            }
        }

        if (startCoord == null) {
            System.out.println(0);
            return;
        }

        long result = solve(grid, rows, cols, startCoord);
        System.out.println(result);

        scanner.close();
    }

    /**
     * Orchestrates the BFS and the calculation of the final result.
     * 
     * @return The sum of values within the target distance.
     */
    private static long solve(char[][] grid, int rows, int cols, Coordinate start) {
        int[][] distances = computeDistances(grid, rows, cols, start);
        int maxAllowedDistance = findTargetDistance(grid, rows, cols, distances);

        // If the target 'S' is unreachable, the sum is 0
        if (maxAllowedDistance == -1) {
            return 0;
        }

        return calculateValueSum(grid, rows, cols, distances, maxAllowedDistance);
    }

    /**
     * Uses Breadth-First Search to find the shortest distance from the start 
     * point to all other reachable cells in the grid.
     */
    private static int[][] computeDistances(char[][] grid, int rows, int cols, Coordinate start) {
        int[][] distances = new int[rows][cols];
        for (int[] row : distances) {
            Arrays.fill(row, Integer.MAX_VALUE);
        }

        Queue<Coordinate> queue = new ArrayDeque<>();
        queue.add(start);
        distances[start.row][start.col] = 0;

        while (!queue.isEmpty()) {
            Coordinate current = queue.poll();

            for (int i = 0; i < 4; i++) {
                int nextRow = current.row + ROW_DIRECTIONS[i];
                int nextCol = current.col + COL_DIRECTIONS[i];

                if (isValidMove(grid, rows, cols, nextRow, nextCol, distances)) {
                    distances[nextRow][nextCol] = distances[current.row][current.col] + 1;
                    queue.add(new Coordinate(nextRow, nextCol));
                }
            }
        }
        return distances;
    }

    /**
     * Checks if a neighbor cell is within bounds, not an obstacle, and not yet visited.
     */
    private static boolean isValidMove(char[][] grid, int rows, int cols, int r, int c, int[][] distances) {
        return r >= 0 && r < rows && 
               c >= 0 && c < cols && 
               grid[r][c] != OBSTACLE && 
               distances[r][c] == Integer.MAX_VALUE;
    }

    /**
     * Finds the distance from the start node to the target node 'S'.
     */
    private static int findTargetDistance(char[][] grid, int rows, int cols, int[][] distances) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == TARGET_NODE) {
                    int dist = distances[i][j];
                    return (dist == Integer.MAX_VALUE) ? -1 : dist;
                }
            }
        }
        return -1;
    }

    /**
     * Sums the values of all digit-based cells that fall within the allowed distance.
     */
    private static long calculateValueSum(char[][] grid, int rows, int cols, int[][] distances, int maxDist) {
        long sum = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                char cellValue = grid[i][j];
                if (Character.isDigit(cellValue) && distances[i][j] <= maxDist) {
                    sum += Character.getNumericValue(cellValue);
                }
            }
        }
        return sum;
    }
}

