/**
 * Represents a coordinate in the 2D grid.
 */
record Point(int row, int col) {}

/**
 * Encapsulates the forest grid and its properties.
 */
class ForestMap {
    public static final char START_CHAR = 'S';
    public static final char END_CHAR = 'E';
    public static final char OBSTACLE_CHAR = 'T';

    private final int height;
    private final int width;
    private final char[][] grid;
    private Point startPoint;
    private Point endPoint;

    public ForestMap(int height, int width, char[][] grid) {
        this.height = height;
        this.width = width;
        this.grid = grid;
        findSpecialPoints();
    }

    private void findSpecialPoints() {
        for (int r = 0; r < height; r++) {
            for (int c = 0; c < width; c++) {
                if (grid[r][c] == START_CHAR) {
                    startPoint = new Point(r, c);
                } else if (grid[r][c] == END_CHAR) {
                    endPoint = new Point(r, c);
                }
            }
        }
    }

    public boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < height && c >= 0 && c < width;
    }

    public boolean isObstacle(int r, int c) {
        return grid[r][c] == OBSTACLE_CHAR;
    }

    public boolean isDigit(int r, int c) {
        char val = grid[r][c];
        return val >= '0' && val <= '9';
    }

    public int getDigitValue(int r, int c) {
        return grid[r][c] - '0';
    }

    public int getHeight() { return height; }
    public int getWidth() { return width; }
    public Point getStartPoint() { return startPoint; }
    public Point getEndPoint() { return endPoint; }
}

/**
 * Handles pathfinding logic using Breadth-First Search.
 */
class DistanceCalculator {
    private static final int[][] DIRECTIONS = {
        {0, 1}, {0, -1}, {1, 0}, {-1, 0}
    };

    /**
     * Computes shortest distances from a target point to all reachable cells.
     * @return A 2D array where dist[r][c] is the distance, or -1 if unreachable.
     */
    public int[][] computeDistances(ForestMap forest, Point target) {
        int[][] distances = new int[forest.getHeight()][forest.getWidth()];
        for (int[] row : distances) {
            Arrays.fill(row, -1);
        }

        Queue<Point> queue = new ArrayDeque<>();
        distances[target.row()][target.col()] = 0;
        queue.add(target);

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            for (int[] dir : DIRECTIONS) {
                int nextR = current.row() + dir[0];
                int nextC = current.col() + dir[1];

                if (forest.isWithinBounds(nextR, nextC) 
                        && !forest.isObstacle(nextR, nextC) 
                        && distances[nextR][nextC] == -1) {

                    distances[nextR][nextC] = distances[current.row()][current.col()] + 1;
                    queue.add(new Point(nextR, nextC));
                }
            }
        }
        return distances;
    }
}

/**
 * Orchestrates the solving of the forest problem.
 */
class ForestSolver {
    private final DistanceCalculator distanceCalculator = new DistanceCalculator();

    public void solve(FastReader in, FastWriter out) throws IOException {
        int height = in.nextInt();
        int width = in.nextInt();
        char[][] grid = in.next2DCharArray(height, width);

        ForestMap forest = new ForestMap(height, width, grid);

        // Calculate distances starting from the End point ('E')
        int[][] distMap = distanceCalculator.computeDistances(forest, forest.getEndPoint());

        int distanceToStart = distMap[forest.getStartPoint().row()][forest.getStartPoint().col()];
        int totalDigitSum = 0;

        // If the End point is unreachable from Start, distanceToStart will be -1.
        // The problem logic implies we sum digits within distance <= distanceToStart.
        if (distanceToStart != -1) {
            for (int r = 0; r < forest.getHeight(); r++) {
                for (int c = 0; c < forest.getWidth(); c++) {
                    int d = distMap[r][c];
                    if (d != -1 && d <= distanceToStart && forest.isDigit(r, c)) {
                        totalDigitSum += forest.getDigitValue(r, c);
                    }
                }
            }
        }

        out.println(totalDigitSum);
    }
}

/**
 * Optimized input reader for faster execution.
 */
class FastReader implements AutoCloseable {
    private final InputStream stream;
    private final byte[] buffer = new byte[1 << 16];
    private int curChar;
    private int numChars;

    public FastReader(InputStream stream) {
        this.stream = stream;
    }

    private int read() throws IOException {
        if (numChars == -1) throw new EOFException();
        if (curChar >= numChars) {
            curChar = 0;
            numChars = stream.read(buffer);
            if (numChars <= 0) return -1;
        }
        return buffer[curChar++];
    }

    public int nextInt() throws IOException {
        int c = read();
        while (isSpaceChar(c)) c = read();
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        int res = 0;
        do {
            if (c < '0' || c > '9') throw new InputMismatchException();
            res = res * 10 + (c - '0');
            c = read();
        } while (!isSpaceChar(c));
        return res * sgn;
    }

    public char[][] next2DCharArray(int rows, int cols) throws IOException {
        char[][] result = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                result[i][j] = nextChar();
            }
        }
        return result;
    }

    private char nextChar() throws IOException {
        int c = read();
        while (isSpaceChar(c)) c = read();
        return (char) c;
    }

    private boolean isSpaceChar(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    @Override
    public void close() throws IOException {
        stream.close();
    }
}

/**
 * Optimized output writer.
 */
class FastWriter implements AutoCloseable {
    private final PrintWriter writer;

    public FastWriter(OutputStream stream) {
        this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(stream)));
    }

    public void println(Object message) {
        writer.println(message);
    }

    @Override
    public void close() {
        writer.close();
    }
}

