/**
 * A solver that calculates the sum of digits located on valid paths
 * within a grid, constrained by the shortest distance from an end point to a start point.
 */
public class GridPathSumSolver {

    /**
     * Represents a coordinate point in the 2D grid.
     */
    private static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * FastReader provides efficient reading of input using BufferedReader and StringTokenizer.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            return next == null ? -1 : Integer.parseInt(next);
        }
    }

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int[][] distances;

    private int startRow = -1, startCol = -1;
    private int endRow = -1, endCol = -1;

    public GridPathSumSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.distances = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            Arrays.fill(distances[i], -1);
        }
    }

    /**
     * Orchestrates the grid processing and prints the resulting sum.
     */
    public void solve() {
        findSpecialPoints();

        // If the start or end point is not found, the problem is unsolvable.
        if (startRow == -1 || endRow == -1) {
            System.out.println(0);
            return;
        }

        // Perform BFS starting from the 'E' (End) point to find shortest paths to all cells.
        performBFS(endRow, endCol);

        int distToStart = distances[startRow][startCol];
        long totalDigitSum = 0;

        // If the start point is unreachable from the end point
        if (distToStart != -1) {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    int currentDist = distances[r][c];
                    char cellValue = grid[r][c];

                    // Sum digits '1'-'9' if they are within the distance to the start point.
                    // Note: The original logic excluded '0' (char 48) and only looked at 1-9 (chars 49-57).
                    if (currentDist > 0 && currentDist <= distToStart && isDigitOneToNine(cellValue)) {
                        totalDigitSum += Character.getNumericValue(cellValue);
                    }
                }
            }
        }

        System.out.println(totalDigitSum);
    }

    private void findSpecialPoints() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 'S') {
                    startRow = r;
                    startCol = c;
                } else if (grid[r][c] == 'E') {
                    endRow = r;
                    endCol = c;
                }
            }
        }
    }

    private void performBFS(int startR, int startC) {
        Queue<Point> queue = new LinkedList<>();
        queue.add(new Point(startR, startC));
        distances[startR][startC] = 0;

        int[] dr = {1, -1, 0, 0};
        int[] dc = {0, 0, 1, -1};

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            for (int i = 0; i < 4; i++) {
                int nextR = current.row + dr[i];
                int nextC = current.col + dc[i];

                if (isValidMove(nextR, nextC)) {
                    distances[nextR][nextC] = distances[current.row][current.col] + 1;
                    queue.add(new Point(nextR, nextC));
                }
            }
        }
    }

    /**
     * Checks if a cell is within bounds, not a trap ('T'), 
     * not the end point ('E'), and has not been visited.
     */
    private boolean isValidMove(int r, int c) {
        return r >= 0 && r < rows && 
               c >= 0 && c < cols && 
               grid[r][c] != 'T' && 
               grid[r][c] != 'E' && 
               distances[r][c] == -1;
    }

    private boolean isDigitOneToNine(char c) {
        return c >= '1' && c <= '9';
    }

    public static void main(String[] args) {
        FastReader fr = new FastReader(System.in);

        String nInput = fr.next();
        if (nInput == null) return;

        int n = Integer.parseInt(nInput);
        int m = fr.nextInt();
        char[][] grid = new char[n][m];

        for (int i = 0; i < n; i++) {
            String rowStr = fr.next();
            if (rowStr != null) {
                for (int j = 0; j < m; j++) {
                    grid[i][j] = rowStr.charAt(j);
                }
            }
        }

        GridPathSumSolver solver = new GridPathSumSolver(n, m, grid);
        solver.solve();
    }
}

