/**
 * A program to navigate a forest grid and calculate the sum of numeric values 
 * encountered during a BFS traversal starting from the End ('E') until the Start ('S') is found.
 */
public class BirdianForest {

    public static void main(String[] args) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)))) {

            String line = reader.readLine();
            if (line == null) return;

            String[] dimensions = line.trim().split("\\s+");
            int rows = Integer.parseInt(dimensions[0]);
            int cols = Integer.parseInt(dimensions[1]);

            char[][] gridData = new char[rows][cols];
            int endRow = -1;
            int endCol = -1;

            for (int i = 0; i < rows; i++) {
                String rowString = reader.readLine();
                if (rowString == null) break;
                gridData[i] = rowString.toCharArray();

                // Locate the End point 'E' during input reading
                if (endRow == -1) {
                    for (int j = 0; j < cols; j++) {
                        if (gridData[i][j] == ForestConstants.END_NODE) {
                            endRow = i;
                            endCol = j;
                        }
                    }
                }
            }

            Forest forest = new Forest(gridData, endRow, endCol);
            ForestSolver solver = new ForestSolver(forest);

            writer.println(solver.solve());
            writer.flush();

        } catch (IOException | NumberFormatException e) {
            System.err.println("Error processing input: " + e.getMessage());
        }
    }
}

/**
 * Constants used throughout the application to avoid magic characters.
 */
class ForestConstants {
    public static final char START_NODE = 'S';
    public static final char END_NODE = 'E';
    public static final char TREE = 'T';
}

/**
 * Represents a single point in the grid.
 */
class Coordinate {
    final int row;
    final int col;

    Coordinate(int row, int col) {
        this.row = row;
        this.col = col;
    }
}

/**
 * Encapsulates the grid data and provides boundary checks.
 */
class Forest {
    private final char[][] grid;
    private final int rows;
    private final int cols;
    private final int startRow;
    private final int startCol;

    public Forest(char[][] grid, int endRow, int endCol) {
        this.grid = grid;
        this.rows = grid.length;
        this.cols = (rows > 0) ? grid[0].length : 0;
        this.startRow = endRow;
        this.startCol = endCol;
    }

    public int getRows() { return rows; }
    public int getCols() { return cols; }
    public char getCell(int r, int c) { return grid[r][c]; }
    public int getEndRow() { return startRow; }
    public int getEndCol() { return startCol; }

    public boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    public boolean isPassable(int r, int c) {
        return isWithinBounds(r, c) && grid[r][c] != ForestConstants.TREE;
    }
}

/**
 * Contains the logic to perform the BFS traversal and calculate the sum.
 */
class ForestSolver {
    private final Forest forest;

    // Directions: Up, Down, Left, Right
    private static final int[][] DIRECTIONS = {
        {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    public ForestSolver(Forest forest) {
        this.forest = forest;
    }

    /**
     * Executes BFS from 'E' until 'S' is reached.
     * @return The sum of numeric characters encountered.
     */
    public int solve() {
        if (forest.getEndRow() == -1) return 0;

        int accumulatedSum = 0;
        boolean startFound = false;
        boolean[][] visited = new boolean[forest.getRows()][forest.getCols()];
        Queue<Coordinate> queue = new LinkedList<>();

        // Initialize BFS
        Coordinate startNode = new Coordinate(forest.getEndRow(), forest.getEndCol());
        queue.offer(startNode);
        visited[startNode.row][startNode.col] = true;

        while (!queue.isEmpty() && !startFound) {
            int nodesInCurrentLevel = queue.size();

            // Process the current level of the BFS
            for (int i = 0; i < nodesInCurrentLevel; i++) {
                Coordinate current = queue.poll();
                int r = current.row;
                int c = current.col;
                char cellValue = forest.getCell(r, c);

                if (cellValue == ForestConstants.START_NODE) {
                    startFound = true;
                } else if (isDigit(cellValue)) {
                    accumulatedSum += Character.getNumericValue(cellValue);
                }

                // Explore neighbors
                for (int[] dir : DIRECTIONS) {
                    int nextR = r + dir[0];
                    int nextC = c + dir[1];

                    if (forest.isPassable(nextR, nextC) && !visited[nextR][nextC]) {
                        visited[nextR][nextC] = true;
                        queue.offer(new Coordinate(nextR, nextC));
                    }
                }
            }
        }

        return accumulatedSum;
    }

    private boolean isDigit(char c) {
        return c >= '1' && c <= '9';
    }
}

