public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            while (reader.hasNext()) {
                int rows = reader.nextInt();
                int cols = reader.nextInt();
                char[][] grid = reader.readGrid(rows, cols);

                GridSolver solver = new GridSolver(rows, cols, grid);
                writer.println(solver.solve());
            }
        } catch (Exception e) {
            // End of input or parsing error
        } finally {
            writer.flush();
            writer.close();
        }
    }

    record Point(int row, int col) {}

    static class GridSolver {
        private static final char ENTRY = 'E';
        private static final char START = 'S';
        private static final char WALL = 'T';
        private static final int INF = Integer.MAX_VALUE;
        private static final int[] DR = {-1, 1, 0, 0};
        private static final int[] DC = {0, 0, -1, 1};

        private final int rows, cols;
        private final char[][] grid;

        public GridSolver(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
        }

        public int solve() {
            int[][] dist = new int[rows][cols];
            for (int i = 0; i < rows; i++) Arrays.fill(dist[i], INF);

            Queue<Point> queue = new LinkedList<>();
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == ENTRY) {
                        dist[i][j] = 0;
                        queue.add(new Point(i, j));
                    }
                }
            }

            int targetDist = -1;
            while (!queue.isEmpty()) {
                Point curr = queue.poll();

                if (grid[curr.row()][curr.col()] == START) {
                    targetDist = dist[curr.row()][curr.col()];
                    break;
                }

                for (int i = 0; i < 4; i++) {
                    int nr = curr.row() + DR[i];
                    int nc = curr.col() + DC[i];

                    if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && 
                        grid[nr][nc] != WALL && dist[nr][nc] == INF) {
                        dist[nr][nc] = dist[curr.row()][curr.col()] + 1;
                        queue.add(new Point(nr, nc));
                    }
                }
            }

            if (targetDist == -1) return 0;

            int sum = 0;
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (dist[i][j] <= targetDist && Character.isDigit(grid[i][j])) {
                        sum += (grid[i][j] - '0');
                    }
                }
            }
            return sum;
        }
    }

    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public boolean hasNext() {
            try {
                while (tokenizer == null || !tokenizer.hasMoreElements()) {
                    String line = reader.readLine();
                    if (line == null) return false;
                    tokenizer = new StringTokenizer(line);
                }
                return true;
            } catch (IOException e) {
                return false;
            }
        }

        public String next() {
            if (hasNext()) return tokenizer.nextToken();
            return null;
        }

        public int nextInt() {
            String s = next();
            return s == null ? -1 : Integer.parseInt(s);
        }

        public char[][] readGrid(int rows, int cols) {
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = next().toCharArray();
            }
            return grid;
        }
    }
}

