class MazeSolver {
    private static final char EXIT_CHAR = 'E';
    private static final char TARGET_CHAR = 'S';
    private static final char OBSTACLE_CHAR = 'T';

    private static final int[] ROW_DIRECTIONS = {1, -1, 0, 0};
    private static final int[] COL_DIRECTIONS = {0, 0, -1, 1};

    private final InputReader reader;

    public MazeSolver(InputReader reader) {
        this.reader = reader;
    }

    /**
     * Represents a coordinate in the grid.
     */
    private record Point(int row, int col) {}

    public void run() throws IOException {
        int rows = reader.nextInt();
        int cols = reader.nextInt();
        char[][] grid = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            grid[i] = reader.next().toCharArray();
        }

        int result = solve(rows, cols, grid);
        System.out.println(result);
    }

    private int solve(int rows, int cols, char[][] grid) {
        int[][] distances = computeDistancesFromExit(rows, cols, grid);

        int maxAllowedDistance = findTargetDistance(rows, cols, grid, distances);

        return sumDigitsWithinDistance(rows, cols, grid, distances, maxAllowedDistance);
    }

    /**
     * Performs a BFS starting from the Exit ('E') to calculate 
     * the shortest path to all reachable cells.
     */
    private int[][] computeDistancesFromExit(int rows, int cols, char[][] grid) {
        int[][] distances = new int[rows][cols];
        Queue<Point> queue = new ArrayDeque<>();

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == EXIT_CHAR) {
                    distances[r][c] = 1; // Using 1-based distance as per original logic
                    queue.add(new Point(r, c));
                }
            }
        }

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            for (int i = 0; i < 4; i++) {
                int nextR = current.row() + ROW_DIRECTIONS[i];
                int nextC = current.col() + COL_DIRECTIONS[i];

                if (isValidMove(nextR, nextC, rows, cols, grid, distances)) {
                    distances[nextR][nextC] = distances[current.row()][current.col()] + 1;
                    queue.add(new Point(nextR, nextC));
                }
            }
        }

        return distances;
    }

    private boolean isValidMove(int r, int c, int rows, int cols, char[][] grid, int[][] distances) {
        return r >= 0 && r < rows && 
               c >= 0 && c < cols && 
               distances[r][c] == 0 && 
               grid[r][c] != OBSTACLE_CHAR;
    }

    /**
     * Finds the distance from 'E' to 'S'.
     */
    private int findTargetDistance(int rows, int cols, char[][] grid, int[][] distances) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == TARGET_CHAR) {
                    return distances[r][c];
                }
            }
        }
        return 0;
    }

    /**
     * Sums up all digit values in the grid that are within the maxAllowedDistance.
     */
    private int sumDigitsWithinDistance(int rows, int cols, char[][] grid, int[][] distances, int maxDistance) {
        int totalSum = 0;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (isDigitInRange(grid[r][c], distances[r][c], maxDistance)) {
                    totalSum += Character.getNumericValue(grid[r][c]);
                }
            }
        }
        return totalSum;
    }

    private boolean isDigitInRange(char cellChar, int distance, int maxDistance) {
        return Character.isDigit(cellChar) && distance != 0 && distance <= maxDistance;
    }
}

