class GridSolver {
    private static final int TYPE_EXIT = -1;
    private static final int TYPE_START = -2;
    private static final int TYPE_TRAP = -3;
    private static final int INF = Integer.MAX_VALUE;

    private final FastReader reader;
    private int rows;
    private int cols;
    private int[][] grid;
    private int[][] distances;

    public GridSolver(FastReader reader) {
        this.reader = reader;
    }

    /**
     * Represents a coordinate in the grid.
     */
    private static class Point {
        final int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    public void solve(PrintWriter out) {
        this.rows = reader.nextInt();
        this.cols = reader.nextInt();
        this.grid = new int[rows][cols];
        this.distances = new int[rows][cols];

        int startRow = -1;
        int startCol = -1;

        // Parse the grid
        for (int i = 0; i < rows; i++) {
            String line = reader.next();
            for (int j = 0; j < cols; j++) {
                char cell = line.charAt(j);
                distances[i][j] = INF;

                if (Character.isDigit(cell)) {
                    grid[i][j] = cell - '0';
                } else if (cell == 'E') {
                    grid[i][j] = TYPE_EXIT;
                } else if (cell == 'S') {
                    grid[i][j] = TYPE_START;
                    startRow = i;
                    startCol = j;
                } else if (cell == 'T') {
                    grid[i][j] = TYPE_TRAP;
                }
            }
        }

        performMultiSourceBFS();

        out.println(calculateTotalFood(startRow, startCol));
    }

    /**
     * Performs a multi-source BFS starting from all Exit ('E') cells.
     */
    private void performMultiSourceBFS() {
        Deque<Point> queue = new ArrayDeque<>();

        // Initialize BFS with all exit points
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == TYPE_EXIT) {
                    distances[i][j] = 0;
                    queue.add(new Point(i, j));
                }
            }
        }

        int[] dr = {1, -1, 0, 0};
        int[] dc = {0, 0, 1, -1};

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            for (int i = 0; i < 4; i++) {
                int nr = current.r + dr[i];
                int nc = current.c + dc[i];

                if (isValidMove(nr, nc)) {
                    distances[nr][nc] = distances[current.r][current.c] + 1;
                    queue.add(new Point(nr, nc));
                }
            }
        }
    }

    private boolean isValidMove(int r, int c) {
        return r >= 0 && r < rows && 
               c >= 0 && c < cols && 
               grid[r][c] != TYPE_TRAP && 
               distances[r][c] == INF;
    }

    /**
     * Calculates the sum of food items reachable from an exit 
     * in a distance less than or equal to the distance from the start to an exit.
     */
    private int calculateTotalFood(int startRow, int startCol) {
        int totalFood = 0;
        int startDist = (startRow != -1) ? distances[startRow][startCol] : INF;

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                // Food cell must have a value > 0 and be reachable within startDist
                if (grid[i][j] > 0 && distances[i][j] <= startDist) {
                    totalFood += grid[i][j];
                }
            }
        }
        return totalFood;
    }
}

