/**
 * Logic for solving the grid-based shortest path and summation problem.
 */
class GridPathfinder {
    private static final int INF = Integer.MAX_VALUE;
    private static final int[] ROW_DIRECTIONS = {0, 1, 0, -1};
    private static final int[] COL_DIRECTIONS = {1, 0, -1, 0};

    /**
     * Represents a coordinate in the 2D grid.
     */
    private static class GridPosition {
        final int row;
        final int col;

        GridPosition(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Container for the special 'S' and 'E' positions.
     */
    private static class GridMarkers {
        GridPosition start;
        GridPosition end;

        GridMarkers(GridPosition start, GridPosition end) {
            this.start = start;
            this.end = end;
        }
    }

    public void solve(FastReader in, PrintWriter out) throws IOException {
        int rows = in.nextInt();
        int cols = in.nextInt();
        char[][] grid = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            grid[i] = in.next().toCharArray();
        }

        GridMarkers markers = findSpecialPositions(grid, rows, cols);
        if (markers.start == null || markers.end == null) {
            out.println(0);
            return;
        }

        int[][] distanceMap = computeDistances(grid, rows, cols, markers.end);
        int targetDistance = distanceMap[markers.start.row][markers.start.col];

        long result = calculateSumOfDigits(grid, distanceMap, rows, cols, targetDistance);
        out.println(result);
    }

    private GridMarkers findSpecialPositions(char[][] grid, int rows, int cols) {
        GridPosition start = null;
        GridPosition end = null;

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 'S') {
                    start = new GridPosition(i, j);
                } else if (grid[i][j] == 'E') {
                    end = new GridPosition(i, j);
                }
            }
        }
        return new GridMarkers(start, end);
    }

    /**
     * Performs a Breadth-First Search from the end position to find shortest paths.
     */
    private int[][] computeDistances(char[][] grid, int rows, int cols, GridPosition startNode) {
        int[][] distances = new int[rows][cols];
        for (int[] row : distances) {
            Arrays.fill(row, INF);
        }

        Queue<GridPosition> queue = new LinkedList<>();
        distances[startNode.row][startNode.col] = 0;
        queue.add(startNode);

        while (!queue.isEmpty()) {
            GridPosition current = queue.poll();

            for (int d = 0; d < 4; d++) {
                int nextRow = current.row + ROW_DIRECTIONS[d];
                int nextCol = current.col + COL_DIRECTIONS[d];

                if (isWithinBounds(nextRow, nextCol, rows, cols) 
                        && grid[nextRow][nextCol] != 'T' 
                        && distances[nextRow][nextCol] == INF) {

                    distances[nextRow][nextCol] = distances[current.row][current.col] + 1;
                    queue.add(new GridPosition(nextRow, nextCol));
                }
            }
        }
        return distances;
    }

    private boolean isWithinBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private long calculateSumOfDigits(char[][] grid, int[][] distances, int rows, int cols, int maxDist) {
        // If the start position is unreachable, maxDist will be INF.
        // We use long to prevent potential overflow in summation.
        long sum = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (Character.isDigit(grid[i][j]) && distances[i][j] != INF && distances[i][j] <= maxDist) {
                    sum += (grid[i][j] - '0');
                }
            }
        }
        return sum;
    }
}

