import java.util.*;

/**
 * A solver that calculates the sum of digits in a grid based on 
 * reachability and distance from an exit point 'E' to a target 'S'.
 */
public class GridDigitSumSolver {

    private static final char EXIT_CHAR = 'E';
    private static final char TARGET_CHAR = 'S';
    private static final char WALL_CHAR = 'T';

    // Direction vectors for moving Up, Down, Left, Right
    private static final int[][] DIRECTIONS = {
        {1, 0}, {-1, 0}, {0, 1}, {0, -1}
    };

    private final int rows;
    private final int cols;
    private final char[][] grid;

    public GridDigitSumSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
    }

    /**
     * Represents a point in the grid with its distance from the starting point.
     */
    private static class Node {
        int r, c, distance;

        Node(int r, int c, int distance) {
            this.r = r;
            this.c = c;
            this.distance = distance;
        }
    }

    public long solve() {
        int startR = -1, startC = -1;
        int targetR = -1, targetC = -1;

        // 1. Locate the Exit (Start) and Target (S)
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == EXIT_CHAR) {
                    startR = i;
                    startC = j;
                } else if (grid[i][j] == TARGET_CHAR) {
                    targetR = i;
                    targetC = j;
                }
            }
        }

        if (startR == -1) return 0;

        // 2. BFS to find the shortest distance from Exit to all reachable cells
        int[][] distanceMap = bfs(startR, startC);

        int targetDistance = (targetR != -1) ? distanceMap[targetR][targetC] : -1;

        // 3. Calculate the sum based on the distance threshold
        long totalDigitSum = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int dist = distanceMap[i][j];

                // Only process reachable cells
                if (dist != -1) {
                    // If target 'S' is reachable, only sum digits within its distance threshold
                    // Note: The original logic excludes the 'S' cell and the 'E' cell from the sum
                    if (targetDistance != -1) {
                        if (dist <= targetDistance && isDigit(grid[i][j]) && grid[i][j] != TARGET_CHAR) {
                            totalDigitSum += Character.getNumericValue(grid[i][j]);
                        }
                    } else {
                        // If 'S' is never found, sum all reachable digits (excluding 'E')
                        if (isDigit(grid[i][j])) {
                            totalDigitSum += Character.getNumericValue(grid[i][j]);
                        }
                    }
                }
            }
        }

        return totalDigitSum;
    }

    private int[][] bfs(int startR, int startC) {
        int[][] distanceMap = new int[rows][cols];
        for (int[] row : distanceMap) {
            Arrays.fill(row, -1);
        }

        Deque<Node> queue = new ArrayDeque<>();
        queue.add(new Node(startR, startC, 0));
        distanceMap[startR][startC] = 0;

        while (!queue.isEmpty()) {
            Node current = queue.poll();

            for (int[] dir : DIRECTIONS) {
                int nextR = current.r + dir[0];
                int nextC = current.c + dir[1];

                if (isValidMove(nextR, nextC) && distanceMap[nextR][nextC] == -1) {
                    distanceMap[nextR][nextC] = current.distance + 1;
                    queue.add(new Node(nextR, nextC, current.distance + 1));
                }
            }
        }
        return distanceMap;
    }

    private boolean isValidMove(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] != WALL_CHAR;
    }

    private boolean isDigit(char ch) {
        return ch >= '0' && ch <= '9';
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int r = scanner.nextInt();
        int c = scanner.nextInt();

        char[][] grid = new char[r][c];
        for (int i = 0; i < r; i++) {
            String rowString = scanner.next();
            for (int j = 0; j < c; j++) {
                grid[i][j] = rowString.charAt(j);
            }
        }

        GridDigitSumSolver solver = new GridDigitSumSolver(r, c, grid);
        System.out.println(solver.solve());

        scanner.close();
    }
}

import java.util.*;

/**
 * A solver for a grid-based navigation problem.
 * The goal is to find the shortest distance from an exit ('E') to a start point ('S')
 * and sum the values of all numeric cells within that distance.
 */
public class MazeSolver {

    private static final char EXIT = 'E';
    private static final char START = 'S';
    private static final char WALL = 'T';
    private static final int UNVISITED = -1;

    // Direction vectors for Up, Down, Left, Right
    private static final int[] DX = {-1, 1, 0, 0};
    private static final int[] DY = {0, 0, -1, 1};

    /**
     * Represents a coordinate in the grid with its distance from the starting point.
     */
    private record Node(int x, int y, int distance) {}

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        scanner.nextLine(); // Consume newline

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.nextLine();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
            }
        }

        MazeSolver solver = new MazeSolver();
        int result = solver.solve(grid, rows, cols);
        System.out.println(result);

        scanner.close();
    }

    /**
     * Orchestrates the BFS and the final calculation.
     */
    public int solve(char[][] grid, int rows, int cols) {
        int[] exitCoords = findCharacter(grid, rows, cols, EXIT);
        if (exitCoords == null) return 0;

        int[][] distances = computeDistancesFrom(grid, rows, cols, exitCoords[0], exitCoords[1]);

        // Find the distance to the Start point 'S'
        int[] startCoords = findCharacter(grid, rows, cols, START);
        int maxAllowedDistance = (startCoords != null) ? distances[startCoords[0]][startCoords[1]] : 0;

        // If 'S' is unreachable, maxAllowedDistance will be UNVISITED (-1)
        return calculateSumOfDigitsWithinDistance(grid, rows, cols, distances, maxAllowedDistance);
    }

    /**
     * Performs BFS to find shortest distances from (startX, startY) to all reachable cells.
     */
    private int[][] computeDistancesFrom(char[][] grid, int rows, int cols, int startX, int startY) {
        int[][] distances = new int[rows][cols];
        for (int[] row : distances) {
            Arrays.fill(row, UNVISITED);
        }

        Deque<Node> queue = new ArrayDeque<>();
        queue.add(new Node(startX, startY, 0));
        distances[startX][startY] = 0;

        while (!queue.isEmpty()) {
            Node current = queue.poll();

            for (int i = 0; i < 4; i++) {
                int nx = current.x + DX[i];
                int ny = current.y + DY[i];

                if (isValidMove(grid, rows, cols, nx, ny) && distances[nx][ny] == UNVISITED) {
                    distances[nx][ny] = current.distance + 1;
                    queue.add(new Node(nx, ny, distances[nx][ny]));
                }
            }
        }
        return distances;
    }

    private boolean isValidMove(char[][] grid, int rows, int cols, int x, int y) {
        return x >= 0 && x < rows && y >= 0 && y < cols && grid[x][y] != WALL;
    }

    /**
     * Sums the numeric values of cells whose distance is <= threshold.
     */
    private int calculateSumOfDigitsWithinDistance(char[][] grid, int rows, int cols, int[][] distances, int threshold) {
        if (threshold == UNVISITED) return 0;

        int sum = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                char cell = grid[i][j];
                if (Character.isDigit(cell)) {
                    int dist = distances[i][j];
                    if (dist != UNVISITED && dist <= threshold) {
                        sum += Character.getNumericValue(cell);
                    }
                }
            }
        }
        return sum;
    }

    /**
     * Helper to find the coordinates of a specific character in the grid.
     */
    private int[] findCharacter(char[][] grid, int rows, int cols, char target) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == target) {
                    return new int[]{i, j};
                }
            }
        }
        return null;
    }
}

