/**
 * A solver that calculates the sum of digits in a grid based on their 
 * proximity to a starting point 'E', relative to a target point 'S'.
 */
public class GridDigitSumSolver {

    private static final int[][] DIRECTIONS = {
            {0, 1}, {0, -1}, {1, 0}, {-1, 0}
    };

    /**
     * Represents a coordinate in the 2D grid.
     */
    private static class Cell {
        final int row;
        final int col;

        Cell(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private int[][] distances;
    private Cell exitCell;
    private Cell startCell;

    public GridDigitSumSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.distances = new int[rows][cols];
    }

    /**
     * Main execution logic.
     */
    public long solve() {
        initializeDistances();
        findSpecialCells();
        computeDistancesFromExit();
        return calculateDigitSum();
    }

    private void initializeDistances() {
        for (int i = 0; i < rows; i++) {
            Arrays.fill(distances[i], -1);
        }
    }

    /**
     * Locates the 'E' (Exit/Source) and 'S' (Start/Target) cells in the grid.
     */
    private void findSpecialCells() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 'E') {
                    exitCell = new Cell(i, j);
                } else if (grid[i][j] == 'S') {
                    startCell = new Cell(i, j);
                }
            }
        }
    }

    /**
     * Performs a Breadth-First Search starting from the 'E' cell to calculate 
     * the shortest distance to all reachable cells.
     */
    private void computeDistancesFromExit() {
        if (exitCell == null) return;

        Queue<Cell> queue = new LinkedList<>();
        exitCell = exitCell; // redundant but for clarity
        queue.add(exitCell);
        distances[exitCell.row][exitCell.col] = 0;

        while (!queue.isEmpty()) {
            Cell current = queue.poll();

            for (int[] dir : DIRECTIONS) {
                int nextRow = current.row + dir[0];
                int nextCol = current.col + dir[1];

                if (isValidMove(nextRow, nextCol)) {
                    distances[nextRow][nextCol] = distances[current.row][current.col] + 1;
                    queue.add(new Cell(nextRow, nextCol));
                }
            }
        }
    }

    private boolean isValidMove(int r, int c) {
        return r >= 0 && r < rows && 
               c >= 0 && c < cols && 
               grid[r][c] != 'T' && 
               distances[r][c] == -1;
    }

    /**
     * Sums the values of all digits in the grid where the distance from 'E' 
     * is less than or equal to the distance from 'E' to 'S'.
     */
    private long calculateDigitSum() {
        if (startCell == null || exitCell == null) return 0;

        int targetDistance = distances[startCell.row][startCell.col];
        // If 'S' is unreachable, targetDistance is -1. 
        // Based on logic, if targetDistance is -1, no cell can have dist <= -1.
        if (targetDistance == -1) return 0;

        long totalSum = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                char cellChar = grid[i][j];
                if (isDigit(cellChar) && distances[i][j] != -1 && distances[i][j] <= targetDistance) {
                    totalSum += (cellChar - '0');
                }
            }
        }
        return totalSum;
    }

    private boolean isDigit(char c) {
        return c >= '0' && c <= '9';
    }

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int n = reader.nextInt();
            int m = reader.nextInt();
            char[][] grid = new char[n][];
            for (int i = 0; i < n; i++) {
                grid[i] = reader.next().toCharArray();
            }

            GridDigitSumSolver solver = new GridDigitSumSolver(n, m, grid);
            writer.println(solver.solve());
        } catch (Exception e) {
            // In a production environment, use a Logger
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    /**
     * Optimized reader for fast input processing.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

