/**
 * Represents a coordinate on the grid.
 */
record Point(int row, int col) {}

/**
 * Holds the grid data and provides access to its properties.
 */
class Grid {
    private static final char START_CHAR = 'S';
    private static final char END_CHAR = 'E';
    private static final char OBSTACLE_CHAR = 'T';

    private final int rows;
    private final int cols;
    private final char[][] cells;
    private Point startPoint;
    private Point endPoint;

    public Grid(int rows, int cols, FastReader reader) throws IOException {
        this.rows = rows;
        this.cols = cols;
        this.cells = new char[rows][cols];
        parseGrid(reader);
    }

    private void parseGrid(FastReader reader) throws IOException {
        for (int i = 0; i < rows; i++) {
            String line = reader.next();
            for (int j = 0; j < cols; j++) {
                char c = line.charAt(j);
                cells[i][j] = c;
                if (c == START_CHAR) {
                    startPoint = new Point(i, j);
                } else if (c == END_CHAR) {
                    endPoint = new Point(i, j);
                }
            }
        }
    }

    public int getRows() { return rows; }
    public int getCols() { return cols; }
    public char getCell(int r, int c) { return cells[r][c]; }
    public Point getStartPoint() { return startPoint; }
    public Point getEndPoint() { return endPoint; }
    public boolean isObstacle(int r, int c) { return cells[r][c] == OBSTACLE_CHAR; }
    public boolean isNumeric(int r, int c) {
        char cell = cells[r][c];
        return cell >= '1' && cell <= '9';
    }
    public int getNumericValue(int r, int c) {
        return cells[r][c] - '0';
    }
}

/**
 * Contains the logic to solve the specific grid task.
 */
class GridSolver {
    private static final int[][] DIRECTIONS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
    private static final int INF = Integer.MAX_VALUE;

    public void solve(FastReader reader, PrintWriter writer) throws IOException {
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        Grid grid = new Grid(rows, cols, reader);

        // Calculate shortest distances from the End point to all other cells
        int[][] distancesFromEnd = calculateDistances(grid, grid.getEndPoint());

        // Find the distance required to travel from Start to End
        int travelLimit = distancesFromEnd[grid.getStartPoint().row()][grid.getStartPoint().col()];

        // If the end is unreachable from the start
        if (travelLimit == INF) {
            writer.println(0);
            return;
        }

        // Sum numeric values of cells reachable within the travel limit
        long totalValue = 0;
        for (int i = 0; i < grid.getRows(); i++) {
            for (int j = 0; j < grid.getCols(); j++) {
                if (grid.isNumeric(i, j) && distancesFromEnd[i][j] <= travelLimit) {
                    totalValue += grid.getNumericValue(i, j);
                }
            }
        }

        writer.println(totalValue);
    }

    /**
     * Performs a BFS to find shortest paths from a starting point to all reachable cells.
     */
    private int[][] calculateDistances(Grid grid, Point start) {
        int rows = grid.getRows();
        int cols = grid.getCols();
        int[][] distances = new int[rows][cols];

        for (int[] row : distances) {
            Arrays.fill(row, INF);
        }

        Queue<Point> queue = new ArrayDeque<>();
        distances[start.row()][start.col()] = 0;
        queue.add(start);

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            for (int[] dir : DIRECTIONS) {
                int nextR = current.row() + dir[0];
                int nextC = current.col() + dir[1];

                if (isValidMove(grid, nextR, nextC, distances)) {
                    distances[nextR][nextC] = distances[current.row()][current.col()] + 1;
                    queue.add(new Point(nextR, nextC));
                }
            }
        }

        return distances;
    }

    private boolean isValidMove(Grid grid, int r, int c, int[][] distances) {
        return r >= 0 && r < grid.getRows() &&
               c >= 0 && c < grid.getCols() &&
               !grid.isObstacle(r, c) &&
               distances[r][c] == INF;
    }
}

