/**
 * A program to calculate the sum of digits in a grid that are within a certain 
 * distance from an exit point 'E', relative to a starting point 'S'.
 */
public class GridPathSumSolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = reader.nextInt();
            int m = reader.nextInt();
            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                grid[i] = reader.nextString().toCharArray();
            }

            GridSolver solver = new GridSolver(n, m, grid);
            long result = solver.solve();
            out.println(result);
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        } finally {
            out.close();
        }
    }

    /**
     * Represents a coordinate in the 2D grid.
     */
    private record Point(int x, int y) {}

    /**
     * Encapsulates the grid logic and the BFS algorithm.
     */
    private static class GridSolver {
        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final int[][] distances;

        private static final int[] DX = {0, -1, 0, 1};
        private static final int[] DY = {1, 0, -1, 0};

        public GridSolver(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            this.distances = new int[rows][cols];
            for (int[] row : distances) {
                Arrays.fill(row, -1);
            }
        }

        public long solve() {
            Point exitPos = findCharacter('E');
            Point startPos = findCharacter('S');

            if (exitPos == null || startPos == null) {
                return 0;
            }

            // Perform BFS starting from the exit 'E'
            performBFS(exitPos);

            int distToStart = distances[startPos.x()][startPos.y()];

            // If start is unreachable from exit, distance is effectively infinite 
            // based on original logic, but we handle the unreachable case.
            if (distToStart == -1) {
                return 0;
            }

            return calculateSum(distToStart);
        }

        private Point findCharacter(char target) {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == target) {
                        return new Point(i, j);
                    }
                }
            }
            return null;
        }

        private void performBFS(Point start) {
            Deque<Point> queue = new ArrayDeque<>();

            distances[start.x()][start.y()] = 0;
            queue.add(start);

            while (!queue.isEmpty()) {
                Point current = queue.poll();

                for (int i = 0; i < 4; i++) {
                    int nx = current.x() + DX[i];
                    int ny = current.y() + DY[i];

                    if (isValidMove(nx, ny)) {
                        distances[nx][ny] = distances[current.x()][current.y()] + 1;
                        queue.add(new Point(nx, ny));
                    }
                }
            }
        }

        private boolean isValidMove(int x, int y) {
            return x >= 0 && x < rows && 
                   y >= 0 && y < cols && 
                   grid[x][y] != 'T' && 
                   distances[x][y] == -1;
        }

        private long calculateSum(int maxAllowedDist) {
            long sum = 0;
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    char cell = grid[i][j];
                    // Check if cell is a digit '1'-'9' and reachable within maxAllowedDist
                    if (cell >= '1' && cell <= '9' && distances[i][j] != -1 && distances[i][j] <= maxAllowedDist) {
                        sum += (cell - '0');
                    }
                }
            }
            return sum;
        }
    }

    /**
     * Utility class for fast input reading.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String nextToken() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        public String nextString() throws IOException {
            return reader.readLine();
        }
    }
}

