/**
 * Solves the grid problem by finding the shortest path from the end ('E') 
 * to the start ('S') and summing the values of all digit-containing cells 
 * reachable within that distance.
 */
public class GridPathSolver {

    private static final char START_NODE = 'S';
    private static final char END_NODE = 'E';
    private static final char TRAP_NODE = 'T';

    // Represent a coordinate in the 2D grid
    private record Point(int row, int col) {}

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            GridPathSolver solver = new GridPathSolver();
            solver.solve(reader, writer);
        } catch (IOException e) {
            System.err.println("An error occurred while processing the grid: " + e.getMessage());
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Orchestrates the solving process.
     */
    public void solve(FastReader reader, PrintWriter writer) throws IOException {
        int rows = reader.nextInt();
        int cols = reader.nextInt();
        char[][] grid = new char[rows][cols];

        Point start = null;
        Point end = null;

        // 1. Parse grid and locate Start and End positions
        for (int i = 0; i < rows; i++) {
            String line = reader.next();
            grid[i] = line.toCharArray();
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == START_NODE) {
                    start = new Point(i, j);
                } else if (grid[i][j] == END_NODE) {
                    end = new Point(i, j);
                }
            }
        }

        if (start == null || end == null) {
            writer.println(0);
            return;
        }

        // 2. Compute shortest distances from the End node to all other nodes using BFS
        int[][] distances = computeDistancesFrom(grid, end, rows, cols);

        // 3. Determine the shortest distance to the Start node
        int shortestPathToStart = distances[start.row()][start.col()];

        // 4. Calculate the sum of digits in cells reachable within that distance
        long totalSum = calculateDigitSum(grid, distances, shortestPathToStart, rows, cols);

        writer.println(totalSum);
    }

    /**
     * Performs a Breadth-First Search to find the shortest path from a source point 
     * to all reachable points in the grid.
     */
    private int[][] computeDistancesFrom(char[][] grid, Point source, int rows, int cols) {
        int[][] distances = new int[rows][cols];
        for (int[] row : distances) {
            Arrays.fill(row, Integer.MAX_VALUE);
        }

        Queue<Point> queue = new ArrayDeque<>();
        distances[source.row()][source.col()] = 0;
        queue.add(source);

        int[] dRow = {-1, 1, 0, 0};
        int[] dCol = {0, 0, -1, 1};

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            for (int i = 0; i < 4; i++) {
                int nextRow = current.row() + dRow[i];
                int nextCol = current.col() + dCol[i];

                if (isValidMove(grid, nextRow, nextCol, rows, cols)) {
                    if (distances[nextRow][nextCol] == Integer.MAX_VALUE) {
                        distances[nextRow][nextCol] = distances[current.row()][current.col()] + 1;
                        queue.add(new Point(nextRow, nextCol));
                    }
                }
            }
        }
        return distances;
    }

    private boolean isValidMove(char[][] grid, int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] != TRAP_NODE;
    }

    /**
     * Sums up digits in cells that satisfy the distance condition.
     */
    private long calculateDigitSum(char[][] grid, int[][] distances, int maxDist, int rows, int cols) {
        long sum = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                char cell = grid[i][j];
                // Sum if cell is a digit and distance is within the limit
                if (Character.isDigit(cell)) {
                    if (distances[i][j] <= maxDist) {
                        sum += Character.getNumericValue(cell);
                    }
                }
            }
        }
        return sum;
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

