/**
 * A program to solve the forest path summation problem.
 * The goal is to sum the values of all digit-based cells whose distance 
 * to the 'End' is less than or equal to the distance from 'Start' to 'End'.
 */
public class Main {
    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        ForestSolver solver = new ForestSolver();
        solver.solve(reader, writer);

        writer.flush();
        writer.close();
    }
}

class ForestSolver {
    private static final int INF = Integer.MAX_VALUE;
    private static final int[] DR = {1, -1, 0, 0};
    private static final int[] DC = {0, 0, 1, -1};

    private int rows;
    private int cols;
    private char[][] grid;
    private int[][] distances;

    /**
     * Main logic to process the grid and calculate the result.
     */
    public void solve(FastReader in, PrintWriter out) {
        rows = in.nextInt();
        cols = in.nextInt();
        grid = new char[rows][cols];
        distances = new int[rows][cols];

        int startRow = -1, startCol = -1;
        int endRow = -1, endCol = -1;

        for (int i = 0; i < rows; i++) {
            String line = in.next();
            grid[i] = line.toCharArray();
            for (int j = 0; j < cols; j++) {
                distances[i][j] = INF;
                if (grid[i][j] == 'S') {
                    startRow = i;
                    startCol = j;
                } else if (grid[i][j] == 'E') {
                    endRow = i;
                    endCol = j;
                }
            }
        }

        // Perform BFS from the End point to find distances to all other cells
        performBFS(endRow, endCol);

        long totalSum = 0;
        int distanceToStart = distances[startRow][startCol];

        // If the Start point is unreachable, we only sum reachable digit cells.
        // The original logic implies we compare distances to the distance of S from E.
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (Character.isDigit(grid[i][j])) {
                    int d = distances[i][j];
                    // Sum if cell is reachable and within the distance threshold
                    if (d != INF && d <= distanceToStart) {
                        totalSum += (grid[i][j] - '0');
                    }
                }
            }
        }

        out.println(totalSum);
    }

    /**
     * Standard Breadth-First Search to find shortest paths in an unweighted grid.
     */
    private void performBFS(int startR, int startC) {
        if (startR == -1) return;

        Queue<Point> queue = new ArrayDeque<>();
        queue.add(new Point(startR, startC));
        distances[startR][startC] = 0;

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            for (int i = 0; i < 4; i++) {
                int nextR = current.r + DR[i];
                int nextC = current.c + DC[i];

                if (isValid(nextR, nextC) && distances[nextR][nextC] == INF) {
                    distances[nextR][nextC] = distances[current.r][current.c] + 1;
                    queue.add(new Point(nextR, nextC));
                }
            }
        }
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] != 'T';
    }

    /**
     * Simple data carrier for grid coordinates.
     */
    private static class Point {
        int r, c;
        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }
}

/**
 * Optimized reader for fast input processing.
 */
class FastReader {
    private final BufferedInputStream bis;
    private final byte[] buffer = new byte[1 << 16];
    private int bufferPointer = 0;
    private int bytesRead = 0;

    public FastReader(InputStream is) {
        this.bis = new BufferedInputStream(is);
    }

    public int nextInt() {
        int c = read();
        while (isSpaceChar(c)) c = read();
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        int res = 0;
        do {
            res = res * 10 + (c - '0');
            c = read();
        } while (!isSpaceChar(c));
        return res * sgn;
    }

    public String next() {
        int c = read();
        while (isSpaceChar(c)) c = read();
        StringBuilder sb = new StringBuilder();
        do {
            sb.append((char) c);
            c = read();
        } while (!isSpaceChar(c));
        return sb.toString();
    }

    private int read() {
        if (bufferPointer == bytesRead) fillBuffer();
        return (bytesRead == -1) ? -1 : buffer[bufferPointer++];
    }

    private void fillBuffer() {
        try {
            bytesRead = bis.read(buffer, bufferPointer = 0, buffer.length);
        } catch (IOException e) {
            bytesRead = -1;
        }
    }

    private boolean isSpaceChar(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }
}

