        this.columnCount = columnCount;
        this.cells = new char[rowCount][columnCount];
        initializeGrid(reader);
    }

    private void initializeGrid(FastReader reader) throws IOException {
        for (int i = 0; i < rowCount; i++) {
            String line = reader.next();
            cells[i] = line.toCharArray();
            for (int j = 0; j < columnCount; j++) {
                if (cells[i][j] == EXIT_CHAR) {
                    exitPosition = new Position(i, j);
                } else if (cells[i][j] == START_CHAR) {
                    startPosition = new Position(i, j);
                }
            }
        }
    }

    public boolean isValid(int r, int c) {
        return r >= 0 && r < rowCount && c >= 0 && c < columnCount;
    }

    public boolean isTraversable(int r, int c) {
        return isValid(r, c) && cells[r][c] != TRAP_CHAR;
    }

    public int getCellValue(int r, int c) {
        char val = cells[r][c];
        if (Character.isDigit(val)) {
            return val - '0';
        }
        return 0;
    }

