    public int getColumnCount() { return columnCount; }
    public Position getExitPosition() { return exitPosition; }
    public Position getStartPosition() { return startPosition; }
}

/**
 * Handles the BFS algorithm and distance calculations.
 */
class Pathfinder {
    private static final int[][] DIRECTIONS = {
        {1, 0}, {-1, 0}, {0, 1}, {0, -1}
    };

    private final Grid grid;

    public Pathfinder(Grid grid) {
        this.grid = grid;
    }

    /**
     * Performs BFS starting from the exit to find shortest distances to all reachable cells.
     * @return A 2D array of distances where -1 indicates unreachable.
     */
    private int[][] computeDistancesFromExit() {
        int rows = grid.getRowCount();
        int cols = grid.getColumnCount();
        int[][] distances = new int[rows][cols];
        for (int[] row : distances) {
            Arrays.fill(row, -1);
        }

        Queue<Position> queue = new LinkedList<>();
        Position exit = grid.getExitPosition();

        if (exit != null) {
            distances[exit.row()][exit.col()] = 0;
            queue.add(exit);
        }

        while (!queue.isEmpty()) {
            Position current = queue.poll();

            for (int[] dir : DIRECTIONS) {
                int nextR = current.row() + dir[0];
                int nextC = current.col() + dir[1];

                if (grid.isTraversable(nextR, nextC) && distances[nextR][nextC] == -1) {
                    distances[nextR][nextC] = distances[current.row()][current.col()] + 1;
                    queue.add(new Position(nextR, nextC));
                }
            }
        }
        return distances;
    }

    /**
     * Sums up the values of cells that are within the distance range 
     * defined by the player's distance from the exit.
     */
    public long calculateReachableValueSum() {
        int[][] distances = computeDistancesFromExit();
        Position start = grid.getStartPosition();
        Position exit = grid.getExitPosition();

        if (start == null || exit == null) return 0;

        int playerDistance = distances[start.row()][start.col()];
        // If player is in a trap or unreachable, distance will be -1
        if (playerDistance == -1) return 0;

        long totalValue = 0;
        for (int i = 0; i < grid.getRowCount(); i++) {
            for (int j = 0; j < grid.getColumnCount(); j++) {
                // Skip the player and the exit themselves as per original logic
                if (new Position(i, j).equals(start) || new Position(i, j).equals(exit)) {
                    continue;
                }

                int distToCell = distances[i][j];
                if (distToCell != -1 && distToCell <= playerDistance) {
                    totalValue += grid.getCellValue(i, j);
                }
            }
        }
        return totalValue;
    }
}

