/**
 * A program to solve a maze-based puzzle where digits on the path 
 * between start and end points are summed based on distance constraints.
 */
public class MazeSolverApp {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] grid = reader.readGrid(rows, cols);

            MazeSolver solver = new MazeSolver(grid, rows, cols);
            int result = solver.solve();

            System.out.println(result);
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Represents a coordinate in the 2D grid.
     */
    static class Point {
        final int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Handles the core logic for navigating the maze and calculating scores.
     */
    static class MazeSolver {
        private static final char START_CHAR = 'S';
        private static final char END_CHAR = 'E';
        private static final char TRAP_CHAR = 'T';
        private static final int[][] DIRECTIONS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

        private final char[][] grid;
        private final int rows;
        private final int cols;
        private Point startNode;
        private Point endNode;

        public MazeSolver(char[][] grid, int rows, int cols) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
            findSpecialPoints();
        }

        /**
         * Locates the 'S' and 'E' points in the grid.
         */
        private void findSpecialPoints() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == START_CHAR) {
                        startNode = new Point(i, j);
                    } else if (grid[i][j] == END_CHAR) {
                        endNode = new Point(i, j);
                    }
                }
            }
        }

        /**
         * Executes the main algorithm:
         * 1. BFS from Start to find distance to End.
         * 2. BFS from End to find distances to all other cells.
         * 3. Sum digits that meet the distance criteria.
         */
        public int solve() {
            if (startNode == null || endNode == null) {
                return 0;
            }

            int[][] distFromStart = computeDistances(startNode);
            int shortestPathLen = distFromStart[endNode.r][endNode.c];

            // If end is unreachable, the original logic would return 0
            if (shortestPathLen == -1) {
                return 0;
            }

            int[][] distFromEnd = computeDistances(endNode);
            return calculateScore(shortestPathLen, distFromEnd);
        }

        /**
         * Performs a Breadth-First Search to find shortest distances from a source.
         */
        private int[][] computeDistances(Point source) {
            int[][] distances = new int[rows][cols];
            for (int[] row : distances) {
                Arrays.fill(row, -1);
            }

            Queue<Point> queue = new ArrayDeque<>();
            distances[source.r][source.c] = 0;
            queue.add(source);

            while (!queue.isEmpty()) {
                Point curr = queue.poll();

                for (int[] dir : DIRECTIONS) {
                    int nr = curr.r + dir[0];
                    int nc = curr.c + dir[1];

                    if (isValidMove(nr, nc) && distances[nr][nc] == -1) {
                        distances[nr][nc] = distances[curr.r][curr.c] + 1;
                        queue.add(new Point(nr, nc));
                    }
                }
            }
            return distances;
        }

        private boolean isValidMove(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] != TRAP_CHAR;
        }

        /**
         * Aggregates the values of digits based on the puzzle rules.
         */
        private int calculateScore(int shortestPathLen, int[][] distFromEnd) {
            int score = 0;
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    char cell = grid[i][j];
                    if (Character.isDigit(cell)) {
                        int d = distFromEnd[i][j];
                        // Based on original logic: dist(End, Cell) <= dist(Start, End)
                        // and the cell must be reachable from End.
                        if (d != -1 && d <= shortestPathLen) {
                            score += Character.getNumericValue(cell);
                        }
                    }
                }
            }
            return score;
        }
    }

    /**
     * Utility class for fast input reading.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(java.io.InputStream is) {
            reader = new BufferedReader(new InputStreamReader(is));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public char[][] readGrid(int rows, int cols) throws IOException {
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }
            return grid;
        }
    }
}

