/**
 * Contains the core logic for solving the grid puzzle.
 */
class GridSolver {
    private static final int[][] DIRECTIONS = {
        {1, 0}, {-1, 0}, {0, 1}, {0, -1}
    };

    private final FastReader reader;

    public GridSolver(FastReader reader) {
        this.reader = reader;
    }

    public void solve(PrintWriter out) throws IOException {
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        char[][] cellData = new char[rows][cols];
        Point startPoint = null;
        Point exitPoint = null;

        for (int i = 0; i < rows; i++) {
            String line = reader.next();
            for (int j = 0; j < cols; j++) {
                cellData[i][j] = line.charAt(j);
                if (cellData[i][j] == 'S') {
                    startPoint = new Point(i, j);
                } else if (cellData[i][j] == 'E') {
                    exitPoint = new Point(i, j);
                }
            }
        }

        Grid grid = new Grid(rows, cols, cellData);
        int[][] distances = computeDistancesFrom(grid, exitPoint);

        // The distance from Exit to Start defines our threshold
        int maxAllowedDistance = distances[startPoint.row()][startPoint.col()];

        // If start point is unreachable from exit, distance will be -1
        if (maxAllowedDistance == -1) {
            out.println(0);
            return;
        }

        out.println(calculateDigitSum(grid, distances, maxAllowedDistance));
    }

    /**
     * Performs a BFS to find shortest distances from the exit point to all reachable cells.
     */
    private int[][] computeDistancesFrom(Grid grid, Point start) {
        int[][] distances = new int[grid.getRows()][grid.getCols()];
        for (int[] row : distances) {
            Arrays.fill(row, -1);
        }

        Queue<Point> queue = new ArrayDeque<>();
        distances[start.row()][start.col()] = 0;
        queue.add(start);

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            for (int[] dir : DIRECTIONS) {
                int nextR = current.row() + dir[0];
                int nextC = current.col() + dir[1];

                if (grid.isTraversable(nextR, nextC) && distances[nextR][nextC] == -1) {
                    distances[nextR][nextC] = distances[current.row()][current.col()] + 1;
                    queue.add(new Point(nextR, nextC));
                }
            }
        }
        return distances;
    }

    /**
     * Sums all digits in the grid that are within the specified distance from the exit.
     */
    private int calculateDigitSum(Grid grid, int[][] distances, int threshold) {
        int sum = 0;
        for (int r = 0; r < grid.getRows(); r++) {
            for (int c = 0; c < grid.getCols(); c++) {
                if (grid.isDigit(r, c) && distances[r][c] != -1 && distances[r][c] <= threshold) {
                    sum += grid.getDigitValue(r, c);
                }
            }
        }
        return sum;
    }
}

