/**
 * GridGameSolver calculates the total value of "fightable" entities 
 * reachable within a specific distance from enemy positions in a grid.
 */
public class GridGameSolver {

    private static final int[][] DIRECTIONS = {
        {0, 1}, {0, -1}, {1, 0}, {-1, 0}
    };

    private static final char ENEMY_CELL = 'E';
    private static final char START_CELL = 'S';
