     * Orchestrates the reading, solving, and outputting of the game logic.
     */
    public void run() throws IOException {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        int rows = reader.nextInt();
        int cols = reader.nextInt();
        char[][] grid = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            grid[i] = reader.nextString().toCharArray();
        }

        int totalFightValue = solve(rows, cols, grid);
        writer.println(totalFightValue);
        writer.flush();
        writer.close();
    }

    /**
     * Core logic to process the grid and calculate the fight value.
     */
    private int solve(int rows, int cols, char[][] grid) {
        int[][] distancesFromEnemies = computeDistancesFromEnemies(rows, cols, grid);

        int distanceToStart = findDistanceToStart(rows, cols, grid, distancesFromEnemies);

        return calculateSumWithinRange(rows, cols, grid, distancesFromEnemies, distanceToStart);
    }

    /**
     * Performs a Multi-source BFS to find the shortest distance from any 'E' cell to all other cells.
     */
    private int[][] computeDistancesFromEnemies(int rows, int cols, char[][] grid) {
        int[][] distances = new int[rows][cols];
        for (int[] row : distances) {
            Arrays.fill(row, -1);
        }

        Deque<Point> queue = new ArrayDeque<>();

        // Initialize BFS with all enemy positions
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == ENEMY_CELL) {
                    distances[r][c] = 0;
                    queue.add(new Point(r, c));
                }
            }
        }

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            for (int[] dir : DIRECTIONS) {
                int nextR = current.row + dir[0];
                int nextC = current.col + dir[1];

                if (isValidMove(nextR, nextC, rows, cols, grid) && distances[nextR][nextC] == -1) {
                    distances[nextR][nextC] = distances[current.row][current.col] + 1;
                    queue.add(new Point(nextR, nextC));
                }
            }
        }

        return distances;
    }

    private boolean isValidMove(int r, int c, int rows, int cols, char[][] grid) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] != OBSTACLE_CELL;
    }

    /**
     * Finds the distance from the closest enemy to the starting position 'S'.
     */
    private int findDistanceToStart(int rows, int cols, char[][] grid, int[][] distances) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == START_CELL) {
                    return distances[r][c];
                }
            }
        }
        return -1; // Should not happen based on problem constraints
    }

    /**
     * Sums up numeric characters in cells that are within the distance to 'S'.
     */
    private int calculateSumWithinRange(int rows, int cols, char[][] grid, int[][] distances, int maxRange) {
        if (maxRange < 0) return 0;

        int sum = 0;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int dist = distances[r][c];
                if (dist >= 0 && dist <= maxRange) {
                    if (isNumeric(grid[r][c])) {
                        sum += Character.getNumericValue(grid[r][c]);
                    }
                }
            }
        }
        return sum;
    }

    private boolean isNumeric(char ch) {
        return ch >= '0' && ch <= '9';
    }

    /**
     * Simple data structure to represent a coordinate.
     */
    private static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * High-performance input reader.
     */
    private static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String nextString() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(nextString());
        }
    }
}

