/**
 * Main entry point for the Grid Solver application.
 */
public class GridSolverMain {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        GridSolver solver = new GridSolver();
        // The original code had a loop for 't' test cases, currently set to 1.
        int testCases = 1;
        for (int i = 0; i < testCases; i++) {
            solver.solve(reader, writer);
        }

        writer.flush();
        writer.close();
    }

    /**
     * Handles the core logic of traversing the grid and collecting values.
     */
    static class GridSolver {
        private static final char ENEMY = 'E';
        private static final char START = 'S';
        private static final char TRAP = 'T';

        // Direction vectors for 4-directional movement (Up, Down, Left, Right)
        private static final int[] DX = {1, -1, 0, 0};
        private static final int[] DY = {0, 0, 1, -1};

        /**
         * Represents a single cell in the BFS queue.
         */
        private static class Node {
            int x, y, distance;

            Node(int x, int y, int distance) {
                this.x = x;
                this.y = y;
                this.distance = distance;
            }
        }

        public void solve(FastReader in, PrintWriter out) {
            int rows = in.nextInt();
            int cols = in.nextInt();

            char[][] grid = new char[rows][cols];
            int startX = 0, startY = 0;
            Queue<Node> queue = new LinkedList<>();

            // Initialize grid and find starting points
            for (int i = 0; i < rows; i++) {
                String rowString = in.next();
                grid[i] = rowString.toCharArray();
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == ENEMY) {
                        queue.add(new Node(i, j, 0));
                    } else if (grid[i][j] == START) {
                        startX = i;
                        startY = j;
                    }
                }
            }

            int totalValue = 0;
            int distToStart = Integer.MAX_VALUE;
            boolean hasReachedStart = false;

            // Tracking visited nodes and their distances
            boolean[][] visited = new boolean[rows][cols];
            int[][] distances = new int[rows][cols];

            while (!queue.isEmpty()) {
                Node current = queue.poll();

                if (visited[current.x][current.y]) {
                    continue;
                }
                visited[current.x][current.y] = true;
                distances[current.x][current.y] = current.distance;

                // Check if we reached the 'S' node
                if (grid[current.x][current.y] == START) {
                    hasReachedStart = true;
                    distToStart = current.distance;
                }

                // Stop BFS if we have already passed the distance at which 'S' was found
                if (hasReachedStart && current.distance > distToStart) {
                    break;
                }

                // Accumulate digit values found in cells
                if (Character.isDigit(grid[current.x][current.y])) {
                    totalValue += Character.getNumericValue(grid[current.x][current.y]);
                }

                // Explore neighbors
                for (int i = 0; i < 4; i++) {
                    int nextX = current.x + DX[i];
                    int nextY = current.y + DY[i];

                    if (isValidMove(grid, visited, rows, cols, nextX, nextY)) {
                        queue.add(new Node(nextX, nextY, current.distance + 1));
                    }
                }
            }

            out.println(totalValue);
        }

        private boolean isValidMove(char[][] grid, boolean[][] visited, int rows, int cols, int x, int y) {
            return x >= 0 && x < rows && 
                   y >= 0 && y < cols && 
                   !visited[x][y] && 
                   grid[x][y] != TRAP && 
                   grid[x][y] != ENEMY;
        }
    }

    /**
     * Efficient utility class for reading input.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }
}

