/**
 * Represents a coordinate in the 2D grid.
 */
record Point(int row, int col) {}

/**
 * Solves the grid traversal problem using Breadth-First Search.
 */
class GridPathSolver {
    private static final int[][] DIRECTIONS = {
        {0, 1}, {0, -1}, {1, 0}, {-1, 0}
    };

    private static final char EXIT = 'E';
    private static final char TRAP = 'T';
    private static final char START = 'S';

    public void solve(FastReader reader, PrintWriter writer) {
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        char[][] grid = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            grid[r] = reader.next().toCharArray();
        }

        int[][] distanceMap = computeDistancesFromExits(grid, rows, cols);
        int startDistance = findStartDistance(grid, distanceMap, rows, cols);

        long totalValueSum = calculateDigitSum(grid, distanceMap, rows, cols, startDistance);

        writer.println(totalValueSum);
    }

    /**
     * Performs a multi-source BFS starting from all 'E' (Exit) cells.
     * Returns a 2D array containing the shortest distance to the nearest Exit.
     */
    private int[][] computeDistancesFromExits(char[][] grid, int rows, int cols) {
        int[][] distanceMap = new int[rows][cols];
        for (int[] row : distanceMap) {
            Arrays.fill(row, -1);
        }

        Deque<Point> queue = new ArrayDeque<>();

        // Initialize BFS with all exit points
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == EXIT) {
                    distanceMap[r][c] = 0;
                    queue.add(new Point(r, c));
                }
            }
        }

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            for (int[] dir : DIRECTIONS) {
                int nr = current.row() + dir[0];
                int nc = current.col() + dir[1];

                if (isWithinBounds(nr, nc, rows, cols) 
                        && grid[nr][nc] != TRAP 
                        && distanceMap[nr][nc] == -1) {

                    distanceMap[nr][nc] = distanceMap[current.row()][current.col()] + 1;
                    queue.add(new Point(nr, nc));
                }
            }
        }

        return distanceMap;
    }

    /**
     * Locates the 'S' cell and returns its distance to the nearest exit.
     */
    private int findStartDistance(char[][] grid, int[][] distanceMap, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == START) {
                    return distanceMap[r][c];
                }
            }
        }
        return -1; // Start not found or unreachable
    }

    /**
     * Sums the values of all digit cells reachable within the threshold distance.
     */
    private long calculateDigitSum(char[][] grid, int[][] distanceMap, int rows, int cols, int threshold) {
        long sum = 0;
        // If start is unreachable, threshold is -1. 
        // The condition (dist >= 0 && dist <= -1) will correctly result in 0.
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                char cellValue = grid[r][c];
                int dist = distanceMap[r][c];

                if (Character.isDigit(cellValue) && dist >= 0 && dist <= threshold) {
                    sum += Character.getNumericValue(cellValue);
                }
            }
        }
        return sum;
    }

    private boolean isWithinBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

