import java.util.*;

/**
 * A program to calculate the total battle value of cells within a specific 
 * reachability distance in a forest grid.
 */
public class BiridianForest {

    // Constants for grid markers to improve maintainability
    private static final char START_NODE = 'S';
    private static final char EXIT_NODE = 'E';
    private static final char TREE_OBSTACLE = 'T';

    // Direction vectors for traversing the grid (Up, Left, Down, Right)
    private static final int[] ROW_OFFSETS = {-1, 0, 1, 0};
    private static final int[] COL_OFFSETS = {0, -1, 0, 1};

    /**
     * Represents a coordinate pair in the forest grid.
     */
    private record Point(int row, int col) {}

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        scanner.nextLine(); // Consume the remaining newline

        char[][] forestGrid = new char[rows][cols];
        Point startPoint = null;
        Point exitPoint = null;

        // Input parsing and identifying start/exit positions
        for (int r = 0; r < rows; r++) {
            String line = scanner.nextLine();
            forestGrid[r] = line.toCharArray();
            for (int c = 0; c < cols; c++) {
                if (forestGrid[r][c] == START_NODE) {
                    startPoint = new Point(r, c);
                } else if (forestGrid[r][c] == EXIT_NODE) {
                    exitPoint = new Point(r, c);
                }
            }
        }

        // Handle cases where start or exit are not provided in the input
        if (startPoint == null || exitPoint == null) {
            System.out.println(0);
            return;
        }

        ForestAnalyzer analyzer = new ForestAnalyzer(forestGrid, rows, cols);
        int result = analyzer.calculateTotalBattles(startPoint, exitPoint);
        System.out.println(result);
    }

    /**
     * Encapsulates the logic for analyzing the forest grid and calculating distances.
     */
    static class ForestAnalyzer {
        private final char[][] grid;
        private final int rows;
        private final int cols;

        public ForestAnalyzer(char[][] grid, int rows, int cols) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
        }

        /**
         * Calculates the sum of battles for cells that meet the distance criteria.
         * 
         * @param start The starting point 'S'
         * @param exit The exit point 'E'
         * @return Total battle value
         */
        public int calculateTotalBattles(Point start, Point exit) {
            int[][] distancesFromStart = computeShortestDistances(start);
            int exitDistance = distancesFromStart[exit.row()][exit.col()];

            // If the exit is unreachable from the start, the logic returns 0
            if (exitDistance == -1) {
                return 0;
            }

            int[][] distancesFromExit = computeShortestDistances(exit);
            int totalBattles = 0;

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (isBattleCell(r, c) && isWithinReach(distancesFromExit[r][c], exitDistance)) {
                        totalBattles += getBattleValue(r, c);
                    }
                }
            }

            return totalBattles;
        }

        /**
         * Computes the shortest distance from a source point to all other points using BFS.
         * 
         * @param source The starting point for BFS
         * @return A 2D array of distances, where -1 represents unreachable cells
         */
        private int[][] computeShortestDistances(Point source) {
            int[][] distances = new int[rows][cols];
            for (int[] row : distances) {
                Arrays.fill(row, -1);
            }

            Queue<Point> queue = new ArrayDeque<>();
            distances[source.row()][source.col()] = 0;
            queue.add(source);

            while (!queue.isEmpty()) {
                Point current = queue.poll();

                for (int i = 0; i < 4; i++) {
                    int nextRow = current.row() + ROW_OFFSETS[i];
                    int nextCol = current.col() + COL_OFFSETS[i];

                    if (isValidMove(nextRow, nextCol) && 
                        distances[nextRow][nextCol] == -1 && 
                        grid[nextRow][nextCol] != TREE_OBSTACLE) {

                        distances[nextRow][nextCol] = distances[current.row()][current.col()] + 1;
                        queue.add(new Point(nextRow, nextCol));
                    }
                }
            }
            return distances;
        }

        private boolean isValidMove(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        private boolean isBattleCell(int r, int c) {
            char cell = grid[r][c];
            // A cell is a battle cell if it's a digit and not the special markers
            return cell != START_NODE && cell != EXIT_NODE && Character.isDigit(cell);
        }

        private boolean isWithinReach(int distance, int limit) {
            return distance >= 0 && distance <= limit;
        }

        private int getBattleValue(int r, int c) {
            return Character.getNumericValue(grid[r][c]);
        }
    }
}

import java.util.*;

/**
 * A program to solve the Biridian Forest problem:
 * Finds the shortest path from the End (E) to the Start (S) and 
 * sums all berries (0-9) located within that shortest distance.
 */
public class BiridianForest {

    /**
     * Represents a coordinate in the 2D grid.
     */
    private record Point(int row, int col) {}

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private Point startPoint;
    private Point endPoint;

    private static final char START_CHAR = 'S';
    private static final char END_CHAR = 'E';
    private static final char OBSTACLE_CHAR = 'T';

    public BiridianForest(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        findSpecialPoints();
    }

    /**
     * Locates the Start (S) and End (E) positions within the grid.
     */
    private void findSpecialPoints() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == START_CHAR) {
                    startPoint = new Point(r, c);
                } else if (grid[r][c] == END_CHAR) {
                    endPoint = new Point(r, c);
                }
            }
        }
    }

    /**
     * Calculates distances from the End point to all reachable cells using BFS.
     * 
     * @return A 2D array where each cell contains the shortest distance from the End point.
     *         Cells that are unreachable or contain obstacles are marked with -1.
     */
    private int[][] calculateDistancesFromEnd() {
        int[][] distances = new int[rows][cols];
        for (int[] row : distances) {
            Arrays.fill(row, -1);
        }

        if (endPoint == null) return distances;

        Queue<Point> queue = new ArrayDeque<>();
        distances[endPoint.row()][endPoint.col()] = 0;
        queue.add(endPoint);

        int[] dRow = {0, 1, 0, -1};
        int[] dCol = {-1, 0, 1, 0};

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            for (int i = 0; i < 4; i++) {
                int nextR = current.row() + dRow[i];
                int nextC = current.col() + dCol[i];

                if (isValidMove(nextR, nextC, distances)) {
                    distances[nextR][nextC] = distances[current.row()][current.col()] + 1;
                    queue.add(new Point(nextR, nextC));
                }
            }
        }
        return distances;
    }

    private boolean isValidMove(int r, int c, int[][] distances) {
        return r >= 0 && r < rows && 
               c >= 0 && c < cols && 
               grid[r][c] != OBSTACLE_CHAR && 
               distances[r][c] == -1;
    }

    /**
     * Main logic to solve the problem.
     * 
     * @return The total sum of berries within the distance of the shortest path from E to S.
     */
    public int solve() {
        if (startPoint == null || endPoint == null) {
            return 0;
        }

        int[][] distances = calculateDistancesFromEnd();
        int shortestDistanceToStart = distances[startPoint.row()][startPoint.col()];

        // If the Start is unreachable from the End, return 0
        if (shortestDistanceToStart == -1) {
            return 0;
        }

        return sumBerriesWithinDistance(distances, shortestDistanceToStart);
    }

    private int sumBerriesWithinDistance(int[][] distances, int maxDistance) {
        int totalBerries = 0;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (isBerry(grid[r][c])) {
                    int dist = distances[r][c];
                    if (dist != -1 && dist <= maxDistance) {
                        totalBerries += Character.getNumericValue(grid[r][c]);
                    }
                }
            }
        }
        return totalBerries;
    }

    private boolean isBerry(char c) {
        return Character.isDigit(c);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String line = scanner.next();
            for (int j = 0; j < m; j++) {
                grid[i][j] = line.charAt(j);
            }
        }

        BiridianForest forest = new BiridianForest(n, m, grid);
        System.out.println(forest.solve());

        scanner.close();
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves a grid-based pathfinding problem where we calculate the sum of 
 * digit-valued cells that are closer to the End point than the Start point.
 */
public class GridPathSolver {

    // Represents a coordinate in the 2D grid
    private record Point(int row, int col) {}

    // Directional vectors for moving Up, Down, Left, and Right
    private static final int[] ROW_DIRECTION = {1, 0, -1, 0};
    private static final int[] COL_DIRECTION = {0, 1, 0, -1};
    private static final int UNREACHABLE_DISTANCE = 1_000_001;

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int[][] distances;
    private final boolean[][] visited;

    private int startRow, startCol;
    private int endRow, endCol;

    public GridPathSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.distances = new int[rows][cols];
        this.visited = new boolean[rows][cols];
        initializeMetadata();
    }

    /**
     * Scans the grid to locate the Start ('S') and End ('E') positions
     * and initializes distance tracking.
     */
    private void initializeMetadata() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                distances[i][j] = UNREACHABLE_DISTANCE;
                if (grid[i][j] == 'S') {
                    startRow = i;
                    startCol = j;
                } else if (grid[i][j] == 'E') {
                    endRow = i;
                    endCol = j;
                }
            }
        }
    }

    /**
     * Orchestrates the BFS and the final sum calculation.
     * @return The sum of reachable digits within the specified distance.
     */
    public long solve() {
        performBreadthFirstSearch();
        return calculateSumOfDigitsWithinRange();
    }

    /**
     * Performs BFS starting from the 'End' point to find shortest distances to all cells.
     */
    private void performBreadthFirstSearch() {
        Queue<Point> queue = new LinkedList<>();

        // BFS starts from the End point 'E'
        distances[endRow][endCol] = 0;
        visited[endRow][endCol] = true;
        queue.add(new Point(endRow, endCol));

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            for (int i = 0; i < 4; i++) {
                int nextRow = current.row + ROW_DIRECTION[i];
                int nextCol = current.col + COL_DIRECTION[i];

                if (isValidMove(nextRow, nextCol)) {
                    distances[nextRow][nextCol] = distances[current.row][current.col] + 1;
                    visited[nextRow][nextCol] = true;
                    queue.add(new Point(nextRow, nextCol));
                }
            }
        }
    }

    private boolean isValidMove(int r, int c) {
        return r >= 0 && r < rows && 
               c >= 0 && c < cols && 
               !visited[r][c] && 
               grid[r][c] != 'T';
    }

    /**
     * Sums all digits in the grid that are not 'S' or 'E' and whose 
     * distance from 'E' is less than or equal to 'S's distance from 'E'.
     */
    private long calculateSumOfDigitsWithinRange() {
        long sum = 0;
        int maxAllowedDistance = distances[startRow][startCol];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                char cellValue = grid[i][j];
                if (cellValue != 'S' && cellValue != 'E' && distances[i][j] <= maxAllowedDistance) {
                    if (Character.isDigit(cellValue)) {
                        sum += cellValue - '0';
                    }
                }
            }
        }
        return sum;
    }

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            int r = reader.nextInt();
            int c = reader.nextInt();

            char[][] grid = new char[r][c];
            for (int i = 0; i < r; i++) {
                String rowStr = reader.next();
                if (rowStr != null) {
                    grid[i] = rowStr.toCharArray();
                }
            }

            GridPathSolver solver = new GridPathSolver(r, c, grid);
            out.println(solver.solve());

        } catch (Exception e) {
            // Handle or log exception as per environment requirements
        } finally {
            out.close();
        }
    }

    /**
     * Optimized input reader for performance.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Queue;
import java.util.StringTokenizer;

/**
 * This program calculates the sum of digit values in a grid that are within 
 * a certain distance from an exit point, as determined by a shortest-path BFS.
 */
public class GridValueCalculator {

    private static final char START_CHAR = 'S';
    private static final char END_CHAR = 'E';
    private static final char TRAP_CHAR = 'T';
    private static final int[][] DIRECTIONS = {
        {-1, 0}, {0, 1}, {0, -1}, {1, 0}
    };

    public static void main(String[] args) {
        try {
            FastScanner scanner = new FastScanner(System.in);
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            char[][] grid = new char[rows][cols];
            int startRow = 0, startCol = 0;
            int endRow = 0, endCol = 0;

            for (int i = 0; i < rows; i++) {
                String line = scanner.next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                    if (grid[i][j] == START_CHAR) {
                        startRow = i;
                        startCol = j;
                    } else if (grid[i][j] == END_CHAR) {
                        endRow = i;
                        endCol = j;
                    }
                }
            }

            GridSolver solver = new GridSolver(rows, cols, grid);
            int result = solver.solve(startRow, startCol, endRow, endCol);
            System.out.println(result);

        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Logic handler for processing the grid and calculating the distance-based sum.
     */
    static class GridSolver {
        private final int rows;
        private final int cols;
        private final char[][] grid;

        public GridSolver(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
        }

        public int solve(int startRow, int startCol, int endRow, int endCol) {
            int[][] distances = computeDistancesFrom(endRow, endCol);

            // The distance threshold is the shortest path from the end to the start
            int maxAllowedDistance = distances[startRow][startCol];

            // If start is unreachable from end, maxAllowedDistance will be -1
            if (maxAllowedDistance == -1) {
                return 0;
            }

            return calculateSumWithinDistance(distances, maxAllowedDistance);
        }

        /**
         * Performs BFS to find the shortest distance from the exit to all reachable cells.
         */
        private int[][] computeDistancesFrom(int startR, int startC) {
            int[][] dist = new int[rows][cols];
            for (int[] row : dist) {
                Arrays.fill(row, -1);
            }

            Queue<Point> queue = new ArrayDeque<>();
            queue.offer(new Point(startR, startC));
            dist[startR][startC] = 0;

            while (!queue.isEmpty()) {
                Point current = queue.poll();

                for (int[] dir : DIRECTIONS) {
                    int nextR = current.r + dir[0];
                    int nextC = current.c + dir[1];

                    if (isValidMove(nextR, nextC) && dist[nextR][nextC] == -1 && grid[nextR][nextC] != TRAP_CHAR) {
                        dist[nextR][nextC] = dist[current.r][current.c] + 1;
                        queue.offer(new Point(nextR, nextC));
                    }
                }
            }
            return dist;
        }

        private boolean isValidMove(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        /**
         * Sums the digits in cells that are reachable and within the distance threshold.
         */
        private int calculateSumWithinDistance(int[][] distances, int maxDist) {
            int sum = 0;
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    int d = distances[r][c];
                    // Criteria: Reachable, within distance, and is a digit (not S, E, or T)
                    if (d != -1 && d <= maxDist && Character.isDigit(grid[r][c])) {
                        sum += grid[r][c] - '0';
                    }
                }
            }
            return sum;
        }
    }

    /**
     * Simple immutable data carrier for coordinates.
     */
    static class Point {
        final int r, c;
        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * High-performance input reader.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

