 * within the number of steps it takes to reach the starting position ('S').
 */
public class Main {
    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            BattleSolver solver = new BattleSolver(reader);
            int result = solver.solve();
            out.println(result);
        } catch (IOException e) {
