/**
 * Represents a coordinate and its distance from the source in the grid.
 */
class GridPosition {
    final int row;
    final int col;
    final int distance;

    public GridPosition(int row, int col, int distance) {
        this.row = row;
        this.col = col;
        this.distance = distance;
    }
}

/**
 * Manages the grid data and provides utility methods for coordinate validation.
 */
class Grid {
    private final char[][] cells;
    private final int rows;
    private final int cols;

    private static final char EXIT = 'E';
    private static final char START = 'S';
    private static final char OBSTACLE = 'T';

    public Grid(int rows, int cols, char[][] cells) {
        this.rows = rows;
        this.cols = cols;
        this.cells = cells;
    }

    public int getRows() { return rows; }
    public int getCols() { return cols; }

    public char getCell(int r, int c) {
        return cells[r][c];
    }

    public boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    public boolean isObstacle(int r, int c) {
        return cells[r][c] == OBSTACLE;
    }

    public boolean isExit(int r, int c) {
        return cells[r][c] == EXIT;
    }

    public boolean isStart(int r, int c) {
        return cells[r][c] == START;
    }

    public boolean isBattleCell(int r, int c) {
        char cell = cells[r][c];
        return Character.isDigit(cell) && cell > '0';
    }

    public int getBattleValue(int r, int c) {
        return Character.getNumericValue(cells[r][c]);
    }

    public GridPosition findFirstCell(java.util.function.BiPredicate<Integer, Integer> predicate) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (predicate.test(r, c)) {
                    return new GridPosition(r, c, 0);
                }
            }
        }
        return null;
    }
}

/**
 * Contains the core algorithm logic.
 */
class BattleSolver {
    private final Grid grid;
    private final FastReader reader;

    private static final int[][] DIRECTIONS = {{1, 0}, {0, 1}, {-1, 0}, {0, -1}};

    public BattleSolver(FastReader reader) throws IOException {
        this.reader = reader;
        int r = reader.nextInt();
        int c = reader.nextInt();
        char[][] cells = new char[r][c];
        for (int i = 0; i < r; i++) {
            cells[i] = reader.next().toCharArray();
        }
        this.grid = new Grid(r, c, cells);
    }

    public int solve() {
        GridPosition exitPos = grid.findFirstCell(grid::isExit);
        if (exitPos == null) return 0;

        int[][] distanceMap = computeDistancesFrom(exitPos);

        GridPosition startPos = grid.findFirstCell(grid::isStart);
        int maxAllowedSteps = (startPos != null) ? distanceMap[startPos.row][startPos.col] : 0;

        // If start is unreachable from exit, distances will be -1 or similar.
        // The original logic handles this by checking distance >= 0.
        return calculateBattleSum(distanceMap, maxAllowedSteps);
    }

    private int[][] computeDistancesFrom(GridPosition start) {
        int rows = grid.getRows();
        int cols = grid.getCols();
        int[][] distances = new int[rows][cols];
        boolean[][] visited = new boolean[rows][cols];

        for (int[] row : distances) Arrays.fill(row, -1);

        Queue<GridPosition> queue = new LinkedList<>();
        queue.add(start);
        visited[start.row][start.col] = true;

        while (!queue.isEmpty()) {
            GridPosition current = queue.poll();
            distances[current.row][current.col] = current.distance;

            for (int[] dir : DIRECTIONS) {
                int nr = current.row + dir[0];
                int nc = current.col + dir[1];

                if (grid.isWithinBounds(nr, nc) && !grid.isObstacle(nr, nc) && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    queue.add(new GridPosition(nr, nc, current.distance + 1));
                }
            }
        }
        return distances;
    }

    private int calculateBattleSum(int[][] distanceMap, int maxSteps) {
        int totalBattles = 0;
        for (int r = 0; r < grid.getRows(); r++) {
            for (int c = 0; c < grid.getCols(); c++) {
                if (grid.isBattleCell(r, c)) {
                    int dist = distanceMap[r][c];
                    // A battle counts if it's reachable within the steps taken to reach 'S'
                    if (dist >= 0 && dist <= maxSteps) {
                        totalBattles += grid.getBattleValue(r, c);
                    }
                }
            }
        }
        return totalBattles;
    }
}

