import java.io.IOException;
import java.io.PrintWriter;
import java.util.*;

/**
 * ProblemB solves a grid-based pathfinding problem where we find the shortest distance 
 * from an End point to a Start point and sum the costs of all cells encountered 
 * within that shortest distance.
 */
public class ProblemB {

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter writer = new PrintWriter(System.out)) {

            if (!scanner.hasNextInt()) return;

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            Grid grid = Grid.parse(scanner, rows, cols);
            Solver solver = new Solver(grid);

            int result = solver.solve();
            writer.println(result);
            writer.flush();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * Represents a single cell in the grid with its coordinate and cost.
     */
    static class Grid {
        private static final char START_CHAR = 'S';
        private static final char END_CHAR = 'E';
        private static final char OBSTACLE_CHAR = 'T';

        private final int[][] cellCosts;
        private final int rows;
        private final int cols;
        private final Point startPos;
        private final Point endPos;

        private record Point(int col, int row) {}

        private Grid(int rows, int cols, int[][] cellCosts, Point startPos, Point endPos) {
            this.rows = rows;
            this.cols = cols;
            this.cellCosts = cellCosts;
            this.startPos = startPos;
            this.endPos = endPos;
        }

        /**
         * Parses the grid input from the scanner.
         */
        public static Grid parse(Scanner sc, int rows, int cols) {
            int[][] costs = new int[rows][cols];
            Point start = null;
            Point end = null;

            for (int i = 0; i < rows; i++) {
                String line = sc.next();
                for (int j = 0; j < cols; j++) {
                    char c = line.charAt(j);
                    if (c == START_CHAR) {
                        start = new Point(j, i);
                    } else if (c == END_CHAR) {
                        end = new Point(j, i);
                    } else if (c == OBSTACLE_CHAR) {
                        costs[i][j] = -1; // Represent obstacle
                    } else if (Character.isDigit(c)) {
                        costs[i][j] = c - '0';
                    }
                }
            }
            return new Grid(rows, cols, costs, start, end);
        }

        public int getCost(int row, int col) {
            return cellCosts[row][col];
        }

        public boolean isObstacle(int row, int col) {
            return cellCosts[row][col] == -1;
        }

        public int getRows() { return rows; }
        public int getCols() { return cols; }
        public Point getStartPos() { return startPos; }
        public Point getEndPos() { return endPos; }
    }

    /**
     * Encapsulates the BFS logic to solve the problem.
     */
    static class Solver {
        private static final int[] DX = {1, 0, -1, 0};
        private static final int[] DY = {0, 1, 0, -1};

        private final Grid grid;

        private record Node(int col, int row, int distance) {}

        public Solver(Grid grid) {
            this.grid = grid;
        }

        /**
         * Executes BFS to find the shortest distance to the start and 
         * calculates the total cost of cells within that distance.
         */
        public int solve() {
            int rows = grid.getRows();
            int cols = grid.getCols();

            // Stores the sum of cell costs at each specific distance step
            int[] costsByDistance = new int[rows * cols + 1];
            boolean[][] visited = new boolean[rows][cols];
            Queue<Node> queue = new ArrayDeque<>();

            Grid.Point end = grid.getEndPos();
            Grid.Point start = grid.getStartPos();

            if (end == null || start == null) return 0;

            // Initialize BFS from the End point
            queue.add(new Node(end.col(), end.row(), 0));
            visited[end.row()][end.col()] = true;

            int shortestDistanceToStart = -1;

            while (!queue.isEmpty()) {
                Node current = queue.poll();

                // If we reached the Start position, record the distance
                if (current.col == start.col() && current.row == start.row()) {
                    shortestDistanceToStart = current.distance;
                }

                // Add cost of current cell to its distance bucket if it's a digit
                int cost = grid.getCost(current.row, current.col);
                if (cost >= 1) {
                    costsByDistance[current.distance] += cost;
                }

                // Explore neighbors
                for (int i = 0; i < 4; i++) {
                    int nextCol = current.col + DX[i];
                    int nextRow = current.row + DY[i];

                    if (isValidMove(nextRow, nextCol, rows, cols)) {
                        if (!visited[nextRow][nextCol]) {
                            visited[nextRow][nextCol] = true;
                            queue.add(new Node(nextCol, nextRow, current.distance + 1));
                        }
                    }
                }
            }

            return calculateTotalCost(costsByDistance, shortestDistanceToStart);
        }

        private boolean isValidMove(int r, int c, int maxR, int maxC) {
            return r >= 0 && r < maxR && c >= 0 && c < maxC && !grid.isObstacle(r, c);
        }

        private int calculateTotalCost(int[] costsByDistance, int maxDist) {
            if (maxDist == -1) return 0;
            int total = 0;
            for (int i = 0; i <= maxDist; i++) {
                total += costsByDistance[i];
            }
            return total;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A refactored solution for the Grid Digit Sum problem.
 * The goal is to find the shortest distance from 'S' to 'E' and sum up 
 * the values of digits reachable from 'E' within that distance.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            GridSolver solver = new GridSolver(rows, cols, grid);
            out.println(solver.solve());
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Represents a coordinate point in the grid.
     */
    static class Point {
        int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Handles the logic for solving a specific grid instance.
     */
    static class GridSolver {
        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        private static final int INF = Integer.MAX_VALUE;

        public GridSolver(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
        }

        public int solve() {
            List<Point> startPoints = new ArrayList<>();
            Point endPoint = null;

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == 'S') {
                        startPoints.add(new Point(i, j));
                    } else if (grid[i][j] == 'E') {
                        endPoint = new Point(i, j);
                    }
                }
            }

            if (endPoint == null) return 0;

            // 1. Calculate shortest distances from all 'S' points to all other cells
            int[][] distanceFromStart = computeDistances(startPoints, false);

            // 2. Determine the distance limit (S to E)
            int limit = distanceFromStart[endPoint.r][endPoint.c];
            if (limit == INF) return 0;

            // 3. Perform BFS from 'E' to sum up digits within the limit
            return sumDigitsWithinLimit(endPoint, limit);
        }

        /**
         * Standard BFS to calculate shortest distances from a set of starting points.
         * @param starts The collection of starting coordinates.
         * @param ignoreS If true, 'S' cells are treated as walls during this BFS.
         * @return A 2D array of shortest distances.
         */
        private int[][] computeDistances(List<Point> starts, boolean ignoreS) {
            int[][] dist = new int[rows][cols];
            for (int[] row : dist) Arrays.fill(row, INF);
            Queue<Point> queue = new LinkedList<>();

            for (Point p : starts) {
                dist[p.r][p.c] = 0;
                queue.add(p);
            }

            while (!queue.isEmpty()) {
                Point curr = queue.poll();

                for (int[] dir : directions) {
                    int nr = curr.r + dir[0];
                    int nc = curr.c + dir[1];

                    if (isValid(nr, nc) && dist[nr][nc] == INF && grid[nr][nc] != 'T') {
                        // If ignoreS is true, we treat 'S' as an obstacle
                        if (ignoreS && grid[nr][nc] == 'S') continue;

                        dist[nr][nc] = dist[curr.r][curr.c] + 1;
                        queue.add(new Point(nr, nc));
                    }
                }
            }
            return dist;
        }

        /**
         * BFS starting from 'E' to sum digits reachable within the distance limit.
         * Replicates original logic where 'S' and 'E' are not included in the sum.
         */
        private int sumDigitsWithinLimit(Point endPoint, int limit) {
            int[][] distFromEnd = new int[rows][cols];
            for (int[] row : distFromEnd) Arrays.fill(row, INF);
            boolean[][] visited = new boolean[rows][cols];

            Queue<Point> queue = new LinkedList<>();
            queue.add(endPoint);
            distFromEnd[endPoint.r][endPoint.c] = 0;
            visited[endPoint.r][endPoint.c] = true;

            int totalSum = 0;

            while (!queue.isEmpty()) {
                Point curr = queue.poll();

                // If current distance exceeds limit, no need to process neighbors
                if (distFromEnd[curr.r][curr.c] >= limit) continue;

                for (int[] dir : directions) {
                    int nr = curr.r + dir[0];
                    int nc = curr.c + dir[1];

                    if (isValid(nr, nc) && !visited[nr][nc] && grid[nr][nc] != 'T') {
                        // Original logic treats 'S' and 'E' as boundaries for the digit sum
                        if (grid[nr][nc] == 'S' || grid[nr][nc] == 'E') {
                            visited[nr][nc] = true;
                            distFromEnd[nr][nc] = distFromEnd[curr.r][curr.c] + 1;
                            continue;
                        }

                        visited[nr][nc] = true;
                        distFromEnd[nr][nc] = distFromEnd[curr.r][curr.c] + 1;
                        queue.add(new Point(nr, nc));

                        if (Character.isDigit(grid[nr][nc])) {
                            totalSum += (grid[nr][nc] - '0');
                        }
                    }
                }
            }
            return totalSum;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * Fast I/O utility.
     */
    static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
