import java.util.*;

/**
 * A program to calculate the total battle count in a forest based on 
 * the shortest path from an entrance to a station.
 */
public class BiridianForest {

    private static final char EXIT_CHAR = 'E';
    private static final char STATION_CHAR = 'S';
    private static final char TREE_CHAR = 'T';

    /**
     * Represents a coordinate in the forest grid.
     */
    private static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
        int columns = scanner.nextInt();
        char[][] grid = new char[rows][columns];

        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        System.out.println(calculateTotalBattles(grid, rows, columns));
        scanner.close();
    }

    /**
     * Orchestrates the logic to find the required steps and sum the battles.
     */
    private static int calculateTotalBattles(char[][] grid, int rows, int columns) {
        Point exitPoint = findPoint(grid, rows, columns, EXIT_CHAR);
        Point stationPoint = findPoint(grid, rows, columns, STATION_CHAR);

        // If critical points are missing, no path can be determined.
        if (exitPoint == null || stationPoint == null) {
            return 0;
        }

        int[][] distanceMap = computeDistanceMap(grid, rows, columns, exitPoint);
        int requiredSteps = distanceMap[stationPoint.row][stationPoint.col];

        // If the station is unreachable, the original logic effectively results in 0 battles.
        if (requiredSteps == Integer.MAX_VALUE) {
            return 0;
        }

        return sumBattleValues(grid, rows, columns, distanceMap, requiredSteps);
    }

    /**
     * Finds the coordinates of a specific character in the grid.
     */
    private static Point findPoint(char[][] grid, int rows, int cols, char target) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == target) {
                    return new Point(r, c);
                }
            }
        }
        return null;
    }

    /**
     * Performs a Breadth-First Search (BFS) to find the shortest distance 
     * from the start point to all reachable cells.
     */
    private static int[][] computeDistanceMap(char[][] grid, int rows, int cols, Point start) {
        int[][] distances = new int[rows][cols];
        for (int[] row : distances) {
            Arrays.fill(row, Integer.MAX_VALUE);
        }

        Queue<Point> queue = new LinkedList<>();
        distances[start.row][start.col] = 0;
        queue.add(start);

        int[][] directions = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            for (int[] dir : directions) {
                int nextR = current.row + dir[0];
                int nextC = current.col + dir[1];

                if (isValidMove(grid, rows, cols, nextR, nextC, distances, current)) {
                    distances[nextR][nextC] = distances[current.row][current.col] + 1;
                    queue.add(new Point(nextR, nextC));
                }
            }
        }
        return distances;
    }

    /**
     * Helper to validate if a move is within bounds, not a tree, and not yet visited.
     */
    private static boolean isValidMove(char[][] grid, int rows, int cols, int r, int c, int[][] distances, Point current) {
        return r >= 0 && r < rows && 
               c >= 0 && c < cols && 
               grid[r][c] != TREE_CHAR && 
               distances[r][c] > distances[current.row][current.col] + 1;
    }

    /**
     * Iterates through the grid to sum digits of cells reachable within the required steps.
     */
    private static int sumBattleValues(char[][] grid, int rows, int cols, int[][] distanceMap, int limit) {
        int totalBattles = 0;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (Character.isDigit(grid[r][c]) && distanceMap[r][c] <= limit) {
                    totalBattles += Character.getNumericValue(grid[r][c]);
                }
            }
        }
        return totalBattles;
    }
}

import java.util.*;
import java.io.*;

/**
 * A solver for the Maze/Grid pathfinding problem.
 * Finds the sum of values in reachable cells within a specific distance limit.
 */
public class CF330D {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(new OutputStreamWriter(System.out));

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            MazeSolver solver = new MazeSolver(rows, cols, grid);
            long result = solver.solve();
            writer.println(result);
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    static class MazeSolver {
        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final int[][] distances;

        // Directions for 4-way movement (Up, Down, Left, Right)
        private static final int[] DR = {1, -1, 0, 0};
        private static final int[] DC = {0, 0, -1, 1};

        private Cell startCell = null;
        private Cell endCell = null;

        public MazeSolver(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            this.distances = new int[rows][cols];
            for (int i = 0; i < rows; i++) {
                Arrays.fill(distances[i], -1);
            }
            findSpecialCells();
        }

        private void findSpecialCells() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == 'S') {
                        startCell = new Cell(r, c);
                    } else if (grid[r][c] == 'E') {
                        endCell = new Cell(r, c);
                    }
                }
            }
        }

        /**
         * Core logic to solve the problem.
         * @return The sum of cell values within the distance limit.
         */
        public long solve() {
            if (endCell == null || startCell == null) {
                return 0;
            }

            // Step 1: Perform BFS from the end cell ('E') to find distances to all other cells
            performBfs(endCell);

            // Step 2: Determine the maximum allowed moves (distance from 'E' to 'S')
            int maxAllowedMoves = distances[startCell.r][startCell.c];
            if (maxAllowedMoves == -1) {
                return 0; // 'S' is unreachable from 'E'
            }

            // Step 3: Sum values of all valid cells within the move limit
            long totalValueSum = 0;
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    int dist = distances[r][c];
                    if (isValuableCell(r, c) && dist != -1 && dist <= maxAllowedMoves) {
                        totalValueSum += (grid[r][c] - '0');
                    }
                }
            }

            return totalValueSum;
        }

        private void performBfs(Cell start) {
            Queue<Cell> queue = new LinkedList<>();
            queue.add(start);
            distances[start.r][start.c] = 0;

            while (!queue.isEmpty()) {
                Cell current = queue.poll();

                for (int i = 0; i < 4; i++) {
                    int nr = current.r + DR[i];
                    int nc = current.c + DC[i];

                    if (isValidMove(nr, nc) && distances[nr][nc] == -1) {
                        distances[nr][nc] = distances[current.r][current.c] + 1;
                        queue.add(new Cell(nr, nc));
                    }
                }
            }
        }

        private boolean isValidMove(int r, int c) {
            // A move is valid if it's within bounds and not a wall ('T' or '*')
            return r >= 0 && r < rows && c >= 0 && c < cols 
                   && grid[r][c] != 'T' && grid[r][c] != '*';
        }

        private boolean isValuableCell(int r, int c) {
            char ch = grid[r][c];
            // In the original logic, any cell that is not 'S', 'E', or 'T' is added to the sum
            return ch != 'S' && ch != 'E' && ch != 'T';
        }
    }

    /**
     * Simple data carrier for grid coordinates.
     */
    static class Cell {
        final int r, c;
        Cell(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Fast I/O utility.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * GridPathAnalyzer calculates the shortest path distance between a start and end point
 * and finds the sum of digits reachable within that distance.
 */
public class GridPathAnalyzer {

    private static final char START_CHAR = 'S';
    private static final char END_CHAR = 'E';
    private static final char OBSTACLE_CHAR = 'T';
    private static final int[][] DIRECTIONS = {
            {1, 0},  // Down
            {-1, 0}, // Up
            {0, 1},  // Right
            {0, -1}  // Left
    };

    /**
     * Represents a coordinate in the 2D grid.
     */
    private static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        int rows = reader.nextInt();
        int cols = reader.nextInt();

        if (rows <= 0 || cols <= 0) {
            return;
        }

        char[][] grid = new char[rows][cols];
        Point startPoint = null;
        Point endPoint = null;

        // Parse grid and locate S and E
        for (int i = 0; i < rows; i++) {
            String line = reader.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] == START_CHAR) {
                    startPoint = new Point(i, j);
                } else if (grid[i][j] == END_CHAR) {
                    endPoint = new Point(i, j);
                }
            }
        }

        if (startPoint == null || endPoint == null) {
            System.out.println(0);
            return;
        }

        GridPathAnalyzer analyzer = new GridPathAnalyzer();
        int shortestDistance = analyzer.findShortestDistance(grid, startPoint, endPoint);
        int digitSum = analyzer.calculateDigitSumInRange(grid, endPoint, shortestDistance);

        System.out.println(digitSum);
    }

    /**
     * Performs BFS to find the shortest path from start to end.
     * 
     * @return Shortest distance, or 0 if unreachable.
     */
    private int findShortestDistance(char[][] grid, Point start, Point end) {
        int rows = grid.length;
        int cols = grid[0].length;

        Queue<Point> queue = new ArrayDeque<>();
        boolean[][] visited = new boolean[rows][cols];
        int[][] distanceMap = new int[rows][cols];

        queue.add(start);
        visited[start.row][start.col] = true;
        distanceMap[start.row][start.col] = 0;

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            if (current.row == end.row && current.col == end.col) {
                return distanceMap[end.row][end.col];
            }

            for (int[] dir : DIRECTIONS) {
                int nr = current.row + dir[0];
                int nc = current.col + dir[1];

                if (isValidMove(grid, nr, nc, visited)) {
                    visited[nr][nc] = true;
                    distanceMap[nr][nc] = distanceMap[current.row][current.col] + 1;
                    queue.add(new Point(nr, nc));
                }
            }
        }

        return 0; 
    }

    /**
     * Calculates the sum of all digits reachable from the end point within a specified distance.
     * Note: The search only expands through cells containing digits.
     * 
     * @param maxDist The maximum allowable distance from the end point.
     * @return The sum of digits found.
     */
    private int calculateDigitSumInRange(char[][] grid, Point end, int maxDist) {
        int rows = grid.length;
        int cols = grid[0].length;

        Queue<Point> queue = new ArrayDeque<>();
        boolean[][] visited = new boolean[rows][cols];
        int[][] distanceMap = new int[rows][cols];
        int totalSum = 0;

        queue.add(end);
        visited[end.row][end.col] = true;
        distanceMap[end.row][end.col] = 0;

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            for (int[] dir : DIRECTIONS) {
                int nr = current.row + dir[0];
                int nc = current.col + dir[1];

                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && !visited[nr][nc]) {
                    int nextDist = distanceMap[current.row][current.col] + 1;

                    if (nextDist <= maxDist) {
                        visited[nr][nc] = true;
                        distanceMap[nr][nc] = nextDist;

                        char cellValue = grid[nr][nc];
                        // If cell is a digit, add to sum and continue BFS expansion
                        if (isDigit(cellValue)) {
                            totalSum += (cellValue - '0');
                            queue.add(new Point(nr, nc));
                        } 
                        // If cell is S or E, mark visited but do not expand (matching original logic)
                        else if (cellValue != OBSTACLE_CHAR && cellValue != START_CHAR && cellValue != END_CHAR) {
                            // This handles cases where a cell might be something else, 
                            // but the original logic specifically looks for digits to expand.
                        }
                    }
                }
            }
        }
        return totalSum;
    }

    private boolean isValidMove(char[][] grid, int r, int c, boolean[][] visited) {
        return r >= 0 && r < grid.length &&
               c >= 0 && c < grid[0].length &&
               !visited[r][c] &&
               grid[r][c] != OBSTACLE_CHAR;
    }

    private boolean isDigit(char c) {
        return c >= '0' && c <= '9';
    }

    /**
     * Efficient reader for fast input processing.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Queue;
import java.util.StringTokenizer;

/**
 * GridMaximizer finds the maximum sum of digits reachable from a starting point 'S'
 * such that the path to the exit 'E' is not increased beyond the shortest possible path.
 */
public class GridMaximizer {

    // Constant for representing unvisited cells or unreachable paths
    private static final int INF = Integer.MAX_VALUE;

    // Direction vectors for moving Up, Down, Left, Right
    private static final int[] DX = {0, 1, 0, -1};
    private static final int[] DY = {1, 0, -1, 0};

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            char[][] grid = new char[rows][cols];
            int startX = -1, startY = -1;
            int exitX = -1, exitY = -1;

            // Parse the grid and locate 'S' (Start) and 'E' (Exit)
            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                    if (grid[i][j] == 'S') {
                        startX = i;
                        startY = j;
                    } else if (grid[i][j] == 'E') {
                        exitX = i;
                        exitY = j;
                    }
                }
            }

            // Handle edge case where S or E are missing
            if (startX == -1 || exitX == -1) {
                System.out.println(0);
                return;
            }

            // Step 1: Compute shortest distances from the Exit to all reachable cells using BFS
            int[][] distancesFromExit = computeShortestDistances(grid, rows, cols, exitX, exitY);

            // The threshold is the shortest distance from the Start to the Exit
            int maxAllowedDistance = distancesFromExit[startX][startY];

            // If the Exit is unreachable from the Start
            if (maxAllowedDistance == INF) {
                System.out.println(0);
                return;
            }

            // Step 2: Sum all digits that satisfy the distance constraint
            long totalValueSum = 0;
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (Character.isDigit(grid[i][j]) && distancesFromExit[i][j] <= maxAllowedDistance) {
                        totalValueSum += (grid[i][j] - '0');
                    }
                }
            }

            System.out.println(totalValueSum);

        } catch (Exception e) {
            // In a production environment, use a logger. For competitive programming, 
            // we handle basic input errors silently.
        }
    }

    /**
     * Uses Breadth-First Search to calculate shortest paths from a source point.
     * 
     * @param grid The character grid representing the map.
     * @param rows Number of rows in the grid.
     * @param cols Number of columns in the grid.
     * @param startX X-coordinate of the source.
     * @param startY Y-coordinate of the source.
     * @return A 2D array containing the shortest distance from the source to each cell.
     */
    private static int[][] computeShortestDistances(char[][] grid, int rows, int cols, int startX, int startY) {
        int[][] distances = new int[rows][cols];
        for (int[] row : distances) {
            Arrays.fill(row, INF);
        }

        Queue<Point> queue = new ArrayDeque<>();
        distances[startX][startY] = 0;
        queue.add(new Point(startX, startY));

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            for (int i = 0; i < 4; i++) {
                int nx = current.x + DX[i];
                int ny = current.y + DY[i];

                if (isValid(nx, ny, rows, cols) && grid[nx][ny] != 'T' && distances[nx][ny] == INF) {
                    distances[nx][ny] = distances[current.x][current.y] + 1;
                    queue.add(new Point(nx, ny));
                }
            }
        }

        return distances;
    }

    /**
     * Checks if a coordinate is within the bounds of the grid.
     */
    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Represents a 2D coordinate.
     */
    private static class Point {
        final int x, y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    /**
     * A high-performance input reader for large datasets.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            return (next == null) ? 0 : Integer.parseInt(next);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Queue;
import java.util.StringTokenizer;

/**
 * A program to calculate the sum of cell values within a certain distance 
 * from a starting point in a grid, where distances are calculated 
 * from an ending point.
 */
public class Main {

    public static void main(String[] args) {
        try {
            GridSolver solver = new GridSolver();
            solver.solve();
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Represents a coordinate in the 2D grid.
     */
    private static record Point(int row, int col) {}

    /**
     * Holds the grid data and configuration.
     */
    private static class Grid {
        private final int rows;
        private final int cols;
        private final int[][] cellValues;
        private final boolean[][] isBlocked;
        private int startRow, startCol;
        private int endRow, endCol;

        private static final int INF = 1_000_000_000;

        public Grid(int rows, int cols) {
            this.rows = rows;
            this.cols = cols;
            this.cellValues = new int[rows][cols];
            this.isBlocked = new boolean[rows][cols];

            for (int i = 0; i < rows; i++) {
                Arrays.fill(cellValues[i], 0);
            }
        }

        public void setStart(int r, int c) {
            this.startRow = r;
            this.startCol = c;
        }

        public void setEnd(int r, int c) {
            this.endRow = r;
            this.endCol = c;
        }

        public void setBlocked(int r, int c) {
            this.isBlocked[r][c] = true;
        }

        public void setValue(int r, int c, int val) {
            this.cellValues[r][c] = val;
        }

        public boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        public int getRows() { return rows; }
        public int getCols() { return cols; }
        public int getStartRow() { return startRow; }
        public int getStartCol() { return startCol; }
        public int getEndRow() { return endRow; }
        public int getEndCol() { return endCol; }
        public int getValue(int r, int c) { return cellValues[r][c]; }
        public boolean isBlocked(int r, int c) { return isBlocked[r][c]; }
        public int getInf() { return INF; }
    }

    /**
     * Contains the logic for parsing input and solving the problem.
     */
    private static class GridSolver {

        public void solve() throws IOException {
            BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
            String line = reader.readLine();
            if (line == null) return;

            StringTokenizer st = new StringTokenizer(line);
            int rows = Integer.parseInt(st.nextToken());
            int cols = Integer.parseInt(st.nextToken());

            Grid grid = new Grid(rows, cols);

            // Parse the grid
            for (int i = 0; i < rows; i++) {
                String rowString = reader.readLine();
                for (int j = 0; j < cols; j++) {
                    char c = rowString.charAt(j);
                    if (c == 'T') {
                        grid.setBlocked(i, j);
                    } else if (c == 'S') {
                        grid.setStart(i, j);
                    } else if (c == 'E') {
                        grid.setEnd(i, j);
                    } else if (Character.isDigit(c)) {
                        grid.setValue(i, j, c - '0');
                    }
                }
            }

            int[][] distances = computeDistancesFromEnd(grid);
            int result = calculateSumOfValuesWithinThreshold(grid, distances);

            System.out.println(result);
        }

        /**
         * Performs BFS starting from the 'End' point to find shortest paths to all reachable cells.
         */
        private int[][] computeDistancesFromEnd(Grid grid) {
            int[][] distances = new int[grid.getRows()][grid.getCols()];
            for (int[] row : distances) {
                Arrays.fill(row, grid.getInf());
            }

            boolean[][] visited = new boolean[grid.getRows()][grid.getCols()];
            Queue<Point> queue = new ArrayDeque<>();

            int endR = grid.getEndRow();
            int endC = grid.getEndCol();

            // Initialize BFS
            distances[endR][endC] = 0;
            visited[endR][endC] = true;
            queue.add(new Point(endR, endC));

            int[] dr = {1, -1, 0, 0};
            int[] dc = {0, 0, 1, -1};

            while (!queue.isEmpty()) {
                Point current = queue.poll();

                for (int i = 0; i < 4; i++) {
                    int nr = current.row() + dr[i];
                    int nc = current.col() + dc[i];

                    if (grid.isWithinBounds(nr, nc) && !grid.isBlocked(nr, nc) && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        distances[nr][nc] = distances[current.row()][current.col()] + 1;
                        queue.add(new Point(nr, nc));
                    }
                }
            }
            return distances;
        }

        /**
         * Sums the values of all cells whose distance from 'End' is less than or equal to 
         * the distance from 'End' to 'Start'.
         */
        private int calculateSumOfValuesWithinThreshold(Grid grid, int[][] distances) {
            int thresholdDistance = distances[grid.getStartRow()][grid.getStartCol()];
            int totalSum = 0;

            for (int r = 0; r < grid.getRows(); r++) {
                for (int c = 0; c < grid.getCols(); c++) {
                    if (distances[r][c] <= thresholdDistance) {
                        totalSum += grid.getValue(r, c);
                    }
                }
            }
            return totalSum;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver for the Maze Treasure problem.
 * The goal is to find the sum of all treasure values (digits) 
 * that are reachable within the distance it takes to travel from Start to End.
 */
public class MazeTreasureSolver {

    private static final int INF = Integer.MAX_VALUE / 3;
    private static final char START_CHAR = 'S';
    private static final char END_CHAR = 'E';
    private static final char TRAP_CHAR = 'T';
    private static final char EMPTY_CHAR = '0';

    private static final int[][] DIRECTIONS = {
        {-1, 0}, // Up
        {0, -1}, // Left
        {1, 0},  // Down
        {0, 1}   // Right
    };

    /**
     * Represents a coordinate in the 2D grid.
     */
    private static record Point(int row, int col) {}

    public static void main(String[] args) {
        try {
            FastReader reader = new FastReader(System.in);
            MazeSolver solver = new MazeSolver(reader);
            solver.solve();
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    private static class MazeSolver {
        private final FastReader reader;

        public MazeSolver(FastReader reader) {
            this.reader = reader;
        }

        public void solve() throws IOException {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] grid = new char[rows][cols];

            Point start = null;
            Point end = null;

            // 1. Load grid and locate Start (S) and End (E) positions
            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                grid[i] = line.toCharArray();
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == START_CHAR) {
                        start = new Point(i, j);
                        grid[i][j] = EMPTY_CHAR; // Treat as walkable path
                    } else if (grid[i][j] == END_CHAR) {
                        end = new Point(i, j);
                        grid[i][j] = EMPTY_CHAR; // Treat as walkable path
                    }
                }
            }

            if (start == null || end == null) {
                System.out.println(0);
                return;
            }

            // 2. Perform BFS from the End point to calculate distances to all cells
            int[][] distances = computeDistancesFrom(grid, end, rows, cols);

            // 3. Sum up values of treasure cells reachable within the start-to-end distance
            int totalTreasure = calculateTreasureSum(grid, distances, start, rows, cols);

            System.out.println(totalTreasure);
        }

        /**
         * Uses Breadth-First Search to find the shortest distance from the target point
         * to all other reachable points in the grid.
         */
        private int[][] computeDistancesFrom(char[][] grid, Point target, int rows, int cols) {
            int[][] distances = new int[rows][cols];
            for (int[] row : distances) {
                Arrays.fill(row, INF);
            }

            Queue<Point> queue = new ArrayDeque<>();
            distances[target.row()][target.col()] = 0;
            queue.add(target);

            while (!queue.isEmpty()) {
                Point current = queue.poll();

                for (int[] dir : DIRECTIONS) {
                    int nextRow = current.row() + dir[0];
                    int nextCol = current.col() + dir[1];

                    if (isValidMove(nextRow, nextCol, rows, cols, grid)) {
                        if (distances[nextRow][nextCol] > distances[current.row()][current.col()] + 1) {
                            distances[nextRow][nextCol] = distances[current.row()][current.col()] + 1;
                            queue.add(new Point(nextRow, nextCol));
                        }
                    }
                }
            }
            return distances;
        }

        private boolean isValidMove(int r, int c, int rows, int cols, char[][] grid) {
            return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] != TRAP_CHAR;
        }

        /**
         * Sums all digit characters where the distance from End to that cell
         * is less than or equal to the distance from End to Start.
         */
        private int calculateTreasureSum(char[][] grid, int[][] distances, Point start, int rows, int cols) {
            int sum = 0;
            int maxAllowedDistance = distances[start.row()][start.col()];

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    char cell = grid[i][j];
                    // If cell is a digit and within the distance threshold
                    if (Character.isDigit(cell) && distances[i][j] <= maxAllowedDistance) {
                        sum += cell - '0';
                    }
                }
            }
            return sum;
        }
    }

    /**
     * Fast I/O utility for efficient reading.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.LinkedList;
import java.util.Queue;
import java.util.StringTokenizer;

/**
 * BiridianForest solves a grid-based pathfinding problem where the goal is to 
 * sum the values of certain nodes reachable from an exit within a distance 
 * constraint determined by a starting position.
 */
public class BiridianForest {

    // Constants for grid cell types and movement
    private static final char TREE = 'T';
    private static final char START = 'S';
    private static final char END = 'E';
    private static final int[][] DIRECTIONS = {
        {1, 0}, {-1, 0}, {0, 1}, {0, -1}
    };

    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            String rowsInput = in.next();
            if (rowsInput == null) return;

            int rows = Integer.parseInt(rowsInput);
            int cols = in.nextInt();

            Forest forest = new Forest(rows, cols, in);
            int result = forest.solve();
            out.println(result);
        } catch (Exception e) {
            // In a production environment, use a logging framework.
        } finally {
            out.close();
        }
    }

    /**
     * Represents a coordinate in the 2D grid.
     */
    private static class Point {
        final int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Encapsulates the forest grid and the logic for pathfinding and calculation.
     */
    private static class Forest {
        private final int rows;
        private final int cols;
        private final char[][] grid;
        private Point startPoint;
        private Point endPoint;

        Forest(int rows, int cols, InputReader in) {
            this.rows = rows;
            this.cols = cols;
            this.grid = new char[rows][cols];
            initializeGrid(in);
        }

        private void initializeGrid(InputReader in) {
            for (int i = 0; i < rows; i++) {
                String line = in.next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                    if (grid[i][j] == START) {
                        startPoint = new Point(i, j);
                    } else if (grid[i][j] == END) {
                        endPoint = new Point(i, j);
                    }
                }
            }
        }

        /**
         * Orchestrates the BFS and the final calculation.
         */
        public int solve() {
            int[][] distanceMap = computeDistancesFromExit();
            return calculateReachableSum(distanceMap);
        }

        /**
         * Computes the shortest distance from the Exit ('E') to all reachable cells
         * using Breadth-First Search.
         * 
         * @return A 2D array of distances. -2 represents an obstacle (Tree), 
         *         -1 represents an unvisited path.
         */
        private int[][] computeDistancesFromExit() {
            int[][] distances = new int[rows][cols];

            // Initialize the distance map
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    // If it's a tree, it's an obstacle (-2), otherwise it's a potential path (-1)
                    distances[i][j] = (grid[i][j] == TREE) ? -2 : -1;
                }
            }

            if (endPoint == null) {
                return distances;
            }

            Queue<Point> queue = new LinkedList<>();
            queue.add(endPoint);
            distances[endPoint.r][endPoint.c] = 0;

            while (!queue.isEmpty()) {
                Point current = queue.poll();

                for (int[] dir : DIRECTIONS) {
                    int nextR = current.r + dir[0];
                    int nextC = current.c + dir[1];

                    if (isValid(nextR, nextC) && distances[nextR][nextC] == -1) {
                        distances[nextR][nextC] = distances[current.r][current.c] + 1;
                        queue.add(new Point(nextR, nextC));
                    }
                }
            }
            return distances;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        /**
         * Sums the values of cells '1'-'9' that are closer to the exit than the 
         * start point is.
         */
        private int calculateReachableSum(int[][] distances) {
            int sum = 0;
            int startDist = (startPoint != null) ? distances[startPoint.r][startPoint.c] : -1;

            // If start point is unreachable from exit, the sum is 0
            if (startDist < 0) {
                return 0;
            }

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    char cellValue = grid[i][j];
                    if (isDigit(cellValue) && distances[i][j] > 0) {
                        if (distances[i][j] <= startDist) {
                            sum += (cellValue - '0');
                        }
                    }
                }
            }
            return sum;
        }

        private boolean isDigit(char c) {
            return c >= '1' && c <= '9';
        }
    }

    /**
     * Fast I/O utility for efficient reading of large inputs.
     */
    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            return next != null ? Integer.parseInt(next) : 0;
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A solver for the grid-based pathfinding problem.
 * The goal is to sum all digits in a grid that are reachable from an exit 'E' 
 * within the same distance it takes to reach the starting point 'S'.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] grid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                String line = reader.nextLine();
                grid[i] = line.toCharArray();
            }

            GridSolver solver = new GridSolver(rows, cols, grid);
            System.out.println(solver.solve());

        } catch (Exception e) {
            // In a production environment, use a logger.
            e.printStackTrace();
        }
    }

    /**
     * Represents a coordinate in the 2D grid.
     */
    private static record Cell(int r, int c) {}

    /**
     * Handles the logic for grid traversal and sum calculation.
     */
    static class GridSolver {
        private final int rows;
        private final int cols;
        private final char[][] grid;

        private static final int[][] DIRECTIONS = {
            {1, 0}, {-1, 0}, {0, 1}, {0, -1}
        };
        private static final int UNVISITED = Integer.MAX_VALUE;

        public GridSolver(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
        }

        public int solve() {
            Cell startCell = null;
            Cell exitCell = null;

            // Locate Start (S) and Exit (E)
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == 'S') {
                        startCell = new Cell(i, j);
                    } else if (grid[i][j] == 'E') {
                        exitCell = new Cell(i, j);
                    }
                }
            }

            if (startCell == null || exitCell == null) {
                return 0;
            }

            // Calculate shortest distances from the exit to all reachable cells
            int[][] distances = bfs(exitCell);

            int maxAllowedDistance = distances[startCell.r()][startCell.c()];

            // If the start is unreachable from the exit
            if (maxAllowedDistance == UNVISITED) {
                return 0;
            }

            return calculateDigitSum(distances, maxAllowedDistance);
        }

        /**
         * Performs a Breadth-First Search starting from the given cell.
         * @return A 2D array of distances from the source.
         */
        private int[][] bfs(Cell source) {
            int[][] distances = new int[rows][cols];
            for (int[] row : distances) {
                Arrays.fill(row, UNVISITED);
            }

            Queue<Cell> queue = new ArrayDeque<>();

            distances[source.r()][source.c()] = 0;
            queue.add(source);

            while (!queue.isEmpty()) {
                Cell current = queue.poll();

                for (int[] dir : DIRECTIONS) {
                    int nr = current.r() + dir[0];
                    int nc = current.c() + dir[1];

                    if (isValidMove(nr, nc) && distances[nr][nc] == UNVISITED) {
                        distances[nr][nc] = distances[current.r()][current.c()] + 1;
                        queue.add(new Cell(nr, nc));
                    }
                }
            }
            return distances;
        }

        private boolean isValidMove(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] != 'T';
        }

        /**
         * Sums all digits in the grid where the distance from the exit 
         * is less than or equal to the distance to the start.
         */
        private int calculateDigitSum(int[][] distances, int maxDistance) {
            int sum = 0;
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    char cellChar = grid[i][j];
                    if (Character.isDigit(cellChar)) {
                        if (distances[i][j] <= maxDistance) {
                            sum += Character.getNumericValue(cellChar);
                        }
                    }
                }
            }
            return sum;
        }
    }

    /**
     * Faster input reader for large datasets.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public String nextLine() {
            if (tokenizer != null && tokenizer.hasMoreElements()) {
                StringBuilder sb = new StringBuilder();
                while (tokenizer.hasMoreElements()) {
                    sb.append(tokenizer.nextToken());
                    if (tokenizer.hasMoreElements()) sb.append(" ");
                }
                tokenizer = null;
                return sb.toString();
            }
            try {
                return reader.readLine();
            } catch (IOException e) {
                return null;
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Queue;
import java.util.StringTokenizer;

/**
 * ProblemSolver finds the sum of digits in a grid that are reachable from 
 * an 'End' point within the same number of steps it takes to reach the 'Start' point.
 */
public class MazeProblemSolver {

    private static final char START_CHAR = 'S';
    private static final char END_CHAR = 'E';
    private static final char OBSTACLE_CHAR = 'T';

    private static final int[][] DIRECTIONS = {
        {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            char[][] grid = new char[rows][cols];
            int startRow = -1, startCol = -1;
            int endRow = -1, endCol = -1;

            // Parse grid and locate Start (S) and End (E) positions
            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                grid[i] = line.toCharArray();
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == START_CHAR) {
                        startRow = i;
                        startCol = j;
                    } else if (grid[i][j] == END_CHAR) {
                        endRow = i;
                        endCol = j;
                    }
                }
            }

            // Find shortest distances from the End (E) to all other reachable cells
            int[][] distanceMap = computeDistancesFromEnd(grid, rows, cols, endRow, endCol);

            // Calculate result: sum of digits reachable within the distance to Start
            long totalSum = calculateDigitSum(grid, distanceMap, startRow, startCol);
            System.out.println(totalSum);

        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * Performs a Breadth-First Search starting from the End point.
     * @return A 2D array containing the shortest distance from 'E' to each cell.
     */
    private static int[][] computeDistancesFromEnd(char[][] grid, int rows, int cols, int endR, int endC) {
        int[][] distanceMap = new int[rows][cols];
        for (int[] row : distanceMap) {
            Arrays.fill(row, -1);
        }

        Queue<Node> queue = new ArrayDeque<>();

        // Initialize BFS from End point
        distanceMap[endR][endC] = 0;
        queue.add(new Node(endR, endC, 0));

        while (!queue.isEmpty()) {
            Node current = queue.poll();

            for (int[] dir : DIRECTIONS) {
                int nextR = current.row + dir[0];
                int nextC = current.col + dir[1];

                if (isValidMove(grid, rows, cols, nextR, nextC, distanceMap)) {
                    distanceMap[nextR][nextC] = current.distance + 1;
                    queue.add(new Node(nextR, nextC, current.distance + 1));
                }
            }
        }
        return distanceMap;
    }

    private static boolean isValidMove(char[][] grid, int rows, int cols, int r, int c, int[][] distanceMap) {
        return r >= 0 && r < rows && 
               c >= 0 && c < cols && 
               grid[r][c] != OBSTACLE_CHAR && 
               distanceMap[r][c] == -1;
    }

    /**
     * Sums digits where distance(End, digit) <= distance(End, Start).
     */
    private static long calculateDigitSum(char[][] grid, int[][] distanceMap, int startR, int startC) {
        long sum = 0;
        int maxAllowedDistance = distanceMap[startR][startC];

        // If Start is unreachable from End, maxAllowedDistance will be -1.
        // The condition below handles this naturally.
        if (maxAllowedDistance == -1) return 0;

        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                char cell = grid[i][j];
                if (Character.isDigit(cell)) {
                    int dist = distanceMap[i][j];
                    if (dist != -1 && dist <= maxAllowedDistance) {
                        sum += Character.getNumericValue(cell);
                    }
                }
            }
        }
        return sum;
    }

    /**
     * Represents a coordinate in the grid with its distance from the source.
     */
    private static class Node {
        final int row;
        final int col;
        final int distance;

        Node(int row, int col, int distance) {
            this.row = row;
            this.col = col;
            this.distance = distance;
        }
    }

    /**
     * Efficient reader for large inputs.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver for the grid-based pathfinding problem.
 * The goal is to find the shortest distance from an 'End' point to a 'Start' point
 * and sum the values of all cells reachable within that distance.
 */
public class Main {

    public static void main(String[] args) {
        try {
            GridSolver solver = new GridSolver(System.in);
            solver.solve(System.out);
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }
}

/**
 * Represents a coordinate in the 2D grid.
 */
record Point(int x, int y) {}

/**
 * Handles the grid data and the core logic of the pathfinding problem.
 */
class GridSolver {
    private static final int OBSTACLE = -1;
    private static final int UNVISITED_DISTANCE = Integer.MAX_VALUE / 2;

    private final FastReader reader;
    private int rows;
    private int cols;
    private int[][] grid;
    private Point startPoint;
    private Point endPoint;

    public GridSolver(InputStream inputStream) {
        this.reader = new FastReader(inputStream);
    }

    /**
     * Executes the primary logic: parsing, BFS, and summation.
     */
    public void solve(PrintStream out) throws IOException {
        parseGrid();
        int[][] distances = computeDistancesFromEnd();
        int totalValue = calculateSum(distances);
        out.println(totalValue);
    }

    private void parseGrid() throws IOException {
        this.rows = reader.nextInt();
        this.cols = reader.nextInt();
        this.grid = new int[rows][cols];

        for (int r = 0; r < rows; r++) {
            String line = reader.next();
            for (int c = 0; c < cols; c++) {
                char cell = line.charAt(c);
                switch (cell) {
                    case 'T' -> grid[r][c] = OBSTACLE;
                    case 'S' -> {
                        startPoint = new Point(c, r);
                        grid[r][c] = 0;
                    }
                    case 'E' -> {
                        endPoint = new Point(c, r);
                        grid[r][c] = 0;
                    }
                    default -> grid[r][c] = Character.getNumericValue(cell);
                }
            }
        }
    }

    /**
     * Performs a Breadth-First Search starting from the 'End' point.
     * 
     * @return A 2D array containing the shortest distance from the end point to every cell.
     */
    private int[][] computeDistancesFromEnd() {
        int[][] distances = new int[rows][cols];
        for (int[] row : distances) {
            Arrays.fill(row, UNVISITED_DISTANCE);
        }

        Deque<Point> queue = new ArrayDeque<>();

        if (endPoint != null) {
            distances[endPoint.y()][endPoint.x()] = 0;
            queue.addLast(endPoint);
        }

        int[] dx = {0, 0, -1, 1};
        int[] dy = {-1, 1, 0, 0};

        while (!queue.isEmpty()) {
            Point current = queue.removeFirst();

            for (int i = 0; i < 4; i++) {
                int nx = current.x() + dx[i];
                int ny = current.y() + dy[i];

                if (isWithinBounds(nx, ny) && grid[ny][nx] != OBSTACLE) {
                    if (distances[current.y()][current.x()] + 1 < distances[ny][nx]) {
                        distances[ny][nx] = distances[current.y()][current.x()] + 1;
                        queue.addLast(new Point(nx, ny));
                    }
                }
            }
        }
        return distances;
    }

    /**
     * Sums up the grid values for cells whose distance from the end is 
     * less than or equal to the distance from the end to the start.
     */
    private int calculateSum(int[][] distances) {
        int sum = 0;
        // If start point is not reachable, the distance remains UNVISITED_DISTANCE.
        // This matches the original logic where all reachable cells would then be summed.
        int maxAllowedDist = (startPoint != null) ? distances[startPoint.y()][startPoint.x()] : 0;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (distances[r][c] <= maxAllowedDist && grid[r][c] > 0) {
                    sum += grid[r][c];
                }
            }
        }
        return sum;
    }

    private boolean isWithinBounds(int x, int y) {
        return x >= 0 && x < cols && y >= 0 && y < rows;
    }

    /**
     * Utility class for efficient input reading.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream is) {
            this.reader = new BufferedReader(new InputStreamReader(is));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

