/**
 * Represents a coordinate in the 2D grid.
 */
record Point(int row, int col) {}

/**
 * Represents the forest grid and its properties.
 */
class Grid {
    private final int rows;
    private final int cols;
    private final int[][] cellValues;
    private Point startPos;
    private Point endPos;

    private static final char OBSTACLE = 'T';
    private static final char START = 'S';
    private static final char END = 'E';

    public Grid(int rows, int cols, FastReader reader) throws IOException {
        this.rows = rows;
        this.cols = cols;
        this.cellValues = new int[rows][cols];
        parseGrid(reader);
    }

    private void parseGrid(FastReader reader) throws IOException {
        for (int i = 0; i < rows; i++) {
            String line = reader.next();
            for (int j = 0; j < cols; j++) {
                char c = line.charAt(j);
                if (c == OBSTACLE) {
                    cellValues[i][j] = -1; // -1 represents an impassable obstacle
                } else if (c == START) {
                    startPos = new Point(i, j);
                    cellValues[i][j] = 0;
                } else if (c == END) {
                    endPos = new Point(i, j);
                    cellValues[i][j] = 0;
                } else {
                    cellValues[i][j] = Character.getNumericValue(c);
                }
            }
        }
    }

    public boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    public boolean isPassable(int r, int c) {
        return isWithinBounds(r, c) && cellValues[r][c] != -1;
    }

    public int getValue(int r, int c) {
        return cellValues[r][c];
    }

    public int getRows() { return rows; }
    public int getCols() { return cols; }
    public Point getStartPos() { return startPos; }
    public Point getEndPos() { return endPos; }
}

/**
 * Handles the core logic of solving the forest traversal problem.
 */
class ForestSolver {
    private static final int[] DR = {-1, 0, 1, 0};
    private static final int[] DC = {0, 1, 0, -1};

    private final FastReader reader;

    public ForestSolver(FastReader reader) {
        this.reader = reader;
    }

    public void solve(PrintWriter out) throws IOException {
        int rows = reader.nextInt();
        int cols = reader.nextInt();
        Grid grid = new Grid(rows, cols, reader);

        int[][] distances = computeDistancesFromEnd(grid);

        int maxDistanceAllowed = distances[grid.getStartPos().row()][grid.getStartPos().col()];
        out.println(calculateTotalValue(grid, distances, maxDistanceAllowed));
    }

    /**
     * Performs BFS starting from the End position to find shortest paths to all reachable cells.
     */
    private int[][] computeDistancesFromEnd(Grid grid) {
        int rows = grid.getRows();
        int cols = grid.getCols();
        int[][] distances = new int[rows][cols];
        for (int[] row : distances) Arrays.fill(row, -1);

        Deque<Point> queue = new ArrayDeque<>();
        Point end = grid.getEndPos();

        distances[end.row()][end.col()] = 0;
        queue.add(end);

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            for (int i = 0; i < 4; i++) {
                int nr = current.row() + DR[i];
                int nc = current.col() + DC[i];

                if (grid.isPassable(nr, nc) && distances[nr][nc] == -1) {
                    distances[nr][nc] = distances[current.row()][current.col()] + 1;
                    queue.add(new Point(nr, nc));
                }
            }
        }
        return distances;
    }

    /**
     * Sums the values of all cells within the distance threshold from the start.
     */
    private long calculateTotalValue(Grid grid, int[][] distances, int maxDistance) {
        if (maxDistance == -1) return 0; // Start is unreachable from end

        long sum = 0;
        for (int i = 0; i < grid.getRows(); i++) {
            for (int j = 0; j < grid.getCols(); j++) {
                int dist = distances[i][j];
                if (dist != -1 && dist <= maxDistance) {
                    sum += grid.getValue(i, j);
                }
            }
        }
        return sum;
    }
}

