 */
class ForestGrid {
    public static final char ENTRANCE = 'E';
    public static final char SANCTUARY = 'S';
    public static final char TREE = 'T';

    private final int rows;
    private final int cols;
    private final char[][] matrix;

    public ForestGrid(int rows, int cols, char[][] matrix) {
        this.rows = rows;
        this.cols = cols;
        this.matrix = matrix;
    }

