        return matrix[r][c];
    }

    public boolean isWalkable(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols && matrix[r][c] != TREE;
    }

    public Optional<Point> findCell(char target) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (matrix[i][j] == target) {
                    return Optional.of(new Point(i, j));
                }
            }
        }
        return Optional.empty();
    }
}

/**
 * Contains the logic to solve the Biridian Forest problem.
 */
class ForestSolver {
    private static final int[] ROW_DIRECTIONS = {1, -1, 0, 0};
    private static final int[] COL_DIRECTIONS = {0, 0, 1, -1};
    private static final int UNREACHABLE = Integer.MAX_VALUE;

    private final ForestGrid grid;

    public ForestSolver(ForestGrid grid) {
        this.grid = grid;
    }

    public int solve() {
        Optional<Point> entranceOpt = grid.findCell(ForestGrid.ENTRANCE);
        if (entranceOpt.isEmpty()) {
            return 0;
        }

        Point entrance = entranceOpt.get();
        int[][] distances = computeDistancesFrom(entrance);

        int sanctuaryDistance = findSanctuaryDistance(distances);

        // If sanctuary is unreachable, the distance remains UNREACHABLE.
        // The problem implies we sum digits reachable within the sanctuary distance.
        return calculateSumOfReachableDigits(distances, sanctuaryDistance);
    }

    /**
     * Standard BFS to find the shortest path from a starting point to all other reachable points.
     */
    private int[][] computeDistancesFrom(Point start) {
        int rows = grid.getRows();
        int cols = grid.getCols();
        int[][] distances = new int[rows][cols];
        for (int[] row : distances) {
            Arrays.fill(row, UNREACHABLE);
        }

        Queue<Point> queue = new LinkedList<>();
        distances[start.getRow()][start.getCol()] = 0;
        queue.add(start);

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            for (int i = 0; i < 4; i++) {
                int nextR = current.getRow() + ROW_DIRECTIONS[i];
                int nextC = current.getCol() + COL_DIRECTIONS[i];

                if (grid.isWalkable(nextR, nextC) && distances[nextR][nextC] == UNREACHABLE) {
                    distances[nextR][nextC] = distances[current.getRow()][current.getCol()] + 1;
                    queue.add(new Point(nextR, nextC));
                }
            }
        }
        return distances;
    }

    private int findSanctuaryDistance(int[][] distances) {
        for (int i = 0; i < grid.getRows(); i++) {
            for (int j = 0; j < grid.getCols(); j++) {
                if (grid.getCell(i, j) == ForestGrid.SANCTUARY) {
                    return distances[i][j];
                }
            }
        }
        return UNREACHABLE;
    }

    private int calculateSumOfReachableDigits(int[][] distances, int maxDistance) {
        // If sanctuary is unreachable, maxDistance is UNREACHABLE. 
        // Since distance can't be > Integer.MAX_VALUE, we handle logic carefully.
        if (maxDistance == UNREACHABLE) {
            return 0;
        }

        int totalSum = 0;
        for (int i = 0; i < grid.getRows(); i++) {
            for (int j = 0; j < grid.getCols(); j++) {
                char cell = grid.getCell(i, j);
                if (Character.isDigit(cell) && distances[i][j] <= maxDistance) {
                    totalSum += Character.getNumericValue(cell);
                }
            }
        }
        return totalSum;
    }
}

