/**
 * Handles the pathfinding and calculation logic.
 */
class MazeSolver {
    private static final int INF = (int) 1e9;
    private static final int[][] DIRECTIONS = {
        {1, 0}, {0, 1}, {0, -1}, {-1, 0}
    };

    private final Grid grid;

    public MazeSolver(Grid grid) {
        this.grid = grid;
    }

    /**
     * Calculates the shortest distance from the start point to all reachable cells using BFS.
     * @param start The starting Point.
     * @return A 2D array of distances.
     */
    public int[][] calculateDistances(Point start) {
        int rows = grid.getRows();
        int cols = grid.getCols();
        int[][] distances = new int[rows][cols];

        for (int[] row : distances) {
            Arrays.fill(row, INF);
        }

        Queue<Point> queue = new LinkedList<>();
        distances[start.x()][start.y()] = 0;
        queue.add(start);

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            for (int[] dir : DIRECTIONS) {
                int nx = current.x() + dir[0];
                int ny = current.y() + dir[1];

                if (isValidMove(nx, ny, distances)) {
                    distances[nx][ny] = distances[current.x()][current.y()] + 1;
                    queue.add(new Point(nx, ny));
                }
            }
        }
        return distances;
    }

    private boolean isValidMove(int x, int y, int[][] distances) {
        return grid.isWithinBounds(x, y) 
            && !grid.isObstacle(x, y) 
            && distances[x][y] == INF;
    }

    /**
     * Sums values of nodes that are closer to the exit than the start point is.
     */
    public int solve(Point exitPoint, Point startPoint, List<Point> valueNodes) {
        int[][] distances = calculateDistances(exitPoint);
        int targetDistance = distances[startPoint.x()][startPoint.y()];
        int totalSum = 0;

        for (Point node : valueNodes) {
            if (distances[node.x()][node.y()] <= targetDistance) {
                totalSum += grid.getCellValue(node.x(), node.y());
            }
        }
        return totalSum;
    }
}

