import java.io.*;
import java.util.*;

/**
 * BirdianForest solves the problem of calculating the sum of numeric values 
 * in a forest grid that are within a certain distance from the exit.
 */
public class BirdianForest {

    private static final char START_CHAR = 'S';
    private static final char END_CHAR = 'E';
    private static final char OBSTACLE_CHAR = 'T';
    private static final int INF = 1_000_000_000;

    private final int rows;
    private final int cols;
    private final char[][] grid;

    public BirdianForest(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
    }

    /**
     * Represents a single coordinate point in the grid.
     */
    private static class Node {
        int r, c, dist;

        Node(int r, int c, int dist) {
            this.r = r;
            this.c = c;
            this.dist = dist;
        }
    }

    /**
     * Performs a BFS to find the shortest distance from the exit to all reachable cells.
     * 
     * @param startR Starting row (Exit location)
     * @param startC Starting column (Exit location)
     * @return A 2D array containing minimum distances from the exit.
     */
    private int[][] computeDistancesFromExit(int startR, int startC) {
        int[][] distances = new int[rows][cols];
        for (int[] row : distances) {
            Arrays.fill(row, INF);
        }

        Deque<Node> queue = new ArrayDeque<>();
        distances[startR][startC] = 0;
        queue.add(new Node(startR, startC, 0));

        int[] dr = {1, -1, 0, 0};
        int[] dc = {0, 0, 1, -1};

        while (!queue.isEmpty()) {
            Node current = queue.poll();

            if (current.dist > distances[current.r][current.c]) {
                continue;
            }

            for (int i = 0; i < 4; i++) {
                int nr = current.r + dr[i];
                int nc = current.c + dc[i];

                if (isValidMove(nr, nc) && distances[nr][nc] > current.dist + 1) {
                    distances[nr][nc] = current.dist + 1;
                    queue.add(new Node(nr, nc, distances[nr][nc]));
                }
            }
        }
        return distances;
    }

    private boolean isValidMove(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] != OBSTACLE_CHAR;
    }

    /**
     * Calculates the final answer based on the distance to the start point.
     */
    public long solve() {
        int startR = -1, startC = -1;
        int endR = -1, endC = -1;

        // Locate S and E
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == START_CHAR) {
                    startR = i;
                    startC = j;
                } else if (grid[i][j] == END_CHAR) {
                    endR = i;
                    endC = j;
                }
            }
        }

        // If start or end is missing, return 0
        if (startR == -1 || endR == -1) return 0;

        int[][] distances = computeDistancesFromExit(endR, endC);
        int maxAllowedDist = distances[startR][startC];

        // If start is unreachable from end
        if (maxAllowedDist == INF) return 0;

        long totalSum = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (distances[i][j] <= maxAllowedDist) {
                    char cell = grid[i][j];
                    // Sum only numeric characters, excluding S, E, and T
                    if (Character.isDigit(cell)) {
                        totalSum += (cell - '0');
                    }
                }
            }
        }

        return totalSum;
    }

    public static void main(String[] args) {
        FastReader fr = new FastReader(System.in);
        PrintWriter pw = new PrintWriter(System.out);

        try {
            int n = fr.nextInt();
            int m = fr.nextInt();
            char[][] grid = new char[n][m];

            for (int i = 0; i < n; i++) {
                grid[i] = fr.next().toCharArray();
            }

            BirdianForest solver = new BirdianForest(n, m, grid);
            pw.println(solver.solve());
        } catch (Exception e) {
            // In a real-world app, use a logger
        } finally {
            pw.close();
        }
    }

    /**
     * Fast I/O utility.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

