/**
 * A program to calculate the total battle power in a forest 
 * based on proximity to an entrance and a target point.
 */
public class ViridianForest {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            ForestGrid forest = new ForestGrid(rows, cols, reader);
            ForestService service = new ForestService(forest);

            service.calculateDistances();
            long totalPower = service.calculatePowerWithinTargetRange();

            System.out.println(totalPower);
        } catch (Exception e) {
            System.err.println("Error processing forest data: " + e.getMessage());
        }
    }

    /**
     * Represents a coordinate in the grid.
     */
    record Point(int row, int col) {}

    /**
     * Constants representing specific cell types and values.
     */
    class CellConstants {
        static final int TREE = -1;
        static final int ENTRANCE = 0;
        static final int TARGET = -2;
    }

    /**
     * Holds the state and structure of the forest grid.
     */
    static class ForestGrid {
        private final int rows;
        private final int cols;
        private final int[][] grid;
        private Point entrance;
        private Point target;

        public ForestGrid(int rows, int cols, FastReader reader) {
            this.rows = rows;
            this.cols = cols;
            this.grid = new int[rows][cols];
            parseGrid(reader);
        }

        private void parseGrid(FastReader reader) {
            for (int i = 0; i < rows; i++) {
                String rowString = reader.next();
                for (int j = 0; j < cols; j++) {
                    char cellChar = rowString.charAt(j);
                    grid[i][j] = mapCharToValue(cellChar, i, j);
                }
            }
        }

        private int mapCharToValue(char c, int r, int col) {
            switch (c) {
                case 'T': return CellConstants.TREE;
                case 'E':
                    entrance = new Point(r, col);
                    return CellConstants.ENTRANCE;
                case 'S':
                    target = new Point(r, col);
                    return CellConstants.TARGET;
                default:
                    return Character.getNumericValue(c);
            }
        }

        public boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        public int getValue(int r, int c) { return grid[r][c]; }
        public int getRows() { return rows; }
        public int getCols() { return cols; }
        public Point getEntrance() { return entrance; }
        public Point getTarget() { return target; }
    }

    /**
     * Contains the business logic for traversing and analyzing the forest.
     */
    static class ForestService {
        private final ForestGrid forest;
        private final int[][] distanceMap;

        private static final int[] DR = {1, -1, 0, 0};
        private static final int[] DC = {0, 0, 1, -1};

        public ForestService(ForestGrid forest) {
            this.forest = forest;
            this.distanceMap = new int[forest.getRows()][forest.getCols()];
            for (int[] row : distanceMap) {
                Arrays.fill(row, Integer.MAX_VALUE);
            }
        }

        /**
         * Performs Breadth-First Search to find shortest paths from the entrance.
         */
        public void calculateDistances() {
            Point start = forest.getEntrance();
            if (start == null) return;

            Queue<Point> queue = new LinkedList<>();
            queue.add(start);
            distanceMap[start.row()][start.col()] = 0;

            while (!queue.isEmpty()) {
                Point current = queue.poll();

                for (int i = 0; i < 4; i++) {
                    int nr = current.row() + DR[i];
                    int nc = current.col() + DC[i];

                    if (forest.isValid(nr, nc) && 
                        forest.getValue(nr, nc) != CellConstants.TREE && 
                        distanceMap[nr][nc] == Integer.MAX_VALUE) {

                        distanceMap[nr][nc] = distanceMap[current.row()][current.col()] + 1;
                        queue.add(new Point(nr, nc));
                    }
                }
            }
        }

        /**
         * Sums values of cells reachable within the distance of the target point.
         */
        public long calculatePowerWithinTargetRange() {
            Point target = forest.getTarget();
            if (target == null) return 0;

            int maxAllowedDist = distanceMap[target.row()][target.col()];
            long totalPower = 0;

            for (int i = 0; i < forest.getRows(); i++) {
                for (int j = 0; j < forest.getCols(); j++) {
                    int val = forest.getValue(i, j);
                    // Exclude Trees and the Target itself from the sum
                    if (val != CellConstants.TREE && val != CellConstants.TARGET) {
                        if (distanceMap[i][j] <= maxAllowedDist) {
                            totalPower += val;
                        }
                    }
                }
            }
            return totalPower;
        }
    }

    /**
     * Optimized reader for fast I/O operations.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(java.io.InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

/**
 * A validator for Tic-Tac-Toe game states.
 * Determines if a given board state is illegal, a win, a draw, or whose turn it is.
 */
public class TicTacToe {

    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0';
    private static final char EMPTY = '.';

    private final char[][] board = new char[3][3];
    private int countX = 0;
    private int countO = 0;
    private int countEmpty = 0;

    public static void main(String[] args) {
        TicTacToe game = new TicTacToe();
        game.run();
    }

    /**
     * Orchestrates the execution of the program.
     */
    public void run() {
        Scanner sc = new Scanner(System.in);
        if (parseInput(sc)) {
            analyzeAndPrintResult();
        }
        sc.close();
    }

    /**
     * Reads 3 lines of input and populates the board.
     * @return true if input was parsed successfully.
     */
    private boolean parseInput(Scanner sc) {
        try {
            for (int i = 0; i < 3; i++) {
                String line = sc.nextLine();
                if (line.length() < 3) return false;

                for (int j = 0; j < 3; j++) {
                    char cell = line.charAt(j);
                    board[i][j] = cell;
                    updateCounts(cell);
                }
            }
            return true;
        } catch (Exception e) {
            return false;
        }
    }

    private void updateCounts(char cell) {
        if (cell == PLAYER_X) countX++;
        else if (cell == PLAYER_O) countO++;
        else if (cell == EMPTY) countEmpty++;
    }

    /**
     * Evaluates the board state and prints the appropriate status.
     */
    private void analyzeAndPrintResult() {
        boolean xWins = isWin(PLAYER_X);
        boolean oWins = isWin(PLAYER_O);

        if (isIllegal(xWins, oWins)) {
            System.out.println("illegal");
        } else if (xWins) {
            System.out.println("the first player won");
        } else if (oWins) {
            System.out.println("the second player won");
        } else if (countEmpty == 0) {
            System.out.println("draw");
        } else {
            // Determine whose turn it is
            if (countX == countO) {
                System.out.println("first");
            } else {
                System.out.println("second");
            }
        }
    }

    /**
     * Validates if the current piece counts and win states are consistent 
     * with the rules of Tic-Tac-Toe.
     */
    private boolean isIllegal(boolean xWins, boolean oWins) {
        // Rule 1: Piece counts must be valid (O cannot be more than X, and X cannot be more than O+1)
        if (countO > countX || countO < countX - 1) {
            return true;
        }

        // Rule 2: Both players cannot have winning configurations
        if (xWins && oWins) {
            return true;
        }

        // Rule 3: If X won, X must have made the last move (countX = countO + 1)
        if (xWins && countX != countO + 1) {
            return true;
        }

        // Rule 4: If O won, O must have made the last move (countX = countO)
        if (oWins && countX != countO) {
            return true;
        }

        return false;
    }

    /**
     * Checks if the specified player has a winning line.
     */
    private boolean isWin(char player) {
        // Check Rows and Columns
        for (int i = 0; i < 3; i++) {
            if (checkLine(board[i][0], board[i][1], board[i][2], player)) return true;
            if (checkLine(board[0][i], board[1][i], board[2][i], player)) return true;
        }

        // Check Diagonals
        if (checkLine(board[0][0], board[1][1], board[2][2], player)) return true;
        if (checkLine(board[0][2], board[1][1], board[2][0], player)) return true;

        return false;
    }

    private boolean checkLine(char c1, char c2, char c3, char player) {
        return c1 == player && c2 == player && c3 == player;
    }
}

import java.util.Scanner;

/**
 * A professional implementation of a Tic-Tac-Toe board state validator.
 * This program evaluates whether a 3x3 board is in a winning state, 
 * a draw, an illegal state, or whose turn it is next.
 */
public class TicTacToeValidator {

    private static final int SIZE = 3;

    /**
     * Represents the players available in the game.
     */
    private enum Player {
        EMPTY, X, O
    }

    /**
     * Represents the possible evaluation outcomes of a game board.
     */
    private enum GameStatus {
        ILLEGAL("illegal"),
        X_WON("the first player won"),
        O_WON("the second player won"),
        X_TURN("first"),
        O_TURN("second"),
        DRAW("draw");

        private final String message;

        GameStatus(String message) {
            this.message = message;
        }

        @Override
        public String toString() {
            return message;
        }
    }

    private final Player[][] board;
    private int xCount = 0;
    private int oCount = 0;

    public TicTacToeValidator(Player[][] board) {
        this.board = board;
        countPlayers();
    }

    /**
     * Calculates the number of X and O pieces on the board.
     */
    private void countPlayers() {
        for (int i = 0; i < SIZE; i++) {
            for (int j = 0; j < SIZE; j++) {
                if (board[i][j] == Player.X) {
                    xCount++;
                } else if (board[i][j] == Player.O) {
                    oCount++;
                }
            }
        }
    }

    /**
     * Evaluates the board state based on standard Tic-Tac-Toe rules.
     * 
     * @return The GameStatus of the current board.
     */
    public GameStatus evaluate() {
        boolean xWins = checkWinner(Player.X);
        boolean oWins = checkWinner(Player.O);

        // 1. Validate turn order/move counts.
        // Assuming Player X moves first: X must be equal to O (O's turn) 
        // or X must be O + 1 (X just moved).
        if (!(xCount == oCount || xCount == oCount + 1)) {
            return GameStatus.ILLEGAL;
        }

        // 2. Check for impossible scenarios (both winning simultaneously).
        if (xWins && oWins) {
            return GameStatus.ILLEGAL;
        }

        // 3. Check X winning condition.
        if (xWins) {
            // If X won, they must have just made the move that put them ahead.
            return (xCount == oCount + 1) ? GameStatus.X_WON : GameStatus.ILLEGAL;
        }

        // 4. Check O winning condition.
        if (oWins) {
            // If O won, the counts must be equal as O just completed their turn.
            return (xCount == oCount) ? GameStatus.O_WON : GameStatus.ILLEGAL;
        }

        // 5. Check for draw (no winner and board is full).
        if (isBoardFull()) {
            return GameStatus.DRAW;
        }

        // 6. Determine whose turn it is.
        return (xCount == oCount) ? GameStatus.X_TURN : GameStatus.O_TURN;
    }

    /**
     * Checks if a specific player has three in a row.
     */
    private boolean checkWinner(Player player) {
        // Check all rows and columns
        for (int i = 0; i < SIZE; i++) {
            if (hasThreeInARow(board[i][0], board[i][1], board[i][2], player)) return true;
            if (hasThreeInARow(board[0][i], board[1][i], board[2][i], player)) return true;
        }
        // Check both diagonals
        return hasThreeInARow(board[0][0], board[1][1], board[2][2], player) ||
               hasThreeInARow(board[0][2], board[1][1], board[2][0], player);
    }

    private boolean hasThreeInARow(Player p1, Player p2, Player p3, Player winner) {
        return p1 == winner && p2 == winner && p3 == winner;
    }

    private boolean isBoardFull() {
        return (xCount + oCount) == (SIZE * SIZE);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        Player[][] board = new Player[SIZE][SIZE];

        try {
            for (int i = 0; i < SIZE; i++) {
                if (!scanner.hasNext()) break;
                String row = scanner.next();
                for (int j = 0; j < SIZE; j++) {
                    char cell = row.charAt(j);
                    if (cell == 'X') {
                        board[i][j] = Player.X;
                    } else if (cell == 'O') {
                        board[i][j] = Player.O;
                    } else {
                        board[i][j] = Player.EMPTY;
                    }
                }
            }

            TicTacToeValidator validator = new TicTacToeValidator(board);
            System.out.println(validator.evaluate());

        } catch (Exception e) {
            // If input is malformed, treat as illegal
            System.out.println(GameStatus.ILLEGAL);
        } finally {
            scanner.close();
        }
    }
}

