/**
 * Represents the players in the Tic-Tac-Toe game.
 */
enum Player {
    NONE,
    X,
    O;

    /**
     * Parses a character into a Player enum.
     * Note: The original code used '0' (zero) as the second player.
     */
    public static Player fromChar(char c) {
        if (c == 'X') return X;
        if (c == '0') return O;
        return NONE;
    }
}

/**
 * Represents the possible outcomes of a Tic-Tac-Toe game evaluation.
 */
enum GameResult {
    FIRST_PLAYER_WON("the first player won"),
    SECOND_PLAYER_WON("the second player won"),
    DRAW("draw"),
    FIRST_TURN_NEXT("first"),
    SECOND_TURN_NEXT("second"),
    ILLEGAL("illegal");

    private final String message;

    GameResult(String message) {
        this.message = message;
    }

    @Override
    public String toString() {
        return this.message;
    }
