/**
 * Manages the state of the 3x3 Tic-Tac-Toe grid.
 */
class TicTacToeBoard {
    private static final int SIZE = 3;
    private final Player[][] grid = new Player[SIZE][SIZE];
    private int xCount = 0;
    private int oCount = 0;

    public TicTacToeBoard(String input) {
        parseInput(input);
    }

    private void parseInput(String input) {
        for (int i = 0; i < input.length() && i < SIZE * SIZE; i++) {
            int row = i / SIZE;
            int col = i % SIZE;
            Player p = Player.fromChar(input.charAt(i));
            grid[row][col] = p;
            if (p == Player.X) xCount++;
            else if (p == Player.O) oCount++;
        }
    }

    public int getXCount() { return xCount; }
    public int getOCount() { return oCount; }
    public boolean isFull() { return (xCount + oCount) == (SIZE * SIZE); }

    /**
     * Checks if a specific player has achieved a winning line.
     */
    public boolean checkWin(Player p) {
        if (p == Player.NONE) return false;

        // Check rows and columns
        for (int i = 0; i < SIZE; i++) {
            if (checkLine(grid[i][0], grid[i][1], grid[i][2], p)) return true;
            if (checkLine(grid[0][i], grid[1][i], grid[2][i], p)) return true;
        }

        // Check diagonals
        if (checkLine(grid[0][0], grid[1][1], grid[2][2], p)) return true;
        if (checkLine(grid[0][2], grid[1][1], grid[2][0], p)) return true;

        return false;
    }

    private boolean checkLine(Player p1, Player p2, Player p3, Player target) {
        return p1 == target && p2 == target && p3 == target;
    }
}

/**
 * Contains the business logic to evaluate the game state.
 */
class TicTacToeEvaluator {
    private final TicTacToeBoard board;

    public TicTacToeEvaluator(TicTacToeBoard board) {
        this.board = board;
    }

    public GameResult evaluate() {
        boolean xWon = board.checkWin(Player.X);
        boolean oWon = board.checkWin(Player.O);
        int xCount = board.getXCount();
        int oCount = board.getOCount();

        // 1. Check for winner scenarios
        if (xWon && !oWon && xCount == oCount + 1) {
            return GameResult.FIRST_PLAYER_WON;
        }
        if (oWon && !xWon && xCount == oCount) {
            return GameResult.SECOND_PLAYER_WON;
        }

        // 2. Check for draw scenario
        if (!xWon && !oWon && board.isFull()) {
            // In a full valid board, X must have 5 and O must have 4
            if (xCount == 5 && oCount == 4) {
                return GameResult.DRAW;
            }
            return GameResult.ILLEGAL;
        }

        // 3. Check for ongoing game (valid turn order)
        if (!xWon && !oWon) {
            if (xCount == oCount) {
                return GameResult.FIRST_TURN_NEXT; // X's turn
            } else if (xCount == oCount + 1) {
                return GameResult.SECOND_TURN_NEXT; // O's turn
            }
        }

        return GameResult.ILLEGAL;
    }
}

