import java.util.*;

/**
 * Analyzes the state of a 3x3 Tic-Tac-Toe game.
 * Determines if the game is valid, who won, if it's a draw, or whose turn it is.
 */
public class TicTacToeAnalyzer {

    private enum Cell {
        EMPTY,
        PLAYER_X,
        PLAYER_O
    }

    private enum GameState {
        ILLEGAL("illegal"),
        X_WON("the first player won"),
        O_WON("the second player won"),
        DRAW("draw"),
        X_TURN("first"),
        O_TURN("second");

        private final String message;

        GameState(String message) {
            this.message = message;
        }

        @Override
        public String toString() {
            return this.message;
        }
    }

    private static final int BOARD_SIZE = 3;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        Cell[][] board = new Cell[BOARD_SIZE][BOARD_SIZE];

        try {
            for (int i = 0; i < BOARD_SIZE; i++) {
                String line = scanner.nextLine();
                for (int j = 0; j < BOARD_SIZE; j++) {
                    board[i][j] = parseCell(line.charAt(j));
                }
            }

            GameState result = analyzeGame(board);
            System.out.println(result);
        } catch (Exception e) {
            System.out.println("illegal");
        } finally {
            scanner.close();
        }
    }

    /**
     * Maps characters to Cell types. 
     * Note: Original code used '0' (zero) for Player O.
     */
    private static Cell parseCell(char c) {
        return switch (c) {
            case 'X' -> Cell.PLAYER_X;
            case '0' -> Cell.PLAYER_O;
            default -> Cell.EMPTY;
        };
    }

    /**
     * Core logic to determine the state of the game.
     */
    public static GameState analyzeGame(Cell[][] board) {
        int xCount = 0;
        int oCount = 0;

        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                if (board[i][j] == Cell.PLAYER_X) xCount++;
                else if (board[i][j] == Cell.PLAYER_O) oCount++;
            }
        }

        boolean xWins = checkWin(board, Cell.PLAYER_X);
        boolean oWins = checkWin(board, Cell.PLAYER_O);

        // 1. Validation: Check for impossible move counts
        if (oCount > xCount || Math.abs(xCount - oCount) > 1) {
            return GameState.ILLEGAL;
        }

        // 2. Validation: Check if both players won simultaneously
        if (xWins && oWins) {
            return GameState.ILLEGAL;
        }

        // 3. Validation: Check if X won but it's O's turn (X must have made the last move)
        if (xWins && xCount == oCount) {
            return GameState.ILLEGAL;
        }

        // 4. Validation: Check if O won but X has more moves (O must have made the last move)
        if (oWins && xCount > oCount) {
            return GameState.ILLEGAL;
        }

        // Determine Outcome
        if (xWins) return GameState.X_WON;
        if (oWins) return GameState.O_WON;
        if (xCount + oCount == BOARD_SIZE * BOARD_SIZE) return GameState.DRAW;

        // Determine Turn
        return (xCount == oCount) ? GameState.X_TURN : GameState.O_TURN;
    }

    /**
     * Checks all possible winning combinations for a specific player.
     */
    private static boolean checkWin(Cell[][] board, Cell player) {
        // Check rows and columns
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (checkLine(board[i][0], board[i][1], board[i][2], player)) return true;
            if (checkLine(board[0][i], board[1][i], board[2][i], player)) return true;
        }

        // Check diagonals
        if (checkLine(board[0][0], board[1][1], board[2][2], player)) return true;
        if (checkLine(board[0][2], board[1][1], board[2][0], player)) return true;

        return false;
    }

    private static boolean checkLine(Cell c1, Cell c2, Cell c3, Cell player) {
        return c1 == player && c2 == player && c3 == player;
    }
}

import java.util.Scanner;

/**
 * Represents the possible outcomes of a Tic-Tac-Toe game state.
 */
enum GameStatus {
    ILLEGAL("illegal"),
    FIRST_PLAYER_WON("the first player won"),
    SECOND_PLAYER_WON("the second player won"),
    DRAW("draw"),
    FIRST_PLAYER_TURN("first"),
    SECOND_PLAYER_TURN("second");

    private final String message;

    GameStatus(String message) {
        this.message = message;
    }

    @Override
    public String toString() {
        return this.message;
    }
}

/**
 * Logic engine to evaluate the state of a Tic-Tac-Toe board.
 */
class TicTacToeEvaluator {
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_ZERO = '0';
    private static final int BOARD_SIZE = 9;

    // Winning combinations represented as indices in a 1D array
    private static final int[][] WINNING_COMBINATIONS = {
        {0, 1, 2}, {3, 4, 5}, {6, 7, 8}, // Rows
        {0, 3, 6}, {1, 4, 7}, {2, 5, 8}, // Columns
        {0, 4, 8}, {2, 4, 6}             // Diagonals
    };

    private final char[] board;
    private int countX = 0;
    private int countZero = 0;

    public TicTacToeEvaluator(char[] board) {
        this.board = board;
        calculateCounts();
    }

    private void calculateCounts() {
        for (char cell : board) {
            if (cell == PLAYER_X) countX++;
            else if (cell == PLAYER_ZERO) countZero++;
        }
    }

    public GameStatus evaluate() {
        if (!isTurnCountValid()) {
            return GameStatus.ILLEGAL;
        }

        boolean xWins = checkWin(PLAYER_X);
        boolean zeroWins = checkWin(PLAYER_ZERO);

        // Rule: Both players cannot have winning lines simultaneously
        if (xWins && zeroWins) {
            return GameStatus.ILLEGAL;
        }

        if (xWins) {
            // If X won, it must be X's turn that just ended (X count = Zero count + 1)
            return (countX == countZero + 1) ? GameStatus.FIRST_PLAYER_WON : GameStatus.ILLEGAL;
        }

        if (zeroWins) {
            // If 0 won, it must be 0's turn that just ended (X count = Zero count)
            return (countX == countZero) ? GameStatus.SECOND_PLAYER_WON : GameStatus.ILLEGAL;
        }

        return evaluateNonWinningState();
    }

    private boolean isTurnCountValid() {
        int diff = countX - countZero;
        // X goes first, so X must be equal to or one greater than 0.
        // The difference can only be 0 or 1.
        return diff == 0 || diff == 1;
    }

    private boolean checkWin(char player) {
        for (int[] combo : WINNING_COMBINATIONS) {
            if (board[combo[0]] == player && 
                board[combo[1]] == player && 
                board[combo[2]] == player) {
                return true;
            }
        }
        return false;
    }

    private GameStatus evaluateNonWinningState() {
        if (countX + countZero == BOARD_SIZE) {
            return GameStatus.DRAW;
        }
        // If board is not full and no one won, determine whose turn it is
        return (countX == countZero) ? GameStatus.FIRST_PLAYER_TURN : GameStatus.SECOND_PLAYER_TURN;
    }
}

public class Solution {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[] board = new char[9];

        try {
            for (int i = 0; i < 3; i++) {
                String line = scanner.nextLine();
                for (int j = 0; j < 3; j++) {
                    // Map 2D input to 1D array index
                    board[i * 3 + j] = line.charAt(j);
                }
            }

            TicTacToeEvaluator evaluator = new TicTacToeEvaluator(board);
            System.out.println(evaluator.evaluate());

        } catch (Exception e) {
            // In case of unexpected input format
            System.out.println("illegal");
        } finally {
            scanner.close();
        }
    }
}

