/**
 * Represents the players in the Tic Tac Toe game.
 */
enum Player {
    FIRST, SECOND, EMPTY;

    public static Player fromChar(char c) {
        return switch (c) {
            case 'X' -> FIRST;
            case 'O' -> SECOND;
            default -> EMPTY;
        };
    }
}

/**
 * Represents the possible outcomes of the game validation.
 */
enum GameStatus {
    FIRST_TURN("first"),
    SECOND_TURN("second"),
    DRAW("draw"),
    FIRST_PLAYER_WON("the first player won"),
    SECOND_PLAYER_WON("the second player won"),
    ILLEGAL("illegal");

    private final String message;

    GameStatus(String message) {
        this.message = message;
    }

    @Override
    public String toString() {
        return message;
    }
}

/**
 * Encapsulates the 3x3 Tic Tac Toe board.
 */
class TicTacToeBoard {
    private static final int SIZE = 3;
    private final Player[][] grid = new Player[SIZE][SIZE];

    public void setCell(int row, int col, Player player) {
        grid[row][col] = player;
    }

    public Player getCell(int row, int col) {
        return grid[row][col];
    }

    public int getSize() {
        return SIZE;
    }

    /**
     * Deep copies the current board state.
     */
    public TicTacToeBoard copy() {
        TicTacToeBoard newBoard = new TicTacToeBoard();
        for (int i = 0; i < SIZE; i++) {
            for (int j = 0; j < SIZE; j++) {
                newBoard.setCell(i, j, this.getCell(i, j));
            }
        }
        return newBoard;
    }
}

/**
 * Contains logic to validate the legality and state of a Tic Tac Toe board.
 */
class TicTacToeValidator {
    private final TicTacToeBoard board;

    public TicTacToeValidator(TicTacToeBoard board) {
        this.board = board;
    }

    public GameStatus validate() {
        int firstCount = 0;
        int secondCount = 0;

        for (int i = 0; i < board.getSize(); i++) {
            for (int j = 0; j < board.getSize(); j++) {
                Player p = board.getCell(i, j);
                if (p == Player.FIRST) firstCount++;
                else if (p == Player.SECOND) secondCount++;
            }
        }

        // Rule 1: Turn count must be valid (First player starts, so firstCount is either equal to or 1 greater than secondCount)
        if (firstCount - secondCount > 1 || firstCount - secondCount < 0) {
            return GameStatus.ILLEGAL;
        }

        int winCount = countWinningLines();

        if (winCount == 0) {
            int totalMoves = firstCount + secondCount;
            if (totalMoves == 9) {
                return GameStatus.DRAW;
            }
            // If no one won, determine whose turn it is
            return (firstCount > secondCount) ? GameStatus.SECOND_TURN : GameStatus.FIRST_TURN;
        } else {
            // Rule 2: If someone won, the board must be consistent with the winning move.
            // We verify if removing exactly one piece results in a board with 0 winning lines 
            // and that piece belonged to the winner.
            boolean moveFound = false;
            for (int i = 0; i < board.getSize(); i++) {
                for (int j = 0; j < board.getSize(); j++) {
                    Player currentPlayer = board.getCell(i, j);
                    if (currentPlayer != Player.EMPTY) {
                        TicTacToeBoard testBoard = board.copy();
                        testBoard.setCell(i, j, Player.EMPTY);

                        TicTacToeValidator testValidator = new TicTacToeValidator(testBoard);
                        boolean isLastMoveCorrect = (testValidator.countWinningLines() == 0) 
                                && (firstCount > secondCount == (currentPlayer == Player.FIRST));

                        if (isLastMoveCorrect) {
                            moveFound = true;
                            break;
                        }
                    }
                }
                if (moveFound) break;
            }

            if (!moveFound) {
                return GameStatus.ILLEGAL;
            }

            return (firstCount > secondCount) ? GameStatus.FIRST_PLAYER_WON : GameStatus.SECOND_PLAYER_WON;
        }
    }

    private int countWinningLines() {
        int wins = 0;
        // Rows and Columns
        for (int i = 0; i < board.getSize(); i++) {
            if (isTriple(i, 0, 0, 1)) wins++;
            if (isTriple(0, i, 1, 0)) wins++;
        }
        // Diagonals
        if (isTriple(0, 0, 1, 1)) wins++;
        if (isTriple(0, 2, 1, -1)) wins++;
        return wins;
    }

    private boolean isTriple(int row, int col, int dr, int dc) {
        Player p1 = board.getCell(row, col);
        if (p1 == Player.EMPTY) return false;

        Player p2 = board.getCell(row + dr, col + dc);
        Player p3 = board.getCell(row + 2 * dr, col + 2 * dc);

        return p1 == p2 && p2 == p3;
    }
}

