import java.util.*;
import java.io.*;

/**
 * A program to analyze the state of a Tic-Tac-Toe game.
 * It determines if the state is a win, a draw, whose turn it is, or illegal.
 */
public class TicTacToeAnalyzer {

    // Constants for game rules
    private static final int BOARD_SIZE = 9;
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0'; // Using '0' as per the original implementation
    private static final char EMPTY = '.';

    // Possible winning combinations on a 3x3 grid
    private static final int[][] WINNING_COMBINATIONS = {
        {0, 1, 2}, {3, 4, 5}, {6, 7, 8}, // Rows
        {0, 3, 6}, {1, 4, 7}, {2, 5, 8}, // Columns
        {0, 4, 8}, {2, 4, 6}             // Diagonals
    };

    /**
     * Represents the possible outcomes of the game analysis.
     */
    public enum GameResult {
        FIRST_PLAYER_WON("the first player won"),
        SECOND_PLAYER_WON("the second player won"),
        DRAW("draw"),
        FIRST_PLAYER_TURN("first"),
        SECOND_PLAYER_TURN("second"),
        ILLEGAL("illegal");

        private final String message;

        GameResult(String message) {
            this.message = message;
        }

        @Override
        public String toString() {
            return message;
        }
    }

    /**
     * Represents the Tic-Tac-Toe board state.
     */
    private static class Board {
        private final char[] cells;

        public Board(char[] cells) {
            if (cells.length != BOARD_SIZE) {
                throw new IllegalArgumentException("Board must consist of exactly 9 cells.");
            }
            this.cells = cells.clone();
        }

        public char[] getCells() {
            return cells;
        }

        public void setCell(int index, char value) {
            cells[index] = value;
        }

        /**
         * Checks if the specified player has a winning line.
         */
        public boolean hasWinner(char player) {
            for (int[] combo : WINNING_COMBINATIONS) {
                if (cells[combo[0]] == player &&
                    cells[combo[1]] == player &&
                    cells[combo[2]] == player) {
                    return true;
                }
            }
            return false;
        }

        public boolean isFull() {
            for (char cell : cells) {
                if (cell == EMPTY) return false;
            }
            return true;
        }
    }

    /**
     * Engine to evaluate the validity and status of a board.
     */
    public GameResult analyze(char[] boardArray) {
        Board board = new Board(boardArray);

        int countX = 0;
        int countO = 0;
        for (char cell : board.getCells()) {
            if (cell == PLAYER_X) countX++;
            else if (cell == PLAYER_O) countO++;
        }

        // Rule 1: The difference between player counts must be 0 or 1.
        int diff = countX - countO;
        if (diff != 0 && diff != 1) {
            return GameResult.ILLEGAL;
        }

        char lastMovePlayer = (diff == 0) ? PLAYER_O : PLAYER_X;
        char nextMovePlayer = (diff == 0) ? PLAYER_X : PLAYER_O;

        // Rule 2: The player who is supposed to move cannot have already won.
        if (board.hasWinner(nextMovePlayer)) {
            return GameResult.ILLEGAL;
        }

        // Case A: The last player did not win.
        if (!board.hasWinner(lastMovePlayer)) {
            if (board.isFull()) {
                return GameResult.DRAW;
            } else {
                return (nextMovePlayer == PLAYER_X) ? GameResult.FIRST_PLAYER_TURN : GameResult.SECOND_PLAYER_TURN;
            }
        }

        // Case B: The last player has a winning line. 
        // We must verify if this win was achieved by a single valid move.
        // A move is valid if removing one of the winner's pieces results in no win.
        boolean validWin = false;
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board.getCells()[i] == lastMovePlayer) {
                board.setCell(i, EMPTY);
                if (!board.hasWinner(lastMovePlayer)) {
                    validWin = true;
                    board.setCell(i, lastMovePlayer); // Restore
                    break;
                }
                board.setCell(i, lastMovePlayer); // Restore
            }
        }

        if (validWin) {
            return (lastMovePlayer == PLAYER_X) ? GameResult.FIRST_PLAYER_WON : GameResult.SECOND_PLAYER_WON;
        }

        return GameResult.ILLEGAL;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        TicTacToeAnalyzer analyzer = new TicTacToeAnalyzer();

        try {
            // The original logic expects 3 tokens which are concatenated to form a 9-char board.
            StringBuilder boardBuilder = new StringBuilder();
            for (int i = 0; i < 3; i++) {
                if (sc.hasNext()) {
                    boardBuilder.append(sc.next());
                }
            }

            String boardString = boardBuilder.toString();
            if (boardString.length() != BOARD_SIZE) {
                System.out.println(GameResult.ILLEGAL);
            } else {
                System.out.println(analyzer.analyze(boardString.toCharArray()));
            }
        } catch (Exception e) {
            System.out.println(GameResult.ILLEGAL);
        } finally {
            sc.close();
        }
    }
}

import java.util.Scanner;

/**
 * A utility class to validate Tic-Tac-Toe board states and determine the game outcome.
 */
public class TicTacToe {

    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0'; // Using '0' as per original logic
    private static final int BOARD_SIZE = 9;

    private static final int[][] WINNING_COMBINATIONS = {
        {0, 1, 2}, {3, 4, 5}, {6, 7, 8}, // Rows
        {0, 3, 6}, {1, 4, 7}, {2, 5, 8}, // Columns
        {0, 4, 8}, {2, 4, 6}             // Diagonals
    };

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            char[] board = readBoard(scanner);

            int xCount = 0;
            int oCount = 0;
            int emptyCount = 0;

            for (char cell : board) {
                if (cell == PLAYER_X) {
                    xCount++;
                } else if (cell == PLAYER_O) {
                    oCount++;
                } else {
                    emptyCount++;
                }
            }

            printGameResult(board, xCount, oCount, emptyCount);
        } catch (Exception e) {
            System.out.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Reads the 3x3 grid from standard input.
     */
    private static char[] readBoard(Scanner scanner) {
        char[] board = new char[BOARD_SIZE];
        for (int i = 0; i < 3; i++) {
            String row = scanner.next();
            for (int j = 0; j < 3; j++) {
                board[i * 3 + j] = row.charAt(j);
            }
        }
        return board;
    }

    /**
     * Determines and prints the outcome of the game based on the board state.
     */
    private static void printGameResult(char[] board, int xCount, int oCount, int emptyCount) {
        if (!isValid(board, xCount, oCount)) {
            System.out.println("illegal");
            return;
        }

        if (isWin(board, PLAYER_X)) {
            System.out.println("the first player won");
        } else if (isWin(board, PLAYER_O)) {
            System.out.println("the second player won");
        } else if (emptyCount == 0) {
            System.out.println("draw");
        } else {
            // If the game is not over, determine whose turn is next
            // Based on original logic: if X has moved more, it's O's turn ("second")
            if (xCount > oCount) {
                System.out.println("second");
            } else {
                System.out.println("first");
            }
        }
    }

    /**
     * Validates if the current counts and win states are logically possible in Tic-Tac-Toe.
     */
    private static boolean isValid(char[] board, int xCount, int oCount) {
        boolean xWins = isWin(board, PLAYER_X);
        boolean oWins = isWin(board, PLAYER_O);

        // Rule 1: Turn count must be valid (X goes first, so xCount is either equal to oCount or oCount + 1)
        if (!(xCount == oCount || xCount == oCount + 1)) {
            return false;
        }

        // Rule 2: Both players cannot have winning lines simultaneously
        if (xWins && oWins) {
            return false;
        }

        // Rule 3: If O won, X must have made the last move to bring counts to equality
        if (oWins && xCount != oCount) {
            return false;
        }

        // Rule 4: If X won, X must have made the last move to be exactly one ahead
        if (xWins && xCount != oCount + 1) {
            return false;
        }

        return true;
    }

    /**
     * Checks if the specified player has a winning combination on the board.
     */
    private static boolean isWin(char[] board, char player) {
        for (int[] combo : WINNING_COMBINATIONS) {
            if (board[combo[0]] == player && 
                board[combo[1]] == player && 
                board[combo[2]] == player) {
                return true;
            }
        }
        return false;
    }
}

