/**
 * Represents the state of the Tic-Tac-Toe board.
 */
class Board {
    public static final char PLAYER_X = 'X';
    public static final char PLAYER_O = '0'; // Note: Preserving original '0' (zero)
    public static final char EMPTY = '.';
    public static final int SIZE = 3;

    private final char[][] grid;

    public Board(char[][] grid) {
        this.grid = grid;
    }

    public char getCell(int row, int col) {
        return grid[row][col];
    }

    public int countPieces(char player) {
        int count = 0;
        for (int r = 0; r < SIZE; r++) {
            for (int c = 0; c < SIZE; c++) {
                if (grid[r][c] == player) {
                    count++;
                }
            }
        }
        return count;
    }

    public boolean isFull() {
        for (int r = 0; r < SIZE; r++) {
            for (int c = 0; c < SIZE; c++) {
                if (grid[r][c] == EMPTY) return false;
            }
        }
        return true;
    }

    public boolean hasWinner(char player) {
        // Check rows and columns
        for (int i = 0; i < SIZE; i++) {
            if (checkLine(grid[i][0], grid[i][1], grid[i][2], player)) return true;
            if (checkLine(grid[0][i], grid[1][i], grid[2][i], player)) return true;
        }
        // Check diagonals
        if (checkLine(grid[0][0], grid[1][1], grid[2][2], player)) return true;
        if (checkLine(grid[0][2], grid[1][1], grid[2][0], player)) return true;

        return false;
    }

    private boolean checkLine(char c1, char c2, char c3, char player) {
        return c1 == player && c2 == player && c3 == player;
    }
}

/**
 * Contains the business logic to evaluate the current state of the game.
 */
class GameEvaluator {
    private final Board board;

    public GameEvaluator(Board board) {
        this.board = board;
    }

    public String evaluate() {
        if (isIllegal()) {
            return "illegal";
        }
        if (board.hasWinner(Board.PLAYER_X)) {
            return "the first player won";
        }
        if (board.hasWinner(Board.PLAYER_O)) {
            return "the second player won";
        }
        if (board.isFull()) {
            return "draw";
        }

        return determineTurn();
    }

    private boolean isIllegal() {
        int xCount = board.countPieces(Board.PLAYER_X);
        int oCount = board.countPieces(Board.PLAYER_O);

        // 1. Check if piece counts are valid for a standard game flow
        boolean validCounts = (xCount == oCount || xCount == oCount + 1);
        if (!validCounts) return true;

        boolean xWins = board.hasWinner(Board.PLAYER_X);
        boolean oWins = board.hasWinner(Board.PLAYER_O);

        // 2. Check if both players won (impossible)
        if (xWins && oWins) return true;

        // 3. If X won, X must have exactly one more piece than O
        if (xWins && xCount != oCount + 1) return true;

        // 4. If O won, X must have the same amount of pieces as O
        if (oWins && xCount != oCount) return true;

        return false;
    }

    private String determineTurn() {
        int xCount = board.countPieces(Board.PLAYER_X);
        int oCount = board.countPieces(Board.PLAYER_O);

        if (xCount == oCount) {
            return "first";
        } else if (xCount == oCount + 1) {
            return "second";
        } else {
            return "unexpected";
        }
    }
}

