/**
 * Logic engine for analyzing a Tic Tac Toe board state.
 */
class TicTacToeAnalyzer {
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0'; // Keeping '0' to match original logic
    private static final char EMPTY = '.';

    private final char[][] grid;
    private final int countX;
    private final int countO;
    private final int countEmpty;
    private final boolean wonX;
    private final boolean wonO;

    public TicTacToeAnalyzer(char[][] grid) {
        this.grid = grid;

        int x = 0;
        int o = 0;
        int empty = 0;

        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                if (grid[i][j] == PLAYER_X) x++;
                else if (grid[i][j] == PLAYER_O) o++;
                else empty++;
            }
        }

        this.countX = x;
        this.countO = o;
        this.countEmpty = empty;
        this.wonX = checkWin(PLAYER_X);
        this.wonO = checkWin(PLAYER_O);
    }

    /**
     * Determines the result of the board state.
     */
    public GameResult analyze() {
        if (isIllegal()) {
            return GameResult.ILLEGAL;
        }

        if (wonX) return GameResult.FIRST_PLAYER_WON;
        if (wonO) return GameResult.SECOND_PLAYER_WON;
        if (countEmpty == 0) return GameResult.DRAW;

        // If no one won and it's not a draw, determine whose turn it is
        // Based on original logic: if X has moved once more than O, it's O's turn.
        return (countX - countO == 1) ? GameResult.SECOND_PLAYER_TURN : GameResult.FIRST_PLAYER_TURN;
    }

    private boolean isIllegal() {
        int diff = countX - countO;

        // 1. Turn count must be valid (X starts first, so diff must be 0 or 1)
        if (diff != 0 && diff != 1) return true;

        // 2. Both players cannot have winning lines simultaneously
        if (wonX && wonO) return true;

        // 3. If O wins, X must have made the same number of moves as O
        if (wonO && diff != 0) return true;

        // 4. If X wins, X must have made exactly one more move than O
        if (wonX && diff != 1) return true;

        return false;
    }

    private boolean checkWin(char player) {
        // Check rows and columns
        for (int i = 0; i < 3; i++) {
            if (checkLine(grid[i][0], grid[i][1], grid[i][2], player)) return true;
            if (checkLine(grid[0][i], grid[1][i], grid[2][i], player)) return true;
        }

        // Check diagonals
        if (checkLine(grid[0][0], grid[1][1], grid[2][2], player)) return true;
        if (checkLine(grid[0][2], grid[1][1], grid[2][0], player)) return true;

        return false;
    }

    private boolean checkLine(char c1, char c2, char c3, char player) {
        return c1 == player && c2 == player && c3 == player;
    }
}

