import java.util.Scanner;

/**
 * A validator for the state of a 3x3 Tic-Tac-Toe game.
 * It determines if the current board is a win, a draw, an ongoing game, 
 * or an illegal state based on piece counts and winning patterns.
 */
public class TicTacToeValidator {

    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0';
    private static final int BOARD_SIZE = 3;
    private static final int TOTAL_CELLS = BOARD_SIZE * BOARD_SIZE;

    private final char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
    private int countX = 0;
    private int countO = 0;

    /**
     * Constructor that parses the board from the provided scanner.
     * @param scanner The scanner reading from standard input.
     */
    public TicTacToeValidator(Scanner scanner) {
        parseBoard(scanner);
    }

    /**
     * Reads 3 lines of input to populate the 3x3 grid and count player pieces.
     */
    private void parseBoard(Scanner scanner) {
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (scanner.hasNextLine()) {
                String line = scanner.nextLine();
                for (int j = 0; j < BOARD_SIZE; j++) {
                    char cell = line.charAt(j);
                    board[i][j] = cell;
                    if (cell == PLAYER_X) {
                        countX++;
                    } else if (cell == PLAYER_O) {
                        countO++;
                    }
                }
            }
        }
    }

    /**
     * Evaluates the game state and returns the result string.
     * @return Result string: "the first player won", "the second player won", 
     *         "draw", "first", "second", or "illegal".
     */
    public String getGameState() {
        // 1. Validate piece counts. 
        // In Tic-Tac-Toe, Player 1 (X) moves first, so countX must be countO or countO + 1.
        if (!(countX == countO || countX == countO + 1)) {
            return "illegal";
        }

        boolean xWins = checkWinner(PLAYER_X);
        boolean oWins = checkWinner(PLAYER_O);

        // 2. A game is illegal if both players have winning lines simultaneously.
        if (xWins && oWins) {
            return "illegal";
        }

        // 3. Handle Winner scenarios
        if (xWins) {
            // If X wins, it must be X's turn that completed the win (countX = countO + 1).
            return (countX == countO + 1) ? "the first player won" : "illegal";
        }

        if (oWins) {
            // If O wins, it must be O's turn that completed the win (countX = countO).
            return (countX == countO) ? "the second player won" : "illegal";
        }

        // 4. Handle non-winning scenarios
        if (countX + countO == TOTAL_CELLS) {
            return "draw";
        }

        // If no winner and board is not full, determine whose turn is next.
        return (countX == countO) ? "first" : "second";
    }

    /**
     * Checks all possible winning lines (rows, columns, diagonals) for a given player.
     */
    private boolean checkWinner(char player) {
        // Check Rows and Columns
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (checkLine(i, 0, i, 1, i, 2, player)) return true; // Horizontal
            if (checkLine(0, i, 1, i, 2, i, player)) return true; // Vertical
        }

        // Check Diagonals
        if (checkLine(0, 0, 1, 1, 2, 2, player)) return true;
        if (checkLine(0, 2, 1, 1, 2, 0, player)) return true;

        return false;
    }

    /**
     * Helper to verify if three specific coordinates belong to the same player.
     */
    private boolean checkLine(int r1, int c1, int r2, int c2, int r3, int c3, char player) {
        return board[r1][c1] == player && 
               board[r2][c2] == player && 
               board[r3][c3] == player;
    }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (scanner.hasNextLine()) {
                TicTacToeValidator game = new TicTacToeValidator(scanner);
                System.out.println(game.getGameState());
            }
        } catch (Exception e) {
            // Basic error handling for unexpected input formats
            System.out.println("illegal");
        }
    }
}

import java.util.Scanner;

/**
 * A class to validate and determine the state of a Tic-Tac-Toe game.
 */
public class TicTacToe {

    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0'; // Using '0' as per the original implementation requirements

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] board = new char[3][3];

        try {
            // Parse input
            for (int i = 0; i < 3; i++) {
                String row = scanner.next();
                for (int j = 0; j < 3; j++) {
                    board[i][j] = row.charAt(j);
                }
            }

            determineGameState(board);
        } catch (Exception e) {
            // In a production environment, use proper logging
            System.out.println("Invalid input format.");
        } finally {
            scanner.close();
        }
    }

    /**
     * Validates the board state and prints the game outcome.
     * 
     * @param board The 3x3 Tic-Tac-Toe board.
     */
    private static void determineGameState(char[][] board) {
        int xCount = 0;
        int oCount = 0;

        // 1. Count pieces for each player
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                if (board[i][j] == PLAYER_X) {
                    xCount++;
                } else if (board[i][j] == PLAYER_O) {
                    oCount++;
                }
            }
        }

        boolean xWins = checkWin(board, PLAYER_X);
        boolean oWins = checkWin(board, PLAYER_O);

        // 2. Validate Turn Integrity
        // Player X goes first, so X count must be equal to O or O + 1.
        if (oCount > xCount || xCount > oCount + 1) {
            System.out.println("illegal");
            return;
        }

        // 3. Validate Win Consistency
        // Both players cannot have winning configurations simultaneously.
        if (xWins && oWins) {
            System.out.println("illegal");
            return;
        }

        // If X wins, it must be X's turn that just finished (xCount == oCount + 1).
        if (xWins && xCount != oCount + 1) {
            System.out.println("illegal");
            return;
        }

        // If O wins, it must be O's turn that just finished (xCount == oCount).
        if (oWins && xCount != oCount) {
            System.out.println("illegal");
            return;
        }

        // 4. Determine Outcome
        if (xWins) {
            System.out.println("the first player won");
        } else if (oWins) {
            System.out.println("the second player won");
        } else if (isBoardFull(xCount, oCount)) {
            System.out.println("draw");
        } else {
            // Game is still in progress
            printTurnIndicator(xCount, oCount);
        }
    }

    /**
     * Checks if the specified player has a winning line.
     */
    private static boolean checkWin(char[][] board, char player) {
        // Check rows and columns
        for (int i = 0; i < 3; i++) {
            if ((board[i][0] == player && board[i][1] == player && board[i][2] == player) ||
                (board[0][i] == player && board[1][i] == player && board[2][i] == player)) {
                return true;
            }
        }
        // Check diagonals
        return (board[0][0] == player && board[1][1] == player && board[2][2] == player) ||
               (board[0][2] == player && board[1][1] == player && board[2][0] == player);
    }

    /**
     * Checks if all 9 cells are occupied.
     */
    private static boolean isBoardFull(int xCount, int oCount) {
        return (xCount + oCount) == 9;
    }

    /**
     * Prints whether it is currently the first or second player's turn.
     */
    private static void printTurnIndicator(int xCount, int oCount) {
        if (xCount == oCount) {
            System.out.println("first");
        } else {
            System.out.println("second");
        }
    }
}

import java.util.*;

/**
 * Represents the players in the game.
 */
enum Player {
    X, O, EMPTY;

    public static Player fromString(String s) {
        return switch (s) {
            case "X" -> X;
            case "0" -> O; // Note: Original code used the character '0'
            default -> EMPTY;
        };
    }
}

/**
 * Represents the possible outcomes of a Tic-Tac-Toe game state.
 */
enum GameResult {
    ILLEGAL("illegal"),
    FIRST_PLAYER_WON("the first player won"),
    SECOND_PLAYER_WON("the second player won"),
    DRAW("draw"),
    FIRST_PLAYER_TURN("first"),
    SECOND_PLAYER_TURN("second");

    private final String message;

    GameResult(String message) {
        this.message = message;
    }

    @Override
    public String toString() {
        return this.message;
    }
}

/**
 * Handles the logic and state of a Tic-Tac-Toe board.
 */
class TicTacToeBoard {
    private static final int SIZE = 3;
    private static final int[][] WINNING_COMBINATIONS = {
            {0, 0, 0, 1, 0, 2}, {1, 0, 1, 1, 1, 2}, {2, 0, 2, 1, 2, 2}, // Rows
            {0, 0, 1, 0, 2, 0}, {0, 1, 1, 1, 2, 1}, {0, 2, 1, 2, 2, 2}, // Cols
            {0, 0, 1, 1, 2, 2}, {0, 2, 1, 1, 2, 0}                      // Diagonals
    };

    private final Player[][] grid = new Player[SIZE][SIZE];
    private int xCount = 0;
    private int oCount = 0;
    private int emptyCount = 0;

    public TicTacToeBoard(String row1, String row2, String row3) {
        parseRows(row1, row2, row3);
    }

    private void parseRows(String r1, String r2, String r3) {
        String[] rows = {r1, r2, r3};
        for (int i = 0; i < SIZE; i++) {
            char[] chars = rows[i].toCharArray();
            for (int j = 0; j < SIZE; j++) {
                Player p = Player.fromString(String.valueOf(chars[j]));
                grid[i][j] = p;

                if (p == Player.X) xCount++;
                else if (p == Player.O) oCount++;
                else emptyCount++;
            }
        }
    }

    public GameResult evaluate() {
        // 1. Basic move count validation
        if (oCount > xCount || (xCount - oCount) > 1) {
            return GameResult.ILLEGAL;
        }

        boolean xWins = checkWin(Player.X);
        boolean oWins = checkWin(Player.O);

        // 2. Validate win conditions against turn counts
        // X moves first, so if X wins, X must have one more move than O
        if (xWins && xCount == oCount) return GameResult.ILLEGAL;
        // If O wins, counts must be equal
        if (oWins && xCount > oCount) return GameResult.ILLEGAL;
        // Both cannot win simultaneously
        if (xWins && oWins) return GameResult.ILLEGAL;

        // 3. Determine specific outcome
        if (xWins) return GameResult.FIRST_PLAYER_WON;
        if (oWins) return GameResult.SECOND_PLAYER_WON;
        if (emptyCount == 0) return GameResult.DRAW;

        // 4. Determine whose turn it is
        return (xCount == oCount) ? GameResult.FIRST_PLAYER_TURN : GameResult.SECOND_PLAYER_TURN;
    }

    private boolean checkWin(Player player) {
        for (int[] combo : WINNING_COMBINATIONS) {
            if (grid[combo[0]][combo[1]] == player &&
                grid[combo[2]][combo[3]] == player &&
                grid[combo[4]][combo[5]] == player) {
                return true;
            }
        }
        return false;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNext()) return;
        String row1 = scanner.next();
        String row2 = scanner.next();
        String row3 = scanner.next();

        TicTacToeBoard board = new TicTacToeBoard(row1, row2, row3);
        System.out.println(board.evaluate());

        scanner.close();
    }

    /**
     * Manual test suite to verify logic.
     */
    public static void runTests() {
        test("X0X", ".0.", ".X.", "second");
        test("X.X", "0.0", ".0X", "illegal"); // O won but X has more moves
        test("X.0", "X.0", "X0.", "the first player won");
        test("000", "X.X", "X.X", "illegal"); // O won but X has more moves
    }

    private static void test(String r1, String r2, String r3, String expected) {
        TicTacToeBoard board = new TicTacToeBoard(r1, r2, r3);
        String actual = board.evaluate().toString();
        System.out.printf("Input: [%s, %s, %s] | Expected: %s | Actual: %s | %s%n",
                r1, r2, r3, expected, actual, actual.equals(expected) ? "PASS" : "FAIL");
    }
}

import java.util.*;

/**
 * A program to validate the state of a Tic-Tac-Toe game.
 * It determines if the game is ongoing (whose turn it is), 
 * if someone has won, if it is a draw, or if the state is illegal.
 */
public class Main {

    private static final int BOARD_SIZE = 3;

    /**
     * Represents the players in the game.
     */
    enum Player {
        X, O, EMPTY;

        public static Player fromChar(char c) {
            if (c == 'X') return X;
            // Handles both the letter 'O' and the digit '0' found in the original code
            if (c == 'O' || c == '0') return O;
            return EMPTY;
        }
    }

    /**
     * Represents the possible outcomes of a game state validation.
     */
    enum GameResult {
        FIRST_TURN("first"),
        SECOND_TURN("second"),
        X_WON("the first player won"),
        O_WON("the second player won"),
        DRAW("draw"),
        ILLEGAL("illegal");

        private final String message;

        GameResult(String message) {
            this.message = message;
        }

        @Override
        public String toString() {
            return this.message;
        }
    }

    /**
     * Represents the Tic-Tac-Toe board and provides logic for game state analysis.
     */
    static class Board {
        private final Player[][] grid = new Player[BOARD_SIZE][BOARD_SIZE];

        public void setCell(int row, int col, Player player) {
            grid[row][col] = player;
        }

        public Player getCell(int row, int col) {
            return grid[row][col];
        }

        public int countMoves(Player player) {
            int count = 0;
            for (int i = 0; i < BOARD_SIZE; i++) {
                for (int j = 0; j < BOARD_SIZE; j++) {
                    if (grid[i][j] == player) {
                        count++;
                    }
                }
            }
            return count;
        }

        public boolean hasWon(Player player) {
            // Check rows and columns
            for (int i = 0; i < BOARD_SIZE; i++) {
                if (checkLine(player, i, 0, 0, 1)) return true; // Row
                if (checkLine(player, 0, i, 1, 0)) return true; // Column
            }
            // Check diagonals
            if (checkLine(player, 0, 0, 1, 1)) return true;
            if (checkLine(player, 0, 2, 1, -1)) return true;

            return false;
        }

        /**
         * Helper to check if a line of 3 exists starting from (startRow, startCol) 
         * moving in direction (rowStep, colStep).
         */
        private boolean checkLine(Player p, int startRow, int startCol, int rowStep, int colStep) {
            for (int i = 0; i < BOARD_SIZE; i++) {
                int r = startRow + (i * rowStep);
                int c = startCol + (i * colStep);
                if (grid[r][c] != p) return false;
            }
            return true;
        }
    }

    /**
     * Logic engine to determine the validity of a Board state.
     */
    static class TicTacToeValidator {

        public static GameResult validate(Board board) {
            int xMoves = board.countMoves(Player.X);
            int oMoves = board.countMoves(Player.O);
            boolean xWon = board.hasWon(Player.X);
            boolean oWon = board.hasWon(Player.O);

            // 1. A player cannot win if it's not their turn logic (X moves first)
            // 2. Both players cannot have winning lines simultaneously
            if (xWon && oWon) return GameResult.ILLEGAL;

            // Check if X won
            if (xWon) {
                return (xMoves == oMoves + 1) ? GameResult.X_WON : GameResult.ILLEGAL;
            }

            // Check if O won
            if (oWon) {
                return (xMoves == oMoves) ? GameResult.O_WON : GameResult.ILLEGAL;
            }

            // Check move count validity (X goes first, so xMoves must be oMoves or oMoves + 1)
            if (xMoves != oMoves && xMoves != oMoves + 1) {
                return GameResult.ILLEGAL;
            }

            // If no one has won, check if it's a draw or whose turn it is
            if (xMoves + oMoves == BOARD_SIZE * BOARD_SIZE) {
                return GameResult.DRAW;
            }

            if (xMoves == oMoves) {
                return GameResult.FIRST_TURN;
            } else {
                return GameResult.SECOND_TURN;
            }
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        while (scanner.hasNext()) {
            Board board = new Board();
            try {
                for (int i = 0; i < BOARD_SIZE; i++) {
                    String rowString = scanner.next();
                    for (int j = 0; j < BOARD_SIZE; j++) {
                        board.setCell(i, j, Player.fromChar(rowString.charAt(j)));
                    }
                }
                System.out.println(TicTacToeValidator.validate(board));
            } catch (Exception e) {
                // Handle unexpected input formatting gracefully
                System.out.println(GameResult.ILLEGAL);
            }
        }
        scanner.close();
    }
}

import java.util.Scanner;

/**
 * Represents a Tic-Tac-Toe game validator and solver.
 */
public class Main {

    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0';
    private static final char EMPTY = '.';
    private static final int GRID_SIZE = 3;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        try {
            char[][] boardData = new char[GRID_SIZE][GRID_SIZE];
            for (int i = 0; i < GRID_SIZE; i++) {
                String line = scanner.next();
                for (int j = 0; j < GRID_SIZE; j++) {
                    boardData[i][j] = line.charAt(j);
                }
            }

            Board board = new Board(boardData);
            TicTacToeEvaluator evaluator = new TicTacToeEvaluator(board);
            System.out.println(evaluator.evaluate());

        } catch (Exception e) {
            // In a production environment, use a logger
            System.out.println("illegal");
        } finally {
            scanner.close();
        }
    }

    /**
     * Represents the state of the Tic-Tac-Toe board.
     */
    static class Board {
        private final char[][] grid;
        private final int countX;
        private final int countO;
        private final int countEmpty;

        public Board(char[][] grid) {
            this.grid = grid;
            int x = 0, o = 0, empty = 0;
            for (int r = 0; r < GRID_SIZE; r++) {
                for (int c = 0; c < GRID_SIZE; c++) {
                    if (grid[r][c] == PLAYER_X) x++;
                    else if (grid[r][c] == PLAYER_O) o++;
                    else if (grid[r][c] == EMPTY) empty++;
                }
            }
            this.countX = x;
            this.countO = o;
            this.countEmpty = empty;
        }

        public char getCell(int row, int col) {
            return grid[row][col];
        }

        public int getCountX() { return countX; }
        public int getCountO() { return countO; }
        public int getCountEmpty() { return countEmpty; }

        public boolean hasWinner(char player) {
            // Check rows and columns
            for (int i = 0; i < GRID_SIZE; i++) {
                if (checkLine(grid[i][0], grid[i][1], grid[i][2], player)) return true;
                if (checkLine(grid[0][i], grid[1][i], grid[2][i], player)) return true;
            }
            // Check diagonals
            return checkLine(grid[0][0], grid[1][1], grid[2][2], player) ||
                   checkLine(grid[0][2], grid[1][1], grid[2][0], player);
        }

        private boolean checkLine(char c1, char c2, char c3, char player) {
            return c1 == player && c2 == player && c3 == player;
        }
    }

    /**
     * Logic engine to evaluate the board state according to Tic-Tac-Toe rules.
     */
    static class TicTacToeEvaluator {
        private final Board board;

        public TicTacToeEvaluator(Board board) {
            this.board = board;
        }

        public String evaluate() {
            if (isTurnOrderIllegal()) {
                return "illegal";
            }

            boolean xWins = board.hasWinner(PLAYER_X);
            boolean oWins = board.hasWinner(PLAYER_O);

            // Rule: Both players cannot have winning lines simultaneously in a valid game
            if (xWins && oWins) {
                return "illegal";
            }

            if (xWins) {
                return (board.getCountX() - board.getCountO() == 1) 
                        ? "the first player won" : "illegal";
            }

            if (oWins) {
                return (board.getCountX() - board.getCountO() == 0) 
                        ? "the second player won" : "illegal";
            }

            if (board.getCountEmpty() == 0) {
                return "draw";
            }

            // If no one won and there are empty spaces, determine whose turn it is
            return (board.getCountX() == board.getCountO()) ? "first" : "second";
        }

        private boolean isTurnOrderIllegal() {
            int diff = board.getCountX() - board.getCountO();
            // X goes first, so X must be equal to O or X must be O + 1
            return diff < 0 || diff > 1;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.*;

/**
 * A validator for Tic-Tac-Toe game states.
 * Determines if a given board state is a win, a draw, a continuation, or illegal.
 */
public class Main {

    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0'; // Using '0' as per original requirement
    private static final char EMPTY = '.';

    public enum GameOutcome {
        FIRST_PLAYER_WON("the first player won"),
        SECOND_PLAYER_WON("the second player won"),
        DRAW("draw"),
        FIRST_TURN_NEXT("first"),
        SECOND_TURN_NEXT("second"),
        ILLEGAL("illegal");

        private final String message;

        GameOutcome(String message) {
            this.message = message;
        }

        @Override
        public String toString() {
            return message;
        }
    }

    public static void main(String[] args) {
        try {
            TicTacToeBoard board = TicTacToeBoard.fromReader(new BufferedReader(new InputStreamReader(System.in)));
            System.out.println(determineOutcome(board));
        } catch (IllegalArgumentException e) {
            System.out.println(GameOutcome.ILLEGAL);
        } catch (IOException e) {
            System.out.println(GameOutcome.ILLEGAL);
        }
    }

    /**
     * Core logic to determine the state of the game based on the board configuration.
     */
    private static GameOutcome determineOutcome(TicTacToeBoard board) {
        int countX = board.countPlayer(PLAYER_X);
        int countO = board.countPlayer(PLAYER_O);

        // 1. Basic move count validation
        // X starts, so X must have equal to or exactly one more move than O.
        if (countO > countX || countX > countO + 1) {
            return GameOutcome.ILLEGAL;
        }

        Set<Character> winners = board.getWinners();

        // 2. Check for impossible win states (e.g., both players having winning lines)
        if (winners.size() > 1) {
            return GameOutcome.ILLEGAL;
        }

        // 3. Evaluate outcome based on winners
        if (!winners.isEmpty()) {
            char winner = winners.iterator().next();
            if (winner == PLAYER_X) {
                // If X wins, X must have made the last move (countX = countO + 1)
                return (countX == countO + 1) ? GameOutcome.FIRST_PLAYER_WON : GameOutcome.ILLEGAL;
            } else {
                // If 0 wins, 0 must have made the last move (countX = countO)
                return (countX == countO) ? GameOutcome.SECOND_PLAYER_WON : GameOutcome.ILLEGAL;
            }
        }

        // 4. No winners: Determine if it's a draw or a continuation
        if (board.isFull()) {
            // Check if full board adheres to standard move counts (5 X, 4 0)
            return (countX == 5 && countO == 4) ? GameOutcome.DRAW : GameOutcome.ILLEGAL;
        } else {
            // Determine whose turn it is
            return (countX == countO) ? GameOutcome.FIRST_TURN_NEXT : GameOutcome.SECOND_TURN_NEXT;
        }
    }

    /**
     * Represents the 3x3 Tic-Tac-Toe grid and provides utility methods.
     */
    static class TicTacToeBoard {
        private final char[][] grid = new char[3][3];

        private TicTacToeBoard() {}

        public static TicTacToeBoard fromReader(BufferedReader reader) throws IOException, IllegalArgumentException {
            TicTacToeBoard board = new TicTacToeBoard();
            for (int i = 0; i < 3; i++) {
                String line = reader.readLine();
                if (line == null || line.length() < 3) {
                    throw new IllegalArgumentException("Invalid input format");
                }
                for (int j = 0; j < 3; j++) {
                    char c = line.charAt(j);
                    if (c != PLAYER_X && c != PLAYER_O && c != EMPTY) {
                        throw new IllegalArgumentException("Illegal character");
                    }
                    board.grid[i][j] = c;
                }
            }
            return board;
        }

        public int countPlayer(char player) {
            int count = 0;
            for (int i = 0; i < 3; i++) {
                for (int j = 0; j < 3; j++) {
                    if (grid[i][j] == player) count++;
                }
            }
            return count;
        }

        public boolean isFull() {
            for (int i = 0; i < 3; i++) {
                for (int j = 0; j < 3; j++) {
                    if (grid[i][j] == EMPTY) return false;
                }
            }
            return true;
        }

        /**
         * Finds all players who have at least one winning line.
         */
        public Set<Character> getWinners() {
            Set<Character> winners = new HashSet<>();
            int[][] lines = {
                // Rows
                {0,0, 0,1, 0,2}, {1,0, 1,1, 1,2}, {2,0, 2,1, 2,2},
                // Columns
                {0,0, 1,0, 2,0}, {0,1, 1,1, 2,1}, {0,2, 1,2, 2,2},
                // Diagonals
                {0,0, 1,1, 2,2}, {0,2, 1,1, 2,0}
            };

            for (int[] line : lines) {
                char c1 = grid[line[0]][line[1]];
                char c2 = grid[line[2]][line[3]];
                char c3 = grid[line[4]][line[5]];

                if (c1 != EMPTY && c1 == c2 && c1 == c3) {
                    winners.add(c1);
                }
            }
            return winners;
        }
    }
}

import java.util.Scanner;

public class TicTacToeAnalyzer {

    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0'; 
    private static final int SIZE = 3;

    public enum Outcome {
        ILLEGAL("illegal"),
        X_WON("the first player won"),
        O_WON("the second player won"),
        DRAW("draw"),
        X_TURN("first"),
        O_TURN("second");

        private final String message;
        Outcome(String message) { this.message = message; }
        @Override public String toString() { return message; }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        char[][] grid = new char[SIZE][SIZE];

        try {
            for (int i = 0; i < SIZE; i++) {
                String line = sc.next();
                grid[i] = line.toCharArray();
            }
            System.out.println(analyze(grid));
        } catch (Exception e) {
            System.out.println(Outcome.ILLEGAL);
        }
    }

    public static Outcome analyze(char[][] grid) {
        int countX = 0;
        int countO = 0;

        for (int i = 0; i < SIZE; i++) {
            for (int j = 0; j < SIZE; j++) {
                if (grid[i][j] == PLAYER_X) countX++;
                else if (grid[i][j] == PLAYER_O) countO++;
            }
        }

        boolean xWins = hasWinner(grid, PLAYER_X);
        boolean oWins = hasWinner(grid, PLAYER_O);

        // 1. Check legality
        if (countO > countX || (countX - countO) > 1) return Outcome.ILLEGAL;
        if (xWins && oWins) return Outcome.ILLEGAL;
        if (xWins && (countX - countO != 1)) return Outcome.ILLEGAL;
        if (oWins && (countX != countO)) return Outcome.ILLEGAL;

        // 2. Check outcomes
        if (xWins) return Outcome.X_WON;
        if (oWins) return Outcome.O_WON;
        if (countX + countO == 9) return Outcome.DRAW;

        // 3. Check whose turn
        return (countX == countO) ? Outcome.X_TURN : Outcome.O_TURN;
    }

    private static boolean hasWinner(char[][] grid, char p) {
        // Check rows and columns
        for (int i = 0; i < SIZE; i++) {
            if (grid[i][0] == p && grid[i][1] == p && grid[i][2] == p) return true;
            if (grid[0][i] == p && grid[1][i] == p && grid[2][i] == p) return true;
        }
        // Check diagonals
        return (grid[0][0] == p && grid[1][1] == p && grid[2][2] == p) ||
               (grid[0][2] == p && grid[1][1] == p && grid[2][0] == p);
    }
}

import java.io.*;
import java.util.*;

/**
 * A professional implementation of a Tic-Tac-Toe game state judge.
 * This class validates whether a given 3x3 board state is legal and determines the outcome.
 */
public class TicTacToeJudge {

    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0';
    private static final char EMPTY = '.';
    private static final int BOARD_SIZE = 3;

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];

        // Load the board from input
        try {
            for (int i = 0; i < BOARD_SIZE; i++) {
                String line = reader.next();
                if (line == null) break;
                board[i] = line.toCharArray();
            }
            System.out.println(judgeGameState(board));
        } catch (Exception e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Evaluates the board and returns the game result.
     *
     * @param board The 3x3 character array representing the game.
     * @return A string representing the outcome: "the first player won", 
     *         "the second player won", "draw", "illegal", "first" (turn), or "second" (turn).
     */
    public static String judgeGameState(char[][] board) {
        int xCount = 0;
        int oCount = 0;

        // 1. Count pieces and validate basic constraints
        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                if (board[i][j] == PLAYER_X) {
                    xCount++;
                } else if (board[i][j] == PLAYER_O) {
                    oCount++;
                }
            }
        }

        // X (Player 1) always moves first. 
        // Therefore, X count must be equal to O count or O count + 1.
        if (oCount > xCount || xCount > oCount + 1) {
            return "illegal";
        }

        boolean xWins = hasWinningLine(board, PLAYER_X);
        boolean oWins = hasWinningLine(board, PLAYER_O);

        // 2. Validate win conditions
        // Both players cannot have won simultaneously.
        if (xWins && oWins) {
            return "illegal";
        }

        // If X won, X must have made the last move (making the counts X = O + 1).
        if (xWins && xCount != oCount + 1) {
            return "illegal";
        }

        // If O won, O must have made the last move (making the counts X = O).
        if (oWins && xCount != oCount) {
            return "illegal";
        }

        // 3. Determine final result
        if (xWins) {
            return "the first player won";
        }
        if (oWins) {
            return "the second player won";
        }
        if (isBoardFull(board)) {
            return "draw";
        }

        // 4. Determine whose turn it is if the game is ongoing
        return (xCount > oCount) ? "second" : "first";
    }

    /**
     * Checks if the specified player has a complete row, column, or diagonal.
     */
    private static boolean hasWinningLine(char[][] board, char player) {
        // Check rows and columns
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (checkLine(board[i][0], board[i][1], board[i][2], player)) return true;
            if (checkLine(board[0][i], board[1][i], board[2][i], player)) return true;
        }
        // Check diagonals
        if (checkLine(board[0][0], board[1][1], board[2][2], player)) return true;
        if (checkLine(board[0][2], board[1][1], board[2][0], player)) return true;

        return false;
    }

    private static boolean checkLine(char c1, char c2, char c3, char player) {
        return c1 == player && c2 == player && c3 == player;
    }

    private static boolean isBoardFull(char[][] board) {
        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                if (board[i][j] == EMPTY) return false;
            }
        }
        return true;
    }

    /**
     * Fast I/O utility for efficient reading.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }
    }
}

import java.util.Scanner;

/**
 * A validator for Tic-Tac-Toe game states.
 * Determines if a board is legal, whose turn it is, or if a player has won.
 */
public class TicTacToeValidator {

    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0'; // Using '0' as per original implementation
    private static final char EMPTY = '.';

    /**
     * Represents the possible states of a Tic-Tac-Toe board.
     */
    private enum GameStatus {
        X_TURN,         // First player's turn
        O_TURN,         // Second player's turn
        X_WON,          // First player won
        O_WON,          // Second player won
        DRAW,           // Game ended in a draw
        ILLEGAL         // Invalid board state
    }

    private final char[][] board;

    public TicTacToeValidator(char[][] board) {
        this.board = board;
    }

    /**
     * Evaluates the current state of the board.
     * 
     * @return The GameStatus of the current board.
     */
    public GameStatus evaluate() {
        int countX = countPieces(PLAYER_X);
        int countO = countPieces(PLAYER_O);

        // 1. Basic count validation: X must move first or equal to O, and difference cannot exceed 1.
        if (countX < countO || countX > countO + 1) {
            return GameStatus.ILLEGAL;
        }

        boolean xWins = hasWinningLine(PLAYER_X);
        boolean oWins = hasWinningLine(PLAYER_O);

        // 2. Winner validation
        if (xWins && oWins) {
            return GameStatus.ILLEGAL;
        }

        // If X won, it must be X's turn count that is one ahead (countX == countO + 1)
        if (xWins && countX != countO + 1) {
            return GameStatus.ILLEGAL;
        }

        // If O won, the counts must be equal (countX == countO)
        if (oWins && countX != countO) {
            return GameStatus.ILLEGAL;
        }

        // 3. Redundancy validation (ensures the win was achieved by the very last move)
        // If a player has multiple disjoint winning lines, the state is illegal.
        if (xWins && isWinRedundant(PLAYER_X)) {
            return GameStatus.ILLEGAL;
        }
        if (oWins && isWinRedundant(PLAYER_O)) {
            return GameStatus.ILLEGAL;
        }

        // 4. Determine final outcome
        if (xWins) return GameStatus.X_WON;
        if (oWins) return GameStatus.O_WON;
        if (countX + countO == 9) return GameStatus.DRAW;

        // 5. Determine whose turn it is
        return (countX == countO) ? GameStatus.X_TURN : GameStatus.O_TURN;
    }

    private int countPieces(char player) {
        int count = 0;
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                if (board[i][j] == player) {
                    count++;
                }
            }
        }
        return count;
    }

    private boolean hasWinningLine(char player) {
        // Check rows and columns
        for (int i = 0; i < 3; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) return true;
            if (board[0][i] == player && board[1][i] == player && board[2][i] == player) return true;
        }
        // Check diagonals
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) return true;
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) return true;

        return false;
    }

    /**
     * Checks if a player's win is redundant. 
     * A win is redundant if removing ANY single piece of that player still results in a win.
     */
    private boolean isWinRedundant(char player) {
        boolean allPiecesRedundant = true;
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                if (board[i][j] == player) {
                    board[i][j] = EMPTY;
                    boolean stillWins = hasWinningLine(player);
                    board[i][j] = player; // Backtrack

                    if (!stillWins) {
                        allPiecesRedundant = false;
                        break;
                    }
                }
            }
            if (!allPiecesRedundant) break;
        }
        return allPiecesRedundant;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNext()) {
            return;
        }

        char[][] board = new char[3][3];
        for (int i = 0; i < 3; i++) {
            String row = scanner.next();
            board[i] = row.toCharArray();
        }

        TicTacToeValidator validator = new TicTacToeValidator(board);
        GameStatus status = validator.evaluate();

        printResult(status);
        scanner.close();
    }

    private static void printResult(GameStatus status) {
        switch (status) {
            case ILLEGAL:
                System.out.println("illegal");
                break;
            case X_TURN:
                System.out.println("first");
                break;
            case O_TURN:
                System.out.println("second");
                break;
            case DRAW:
                System.out.println("draw");
                break;
            case X_WON:
                System.out.println("the first player won");
                break;
            case O_WON:
                System.out.println("the second player won");
                break;
        }
    }
}

