/**
 * Logic engine for evaluating the state of a Tic-Tac-Toe board.
 */
class TicTacToeEvaluator {

    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0';
    private static final char EMPTY = '.';

    private final char[][] board;
    private final int xCount;
    private final int oCount;
    private final boolean isBoardFull;

    public enum GameState {
        FIRST_PLAYER_WON("the first player won"),
        SECOND_PLAYER_WON("the second player won"),
        DRAW("draw"),
        NEXT_TURN_X("first"),
        NEXT_TURN_O("second"),
        ILLEGAL("illegal");

        private final String message;

        GameState(String message) {
            this.message = message;
        }

        @Override
        public String toString() {
            return message;
        }
    }

    public TicTacToeEvaluator(char[][] board) {
        this.board = board;
        int x = 0;
        int o = 0;
        boolean full = true;

        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                if (board[i][j] == PLAYER_X) {
                    x++;
                } else if (board[i][j] == PLAYER_O) {
                    o++;
                } else if (board[i][j] == EMPTY) {
                    full = false;
                }
            }
        }

        this.xCount = x;
        this.oCount = o;
        this.isBoardFull = full;
    }

    /**
     * Evaluates the board and returns the appropriate game state.
     */
    public GameState evaluate() {
        // 1. Basic count validation: X starts first, so X count must be O or O + 1
        if (xCount < oCount || xCount > oCount + 1) {
            return GameState.ILLEGAL;
        }

        boolean xWins = hasWinner(PLAYER_X);
        boolean oWins = hasWinner(PLAYER_O);

        // 2. Check if both players have winning lines (impossible in a valid game)
        if (xWins && oWins) {
            return GameState.ILLEGAL;
        }

        // 3. Handle win scenarios
        if (xWins) {
            // If X wins, X must have made the last move (X = O + 1)
            return (xCount == oCount + 1) ? GameState.FIRST_PLAYER_WON : GameState.ILLEGAL;
        }

        if (oWins) {
            // If O wins, O must have made the last move (X = O)
            return (xCount == oCount) ? GameState.SECOND_PLAYER_WON : GameState.ILLEGAL;
        }

        // 4. Handle non-win scenarios
        if (isBoardFull) {
            return GameState.DRAW;
        }

        // 5. Determine whose turn it is next
        if (xCount == oCount) {
            return GameState.NEXT_TURN_X;
        } else {
            return GameState.NEXT_TURN_O;
        }
    }

    /**
     * Checks all possible winning lines (rows, columns, diagonals) for a specific player.
     */
    private boolean hasWinner(char player) {
        // Check rows and columns
        for (int i = 0; i < 3; i++) {
            if (checkLine(board[i][0], board[i][1], board[i][2], player)) return true;
            if (checkLine(board[0][i], board[1][i], board[2][i], player)) return true;
        }

        // Check diagonals
        if (checkLine(board[0][0], board[1][1], board[2][2], player)) return true;
        if (checkLine(board[0][2], board[1][1], board[2][0], player)) return true;

        return false;
    }

    private boolean checkLine(char c1, char c2, char c3, char player) {
        return c1 == player && c2 == player && c3 == player;
    }
}

import java.util.Scanner;

/**
 * A utility to validate the state of a Tic-Tac-Toe game.
 * It determines if a board state is illegal, if a player has won,
 * if the game is a draw, or whose turn it is.
 */
public class TicTacToeValidator {

    private static final int BOARD_SIZE = 3;
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = 'O';
    private static final char EMPTY = '.';

    /**
     * Represents the possible outcomes of a Tic-Tac-Toe game state.
     */
    public enum GameStatus {
        X_WINS("the first player won"),
        O_WINS("the second player won"),
        DRAW("draw"),
        X_TURN("first"),
        O_TURN("second"),
        ILLEGAL("illegal");

        private final String message;

        GameStatus(String message) {
            this.message = message;
        }

        @Override
        public String toString() {
            return message;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];

        try {
            // Parse the input board
            for (int i = 0; i < BOARD_SIZE; i++) {
                String line = scanner.next();
                for (int j = 0; j < BOARD_SIZE; j++) {
                    board[i][j] = line.charAt(j);
                }
            }

            // Evaluate and print the result
            System.out.println(evaluateGame(board));

        } catch (Exception e) {
            // If input is malformed, treat as illegal
            System.out.println(GameStatus.ILLEGAL);
        } finally {
            scanner.close();
        }
    }

    /**
     * Evaluates the board to determine the current game status.
     * 
     * @param board 2D array representing the game board.
     * @return The GameStatus (WIN, DRAW, TURN, or ILLEGAL).
     */
    public static GameStatus evaluateGame(char[][] board) {
        int xCount = 0;
        int oCount = 0;
        int emptyCount = 0;

        // Count occurrences of each symbol
        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                if (board[i][j] == PLAYER_X) {
                    xCount++;
                } else if (board[i][j] == PLAYER_O || board[i][j] == '0') { 
                    // Supporting '0' for compatibility with original code input
                    oCount++;
                } else if (board[i][j] == EMPTY) {
                    emptyCount++;
                }
            }
        }

        boolean xWins = checkWin(board, PLAYER_X);
        boolean oWins = checkWin(board, PLAYER_O);

        // 1. Validate move counts (X is the first player)
        // X can only have the same number of moves as O, or exactly one more.
        if (xCount < oCount || xCount > oCount + 1) {
            return GameStatus.ILLEGAL;
        }

        // 2. Validate win conditions
        // Both players cannot have winning lines simultaneously.
        if (xWins && oWins) {
            return GameStatus.ILLEGAL;
        }

        // If X won, X must have made the last move (xCount == oCount + 1).
        if (xWins && xCount != oCount + 1) {
            return GameStatus.ILLEGAL;
        }

        // If O won, O must have made the last move (xCount == oCount).
        if (oWins && xCount != oCount) {
            return GameStatus.ILLEGAL;
        }

        // 3. Return actual game state
        if (xWins) return GameStatus.X_WINS;
        if (oWins) return GameStatus.O_WINS;
        if (emptyCount == 0) return GameStatus.DRAW;

        // If no one won and board is not full, determine whose turn it is.
        return (xCount == oCount) ? GameStatus.X_TURN : GameStatus.O_TURN;
    }

    /**
     * Checks if the specified player has a winning line.
     */
    private static boolean checkWin(char[][] board, char player) {
        // Check rows and columns
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (checkLine(board[i][0], board[i][1], board[i][2], player)) return true;
            if (checkLine(board[0][i], board[1][i], board[2][i], player)) return true;
        }

        // Check diagonals
        return checkLine(board[0][0], board[1][1], board[2][2], player) ||
               checkLine(board[0][2], board[1][1], board[2][0], player);
    }

    /**
     * Helper to check if three characters match the player.
     */
    private static boolean checkLine(char c1, char c2, char c3, char player) {
        return c1 == player && c2 == player && c3 == player;
    }
}

