/**
 * Represents the state of the TicTacToe board.
 */
class Board {
    public static final char PLAYER_X = 'X';
    public static final char PLAYER_O = '0'; // Preserving '0' as per original code
    public static final char EMPTY = '.';

    private final char[][] grid;
    private int countX = 0;
    private int countO = 0;
    private int emptyCells = 0;

    public Board(char[][] grid) {
        this.grid = grid;
        calculateStats();
    }

    private void calculateStats() {
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                if (grid[i][j] == PLAYER_X) countX++;
                else if (grid[i][j] == PLAYER_O) countO++;
                else if (grid[i][j] == EMPTY) emptyCells++;
            }
        }
    }

    public char getCell(int row, int col) {
        return grid[row][col];
    }

    public int getCountX() { return countX; }
    public int getCountO() { return countO; }
    public boolean isFull() { return emptyCells == 0; }
}

/**
 * Result states of the game evaluation.
 */
enum GameResult {
    ILLEGAL("illegal"),
    FIRST_PLAYER_WON("the first player won"),
    SECOND_PLAYER_WON("the second player won"),
    DRAW("draw"),
    FIRST_PLAYER_TURN("first"),
    SECOND_PLAYER_TURN("second");

    private final String displayMessage;

    GameResult(String displayMessage) {
        this.displayMessage = displayMessage;
    }

    public String getDisplayMessage() {
        return displayMessage;
    }
}

/**
 * Logic engine to evaluate the validity and state of the game.
 */
class GameEngine {
    private final Board board;

    public GameEngine(Board board) {
        this.board = board;
    }

    public GameResult evaluate() {
        if (isIllegal()) {
            return GameResult.ILLEGAL;
        }

        if (checkWin(Board.PLAYER_X)) {
            return GameResult.FIRST_PLAYER_WON;
        }

        if (checkWin(Board.PLAYER_O)) {
            return GameResult.SECOND_PLAYER_WON;
        }

        if (board.isFull()) {
            return GameResult.DRAW;
        }

        // If no one won and board is not full, determine whose turn it is
        return (board.getCountX() == board.getCountO()) 
                ? GameResult.FIRST_PLAYER_TURN 
                : GameResult.SECOND_PLAYER_TURN;
    }

    /**
     * Validates if the current board state violates TicTacToe rules.
     */
    private boolean isIllegal() {
        boolean winX = checkWin(Board.PLAYER_X);
        boolean winO = checkWin(Board.PLAYER_O);
        int x = board.getCountX();
        int o = board.getCountO();

        // Rule: Both players cannot have winning configurations
        if (winX && winO) return true;

        // Rule: Turn counts must be valid (X starts, so X count is either equal to O or O + 1)
        if (o > x || (x - o) > 1) return true;

        // Rule: If X wins, X must have made the last move (x = o + 1)
        if (winX && x != o + 1) return true;

        // Rule: If O wins, it must be X's turn to have just moved (x = o)
        if (winO && x != o) return true;

        return false;
    }

    /**
     * Checks if a specific player has a winning line.
     */
    private boolean checkWin(char player) {
        // Check Rows and Columns
        for (int i = 0; i < 3; i++) {
            if (isLine(i, 0, i, 2, player)) return true; // Row
            if (isLine(0, i, 2, i, player)) return true; // Column
        }
        // Check Diagonals
        return isLine(0, 0, 2, 2, player) || isLine(0, 2, 2, 0, player);
    }

    /**
     * Helper to check if a line of cells contains the player's character.
     */
    private boolean isLine(int r1, int c1, int r2, int c2, char player) {
        // This is a simplified check for 3-in-a-row logic
        // For rows/cols, we check the specific axis. For diagonals, we check the corners.
        // Given the 3x3 constraints, a more explicit approach for diagonals/lines is cleaner:
        if (r1 == r2) { // Horizontal
            return board.getCell(r1, 0) == player && board.getCell(r1, 1) == player && board.getCell(r1, 2) == player;
        } else if (c1 == c2) { // Vertical
            return board.getCell(0, c1) == player && board.getCell(1, c1) == player && board.getCell(2, c1) == player;
        } else { // Diagonal
            if (r1 == 0 && c1 == 0) // Main diagonal
                return board.getCell(0, 0) == player && board.getCell(1, 1) == player && board.getCell(2, 2) == player;
            if (r1 == 0 && c1 == 2) // Anti diagonal
                return board.getCell(0, 2) == player && board.getCell(1, 1) == player && board.getCell(2, 0) == player;
        }
        return false;
    }
}

