/**
 * Represents the possible outcomes of a Tic-Tac-Toe game evaluation.
 */
enum GameState {
    ILLEGAL("illegal"),
    FIRST_TURN("first"),
    SECOND_TURN("second"),
    X_WON("the first player won"),
    O_WON("the second player won"),
    DRAW("draw");

    private final String message;

    GameState(String message) {
        this.message = message;
    }

    @Override
    public String toString() {
        return this.message;
    }
}

/**
 * Logic engine for evaluating a Tic-Tac-Toe board state.
 */
class TicTacToeGame {
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0'; // Using '0' to match original implementation
    private static final char EMPTY = '.';

    private static final int[][] WINNING_COMBINATIONS = {
        {0, 1, 2}, {3, 4, 5}, {6, 7, 8}, // Rows
        {0, 3, 6}, {1, 4, 7}, {2, 5, 8}, // Cols
        {0, 4, 8}, {2, 4, 6}             // Diagonals
    };

    private final String board;
    private final int countX;
    private final int countO;
    private final int countEmpty;

    public TicTacToeGame(String board) {
        this.board = board;
        int x = 0;
        int o = 0;
        int empty = 0;

        for (char c : board.toCharArray()) {
            if (c == PLAYER_X) x++;
            else if (c == PLAYER_O) o++;
            else if (c == EMPTY) empty++;
        }

        this.countX = x;
        this.countO = o;
        this.countEmpty = empty;
    }

    /**
     * Evaluates the current board state and returns the resulting GameState.
     */
    public GameState evaluate() {
        if (isIllegal()) {
            return GameState.ILLEGAL;
        }

        boolean xWins = checkWinner(PLAYER_X);
        boolean oWins = checkWinner(PLAYER_O);

        if (xWins) return GameState.X_WON;
        if (oWins) return GameState.O_WON;
        if (countEmpty == 9) return GameState.FIRST_TURN; // Equivalent to "emptyBoard"
        if (countEmpty == 0) return GameState.DRAW;

        // If no winner and not draw, determine whose turn it is
        return (countX > countO) ? GameState.SECOND_TURN : GameState.FIRST_TURN;
    }

    private boolean isIllegal() {
        // Rule 1: Basic count mismatches
        if (countO > countX || countX > countO + 1) {
            return true;
        }

        boolean xWins = checkWinner(PLAYER_X);
        boolean oWins = checkWinner(PLAYER_O);

        // Rule 2: Both players cannot have winning configurations
        if (xWins && oWins) {
            return true;
        }

        // Rule 3: If O wins, X and O must have the same number of marks
        if (oWins && countX != countO) {
            return true;
        }

        // Rule 4: If X wins, X must have exactly one more mark than O
        if (xWins && countX != countO + 1) {
            return true;
        }

        return false;
    }

    private boolean checkWinner(char player) {
        for (int[] combo : WINNING_COMBINATIONS) {
            if (board.charAt(combo[0]) == player &&
                board.charAt(combo[1]) == player &&
                board.charAt(combo[2]) == player) {
                return true;
            }
        }
        return false;
    }
}

