import java.util.StringTokenizer;

/**
 * A refactored Tic-Tac-Toe validator and state evaluator.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            TicTacToeGame game = new TicTacToeGame(reader);
            GameResult result = game.evaluate();
            writer.println(result.getMessage());
        } catch (Exception e) {
            writer.println("error");
        } finally {
            writer.close();
        }
    }

    /**
     * Represents the possible outcomes of a Tic-Tac-Toe game state.
     */
    enum GameResult {
        FIRST_PLAYER_WON("the first player won"),
        SECOND_PLAYER_WON("the second player won"),
        DRAW("draw"),
        IN_PROGRESS("in progress"),
        ILLEGAL("illegal");

        private final String message;

        GameResult(String message) {
            this.message = message;
        }

        public String getMessage() {
            return message;
        }
    }

    /**
     * Logic engine for the Tic-Tac-Toe game.
     */
    static class TicTacToeGame {
        private static final char PLAYER_X = 'X';
        private static final char PLAYER_O = '0';
        private static final char EMPTY = '.';
        private static final int SIZE = 3;

        private final char[][] board = new char[SIZE][SIZE];

        public TicTacToeGame(FastReader reader) {
            for (int i = 0; i < SIZE; i++) {
                String row = reader.nextString();
                board[i] = row.toCharArray();
            }
        }

        /**
         * Evaluates the current board state and returns the game result.
         */
        public GameResult evaluate() {
            int countX = countSymbol(PLAYER_X);
            int countO = countSymbol(PLAYER_O);

            // Basic rule: X goes first, so X count must be equal to O or O + 1
            if (countX != countO && countX != countO + 1) {
                return GameResult.ILLEGAL;
            }

            boolean xWins = checkWin(PLAYER_X);
            boolean oWins = checkWin(PLAYER_O);

            // Rule: Both players cannot have winning lines simultaneously
            if (xWins && oWins) {
                return GameResult.ILLEGAL;
            }

            if (xWins) {
                // X can only win if they just made the move that resulted in countX = countO + 1
                return (countX == countO + 1) ? GameResult.FIRST_PLAYER_WON : GameResult.ILLEGAL;
            }

            if (oWins) {
                // O can only win if they just made the move that resulted in countX = countO
                return (countX == countO) ? GameResult.SECOND_PLAYER_WON : GameResult.ILLEGAL;
            }

            // If no one has won, check if the board is full
            if (countEmptyCells() == 0) {
                return GameResult.DRAW;
            }

            // Otherwise, the game is still ongoing
            return GameResult.IN_PROGRESS;
        }

        private int countSymbol(char symbol) {
            int count = 0;
            for (int i = 0; i < SIZE; i++) {
                for (int j = 0; j < SIZE; j++) {
                    if (board[i][j] == symbol) {
                        count++;
                    }
                }
            }
            return count;
        }

        private int countEmptyCells() {
            int count = 0;
            for (int i = 0; i < SIZE; i++) {
                for (int j = 0; j < SIZE; j++) {
                    if (board[i][j] == EMPTY) {
                        count++;
                    }
                }
            }
            return count;
        }

        private boolean checkWin(char p) {
            // Check rows and columns
            for (int i = 0; i < SIZE; i++) {
                if (checkLine(board[i][0], board[i][1], board[i][2], p)) return true;
                if (checkLine(board[0][i], board[1][i], board[2][i], p)) return true;
            }
            // Check diagonals
            return checkLine(board[0][0], board[1][1], board[2][2], p) ||
                   checkLine(board[0][2], board[1][1], board[2][0], p);
        }

        private boolean checkLine(char c1, char c2, char c3, char p) {
            return c1 == p && c2 == p && c3 == p;
        }
    }

    /**
     * Utility class for fast input reading.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            this.reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String nextString() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return "";
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return tokenizer.nextToken();
        }
    }
}

