/**
 * Domain service responsible for evaluating the state of a Tic-Tac-Toe game.
 */
class TicTacToeEvaluator {
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0'; // Note: Using '0' as per original requirements

    private static final int[][] WIN_COMBINATIONS = {
        {0, 1, 2}, {3, 4, 5}, {6, 7, 8}, // Rows
        {0, 3, 6}, {1, 4, 7}, {2, 5, 8}, // Columns
        {0, 4, 8}, {2, 4, 6}             // Diagonals
    };

    private final Grid grid;

    public TicTacToeEvaluator(Grid grid) {
        this.grid = grid;
    }

    public GameResult evaluate() {
        int xCount = 0;
        int oCount = 0;

        for (char c : grid.getTiles()) {
            if (c == PLAYER_X) {
                xCount++;
            } else if (c == PLAYER_O) {
                oCount++;
            } else {
                return GameResult.ILLEGAL;
            }
        }

        // 1. Validate move counts (X starts first, so X must be equal to or 1 greater than O)
        if (oCount > xCount || (xCount - oCount) > 1) {
            return GameResult.ILLEGAL;
        }

        boolean xWins = checkWin(PLAYER_X);
        boolean oWins = checkWin(PLAYER_O);

        // 2. Validate win conditions
        if (xWins && oWins) {
            return GameResult.ILLEGAL;
        }

        if (xWins) {
            // If X won, X must have made the last move
            return (xCount == oCount + 1) ? GameResult.FIRST_PLAYER_WON : GameResult.ILLEGAL;
        }

        if (oWins) {
            // If O won, O must have made the last move (X and O equal)
            return (xCount == oCount) ? GameResult.SECOND_PLAYER_WON : GameResult.ILLEGAL;
        }

        // 3. No winner, determine if Draw or Next Player
        if (xCount + oCount == grid.getTotalCells()) {
            return GameResult.DRAW;
        } else {
            return (xCount == oCount) ? GameResult.NEXT_FIRST_PLAYER : GameResult.NEXT_SECOND_PLAYER;
        }
    }

    private boolean checkWin(char player) {
        for (int[] combo : WIN_COMBINATIONS) {
            if (grid.get(combo[0]) == player &&
                grid.get(combo[1]) == player &&
                grid.get(combo[2]) == player) {
                return true;
            }
        }
        return false;
    }
}

