/**
 * Represents the 3x3 Tic-Tac-Toe board.
 */
class Board {
    private static final int SIZE = 3;
    private final char[][] grid = new char[SIZE][SIZE];
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0'; // Maintaining original quirk of using digit '0'

    public Board(String[] lines) {
        for (int i = 0; i < SIZE; i++) {
            for (int j = 0; j < SIZE; j++) {
                grid[i][j] = lines[i].charAt(j);
            }
        }
    }

    public int countPlayer(char player) {
        int count = 0;
        for (int i = 0; i < SIZE; i++) {
            for (int j = 0; j < SIZE; j++) {
                if (grid[i][j] == player) {
                    count++;
                }
            }
        }
        return count;
    }

    public boolean hasWon(char player) {
        // Check rows and columns
        for (int i = 0; i < SIZE; i++) {
            if (checkLine(grid[i][0], grid[i][1], grid[i][2], player)) return true;
            if (checkLine(grid[0][i], grid[1][i], grid[2][i], player)) return true;
        }
        // Check diagonals
        return checkLine(grid[0][0], grid[1][1], grid[2][2], player) ||
               checkLine(grid[0][2], grid[1][1], grid[2][0], player);
    }

    private boolean checkLine(char c1, char c2, char c3, char player) {
        return c1 == player && c2 == player && c3 == player;
    }

    public boolean isFull() {
        return countPlayer(PLAYER_X) + countPlayer(PLAYER_O) == SIZE * SIZE;
    }

    public char getPlayerX() { return PLAYER_X; }
    public char getPlayerO() { return PLAYER_O; }
}

/**
 * Contains the business logic to analyze the game state.
 */
class TicTacToe {
    private final Board board;

    public TicTacToe(Board board) {
        this.board = board;
    }

    public GameResult evaluate() {
        int countX = board.countPlayer(board.getPlayerX());
        int countO = board.countPlayer(board.getPlayerO());

        boolean winX = board.hasWon(board.getPlayerX());
        boolean winO = board.hasWon(board.getPlayerO());

        // 1. Check for illegal move counts
        // X goes first, so X can only have equal to O or O + 1
        if (countX > countO + 1 || countO > countX) {
            return GameResult.ILLEGAL;
        }

        // 2. Check for illegal win states
        if (winX && winO) {
            return GameResult.ILLEGAL;
        }
        if (winX && countX != countO + 1) {
            return GameResult.ILLEGAL;
        }
        if (winO && countX != countO) {
            return GameResult.ILLEGAL;
        }

        // 3. Determine winner or current state
        if (winX) {
            return GameResult.FIRST_PLAYER_WON;
        }
        if (winO) {
            return GameResult.SECOND_PLAYER_WON;
        }
        if (board.isFull()) {
            return GameResult.DRAW;
        }

        // 4. Determine whose turn it is
        return (countX == countO) ? GameResult.FIRST_TURN_TO_MOVE : GameResult.SECOND_TURN_TO_MOVE;
    }
}

