import java.util.Scanner;

/**
 * A validator and predictor for Tic-Tac-Toe game states.
 * Analyzes a 3x3 grid to determine if the state is legal, who won, 
 * or whose turn it is next.
 */
public class TicTacToeValidator {

    private static final char PLAYER_X = 'x';
    private static final char PLAYER_O = '0'; // Note: Using '0' as per original requirement
    private static final char EMPTY = '.';

    private final char[][] board = new char[3][3];
    private int xMoves = 0;
    private int oMoves = 0;
    private int emptyCells = 0;

    public static void main(String[] args) {
        TicTacToeValidator game = new TicTacToeValidator();
        game.run();
    }

    /**
     * Entry point for the application logic.
     */
    public void run() {
        Scanner scanner = new Scanner(System.in);
        if (readBoard(scanner)) {
            analyzeGameState();
        }
        scanner.close();
    }

    /**
     * Reads 3 lines of input from the scanner to populate the board.
     * 
     * @param scanner The scanner to read from.
     * @return true if reading was successful, false otherwise.
     */
    private boolean readBoard(Scanner scanner) {
        try {
            for (int i = 0; i < 3; i++) {
                String line = scanner.next();
                for (int j = 0; j < 3; j++) {
                    char cell = Character.toLowerCase(line.charAt(j));
                    board[i][j] = cell;
                    updateCounts(cell);
                }
            }
            return true;
        } catch (Exception e) {
            return false;
        }
    }

    private void updateCounts(char cell) {
        if (cell == PLAYER_X) {
            xMoves++;
        } else if (cell == PLAYER_O) {
            oMoves++;
        } else if (cell == EMPTY) {
            emptyCells++;
        }
    }

    /**
     * Core logic engine that determines the status of the game.
     */
    private void analyzeGameState() {
        // 1. Validate Turn Order
        // X always goes first, so xMoves must be equal to oMoves or oMoves + 1.
        if (oMoves > xMoves || xMoves - oMoves > 1) {
            printResult("illegal");
            return;
        }

        boolean xWon = checkWinner(PLAYER_X);
        boolean oWon = checkWinner(PLAYER_O);

        // 2. Validate Win Conditions
        if (xWon && oWon) {
            printResult("illegal");
            return;
        }

        if (xWon) {
            // If X wins, it must have been X's turn that just finished (xMoves = oMoves + 1)
            if (xMoves == oMoves + 1) {
                printResult("the first player won");
            } else {
                printResult("illegal");
            }
            return;
        }

        if (oWon) {
            // If O wins, it must have been O's turn that just finished (xMoves = oMoves)
            if (xMoves == oMoves) {
                printResult("the second player won");
            } else {
                printResult("illegal");
            }
            return;
        }

        // 3. Handle non-winning states
        if (emptyCells == 0) {
            printResult("draw");
        } else {
            // If no one won and there are moves left, predict the next player
            // If counts are equal, it's X's turn (first)
            // If X has one more move, it's O's turn (second)
            printResult(xMoves == oMoves ? "first" : "second");
        }
    }

    /**
     * Checks if the specified player has a winning line.
     */
    private boolean checkWinner(char player) {
        // Check rows and columns
        for (int i = 0; i < 3; i++) {
            if (checkLine(board[i][0], board[i][1], board[i][2], player)) return true;
            if (checkLine(board[0][i], board[1][i], board[2][i], player)) return true;
        }
        // Check diagonals
        return checkLine(board[0][0], board[1][1], board[2][2], player) ||
               checkLine(board[0][2], board[1][1], board[2][0], player);
    }

    /**
     * Helper to check if three specific cells belong to a player.
     */
    private boolean checkLine(char c1, char c2, char c3, char player) {
        return c1 == player && c2 == player && c3 == player;
    }

    private void printResult(String message) {
        System.out.println(message);
    }
}

