/**
 * Represents a Tic-Tac-Toe game engine that validates the state of a 3x3 board.
 */
class TicTacToe {
    private static final int SIZE = 3;
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0';
    private static final char EMPTY = '.';

    private final char[][] board = new char[SIZE][SIZE];
    private int countX = 0;
    private int countO = 0;
    private int countEmpty = 0;

    /**
     * Populates the board from a scanner.
     * @param scanner The input source.
     */
    public void loadBoard(Scanner scanner) {
        for (int i = 0; i < SIZE; i++) {
            String line = scanner.nextLine();
            for (int j = 0; j < SIZE; j++) {
                char cell = line.charAt(j);
                board[i][j] = cell;
                updateCounts(cell);
            }
        }
    }

    private void updateCounts(char cell) {
        if (cell == PLAYER_X) countX++;
        else if (cell == PLAYER_O) countO++;
        else if (cell == EMPTY) countEmpty++;
    }

    /**
     * Evaluates the current state of the board and returns a descriptive string.
     * @return The status of the game.
     */
    public String evaluateGameState() {
        // 1. Validate move counts: X must be equal to O or O + 1
        if (countX < countO || countX > countO + 1) {
            return "illegal";
        }

        boolean xWins = hasWinner(PLAYER_X);
        boolean oWins = hasWinner(PLAYER_O);

        // 2. Check for impossible win states
        if (xWins && oWins) return "illegal";

        // If X won, X must have been the last player to move (countX == countO + 1)
        if (xWins && countX != countO + 1) return "illegal";

        // If O won, O must have been the last player to move (countX == countO)
        if (oWins && countX != countO) return "illegal";

        // 3. Determine the result
        if (xWins) return "the first player won";
        if (oWins) return "the second player won";
        if (countEmpty == 0) return "draw";

        // If no one won and game is ongoing, determine whose turn it is
        return (countX == countO) ? "first" : "second";
    }

    /**
     * Checks if a specific player has a winning line.
     * @param player The character representing the player.
     * @return true if the player has won.
     */
    private boolean hasWinner(char player) {
        return checkRows(player) || checkCols(player) || checkDiagonals(player);
    }

    private boolean checkRows(char player) {
        for (int i = 0; i < SIZE; i++) {
            boolean win = true;
            for (int j = 0; j < SIZE; j++) {
                if (board[i][j] != player) {
                    win = false;
                    break;
                }
            }
            if (win) return true;
        }
        return false;
    }

    private boolean checkCols(char player) {
        for (int j = 0; j < SIZE; j++) {
            boolean win = true;
            for (int i = 0; i < SIZE; i++) {
                if (board[i][j] != player) {
                    win = false;
                    break;
                }
            }
            if (win) return true;
        }
        return false;
    }

    private boolean checkDiagonals(char player) {
        // Primary diagonal
        boolean diag1 = true;
        for (int i = 0; i < SIZE; i++) {
            if (board[i][i] != player) {
                diag1 = false;
                break;
            }
        }
        if (diag1) return true;

        // Anti-diagonal
        boolean diag2 = true;
        for (int i = 0; i < SIZE; i++) {
            if (board[i][SIZE - 1 - i] != player) {
                diag2 = false;
                break;
            }
        }
        return diag2;
    }
}

