import java.util.Scanner;

/**
 * A refactored TicTacToe validator that determines the state of a 3x3 game board.
 */
public class TicTacToe {

    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0'; // Using '0' as per original requirement

    /**
     * Represents the possible valid or illegal states of the game.
     */
    public enum Outcome {
        FIRST_PLAYER_TURN("first"),
        SECOND_PLAYER_TURN("second"),
        DRAW("draw"),
        FIRST_PLAYER_WON("the first player won"),
        SECOND_PLAYER_WON("the second player won"),
        ILLEGAL("illegal");

        private final String message;

        Outcome(String message) {
            this.message = message;
        }

        @Override
        public String toString() {
            return message;
        }
    }

    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);

        try {
            char[] boardData = new char[9];
            for (int i = 0; i < 3; i++) {
                String row = input.next();
                for (int j = 0; j < 3; j++) {
                    boardData[i * 3 + j] = row.charAt(j);
                }
            }

            Board board = new Board(boardData);
            Outcome outcome = GameValidator.validate(board);
            System.out.println(outcome);

        } catch (Exception e) {
            System.out.println(Outcome.ILLEGAL);
        } finally {
            input.close();
        }
    }

    /**
     * Holds the state of the 3x3 TicTacToe board.
     */
    static class Board {
        private final char[] grid;

        public Board(char[] grid) {
            this.grid = grid;
        }

        public int countMoves(char player) {
            int count = 0;
            for (char cell : grid) {
                if (cell == player) count++;
            }
            return count;
        }

        public int getTotalMoves() {
            return grid.length;
        }

        public char getCell(int index) {
            return grid[index];
        }

        public boolean hasWinner(char player) {
            int[][] winningCombinations = {
                {0, 1, 2}, {3, 4, 5}, {6, 7, 8}, // Rows
                {0, 3, 6}, {1, 4, 7}, {2, 5, 8}, // Columns
                {0, 4, 8}, {2, 4, 6}             // Diagonals
            };

            for (int[] combo : winningCombinations) {
                if (grid[combo[0]] == player && 
                    grid[combo[1]] == player && 
                    grid[combo[2]] == player) {
                    return true;
                }
            }
            return false;
        }
    }

    /**
     * Contains the business rules for validating a TicTacToe board state.
     */
    static class GameValidator {

        public static Outcome validate(Board board) {
            int countX = board.countMoves(PLAYER_X);
            int countO = board.countMoves(PLAYER_O);

            // 1. Validate turn order/count parity
            // X goes first, so X must be equal to O or O + 1.
            if (countO > countX || countX > countO + 1) {
                return Outcome.ILLEGAL;
            }

            boolean xWins = board.hasWinner(PLAYER_X);
            boolean oWins = board.hasWinner(PLAYER_O);

            // 2. Validate win conditions
            if (xWins && oWins) {
                return Outcome.ILLEGAL;
            }

            if (xWins) {
                // If X won, it must be X's turn that just finished (countX = countO + 1)
                return (countX == countO + 1) ? Outcome.FIRST_PLAYER_WON : Outcome.ILLEGAL;
            }

            if (oWins) {
                // If O won, counts must be equal
                return (countX == countO) ? Outcome.SECOND_PLAYER_WON : Outcome.ILLEGAL;
            }

            // 3. Determine remaining game state if no one has won
            if (countX + countO == 9) {
                return Outcome.DRAW;
            }

            if (countX == countO) {
                return Outcome.FIRST_PLAYER_TURN;
            } else {
                return Outcome.SECOND_PLAYER_TURN;
            }
        }
    }
}

import java.util.Scanner;

/**
 * A program to evaluate the state of a Tic-Tac-Toe game.
 * It determines if a player has won, if the game is a draw, 
 * whose turn it is next, or if the board state is illegal.
 */
public class Tictactoe {

    private static final char PLAYER_X = 'X';
    private static final char PLAYER_ZERO = '0';
    private static final int BOARD_SIZE = 3;
    private static final int TOTAL_CELLS = 9;

    private final char[][] board = new char[BOARD_SIZE][BOARD_SIZE];

    public static void main(String[] args) {
        Tictactoe game = new Tictactoe();
        game.run();
    }

    /**
     * Orchestrates the reading, evaluation, and output of the game state.
     */
    public void run() {
        Scanner scanner = new Scanner(System.in);
        if (loadBoard(scanner)) {
            System.out.println(evaluateGameState());
        }
        scanner.close();
    }

    /**
     * Reads the board input from the user.
     * @return true if input was successfully loaded.
     */
    private boolean loadBoard(Scanner scanner) {
        try {
            for (int i = 0; i < BOARD_SIZE; i++) {
                String line = scanner.next();
                if (line.length() != BOARD_SIZE) return false;
                for (int j = 0; j < BOARD_SIZE; j++) {
                    board[i][j] = line.charAt(j);
                }
            }
            return true;
        } catch (Exception e) {
            return false;
        }
    }

    /**
     * Evaluates the current board state based on Tic-Tac-Toe rules.
     * 
     * @return A string representing the game outcome.
     */
    private String evaluateGameState() {
        int xCount = countOccurrences(PLAYER_X);
        int zeroCount = countOccurrences(PLAYER_ZERO);
        int totalMoves = xCount + zeroCount;
        int diff = xCount - zeroCount;

        boolean xWins = hasWon(PLAYER_X);
        boolean zeroWins = hasWon(PLAYER_ZERO);

        // Rule 1: First player won
        if (diff == 1 && xWins && !zeroWins) {
            return "the first player won";
        }

        // Rule 2: Second player won
        if (diff == 0 && !xWins && zeroWins) {
            return "the second player won";
        }

        // Rule 3: Draw (Full board, no winner, X moved last)
        if (totalMoves == TOTAL_CELLS && diff == 1 && !xWins && !zeroWins) {
            return "draw";
        }

        // Rule 4: Next turn is Second Player (X moved, no winner, board not full)
        if (diff == 1 && totalMoves < TOTAL_CELLS && !xWins && !zeroWins) {
            return "second";
        }

        // Rule 5: Next turn is First Player (Zero moved, no winner, board not full)
        if (diff == 0 && totalMoves < TOTAL_CELLS && !xWins && !zeroWins) {
            return "first";
        }

        // Rule 6: Any other state is considered illegal (e.g., both winning, invalid move counts)
        return "illegal";
    }

    /**
     * Counts how many times a specific character appears on the board.
     */
    private int countOccurrences(char target) {
        int count = 0;
        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                if (board[i][j] == target) {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Checks if the specified player has a winning line (row, column, or diagonal).
     */
    private boolean hasWon(char player) {
        // Check Rows and Columns
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (checkLine(board[i][0], board[i][1], board[i][2], player)) return true;
            if (checkLine(board[0][i], board[1][i], board[2][i], player)) return true;
        }

        // Check Diagonals
        if (checkLine(board[0][0], board[1][1], board[2][2], player)) return true;
        if (checkLine(board[0][2], board[1][1], board[2][0], player)) return true;

        return false;
    }

    /**
     * Helper to check if three characters satisfy a win condition.
     */
    private boolean checkLine(char c1, char c2, char c3, char player) {
        return c1 == player && c2 == player && c3 == player;
    }
}

