/**
 * Represents the logic and rules of a Tic-Tac-Toe game.
 */
class TicTacToeGame {
    private static final int SIZE = 3;
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = 'O';
    private static final char EMPTY = '.';

    private final char[][] board;
    private final int xCount;
    private final int oCount;
    private final boolean xWins;
    private final boolean oWins;

    public TicTacToeGame(char[][] board) {
        this.board = board;

        int xCountTemp = 0;
        int oCountTemp = 0;

        for (int i = 0; i < SIZE; i++) {
            for (int j = 0; j < SIZE; j++) {
                if (board[i][j] == PLAYER_X) {
                    xCountTemp++;
                } else if (board[i][j] == PLAYER_O) {
                    oCountTemp++;
                }
            }
        }

        this.xCount = xCountTemp;
        this.oCount = oCountTemp;
        this.xWins = checkWin(PLAYER_X);
        this.oWins = checkWin(PLAYER_O);
    }

    /**
     * Evaluates the current board state and returns the result string.
     */
    public String evaluateResult() {
        if (isIllegal()) {
            return "illegal";
        }
        if (xWins) {
            return "the first player won";
        }
        if (oWins) {
            return "the second player won";
        }
        if (xCount + oCount == SIZE * SIZE) {
            return "draw";
        }

        // If no one won and it's not a draw, determine whose turn it is
        return (xCount > oCount) ? "second" : "first";
    }

    /**
     * Validates the board against standard Tic-Tac-Toe rules.
     */
    private boolean isIllegal() {
        // 1. Both players cannot have winning configurations simultaneously
        if (xWins && oWins) return true;

        // 2. Player X (first) must have either equal moves or one more move than Player O
        if (xCount < oCount || xCount > oCount + 1) return true;

        // 3. If X won, X must have made the last move (X count = O count + 1)
        if (xWins && xCount != oCount + 1) return true;

        // 4. If O won, O must have made the last move (X count = O count)
        if (oWins && xCount != oCount) return true;

        return false;
    }

    /**
     * Checks if the specified player has a winning line.
     */
    private boolean checkWin(char player) {
        // Check rows and columns
        for (int i = 0; i < SIZE; i++) {
            if (checkLine(board[i][0], board[i][1], board[i][2], player)) return true;
            if (checkLine(board[0][i], board[1][i], board[2][i], player)) return true;
        }

        // Check diagonals
        if (checkLine(board[0][0], board[1][1], board[2][2], player)) return true;
        if (checkLine(board[0][2], board[1][1], board[2][0], player)) return true;

        return false;
    }

    private boolean checkLine(char c1, char c2, char c3, char player) {
        return c1 == player && c2 == player && c3 == player;
    }
}

import java.util.Scanner;

/**
 * A validator for Tic-Tac-Toe game states.
 * Determines if a board configuration is legal and identifies the winner or next player.
 */
public class TicTacToeValidator {

    private static final char X_PLAYER = 'X';
    private static final char O_PLAYER = '0'; // Note: Using '0' as per original requirement
    private static final int BOARD_SIZE = 3;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];

        try {
            // Read the board from input
            for (int i = 0; i < BOARD_SIZE; i++) {
                if (!scanner.hasNext()) break;
                String line = scanner.next();
                for (int j = 0; j < BOARD_SIZE; j++) {
                    board[i][j] = line.charAt(j);
                }
            }

            TicTacToeGame game = new TicTacToeGame(board);
            System.out.println(game.evaluateGameState());

        } catch (Exception e) {
            // In a production environment, use a logger.
            // For this utility, we treat unexpected input as an error.
        } finally {
            scanner.close();
        }
    }

    /**
     * Encapsulates the game rules and state evaluation.
     */
    static class TicTacToeGame {
        private final char[][] board;

        public TicTacToeGame(char[][] board) {
            this.board = board;
        }

        /**
         * Evaluates the board and returns the status string.
         * 
         * @return "the first player won", "the second player won", "draw", 
         *         "first", "second", or "illegal".
         */
        public String evaluateGameState() {
            int xCount = countPlayer(X_PLAYER);
            int oCount = countPlayer(O_PLAYER);

            // Rule 1: Validate turn count parity
            // X (first player) must have moved either the same amount as O or one more.
            if (xCount < oCount || xCount > oCount + 1) {
                return "illegal";
            }

            boolean xWins = checkWin(X_PLAYER);
            boolean oWins = checkWin(O_PLAYER);

            // Rule 2: Both players cannot have winning configurations simultaneously
            if (xWins && oWins) {
                return "illegal";
            }

            // Rule 3: If X wins, it must have been X's turn that just ended (xCount = oCount + 1)
            if (xWins && xCount != oCount + 1) {
                return "illegal";
            }

            // Rule 4: If O wins, it must have been O's turn that just ended (xCount = oCount)
            if (oWins && xCount != oCount) {
                return "illegal";
            }

            // Determination of result
            if (xWins) {
                return "the first player won";
            }
            if (oWins) {
                return "the second player won";
            }
            if (isBoardFull(xCount, oCount)) {
                return "draw";
            }

            // If no winner and board is not full, return whose turn is next
            return (xCount == oCount) ? "first" : "second";
        }

        private int countPlayer(char player) {
            int count = 0;
            for (int i = 0; i < BOARD_SIZE; i++) {
                for (int j = 0; j < BOARD_SIZE; j++) {
                    if (board[i][j] == player) {
                        count++;
                    }
                }
            }
            return count;
        }

        private boolean isBoardFull(int xCount, int oCount) {
            return (xCount + oCount) == (BOARD_SIZE * BOARD_SIZE);
        }

        /**
         * Checks if the specified player has a winning line.
         */
        private boolean checkWin(char player) {
            // Check Rows and Columns
            for (int i = 0; i < BOARD_SIZE; i++) {
                if (checkLine(player, i, 0, 0, 1)) return true; // Horizontal
                if (checkLine(player, 0, i, 1, 0)) return true; // Vertical
            }

            // Check Diagonals
            if (checkLine(player, 0, 0, 1, 1)) return true; // Main diagonal
            if (checkLine(player, 0, BOARD_SIZE - 1, 1, -1)) return true; // Anti-diagonal

            return false;
        }

        /**
         * Helper to check if a line starting at (startRow, startCol) in direction (rowDelta, colDelta) 
         * consists entirely of the specified player.
         */
        private boolean checkLine(char player, int startRow, int startCol, int rowDelta, int colDelta) {
            for (int step = 0; step < BOARD_SIZE; step++) {
                int r = startRow + (step * rowDelta);
                int c = startCol + (step * colDelta);

                // Bounds check (though logic should prevent out of bounds)
                if (r < 0 || r >= BOARD_SIZE || c < 0 || c >= BOARD_SIZE || board[r][c] != player) {
                    return false;
                }
            }
            return true;
        }
    }
}

import java.util.Scanner;

/**
 * A validator for Tic-Tac-Toe game states.
 * Determines if a given 3x3 board represents a legal game state, 
 * a winner, a draw, or whose turn it is.
 */
public class TicTacToeValidator {

    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0';
    private static final int BOARD_SIZE = 3;

    private final char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
    private int countX = 0;
    private int countO = 0;

    public static void main(String[] args) {
        TicTacToeValidator validator = new TicTacToeValidator();
        validator.run();
    }

    /**
     * Orchestrates the reading of input and the output of results.
     */
    public void run() {
        Scanner scanner = new Scanner(System.in);

        if (!readBoard(scanner)) {
            return;
        }

        processResult();
        scanner.close();
    }

    /**
     * Reads the 3x3 board from the input.
     * 
     * @param scanner The scanner to read from.
     * @return true if input was successfully read, false otherwise.
     */
    private boolean readBoard(Scanner scanner) {
        try {
            for (int i = 0; i < BOARD_SIZE; i++) {
                if (!scanner.hasNext()) return false;
                String row = scanner.next();
                for (int j = 0; j < BOARD_SIZE; j++) {
                    char cell = row.charAt(j);
                    board[i][j] = cell;
                    if (cell == PLAYER_X) {
                        countX++;
                    } else if (cell == PLAYER_O) {
                        countO++;
                    }
                }
            }
            return true;
        } catch (Exception e) {
            return false;
        }
    }

    /**
     * Evaluates the board and prints the appropriate game status.
     */
    private void processResult() {
        boolean isXWinner = checkWin(PLAYER_X);
        boolean isOWinner = checkWin(PLAYER_O);

        if (isIllegal(isXWinner, isOWinner)) {
            System.out.println("illegal");
        } else if (isXWinner) {
            System.out.println("the first player won");
        } else if (isOWinner) {
            System.out.println("the second player won");
        } else if (isBoardFull()) {
            System.out.println("draw");
        } else {
            // If no one has won and the board isn't full, determine whose turn it is.
            // X goes first, so if counts are equal, it is X's turn.
            System.out.println(countX == countO ? "first" : "second");
        }
    }

    /**
     * Checks if the provided player has a winning line.
     */
    private boolean checkWin(char player) {
        // Check rows and columns
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (checkLine(board[i][0], board[i][1], board[i][2], player)) return true;
            if (checkLine(board[0][i], board[1][i], board[2][i], player)) return true;
        }
        // Check diagonals
        if (checkLine(board[0][0], board[1][1], board[2][2], player)) return true;
        if (checkLine(board[0][2], board[1][1], board[2][0], player)) return true;

        return false;
    }

    private boolean checkLine(char c1, char c2, char c3, char player) {
        return c1 == player && c2 == player && c3 == player;
    }

    /**
     * Validates the legality of the game state based on Tic-Tac-Toe rules.
     */
    private boolean isIllegal(boolean xWins, boolean oWins) {
        // 1. Both players cannot have winning configurations simultaneously.
        if (xWins && oWins) return true;

        // 2. X goes first. Valid move counts are:
        // countX == countO (it is X's turn)
        // countX == countO + 1 (it is O's turn)
        if (!(countX == countO || countX == countO + 1)) return true;

        // 3. If X won, the last move must have been made by X.
        if (xWins && countX != countO + 1) return true;

        // 4. If O won, the last move must have been made by O.
        if (oWins && countX != countO) return true;

        return false;
    }

    private boolean isBoardFull() {
        return (countX + countO) == (BOARD_SIZE * BOARD_SIZE);
    }
}

