        ILLEGAL("illegal"),
        FIRST_TURN("first"),
        SECOND_TURN("second");

        private final String message;

        GameResult(String message) {
            this.message = message;
        }

        @Override
        public String toString() {
            return this.message;
        }
    }

    /**
     * Represents the 3x3 Tic-Tac-Toe board.
     */
    private static class Board {
        private static final int SIZE = 3;
        private final Player[][] grid = new Player[SIZE][SIZE];
        private int xCount = 0;
        private int oCount = 0;
        private int emptyCount = 0;

        public Board(Scanner scanner) {
            for (int i = 0; i < SIZE; i++) {
                String row = scanner.next();
                for (int j = 0; j < SIZE; j++) {
                    parseCell(i, j, row.charAt(j));
                }
            }
        }

        private void parseCell(int r, int c, char symbol) {
            if (symbol == 'X') {
                grid[r][c] = Player.X;
                xCount++;
            } else if (symbol == 'O') {
                grid[r][c] = Player.O;
                oCount++;
            } else {
                grid[r][c] = Player.EMPTY;
                emptyCount++;
            }
        }

        public int getXCount() { return xCount; }
        public int getOCount() { return oCount; }
        public int getEmptyCount() { return emptyCount; }

        public boolean hasWon(Player player) {
            // Check rows and columns
            for (int i = 0; i < SIZE; i++) {
                if (checkLine(player, grid[i][0], grid[i][1], grid[i][2])) return true;
                if (checkLine(player, grid[0][i], grid[1][i], grid[2][i])) return true;
            }
            // Check diagonals
            if (checkLine(player, grid[0][0], grid[1][1], grid[2][2])) return true;
            if (checkLine(player, grid[0][2], grid[1][1], grid[2][0])) return true;

            return false;
        }

        private boolean checkLine(Player p, Player a, Player b, Player c) {
            return a == p && b == p && c == p;
        }

        public boolean isFull() {
            return emptyCount == 0;
        }
    }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            Board board = new Board(scanner);
            System.out.println(evaluateGame(board));
        } catch (Exception e) {
            // In a real application, use a logger
            System.out.println("illegal");
        }
    }

    /**
     * Evaluates the board state and returns the game result.
     */
    private static GameResult evaluateGame(Board board) {
        int xCount = board.getXCount();
        int oCount = board.getOCount();

        // 1. Basic rule: X starts, so X count must be equal to O or O + 1
        if (xCount < oCount || xCount > oCount + 1) {
            return GameResult.ILLEGAL;
        }

        boolean xWins = board.hasWon(Player.X);
        boolean oWins = board.hasWon(Player.O);

        // 2. Both players cannot have winning configurations
        if (xWins && oWins) {
            return GameResult.ILLEGAL;
        }

        // 3. If X wins, it must have been X's turn that just finished (xCount == oCount + 1)
        if (xWins && xCount != oCount + 1) {
            return GameResult.ILLEGAL;
        }

        // 4. If O wins, it must have been O's turn that just finished (xCount == oCount)
        if (oWins && xCount != oCount) {
            return GameResult.ILLEGAL;
        }

        // 5. Determine result based on winners
        if (xWins) return GameResult.FIRST_PLAYER_WON;
        if (oWins) return GameResult.SECOND_PLAYER_WON;

        // 6. No winner: check if it's a draw or ongoing
        if (board.isFull()) {
            return GameResult.DRAW;
        }

        // 7. Return whose turn it is
        return (xCount > oCount) ? GameResult.SECOND_TURN : GameResult.FIRST_TURN;
    }
}

