/**
 * Evaluates the game state based on Tic-Tac-Toe rules.
 */
class GameEvaluator {

    private enum GameStatus {
        ILLEGAL,
        X_WON,
        O_WON,
        DRAW,
        X_TURN, // Representing original "first"
        O_TURN  // Representing original "second"
    }

    private static final int[][] WIN_COMBINATIONS = {
        {0, 0, 0, 1, 0, 2}, {1, 0, 1, 1, 1, 2}, {2, 0, 2, 1, 2, 2}, // Rows
        {0, 0, 1, 0, 2, 0}, {0, 1, 1, 1, 2, 1}, {0, 2, 1, 2, 2, 2}, // Cols
        {0, 0, 1, 1, 2, 2}, {0, 2, 1, 1, 2, 0}                      // Diagonals
    };

    private final TicTacToeBoard board;

    public GameEvaluator(TicTacToeBoard board) {
        this.board = board;
    }

    public String getGameResultMessage() {
        GameStatus status = evaluateStatus();
        switch (status) {
            case ILLEGAL: return "illegal";
            case X_WON:   return "the first player won";
            case O_WON:   return "the second player won";
            case DRAW:    return "draw";
            case X_TURN:  return "first";
            case O_TURN:  return "second";
            default:      return "illegal";
        }
    }

    private GameStatus evaluateStatus() {
        int xWins = 0;
        int oWins = 0;

        // Check all possible winning lines
        for (int[] combo : WIN_COMBINATIONS) {
            char c1 = board.getCell(combo[0], combo[1]);
            char c2 = board.getCell(combo[2], combo[3]);
            char c3 = board.getCell(combo[4], combo[5]);

            if (c1 != ' ' && c1 == c2 && c1 == c3) {
                if (c1 == 'X') xWins++;
                else if (c1 == '0') oWins++;
            }
        }

        // Rule: Multiple winners is illegal
        if (xWins > 0 && oWins > 0) return GameStatus.ILLEGAL;

        // Determine winner and validate move counts
        if (xWins > 0) {
            return (board.getXCount() == board.getOCount() + 1) ? GameStatus.X_WON : GameStatus.ILLEGAL;
        }
        if (oWins > 0) {
            return (board.getOCount() == board.getXCount()) ? GameStatus.O_WON : GameStatus.ILLEGAL;
        }

        // Basic count validation (X must be equal to or one more than O)
        if (board.getXCount() > board.getOCount() + 1 || board.getOCount() > board.getXCount()) {
            return GameStatus.ILLEGAL;
        }

        // Check for Draw or Turn state
        if (board.getTotalMarks() == 9) {
            return GameStatus.DRAW;
        }

        // If no winner and game continues:
        // If xCount == oCount, it's X's turn (original code "first")
        // If xCount == oCount + 1, it's O's turn (original code "second")
        return (board.getXCount() == board.getOCount()) ? GameStatus.X_TURN : GameStatus.O_TURN;
    }
}

import java.util.*;

/**
 * A utility to evaluate the state of a Tic-Tac-Toe game.
 */
public class TicTacToeValidator {

    private static final int BOARD_SIZE = 3;
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0';
    private static final char EMPTY = '.';

    /**
     * Represents the possible outcomes of a Tic-Tac-Toe game state.
     */
    public enum GameResult {
        FIRST_PLAYER_WON("the first player won"),
        SECOND_PLAYER_WON("the second player won"),
        DRAW("draw"),
        ILLEGAL("illegal");

        private final String message;

        GameResult(String message) {
            this.message = message;
        }

        @Override
        public String toString() {
            return message;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] grid = new char[BOARD_SIZE][BOARD_SIZE];

        try {
            for (int i = 0; i < BOARD_SIZE; i++) {
                String rowInput = scanner.next();
                if (rowInput.length() != BOARD_SIZE) {
                    System.out.println(GameResult.ILLEGAL);
                    return;
                }
                for (int j = 0; j < BOARD_SIZE; j++) {
                    grid[i][j] = rowInput.charAt(j);
                }
            }

            System.out.println(evaluateGameState(grid));
        } catch (Exception e) {
            System.out.println(GameResult.ILLEGAL);
        } finally {
            scanner.close();
        }
    }

    /**
     * Evaluates the provided grid and returns the result of the game.
     * 
     * @param grid 2D array representing the board.
     * @return The GameResult (Win, Draw, or Illegal).
     */
    public static GameResult evaluateGameState(char[][] grid) {
        int countX = 0;
        int countO = 0;
        int emptyCount = 0;

        // 1. Count occurrences of each symbol
        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                if (grid[i][j] == PLAYER_X) {
                    countX++;
                } else if (grid[i][j] == PLAYER_O) {
                    countO++;
                } else if (grid[i][j] == EMPTY) {
                    emptyCount++;
                }
            }
        }

        // 2. Basic Rule: Player X must always have either equal or one more move than Player O
        if (countX < countO || countX > countO + 1) {
            return GameResult.ILLEGAL;
        }

        // 3. Identify all winning symbols on the board
        Set<Character> winners = findWinningSymbols(grid);

        // 4. Rule: It is illegal if both players have winning lines
        if (winners.size() > 1) {
            return GameResult.ILLEGAL;
        }

        // 5. Evaluate the winner based on counts and winning lines
        if (winners.contains(PLAYER_X)) {
            // If X won, X must have made the last move (countX = countO + 1)
            return (countX == countO + 1) ? GameResult.FIRST_PLAYER_WON : GameResult.ILLEGAL;
        } 

        if (winners.contains(PLAYER_O)) {
            // If O won, the counts must be equal (countX = countO)
            return (countX == countO) ? GameResult.SECOND_PLAYER_WON : GameResult.ILLEGAL;
        }

        // 6. No winner found: check if it's a draw (full board) or ongoing
        // For evaluation purposes, a non-winning valid state is treated as a draw.
        return GameResult.DRAW;
    }

    /**
     * Scans the grid for winning rows, columns, and diagonals.
     * 
     * @param grid 2D array.
     * @return A set of characters representing the symbols that have completed a line.
     */
    private static Set<Character> findWinningSymbols(char[][] grid) {
        Set<Character> winners = new HashSet<>();

        // Check rows and columns
        for (int i = 0; i < BOARD_SIZE; i++) {
            // Rows
            if (isWinningLine(grid[i][0], grid[i][1], grid[i][2])) {
                winners.add(grid[i][0]);
            }
            // Columns
            if (isWinningLine(grid[0][i], grid[1][i], grid[2][i])) {
                winners.add(grid[0][i]);
            }
        }

        // Check diagonals
        if (isWinningLine(grid[0][0], grid[1][1], grid[2][2])) {
            winners.add(grid[0][0]);
        }
        if (isWinningLine(grid[0][2], grid[1][1], grid[2][0])) {
            winners.add(grid[0][2]);
        }

        return winners;
    }

    /**
     * Helper to check if three characters form a winning line.
     */
    private static boolean isWinningLine(char c1, char c2, char c3) {
        return c1 != EMPTY && c1 == c2 && c2 == c3;
    }
}

import java.util.Scanner;

/**
 * Evaluates the state of a Tic-Tac-Toe game board.
 * Determines if the game is in a winning, drawing, ongoing, or illegal state.
 */
public class TicTacToeEvaluator {

    private static final int BOARD_SIZE = 3;
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = 'O';

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            char[][] board = readBoard(scanner);
            System.out.println(evaluateGameState(board));
        } catch (Exception e) {
            System.out.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Reads the 3x3 board from standard input.
     */
    private static char[][] readBoard(Scanner scanner) {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i++) {
            String row = scanner.next();
            for (int j = 0; j < BOARD_SIZE; j++) {
                // Support both '0' (zero) and 'O' (letter) as per original code logic
                char c = row.charAt(j);
                board[i][j] = (c == '0') ? PLAYER_O : c;
            }
        }
        return board;
    }

    /**
     * Processes the board state and returns the result string.
     */
    private static String evaluateGameState(char[][] board) {
        int countX = countOccurrences(board, PLAYER_X);
        int countO = countOccurrences(board, PLAYER_O);

        boolean xWins = hasWinner(board, PLAYER_X);
        boolean oWins = hasWinner(board, PLAYER_O);

        // 1. Check for Illegal States
        if (isIllegal(xWins, oWins, countX, countO)) {
            return "illegal";
        }

        // 2. Check for Winners
        if (xWins) {
            return "the first player won";
        }
        if (oWins) {
            return "the second player won";
        }

        // 3. Check for Draw
        if (countX + countO == BOARD_SIZE * BOARD_SIZE) {
            return "draw";
        }

        // 4. Check whose turn it is
        return (countX == countO) ? "first" : "second";
    }

    /**
     * Determines if the current board configuration violates Tic-Tac-Toe rules.
     */
    private static boolean isIllegal(boolean xWins, boolean oWins, int countX, int countO) {
        // Both players cannot have winning configurations simultaneously
        if (xWins && oWins) return true;

        // If X wins, X must have exactly one more move than O
        if (xWins && countX != countO + 1) return true;

        // If O wins, X and O must have an equal number of moves
        if (oWins && countX != countO) return true;

        // If no one has won, the move counts must be either equal (X's turn) 
        // or X has one more move (O's turn)
        if (!xWins && !oWins && (countX != countO && countX != countO + 1)) return true;

        return false;
    }

    /**
     * Checks if the specified player has a winning line.
     */
    private static boolean hasWinner(char[][] board, char player) {
        // Check rows and columns
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (checkLine(board[i][0], board[i][1], board[i][2], player)) return true;
            if (checkLine(board[0][i], board[1][i], board[2][i], player)) return true;
        }

        // Check diagonals
        if (checkLine(board[0][0], board[1][1], board[2][2], player)) return true;
        if (checkLine(board[0][2], board[1][1], board[2][0], player)) return true;

        return false;
    }

    private static boolean checkLine(char c1, char c2, char c3, char player) {
        return c1 == player && c2 == player && c3 == player;
    }

    private static int countOccurrences(char[][] board, char player) {
        int count = 0;
        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                if (board[i][j] == player) {
                    count++;
                }
            }
        }
        return count;
    }
}

import java.util.Scanner;

/**
 * A program to evaluate the state of a Tic-Tac-Toe game.
 * It determines if the current board state is legal and identifies the winner or current turn.
 */
public class TicTacToeEvaluator {

    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0'; // Using '0' as per original requirement
    private static final int GRID_SIZE = 3;

    public enum GameResult {
        ILLEGAL,
        FIRST_PLAYER_WON,
        SECOND_PLAYER_WON,
        DRAW,
        FIRST_PLAYER_TURN,
        SECOND_PLAYER_TURN
    }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            char[][] board = readBoard(scanner);
            TicTacToeBoard gameBoard = new TicTacToeBoard(board);
            GameResult result = evaluateGameState(gameBoard);
            printResult(result);
        } catch (Exception e) {
            System.out.println("illegal");
        }
    }

    private static char[][] readBoard(Scanner scanner) {
        char[][] board = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            String row = scanner.next();
            for (int j = 0; j < GRID_SIZE; j++) {
                board[i][j] = row.charAt(j);
            }
        }
        return board;
    }

    /**
     * Evaluates the game board to determine the winner or if the state is invalid.
     */
    private static GameResult evaluateGameState(TicTacToeBoard board) {
        int xCount = board.countMoves(PLAYER_X);
        int oCount = board.countMoves(PLAYER_O);
        int emptyCount = board.countEmpty();

        // 1. Validate turn order: X starts first, so xCount must be oCount or oCount + 1
        if (xCount > oCount + 1 || oCount > xCount) {
            return GameResult.ILLEGAL;
        }

        boolean xWins = board.hasWinner(PLAYER_X);
        boolean oWins = board.hasWinner(PLAYER_O);

        // 2. Check if both players have winning lines
        if (xWins && oWins) {
            return GameResult.ILLEGAL;
        }

        // 3. Determine winner or state
        if (xWins) {
            // If X wins, X must have made the last move (xCount == oCount + 1)
            return (xCount == oCount + 1) ? GameResult.FIRST_PLAYER_WON : GameResult.ILLEGAL;
        }

        if (oWins) {
            // If O wins, X and O must have the same number of moves (xCount == oCount)
            return (xCount == oCount) ? GameResult.SECOND_PLAYER_WON : GameResult.ILLEGAL;
        }

        // 4. No winner: Check for Draw or current turn
        if (emptyCount == 0) {
            return GameResult.DRAW;
        } else {
            return (xCount == oCount) ? GameResult.FIRST_PLAYER_TURN : GameResult.SECOND_PLAYER_TURN;
        }
    }

    private static void printResult(GameResult result) {
        switch (result) {
            case ILLEGAL -> System.out.println("illegal");
            case FIRST_PLAYER_WON -> System.out.println("the first player won");
            case SECOND_PLAYER_WON -> System.out.println("the second player won");
            case DRAW -> System.out.println("draw");
            case FIRST_PLAYER_TURN -> System.out.println("first");
            case SECOND_PLAYER_TURN -> System.out.println("second");
        }
    }

    /**
     * Represents the Tic-Tac-Toe board and provides logic for analyzing its state.
     */
    static class TicTacToeBoard {
        private final char[][] grid;

        public TicTacToeBoard(char[][] grid) {
            this.grid = grid;
        }

        public int countMoves(char player) {
            int count = 0;
            for (int i = 0; i < GRID_SIZE; i++) {
                for (int j = 0; j < GRID_SIZE; j++) {
                    if (grid[i][j] == player) count++;
                }
            }
            return count;
        }

        public int countEmpty() {
            int count = 0;
            for (int i = 0; i < GRID_SIZE; i++) {
                for (int j = 0; j < GRID_SIZE; j++) {
                    if (grid[i][j] != PLAYER_X && grid[i][j] != PLAYER_O) {
                        count++;
                    }
                }
            }
            return count;
        }

        public boolean hasWinner(char player) {
            return checkRows(player) || checkColumns(player) || checkDiagonals(player);
        }

        private boolean checkRows(char player) {
            for (int i = 0; i < GRID_SIZE; i++) {
                if (grid[i][0] == player && grid[i][1] == player && grid[i][2] == player) return true;
            }
            return false;
        }

        private boolean checkColumns(char player) {
            for (int j = 0; j < GRID_SIZE; j++) {
                if (grid[0][j] == player && grid[1][j] == player && grid[2][j] == player) return true;
            }
            return false;
        }

        private boolean checkDiagonals(char player) {
            boolean mainDiag = grid[0][0] == player && grid[1][1] == player && grid[2][2] == player;
            boolean antiDiag = grid[0][2] == player && grid[1][1] == player && grid[2][0] == player;
            return mainDiag || antiDiag;
        }
    }
}

