/**
 * Represents the players in the game.
 */
enum Player {
    X, O, EMPTY;

    public static Player fromChar(char c) {
        return switch (c) {
            case 'X' -> X;
            case '0' -> O;
            default -> EMPTY;
        };
    }
}

/**
 * Represents the possible outcomes of a Tic-Tac-Toe game state.
 */
enum GameResult {
    FIRST_PLAYER_WON("the first player won"),
    SECOND_PLAYER_WON("the second player won"),
    DRAW("draw"),
    FIRST_TURN("first"),
    SECOND_TURN("second"),
    ILLEGAL("illegal");

    private final String message;

    GameResult(String message) {
        this.message = message;
    }

    @Override
    public String toString() {
        return message;
    }
}

/**
 * Represents the 3x3 Tic-Tac-Toe board.
 */
class Board {
    private static final int SIZE = 3;
    private final Player[][] grid = new Player[SIZE][SIZE];

    public void setCell(int row, int col, Player player) {
        grid[row][col] = player;
    }

    public Player getCell(int row, int col) {
        return grid[row][col];
    }

    public int getSize() {
        return SIZE;
    }

    public int getCount(Player player) {
        int count = 0;
        for (int i = 0; i < SIZE; i++) {
            for (int j = 0; j < SIZE; j++) {
                if (grid[i][j] == player) count++;
            }
        }
        return count;
    }

    public boolean isFull() {
        return getCount(Player.X) + getCount(Player.O) == SIZE * SIZE;
    }

    public boolean hasWinningLine(Player player) {
        // Check rows and columns
        for (int i = 0; i < SIZE; i++) {
            if (checkRow(i, player) || checkCol(i, player)) return true;
        }
        // Check diagonals
        return checkMainDiagonal(player) || checkAntiDiagonal(player);
    }

    private boolean checkRow(int row, Player p) {
        return grid[row][0] == p && grid[row][1] == p && grid[row][2] == p;
    }

    private boolean checkCol(int col, Player p) {
        return grid[0][col] == p && grid[1][col] == p && grid[2][col] == p;
    }

    private boolean checkMainDiagonal(Player p) {
        return grid[0][0] == p && grid[1][1] == p && grid[2][2] == p;
    }

    private boolean checkAntiDiagonal(Player p) {
        return grid[0][2] == p && grid[1][1] == p && grid[2][0] == p;
    }
}

/**
 * Contains the logic to evaluate the state of a Tic-Tac-Toe board.
 */
class GameEvaluator {

    public GameResult evaluate(Board board) {
        int xCount = board.getCount(Player.X);
        int oCount = board.getCount(Player.O);
        boolean xWins = board.hasWinningLine(Player.X);
        boolean oWins = board.hasWinningLine(Player.O);

        // Case 1: First player (X) has one more mark than second player (O)
        if (xCount == oCount + 1) {
            if (xWins && !oWins) {
                return GameResult.FIRST_PLAYER_WON;
            } else if (!xWins && !oWins) {
                return board.isFull() ? GameResult.DRAW : GameResult.SECOND_TURN;
            } else {
                return GameResult.ILLEGAL;
            }
        }

        // Case 2: Counts are equal
        if (xCount == oCount) {
            if (!xWins && oWins) {
                return GameResult.SECOND_PLAYER_WON;
            } else if (!xWins && !oWins) {
                return GameResult.FIRST_TURN;
            } else {
                // This covers cases where both won or X won but counts are equal
                return GameResult.ILLEGAL;
            }
        }

        // Any other count distribution is illegal
        return GameResult.ILLEGAL;
    }
}

/**
 * Main application class.
 */
public class TicTacToeApp {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        Board board = new Board();

        try {
