                }
                for (int j = 0; j < 3; j++) {
                    board.setCell(i, j, Player.fromChar(line.charAt(j)));
                }
            }

            GameEvaluator evaluator = new GameEvaluator();
            GameResult result = evaluator.evaluate(board);
            System.out.print(result);

        } catch (Exception e) {
