        } finally {
            scanner.close();
        }
    }
}

import java.util.Scanner;

/**
 * A refactored Tic-Tac-Toe board analyzer.
 * This program evaluates a 3x3 board and determines if the state is 
 * illegal, a draw, a win, or whose turn it is.
 */
public class TicTacToeAnalyzer {

    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0'; // Note: Using '0' as per original requirement
    private static final int BOARD_SIZE = 3;

    /**
     * Represents the possible outcomes of a Tic-Tac-Toe game state.
     */
    enum GameState {
        ILLEGAL("illegal"),
        DRAW("draw"),
        FIRST_PLAYER_WON("the first player won"),
        SECOND_PLAYER_WON("the second player won"),
        FIRST_TURN("first"),
        SECOND_TURN("second");

        private final String message;

        GameState(String message) {
            this.message = message;
        }

        @Override
        public String toString() {
            return this.message;
        }
    }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            TicTacToe game = new TicTacToe(scanner);
            System.out.println(game.analyze());
        } catch (Exception e) {
            System.out.println("illegal");
        }
    }

    /**
     * Encapsulates the Tic-Tac-Toe board and its rules.
     */
    static class TicTacToe {
        private final char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        private int xCount = 0;
        private int oCount = 0;

        public TicTacToe(Scanner scanner) {
            for (int i = 0; i < BOARD_SIZE; i++) {
                String row = scanner.next();
                for (int j = 0; j < BOARD_SIZE; j++) {
                    char cell = row.charAt(j);
                    board[i][j] = cell;
                    if (cell == PLAYER_X) {
                        xCount++;
                    } else if (cell == PLAYER_O) {
                        oCount++;
                    }
                }
            }
        }

        /**
         * Analyzes the current board state and returns the GameState.
         */
        public GameState analyze() {
            if (isConfigurationIllegal()) {
                return GameState.ILLEGAL;
            }

            boolean xWins = checkWinner(PLAYER_X);
            boolean oWins = checkWinner(PLAYER_O);

            // Both players cannot win simultaneously
            if (xWins && oWins) {
                return GameState.ILLEGAL;
            }

            if (xWins) {
                // If X wins, it must have been X's turn that completed the win
                return (xCount - oCount == 1) ? GameState.FIRST_PLAYER_WON : GameState.ILLEGAL;
            }

            if (oWins) {
                // If O wins, X and O must have an equal number of moves
                return (xCount == oCount) ? GameState.SECOND_PLAYER_WON : GameState.ILLEGAL;
            }

            // No winner detected
            if (xCount + oCount == 9) {
                return GameState.DRAW;
            } else if (xCount == oCount) {
                return GameState.FIRST_TURN;
            } else {
                return GameState.SECOND_TURN;
            }
        }

        /**
         * Validates basic piece count rules.
         */
        private boolean isConfigurationIllegal() {
            if (oCount > xCount) return true;
            if (xCount > 5) return true;
            if (oCount > 4) return true;
            if (xCount - oCount > 1) return true;
            return false;
        }

        /**
         * Checks if a specific player has three in a row.
         */
        private boolean checkWinner(char player) {
            // Check Rows and Columns
            for (int i = 0; i < BOARD_SIZE; i++) {
                if (checkLine(i, 0, i, 1, i, 2, player)) return true; // Row
                if (checkLine(0, i, 1, i, 2, i, player)) return true; // Col
            }
            // Check Diagonals
            if (checkLine(0, 0, 1, 1, 2, 2, player)) return true;
            if (checkLine(0, 2, 1, 1, 2, 0, player)) return true;

            return false;
        }

        /**
         * Helper to check if three specific coordinates contain the same player.
         */
        private boolean checkLine(int r1, int c1, int r2, int c2, int r3, int c3, char p) {
            return board[r1][c1] == p && board[r2][c2] == p && board[r3][c3] == p;
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A utility class for fast input reading.
 */
class FastReader {
    private BufferedReader reader;
    private StringTokenizer tokenizer;

    public FastReader(InputStream input) {
        reader = new BufferedReader(new InputStreamReader(input));
        tokenizer = new StringTokenizer("");
    }

    public String next() {
        while (!tokenizer.hasMoreTokens()) {
            try {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                return null;
            }
        }
        return tokenizer.nextToken();
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }

    public char[][] readBoard(int size) {
        char[][] board = new char[size][size];
        for (int i = 0; i < size; i++) {
            board[i] = next().toCharArray();
        }
        return board;
    }
}

/**
 * Logic handler for the Tic-Tac-Toe game validation.
 */
class TicTacToeSolver {
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0'; // Note: uses digit '0' as per original requirement
    private static final char EMPTY = '.';
    private static final int BOARD_SIZE = 3;

    private boolean isReachable = false;
    private boolean isDraw = false;
    private char nextPlayerToMove = '$';

    /**
     * Validates if the given board state is a reachable state in a legal game.
     * 
     * @param targetBoard The board state provided by the user.
     * @return A result object containing the outcome of the validation.
     */
    public GameResult solve(char[][] targetBoard) {
        isReachable = false;
        isDraw = false;
        nextPlayerToMove = '$';

        char[][] currentBoard = createEmptyBoard();
        backtrack(targetBoard, currentBoard, PLAYER_X);

        if (!isReachable) {
            return GameResult.ILLEGAL;
        }

        if (checkWinner(targetBoard, PLAYER_X)) {
            return GameResult.FIRST_PLAYER_WON;
        }
        if (checkWinner(targetBoard, PLAYER_O)) {
            return GameResult.SECOND_PLAYER_WON;
        }
        if (isDraw) {
            return GameResult.DRAW;
        }

        return (nextPlayerToMove == PLAYER_X) ? GameResult.FIRST_TURN : GameResult.SECOND_TURN;
    }

    private void backtrack(char[][] target, char[][] current, char nextPlayer) {
        // If current state matches the target, record it
        if (Arrays.deepEquals(target, current)) {
            isReachable = true;
            nextPlayerToMove = nextPlayer;
            isDraw = isBoardFull(current);
        }

        // If someone already won, the game ends; stop exploring this branch
        if (checkWinner(current, PLAYER_X) || checkWinner(current, PLAYER_O)) {
            return;
        }

        // Try all possible moves
        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                if (current[i][j] == EMPTY) {
                    current[i][j] = nextPlayer;
                    backtrack(target, current, (nextPlayer == PLAYER_X) ? PLAYER_O : PLAYER_X);
                    current[i][j] = EMPTY; // Backtrack
                }
            }
        }
    }

    private boolean checkWinner(char[][] board, char player) {
        for (int i = 0; i < BOARD_SIZE; i++) {
            // Check rows and columns
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) return true;
            if (board[0][i] == player && board[1][i] == player && board[2][i] == player) return true;
        }
        // Check diagonals
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) return true;
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) return true;
        return false;
    }

    private boolean isBoardFull(char[][] board) {
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == EMPTY) return false;
            }
        }
        return true;
    }

    private char[][] createEmptyBoard() {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i++) {
            Arrays.fill(board[i], EMPTY);
        }
        return board;
    }

    public enum GameResult {
        ILLEGAL("illegal"),
        FIRST_PLAYER_WON("the first player won"),
        SECOND_PLAYER_WON("the second player won"),
        DRAW("draw"),
        FIRST_TURN("first"),
        SECOND_TURN("second");

        private final String message;
        GameResult(String message) { this.message = message; }
        @Override
        public String toString() { return message; }
    }
}

