import java.io.*;
import java.util.*;

/**
 * A refactored Tic-Tac-Toe solver that determines if a given board state 
 * is legal and predicts the outcome (win, loss, draw, or whose turn it is).
 */
public class Main {

    // Game Constants
    private static final int PLAYER_1 = 1;
    private static final int PLAYER_2 = 2;
    private static final int EMPTY = 0;
    private static final int DRAW = 3;

    public static void main(String[] args) {
        new Main().run();
    }

    /**
     * Orchestrates the reading of input and the printing of the result.
     */
    public void run() {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)))) {

            TicTacToeEngine engine = new TicTacToeEngine();
            // Pre-calculate all possible reachable game states using minimax
            engine.precalculateAllStates();

            int[] board = new int[9];
            for (int i = 0; i < 3; i++) {
                String line = br.readLine();
                if (line == null) break;
                for (int j = 0; j < 3; j++) {
                    char c = line.charAt(j);
                    if (c == 'X') {
                        board[i * 3 + j] = PLAYER_1;
                    } else if (c == '0') {
                        board[i * 3 + j] = PLAYER_2;
                    } else {
                        board[i * 3 + j] = EMPTY;
                    }
                }
            }

            processResult(board, engine, out);
            out.flush();

        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Determines the output based on the state of the board.
     */
    private void processResult(int[] board, TicTacToeEngine engine, PrintWriter out) {
        // 1. Check if the state is reachable/legal
        int memoizedOutcome = engine.getMemoizedOutcome(board);
        if (memoizedOutcome == 0) {
            out.println("illegal");
            return;
        }

        // 2. Check if someone has already won or if it's a draw
        int winner = engine.checkWinner(board);
        if (winner == PLAYER_1) {
            out.println("the first player won");
        } else if (winner == PLAYER_2) {
            out.println("the second player won");
        } else if (winner == DRAW) {
            out.println("draw");
        } else {
            // 3. If no winner, determine whose turn it is based on piece count
            out.println(determineNextTurn(board));
        }
    }

    private String determineNextTurn(int[] board) {
        int countP1 = 0;
        int countP2 = 0;
        for (int cell : board) {
            if (cell == PLAYER_1) countP1++;
            else if (cell == PLAYER_2) countP2++;
        }
        // If Player 1 has moved more times than Player 2, it is Player 2's turn.
        return (countP1 > countP2) ? "second" : "first";
    }
}

/**
 * Contains the core logic for the Tic-Tac-Toe engine, including 
 * minimax, winner detection, and state memoization.
 */
class TicTacToeEngine {
    // 3^9 possible states = 19683. 20000 is a safe array size for memoization.
    private final int[] memo = new int[20000];

    private static final int PLAYER_1 = 1;
    private static final int PLAYER_2 = 2;
    private static final int EMPTY = 0;
    private static final int DRAW = 3;

    /**
     * Fills the memoization table by simulating a game from an empty board.
     */
    public void precalculateAllStates() {
        int[] board = new int[9];
        solveMinimax(board, PLAYER_1);
    }

    /**
     * Minimax algorithm to determine the perfect outcome for any given board state.
     * 
     * @param board The current board state.
     * @param turn The player whose turn it is.
     * @return The outcome (1, 2, or 3).
     */
    private int solveMinimax(int[] board, int turn) {
        int hash = calculateStateHash(board);
        if (memo[hash] != 0) {
            return memo[hash];
        }

        int winner = checkWinner(board);
        if (winner != 0) {
            memo[hash] = winner;
            return winner;
        }

        // The current player tries to maximize their outcome: Win > Draw > Loss.
        // We initialize bestResult to the worst possible outcome for the current player.
        int bestResult = (turn == PLAYER_1) ? PLAYER_2 : PLAYER_1;

        for (int i = 0; i < 9; i++) {
            if (board[i] == EMPTY) {
                board[i] = turn;
                int result = solveMinimax(board, (turn == PLAYER_1) ? PLAYER_2 : PLAYER_1);
                board[i] = EMPTY;

                if (result == turn) {
                    // Found a move that results in a win
                    bestResult = turn;
                    break;
                } else if (result == DRAW && bestResult != turn) {
                    // Found a move that results in a draw (better than a loss)
                    bestResult = DRAW;
                }
            }
        }

        memo[hash] = bestResult;
        return bestResult;
    }

    /**
     * Checks if there is a winner or a draw on the current board.
     * 
     * @return 1 if Player 1 won, 2 if Player 2 won, 3 if draw, 0 if ongoing.
     */
    public int checkWinner(int[] board) {
        // Check Rows
        for (int i = 0; i < 9; i += 3) {
            if (board[i] != EMPTY && board[i] == board[i + 1] && board[i] == board[i + 2]) {
                return board[i];
            }
        }
        // Check Columns
        for (int i = 0; i < 3; i++) {
            if (board[i] != EMPTY && board[i] == board[i + 3] && board[i] == board[i + 6]) {
                return board[i];
            }
        }
        // Check Diagonals
        if (board[0] != EMPTY && board[0] == board[4] && board[0] == board[8]) return board[0];
        if (board[2] != EMPTY && board[2] == board[4] && board[2] == board[6]) return board[2];

        // Check if any cells are empty to distinguish between DRAW and ONGOING
        for (int cell : board) {
            if (cell == EMPTY) return 0;
        }
        return DRAW;
    }

    /**
     * Converts the board state into a unique base-3 integer for memoization.
     */
    private int calculateStateHash(int[] board) {
        int hash = 0;
        int multiplier = 1;
        for (int i = 0; i < 9; i++) {
            hash += board[i] * multiplier;
            multiplier *= 3;
        }
        return hash;
    }

    /**
     * Retrieves the pre-calculated result for a specific board state.
     */
    public int getMemoizedOutcome(int[] board) {
        return memo[calculateStateHash(board)];
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;

/**
 * Represents the players in the game.
 */
enum Player {
    NONE,
    FIRST,
    SECOND
}

/**
 * Represents the possible outcomes of a Tic-Tac-Toe game state.
 */
enum GameResult {
    ILLEGAL("illegal"),
    DRAW("draw"),
    FIRST_PLAYER_WON("the first player won"),
    SECOND_PLAYER_WON("the second player won"),
    FIRST_TURN_NEXT("first"),
    SECOND_TURN_NEXT("second");

    private final String message;

    GameResult(String message) {
        this.message = message;
    }

    public String getMessage() {
        return message;
    }
}

/**
 * Logic engine for the Tic-Tac-Toe game.
 */
class TicTacToeBoard {
    private static final int GRID_SIZE = 3;
    private final Player[][] board = new Player[GRID_SIZE][GRID_SIZE];
    private int countFirst = 0;
    private int countSecond = 0;
    private boolean isBoardFull = true;

    public TicTacToeBoard() {
        for (int i = 0; i < GRID_SIZE; i++) {
            for (int j = 0; j < GRID_SIZE; j++) {
                board[i][j] = Player.NONE;
            }
        }
    }

    /**
     * Sets a cell value based on input character.
     * @param row 0-2
     * @param col 0-2
     * @param symbol 'X', '0', or other (empty)
     */
    public void setCell(int row, int col, char symbol) {
        if (symbol == 'X') {
            board[row][col] = Player.FIRST;
            countFirst++;
        } else if (symbol == '0') {
            board[row][col] = Player.SECOND;
            countSecond++;
        } else {
            board[row][col] = Player.NONE;
            isBoardFull = false;
        }
    }

    /**
     * Evaluates the current board state to determine the game result.
     */
    public GameResult evaluate() {
        Player winner = getWinner();

        // 1. Check if there are multiple winners (impossible in a valid game)
        if (winner == Player.NONE && hasMultipleDifferentWinners()) {
            return GameResult.ILLEGAL;
        }

        // 2. Handle full board state
        if (isBoardFull) {
            if (countFirst != countSecond + 1) {
                return GameResult.ILLEGAL;
            }
            if (winner == Player.FIRST) return GameResult.FIRST_PLAYER_WON;
            if (winner == Player.SECOND) return GameResult.SECOND_PLAYER_WON;
            return GameResult.DRAW;
        }

        // 3. Handle incomplete board state
        Player nextToMove = getNextPlayerToMove();
        if (nextToMove == null) {
            return GameResult.ILLEGAL;
        }

        if (winner != Player.NONE) {
            // If someone has won, it must have been the player who just moved.
            // Therefore, the winner cannot be the player whose turn it is now.
            if (winner == nextToMove) {
                return GameResult.ILLEGAL;
            }
            return (winner == Player.FIRST) ? GameResult.FIRST_PLAYER_WON : GameResult.SECOND_PLAYER_WON;
        }

        return (nextToMove == Player.FIRST) ? GameResult.FIRST_TURN_NEXT : GameResult.SECOND_TURN_NEXT;
    }

    private Player getNextPlayerToMove() {
        if (countFirst == countSecond) {
            return Player.FIRST;
        } else if (countFirst == countSecond + 1) {
            return Player.SECOND;
        }
        return null; // Illegal move count
    }

    private Player getWinner() {
        Player winner = Player.NONE;

        // Check Rows and Columns
        for (int i = 0; i < GRID_SIZE; i++) {
            if (isLineWinning(board[i][0], board[i][1], board[i][2])) {
                winner = updateWinner(winner, board[i][0]);
            }
            if (isLineWinning(board[0][i], board[1][i], board[2][i])) {
                winner = updateWinner(winner, board[0][i]);
            }
        }

        // Check Diagonals
        if (isLineWinning(board[0][0], board[1][1], board[2][2])) {
            winner = updateWinner(winner, board[0][0]);
        }
        if (isLineWinning(board[0][2], board[1][1], board[2][0])) {
            winner = updateWinner(winner, board[0][2]);
        }

        return winner;
    }

    private Player updateWinner(Player currentWinner, Player lineWinner) {
        if (lineWinner == Player.NONE) return currentWinner;
        // If we found a line for a different player, we return a special value to signal multiple winners
        if (currentWinner != Player.NONE && currentWinner != lineWinner) {
            return Player.NONE; // We use NONE as a temporary marker for "conflicting winners"
        }
        return lineWinner;
    }

    private boolean hasMultipleDifferentWinners() {
        // This helper specifically looks for the case where lines belong to different players
        // The updateWinner logic returns NONE if conflicts occur, but we need to be sure.
        // Let's implement a cleaner approach for finding winners.
        List<Player> winnersFound = new ArrayList<>();

        // Check all 8 possible lines
        checkLineForList(winnersFound, board[0][0], board[0][1], board[0][2]);
        checkLineForList(winnersFound, board[1][0], board[1][1], board[1][2]);
        checkLineForList(winnersFound, board[2][0], board[2][1], board[2][2]);
        checkLineForList(winnersFound, board[0][0], board[1][0], board[2][0]);
        checkLineForList(winnersFound, board[0][1], board[1][1], board[2][1]);
        checkLineForList(winnersFound, board[0][2], board[1][2], board[2][2]);
        checkLineForList(winnersFound, board[0][0], board[1][1], board[2][2]);
        checkLineForList(winnersFound, board[0][2], board[1][1], board[2][0]);

        if (winnersFound.isEmpty()) return false;
        Player first = winnersFound.get(0);
        for (Player p : winnersFound) {
            if (p != first) return true;
        }
        return false;
    }

    private void checkLineForList(List<Player> list, Player p1, Player p2, Player p3) {
        if (p1 != Player.NONE && p1 == p2 && p2 == p3) {
            list.add(p1);
        }
    }

    private boolean isLineWinning(Player p1, Player p2, Player p3) {
