import java.io.*;
import java.util.Scanner;

/**
 * Represents the possible states of a Tic-Tac-Toe game.
 */
enum GameState {
    ILLEGAL,
    FIRST_PLAYER_WON,
    SECOND_PLAYER_WON,
    DRAW,
    FIRST_PLAYER_TURN,
    SECOND_PLAYER_TURN
}

/**
 * Represents the Tic-Tac-Toe board and its basic properties.
 */
class Board {
    private static final int SIZE = 3;
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0'; // Using '0' as per original requirements
    private static final char EMPTY = '.';

    private final char[][] grid;
    private int xCount = 0;
    private int oCount = 0;

    public Board(char[][] grid) {
        this.grid = grid;
        calculateCounts();
    }

    private void calculateCounts() {
        for (int i = 0; i < SIZE; i++) {
            for (int j = 0; j < SIZE; j++) {
                if (grid[i][j] == PLAYER_X) xCount++;
                else if (grid[i][j] == PLAYER_O) oCount++;
            }
        }
    }

    public int getXCount() { return xCount; }
    public int getOCount() { return oCount; }
    public int getSize() { return SIZE; }
    public char getCell(int row, int col) { return grid[row][col]; }

    /**
     * Checks if the specified player has a winning line.
     */
    public boolean hasWinner(char player) {
        // Check rows and columns
        for (int i = 0; i < SIZE; i++) {
            if (checkLine(i, 0, 0, 1, player)) return true; // Row
            if (checkLine(0, i, 1, 0, player)) return true; // Column
        }
        // Check diagonals
        if (checkLine(0, 0, 1, 1, player)) return true;
        if (checkLine(0, SIZE - 1, 1, -1, player)) return true;

        return false;
    }

    /**
     * Helper to check a line of cells based on a starting point and direction.
     */
    private boolean checkLine(int startR, int startC, int deltaR, int deltaC, char player) {
        for (int i = 0; i < SIZE; i++) {
            int r = startR + (i * deltaR);
            int c = startC + (i * deltaC);
            if (grid[r][c] != player) return false;
        }
        return true;
    }

    public boolean isFull() {
        return (xCount + oCount) == SIZE * SIZE;
    }
}

/**
 * Encapsulates the business rules of Tic-Tac-Toe.
 */
class GameEvaluator {
    private final Board board;

    public GameEvaluator(Board board) {
        this.board = board;
    }

    public GameState evaluate() {
        boolean xWins = board.hasWinner('X');
        boolean oWins = board.hasWinner('0');

        int xCount = board.getXCount();
        int oCount = board.getOCount();

        // 1. Rule: Only one player can win
        if (xWins && oWins) return GameState.ILLEGAL;

        // 2. Rule: Turn counts must be valid (X is first player)
        // X must have either the same number of pieces as O, or exactly one more.
        if (oCount > xCount || (xCount - oCount) > 1) return GameState.ILLEGAL;

        // 3. Rule: If X won, X must have exactly one more piece than O
        if (xWins && xCount != oCount + 1) return GameState.ILLEGAL;

        // 4. Rule: If O won, X and O must have an equal number of pieces
        if (oWins && xCount != oCount) return GameState.ILLEGAL;

        // Determine outcome
        if (xWins) return GameState.FIRST_PLAYER_WON;
        if (oWins) return GameState.SECOND_PLAYER_WON;
        if (board.isFull()) return GameState.DRAW;

        // Determine whose turn it is
        return (xCount == oCount) ? GameState.FIRST_PLAYER_TURN : GameState.SECOND_PLAYER_TURN;
    }
}

