/**
 * Represents the players in the game.
 */
enum Player {
    X, O, EMPTY;

    public static Player fromChar(char c) {
        if (c == 'X') return X;
        if (c == '0') return O; // Keeping '0' as per original specification
        return EMPTY;
    }
}

/**
 * Represents the possible outcomes of a Tic-Tac-Toe game.
 */
enum GameStatus {
    X_WON("the first player won"),
    O_WON("the second player won"),
    DRAW("draw"),
    X_TURN("first"),
    O_TURN("second"),
    ILLEGAL("illegal");

    private final String message;

    GameStatus(String message) {
        this.message = message;
    }

    @Override
    public String toString() {
        return this.message;
    }
}

/**
 * Manages the state of the 3x3 Tic-Tac-Toe board.
 */
class TicTacToeBoard {
    private static final int SIZE = 3;
    private final Player[][] grid = new Player[SIZE][SIZE];

    public void setCell(int row, int col, Player player) {
        grid[row][col] = player;
    }

    public Player getCell(int row, int col) {
        return grid[row][col];
    }

    public int countPlayer(Player player) {
        int count = 0;
        for (int i = 0; i < SIZE; i++) {
            for (int j = 0; j < SIZE; j++) {
                if (grid[i][j] == player) count++;
            }
        }
        return count;
    }

    public int getTotalMoves() {
        return countPlayer(Player.X) + countPlayer(Player.O);
    }

    public boolean isFull() {
        return getTotalMoves() == SIZE * SIZE;
    }

    public boolean checkWin(Player player) {
        // Check rows and columns
        for (int i = 0; i < SIZE; i++) {
            if (checkLine(player, i, 0, 0, 1)) return true; // Row
            if (checkLine(player, 0, i, 1, 0)) return true; // Column
        }
        // Check diagonals
        if (checkLine(player, 0, 0, 1, 1)) return true;
        if (checkLine(player, 0, 2, 1, -1)) return true;

        return false;
    }

    private boolean checkLine(Player player, int startRow, int startCol, int rowStep, int colStep) {
        for (int i = 0; i < SIZE; i++) {
            if (getCell(startRow + (i * rowStep), startCol + (i * colStep)) != player) {
                return false;
            }
        }
        return true;
    }
}

/**
 * Contains the business logic to evaluate the game state.
 */
class GameEvaluator {
    public static GameStatus evaluate(TicTacToeBoard board) {
        int xCount = board.countPlayer(Player.X);
        int oCount = board.countPlayer(Player.O);
        int turnDifference = xCount - oCount;

        boolean xWins = board.checkWin(Player.X);
        boolean oWins = board.checkWin(Player.O);

        // 1. Validate turn order: X must have 0 or 1 more moves than O
        if (turnDifference < 0 || turnDifference > 1) {
            return GameStatus.ILLEGAL;
        }

        // 2. Validate win conditions against turn counts
        // - Both cannot win
        // - If X wins, X must have made the last move (diff == 1)
        // - If O wins, O must have made the last move (diff == 0)
        if ((xWins && oWins) || (xWins && turnDifference == 0) || (oWins && turnDifference == 1)) {
            return GameStatus.ILLEGAL;
        }

        if (xWins) return GameStatus.X_WON;
        if (oWins) return GameStatus.O_WON;
        if (board.isFull()) return GameStatus.DRAW;

        // 3. If game is ongoing, determine whose turn it is
        return (turnDifference == 0) ? GameStatus.X_TURN : GameStatus.O_TURN;
    }
}

