/**
 * A utility class to validate the state of a Tic-Tac-Toe game.
 */
public class Solution {

    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0'; // Using '0' as per the original code
    private static final char EMPTY = '.';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] board = new char[3][3];

        try {
            for (int i = 0; i < 3; i++) {
                String line = scanner.next();
                board[i] = line.toCharArray();
            }

            TicTacToeValidator validator = new TicTacToeValidator(board);
            System.out.println(validator.evaluateGameState());
        } catch (Exception e) {
            System.out.println("illegal");
        } finally {
            scanner.close();
        }
    }

    /**
     * Represents the logic for validating a Tic-Tac-Toe board state.
     */
    static class TicTacToeValidator {
        private final char[][] board;
        private final int xCount;
        private final int oCount;

        public TicTacToeValidator(char[][] board) {
            this.board = board;
            int x = 0;
            int o = 0;
            for (int i = 0; i < 3; i++) {
                for (int j = 0; j < 3; j++) {
                    if (board[i][j] == PLAYER_X) x++;
                    else if (board[i][j] == PLAYER_O) o++;
                }
            }
            this.xCount = x;
            this.oCount = o;
        }

        /**
         * Evaluates the board and returns the status string as required by the specification.
         */
        public String evaluateGameState() {
            boolean xWins = checkWinner(PLAYER_X);
            boolean oWins = checkWinner(PLAYER_O);

            // Both players cannot have winning lines in a valid game state
            if (xWins && oWins) {
                return "illegal";
            }

            int turnDifference = xCount - oCount;

            if (turnDifference == 1) {
                return evaluateXTurn(xWins, oWins);
            } else if (turnDifference == 0) {
                return evaluateOTurn(xWins, oWins);
            } else {
                return "illegal";
            }
        }

        private String evaluateXTurn(boolean xWins, boolean oWins) {
            if (xWins) {
                return "the first player won";
            }
            if (oWins) {
                return "illegal";
            }
            // If no one won, check if the game is finished (draw) or ongoing
            return (xCount + oCount == 9) ? "draw" : "second";
        }

        private String evaluateOTurn(boolean xWins, boolean oWins) {
            if (oWins) {
                return "the second player won";
            }
            if (xWins) {
                return "illegal";
            }
            // If no one won, it is X's turn next
            return "first";
        }

        /**
         * Checks if a specific player has won the game.
         */
        private boolean checkWinner(char player) {
            // Check rows and columns
            for (int i = 0; i < 3; i++) {
                if ((board[i][0] == player && board[i][1] == player && board[i][2] == player) ||
                    (board[0][i] == player && board[1][i] == player && board[2][i] == player)) {
                    return true;
                }
            }
            // Check diagonals
            if ((board[0][0] == player && board[1][1] == player && board[2][2] == player) ||
                (board[0][2] == player && board[1][1] == player && board[2][0] == player)) {
                return true;
            }
            return false;
        }
    }
}

import java.util.Scanner;

/**
 * A refactored TicTacToe validator that checks the legality of a game state
 * and determines the current game status.
 */
public class TicTacToe {

    private static final int BOARD_SIZE = 3;

    /**
     * Represents the players in the game.
     */
    enum Player {
        X, O, NONE
    }

    /**
     * Represents the possible outcomes/states of the game.
     */
    enum GameStatus {
        ILLEGAL("illegal"),
        FIRST_PLAYER_WON("the first player won"),
        SECOND_PLAYER_WON("the second player won"),
        DRAW("draw"),
        FIRST_PLAYER_TURN("first"),
        SECOND_PLAYER_TURN("second");

        private final String outputMessage;

        GameStatus(String outputMessage) {
            this.outputMessage = outputMessage;
        }

        public String getOutputMessage() {
            return outputMessage;
        }
    }

    /**
     * Manages the state of the 3x3 TicTacToe board.
     */
    static class Board {
        private final Player[][] grid = new Player[BOARD_SIZE][BOARD_SIZE];

        public void setCell(int row, int col, Player player) {
            grid[row][col] = player;
        }

        public int countPlayer(Player player) {
            int count = 0;
            for (int r = 0; r < BOARD_SIZE; r++) {
                for (int c = 0; c < BOARD_SIZE; c++) {
                    if (grid[r][c] == player) {
                        count++;
                    }
                }
            }
            return count;
        }

        /**
         * Checks if the specified player has a winning line.
         */
        public boolean hasWon(Player player) {
            // Check rows and columns
            for (int i = 0; i < BOARD_SIZE; i++) {
                if (checkLine(grid[i][0], grid[i][1], grid[i][2], player)) return true;
                if (checkLine(grid[0][i], grid[1][i], grid[2][i], player)) return true;
            }
            // Check diagonals
            return checkLine(grid[0][0], grid[1][1], grid[2][2], player) ||
                   checkLine(grid[0][2], grid[1][1], grid[2][0], player);
        }

        private boolean checkLine(Player p1, Player p2, Player p3, Player target) {
            return p1 == target && p2 == target && p3 == target;
        }
    }

    /**
     * Contains the business logic to evaluate the legality and status of the game.
     */
    static class TicTacToeEngine {

        /**
         * Evaluates the board state according to standard TicTacToe rules.
         * 
         * @param board The current board state.
         * @return The resulting GameStatus.
         */
        public GameStatus evaluate(Board board) {
            int xCount = board.countPlayer(Player.X);
            int oCount = board.countPlayer(Player.O);
            boolean xWins = board.hasWon(Player.X);
            boolean oWins = board.hasWon(Player.O);

            // 1. Validate move count logic
            // Player X always starts, so X count must be equal to O or O + 1
            if (xCount - oCount > 1 || xCount < oCount) {
                return GameStatus.ILLEGAL;
            }

            // 2. Validate win conditions
            // Both players cannot have winning lines simultaneously
            if (xWins && oWins) {
                return GameStatus.ILLEGAL;
            }

            // If X wins, it must be that X just made the move that ended the game (xCount == oCount + 1)
            if (xWins && xCount != oCount + 1) {
                return GameStatus.ILLEGAL;
            }

            // If O wins, it must be that O just made the move that ended the game (xCount == oCount)
            if (oWins && xCount != oCount) {
                return GameStatus.ILLEGAL;
            }

            // 3. Determine result
            if (xWins) return GameStatus.FIRST_PLAYER_WON;
            if (oWins) return GameStatus.SECOND_PLAYER_WON;

            if (xCount + oCount == BOARD_SIZE * BOARD_SIZE) {
                return GameStatus.DRAW;
            }

            // If no one has won and board is not full, determine whose turn it is
            return (xCount == oCount) ? GameStatus.FIRST_PLAYER_TURN : GameStatus.SECOND_PLAYER_TURN;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        Board board = new Board();

        try {
            for (int i = 0; i < BOARD_SIZE; i++) {
                if (!scanner.hasNext()) break;
                String rowInput = scanner.next();
                for (int j = 0; j < BOARD_SIZE; j++) {
                    char c = rowInput.charAt(j);
                    if (c == 'X') {
                        board.setCell(i, j, Player.X);
                    } else if (c == '0') { // Note: '0' is the zero character as per original requirements
                        board.setCell(i, j, Player.O);
                    } else {
                        board.setCell(i, j, Player.NONE);
                    }
                }
            }

            TicTacToeEngine engine = new TicTacToeEngine();
            GameStatus result = engine.evaluate(board);
            System.out.println(result.getOutputMessage());

        } catch (Exception e) {
            // If input is malformed or doesn't meet expectations
            System.out.println(GameStatus.ILLEGAL.getOutputMessage());
        } finally {
            scanner.close();
        }
    }
}

