     * @param oCount Number of moves made by the second player (0).
     * @return A string describing the result ("illegal", "draw", player won, or whose turn it is).
     */
    private static String analyzeGameState(char[][] board, int xCount, int oCount) {
        // 1. Validate basic move counts. 
        // Since X starts, X must have either the same amount of moves as O or exactly one more.
        if (!(xCount == oCount || xCount == oCount + 1)) {
            return "illegal";
        }

        boolean xWins = checkWinner(board, PLAYER_X);
        boolean oWins = checkWinner(board, PLAYER_O);

        // 2. Check for conflicting winners (both players cannot have winning lines)
        if (xWins && oWins) {
            return "illegal";
        }

        // 3. Validate winner consistency with move counts
        if (xWins) {
            // If X won, X must have made the final move (xCount = oCount + 1)
            return (xCount == oCount + 1) ? "the first player won" : "illegal";
        }

        if (oWins) {
            // If O won, O must have made the final move (xCount = oCount)
            return (xCount == oCount) ? "the second player won" : "illegal";
        }

        // 4. Handle non-winning scenarios
        if (isBoardFull(xCount, oCount)) {
            return "draw";
        }

        // Determine whose turn is next
        return (xCount == oCount) ? "first" : "second";
    }

    /**
     * Checks if a specific player has a winning line on the board.
     */
    private static boolean checkWinner(char[][] board, char player) {
        // Check rows and columns
        for (int i = 0; i < 3; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) return true;
            if (board[0][i] == player && board[1][i] == player && board[2][i] == player) return true;
        }

        // Check diagonals
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) return true;
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) return true;

        return false;
    }

    /**
     * Determines if the board is completely filled.
     */
    private static boolean isBoardFull(int xCount, int oCount) {
        return (xCount + oCount) == 9;
    }
}

import java.util.Scanner;

/**
 * A validator for Tic-Tac-Toe game states.
 * It determines if a given board configuration is legal, a draw, 
 * a win for a specific player, or whose turn it is.
 */
public class TicTacToeEvaluator {

    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0'; // Using '0' as per original requirements
    private static final int BOARD_SIZE = 3;
    private static final int TOTAL_CELLS = BOARD_SIZE * BOARD_SIZE;

    public static void main(String[] args) {
        TicTacToeEvaluator evaluator = new TicTacToeEvaluator();
        evaluator.run();
    }

    /**
     * Orchestrates the reading, evaluation, and output of the game state.
     */
    public void run() {
        try (Scanner scanner = new Scanner(System.in)) {
            char[][] board = readBoard(scanner);
            if (board != null) {
                System.out.println(evaluateGameState(board));
            }
        } catch (Exception e) {
            // If input format is fundamentally broken, treat as illegal
            System.out.println("illegal");
        }
    }

    /**
     * Reads the board from standard input.
     * @return A 2D char array representing the board, or null if input is invalid.
     */
    private char[][] readBoard(Scanner scanner) {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (!scanner.hasNextLine()) return null;
            String line = scanner.nextLine();
            if (line.length() < BOARD_SIZE) return null;

            for (int j = 0; j < BOARD_SIZE; j++) {
                board[i][j] = line.charAt(j);
            }
        }
        return board;
    }

    /**
     * Evaluates the board against Tic-Tac-Toe rules.
     * @param board The 3x3 game board.
     * @return A string describing the result (win, draw, turn, or illegal).
     */
    private String evaluateGameState(char[][] board) {
        int xCount = countPlayer(board, PLAYER_X);
        int oCount = countPlayer(board, PLAYER_O);

        // 1. Validate turn order: 
        // Player X starts first, so X count must be equal to O or exactly one more than O.
        if (!(xCount == oCount || xCount == oCount + 1)) {
            return "illegal";
        }

        boolean xWins = checkWin(board, PLAYER_X);
        boolean oWins = checkWin(board, PLAYER_O);

        // 2. Validate win scenarios
        if (xWins && oWins) {
            return "illegal";
        }

        if (xWins) {
            // If X won, they must have made the last move (X = O + 1)
            return (xCount == oCount + 1) ? "the first player won" : "illegal";
        }

        if (oWins) {
            // If O won, X must have just moved, making counts equal (X = O)
            return (xCount == oCount) ? "the second player won" : "illegal";
        }

        // 3. No winner: Check for draw or determine whose turn it is
        if (xCount + oCount == TOTAL_CELLS) {
            return "draw";
        }

        // If X has more pieces, it is Player 2's turn ("second")
        // If counts are equal, it is Player 1's turn ("first")
        return (xCount > oCount) ? "second" : "first";
    }

    /**
     * Counts the occurrences of a specific player's symbol on the board.
     */
    private int countPlayer(char[][] board, char player) {
        int count = 0;
        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                if (board[i][j] == player) count++;
            }
        }
        return count;
    }

    /**
     * Checks if the specified player has achieved a winning line.
     */
    private boolean checkWin(char[][] board, char player) {
        // Check rows and columns
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (isWinningLine(board[i][0], board[i][1], board[i][2], player)) return true;
            if (isWinningLine(board[0][i], board[1][i], board[2][i], player)) return true;
        }
        // Check diagonals
        return isWinningLine(board[0][0], board[1][1], board[2][2], player) ||
               isWinningLine(board[0][2], board[1][1], board[2][0], player);
    }

    /**
     * Helper to check if three characters constitute a winning line.
     */
    private boolean isWinningLine(char c1, char c2, char c3, char player) {
        return c1 == player && c2 == player && c3 == player;
    }
}

import java.util.Scanner;

/**
 * Represents the possible states of a cell in the Tic-Tac-Toe grid.
 */
enum Cell {
    EMPTY,
    X,
    O;

    public static Cell fromChar(char c) {
        return switch (c) {
            case 'X' -> X;
            case 'O' -> O;
            default -> EMPTY;
        };
    }
}

/**
 * Represents the possible outcomes/states of a Tic-Tac-Toe game.
 */
enum GameStatus {
    ILLEGAL,
    DRAW,
    X_WON,
    O_WON,
    NEXT_X_TURN,
    NEXT_O_TURN
}

/**
 * Represents the Tic-Tac-Toe board and its current state.
 */
class TicTacToeBoard {
    private static final int SIZE = 3;
    private final Cell[][] grid = new Cell[SIZE][SIZE];
    private int xCount = 0;
    private int oCount = 0;

    public void loadFromScanner(Scanner scanner) {
        for (int i = 0; i < SIZE; i++) {
            String rowString = scanner.next();
            for (int j = 0; j < SIZE; j++) {
                Cell cell = Cell.fromChar(rowString.charAt(j));
                grid[i][j] = cell;
                if (cell == Cell.X) xCount++;
                else if (cell == Cell.O) oCount++;
            }
        }
    }

    public Cell getCell(int row, int col) {
        return grid[row][col];
    }

    public int getXCount() {
        return xCount;
    }

    public int getOCount() {
        return oCount;
    }

    public int getGridSize() {
        return SIZE;
    }
}

/**
 * Logic engine to evaluate the validity and state of a Tic-Tac-Toe game.
 */
class TicTacToeEvaluator {

    public GameStatus evaluate(TicTacToeBoard board) {
        if (!isMoveCountValid(board)) {
            return GameStatus.ILLEGAL;
        }

        boolean xWins = checkWinner(board, Cell.X);
        boolean oWins = checkWinner(board, Cell.O);

        // If both players have winning configurations, the state is illegal
        if (xWins && oWins) {
            return GameStatus.ILLEGAL;
        }

        if (xWins) {
            return validateWinner(board, Cell.X) ? GameStatus.X_WON : GameStatus.ILLEGAL;
        }

        if (oWins) {
            return validateWinner(board, Cell.O) ? GameStatus.O_WON : GameStatus.ILLEGAL;
        }

        return evaluateOngoingGame(board);
    }

    private boolean isMoveCountValid(TicTacToeBoard board) {
        int x = board.getXCount();
        int o = board.getOCount();
        // X must be equal to O or O + 1. O cannot exceed X.
        return (Math.abs(x - o) <= 1) && (x >= o);
    }

    private boolean validateWinner(TicTacToeBoard board, Cell winner) {
        if (winner == Cell.X) {
            return board.getXCount() == board.getOCount() + 1;
        } else {
            return board.getXCount() == board.getOCount();
        }
    }

    private GameStatus evaluateOngoingGame(TicTacToeBoard board) {
        int totalMoves = board.getXCount() + board.getOCount();
        if (totalMoves == board.getGridSize() * board.getGridSize()) {
            return GameStatus.DRAW;
        }
        return (board.getXCount() == board.getOCount()) 
                ? GameStatus.NEXT_X_TURN 
                : GameStatus.NEXT_O_TURN;
    }

    private boolean checkWinner(TicTacToeBoard board, Cell player) {
        int size = board.getGridSize();

        // Check Rows and Columns
        for (int i = 0; i < size; i++) {
            if (checkLine(board, i, 0, 0, 1, player) || // Row
                checkLine(board, 0, i, 1, 0, player)) { // Col
                return true;
            }
        }

        // Check Diagonals
        if (checkLine(board, 0, 0, 1, 1, player) || // Main diagonal
            checkLine(board, 0, size - 1, 1, -1, player)) { // Anti-diagonal
            return true;
        }

        return false;
    }

    /**
     * Helper to check a line of cells.
     * @param startRow Starting row index
     * @param startCol Starting column index
     * @param rowStep Step direction for row
     * @param colStep Step direction for column
     */
    private boolean checkLine(TicTacToeBoard board, int startRow, int startCol, int rowStep, int colStep, Cell player) {
        for (int i = 0; i < board.getGridSize(); i++) {
            if (board.getCell(startRow + (i * rowStep), startCol + (i * colStep)) != player) {
                return false;
            }
        }
        return true;
    }
}

/**
 * Main entry point for the application.
 */
public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        TicTacToeBoard board = new TicTacToeBoard();
        TicTacToeEvaluator evaluator = new TicTacToeEvaluator();

        try {
            board.loadFromScanner(scanner);
            GameStatus status = evaluator.evaluate(board);
            printResult(status);
        } catch (Exception e) {
            System.out.print("illegal");
        } finally {
            scanner.close();
        }
    }

    private static void printResult(GameStatus status) {
        switch (status) {
            case ILLEGAL -> System.out.print("illegal");
            case DRAW -> System.out.print("draw");
            case X_WON -> System.out.print("the first player won");
            case O_WON -> System.out.print("the second player won");
            case NEXT_X_TURN -> System.out.print("first");
            case NEXT_O_TURN -> System.out.print("second");
        }
    }
}

