/**
 * Represents the possible states/outcomes of a Tic-Tac-Toe game.
 */
enum GameResult {
    FIRST_PLAYER_WON("the first player won"),
    SECOND_PLAYER_WON("the second player won"),
    DRAW("draw"),
    FIRST_TURN("first"),
    SECOND_TURN("second"),
    ILLEGAL("illegal");

    private final String message;

    GameResult(String message) {
        this.message = message;
    }

    public String getMessage() {
        return message;
    }
}

/**
 * Represents the Tic-Tac-Toe board and handles grid-based calculations.
 */
class Board {
    public static final int SIZE = 3;
    public static final char PLAYER_X = 'X';
    public static final char PLAYER_O = '0'; // Using '0' as per original requirement

    private final char[][] grid;
    private int countX = 0;
    private int countO = 0;
    private int countBlank = 0;

    public Board() {
        this.grid = new char[SIZE][SIZE];
    }

    public void setCell(int row, int col, char value) {
        grid[row][col] = value;
        if (value == PLAYER_X) {
            countX++;
        } else if (value == PLAYER_O) {
            countO++;
        } else {
            countBlank++;
        }
    }

    public boolean isWin(char player) {
        // Check rows and columns
        for (int i = 0; i < SIZE; i++) {
            if (checkLine(grid[i][0], grid[i][1], grid[i][2], player)) return true;
            if (checkLine(grid[0][i], grid[1][i], grid[2][i], player)) return true;
        }
        // Check diagonals
        return checkLine(grid[0][0], grid[1][1], grid[2][2], player) ||
               checkLine(grid[2][0], grid[1][1], grid[0][2], player);
    }

    private boolean checkLine(char c1, char c2, char c3, char player) {
        return c1 == player && c2 == player && c3 == player;
    }

    public int getCountX() { return countX; }
    public int getCountO() { return countO; }
    public int getCountBlank() { return countBlank; }
}

/**
 * Logic engine that determines the game status based on board state.
 */
class GameEvaluator {

    public GameResult evaluate(Board board) {
        int x = board.getCountX();
        int o = board.getCountO();
        int blanks = board.getCountBlank();
        boolean xWin = board.isWin(Board.PLAYER_X);
        boolean oWin = board.isWin(Board.PLAYER_O);

        // 1. Validate basic piece count rules
        if (Math.abs(x - o) > 1 || o > x) {
            return GameResult.ILLEGAL;
        }

        // 2. Validate win consistency
        if (xWin && oWin) return GameResult.ILLEGAL;
        if (oWin && x > o) return GameResult.ILLEGAL;
        if (xWin && x == o) return GameResult.ILLEGAL;

        // 3. Determine specific outcomes
        if (xWin) return GameResult.FIRST_PLAYER_WON;
        if (oWin) return GameResult.SECOND_PLAYER_WON;

        // 4. Handle non-win scenarios (Draws and Turns)
        if (blanks == 0 && x > o) {
            return GameResult.DRAW;
        }

        if (x == o) {
            return GameResult.FIRST_TURN;
        } else if (x > o) {
            return GameResult.SECOND_TURN;
        }

        return GameResult.ILLEGAL;
    }
}

/**
 * Main entry point for the TicTacToe application.
 */
public class TicTacToe {

    public static void main(String[] args) {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter pw = new PrintWriter(System.out)) {

            Board board = readBoard(br);
            GameEvaluator evaluator = new GameEvaluator();
            GameResult result = evaluator.evaluate(board);

            pw.println(result.getMessage());
            pw.flush();

        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Parses the input from the reader into a Board object.
     */
    private static Board readBoard(BufferedReader br) throws IOException {
        Board board = new Board();
        for (int i = 0; i < Board.SIZE; i++) {
            String line = br.readLine();
            if (line == null) throw new IOException("Unexpected end of input");

            for (int j = 0; j < Board.SIZE; j++) {
                // Handling potential index out of bounds if input line is short
                char c = (j < line.length()) ? line.charAt(j) : ' ';
                board.setCell(i, j, c);
            }
        }
        return board;
    }
}

