/**
 * An evaluator for Tic-Tac-Toe game states.
 * Determines if a board state is illegal, a draw, a win, or whose turn it is.
 */
public class TicTacToeEvaluator {

    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0';
    private static final int BOARD_SIZE = 3;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];

        try {
            for (int i = 0; i < BOARD_SIZE; i++) {
                String line = scanner.next();
                board[i] = line.toCharArray();
            }
            System.out.println(evaluateGameState(board));
        } catch (Exception e) {
            System.out.println("illegal");
        } finally {
            scanner.close();
        }
    }

    /**
     * Evaluates the current board and returns the game status string.
     */
    public static String evaluateGameState(char[][] board) {
        int xCount = countPlayer(board, PLAYER_X);
        int oCount = countPlayer(board, PLAYER_O);

        boolean xWins = checkWin(board, PLAYER_X);
        boolean oWins = checkWin(board, PLAYER_O);

        // 1. Check for Illegal States
        if (isIllegal(xCount, oCount, xWins, oWins)) {
            return "illegal";
        }

        // 2. Check for Wins
        if (xWins) {
            return "the first player won";
        }
        if (oWins) {
            return "the second player won";
        }

        // 3. Check for Draw
        if (isBoardFull(xCount, oCount)) {
            return "draw";
        }

        // 4. Determine whose turn it is
        // If xCount == oCount, it is Player X's turn
        return (xCount == oCount) ? "first" : "second";
    }

    private static boolean isIllegal(int xCount, int oCount, boolean xWins, boolean oWins) {
        // Both players cannot win simultaneously
        if (xWins && oWins) return true;

        // Turn order violations
        if (oCount > xCount) return true;             // Player O cannot have more moves than X
        if (xCount - oCount > 1) return true;        // Player X cannot have more than 1 extra move

        // If X won, it must have been X's turn that just finished (X = O + 1)
        if (xWins && xCount == oCount) return true;

        // If O won, it must have been O's turn that just finished (X = O)
        if (oWins && xCount == oCount + 1) return true;

        return false;
    }

    private static boolean isBoardFull(int xCount, int oCount) {
        return (xCount + oCount) == (BOARD_SIZE * BOARD_SIZE);
    }

    private static int countPlayer(char[][] board, char player) {
        int count = 0;
        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                if (board[i][j] == player) count++;
            }
        }
        return count;
    }

    private static boolean checkWin(char[][] board, char p) {
        // Check Rows and Columns
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i][0] == p && board[i][1] == p && board[i][2] == p) return true;
            if (board[0][i] == p && board[1][i] == p && board[2][i] == p) return true;
        }

        // Check Diagonals
        if (board[0][0] == p && board[1][1] == p && board[2][2] == p) return true;
        if (board[0][2] == p && board[1][1] == p && board[2][0] == p) return true;

        return false;
    }
}

