/**
 * Represents the players in the game.
 */
enum Player {
    X, O, EMPTY;

    public static Player fromChar(char c) {
        return switch (c) {
            case 'X' -> X;
            case '0' -> O; // Maintaining original logic where '0' represents the second player
            default -> EMPTY;
        };
    }
}

/**
 * Represents the possible results of a board validation.
 */
enum GameStatus {
    FIRST_PLAYER_WON("the first player won"),
    SECOND_PLAYER_WON("the second player won"),
    DRAW("draw"),
    FIRST_TURN("first"),
    SECOND_TURN("second"),
    ILLEGAL("illegal");

    private final String message;

    GameStatus(String message) {
        this.message = message;
    }

    @Override
    public String toString() {
        return message;
    }
}

/**
 * Logic engine for the Tic Tac Toe board.
 */
class TicTacToeBoard {
    private static final int SIZE = 3;
    private final Player[][] grid = new Player[SIZE][SIZE];

    public TicTacToeBoard(String[] rows) {
        for (int i = 0; i < SIZE; i++) {
            for (int j = 0; j < SIZE; j++) {
                grid[i][j] = Player.fromChar(rows[i].charAt(j));
            }
        }
    }

    /**
     * Validates the board state according to Tic Tac Toe rules.
     * 
     * @return GameStatus indicating the current state of the board.
     */
    public GameStatus validate() {
        int xCount = countPlayer(Player.X);
        int oCount = countPlayer(Player.O);

        // Rule 1: Turn order must be valid. 
        // X moves first, so xCount must be equal to oCount or oCount + 1.
        if (xCount < oCount || xCount > oCount + 1) {
            return GameStatus.ILLEGAL;
        }

        boolean xWon = checkWin(Player.X);
        boolean oWon = checkWin(Player.O);

        // Rule 2: Both players cannot win simultaneously.
        if (xWon && oWon) {
            return GameStatus.ILLEGAL;
        }

        // Rule 3: If X won, it must have been X's turn that just finished (xCount = oCount + 1).
        if (xWon) {
            return (xCount == oCount + 1) ? GameStatus.FIRST_PLAYER_WON : GameStatus.ILLEGAL;
        }

        // Rule 4: If O won, it must have been O's turn that just finished (xCount = oCount).
        if (oWon) {
            return (xCount == oCount) ? GameStatus.SECOND_PLAYER_WON : GameStatus.ILLEGAL;
        }

        // Rule 5: If no one won, check if board is full or whose turn it is.
        if (xCount + oCount == SIZE * SIZE) {
            return GameStatus.DRAW;
        }

        return (xCount == oCount) ? GameStatus.FIRST_TURN : GameStatus.SECOND_TURN;
    }

    private int countPlayer(Player player) {
        int count = 0;
        for (int r = 0; r < SIZE; r++) {
            for (int c = 0; c < SIZE; c++) {
                if (grid[r][c] == player) count++;
            }
        }
        return count;
    }

    private boolean checkWin(Player p) {
        // Check rows and columns
        for (int i = 0; i < SIZE; i++) {
            if (checkLine(p, i, 0, 0, 1) || checkLine(p, 0, i, 1, 0)) {
                return true;
            }
        }
        // Check diagonals
        return checkLine(p, 0, 0, 1, 1) || checkLine(p, 0, 2, 1, -1);
    }

    /**
     * Helper to check if 3 squares in a specific direction match the player.
     */
    private boolean checkLine(Player p, int startR, int startC, int deltaR, int deltaC) {
        for (int i = 0; i < SIZE; i++) {
            int r = startR + (i * deltaR);
            int c = startC + (i * deltaC);
            if (grid[r][c] != p) return false;
        }
        return true;
    }
}

