    private static final String MSG_DRAW = "draw";
    private static final String MSG_TURN_FIRST = "first";
    private static final String MSG_TURN_SECOND = "second";

    private enum Player {
        X, ZERO, EMPTY;

        public static Player fromChar(char c) {
            if (c == 'X') return X;
            if (c == '0') return ZERO;
            return EMPTY;
        }
    }

    private enum GameResult {
        ILLEGAL(MSG_ILLEGAL),
        WIN_X(MSG_FIRST_PLAYER_WON),
        WIN_ZERO(MSG_SECOND_PLAYER_WON),
        DRAW(MSG_DRAW),
        TURN_X(MSG_TURN_SECOND), // X is the first player, so if X has moved, it's the second player's turn
        TURN_ZERO(MSG_TURN_FIRST); // If counts are equal, it is the first player's turn

        private final String message;

        GameResult(String message) {
            this.message = message;
        }

        public String getMessage() {
            return message;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] gridInput = new char[3][3];

        try {
            for (int i = 0; i < 3; i++) {
                String line = scanner.nextLine();
                for (int j = 0; j < 3; j++) {
                    gridInput[i][j] = line.charAt(j);
                }
            }

            TicTacToeGame game = new TicTacToeGame(gridInput);
            System.out.println(game.evaluate().getMessage());

        } catch (Exception e) {
            // In a real-world scenario, handle specific input errors more gracefully
            System.out.println(MSG_ILLEGAL);
        } finally {
            scanner.close();
        }
    }

    private static class TicTacToeGame {
        private final Player[][] board = new Player[3][3];
        private int xCount = 0;
        private int zeroCount = 0;

        public TicTacToeGame(char[][] input) {
            for (int i = 0; i < 3; i++) {
                for (int j = 0; j < 3; j++) {
                    board[i][j] = Player.fromChar(input[i][j]);
                    if (board[i][j] == Player.X) xCount++;
                    else if (board[i][j] == Player.ZERO) zeroCount++;
                }
            }
        }

        /**
         * Evaluates the board state and returns the appropriate GameResult.
         */
        public GameResult evaluate() {
            if (isIllegal()) {
                return GameResult.ILLEGAL;
            }

            int xLines = countWinningLines(Player.X);
            int zeroLines = countWinningLines(Player.ZERO);

            // A state is illegal if more than one player has won, 
            // or if a player has more than one winning line (indicating game should have ended)
            if (xLines + zeroLines > 1) {
                return GameResult.ILLEGAL;
            }

            if (xLines > 0) return GameResult.WIN_X;
            if (zeroLines > 0) return GameResult.WIN_ZERO;
            if (isBoardFull()) return GameResult.DRAW;

            // Determine turn: If counts are equal, it's Player 1's (X) turn.
            // If X has one more, it's Player 2's (ZERO) turn.
            return (xCount == zeroCount) ? GameResult.TURN_ZERO : GameResult.TURN_X;
        }

        private boolean isIllegal() {
            // Check if piece counts are mathematically impossible
            if (zeroCount > xCount || (xCount - zeroCount) > 1) {
                return true;
            }

            int xLines = countWinningLines(Player.X);
            int zeroLines = countWinningLines(Player.ZERO);

            // Check if win conditions match the piece counts
            // If X wins, X must have exactly one more piece than ZERO
            if (xLines > 0 && xCount != zeroCount + 1) return true;
            // If ZERO wins, counts must be equal
            if (zeroLines > 0 && xCount != zeroCount) return true;

            return false;
        }

        private boolean isBoardFull() {
            return (xCount + zeroCount) == 9;
        }

        /**
         * Counts how many winning lines a specific player has.
         */
        private int countWinningLines(Player player) {
            int lines = 0;
            int[][] winningPatterns = {
                {0, 1, 2}, {3, 4, 5}, {6, 7, 8}, // Rows
                {0, 3, 6}, {1, 4, 7}, {2, 5, 8}, // Cols
                {0, 4, 8}, {2, 4, 6}             // Diagonals
            };

            for (int[] pattern : winningPatterns) {
                if (checkPattern(pattern, player)) {
                    lines++;
                }
            }
            return lines;
        }

        private boolean checkPattern(int[] pattern, Player player) {
            for (int index : pattern) {
                int row = index / 3;
                int col = index % 3;
                if (board[row][col] != player) {
                    return false;
                }
            }
            return true;
        }
    }
}

