/**
 * Contains the logic to evaluate a 3x3 Tic-Tac-Toe board.
 */
class TicTacToeEvaluator {
    private static final int BOARD_SIZE = 3;
    private static final int TOTAL_CELLS = BOARD_SIZE * BOARD_SIZE;
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_ZERO = '0';

    private final char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
    private int countX = 0;
    private int countZero = 0;

    /**
     * Populates the board from the provided reader.
     */
    public void loadBoard(FastReader reader) {
        for (int i = 0; i < BOARD_SIZE; i++) {
            String row = reader.next();
            if (row != null) {
                for (int j = 0; j < BOARD_SIZE; j++) {
                    char cell = row.charAt(j);
                    board[i][j] = cell;
                    if (cell == PLAYER_X) {
                        countX++;
                    } else if (cell == PLAYER_ZERO) {
                        countZero++;
                    }
                }
            }
        }
    }

    /**
     * Evaluates the current board state and returns the game result.
     */
    public GameResult evaluate() {
        // 1. Validate player counts (X must be equal to 0 or 0 + 1)
        if (!(countX == countZero || countX == countZero + 1)) {
            return GameResult.ILLEGAL;
        }

        boolean xWon = hasWinner(PLAYER_X);
        boolean zeroWon = hasWinner(PLAYER_ZERO);

        // 2. Validate that both players haven't won simultaneously
        if (xWon && zeroWon) {
            return GameResult.ILLEGAL;
        }

        // 3. Evaluate Win Conditions
        if (xWon) {
            // If X won, it must have been X's turn that completed the win (countX = countZero + 1)
            return (countX == countZero + 1) ? GameResult.FIRST_PLAYER_WON : GameResult.ILLEGAL;
        }

        if (zeroWon) {
            // If Zero won, it must have been Zero's turn that completed the win (countX = countZero)
            return (countX == countZero) ? GameResult.SECOND_PLAYER_WON : GameResult.ILLEGAL;
        }

        // 4. Evaluate non-win conditions (Draw or ongoing game)
        if (countX + countZero == TOTAL_CELLS) {
            return GameResult.DRAW;
        }

        // Return whose turn it is based on counts
        return (countX == countZero) ? GameResult.FIRST_PLAYER_TURN : GameResult.SECOND_PLAYER_TURN;
    }

    /**
     * Checks if the specified player has a winning line on the board.
     */
    private boolean hasWinner(char player) {
        // Check rows and columns
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) return true;
            if (board[0][i] == player && board[1][i] == player && board[2][i] == player) return true;
        }
        // Check diagonals
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) return true;
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) return true;

        return false;
    }
}

/**
 * Utility class for fast I/O operations.
 */
class FastReader {
    private final BufferedReader br;
    private StringTokenizer st;

    public FastReader(InputStream in) {
        this.br = new BufferedReader(new InputStreamReader(in));
    }

    public String next() {
        while (st == null || !st.hasMoreTokens()) {
            try {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            } catch (IOException e) {
                throw new RuntimeException("Error reading input", e);
            }
        }
        return st.nextToken();
    }
}

