/**
 * Represents the Tic-Tac-Toe board.
 */
class TicTacToeBoard {
    private static final int SIZE = 3;
    private final char[][] grid = new char[SIZE][SIZE];
    private int xCount = 0;
    private int zeroCount = 0;

    public static final char PLAYER_X = 'X';
    public static final char PLAYER_ZERO = '0';
    public static final char EMPTY = '.';

    public TicTacToeBoard() {
        for (int i = 0; i < SIZE; i++) {
            for (int j = 0; j < SIZE; j++) {
                grid[i][j] = EMPTY;
            }
        }
    }

    public void setCell(int row, int col, char symbol) {
        grid[row][col] = symbol;
        if (symbol == PLAYER_X) {
            xCount++;
        } else if (symbol == PLAYER_ZERO) {
            zeroCount++;
        }
    }

    public char getCell(int row, int col) {
        return grid[row][col];
    }

    public int getXCount() {
        return xCount;
    }

    public int getZeroCount() {
        return zeroCount;
    }

    public int getTotalMoves() {
        return xCount + zeroCount;
    }

    public boolean isFull() {
        return getTotalMoves() == SIZE * SIZE;
    }

    public boolean hasWon(char player) {
        // Check rows and columns
        for (int i = 0; i < SIZE; i++) {
            if (checkLine(grid[i][0], grid[i][1], grid[i][2], player)) return true;
            if (checkLine(grid[0][i], grid[1][i], grid[2][i], player)) return true;
        }
        // Check diagonals
        return checkLine(grid[0][0], grid[1][1], grid[2][2], player) ||
               checkLine(grid[0][2], grid[1][1], grid[2][0], player);
    }

    private boolean checkLine(char c1, char c2, char c3, char player) {
        return c1 == player && c2 == player && c3 == player;
    }
}

/**
 * Handles the evaluation logic of the Tic-Tac-Toe game rules.
 */
class TicTacToeGame {
    private final TicTacToeBoard board;

    public TicTacToeGame(TicTacToeBoard board) {
        this.board = board;
    }

    public GameResult evaluate() {
        int xCount = board.getXCount();
        int zeroCount = board.getZeroCount();

        // 1. Validate move count parity
        if (xCount < zeroCount || xCount > zeroCount + 1) {
            return GameResult.ILLEGAL;
        }

        boolean xWins = board.hasWon(TicTacToeBoard.PLAYER_X);
        boolean zeroWins = board.hasWon(TicTacToeBoard.PLAYER_ZERO);

        // 2. Evaluate win conditions
        if (xWins) {
            // If X wins, X must have made one more move than 0
            return (xCount == zeroCount + 1) ? GameResult.FIRST_PLAYER_WON : GameResult.ILLEGAL;
        }

        if (zeroWins) {
            // If 0 wins, X must have the same number of moves as 0
            return (xCount == zeroCount) ? GameResult.SECOND_PLAYER_WON : GameResult.ILLEGAL;
        }

        // 3. Evaluate draw or turn
        if (board.isFull()) {
            return GameResult.DRAW;
        }

        return (xCount == zeroCount) ? GameResult.FIRST_PLAYER_TURN : GameResult.SECOND_PLAYER_TURN;
    }
}

