/**
 * A validator for Tic-Tac-Toe game states.
 * It determines if a game state is legal, who won, or whose turn it is.
 */
public class TicTacToeValidator {

    private static final char PLAYER_ONE = 'X';
    private static final char PLAYER_TWO = '0';
    private static final int GRID_SIZE = 3;

    /**
     * Represents the possible outcomes of a Tic-Tac-Toe game state.
     */
    public enum GameResult {
        ILLEGAL("illegal"),
        FIRST_PLAYER_WON("the first player won"),
        SECOND_PLAYER_WON("the second player won"),
        DRAW("draw"),
        FIRST_TURN("first"),
        SECOND_TURN("second");

        private final String message;

        GameResult(String message) {
            this.message = message;
        }

        @Override
        public String toString() {
            return message;
        }
    }

    /**
     * Represents the Tic-Tac-Toe board.
     */
    private static class Board {
        private final char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        private int xCount = 0;
        private int oCount = 0;

        public Board(Scanner sc) {
            for (int i = 0; i < GRID_SIZE; i++) {
                String line = sc.next();
                for (int j = 0; j < GRID_SIZE; j++) {
                    grid[i][j] = line.charAt(j);
                    if (grid[i][j] == PLAYER_ONE) {
                        xCount++;
                    } else if (grid[i][j] == PLAYER_TWO) {
                        oCount++;
                    }
                }
            }
        }

        public int getXCount() { return xCount; }
        public int getOCount() { return oCount; }
        public int getTotalMoves() { return xCount + oCount; }

        public boolean hasWon(char player) {
            // Check rows and columns
            for (int i = 0; i < GRID_SIZE; i++) {
                if (checkLine(grid[i][0], grid[i][1], grid[i][2], player)) return true;
                if (checkLine(grid[0][i], grid[1][i], grid[2][i], player)) return true;
            }
            // Check diagonals
            return checkLine(grid[0][0], grid[1][1], grid[2][2], player) ||
                   checkLine(grid[0][2], grid[1][1], grid[2][0], player);
        }

        private boolean checkLine(char c1, char c2, char c3, char player) {
            return c1 == player && c2 == player && c3 == player;
        }
    }

    /**
     * Core engine to analyze the board state.
     */
    public static class GameEngine {

        public static GameResult analyze(Board board) {
            int x = board.getXCount();
            int o = board.getOCount();

            // 1. Basic move count validation
            if (!(x == o || x == o + 1)) {
                return GameResult.ILLEGAL;
            }

            boolean xWins = board.hasWon(PLAYER_ONE);
            boolean oWins = board.hasWon(PLAYER_TWO);

            // 2. Winner validation
            if (xWins && oWins) {
                return GameResult.ILLEGAL;
            }

            if (xWins) {
                // If X wins, X must have made the last move (x == o + 1)
                return (x == o + 1) ? GameResult.FIRST_PLAYER_WON : GameResult.ILLEGAL;
            }

            if (oWins) {
                // If O wins, the counts must be equal (x == o)
                return (x == o) ? GameResult.SECOND_PLAYER_WON : GameResult.ILLEGAL;
            }

            // 3. Non-winning state validation
            if (board.getTotalMoves() == 9) {
                return GameResult.DRAW;
            }

            return (x == o) ? GameResult.FIRST_TURN : GameResult.SECOND_TURN;
        }
    }

    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            if (!sc.hasNext()) return;

            Board board = new Board(sc);
            GameResult result = GameEngine.analyze(board);
            System.out.println(result);
        } catch (Exception e) {
            // In a production environment, use a proper logger
            System.out.println("illegal");
        }
    }
}

