/**
 * Contains the business logic for evaluating the game state.
 */
class TicTacToeEvaluator {
    private final Board board;

    // Result Constants
    private static final String ILLEGAL = "illegal";
    private static final String X_WON = "the first player won";
    private static final String O_WON = "the second player won";
    private static final String DRAW = "draw";
    private static final String NEXT_X = "first";
    private static final String NEXT_O = "second";

    public TicTacToeEvaluator(Board board) {
        this.board = board;
    }

    /**
     * Evaluates the current board state and returns the game status.
     */
    public String evaluate() {
        int xCount = board.getXCount();
        int oCount = board.getOCount();

        // 1. Validate turn counts (X goes first, so X must be equal to O or O + 1)
        if (xCount < oCount || xCount > oCount + 1) {
            return ILLEGAL;
        }

        boolean xWins = hasWinningLine(Board.PLAYER_X);
        boolean oWins = hasWinningLine(Board.PLAYER_O);

        // 2. Check for impossible win states
        if (xWins && oWins) {
            return ILLEGAL;
        }

        // 3. Evaluate Win/Draw/Turn status
        if (xWins) {
            // X can only win if it was X's turn that completed the line (xCount = oCount + 1)
            return (xCount == oCount + 1) ? X_WON : ILLEGAL;
        }

        if (oWins) {
            // O can only win if it was O's turn that completed the line (xCount = oCount)
            return (xCount == oCount) ? O_WON : ILLEGAL;
        }

        if (board.isFull()) {
            return DRAW;
        }

        // 4. Determine whose turn it is if no one has won and game is not full
        return (xCount == oCount) ? NEXT_X : NEXT_O;
    }

    /**
     * Checks if the specified player has three in a row.
     */
    private boolean hasWinningLine(char player) {
        // Check rows and columns
        for (int i = 0; i < 3; i++) {
            if (checkLine(board.getCell(i, 0), board.getCell(i, 1), board.getCell(i, 2), player)) return true;
            if (checkLine(board.getCell(0, i), board.getCell(1, i), board.getCell(2, i), player)) return true;
        }

        // Check diagonals
        if (checkLine(board.getCell(0, 0), board.getCell(1, 1), board.getCell(2, 2), player)) return true;
        if (checkLine(board.getCell(0, 2), board.getCell(1, 1), board.getCell(2, 0), player)) return true;

        return false;
    }

    private boolean checkLine(char c1, char c2, char c3, char player) {
        return c1 == player && c2 == player && c3 == player;
    }
}

