        if (xWins) {
            // If X wins, the last move must have been X's (making X = O + 1)
            return (xCount == oCount + 1) ? RESULT_X_WON : RESULT_ILLEGAL;
        }

        if (oWins) {
            // If O wins, the last move must have been O's (making X = O)
            return (xCount == oCount) ? RESULT_O_WON : RESULT_ILLEGAL;
        }

        // 4. Handle non-win scenarios
        if (xCount + oCount == TOTAL_CELLS) {
            return RESULT_DRAW;
        }

        // Return whose turn it is based on current counts
        return (xCount == oCount) ? TURN_FIRST : TURN_SECOND;
    }

    private static int countPlayer(char[][] board, char player) {
        int count = 0;
        for (int r = 0; r < BOARD_SIZE; r++) {
            for (int c = 0; c < BOARD_SIZE; c++) {
                if (board[r][c] == player) {
                    count++;
                }
            }
        }
        return count;
    }

    private static boolean hasWinner(char[][] board, char player) {
        // Check Rows
        for (int r = 0; r < BOARD_SIZE; r++) {
            if (board[r][0] == player && board[r][1] == player && board[r][2] == player) {
                return true;
            }
        }

        // Check Columns
        for (int c = 0; c < BOARD_SIZE; c++) {
            if (board[0][c] == player && board[1][c] == player && board[2][c] == player) {
                return true;
            }
        }

        // Check Diagonals
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
            return true;
        }
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
            return true;
        }

        return false;
    }
}

