/**
 * A program to evaluate the current state of a Tic-Tac-Toe game.
 * It determines if the game is in a winning state, a draw, a turn-based state, 
 * or an illegal state.
 */
public class TicTacToeSolution {

    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0'; // Using digit '0' as per original requirement
    private static final char EMPTY = '.';
    private static final int BOARD_SIZE = 3;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNext()) {
            return;
        }

        try {
            char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
            int xCount = 0;
            int oCount = 0;

            // Parse the 3x3 grid
            for (int i = 0; i < BOARD_SIZE; i++) {
                String rowString = scanner.next();
                for (int j = 0; j < BOARD_SIZE; j++) {
                    char cell = rowString.charAt(j);
                    board[i][j] = cell;
                    if (cell == PLAYER_X) {
                        xCount++;
                    } else if (cell == PLAYER_O) {
                        oCount++;
                    }
                }
            }

            System.out.println(evaluateGameState(board, xCount, oCount));
        } catch (Exception e) {
            // In a production environment, use a proper logging framework
            System.err.println("Error processing input: " + e.getMessage());
        } finally {
            scanner.close();
        }
    }

    /**
     * Evaluates the state of the Tic-Tac-Toe board based on turn counts and winner detection.
     *
     * @param board   The 3x3 board representation.
     * @param xCount  Total number of 'X' pieces.
     * @param oCount  Total number of '0' pieces.
     * @return A string describing the game status.
     */
    private static String evaluateGameState(char[][] board, int xCount, int oCount) {
        // 1. Validate if the number of moves is possible.
        // X starts first, so X count must be equal to O or exactly one more than O.
        if (xCount != oCount && xCount != oCount + 1) {
            return "illegal";
        }

        boolean xWon = checkWinner(board, PLAYER_X);
        boolean oWon = checkWinner(board, PLAYER_O);

        // 2. If both players have a winning line, the game state is illegal.
        if (xWon && oWon) {
            return "illegal";
        }

        // 3. Handle Winner Scenarios
        if (xWon) {
            // If X won, the last move must have been X's, meaning X count = O count + 1.
            return (xCount == oCount + 1) ? "the first player won" : "illegal";
        }

        if (oWon) {
            // If O won, the last move must have been O's, meaning X count = O count.
            return (xCount == oCount) ? "the second player won" : "illegal";
        }

        // 4. Handle Non-Winner Scenarios
        if (xCount + oCount == BOARD_SIZE * BOARD_SIZE) {
            return "draw";
        } else {
            // If board is not full and no one has won, determine whose turn it is.
            // If X and O counts are equal, it is X's (first) turn.
            // If X has one more, it is O's (second) turn.
            return (xCount == oCount) ? "first" : "second";
        }
    }

    /**
     * Checks if a specific player has three in a row (rows, columns, or diagonals).
     *
     * @param board  The game board.
     * @param player The character representing the player.
     * @return True if the player has won, false otherwise.
     */
    private static boolean checkWinner(char[][] board, char player) {
        // Check Rows
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                return true;
            }
        }

        // Check Columns
        for (int j = 0; j < BOARD_SIZE; j++) {
            if (board[0][j] == player && board[1][j] == player && board[2][j] == player) {
                return true;
            }
        }

        // Check Diagonals
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
            return true;
        }
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
            return true;
        }

        return false;
    }
}

