/**
 * Represents the possible outcomes of a Tic-Tac-Toe game.
 */
enum GameResult {
    ILLEGAL("illegal"),
    FIRST_PLAYER_WON("the first player won"),
    SECOND_PLAYER_WON("the second player won"),
    DRAW("draw"),
    NEXT_TURN_FIRST("first"),
    NEXT_TURN_SECOND("second");

    private final String message;

    GameResult(String message) {
        this.message = message;
    }

    public String getMessage() {
        return message;
    }
}

/**
 * Logic engine for validating and evaluating the Tic-Tac-Toe board.
 */
class TicTacToeEvaluator {

    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0';
    private static final char EMPTY = '.';

    // Winning index combinations for a 3x3 board
    private static final int[][] WINNING_COMBINATIONS = {
        {0, 1, 2}, {3, 4, 5}, {6, 7, 8}, // Rows
        {0, 3, 6}, {1, 4, 7}, {2, 5, 8}, // Columns
        {0, 4, 8}, {2, 4, 6}             // Diagonals
    };

    private final char[] board;

    public TicTacToeEvaluator(char[] board) {
        this.board = board;
    }

    /**
     * Evaluates the board and returns the current GameResult.
     */
    public GameResult evaluate() {
        int countX = 0;
        int countO = 0;
        int countEmpty = 0;

        for (char cell : board) {
            if (cell == PLAYER_X) countX++;
            else if (cell == PLAYER_O) countO++;
            else if (cell == EMPTY) countEmpty++;
        }

        // 1. Basic count legality: X must be equal to O or O + 1
        if (countX < countO || countX > countO + 1) {
            return GameResult.ILLEGAL;
        }

        boolean isXWinner = checkWinner(PLAYER_X);
        boolean isOWinner = checkWinner(PLAYER_O);

        // 2. Winner legality: Both cannot win simultaneously
        if (isXWinner && isOWinner) {
            return GameResult.ILLEGAL;
        }

        // 3. Turn consistency: 
        // If X wins, it must have been X's turn that just ended (countX == countO + 1)
        if (isXWinner && countX != countO + 1) {
            return GameResult.ILLEGAL;
        }
        // If O wins, it must have been O's turn that just ended (countX == countO)
        if (isOWinner && countX != countO) {
            return GameResult.ILLEGAL;
        }

        // 4. Return winning states
        if (isXWinner) return GameResult.FIRST_PLAYER_WON;
        if (isOWinner) return GameResult.SECOND_PLAYER_WON;

        // 5. Return non-winning states
        if (countEmpty == 0) {
            return GameResult.DRAW;
        }

        return (countX == countO) ? GameResult.NEXT_TURN_FIRST : GameResult.NEXT_TURN_SECOND;
    }

    /**
     * Checks if the specified player has a winning line on the board.
     */
    private boolean checkWinner(char player) {
        for (int[] combo : WINNING_COMBINATIONS) {
            if (board[combo[0]] == player &&
                board[combo[1]] == player &&
                board[combo[2]] == player) {
                return true;
            }
        }
        return false;
    }
}

