/**
 * A validator for Tic-Tac-Toe game states.
 * It checks if a given board state is valid according to standard rules:
 * 1. Turn order must be correct (X starts first).
 * 2. Only one player can have a winning combination.
 * 3. A winner's move count must align with whose turn it was.
 */
public class TicTacToeValidator {

    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0'; // Using '0' to match original requirement

    // All possible winning index combinations in a 3x3 grid
    private static final int[][] WINNING_COMBINATIONS = {
        {0, 1, 2}, {3, 4, 5}, {6, 7, 8}, // Rows
        {0, 3, 6}, {1, 4, 7}, {2, 5, 8}, // Columns
        {0, 4, 8}, {2, 4, 6}             // Diagonals
    };

    public static void main(String[] args) {
        TicTacToeValidator validator = new TicTacToeValidator();
        validator.execute();
    }

    public void execute() {
        Scanner scanner = new Scanner(System.in);
        char[][] board = new char[3][3];
        int countX = 0;
        int countO = 0;

