            for (int i = 0; i < 3; i++) {
                if (!scanner.hasNext()) break;
                String row = scanner.next();
                for (int j = 0; j < 3; j++) {
                    char cell = row.charAt(j);
                    board[i][j] = cell;
                    if (cell == PLAYER_X) {
                        countX++;
                    } else if (cell == PLAYER_O) {
                        countO++;
                    }
                }
            }
            validateGameState(board, countX, countO);
        } catch (Exception e) {
