        }
    }

    /**
     * Validates the board based on move counts and winning patterns.
     */
    private void validateGameState(char[][] board, int countX, int countO) {
        int turnDifference = countX - countO;

        // Rule 1: Turn order check. 
        // X starts, so X must have either the same number of moves as O or exactly one more.
        if (turnDifference < 0 || turnDifference >= 2) {
            System.out.println("illegal");
            return;
        }

        boolean xWins = hasWinner(board, PLAYER_X);
        boolean oWins = hasWinner(board, PLAYER_O);

        // Rule 2: Only one player can win.
        if (xWins && oWins) {
            System.out.println("illegal");
            return;
        }

        if (xWins) {
            // Rule 3: If X wins, it must have been X's turn that completed the move (countX = countO + 1)
            if (countX == countO + 1) {
                System.out.println("the first player won");
            } else {
                System.out.println("illegal");
            }
        } else if (oWins) {
            // Rule 4: If O wins, it must have been O's turn that completed the move (countX = countO)
            if (countX == countO) {
                System.out.println("the second player won");
            } else {
                System.out.println("illegal");
            }
        } else {
            // Rule 5: No winner found, check if the board is full (Draw)
            if (countX + countO == 9) {
                System.out.println("draw");
            }
            // If not full and no winner, the game is ongoing (no output required per original logic)
        }
    }

    /**
     * Checks if the specified player has a winning line on the board.
     */
    private boolean hasWinner(char[][] board, char player) {
        for (int[] combo : WINNING_COMBINATIONS) {
            if (isLineWinning(board, combo, player)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Helper to check if a specific combination of indices belongs to the player.
     */
    private boolean isLineWinning(char[][] board, int[] combo, char player) {
        for (int index : combo) {
            int row = index / 3;
            int col = index % 3;
            if (board[row][col] != player) {
                return false;
            }
        }
        return true;
    }
}

