/**
 * A utility to analyze the state of a Tic-Tac-Toe board.
 * It determines if the current state is illegal, who won, 
 * if it's a draw, or whose turn it is.
 */
public class TicTacToeAnalyzer {

    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0'; // Preserved original '0' character
    private static final char EMPTY = '.';
    private static final int BOARD_SIZE = 3;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        while (scanner.hasNext()) {
            try {
                char[][] board = readBoard(scanner);
                if (board == null) break;

                analyzeBoard(board);
            } catch (Exception e) {
                // Handle potential input errors gracefully
                break;
            }
        }
        scanner.close();
    }

    /**
     * Reads 3 rows from the scanner to construct the board.
     */
    private static char[][] readBoard(Scanner scanner) {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (!scanner.hasNext()) return null;
            String row = scanner.next();
            for (int j = 0; j < BOARD_SIZE; j++) {
                board[i][j] = row.charAt(j);
            }
        }
        return board;
    }

    /**
     * Performs the logic to determine the game state and prints the result.
     */
    private static void analyzeBoard(char[][] board) {
        int countX = 0;
        int countO = 0;
        int countEmpty = 0;

        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                if (board[i][j] == PLAYER_X) countX++;
                else if (board[i][j] == PLAYER_O) countO++;
                else if (board[i][j] == EMPTY) countEmpty++;
            }
        }

        boolean xWins = checkWin(board, PLAYER_X);
        boolean oWins = checkWin(board, PLAYER_O);

        if (isIllegalState(countX, countO, xWins, oWins)) {
            System.out.println("illegal");
        } else if (xWins) {
            System.out.println("the first player won");
        } else if (oWins) {
            System.out.println("the second player won");
        } else if (countEmpty == 0) {
            System.out.println("draw");
        } else {
            // Determine whose turn it is
            if (countX == countO) {
                System.out.println("first");
            } else {
                System.out.println("second");
            }
        }
    }

    /**
     * Validates if the current piece counts and win states are mathematically possible.
     */
    private static boolean isIllegalState(int x, int o, boolean xWins, boolean oWins) {
        // Rule 1: X must have either equal to O or one more than O
        if (x < o || x > o + 1) return true;

        // Rule 2: Both players cannot have winning configurations simultaneously
        if (xWins && oWins) return true;

        // Rule 3: If X won, it must have been X's turn that just ended (x = o + 1)
        if (xWins && x != o + 1) return true;

        // Rule 4: If O won, it must have been O's turn that just ended (x = o)
        if (oWins && x != o) return true;

        return false;
    }

    /**
     * Checks if the specified player has a winning line (row, column, or diagonal).
     */
    private static boolean checkWin(char[][] board, char player) {
        // Check rows and columns
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (checkLine(board[i][0], board[i][1], board[i][2], player)) return true;
            if (checkLine(board[0][i], board[1][i], board[2][i], player)) return true;
        }

        // Check diagonals
        if (checkLine(board[0][0], board[1][1], board[2][2], player)) return true;
        if (checkLine(board[0][2], board[1][1], board[2][0], player)) return true;

        return false;
    }

    private static boolean checkLine(char c1, char c2, char c3, char player) {
        return c1 == player && c2 == player && c3 == player;
    }
}

