/**
 * Encapsulates the logic and state of a Tic-Tac-Toe game.
 */
class TicTacToeGame {
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0';
    private static final int BOARD_SIZE = 3;

    private final char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
    private int xCount = 0;
    private int oCount = 0;

    /**
     * Constructs a game by reading the board from the provided InputReader.
     */
    public TicTacToeGame(InputReader in) {
        for (int i = 0; i < BOARD_SIZE; i++) {
            String row = in.next();
            for (int j = 0; j < BOARD_SIZE; j++) {
                char cell = row.charAt(j);
                board[i][j] = cell;
                if (cell == PLAYER_X) {
                    xCount++;
                } else if (cell == PLAYER_O) {
                    oCount++;
                }
            }
        }
    }

    /**
     * Determines the current status of the game.
     * @return A string representing the game result or current state.
     */
    public String evaluate() {
        if (isIllegal()) {
            return "illegal";
        }
        if (hasWon(PLAYER_X)) {
            return "the first player won";
        }
        if (hasWon(PLAYER_O)) {
            return "the second player won";
        }
        if (isBoardFull()) {
            return "draw";
        }
        return isFirstPlayerTurn() ? "first" : "second";
    }

    private boolean isIllegal() {
        // Rule 1: Player 2 cannot have more moves than Player 1
        if (oCount > xCount) return true;
        // Rule 2: Player 1 cannot have more than one extra move
        if (xCount > oCount + 1) return true;

        boolean xWins = hasWon(PLAYER_X);
        boolean oWins = hasWon(PLAYER_O);

        // Rule 3: Both players cannot have winning configurations
        if (xWins && oWins) return true;

        // Rule 4: If X wins, X must have taken the last turn (xCount = oCount + 1)
        if (xWins && xCount != oCount + 1) return true;

        // Rule 5: If O wins, O must have taken the last turn (xCount = oCount)
        if (oWins && xCount != oCount) return true;

        return false;
    }

    private boolean hasWon(char player) {
        // Check Rows and Columns
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (checkLine(board[i][0], board[i][1], board[i][2], player)) return true;
            if (checkLine(board[0][i], board[1][i], board[2][i], player)) return true;
        }
        // Check Diagonals
        if (checkLine(board[0][0], board[1][1], board[2][2], player)) return true;
        if (checkLine(board[0][2], board[1][1], board[2][0], player)) return true;

        return false;
    }

    private boolean checkLine(char c1, char c2, char c3, char player) {
        return c1 == player && c2 == player && c3 == player;
    }

    private boolean isBoardFull() {
        return (xCount + oCount) == (BOARD_SIZE * BOARD_SIZE);
    }

    private boolean isFirstPlayerTurn() {
        return xCount == oCount;
    }
}

/**
 * Fast I/O utility for reading input.
 */
class InputReader {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    public InputReader(InputStream stream) {
        this.reader = new BufferedReader(new InputStreamReader(stream), 32768);
    }

    public String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                throw new RuntimeException("Error reading input", e);
            }
        }
        return tokenizer.nextToken();
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }
}

import java.util.Scanner;

/**
 * A validator for Tic-Tac-Toe game states.
 * This program determines if a 3x3 board state is a win, a draw, 
 * an ongoing game, or an illegal state based on standard rules.
 */
public class TicTacToeValidator {

    private static final char X_PLAYER = 'X';
    private static final char O_PLAYER = '0';
    private static final int BOARD_SIZE = 3;

    /**
     * Represents the possible validated states of a Tic-Tac-Toe game.
     */
    public enum GameStatus {
        ILLEGAL,
        DRAW,
        X_WON,
        O_WON,
        X_NEXT_TURN,
        O_NEXT_TURN
    }

    /**
     * Encapsulates the board state and the logic to evaluate the game.
     */
    public static class TicTacToeBoard {
        private final char[][] grid;
        private int xCount = 0;
        private int oCount = 0;

        public TicTacToeBoard(char[][] grid) {
            this.grid = grid;
            calculateCounts();
        }

        private void calculateCounts() {
            for (int r = 0; r < BOARD_SIZE; r++) {
                for (int c = 0; c < BOARD_SIZE; c++) {
                    if (grid[r][c] == X_PLAYER) {
                        xCount++;
                    } else if (grid[r][c] == O_PLAYER) {
                        oCount++;
                    }
                }
            }
        }

        public GameStatus evaluate() {
            // 1. Check for basic move count validity
            // X always goes first, so oCount cannot exceed xCount, 
            // and xCount cannot exceed oCount by more than 1.
            if (oCount > xCount || xCount > oCount + 1) {
                return GameStatus.ILLEGAL;
            }

            boolean xWon = hasPlayerWon(X_PLAYER);
            boolean oWon = hasPlayerWon(O_PLAYER);

            // 2. Check for conflicting win conditions
            if (xWon && oWon) {
                return GameStatus.ILLEGAL;
            }

            // 3. Evaluate Winner-based logic
            if (xWon) {
                // If X wins, X must have made exactly one more move than O
                return (xCount == oCount + 1) ? GameStatus.X_WON : GameStatus.ILLEGAL;
            }

            if (oWon) {
                // If O wins, move counts must be equal
                return (xCount == oCount) ? GameStatus.O_WON : GameStatus.ILLEGAL;
            }

            // 4. Evaluate Ongoing or Draw states
            if (isBoardFull()) {
                return GameStatus.DRAW;
            } else {
                // The original code uses "first" for X's turn and "second" for O's turn
                return (xCount == oCount) ? GameStatus.X_NEXT_TURN : GameStatus.O_NEXT_TURN;
            }
        }

        private boolean hasPlayerWon(char player) {
            // Check rows and columns
            for (int i = 0; i < BOARD_SIZE; i++) {
                if (checkLine(grid[i][0], grid[i][1], grid[i][2], player)) return true;
                if (checkLine(grid[0][i], grid[1][i], grid[2][i], player)) return true;
            }
            // Check diagonals
            if (checkLine(grid[0][0], grid[1][1], grid[2][2], player)) return true;
            if (checkLine(grid[0][2], grid[1][1], grid[2][0], player)) return true;

            return false;
        }

        private boolean checkLine(char c1, char c2, char c3, char player) {
            return c1 == player && c2 == player && c3 == player;
        }

        private boolean isBoardFull() {
            return (xCount + oCount) == (BOARD_SIZE * BOARD_SIZE);
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] grid = new char[BOARD_SIZE][BOARD_SIZE];

        try {
            for (int i = 0; i < BOARD_SIZE; i++) {
                String line = scanner.next();
                grid[i] = line.toCharArray();
            }

            TicTacToeBoard board = new TicTacToeBoard(grid);
            printResult(board.evaluate());

        } catch (Exception e) {
            System.out.println("illegal");
        } finally {
            scanner.close();
        }
    }

    /**
     * Maps the internal GameStatus to the specific output strings required.
     */
    private static void printResult(GameStatus status) {
        switch (status) {
            case ILLEGAL:
                System.out.println("illegal");
                break;
            case DRAW:
                System.out.println("draw");
                break;
            case X_WON:
                System.out.println("the first player won");
                break;
            case O_WON:
                System.out.println("the second player won");
                break;
            case X_NEXT_TURN:
