/**
 * Represents the Tic-Tac-Toe board and provides access to its state.
 */
class TicTacToeBoard {
    private static final int SIZE = 3;
    private final char[][] grid;

    public TicTacToeBoard(char[][] grid) {
        this.grid = grid;
    }

    public char getCell(int row, int col) {
        return grid[row][col];
    }

    public int count(char player) {
        int count = 0;
        for (int i = 0; i < SIZE; i++) {
            for (int j = 0; j < SIZE; j++) {
                if (grid[i][j] == player) {
                    count++;
                }
            }
        }
        return count;
    }

    public boolean hasWinner(char player) {
        // Check rows and columns
        for (int i = 0; i < SIZE; i++) {
            if (isLineWinning(i, 0, i, 1, i, 2, player)) return true; // Row
            if (isLineWinning(0, i, 1, i, 2, i, player)) return true; // Col
        }
        // Check diagonals
        if (isLineWinning(0, 0, 1, 1, 2, 2, player)) return true;
        if (isLineWinning(0, 2, 1, 1, 2, 0, player)) return true;

        return false;
    }

    private boolean isLineWinning(int r1, int c1, int r2, int c2, int r3, int c3, char player) {
        return grid[r1][c1] == player && grid[r2][c2] == player && grid[r3][c3] == player;
    }
}

/**
 * Handles the business logic for validating the Tic-Tac-Toe game state.
 */
class TicTacToeEvaluator {
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0'; // Using '0' as per original requirement

    public GameStatus evaluate(TicTacToeBoard board) {
        int xCount = board.count(PLAYER_X);
        int oCount = board.count(PLAYER_O);
        boolean xWins = board.hasWinner(PLAYER_X);
        boolean oWins = board.hasWinner(PLAYER_O);

        // 1. Validate piece counts (X goes first, so xCount must be oCount or oCount + 1)
        if (xCount > oCount + 1 || oCount > xCount) {
            return GameStatus.ILLEGAL;
        }

        // 2. Validate win conditions
        if (xWins && oWins) {
            return GameStatus.ILLEGAL;
        }
        if (xWins && xCount != oCount + 1) {
            return GameStatus.ILLEGAL;
        }
        if (oWins && xCount != oCount) {
            return GameStatus.ILLEGAL;
        }

        // 3. Determine the winner
        if (xWins) {
            return GameStatus.FIRST_PLAYER_WON;
        }
        if (oWins) {
            return GameStatus.SECOND_PLAYER_WON;
        }

        // 4. Determine if the game is ongoing, a draw, or finished
        return determineOngoingStatus(xCount, oCount);
    }

    private GameStatus determineOngoingStatus(int xCount, int oCount) {
        if (xCount == oCount + 1 && xCount < 5) {
            return GameStatus.SECOND_TURN;
        } else if (xCount == oCount) {
            return GameStatus.FIRST_TURN;
        } else if (xCount == 5 && oCount == 4) {
            return GameStatus.DRAW;
        }
        return GameStatus.ILLEGAL;
    }
}

