/**
 * A refactored Tic-Tac-Toe analyzer.
 * Determines if a board state represents a win, draw, next turn, or illegal state.
 */
public class TicTacToe {

    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0';
    private static final int GRID_SIZE = 3;

    public enum GameResult {
        FIRST_PLAYER_WON("the first player won"),
        SECOND_PLAYER_WON("the second player won"),
        DRAW("draw"),
        FIRST_TURN("first"),
        SECOND_TURN("second"),
        ILLEGAL("illegal");

        private final String message;
        GameResult(String message) { this.message = message; }
        @Override public String toString() { return message; }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] board = new char[GRID_SIZE][GRID_SIZE];
        int countX = 0;
        int countO = 0;

        try {
            for (int i = 0; i < GRID_SIZE; i++) {
                for (int j = 0; j < GRID_SIZE; j++) {
                    if (!scanner.hasNext()) throw new Exception();
                    char symbol = scanner.next().charAt(0);
                    board[i][j] = symbol;
                    if (symbol == PLAYER_X) countX++;
                    else if (symbol == PLAYER_O) countO++;
                }
            }
            System.out.println(analyze(board, countX, countO));
        } catch (Exception e) {
            System.out.println(GameResult.ILLEGAL);
        } finally {
            scanner.close();
        }
    }

    public static GameResult analyze(char[][] board, int countX, int countO) {
        int diff = countX - countO;

        // Rule: Turn counts must be valid (X is first)
        if (diff != 0 && diff != 1) return GameResult.ILLEGAL;

        boolean xWins = hasWinner(board, PLAYER_X);
        boolean oWins = hasWinner(board, PLAYER_O);

        // Rule: Only one player can win
        if (xWins && oWins) return GameResult.ILLEGAL;

        if (xWins) {
            // Rule: If X wins, X must have just moved (countX = countO + 1)
            return (diff == 1) ? GameResult.FIRST_PLAYER_WON : GameResult.ILLEGAL;
        }

        if (oWins) {
            // Rule: If O wins, O must have just moved (countX = countO)
            return (diff == 0) ? GameResult.SECOND_PLAYER_WON : GameResult.ILLEGAL;
        }

        // No winner: check if board is full or whose turn it is
        if (countX + countO == 9) return GameResult.DRAW;
        return (diff == 0) ? GameResult.FIRST_TURN : GameResult.SECOND_TURN;
    }

    private static boolean hasWinner(char[][] board, char p) {
        for (int i = 0; i < 3; i++) {
            // Check rows and columns
            if (board[i][0] == p && board[i][1] == p && board[i][2] == p) return true;
            if (board[0][i] == p && board[1][i] == p && board[2][i] == p) return true;
        }
        // Check diagonals
        return (board[0][0] == p && board[1][1] == p && board[2][2] == p) ||
               (board[0][2] == p && board[1][1] == p && board[2][0] == p);
    }
}

