/**
 * A refactored Tic-Tac-Toe game analyzer that determines the state 
 * of a game board and predicts the next move or result.
 */
public class TicTacToe {

    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0'; // Note: Original code used digit zero

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        try {
            Board board = readBoard(scanner);
            GameResult result = GameAnalyzer.analyze(board);
            System.out.println(result.getMessage());
        } catch (Exception e) {
            System.out.println("illegal");
        } finally {
            scanner.close();
        }
    }

    private static Board readBoard(Scanner scanner) {
        Board board = new Board();
        for (int i = 0; i < 3; i++) {
            if (!scanner.hasNext()) break;
            String row = scanner.next();
            for (int j = 0; j < 3; j++) {
                board.setCell(i, j, row.charAt(j));
            }
        }
        return board;
    }

    /**
     * Represents the state of the Tic-Tac-Toe board.
     */
    static class Board {
        private static final int SIZE = 3;
        private final char[][] grid = new char[SIZE][SIZE];
        private int xCount = 0;
        private int oCount = 0;

        public void setCell(int row, int col, char symbol) {
            grid[row][col] = symbol;
            if (symbol == PLAYER_X) {
                xCount++;
            } else if (symbol == PLAYER_O) {
                oCount++;
            }
        }

        public char getCell(int row, int col) {
            return grid[row][col];
        }

        public int getXCount() { return xCount; }
        public int getOCount() { return oCount; }
        public int getSize() { return SIZE; }
    }

    /**
     * Possible outcomes of a game analysis.
     */
    enum GameResult {
        ILLEGAL("illegal"),
        X_WON("the first player won"),
        O_WON("the second player won"),
        DRAW("draw"),
        NEXT_X("first"),
        NEXT_O("second");

        private final String message;

        GameResult(String message) {
            this.message = message;
        }

        public String getMessage() {
            return message;
        }
    }

    /**
     * Service class to analyze the board state.
     */
    static class GameAnalyzer {

        public static GameResult analyze(Board board) {
            boolean xWins = checkWin(board, PLAYER_X);
            boolean oWins = checkWin(board, PLAYER_O);

            int xCount = board.getXCount();
            int oCount = board.getOCount();

            // 1. Check turn-based legality
            // X always starts, so X count must be equal to O count or O count + 1
            if (oCount > xCount || xCount > oCount + 1) {
                return GameResult.ILLEGAL;
            }

            // 2. Check win-state legality
            // Both players cannot have winning configurations
            if (xWins && oWins) {
                return GameResult.ILLEGAL;
            }

            // If X won, it must have been X's turn that just ended (X count = O count + 1)
            if (xWins && xCount != oCount + 1) {
                return GameResult.ILLEGAL;
            }

            // If O won, it must have been O's turn that just ended (X count = O count)
            if (oWins && xCount != oCount) {
                return GameResult.ILLEGAL;
            }

            // 3. Return valid results
            if (xWins) return GameResult.X_WON;
            if (oWins) return GameResult.O_WON;

            if (xCount + oCount == 9) {
                return GameResult.DRAW;
            }

            // Determine whose turn it is
            return (xCount == oCount) ? GameResult.NEXT_X : GameResult.NEXT_O;
        }

        private static boolean checkWin(Board board, char player) {
            int size = board.getSize();

            // Check rows and columns
            for (int i = 0; i < size; i++) {
                if (checkLine(board, i, 0, 0, 1, player) || // Row
                    checkLine(board, 0, i, 1, 0, player)) { // Col
                    return true;
                }
            }

            // Check diagonals
            if (checkLine(board, 0, 0, 1, 1, player) || // Main diagonal
                checkLine(board, 0, size - 1, 1, -1, player)) { // Anti-diagonal
                return true;
            }

            return false;
        }

        /**
         * Helper to check a sequence of cells.
         * @param startR Starting row
         * @param startC Starting column
         * @param dr Row direction (delta)
         * @param dc Column direction (delta)
         */
        private static boolean checkLine(Board board, int startR, int startC, int dr, int dc, char player) {
            for (int i = 0; i < 3; i++) {
                if (board.getCell(startR + i * dr, startC + i * dc) != player) {
                    return false;
                }
            }
            return true;
        }
    }
}

