/**
 * Logic engine responsible for analyzing the state of a board.
 */
class GameAnalyzer {
    private final Board board;
    private final int countX;
    private final int countO;
    private final int countDots;
    private final int winsX;
    private final int winsO;

    public GameAnalyzer(Board board) {
        this.board = board;

        // Initialize counters
        int x = 0, o = 0, dots = 0;
        for (int r = 0; r < board.getSize(); r++) {
            for (int c = 0; c < board.getSize(); c++) {
                char cell = board.getCell(r, c);
                if (cell == Board.PLAYER_X) x++;
                else if (cell == Board.PLAYER_O) o++;
                else if (cell == Board.EMPTY) dots++;
            }
        }
        this.countX = x;
        this.countO = o;
        this.countDots = dots;

        // Calculate wins
        this.winsX = countWins(Board.PLAYER_X);
        this.winsO = countWins(Board.PLAYER_O);
    }

    public GameResult analyze() {
        if (isIllegal()) {
            return GameResult.ILLEGAL;
        }
        if (winsX > 0) {
            return GameResult.FIRST_PLAYER_WON;
        }
        if (winsO > 0) {
            return GameResult.SECOND_PLAYER_WON;
        }
        if (countDots == 0) {
            return GameResult.DRAW;
        }
        if (countX == countO) {
            return GameResult.FIRST_TURN;
        }
        if (countX == countO + 1) {
            return GameResult.SECOND_TURN;
        }

        return GameResult.ILLEGAL;
    }

    private boolean isIllegal() {
        // Rule 1: Counts must be valid (X is first, so X can be equal to O or O + 1)
        if (countX < countO || countX > countO + 1) {
            return true;
        }

        // Rule 2: Both players cannot have winning lines
        if (winsX > 0 && winsO > 0) {
            return true;
        }

        // Rule 3: If X won, X must have made the last move (X = O + 1)
        if (winsX > 0 && countX == countO) {
            return true;
        }

        // Rule 4: If O won, O must have made the last move (X = O)
        if (winsO > 0 && countX == countO + 1) {
            return true;
        }

        return false;
    }

    private int countWins(char player) {
        int wins = 0;

        // Check Rows and Columns
        for (int i = 0; i < board.getSize(); i++) {
            if (checkLine(getRow(i), player)) wins++;
            if (checkLine(getCol(i), player)) wins++;
        }

        // Check Diagonals
        if (checkLine(getMainDiagonal(), player)) wins++;
        if (checkLine(getAntiDiagonal(), player)) wins++;

        return wins;
    }

    private boolean checkLine(char[] line, char player) {
        for (char c : line) {
            if (c != player) return false;
        }
        return true;
    }

    private char[] getRow(int r) {
        char[] row = new char[board.getSize()];
        for (int c = 0; c < board.getSize(); c++) row[c] = board.getCell(r, c);
        return row;
    }

    private char[] getCol(int c) {
        char[] col = new char[board.getSize()];
        for (int r = 0; r < board.getSize(); r++) col[r] = board.getCell(r, c);
        return col;
    }

    private char[] getMainDiagonal() {
        char[] diag = new char[board.getSize()];
        for (int i = 0; i < board.getSize(); i++) diag[i] = board.getCell(i, i);
        return diag;
    }

    private char[] getAntiDiagonal() {
        char[] diag = new char[board.getSize()];
        for (int i = 0; i < board.getSize(); i++) diag[i] = board.getCell(board.getSize() - 1 - i, i);
        return diag;
    }
}

