/**
 * TicTacToeValidator analyzes a 3x3 Tic-Tac-Toe board to determine if the 
 * current state is legal, if a player has won, or whose turn it is.
 */
public class TicTacToeValidator {

    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = 'O';
    private static final char EMPTY = '.';

    // Winner bitmasks
    private static final int NO_WINNER = 0;
    private static final int X_WINS = 1;
    private static final int O_WINS = 2;
    private static final int BOTH_WON = 3;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        try {
            char[][] board = readBoard(sc);
            analyzeGame(board);
        } catch (Exception e) {
            // In a production environment, implement proper error logging
        } finally {
            sc.close();
        }
    }

    /**
     * Reads the 3x3 board from the scanner.
     */
    private static char[][] readBoard(Scanner sc) {
        char[][] board = new char[3][3];
        for (int i = 0; i < 3; i++) {
            String row = sc.next();
            for (int j = 0; j < 3; j++) {
                board[i][j] = row.charAt(j);
            }
        }
        return board;
    }

    /**
     * Orchestrates the validation and output of the game state.
     */
    private static void analyzeGame(char[][] board) {
        int countX = 0;
        int countO = 0;
        int countEmpty = 0;

        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                if (board[i][j] == PLAYER_X) countX++;
                else if (board[i][j] == PLAYER_O) countO++;
                else if (board[i][j] == EMPTY) countEmpty++;
            }
        }

        int winnerBitmask = findWinner(board);

        if (isIllegal(winnerBitmask, countX, countO)) {
            System.out.println("illegal");
        } else if (winnerBitmask == X_WINS) {
            System.out.println("the first player won");
        } else if (winnerBitmask == O_WINS) {
            System.out.println("the second player won");
        } else if (countEmpty == 0) {
            System.out.println("draw");
        } else {
            // Determine whose turn it is
            if (countX == countO) {
                System.out.println("first");
            } else {
                System.out.println("second");
            }
        }
    }

    /**
     * Checks all 8 possible winning lines (rows, cols, diagonals).
     * Returns a bitmask representing the winner.
     */
    private static int findWinner(char[][] board) {
        int winner = NO_WINNER;

        // Check Rows and Columns
        for (int i = 0; i < 3; i++) {
            winner |= checkLine(board, i, 0, 0, 1); // Rows
            winner |= checkLine(board, 0, i, 1, 0); // Columns
        }

        // Check Diagonals
        winner |= checkLine(board, 0, 0, 1, 1);
        winner |= checkLine(board, 2, 0, -1, 1);

        return winner;
    }

    /**
     * Checks a specific line starting from (r, c) in direction (dr, dc).
     */
    private static int checkLine(char[][] board, int r, int c, int dr, int dc) {
        char player = board[r][c];
        if (player == EMPTY) return NO_WINNER;

        if (board[r + dr][c + dc] == player && board[r + 2 * dr][c + 2 * dc] == player) {
            return (player == PLAYER_X) ? X_WINS : O_WINS;
        }
        return NO_WINNER;
    }

    /**
     * Validates if the combination of winner and move counts is physically possible.
     */
    private static boolean isIllegal(int winner, int countX, int countO) {
        // 1. Both players cannot have winning configurations
        if (winner == BOTH_WON) return true;

        // 2. Second player cannot have more moves than the first
        if (countO > countX) return true;

        // 3. First player cannot have more than one extra move
        if (countX - countO > 1) return true;

        // 4. If X won, X must have made the last move (countX = countO + 1)
        if (winner == X_WINS && countX == countO) return true;

        // 5. If O won, O must have made the last move (countX = countO)
        if (winner == O_WINS && countX == countO + 1) return true;

        return false;
    }
}

