        PLAYER_2_WON("the second player won"),
        DRAW("draw");

        private final String message;

        GameResult(String message) {
            this.message = message;
        }

        @Override
        public String toString() {
            return message;
        }
    }

    public static void main(String[] args) {
        TicTacToeAnalyzer analyzer = new TicTacToeAnalyzer();
        analyzer.run();
    }

    /**
     * Entry point for the application logic.
     */
    public void run() {
        try (Scanner scanner = new Scanner(System.in)) {
            char[][] board = readBoard(scanner);
            System.out.println(analyze(board));
        } catch (Exception e) {
            // In a production environment, use a formal logging framework.
            System.err.println("Error processing input: " + e.getMessage());
        }
    }

    /**
     * Reads the 3x3 grid from the standard input.
     */
    private char[][] readBoard(Scanner scanner) {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i++) {
            String line = scanner.next();
            for (int j = 0; j < BOARD_SIZE; j++) {
                board[i][j] = line.charAt(j);
            }
        }
        return board;
    }

    /**
     * Analyzes the board state and returns the resulting GameResult.
     */
    private GameResult analyze(char[][] board) {
        int countX = 0;
        int countO = 0;

        // Count pieces for both players
        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                if (board[i][j] == PLAYER_X) {
                    countX++;
                } else if (board[i][j] == PLAYER_O) {
                    countO++;
                }
            }
        }

        boolean xWins = checkWinner(board, PLAYER_X);
        boolean oWins = checkWinner(board, PLAYER_O);

        // 1. Validate if the counts of X and O are even possible in a standard game
        if (isInvalidCount(countX, countO) || isInvalidWinState(xWins, oWins, countX, countO)) {
            return GameResult.ILLEGAL;
        }

        // 2. Determine the game outcome
        if (xWins) return GameResult.PLAYER_1_WON;
        if (oWins) return GameResult.PLAYER_2_WON;
        if (isBoardFull(countX, countO)) return GameResult.DRAW;

        // 3. If no one won and board is not full, return whose turn it is
        return (countX == countO) ? GameResult.FIRST_TURN : GameResult.SECOND_TURN;
    }

    /**
     * Checks if the number of pieces placed is consistent with turn-based rules.
     */
    private boolean isInvalidCount(int countX, int countO) {
        // Player X (first) must have either equal moves to O or exactly one more move.
        // It is illegal if O has more moves than X or if X has more than 1 extra move.
        return countO > countX || (countX - countO) > 1;
    }

    /**
     * Checks if the win conditions violate the sequence of play.
     */
    private boolean isInvalidWinState(boolean xWins, boolean oWins, int countX, int countO) {
        if (xWins && oWins) return true; // Both players cannot have winning lines simultaneously
        if (xWins && countX != countO + 1) return true; // X wins only if they made the last move
        if (oWins && countX != countO) return true;     // O wins only if counts are equal
        return false;
    }

    private boolean isBoardFull(int countX, int countO) {
        return (countX + countO) == (BOARD_SIZE * BOARD_SIZE);
    }

    /**
     * Checks if the specified player has a winning line (row, column, or diagonal).
     */
    private boolean checkWinner(char[][] board, char player) {
        // Check rows and columns
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (checkLine(board[i][0], board[i][1], board[i][2], player)) return true;
            if (checkLine(board[0][i], board[1][i], board[2][i], player)) return true;
        }
        // Check diagonals
        if (checkLine(board[0][0], board[1][1], board[2][2], player)) return true;
        if (checkLine(board[0][2], board[1][1], board[2][0], player)) return true;

        return false;
    }

    /**
     * Helper to check if three characters form a winning line.
     */
    private boolean checkLine(char c1, char c2, char c3, char player) {
        return c1 == player && c2 == player && c3 == player;
    }
}

import java.util.Scanner;

/**
 * A program to evaluate the state of a Tic-Tac-Toe game.
 * It determines if the game is illegal, won, drawn, or whose turn it is.
 */
public class TicTacToe {

    private static final int BOARD_SIZE = 3;
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0';

    /**
     * Represents the possible outcomes of a game evaluation.
     */
    public enum GameStatus {
        ILLEGAL,
        PLAYER_1_WON,
        PLAYER_2_WON,
        DRAW,
        PLAYER_1_TURN,
        PLAYER_2_TURN
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] boardData = new char[BOARD_SIZE][BOARD_SIZE];

        try {
            for (int i = 0; i < BOARD_SIZE; i++) {
                String line = scanner.next();
                for (int j = 0; j < BOARD_SIZE; j++) {
                    boardData[i][j] = line.charAt(j);
                }
            }
        } catch (Exception e) {
            System.out.println("illegal");
            return;
        }

        Board board = new Board(boardData);
        GameStatus status = TicTacToeEvaluator.evaluate(board);
        printStatus(status);
    }

    private static void printStatus(GameStatus status) {
        switch (status) {
            case ILLEGAL -> System.out.println("illegal");
            case PLAYER_1_WON -> System.out.println("the first player won");
            case PLAYER_2_WON -> System.out.println("the second player won");
            case DRAW -> System.out.println("draw");
            case PLAYER_1_TURN -> System.out.println("first");
            case PLAYER_2_TURN -> System.out.println("second");
        }
    }

    /**
     * Represents the Tic-Tac-Toe board grid.
     */
    static class Board {
        private final char[][] grid;

        public Board(char[][] grid) {
            this.grid = grid;
        }

        public char getCell(int row, int col) {
            return grid[row][col];
        }

        public int countMoves(char player) {
            int count = 0;
            for (int i = 0; i < BOARD_SIZE; i++) {
                for (int j = 0; j < BOARD_SIZE; j++) {
                    if (grid[i][j] == player) {
                        count++;
                    }
                }
            }
            return count;
        }

        public boolean checkWin(char player) {
            // Check rows and columns
            for (int i = 0; i < BOARD_SIZE; i++) {
                if (checkLine(grid[i][0], grid[i][1], grid[i][2], player)) return true;
                if (checkLine(grid[0][i], grid[1][i], grid[2][i], player)) return true;
            }
            // Check diagonals
            if (checkLine(grid[0][0], grid[1][1], grid[2][2], player)) return true;
            if (checkLine(grid[0][2], grid[1][1], grid[2][0], player)) return true;

            return false;
        }

        private boolean checkLine(char c1, char c2, char c3, char player) {
            return c1 == player && c2 == player && c3 == player;
        }

        public int getTotalMoves() {
            int moves = 0;
            for (int i = 0; i < BOARD_SIZE; i++) {
                for (int j = 0; j < BOARD_SIZE; j++) {
                    if (grid[i][j] == PLAYER_X || grid[i][j] == PLAYER_O) {
                        moves++;
                    }
                }
            }
            return moves;
        }
    }

    /**
     * Contains the rules logic to evaluate the board state.
     */
    static class TicTacToeEvaluator {

        public static GameStatus evaluate(Board board) {
            int xMoves = board.countMoves(PLAYER_X);
            int oMoves = board.countMoves(PLAYER_O);
            boolean xWins = board.checkWin(PLAYER_X);
            boolean oWins = board.checkWin(PLAYER_O);

            // Rule 1: Both players cannot win simultaneously
            if (xWins && oWins) return GameStatus.ILLEGAL;

            // Rule 2: Validate move counts (X starts first, so X moves must be O moves or O moves + 1)
            if (Math.abs(xMoves - oMoves) > 1 || oMoves > xMoves) {
                return GameStatus.ILLEGAL;
            }

            // Rule 3: If X wins, X must have made the last move (xMoves == oMoves + 1)
            if (xWins && xMoves != oMoves + 1) {
                return GameStatus.ILLEGAL;
            }

            // Rule 4: If O wins, O must have made the last move (xMoves == oMoves)
            if (oWins && xMoves != oMoves) {
                return GameStatus.ILLEGAL;
            }

            // Determine status based on wins, draws, or turns
            if (xWins) return GameStatus.PLAYER_1_WON;
            if (oWins) return GameStatus.PLAYER_2_WON;
            if (board.getTotalMoves() == BOARD_SIZE * BOARD_SIZE) return GameStatus.DRAW;

            // If board is not full and no one won, determine whose turn it is
            return (xMoves == oMoves) ? GameStatus.PLAYER_1_TURN : GameStatus.PLAYER_2_TURN;
        }
    }
}

import java.util.Scanner;

/**
 * Evaluates the state of a Tic-Tac-Toe game board.
 * Determines if the board is in a valid state and identifies the current status.
 */
public class TicTacToeEvaluator {

    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0';
    private static final int GRID_SIZE = 3;
    private static final int TOTAL_CELLS = GRID_SIZE * GRID_SIZE;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] board = new char[GRID_SIZE][GRID_SIZE];

        try {
            for (int i = 0; i < GRID_SIZE; i++) {
                String line = scanner.nextLine();
                if (line.length() < GRID_SIZE) {
                    System.out.println("illegal");
                    return;
                }
                board[i] = line.toCharArray();
            }
            System.out.println(evaluateGame(board));
        } catch (Exception e) {
            System.out.println("illegal");
        } finally {
            scanner.close();
        }
    }

    /**
     * Orchestrates the evaluation of the board state.
     * 
     * @param board The 3x3 Tic-Tac-Toe grid.
     * @return A string describing the game state.
     */
    private static String evaluateGame(char[][] board) {
        int countX = countMoves(board, PLAYER_X);
        int countO = countMoves(board, PLAYER_O);
        boolean winX = hasWinner(board, PLAYER_X);
        boolean winO = hasWinner(board, PLAYER_O);

        if (isIllegalState(countX, countO, winX, winO)) {
            return "illegal";
        }

        if (winX) {
            return "the first player won";
        }

        if (winO) {
            return "the second player won";
        }

        return determineTurnOrDraw(countX, countO);
    }

    /**
     * Validates if the current board configuration follows the rules of Tic-Tac-Toe.
     */
    private static boolean isIllegalState(int countX, int countO, boolean winX, boolean winO) {
        // Both players cannot have winning configurations simultaneously
        if (winX && winO) return true;

        // Player O cannot have more moves than Player X, and X cannot lead by more than 1
        if (countO > countX || (countX - countO) > 1) return true;

        // If X won, X must have made the last move (countX = countO + 1)
        if (winX && countX != countO + 1) return true;

        // If O won, O must have made the last move (countX = countO)
        if (winO && countX != countO) return true;

        return false;
    }

    /**
     * Determines if the game is ongoing (whose turn it is) or a draw.
     */
    private static String determineTurnOrDraw(int countX, int countO) {
        if (countX == countO) {
            return "first"; // It is X's turn
        } else if (countX + countO < TOTAL_CELLS) {
            return "second"; // It is O's turn
        } else {
            return "draw";
        }
    }

    /**
     * Checks if a specific player has achieved three in a row, column, or diagonal.
     */
    private static boolean hasWinner(char[][] board, char player) {
        // Check Rows and Columns
        for (int i = 0; i < GRID_SIZE; i++) {
            boolean rowWin = true;
            boolean colWin = true;
            for (int j = 0; j < GRID_SIZE; j++) {
                if (board[i][j] != player) rowWin = false;
                if (board[j][i] != player) colWin = false;
            }
            if (rowWin || colWin) return true;
        }

        // Check Diagonals
        boolean diag1 = true;
        boolean diag2 = true;
        for (int i = 0; i < GRID_SIZE; i++) {
            if (board[i][i] != player) diag1 = false;
            if (board[i][GRID_SIZE - 1 - i] != player) diag2 = false;
        }

        return diag1 || diag2;
    }

    /**
     * Counts how many times a specific player's symbol appears on the board.
     */
    private static int countMoves(char[][] board, char player) {
        int count = 0;
        for (int i = 0; i < GRID_SIZE; i++) {
            for (int j = 0; j < GRID_SIZE; j++) {
                if (board[i][j] == player) {
                    count++;
                }
            }
        }
        return count;
    }
}

