/**
 * A utility to analyze the state of a Tic-Tac-Toe game.
 * It determines if the current board state is legal, if a player has won,
 * if the game is a draw, or whose turn it is next.
 */
public class TicTacToeAnalyzer {

    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0'; // Using '0' as per original implementation
    private static final int BOARD_SIZE = 3;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNext()) {
            return;
        }

        char[][] board = readBoard(scanner);
        System.out.println(analyzeGameState(board));

        scanner.close();
    }

    /**
     * Reads a 3x3 grid from the scanner.
     */
    private static char[][] readBoard(Scanner scanner) {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i++) {
            String rowString = scanner.next();
            for (int j = 0; j < BOARD_SIZE; j++) {
                board[i][j] = rowString.charAt(j);
            }
        }
        return board;
    }

    /**
     * Analyzes the board and returns the game status string.
     */
    private static String analyzeGameState(char[][] board) {
        int xCount = countOccurrences(board, PLAYER_X);
        int oCount = countOccurrences(board, PLAYER_O);
        int xWins = countWinningLines(board, PLAYER_X);
        int oWins = countWinningLines(board, PLAYER_O);

        // 1. Validate Legality
        if (isIllegal(xCount, oCount, xWins, oWins)) {
            return "illegal";
        }

        // 2. Check for Winners
        if (xWins == 1) {
            return "the first player won";
        }
        if (oWins == 1) {
            return "the second player won";
        }

        // 3. Check for Draw or Next Turn
        if (xCount + oCount == BOARD_SIZE * BOARD_SIZE) {
            return "draw";
        }

        // Determine whose turn it is:
        // If X has more pieces, it is O's turn (second player).
        // If X and O have equal pieces, it is X's turn (first player).
        return (xCount > oCount) ? "second" : "first";
    }

    /**
     * Validates game rules to ensure the board state is possible.
     */
    private static boolean isIllegal(int xCount, int oCount, int xWins, int oWins) {
        // Rule: Player 1 (X) starts, so O cannot have more pieces than X, 
        // and X cannot have more than one extra piece.
        if (oCount > xCount || (xCount - oCount) > 1) {
            return true;
        }

        // Rule: Both players cannot have won simultaneously.
        if ((xWins + oWins) > 1) {
            return true;
        }

        // Rule: If X won, X must have exactly one more piece than O.
        if (xWins == 1 && oCount >= xCount) {
            return true;
        }

        // Rule: If O won, X and O must have an equal number of pieces.
        if (oWins == 1 && xCount > oCount) {
            return true;
        }

        return false;
    }

    /**
     * Counts how many rows, columns, or diagonals are fully occupied by the player.
     * Includes a validation check to ensure the number of pieces supports the win count.
     */
    private static int countWinningLines(char[][] board, char player) {
        int lines = 0;

        // Check Rows
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                lines++;
            }
        }

        // Check Columns
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[0][i] == player && board[1][i] == player && board[2][i] == player) {
                lines++;
            }
        }

        // Check Diagonals
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
            lines++;
        }
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
            lines++;
        }

        int playerPieceCount = countOccurrences(board, player);

        // Replicating original logic: a line is only valid if there are enough 
        // pieces to mathematically support the number of winning lines claimed.
        return (3 * lines <= playerPieceCount) ? lines : lines - 1;
    }

    private static int countOccurrences(char[][] board, char target) {
        int count = 0;
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == target) {
                    count++;
                }
            }
        }
        return count;
    }
}

import java.util.*;

/**
 * Represents the possible states and outcomes of a Tic-Tac-Toe game.
 */
enum GameState {
    FIRST_PLAYER_WON("the first player won"),
    SECOND_PLAYER_WON("the second player won"),
    DRAW("draw"),
    FIRST_PLAYER_TURN("first"),
    SECOND_PLAYER_TURN("second"),
    ILLEGAL("illegal");

    private final String message;

    GameState(String message) {
        this.message = message;
    }

    public String getMessage() {
        return message;
    }
}

/**
 * Represents the Tic-Tac-Toe board.
 */
class Board {
    public static final int SIZE = 3;
    public static final char PLAYER_X = 'X';
    public static final char PLAYER_O = '0'; // Note: original code uses zero '0'
    public static final char EMPTY = '.';

    private final char[][] grid;

    public Board(char[][] grid) {
        this.grid = grid;
    }

    public char getCell(int row, int col) {
        return grid[row][col];
    }

    public int countPlayer(char player) {
        int count = 0;
        for (int i = 0; i < SIZE; i++) {
            for (int j = 0; j < SIZE; j++) {
                if (grid[i][j] == player) {
                    count++;
                }
            }
        }
        return count;
    }

    public int getTotalOccupiedCells() {
        int count = 0;
        for (int i = 0; i < SIZE; i++) {
            for (int j = 0; j < SIZE; j++) {
                if (grid[i][j] != EMPTY) {
                    count++;
                }
            }
        }
        return count;
    }
}

/**
 * Logic engine to evaluate the state of the Tic-Tac-Toe board.
 */
class TicTacToeEvaluator {
    private static final int[][] WINNING_COMBINATIONS = {
        {0, 1, 2}, {3, 4, 5}, {6, 7, 8}, // Rows
        {0, 3, 6}, {1, 4, 7}, {2, 5, 8}, // Columns
        {0, 4, 8}, {2, 4, 6}             // Diagonals
    };

    public GameState evaluate(Board board) {
        int xCount = board.countPlayer(Board.PLAYER_X);
        int oCount = board.countPlayer(Board.PLAYER_O);

        int xWins = countWinningLines(board, Board.PLAYER_X);
        int oWins = countWinningLines(board, Board.PLAYER_O);

        // 1. Determine turn type
        // Turn 1: X's turn, Turn 2: O's turn, Turn 3: Draw (full board), Turn -1: Illegal
        int turnType = calculateTurnType(xCount, oCount, board.getTotalOccupiedCells());

        // 2. Check for illegality
        if (isIllegal(xWins, oWins, turnType)) {
            return GameState.ILLEGAL;
        }

        // 3. Determine outcome
        if (xWins > 0) return GameState.FIRST_PLAYER_WON;
        if (oWins > 0) return GameState.SECOND_PLAYER_WON;
        if (turnType == 3) return GameState.DRAW;
        if (turnType == 1) return GameState.FIRST_PLAYER_TURN;
        if (turnType == 2) return GameState.SECOND_PLAYER_TURN;

        return GameState.ILLEGAL;
    }

    private int calculateTurnType(int xCount, int oCount, int totalOccupied) {
        if (xCount == oCount) {
            return 1; // X's turn
        } else if (xCount == oCount + 1) {
            return (totalOccupied == 9) ? 3 : 2; // 3 = Draw, 2 = O's turn
        }
        return -1; // Illegal piece count
    }

    private boolean isIllegal(int xWins, int oWins, int turnType) {
        if (turnType == -1) return true;
        if (xWins > 0 && oWins > 0) return true;
        if (turnType == 1 && xWins > 0) return true; // X won, but it's X's turn again
        if (turnType == 2 && oWins > 0) return true; // O won, but it's O's turn again
        return false;
    }

    private int countWinningLines(Board board, char player) {
        int wins = 0;
        for (int[] combo : WINNING_COMBINATIONS) {
            if (checkWin(board, combo, player)) {
                wins++;
            }
        }
        return wins;
    }

    private boolean checkWin(Board board, int[] combo, char player) {
        // Convert 1D combo index to 2D coordinates
        int r1 = combo[0] / Board.SIZE, c1 = combo[0] % Board.SIZE;
        int r2 = combo[1] / Board.SIZE, c2 = combo[1] % Board.SIZE;
        int r3 = combo[2] / Board.SIZE, c3 = combo[2] % Board.SIZE;

        return board.getCell(r1, c1) == player &&
               board.getCell(r2, c2) == player &&
               board.getCell(r3, c3) == player;
    }
}

/**
 * Main entry point and I/O handler.
 */
public class Game {
    public static void main(String[] args) {
        new Game().run();
    }

    public void run() {
        try (Scanner scanner = new Scanner(System.in)) {
            Board board = readBoard(scanner);
            if (board == null) return;

            TicTacToeEvaluator evaluator = new TicTacToeEvaluator();
            GameState result = evaluator.evaluate(board);

            System.out.println(result.getMessage());
        } catch (Exception e) {
            System.out.println("illegal");
        }
    }

    private Board readBoard(Scanner scanner) {
        char[][] grid = new char[Board.SIZE][Board.SIZE];
        try {
            for (int i = 0; i < Board.SIZE; i++) {
                String line = scanner.next();
                if (line.length() != Board.SIZE) return null;
                grid[i] = line.toCharArray();
            }
            return new Board(grid);
        } catch (NoSuchElementException e) {
            return null;
        }
    }
}

