    private static final int[][] WINNING_LINES = {
            {0, 1, 2}, {3, 4, 5}, {6, 7, 8}, // Rows
            {0, 3, 6}, {1, 4, 7}, {2, 5, 8}, // Columns
            {0, 4, 8}, {2, 4, 6}             // Diagonals
    };

    /**
     * Precomputes all possible board states using a depth-first search.
     */
    public void precompute() {
        for (int i = 0; i < BOARD_SIZE; i++) {
            board[i] = EMPTY;
        }
        fill(0, PLAYER_X);
    }

    private void fill(int stateHash, int nextPlayer) {
        if (dp[stateHash] != RESULT_ILLEGAL) {
            return;
        }

        int winner = getWinner();
        if (winner != EMPTY) {
            dp[stateHash] = winner + 2; // Map to 3 (X won) or 4 (O won)
            return;
        }

        boolean hasMoves = false;
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i] == EMPTY) {
                hasMoves = true;
                break;
            }
        }

        if (!hasMoves) {
            dp[stateHash] = RESULT_DRAW;
            return;
        }

        // If game is ongoing, mark it with the current player's turn
        dp[stateHash] = nextPlayer;

        int multiplier = 1;
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i] == EMPTY) {
                board[i] = nextPlayer;
                fill(stateHash + (multiplier * nextPlayer), 3 - nextPlayer);
                board[i] = EMPTY;
            }
            multiplier *= 3;
        }
    }

    /**
     * Checks the current board for a winner.
     * @return The player constant (1 or 2) or EMPTY (0).
     */
    private int getWinner() {
        for (int[] line : WINNING_LINES) {
            int p1 = board[line[0]];
            int p2 = board[line[1]];
            int p3 = board[line[2]];
            if (p1 != EMPTY && p1 == p2 && p1 == p3) {
                return p1;
            }
        }
        return EMPTY;
    }

    /**
     * Parses the 3x3 grid from user input and converts it to a base-3 hash.
     */
    public int parseInput(Scanner scanner) {
        int stateHash = 0;
        int multiplier = 1;

        for (int i = 0; i < 3; i++) {
            String line = scanner.next();
            for (int j = 0; j < 3; j++) {
                char c = line.charAt(j);
                int val = EMPTY;
                if (c == 'X') {
                    val = PLAYER_X;
                } else if (c == '0') {
                    val = PLAYER_O;
                }
                stateHash += val * multiplier;
                multiplier *= 3;
            }
        }
        return stateHash;
    }

    /**
     * Prints the result of the game state corresponding to the given hash.
     */
    public void printResult(int stateHash) {
        int result = dp[stateHash];
        switch (result) {
            case RESULT_X_TURN:
                System.out.println("first");
                break;
            case RESULT_O_TURN:
                System.out.println("second");
                break;
            case RESULT_X_WON:
                System.out.println("the first player won");
                break;
            case RESULT_O_WON:
                System.out.println("the second player won");
                break;
            case RESULT_DRAW:
                System.out.println("draw");
                break;
            default:
                System.out.println("illegal");
                break;
        }
    }
}

