/**
 * Represents the 3x3 TicTacToe board and its state.
 */
class Board {
    public static final int SIZE = 3;
    public static final char PLAYER_X = 'X';
    public static final char PLAYER_O = '0'; // Note: Using '0' as per original requirement

    private final char[][] grid;
    private int xCount = 0;
    private int oCount = 0;

    public Board(char[][] grid) {
        this.grid = grid;
        calculateCounts();
    }

    /**
     * Factory method to create a board from user input.
     */
    public static Board fromScanner(Scanner scanner) throws Exception {
        char[][] grid = new char[SIZE][SIZE];
        for (int r = 0; r < SIZE; r++) {
            String line = scanner.nextLine();
            if (line.length() < SIZE) throw new Exception("Invalid input length");
            for (int c = 0; c < SIZE; c++) {
                grid[r][c] = line.charAt(c);
            }
        }
        return new Board(grid);
    }

    private void calculateCounts() {
        for (int r = 0; r < SIZE; r++) {
            for (int c = 0; c < SIZE; c++) {
                if (grid[r][c] == PLAYER_X) xCount++;
                else if (grid[r][c] == PLAYER_O) oCount++;
            }
        }
    }

    public boolean hasWinner(char player) {
        // Check rows and columns
        for (int i = 0; i < SIZE; i++) {
            if (checkLine(grid[i][0], grid[i][1], grid[i][2], player)) return true;
            if (checkLine(grid[0][i], grid[1][i], grid[2][i], player)) return true;
        }
        // Check diagonals
        if (checkLine(grid[0][0], grid[1][1], grid[2][2], player)) return true;
        if (checkLine(grid[0][2], grid[1][1], grid[2][0], player)) return true;

        return false;
    }

    private boolean checkLine(char c1, char c2, char c3, char player) {
        return c1 == player && c2 == player && c3 == player;
    }

    public int getXCount() { return xCount; }
    public int getOCount() { return oCount; }
    public int getTotalPieces() { return xCount + oCount; }
}

/**
 * Contains the business logic to determine the state of the game.
 */
class TicTacToeAnalyzer {
    private final Board board;

    public TicTacToeAnalyzer(Board board) {
        this.board = board;
    }

    public String analyze() {
        if (isMoveCountInvalid()) {
            return "illegal";
        }

        boolean firstWon = board.hasWinner(Board.PLAYER_X);
        boolean secondWon = board.hasWinner(Board.PLAYER_O);

        return determineOutcome(firstWon, secondWon);
    }

    private boolean isMoveCountInvalid() {
        int x = board.getXCount();
        int o = board.getOCount();
        // X is first player, O is second player. 
        // X can only be equal to O or O + 1.
        return Math.abs(x - o) > 1 || o > x;
    }

    private String determineOutcome(boolean firstWon, boolean secondWon) {
        int x = board.getXCount();
        int o = board.getOCount();

        // 1. Both cannot win
        if (firstWon && secondWon) {
            return "illegal";
        }

        // 2. Check X win validity
        if (firstWon) {
            // If X won, it must be because X just moved, so X count must be O + 1
            return (o >= x) ? "illegal" : "the first player won";
        }

        // 3. Check O win validity
        if (secondWon) {
            // If O won, it must be because O just moved, so X count must equal O count
            return (x > o) ? "illegal" : "the second player won";
        }

        // 4. No winner, check if draw or next turn
        if (board.getTotalPieces() == Board.SIZE * Board.SIZE) {
            return "draw";
        }

        return (board.getTotalPieces() % 2 == 1) ? "second" : "first";
    }
}

