/**
 * Encapsulates the logic for evaluating the state of a Tic-Tac-Toe game.
 */
class TicTacToeGame {
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0'; // Using '0' as per original implementation

    private final char[][] board;
    private final int xCount;
    private final int oCount;

    public TicTacToeGame(char[][] board) {
        this.board = board;
        int x = 0;
        int o = 0;

        // Count occurrences of each player's symbol
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                if (board[i][j] == PLAYER_X) {
                    x++;
                } else if (board[i][j] == PLAYER_O) {
                    o++;
                }
            }
        }
        this.xCount = x;
        this.oCount = o;
    }

    /**
     * Evaluates the board and returns the game status.
     * @return A string representing the game state.
     */
    public String evaluate() {
        boolean xWins = checkWin(PLAYER_X);
        boolean oWins = checkWin(PLAYER_O);

        // 1. Check fundamental legality: 
        // X (first player) must have either equal moves to O or exactly one more move.
        if (isIllegalMoveCount() || (xWins && oWins)) {
            return "illegal";
        }

        // 2. Check if the first player (X) won
        if (xWins) {
            // If X wins, X must have made the last move (xCount = oCount + 1)
            return (xCount == oCount + 1) ? "the first player won" : "illegal";
        }

        // 3. Check if the second player (O) won
        if (oWins) {
            // If O wins, the move counts must be equal (xCount = oCount)
            return (xCount == oCount) ? "the second player won" : "illegal";
        }

        // 4. No winner found, check for a draw or determine whose turn it is
        if (isBoardFull()) {
            return "draw";
        }

        // Based on move counts, determine whose turn is next
        // If xCount > oCount, it's the second player's turn
        // If xCount == oCount, it's the first player's turn
        return (xCount > oCount) ? "second" : "first";
    }

    private boolean isIllegalMoveCount() {
        return oCount > xCount || xCount > oCount + 1;
    }

    private boolean isBoardFull() {
        return (xCount + oCount) == 9;
    }

    /**
     * Checks if a specific player has a winning line.
     */
    private boolean checkWin(char player) {
        // Check all rows and columns
        for (int i = 0; i < 3; i++) {
            if (checkLine(i, 0, 0, 1, player) || // Check row i
                checkLine(0, i, 1, 0, player)) { // Check column i
                return true;
            }
        }
        // Check both diagonals
        return checkLine(0, 0, 1, 1, player) || // Main diagonal
               checkLine(0, 2, 1, -1, player);  // Anti-diagonal
    }

    /**
     * Helper to check a line of 3 cells starting from (row, col) moving in (rowStep, colStep) direction.
     */
    private boolean checkLine(int row, int col, int rowStep, int colStep, char player) {
        for (int i = 0; i < 3; i++) {
            int r = row + (i * rowStep);
            int c = col + (i * colStep);

            // Bounds check and player match check
            if (r < 0 || r >= 3 || c < 0 || c >= 3 || board[r][c] != player) {
                return false;
            }
        }
        return true;
    }
}

