/**
 * Refactored Tic-Tac-Toe Validator.
 * This program validates the legality of a Tic-Tac-Toe board state and 
 * determines the game outcome or the next player.
 */
public class Problem3B {

    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0'; // Note: Using '0' as per original requirement
    private static final char EMPTY = '.';
    private static final int BOARD_SIZE = 3;

    public static void main(String[] args) {
        try {
            TicTacToeBoard board = parseInput();
            printResult(board.evaluateGameState());
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        } catch (IllegalArgumentException e) {
            System.out.println("illegal");
        }
    }

    private static TicTacToeBoard parseInput() throws IOException {
        BufferedReader input = new BufferedReader(new InputStreamReader(System.in));
        char[][] grid = new char[BOARD_SIZE][BOARD_SIZE];

        for (int i = 0; i < BOARD_SIZE; i++) {
            String line = input.readLine();
            if (line == null || line.length() < BOARD_SIZE) {
                throw new IllegalArgumentException("Invalid input format");
            }
            for (int j = 0; j < BOARD_SIZE; j++) {
                grid[i][j] = line.charAt(j);
            }
        }
        return new TicTacToeBoard(grid);
    }

    private static void printResult(GameState state) {
        switch (state) {
            case ILLEGAL:
                System.out.println("illegal");
                break;
            case X_WON:
                System.out.println("the first player won");
                break;
            case O_WON:
                System.out.println("the second player won");
                break;
            case DRAW:
                System.out.println("draw");
                break;
            case NEXT_X:
                System.out.println("first");
                break;
            case NEXT_O:
                System.out.println("second");
                break;
        }
    }

    /**
     * Represents the possible states of the game evaluation.
     */
    enum GameState {
        X_WON, O_WON, DRAW, NEXT_X, NEXT_O, ILLEGAL
    }

    /**
     * Encapsulates the Tic-Tac-Toe board logic and rules.
     */
    static class TicTacToeBoard {
        private final char[][] grid;
        private final int xCount;
        private final int oCount;
        private final int emptyCount;

        public TicTacToeBoard(char[][] grid) {
            this.grid = grid;
            int x = 0, o = 0, empty = 0;

            for (int i = 0; i < BOARD_SIZE; i++) {
                for (int j = 0; j < BOARD_SIZE; j++) {
                    if (grid[i][j] == PLAYER_X) x++;
                    else if (grid[i][j] == PLAYER_O) o++;
                    else if (grid[i][j] == EMPTY) empty++;
                }
            }
            this.xCount = x;
            this.oCount = o;
            this.emptyCount = empty;
        }

        /**
         * Evaluates the board to determine the current status.
         * Logic follows the priority: Legality -> Win/Loss -> Draw -> Next Turn.
         */
        public GameState evaluateGameState() {
            // 1. Basic piece count legality
            if (Math.abs(xCount - oCount) > 1 || oCount > xCount) {
                return GameState.ILLEGAL;
            }

            boolean xWins = checkWin(PLAYER_X);
            boolean oWins = checkWin(PLAYER_O);

            // 2. Win condition legality
            if (xWins && oWins) return GameState.ILLEGAL;
            if (xWins && xCount == oCount) return GameState.ILLEGAL; // X moves first, must have more pieces to win
            if (oWins && xCount > oCount) return GameState.ILLEGAL; // O moves second, must have equal pieces to win

            // 3. Result detection
            if (xWins) return GameState.X_WON;
            if (oWins) return GameState.O_WON;
            if (emptyCount == 0) return GameState.DRAW;

            // 4. Turn detection
            return (xCount > oCount) ? GameState.NEXT_O : GameState.NEXT_X;
        }

        /**
         * Checks if a specific player has a winning line (row, column, or diagonal).
         */
        private boolean checkWin(char player) {
            // Check rows and columns
            for (int i = 0; i < BOARD_SIZE; i++) {
                if (checkLine(grid[i][0], grid[i][1], grid[i][2], player)) return true;
                if (checkLine(grid[0][i], grid[1][i], grid[2][i], player)) return true;
            }
            // Check diagonals
            if (checkLine(grid[0][0], grid[1][1], grid[2][2], player)) return true;
            if (checkLine(grid[0][2], grid[1][1], grid[2][0], player)) return true;

            return false;
        }

        private boolean checkLine(char c1, char c2, char c3, char player) {
            return c1 == player && c2 == player && c3 == player;
        }
    }
}

