 */
enum GameStatus {
    X_WON("the first player won"),
    O_WON("the second player won"),
    DRAW("draw"),
    X_TURN("first"),
    O_TURN("second"),
    ILLEGAL("illegal");

    private final String message;

    GameStatus(String message) {
        this.message = message;
    }

    @Override
    public String toString() {
        return this.message;
    }
}

/**
 * Evaluates the state of a 3x3 Tic-Tac-Toe board.
 */
class TicTacToeEvaluator {
    private static final int BOARD_SIZE = 3;
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0'; // Using '0' to maintain parity with original code

    private final char[][] board;

    public TicTacToeEvaluator(char[][] board) {
        if (board.length != BOARD_SIZE || board[0].length != BOARD_SIZE) {
            throw new IllegalArgumentException("Board must be 3x3");
        }
        this.board = board;
    }

    /**
     * Analyzes the board and determines the current game status.
     * 
     * @return The GameStatus representing the board state.
     */
    public GameStatus evaluate() {
        int xCount = countPlayer(PLAYER_X);
        int oCount = countPlayer(PLAYER_O);

        // 1. Validate basic turn count legality
        // X always goes first, so X count must be equal to O or O + 1
        if (xCount < oCount || xCount > oCount + 1) {
            return GameStatus.ILLEGAL;
        }

        boolean xWins = checkWin(PLAYER_X);
        boolean oWins = checkWin(PLAYER_O);

        // 2. Validate win-state legality
        // Both players cannot have winning lines
        if (xWins && oWins) {
            return GameStatus.ILLEGAL;
        }
        // If X wins, X must have made the last move (xCount = oCount + 1)
        if (xWins && xCount != oCount + 1) {
            return GameStatus.ILLEGAL;
        }
        // If O wins, O must have made the last move (xCount = oCount)
        if (oWins && xCount != oCount) {
            return GameStatus.ILLEGAL;
        }

        // 3. Determine Result
        if (xWins) return GameStatus.X_WON;
        if (oWins) return GameStatus.O_WON;
        if (isBoardFull(xCount + oCount)) return GameStatus.DRAW;

        // If no winner and board not full, determine whose turn it is
        return (xCount == oCount) ? GameStatus.X_TURN : GameStatus.O_TURN;
    }

    private int countPlayer(char player) {
        int count = 0;
        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                if (board[i][j] == player) {
                    count++;
                }
            }
        }
        return count;
    }

    private boolean isBoardFull(int totalPieces) {
        return totalPieces == BOARD_SIZE * BOARD_SIZE;
    }

    private boolean checkWin(char player) {
        // Check rows and columns
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (checkLine(board[i][0], board[i][1], board[i][2], player)) return true;
            if (checkLine(board[0][i], board[1][i], board[2][i], player)) return true;
        }

        // Check diagonals
        if (board[1][1] == player) {
            if (checkLine(board[0][0], board[1][1], board[2][2], player)) return true;
            if (checkLine(board[0][2], board[1][1], board[2][0], player)) return true;
        }

        return false;
    }

    private boolean checkLine(char c1, char c2, char c3, char player) {
        return c1 == player && c2 == player && c3 == player;
    }
}

