import java.util.Scanner;

/**
 * Represents the possible states of a Tic-Tac-Toe game.
 */
enum GameState {
    FIRST_PLAYER_WON,
    SECOND_PLAYER_WON,
    DRAW,
    FIRST_PLAYER_TURN,
    SECOND_PLAYER_TURN,
    ILLEGAL
}

/**
 * Handles the representation and data retrieval of the Tic-Tac-Toe board.
 */
class Board {
    public static final char PLAYER_X = 'X';
    public static final char PLAYER_O = '0'; // Maintaining '0' as per original requirement
    public static final char EMPTY = '.';

    private final char[][] grid;
    private int xCount = 0;
    private int oCount = 0;
    private boolean hasEmptyCell = false;

    public Board(char[][] grid) {
        this.grid = grid;
        calculateStats();
    }

    private void calculateStats() {
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                if (grid[i][j] == PLAYER_X) xCount++;
                else if (grid[i][j] == PLAYER_O) oCount++;
                else if (grid[i][j] == EMPTY) hasEmptyCell = true;
            }
        }
    }

    public char getCell(int row, int col) {
        return grid[row][col];
    }

    public int getXCount() { return xCount; }
    public int getOCount() { return oCount; }
    public boolean hasEmptyCell() { return hasEmptyCell; }

    public boolean checkWin(char player) {
        // Check Rows and Columns
        for (int i = 0; i < 3; i++) {
            if (checkLine(grid[i][0], grid[i][1], grid[i][2], player)) return true;
            if (checkLine(grid[0][i], grid[1][i], grid[2][i], player)) return true;
        }
        // Check Diagonals
        if (checkLine(grid[0][0], grid[1][1], grid[2][2], player)) return true;
        if (checkLine(grid[0][2], grid[1][1], grid[2][0], player)) return true;

        return false;
    }

    private boolean checkLine(char c1, char c2, char c3, char player) {
        return c1 == player && c2 == player && c3 == player;
    }
}

/**
 * Contains the core engine logic to evaluate the game state.
 */
class GameEvaluator {

    public GameState evaluate(Board board) {
        int diff = board.getXCount() - board.getOCount();

        // 1. Validate piece counts (X must be equal to O or O + 1)
        if (diff < 0 || diff > 1) {
            return GameState.ILLEGAL;
        }

        boolean xWon = board.checkWin(Board.PLAYER_X);
        boolean oWon = board.checkWin(Board.PLAYER_O);

        // 2. Check for win contradictions
        if (xWon && oWon) {
            return GameState.ILLEGAL;
        }

        // 3. Evaluate winner based on piece count legality
        if (xWon) {
            return (diff == 1) ? GameState.FIRST_PLAYER_WON : GameState.ILLEGAL;
        }

        if (oWon) {
            return (diff == 0) ? GameState.SECOND_PLAYER_WON : GameState.ILLEGAL;
        }

        // 4. Evaluate non-win states (Draw or Turn)
        if (board.hasEmptyCell()) {
            return (diff == 0) ? GameState.FIRST_PLAYER_TURN : GameState.SECOND_PLAYER_TURN;
        } else {
            return GameState.DRAW;
        }
    }
}

