/**
 * Represents the 3x3 Tic-Tac-Toe board.
 */
class Board {
    private final Player[][] grid = new Player[3][3];

    public Board(String[] rows) {
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                grid[i][j] = Player.fromChar(rows[i].charAt(j));
            }
        }
    }

    public Player get(int row, int col) {
        return grid[row][col];
    }

    public int count(Player player) {
        int count = 0;
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                if (grid[i][j] == player) count++;
            }
        }
        return count;
    }

    public boolean isFull() {
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                if (grid[i][j] == Player.EMPTY) return false;
            }
        }
        return true;
    }

    public boolean hasWon(Player p) {
        // Check rows and columns
        for (int i = 0; i < 3; i++) {
            if (checkLine(p, grid[i][0], grid[i][1], grid[i][2])) return true;
            if (checkLine(p, grid[0][i], grid[1][i], grid[2][i])) return true;
        }
        // Check diagonals
        if (checkLine(p, grid[0][0], grid[1][1], grid[2][2])) return true;
        if (checkLine(p, grid[0][2], grid[1][1], grid[2][0])) return true;

        return false;
    }

    private boolean checkLine(Player p, Player p1, Player p2, Player p3) {
        return p1 == p && p2 == p && p3 == p;
    }
}

/**
 * Analyzes the board to determine the current game status.
 */
class TicTacToeAnalyzer {
    private static final String ILLEGAL = "illegal";
    private static final String X_WON = "the first player won";
    private static final String O_WON = "the second player won";
    private static final String DRAW = "draw";
    private static final String NEXT_X = "first";
    private static final String NEXT_O = "second";

    public String analyze(Board board) {
        int xCount = board.count(Player.X);
        int oCount = board.count(Player.O);

        boolean xWins = board.hasWon(Player.X);
        boolean oWins = board.hasWon(Player.O);

        // 1. Validate move counts: X must be equal to O or O + 1
        if (xCount != oCount && xCount != oCount + 1) {
            return ILLEGAL;
        }

        // 2. Check for illegal dual winners
        if (xWins && oWins) {
            return ILLEGAL;
        }

        // 3. Validate X win: X must have exactly one more move than O
        if (xWins) {
            return (xCount == oCount + 1) ? X_WON : ILLEGAL;
        }

        // 4. Validate O win: X and O must have equal moves
        if (oWins) {
            return (xCount == oCount) ? O_WON : ILLEGAL;
        }

        // 5. If no winner, check if it's a draw or whose turn it is
        if (board.isFull()) {
            return DRAW;
        }

        return (xCount == oCount) ? NEXT_X : NEXT_O;
    }
}

