/**
 * A validator for Tic-Tac-Toe game states.
 * It determines if a given 3x3 board is legal, who won, or whose turn it is.
 */
public class TicTacToeValidator {

    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0'; // Note: Using '0' as per original requirement
    private static final int BOARD_SIZE = 3;

    private final char[][] board;

    /**
     * Represents the possible outcomes/states of a Tic-Tac-Toe game.
     */
    public enum GameStatus {
        ILLEGAL("illegal"),
        FIRST_PLAYER_WON("the first player won"),
        SECOND_PLAYER_WON("the second player won "), // Preserving trailing space from original
        DRAW("draw"),
        FIRST_PLAYER_TURN("first"),
        SECOND_PLAYER_TURN("second");

        private final String message;

        GameStatus(String message) {
            this.message = message;
        }

        @Override
        public String toString() {
            return message;
        }
    }

    public TicTacToeValidator(char[][] board) {
        this.board = board;
    }

    /**
     * Analyzes the board and returns the current GameStatus.
     * 
     * @return The determined GameStatus.
     */
    public GameStatus determineStatus() {
        int countX = countOccurrences(PLAYER_X);
        int countO = countOccurrences(PLAYER_O);

        boolean winX = checkWin(PLAYER_X);
        boolean winO = checkWin(PLAYER_O);

        if (!isStateLegal(countX, countO, winX, winO)) {
            return GameStatus.ILLEGAL;
        }

        if (winX) {
            return GameStatus.FIRST_PLAYER_WON;
        }

        if (winO) {
            return GameStatus.SECOND_PLAYER_WON;
        }

        if (countX + countO == BOARD_SIZE * BOARD_SIZE) {
            return GameStatus.DRAW;
        }

        // Logic for whose turn it is:
        // If X starts, X moves when countX == countO.
        // If X has one more than O, it is O's turn (the second player).
        return (countX - countO == 1) ? GameStatus.SECOND_PLAYER_TURN : GameStatus.FIRST_PLAYER_TURN;
    }

    /**
     * Validates if the board configuration follows Tic-Tac-Toe rules.
     */
    private boolean isStateLegal(int countX, int countO, boolean winX, boolean winO) {
        // Rule 1: The number of X's must be equal to O's or exactly one more than O's.
        if (countX != countO && countX - countO != 1) {
            return false;
        }
        // Rule 2: Both players cannot have winning configurations simultaneously.
        if (winX && winO) {
            return false;
        }
        // Rule 3: If X wins, X must have made the last move (countX = countO + 1).
        if (winX && countX == countO) {
            return false;
        }
        // Rule 4: If O wins, X must have the same number of moves as O (countX = countO).
        if (winO && countX > countO) {
            return false;
        }
        return true;
    }

    private int countOccurrences(char player) {
        int count = 0;
        for (int r = 0; r < BOARD_SIZE; r++) {
            for (int c = 0; c < BOARD_SIZE; c++) {
                if (board[r][c] == player) {
                    count++;
                }
            }
        }
        return count;
    }

    private boolean checkWin(char player) {
        // Check rows
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                return true;
            }
        }
        // Check columns
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[0][i] == player && board[1][i] == player && board[2][i] == player) {
                return true;
            }
        }
        // Check diagonals
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
            return true;
        }
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
            return true;
        }
        return false;
    }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            char[][] inputBoard = new char[BOARD_SIZE][BOARD_SIZE];

            for (int i = 0; i < BOARD_SIZE; i++) {
                if (scanner.hasNext()) {
                    String row = scanner.next();
                    for (int j = 0; j < BOARD_SIZE; j++) {
                        inputBoard[i][j] = row.charAt(j);
                    }
                }
            }

            TicTacToeValidator validator = new TicTacToeValidator(inputBoard);
            System.out.println(validator.determineStatus());

        } catch (Exception e) {
            // In a production environment, use a logger and handle specific exceptions.
            // For this refactor, we maintain simplicity.
        }
    }
}

