/**
 * Represents the possible outcomes of a Tic-Tac-Toe game state.
 */
enum GameResult {
    FIRST_PLAYER_WON("the first player won"),
    SECOND_PLAYER_WON("the second player won"),
    DRAW("draw"),
    FIRST_PLAYER_TURN("first"),
    SECOND_PLAYER_TURN("second"),
    ILLEGAL("illegal");

    private final String message;

    GameResult(String message) {
        this.message = message;
    }

    @Override
    public String toString() {
        return message;
    }
}

/**
 * Represents the players in the game.
 */
enum Player {
    NONE, X, O
}

/**
 * Logic engine for validating a Tic-Tac-Toe board state.
 */
class TicTacToeGame {
    private static final char SYMBOL_X = 'X';
    private static final char SYMBOL_O = 'O';
    private static final char SYMBOL_EMPTY = '.';

    private final Player[][] board = new Player[3][3];
    private int countX = 0;
    private int countO = 0;

    public TicTacToeGame(char[][] inputBoard) {
        parseBoard(inputBoard);
    }

    private void parseBoard(char[][] inputBoard) {
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                char cell = inputBoard[i][j];
                if (cell == SYMBOL_X) {
                    board[i][j] = Player.X;
                    countX++;
                } else if (cell == SYMBOL_O) {
                    board[i][j] = Player.O;
                    countO++;
                } else {
                    board[i][j] = Player.NONE;
                }
            }
        }
    }

    public GameResult evaluate() {
        if (isIllegal()) {
            return GameResult.ILLEGAL;
        }

        Player winner = getWinner();
        if (winner == Player.X) {
            return GameResult.FIRST_PLAYER_WON;
        }
        if (winner == Player.O) {
            return GameResult.SECOND_PLAYER_WON;
        }

        if (isBoardFull()) {
            return GameResult.DRAW;
        }

        return getNextTurn();
    }

    private boolean isIllegal() {
        int diff = countX - countO;
        Player winner = getWinner();

        // Rule 1: Turn difference must be 0 (O just moved) or 1 (X just moved)
        if (diff != 0 && diff != 1) {
            return true;
        }

        // Rule 2: Both players cannot have won
        // (Note: In a standard game, checkWinner returns the first winner found, 
        // but we must ensure the count consistency)
        if (winner == Player.X && diff != 1) {
            return true;
        }
        if (winner == Player.O && diff != 0) {
            return true;
        }

        return false;
    }

    private Player getWinner() {
        // Check rows, columns, and diagonals
        for (int i = 0; i < 3; i++) {
            // Rows
            if (checkLine(board[i][0], board[i][1], board[i][2])) return board[i][0];
            // Columns
            if (checkLine(board[0][i], board[1][i], board[2][i])) return board[0][i];
        }
        // Diagonals
        if (checkLine(board[0][0], board[1][1], board[2][2])) return board[0][0];
        if (checkLine(board[0][2], board[1][1], board[2][0])) return board[0][2];

        return Player.NONE;
    }

    private boolean checkLine(Player p1, Player p2, Player p3) {
        return p1 != Player.NONE && p1 == p2 && p2 == p3;
    }

    private boolean isBoardFull() {
        return (countX + countO) == 9;
    }

    private GameResult getNextTurn() {
        // If diff is 0, it's X's turn (First player)
        // If diff is 1, it's O's turn (Second player)
        return (countX - countO == 0) ? GameResult.FIRST_PLAYER_TURN : GameResult.SECOND_PLAYER_TURN;
    }
}

