/**
 * A validator for Tic-Tac-Toe game states.
 * Analyzes a 3x3 board to determine if the game is in a valid state,
 * if a player has won, if it is a draw, or whose turn it is.
 */
public class Prob003C {

    private static final int BOARD_SIZE = 3;
    private static final int TOTAL_CELLS = 9;
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0'; // Note: using '0' as per original requirement

    /**
     * Represents the possible valid and invalid states of a Tic-Tac-Toe game.
     */
    private enum GameStatus {
        FIRST_PLAYER_WON("the first player won"),
        SECOND_PLAYER_WON("the second player won"),
        DRAW("draw"),
        FIRST_TURN("first"),
        SECOND_TURN("second"),
        ILLEGAL("illegal");

        private final String message;

        GameStatus(String message) {
            this.message = message;
        }

        @Override
        public String toString() {
            return this.message;
        }
    }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            char[][] board = readBoard(scanner);
            GameStatus status = analyzeGame(board);
            System.out.println(status);
        } catch (Exception e) {
            // In a real-world scenario, handle or log specific exceptions
            System.out.println("illegal");
        }
    }

    /**
     * Reads the 3x3 board from standard input.
     */
    private static char[][] readBoard(Scanner scanner) {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i++) {
            String line = scanner.next();
            board[i] = line.toCharArray();
        }
        return board;
    }

    /**
     * Evaluates the game board and returns the resulting game status.
     */
    private static GameStatus analyzeGame(char[][] board) {
        int xCount = 0;
        int oCount = 0;

        // Count occurrences of each player's symbol
        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                if (board[i][j] == PLAYER_X) {
                    xCount++;
                } else if (board[i][j] == PLAYER_O) {
                    oCount++;
                }
            }
        }

        // 1. Rule: Turn order validation (X starts, so X must be equal to O or O + 1)
        if (!(xCount == oCount || xCount == oCount + 1)) {
            return GameStatus.ILLEGAL;
        }

        boolean xWins = checkWinner(board, PLAYER_X);
        boolean oWins = checkWinner(board, PLAYER_O);

        // 2. Rule: Both players cannot have winning configurations simultaneously
        if (xWins && oWins) {
            return GameStatus.ILLEGAL;
        }

        // 3. Rule: Handle Win states
        if (xWins) {
            // If X wins, X must have made the last move
            return (xCount == oCount + 1) ? GameStatus.FIRST_PLAYER_WON : GameStatus.ILLEGAL;
        }

        if (oWins) {
            // If O wins, X and O must have an equal number of moves
            return (xCount == oCount) ? GameStatus.SECOND_PLAYER_WON : GameStatus.ILLEGAL;
        }

        // 4. Rule: Handle non-win states (Draw or Ongoing)
        if (xCount + oCount == TOTAL_CELLS) {
            return GameStatus.DRAW;
        }

        // Determine whose turn it is
        return (xCount == oCount) ? GameStatus.FIRST_TURN : GameStatus.SECOND_TURN;
    }

    /**
     * Checks if the specified player has a winning line on the board.
     */
    private static boolean checkWinner(char[][] board, char symbol) {
        // Check Rows and Columns
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (checkLine(board[i][0], board[i][1], board[i][2], symbol)) return true;
            if (checkLine(board[0][i], board[1][i], board[2][i], symbol)) return true;
        }

        // Check Diagonals
        if (checkLine(board[0][0], board[1][1], board[2][2], symbol)) return true;
        if (checkLine(board[0][2], board[1][1], board[2][0], symbol)) return true;

        return false;
    }

    /**
     * Helper to check if three specific cells match the symbol.
     */
    private static boolean checkLine(char c1, char c2, char c3, char symbol) {
        return c1 == symbol && c2 == symbol && c3 == symbol;
    }
}

