/**
 * Represents the possible outcomes of a game state analysis.
 */
enum GameStatus {
    X_WINS("the first player won"),
    O_WINS("the second player won"),
    DRAW("draw"),
    ILLEGAL("illegal"),
    IN_PROGRESS_FIRST("first"),
    IN_PROGRESS_SECOND("second");

    private final String message;

    GameStatus(String message) {
        this.message = message;
    }

    public String getMessage() {
        return message;
    }
}

/**
 * Represents the Tic-Tac-Toe board and provides basic state information.
 */
class Board {
    private static final int SIZE = 3;
    private final Player[][] grid = new Player[SIZE][SIZE];
    private int xCount = 0;
    private int oCount = 0;
    private int emptyCount = 0;

    public void setCell(int row, int col, Player player) {
        grid[row][col] = player;
        if (player == Player.X) xCount++;
        else if (player == Player.O) oCount++;
        else emptyCount++;
    }

    public Player getCell(int row, int col) {
        return grid[row][col];
    }

    public int getXCount() { return xCount; }
    public int getOCount() { return oCount; }
    public boolean isFull() { return emptyCount == 0; }
    public int getSize() { return SIZE; }
}

/**
 * Contains the domain logic to analyze the board state.
 */
class GameAnalyzer {

    public GameStatus analyze(Board board) {
        if (isTurnCountIllegal(board)) {
            return GameStatus.ILLEGAL;
        }

        Set<Player> winners = getWinningPlayers(board);

        // If multiple players have winning lines, it's an illegal state
        if (winners.size() > 1) {
            return GameStatus.ILLEGAL;
        }

        if (winners.contains(Player.X)) {
            // If X wins, X must have made the last move (X count = O count + 1)
            return (board.getXCount() == board.getOCount() + 1) 
                ? GameStatus.X_WINS : GameStatus.ILLEGAL;
        }

        if (winners.contains(Player.O)) {
            // If O wins, O must have made the last move (X count = O count)
            return (board.getXCount() == board.getOCount()) 
                ? GameStatus.O_WINS : GameStatus.ILLEGAL;
        }

        // No winner found
        if (board.isFull()) {
            return GameStatus.DRAW;
        } else {
            return (board.getXCount() > board.getOCount()) 
                ? GameStatus.IN_PROGRESS_SECOND : GameStatus.IN_PROGRESS_FIRST;
        }
    }

    private boolean isTurnCountIllegal(Board board) {
        int diff = board.getXCount() - board.getOCount();
        // Valid turn counts: X=O (next is X) or X=O+1 (next is O)
        // Any other difference is invalid.
        return diff != 0 && diff != 1;
    }

    private Set<Player> getWinningPlayers(Board board) {
        Set<Player> winners = new HashSet<>();
        int size = board.getSize();

        // Check Rows and Columns
        for (int i = 0; i < size; i++) {
            if (checkLine(board.getCell(i, 0), board.getCell(i, 1), board.getCell(i, 2))) {
                winners.add(board.getCell(i, 0));
            }
            if (checkLine(board.getCell(0, i), board.getCell(1, i), board.getCell(2, i))) {
                winners.add(board.getCell(0, i));
            }
        }

        // Check Diagonals
        if (checkLine(board.getCell(0, 0), board.getCell(1, 1), board.getCell(2, 2))) {
            winners.add(board.getCell(0, 0));
        }
        if (checkLine(board.getCell(0, 2), board.getCell(1, 1), board.getCell(2, 0))) {
            winners.add(board.getCell(0, 2));
        }

        winners.remove(Player.NONE);
        return winners;
    }

    private boolean checkLine(Player p1, Player p2, Player p3) {
        return p1 != Player.NONE && p1 == p2 && p2 == p3;
    }
}

