    static class CycleDetector {
        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final boolean[][] visited;

        private static final int[][] DIRECTIONS = {
            {0, 1},  // Right
            {0, -1}, // Left
            {1, 0},  // Down
            {-1, 0}  // Up
        };

        public CycleDetector(char[][] grid) {
            this.grid = grid;
            this.rows = grid.length;
            this.cols = grid[0].length;
            this.visited = new boolean[rows][cols];
        }

        /**
         * Iterates through the grid to find any cycle of matching characters.
         * @return true if a cycle is found, false otherwise.
         */
        public boolean hasCycle() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (!visited[r][c]) {
                        if (dfs(r, c, -1, -1, grid[r][c])) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        /**
         * Depth First Search to detect cycles.
         * 
         * @param r current row
         * @param c current column
         * @param prevR row of the parent cell
         * @param prevC column of the parent cell
         * @param target the character we are tracing
         * @return true if a cycle is detected
         */
        private boolean dfs(int r, int c, int prevR, int prevC, char target) {
            visited[r][c] = true;

            for (int[] dir : DIRECTIONS) {
                int nextR = r + dir[0];
                int nextC = c + dir[1];

                if (isValid(nextR, nextC) && grid[nextR][nextC] == target) {
                    if (visited[nextR][nextC]) {
                        // If the neighbor is visited and is NOT the cell we just came from, 
                        // we have found a cycle.
                        if (nextR != prevR || nextC != prevC) {
                            return true;
                        }
                    } else {
                        // If not visited, continue DFS
                        if (dfs(nextR, nextC, r, c, target)) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * High-performance input reader.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
