/**
 * Encapsulates the logic for analyzing the grid for cycles.
 */
class GridAnalyzer {
    private final int[][] grid;
    private final int rows;
    private final int cols;
    private final boolean[][] visited;

    // Direction vectors for exploring adjacent cells (Up, Down, Left, Right)
    private static final int[] ROW_DIRECTIONS = {-1, 1, 0, 0};
    private static final int[] COL_DIRECTIONS = {0, 0, -1, 1};

    public GridAnalyzer(int[][] grid, int rows, int cols) {
        this.grid = grid;
        this.rows = rows;
        this.cols = cols;
        this.visited = new boolean[rows][cols];
    }

    /**
     * Iterates through every cell in the grid to find if any connected 
     * component of identical characters contains a cycle.
     * 
     * @return true if a cycle is detected, false otherwise.
     */
    public boolean containsCycle() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                // Only start a DFS if the cell is not 'empty' and hasn't been visited
                if (grid[i][j] != 0 && !visited[i][j]) {
                    if (hasCycleInComponent(i, j, -1, -1, grid[i][j])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Performs a Depth First Search to detect cycles in a component.
     * 
     * @param r Current row index
     * @param c Current column index
     * @param prevR Row index of the parent cell (to avoid immediate backtracking)
     * @param prevC Column index of the parent cell
     * @param targetColor The character value belonging to the current component
     * @return true if a cycle is detected
     */
    private boolean hasCycleInComponent(int r, int c, int prevR, int prevC, int targetColor) {
        visited[r][c] = true;

        for (int i = 0; i < 4; i++) {
            int nextR = r + ROW_DIRECTIONS[i];
            int nextC = c + COL_DIRECTIONS[i];

            if (isWithinBounds(nextR, nextC) && grid[nextR][nextC] == targetColor) {
                if (visited[nextR][nextC]) {
                    // If the neighbor is already visited and is NOT the parent cell,
                    // it means we have found a cycle.
                    if (nextR != prevR || nextC != prevC) {
                        return true;
                    }
                } else {
                    // Recursively visit the unvisited neighbor
                    if (hasCycleInComponent(nextR, nextC, r, c, targetColor)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

