/**
 * Logic for detecting cycles in a character grid.
 */
class GridCycleDetector {

    private enum VisitStatus {
        UNVISITED,
        VISITING,
        VISITED
    }

    private static final int[][] DIRECTIONS = {
        {0, 1}, {0, -1}, {1, 0}, {-1, 0}
    };

    private final char[][] grid;
    private final int rows;
    private final int cols;
    private final VisitStatus[][] visitStatus;

    public GridCycleDetector(char[][] grid) {
        this.grid = grid;
        this.rows = grid.length;
        this.cols = (rows > 0) ? grid[0].length : 0;
        this.visitStatus = new VisitStatus[rows][cols];

        for (int i = 0; i < rows; i++) {
            Arrays.fill(visitStatus[i], VisitStatus.UNVISITED);
        }
    }

    /**
     * Traverses the grid to find any cycle of identical characters.
     * @return true if a cycle is found, false otherwise.
     */
    public boolean hasCycle() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (visitStatus[i][j] == VisitStatus.UNVISITED) {
                    if (dfs(i, j, -1, -1, grid[i][j])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    private boolean dfs(int r, int c, int parentR, int parentC, char targetChar) {
        visitStatus[r][c] = VisitStatus.VISITING;

        for (int[] dir : DIRECTIONS) {
            int nextR = r + dir[0];
            int nextC = c + dir[1];

            if (isValidMove(nextR, nextC, targetChar)) {
                // If the neighbor is currently being visited and is not the parent, we found a cycle
                if (visitStatus[nextR][nextC] == VisitStatus.VISITING) {
                    if (nextR != parentR || nextC != parentC) {
                        return true;
                    }
                } 
                // If the neighbor is unvisited, continue DFS
                else if (visitStatus[nextR][nextC] == VisitStatus.UNVISITED) {
                    if (dfs(nextR, nextC, r, c, targetChar)) {
                        return true;
                    }
                }
            }
        }

        visitStatus[r][c] = VisitStatus.VISITED;
        return false;
    }

    private boolean isValidMove(int r, int c, char targetChar) {
        return r >= 0 && r < rows && 
               c >= 0 && c < cols && 
               grid[r][c] == targetChar;
    }
}

