/**
 * A program to detect if there is a cycle of identical characters 
 * within a 2D grid.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        // Read dimensions
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        // Edge case: invalid dimensions
        if (rows <= 0 || cols <= 0) {
            System.out.print("No");
            return;
        }

        // Read the grid
        int[][] grid = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            String rowData = reader.next();
            if (rowData == null) break;
            for (int j = 0; j < cols; j++) {
                // Store characters as integers for easy sign-flipping (visited marking)
                grid[i][j] = rowData.charAt(j);
            }
        }

        // Execute detection logic
        GridCycleDetector detector = new GridCycleDetector(grid);
        if (detector.hasCycle()) {
            System.out.print("Yes");
        } else {
            System.out.print("No");
        }
    }

    /**
     * Encapsulates the logic for finding a cycle of identical characters in the grid.
     */
    static class GridCycleDetector {
        private final int rows;
        private final int cols;
        private final int[][] grid;
        private boolean foundCycle = false;

        public GridCycleDetector(int[][] grid) {
            this.grid = grid;
            this.rows = grid.length;
            this.cols = grid[0].length;
        }

        /**
         * Iterates through the grid to find any cell that initiates a cycle.
         * @return true if a cycle of identical characters is found.
         */
        public boolean hasCycle() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    // Only start a DFS from unvisited cells (positive values)
                    if (grid[i][j] > 0) {
                        dfs(i, j, null, grid[i][j]);
                        if (foundCycle) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        /**
         * Depth-First Search to explore paths of identical characters.
         * 
         * @param r Current row index.
         * @param c Current column index.
         * @param prevDir The direction we just traveled from (to prevent immediate backtracking).
         * @param targetVal The character value we are currently tracing.
         */
        private void dfs(int r, int c, Direction prevDir, int targetVal) {
            if (foundCycle) return;

            // Boundary check
            if (r < 0 || r >= rows || c < 0 || c >= cols) {
                return;
            }

            // If the current cell's value is the negative of our target, 
            // it means we've revisited a cell in the current traversal path.
            if (grid[r][c] == -targetVal) {
                foundCycle = true;
                return;
            }

            // If the cell does not match our target character, stop this path.
            if (grid[r][c] != targetVal) {
                return;
            }

            // Mark the cell as visited by flipping its sign
            grid[r][c] = -targetVal;

            // Explore all four cardinal directions
            for (Direction dir : Direction.values()) {
                // Prevent the DFS from moving directly back to the previous cell
                if (prevDir != null && dir.isOpposite(prevDir)) {
                    continue;
                }

                dfs(r + dir.dr, c + dir.dc, dir, targetVal);

                if (foundCycle) {
                    return;
                }
            }
        }
    }

    /**
     * Represents the possible movement directions in the grid.
     */
    enum Direction {
        UP(-1, 0), 
        DOWN(1, 0), 
        LEFT(0, -1), 
        RIGHT(0, 1);

        final int dr, dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }

        /**
         * Checks if this direction is the direct opposite of another direction.
         */
        boolean isOpposite(Direction other) {
            return (this == UP && other == DOWN) ||
                   (this == DOWN && other == UP) ||
                   (this == LEFT && other == RIGHT) ||
                   (this == RIGHT && other == LEFT);
        }
    }

    /**
     * A fast input reader to handle large volumes of data efficiently.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            return next != null ? Integer.parseInt(next) : 0;
        }
    }
}

