            }
        }
        return false;
    }

    private boolean detectCycleFrom(int startR, int startC) {
        Deque<Node> stack = new ArrayDeque<>();

        // Initialize traversal
        visited[startR][startC] = true;
        stack.push(new Node(startR, startC, -1, -1));

        while (!stack.isEmpty()) {
            Node curr = stack.pop();

            for (int i = 0; i < 4; i++) {
                int nr = curr.r + ROW_OFFSETS[i];
                int nc = curr.c + COL_OFFSETS[i];

                if (isValidNeighbor(curr.r, curr.c, nr, nc)) {
                    // If neighbor is the parent we just came from, skip it
                    if (nr == curr.parentR && nc == curr.parentC) {
                        continue;
                    }

                    // If neighbor is already visited and isn't the parent, a cycle is detected
                    if (visited[nr][nc]) {
                        return true;
                    }

                    // Otherwise, mark visited and push to stack
                    visited[nr][nc] = true;
                    stack.push(new Node(nr, nc, curr.r, curr.c));
                }
            }
        }
        return false;
    }

    private boolean isValidNeighbor(int currR, int currC, int nr, int nc) {
        return nr >= 0 && nr < rows && 
               nc >= 0 && nc < cols && 
               grid[nr][nc] == grid[currR][currC];
    }
}

