import java.util.*;

/**
 * A utility to detect cycles in a graph derived from a character grid.
 * A cycle is defined as a path of identical adjacent characters that returns to the start.
 */
public class GridCycleDetector {

    /**
     * Represents an undirected graph using an adjacency list.
     */
    public static class Graph {
        private final int numVertices;
        private final List<List<Integer>> adjacencyList;

        public Graph(int numVertices) {
            this.numVertices = numVertices;
            this.adjacencyList = new ArrayList<>(numVertices);
            for (int i = 0; i < numVertices; i++) {
                this.adjacencyList.add(new ArrayList<>());
            }
        }

        /**
         * Adds an undirected edge between vertex u and vertex v.
         */
        public void addEdge(int u, int v) {
            validateVertex(u);
            validateVertex(v);
            adjacencyList.get(u).add(v);
            adjacencyList.get(v).add(u);
        }

        private void validateVertex(int v) {
            if (v < 0 || v >= numVertices) {
                throw new IllegalArgumentException("Vertex " + v + " is out of bounds.");
            }
        }

        /**
         * Detects if there is any cycle in the undirected graph.
         * @return true if a cycle exists, false otherwise.
         */
        public boolean hasCycle() {
            boolean[] visited = new boolean[numVertices];

            // Check every component of the graph
            for (int i = 0; i < numVertices; i++) {
                if (!visited[i]) {
                    if (containsCycleDFS(i, -1, visited)) {
                        return true;
                    }
                }
            }
            return false;
        }

        private boolean containsCycleDFS(int current, int parent, boolean[] visited) {
            visited[current] = true;

            for (int neighbor : adjacencyList.get(current)) {
                // If neighbor is not visited, recurse
                if (!visited[neighbor]) {
                    if (containsCycleDFS(neighbor, current, visited)) {
                        return true;
                    }
                } 
                // If neighbor is visited and is NOT the parent, we found a cycle
                else if (neighbor != parent) {
                    return true;
                }
            }
            return false;
        }
    }

    /**
     * Main execution logic.
     */
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            grid[i] = line.toCharArray();
        }

        // Build the graph based on grid adjacency
        Graph graph = buildGraphFromGrid(grid, rows, cols);

        // Output result
        if (graph.hasCycle()) {
            System.out.println("Yes");
        } else {
            System.out.println("No");
        }

        scanner.close();
    }

    /**
     * Transforms a 2D grid into a Graph where edges exist between 
     * adjacent cells containing the same character.
     */
    private static Graph buildGraphFromGrid(char[][] grid, int rows, int cols) {
        Graph graph = new Graph(rows * cols);

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int currentIndex = r * cols + c;

                // Check Right neighbor
                if (c + 1 < cols && grid[r][c] == grid[r][c + 1]) {
                    graph.addEdge(currentIndex, r * cols + (c + 1));
                }

                // Check Down neighbor
                if (r + 1 < rows && grid[r][c] == grid[r + 1][c]) {
                    graph.addEdge(currentIndex, (r + 1) * cols + c);
                }
            }
        }
        return graph;
    }
}

