    public static class GridCycleDetector {
        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final boolean[][] visited;

        private static final int[] ROW_DIRECTIONS = {0, 0, 1, -1};
        private static final int[] COL_DIRECTIONS = {1, -1, 0, 0};

        public GridCycleDetector(char[][] grid) {
            this.grid = grid;
            this.rows = grid.length;
            this.cols = grid[0].length;
            this.visited = new boolean[rows][cols];
        }

        /**
         * Iterates through every cell to ensure all connected components are checked.
         * @return true if a cycle is found anywhere in the grid.
         */
        public boolean hasCycle() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (!visited[r][c]) {
                        // Start DFS. -1, -1 represents the "parent" of the starting node.
                        if (dfs(r, c, -1, -1)) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        /**
         * Depth First Search to find cycles in an undirected graph represented by the grid.
         * 
         * @param r current row
         * @param c current column
         * @param prevR row of the parent node
         * @param prevC column of the parent node
         * @return true if a cycle is detected
         */
        private boolean dfs(int r, int c, int prevR, int prevC) {
            visited[r][c] = true;

            for (int i = 0; i < 4; i++) {
                int nextR = r + ROW_DIRECTIONS[i];
                int nextC = c + COL_DIRECTIONS[i];

                // Check boundaries and character match
                if (isValidMove(nextR, nextC) && grid[nextR][nextC] == grid[r][c]) {
                    if (visited[nextR][nextC]) {
                        // If the neighbor is visited and is NOT the node we just came from, it's a cycle
                        if (nextR != prevR || nextC != prevC) {
                            return true;
                        }
                    } else {
                        // Recursively visit the neighbor
                        if (dfs(nextR, nextC, r, c)) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        private boolean isValidMove(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

