/**
 * A class to detect if there is a cycle of identical characters 
 * in a 2D grid.
 */
public class CycleDetector {

    private final char[][] grid;
    private final boolean[][] visited;
    private final int rows;
    private final int cols;

    // Direction vectors for North, South, East, West
    private static final int[] ROW_OFFSETS = {-1, 1, 0, 0};
    private static final int[] COL_OFFSETS = {0, 0, -1, 1};

    public CycleDetector(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.visited = new boolean[rows][cols];
    }

    /**
     * Orchestrates the search for any cycle in the grid.
     * @return true if a cycle is found, false otherwise.
     */
    public boolean hasCycle() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (!visited[i][j]) {
                    if (containsCycle(i, j, -1, -1)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Performs Depth First Search to find a cycle.
     *
     * @param r        Current row index.
     * @param c        Current column index.
     * @param prevR    The row index of the previous cell in the path.
     * @param prevC    The column index of the previous cell in the path.
     * @return true if a cycle is detected from this cell.
     */
    private boolean containsCycle(int r, int c, int prevR, int prevC) {
        visited[r][c] = true;

        for (int i = 0; i < 4; i++) {
            int nextR = r + ROW_OFFSETS[i];
            int nextC = c + COL_OFFSETS[i];

            // 1. Check bounds
            if (isValidPosition(nextR, nextC)) {
                // 2. Only move to cells with the same character
                if (grid[nextR][nextC] == grid[r][c]) {

                    if (visited[nextR][nextC]) {
                        // 3. If visited and not the parent cell, we found a cycle
                        if (nextR != prevR || nextC != prevC) {
                            return true;
                        }
                    } else {
                        // 4. If not visited, recurse
                        if (containsCycle(nextR, nextC, r, c)) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    private boolean isValidPosition(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        scanner.nextLine(); // Consume newline

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String line = scanner.nextLine();
            grid[i] = line.toCharArray();
        }

        CycleDetector detector = new CycleDetector(n, m, grid);

        if (detector.hasCycle()) {
            System.out.println("Yes");
        } else {
            System.out.println("No");
        }

        scanner.close();
    }
}

