/**
 * A program to detect if there is a cycle of identical adjacent characters in a grid.
 */
public class Main {

    public static void main(String[] args) {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String firstLine = br.readLine();
            if (firstLine == null) return;

            String[] dimensions = firstLine.trim().split("\\s+");
            int rows = Integer.parseInt(dimensions[0]);
            int cols = Integer.parseInt(dimensions[1]);

            char[][] grid = readGrid(br, rows, cols);

            GridCycleDetector detector = new GridCycleDetector(grid);
            if (detector.hasCycle()) {
                System.out.println("Yes");
            } else {
                System.out.println("No");
            }

        } catch (IOException | NumberFormatException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Reads the grid from the input stream, skipping non-alphabetic characters.
     */
    private static char[][] readGrid(BufferedReader br, int rows, int cols) throws IOException {
        char[][] grid = new char[rows][cols];
        int totalCells = rows * cols;
        int currentCell = 0;

        while (currentCell < totalCells) {
            int character = br.read();
            if (character == -1) break; // End of stream

            char c = (char) character;
            if (Character.isAlphabetic(c)) {
                grid[currentCell / cols][currentCell % cols] = c;
                currentCell++;
            }
        }
        return grid;
    }
}

