import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * A utility to detect if a grid contains a cycle of identical adjacent characters.
 */
class CycleDetector {

    private enum VisitStatus {
        UNVISITED,
        VISITING,
        VISITED
    }

    private final char[][] grid;
    private final int rows;
    private final int cols;
    private final VisitStatus[][] visitStatus;
    private boolean cycleFound = false;

    private static final int[] ROW_OFFSETS = {0, 1, 0, -1};
    private static final int[] COL_OFFSETS = {1, 0, -1, 0};

    public CycleDetector(char[][] grid) {
        this.grid = grid;
        this.rows = grid.length;
        this.cols = grid[0].length;
        this.visitStatus = new VisitStatus[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                visitStatus[i][j] = VisitStatus.UNVISITED;
            }
        }
    }

    /**
     * Iterates through the grid to find any character cycle.
     * @return true if a cycle is found, false otherwise.
     */
    public boolean hasCycle() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (visitStatus[r][c] == VisitStatus.UNVISITED) {
                    detectCycleDFS(r, c, -1, -1, grid[r][c]);
                    if (cycleFound) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Performs Depth First Search to detect cycles of the same character.
     * 
     * @param r Current row
     * @param c Current column
     * @param prevR Row of the previous cell (to avoid immediate backtracking)
     * @param prevC Column of the previous cell
     * @param targetChar The character value we are tracing for a cycle
     */
    private void detectCycleDFS(int r, int c, int prevR, int prevC, char targetChar) {
        if (cycleFound) return;

        visitStatus[r][c] = VisitStatus.VISITING;

        for (int i = 0; i < 4; i++) {
            int nextR = r + ROW_OFFSETS[i];
            int nextC = c + COL_OFFSETS[i];

            // 1. Boundary check
            if (nextR < 0 || nextR >= rows || nextC < 0 || nextC >= cols) {
                continue;
            }

            // 2. Character match check
            if (grid[nextR][nextC] != targetChar) {
                continue;
            }

            // 3. Prevent moving back to the cell we just came from
            if (nextR == prevR && nextC == prevC) {
                continue;
            }

            // 4. Cycle detected if we hit a cell currently in the recursion stack
            if (visitStatus[nextR][nextC] == VisitStatus.VISITING) {
                cycleFound = true;
                return;
            }

            // 5. If unvisited, recurse
            if (visitStatus[nextR][nextC] == VisitStatus.UNVISITED) {
                detectCycleDFS(nextR, nextC, r, c, targetChar);
            }
        }

        // Mark as fully processed
        visitStatus[r][c] = VisitStatus.VISITED;
    }
}

public class Main {
    public static void main(String[] args) {
        try {
            BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
            String line = br.readLine();
            if (line == null) return;

            StringTokenizer st = new StringTokenizer(line);
            int rows = Integer.parseInt(st.nextToken());
            int cols = Integer.parseInt(st.nextToken());

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String rowLine = br.readLine();
                if (rowLine != null) {
                    grid[i] = rowLine.toCharArray();
                }
            }

            CycleDetector detector = new CycleDetector(grid);
            if (detector.hasCycle()) {
                System.out.println("Yes");
            } else {
                System.out.println("No");
            }

        } catch (IOException | NumberFormatException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A utility to detect if a cycle exists within a grid of characters.
 * A cycle is defined as a path of the same character that returns to a 
 * cell currently being visited, without immediately reversing direction.
 */
public class GridCycleDetector {

    private enum NodeState {
        UNVISITED,
        VISITING,
        VISITED
    }

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final NodeState[][] visited;

    private final int[] rowDirections = {1, -1, 0, 0};
    private final int[] colDirections = {0, 0, 1, -1};

    public GridCycleDetector(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.visited = new NodeState[rows][cols];
        for (int i = 0; i < rows; i++) {
            Arrays.fill(this.visited[i], NodeState.UNVISITED);
        }
    }

    /**
     * Iterates through the grid to find any cycle.
     * @return true if a cycle of identical adjacent characters is found.
     */
    public boolean hasCycle() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (visited[r][c] == NodeState.UNVISITED) {
                    if (dfs(r, c, -1, -1)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    private boolean dfs(int r, int c, int prevR, int prevC) {
        // If we encounter a node currently in the recursion stack, a cycle is detected
        if (visited[r][c] == NodeState.VISITING) {
            return true;
        }
        // If already fully processed, no need to visit again
        if (visited[r][c] == NodeState.VISITED) {
            return false;
        }

        visited[r][c] = NodeState.VISITING;

        for (int i = 0; i < 4; i++) {
            int nextR = r + rowDirections[i];
            int nextC = c + colDirections[i];

            // Check bounds, character match, and ensure we aren't just moving back to the parent
            if (isValidMove(nextR, nextC) && grid[nextR][nextC] == grid[r][c]) {
                if (nextR == prevR && nextC == prevC) {
                    continue;
                }
                if (dfs(nextR, nextC, r, c)) {
                    return true;
                }
            }
        }

        visited[r][c] = NodeState.VISITED;
        return false;
    }

    private boolean isValidMove(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    public static void main(String[] args) {
        try (FastReader reader = new FastReader(System.in);
             PrintWriter writer = new PrintWriter(System.out)) {

            int rows = reader.nextInt();
            int cols = reader.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            GridCycleDetector detector = new GridCycleDetector(rows, cols, grid);

            if (detector.hasCycle()) {
                writer.println("Yes");
            } else {
                writer.println("No");
            }

        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * Fast I/O utility class for reading input efficiently.
     */
    private static class FastReader implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            this.reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        @Override
        public void close() throws IOException {
            reader.close();
        }
    }
}

import java.util.Scanner;

/**
 * A utility to detect cycles of identical characters in a 2D grid.
 * A cycle is defined as a path of length >= 4 that returns to the starting cell.
 */
public class GridCycleDetector {

    // Direction vectors for Up, Down, Left, Right
    private static final int[] ROW_OFFSETS = {-1, 1, 0, 0};
    private static final int[] COL_OFFSETS = {0, 0, -1, 1};

    /**
     * Determines if there is a cycle of the same character in the provided grid.
     * 
     * @param grid The 2D character array to search.
     * @return true if a cycle is found, false otherwise.
     */
    public static boolean hasCycle(char[][] grid) {
        if (grid == null || grid.length == 0) {
            return false;
        }

        int rows = grid.length;
        int cols = grid[0].length;
        boolean[][] visited = new boolean[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                // Only start a DFS if the cell hasn't been processed yet
                if (!visited[i][j]) {
                    if (dfs(i, j, -1, -1, grid, visited)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Performs Depth First Search to find a back-edge in a graph of identical characters.
     *
     * @param r         Current row.
     * @param c         Current column.
     * @param parentR   Row of the cell we just came from.
     * @param parentC   Column of the cell we just came from.
     * @param grid      The input grid.
     * @param visited   Global tracker for visited cells.
     * @return true if a cycle is detected.
     */
    private static boolean dfs(int r, int c, int parentR, int parentC, char[][] grid, boolean[][] visited) {
        visited[r][c] = true;
        char color = grid[r][c];

        for (int i = 0; i < 4; i++) {
            int nextR = r + ROW_OFFSETS[i];
            int nextC = c + COL_OFFSETS[i];

            // 1. Check bounds
            if (isOutOfBounds(nextR, nextC, grid.length, grid[0].length)) {
                continue;
            }

            // 2. Only consider neighbors with the same character (color)
            if (grid[nextR][nextC] == color) {
                if (visited[nextR][nextC]) {
                    // 3. If neighbor is visited and is NOT the immediate parent, we found a cycle
                    if (nextR != parentR || nextC != parentC) {
                        return true;
                    }
                } else {
                    // 4. If neighbor is not visited, recurse
                    if (dfs(nextR, nextC, r, c, grid, visited)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    private static boolean isOutOfBounds(int r, int c, int maxR, int maxC) {
        return r < 0 || r >= maxR || c < 0 || c >= maxC;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        if (!sc.hasNextInt()) {
            return;
        }

        int rows = sc.nextInt();
        int cols = sc.nextInt();
        char[][] grid = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            String line = sc.next();
            grid[i] = line.toCharArray();
        }

        boolean result = hasCycle(grid);
        System.out.println(result ? "Yes" : "No");

        sc.close();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * A program to detect if there is a cycle of identical characters in a 2D grid.
 * A cycle is defined as a path of length >= 4 that returns to the starting cell
 * without reversing the immediate previous step.
 */
public class GridCycleDetector {

    // Direction vectors for moving Up, Down, Left, and Right
    private static final int[][] DIRECTIONS = {
        {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    private final int rowCount;
    private final int columnCount;
    private final char[][] grid;
    private final boolean[][] visited;

    public GridCycleDetector(int rowCount, int columnCount, String[] inputRows) {
        this.rowCount = rowCount;
        this.columnCount = columnCount;
        this.grid = new char[rowCount][columnCount];
        this.visited = new boolean[rowCount][columnCount];

        for (int i = 0; i < rowCount; i++) {
            this.grid[i] = inputRows[i].toCharArray();
        }
    }

    /**
     * Orchestrates the search for any cycle in the grid.
     * @return true if a cycle is found, false otherwise.
     */
    public boolean hasCycle() {
        for (int r = 0; r < rowCount; r++) {
            for (int c = 0; c < columnCount; c++) {
                if (!visited[r][c]) {
                    // Start DFS. Using -1, -1 as initial 'previous' coordinates.
                    if (detectCycleDFS(r, c, -1, -1)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Depth First Search to find cycles of identical characters.
     * 
     * @param r Current row index.
     * @param c Current column index.
     * @param prevR Row index of the cell we just came from.
     * @param prevC Column index of the cell we just came from.
     * @return true if a cycle is detected.
     */
    private boolean detectCycleDFS(int r, int c, int prevR, int prevC) {
        visited[r][c] = true;
        char currentChar = grid[r][c];

        for (int[] dir : DIRECTIONS) {
            int nextR = r + dir[0];
            int nextC = c + dir[1];

            // 1. Check bounds
            if (isWithinBounds(nextR, nextC)) {
                // 2. Ensure we aren't just moving back to the cell we just arrived from
                boolean isNotImmediateParent = (nextR != prevR || nextC != prevC);

                // 3. Check if the neighbor has the same character
                if (isNotImmediateParent && grid[nextR][nextC] == currentChar) {
                    // If neighbor is already visited, we found a cycle
                    if (visited[nextR][nextC]) {
                        return true;
                    }
                    // Otherwise, continue the DFS
                    if (detectCycleDFS(nextR, nextC, r, c)) {
                        return true;
                    }
                }
            }
        }

        return false;
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rowCount && c >= 0 && c < columnCount;
    }

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        try {
            String firstLine = reader.next();
            if (firstLine == null) return;

            int rows = Integer.parseInt(firstLine);
            int cols = reader.nextInt();

            String[] gridData = new String[rows];
            for (int i = 0; i < rows; i++) {
                gridData[i] = reader.next();
            }

            GridCycleDetector detector = new GridCycleDetector(rows, cols, gridData);

            if (detector.hasCycle()) {
                System.out.println("Yes");
            } else {
                System.out.println("No");
            }

        } catch (Exception e) {
            // In a production environment, use a logger
            e.printStackTrace();
        }
    }

    /**
     * Optimized reader for faster input processing.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            this.reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

