/**
 * Logic handler for detecting cycles within a grid of characters.
 * A cycle is defined as a path of identical characters that returns to 
 * a visited cell without immediately retracing the previous step.
 */
class GridCycleDetector {

    private final char[][] grid;
    private final int rows;
    private final int cols;
    private final boolean[][] visited;

    /**
     * Represents possible movement directions in the grid.
     */
    private enum Direction {
        UP(-1, 0), DOWN(1, 0), LEFT(0, -1), RIGHT(0, 1);

        final int dr;
        final int dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }
    }

    public GridCycleDetector(char[][] grid) {
        this.grid = grid;
        this.rows = grid.length;
        this.cols = (rows > 0) ? grid[0].length : 0;
        this.visited = new boolean[rows][cols];
    }

    /**
     * Iterates through the grid to find if any connected component of 
     * identical characters contains a cycle.
     * 
     * @return true if a cycle is found, false otherwise.
     */
    public boolean containsCycle() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (!visited[r][c]) {
                    // Start a DFS from every unvisited cell
                    if (hasCycleDFS(r, c, -1, -1, grid[r][c])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Depth-First Search to detect cycles in an undirected graph.
     * 
     * @param r Current row
     * @param c Current column
     * @param parentR Row of the cell we just came from
     * @param parentC Column of the cell we just came from
     * @param targetChar The character value we are tracking for a cycle
     * @return true if a cycle is detected
     */
    private boolean hasCycleDFS(int r, int c, int parentR, int parentC, char targetChar) {
        visited[r][c] = true;

        for (Direction dir : Direction.values()) {
            int nextR = r + dir.dr;
            int nextC = c + dir.dc;

            if (isValidMove(nextR, nextC, targetChar)) {
                if (visited[nextR][nextC]) {
                    // If the neighbor is visited and is NOT the parent, we found a cycle
                    if (nextR != parentR || nextC != parentC) {
                        return true;
                    }
                } else {
                    // Standard DFS recursion
                    if (hasCycleDFS(nextR, nextC, r, c, targetChar)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Validates if the next move is within bounds and matches the target character.
     */
    private boolean isValidMove(int r, int c, char targetChar) {
        return r >= 0 && r < rows && 
               c >= 0 && c < cols && 
               grid[r][c] == targetChar;
    }
}

import java.util.*;
