/**
 * A utility to detect if a cycle of identical characters exists in a 2D grid.
 * A cycle is defined as a path of length at least 4 that returns to its starting point.
 */
class GridCycleDetector {
    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final boolean[][] visited;

    private static final int[] ROW_OFFSET = {-1, 0, 1, 0};
    private static final int[] COL_OFFSET = {0, 1, 0, -1};

    public GridCycleDetector(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.visited = new boolean[rows][cols];
    }

    /**
     * Performs a Depth First Search to find cycles of the same character.
     * 
     * @param r Current row
     * @param c Current column
     * @param prevR Row of the parent node
     * @param prevC Column of the parent node
     * @param targetChar The character we are tracking for the cycle
     * @return true if a cycle is found
     */
    private boolean hasCycleDFS(int r, int c, int prevR, int prevC, char targetChar) {
        visited[r][c] = true;

        for (int i = 0; i < 4; i++) {
            int nr = r + ROW_OFFSET[i];
            int nc = c + COL_OFFSET[i];

            if (isValid(nr, nc) && grid[nr][nc] == targetChar) {
                if (visited[nr][nc]) {
                    // If the neighbor is visited and is NOT the parent, a cycle exists.
                    // In a grid, any such cycle is naturally length >= 4.
                    if (nr != prevR || nc != prevC) {
                        return true;
                    }
                } else {
                    if (hasCycleDFS(nr, nc, r, c, targetChar)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Iterates through the grid to find any cycle.
     * @return true if at least one cycle of identical characters is found.
     */
    public boolean detectCycle() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (!visited[i][j]) {
                    if (hasCycleDFS(i, j, -1, -1, grid[i][j])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }
}

