import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * A utility class to detect if a cycle exists in a 2D grid of characters.
 * A cycle is defined as a path of at least 4 adjacent cells containing the same character.
 */
public class GridCycleDetector {

    // Directional offsets for moving Up, Down, Left, and Right
    private static final int[] ROW_OFFSETS = {1, -1, 0, 0};
    private static final int[] COL_OFFSETS = {0, 0, 1, -1};

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final boolean[][] visited;

    /**
     * Initializes the detector with the provided grid.
     *
     * @param rows The number of rows in the grid.
     * @param cols The number of columns in the grid.
     * @param grid The 2D character array representing the grid.
     */
    public GridCycleDetector(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.visited = new boolean[rows][cols];
    }

    /**
     * Scans the entire grid to find if any cycle of identical characters exists.
     *
     * @return true if a cycle is found, false otherwise.
     */
    public boolean containsCycle() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                // If the cell hasn't been visited, start a DFS from here
                if (!visited[r][c]) {
                    if (hasCycleDFS(r, c, -1, -1, grid[r][c])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Performs a Depth-First Search to detect cycles in an undirected graph structure.
     *
     * @param r            The current row index.
     * @param c            The current column index.
     * @param prevR        The row index of the parent node in the DFS tree.
     * @param prevC        The column index of the parent node in the DFS tree.
     * @param targetChar   The character value required to stay within the current path.
     * @return true if a cycle is detected, false otherwise.
     */
    private boolean hasCycleDFS(int r, int c, int prevR, int prevC, char targetChar) {
        visited[r][c] = true;

        for (int i = 0; i < 4; i++) {
            int nextR = r + ROW_OFFSETS[i];
            int nextC = c + COL_OFFSETS[i];

            // Ensure neighbor is within bounds and matches the target character
            if (isWithinBounds(nextR, nextC) && grid[nextR][nextC] == targetChar) {

                if (visited[nextR][nextC]) {
                    // If the neighbor is visited and is NOT the parent, we found a cycle.
                    // In a square grid, any such cycle must have a length of at least 4.
                    if (nextR != prevR || nextC != prevC) {
                        return true;
                    }
                } else {
                    // If not visited, continue the DFS
                    if (hasCycleDFS(nextR, nextC, r, c, targetChar)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Validates if the given coordinates are within the grid boundaries.
     */
    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();

        try {
            String rowStr = scanner.next();
            if (rowStr == null) return;

            int n = Integer.parseInt(rowStr);
