/**
 * Problem: Determine if there is a connected component of identical 
 * characters in a grid with a size of at least 3.
 */
public class FoxandCeil2 {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();

        try {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = scanner.next().toCharArray();
            }

            FoxAndCeilSolver solver = new FoxAndCeilSolver(grid, rows, cols);
            if (solver.hasComponentOfSizeAtLeastThree()) {
                System.out.println("Yes");
            } else {
                System.out.println("No");
            }
        } catch (Exception e) {
            // In a real-world scenario, use a logger.
            e.printStackTrace();
        }
    }

    /**
     * Handles the core logic of the Fox and Ceil problem.
     */
    static class FoxAndCeilSolver {
        private final char[][] grid;
        private final int rows;
        private final int cols;
        private final boolean[][] visited;

        // Direction vectors for traversing Up, Down, Left, Right
        private static final int[] DR = {-1, 1, 0, 0};
        private static final int[] DC = {0, 0, -1, 1};

        public FoxAndCeilSolver(char[][] grid, int rows, int cols) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
            this.visited = new boolean[rows][cols];
        }

        /**
         * Iterates through the grid to find if any component meets the size requirement.
         * @return true if a component of size >= 3 is found.
         */
        public boolean hasComponentOfSizeAtLeastThree() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (!visited[r][c]) {
                        int componentSize = calculateComponentSize(r, c, grid[r][c]);
                        if (componentSize >= 3) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        /**
         * Performs a DFS to calculate the size of a connected component.
         */
        private int calculateComponentSize(int r, int c, char targetChar) {
            visited[r][c] = true;
            int size = 1;

            for (int i = 0; i < 4; i++) {
                int nextR = r + DR[i];
                int nextC = c + DC[i];

                if (isValidMove(nextR, nextC, targetChar)) {
                    size += calculateComponentSize(nextR, nextC, targetChar);
                }
            }
            return size;
        }

        private boolean isValidMove(int r, int c, char targetChar) {
            return r >= 0 && r < rows && 
                   c >= 0 && c < cols && 
                   !visited[r][c] && 
                   grid[r][c] == targetChar;
        }
    }

    /**
     * Optimized scanner for fast I/O operations.
     */
    static class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
