        } finally {
            writer.close();
        }
    }

    /**
     * Logic for detecting cycles of identical adjacent characters in a 2D grid.
     */
    static class GridCycleDetector {
        private static final int[] ROW_DIRECTIONS = {1, 0, -1, 0};
        private static final int[] COL_DIRECTIONS = {0, 1, 0, -1};

        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final boolean[][] visited;
        private boolean cycleFound;

        public GridCycleDetector(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            this.visited = new boolean[rows][cols];
            this.cycleFound = false;
        }

        /**
         * Orchestrates the DFS traversal to find any cycle in the grid.
         * @return true if a cycle of identical characters is found.
         */
        public boolean hasCycle() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (!visited[i][j]) {
                        performDFS(i, j, -1, -1, grid[i][j]);
                        if (cycleFound) return true;
                    }
                }
            }
            return false;
        }

        /**
         * Depth First Search to detect cycles.
         * 
         * @param r Current row
         * @param c Current column
         * @param parentR Row of the cell we just came from
         * @param parentC Column of the cell we just came from
         * @param targetChar The character we are tracking for the cycle
         */
        private void performDFS(int r, int c, int parentR, int parentC, char targetChar) {
            visited[r][c] = true;

            for (int k = 0; k < 4; k++) {
                int nextR = r + ROW_DIRECTIONS[k];
                int nextC = c + COL_DIRECTIONS[k];

                if (isValidMove(nextR, nextC)) {
                    // If the neighbor is the same character and already visited
                    if (visited[nextR][nextC] && grid[nextR][nextC] == targetChar) {
                        // Check if it's not just the cell we literally just came from
                        if (nextR != parentR || nextC != parentC) {
                            cycleFound = true;
                            return;
                        }
                    } else if (grid[nextR][nextC] == targetChar && !visited[nextR][nextC]) {
                        performDFS(nextR, nextC, r, c, targetChar);
                        if (cycleFound) return;
                    }
                }
            }
        }

        private boolean isValidMove(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * A high-performance custom scanner for reading input from an InputStream.
     */
    static class FastScanner {
        private static final int BUFFER_SIZE = 4096;
        private final BufferedInputStream inputStream;
        private final byte[] buffer = new byte[BUFFER_SIZE];
        private int bufferIndex = 0;
        private int bytesRead = 0;

        public FastScanner(InputStream inputStream) {
            this.inputStream = new BufferedInputStream(inputStream);
        }

        /**
         * Reads a single byte from the buffer.
         * @return The byte value or -1 if EOF.
         */
        private int readByte() {
            if (bufferIndex >= bytesRead) {
                bufferIndex = 0;
                try {
                    bytesRead = inputStream.read(buffer);
                } catch (IOException e) {
                    return -1;
                }
                if (bytesRead <= 0) return -1;
            }
            return buffer[bufferIndex++] & 0xFF;
        }

        public int nextInt() {
            int c = readByte();
            while (c != -1 && isWhiteSpace(c)) {
                c = readByte();
            }
            if (c == -1) return 0;

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }

            int result = 0;
            while (c != -1 && !isWhiteSpace(c)) {
                if (c >= '0' && c <= '9') {
                    result = result * 10 + (c - '0');
                }
                c = readByte();
            }
            return result * sign;
        }

        public String nextString() {
            int c = readByte();
            while (c != -1 && isWhiteSpace(c)) {
                c = readByte();
            }
            if (c == -1) return "";

            StringBuilder sb = new StringBuilder();
            while (c != -1 && !isWhiteSpace(c)) {
                sb.append((char) c);
                c = readByte();
            }
            return sb.toString();
        }

        private boolean isWhiteSpace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

