         * @param c current column
         * @param prevR row of the parent cell
         * @param prevC column of the parent cell
         */
        private void dfs(int r, int c, int prevR, int prevC) {
            visited[r][c] = true;

            for (int i = 0; i < 4; i++) {
                int nextR = r + DR[i];
                int nextC = c + DC[i];

                if (isValid(nextR, nextC) && grid[nextR][nextC] == grid[r][c]) {
