import java.util.Scanner;

/**
 * Problem: Fox and Two Dots (Codeforces 510B)
 * Goal: Find if there exists a path of at least 4 cells of the same color in a grid.
 */
public class FoxAndTwoDots {

    // Direction vectors for moving Up, Down, Left, Right
    private static final int[] ROW_DIRECTIONS = {-1, 1, 0, 0};
    private static final int[] COL_DIRECTIONS = {0, 0, -1, 1};
    private static final int REQUIRED_PATH_LENGTH = 4;

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final boolean[][] visited;

    public FoxAndTwoDots(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.visited = new boolean[rows][cols];
    }

    /**
     * Orchestrates the search by starting a DFS from every cell in the grid.
     * @return true if a valid path is found, false otherwise.
     */
    public boolean solve() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (findPath(r, c, 1)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * A backtracking Depth-First Search to find a path of the same character.
     * 
     * @param r current row
     * @param c current column
     * @param length current path length
     * @return true if a path of REQUIRED_PATH_LENGTH is reached
     */
    private boolean findPath(int r, int c, int length) {
        // Base case: If we've reached the required length, a path is found.
        if (length == REQUIRED_PATH_LENGTH) {
            return true;
        }

        // Mark the current cell as visited to avoid cycles in the current path
        visited[r][c] = true;

        // Explore all 4 adjacent directions
        for (int i = 0; i < 4; i++) {
            int nextR = r + ROW_DIRECTIONS[i];
            int nextC = c + COL_DIRECTIONS[i];

            if (isValidMove(nextR, nextC, grid[r][c])) {
                if (findPath(nextR, nextC, length + 1)) {
                    return true;
                }
            }
        }

        // Backtrack: Unmark the current cell so it can be part of other paths
        visited[r][c] = false;
        return false;
    }

    /**
     * Validates if the next move is within bounds, matches the color, and hasn't been visited.
     */
    private boolean isValidMove(int r, int c, char targetColor) {
        return r >= 0 && r < rows && 
               c >= 0 && c < cols && 
               !visited[r][c] && 
               grid[r][c] == targetColor;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int n = scanner.nextInt();
        int m = scanner.nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String rowString = scanner.next();
            for (int j = 0; j < m; j++) {
                grid[i][j] = rowString.charAt(j);
            }
        }

        FoxAndTwoDots solver = new FoxAndTwoDots(n, m, grid);

        if (solver.solve()) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }
}

import java.util.*;
import java.io.*;

/**
 * Detects if there is a cycle of identical adjacent characters in a 2D grid.
 */
public class GridCycleDetector {

    private enum VisitStatus {
        UNVISITED,
        VISITING,
        VISITED
    }

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final VisitStatus[][] visitedStatus;

    private static final int[][] DIRECTIONS = {
            {0, 1},  // Right
            {0, -1}, // Left
            {1, 0},  // Down
            {-1, 0}  // Up
    };

    public GridCycleDetector(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.visitedStatus = new VisitStatus[rows][cols];
        for (int i = 0; i < rows; i++) {
            Arrays.fill(visitedStatus[i], VisitStatus.UNVISITED);
        }
    }

    /**
     * Orchestrates the cycle detection process.
     * @return true if a cycle is found, false otherwise.
     */
    public boolean hasCycle() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (visitedStatus[r][c] == VisitStatus.UNVISITED) {
                    if (dfs(r, c, -1, -1, grid[r][c])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Performs Depth First Search to find cycles in the graph of identical characters.
     */
    private boolean dfs(int r, int c, int prevR, int prevC, char targetChar) {
        // If we encounter a node currently in the recursion stack, a cycle is detected
        if (visitedStatus[r][c] == VisitStatus.VISITING) {
            return true;
        }
        // If we encounter a node already fully processed, no cycle exists in this branch
        if (visitedStatus[r][c] == VisitStatus.VISITED) {
            return false;
        }

        visitedStatus[r][c] = VisitStatus.VISITING;

        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            if (isValidNeighbor(nr, nc, prevR, prevC, targetChar)) {
                if (dfs(nr, nc, r, c, targetChar)) {
                    return true;
                }
            }
        }

        visitedStatus[r][c] = VisitStatus.VISITED;
        return false;
    }

    private boolean isValidNeighbor(int nr, int nc, int prevR, int prevC, char targetChar) {
        return nr >= 0 && nr < rows &&
               nc >= 0 && nc < cols &&
               grid[nr][nc] == targetChar &&
               !(nr == prevR && nc == prevC);
    }

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = reader.nextInt();
            int m = reader.nextInt();
            char[][] grid = new char[n][m];

            for (int i = 0; i < n; i++) {
                String rowStr = reader.next();
                grid[i] = rowStr.toCharArray();
            }

            GridCycleDetector detector = new GridCycleDetector(n, m, grid);
            if (detector.hasCycle()) {
                out.println("Yes");
            } else {
                out.println("No");
            }
        } catch (Exception e) {
            // In a production environment, use a proper logger
            e.printStackTrace();
        } finally {
            out.close();
        }
    }

    /**
     * Utility class for fast input reading.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream inputStream) {
            br = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

