     */
    private boolean dfs(int r, int c, int parentRow, int parentCol, char targetChar) {
        visited[r][c] = true;

        for (int[] direction : DIRECTIONS) {
            int nextRow = r + direction[0];
            int nextCol = c + direction[1];

            // Check if the neighbor is within bounds and matches the target character
            if (isWithinBounds(nextRow, nextCol) && grid[nextRow][nextCol] == targetChar) {

                if (visited[nextRow][nextCol]) {
                    // If the neighbor is already visited and is NOT the parent, we found a cycle
                    if (nextRow != parentRow || nextCol != parentCol) {
                        return true;
                    }
                } else {
                    // If not visited, recurse
                    if (dfs(nextRow, nextCol, r, c, targetChar)) {
                        return true;
                    }
                }
            }
        }

        return false;
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

