/**
 * A utility class to detect if a grid contains a cycle of identical adjacent characters.
 * A cycle is defined as a path of at least 4 cells of the same character that returns 
 * to a previously visited cell without immediately backtracking.
 */
public class GridCycleDetector {

    // Directional vectors for North, South, East, and West movements
    private static final int[][] DIRECTIONS = {
        {0, 1},  // Right
        {0, -1}, // Left
        {1, 0},  // Down
        {-1, 0}  // Up
    };

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        char[][] grid = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            String rowString = scanner.next();
            grid[i] = rowString.toCharArray();
        }

        if (hasAnyCycle(grid, rows, cols)) {
            System.out.println("Yes");
        } else {
            System.out.println("No");
        }

        scanner.close();
    }

    /**
     * Iterates through the grid to find any connected component of identical 
     * characters that contains a cycle.
     *
     * @param grid The input character grid.
     * @param rows Number of rows in the grid.
     * @param cols Number of columns in the grid.
     * @return true if at least one cycle is found.
     */
    private static boolean hasAnyCycle(char[][] grid, int rows, int cols) {
        boolean[][] visited = new boolean[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                // If the cell hasn't been visited yet, it's a new component.
                // We start a DFS from here to look for cycles within this component.
                if (!visited[i][j]) {
                    if (detectCycleDFS(grid, visited, i, j, -1, -1, grid[i][j], rows, cols)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Performs a Depth First Search to detect cycles in an undirected graph representation of the grid.
     *
     * @param grid     The character grid.
     * @param visited  Tracking array for visited cells.
     * @param r        Current row index.
     * @param c        Current column index.
     * @param prevR    Row index of the parent cell (the cell we just came from).
     * @param prevC    Column index of the parent cell.
     * @param target   The specific character value we are tracing.
     * @param rows     Total rows in the grid.
     * @param cols     Total columns in the grid.
     * @return true if a cycle is detected.
     */
    private static boolean detectCycleDFS(char[][] grid, boolean[][] visited, int r, int c,
                                          int prevR, int prevC, char target, int rows, int cols) {
        visited[r][c] = true;

        for (int[] direction : DIRECTIONS) {
            int nextR = r + direction[0];
            int nextC = c + direction[1];

            // Ensure the neighbor is within bounds and matches the target character
            if (isWithinBounds(nextR, nextC, rows, cols) && grid[nextR][nextC] == target) {
                if (visited[nextR][nextC]) {
                    // If the neighbor is already visited and is NOT the cell we just came from,
                    // then we have found a cycle.
                    if (nextR != prevR || nextC != prevC) {
                        return true;
                    }
                } else {
                    // If the neighbor hasn't been visited, continue the DFS
                    if (detectCycleDFS(grid, visited, nextR, nextC, r, c, target, rows, cols)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Validates if the given coordinates are within the grid boundaries.
     */
    private static boolean isWithinBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

