/**
 * Logic handler for detecting cycles of the same character in a 2D grid.
 */
class GridCycleDetector {
    private final char[][] grid;
    private final int rows;
    private final int cols;
    private final boolean[][] visited;
    private boolean hasCycleFound;

    // Direction vectors for Up, Down, Left, Right
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public GridCycleDetector(char[][] grid) {
        this.grid = grid;
        this.rows = grid.length;
        this.cols = grid[0].length;
        this.visited = new boolean[rows][cols];
        this.hasCycleFound = false;
    }

    /**
     * Initiates the cycle detection process across the entire grid.
     * @return true if a cycle of identical characters is found, false otherwise.
     */
    public boolean hasSameColorCycle() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (!visited[i][j]) {
                    performDfs(i, j, -1, -1);
                    if (hasCycleFound) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Depth First Search to detect cycles in an undirected graph structure.
     * 
     * @param r current row
     * @param c current column
     * @param prevR the row index of the cell we just came from
     * @param prevC the column index of the cell we just came from
     */
    private void performDfs(int r, int c, int prevR, int prevC) {
        visited[r][c] = true;

        for (int i = 0; i < 4; i++) {
            int nextR = r + DR[i];
            int nextC = c + DC[i];

            if (isValidMove(nextR, nextC, r, c, prevR, prevC)) {
                if (visited[nextR][nextC]) {
                    // If the neighbor is already visited and it's not the parent, a cycle exists
                    hasCycleFound = true;
                    return;
                } else {
                    performDfs(nextR, nextC, r, c);
                    if (hasCycleFound) {
                        return;
                    }
                }
            }
        }
    }

    /**
     * Validates if the move to the neighbor is within bounds, matches the current character,
     * and is not a move back to the immediate parent.
     */
    private boolean isValidMove(int nr, int nc, int r, int c, int prevR, int prevC) {
        // Boundary check
        if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) {
            return false;
        }

        // Must be the same character
        if (grid[nr][nc] != grid[r][c]) {
            return false;
        }

        // Must not be the cell we just came from (prevents trivial 2-node cycles)
        if (nr == prevR && nc == prevC) {
            return false;
        }

        return true;
    }
}

