     * @return true if a cycle is found, false otherwise.
     */
    public boolean hasCycle() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (!visited[r][c]) {
                    // Start a DFS from every unvisited cell
                    if (dfs(r, c, -1, -1, grid[r][c])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Depth First Search to detect a cycle in an undirected graph representation of the grid.
     * 
     * @param r Current row
     * @param c Current column
     * @param prevR Row of the parent cell (to prevent moving backward)
     * @param prevC Column of the parent cell
     * @param targetChar The character value we are tracking for the cycle
     * @return true if a cycle is detected
     */
    private boolean dfs(int r, int c, int prevR, int prevC, char targetChar) {
        visited[r][c] = true;

        for (int i = 0; i < 4; i++) {
            int nextR = r + DR[i];
            int nextC = c + DC[i];

            // Check bounds and character match
            if (isValidMove(nextR, nextC, targetChar)) {
                // If the next cell is visited and is NOT the cell we just came from, 
                // we have found a cycle.
                if (visited[nextR][nextC]) {
                    if (nextR != prevR || nextC != prevC) {
                        return true;
                    }
                } else {
                    // Standard recursive DFS step
                    if (dfs(nextR, nextC, r, c, targetChar)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    private boolean isValidMove(int r, int c, char targetChar) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] == targetChar;
    }

