     * @param parentR    Row index of the predecessor cell.
     * @param parentC    Column index of the predecessor cell.
     * @return true if a cycle is found, false otherwise.
     */
    private boolean dfs(int r, int c, int parentR, int parentC) {
        visited[r][c] = true;

        for (int[] dir : DIRECTIONS) {
            int nextR = r + dir[0];
            int nextC = c + dir[1];

            // Check if neighbor is within bounds and has the same character
            if (isWithinBounds(nextR, nextC) && grid[r][c] == grid[nextR][nextC]) {
