                    // If the neighbor is already visited and is NOT the parent, a cycle exists.
                    if (nextR != parentR || nextC != parentC) {
                        return true;
                    }
                } else {
                    // Recurse into the unvisited neighbor
                    if (dfs(nextR, nextC, r, c)) {
                        return true;
                    }
                }
