class GridAnalyzer {
    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final boolean[][] visited;

    private static final int[][] DIRECTIONS = {
        {-1, 0}, {1, 0}, {0, -1}, {0, 1} // Up, Down, Left, Right
    };

    public GridAnalyzer(char[][] grid) {
        this.grid = grid;
        this.rows = grid.length;
        this.cols = grid[0].length;
        this.visited = new boolean[rows][cols];
    }

    /**
     * Scans the grid to find if any color component contains at least two junctions.
     * A junction is defined as a cell having 2 or more neighbors of the same color.
     */
    public boolean hasSpecialComponent() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                // We only start a search from a junction that hasn't been visited yet
                if (!visited[r][c] && isJunction(r, c)) {
                    if (dfsSearchForSecondJunction(r, c, grid[r][c], true)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Performs a DFS to explore a component and detect if it contains multiple junctions.
     * 
     * @param r Current row
     * @param c Current column
     * @param color The character color of the current component
     * @param isStartingNode True if this is the very first node of the DFS
     * @return true if a second junction is found within the same component
     */
    private boolean dfsSearchForSecondJunction(int r, int c, char color, boolean isStartingNode) {
        visited[r][c] = true;

        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            if (isValid(nr, nc) && grid[nr][nc] == color) {
                if (isJunction(nr, nc)) {
                    // If we encounter a neighbor that is a junction and it's not the start node, 
                    // we have found a component with multiple junctions.
                    if (!isStartingNode) {
                        return true;
                    }

                    // If the neighbor is a junction but we haven't visited it yet,
                    // we continue DFS. The 'isStartingNode' logic in the original 
                    // code effectively checks for the existence of another junction.
                    if (!visited[nr][nc]) {
                        if (dfsSearchForSecondJunction(nr, nc, color, false)) {
                            return true;
                        }
                    }
                } else if (!visited[nr][nc]) {
                    // Regular node in the component
                    if (dfsSearchForSecondJunction(nr, nc, color, false)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Determines if a cell is a "junction" (has 2 or more neighbors of the same color).
     */
    private boolean isJunction(int r, int c) {
        char color = grid[r][c];
        int neighborCount = 0;

        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            if (isValid(nr, nc) && grid[nr][nc] == color) {
                neighborCount++;
            }
        }
        return neighborCount >= 2;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

