     */
    public boolean hasComponentOfSizeAtLeast(int minSize) {
        // Reset visited array for a fresh analysis
        for (boolean[] row : visited) {
            Arrays.fill(row, false);
        }

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (!visited[r][c]) {
                    int componentSize = countComponentSize(r, c, grid[r][c]);
                    if (componentSize >= minSize) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Performs a Depth First Search to count the size of a connected component.
     *
     * @param r Current row index.
     * @param c Current column index.
     * @param targetChar The character value we are grouping by.
     * @return The total number of connected cells with the targetChar.
     */
    private int countComponentSize(int r, int c, char targetChar) {
        visited[r][c] = true;
        int size = 1;

        for (int[] dir : DIRECTIONS) {
            int nextRow = r + dir[0];
            int nextCol = c + dir[1];

            if (isValidMove(nextRow, nextCol, targetChar)) {
                size += countComponentSize(nextRow, nextCol, targetChar);
            }
        }
        return size;
    }

    private boolean isValidMove(int r, int c, char targetChar) {
        return r >= 0 && r < rows && 
               c >= 0 && c < cols && 
               !visited[r][c] && 
               grid[r][c] == targetChar;
    }
}

/**
 * Utility class for fast input parsing.
 */
class FastReader {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    public FastReader(InputStream stream) {
        reader = new BufferedReader(new InputStreamReader(stream));
        tokenizer = null;
    }

    public String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                throw new RuntimeException("Error reading input", e);
            }
        }
        return tokenizer.nextToken();
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }

    public long nextLong() {
        return Long.parseLong(next());
    }

    public double nextDouble() {
        return Double.parseDouble(next());
    }
}

