/**
 * A utility to detect if a grid contains a cycle of identical adjacent characters.
 */
class GridCycleDetector {

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final boolean[][] visited;

    // Direction vectors for traversing Up, Down, Left, Right
    private static final int[][] DIRECTIONS = {
        {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    public GridCycleDetector(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.visited = new boolean[rows][cols];
    }

    /**
     * Scans the grid to find if any connected component of identical characters forms a cycle.
     * 
     * @return true if a cycle is found, false otherwise.
     */
    public boolean hasCycle() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (!visited[r][c]) {
                    // Start a DFS from every unvisited cell
                    if (detectCycleDFS(r, c, -1, -1, grid[r][c])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Depth First Search to detect cycles in the grid.
     * 
     * @param r current row
     * @param c current column
     * @param parentR row of the previous cell (to prevent immediate backtracking)
     * @param parentC column of the previous cell
     * @param targetChar the character we are currently tracing
     * @return true if a cycle is detected
     */
    private boolean detectCycleDFS(int r, int c, int parentR, int parentC, char targetChar) {
        visited[r][c] = true;

        for (int[] dir : DIRECTIONS) {
            int nextR = r + dir[0];
            int nextC = c + dir[1];

            if (isValidMove(nextR, nextC, targetChar)) {
                if (visited[nextR][nextC]) {
                    // If the neighbor is visited and is NOT the parent, a cycle exists
                    if (nextR != parentR || nextC != parentC) {
                        return true;
                    }
                } else {
                    // Recursive DFS call
                    if (detectCycleDFS(nextR, nextC, r, c, targetChar)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    private boolean isValidMove(int r, int c, char targetChar) {
        return r >= 0 && r < rows && 
               c >= 0 && c < cols && 
               grid[r][c] == targetChar;
    }
}

