import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Queue;
import java.util.StringTokenizer;

/**
 * FoxDots identifies if there is a cycle of identical characters in a 2D grid.
 * A cycle is defined as a path of length 4 or more where all characters are the same
 * and we return to the starting point without immediate backtracking.
 */
public class FoxDots {

    // Direction vectors for moving Up, Down, Left, Right
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public static void main(String[] args) {
        FastReader reader = new FastReader();

        int rows = reader.nextInt();
        int cols = reader.nextInt();

        if (rows <= 0 || cols <= 0) {
            System.out.println("No");
            return;
        }

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = reader.next().toCharArray();
        }

        if (hasCycle(rows, cols, grid)) {
            System.out.println("Yes");
        } else {
            System.out.println("No");
        }
    }

    /**
     * Iterates through the grid to find any unvisited components and checks for cycles.
     */
    private static boolean hasCycle(int rows, int cols, char[][] grid) {
        boolean[][] visited = new boolean[rows][cols];

        // To detect a cycle in an undirected graph, we must track the parent 
        // of each node to ensure we don't immediately "backtrack" to the caller.
        int[][] parentRow = new int[rows][cols];
        int[][] parentCol = new int[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (!visited[i][j]) {
                    if (bfsCheckForCycle(i, j, rows, cols, grid, visited, parentRow, parentCol)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Performs a Breadth-First Search to detect a cycle within a component of identical characters.
     */
    private static boolean bfsCheckForCycle(int startR, int startC, int rows, int cols, 
                                            char[][] grid, boolean[][] visited, 
                                            int[][] parentRow, int[][] parentCol) {

        Queue<int[]> queue = new ArrayDeque<>();

        // Initialize start node
        visited[startR][startC] = true;
        parentRow[startR][startC] = -1; // No parent for the root
        parentCol[startR][startC] = -1;
        queue.add(new int[]{startR, startC});

        char targetChar = grid[startR][startC];

        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            int r = curr[0];
            int c = curr[1];

            for (int i = 0; i < 4; i++) {
                int nr = r + DR[i];
                int nc = c + DC[i];

                // Check boundaries and character match
                if (isValidMove(nr, nc, rows, cols) && grid[nr][nc] == targetChar) {

                    // If the neighbor is the parent we just came from, skip it (not a cycle)
                    if (nr == parentRow[r][c] && nc == parentCol[r][c]) {
                        continue;
                    }

                    // If the neighbor is already visited and not the parent, a cycle is found
                    if (visited[nr][nc]) {
                        return true;
                    }

                    // Otherwise, mark visited, set parent, and add to queue
                    visited[nr][nc] = true;
                    parentRow[nr][nc] = r;
                    parentCol[nr][nc] = c;
                    queue.add(new int[]{nr, nc});
                }
            }
        }
        return false;
    }

    private static boolean isValidMove(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Fast I/O helper class.
     */
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

