/**
 * A utility to detect cycles in a grid of characters where a cycle 
 * is defined as a path of adjacent cells containing the same character.
 */
public class GridCycleDetector {

    private static final int[][] DIRECTIONS = {
        {0, 1},  // Right
        {0, -1}, // Left
        {1, 0},  // Down
        {-1, 0}  // Up
    };

    private final char[][] grid;
    private final int rows;
    private final int cols;
    private final boolean[][] visited;

    public GridCycleDetector(char[][] grid) {
        this.grid = grid;
        this.rows = grid.length;
        this.cols = grid[0].length;
        this.visited = new boolean[rows][cols];
    }

    /**
     * Scans the grid to find if any character forms a cycle.
     * @return true if a cycle of identical adjacent characters is found.
     */
    public boolean hasCycle() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (!visited[r][c]) {
                    // Start a DFS from every unvisited cell
                    // We pass -1, -1 as the parent coordinates for the starting cell
                    if (containsCycle(r, c, -1, -1)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Depth First Search to detect cycles in an undirected graph representation of the grid.
     * 
     * @param r Current row
     * @param c Current column
     * @param parentR Row index of the cell we just came from
     * @param parentC Column index of the cell we just came from
     * @return true if a cycle is detected
     */
    private boolean containsCycle(int r, int c, int parentR, int parentC) {
        visited[r][c] = true;

        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            if (isValidMove(nr, nc) && grid[nr][nc] == grid[r][c]) {
                if (visited[nr][nc]) {
                    // If the neighbor is already visited and is NOT the parent,
                    // we have found a cycle.
                    if (nr != parentR || nc != parentC) {
                        return true;
                    }
                } else {
                    // Recursive DFS call
                    if (containsCycle(nr, nc, r, c)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    private boolean isValidMove(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Entry point for the application.
     */
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        char[][] grid = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            String rowString = scanner.next();
            grid[i] = rowString.toCharArray();
        }

        GridCycleDetector detector = new GridCycleDetector(grid);

        if (detector.hasCycle()) {
            System.out.println("Yes");
        } else {
            System.out.println("No");
        }

        scanner.close();
    }
}

