        this.cols = in.nextInt();
        this.grid = new char[rows][cols];
        this.visited = new boolean[rows][cols];

        for (int i = 0; i < rows; i++) {
            String line = in.next();
            if (line != null) {
                grid[i] = line.toCharArray();
            }
        }
    }

    /**
     * Iterates through the grid to find any cycle of identical adjacent characters.
     * @return true if a cycle is found, false otherwise.
     */
    public boolean hasCycle() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (!visited[i][j]) {
                    // Start a DFS from every unvisited cell
                    if (dfs(i, j, -1, -1, grid[i][j])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Standard DFS for detecting cycles in an undirected graph.
     * 
     * @param r Current row
     * @param c Current column
     * @param prevR Row of the parent node (to prevent moving immediately back)
     * @param prevC Column of the parent node
     * @param targetChar The character we are currently tracing
     * @return true if a cycle is detected
     */
    private boolean dfs(int r, int c, int prevR, int prevC, char targetChar) {
        visited[r][c] = true;

        for (int[] dir : DIRECTIONS) {
            int nextR = r + dir[0];
            int nextC = c + dir[1];

            if (isWithinBounds(nextR, nextC) && grid[nextR][nextC] == targetChar) {
                // If the neighbor is visited and is NOT the parent, we found a cycle
                if (visited[nextR][nextC]) {
                    if (nextR != prevR || nextC != prevC) {
                        return true;
                    }
                    continue;
                }

                if (dfs(nextR, nextC, r, c, targetChar)) {
                    return true;
                }
            }
        }
        return false;
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

