/**
 * A utility class to detect if a 2D grid contains any adjacent 
 * cells with identical characters.
 */
public class GridSearch {

    // Possible movements: Right, Down, Left, Up
    private static final int[][] DIRECTIONS = {
        {0, 1}, 
        {1, 0}, 
        {0, -1}, 
        {-1, 0}
    };

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            scanner.nextLine(); // Consume the remaining newline

            char[][] grid = readGrid(scanner, rows, cols);

            if (hasAdjacentDuplicates(grid)) {
                System.out.println("Yes");
            } else {
                System.out.println("No");
            }
        } catch (Exception e) {
            // In a production environment, use a logger here.
            // For this exercise, we terminate gracefully on input errors.
        }
    }

    /**
     * Reads the grid dimensions and characters from the input stream.
     *
     * @param scanner The input scanner.
     * @param rows    Number of rows to read.
     * @param cols    Number of columns per row.
     * @return A 2D character array representing the grid.
     */
    private static char[][] readGrid(Scanner scanner, int rows, int cols) {
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            if (scanner.hasNextLine()) {
                String line = scanner.nextLine();
                for (int j = 0; j < cols && j < line.length(); j++) {
                    grid[i][j] = line.charAt(j);
                }
            }
        }
        return grid;
    }

    /**
     * Scans the grid to determine if any two adjacent cells (horizontal or vertical)
     * contain the same character.
     *
     * @param grid The 2D grid to search.
     * @return true if adjacent identical characters are found, false otherwise.
     */
    public static boolean hasAdjacentDuplicates(char[][] grid) {
        if (grid == null || grid.length == 0) {
            return false;
        }

        int rows = grid.length;
        int cols = grid[0].length;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (checkNeighbors(grid, r, c, rows, cols)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Checks the four cardinal neighbors of a specific cell.
     *
     * @param grid The 2D grid.
     * @param r    Current row index.
     * @param c    Current column index.
     * @param rows Total rows in grid.
     * @param cols Total columns in grid.
     * @return true if any neighbor has the same character as grid[r][c].
     */
    private static boolean checkNeighbors(char[][] grid, int r, int c, int rows, int cols) {
        char currentChar = grid[r][c];

        for (int[] direction : DIRECTIONS) {
            int nextR = r + direction[0];
            int nextC = c + direction[1];

            if (isWithinBounds(nextR, nextC, rows, cols)) {
                if (grid[nextR][nextC] == currentChar) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Validates if the given coordinates are within the grid boundaries.
     */
    private static boolean isWithinBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

