/**
 * Logic for detecting cycles in a 2D character grid.
 */
class CycleDetector {
    private final FastReader reader;
    private static final int[][] DIRECTIONS = {
        {1, 0}, {0, 1}, {-1, 0}, {0, -1}
    };

    public CycleDetector(FastReader reader) {
        this.reader = reader;
    }

    public void solve() throws IOException {
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        if (rows <= 0 || cols <= 0) {
            System.out.println("No");
            return;
        }

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = reader.nextChars(cols);
        }

        boolean hasCycle = findCycleInGrid(rows, cols, grid);
        System.out.println(hasCycle ? "Yes" : "No");
    }

    private boolean findCycleInGrid(int rows, int cols, char[][] grid) {
        boolean[][] visited = new boolean[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                // If not visited, start a DFS to find a cycle in this connected component
                if (!visited[i][j]) {
                    if (hasCycleDFS(i, j, -1, -1, grid[i][j], visited, grid)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Depth First Search to detect a cycle of the same character.
     * 
     * @param r Current row
     * @param c Current column
     * @param prevR Row of the parent cell
     * @param prevC Column of the parent cell
     * @param targetChar The character we are tracing
     * @param visited Visited matrix
     * @param grid The character grid
     * @return true if a cycle is detected
     */
    private boolean hasCycleDFS(int r, int c, int prevR, int prevC, char targetChar, 
                                boolean[][] visited, char[][] grid) {
        // If we encounter a cell already visited in the current traversal, a cycle exists
        if (visited[r][c]) {
            return true;
        }

        visited[r][c] = true;

        for (int[] dir : DIRECTIONS) {
            int nextR = r + dir[0];
            int nextC = c + dir[1];

            // Boundary check and "not parent" check
            if (isValid(nextR, nextC, visited.length, visited[0].length) 
                && !(nextR == prevR && nextC == prevC) 
                && grid[nextR][nextC] == targetChar) {

                if (hasCycleDFS(nextR, nextC, r, c, targetChar, visited, grid)) {
                    return true;
                }
            }
        }

        return false;
    }

    private boolean isValid(int r, int c, int maxR, int maxC) {
        return r >= 0 && r < maxR && c >= 0 && c < maxC;
    }
}

/**
 * Optimized reader for fast character/integer input.
 */
class FastReader {
    private final InputStream in;
    private final byte[] buffer = new byte[1024];
    private int pointer = 0;
    private int bufferLength = 0;

    public FastReader(InputStream in) {
        this.in = in;
    }

    private int readByte() throws IOException {
        if (pointer >= bufferLength) {
            pointer = 0;
            bufferLength = in.read(buffer);
            if (bufferLength <= 0) return -1;
        }
        return buffer[pointer++] & 0xFF;
    }

    private boolean isSpaceChar(int b) {
        return b == ' ' || b == '\n' || b == '\r' || b == '\t' || b == -1;
    }

    public int nextInt() throws IOException {
        int b = skipSpaces();
        boolean negative = false;
        if (b == '-') {
            negative = true;
            b = readByte();
        }
        int res = 0;
        while (b >= '0' && b <= '9') {
            res = res * 10 + (b - '0');
            b = readByte();
        }
        return negative ? -res : res;
    }

    public char[] nextChars(int n) throws IOException {
        skipSpaces();
        char[] res = new char[n];
        for (int i = 0; i < n; i++) {
            int b = readByte();
            if (b == -1) break;
            res[i] = (char) b;
        }
        return res;
    }

    private int skipSpaces() throws IOException {
        int b = readByte();
        while (b != -1 && isSpaceChar(b)) {
            b = readByte();
        }
        return b;
    }
}

