/**
 * A utility to detect if a cycle of identical characters exists in a 2D grid.
 */
public class GridCycleFinder {

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final boolean[][] visited;

    // Direction vectors for Up, Down, Left, Right
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public GridCycleFinder(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.visited = new boolean[rows][cols];
    }

    /**
     * Orchestrates the search for a cycle across the entire grid.
     * @return true if at least one cycle of identical characters is found.
     */
    public boolean hasCycle() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                // If not visited, start a new DFS to explore this connected component
                if (!visited[r][c]) {
                    if (dfs(r, c, -1, -1, grid[r][c])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Depth First Search to find a cycle in a component of identical characters.
     * 
     * @param r Current row
     * @param c Current column
     * @param prevR Row of the parent cell (to avoid immediate backtracking)
     * @param prevC Column of the parent cell
     * @param targetChar The character value we are tracking for the cycle
     * @return true if a cycle is detected
     */
    private boolean dfs(int r, int c, int prevR, int prevC, char targetChar) {
        visited[r][c] = true;

        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];

            // 1. Check bounds
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
                // 2. Check if the neighbor is the same character
                if (grid[nr][nc] == targetChar) {
                    // 3. If neighbor is visited and is NOT the parent, we found a cycle
                    if (visited[nr][nc]) {
                        if (nr != prevR || nc != prevC) {
                            return true;
                        }
                    } else {
                        // 4. If neighbor is not visited, recurse
                        if (dfs(nr, nc, r, c, targetChar)) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String line = scanner.next();
            for (int j = 0; j < m; j++) {
                grid[i][j] = line.charAt(j);
            }
        }

        GridCycleFinder finder = new GridCycleFinder(n, m, grid);

        if (finder.hasCycle()) {
            System.out.println("Yes");
        } else {
            System.out.println("No");
        }

        scanner.close();
    }
}

