            // Check if we hit an asterisk (existing or newly placed)
            if (grid[r][c] == '*') {
                // If the asterisk is at the starting position and the path is long enough, pattern found
                if (r == startR && c == startC && depth >= 4) {
                    patternFound = true;
                }
                return;
            }

            // Only continue if the cell matches the character we are searching for
            if (grid[r][c] != searched) {
                return;
            }

            // Mark current cell as visited by changing it to '*'
            grid[r][c] = '*';
            changed.add(new int[]{r, c});

            // Explore all 4 adjacent neighbors
            for (int i = 0; i < 4; i++) {
                dfs(r + dr[i], c + dc[i], startR, startC, searched, depth + 1, changed);
                if (patternFound) {
                    return; // Early exit if pattern found
                }
            }
        }

        /**
         * Restores the modified cells to their original character.
         */
        private void undoChanges(List<int[]> changed, char originalChar) {
            for (int[] cell : changed) {
                grid[cell[0]][cell[1]] = originalChar;
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Queue;
import java.util.StringTokenizer;

/**
 * A utility to detect if any character in a 2D grid forms a cycle 
 * by connecting adjacent identical characters.
 */
public class GridCycleDetector {

    // Direction vectors for navigating Up, Down, Left, Right
    private static final int[][] DIRECTIONS = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

    /**
     * Represents a state in the BFS traversal.
     * @param r Current row index
     * @param c Current column index
     * @param pr Parent row index (to prevent immediate backtracking)
     * @param pc Parent column index
     */
    private record Node(int r, int c, int pr, int pc) {}

    /**
     * Scans the grid to find if any connected component of identical characters forms a cycle.
     *
     * @param rows Total rows in the grid
     * @param cols Total columns in the grid
     * @param grid The 2D character array
     * @return "Yes" if a cycle is found, "No" otherwise.
     */
    public String detectCycle(int rows, int cols, char[][] grid) {
        boolean[][] visited = new boolean[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                // If this cell hasn't been part of a previous traversal, start a new one
                if (!visited[r][c]) {
                    if (hasCycleInComponent(r, c, rows, cols, grid, visited)) {
                        return "Yes";
                    }
                }
            }
        }
        return "No";
    }

    /**
     * Performs an iterative BFS to find a cycle within a component of identical characters.
     */
    private boolean hasCycleInComponent(int startR, int startC, int rows, int cols, 
                                        char[][] grid, boolean[][] visited) {
        char targetChar = grid[startR][startC];
        Queue<Node> queue = new ArrayDeque<>();

        // Initialize BFS
        visited[startR][startC] = true;
        queue.add(new Node(startR, startC, -1, -1));

        while (!queue.isEmpty()) {
            Node curr = queue.poll();

            for (int[] dir : DIRECTIONS) {
                int nr = curr.r + dir[0];
                int nc = curr.c + dir[1];

                // Check boundaries and if the neighbor is the same character
                if (isValidMove(nr, nc, rows, cols) && grid[nr][nc] == targetChar) {
                    if (visited[nr][nc]) {
                        // If the neighbor is visited and is NOT the parent we just came from,
                        // it means there is another path to this cell, implying a cycle.
                        if (nr != curr.pr || nc != curr.pc) {
                            return true;
                        }
                    } else {
                        // Mark as visited and add to queue
                        visited[nr][nc] = true;
                        queue.add(new Node(nr, nc, curr.r, curr.c));
                    }
                }
            }
        }
        return false;
    }

    private boolean isValidMove(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    public static void main(String[] args) {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String firstLine = br.readLine();
            if (firstLine == null) return;

            StringTokenizer st = new StringTokenizer(firstLine);
            int n = Integer.parseInt(st.nextToken());
            int m = Integer.parseInt(st.nextToken());

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                String line = br.readLine();
                if (line != null) {
                    grid[i] = line.toCharArray();
                }
            }

            GridCycleDetector detector = new GridCycleDetector();
            System.out.println(detector.detectCycle(n, m, grid));

        } catch (IOException | NumberFormatException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }
}

