        if (detector.hasCycle()) {
            System.out.println("Yes");
        } else {
            System.out.println("No");
        }

        scanner.close();
    }

    /**
     * Logic class responsible for cycle detection in the grid.
     */
    private static class CycleDetector {
        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final boolean[][] visited;

        // Direction vectors for North, South, East, West movements
        private static final int[] DR = {-1, 1, 0, 0};
        private static final int[] DC = {0, 0, 1, -1};

        public CycleDetector(char[][] grid) {
            this.grid = grid;
            this.rows = grid.length;
            this.cols = (rows > 0) ? grid[0].length : 0;
            this.visited = new boolean[rows][cols];
        }

        /**
         * Iterates through the grid to find any unvisited component that contains a cycle.
         * @return true if a cycle is found, false otherwise.
         */
        public boolean hasCycle() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (!visited[r][c]) {
                        // Start a DFS from every unvisited cell
                        if (dfs(r, c, -1, -1, grid[r][c])) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        /**
         * Depth First Search to detect cycles in an undirected graph representation of the grid.
         * 
         * @param r Current row
         * @param c Current column
         * @param prevR Row of the cell we just came from (to prevent immediate backtracking)
         * @param prevC Column of the cell we just came from
         * @param color The character value we are tracking for the cycle
         * @return true if a cycle is detected
         */
        private boolean dfs(int r, int c, int prevR, int prevC, char color) {
            visited[r][c] = true;

            for (int i = 0; i < 4; i++) {
                int nextR = r + DR[i];
                int nextC = c + DC[i];

                // Check boundaries and if the neighbor matches the color
                if (isValidMove(nextR, nextC, color)) {

                    // If the neighbor is the cell we just came from, ignore it (undirected graph rule)
                    if (nextR == prevR && nextC == prevC) {
                        continue;
                    }

                    // If the neighbor is already visited, we found a cycle
                    if (visited[nextR][nextC]) {
                        return true;
                    }

                    // Recurse into the neighbor
                    if (dfs(nextR, nextC, r, c, color)) {
                        return true;
                    }
                }
            }

            return false;
        }

        /**
         * Helper to validate if a coordinate is within bounds and matches the target color.
         */
        private boolean isValidMove(int r, int c, char color) {
            return r >= 0 && r < rows && 
                   c >= 0 && c < cols && 
                   grid[r][c] == color;
        }
    }
}

