     *
     * @return true if a cycle is found, false otherwise.
     */
    public boolean hasCycle() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (!visited[r][c]) {
                    // Start a DFS from every unvisited cell
                    if (detectCycleDFS(r, c, -1, -1)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Performs a Depth-First Search to find a cycle.
     *
     * @param r         Current row index.
     * @param c         Current column index.
     * @param parentR   Row index of the cell we just came from.
     * @param parentC   Column index of the cell we just came from.
