        char currentChar = grid[r][c];

        for (int[] dir : DIRECTIONS) {
            int nextR = r + dir[0];
            int nextC = c + dir[1];

            if (isValidMove(nextR, nextC, currentChar)) {
                // If the next cell is already visited and is NOT the parent, we found a cycle
                if (visited[nextR][nextC]) {
                    if (nextR != parentR || nextC != parentC) {
                        return true;
                    }
                } else {
                    // Continue DFS
                    if (detectCycleDFS(nextR, nextC, r, c)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Validates if a move is within bounds and matches the target character.
     */
    private boolean isValidMove(int r, int c, char targetChar) {
