/**
 * Handles the logic of solving the grid cycle detection problem.
 */
class GridCycleSolver {
    private final FastReader reader;

    public GridCycleSolver(FastReader reader) {
        this.reader = reader;
    }

    /**
     * Orchestrates the reading of input and the execution of the solver.
     */
    public void solve(PrintWriter out) throws IOException {
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        if (rows <= 0 || cols <= 0) {
            out.println("No");
            return;
        }

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = reader.nextLine();
            if (line == null || line.isEmpty()) {
                // If an empty line is encountered, skip it to find the actual row data
                i--;
                continue;
            }
            grid[i] = line.toCharArray();
        }

        if (containsCycle(grid, rows, cols)) {
            out.println("Yes");
        } else {
            out.println("No");
        }
    }

    /**
     * Iterates through the grid to find any connected component of 
     * identical characters that contains a cycle.
     */
    private boolean containsCycle(char[][] grid, int rows, int cols) {
        boolean[][] visited = new boolean[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (!visited[i][j]) {
                    // Start a DFS for every unvisited cell to explore its component
                    if (hasCycleDFS(grid, i, j, -1, -1, grid[i][j], visited, rows, cols)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Depth First Search to detect a cycle in an undirected graph (the grid).
     * 
     * @param r Current row index
     * @param c Current column index
     * @param prevR Row index of the previous cell (to avoid immediate backtracking)
     * @param prevC Column index of the previous cell
     * @param targetChar The character value that forms the component
     * @param visited Matrix tracking visited cells
     * @param rows Total rows in grid
     * @param cols Total columns in grid
     * @return true if a cycle is detected
     */
    private boolean hasCycleDFS(char[][] grid, int r, int c, int prevR, int prevC, 
                                char targetChar, boolean[][] visited, int rows, int cols) {
        visited[r][c] = true;

        // Direction vectors for moving: Right, Left, Down, Up
        int[] dr = {0, 0, 1, -1};
        int[] dc = {1, -1, 0, 0};

        for (int i = 0; i < 4; i++) {
            int nextR = r + dr[i];
            int nextC = c + dc[i];

            // Check boundaries and if the character matches the target component
            if (isWithinBounds(nextR, nextC, rows, cols) && grid[nextR][nextC] == targetChar) {
                if (visited[nextR][nextC]) {
                    // If the neighbor is already visited and is NOT the parent we just came from,
                    // we have found a cycle.
                    if (nextR != prevR || nextC != prevC) {
                        return true;
                    }
                } else {
                    // Continue DFS
                    if (hasCycleDFS(grid, nextR, nextC, r, c, targetChar, visited, rows, cols)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    private boolean isWithinBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

/**
 * Efficient utility for reading input from an InputStream.
 */
class FastReader {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    public FastReader(InputStream inputStream) {
        this.reader = new BufferedReader(new InputStreamReader(inputStream));
    }

    public String next() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreElements()) {
            String line = reader.readLine();
            if (line == null) {
                return null;
            }
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    public int nextInt() throws IOException {
        String next = next();
        return (next == null) ? 0 : Integer.parseInt(next);
    }

    public String nextLine() throws IOException {
        return reader.readLine();
    }
}

