    static class GridCycleDetector {
        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final boolean[][] visited;

        private static final int[] ROW_DIRECTIONS = {1, -1, 0, 0};
        private static final int[] COL_DIRECTIONS = {0, 0, 1, -1};

        public GridCycleDetector(char[][] grid) {
            this.grid = grid;
            this.rows = grid.length;
            this.cols = grid[0].length;
            this.visited = new boolean[rows][cols];
        }

        /**
         * Iterates through the grid to find any component containing a cycle.
         * @return true if at least one cycle is found.
         */
        public boolean hasCycle() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (!visited[r][c]) {
                        if (findCycleDFS(r, c, -1, -1)) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        /**
         * Depth First Search to detect cycles in an undirected graph structure.
         * 
         * @param r Current row
         * @param c Current column
         * @param prevR Row of the parent cell (to prevent immediate backtracking)
         * @param prevC Column of the parent cell
         * @return true if a cycle is detected
         */
        private boolean findCycleDFS(int r, int c, int prevR, int prevC) {
            visited[r][c] = true;

            for (int i = 0; i < 4; i++) {
                int newRow = r + ROW_DIRECTIONS[i];
                int newCol = c + COL_DIRECTIONS[i];

                if (isInBounds(newRow, newCol)) {
                    // A cycle is found if we encounter a visited cell of the same 
                    // character that is NOT the cell we just came from.
                    if (grid[newRow][newCol] == grid[r][c]) {
                        if (visited[newRow][newCol]) {
                            if (newRow != prevR || newCol != prevC) {
                                return true;
                            }
                        } else {
                            if (findCycleDFS(newRow, newCol, r, c)) {
                                return true;
                            }
                        }
                    }
                }
            }
            return false;
        }

        private boolean isInBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * Fast I/O utility for efficient reading of large inputs.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
