 * A cycle is defined as a path of at least 4 cells of the same color 
 * that returns to the starting point without reusing an edge.
 */
public class School {

    private static final int[][] DIRECTIONS = {
        {1, 0}, {-1, 0}, {0, 1}, {0, -1}
    };

    public static void main(String[] args) {
