            // In a real-world scenario, use a logger
            out.println("Error processing input: " + e.getMessage());
        } finally {
            out.close();
        }
    }

    /**
     * Orchestrates the cycle detection across the entire grid.
     */
    private static boolean hasCycle(char[][] grid, int rows, int cols) {
        boolean[][] visited = new boolean[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                // If not visited, start a DFS to explore this connected component
                if (!visited[i][j]) {
                    if (detectCycleDFS(grid, visited, i, j, -1, -1)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Uses DFS to find cycles in an undirected graph component.
     * 
     * @param grid The character grid.
     * @param visited Tracker for visited cells.
     * @param r Current row.
     * @param c Current column.
     * @param pr Parent row (to avoid immediate backtracking).
     * @param pc Parent column.
     * @return true if a cycle is found.
     */
    private static boolean detectCycleDFS(char[][] grid, boolean[][] visited, int r, int c, int pr, int pc) {
        visited[r][c] = true;

        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            // Check bounds and if the neighbor has the same color
            if (isValid(grid, nr, nc) && grid[nr][nc] == grid[r][c]) {
                if (visited[nr][nc]) {
                    // If the neighbor is visited and is NOT the parent, we found a cycle
                    if (nr != pr || nc != pc) {
                        return true;
                    }
                } else {
                    // Recursive DFS call
                    if (detectCycleDFS(grid, visited, nr, nc, r, c)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    private static boolean isValid(char[][] grid, int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }

