import java.util.Scanner;

/**
 * Detects if there is a cycle of identical adjacent characters in a 2D grid.
 */
class GridCycleDetector {

    private final char[][] grid;
    private final boolean[][] visited;
    private final int rows;
    private final int cols;

    // Directions for movement: Up, Down, Left, Right
    private static final int[] ROW_DIRECTIONS = {-1, 1, 0, 0};
    private static final int[] COL_DIRECTIONS = {0, 0, -1, 1};

    public GridCycleDetector(char[][] grid) {
        this.grid = grid;
        this.rows = grid.length;
        this.cols = (rows > 0) ? grid[0].length : 0;
        this.visited = new boolean[rows][cols];
    }

    /**
     * Orchestrates the cycle detection process across the entire grid.
     * @return true if a cycle is found, false otherwise.
     */
    public boolean hasCycle() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                // If the cell hasn't been visited, start a DFS from here
                if (!visited[r][c]) {
                    if (containsCycleDFS(r, c, -1, -1, grid[r][c])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Performs a Depth First Search to find a cycle of the same color.
     * 
     * @param r Current row index
     * @param c Current column index
     * @param parentRow Row index of the cell we just came from
     * @param parentCol Column index of the cell we just came from
     * @param color The character color we are tracing
     * @return true if a cycle is detected
     */
    private boolean containsCycleDFS(int r, int c, int parentRow, int parentCol, char color) {
        visited[r][c] = true;

        for (int i = 0; i < 4; i++) {
            int nextRow = r + ROW_DIRECTIONS[i];
            int nextCol = c + COL_DIRECTIONS[i];

            if (isValidMove(nextRow, nextCol) && grid[nextRow][nextCol] == color) {
                if (visited[nextRow][nextCol]) {
                    // If neighbor is visited and is NOT the parent, we found a cycle
                    if (nextRow != parentRow || nextCol != parentCol) {
                        return true;
                    }
                } else {
                    // If neighbor is not visited, recurse
                    if (containsCycleDFS(nextRow, nextCol, r, c, color)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    private boolean isValidMove(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
