            for (int j = 0; j < cols; j++) {
                // Handle potential line length mismatches gracefully
                grid[i][j] = (j < line.length()) ? line.charAt(j) : ' ';
            }
        }

        GridCycleDetector detector = new GridCycleDetector(grid);
        boolean foundCycle = detector.hasCycle();

        System.out.println(foundCycle ? "Yes" : "No");

        scanner.close();
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.util.InputMismatchException;

/**
 * A program to detect if a cycle exists in a grid of characters.
 * A cycle is formed by adjacent cells with the same character where the cycle length is at least 4.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = reader.nextLine();
                // Handle potential empty lines or mismatching lengths
                grid[i] = (line.length() >= cols) ? line.substring(0, cols).toCharArray() : line.toCharArray();
            }

            GridCycleDetector detector = new GridCycleDetector(grid);
            if (detector.hasCycle()) {
                System.out.println("Yes");
            } else {
                System.out.println("No");
            }

        } catch (IOException | InputMismatchException e) {
            // In a competitive programming context, we might just exit.
            // In production, we would log this error.
        }
    }

    /**
     * Logic for detecting cycles in a character grid using Depth First Search.
     */
    static class GridCycleDetector {
        private final int rowCount;
        private final int colCount;
        private final char[][] grid;
        private final int[][] distances;

        // Direction vectors for Up, Down, Left, Right
        private static final int[] DR = {-1, 1, 0, 0};
        private static final int[] DC = {0, 0, -1, 1};

        public GridCycleDetector(char[][] grid) {
            this.grid = grid;
            this.rowCount = grid.length;
            this.colCount = (rowCount > 0) ? grid[0].length : 0;
            this.distances = new int[rowCount][colCount];

            // Initialize distances with -1 (unvisited)
            for (int i = 0; i < rowCount; i++) {
                for (int j = 0; j < colCount; j++) {
                    distances[i][j] = -1;
                }
            }
        }

        /**
         * Iterates through the grid and starts DFS from every unvisited cell.
         * @return true if a cycle is found, false otherwise.
         */
        public boolean hasCycle() {
            for (int i = 0; i < rowCount; i++) {
                for (int j = 0; j < colCount; j++) {
                    if (distances[i][j] == -1) {
                        if (dfs(i, j, 0)) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        private boolean dfs(int r, int c, int currentDistance) {
            distances[r][c] = currentDistance;

            for (int d = 0; d < 4; d++) {
                int nr = r + DR[d];
                int nc = c + DC[d];

                // Check bounds and character match
                if (isValid(nr, nc) && grid[r][c] == grid[nr][nc]) {
                    if (distances[nr][nc] == -1) {
                        // If neighbor is unvisited, recurse
                        if (dfs(nr, nc, currentDistance + 1)) {
                            return true;
                        }
                    } else {
                        /* 
                         * If neighbor is already visited, check the distance difference.
                         * In a grid, the parent's distance is always currentDistance - 1.
                         * A distance difference >= 3 indicates a cycle of length >= 4.
                         */
                        if (currentDistance - distances[nr][nc] >= 3) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rowCount && c >= 0 && c < colCount;
        }
    }

    /**
     * Efficient input reader for large data sets.
     */
    static class FastReader {
        private final InputStream in;
        private final byte[] buffer = new byte[1024];
        private int pointer = 0;
        private int bufferLength = 0;

        public FastReader(InputStream in) {
            this.in = in;
        }

        private boolean fillBuffer() throws IOException {
            bufferLength = in.read(buffer);
            pointer = 0;
            return bufferLength > 0;
        }

        private int read() throws IOException {
            if (pointer >= bufferLength) {
                if (!fillBuffer()) return -1;
            }
            return buffer[pointer++];
        }

        public int nextInt() throws IOException {
            int c = read();
            while (c != -1 && isSpaceChar(c)) c = read();
            if (c == -1) throw new InputMismatchException();

            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }

            int res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res = res * 10 + (c - '0');
                c = read();
            } while (c != -1 && !isSpaceChar(c));

            return res * sgn;
        }

        public String nextLine() throws IOException {
            int c = read();
            // Skip leading whitespace but respect end of line
            while (c != -1 && isSpaceChar(c) && !isEndOfLine(c)) {
                c = read();
            }

            StringBuilder sb = new StringBuilder();
            while (c != -1 && !isEndOfLine(c)) {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        private boolean isEndOfLine(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }
    }
}

