class GridCycleDetector {

    private static final int[][] DIRECTIONS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    private final FastReader reader;
    private final PrintWriter writer;

    private int rows;
    private int cols;
    private char[][] grid;
    private boolean[][] visited;

    public GridCycleDetector() {
        this.reader = new FastReader();
        this.writer = new PrintWriter(System.out);
    }

    /**
     * Main execution loop.
     */
    public void run() {
        try {
            solve();
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        } finally {
            writer.close();
        }
    }

    private void solve() throws IOException {
        rows = reader.nextInt();
        cols = reader.nextInt();
        grid = new char[rows][cols];
        visited = new boolean[rows][cols];

        for (int i = 0; i < rows; i++) {
            String line = reader.next();
            grid[i] = line.toCharArray();
        }

        if (containsCycle()) {
            writer.println("Yes");
        } else {
            writer.println("No");
        }
    }

    /**
     * Iterates through the grid to find any unvisited colored cell and starts a BFS.
     */
    private boolean containsCycle() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                // '#' represents an empty/wall cell; we only care about colored cells
                if (grid[r][c] != '#' && !visited[r][c]) {
                    if (hasCycleFrom(r, c)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Performs BFS to detect a cycle within a connected component of the same color.
     * 
     * @param startRow Starting row index
     * @param startCol Starting column index
     * @return true if a cycle is detected
     */
    private boolean hasCycleFrom(int startRow, int startCol) {
        char targetColor = grid[startRow][startCol];
        Queue<Node> queue = new LinkedList<>();

        // Node stores current position (r, c) and the position of the parent (pr, pc)
        // to ensure we don't immediately count moving back to a parent as a cycle.
        queue.add(new Node(startRow, startCol, -1, -1));
        visited[startRow][startCol] = true;

        while (!queue.isEmpty()) {
            Node current = queue.poll();

            for (int[] dir : DIRECTIONS) {
                int nextR = current.r + dir[0];
                int nextC = current.c + dir[1];

                if (isValid(nextR, nextC) && grid[nextR][nextC] == targetColor) {
                    if (visited[nextR][nextC]) {
                        // If the neighbor is visited and is NOT the parent of the current cell, 
                        // we found a cycle.
                        if (nextR != current.parentR || nextC != current.parentC) {
                            return true;
                        }
                    } else {
                        visited[nextR][nextC] = true;
                        queue.add(new Node(nextR, nextC, current.r, current.c));
                    }
                }
            }
        }
        return false;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Represents a cell in the grid during BFS traversal.
     */
    private static class Node {
        final int r, c, parentR, parentC;

        Node(int r, int c, int parentR, int parentC) {
            this.r = r;
            this.c = c;
            this.parentR = parentR;
            this.parentC = parentC;
        }
    }

    /**
     * Fast I/O utility.
     */
    private static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

