    private final boolean[][] visited;

    // Directional vectors for movement: Up, Down, Left, Right
    private static final int[] ROW_DIRECTIONS = {-1, 1, 0, 0};
    private static final int[] COL_DIRECTIONS = {0, 0, -1, 1};

    public GridCycleDetector(char[][] grid) {
        this.grid = grid;
        this.rows = grid.length;
        this.cols = grid[0].length;
        this.visited = new boolean[rows][cols];
    }

    /**
     * Iterates through the grid to find unvisited cells and triggers DFS.
     * 
     * @return true if a cycle of identical adjacent characters is found.
     */
    public boolean hasCycle() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (!visited[i][j]) {
                    // Start DFS from unvisited cell. 
                    // -1, -1 indicates the starting node has no parent.
                    if (dfs(i, j, -1, -1)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Performs Depth First Search to detect cycles in the grid.
     * 
     * @param r Current row index.
     * @param c Current column index.
     * @param parentRow The row index of the cell we arrived from.
     * @param parentCol The column index of the cell we arrived from.
     * @return true if a cycle is detected.
     */
    private boolean dfs(int r, int c, int parentRow, int parentCol) {
        visited[r][c] = true;
        char currentChar = grid[r][c];

        for (int i = 0; i < 4; i++) {
            int nextR = r + ROW_DIRECTIONS[i];
            int nextC = c + COL_DIRECTIONS[i];

            // Boundary check
            if (isWithinBounds(nextR, nextC)) {
                // Check if neighbor has the same character
                if (grid[nextR][nextC] == currentChar) {

                    if (visited[nextR][nextC]) {
                        // If neighbor is visited and is NOT the immediate parent, it's a cycle
                        if (nextR != parentRow || nextC != parentCol) {
                            return true;
                        }
                    } else {
                        // If neighbor is unvisited, continue the DFS
                        if (dfs(nextR, nextC, r, c)) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Validates if the given coordinates are within the grid boundaries.
     */
    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

