     * Orchestrates the search for a cycle within the grid.
     * @return true if a cycle is found, false otherwise.
     */
    public boolean hasCycle() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (!visited[r][c]) {
                    // Start DFS from every unvisited cell
                    if (isCycleFoundDFS(r, c, -1, -1)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Performs Depth First Search to detect cycles in an undirected graph.
     * 
     * @param r current row
     * @param c current column
     * @param parentR the row of the cell we just came from
     * @param parentC the column of the cell we just came from
     * @return true if a cycle is detected
     */
    private boolean isCycleFoundDFS(int r, int c, int parentR, int parentC) {
        visited[r][c] = true;

        for (int i = 0; i < 4; i++) {
            int nextR = r + ROW_OFFSETS[i];
            int nextC = c + COL_OFFSETS[i];

            // 1. Check boundaries
            if (nextR < 0 || nextR >= rows || nextC < 0 || nextC >= cols) {
                continue;
            }

            // 2. Only traverse cells with the same character
            if (grid[nextR][nextC] != grid[r][c]) {
                continue;
