     */
    public boolean hasCycle() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                // If cell not visited, start a DFS to find a cycle from this component
                if (!visited[r][c]) {
                    if (isCyclePresent(r, c, -1, -1, grid[r][c])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

