     * @param prevR Row of the cell we just came from
     * @param prevC Column of the cell we just came from
     * @param targetChar The character value we are tracing
     * @return true if a cycle is detected
     */
    private boolean isCyclePresent(int r, int c, int prevR, int prevC, char targetChar) {
        // If we hit a cell already visited in this traversal, a cycle exists
        if (visited[r][c]) {
            return true;
        }

        visited[r][c] = true;

        for (int[] dir : DIRECTIONS) {
            int nextR = r + dir[0];
            int nextC = c + dir[1];

