    private final boolean[][] visited;

    // Direction vectors for Up, Down, Left, Right
    private static final int[][] DIRECTIONS = {
            {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    public GridCycleDetector(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.visited = new boolean[rows][cols];
    }

    /**
     * Orchestrates the search for any cycle in the grid.
     * @return true if a cycle of identical characters is found, false otherwise.
     */
    public boolean hasCycle() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (!visited[r][c]) {
                    // Start a DFS for every unvisited component
                    if (dfs(r, c, -1, -1, grid[r][c])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Depth First Search to detect cycles in an undirected graph.
     *
     * @param r         Current row
     * @param c         Current column
     * @param prevR     Row of the parent node (to prevent immediate backtracking)
     * @param prevC     Column of the parent node
     * @param targetChar The character value we are tracking in this component
     * @return true if a cycle is detected
     */
    private boolean dfs(int r, int c, int prevR, int prevC, char targetChar) {
        visited[r][c] = true;

        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            if (isValidMove(nr, nc, targetChar)) {
                // If the neighbor is visited and is NOT the parent, we found a cycle
                if (visited[nr][nc]) {
                    if (nr != prevR || nc != prevC) {
                        return true;
                    }
                } else {
                    // Standard recursive DFS call
                    if (dfs(nr, nc, r, c, targetChar)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Validates if a move is within bounds and matches the target character.
     */
    private boolean isValidMove(int r, int c, char targetChar) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] == targetChar;
    }
}

