/**
 * A utility to detect cycles of identical characters in a 2D grid.
 * A cycle is defined as a path of at least 4 adjacent cells of the same character 
 * that returns to the starting point.
 */
public class FoxAndTwoDots {

    // Direction vectors for moving Up, Down, Left, and Right
    private static final int[] ROW_DIRECTIONS = {-1, 1, 0, 0};
    private static final int[] COL_DIRECTIONS = {0, 0, -1, 1};

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String rowString = scanner.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = rowString.charAt(j);
            }
        }

        if (hasAnyCycle(grid, rows, cols)) {
            System.out.println("Yes");
        } else {
            System.out.println("No");
        }

        scanner.close();
    }

    /**
     * Iterates through the grid to find if any connected component contains a cycle.
     * 
     * @param grid The 2D character array.
     * @param rows Number of rows in the grid.
     * @param cols Number of columns in the grid.
     * @return true if a cycle is found, false otherwise.
     */
    private static boolean hasAnyCycle(char[][] grid, int rows, int cols) {
        boolean[][] visited = new boolean[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                // If the cell hasn't been visited, start a DFS from here
                if (!visited[i][j]) {
                    if (detectCycleDFS(grid, visited, i, j, -1, -1, grid[i][j], rows, cols)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Depth First Search to detect cycles in an undirected graph.
     * 
     * @param grid          The 2D grid.
     * @param visited       The tracking array for visited cells.
     * @param currR         Current row index.
     * @param currC         Current column index.
     * @param prevR         Row index of the cell we just came from.
     * @param prevC         Column index of the cell we just came from.
     * @param targetChar    The character value we are tracking for the cycle.
     * @param rows          Total rows.
     * @param cols          Total columns.
     * @return true if a cycle of targetChar is detected.
     */
    private static boolean detectCycleDFS(char[][] grid, boolean[][] visited, 
                                          int currR, int currC, 
                                          int prevR, int prevC, 
                                          char targetChar, int rows, int cols) {

        visited[currR][currC] = true;

        for (int i = 0; i < 4; i++) {
            int nextR = currR + ROW_DIRECTIONS[i];
            int nextC = currC + COL_DIRECTIONS[i];

            // Check boundaries and if the neighbor is the same character
            if (isWithinBounds(nextR, nextC, rows, cols) && grid[nextR][nextC] == targetChar) {

                if (visited[nextR][nextC]) {
                    // If neighbor is visited and is NOT the parent, we found a cycle
                    if (nextR != prevR || nextC != prevC) {
                        return true;
                    }
                } else {
                    // If neighbor is not visited, continue DFS
                    if (detectCycleDFS(grid, visited, nextR, nextC, currR, currC, targetChar, rows, cols)) {
                        return true;
                    }
                }
            }
        }

        return false;
    }

    /**
     * Helper to validate if coordinates are within the grid boundaries.
     */
    private static boolean isWithinBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

import java.util.*;

/**
 * A utility to detect if there is a cycle of identical characters 
 * in a 2D grid using Breadth-First Search.
 */
public class GridCycleDetector {

    private static final int[][] DIRECTIONS = {
        {0, 1},  // Right
        {0, -1}, // Left
        {1, 0},  // Down
        {-1, 0}  // Up
    };

    /**
     * Represents a coordinate in the grid.
     */
    private static class Node {
        final int r;
        final int c;

        Node(int r, int c) {
            this.r = r;
            this.c = c;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            Node node = (Node) o;
            return r == node.r && c == node.c;
        }

        @Override
        public int hashCode() {
            return Objects.hash(r, c);
        }
    }

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final boolean[][] visited;
    private final Node[][] parent;

    public GridCycleDetector(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.visited = new boolean[rows][cols];
        this.parent = new Node[rows][cols];
    }

    /**
     * Iterates through the grid to find if any connected component forms a cycle.
     * @return true if a cycle is found, false otherwise.
     */
    public boolean hasCycle() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (!visited[i][j]) {
                    if (bfs(i, j)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Performs Breadth-First Search to detect cycles of the same character.
     */
    private boolean bfs(int startR, int startC) {
        Queue<Node> queue = new ArrayDeque<>();
        Node startNode = new Node(startR, startC);

        queue.add(startNode);
        visited[startR][startC] = true;
        parent[startR][startC] = null; // Starting node has no parent

        while (!queue.isEmpty()) {
            Node current = queue.poll();

            for (int[] dir : DIRECTIONS) {
                int nextR = current.r + dir[0];
                int nextC = current.c + dir[1];

                // Check bounds and character matching
                if (isValidMove(nextR, nextC, current)) {
                    Node neighbor = new Node(nextR, nextC);

                    if (!visited[nextR][nextC]) {
                        visited[nextR][nextC] = true;
                        parent[nextR][nextC] = current;
                        queue.add(neighbor);
                    } else {
                        // If the neighbor is already visited and is NOT the parent 
                        // of the current node, we have found a cycle.
                        if (!neighbor.equals(parent[current.r][current.c])) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    private boolean isValidMove(int r, int c, Node current) {
        return r >= 0 && r < rows && 
               c >= 0 && c < cols && 
               grid[r][c] == grid[current.r][current.c];
    }

    /**
     * Main driver for the application.
     */
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        if (!sc.hasNextInt()) return;
        int rows = sc.nextInt();
        int cols = sc.nextInt();
        sc.nextLine(); // Consume newline

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = sc.nextLine();
            grid[i] = line.toCharArray();
        }

        GridCycleDetector detector = new GridCycleDetector(rows, cols, grid);

        if (detector.hasCycle()) {
            System.out.println("Yes");
        } else {
            System.out.println("No");
        }

        sc.close();
    }
}

