/**
 * Logic for detecting cycles in a grid of characters.
 * A cycle is defined as a path of the same character that returns to a visited cell
 * without immediately backtracking to the previous cell.
 */
class CycleDetector {

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final boolean[][] visited;

    private static final int[][] DIRECTIONS = {
        {0, 1},  // Right
        {0, -1}, // Left
        {1, 0},  // Down
        {-1, 0}  // Up
    };

    public CycleDetector(char[][] grid) {
        this.grid = grid;
        this.rows = grid.length;
        this.cols = (rows > 0) ? grid[0].length : 0;
        this.visited = new boolean[rows][cols];
    }

    /**
     * Iterates through the grid to find any connected component containing a cycle.
     * @return true if a cycle is found, false otherwise.
     */
    public boolean hasCycle() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (!visited[i][j]) {
                    if (performIterativeDFS(i, j)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Performs an iterative Depth-First Search to detect cycles.
     * Iterative approach is used to prevent StackOverflowError on large grids.
     */
    private boolean performIterativeDFS(int startR, int startC) {
        char targetColor = grid[startR][startC];
        // Stack stores the current cell and its parent cell to prevent immediate backtracking
        Deque<TraversalState> stack = new ArrayDeque<>();

        stack.push(new TraversalState(startR, startC, -1, -1));
        visited[startR][startC] = true;

        while (!stack.isEmpty()) {
            TraversalState current = stack.pop();

            for (int[] dir : DIRECTIONS) {
                int nr = current.r + dir[0];
                int nc = current.c + dir[1];

                // 1. Check bounds
                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
                    // 2. Check if it matches the color of the current component
                    if (grid[nr][nc] == targetColor) {
                        // 3. If visited and not the cell we just came from, we found a cycle
                        if (visited[nr][nc]) {
                            if (nr != current.parentR || nc != current.parentC) {
                                return true;
                            }
                        } else {
                            // 4. If not visited, mark and push to stack
                            visited[nr][nc] = true;
                            stack.push(new TraversalState(nr, nc, current.r, current.c));
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Represents the state of a cell during DFS traversal.
     */
    private static class TraversalState {
        final int r;
        final int c;
        final int parentR;
        final int parentC;

        TraversalState(int r, int c, int parentR, int parentC) {
            this.r = r;
            this.c = c;
            this.parentR = parentR;
            this.parentC = parentC;
        }
    }
}

