/**
 * Problem: Detect if there is a cycle of same-colored cells in a grid.
 * A cycle is defined as a path of at least 4 cells where each cell 
 * is adjacent to the next and has the same color, without immediate backtracking.
 */
public class CF510B_FoxAndTwoDots {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] gridData = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            for (int j = 0; j < cols; j++) {
                gridData[i][j] = line.charAt(j);
            }
        }

        Grid grid = new Grid(gridData);
        CycleDetector detector = new CycleDetector(grid);

        if (detector.hasCycle()) {
            System.out.println("Yes");
        } else {
            System.out.println("No");
        }

        scanner.close();
    }

    /**
     * Represents the possible directions of movement in the grid.
     */
    enum Direction {
        UP(-1, 0),
        DOWN(1, 0),
        LEFT(0, -1),
        RIGHT(0, 1),
        NONE(0, 0);

        private final int deltaRow;
        private final int deltaCol;

        Direction(int deltaRow, int deltaCol) {
            this.deltaRow = deltaRow;
            this.deltaCol = deltaCol;
        }

        public int getDeltaRow() { return deltaRow; }
        public int getDeltaCol() { return deltaCol; }

        /**
         * Returns the opposite direction to prevent immediate backtracking.
         */
        public Direction getOpposite() {
            return switch (this) {
                case UP -> DOWN;
                case DOWN -> UP;
                case LEFT -> RIGHT;
                case RIGHT -> LEFT;
                case NONE -> NONE;
            };
        }
    }

    /**
     * Represents a single cell state during the BFS traversal.
     */
    private static class Node {
        final int row;
        final int col;
        final Direction incomingDirection;

        Node(int row, int col, Direction incomingDirection) {
            this.row = row;
            this.col = col;
            this.incomingDirection = incomingDirection;
        }
    }

    /**
     * Encapsulates the grid data and boundary validation.
     */
    private static class Grid {
        private final char[][] cells;
        private final int rows;
        private final int cols;

        Grid(char[][] cells) {
            this.cells = cells;
            this.rows = cells.length;
            this.cols = cells[0].length;
        }

        public int getRows() { return rows; }
        public int getCols() { return cols; }

        public boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        public char getColorAt(int r, int c) {
            return cells[r][c];
        }

        public boolean isSameColor(int r1, int c1, int r2, int c2) {
            return cells[r1][c1] == cells[r2][c2];
        }
    }

    /**
     * Contains the logic for finding cycles within the grid.
     */
    private static class CycleDetector {
        private final Grid grid;

        CycleDetector(Grid grid) {
            this.grid = grid;
        }

        /**
         * Iterates through all cells to ensure all connected components are checked.
         */
        public boolean hasCycle() {
            boolean[][] visited = new boolean[grid.getRows()][grid.getCols()];

            for (int r = 0; r < grid.getRows(); r++) {
                for (int c = 0; c < grid.getCols(); c++) {
                    if (!visited[r][c]) {
                        if (bfsFindCycle(r, c, visited)) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        /**
         * Performs BFS starting from a given cell to find a cycle in its component.
         */
        private boolean bfsFindCycle(int startRow, int startCol, boolean[][] visited) {
            Deque<Node> queue = new ArrayDeque<>();

            // Initial node has no incoming direction
            queue.add(new Node(startRow, startCol, Direction.NONE));
            visited[startRow][startCol] = true;

            while (!queue.isEmpty()) {
                Node current = queue.poll();

                for (Direction dir : Direction.values()) {
                    if (dir == Direction.NONE) continue;

                    // Skip the direction that would move us directly back to the parent
                    if (dir == current.incomingDirection.getOpposite()) {
                        continue;
                    }

                    int nextRow = current.row + dir.getDeltaRow();
                    int nextCol = current.col + dir.getDeltaCol();

                    if (grid.isWithinBounds(nextRow, nextCol) && 
                        grid.isSameColor(current.row, current.col, nextRow, nextCol)) {

                        if (visited[nextRow][nextCol]) {
                            // If we reach a visited node and it's not our parent, a cycle exists
                            return true;
                        }

                        visited[nextRow][nextCol] = true;
                        queue.add(new Node(nextRow, nextCol, dir));
                    }
                }
            }
            return false;
        }
    }
}

