     * @return true if a cycle is detected, false otherwise.
     */
    private static boolean containsCycleDFS(char[][] grid, boolean[][] visited, 
                                            int row, int col, int prevRow, int prevCol) {
        visited[row][col] = true;
        char currentChar = grid[row][col];

        for (int[] dir : DIRECTIONS) {
            int nextRow = row + dir[0];
            int nextCol = col + dir[1];

            // 1. Check bounds
            if (isValidPosition(grid, nextRow, nextCol)) {
                // 2. Check if neighbor has the same character
                if (grid[nextRow][nextCol] == currentChar) {

                    // 3. If neighbor is already visited and is NOT the parent, we found a cycle
                    if (visited[nextRow][nextCol]) {
                        if (nextRow != prevRow || nextCol != prevCol) {
                            return true;
                        }
                    } else {
                        // 4. Recursive DFS call
                        if (containsCycleDFS(grid, visited, nextRow, nextCol, row, col)) {
                            return true;
                        }
                    }
                }
            }
        }

        return false;
    }

    /**
     * Validates if the given coordinates are within the grid boundaries.
     */
    private static boolean isValidPosition(char[][] grid, int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }
}

