    /**
     * Logic for detecting cycles in the character grid using Depth First Search.
     */
    static class GridCycleDetector {
        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final boolean[][] visited;

        private static final int[][] DIRECTIONS = {
            {1, 0}, {-1, 0}, {0, 1}, {0, -1}
        };

        public GridCycleDetector(char[][] grid) {
            this.grid = grid;
            this.rows = grid.length;
            this.cols = (rows > 0) ? grid[0].length : 0;
            this.visited = new boolean[rows][cols];
        }

        /**
         * Iterates through every cell in the grid to find any connected component
         * containing a cycle.
         *
         * @return true if a cycle is found, false otherwise.
         */
        public boolean hasCycle() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (!visited[i][j]) {
                        // Start DFS from unvisited cells. 
                        // -1, -1 indicates no parent for the starting node.
                        if (dfs(i, j, -1, -1, grid[i][j])) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        /**
         * Performs DFS to find a cycle of the same character.
         *
         * @param r Current row
         * @param c Current column
         * @param pr Parent row (to avoid immediate backtracking)
         * @param pc Parent column
         * @param targetChar The character required to continue the path
         * @return true if a cycle is detected
         */
        private boolean dfs(int r, int c, int pr, int pc, char targetChar) {
            visited[r][c] = true;

            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                // Boundary and character match check
                if (isValidMove(nr, nc, targetChar)) {
                    if (visited[nr][nc]) {
                        // If the neighbor is visited and is NOT the parent, we found a cycle
                        if (nr != pr || nc != pc) {
                            return true;
                        }
                    } else {
                        // Continue DFS
                        if (dfs(nr, nc, r, c, targetChar)) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        private boolean isValidMove(int r, int c, char targetChar) {
            return r >= 0 && r < rows && 
                   c >= 0 && c < cols && 
                   grid[r][c] == targetChar;
        }
    }

    /**
     * High-performance input reader.
