import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.StringTokenizer;

/**
 * A utility to detect if there is a cycle of identical adjacent characters 
 * within a 2D grid.
 */
public class GridCycleDetector {

    public static void main(String[] args) {
        FastReader reader = new FastReader();

        try {
            String firstLine = reader.next();
            if (firstLine == null) return;

            int rows = Integer.parseInt(firstLine);
            int cols = reader.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            GridCycleSolver solver = new GridCycleSolver(grid);
            boolean hasCycle = solver.hasCycle();

            System.out.println(hasCycle ? "Yes" : "No");

        } catch (Exception e) {
            // In a production environment, use a logging framework.
            // For this utility, we fail silently or could print a usage error.
        }
    }

    /**
     * Logic for detecting cycles in a character grid.
     */
    private static class GridCycleSolver {
        private final char[][] grid;
        private final int rows;
        private final int cols;
        private final boolean[][] visited;

        // Standard directions for 4-way adjacency (Up, Down, Left, Right)
        private static final int[][] DIRECTIONS = {
            {0, 1}, {0, -1}, {1, 0}, {-1, 0}
        };

        public GridCycleSolver(char[][] grid) {
            this.grid = grid;
            this.rows = grid.length;
            this.cols = grid[0].length;
            this.visited = new boolean[rows][cols];
        }

        /**
         * Iterates through the grid to find unvisited components and checks them for cycles.
         * @return true if a cycle of identical adjacent characters is detected.
         */
        public boolean hasCycle() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (!visited[r][c]) {
                        if (detectCycleInComponent(r, c)) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        /**
         * Performs an iterative Depth-First Search (DFS) to detect cycles 
         * within a component of identical characters.
         */
        private boolean detectCycleInComponent(int startRow, int startCol) {
            Deque<Node> stack = new ArrayDeque<>();

            // Mark starting node as visited and add to stack
            visited[startRow][startCol] = true;
            stack.push(new Node(startRow, startCol, -1, -1));

            while (!stack.isEmpty()) {
                Node current = stack.pop();

                for (int[] dir : DIRECTIONS) {
                    int nextRow = current.row + dir[0];
                    int nextCol = current.col + dir[1];

                    if (isValidNeighbor(nextRow, nextCol, current.row, current.col)) {
                        if (visited[nextRow][nextCol]) {
                            // If the neighbor is already visited and is NOT the 
                            // immediate parent of the current node, a cycle exists.
                            if (nextRow != current.parentRow || nextCol != current.parentCol) {
                                return true;
                            }
                        } else {
                            // Mark as visited immediately when pushing to avoid redundant stack entries
                            visited[nextRow][nextCol] = true;
                            stack.push(new Node(nextRow, nextCol, current.row, current.col));
                        }
                    }
                }
            }
            return false;
        }

        private boolean isValidNeighbor(int nr, int nc, int cr, int cc) {
            return nr >= 0 && nr < rows && 
                   nc >= 0 && nc < cols && 
                   grid[nr][nc] == grid[cr][cc];
        }

        /**
         * Represents a coordinate in the grid and its parent in the DFS tree.
         */
        private static class Node {
            final int row;
            final int col;
            final int parentRow;
            final int parentCol;

            Node(int row, int col, int parentRow, int parentCol) {
                this.row = row;
                this.col = col;
                this.parentRow = parentRow;
                this.parentCol = parentCol;
            }
        }
    }

    /**
     * High-performance input reader.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader() {
            this.reader = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

