 */
class MazeCycleDetector {
    private final char[][] maze;
    private final int rows;
    private final int cols;
    private final boolean[][] visited;

    private static final int[][] DIRECTIONS = {
        {1, 0},  // Down
        {0, 1},  // Right
        {-1, 0}, // Up
        {0, -1}  // Left
    };

    /**
     * Initializes the detector with a given maze.
     * 
     * @param maze The 2D character array representing the maze.
     */
    public MazeCycleDetector(char[][] maze) {
        this.maze = maze;
        this.rows = maze.length;
        this.cols = (rows > 0) ? maze[0].length : 0;
        this.visited = new boolean[rows][cols];
    }

    /**
     * Iterates through the maze to find if any character forms a cycle.
     * 
     * @return true if a cycle of identical characters is found, false otherwise.
     */
    public boolean hasCycle() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (!visited[r][c]) {
                    if (detectCycleDFS(r, c, -1, -1, maze[r][c])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Performs Depth First Search to detect cycles.
     * 
     * @param currRow    Current row index.
     * @param currCol    Current column index.
     * @param parentRow  Row index of the cell we arrived from.
     * @param parentCol  Column index of the cell we arrived from.
     * @param targetChar The character we are currently tracing.
     * @return true if a cycle is detected.
     */
    private boolean detectCycleDFS(int currRow, int currCol, int parentRow, int parentCol, char targetChar) {
        visited[currRow][currCol] = true;

        for (int[] direction : DIRECTIONS) {
            int nextRow = currRow + direction[0];
            int nextCol = currCol + direction[1];

            // Skip the cell we just came from to prevent trivial backtracking cycles
            if (nextRow == parentRow && nextCol == parentCol) {
                continue;
            }

            // Check bounds and if the neighbor matches the target character
            if (isValidMove(nextRow, nextCol) && maze[nextRow][nextCol] == targetChar) {
                // If the neighbor was already visited, we found a cycle
                if (visited[nextRow][nextCol]) {
                    return true;
                }

                // Recursively visit the neighbor
                if (detectCycleDFS(nextRow, nextCol, currRow, currCol, targetChar)) {
                    return true;
                }
            }
        }
        return false;
    }

    private boolean isValidMove(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

