import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * This program detects if there is a cycle of length 4 or more 
 * consisting of identical characters in a 2D grid.
 */
public class GridCycleDetector {

    private static final int[] DIRECTION_X = {-1, 1, 0, 0};
    private static final int[] DIRECTION_Y = {0, 0, 1, -1};

    private FastReader reader;
    private PrintWriter writer;

    public static void main(String[] args) {
        new GridCycleDetector().run();
    }

    /**
     * Orchestrates the execution of the program.
     */
    public void run() {
        reader = new FastReader();
        writer = new PrintWriter(System.out);

        try {
            solve();
        } catch (IOException e) {
            System.err.println("An error occurred while processing input: " + e.getMessage());
        } finally {
            writer.close();
        }
    }

    /**
     * Contains the core logic for reading the grid and searching for cycles.
     */
    private void solve() throws IOException {
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = reader.next().toCharArray();
        }

        // 'inCurrentPath' tracks cells in the current DFS recursion stack to detect cycles.
        boolean[][] inCurrentPath = new boolean[rows][cols];
        // 'isProcessed' tracks cells that have been fully explored to avoid redundant work.
        boolean[][] isProcessed = new boolean[rows][cols];
        // 'stepCount' stores the depth at which a cell was visited to validate cycle length.
        int[][] stepCount = new int[rows][cols];

        boolean foundCycle = false;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (!isProcessed[i][j]) {
                    if (dfs(grid, inCurrentPath, isProcessed, stepCount, 1, i, j, grid[i][j])) {
                        foundCycle = true;
                        break;
                    }
                }
            }
            if (foundCycle) break;
        }

        writer.println(foundCycle ? "Yes" : "No");
    }

    /**
     * Performs a Depth First Search to find a cycle of identical characters.
     * 
     * @param grid          The 2D character grid.
     * @param inCurrentPath Boolean array tracking the current DFS path.
     * @param isProcessed   Boolean array tracking if a cell has been completely explored.
     * @param stepCount     2D array storing the traversal depth of each cell.
     * @param currentStep   The current depth in the DFS.
     * @param x             Current row index.
     * @param y             Current column index.
     * @param targetChar    The character we are looking for in the cycle.
     * @return true if a valid cycle is found, false otherwise.
     */
    private boolean dfs(char[][] grid, 
                        boolean[][] inCurrentPath, 
                        boolean[][] isProcessed, 
                        int[][] stepCount, 
                        int currentStep, 
                        int x, 
                        int y, 
                        char targetChar) {

        inCurrentPath[x][y] = true;
        isProcessed[x][y] = true;
        stepCount[x][y] = currentStep;

        for (int i = 0; i < 4; i++) {
            int nextX = x + DIRECTION_X[i];
            int nextY = y + DIRECTION_Y[i];

            // Boundary and character match check
            if (isOutOfBounds(grid, nextX, nextY) || grid[nextX][nextY] != targetChar) {
                continue;
            }

            // If the neighbor is in the current path, we found a cycle.
            // A cycle must have at least 4 nodes, so the step difference must be at least 3.
            if (inCurrentPath[nextX][nextY]) {
                if (Math.abs(currentStep - stepCount[nextX][nextY]) >= 3) {
                    return true;
                }
            } else if (!isProcessed[nextX][nextY]) {
                // If not visited, continue the DFS.
                if (dfs(grid, inCurrentPath, isProcessed, stepCount, currentStep + 1, nextX, nextY, targetChar)) {
                    return true;
                }
            }
        }

        // Backtrack: remove the cell from the current path.
        inCurrentPath[x][y] = false;
        return false;
    }

    private boolean isOutOfBounds(char[][] grid, int x, int y) {
        return x < 0 || x >= grid.length || y < 0 || y >= grid[0].length;
    }

    /**
     * Fast I/O utility class.
     */
    private static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader() {
            reader = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

