/**
 * Encapsulates the logic for detecting cycles in a character grid.
 */
class GridCycleDetector {
    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final boolean[][] visited;

    // Directional offsets for Up, Down, Left, Right movements
    private static final int[] ROW_OFFSETS = {-1, 1, 0, 0};
    private static final int[] COL_OFFSETS = {0, 0, -1, 1};

    public GridCycleDetector(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.visited = new boolean[rows][cols];
    }

    /**
     * Iterates through all cells to find any connected component containing a cycle.
     * @return true if a cycle is found, false otherwise.
     */
    public boolean hasCycle() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (!visited[r][c]) {
                    // Start a DFS from unvisited cells
                    if (dfs(r, c, -1, -1, grid[r][c])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Performs Depth First Search to find cycles of the same character.
     * 
     * @param r Current row index
     * @param c Current column index
     * @param parentRow Row index of the cell we just came from
     * @param parentCol Column index of the cell we just came from
     * @param targetChar The character we are looking to form a cycle with
     * @return true if a cycle is detected
     */
    private boolean dfs(int r, int c, int parentRow, int parentCol, char targetChar) {
        visited[r][c] = true;

        for (int i = 0; i < 4; i++) {
            int nextR = r + ROW_OFFSETS[i];
            int nextC = c + COL_OFFSETS[i];

            // Check boundaries and character match
            if (isWithinBounds(nextR, nextC) && grid[nextR][nextC] == targetChar) {
                if (visited[nextR][nextC]) {
                    // If the neighbor is visited and is NOT the cell we just came from, 
                    // we have found a cycle.
                    if (nextR != parentRow || nextC != parentCol) {
                        return true;
                    }
                } else {
                    // Continue DFS
                    if (dfs(nextR, nextC, r, c, targetChar)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

