/**
 * A utility to detect if a grid contains a cycle of at least 4 
 * identical characters in an undirected manner (up, down, left, right).
 */
public class GridCycleDetector {

    // Direction vectors for navigating: Up, Down, Left, Right
    private static final int[][] DIRECTIONS = {
        {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final boolean[][] visited;

    public GridCycleDetector(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.visited = new boolean[rows][cols];
    }

    /**
     * Orchestrates the search for a cycle within the grid.
     * 
     * @return true if a cycle of identical characters is found.
     */
    public boolean hasCycle() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                // If this cell hasn't been visited, start a DFS from here
                if (!visited[i][j]) {
                    if (findCycleDFS(i, j, -1, -1, grid[i][j])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Performs a Depth First Search to detect cycles.
     * 
     * @param r Current row index
     * @param c Current column index
     * @param prevR Row index of the parent cell (to prevent immediate backtracking)
     * @param prevC Column index of the parent cell
     * @param target The character we are looking for in the cycle
     * @return true if a cycle is detected
     */
    private boolean findCycleDFS(int r, int c, int prevR, int prevC, char target) {
        visited[r][c] = true;

        for (int[] dir : DIRECTIONS) {
            int nextR = r + dir[0];
            int nextC = c + dir[1];

            if (isValid(nextR, nextC, target)) {
                if (visited[nextR][nextC]) {
                    // If the neighbor is already visited and it's NOT the parent, 
                    // we have found a cycle. In a grid, the shortest possible 
                    // cycle is length 4.
                    if (nextR != prevR || nextC != prevC) {
                        return true;
                    }
                } else {
                    // Continue DFS
                    if (findCycleDFS(nextR, nextC, r, c, target)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Validates if the given coordinates are within bounds and match the target character.
     */
    private boolean isValid(int r, int c, char target) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] == target;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        if (!sc.hasNextInt()) return;
        int n = sc.nextInt();
        int m = sc.nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String rowString = sc.next();
            for (int j = 0; j < m; j++) {
                grid[i][j] = rowString.charAt(j);
            }
        }

        GridCycleDetector detector = new GridCycleDetector(n, m, grid);

        if (detector.hasCycle()) {
            System.out.println("Yes");
        } else {
            System.out.println("No");
        }

        sc.close();
    }
}

