        /**
         * Depth First Search to detect a cycle in an undirected graph.
         *
         * @param r Current row
         * @param c Current column
         * @param pr Parent row (to avoid immediate backtracking)
         * @param pc Parent column
         * @return true if a cycle is detected
         */
        private boolean dfs(int r, int c, int pr, int pc) {
            visited[r][c] = true;

            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                if (isValidMove(nr, nc) && grid[nr][nc] == grid[r][c]) {
