                        }
                    } else {
                        // If the neighbor is not visited, recurse
                        if (dfs(nr, nc, r, c)) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        private boolean isValidMove(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }
