/**
 * The Foxdots class determines if a grid of characters contains 
 * a cycle consisting of the same character.
 */
public class Foxdots {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        scanner.nextLine(); // Consume the leftover newline

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.nextLine();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
            }
        }

        if (containsSameCharacterCycle(grid, rows, cols)) {
            System.out.println("Yes");
        } else {
            System.out.println("No");
        }

        scanner.close();
    }

    /**
     * Iterates through the grid and uses Disjoint Set Union to detect 
     * if a cycle of identical adjacent characters exists.
     * 
     * @param grid The 2D character array.
     * @param rows Number of rows.
     * @param cols Number of columns.
     * @return true if a cycle is detected, false otherwise.
     */
    private static boolean containsSameCharacterCycle(char[][] grid, int rows, int cols) {
        DisjointSetUnion dsu = new DisjointSetUnion(rows * cols);

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                // Check neighbor to the right
                if (c + 1 < cols && grid[r][c] == grid[r][c + 1]) {
                    if (!dsu.union(getIndex(r, c, cols), getIndex(r, c + 1, cols))) {
                        return true; // Cycle detected
                    }
                }

                // Check neighbor below
                if (r + 1 < rows && grid[r][c] == grid[r + 1][c]) {
                    if (!dsu.union(getIndex(r, c, cols), getIndex(r + 1, c, cols))) {
                        return true; // Cycle detected
                    }
                }
            }
        }
        return false;
    }

    /**
     * Maps 2D grid coordinates to a 1D index for the DSU.
     */
    private static int getIndex(int row, int col, int totalCols) {
        return row * totalCols + col;
    }
}

/**
 * Disjoint Set Union (DSU) data structure with Path Compression 
 * and Union by Rank for efficient cycle detection.
 */
class DisjointSetUnion {
    private final int[] parent;
    private final int[] rank;

    public DisjointSetUnion(int size) {
        parent = new int[size];
        rank = new int[size];
        for (int i = 0; i < size; i++) {
            parent[i] = i;
            rank[i] = 0;
        }
    }

    /**
     * Finds the representative (root) of the set containing element i.
     * Uses path compression to flatten the structure.
     */
    public int find(int i) {
        if (parent[i] == i) {
            return i;
        }
        return parent[i] = find(parent[i]);
    }

    /**
     * Unites the sets containing elements i and j.
     * 
     * @param i First element.
     * @param j Second element.
     * @return false if i and j are already in the same set (indicating a cycle), 
     *         true if they were successfully united.
     */
    public boolean union(int i, int j) {
        int rootI = find(i);
        int rootJ = find(j);

        if (rootI == rootJ) {
            return false; // Elements are already connected; a cycle is found.
        }

        // Union by rank to keep the tree shallow
        if (rank[rootI] < rank[rootJ]) {
            parent[rootI] = rootJ;
        } else if (rank[rootI] > rank[rootJ]) {
            parent[rootJ] = rootI;
        } else {
            parent[rootI] = rootJ;
            rank[rootJ]++;
        }
        return true;
    }
}

