/**
 * A utility class to detect cycles of identical characters in a 2D grid.
 */
public class GridCycleDetector {

    private final int rowCount;
    private final int colCount;
    private final char[][] grid;

    // Tracks cells that have been fully explored in previous DFS traversals
    private final boolean[][] isProcessed;

    // Tracks the depth of cells in the current DFS recursion path to detect cycle length
    private final int[][] currentPathDepths;

    private static final int[] ROW_DIRECTIONS = {0, 1, 0, -1};
    private static final int[] COL_DIRECTIONS = {1, 0, -1, 0};
    private static final int MINIMUM_CYCLE_LENGTH = 5;

    /**
     * @param rowCount Number of rows in the grid.
     * @param colCount Number of columns in the grid.
     * @param grid     The 2D character array.
     */
    public GridCycleDetector(int rowCount, int colCount, char[][] grid) {
        this.rowCount = rowCount;
        this.colCount = colCount;
        this.grid = grid;
        this.isProcessed = new boolean[rowCount][colCount];
        this.currentPathDepths = new int[rowCount][colCount];
    }

    /**
     * Iterates through the grid to find any cycle of identical characters 
     * that meets the minimum length requirement.
     * 
     * @return true if a valid cycle is found, false otherwise.
     */
    public boolean hasLongCycle() {
        for (int r = 0; r < rowCount; r++) {
            for (int c = 0; c < colCount; c++) {
                if (!isProcessed[r][c]) {
                    // Start a DFS if this cell hasn't been processed yet
                    if (findCycle(r, c, -1, -1, 1, grid[r][c])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Depth First Search to explore paths of the same character.
     *
     * @param r            Current row index.
     * @param c            Current column index.
     * @param parentR      Row index of the predecessor cell.
     * @param parentC      Column index of the predecessor cell.
     * @param depth        The current depth in the recursion stack.
     * @param targetChar   The character we are currently tracking.
     * @return true if a cycle of length >= MINIMUM_CYCLE_LENGTH is detected.
     */
    private boolean findCycle(int r, int c, int parentR, int parentC, int depth, char targetChar) {
        // If we encounter a cell already in the current path, a cycle is detected
        if (currentPathDepths[r][c] > 0) {
            int cycleLength = depth - currentPathDepths[r][c] + 1;
            // The original logic used (depth - originalDepth >= 4), 
            // which is equivalent to checking if cycle length is at least 5.
            return (depth - currentPathDepths[r][c]) >= (MINIMUM_CYCLE_LENGTH - 1);
        }

        isProcessed[r][c] = true;
        currentPathDepths[r][c] = depth;

        for (int i = 0; i < 4; i++) {
            int nextR = r + ROW_DIRECTIONS[i];
            int nextC = c + COL_DIRECTIONS[i];

            // 1. Check bounds
            // 2. Ensure we don't immediately move back to the parent cell
            // 3. Ensure the neighbor matches the target character
            if (isValid(nextR, nextC) && 
                (nextR != parentR || nextC != parentC) && 
                grid[nextR][nextC] == targetChar) {

                if (findCycle(nextR, nextC, r, c, depth + 1, targetChar)) {
                    return true;
                }
            }
        }

        // Backtrack: remove this cell from the current path depth tracker
        currentPathDepths[r][c] = 0;
        return false;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rowCount && c >= 0 && c < colCount;
    }

    public static void main(String[] args) {
        try (FastReader reader = new FastReader(System.in);
             PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)))) {

            int n = reader.nextInt();
