     */
    static class GridCycleDetector {
        private final char[][] grid;
        private final int rows;
        private final int cols;
        private final boolean[][] visited;

        private static final int[][] DIRECTIONS = {
            {-1, 0}, {1, 0}, {0, -1}, {0, 1}
        };

        public GridCycleDetector(char[][] grid) {
            this.grid = grid;
            this.rows = grid.length;
            this.cols = (rows > 0) ? grid[0].length : 0;
            this.visited = new boolean[rows][cols];
        }

        /**
         * Iterates through the grid to find any cycle of identical characters.
         * @return true if a cycle is found, false otherwise.
         */
        public boolean hasCycle() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (!visited[i][j]) {
                        if (detectCycleDFS(i, j, -1, -1, grid[i][j])) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        /**
         * Performs Depth First Search to detect a cycle.
         * 
         * @param r Current row
         * @param c Current column
         * @param parentR Row of the cell we just came from
         * @param parentC Column of the cell we just came from
         * @param targetChar The character we are tracing
         * @return true if a cycle is detected
         */
        private boolean detectCycleDFS(int r, int c, int parentR, int parentC, char targetChar) {
            visited[r][c] = true;

            for (int[] dir : DIRECTIONS) {
                int nextR = r + dir[0];
                int nextC = c + dir[1];

                // Check boundaries and if the neighbor matches the target character
                if (isValidMove(nextR, nextC, targetChar)) {

                    // If the neighbor is already visited and is NOT the parent, a cycle is found
                    if (visited[nextR][nextC]) {
                        if (nextR != parentR || nextC != parentC) {
                            return true;
                        }
                        continue;
                    }

                    // Recurse into the neighbor
                    if (detectCycleDFS(nextR, nextC, r, c, targetChar)) {
                        return true;
                    }
                }
            }
            return false;
        }

        private boolean isValidMove(int r, int c, char targetChar) {
            return r >= 0 && r < rows && 
                   c >= 0 && c < cols && 
                   grid[r][c] == targetChar;
        }
    }

