/**
 * Logic for detecting cycles within a grid of characters.
 * A cycle is defined as a path of the same character that returns to a visited node
 * without immediately reversing the previous move.
 */
class GridCycleDetector {
    private final int rowCount;
    private final int colCount;
    private final char[][] grid;
    private final boolean[][] visited;

    private static final int[] ROW_DIRECTIONS = {0, 0, 1, -1};
    private static final int[] COL_DIRECTIONS = {1, -1, 0, 0};

    public GridCycleDetector(char[][] grid) {
        this.grid = grid;
        this.rowCount = grid.length;
        this.colCount = grid[0].length;
        this.visited = new boolean[rowCount][colCount];
    }

    /**
     * Iterates through the grid to find if any connected component of 
     * identical characters contains a cycle.
     * @return true if a cycle is found, false otherwise.
     */
    public boolean hasCycle() {
        for (int r = 0; r < rowCount; r++) {
            for (int c = 0; c < colCount; c++) {
                if (!visited[r][c]) {
                    // Start a DFS from an unvisited cell
                    if (containsCycle(r, c, -1, -1, grid[r][c])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Depth-First Search to detect a cycle in an undirected graph.
     * 
     * @param r Current row
     * @param c Current column
     * @param prevR Row of the parent node (to prevent moving back immediately)
     * @param prevC Column of the parent node
     * @param targetChar The character type we are currently tracing
     * @return true if a cycle is detected
     */
    private boolean containsCycle(int r, int c, int prevR, int prevC, char targetChar) {
        visited[r][c] = true;

        for (int i = 0; i < 4; i++) {
            int nextR = r + ROW_DIRECTIONS[i];
            int nextC = c + COL_DIRECTIONS[i];

            if (isValidMove(nextR, nextC, targetChar)) {
                if (visited[nextR][nextC]) {
                    // If the neighbor is visited and is NOT the parent, we found a cycle
                    if (nextR != prevR || nextC != prevC) {
                        return true;
                    }
                } else {
                    // Recursive DFS call
                    if (containsCycle(nextR, nextC, r, c, targetChar)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    private boolean isValidMove(int r, int c, char targetChar) {
        return r >= 0 && r < rowCount && 
               c >= 0 && c < colCount && 
               grid[r][c] == targetChar;
    }
}

