/**
 * Problem: Detect if there is a cycle in a graph formed by adjacent 
 * cells in a grid containing the same character.
 */
public class FoxAndTwoDots {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            char[][] grid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                grid[i] = scanner.next().toCharArray();
            }

            GridCycleDetector detector = new GridCycleDetector(rows, cols, grid);

            if (detector.hasCycle()) {
                writer.println("Yes");
            } else {
                writer.println("No");
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    /**
     * Handles the logic of building a graph from a grid and detecting cycles.
     */
    static class GridCycleDetector {
        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final List<List<Integer>> adjacencyList;
        private final boolean[] visited;

        public GridCycleDetector(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            this.adjacencyList = new ArrayList<>(rows * cols);
            this.visited = new boolean[rows * cols];

            for (int i = 0; i < rows * cols; i++) {
                adjacencyList.add(new ArrayList<>());
            }

            buildGraph();
        }

        /**
         * Iterates through the grid and connects adjacent cells with the same character.
         */
        private void buildGraph() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    int u = getIndex(r, c);

                    // Check neighbor to the right
                    if (c + 1 < cols && grid[r][c] == grid[r][c + 1]) {
                        addEdge(u, getIndex(r, c + 1));
                    }

                    // Check neighbor below
                    if (r + 1 < rows && grid[r][c] == grid[r + 1][c]) {
                        addEdge(u, getIndex(r + 1, c));
                    }
                }
            }
        }

        private void addEdge(int u, int v) {
            adjacencyList.get(u).add(v);
            adjacencyList.get(v).add(u);
        }

        private int getIndex(int r, int c) {
            return r * cols + c;
        }

        /**
         * Performs DFS on all connected components to find any cycle.
         * @return true if a cycle is found.
         */
        public boolean hasCycle() {
            for (int i = 0; i < rows * cols; i++) {
                if (!visited[i]) {
                    if (dfs(i, -1)) {
                        return true;
                    }
                }
            }
            return false;
        }

        private boolean dfs(int u, int parent) {
            visited[u] = true;

            for (int v : adjacencyList.get(u)) {
                if (!visited[v]) {
                    if (dfs(v, u)) {
                        return true;
                    }
                } else if (v != parent) {
                    // If neighbor is visited and not the parent, we found a cycle.
                    return true;
                }
            }
            return false;
        }
    }

    /**
     * Utility class for fast I/O operations.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(java.io.InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

