    /**
     * Logic for detecting cycles within the grid using BFS.
     */
    static class GridCycleDetector {
        private final int rows;
        private final int cols;
        private final char[][] grid;

        // Directions for moving Up, Down, Left, Right
        private static final int[] DR = {0, 0, 1, -1};
        private static final int[] DC = {1, -1, 0, 0};

        public GridCycleDetector(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
        }

        /**
         * Iterates through the grid to find any connected component that contains a cycle.
         * @return true if a cycle of identical characters is found.
         */
        public boolean hasCycle() {
            boolean[] visited = new boolean[rows * cols];
            int[] parent = new int[rows * cols];
            Arrays.fill(parent, -1);

            for (int i = 0; i < rows * cols; i++) {
                if (!visited[i]) {
                    if (bfsCheckForCycle(i, visited, parent)) {
                        return true;
                    }
                }
            }
            return false;
        }

        /**
         * Standard BFS cycle detection for an undirected graph.
         * A cycle is detected if we encounter a visited neighbor that is not the parent.
         */
        private boolean bfsCheckForCycle(int startIdx, boolean[] visited, int[] parent) {
            int[] queue = new int[rows * cols];
            int head = 0;
            int tail = 0;

            queue[tail++] = startIdx;
            visited[startIdx] = true;

            while (head < tail) {
                int currIdx = queue[head++];
                int r = currIdx / cols;
                int c = currIdx % cols;

                for (int i = 0; i < 4; i++) {
                    int nr = r + DR[i];
                    int nc = c + DC[i];

                    // Boundary and character match check
                    if (isValid(nr, nc) && grid[nr][nc] == grid[r][c]) {
                        int neighborIdx = nr * cols + nc;

                        if (!visited[neighborIdx]) {
                            visited[neighborIdx] = true;
                            parent[neighborIdx] = currIdx;
                            queue[tail++] = neighborIdx;
                        } else if (neighborIdx != parent[currIdx]) {
                            // If visited neighbor is not the parent, a cycle exists
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

