/**
 * Represents a Disjoint Set Union (DSU) data structure, 
 * also known as Union-Find, with path compression and union by rank.
 */
class DisjointSetUnion {
    private final int[] parent;
    private final int[] rank;

    public DisjointSetUnion(int size) {
        parent = new int[size];
        rank = new int[size];
        for (int i = 0; i < size; i++) {
            parent[i] = i;
            rank[i] = 0;
        }
    }

    /**
     * Finds the representative of the set containing element i.
     * Implements path compression.
     */
    public int find(int i) {
        if (parent[i] == i) {
            return i;
        }
        return parent[i] = find(parent[i]);
    }

    /**
     * Unites the sets containing elements i and j.
     * Implements union by rank.
     * @return true if i and j were already in the same set, false otherwise.
     */
    public boolean union(int i, int j) {
        int rootI = find(i);
        int rootJ = find(j);

        if (rootI == rootJ) {
            return true;
        }

        if (rank[rootI] < rank[rootJ]) {
            parent[rootI] = rootJ;
        } else if (rank[rootI] > rank[rootJ]) {
            parent[rootJ] = rootI;
        } else {
            parent[rootI] = rootJ;
            rank[rootJ]++;
        }
        return false;
    }

    public boolean isConnected(int i, int j) {
        return find(i) == find(j);
    }
}

/**
 * Logic to detect if there is a cycle of identical characters in a grid.
 */
class GridCycleDetector {
    private final int rows;
    private final int cols;
    private final char[][] grid;
