     * @param parentC   Column index of the cell we just came from.
     * @param target    The character value we are looking for in a continuous path.
     * @return true if a cycle is detected.
     */
    private boolean dfs(int r, int c, int parentR, int parentC, char target) {
        visited[r][c] = true;

        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            if (isValid(nr, nc) && grid[nr][nc] == target) {
                if (visited[nr][nc]) {
                    // If the neighbor is already visited and is not the direct parent,
                    // we have found a cycle.
                    if (nr != parentR || nc != parentC) {
                        return true;
                    }
                } else {
                    // Recurse into the next cell
                    if (dfs(nr, nc, r, c, target)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Entry point for the application.
     */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;
            int m = scanner.nextInt();

            if (!scanner.hasNextInt()) return;
            int n = scanner.nextInt();

            char[][] grid = new char[m][n];
            for (int i = 0; i < m; i++) {
                String line = scanner.next();
                for (int j = 0; j < n; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }

            GridCycleDetector detector = new GridCycleDetector(grid);
            if (detector.hasCycle()) {
                System.out.println("Yes");
            } else {
                System.out.println("No");
            }
        } catch (Exception e) {
            System.err.println("An error occurred during execution: " + e.getMessage());
        }
    }
}

