/**
 * Contains the logic to detect cycles in the grid using Depth First Search.
 */
class CycleDetector {
    private static final int[] DR = {1, 0, -1, 0};
    private static final int[] DC = {0, -1, 0, 1};
    private static final char VISITED_MARKER = '*';

    private final Grid grid;
    private boolean foundCycle = false;

    public CycleDetector(Grid grid) {
        this.grid = grid;
    }

    /**
     * Scans the grid to find if any colored region contains a cycle of at least minLength.
     */
    public boolean hasCycleOfMinimumLength(int minLength) {
        for (int r = 0; r < grid.getRows(); r++) {
            for (int c = 0; c < grid.getCols(); c++) {
                if (foundCycle) return true;
                // Start DFS from every cell to ensure all connected components are checked
                dfs(r, c, -1, -1, grid.getCell(r, c), 1, minLength);
            }
        }
        return foundCycle;
    }

    private void dfs(int r, int c, int prevR, int prevC, char color, int pathLength, int minLength) {
        if (foundCycle) return;

        grid.setCell(r, c, VISITED_MARKER);

        for (int i = 0; i < 4; i++) {
            int nextR = r + DR[i];
            int nextC = c + DC[i];

            // Skip the cell we just came from to prevent trivial 2-node cycles
            if (nextR == prevR && nextC == prevC) {
                continue;
            }

            if (grid.isValid(nextR, nextC)) {
                char neighborChar = grid.getCell(nextR, nextC);

                if (neighborChar == color) {
                    // Continue exploring the same colored path
                    dfs(nextR, nextC, r, c, color, pathLength + 1, minLength);
                } else if (neighborChar == VISITED_MARKER && pathLength >= minLength - 1) {
                    // Found a path that loops back to a cell currently in the recursion stack
                    foundCycle = true;
                }
            }
        }

        // Backtrack: restore the original color so other DFS paths can use this cell
        grid.setCell(r, c, color);
    }
}

