import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Scanner;

/**
 * A utility to detect if any connected components of identical characters 
 * within a 2D grid contain a cycle.
 */
public class GridCycleDetector {

    private static final int[] ROW_DIRECTIONS = {-1, 0, 1, 0};
    private static final int[] COL_DIRECTIONS = {0, 1, 0, -1};

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            grid[i] = line.toCharArray();
        }

        if (hasAnyCycle(grid, rows, cols)) {
            System.out.println("Yes");
        } else {
            System.out.println("No");
        }

        scanner.close();
    }

    /**
     * Iterates through the grid to find all connected components.
     *
     * @param grid The 2D character array.
     * @param rows Number of rows in the grid.
     * @param cols Number of columns in the grid.
     * @return true if any connected component contains a cycle, false otherwise.
     */
    private static boolean hasAnyCycle(char[][] grid, int rows, int cols) {
        boolean[][] visited = new boolean[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (!visited[r][c]) {
                    // If a component is found that contains a cycle, return true immediately.
                    if (isComponentCyclic(grid, visited, r, c, rows, cols)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Performs an iterative DFS to explore a connected component and determine if it contains a cycle.
     * 
     * Logic: In an undirected graph, a connected component is acyclic if the number 
     * of unique edges (E) is exactly nodes - 1 (V - 1).
     *
     * @param grid    The 2D character array.
     * @param visited The tracking array for visited cells.
     * @param startR  Starting row of the component.
     * @param startC  Starting column of the component.
     * @param rows    Total rows in the grid.
     * @param cols    Total columns in the grid.
     * @return true if the component has a cycle, false otherwise.
     */
    private static boolean isComponentCyclic(char[][] grid, boolean[][] visited, int startR, int startC, int rows, int cols) {
        char targetColor = grid[startR][startC];
        int nodeCount = 0;
        int edgeCount = 0;

        Deque<Cell> stack = new ArrayDeque<>();
        stack.push(new Cell(startR, startC));
        visited[startR][startC] = true;

        while (!stack.isEmpty()) {
            Cell current = stack.pop();
            nodeCount++;

            for (int i = 0; i < 4; i++) {
                int nr = current.row + ROW_DIRECTIONS[i];
                int nc = current.col + COL_DIRECTIONS[i];

                if (isWithinBounds(nr, nc, rows, cols) && grid[nr][nc] == targetColor) {
                    // Every edge in an undirected graph is discovered twice (once from each end)
                    edgeCount++;

                    if (!visited[nr][nc]) {
                        visited[nr][nc] = true;
                        stack.push(new Cell(nr, nc));
                    }
                }
            }
        }

        // The number of unique edges is the total connections found divided by 2.
        int uniqueEdges = edgeCount / 2;
        return uniqueEdges != (nodeCount - 1);
    }

    /**
     * Checks if a coordinate is within the grid boundaries.
     */
    private static boolean isWithinBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Simple data structure to represent a cell coordinate.
     */
    private static class Cell {
        final int row;
        final int col;

        Cell(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }
}

import java.util.Scanner;

/**
 * A utility class implementing the Disjoint Set Union (DSU) data structure
 * with path compression and union by size to ensure near-constant time complexity.
 */
class DisjointSetUnion {
    private final int[] parent;
    private final int[] size;

    public DisjointSetUnion(int n) {
        parent = new int[n];
        size = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
            size[i] = 1;
        }
    }

    /**
     * Finds the representative of the set containing the given element.
     * Implements path compression.
     */
    public int find(int i) {
        if (parent[i] == i) {
            return i;
        }
        return parent[i] = find(parent[i]);
    }

    /**
     * Unites the sets containing elements i and j.
     * @return true if the elements were in different sets and successfully united.
     * @return false if they were already in the same set (indicating a cycle).
     */
    public boolean union(int i, int j) {
        int rootI = find(i);
        int rootJ = find(j);

        if (rootI == rootJ) {
            return false;
        }

        // Union by size optimization
        if (size[rootI] < size[rootJ]) {
            parent[rootI] = rootJ;
            size[rootJ] += size[rootI];
        } else {
            parent[rootJ] = rootI;
            size[rootI] += size[rootJ];
        }
        return true;
    }
}

/**
 * Business logic class to detect if there is a cycle of identical characters in a grid.
 */
class GridCycleDetector {
    private final int rows;
    private final int cols;
    private final char[][] grid;

    public GridCycleDetector(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
    }

    /**
     * Detects if there's a cycle in the grid where adjacent cells have the same character.
     * @return true if a cycle is found, false otherwise.
     */
    public boolean hasCycle() {
        DisjointSetUnion dsu = new DisjointSetUnion(rows * cols);

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int currentIndex = r * cols + c;

                // Check top neighbor
                if (r > 0 && grid[r][c] == grid[r - 1][c]) {
                    int topNeighborIndex = (r - 1) * cols + c;
                    if (!dsu.union(currentIndex, topNeighborIndex)) {
                        return true;
                    }
                }

                // Check left neighbor
                if (c > 0 && grid[r][c] == grid[r][c - 1]) {
                    int leftNeighborIndex = r * cols + (c - 1);
                    if (!dsu.union(currentIndex, leftNeighborIndex)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }
}

