import java.util.Scanner;

/**
 * A program to detect if there is a cycle within connected components of identical characters
 * in a 2D grid. A cycle is defined as a path of the same character that returns to a 
 * previously visited cell, excluding the immediate parent cell.
 */
public class FoxAndTwoDots {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        char[][] grid = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
            }
        }

        GridCycleDetector detector = new GridCycleDetector(grid);
        if (detector.hasCycle()) {
            System.out.println("Yes");
        } else {
            System.out.println("No");
        }

        scanner.close();
    }

    /**
     * Logic engine for analyzing the grid for cycles.
     */
    private static class GridCycleDetector {
        private static final int[] ROW_DIRECTIONS = {-1, 0, 1, 0};
        private static final int[] COL_DIRECTIONS = {0, 1, 0, -1};

        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final boolean[][] visited;
        private boolean cycleFound;

        public GridCycleDetector(char[][] grid) {
            this.grid = grid;
            this.rows = grid.length;
            this.cols = (rows > 0) ? grid[0].length : 0;
            this.visited = new boolean[rows][cols];
            this.cycleFound = false;
        }

        /**
         * Orchestrates the search for cycles across all components in the grid.
         * @return true if at least one cycle is found.
         */
        public boolean hasCycle() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (!visited[r][c]) {
                        performDfs(r, c, -1, -1);
                        if (cycleFound) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        /**
         * Performs Depth First Search to explore connected components of the same character.
         * 
         * @param r Current row
         * @param c Current column
         * @param parentRow Row of the cell we just came from
         * @param parentCol Column of the cell we just came from
         */
        private void performDfs(int r, int c, int parentRow, int parentCol) {
            visited[r][c] = true;

            for (int i = 0; i < 4; i++) {
                int nextRow = r + ROW_DIRECTIONS[i];
                int nextCol = c + COL_DIRECTIONS[i];

                // 1. Check bounds and if the neighbor has the same character
                if (isValidNeighbor(r, c, nextRow, nextCol)) {

                    if (visited[nextRow][nextCol]) {
                        // 2. If neighbor is visited and NOT the parent, we found a cycle
                        if (nextRow != parentRow || nextCol != parentCol) {
                            cycleFound = true;
                            return;
                        }
                    } else {
                        // 3. Recursive step for unvisited neighbors
                        performDfs(nextRow, nextCol, r, c);
                        if (cycleFound) {
                            return;
                        }
                    }
                }
            }
        }

        /**
         * Validates if the target cell is within bounds and matches the current character.
         */
        private boolean isValidNeighbor(int currentRow, int currentCol, int nextRow, int nextCol) {
            return nextRow >= 0 && nextRow < rows &&
                   nextCol >= 0 && nextCol < cols &&
                   grid[nextRow][nextCol] == grid[currentRow][currentCol];
        }
    }
}

