/**
 * Solves the problem of finding a connected path of at least 4 identical characters in a grid.
 */
public class GridPathFinder {

    private final int rows;
    private final int cols;
    private final char[][] grid;

    // Direction vectors for moving Up, Down, Left, Right
    private final int[] dr = {-1, 1, 0, 0};
    private final int[] dc = {0, 0, -1, 1};

    public GridPathFinder(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
    }

    /**
     * Iterates through the grid to find if any path of the required length exists.
     * @param targetLength The number of identical characters required in a path.
     * @return true if such a path exists, false otherwise.
     */
    public boolean containsPathOfLength(int targetLength) {
        boolean[][] visited = new boolean[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                // Start a DFS from each cell
                if (dfs(i, j, 1, grid[i][j], targetLength, visited)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Depth-First Search to find a path of identical characters.
     */
    private boolean dfs(int r, int c, int currentLength, char targetChar, int targetLength, boolean[][] visited) {
        if (currentLength == targetLength) {
            return true;
        }

        visited[r][c] = true;

        for (int i = 0; i < 4; i++) {
            int nr = r + dr[i];
            int nc = c + dc[i];

            if (isValidMove(nr, nc, targetChar, visited)) {
                if (dfs(nr, nc, currentLength + 1, targetChar, targetLength, visited)) {
                    return true;
                }
            }
        }

        // Backtrack: unmark the cell so it can be used in other potential paths
        visited[r][c] = false;
        return false;
    }

    private boolean isValidMove(int r, int c, char targetChar, boolean[][] visited) {
        return r >= 0 && r < rows && 
               c >= 0 && c < cols && 
               !visited[r][c] && 
               grid[r][c] == targetChar;
    }

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            String rowsStr = reader.next();
            if (rowsStr == null) return;

            int n = Integer.parseInt(rowsStr);
            int m = reader.nextInt();

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                String rowStr = reader.next();
                for (int j = 0; j < m; j++) {
                    grid[i][j] = rowStr.charAt(j);
                }
            }

            GridPathFinder finder = new GridPathFinder(n, m, grid);

            // The original logic aimed for a path of 4 identical characters
            if (finder.containsPathOfLength(4)) {
                writer.println("Yes");
            } else {
                writer.println("No");
            }

        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        } finally {
            try {
                reader.close();
            } catch (IOException e) {
                // Silent close
            }
            writer.close();
        }
    }
}

import java.io.IOException;
import java.util.*;

/**
 * A solver for the domino tiling problem on a grid.
 * The goal is to determine if a unique tiling exists based on forced placements.
 */
public class ProblemB {

    public static void main(String[] args) {
        try {
            DominoTilingSolver solver = new DominoTilingSolver();
            solver.solve();
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    private static class Point {
        final int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    private static class DominoTilingSolver {
        private static final int[][] ADJACENT_DIRECTIONS = {
            {-1, 0}, {1, 0}, {0, -1}, {0, 1}
        };

        // Directions used to find neighbors for re-checking after a tile placement
        private static final int[][] EXPANDED_DIRECTIONS = {
            {-1, 0}, {2, 0}, {0, -1}, {1, -1}, {0, 1}, {1, 1}
        };

        private final Scanner scanner = new Scanner(System.in);
        private int rowCount;
        private int colCount;
        private char[][] grid;
        private boolean isValid = true;

        public void solve() throws IOException {
            if (!readInput()) return;

            processForcedTiles();

            if (isValid) {
                processRemainingComponents();
            }

            printResult();
        }

        private boolean readInput() {
            if (!scanner.hasNextInt()) return false;
            rowCount = scanner.nextInt();
            colCount = scanner.nextInt();
            grid = new char[rowCount][colCount];
            for (int i = 0; i < rowCount; i++) {
                String line = scanner.next();
                grid[i] = line.toCharArray();
            }
            return true;
        }

        /**
         * Phase 1: Identify cells that have only one neighbor and are forced to form a domino.
         */
        private void processForcedTiles() {
            Deque<Point> forcedQueue = new ArrayDeque<>();

            for (int r = 0; r < rowCount; r++) {
                for (int c = 0; c < colCount; c++) {
                    if (grid[r][c] == '.') {
                        int neighbors = countAdjacentDots(r, c);
                        if (neighbors == 0) {
                            isValid = false;
                            return;
                        }
                        if (neighbors == 1) {
                            forcedQueue.add(new Point(r, c));
                        }
                    }
                }
            }

            while (!forcedQueue.isEmpty() && isValid) {
                Point p = forcedQueue.pollFirst();
                if (grid[p.r][p.c] != '.') continue;

                // Find the unique neighbor to determine orientation
                Point neighbor = findUniqueNeighbor(p);
                if (neighbor != null) {
                    boolean isVertical = neighbor.r != p.r;
                    Queue<Point> recheckQueue = new LinkedList<>();
                    applyDomino(p, isVertical, recheckQueue);

                    // Re-evaluate neighbors of the newly placed domino
                    for (Point recheck : recheckQueue) {
                        if (countAdjacentDots(recheck.r, recheck.c) == 1) {
                            forcedQueue.addLast(recheck);
                        }
                    }
                }
            }
        }

        /**
         * Phase 2: Find connected components of remaining empty cells and verify they can be tiled.
         */
        private void processRemainingComponents() {
            boolean[][] visited = new boolean[rowCount][colCount];

            for (int r = 0; r < rowCount; r++) {
                for (int c = 0; c < colCount; c++) {
                    if (!visited[r][c] && grid[r][c] == '.') {
                        int componentSize = 0;
                        Point startPoint = null;
                        boolean isVerticalHeuristic = true;

                        Queue<Point> bfsQueue = new LinkedList<>();
                        bfsQueue.add(new Point(r, c));
                        visited[r][c] = true;

                        while (!bfsQueue.isEmpty()) {
                            Point curr = bfsQueue.poll();
                            componentSize++;

                            int boundaryCount = 0;
                            for (int[] d : ADJACENT_DIRECTIONS) {
                                int nr = curr.r + d[0];
                                int nc = curr.c + d[1];

                                if (isWithinBounds(nr, nc)) {
