import java.util.LinkedList;
import java.util.Queue;
import java.util.Scanner;

/**
 * A solver for an arrow-based grid puzzle.
 * The solver identifies cells that must contain arrows based on the number of 
 * adjacent empty cells and propagates the placement until the grid is filled.
 */
public class ArrowPuzzleSolver {

    private static final int[] ROW_OFFSETS = {-1, 1, 0, 0};
    private static final int[] COL_OFFSETS = {0, 0, -1, 1};

    private int rows;
    private int cols;
    private char[][] grid;

    public static void main(String[] args) {
        ArrowPuzzleSolver solver = new ArrowPuzzleSolver();
        solver.run();
    }

    /**
     * Entry point to initialize and run the solver.
     */
    public void run() {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) {
            return;
        }

        rows = scanner.nextInt();
        cols = scanner.nextInt();
        scanner.nextLine(); // Consume the remaining newline

        grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.nextLine();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
            }
        }

        solve();
    }

    /**
     * Core logic to solve the puzzle using a propagation algorithm.
     */
    private void solve() {
        Queue<int[]> queue = new LinkedList<>();

        // Initial scan: find cells that have exactly one empty neighbor.
        // These cells are "forced" to connect to that neighbor.
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && countEmptyNeighbors(r, c) == 1) {
                    queue.add(new int[]{r, c});
                }
            }
        }

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int r = current[0];
            int c = current[1];

            // If this cell was already filled by another propagation, skip it.
            if (grid[r][c] != '.') {
                continue;
            }

            // Find the only adjacent empty cell ('.')
            int targetR = -1;
            int targetC = -1;
            for (int i = 0; i < 4; i++) {
                int nr = r + ROW_OFFSETS[i];
                int nc = c + COL_OFFSETS[i];
                if (isValid(nr, nc) && grid[nr][nc] == '.') {
                    targetR = nr;
                    targetC = nc;
                    break;
                }
            }

            // If a valid neighbor was found, place the arrows and update neighbors.
            if (targetR != -1) {
                placeArrow(r, c, targetR, targetC);

                // When cells are filled, their neighbors' empty-cell counts change.
                // We check neighbors of both cells involved in the new arrows.
                updateAffectedNeighbors(r, c, queue);
                updateAffectedNeighbors(targetR, targetC, queue);
            }
        }

        // Final verification
        if (hasEmptyCells()) {
            System.out.println("Not unique");
        } else {
            printGrid();
        }
    }

    /**
     * Checks neighbors of a cell and adds them to the queue if they now 
     * meet the criteria for forced arrow placement.
     */
    private void updateAffectedNeighbors(int r, int c, Queue<int[]> queue) {
        for (int i = 0; i < 4; i++) {
            int nr = r + ROW_OFFSETS[i];
            int nc = c + COL_OFFSETS[i];
            if (isValid(nr, nc) && grid[nr][nc] == '.' && countEmptyNeighbors(nr, nc) == 1) {
                queue.add(new int[]{nr, nc});
            }
        }
    }

    /**
     * Places arrows in the grid. Based on the original logic, 
     * arrows are placed pointing away from each other.
     */
    private void placeArrow(int r1, int c1, int r2, int c2) {
        if (c1 == c2) { // Vertical connection
            int top = Math.min(r1, r2);
            int bottom = Math.max(r1, r2);
            grid[top][c1] = '^';
            grid[bottom][c1] = 'v';
        } else { // Horizontal connection
            int left = Math.min(c1, c2);
            int right = Math.max(c1, c2);
            grid[r1][left] = '<';
            grid[r1][right] = '>';
        }
    }

    /**
     * Counts how many adjacent cells contain the '.' character.
     */
    private int countEmptyNeighbors(int r, int c) {
        int count = 0;
        for (int i = 0; i < 4; i++) {
            int nr = r + ROW_OFFSETS[i];
            int nc = c + COL_OFFSETS[i];
            if (isValid(nr, nc) && grid[nr][nc] == '.') {
                count++;
            }
        }
        return count;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private boolean hasEmptyCells() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') return true;
            }
        }
        return false;
    }

    private void printGrid() {
        StringBuilder sb = new StringBuilder();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                sb.append(grid[r][c]);
            }
            sb.append('\n');
        }
        System.out.print(sb.toString());
    }
}

import java.util.ArrayDeque;
import java.util.Queue;
import java.util.Scanner;

/**
 * GridSolver solves a grid-based puzzle where every empty cell ('.') 
 * must be filled with a directional arrow. The algorithm identifies 
 * cells that have exactly one adjacent empty cell and forces a connection.
 */
public class GridSolver {
    private static final int[] ROW_OFFSETS = {0, 0, 1, -1};
    private static final int[] COL_OFFSETS = {1, -1, 0, 0};
    private static final char EMPTY_CELL = '.';

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final Queue<ForcedMove> worklist = new ArrayDeque<>();

    /**
     * Represents a coordinate on the grid.
     */
    private static class Cell {
        final int r, c;

        Cell(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Represents a movement requirement between two cells.
     */
    private static class ForcedMove {
        final Cell from;
        final Cell to;

        ForcedMove(Cell from, Cell to) {
            this.from = from;
            this.to = to;
        }
    }

    public GridSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
    }

    /**
     * Checks if a cell is within bounds and is currently an empty '.' cell.
     */
    private boolean isDot(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] == EMPTY_CELL;
    }

    /**
     * Identifies if a cell has exactly one adjacent dot neighbor.
     * If so, it adds that forced move to the worklist.
     */
    private void findForcedMoves(int r, int c) {
        int dotNeighborCount = 0;
        int targetRow = -1;
        int targetCol = -1;

        for (int i = 0; i < 4; i++) {
            int nr = r + ROW_OFFSETS[i];
            int nc = c + COL_OFFSETS[i];
            if (isDot(nr, nc)) {
                dotNeighborCount++;
                targetRow = nr;
                targetCol = nc;
            }
        }

        if (dotNeighborCount == 1) {
            worklist.add(new ForcedMove(new Cell(r, c), new Cell(targetRow, targetCol)));
        }
    }

    /**
     * Orchestrates the solving process.
     */
    public void solve() {
        // Initial pass: Find all cells that have only one possible move
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                findForcedMoves(r, c);
            }
        }

        // Process the worklist of forced moves
        while (!worklist.isEmpty()) {
            ForcedMove move = worklist.poll();
            Cell c1 = move.from;
            Cell c2 = move.to;

            // Only proceed if both cells in the move are still empty
            if (isDot(c1.r, c1.c) && isDot(c2.r, c2.c)) {
                applyArrows(c1, c2);

                // After filling these cells, neighbors might now have only one dot neighbor
                checkNeighbors(c1);
                checkNeighbors(c2);
            }
        }

        printResult();
    }

    private void checkNeighbors(Cell cell) {
        for (int i = 0; i < 4; i++) {
            int nr = cell.r + ROW_OFFSETS[i];
            int nc = cell.c + COL_OFFSETS[i];
            if (isDot(nr, nc)) {
                findForcedMoves(nr, nc);
            }
        }
    }

    /**
     * Assigns direction characters to the two cells involved in a forced move.
     */
    private void applyArrows(Cell c1, Cell c2) {
        if (c1.r == c2.r) { // Horizontal relationship
            if (c2.c > c1.c) {
                grid[c1.r][c1.c] = '<';
                grid[c2.r][c2.c] = '>';
            } else {
                grid[c2.r][c2.c] = '<';
                grid[c1.r][c1.c] = '>';
            }
        } else { // Vertical relationship
            if (c2.r > c1.r) {
                grid[c1.r][c1.c] = '^';
                grid[c2.r][c2.c] = 'v';
            } else {
                grid[c2.r][c2.c] = '^';
                grid[c1.r][c1.c] = 'v';
            }
        }
    }

    private boolean isSolutionComplete() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == EMPTY_CELL) {
                    return false;
                }
            }
        }
        return true;
    }

    private void printResult() {
        if (isSolutionComplete()) {
            for (int r = 0; r < rows; r++) {
                System.out.println(new String(grid[r]));
            }
        } else {
            System.out.println("Not unique");
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) {
            return;
        }

        int n = scanner.nextInt();
        int m = scanner.nextInt();
        char[][] grid = new char[n][m];

        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        GridSolver solver = new GridSolver(n, m, grid);
        solver.solve();

        scanner.close();
    }
}

