/**
 * Refactored solution for the grid-based puzzle solver.
 * The program uses a topological-style peeling algorithm to fill empty cells
 * with directional arrows based on their connectivity (degree).
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            GridSolver solver = new GridSolver(rows, cols, reader);
            solver.solve(writer);
        } catch (IOException e) {
            // Silent exit as per original implementation's behavior
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Core logic class for solving the grid puzzle.
     */
    static class GridSolver {
        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final int[][] neighborDegree;
        private final Queue<Cell> queue = new LinkedList<>();
        private final FastReader reader;

        // Directional offsets for grid traversal
        private static final int[] ROW_OFFSETS = {1, -1, 0, 0};
        private static final int[] COL_OFFSETS = {0, 0, 1, -1};

        // Constants for cell characters
        private static final char EMPTY = '.';
        private static final char LEFT = '<';
        private static final char RIGHT = '>';
        private static final char UP = '^';
        private static final char DOWN = 'v';

        public GridSolver(int rows, int cols, FastReader reader) throws IOException {
            this.rows = rows;
            this.cols = cols;
            this.reader = reader;
            this.grid = new char[rows][cols];
            this.neighborDegree = new int[rows][cols];

            for (int i = 0; i < rows; i++) {
                grid[i] = reader.nextRow().toCharArray();
            }
        }

        /**
         * Orchestrates the peeling algorithm and outputs the result.
         */
        public void solve(PrintWriter out) throws IOException {
            initializeDegrees();
            populateInitialQueue();
            processPeeling();

            if (isGridFullyFilled()) {
                for (int i = 0; i < rows; i++) {
                    out.println(new String(grid[i]));
                }
            } else {
                out.println("Not unique");
            }
        }

        /**
         * Calculates the initial degree (number of adjacent empty cells) for every cell.
         */
        private void initializeDegrees() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (isCellEmpty(r, c)) {
                        int count = 0;
                        for (int i = 0; i < 4; i++) {
                            int nr = r + ROW_OFFSETS[i];
                            int nc = c + COL_OFFSETS[i];
                            if (isCellEmpty(nr, nc)) {
                                count++;
                            }
                        }
                        neighborDegree[r][c] = count;
                    }
                }
            }
        }

        /**
         * Adds all cells with exactly one empty neighbor to the processing queue.
         */
        private void populateInitialQueue() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (neighborDegree[r][c] == 1) {
                        queue.add(new Cell(r, c));
                    }
                }
            }
        }

        /**
         * Processes the queue by placing arrows in cells and updating their neighbors' degrees.
         */
        private void processPeeling() {
            while (!queue.isEmpty()) {
                Cell current = queue.poll();
                int r = current.row;
                int c = current.col;

                // Only process if the cell is still empty
                if (!isCellEmpty(r, c)) {
                    continue;
                }

                for (int i = 0; i < 4; i++) {
                    int nr = r + ROW_OFFSETS[i];
                    int nc = c + COL_OFFSETS[i];

                    if (isCellEmpty(nr, nc)) {
                        placeArrows(r, c, nr, nc);
                        updateNeighborDegrees(r, c);
                        updateNeighborDegrees(nr, nc);
                        break;
                    }
                }
            }
        }

        /**
         * Updates the degrees of neighbors after a cell is no longer empty.
         */
        private void updateNeighborDegrees(int r, int c) {
            neighborDegree[r][c] = 0;
            for (int i = 0; i < 4; i++) {
                int nr = r + ROW_OFFSETS[i];
                int nc = c + COL_OFFSETS[i];
                if (isCellEmpty(nr, nc)) {
                    neighborDegree[nr][nc]--;
                    if (neighborDegree[nr][nc] == 1) {
                        queue.add(new Cell(nr, nc));
                    }
                }
            }
        }

        /**
         * Determines which arrows to place based on the relationship between two cells.
         * Preserves the original logic for deterministic arrow orientation.
         */
        private void placeArrows(int r1, int c1, int r2, int c2) {
            // Original deterministic swap logic: if (x+y > xx+yy) swap coordinates
            if ((r1 + c1) > (r2 + c2)) {
                int tempR = r1; r1 = r2; r2 = tempR;
                int tempC = c1; c1 = c2; c2 = tempC;
            }

            if (r1 == r2) { // Horizontal connection
                grid[r1][c1] = LEFT;
                grid[r2][c2] = RIGHT;
            } else { // Vertical connection
                grid[r1][c1] = UP;
                grid[r2][c2] = DOWN;
            }
        }

        private boolean isCellEmpty(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] == EMPTY;
        }

        private boolean isGridFullyFilled() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == EMPTY) {
                        return false;
                    }
                }
            }
            return true;
        }
    }

    /**
     * Simple data transfer object for grid coordinates.
     */
    static class Cell {
        final int row;
        final int col;

        Cell(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Optimized input reader for large datasets.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String nextToken() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        public String nextRow() throws IOException {
            return nextToken();
        }
    }
}

