            }
        }

        // Step 2: Propagate constraints using the stack
        while (!constraintStack.isEmpty() && isPossible) {
            Point current = constraintStack.pop();

            // If this cell was already filled by a previous pairing, skip it
            if (grid[current.r][current.c] != '.') {
                continue;
            }

            boolean paired = false;
            for (int i = 0; i < 4; i++) {
                int targetR = current.r + DIRECTIONS[i][0];
                int targetC = current.c + DIRECTIONS[i][1];

                if (grid[targetR][targetC] == '.') {
                    // Apply the directional pairing
                    grid[current.r][current.c] = THIS_CELL_MAP[i];
                    grid[targetR][targetC] = OTHER_CELL_MAP[i];

                    // Re-calculate constraints for the newly filled cell and its neighbors
                    updateVicinity(targetR, targetC);
                    paired = true;
                    break;
                }
            }

            if (!paired) {
                isPossible = false;
            }
        }

        // Step 3: Validation and Output
        if (!isPossible || !isGridComplete()) {
            System.out.println("Not unique");
        } else {
            printGrid();
        }
    }

    /**
     * Calculates the number of adjacent '.' cells for a given coordinate.
     */
    private void updateDegree(int r, int c) {
        if (grid[r][c] == '.') {
            int count = 0;
            for (int[] dir : DIRECTIONS) {
                if (grid[r + dir[0]][c + dir[1]] == '.') {
                    count++;
                }
            }
            degrees[r][c] = count;
        } else {
            degrees[r][c] = 0;
        }
    }

    /**
     * Updates the degree for the target cell and its neighbors after a cell is filled.
     */
    private void updateVicinity(int r, int c) {
        updateDegree(r, c);
        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            // Ensure we only process cells within the active grid boundaries
            if (nr >= 1 && nr <= rows && nc >= 1 && nc <= cols) {
                updateDegree(nr, nc);
                if (grid[nr][nc] == '.') {
                    if (degrees[nr][nc] == 0) {
                        isPossible = false;
                    } else if (degrees[nr][nc] == 1) {
                        constraintStack.push(new Point(nr, nc));
                    }
                }
            }
        }
    }

    /**
     * Checks if all cells in the grid have been assigned an arrow.
     */
    private boolean isGridComplete() {
        for (int r = 1; r <= rows; r++) {
            for (int c = 1; c <= cols; c++) {
                if (grid[r][c] == '.') {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Efficiently prints the final grid to the console.
     */
    private void printGrid() {
        StringBuilder sb = new StringBuilder();
        for (int r = 1; r <= rows; r++) {
            for (int c = 1; c <= cols; c++) {
                sb.append(grid[r][c]);
            }
            sb.append('\n');
        }
        System.out.print(sb.toString());
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the Drazil and Tiles problem.
 * The program finds a unique tiling for a grid of empty cells.
 */
public class DrazilAndTiles {

    // Constants for cell types
    private static final char OBSTACLE = '*';
    private static final char EMPTY = '.';
    private static final char UP = '^';
    private static final char DOWN = 'v';
    private static final char LEFT = '<';
    private static final char RIGHT = '>';

    // Direction vectors: Down, Left, Up, Right (matching original logic)
    private static final int[] DR = {1, 0, -1, 0};
    private static final int[] DC = {0, -1, 0, 1};

    // Mapping of direction index to the tile characters for (current, neighbor)
    // This preserves the exact behavior of the original implementation.
    private static final char[][] DIRECTION_TILE_PAIRS = {
            {UP, DOWN},    // i=0: neighbor is row + 1 (Down)
            {RIGHT, LEFT}, // i=1: neighbor is col - 1 (Left)
            {DOWN, UP},    // i=2: neighbor is row - 1 (Up)
            {LEFT, RIGHT}  // i=3: neighbor is col + 1 (Right)
    };

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] initialGrid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                initialGrid[i] = reader.next().toCharArray();
            }

            TilingSolver solver = new TilingSolver(rows, cols, initialGrid);
            TilingResult result = solver.solve();

            if (result.isUnique()) {
                for (char[] row : result.getGrid()) {
                    out.println(new String(row));
                }
            } else {
                out.println("Not unique");
            }
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Represents a coordinate on the grid.
     */
    static class Cell {
        final int r, c;

        Cell(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Holds the result of the tiling attempt.
     */
    static class TilingResult {
        private final char[][] grid;
        private final boolean unique;

        TilingResult(char[][] grid, boolean unique) {
            this.grid = grid;
            this.unique = unique;
        }

        public char[][] getGrid() { return grid; }
        public boolean isUnique() { return unique; }
    }

    /**
     * Core logic for solving the tiling problem.
     */
    static class TilingSolver {
        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final int[][] degrees;
        private final Queue<Cell> tileQueue;

        public TilingSolver(int rows, int cols, char[][] initialGrid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = initialGrid;
            this.degrees = new int[rows][cols];
            this.tileQueue = new LinkedList<>();
        }

        public TilingResult solve() {
            initializeDegrees();

            while (!tileQueue.isEmpty()) {
                Cell current = tileQueue.poll();

                // If the cell was already tiled by a neighbor, skip it
                if (grid[current.r][current.c] != EMPTY) {
                    continue;
                }

                // Find the only valid adjacent empty cell
                for (int i = 0; i < 4; i++) {
                    int nr = current.r + DR[i];
                    int nc = current.c + DC[i];

                    if (isValid(nr, nc) && grid[nr][nc] == EMPTY) {
                        placeTile(current.r, current.c, nr, nc, i);
                        updateNeighborDegrees(nr, nc);
                        break;
                    }
                }
            }

            boolean isUnique = checkUniqueness();
            return new TilingResult(grid, isUnique);
        }

        private void initializeDegrees() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == OBSTACLE) {
                        continue;
                    }

                    int degree = 0;
                    for (int i = 0; i < 4; i++) {
                        int nr = r + DR[i];
                        int nc = c + DC[i];
                        if (isValid(nr, nc) && grid[nr][nc] != OBSTACLE) {
                            degree++;
                        }
                    }
                    degrees[r][c] = degree;
                    if (degree == 1) {
                        tileQueue.add(new Cell(r, c));
                    }
                }
            }
        }

        private void placeTile(int r1, int c1, int r2, int c2, int directionIdx) {
            grid[r1][c1] = DIRECTION_TILE_PAIRS[directionIdx][0];
            grid[r2][c2] = DIRECTION_TILE_PAIRS[directionIdx][1];
            degrees[r1][c1] = 0;
            degrees[r2][c2] = 0;
        }

        private void updateNeighborDegrees(int r, int c) {
            for (int i = 0; i < 4; i++) {
                int nr = r + DR[i];
                int nc = c + DC[i];
                if (isValid(nr, nc) && grid[nr][nc] == EMPTY) {
                    degrees[nr][nc]--;
                    if (degrees[nr][nc] == 1) {
                        tileQueue.add(new Cell(nr, nc));
                    }
                }
            }
        }

        private boolean checkUniqueness() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == EMPTY) {
                        return false;
                    }
                }
            }
            return true;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * Fast I/O utility for reading input efficiently.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves the Arrow Puzzle by filling empty spaces with directional arrows
 * based on the number of surrounding non-empty neighbors.
 */
public class ArrowPuzzleSolver {

    // Grid Cell Constants
    private static final int EMPTY = 0;
    private static final int WALL = -1;
    private static final int ARROW_LT = 1;
    private static final int ARROW_RT = 2;
    private static final int ARROW_UP = 3;
    private static final int ARROW_DN = 4;

    private static final char[] ARROW_SYMBOLS = {'<', '>', '^', 'v'};

    /**
     * Represents a coordinate in the grid.
     */
    private static class Point implements Comparable<Point> {
        final int x, y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }

        @Override
        public int compareTo(Point other) {
            if (this.x != other.x) {
                return Integer.compare(this.x, other.x);
            }
            return Integer.compare(this.y, other.y);
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Point)) return false;
            Point point = (Point) o;
            return x == point.x && y == point.y;
        }

        @Override
        public int hashCode() {
            return Objects.hash(x, y);
        }
    }

    /**
     * Encapsulates direction movement and the corresponding arrow assignment logic.
     */
    private enum Direction {
        LEFT(-1, 0, ARROW_UP, ARROW_DN),
        RIGHT(1, 0, ARROW_DN, ARROW_UP),
        UP(0, -1, ARROW_LT, ARROW_RT),
        DOWN(0, 1, ARROW_RT, ARROW_LT);

        final int dx, dy;
        final int newValForNeighbor, newValForCurrent;

        Direction(int dx, int dy, int newValForNeighbor, int newValForCurrent) {
            this.dx = dx;
            this.dy = dy;
            this.newValForNeighbor = newValForNeighbor;
            this.newValForCurrent = newValForCurrent;
        }
    }

    /**
     * Manages the 2D grid state and boundary logic.
     */
    private static class Grid {
        private final int[][] cells;
        private final int rows, cols;

        Grid(int n, int m) {
            this.rows = n + 2;
            this.cols = m + 2;
            this.cells = new int[rows][cols];

            // Initialize padding (boundary) as walls
            for (int i = 0; i < rows; i++) {
                cells[i][0] = WALL;
                cells[i][cols - 1] = WALL;
            }
            for (int j = 0; j < cols; j++) {
                cells[0][j] = WALL;
                cells[rows - 1][j] = WALL;
            }
        }

        void setCell(int r, int c, int value) {
            cells[r][c] = value;
        }

        int getCell(int r, int c) {
            return cells[r][c];
        }

        boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        int countNonEmptyNeighbors(int r, int c) {
            int count = 0;
            for (Direction d : Direction.values()) {
                if (cells[r + d.dx][c + d.dy] != EMPTY) {
                    count++;
                }
            }
            return count;
        }
    }

    /**
     * Main logic for solving the puzzle.
     */
    public void solve() throws IOException {
        FastReader sc = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = sc.nextInt();
        int m = sc.nextInt();

        Grid grid = new Grid(n, m);

        // Load input grid
        for (int i = 1; i <= n; i++) {
            String rowString = sc.next();
            for (int j = 1; j <= m; j++) {
                if (rowString.charAt(j - 1) == '*') {
                    grid.setCell(i, j, WALL);
                }
            }
        }

        PriorityQueue<Point> queue = new PriorityQueue<>();

        // Initial identification of candidate points
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                if (grid.getCell(i, j) == EMPTY && grid.countNonEmptyNeighbors(i, j) == 3) {
                    queue.add(new Point(i, j));
                }
            }
        }

        // Process the queue
        while (!queue.isEmpty()) {
            Point cur = queue.poll();
            if (grid.getCell(cur.x, cur.y) != EMPTY) continue;

            for (Direction dir : Direction.values()) {
                int nx = cur.x + dir.dx;
                int ny = cur.y + dir.dy;

                if (grid.getCell(nx, ny) == EMPTY) {
                    // Fill current and neighbor with the specific arrow pair
                    grid.setCell(nx, ny, dir.newValForNeighbor);
                    grid.setCell(cur.x, cur.y, dir.newValForCurrent);

                    // Add neighbors of both updated points back to the queue
                    enqueueValidNeighbors(nx, ny, grid, queue);
                    enqueueValidNeighbors(cur.x, cur.y, grid, queue);
                    break;
                }
            }
        }

        printResult(n, m, grid, out);
        out.flush();
    }

    private void enqueueValidNeighbors(int r, int c, Grid grid, PriorityQueue<Point> queue) {
        for (Direction d : Direction.values()) {
            int nr = r + d.dx;
            int nc = c + d.dy;
            if (grid.isWithinBounds(nr, nc) && grid.getCell(nr, nc) == EMPTY) {
                if (grid.countNonEmptyNeighbors(nr, nc) == 3) {
                    queue.add(new Point(nr, nc));
                }
            }
        }
    }

    private void printResult(int n, int m, Grid grid, PrintWriter out) {
        boolean allFilled = true;
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                if (grid.getCell(i, j) == EMPTY) {
                    allFilled = false;
                    break;
                }
            }
        }

        if (!allFilled) {
            out.println("Not unique");
        } else {
            StringBuilder sb = new StringBuilder();
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= m; j++) {
                    int val = grid.getCell(i, j);
                    if (val == WALL) {
                        sb.append('*');
                    } else {
                        sb.append(ARROW_SYMBOLS[val - 1]);
                    }
                }
                sb.append('\n');
            }
            out.print(sb.toString());
        }
    }

    public static void main(String[] args) throws IOException {
        new ArrowPuzzleSolver().solve();
    }

    /**
     * Fast I/O utility class.
     */
    private static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;

/**
 * A program to solve the Drazil Tiles puzzle by iteratively filling 
 * terminal dots with directional tiles.
 */
public class Solution {

    /**
     * Represents a 2D coordinate on the grid.
     */
    private static class Point {
        final int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Represents movement directions and the tile characters 
     * associated with them.
     */
    private enum Direction {
        UP(-1, 0, '^', 'v'),
        DOWN(1, 0, 'v', '^'),
        LEFT(0, -1, '<', '>'),
        RIGHT(0, 1, '>', '<');

        final int dr, dc;
        final char neighborChar; // Character for the cell being pointed to
        final char currentChar;  // Character for the current cell

        Direction(int dr, int dc, char neighborChar, char currentChar) {
            this.dr = dr;
            this.dc = dc;
            this.neighborChar = neighborChar;
            this.currentChar = currentChar;
        }
    }

    /**
     * Manages the state and boundary logic of the tile board.
     */
    private static class Grid {
        private final char[][] cells;
        private final int rows;
        private final int cols;

        Grid(int rows, int cols) {
            this.rows = rows;
            this.cols = cols;
            this.cells = new char[rows][cols];
        }

        int rows() { return rows; }
        int cols() { return cols; }

        char get(int r, int c) { return cells[r][c]; }
        void set(int r, int c, char val) { cells[r][c] = val; }

        boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        boolean isDot(int r, int c) {
            return isValid(r, c) && cells[r][c] == '.';
        }

        int countDotNeighbors(int r, int c) {
            int count = 0;
            for (Direction d : Direction.values()) {
                if (isDot(r + d.dr, c + d.dc)) {
                    count++;
                }
            }
            return count;
        }

        /**
         * A dot is a terminal if it has exactly one dot neighbor.
         */
        boolean isTerminal(int r, int c) {
            return isDot(r, c) && countDotNeighbors(r, c) == 1;
        }

        @Override
        public String toString() {
            StringBuilder sb = new StringBuilder();
            for (char[] row : cells) {
                sb.append(new String(row)).append("\n");
            }
            return sb.toString();
        }
    }

    /**
     * Contains the algorithm to solve the puzzle.
     */
    private static class Solver {
        public void solve(Grid grid) {
            Queue<Point> queue = new LinkedList<>();

            // Phase 1: Find all initial terminal cells
            for (int r = 0; r < grid.rows(); r++) {
                for (int c = 0; c < grid.cols(); c++) {
                    if (grid.isTerminal(r, c)) {
                        queue.add(new Point(r, c));
                    }
                }
            }

            // Phase 2: Process terminals via a BFS-like propagation
            while (!queue.isEmpty()) {
                Point curr = queue.poll();

                // If the cell was already filled by another terminal, skip it
                if (!grid.isDot(curr.r, curr.c)) {
                    continue;
                }

                Direction targetDir = findDotNeighborDirection(grid, curr);

                if (targetDir != null) {
                    int nr = curr.r + targetDir.dr;
                    int nc = curr.c + targetDir.dc;

                    // Place the tiles pointing away from each other
                    grid.set(nr, nc, targetDir.neighborChar);
                    grid.set(curr.r, curr.c, targetDir.currentChar);

                    // Check surrounding cells for new terminals
                    enqueueNewTerminals(grid, queue, curr.r, curr.c);
                    enqueueNewTerminals(grid, queue, nr, nc);
                }
            }

            // Phase 3: Verify if all dots were filled
            if (hasUnfilledCells(grid)) {
                System.out.println("Not unique");
            } else {
                System.out.print(grid.toString());
            }
        }

        private Direction findDotNeighborDirection(Grid grid, Point p) {
            for (Direction d : Direction.values()) {
                if (grid.isDot(p.r + d.dr, p.c + d.dc)) {
                    return d;
                }
            }
            return null;
        }

        private void enqueueNewTerminals(Grid grid, Queue<Point> queue, int r, int c) {
            for (Direction d : Direction.values()) {
                int nr = r + d.dr;
                int nc = c + d.dc;
                if (grid.isTerminal(nr, nc)) {
                    queue.add(new Point(nr, nc));
                }
            }
        }

        private boolean hasUnfilledCells(Grid grid) {
            for (int r = 0; r < grid.rows(); r++) {
                for (int c = 0; c < grid.cols(); c++) {
                    if (grid.get(r, c) == '.') return true;
                }
            }
            return false;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }

        int n = scanner.nextInt();
        int m = scanner.nextInt();
        Grid grid = new Grid(n, m);

        for (int i = 0; i < n; i++) {
            String line = scanner.next();
            for (int j = 0; j < m; j++) {
                grid.set(i, j, line.charAt(j));
            }
        }
        scanner.close();

        new Solver().solve(grid);
    }
}

