/**
 * Represents possible movements and their associated characters.
 */
enum Direction {
    UP('^', -1, 0),
    DOWN('v', 1, 0),
    LEFT('<', 0, -1),
    RIGHT('>', 0, 1);

    final char symbol;
    final int dr, dc;

    Direction(char symbol, int dr, int dc) {
        this.symbol = symbol;
        this.dr = dr;
        this.dc = dc;
    }

    /**
     * Calculates the direction required to move from (r1, c1) to (r2, c2).
     */
    static Direction getDirectionFrom(int r1, int c1, int r2, int c2) {
        if (r2 < r1) return UP;
        if (r2 > r1) return DOWN;
        if (c2 < c1) return LEFT;
        return RIGHT;
    }
