/**
 * Handles the logic for solving the grid puzzle.
 */
class GridSolver {
    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int[][] degree;
    private final Deque<Point> queue = new ArrayDeque<>();

    public GridSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.degree = new int[rows][cols];
    }

    /**
     * Solves the puzzle using a degree-based BFS approach.
     * @param out PrintWriter to output the result.
     */
    public void solve(PrintWriter out) {
        // 1. Calculate initial degrees for all empty cells
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    int d = countEmptyNeighbors(r, c);
                    degree[r][c] = d;
                    if (d == 1) {
                        queue.add(new Point(r, c));
                    }
                }
            }
        }

        // 2. Process forced moves
        while (!queue.isEmpty()) {
            Point p = queue.poll();

            // If the cell was already filled by another neighbor's constraint, skip
            if (grid[p.r][p.c] != '.') {
                continue;
            }

            Point neighbor = findOnlyEmptyNeighbor(p.r, p.c);
            if (neighbor == null) {
                out.println("Not unique");
                return;
            }

            // Force the direction: current cell points to neighbor, neighbor points to current
            grid[p.r][p.c] = Direction.getDirectionFrom(p.r, p.c, neighbor.r, neighbor.c).symbol;
            grid[neighbor.r][neighbor.c] = Direction.getDirectionFrom(neighbor.r, neighbor.c, p.r, p.c).symbol;

            // Update degrees for all neighbors of both newly filled cells
            updateNeighbors(p.r, p.c, queue);
            updateNeighbors(neighbor.r, neighbor.c, queue);
        }

        // 3. Final Validation: Check if any empty cells remain
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    out.println("Not unique");
                    return;
                }
            }
        }

        // 4. Success: Print the completed grid
        printGrid(out);
    }

    private int countEmptyNeighbors(int r, int c) {
        int count = 0;
        for (Direction d : Direction.values()) {
            int nr = r + d.dr;
            int nc = c + d.dc;
            if (isValid(nr, nc) && grid[nr][nc] == '.') {
                count++;
            }
        }
        return count;
    }

    private Point findOnlyEmptyNeighbor(int r, int c) {
        for (Direction d : Direction.values()) {
            int nr = r + d.dr;
            int nc = c + d.dc;
            if (isValid(nr, nc) && grid[nr][nc] == '.') {
                return new Point(nr, nc);
            }
        }
        return null;
    }

    private void updateNeighbors(int r, int c, Deque<Point> queue) {
        for (Direction d : Direction.values()) {
            int nr = r + d.dr;
            int nc = c + d.dc;
            if (isValid(nr, nc) && grid[nr][nc] == '.') {
                degree[nr][nc]--;
                if (degree[nr][nc] == 1) {
                    queue.add(new Point(nr, nc));
                }
            }
        }
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private void printGrid(PrintWriter out) {
        for (int i = 0; i < rows; i++) {
            out.println(new String(grid[i]));
        }
    }
}

