import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Queue;
import java.util.StringTokenizer;

/**
 * Refactored solution for the grid arrow puzzle.
 * The goal is to fill all '.' cells with arrows such that the constraints are met.
 * The algorithm uses a work-list (Queue-based) approach to propagate changes 
 * whenever a cell's surroundings allow it to be uniquely determined.
 */
public class D515 {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            PuzzleSolver solver = new PuzzleSolver(reader);
            solver.solve(writer);
        } catch (Exception e) {
            // In a production environment, use a proper logger.
            // For competitive programming, this is a standard way to handle unexpected errors.
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    /**
     * Core logic for solving the grid puzzle.
     */
    static class PuzzleSolver {
        private static final int[] DR = {-1, 0, 1, 0}; // Row offsets for Up, Right, Down, Left
        private static final int[] DC = {0, 1, 0, -1}; // Column offsets
        private static final char[] ARROWS = {'<', 'v', '>', '^'}; 
        // Note: The original code's mapping was slightly different. 
        // To preserve original logic: 
        // dir 0: dx=-1, dy=0 (Left) -> c[0] = '<'
        // dir 1: dx=0,  dy=1 (Down) -> c[1] = 'v'
        // dir 2: dx=1,  dy=0 (Right)-> c[2] = '>'
        // dir 3: dx=0,  dy=-1(Up)   -> c[3] = '^'
        // Let's align DR/DC with the original dx/dy/c index logic.
        // Original dx = {-1, 0, 1, 0}, dy = {0, 1, 0, -1}, c = {'<', 'v', '>', '^'}
        // This means:
        // Index 0: dx=-1, dy=0  => '<'
        // Index 1: dx=0,  dy=1  => 'v'
        // Index 2: dx=1,  dy=0  => '>'
        // Index 3: dx=0,  dy=-1 => '^'

        private static final int[] DX = {-1, 0, 1, 0};
        private static final int[] DY = {0, 1, 0, -1};
        private static final char[] SYMBOLS = {'<', 'v', '>', '^'};

        private int rows;
        private int cols;
        private char[][] grid;
        private final FastReader reader;

        public PuzzleSolver(FastReader reader) {
            this.reader = reader;
        }

        /**
         * Orchestrates the puzzle solving process.
         */
        public void solve(PrintWriter out) {
            this.rows = reader.nextInt();
            this.cols = reader.nextInt();
            this.grid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            processGrid();

            if (isGridFullyFilled()) {
                printGrid(out);
            } else {
                out.println("Not unique");
            }
        }

        /**
         * Iteratively processes the grid using a queue to propagate deductions.
         */
        private void processGrid() {
            Queue<Point> queue = new ArrayDeque<>();

            // Initial pass: find all '.' cells that have exactly one '.' neighbor.
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.' && countDotNeighbors(r, c) == 1) {
                        queue.add(new Point(r, c));
                    }
                }
            }

            while (!queue.isEmpty()) {
                Point curr = queue.poll();
                int r = curr.row;
                int c = curr.col;

                // If the cell is no longer '.', it was already processed.
                if (grid[r][c] != '.') continue;

                // Re-verify the condition (dot neighbors might have changed).
                int dotCount = 0;
                int targetDir = -1;
                int targetR = -1;
                int targetC = -1;

                for (int i = 0; i < 4; i++) {
                    int nr = r + DY[i];
                    int nc = c + DX[i];
                    if (isValid(nr, nc) && grid[nr][nc] == '.') {
                        dotCount++;
                        targetDir = i;
                        targetR = nr;
                        targetC = nc;
                    }
                }

                if (dotCount == 1) {
                    // Fill the current cell and its only '.' neighbor.
                    // The original logic: 
                    // field[ny][nx] = c[ndir];
                    // field[y][x] = c[opposite];
                    int oppositeDir = (targetDir + 2) % 4;
                    grid[targetR][targetC] = SYMBOLS[targetDir];
                    grid[r][c] = SYMBOLS[oppositeDir];

                    // Adding neighbors of both modified cells to the queue.
                    addNeighborsToQueue(r, c, queue);
                    addNeighborsToQueue(targetR, targetC, queue);
                }
            }
        }

        private void addNeighborsToQueue(int r, int c, Queue<Point> queue) {
            for (int i = 0; i < 4; i++) {
                int nr = r + DY[i];
                int nc = c + DX[i];
                if (isValid(nr, nc) && grid[nr][nc] == '.') {
                    queue.add(new Point(nr, nc));
                }
            }
        }

        private int countDotNeighbors(int r, int c) {
            int count = 0;
            for (int i = 0; i < 4; i++) {
                int nr = r + DY[i];
                int nc = c + DX[i];
                if (isValid(nr, nc) && grid[nr][nc] == '.') {
                    count++;
                }
            }
            return count;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        private boolean isGridFullyFilled() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.') return false;
                }
            }
            return true;
        }

        private void printGrid(PrintWriter out) {
            for (int i = 0; i < rows; i++) {
                out.println(new String(grid[i]));
            }
        }

        /**
         * Simple data carrier for coordinates.
         */
        private static class Point {
            final int row;
            final int col;

            Point(int row, int col) {
                this.row = row;
                this.col = col;
            }
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;

/**
 * DrazilandTiles solver.
 * This program tiles a grid with arrows such that every cell points to a neighbor.
 * It uses a greedy approach by processing cells with only one available neighbor.
 */
public class DrazilandTiles {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        GridSolver solver = new GridSolver(n, m, grid);
        solver.solve();
    }

    /**
     * Represents a coordinate in the grid.
     */
    private record Point(int r, int c) {}

    private static class GridSolver {
        private final int rows;
        private final int cols;
        private final char[][] grid;

        // Directional vectors: Up, Down, Left, Right
        private static final int[] DR = {-1, 1, 0, 0};
        private static final int[] DC = {0, 0, -1, 1};

        public GridSolver(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
        }

        /**
         * Executes the solving algorithm.
         */
        public void solve() {
            Queue<Point> queue = new LinkedList<>();

            // Initial pass: find all cells with exactly one '.' neighbor
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.' && countDotNeighbors(r, c) == 1) {
                        queue.add(new Point(r, c));
                    }
                }
            }

            // Process cells with only one neighbor available
            while (!queue.isEmpty()) {
                Point p1 = queue.poll();

                // If this cell was already filled by a neighbor's pairing, skip it
                if (grid[p1.r][p1.c] != '.') {
                    continue;
                }

                Point p2 = findOnlyDotNeighbor(p1.r, p1.c);

                // If no dot neighbor is found, it's either impossible or already handled
                if (p2 == null) {
                    continue;
                }

                // Try to pair p1 and p2
                if (grid[p2.r][p2.c] != '.') {
                    System.out.println("Not unique");
                    return;
                }

                // Apply arrows pointing at each other
                applyArrows(p1, p2);

                // After filling p2, its neighbors' degrees have changed.
                // If any neighbor now has exactly one '.' neighbor, add to queue.
                for (int i = 0; i < 4; i++) {
                    int nr = p2.r + DR[i];
                    int nc = p2.c + DC[i];
                    if (isValid(nr, nc) && grid[nr][nc] == '.' && countDotNeighbors(nr, nc) == 1) {
                        queue.add(new Point(nr, nc));
                    }
                }
            }

            // Final verification: Check if any '.' remains
            if (isGridIncomplete()) {
                System.out.println("Not unique");
            } else {
                printGrid();
            }
        }

        private int countDotNeighbors(int r, int c) {
            int count = 0;
            for (int i = 0; i < 4; i++) {
                int nr = r + DR[i];
                int nc = c + DC[i];
                if (isValid(nr, nc) && grid[nr][nc] == '.') {
                    count++;
                }
            }
            return count;
        }

        private Point findOnlyDotNeighbor(int r, int c) {
            for (int i = 0; i < 4; i++) {
                int nr = r + DR[i];
                int nc = c + DC[i];
                if (isValid(nr, nc) && grid[nr][nc] == '.') {
                    return new Point(nr, nc);
                }
            }
            return null;
        }

        private void applyArrows(Point p1, Point p2) {
            if (p2.c > p1.c) { // p2 is Right of p1
                grid[p1.r][p1.c] = '>';
                grid[p2.r][p2.c] = '<';
            } else if (p2.c < p1.c) { // p2 is Left of p1
                grid[p1.r][p1.c] = '<';
                grid[p2.r][p2.c] = '>';
            } else if (p2.r < p1.r) { // p2 is Up of p1
                grid[p1.r][p1.c] = '^';
                grid[p2.r][p2.c] = 'v';
            } else if (p2.r > p1.r) { // p2 is Down of p1
                grid[p1.r][p1.c] = 'v';
                grid[p2.r][p2.c] = '^';
            }
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        private boolean isGridIncomplete() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.') return true;
                }
            }
            return false;
        }

        private void printGrid() {
            StringBuilder sb = new StringBuilder();
            for (int r = 0; r < rows; r++) {
                sb.append(new String(grid[r])).append("\n");
            }
            System.out.print(sb.toString());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.*;

/**
 * A solver for the Drazil and Tiles problem.
 * The goal is to tile all empty cells ('.') in a grid using dominoes.
 */
public class DrazilAndTiles {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] grid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                grid[i] = line.toCharArray();
            }

            TilingSolver solver = new TilingSolver(grid);
            System.out.println(solver.solve());

        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Represents a single cell in the grid.
     */
    private record Cell(int r, int c) {}

    /**
     * Defines the possible moves and the characters used to represent dominoes.
     */
    private enum Direction {
        DOWN(1, 0, '^', 'v'),
        UP(-1, 0, 'v', '^'),
        RIGHT(0, 1, '<', '>'),
        LEFT(0, -1, '>', '<');

        final int dr, dc;
        final char currentCellChar;
        final char neighborCellChar;

        Direction(int dr, int dc, char currentCellChar, char neighborCellChar) {
            this.dr = dr;
            this.dc = dc;
            this.currentCellChar = currentCellChar;
            this.neighborCellChar = neighborCellChar;
        }
    }

    /**
     * Handles the logic for tiling the grid.
     */
    private static class TilingSolver {
        private final char[][] grid;
        private final int rows;
        private final int cols;
        private final int[][] degrees;

        public TilingSolver(char[][] grid) {
            this.grid = grid;
            this.rows = grid.length;
            this.cols = grid[0].length;
            this.degrees = new int[rows][cols];
        }

        /**
         * Solves the tiling problem and returns the grid or "Not unique".
         */
        public String solve() {
            initializeDegrees();
            Queue<Cell> queue = new LinkedList<>();

            // Add all degree-1 cells to the queue
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.' && degrees[i][j] == 1) {
                        queue.add(new Cell(i, j));
                    }
                }
            }

            while (!queue.isEmpty()) {
                Cell current = queue.poll();

                // If the cell was already filled by a neighbor, skip it
                if (grid[current.r][current.c] != '.') {
                    continue;
                }

                // Find the only available neighbor to pair with
                Cell neighbor = findEmptyNeighbor(current);
                if (neighbor != null) {
                    Direction dir = getDirection(current, neighbor);
                    placeDomino(current, neighbor, dir);
                    updateNeighborDegrees(neighbor, queue);
                }
            }

            return finalizeResult();
        }

        private void initializeDegrees() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.') {
                        int count = 0;
                        for (Direction dir : Direction.values()) {
                            int nr = r + dir.dr;
                            int nc = c + dir.dc;
                            if (isInBounds(nr, nc) && grid[nr][nc] == '.') {
                                count++;
                            }
                        }
                        degrees[r][c] = count;
                    }
                }
            }
        }

        private Cell findEmptyNeighbor(Cell cell) {
            for (Direction dir : Direction.values()) {
                int nr = cell.r + dir.dr;
                int nc = cell.c + dir.dc;
                if (isInBounds(nr, nc) && grid[nr][nc] == '.') {
                    return new Cell(nr, nc);
                }
            }
            return null;
        }

        private Direction getDirection(Cell from, Cell to) {
            for (Direction dir : Direction.values()) {
                if (from.r + dir.dr == to.r && from.c + dir.dc == to.c) {
                    return dir;
                }
            }
            throw new IllegalStateException("Invalid direction calculation");
        }

        private void placeDomino(Cell current, Cell neighbor, Direction dir) {
            grid[current.r][current.c] = dir.currentCellChar;
            grid[neighbor.r][neighbor.c] = dir.neighborCellChar;
        }

        private void updateNeighborDegrees(Cell neighbor, Queue<Cell> queue) {
            for (Direction dir : Direction.values()) {
                int nr = neighbor.r + dir.dr;
                int nc = neighbor.c + dir.dc;
                if (isInBounds(nr, nc) && grid[nr][nc] == '.') {
                    degrees[nr][nc]--;
                    if (degrees[nr][nc] == 1) {
                        queue.add(new Cell(nr, nc));
                    }
                }
            }
        }

        private boolean isInBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        private String finalizeResult() {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.') {
                        return "Not unique";
                    }
                }
                sb.append(new String(grid[i])).append("\n");
            }
            return sb.toString().trim();
        }
    }

    /**
     * Efficient reader for fast I/O operations.
     */
    private static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream s) {
            br = new BufferedReader(new InputStreamReader(s));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver that fills a grid of empty cells ('.') with arrows ('^', 'v', '<', '>')
 * such that each arrow points to exactly one adjacent cell, and that cell points back.
 * If a unique configuration cannot be determined, it outputs "Not unique".
 */
public class GridArrowSolver {

    // Directions: Up, Right, Down, Left
    private static final int[] ROW_OFFSETS = {-1, 0, 1, 0};
    private static final int[] COL_OFFSETS = {0, 1, 0, -1};

    // Arrows pointing from the current cell to the neighbor
    private static final char[] ARROW_OUT = {'^', '>', 'v', '<'};
    // Arrows pointing from the neighbor back to the current cell
    private static final char[] ARROW_IN = {'v', '<', '^', '>'};

    private final int rows;
    private final int cols;
    private final char[][] grid;

    public GridArrowSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
    }

    /**
     * Main logic to solve the grid using a topological-sort-like approach.
     * Cells with 0 or 1 available neighbors are "forced" and added to a queue.
     */
    public void solve(PrintWriter writer) {
        boolean isUnique = true;
        Deque<Integer> queue = new ArrayDeque<>();

        // Initial pass: find all empty cells with 1 or fewer neighbors
        for (int r = 1; r <= rows; r++) {
            for (int c = 1; c <= cols; c++) {
                if (grid[r][c] == '.' && countEmptyNeighbors(r, c) <= 1) {
                    queue.add(r * (cols + 2) + c);
                }
            }
        }

        while (!queue.isEmpty()) {
            int pos = queue.poll();
            int r = pos / (cols + 2);
            int c = pos % (cols + 2);

            // If cell is already processed, skip
            if (grid[r][c] != '.') {
                continue;
            }

            // Find the neighbor to pair with
            int targetR = -1;
            int targetC = -1;
            int directionIdx = -1;

            for (int i = 0; i < 4; i++) {
                int nr = r + ROW_OFFSETS[i];
                int nc = c + COL_OFFSETS[i];
                if (grid[nr][nc] == '.') {
                    targetR = nr;
                    targetC = nc;
                    directionIdx = i;
                    break;
                }
            }

            // If no neighbor found and cell is '.', it's an invalid/non-unique state
            if (targetR == -1) {
                isUnique = false;
                break;
            }

            // Place arrows to point at each other
            grid[r][c] = ARROW_OUT[directionIdx];
            grid[targetR][targetC] = ARROW_IN[directionIdx];

            // Update neighbors of the newly filled target cell
            for (int i = 0; i < 4; i++) {
                int nr = targetR + ROW_OFFSETS[i];
                int nc = targetC + COL_OFFSETS[i];
                if (grid[nr][nc] == '.' && countEmptyNeighbors(nr, nc) <= 1) {
                    queue.add(nr * (cols + 2) + nc);
                }
            }
        }

        // Final validation: ensure no empty cells remain
        if (isUnique) {
            for (int r = 1; r <= rows; r++) {
                for (int c = 1; c <= cols; c++) {
                    if (grid[r][c] == '.') {
                        isUnique = false;
                        break;
                    }
                }
                if (!isUnique) break;
            }
        }

        if (!isUnique) {
            writer.println("Not unique");
        } else {
            printGrid(writer);
        }
    }

    private int countEmptyNeighbors(int r, int c) {
        int count = 0;
        for (int i = 0; i < 4; i++) {
            if (grid[r + ROW_OFFSETS[i]][c + COL_OFFSETS[i]] == '.') {
                count++;
            }
        }
        return count;
    }

    private void printGrid(PrintWriter writer) {
        for (int r = 1; r <= rows; r++) {
            for (int c = 1; c <= cols; c++) {
                writer.print(grid[r][c]);
            }
            writer.println();
        }
    }

    public static void main(String[] args) throws IOException {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        int n = reader.nextInt();
        int m = reader.nextInt();

        // Use padding to avoid boundary checks
        char[][] grid = new char[n + 2][m + 2];
        for (char[] row : grid) {
            Arrays.fill(row, '*');
        }

        for (int i = 1; i <= n; i++) {
            String line = reader.next();
            for (int j = 1; j <= m; j++) {
                grid[i][j] = line.charAt(j - 1);
            }
        }

        GridArrowSolver solver = new GridArrowSolver(n, m, grid);
        solver.solve(writer);
        writer.close();
    }

    /**
     * Efficient utility for reading input.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;

/**
 * A refactored version of the puzzle solver.
 * The program solves a constraint-satisfaction puzzle where empty cells must be filled 
 * with arrows (^, v, <, >) pointing into obstacles or boundaries.
 */
public class Main {

    /**
     * Represents the different types of cells in the grid.
     */
    enum CellType {
        EMPTY,
        OBSTACLE('*'),
        UP('^'),
        DOWN('v'),
        LEFT('<'),
        RIGHT('>');

        private final char symbol;

        CellType() {
            this.symbol = ' ';
        }

        CellType(char symbol) {
            this.symbol = symbol;
        }

        public char getSymbol() {
            return symbol;
        }
    }

    /**
     * Represents a coordinate on the grid.
     */
    record Point(int r, int c) {}

    /**
     * Custom exception to signal that the puzzle solution is not unique or invalid.
     */
    static class UniquenessException extends Exception {
        public UniquenessException(String message) {
            super(message);
        }
    }

    /**
     * Encapsulates the grid and its bounds-checking logic.
     */
    static class Grid {
        private final CellType[][] cells;
        private final int rows;
        private final int cols;

        public Grid(int n, int m) {
            // Add padding of 1 around the grid to simplify boundary checks
            this.rows = n + 2;
            this.cols = m + 2;
            this.cells = new CellType[rows][cols];
            for (int i = 0; i < rows; i++) {
                Arrays.fill(cells[i], CellType.EMPTY);
            }
        }

        public void set(int r, int c, CellType type) {
            cells[r][c] = type;
        }

        public CellType get(int r, int c) {
            return cells[r][c];
        }

        public int getRows() {
            return rows;
        }

        public int getCols() {
            return cols;
        }
    }

    /**
     * Contains the logic for solving the puzzle.
     */
    static class PuzzleSolver {
        private final int n;
        private final int m;
        private final Grid grid;
        private final Deque<Point> worklist = new ArrayDeque<>();

        public PuzzleSolver(int n, int m, Grid grid) {
            this.n = n;
            this.m = m;
            this.grid = grid;
        }

        public void solve() {
            initializeBoundaries();

            try {
                // Initial pass to find all forced moves
                for (int i = 1; i <= n; i++) {
                    for (int j = 1; j <= m; j++) {
                        tryDoTry(i, j);
                    }
                }

                // Process the worklist of cells that need re-checking
                while (!worklist.isEmpty()) {
                    Point p = worklist.poll();
                    tryDoTry(p.r(), p.c());
                }

                // Validate that no empty cells remain
                validateSolution();

                printGrid();

            } catch (UniquenessException e) {
                System.out.print("Not unique");
            }
        }

        private void initializeBoundaries() {
            for (int i = 0; i < grid.getRows(); i++) {
                grid.set(i, 0, CellType.OBSTACLE);
                grid.set(i, grid.getCols() - 1, CellType.OBSTACLE);
            }
            for (int j = 0; j < grid.getCols(); j++) {
                grid.set(0, j, CellType.OBSTACLE);
                grid.set(n + 1, j, CellType.OBSTACLE);
            }
        }

        private void tryDoTry(int r, int c) throws UniquenessException {
            try {
                doTry(r, c);
            } catch (UniquenessException e) {
                throw e;
            }
        }

        private void addWorklist(int r, int c) {
            // Only add to worklist if the cell is currently EMPTY
            if (r >= 0 && r < grid.getRows() && c >= 0 && c < grid.getCols()) {
                if (grid.get(r, c) == CellType.EMPTY) {
                    worklist.add(new Point(r, c));
                }
            }
        }

        private void doTry(int r, int c) throws UniquenessException {
            if (grid.get(r, c) != CellType.EMPTY) return;

            int emptyNeighbors = countEmptyNeighbors(r, c);

            // If more than one neighbor is empty, the cell's state is not yet forced
            if (emptyNeighbors > 1) return;

            // If no neighbors are empty, the configuration is invalid/not unique
            if (emptyNeighbors == 0) throw new UniquenessException("Isolated empty cell");

            // Case: The only empty neighbor is ABOVE
            if (grid.get(r - 1, c) == CellType.EMPTY) {
                grid.set(r - 1, c, CellType.UP);
                grid.set(r, c, CellType.DOWN);
                addWorklist(r - 2, c);
                addWorklist(r - 1, c - 1);
                addWorklist(r - 1, c + 1);
            }
            // Case: The only empty neighbor is BELOW
            else if (grid.get(r + 1, c) == CellType.EMPTY) {
                grid.set(r, c, CellType.UP);
                grid.set(r + 1, c, CellType.DOWN);
                addWorklist(r + 2, c);
                addWorklist(r + 1, c - 1);
                addWorklist(r + 1, c + 1);
            }
            // Case: The only empty neighbor is LEFT
            else if (grid.get(r, c - 1) == CellType.EMPTY) {
                grid.set(r, c - 1, CellType.LEFT);
                grid.set(r, c, CellType.RIGHT);
                addWorklist(r, c - 2);
                addWorklist(r - 1, c - 1);
                addWorklist(r + 1, c - 1);
            }
            // Case: The only empty neighbor is RIGHT
            else if (grid.get(r, c + 1) == CellType.EMPTY) {
                grid.set(r, c + 1, CellType.RIGHT);
                grid.set(r, c, CellType.LEFT);
                addWorklist(r, c + 2);
                addWorklist(r - 1, c + 1);
                addWorklist(r + 1, c + 1);
            }
        }

        private int countEmptyNeighbors(int r, int c) {
            int count = 0;
            if (grid.get(r - 1, c) == CellType.EMPTY) count++;
            if (grid.get(r + 1, c) == CellType.EMPTY) count++;
            if (grid.get(r, c - 1) == CellType.EMPTY) count++;
            if (grid.get(r, c + 1) == CellType.EMPTY) count++;
            return count;
        }

        private void validateSolution() throws UniquenessException {
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= m; j++) {
                    if (grid.get(i, j) == CellType.EMPTY) {
                        throw new UniquenessException("Unfilled cells remain");
                    }
                }
            }
        }

        private void printGrid() {
            StringBuilder sb = new StringBuilder();
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= m; j++) {
                    sb.append(grid.get(i, j).getSymbol());
                }
                sb.append('\n');
            }
            System.out.print(sb.toString());
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) return;

        int n = scanner.nextInt();
        int m = scanner.nextInt();
        scanner.nextLine(); // consume leftover newline

        Grid grid = new Grid(n, m);
        for (int i = 1; i <= n; i++) {
            String line = scanner.nextLine();
            for (int j = 1; j <= m; j++) {
                if (line.charAt(j - 1) == '*') {
                    grid.set(i, j, CellType.OBSTACLE);
                }
            }
        }

        PuzzleSolver solver = new PuzzleSolver(n, m, grid);
        solver.solve();
        scanner.close();
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver for the Drazil and Tiles problem.
 * The goal is to fill empty grid cells ('.') with arrows such that 
 * every arrow points to another arrow cell.
 */
public class TileSolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int n = reader.nextInt();
            int m = reader.nextInt();
            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                grid[i] = reader.nextString().toCharArray();
            }

            GridSolver solver = new GridSolver(n, m, grid);
            String result = solver.solve();
            writer.println(result);
        } catch (Exception e) {
            writer.println("Error processing input: " + e.getMessage());
        } finally {
            writer.close();
        }
    }

    /**
     * Encapsulates the logic for solving the grid puzzle.
     */
    static class GridSolver {
        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final int[][] degree;
        private final Deque<Coordinate> queue = new ArrayDeque<>();
        private int remainingEmptyCells;

        private static final int[][] DIRECTIONS = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

        /**
         * Represents a cell in the grid.
         */
        private record Coordinate(int row, int col) {}

        public GridSolver(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            // Padding the grid to avoid boundary checks during degree calculation
            this.degree = new int[rows + 2][cols + 2];
            this.remainingEmptyCells = 0;
            initializeDegrees();
        }

        private void initializeDegrees() {
            // Create a padded grid for easier neighbor access
            char[][] paddedGrid = new char[rows + 2][cols + 2];
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    paddedGrid[i + 1][j + 1] = grid[i][j];
                }
            }

            for (int i = 1; i <= rows; i++) {
                for (int j = 1; j <= cols; j++) {
                    if (paddedGrid[i][j] == '.') {
                        remainingEmptyCells++;
                        int d = 0;
                        for (int[] dir : DIRECTIONS) {
                            if (paddedGrid[i + dir[0]][j + dir[1]] == '.') {
                                d++;
                            }
                        }
                        degree[i][j] = d;
                        if (d == 1) {
                            queue.offer(new Coordinate(i, j));
                        }
                    }
                }
            }

            // Transfer padding back to the internal grid representation logic
            // We will use the padded logic internally via the degree array.
            this.internalGrid = paddedGrid;
        }

        private char[][] internalGrid;

        public String solve() {
            while (!queue.isEmpty()) {
                Coordinate curr = queue.poll();
                int r = curr.row();
                int c = curr.col();

                // Skip if the cell is no longer a '.'
                if (internalGrid[r][c] != '.') continue;
                // A leaf must have exactly one '.' neighbor
                if (degree[r][c] != 1) continue;

                Coordinate neighbor = findOnlyNeighbor(r, c);
                if (neighbor == null) continue;

                // Pair the current cell and its neighbor
                pairCells(r, c, neighbor.row(), neighbor.col());
                remainingEmptyCells -= 2;

                // When we pair them, the neighbor is effectively "removed" from the graph.
                // We must update the degrees of all cells surrounding the neighbor.
                int nr = neighbor.row();
                int nc = neighbor.col();
                degree[nr][nc] = 0; 

                for (int[] dir : DIRECTIONS) {
                    int nnr = nr + dir[0];
                    int nnc = nc + dir[1];
                    degree[nnr][nnc]--;
                    if (degree[nnr][nnc] == 1) {
                        queue.offer(new Coordinate(nnr, nnc));
                    }
                }
            }

            if (remainingEmptyCells != 0) {
                return "Not unique";
            } else {
                return formatGrid();
            }
        }

        private Coordinate findOnlyNeighbor(int r, int c) {
            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (internalGrid[nr][nc] == '.') {
                    return new Coordinate(nr, nc);
                }
            }
            return null;
        }

        private void pairCells(int r1, int c1, int r2, int c2) {
            // Set arrows so they point at each other
            if (r1 == r2) {
                if (c1 < c2) { // Neighbor is to the right
                    internalGrid[r1][c1] = '>';
                    internalGrid[r2][c2] = '<';
                } else { // Neighbor is to the left
                    internalGrid[r1][c1] = '<';
                    internalGrid[r2][c2] = '>';
                }
            } else {
                if (r1 < r2) { // Neighbor is below
                    internalGrid[r1][c1] = 'v';
                    internalGrid[r2][c2] = '^';
                } else { // Neighbor is above
                    internalGrid[r1][c1] = '^';
                    internalGrid[r2][c2] = 'v';
                }
            }
        }

        private String formatGrid() {
            StringBuilder sb = new StringBuilder();
            for (int i = 1; i <= rows; i++) {
                for (int j = 1; j <= cols; j++) {
                    sb.append(internalGrid[i][j]);
                }
                sb.append("\n");
            }
            return sb.toString().trim();
        }
    }

    /**
     * High-performance input reader.
     */
    static class FastReader {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (numChars == -1) throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) return -1;
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res = res * 10 + (c - '0');
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public String nextString() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = read();
            } while (!isSpaceChar(c));
            return sb.toString();
        }

        private boolean isSpaceChar(int c) {
            return c == -1 || c == ' ' || c == '\n' || c == '\r' || c == '\t';
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver for the Grid Arrow Puzzle.
 * The goal is to determine if there is a unique way to fill empty cells ('.')
 * with arrows such that each arrow points to an adjacent cell, effectively
 * pairing up all empty cells.
 */
public class GridArrowSolver {

    // Direction vectors for traversing neighbors (Up, Down, Left, Right)
    private static final int[] DIRECTION_X = {0, 0, -1, 1};
    private static final int[] DIRECTION_Y = {-1, 1, 0, 0};

    // Arrow character mappings corresponding to the directions above
    private static final char[] ARROW_A = {'>', '<', 'v', '^'};
    private static final char[] ARROW_B = {'<', '>', '^', 'v'};

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int[] neighborCount;
    private final boolean[] isQueued;

    public GridArrowSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.neighborCount = new int[rows * cols];
        this.isQueued = new boolean[rows * cols];
    }

    /**
     * Executes the greedy forced-move algorithm to solve the puzzle.
     * 
     * @return true if the solution is unique, false otherwise.
     */
    public boolean solve() {
        Queue<Integer> processingQueue = new LinkedList<>();

        // 1. Initialization: Calculate degrees (neighboring dots) for all empty cells
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    int neighbors = 0;
                    for (int k = 0; k < 4; k++) {
                        if (isDot(r + DIRECTION_X[k], c + DIRECTION_Y[k])) {
                            neighbors++;
                        }
                    }
                    int index = r * cols + c;
                    neighborCount[index] = neighbors;

                    // If a cell has only one possible neighbor, it is a "forced" move
                    if (neighbors == 1) {
                        isQueued[index] = true;
                        processingQueue.add(index);
                    }
                }
            }
        }

        // 2. Constraint Propagation: Process the queue of forced cells
        while (!processingQueue.isEmpty()) {
            int currentIdx = processingQueue.poll();
            int r = currentIdx / cols;
            int c = currentIdx % cols;

            boolean alreadyMatched = (grid[r][c] != '.');

            for (int k = 0; k < 4; k++) {
                int nr = r + DIRECTION_X[k];
                int nc = c + DIRECTION_Y[k];

                // Only interact with neighbors that are currently empty cells
                if (isDot(nr, nc)) {
                    int neighborIdx = nr * cols + nc;

                    // Decrement the degree of the valid neighbor
                    neighborCount[neighborIdx]--;
                    if (neighborCount[neighborIdx] == 1) {
                        if (!isQueued[neighborIdx]) {
                            isQueued[neighborIdx] = true;
                            processingQueue.add(neighborIdx);
                        }
                    }

                    // If the current cell hasn't been assigned an arrow yet, pair it with this neighbor
                    if (!alreadyMatched) {
                        alreadyMatched = true;
                        grid[r][c] = ARROW_A[k];
                        grid[nr][nc] = ARROW_B[k];

                        // The neighbor is now an arrow and should be added to the queue to propagate its effect
                        if (!isQueued[neighborIdx]) {
                            isQueued[neighborIdx] = true;
                            processingQueue.add(neighborIdx);
                        }
                    }
                }
            }
        }

        // 3. Verification: If any empty cells remain, the solution is not unique or impossible
        return areAllCellsFilled();
    }

    private boolean isDot(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] == '.';
    }

    private boolean areAllCellsFilled() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    return false;
                }
            }
        }
        return true;
    }

    public void printGrid(PrintWriter out) {
        for (char[] row : grid) {
            out.println(new String(row));
        }
    }

    public static void main(String[] args) throws IOException {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = reader.nextInt();
        int m = reader.nextInt();
        char[][] grid = new char[n][m];

        for (int i = 0; i < n; i++) {
            grid[i] = reader.next().toCharArray();
        }

        GridArrowSolver solver = new GridArrowSolver(n, m, grid);

        if (solver.solve()) {
            solver.printGrid(out);
        } else {
            out.println("Not unique");
        }

        out.flush();
        out.close();
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream s) {
            br = new BufferedReader(new InputStreamReader(s));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

