/**
 * Handles the logic of filling dots in a grid with arrows such that 
 * every arrow points to a neighbor.
 */
class GridSolver {
    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int[][] degrees;

    /**
     * Represents a movement direction in the grid, 
     * linking offsets to the corresponding arrow character.
     */
    private enum Direction {
        UP(-1, 0, '^'),
        DOWN(1, 0, 'v'),
        LEFT(0, -1, '<'),
        RIGHT(0, 1, '>');

        final int dr, dc;
        final char arrow;

        Direction(int dr, int dc, char arrow) {
            this.dr = dr;
            this.dc = dc;
            this.arrow = arrow;
        }

        public static Direction getDirectionFromOffset(int dr, int dc) {
            for (Direction dir : values()) {
                if (dir.dr == dr && dir.dc == dc) {
                    return dir;
                }
            }
            return null;
        }
    }

    /**
     * Simple data carrier for grid coordinates.
     */
    private record Point(int r, int c) {}

    public GridSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.degrees = new int[rows][cols];
    }

    /**
     * Executes the solver algorithm and writes the result to the provided PrintWriter.
     * @param out The output stream to write results to.
     */
    public void solve(PrintWriter out) {
        Queue<Point> queue = new LinkedList<>();
        int dotsCount = 0;

        // Phase 1: Calculate initial degrees (number of adjacent dot neighbors)
        // and identify "leaf" dots (degree 1) to start the pruning process.
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    dotsCount++;
                    int deg = countDotNeighbors(r, c);
                    degrees[r][c] = deg;
                    if (deg == 1) {
                        queue.add(new Point(r, c));
                    }
                }
            }
        }

        // Phase 2: Process the queue to pair dots.
        while (!queue.isEmpty()) {
            Point current = queue.poll();

            // If this cell was already filled by a neighbor's pairing, skip it.
            if (grid[current.r][current.c] != '.') {
                continue;
            }

            Point neighbor = findSingleDotNeighbor(current.r, current.c);
            if (neighbor != null) {
                // Pair current dot with its only available dot neighbor.
                applyPairing(current, neighbor);
                dotsCount -= 2;

                // Since the neighbor is no longer a dot, update the degrees of its neighbors.
                updateNeighborDegrees(neighbor, queue);
            }
        }

        // Phase 3: Output results.
        if (dotsCount != 0) {
            out.println("Not unique");
        } else {
            for (int i = 0; i < rows; i++) {
                out.println(new String(grid[i]));
            }
        }
    }

    private void applyPairing(Point p1, Point p2) {
        grid[p1.r][p1.c] = getDirectionTo(p1, p2).arrow;
        grid[p2.r][p2.c] = getDirectionTo(p2, p1).arrow;
    }

    private void updateNeighborDegrees(Point p, Queue<Point> queue) {
        for (Direction d : Direction.values()) {
            int nr = p.r + d.dr;
            int nc = p.c + d.dc;

            if (isInBounds(nr, nc) && grid[nr][nc] == '.') {
                degrees[nr][nc]--;
                if (degrees[nr][nc] == 1) {
                    queue.add(new Point(nr, nc));
                }
            }
        }
    }

    private int countDotNeighbors(int r, int c) {
        int count = 0;
        for (Direction d : Direction.values()) {
            int nr = r + d.dr;
            int nc = c + d.dc;
            if (isInBounds(nr, nc) && grid[nr][nc] == '.') {
                count++;
            }
        }
        return count;
    }

    private Point findSingleDotNeighbor(int r, int c) {
        for (Direction d : Direction.values()) {
            int nr = r + d.dr;
            int nc = c + d.dc;
            if (isInBounds(nr, nc) && grid[nr][nc] == '.') {
                return new Point(nr, nc);
            }
        }
        return null;
    }

    private Direction getDirectionTo(Point from, Point to) {
        return Direction.getDirectionFromOffset(to.r - from.r, to.c - from.c);
    }

    private boolean isInBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.*;

/**
 * A solver for a grid-based puzzle where empty cells ('.') must be paired 
 * with adjacent empty cells and assigned direction characters pointing away from each other.
 */
public class GridPairSolver {

    private static final char EMPTY = '.';

    private final int rows;
    private final int cols;
    private final char[][] grid;

    /**
     * Constructs a new solver with the given grid dimensions and content.
     *
     * @param rows Number of rows in the grid.
     * @param cols Number of columns in the grid.
     * @param grid The initial character grid.
     */
    public GridPairSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
    }

    /**
     * Executes the solving algorithm to fill the grid.
     */
    public void solve() {
        Queue<Point> queue = new LinkedList<>();

        // Step 1: Identify all initial "leaf" cells.
        // A leaf cell is an empty cell with exactly one empty neighbor.
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (isCellEmpty(r, c) && getEmptyNeighborCount(r, c) == 1) {
                    queue.add(new Point(r, c));
                }
            }
        }

        // Step 2: Process the queue to propagate pairings through the grid.
        while (!queue.isEmpty()) {
            Point current = queue.poll();

            // If the cell was already paired by a previous operation, skip it.
            if (!isCellEmpty(current.r, current.c)) {
                continue;
            }

            List<Point> neighbors = getEmptyNeighbors(current.r, current.c);

            // If the cell still has exactly one empty neighbor, they must form a pair.
            if (neighbors.size() == 1) {
                Point neighbor = neighbors.get(0);
                fillPair(current, neighbor);

                // After filling these two cells, their neighbors' degrees change.
                // We add them to the queue to check if they have now become leaf cells.
                for (Point p : getEmptyNeighbors(current.r, current.c)) {
                    queue.add(p);
                }
                for (Point p : getEmptyNeighbors(neighbor.r, neighbor.c)) {
                    queue.add(p);
                }
            }
        }

        printResult();
    }

    private boolean isCellEmpty(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] == EMPTY;
    }

    private int getEmptyNeighborCount(int r, int c) {
        return getEmptyNeighbors(r, c).size();
    }

    /**
     * Retrieves all adjacent cells that are currently empty.
     */
    private List<Point> getEmptyNeighbors(int r, int c) {
        List<Point> neighbors = new ArrayList<>();
        int[] dr = {-1, 1, 0, 0}; // Row directions: up, down, left, right
        int[] dc = {0, 0, -1, 1}; // Col directions: up, down, left, right

        for (int i = 0; i < 4; i++) {
            int nr = r + dr[i];
            int nc = c + dc[i];
            if (isCellEmpty(nr, nc)) {
                neighbors.add(new Point(nr, nc));
            }
        }
        return neighbors;
    }

    /**
     * Fills two adjacent cells with direction characters pointing away from each other.
     */
    private void fillPair(Point p1, Point p2) {
        if (p1.r == p2.r) { 
            // Horizontal pair: assign '<' to the left cell and '>' to the right cell.
            int minCol = Math.min(p1.c, p2.c);
            int maxCol = Math.max(p1.c, p2.c);
            grid[p1.r][minCol] = '<';
            grid[p1.r][maxCol] = '>';
        } else { 
            // Vertical pair: assign '^' to the top cell and 'v' to the bottom cell.
            int minRow = Math.min(p1.r, p2.r);
            int maxRow = Math.max(p1.r, p2.r);
            grid[minRow][p1.c] = '^';
            grid[maxRow][p1.c] = 'v';
        }
    }

    /**
     * Prints the grid if fully solved, otherwise prints "Not unique".
     */
    private void printResult() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == EMPTY) {
                    System.out.println("Not unique");
                    return;
                }
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int r = 0; r < rows; r++) {
            sb.append(grid[r]).append('\n');
        }
        System.out.print(sb.toString());
    }

    /**
     * Lightweight representation of a grid coordinate.
     */
    private static class Point {
        final int r, c;
        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    public static void main(String[] args) {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String line = br.readLine();
            if (line == null || line.trim().isEmpty()) return;

            String[] dims = line.trim().split("\\s+");
            int rows = Integer.parseInt(dims[0]);
            int cols = Integer.parseInt(dims[1]);

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String rowLine = br.readLine();
                if (rowLine != null) {
                    grid[i] = rowLine.toCharArray();
                }
            }

            GridPairSolver solver = new GridPairSolver(rows, cols, grid);
            solver.solve();

        } catch (IOException | NumberFormatException e) {
            // Silent fail or log error for malformed input
        }
    }
}

