/**
 * Represents a 2D coordinate on the grid.
 */
record Point(int row, int col) {}

/**
 * Encapsulates direction logic, including movement deltas and character mappings.
 */
enum Direction {
    RIGHT(0, 1, '<', '>'),
    LEFT(0, -1, '>', '<'),
    DOWN(1, 0, '^', 'v'),
    UP(-1, 0, 'v', '^');

    final int deltaRow;
    final int deltaCol;
    final char beginChar;
    final char endChar;

    Direction(int deltaRow, int deltaCol, char beginChar, char endChar) {
        this.deltaRow = deltaRow;
        this.deltaCol = deltaCol;
        this.beginChar = beginChar;
        this.endChar = endChar;
    }

    static Direction fromDelta(int dr, int dc) {
        for (Direction d : values()) {
            if (d.deltaRow == dr && d.deltaCol == dc) return d;
        }
        return null;
    }
}

/**
 * Core logic for solving the grid-based arrow puzzle.
 */
class PuzzleSolver {
    private final FastReader reader;
    private final PrintWriter out;

    public PuzzleSolver(FastReader reader, PrintWriter out) {
        this.reader = reader;
        this.out = out;
    }

    public void solve() throws IOException {
        int rows = reader.nextInt();
        int cols = reader.nextInt();
        char[][] grid = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            grid[i] = reader.next().toCharArray();
        }

        Queue<Point> queue = new ArrayDeque<>();

        // Initial pass: find cells that have exactly one empty neighbor
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (countEmptyNeighbors(grid, r, c, rows, cols) == 1) {
                    queue.add(new Point(r, c));
                }
            }
        }

        while (!queue.isEmpty()) {
            Point p = queue.poll();

            // If the cell was already processed or is no longer empty, skip
            if (grid[p.row()][p.col()] != '.') {
                continue;
            }

            Direction targetDir = null;
            int emptyNeighbors = 0;

            // Find which direction the single empty neighbor is located
            for (Direction d : Direction.values()) {
                int nr = p.row() + d.deltaRow;
                int nc = p.col() + d.deltaCol;

                if (isValid(nr, nc, rows, cols) && grid[nr][nc] == '.') {
                    emptyNeighbors++;
                    targetDir = d;
                }
            }

            // If not exactly one neighbor, the solution is not unique/valid
            if (emptyNeighbors != 1 || targetDir == null) {
                out.println("Not unique");
                return;
            }

            // Apply the arrows
            grid[p.row()][p.col()] = targetDir.beginChar;
            int targetR = p.row() + targetDir.deltaRow;
            int targetC = p.col() + targetDir.deltaCol;
            grid[targetR][targetC] = targetDir.endChar;

            // Re-check neighbors of the updated target cell
            for (Direction d : Direction.values()) {
                int nr = targetR + d.deltaRow;
                int nc = targetC + d.deltaCol;
                if (isValid(nr, nc, rows, cols) && countEmptyNeighbors(grid, nr, nc, rows, cols) == 1) {
                    queue.add(new Point(nr, nc));
                }
            }
        }

        // Final verification: check if any empty cells remain
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    out.println("Not unique");
                    return;
                }
            }
        }

        // Output the completed grid
        for (int r = 0; r < rows; r++) {
            out.println(new String(grid[r]));
        }
    }

    private int countEmptyNeighbors(char[][] grid, int r, int c, int rows, int cols) {
        if (grid[r][c] != '.') {
            return 0;
        }
        int count = 0;
        for (Direction d : Direction.values()) {
            int nr = r + d.deltaRow;
            int nc = c + d.deltaCol;
            if (isValid(nr, nc, rows, cols) && grid[nr][nc] == '.') {
                count++;
            }
        }
        return count;
    }

    private boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

/**
 * Utility class for fast input parsing.
