import java.util.*;
import java.io.*;

/**
 * Refactored solution for the grid arrow construction problem.
 * The goal is to fill every '.' cell with an arrow such that every arrow 
 * points to an adjacent cell, and the configuration is unique.
 */
public class GridArrowConstructor {

    // Directional offsets for: Right, Left, Down, Up
    private static final int[] DR = {0, 0, 1, -1};
    private static final int[] DC = {1, -1, 0, 0};

    public static void main(String[] args) {
        FastReader sc = new FastReader(System.in);

        int n = sc.nextInt();
        int m = sc.nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = sc.next().toCharArray();
        }

        if (canFillUniquely(n, m, grid)) {
            printGrid(grid);
        } else {
            System.out.println("Not unique");
        }
    }

    /**
     * Uses a degree-based propagation algorithm to determine if the grid
     * can be uniquely filled with arrows.
     *
     * @param n Number of rows
     * @param m Number of columns
     * @param grid The input grid
     * @return true if a unique configuration is found, false otherwise
     */
    private static boolean canFillUniquely(int n, int m, char[][] grid) {
        int[][] degree = new int[n][m];

        // 1. Calculate initial degrees (number of '.' neighbors)
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (grid[r][c] == '.') {
                    degree[r][c] = countEmptyNeighbors(r, c, n, m, grid);
                }
            }
        }

        // 2. Initialize queue with "dead ends" (cells with only one '.' neighbor)
        Queue<int[]> queue = new ArrayDeque<>();
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (grid[r][c] == '.' && degree[r][c] == 1) {
                    queue.add(new int[]{r, c});
                }
            }
        }

        // 3. Propagate arrows
        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            int r = curr[0];
            int c = curr[1];

            if (grid[r][c] != '.') continue;

            if (degree[r][c] == 1) {
                // Case: The cell has exactly one '.' neighbor. It MUST point to it.
                int[] target = findEmptyNeighbor(r, c, n, m, grid);
                if (target != null) {
                    int tr = target[0];
                    int tc = target[1];
                    grid[r][c] = getDirectionChar(r, c, tr, tc);

                    // Decrement degree of the neighbor
                    degree[tr][tc]--;
                    // If neighbor becomes a dead end, add to queue
                    if (degree[tr][tc] <= 1) {
                        queue.add(new int[]{tr, tc});
                    }
                }
            } else if (degree[r][c] == 0) {
                // Case: The cell has no '.' neighbors. It must point to a cell that was just filled.
                // For uniqueness, there must be exactly one non-'.' neighbor.
                int[] target = findOnlyNonEmptyNeighbor(r, c, n, m, grid);
                if (target == null) return false; // Not unique or invalid

                int tr = target[0];
                int tc = target[1];
                grid[r][c] = getDirectionChar(r, c, tr, tc);
            } else {
                // If degree > 1 and not in queue, it's part of a cycle and not uniquely determined.
                continue;
            }
        }

        // 4. Verify that no '.' remains
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (grid[r][c] == '.') return false;
            }
        }

        return true;
    }

    private static int countEmptyNeighbors(int r, int c, int n, int m, char[][] grid) {
        int count = 0;
        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];
            if (isInBounds(nr, nc, n, m) && grid[nr][nc] == '.') {
                count++;
            }
        }
        return count;
    }

    private static int[] findEmptyNeighbor(int r, int c, int n, int m, char[][] grid) {
        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];
            if (isInBounds(nr, nc, n, m) && grid[nr][nc] == '.') {
                return new int[]{nr, nc};
            }
        }
        return null;
    }

    private static int[] findOnlyNonEmptyNeighbor(int r, int c, int n, int m, char[][] grid) {
        int count = 0;
        int[] lastFound = null;
        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];
            if (isInBounds(nr, nc, n, m) && grid[nr][nc] != '.') {
                count++;
                lastFound = new int[]{nr, nc};
            }
        }
        // For uniqueness, a degree-0 cell must have exactly one non-empty neighbor to point to
        return (count == 1) ? lastFound : null;
    }

    private static char getDirectionChar(int r, int c, int tr, int tc) {
        if (tr == r) {
            return (tc > c) ? '>' : '<';
        } else {
            return (tr > r) ? 'v' : '^';
        }
    }

    private static boolean isInBounds(int r, int c, int n, int m) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }

    private static void printGrid(char[][] grid) {
        StringBuilder sb = new StringBuilder();
        for (char[] row : grid) {
            sb.append(new String(row)).append('\n');
        }
        System.out.print(sb.toString());
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * Solver for the grid arrow placement problem.
 * The goal is to fill empty cells ('.') with arrows such that every cell 
 * is part of a unique cycle/path.
 */
public class CF515D {

    // Directional offsets for Row and Column movements
    private static final int[] ROW_DIRECTIONS = {0, 0, 1, -1};
    private static final int[] COL_DIRECTIONS = {1, -1, 0, 0};

    // Arrow characters corresponding to the direction index
    private static final char[] PRIMARY_CHARS = {'<', '>', '^', 'v'};
    private static final char[] SECONDARY_CHARS = {'>', '<', 'v', '^'};

    private int rows;
    private int cols;
    private char[][] grid;
    private int emptyCellCount;
    private final Deque<CellState> processingQueue = new ArrayDeque<>();

    /**
     * Represents a cell that has been identified as having only one possible
     * empty neighbor, forcing a specific arrow placement.
     */
    private static class CellState {
        final int r;
        final int c;
        final int neighborDirIdx;

        CellState(int r, int c, int neighborDirIdx) {
            this.r = r;
            this.c = c;
            this.neighborDirIdx = neighborDirIdx;
        }
    }

    /**
     * Fast I/O utility for efficient reading.
     */
    private static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) {
        new CF515D().solve();
    }

    public void solve() {
        FastReader reader = new FastReader();
        PrintWriter out = new PrintWriter(System.out);

        String firstLine = reader.next();
        if (firstLine == null) return;

        rows = Integer.parseInt(firstLine);
        cols = reader.nextInt();
        grid = new char[rows][cols];
        emptyCellCount = 0;

        for (int i = 0; i < rows; i++) {
            grid[i] = reader.next().toCharArray();
        }

        // Initial pass: find all empty cells that are forced by having only one empty neighbor
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.') {
                    emptyCellCount++;
                    checkAndEnqueueForcedCell(i, j);
                }
            }
        }

        processForcedPlacements();

        if (emptyCellCount > 0) {
            out.println("Not unique");
        } else {
            for (int i = 0; i < rows; i++) {
                out.println(new String(grid[i]));
            }
        }
        out.flush();
        out.close();
    }

    /**
     * Iteratively processes the queue of forced arrow placements.
     */
    private void processForcedPlacements() {
        while (!processingQueue.isEmpty() && emptyCellCount > 0) {
            CellState state = processingQueue.poll();
            int r = state.r;
            int c = state.c;
            int k = state.neighborDirIdx;

            int nr = r + ROW_DIRECTIONS[k];
            int nc = c + COL_DIRECTIONS[k];

            // If both the current cell and its target neighbor are still empty, pair them
            if (isWithinBounds(r, c) && isWithinBounds(nr, nc) 
                    && grid[r][c] == '.' && grid[nr][nc] == '.') {

                grid[r][c] = PRIMARY_CHARS[k];
                grid[nr][nc] = SECONDARY_CHARS[k];
                emptyCellCount -= 2;

                // After filling cells, neighbors of the newly filled cells might now be forced
                updateNeighbors(r, c);
                updateNeighbors(nr, nc);
            }
        }
    }

    /**
     * Checks the 4 neighbors of a cell. If a neighbor is empty and now has 
     * only one empty neighbor itself, it is added to the queue.
     */
    private void updateNeighbors(int r, int c) {
        for (int d = 0; d < 4; d++) {
            int adjR = r + ROW_DIRECTIONS[d];
            int adjC = c + COL_DIRECTIONS[d];
            if (isWithinBounds(adjR, adjC) && grid[adjR][adjC] == '.') {
                checkAndEnqueueForcedCell(adjR, adjC);
            }
        }
    }

    /**
     * Determines if a cell has exactly one empty neighbor.
     * If so, it enqueues the cell and the direction of that neighbor.
     */
    private void checkAndEnqueueForcedCell(int r, int c) {
        int emptyNeighborCount = 0;
        int lastNeighborDirIdx = -1;

        for (int k = 0; k < 4; k++) {
            int nr = r + ROW_DIRECTIONS[k];
            int nc = c + COL_DIRECTIONS[k];
            if (isWithinBounds(nr, nc) && grid[nr][nc] == '.') {
                emptyNeighborCount++;
                lastNeighborDirIdx = k;
            }
        }

        if (emptyNeighborCount == 1) {
            processingQueue.add(new CellState(r, c, lastNeighborDirIdx));
        }
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

import java.util.*;
import java.io.*;

/**
 * Solver for the Arrow Grid problem.
 * The goal is to fill all '.' cells in a grid with arrows (<, >, ^, v)
 * such that every cell's configuration is unique and forced by its neighbors.
 */
public class ArrowGridSolver {

    private static final int[] ROW_OFFSETS = {1, -1, 0, 0};
    private static final int[] COL_OFFSETS = {0, 0, 1, -1};

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int[][] degreeMap;

    /**
     * Represents a coordinate in the grid.
     */
    private record Cell(int row, int col) {}

    /**
     * Custom reader for efficient input processing.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }

    public ArrowGridSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.degreeMap = new int[rows][cols];
    }

    /**
     * Executes the solver logic.
     * @return The resulting grid as a string or "Not unique" if no unique solution exists.
     */
    public String solve() {
        initializeDegrees();

        Queue<Cell> queue = new LinkedList<>();

        // Initial check for impossible configurations and identification of forced cells
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    if (degreeMap[r][c] == 0) {
                        return "Not unique";
                    }
                    if (degreeMap[r][c] == 1) {
                        queue.add(new Cell(r, c));
                    }
                }
            }
        }

        // Process cells with only one possible exit neighbor
        while (!queue.isEmpty()) {
            Cell current = queue.poll();
            int r = current.row();
            int c = current.col();

            // Skip if this cell was already filled by another forced connection
            if (grid[r][c] != '.') {
                continue;
            }

            // If a cell is '.' but has no '.' neighbors, it cannot be filled uniquely
            if (degreeMap[r][c] == 0) {
                return "Not unique";
            }

            // Find the single available neighbor
            Cell neighbor = findOnlyNeighbor(r, c);
            if (neighbor == null) {
                return "Not unique";
            }

            // Assign arrows to both cells
            applyArrows(r, c, neighbor.row(), neighbor.col());

            // Update degrees of neighbors affected by the change
            updateNeighborsAndQueue(r, c, queue);
            updateNeighborsAndQueue(neighbor.row(), neighbor.col(), queue);
        }

        // Verify if any '.' cells remain unvisited
        if (containsUnfilledCells()) {
            return "Not unique";
        }

        return formatGrid();
    }

    private void initializeDegrees() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                calculateDegree(r, c);
            }
        }
    }

    private void calculateDegree(int r, int c) {
        int count = 0;
        for (int i = 0; i < 4; i++) {
            int nr = r + ROW_OFFSETS[i];
            int nc = c + COL_OFFSETS[i];
            if (isValid(nr, nc) && grid[nr][nc] == '.') {
                count++;
            }
        }
        degreeMap[r][c] = count;
    }

    private Cell findOnlyNeighbor(int r, int c) {
        for (int i = 0; i < 4; i++) {
            int nr = r + ROW_OFFSETS[i];
            int nc = c + COL_OFFSETS[i];
            if (isValid(nr, nc) && grid[nr][nc] == '.') {
                return new Cell(nr, nc);
            }
        }
        return null;
    }

    private void applyArrows(int r1, int c1, int r2, int c2) {
        if (r1 == r2) { // Horizontal connection
            int minC = Math.min(c1, c2);
            int maxC = Math.max(c1, c2);
            grid[r1][minC] = '<';
            grid[r1][maxC] = '>';
        } else { // Vertical connection
            int minR = Math.min(r1, r2);
            int maxR = Math.max(r1, r2);
            grid[minR][c1] = '^';
            grid[maxR][c1] = 'v';
        }
    }

    private void updateNeighborsAndQueue(int r, int c, Queue<Cell> queue) {
        // Recalculate the degree of the current cell (now an arrow)
        calculateDegree(r, c);

        // Update all adjacent neighbors because the current cell is no longer '.'
        for (int i = 0; i < 4; i++) {
            int nr = r + ROW_OFFSETS[i];
            int nc = c + COL_OFFSETS[i];
            if (isValid(nr, nc) && grid[nr][nc] == '.') {
                calculateDegree(nr, nc);
                if (degreeMap[nr][nc] == 1) {
                    queue.add(new Cell(nr, nc));
                }
            }
        }
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private boolean containsUnfilledCells() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') return true;
            }
        }
        return false;
    }

    private String formatGrid() {
        StringBuilder sb = new StringBuilder();
        for (int r = 0; r < rows; r++) {
            sb.append(grid[r]);
            sb.append("\n");
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        FastReader sc = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        String nStr = sc.next();
        if (nStr == null) return;
        int n = Integer.parseInt(nStr);
        int m = sc.nextInt();

        char[][] inputGrid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String rowStr = sc.next();
            inputGrid[i] = rowStr.toCharArray();
        }

        ArrowGridSolver solver = new ArrowGridSolver(n, m, inputGrid);
        out.print(solver.solve());
        out.flush();
        out.close();
    }
}

import java.util.*;

/**
 * A solver for a grid-based domino placement puzzle where certain moves are forced.
 * The solver identifies cells that have only one possible neighbor to form a domino.
 */
public class DominoSolver {

    // Direction vectors for orthogonal movement (Right, Left, Down, Up)
    private static final int[] DR = {0, 0, 1, -1};
    private static final int[] DC = {1, -1, 0, 0};

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final Deque<DominoPair> forcedPairsQueue = new ArrayDeque<>();

    /**
     * Represents a coordinate in the grid.
     */
    private static class Point {
        final int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Represents a pair of points that must be connected as a domino.
     */
    private static class DominoPair {
        final Point p1;
        final Point p2;

        DominoPair(Point p1, Point p2) {
            this.p1 = p1;
            this.p2 = p2;
        }
    }

    public DominoSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
    }

    /**
     * Executes the solver logic.
     */
    public void solve() {
        // Step 1: Initial scan to find all cells that are immediately forced
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    findAndEnqueueForcedPair(r, c);
                }
            }
        }

        // Step 2: Process the queue of forced domino placements
        while (!forcedPairsQueue.isEmpty()) {
            DominoPair pair = forcedPairsQueue.poll();
            Point p1 = pair.p1;
            Point p2 = pair.p2;

            // If either cell in the pair has already been filled, skip processing
            if (grid[p1.r][p1.c] != '.' || grid[p2.r][p2.c] != '.') {
                continue;
            }

            applyDomino(p1, p2);

            // Step 3: After placing a domino, check the neighbors of the affected cells
            // for new forced moves.
            checkNeighbors(p1);
            checkNeighbors(p2);
        }

        printResult();
    }

    /**
     * Checks if a cell is out of bounds or is an obstacle (not an empty '.').
     */
    private boolean isObstacle(int r, int c) {
        if (r < 0 || r >= rows || c < 0 || c >= cols) {
            return true;
        }
        return grid[r][c] != '.';
    }

    /**
     * If a cell has exactly one empty neighbor, it is a forced move.
     */
    private void findAndEnqueueForcedPair(int r, int c) {
        if (grid[r][c] != '.') return;

        int emptyNeighborCount = 0;
        int neighborRow = -1;
        int neighborCol = -1;

        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];

            if (!isObstacle(nr, nc)) {
                emptyNeighborCount++;
                neighborRow = nr;
                neighborCol = nc;
            }
        }

        // If there is exactly one neighbor that is '.', this cell must pair with it.
        if (emptyNeighborCount == 1) {
            forcedPairsQueue.add(new DominoPair(new Point(r, c), new Point(neighborRow, neighborCol)));
        }
    }

    private void checkNeighbors(Point p) {
        for (int i = 0; i < 4; i++) {
            int nr = p.r + DR[i];
            int nc = p.c + DC[i];
            if (!isObstacle(nr, nc)) {
                findAndEnqueueForcedPair(nr, nc);
            }
        }
    }

    /**
     * Marks the two cells with direction characters based on their relative position.
     */
    private void applyDomino(Point p1, Point p2) {
        if (p1.r != p2.r) {
            // Vertical domino
            if (p1.r > p2.r) {
                grid[p2.r][p2.c] = '^';
                grid[p1.r][p1.c] = 'v';
            } else {
                grid[p2.r][p2.c] = 'v';
                grid[p1.r][p1.c] = '^';
            }
        } else {
            // Horizontal domino
            if (p1.c > p2.c) {
                grid[p2.r][p2.c] = '<';
                grid[p1.r][p1.c] = '>';
            } else {
                grid[p2.r][p2.c] = '>';
                grid[p1.r][p1.c] = '<';
            }
        }
    }

    /**
     * Prints the grid if all cells are filled, otherwise prints "Not unique".
     */
    private void printResult() {
        boolean allFilled = true;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    allFilled = false;
                    break;
                }
            }
            if (!allFilled) break;
        }

        if (allFilled) {
            for (int r = 0; r < rows; r++) {
                System.out.println(new String(grid[r]));
            }
        } else {
            System.out.println("Not unique");
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int n = scanner.nextInt();
        int m = scanner.nextInt();
        char[][] grid = new char[n][m];

        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        DominoSolver solver = new DominoSolver(n, m, grid);
        solver.solve();

        scanner.close();
    }
}

import java.util.*;

/**
 * A refactored solution for the maze-filling task.
 * The program identifies paths in a grid and fills them with directional symbols.
 */
public class Task4 {

    /**
     * Represents the possible movement directions and their corresponding symbols.
     * The symbols are designed such that two connected cells point toward each other.
     */
    enum Direction {
        UP(-1, 0, 'v', '^'),
        RIGHT(0, 1, '<', '>'),
        DOWN(1, 0, '^', 'v'),
        LEFT(0, -1, '>', '<');

        final int dr;
        final int dc;
        final char symbol;
        final char oppositeSymbol;

        Direction(int dr, int dc, char symbol, char oppositeSymbol) {
            this.dr = dr;
            this.dc = dc;
            this.symbol = symbol;
            this.oppositeSymbol = oppositeSymbol;
        }

        public static Direction fromIndex(int index) {
            return values()[index];
        }
    }

    /**
     * A simple coordinate representation.
     */
    static class Point {
        final int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Encapsulates the grid and its associated operations.
     */
    static class Maze {
        private final char[][] grid;
        private final int rows;
        private final int cols;

        public Maze(int rows, int cols) {
            this.rows = rows;
            this.cols = cols;
            // Padding the grid with '#' to handle boundaries gracefully
            this.grid = new char[rows + 2][cols + 2];
            for (int i = 0; i < rows + 2; i++) {
                Arrays.fill(grid[i], '#');
            }
        }

        public void setCell(int r, int c, char value) {
            grid[r][c] = value;
        }

        public char getCell(int r, int c) {
            return grid[r][c];
        }

        public void setContent(int r, int c, char value) {
            grid[r + 1][c + 1] = value;
        }

        public boolean isPath(int r, int c) {
            return grid[r][c] == '.';
        }

        /**
         * Counts how many adjacent cells are currently paths ('.').
         */
        public int countNeighbors(int r, int c) {
            if (!isPath(r, c)) {
                return 0;
            }
            int count = 0;
            for (Direction d : Direction.values()) {
                if (isPath(r + d.dr, c + d.dc)) {
                    count++;
                }
            }
            return count;
        }

        /**
         * Fills the current cell and its neighbor with opposing directional symbols.
         * @return The direction used to find the neighbor, or null if no path neighbor exists.
         */
        public Direction fill(int r, int c) {
            for (Direction d : Direction.values()) {
                int nr = r + d.dr;
                int nc = c + d.dc;
                if (isPath(nr, nc)) {
                    grid[r][c] = d.symbol;
                    grid[nr][nc] = d.oppositeSymbol;
                    return d;
                }
            }
            return null;
        }

        public boolean isFullyFilled() {
            for (int i = 1; i <= rows; i++) {
                for (int j = 1; j <= cols; j++) {
                    if (grid[i][j] == '.') return false;
                }
            }
            return true;
        }

        public String toString() {
            StringBuilder sb = new StringBuilder();
            for (int i = 1; i <= rows; i++) {
                for (int j = 1; j <= cols; j++) {
                    sb.append(grid[i][j]);
                }
                sb.append('\n');
            }
            return sb.toString();
        }
    }

    /**
     * Contains the logic to solve the maze filling problem.
     */
    static class MazeSolver {
        private final Maze maze;
        private final int rows;
        private final int cols;

        public MazeSolver(Maze maze, int rows, int cols) {
            this.maze = maze;
            this.rows = rows;
            this.cols = cols;
        }

        public void solve() {
            Deque<Point> queue = new ArrayDeque<>();

            // Initialize queue with all path cells that have exactly one neighbor
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (maze.countNeighbors(i + 1, j + 1) == 1) {
                        queue.add(new Point(i, j));
                    }
                }
            }

            while (!queue.isEmpty()) {
                Point curr = queue.poll();
                int r = curr.r + 1;
                int c = curr.c + 1;

                // Re-verify current cell condition as neighbors might have changed
                if (maze.countNeighbors(r, c) != 1) {
                    continue;
                }

                Direction dir = maze.fill(r, c);
                if (dir == null) {
                    continue;
                }

                // Check neighbors of the current and filled cells to update the queue
                for (Direction d : Direction.values()) {
                    int x1 = curr.r + d.dr;
                    int y1 = curr.c + d.dc;
                    int x2 = x1 + dir.dr;
                    int y2 = y1 + dir.dc;

                    // Use 1-based indexing for the maze check
                    if (maze.isPath(x1 + 1, y1 + 1) && maze.countNeighbors(x1 + 1, y1 + 1) == 1) {
                        queue.add(new Point(x1, y1));
                    }
                    if (maze.isPath(x2 + 1, y2 + 1) && maze.countNeighbors(x2 + 1, y2 + 1) == 1) {
                        queue.add(new Point(x2, y2));
                    }
                }
            }

            if (!maze.isFullyFilled()) {
                System.out.println("Not unique");
            } else {
                System.out.print(maze.toString());
            }
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextInt()) return;

        int n = sc.nextInt();
        int m = sc.nextInt();
        sc.nextLine(); // Consume newline

        Maze maze = new Maze(n, m);
        for (int i = 0; i < n; i++) {
            String line = sc.nextLine();
            for (int j = 0; j < m; j++) {
                maze.setContent(i, j, line.charAt(j));
            }
        }
        sc.close();

        MazeSolver solver = new MazeSolver(maze, n, m);
        solver.solve();
    }
}

import java.io.*;
import java.util.*;

/**
 * A solution to find a unique tiling of a grid with directional arrows.
 * Each '.' must be paired with an adjacent '.' to form a domino.
 */
public class Main {
    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int n = reader.nextInt();
            int m = reader.nextInt();
            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                String line = reader.next();
                for (int j = 0; j < m; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }

            GridSolver solver = new GridSolver(n, m, grid);
            solver.solve(writer);
        } catch (Exception e) {
            // In competitive programming, usually we don't catch exceptions, 
            // but for maintainability, we handle them.
        } finally {
            writer.close();
        }
    }

    static class GridSolver {
        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final int[][] degree;
        private final Deque<int[]> queue = new ArrayDeque<>();

        private static final int[] DR = {1, 0, -1, 0};
        private static final int[] DC = {0, 1, 0, -1};

        public GridSolver(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            this.degree = new int[rows][cols];
        }

        public void solve(PrintWriter out) {
            calculateDegrees();
            initializeQueue();
            processQueue();

            if (isTilingIncomplete()) {
                out.println("Not unique");
            } else {
                printGrid(out);
            }
        }

        private void calculateDegrees() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.') {
                        int count = 0;
                        for (int i = 0; i < 4; i++) {
                            int nr = r + DR[i];
                            int nc = c + DC[i];
                            if (isValid(nr, nc) && grid[nr][nc] == '.') {
                                count++;
                            }
                        }
                        degree[r][c] = count;
                    }
                }
            }
        }

        private void initializeQueue() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.' && degree[r][c] == 1) {
                        queue.add(new int[]{r, c});
                    }
                }
            }
        }

        private void processQueue() {
            while (!queue.isEmpty()) {
                int[] cell = queue.poll();
                int r = cell[0];
                int c = cell[1];

                // If already paired or not an empty cell, skip
                if (grid[r][c] != '.') {
                    continue;
                }

                // Find the only available neighbor to pair with
                int nr = -1, nc = -1;
                for (int i = 0; i < 4; i++) {
                    int tr = r + DR[i];
                    int tc = c + DC[i];
                    if (isValid(tr, tc) && grid[tr][tc] == '.') {
                        nr = tr;
                        nc = tc;
                        break;
                    }
                }

                if (nr != -1) {
                    pairCells(r, c, nr, nc);
                }
            }
        }

        private void pairCells(int r1, int c1, int r2, int c2) {
            // Apply arrow orientation based on the relative position
            if (c1 == c2) { // Vertical pair
                int top = Math.min(r1, r2);
                int bottom = Math.max(r1, r2);
                grid[top][c1] = '^';
                grid[bottom][c1] = 'v';
            } else { // Horizontal pair
                int left = Math.min(c1, c2);
                int right = Math.max(c1, c2);
                grid[r1][left] = '<';
                grid[r1][right] = '>';
            }

            // Update neighbors of both paired cells
            updateNeighbors(r1, c1);
            updateNeighbors(r2, c2);
        }

        private void updateNeighbors(int r, int c) {
            for (int i = 0; i < 4; i++) {
                int nr = r + DR[i];
                int nc = c + DC[i];
                if (isValid(nr, nc) && grid[nr][nc] == '.') {
                    degree[nr][nc]--;
                    if (degree[nr][nc] == 1) {
                        queue.add(new int[]{nr, nc});
                    }
                }
            }
        }

        private boolean isTilingIncomplete() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.') return true;
                }
            }
            return false;
        }

        private void printGrid(PrintWriter out) {
            for (int r = 0; r < rows; r++) {
                out.println(new String(grid[r]));
            }
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * Efficient reader for large input datasets.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver for the grid-based arrow placement puzzle.
 * The goal is to fill all empty '.' cells with arrows that point to adjacent cells,
 * based on the degree of connectivity.
 */
public class PuzzleSolverApp {

    public static void main(String[] args) {
        try {
            FastReader reader = new FastReader(System.in);
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            PuzzleSolver solver = new PuzzleSolver(rows, cols, grid);
            solver.solve();
            solver.printResult();

        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Represents a coordinate in the 2D grid.
     */
    private record Coordinate(int row, int col) {}

    /**
     * Handles the logic for solving the arrow puzzle.
     */
    private static class PuzzleSolver {
        // Directional offsets: {row_offset, col_offset}
        private static final int[] ROW_OFFSETS = {0, 0, -1, 1};
        private static final int[] COL_OFFSETS = {-1, 1, 0, 0};

        // Character mapping for the current cell and its neighbor based on direction index
        private static final char[] ARROW_SYMBOLS_CURRENT = {'>', '<', 'v', '^'};
        private static final char[] ARROW_SYMBOLS_NEIGHBOR = {'<', '>', '^', 'v'};

        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final int[][] degrees;
        private final Deque<Coordinate> queue;
        private boolean isUnique = true;

        public PuzzleSolver(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            this.degrees = new int[rows][cols];
            this.queue = new ArrayDeque<>();
        }

        /**
         * Executes the solving algorithm.
         */
        public void solve() {
            initializeDegrees();

            while (!queue.isEmpty()) {
                Coordinate current = queue.poll();

                // If the degree is no longer 1, this cell was already processed or invalidated
                if (degrees[current.row()][current.col()] != 1) {
                    continue;
                }

                if (!processCell(current)) {
                    // If we couldn't find a neighbor to pair with, the solution might not be unique
                    // though in this specific algorithm, the uniqueness is checked at the end.
                }
            }

            validateSolution();
        }

        /**
         * Calculates initial connection degrees for all non-obstacle cells.
         */
        private void initializeDegrees() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '*') continue;

                    int degree = 0;
                    for (int k = 0; k < 4; k++) {
                        int nr = r + ROW_OFFSETS[k];
                        int nc = c + COL_OFFSETS[k];
                        if (isWithinBounds(nr, nc) && grid[nr][nc] != '*') {
                            degree++;
                        }
                    }
                    degrees[r][c] = degree;
                    if (degree == 1) {
                        queue.add(new Coordinate(r, c));
                    }
                }
            }
        }

        /**
         * Attempts to pair the current cell with its only available '.' neighbor.
         * @return true if a neighbor was found and processed.
         */
        private boolean processCell(Coordinate curr) {
            for (int k = 0; k < 4; k++) {
                int nr = curr.row() + ROW_OFFSETS[k];
                int nc = curr.col() + COL_OFFSETS[k];

                if (isWithinBounds(nr, nc) && grid[nr][nc] == '.') {
                    // Place arrows
                    grid[curr.row()][curr.col()] = ARROW_SYMBOLS_CURRENT[k];
                    grid[nr][nc] = ARROW_SYMBOLS_NEIGHBOR[k];

                    // Mark neighbor as processed to prevent re-entry into queue
                    degrees[nr][nc] = -1;

                    // Update surrounding neighbors
                    decrementNeighborDegrees(nr, nc);
                    decrementNeighborDegrees(curr.row(), curr.col());
                    return true;
                }
            }
            return false;
        }

        /**
         * Decrements the degree of all adjacent '.' cells.
         */
        private void decrementNeighborDegrees(int r, int c) {
            for (int k = 0; k < 4; k++) {
                int nr = r + ROW_OFFSETS[k];
                int nc = c + COL_OFFSETS[k];

                if (isWithinBounds(nr, nc) && grid[nr][nc] == '.') {
                    degrees[nr][nc]--;
                    if (degrees[nr][nc] == 1) {
                        queue.add(new Coordinate(nr, nc));
                    }
                }
            }
        }

        private void validateSolution() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.') {
                        isUnique = false;
                        return;
                    }
                }
            }
        }

        private boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        public void printResult() {
            if (!isUnique) {
                System.out.println("Not unique");
            } else {
                for (int i = 0; i < rows; i++) {
                    System.out.println(new String(grid[i]));
                }
            }
        }
    }

    /**
     * Utility class for fast input reading.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.StringTokenizer;

/**
 * Solves the Domino Tiling problem by identifying forced moves.
 * If a cell has only one empty neighbor, it must be paired with that neighbor.
 */
public class DominoTilingSolver {

    // Direction vectors for Up, Left, Down, Right
    private static final int[] ROW_OFFSETS = {-1, 0, 1, 0};
    private static final int[] COL_OFFSETS = {0, -1, 0, 1};

    private final int rows;
    private final int cols;
    private final char[][] board;

    public DominoTilingSolver(int rows, int cols, char[][] board) {
        this.rows = rows;
        this.cols = cols;
        this.board = board;
    }

    /**
     * Represents a coordinate on the grid.
     */
    private static class Cell {
        final int r, c;

        Cell(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Core logic to solve the tiling problem.
     * @return true if a unique tiling was found, false otherwise.
     */
    public boolean solve() {
        Deque<Cell> queue = new ArrayDeque<>();

        // Initial pass: find all cells that are forced
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (board[i][j] == '.' && countEmptyNeighbors(i, j) == 1) {
                    queue.add(new Cell(i, j));
                }
            }
        }

        // Process forced moves iteratively
        while (!queue.isEmpty()) {
            Cell current = queue.poll();
            int r = current.r;
            int c = current.c;

            // If cell was already filled by a previous forced move, skip it
            if (board[r][c] != '.') {
                continue;
            }

            int mask = getEmptyNeighborMask(r, c);

            // If it no longer has exactly one neighbor, we can't make a forced move here
            if (Integer.bitCount(mask) != 1) {
                continue;
            }

            // Apply the forced move
            applyForcedMove(r, c, mask);

            // After filling cells, neighbors of the newly filled cells might now be forced
            // We check the neighbors of the current cell and its partner
            addNeighborsToQueue(r, c, queue);

            // Find the neighbor that was just filled to check its neighbors too
            int nr = r, nc = c;
            if (mask == 1) nr--;
            else if (mask == 2) nc--;
            else if (mask == 4) nr++;
            else if (mask == 8) nc++;

            addNeighborsToQueue(nr, nc, queue);
        }

        // Final validation: Check if any empty cells remain
        return isFullyTiled();
    }

    private void applyForcedMove(int r, int c, int mask) {
        // mask bit indices correspond to ROW_OFFSETS/COL_OFFSETS
        // 1 (bit 0): Up, 2 (bit 1): Left, 4 (bit 2): Down, 8 (bit 3): Right
        if (mask == 1) { // Neighbor is Up
            board[r][c] = 'v';
            board[r - 1][c] = '^';
        } else if (mask == 2) { // Neighbor is Left
            board[r][c] = '>';
            board[r][c - 1] = '<';
        } else if (mask == 4) { // Neighbor is Down
            board[r][c] = '^';
            board[r + 1][c] = 'v';
        } else if (mask == 8) { // Neighbor is Right
            board[r][c] = '<';
            board[r][c + 1] = '>';
        }
    }

    private void addNeighborsToQueue(int r, int c, Deque<Cell> queue) {
        for (int i = 0; i < 4; i++) {
            int nr = r + ROW_OFFSETS[i];
            int nc = c + COL_OFFSETS[i];
            if (isWithinBounds(nr, nc) && board[nr][nc] == '.' && countEmptyNeighbors(nr, nc) == 1) {
                queue.add(new Cell(nr, nc));
            }
        }
    }

    private int countEmptyNeighbors(int r, int c) {
        int count = 0;
        for (int i = 0; i < 4; i++) {
            if (isWithinBounds(r + ROW_OFFSETS[i], c + COL_OFFSETS[i]) && 
                board[r + ROW_OFFSETS[i]][c + COL_OFFSETS[i]] == '.') {
                count++;
            }
        }
        return count;
    }

    private int getEmptyNeighborMask(int r, int c) {
        int mask = 0;
        for (int i = 0; i < 4; i++) {
            if (isWithinBounds(r + ROW_OFFSETS[i], c + COL_OFFSETS[i]) && 
                board[r + ROW_OFFSETS[i]][c + COL_OFFSETS[i]] == '.') {
                mask |= (1 << i);
            }
        }
        return mask;
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private boolean isFullyTiled() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (board[i][j] == '.') return false;
            }
        }
        return true;
    }

    public void printBoard(PrintWriter writer) {
        for (int i = 0; i < rows; i++) {
            writer.println(new String(board[i]));
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader() {
            this.reader = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        @Override
        public void close() throws IOException {
            reader.close();
        }
    }

    public static void main(String[] args) {
        try (FastReader sc = new FastReader(); 
             PrintWriter out = new PrintWriter(System.out)) {

            String firstLine = sc.next();
            if (firstLine == null) return;

            int rows = Integer.parseInt(firstLine);
            int cols = sc.nextInt();
            char[][] board = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                String line = sc.next();
                for (int j = 0; j < cols; j++) {
                    board[i][j] = line.charAt(j);
                }
            }

            DominoTilingSolver solver = new DominoTilingSolver(rows, cols, board);
            if (solver.solve()) {
                solver.printBoard(out);
            } else {
                out.println("Not unique");
            }
            out.flush();

        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

