/**
 * Core logic for solving the grid-based direction puzzle.
 */
class GridSolver {

    /**
     * Represents possible directions in the grid.
     */
    private enum Direction {
        UP(-1, 0, '^'),
        LEFT(0, -1, '<'),
        DOWN(1, 0, 'v'),
        RIGHT(0, 1, '>');

        final int rowDelta;
        final int colDelta;
        final char symbol;

        Direction(int rowDelta, int colDelta, char symbol) {
            this.rowDelta = rowDelta;
            this.colDelta = colDelta;
            this.symbol = symbol;
        }

        static Direction fromRowDelta(int dr, int dc) {
            for (Direction d : values()) {
                if (d.rowDelta == dr && d.colDelta == dc) return d;
            }
            return null;
        }
    }

    /**
     * Simple coordinate helper.
     */
    private static record Point(int r, int c) {}

    public void solve(int testNumber, FastReader in, PrintWriter out) {
        int rows = in.nextInt();
        int cols = in.nextInt();
        char[][] board = in.nextCharRows(rows);

        // Use a Queue to propagate forced moves (BFS approach) to avoid StackOverflow
        Queue<Point> queue = new ArrayDeque<>();

        // Initial pass: find all empty cells that are immediately constrained
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (board[r][c] == '.' && countDotNeighbors(board, r, c) == 1) {
                    queue.add(new Point(r, c));
                }
            }
        }

        // Process forced cells
        while (!queue.isEmpty()) {
            Point curr = queue.poll();

            // Skip if this cell has already been filled
            if (board[curr.r][curr.c] != '.') {
                continue;
            }

            Direction forcedDir = findOnlyDotNeighborDirection(board, curr.r, curr.c);
            if (forcedDir != null) {
                board[curr.r][curr.c] = forcedDir.symbol;

                // After filling a cell, its neighbors might now be constrained
                for (Direction d : Direction.values()) {
                    int nr = curr.r + d.rowDelta;
                    int nc = curr.c + d.colDelta;
                    if (isDot(board, nr, nc)) {
                        queue.add(new Point(nr, nc));
                    }
                }
            }
        }

        // Verification and Output
        if (hasUnfilledCells(board)) {
            out.println("Not unique");
        } else {
            for (char[] row : board) {
                out.println(new String(row));
            }
        }
    }

    private int countDotNeighbors(char[][] board, int r, int c) {
        int count = 0;
        for (Direction d : Direction.values()) {
            if (isDot(board, r + d.rowDelta, c + d.colDelta)) {
                count++;
            }
        }
        return count;
    }

    private Direction findOnlyDotNeighborDirection(char[][] board, int r, int c) {
        for (Direction d : Direction.values()) {
            if (isDot(board, r + d.rowDelta, c + d.colDelta)) {
                return d;
            }
        }
        return null;
    }

    private boolean isDot(char[][] board, int r, int c) {
        return r >= 0 && r < board.length && 
               c >= 0 && c < board[0].length && 
               board[r][c] == '.';
    }

    private boolean hasUnfilledCells(char[][] board) {
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == '.') return true;
            }
        }
        return false;
    }
}

