/**
 * A solution for the domino tiling problem.
 * The algorithm uses a pruning approach: it repeatedly finds cells with only one 
 * possible neighbor (degree 1) and places a domino there.
 */
public class DominoTilingSolution {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = scanner.next().toCharArray();
            }

            DominoTilingSolver solver = new DominoTilingSolver(rows, cols, grid);
            solver.solve(out);

        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            out.close();
        }
    }
}

class DominoTilingSolver {
    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final Deque<Point> queue;

    /**
     * Represents a direction of movement and the corresponding domino symbols.
     */
    private enum Direction {
        RIGHT(0, 1, '<', '>'),
        LEFT(0, -1, '>', '<'),
        DOWN(1, 0, '^', 'v'),
        UP(-1, 0, 'v', '^');

        final int dr, dc;
        final char currentSymbol, neighborSymbol;

        Direction(int dr, int dc, char currentSymbol, char neighborSymbol) {
            this.dr = dr;
            this.dc = dc;
            this.currentSymbol = currentSymbol;
            this.neighborSymbol = neighborSymbol;
        }

        static Direction getDirectionFromPoint(Point from, Point to) {
            int dr = to.row - from.row;
            int dc = to.col - from.col;
            for (Direction d : values()) {
                if (d.dr == dr && d.dc == dc) return d;
            }
            return null;
        }
    }

    /**
     * Simple coordinate representation.
     */
    private static class Point {
        final int row, col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Point)) return false;
            Point point = (Point) o;
            return row == point.row && col == point.col;
        }

        @Override
        public int hashCode() {
            return Objects.hash(row, col);
        }
    }

    public DominoTilingSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.queue = new ArrayDeque<>();
    }

    public void solve(PrintWriter out) {
        // Initialize queue with all empty cells that have only one neighbor
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (isAvailable(r, c) && countNeighbors(r, c) == 1) {
                    queue.add(new Point(r, c));
                }
            }
        }

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            // If cell was already filled by a domino placed from a neighbor
            if (!isAvailable(current.row, current.col)) {
                continue;
            }

            Point partner = findPartner(current);
            if (partner == null) {
                out.println("Not unique");
                return;
            }

            placeDomino(current, partner);

            // When a domino is placed, the partner's neighbors' degrees change.
            // We check the neighbors of the partner to see if they became degree-1.
            for (Direction dir : Direction.values()) {
                int nr = partner.row + dir.dr;
                int nc = partner.col + dir.dc;
                if (isAvailable(nr, nc) && countNeighbors(nr, nc) == 1) {
                    queue.add(new Point(nr, nc));
                }
            }
        }

        // Final check: if any empty cells remain, the tiling was not unique or impossible
        if (hasRemainingEmptyCells()) {
            out.println("Not unique");
        } else {
            printGrid(out);
        }
    }

    private boolean isAvailable(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] == '.';
    }

    private int countNeighbors(int r, int c) {
        int count = 0;
        for (Direction dir : Direction.values()) {
            if (isAvailable(r + dir.dr, c + dir.dc)) {
                count++;
            }
        }
        return count;
    }

    private Point findPartner(Point p) {
        for (Direction dir : Direction.values()) {
            int nr = p.row + dir.dr;
            int nc = p.col + dir.dc;
            if (isAvailable(nr, nc)) {
                return new Point(nr, nc);
            }
        }
        return null;
    }

    private void placeDomino(Point p1, Point p2) {
        Direction dir = Direction.getDirectionFromPoint(p1, p2);
        if (dir != null) {
            grid[p1.row][p1.col] = dir.currentSymbol;
            grid[p2.row][p2.col] = dir.neighborSymbol;
        }
    }

    private boolean hasRemainingEmptyCells() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') return true;
            }
        }
        return false;
    }

    private void printGrid(PrintWriter out) {
        for (int r = 0; r < rows; r++) {
            out.println(new String(grid[r]));
        }
    }
}

