import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.*;

/**
 * A solver for a directional path puzzle.
 * The goal is to fill empty cells with directions such that every cell 
 * points away from its paired neighbor.
 */
public class PuzzleSolver {

    /**
     * Represents the possible states of a cell in the grid.
     */
    enum CellType {
        EMPTY('.', 0),
        WALL('*', 1),
        LEFT('<', 2),
        RIGHT('>', 3),
        UP('^', 4),
        DOWN('v', 5);

        private final char symbol;
        private final int id;

        CellType(char symbol, int id) {
            this.symbol = symbol;
            this.id = id;
        }

        public char getSymbol() {
            return symbol;
        }

        public static CellType fromId(int id) {
            for (CellType type : values()) {
                if (type.id == id) return type;
            }
            return EMPTY;
        }
    }

    /**
     * Represents a coordinate in the 2D grid.
     */
    record Point(int row, int col) {}

    /**
     * Manages the grid state and provides boundary-safe access.
     */
    static class Grid {
        private final int rows;
        private final int cols;
        private final CellType[][] cells;

        private static final int[][] DIRECTIONS = {
            {-1, 0}, {1, 0}, {0, -1}, {0, 1}
        };

        public Grid(int rows, int cols) {
            this.rows = rows;
            this.cols = cols;
            this.cells = new CellType[rows][cols];
        }

        public void setCell(int r, int c, CellType type) {
            cells[r][c] = type;
        }

        public CellType getCell(int r, int c) {
            return cells[r][c];
        }

        public int getRows() { return rows; }
        public int getCols() { return cols; }

        public boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        public boolean isEmpty(int r, int c) {
            return isWithinBounds(r, c) && cells[r][c] == CellType.EMPTY;
        }

        public int countEmptyNeighbors(int r, int c) {
            int count = 0;
            for (int[] dir : DIRECTIONS) {
                if (isEmpty(r + dir[0], c + dir[1])) {
                    count++;
                }
            }
            return count;
        }

        public Optional<Point> getOnlyEmptyNeighbor(int r, int c) {
            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (isEmpty(nr, nc)) {
                    return Optional.of(new Point(nr, nc));
                }
            }
            return Optional.empty();
        }

        public void print() {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    sb.append(cells[i][j].getSymbol());
                }
                sb.append("\n");
            }
            System.out.print(sb.toString());
        }
    }

    /**
     * Logic engine to solve the puzzle.
     */
    static class Solver {
        private final Grid grid;
        private int emptyCellsCount;

        public Solver(Grid grid, int emptyCellsCount) {
            this.grid = grid;
            this.emptyCellsCount = emptyCellsCount;
        }

        public boolean solve() {
            if (emptyCellsCount % 2 != 0) return false;
            if (emptyCellsCount == 0) return true;

            Deque<Point> queue = new ArrayDeque<>();
            boolean[][] addedToQueue = new boolean[grid.getRows()][grid.getCols()];
            boolean[][] solved = new boolean[grid.getRows()][grid.getCols()];

            // Find initial candidates: empty cells with exactly one empty neighbor
            for (int r = 0; r < grid.getRows(); r++) {
                for (int c = 0; c < grid.getCols(); c++) {
                    if (grid.isEmpty(r, c) && grid.countEmptyNeighbors(r, c) == 1) {
                        queue.addLast(new Point(r, c));
                        addedToQueue[r][c] = true;
                    }
                }
            }

            while (!queue.isEmpty()) {
                Point p1 = queue.removeFirst();
                if (solved[p1.row()][p1.col()]) continue;

                Optional<Point> neighborOpt = grid.getOnlyEmptyNeighbor(p1.row(), p1.col());
                if (neighborOpt.isEmpty()) return false;

                Point p2 = neighborOpt.get();
                if (solved[p2.row()][p2.col()]) return false; // Neighbor already filled

                // Mark both cells as solved
                solved[p1.row()][p1.col()] = true;
                solved[p2.row()][p2.col()] = true;

                // Assign directions pointing away from each other
                assignDirections(p1, p2);

                // Check neighbors of both cells to see if they now have only one empty neighbor
                checkAndEnqueue(p1, queue, addedToQueue, solved);
                checkAndEnqueue(p2, queue, addedToQueue, solved);

                emptyCellsCount -= 2;
            }

            return emptyCellsCount == 0;
        }

        private void assignDirections(Point p1, Point p2) {
            if (p1.row() == p2.row()) {
                // Horizontal pairing
                if (p1.col() < p2.col()) {
                    grid.setCell(p1.row(), p1.col(), CellType.LEFT);
                    grid.setCell(p2.row(), p2.col(), CellType.RIGHT);
                } else {
                    grid.setCell(p1.row(), p1.col(), CellType.RIGHT);
                    grid.setCell(p2.row(), p2.col(), CellType.LEFT);
                }
            } else {
                // Vertical pairing
                if (p1.row() < p2.row()) {
                    grid.setCell(p1.row(), p1.col(), CellType.UP);
                    grid.setCell(p2.row(), p2.col(), CellType.DOWN);
                } else {
                    grid.setCell(p1.row(), p1.col(), CellType.DOWN);
                    grid.setCell(p2.row(), p2.col(), CellType.UP);
                }
            }
        }

        private void checkAndEnqueue(Point p, Deque<Point> queue, boolean[][] added, boolean[][] solved) {
            int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
            for (int[] dir : directions) {
                int nr = p.row() + dir[0];
                int nc = p.col() + dir[1];

                if (grid.isEmpty(nr, nc) 
                        && !added[nr][nc] 
                        && !solved[nr][nc] 
                        && grid.countEmptyNeighbors(nr, nc) == 1) {
                    queue.addLast(new Point(nr, nc));
                    added[nr][nc] = true;
                }
            }
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null) return;

        String[] dims = line.trim().split("\\s+");
        int rows = Integer.parseInt(dims[0]);
        int cols = Integer.parseInt(dims[1]);

        Grid grid = new Grid(rows, cols);
        int emptyCnt = 0;

        for (int i = 0; i < rows; i++) {
            String rowStr = br.readLine();
            for (int j = 0; j < cols; j++) {
                if (rowStr.charAt(j) == '*') {
                    grid.setCell(i, j, CellType.WALL);
                } else {
                    grid.setCell(i, j, CellType.EMPTY);
                    emptyCnt++;
                }
            }
        }

        Solver solver = new Solver(grid, emptyCnt);
        if (solver.solve()) {
            grid.print();
        } else {
            System.out.println("Not unique");
        }
    }
}

