/**
 * Logic for solving the grid arrow matching problem.
 */
class GridArrowSolver {
    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int[][] degree;

    private static final int[] DX = {0, 0, 1, -1};
    private static final int[] DY = {1, -1, 0, 0};

    public GridArrowSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.degree = new int[rows][cols];
    }

    /**
     * Executes the solver logic.
     * @return The processed grid or "Not unique" if the configuration is not unique.
     */
    public String solve() {
        calculateInitialDegrees();

        // Queue stores packed coordinates: x * cols + y
        Deque<Integer> queue = new ArrayDeque<>();

        // Initialize queue with all cells that have exactly one empty neighbor
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.' && degree[i][j] == 1) {
                    queue.add(i * cols + j);
                }
            }
        }

        while (!queue.isEmpty()) {
            int pos = queue.poll();
            int x = pos / cols;
            int y = pos % cols;

            // If the cell was already filled by another pair, skip it
            if (grid[x][y] != '.') {
                continue;
            }

            // Find the only available neighbor to pair with
            int nx = -1, ny = -1;
            for (int i = 0; i < 4; i++) {
                int tx = x + DX[i];
                int ty = y + DY[i];
                if (isValid(tx, ty) && grid[tx][ty] == '.') {
                    nx = tx;
                    ny = ty;
                    break;
                }
            }

            // If a cell with degree 1 has no '.' neighbors, it cannot be paired
            if (nx != -1) {
                assignPairArrows(x, y, nx, ny);
                updateNeighbors(x, y, queue);
                updateNeighbors(nx, ny, queue);
            }
        }

        return formatResult();
    }

    private void calculateInitialDegrees() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.') {
                    int count = 0;
                    for (int d = 0; d < 4; d++) {
                        int ni = i + DX[d];
                        int nj = j + DY[d];
                        if (isValid(ni, nj) && grid[ni][nj] == '.') {
                            count++;
                        }
                    }
                    degree[i][j] = count;
                }
            }
        }
    }

    private void updateNeighbors(int r, int c, Deque<Integer> queue) {
        for (int i = 0; i < 4; i++) {
            int nr = r + DX[i];
            int nc = c + DY[i];
            if (isValid(nr, nc) && grid[nr][nc] == '.') {
                degree[nr][nc]--;
                if (degree[nr][nc] == 1) {
                    queue.add(nr * cols + nc);
                }
            }
        }
    }

    /**
     * Assigns arrows to the two cells in a pair.
     * Preserves the original logic where paired cells point away from each other.
     */
    private void assignPairArrows(int r1, int c1, int r2, int c2) {
        // Ensure (r1, c1) is the "smaller" cell to simplify logic
        if (r1 > r2 || (r1 == r2 && c1 > c2)) {
            int tempR = r1; r1 = r2; r2 = tempR;
            int tempC = c1; c1 = c2; c2 = tempC;
        }

        if (r1 == r2) { // Horizontal pair
            if (c2 == c1 + 1) {
                grid[r1][c1] = '<';
                grid[r2][c2] = '>';
            } else {
                grid[r1][c1] = '>';
                grid[r2][c2] = '<';
            }
        } else { // Vertical pair
            if (r2 == r1 + 1) {
                grid[r1][c1] = '^';
                grid[r2][c2] = 'v';
            } else {
                grid[r1][c1] = 'v';
                grid[r2][c2] = '^';
            }
        }
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private String formatResult() {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.') {
                    return "Not unique";
                }
                sb.append(grid[i][j]);
            }
            sb.append("\n");
        }
        return sb.toString().trim();
    }
}

