import java.util.*;
import java.io.*;

/**
 * A solver for the Grid Arrow Puzzle.
 * The goal is to pair all '.' cells with an adjacent '.' cell using arrows.
 */
public class GridArrowPuzzle {

    public static void main(String[] args) {
        InputReader reader = new InputReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] grid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            Solver solver = new Solver(rows, cols, grid);
            Result result = solver.solve();

            if (result.isSuccess()) {
                for (int i = 0; i < rows; i++) {
                    writer.println(new String(result.getGrid()[i]));
                }
            } else {
                writer.println(result.getMessage());
            }
        } catch (Exception e) {
            // In a production environment, use a logger here.
        } finally {
            writer.close();
        }
    }

    /**
     * Represents a coordinate in the grid.
     */
    private static class Point {
        final int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Represents the result of the solving process.
     */
    private static class Result {
        private final boolean success;
        private final char[][] grid;
        private final String message;

        private Result(boolean success, char[][] grid, String message) {
            this.success = success;
            this.grid = grid;
            this.message = message;
        }

        public static Result success(char[][] grid) {
            return new Result(true, grid, null);
        }

        public static Result failure(String message) {
            return new Result(false, null, message);
        }

        public boolean isSuccess() { return success; }
        public char[][] getGrid() { return grid; }
        public String getMessage() { return message; }
    }

    /**
     * Defines possible movements and their corresponding direction vectors.
     */
    private enum Direction {
        UP(-1, 0), DOWN(1, 0), LEFT(0, -1), RIGHT(0, 1);

        final int dr, dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }
    }

    /**
     * Core logic for solving the grid puzzle.
     */
    private static class Solver {
        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final int[][] neighborCounts;

        Solver(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            this.neighborCounts = new int[rows][cols];
        }

        public Result solve() {
            Deque<Point> queue = new ArrayDeque<>();

            // Phase 1: Calculate initial degrees and find leaf nodes (degree 1)
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.') {
                        int count = countDotNeighbors(i, j);
                        neighborCounts[i][j] = count;
                        if (count == 1) {
                            queue.add(new Point(i, j));
                        }
                    }
                }
            }

            // Phase 2: Reduction process (Peeling the graph)
            while (!queue.isEmpty()) {
                Point current = queue.poll();

                // If this cell was already processed and turned into an arrow, skip it
                if (grid[current.r][current.c] != '.') {
                    continue;
                }

                Point neighbor = findFirstDotNeighbor(current.r, current.c);
                if (neighbor == null) {
                    return Result.failure("Not unique");
                }

                placeArrows(current.r, current.c, neighbor.r, neighbor.c);

                // Update the degrees of the neighbors of the neighbor we just matched
                for (Direction d : Direction.values()) {
                    int nr = neighbor.r + d.dr;
                    int nc = neighbor.c + d.dc;

                    if (isValid(nr, nc) && grid[nr][nc] == '.') {
                        neighborCounts[nr][nc]--;
                        if (neighborCounts[nr][nc] == 1) {
                            queue.add(new Point(nr, nc));
                        }
                    }
                }
            }

            // Phase 3: Final validation
            if (hasRemainingDots()) {
                return Result.failure("Not unique");
            }

            return Result.success(grid);
        }

        private int countDotNeighbors(int r, int c) {
            int count = 0;
            for (Direction d : Direction.values()) {
                int nr = r + d.dr;
                int nc = c + d.dc;
                if (isValid(nr, nc) && grid[nr][nc] == '.') {
                    count++;
                }
            }
            return count;
        }

        private Point findFirstDotNeighbor(int r, int c) {
            for (Direction d : Direction.values()) {
                int nr = r + d.dr;
                int nc = c + d.dc;
                if (isValid(nr, nc) && grid[nr][nc] == '.') {
                    return new Point(nr, nc);
                }
            }
            return null;
        }

        private void placeArrows(int r1, int c1, int r2, int c2) {
            if (r1 == r2) { // Horizontal pairing
                int minC = Math.min(c1, c2);
                int maxC = Math.max(c1, c2);
                grid[r1][minC] = '<';
                grid[r1][maxC] = '>';
            } else { // Vertical pairing
                int minR = Math.min(r1, r2);
                int maxR = Math.max(r1, r2);
                grid[minR][c1] = '^';
                grid[maxR][c1] = 'v';
            }
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        private boolean hasRemainingDots() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.') return true;
                }
            }
            return false;
        }
    }

    /**
     * Optimized reader for fast input processing.
     */
    private static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored DrazilTiles program.
 * This program solves a tiling problem using a leaf-peeling algorithm.
 */
public class DrazilTiles {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        TilingSolver solver = new TilingSolver(reader);
        solver.solve(writer);

        writer.close();
    }

    /**
     * Represents the possible directions in the grid and the characters
     * required to tile the cells.
     */
    enum Direction {
        // dr, dc, charForCurrentCell, charForNeighborCell
        // The characters are chosen based on the original logic: 
        // adjacent tiles point away from each other.
        UP(-1, 0, 'v', '^'),
        LEFT(0, -1, '>', '<'),
        RIGHT(0, 1, '<', '>'),
        DOWN(1, 0, '^', 'v');

        final int dr, dc;
        final char currentCellChar;
        final char neighborCellChar;

        Direction(int dr, int dc, char currentCellChar, char neighborCellChar) {
            this.dr = dr;
            this.dc = dc;
            this.currentCellChar = currentCellChar;
            this.neighborCellChar = neighborCellChar;
        }

        static final Direction[] ALL = Direction.values();
    }

    /**
     * Simple wrapper for grid coordinates.
     */
    static class Coordinate {
        final int r, c;

        Coordinate(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Manages the grid state, including the board characters and the 
     * connectivity degrees of empty cells.
     */
    static class Grid {
        private final int rows;
        private final int cols;
        private final char[][] board;
        private final int[][] degrees;

        Grid(int rows, int cols, char[][] initialBoard) {
            this.rows = rows;
            this.cols = cols;
            this.board = initialBoard;
            this.degrees = new int[rows][cols];
        }

        int getRows() { return rows; }
        int getCols() { return cols; }

        boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        boolean isDot(int r, int c) {
            return isValid(r, c) && board[r][c] == '.';
        }

        void setCell(int r, int c, char val) {
            board[r][c] = val;
        }

        void calculateInitialDegrees() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (isDot(r, c)) {
                        int count = 0;
                        for (Direction d : Direction.ALL) {
                            if (isDot(r + d.dr, c + d.dc)) {
                                count++;
                            }
                        }
                        degrees[r][c] = count;
                    }
                }
            }
        }

        int getDegree(int r, int c) {
            return degrees[r][c];
        }

        void decrementDegree(int r, int c) {
            if (isValid(r, c)) {
                degrees[r][c]--;
            }
        }

        void print(PrintWriter out) {
            for (int r = 0; r < rows; r++) {
                out.println(new String(board[r]));
            }
        }
    }

    /**
     * Contains the core algorithm logic for solving the tiling problem.
     */
    static class TilingSolver {
        private final FastReader reader;

        TilingSolver(FastReader reader) {
            this.reader = reader;
        }

        void solve(PrintWriter out) {
            int n = reader.nextInt();
            int m = reader.nextInt();
            char[][] boardData = new char[n][];
            for (int i = 0; i < n; i++) {
                boardData[i] = reader.next().toCharArray();
            }

            Grid grid = new Grid(n, m, boardData);
            grid.calculateInitialDegrees();

            int dotCount = 0;
            Queue<Coordinate> queue = new LinkedList<>();

            // Initialize the queue with all leaf cells (degree 1)
            for (int r = 0; r < n; r++) {
                for (int c = 0; c < m; c++) {
                    if (grid.isDot(r, c)) {
                        dotCount++;
                        if (grid.getDegree(r, c) == 1) {
                            queue.offer(new Coordinate(r, c));
                        }
                    }
                }
            }

            // Peeling process
            while (!queue.isEmpty()) {
                Coordinate curr = queue.poll();
                int r = curr.r;
                int c = curr.c;

                // If cell was already paired by a previous operation, skip it
                if (!grid.isDot(r, c)) continue;

                // Find the single '.' neighbor to pair with
                for (Direction d : Direction.ALL) {
                    int nr = r + d.dr;
                    int nc = c + d.dc;

                    if (grid.isDot(nr, nc)) {
                        // Pair the two cells
                        grid.setCell(r, c, d.currentCellChar);
                        grid.setCell(nr, nc, d.neighborCellChar);
                        dotCount -= 2;

                        // Update degrees of the neighbor's neighbors
                        for (Direction neighborDir : Direction.ALL) {
                            int nnr = nr + neighborDir.dr;
                            int nnc = nc + neighborDir.dc;
                            if (grid.isDot(nnr, nnc)) {
                                grid.decrementDegree(nnr, nnc);
                                // If a neighbor becomes a leaf, add to queue
                                if (grid.getDegree(nnr, nnc) == 1) {
                                    queue.offer(new Coordinate(nnr, nnc));
                                }
                            }
                        }
                        break; 
                    }
                }
            }

            if (dotCount != 0) {
                out.println("Not unique");
            } else {
                grid.print(out);
            }
        }
    }

    /**
     * High-performance input reader.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;

/**
 * A solver for the Arrow Grid puzzle.
 * The goal is to fill all empty '.' cells with arrows pointing to neighbors
 * such that every cell has exactly one arrow pointing away from it.
 */
public class ArrowGridSolver {

    // Directional offsets for Up, Down, Left, Right
    private static final int[] ROW_OFFSETS = {-1, 1, 0, 0};
    private static final int[] COL_OFFSETS = {0, 0, -1, 1};

    private final int rows;
    private final int cols;
    private final char[][] grid;

    /**
     * Represents a coordinate in the grid.
     */
    private static class Cell {
        final int r;
        final int c;

        Cell(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    public ArrowGridSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
    }

    /**
     * Core logic to solve the grid using a queue-based propagation.
     */
    public void solve() {
        Queue<Cell> queue = new LinkedList<>();

        // Step 1: Find all initial cells that satisfy the condition (exactly one empty neighbor)
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && countEmptyNeighbors(r, c) == 1) {
                    queue.add(new Cell(r, c));
                }
            }
        }

        // Step 2: Propagate the filling process
        while (!queue.isEmpty()) {
            Cell current = queue.poll();
            int r = current.r;
            int c = current.c;

            // Re-verify conditions because the grid state may have changed since adding to queue
            if (grid[r][c] != '.' || countEmptyNeighbors(r, c) != 1) {
                continue;
            }

            // Find the single empty neighbor to fill
            for (int i = 0; i < 4; i++) {
                int nr = r + ROW_OFFSETS[i];
                int nc = c + COL_OFFSETS[i];

                if (isValid(nr, nc) && grid[nr][nc] == '.') {
                    applyArrows(r, c, nr, nc);

                    // Adding the neighbor's neighbors to the queue as their empty-neighbor-count may have changed
                    for (int j = 0; j < 4; j++) {
                        int nnr = nr + ROW_OFFSETS[j];
                        int nnc = nc + COL_OFFSETS[j];
                        if (isValid(nnr, nnc)) {
                            queue.add(new Cell(nnr, nnc));
                        }
                    }
                    break; // Found the only neighbor, move to next queue item
                }
            }
        }
    }

    private int countEmptyNeighbors(int r, int c) {
        int count = 0;
        for (int i = 0; i < 4; i++) {
            int nr = r + ROW_OFFSETS[i];
            int nc = c + COL_OFFSETS[i];
            if (isValid(nr, nc) && grid[nr][nc] == '.') {
                count++;
            }
        }
        return count;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Fills the current cell and its neighbor with arrows.
     * This follows the specific directional logic provided in the original implementation.
     */
    private void applyArrows(int r, int c, int nr, int nc) {
        if (nr == r - 1) { // Neighbor is UP
            grid[nr][nc] = '^';
            grid[r][c] = 'v';
        } else if (nr == r + 1) { // Neighbor is DOWN
            grid[nr][nc] = 'v';
            grid[r][c] = '^';
        } else if (nc == c - 1) { // Neighbor is LEFT
            grid[nr][nc] = '<';
            grid[r][c] = '>';
        } else if (nc == c + 1) { // Neighbor is RIGHT
            grid[nr][nc] = '>';
            grid[r][c] = '<';
        }
    }

    /**
     * Checks if any '.' remain and prints the grid or error message.
     */
    public void printResult() {
        boolean hasEmpty = false;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    hasEmpty = true;
                    break;
                }
            }
        }

        if (hasEmpty) {
            System.out.println("Not unique");
        } else {
            StringBuilder output = new StringBuilder();
            for (int r = 0; r < rows; r++) {
                output.append(new String(grid[r])).append('\n');
            }
            System.out.print(output.toString());
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int n = scanner.nextInt();
        int m = scanner.nextInt();
        char[][] grid = new char[n][m];

        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        ArrowGridSolver solver = new ArrowGridSolver(n, m, grid);
        solver.solve();
        solver.printResult();

        scanner.close();
    }
}

