class GridSolver {
    private static final char EMPTY = '.';
    private static final char WALL = '*';
    private static final char UP = '^';
    private static final char DOWN = 'v';
    private static final char LEFT = '<';
    private static final char RIGHT = '>';

    // Directional offsets: Up, Left, Down, Right
    private static final int[] DR = {-1, 0, 1, 0};
    private static final int[] DC = {0, -1, 0, 1};

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int[][] degrees;
    private final boolean[][] inQueue;

    public GridSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.degrees = new int[rows][cols];
        this.inQueue = new boolean[rows][cols];
    }

    /**
     * Executes the solving algorithm using a leaf-pruning approach (similar to topological sort).
     */
    public void solve(PrintWriter out) {
        Queue<Point> queue = new LinkedList<>();

        // 1. Initialize degrees for all empty cells
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == WALL) continue;

                int degree = countEmptyNeighbors(r, c);
                degrees[r][c] = degree;

                if (degree == 1) {
                    queue.add(new Point(r, c));
                    inQueue[r][c] = true;
                }
            }
        }

        // 2. Process cells with degree 1
        while (!queue.isEmpty()) {
            Point curr = queue.poll();

            // If this cell was already filled by a neighbor processing
            if (grid[curr.r][curr.c] != EMPTY) {
                continue;
            }

            // Find an adjacent empty cell to pair with
            Point neighbor = findEmptyNeighbor(curr.r, curr.c);

            if (neighbor == null) {
                out.println("Not unique");
                return;
            }

            // Place arrows pointing away from each other as per original logic
            placeArrows(curr, neighbor);

            // 3. Update degrees of neighbors of the newly placed pair
            updateNeighbors(neighbor.r, neighbor.c, queue);
        }

        // 4. Validation: Check if any empty cells remain
        if (hasEmptyCells()) {
            out.println("Not unique");
            return;
        }

        // 5. Output the resulting grid
        printGrid(out);
    }

    private int countEmptyNeighbors(int r, int c) {
        int count = 0;
        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];
            if (isValid(nr, nc) && grid[nr][nc] == EMPTY) {
                count++;
            }
        }
        return count;
    }

    private Point findEmptyNeighbor(int r, int c) {
        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];
            if (isValid(nr, nc) && grid[nr][nc] == EMPTY) {
                return new Point(nr, nc);
            }
        }
        return null;
    }

    private void placeArrows(Point p1, Point p2) {
        if (p1.r == p2.r) { // Same row
            if (p1.c < p2.c) {
                grid[p1.r][p1.c] = LEFT;
                grid[p2.r][p2.c] = RIGHT;
            } else {
                grid[p1.r][p1.c] = RIGHT;
                grid[p2.r][p2.c] = LEFT;
            }
        } else { // Different row
            if (p1.r > p2.r) {
                grid[p1.r][p1.c] = DOWN;
                grid[p2.r][p2.c] = UP;
            } else {
                grid[p1.r][p1.c] = UP;
                grid[p2.r][p2.c] = DOWN;
            }
        }
    }

    private void updateNeighbors(int r, int c, Queue<Point> queue) {
        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];

            if (isValid(nr, nc) && grid[nr][nc] == EMPTY && !inQueue[nr][nc]) {
                degrees[nr][nc]--;
                if (degrees[nr][nc] == 1) {
                    inQueue[nr][nc] = true;
                    queue.add(new Point(nr, nc));
                }
            }
        }
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private boolean hasEmptyCells() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == EMPTY) return true;
            }
        }
        return false;
    }

    private void printGrid(PrintWriter out) {
        for (int r = 0; r < rows; r++) {
            out.println(new String(grid[r]));
        }
    }

    /**
     * Simple coordinate wrapper.
     */
    private static class Point {
        final int r, c;
        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }
}

/**
 * Efficient input reader for large data sets.
 */
class FastReader {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    public FastReader(InputStream input) {
        reader = new BufferedReader(new InputStreamReader(input));
    }

    public String next() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            String line = reader.readLine();
            if (line == null) return null;
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    public int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    public char[][] readGrid(int rows, int cols) throws IOException {
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = next().toCharArray();
        }
        return grid;
    }
}

import java.util.*;
import java.io.*;

/**
 * Refactored solution for the Maze/Arrow problem.
 * The problem asks to determine if a grid of '.' cells can be uniquely filled 
 * with arrows such that each pair of '.' cells forms a matching.
 */
public class MazeSolver {

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int rows = sc.nextInt();
            int cols = sc.nextInt();
            String[] gridData = new String[rows];
            for (int i = 0; i < rows; i++) {
                gridData[i] = sc.next();
            }

            Maze maze = new Maze(rows, cols, gridData);
            maze.solve();
            maze.print(out);
        } catch (Exception e) {
            // Handle potential parsing errors
        } finally {
            out.close();
        }
    }

    enum CellType {
        OBSTACLE,
        EMPTY,
        ARROW
    }

    enum Direction {
        UP('^', -1, 0),
        DOWN('v', 1, 0),
        LEFT('<', 0, -1),
        RIGHT('>', 0, 1);

        final char symbol;
        final int rowOffset;
        final int colOffset;

        Direction(char symbol, int rowOffset, int colOffset) {
            this.symbol = symbol;
            this.rowOffset = rowOffset;
            this.colOffset = colOffset;
        }

        public static Direction getFromOffset(int dr, int dc) {
            for (Direction d : values()) {
                if (d.rowOffset == dr && d.colOffset == dc) return d;
            }
            return null;
        }
    }

    static class Cell {
        final int r, c;
        CellType type;
        Direction direction;
        int degree = 0;
        final List<Cell> neighbors = new ArrayList<>();

        Cell(int r, int c, CellType type) {
            this.r = r;
            this.c = c;
            this.type = type;
        }

        void addNeighbor(Cell other) {
            this.neighbors.add(other);
            this.degree++;
        }
    }

    static class Maze {
        private final int rows;
        private final int cols;
        private final Cell[][] grid;
        private boolean isUnique = true;

        public Maze(int rows, int cols, String[] data) {
            this.rows = rows;
            this.cols = cols;
            this.grid = new Cell[rows][cols];

            // 1. Initialize grid
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    CellType type = (data[i].charAt(j) == '*') ? CellType.OBSTACLE : CellType.EMPTY;
                    grid[i][j] = new Cell(i, j, type);
                }
            }

            // 2. Build Adjacency List
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j].type == CellType.EMPTY) {
                        buildNeighbors(grid[i][j]);
                    }
                }
            }
        }

        private void buildNeighbors(Cell cell) {
            for (Direction d : Direction.values()) {
                int nr = cell.r + d.rowOffset;
                int nc = cell.c + d.colOffset;
                if (isValid(nr, nc) && grid[nr][nc].type == CellType.EMPTY) {
                    cell.addNeighbor(grid[nr][nc]);
                }
            }
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        /**
         * Uses a leaf-peeling algorithm (topological sort style) to find if 
         * there is a unique perfect matching in the graph of EMPTY cells.
         */
        public void solve() {
            Deque<Cell> queue = new ArrayDeque<>();

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j].type == CellType.EMPTY && grid[i][j].degree == 1) {
                        queue.add(grid[i][j]);
                    }
                }
            }

            while (!queue.isEmpty()) {
                Cell u = queue.poll();

                // If u is already part of a pair, skip
                if (u.type != CellType.EMPTY) continue;

                // Find the only available neighbor v
                Cell v = null;
                for (Cell neighbor : u.neighbors) {
                    if (neighbor.type == CellType.EMPTY) {
                        v = neighbor;
                        break;
                    }
                }

                if (v != null) {
                    // Match u and v. Per original logic, arrows point away from the pair.
                    u.type = CellType.ARROW;
                    u.direction = Direction.getFromOffset(u.r - v.r, u.c - v.c);

                    v.type = CellType.ARROW;
                    v.direction = Direction.getFromOffset(v.r - u.r, v.c - u.c);

                    // Update degrees of neighbors of v
                    for (Cell w : v.neighbors) {
                        if (w.type == CellType.EMPTY) {
                            w.degree--;
                            if (w.degree == 1) {
                                queue.add(w);
                            }
                        }
                    }
                }
            }

            // Check if any EMPTY cells remain
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j].type == CellType.EMPTY) {
                        isUnique = false;
                        return;
                    }
                }
            }
        }

        public void print(PrintWriter out) {
            if (!isUnique) {
                out.println("Not unique");
                return;
            }

            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    Cell cell = grid[i][j];
                    if (cell.type == CellType.OBSTACLE) {
                        sb.append('*');
                    } else {
                        sb.append(cell.direction.symbol);
                    }
                }
                sb.append('\n');
            }
            out.print(sb.toString());
        }
    }

    static class FastScanner {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public FastScanner(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (numChars == -1) throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) return -1;
            }
            return buf[curChar++];
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A refactored solution for the Dreamoon grid problem.
 * The goal is to pair every '.' cell with an adjacent '.' cell using directional markers.
 */
public class Dreamoon {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            GridSolver solver = new GridSolver(rows, cols, grid);
            solver.solve(writer);
        } catch (Exception e) {
            writer.println("Error processing input.");
        } finally {
            writer.close();
        }
    }

    /**
     * Represents a coordinate in the 2D grid.
     */
    static class Point {
        final int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Core engine that handles the grid processing algorithm.
     */
    static class GridSolver {
        private static final int[] ROW_OFFSETS = {-1, 0, 0, 1};
        private static final int[] COL_OFFSETS = {0, -1, 1, 0};
        private static final String NOT_UNIQUE = "Not unique";
        private static final char EMPTY = '.';
        private static final char WALL = '*';

        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final int[][] degrees;
        private final Deque<Point> queue;
        private boolean isInvalid = false;

        public GridSolver(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            this.degrees = new int[rows][cols];
            this.queue = new ArrayDeque<>();
        }

        public void solve(PrintWriter out) {
            if (!initializeDegrees()) {
                out.println(NOT_UNIQUE);
                return;
            }

            processQueue();

            if (isInvalid || hasRemainingDots()) {
                out.println(NOT_UNIQUE);
            } else {
                printGrid(out);
            }
        }

        /**
         * Scans the grid to count neighbors for each empty cell and 
         * identifies cells that must be processed immediately (degree 1).
         */
        private boolean initializeDegrees() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == EMPTY) {
                        int count = 0;
                        for (int i = 0; i < 4; i++) {
                            int nr = r + ROW_OFFSETS[i];
                            int nc = c + COL_OFFSETS[i];
                            if (isValid(nr, nc) && grid[nr][nc] == EMPTY) {
                                count++;
                            }
                        }
                        degrees[r][c] = count;
                        if (count == 0) return false; // An isolated '.' makes it impossible
                        if (count == 1) queue.add(new Point(r, c));
                    }
                }
            }
            return true;
        }

        /**
         * Iteratively pairs degree-1 cells with their only available neighbor.
         */
        private void processQueue() {
            while (!queue.isEmpty() && !isInvalid) {
                Point p = queue.poll();

                // If cell was already filled by a previous pairing, skip it
                if (grid[p.r][p.c] != EMPTY) continue;

                // If degree dropped to 0 before we could pair it, it's invalid
                if (degrees[p.r][p.c] == 0) {
                    isInvalid = true;
                    return;
                }

                Point neighbor = findOnlyDotNeighbor(p.r, p.c);
                if (neighbor == null) {
                    isInvalid = true;
                    return;
                }

                fillPair(p, neighbor);
                updateNeighbors(p.r, p.c);
                updateNeighbors(neighbor.r, neighbor.c);
            }
        }

        private Point findOnlyDotNeighbor(int r, int c) {
            for (int i = 0; i < 4; i++) {
                int nr = r + ROW_OFFSETS[i];
                int nc = c + COL_OFFSETS[i];
                if (isValid(nr, nc) && grid[nr][nc] == EMPTY) {
                    return new Point(nr, nc);
                }
            }
            return null;
        }

        /**
         * Updates the degrees of adjacent '.' cells when a cell is filled.
         */
        private void updateNeighbors(int r, int c) {
            for (int i = 0; i < 4; i++) {
                int nr = r + ROW_OFFSETS[i];
                int nc = c + COL_OFFSETS[i];
                if (isValid(nr, nc) && grid[nr][nc] == EMPTY) {
                    degrees[nr][nc]--;
                    if (degrees[nr][nc] == 0) {
                        isInvalid = true;
                    } else if (degrees[nr][nc] == 1) {
                        queue.add(new Point(nr, nc));
                    }
                }
            }
        }

        /**
         * Places the appropriate directional characters in the grid.
         */
        private void fillPair(Point p1, Point p2) {
            if (p1.r == p2.r) { // Horizontal pair
                int minC = Math.min(p1.c, p2.c);
                grid[p1.r][minC] = '<';
                grid[p1.r][minC + 1] = '>';
            } else { // Vertical pair
                int minR = Math.min(p1.r, p2.r);
                grid[minR][p1.c] = '^';
                grid[minR + 1][p1.c] = 'v';
            }
        }

        private boolean hasRemainingDots() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == EMPTY) return true;
                }
            }
            return false;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        private void printGrid(PrintWriter out) {
            for (int r = 0; r < rows; r++) {
                out.println(new String(grid[r]));
            }
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

