/**
 * Represents the grid and provides utility methods for coordinate/index management.
 */
class Grid {
    private final int rows;
    private final int cols;
    private final char[][] cells;

    public Grid(int rows, int cols, char[][] cells) {
        this.rows = rows;
        this.cols = cols;
        this.cells = cells;
    }

    public int getRows() { return rows; }
    public int getCols() { return cols; }

    public char getCell(int r, int c) {
        return cells[r][c];
    }

    public void setCell(int r, int c, char val) {
        cells[r][c] = val;
    }

    public boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    public int getIndex(int r, int c) {
        return r * cols + c;
    }

    public int getRow(int index) {
        return index / cols;
    }

    public int getCol(int index) {
        return index % cols;
    }

    public char[][] getRawCells() {
        return cells;
    }
}

/**
 * Contains the core logic to find a unique matching in the grid.
 */
class GridMatcher {
    private static final int[] DX = {-1, 1, 0, 0};
    private static final int[] DY = {0, 0, -1, 1};

    private final int rows;
    private final int cols;
    private final Grid grid;
    private final FastReader reader;

    public GridMatcher(int rows, int cols, FastReader reader) throws IOException {
        this.rows = rows;
        this.cols = cols;
        this.reader = reader;
        char[][] initialCells = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            initialCells[i] = reader.next().toCharArray();
        }
        this.grid = new Grid(rows, cols, initialCells);
    }

    public void solve(FastWriter out) throws IOException {
        int totalCells = rows * cols;
        int[] matching = new int[totalCells];
        int[] degrees = new int[totalCells];
        boolean[] isProcessed = new boolean[totalCells];
        Arrays.fill(matching, -1);

        // 1. Calculate initial degrees for non-star cells
        calculateDegrees(degrees);

        // 2. Initialize queue with cells that have degree <= 1
        Queue<Integer> queue = new LinkedList<>();
        for (int i = 0; i < totalCells; i++) {
            if (grid.getCell(grid.getRow(i), grid.getCol(i)) != '*' && degrees[i] <= 1) {
                isProcessed[i] = true;
                queue.add(i);
            }
        }

        // 3. Perform matching using a leaf-removal (greedy) approach
        while (!queue.isEmpty()) {
            int p = queue.poll();
            int r1 = grid.getRow(p);
            int c1 = grid.getCol(p);

            for (int k = 0; k < 4; k++) {
                int r2 = r1 + DX[k];
                int c2 = c1 + DY[k];

                if (!grid.isValid(r2, c2) || grid.getCell(r1, c1) == '*' || grid.getCell(r2, c2) == '*') {
                    continue;
                }

                int neighborIdx = grid.getIndex(r2, c2);

                // If both are free, match them
                if (matching[neighborIdx] == -1 && matching[p] == -1) {
                    matching[neighborIdx] = p;
                    matching[p] = neighborIdx;
                    if (!isProcessed[neighborIdx]) {
                        isProcessed[neighborIdx] = true;
                        queue.add(neighborIdx);
                    }
                }

                // Decrement neighbor degree and add to queue if it becomes a leaf
                degrees[neighborIdx]--;
                if (degrees[neighborIdx] <= 1 && !isProcessed[neighborIdx]) {
                    isProcessed[neighborIdx] = true;
                    queue.add(neighborIdx);
                }
            }
        }

        // 4. Apply directions to the grid based on matching
        applyMatchingToGrid(matching);

        // 5. Validate uniqueness (check if any '.' remains) and print
        if (hasUnmatchedEmptyCells()) {
            out.printLine("Not unique");
        } else {
            printGrid(out);
        }
    }

    private void calculateDegrees(int[] degrees) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid.getCell(r, c) == '*') continue;

                for (int k = 0; k < 4; k++) {
                    int nr = r + DX[k];
                    int nc = c + DY[k];
                    if (grid.isValid(nr, nc) && grid.getCell(nr, nc) != '*') {
                        degrees[grid.getIndex(nr, nc)]++;
                    }
                }
            }
        }
    }

    private void applyMatchingToGrid(int[] matching) {
        for (int i = 0; i < rows * cols; i++) {
            if (matching[i] == -1) continue;

            int r1 = grid.getRow(i);
            int c1 = grid.getCol(i);
            int r2 = grid.getRow(matching[i]);
            int c2 = grid.getCol(matching[i]);

            if (r1 == r2) {
                grid.setCell(r1, Math.min(c1, c2), '<');
                grid.setCell(r1, Math.max(c1, c2), '>');
            } else {
                grid.setCell(Math.min(r1, r2), c1, '^');
                grid.setCell(Math.max(r1, r2), c2, 'v');
            }
        }
    }

    private boolean hasUnmatchedEmptyCells() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid.getCell(r, c) == '.') return true;
            }
        }
        return false;
    }

    private void printGrid(FastWriter out) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                out.print(grid.getCell(r, c));
                if (c < cols - 1) out.print(' ');
            }
            out.printLine();
        }
    }
}

/**
 * Fast I/O for reading input.
 */
class FastReader {
    private final InputStream stream;
    private final byte[] buffer = new byte[1024];
    private int curChar;
    private int numChars;

    public FastReader(InputStream stream) {
        this.stream = stream;
    }

    private int read() {
        if (numChars == -1) throw new InputMismatchException();
        if (curChar >= numChars) {
            curChar = 0;
            try {
                numChars = stream.read(buffer);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (numChars <= 0) return -1;
        }
        return buffer[curChar++];
    }

    public int readInt() {
        int c = read();
        while (isSpaceChar(c)) c = read();
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        int res = 0;
        do {
            if (c < '0' || c > '9') throw new InputMismatchException();
            res = res * 10 + (c - '0');
            c = read();
        } while (!isSpaceChar(c));
        return res * sgn;
    }

    public String next() {
        int c = read();
        while (isSpaceChar(c)) c = read();
        StringBuilder res = new StringBuilder();
        do {
            res.appendCodePoint(c);
            c = read();
        } while (!isSpaceChar(c));
        return res.toString();
    }

    private boolean isSpaceChar(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }
}

/**
 * Fast I/O for writing output.
 */
class FastWriter {
    private final PrintWriter writer;

    public FastWriter(OutputStream outputStream) {
        this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
    }

    public void print(Object obj) {
        writer.print(obj);
    }

    public void print(char c) {
        writer.print(c);
    }

    public void printLine(Object obj) {
        writer.println(obj);
    }

    public void printLine() {
        writer.println();
    }

    public void close() {
        writer.close();
    }
}

import java.util.*;
import java.io.*;

/**
 * A solution to find a unique pairing of empty cells ('.') in a grid.
 * Each pair of adjacent cells is connected by arrows pointing to each other.
 */
public class GridPairingSolver {

    // Directional vectors: Right, Left, Down, Up
    private static final int[] ROW_OFFSETS = {0, 0, 1, -1};
    private static final int[] COL_OFFSETS = {1, -1, 0, 0};

    // Arrow characters pointing to the partner in the direction of the offsets above
    private static final char[] ARROW_HEADS = {'>', '<', 'v', '^'};
    private static final char[] OPPOSITE_ARROWS = {'<', '>', '^', 'v'};

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int[][] neighborCounts;

    public GridPairingSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.neighborCounts = new int[rows][cols];
    }

    /**
     * Executes the topological-sort-style pairing algorithm.
     */
    public void solve() {
        Deque<Point> leafQueue = new ArrayDeque<>();

        // Step 1: Initialize neighbor counts and find initial "leaf" cells (degree 1)
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    int count = countEmptyNeighbors(r, c);
                    neighborCounts[r][c] = count;
                    if (count == 1) {
                        leafQueue.add(new Point(r, c));
                    }
                }
            }
        }

        // Step 2: Process leaf cells to form pairs
        while (!leafQueue.isEmpty()) {
            Point current = leafQueue.poll();

            // Skip if this cell was already paired by a previous operation
            if (grid[current.row][current.col] != '.') {
                continue;
            }

            // Find the only available neighbor to pair with
            for (int i = 0; i < 4; i++) {
                int nr = current.row + ROW_OFFSETS[i];
                int nc = current.col + COL_OFFSETS[i];

                if (isValid(nr, nc) && grid[nr][nc] == '.') {
                    // Form a pair
                    grid[current.row][current.col] = ARROW_HEADS[i];
                    grid[nr][nc] = OPPOSITE_ARROWS[i];

                    // Update the neighbor counts for the neighbors of the newly paired partner
                    updateNeighborsOfPartner(nr, nc, leafQueue);
                    break; 
                }
            }
        }
    }

    private int countEmptyNeighbors(int r, int c) {
        int count = 0;
        for (int i = 0; i < 4; i++) {
            int nr = r + ROW_OFFSETS[i];
            int nc = c + COL_OFFSETS[i];
            if (isValid(nr, nc) && grid[nr][nc] == '.') {
                count++;
            }
        }
        return count;
    }

    private void updateNeighborsOfPartner(int partnerRow, int partnerCol, Deque<Point> queue) {
        for (int i = 0; i < 4; i++) {
            int nr = partnerRow + ROW_OFFSETS[i];
            int nc = partnerCol + COL_OFFSETS[i];

            if (isValid(nr, nc) && grid[nr][nc] == '.') {
                neighborCounts[nr][nc]--;
                if (neighborCounts[nr][nc] == 1) {
                    queue.add(new Point(nr, nc));
                }
            }
        }
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Checks if all empty cells have been successfully paired.
     */
    public boolean isFullyPaired() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    return false;
                }
            }
        }
        return true;
    }

    public void printGrid() {
        for (int r = 0; r < rows; r++) {
            System.out.println(new String(grid[r]));
        }
    }

    /**
     * Immutable representation of a cell coordinate.
     */
    private static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Fast I/O reader.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public char[][] readGrid(int rows, int cols) {
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = next().toCharArray();
            }
            return grid;
        }
    }

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        String nStr = reader.next();
        if (nStr == null) return;
        int rows = Integer.parseInt(nStr);
        int cols = reader.nextInt();

        char[][] grid = reader.readGrid(rows, cols);

        GridPairingSolver solver = new GridPairingSolver(rows, cols, grid);
        solver.solve();

        if (solver.isFullyPaired()) {
            solver.printGrid();
        } else {
            System.out.println("Not unique");
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.StringTokenizer;

/**
 * Solves the Domino Tiling problem using a degree-based leaf-pruning algorithm.
 * This approach identifies cells that have only one possible neighbor and 
 * iteratively fills the grid.
 */
public class DominoTilingSolver {

    private static final int[] ROW_OFFSETS = {-1, 1, 0, 0};
    private static final int[] COL_OFFSETS = {0, 0, -1, 1};

    public enum TilingResult {
        SUCCESS,
        NOT_UNIQUE
    }

    public static void main(String[] args) throws IOException {
        FastReader reader = new FastReader();

        String nStr = reader.next();
        if (nStr == null) return;
        int rows = Integer.parseInt(nStr);
        int cols = reader.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = reader.next().toCharArray();
        }

        DominoTiler tiler = new DominoTiler(rows, cols, grid);
        TilingResult result = tiler.solve();

        if (result == TilingResult.NOT_UNIQUE) {
            System.out.println("Not unique");
        } else {
            tiler.printGrid();
        }
    }

    /**
     * Encapsulates the logic for tiling the grid with dominoes.
     */
    static class DominoTiler {
        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final int[][] degrees;

        public DominoTiler(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            this.degrees = new int[rows][cols];
        }

        /**
         * Executes the tiling algorithm.
         * @return TilingResult indicating if the tiling was successful or not unique.
         */
        public TilingResult solve() {
            calculateDegrees();
            Deque<Integer> queue = initializeLeafQueue();
            processQueue(queue);

            if (hasRemainingEmptyCells()) {
                return TilingResult.NOT_UNIQUE;
            }
            return TilingResult.SUCCESS;
        }

        private void calculateDegrees() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.') {
                        degrees[r][c] = countEmptyNeighbors(r, c);
                    }
                }
            }
        }

        private int countEmptyNeighbors(int r, int c) {
            int count = 0;
            for (int i = 0; i < 4; i++) {
                int nr = r + ROW_OFFSETS[i];
                int nc = c + COL_OFFSETS[i];
                if (isWithinBounds(nr, nc) && grid[nr][nc] == '.') {
                    count++;
                }
            }
            return count;
        }

        private Deque<Integer> initializeLeafQueue() {
            Deque<Integer> queue = new ArrayDeque<>();
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.' && degrees[r][c] == 1) {
                        queue.add(r * cols + c);
                    }
                }
            }
            return queue;
        }

        private void processQueue(Deque<Integer> queue) {
            while (!queue.isEmpty()) {
                int pos = queue.poll();
                int r = pos / cols;
                int c = pos % cols;

                // Only process if the cell hasn't been filled by a previous step
                if (grid[r][c] != '.') {
                    continue;
                }

                // Find the only remaining empty neighbor
                int neighborR = -1;
                int neighborC = -1;
                for (int i = 0; i < 4; i++) {
                    int nr = r + ROW_OFFSETS[i];
                    int nc = c + COL_OFFSETS[i];
                    if (isWithinBounds(nr, nc) && grid[nr][nc] == '.') {
                        neighborR = nr;
                        neighborC = nc;
                        break;
                    }
                }

                // If a degree-1 cell has no empty neighbor, tiling is impossible 
                // (handled by the remaining dots check)
                if (neighborR != -1) {
                    placeDomino(r, c, neighborR, neighborC);
                    updateNeighborDegrees(neighborR, neighborC, queue);
                }
            }
        }

        private void placeDomino(int r1, int c1, int r2, int c2) {
            if (r1 == r2) { // Horizontal placement
                int minC = Math.min(c1, c2);
                int maxC = Math.max(c1, c2);
                grid[r1][minC] = '<';
                grid[r1][maxC] = '>';
            } else { // Vertical placement
                int minR = Math.min(r1, r2);
                int maxR = Math.max(r1, r2);
                grid[minR][c1] = '^';
                grid[maxR][c1] = 'v';
            }
        }

        private void updateNeighborDegrees(int r, int c, Deque<Integer> queue) {
            for (int i = 0; i < 4; i++) {
                int nr = r + ROW_OFFSETS[i];
                int nc = c + COL_OFFSETS[i];
                if (isWithinBounds(nr, nc) && grid[nr][nc] == '.') {
                    degrees[nr][nc]--;
                    if (degrees[nr][nc] == 1) {
                        queue.add(nr * cols + nc);
                    }
                }
            }
        }

        private boolean hasRemainingEmptyCells() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.') return true;
                }
            }
            return false;
        }

        private boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        public void printGrid() {
            StringBuilder sb = new StringBuilder();
            for (int r = 0; r < rows; r++) {
                sb.append(new String(grid[r])).append('\n');
            }
            System.out.print(sb.toString());
        }
    }

    /**
     * Efficient input reader for large datasets.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A solver for the Maze Direction problem.
 * The goal is to fill empty cells ('.') with direction arrows ('^', '>', 'v', '<')
 * such that the connectivity constraints are satisfied.
 */
public class MazeSolverApp {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] grid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            MazeSolver solver = new MazeSolver(grid, rows, cols);
            String result = solver.solve();
            out.println(result);

        } catch (IOException e) {
            out.println("Error reading input: " + e.getMessage());
        } finally {
            out.close();
        }
    }

    /**
     * Represents a coordinate in the grid.
     */
    private record Point(int r, int c) {}

    /**
     * Handles the logic for solving the maze direction puzzle.
     */
    public static class MazeSolver {
        private static final int[] ROW_OFFSETS = {-1, 0, 1, 0};
        private static final int[] COL_OFFSETS = {0, 1, 0, -1};
        private static final char[] DIRECTION_SYMBOLS = {'^', '>', 'v', '<'};

        private final char[][] grid;
        private final int rows;
        private final int cols;
        private final int[][] degree;

        public MazeSolver(char[][] grid, int rows, int cols) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
            this.degree = new int[rows][cols];
        }

        /**
         * Executes the solving algorithm.
         * @return The formatted grid or "Not unique" if a solution cannot be completed.
         */
        public String solve() {
            calculateInitialDegrees();
            processLeaves();

            if (isFullyFilled()) {
                return formatGrid();
            } else {
                return "Not unique";
            }
        }

        private void calculateInitialDegrees() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] != '.') continue;

                    for (int i = 0; i < 4; i++) {
                        int nr = r + ROW_OFFSETS[i];
                        int nc = c + COL_OFFSETS[i];
                        if (isValidEmptyCell(nr, nc)) {
                            degree[r][c]++;
                        }
                    }
                }
            }
        }

        private void processLeaves() {
            Queue<Point> queue = new ArrayDeque<>();

            // Initialize queue with all cells having degree 1 (leaves)
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.' && degree[r][c] == 1) {
                        queue.add(new Point(r, c));
                        degree[r][c]--; // Mark as processed
                    }
                }
            }

            while (!queue.isEmpty()) {
                Point current = queue.poll();

                for (int i = 0; i < 4; i++) {
                    int nr = current.r + ROW_OFFSETS[i];
                    int nc = current.c + COL_OFFSETS[i];

                    if (isValidEmptyCell(nr, nc)) {
                        // Link current cell and neighbor with opposing arrows
                        // The neighbor's arrow is set based on the direction from 'current' to 'neighbor'
                        // The current cell's arrow is set to point back towards the neighbor
                        grid[nr][nc] = DIRECTION_SYMBOLS[i];
                        grid[current.r][current.c] = DIRECTION_SYMBOLS[(i + 2) % 4];
                        degree[nr][nc] = 0;

                        // Update neighbors of the newly filled neighbor
                        updateNeighborsOfFilledCell(nr, nc, queue);
                        break; 
                    }
                }
            }
        }

        private void updateNeighborsOfFilledCell(int r, int c, Queue<Point> queue) {
            for (int i = 0; i < 4; i++) {
                int nr = r + ROW_OFFSETS[i];
                int nc = c + COL_OFFSETS[i];

                if (isValidEmptyCell(nr, nc)) {
                    degree[nr][nc]--;
                    if (degree[nr][nc] == 1) {
                        queue.add(new Point(nr, nc));
                    }
                }
            }
        }

        private boolean isValidEmptyCell(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] == '.';
        }

        private boolean isFullyFilled() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.') return false;
                }
            }
            return true;
        }

        private String formatGrid() {
            StringBuilder sb = new StringBuilder();
            for (int r = 0; r < rows; r++) {
                sb.append(new String(grid[r])).append("\n");
            }
            return sb.toString().trim();
        }
    }

    /**
     * High-performance input reader.
     */
    public static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            this.reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver that finds a unique pairing of adjacent '.' cells in a grid.
 * If every '.' cell can be uniquely paired with exactly one neighbor,
 * the grid is printed with arrows pointing away from each pair.
 * Otherwise, "Not unique" is printed.
 */
public class GridPairingSolver {

    private static final String NOT_UNIQUE_MESSAGE = "Not unique";
    private static final int[] ROW_OFFSETS = {1, 0, -1, 0};
    private static final int[] COL_OFFSETS = {0, -1, 0, 1};

    private int rows;
    private int cols;
    private char[][] grid;

    public static void main(String[] args) {
        try {
            new GridPairingSolver().solve();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /**
     * Main execution flow.
     */
    public void solve() throws IOException {
        FastScanner scanner = new FastScanner(System.in);

        // Read grid dimensions
        if (!scanner.hasNext()) return;
        rows = scanner.nextInt();
        cols = scanner.nextInt();

        // Read grid content
        grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        // Attempt to solve the pairing problem
        if (attemptPairing()) {
            printGrid();
        } else {
            System.out.println(NOT_UNIQUE_MESSAGE);
        }
    }

    /**
     * Orchestrates the pairing algorithm using a leaf-processing approach.
     * 
     * @return true if all '.' cells are successfully paired, false otherwise.
     */
    private boolean attemptPairing() {
        int[][] neighborCounts = new int[rows][cols];
        boolean[][] visited = new boolean[rows][cols];
        char[][] resultGrid = new char[rows][cols];

        // Initialize result grid with the original grid content
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                resultGrid[r][c] = grid[r][c];
            }
        }

        Queue<Point> queue = new ArrayDeque<>();

        // Step 1: Calculate initial neighbor counts and identify 'leaf' cells
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    int count = countNeighbors(r, c);
                    neighborCounts[r][c] = count;
                    // A cell with only one neighbor is a starting point for pairing
                    if (count == 1) {
                        queue.add(new Point(r, c));
                    }
                }
            }
        }

        // Step 2: Iteratively pair cells starting from the leaves
        while (!queue.isEmpty()) {
            Point p1 = queue.poll();
            int r1 = p1.r;
            int c1 = p1.c;

            // If cell is already part of a pair or no longer a valid leaf, skip it
            if (visited[r1][c1] || neighborCounts[r1][c1] != 1) {
                continue;
            }

            // Find the single unvisited neighbor to pair with
            Point p2 = findUnvisitedNeighbor(r1, c1, visited);
            if (p2 == null) {
                continue;
            }

            int r2 = p2.r;
            int c2 = p2.c;

            // Mark both cells as visited/paired
            visited[r1][c1] = true;
            visited[r2][c2] = true;

            // Place arrows in the result grid
            applyArrows(r1, c1, r2, c2, resultGrid);

            // Update neighbor counts for cells adjacent to the newly paired cell (p2)
            for (int i = 0; i < 4; i++) {
                int nr = r2 + ROW_OFFSETS[i];
                int nc = c2 + COL_OFFSETS[i];

                if (isWithinBounds(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                    neighborCounts[nr][nc]--;
                    // If a neighbor becomes a leaf, add it to the queue
                    if (neighborCounts[nr][nc] == 1) {
                        queue.add(new Point(nr, nc));
                    }
                }
            }
        }

        // Step 3: Validate if any '.' cell remains unpaired
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && !visited[r][c]) {
                    return false;
                }
            }
        }

        // Transfer the successfully paired result back to the main grid
        for (int r = 0; r < rows; r++) {
            grid[r] = resultGrid[r];
        }
        return true;
    }

    private int countNeighbors(int r, int c) {
        int count = 0;
        for (int i = 0; i < 4; i++) {
            int nr = r + ROW_OFFSETS[i];
            int nc = c + COL_OFFSETS[i];
            if (isWithinBounds(nr, nc) && grid[nr][nc] == '.') {
                count++;
            }
        }
        return count;
    }

    private Point findUnvisitedNeighbor(int r, int c, boolean[][] visited) {
        for (int i = 0; i < 4; i++) {
            int nr = r + ROW_OFFSETS[i];
            int nc = c + COL_OFFSETS[i];
            if (isWithinBounds(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                return new Point(nr, nc);
            }
        }
        return null;
    }

    /**
     * Sets arrows in the result grid based on the relative positions of the pair.
     * Following the original logic: arrows point away from each other.
     */
    private void applyArrows(int r1, int c1, int r2, int c2, char[][] res) {
        if (r1 < r2) { // Vertical pair, r1 is above r2
            res[r1][c1] = '^';
            res[r2][c2] = 'v';
        } else if (r1 > r2) { // Vertical pair, r1 is below r2
            res[r1][c1] = 'v';
            res[r2][c2] = '^';
        } else if (c1 < c2) { // Horizontal pair, c1 is left of c2
            res[r1][c1] = '<';
            res[r2][c2] = '>';
        } else { // Horizontal pair, c1 is right of c2
            res[r1][c1] = '>';
            res[r2][c2] = '<';
        }
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private void printGrid() {
        StringBuilder sb = new StringBuilder();
        for (int r = 0; r < rows; r++) {
            sb.append(new String(grid[r])).append('\n');
        }
        System.out.print(sb);
    }

    /**
     * Represents a coordinate in the grid.
     */
    private static class Point {
        final int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Optimized utility for fast input reading.
     */
    private static class FastScanner {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public FastScanner(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (numChars == -1) throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) return -1;
            }
            return buf[curChar++];
        }

        public boolean hasNext() {
            int c = read();
            while (c != -1 && isWhitespace(c)) {
                c = read();
            }
            if (c == -1) return false;
            curChar--; // Return character to the buffer
            return true;
        }

        public String next() {
            int c = read();
            while (isWhitespace(c)) {
                c = read();
            }
            StringBuilder sb = new StringBuilder();
            do {
                sb.appendCodePoint(c);
                c = read();
            } while (!isWhitespace(c) && c != -1);
            return sb.toString();
        }

        public int nextInt() {
            return (int) nextLong();
        }

        public long nextLong() {
            int c = read();
            while (isWhitespace(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res = res * 10 + (c - '0');
                c = read();
            } while (!isWhitespace(c) && c != -1);
            return res * sgn;
        }

        private boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver for the grid-based pathing puzzle.
 * The goal is to fill all '.' cells with directional arrows such that they 
 * form valid connections.
 */
public class GridPathSolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] initialGrid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                initialGrid[i] = reader.next().toCharArray();
            }

            GridSolver solver = new GridSolver(new Grid(initialGrid));
            String result = solver.solve();

            out.println(result);
        } catch (Exception e) {
            out.println("Error parsing input.");
        } finally {
            out.close();
        }
    }

    /**
     * Represents a coordinate in the grid.
     */
    private record Cell(int row, int col) {}

    /**
     * Defines the possible movements and their symbols.
     */
    private enum Direction {
        UP('^', -1, 0),
        DOWN('v', 1, 0),
        LEFT('<', 0, -1),
        RIGHT('>', 0, 1);

        final char symbol;
        final int rowOffset;
        final int colOffset;

        Direction(char symbol, int rowOffset, int colOffset) {
            this.symbol = symbol;
            this.rowOffset = rowOffset;
            this.colOffset = colOffset;
        }

        public Direction getOpposite() {
            return switch (this) {
                case UP -> DOWN;
                case DOWN -> UP;
                case LEFT -> RIGHT;
                case RIGHT -> LEFT;
            };
        }

        public static Direction fromOffset(int dr, int dc) {
            for (Direction d : values()) {
                if (d.rowOffset == dr && d.colOffset == dc) return d;
            }
            return null;
        }
    }

    /**
     * Manages the grid state and boundary checks.
     */
    private static class Grid {
        private final int rows;
        private final int cols;
        private final char[][] matrix;

        public Grid(char[][] matrix) {
            this.rows = matrix.length;
            this.cols = matrix[0].length;
            this.matrix = matrix;
        }

        public int getRows() { return rows; }
        public int getCols() { return cols; }

        public boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        public boolean isEmpty(int r, int c) {
            return isValid(r, c) && matrix[r][c] == '.';
        }

        public void setCell(int r, int c, char symbol) {
            matrix[r][c] = symbol;
        }

        public char getCell(int r, int c) {
            return matrix[r][c];
        }

        public long countEmptyNeighbors(int r, int c) {
            long count = 0;
            for (Direction d : Direction.values()) {
                if (isEmpty(r + d.rowOffset, c + d.colOffset)) {
                    count++;
                }
            }
            return count;
        }

        public boolean isFullyFilled() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (matrix[i][j] == '.') return false;
                }
            }
            return true;
        }

        @Override
        public String toString() {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    sb.append(matrix[i][j]);
                }
                sb.append("\n");
            }
            return sb.toString();
        }
    }

    /**
     * Contains the logic to solve the puzzle using a propagation algorithm.
     */
    private static class GridSolver {
        private final Grid grid;

        public GridSolver(Grid grid) {
            this.grid = grid;
        }

        public String solve() {
            Queue<Cell> processingQueue = new ArrayDeque<>();

            // Step 1: Find all empty cells that have exactly one empty neighbor.
            // These are the "anchors" for our propagation.
            for (int r = 0; r < grid.getRows(); r++) {
                for (int c = 0; c < grid.getCols(); c++) {
                    if (grid.isEmpty(r, c) && grid.countEmptyNeighbors(r, c) == 1) {
                        processingQueue.add(new Cell(r, c));
                    }
                }
            }

            // Step 2: Propagate the connections.
            while (!processingQueue.isEmpty()) {
                Cell current = processingQueue.poll();

                // If the cell was already filled by another propagation, skip it.
                if (!grid.isEmpty(current.row, current.col)) continue;

                // Find the only empty neighbor.
                for (Direction dir : Direction.values()) {
                    int nr = current.row + dir.rowOffset;
                    int nc = current.col + dir.colOffset;

                    if (grid.isEmpty(nr, nc)) {
                        // Match the pair: point the current cell and its neighbor away from each other
                        // as per the original algorithm's behavior.
                        grid.setCell(current.row, current.col, dir.getOpposite().symbol);
                        grid.setCell(nr, nc, dir.symbol);

                        // Check neighbors of the newly filled cell to see if they are now candidates.
                        for (Direction adjDir : Direction.values()) {
                            int nnr = nr + adjDir.rowOffset;
                            int nnc = nc + adjDir.colOffset;
                            if (grid.isEmpty(nnr, nnc) && grid.countEmptyNeighbors(nnr, nnc) == 1) {
                                processingQueue.add(new Cell(nnr, nnc));
                            }
                        }
                        break; 
                    }
                }
            }

            return grid.isFullyFilled() ? grid.toString().trim() : "Not unique";
        }
    }

    /**
     * Fast I/O utility for efficient reading.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * GridArrowSolver solves a grid-based puzzle where '.' cells must be replaced
 * by directional arrows ('^', 'v', '<', '>') based on their neighbors.
 */
public class GridArrowSolver {

    private static final char EMPTY = '.';
    private static final char UP = '^';
    private static final char DOWN = 'v';
    private static final char LEFT = '<';
    private static final char RIGHT = '>';

    private final int rows;
    private final int cols;
    private final char[][] grid;

    // Directional offsets for checking neighbors: Up, Down, Left, Right
    private static final int[] ROW_OFFSETS = {-1, 1, 0, 0};
    private static final int[] COL_OFFSETS = {0, 0, -1, 1};

    public GridArrowSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
    }

    /**
     * Represents a cell and its only available '.' neighbor.
     */
    private static class CellTarget {
        final int r, c;
        final int nr, nc;

        CellTarget(int r, int c, int nr, int nc) {
            this.r = r;
            this.c = c;
            this.nr = nr;
            this.nc = nc;
        }
    }

    public void solve() {
        Queue<CellTarget> queue = new LinkedList<>();

        // 1. Initial pass: find all empty cells that have exactly one empty neighbor
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                addCellToQueueIfUnique(r, c, queue);
            }
        }

        // 2. Process the queue
        while (!queue.isEmpty()) {
            CellTarget target = queue.poll();

            // If either the current cell or the target neighbor has already been processed, skip
            if (grid[target.r][target.c] != EMPTY || grid[target.nr][target.nc] != EMPTY) {
                continue;
            }

            // Assign arrows to both cells (pointing away from each other per original logic)
            assignArrows(target.r, target.c, target.nr, target.nc);

            // 3. After updating, check the neighbors of the newly updated target cell
            for (int i = 0; i < 4; i++) {
                int neighborR = target.nr + ROW_OFFSETS[i];
                int neighborC = target.nc + COL_OFFSETS[i];

                if (isValid(neighborR, neighborC) && grid[neighborR][neighborC] == EMPTY) {
                    addCellToQueueIfUnique(neighborR, neighborC, queue);
                }
            }
        }

        // 4. Final output
        printResult();
    }

    private void addCellToQueueIfUnique(int r, int c, Queue<CellTarget> queue) {
        if (grid[r][c] != EMPTY) return;

        int dotNeighbors = countDotNeighbors(r, c);
        if (dotNeighbors == 1) {
            int[] neighborCoords = findOnlyDotNeighbor(r, c);
            if (neighborCoords != null) {
                queue.add(new CellTarget(r, c, neighborCoords[0], neighborCoords[1]));
            }
        }
    }

    private int countDotNeighbors(int r, int c) {
        int count = 0;
        for (int i = 0; i < 4; i++) {
            int nr = r + ROW_OFFSETS[i];
            int nc = c + COL_OFFSETS[i];
            if (isValid(nr, nc) && grid[nr][nc] == EMPTY) {
                count++;
            }
        }
        return count;
    }

    private int[] findOnlyDotNeighbor(int r, int c) {
        for (int i = 0; i < 4; i++) {
            int nr = r + ROW_OFFSETS[i];
            int nc = c + COL_OFFSETS[i];
            if (isValid(nr, nc) && grid[nr][nc] == EMPTY) {
                return new int[]{nr, nc};
            }
        }
        return null;
    }

    private void assignArrows(int r1, int c1, int r2, int c2) {
        if (r1 > r2) { // r1 is below r2
            grid[r1][c1] = DOWN;
            grid[r2][c2] = UP;
        } else if (r1 < r2) { // r1 is above r2
            grid[r1][c1] = UP;
            grid[r2][c2] = DOWN;
        } else if (c1 > c2) { // c1 is right of c2
            grid[r1][c1] = RIGHT;
            grid[r2][c2] = LEFT;
        } else if (c1 < c2) { // c1 is left of c2
            grid[r1][c1] = LEFT;
            grid[r2][c2] = RIGHT;
        }
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private void printResult() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == EMPTY) {
                    System.out.println("Not unique");
                    return;
                }
            }
        }
        for (int r = 0; r < rows; r++) {
            System.out.println(new String(grid[r]));
        }
    }

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        char[][] map = new char[n][m];
        for (int i = 0; i < n; i++) {
            map[i] = sc.next().toCharArray();
        }

        new GridArrowSolver(n, m, map).solve();
    }

    /**
     * Efficient scanner for fast I/O.
     */
    static class FastScanner {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public FastScanner(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (numChars == -1) throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) return -1;
            }
            return buf[curChar++];
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solution to solve a grid-based domino pairing puzzle.
 * The goal is to pair all adjacent '.' cells such that each pair points away from each other.
 */
public class Solution {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] initialGrid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                String line = reader.readLine();
                if (line != null) {
                    initialGrid[i] = line.toCharArray();
                }
            }

            DominoSolver solver = new DominoSolver(rows, cols, initialGrid);
            out.println(solver.solve());

        } catch (IOException e) {
            out.println("Error reading input: " + e.getMessage());
        } finally {
            out.close();
        }
    }

    /**
     * Represents a coordinate in the grid.
     */
    static class Point {
        final int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Point)) return false;
            Point point = (Point) o;
            return r == point.r && c == point.c;
        }

        @Override
        public int hashCode() {
            return Objects.hash(r, c);
        }
    }

    /**
     * Manages the grid data, including cells and the degree of each '.' cell.
     */
    static class Grid {
        private final int rows;
        private final int cols;
        private final char[][] cells;
        private final int[][] degree;

        public Grid(int rows, int cols, char[][] initialCells) {
            this.rows = rows;
            this.cols = cols;
            this.cells = initialCells;
            this.degree = new int[rows][cols];
            calculateInitialDegrees();
        }

        private void calculateInitialDegrees() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (cells[r][c] == '.') {
                        degree[r][c] = countDotNeighbors(r, c);
                    }
                }
            }
        }

        private int countDotNeighbors(int r, int c) {
            int count = 0;
            int[] dr = {-1, 1, 0, 0};
            int[] dc = {0, 0, -1, 1};
            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i];
                int nc = c + dc[i];
                if (isValid(nr, nc) && cells[nr][nc] == '.') {
                    count++;
                }
            }
            return count;
        }

        public void setCell(int r, int c, char arrow, Queue<Point> queue) {
            cells[r][c] = arrow;
            // When a '.' becomes an arrow, decrement degree of all '.' neighbors
            int[] dr = {-1, 1, 0, 0};
            int[] dc = {0, 0, -1, 1};
            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i];
                int nc = c + dc[i];
                if (isValid(nr, nc) && cells[nr][nc] == '.') {
                    degree[nr][nc]--;
                    if (degree[nr][nc] == 1) {
                        queue.add(new Point(nr, nc));
                    }
                }
            }
        }

        public boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        public int getRows() { return rows; }
        public int getCols() { return cols; }
        public char[][] getCells() { return cells; }
        public int getDegree(int r, int c) { return degree[r][c]; }
        public char getCell(int r, int c) { return cells[r][c]; }
    }

    /**
     * Contains the logic to solve the domino puzzle.
     */
    static class DominoSolver {
        private final Grid grid;

        public DominoSolver(int rows, int cols, char[][] initialCells) {
            this.grid = new Grid(rows, cols, initialCells);
        }

        public String solve() {
            int dotCount = 0;
            for (int r = 0; r < grid.getRows(); r++) {
                for (int c = 0; c < grid.getCols(); c++) {
                    if (grid.getCell(r, c) == '.') dotCount++;
                }
            }

            // A perfect matching is impossible if the number of cells is odd
            if (dotCount % 2 != 0) return "Not unique";

            Queue<Point> queue = new LinkedList<>();
            for (int r = 0; r < grid.getRows(); r++) {
                for (int c = 0; c < grid.getCols(); c++) {
                    if (grid.getCell(r, c) == '.' && grid.getDegree(r, c) == 1) {
                        queue.add(new Point(r, c));
                    }
                }
            }

            while (!queue.isEmpty()) {
                Point p = queue.poll();
                if (grid.getCell(p.r, p.c) != '.') continue;

                Point neighbor = findOnlyDotNeighbor(p);
                if (neighbor == null) return "Not unique";

                applyPair(p, neighbor, queue);
            }

            // Final check: are there any unvisited dots?
            for (int r = 0; r < grid.getRows(); r++) {
                for (int c = 0; c < grid.getCols(); c++) {
                    if (grid.getCell(r, c) == '.') return "Not unique";
                }
            }

            return formatGrid();
        }

        private Point findOnlyDotNeighbor(Point p) {
            int[] dr = {-1, 1, 0, 0};
            int[] dc = {0, 0, -1, 1};
            for (int i = 0; i < 4; i++) {
                int nr = p.r + dr[i];
                int nc = p.c + dc[i];
                if (grid.isValid(nr, nc) && grid.getCell(nr, nc) == '.') {
                    return new Point(nr, nc);
                }
            }
            return null;
        }

        private void applyPair(Point p1, Point p2, Queue<Point> queue) {
            // Determine direction to set arrows pointing away from each other
            if (p2.r == p1.r - 1) { // p2 is above p1
                grid.setCell(p2.r, p2.c, '^', queue);
                grid.setCell(p1.r, p1.c, 'v', queue);
            } else if (p2.r == p1.r + 1) { // p2 is below p1
                grid.setCell(p2.r, p2.c, 'v', queue);
                grid.setCell(p1.r, p1.c, '^', queue);
            } else if (p2.c == p1.c - 1) { // p2 is left of p1
                grid.setCell(p2.r, p2.c, '<', queue);
                grid.setCell(p1.r, p1.c, '>', queue);
            } else if (p2.c == p1.c + 1) { // p2 is right of p1
                grid.setCell(p2.r, p2.c, '>', queue);
                grid.setCell(p1.r, p1.c, '<', queue);
            }
        }

        private String formatGrid() {
            StringBuilder sb = new StringBuilder();
            for (int r = 0; r < grid.getRows(); r++) {
                for (int c = 0; c < grid.getCols(); c++) {
                    sb.append(grid.getCell(r, c));
                }
                sb.append("\n");
            }
            return sb.toString().trim();
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public String readLine() throws IOException {
            return reader.readLine();
        }
    }
}

