/**
 * Manages the grid data and provides geometric helper methods.
 */
class Grid {
    private static final char EMPTY = '.';
    private static final char LEFT = '<';
    private static final char RIGHT = '>';
    private static final char UP = '^';
    private static final char DOWN = 'v';

    private final char[][] matrix;
    private final int rows;
    private final int cols;

    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public Grid(int rows, int cols, char[][] initialData) {
        this.rows = rows;
        this.cols = cols;
        this.matrix = initialData;
    }

    public int getRows() { return rows; }
    public int getCols() { return cols; }

    public char get(int r, int c) {
        if (!isValid(r, c)) return '\0';
        return matrix[r][c];
    }

    public void set(int r, int c, char val) {
        if (isValid(r, c)) {
            matrix[r][c] = val;
        }
    }

    public boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    public int getDegree(int r, int c) {
        if (!isValid(r, c) || get(r, c) != EMPTY) {
            return 0;
        }
        int degree = 0;
        for (int i = 0; i < 4; i++) {
            if (get(r + DR[i], c + DC[i]) == EMPTY) {
                degree++;
            }
        }
        return degree;
    }

    /**
     * Finds the only empty neighbor for a cell.
     * Returns null if no such neighbor exists.
     */
    public Point findOnlyEmptyNeighbor(int r, int c) {
        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];
            if (isValid(nr, nc) && get(nr, nc) == EMPTY) {
                return new Point(nr, nc);
            }
        }
        return null;
    }

    /**
     * Marks two adjacent cells with direction arrows.
     */
    public void markPath(int r1, int c1, int r2, int c2) {
        if (r1 == r2) { // Horizontal connection
            int minC = Math.min(c1, c2);
            int maxC = Math.max(c1, c2);
            set(r1, minC, LEFT);
            set(r1, maxC, RIGHT);
        } else { // Vertical connection
            int minR = Math.min(r1, r2);
            int maxR = Math.max(r1, r2);
            set(minR, c1, UP);
            set(maxR, c1, DOWN);
        }
    }

    public void print(PrintWriter out) {
        for (int i = 0; i < rows; i++) {
            out.println(new String(matrix[i]));
        }
    }
}

/**
 * Contains the logic to solve the grid problem.
 */
class Solver {
    private static final char EMPTY = '.';

    public void solve(InputReader in, PrintWriter out) {
        int rows = in.nextInt();
        int cols = in.nextInt();
        char[][] data = new char[rows][cols];
        int remainingEmptyCells = 0;

        for (int i = 0; i < rows; i++) {
            data[i] = in.next().toCharArray();
            for (int j = 0; j < cols; j++) {
                if (data[i][j] == EMPTY) {
                    remainingEmptyCells++;
                }
            }
        }

        Grid grid = new Grid(rows, cols, data);
        Queue<Point> queue = new LinkedList<>();

        // Initialize queue with all degree-1 cells
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid.getDegree(i, j) == 1) {
                    queue.add(new Point(i, j));
                }
            }
        }

        while (!queue.isEmpty()) {
            Point p = queue.poll();
            int r = p.r;
            int c = p.c;

            // If this cell was already covered, skip it
            if (grid.get(r, c) != EMPTY) {
                continue;
            }

            Point neighbor = grid.findOnlyEmptyNeighbor(r, c);
            // If no neighbor or neighbor is already covered, skip
            if (neighbor == null || grid.get(neighbor.r, neighbor.c) != EMPTY) {
                continue;
            }

            // Match the pair
            grid.markPath(r, c, neighbor.r, neighbor.c);
            remainingEmptyCells -= 2;

            // Check neighbors of the matched pair to see if their degree became 1
            updateQueue(r, c, queue, grid);
            updateQueue(neighbor.r, neighbor.c, queue, grid);
        }

        if (remainingEmptyCells > 0) {
            out.println("Not unique");
        } else {
            grid.print(out);
        }
    }

    private void updateQueue(int r, int c, Queue<Point> queue, Grid grid) {
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};
        for (int i = 0; i < 4; i++) {
            int nr = r + dr[i];
            int nc = c + dc[i];
            if (grid.isValid(nr, nc) && grid.get(nr, nc) == EMPTY && grid.getDegree(nr, nc) == 1) {
                queue.add(new Point(nr, nc));
            }
        }
    }
}

