import java.io.*;
import java.util.*;

/**
 * A program that solves a grid-based path puzzle by propagating connections
 * from endpoint cells (cells with only one empty neighbor).
 */
public class MazeSolver {

    private static final String NOT_UNIQUE_MESSAGE = "Not unique";
    private static final char EMPTY_CELL = '.';

    // Directional offsets for North, South, West, East
    private static final int[] ROW_OFFSETS = {-1, 1, 0, 0};
    private static final int[] COL_OFFSETS = {0, 0, -1, 1};

    private final int rows;
    private final int cols;
    private final char[][] grid;

    /**
     * Represents a coordinate in the grid.
     */
    private static class Point {
        final int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    public MazeSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
    }

    /**
     * Executes the solver logic using a Breadth-First Search (BFS) approach.
     * 
     * @return true if the grid is successfully filled, false if any '.' remain.
     */
    public boolean solve() {
        Queue<Point> queue = new LinkedList<>();
        boolean[][] visited = new boolean[rows][cols];

        // Step 1: Initialize queue with all cells that are potential endpoints (degree 1)
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (isCellEmpty(r, c) && countEmptyNeighbors(r, c) == 1) {
                    queue.offer(new Point(r, c));
                    visited[r][c] = true;
                }
            }
        }

        // Step 2: Propagate connections
        while (!queue.isEmpty()) {
            Point curr = queue.poll();

            for (int i = 0; i < 4; i++) {
                int nr = curr.r + ROW_OFFSETS[i];
                int nc = curr.c + COL_OFFSETS[i];

                // If we find an adjacent empty cell, link them and check their surroundings
                if (isCellEmpty(nr, nc)) {
                    applyDirectionalArrows(curr.r, curr.c, nr, nc);

                    // The updated cells might make their neighbors new endpoints
                    checkAndEnqueueNeighbors(nr, nc, queue, visited);
                    checkAndEnqueueNeighbors(curr.r, curr.c, queue, visited);
                }
            }
        }

        return isGridFullyFilled();
    }

    /**
     * Checks if a neighbor has become a new endpoint and adds it to the queue.
     */
    private void checkAndEnqueueNeighbors(int r, int c, Queue<Point> queue, boolean[][] visited) {
        for (int i = 0; i < 4; i++) {
            int nr = r + ROW_OFFSETS[i];
            int nc = c + COL_OFFSETS[i];

            if (isCellEmpty(nr, nc) && !visited[nr][nc]) {
                if (countEmptyNeighbors(nr, nc) == 1) {
                    visited[nr][nc] = true;
                    queue.offer(new Point(nr, nc));
                }
            }
        }
    }

    /**
     * Sets the direction arrows between two linked cells.
     * Note: Following the original logic, arrows point away from each other.
     */
    private void applyDirectionalArrows(int r1, int c1, int r2, int c2) {
        if (r2 < r1) { // Neighbor is North
            grid[r2][c2] = '^';
            grid[r1][c1] = 'v';
        } else if (r2 > r1) { // Neighbor is South
            grid[r2][c2] = 'v';
            grid[r1][c1] = '^';
        } else if (c2 < c1) { // Neighbor is West
            grid[r2][c2] = '<';
            grid[r1][c1] = '>';
        } else { // Neighbor is East
            grid[r2][c2] = '>';
            grid[r1][c1] = '<';
        }
    }

    private int countEmptyNeighbors(int r, int c) {
        int count = 0;
        for (int i = 0; i < 4; i++) {
            int nr = r + ROW_OFFSETS[i];
            int nc = c + COL_OFFSETS[i];
            if (isCellEmpty(nr, nc)) {
                count++;
            }
        }
        return count;
    }

    private boolean isCellEmpty(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] == EMPTY_CELL;
    }

    private boolean isGridFullyFilled() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == EMPTY_CELL) return false;
            }
        }
        return true;
    }

    public void printGrid(PrintWriter writer) {
        for (int r = 0; r < rows; r++) {
            writer.println(new String(grid[r]));
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter writer = new PrintWriter(new OutputStreamWriter(System.out));

        String header = reader.readLine();
        if (header == null) return;

        StringTokenizer tokenizer = new StringTokenizer(header);
        int n = Integer.parseInt(tokenizer.nextToken());
        int m = Integer.parseInt(tokenizer.nextToken());

        char[][] map = new char[n][m];
        for (int i = 0; i < n; i++) {
            map[i] = reader.readLine().toCharArray();
        }

        MazeSolver solver = new MazeSolver(n, m, map);

        if (solver.solve()) {
            solver.printGrid(writer);
        } else {
            writer.println(NOT_UNIQUE_MESSAGE);
        }

        writer.flush();
        writer.close();
    }
}

