/**
 * Represents a direction in the grid and its associated character mapping.
 */
enum Direction {
    UP(-1, 0, 'v', '^'),
    LEFT(0, -1, '>', '<'),
    RIGHT(0, 1, '<', '>'),
    DOWN(1, 0, '^', 'v');

    final int dr, dc;
    final char selfChar;
    final char neighborChar;

    Direction(int dr, int dc, char selfChar, char neighborChar) {
        this.dr = dr;
        this.dc = dc;
        this.selfChar = selfChar;
        this.neighborChar = neighborChar;
    }

    /**
     * Finds the direction based on the relative offset from a cell to its neighbor.
     */
    public static Direction fromOffset(int dr, int dc) {
        for (Direction d : values()) {
            if (d.dr == dr && d.dc == dc) {
                return d;
            }
        }
        return null;
    }
}

/**
 * A simple data carrier for grid coordinates.
 */
record Coordinate(int r, int c) {}

/**
 * Logic for solving the grid matching puzzle.
 */
class GridSolver {
    private final FastReader reader;
    private int rows;
    private int cols;
    private char[][] grid;
    private int[][] neighborCount;

    public GridSolver(FastReader reader) {
        this.reader = reader;
    }

    /**
     * Orchestrates the reading of input and the execution of the solver.
     */
    public void solve(PrintWriter out) {
        this.rows = reader.nextInt();
        this.cols = reader.nextInt();
        this.grid = new char[rows][cols];
        this.neighborCount = new int[rows][cols];

        for (int i = 0; i < rows; i++) {
            grid[i] = reader.next().toCharArray();
        }

        if (solveGrid()) {
            for (int i = 0; i < rows; i++) {
                out.println(new String(grid[i]));
            }
        } else {
            out.print("Not unique");
        }
        out.flush();
    }

    /**
     * The core algorithm using a degree-based reduction (similar to topological sort).
     * 
     * @return true if a unique solution was found, false otherwise.
     */
    private boolean solveGrid() {
        Queue<Coordinate> queue = new ArrayDeque<>(rows * cols);

        // 1. Initialize neighbor counts and populate initial queue
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    int count = countEmptyNeighbors(r, c);
                    neighborCount[r][c] = count;
                    if (count <= 1) {
                        queue.add(new Coordinate(r, c));
                    }
                }
            }
        }

        // 2. Process cells with 0 or 1 available neighbors
        while (!queue.isEmpty()) {
            Coordinate curr = queue.poll();

            // If cell is already filled, skip it
            if (grid[curr.r()][curr.c()] != '.') {
                continue;
            }

            // Find the first available neighbor
            Coordinate neighbor = findFirstEmptyNeighbor(curr);
            if (neighbor == null) {
                return false; // No valid neighbor to pair with
            }

            // Determine direction and fill the grid
            Direction dir = Direction.fromOffset(neighbor.r() - curr.r(), neighbor.c() - curr.c());
            if (dir == null) return false;

            grid[curr.r()][curr.c()] = dir.selfChar;
            grid[neighbor.r()][neighbor.c()] = dir.neighborChar;

            // Update counts for all neighbors of the newly filled neighbor
            for (Direction d : Direction.values()) {
                int nr = neighbor.r() + d.dr;
                int nc = neighbor.c() + d.dc;

                if (isValid(nr, nc) && grid[nr][nc] == '.') {
                    neighborCount[nr][nc]--;
                    if (neighborCount[nr][nc] <= 1) {
                        queue.add(new Coordinate(nr, nc));
                    }
                }
            }
        }

        // 3. Final verification: ensure no '.' remain in the grid
        return isGridFullyFilled();
    }

    private int countEmptyNeighbors(int r, int c) {
        int count = 0;
        for (Direction d : Direction.values()) {
            int nr = r + d.dr;
            int nc = c + d.dc;
            if (isValid(nr, nc) && grid[nr][nc] == '.') {
                count++;
            }
        }
        return count;
    }

    private Coordinate findFirstEmptyNeighbor(Coordinate pos) {
        for (Direction d : Direction.values()) {
            int nr = pos.r() + d.dr;
            int nc = pos.c() + d.dc;
            if (isValid(nr, nc) && grid[nr][nc] == '.') {
                return new Coordinate(nr, nc);
            }
        }
        return null;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private boolean isGridFullyFilled() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') return false;
            }
        }
        return true;
    }
}

