import java.io.*;
import java.util.*;

/**
 * A program to solve a grid-based path/arrow placement problem.
 * The goal is to fill all '.' cells with directional arrows such that
 * the constraints of the degree-based leaf-propagation are met.
 */
public class Main {
    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        GridPathSolver solver = new GridPathSolver(reader, writer);
        solver.solve();

        writer.close();
    }

    static class GridPathSolver {
        // Directional deltas: Down, Up, Right, Left
        private static final int[] ROW_DELTAS = {1, -1, 0, 0};
        private static final int[] COL_DELTAS = {0, 0, 1, -1};

        // Symbols mapping based on original logic:
        // str[0] = "^v<>", str[1] = "v^><"
        // If direction is Down (idx 0), current gets '^', neighbor gets 'v'
        private static final char[] AWAY_SYMBOLS = {'^', 'v', '<', '>'};
        private static final char[] TOWARDS_SYMBOLS = {'v', '^', '>', '<'};

        private final FastReader reader;
        private final PrintWriter writer;

        private int rows;
        private int cols;
        private char[][] grid;
        private int[][] degrees;

        public GridPathSolver(FastReader reader, PrintWriter writer) {
            this.reader = reader;
            this.writer = writer;
        }

        public void solve() {
            if (!readInput()) return;

            initializeDegrees();
            if (processLeaves()) {
                if (isGridComplete()) {
                    printGrid();
                } else {
                    writer.println("Not unique");
                }
            } else {
                writer.println("Not unique");
            }
        }

        private boolean readInput() {
            try {
                rows = reader.nextInt();
                cols = reader.nextInt();
                grid = new char[rows][cols];
                degrees = new int[rows][cols];

                for (int i = 0; i < rows; i++) {
                    grid[i] = reader.next().toCharArray();
                }
                return true;
            } catch (Exception e) {
                return false;
            }
        }

        private void initializeDegrees() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.') {
                        calculateCellDegree(r, c);
                    }
                }
            }
        }

        private void calculateCellDegree(int r, int c) {
            // Check Right and Down to avoid double counting edges
            if (r + 1 < rows && grid[r + 1][c] == '.') {
                degrees[r][c]++;
                degrees[r + 1][c]++;
            }
            if (c + 1 < cols && grid[r][c + 1] == '.') {
                degrees[r][c]++;
                degrees[r][c + 1]++;
            }
        }

        private boolean processLeaves() {
            Deque<Point> leafQueue = new ArrayDeque<>();

            // Initial leaf detection
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.' && degrees[r][c] == 1) {
                        leafQueue.add(new Point(r, c));
                    }
                }
            }

            while (!leafQueue.isEmpty()) {
                Point current = leafQueue.poll();

                // If this cell was already filled by a neighbor's processing
                if (grid[current.r][current.c] != '.') {
                    continue;
                }

                Point neighbor = findEmptyNeighbor(current);
                if (neighbor == null) {
                    return false; // No valid neighbor found to connect to
                }

                int dirIdx = getDirectionIndex(current, neighbor);

                // Apply the directional symbols
                grid[current.r][current.c] = AWAY_SYMBOLS[dirIdx];
                grid[neighbor.r][neighbor.c] = TOWARDS_SYMBOLS[dirIdx];

                // Update neighbors of the newly filled neighbor cell
                updateNeighborDegrees(neighbor, leafQueue);
            }
            return true;
        }

        private Point findEmptyNeighbor(Point p) {
            for (int i = 0; i < 4; i++) {
                int nr = p.r + ROW_DELTAS[i];
                int nc = p.c + COL_DELTAS[i];

                if (isValid(nr, nc) && grid[nr][nc] == '.') {
                    return new Point(nr, nc);
                }
            }
            return null;
        }

        private int getDirectionIndex(Point from, Point to) {
            for (int i = 0; i < 4; i++) {
                if (from.r + ROW_DELTAS[i] == to.r && from.c + COL_DELTAS[i] == to.c) {
                    return i;
                }
            }
            return -1;
        }

        private void updateNeighborDegrees(Point neighbor, Deque<Point> queue) {
            for (int i = 0; i < 4; i++) {
                int nr = neighbor.r + ROW_DELTAS[i];
                int nc = neighbor.c + COL_DELTAS[i];

                if (isValid(nr, nc)) {
                    degrees[nr][nc]--;
                    if (grid[nr][nc] == '.' && degrees[nr][nc] == 1) {
                        queue.add(new Point(nr, nc));
                    }
                }
            }
        }

