/**
 * GridMatcher solves a bipartite matching problem on a grid.
 * It identifies unique pairings of adjacent empty cells.
 */
public class GridMatcher {

    // Directional offsets: Right, Down, Left, Up
    private static final int[] DR = {0, 1, 0, -1};
    private static final int[] DC = {1, 0, -1, 0};

    // Characters representing the direction pointing FROM the current cell 
    // and TO the matched neighbor.
    // Based on the original logic: if neighbor is to the Right (index 0),
    // current cell points '<' and neighbor points '>'.
    private static final char[] CURRENT_CHAR = {'<', '^', '>', 'v'};
    private static final char[] NEIGHBOR_CHAR = {'>', 'v', '<', '^'};

    public static void main(String[] args) {
        try (FastReader reader = new FastReader(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            int rows = reader.nextInt();
            int cols = reader.nextInt();

            GridSolver solver = new GridSolver(rows, cols, reader);
            solver.solve(out);

        } catch (IOException e) {
            System.err.println("An error occurred while processing input: " + e.getMessage());
        }
    }

    /**
     * Logic for solving the grid pairing problem.
     */
    static class GridSolver {
        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final char[][] resultGrid;
        private final int[][] degrees;
        private final Queue<Point> queue;

        public GridSolver(int rows, int cols, FastReader reader) throws IOException {
            this.rows = rows;
            this.cols = cols;
            this.grid = new char[rows][cols];
            this.resultGrid = new char[rows][cols];
            this.degrees = new int[rows][cols];
            this.queue = new LinkedList<>();

            for (int i = 0; i < rows; i++) {
                String rowData = reader.next();
                for (int j = 0; j < cols; j++) {
                    char cell = rowData.charAt(j);
                    grid[i][j] = cell;
                    resultGrid[i][j] = cell;
                }
            }
        }

        public void solve(PrintWriter out) {
            initializeDegrees();
            processQueue();
            printResult(out);
        }

        /**
         * Calculates initial degrees of '.' cells and populates the queue with leaf nodes.
         */
        private void initializeDegrees() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    // Original algorithm starts processing from "odd" cells in a bipartite grid
                    if ((i + j) % 2 == 0 || grid[i][j] == '*') {
                        continue;
                    }

                    int degree = 0;
                    for (int k = 0; k < 4; k++) {
                        int ni = i + DR[k];
                        int nj = j + DC[k];
                        if (isWithinBounds(ni, nj) && grid[ni][nj] == '.') {
                            degree++;
                        }
                    }
                    degrees[i][j] = degree;
                    if (degree == 1) {
                        queue.add(new Point(i, j));
                    }
                }
            }
        }

        /**
         * Uses a topological-sort-like approach to pair cells with degree 1.
         */
        private void processQueue() {
            while (!queue.isEmpty()) {
                Point current = queue.poll();
                int r = current.r;
                int c = current.c;

                // Find the neighbor that hasn't been paired yet
                int directionIdx = -1;
                for (int k = 0; k < 4; k++) {
                    int ni = r + DR[k];
                    int nj = c + DC[k];
                    if (isWithinBounds(ni, nj) && resultGrid[ni][nj] == '.') {
                        directionIdx = k;
                        break;
                    }
                }

                if (directionIdx == -1) {
                    break;
                }

                int nr = r + DR[directionIdx];
                int nc = c + DC[directionIdx];

                // Set the direction characters for the pair
                resultGrid[r][c] = CURRENT_CHAR[directionIdx];
                resultGrid[nr][nc] = NEIGHBOR_CHAR[directionIdx];

                // Update degrees of neighbors of the matched cell
                for (int k = 0; k < 4; k++) {
                    int nni = nr + DR[k];
                    int nnj = nc + DC[k];
                    if (isWithinBounds(nni, nnj) && grid[nni][nnj] == '.') {
                        degrees[nni][nnj]--;
                        if (degrees[nni][nnj] == 1) {
                            queue.add(new Point(nni, nnj));
                        }
                    }
                }
            }
        }

        private void printResult(PrintWriter out) {
            if (isMatchingComplete()) {
                for (int i = 0; i < rows; i++) {
                    out.println(new String(resultGrid[i]));
                }
            } else {
                out.println("Not unique");
            }
        }

        private boolean isMatchingComplete() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.' && resultGrid[i][j] == '.') {
                        return false;
                    }
                }
            }
            return true;
        }

        private boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * Lightweight coordinate container.
     */
    static class Point {
        final int r, c;
        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * High-performance reader for faster input processing.
     */
    static class FastReader implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream is) {
            this.reader = new BufferedReader(new InputStreamReader(is));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        @Override
        public void close() throws IOException {
            reader.close();
        }
    }
}

