class GridSolver {
    private static final String NOT_UNIQUE = "Not unique";
    private static final int[] DR = {1, 0, -1, 0};
    private static final int[] DC = {0, 1, 0, -1};

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int[][] degrees;
    private final Deque<int[]> queue = new ArrayDeque<>();

    public GridSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.degrees = new int[rows][cols];
    }

    /**
     * Executes the solving algorithm and prints the result to the provided PrintWriter.
     */
    public void solve(PrintWriter out) {
        // 1. Initialize degrees for all '.' cells
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    int count = countEmptyNeighbors(r, c);
                    degrees[r][c] = count;

                    if (count == 0) {
                        out.println(NOT_UNIQUE);
                        return;
                    }
                    if (count == 1) {
                        queue.add(new int[]{r, c});
                    }
                }
            }
        }

        // 2. Process cells with only one possible connection
        while (!queue.isEmpty()) {
            int[] pos = queue.poll();
            int r = pos[0];
            int c = pos[1];

            // If cell was already processed by another connection, skip
            if (grid[r][c] != '.') {
                continue;
            }

            // Find the only '.' neighbor
            int[] neighbor = findEmptyNeighbor(r, c);
            if (neighbor == null) {
                out.println(NOT_UNIQUE);
                return;
            }

            int nr = neighbor[0];
            int nc = neighbor[1];

            // Assign arrows to both cells in the pair
            assignArrows(r, c, nr, nc);

            // Update neighbors of the two newly filled cells
            if (!updateNeighborDegrees(r, c, out) || !updateNeighborDegrees(nr, nc, out)) {
                out.println(NOT_UNIQUE);
                return;
            }
        }

        // 3. Final validation: Check if any '.' cells remain unfilled
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    out.println(NOT_UNIQUE);
                    return;
                }
            }
        }

        // 4. Print the resulting grid
        for (int r = 0; r < rows; r++) {
            out.println(new String(grid[r]));
        }
    }

    private int countEmptyNeighbors(int r, int c) {
        int count = 0;
        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];
            if (isValid(nr, nc) && grid[nr][nc] == '.') {
                count++;
            }
        }
        return count;
    }

    private int[] findEmptyNeighbor(int r, int c) {
        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];
            if (isValid(nr, nc) && grid[nr][nc] == '.') {
                return new int[]{nr, nc};
            }
        }
        return null;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Assigns arrows to both cells such that they point away from each other,
     * maintaining the specific logic required by the original implementation.
     */
    private void assignArrows(int r1, int c1, int r2, int c2) {
        if (r1 == r2) { // Horizontal connection
            int minC = Math.min(c1, c2);
            int maxC = Math.max(c1, c2);
            grid[r1][minC] = '<';
            grid[r1][maxC] = '>';
        } else { // Vertical connection
            int minR = Math.min(r1, r2);
            int maxR = Math.max(r1, r2);
            grid[minR][c1] = '^';
            grid[maxR][c1] = 'v';
        }
    }

    /**
     * Decrements degrees of neighbors and adds them to the queue if degree becomes 1.
     * Returns false if a degree hits 0 (dead end).
     */
    private boolean updateNeighborDegrees(int r, int c, PrintWriter out) {
        // Note: We only care about neighbors that are still '.'
        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];
            if (isValid(nr, nc) && grid[nr][nc] == '.') {
                degrees[nr][nc]--;
                if (degrees[nr][nc] == 0) {
                    return false;
                }
                if (degrees[nr][nc] == 1) {
                    queue.add(new int[]{nr, nc});
                }
            }
        }
        return true;
    }
}

