/**
 * Logic for solving the grid-based path/tiling problem.
 * The algorithm uses a greedy approach to find cells with degree 1 
 * and connects them to their only available neighbor.
 */
class GridPathSolver {
    private static final char EMPTY = '.';
    private static final char LEFT = '<';
    private static final char RIGHT = '>';
    private static final char UP = '^';
    private static final char DOWN = 'v';

    private static final int[][] DIRECTIONS = {
        {0, 1},  // Right
        {0, -1}, // Left
        {1, 0},  // Down
        {-1, 0}  // Up
    };

    private final int rows;
    private final int cols;
    private final char[][] grid;

    /**
     * Represents a coordinate in the grid.
     */
    private record Point(int r, int c) {}

    public GridPathSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
    }

    public void solve(PrintWriter out) {
        int emptyCells = countEmptyCells();
        Queue<Point> queue = new LinkedList<>();

        // Initialize queue with all cells that have exactly one neighbor
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (getDegree(i, j) == 1) {
                    queue.add(new Point(i, j));
                }
            }
        }

        while (!queue.isEmpty()) {
            Point p1 = queue.poll();

            // Skip if the cell is no longer empty or no longer has degree 1
            if (grid[p1.r][p1.c] != EMPTY || getDegree(p1.r, p1.c) != 1) {
                continue;
            }

            Point p2 = findOnlyNeighbor(p1);
            if (p2 == null) {
                continue;
            }

            // Apply the covering logic
            cover(p1, p2);
            emptyCells -= 2;

            // Re-check neighbors of both processed cells for new degree-1 candidates
            updateNeighborhood(p1, queue);
            updateNeighborhood(p2, queue);
        }

        if (emptyCells > 0) {
            out.println("Not unique");
        } else {
            printGrid(out);
        }
    }

    private int countEmptyCells() {
        int count = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == EMPTY) count++;
            }
        }
        return count;
    }

    private int getDegree(int r, int c) {
        if (isOutOfBounds(r, c) || grid[r][c] != EMPTY) {
            return 0;
        }
        int degree = 0;
        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            if (!isOutOfBounds(nr, nc) && grid[nr][nc] == EMPTY) {
                degree++;
            }
        }
        return degree;
    }

    private Point findOnlyNeighbor(Point p) {
        for (int[] dir : DIRECTIONS) {
            int nr = p.r + dir[0];
            int nc = p.c + dir[1];
            if (!isOutOfBounds(nr, nc) && grid[nr][nc] == EMPTY) {
                return new Point(nr, nc);
            }
        }
        return null;
    }

    private void cover(Point p1, Point p2) {
        if (p1.r == p2.r) {
            // Horizontal connection
            int minC = Math.min(p1.c, p2.c);
            int maxC = Math.max(p1.c, p2.c);
            grid[p1.r][minC] = LEFT;
            grid[p1.r][maxC] = RIGHT;
        } else {
            // Vertical connection
            int minR = Math.min(p1.r, p2.r);
            int maxR = Math.max(p1.r, p2.r);
            grid[minR][p1.c] = UP;
            grid[maxR][p1.c] = DOWN;
        }
    }

    private void updateNeighborhood(Point p, Queue<Point> queue) {
        // Check the 3x3 area around the modified cell for new degree-1 candidates
        for (int dr = -1; dr <= 1; dr++) {
            for (int dc = -1; dc <= 1; dc++) {
                int nr = p.r + dr;
                int nc = p.c + dc;
                if (!isOutOfBounds(nr, nc) && getDegree(nr, nc) == 1) {
                    queue.add(new Point(nr, nc));
                }
            }
        }
    }

    private boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= rows || c < 0 || c >= cols;
    }

    private void printGrid(PrintWriter out) {
        for (int i = 0; i < rows; i++) {
            out.println(new String(grid[i]));
        }
    }
}

