/**
 * A solution to the Arrow Grid problem.
 * The goal is to fill a grid of '.' cells with arrows such that every cell 
 * is part of a unique path. This is achieved by identifying "leaves" 
 * (cells with only one neighbor) and propagating the arrow placement.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] grid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            ArrowGridSolver solver = new ArrowGridSolver(rows, cols, grid);
            solver.solve(writer);
        } catch (Exception e) {
            // Handle potential input errors
        } finally {
            writer.close();
        }
    }

    static class ArrowGridSolver {
        private final int rows;
        private final int cols;
        private final char[][] grid;

        // Direction offsets: UP, RIGHT, DOWN, LEFT
        private static final int[] ROW_OFFSETS = {-1, 0, 1, 0};
        private static final int[] COL_OFFSETS = {0, 1, 0, -1};

        // Symbols corresponding to the direction mapping above
        // Note: The original logic places arrows pointing AWAY from the connection
        private static final char[] ARROW_SYMBOLS = {'v', '<', '^', '>'};

        public ArrowGridSolver(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
        }

        public void solve(PrintWriter out) {
            Queue<Point> queue = new ArrayDeque<>();

            // Step 1: Find initial "leaf" cells (cells with exactly one '.' neighbor)
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (isCellEmpty(r, c) && countEmptyNeighbors(r, c) == 1) {
                        queue.add(new Point(r, c));
                    }
                }
            }

            // Step 2: BFS to propagate arrow placement
            while (!queue.isEmpty()) {
                Point current = queue.poll();

                // If the cell is no longer empty, it has already been processed
                if (!isCellEmpty(current.r, current.c)) {
                    continue;
                }

                int direction = getNeighborDirection(current.r, current.c);
                if (direction == -1) {
                    continue;
                }

                // Neighbor coordinates
                int nr = current.r + ROW_OFFSETS[direction];
                int nc = current.c + COL_OFFSETS[direction];

                // Place arrows in the current cell and its neighbor
                // Using direction ^ 2 to match the original logic's bitwise pairing
                grid[current.r][current.c] = ARROW_SYMBOLS[direction];
                grid[nr][nc] = ARROW_SYMBOLS[direction ^ 2];

                // Step 3: Check if the neighbor's neighbors have now become leaves
                for (int i = 0; i < 4; i++) {
                    int nnr = nr + ROW_OFFSETS[i];
                    int nnc = nc + COL_OFFSETS[i];
                    if (isCellEmpty(nnr, nnc) && countEmptyNeighbors(nnr, nnc) == 1) {
                        queue.add(new Point(nnr, nnc));
                    }
                }
            }

            // Step 4: Verify if all '.' cells were filled
            if (hasUnfilledCells()) {
                out.println("Not unique");
            } else {
                printGrid(out);
            }
        }

        private boolean isCellEmpty(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] == '.';
        }

        private int countEmptyNeighbors(int r, int c) {
            int count = 0;
            for (int i = 0; i < 4; i++) {
                if (isCellEmpty(r + ROW_OFFSETS[i], c + COL_OFFSETS[i])) {
                    count++;
                }
            }
            return count;
        }

        /**
         * Returns the index of the direction (0-3) where the single neighbor is located.
         * Returns -1 if no neighbor is found.
         */
        private int getNeighborDirection(int r, int c) {
            for (int i = 0; i < 4; i++) {
                if (isCellEmpty(r + ROW_OFFSETS[i], c + COL_OFFSETS[i])) {
                    return i;
                }
            }
            return -1;
        }

        private boolean hasUnfilledCells() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.') return true;
                }
            }
            return false;
        }

        private void printGrid(PrintWriter out) {
            for (int r = 0; r < rows; r++) {
                out.println(new String(grid[r]));
            }
        }
    }

    /**
     * Simple helper class to represent grid coordinates.
     */
    static class Point {
        final int r, c;
        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Fast I/O utility for efficient reading.
     */
    static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

