/**
 * ArrowGridSolver solves the problem of finding a unique orientation 
 * for arrows in a grid of dots ('.') and obstacles ('*').
 */
public class ArrowGridSolver {

    private static class Cell {
        final int r, c;

        Cell(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    private int rows, cols;
    private char[][] grid;
    private boolean[][] visited;
    private int[][] degrees;

    public void solve() throws IOException {
        FastReader reader = new FastReader(System.in);

        // Parse dimensions
        String nStr = reader.next();
        if (nStr == null) return;
        rows = Integer.parseInt(nStr);
        cols = reader.nextInt();

        grid = new char[rows][cols];
        visited = new boolean[rows][cols];
        degrees = new int[rows][cols];

        for (int i = 0; i < rows; i++) {
            grid[i] = reader.next().toCharArray();
        }

        // Step 1: Calculate initial degrees (number of unvisited '.' neighbors)
        if (!calculateInitialDegrees()) {
            System.out.println("Not unique");
            return;
        }

        // Step 2: Process cells with degree 1 using a topological-sort-like approach
        if (!processQueue()) {
            System.out.println("Not unique");
            return;
        }

        // Step 3: Final validation - ensure all dots were visited
        if (!isEveryDotVisited()) {
            System.out.println("Not unique");
            return;
        }

        printGrid();
    }

    /**
     * Calculates the initial degree of each dot.
     * If any dot has no neighbors, the solution is not unique.
     */
    private boolean calculateInitialDegrees() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    List<Cell> neighbors = getNeighbors(r, c);
                    degrees[r][c] = neighbors.size();
                    if (degrees[r][c] == 0) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    /**
     * Processes cells with degree 1, marking them and their only neighbor as visited.
     */
    private boolean processQueue() {
        Deque<Cell> queue = new ArrayDeque<>();

        // Initialize queue with degree-1 cells
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && degrees[r][c] == 1) {
                    queue.add(new Cell(r, c));
                }
            }
        }

        while (!queue.isEmpty()) {
            Cell curr = queue.poll();

            if (visited[curr.r][curr.c]) {
                continue;
            }

            List<Cell> neighbors = getNeighbors(curr.r, curr.c);
            // If the cell has no unvisited neighbors left, it can't be uniquely determined
            if (neighbors.isEmpty()) {
                continue; 
            }

            // The problem guarantees degree 1, so we take the first available neighbor
            Cell neighbor = neighbors.get(0);

            // Mark both as visited
            visited[curr.r][curr.c] = true;
            visited[neighbor.r][neighbor.c] = true;

            // Set the arrow directions
            applyArrows(curr, neighbor);

            // Update the degrees of the neighbor's neighbors
            for (Cell nextNeighbor : getNeighbors(neighbor.r, neighbor.c)) {
                degrees[nextNeighbor.r][nextNeighbor.c]--;
                if (degrees[nextNeighbor.r][nextNeighbor.c] == 1) {
                    queue.add(nextNeighbor);
                }
            }
        }
        return true;
    }

    private void applyArrows(Cell curr, Cell neighbor) {
        if (neighbor.r < curr.r) { // Neighbor is Above
            grid[neighbor.r][neighbor.c] = '^';
            grid[curr.r][curr.c] = 'v';
        } else if (neighbor.r > curr.r) { // Neighbor is Below
            grid[neighbor.r][neighbor.c] = 'v';
            grid[curr.r][curr.c] = '^';
        } else if (neighbor.c < curr.c) { // Neighbor is Left
            grid[neighbor.r][neighbor.c] = '<';
            grid[curr.r][curr.c] = '>';
        } else { // Neighbor is Right
            grid[neighbor.r][neighbor.c] = '>';
            grid[curr.r][curr.c] = '<';
        }
    }

    private List<Cell> getNeighbors(int r, int c) {
        List<Cell> neighbors = new ArrayList<>();
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int i = 0; i < 4; i++) {
            int nr = r + dr[i];
            int nc = c + dc[i];

            if (isValid(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                neighbors.add(new Cell(nr, nc));
            }
        }
        return neighbors;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private boolean isEveryDotVisited() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && !visited[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    private void printGrid() {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < rows; i++) {
            sb.append(new String(grid[i])).append('\n');
        }
        System.out.print(sb.toString());
    }

    public static void main(String[] args) throws IOException {
        new ArrowGridSolver().solve();
    }

    /**
     * Fast I/O helper for efficient reading.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;

/**
 * A solver for the grid tiling problem. 
 * The goal is to pair adjacent empty cells ('.') with arrows pointing away from each other.
 * If the pairing is not unique or cannot be completed, it reports "Not unique".
 */
public class GridTilingSolver {

    private static final char EMPTY_CELL = '.';

    /**
     * Represents the four possible movement directions and the specific
     * arrow characters required by the problem's rules.
     */
    private enum Direction {
        DOWN(1, 0, '^', 'v'),
        RIGHT(0, 1, '<', '>'),
        UP(-1, 0, 'v', '^'),
        LEFT(0, -1, '>', '<');

        final int dr;
        final int dc;
        final char charForSelf;
        final char charForNeighbor;

        Direction(int dr, int dc, char charForSelf, char charForNeighbor) {
            this.dr = dr;
            this.dc = dc;
            this.charForSelf = charForSelf;
            this.charForNeighbor = charForNeighbor;
        }
    }

    /**
     * Helper class to store grid coordinates.
     */
    private static class Position {
        final int r, c;

        Position(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int[][] neighborCount;
    private int emptyCellsRemaining;

    public GridTilingSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.neighborCount = new int[rows][cols];
        this.emptyCellsRemaining = 0;
        initializeDegrees();
    }

    /**
     * Calculates the initial number of empty neighbors for each empty cell.
     */
    private void initializeDegrees() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] != EMPTY_CELL) {
                    continue;
                }
                emptyCellsRemaining++;
                for (Direction dir : Direction.values()) {
                    int nr = r + dir.dr;
                    int nc = c + dir.dc;
                    if (isValid(nr, nc) && grid[nr][nc] == EMPTY_CELL) {
                        neighborCount[r][c]++;
                    }
                }
            }
        }
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Executes the matching algorithm using a queue of "leaf" cells (degree 1).
     */
    public void solve() {
        Queue<Position> queue = new LinkedList<>();

        // Seed the queue with cells that have exactly one empty neighbor
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == EMPTY_CELL && neighborCount[r][c] == 1) {
                    queue.add(new Position(r, c));
                }
            }
        }

        while (!queue.isEmpty()) {
            Position pos = queue.poll();
            int r = pos.r;
            int c = pos.c;

            // If this cell was already paired by a previous operation, skip it
            if (grid[r][c] != EMPTY_CELL) {
                continue;
            }

            // Find the one available empty neighbor
            for (Direction dir : Direction.values()) {
                int nr = r + dir.dr;
                int nc = c + dir.dc;

                if (isValid(nr, nc) && grid[nr][nc] == EMPTY_CELL) {
                    // Match current cell with the neighbor
                    grid[r][c] = dir.charForSelf;
                    grid[nr][nc] = dir.charForNeighbor;
                    emptyCellsRemaining -= 2;

                    // Update the neighbor count for all cells surrounding the matched neighbor
                    updateNeighboringDegrees(nr, nc, queue);
                    break; 
                }
            }
        }
    }

    /**
     * Decrements the neighbor count for cells adjacent to the newly matched cell.
     */
    private void updateNeighboringDegrees(int matchedR, int matchedC, Queue<Position> queue) {
        for (Direction dir : Direction.values()) {
            int nr = matchedR + dir.dr;
            int nc = matchedC + dir.dc;

            if (isValid(nr, nc) && grid[nr][nc] == EMPTY_CELL) {
                neighborCount[nr][nc]--;
                if (neighborCount[nr][nc] == 1) {
                    queue.add(new Position(nr, nc));
                }
            }
        }
    }

    /**
     * Returns the final grid state or a message indicating non-uniqueness.
     */
    public String getResult() {
        if (emptyCellsRemaining > 0) {
            return "Not unique\n";
        }

        StringBuilder sb = new StringBuilder();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                sb.append(grid[r][c]);
            }
            sb.append('\n');
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int R = scanner.nextInt();
        int C = scanner.nextInt();
        char[][] grid = new char[R][C];

        for (int i = 0; i < R; i++) {
            String line = scanner.next();
            grid[i] = line.toCharArray();
        }

        GridTilingSolver solver = new GridTilingSolver(R, C, grid);
        solver.solve();
        System.out.print(solver.getResult());

        scanner.close();
    }
}

