/**
 * A solver for the grid arrow puzzle.
 * The goal is to fill all empty cells ('.') with arrows that point 
 * towards their respective neighbors in a unique configuration.
 */
public class Main {

    public static void main(String[] args) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String firstLine = reader.readLine();
            if (firstLine == null) return;

            StringTokenizer st = new StringTokenizer(firstLine);
            int rows = Integer.parseInt(st.nextToken());
            int cols = Integer.parseInt(st.nextToken());

            char[][] gridData = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                gridData[i] = reader.readLine().toCharArray();
            }

            GridSolver solver = new GridSolver(gridData, rows, cols);
            solver.solve();
            solver.printResult();

        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }
}

/**
 * Represents a coordinate in the grid.
 */
class Cell {
    final int r, c;

    Cell(int r, int c) {
        this.r = r;
        this.c = c;
    }
}

/**
 * Encapsulates movement directions and the characters used to represent 
 * an arrow pointing at or away from a neighbor.
 */
enum Direction {
    UP(-1, 0, 'v', '^'),
    DOWN(1, 0, '^', 'v'),
    LEFT(0, -1, '>', '<'),
    RIGHT(0, 1, '<', '>');

    final int dr, dc;
    final char currentCellChar;
    final char neighborCellChar;

    Direction(int dr, int dc, char currentCellChar, char neighborCellChar) {
        this.dr = dr;
        this.dc = dc;
        this.currentCellChar = currentCellChar;
        this.neighborCellChar = neighborCellChar;
    }

    static Direction getDirection(int dr, int dc) {
        for (Direction d : values()) {
            if (d.dr == dr && d.dc == dc) return d;
        }
        return null;
    }
}

/**
 * Contains the logic to solve the grid using a degree-based pruning algorithm.
 */
class GridSolver {
    private final char[][] grid;
    private final int rows;
    private final int cols;
    private final int[][] degree;
    private boolean isUnique = true;

    public GridSolver(char[][] grid, int rows, int cols) {
        this.grid = grid;
        this.rows = rows;
        this.cols = cols;
        this.degree = new int[rows][cols];
    }

    /**
     * Executes the solving algorithm.
     */
    public void solve() {
        calculateInitialDegrees();

        Queue<Cell> queue = new LinkedList<>();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] != '*' && degree[r][c] == 1) {
                    queue.add(new Cell(r, c));
                }
            }
        }

        while (!queue.isEmpty()) {
            Cell current = queue.poll();

            // If the cell was already filled by a previous neighbor processing
            if (grid[current.r][current.c] != '.') continue;

            for (Direction dir : Direction.values()) {
                int nr = current.r + dir.dr;
                int nc = current.c + dir.dc;

                if (isValidEmptyCell(nr, nc)) {
                    // Fill current cell and its neighbor with opposing arrows
                    grid[current.r][current.c] = dir.currentCellChar;
                    grid[nr][nc] = dir.neighborCellChar;

                    // Update degrees of the neighbors of the newly filled neighbor cell
                    updateNeighboringDegrees(nr, nc, queue);
                    break;
                }
            }
        }

        validateSolution();
    }

    private void calculateInitialDegrees() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*') continue;

                for (Direction dir : Direction.values()) {
                    int nr = r + dir.dr;
                    int nc = c + dir.dc;
                    if (isValidEmptyCell(nr, nc)) {
                        degree[r][c]++;
                    }
                }
            }
        }
    }

    private void updateNeighboringDegrees(int r, int c, Queue<Cell> queue) {
        for (Direction dir : Direction.values()) {
            int nr = r + dir.dr;
            int nc = c + dir.dc;

            if (isValidEmptyCell(nr, nc)) {
                degree[nr][nc]--;
                if (degree[nr][nc] == 1) {
                    queue.add(new Cell(nr, nc));
                }
            }
        }
    }

    private boolean isValidEmptyCell(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] == '.';
    }

    private void validateSolution() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    isUnique = false;
                    return;
                }
            }
        }
    }

    /**
     * Prints the resulting grid or the uniqueness error.
     */
    public void printResult() {
        if (!isUnique) {
            System.out.println("Not unique");
            return;
        }

        StringBuilder sb = new StringBuilder();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                sb.append(grid[r][c]);
            }
            sb.append("\n");
        }
        System.out.print(sb.toString());
    }
}

import java.util.*;
import java.io.*;

/**
 * The entry point of the application.
 * Handles input reading and outputting the final result.
 */
public class Main {
    public static void main(String[] args) {
        try {
            FastReader sc = new FastReader(System.in);
            int rows = sc.nextInt();
            int cols = sc.nextInt();

            char[][] grid = new char[rows][cols];
            int emptySpaces = 0;

            for (int i = 0; i < rows; i++) {
                String line = sc.next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                    if (grid[i][j] == '.') {
                        emptySpaces++;
                    }
                }
            }

            TileSolver solver = new TileSolver(grid, rows, cols, emptySpaces);
            System.out.println(solver.solve());

        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

/**
 * Represents the possible directions and the characters to be placed 
 * when a direction is chosen.
 */
enum Direction {
    RIGHT(0, 1, '<', '>'),
    DOWN(1, 0, '^', 'v'),
    LEFT(0, -1, '>', '<'),
    UP(-1, 0, 'v', '^');

    final int dr, dc;
    final char firstChar, secondChar;

    Direction(int dr, int dc, char firstChar, char secondChar) {
        this.dr = dr;
        this.dc = dc;
        this.firstChar = firstChar;
        this.secondChar = secondChar;
    }

    static final Direction[] VALUES = Direction.values();
}

/**
 * A data carrier representing a cell that is a candidate for tile placement.
 */
class PlacementCandidate {
    final int row;
    final int col;
    final Direction direction;

    PlacementCandidate(int row, int col, Direction direction) {
        this.row = row;
        this.col = col;
        this.direction = direction;
    }
}

/**
 * Contains the logic to solve the tile placement puzzle.
 */
class TileSolver {
    private final char[][] grid;
    private final int rows;
    private final int cols;
    private int remainingEmptySpaces;

    TileSolver(char[][] grid, int rows, int cols, int emptySpaces) {
        this.grid = grid;
        this.rows = rows;
        this.cols = cols;
        this.remainingEmptySpaces = emptySpaces;
    }

    /**
     * Executes the queue-based propagation algorithm to fill the grid.
     * @return The filled grid as a string, or "Not unique" if impossible.
     */
    public String solve() {
        Queue<PlacementCandidate> queue = new LinkedList<>();

        // Initial scan to find all cells with exactly one empty neighbor
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    findAndAddCandidate(r, c, queue);
                }
            }
        }

        while (!queue.isEmpty() && remainingEmptySpaces > 0) {
            PlacementCandidate candidate = queue.poll();
            int r = candidate.row;
            int c = candidate.col;
            Direction dir = candidate.direction;

            int nr = r + dir.dr;
            int nc = c + dir.dc;

            // Check if the cells are still valid for placement
            if (grid[r][c] != '.' || !isValid(nr, nc) || grid[nr][nc] != '.') {
                continue;
            }

            // Place the arrow pair
            grid[r][c] = dir.firstChar;
            grid[nr][nc] = dir.secondChar;
            remainingEmptySpaces -= 2;

            if (remainingEmptySpaces == 0) break;

            // Check neighbors of the newly filled neighbor to propagate the logic
            for (Direction d : Direction.VALUES) {
                int checkR = nr + d.dr;
                int checkC = nc + d.dc;
                if (isValid(checkR, checkC) && grid[checkR][checkC] == '.') {
                    findAndAddCandidate(checkR, checkC, queue);
                }
            }
        }

        return (remainingEmptySpaces == 0) ? buildGridString() : "Not unique";
    }

    /**
     * Identifies if a cell has exactly one empty neighbor and adds it to the queue.
     */
    private void findAndAddCandidate(int r, int c, Queue<PlacementCandidate> queue) {
        int emptyNeighborCount = 0;
        Direction targetDir = null;

        for (Direction dir : Direction.VALUES) {
            int nr = r + dir.dr;
            int nc = c + dir.dc;
            if (isValid(nr, nc) && grid[nr][nc] == '.') {
                emptyNeighborCount++;
                targetDir = dir;
            }
        }

        if (emptyNeighborCount == 1 && targetDir != null) {
            queue.add(new PlacementCandidate(r, c, targetDir));
        }
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private String buildGridString() {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < rows; i++) {
            sb.append(new String(grid[i])).append("\n");
        }
        return sb.toString();
    }
}

/**
 * Utility class for fast input parsing.
 */
