    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * PathFinder resolves a grid of paths by starting from endpoints (degree 1 nodes)
 * and propagating direction characters through the connected components.
 */
public class PathFinder {

    private static final int[] ROW_DELTA = {1, -1, 0, 0};
    private static final int[] COL_DELTA = {0, 0, 1, -1};

    private final int rows;
    private final int cols;
    private final char[][] grid;

    public PathFinder(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
    }

    /**
     * Orchestrates the path-filling process and outputs the result.
     */
    public void solve() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    fillPath(r, c);
                }
            }
        }

        if (isAllFilled()) {
            printGrid();
        } else {
            System.out.println("Not unique");
        }
    }

    /**
     * Recursively fills directions starting from a cell with exactly one neighbor.
     */
    private void fillPath(int r, int c) {
        if (countAdjacentEmptyCells(r, c) != 1) {
            return;
        }

        int[] neighbor = findOnlyEmptyNeighbor(r, c);
        if (neighbor == null) {
            return;
        }

        int nr = neighbor[0];
        int nc = neighbor[1];

        assignDirections(r, c, nr, nc);

        // Recurse on neighbors of the current cell
        for (int i = 0; i < 4; i++) {
            int rr = r + ROW_DELTA[i];
            int cc = c + COL_DELTA[i];
            if (isWithinBounds(rr, cc) && grid[rr][cc] == '.') {
                fillPath(rr, cc);
            }
        }

        // Recurse on neighbors of the newly filled neighbor cell
        for (int i = 0; i < 4; i++) {
            int rr = nr + ROW_DELTA[i];
            int cc = nc + COL_DELTA[i];
            if (isWithinBounds(rr, cc) && grid[rr][cc] == '.') {
                fillPath(rr, cc);
            }
        }
    }

    /**
     * Sets direction characters for the current cell and its neighbor.
     * The original logic sets arrows pointing away from each other.
     */
    private void assignDirections(int r, int c, int nr, int nc) {
        if (nr == r) { // Horizontal neighbor
            if (nc == c - 1) { // Neighbor is to the left
                grid[nr][nc] = '<';
                grid[r][c] = '>';
            } else { // Neighbor is to the right
                grid[nr][nc] = '>';
                grid[r][c] = '<';
            }
        } else { // Vertical neighbor
            if (nr == r - 1) { // Neighbor is above
                grid[nr][nc] = '^';
                grid[r][c] = 'v';
            } else { // Neighbor is below
                grid[nr][nc] = 'v';
                grid[r][c] = '^';
            }
        }
    }

    private int[] findOnlyEmptyNeighbor(int r, int c) {
        for (int i = 0; i < 4; i++) {
            int rr = r + ROW_DELTA[i];
            int cc = c + COL_DELTA[i];
            if (isWithinBounds(rr, cc) && grid[rr][cc] == '.') {
                return new int[]{rr, cc};
            }
        }
        return null;
    }

    private int countAdjacentEmptyCells(int r, int c) {
        int count = 0;
        for (int i = 0; i < 4; i++) {
            int rr = r + ROW_DELTA[i];
            int cc = c + COL_DELTA[i];
            if (isWithinBounds(rr, cc) && grid[rr][cc] == '.') {
                count++;
            }
        }
        return count;
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private boolean isAllFilled() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    return false;
                }
            }
        }
        return true;
    }

    private void printGrid() {
        StringBuilder sb = new StringBuilder();
        for (int r = 0; r < rows; r++) {
            sb.append(grid[r]);
            sb.append('\n');
        }
        System.out.print(sb.toString());
    }

    public static void main(String[] args) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String firstLine = reader.readLine();
            if (firstLine == null) return;

            StringTokenizer st = new StringTokenizer(firstLine);
            int rows = Integer.parseInt(st.nextToken());
            int cols = Integer.parseInt(st.nextToken());

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = reader.readLine();
                if (line != null) {
                    grid[i] = line.toCharArray();
                }
            }

            PathFinder solver = new PathFinder(rows, cols, grid);
            solver.solve();

        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        } catch (NumberFormatException e) {
            System.err.println("Invalid input format.");
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver for the domino tiling problem on a grid.
 * 
 * The algorithm uses a greedy "forced move" approach: 
 * If a cell has exactly one possible neighbor to pair with, it is a "forced move."
 * By processing these forced moves using a queue, we can determine if a unique 
 * tiling exists for the grid.
 */
public class DominoTilingSolver {

    private static final String NOT_UNIQUE = "Not unique";

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            String nStr = reader.next();
            if (nStr == null) return;

            int rows = Integer.parseInt(nStr);
            int cols = reader.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            String result = solve(rows, cols, grid);
            out.println(result);
        } catch (Exception e) {
            // In a production environment, use a logger
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Executes the tiling logic.
     * 
     * @param rows Number of rows in the grid.
     * @param cols Number of columns in the grid.
     * @param grid The initial grid state.
     * @return The completed grid as a formatted string, or "Not unique".
     */
    private static String solve(int rows, int cols, char[][] grid) {
        int emptyCount = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.') {
                    emptyCount++;
                }
            }
        }

        // A domino covers 2 cells; an odd count of empty cells is impossible to tile.
        if (emptyCount % 2 != 0) {
            return NOT_UNIQUE;
        }

        if (emptyCount == 0) {
            return formatGrid(grid);
        }

        Queue<Point> queue = new LinkedList<>();

        // Step 1: Identify all initial "forced moves" (cells with only 1 neighbor).
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.') {
                    int neighbors = countEmptyNeighbors(grid, i, j, rows, cols);
                    if (neighbors == 0) return NOT_UNIQUE;
                    if (neighbors == 1) {
                        queue.add(new Point(i, j));
                    }
                }
            }
        }

        // If there are empty cells but no forced moves, the tiling is not unique.
        if (queue.isEmpty()) {
            return NOT_UNIQUE;
        }

        // Direction vectors: Up, Left, Down, Right
        int[] dr = {-1, 0, 1, 0};
        int[] dc = {0, -1, 0, 1};

        boolean isPossible = true;
        while (!queue.isEmpty()) {
            Point p = queue.poll();
            int r = p.r;
            int c = p.c;

            // If the cell was already tiled by a previously processed neighbor
            if (grid[r][c] != '.') {
                continue;
            }

            // Step 2: Find which neighbor this cell MUST be paired with.
            int targetR = -1;
            int targetC = -1;
            char myChar = ' ';
            char neighborChar = ' ';

            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i];
                int nc = c + dc[i];
                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == '.') {
                    targetR = nr;
                    targetC = nc;
                    // Define the orientation of the domino
                    if (i == 0) { // Up
                        myChar = '^'; neighborChar = 'v';
                    } else if (i == 1) { // Left
                        myChar = '<'; neighborChar = '>';
                    } else if (i == 2) { // Down
                        myChar = 'v'; neighborChar = '^';
                    } else if (i == 3) { // Right
                        myChar = '>'; neighborChar = '<';
                    }
                    break; 
                }
            }

            if (targetR == -1) {
                isPossible = false;
                break;
            }

            // Step 3: Place the domino.
            grid[r][c] = myChar;
            grid[targetR][targetC] = neighborChar;

            // Step 4: Re-evaluate neighbors of the newly tiled cells.
            int[] checkR = {r, targetR};
            int[] checkC = {c, targetC};
            for (int i = 0; i < 2; i++) {
                for (int k = 0; k < 4; k++) {
                    int nnr = checkR[i] + dr[k];
                    int nnc = checkC[i] + dc[k];
                    if (nnr >= 0 && nnr < rows && nnc >= 0 && nnc < cols && grid[nnr][nnc] == '.') {
                        int neighbors = countEmptyNeighbors(grid, nnr, nnc, rows, cols);
                        if (neighbors == 0) {
                            isPossible = false;
                            break;
                        }
                        if (neighbors == 1) {
                            queue.add(new Point(nnr, nnc));
                        }
                    }
                }
                if (!isPossible) break;
            }
            if (!isPossible) break;
        }

        // Final Verification: Ensure no empty cells remain and no logical failures occurred.
        if (!isPossible) return NOT_UNIQUE;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.') return NOT_UNIQUE;
            }
        }

        return formatGrid(grid);
    }

    private static int countEmptyNeighbors(char[][] grid, int r, int c, int rows, int cols) {
        int count = 0;
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};
        for (int i = 0; i < 4; i++) {
            int nr = r + dr[i];
            int nc = c + dc[i];
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == '.') {
                count++;
            }
        }
        return count;
    }

    private static String formatGrid(char[][] grid) {
        StringBuilder sb = new StringBuilder();
        for (char[] row : grid) {
            sb.append(new String(row)).append("\n");
        }
        return sb.toString().trim();
    }

    private static class Point {
        final int r, c;
        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Efficient input reader for competitive programming style inputs.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A solver for the grid direction placement problem.
 * The goal is to fill empty cells ('.') with direction arrows ('^', 'v', '<', '>')
 * such that every cell is filled according to specific neighbor constraints.
 */
public class GridDirectionSolver {

    private static final char EMPTY_CELL = '.';

    /**
     * Represents the four possible cardinal directions.
     */
    private enum Direction {
        UP(-1, 0, '^'),
        DOWN(1, 0, 'v'),
        LEFT(0, -1, '<'),
        RIGHT(0, 1, '>');

        final int dr; // row offset
        final int dc; // column offset
        final char symbol;

        Direction(int dr, int dc, char symbol) {
            this.dr = dr;
            this.dc = dc;
            this.symbol = symbol;
        }

        /**
         * Returns the direction pointing in the opposite direction.
         */
        public Direction getOpposite() {
            return switch (this) {
                case UP -> DOWN;
                case DOWN -> UP;
                case LEFT -> RIGHT;
                case RIGHT -> LEFT;
            };
        }
    }

    private final int rows;
    private final int cols;
    private final char[][] grid;

    public GridDirectionSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
    }

    /**
     * Counts neighbors that are either out of bounds or already filled.
     */
    private int countNonEmptyNeighbors(int r, int c) {
        int count = 0;
        for (Direction d : Direction.values()) {
            int nr = r + d.dr;
            int nc = c + d.dc;
            if (isOutOfBounds(nr, nc) || grid[nr][nc] != EMPTY_CELL) {
                count++;
            }
        }
        return count;
    }

    private boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= rows || c < 0 || c >= cols;
    }

    /**
     * Finds the direction of the single empty neighbor if exactly one exists.
     */
    private Direction findEmptyNeighborDirection(int r, int c) {
        for (Direction d : Direction.values()) {
            int nr = r + d.dr;
            int nc = c + d.dc;
            if (!isOutOfBounds(nr, nc) && grid[nr][nc] == EMPTY_CELL) {
                return d;
            }
        }
        return null;
    }

    /**
     * Recursively attempts to fill empty cells using a DFS-based approach.
     * 
     * @return true if the filling process is valid, false if a conflict is found.
     */
    private boolean fillCellsRecursively(int r, int c) {
        if (isOutOfBounds(r, c) || grid[r][c] != EMPTY_CELL) {
            return true;
        }

        int neighborCount = countNonEmptyNeighbors(r, c);

        // If an empty cell is completely surrounded by non-empty cells/boundaries,
        // it cannot be filled according to the pairing logic.
        if (neighborCount == 4) {
            return false;
        }

        // If there is exactly one empty neighbor, we can form a pair.
        if (neighborCount == 3) {
            Direction dirToNeighbor = findEmptyNeighborDirection(r, c);
            if (dirToNeighbor != null) {
                int nr = r + dirToNeighbor.dr;
                int nc = c + dirToNeighbor.dc;

                // Original logic: Current cell and its neighbor point away from each other.
                // We set current to the opposite of the direction to the neighbor,
                // and the neighbor to the direction of the neighbor itself.
                grid[r][c] = dirToNeighbor.getOpposite().symbol;
                grid[nr][nc] = dirToNeighbor.symbol;

                // Propagate the check to neighbors of the newly filled cell.
                boolean success = true;
                for (Direction d : Direction.values()) {
                    success &= fillCellsRecursively(nr + d.dr, nc + d.dc);
                }
                return success;
            }
        }

        return true;
    }

    /**
     * Executes the solving logic and prints the result.
     */
    public void solve(PrintWriter out) {
        // 1. Attempt to fill the grid using the recursive rules.
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (!fillCellsRecursively(r, c)) {
                    out.println("Not unique");
                    return;
                }
            }
        }

        // 2. Verify that no empty cells remain.
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == EMPTY_CELL) {
                    out.println("Not unique");
                    return;
                }
            }
        }

        // 3. Output the successful grid.
        for (int r = 0; r < rows; r++) {
            out.println(new String(grid[r]));
        }
    }

    public static void main(String[] args) {
        try (FastReader sc = new FastReader(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            int n = sc.nextInt();
            int m = sc.nextInt();
            char[][] grid = new char[n][];
            for (int i = 0; i < n; i++) {
                grid[i] = sc.next().toCharArray();
            }

            GridDirectionSolver solver = new GridDirectionSolver(n, m, grid);
            solver.solve(out);
            out.flush();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /**
     * Efficient utility class for reading input.
     */
    static class FastReader implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        @Override
        public void close() throws IOException {
            reader.close();
        }
    }
}

