/**
 * Represents a 2D coordinate in the grid.
 */
record Point(int row, int col) {}

/**
 * Handles the core logic of solving the maze arrow puzzle.
 */
class MazeSolver {
    private static final int[] ROW_OFFSETS = {1, 0, -1, 0};
    private static final int[] COL_OFFSETS = {0, -1, 0, 1};

    private final FastReader reader;
    private char[][] grid;
    private int rows;
    private int cols;

    public MazeSolver(FastReader reader) {
        this.reader = reader;
    }

    /**
     * Orchestrates the solving process.
     */
    public void solve(PrintWriter out) {
        if (!initializeGrid()) return;

        int[][] neighborDegrees = calculateInitialDegrees();
        Deque<Point> queue = initializeProcessingQueue(neighborDegrees);

        processQueue(queue, neighborDegrees);

        if (hasRemainingEmptyCells()) {
            out.println("Not unique");
        } else {
            printGrid(out);
        }
    }

    private boolean initializeGrid() {
        try {
            rows = reader.nextInt();
            cols = reader.nextInt();
            grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.nextString().toCharArray();
            }
            return true;
        } catch (Exception e) {
            return false;
        }
    }

    private int[][] calculateInitialDegrees() {
        int[][] degrees = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    degrees[r][c] = countAdjacentEmptyCells(r, c);
                }
            }
        }
        return degrees;
    }

    private int countAdjacentEmptyCells(int r, int c) {
        int count = 0;
        for (int d = 0; d < 4; d++) {
            int nr = r + ROW_OFFSETS[d];
            int nc = c + COL_OFFSETS[d];
            if (isValid(nr, nc) && grid[nr][nc] == '.') {
                count++;
            }
        }
        return count;
    }

    private Deque<Point> initializeProcessingQueue(int[][] degrees) {
        Deque<Point> queue = new ArrayDeque<>();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && degrees[r][c] == 1) {
                    queue.add(new Point(r, c));
                }
            }
        }
        return queue;
    }

    private void processQueue(Deque<Point> queue, int[][] degrees) {
        while (!queue.isEmpty()) {
            Point current = queue.poll();
            int r = current.row();
            int c = current.col();

            // If cell was already processed as a neighbor of another pair, skip
            if (grid[r][c] != '.') continue;

            Point neighbor = findFirstEmptyNeighbor(r, c);
            if (neighbor == null) continue;

            // Pair the current cell with its neighbor
            applyArrows(r, c, neighbor.row(), neighbor.col());

            // Update degrees for neighbors of both cells in the pair
            decrementNeighborDegrees(r, c, degrees, queue);
            decrementNeighborDegrees(neighbor.row(), neighbor.col(), degrees, queue);
        }
    }

    private Point findFirstEmptyNeighbor(int r, int c) {
        for (int d = 0; d < 4; d++) {
            int nr = r + ROW_OFFSETS[d];
            int nc = c + COL_OFFSETS[d];
            if (isValid(nr, nc) && grid[nr][nc] == '.') {
                return new Point(nr, nc);
            }
        }
        return null;
    }

    private void decrementNeighborDegrees(int r, int c, int[][] degrees, Deque<Point> queue) {
        for (int d = 0; d < 4; d++) {
            int nr = r + ROW_OFFSETS[d];
            int nc = c + COL_OFFSETS[d];
            if (isValid(nr, nc) && grid[nr][nc] == '.') {
                degrees[nr][nc]--;
                if (degrees[nr][nc] == 1) {
                    queue.add(new Point(nr, nc));
                }
            }
        }
    }

    private void applyArrows(int r1, int c1, int r2, int c2) {
        if (r1 == r2) { // Horizontal pair
            int leftC = Math.min(c1, c2);
            int rightC = Math.max(c1, c2);
            grid[r1][leftC] = '<';
            grid[r1][rightC] = '>';
        } else { // Vertical pair
            int topR = Math.min(r1, r2);
            int botR = Math.max(r1, r2);
            grid[topR][c1] = '^';
            grid[botR][c1] = 'v';
        }
    }

    private boolean hasRemainingEmptyCells() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') return true;
            }
        }
        return false;
    }

    private void printGrid(PrintWriter out) {
        for (int r = 0; r < rows; r++) {
            out.println(new String(grid[r]));
        }
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

/**
 * High-performance input reader.
 */
class FastReader {
    private final InputStream stream;
    private final byte[] buffer = new byte[1024];
    private int curChar;
    private int numChars;

    public FastReader(InputStream stream) {
        this.stream = stream;
    }

    private int read() {
        if (numChars == -1) throw new InputMismatchException();
        if (curChar >= numChars) {
            curChar = 0;
            try {
                numChars = stream.read(buffer);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (numChars <= 0) return -1;
        }
        return buffer[curChar++];
    }

    public int nextInt() {
        return Integer.parseInt(nextString());
    }

    public String nextString() {
        int c = read();
        while (isSpaceChar(c)) c = read();
        StringBuilder res = new StringBuilder();
        do {
            res.appendCodePoint(c);
            c = read();
        } while (!isSpaceChar(c));
        return res.toString();
    }

    private boolean isSpaceChar(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves the "Puzzles" problem where a grid of empty spaces must be filled
 * with directional arrows such that every arrow points to another arrow.
 */
public class PuzzleSolver {

    private static final String NOT_UNIQUE = "Not unique";

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        int rows = reader.nextInt();
        int cols = reader.nextInt();

        char[][] initialGrid = new char[rows][cols];
        int emptyCount = 0;

        for (int i = 0; i < rows; i++) {
            String line = reader.next();
            for (int j = 0; j < cols; j++) {
                initialGrid[i][j] = line.charAt(j);
                if (initialGrid[i][j] == '.') {
                    emptyCount++;
                }
            }
        }

        // If the number of empty spaces is odd, a valid configuration is impossible.
        if (emptyCount % 2 != 0) {
            System.out.println(NOT_UNIQUE);
            return;
        }

        Grid grid = new Grid(initialGrid);
        boolean success = solve(grid, emptyCount);

        if (success) {
            System.out.print(grid.toString());
        } else {
            System.out.println(NOT_UNIQUE);
        }
    }

    /**
     * Core algorithm using a topological-sort-like approach to fill the grid.
     */
    private static boolean solve(Grid grid, int totalEmpty) {
        Queue<Point> candidateQueue = new LinkedList<>();

        // Initialize queue with all cells that have exactly one empty neighbor.
        for (int r = 0; r < grid.getRows(); r++) {
            for (int c = 0; c < grid.getCols(); c++) {
                if (grid.getChar(r, c) == '.' && grid.countEmptyNeighbors(r, c) == 1) {
                    candidateQueue.add(new Point(r, c));
                }
            }
        }

        int filledEmpty = 0;

        while (!candidateQueue.isEmpty()) {
            Point p = candidateQueue.poll();

            // If the cell was already filled by a neighbor's logic, skip it.
            if (grid.getChar(p.r, p.c) != '.') {
                continue;
            }

            List<Point> emptyNeighbors = grid.getEmptyNeighbors(p.r, p.c);

            // If it still has exactly one neighbor, we can place arrows.
            if (emptyNeighbors.size() == 1) {
                Point target = emptyNeighbors.get(0);

                Direction dir = Direction.fromOffset(target.r - p.r, target.c - p.c);
                if (dir == null) continue;

                // Place the arrows.
                grid.setChar(p.r, p.c, dir.currentArrow);
                grid.setChar(target.r, target.c, dir.oppositeArrow);
                filledEmpty += 2;

                // Check neighbors of the 'target' cell to see if they are now candidates.
                for (Point neighborOfTarget : grid.getNeighbors(target.r, target.c)) {
                    if (grid.getChar(neighborOfTarget.r, neighborOfTarget.c) == '.' 
                        && grid.countEmptyNeighbors(neighborOfTarget.r, neighborOfTarget.c) == 1) {
                        candidateQueue.add(neighborOfTarget);
                    }
                }
            }
        }

        return filledEmpty == totalEmpty;
    }

    /**
     * Represents a coordinate in the grid.
     */
    private static class Point {
        final int r, c;
        Point(int r, int c) { this.r = r; this.c = c; }
    }

    /**
     * Defines possible directions and their corresponding arrow characters.
     */
    private enum Direction {
        UP(-1, 0, '^', 'v'),
        DOWN(1, 0, 'v', '^'),
        LEFT(0, -1, '<', '>'),
        RIGHT(0, 1, '>', '<');

        final int dr, dc;
        final char currentArrow;
        final char oppositeArrow;

        Direction(int dr, int dc, char currentArrow, char oppositeArrow) {
            this.dr = dr;
            this.dc = dc;
            this.currentArrow = currentArrow;
            this.oppositeArrow = oppositeArrow;
        }

        static Direction fromOffset(int dr, int dc) {
            for (Direction d : values()) {
                if (d.dr == dr && d.dc == dc) return d;
            }
            return null;
        }
    }

    /**
     * Manages the grid data and boundary operations.
     */
    private static class Grid {
        private final char[][] cells;
        private final int rows;
        private final int cols;

        Grid(char[][] cells) {
            this.cells = cells;
            this.rows = cells.length;
            this.cols = cells[0].length;
        }

        int getRows() { return rows; }
        int getCols() { return cols; }
        char getChar(int r, int c) { return cells[r][c]; }
        void setChar(int r, int c, char val) { cells[r][c] = val; }

        boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        int countEmptyNeighbors(int r, int c) {
            int count = 0;
            for (Point n : getNeighbors(r, c)) {
                if (cells[n.r][n.c] == '.') count++;
            }
            return count;
        }

        List<Point> getEmptyNeighbors(int r, int c) {
            List<Point> emptyNeighbors = new ArrayList<>();
            for (Point n : getNeighbors(r, c)) {
                if (cells[n.r][n.c] == '.') emptyNeighbors.add(n);
            }
            return emptyNeighbors;
        }

        List<Point> getNeighbors(int r, int c) {
            List<Point> neighbors = new ArrayList<>();
            int[] dr = {-1, 1, 0, 0};
            int[] dc = {0, 0, -1, 1};
            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i];
                int nc = c + dc[i];
                if (isValid(nr, nc)) {
                    neighbors.add(new Point(nr, nc));
                }
            }
            return neighbors;
        }

        @Override
        public String toString() {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < rows; i++) {
                sb.append(new String(cells[i])).append('\n');
            }
            return sb.toString();
        }
    }

    /**
     * Optimized reader for fast I/O.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

