/**
 * A program that attempts to fill a grid of empty cells ('.') with arrows 
 * such that each cell is part of a path/pair, ultimately pointing toward 
 * obstacles ('*') or other arrows.
 */
public class Solution {

    public static void main(String[] args) {
        try {
            MazeSolver solver = new MazeSolver(System.in, System.out);
            solver.solve();
        } catch (IOException e) {
            System.err.println("Error processing input: " + e.getMessage());
        }
    }
}

class MazeSolver {
    private final FastReader reader;
    private final PrintWriter out;

    public MazeSolver(InputStream inputStream, OutputStream outputStream) {
        this.reader = new FastReader(inputStream);
        this.out = new PrintWriter(outputStream);
    }

    /**
     * Executes the core maze solving logic.
     */
    public void solve() throws IOException {
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = reader.nextString().toCharArray();
        }

        Maze maze = new Maze(grid, rows, cols);
        maze.calculateInitialDegrees();
        processLeaves(maze);

        if (maze.hasRemainingEmptyCells()) {
            out.println("Not unique");
        } else {
            maze.printGrid(out);
        }
        out.flush();
        out.close();
    }

    /**
     * Uses a leaf-removal algorithm (similar to topological sort) 
     * to fill the grid with arrows.
     */
    private void processLeaves(Maze maze) {
        Deque<Integer> queue = new ArrayDeque<>();

        // Initialize queue with "leaf" cells (those with only 1 empty neighbor)
        for (int r = 0; r < maze.getRows(); r++) {
            for (int c = 0; c < maze.getCols(); c++) {
                if (maze.getDegree(r, c) == 1) {
                    queue.add(r * maze.getCols() + c);
                }
            }
        }

        int[] dr = {1, -1, 0, 0};
        int[] dc = {0, 0, 1, -1};

        while (!queue.isEmpty()) {
            int cellIdx = queue.poll();
            int r = cellIdx / maze.getCols();
            int c = cellIdx % maze.getCols();

            // Skip if this cell has already been filled with an arrow
            if (maze.getChar(r, c) != '.') {
                continue;
            }

            // Look for an adjacent empty cell to form a pair/path
            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i];
                int nc = c + dc[i];

                if (maze.isWithinBounds(nr, nc) && maze.getChar(nr, nc) == '.') {
                    maze.assignArrowsToPair(nr, nc, r, c);

                    // After marking the neighbor, update the degrees of its neighbors
                    for (int j = 0; j < 4; j++) {
                        int nnr = nr + dr[j];
                        int nnc = nc + dc[j];
                        if (maze.isWithinBounds(nnr, nnc) && maze.getChar(nnr, nnc) == '.') {
                            maze.decrementDegree(nnr, nnc);
                            if (maze.getDegree(nnr, nnc) == 1) {
                                queue.add(nnr * maze.getCols() + nnc);
                            }
                        }
                    }
                    // Since we found and processed the only valid neighbor for this leaf, break
                    break; 
                }
            }
        }
    }
}

class Maze {
    private final char[][] grid;
    private final int rows;
    private final int cols;
    private final int[][] degree;

    public Maze(char[][] grid, int rows, int cols) {
        this.grid = grid;
        this.rows = rows;
        this.cols = cols;
        this.degree = new int[rows][cols];
    }

    public void calculateInitialDegrees() {
        int[] dr = {1, -1, 0, 0};
        int[] dc = {0, 0, 1, -1};

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*') continue;
                for (int i = 0; i < 4; i++) {
                    int nr = r + dr[i];
                    int nc = c + dc[i];
                    if (isWithinBounds(nr, nc) && grid[nr][nc] == '.') {
                        degree[r][c]++;
                    }
                }
            }
        }
    }

    /**
     * Assigns arrows to two adjacent cells. 
     * Maintains the specific directional logic of the original implementation.
     */
    public void assignArrowsToPair(int r1, int c1, int r2, int c2) {
        if (r1 == r2) {
            int y1 = c1, y2 = c2;
            if (y1 > y2) {
                int temp = y2; y2 = y1; y1 = temp;
            }
            grid[r1][y1] = '<';
            grid[r2][y2] = '>';
        } else {
            int x1 = r1, x2 = r2;
            if (x1 > x2) {
                int temp = x1; x1 = x2; x2 = temp;
            }
            // Note: The original logic ties the y-coordinates to the original x-coordinate swap
            grid[x1][c1] = '^';
            grid[x2][c2] = 'v';
        }
    }

    public void decrementDegree(int r, int c) {
        degree[r][c]--;
    }

    public boolean hasRemainingEmptyCells() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') return true;
            }
        }
        return false;
    }

    public void printGrid(PrintWriter out) {
        for (int r = 0; r < rows; r++) {
            out.println(new String(grid[r]));
        }
    }

    public boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    public char getChar(int r, int c) { return grid[r][c]; }
    public int getDegree(int r, int c) { return degree[r][c]; }
    public int getRows() { return rows; }
    public int getCols() { return cols; }
}

