class MazeSolver {
    // Cell type constants
    private static final int PATH = 0;
    private static final int WALL = 1;
    private static final int DOWN = 2;
    private static final int UP = 3;
    private static final int RIGHT = 4;
    private static final int LEFT = 5;

    private final int rows;
    private final int cols;
    private final int[][] grid;
    private final int[][] neighborDegrees;

    /**
     * Initializes the maze with padding to avoid boundary checks during traversal.
     */
    public MazeSolver(int rows, int cols, int[][] inputGrid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = new int[rows + 2][cols + 2];
        this.neighborDegrees = new int[rows + 2][cols + 2];

        // Initialize grid with walls and copy input
        for (int[] row : grid) {
            Arrays.fill(row, WALL);
        }

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                grid[i + 1][j + 1] = inputGrid[i][j];
            }
        }

        calculateInitialDegrees();
    }

    private void calculateInitialDegrees() {
        for (int i = 1; i <= rows; i++) {
            for (int j = 1; j <= cols; j++) {
                if (grid[i][j] == PATH) {
                    int count = 0;
                    if (grid[i - 1][j] == PATH) count++;
                    if (grid[i + 1][j] == PATH) count++;
                    if (grid[i][j - 1] == PATH) count++;
                    if (grid[i][j + 1] == PATH) count++;
                    neighborDegrees[i][j] = count;
                }
            }
        }
    }

    /**
     * The core algorithm to fill paths based on cells with a single neighbor.
     * @return The formatted grid as a string, or null if no unique solution exists.
     */
    public String solve() {
        boolean searchingForMore = true;

        while (searchingForMore) {
            boolean pathFoundInThisIteration = false;
            boolean allPathsResolved = true;

            for (int i = 1; i <= rows; i++) {
                for (int j = 1; j <= cols; j++) {
                    if (grid[i][j] == PATH && neighborDegrees[i][j] == 1) {
                        pathFoundInThisIteration = true;
                        if (!followPath(i, j)) {
                            return null;
                        }
                    } else if (grid[i][j] == PATH) {
                        allPathsResolved = false;
                    }
                }
            }

            searchingForMore = pathFoundInThisIteration;

            // If we couldn't find any degree-1 cells but some PATH cells still exist
            if (!allPathsResolved && !searchingForMore) {
                return null;
            }
        }

        // Final verification: Ensure no unassigned PATH cells remain
        for (int i = 1; i <= rows; i++) {
            for (int j = 1; j <= cols; j++) {
                if (grid[i][j] == PATH) return null;
            }
        }

        return formatOutput();
    }

    /**
     * Follows a path starting from a degree-1 cell and assigns direction symbols.
     */
    private boolean followPath(int startR, int startC) {
        int r = startR;
        int c = startC;

        while (grid[r][c] == PATH && neighborDegrees[r][c] == 1) {
            // Try directions based on the original logic: Up, Left, Down, Right
            if (grid[r - 1][c] == PATH) {
                grid[r][c] = DOWN;
                grid[r - 1][c] = UP;
                relax(r, c);
                r--;
                relax(r, c);
                // Heuristic move to next potential path node
                if (neighborDegrees[r - 1][c] == 1) r--;
                if (neighborDegrees[r][c - 1] == 1) c--;
                if (neighborDegrees[r][c + 1] == 1) c++;
            } else if (grid[r][c - 1] == PATH) {
                grid[r][c] = RIGHT;
                grid[r][c - 1] = LEFT;
                relax(r, c);
                c--;
                relax(r, c);
                if (neighborDegrees[r - 1][c] == 1) r--;
                if (neighborDegrees[r + 1][c] == 1) r++;
                if (neighborDegrees[r][c - 1] == 1) c--;
            } else if (grid[r + 1][c] == PATH) {
                grid[r][c] = UP;
                grid[r + 1][c] = DOWN;
                relax(r, c);
                r++;
                relax(r, c);
                if (neighborDegrees[r + 1][c] == 1) r++;
                if (neighborDegrees[r][c - 1] == 1) c--;
                if (neighborDegrees[r][c + 1] == 1) c++;
            } else if (grid[r][c + 1] == PATH) {
                grid[r][c] = LEFT;
                grid[r][c + 1] = RIGHT;
                relax(r, c);
                c++;
                relax(r, c);
                if (neighborDegrees[r - 1][c] == 1) r--;
                if (neighborDegrees[r + 1][c] == 1) r++;
                if (neighborDegrees[r][c + 1] == 1) c++;
            } else {
                return false;
            }
        }
        return true;
    }

    private void relax(int r, int c) {
        if (neighborDegrees[r - 1][c] > 0) neighborDegrees[r - 1][c]--;
        if (neighborDegrees[r + 1][c] > 0) neighborDegrees[r + 1][c]--;
        if (neighborDegrees[r][c - 1] > 0) neighborDegrees[r][c - 1]--;
        if (neighborDegrees[r][c + 1] > 0) neighborDegrees[r][c + 1]--;
    }

    private String formatOutput() {
        StringBuilder sb = new StringBuilder();
        for (int i = 1; i <= rows; i++) {
            for (int j = 1; j <= cols; j++) {
                if (grid[i][j] == WALL) {
                    sb.append('*');
                } else {
                    sb.append(getDirectionSymbol(grid[i][j]));
                }
            }
            sb.append('\n');
        }
        return sb.toString();
    }

    private char getDirectionSymbol(int type) {
        switch (type) {
            case UP:    return '^';
            case DOWN:  return 'v';
            case LEFT:  return '<';
            case RIGHT: return '>';
            default:    return ' ';
        }
    }
}

