/**
 * A program to solve a grid-based connection puzzle.
 * The algorithm iteratively connects empty cells ('.') that have exactly one 
 * available neighbor until the grid is filled or no more moves can be made.
 */
public class Main {

    public static void main(String[] args) {
        try {
            FastReader reader = new FastReader(System.in);

            int rows = reader.nextInt();
            int cols = reader.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.nextString().toCharArray();
            }

            GridPuzzleSolver solver = new GridPuzzleSolver(rows, cols, grid);
            solver.solve();

        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }
}

/**
 * Encapsulates the logic for solving the grid puzzle.
 */
class GridPuzzleSolver {
    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int[][] neighborCount;
    private final Queue<Point> queue;

    // Directional offsets for cardinal movement: Down, Up, Right, Left
    private static final int[] DX = {1, -1, 0, 0};
    private static final int[] DY = {0, 0, 1, -1};

    // Connection symbols: <, >, ^, v
    private static final char[] CONNECTORS = {'<', '>', '^', 'v'};

    public GridPuzzleSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.neighborCount = new int[rows][cols];
        this.queue = new ArrayDeque<>();
    }

    /**
     * Orchestrates the solving process.
     */
    public void solve() {
        initializeNeighborCounts();
        processConnections();
        printResult();
    }

    /**
     * Pre-calculates the number of adjacent empty cells for every empty cell.
     * Adds cells with exactly one neighbor to the processing queue.
     */
    private void initializeNeighborCounts() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    int count = 0;
                    for (int i = 0; i < 4; i++) {
                        int nr = r + DX[i];
                        int nc = c + DY[i];
                        if (isValidPosition(nr, nc) && grid[nr][nc] == '.') {
                            count++;
                        }
                    }
                    neighborCount[r][c] = count;
                    if (count == 1) {
                        queue.add(new Point(r, c));
                    }
                }
            }
        }
    }

    /**
     * Iteratively processes cells in the queue to establish connections.
     */
    private void processConnections() {
        while (!queue.isEmpty()) {
            Point current = queue.poll();
            int r = current.row();
            int c = current.col();

            // Skip if the cell is no longer empty or has no connections left
            if (grid[r][c] != '.' || neighborCount[r][c] < 1) {
                continue;
            }

            // Find the single available neighbor to connect to
            for (int i = 0; i < 4; i++) {
                int nr = r + DX[i];
                int nc = c + DY[i];

                if (isValidPosition(nr, nc) && grid[nr][nc] == '.') {
                    establishConnection(r, c, nr, nc);

                    // Update the neighbor's degree and queue it if it becomes a critical cell
                    for (int j = 0; j < 4; j++) {
                        int nnr = nr + DX[j];
                        int nnc = nc + DY[j];
                        if (isValidPosition(nnr, nnc) && grid[nnr][nnc] == '.') {
                            neighborCount[nnr][nnc]--;
                            if (neighborCount[nnr][nnc] == 1) {
                                queue.add(new Point(nnr, nnc));
                            }
                        }
                    }
                    break; // Connection established for current cell
                }
            }
        }
    }

    /**
     * Sets the connector characters for two adjacent cells.
     * Note: Logic follows the specific directional mapping provided in the original code.
     */
    private void establishConnection(int r, int c, int nr, int nc) {
        int dr = nr - r;
        int dc = nc - c;

        if (dr < 0) { // Up
            grid[r][c] = CONNECTORS[3]; // 'v'
            grid[nr][nc] = CONNECTORS[2]; // '^'
        } else if (dc < 0) { // Left
            grid[r][c] = CONNECTORS[1]; // '>'
            grid[nr][nc] = CONNECTORS[0]; // '<'
        } else if (dc > 0) { // Right
            grid[r][c] = CONNECTORS[0]; // '<'
            grid[nr][nc] = CONNECTORS[1]; // '>'
        } else { // Down (dr must be > 0)
            grid[r][c] = CONNECTORS[2]; // '^'
            grid[nr][nc] = CONNECTORS[3]; // 'v'
        }
    }

    private boolean isValidPosition(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Checks if any empty cells remain and prints the result.
     */
    private void printResult() {
        boolean unresolved = false;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    unresolved = true;
                    break;
                }
            }
            if (unresolved) break;
        }

        if (unresolved) {
            System.out.println("Not unique");
        } else {
            StringBuilder sb = new StringBuilder();
            for (int r = 0; r < rows; r++) {
                sb.setLength(0);
                for (int c = 0; c < cols; c++) {
                    sb.append(grid[r][c]);
                }
                System.out.println(sb.toString());
            }
        }
    }
}

