/**
 * Handles the logic for solving the maze matching problem.
 */
class MazeSolver {
    private final int rows;
    private final int cols;
    private final boolean[][] isPath;
    private final int[][] degree;
    private final boolean[][] processed;
    private final Point[][] pairedWith;

    public MazeSolver(int rows, int cols, String[] grid) {
        this.rows = rows;
        this.cols = cols;
        this.isPath = new boolean[rows][cols];
        this.degree = new int[rows][cols];
        this.processed = new boolean[rows][cols];
        this.pairedWith = new Point[rows][cols];

        initializeGrid(grid);
        calculateInitialDegrees();
    }

    private void initializeGrid(String[] grid) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i].charAt(j) == '.') {
                    isPath[i][j] = true;
                }
            }
        }
    }

    private void calculateInitialDegrees() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (isPath[i][j]) {
                    degree[i][j] = countAdjacentPaths(i, j);
                }
            }
        }
    }

    private int countAdjacentPaths(int r, int c) {
        int count = 0;
        if (isValid(r - 1, c) && isPath[r - 1][c]) count++;
        if (isValid(r + 1, c) && isPath[r + 1][c]) count++;
        if (isValid(r, c - 1) && isPath[r][c - 1]) count++;
        if (isValid(r, c + 1) && isPath[r][c + 1]) count++;
        return count;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Executes the solver algorithm and writes the result to the output.
     */
    public void solve(PrintWriter out) {
        Queue<Point> leafQueue = new ArrayDeque<>();

        // Find initial leaves (cells with only one neighbor)
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (isPath[i][j]) {
                    if (degree[i][j] == 0) {
                        out.println("Not unique");
                        return;
                    }
                    if (degree[i][j] == 1) {
                        leafQueue.add(new Point(i, j));
                    }
                }
            }
        }

        while (!leafQueue.isEmpty()) {
            Point current = leafQueue.poll();

            // Skip if this cell was already paired as a neighbor of another leaf
            if (processed[current.r][current.c]) {
                continue;
            }

            Point neighbor = findUnprocessedNeighbor(current.r, current.c);
            if (neighbor == null) {
                // If a leaf has no available neighbors, the solution is not unique/possible
                out.println("Not unique");
                return;
            }

            // Pair the leaf with its only available neighbor
            markAsPaired(current, neighbor);

            // Update the degrees of neighbors affected by this pairing
            updateNeighborDegrees(current.r, current.c, leafQueue);
            updateNeighborDegrees(neighbor.r, neighbor.c, leafQueue);
        }

        // Final check: ensure all path cells have been paired
        if (hasUnpairedPathCells()) {
            out.println("Not unique");
            return;
        }

        printResult(out);
    }

    private void markAsPaired(Point p1, Point p2) {
        processed[p1.r][p1.c] = true;
        processed[p2.r][p2.c] = true;
        pairedWith[p1.r][p1.c] = p2;
        pairedWith[p2.r][p2.c] = p1;
    }

    private Point findUnprocessedNeighbor(int r, int c) {
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};
        for (int i = 0; i < 4; i++) {
            int nr = r + dr[i];
            int nc = c + dc[i];
            if (isValid(nr, nc) && isPath[nr][nc] && !processed[nr][nc]) {
                return new Point(nr, nc);
            }
        }
        return null;
    }

    private void updateNeighborDegrees(int r, int c, Queue<Point> queue) {
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};
        for (int i = 0; i < 4; i++) {
            int nr = r + dr[i];
            int nc = c + dc[i];
            if (isValid(nr, nc) && isPath[nr][nc] && !processed[nr][nc]) {
                degree[nr][nc]--;
                if (degree[nr][nc] == 1) {
                    queue.add(new Point(nr, nc));
                }
            }
        }
    }

    private boolean hasUnpairedPathCells() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (isPath[i][j] && !processed[i][j]) {
                    return true;
                }
            }
        }
        return false;
    }

    private void printResult(PrintWriter out) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (!isPath[i][j]) {
                    out.print('*');
                } else {
                    Point target = pairedWith[i][j];
                    out.print(calculateDirectionChar(i, j, target.r, target.c));
                }
            }
            out.println();
        }
    }

    /**
     * Calculates the arrow character based on the original program's logic.
     * Note: The original logic defines directionality inversely to the target position.
     */
    private char calculateDirectionChar(int r, int c, int targetR, int targetC) {
        if (targetR == r) {
            // If neighbor is on the same row, print '>' if neighbor is left, '<' if neighbor is right
            return (targetC < c) ? '>' : '<';
        } else {
            // If neighbor is on a different row, print 'v' if neighbor is above, '^' if neighbor is below
            return (targetR < r) ? 'v' : '^';
        }
    }
}

