/**
 * Represents a coordinate in the 2D grid.
 */
class Point {
    final int r, c;

    Point(int r, int c) {
        this.r = r;
        this.c = c;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof Point)) return false;
        Point point = (Point) o;
        return r == point.r && c == point.c;
    }

    @Override
    public int hashCode() {
        return Objects.hash(r, c);
    }
}

/**
 * Encapsulates direction logic for movement in the grid.
 */
enum Direction {
    DOWN(1, 0), UP(-1, 0), RIGHT(0, 1), LEFT(0, -1);

    final int dr, dc;

    Direction(int dr, int dc) {
        this.dr = dr;
        this.dc = dc;
    }
}

/**
 * Manages the grid state, bounds checking, and neighbor queries.
 */
class Grid {
    private final int rows;
    private final int cols;
    private final char[][] cells;

    public Grid(int rows, int cols, char[][] initialCells) {
        this.rows = rows;
        this.cols = cols;
        this.cells = initialCells;
    }

    public int getRows() { return rows; }
    public int getCols() { return cols; }

    public char get(int r, int c) {
        return cells[r][c];
    }

    public void set(int r, int c, char value) {
        cells[r][c] = value;
    }

    public boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    public boolean isDot(int r, int c) {
        return isWithinBounds(r, c) && cells[r][c] == '.';
    }

    public boolean isArrow(int r, int c) {
        char cell = get(r, c);
        return cell == '<' || cell == '>' || cell == '^' || cell == 'v';
    }

    /**
     * Counts how many neighbors of a '.' cell are NOT '.' cells.
     */
    public int countNonDotNeighbors(int r, int c) {
        if (!isDot(r, c)) return 0;

        int count = 0;
        for (Direction dir : Direction.values()) {
            int nr = r + dir.dr;
            int nc = c + dir.dc;
            if (!isWithinBounds(nr, nc) || !isDot(nr, nc)) {
                count++;
            }
        }
        return count;
    }

    public void print(PrintWriter out) {
        for (int i = 0; i < rows; i++) {
            out.println(new String(cells[i]));
        }
    }
}

/**
 * Contains the logic for solving the grid puzzle.
 */
class PuzzleSolver {
    private static final String NOT_UNIQUE = "Not unique";

    private final Grid grid;
    private final boolean[][] visited;
    private final Deque<Point> queue;

    public PuzzleSolver(int rows, int cols, char[][] initialCells) {
        this.grid = new Grid(rows, cols, initialCells);
        this.visited = new boolean[rows][cols];
        this.queue = new ArrayDeque<>();
    }

    public void solve(PrintWriter out) {
        // Initial Scan
        for (int r = 0; r < grid.getRows(); r++) {
            for (int c = 0; c < grid.getCols(); c++) {
                int nonDotCount = grid.countNonDotNeighbors(r, c);
                if (nonDotCount == 4) {
                    out.println(NOT_UNIQUE);
                    return;
                }
                if (nonDotCount == 3) {
                    enqueue(r, c);
                }
            }
        }

        // Propagation
        while (!queue.isEmpty()) {
            Point current = queue.poll();
            int r = current.r;
            int c = current.c;

            // If already processed by another propagation, skip
            if (grid.isArrow(r, c)) continue;

            // Find the unique '.' neighbor
            Point dotNeighbor = findOnlyDotNeighbor(r, c);
            if (dotNeighbor == null) {
                out.println(NOT_UNIQUE);
                return;
            }

            // Fill the current cell and its neighbor with opposing arrows
            fillOpposingArrows(r, c, dotNeighbor.r, dotNeighbor.c);

            // Check neighbors of the newly filled dot cell
            if (!updateNeighborsOf(dotNeighbor.r, dotNeighbor.c)) {
                out.println(NOT_UNIQUE);
                return;
            }
        }

        // Final validation: ensure no dots remain
        if (hasEmptyCells()) {
            out.println(NOT_UNIQUE);
        } else {
            grid.print(out);
        }
    }

    private Point findOnlyDotNeighbor(int r, int c) {
        Point found = null;
        for (Direction dir : Direction.values()) {
            int nr = r + dir.dr;
            int nc = c + dir.dc;
            if (grid.isDot(nr, nc)) {
                if (found != null) return null; // More than one dot neighbor found
                found = new Point(nr, nc);
            }
        }
        return found;
    }

    private void fillOpposingArrows(int r1, int c1, int r2, int c2) {
        if (r1 == r2) { // Horizontal movement
            int minC = Math.min(c1, c2);
            int maxC = Math.max(c1, c2);
            grid.set(r1, minC, '<');
            grid.set(r1, maxC, '>');
        } else { // Vertical movement
            int minR = Math.min(r1, r2);
            int maxR = Math.max(r1, r2);
            grid.set(minR, c1, '^');
            grid.set(maxR, c1, 'v');
        }
    }

    private boolean updateNeighborsOf(int r, int c) {
        for (Direction dir : Direction.values()) {
            int nr = r + dir.dr;
            int nc = c + dir.dc;
            if (grid.isWithinBounds(nr, nc)) {
                int nonDotCount = grid.countNonDotNeighbors(nr, nc);
                if (nonDotCount == 4) return false;
                if (nonDotCount == 3) enqueue(nr, nc);
            }
        }
        return true;
    }

    private void enqueue(int r, int c) {
        if (!visited[r][c]) {
            visited[r][c] = true;
            queue.add(new Point(r, c));
        }
    }

    private boolean hasEmptyCells() {
        for (int r = 0; r < grid.getRows(); r++) {
            for (int c = 0; c < grid.getCols(); c++) {
                if (grid.isDot(r, c)) return true;
            }
        }
        return false;
    }
}

/**
 * Utility class for fast input reading.
 */
class InputReader implements AutoCloseable {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    public InputReader(InputStream in) {
        this.reader = new BufferedReader(new InputStreamReader(in));
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }

    public String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
        return tokenizer.nextToken();
    }

    public char[][] readGrid(int rows, int cols) {
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = next().toCharArray();
        }
        return grid;
    }

    @Override
    public void close() throws IOException {
        reader.close();
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver for the grid tiling problem.
 * The goal is to place directed arrows on all '.' cells such that each arrow
 * points to a neighbor, creating a unique tiling.
 */
public class Main {

    public static void main(String[] args) {
        TilingSolver solver = new TilingSolver();
        solver.execute();
    }

    /**
     * Represents a coordinate in the 2D grid.
     */
    private static final class Point {
        final int col;
        final int row;

        Point(int col, int row) {
            this.col = col;
            this.row = row;
        }
    }

    /**
     * Defines movement directions and the arrow characters 
     * associated with the current cell and its neighbor.
     */
    private enum Direction {
        UP(0, -1, 'v', '^'),
        RIGHT(1, 0, '<', '>'),
        DOWN(0, 1, '^', 'v'),
        LEFT(-1, 0, '>', '<');

        final int dc; // Delta Column
        final int dr; // Delta Row
        final char currentArrow;
        final char neighborArrow;

        Direction(int dc, int dr, char currentArrow, char neighborArrow) {
            this.dc = dc;
            this.dr = dr;
            this.currentArrow = currentArrow;
            this.neighborArrow = neighborArrow;
        }

        static Direction[] getValues() {
            return values();
        }
    }

    /**
     * Core logic for the tiling algorithm.
     */
    private static class TilingSolver {
        private int rows;
        private int cols;
        private char[][] grid;

        public void execute() {
            FastReader reader = new FastReader(System.in);
            PrintWriter out = new PrintWriter(System.out);

            try {
                this.rows = reader.nextInt();
                this.cols = reader.nextInt();
                this.grid = new char[rows][cols];

                for (int i = 0; i < rows; i++) {
                    grid[i] = reader.next().toCharArray();
                }

                if (solveTiling()) {
                    printGrid(out);
                } else {
                    out.println("Not unique");
                }
            } catch (Exception e) {
                // Handle unexpected input errors
            } finally {
                out.flush();
                out.close();
            }
        }

        /**
         * Uses a topological-sort-style approach to fill the grid.
         * Cells with only one '.' neighbor are processed greedily.
         * 
         * @return true if all '.' cells were successfully tiled, false otherwise.
         */
        private boolean solveTiling() {
            int[][] degree = new int[rows][cols];
            Queue<Point> queue = new LinkedList<>();

            // Step 1: Calculate initial degrees (count of '.' neighbors)
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.') {
                        int neighborDots = countDotNeighbors(r, c);
                        degree[r][c] = neighborDots;
                        if (neighborDots == 1) {
                            queue.offer(new Point(c, r));
                        }
                    }
                }
            }

            // Step 2: Process cells with degree 1
            while (!queue.isEmpty()) {
                Point p = queue.poll();
                // If the cell was already filled by a neighbor's process, skip
                if (grid[p.row][p.col] != '.') continue;

                degree[p.row][p.col] = 0;

                // Find the only '.' neighbor
                for (Direction dir : Direction.getValues()) {
                    int nr = p.row + dir.dr;
                    int nc = p.col + dir.dc;

                    if (isValid(nr, nc) && grid[nr][nc] == '.') {
                        // Place arrows
                        grid[p.row][p.col] = dir.currentArrow;
                        grid[nr][nc] = dir.neighborArrow;

                        // Update degrees of neighbors of the newly filled neighbor cell
                        updateNeighborDegrees(nr, nc, degree, queue);
                        break; 
                    }
                }
            }

            // Step 3: Validate if any '.' remain
            return isGridFullyTiled();
        }

        private int countDotNeighbors(int r, int c) {
            int count = 0;
            for (Direction dir : Direction.getValues()) {
                int nr = r + dir.dr;
                int nc = c + dir.dc;
                if (isValid(nr, nc) && grid[nr][nc] == '.') {
                    count++;
                }
            }
            return count;
        }

        private void updateNeighborDegrees(int r, int c, int[][] degree, Queue<Point> queue) {
            for (Direction dir : Direction.getValues()) {
                int nr = r + dir.dr;
                int nc = c + dir.dc;
                if (isValid(nr, nc)) {
                    degree[nr][nc]--;
                    if (degree[nr][nc] == 1) {
                        queue.offer(new Point(nc, nr));
                    }
                }
            }
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        private boolean isGridFullyTiled() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.') return false;
                }
            }
            return true;
        }

        private void printGrid(PrintWriter out) {
            for (int i = 0; i < rows; i++) {
                out.println(new String(grid[i]));
            }
        }
    }

    /**
     * Optimized reader for high-performance input parsing.
     */
    private static class FastReader {
        private final BufferedInputStream bis;
        private final byte[] buffer = new byte[1024];
        private int curChar;
        private int numChars;

        public FastReader(InputStream is) {
            this.bis = new BufferedInputStream(is);
        }

        private int read() throws IOException {
            if (numChars == -1) throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                numChars = bis.read(buffer);
                if (numChars <= 0) return -1;
            }
            return buffer[curChar++];
        }

        public int nextInt() throws IOException {
            int c = read();
            while (isSpaceChar(c)) c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res = res * 10 + (c - '0');
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public String next() throws IOException {
            int c = read();
            while (isSpaceChar(c)) c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A refactored solution for the grid-based arrow placement puzzle.
 * The goal is to pair up all empty cells using arrows.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = reader.nextInt();
            int m = reader.nextInt();
            char[][] gridData = new char[n][m];
            for (int i = 0; i < n; i++) {
                gridData[i] = reader.next().toCharArray();
            }

            PuzzleSolver solver = new PuzzleSolver(n, m, gridData);
            SolverResult result = solver.solve();

            if (result.isUnique()) {
                result.printGrid(out);
            } else {
                out.println("Not unique");
            }
        } catch (Exception e) {
            // In a real application, we would use a logger.
            out.println("Not unique");
        } finally {
            out.close();
        }
    }

    /**
     * Represents a direction in the grid, its movement vectors, and its symbol.
     */
    enum Direction {
        RIGHT(0, 1, '>'),
        UP(-1, 0, '^'),
        LEFT(0, -1, '<'),
        DOWN(1, 0, 'v');

        final int dr;
        final int dc;
        final char symbol;

        Direction(int dr, int dc, char symbol) {
            this.dr = dr;
            this.dc = dc;
            this.symbol = symbol;
        }

        public Direction getOpposite() {
            switch (this) {
                case RIGHT: return LEFT;
                case LEFT: return RIGHT;
                case UP: return DOWN;
                case DOWN: return UP;
                default: throw new IllegalStateException("Invalid direction");
            }
        }
    }

    /**
     * Represents a coordinate on the grid.
     */
    record Cell(int r, int c) {}

    /**
     * Manages the grid state and boundary checks.
     */
    static class Grid {
        private final int rows;
        private final int cols;
        private final char[][] data;

        public Grid(int rows, int cols, char[][] data) {
            this.rows = rows;
            this.cols = cols;
            this.data = data;
        }

        public boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        public boolean isCellEmpty(int r, int c) {
            return data[r][c] == '.';
        }

        public void setCell(int r, int c, char symbol) {
            data[r][c] = symbol;
        }

        public int countEmptyNeighbors(int r, int c) {
            int count = 0;
            for (Direction dir : Direction.values()) {
                int nr = r + dir.dr;
                int nc = c + dir.dc;
                if (isValid(nr, nc) && isCellEmpty(nr, nc)) {
                    count++;
                }
            }
            return count;
        }

        public boolean hasEmptyCells() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (data[i][j] == '.') return true;
                }
            }
            return false;
        }

        public void print(PrintWriter out) {
            for (int i = 0; i < rows; i++) {
                out.println(new String(data[i]));
            }
        }
    }

    /**
     * Result object containing the outcome of the solver.
     */
    static class SolverResult {
        private final boolean unique;
        private final Grid grid;

        public SolverResult(boolean unique, Grid grid) {
            this.unique = unique;
            this.grid = grid;
        }

        public boolean isUnique() { return unique; }
        public void printGrid(PrintWriter out) { grid.print(out); }
    }

    /**
     * Core logic for solving the puzzle.
     */
    static class PuzzleSolver {
        private final Grid grid;
        private final Queue<Cell> queue = new LinkedList<>();

        public PuzzleSolver(int rows, int cols, char[][] data) {
            this.grid = new Grid(rows, cols, data);
        }

        public SolverResult solve() {
            // Initial scan: find cells that MUST be filled because they only have one neighbor
            for (int r = 0; r < grid.rows; r++) {
                for (int c = 0; c < grid.cols; c++) {
                    if (grid.isCellEmpty(r, c)) {
                        int neighbors = grid.countEmptyNeighbors(r, c);
                        if (neighbors == 0) return new SolverResult(false, grid);
                        if (neighbors == 1) {
                            queue.add(new Cell(r, c));
                        }
                    }
                }
            }

            // Process queue of forced moves
            while (!queue.isEmpty()) {
                Cell current = queue.poll();
                if (!grid.isCellEmpty(current.r, current.c)) continue;

                Direction foundDir = null;
                Cell neighbor = null;

                // Find the one neighbor this cell must pair with
                for (Direction dir : Direction.values()) {
                    int nr = current.r + dir.dr;
                    int nc = current.c + dir.dc;
                    if (grid.isValid(nr, nc) && grid.isCellEmpty(nr, nc)) {
                        foundDir = dir;
                        neighbor = new Cell(nr, nc);
                        break;
                    }
                }

                if (foundDir == null) return new SolverResult(false, grid);

                // Perform the pairing (filling current cell and its neighbor)
                fillCellAndPropagate(current.r, current.c, foundDir.getOpposite().symbol);
                fillCellAndPropagate(neighbor.r, neighbor.c, foundDir.symbol);
            }

            // Final check: if any empty cells remain, the solution wasn't unique/complete
            if (grid.hasEmptyCells()) {
                return new SolverResult(false, grid);
            }

            return new SolverResult(true, grid);
        }

        /**
         * Fills a cell and checks if neighbors now only have one empty neighbor left.
         */
        private void fillCellAndPropagate(int r, int c, char symbol) {
            grid.setCell(r, c, symbol);
            for (Direction dir : Direction.values()) {
                int nr = r + dir.dr;
                int nc = c + dir.dc;
                if (grid.isValid(nr, nc) && grid.isCellEmpty(nr, nc)) {
                    if (grid.countEmptyNeighbors(nr, nc) == 1) {
                        queue.add(new Cell(nr, nc));
                    }
                }
            }
        }
    }

    /**
     * Efficient input reader for large datasets.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

