/**
 * Represents the possible movement directions in the grid.
 */
enum Direction {
    UP(-1, 0, '^', 'v'),
    DOWN(1, 0, 'v', '^'),
    LEFT(0, -1, '<', '>'),
    RIGHT(0, 1, '>', '<');

    public final int dr;
    public final int dc;
    public final char symbol;
    public final char oppositeSymbol;

    Direction(int dr, int dc, char symbol, char oppositeSymbol) {
        this.dr = dr;
        this.dc = dc;
        this.symbol = symbol;
        this.oppositeSymbol = oppositeSymbol;
    }

    public static Direction fromOffsets(int dr, int dc) {
        for (Direction d : values()) {
            if (d.dr == dr && d.dc == dc) {
                return d;
            }
        }
        return null;
    }
}

/**
 * Represents a 2D coordinate in the grid.
 */
record Point(int r, int c) {}

class GridSolver {
    private final int rows;
    private final int cols;
    private final char[][] solution;
    private final int[][] degree;
    private final boolean[][] isCovered;
    private final boolean[][] isObstacle;

    public GridSolver(int rows, int cols, String[] gridLines) {
        this.rows = rows;
        this.cols = cols;
        this.solution = new char[rows][cols];
        this.degree = new int[rows][cols];
        this.isCovered = new boolean[rows][cols];
        this.isObstacle = new boolean[rows][cols];

        // Initialize grid state
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (gridLines[r].charAt(c) == '*') {
                    isObstacle[r][c] = true;
                    isCovered[r][c] = true; // Obstacles are considered "covered"
                }
            }
        }

        // Calculate initial degrees (number of adjacent non-obstacle cells)
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (!isObstacle[r][c]) {
                    degree[r][c] = countNeighbors(r, c);
                }
            }
        }
    }

    private int countNeighbors(int r, int c) {
        int count = 0;
        for (Direction d : Direction.values()) {
            int nr = r + d.dr;
            int nc = c + d.dc;
            if (isValid(nr, nc) && !isObstacle[nr][nc]) {
                count++;
            }
        }
        return count;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    public void solve() {
        PrintWriter out = new PrintWriter(System.out);
        Queue<Point> queue = new ArrayDeque<>();

        // Seed queue with cells that have exactly one neighbor
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (!isObstacle[r][c] && degree[r][c] == 1) {
                    queue.add(new Point(r, c));
                }
            }
        }

        while (!queue.isEmpty()) {
            Point curr = queue.poll();
            int r = curr.r();
            int c = curr.c();

            // If this cell is already paired or its degree changed, skip
            if (isCovered[r][c] || degree[r][c] != 1) {
                continue;
            }

            // Find the single available neighbor to pair with
            for (Direction dir : Direction.values()) {
                int nr = r + dir.dr;
                int nc = c + dir.dc;

                if (isValid(nr, nc) && !isObstacle[nr][nc] && !isCovered[nr][nc] && degree[nr][nc] > 0) {
                    // Perform pairing
                    solution[r][c] = dir.oppositeSymbol;
                    solution[nr][nc] = dir.symbol;
                    isCovered[r][c] = true;
                    isCovered[nr][nc] = true;

                    // Update the degree of all neighbors of the newly paired neighbor
                    for (Direction d2 : Direction.values()) {
                        int nnr = nr + d2.dr;
                        int nnc = nc + d2.dc;
                        if (isValid(nnr, nnc) && !isObstacle[nnr][nnc] && !isCovered[nnr][nnc]) {
                            degree[nnr][nnc]--;
                            if (degree[nnr][nnc] == 1) {
                                queue.add(new Point(nnr, nnc));
                            }
                        }
                    }
                    break;
                }
            }
        }

        printResult(out);
        out.flush();
    }

    private void printResult(PrintWriter out) {
        boolean allCovered = true;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (!isCovered[r][c]) {
                    allCovered = false;
                    break;
                }
            }
            if (!allCovered) break;
        }

        if (!allCovered) {
            out.println("Not unique");
        } else {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    // If it's an obstacle, we don't print an arrow, 
                    // but the problem implies non-obstacles are paired.
                    // The original code prints '*' for obstacles by default 
                    // if they aren't explicitly set.
                    if (isObstacle[r][c]) {
                        out.print('*');
                    } else {
                        out.print(solution[r][c]);
                    }
                }
                out.println();
            }
        }
    }
}

import java.util.*;

/**
 * Solves the arrow grid puzzle by pairing adjacent empty cells ('.') 
 * using a degree-based topological sort approach.
 */
public class ArrowGridSolver {

    /**
     * Represents the four possible movement directions in the grid.
     */
    private enum Direction {
        DOWN(1, 0, 'v', '^'),
        UP(-1, 0, '^', 'v'),
        RIGHT(0, 1, '>', '<'),
        LEFT(0, -1, '<', '>');

        final int dr; // Change in row
        final int dc; // Change in column
        final char symbol; // Arrow character pointing in this direction
        final char oppositeSymbol; // Arrow character pointing back

        Direction(int dr, int dc, char symbol, char oppositeSymbol) {
            this.dr = dr;
            this.dc = dc;
            this.symbol = symbol;
            this.oppositeSymbol = oppositeSymbol;
        }
    }

    /**
     * Represents a coordinate in the grid.
     */
    private static class Point {
        final int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Holds information about a neighbor found during the pairing process.
     */
    private static class NeighborInfo {
        final int r, c;
        final Direction dir;

        NeighborInfo(int r, int c, Direction dir) {
            this.r = r;
            this.c = c;
            this.dir = dir;
        }
    }

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int[][] degrees;

    public ArrowGridSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.degrees = new int[rows][cols];
    }

    /**
     * Executes the solver algorithm.
     */
    public void solve() {
        Deque<Point> queue = new ArrayDeque<>();
        initializeDegrees(queue);

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            // If the cell was already filled by a previous pairing, skip it
            if (grid[current.r][current.c] != '.') {
                continue;
            }

            NeighborInfo neighbor = findFirstAvailableNeighbor(current.r, current.c);
            if (neighbor != null) {
                // Pair current cell with its only available neighbor
                grid[current.r][current.c] = neighbor.dir.symbol;
                grid[neighbor.r][neighbor.c] = neighbor.dir.oppositeSymbol;

                // Since the neighbor is now filled, update the degrees of its neighbors
                updateNeighborsOfFilledCell(neighbor.r, neighbor.c, queue);
            }
        }

        printResult();
    }

    /**
     * Calculates initial degrees for all empty cells and adds those with degree 1 to the queue.
     */
    private void initializeDegrees(Deque<Point> queue) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    int count = 0;
                    for (Direction dir : Direction.values()) {
                        int nr = r + dir.dr;
                        int nc = c + dir.dc;
                        if (isValid(nr, nc) && grid[nr][nc] == '.') {
                            count++;
                        }
                    }
                    degrees[r][c] = count;
                    if (count == 1) {
                        queue.add(new Point(r, c));
                    }
                }
            }
        }
    }

    /**
     * Finds the first adjacent cell that is still empty.
     */
    private NeighborInfo findFirstAvailableNeighbor(int r, int c) {
        for (Direction dir : Direction.values()) {
            int nr = r + dir.dr;
            int nc = c + dir.dc;
            if (isValid(nr, nc) && grid[nr][nc] == '.') {
                return new NeighborInfo(nr, nc, dir);
            }
        }
        return null;
    }

    /**
     * Decrements the degree of cells adjacent to a cell that was just filled.
     */
    private void updateNeighborsOfFilledCell(int r, int c, Deque<Point> queue) {
        for (Direction dir : Direction.values()) {
            int nr = r + dir.dr;
            int nc = c + dir.dc;
            if (isValid(nr, nc) && grid[nr][nc] == '.') {
                degrees[nr][nc]--;
                if (degrees[nr][nc] == 1) {
                    queue.add(new Point(nr, nc));
                }
            }
        }
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private void printResult() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    System.out.println("Not unique");
                    return;
                }
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int r = 0; r < rows; r++) {
            sb.append(new String(grid[r])).append("\n");
        }
        System.out.print(sb.toString());
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        if (!sc.hasNextInt()) return;
        int n = sc.nextInt();
        int m = sc.nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String rowStr = sc.next();
            grid[i] = rowStr.toCharArray();
        }

        ArrowGridSolver solver = new ArrowGridSolver(n, m, grid);
        solver.solve();

        sc.close();
    }
}

