class GridPathSolver {
    private final int rows;
    private final int cols;
    private final StringBuilder[] grid;
    private final int[][] degrees;

    private static final int[] ROW_DIR = {0, 0, -1, 1};
    private static final int[] COL_DIR = {-1, 1, 0, 0};

    private static class Point {
        int r, c;
        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    public GridPathSolver(int rows, int cols, StringBuilder[] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.degrees = new int[rows][cols];
    }

    /**
     * Executes the core algorithm to fill the grid with arrows.
     */
    public void solve() {
        calculateInitialDegrees();
        processEndpoints();

        if (hasRemainingDots()) {
            System.out.println("Not unique");
        } else {
            printGrid();
        }
    }

    private void calculateInitialDegrees() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r].charAt(c) == '.') {
                    degrees[r][c] = countDotNeighbors(r, c);
                }
            }
        }
    }

    private int countDotNeighbors(int r, int c) {
        int count = 0;
        for (int i = 0; i < 4; i++) {
            int nr = r + ROW_DIR[i];
            int nc = c + COL_DIR[i];
            if (isWithinBounds(nr, nc) && grid[nr].charAt(nc) == '.') {
                count++;
            }
        }
        return count;
    }

    private void processEndpoints() {
        Queue<Point> queue = new LinkedList<>();

        // Add all cells that are endpoints (degree 1) or isolated (degree 0)
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r].charAt(c) == '.' && degrees[r][c] <= 1) {
                    queue.add(new Point(r, c));
                }
            }
        }

        while (!queue.isEmpty()) {
            Point curr = queue.poll();
            int r = curr.r;
            int c = curr.c;

            // Only process if it's still a dot
            if (grid[r].charAt(c) != '.') continue;

            // Find a neighbor that is either a dot or an existing arrow
            Point neighbor = findValidNeighbor(r, c);

            if (neighbor != null) {
                // Set current cell to point towards the neighbor
                grid[r].setCharAt(c, getArrowDirection(r, c, neighbor.r, neighbor.c));

                // If the neighbor is a dot, update its degree and check if it's now an endpoint
                if (grid[neighbor.r].charAt(neighbor.c) == '.') {
                    degrees[neighbor.r][neighbor.c]--;
                    if (degrees[neighbor.r][neighbor.c] <= 1) {
                        queue.add(neighbor);
                    }
                }
            } else {
                // If no dot/arrow neighbor found, this is an isolated dot or 
                // the path is being filled from both ends. 
                // Look for any neighbor that is already an arrow to point to.
                Point arrowNeighbor = findArrowNeighbor(r, c);
                if (arrowNeighbor != null) {
                    grid[r].setCharAt(c, getArrowDirection(r, c, arrowNeighbor.r, arrowNeighbor.c));
                }
            }
        }
    }

    private Point findValidNeighbor(int r, int c) {
        for (int i = 0; i < 4; i++) {
            int nr = r + ROW_DIR[i];
            int nc = c + COL_DIR[i];
            if (isWithinBounds(nr, nc)) {
                char ch = grid[nr].charAt(nc);
                if (ch == '.' || isArrow(ch)) {
                    return new Point(nr, nc);
                }
            }
        }
        return null;
    }

    private Point findArrowNeighbor(int r, int c) {
        for (int i = 0; i < 4; i++) {
            int nr = r + ROW_DIR[i];
            int nc = c + COL_DIR[i];
            if (isWithinBounds(nr, nc) && isArrow(grid[nr].charAt(nc))) {
                return new Point(nr, nc);
            }
        }
        return null;
    }

    private boolean isArrow(char ch) {
        return ch == '<' || ch == '>' || ch == '^' || ch == 'v';
    }

    private char getArrowDirection(int r, int c, int nr, int nc) {
        if (nr == r) {
            return nc > c ? '>' : '<';
        } else {
            return nr > r ? 'v' : '^';
        }
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private boolean hasRemainingDots() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r].charAt(c) == '.') return true;
            }
        }
        return false;
    }

    private void printGrid() {
        for (StringBuilder row : grid) {
            System.out.println(row.toString());
        }
    }
}

