/**
 * Encapsulates the logic for solving the arrow grid propagation puzzle.
 */
class ArrowGridSolver {
    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int[][] degrees;

    public ArrowGridSolver(int rows, int cols, char[][] initialTable) {
        this.rows = rows;
        this.cols = cols;
        this.grid = initialTable;
        this.degrees = new int[rows][cols];
    }

    /**
     * Solves the puzzle using a degree-based propagation algorithm.
     * @return true if the grid is fully and uniquely filled, false otherwise.
     */
    public boolean solve() {
        Queue<Point> queue = new ArrayDeque<>();

        // Step 1: Initialize degrees for all empty '.' cells
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    int degree = countEmptyNeighbors(r, c);
                    degrees[r][c] = degree;
                    if (degree == 1) {
                        queue.add(new Point(r, c));
                    }
                }
            }
        }

        // Step 2: Propagate constraints
        while (!queue.isEmpty()) {
            Point current = queue.poll();

            // If cell was already filled by another propagation, skip
            if (grid[current.r][current.c] != '.') continue;

            for (Direction dir : Direction.values()) {
                int nr = current.r + dir.dr;
                int nc = current.c + dir.dc;

                if (isCellEmpty(nr, nc)) {
                    // Fill current cell and its neighbor with opposing arrows
                    grid[current.r][current.c] = dir.selfChar;
                    grid[nr][nc] = dir.otherChar;

                    // Since neighbor (nr, nc) is no longer '.', update its neighbors' degrees
                    updateNeighborDegrees(nr, nc, queue);
                    break; 
                }
            }
        }

        // Step 3: Verify if the entire grid was filled
        return isGridFullyFilled();
    }

    private int countEmptyNeighbors(int r, int c) {
        int count = 0;
        for (Direction dir : Direction.values()) {
            if (isCellEmpty(r + dir.dr, c + dir.dc)) {
                count++;
            }
        }
        return count;
    }

    private void updateNeighborDegrees(int r, int c, Queue<Point> queue) {
        for (Direction dir : Direction.values()) {
            int nnr = r + dir.dr;
            int nnc = c + dir.dc;
            if (isCellEmpty(nnr, nnc)) {
                degrees[nnr][nnc]--;
                if (degrees[nnr][nnc] == 1) {
                    queue.add(new Point(nnr, nnc));
                }
            }
        }
    }

    private boolean isCellEmpty(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] == '.';
    }

    private boolean isGridFullyFilled() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') return false;
            }
        }
        return true;
    }

    public void printGrid(FastWriter out) {
        for (int r = 0; r < rows; r++) {
            out.println(new String(grid[r]));
        }
    }
}

/**
 * Represents the possible movement directions and associated arrow characters.
 */
enum Direction {
    // dr, dc, arrow at current, arrow at neighbor
    DOWN(1, 0, '^', 'v'),
    LEFT(0, -1, '>', '<'),
    UP(-1, 0, 'v', '^'),
    RIGHT(0, 1, '<', '>');

    final int dr, dc;
    final char selfChar;
    final char otherChar;

    Direction(int dr, int dc, char selfChar, char otherChar) {
