/**
 * High-performance input reader.
 */
class FastReader implements AutoCloseable {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    public FastReader(InputStream stream) {
        this.reader = new BufferedReader(new InputStreamReader(stream));
    }

    public String next() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreElements()) {
            String line = reader.readLine();
            if (line == null) return null;
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    public int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    public char[][] readTable(int rows, int cols) throws IOException {
        char[][] table = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = next();
            table[i] = line.toCharArray();
        }
        return table;
    }

    @Override
    public void close() throws IOException {
        reader.close();
    }
}

/**
 * High-performance output writer.
 */
class FastWriter implements AutoCloseable {
    private final PrintWriter writer;

    public FastWriter(OutputStream outputStream) {
        this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
    }

    public void println(String s) {
        writer.println(s);
    }

    @Override
    public void close() {
        writer.close();
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves a grid-based path problem by filling empty cells ('.') 
 * with directional arrows ('^', 'v', '<', '>').
 */
public class GridPathSolver {

    private static final char DOT = '.';
    private static final char UP = '^';
    private static final char DOWN = 'v';
    private static final char LEFT = '<';
    private static final char RIGHT = '>';

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        GridPathSolver solver = new GridPathSolver();
        solver.run(reader);
    }

    /**
     * Orchestrates the reading, solving, and printing of the grid.
     */
    public void run(FastReader reader) {
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        if (rows <= 0 || cols <= 0) {
            return;
        }

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = reader.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
            }
        }

        solve(grid, rows, cols);
        printResult(grid, rows, cols);
    }

    /**
     * Core algorithm: Uses a leaf-removal approach (similar to topological sort)
     * to assign arrows to cells with only one possible neighbor.
     */
    private void solve(char[][] grid, int rows, int cols) {
        Deque<Point> queue = new ArrayDeque<>();

        // Initial pass: Find all '.' cells that have exactly one '.' neighbor
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (countDotNeighbors(grid, i, j, rows, cols) == 1) {
                    queue.add(new Point(i, j));
                }
            }
        }

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            // Only process if the cell is still a dot
            if (grid[current.r][current.c] != DOT) {
                continue;
            }

            List<Point> dotNeighbors = getDotNeighbors(grid, current.r, current.c, rows, cols);

            // If the cell has exactly one dot-neighbor, it forms a pair
            if (dotNeighbors.size() == 1) {
                Point neighbor = dotNeighbors.get(0);
                assignArrows(grid, current, neighbor);

                // Adding the neighbor to the queue as its neighbor count has changed
                queue.addAll(getDotNeighbors(grid, neighbor.r, neighbor.c, rows, cols));
            }
        }
    }

    /**
     * Assigns arrows to two cells based on their relative position.
     * Note: Following original logic, arrows point AWAY from each other.
     */
    private void assignArrows(char[][] grid, Point p1, Point p2) {
        if (p1.r > p2.r) { // p1 is below p2
            grid[p1.r][p1.c] = DOWN;
            grid[p2.r][p2.c] = UP;
        } else if (p1.r < p2.r) { // p1 is above p2
            grid[p1.r][p1.c] = UP;
            grid[p2.r][p2.c] = DOWN;
        } else if (p1.c < p2.c) { // p1 is left of p2
            grid[p1.r][p1.c] = LEFT;
            grid[p2.r][p2.c] = RIGHT;
        } else if (p1.c > p2.c) { // p1 is right of p2
            grid[p1.r][p1.c] = RIGHT;
            grid[p2.r][p2.c] = LEFT;
        }
    }

    private int countDotNeighbors(char[][] grid, int r, int c, int rows, int cols) {
        if (grid[r][c] != DOT) return 0;
        int count = 0;
        if (r > 0 && grid[r - 1][c] == DOT) count++;
        if (r < rows - 1 && grid[r + 1][c] == DOT) count++;
        if (c > 0 && grid[r][c - 1] == DOT) count++;
        if (c < cols - 1 && grid[r][c + 1] == DOT) count++;
        return count;
    }

    private List<Point> getDotNeighbors(char[][] grid, int r, int c, int rows, int cols) {
        List<Point> neighbors = new ArrayList<>();
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int i = 0; i < 4; i++) {
            int nr = r + dr[i];
            int nc = c + dc[i];
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == DOT) {
                neighbors.add(new Point(nr, nc));
            }
        }
        return neighbors;
    }

    private void printResult(char[][] grid, int rows, int cols) {
        boolean hasRemainingDots = false;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == DOT) {
                    hasRemainingDots = true;
                    break;
                }
            }
            if (hasRemainingDots) break;
        }

        if (hasRemainingDots) {
            System.out.println("Not unique");
        } else {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    sb.append(grid[i][j]);
                }
                sb.append("\n");
            }
            System.out.print(sb.toString());
        }
    }

    /**
     * Represents a coordinate in the grid.
     */
    static class Point {
        final int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Point)) return false;
            Point point = (Point) o;
            return r == point.r && c == point.c;
        }

        @Override
        public int hashCode() {
            return Objects.hash(r, c);
        }

        @Override
        public String toString() {
            return r + " " + c;
        }
    }

    /**
     * Fast I/O wrapper for efficient reading.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A solver for a grid-based connection puzzle.
 * The goal is to fill empty cells ('.') with direction characters to form unique paths.
 */
public class Main {

    public static void main(String[] args) {
        try {
            FastReader reader = new FastReader(System.in);
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            char[][] grid = new char[rows][];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            GridSolver solver = new GridSolver(rows, cols, grid);
            solver.solve();
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        } catch (Exception e) {
            System.err.println("An error occurred during solving: " + e.getMessage());
        }
    }

    /**
     * Represents a coordinate in the grid.
     */
    record Cell(int r, int c) {}

    /**
     * Encapsulates direction-specific logic including coordinate offsets and characters.
     */
    enum Direction {
        LEFT(0, -1, '>', '<'),
        UP(-1, 0, 'v', '^'),
        RIGHT(0, 1, '<', '>'),
        DOWN(1, 0, '^', 'v');

        final int dr, dc;
        final char selfChar;     // Character to place in the current cell
        final char neighborChar; // Character to place in the neighbor cell

        Direction(int dr, int dc, char selfChar, char neighborChar) {
            this.dr = dr;
            this.dc = dc;
            this.selfChar = selfChar;
            this.neighborChar = neighborChar;
        }

        public static Direction fromMask(int mask) {
            for (Direction dir : Direction.values()) {
                // Identify which direction matches the bit set in the mask
                if (mask == (1 << dir.ordinal())) {
                    return dir;
                }
            }
            throw new IllegalStateException("Invalid mask: " + mask);
        }
    }

    static class GridSolver {
        private final int rows;
        private final int cols;
        private final char[][] resultGrid;
        private final int[][] degrees;
        private final Queue<Cell> queue;

        public GridSolver(int rows, int cols, char[][] originalGrid) {
            this.rows = rows;
            this.cols = cols;
            this.resultGrid = new char[rows][cols];
            this.degrees = new int[rows][cols];
            this.queue = new LinkedList<>();

            // Initialize result grid and degree counts
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    resultGrid[i][j] = originalGrid[i][j];
                }
            }

            calculateInitialDegrees(originalGrid);
        }

        private void calculateInitialDegrees(char[][] originalGrid) {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (originalGrid[i][j] != '.') continue;

                    int availableNeighbors = 0;
                    for (Direction dir : Direction.values()) {
                        int ni = i + dir.dr;
                        int nj = j + dir.dc;
                        if (isCellAvailable(ni, nj, originalGrid)) {
                            availableNeighbors++;
                        }
                    }
                    degrees[i][j] = availableNeighbors;
                    if (degrees[i][j] == 1) {
                        queue.add(new Cell(i, j));
                    }
                }
            }
        }

        private boolean isCellAvailable(int r, int c, char[][] grid) {
            return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] == '.';
        }

        /**
         * Checks if a cell is blocked (boundary or already filled in resultGrid).
         */
        private boolean isBlocked(int r, int c) {
            return r < 0 || r >= rows || c < 0 || c >= cols || resultGrid[r][c] != '.';
        }

        public void solve() {
            while (!queue.isEmpty()) {
                Cell current = queue.poll();
                int r = current.r();
                int c = current.c();

                if (degrees[r][c] == 0 || resultGrid[r][c] != '.') continue;

                // Determine which direction is available for this degree-1 cell
                int mask = 0;
                for (int i = 0; i < Direction.values().length; i++) {
                    Direction dir = Direction.values()[i];
                    int ni = r + dir.dr;
                    int nj = c + dir.dc;
                    if (!isBlocked(ni, nj)) {
                        mask |= (1 << i);
                    }
                }

                if (mask == 0) continue;

                Direction dir = Direction.fromMask(mask);
                int nr = r + dir.dr;
                int nc = c + dir.dc;

                // Fill the two connected cells
                resultGrid[r][c] = dir.selfChar;
                resultGrid[nr][nc] = dir.neighborChar;

                // Update degrees for the neighbor and its neighbors
                updateDegrees(nr, nc);
            }

            printResult();
        }

        private void updateDegrees(int r, int c) {
            // The neighbor cell's degree is decremented because it's now filled
            degrees[r][c]--;

            // For every neighbor of the neighbor, decrement their degree
            for (Direction dir : Direction.values()) {
                int ni = r + dir.dr;
                int nj = c + dir.dc;

                if (ni >= 0 && ni < rows && nj >= 0 && nj < cols) {
                    if (resultGrid[ni][nj] == '.') {
                        degrees[ni][nj]--;
                        if (degrees[ni][nj] == 1) {
                            queue.add(new Cell(ni, nj));
                        }
                    }
                }
            }
        }

        private void printResult() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (resultGrid[i][j] == '.') {
                        System.out.println("Not unique");
                        return;
                    }
                }
            }

            PrintWriter out = new PrintWriter(System.out);
            for (int i = 0; i < rows; i++) {
                out.println(new String(resultGrid[i]));
            }
            out.flush();
        }
    }

    /**
     * Fast I/O utility.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Represents the possible states of a cell in the puzzle.
 */
enum CellType {
    EMPTY('.'),
    OBSTACLE('*'),
    UP('^'),
    DOWN('v'),
    LEFT('<'),
    RIGHT('>');

    private final char symbol;

    CellType(char symbol) {
        this.symbol = symbol;
    }

    public char getSymbol() {
        return symbol;
    }

    public static CellType fromChar(char c) {
        for (CellType type : values()) {
            if (type.symbol == c) return type;
        }
        return EMPTY; // Default fallback
    }
}

/**
 * Represents the four cardinal directions and their movement vectors.
 */
enum Direction {
    UP(-1, 0, CellType.UP, CellType.DOWN),
    DOWN(1, 0, CellType.DOWN, CellType.UP),
    LEFT(0, -1, CellType.LEFT, CellType.RIGHT),
    RIGHT(0, 1, CellType.RIGHT, CellType.LEFT);

    final int dr;
    final int dc;
    final CellType self;
    final CellType opposite;

    Direction(int dr, int dc, CellType self, CellType opposite) {
        this.dr = dr;
        this.dc = dc;
        this.self = self;
        this.opposite = opposite;
    }
}

/**
 * Simple coordinate wrapper.
 */
class Point {
    final int r, c;

    Point(int r, int c) {
        this.r = r;
        this.c = c;
    }
}

/**
 * Manages the grid state and boundary checks.
 */
class Grid {
    private final int rows;
    private final int cols;
    private final CellType[][] cells;

    public Grid(int rows, int cols) {
        this.rows = rows;
        this.cols = cols;
        this.cells = new CellType[rows][cols];
    }

    public void setCell(int r, int c, CellType type) {
        cells[r][c] = type;
    }

    public CellType getCell(int r, int c) {
        return cells[r][c];
    }

    public int getRows() {
        return rows;
    }

    public int getCols() {
        return cols;
    }

    public boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Counts how many adjacent cells are currently EMPTY.
     */
    public int countEmptyNeighbors(int r, int c) {
        int count = 0;
        for (Direction d : Direction.values()) {
            int nr = r + d.dr;
            int nc = c + d.dc;
            if (isWithinBounds(nr, nc) && cells[nr][nc] == CellType.EMPTY) {
                count++;
            }
        }
        return count;
    }

    public boolean hasEmptyCells() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (cells[i][j] == CellType.EMPTY) return true;
            }
        }
        return false;
    }
}

/**
 * Contains the core logic for solving the arrow puzzle.
 */
class ArrowPuzzleSolver {
    private final Grid grid;
    private final Deque<Point> stack;

    public ArrowPuzzleSolver(Grid grid) {
        this.grid = grid;
        this.stack = new ArrayDeque<>();
    }

    public void solve() {
        // Initial scan to find cells with exactly one empty neighbor
        for (int i = 0; i < grid.getRows(); i++) {
            for (int j = 0; j < grid.getCols(); j++) {
                checkAndEnqueue(i, j);
            }
        }

        while (!stack.isEmpty()) {
            Point current = stack.pop();
            int r = current.r;
            int c = current.c;

            // If the cell was filled by another operation, skip
            if (grid.getCell(r, c) != CellType.EMPTY) continue;

            // Try to find the single empty neighbor to point to
            for (Direction d : Direction.values()) {
                int nr = r + d.dr;
                int nc = c + d.dc;

                if (grid.isWithinBounds(nr, nc) && grid.getCell(nr, nc) == CellType.EMPTY) {
                    // Set the neighbor to point towards the current cell
                    // and the current cell to point towards the neighbor
                    grid.setCell(nr, nc, d.self);
                    grid.setCell(r, c, d.opposite);

                    // Re-evaluate the 5x5 area around the changed cells
                    reEvaluateArea(r, c);
                    break; 
                }
            }
        }
    }

    private void checkAndEnqueue(int r, int c) {
        if (grid.isWithinBounds(r, c) && grid.getCell(r, c) == CellType.EMPTY) {
            if (grid.countEmptyNeighbors(r, c) == 1) {
                stack.push(new Point(r, c));
            }
        }
    }

    private void reEvaluateArea(int r, int c) {
        for (int dr = -2; dr <= 2; dr++) {
            for (int dc = -2; dc <= 2; dc++) {
                checkAndEnqueue(r + dr, c + dc);
            }
        }
    }

    public boolean isUniqueSolution() {
        return !grid.hasEmptyCells();
    }
}

/**
 * Entry point for the application.
 */
public class ArrowPuzzleApp {
    public static void main(String[] args) {
        try (BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(System.out)) {

            String line = in.readLine();
            if (line == null) return;
            StringTokenizer st = new StringTokenizer(line);
            int n = Integer.parseInt(st.nextToken());
            int m = Integer.parseInt(st.nextToken());

            Grid grid = new Grid(n, m);
            for (int i = 0; i < n; i++) {
                String rowStr = in.readLine();
                for (int j = 0; j < m; j++) {
                    char c = rowStr.charAt(j);
                    grid.setCell(i, j, c == '.' ? CellType.EMPTY : CellType.OBSTACLE);
                }
            }

            ArrowPuzzleSolver solver = new ArrowPuzzleSolver(grid);
            solver.solve();

            if (!solver.isUniqueSolution()) {
                out.println("Not unique");
            } else {
                printGrid(grid, out);
            }
            out.flush();

        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private static void printGrid(Grid grid, PrintWriter out) {
        for (int i = 0; i < grid.getRows(); i++) {
            for (int j = 0; j < grid.getCols(); j++) {
                out.print(grid.getCell(i, j).getSymbol());
            }
            out.println();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves the Drazil and Tiles problem by attempting to fill a grid with 2x1 dominoes.
 * If a unique tiling is not possible, it reports "Not unique".
 */
public class DrazilAndTiles {

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);

        int rows = sc.nextInt();
        int cols = sc.nextInt();

        char[][] initialGrid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            initialGrid[i] = sc.next().toCharArray();
        }

        Board board = new Board(rows, cols, initialGrid);
        TilingSolver solver = new TilingSolver(board);

        solver.solve();

        if (board.hasEmptyCell()) {
            System.out.println("Not unique");
        } else {
            board.print();
        }
    }

    /**
     * Represents the grid and provides methods for safe manipulation.
     */
    static class Board {
        private final char[][] grid;
        private final int rows;
        private final int cols;

        public Board(int rows, int cols, char[][] initialGrid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = initialGrid;
        }

        public int getRows() { return rows; }
        public int getCols() { return cols; }

        public boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        public boolean isEmpty(int r, int c) {
            return isWithinBounds(r, c) && grid[r][c] == '.';
        }

        public void set(int r, int c, char val) {
            grid[r][c] = val;
        }

        public boolean hasEmptyCell() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.') return true;
                }
            }
            return false;
        }

        public void print() {
            StringBuilder sb = new StringBuilder();
            for (int r = 0; r < rows; r++) {
                sb.append(grid[r]).append('\n');
            }
            System.out.print(sb.toString());
        }
    }

    /**
     * Contains the logic for solving the tiling problem.
     */
    static class TilingSolver {
        // Directions: 0: Up, 1: Right, 2: Down, 3: Left
        private static final int[] DR = {-1, 0, 1, 0};
        private static final int[] DC = {0, 1, 0, -1};

        private final Board board;

        public TilingSolver(Board board) {
            this.board = board;
        }

        /**
         * Iterates through the grid to trigger tile expansion.
         */
        public void solve() {
            for (int r = 0; r < board.getRows(); r++) {
                for (int c = 0; c < board.getCols(); c++) {
                    if (board.isEmpty(r, c)) {
                        expand(r, c);
                    }
                }
            }
        }

        /**
         * Performs a BFS-based expansion to fill tiles based on forced placements.
         */
        private void expand(int r0, int c0) {
            int d0 = getForcedDirection(r0, c0);
            if (d0 == -1) return;

            Deque<State> queue = new ArrayDeque<>();
            queue.add(new State(r0, c0, d0));
            placeTile(r0, c0, d0);

            while (!queue.isEmpty()) {
                State current = queue.poll();

                // The current tile covers (r, c) and (r + DR[d], c + DC[d]).
                // We check the neighbors of the "other" cell of this tile.
                int otherR = current.r + DR[current.dir];
                int otherC = current.c + DC[current.dir];

                for (int i = 0; i < 4; i++) {
                    int nr = otherR + DR[i];
                    int nc = otherC + DC[i];

                    int nextDir = getForcedDirection(nr, nc);
                    if (nextDir != -1) {
                        placeTile(nr, nc, nextDir);
                        queue.add(new State(nr, nc, nextDir));
                    }
                }
            }
        }

        /**
         * Finds if a cell has exactly one empty neighbor, which forces a tile placement.
         * @return the direction index if exactly one neighbor is found, else -1.
         */
        private int getForcedDirection(int r, int c) {
            if (!board.isEmpty(r, c)) return -1;

            int foundDir = -1;
            int emptyNeighborCount = 0;

            for (int i = 0; i < 4; i++) {
                int nr = r + DR[i];
                int nc = c + DC[i];
                if (board.isEmpty(nr, nc)) {
                    emptyNeighborCount++;
                    foundDir = i;
                }
            }

            return (emptyNeighborCount == 1) ? foundDir : -1;
        }

        /**
         * Places the domino characters on the board based on the required direction.
         */
        private void placeTile(int r, int c, int dir) {
            switch (dir) {
                case 0 -> { // Up
                    board.set(r - 1, c, '^');
                    board.set(r, c, 'v');
                }
                case 1 -> { // Right
                    board.set(r, c, '<');
                    board.set(r, c + 1, '>');
                }
                case 2 -> { // Down
                    board.set(r, c, '^');
                    board.set(r + 1, c, 'v');
                }
                case 3 -> { // Left
                    board.set(r, c - 1, '<');
                    board.set(r, c, '>');
                }
            }
        }

        private static class State {
            final int r, c, dir;
            State(int r, int c, int dir) {
                this.r = r;
                this.c = c;
                this.dir = dir;
            }
        }
    }

    /**
     * Efficient input reader.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;

/**
 * Solver for filling a grid with arrows such that every empty cell ('.') 
 * is part of a connected path.
 */
public class ArrowGridSolver {

    /**
     * Represents a coordinate in the grid.
     */
    private record Cell(int row, int col) {}

    /**
     * Represents movement directions and the arrows associated with them.
     */
    private enum Direction {
        LEFT(0, -1, '>', '<'),
        RIGHT(0, 1, '<', '>'),
        UP(-1, 0, 'v', '^'),
        DOWN(1, 0, '^', 'v');

        final int dr, dc;
        final char selfChar;     // The arrow character for the current cell
        final char neighborChar; // The arrow character for the neighbor cell

        Direction(int dr, int dc, char selfChar, char neighborChar) {
            this.dr = dr;
            this.dc = dc;
            this.selfChar = selfChar;
            this.neighborChar = neighborChar;
        }
    }

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final boolean[][] visited;
    private final Queue<Cell> queue;

    public ArrowGridSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.visited = new boolean[rows][cols];
        this.queue = new ArrayDeque<>();
    }

    /**
     * Main orchestration logic for solving the grid.
     */
    public void solve() {
        // Step 1: Find initial dead ends (cells with exactly one '.' neighbor)
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                enqueueIfDeadEnd(r, c);
            }
        }

        // Step 2: Process the queue of dead ends
        while (!queue.isEmpty()) {
            Cell current = queue.poll();
            processDeadEnd(current.row(), current.col());
        }

        // Step 3: Output results
        printResult();
    }

    /**
     * Checks if a cell has exactly one '.' neighbor and adds it to the queue if so.
     */
    private void enqueueIfDeadEnd(int r, int c) {
        if (isInside(r, c) && grid[r][c] == '.' && !visited[r][c] && getDegree(r, c) == 1) {
            visited[r][c] = true;
            queue.add(new Cell(r, c));
        }
    }

    /**
     * Processes a dead end by placing arrows and checking its neighbor's neighbors.
     */
    private void processDeadEnd(int r, int c) {
        // If the cell was already filled by another process, skip it
        if (!isInside(r, c) || grid[r][c] != '.') return;

        // A dead end must have exactly one '.' neighbor to be processed
        if (getDegree(r, c) != 1) return;

        // Find the single neighbor
        for (Direction dir : Direction.values()) {
            int nr = r + dir.dr;
            int nc = c + dir.dc;

            if (isInside(nr, nc) && grid[nr][nc] == '.') {
                // Place arrows pointing away from each other to form the connection
                grid[r][c] = dir.selfChar;
                grid[nr][nc] = dir.neighborChar;

                // The neighbor's neighbors might now have become new dead ends
                for (Direction nextDir : Direction.values()) {
                    enqueueIfDeadEnd(nr + nextDir.dr, nc + nextDir.dc);
                }
                return;
            }
        }
    }

    /**
     * Calculates how many adjacent cells are currently '.'
     */
    private int getDegree(int r, int c) {
        if (!isInside(r, c) || grid[r][c] != '.') return 0;

        int degree = 0;
        for (Direction dir : Direction.values()) {
            int nr = r + dir.dr;
            int nc = c + dir.dc;
            if (isInside(nr, nc) && grid[nr][nc] == '.') {
                degree++;
            }
        }
        return degree;
    }

    private boolean isInside(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private void printResult() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    System.out.println("Not unique");
                    return;
                }
            }
        }

        for (int r = 0; r < rows; r++) {
            System.out.println(new String(grid[r]));
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) return;

        int n = scanner.nextInt();
        int m = scanner.nextInt();
        scanner.nextLine(); // Consume newline

        char[][] inputGrid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String line = scanner.nextLine();
            inputGrid[i] = line.toCharArray();
        }

        ArrowGridSolver solver = new ArrowGridSolver(n, m, inputGrid);
        solver.solve();

        scanner.close();
    }
}

import java.io.*;
import java.util.*;

/**
 * A solution to determine if a maze configuration is unique.
 * The algorithm propagates forced arrow placements based on cells 
 * having only one valid neighbor.
 */
public class Solution {

    public static void main(String[] args) {
        try {
            MazeSolver solver = new MazeSolver();
            solver.run();
        } catch (IOException e) {
            System.err.println("An error occurred while processing input: " + e.getMessage());
        }
    }

    /**
     * Encapsulates the logic for solving the maze.
     */
    private static class MazeSolver {
        private static final int[] ROW_OFFSETS = {-1, 1, 0, 0};
        private static final int[] COL_OFFSETS = {0, 0, -1, 1};

        private int rows;
        private int cols;
        private char[][] grid;

        /**
         * Entry point for the solver logic.
         */
        public void run() throws IOException {
            Locale.setDefault(Locale.ENGLISH);
            FastReader reader = new FastReader(System.in);
            PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

            // Initialize grid dimensions
            String firstLine = reader.next();
            if (firstLine == null) return;
            rows = Integer.parseInt(firstLine);
            cols = reader.nextInt();

            grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }

            processMaze(writer);
            writer.flush();
            writer.close();
        }

        private void processMaze(PrintWriter writer) {
            Queue<Point> queue = new LinkedList<>();
            boolean[][] visited = new boolean[rows][cols];

            // Step 1: Initial pass to identify forced movements
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    Point neighbor = tryFillIfUnique(r, c);
                    if (neighbor != null && !visited[neighbor.r][neighbor.c]) {
                        visited[neighbor.r][neighbor.c] = true;
                        queue.add(neighbor);
                    }
                }
            }

            // Step 2: BFS propagation of forced movements
            while (!queue.isEmpty()) {
                Point current = queue.poll();

                for (int i = 0; i < 4; i++) {
                    int nr = current.r + ROW_OFFSETS[i];
                    int nc = current.c + COL_OFFSETS[i];

                    Point neighbor = tryFillIfUnique(nr, nc);
                    if (neighbor != null && !visited[neighbor.r][neighbor.c]) {
                        visited[neighbor.r][neighbor.c] = true;
                        queue.add(neighbor);
                    }
                }
            }

            // Step 3: Output results
            if (hasUnfilledCells()) {
                writer.println("Not unique");
            } else {
                printGrid(writer);
            }
        }

        /**
         * Attempts to fill a cell with an arrow if it has exactly one '.' neighbor.
         * 
         * @return The unique neighbor's position if filling occurred, otherwise null.
         */
        private Point tryFillIfUnique(int r, int c) {
            if (!isInside(r, c) || grid[r][c] != '.') {
                return null;
            }

            Point uniqueNeighbor = findUniqueDotNeighbor(r, c);
            if (uniqueNeighbor != null) {
                applyArrows(r, c, uniqueNeighbor);
                return uniqueNeighbor;
            }

            return null;
        }

        private Point findUniqueDotNeighbor(int r, int c) {
            Point found = null;
            for (int i = 0; i < 4; i++) {
                int nr = r + ROW_OFFSETS[i];
                int nc = c + COL_OFFSETS[i];

                if (isInside(nr, nc) && grid[nr][nc] == '.') {
                    if (found != null) return null; // Multiple neighbors found
                    found = new Point(nr, nc);
                }
            }
            return found;
        }

        /**
         * Mutates the grid to set arrow directions based on relative position.
         */
        private void applyArrows(int r, int c, Point neighbor) {
            if (neighbor.r < r) { // Neighbor is above
                grid[neighbor.r][c] = '^';
                grid[r][c] = 'v';
            } else if (neighbor.r > r) { // Neighbor is below
                grid[r][c] = '^';
                grid[neighbor.r][c] = 'v';
            } else if (neighbor.c < c) { // Neighbor is left
                grid[r][neighbor.c] = '<';
                grid[r][c] = '>';
            } else if (neighbor.c > c) { // Neighbor is right
                grid[r][c] = '<';
                grid[r][neighbor.c] = '>';
            }
        }

        private boolean isInside(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        private boolean hasUnfilledCells() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.') return true;
                }
            }
            return false;
        }

        private void printGrid(PrintWriter writer) {
            for (int r = 0; r < rows; r++) {
                writer.println(new String(grid[r]));
            }
        }
    }

    /**
     * Simple coordinate wrapper.
     */
    private static class Point {
        final int r, c;
        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * High-performance input reader.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A solver for the Domino Puzzle problem.
 * The goal is to fill a grid with dominoes represented by arrows pointing outwards.
 * If the tiling is not unique or impossible, it outputs "Not unique".
 */
public class DominoPuzzle {

    // Directional offsets for navigating the 2D grid
    private static final int[] ROW_OFFSETS = {-1, 1, 0, 0};
    private static final int[] COL_OFFSETS = {0, 0, -1, 1};

    private final int rows;
    private final int cols;
    private final char[][] grid;

    public DominoPuzzle(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
    }

    /**
     * Represents a coordinate in the grid.
     */
    private static class Point {
        final int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            if (!sc.hasNextInt()) return;

            int n = sc.nextInt();
            int m = sc.nextInt();
            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                grid[i] = sc.next().toCharArray();
            }

            DominoPuzzle solver = new DominoPuzzle(n, m, grid);
            solver.solve();
        } catch (Exception e) {
            // In a real-world scenario, use a logging framework
            System.err.println("An error occurred: " + e.getMessage());
        }
    }

    /**
     * Orchestrates the domino placement process.
     */
    public void solve() {
        Deque<Point> queue = new ArrayDeque<>();

        // Initial scan: find all empty cells that have exactly one empty neighbor
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && countEmptyNeighbors(r, c) == 1) {
                    queue.add(new Point(r, c));
                }
            }
        }

        while (!queue.isEmpty()) {
            Point p1 = queue.pollFirst();

            // If this cell was already filled by a previous domino, skip it
            if (grid[p1.r][p1.c] != '.') {
                continue;
            }

            // Find the only available neighbor to form a domino
            Point p2 = findOnlyEmptyNeighbor(p1.r, p1.c);

            // If no neighbor is available, the tiling is not unique/possible
            if (p2 == null) {
                System.out.println("Not unique");
                return;
            }

            // Place the domino and update the grid with outward-pointing arrows
            placeDomino(p1, p2);

            // After placing a domino, neighbors of both cells might now have only one empty neighbor
            enqueueNewlyConstrainedNeighbors(p1, p2, queue);
        }

        // Final validation: check if any empty cells remain
        if (hasEmptyCells()) {
            System.out.println("Not unique");
        } else {
            printGrid();
        }
    }

    private int countEmptyNeighbors(int r, int c) {
        int count = 0;
        for (int i = 0; i < 4; i++) {
            int nr = r + ROW_OFFSETS[i];
            int nc = c + COL_OFFSETS[i];
            if (isValid(nr, nc) && grid[nr][nc] == '.') {
                count++;
            }
        }
        return count;
    }

    private Point findOnlyEmptyNeighbor(int r, int c) {
        for (int i = 0; i < 4; i++) {
            int nr = r + ROW_OFFSETS[i];
            int nc = c + COL_OFFSETS[i];
            if (isValid(nr, nc) && grid[nr][nc] == '.') {
                return new Point(nr, nc);
            }
        }
        return null;
    }

    private void placeDomino(Point p1, Point p2) {
        if (p1.r == p2.r - 1) { // p1 is above p2
            grid[p1.r][p1.c] = '^';
            grid[p2.r][p2.c] = 'v';
        } else if (p1.r == p2.r + 1) { // p1 is below p2
            grid[p1.r][p1.c] = 'v';
            grid[p2.r][p2.c] = '^';
        } else if (p1.c == p2.c - 1) { // p1 is left of p2
            grid[p1.r][p1.c] = '<';
            grid[p2.r][p2.c] = '>';
        } else if (p1.c == p2.c + 1) { // p1 is right of p2
            grid[p1.r][p1.c] = '>';
            grid[p2.r][p2.c] = '<';
        }
    }

    private void enqueueNewlyConstrainedNeighbors(Point p1, Point p2, Deque<Point> queue) {
        Point[] targets = {p1, p2};
        for (Point p : targets) {
            for (int i = 0; i < 4; i++) {
                int nr = p.r + ROW_OFFSETS[i];
                int nc = p.c + COL_OFFSETS[i];
                if (isValid(nr, nc) && grid[nr][nc] == '.' && countEmptyNeighbors(nr, nc) == 1) {
                    queue.add(new Point(nr, nc));
                }
            }
        }
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private boolean hasEmptyCells() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') return true;
            }
        }
        return false;
    }

    private void printGrid() {
        StringBuilder sb = new StringBuilder();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                sb.append(grid[r][c]);
            }
            sb.append('\n');
        }
        System.out.print(sb.toString());
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to solve the grid matching problem where adjacent empty cells ('.')
 * must be paired with directional arrows pointing toward each other.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            String header = reader.nextLine();
            if (header == null || header.isEmpty()) {
                return;
            }

            StringTokenizer st = new StringTokenizer(header);
            int rows = Integer.parseInt(st.nextToken());
            int cols = Integer.parseInt(st.nextToken());

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            GridSolver solver = new GridSolver(rows, cols, grid);
            solver.solve(writer);

        } catch (Exception e) {
            // Silently handle or log error as per requirement
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Handles the logic for matching grid cells using a greedy leaf-removal algorithm.
     */
    static class GridSolver {
        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final int[] degrees;

        // Directional offsets: Down, Up, Right, Left
        private static final int[] DR = {1, -1, 0, 0};
        private static final int[] DC = {0, 0, 1, -1};

        // ARROW_TO[i] is the arrow on the current cell pointing towards the neighbor in direction i
        private static final char[] ARROW_TO = {'v', '^', '>', '<'};
        // ARROW_FROM[i] is the arrow on the neighbor cell pointing back to the current cell
        private static final char[] ARROW_FROM = {'^', 'v', '<', '>'};

        public GridSolver(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            this.degrees = new int[rows * cols];
        }

        public void solve(PrintWriter pw) {
            int totalDots = 0;
            int[] queue = new int[rows * cols];
            int head = 0;
            int tail = 0;

            // Step 1: Calculate initial degrees and identify potential starting nodes (leaves)
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.') {
                        totalDots++;
                        int deg = countNeighbors(r, c);
                        degrees[r * cols + c] = deg;
                        if (deg == 1) {
                            queue[tail++] = r * cols + c;
                        }
                    }
                }
            }

            boolean possible = true;
            int matchedDots = 0;

            // Step 2: Process nodes with degree 1 (leaves)
            while (head < tail) {
                int pos = queue[head++];
                int r = pos / cols;
                int c = pos % cols;

                // If cell is already part of a pair, skip
                if (grid[r][c] != '.') {
                    continue;
                }

                boolean matched = false;
                for (int i = 0; i < 4; i++) {
                    int nr = r + DR[i];
                    int nc = c + DC[i];

                    if (isValid(nr, nc) && grid[nr][nc] == '.') {
                        // Create the pair
                        grid[r][c] = ARROW_TO[i];
                        grid[nr][nc] = ARROW_FROM[i];
                        matchedDots += 2;
                        matched = true;

                        // Update neighbors of the matched neighbor
                        for (int j = 0; j < 4; j++) {
                            int nnr = nr + DR[j];
                            int nnc = nc + DC[j];
                            if (isValid(nnr, nnc) && grid[nnr][nnc] == '.') {
                                int nPos = nnr * cols + nnc;
                                degrees[nPos]--;
                                if (degrees[nPos] == 1) {
                                    queue[tail++] = nPos;
                                }
                            }
                        }
                        break;
                    }
                }

                if (!matched) {
                    possible = false;
                    break;
                }
            }

            // Step 3: Final validation
            if (!possible || matchedDots != totalDots) {
                pw.println("Not unique");
            } else {
                for (int i = 0; i < rows; i++) {
                    pw.println(new String(grid[i]));
                }
            }
        }

        private int countNeighbors(int r, int c) {
            int count = 0;
            for (int i = 0; i < 4; i++) {
                int nr = r + DR[i];
                int nc = c + DC[i];
                if (isValid(nr, nc) && grid[nr][nc] == '.') {
                    count++;
                }
            }
            return count;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * Efficient reader for fast I/O operations.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public String nextLine() {
            try {
                return reader.readLine();
            } catch (IOException e) {
                return null;
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.StringTokenizer;

/**
 * Refactored solution for the Drazil and Tiles problem.
 * This program solves the tiling problem using a greedy approach by processing
 * cells with exactly one available neighbor.
 */
public class DrazilAndTiles {

    /**
     * Represents a coordinate in the 2D grid.
     */
    private static class Coordinate {
        final int r, c;

        Coordinate(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    // Directional offsets for 4-way connectivity (Up, Down, Left, Right)
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int[][] degrees;

    public DrazilAndTiles(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.degrees = new int[rows][cols];
    }

    /**
     * Orchestrates the tiling process.
     * @return The tiled grid as a String, or null if no unique solution is possible.
     */
    public String solve() {
        Deque<Coordinate> queue = new ArrayDeque<>();

        // 1. Initialize degrees (count of '.' neighbors) and find initial forced moves
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    int count = 0;
                    for (int i = 0; i < 4; i++) {
                        int nr = r + DR[i];
                        int nc = c + DC[i];
                        if (isInBounds(nr, nc) && grid[nr][nc] == '.') {
                            count++;
                        }
                    }

                    // If a '.' has no neighbors, it's impossible to tile
                    if (count == 0) return null;

                    degrees[r][c] = count;
                    if (count == 1) {
                        queue.add(new Coordinate(r, c));
                    }
                }
            }
        }

        // 2. Process the queue of forced moves (cells with degree 1)
        while (!queue.isEmpty()) {
            Coordinate curr = queue.poll();
            int r = curr.r;
            int c = curr.c;

            // If this cell was already covered by a previously placed tile, skip it
            if (grid[r][c] != '.') {
                continue;
            }

            // If a cell that was supposed to have 1 neighbor now has 0, it's impossible
            if (degrees[r][c] < 1) {
                return null;
            }

            // Find the single available neighbor
            Coordinate neighbor = findAvailableNeighbor(r, c);
            if (neighbor == null) {
                return null;
            }

            // Place the tile
            grid[r][c] = getSymbol(r, c, neighbor.r, neighbor.c);
            grid[neighbor.r][neighbor.c] = getSymbol(neighbor.r, neighbor.c, r, c);

            // 3. Update degrees of neighbors for both cells involved in the tile
            updateDegrees(r, c, queue);
            updateDegrees(neighbor.r, neighbor.c, queue);
        }

        // 4. Final validation: ensure all '.' cells are covered
        if (!isTilingComplete()) {
            return null;
        }

        return buildResultString();
    }

    private boolean isInBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private Coordinate findAvailableNeighbor(int r, int c) {
        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];
            if (isInBounds(nr, nc) && grid[nr][nc] == '.') {
                return new Coordinate(nr, nc);
            }
        }
        return null;
    }

    private void updateDegrees(int r, int c, Deque<Coordinate> queue) {
        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];
            if (isInBounds(nr, nc) && grid[nr][nc] == '.') {
                degrees[nr][nc]--;
                // If degree becomes 1, it's a new forced move
                if (degrees[nr][nc] == 1) {
                    queue.add(new Coordinate(nr, nc));
                }
            }
        }
    }

    private char getSymbol(int r1, int c1, int r2, int c2) {
        if (r1 == r2) {
            return c1 < c2 ? '<' : '>';
        } else {
            return r1 < r2 ? '^' : 'v';
        }
    }

    private boolean isTilingComplete() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') return false;
            }
        }
        return true;
    }

    private String buildResultString() {
        StringBuilder sb = new StringBuilder();
        for (int r = 0; r < rows; r++) {
            sb.append(grid[r]);
            sb.append('\n');
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String line = br.readLine();
            if (line == null) return;

            StringTokenizer st = new StringTokenizer(line);
            int n = Integer.parseInt(st.nextToken());
