/**
 * Represents directions in the grid, providing associated movement offsets 
 * and the character symbols used in the solution.
 */
enum Direction {
    DOWN(1, 0, '^'),
    UP(-1, 0, 'v'),
    RIGHT(0, 1, '<'),
    LEFT(0, -1, '>');

    final int deltaRow;
    final int deltaCol;
    final char symbol;

    Direction(int deltaRow, int deltaCol, char symbol) {
        this.deltaRow = deltaRow;
        this.deltaCol = deltaCol;
        this.symbol = symbol;
    }

    /**
     * Returns the direction that is opposite to the current one.
     */
    public Direction getOpposite() {
        switch (this) {
            case DOWN: return UP;
            case UP: return DOWN;
            case RIGHT: return LEFT;
            case LEFT: return RIGHT;
            default: throw new IllegalStateException("Unexpected direction: " + this);
        }
    }
}

