/**
 * Contains the core logic for solving the grid constraint satisfaction problem.
 */
class GridSolver {
    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int[][] emptyNeighborCount;
    private final Deque<Point> queue = new ArrayDeque<>();

    public GridSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.emptyNeighborCount = new int[rows][cols];
    }

    /**
     * High-level method to run the solver.
     */
    public void solve(PrintWriter out) {
        initializeNeighborCounts();
        processForcedMoves();
        printResult(out);
    }

    /**
     * Calculates the initial number of adjacent empty ('.') cells for every 
     * non-blocked ('*') cell.
     */
    private void initializeNeighborCounts() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] != '*') {
                    int count = 0;
                    for (Direction dir : Direction.values()) {
                        int nr = r + dir.deltaRow;
                        int nc = c + dir.deltaCol;
                        if (isValid(nr, nc) && grid[nr][nc] == '.') {
                            count++;
                        }
                    }
                    emptyNeighborCount[r][c] = count;

                    // If a cell has exactly one neighbor, it is a "forced move"
                    if (count == 1) {
                        queue.add(new Point(r, c));
                    }
                }
            }
        }
    }

    /**
     * Iteratively processes cells from the queue that have only one possible pairing.
     */
    private void processForcedMoves() {
        while (!queue.isEmpty()) {
            Point p = queue.poll();
            int r = p.r;
            int c = p.c;

            // Only process if the cell is still empty (not yet paired)
            if (grid[r][c] == '.') {
                for (Direction dir : Direction.values()) {
                    int nr = r + dir.deltaRow;
                    int nc = c + dir.deltaCol;

                    if (isValid(nr, nc) && grid[nr][nc] == '.') {
                        // Perform the pairing
                        grid[r][c] = dir.symbol;
                        grid[nr][nc] = dir.getOpposite().symbol;

                        // Update the constraints for neighbors of the newly filled cells
                        decrementNeighborCounts(r, c);
                        decrementNeighborCounts(nr, nc);
                        break;
                    }
                }
            }
        }
    }

    /**
     * Decrements the count of available neighbors for all cells adjacent to (r, c).
     */
    private void decrementNeighborCounts(int r, int c) {
        for (Direction dir : Direction.values()) {
            int nr = r + dir.deltaRow;
            int nc = c + dir.deltaCol;

            if (isValid(nr, nc)) {
                emptyNeighborCount[nr][nc]--;
                // If a neighbor is now forced to pair, add it to the queue
                if (emptyNeighborCount[nr][nc] == 1) {
                    queue.add(new Point(nr, nc));
                }
            }
        }
    }

    /**
     * Checks if the grid is fully solved and prints the result.
     */
    private void printResult(PrintWriter out) {
        boolean isSolved = true;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    isSolved = false;
                    break;
                }
            }
            if (!isSolved) break;
        }

        if (!isSolved) {
            out.println("Not unique");
        } else {
            for (int r = 0; r < rows; r++) {
                out.println(new String(grid[r]));
            }
        }
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

