/**
 * Encapsulates the core logic of the grid matching algorithm.
 */
class GridSolver {
    private final char[][] grid;
    private final int rows;
    private final int cols;

    // Directions: Up, Down, Left, Right
    private static final int[] ROW_DELTA = {-1, 1, 0, 0};
    private static final int[] COL_DELTA = {0, 0, -1, 1};

    public GridSolver(char[][] grid, int rows, int cols) {
        this.grid = grid;
        this.rows = rows;
        this.cols = cols;
    }

    /**
     * Executes the pairing algorithm using a degree-reduction approach (similar to topological sort).
     */
    public void solve() {
        Queue<Coordinate> queue = new LinkedList<>();

        // Initial pass: find all empty cells that have exactly one empty neighbor
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (isCellEmpty(r, c) && countEmptyNeighbors(r, c) == 1) {
                    queue.add(new Coordinate(r, c));
                }
            }
        }

        while (!queue.isEmpty()) {
            Coordinate current = queue.poll();
            int r = current.row;
            int c = current.col;

            // If cell was already filled by a previous pairing, skip
            if (!isCellEmpty(r, c)) {
                continue;
            }

            // Check if it still meets the degree-1 requirement
            if (countEmptyNeighbors(r, c) == 1) {
                Coordinate neighbor = findOnlyEmptyNeighbor(r, c);
                if (neighbor != null) {
                    applyPairing(r, c, neighbor.row, neighbor.col);

                    // Since neighbor is no longer empty, its neighbors' degree might have changed
                    for (int i = 0; i < 4; i++) {
                        int nr = neighbor.row + ROW_DELTA[i];
                        int nc = neighbor.col + COL_DELTA[i];
                        if (isValid(nr, nc) && isCellEmpty(nr, nc)) {
                            queue.add(new Coordinate(nr, nc));
                        }
                    }
                }
            }
        }
    }

    /**
     * Checks if any empty cells remain in the grid.
     */
    public boolean hasRemainingEmptyCells() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (isCellEmpty(r, c)) return true;
            }
        }
        return false;
    }

    /**
     * Prints the resulting grid to the specified output.
     */
    public void printGrid(PrintWriter out) {
        for (int r = 0; r < rows; r++) {
            out.println(new String(grid[r]));
        }
    }

    private int countEmptyNeighbors(int r, int c) {
        int count = 0;
        for (int i = 0; i < 4; i++) {
            int nr = r + ROW_DELTA[i];
            int nc = c + COL_DELTA[i];
            if (isValid(nr, nc) && isCellEmpty(nr, nc)) {
                count++;
            }
        }
        return count;
    }

    private Coordinate findOnlyEmptyNeighbor(int r, int c) {
        for (int i = 0; i < 4; i++) {
            int nr = r + ROW_DELTA[i];
            int nc = c + COL_DELTA[i];
            if (isValid(nr, nc) && isCellEmpty(nr, nc)) {
                return new Coordinate(nr, nc);
            }
        }
        return null;
    }

    private void applyPairing(int r1, int c1, int r2, int c2) {
        // Replicating the original logic's directional assignment
        if (r1 < r2) {
            grid[r1][c1] = '^';
            grid[r2][c2] = 'v';
        } else if (r1 > r2) {
            grid[r1][c1] = 'v';
            grid[r2][c2] = '^';
        } else if (c1 < c2) {
            grid[r1][c1] = '<';
            grid[r2][c2] = '>';
        } else {
            grid[r1][c1] = '>';
            grid[r2][c2] = '<';
        }
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private boolean isCellEmpty(int r, int c) {
        return isValid(r, c) && grid[r][c] == '.';
    }
}

