/**
 * Solves the Drazil and Tiles problem by identifying unique tile placements.
 * The algorithm uses a degree-based approach to find "leaf" cells in the grid
 * and pairs them with their only available neighbor.
 */
public class DrazilAndTiles515D {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            TileSolver solver = new TileSolver(reader.nextInt(), reader.nextInt(), reader);
            solver.solve(writer);
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    static class TileSolver {
        private static final int[][] DIRECTIONS = {{0, -1}, {-1, 0}, {0, 1}, {1, 0}};
        // Pairs of arrow characters for the two cells being tiled together
        private static final char[][] ARROW_SYMBOLS = {
            {'>', '<'}, // Horizontal
            {'v', '^'}, // Vertical (using row index logic)
            {'<', '>'}, // Horizontal
            {'^', 'v'}  // Vertical
        };

        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final int[][] degree;
        private final FastReader reader;

        public TileSolver(int rows, int cols, FastReader reader) {
            this.rows = rows;
            this.cols = cols;
            this.reader = reader;
            this.grid = new char[rows][cols];
            this.degree = new int[rows][cols];
            initializeGrid();
        }

        private void initializeGrid() {
            for (int i = 0; i < rows; i++) {
                char[] rowData = reader.nextCharArray(cols);
                System.arraycopy(rowData, 0, grid[i], 0, cols);
            }
        }

        public void solve(PrintWriter out) {
            int emptyCellCount = 0;
            Deque<Point> processQueue = new ArrayDeque<>();

            calculateInitialDegrees(processQueue);
            emptyCellCount = countEmptyCells();

            // If no empty cells exist, it's technically tiled.
            // If the algorithm can't pair everything, it's "Not unique".
            int tiledCells = performTiling(processQueue);

            if (tiledCells != emptyCellCount) {
                out.println("Not unique");
            } else {
                printGrid(out);
            }
        }

        private int countEmptyCells() {
            int count = 0;
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.') count++;
                }
            }
            return count;
        }

        private void calculateInitialDegrees(Deque<Point> queue) {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] != '.') continue;

                    // Check neighbors to calculate degree (number of adjacent '.' cells)
                    for (int[] dir : DIRECTIONS) {
                        int nr = r + dir[0];
                        int nc = c + dir[1];
                        if (isValid(nr, nc) && grid[nr][nc] == '.') {
                            degree[r][c]++;
                        }
                    }

                    if (degree[r][c] == 1) {
                        queue.add(new Point(r, c));
                    }
                }
            }
        }

        private int performTiling(Deque<Point> queue) {
            int tiledCount = 0;

            while (!queue.isEmpty()) {
                Point curr = queue.poll();
                int r = curr.r;
                int c = curr.c;

                // If this cell was already tiled by a previous neighbor's operation
                if (grid[r][c] != '.') continue;

                // If degree is no longer 1, it's not a simple leaf
                if (degree[r][c] != 1) continue;

                // Find the only available neighbor
                boolean foundNeighbor = false;
                for (int i = 0; i < 4; i++) {
                    int nr = r + DIRECTIONS[i][0];
                    int nc = c + DIRECTIONS[i][1];

                    if (isValid(nr, nc) && grid[nr][nc] == '.') {
                        // Tile the two cells
                        grid[r][c] = ARROW_SYMBOLS[i][0];
                        grid[nr][nc] = ARROW_SYMBOLS[i][1];
                        tiledCount += 2;

                        // Update degrees of neighbors of the newly filled neighbor cell
                        updateNeighborsOfFilledCell(nr, nc, queue);
                        foundNeighbor = true;
                        break;
                    }
                }

                // If a leaf exists but has no '.' neighbor, the tiling is impossible/not unique
                if (!foundNeighbor) break;
            }
            return tiledCount;
        }

        private void updateNeighborsOfFilledCell(int r, int c, Deque<Point> queue) {
            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (isValid(nr, nc)) {
                    degree[nr][nc]--;
                    if (degree[nr][nc] == 1 && grid[nr][nc] == '.') {
                        queue.add(new Point(nr, nc));
                    }
                }
            }
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        private void printGrid(PrintWriter out) {
            for (int i = 0; i < rows; i++) {
                out.println(new String(grid[i]));
            }
        }

        private static class Point {
            int r, c;
            Point(int r, int c) { this.r = r; this.c = c; }
        }
    }

    /**
     * Optimized reader for fast I/O performance.
     */
    static class FastReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int curChar;
        private int numChars;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (numChars == -1) throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buffer);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) return -1;
            }
            return buffer[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res = res * 10 + (c - '0');
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public char[] nextCharArray(int n) {
            char[] ca = new char[n];
            int c = read();
            while (isSpaceChar(c)) c = read();
            for (int i = 0; i < n; i++) {
                ca[i] = (char) c;
                if (i < n - 1) c = read();
            }
            return ca;
        }

        private boolean isSpaceChar(int c) {
            return c == -1 || c == ' ' || c == '\n' || c == '\r' || c == '\t';
        }
    }
}

