/**
 * Solves the problem of filling a grid with arrows based on local connectivity rules.
 */
class ArrowGridSolver {
    private static final char EMPTY = '.';
    private static final char WALL = '*';
    private static final char UP = '^';
    private static final char DOWN = 'v';
    private static final char LEFT = '<';
    private static final char RIGHT = '>';

    private final int rows;
    private final int cols;
    private final char[][] grid;

    public ArrowGridSolver(int rows, int cols, String[] inputRows) {
        this.rows = rows;
        this.cols = cols;
        // Padding the grid with walls to prevent boundary checks
        this.grid = new char[rows + 2][cols + 2];
        initializeGrid(inputRows);
    }

    private void initializeGrid(String[] inputRows) {
        for (int i = 0; i < rows + 2; i++) {
            Arrays.fill(grid[i], WALL);
        }
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                grid[i + 1][j + 1] = inputRows[i].charAt(j);
            }
        }
    }

    /**
     * Executes the main simulation algorithm.
     */
    public void solve(PrintWriter out) {
        Queue<Point> queue = new LinkedList<>();

        // Step 1: Find all initial empty cells that have exactly one empty neighbor
        for (int r = 1; r <= rows; r++) {
            for (int c = 1; c <= cols; c++) {
                if (isCellEmpty(r, c) && countEmptyNeighbors(r, c) == 1) {
                    queue.add(new Point(r, c));
                }
            }
        }

        // Step 2: Process the queue using a BFS-like propagation
        while (!queue.isEmpty()) {
            Point current = queue.poll();

            if (!isCellEmpty(current.r, current.c)) {
                continue;
            }

            Point neighbor = findEmptyNeighbor(current);
            if (neighbor == null) {
                continue;
            }

            applyArrows(current, neighbor);

            // Adding neighbors of the filled neighbor to the queue to propagate changes
            addValidNeighborsToQueue(neighbor, queue);
        }

        // Step 3: Output the final grid or error message
        printResult(out);
    }

    private boolean isCellEmpty(int r, int c) {
        return grid[r][c] == EMPTY;
    }

    private int countEmptyNeighbors(int r, int c) {
        int count = 0;
        if (grid[r - 1][c] == EMPTY) count++;
        if (grid[r + 1][c] == EMPTY) count++;
        if (grid[r][c - 1] == EMPTY) count++;
        if (grid[r][c + 1] == EMPTY) count++;
        return count;
    }

    private Point findEmptyNeighbor(Point p) {
        if (grid[p.r - 1][p.c] == EMPTY) return new Point(p.r - 1, p.c);
        if (grid[p.r + 1][p.c] == EMPTY) return new Point(p.r + 1, p.c);
        if (grid[p.r][p.c - 1] == EMPTY) return new Point(p.r, p.c - 1);
        if (grid[p.r][p.c + 1] == EMPTY) return new Point(p.r, p.c + 1);
        return null;
    }

    private void applyArrows(Point p, Point neighbor) {
        int r = p.r;
        int c = p.c;
        int nr = neighbor.r;
        int nc = neighbor.c;

        // We match the original logic: placing arrows that point away from each other
        if (nr == r - 1) { // Neighbor is UP
            grid[nr][nc] = UP;
            grid[r][c] = DOWN;
        } else if (nr == r + 1) { // Neighbor is DOWN
            grid[r][c] = UP;
            grid[nr][nc] = DOWN;
        } else if (nc == c - 1) { // Neighbor is LEFT
            grid[nr][nc] = LEFT;
            grid[r][c] = RIGHT;
        } else if (nc == c + 1) { // Neighbor is RIGHT
            grid[r][c] = LEFT;
            grid[nr][nc] = RIGHT;
        }
    }

    private void addValidNeighborsToQueue(Point p, Queue<Point> queue) {
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};
        for (int i = 0; i < 4; i++) {
            int nr = p.r + dr[i];
            int nc = p.c + dc[i];
            // Bounds check (within actual user grid) and connectivity check
            if (nr >= 1 && nr <= rows && nc >= 1 && nc <= cols) {
                if (isCellEmpty(nr, nc) && countEmptyNeighbors(nr, nc) == 1) {
                    queue.add(new Point(nr, nc));
                }
            }
        }
    }

    private void printResult(PrintWriter out) {
        boolean allFilled = true;
        for (int r = 1; r <= rows; r++) {
            for (int c = 1; c <= cols; c++) {
                if (isCellEmpty(r, c)) {
                    allFilled = false;
                    break;
                }
            }
            if (!allFilled) break;
        }

        if (!allFilled) {
            out.println("Not unique");
        } else {
            StringBuilder sb = new StringBuilder();
            for (int r = 1; r <= rows; r++) {
                for (int c = 1; c <= cols; c++) {
                    sb.append(grid[r][c]);
                }
                sb.append('\n');
            }
            out.print(sb.toString());
        }
    }
}

/**
 * Utility class for fast input reading.
 */
class FastReader {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    public FastReader(InputStream stream) {
        reader = new BufferedReader(new InputStreamReader(stream));
    }

    public String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
        return tokenizer.nextToken();
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.LinkedList;
import java.util.Queue;
import java.util.StringTokenizer;

/**
 * Solves the Arrow Grid puzzle where every '.' cell must be paired with an 
 * adjacent '.' cell using arrows pointing away from each other.
 */
public class ArrowGridSolver {

    private static final String NOT_UNIQUE = "Not unique";

    /**
     * Represents possible directions and their associated movement 
     * and arrow character mappings.
     */
    enum Direction {
        DOWN(1, 0, '^', 'v'),
        UP(-1, 0, 'v', '^'),
        RIGHT(0, 1, '<', '>'),
        LEFT(0, -1, '>', '<');

        final int dr, dc;
        final char topChar, neighborChar;

        Direction(int dr, int dc, char topChar, char neighborChar) {
            this.dr = dr;
            this.dc = dc;
            this.topChar = topChar;
            this.neighborChar = neighborChar;
        }
    }

    /**
     * Represents a cell candidate in the processing queue.
     */
    private static class Cell {
        final int r, c;
        final Direction dir;

        Cell(int r, int c, Direction dir) {
            this.r = r;
            this.c = c;
            this.dir = dir;
        }
    }

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int[][] degrees;

    public ArrowGridSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.degrees = new int[rows][cols];
    }

    /**
     * Checks if a cell is within bounds and is currently an empty '.' cell.
     */
    private boolean isDot(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] == '.';
    }

    /**
     * Finds the direction to the first available adjacent '.' cell.
     */
    private Direction findDirectionToNeighbor(int r, int c) {
        for (Direction d : Direction.values()) {
            if (isDot(r + d.dr, c + d.dc)) {
                return d;
            }
        }
        return null;
    }

    /**
     * Executes the greedy degree-based algorithm to solve the grid.
     * @return The formatted grid as a string, or "Not unique" if no unique solution exists.
     */
    public String solve() {
        Queue<Cell> queue = new LinkedList<>();

        // Phase 1: Initialize degrees and identify starting points for the queue
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] != '.') {
                    degrees[r][c] = -1; // Mark as processed/not a dot
                    continue;
                }

                int count = 0;
                Direction firstDir = null;
                for (Direction d : Direction.values()) {
                    if (isDot(r + d.dr, c + d.dc)) {
                        count++;
                        if (firstDir == null) firstDir = d;
                    }
                }

                degrees[r][c] = count;
                if (count == 0) return NOT_UNIQUE;
                if (count == 1) {
                    queue.add(new Cell(r, c, firstDir));
                }
            }
        }

        // Phase 2: Process degree-1 cells
        while (!queue.isEmpty()) {
            Cell current = queue.poll();

            // If the cell was already filled by a previous pairing, skip it
            if (!isDot(current.r, current.c)) {
                continue;
            }

            Direction dir = current.dir;
            int nr = current.r + dir.dr;
            int nc = current.c + dir.dc;

            // If the neighbor is no longer a dot, the pairing is invalid or non-unique
            if (!isDot(nr, nc)) {
                continue;
            }

            // Place arrows
            grid[current.r][current.c] = dir.topChar;
            grid[nr][nc] = dir.neighborChar;
            degrees[current.r][current.c] = -1;
            degrees[nr][nc] = -1;

            // Update degrees of the neighbor's neighbors
            for (Direction d : Direction.values()) {
                int ur = nr + d.dr;
                int uc = nc + d.dc;

                if (isDot(ur, uc)) {
                    // If a neighbor already had degree 1, it means the solution isn't unique
                    if (degrees[ur][uc] == 1) {
                        return NOT_UNIQUE;
                    }

                    degrees[ur][uc]--;
                    if (degrees[ur][uc] == 1) {
                        queue.add(new Cell(ur, uc, findDirectionToNeighbor(ur, uc)));
                    }
                }
            }
        }

        // Phase 3: Final validation
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    return NOT_UNIQUE;
                }
            }
        }

        return formatGrid();
    }

    private String formatGrid() {
        StringBuilder sb = new StringBuilder();
        for (int r = 0; r < rows; r++) {
            sb.append(new String(grid[r])).append("\n");
        }
        return sb.toString().trim();
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null) return;

        StringTokenizer st = new StringTokenizer(line);
        int R = Integer.parseInt(st.nextToken());
        int C = Integer.parseInt(st.nextToken());

        char[][] grid = new char[R][C];
        for (int i = 0; i < R; i++) {
            grid[i] = br.readLine().toCharArray();
        }

        ArrowGridSolver solver = new ArrowGridSolver(R, C, grid);
        System.out.println(solver.solve());
    }
}

import java.util.*;

/**
 * MazePathSolver implements a "peeling" algorithm to fill empty cells ('.') 
 * in a grid with directional tiles. The algorithm identifies dead-ends 
 * (cells surrounded by walls on 3 sides) and iteratively fills them.
 */
public class MazePathSolver {

    // Directional offsets: Up, Down, Left, Right
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    // Directional tiles corresponding to the DR/DC offsets.
    // For direction index k: current cell gets TILES[k][0], neighbor gets TILES[k][1].
    private static final char[][] TILES = {
        {'v', '^'}, // Up
        {'^', 'v'}, // Down
        {'>', '<'}, // Left
        {'<', '>'}  // Right
    };

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int[][] wallCount;

    /**
     * Represents a coordinate in the grid.
     */
    private record Point(int r, int c) {}

    public MazePathSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.wallCount = new int[rows][cols];
    }

    /**
     * Executes the peeling algorithm to fill the maze.
     */
    public void solve() {
        Queue<Point> queue = new LinkedList<>();

        // Initial pass: count existing walls for each empty cell
        // and identify dead-ends (cells with exactly 3 walls).
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    initializeCell(r, c, queue);
                }
            }
        }

        // Process dead-ends from the queue
        while (!queue.isEmpty()) {
            Point current = queue.poll();

            // If the cell was already filled by a previous neighbor connection, skip it.
            if (grid[current.r()][current.c()] != '.') {
                continue;
            }

            // Find the single remaining empty neighbor to connect to.
            for (int i = 0; i < 4; i++) {
                int nr = current.r() + DR[i];
                int nc = current.c() + DC[i];

                if (isEmpty(nr, nc)) {
                    // Fill current cell and its neighbor with tiles.
                    grid[current.r()][current.c()] = TILES[i][0];
                    grid[nr][nc] = TILES[i][1];

                    // Since (nr, nc) is no longer empty, its neighbors 
                    // effectively gain a new "wall".
                    updateNeighboringWalls(nr, nc, queue);
                    break; 
                }
            }
        }
    }

    private void initializeCell(int r, int c, Queue<Point> queue) {
        int walls = 0;
        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];
            if (!isEmpty(nr, nc)) {
                walls++;
            }
        }
        wallCount[r][c] = walls;
        // A cell with 3 walls is a dead-end (has exactly 1 empty neighbor).
        if (walls == 3) {
            queue.add(new Point(r, c));
        }
    }

    private void updateNeighboringWalls(int r, int c, Queue<Point> queue) {
        // The cell (r, c) was just filled, so it acts as a wall for its neighbors.
        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];
            if (isEmpty(nr, nc)) {
                wallCount[nr][nc]++;
                // If a neighbor becomes a dead-end, add it to the queue.
                if (wallCount[nr][nc] == 3) {
                    queue.add(new Point(nr, nc));
                }
            }
        }
    }

    private boolean isEmpty(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] == '.';
    }

    /**
     * Checks if all empty cells have been successfully filled with tiles.
     */
    public boolean isFullyFilled() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Prints the resulting grid to the console.
     */
    public void printGrid() {
        for (char[] row : grid) {
            System.out.println(row);
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }

        int n = scanner.nextInt();
        int m = scanner.nextInt();
        char[][] maze = new char[n][m];

        for (int i = 0; i < n; i++) {
            String rowString = scanner.next();
            maze[i] = rowString.toCharArray();
        }

        MazePathSolver solver = new MazePathSolver(n, m, maze);
        solver.solve();

        if (solver.isFullyFilled()) {
            solver.printGrid();
        } else {
            System.out.println("Not unique");
        }

        scanner.close();
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver for the grid-based arrow placement problem.
 * The goal is to fill all empty cells ('.') with arrows such that 
 * every arrow points to a valid cell and every cell is covered.
 */
public class GridArrowSolver {

    private static final int[] DR = {-1, 1, 0, 0}; // Up, Down, Left, Right
    private static final int[] DC = {0, 0, -1, 1};
    private static final char[] MY_CHARS = {'^', 'v', '<', '>'};
    private static final char[] OPP_CHARS = {'v', '^', '>', '<'};

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int[][] degrees;
    private final boolean[][] inQueue;
    private final Deque<Cell> processingQueue;

    private static class Cell {
        int r, c;

        Cell(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    public GridArrowSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.degrees = new int[rows][cols];
        this.inQueue = new boolean[rows][cols];
        this.processingQueue = new ArrayDeque<>();
    }

    public void solve() {
        initializeDegrees();
        processQueue();
    }

    /**
     * Calculates the initial degree (number of '.' neighbors) for every cell.
     */
    private void initializeDegrees() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    int count = 0;
                    for (int i = 0; i < 4; i++) {
                        if (isValid(r + DR[i], c + DC[i]) && grid[r + DR[i]][c + DC[i]] == '.') {
                            count++;
                        }
                    }
                    degrees[r][c] = count;
                    if (count == 1) {
                        addToQueue(r, c);
                    }
                }
            }
        }
    }

    private void addToQueue(int r, int c) {
        if (!inQueue[r][c]) {
            processingQueue.add(new Cell(r, c));
            inQueue[r][c] = true;
        }
    }

    /**
     * Processes cells that have only one possible direction to point.
     */
    private void processQueue() {
        while (!processingQueue.isEmpty()) {
            Cell curr = processingQueue.poll();

            // If this cell was already filled by a neighbor's processing, skip it.
            if (grid[curr.r][curr.c] != '.') {
                continue;
            }

            Cell neighbor = findOnlyEmptyNeighbor(curr.r, curr.c);
            if (neighbor == null) {
                continue;
            }

            // Pair the current cell with its only neighbor
            fillPair(curr.r, curr.c, neighbor.r, neighbor.c);
        }
    }

    private void fillPair(int r1, int c1, int r2, int c2) {
        // Set current cell arrow
        grid[r1][c1] = getArrowPointingAt(r1, c1, r2, c2);
        markCellAsFilled(r1, c1);

        // Set neighbor cell arrow (pointing back)
        grid[r2][c2] = getArrowPointingAt(r2, c2, r1, c1);
        markCellAsFilled(r2, c2);
    }

    /**
     * Marks a cell as filled and updates the degrees of its neighbors.
     */
    private void markCellAsFilled(int r, int c) {
        // We use a temporary symbol to ensure we don't treat this cell as '.'
        // But since we already updated grid[r][c] to an arrow, we just need 
        // to notify neighbors.
        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];
            if (isValid(nr, nc) && grid[nr][nc] == '.') {
                degrees[nr][nc]--;
                if (degrees[nr][nc] == 1) {
                    addToQueue(nr, nc);
                }
            }
        }
    }

    private Cell findOnlyEmptyNeighbor(int r, int c) {
        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];
            if (isValid(nr, nc) && grid[nr][nc] == '.') {
                return new Cell(nr, nc);
            }
        }
        return null;
    }

    private char getArrowPointingAt(int r1, int c1, int r2, int c2) {
        if (r2 < r1) return '^';
        if (r2 > r1) return 'v';
        if (c2 < c1) return '<';
        return '>';
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    public boolean isFullyCovered() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') return false;
            }
        }
        return true;
    }

    public void printGrid(PrintWriter out) {
        if (isFullyCovered()) {
            for (int r = 0; r < rows; r++) {
                out.println(new String(grid[r]));
            }
        } else {
            out.println("Not unique");
        }
    }

    public static void main(String[] args) throws IOException {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = reader.nextInt();
        int m = reader.nextInt();
        char[][] grid = new char[n][m];

        for (int i = 0; i < n; i++) {
            grid[i] = reader.next().toCharArray();
        }

        GridArrowSolver solver = new GridArrowSolver(n, m, grid);
        solver.solve();
        solver.printGrid(out);
        out.flush();
        out.close();
    }

    /**
     * Fast I/O helper class.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * Solves a grid-based path puzzle where arrows must be placed to fill empty cells.
 * The algorithm identifies "forced" moves by finding cells with only one empty neighbor.
 */
public class SolveContest {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] gridData = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                gridData[i] = line.toCharArray();
            }

            Grid grid = new Grid(rows, cols, gridData);
            PathSolver solver = new PathSolver(grid);

            String result = solver.solve();
            out.println(result);

        } catch (Exception e) {
            // In a production environment, use a logger.
            // For competitive programming, printing to err is standard.
            System.err.println("Error during execution: " + e.getMessage());
        } finally {
            out.close();
        }
    }

    /**
     * Represents a coordinate in the grid.
     */
    static class Cell {
        final int row;
        final int col;

        Cell(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Encapsulates the grid state and bounds checking.
     */
    static class Grid {
        private final int rows;
        private final int cols;
        private final char[][] cells;

        static final char EMPTY = '.';

        Grid(int rows, int cols, char[][] cells) {
            this.rows = rows;
            this.cols = cols;
            this.cells = cells;
        }

        int getRows() { return rows; }
        int getCols() { return cols; }
        char getCell(int r, int c) { return cells[r][c]; }
        void setCell(int r, int c, char val) { cells[r][c] = val; }

        boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        boolean isCellEmpty(int r, int c) {
            return isValid(r, c) && cells[r][c] == EMPTY;
        }

        public String toString() {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    sb.append(cells[i][j]);
                }
                if (i < rows - 1) sb.append("\n");
            }
            return sb.toString();
        }
    }

    /**
     * Contains the core logic for solving the path puzzle.
     */
    static class PathSolver {
        private static final int[] DX = {1, -1, 0, 0}; // Down, Up, Right, Left
        private static final int[] DY = {0, 0, 1, -1};

        // Symbols representing the direction of the arrow
        private static final char[] START_SYMBOLS = {'^', 'v', '<', '>'};
        private static final char[] END_SYMBOLS = {'v', '^', '>', '<'};

        private final Grid grid;

        PathSolver(Grid grid) {
            this.grid = grid;
        }

        public String solve() {
            Queue<Cell> queue = new LinkedList<>();

            // Initialize queue with cells that have exactly one empty neighbor
            for (int i = 0; i < grid.getRows(); i++) {
                for (int j = 0; j < grid.getCols(); j++) {
                    if (countEmptyNeighbors(i, j) == 1) {
                        queue.add(new Cell(i, j));
                    }
                }
            }

            while (!queue.isEmpty()) {
                Cell current = queue.poll();

                // Skip if cell is no longer empty (already processed)
                if (!grid.isCellEmpty(current.row, current.col)) {
                    continue;
                }

                int emptyNeighborCount = 0;
                int directionIdx = -1;

                // Determine the single empty neighbor
                for (int i = 0; i < 4; i++) {
                    int nr = current.row + DX[i];
                    int nc = current.col + DY[i];
                    if (grid.isCellEmpty(nr, nc)) {
                        emptyNeighborCount++;
                        directionIdx = i;
                    }
                }

                // If there isn't exactly one empty neighbor, the path is not uniquely determined
                if (emptyNeighborCount != 1) {
                    return "Not unique";
                }

                // Place the start and end symbols
                int neighborRow = current.row + DX[directionIdx];
                int neighborCol = current.col + DY[directionIdx];

                grid.setCell(current.row, current.col, START_SYMBOLS[directionIdx]);
                grid.setCell(neighborRow, neighborCol, END_SYMBOLS[directionIdx]);

                // Re-check neighbors of the newly modified neighbor cell
                for (int i = 0; i < 4; i++) {
                    int nnr = neighborRow + DX[i];
                    int nnc = neighborCol + DY[i];
                    if (grid.isCellEmpty(nnr, nnc) && countEmptyNeighbors(nnr, nnc) == 1) {
                        queue.add(new Cell(nnr, nnc));
                    }
                }
            }

            // Final verification: if any empty cells remain, the solution is not unique
            if (hasEmptyCells()) {
                return "Not unique";
            }

            return grid.toString();
        }

        private int countEmptyNeighbors(int r, int c) {
            if (grid.getCell(r, c) != Grid.EMPTY) return 0;
            int count = 0;
            for (int i = 0; i < 4; i++) {
                if (grid.isCellEmpty(r + DX[i], c + DY[i])) {
                    count++;
                }
            }
            return count;
        }

        private boolean hasEmptyCells() {
            for (int i = 0; i < grid.getRows(); i++) {
                for (int j = 0; j < grid.getCols(); j++) {
                    if (grid.getCell(i, j) == Grid.EMPTY) return true;
                }
            }
            return false;
        }
    }

    /**
     * Utility for fast input reading.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

