/**
 * Represents a coordinate in the 2D grid.
 */
class Point {
    final int r, c;

    Point(int r, int c) {
        this.r = r;
        this.c = c;
    }
}

/**
 * Represents possible movements in the grid.
 */
enum Direction {
    UP(-1, 0), DOWN(1, 0), LEFT(0, -1), RIGHT(0, 1);

    final int dr, dc;

    Direction(int dr, int dc) {
        this.dr = dr;
        this.dc = dc;
    }
}

/**
 * Contains the logic for solving the grid pairing problem.
 */
class GridSolver {
    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final boolean[][] used;
    private final int[][] degree;

    public GridSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.used = new boolean[rows][cols];
        this.degree = new int[rows][cols];
    }

    /**
     * Executes the greedy leaf-removal algorithm to pair adjacent cells.
     */
    public void solve(PrintWriter out) {
        Queue<Point> queue = new ArrayDeque<>();
        int totalDots = 0;

        // 1. Initialize degrees and find initial degree-1 cells
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.') {
                    totalDots++;
                    int d = countUnusedNeighbors(i, j);
                    degree[i][j] = d;
                    if (d == 1) {
                        queue.add(new Point(i, j));
                    }
                }
            }
        }

        List<Point[]> matchings = new ArrayList<>();

        // 2. Process cells with degree 1
        while (!queue.isEmpty()) {
            Point current = queue.poll();

            if (used[current.r][current.c]) {
                continue;
            }

            // Find the unique available neighbor
            Point neighbor = findAvailableNeighbor(current.r, current.c);

            if (neighbor == null) {
                // Cell is isolated or all neighbors already used
                out.println("Not unique");
                return;
            }

            // Pair the current cell with its neighbor
            markAsUsed(current, neighbor, matchings);

            // Update degrees of neighbors of the newly used neighbor
            for (Direction dir : Direction.values()) {
                int nr = neighbor.r + dir.dr;
                int nc = neighbor.c + dir.dc;

                if (isValid(nr, nc) && grid[nr][nc] == '.' && !used[nr][nc]) {
                    degree[nr][nc]--;
                    if (degree[nr][nc] == 1) {
                        queue.add(new Point(nr, nc));
                    }
                }
            }
        }

        // 3. Validate that all '.' cells were matched
        if (matchings.size() * 2 != totalDots) {
            out.println("Not unique");
            return;
        }

        // 4. Apply direction symbols based on the pairings
        applyPairingSymbols(matchings);

        // 5. Output the resulting grid
        printGrid(out);
    }

    private int countUnusedNeighbors(int r, int c) {
        int count = 0;
        for (Direction dir : Direction.values()) {
            int nr = r + dir.dr;
            int nc = c + dir.dc;
            if (isValid(nr, nc) && grid[nr][nc] == '.') {
                count++;
            }
        }
        return count;
    }

    private Point findAvailableNeighbor(int r, int c) {
        for (Direction dir : Direction.values()) {
            int nr = r + dir.dr;
            int nc = c + dir.dc;
            if (isValid(nr, nc) && grid[nr][nc] == '.' && !used[nr][nc]) {
                return new Point(nr, nc);
            }
        }
        return null;
    }

    private void markAsUsed(Point p1, Point p2, List<Point[]> matchings) {
        used[p1.r][p1.c] = true;
        used[p2.r][p2.c] = true;
        matchings.add(new Point[]{p1, p2});
    }

    private void applyPairingSymbols(List<Point[]> matchings) {
        for (Point[] pair : matchings) {
            Point a = pair[0];
            Point b = pair[1];

            if (a.r == b.r) { // Horizontal pairing
                if (a.c < b.c) {
                    grid[a.r][a.c] = '<';
                    grid[b.r][b.c] = '>';
                } else {
                    grid[a.r][a.c] = '>';
                    grid[b.r][b.c] = '<';
                }
            } else { // Vertical pairing
                if (a.r < b.r) {
                    grid[a.r][a.c] = '^';
                    grid[b.r][b.c] = 'v';
                } else {
                    grid[a.r][a.c] = 'v';
                    grid[b.r][b.c] = '^';
                }
            }
        }
    }

    private void printGrid(PrintWriter out) {
        for (int i = 0; i < rows; i++) {
            out.println(new String(grid[i]));
        }
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

/**
 * Fast I/O utility class.
 */
class FastReader {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    public FastReader(InputStream input) {
        reader = new BufferedReader(new InputStreamReader(input));
    }

    public String next() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreElements()) {
            String line = reader.readLine();
            if (line == null) return null;
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    public int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    public char[][] readGrid(int rows, int cols) throws IOException {
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = reader.readLine();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
            }
        }
        return grid;
    }
}

