 */
record Point(int r, int c) {}

/**
 * Encapsulates direction-based logic, including movement offsets 
 * and the characters used to represent arrows.
 */
enum Direction {
    RIGHT(0, 1, '<', '>'),
    LEFT(0, -1, '>', '<'),
    UP(-1, 0, 'v', '^'),
    DOWN(1, 0, '^', 'v');

    final int dr;
    final int dc;
    final char charAtCurrent;
    final char charAtNeighbor;

    Direction(int dr, int dc, char charAtCurrent, char charAtNeighbor) {
        this.dr = dr;
        this.dc = dc;
        this.charAtCurrent = charAtCurrent;
        this.charAtNeighbor = charAtNeighbor;
    }

    public static Direction getDirectionFromNeighbor(int dr, int dc) {
