/**
 * Solves the grid orientation problem using a degree-based topological approach.
 */
class GridOrientationSolver {

    private int rows;
    private int cols;
    private char[][] grid;
    private int[][] neighborDegrees;
    private final Queue<Point> processingQueue = new ArrayDeque<>();

    /**
     * Executes the solving algorithm.
     * 
     * @param in  The input scanner.
     * @param out The output writer.
     */
    public void solve(Scanner in, PrintWriter out) {
        if (!in.hasNextInt()) return;

        rows = in.nextInt();
        cols = in.nextInt();
        grid = new char[rows][cols];
        neighborDegrees = new int[rows][cols];

        initializeGrid(in);
        processLeaves();

        if (isSuccessful()) {
            printGrid(out);
        } else {
            out.print("Not unique");
        }
    }

    private void initializeGrid(Scanner in) {
        for (int i = 0; i < rows; i++) {
            grid[i] = in.next().toCharArray();
        }

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    calculateInitialDegree(r, c);
                }
            }
        }
    }

    private void calculateInitialDegree(int r, int c) {
        int count = 0;
        for (Direction dir : Direction.values()) {
            if (isAvailable(r + dir.dr, c + dir.dc)) {
                count++;
            }
        }
        neighborDegrees[r][c] = count;
        if (count == 1) {
            processingQueue.add(new Point(r, c));
        }
    }

    private void processLeaves() {
        while (!processingQueue.isEmpty()) {
            Point p = processingQueue.poll();

            // If degree is 0, it means this cell cannot be uniquely oriented.
            if (neighborDegrees[p.r()][p.c()] == 0) {
                return; 
            }

            for (Direction dir : Direction.values()) {
                int nr = p.r() + dir.dr;
                int nc = p.c() + dir.dc;

                if (isAvailable(nr, nc)) {
                    // Orient the current cell and its neighbor
                    grid[p.r()][p.c()] = dir.charAtCurrent;
                    grid[nr][nc] = dir.charAtNeighbor;

                    // The neighbor is no longer a '.' so it's effectively "removed"
                    // We update the neighbors of the neighbor.
                    updateNeighborsOfNeighbor(nr, nc);
                    break;
                }
            }
        }
    }

    private void updateNeighborsOfNeighbor(int r, int c) {
        // The neighbor (nr, nc) is no longer a '.'
        // We must reduce the degree of all its adjacent '.' neighbors.
        for (Direction dir : Direction.values()) {
            int nr = r + dir.dr;
            int nc = c + dir.dc;
            if (isAvailable(nr, nc)) {
                neighborDegrees[nr][nc]--;
                if (neighborDegrees[nr][nc] == 1) {
                    processingQueue.add(new Point(nr, nc));
                }
            }
        }
    }

    private boolean isAvailable(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] == '.';
    }

    private boolean isSuccessful() {
        // Check if any cells remain unoriented
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') return false;
            }
        }
        // Ensure no leaf-removal failed due to degree 0
        return !processingQueue.isEmpty() || hasNoUnorientedCells();
    }

    private boolean hasNoUnorientedCells() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') return false;
            }
        }
        return true;
    }

    private void printGrid(PrintWriter out) {
        for (int r = 0; r < rows; r++) {
            out.println(new String(grid[r]));
        }
    }
}

import java.util.*;

/**
 * A solver for the Arrow Puzzle, which determines a unique configuration of 
 * directional arrows on a grid such that every empty cell is filled.
 */
public class ArrowPuzzleSolver {

    private static final int[] ROW_OFFSETS = {0, 0, 1, -1};
    private static final int[] COL_OFFSETS = {1, -1, 0, 0};

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final Queue<Connection> connectionQueue = new ArrayDeque<>();

    /**
     * Represents a coordinate on the grid.
     */
    private record Point(int r, int c) {}

    /**
     * Represents a pairing of two cells that should be processed together.
     */
    private record Connection(Point p1, Point p2) {}

    public ArrowPuzzleSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
    }

    /**
     * Executes the solving algorithm.
     */
    public void solve() {
        // Initial pass: Find all cells that have exactly one empty neighbor.
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] != '*') {
                    identifyPotentialConnections(r, c);
                }
            }
        }

        // Main processing loop.
        while (!connectionQueue.isEmpty()) {
            Connection connection = connectionQueue.poll();
            Point p1 = connection.p1();
            Point p2 = connection.p2();

            // Only process if both cells involved are still empty.
            if (isCellEmpty(p1) && isCellEmpty(p2)) {
                applyArrows(p1, p2);

                // After placing arrows, the neighbors of these cells might now 
                // satisfy the "one empty neighbor" condition.
                updateNeighbors(p1);
                updateNeighbors(p2);
            }
        }

        printResult();
    }

    /**
     * Checks if a cell at (r, c) has exactly one neighbor that is an empty space ('.').
     * If so, adds the cell and its neighbor to the processing queue.
     */
    private void identifyPotentialConnections(int r, int c) {
        if (isSolidOrBoundary(r, c)) {
            return;
        }

        findOnlyEmptyNeighbor(r, c).ifPresent(neighbor -> {
            connectionQueue.add(new Connection(new Point(r, c), neighbor));
        });
    }

    /**
     * Searches for the single empty neighbor of a given cell.
     * Returns an Optional containing the Point if exactly one neighbor is empty.
     */
    private Optional<Point> findOnlyEmptyNeighbor(int r, int c) {
        int emptyCount = 0;
        Point emptyPoint = null;

        for (int d = 0; d < 4; d++) {
            int nr = r + ROW_OFFSETS[d];
            int nc = c + COL_OFFSETS[d];

            if (!isSolidOrBoundary(nr, nc)) {
                emptyCount++;
                emptyPoint = new Point(nr, nc);
            }
        }

        return (emptyCount == 1) ? Optional.of(emptyPoint) : Optional.empty();
    }

    /**
     * Determines if a cell is a wall ('*'), an arrow, or out of bounds.
     */
    private boolean isSolidOrBoundary(int r, int c) {
        if (r < 0 || r >= rows || c < 0 || c >= cols) {
            return true;
        }
        return grid[r][c] != '.';
    }

    private boolean isCellEmpty(Point p) {
        return grid[p.r()][p.c()] == '.';
    }

    /**
     * Re-scans the neighbors of a cell to check for new connection opportunities.
     */
    private void updateNeighbors(Point p) {
        for (int d = 0; d < 4; d++) {
            identifyPotentialConnections(p.r() + ROW_OFFSETS[d], p.c() + COL_OFFSETS[d]);
        }
    }

    /**
     * Sets the directional arrows for two cells based on the original logic.
     * Note: The original logic places arrows pointing away from each other.
     */
    private void applyArrows(Point p1, Point p2) {
        int r1 = p1.r(), c1 = p1.c();
        int r2 = p2.r(), c2 = p2.c();

        if (r1 == r2) { // Horizontal relationship
            if (c2 > c1) {
                grid[r1][c1] = '<';
                grid[r2][c2] = '>';
            } else {
                grid[r1][c1] = '>';
                grid[r2][c2] = '<';
            }
        } else { // Vertical relationship
            if (r2 > r1) {
                grid[r1][c1] = '^';
                grid[r2][c2] = 'v';
            } else {
                grid[r1][c1] = 'v';
                grid[r2][c2] = '^';
            }
        }
    }

    /**
     * Checks if all non-wall cells are filled and prints the grid or error message.
     */
    private void printResult() {
        boolean isComplete = true;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    isComplete = false;
                    break;
                }
            }
            if (!isComplete) break;
        }

        if (isComplete) {
            StringBuilder sb = new StringBuilder();
            for (int r = 0; r < rows; r++) {
                sb.append(new String(grid[r])).append("\n");
            }
            System.out.print(sb.toString());
        } else {
            System.out.println("Not unique");
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int n = scanner.nextInt();
        int m = scanner.nextInt();
        char[][] grid = new char[n][m];

        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        ArrowPuzzleSolver solver = new ArrowPuzzleSolver(n, m, grid);
        solver.solve();

        scanner.close();
    }
}

