/**
 * Represents a coordinate in the grid.
 * Using a record for conciseness and immutability (available in Java 14+).
 */
record Point(int row, int col) {}

/**
 * Constants for the characters used in the grid.
 */
class GridConstants {
    public static final char EMPTY = '.';
    public static final char WALL = '*';
    public static final char UP = '^';
    public static final char DOWN = 'v';
    public static final char LEFT = '<';
    public static final char RIGHT = '>';
}

/**
 * Encapsulates the grid data and provides helper methods for grid manipulation.
 * This improves maintainability by centralizing boundary checks and neighbor logic.
 */
class Grid {
    private final char[][] cells;
    private final int rows;
    private final int cols;

    public Grid(int rows, int cols) {
        this.rows = rows;
        this.cols = cols;
        this.cells = new char[rows][cols];
    }

    public int rows() { return rows; }
    public int cols() { return cols; }

    public void setCell(int r, int c, char value) {
        cells[r][c] = value;
    }

    public char getCell(int r, int c) {
        return cells[r][c];
    }

    public boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    public boolean isEmpty(Point p) {
        return isWithinBounds(p.row(), p.col()) && cells[p.row()][p.col()] == GridConstants.EMPTY;
    }

    /**
     * Returns all adjacent cells (Up, Down, Left, Right).
     */
    public List<Point> getNeighbors(Point p) {
        List<Point> neighbors = new ArrayList<>();
        int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        for (int[] d : directions) {
            int nr = p.row() + d[0];
            int nc = p.col() + d[1];
            if (isWithinBounds(nr, nc)) {
                neighbors.add(new Point(nr, nc));
            }
        }
        return neighbors;
    }

    /**
     * Counts how many adjacent cells are currently empty.
     */
    public long countEmptyNeighbors(Point p) {
        return getNeighbors(p).stream()
                .filter(this::isEmpty)
                .count();
    }

    /**
     * Finds an adjacent empty cell if exactly one exists.
     */
    public Optional<Point> getOnlyEmptyNeighbor(Point p) {
        return getNeighbors(p).stream()
                .filter(this::isEmpty)
                .findFirst();
    }

    public boolean isFullyFilled() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (cells[r][c] == GridConstants.EMPTY) {
                    return false;
                }
            }
        }
        return true;
    }

    public void print(OutputWriter out) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                out.print(cells[r][c]);
            }
            out.printLine();
        }
    }
}

/**
 * Contains the core logic to solve the grid puzzle.
 */
class FlowPuzzleSolver {

    public void solve(InputReader in, OutputWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();

        Grid grid = new Grid(n, m);
        for (int i = 0; i < n; i++) {
            String line = in.next();
            for (int j = 0; j < m; j++) {
                grid.setCell(i, j, line.charAt(j));
            }
        }

        Queue<Point> queue = new ArrayDeque<>();
        // Initialize queue with cells that have exactly one empty neighbor
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                Point p = new Point(r, c);
                if (grid.isEmpty(p) && grid.countEmptyNeighbors(p) == 1) {
                    queue.add(p);
                }
            }
        }

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            // If this cell was already filled by a previous propagation, skip
            if (!grid.isEmpty(current)) {
                continue;
            }

            Optional<Point> neighborOpt = grid.getOnlyEmptyNeighbor(current);
            if (neighborOpt.isEmpty()) {
                break; // Should not happen if logic is correct for valid puzzles
            }

            Point neighbor = neighborOpt.get();
            assignDirections(grid, current, neighbor);

            // Check neighbors of the newly filled neighbor cell to see if they now have only 1 empty neighbor
            for (Point adj : grid.getNeighbors(neighbor)) {
                if (grid.isEmpty(adj) && grid.countEmptyNeighbors(adj) == 1) {
                    queue.add(adj);
                }
            }
        }

        if (grid.isFullyFilled()) {
            grid.print(out);
        } else {
            out.printLine("Not unique");
        }
    }

    /**
     * Assigns directional characters to two adjacent cells based on their relative position.
     * Replicates the original logic behavior.
     */
    private void assignDirections(Grid grid, Point p1, Point p2) {
        if (p1.row() == p2.row()) {
            // Same row: horizontal arrows
            if (p1.col() < p2.col()) {
                grid.setCell(p1.row(), p1.col(), GridConstants.LEFT);
                grid.setCell(p2.row(), p2.col(), GridConstants.RIGHT);
            } else {
                grid.setCell(p1.row(), p1.col(), GridConstants.RIGHT);
                grid.setCell(p2.row(), p2.col(), GridConstants.LEFT);
            }
        } else {
            // Same column: vertical arrows
            if (p1.row() < p2.row()) {
                grid.setCell(p1.row(), p1.col(), GridConstants.UP);
                grid.setCell(p2.row(), p2.col(), GridConstants.DOWN);
            } else {
                grid.setCell(p1.row(), p1.col(), GridConstants.DOWN);
                grid.setCell(p2.row(), p2.col(), GridConstants.UP);
            }
        }
    }
}

/**
 * Efficient reader for large input datasets.
 */
class InputReader implements AutoCloseable {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    public InputReader(InputStream stream) {
        this.reader = new BufferedReader(new InputStreamReader(stream), 32768);
    }

    public String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                throw new RuntimeException("Error reading input", e);
            }
        }
        return tokenizer.nextToken();
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }

    @Override
    public void close() throws IOException {
        reader.close();
    }
}

/**
 * Efficient writer for large output datasets.
 */
class OutputWriter implements AutoCloseable {
    private final PrintWriter writer;

    public OutputWriter(OutputStream outputStream) {
        this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
    }

    public void print(Object obj) {
        writer.print(obj);
    }

    public void printLine(Object... objects) {
        for (int i = 0; i < objects.length; i++) {
            writer.print(objects[i]);
            if (i < objects.length - 1) {
                writer.print(' ');
            }
        }
        writer.println();
    }

    @Override
    public void close() {
        writer.close();
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver for the Domino Tiling problem.
 * The goal is to fill a grid with 1x2 dominoes based on directional symbols.
 */
public class Main {

    public static void main(String[] args) {
        try (FastReader in = new FastReader(System.in);
             FastWriter out = new FastWriter(System.out)) {

            int n = in.nextInt();
            int m = in.nextInt();
            char[][] field = in.readGrid(n, m);

            DominoSolver solver = new DominoSolver(n, m, field);
            solver.solve(out);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * Represents a coordinate in the grid.
     */
    record Point(int r, int c) {}

    static class DominoSolver {
        private static final char EMPTY_CHAR = '.';
        private static final String[] DOMINO_SYMBOLS = {"v^", "<>", "^v", "><"};
        private static final int[] ROW_OFFSETS = {-1, 0, 1, 0};
        private static final int[] COL_OFFSETS = {0, 1, 0, -1};

        private final int rows;
        private final int cols;
        private final char[][] field;

        public DominoSolver(int rows, int cols, char[][] field) {
            this.rows = rows;
            this.cols = cols;
            this.field = field;
        }

        public void solve(FastWriter out) throws IOException {
            Queue<Point> queue = new ArrayDeque<>();

            // Initialize queue with all empty cells that have exactly one neighbor
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (field[r][c] == EMPTY_CHAR && calculateDegree(r, c) == 1) {
                        queue.add(new Point(r, c));
                    }
                }
            }

            while (!queue.isEmpty()) {
                Point current = queue.poll();
                int r = current.r();
                int c = current.c();

                // If this cell was already filled by another domino, skip it
                if (field[r][c] != EMPTY_CHAR) {
                    continue;
                }

                // Find the single neighbor to form a domino
                for (int d = 0; d < 4; d++) {
                    int nr = r + ROW_OFFSETS[d];
                    int nc = c + COL_OFFSETS[d];

                    if (isInside(nr, nc) && field[nr][nc] == EMPTY_CHAR) {
                        placeDomino(r, c, d);

                        // After placing, check the neighbors of both newly filled cells
                        enqueueNeighborsIfDegreeOne(r, c, queue);
                        enqueueNeighborsIfDegreeOne(nr, nc, queue);
                        break; 
                    }
                }
            }

            if (isGridIncomplete()) {
                out.print("Not unique");
            } else {
                for (char[] row : field) {
                    out.printLine(row);
                }
            }
        }

        private void placeDomino(int r, int c, int direction) {
            String symbol = DOMINO_SYMBOLS[direction];
            field[r][c] = symbol.charAt(0);
            field[r + ROW_OFFSETS[direction]][c + COL_OFFSETS[direction]] = symbol.charAt(1);
        }

        private void enqueueNeighborsIfDegreeOne(int r, int c, Queue<Point> queue) {
            for (int d = 0; d < 4; d++) {
                int nr = r + ROW_OFFSETS[d];
                int nc = c + COL_OFFSETS[d];
                if (isInside(nr, nc) && field[nr][nc] == EMPTY_CHAR && calculateDegree(nr, nc) == 1) {
                    queue.add(new Point(nr, nc));
                }
            }
        }

        private int calculateDegree(int r, int c) {
            int degree = 0;
            for (int d = 0; d < 4; d++) {
                int nr = r + ROW_OFFSETS[d];
                int nc = c + COL_OFFSETS[d];
                if (isInside(nr, nc) && field[nr][nc] == EMPTY_CHAR) {
                    degree++;
                }
            }
            return degree;
        }

        private boolean isInside(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        private boolean isGridIncomplete() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (field[r][c] == EMPTY_CHAR) return true;
                }
            }
            return false;
        }
    }

    /**
     * Fast I/O Reader.
     */
    static class FastReader implements AutoCloseable {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int pointer = 0;
        private int bytesRead = 0;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() throws IOException {
            if (pointer >= bytesRead) {
                pointer = 0;
                bytesRead = stream.read(buffer);
                if (bytesRead <= 0) return -1;
            }
            return buffer[pointer++] & 0xFF;
        }

        public int nextInt() throws IOException {
            int c = readByte();
            while (c != -1 && c <= 32) c = readByte();
            if (c == -1) return 0;
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = readByte();
            }
            int res = 0;
            while (c >= '0' && c <= '9') {
                res = res * 10 + (c - '0');
                c = readByte();
            }
            return res * sgn;
        }

        public char nextChar() throws IOException {
            int c = readByte();
            while (c != -1 && c <= 32) c = readByte();
            return (char) c;
        }

        public char[][] readGrid(int n, int m) throws IOException {
            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    grid[i][j] = nextChar();
                }
            }
            return grid;
        }

        @Override
        public void close() throws IOException {
            stream.close();
        }
    }

    /**
     * Fast I/O Writer.
     */
    static class FastWriter implements AutoCloseable {
        private final PrintWriter writer;

        public FastWriter(OutputStream outputStream) {
            this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public void print(Object obj) {
            writer.print(obj);
        }

        public void printLine(char[] row) {
            writer.println(row);
        }

        @Override
        public void close() {
            writer.close();
        }
    }
}

