import java.io.*;

/**
 * Entry point for the Maze Path Solver application.
 */
public class Main {
    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] inputGrid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                inputGrid[i] = reader.next().toCharArray();
            }

            Maze maze = new Maze(rows, cols, inputGrid);
            MazeSolver solver = new MazeSolver();
            SolverResult result = solver.solve(maze);

            if (result.isUnique()) {
                printGrid(result.grid(), writer);
            } else {
                writer.println("Not unique");
            }
        } catch (Exception e) {
            writer.println("Error: " + e.getMessage());
        } finally {
            writer.close();
        }
    }

    private static void printGrid(char[][] grid, PrintWriter out) {
        for (char[] row : grid) {
            out.println(new String(row));
        }
    }
}

/**
 * Represents a coordinate in the 2D grid.
 */
record Point(int r, int c) {}

/**
 * Represents the outcome of the maze solving process.
 */
record SolverResult(boolean isUnique, char[][] grid) {}

/**
 * Encapsulates the maze data and provides safe access to its elements.
 */
class Maze {
    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int[][] neighborCounts;

    private static final int[] ROW_OFFSETS = {0, 1, 0, -1};
    private static final int[] COL_OFFSETS = {1, 0, -1, 0};

    public Maze(int rows, int cols, char[][] inputGrid) {
        this.rows = rows;
        this.cols = cols;
        // We use a padded grid to avoid complex boundary checks during algorithm execution
        this.grid = new char[rows + 2][cols + 2];
        this.neighborCounts = new int[rows + 2][cols + 2];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                this.grid[i + 1][j + 1] = inputGrid[i][j];
            }
        }
        calculateInitialDegrees();
    }

    private void calculateInitialDegrees() {
        for (int r = 1; r <= rows; r++) {
            for (int c = 1; c <= cols; c++) {
                if (grid[r][c] == '.') {
                    int count = 0;
                    for (int i = 0; i < 4; i++) {
                        if (grid[r + ROW_OFFSETS[i]][c + COL_OFFSETS[i]] == '.') {
                            count++;
                        }
                    }
                    neighborCounts[r][c] = count;
                }
            }
        }
    }

    public void decrementDegree(int r, int c) {
        neighborCounts[r][c]--;
    }

    public void setDegree(int r, int c, int val) {
        neighborCounts[r][c] = val;
    }

    public int getDegree(int r, int c) {
        return neighborCounts[r][c];
    }

    public char getCell(int r, int c) {
        return grid[r][c];
    }

    public void setCell(int r, int c, char val) {
        grid[r][c] = val;
    }

    public int getRows() { return rows; }
    public int getCols() { return cols; }

    public List<Point> getAdjacentEmptyPoints(int r, int c) {
        List<Point> neighbors = new ArrayList<>();
        for (int i = 0; i < 4; i++) {
            int nr = r + ROW_OFFSETS[i];
            int nc = c + COL_OFFSETS[i];
            if (grid[nr][nc] == '.') {
                neighbors.add(new Point(nr, nc));
            }
        }
        return neighbors;
    }

    public char[][] getResultingGrid() {
        char[][] result = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                result[i][j] = grid[i + 1][j + 1];
            }
        }
        return result;
    }

    public static int[] getRowOffsets() { return ROW_OFFSETS; }
    public static int[] getColOffsets() { return COL_OFFSETS; }
}

/**
 * Contains the logic to solve the maze path problem.
 */
class MazeSolver {
    public SolverResult solve(Maze maze) {
        Queue<Point> leafQueue = new LinkedList<>();
        int remainingCells = 0;

        // Initialization
        for (int r = 1; r <= maze.getRows(); r++) {
            for (int c = 1; c <= maze.getCols(); c++) {
                if (maze.getCell(r, c) == '.') {
                    remainingCells++;
                    if (maze.getDegree(r, c) == 1) {
                        leafQueue.add(new Point(r, c));
                    }
                }
            }
        }

        while (!leafQueue.isEmpty()) {
            Point current = leafQueue.poll();

            // If this cell was already processed/covered, skip
            if (maze.getCell(current.r(), current.c()) != '.') {
                continue;
            }

            List<Point> neighbors = maze.getAdjacentEmptyPoints(current.r(), current.c());
            if (neighbors.isEmpty()) {
                return new SolverResult(false, null);
            }

            Point neighbor = neighbors.get(0);
            applyPath(maze, current, neighbor);

            // Mark both as visited by zeroing degrees and changing grid content
            maze.setDegree(current.r(), current.c(), 0);
            maze.setDegree(neighbor.r(), neighbor.c(), 0);

            // Update neighbors of the second cell in the pair
            for (int i = 0; i < 4; i++) {
                int nr = neighbor.r() + Maze.getRowOffsets()[i];
                int nc = neighbor.c() + Maze.getColOffsets()[i];

                maze.decrementDegree(nr, nc);
                if (maze.getDegree(nr, nc) == 1) {
                    leafQueue.add(new Point(nr, nc));
                }
            }
            remainingCells -= 2;
        }

        if (remainingCells > 0) {
            return new SolverResult(false, null);
        }

        return new SolverResult(true, maze.getResultingGrid());
    }

    private void applyPath(Maze maze, Point p1, Point p2) {
        if (p1.r() == p2.r()) {
            // Horizontal path
            int minC = Math.min(p1.c(), p2.c());
            int maxC = Math.max(p1.c(), p2.c());
            maze.setCell(p1.r(), minC, '<');
            maze.setCell(p1.r(), maxC, '>');
        } else {
            // Vertical path
            int minR = Math.min(p1.r(), p2.r());
            int maxR = Math.max(p1.r(), p2.r());
            // Note: using p1.c() and p2.c() because for vertical adjacent cells, c must be equal
            maze.setCell(minR, p1.c(), '^');
            maze.setCell(maxR, p2.c(), 'v');
        }
    }
}

/**
 * Fast I/O utility for reading input.
 */
class FastReader {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    public FastReader(InputStream stream) {
        this.reader = new BufferedReader(new InputStreamReader(stream));
    }

    public String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                throw new RuntimeException("Failed to read input", e);
            }
        }
        return tokenizer.nextToken();
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }
}

import java.io.*;
import java.util.*;

/**
 * A refactored solution for a grid matching problem.
 * The algorithm finds pairs of adjacent '.' cells.
 * If a cell has only one '.' neighbor, it must be paired with that neighbor.
 */
public class GridMatchingSolver {

    /**
     * Fast I/O reader to handle large input efficiently.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            return next != null ? Integer.parseInt(next) : 0;
        }
    }

    /**
     * Represents a single cell in the grid.
     */
    private static class Cell {
        final int row, col;

        Cell(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int[][] neighborCount;
    private final boolean[][] isQueued;
    private final Deque<Cell> queue = new ArrayDeque<>();

    // Directional offsets for adjacent cells (Up, Down, Right, Left)
    private final int[] dr = {-1, 1, 0, 0};
    private final int[] dc = {0, 0, 1, -1};

    public GridMatchingSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.neighborCount = new int[rows][cols];
        this.isQueued = new boolean[rows][cols];
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Calculates how many '.' neighbors a cell has.
     * If a cell has exactly one '.' neighbor, it is added to the queue for processing.
     */
    private void updateCellStatus(int r, int c) {
        if (!isValid(r, c)) return;

        int count = 0;
        if (grid[r][c] == '.') {
            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i];
                int nc = c + dc[i];
                if (isValid(nr, nc) && grid[nr][nc] == '.') {
                    count++;
                }
            }
        }
        neighborCount[r][c] = count;

        // If a cell has exactly one available neighbor, it MUST be matched with it.
        if (count == 1 && !isQueued[r][c]) {
            queue.add(new Cell(r, c));
            isQueued[r][c] = true;
        }
    }

    /**
     * Updates the neighbor counts for all cells adjacent to the modified cell.
     */
    private void updateNeighbors(int r, int c) {
        for (int i = 0; i < 4; i++) {
            updateCellStatus(r + dr[i], c + dc[i]);
        }
    }

    /**
     * Attempts to pair the current cell with its single available '.' neighbor.
     */
    private void matchWithNeighbor(int r, int c) {
        if (grid[r][c] != '.') return;

        // Re-verify if this cell still has exactly one neighbor
        updateCellStatus(r, c);
        if (neighborCount[r][c] == 0) return;

        boolean matched = false;

        // Try to find the specific neighbor and apply direction markers.
        // Order follows original implementation: Right, Left, Down, Up.

        // 1. Right neighbor
        if (isValid(r, c + 1) && grid[r][c + 1] == '.') {
            grid[r][c] = '<';
            grid[r][c + 1] = '>';
            updateNeighbors(r, c + 1);
            matched = true;
        } 
        // 2. Left neighbor
        else if (isValid(r, c - 1) && grid[r][c - 1] == '.') {
            grid[r][c - 1] = '<';
            grid[r][c] = '>';
            updateNeighbors(r, c - 1);
            matched = true;
        } 
        // 3. Down neighbor
        else if (isValid(r + 1, c) && grid[r + 1][c] == '.') {
            grid[r][c] = '^';
            grid[r + 1][c] = 'v';
            updateNeighbors(r + 1, c);
            matched = true;
        } 
        // 4. Up neighbor
        else if (isValid(r - 1, c) && grid[r - 1][c] == '.') {
            grid[r - 1][c] = '^';
            grid[r][c] = 'v';
            updateNeighbors(r - 1, c);
            matched = true;
        }

        if (matched) {
            updateNeighbors(r, c);
        }
    }

    /**
     * Orchestrates the matching process and outputs the final result.
     */
    public void solve() {
        // Initialize neighbor counts for all cells
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                updateCellStatus(i, j);
            }
        }

        // Process cells that are forced to be matched
        while (!queue.isEmpty()) {
            Cell cell = queue.poll();
            matchWithNeighbor(cell.row, cell.col);
        }

        // Verify if all '.' cells were successfully matched
        if (hasUnmatchedDots()) {
            System.out.println("Not unique");
        } else {
            printGrid();
        }
    }

    private boolean hasUnmatchedDots() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.') return true;
            }
        }
        return false;
    }

    private void printGrid() {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                sb.append(grid[i][j]);
            }
            sb.append('\n');
        }
        System.out.print(sb.toString());
    }

    public static void main(String[] args) {
        FastReader fr = new FastReader(System.in);
        String firstLine = fr.next();
        if (firstLine == null) return;

        int rows = Integer.parseInt(firstLine);
        int cols = fr.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String rowData = fr.next();
            if (rowData != null) {
                grid[i] = rowData.toCharArray();
            }
        }

        GridMatchingSolver solver = new GridMatchingSolver(rows, cols, grid);
        solver.solve();
    }
}

import java.util.*;

/**
 * ArrowGridSolver solves a grid-based puzzle where every empty cell ('.') 
 * must be paired with an adjacent empty cell using arrows.
 * 
 * The algorithm uses constraint propagation: if an empty cell has only 
 * one empty neighbor, it is "forced" to pair with that neighbor.
 */
public class ArrowGridSolver {

    // Character constants for clarity
    private static final char EMPTY = '.';
    private static final char UP = '^';
    private static final char DOWN = 'v';
    private static final char LEFT = '<';
    private static final char RIGHT = '>';

    // Direction vectors for grid traversal (Up, Down, Left, Right)
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    private final int rows;
    private final int cols;
    private final char[][] grid;

    /**
     * Represents a coordinate on the grid.
     */
    private static class Point {
        final int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    public ArrowGridSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
    }

    /**
     * Executes the constraint propagation algorithm.
     * 
     * @return The filled grid if a unique solution is found, or null if not unique.
     */
    public char[][] solve() {
        Queue<Point> currentQueue = new LinkedList<>();

        // Initial pass: Identify all cells that are immediately forced
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == EMPTY && countEmptyNeighbors(r, c) == 1) {
                    currentQueue.add(new Point(r, c));
                }
            }
        }

        while (!currentQueue.isEmpty()) {
            Queue<Point> nextQueue = new LinkedList<>();

            for (Point p : currentQueue) {
                int r = p.r;
                int c = p.c;

                // If the cell was already filled by a previous forced move, skip it
                if (grid[r][c] != EMPTY) {
                    continue;
                }

                Point neighbor = findEmptyNeighbor(r, c);
                if (neighbor == null) {
                    continue;
                }

                // Apply the forced arrow connection
                applyForcedMove(r, c, neighbor.r, neighbor.c);

                // Propagate the change: Check neighbors of the newly filled cells.
                // We focus on the neighbor's neighbors to see if their "empty count" 
                // has dropped to 1.
                for (int d = 0; d < 4; d++) {
                    int nr = neighbor.r + DR[d];
                    int nc = neighbor.c + DC[d];
                    if (isWithinBounds(nr, nc) && grid[nr][nc] == EMPTY) {
                        if (countEmptyNeighbors(nr, nc) == 1) {
                            nextQueue.add(new Point(nr, nc));
                        }
                    }
                }
            }
            currentQueue = nextQueue;
        }

        return isFullyFilled() ? grid : null;
    }

    /**
     * Places arrows in the two cells to create a connection.
     * Logic maintains the exact behavior of the original program.
     */
    private void applyForcedMove(int r1, int c1, int r2, int c2) {
        if (r2 == r1 - 1) { // Neighbor is Above
            grid[r1][c1] = DOWN;
            grid[r2][c2] = UP;
        } else if (r2 == r1 + 1) { // Neighbor is Below
            grid[r1][c1] = UP;
            grid[r2][c2] = DOWN;
        } else if (c2 == c1 - 1) { // Neighbor is Left
            grid[r1][c1] = RIGHT;
            grid[r2][c2] = LEFT;
        } else if (c2 == c1 + 1) { // Neighbor is Right
            grid[r1][c1] = LEFT;
            grid[r2][c2] = RIGHT;
        }
    }

    private Point findEmptyNeighbor(int r, int c) {
        for (int d = 0; d < 4; d++) {
            int nr = r + DR[d];
            int nc = c + DC[d];
            if (isWithinBounds(nr, nc) && grid[nr][nc] == EMPTY) {
                return new Point(nr, nc);
            }
        }
        return null;
    }

    private int countEmptyNeighbors(int r, int c) {
        int count = 0;
        for (int d = 0; d < 4; d++) {
            int nr = r + DR[d];
            int nc = c + DC[d];
            if (isWithinBounds(nr, nc) && grid[nr][nc] == EMPTY) {
                count++;
            }
        }
        return count;
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private boolean isFullyFilled() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == EMPTY) return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) return;

        int n = scanner.nextInt();
        int m = scanner.nextInt();
        scanner.nextLine(); // Consume newline

        char[][] inputGrid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String line = scanner.nextLine();
            for (int j = 0; j < m; j++) {
                inputGrid[i][j] = line.charAt(j);
            }
        }

        ArrowGridSolver solver = new ArrowGridSolver(n, m, inputGrid);
        char[][] result = solver.solve();

        if (result == null) {
            System.out.println("Not unique");
        } else {
            printGrid(result);
        }
        scanner.close();
    }

    private static void printGrid(char[][] grid) {
        StringBuilder sb = new StringBuilder();
        for (char[] row : grid) {
            sb.append(new String(row)).append("\n");
        }
        System.out.print(sb.toString());
    }
}

