/**
 * Solves the grid-based transformation problem.
 */
class GridProblemSolver {
    private static final char CHAR_OCCUPIED = 'x';
    private static final char CHAR_PIECE = 'o';
    private static final char CHAR_EMPTY = '.';

    /**
     * Orchestrates the reading, solving, and printing of the problem.
     */
    public void solve(FastReader in, PrintWriter out) {
        int n = in.readInt();
        if (n <= 0) return;

        char[][] originalBoard = readBoard(in, n);

        // The answer grid is of size (2n-1) x (2n-1)
        int resultSize = 2 * n - 1;
        char[][] resultGrid = new char[resultSize][resultSize];
        for (char[] row : resultGrid) {
            Arrays.fill(row, CHAR_EMPTY);
        }

        // The center of the result grid is the starting piece
        int center = n - 1;
        resultGrid[center][center] = CHAR_PIECE;

        // simulatedBoard tracks the changes made by valid offsets
        char[][] simulatedBoard = initializeSimulatedBoard(originalBoard, n);

        // Iterate through all possible relative offsets (dx, dy)
        for (int rowOffset = -(n - 1); rowOffset <= n - 1; rowOffset++) {
            for (int colOffset = -(n - 1); colOffset <= n - 1; colOffset++) {
                if (rowOffset == 0 && colOffset == 0) {
                    continue;
                }

                if (isValidOffset(originalBoard, rowOffset, colOffset)) {
                    applyOffsetToResult(resultGrid, rowOffset, colOffset, center);
                    applyOffsetToSimulatedBoard(simulatedBoard, originalBoard, rowOffset, colOffset, n);
                }
            }
        }

        if (isSimulatedBoardValid(originalBoard, simulatedBoard, n)) {
            out.println("YES");
            printGrid(out, resultGrid);
        } else {
            out.println("NO");
        }
    }

    private char[][] readBoard(FastReader in, int n) {
        char[][] board = new char[n][n];
        for (int i = 0; i < n; i++) {
            board[i] = in.readString().toCharArray();
        }
        return board;
    }

    private char[][] initializeSimulatedBoard(char[][] originalBoard, int n) {
        char[][] simulated = new char[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                simulated[i][j] = (originalBoard[i][j] == CHAR_PIECE) ? CHAR_PIECE : CHAR_EMPTY;
            }
        }
        return simulated;
    }

    /**
     * Checks if a given offset does not cause a conflict between pieces and empty spaces.
     */
    private boolean isValidOffset(char[][] board, int rowOffset, int colOffset) {
        int n = board.length;
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (board[r][c] == CHAR_PIECE) {
                    int targetR = r + rowOffset;
                    int targetC = c + colOffset;
                    if (isWithinBounds(n, targetR, targetC) && board[targetR][targetC] == CHAR_EMPTY) {
                        return false;
                    }
                } else if (board[r][c] == CHAR_EMPTY) {
                    int sourceR = r - rowOffset;
                    int sourceC = c - colOffset;
                    if (isWithinBounds(n, sourceR, sourceC) && board[sourceR][sourceC] == CHAR_PIECE) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    private void applyOffsetToResult(char[][] resultGrid, int rowOffset, int colOffset, int center) {
        resultGrid[center + rowOffset][center + colOffset] = CHAR_OCCUPIED;
    }

    private void applyOffsetToSimulatedBoard(char[][] simulatedBoard, char[][] originalBoard, 
                                            int rowOffset, int colOffset, int n) {
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (originalBoard[r][c] == CHAR_PIECE) {
                    int targetR = r + rowOffset;
                    int targetC = c + colOffset;
                    if (isWithinBounds(n, targetR, targetC) && simulatedBoard[targetR][targetC] == CHAR_EMPTY) {
                        simulatedBoard[targetR][targetC] = CHAR_OCCUPIED;
                    }
                }
            }
        }
    }

    private boolean isSimulatedBoardValid(char[][] original, char[][] simulated, int n) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (original[i][j] != simulated[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    private boolean isWithinBounds(int n, int r, int c) {
        return r >= 0 && r < n && c >= 0 && c < n;
    }

    private void printGrid(PrintWriter out, char[][] grid) {
        for (char[] row : grid) {
            out.println(new String(row));
        }
    }
}

/**
 * Fast I/O reader for performance.
 */
class FastReader {
    private final InputStream stream;
    private final byte[] buffer = new byte[1024];
    private int curChar;
    private int numChars;

    public FastReader(InputStream stream) {
        this.stream = stream;
    }

    private int read() {
        if (numChars == -1) throw new RuntimeException("End of stream");
        if (curChar >= numChars) {
            curChar = 0;
            try {
                numChars = stream.read(buffer);
            } catch (IOException e) {
                throw new RuntimeException("IO Error", e);
            }
            if (numChars <= 0) return -1;
        }
        return buffer[curChar++];
    }

    public int readInt() {
        int c = read();
        while (isSpaceChar(c)) c = read();
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        } else if (c == '+') {
            c = read();
        }
        int res = 0;
        do {
            if (c < '0' || c > '9') throw new InputMismatchException();
            res = res * 10 + (c - '0');
            c = read();
        } while (!isSpaceChar(c));
        return res * sgn;
    }

    public String readString() {
        int c = read();
        while (isSpaceChar(c)) c = read();
        StringBuilder res = new StringBuilder();
        do {
            res.appendCodePoint(c);
            c = read();
        } while (!isSpaceChar(c));
        return res.toString();
    }

    private boolean isSpaceChar(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.StringTokenizer;

/**
 * A solution to determine if a grid of attacks and pieces 
 * follows a consistent relative attack pattern.
 */
public class Solution {

    private static final char ATTACK_CHAR = 'x';
    private static final char PIECE_CHAR = 'o';
    private static final char EMPTY_CHAR = '.';

    private int n;
    private boolean[][] attackGrid;
    private List<Point> pieceLocations;

    /**
     * Represents a 2D coordinate on the grid.
     */
    private record Point(int row, int col) {}

    /**
     * Main entry point.
     */
    public static void main(String[] args) {
        try {
            new Solution().run();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * Orchestrates the lifecycle of the program.
     */
    private void run() throws IOException {
        FastReader reader = new FastReader();
        PrintWriter writer = new PrintWriter(System.out);

        solve(reader, writer);

        writer.flush();
        writer.close();
    }

    /**
     * Core logic of the program.
     */
    private void solve(FastReader reader, PrintWriter writer) throws IOException {
        readInput(reader);

        boolean[][] validOffsets = computeValidOffsets();
        boolean[][] reconstructedGrid = reconstructGrid(validOffsets);

        if (isReconstructionValid(reconstructedGrid)) {
            writer.println("YES");
            printOffsetGrid(writer, validOffsets);
        } else {
            writer.println("NO");
        }
    }

    /**
     * Reads the grid size and the grid itself.
     */
    private void readInput(FastReader reader) throws IOException {
        this.n = reader.nextInt();
        this.attackGrid = new boolean[n][n];
        this.pieceLocations = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            String line = reader.next();
            for (int j = 0; j < n; j++) {
                char c = line.charAt(j);
                if (c == ATTACK_CHAR) {
                    attackGrid[i][j] = true;
                } else if (c == PIECE_CHAR) {
                    attackGrid[i][j] = true;
                    pieceLocations.add(new Point(i, j));
                }
            }
        }
    }

    /**
     * Determines which relative offsets (dx, dy) are valid.
     * An offset is valid if, when applied to any piece, 
     * it only lands on an attack square or out of bounds.
     */
    private boolean[][] computeValidOffsets() {
        int offsetSize = 2 * n - 1;
        boolean[][] validOffsets = new boolean[offsetSize][offsetSize];
        for (boolean[] row : validOffsets) {
            Arrays.fill(row, true);
        }

        // The center of the offset grid represents (0,0)
        int center = n - 1;
        validOffsets[center][center] = false;

        for (Point piece : pieceLocations) {
            for (int dx = -(n - 1); dx <= n - 1; dx++) {
                for (int dy = -(n - 1); dy <= n - 1; dy++) {
                    int targetRow = piece.row() + dx;
                    int targetCol = piece.col() + dy;

                    if (isWithinBounds(targetRow, targetCol)) {
                        // If the offset lands on a non-attack square, that offset is invalid
                        if (!attackGrid[targetRow][targetCol]) {
                            validOffsets[dx + center][dy + center] = false;
                        }
                    }
                }
            }
        }
        return validOffsets;
    }

    /**
     * Reconstructs an attack grid based on the valid offsets found.
     */
    private boolean[][] reconstructGrid(boolean[][] validOffsets) {
        boolean[][] reconstructed = new boolean[n][n];
        int center = n - 1;

        for (Point piece : pieceLocations) {
            for (int dx = -(n - 1); dx <= n - 1; dx++) {
                for (int dy = -(n - 1); dy <= n - 1; dy++) {
                    int targetRow = piece.row() + dx;
                    int targetCol = piece.col() + dy;

                    if (isWithinBounds(targetRow, targetCol)) {
                        boolean isZeroOffset = (dx == 0 && dy == 0);
                        if (validOffsets[dx + center][dy + center] || isZeroOffset) {
                            reconstructed[targetRow][targetCol] = true;
                        }
                    }
                }
            }
        }
        return reconstructed;
    }

    /**
     * Checks if the reconstructed grid matches the original input grid.
     */
    private boolean isReconstructionValid(boolean[][] reconstructed) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (reconstructed[i][j] != attackGrid[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Prints the valid offset grid in the required format.
     */
    private void printOffsetGrid(PrintWriter writer, boolean[][] validOffsets) {
        int offsetSize = 2 * n - 1;
        int center = n - 1;

        for (int i = 0; i < offsetSize; i++) {
            for (int j = 0; j < offsetSize; j++) {
                if (i == center && j == center) {
                    writer.print(PIECE_CHAR);
                } else if (validOffsets[i][j]) {
                    writer.print(ATTACK_CHAR);
                } else {
                    writer.print(EMPTY_CHAR);
                }
            }
            writer.println();
        }
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < n && c >= 0 && c < n;
    }

    /**
     * Fast I/O utility class.
     */
    private static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

