/**
 * Represents the possible states of a cell in the puzzle.
 */
enum CellType {
    X, O, DOT;

    public static CellType fromChar(char c) {
        return switch (c) {
            case 'x' -> X;
            case 'o' -> O;
            case '.' -> DOT;
            default -> throw new IllegalArgumentException("Invalid character: " + c);
        };
    }

    @Override
    public String toString(CellType type) {
        return switch (type) {
            case X -> "x";
            case O -> "o";
            case DOT -> ".";
        };
    }
}

/**
 * Solves the puzzle by determining if a valid configuration of '.' 
 * exists based on the placement of 'o' pieces.
 */
class PuzzleSolver {
    private final int gridSize;
    private final CellType[][] extendedGrid;
    private final boolean[][] possibleDotMask;

    public PuzzleSolver(int n, CellType[][] inputGrid) {
        this.gridSize = n;
        this.extendedGrid = new CellType[3 * n][3 * n];
        this.possibleDotMask = new boolean[2 * n - 1][2 * n - 1];

        // Initialize extended grid with X by default
        for (int i = 0; i < 3 * n; i++) {
            for (int j = 0; j < 3 * n; j++) {
                extendedGrid[i][j] = CellType.X;
            }
        }

        // Place the input grid into the center of the extended grid
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                extendedGrid[n + r][n + c] = inputGrid[r][c];
            }
        }
    }

    public void solve() {
        // 1. Identify possible '.' positions based on 'o' placements
        for (int r = 0; r < gridSize; r++) {
            for (int c = 0; c < gridSize; c++) {
                if (extendedGrid[nOffset(r)][nOffset(c)] == CellType.O) {
                    boolean[][] neighborhoodMask = calculateNeighborhoodMask(nOffset(r), nOffset(c));
                    unionMasks(neighborhoodMask);
                }
            }
        }

        // 2. Verify if the coverage is valid
        if (isCoverageValid()) {
            System.out.println("YES");
            printResult();
        } else {
            System.out.println("NO");
        }
    }

    private int nOffset(int index) {
        return gridSize + index;
    }

    /**
     * Calculates a mask of where '.' characters exist in the neighborhood 
     * of a given piece position.
     */
    private boolean[][] calculateNeighborhoodMask(int centerRow, int centerCol) {
        boolean[][] mask = new boolean[2 * gridSize - 1][2 * gridSize - 1];
        for (int r = centerRow - gridSize + 1; r < centerRow + gridSize; r++) {
            for (int c = centerCol - gridSize + 1; c < centerCol + gridSize; c++) {
                // Bounds check for the extended grid
                if (r >= 0 && r < 3 * gridSize && c >= 0 && c < 3 * gridSize) {
                    if (extendedGrid[r][c] == CellType.DOT) {
                        int maskR = r - centerCol + gridSize - 1;
                        int maskC = c - centerRow + gridSize - 1;
                        if (maskR >= 0 && maskR < mask.length && maskC >= 0 && maskC < mask[0].length) {
                            mask[maskR][maskC] = true;
                        }
                    }
                }
            }
        }
        return mask;
    }

    private void unionMasks(boolean[][] newMask) {
