import java.io.*;
import java.util.*;

/**
 * Represents a point or offset in a 2D coordinate system.
 */
record Coordinate(int x, int y) {}

/**
 * Represents the result of the board solving process.
 */
record Solution(boolean isPossible, char[][] resultGrid) {
    public void print(PrintWriter out) {
        if (!isPossible) {
            out.println("NO");
        } else {
            out.println("YES");
            for (char[] row : resultGrid) {
                out.println(new String(row));
            }
        }
    }
}

/**
 * Encapsulates the grid data and provides boundary-safe access.
 */
class Grid {
    private final int size;
    private final char[][] cells;

    public Grid(int size) {
        this.size = size;
        this.cells = new char[size][size];
    }

    public Grid(char[][] cells) {
        this.size = cells.length;
        this.cells = cells;
    }

    public int getSize() {
        return size;
    }

    public char get(int x, int y) {
        return cells[y][x];
    }

    public void set(int x, int y, char value) {
        cells[y][x] = value;
    }

    public boolean isWithinBounds(int x, int y) {
        return x >= 0 && x < size && y >= 0 && y < size;
    }

    public char[][] getCells() {
        return cells;
    }
}

/**
 * Contains the core logic for solving the grid puzzle.
 */
class BoardSolver {
    private static final char EMPTY = '.';
    private static final char OCCUPIED = 'o';
    private static final char BLOCKED = 'x';

    public Solution solve(Grid inputGrid) {
        int n = inputGrid.getSize();
        List<Coordinate> occupiedCoordinates = findOccupiedSquares(inputGrid);

        int resultSize = 2 * n - 1;
        char[][] resultCells = new char[resultSize][resultSize];
        List<Coordinate> validMoves = new ArrayList<>();

        // 1. Construct the result grid based on offsets
        for (int row = 0; row < resultSize; row++) {
            for (int col = 0; col < resultSize; col++) {
                if (row == n - 1 && col == n - 1) {
                    resultCells[row][col] = OCCUPIED;
                } else {
                    int offsetX = col - (n - 1);
                    int offsetY = row - (n - 1);

                    if (canFindEmptyDestination(inputGrid, occupiedCoordinates, offsetX, offsetY)) {
                        resultCells[row][col] = EMPTY;
                    } else {
                        resultCells[row][col] = BLOCKED;
                        validMoves.add(new Coordinate(offsetX, offsetY));
                    }
                }
            }
        }

        // 2. Validate the moves against the original board
        if (isValidationSuccessful(inputGrid, validMoves)) {
            return new Solution(true, resultCells);
        } else {
            return new Solution(false, null);
        }
    }

    private List<Coordinate> findOccupiedSquares(Grid grid) {
        List<Coordinate> occupied = new ArrayList<>();
        for (int r = 0; r < grid.getSize(); r++) {
            for (int c = 0; c < grid.getSize(); c++) {
                if (grid.get(c, r) == OCCUPIED) {
                    occupied.add(new Coordinate(c, r));
                }
            }
        }
        return occupied;
    }

    private boolean canFindEmptyDestination(Grid grid, List<Coordinate> occupied, int offX, int offY) {
        for (Coordinate pos : occupied) {
            int destX = pos.x() + offX;
            int destY = pos.y() + offY;
            if (grid.isWithinBounds(destX, destY) && grid.get(destX, destY) == EMPTY) {
                return true;
            }
        }
        return false;
    }

    private boolean isValidationSuccessful(Grid grid, List<Coordinate> moves) {
        int n = grid.getSize();
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid.get(c, r) == BLOCKED) {
                    if (!isCoveredByMove(grid, moves, c, r)) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    private boolean isCoveredByMove(Grid grid, List<Coordinate> moves, int x, int y) {
        for (Coordinate move : moves) {
            int targetX = x - move.x();
            int targetY = y - move.y();
            if (grid.isWithinBounds(targetX, targetY) && grid.get(targetX, targetY) == OCCUPIED) {
                return true;
            }
        }
        return false;
    }
}

