/**
 * Logic for solving the relative grid pattern problem.
 */
class RelativeGridSolver {
    private static final char SOURCE_CHAR = 'o';
    private static final char TARGET_CHAR = 'x';
    private static final char EMPTY_CHAR = '.';

    private final FastReader reader;
    private final PrintWriter writer;

    public RelativeGridSolver(FastReader reader, PrintWriter writer) {
        this.reader = reader;
        this.writer = writer;
    }

    /**
     * Coordinates the steps of the algorithm.
     */
    public void solve() throws IOException {
        int gridSize = reader.nextInt();
        String[] inputGrid = new String[gridSize];
        for (int i = 0; i < gridSize; i++) {
            inputGrid[i] = reader.next();
        }

        List<Point> sources = findPositions(inputGrid, gridSize, SOURCE_CHAR);
        List<Point> targets = findPositions(inputGrid, gridSize, TARGET_CHAR);
        List<Point> empties = findPositions(inputGrid, gridSize, EMPTY_CHAR);

        char[][] relativeGrid = buildRelativeGrid(gridSize, sources, empties);

        if (validateTargets(gridSize, targets, sources, relativeGrid)) {
            writer.println("YES");
            printGrid(relativeGrid);
        } else {
            writer.println("NO");
        }
    }

    private List<Point> findPositions(String[] grid, int n, char target) {
        List<Point> positions = new ArrayList<>();
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r].charAt(c) == target) {
                    positions.add(new Point(r, c));
                }
            }
        }
        return positions;
    }

    private char[][] buildRelativeGrid(int n, List<Point> sources, List<Point> empties) {
        int relativeDim = 2 * n - 1;
        char[][] relativeGrid = new char[relativeDim][relativeDim];

        // Initialize with target character
        for (int i = 0; i < relativeDim; i++) {
            Arrays.fill(relativeGrid[i], TARGET_CHAR);
        }

        // Center point is the source origin
        relativeGrid[n - 1][n - 1] = SOURCE_CHAR;

        // For every empty cell, mark the relative offsets from all sources as empty
        for (Point empty : empties) {
            for (Point source : sources) {
                int rowOffset = n - 1 + (empty.row - source.row);
                int colOffset = n - 1 + (empty.col - source.col);
                relativeGrid[rowOffset][colOffset] = EMPTY_CHAR;
            }
        }
        return relativeGrid;
    }

    private boolean validateTargets(int n, List<Point> targets, List<Point> sources, char[][] relativeGrid) {
        for (Point target : targets) {
            boolean hasValidOffset = false;
            for (Point source : sources) {
                int rowOffset = n - 1 + (target.row - source.row);
                int colOffset = n - 1 + (target.col - source.col);

                // A target is valid if at least one source-relative offset points to a 'x' (or 'o' center)
                // In the original logic, it specifically checks for 'x'
                if (relativeGrid[rowOffset][colOffset] == TARGET_CHAR) {
                    hasValidOffset = true;
                    break;
                }
            }
            if (!hasValidOffset) {
                return false;
            }
        }
        return true;
    }

    private void printGrid(char[][] grid) {
        for (char[] row : grid) {
            writer.println(new String(row));
        }
    }

    /**
     * Simple data structure to represent a coordinate.
     */
    private static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }
}

