 * Represents a 2D coordinate in the grid.
 */
record Point(int row, int col) {}

/**
 * Handles the core logic of the grid transformation and validation.
 */
class GridSolver {
    private final FastReader reader;
    private int gridSize;
    private char[][] inputGrid;
    private List<Point> observers;
    private boolean[][] isSafeMap;
    private int offset;

    public GridSolver(FastReader reader) {
        this.reader = reader;
    }

    /**
     * Orchestrates the solving process.
     */
    public void solve(PrintWriter out) {
        readInput();
        calculateSafeZones();

        if (!validateObstacles()) {
            out.println("NO");
            return;
        }

        out.println("YES");
        printResultGrid(out);
    }

    private void readInput() {
        gridSize = reader.nextInt();
        inputGrid = new char[gridSize][];
        observers = new ArrayList<>();

        for (int i = 0; i < gridSize; i++) {
            inputGrid[i] = reader.next().toCharArray();
            for (int j = 0; j < gridSize; j++) {
                if (inputGrid[i][j] == 'o') {
                    observers.add(new Point(i, j));
                }
            }
        }
    }

    /**
     * Maps safe relative positions based on the empty '.' spots in the input grid.
     */
    private void calculateSafeZones() {
        int mapSize = 2 * gridSize - 1;
        isSafeMap = new boolean[mapSize][mapSize];
        offset = gridSize - 1;

        for (int i = 0; i < gridSize; i++) {
            for (int j = 0; j < gridSize; j++) {
                if (inputGrid[i][j] == '.') {
                    markRelativeSafeSpot(i, j);
                }
            }
        }
    }

    private void markRelativeSafeSpot(int row, int col) {
        for (Point observer : observers) {
            int relativeRow = offset + (row - observer.row());
            int relativeCol = offset + (col - observer.col());
            isSafeMap[relativeRow][relativeCol] = true;
        }
    }

    /**
     * Ensures all 'x' obstacles are "attacked" (i.e., not in a safe relative position).
     */
    private boolean validateObstacles() {
        for (int i = 0; i < gridSize; i++) {
            for (int j = 0; j < gridSize; j++) {
                if (inputGrid[i][j] == 'x') {
                    if (!isObstacleAttacked(i, j)) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    private boolean isObstacleAttacked(int row, int col) {
        for (Point observer : observers) {
            int relativeRow = offset + (row - observer.row());
            int relativeCol = offset + (col - observer.col());
            // If the relative position is NOT marked safe, it is considered attacked
            if (!isSafeMap[relativeRow][relativeCol]) {
                return true;
            }
        }
        return false;
    }

    private void printResultGrid(PrintWriter out) {
        int mapSize = 2 * gridSize - 1;
        for (int i = 0; i < mapSize; i++) {
            for (int j = 0; j < mapSize; j++) {
                if (i == offset && j == offset) {
                    out.print('o');
                } else {
                    out.print(isSafeMap[i][j] ? '.' : 'x');
                }
            }
            out.println();
        }
    }
}

