import java.util.*;

/**
 * A solution to the grid transformation problem.
 * The goal is to construct a larger grid based on the placement of 'o' characters
 * in an input grid and validate the constraints of 'x' and '.' characters.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        try {
            int n = reader.nextInt();
            char[][] inputGrid = reader.readGrid(n);

            GridSolver solver = new GridSolver(n, inputGrid);
            GridSolver.Result result = solver.solve();

            if (result.isPossible()) {
                System.out.println("YES");
                result.printGrid();
            } else {
                System.out.println("NO");
            }
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Represents a 2D coordinate in the grid.
     */
    record Coordinate(int row, int col) {}

    /**
     * Handles the core logic of the grid transformation and validation.
     */
    static class GridSolver {
        private static final char CHAR_X = 'x';
        private static final char CHAR_O = 'o';
        private static final char CHAR_DOT = '.';

        private final int n;
        private final char[][] inputGrid;
        private final List<Coordinate> oPositions;

        public GridSolver(int n, char[][] inputGrid) {
            this.n = n;
            this.inputGrid = inputGrid;
            this.oPositions = new ArrayList<>();
            findOPositions();
        }

        private void findOPositions() {
            for (int r = 0; r < n; r++) {
                for (int c = 0; c < n; c++) {
                    if (inputGrid[r][c] == CHAR_O) {
                        oPositions.add(new Coordinate(r, c));
                    }
                }
            }
        }

        public Result solve() {
            int resultSize = 2 * n - 1;
            char[][] resultGrid = initializeResultGrid(resultSize);

            applyDotsToResult(resultGrid);

            boolean possible = validateXs(resultGrid);

            return new Result(possible, resultGrid);
        }

        private char[][] initializeResultGrid(int size) {
            char[][] grid = new char[size][size];
            for (int i = 0; i < size; i++) {
                Arrays.fill(grid[i], CHAR_X);
            }
            // The center of the resulting grid is always 'o'
            grid[n - 1][n - 1] = CHAR_O;
            return grid;
        }

        private void applyDotsToResult(char[][] resultGrid) {
            for (int r = 0; r < n; r++) {
                for (int c = 0; c < n; c++) {
                    if (inputGrid[r][c] == CHAR_DOT) {
                        for (Coordinate origin : oPositions) {
                            Coordinate transformed = transform(r, c, origin);
                            resultGrid[transformed.row()][transformed.col()] = CHAR_DOT;
                        }
                    }
                }
            }
        }

        private boolean validateXs(char[][] resultGrid) {
            for (int r = 0; r < n; r++) {
                for (int c = 0; c < n; c++) {
                    if (inputGrid[r][c] == CHAR_X) {
                        if (!hasAtLeastOneXMatch(r, c, resultGrid)) {
                            return false;
                        }
                    }
                }
            }
            return true;
        }

        private boolean hasAtLeastOneXMatch(int r, int c, char[][] resultGrid) {
            for (Coordinate origin : oPositions) {
                Coordinate transformed = transform(r, c, origin);
                if (resultGrid[transformed.row()][transformed.col()] == CHAR_X) {
                    return true;
                }
            }
            return false;
        }

        /**
         * Calculates the transformed position in the result grid.
         * Transformation formula: target = (n-1) - (origin - input)
         */
        private Coordinate transform(int inputRow, int inputCol, Coordinate origin) {
            int rowDiff = origin.row() - inputRow;
            int colDiff = origin.col() - inputCol;
            int targetRow = (n - 1) - rowDiff;
            int targetCol = (n - 1) - colDiff;
            return new Coordinate(targetRow, targetCol);
        }

        /**
         * Encapsulates the outcome of the solver.
         */
        static class Result {
            private final boolean possible;
            private final char[][] grid;

            public Result(boolean possible, char[][] grid) {
                this.possible = possible;
                this.grid = grid;
            }

            public boolean isPossible() {
                return possible;
            }

            public void printGrid() {
                StringBuilder sb = new StringBuilder();
                for (char[] row : grid) {
                    sb.append(row).append('\n');
                }
                System.out.print(sb.toString());
            }
        }
    }

    /**
     * Utility class for fast I/O operations.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public char[][] readGrid(int n) throws IOException {
            char[][] grid = new char[n][n];
            for (int i = 0; i < n; i++) {
                String row = next();
                for (int j = 0; j < n; j++) {
                    grid[i][j] = row.charAt(j);
                }
            }
            return grid;
        }
    }
}

import java.util.*;

/**
 * PatternMatcher solves a grid-based pattern matching problem.
 * It determines if a set of 'hits' can be covered by a 'figure' 
 * translated by various 'dots' in a grid.
 */
public class PatternMatcher {

    /**
     * Represents a coordinate in the 2D grid.
     */
    private static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) return;

        int gridSize = scanner.nextInt();
        scanner.nextLine(); // Consume newline

        PatternMatcher matcher = new PatternMatcher();
        matcher.run(gridSize, scanner);
    }

    public void run(int gridSize, Scanner scanner) {
        List<Point> hits = new ArrayList<>();
        List<Point> figures = new ArrayList<>();
        List<Point> dots = new ArrayList<>();

        // 1. Parse Input
        for (int i = 0; i < gridSize; i++) {
            String line = scanner.nextLine();
            for (int j = 0; j < gridSize; j++) {
                char cell = line.charAt(j);
                Point p = new Point(i, j);
                if (cell == 'x') {
                    hits.add(p);
                } else if (cell == 'o') {
                    figures.add(p);
                } else {
                    dots.add(p);
                }
            }
        }

        // 2. Compute Result Grid
        char[][] resultGrid = computeResultGrid(gridSize, dots, figures);

        // 3. Validate Hits
        if (validateHits(hits, figures, resultGrid, gridSize)) {
            System.out.println("YES");
            printGrid(resultGrid);
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Creates the result grid by initializing it with 'x' and 
     * masking out positions based on the relationship between dots and figures.
     */
    private char[][] computeResultGrid(int n, List<Point> dots, List<Point> figures) {
        int resultSize = 2 * n - 1;
        char[][] res = new char[resultSize][resultSize];

        // Initialize grid with 'x'
        for (int i = 0; i < resultSize; i++) {
            Arrays.fill(res[i], 'x');
        }

        // Central anchor point
        res[n - 1][n - 1] = 'o';

        // Mark invalid positions ('.') based on relative offsets
        for (Point dot : dots) {
            for (Point fig : figures) {
                int targetRow = n - 1 - fig.row + dot.row;
                int targetCol = n - 1 - fig.col + dot.col;

                // Bounds check to prevent ArrayIndexOutOfBounds
                if (targetRow >= 0 && targetRow < resultSize && 
                    targetCol >= 0 && targetCol < resultSize) {
                    res[targetRow][targetCol] = '.';
                }
            }
        }
        return res;
    }

    /**
     * Verifies if every 'hit' point is satisfied by the calculated result grid.
     */
    private boolean validateHits(List<Point> hits, List<Point> figures, char[][] res, int n) {
        int resultSize = 2 * n - 1;

        for (Point hit : hits) {
            boolean isHitCovered = false;
            for (Point fig : figures) {
                int targetRow = n - 1 - fig.row + hit.row;
                int targetCol = n - 1 - fig.col + hit.col;

                if (targetRow >= 0 && targetRow < resultSize && 
                    targetCol >= 0 && targetCol < resultSize) {
                    if (res[targetRow][targetCol] == 'x') {
                        isHitCovered = true;
                        break;
                    }
                }
            }

            if (!isHitCovered) {
                return false;
            }
        }
        return true;
    }

    /**
     * Efficiently prints the 2D character array to the console.
     */
    private void printGrid(char[][] grid) {
        StringBuilder sb = new StringBuilder();
        for (char[] row : grid) {
            sb.append(row).append('\n');
        }
        System.out.print(sb.toString());
    }
}

