/**
 * Represents a coordinate point in the grid.
 */
class Point {
    final int row;
    final int col;

    Point(int row, int col) {
        this.row = row;
        this.col = col;
    }
}

/**
 * Contains the logic to solve the pattern matching problem.
 */
class PatternSolver {
    private final FastReader reader;

    public PatternSolver(FastReader reader) {
        this.reader = reader;
    }

    /**
     * Reads the input, processes the pattern, and prints the result.
     */
    public void solve(PrintWriter out) throws IOException {
        int n = reader.nextInt();
        if (n <= 0) return;

        char[][] grid = new char[n][n];
        List<Point> oPoints = new ArrayList<>();

        // 1. Read the input grid and identify all 'o' positions
        for (int i = 0; i < n; i++) {
            String line = reader.next();
            for (int j = 0; j < n; j++) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] == 'o') {
                    oPoints.add(new Point(i, j));
                }
            }
        }

        int resSize = 2 * n - 1;
        char[][] resultGrid = new char[resSize][resSize];
        boolean[][] isCovered = new boolean[n][n];

        // Initialize result grid with '.'
        for (int i = 0; i < resSize; i++) {
            Arrays.fill(resultGrid[i], '.');
        }

        // 2. Evaluate all possible shifts (dx, dy)
        // A shift is valid if no 'o' in the pattern lands on a '.' in the original grid.
        for (int i = 0; i < resSize; i++) {
            for (int j = 0; j < resSize; j++) {
                int dx = i - (n - 1);
                int dy = j - (n - 1);

                if (isValidShift(oPoints, grid, dx, dy, n)) {
                    resultGrid[i][j] = 'x';

                    // Mark which original cells are covered by this valid shift
                    for (Point p : oPoints) {
                        int targetRow = p.row + dx;
                        int targetCol = p.col + dy;
                        if (isInBounds(targetRow, targetCol, n)) {
                            isCovered[targetRow][targetCol] = true;
                        }
                    }
                }
            }
        }

        // Maintain original behavior: setting center of result to 'o'
        resultGrid[n - 1][n - 1] = 'o';

        // 3. Verify if all original 'o' cells are covered by at least one valid shift
        boolean allCovered = true;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 'o' && !isCovered[i][j]) {
                    allCovered = false;
                    break;
                }
            }
            if (!allCovered) break;
        }

        // 4. Output the result
        if (allCovered) {
            out.println("YES");
            for (int i = 0; i < resSize; i++) {
                out.println(new String(resultGrid[i]));
            }
        } else {
            out.println("NO");
        }
    }

    /**
     * Checks if a shift of the 'o' pattern is safe (doesn't hit any '.')
     */
    private boolean isValidShift(List<Point> oPoints, char[][] grid, int dx, int dy, int n) {
        for (Point p : oPoints) {
            int nr = p.row + dx;
            int nc = p.col + dy;
            if (isInBounds(nr, nc, n)) {
                if (grid[nr][nc] == '.') {
                    return false;
                }
            }
        }
        return true;
    }

    private boolean isInBounds(int r, int c, int n) {
        return r >= 0 && r < n && c >= 0 && c < n;
    }
}

/**
 * Efficient input reader.
 */
class FastReader {
    private BufferedReader br;
    private StringTokenizer st;

    public FastReader(InputStream in) {
