/**
 * Represents a coordinate on the grid.
 */
class Point {
    final int row;
    final int col;

    Point(int row, int col) {
        this.row = row;
        this.col = col;
    }
}

/**
 * Contains the logic to calculate and validate the attack pattern.
 */
class PatternSolver {

    public void solve(FastReader in, PrintWriter out) {
        int n = in.nextInt();
        if (n <= 0) return;

        List<Point> oCoordinates = new ArrayList<>();
        List<Point> dotCoordinates = new ArrayList<>();
        List<Point> xCoordinates = new ArrayList<>();

        // 1. Parse input and categorize cell coordinates
        for (int i = 0; i < n; i++) {
            String rowString = in.next();
            for (int j = 0; j < n; j++) {
                char cell = rowString.charAt(j);
                Point p = new Point(i, j);
                if (cell == 'o') {
                    oCoordinates.add(p);
                } else if (cell == '.') {
                    dotCoordinates.add(p);
                } else if (cell == 'x') {
                    xCoordinates.add(p);
                }
            }
        }

        // 2. Build the relative attack pattern
        char[][] attackPattern = buildAttackPattern(n, oCoordinates, dotCoordinates);

        // 3. Validate if the pattern satisfies the requirement for 'x' cells
        if (isPatternValid(xCoordinates, oCoordinates, attackPattern, n)) {
            out.println("YES");
            printGrid(attackPattern, out);
        } else {
            out.println("NO");
        }
    }

    /**
     * Generates a pattern of relative offsets based on 'o' and '.' positions.
     */
    private char[][] buildAttackPattern(int n, List<Point> oCoords, List<Point> dotCoords) {
        int size = 2 * n - 1;
        char[][] pattern = new char[size][size];

        // Initialize pattern with 'x'
        for (int i = 0; i < size; i++) {
            Arrays.fill(pattern[i], 'x');
        }

        // The origin (relative 0,0) is marked as 'o'
        pattern[n - 1][n - 1] = 'o';

        // Calculate relative offsets for all (o, .) pairs and mark as '.'
        for (Point o : oCoords) {
            for (Point dot : dotCoords) {
                int relativeRow = dot.row - o.row;
                int relativeCol = dot.col - o.col;
                pattern[n - 1 + relativeRow][n - 1 + relativeCol] = '.';
            }
        }
        return pattern;
    }

    /**
     * Checks if every 'x' cell in the original field can be represented 
     * by an 'x' offset in the attack pattern relative to an 'o' cell.
     */
    private boolean isPatternValid(List<Point> xCoords, List<Point> oCoords, char[][] pattern, int n) {
        for (Point x : xCoords) {
            boolean hasMatchingOffset = false;
            for (Point o : oCoords) {
                int relativeRow = x.row - o.row;
                int relativeCol = x.col - o.col;

                // Check if the relative offset exists in the pattern as an 'x'
                if (pattern[n - 1 + relativeRow][n - 1 + relativeCol] == 'x') {
                    hasMatchingOffset = true;
                    break;
                }
            }
            if (!hasMatchingOffset) {
                return false;
            }
        }
        return true;
    }

    private void printGrid(char[][] grid, PrintWriter out) {
        for (char[] row : grid) {
            out.println(new String(row));
        }
    }
}

