/**
 * Represents a 2D coordinate in the chess grid.
 * Using a record provides immutability and reduces boilerplate.
 */
record Point(int x, int y) {}

/**
 * ChessSolver encapsulates the logic for calculating piece-to-empty cell 
 * relative offsets and validating target points.
 */
class ChessSolver {
    private final int gridSize;
    private final List<Point> pieces = new ArrayList<>();
    private final List<Point> attackedPoints = new ArrayList<>();
    private final List<Point> emptyCells = new ArrayList<>();

    public ChessSolver(int gridSize) {
        this.gridSize = gridSize;
    }

    /**
     * Populates the lists of points based on the grid character.
     */
    public void addPoint(int r, int c, char type) {
        Point point = new Point(r, c);
        switch (type) {
            case 'o' -> pieces.add(point);
            case 'x' -> attackedPoints.add(point);
            case '.' -> emptyCells.add(point);
        }
    }

    /**
     * Executes the core logic of the program.
     */
    public void solve() {
        int offsetDimension = 2 * gridSize - 1;
        // Represents the set of relative vectors (dx, dy) between pieces and empty cells.
        boolean[][] isOffsetPresent = new boolean[offsetDimension][offsetDimension];

        // Step 1: Calculate all valid relative offsets from pieces to empty cells.
        for (Point piece : pieces) {
            for (Point empty : emptyCells) {
                int dx = empty.x() - piece.x();
                int dy = empty.y() - piece.y();
                // Offset indices are shifted by (gridSize - 1) to handle negative coordinates.
                isOffsetPresent[dx + gridSize - 1][dy + gridSize - 1] = true;
            }
        }

        // Step 2: Validate each 'attacked' point.
        // An attacked point is invalid if ALL pieces relative to it result in an offset 
        // that is already present in the 'isOffsetPresent' set.
        for (Point target : attackedPoints) {
            boolean hasSafePiece = false;
            for (Point piece : pieces) {
                int dx = target.x() - piece.x();
                int dy = target.y() - piece.y();

                if (!isOffsetPresent[dx + gridSize - 1][dy + gridSize - 1]) {
                    hasSafePiece = true;
                    break;
                }
            }

            if (!hasSafePiece) {
                System.out.println("NO");
                return;
            }
        }

        // Step 3: If all points are valid, output the resulting offset grid.
        printResultGrid(isOffsetPresent, offsetDimension);
    }

    /**
     * Formats and prints the final grid.
     */
    private void printResultGrid(boolean[][] isOffsetPresent, int dimension) {
        System.out.println("YES");
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < dimension; i++) {
            for (int j = 0; j < dimension; j++) {
                // The origin (0,0 offset) is conceptually the center of the new grid.
                if (i == gridSize - 1 && j == gridSize - 1) {
                    sb.append('o');
                } else if (isOffsetPresent[i][j]) {
                    sb.append('.');
                } else {
                    sb.append('x');
                }
            }
            sb.append('\n');
        }
        System.out.print(sb.toString());
    }
}

/**
 * Main entry point for the Chess program.
 */
public class Chess {
    public static void main(String[] args) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String firstLine = reader.readLine();
            if (firstLine == null) return;

