        } catch (IOException | NumberFormatException e) {
            // Error handling could be expanded for production use.
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Main entry point for the application.
 * Orchestrates the input, processing, and output phases.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            ProblemSolver solver = new ProblemSolver(reader);
            solver.solve(writer);
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Represents a 2D coordinate on a grid.
     */
    static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Contains the core logic for processing the grid and validating the pattern.
     */
    static class ProblemSolver {
        private final FastReader reader;

        ProblemSolver(FastReader reader) {
            this.reader = reader;
        }

        /**
         * Executes the solving logic.
         * @param out The PrintWriter used for output.
         */
        public void solve(PrintWriter out) {
            int gridSize = reader.nextInt();
            if (gridSize <= 0) return;

            char[][] inputGrid = readGrid(gridSize);
            List<Point> origins = findPointsByChar(inputGrid, 'o');
            char[][] expandedGrid = buildExpandedGrid(gridSize, inputGrid, origins);

            if (validatePattern(gridSize, inputGrid, origins, expandedGrid)) {
                out.println("YES");
                printGrid(out, expandedGrid);
            } else {
                out.println("NO");
            }
        }

        private char[][] readGrid(int size) {
            char[][] grid = new char[size][];
            for (int i = 0; i < size; i++) {
                grid[i] = reader.next().toCharArray();
            }
            return grid;
        }

        private List<Point> findPointsByChar(char[][] grid, char target) {
            List<Point> points = new ArrayList<>();
            for (int i = 0; i < grid.length; i++) {
                for (int j = 0; j < grid[i].length; j++) {
                    if (grid[i][j] == target) {
                        points.add(new Point(i, j));
                    }
                }
            }
            return points;
        }

        /**
         * Constructs the expanded (2n-1)x(2n-1) grid based on relative offsets.
         */
        private char[][] buildExpandedGrid(int n, char[][] inputGrid, List<Point> origins) {
            int expandedSize = 2 * n - 1;
            char[][] expandedGrid = new char[expandedSize][expandedSize];

            // Initialize the expanded grid with 'x'
            for (int i = 0; i < expandedSize; i++) {
                Arrays.fill(expandedGrid[i], 'x');
            }

            // Set the central point to 'o'
            expandedGrid[n - 1][n - 1] = 'o';

            // For every '.' in the input, mark the relative positions from every 'o' as '.' in the expanded grid
            List<Point> dots = findPointsByChar(inputGrid, '.');
            for (Point dot : dots) {
                for (Point origin : origins) {
                    int rowOffset = dot.row - origin.row + (n - 1);
                    int colOffset = dot.col - origin.col + (n - 1);
                    expandedGrid[rowOffset][colOffset] = '.';
                }
            }
            return expandedGrid;
        }

        /**
         * Validates if every 'x' in the input grid is supported by an 'x' in the expanded grid.
         */
        private boolean validatePattern(int n, char[][] inputGrid, List<Point> origins, char[][] expandedGrid) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (inputGrid[i][j] == 'x') {
                        if (!isXCovered(i, j, n, origins, expandedGrid)) {
                            return false;
                        }
                    }
                }
            }
            return true;
        }

        private boolean isXCovered(int row, int col, int n, List<Point> origins, char[][] expandedGrid) {
            for (Point origin : origins) {
                int rowOffset = row - origin.row + (n - 1);
                int colOffset = col - origin.col + (n - 1);
                if (expandedGrid[rowOffset][colOffset] == 'x') {
                    return true;
                }
            }
            return false;
        }

        private void printGrid(PrintWriter out, char[][] grid) {
            for (char[] row : grid) {
                out.println(row);
            }
        }
    }

    /**
     * Utility class for fast input parsing.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A program to determine if a specific attack pattern can cover all required 
 * 'x' cells on a grid without hitting any '.' cells.
 */
public class Main {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        AttackPatternSolver solver = new AttackPatternSolver(scanner);
        solver.solve();
    }

    /**
     * Result container for the pattern solving process.
     */
    static class SolveResult {
        final boolean isPossible;
        final boolean[][] pattern;

        SolveResult(boolean isPossible, boolean[][] pattern) {
            this.isPossible = isPossible;
            this.pattern = pattern;
        }
    }

    /**
     * Handles the core logic of finding and validating the attack pattern.
     */
    static class AttackPatternSolver {
        private final int gridSize;
        private final char[][] grid;
        private final FastScanner scanner;

        public AttackPatternSolver(FastScanner scanner) {
            this.scanner = scanner;
            this.gridSize = scanner.nextInt();
            this.grid = new char[gridSize][gridSize];
            for (int i = 0; i < gridSize; i++) {
                grid[i] = scanner.next().toCharArray();
            }
        }

        public void solve() {
            SolveResult result = computePattern();

            if (result.isPossible) {
                System.out.println("YES");
                printPattern(result.pattern);
            } else {
                System.out.println("NO");
            }
        }

        private SolveResult computePattern() {
            int offset = gridSize - 1;
            int patternSize = 2 * gridSize - 1;

            // Step 1: Determine the valid attack pattern.
            // A pattern offset is invalid if applying it to any 'o' results in hitting a '.'
            boolean[][] attackPattern = new boolean[patternSize][patternSize];
            for (boolean[] row : attackPattern) {
                Arrays.fill(row, true);
            }

            for (int r = 0; r < gridSize; r++) {
                for (int c = 0; c < gridSize; c++) {
                    if (grid[r][c] == 'o') {
                        invalidateOffsetsHittingDots(r, c, offset, attackPattern);
                    }
                }
            }

            // Step 2: Check if the derived pattern covers all 'x' cells.
            boolean[][] coverageMap = calculateCoverage(attackPattern, offset);
            if (verifyRequiredCoverage(coverageMap)) {
                return new SolveResult(true, attackPattern);
            } else {
                return new SolveResult(false, null);
            }
        }

        private void invalidateOffsetsHittingDots(int r, int c, int offset, boolean[][] pattern) {
            for (int dr = -offset; dr <= offset; dr++) {
                for (int dc = -offset; dc <= offset; dc++) {
                    int targetRow = r + dr;
                    int targetCol = c + dc;

                    if (isInBounds(targetRow, targetCol) && grid[targetRow][targetCol] == '.') {
                        pattern[dr + offset][dc + offset] = false;
                    }
                }
            }
        }

        private boolean[][] calculateCoverage(boolean[][] pattern, int offset) {
            int patternSize = pattern.length;
            boolean[][] coverageMap = new boolean[gridSize][gridSize];

            for (int r = 0; r < gridSize; r++) {
                for (int c = 0; c < gridSize; c++) {
                    if (grid[r][c] == 'o') {
                        applyPatternToCoverage(r, c, pattern, offset, coverageMap);
                    }
                }
            }
            return coverageMap;
        }

        private void applyPatternToCoverage(int r, int c, boolean[][] pattern, int offset, boolean[][] coverageMap) {
            for (int dr = -offset; dr <= offset; dr++) {
                for (int dc = -offset; dc <= offset; dc++) {
                    if (pattern[dr + offset][dc + offset]) {
                        int targetRow = r + dr;
                        int targetCol = c + dc;
                        if (isInBounds(targetRow, targetCol)) {
                            coverageMap[targetRow][targetCol] = true;
                        }
                    }
                }
            }
        }

        private boolean verifyRequiredCoverage(boolean[][] coverageMap) {
            for (int r = 0; r < gridSize; r++) {
                for (int c = 0; c < gridSize; c++) {
                    if (grid[r][c] == 'x' && !coverageMap[r][c]) {
                        return false;
                    }
                }
            }
            return true;
        }

        private boolean isInBounds(int r, int c) {
            return r >= 0 && r < gridSize && c >= 0 && c < gridSize;
        }

        private void printPattern(boolean[][] pattern) {
            int patternSize = pattern.length;
            int center = gridSize - 1;

            for (int i = 0; i < patternSize; i++) {
                StringBuilder sb = new StringBuilder();
                for (int j = 0; j < patternSize; j++) {
                    if (i == center && j == center) {
                        sb.append('o');
                    } else {
                        sb.append(pattern[i][j] ? 'x' : '.');
                    }
                }
                System.out.println(sb.toString());
            }
        }
    }

    /**
     * High-performance input reader.
     */
    static class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int curChar;
        private int numChars;

        public FastScanner(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (numChars == -1) throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buffer);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) return -1;
            }
            return buffer[curChar++];
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * A solver that expands a pattern based on relative offsets from source points ('o').
 * It validates if the original obstacles ('x') are preserved in the expanded grid.
 */
public class PatternExpansionSolver {

    /**
     * Represents the possible states of a cell in the grid.
     */
    private enum CellType {
        EMPTY('.', 0),
        OBSTACLE('x', 1),
        SOURCE('o', 2);

        final char symbol;
        final int value;

        CellType(char symbol, int value) {
            this.symbol = symbol;
            this.value = value;
        }

        static CellType fromChar(char c) {
            if (c == '.') return EMPTY;
            if (c == 'x') return OBSTACLE;
            if (c == 'o') return SOURCE;
            throw new IllegalArgumentException("Unknown character: " + c);
        }

        static CellType fromValue(int value) {
            if (value == 0) return EMPTY;
            if (value == 1) return OBSTACLE;
            if (value == 2) return SOURCE;
            throw new IllegalArgumentException("Unknown value: " + value);
        }
    }

    /**
     * Simple container for 2D coordinates.
     */
    private record Point(int row, int col) {}

    private final int gridSize;
    private final CellType[][] inputGrid;
    private final List<Point> sourcePositions = new ArrayList<>();
    private final List<Point> obstaclePositions = new ArrayList<>();
    private final List<Point> emptyPositions = new ArrayList<>();

    public PatternExpansionSolver(int gridSize, CellType[][] inputGrid) {
        this.gridSize = gridSize;
        this.inputGrid = inputGrid;
        identifyCellPositions();
    }

    /**
     * Scans the input grid to categorize points for faster processing.
     */
    private void identifyCellPositions() {
        for (int r = 0; r < gridSize; r++) {
            for (int c = 0; c < gridSize; c++) {
                Point p = new Point(r, c);
                switch (inputGrid[r][c]) {
                    case SOURCE -> sourcePositions.add(p);
                    case OBSTACLE -> obstaclePositions.add(p);
                    case EMPTY -> emptyPositions.add(p);
                }
            }
        }
    }

    /**
     * Executes the core logic of the pattern expansion and validation.
     */
    public void solve() {
        int expandedSize = 2 * gridSize - 1;
        int mid = gridSize - 1;
        CellType[][] expandedGrid = initializeExpandedGrid(expandedSize, mid);

        applyEmptyCellEffects(expandedGrid, mid);

        if (validateObstaclePersistence(expandedGrid, mid)) {
            printResult(true, expandedGrid);
        } else {
            printResult(false, null);
        }
    }

    /**
     * Creates a new grid filled with Obstacles, with the center marked as a Source.
     */
    private CellType[][] initializeExpandedGrid(int size, int mid) {
        CellType[][] grid = new CellType[size][size];
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                grid[i][j] = CellType.OBSTACLE;
            }
        }
        grid[mid][mid] = CellType.SOURCE;
        return grid;
    }

    /**
     * For every empty cell in the input, maps its relative position from 
     * every source to the expanded grid.
     */
    private void applyEmptyCellEffects(CellType[][] expandedGrid, int mid) {
        for (Point emptyPt : emptyPositions) {
            for (Point sourcePt : sourcePositions) {
                int rowOffset = emptyPt.row() - sourcePt.row();
                int colOffset = emptyPt.col() - sourcePt.col();
                expandedGrid[mid + rowOffset][mid + colOffset] = CellType.EMPTY;
            }
        }
    }

    /**
     * Checks if every obstacle in the original grid has at least one 
     * relative position in the expanded grid that remains an obstacle.
     */
    private boolean validateObstaclePersistence(CellType[][] expandedGrid, int mid) {
        for (Point obsPt : obstaclePositions) {
            boolean isPreserved = false;
            for (Point sourcePt : sourcePositions) {
                int rowOffset = obsPt.row() - sourcePt.row();
                int colOffset = obsPt.col() - sourcePt.col();

                if (expandedGrid[mid + rowOffset][mid + colOffset] == CellType.OBSTACLE) {
                    isPreserved = true;
                    break;
                }
            }
            if (!isPreserved) return false;
        }
        return true;
    }

    /**
     * Handles the output of the result.
     */
    private void printResult(boolean success, CellType[][] grid) {
        if (!success) {
            System.out.println("NO");
            return;
        }

        System.out.println("YES");
        StringBuilder sb = new StringBuilder();
        for (CellType[] row : grid) {
            for (CellType cell : row) {
                sb.append(cell.symbol);
            }
            sb.append("\n");
        }
        System.out.print(sb.toString());
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int n = scanner.nextInt();
        CellType[][] grid = new CellType[n][n];

        for (int i = 0; i < n; i++) {
            String line = scanner.next();
            for (int j = 0; j < n; j++) {
                grid[i][j] = CellType.fromChar(line.charAt(j));
            }
        }

        PatternExpansionSolver solver = new PatternExpansionSolver(n, grid);
        solver.solve();

        scanner.close();
    }
}

