    }

    public String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                return null;
            }
        }
        return tokenizer.nextToken();
    }

    public int nextInt() {
        String token = next();
        if (token == null) throw new NoSuchElementException("Unexpected end of input.");
        return Integer.parseInt(token);
    }
}

/**
 * Encapsulates the logic to solve the grid-based pattern problem.
 */
class GridProblemSolver {
    private static final char CHAR_O = 'o';
    private static final char CHAR_X = 'x';
    private static final char CHAR_DOT = '.';

    /**
     * Represents a 2D coordinate in the grid.
     */
    private record Point(int row, int col) {}

    /**
     * Reads input, processes the grid, and outputs the result.
     * 
     * @param in  The input scanner.
     * @param out The output writer.
     */
    public void solve(FastScanner in, PrintWriter out) {
        int n = in.nextInt();
        if (n <= 0) return;

        List<Point> oPositions = new ArrayList<>();
        List<Point> xPositions = new ArrayList<>();
        List<Point> dotPositions = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            String line = in.next();
            for (int j = 0; j < n; j++) {
                char cell = line.charAt(j);
                Point p = new Point(i, j);
                if (cell == CHAR_O) {
                    oPositions.add(p);
                } else if (cell == CHAR_X) {
                    xPositions.add(p);
                } else if (cell == CHAR_DOT) {
                    dotPositions.add(p);
                }
            }
        }

        // Step 1: Determine which relative offsets are valid.
        // An offset is invalid if it maps an 'o' to a '.'
        boolean[][] validOffsets = calculateValidOffsets(n, oPositions, dotPositions);

        // Step 2: Check if all 'x' cells are covered by an 'o' using valid offsets.
        if (isAllXCovered(xPositions, oPositions, n, validOffsets)) {
            out.println("YES");
            printResultPattern(n, validOffsets, out);
        } else {
            out.println("NO");
        }
    }

    /**
     * Calculates the boolean matrix of valid relative offsets.
     */
    private boolean[][] calculateValidOffsets(int n, List<Point> oPositions, List<Point> dotPositions) {
        // The offset range is from -(n-1) to (n-1). 
        // We use a 2n+1 size array to accommodate indexing via (offset + n).
        boolean[][] validOffsets = new boolean[2 * n + 1][2 * n + 1];

        // Initialize all non-zero offsets as true.
        for (int dr = -n; dr <= n; dr++) {
            for (int dc = -n; dc <= n; dc++) {
                if (dr != 0 || dc != 0) {
                    validOffsets[dr + n][dc + n] = true;
                }
            }
        }

        // Mark offsets that land on a '.' from an 'o' as false.
        for (Point o : oPositions) {
            for (Point dot : dotPositions) {
                int dr = dot.row() - o.row();
                int dc = dot.col() - o.col();
                validOffsets[dr + n][dc + n] = false;
            }
        }
        return validOffsets;
    }

    /**
     * Verifies if every 'x' position can be reached from at least one 'o' 
     * using a valid relative offset.
     */
    private boolean isAllXCovered(List<Point> xPositions, List<Point> oPositions, int n, boolean[][] validOffsets) {
        for (Point x : xPositions) {
            boolean covered = false;
            for (Point o : oPositions) {
                int dr = x.row() - o.row();
                int dc = x.col() - o.col();

                // Check if the offset is within bounds and marked as valid.
                if (dr + n >= 0 && dr + n < 2 * n + 1 && dc + n >= 0 && dc + n < 2 * n + 1) {
                    if (validOffsets[dr + n][dc + n]) {
                        covered = true;
                        break;
                    }
                }
            }
            if (!covered) return false;
        }
        return true;
    }

    /**
     * Prints the required (2n-1) x (2n-1) pattern based on valid offsets.
     */
    private void printResultPattern(int n, boolean[][] validOffsets, PrintWriter out) {
        for (int i = 1; i < 2 * n; i++) {
            for (int j = 1; j < 2 * n; j++) {
                if (i == n && j == n) {
                    out.print(CHAR_O);
                } else {
                    out.print(validOffsets[i][j] ? CHAR_X : CHAR_DOT);
                }
            }
            out.println();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solution to determine if a specific pattern shift can cover all required cells.
 */
public class GridShiftSolver {

    private static final char CELL_O = 'o';
    private static final char CELL_X = 'x';
    private static final char CELL_DOT = '.';

    private InputReader reader;
    private OutputWriter writer;

    public static void main(String[] args) {
        try {
            new GridShiftSolver().solve();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /**
     * Orchestrates the main logic of the program.
     */
    public void solve() throws IOException {
        reader = new InputReader("__std");
        writer = new OutputWriter("__std");

        int gridSize = reader.readInt();
        char[][] inputGrid = new char[gridSize][];
        for (int i = 0; i < gridSize; i++) {
            inputGrid[i] = reader.readToken().toCharArray();
        }

        int outputSize = 2 * gridSize - 1;
        char[][] outputGrid = initializeGrid(outputSize, CELL_DOT);
        boolean[][] coveredCells = new boolean[gridSize][gridSize];

        // Iterate through all possible relative shifts
        for (int rowShift = 1 - gridSize; rowShift < gridSize; rowShift++) {
            for (int colShift = 1 - gridSize; colShift < gridSize; colShift++) {

                if (isValidShift(inputGrid, gridSize, rowShift, colShift)) {
                    // Mark this shift in the output grid
                    outputGrid[rowShift + gridSize - 1][colShift + gridSize - 1] = CELL_X;

                    // Update the mask of covered cells
                    markCoveredCells(inputGrid, coveredCells, gridSize, rowShift, colShift);
                }
            }
        }

        if (areAllRequiredCellsCovered(inputGrid, coveredCells, gridSize)) {
            outputGrid[gridSize - 1][gridSize - 1] = CELL_O;
            writer.println("YES");
            for (char[] row : outputGrid) {
                writer.println(new String(row));
            }
        } else {
            writer.println("NO");
        }

        writer.close();
    }

    private char[][] initializeGrid(int size, char defaultChar) {
        char[][] grid = new char[size][size];
        for (int i = 0; i < size; i++) {
            Arrays.fill(grid[i], defaultChar);
        }
        return grid;
    }

    /**
     * Checks if a shift is valid. A shift is valid if every 'o' cell, 
     * when shifted, lands on a non-'.' cell in the original grid.
     */
    private boolean isValidShift(char[][] grid, int n, int rowShift, int colShift) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == CELL_O) {
                    int targetRow = i + rowShift;
                    int targetCol = j + colShift;

                    if (isWithinBounds(targetRow, targetCol, n)) {
                        if (grid[targetRow][targetCol] == CELL_DOT) {
                            return false;
                        }
                    }
                }
            }
        }
        return true;
    }

    /**
     * Marks cells in the mask that are covered by the 'o' pattern under the current shift.
     */
    private void markCoveredCells(char[][] grid, boolean[][] mask, int n, int rowShift, int colShift) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == CELL_O) {
                    int targetRow = i + rowShift;
                    int targetCol = j + colShift;
                    if (isWithinBounds(targetRow, targetCol, n)) {
                        mask[targetRow][targetCol] = true;
                    }
                }
            }
        }
    }

    /**
     * Ensures that every 'x' in the original grid is covered by at least one valid shift.
     */
    private boolean areAllRequiredCellsCovered(char[][] grid, boolean[][] mask, int n) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == CELL_X) {
                    if (!mask[i][j]) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    private boolean isWithinBounds(int r, int c, int n) {
        return r >= 0 && r < n && c >= 0 && c < n;
    }

    /**
     * Fast I/O Utility for reading input.
     */
    class InputReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int pos, len, cur;
        private final StringBuilder sb = new StringBuilder(32);

        InputReader(String name) throws IOException {
            this.stream = name.equals("__std") ? System.in : new FileInputStream(name);
            this.cur = read();
        }

        private int read() throws IOException {
            if (len == -1) throw new EOFException();
            if (pos >= len) {
                pos = 0;
                len = stream.read(buffer);
                if (len == -1) return -1;
            }
            return buffer[pos++];
        }

        private boolean isWhitespace(int c) {
            return c == ' ' || c == '\t' || c == '\r' || c == '\n' || c == -1;
        }

        int readInt() throws IOException {
            while (isWhitespace(cur)) cur = read();
            if (cur == -1) throw new EOFException();
            int sign = 1;
            if (cur == '-') {
                sign = -1;
                cur = read();
            }
            int res = 0;
            while (!isWhitespace(cur)) {
                if (cur < '0' || cur > '9') throw new NumberFormatException();
                res = res * 10 + (cur - '0');
                cur = read();
            }
            return res * sign;
        }

        String readToken() throws IOException {
            while (isWhitespace(cur)) cur = read();
            if (cur == -1) throw new EOFException();
            sb.setLength(0);
            while (!isWhitespace(cur)) {
                sb.append((char) cur);
                cur = read();
            }
            return sb.toString();
        }
    }

    /**
     * Fast I/O Utility for writing output.
     */
    class OutputWriter {
        private final PrintWriter writer;

        OutputWriter(String name) throws IOException {
            this.writer = name.equals("__std") ? new PrintWriter(System.out) : new PrintWriter(name);
        }

        void println(Object value) {
            writer.println(value);
        }

        void close() {
            writer.close();
        }
    }
}

