/**
 * Solves the grid pattern problem by finding valid offsets and checking coverage.
 */
class GridPatternSolver {
    private static final char EMPTY = '.';
    private static final char TARGET = 'o';
    private static final char BLOCKER = 'x';

    private final FastReader reader;

    public GridPatternSolver(FastReader reader) {
        this.reader = reader;
    }

    /**
     * Orchestrates the solving process.
     */
    public void solve(PrintWriter out) throws IOException {
        int n = reader.nextInt();
        char[][] inputGrid = readGrid(n);

        boolean[][] xIsCovered = new boolean[n][n];
        char[][] resultGrid = generateEmptyResultGrid(n);

        // Iterate through all possible relative offsets (di, dj)
        for (int rowOffset = -n + 1; rowOffset < n; rowOffset++) {
            for (int colOffset = -n + 1; colOffset < n; colOffset++) {
                if (isOffsetValid(inputGrid, n, rowOffset, colOffset)) {
                    processValidOffset(inputGrid, n, resultGrid, xIsCovered, rowOffset, colOffset);
                }
            }
        }

        if (allBlockersCovered(inputGrid, n, xIsCovered)) {
            out.println("YES");
            printGrid(resultGrid, out);
        } else {
            out.println("NO");
        }
    }

    private char[][] readGrid(int n) throws IOException {
        char[][] grid = new char[n][n];
        for (int i = 0; i < n; i++) {
            grid[i] = reader.next().toCharArray();
        }
        return grid;
    }

    private char[][] generateEmptyResultGrid(int n) {
        int size = 2 * n - 1;
        char[][] grid = new char[size][size];
        for (int i = 0; i < size; i++) {
            Arrays.fill(grid[i], EMPTY);
        }
        // The origin point in the result grid is always the 'o' target
        grid[n - 1][n - 1] = TARGET;
        return grid;
    }

    /**
     * Checks if an offset is valid: moving all 'o' targets must not land on an empty '.' cell.
     */
    private boolean isOffsetValid(char[][] grid, int n, int dr, int dc) {
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == TARGET) {
                    int targetRow = r + dr;
                    int targetCol = c + dc;

                    if (isWithinBounds(n, targetRow, targetCol) && grid[targetRow][targetCol] == EMPTY) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    /**
     * Updates the result grid and tracks which 'x' blockers are covered by this offset.
     */
    private void processValidOffset(char[][] grid, int n, char[][] resultGrid, boolean[][] xIsCovered, int dr, int dc) {
        // If the offset is not the origin, mark it in the result grid
        if (dr != 0 || dc != 0) {
            resultGrid[dr + n - 1][dc + n - 1] = BLOCKER;
        }

        // Track which blockers in the original grid are covered by a target landing on them
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == TARGET) {
                    int targetRow = r + dr;
                    int targetCol = c + dc;

                    if (isWithinBounds(n, targetRow, targetCol) && grid[targetRow][targetCol] == BLOCKER) {
                        xIsCovered[targetRow][targetCol] = true;
                    }
                }
            }
        }
    }

    private boolean isWithinBounds(int n, int r, int c) {
        return r >= 0 && r < n && c >= 0 && c < n;
    }

    private boolean allBlockersCovered(char[][] grid, int n, boolean[][] xIsCovered) {
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == BLOCKER && !xIsCovered[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    private void printGrid(char[][] grid, PrintWriter out) {
        for (char[] row : grid) {
            out.println(new String(row));
        }
    }
}

/**
 * Optimized utility for fast input reading.
 */
class FastReader {
    private final InputStream inputStream;
    private final byte[] buffer = new byte[1024];
    private int pointer = 0;
    private int bufferLength = 0;

    public FastReader(InputStream inputStream) {
        this.inputStream = inputStream;
    }

    private byte read() throws IOException {
        if (pointer >= bufferLength) {
            pointer = 0;
            bufferLength = inputStream.read(buffer);
            if (bufferLength <= 0) return -1;
        }
        return buffer[pointer++];
    }

    public int nextInt() throws IOException {
        int c = read();
        while (c >= 0 && c <= 32) c = read();
        if (c == -1) throw new IOException("Unexpected EOF");

        int neg = 1;
        if (c == '-') {
            neg = -1;
            c = read();
        }

        int res = 0;
        while (c >= '0' && c <= '9') {
            res = res * 10 + (c - '0');
            c = read();
        }
        return res * neg;
    }

    public String next() throws IOException {
        int c = read();
        while (c >= 0 && c <= 32) c = read();
        if (c == -1) return null;

        StringBuilder sb = new StringBuilder();
        while (c > 32) {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }
}

import java.util.*;
import java.io.*;

/**
 * A program to find valid shifts of a pattern ('o') in a grid such that
 * all target cells ('x') are covered without overlapping empty cells ('.').
 */
public class PatternMatcher {

    private static final int CELL_EMPTY = 0;
    private static final int CELL_TARGET = 1;
    private static final int CELL_ORIGIN = 2;

    public static void main(String[] args) {
        new PatternMatcher().run();
    }

    public void run() {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);
        try {
            solve(reader, writer);
        } catch (IOException e) {
            System.err.println("An error occurred during execution: " + e.getMessage());
        } finally {
            writer.close();
        }
    }

    private void solve(FastReader reader, PrintWriter writer) throws IOException {
        int n = reader.nextInt();
        int[][] grid = new int[n][n];
        List<Point> originPoints = new ArrayList<>();

        // 1. Parse Input
        for (int i = 0; i < n; i++) {
            String line = reader.next();
            for (int j = 0; j < n; j++) {
                char c = line.charAt(j);
                if (c == '.') {
                    grid[i][j] = CELL_EMPTY;
                } else if (c == 'x') {
                    grid[i][j] = CELL_TARGET;
                } else if (c == 'o') {
                    grid[i][j] = CELL_ORIGIN;
                    originPoints.add(new Point(i, j));
                }
            }
        }

        int[][] shiftResultGrid = new int[2 * n - 1][2 * n - 1];
        boolean[][] isTargetCovered = new boolean[n][n];

        // 2. Iterate through all possible shifts (dr, dc)
        // Shift range: -(n-1) to (n-1)
        for (int dr = -n + 1; dr < n; dr++) {
            for (int dc = -n + 1; dc < n; dc++) {
                if (isShiftValid(grid, originPoints, dr, dc, n)) {
                    // Mark this shift position in the output grid
                    shiftResultGrid[dr + n - 1][dc + n - 1] = CELL_TARGET;
                    // Mark which 'x' cells are covered by this valid shift
                    markCoveredCells(grid, originPoints, dr, dc, n, isTargetCovered);
                }
            }
        }

        // 3. Verification and Output
        if (areAllTargetsCovered(grid, isTargetCovered, n)) {
            writer.println("YES");
            printExpandedGrid(writer, shiftResultGrid, n);
        } else {
            writer.println("NO");
        }
    }

    /**
     * A shift is valid if no 'o' in the pattern lands on a '.' cell.
     */
    private boolean isShiftValid(int[][] grid, List<Point> origins, int dr, int dc, int n) {
        for (Point p : origins) {
            int nr = p.r + dr;
            int nc = p.c + dc;

            // If the shifted origin is within bounds, check if it hits an empty cell
            if (nr >= 0 && nr < n && nc >= 0 && nc < n) {
                if (grid[nr][nc] == CELL_EMPTY) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Marks cells in the original grid as covered by the shifted pattern.
     */
    private void markCoveredCells(int[][] grid, List<Point> origins, int dr, int dc, int n, boolean[][] isTargetCovered) {
        for (Point p : origins) {
            int nr = p.r + dr;
            int nc = p.c + dc;
            if (nr >= 0 && nr < n && nc >= 0 && nc < n) {
                isTargetCovered[nr][nc] = true;
            }
        }
    }

    /**
     * Checks if every 'x' cell in the original grid has been covered.
     */
    private boolean areAllTargetsCovered(int[][] grid, boolean[][] isTargetCovered, int n) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == CELL_TARGET && !isTargetCovered[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Constructs and prints the final expanded grid.
     */
    private void printExpandedGrid(PrintWriter writer, int[][] shiftResultGrid, int n) {
        // The problem specifies placing an 'o' at the center of the expanded grid
        shiftResultGrid[n - 1][n - 1] = CELL_ORIGIN;

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < 2 * n - 1; i++) {
            for (int j = 0; j < 2 * n - 1; j++) {
                switch (shiftResultGrid[i][j]) {
                    case CELL_TARGET -> sb.append('x');
                    case CELL_ORIGIN -> sb.append('o');
                    default -> sb.append('.');
                }
            }
            sb.append('\n');
        }
        writer.print(sb.toString());
    }

    private static class Point {
        final int r, c;
        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Fast I/O utility class.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * GridPatternSolver solves a pattern-matching problem on a 2D grid.
 * The goal is to find all valid shifts of a pattern 'o' such that:
 * 1. No 'o' cell lands on a '.' cell.
 * 2. All 'x' cells in the original grid are "attacked" (covered) by at least one valid shift.
 */
public class GridPatternSolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        // Process all test cases until end of input
        while (true) {
            String firstToken = reader.next();
            if (firstToken == null) {
                break;
            }

            try {
                int n = Integer.parseInt(firstToken);
                char[][] grid = new char[n][n];
                for (int i = 0; i < n; i++) {
                    grid[i] = reader.next().toCharArray();
                }

                solve(n, grid, writer);
            } catch (NumberFormatException e) {
                break;
            }
        }
        writer.flush();
        writer.close();
    }

    /**
     * Performs the core logic for a single test case.
     */
    private static void solve(int n, char[][] grid, PrintWriter writer) {
        boolean[][] isCellAttacked = new boolean[n][n];
        boolean[][] isValidShift = new boolean[2 * n - 1][2 * n - 1];

        // Optimization: Pre-locate all 'o' cells to avoid O(N^2) scanning inside the offset loops
        List<int[]> oPositions = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 'o') {
                    oPositions.add(new int[]{i, j});
                }
            }
        }

        // Iterate through all possible relative shifts (rowOffset, colOffset)
        // The range for offsets is [-(n-1), n-1]
        for (int rowOffset = -n + 1; rowOffset < n; rowOffset++) {
            for (int colOffset = -n + 1; colOffset < n; colOffset++) {
                if (checkIsShiftValid(rowOffset, colOffset, n, grid, oPositions)) {
                    // Map offset range [-n+1, n-1] to array index [0, 2n-2]
                    isValidShift[rowOffset + n - 1][colOffset + n - 1] = true;
                    markAttackedCells(rowOffset, colOffset, n, oPositions, isCellAttacked);
                }
            }
        }

        if (validateAllXAreCovered(n, grid, isCellAttacked)) {
            writer.println("YES");
            printResultGrid(n, isValidShift, writer);
        } else {
            writer.println("NO");
        }
    }

    /**
     * Checks if a specific shift is valid (none of the 'o' cells land on a '.').
     */
    private static boolean checkIsShiftValid(int dr, int dc, int n, char[][] grid, List<int[]> oPositions) {
        for (int[] pos : oPositions) {
            int targetRow = pos[0] + dr;
            int targetCol = pos[1] + dc;

            // A shift is invalid if a source 'o' lands on a '.' cell
            if (targetRow >= 0 && targetRow < n && targetCol >= 0 && targetCol < n) {
                if (grid[targetRow][targetCol] == '.') {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Marks cells as 'attacked' if they are covered by a valid shift.
     */
    private static void markAttackedCells(int dr, int dc, int n, List<int[]> oPositions, boolean[][] isCellAttacked) {
        for (int[] pos : oPositions) {
            int targetRow = pos[0] + dr;
            int targetCol = pos[1] + dc;

            if (targetRow >= 0 && targetRow < n && targetCol >= 0 && targetCol < n) {
                isCellAttacked[targetRow][targetCol] = true;
            }
        }
    }

    /**
     * Checks if every 'x' cell in the original grid has been attacked.
     */
    private static boolean validateAllXAreCovered(int n, char[][] grid, boolean[][] isCellAttacked) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 'x' && !isCellAttacked[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Outputs the grid of valid shifts.
     */
    private static void printResultGrid(int n, boolean[][] isValidShift, PrintWriter writer) {
        for (int i = 0; i < isValidShift.length; i++) {
            for (int j = 0; j < isValidShift[i].length; j++) {
                // The center of the result grid (offset 0,0) is conventionally marked 'o'
                if (i == n - 1 && j == n - 1) {
                    writer.print('o');
                } else if (isValidShift[i][j]) {
                    writer.print('x');
                } else {
                    writer.print('.');
                }
            }
            writer.println();
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
