import java.util.Arrays;
import java.util.List;
import java.util.StringTokenizer;

/**
 * WeirdChess solver handles the logic of calculating valid shifts 
 * on a chessboard-style grid.
 */
public class WeirdChess {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        try {
            int n = reader.nextInt();
            char[][] board = new char[n][n];
            List<Position> piecePositions = new ArrayList<>();

            for (int i = 0; i < n; i++) {
                String line = reader.next();
                board[i] = line.toCharArray();
                for (int j = 0; j < n; j++) {
                    if (board[i][j] == 'o') {
                        piecePositions.add(new Position(i, j));
                    }
                }
            }

            ChessSolver solver = new ChessSolver(n, board, piecePositions);
            solver.solve();

        } catch (Exception e) {
            // In a real-world scenario, use a logger
            e.printStackTrace();
        }
    }

    /**
     * Represents a coordinate on the grid.
     */
    static class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Encapsulates the logic for solving the Weird Chess problem.
     */
    static class ChessSolver {
        private final int boardSize;
        private final char[][] inputBoard;
        private final List<Position> piecePositions;

        public ChessSolver(int boardSize, char[][] inputBoard, List<Position> piecePositions) {
            this.boardSize = boardSize;
            this.inputBoard = inputBoard;
            this.piecePositions = piecePositions;
        }

        public void solve() {
            int resultSize = 2 * boardSize - 1;
            char[][] resultGrid = new char[resultSize][resultSize];
            for (char[] row : resultGrid) {
                Arrays.fill(row, '.');
            }

            boolean[][] coverageMask = new boolean[boardSize][boardSize];

            // Iterate through all possible shifts (dx, dy)
            for (int dx = -boardSize + 1; dx < boardSize; dx++) {
                for (int dy = -boardSize + 1; dy < boardSize; dy++) {
                    if (isShiftValid(dx, dy)) {
                        applyShift(dx, dy, resultGrid, coverageMask);
                    }
                }
            }

            // Place the center piece
            resultGrid[boardSize - 1][boardSize - 1] = 'o';

            if (isFinalStateValid(coverageMask)) {
                System.out.println("YES");
                printGrid(resultGrid);
            } else {
                System.out.println("NO");
            }
        }

        /**
         * Checks if a specific shift results in any piece landing on an empty '.' cell.
         */
        private boolean isShiftValid(int dx, int dy) {
            for (Position p : piecePositions) {
                int nx = p.row + dx;
                int ny = p.col + dy;

                // If the piece lands within the board, it must not land on an empty cell
                if (nx >= 0 && nx < boardSize && ny >= 0 && ny < boardSize) {
                    if (inputBoard[nx][ny] == '.') {
                        return false;
                    }
                }
            }
            return true;
        }

        /**
         * Updates the result grid and the coverage mask if a shift is valid.
         */
        private void applyShift(int dx, int dy, char[][] resultGrid, boolean[][] mask) {
            // Only update if there are pieces to shift (matches original logic)
            if (piecePositions.isEmpty()) {
                return;
            }

            resultGrid[boardSize - 1 + dx][boardSize - 1 + dy] = 'x';
            for (Position p : piecePositions) {
                int nx = p.row + dx;
                int ny = p.col + dy;
                if (nx >= 0 && nx < boardSize && ny >= 0 && ny < boardSize) {
                    mask[nx][ny] = true;
                }
            }
        }

        /**
         * Ensures that all 'x' characters on the input board are covered by at least one valid shift.
         */
        private boolean isFinalStateValid(boolean[][] mask) {
            for (int i = 0; i < boardSize; i++) {
                for (int j = 0; j < boardSize; j++) {
                    if (inputBoard[i][j] == 'x' && !mask[i][j]) {
                        return false;
                    }
                }
            }
            return true;
        }

        private void printGrid(char[][] grid) {
            StringBuilder sb = new StringBuilder();
            for (char[] row : grid) {
                sb.append(row).append('\n');
            }
            System.out.print(sb.toString());
        }
    }

    /**
     * Fast I/O utility for efficient reading.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;

/**
 * A utility to process grid transformations based on player movement rules.
 */
public class GridTransformation {

    // Character Constants
    private static final char PLAYER = 'o';
    private static final char EMPTY = '.';
    private static final char OBSTACLE = 'x';
    private static final char CLEARED_OBSTACLE = 'y';
    private static final char SUCCESSFUL_MOVE_MARKER = 'x';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int gridSize = scanner.nextInt();
        char[][] board = new char[gridSize][gridSize];

        for (int i = 0; i < gridSize; i++) {
            board[i] = scanner.next().toCharArray();
        }

        GridTransformation processor = new GridTransformation();
        processor.execute(gridSize, board);

        scanner.close();
    }

    /**
     * Orchestrates the grid transformation process.
     * 
     * @param n The size of the input grid.
     * @param board The initial state of the board.
     */
    public void execute(int n, char[][] board) {
        char[][] resultGrid = createResultGrid(n);

        // Iterate through all possible displacement offsets in the result grid
        for (int row = 0; row < 2 * n - 1; row++) {
            for (int col = 0; col < 2 * n - 1; col++) {

                // Skip the center cell of the result grid
                if (row == n - 1 && col == n - 1) {
                    continue;
                }

                int rowOffset = row - (n - 1);
                int colOffset = col - (n - 1);

                if (isValidMove(board, rowOffset, colOffset)) {
                    applyMoveToBoard(board, rowOffset, colOffset);
                    resultGrid[row][col] = SUCCESSFUL_MOVE_MARKER;
                }
            }
        }

        if (hasRemainingObstacles(board)) {
            System.out.println("NO");
        } else {
            System.out.println("YES");
            printGrid(resultGrid);
        }
    }

    /**
     * Creates the result grid initialized with empty cells and the center player.
     */
    private char[][] createResultGrid(int n) {
        int resultSize = 2 * n - 1;
        char[][] result = new char[resultSize][resultSize];
        for (char[] row : result) {
            Arrays.fill(row, EMPTY);
        }
        result[n - 1][n - 1] = PLAYER;
        return result;
    }

    /**
     * Determines if a move at the given offset is valid.
     * A move is invalid if any player lands on an EMPTY cell.
     */
    private boolean isValidMove(char[][] board, int rowOffset, int colOffset) {
        int n = board.length;
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (board[r][c] == PLAYER) {
                    int targetRow = r + rowOffset;
                    int targetCol = c + colOffset;

                    if (isWithinBounds(targetRow, targetCol, n) && board[targetRow][targetCol] == EMPTY) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    /**
     * Updates the board state by clearing obstacles hit by the move.
     */
    private void applyMoveToBoard(char[][] board, int rowOffset, int colOffset) {
        int n = board.length;
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (board[r][c] == PLAYER) {
                    int targetRow = r + rowOffset;
                    int targetCol = c + colOffset;

                    if (isWithinBounds(targetRow, targetCol, n) && board[targetRow][targetCol] == OBSTACLE) {
                        board[targetRow][targetCol] = CLEARED_OBSTACLE;
                    }
                }
            }
        }
    }

    /**
     * Checks if any obstacles ('x') remain on the board.
     */
    private boolean hasRemainingObstacles(char[][] board) {
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == OBSTACLE) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Helper to verify if coordinates are within the grid boundaries.
     */
    private boolean isWithinBounds(int r, int c, int n) {
        return r >= 0 && r < n && c >= 0 && c < n;
    }

    /**
     * Prints the grid to standard output.
     */
    private void printGrid(char[][] grid) {
        for (char[] row : grid) {
            System.out.println(new String(row));
        }
    }
}

