/**
 * Contains the core logic for expanding the grid based on piece positions.
 */
class GridExpansionSolver {
    private static final char CELL_EMPTY = '.';
    private static final char CELL_PIECE = 'o';
    private static final char CELL_BLOCK = 'x';

    private final int gridSize;
    private final char[][] originalGrid;
    private final List<Point> pieceLocations;

    public GridExpansionSolver(int gridSize, char[][] originalGrid) {
        this.gridSize = gridSize;
        this.originalGrid = originalGrid;
        this.pieceLocations = new ArrayList<>();
        identifyPieceLocations();
    }

    private void identifyPieceLocations() {
        for (int i = 0; i < gridSize; i++) {
            for (int j = 0; j < gridSize; j++) {
                if (originalGrid[i][j] == CELL_PIECE) {
                    pieceLocations.add(new Point(i, j));
                }
            }
        }
    }

    /**
     * Executes the expansion algorithm and validates the result.
     */
    public SolverResult solve() {
        int expandedSize = 2 * gridSize - 1;
        char[][] expandedGrid = new char[expandedSize][expandedSize];

        // Initialize expanded grid with blocks
        for (int i = 0; i < expandedSize; i++) {
            Arrays.fill(expandedGrid[i], CELL_BLOCK);
        }

        // Set the central piece
        int centerIndex = gridSize - 1;
        expandedGrid[centerIndex][centerIndex] = CELL_PIECE;

        // Calculate expanded grid cells
        for (int i = 0; i < expandedSize; i++) {
            for (int j = 0; j < expandedSize; j++) {
                if (i == centerIndex && j == centerIndex) {
                    continue;
                }

                int offsetX = i - centerIndex;
                int offsetY = j - centerIndex;

                if (isAnyPieceShiftedToEmpty(offsetX, offsetY)) {
                    expandedGrid[i][j] = CELL_EMPTY;
                }
            }
        }

        if (isValidSolution(expandedGrid)) {
            return new SolverResult(true, expandedGrid);
        } else {
            return new SolverResult(false, null);
        }
    }

    private boolean isAnyPieceShiftedToEmpty(int offsetX, int offsetY) {
        for (Point piece : pieceLocations) {
            int targetX = piece.getX() + offsetX;
            int targetY = piece.getY() + offsetY;

            if (isWithinBounds(targetX, targetY) && originalGrid[targetX][targetY] == CELL_EMPTY) {
                return true;
            }
        }
        return false;
    }

    private boolean isValidSolution(char[][] expandedGrid) {
        int centerIndex = gridSize - 1;

        for (int i = 0; i < gridSize; i++) {
            for (int j = 0; j < gridSize; j++) {
                if (originalGrid[i][j] == CELL_BLOCK) {
                    if (!isBlockCoveredByExpandedBlock(i, j, expandedGrid, centerIndex)) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    private boolean isBlockCoveredByExpandedBlock(int x, int y, char[][] expandedGrid, int center) {
        for (Point piece : pieceLocations) {
            int dx = x - piece.getX();
            int dy = y - piece.getY();
            int ansX = center + dx;
            int ansY = center + dy;

            if (ansX >= 0 && ansX < expandedGrid.length && 
                ansY >= 0 && ansY < expandedGrid[0].length) {
                if (expandedGrid[ansX][ansY] == CELL_BLOCK) {
                    return true;
                }
            }
        }
        return false;
    }

    private boolean isWithinBounds(int x, int y) {
        return x >= 0 && x < gridSize && y >= 0 && y < gridSize;
    }
}

