import java.util.*;
import java.io.*;

/**
 * GridPatternSolver solves a pattern-matching problem where we determine 
 * if a specific set of relative offsets (a pattern) correctly explains 
 * the distribution of '.' (empty) cells given the 'o' (object) cells.
 */
public class GridPatternSolver {

    /**
     * Represents a 2D coordinate in the grid.
     */
    private static class Point {
        final int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Efficient reader for parsing large inputs.
     */
    private static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }

    public void run() {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        try {
            solve(reader, out);
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.close();
        }
    }

    private void solve(FastReader reader, PrintWriter out) {
        String firstToken = reader.next();
        if (firstToken == null) return;

        int n = Integer.parseInt(firstToken);
        char[][] inputGrid = new char[n][n];
        List<Point> oPositions = new ArrayList<>();
        List<Point> dotPositions = new ArrayList<>();

        // 1. Read input and categorize 'o' and '.' positions
        for (int i = 0; i < n; i++) {
            String rowStr = reader.next();
            for (int j = 0; j < n; j++) {
                char cell = rowStr.charAt(j);
                inputGrid[i][j] = cell;
                if (cell == 'o') {
                    oPositions.add(new Point(i, j));
                } else {
                    dotPositions.add(new Point(i, j));
                }
            }
        }

        // 2. Generate the Pattern Grid
        // The pattern represents relative offsets. Dimensions (2n-1) accommodate all possible shifts.
        int patternSize = 2 * n - 1;
        char[][] patternGrid = new char[patternSize][patternSize];
        for (int i = 0; i < patternSize; i++) {
            Arrays.fill(patternGrid[i], 'x');
        }

        int center = n - 1;
        patternGrid[center][center] = 'o';

        // An offset is considered "valid" ('.') if it connects an 'o' to a '.'
        for (Point o : oPositions) {
            for (Point dot : dotPositions) {
                int dr = dot.r - o.r;
                int dc = dot.c - o.c;
                patternGrid[center + dr][center + dc] = '.';
            }
        }

        // 3. Identify forbidden offsets
        // Forbidden offsets are the 'x' marks in our pattern grid.
        List<Point> forbiddenOffsets = new ArrayList<>();
        for (int i = 0; i < patternSize; i++) {
            for (int j = 0; j < patternSize; j++) {
                if (patternGrid[i][j] == 'x') {
                    forbiddenOffsets.add(new Point(i - center, j - center));
                }
            }
        }

        // 4. Verify the pattern by reconstructing the grid
        char[][] reconstructedGrid = new char[n][n];
        for (int i = 0; i < n; i++) {
            Arrays.fill(reconstructedGrid[i], '.');
        }
        for (Point o : oPositions) {
            reconstructedGrid[o.r][o.c] = 'o';
        }

        for (Point o : oPositions) {
            for (Point offset : forbiddenOffsets) {
                int nr = o.r + offset.r;
                int nc = o.c + offset.c;
                if (nr >= 0 && nr < n && nc >= 0 && nc < n) {
                    // If a forbidden offset lands on a non-'o' cell, mark it as 'x'
                    if (reconstructedGrid[nr][nc] != 'o') {
                        reconstructedGrid[nr][nc] = 'x';
                    }
                }
            }
        }

        // 5. Final comparison and output
        if (isGridEqual(inputGrid, reconstructedGrid)) {
            out.println("YES");
            printGrid(patternGrid, out);
        } else {
            out.println("NO");
        }
    }

    private boolean isGridEqual(char[][] gridA, char[][] gridB) {
        for (int i = 0; i < gridA.length; i++) {
            for (int j = 0; j < gridA[0].length; j++) {
                if (gridA[i][j] != gridB[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    private void printGrid(char[][] grid, PrintWriter out) {
        for (char[] row : grid) {
            out.println(new String(row));
        }
    }

    public static void main(String[] args) {
        new GridPatternSolver().run();
    }
}

