/**
 * Contains the core logic to solve the grid pattern problem.
 */
class GridPatternSolver {

    /**
     * Solves the grid pattern problem.
     * 
     * @param n The size of the input grid.
     * @param inputGrid The original grid characters.
     * @return A PatternResult containing success status and the expanded grid.
     */
    public PatternResult solve(int n, String[] inputGrid) {
        int expandedSize = 2 * n - 1;
        char[][] expandedGrid = initializeGrid(expandedSize, '.');
        boolean[][] isXCovered = new boolean[n][n];

        // The center of the expanded grid is always 'o'
        expandedGrid[n - 1][n - 1] = 'o';

        for (int i = 0; i < expandedSize; i++) {
            for (int j = 0; j < expandedSize; j++) {
                // Skip the center cell as it is already defined
                if (i == n - 1 && j == n - 1) {
                    continue;
                }

                int rowOffset = i - (n - 1);
                int colOffset = j - (n - 1);

                if (isValidOffset(n, inputGrid, rowOffset, colOffset)) {
                    markXAsCovered(n, inputGrid, isXCovered, rowOffset, colOffset);
                    expandedGrid[i][j] = 'x';
                }
            }
        }

        if (verifyAllRequiredXAreCovered(n, inputGrid, isXCovered)) {
            return new PatternResult(true, expandedGrid);
        } else {
            return new PatternResult(false, null);
        }
    }

    private char[][] initializeGrid(int size, char defaultChar) {
        char[][] grid = new char[size][size];
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                grid[i][j] = defaultChar;
            }
        }
        return grid;
    }

    private boolean isValidOffset(int n, String[] grid, int rowOffset, int colOffset) {
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r].charAt(c) == 'o') {
                    int targetR = r + rowOffset;
                    int targetC = c + colOffset;

                    if (isInBounds(targetR, targetC, n)) {
                        // If an 'o' maps to a '.' in the original grid, the offset is invalid
                        if (grid[targetR].charAt(targetC) == '.') {
                            return false;
                        }
                    }
                }
            }
        }
        return true;
    }

    private void markXAsCovered(int n, String[] grid, boolean[][] isXCovered, int rowOffset, int colOffset) {
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r].charAt(c) == 'o') {
                    int targetR = r + rowOffset;
                    int targetC = c + colOffset;

                    if (isInBounds(targetR, targetC, n)) {
                        if (grid[targetR].charAt(targetC) == 'x') {
                            isXCovered[targetR][targetC] = true;
                        }
                    }
                }
            }
        }
    }

    private boolean verifyAllRequiredXAreCovered(int n, String[] grid, boolean[][] isXCovered) {
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r].charAt(c) == 'x' && !isXCovered[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    private boolean isInBounds(int r, int c, int n) {
        return r >= 0 && r < n && c >= 0 && c < n;
    }
}

/**
 * High-performance reader for fast I/O operations.
 */
class FastReader {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    public FastReader(InputStream input) {
        this.reader = new BufferedReader(new InputStreamReader(input));
    }

    public String next() {
        while (tokenizer == null || !tokenizer.hasMoreElements()) {
            String line = readLine();
            if (line == null) return null;
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    public String readLine() {
