            return reader.readLine();
        } catch (IOException e) {
            throw new RuntimeException("Error reading input", e);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver for determining if a pattern of 'o' and 'x' characters can be represented
 * by a set of valid offsets within a grid.
 */
public class Solution {

    private static final int OFFSET_LIMIT = 50;

    /**
     * Represents a 2D coordinate or offset.
     */
    private record Point(int row, int col) {}

    public static void main(String[] args) {
        try (InputReader in = new InputReader(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            Solution solution = new Solution();
            solution.solve(in, out);

            out.println();
            out.flush();
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    /**
     * Orchestrates the solving process.
     */
    private void solve(InputReader in, PrintWriter out) {
        int n = in.nextInt();
        char[][] grid = new char[n][n];
        for (int i = 0; i < n; i++) {
            grid[i] = in.next().toCharArray();
        }

        Set<Point> validOffsets = findValidOffsets(grid, n);

        if (!allXPositionsAreCovered(grid, n, validOffsets)) {
            out.println("NO");
        } else {
            out.println("YES");
            printResultGrid(out, n, validOffsets);
        }
    }

    /**
     * Finds all offsets (dr, dc) such that shifting all 'o's by that offset 
     * does not land any 'o' on a '.' cell.
     */
    private Set<Point> findValidOffsets(char[][] grid, int n) {
        Set<Point> validOffsets = new HashSet<>();
        for (int dr = -OFFSET_LIMIT; dr <= OFFSET_LIMIT; dr++) {
            for (int dc = -OFFSET_LIMIT; dc <= OFFSET_LIMIT; dc++) {
                if (isOffsetValid(grid, n, dr, dc)) {
                    validOffsets.add(new Point(dr, dc));
                }
            }
        }
        return validOffsets;
    }

    private boolean isOffsetValid(char[][] grid, int n, int dr, int dc) {
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 'o') {
                    int targetR = r + dr;
                    int targetC = c + dc;
                    if (isWithinBounds(targetR, targetC, n)) {
                        if (grid[targetR][targetC] == '.') {
                            return false;
                        }
                    }
                }
            }
        }
        return true;
    }

    /**
     * Ensures that every 'x' in the input grid can be mapped back to an 'o' 
     * using one of the valid offsets.
     */
    private boolean allXPositionsAreCovered(char[][] grid, int n, Set<Point> validOffsets) {
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 'x') {
                    if (!isCovered(r, c, grid, n, validOffsets)) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    private boolean isCovered(int r, int c, char[][] grid, int n, Set<Point> validOffsets) {
        for (Point offset : validOffsets) {
            int sourceR = r - offset.row();
            int sourceC = c - offset.col();
            if (isWithinBounds(sourceR, sourceC, n) && grid[sourceR][sourceC] == 'o') {
                return true;
            }
        }
        return false;
    }

    /**
     * Prints the generated (2n-1)x(2n-1) pattern.
     */
    private void printResultGrid(PrintWriter out, int n, Set<Point> validOffsets) {
        int size = 2 * n - 1;
        int center = n - 1;

        for (int r = 0; r < size; r++) {
            StringBuilder rowBuilder = new StringBuilder();
            for (int c = 0; c < size; c++) {
                if (r == center && c == center) {
                    rowBuilder.append('o');
                } else {
                    int dr = r - center;
                    int dc = c - center;
                    if (validOffsets.contains(new Point(dr, dc))) {
                        rowBuilder.append('x');
                    } else {
                        rowBuilder.append('.');
                    }
                }
            }
            out.println(rowBuilder.toString());
        }
    }

    private boolean isWithinBounds(int r, int c, int n) {
        return r >= 0 && r < n && c >= 0 && c < n;
    }

    /**
     * Fast I/O utility.
     */
    private static class InputReader implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        @Override
        public void close() throws IOException {
            reader.close();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver that identifies diagonal patterns in a grid of points.
 * It checks if a set of diagonal shifts can perfectly cover all 'x' points
 * and no '.' points based on the provided 'o' origin points.
 */
public class DiagonalPatternSolver {

    private static final int[] DX = {1, -1, 1, -1};
    private static final int[] DY = {1, 1, -1, -1};

    private record Point(int x, int y) {}

    public static void main(String[] args) {
        try {
            new DiagonalPatternSolver().run();
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    public void run() throws IOException {
        FastReader reader = new FastReader(System.in);
        int n = reader.nextInt();
        char[][] grid = new char[n][n];

        for (int i = 0; i < n; i++) {
            String line = reader.next();
            grid[i] = line.toCharArray();
        }

        List<Point> originPoints = findOriginPoints(grid, n);
        List<Point> validShifts = findValidShifts(grid, originPoints, n);

        if (validateCoverage(grid, originPoints, validShifts, n)) {
            System.out.println("YES");
            printExpandedGrid(validShifts, n);
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Locates all 'o' cells which act as origin points for shifts.
     */
    private List<Point> findOriginPoints(char[][] grid, int n) {
        List<Point> origins = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 'o') {
                    origins.add(new Point(i, j));
                }
            }
        }
        return origins;
    }

    /**
     * Finds all diagonal offsets that do not cause any origin point 
     * to land on a '.' cell.
     */
    private List<Point> findValidShifts(char[][] grid, List<Point> origins, int n) {
        List<Point> validShifts = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            for (int j = i; j < n; j++) {
                if (i == 0 && j == 0) continue;

                // Check all 4 diagonal directions
                for (int k = 0; k < 4; k++) {
                    // Case 1: Shift using (i, j)
                    if (isShiftSafe(grid, origins, DX[k] * i, DY[k] * j, n)) {
                        validShifts.add(new Point(DX[k] * i, DY[k] * j));
                    }
                    // Case 2: Shift using (j, i)
                    if (isShiftSafe(grid, origins, DX[k] * j, DY[k] * i, n)) {
                        validShifts.add(new Point(DX[k] * j, DY[k] * i));
                    }
                }
            }
        }
        return validShifts;
    }

    private boolean isShiftSafe(char[][] grid, List<Point> origins, int offsetX, int offsetY, int n) {
        for (Point origin : origins) {
            int targetX = origin.x + offsetX;
            int targetY = origin.y + offsetY;

            if (isWithinBounds(targetX, targetY, n) && grid[targetX][targetY] == '.') {
                return false;
            }
        }
        return true;
    }

    /**
     * Verifies if the set of valid shifts covers all 'x' cells 
     * and exactly zero '.' cells.
     */
    private boolean validateCoverage(char[][] grid, List<Point> origins, List<Point> shifts, int n) {
        boolean[][] coveredMap = new boolean[n][n];

        for (Point shift : shifts) {
            for (Point origin : origins) {
                int targetX = origin.x + shift.x;
                int targetY = origin.y + shift.y;
                if (isWithinBounds(targetX, targetY, n)) {
                    coveredMap[targetX][targetY] = true;
                }
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                boolean isCovered = coveredMap[i][j];
                if (grid[i][j] == 'x' && !isCovered) return false;
                if (grid[i][j] == '.' && isCovered) return false;
            }
        }
        return true;
    }

    /**
     * Constructs and prints the expanded (2n-1)x(2n-1) grid.
     */
    private void printExpandedGrid(List<Point> shifts, int n) {
        int newSize = 2 * n - 1;
        char[][] expandedGrid = new char[newSize][newSize];
        for (char[] row : expandedGrid) {
            Arrays.fill(row, '.');
        }

        // The original center is at index n-1
        expandedGrid[n - 1][n - 1] = 'o';

        for (Point shift : shifts) {
            int targetX = (n - 1) + shift.x;
            int targetY = (n - 1) + shift.y;
            // Check bounds to prevent ArrayOutOfBounds in the expanded grid
            if (targetX >= 0 && targetX < newSize && targetY >= 0 && targetY < newSize) {
                expandedGrid[targetX][targetY] = 'x';
            }
        }
        // Ensure center remains 'o' if an 'x' was placed there
        expandedGrid[n - 1][n - 1] = 'o';

        StringBuilder sb = new StringBuilder();
        for (char[] row : expandedGrid) {
            sb.append(new String(row)).append("\n");
        }
        System.out.print(sb);
    }

    private boolean isWithinBounds(int x, int y, int n) {
        return x >= 0 && x < n && y >= 0 && y < n;
    }

    /**
     * Efficient reader for parsing input.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves the WeirdChess problem.
 * The problem involves determining a valid configuration of obstacles ('x') 
 * based on relative offsets between empty cells ('.') and orbs ('o').
 */
public class WeirdChess {

    private static final char EMPTY = '.';
    private static final char ORB = 'o';
    private static final char OBSTACLE = 'x';

    public static void main(String[] args) {
        InputReader reader = new InputReader(System.in);
        PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            new ChessSolver(reader, writer).solve();
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    /**
     * Represents a coordinate in the 2D grid.
     */
    private static class Point {
        final int row, col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    private static class ChessSolver {
        private final InputReader reader;
        private final PrintWriter writer;

        ChessSolver(InputReader reader, PrintWriter writer) {
            this.reader = reader;
            this.writer = writer;
        }

        /**
         * Main execution flow of the solver.
         */
        public void solve() {
            int n = reader.nextInt();
            if (n <= 0) return;

            char[][] grid = readGrid(n);

            List<Point> dots = new ArrayList<>();
            List<Point> orbs = new ArrayList<>();
            List<Point> obstacles = new ArrayList<>();

            // Step 1: Parse the grid and categorize positions
            for (int r = 0; r < n; r++) {
                for (int c = 0; c < n; c++) {
                    if (grid[r][c] == EMPTY) {
                        dots.add(new Point(r, c));
                    } else if (grid[r][c] == ORB) {
                        orbs.add(new Point(r, c));
                    } else if (grid[r][c] == OBSTACLE) {
                        obstacles.add(new Point(r, c));
                    }
                }
            }

            // Step 2: Pre-calculate "safe" relative offsets
            boolean[][] isSafeOffset = computeSafeOffsets(n, dots, orbs);

            // Step 3: Validate if the existing obstacles satisfy the problem constraints
            if (validateObstacles(n, obstacles, orbs, isSafeOffset)) {
                printSuccess(n, isSafeOffset);
            } else {
                writer.println("NO");
            }
        }

        private char[][] readGrid(int n) {
            char[][] grid = new char[n][n];
            for (int i = 0; i < n; i++) {
                String line = reader.next();
                for (int j = 0; j < n; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }
            return grid;
        }

        /**
         * Calculates which relative displacements (dr, dc) are "safe".
         * A displacement is safe if it exists between an empty cell and an orb.
         */
        private boolean[][] computeSafeOffsets(int n, List<Point> dots, List<Point> orbs) {
            int offsetCenter = n - 1;
            int dimension = 2 * n - 1;
            boolean[][] isSafe = new boolean[dimension][dimension];

            // The zero offset is safe by default
            isSafe[offsetCenter][offsetCenter] = true;

            for (Point dot : dots) {
                for (Point orb : orbs) {
                    int dr = dot.row - orb.row + offsetCenter;
                    int dc = dot.col - orb.col + offsetCenter;
                    isSafe[dr][dc] = true;
                }
            }
            return isSafe;
        }

        /**
         * An obstacle 'x' is valid if there is at least one orb such that the 
         * offset between the obstacle and the orb is NOT in the safe set.
         */
        private boolean validateObstacles(int n, List<Point> obstacles, List<Point> orbs, boolean[][] isSafeOffset) {
            int offsetCenter = n - 1;
            for (Point obs : obstacles) {
                boolean canBeValid = false;
                for (Point orb : orbs) {
                    int dr = obs.row - orb.row + offsetCenter;
                    int dc = obs.col - orb.col + offsetCenter;
                    if (!isSafeOffset[dr][dc]) {
                        canBeValid = true;
                        break;
                    }
                }
                if (!canBeValid) {
                    return false;
                }
            }
            return true;
        }

        private void printSuccess(int n, boolean[][] isSafeOffset) {
            writer.println("YES");
            int offsetCenter = n - 1;
            int dimension = 2 * n - 1;
            for (int i = 0; i < dimension; i++) {
                for (int j = 0; j < dimension; j++) {
                    if (i == offsetCenter && j == offsetCenter) {
                        writer.print(ORB);
                    } else if (isSafeOffset[i][j]) {
                        writer.print(EMPTY);
                    } else {
                        writer.print(OBSTACLE);
                    }
                }
                writer.println();
            }
        }
    }

    /**
     * Efficient input reader using BufferedReader and StringTokenizer.
     */
    private static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to determine if a pattern of 'o' characters can be shifted 
 * to cover all 'x' characters on a grid without overlapping any '.' cells.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            String line = reader.readLine();
            if (line == null) return;

            int n = Integer.parseInt(line.trim());
            char[][] board = new char[n][n];
            for (int i = 0; i < n; i++) {
                board[i] = reader.readLine().toCharArray();
            }

            PatternSolver solver = new PatternSolver(n, board);
            solver.solve(writer);
        } catch (Exception e) {
            // In a production environment, use a logger.
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Logic engine for solving the grid pattern problem.
     */
    static class PatternSolver {
        private final int n;
        private final char[][] board;
        private final List<Point> oPositions;

        private static class Point {
            final int r, c;
            Point(int r, int c) {
                this.r = r;
                this.c = c;
            }
        }

        public PatternSolver(int n, char[][] board) {
            this.n = n;
            this.board = board;
            this.oPositions = new ArrayList<>();
            findOriginalOPositions();
        }

        private void findOriginalOPositions() {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (board[i][j] == 'o') {
                        oPositions.add(new Point(i, j));
                    }
                }
            }
        }

        public void solve(PrintWriter out) {
            // isValidOffset[cdx + n][cdy + n] stores if a translation is valid
            boolean[][] isValidOffset = new boolean[2 * n][2 * n];
            // isCovered[r][c] stores if cell (r, c) is covered by a validly shifted 'o'
            boolean[][] isCovered = new boolean[n][n];

            // Iterate through all possible relative offsets (dx, dy)
            for (int dx = -(n - 1); dx <= n - 1; dx++) {
                for (int dy = -(n - 1); dy <= n - 1; dy++) {
                    if (isTranslationValid(dx, dy)) {
                        markValidOffset(dx, dy, isValidOffset, isCovered);
                    }
                }
            }

            if (checkAllXCovered(isCovered)) {
                out.println("YES");
                printResultGrid(isValidOffset, out);
            } else {
                out.println("NO");
            }
        }

        private boolean isTranslationValid(int dx, int dy) {
            for (Point p : oPositions) {
                int targetR = p.r + dx;
                int targetC = p.c + dy;
                // If the shifted 'o' lands on a '.', the whole translation is invalid
                if (isWithinBounds(targetR, targetC) && board[targetR][targetC] == '.') {
                    return false;
                }
            }
            return true;
        }

        private void markValidOffset(int dx, int dy, boolean[][] isValidOffset, boolean[][] isCovered) {
            isValidOffset[dx + n][dy + n] = true;
            for (Point p : oPositions) {
                int targetR = p.r + dx;
                int targetC = p.c + dy;
                if (isWithinBounds(targetR, targetC)) {
                    isCovered[targetR][targetC] = true;
                }
            }
        }

        private boolean checkAllXCovered(boolean[][] isCovered) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (board[i][j] == 'x' && !isCovered[i][j]) {
                        return false;
                    }
                }
            }
            return true;
        }

        private void printResultGrid(boolean[][] isValidOffset, PrintWriter out) {
            int size = 2 * n - 1;
            char[][] resultGrid = new char[size][size];

            // Initialize grid with '.'
            for (int i = 0; i < size; i++) {
                Arrays.fill(resultGrid[i], '.');
            }

            // Map valid offsets to the result grid
            for (int i = 1; i < 2 * n; i++) {
                for (int j = 1; j < 2 * n; j++) {
                    if (isValidOffset[i][j]) {
                        resultGrid[i - 1][j - 1] = 'x';
                    }
                }
            }

            // The origin offset (0,0) is always represented by 'o' at the center
            resultGrid[n - 1][n - 1] = 'o';

            for (int i = 0; i < size; i++) {
                out.println(new String(resultGrid[i]));
            }
        }

        private boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < n && c >= 0 && c < n;
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String readLine() throws IOException {
            return reader.readLine();
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * TaskD handles the logic for calculating valid grid shifts and verifying 
 * if the input grid satisfies specific shift-based constraints.
 */
public class TaskD {

    // Constants for grid cell types to avoid magic characters
    private static final char EMPTY_CELL = '.';
    private static final char TARGET_CELL = 'o';
    private static final char VALID_SHIFT_CELL = 'x';
    private static final char ORIGIN_CELL = 'o';

    private int gridSize;
    private char[][] inputGrid;
    private char[][] shiftGrid;
    private FastScanner scanner;
    private PrintWriter out;

    public void run() {
        try {
            scanner = new FastScanner();
            out = new PrintWriter(System.out);

            solve();

            out.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /**
     * Orchestrates the problem-solving steps.
     */
    private void solve() throws IOException {
        readInput();
        calculateValidShifts();
        updateInputGridWithShifts();

        if (isSolutionInvalid()) {
            out.println("NO");
        } else {
            out.println("YES");
            printShiftGrid();
        }
    }

    private void readInput() throws IOException {
        this.gridSize = scanner.nextInt();
        this.inputGrid = new char[gridSize][gridSize];
        for (int i = 0; i < gridSize; i++) {
            this.inputGrid[i] = scanner.next().toCharArray();
        }
    }

    /**
     * Computes the shift grid of size (2n-1)x(2n-1).
     */
    private void calculateValidShifts() {
        int resultSize = 2 * gridSize - 1;
        this.shiftGrid = new char[resultSize][resultSize];
        int offset = gridSize - 1;

        for (int dr = -gridSize + 1; dr < gridSize; dr++) {
            for (int dc = -gridSize + 1; dc < gridSize; dc++) {
                int resRow = dr + offset;
                int resCol = dc + offset;

                if (dr == 0 && dc == 0) {
                    shiftGrid[resRow][resCol] = ORIGIN_CELL;
                } else if (isShiftValid(dr, dc)) {
                    shiftGrid[resRow][resCol] = VALID_SHIFT_CELL;
                } else {
                    shiftGrid[resRow][resCol] = EMPTY_CELL;
                }
            }
        }
    }

    /**
     * Checks if a specific shift (dr, dc) is valid.
     * A shift is valid if for every target cell 'o', the shifted cell is not empty.
     */
    private boolean isShiftValid(int dr, int dc) {
        for (int r = 0; r < gridSize; r++) {
            for (int c = 0; c < gridSize; c++) {
                if (inputGrid[r][c] == TARGET_CELL) {
                    int targetRow = r + dr;
                    int targetCol = c + dc;

                    if (isWithinBounds(targetRow, targetCol) && inputGrid[targetRow][targetCol] == EMPTY_CELL) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    /**
     * Modifies the input grid based on valid shifts found in the shift grid.
     */
    private void updateInputGridWithShifts() {
        int offset = gridSize - 1;
        for (int dr = -gridSize + 1; dr < gridSize; dr++) {
            for (int dc = -gridSize + 1; dc < gridSize; dc++) {
                if (shiftGrid[dr + offset][dc + offset] == VALID_SHIFT_CELL) {
                    applyShiftEffect(dr, dc);
                }
            }
        }
    }

    private void applyShiftEffect(int dr, int dc) {
        for (int r = 0; r < gridSize; r++) {
            for (int c = 0; c < gridSize; c++) {
                if (inputGrid[r][c] == TARGET_CELL) {
                    int targetRow = r + dr;
                    int targetCol = c + dc;
                    // Note: This logic preserves the original behavior where inputGrid 
                    // elements might be changed if they match a specific char.
                    if (isWithinBounds(targetRow, targetCol) && inputGrid[targetRow][targetCol] == VALID_SHIFT_CELL) {
                        inputGrid[targetRow][targetCol] = EMPTY_CELL;
                    }
                }
            }
        }
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < gridSize && c >= 0 && c < gridSize;
    }

    /**
     * Verifies if any invalid state (represented by VALID_SHIFT_CELL) remains in the input grid.
     */
    private boolean isSolutionInvalid() {
        for (int i = 0; i < gridSize; i++) {
            for (int j = 0; j < gridSize; j++) {
                if (inputGrid[i][j] == VALID_SHIFT_CELL) {
                    return true;
                }
            }
        }
        return false;
    }

    private void printShiftGrid() {
        for (int i = 0; i < shiftGrid.length; i++) {
            for (int j = 0; j < shiftGrid[i].length; j++) {
                out.print(shiftGrid[i][j]);
            }
            out.println();
        }
    }

    /**
     * Fast I/O utility class.
     */
    private static class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) {
        new TaskD().run();
    }
}

import java.util.Scanner;

/**
 * WeirdChess performs a spatial coverage analysis on a grid.
 * It determines if specific 'x' pieces can be covered by 'o' pieces
 * using a set of allowed relative offsets derived from the input grid.
 */
public class WeirdChess {

    private static final char PIECE_O = 'o';
    private static final char PIECE_X = 'x';
    private static final char EMPTY = '.';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int gridSize = scanner.nextInt();
        char[][] inputGrid = new char[gridSize][gridSize];

        for (int i = 0; i < gridSize; i++) {
            String row = scanner.next();
            inputGrid[i] = row.toCharArray();
        }

        // Phase 1: Compute the set of relative offsets
        // The offset grid represents the relationship between 'o' and '.' pieces.
        char[][] offsetGrid = computeOffsetGrid(inputGrid, gridSize);

        // Phase 2: Check if the 'x' pieces are covered by the 'o' pieces via allowed offsets
        boolean isCovered = checkCoverage(inputGrid, offsetGrid, gridSize);

        // Phase 3: Output results
        if (isCovered) {
            System.out.println("YES");
            printGrid(offsetGrid);
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Constructs a relative offset grid based on the distances between 'o' and '.' pieces.
     */
    private static char[][] computeOffsetGrid(char[][] input, int n) {
        int size = 2 * n - 1;
        char[][] offsets = new char[size][size];

        // Initialize the offset grid with 'x' (representing available/unknown moves)
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                offsets[i][j] = PIECE_X;
            }
        }

        // The origin (no movement) is marked as 'o'
        offsets[n - 1][n - 1] = PIECE_O;

        // For every 'o' piece, find all '.' pieces to define disallowed/special relative vectors
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (input[i][j] == PIECE_O) {
                    for (int k = 0; k < n; k++) {
                        for (int l = 0; l < n; l++) {
                            if (input[k][l] == EMPTY) {
                                // Map the relative distance (k-i, l-j) into the offset grid
                                offsets[n - 1 + k - i][n - 1 + l - j] = EMPTY;
                            }
                        }
                    }
                }
            }
        }
        return offsets;
    }

    /**
     * Verifies if all 'x' positions in the original input can be reached 
     * by an 'o' position plus an offset marked as 'x' in the offset grid.
     */
    private static boolean checkCoverage(char[][] input, char[][] offsets, int n) {
        // coverageGrid tracks which cells are 'o' or have been covered by an 'x'
        char[][] coverageGrid = new char[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                coverageGrid[i][j] = (input[i][j] == PIECE_O) ? PIECE_O : EMPTY;
            }
        }

        int offsetSize = offsets.length;

        // Apply the 'x' offsets to every 'o' piece to spread coverage
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (coverageGrid[i][j] == PIECE_O) {
                    for (int k = 0; k < offsetSize; k++) {
                        for (int l = 0; l < offsetSize; l++) {
                            if (offsets[k][l] == PIECE_X) {
                                int targetRow = i + k - (n - 1);
                                int targetCol = j + l - (n - 1);

                                if (isWithinBounds(targetRow, targetCol, n)) {
                                    if (coverageGrid[targetRow][targetCol] != PIECE_O) {
                                        coverageGrid[targetRow][targetCol] = PIECE_X;
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }

        // Validate that every 'x' from the input is now marked as 'x' in the coverage grid
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (input[i][j] == PIECE_X && coverageGrid[i][j] == EMPTY) {
                    return false;
                }
            }
        }
        return true;
    }

    private static boolean isWithinBounds(int row, int col, int n) {
        return row >= 0 && row < n && col >= 0 && col < n;
    }

    private static void printGrid(char[][] grid) {
        for (char[] row : grid) {
            System.out.println(new String(row));
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * The PatternMatcher class solves a grid-based pattern problem.
 * It identifies valid shifts of a set of 'o' points such that 
 * the union of all shifted 'o' points covers all 'x' points 
 * present in the original grid.
 */
public class PatternMatcher {

    private static final char EMPTY = '.';
    private static final char TARGET = 'o';
    private static final char MARKER = 'x';

    private final int gridSize;
    private final char[][] inputGrid;
    private final List<Point> targetPoints;
    private final boolean[][] isXCovered;

    /**
     * Represents a 2D coordinate.
     */
    private record Point(int y, int x) {}

    public PatternMatcher(int gridSize, char[][] inputGrid) {
        this.gridSize = gridSize;
        this.inputGrid = inputGrid;
        this.targetPoints = new ArrayList<>();
        this.isXCovered = new boolean[gridSize][gridSize];

        // Identify all initial 'o' positions
        for (int r = 0; r < gridSize; r++) {
            for (int c = 0; c < gridSize; c++) {
                if (inputGrid[r][c] == TARGET) {
                    targetPoints.add(new Point(r, c));
                }
            }
        }
    }

    /**
     * Orchestrates the pattern solving process.
     */
    public void solve(PrintWriter out) {
        if (gridSize == 1) {
            out.println("YES");
            out.println("o");
            return;
        }

        int solutionSize = 2 * gridSize - 1;
        char[][] solutionGrid = new char[solutionSize][solutionSize];
        int offset = gridSize - 1;

        // Initialize solution grid with empty cells
        for (int i = 0; i < solutionSize; i++) {
            Arrays.fill(solutionGrid[i], EMPTY);
        }

        // The zero-offset (center) is always considered a valid part of the pattern
        solutionGrid[offset][offset] = TARGET;

        // Iterate through all possible relative shifts (dy, dx)
        for (int dy = -offset; dy <= offset; dy++) {
            for (int dx = -offset; dx <= offset; dx++) {
                // Skip the center as it was already initialized
                if (dy == 0 && dx == 0) continue;

                List<Point> validHits = getValidShiftHits(dy, dx);

                // If the shift is valid (all 'o's land on non-'.' cells), mark it in the pattern
                if (validHits != null) {
                    solutionGrid[dy + offset][dx + offset] = MARKER;
                    for (Point p : validHits) {
                        isXCovered[p.y][p.x] = true;
                    }
                }
            }
        }

        if (validateCoverage()) {
            out.println("YES");
            printGrid(solutionGrid, out);
        } else {
            out.println("NO");
        }
    }

    /**
     * Checks if a specific shift (dy, dx) is valid.
     * A shift is valid if every 'o' that remains within grid bounds lands on a non-'.' cell.
     * 
     * @return A list of resulting points if valid, or null if the shift hits a '.'
     */
    private List<Point> getValidShiftHits(int dy, int dx) {
        List<Point> hits = new ArrayList<>();
        for (Point p : targetPoints) {
            int ny = p.y + dy;
            int nx = p.x + dx;

            // If the shifted point is within grid boundaries
            if (ny >= 0 && ny < gridSize && nx >= 0 && nx < gridSize) {
                if (inputGrid[ny][nx] == EMPTY) {
                    return null; // Invalid shift: hit an empty cell
                }
                hits.add(new Point(ny, nx));
            }
            // Out-of-bounds points are ignored per original logic
        }
        return hits;
    }

    /**
     * Verifies if every 'x' in the original grid has been covered by at least one valid shift.
     */
    private boolean validateCoverage() {
        for (int r = 0; r < gridSize; r++) {
            for (int c = 0; c < gridSize; c++) {
                if (inputGrid[r][c] == MARKER && !isXCovered[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    private void printGrid(char[][] grid, PrintWriter out) {
        for (char[] row : grid) {
            out.println(new String(row));
        }
    }

    public static void main(String[] args) throws IOException {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        String firstLine = reader.next();
        if (firstLine != null) {
            int n = Integer.parseInt(firstLine);
            char[][] grid = new char[n][n];
            for (int i = 0; i < n; i++) {
                grid[i] = reader.next().toCharArray();
            }

            PatternMatcher matcher = new PatternMatcher(n, grid);
            matcher.solve(out);
        }

        out.flush();
        out.close();
    }

    /**
     * Efficient input reader for competitive programming/large data sets.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A refactored solution for the Board Transformation problem.
 * This program determines if a set of pieces ('o') can be shifted by a set of 
 * valid relative vectors such that all obstacles ('x') are covered and 
 * no empty spaces ('.') are covered.
 */
public class Main {

    public static void main(String[] args) {
        try {
            FastReader reader = new FastReader(System.in);
            BoardTransformationSolver solver = new BoardTransformationSolver(reader);
            solver.solve();
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Enum representing the possible states of a single cell on the board.
     */
    enum CellType {
        EMPTY,
        OBSTACLE,
        PIECE
    }

    /**
     * A simple utility class representing a 2D coordinate.
     */
    static class Coordinate {
        final int row, col;

        Coordinate(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Handles efficient input reading.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String nextLine() throws IOException {
            return reader.readLine();
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    /**
     * Encapsulates the grid and its dimensions.
     */
    static class Grid {
        private final int size;
        private final CellType[][] cells;

        public Grid(int size) {
            this.size = size;
            this.cells = new CellType[size][size];
        }

        public void setCell(int r, int c, CellType type) {
            cells[r][c] = type;
        }

        public CellType getCell(int r, int c) {
            return cells[r][c];
        }

        public int getSize() {
            return size;
        }

        public boolean isOutOfBounds(int r, int c) {
            return r < 0 || r >= size || c < 0 || c >= size;
        }
    }

    /**
     * Contains the core logic for solving the board transformation problem.
     */
    static class BoardTransformationSolver {
        private final FastReader reader;
        private Grid grid;
        private List<Coordinate> pieceLocations;

        public BoardTransformationSolver(FastReader reader) {
            this.reader = reader;
            this.pieceLocations = new ArrayList<>();
        }

        public void solve() throws IOException {
            // The original code consumes a line before reading N.
            reader.nextLine();
            int n = reader.nextInt();
            parseGrid(n);

            // The validShifts grid stores:
            // 1: A valid relative displacement
            // -1: The origin displacement (0,0)
            // 0: An invalid displacement
            int[][] validShifts = calculateValidShifts(n);

            // Check which cells are covered by applying all valid shifts to the pieces.
            boolean[][] coverageMap = buildCoverageMap(n, validShifts);

            if (validate(n, coverageMap)) {
                printResult(n, validShifts);
            } else {
                System.out.println("NO");
            }
        }

        private void parseGrid(int n) throws IOException {
            grid = new Grid(n);
            for (int i = 0; i < n; i++) {
                String line = reader.next();
                for (int j = 0; j < line.length(); j++) {
                    char symbol = line.charAt(j);
                    switch (symbol) {
                        case 'o':
                            grid.setCell(i, j, CellType.PIECE);
                            pieceLocations.add(new Coordinate(i, j));
                            break;
                        case 'x':
                            grid.setCell(i, j, CellType.OBSTACLE);
                            break;
                        case '.':
                            grid.setCell(i, j, CellType.EMPTY);
                            break;
                    }
                }
            }
        }

        private int[][] calculateValidShifts(int n) {
            int dimension = 2 * n - 1;
            int[][] validShifts = new int[dimension][dimension];

            for (int i = 0; i < dimension; i++) {
                for (int j = 0; j < dimension; j++) {
                    int dr = i - n + 1;
                    int dc = j - n + 1;

                    // Origin shift is special in the output
                    if (dr == 0 && dc == 0) {
                        validShifts[i][j] = -1;
                        continue;
                    }

                    boolean isShiftValid = true;
                    for (Coordinate piece : pieceLocations) {
                        int newR = piece.row + dr;
                        int newC = piece.col + dc;

                        // If a piece lands on an empty space, this shift is invalid.
                        if (!grid.isOutOfBounds(newR, newC)) {
                            if (grid.getCell(newR, newC) == CellType.EMPTY) {
                                isShiftValid = false;
                                break;
                            }
                        }
                    }

                    if (isShiftValid) {
                        validShifts[i][j] = 1;
                    }
                }
            }
            return validShifts;
        }

        private boolean[][] buildCoverageMap(int n, int[][] validShifts) {
            boolean[][] coverageMap = new boolean[n][n];
            int dimension = 2 * n - 1;

            for (int i = 0; i < dimension; i++) {
                for (int j = 0; j < dimension; j++) {
                    // Only apply shifts that are either valid (1) or the origin (-1)
                    if (validShifts[i][j] == 0) continue;

                    int dr = i - n + 1;
                    int dc = j - n + 1;

                    for (Coordinate piece : pieceLocations) {
                        int newR = piece.row + dr;
                        int newC = piece.col + dc;

                        if (!grid.isOutOfBounds(newR, newC)) {
                            coverageMap[newR][newC] = true;
                        }
                    }
                }
            }
            return coverageMap;
        }

        private boolean validate(int n, boolean[][] coverageMap) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    CellType currentType = grid.getCell(i, j);
                    boolean isCovered = coverageMap[i][j];

                    // All obstacles must be covered by at least one shifted piece.
                    if (currentType == CellType.OBSTACLE && !isCovered) {
                        return false;
                    }
                    // No empty spaces can be covered by any shifted piece.
                    if (currentType == CellType.EMPTY && isCovered) {
                        return false;
                    }
                }
            }
            return true;
        }

        private void printResult(int n, int[][] validShifts) {
            StringBuilder sb = new StringBuilder();
            int dimension = 2 * n - 1;
            sb.append("YES\n");

            for (int i = 0; i < dimension; i++) {
                for (int j = 0; j < dimension; j++) {
                    if (validShifts[i][j] == 1) {
                        sb.append('x');
                    } else if (validShifts[i][j] == -1) {
                        sb.append('o');
                    } else {
                        sb.append('.');
                    }
                }
                sb.append('\n');
            }
            System.out.print(sb.toString());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Main entry point for the application.
 * Orchestrates the reading of input and the execution of the solver.
 */
public class Main {
    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        GridCoverageSolver solver = new GridCoverageSolver();
        solver.solve(reader, writer);

        writer.flush();
        writer.close();
    }

    /**
     * Logic solver for the grid coverage problem.
     */
    static class GridCoverageSolver {
        private static final char CHAR_EMPTY = '.';
        private static final char CHAR_OBSTACLE = 'x';
        private static final char CHAR_TARGET = 'o';

        /**
         * Orchestrates the solving process: reading, computing, validating, and printing.
         */
        public void solve(FastReader in, PrintWriter out) {
            int gridSize = in.readInt();
            if (gridSize <= 0) return;

            char[][] inputGrid = new char[gridSize][gridSize];
            for (int i = 0; i < gridSize; i++) {
                inputGrid[i] = in.readString().toCharArray();
            }

            char[][] outputGrid = computeOutputGrid(inputGrid, gridSize);

            if (isInputValid(inputGrid, outputGrid, gridSize)) {
                out.println("YES");
                printGrid(out, outputGrid);
            } else {
                out.println("NO");
            }
        }

        /**
         * Generates the resulting grid based on the target 'o' and empty '.' positions.
         */
        private char[][] computeOutputGrid(char[][] inputGrid, int n) {
            int resultSize = 2 * n - 1;
            char[][] outputGrid = new char[resultSize][resultSize];

            // Initialize grid with obstacles
            for (int i = 0; i < resultSize; i++) {
                Arrays.fill(outputGrid[i], CHAR_OBSTACLE);
            }

            // Set the central target
            outputGrid[n - 1][n - 1] = CHAR_TARGET;

            // Project empty cells from input onto the output grid relative to targets
            for (int row = 0; row < n; row++) {
                for (int col = 0; col < n; col++) {
                    if (inputGrid[row][col] == CHAR_TARGET) {
                        projectEmptyCells(inputGrid, outputGrid, row, col, n);
                    }
                }
            }
            return outputGrid;
        }

        private void projectEmptyCells(char[][] input, char[][] output, int targetRow, int targetCol, int n) {
            for (int r = 0; r < n; r++) {
                for (int c = 0; c < n; c++) {
                    if (input[r][c] == CHAR_EMPTY) {
                        int targetOutputRow = (n - 1) - targetRow + r;
                        int targetOutputCol = (n - 1) - targetCol + c;
                        output[targetOutputRow][targetOutputCol] = CHAR_EMPTY;
                    }
                }
            }
        }

        /**
         * Validates if all obstacle 'x' cells in the input are properly "covered".
         */
        private boolean isInputValid(char[][] inputGrid, char[][] outputGrid, int n) {
            for (int row = 0; row < n; row++) {
                for (int col = 0; col < n; col++) {
                    if (inputGrid[row][col] == CHAR_OBSTACLE) {
                        if (!isObstacleCovered(inputGrid, outputGrid, row, col, n)) {
                            return false;
                        }
                    }
                }
            }
            return true;
        }

        private boolean isObstacleCovered(char[][] input, char[][] output, int row, int col, int n) {
            boolean covered = false;
            for (int r = 0; r < n; r++) {
                for (int c = 0; c < n; c++) {
                    if (input[r][c] == CHAR_TARGET) {
                        int checkRow = (n - 1) + row - r;
                        int checkCol = (n - 1) + col - c;
                        // Check if the mapping is NOT an empty cell
                        if (output[checkRow][checkCol] != CHAR_EMPTY) {
                            covered = true;
                            break;
                        }
                    }
                }
                if (covered) break;
            }
            return covered;
        }

        private void printGrid(PrintWriter out, char[][] grid) {
            for (char[] row : grid) {
                out.println(new String(row));
            }
        }
    }

    /**
     * High-performance custom reader for fast I/O operations.
     */
    static class FastReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int curChar;
        private int numChars;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buffer);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading from stream", e);
                }
                if (numChars <= 0) return -1;
            }
            return buffer[curChar++];
        }

        public int readInt() {
            return (int) readLong();
        }

        public long readLong() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            boolean negative = false;
            if (c == '-') {
                negative = true;
                c = read();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res *= 10;
                res += (c - '0');
                c = read();
            } while (!isSpaceChar(c));
            return negative ? (-res) : res;
        }

        public String readString() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.append((char) c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

