record Point(int row, int col) {}

/**
 * Represents the state of the game board.
 */
class Grid {
    private final int size;
    private final char[][] cells;
    private final boolean[][] attackMask;
    private final List<Point> piecePositions;

    public Grid(int size, char[][] cells) {
        this.size = size;
        this.cells = cells;
        this.attackMask = new boolean[size][size];
        this.piecePositions = new ArrayList<>();
        initializeMask();
    }

    private void initializeMask() {
        for (int r = 0; r < size; r++) {
            for (int c = 0; c < size; c++) {
                if (cells[r][c] != '.') {
                    attackMask[r][c] = true;
                }
                if (cells[r][c] == 'o') {
                    piecePositions.add(new Point(r, c));
                }
            }
        }
    }

    public int getSize() {
        return size;
    }

    public boolean isUnderAttack(int row, int col) {
        return attackMask[row][col];
    }

    public List<Point> getPiecePositions() {
        return piecePositions;
    }
}

/**
 * Encapsulates the result of the problem solving process.
 */
class Solution {
    private final boolean isPossible;
    private final boolean[][] shiftPattern;
    private final int gridSize;

    private Solution(boolean isPossible, boolean[][] shiftPattern, int gridSize) {
        this.isPossible = isPossible;
        this.shiftPattern = shiftPattern;
        this.gridSize = gridSize;
    }

    public static Solution success(boolean[][] shiftPattern, int gridSize) {
        return new Solution(true, shiftPattern, gridSize);
    }

    public static Solution failure() {
        return new Solution(false, null, 0);
    }

    public void print(PrintWriter out) {
        if (!isPossible) {
            out.println("NO");
            return;
        }

        out.println("YES");
        int center = gridSize - 1;
        for (int i = 0; i < shiftPattern.length; i++) {
            for (int j = 0; j < shiftPattern[i].length; j++) {
                if (i == center && j == center) {
                    out.print('o');
                } else if (shiftPattern[i][j]) {
                    out.print('x');
                } else {
                    out.print('.');
                }
            }
            out.println();
        }
    }
}

/**
 * Contains the logic to solve the grid problem.
 */
class GridSolver {

    public Solution solve(FastScanner scanner) {
        int n = scanner.nextInt();
        char[][] cells = new char[n][n];
        for (int i = 0; i < n; i++) {
            cells[i] = scanner.next().toCharArray();
        }

        Grid grid = new Grid(n, cells);
        return computeSolution(grid);
    }

    private Solution computeSolution(Grid grid) {
        int n = grid.getSize();
        List<Point> pieces = grid.getPiecePositions();

        // hitMask tracks which shifts (dr, dc) are valid
        boolean[][] validShiftsMask = new boolean[2 * n - 1][2 * n - 1];
        // coverageMask tracks which cells are covered by pieces across all valid shifts
        boolean[][] coverageMask = new boolean[n][n];

        // Iterate through all possible relative shifts
        for (int dr = -(n - 1); dr <= n - 1; dr++) {
            for (int dc = -(n - 1); dc <= n - 1; dc++) {
                if (isShiftValid(grid, pieces, dr, dc)) {
                    validShiftsMask[n - 1 + dr][n - 1 + dc] = true;
                    applyShiftToCoverage(coverageMask, pieces, dr, dc, n);
                }
            }
        }

        if (checkCoverageMatch(grid, coverageMask)) {
            return Solution.success(validShiftsMask, n);
        } else {
            return Solution.failure();
        }
    }

    private boolean isShiftValid(Grid grid, List<Point> pieces, int dr, int dc) {
        for (Point p : pieces) {
            int nr = p.row() + dr;
            int nc = p.col() + dc;

            // If the piece is within bounds, it must land on a cell that was under attack
            if (isWithinBounds(nr, nc, grid.getSize())) {
                if (!grid.isUnderAttack(nr, nc)) {
                    return false;
                }
            }
        }
        return true;
    }

    private void applyShiftToCoverage(boolean[][] coverageMask, List<Point> pieces, int dr, int dc, int n) {
        for (Point p : pieces) {
            int nr = p.row() + dr;
            int nc = p.col() + dc;
            if (isWithinBounds(nr, nc, n)) {
                coverageMask[nr][nc] = true;
            }
        }
    }

    private boolean checkCoverageMatch(Grid grid, boolean[][] coverageMask) {
        int n = grid.getSize();
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (coverageMask[r][c] != grid.isUnderAttack(r, c)) {
                    return false;
                }
            }
        }
        return true;
    }

    private boolean isWithinBounds(int r, int c, int n) {
        return r >= 0 && r < n && c >= 0 && c < n;
    }
}

