/**
 * Logic engine to solve the grid-based puzzle.
 */
class PuzzleSolver {

    public void solve(InputReader in, PrintWriter out) {
        int gridSize = in.nextInt();
        Set<Point> circles = new HashSet<>();
        Set<Point> crosses = new HashSet<>();

        // 1. Parse the input grid
        for (int i = 0; i < gridSize; i++) {
            String row = in.next();
            for (int j = 0; j < gridSize; j++) {
                char cell = row.charAt(j);
                if (cell == 'o') {
                    circles.add(new Point(i, j));
                } else if (cell == 'x') {
                    crosses.add(new Point(i, j));
                }
            }
        }

        // 2. Determine which relative shifts (dx, dy) are "allowed"
        // A shift is allowed if every circle, when shifted, lands on either a circle or a cross.
        Set<Point> allowedShifts = calculateAllowedShifts(gridSize, circles, crosses);

        // 3. Validate if every cross is "explained" by at least one circle via an allowed shift
        if (!allCrossesAreExplained(circles, crosses, allowedShifts)) {
            out.println("NO");
            return;
        }

        // 4. Output the result
        out.println("YES");
        printShiftGrid(gridSize, allowedShifts, out);
    }

    private Set<Point> calculateAllowedShifts(int n, Set<Point> circles, Set<Point> crosses) {
        Set<Point> allowedShifts = new HashSet<>();

        // Iterate through all possible relative shifts in the range [-n+1, n-1]
        for (int dx = -n + 1; dx < n; dx++) {
            for (int dy = -n + 1; dy < n; dy++) {
                if (isValidShift(dx, dy, n, circles, crosses)) {
                    allowedShifts.add(new Point(dx, dy));
                }
            }
        }
        return allowedShifts;
    }

    private boolean isValidShift(int dx, int dy, int n, Set<Point> circles, Set<Point> crosses) {
        for (Point circle : circles) {
            int nx = circle.getX() + dx;
            int ny = circle.getY() + dy;

            // If the shifted circle is within bounds
            if (nx >= 0 && nx < n && ny >= 0 && ny < n) {
                Point nextPos = new Point(nx, ny);
                // The target must be either a circle or a cross
                if (!circles.contains(nextPos) && !crosses.contains(nextPos)) {
                    return false;
                }
            }
            // Note: If the shifted circle lands outside the grid, 
            // the original logic skips it (continues), effectively treating it as 'OK'.
        }
        return true;
    }

    private boolean allCrossesAreExplained(Set<Point> circles, Set<Point> crosses, Set<Point> allowedShifts) {
        for (Point cross : crosses) {
            boolean explained = false;
            for (Point circle : circles) {
                int dx = cross.getX() - circle.getX();
                int dy = cross.getY() - circle.getY();

                if (allowedShifts.contains(new Point(dx, dy))) {
                    explained = true;
                    break;
                }
            }
            if (!explained) {
                return false;
            }
        }
        return true;
    }

    private void printShiftGrid(int n, Set<Point> allowedShifts, PrintWriter out) {
        int outputDim = 2 * n - 1;
        char[][] outputGrid = new char[outputDim][outputDim];

        // Initialize grid with '.'
        for (int i = 0; i < outputDim; i++) {
            Arrays.fill(outputGrid[i], '.');
        }

        // Mark allowed shifts as 'x'
        for (int i = 0; i < outputDim; i++) {
            for (int j = 0; j < outputDim; j++) {
                int dx = i - n + 1;
                int dy = j - n + 1;
                if (allowedShifts.contains(new Point(dx, dy))) {
                    outputGrid[i][j] = 'x';
                }
            }
        }

        // The center of the shift grid (0,0 shift) is always an 'o'
        outputGrid[n - 1][n - 1] = 'o';

        for (int i = 0; i < outputDim; i++) {
            out.println(new String(outputGrid[i]));
        }
    }
}

