/**
 * Handles the core logic of solving the grid-based puzzle.
 */
class GridProblemSolver {
    private static final char CELL_O = 'o';
    private static final char CELL_X = 'x';
    private static final char CELL_DOT = '.';

    /**
     * Solves the problem based on input grid.
     * 
     * @param in  The fast scanner for input.
     * @param out The fast printer for output.
     */
    public void solve(FastScanner in, FastPrinter out) {
        int n = in.nextInt();
        char[][] grid = in.readCharacterFieldTokens(n, n);

        // 1. Determine which relative offsets are "safe" to use.
        // An offset is unsafe if applying it to any 'o' lands on a '.'.
        boolean[][] isValidOffset = computeValidOffsets(grid, n);

        // 2. Calculate how many 'o' cells can cover each cell in the grid using safe offsets.
        int[][] coverageCount = computeCoverageCount(grid, isValidOffset, n);

        // 3. Verify if all 'x' cells are covered by at least one 'o'.
        if (!isRequirementSatisfied(grid, coverageCount, n)) {
            out.println("NO");
            return;
        }

        // 4. Output the resulting pattern.
        printResult(out, isValidOffset, n);
    }

    private boolean[][] computeValidOffsets(char[][] grid, int n) {
        int offsetSize = 2 * n - 1;
        boolean[][] isValidOffset = new boolean[offsetSize][offsetSize];
        for (boolean[] row : isValidOffset) {
            Arrays.fill(row, true);
        }

        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == CELL_O) {
                    // Check all possible relative offsets
                    for (int dr = -n + 1; dr < n; dr++) {
                        for (int dc = -n + 1; dc < n; dc++) {
                            int targetRow = r + dr;
                            int targetCol = c + dc;

                            // If an 'o' lands on a '.', that specific offset becomes invalid
                            if (isWithinBounds(targetRow, targetCol, n) && grid[targetRow][targetCol] == CELL_DOT) {
                                isValidOffset[getOffsetIndex(dr, n)][getOffsetIndex(dc, n)] = false;
                            }
                        }
                    }
                }
            }
        }
        return isValidOffset;
    }

    private int[][] computeCoverageCount(char[][] grid, boolean[][] isValidOffset, int n) {
        int[][] coverageCount = new int[n][n];
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == CELL_O) {
                    for (int dr = -n + 1; dr < n; dr++) {
                        for (int dc = -n + 1; dc < n; dc++) {
                            int targetRow = r + dr;
                            int targetCol = c + dc;

                            if (isWithinBounds(targetRow, targetCol, n)) {
                                if (isValidOffset[getOffsetIndex(dr, n)][getOffsetIndex(dc, n)]) {
                                    coverageCount[targetRow][targetCol]++;
                                }
                            }
                        }
                    }
                }
            }
        }
        return coverageCount;
    }

    private boolean isRequirementSatisfied(char[][] grid, int[][] coverageCount, int n) {
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == CELL_X && coverageCount[r][c] == 0) {
                    return false;
                }
            }
        }
        return true;
    }

    private void printResult(FastPrinter out, boolean[][] isValidOffset, int n) {
        out.println("YES");
        int offsetSize = 2 * n - 1;
        int centerIdx = n - 1;

        for (int i = 0; i < offsetSize; i++) {
            for (int j = 0; j < offsetSize; j++) {
                if (i == centerIdx && j == centerIdx) {
                    out.print(CELL_O);
                } else if (isValidOffset[i][j]) {
                    out.print(CELL_X);
                } else {
                    out.print(CELL_DOT);
                }
            }
            out.println();
        }
    }

    private boolean isWithinBounds(int r, int c, int n) {
        return r >= 0 && r < n && c >= 0 && c < n;
    }

    private int getOffsetIndex(int offset, int n) {
        return offset + n - 1;
    }
}

/**
 * Optimized reader for fast input processing.
 */
class FastScanner {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    public FastScanner(InputStream is) {
        this.reader = new BufferedReader(new InputStreamReader(is));
    }

    public String next() {
        while (tokenizer == null || !tokenizer.hasMoreElements()) {
            try {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                return null;
            }
        }
        return tokenizer.nextToken();
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }

    public char[][] readCharacterFieldTokens(int rows, int cols) {
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = next();
            if (line == null) throw new RuntimeException("Unexpected EOF");
            grid[i] = line.toCharArray();
            if (grid[i].length != cols) {
                throw new IllegalArgumentException("Expected column width " + cols + " but found " + grid[i].length);
            }
        }
        return grid;
    }
}

