/**
 * Refactored solution for the grid pattern generation problem.
 * The goal is to generate an expanded grid that covers all 'x' markers in an input grid
 * without ever hitting a '.' (empty) cell when the 'o' pattern is shifted.
 */
public class Template {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = reader.nextInt();
        if (n <= 0) {
            out.close();
            return;
        }

        char[][] inputGrid = new char[n][n];
        List<Point> oPositions = new ArrayList<>();

        // Read input grid and identify positions of 'o'
        for (int i = 0; i < n; i++) {
            String line = reader.next();
            for (int j = 0; j < n; j++) {
                inputGrid[i][j] = line.charAt(j);
                if (inputGrid[i][j] == 'o') {
                    oPositions.add(new Point(i, j));
                }
            }
        }

        // The expanded grid size is (2N - 1)
        int expandedSize = 2 * n - 1;
        int offset = n - 1;

        // 1. Construct the expanded grid
        // expandedGrid[i][j] represents a pattern of 'x's placed in a larger field
        char[][] expandedGrid = new char[expandedSize][expandedSize];
        for (int i = 0; i < expandedSize; i++) {
            Arrays.fill(expandedGrid[i], '.');
        }

        // The center of the expanded grid is the reference point for the 'o' pattern
        expandedGrid[offset][offset] = 'o';

        for (int i = 0; i < expandedSize; i++) {
            for (int j = 0; j < expandedSize; j++) {
                // Skip the center which is already set to 'o'
                if (i == offset && j == offset) {
                    continue;
                }

                int dy = i - offset;
                int dx = j - offset;
                boolean isSafeToPlaceX = true;

                // Check if placing an 'x' at (i, j) would result in any 'o' landing on a '.'
                for (Point p : oPositions) {
                    int ny = p.r + dy;
                    int nx = p.c + dx;

                    if (ny >= 0 && ny < n && nx >= 0 && nx < n) {
                        if (inputGrid[ny][nx] == '.') {
                            isSafeToPlaceX = false;
                            break;
                        }
                    }
                }

                if (isSafeToPlaceX) {
                    expandedGrid[i][j] = 'x';
                }
            }
        }

        // 2. Validate coverage
        // Check if every 'x' in the input grid is actually covered by the generated 'x' pattern
        boolean[][] covered = new boolean[n][n];
        for (int i = 0; i < expandedSize; i++) {
            for (int j = 0; j < expandedSize; j++) {
                if (expandedGrid[i][j] == 'x') {
                    int dy = i - offset;
                    int dx = j - offset;
                    for (Point p : oPositions) {
                        int ny = p.r + dy;
                        int nx = p.c + dx;
                        if (ny >= 0 && ny < n && nx >= 0 && nx < n) {
                            covered[ny][nx] = true;
                        }
                    }
                }
            }
        }

        boolean isSolutionValid = true;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (inputGrid[i][j] == 'x' && !covered[i][j]) {
                    isSolutionValid = false;
                    break;
                }
            }
            if (!isSolutionValid) break;
        }

        // 3. Output the result
        if (isSolutionValid) {
            out.println("YES");
            for (int i = 0; i < expandedSize; i++) {
                out.println(new String(expandedGrid[i]));
            }
        } else {
            out.println("NO");
        }

        out.flush();
        out.close();
    }

    /**
     * Simple data structure to hold 2D coordinates.
     */
    static class Point {
        final int r, c;
        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * High-performance reader for fast I/O operations.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * A solver that validates a grid pattern of pieces ('o') and marks ('x')
 * and constructs a larger symmetric pattern based on valid offsets.
 */
public class GridPatternSolver {

    private static final char EMPTY = '.';
    private static final char PIECE = 'o';
    private static final char MARK = 'x';

    private final int gridSize;
    private final char[][] grid;
    private final List<Point> pieceLocations;

    /**
     * Represents a coordinate in the grid.
     */
    private static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    public GridPatternSolver(int gridSize, char[][] grid) {
        this.gridSize = gridSize;
        this.grid = grid;
        this.pieceLocations = new ArrayList<>();
        initializePieceLocations();
    }

    /**
     * Finds all 'o' pieces in the input grid.
     */
    private void initializePieceLocations() {
        for (int r = 0; r < gridSize; r++) {
            for (int c = 0; c < gridSize; c++) {
                if (grid[r][c] == PIECE) {
                    pieceLocations.add(new Point(r, c));
                }
            }
        }
    }

    /**
     * Validates if every 'x' in the current grid is "explained" by at least one 'o'.
     * An 'x' is explained if the relative offset from a piece to the 'x' is "possible".
     * An offset (dr, dc) is possible if, for every existing piece, the cell at
     * (piece.row + dr, piece.col + dc) is not an empty cell ('.').
     */
    public boolean validate() {
        for (int r = 0; r < gridSize; r++) {
            for (int c = 0; c < gridSize; c++) {
                if (grid[r][c] == MARK) {
                    if (!isMarkExplained(r, c)) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    private boolean isMarkExplained(int markRow, int markCol) {
        for (Point piece : pieceLocations) {
            int dr = markRow - piece.row;
            int dc = markCol - piece.col;
            if (isOffsetValid(dr, dc)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Determines if a specific offset (dr, dc) is valid across all pieces.
     */
    private boolean isOffsetValid(int dr, int dc) {
        for (Point piece : pieceLocations) {
            int targetR = piece.row + dr;
            int targetC = piece.col + dc;

            // If the shifted position is within bounds and lands on an empty cell, the offset is invalid.
            if (isInBounds(targetR, targetC) && grid[targetR][targetC] == EMPTY) {
                return false;
            }
        }
        return true;
    }

    private boolean isInBounds(int r, int c) {
        return r >= 0 && r < gridSize && c >= 0 && c < gridSize;
    }

    /**
     * Constructs the resulting expanded grid of size (2n-1) x (2n-1).
     */
    public char[][] constructResultGrid() {
        int newSize = 2 * gridSize - 1;
        char[][] result = new char[newSize][newSize];

        // Initialize with empty cells
        for (int r = 0; r < newSize; r++) {
            for (int c = 0; c < newSize; c++) {
                result[r][c] = EMPTY;
            }
        }

        // Place the central piece at the center of the new grid
        int center = gridSize - 1;
        result[center][center] = PIECE;

        // Apply all valid offsets within the bounds of the new grid
        // The maximum possible offset in a (2n-1) grid from the center is (n-1)
        for (int dr = -(gridSize - 1); dr <= (gridSize - 1); dr++) {
            for (int dc = -(gridSize - 1); dc <= (gridSize - 1); dc++) {
                if (dr == 0 && dc == 0) continue;

                if (isOffsetValid(dr, dc)) {
                    int targetR = center + dr;
                    int targetC = center + dc;
                    result[targetR][targetC] = MARK;
                }
            }
        }
        return result;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        if (!sc.hasNextInt()) {
            sc.close();
            return;
        }

        int n = sc.nextInt();
        char[][] inputGrid = new char[n][n];
        for (int i = 0; i < n; i++) {
            inputGrid[i] = sc.next().toCharArray();
        }

        GridPatternSolver solver = new GridPatternSolver(n, inputGrid);

        if (!solver.validate()) {
            System.out.println("NO");
        } else {
            System.out.println("YES");
            char[][] result = solver.constructResultGrid();
            printGrid(result);
        }

        sc.close();
    }

    private static void printGrid(char[][] grid) {
        StringBuilder sb = new StringBuilder();
        for (char[] row : grid) {
            sb.append(new String(row)).append("\n");
        }
        System.out.print(sb.toString());
    }
}

import java.util.*;

/**
 * A solver for a grid-based placement puzzle.
 * The goal is to determine a valid offset pattern that satisfies piece constraints.
 */
public class BoardPuzzleSolver {

    // Input/Output Constants
    private static final char CHAR_EMPTY = '.';
    private static final char CHAR_PIECE = 'o';
    private static final char CHAR_SOLUTION_MARKER = 'x';
    private static final char CHAR_CONFLICT_MARKER = 'X';

    /**
     * Represents a 2D coordinate on the board.
     */
    private record Point(int row, int col) {}

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int boardSize = scanner.nextInt();
        scanner.nextLine(); // Consume newline

        char[][] board = readBoard(scanner, boardSize);
        solveAndPrint(board, boardSize);
    }

    /**
     * Reads the n x n board from standard input.
     */
    private static char[][] readBoard(Scanner scanner, int size) {
        char[][] board = new char[size][size];
        for (int i = 0; i < size; i++) {
            String line = scanner.nextLine();
            board[i] = line.trim().toCharArray();
        }
        return board;
    }

    /**
     * Orchestrates the solving logic and outputs the result.
     */
    private static void solveAndPrint(char[][] board, int n) {
        int m = 2 * n - 1;
        int mid = n - 1;
        char[][] solutionBoard = new char[m][m];

        // Initialize solution board
        for (int i = 0; i < m; i++) {
            Arrays.fill(solutionBoard[i], CHAR_EMPTY);
        }
        solutionBoard[mid][mid] = CHAR_PIECE;

        List<Point> pieces = findPiecePositions(board, n);

        // Iterate through all possible offsets in the solution grid
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < m; j++) {
                int dr = i - mid;
                int dc = j - mid;

                // Skip the center offset
                if (dr == 0 && dc == 0) {
                    continue;
                }

                if (isOffsetAttacked(board, pieces, n, dr, dc)) {
                    solutionBoard[i][j] = CHAR_SOLUTION_MARKER;
                    applyConflictCheck(board, pieces, n, dr, dc);
                }
            }
        }

        if (hasConflicts(board, n)) {
            System.out.println("NO");
        } else {
            System.out.println("YES");
            printGrid(solutionBoard);
        }
    }

    /**
     * Finds all coordinates containing the piece marker.
     */
    private static List<Point> findPiecePositions(char[][] board, int n) {
        List<Point> pieces = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (board[i][j] == CHAR_PIECE) {
                    pieces.add(new Point(i, j));
                }
            }
        }
        return pieces;
    }

    /**
     * Determines if a specific offset (dr, dc) is "attacked".
     * An offset is attacked if every piece, when shifted, lands on a non-empty cell.
     */
    private static boolean isOffsetAttacked(char[][] board, List<Point> pieces, int n, int dr, int dc) {
        boolean attacked = true;
        for (Point p : pieces) {
            int nr = p.row() + dr;
            int nc = p.col() + dc;

            // If the shifted piece is within bounds, it must not be on an empty cell
            if (nr >= 0 && nr < n && nc >= 0 && nc < n) {
                if (board[nr][nc] == CHAR_EMPTY) {
                    attacked = false;
                    break;
                }
            }
        }
        return attacked;
    }

    /**
     * If an offset is valid, we check if it conflicts with existing 'x' markers in the input board.
     */
    private static void applyConflictCheck(char[][] board, List<Point> pieces, int n, int dr, int dc) {
        for (Point p : pieces) {
            int nr = p.row() + dr;
            int nc = p.col() + dc;

            if (nr >= 0 && nr < n && nc >= 0 && nc < n) {
                if (board[nr][nc] == CHAR_SOLUTION_MARKER) {
                    board[nr][nc] = CHAR_CONFLICT_MARKER;
                }
            }
        }
    }

    /**
     * Checks if the original board contains any 'x' markers that weren't neutralized.
     */
    private static boolean hasConflicts(char[][] board, int n) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (board[i][j] == CHAR_SOLUTION_MARKER) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Prints the 2D grid to standard output.
     */
    private static void printGrid(char[][] grid) {
        StringBuilder sb = new StringBuilder();
        for (char[] row : grid) {
            for (char cell : row) {
                sb.append(cell);
            }
            sb.append("\n");
        }
        System.out.print(sb.toString());
    }
}

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

/**
 * A program that solves a grid-based pattern problem.
 * It finds a set of offsets such that shifting the 'o' elements 
 * covers all 'x' elements without landing on any '.' elements.
 */
public class Main {

    public static void main(String[] args) {
        try {
            FastReader reader = new FastReader(System.in);
            int gridSize = reader.nextInt();

            GridSolver solver = new GridSolver(gridSize, reader);
            solver.solve();
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Represents a coordinate in the 2D grid.
     */
    static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Handles efficient input reading.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            this.reader = new BufferedReader(new InputStreamReader(inputStream, StandardCharsets.ISO_8859_1));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public void close() throws IOException {
            reader.close();
        }
    }

    /**
     * Contains the core logic for solving the grid pattern problem.
     */
    static class GridSolver {
        private final int size;
        private final char[][] grid;
        private final List<Point> oPositions = new ArrayList<>();
        private final List<Point> xPositions = new ArrayList<>();
        private final List<Point> validOffsets = new ArrayList<>();
        private final boolean[][] isCovered;

        public GridSolver(int size, FastReader reader) throws IOException {
            this.size = size;
            this.grid = new char[size][size];
            this.isCovered = new boolean[size][size];
            readGrid(reader);
            identifySpecialPoints();
        }

        private void readGrid(FastReader reader) throws IOException {
            for (int i = 0; i < size; i++) {
                String rowStr = reader.next();
                for (int j = 0; j < size; j++) {
                    grid[i][j] = rowStr.charAt(j);
                }
            }
        }

        private void identifySpecialPoints() {
            for (int i = 0; i < size; i++) {
                for (int j = 0; j < size; j++) {
                    if (grid[i][j] == 'o') {
                        oPositions.add(new Point(i, j));
                    } else if (grid[i][j] == 'x') {
                        xPositions.add(new Point(i, j));
                    }
                }
            }
        }

        public void solve() throws IOException {
            findValidOffsets();

            if (areAllXCovered()) {
                printResult(true);
            } else {
                printResult(false);
            }
        }

        private void findValidOffsets() {
            // Iterate through all possible relative offsets
            for (int dr = -size + 1; dr < size; dr++) {
                for (int dc = -size + 1; dc < size; dc++) {
                    // Skip the zero offset as per original logic
                    if (dr == 0 && dc == 0) continue;

                    if (isValidOffset(dr, dc)) {
                        validOffsets.add(new Point(dr, dc));
                        markCoveredPositions(dr, dc);
                    }
                }
            }
        }

        private boolean isValidOffset(int dr, int dc) {
            for (Point p : oPositions) {
                int targetR = p.row + dr;
                int targetC = p.col + dc;

                // If the shifted 'o' is within bounds, it must not land on '.'
                if (isInBounds(targetR, targetC)) {
                    if (grid[targetR][targetC] == '.') {
                        return false;
                    }
                }
            }
            return true;
        }

        private void markCoveredPositions(int dr, int dc) {
            for (Point p : oPositions) {
                int targetR = p.row + dr;
                int targetC = p.col + dc;
                if (isInBounds(targetR, targetC)) {
                    isCovered[targetR][targetC] = true;
                }
            }
        }

        private boolean areAllXCovered() {
            for (Point p : xPositions) {
                if (!isCovered[p.row][p.col]) {
                    return false;
                }
            }
            return true;
        }

        private boolean isInBounds(int r, int c) {
            return r >= 0 && r < size && c >= 0 && c < size;
        }

        private void printResult(boolean success) throws IOException {
            PrintWriter out = new PrintWriter(System.out);
            if (!success) {
                out.println("NO");
            } else {
                out.println("YES");
                renderOutputGrid(out);
            }
            out.flush();
        }

        private void renderOutputGrid(PrintWriter out) {
            int outputSize = 2 * size - 1;
            char[][] outputGrid = new char[outputSize][outputSize];

            // Initialize with '.'
            for (int i = 0; i < outputSize; i++) {
                Arrays.fill(outputGrid[i], '.');
            }

            // The center of the output represents the (0,0) offset
            int center = size - 1;
            outputGrid[center][center] = 'o';

            // Place 'x' at positions representing the valid offsets
            for (Point offset : validOffsets) {
                outputGrid[center + offset.row][center + offset.col] = 'x';
            }

            // Print the pattern
            for (int i = 0; i < outputSize; i++) {
                out.println(new String(outputGrid[i]));
            }
        }
    }
}

