/**
 * GridSolver contains the core logic to solve the grid-based pattern problem.
 */
class GridSolver {

    /**
     * Solves the grid problem based on the provided input.
     * 
     * @param in  The FastReader for input parsing.
     * @param out The PrintWriter for output.
     * @throws IOException If an I/O error occurs.
     */
    public void solve(FastReader in, PrintWriter out) throws IOException {
        int n = in.nextInt();
        if (n <= 0) {
            return;
        }

        String[] grid = new String[n];
        for (int i = 0; i < n; i++) {
            grid[i] = in.next();
        }

        // The 'moves' matrix tracks relative offsets.
        // It is initialized with 'x' (representing invalid moves).
        int movesSize = 2 * n - 1;
        char[][] moves = new char[movesSize][movesSize];
        for (int i = 0; i < movesSize; i++) {
            Arrays.fill(moves[i], 'x');
        }

        // The center of the moves matrix is the reference origin.
        moves[n - 1][n - 1] = 'o';

        // First Pass: Map valid relative moves from 'o' cells using '.' cells in the grid.
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i].charAt(j) == 'o') {
                    for (int k = 0; k < n; k++) {
                        for (int m = 0; m < n; m++) {
                            if (grid[k].charAt(m) == '.') {
                                int targetRow = n - 1 + (k - i);
                                int targetCol = n - 1 + (m - j);
                                moves[targetRow][targetCol] = '.';
                            }
                        }
                    }
                }
            }
        }

        // Second Pass: Verify if every 'x' cell is covered by a valid 'o' cell movement.
        boolean isValid = true;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i].charAt(j) == 'x') {
                    boolean hasXMove = false;
                    for (int k = 0; k < n; k++) {
                        for (int m = 0; m < n; m++) {
                            if (grid[k].charAt(m) == 'o') {
                                // Check if the move from 'o' at (k,m) to 'x' at (i,j) is an 'x' move.
                                int relativeRow = n - 1 + (i - k);
                                int relativeCol = n - 1 + (j - m);

                                if (moves[relativeRow][relativeCol] == 'x') {
                                    hasXMove = true;
                                }
                            }
                        }
                    }
                    // If no 'o' satisfies the 'x' move condition for this 'x', the configuration is invalid.
                    if (!hasXMove) {
                        isValid = false;
                        break;
                    }
                }
            }
            if (!isValid) break;
        }

        // Final Output
        if (isValid) {
            out.println("YES");
            for (char[] row : moves) {
                out.println(row);
            }
        } else {
            out.println("NO");
        }
    }
}

/**
 * FastReader provides an efficient way to read large inputs using BufferedReader and StringTokenizer.
 */
class FastReader implements AutoCloseable {
