                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                throw new RuntimeException("Error reading input", e);
            }
        }
        return tokenizer.nextToken();
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }

    @Override
    public void close() throws IOException {
        reader.close();
    }
}

import java.util.*;
import java.io.*;

/**
 * A solver for finding a pattern of relative offsets that reconstructs a given grid.
 */
public class GridPatternSolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            solve(reader, out);
        } catch (Exception e) {
            // In a real-world scenario, use a logger
            e.printStackTrace();
        } finally {
            out.close();
        }
    }

    private static void solve(FastReader reader, PrintWriter out) {
        int gridSize = reader.nextInt();
        char[][] gridData = new char[gridSize][gridSize];
        List<Point> oPositions = new ArrayList<>();

        for (int i = 0; i < gridSize; i++) {
            String line = reader.next();
            for (int j = 0; j < gridSize; j++) {
                gridData[i][j] = line.charAt(j);
                if (gridData[i][j] == 'o') {
                    oPositions.add(new Point(i, j));
                }
            }
        }

        Grid inputGrid = new Grid(gridData);

        // If no 'o' exists, the pattern is trivial or undefined based on problem constraints.
        if (oPositions.isEmpty()) {
            out.println("YES");
            printGrid(new Grid(new char[1][1]), out); // Placeholder
            return;
        }

        Set<Offset> validOffsets = findValidOffsets(inputGrid, oPositions);

        if (isPatternValid(inputGrid, oPositions, validOffsets)) {
            out.println("YES");
            Grid resultGrid = buildResultGrid(gridSize, oPositions, validOffsets);
            printGrid(resultGrid, out);
        } else {
            out.println("NO");
        }
    }

    /**
     * Finds the set of relative offsets that could potentially form the pattern.
     */
    private static Set<Offset> findValidOffsets(Grid grid, List<Point> oPositions) {
        Set<Offset> offsets = new TreeSet<>();
        Point firstO = oPositions.get(0);

        // Step 1: Candidate selection based on the first 'o'
        // We check all possible relative offsets that land on 'x', 'o', or out of bounds.
        int N = grid.getSize();
        for (int dr = -(N - 1); dr <= N - 1; dr++) {
            for (int dc = -(N - 1); dc <= N - 1; dc++) {
                int targetR = firstO.r + dr;
                int targetC = firstO.c + dc;

                if (!grid.isWithinBounds(targetR, targetC) || 
                     grid.getChar(targetR, targetC) == 'x' || 
                     grid.getChar(targetR, targetC) == 'o') {
                    offsets.add(new Offset(dr, dc));
                }
            }
        }

        // Step 2: Refinement
        // Remove offsets that would cause any 'o' to land on a '.'
        for (Point p : oPositions) {
            Iterator<Offset> it = offsets.iterator();
            while (it.hasNext()) {
                Offset off = it.next();
                int targetR = p.r + off.dr;
                int targetC = p.c + off.dc;
                if (grid.isWithinBounds(targetR, targetC) && grid.getChar(targetR, targetC) == '.') {
                    it.remove();
                }
            }
        }

        return offsets;
    }

    /**
     * Verifies if applying the offsets to the 'o' positions reproduces the input grid.
     */
    private static boolean isPatternValid(Grid inputGrid, List<Point> oPositions, Set<Offset> offsets) {
        int N = inputGrid.getSize();
        Grid verificationGrid = new Grid(N);

        // Place original 'o's
        for (Point p : oPositions) {
            verificationGrid.setChar(p.r, p.c, 'o');
        }

        // Apply offsets to transform 'o's into 'x's where appropriate
        for (Offset off : offsets) {
            for (Point p : oPositions) {
                verificationGrid.setIfEmpty(p.r + off.dr, p.c + off.dc, 'x');
            }
        }

        // Compare constructed grid with original
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                if (inputGrid.getChar(i, j) != verificationGrid.getChar(i, j)) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Constructs the larger (2N-1) grid requested in the output.
     */
    private static Grid buildResultGrid(int n, List<Point> oPositions, Set<Offset> offsets) {
        int expandedSize = 2 * n - 1;
        Grid result = new Grid(expandedSize);
        int center = n - 1;

        result.setChar(center, center, 'o');

        // For each valid offset, apply it to the single 'o' at the center
        for (Offset off : offsets) {
            result.setIfEmpty(center + off.dr, center + off.dc, 'x');
        }
        return result;
    }

    private static void printGrid(Grid grid, PrintWriter out) {
        for (int i = 0; i < grid.getSize(); i++) {
            out.println(grid.getRowString(i));
        }
    }

    // --- Helper Classes ---

    static class Point {
        final int r, c;
        Point(int r, int c) { this.r = r; this.c = c; }
    }

    static class Offset implements Comparable<Offset> {
        final int dr, dc;
        Offset(int dr, int dc) { this.dr = dr; this.dc = dc; }

        @Override
        public int compareTo(Offset other) {
            if (this.dr != other.dr) return Integer.compare(this.dr, other.dr);
            return Integer.compare(this.dc, other.dc);
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Offset)) return false;
            Offset offset = (Offset) o;
            return dr == offset.dr && dc == offset.dc;
        }

        @Override
        public int hashCode() {
            return Objects.hash(dr, dc);
        }
    }

    static class Grid {
        private final char[][] cells;
        private final int size;

        Grid(int size) {
            this.size = size;
            this.cells = new char[size][size];
            for (int i = 0; i < size; i++) {
                Arrays.fill(cells[i], '.');
            }
        }

        Grid(char[][] data) {
            this.size = data.length;
            this.cells = data;
        }

        int getSize() { return size; }

        boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < size && c >= 0 && c < size;
        }

        char getChar(int r, int c) {
            return isWithinBounds(r, c) ? cells[r][c] : ' '; // ' ' represents out of bounds
        }

        void setChar(int r, int c, char val) {
            if (isWithinBounds(r, c)) cells[r][c] = val;
        }

        void setIfEmpty(int r, int c, char val) {
            if (isWithinBounds(r, c) && cells[r][c] == '.') {
                cells[r][c] = val;
            }
        }

        String getRowString(int r) {
            return new String(cells[r]);
        }
    }

    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() { return Integer.parseInt(next()); }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver for grid-based pattern matching problems.
 * The goal is to find all valid shifts of 'o' characters such that no 'o' lands on a '.' cell,
 * and then determine if all 'x' cells in the original grid are covered by these shifts.
 */
public class GridPatternSolver {

    private static final char EMPTY = '.';
    private static final char X_CELL = 'x';
    private static final char O_CELL = 'o';

    private final FastScanner scanner;
    private final PrintWriter writer;

    public GridPatternSolver() {
        this.scanner = new FastScanner(System.in);
        this.writer = new PrintWriter(System.out);
    }

    /**
     * Represents a coordinate in a 2D grid.
     */
    record Point(int x, int y) {}

    public void solve() {
        int gridSize = scanner.nextInt();
        if (gridSize <= 0) return;

        char[][] inputGrid = readGrid(gridSize);
        List<Point> xPoints = new ArrayList<>();
        List<Point> oPoints = new ArrayList<>();

        // Identify coordinates of all 'x' and 'o' cells
        for (int r = 0; r < gridSize; r++) {
            for (int c = 0; c < gridSize; c++) {
                if (inputGrid[r][c] == X_CELL) {
                    xPoints.add(new Point(c, r));
                } else if (inputGrid[r][c] == O_CELL) {
                    oPoints.add(new Point(c, r));
                }
            }
        }

        boolean[][] isXCovered = new boolean[gridSize][gridSize];
        char[][] resultGrid = initializeResultGrid(gridSize);

        // Iterate through all possible relative offsets
        int offsetRange = gridSize - 1;
        for (int offsetX = -offsetRange; offsetX <= offsetRange; offsetX++) {
            for (int offsetY = -offsetRange; offsetY <= offsetRange; offsetY++) {
                if (offsetX == 0 && offsetY == 0) continue;

                if (isValidOffset(inputGrid, oPoints, offsetX, offsetY, gridSize)) {
                    markCoverage(inputGrid, oPoints, isXCovered, offsetX, offsetY, gridSize);
                    // Place 'x' in the expanded result grid representing this valid shift
                    resultGrid[gridSize + offsetY - 1][gridSize + offsetX - 1] = X_CELL;
                }
            }
        }

        if (checkAllXCovered(inputGrid, xPoints, isXCovered)) {
            printResult(true, resultGrid);
        } else {
            printResult(false, null);
        }

        writer.flush();
        writer.close();
    }

    private char[][] readGrid(int size) {
        char[][] grid = new char[size][];
        for (int i = 0; i < size; i++) {
            grid[i] = scanner.next().toCharArray();
        }
        return grid;
    }

    private char[][] initializeResultGrid(int n) {
        int size = 2 * n - 1;
        char[][] res = new char[size][size];
        for (int i = 0; i < size; i++) {
            Arrays.fill(res[i], EMPTY);
        }
        // The center of the result grid represents the original (0,0) offset
        res[n - 1][n - 1] = O_CELL;
        return res;
    }

    /**
     * Checks if a shift (offsetX, offsetY) is valid.
     * A shift is valid if no 'o' lands on a '.' cell.
     */
    private boolean isValidOffset(char[][] grid, List<Point> oPoints, int dx, int dy, int n) {
        for (Point p : oPoints) {
            int nx = p.x() + dx;
            int ny = p.y() + dy;
            if (nx >= 0 && nx < n && ny >= 0 && ny < n) {
                if (grid[ny][nx] == EMPTY) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Marks the 'x' cells in the original grid as covered if they are 
     * hit by a shifted 'o'.
     */
    private void markCoverage(char[][] grid, List<Point> oPoints, boolean[][] isXCovered, int dx, int dy, int n) {
        for (Point p : oPoints) {
            int nx = p.x() + dx;
            int ny = p.y() + dy;
            if (nx >= 0 && nx < n && ny >= 0 && ny < n && grid[ny][nx] == X_CELL) {
                isXCovered[ny][nx] = true;
            }
        }
    }

    private boolean checkAllXCovered(char[][] grid, List<Point> xPoints, boolean[][] isXCovered) {
        for (Point p : xPoints) {
            if (!isXCovered[p.y()][p.x()]) {
                return false;
            }
        }
        return true;
    }

    private void printResult(boolean success, char[][] resultGrid) {
        if (!success) {
            writer.println("NO");
            return;
        }

        writer.println("YES");
        for (char[] row : resultGrid) {
            writer.println(new String(row));
        }
    }

    public static void main(String[] args) {
        new GridPatternSolver().solve();
    }

    /**
     * Fast I/O utility class for efficient input reading.
     */
    static class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int pointer = 0;
        private int bytesRead = 0;

        public FastScanner(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() {
            if (pointer >= bytesRead) {
                pointer = 0;
                try {
                    bytesRead = stream.read(buffer);
                } catch (IOException e) {
                    return -1;
                }
                if (bytesRead <= 0) return -1;
            }
            return buffer[pointer++];
        }

        public String next() {
            int b = readByte();
            while (b != -1 && b <= 32) b = readByte();
            if (b == -1) return "";
            StringBuilder sb = new StringBuilder();
            while (b > 32) {
                sb.append((char) b);
                b = readByte();
            }
            return sb.toString();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

