class GridSolver {
    private static final char SHAPE_CHAR = 'o';
    private static final char TARGET_CHAR = 'x';
    private static final char EMPTY_CHAR = '.';

    private final int gridSize;
    private final char[][] originalGrid;
    private final List<Point> shapePositions;

    /**
     * Represents a coordinate in the 2D grid.
     */
    public record Point(int row, int col) {}

    /**
     * Represents the outcome of the solver.
     */
    public static class Result {
        private final boolean success;
        private final char[][] grid;

        public Result(boolean success, char[][] grid) {
            this.success = success;
            this.grid = grid;
        }

        public boolean isSuccess() { return success; }
        public char[][] getGrid() { return grid; }
    }

    public GridSolver(int gridSize, char[][] originalGrid) {
        this.gridSize = gridSize;
        this.originalGrid = originalGrid;
        this.shapePositions = findShapePositions();
    }

    /**
     * Locates all occurrences of the shape character in the input grid.
     */
    private List<Point> findShapePositions() {
        List<Point> positions = new ArrayList<>();
        for (int i = 0; i < gridSize; i++) {
            for (int j = 0; j < gridSize; j++) {
                if (originalGrid[i][j] == SHAPE_CHAR) {
                    positions.add(new Point(i, j));
                }
            }
        }
        return positions;
    }

    /**
     * Executes the core logic to reconstruct the result grid.
     * @return A Result object containing the success status and the resulting grid.
     */
    public Result solve() {
        int resDim = 2 * gridSize - 1;
        char[][] resultGrid = new char[resDim][resDim];

        // Initialize result grid with empty characters
        for (int i = 0; i < resDim; i++) {
            Arrays.fill(resultGrid[i], EMPTY_CHAR);
        }

        // 1. Calculate potential target placements in the result grid
        for (int dr = -gridSize + 1; dr < gridSize; dr++) {
            for (int dc = -gridSize + 1; dc < gridSize; dc++) {
                // Skip the center which is reserved for the shape itself
                if (dr == 0 && dc == 0) continue;

                boolean hitsEmpty = false;
                for (Point p : shapePositions) {
                    int nr = p.row() + dr;
                    int nc = p.col() + dc;

                    if (isWithinBounds(nr, nc) && originalGrid[nr][nc] == EMPTY_CHAR) {
                        hitsEmpty = true;
                        break;
                    }
                }

                // If the shape at this offset doesn't hit any '.', it's a potential target
                resultGrid[gridSize - 1 + dr][gridSize - 1 + dc] = hitsEmpty ? EMPTY_CHAR : TARGET_CHAR;
            }
        }

        // Place the original shape in the center of the result grid
        resultGrid[gridSize - 1][gridSize - 1] = SHAPE_CHAR;

        // 2. Verify if the result grid covers all target characters in the original grid
        char[][] workingGrid = copyGrid(originalGrid);
        for (int dr = -gridSize + 1; dr < gridSize; dr++) {
            for (int dc = -gridSize + 1; dc < gridSize; dc++) {
                if (resultGrid[gridSize - 1 + dr][gridSize - 1 + dc] == TARGET_CHAR) {
                    applyRemoval(workingGrid, dr, dc);
                }
            }
        }

        if (containsUncoveredTargets(workingGrid)) {
            return new Result(false, null);
        }

        return new Result(true, resultGrid);
    }

    private void applyRemoval(char[][] grid, int dr, int dc) {
        for (Point p : shapePositions) {
            int nr = p.row() + dr;
            int nc = p.col() + dc;
            if (isWithinBounds(nr, nc)) {
                grid[nr][nc] = EMPTY_CHAR;
            }
        }
    }

    private boolean containsUncoveredTargets(char[][] grid) {
        for (int i = 0; i < gridSize; i++) {
            for (int j = 0; j < gridSize; j++) {
                if (grid[i][j] == TARGET_CHAR) {
                    return true;
                }
            }
        }
        return false;
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < gridSize && c >= 0 && c < gridSize;
    }

    private char[][] copyGrid(char[][] source) {
        char[][] copy = new char[source.length][];
        for (int i = 0; i < source.length; i++) {
            copy[i] = source[i].clone();
        }
        return copy;
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver for a grid-based pattern matching problem.
 * The goal is to generate an offset grid that satisfies specific 
 * placement constraints based on an input pattern grid.
 */
public class GridPatternSolver {

    private static final char PATTERN_O = 'o';
    private static final char PATTERN_X = 'x';
    private static final char PATTERN_DOT = '.';

    private InputReader inputReader;
    private PrintWriter outputWriter;

    public static void main(String[] args) {
        new GridPatternSolver().run();
    }

    /**
     * Initializes resources and starts the solver.
     */
    public void run() {
        inputReader = new InputReader(System.in);
        outputWriter = new PrintWriter(System.out);

        try {
            solve();
        } finally {
            outputWriter.close();
        }
    }

    /**
     * Contains the core logic for constructing the offset grid and validating it.
     */
    private void solve() {
        int gridSize = inputReader.nextInt();
        char[][] patternGrid = new char[gridSize][gridSize];

        for (int i = 0; i < gridSize; i++) {
            patternGrid[i] = inputReader.next().toCharArray();
        }

        // The offset grid represents valid relative shifts. 
        // Its dimensions are (2n - 1) x (2n - 1) to cover all possible shifts.
        int offsetDim = 2 * gridSize - 1;
        char[][] offsetGrid = new char[offsetDim][offsetDim];

        // Determine which offsets are valid.
        // An offset (dr, dc) is valid if no 'o' in the pattern lands on a '.' in the original grid.
        for (int dr = -gridSize + 1; dr < gridSize; dr++) {
            for (int dc = -gridSize + 1; dc < gridSize; dc++) {
                boolean isValidShift = true;

                outerLoop:
                for (int r = 0; r < gridSize; r++) {
                    for (int c = 0; c < gridSize; c++) {
                        if (patternGrid[r][c] == PATTERN_O) {
                            int targetRow = r + dr;
                            int targetCol = c + dc;

                            // Check if the shifted 'o' lands on a '.' in the pattern grid
                            if (isWithinBounds(targetRow, targetCol, gridSize) && 
                                patternGrid[targetRow][targetCol] == PATTERN_DOT) {
                                isValidShift = false;
                                break outerLoop;
                            }
                        }
                    }
                }
                offsetGrid[dr + gridSize - 1][dc + gridSize - 1] = isValidShift ? PATTERN_X : PATTERN_DOT;
            }
        }

        // The zero-offset position is specifically marked as 'o' per problem requirements
        offsetGrid[gridSize - 1][gridSize - 1] = PATTERN_O;

        if (isPatternCovered(offsetGrid, patternGrid)) {
            outputWriter.println("YES");
            for (char[] row : offsetGrid) {
                outputWriter.println(new String(row));
            }
        } else {
            outputWriter.println("NO");
        }
    }

    /**
     * Validates if the generated offset grid successfully "covers" all 'x' cells 
     * in the original pattern grid through the valid shifts marked in offsetGrid.
     * 
     * @param offsetGrid The grid of valid shifts.
     * @param patternGrid The original pattern grid.
     * @return true if all 'x' cells in the pattern are covered.
     */
    private boolean isPatternCovered(char[][] offsetGrid, char[][] patternGrid) {
        int n = patternGrid.length;
        boolean[][] isXCellCovered = new boolean[n][n];

        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                // For every 'o' in the pattern, apply all valid offsets marked 'x'
                if (patternGrid[r][c] == PATTERN_O) {
                    for (int dr = -n + 1; dr < n; dr++) {
                        for (int dc = -n + 1; dc < n; dc++) {
                            int targetR = r + dr;
                            int targetC = c + dc;

                            // If this shift is valid ('x') and hits a valid cell in the pattern
                            if (isWithinBounds(targetR, targetC, n)) {
                                if (offsetGrid[dr + n - 1][dc + n - 1] == PATTERN_X) {
                                    isXCellCovered[targetR][targetC] = true;
                                }
                            }
                        }
                    }
                }
            }
        }

        // Final verification: ensure every 'x' in the pattern grid is covered
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (patternGrid[r][c] == PATTERN_X && !isXCellCovered[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    private boolean isWithinBounds(int r, int c, int limit) {
        return r >= 0 && r < limit && c >= 0 && c < limit;
    }

    /**
     * Fast I/O utility class.
     */
    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Scanner;

/**
 * A program that determines if a pattern of 'o' characters can be shifted
 * to cover all 'x' characters on a grid without overlapping any '.' characters.
 */
public class PatternCoverageSolverApp {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int gridSize = scanner.nextInt();
        char[][] grid = new char[gridSize][];
        for (int i = 0; i < gridSize; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        PatternCoverageSolver solver = new PatternCoverageSolver(gridSize, grid);
        solver.solve();

        scanner.close();
    }

    /**
     * Represents a coordinate on the grid.
     */
    private static class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Logic handler for finding valid shifts and checking pattern coverage.
     */
    private static class PatternCoverageSolver {
        private final int n;
        private final char[][] grid;
        private final List<Position> patternPoints = new ArrayList<>();
        private final List<Position> targetPoints = new ArrayList<>();

        public PatternCoverageSolver(int n, char[][] grid) {
            this.n = n;
            this.grid = grid;
            extractPositions();
        }

        /**
         * Scans the grid to identify the positions of the pattern ('o') 
         * and the targets ('x').
         */
        private void extractPositions() {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (grid[i][j] == 'o') {
                        patternPoints.add(new Position(i, j));
                    } else if (grid[i][j] == 'x') {
                        targetPoints.add(new Position(i, j));
                    }
                }
            }
        }

        /**
         * Orchestrates the solving process and outputs the result.
         */
        public void solve() {
            List<Position> validShifts = findValidShifts();
            boolean allTargetsCovered = checkCoverage(validShifts);

            if (allTargetsCovered) {
                System.out.println("YES");
                printShiftMap(validShifts);
            } else {
                System.out.println("NO");
            }
        }

        /**
         * Finds all shifts (dx, dy) where the pattern does not overlap a '.' cell.
         */
        private List<Position> findValidShifts() {
            List<Position> validShifts = new ArrayList<>();
            int range = n - 1;

            for (int dr = -range; dr <= range; dr++) {
                for (int dc = -range; dc <= range; dc++) {
                    if (isShiftValid(dr, dc)) {
                        validShifts.add(new Position(dr, dc));
                    }
                }
            }
            return validShifts;
        }

        /**
         * Validates if a specific shift is allowed.
         * A shift is invalid if any 'o' from the pattern lands on a '.' in the grid.
         */
        private boolean isShiftValid(int deltaRow, int deltaCol) {
            for (Position p : patternPoints) {
                int newRow = p.row + deltaRow;
                int newCol = p.col + deltaCol;

                if (isWithinBounds(newRow, newCol)) {
                    if (grid[newRow][newCol] == '.') {
                        return false;
                    }
                }
            }
            return true;
        }

        /**
         * Checks if the set of valid shifts covers all 'x' target positions.
         */
        private boolean checkCoverage(List<Position> validShifts) {
            boolean[][] covered = new boolean[n][n];

            for (Position shift : validShifts) {
                for (Position p : patternPoints) {
                    int nr = p.row + shift.row;
                    int nc = p.col + shift.col;
                    if (isWithinBounds(nr, nc)) {
                        covered[nr][nc] = true;
                    }
                }
            }

            for (Position target : targetPoints) {
                if (!covered[target.row][target.col]) {
                    return false;
                }
            }
            return true;
        }

        private boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < n && c >= 0 && c < n;
        }

        /**
         * Prints the grid of valid shifts.
         * The origin (0,0) is centered at (n-1, n-1).
         */
        private void printShiftMap(List<Position> validShifts) {
            int mapSize = 2 * n - 1;
            char[][] shiftMap = new char[mapSize][mapSize];

            // Initialize with '.'
            for (int i = 0; i < mapSize; i++) {
                Arrays.fill(shiftMap[i], '.');
            }

            // Mark valid shifts
            for (Position s : validShifts) {
                int mapIdxR = s.row + (n - 1);
                int mapIdxC = s.col + (n - 1);
                shiftMap[mapIdxR][mapIdxC] = 'x';
            }

            // The (0,0) shift is always marked as 'o'
            shiftMap[n - 1][n - 1] = 'o';

            for (char[] row : shiftMap) {
                System.out.println(new String(row));
            }
        }
    }
}

