/**
 * Contains the core logic for calculating the grid pattern and validating it.
 */
class GridPatternSolver {
    private static final char CELL_EMPTY = '.';
    private static final char CELL_FILLED = 'o';
    private static final char CELL_UNKNOWN = 'x';

    /**
     * Solves the grid pattern problem.
     * 
     * @param gridSize The size of the input N x N grid.
     * @param in       The input reader.
     * @return A Solution object containing the result and the generated pattern.
     */
    public Solution solve(int gridSize, FastReader in) {
        char[][] inputGrid = in.nextTable(gridSize, gridSize);
        if (inputGrid == null) {
            return null;
        }

        char[][] patternGrid = computePatternGrid(gridSize, inputGrid);
        char[][] reconstructedGrid = reconstructGrid(gridSize, inputGrid, patternGrid);

        boolean isMatch = validateReconstruction(gridSize, inputGrid, reconstructedGrid);

        return new Solution(isMatch, patternGrid);
    }

    /**
     * Computes the relative pattern grid based on the positions of filled and empty cells.
     */
    private char[][] computePatternGrid(int n, char[][] inputGrid) {
        int patternSize = 2 * n - 1;
        char[][] pattern = new char[patternSize][patternSize];

        for (int i = 0; i < patternSize; i++) {
            Arrays.fill(pattern[i], CELL_UNKNOWN);
        }

        // The center of the pattern is the reference point.
        pattern[n - 1][n - 1] = CELL_FILLED;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (inputGrid[i][j] == CELL_FILLED) {
                    // For every filled cell, map the relative positions of all empty cells into the pattern.
                    for (int x = 0; x < n; x++) {
                        for (int y = 0; y < n; y++) {
                            if (inputGrid[x][y] == CELL_EMPTY) {
                                int patternRow = n - 1 + x - i;
                                int patternCol = n - 1 + y - j;
                                pattern[patternRow][patternCol] = CELL_EMPTY;
                            }
                        }
                    }
                }
            }
        }
        return pattern;
    }

    /**
     * Attempts to reconstruct the original grid using the computed pattern.
     */
    private char[][] reconstructGrid(int n, char[][] inputGrid, char[][] patternGrid) {
        char[][] reconstruction = new char[n][n];
        for (int i = 0; i < n; i++) {
            Arrays.fill(reconstruction[i], CELL_EMPTY);
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (inputGrid[i][j] == CELL_FILLED) {
                    reconstruction[i][j] = CELL_FILLED;
                    // Apply pattern offsets to mark unknown (x) cells in the reconstruction.
                    for (int dx = -n + 1; dx < n; dx++) {
                        for (int dy = -n + 1; dy < n; dy++) {
                            int targetRow = i + dx;
                            int targetCol = j + dy;

                            if (isInBounds(n, targetRow, targetCol)) {
                                if (reconstruction[targetRow][targetCol] == CELL_EMPTY 
                                    && patternGrid[n - 1 + dx][n - 1 + dy] == CELL_UNKNOWN) {
                                    reconstruction[targetRow][targetCol] = CELL_UNKNOWN;
                                }
                            }
                        }
                    }
                }
            }
        }
        return reconstruction;
    }

    private boolean validateReconstruction(int n, char[][] original, char[][] reconstructed) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (reconstructed[i][j] != original[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    private boolean isInBounds(int n, int r, int c) {
        return r >= 0 && r < n && c >= 0 && c < n;
    }
}

/**
 * Fast I/O utility for reading input efficiently.
 */
class FastReader {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    public FastReader(InputStream inputStream) {
        this.reader = new BufferedReader(new InputStreamReader(inputStream));
    }

    public String nextToken() {
        try {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        } catch (IOException e) {
            return null;
        }
    }

    public int nextInt() {
        String token = nextToken();
        return token != null ? Integer.parseInt(token) : 0;
    }

    public char[][] nextTable(int rows, int cols) {
        char[][] table = new char[rows][];
        for (int i = 0; i < rows; i++) {
            String line = nextToken();
            if (line == null || line.length() != cols) {
                return null;
            }
            table[i] = line.toCharArray();
        }
        return table;
    }
}

/**
 * Fast I/O utility for writing output efficiently.
 */
class FastWriter extends PrintWriter {
    public FastWriter(OutputStream out) {
        super(out);
    }

    public void printSolution(Solution solution) {
        if (solution.isSuccess()) {
            println("YES");
            for (char[] row : solution.getPatternGrid()) {
                println(row);
            }
        } else {
            println("NO");
        }
    }
}

import java.io.BufferedInputStream;
import java.io.PrintStream;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Scanner;

/**
 * A refactored solution for solving grid-based pattern shifts.
 * This program finds valid relative offsets that can be applied to a set of target 
 * points without landing on empty cells in a provided grid.
 */
public class GridPatternSolver {

    // Constants for grid characters to avoid magic characters throughout the code
    private static final char EMPTY = '.';
    private static final char TARGET = 'o';
    private static final char SHIFT_MARKER = 'x';

    private static final PrintStream out = System.out;

    /**
     * Represents a point in a 2D coordinate system.
     */
    private static class Coordinate {
        final int row;
        final int col;

        Coordinate(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(new BufferedInputStream(System.in));

        if (!scanner.hasNextInt()) {
            return;
        }

        int gridSize = scanner.nextInt();
        char[][] inputGrid = new char[gridSize][gridSize];
        List<Coordinate> targetPoints = new ArrayList<>();

        // Parse input grid and identify target points ('o')
        for (int i = 0; i < gridSize; i++) {
            String line = scanner.next();
            inputGrid[i] = line.toCharArray();
            for (int j = 0; j < gridSize; j++) {
                if (inputGrid[i][j] == TARGET) {
                    targetPoints.add(new Coordinate(i, j));
                }
            }
        }

        processGrid(gridSize, inputGrid, targetPoints);
    }

    /**
     * Orchestrates the shift calculation, cleaning, and verification process.
     */
    private static void processGrid(int gridSize, char[][] board, List<Coordinate> targetPoints) {
        int expandedSize = 2 * gridSize - 1;
        char[][] expandedGrid = createEmptyGrid(expandedSize);

        // 1. Calculate all valid shifts
        calculateValidShifts(gridSize, expandedSize, board, targetPoints, expandedGrid);

        // 2. The center of the expanded grid represents the origin/base target
        expandedGrid[gridSize - 1][gridSize - 1] = TARGET;

        // 3. Apply the specific cleaning logic from the original implementation
        applyCleaningLogic(gridSize, board, expandedGrid, targetPoints);

        // 4. Verify if the pattern is valid and print results
        if (containsRemainingMarkers(gridSize, board)) {
            out.println("NO");
        } else {
            out.println("YES");
            for (int i = 0; i < expandedSize; i++) {
                out.println(expandedGrid[i]);
            }
        }
    }

    private static char[][] createEmptyGrid(int size) {
        char[][] grid = new char[size][size];
        for (int i = 0; i < size; i++) {
            Arrays.fill(grid[i], EMPTY);
        }
        return grid;
    }

    /**
     * Determines which shifts (dr, dc) are valid.
     * A shift is valid if no 'o' point lands on a '.' cell in the original grid.
     */
    private static void calculateValidShifts(int gridSize, int expandedSize, char[][] board, 
                                             List<Coordinate> targetPoints, char[][] expandedGrid) {
        for (int dr = -(gridSize - 1); dr < gridSize; dr++) {
            for (int dc = -(gridSize - 1); dc < gridSize; dc++) {
                // Skip the origin shift as it is handled explicitly later
                if (dr == 0 && dc == 0) {
                    continue;
                }

                if (isShiftPossible(gridSize, board, targetPoints, dr, dc)) {
                    expandedGrid[gridSize - 1 + dr][gridSize - 1 + dc] = SHIFT_MARKER;
                }
            }
        }
    }

    private static boolean isShiftPossible(int gridSize, char[][] board, List<Coordinate> targetPoints, 
                                           int dr, int dc) {
        for (Coordinate p : targetPoints) {
            int nextR = p.row + dr;
            int nextC = p.col + dc;

            if (isWithinBounds(nextR, nextC, gridSize) && board[nextR][nextC] == EMPTY) {
                return false;
            }
        }
        return true;
    }

    /**
     * Implements the transformation logic where certain characters in the original board 
     * are cleared based on the valid shifts found.
     */
    private static void applyCleaningLogic(int gridSize, char[][] board, char[][] expandedGrid, 
                                           List<Coordinate> targetPoints) {
        for (Coordinate p : targetPoints) {
            for (int dr = -(gridSize - 1); dr < gridSize; dr++) {
                for (int dc = -(gridSize - 1); dc < gridSize; dc++) {
                    if (dr == 0 && dc == 0) continue;

                    int nextR = p.row + dr;
                    int nextC = p.col + dc;
                    int shiftR = gridSize - 1 + dr;
                    int shiftC = gridSize - 1 + dc;

                    if (expandedGrid[shiftR][shiftC] == SHIFT_MARKER &&
                        isWithinBounds(nextR, nextC, gridSize) &&
                        board[nextR][nextC] == SHIFT_MARKER) {
                        board[nextR][nextC] = EMPTY;
                    }
                }
            }
        }
    }

    private static boolean containsRemainingMarkers(int gridSize, char[][] board) {
        for (int i = 0; i < gridSize; i++) {
            for (int j = 0; j < gridSize; j++) {
                if (board[i][j] == SHIFT_MARKER) {
                    return true;
                }
            }
        }
        return false;
    }

    private static boolean isWithinBounds(int r, int c, int size) {
        return r >= 0 && r < size && c >= 0 && c < size;
    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Scanner;

/**
 * A solver for the Grid Displacement problem.
 * The goal is to find all valid displacements (dx, dy) such that applying the displacement 
 * to all 'o' cells does not land on a '.' cell, and every 'x' cell is covered by 
 * at least one such valid displacement.
 */
public class GridSolver {

    /**
     * Represents a coordinate on the 2D grid.
     */
    private static class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    private final int gridSize;
    private final char[][] grid;
    private final List<Position> oPositions = new ArrayList<>();
    private final List<Position> xPositions = new ArrayList<>();

    public GridSolver(int gridSize, char[][] grid) {
        this.gridSize = gridSize;
        this.grid = grid;
        initializePositionLists();
    }

    /**
     * Scans the grid once to store the locations of 'o' and 'x' for faster access.
     */
    private void initializePositionLists() {
        for (int r = 0; r < gridSize; r++) {
            for (int c = 0; c < gridSize; c++) {
                if (grid[r][c] == 'o') {
                    oPositions.add(new Position(r, c));
                } else if (grid[r][c] == 'x') {
                    xPositions.add(new Position(r, c));
                }
            }
        }
    }

    /**
     * Executes the core logic: finds valid displacements and determines if all 'x' are covered.
     */
    public void solve() {
        char[][] displacementMap = createEmptyDisplacementMap();

        // Iterate through all possible displacements in the range [-(n-1), n-1]
        for (int dx = -gridSize + 1; dx <= gridSize - 1; dx++) {
            for (int dy = -gridSize + 1; dy <= gridSize - 1; dy++) {
                // Skip the origin (0,0) as it is reserved for 'o'
                if (dx == 0 && dy == 0) {
                    continue;
                }

                if (isValidDisplacement(dx, dy)) {
                    // Mark this displacement as valid in the output map
                    displacementMap[gridSize - 1 + dx][gridSize - 1 + dy] = 'x';
                    // Mark the 'x' cells on the board that this displacement covers
                    markTargetCells(dx, dy);
                } else {
                    displacementMap[gridSize - 1 + dx][gridSize - 1 + dy] = '.';
                }
            }
        }

        if (hasUnmarkedX()) {
            System.out.println("NO");
        } else {
            System.out.println("YES");
            printMap(displacementMap);
        }
    }

    private char[][] createEmptyDisplacementMap() {
        int size = 2 * gridSize - 1;
        char[][] map = new char[size][size];
        for (char[] row : map) {
            Arrays.fill(row, '.');
        }
        map[gridSize - 1][gridSize - 1] = 'o';
        return map;
    }

    /**
     * A displacement is valid if no 'o' cell, when shifted, lands on a '.' cell.
     */
    private boolean isValidDisplacement(int dx, int dy) {
        for (Position o : oPositions) {
            int targetRow = o.row + dx;
            int targetCol = o.col + dy;

            if (isWithinBounds(targetRow, targetCol) && grid[targetRow][targetCol] == '.') {
                return false;
            }
        }
        return true;
    }

    /**
     * Changes 'x' to 'X' if it is hit by a valid displacement.
     */
    private void markTargetCells(int dx, int dy) {
        for (Position o : oPositions) {
            int targetRow = o.row + dx;
            int targetCol = o.col + dy;

            if (isWithinBounds(targetRow, targetCol) && grid[targetRow][targetCol] == 'x') {
                grid[targetRow][targetCol] = 'X';
            }
        }
    }

    /**
     * Checks if any 'x' cells remain in their original state.
     */
    private boolean hasUnmarkedX() {
        for (Position x : xPositions) {
            if (grid[x.row][x.col] == 'x') {
                return true;
            }
        }
        return false;
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < gridSize && c >= 0 && c < gridSize;
    }

    private void printMap(char[][] map) {
        StringBuilder sb = new StringBuilder();
        for (char[] row : map) {
            sb.append(new String(row)).append('\n');
        }
        System.out.print(sb.toString());
    }

    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            if (!sc.hasNextInt()) {
                return;
            }

            int n = sc.nextInt();
            sc.nextLine(); // Consume trailing newline

            char[][] board = new char[n][n];
            for (int i = 0; i < n; i++) {
                String line = sc.nextLine();
                board[i] = line.toCharArray();
            }

            GridSolver solver = new GridSolver(n, board);
            solver.solve();
        }
    }
}

