/**
 * Represents a coordinate in a 2D grid.
 */
record Point(int row, int col) {}

/**
 * Contains the core logic for solving the grid expansion problem.
 */
class GridProblemSolver {

    private static final char EMPTY = '.';
    private static final char PIECE = 'o';
    private static final char MARK = 'x';

    public void solve(FastReader in, FastWriter out) throws IOException {
        int n = in.readInt();
        char[][] originalGrid = in.readGrid(n, n);

        List<Point> piecePositions = findPiecePositions(originalGrid, n);
        char[][] expandedGrid = buildExpandedGrid(originalGrid, piecePositions, n);

        if (verifyCoverage(originalGrid, expandedGrid, piecePositions, n)) {
            out.printLine("YES");
            out.printGrid(expandedGrid);
        } else {
            out.printLine("NO");
        }
    }

    /**
     * Locates all 'o' characters in the original grid.
     */
    private List<Point> findPiecePositions(char[][] grid, int n) {
        List<Point> positions = new ArrayList<>();
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == PIECE) {
                    positions.add(new Point(r, c));
                }
            }
        }
        return positions;
    }

    /**
     * Constructs the (2n-1)x(2n-1) expanded grid based on valid offsets.
     */
    private char[][] buildExpandedGrid(char[][] originalGrid, List<Point> pieces, int n) {
        int expandedSize = 2 * n - 1;
        char[][] expandedGrid = new char[expandedSize][expandedSize];

        for (int r = 0; r < expandedSize; r++) {
            for (int c = 0; c < expandedSize; c++) {
                // The center of the expanded grid is special
                if (r == n - 1 && c == n - 1) {
                    expandedGrid[r][c] = PIECE;
                    continue;
                }

                int rowOffset = r - (n - 1);
                int colOffset = c - (n - 1);

                if (isValidOffset(originalGrid, pieces, rowOffset, colOffset, n)) {
                    expandedGrid[r][c] = MARK;
                } else {
                    expandedGrid[r][c] = EMPTY;
                }
            }
        }
        return expandedGrid;
    }

    /**
     * Checks if a specific offset is valid (i.e., no piece lands on a '.' in the original grid).
     */
    private boolean isValidOffset(char[][] grid, List<Point> pieces, int dr, int dc, int n) {
        for (Point piece : pieces) {
            int targetRow = piece.row() + dr;
            int targetCol = piece.col() + dc;

            if (isWithinBounds(targetRow, targetCol, n)) {
                if (grid[targetRow][targetCol] == EMPTY) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Verifies if the generated expanded grid covers all 'x' marks in the original grid.
     */
    private boolean verifyCoverage(char[][] originalGrid, char[][] expandedGrid, List<Point> pieces, int n) {
        char[][] coverageGrid = new char[n][n];
        for (char[] row : coverageGrid) {
            Arrays.fill(row, EMPTY);
        }

        int expandedSize = expandedGrid.length;
        for (int r = 0; r < expandedSize; r++) {
            for (int c = 0; c < expandedSize; c++) {
                if (expandedGrid[r][c] == MARK) {
                    // Apply this valid offset to all pieces to see what it covers
                    int rowOffset = r - (n - 1);
                    int colOffset = c - (n - 1);
                    for (Point piece : pieces) {
                        int nr = piece.row() + rowOffset;
                        int nc = piece.col() + colOffset;
                        if (isWithinBounds(nr, nc, n)) {
                            coverageGrid[nr][nc] = MARK;
                        }
                    }
                }
            }
        }

        // Check if every 'x' in the original grid is covered
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (originalGrid[r][c] == MARK && coverageGrid[r][c] == EMPTY) {
                    return false;
                }
            }
        }
        return true;
    }

    private boolean isWithinBounds(int r, int c, int n) {
        return r >= 0 && r < n && c >= 0 && c < n;
    }
}

/**
 * High-performance reader for large input datasets.
 */
class FastReader implements AutoCloseable {
    private final InputStream inputStream;
    private final byte[] buffer = new byte[1024];
    private int pointer = 0;
    private int bytesRead = 0;

    public FastReader(InputStream inputStream) {
        this.inputStream = inputStream;
    }

    private int readByte() throws IOException {
        if (pointer >= bytesRead) {
            pointer = 0;
            bytesRead = inputStream.read(buffer);
            if (bytesRead <= 0) return -1;
        }
        return buffer[pointer++] & 0xFF;
    }

    public int readInt() throws IOException {
        int c = readByte();
        while (c != -1 && c <= 32) c = readByte();
        if (c == -1) return 0;
        int sign = 1;
        if (c == '-') {
            sign = -1;
            c = readByte();
        }
        int res = 0;
        while (c >= '0' && c <= '9') {
            res = res * 10 + (c - '0');
            c = readByte();
        }
        return res * sign;
    }

    public char readChar() throws IOException {
        int c = readByte();
        while (c != -1 && c <= 32) c = readByte();
        return (char) c;
    }

    public char[][] readGrid(int rows, int cols) throws IOException {
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                grid[i][j] = readChar();
            }
        }
        return grid;
    }

    @Override
    public void close() throws IOException {
        inputStream.close();
    }
}

/**
 * High-performance writer for efficient output.
 */
class FastWriter implements AutoCloseable {
    private final PrintWriter writer;

    public FastWriter(OutputStream outputStream) {
        this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
    }

    public void printLine(String s) {
        writer.println(s);
    }

    public void printGrid(char[][] grid) {
        for (char[] row : grid) {
            writer.println(new String(row));
        }
    }

    @Override
    public void close() {
        writer.close();
    }
}

import java.io.*;
import java.util.*;

/**
 * PatternMatcher solves the problem of determining if a pattern of target cells ('o')
 * can be shifted across a grid such that all obstacle cells ('x') are covered,
 * without any target cell landing on an empty cell ('.').
 */
public class PatternMatcher {

    private static final char EMPTY_CHAR = '.';
    private static final char OBSTACLE_CHAR = 'x';
    private static final char TARGET_CHAR = 'o';

    /**
     * Represents the different types of cells within the input grid.
     */
    enum CellType {
        EMPTY, OBSTACLE, TARGET
    }

    /**
     * A simple coordinate representation.
     */
    static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            String nInput = reader.next();
            if (nInput == null) return;
            int n = Integer.parseInt(nInput);

            Grid grid = new Grid(n);
            for (int i = 0; i < n; i++) {
                String line = reader.next();
                for (int j = 0; j < n; j++) {
                    grid.setCell(i, j, line.charAt(j));
                }
            }

            PatternSolver solver = new PatternSolver(grid);
            solver.solve(writer);

        } catch (Exception e) {
            // In a production environment, use a proper logging framework
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Holds the grid data and pre-calculated positions of targets and obstacles.
     */
    static class Grid {
        private final int size;
        private final CellType[][] cells;
        private final List<Point> targets = new ArrayList<>();
        private final List<Point> obstacles = new ArrayList<>();

        public Grid(int size) {
            this.size = size;
            this.cells = new CellType[size][size];
        }

        public void setCell(int r, int c, char ch) {
            if (ch == '.') {
                cells[r][c] = CellType.EMPTY;
            } else if (ch == 'x') {
                cells[r][c] = CellType.OBSTACLE;
                obstacles.add(new Point(r, c));
            } else if (ch == 'o') {
                cells[r][c] = CellType.TARGET;
                targets.add(new Point(r, c));
            }
        }

        public int getSize() { return size; }
        public CellType getCell(int r, int c) { return cells[r][c]; }
        public List<Point> getTargets() { return targets; }
        public List<Point> getObstacles() { return obstacles; }
    }

    /**
     * Contains the core logic for calculating valid shifts and verifying obstacle coverage.
     */
    static class PatternSolver {
        private final Grid grid;
        private final int n;

        public PatternSolver(Grid grid) {
            this.grid = grid;
            this.n = grid.getSize();
        }

        public void solve(PrintWriter out) {
            int shiftGridSize = 2 * n - 1;
            char[][] shiftGrid = new char[shiftGridSize][shiftGridSize];

            for (int i = 0; i < shiftGridSize; i++) {
                Arrays.fill(shiftGrid[i], EMPTY_CHAR);
            }

            // 1. Identify all valid relative shifts (dr, dc)
            // A shift is valid if no 'o' lands on an EMPTY ('.') cell.
            for (int dr = -n + 1; dr < n; dr++) {
                for (int dc = -n + 1; dc < n; dc++) {
                    if (isShiftValid(dr, dc)) {
                        shiftGrid[dr + n - 1][dc + n - 1] = OBSTACLE_CHAR;
                    }
                }
            }

            // Mark the (0,0) shift as the target marker (original position)
            shiftGrid[n - 1][n - 1] = TARGET_CHAR;

            // 2. Verify if every obstacle is covered by at least one valid shift
            if (areAllObstaclesCovered(shiftGrid)) {
                out.println("YES");
                printGrid(shiftGrid, out);
            } else {
                out.println("NO");
            }
        }

        private boolean isShiftValid(int dr, int dc) {
            for (Point target : grid.getTargets()) {
                int nr = target.row + dr;
                int nc = target.col + dc;

                // If the shifted target is within grid bounds, it must not be an empty cell
                if (nr >= 0 && nr < n && nc >= 0 && nc < n) {
                    if (grid.getCell(nr, nc) == CellType.EMPTY) {
                        return false;
                    }
                }
            }
            return true;
        }

        private boolean areAllObstaclesCovered(char[][] shiftGrid) {
            for (Point obs : grid.getObstacles()) {
                boolean covered = false;
                for (Point target : grid.getTargets()) {
                    // Calculate the shift required to move this target to the obstacle position
                    int dr = obs.row - target.row;
                    int dc = obs.col - target.col;

                    // Verify if this shift is within the valid bounds of our shiftGrid
                    if (dr >= -n + 1 && dr < n && dc >= -n + 1 && dc < n) {
                        char status = shiftGrid[dr + n - 1][dc + n - 1];
                        // An obstacle is covered if the shift is valid (either 'x' or the original 'o')
                        if (status == OBSTACLE_CHAR || status == TARGET_CHAR) {
                            covered = true;
                            break;
                        }
                    }
                }
                if (!covered) return false;
            }
            return true;
        }

        private void printGrid(char[][] grid, PrintWriter out) {
            for (char[] row : grid) {
                out.println(new String(row));
            }
        }
    }

    /**
     * Utility class for efficient input reading.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }
    }
}

import java.io.InputStream;
import java.util.HashSet;
import java.util.Scanner;
import java.util.Set;

/**
 * A solver for the grid-based chess configuration problem.
 * The goal is to validate if a given board configuration is valid 
 * and, if so, generate a larger expanded board.
 */
public class Main {

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            BoardSolver solver = new BoardSolver();
            if (scanner.hasNextInt()) {
                solver.readInput(scanner);
                solver.solve();
            }
        }
    }

    /**
     * Represents a 2D coordinate on the grid.
     */
    private record Point(int row, int col) {
        public Point add(Point other) {
            return new Point(this.row + other.row, this.col + other.col);
        }

        public Point subtract(Point other) {
            return new Point(this.row - other.row, this.col - other.col);
        }

        public boolean isWithinBounds(int n) {
            return row >= 0 && row < n && col >= 0 && col < n;
        }
    }

    private static class BoardSolver {
        private int size = 0;
        private char[][] grid = null;

        public void readInput(Scanner scanner) {
            this.size = scanner.nextInt();
            scanner.nextLine(); // Consume newline
            this.grid = new char[size][size];
            for (int i = 0; i < size; i++) {
                String line = scanner.nextLine();
                for (int j = 0; j < size; j++) {
                    this.grid[i][j] = line.charAt(j);
                }
            }
        }

        public void solve() {
            Set<Point> chessPositions = new HashSet<>();
            Set<Point> emptyPositions = new HashSet<>();

            // Identify initial positions of pieces and empty spaces
            for (int r = 0; r < size; r++) {
                for (int c = 0; c < size; c++) {
                    if (grid[r][c] == 'o') {
                        chessPositions.add(new Point(r, c));
                    } else if (grid[r][c] == '.') {
                        emptyPositions.add(new Point(r, c));
                    }
                }
            }

            Set<Point> impossibleOffsets = calculateImpossibleOffsets(chessPositions, emptyPositions);

            if (!verifyValidConfiguration(chessPositions, impossibleOffsets)) {
                System.out.println("NO");
                return;
            }

            if (containsInvalidCharacters()) {
                System.out.println("NO");
                return;
            }

            printSuccessResult(impossibleOffsets);
        }

        /**
         * Calculates offsets that are considered "impossible" based on the distance
         * between chess pieces and empty spaces.
         */
        private Set<Point> calculateImpossibleOffsets(Set<Point> chessPositions, Set<Point> emptyPositions) {
            Set<Point> impossibleOffsets = new HashSet<>();
            for (Point chess : chessPositions) {
                for (Point empty : emptyPositions) {
                    impossibleOffsets.add(empty.subtract(chess));
                }
            }
            return impossibleOffsets;
        }

        /**
         * Validates if the current board layout violates the movement rules.
         */
        private boolean verifyValidConfiguration(Set<Point> chessPositions, Set<Point> impossibleOffsets) {
            for (Point chess : chessPositions) {
                // Check all possible relative offsets within the grid boundaries
                for (int i = -size + 1; i < size; i++) {
                    for (int j = -size + 1; j < size; j++) {
                        Point offset = new Point(i, j);

                        if (!impossibleOffsets.contains(offset)) {
                            Point target = chess.add(offset);
                            if (target.isWithinBounds(size)) {
                                if (grid[target.row()][target.col()] == '.') {
                                    return false;
                                }
                                // Mark as visited to avoid redundant checks
                                grid[target.row()][target.col()] = 'v';
                            }
                        }
                    }
                }
            }
            return true;
        }

        private boolean containsInvalidCharacters() {
            for (int i = 0; i < size; i++) {
                for (int j = 0; j < size; j++) {
                    if (grid[i][j] == 'x') {
                        return true;
                    }
                }
            }
            return false;
        }

        /**
         * Generates and prints the expanded (2N-1) x (2N-1) board.
         */
        private void printSuccessResult(Set<Point> impossibleOffsets) {
            int resultSize = size * 2 - 1;
            char[][] resultGrid = new char[resultSize][resultSize];

            // Initialize result grid with empty space
            for (int i = 0; i < resultSize; i++) {
                for (int j = 0; j < resultSize; j++) {
                    resultGrid[i][j] = '.';
                }
            }

            // Place the central piece
            resultGrid[size - 1][size - 1] = 'o';

            // Place 'x' markers for all valid offsets
            for (int i = -size + 1; i < size; i++) {
                for (int j = -size + 1; j < size; j++) {
                    if (i == 0 && j == 0) continue;

                    if (!impossibleOffsets.contains(new Point(i, j))) {
                        resultGrid[i + size - 1][j + size - 1] = 'x';
                    }
                }
            }

            System.out.println("YES");
            printGrid(resultGrid);
        }

        private void printGrid(char[][] gridToPrint) {
            StringBuilder output = new StringBuilder();
            for (char[] row : gridToPrint) {
                output.append(new String(row)).append("\n");
            }
            System.out.print(output.toString());
        }
    }
}

import java.util.*;

/**
 * PatternSolver analyzes a grid to determine if specific relative patterns 
 * can be applied to clear 'x' markers based on 'o' and '.' constraints.
 */
public class PatternSolver {

    private static final char CELL_OCCUPIED = 'o';
    private static final char CELL_EMPTY = '.';
    private static final char CELL_MARKER = 'x';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int size = scanner.nextInt();
        char[][] grid = new char[size][size];

        for (int i = 0; i < size; i++) {
            String rowString = scanner.next();
            for (int j = 0; j < size; j++) {
                grid[i][j] = rowString.charAt(j);
            }
        }

        PatternSolver solver = new PatternSolver();
        solver.execute(size, grid);

        scanner.close();
    }

    /**
     * Orchestrates the execution logic of the solver.
     */
    public void execute(int size, char[][] grid) {
        boolean[][] allowedOffsets = computeAllowedOffsets(size, grid);
        applyAllowedPatterns(size, grid, allowedOffsets);

        if (isGridValid(size, grid)) {
            System.out.println("YES");
            printResultGrid(size, allowedOffsets);
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Determines which relative displacements (offsets) are valid.
     * An offset is invalid if applying it to an 'o' cell lands on a '.' cell.
     */
    private boolean[][] computeAllowedOffsets(int size, char[][] grid) {
        int offsetDim = 2 * size - 1;
        boolean[][] allowedOffsets = new boolean[offsetDim][offsetDim];

        // Initialize all offsets as true
        for (int i = 0; i < offsetDim; i++) {
            Arrays.fill(allowedOffsets[i], true);
        }

        List<int[]> occupiedPositions = new ArrayList<>();
        List<int[]> emptyPositions = new ArrayList<>();

        // Collect positions to optimize the O(N^4) search
        for (int r = 0; r < size; r++) {
            for (int c = 0; c < size; c++) {
                if (grid[r][c] == CELL_OCCUPIED) {
                    occupiedPositions.add(new int[]{r, c});
                } else if (grid[r][c] == CELL_EMPTY) {
                    emptyPositions.add(new int[]{r, c});
                }
            }
        }

        // Mark forbidden offsets
        for (int[] occ : occupiedPositions) {
            for (int[] emp : emptyPositions) {
                int deltaRow = emp[0] - occ[0] + size - 1;
                int deltaCol = emp[1] - occ[1] + size - 1;
                allowedOffsets[deltaRow][deltaCol] = false;
            }
        }

        return allowedOffsets;
    }

    /**
     * Uses the valid offsets to transform 'x' markers into '.' in the grid.
     */
    private void applyAllowedPatterns(int size, char[][] grid, boolean[][] allowedOffsets) {
        for (int dr = 1 - size; dr < size; dr++) {
            for (int dc = 1 - size; dc < size; dc++) {
                // Check if this relative displacement is allowed
                if (!allowedOffsets[dr + size - 1][dc + size - 1]) {
                    continue;
                }

                for (int r = 0; r < size; r++) {
                    for (int c = 0; c < size; c++) {
                        int targetRow = r + dr;
                        int targetCol = c + dc;

                        // Check bounds and pattern condition
                        if (isWithinBounds(targetRow, targetCol, size)) {
                            if (grid[r][c] == CELL_OCCUPIED && grid[targetRow][targetCol] == CELL_MARKER) {
                                grid[targetRow][targetCol] = CELL_EMPTY;
                            }
                        }
                    }
                }
            }
        }
    }

    /**
     * Checks if any 'x' markers remain in the grid.
     */
    private boolean isGridValid(int size, char[][] grid) {
        for (int r = 0; r < size; r++) {
            for (int c = 0; c < size; c++) {
                if (grid[r][c] == CELL_MARKER) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Prints the resulting pattern grid based on the allowed offsets.
     */
    private void printResultGrid(int size, boolean[][] allowedOffsets) {
        int offsetDim = 2 * size - 1;
        StringBuilder output = new StringBuilder();

        for (int i = 0; i < offsetDim; i++) {
            for (int j = 0; j < offsetDim; j++) {
                // The center of the offset grid is always the origin 'o'
                if (i == size - 1 && j == size - 1) {
                    output.append(CELL_OCCUPIED);
                } else {
                    output.append(allowedOffsets[i][j] ? CELL_MARKER : CELL_EMPTY);
                }
            }
            output.append("\n");
        }
        System.out.print(output.toString());
    }

    private boolean isWithinBounds(int r, int c, int size) {
        return r >= 0 && r < size && c >= 0 && c < size;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

/**
 * A solver for grid transformation logic that determines valid cell offsets.
 */
public class GridTransformer {

    private static final char CELL_O = 'o';
    private static final char CELL_X = 'x';
    private static final char CELL_DOT = '.';

    /**
     * Represents a 2D coordinate offset.
     */
    private record Offset(int dx, int dy) {}

    public static void main(String[] args) {
        try (BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(System.out)) {
            new GridTransformer().solve(in, out);
        } catch (IOException e) {
            System.err.println("An error occurred during execution: " + e.getMessage());
        }
    }

    /**
     * Orchestrates the grid transformation logic.
     */
    public void solve(BufferedReader in, PrintWriter out) throws IOException {
        String firstLine = in.readLine();
        if (firstLine == null) return;

        int gridSize = Integer.parseInt(firstLine.trim());
        char[][] originalGrid = readGrid(in, gridSize);

        // 1. Find all offsets that preserve the 'o' character pattern or move them out of bounds
        List<Offset> validOffsets = findValidOffsets(originalGrid, gridSize);

        // 2. Create the result grid (the 2N-1 grid)
        char[][] offsetGrid = constructOffsetGrid(gridSize, validOffsets);

        // 3. Simulate the transformation to see if the original pattern is preserved
        char[][] modifiedGrid = applyValidOffsets(originalGrid, gridSize, validOffsets);

        // 4. Verify and output results
        if (isOriginalMatchModified(originalGrid, modifiedGrid, gridSize)) {
            out.println("YES");
            printGrid(offsetGrid, out);
        } else {
            out.println("NO");
        }
    }

    private char[][] readGrid(BufferedReader in, int size) throws IOException {
        char[][] grid = new char[size][size];
        for (int i = 0; i < size; i++) {
            grid[i] = in.readLine().toCharArray();
        }
        return grid;
    }

    private List<Offset> findValidOffsets(char[][] grid, int size) {
        List<Offset> validOffsets = new ArrayList<>();
        for (int dy = -size + 1; dy <= size - 1; dy++) {
            for (int dx = -size + 1; dx <= size - 1; dx++) {
                // Skip the zero offset as per original logic
                if (dx == 0 && dy == 0) {
                    continue;
                }

                if (isOffsetValid(grid, size, dx, dy)) {
                    validOffsets.add(new Offset(dx, dy));
                }
            }
        }
        return validOffsets;
    }

    private boolean isOffsetValid(char[][] grid, int size, int dx, int dy) {
        for (int row = 0; row < size; row++) {
            for (int col = 0; col < size; col++) {
                if (grid[row][col] != CELL_O) {
                    continue;
                }

                int targetRow = row + dy;
                int targetCol = col + dx;

                if (isOutOfBounds(targetRow, targetCol, size)) {
                    continue;
                }

                char targetCell = grid[targetRow][targetCol];
                // Valid if the 'o' lands on another 'o' or an 'x'
                if (targetCell != CELL_O && targetCell != CELL_X) {
                    return false;
                }
            }
        }
        return true;
    }

    private boolean isOutOfBounds(int row, int col, int size) {
        return row < 0 || row >= size || col < 0 || col >= size;
    }

    private char[][] constructOffsetGrid(int size, List<Offset> validOffsets) {
        int dimension = 2 * size - 1;
        char[][] offsetGrid = new char[dimension][dimension];
        for (char[] row : offsetGrid) {
            Arrays.fill(row, CELL_DOT);
        }

        // The center of the offset grid is always 'o'
        offsetGrid[size - 1][size - 1] = CELL_O;

        for (Offset offset : validOffsets) {
            offsetGrid[size - 1 + offset.dy][size - 1 + offset.dx] = CELL_X;
        }
        return offsetGrid;
    }

    private char[][] applyValidOffsets(char[][] originalGrid, int size, List<Offset> validOffsets) {
        char[][] modifiedGrid = new char[size][size];

        // Initialize modifiedGrid: 'o' where original has 'o', otherwise '.'
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                modifiedGrid[i][j] = (originalGrid[i][j] == CELL_O) ? CELL_O : CELL_DOT;
            }
        }

        // For every valid offset, if an 'o' lands on a non-'o' cell, mark that cell as 'x'
        for (Offset offset : validOffsets) {
            for (int row = 0; row < size; row++) {
                for (int col = 0; col < size; col++) {
                    if (originalGrid[row][col] != CELL_O) {
                        continue;
                    }

                    int targetRow = row + offset.dy;
                    int targetCol = col + offset.dx;

                    if (!isOutOfBounds(targetRow, targetCol, size)) {
                        if (originalGrid[targetRow][targetCol] != CELL_O) {
                            modifiedGrid[targetRow][targetCol] = CELL_X;
                        }
                    }
                }
            }
        }
        return modifiedGrid;
    }

    private boolean isOriginalMatchModified(char[][] original, char[][] modified, int size) {
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                if (original[i][j] != modified[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    private void printGrid(char[][] grid, PrintWriter out) {
        for (char[] row : grid) {
            out.println(new String(row));
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * PatternMatcher finds a set of translation offsets that cover all 'wall' cells 
 * without landing on any 'empty' cells, based on the positions of 'target' pieces.
 */
public class PatternMatcher {

    private static final char TARGET_PIECE = 'o';
    private static final char WALL = 'x';
    private static final char EMPTY = '.';

    /**
     * Represents a coordinate on a 2D grid.
     */
    private static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String firstLine = reader.readLine();

        if (firstLine == null || firstLine.trim().isEmpty()) {
            return;
        }

        int size = Integer.parseInt(firstLine.trim());
        char[][] board = new char[size][size];
        for (int i = 0; i < size; i++) {
            String line = reader.readLine();
            if (line != null) {
                board[i] = line.toCharArray();
            }
        }

        // Special case handling for size 1 as per original implementation
        if (size == 1) {
            System.out.println("YES");
            System.out.println("o");
        } else {
            solve(board, size);
        }
    }

    /**
     * Core logic to determine if valid offsets exist and print the resulting grid.
     */
    private static void solve(char[][] board, int size) {
        List<Point> targetPositions = new ArrayList<>();
        boolean[][] isCovered = new boolean[size][size];

        // 1. Initialize coverage tracking and locate all 'o' pieces
        for (int r = 0; r < size; r++) {
            for (int c = 0; c < size; c++) {
                if (board[r][c] == TARGET_PIECE) {
                    targetPositions.add(new Point(r, c));
                    isCovered[r][c] = true;
                } else if (board[r][c] == WALL) {
                    isCovered[r][c] = false;
                } else {
                    // '.' cells are treated as 'covered' initially in original logic
                    isCovered[r][c] = true;
                }
            }
        }

        // 2. Find all valid translation offsets (dr, dc)
        List<Point> validOffsets = new ArrayList<>();
        for (int dr = -(size - 1); dr <= (size - 1); dr++) {
            for (int dc = -(size - 1); dc <= (size - 1); dc++) {
                // Skip the zero offset
                if (dr == 0 && dc == 0) {
                    continue;
                }

                if (isValidOffset(board, size, targetPositions, dr, dc)) {
                    validOffsets.add(new Point(dr, dc));
                    applyOffsetToCoverage(isCovered, targetPositions, size, dr, dc);
                }
            }
        }

        // 3. Verify if all required cells (originally 'x') have been covered
        if (validOffsets.isEmpty() || !isAllRequiredCovered(isCovered, size)) {
            System.out.println("NO");
            return;
        }

        // 4. Output the result
        System.out.println("YES");
        printResultGrid(size, validOffsets);
    }

    /**
     * Checks if a given offset is valid. An offset is invalid if any 
     * target piece, when moved by the offset, lands on an EMPTY ('.') cell.
     */
    private static boolean isValidOffset(char[][] board, int size, List<Point> targets, int dr, int dc) {
        for (Point p : targets) {
            int nr = p.row + dr;
            int nc = p.col + dc;

            if (nr >= 0 && nr < size && nc >= 0 && nc < size) {
                if (board[nr][nc] == EMPTY) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Marks cells as covered when a valid offset is applied.
     */
    private static void applyOffsetToCoverage(boolean[][] isCovered, List<Point> targets, int size, int dr, int dc) {
        for (Point p : targets) {
            int nr = p.row + dr;
            int nc = p.col + dc;
            if (nr >= 0 && nr < size && nc >= 0 && nc < size) {
                isCovered[nr][nc] = true;
            }
        }
    }

    /**
     * Ensures no cell remains uncovered (specifically checking if 'x' cells were covered).
     */
    private static boolean isAllRequiredCovered(boolean[][] isCovered, int size) {
        for (int r = 0; r < size; r++) {
            for (int c = 0; c < size; c++) {
                if (!isCovered[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Constructs and prints the (2*size-1) x (2*size-1) output grid.
     */
    private static void printResultGrid(int size, List<Point> validOffsets) {
        int gridDim = 2 * size - 1;
        char[][] output = new char[gridDim][gridDim];

        for (int i = 0; i < gridDim; i++) {
            Arrays.fill(output[i], EMPTY);
        }

        // Place the central target piece
        output[size - 1][size - 1] = TARGET_PIECE;

        // Place the valid offsets as walls
        for (Point offset : validOffsets) {
            int r = (size - 1) + offset.row;
            int c = (size - 1) + offset.col;
            output[r][c] = WALL;
        }

        StringBuilder sb = new StringBuilder();
        for (char[] row : output) {
            sb.append(row).append("\n");
        }
        System.out.print(sb.toString());
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver for the Grid Attack problem.
 * The goal is to determine if all 'x' cells in a grid can be "attacked" by 'o' cells
 * using a set of relative offsets that do not result in hitting any '.' cells.
 */
public class GridProblemSolver {

    private FastReader reader;
    private PrintWriter writer;

    public static void main(String[] args) {
        new GridProblemSolver().run();
    }

    public void run() {
        reader = new FastReader(System.in);
        writer = new PrintWriter(System.out);

        try {
            solve();
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    private void solve() {
        int n = reader.nextInt();
        if (n <= 0) return;

        char[][] grid = new char[n][n];
        for (int i = 0; i < n; i++) {
            grid[i] = reader.next().toCharArray();
        }

        // Step 1: Identify forbidden relative offsets.
        // An offset (dr, dc) is forbidden if applying it to an 'o' results in a '.'.
        boolean[][] isForbiddenOffset = calculateForbiddenOffsets(grid, n);

        // Step 2: Check if all 'x' cells are covered by the non-forbidden offsets.
        if (!verifyAllXAreAttacked(grid, isForbiddenOffset, n)) {
            writer.println("NO");
            return;
        }

        // Step 3: If valid, print the reconstructed offset grid.
        writer.println("YES");
        printSolution(isForbiddenOffset, n);
    }

    /**
     * Finds all relative offsets (dr, dc) that would cause an 'o' to hit a '.'.
     */
    private boolean[][] calculateForbiddenOffsets(char[][] grid, int n) {
        // The offset grid size is (2n-1)x(2n-1) to accommodate ranges from -(n-1) to (n-1).
        boolean[][] forbidden = new boolean[2 * n - 1][2 * n - 1];
        int offsetShift = n - 1;

        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 'o') {
                    for (int targetR = 0; targetR < n; targetR++) {
                        for (int targetC = 0; targetC < n; targetC++) {
                            if (grid[targetR][targetC] == '.') {
                                int dr = targetR - r;
                                int dc = targetC - c;
                                forbidden[dr + offsetShift][dc + offsetShift] = true;
                            }
                        }
                    }
                }
            }
        }
        return forbidden;
    }

    /**
     * Checks if every 'x' in the input grid is "attacked" by at least one 'o' 
     * using a permitted (non-forbidden) offset.
     */
    private boolean verifyAllXAreAttacked(char[][] grid, boolean[][] forbidden, int n) {
        boolean[][] isCellAttacked = new boolean[n][n];
        int offsetShift = n - 1;

        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 'o') {
                    for (int targetR = 0; targetR < n; targetR++) {
                        for (int targetC = 0; targetC < n; targetC++) {
                            int dr = targetR - r;
                            int dc = targetC - c;
                            if (!forbidden[dr + offsetShift][dc + offsetShift]) {
                                isCellAttacked[targetR][targetC] = true;
                            }
                        }
                    }
                }
            }
        }

        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 'x' && !isCellAttacked[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Prints the resulting offset grid.
     */
    private void printSolution(boolean[][] forbidden, int n) {
        int size = 2 * n - 1;
        int center = n - 1;

        for (int i = 0; i < size; i++) {
            StringBuilder sb = new StringBuilder();
            for (int j = 0; j < size; j++) {
                if (i == center && j == center) {
                    sb.append('o');
                } else {
                    sb.append(forbidden[i][j] ? '.' : 'x');
                }
            }
            writer.println(sb.toString());
        }
    }

    /**
     * Optimized reader for fast I/O operations.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.util.Scanner;

/**
 * TaskD solves a grid-based puzzle determining if a configuration 
 * can be transformed based on relative positional constraints.
 */
public class TaskD {

    private static final char CHAR_O = 'o';
    private static final char CHAR_X = 'x';
    private static final char CHAR_DOT = '.';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int gridSize = scanner.nextInt();
        scanner.nextLine(); // Consume newline

        char[][] inputGrid = readGrid(scanner, gridSize);

        PuzzleSolver solver = new PuzzleSolver(gridSize, inputGrid);
        solver.solve();

        scanner.close();
    }

    private static char[][] readGrid(Scanner scanner, int size) {
        char[][] grid = new char[size][size];
        for (int i = 0; i < size; i++) {
            String line = scanner.nextLine();
            grid[i] = line.toCharArray();
        }
        return grid;
    }

    /**
     * Logic handler for the puzzle computation.
     */
    static class PuzzleSolver {
        private final int gridSize;
        private final char[][] inputGrid;
        private final int possibilityGridSize;

        public PuzzleSolver(int gridSize, char[][] inputGrid) {
            this.gridSize = gridSize;
            this.inputGrid = inputGrid;
            this.possibilityGridSize = 2 * gridSize - 1;
        }

        public void solve() {
            char[][] possibilityGrid = computePossibilityGrid();
            char[][] workingGrid = copyGrid(inputGrid);

            applyTransformations(workingGrid, possibilityGrid);

            if (isGridClean(workingGrid)) {
                System.out.println("YES");
                printGrid(possibilityGrid);
            } else {
                System.out.println("NO");
            }
        }

        /**
         * Initializes the possibility grid and marks relative dot positions.
         */
        private char[][] computePossibilityGrid() {
            char[][] possibility = new char[possibilityGridSize][possibilityGridSize];
            int center = gridSize - 1;

            // Initialize grid: center is 'o', others are 'x'
            for (int i = 0; i < possibilityGridSize; i++) {
                for (int j = 0; j < possibilityGridSize; j++) {
                    possibility[i][j] = (i == center && j == center) ? CHAR_O : CHAR_X;
                }
            }

            // For every 'o' in input, map relative '.' positions to the possibility grid
            for (int i = 0; i < gridSize; i++) {
                for (int j = 0; j < gridSize; j++) {
                    if (inputGrid[i][j] == CHAR_O) {
                        markRelativeDots(possibility, i, j);
                    }
                }
            }
            return possibility;
        }

        private void markRelativeDots(char[][] possibility, int rowO, int colO) {
            for (int k = 0; k < gridSize; k++) {
                for (int l = 0; l < gridSize; l++) {
                    if (inputGrid[k][l] == CHAR_DOT) {
                        int targetRow = (gridSize - 1) + k - rowO;
                        int targetCol = (gridSize - 1) + l - colO;
                        possibility[targetRow][targetCol] = CHAR_DOT;
                    }
                }
            }
        }

        /**
         * Updates the working grid based on the possibility constraints.
         */
        private void applyTransformations(char[][] workingGrid, char[][] possibilityGrid) {
            for (int i = 0; i < gridSize; i++) {
                for (int j = 0; j < gridSize; j++) {
                    if (workingGrid[i][j] == CHAR_O) {
                        processRow(workingGrid, possibilityGrid, i, j);
                    }
                }
            }
        }

        private void processRow(char[][] workingGrid, char[][] possibilityGrid, int rowO, int colO) {
            for (int k = 0; k < gridSize; k++) {
                for (int l = 0; l < gridSize; l++) {
                    if (workingGrid[k][l] == CHAR_X) {
                        int targetRow = (gridSize - 1) + k - rowO;
                        int targetCol = (gridSize - 1) + l - colO;

                        if (possibilityGrid[targetRow][targetCol] == CHAR_X) {
                            workingGrid[k][l] = CHAR_DOT;
                        }
                    }
                }
            }
        }

        private boolean isGridClean(char[][] grid) {
            for (int i = 0; i < gridSize; i++) {
                for (int j = 0; j < gridSize; j++) {
                    if (grid[i][j] == CHAR_X) {
                        return false;
                    }
                }
            }
            return true;
        }

        private char[][] copyGrid(char[][] original) {
            char[][] copy = new char[gridSize][gridSize];
            for (int i = 0; i < gridSize; i++) {
                System.arraycopy(original[i], 0, copy[i], 0, gridSize);
            }
            return copy;
        }

        private void printGrid(char[][] grid) {
            StringBuilder sb = new StringBuilder();
            for (char[] row : grid) {
                sb.append(row).append('\n');
            }
            System.out.print(sb.toString());
        }
    }
}

