/**
 * Application to solve the grid pattern problem.
 * The goal is to determine if a specific grid configuration is valid 
 * based on forbidden relative offsets between specific cell types.
 */
public class GridResolutionApp {

    public static void main(String[] args) {
        try {
            FastReader reader = new FastReader(System.in);
            PrintWriter writer = new PrintWriter(System.out);

            int n = reader.nextInt();
            char[][] inputGrid = new char[n][n];
            for (int i = 0; i < n; i++) {
                inputGrid[i] = reader.next().toCharArray();
            }

