/**
 * Encapsulates the result of the grid solving process.
 */
class SolverResult {
    private final boolean success;
    private final char[][] grid;

    public SolverResult(boolean success, char[][] grid) {
        this.success = success;
        this.grid = grid;
    }

    public boolean isSuccess() {
        return success;
    }

    public char[][] getGrid() {
        return grid;
    }
}

/**
 * Contains the core logic for calculating forbidden offsets and validating the grid.
 */
class GridProblemSolver {
    private final int n;
    private final char[][] inputGrid;
    private final int offsetCenter;
    private final int gridDimension;

    public GridProblemSolver(int n, char[][] inputGrid) {
        this.n = n;
        this.inputGrid = inputGrid;
        this.offsetCenter = n - 1;
        this.gridDimension = 2 * n - 1;
    }

    /**
     * Executes the solving logic.
     * @return A SolverResult containing success status and the generated grid.
     */
    public SolverResult solve() {
        boolean[][] forbiddenOffsets = computeForbiddenOffsets();

        if (!isConfigurationValid(forbiddenOffsets)) {
            return new SolverResult(false, null);
        }

        char[][] resultGrid = buildResultGrid(forbiddenOffsets);
        return new SolverResult(true, resultGrid);
    }

    /**
     * Identifies relative (dr, dc) vectors that are forbidden.
     * A vector is forbidden if moving from an 'o' by that vector lands on a '.'.
     */
    private boolean[][] computeForbiddenOffsets() {
        boolean[][] forbidden = new boolean[gridDimension][gridDimension];

        for (int r1 = 0; r1 < n; r1++) {
            for (int c1 = 0; c1 < n; c1++) {
                if (inputGrid[r1][c1] != 'o') continue;

                for (int r2 = 0; r2 < n; r2++) {
                    for (int c2 = 0; c2 < n; c2++) {
                        if (inputGrid[r2][c2] == '.') {
                            int dr = r2 - r1;
                            int dc = c2 - c1;
                            forbidden[offsetCenter + dr][offsetCenter + dc] = true;
                        }
                    }
                }
            }
        }
        return forbidden;
    }

    /**
     * Checks if every 'x' in the input grid has at least one 'o' 
     * that does not violate the forbidden offset rules.
     */
    private boolean isConfigurationValid(boolean[][] forbiddenOffsets) {
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (inputGrid[r][c] != 'x') continue;

                boolean canSatisfyConstraint = false;
                for (int rO = 0; rO < n; rO++) {
                    for (int cO = 0; cO < n; cO++) {
                        if (inputGrid[rO][cO] == 'o') {
                            // The rule is: check if the vector from 'o' to 'x' is not forbidden
                            // In original logic: !forbidden[n-1 + (x-o_r)][n-1 + (x-o_c)]
                            int dr = r - rO;
                            int dc = c - cO;
                            if (!forbiddenOffsets[offsetCenter + dr][offsetCenter + dc]) {
                                canSatisfyConstraint = true;
                                break;
                            }
                        }
                    }
                    if (canSatisfyConstraint) break;
                }

                if (!canSatisfyConstraint) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Generates the output grid of size (2n-1)x(2n-1) based on forbidden offsets.
     */
    private char[][] buildResultGrid(boolean[][] forbiddenOffsets) {
        char[][] result = new char[gridDimension][gridDimension];

        for (int i = 0; i < gridDimension; i++) {
            for (int j = 0; j < gridDimension; j++) {
                if (i == offsetCenter && j == offsetCenter) {
                    result[i][j] = 'o';
                } else if (forbiddenOffsets[i][j]) {
                    result[i][j] = '.';
                } else {
                    result[i][j] = 'x';
                }
            }
        }
        return result;
    }
}

