import java.io.*;
import java.util.*;

/**
 * GridPatternSolver solves a grid-based pattern problem where 'o' characters
 * define valid relative offsets that must cover all 'x' characters.
 */
public class GridPatternSolver {

    public static void main(String[] args) {
        try (FastReader reader = new FastReader(System.in);
             PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)))) {

            GridPatternSolver solver = new GridPatternSolver();
            solver.solve(reader, writer);

        } catch (Exception e) {
            System.err.println("An error occurred during execution: " + e.getMessage());
            e.printStackTrace();
            System.exit(1);
        }
    }

    /**
     * Core logic for solving the grid pattern problem.
     * 
     * @param reader The input reader.
     * @param writer The output writer.
     * @throws IOException If an I/O error occurs.
     */
    public void solve(FastReader reader, PrintWriter writer) throws IOException {
        String firstLine = reader.next();
        if (firstLine == null) return;

        int n = Integer.parseInt(firstLine);
        char[][] grid = new char[n][n];

        for (int i = 0; i < n; i++) {
            grid[i] = reader.next().toCharArray();
        }

        // isValidOffset[r][c] stores whether the relative offset 
        // (row = r - (n-1), col = c - (n-1)) is valid.
        boolean[][] isValidOffset = new boolean[2 * n - 1][2 * n - 1];
        for (int i = 0; i < 2 * n - 1; i++) {
            Arrays.fill(isValidOffset[i], true);
        }

        // Step 1: Determine invalid offsets.
        // An offset is invalid if applying it to an 'o' results in a '.'
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 'o') {
                    for (int rr = 0; rr < n; rr++) {
                        for (int cc = 0; cc < n; cc++) {
                            if (grid[rr][cc] == '.') {
                                int offsetR = rr - r + (n - 1);
                                int offsetC = cc - c + (n - 1);
                                isValidOffset[offsetR][offsetC] = false;
                            }
                        }
                    }
                }
            }
        }

        // Step 2: Determine which cells in the original grid are "covered".
        // A cell is covered if there is an 'o' such that the offset to this cell is valid.
        boolean[][] isCellCovered = new boolean[n][n];
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 'o') {
                    for (int rr = 0; rr < n; rr++) {
                        for (int cc = 0; cc < n; cc++) {
                            int offsetR = rr - r + (n - 1);
                            int offsetC = cc - c + (n - 1);
                            if (isValidOffset[offsetR][offsetC]) {
                                isCellCovered[rr][cc] = true;
                            }
                        }
                    }
                }
            }
        }

        // Step 3: Verify if all 'x' cells in the input grid are covered.
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 'x' && !isCellCovered[r][c]) {
                    writer.println("NO");
                    return;
                }
            }
        }

        // Step 4: Output the resulting pattern grid of size (2n-1) x (2n-1).
        writer.println("YES");
        for (int i = 0; i < 2 * n - 1; i++) {
            StringBuilder rowOutput = new StringBuilder();
            for (int j = 0; j < 2 * n - 1; j++) {
                if (i == n - 1 && j == n - 1) {
                    rowOutput.append('o');
                } else if (isValidOffset[i][j]) {
                    rowOutput.append('x');
                } else {
                    rowOutput.append('.');
                }
            }
            writer.println(rowOutput.toString());
        }
    }

    /**
     * FastReader utility for efficient input parsing.
     */
    static class FastReader implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            this.reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        @Override
        public void close() throws IOException {
            reader.close();
        }
    }
}

import java.util.Scanner;

/**
 * A solver for reconstructing a large pattern grid based on a smaller input grid.
 * The algorithm determines if a pattern exists that, when applied to the input grid,
 * perfectly reconstructs the original configuration.
 */
public class CF538D {

    private static final char CELL_EMPTY = '.';
    private static final char CELL_OBJECT = 'o';
    private static final char CELL_BLOCKED = 'x';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int gridSize = scanner.nextInt();
        char[][] inputGrid = new char[gridSize][gridSize];

        for (int i = 0; i < gridSize; i++) {
            inputGrid[i] = scanner.next().toCharArray();
        }

        GridPatternSolver solver = new GridPatternSolver(gridSize, inputGrid);
        solver.solve();

        scanner.close();
    }

    /**
     * Encapsulates the logic for solving the grid pattern puzzle.
     */
    static class GridPatternSolver {
        private final int gridSize;
        private final char[][] inputGrid;
        private final int patternSize;

        public GridPatternSolver(int gridSize, char[][] inputGrid) {
            this.gridSize = gridSize;
            this.inputGrid = inputGrid;
            this.patternSize = 2 * gridSize - 1;
        }

        /**
         * Orchestrates the construction, verification, and output of the result.
         */
        public void solve() {
            char[][] patternGrid = constructPatternGrid();
            boolean isMatch = verifyPattern(patternGrid);

            if (isMatch) {
                System.out.println("YES");
                printGrid(patternGrid);
            } else {
                System.out.println("NO");
            }
        }

        /**
         * Constructs the larger pattern grid based on the relative distances
         * between 'o' (objects) and '.' (empty cells) in the input grid.
         */
        private char[][] constructPatternGrid() {
            char[][] pattern = new char[patternSize][patternSize];

            // Initialize pattern with BLOCKED cells
            for (int i = 0; i < patternSize; i++) {
                for (int j = 0; j < patternSize; j++) {
                    pattern[i][j] = CELL_BLOCKED;
                }
            }

            // Set the center cell
            pattern[gridSize - 1][gridSize - 1] = CELL_OBJECT;

            // For every pair of (object, empty), mark the relative position as empty in the pattern
            for (int i = 0; i < gridSize; i++) {
                for (int j = 0; j < gridSize; j++) {
                    if (inputGrid[i][j] != CELL_OBJECT) {
                        continue;
                    }
                    for (int x = 0; x < gridSize; x++) {
                        for (int y = 0; y < gridSize; y++) {
                            if (inputGrid[x][y] == CELL_EMPTY) {
                                int rowIdx = x - i + gridSize - 1;
                                int colIdx = y - j + gridSize - 1;
                                pattern[rowIdx][colIdx] = CELL_EMPTY;
                            }
                        }
                    }
                }
            }
            return pattern;
        }

        /**
         * Verifies if the constructed pattern grid accurately reconstructs the input grid.
         */
        private boolean verifyPattern(char[][] pattern) {
            char[][] simulatedGrid = new char[gridSize][gridSize];

            // Initialize simulated grid with EMPTY cells
            for (int i = 0; i < gridSize; i++) {
                for (int j = 0; j < gridSize; j++) {
                    simulatedGrid[i][j] = CELL_EMPTY;
                }
            }

            // Simulate the application of the pattern
            for (int i = 0; i < gridSize; i++) {
                for (int j = 0; j < gridSize; j++) {
                    if (inputGrid[i][j] != CELL_OBJECT) {
                        continue;
                    }

                    simulatedGrid[i][j] = CELL_OBJECT;

                    // Apply the pattern's blocking rules to the simulated grid
                    for (int x = 0; x < gridSize; x++) {
                        for (int y = 0; y < gridSize; y++) {
                            // Only update if the cell is currently empty and the pattern dictates a block
                            if (simulatedGrid[x][y] == CELL_EMPTY) {
                                int rowIdx = x - i + gridSize - 1;
                                int colIdx = y - j + gridSize - 1;
                                if (pattern[rowIdx][colIdx] == CELL_BLOCKED) {
                                    simulatedGrid[x][y] = CELL_BLOCKED;
                                }
                            }
                        }
                    }
                }
            }

            return isConfigurationIdentical(simulatedGrid);
        }

        /**
         * Compares the simulated grid against the original input grid.
         */
        private boolean isConfigurationIdentical(char[][] simulatedGrid) {
            for (int i = 0; i < gridSize; i++) {
                for (int j = 0; j < gridSize; j++) {
                    if (inputGrid[i][j] != simulatedGrid[i][j]) {
                        return false;
                    }
                }
            }
            return true;
        }

        /**
         * Prints the 2D grid to standard output.
         */
        private void printGrid(char[][] grid) {
            StringBuilder sb = new StringBuilder();
            for (char[] row : grid) {
                sb.append(new String(row)).append("\n");
            }
            System.out.print(sb.toString());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.List;

/**
 * A program to reconstruct a pattern based on the relative positions 
 * of 'o' (open) and 'x' (closed) cells in a grid.
 */
public class PatternReconstructor {

    private enum CellType {
        EMPTY(0),
        OPEN(1),
        CLOSED(-1);

        final int value;

        CellType(int value) {
            this.value = value;
        }

        static CellType fromChar(char c) {
            if (c == 'o') return OPEN;
            if (c == 'x') return CLOSED;
            return EMPTY;
        }
    }

    private static class Coordinate {
        final int row;
        final int col;

        Coordinate(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    public static void main(String[] args) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter writer = new PrintWriter(System.out)) {

            String firstLine = reader.readLine();
            if (firstLine == null) return;

            int gridSize = Integer.parseInt(firstLine.trim());
            CellType[][] inputGrid = parseGrid(reader, gridSize);

            PatternReconstructor solver = new PatternReconstructor();
            solver.solve(gridSize, inputGrid, writer);

        } catch (IOException | NumberFormatException e) {
            System.err.println("Error processing input: " + e.getMessage());
        }
    }

    /**
     * Orchestrates the solving process and outputs the result.
     */
    public void solve(int n, CellType[][] grid, PrintWriter out) {
        List<Coordinate> openCells = findCellsByType(grid, n, CellType.OPEN);
        List<Coordinate> closedCells = findCellsByType(grid, n, CellType.CLOSED);
        List<Coordinate> emptyCells = findCellsByType(grid, n, CellType.EMPTY);

        // Step 1: Determine all valid relative offsets between empty cells and 'o' cells.
        // The pattern size is (2n-1) x (2n-1). We use an offset of (n-1) to map 
        // negative relative distances into a positive array index.
        boolean[][] validOffsets = calculateValidOffsets(emptyCells, openCells, n);

        // Step 2: Validate if all 'x' cells are consistent with the discovered pattern.
        // An 'x' cell is valid if every 'o' cell's relative offset to it exists in the pattern.
        if (!isPatternValid(closedCells, openCells, validOffsets, n)) {
            out.println("NO");
            return;
        }

        // Step 3: Output the resulting reconstructed pattern.
        out.println("YES");
        out.print(formatPattern(validOffsets, n));
        out.flush();
    }

    private CellType[][] parseGrid(BufferedReader reader, int n) throws IOException {
        CellType[][] grid = new CellType[n][n];
        for (int i = 0; i < n; i++) {
            String line = reader.readLine();
            for (int j = 0; j < n; j++) {
                grid[i][j] = CellType.fromChar(line.charAt(j));
            }
        }
        return grid;
    }

    private List<Coordinate> findCellsByType(CellType[][] grid, int n, CellType type) {
        List<Coordinate> cells = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == type) {
                    cells.add(new Coordinate(i, j));
                }
            }
        }
        return cells;
    }

    private boolean[][] calculateValidOffsets(List<Coordinate> emptyCells, List<Coordinate> openCells, int n) {
        int patternDim = 2 * n - 1;
        boolean[][] offsets = new boolean[patternDim][patternDim];
        int offsetShift = n - 1;

        for (Coordinate empty : emptyCells) {
            for (Coordinate open : openCells) {
                int dr = empty.row - open.row + offsetShift;
                int dc = empty.col - open.col + offsetShift;
                if (dr >= 0 && dr < patternDim && dc >= 0 && dc < patternDim) {
                    offsets[dr][dc] = true;
                }
            }
        }
        return offsets;
    }

    private boolean isPatternValid(List<Coordinate> closedCells, List<Coordinate> openCells, boolean[][] validOffsets, int n) {
        int offsetShift = n - 1;
        for (Coordinate closed : closedCells) {
            for (Coordinate open : openCells) {
                int dr = closed.row - open.row + offsetShift;
                int dc = closed.col - open.col + offsetShift;

                // If the relative distance between an 'x' and an 'o' is not in our pattern, it's invalid.
                if (dr < 0 || dr >= validOffsets.length || dc < 0 || dc >= validOffsets[0].length 
                    || !validOffsets[dr][dc]) {
                    return false;
                }
            }
        }
        return true;
    }

    private String formatPattern(boolean[][] validOffsets, int n) {
        StringBuilder sb = new StringBuilder();
        int patternDim = 2 * n - 1;
        int center = n - 1;

        for (int i = 0; i < patternDim; i++) {
            for (int j = 0; j < patternDim; j++) {
                if (i == center && j == center) {
                    sb.append('o');
                } else if (validOffsets[i][j]) {
                    sb.append('.');
                } else {
                    sb.append('x');
                }
            }
            sb.append('\n');
        }
        return sb.toString();
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver for the grid-based movement and coverage problem.
 */
public class GridGameSolver {

    /**
     * Represents a point or vector on the 2D grid.
     */
    public record Coordinate(int r, int c) {}

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            int boardSize = reader.nextInt();
            char[][] grid = reader.readGrid(boardSize);

            Solver solver = new Solver(boardSize, grid);
            solver.solve(writer);
        } catch (IOException | NoSuchElementException e) {
            // In a production environment, use a logger
            System.err.println("Error processing input: " + e.getMessage());
        } finally {
            writer.flush();
            writer.close();
        }
    }

    private static class Solver {
        private final int n;
        private final char[][] grid;
        private final List<Coordinate> piecePositions = new ArrayList<>();
        private final List<Coordinate> targetPositions = new ArrayList<>();

        public Solver(int n, char[][] grid) {
            this.n = n;
            this.grid = grid;
            initializePositions();
        }

        private void initializePositions() {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (grid[i][j] == 'o') {
                        piecePositions.add(new Coordinate(i, j));
                    } else if (grid[i][j] == 'x') {
                        targetPositions.add(new Coordinate(i, j));
                    }
                }
            }
        }

        public void solve(PrintWriter out) {
            List<Coordinate> validOffsets = findValidOffsets();

            if (isCoveragePossible(validOffsets)) {
                out.println("YES");
                printExpandedGrid(validOffsets, out);
            } else {
                out.println("NO");
            }
        }

        /**
         * Finds all relative moves (dx, dy) such that every 'o' piece 
         * moving by that offset does not land on an empty '.' cell.
         */
        private List<Coordinate> findValidOffsets() {
            List<Coordinate> validOffsets = new ArrayList<>();

            for (int dr = -n; dr <= n; dr++) {
                for (int dc = -n; dc <= n; dc++) {
                    if (isValidOffset(dr, dc)) {
                        validOffsets.add(new Coordinate(dr, dc));
                    }
                }
            }
            return validOffsets;
        }

        private boolean isValidOffset(int dr, int dc) {
            for (Coordinate piece : piecePositions) {
                int nr = piece.r() + dr;
                int nc = piece.c() + dc;

                if (isWithinBounds(nr, nc) && grid[nr][nc] == '.') {
                    return false;
                }
            }
            return true;
        }

        /**
         * Checks if the identified move offsets are sufficient to cover all 'x' targets.
         */
        private boolean isCoveragePossible(List<Coordinate> offsets) {
            if (targetPositions.isEmpty()) return true;

            boolean[][] attacked = new boolean[n][n];
            for (Coordinate piece : piecePositions) {
                for (Coordinate offset : offsets) {
                    int nr = piece.r() + offset.r();
                    int nc = piece.c() + offset.c();
                    if (isWithinBounds(nr, nc)) {
                        attacked[nr][nc] = true;
                    }
                }
            }

            for (Coordinate target : targetPositions) {
                if (!attacked[target.r()][target.c()]) {
                    return false;
                }
            }
            return true;
        }

        /**
         * Generates and prints the expanded board based on the valid moves.
         */
        private void printExpandedGrid(List<Coordinate> offsets, PrintWriter out) {
            int expandedSize = 2 * n - 1;
            char[][] expandedGrid = new char[expandedSize][expandedSize];

            // Initialize with empty cells
            for (int i = 0; i < expandedSize; i++) {
                Arrays.fill(expandedGrid[i], '.');
            }

            // The center of the expanded grid corresponds to the original (n,n) context
            int center = n - 1;
            expandedGrid[center][center] = 'o';

            for (Coordinate offset : offsets) {
                int nr = center + offset.r();
                int nc = center + offset.c();

                if (nr >= 0 && nr < expandedSize && nc >= 0 && nc < expandedSize) {
                    if (expandedGrid[nr][nc] == '.') {
                        expandedGrid[nr][nc] = 'x';
                    }
                }
            }

            for (int i = 0; i < expandedSize; i++) {
                out.println(new String(expandedGrid[i]));
            }
        }

        private boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < n && c >= 0 && c < n;
        }
    }

    /**
     * Utility class for efficient input reading.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public char[][] readGrid(int n) {
            char[][] grid = new char[n][n];
            for (int i = 0; i < n; i++) {
                String row = next();
                for (int j = 0; j < n; j++) {
                    grid[i][j] = row.charAt(j);
                }
            }
            return grid;
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * PatternSolver identifies valid translations (shifts) of a pattern within a grid.
 * A shift is considered valid if every 'o' in the original grid, when shifted,
 * lands either outside the grid boundaries or on another 'o' cell.
 */
public class PatternSolver {

    public static void main(String[] args) {
        PatternSolver solver = new PatternSolver();
        solver.solve();
    }

    /**
     * Orchestrates the grid processing logic.
     */
    public void solve() {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            String firstToken = reader.next();
            if (firstToken == null) {
                return;
            }

            int gridSize = Integer.parseInt(firstToken);
            char[][] inputGrid = reader.nextCharGrid(gridSize);

            // The resulting grid size is (2 * N - 1) to accommodate all possible shifts
            int resultSize = 2 * gridSize - 1;
            char[][] resultGrid = new char[resultSize][resultSize];

            // Initialize result grid with '.'
            for (int i = 0; i < resultSize; i++) {
                Arrays.fill(resultGrid[i], '.');
            }

            // The original center of the grid is marked as 'o' in the output
            resultGrid[gridSize - 1][gridSize - 1] = 'o';

            // Iterate through all possible translation offsets (di, dj)
            // The range is from -(gridSize - 1) to (gridSize - 1)
            for (int di = -gridSize + 1; di < gridSize; di++) {
                for (int dj = -gridSize + 1; dj < gridSize; dj++) {

                    // Skip the zero offset (the original position)
                    if (di == 0 && dj == 0) {
                        continue;
                    }

                    if (isShiftValid(inputGrid, gridSize, di, dj)) {
                        // Mark the valid shift in the output grid
                        resultGrid[gridSize - 1 + di][gridSize - 1 + dj] = 'x';

                        // Update the input grid based on the valid shift
                        updateGridWithShift(inputGrid, gridSize, di, dj);
                    }
                }
            }

            // Perform final validation check as per original logic
            if (containsCharacter(inputGrid, gridSize, 'x')) {
                out.println("NO");
            } else {
                out.println("YES");
                printGrid(out, resultGrid);
            }

        } catch (Exception e) {
            // In a production environment, use a logging framework here
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Checks if a specific shift (di, dj) is valid.
     * A shift is invalid if any 'o' cell translates into a '.' cell.
     */
    private boolean isShiftValid(char[][] grid, int n, int di, int dj) {
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 'o') {
                    int targetR = r + di;
                    int targetC = c + dj;

                    // Check if the target position is within bounds
                    if (targetR >= 0 && targetR < n && targetC >= 0 && targetC < n) {
                        if (grid[targetR][targetC] == '.') {
                            return false;
                        }
                    }
                }
            }
        }
        return true;
    }

    /**
     * Updates the input grid by marking cells that are hit by a valid shift.
     */
    private void updateGridWithShift(char[][] grid, int n, int di, int dj) {
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 'o') {
                    int targetR = r + di;
                    int targetC = c + dj;

                    if (targetR >= 0 && targetR < n && targetC >= 0 && targetC < n) {
                        if (grid[targetR][targetC] != 'o') {
                            grid[targetR][targetC] = 'y';
                        }
                    }
                }
            }
        }
    }

    /**
     * Checks if the grid contains a specific character.
     */
    private boolean containsCharacter(char[][] grid, int n, char target) {
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == target) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Helper to print the 2D grid efficiently.
     */
    private void printGrid(PrintWriter out, char[][] grid) {
        for (char[] row : grid) {
            out.println(new String(row));
        }
    }

    /**
     * High-performance reader for large input sets.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream is) {
            this.reader = new BufferedReader(new InputStreamReader(is));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public char[][] nextCharGrid(int n) {
            char[][] grid = new char[n][n];
            for (int i = 0; i < n; i++) {
                String line = next();
                if (line != null) {
                    grid[i] = line.toCharArray();
                }
            }
            return grid;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solution class to solve the grid attack pattern problem.
 * The goal is to find a set of relative offsets that, when applied to all player cells,
 * do not hit any empty cells, and use these offsets to clear all blocked cells.
 */
public class Solution {

    private static final int EMPTY = 0;
    private static final int BLOCKED = -1;
    private static final int PLAYER = 1;

    public static void main(String[] args) {
        InputReader reader = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            String firstToken = reader.next();
            if (firstToken == null) return;
            int n = Integer.parseInt(firstToken);

            Grid grid = new Grid(n);
            for (int i = 0; i < n; i++) {
                String row = reader.next();
                for (int j = 0; j < n; j++) {
                    grid.setCell(i, j, row.charAt(j));
                }
            }

            solve(grid, out);
        } catch (Exception e) {
            // In a production environment, use a proper logger
        } finally {
            out.close();
        }
    }

    private static void solve(Grid grid, PrintWriter out) {
        int n = grid.getSize();
        List<Point> playerPoints = grid.getPlayerPositions();
        List<Offset> validOffsets = findValidOffsets(grid, playerPoints, n);

        // Simulate the attack: clearing cells hit by valid offsets from players
        for (Point p : playerPoints) {
            for (Offset offset : validOffsets) {
                int targetR = p.row + offset.dr;
                int targetC = p.col + offset.dc;

                if (grid.isWithinBounds(targetR, targetC)) {
                    // If the cell hit is not a player, it becomes empty
                    if (grid.getCell(targetR, targetC) != PLAYER) {
                        grid.setCell(targetR, targetC, '.');
                    }
                }
            }
        }

        // Check if any blocked cells ('x') remain
        if (grid.hasRemainingBlockedCells()) {
            out.println("NO");
        } else {
            out.println("YES");
            printAttackPattern(out, n, validOffsets);
        }
    }

    /**
     * Finds all relative offsets (dr, dc) such that for every player, 
     * the cell at (player.r + dr, player.c + dc) is either out of bounds, 
     * a player, or a blocked cell (i.e., NOT an empty cell).
     */
    private static List<Offset> findValidOffsets(Grid grid, List<Point> players, int n) {
        List<Offset> validOffsets = new ArrayList<>();
        for (int dr = -(n - 1); dr < n; dr++) {
            for (int dc = -(n - 1); dc < n; dc++) {
                if (dr == 0 && dc == 0) continue;

                if (isOffsetValid(grid, players, dr, dc)) {
                    validOffsets.add(new Offset(dr, dc));
                }
            }
        }
        return validOffsets;
    }

    private static boolean isOffsetValid(Grid grid, List<Point> players, int dr, int dc) {
        for (Point p : players) {
            int nr = p.row + dr;
            int nc = p.col + dc;
            if (grid.isWithinBounds(nr, nc)) {
                if (grid.getCell(nr, nc) == EMPTY) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Generates and prints the symmetric pattern based on the valid offsets.
     */
    private static void printAttackPattern(PrintWriter out, int n, List<Offset> offsets) {
        int patternSize = 2 * n - 1;
        char[][] pattern = new char[patternSize][patternSize];
        for (int i = 0; i < patternSize; i++) {
            Arrays.fill(pattern[i], '.');
        }

        int mid = n - 1;
        pattern[mid][mid] = 'o';
        for (Offset offset : offsets) {
            int pr = mid + offset.dr;
            int pc = mid + offset.dc;
            // The bounds check is logically guaranteed by the offset range
            pattern[pr][pc] = 'x';
        }

        for (int i = 0; i < patternSize; i++) {
            out.println(new String(pattern[i]));
        }
    }

    // --- Helper Classes ---

    static class Point {
        final int row, col;
        Point(int row, int col) { this.row = row; this.col = col; }
    }

    static class Offset {
        final int dr, dc;
        Offset(int dr, int dc) { this.dr = dr; this.dc = dc; }
    }

    static class Grid {
        private final int[][] matrix;
        private final int size;

        Grid(int size) {
            this.size = size;
            this.matrix = new int[size][size];
        }

        void setCell(int r, int c, char ch) {
            if (ch == '.') matrix[r][c] = EMPTY;
            else if (ch == 'x') matrix[r][c] = BLOCKED;
            else if (ch == 'o') matrix[r][c] = PLAYER;
        }

        int getCell(int r, int c) { return matrix[r][c]; }

        int getSize() { return size; }

        boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < size && c >= 0 && c < size;
        }

        List<Point> getPlayerPositions() {
            List<Point> players = new ArrayList<>();
            for (int i = 0; i < size; i++) {
                for (int j = 0; j < size; j++) {
                    if (matrix[i][j] == PLAYER) {
                        players.add(new Point(i, j));
                    }
                }
            }
            return players;
        }

        boolean hasRemainingBlockedCells() {
            for (int i = 0; i < size; i++) {
                for (int j = 0; j < size; j++) {
                    if (matrix[i][j] == BLOCKED) return true;
                }
            }
            return false;
        }
    }

    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * PatternSolver reconstructs a relative movement pattern based on a given grid
 * containing sources ('o'), targets ('x'), and empty spaces ('.').
 * 
 * The core logic identifies "illegal" relative offsets—offsets that would cause 
 * a source to land on an empty space—and verifies if all targets can be covered 
 * by "legal" offsets.
 */
public class PatternSolver {

    // Character constants for better readability and maintenance
    private static final char SOURCE = 'o';
    private static final char TARGET = 'x';
    private static final char EMPTY = '.';
    private static final char COVERED = '#';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int boardSize = scanner.nextInt();
        char[][] board = new char[boardSize][boardSize];

        for (int i = 0; i < boardSize; i++) {
            String row = scanner.next();
            board[i] = row.toCharArray();
        }

        PatternSolver solver = new PatternSolver();
        solver.solve(boardSize, board);
    }

    /**
     * Orchestrates the solving, validation, and output process.
     */
    public void solve(int n, char[][] board) {
        // Step 1: Determine which relative offsets are invalid
        boolean[][] isIllegalOffset = calculateIllegalOffsets(n, board);

        // Step 2: Verify if the existing targets can be satisfied by legal offsets
        if (isPatternValid(n, board, isIllegalOffset)) {
            System.out.println("YES");

            // Step 3: Generate and print the resulting pattern
            char[][] pattern = constructPattern(n, isIllegalOffset);
            printPattern(pattern, n);
        } else {
            System.out.println("NO");
        }
    }

    /**
     * An offset (dr, dc) is illegal if there exists at least one source 'o' 
     * that, when shifted by this offset, lands on an empty space '.'.
     * 
     * @return A boolean grid where index [dr + n][dc + n] indicates if the offset is illegal.
     */
    private boolean[][] calculateIllegalOffsets(int n, char[][] board) {
        boolean[][] illegal = new boolean[2 * n][2 * n];
        List<int[]> sourcePositions = new ArrayList<>();
        List<int[]> emptyPositions = new ArrayList<>();

        // Locate all sources and empty cells to reduce unnecessary iterations
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (board[r][c] == SOURCE) {
                    sourcePositions.add(new int[]{r, c});
                } else if (board[r][c] == EMPTY) {
                    emptyPositions.add(new int[]{r, c});
                }
            }
        }

        // Determine illegal offsets
        for (int[] source : sourcePositions) {
            for (int[] empty : emptyPositions) {
                int dr = empty[0] - source[0];
                int dc = empty[1] - source[1];
                // Map dr, dc from [-(n-1), n-1] to [1, 2n-1] for array indexing
                illegal[dr + n][dc + n] = true;
            }
        }
        return illegal;
    }

    /**
     * Checks if every target 'x' on the board can be reached by at least one 
     * source 'o' using a valid (non-illegal) offset.
     */
    private boolean isPatternValid(int n, char[][] board, boolean[][] isIllegalOffset) {
        boolean[][] targetIsCovered = new boolean[n][n];

        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (board[r][c] == SOURCE) {
                    // Check all possible offsets in the pattern range
                    for (int dr = -(n - 1); dr <= n - 1; dr++) {
                        for (int dc = -(n - 1); dc <= n - 1; dc++) {
                            if (!isIllegalOffset[dr + n][dc + n]) {
                                int nr = r + dr;
                                int nc = c + dc;
                                // If the offset hits a target, mark that target as covered
                                if (nr >= 0 && nr < n && nc >= 0 && nc < n) {
                                    if (board[nr][nc] == TARGET) {
                                        targetIsCovered[nr][nc] = true;
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }

        // If any target remains uncovered, the pattern is invalid
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (board[r][c] == TARGET && !targetIsCovered[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Constructs the (2n-1)x(2n-1) pattern grid.
     */
    private char[][] constructPattern(int n, boolean[][] isIllegalOffset) {
        char[][] pattern = new char[2 * n][2 * n];
        for (int i = 0; i < 2 * n; i++) {
            Arrays.fill(pattern[i], EMPTY);
        }

        // Fill the pattern based on valid offsets
        for (int r = 1; r < 2 * n; r++) {
            for (int c = 1; c < 2 * n; c++) {
                if (!isIllegalOffset[r][c]) {
                    pattern[r][c] = TARGET;
                }
            }
        }

        // The center of the pattern (at index n, n) is the source 'o'
        pattern[n][n] = SOURCE;
        return pattern;
    }

    /**
     * Efficiently prints the pattern to the console.
     */
    private void printPattern(char[][] pattern, int n) {
        PrintWriter out = new PrintWriter(System.out);
        // The pattern dimensions are (2n-1) x (2n-1), using indices 1 to 2n-1
        for (int r = 1; r < 2 * n; r++) {
            for (int c = 1; c < 2 * n; c++) {
                out.print(pattern[r][c]);
            }
            out.println();
        }
        out.flush();
    }
}

import java.io.*;
import java.util.*;

/**
 * WeirdChess solves a puzzle involving 'x', 'o', and '.' characters on a grid.
 * It determines if a valid configuration of 'o' characters can cover all 'x' cells
 * based on a set of allowable relative shifts.
 */
public class WeirdChess {

    private final FastReader reader;
    private final PrintWriter writer;

    public WeirdChess() {
        this.reader = new FastReader(System.in);
        this.writer = new PrintWriter(System.out);
    }

    public static void main(String[] args) {
        new WeirdChess().run();
    }

    /**
     * Orchestrates the execution of the program.
     */
    public void run() {
        try {
            int gridSize = reader.nextInt();
            char[][] board = readBoard(gridSize);

            boolean[][] isValidShift = calculateValidShifts(board, gridSize);

            if (isAllXCovered(board, isValidShift, gridSize)) {
                printResult(true, isValidShift, gridSize);
            } else {
                printResult(false, null, gridSize);
            }
        } catch (Exception e) {
            // In a production environment, use a proper logging framework.
            // For competitive programming, we handle input/output errors gracefully.
        } finally {
            writer.close();
        }
    }

    private char[][] readBoard(int n) {
        char[][] board = new char[n][n];
        for (int i = 0; i < n; i++) {
            board[i] = reader.next().toCharArray();
        }
        return board;
    }

    /**
     * Determines which relative shifts (dr, dc) are valid.
     * A shift is invalid if applying it to an 'o' lands on a '.' cell.
     */
    private boolean[][] calculateValidShifts(char[][] board, int n) {
        int shiftDimension = 2 * n - 1;
        boolean[][] isValidShift = new boolean[shiftDimension][shiftDimension];

        for (boolean[] row : isValidShift) {
            Arrays.fill(row, true);
        }

        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (board[r][c] == 'o') {
                    invalidateShiftsForPoint(board, r, c, n, isValidShift);
                }
            }
        }
        return isValidShift;
    }

    private void invalidateShiftsForPoint(char[][] board, int r, int c, int n, boolean[][] isValidShift) {
        for (int k = 0; k < n; k++) {
            for (int m = 0; m < n; m++) {
                if (board[k][m] == '.') {
                    int dr = k - r;
                    int dc = m - c;
                    int shiftIdxR = dr + n - 1;
                    int shiftIdxC = dc + n - 1;
                    isValidShift[shiftIdxR][shiftIdxC] = false;
                }
            }
        }
    }

    /**
     * Checks if every 'x' on the board is "covered" by an 'o' via a valid shift.
     */
    private boolean isAllXCovered(char[][] board, boolean[][] isValidShift, int n) {
        boolean[][] isCellCovered = new boolean[n][n];

        // Compute coverage
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (board[r][c] == 'o') {
                    markCoveredCells(r, c, n, isValidShift, isCellCovered);
                }
            }
        }

        // Validate all 'x' cells
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (board[r][c] == 'x' && !isCellCovered[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    private void markCoveredCells(int r, int c, int n, boolean[][] isValidShift, boolean[][] isCellCovered) {
        for (int dr = -n + 1; dr <= n - 1; dr++) {
            for (int dc = -n + 1; dc <= n - 1; dc++) {
                int targetR = r + dr;
                int targetC = c + dc;

                if (targetR >= 0 && targetR < n && targetC >= 0 && targetC < n) {
                    if (isValidShift[dr + n - 1][dc + n - 1]) {
                        isCellCovered[targetR][targetC] = true;
                    }
                }
            }
        }
    }

    /**
     * Outputs the final YES/NO and the resulting grid.
     */
    private void printResult(boolean success, boolean[][] isValidShift, int n) {
        if (!success) {
            writer.println("NO");
            return;
        }

        writer.println("YES");
        int dim = 2 * n - 1;
        int center = n - 1;

        for (int i = 0; i < dim; i++) {
            StringBuilder rowBuilder = new StringBuilder();
            for (int j = 0; j < dim; j++) {
                if (i == center && j == center) {
                    rowBuilder.append('o');
                } else if (isValidShift[i][j]) {
                    rowBuilder.append('x');
                } else {
                    rowBuilder.append('.');
                }
            }
            writer.println(rowBuilder.toString());
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

