/**
 * Handles the core logic for processing the grid patterns.
 */
class GridProcessor {
    private static final char DOT = '.';
    private static final char ORB = 'o';
    private static final char CROSS = 'x';
    private static final char EMPTY = '\0';

    private final FastReader reader;

    public GridProcessor(FastReader reader) {
        this.reader = reader;
    }

    /**
     * Reads the grid, computes the result, validates the constraints, 
     * and writes the output.
     * 
     * @param out The PrintWriter used to output the results.
     */
    public void solve(PrintWriter out) throws IOException {
        String line = reader.readLine();
        if (line == null) return;

        int gridSize = Integer.parseInt(line.trim());
        char[][] inputGrid = readGrid(gridSize);

        // The result grid is size (2n-1) x (2n-1)
        int resultSize = 2 * gridSize - 1;
        char[][] resultGrid = new char[resultSize][resultSize];

        // Initial state: center of the result grid is an 'orb'
        resultGrid[gridSize - 1][gridSize - 1] = ORB;

        // Step 1: Calculate relative positions of '.' and 'o'
        populateResultDots(gridSize, inputGrid, resultGrid);

        // Step 2: Validate if 'x' positions are valid according to the rules
        if (!validateCrossPositions(gridSize, inputGrid, resultGrid)) {
            out.println("NO");
            return;
        }

        // Step 3: Output the final grid
        out.println("YES");
        printResultGrid(out, resultGrid, resultSize);
    }

    private char[][] readGrid(int n) throws IOException {
        char[][] grid = new char[n][n];
        for (int i = 0; i < n; i++) {
            String row = reader.readLine();
            for (int j = 0; j < n; j++) {
                grid[i][j] = row.charAt(j);
            }
        }
        return grid;
    }

    private void populateResultDots(int n, char[][] inputGrid, char[][] resultGrid) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (inputGrid[i][j] == DOT) {
                    // Check all 'o' positions to find relative offsets
                    for (int k = 0; k < n; k++) {
                        for (int l = 0; l < n; l++) {
                            if (inputGrid[k][l] == ORB) {
                                int resI = n + i - k - 1;
                                int resJ = n + j - l - 1;
                                resultGrid[resI][resJ] = DOT;
                            }
                        }
                    }
                }
            }
        }
    }

    private boolean validateCrossPositions(int n, char[][] inputGrid, char[][] resultGrid) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (inputGrid[i][j] == CROSS) {
                    if (!isCrossPositionValid(n, i, j, inputGrid, resultGrid)) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    private boolean isCrossPositionValid(int n, int i, int j, char[][] inputGrid, char[][] resultGrid) {
        for (int k = 0; k < n; k++) {
            for (int l = 0; l < n; l++) {
                if (inputGrid[k][l] == ORB) {
                    int resI = n + i - k - 1;
                    int resJ = n + j - l - 1;
                    // A cross is valid if there's an orb such that the result cell is not a dot
                    if (resultGrid[resI][resJ] != DOT) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    private void printResultGrid(PrintWriter out, char[][] resultGrid, int size) {
        for (int i = 0; i < size; i++) {
            StringBuilder sb = new StringBuilder();
            for (int j = 0; j < size; j++) {
                char cell = resultGrid[i][j];
                // If the cell was never assigned, it becomes a cross
                sb.append(cell == EMPTY ? CROSS : cell);
            }
            out.println(sb.toString());
        }
    }
}

