/**
 * Represents a 2D coordinate on the grid.
 */
record Coordinate(int row, int col) {}

/**
 * Contains the core logic for solving the board pattern problem.
 */
class BoardPatternSolver {
    private final int size;
    private final char[][] board;

    public BoardPatternSolver(int size, char[][] board) {
        this.size = size;
        this.board = board;
    }

    /**
     * Executes the solver logic and writes the result to the output.
     */
    public void solve(FastWriter out) throws IOException {
        List<Coordinate> pieceLocations = findPieces('o');
        List<Coordinate> validShifts = findValidShifts(pieceLocations);

        if (!isPatternValid(validShifts)) {
            out.printLine("NO");
            return;
        }

        out.printLine("YES");
        out.printLine(constructResultGrid(validShifts));
    }

    private List<Coordinate> findPieces(char target) {
        List<Coordinate> pieces = new ArrayList<>();
        for (int r = 0; r < size; r++) {
            for (int c = 0; c < size; c++) {
                if (board[r][c] == target) {
                    pieces.add(new Coordinate(r, c));
                }
            }
        }
        return pieces;
    }

    /**
     * Finds all relative shifts (dr, dc) where shifting all 'o' pieces
     * does not result in any piece landing on an empty cell ('.').
     */
    private List<Coordinate> findValidShifts(List<Coordinate> pieces) {
        List<Coordinate> shifts = new ArrayList<>();
        for (int dr = -size + 1; dr < size; dr++) {
            for (int dc = -size + 1; dc < size; dc++) {
                if (dr == 0 && dc == 0) continue;

                if (isValidShift(dr, dc, pieces)) {
                    shifts.add(new Coordinate(dr, dc));
                }
            }
        }
        return shifts;
    }

    private boolean isValidShift(int dr, int dc, List<Coordinate> pieces) {
        for (Coordinate p : pieces) {
            int newRow = p.row() + dr;
            int newCol = p.col() + dc;
            if (isInBounds(newRow, newCol) && board[newRow][newCol] == '.') {
                return false;
            }
        }
        return true;
    }

    /**
     * Validates that every 'x' on the original board is accounted for by one of the valid shifts.
     */
    private boolean isPatternValid(List<Coordinate> validShifts) {
        for (int r = 0; r < size; r++) {
            for (int c = 0; c < size; c++) {
                if (board[r][c] == 'x') {
                    if (!isXCoveredByShift(r, c, validShifts)) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    private boolean isXCoveredByShift(int xRow, int xCol, List<Coordinate> validShifts) {
        for (Coordinate shift : validShifts) {
            int originalRow = xRow - shift.row();
            int originalCol = xCol - shift.col();
            if (isInBounds(originalRow, originalCol) && board[originalRow][originalCol] == 'o') {
                return true;
            }
        }
        return false;
    }

    /**
     * Constructs the required (2N-1) x (2N-1) output grid.
     */
    private char[][] constructResultGrid(List<Coordinate> validShifts) {
        int newSize = 2 * size - 1;
        char[][] result = new char[newSize][newSize];
        for (char[] row : result) {
            Arrays.fill(row, '.');
        }

        // The center of the new grid is the original 'o' piece reference point
        result[size - 1][size - 1] = 'o';

        for (Coordinate shift : validShifts) {
            int targetRow = size + shift.row() - 1;
            int targetCol = size + shift.col() - 1;
            result[targetRow][targetCol] = 'x';
        }
        return result;
    }

    private boolean isInBounds(int r, int c) {
        return r >= 0 && r < size && c >= 0 && c < size;
    }
}

/**
 * High-performance input reader.
 */
class FastReader implements AutoCloseable {
    private final BufferedReader reader;

    public FastReader(InputStream is) {
        this.reader = new BufferedReader(new InputStreamReader(is));
    }

    public int nextInt() throws IOException {
        String line = reader.readLine();
        if (line == null) return 0;
