import java.io.*;
import java.util.*;

/**
 * A program to solve the grid-shifting problem.
 * Finds valid relative shifts of 'o' characters that do not land on '.' characters,
 * ensuring all 'x' target characters are covered by at least one valid shift.
 */
public class Main {

    public static void main(String[] args) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter writer = new PrintWriter(new OutputStreamWriter(System.out))) {

            String firstLine = reader.readLine();
            if (firstLine == null) return;

            int n = Integer.parseInt(firstLine.trim());
            char[][] inputGrid = new char[n][n];

            for (int i = 0; i < n; i++) {
                String row = reader.readLine();
                if (row != null) {
                    inputGrid[i] = row.toCharArray();
                }
            }

            GridShiftSolver solver = new GridShiftSolver(n, inputGrid);
            GridShiftSolver.Solution solution = solver.solve();

            if (solution.isPossible) {
                writer.println("YES");
                printGrid(solution.resultGrid, writer);
            } else {
                writer.println("NO");
            }
            writer.flush();

        } catch (IOException | NumberFormatException e) {
            System.err.println("Error processing input: " + e.getMessage());
        }
    }

    private static void printGrid(char[][] grid, PrintWriter writer) {
        for (char[] row : grid) {
            writer.println(new String(row));
        }
    }
}

class GridShiftSolver {
    private static final char EMPTY = '.';
    private static final char SOURCE = 'o';
    private static final char TARGET = 'x';
    private static final char RESULT_SHIFT_MARKER = 'x';
    private static final char RESULT_CENTER_MARKER = 'o';

    private final int gridSize;
    private final char[][] inputGrid;
    private final List<int[]> sourcePositions;

    /**
     * Represents the result of the grid shifting computation.
     */
    public static class Solution {
        public final boolean isPossible;
        public final char[][] resultGrid;

        public Solution(boolean isPossible, char[][] resultGrid) {
            this.isPossible = isPossible;
            this.resultGrid = resultGrid;
        }
    }

    public GridShiftSolver(int gridSize, char[][] inputGrid) {
        this.gridSize = gridSize;
        this.inputGrid = inputGrid;
        this.sourcePositions = findSourcePositions();
    }

    /**
     * Finds all coordinates containing the 'o' character to optimize shift checking.
     */
    private List<int[]> findSourcePositions() {
        List<int[]> positions = new ArrayList<>();
        for (int r = 0; r < gridSize; r++) {
            for (int c = 0; c < gridSize; c++) {
                if (inputGrid[r][c] == SOURCE) {
                    positions.add(new int[]{r, c});
                }
            }
        }
        return positions;
    }

    /**
     * Executes the core logic to determine if target coverage is possible.
     */
    public Solution solve() {
        boolean[][] coverageMap = new boolean[gridSize][gridSize];
        char[][] resultGrid = createInitialResultGrid();

        // Iterate through all possible relative shifts (dr, dc)
        for (int dr = -gridSize + 1; dr < gridSize; dr++) {
            for (int dc = -gridSize + 1; dc < gridSize; dc++) {
                // The (0,0) shift is skipped as per the original algorithm logic
                if (dr == 0 && dc == 0) {
                    continue;
                }

                if (isValidShift(dr, dc)) {
                    markCoverage(dr, dc, coverageMap);
                    resultGrid[gridSize - 1 + dr][gridSize - 1 + dc] = RESULT_SHIFT_MARKER;
                }
            }
        }

        boolean allTargetsCovered = checkTargetCoverage(coverageMap);
        return new Solution(allTargetsCovered, resultGrid);
    }

    private char[][] createInitialResultGrid() {
        int resSize = 2 * gridSize - 1;
        char[][] res = new char[resSize][resSize];
        for (int i = 0; i < resSize; i++) {
            Arrays.fill(res[i], EMPTY);
        }
        // The center of the resulting grid corresponds to the (0,0) shift
        res[gridSize - 1][gridSize - 1] = RESULT_CENTER_MARKER;
        return res;
    }

    /**
     * Validates if a shift (dr, dc) is allowed. 
     * A shift is invalid if any 'o' lands on a '.' cell.
     */
    private boolean isValidShift(int dr, int dc) {
        for (int[] pos : sourcePositions) {
            int nr = pos[0] + dr;
            int nc = pos[1] + dc;

            if (isWithinBounds(nr, nc) && inputGrid[nr][nc] == EMPTY) {
                return false;
            }
        }
        return true;
    }

    /**
     * Updates the coverage map with cells that are landed on by shifted 'o' sources.
     */
    private void markCoverage(int dr, int dc, boolean[][] coverageMap) {
        for (int[] pos : sourcePositions) {
            int nr = pos[0] + dr;
            int nc = pos[1] + dc;

            if (isWithinBounds(nr, nc)) {
                coverageMap[nr][nc] = true;
            }
        }
    }

    /**
     * Verifies if every 'x' in the original grid is covered by at least one valid shift.
     */
    private boolean checkTargetCoverage(boolean[][] coverageMap) {
        for (int r = 0; r < gridSize; r++) {
            for (int c = 0; c < gridSize; c++) {
                if (inputGrid[r][c] == TARGET && !coverageMap[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < gridSize && c >= 0 && c < gridSize;
    }
}

import java.util.Scanner;

/**
 * The MaskProcessor class computes a transformation mask based on a provided grid
 * and validates whether certain attack conditions are met.
 */
public class MaskProcessor {

    // Constants for board characters
    private static final char EMPTY_CELL = '.';
    private static final char PIECE_CELL = 'o';
    private static final char ATTACK_CELL = 'x';

    // Constants for mask characters
    private static final char MASK_NULL = '\u0000';
    private static final char MASK_DOT = '.';
    private static final char MASK_X = 'x';
    private static final char MASK_PIECE = 'o';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int gridSize = scanner.nextInt();
        scanner.nextLine(); // Consume newline

        char[][] board = readBoard(scanner, gridSize);
        char[][] mask = computeMask(gridSize, board);

        if (validateAttacks(gridSize, board, mask)) {
            System.out.println("YES");
            printMask(mask);
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Reads the grid from the standard input.
     */
    private static char[][] readBoard(Scanner scanner, int size) {
        char[][] board = new char[size][size];
        for (int i = 0; i < size; i++) {
            board[i] = scanner.nextLine().toCharArray();
        }
        return board;
    }

    /**
     * Computes the transformation mask based on the relative positions 
     * of empty cells and pieces.
     */
    private static char[][] computeMask(int n, char[][] board) {
        int maskSize = 2 * n - 1;
        char[][] mask = new char[maskSize][maskSize];

        // Initialize central piece
        mask[n - 1][n - 1] = MASK_PIECE;

        // Step 1: Mark relative positions of empty cells and pieces
        for (int emptyRow = 0; emptyRow < n; emptyRow++) {
            for (int emptyCol = 0; emptyCol < n; emptyCol++) {
                if (board[emptyRow][emptyCol] == EMPTY_CELL) {
                    applyPieceRelativity(n, board, mask, emptyRow, emptyCol);
                }
            }
        }

        // Step 2: Replace uninitialized mask cells with 'x'
        for (int i = 0; i < maskSize; i++) {
            for (int j = 0; j < maskSize; j++) {
                if (mask[i][j] == MASK_NULL) {
                    mask[i][j] = MASK_X;
                }
            }
        }

        return mask;
    }

    /**
     * Helper to mark mask based on piece positions relative to an empty cell.
     */
    private static void applyPieceRelativity(int n, char[][] board, char[][] mask, int emptyRow, int emptyCol) {
        for (int pieceRow = 0; pieceRow < n; pieceRow++) {
            for (int pieceCol = 0; pieceCol < n; pieceCol++) {
                if (board[pieceRow][pieceCol] == PIECE_CELL) {
                    int maskRow = (n - 1) + (emptyRow - pieceRow);
                    int maskCol = (n - 1) + (emptyCol - pieceCol);
                    mask[maskRow][maskCol] = MASK_DOT;
                }
            }
        }
    }

    /**
     * Validates that every 'x' cell in the board can be "hit" by an 'o' piece
     * according to the computed mask.
     */
    private static boolean validateAttacks(int n, char[][] board, char[][] mask) {
        for (int attackRow = 0; attackRow < n; attackRow++) {
            for (int attackCol = 0; attackCol < n; attackCol++) {
                if (board[attackRow][attackCol] == ATTACK_CELL) {
                    if (!isAttackValid(n, board, mask, attackRow, attackCol)) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    /**
     * Checks if a specific attack cell is valid based on the mask and piece positions.
     */
    private static boolean isAttackValid(int n, char[][] board, char[][] mask, int attackRow, int attackCol) {
        for (int pieceRow = 0; pieceRow < n; pieceRow++) {
            for (int pieceCol = 0; pieceCol < n; pieceCol++) {
                if (board[pieceRow][pieceCol] == PIECE_CELL) {
                    int maskRow = (n - 1) + (attackRow - pieceRow);
                    int maskCol = (n - 1) + (attackCol - pieceCol);

                    if (mask[maskRow][maskCol] == MASK_X) {
                        return true; // Found a valid hit
                    }
                }
            }
        }
        return false;
    }

    /**
     * Prints the resulting mask to the console.
     */
    private static void printMask(char[][] mask) {
        for (char[] row : mask) {
            System.out.println(new String(row));
        }
    }
}

