        }
    }

    /**
     * Contains the core logic for processing the grids.
     */
    static class GridSolver {
        private final int gridSize;
        private final char[][] inputGrid;
        private char[][] expandedGrid;

        public GridSolver(int gridSize, char[][] inputGrid) {
            this.gridSize = gridSize;
            this.inputGrid = inputGrid;
        }

        /**
         * Executes the solver logic and prints the result to the output.
         */
        public void solve(PrintWriter out) {
            this.expandedGrid = buildExpandedGrid();

            if (validateExpandedGrid()) {
                out.println("YES");
                printGrid(out, expandedGrid);
            } else {
                out.println("NO");
            }
        }

        /**
         * Constructs the expanded grid based on the relative positions 
         * of 'o' and '.' in the input grid.
         */
        private char[][] buildExpandedGrid() {
            int expandedSize = 2 * gridSize - 1;
            char[][] res = new char[expandedSize][expandedSize];

            // Initialize expanded grid with 'x'
            for (int i = 0; i < expandedSize; i++) {
                Arrays.fill(res[i], 'x');
            }

            // Set the center point
            int center = gridSize - 1;
            res[center][center] = 'o';

            // Apply the pattern rule
            for (int r = 0; r < gridSize; r++) {
                for (int c = 0; c < gridSize; c++) {
                    if (inputGrid[r][c] == 'o') {
                        applyPatternForPoint(r, c, res, center);
                    }
                }
            }
            return res;
        }

        private void applyPatternForPoint(int originRow, int originCol, char[][] res, int center) {
            for (int r = 0; r < gridSize; r++) {
                for (int c = 0; c < gridSize; c++) {
                    if (inputGrid[r][c] == '.') {
                        int dx = r - originRow;
                        int dy = c - originCol;
                        res[center + dx][center + dy] = '.';
                    }
                }
            }
        }

        /**
         * Validates if the expanded grid satisfies the condition for all 'x' 
         * characters in the original input grid.
         */
        private boolean validateExpandedGrid() {
            for (int r = 0; r < gridSize; r++) {
                for (int c = 0; c < gridSize; c++) {
                    if (inputGrid[r][c] == 'x') {
                        if (!isXConditionMet(r, c)) {
                            return false;
                        }
                    }
                }
            }
            return true;
        }

        private boolean isXConditionMet(int targetRow, int targetCol) {
            int center = gridSize - 1;
            for (int r = 0; r < gridSize; r++) {
                for (int c = 0; c < gridSize; c++) {
                    if (inputGrid[r][c] == 'o') {
                        int expandedRow = center + (targetRow - r);
                        int expandedCol = center + (targetCol - c);

                        // Check if the relative position in the expanded grid is still 'x'
                        if (expandedGrid[expandedRow][expandedCol] == 'x') {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        private void printGrid(PrintWriter out, char[][] grid) {
            for (char[] row : grid) {
                out.println(new String(row));
            }
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        public double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Scanner;

/**
 * A solver for the grid coverage problem.
 * The goal is to place 'x' markers in a transformed grid such that all 'x' 
 * positions in the original grid are covered by shifted 'o' positions, 
 * without any 'o' landing on an empty '.' cell.
 */
public class GridCoverageSolver {

    /**
     * Represents a coordinate in the 2D grid.
     */
    private record Point(int row, int col) {}

    public void solve() {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int gridSize = scanner.nextInt();
        char[][] originalGrid = new char[gridSize][gridSize];
        List<Point> xPositions = new ArrayList<>();
        List<Point> oPositions = new ArrayList<>();

        // 1. Parse input and identify key positions
        for (int i = 0; i < gridSize; i++) {
            String line = scanner.next();
            originalGrid[i] = line.toCharArray();
            for (int j = 0; j < gridSize; j++) {
                if (originalGrid[i][j] == 'o') {
                    oPositions.add(new Point(i, j));
                } else if (originalGrid[i][j] == 'x') {
                    xPositions.add(new Point(i, j));
                }
            }
        }

        // 2. Prepare the result grid (size 2n-1)
        int expandedSize = 2 * gridSize - 1;
        char[][] resultGrid = new char[expandedSize][expandedSize];
        boolean[][] isCellCovered = new boolean[gridSize][gridSize];

        // Initialize result grid with empty cells
        for (int i = 0; i < expandedSize; i++) {
            Arrays.fill(resultGrid[i], '.');
        }

        // The center of the expanded grid is always designated as 'o'
        int centerIndex = gridSize - 1;
        resultGrid[centerIndex][centerIndex] = 'o';

        // 3. Iterate through all possible offsets in the expanded grid
        for (int i = 0; i < expandedSize; i++) {
            for (int j = 0; j < expandedSize; j++) {
                // Skip the center point as it's already assigned
                if (i == centerIndex && j == centerIndex) {
                    continue;
                }

                int rowOffset = i - centerIndex;
                int colOffset = j - centerIndex;

                if (isValidPlacement(rowOffset, colOffset, gridSize, originalGrid, oPositions)) {
                    resultGrid[i][j] = 'x';
                    markCoverage(rowOffset, colOffset, gridSize, oPositions, isCellCovered);
                }
            }
        }

        // 4. Validate and Output result
        if (allXPositionsAreCovered(xPositions, isCellCovered)) {
            System.out.println("YES");
            printGrid(resultGrid);
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Checks if placing an 'x' at the current offset is valid.
     * A placement is valid if no 'o' from the original grid lands on a '.' cell.
     */
    private boolean isValidPlacement(int rowOffset, int colOffset, int n, 
                                     char[][] grid, List<Point> oPositions) {
        for (Point o : oPositions) {
            int targetRow = o.row() + rowOffset;
            int targetCol = o.col() + colOffset;

            if (isWithinBounds(targetRow, targetCol, n) && grid[targetRow][targetCol] == '.') {
                return false;
            }
        }
        return true;
    }

    /**
     * Marks the cells in the original grid that are covered by the shifted 'o' positions.
     */
    private void markCoverage(int rowOffset, int colOffset, int n, 
                              List<Point> oPositions, boolean[][] isCellCovered) {
        for (Point o : oPositions) {
            int targetRow = o.row() + rowOffset;
            int targetCol = o.col() + colOffset;

            if (isWithinBounds(targetRow, targetCol, n)) {
                isCellCovered[targetRow][targetCol] = true;
            }
        }
    }

    private boolean isWithinBounds(int r, int c, int n) {
        return r >= 0 && r < n && c >= 0 && c < n;
    }

    private boolean allXPositionsAreCovered(List<Point> xPositions, boolean[][] isCellCovered) {
        for (Point x : xPositions) {
            if (!isCellCovered[x.row()][x.col()]) {
                return false;
            }
        }
        return true;
    }

    private void printGrid(char[][] grid) {
        StringBuilder sb = new StringBuilder();
        for (char[] row : grid) {
            sb.append(new String(row)).append("\n");
        }
        System.out.print(sb.toString());
    }

    public static void main(String[] args) {
        new GridCoverageSolver().solve();
    }
}

import java.io.*;
import java.util.*;

/**
 * A program that identifies valid pattern shifts in a grid and attempts
 * to reconstruct the grid using those shifts.
 * 
 * The logic:
 * 1. Find all offsets (dx, dy) such that shifting all 'o' characters by (dx, dy)
 *    results in the 'o's landing only on 'o's or going out of bounds.
 * 2. Use these valid offsets to expand 'o' characters into 'x' characters.
 * 3. If the reconstructed grid matches the original grid, the pattern is valid.
 */
public class GridPatternMatcher {

    private static final char CHAR_CIRCLE = 'o';
    private static final char CHAR_CROSS = 'x';
    private static final char CHAR_EMPTY = '.';

    private FastScanner scanner;
    private PrintWriter writer;

    public static void main(String[] args) {
        new GridPatternMatcher().run();
    }

    /**
     * Initializes resources and executes the solve logic.
     */
    public void run() {
        scanner = new FastScanner(System.in);
        writer = new PrintWriter(System.out);
        try {
            solve();
        } finally {
            writer.close();
        }
    }

    private void solve() {
        int gridSize = scanner.nextInt();
        char[][] originalGrid = readGrid(gridSize);

        char[][] offsetGrid = computeOffsetGrid(originalGrid, gridSize);
        char[][] reconstructedGrid = reconstructGrid(originalGrid, offsetGrid, gridSize);

        if (isReconstructionSuccessful(originalGrid, reconstructedGrid)) {
            writer.println("YES");
            printGrid(offsetGrid);
        } else {
            writer.println("NO");
        }
    }

    /**
     * Reads the grid from the input scanner.
     */
    private char[][] readGrid(int n) {
        char[][] grid = new char[n][n];
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }
        return grid;
    }

    /**
     * Computes a grid of offsets where each cell (dx, dy) indicates if a shift
     * is valid according to the 'o' preservation rule.
     */
    private char[][] computeOffsetGrid(char[][] grid, int n) {
        int offsetDim = 2 * n - 1;
        char[][] offsetGrid = new char[offsetDim][offsetDim];

        // Initialize offset grid with empty markers
        for (char[] row : offsetGrid) {
            Arrays.fill(row, CHAR_EMPTY);
        }

        for (int dx = -n + 1; dx <= n - 1; dx++) {
            for (int dy = -n + 1; dy <= n - 1; dy++) {
                int centerIdx = n - 1;

                // Special case for origin
                if (dx == 0 && dy == 0) {
                    offsetGrid[centerIdx + dx][centerIdx + dy] = CHAR_CIRCLE;
                    continue;
                }

                if (isValidShift(grid, dx, dy, n)) {
                    offsetGrid[centerIdx + dx][centerIdx + dy] = CHAR_CROSS;
                }
            }
        }
        return offsetGrid;
    }

    /**
     * Checks if a translation (dx, dy) is valid.
     * A shift is valid if for every 'o' in the grid, the target position 
     * is either out of bounds or contains another 'o'.
     */
    private boolean isValidShift(char[][] grid, int dx, int dy, int n) {
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == CHAR_CIRCLE) {
                    int targetR = r + dx;
                    int targetC = c + dy;

                    if (isWithinBounds(targetR, targetC, n)) {
                        if (grid[targetR][targetC] == CHAR_EMPTY) {
                            return false;
                        }
                    }
                }
            }
        }
        return true;
    }

    /**
     * Reconstructs the grid by applying all valid 'x' offsets to existing 'o' positions.
     */
    private char[][] reconstructGrid(char[][] originalGrid, char[][] offsetGrid, int n) {
        char[][] reconstructed = new char[n][n];
        for (char[] row : reconstructed) {
            Arrays.fill(row, CHAR_EMPTY);
        }

        // Start by placing 'o's
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (originalGrid[r][c] == CHAR_CIRCLE) {
                    reconstructed[r][c] = CHAR_CIRCLE;
                }
            }
        }

        // Expand 'o's into 'x's using valid offsets
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (originalGrid[r][c] == CHAR_CIRCLE) {
                    applyOffsets(reconstructed, offsetGrid, r, c, n);
                }
            }
        }
        return reconstructed;
    }

    private void applyOffsets(char[][] reconstructed, char[][] offsetGrid, int r, int c, int n) {
        int offsetDim = 2 * n - 1;
        int centerIdx = n - 1;

        for (int dx = -n + 1; dx <= n - 1; dx++) {
            for (int dy = -n + 1; dy <= n - 1; dy++) {
                if (offsetGrid[centerIdx + dx][centerIdx + dy] != CHAR_CROSS) {
                    continue;
                }

                int targetR = r + dx;
                int targetC = c + dy;

                if (isWithinBounds(targetR, targetC, n)) {
                    if (reconstructed[targetR][targetC] == CHAR_EMPTY) {
                        reconstructed[targetR][targetC] = CHAR_CROSS;
                    }
                }
            }
        }
    }

    private boolean isWithinBounds(int r, int c, int n) {
        return r >= 0 && r < n && c >= 0 && c < n;
    }

    private boolean isReconstructionSuccessful(char[][] original, char[][] reconstructed) {
        return Arrays.deepEquals(original, reconstructed);
    }

    private void printGrid(char[][] grid) {
        for (char[] row : grid) {
            writer.println(new String(row));
        }
    }

    /**
     * Fast I/O Utility.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

