import java.util.*;

/**
 * A solver for the grid transformation problem.
 * The goal is to construct an expanded grid based on the relative positions
 * of 'o' and '.' characters in the original grid.
 */
public class Main {

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;

            int n = scanner.nextInt();
            char[][] inputGrid = new char[n][n];
            for (int i = 0; i < n; i++) {
                String line = scanner.next();
                inputGrid[i] = line.toCharArray();
            }

            GridSolver solver = new GridSolver(n, inputGrid);
            solver.solve();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}

class GridSolver {
    private static final char CELL_O = 'o';
    private static final char CELL_X = 'x';
    private static final char CELL_DOT = '.';

    private final int n;
    private final char[][] inputGrid;
    private final int expandedSize;
    private final int centerOffset;

    public GridSolver(int n, char[][] inputGrid) {
        this.n = n;
        this.inputGrid = inputGrid;
        this.expandedSize = 2 * n - 1;
        this.centerOffset = n - 1;
    }

    /**
     * Executes the solver logic and prints the result.
     */
    public void solve() {
        int targetPointCount = countTargetPoints();
        char[][] expandedGrid = buildExpandedGrid(targetPointCount);

        if (hasInconsistencies(targetPointCount, expandedGrid)) {
            System.out.println("NO");
        } else {
            printResult(expandedGrid);
        }
    }

    /**
     * Counts the number of 'o' cells in the input grid.
     */
    private int countTargetPoints() {
        int count = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (inputGrid[i][j] == CELL_O) {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Builds the expanded grid based on the relative displacement 
     * between 'o' cells and '.' cells.
     */
    private char[][] buildExpandedGrid(int targetPointCount) {
        char[][] expandedGrid = new char[expandedSize][expandedSize];
        for (int i = 0; i < expandedSize; i++) {
            Arrays.fill(expandedGrid[i], CELL_X);
        }

        for (int rO = 0; rO < n; rO++) {
            for (int cO = 0; cO < n; cO++) {
                if (inputGrid[rO][cO] == CELL_O) {
                    markRelativeDots(rO, cO, expandedGrid);
                }
            }
        }
        return expandedGrid;
    }

    private void markRelativeDots(int rO, int cO, char[][] expandedGrid) {
        for (int rDot = 0; rDot < n; rDot++) {
            for (int cDot = 0; cDot < n; cDot++) {
                if (inputGrid[rDot][cDot] == CELL_DOT) {
                    int rowOffset = rDot - rO;
                    int colOffset = cDot - cO;
                    expandedGrid[centerOffset + rowOffset][centerOffset + colOffset] = CELL_DOT;
                }
            }
        }
    }

    /**
     * Checks if the expanded grid contradicts the original input grid.
     */
    private boolean hasInconsistencies(int targetPointCount, char[][] expandedGrid) {
        int[][] inconsistencyTracker = new int[n][n];

        for (int rO = 0; rO < n; rO++) {
            for (int cO = 0; cO < n; cO++) {
                if (inputGrid[rO][cO] == CELL_O) {
                    updateInconsistencyTracker(rO, cO, expandedGrid, inconsistencyTracker);
                }
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (inconsistencyTracker[i][j] == targetPointCount) {
                    return true;
                }
            }
        }
        return false;
    }

    private void updateInconsistencyTracker(int rO, int cO, char[][] expandedGrid, int[][] tracker) {
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                int rowOffset = r - rO;
                int colOffset = c - cO;
                char expandedCell = expandedGrid[centerOffset + rowOffset][centerOffset + colOffset];

                // If original cell and expanded cell have conflicting expected values
                boolean isConflict = (inputGrid[r][c] == CELL_X && expandedCell == CELL_DOT) ||
                                     (inputGrid[r][c] == CELL_DOT && expandedCell == CELL_X);

                if (isConflict) {
                    tracker[r][c]++;
                }
            }
        }
    }

    /**
     * Formats and prints the final expanded grid.
     */
    private void printResult(char[][] expandedGrid) {
        StringBuilder sb = new StringBuilder();
        sb.append("YES\n");

        // Set the center of the expanded grid to 'o' as per original logic
        expandedGrid[centerOffset][centerOffset] = CELL_O;

        for (int i = 0; i < expandedSize; i++) {
            for (int j = 0; j < expandedSize; j++) {
                sb.append(expandedGrid[i][j]);
            }
            sb.append("\n");
        }
        System.out.print(sb.toString());
    }
}

import java.io.*;
import java.util.*;

/**
 * Represents a 2D coordinate on the grid.
 */
record Point(int r, int c) {}

/**
 * Handles fast input reading.
 */
class FastReader {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    public FastReader(InputStream input) {
        reader = new BufferedReader(new InputStreamReader(input));
    }

    public String next() {
        while (tokenizer == null || !tokenizer.hasMoreElements()) {
            try {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                return null;
            }
        }
        return tokenizer.nextToken();
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }
}

/**
 * Encapsulates the board and its properties.
 */
class Grid {
    private final int size;
    private final char[][] cells;
    private final List<Point> oCells = new ArrayList<>();
    private final List<Point> xCells = new ArrayList<>();
    private final List<Point> dotCells = new ArrayList<>();

    public Grid(int size, FastReader reader) {
        this.size = size;
        this.cells = new char[size][size];
        for (int i = 0; i < size; i++) {
            String row = reader.next();
            for (int j = 0; j < size; j++) {
                cells[i][j] = row.charAt(j);
                if (cells[i][j] == 'o') oCells.add(new Point(i, j));
                else if (cells[i][j] == 'x') xCells.add(new Point(i, j));
                else if (cells[i][j] == '.') dotCells.add(new Point(i, j));
            }
        }
    }

    public int getSize() { return size; }
    public List<Point> getOCells() { return oCells; }
    public List<Point> getXCells() { return xCells; }
    public List<Point> getDotCells() { return dotCells; }
    public boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < size && c >= 0 && c < size;
    }
}

/**
 * Logic engine to solve the grid task.
 */
class TaskSolver {
    private final Grid grid;
    private final int offsetConstant;
    private final boolean[][] isForbiddenOffset;

    public TaskSolver(Grid grid) {
        this.grid = grid;
        this.offsetConstant = grid.getSize();
        // Dimension is (2n-1)x(2n-1), so offsets range from -(n-1) to (n-1)
        this.isForbiddenOffset = new boolean[2 * grid.getSize() + 1][2 * grid.getSize() + 1];
        calculateForbiddenOffsets();
    }

    /**
     * An offset is forbidden if applying it to an 'o' cell lands on a '.' cell.
     */
    private void calculateForbiddenOffsets() {
        for (Point o : grid.getOCells()) {
            for (Point dot : grid.getDotCells()) {
                int dy = dot.r() - o.r();
                int dx = dot.c() - o.c();
                isForbiddenOffset[dy + offsetConstant][dx + offsetConstant] = true;
            }
        }
    }

    private boolean isOffsetValid(int dy, int dx) {
        return !isForbiddenOffset[dy + offsetConstant][dx + offsetConstant];
    }

    public void solve() throws IOException {
        if (!checkCoverage()) {
            System.out.println("NO");
            return;
        }

        System.out.println("YES");
        printExpandedGrid();
    }

    /**
     * Checks if every 'x' cell in the original grid can be covered by an 'o' cell 
     * using a valid offset.
     */
    private boolean checkCoverage() {
        for (Point x : grid.getXCells()) {
            boolean covered = false;
            for (Point o : grid.getOCells()) {
                int dy = x.r() - o.r();
                int dx = x.c() - o.c();
                if (isOffsetValid(dy, dx)) {
                    covered = true;
                    break;
                }
            }
            if (!covered) return false;
        }
        return true;
    }

    /**
     * Prints the (2n-1)x(2n-1) grid.
     */
    private void printExpandedGrid() {
        int n = grid.getSize();
        int N = 2 * n - 1;
        int centerR = n - 1;
        int centerC = n - 1;

        PrintWriter out = new PrintWriter(System.out);
        for (int i = 0; i < N; i++) {
            StringBuilder row = new StringBuilder();
            for (int j = 0; j < N; j++) {
                if (i == centerR && j == centerC) {
                    row.append('o');
                } else {
                    int dy = i - centerR;
                    int dx = j - centerC;
                    if (isOffsetValid(dy, dx)) {
                        row.append('x');
                    } else {
                        row.append('.');
                    }
                }
            }
            out.println(row.toString());
        }
        out.flush();
    }
}

public class Task {
    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        try {
            String nStr = reader.next();
            if (nStr == null) return;

            int n = Integer.parseInt(nStr);
            Grid grid = new Grid(n, reader);
            TaskSolver solver = new TaskSolver(grid);
            solver.solve();
        } catch (Exception e) {
            // In a real production environment, use a logger
            e.printStackTrace();
        }
    }
}

