        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}

/**
 * Handles the core logic of calculating the pattern and validating 
 * whether the pattern satisfies the grid requirements.
 */
class PatternSolver {
    private static final char CELL_O = 'o';
    private static final char CELL_X = 'x';
    private static final char CELL_EMPTY = '.';
    private static final char PATTERN_TRUE = 'x';
    private static final char PATTERN_FALSE = '.';
    private static final char PATTERN_CENTER = 'o';

    private final int gridSize;
    private final char[][] grid;
    private final int patternSize;
    private final int patternCenter;

    public PatternSolver(int gridSize, char[][] grid) {
        this.gridSize = gridSize;
        this.grid = grid;
        this.patternSize = 2 * gridSize - 1;
        this.patternCenter = gridSize - 1;
    }

    /**
     * Executes the solver logic: calculates a candidate pattern,
     * verifies it, and writes the result to the output.
     */
    public void solve(PrintWriter out) {
        boolean[][] candidatePattern = calculateCandidatePattern();

        if (isPatternValid(candidatePattern)) {
            out.println("YES");
            printPattern(candidatePattern, out);
        } else {
            out.println("NO");
        }
    }

    /**
     * Determines the candidate pattern by eliminating offsets 
     * that would cause a pattern-cell to overlap with a '.' cell 
     * when aligned with an 'o' cell.
     * 
     * Complexity: O(N^4)
     */
    private boolean[][] calculateCandidatePattern() {
        boolean[][] pattern = new boolean[patternSize][patternSize];
        for (boolean[] row : pattern) {
            Arrays.fill(row, true);
        }

        // The center of the pattern itself is always false by definition/problem constraint
        pattern[patternCenter][patternCenter] = false;

        for (int rO = 0; rO < gridSize; rO++) {
            for (int cO = 0; cO < gridSize; cO++) {
                if (grid[rO][cO] == CELL_O) {
                    invalidateOffsetsForEmptyCells(rO, cO, pattern);
                }
            }
        }
        return pattern;
    }

    private void invalidateOffsetsForEmptyCells(int rO, int cO, boolean[][] pattern) {
        for (int rE = 0; rE < gridSize; rE++) {
            for (int cE = 0; cE < gridSize; cE++) {
                if (grid[rE][cE] == CELL_EMPTY) {
                    int patternRow = patternCenter + (rE - rO);
                    int patternCol = patternCenter + (cE - cO);

                    // Bounds check is implicitly handled by the problem constraints 
                    // but pattern indexing must stay within patternSize
                    if (patternRow >= 0 && patternRow < patternSize && 
                        patternCol >= 0 && patternCol < patternSize) {
                        pattern[patternRow][patternCol] = false;
                    }
                }
            }
        }
    }

    /**
     * Checks if all 'x' cells in the grid are "covered" by the pattern
     * when the pattern is applied to every 'o' cell.
     */
    private boolean isPatternValid(boolean[][] pattern) {
        boolean[][] isCellCovered = new boolean[gridSize][gridSize];

        // Apply pattern to every 'o' cell
        for (int rO = 0; rO < gridSize; rO++) {
            for (int cO = 0; cO < gridSize; cO++) {
                if (grid[rO][cO] == CELL_O) {
                    markCoveredCells(rO, cO, pattern, isCellCovered);
                }
            }
        }

        // Verify all 'x' cells are covered
        for (int r = 0; r < gridSize; r++) {
            for (int c = 0; c < gridSize; c++) {
                if (grid[r][c] == CELL_X && !isCellCovered[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    private void markCoveredCells(int rO, int cO, boolean[][] pattern, boolean[][] isCellCovered) {
        for (int rG = 0; rG < gridSize; rG++) {
            for (int cG = 0; cG < gridSize; cG++) {
                int pRow = patternCenter + (rG - rO);
                int pCol = patternCenter + (cG - cO);

                if (pRow >= 0 && pRow < patternSize && pCol >= 0 && pCol < patternSize) {
                    if (pattern[pRow][pCol]) {
                        isCellCovered[rG][cG] = true;
                    }
                }
            }
        }
    }

    private void printPattern(boolean[][] pattern, PrintWriter out) {
        for (int i = 0; i < patternSize; i++) {
            for (int j = 0; j < patternSize; j++) {
                if (i == patternCenter && j == patternCenter) {
                    out.print(PATTERN_CENTER);
                } else {
                    out.print(pattern[i][j] ? PATTERN_TRUE : PATTERN_FALSE);
                }
            }
            out.println();
        }
    }
}

