import java.util.Arrays;
import java.util.Scanner;
import java.io.PrintWriter;

/**
 * A refactored solution for a pattern-matching problem on a 2D grid.
 * The program identifies a "safe" relative pattern of offsets that can cover 
 * all target 'x' cells without landing on any empty '.' cells when applied 
 * to the source 'o' cells.
 */
public class Main {

    public static void main(String[] args) {
        // Use try-with-resources to ensure scanner and writer are closed properly
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter writer = new PrintWriter(System.out)) {

            if (!scanner.hasNextInt()) {
                return;
            }

            int n = scanner.nextInt();
            char[][] grid = new char[n][n];
            for (int i = 0; i < n; i++) {
                grid[i] = scanner.next().toCharArray();
            }

            PatternSolver solver = new PatternSolver(n, grid);
            solver.solve(writer);
        }
    }
}

/**
 * Handles the logic for calculating valid pattern offsets and verifying coverage.
 */
class PatternSolver {
    // Constants for grid character types
    private static final char SOURCE = 'o';
    private static final char TARGET = 'x';
    private static final char EMPTY = '.';

    private final int gridSize;
    private final char[][] grid;

    public PatternSolver(int gridSize, char[][] grid) {
        this.gridSize = gridSize;
        this.grid = grid;
    }

    /**
     * Executes the solver logic and writes the result to the provided PrintWriter.
     */
    public void solve(PrintWriter out) {
        boolean[][] isValidOffset = calculateValidOffsets();

        if (isEveryTargetCovered(isValidOffset)) {
            out.println("YES");
            printPattern(out, isValidOffset);
        } else {
            out.println("NO");
        }
    }

    /**
     * Calculates which relative offsets (dr, dc) are valid.
     * An offset is invalid if it would map any 'o' in the input grid to a '.' cell.
     * 
     * @return A 2D boolean array representing valid offsets in a (2n-1)x(2n-1) space.
     */
    private boolean[][] calculateValidOffsets() {
        int dimension = 2 * gridSize - 1;
        boolean[][] isValid = new boolean[dimension][dimension];

        // Initialize all offsets as valid
        for (boolean[] row : isValid) {
            Arrays.fill(row, true);
        }

        for (int r = 0; r < gridSize; r++) {
            for (int c = 0; c < gridSize; c++) {
                if (grid[r][c] == SOURCE) {
                    markForbiddenOffsets(r, c, isValid);
                }
            }
        }
        return isValid;
    }

    /**
     * Marks offsets as invalid if they cause a SOURCE to land on an EMPTY cell.
     */
    private void markForbiddenOffsets(int sourceR, int sourceC, boolean[][] isValid) {
        for (int r = 0; r < gridSize; r++) {
            for (int c = 0; c < gridSize; c++) {
                if (grid[r][c] == EMPTY) {
                    // The offset required to get from (sourceR, sourceC) to (r, c)
                    // We map this to the [0, 2n-2] coordinate system.
                    int dr = r - sourceR + gridSize - 1;
                    int dc = c - sourceC + gridSize - 1;
                    isValid[dr][dc] = false;
                }
            }
        }
    }

    /**
     * Verifies if all 'x' cells in the input grid are covered by applying
     * the valid pattern offsets to the existing 'o' cells.
     */
    private boolean isEveryTargetCovered(boolean[][] isValidOffset) {
        boolean[][] isCovered = new boolean[gridSize][gridSize];

        for (int r = 0; r < gridSize; r++) {
            for (int c = 0; c < gridSize; c++) {
                if (grid[r][c] == SOURCE) {
                    markCellsCoveredBySource(r, c, isValidOffset, isCovered);
                }
            }
        }

        // Check if every target 'x' cell has been marked as covered
        for (int r = 0; r < gridSize; r++) {
            for (int c = 0; c < gridSize; c++) {
                if (grid[r][c] == TARGET && !isCovered[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    private void markCellsCoveredBySource(int r, int c, boolean[][] isValidOffset, boolean[][] isCovered) {
        for (int targetR = 0; targetR < gridSize; targetR++) {
            for (int targetC = 0; targetC < gridSize; targetC++) {
                int dr = targetR - r + gridSize - 1;
                int dc = targetC - c + gridSize - 1;
                if (isValidOffset[dr][dc]) {
                    isCovered[targetR][targetC] = true;
                }
            }
        }
    }

    /**
     * Constructs and prints the (2n-1)x(2n-1) pattern grid.
     */
    private void printPattern(PrintWriter out, boolean[][] isValidOffset) {
        int dimension = 2 * gridSize - 1;
        StringBuilder sb = new StringBuilder();

        for (int i = 0; i < dimension; i++) {
            for (int j = 0; j < dimension; j++) {
                if (i == gridSize - 1 && j == gridSize - 1) {
                    sb.append(SOURCE);
                } else if (isValidOffset[i][j]) {
                    sb.append(TARGET);
                } else {
                    sb.append(EMPTY);
                }
            }
            sb.append('\n');
        }
        out.print(sb.toString());
    }
}

import java.io.*;
import java.util.*;

/**
 * GridCoverageSolver determines if all target cells ('x') in a grid are "covered"
 * by at least one source cell ('o') using non-forbidden vectors.
 * 
 * A vector is forbidden if it represents the displacement from any source ('o')
 * to any endpoint ('.').
 */
public class GridCoverageSolver {

    // Constants representing the possible cell types in the input grid
    private static final char TARGET_CHAR = 'x';
    private static final char SOURCE_CHAR = 'o';
    private static final char ENDPOINT_CHAR = '.';

    /**
     * Represents a 2D coordinate in the grid.
     */
    private static class Point {
        final int row, col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * A fast I/O utility for reading large inputs efficiently.
     */
    private static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String next = next();
            return (next == null) ? -1 : Integer.parseInt(next);
        }
    }

    /**
     * Orchestrates the solving process.
     */
    public void run() {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            int n = reader.nextInt();
            if (n <= 0) {
                out.close();
                return;
            }

            char[][] grid = new char[n][n];
            List<Point> sources = new ArrayList<>();
            List<Point> endpoints = new ArrayList<>();

            // Step 1: Parse the input grid and identify special cells
            for (int i = 0; i < n; i++) {
                String line = reader.next();
                for (int j = 0; j < n; j++) {
                    grid[i][j] = line.charAt(j);
                    if (grid[i][j] == SOURCE_CHAR) {
                        sources.add(new Point(i, j));
                    } else if (grid[i][j] == ENDPOINT_CHAR) {
                        endpoints.add(new Point(i, j));
                    }
                }
            }

            // Step 2: Calculate forbidden offsets.
            // An offset (dr, dc) is forbidden if there is any source and any endpoint
            // such that end.row - src.row == dr and end.col - src.col == dc.
            // We use a 2D array to store offsets in the range [-(n-1), n-1].
            boolean[][] forbiddenOffsets = new boolean[2 * n - 1][2 * n - 1];
            for (Point src : sources) {
                for (Point end : endpoints) {
                    int dr = end.row - src.row;
                    int dc = end.col - src.col;
                    // Map offset range [-(n-1), n-1] to [0, 2n-2]
                    forbiddenOffsets[dr + n - 1][dc + n - 1] = true;
                }
            }

            // Step 3: Determine coverage for every cell in the n x n grid.
            // A cell is "covered" if there exists at least one source where the 
            // displacement vector to that cell is NOT forbidden.
            boolean[][] isCovered = new boolean[n][n];
            for (Point src : sources) {
                // Iterate over all relative offsets that keep the target cell within bounds
                for (int dr = -src.row; dr < n - src.row; dr++) {
                    for (int dc = -src.col; dc < n - src.col; dc++) {
                        if (!forbiddenOffsets[dr + n - 1][dc + n - 1]) {
                            isCovered[src.row + dr][src.col + dc] = true;
                        }
                    }
                }
            }

            // Step 4: Validate if all target cells ('x') are covered
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (grid[i][j] == TARGET_CHAR && !isCovered[i][j]) {
                        out.println("NO");
                        out.flush();
                        return;
                    }
                }
            }

            // Step 5: Output the result grid if all targets are covered
            out.println("YES");
            for (int i = 0; i < 2 * n - 1; i++) {
                for (int j = 0; j < 2 * n - 1; j++) {
                    if (i == n - 1 && j == n - 1) {
                        out.print(SOURCE_CHAR);
                    } else {
                        out.print(forbiddenOffsets[i][j] ? ENDPOINT_CHAR : TARGET_CHAR);
                    }
                }
                out.println();
            }

        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    public static void main(String[] args) {
        new GridCoverageSolver().run();
    }
}

import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.Closeable;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.StringTokenizer;

/**
 * A utility to determine if a relative translation pattern can reconstruct 
 * a given board configuration of 'o' and '.' characters.
 */
public class BoardPatternMatcher {

    public static void main(String[] args) {
        try (FastReader reader = new FastReader(System.in);
             PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)))) {

            BoardPatternMatcher matcher = new BoardPatternMatcher();
            matcher.solve(reader, writer);
        } catch (IOException e) {
            // In a production environment, use a logging framework instead of printStackTrace.
            e.printStackTrace();
        }
    }

    /**
     * Orchestrates the reading, processing, and output of the pattern matching problem.
     * 
     * @param reader The fast input reader.
     * @param writer The fast output writer.
     * @throws IOException If an I/O error occurs.
     */
    public void solve(FastReader reader, PrintWriter writer) throws IOException {
        int gridSize = reader.nextInt();
        if (gridSize <= 0) {
            return;
        }

        char[][] board = new char[gridSize][gridSize];
        for (int i = 0; i < gridSize; i++) {
            board[i] = reader.next().toCharArray();
        }

        char[][] pattern = computePattern(board, gridSize);

        if (isPatternValid(board, pattern, gridSize)) {
            writer.println("YES");
            for (char[] row : pattern) {
                writer.println(new String(row));
            }
        } else {
            writer.println("NO");
        }
    }

    /**
     * Constructs the pattern grid based on the relative displacements 
     * from 'o' cells to '.' cells.
     */
    private char[][] computePattern(char[][] board, int gridSize) {
        int patternSize = 2 * gridSize - 1;
        char[][] pattern = new char[patternSize][patternSize];

        for (char[] row : pattern) {
            Arrays.fill(row, 'x');
        }

        int centerOffset = gridSize - 1;
        pattern[centerOffset][centerOffset] = 'o';

        for (int i = 0; i < gridSize; i++) {
            for (int j = 0; j < gridSize; j++) {
                if (board[i][j] == 'o') {
                    for (int r = 0; r < gridSize; r++) {
                        for (int c = 0; c < gridSize; c++) {
                            if (board[r][c] == '.') {
                                int patternRow = centerOffset + r - i;
                                int patternCol = centerOffset + c - j;
                                pattern[patternRow][patternCol] = '.';
                            }
                        }
                    }
                }
            }
        }
        return pattern;
    }

    /**
     * Verifies if the provided pattern correctly reconstructs the original board.
     */
    private boolean isPatternValid(char[][] board, char[][] pattern, int gridSize) {
        char[][] validationGrid = new char[gridSize][gridSize];
        for (char[] row : validationGrid) {
            Arrays.fill(row, '.');
        }

        int centerOffset = gridSize - 1;

        for (int i = 0; i < gridSize; i++) {
            for (int j = 0; j < gridSize; j++) {
                if (board[i][j] == 'o') {
                    validationGrid[i][j] = 'o';
                    for (int r = 0; r < gridSize; r++) {
                        for (int c = 0; c < gridSize; c++) {
                            // If a cell is currently '.' and the pattern indicates 
                            // an invalid translation ('x'), mark it as 'x'.
                            if (validationGrid[r][c] == '.' && 
                                pattern[centerOffset + r - i][centerOffset + c - j] == 'x') {
                                validationGrid[r][c] = 'x';
                            }
                        }
                    }
                }
            }
        }

        for (int i = 0; i < gridSize; i++) {
            if (!Arrays.equals(board[i], validationGrid[i])) {
                return false;
            }
        }
        return true;
    }

    /**
     * Efficient reader for parsing input tokens.
     */
    static class FastReader implements Closeable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            this.reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) {
                    return null;
                }
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            String next = next();
            return (next == null) ? 0 : Integer.parseInt(next);
        }

        @Override
        public void close() throws IOException {
            reader.close();
        }
    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Scanner;

/**
 * Refactored version of Prob04.
 * This program analyzes the relative geometric offsets between 'origin' (o) and 'empty' (.) cells
 * to determine if all 'obstacle' (x) cells are covered by the pattern.
 */
public class Prob04 {

    // Constants for cell types to avoid magic characters
    private static final char TYPE_ORIGIN = 'o';
    private static final char TYPE_EMPTY = '.';
    private static final char TYPE_OBSTACLE = 'x';
    private static final char TYPE_PLACEHOLDER = 'o';

    /**
     * Represents a 2D coordinate on the grid.
     */
    private static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextLine()) {
            return;
        }

        int gridSize = Integer.parseInt(scanner.nextLine().trim());
        char[][] board = new char[gridSize][gridSize];

        List<Point> originPoints = new ArrayList<>();
        List<Point> emptyPoints = new ArrayList<>();
        List<Point> obstaclePoints = new ArrayList<>();

        // Parse input and categorize cell coordinates
        for (int i = 0; i < gridSize; i++) {
            String line = scanner.nextLine();
            for (int j = 0; j < gridSize; j++) {
                char cell = line.charAt(j);
                board[i][j] = cell;

                Point current = new Point(i, j);
                if (cell == TYPE_ORIGIN) {
                    originPoints.add(current);
                } else if (cell == TYPE_EMPTY) {
                    emptyPoints.add(current);
                } else if (cell == TYPE_OBSTACLE) {
                    obstaclePoints.add(current);
                }
            }
        }

        // 1. Compute the Relative Map
        // The relative map size is (2n-1)x(2n-1) to accommodate all possible relative offsets.
        int mapSize = 2 * gridSize - 1;
        char[][] relativeMap = computeRelativeMap(gridSize, originPoints, emptyPoints);

        // 2. Validate Obstacles
        // An obstacle is "valid" if there is at least one origin point such that 
        // the offset to the obstacle does not match an origin-to-empty offset.
        boolean allObstaclesValid = validateObstacles(obstaclePoints, originPoints, relativeMap, gridSize);

        // 3. Output Result
        if (allObstaclesValid) {
            System.out.println("YES");
            printGrid(relativeMap);
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Generates a map of relative offsets between all origins and all empty cells.
     */
    private static char[][] computeRelativeMap(int n, List<Point> origins, List<Point> empties) {
        int mapSize = 2 * n - 1;
        char[][] map = new char[mapSize][mapSize];

        for (int i = 0; i < mapSize; i++) {
            Arrays.fill(map[i], TYPE_OBSTACLE);
        }

        // The center of the relative map corresponds to offset (0,0)
        map[n - 1][n - 1] = TYPE_PLACEHOLDER;

        for (Point o : origins) {
            for (Point e : empties) {
                int offsetRow = (n - 1) + (e.row - o.row);
                int offsetCol = (n - 1) + (e.col - o.col);
                map[offsetRow][offsetCol] = TYPE_EMPTY;
            }
        }
        return map;
    }

    /**
     * Checks if every obstacle in the original grid is "covered" by the pattern.
     */
    private static boolean validateObstacles(List<Point> obstacles, List<Point> origins, char[][] relativeMap, int n) {
        for (Point obs : obstacles) {
            boolean isObstacleCovered = false;

            for (Point o : origins) {
                int offsetRow = (n - 1) + (obs.row - o.row);
                int offsetCol = (n - 1) + (obs.col - o.col);

                // If the offset points to a cell in the relative map that is still an obstacle,
                // it means this specific origin-to-obstacle offset is not an origin-to-empty offset.
                if (relativeMap[offsetRow][offsetCol] == TYPE_OBSTACLE) {
                    isObstacleCovered = true;
                    break;
                }
            }

            if (!isObstacleCovered) {
                return false;
            }
        }
        return true;
    }

    /**
     * Helper to print the character grid.
     */
    private static void printGrid(char[][] grid) {
        for (char[] row : grid) {
            System.out.println(new String(row));
        }
    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.StringTokenizer;

/**
 * Solution to find a valid path in a grid from a starting point to a destination.
 * A path is valid if it only traverses '.' cells or an 'X' cell if it is the destination,
 * and the destination must satisfy a specific neighbor score condition.
 */
public class Solution {

    private static final int[][] DIRECTIONS = {
        {1, 0},  // Down
        {-1, 0}, // Up
        {0, 1},  // Right
        {0, -1}  // Left
    };

    /**
     * Represents a coordinate in the grid.
     */
    private record Point(int row, int col) {}

    public static void main(String[] args) {
        try {
            Solution solution = new Solution();
            solution.execute();
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Main execution flow: reads input, solves the problem, and prints the result.
     */
    public void execute() throws IOException {
        FastReader reader = new FastReader();

        int rows = reader.nextInt();
        int cols = reader.nextInt();
        if (rows <= 0 || cols <= 0) return;

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = reader.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
            }
        }

        int startRow = reader.nextInt() - 1;
        int startCol = reader.nextInt() - 1;
        int endRow = reader.nextInt() - 1;
        int endCol = reader.nextInt() - 1;

        if (canFindPath(grid, rows, cols, startRow, startCol, endRow, endCol)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Uses Depth-First Search to determine if a valid path exists to the target.
     */
    private boolean canFindPath(char[][] grid, int rows, int cols, 
                                int startR, int startC, int endR, int endC) {

        // Basic bounds check
        if (!isWithinBounds(startR, startC, rows, cols) || !isWithinBounds(endR, endC, rows, cols)) {
            return false;
        }

        Deque<Point> stack = new ArrayDeque<>();
        boolean[][] visited = new boolean[rows][cols];

        stack.push(new Point(startR, startC));
        visited[startR][startC] = true;

        while (!stack.isEmpty()) {
            Point current = stack.pop();

            // Check if we reached the destination
            if (current.row == endR && current.col == endC) {
                if (calculateTargetScore(grid, rows, cols, endR, endC, startR, startC) > 1) {
                    return true;
                }
                // If score condition is not met, we don't stop searching, 
                // but because it's marked visited, we won't process this target again.
            }

            for (int[] dir : DIRECTIONS) {
                int nextR = current.row + dir[0];
                int nextC = current.col + dir[1];

                if (isWithinBounds(nextR, nextC, rows, cols) && !visited[nextR][nextC]) {
                    if (isTraversable(grid, nextR, nextC, endR, endC)) {
                        visited[nextR][nextC] = true;
                        stack.push(new Point(nextR, nextC));
                    }
                }
            }
        }

        return false;
    }

    /**
     * Determines if a cell can be stepped on.
     * A cell is traversable if it is '.' or if it is 'X' and is the target destination.
     */
    private boolean isTraversable(char[][] grid, int r, int c, int targetR, int targetC) {
        if (grid[r][c] == '.') {
            return true;
        }
        return grid[r][c] == 'X' && r == targetR && c == targetC;
    }

    private boolean isWithinBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Calculates the target score based on the presence of 'X' at the target 
     * and the number of neighbors that are '.' or the original starting point.
     */
    private int calculateTargetScore(char[][] grid, int rows, int cols, 
                                     int targetR, int targetC, int startR, int startC) {
        int score = 0;

        if (grid[targetR][targetC] == 'X') {
            score++;
        }

        for (int[] dir : DIRECTIONS) {
            int neighborR = targetR + dir[0];
            int neighborC = targetC + dir[1];

            if (isWithinBounds(neighborR, neighborC, rows, cols)) {
                if (grid[neighborR][neighborC] == '.' || (neighborR == startR && neighborC == startC)) {
                    score++;
                }
            }
        }
        return score;
    }

    /**
     * Helper class for efficient input reading.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader() {
            reader = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

