/**
 * A refactored version of TaskA that solves the maze reachability problem.
 * The program determines if a path exists between two points and evaluates
 * a specific set of conditions based on the target's neighbors and state.
 */
public class TaskA {

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            Grid grid = new Grid(rows, cols);
            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                for (int j = 0; j < cols; j++) {
                    // '.' represents a path (false), anything else represents a wall (true)
                    grid.setWall(i, j, line.charAt(j) != '.');
                }
            }

            Point start = new Point(reader.nextInt() - 1, reader.nextInt() - 1);
            Point end = new Point(reader.nextInt() - 1, reader.nextInt() - 1);

            MazeSolver solver = new MazeSolver(grid);
            boolean isPathPossible = solver.canReach(start, end);

            if (isPathPossible) {
                boolean isTargetCracked = grid.isWall(end.row(), end.col());
                int pathNeighborsCount = grid.countPathNeighbors(end);
                boolean isStartAdjacentToEnd = grid.areAdjacent(start, end);

                // Evaluate original logic: 
                // reached && (target_is_wall || (adjacent && path_neighbors >= 1) || path_neighbors >= 2)
                boolean meetsCriteria = isTargetCracked || 
                                        (isStartAdjacentToEnd && pathNeighborsCount >= 1) || 
                                        (pathNeighborsCount >= 2);

                System.out.println(meetsCriteria ? "YES" : "NO");
            } else {
                System.out.println("NO");
            }

        } catch (IOException | IllegalArgumentException e) {
            e.printStackTrace();
        }
    }

    /**
     * Represents a coordinate in the grid.
     */
    record Point(int row, int col) {}

    /**
     * Manages the grid data and spatial queries.
     */
    static class Grid {
        private final int rows;
        private final int cols;
        private final boolean[][] wallMap;
        private static final int[] DR = {0, 1, -1, 0};
        private static final int[] DC = {1, 0, 0, -1};

        public Grid(int rows, int cols) {
            this.rows = rows;
            this.cols = cols;
            this.wallMap = new boolean[rows][cols];
        }

        public void setWall(int r, int c, boolean isWall) {
            wallMap[r][c] = isWall;
        }

        public boolean isWall(int r, int c) {
            return wallMap[r][c];
        }

        public boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        public boolean areAdjacent(Point p1, Point p2) {
            int rowDiff = Math.abs(p1.row() - p2.row());
            int colDiff = Math.abs(p1.col() - p2.col());
            return (rowDiff == 1 && colDiff == 0) || (rowDiff == 0 && colDiff == 1);
        }

        public int countPathNeighbors(Point p) {
            int count = 0;
            for (int i = 0; i < 4; i++) {
                int nr = p.row() + DR[i];
                int nc = p.col() + DC[i];
                if (isValid(nr, nc) && !isWall(nr, nc)) {
                    count++;
                }
            }
            return count;
        }

        public int getRows() { return rows; }
        public int getCols() { return cols; }
        public boolean isWallAt(int r, int c) { return wallMap[r][c]; }

        public static int[] getDr() { return DR; }
        public static int[] getDc() { return DC; }
    }

    /**
     * Handles pathfinding logic using Depth First Search.
     */
    static class MazeSolver {
        private final Grid grid;
        private boolean reached = false;

        public MazeSolver(Grid grid) {
            this.grid = grid;
        }

        public boolean canReach(Point start, Point end) {
            this.reached = false;
            // The original code used the grid itself to mark visited cells.
            // We use a separate visited array to maintain the integrity of the map.
            boolean[][] visited = new boolean[grid.getRows()][grid.getCols()];
            dfs(start.row(), start.col(), end, visited);
            return reached;
        }

        private void dfs(int r, int c, Point target, boolean[][] visited) {
            visited[r][c] = true;

            for (int i = 0; i < 4; i++) {
                if (reached) break;

                int nr = r + Grid.getDr()[i];
                int nc = c + Grid.getDc()[i];

                if (nr == target.row() && nc == target.col()) {
                    reached = true;
                    return;
                }

                if (grid.isValid(nr, nc) && !grid.isWallAt(nr, nc) && !visited[nr][nc]) {
                    dfs(nr, nc, target, visited);
                }
            }
        }
    }

    /**
     * Efficient input reader for large datasets.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader() throws IOException {
            reader = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        public double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }
}

import java.util.Scanner;

/**
 * GridPathSolver determines if a path exists between two points in a grid 
 * based on specific connectivity rules regarding obstacles ('X') and paths ('.').
 */
public class GridPathSolver {

    private static final int[] ROW_OFFSETS = {0, 1, 0, -1};
    private static final int[] COL_OFFSETS = {1, 0, -1, 0};

    private int rowCount;
    private int colCount;
    private char[][] grid;

    public static void main(String[] args) {
        GridPathSolver solver = new GridPathSolver();
        solver.run();
    }

    /**
     * Orchestrates the execution flow: input, processing, and output.
     */
    public void run() {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;

            parseInput(scanner);

            int startRow = scanner.nextInt() - 1;
            int startCol = scanner.nextInt() - 1;
            int endRow = scanner.nextInt() - 1;
            int endCol = scanner.nextInt() - 1;

            boolean result = determineIfPathIsPossible(startRow, startCol, endRow, endCol);
            System.out.println(result ? "YES" : "NO");
        } catch (Exception e) {
            System.out.println("NO");
        }
    }

    private void parseInput(Scanner scanner) {
        rowCount = scanner.nextInt();
        colCount = scanner.nextInt();
        grid = new char[rowCount][colCount];
        for (int i = 0; i < rowCount; i++) {
            String row = scanner.next();
            grid[i] = row.toCharArray();
        }
    }

    /**
     * Core logic to determine if the connection satisfies the problem requirements.
     */
    private boolean determineIfPathIsPossible(int startRow, int startCol, int endRow, int endCol) {
        int validNeighborCount = countValidNeighbors(endRow, endCol, startRow, startCol);

        // Case 1: Start and end are the same cell
        if (startRow == endRow && startCol == endCol) {
            return validNeighborCount > 0;
        }

        // Case 2: Determine reachability via DFS
        boolean[][] visited = initializeVisitedArray();

        // We allow the DFS to reach the target by ensuring it isn't pre-marked as "visited"
        // (Even if the target cell is an obstacle 'X')
        visited[endRow][endCol] = false;

        performDfs(startRow, startCol, visited);

        boolean isEndReachable = visited[endRow][endCol];

        if (!isEndReachable) {
            return false;
        }

        // If reachable, check the connectivity condition:
        // If the destination is a path ('.'), it must have more than one way to be entered.
        // If the destination is an obstacle ('X'), it is considered valid if reached.
        if (grid[endRow][endCol] == '.') {
            return validNeighborCount > 1;
        } else {
            return true;
        }
    }

    /**
     * Counts neighbors of the target that are either a path ('.') or the start point.
     */
    private int countValidNeighbors(int targetRow, int targetCol, int startRow, int startCol) {
        int count = 0;
        for (int i = 0; i < 4; i++) {
            int r = targetRow + ROW_OFFSETS[i];
            int c = targetCol + COL_OFFSETS[i];

            if (isWithinBounds(r, c)) {
                boolean isPath = grid[r][c] == '.';
                boolean isStartPoint = (r == startRow && c == startCol);
                if (isPath || isStartPoint) {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Initializes a visited array where all obstacle cells ('X') are pre-marked as visited.
     */
    private boolean[][] initializeVisitedArray() {
        boolean[][] visited = new boolean[rowCount][colCount];
        for (int i = 0; i < rowCount; i++) {
            for (int j = 0; j < colCount; j++) {
                if (grid[i][j] == 'X') {
                    visited[i][j] = true;
                }
            }
        }
        return visited;
    }

    /**
     * Standard Depth First Search to find all reachable cells.
     */
    private void performDfs(int r, int c, boolean[][] visited) {
        visited[r][c] = true;
        for (int i = 0; i < 4; i++) {
            int nextR = r + ROW_OFFSETS[i];
            int nextC = c + COL_OFFSETS[i];

            if (isWithinBounds(nextR, nextC) && !visited[nextR][nextC]) {
                performDfs(nextR, nextC, visited);
            }
        }
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rowCount && c >= 0 && c < colCount;
    }
}

import java.util.*;

/**
 * A solver for grid-based reachability problems.
 * This class determines if a target cell can be reached from a starting cell
 * through a path of traversable cells.
 */
public class MazeSolver {

    private static final int[] ROW_DIRECTIONS = {1, 0, 0, -1};
    private static final int[] COL_DIRECTIONS = {0, 1, -1, 0};
    private static final char TRAVERSABLE_CHAR = '.';

    private final int rows;
    private final int cols;
    private final char[][] grid;

    /**
     * Represents a coordinate on the grid.
     */
    private record Point(int row, int col) {}

    public MazeSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
    }

    /**
     * Performs a BFS to find if the target is reachable.
     * 
     * @param startRow The starting row index.
     * @param startCol The starting column index.
     * @param targetRow The target row index.
     * @param targetCol The target column index.
     * @return true if the target is reachable under the original program's constraints.
     */
    public boolean canReachTarget(int startRow, int startCol, int targetRow, int targetCol) {
        // The original logic specifically requires the target to be a non-dot cell.
        if (grid[targetRow][targetCol] == TRAVERSABLE_CHAR) {
            return false;
        }

        Queue<Point> queue = new ArrayDeque<>();
        boolean[][] visited = new boolean[rows][cols];

        // Initialize the search
        queue.add(new Point(startRow, startCol));
        visited[startRow][startCol] = true;

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            // Check if we have reached the target cell
            if (current.row() == targetRow && current.col() == targetCol) {
                return true;
            }

            // The original logic allows traversing through '.' cells.
            // It also treats the starting cell as traversable regardless of its initial character.
            boolean isStartingCell = (current.row() == startRow && current.col() == startCol);
            boolean isTraversableCell = (grid[current.row()][current.col()] == TRAVERSABLE_CHAR);

            if (!isStartingCell && !isTraversableCell) {
                continue;
            }

            // Explore adjacent cells
            for (int i = 0; i < 4; i++) {
                int nextRow = current.row() + ROW_DIRECTIONS[i];
                int nextCol = current.col() + COL_DIRECTIONS[i];

                if (isWithinBounds(nextRow, nextCol) && !visited[nextRow][nextCol]) {
                    visited[nextRow][nextCol] = true;
                    queue.add(new Point(nextRow, nextCol));
                }
            }
        }

        return false;
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Main entry point for the program.
     */
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
            }
        }

        // Input coordinates are 1-indexed in the original program
        int startRow = scanner.nextInt() - 1;
        int startCol = scanner.nextInt() - 1;
        int targetRow = scanner.nextInt() - 1;
        int targetCol = scanner.nextInt() - 1;

        MazeSolver solver = new MazeSolver(rows, cols, grid);
        boolean isReachable = solver.canReachTarget(startRow, startCol, targetRow, targetCol);

        System.out.println(isReachable ? "YES" : "NO");

        scanner.close();
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for CF540C.
 * This program determines if a path exists between two points in a grid 
 * based on specific traversal and adjacency rules.
 */
public class CF540C {

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);

        try {
            int n = sc.nextInt();
            int m = sc.nextInt();

            char[][] layout = new char[n][m];
            for (int i = 0; i < n; i++) {
                layout[i] = sc.next().toCharArray();
            }

            int sourceRow = sc.nextInt() - 1;
            int sourceCol = sc.nextInt() - 1;
            int destRow = sc.nextInt() - 1;
            int destCol = sc.nextInt() - 1;

            Grid grid = new Grid(n, m, layout);
            PathFinder pathFinder = new PathFinder(grid);

            boolean possible = pathFinder.solve(sourceRow, sourceCol, destRow, destCol);
            pw.println(possible ? "YES" : "NO");

        } catch (Exception e) {
            // In a production environment, use a logger. 
            // For competitive programming, we allow the exception to propagate or handle it silently.
        } finally {
            pw.flush();
            pw.close();
        }
    }

    /**
     * Represents the grid layout and provides boundary and walkability checks.
     */
    static class Grid {
        private final int rows;
        private final int cols;
        private final boolean[][] isWalkable;

        public Grid(int rows, int cols, char[][] layout) {
            this.rows = rows;
            this.cols = cols;
            this.isWalkable = new boolean[rows][cols];
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    // A cell is walkable if it contains a '.'
                    this.isWalkable[i][j] = (layout[i][j] == '.');
                }
            }
        }

        public int getRows() { return rows; }
        public int getCols() { return cols; }

        public boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        public boolean isWalkable(int r, int c) {
            return isWithinBounds(r, c) && isWalkable[r][c];
        }

        public void setWalkable(int r, int c, boolean value) {
            if (isWithinBounds(r, c)) {
                isWalkable[r][c] = value;
            }
        }

        public boolean isCellWalkable(int r, int c) {
            return isWithinBounds(r, c) && isWalkable[r][c];
        }
    }

    /**
     * Contains the logic for pathfinding and destination validation.
     */
    static class PathFinder {
        private final Grid grid;
        private static final int[][] DIRECTIONS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

        public PathFinder(Grid grid) {
            this.grid = grid;
        }

        /**
         * Solves the problem by checking path existence and destination requirements.
         */
        public boolean solve(int startR, int startC, int endR, int endC) {
            // The original logic ensures the starting cell is treated as walkable.
            grid.setWalkable(startR, startC, true);

            // Requirement 1: A path must exist from start to end.
            // The path must consist of walkable cells, but can end on a wall.
            if (!hasPath(startR, startC, endR, endC)) {
                return false;
            }

            // Requirement 2: The destination must satisfy specific adjacency rules.
            return isDestinationValid(startR, startC, endR, endC);
        }

        /**
         * Uses BFS to determine if a path exists from start to end.
         */
        private boolean hasPath(int startR, int startC, int endR, int endC) {
            Queue<int[]> queue = new LinkedList<>();
            boolean[][] visited = new boolean[grid.getRows()][grid.getCols()];

            queue.offer(new int[]{startR, startC});
            visited[startR][startC] = true;

            while (!queue.isEmpty()) {
                int[] curr = queue.poll();
                int r = curr[0];
                int c = curr[1];

                if (r == endR && c == endC) {
                    return true;
                }

                for (int[] dir : DIRECTIONS) {
                    int nr = r + dir[0];
                    int nc = c + dir[1];

                    if (grid.isWithinBounds(nr, nc) && !visited[nr][nc]) {
                        // We can move to a cell if it's the destination OR if it's a walkable cell.
                        if ((nr == endR && nc == endC) || grid.isCellWalkable(nr, nc)) {
                            visited[nr][nc] = true;
                            queue.offer(new int[]{nr, nc});
                        }
                    }
                }
            }
            return false;
        }

        /**
         * Implements the specific adjacency logic from the original problem.
         */
        private boolean isDestinationValid(int startR, int startC, int endR, int endC) {
            // If the destination is a wall, the original condition (!mat[dest]) is true.
            if (!grid.isCellWalkable(endR, endC)) {
                return true;
            }

            // If the destination is a walkable '.', it must satisfy adjacency rules.
            int adjWalkableCount = countAdjacentWalkable(endR, endC);

            if (startR == endR && startC == endC) {
                // If start is the destination, we need at least 1 neighbor.
                return adjWalkableCount >= 1;
            }
            // Otherwise, we need at least 2 neighbors to ensure "pass-through" capability.
            return adjWalkableCount >= 2;
        }

        private int countAdjacentWalkable(int r, int c) {
            int count = 0;
            for (int[] dir : DIRECTIONS) {
                if (grid.isCellWalkable(r + dir[0], c + dir[1])) {
                    count++;
                }
            }
            return count;
        }
    }

    /**
     * High-performance input reader.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream input) {
            this.reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

