/**
 * Represents a coordinate point in the 2D grid.
 */
record Point(int row, int col) {}

/**
 * Handles the logic of navigating the grid and determining target reachability.
 */
class GridSolver {
    private final FastReader reader;
    private int rows;
    private int cols;
    private boolean[][] grid;
    private boolean[][] visited;

    private static final int[] ROW_DIRECTIONS = {-1, 1, 0, 0};
    private static final int[] COL_DIRECTIONS = {0, 0, -1, 1};

    public GridSolver(FastReader reader) {
        this.reader = reader;
    }

    /**
     * Executes the solver logic.
     * @return true if the target meets the reachability criteria.
     */
    public boolean solve() {
        this.rows = reader.nextInt();
        this.cols = reader.nextInt();
        this.grid = new boolean[rows + 1][cols + 1];
        this.visited = new boolean[rows + 1][cols + 1];

        // Build the grid (1-indexed based on original logic)
        for (int i = 1; i <= rows; i++) {
            String rowData = reader.next();
            for (int j = 1; j <= cols; j++) {
                grid[i][j] = (rowData.charAt(j - 1) == '.');
            }
        }

        int startRow = reader.nextInt();
        int startCol = reader.nextInt();
        int targetRow = reader.nextInt();
        int targetCol = reader.nextInt();

        performDepthFirstSearch(startRow, startCol);

        return evaluateTargetReachability(targetRow, targetCol);
    }

    /**
     * Standard DFS traversal to mark all reachable cells.
     */
    private void performDepthFirstSearch(int startRow, int startCol) {
        Deque<Point> stack = new ArrayDeque<>();
        stack.push(new Point(startRow, startCol));

        while (!stack.isEmpty()) {
            Point current = stack.pop();

            if (visited[current.row()][current.col()]) {
                continue;
            }

            visited[current.row()][current.col()] = true;

            for (int i = 0; i < 4; i++) {
                int nextRow = current.row() + ROW_DIRECTIONS[i];
                int nextCol = current.col() + COL_DIRECTIONS[i];

                if (isValidMove(nextRow, nextCol)) {
                    stack.push(new Point(nextRow, nextCol));
                }
            }
        }
    }

    private boolean isValidMove(int r, int c) {
        return r >= 1 && r <= rows && c >= 1 && c <= cols && grid[r][c] && !visited[r][c];
    }

    /**
     * Evaluates the target cell based on the problem rules:
     * 1. If target is a wall (not '.'), at least 1 neighbor must be reachable.
     * 2. If target is a path ('.'), at least 2 neighbors must be reachable.
     */
    private boolean evaluateTargetReachability(int targetRow, int targetCol) {
        int reachableNeighborCount = 0;

        for (int i = 0; i < 4; i++) {
            int neighborRow = targetRow + ROW_DIRECTIONS[i];
            int neighborCol = targetCol + COL_DIRECTIONS[i];

            if (isWithinBounds(neighborRow, neighborCol) && visited[neighborRow][neighborCol]) {
                reachableNeighborCount++;
            }
        }

        boolean targetIsPassable = grid[targetRow][targetCol];
        if (!targetIsPassable) {
            return reachableNeighborCount >= 1;
        } else {
            return reachableNeighborCount >= 2;
        }
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 1 && r <= rows && c >= 1 && c <= cols;
    }
}

/**
 * Utility class for high-performance input reading.
