/**
 * Manages the grid data, including padding for boundary safety.
 */
class Grid {
    private final char[][] cells;
    private final int rows;
    private final int cols;

    public Grid(int h, int w, String[] lines) {
        this.rows = h + 2;
        this.cols = w + 2;
        this.cells = new char[rows][cols];

        // Initialize with boundaries
        for (int i = 0; i < rows; i++) {
            Arrays.fill(cells[i], 'X');
        }

        // Populate the map
        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                cells[i + 1][j + 1] = lines[i].charAt(j);
            }
        }
    }

    public char getChar(int r, int c) {
        return cells[r][c];
    }

    public boolean isWalkable(int r, int c) {
        return cells[r][c] == '.';
    }

    public int getRows() { return rows; }
    public int getCols() { return cols; }
}

/**
 * Contains the logic to solve the maze traversal problem.
 */
class MazeSolver {
    private static final int[][] DIRECTIONS = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};

    private enum RuleResult {
        YES, NO, CONTINUE_TO_BFS
    }

    private final Grid grid;
    private final Point start;
    private final Point goal;

    public MazeSolver(Grid grid, Point start, Point goal) {
        this.grid = grid;
        this.start = start;
        this.goal = goal;
    }

    /**
     * Orchestrates the solving process.
     * @return true if the goal is reachable, false otherwise.
     */
    public boolean solve() {
        RuleResult specialRuleResult = checkSpecialGoalRules();

        if (specialRuleResult == RuleResult.YES) return true;
        if (specialRuleResult == RuleResult.NO) return false;

        return performBFS();
    }

    /**
     * Handles the specific problem constraints regarding the goal's type and surroundings.
     */
    private RuleResult checkSpecialGoalRules() {
        boolean goalIsObstacle = grid.getChar(goal.r, goal.c) == 'X';
        int walkableNeighbors = countWalkableNeighbors(goal);
        boolean isStartAdjacentToGoal = isAdjacent(start, goal);

        if (goalIsObstacle) {
            if (isStartAdjacentToGoal) return RuleResult.YES;
            if (walkableNeighbors == 0) return RuleResult.NO;
            return RuleResult.CONTINUE_TO_BFS;
        } else {
            // Goal is a walkable '.' cell
            if (isStartAdjacentToGoal && walkableNeighbors >= 1) return RuleResult.YES;
            if (walkableNeighbors < 2) return RuleResult.NO;
            return RuleResult.CONTINUE_TO_BFS;
        }
    }

    private int countWalkableNeighbors(Point p) {
        int count = 0;
        for (int[] dir : DIRECTIONS) {
            if (grid.isWalkable(p.r + dir[0], p.c + dir[1])) {
                count++;
            }
        }
        return count;
    }

    private boolean isAdjacent(Point p1, Point p2) {
        return Math.abs(p1.r - p2.r) + Math.abs(p1.c - p2.c) == 1;
    }

    /**
     * Standard Breadth-First Search to find if the goal is reachable through '.' cells.
     */
    private boolean performBFS() {
        Queue<Point> queue = new ArrayDeque<>();
        boolean[][] visited = new boolean[grid.getRows()][grid.getCols()];

        queue.add(start);
        visited[start.r][start.c] = true;

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            for (int[] dir : DIRECTIONS) {
                int nextR = current.r + dir[0];
                int nextC = current.c + dir[1];

                // Check if the neighbor is the goal (could be 'X' or '.')
                if (nextR == goal.r && nextC == goal.c) {
                    return true;
                }

                // Standard traversal rules
                if (grid.isWalkable(nextR, nextC) && !visited[nextR][nextC]) {
                    visited[nextR][nextC] = true;
                    queue.add(new Point(nextR, nextC));
                }
            }
        }
        return false;
    }
}

