}

import java.util.*;
import java.io.*;

/**
 * A refactored solution for the Maze Pathfinding problem.
 * Focuses on maintainability, readability, and clean separation of concerns.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            MazeSolver solver = new MazeSolver(reader);
            out.println(solver.solve());
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.close();
        }
    }

    /**
     * Handles the core logic of the maze problem.
     */
    static class MazeSolver {
        private final int startRow;
        private final int startCol;
        private final int targetRow;
        private final int targetCol;
        private final Grid grid;

        private static final int[][] DIRECTIONS = {
            {0, 1}, {0, -1}, {1, 0}, {-1, 0}
        };

        public MazeSolver(FastReader reader) {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            this.grid = new Grid(rows, cols);

            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                for (int j = 0; j < cols; j++) {
                    if (line.charAt(j) == '.') {
                        grid.setWalkable(i, j, true);
                    }
                }
            }

            // Input is 1-based, converting to 0-based
            this.startRow = reader.nextInt() - 1;
            this.startCol = reader.nextInt() - 1;
            this.targetRow = reader.nextInt() - 1;
            this.targetCol = reader.nextInt() - 1;
        }

        public String solve() {
            boolean targetWasOriginallyBlocked = !grid.isWalkable(targetRow, targetCol);

            // Ensure start and target are treated as walkable for pathfinding purposes
            grid.setWalkable(startRow, startCol, true);
            grid.setWalkable(targetRow, targetCol, true);

            int walkableNeighborsOfTarget = countWalkableNeighbors(targetRow, targetCol);
            boolean pathExists = hasPathToTarget();

            if (startRow == targetRow && startCol == targetCol) {
                return walkableNeighborsOfTarget >= 1 ? "YES" : "NO";
            }

            // Condition: Path exists AND (target was a hole OR target has multiple exits)
            boolean conditionMet = pathExists && (targetWasOriginallyBlocked || walkableNeighborsOfTarget > 1);
            return conditionMet ? "YES" : "NO";
        }

        private int countWalkableNeighbors(int r, int c) {
            int count = 0;
            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (grid.isInBounds(nr, nc) && grid.isWalkable(nr, nc)) {
                    count++;
                }
            }
            return count;
        }

        private boolean hasPathToTarget() {
            boolean[][] visited = new boolean[grid.getRows()][grid.getCols()];
            return dfs(startRow, startCol, visited);
        }

        private boolean dfs(int r, int c, boolean[][] visited) {
            if (r == targetRow && c == targetCol) {
                return true;
            }

            visited[r][c] = true;

            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                if (grid.isInBounds(nr, nc) 
                        && grid.isWalkable(nr, nc) 
                        && !visited[nr][nc]) {
                    if (dfs(nr, nc, visited)) {
                        return true;
                    }
                }
            }
            return false;
        }
    }

    /**
     * Encapsulates the grid data and boundary checks.
     */
    static class Grid {
        private final int rows;
        private final int cols;
        private final boolean[][] walkableMatrix;

        public Grid(int rows, int cols) {
            this.rows = rows;
            this.cols = cols;
            this.walkableMatrix = new boolean[rows][cols];
        }

        public void setWalkable(int r, int c, boolean isWalkable) {
            walkableMatrix[r][c] = isWalkable;
        }

        public boolean isWalkable(int r, int c) {
            return walkableMatrix[r][c];
        }

        public boolean isInBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        public int getRows() { return rows; }
        public int getCols() { return cols; }
    }

    /**
     * Fast I/O utility for efficient reading.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }
    }
}

