/**
 * A solver for the Ice Cave problem.
 * The goal is to determine if a target cell can be reached under specific movement rules.
 */
public class IceCave {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            int startRow = reader.nextInt() - 1;
            int startCol = reader.nextInt() - 1;
            int targetRow = reader.nextInt() - 1;
            int targetCol = reader.nextInt() - 1;

            IceCaveSolver solver = new IceCaveSolver(rows, cols, grid, startRow, startCol, targetRow, targetCol);
            out.println(solver.solve() ? "YES" : "NO");

        } catch (Exception e) {
            // In a production environment, use a proper logging framework
            e.printStackTrace();
        } finally {
            out.close();
        }
    }

    /**
     * Core logic for solving the Ice Cave pathfinding problem.
     */
    static class IceCaveSolver {
        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final boolean[][] visited;

        private final int startRow;
        private final int startCol;
        private final int targetRow;
        private final int targetCol;

        private static final int[] DR = {-1, 1, 0, 0};
        private static final int[] DC = {0, 0, -1, 1};

        public IceCaveSolver(int rows, int cols, char[][] grid, 
                             int startRow, int startCol, int targetRow, int targetCol) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            this.startRow = startRow;
            this.startCol = startCol;
            this.targetRow = targetRow;
            this.targetCol = targetCol;
            this.visited = new boolean[rows][cols];
        }

        public boolean solve() {
            // Ensure the starting position is treated as a path
            grid[startRow][startCol] = '.';

            performIterativeFloodFill();

            if (!visited[targetRow][targetCol]) {
                return false;
            }

            // Specific rule logic preserved from original implementation
            if (startRow == targetRow && startCol == targetCol) {
                return countVisitedNeighbors(targetRow, targetCol) >= 1;
            }

            if (grid[targetRow][targetCol] == 'X') {
                return true;
            }

            // If target is a path ('.'), it requires at least 2 visited neighbors to be "valid"
            return countVisitedNeighbors(targetRow, targetCol) >= 2;
        }

        /**
         * Uses an iterative DFS approach to avoid StackOverflowError on large grids.
         */
        private void performIterativeFloodFill() {
            Deque<Point> stack = new ArrayDeque<>();
            stack.push(new Point(startRow, startCol));
            visited[startRow][startCol] = true;

            while (!stack.isEmpty()) {
                Point current = stack.pop();

                for (int i = 0; i < 4; i++) {
                    int nr = current.r + DR[i];
                    int nc = current.c + DC[i];

                    if (isWithinBounds(nr, nc) && !visited[nr][nc]) {
                        // We can move to a cell if it is a path ('.') 
                        // OR if it is the designated target cell.
                        if (grid[nr][nc] == '.' || (nr == targetRow && nc == targetCol)) {
                            visited[nr][nc] = true;
                            stack.push(new Point(nr, nc));
                        }
                    }
                }
            }
        }

        private int countVisitedNeighbors(int r, int c) {
            int count = 0;
            for (int i = 0; i < 4; i++) {
                int nr = r + DR[i];
                int nc = c + DC[i];
                if (isWithinBounds(nr, nc) && visited[nr][nc]) {
                    count++;
                }
            }
            return count;
        }

        private boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        private static class Point {
            final int r, c;
            Point(int r, int c) {
                this.r = r;
                this.c = c;
            }
        }
    }

    /**
     * Utility class for fast input reading.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

