/**
 * A solver to determine reachability in a grid with specific movement rules.
 */
public class GridReachabilitySolver {

    public static void main(String[] args) {
        try {
            SolverEngine engine = new SolverEngine(new FastReader(System.in));
            engine.run();
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Represents a coordinate in the 2D grid.
     */
    private record Point(int row, int col) {}

    /**
     * Encapsulates the grid and provides safe access methods.
     */
    private static class Grid {
        private final char[][] cells;
        private final int rows;
        private final int cols;

        public Grid(int rows, int cols, char[][] cells) {
            this.rows = rows;
            this.cols = cols;
            this.cells = cells;
        }

        public boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        public char getCell(int r, int c) {
            return cells[r][c];
        }

        public boolean isPath(int r, int c) {
            return isWithinBounds(r, c) && cells[r][c] == '.';
        }

        public boolean isObstacle(int r, int c) {
            return isWithinBounds(r, c) && cells[r][c] == 'X';
        }

        public int getRows() { return rows; }
        public int getCols() { return cols; }
    }

    /**
     * Handles the core logic of the problem.
     */
    private static class SolverEngine {
        private static final int[][] DIRECTIONS = { {-1, 0}, {1, 0}, {0, -1}, {0, 1} };

        private final FastReader reader;
        private Grid grid;
        private Point startPoint;
        private Point targetPoint;

        public SolverEngine(FastReader reader) {
            this.reader = reader;
        }

        public void run() throws IOException {
            int n = reader.nextInt();
            int m = reader.nextInt();
            char[][] gridData = new char[n][];
            for (int i = 0; i < n; i++) {
                gridData[i] = reader.readLine().toCharArray();
            }
            this.grid = new Grid(n, m, gridData);

            // Input coordinates are 1-indexed in the original logic, convert to 0-indexed
            this.startPoint = new Point(reader.nextInt() - 1, reader.nextInt() - 1);
            this.targetPoint = new Point(reader.nextInt() - 1, reader.nextInt() - 1);

            boolean reachable = computeReachability();
            System.out.println(reachable ? "YES" : "NO");
        }

        private boolean computeReachability() {
            int adjacentDotCount = countAdjacentDots(targetPoint);
            boolean isStartAtTarget = startPoint.equals(targetPoint);
            boolean isTargetEmpty = grid.getCell(targetPoint.row(), targetPoint.col()) == '.';
            boolean isAdjacent = getManhattanDistance(startPoint, targetPoint) == 1;

            // Special case logic preserved from original implementation
            if (isStartAtTarget) {
                return adjacentDotCount > 0;
            } 

            if (isTargetEmpty) {
                if (adjacentDotCount == 0) {
                    return false;
                } else if (adjacentDotCount == 1) {
                    return isAdjacent && grid.isObstacle(startPoint.row(), startPoint.col());
                }
            } else {
                // Target is an obstacle 'X'
                if (adjacentDotCount == 0) {
                    return isAdjacent;
                }
            }

            // Default to BFS for complex connectivity
            return performBfs();
        }

        private boolean performBfs() {
            Queue<Point> queue = new ArrayDeque<>();
            Set<Point> visited = new HashSet<>();

            queue.add(startPoint);
            visited.add(startPoint);

            while (!queue.isEmpty()) {
                Point current = queue.poll();

                if (current.equals(targetPoint)) {
                    return true;
                }

                for (int[] dir : DIRECTIONS) {
                    int nextR = current.row() + dir[0];
                    int nextC = current.col() + dir[1];
                    Point neighbor = new Point(nextR, nextC);

                    if (grid.isWithinBounds(nextR, nextC)) {
                        // Rule: Can move into a '.' cell OR the target cell itself
                        boolean canMoveToNeighbor = grid.isPath(nextR, nextC) || neighbor.equals(targetPoint);

                        if (canMoveToNeighbor && !visited.contains(neighbor)) {
                            visited.add(neighbor);
                            queue.add(neighbor);
                        }
                    }
                }
            }
            return false;
        }

        private int countAdjacentDots(Point p) {
            int count = 0;
            for (int[] dir : DIRECTIONS) {
                int nr = p.row() + dir[0];
                int nc = p.col() + dir[1];
                if (grid.isPath(nr, nc)) {
                    count++;
                }
            }
            return count;
        }

        private int getManhattanDistance(Point p1, Point p2) {
            return Math.abs(p1.row() - p2.row()) + Math.abs(p1.col() - p2.col());
        }
    }

    /**
     * Efficient reader for large input sets.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(java.io.InputStream inputStream) {
            this.reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String readLine() throws IOException {
            return reader.readLine();
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

