            IceCaveSolver solver = new IceCaveSolver(grid, endRow, endCol);
            boolean reachable = solver.canReachTarget(startRow, startCol);

            System.out.println(reachable ? "YES" : "NO");
        }
    }
}

/**
 * Contains the core logic for navigating the ice cave.
 */
class IceCaveSolver {

    private static final int[][] DIRECTIONS = {
        {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    private final boolean[][] isCrack;
    private final int rows;
    private final int cols;
    private final int targetRow;
    private final int targetCol;

    // Search state tracking
    private final boolean[][] failedNodes;
    private final boolean[][] onCurrentPath;

    /**
     * @param grid The initial state of the ice cave (true if cracked).
     * @param targetRow The target destination row.
     * @param targetCol The target destination column.
     */
    public IceCaveSolver(boolean[][] grid, int targetRow, int targetCol) {
        this.isCrack = grid;
        this.rows = grid.length;
        this.cols = grid[0].length;
        this.targetRow = targetRow;
        this.targetCol = targetCol;
        this.failedNodes = new boolean[rows][cols];
        this.onCurrentPath = new boolean[rows][cols];
    }

    /**
     * Determines if a path exists from the starting point to the target.
     * 
     * @param startRow Starting row index.
     * @param startCol Starting column index.
     * @return true if target is reachable, false otherwise.
     */
    public boolean canReachTarget(int startRow, int startCol) {
        // The original logic treats the starting cell as non-cracked regardless of input
        isCrack[startRow][startCol] = false;
        return performDfs(startRow, startCol);
    }

    /**
     * Depth-First Search to find a valid path.
     */
    private boolean performDfs(int r, int c) {
        // 1. Check if the current cell is the target
        if (r == targetRow && c == targetCol) {
            return isTargetReachable(r, c);
        }

        // 2. Validate boundaries and traversal constraints
        if (!isInside(r, c) || isCrack[r][c] || onCurrentPath[r][c] || failedNodes[r][c]) {
            return false;
        }

        // 3. Mark current cell as being in the active search path to prevent cycles
        onCurrentPath[r][c] = true;

        // 4. Explore neighbors
        boolean foundPath = false;
        for (int[] dir : DIRECTIONS) {
            if (performDfs(r + dir[0], c + dir[1])) {
                foundPath = true;
                break;
            }
        }

        // 5. Backtrack and prune
        if (foundPath) {
            return true;
        } else {
            // If no path was found through this node, mark it as failed to avoid re-processing
            onCurrentPath[r][c] = false;
            failedNodes[r][c] = true;
            return false;
        }
    }

    /**
     * Implements the original logic for the target cell:
     * A target is reached if it's cracked OR if it's a non-cracked cell with a non-cracked neighbor.
     */
    private boolean isTargetReachable(int r, int c) {
        return isCrack[r][c] || hasNonCrackNeighbor(r, c);
    }

    private boolean hasNonCrackNeighbor(int r, int c) {
        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            if (isInside(nr, nc) && !isCrack[nr][nc]) {
                return true;
            }
        }
        return false;
    }

    private boolean isInside(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

import java.util.Scanner;

/**
 * A solver for the Ice Cave pathfinding problem.
 * Determines if there is a traversable path from a starting point to an end point.
 */
public class IceCaveSolver {

    // Directions for movement: Right, Down, Left, Up
    private static final int[][] DIRECTIONS = {
        {0, 1}, {1, 0}, {0, -1}, {-1, 0}
    };

    private final int rowCount;
    private final int colCount;
    private final char[][] grid;
    private final boolean[][] visited;

    /**
     * Initializes the solver with the game grid.
     * 
     * @param rowCount Number of rows in the grid.
     * @param colCount Number of columns in the grid.
     * @param grid     The 2D character array representing the cave.
     */
    public IceCaveSolver(int rowCount, int colCount, char[][] grid) {
        this.rowCount = rowCount;
        this.colCount = colCount;
        this.grid = grid;
        this.visited = new boolean[rowCount][colCount];
    }

    /**
     * Determines if a path exists between the start and end coordinates.
     *
     * @param startRow Starting row index (0-indexed).
     * @param startCol Starting column index (0-indexed).
     * @param endRow   Target row index (0-indexed).
     * @param endCol   Target column index (0-indexed).
     * @return true if a path is found, false otherwise.
     */
    public boolean canReachTarget(int startRow, int startCol, int endRow, int endCol) {
        // Validate input boundaries
        if (isOutOfBounds(startRow, startCol) || isOutOfBounds(endRow, endCol)) {
            return false;
        }

        // Check if start or end positions are blocked
        if (grid[startRow][startCol] == 'X' || grid[endRow][endCol] == 'X') {
            return false;
        }

        return performDFS(startRow, startCol, endRow, endCol);
    }

    /**
     * Recursive Depth First Search to explore the cave.
     */
    private boolean performDFS(int r, int c, int targetR, int targetC) {
        // Base case: Target reached
        if (r == targetR && c == targetC) {
            return true;
        }

        // Mark current cell as visited
        visited[r][c] = true;

        // Explore neighbors
        for (int[] direction : DIRECTIONS) {
            int nextR = r + direction[0];
            int nextC = c + direction[1];

            if (isValidMove(nextR, nextC) && !visited[nextR][nextC]) {
                if (performDFS(nextR, nextC, targetR, targetC)) {
                    return true;
                }
            }
        }

        return false;
    }

    /**
     * Validates if a move is within bounds and is a walkable path ('.').
     */
    private boolean isValidMove(int r, int c) {
        return !isOutOfBounds(r, c) && grid[r][c] == '.';
    }

    /**
     * Checks if the given coordinates are outside the grid boundaries.
     */
    private boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= rowCount || c < 0 || c >= colCount;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
            }
        }

        // The original code used 1-based indexing for coordinates.
        // We convert them to 0-based indexing for internal logic.
        int startRow = scanner.nextInt() - 1;
        int startCol = scanner.nextInt() - 1;
        int endRow = scanner.nextInt() - 1;
        int endCol = scanner.nextInt() - 1;

        IceCaveSolver solver = new IceCaveSolver(rows, cols, grid);

        if (solver.canReachTarget(startRow, startCol, endRow, endCol)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }
}

import java.io.*;
import java.util.*;

/**
 * A solution to determine reachability on a grid based on specific 
 * adjacency and character rules.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            char[][] gridData = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                gridData[i] = reader.next().toCharArray();
            }

            Point start = new Point(reader.nextInt() - 1, reader.nextInt() - 1);
            Point end = new Point(reader.nextInt() - 1, reader.nextInt() - 1);

            Grid grid = new Grid(gridData);
            Pathfinder pathfinder = new Pathfinder(grid, start, end);

            if (pathfinder.solve()) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }

        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Represents a coordinate on the grid.
     */
    record Point(int row, int col) {}

    /**
     * Manages the grid data and boundary checks.
     */
    static class Grid {
        private final char[][] matrix;
        private final int rows;
        private final int cols;

        public Grid(char[][] matrix) {
            this.matrix = matrix;
            this.rows = matrix.length;
            this.cols = matrix[0].length;
        }

        public boolean isValid(int r, int c) {
            return r >= 0 && c >= 0 && r < rows && c < cols;
        }

        public char getCharAt(int r, int c) {
            return matrix[r][c];
        }

        public int countNeighborsWithChar(Point p, char target) {
            int count = 0;
            int[] dr = {0, 0, 1, -1};
            int[] dc = {1, -1, 0, 0};

            for (int i = 0; i < 4; i++) {
                int nr = p.row() + dr[i];
                int nc = p.col() + dc[i];
                if (isValid(nr, nc) && matrix[nr][nc] == target) {
                    count++;
                }
            }
            return count;
        }

        public boolean isNeighbor(Point p1, Point p2) {
            return Math.abs(p1.row() - p2.row()) + Math.abs(p1.col() - p2.col()) == 1;
        }

        public int getRows() { return rows; }
        public int getCols() { return cols; }
    }

    /**
     * Contains the business logic for pathfinding and adjacency rules.
     */
    static class Pathfinder {
        private final Grid grid;
        private final Point start;
        private final Point end;
        private final boolean[][] visited;

        private static final int[] ROW_OFFSETS = {0, 0, 1, -1};
        private static final int[] COL_OFFSETS = {1, -1, 0, 0};

        public Pathfinder(Grid grid, Point start, Point end) {
            this.grid = grid;
            this.start = start;
            this.end = end;
            this.visited = new boolean[grid.getRows()][grid.getCols()];
        }

        /**
         * The core logic determining if the destination is reachable under the given rules.
         */
        public boolean solve() {
            if (start.equals(end)) {
                return hasAtLeastOneEmptyNeighbor(start);
            }

            boolean canReachDest = canReach(start.row(), start.col());
            boolean destIsSpecial = grid.getCharAt(end.row(), end.col()) == 'X' 
                                    || isComplexSurrounded(end);

            return canReachDest && destIsSpecial;
        }

        private boolean hasAtLeastOneEmptyNeighbor(Point p) {
            return grid.countNeighborsWithChar(p, '.') >= 1;
        }

        /**
         * Complex rule: counts '.' neighbors, plus 1 if a neighbor is the start point and is 'X'.
         */
        private boolean isComplexSurrounded(Point p) {
            int dotNeighbors = grid.countNeighborsWithChar(p, '.');
            boolean startIsXNeighbor = grid.isNeighbor(p, start) && grid.getCharAt(start.row(), start.col()) == 'X';

            int totalWeight = dotNeighbors + (startIsXNeighbor ? 1 : 0);
            return totalWeight >= 2;
        }

        /**
         * DFS to find a path from current cell to end cell.
         * Rules: Can move to non-'X' cells, or the end cell itself.
         */
        private boolean canReach(int r, int c) {
            if (r == end.row() && c == end.col()) {
                return true;
            }

            visited[r][c] = true;

            for (int i = 0; i < 4; i++) {
                int nr = r + ROW_OFFSETS[i];
                int nc = c + COL_OFFSETS[i];

                if (grid.isValid(nr, nc) && !visited[nr][nc]) {
                    // The destination is reachable even if it is 'X'
                    boolean isTarget = (nr == end.row() && nc == end.col());
                    boolean isPassable = grid.getCharAt(nr, nc) != 'X';

                    if (isTarget || isPassable) {
                        if (canReach(nr, nc)) return true;
                    }
                }
            }
            return false;
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
