import java.util.StringTokenizer;

/**
 * Refactored IceCave program.
 * Solves the problem of determining if a path can be successfully navigated
 * within an ice cave based on specific entry and terrain rules.
 */
public class IceCave {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            IceCaveSolver solver = new IceCaveSolver(reader);
            boolean canNavigate = solver.solve();
            writer.println(canNavigate ? "YES" : "NO");
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    /**
     * Encapsulates the logic for solving the Ice Cave problem.
     */
    static class IceCaveSolver {
        private static final int[] ROW_OFFSETS = {0, 0, -1, 1};
        private static final int[] COL_OFFSETS = {-1, 1, 0, 0};

        private final int rows;
        private final int cols;
        private final boolean[][] passableGrid;
        private final int startRow, startCol;
        private final int targetRow, targetCol;
        private boolean[][] visited;

        public IceCaveSolver(FastReader reader) {
            this.rows = reader.nextInt();
            this.cols = reader.nextInt();
            this.passableGrid = new boolean[rows][cols];

            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                for (int j = 0; j < cols; j++) {
                    // '.' is passable, anything else is a wall
                    passableGrid[i][j] = (line.charAt(j) == '.');
                }
            }

            // Convert 1-based indexing to 0-based
            this.startRow = reader.nextInt() - 1;
            this.startCol = reader.nextInt() - 1;
            this.targetRow = reader.nextInt() - 1;
            this.targetCol = reader.nextInt() - 1;
        }

        /**
         * Executes the core logic of the problem.
         * @return true if the navigation is possible, false otherwise.
         */
        public boolean solve() {
            // Edge case: Start and Target are the same cell
            if (startRow == targetRow && startCol == targetCol) {
                return isAdjacentToPassable(targetRow, targetCol);
            }

            this.visited = new boolean[rows][cols];

            // Check if a path can be found to the target cell
            if (findPathDFS(startRow, startCol)) {
                // If target is a wall, it's considered a successful "entry"
                if (!passableGrid[targetRow][targetCol]) {
                    return true;
                }

                // If target is passable, it must have at least 2 neighbors 
                // that are either part of the path or also passable.
                return countValidNeighbors(targetRow, targetCol) >= 2;
            }

            return false;
        }

        private boolean findPathDFS(int r, int c) {
            visited[r][c] = true;

            for (int i = 0; i < 4; i++) {
                int nextR = r + ROW_OFFSETS[i];
                int nextC = c + COL_OFFSETS[i];

                if (isWithinBounds(nextR, nextC)) {
                    // If we can step into the target cell
                    if (nextR == targetRow && nextC == targetCol) {
                        return true;
                    }

                    // Continue DFS if the cell is passable and not visited
                    if (passableGrid[nextR][nextC] && !visited[nextR][nextC]) {
                        if (findPathDFS(nextR, nextC)) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        private int countValidNeighbors(int r, int c) {
            int count = 0;
            for (int i = 0; i < 4; i++) {
                int nextR = r + ROW_OFFSETS[i];
                int nextC = c + COL_OFFSETS[i];

                if (isWithinBounds(nextR, nextC)) {
                    // A neighbor is valid if it was part of the DFS path or is passable
                    if (visited[nextR][nextC] || passableGrid[nextR][nextC]) {
                        count++;
                    }
                }
            }
            return count;
        }

        private boolean isAdjacentToPassable(int r, int c) {
            for (int i = 0; i < 4; i++) {
                int nextR = r + ROW_OFFSETS[i];
                int nextC = c + COL_OFFSETS[i];
                if (isWithinBounds(nextR, nextC) && passableGrid[nextR][nextC]) {
                    return true;
                }
            }
            return false;
        }

        private boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * Utility class for fast input parsing.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(java.io.InputStream input) {
            this.reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A refactored solution for the grid reachability problem.
 * The goal is to determine if a target cell can be reached from a starting point
 * based on specific adjacency conditions.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        GridSolver solver = new GridSolver();
        solver.solve(reader, writer);

        writer.flush();
        writer.close();
    }

    /**
     * Handles the core logic of solving the grid problem.
     */
    static class GridSolver {
        // Directional vectors for 4-connectivity (Up, Down, Left, Right)
        private static final int[] ROW_OFFSETS = {0, 0, 1, -1};
        private static final int[] COL_OFFSETS = {-1, 1, 0, 0};

        private char[][] grid;
        private int rows;
        private int cols;

        /**
         * Reads input, executes the solver, and prints the result.
         */
        public void solve(FastReader in, PrintWriter out) {
            rows = in.nextInt();
            cols = in.nextInt();
            grid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                String line = in.nextLine();
                if (line != null) {
                    grid[i] = line.toCharArray();
                }
            }

            // Convert 1-based indexing to 0-based indexing
            int startR = in.nextInt() - 1;
            int startC = in.nextInt() - 1;
            int targetR = in.nextInt() - 1;
            int targetC = in.nextInt() - 1;

            boolean isPossible = performBfs(startR, startC, targetR, targetC);
            out.println(isPossible ? "YES" : "NO");
        }

        /**
         * Performs a Breadth-First Search to find a valid path to the target.
         * 
         * @return true if the target cell is reached and satisfies the condition.
         */
        private boolean performBfs(int startR, int startC, int targetR, int targetC) {
            Queue<Point> queue = new ArrayDeque<>();
            queue.add(new Point(startR, startC));

            while (!queue.isEmpty()) {
                Point current = queue.poll();

                for (int i = 0; i < 4; i++) {
                    int nextR = current.r + ROW_OFFSETS[i];
                    int nextC = current.c + COL_OFFSETS[i];

                    if (isWithinBounds(nextR, nextC)) {
                        // If the neighbor is the target, check its specific conditions
                        if (nextR == targetR && nextC == targetC) {
                            if (isTargetSatisfied(targetR, targetC)) {
                                return true;
                            }
                        } 
                        // Otherwise, if it's a path cell ('.'), mark as visited and continue BFS
                        else if (grid[nextR][nextC] == '.') {
                            grid[nextR][nextC] = 'S'; // 'S' acts as a visited marker
                            queue.add(new Point(nextR, nextC));
                        }
                    }
                }
            }
            return false;
        }

        /**
         * Evaluates whether the target cell meets the requirement:
         * 1. The cell contains 'X'
         * 2. The cell contains '.' AND (has >= 1 '.' neighbor OR >= 2 'S' neighbors)
         */
        private boolean isTargetSatisfied(int r, int c) {
            if (grid[r][c] == 'X') {
                return true;
            }
            if (grid[r][c] != '.') {
                return false;
            }

            int dotNeighbors = 0;
            int visitedNeighbors = 0;

            for (int i = 0; i < 4; i++) {
                int nr = r + ROW_OFFSETS[i];
                int nc = c + COL_OFFSETS[i];

                if (isWithinBounds(nr, nc)) {
                    if (grid[nr][nc] == '.') {
                        dotNeighbors++;
                    } else if (grid[nr][nc] == 'S') {
                        visitedNeighbors++;
                    }
                }
            }

            return dotNeighbors >= 1 || visitedNeighbors >= 2;
        }

        private boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        /**
         * Simple data carrier for grid coordinates.
         */
        private static class Point {
            final int r, c;
            Point(int r, int c) {
                this.r = r;
                this.c = c;
            }
        }
    }

    /**
     * Fast I/O utility for efficient reading of large inputs.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            this.reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            return next != null ? Integer.parseInt(next) : 0;
        }

        public String nextLine() {
            try {
                return reader.readLine();
            } catch (IOException e) {
                return null;
            }
        }
    }
}

import java.util.*;

/**
 * MazeSolver determines if a path exists to a target location in a grid
 * and evaluates if that target is a valid "exit" based on its surroundings.
 */
public class MazeSolver {

    // Directions for moving: Right, Left, Down, Up
    private static final int[][] DIRECTIONS = {
            {0, 1}, {0, -1}, {1, 0}, {-1, 0}
    };

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        scanner.nextLine(); // Consume the remaining newline

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.nextLine();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
            }
        }

        // Convert 1-based indexing to 0-based indexing
        int startRow = scanner.nextInt() - 1;
        int startCol = scanner.nextInt() - 1;
        int endRow = scanner.nextInt() - 1;
        int endCol = scanner.nextInt() - 1;

        if (canEscape(grid, rows, cols, startRow, startCol, endRow, endCol)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Determines if the target location can be reached and if it meets the exit criteria.
     */
    private static boolean canEscape(char[][] grid, int rows, int cols, 
                                     int startR, int startC, int endR, int endC) {

        // Step 1: Verify if a path exists to the target
        if (!hasPathToTarget(grid, rows, cols, startR, startC, endR, endC)) {
            return false;
        }

        // Step 2: If target is an obstacle 'X', it's considered a valid exit/destination
        if (grid[endR][endC] == 'X') {
            return true;
        }

        // Step 3: If target is '.', check if it has multiple exits or connects back to start
        int exitCount = countPassableNeighbors(grid, rows, cols, startR, startC, endR, endC);

        return exitCount > 1;
    }

    /**
     * Uses Breadth-First Search (BFS) to find if a path exists from start to end.
     */
    private static boolean hasPathToTarget(char[][] grid, int rows, int cols, 
                                           int startR, int startC, int endR, int endC) {

        boolean[][] visited = new boolean[rows][cols];
        Deque<int[]> queue = new ArrayDeque<>();

        queue.add(new int[]{startR, startC});
        visited[startR][startC] = true;

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int currR = current[0];
            int currC = current[1];

            if (currR == endR && currC == endC) {
                return true;
            }

            for (int[] dir : DIRECTIONS) {
                int nextR = currR + dir[0];
                int nextC = currC + dir[1];

                if (isWithinBounds(nextR, nextC, rows, cols) && !visited[nextR][nextC]) {
                    // We can move to the target even if it's 'X', 
                    // but we can only traverse through '.' cells.
                    if ((nextR == endR && nextC == endC) || grid[nextR][nextC] == '.') {
                        visited[nextR][nextC] = true;
                        queue.add(new int[]{nextR, nextC});
                    }
                }
            }
        }

        return false;
    }

    /**
     * Counts how many neighbors of the target are either '.' or the starting position.
     */
    private static int countPassableNeighbors(char[][] grid, int rows, int cols, 
                                              int startR, int startC, int endR, int endC) {
        int count = 0;
        for (int[] dir : DIRECTIONS) {
            int nr = endR + dir[0];
            int nc = endC + dir[1];

            if (isWithinBounds(nr, nc, rows, cols)) {
                // A neighbor is "passable" if it's an empty space or the origin point
                if (grid[nr][nc] == '.' || (nr == startR && nc == startC)) {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Helper to validate grid boundaries.
     */
    private static boolean isWithinBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

import java.util.Scanner;

/**
 * A solver for grid-based reachability problems.
 * The goal is to determine if a target cell can be reached under specific conditions:
 * 1. If the target is an obstacle ('X'), check if any adjacent path cell is reachable.
 * 2. If the target is a path ('.'), check if it remains reachable even after blocking one adjacent path cell.
 */
public class MazeSolver {

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private boolean[][] visited;

    // Direction vectors for moving Up, Down, Left, and Right
    private static final int[] ROW_OFFSETS = {-1, 1, 0, 0};
    private static final int[] COL_OFFSETS = {0, 0, -1, 1};

    public MazeSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.visited = new boolean[rows][cols];
    }

    /**
     * Performs a Depth First Search to mark all reachable '.' cells.
     * 
     * @param r Current row index
     * @param c Current column index
     */
    private void dfs(int r, int c) {
        visited[r][c] = true;

        for (int i = 0; i < 4; i++) {
            int nextR = r + ROW_OFFSETS[i];
            int nextC = c + COL_OFFSETS[i];

            if (isWithinBounds(nextR, nextC) && grid[nextR][nextC] == '.' && !visited[nextR][nextC]) {
                dfs(nextR, nextC);
            }
        }
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private void resetVisited() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                visited[i][j] = false;
            }
        }
    }

    /**
     * Executes the primary logic of the maze problem.
     * 
     * @param startRow Starting row index (0-indexed)
     * @param startCol Starting column index (0-indexed)
     * @param endRow Target row index (0-indexed)
     * @param endCol Target column index (0-indexed)
     */
    public void solve(int startRow, int startCol, int endRow, int endCol) {
        if (grid[endRow][endCol] == 'X') {
            handleObstacleTarget(startRow, startCol, endRow, endCol);
        } else {
            handlePathTarget(startRow, startCol, endRow, endCol);
        }
    }

    /**
     * Logic for when the target cell is an obstacle ('X').
     * Checks if any adjacent cell to the obstacle is reachable from the start.
     */
    private void handleObstacleTarget(int startRow, int startCol, int endRow, int endCol) {
        dfs(startRow, startCol);
        boolean neighborReachable = false;

        for (int i = 0; i < 4; i++) {
            int nr = endRow + ROW_OFFSETS[i];
            int nc = endCol + COL_OFFSETS[i];
            if (isWithinBounds(nr, nc) && visited[nr][nc]) {
                neighborReachable = true;
                break;
            }
        }
        System.out.println(neighborReachable ? "YES" : "NO");
    }

    /**
     * Logic for when the target cell is a path ('.').
     * Checks if the target remains reachable even if one adjacent '.' cell is turned into an 'X'.
     */
    private void handlePathTarget(int startRow, int startCol, int endRow, int endCol) {
        boolean multiplePathsExist = false;

        for (int i = 0; i < 4; i++) {
            int nr = endRow + ROW_OFFSETS[i];
            int nc = endCol + COL_OFFSETS[i];

            if (isWithinBounds(nr, nc) && grid[nr][nc] == '.') {
                // Temporarily block this neighbor
                grid[nr][nc] = 'X';
                resetVisited();
                dfs(startRow, startCol);

                if (visited[endRow][endCol]) {
                    multiplePathsExist = true;
                }

                // Backtrack: restore the grid for the next attempt
                grid[nr][nc] = '.';
                if (multiplePathsExist) break;
            }
        }
        System.out.println(multiplePathsExist ? "YES" : "NO");
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int n = scanner.nextInt();
        int m = scanner.nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String rowData = scanner.next();
            for (int j = 0; j < m; j++) {
                grid[i][j] = rowData.charAt(j);
            }
        }

        // Convert 1-based input to 0-based indices
        int r1 = scanner.nextInt() - 1;
        int c1 = scanner.nextInt() - 1;
        int r2 = scanner.nextInt() - 1;
        int c2 = scanner.nextInt() - 1;

        MazeSolver solver = new MazeSolver(n, m, grid);
        solver.solve(r1, c1, r2, c2);

        scanner.close();
    }
}

import java.io.*;
import java.util.*;

/**
 * GridPathfinder solves the problem of determining if a target cell in a grid 
 * is reachable from a starting cell according to specific movement and 
 * environmental constraints.
 */
public class GridPathfinder {

    private static final int EMPTY = 0;
    private static final int OBSTACLE = 1;

    private final int[][] grid;
    private final int rows;
    private final int cols;

    public GridPathfinder(int rows, int cols, int[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
    }

    /**
     * Represents a coordinate in the grid.
     */
    public record Point(int r, int c) {}

    /**
     * Determines if the target cell can be reached and meets the required conditions.
     * 
     * @param startR Starting row index.
     * @param startC Starting column index.
     * @param targetR Target row index.
     * @param targetC Target column index.
     * @return true if the path is valid and the destination meets the criteria.
     */
    public boolean solve(int startR, int startC, int targetR, int targetC) {
        if (!isReachable(startR, startC, targetR, targetC)) {
            return false;
        }
        return isTargetValid(targetR, targetC, startR, startC);
    }

    /**
     * Performs a BFS to check if the target is reachable.
     * A path consists of empty cells, but the target cell itself can be an obstacle.
     */
    private boolean isReachable(int startR, int startC, int targetR, int targetC) {
        if (startR == targetR && startC == targetC) {
            return true;
        }

        Queue<Point> queue = new LinkedList<>();
        boolean[][] visited = new boolean[rows][cols];

        queue.add(new Point(startR, startC));
        visited[startR][startC] = true;

        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            for (int i = 0; i < 4; i++) {
                int nr = current.r() + dr[i];
                int nc = current.c() + dc[i];

                if (isValidBounds(nr, nc)) {
                    // If we hit the target, it's reachable (even if it's an obstacle)
                    if (nr == targetR && nc == targetC) {
                        return true;
                    }
                    // Otherwise, we can only continue through empty cells
                    if (grid[nr][nc] == EMPTY && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        queue.add(new Point(nr, nc));
                    }
                }
            }
        }
        return false;
    }

    /**
     * Validates the target cell based on its type and surrounding environment.
     */
    private boolean isTargetValid(int r, int c, int startR, int startC) {
        int emptyNeighbors = countEmptyNeighbors(r, c);
        int manhattanDist = Math.abs(r - startR) + Math.abs(c - startC);

        if (grid[r][c] == OBSTACLE) {
            // Obstacle is valid if it has an empty neighbor or is adjacent to start
            return emptyNeighbors > 0 || manhattanDist == 1;
        } else {
            // Empty cell is valid if it has > 1 empty neighbors OR is adjacent with at least 1 neighbor
            return emptyNeighbors > 1 || (manhattanDist == 1 && emptyNeighbors >= 1);
        }
    }

    private int countEmptyNeighbors(int r, int c) {
        int count = 0;
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int i = 0; i < 4; i++) {
            int nr = r + dr[i];
            int nc = c + dc[i];
            if (isValidBounds(nr, nc) && grid[nr][nc] == EMPTY) {
                count++;
            }
        }
        return count;
    }

    private boolean isValidBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    public static void main(String[] args) {
        FastReader fr = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            int n = fr.nextInt();
            int m = fr.nextInt();

            int[][] grid = new int[n][m];
            for (int i = 0; i < n; i++) {
                String line = fr.next();
                for (int j = 0; j < m; j++) {
                    grid[i][j] = (line.charAt(j) == '.') ? EMPTY : OBSTACLE;
                }
            }

            // Input coordinates are 1-indexed in the original problem
            int startR = fr.nextInt() - 1;
            int startC = fr.nextInt() - 1;
            int targetR = fr.nextInt() - 1;
            int targetC = fr.nextInt() - 1;

            GridPathfinder solver = new GridPathfinder(n, m, grid);
            if (solver.solve(startR, startC, targetR, targetC)) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        } catch (Exception e) {
            // Handle or log exceptions as needed for production
        } finally {
            out.close();
        }
    }

    /**
     * Efficient reader for large input sets.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.*;

/**
 * A solver for grid connectivity problems.
 * Determines if two points in a grid can be connected based on specific connectivity rules.
 */
public class GridConnectivitySolver {

    private static final int[][] DIRECTIONS = {
            {1, 0}, {-1, 0}, {0, 1}, {0, -1}
    };

    private final FastReader reader;
    private final PrintWriter writer;

    public GridConnectivitySolver() {
        this.reader = new FastReader();
        this.writer = new PrintWriter(System.out);
    }

    /**
     * Represents a coordinate in the grid.
     */
    private static class Point {
        final int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Point)) return false;
            Point point = (Point) o;
            return r == point.r && c == point.c;
        }

        @Override
        public int hashCode() {
            return Objects.hash(r, c);
        }
    }

    /**
     * Manages the grid structure and operations.
     */
    private static class Grid {
        private final char[][] cells;
        private final int rows;
        private final int cols;

        Grid(int rows, int cols) {
            this.rows = rows;
            this.cols = cols;
            this.cells = new char[rows][cols];
        }

        void setCell(int r, int c, char val) {
            cells[r][c] = val;
        }

        char getCell(int r, int c) {
            return cells[r][c];
        }

        boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        boolean isDot(int r, int c) {
            return isValid(r, c) && cells[r][c] == '.';
        }

        int getRows() { return rows; }
        int getCols() { return cols; }
    }

    public void solve() {
        int n = reader.nextInt();
        int m = reader.nextInt();

        Grid grid = new Grid(n, m);
        for (int i = 0; i < n; i++) {
            String line = reader.next();
            for (int j = 0; j < m; j++) {
                grid.setCell(i, j, line.charAt(j));
            }
        }

        Point start = new Point(reader.nextInt() - 1, reader.nextInt() - 1);
        Point end = new Point(reader.nextInt() - 1, reader.nextInt() - 1);

        if (canConnect(grid, start, end)) {
            writer.println("YES");
        } else {
            writer.println("NO");
        }
    }

    private boolean canConnect(Grid grid, Point start, Point end) {
        // Case 1: Points are identical
        if (start.equals(end)) {
            return countDotNeighbors(grid, end) >= 1;
        }

        // Case 2: Points are adjacent
        if (isAdjacent(start, end)) {
            if (grid.getCell(end.r, end.c) == 'X') {
                return true;
            }
            return countDotNeighbors(grid, end) >= 1;
        }

        // Case 3: Path exists through '.' cells
        if (hasPathViaDots(grid, start, end)) {
            if (grid.getCell(end.r, end.c) == 'X') {
                return true;
            }
            return countDotNeighbors(grid, end) >= 2;
        }

        return false;
    }

    private boolean isAdjacent(Point p1, Point p2) {
        return Math.abs(p1.r - p2.r) + Math.abs(p1.c - p2.c) == 1;
    }

    private int countDotNeighbors(Grid grid, Point target) {
        int count = 0;
        for (int[] dir : DIRECTIONS) {
            int nr = target.r + dir[0];
            int nc = target.c + dir[1];
            if (grid.isDot(nr, nc)) {
                count++;
            }
        }
        return count;
    }

    private boolean hasPathViaDots(Grid grid, Point start, Point end) {
        Queue<Point> queue = new ArrayDeque<>();
        queue.add(start);

        boolean[][] visited = new boolean[grid.getRows()][grid.getCols()];
        visited[start.r][start.c] = true;

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            for (int[] dir : DIRECTIONS) {
                int nr = current.r + dir[0];
                int nc = current.c + dir[1];

                if (!grid.isValid(nr, nc)) continue;

                Point neighbor = new Point(nr, nc);
                if (neighbor.equals(end)) {
                    return true;
                }

                if (grid.isDot(nr, nc) && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    queue.add(neighbor);
                }
            }
        }
        return false;
    }

    public void run() {
        try {
            solve();
        } finally {
            writer.close();
        }
    }

    public static void main(String[] args) {
        new GridConnectivitySolver().run();
    }

    /**
     * Fast I/O utility class.
     */
    private static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
