import java.util.Deque;
import java.util.StringTokenizer;

/**
 * Solution for the IceCave problem.
 * Determines if a path exists to a target cell based on specific movement and exit rules.
 */
public class IceCave {

    public static void main(String[] args) {
        InputReader reader = new InputReader(System.in);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            // Convert 1-based input to 0-based coordinates
            Coordinate start = new Coordinate(reader.nextInt() - 1, reader.nextInt() - 1);
            Coordinate target = new Coordinate(reader.nextInt() - 1, reader.nextInt() - 1);

            IceCaveSolver solver = new IceCaveSolver(grid, start, target);
            if (solver.solve()) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        } catch (Exception e) {
            // In competitive programming context, we typically assume valid input 
            // or handle errors gracefully.
        }
    }

    /**
     * Represents a point in the 2D grid.
     */
    static class Coordinate {
        final int row;
        final int col;

        Coordinate(int row, int col) {
            this.row = row;
            this.col = col;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Coordinate)) return false;
            Coordinate that = (Coordinate) o;
            return row == that.row && col == that.col;
        }

        @Override
        public int hashCode() {
            return 31 * row + col;
        }
    }

    /**
     * Handles the logic for navigating the ice cave.
     */
    static class IceCaveSolver {
        private static final int[][] DIRECTIONS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

        private final char[][] grid;
        private final int rows;
        private final int cols;
        private final Coordinate start;
        private final Coordinate target;
        private boolean[][] visited;

        public IceCaveSolver(char[][] grid, Coordinate start, Coordinate target) {
            this.grid = grid;
            this.rows = grid.length;
            this.cols = grid[0].length;
            this.start = start;
            this.target = target;
            this.visited = new boolean[rows][cols];
        }

        /**
         * Orchestrates the BFS and evaluates the winning condition.
         */
        public boolean solve() {
            performBFS();

            int reachableNeighborCount = countReachableNeighbors(target);

            if (grid[target.row][target.col] == 'X') {
                // If target is 'X', we need at least one reachable neighbor or the start point
                return reachableNeighborCount >= 1;
            } else {
                // If target is '.', it must be reachable via BFS and have at least 2 ways to exit/arrive
                return visited[target.row][target.col] && reachableNeighborCount >= 2;
            }
        }

        /**
         * standard BFS to find all reachable '.' cells.
         */
        private void performBFS() {
            Deque<Coordinate> queue = new ArrayDeque<>();

            if (isValid(start.row, start.col) && grid[start.row][start.col] == '.') {
                queue.add(start);
                visited[start.row][start.col] = true;
            } else if (start.equals(target)) {
                // Edge case where start is the target (even if start is not '.')
                visited[start.row][start.col] = true;
            }

            while (!queue.isEmpty()) {
                Coordinate current = queue.poll();

                for (int[] dir : DIRECTIONS) {
                    int nextRow = current.row + dir[0];
                    int nextCol = current.col + dir[1];

                    if (isValid(nextRow, nextCol) && grid[nextRow][nextCol] == '.' && !visited[nextRow][nextCol]) {
                        visited[nextRow][nextCol] = true;
                        queue.add(new Coordinate(nextRow, nextCol));
                    }
                }
            }
        }

        /**
         * Counts neighbors of the target that are either reachable '.' cells or the start point.
         * Note: This replicates the original logic where the start point might be double-counted
         * if it is also a visited '.' cell.
         */
        private int countReachableNeighbors(Coordinate target) {
            int count = 0;
            for (int[] dir : DIRECTIONS) {
                int nr = target.row + dir[0];
                int nc = target.col + dir[1];

                if (isValid(nr, nc)) {
                    if (grid[nr][nc] == '.' && visited[nr][nc]) {
                        count++;
                    }
                    if (nr == start.row && nc == start.col) {
                        count++;
                    }
                }
            }
            return count;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

