/**
 * Handles the core logic of determining connectivity in a grid.
 */
class GridConnectivitySolver {

    private static final char WALKABLE = '.';
    private static final char OBSTACLE = 'X';

    public void solve(FastReader in, FastWriter out) throws IOException {
        int rows = in.nextInt();
        int cols = in.nextInt();
        char[][] grid = in.readGrid(rows, cols);

        // Convert 1-based input to 0-based coordinates
        int startRow = in.nextInt() - 1;
        int startCol = in.nextInt() - 1;
        int endRow = in.nextInt() - 1;
        int endCol = in.nextInt() - 1;

        boolean endWasObstacle = (grid[endRow][endCol] == OBSTACLE);

        // The problem treats start and end points as walkable for pathing
        grid[startRow][startCol] = WALKABLE;
        grid[endRow][endCol] = WALKABLE;

        DisjointSetUnion dsu = new DisjointSetUnion(rows * cols);
        buildConnectivity(grid, rows, cols, dsu);

        if (startRow == endRow && startCol == endCol) {
            int neighbors = countWalkableNeighbors(grid, rows, cols, endRow, endCol);
            out.println(neighbors >= 1 ? "YES" : "NO");
            return;
        }

        boolean isConnected = dsu.isConnected(
            flatten(startRow, startCol, cols), 
            flatten(endRow, endCol, cols)
        );

        if (endWasObstacle) {
            // If target was an obstacle, we only care if it's now connected to start
            out.println(isConnected ? "YES" : "NO");
        } else {
            // If target was walkable, it must be connected AND have at least 2 neighbors 
            // (likely to satisfy a 'pass-through' or 'entry-exit' requirement)
            int neighbors = countWalkableNeighbors(grid, rows, cols, endRow, endCol);
            out.println(isConnected && neighbors >= 2 ? "YES" : "NO");
        }
    }

    private void buildConnectivity(char[][] grid, int rows, int cols, DisjointSetUnion dsu) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] != WALKABLE) continue;

                // Check right neighbor
                if (c + 1 < cols && grid[r][c + 1] == WALKABLE) {
                    dsu.union(flatten(r, c, cols), flatten(r, c + 1, cols));
                }
                // Check bottom neighbor
                if (r + 1 < rows && grid[r + 1][c] == WALKABLE) {
                    dsu.union(flatten(r, c, cols), flatten(r + 1, c, cols));
                }
            }
        }
    }

    private int countWalkableNeighbors(char[][] grid, int rows, int cols, int r, int c) {
        int count = 0;
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int i = 0; i < 4; i++) {
            int nr = r + dr[i];
            int nc = c + dc[i];
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == WALKABLE) {
                count++;
            }
        }
        return count;
    }

    private int flatten(int r, int c, int cols) {
        return r * cols + c;
    }
}

/**
 * Disjoint Set Union (DSU) with Path Compression and Union by Rank.
 */
class DisjointSetUnion {
    private final int[] parent;
    private final int[] rank;

    public DisjointSetUnion(int size) {
        parent = new int[size];
        rank = new int[size];
        for (int i = 0; i < size; i++) {
            parent[i] = i;
        }
    }

    public int find(int i) {
        if (parent[i] == i) {
            return i;
        }
        return parent[i] = find(parent[i]); // Path compression
    }

    public void union(int i, int j) {
        int rootI = find(i);
        int rootJ = find(j);
        if (rootI != rootJ) {
            // Union by rank
            if (rank[rootI] < rank[rootJ]) {
                parent[rootI] = rootJ;
            } else if (rank[rootI] > rank[rootJ]) {
                parent[rootJ] = rootI;
            } else {
                parent[rootI] = rootJ;
                rank[rootJ]++;
            }
        }
    }

    public boolean isConnected(int i, int j) {
        return find(i) == find(j);
    }
}

