import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.*;

/**
 * A refactored solution to the grid reachability problem.
 * The problem determines if a target can be reached and if the target 
 * satisfies specific structural conditions within the grid.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            char[][] gridData = reader.readGrid(rows, cols);
            Grid grid = new Grid(rows, cols, gridData);

            Point start = reader.nextPoint();
            Point target = reader.nextPoint();

            ProblemSolver solver = new ProblemSolver(grid);
            String result = solver.solve(start, target);

            writer.println(result);
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Represents a coordinate in the grid.
     */
    record Point(int r, int c) {
        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            Point point = (Point) o;
            return r == point.r && c == point.c;
        }
    }

    /**
     * Manages the grid boundaries and obstacle information.
     */
    static class Grid {
        private final int rows;
        private final int cols;
        private final boolean[][] isObstacle;

        public Grid(int rows, int cols, char[][] gridData) {
            this.rows = rows;
            this.cols = cols;
            this.isObstacle = new boolean[rows][cols];
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    this.isObstacle[i][j] = (gridData[i][j] == 'X');
                }
            }
        }

        public int getRows() { return rows; }
        public int getCols() { return cols; }

        public boolean isObstacle(int r, int c) {
            return isObstacle[r][c];
        }

        public boolean isObstacle(Point p) {
            return isObstacle(p.r(), p.c());
        }

        public boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        public boolean isValid(Point p) {
            return isValid(p.r(), p.c());
        }

        public List<Point> getNeighbors(Point p) {
            List<Point> neighbors = new ArrayList<>();
            int[] dr = {-1, 1, 0, 0};
            int[] dc = {0, 0, -1, 1};

            for (int i = 0; i < 4; i++) {
                int nr = p.r() + dr[i];
                int nc = p.c() + dc[i];
                if (isValid(nr, nc)) {
                    neighbors.add(new Point(nr, nc));
                }
            }
            return neighbors;
        }
    }

    /**
     * Handles pathfinding logic using BFS.
     */
    static class Pathfinder {
        private final Grid grid;

        public Pathfinder(Grid grid) {
            this.grid = grid;
        }

        /**
         * Checks reachability based on the specific rules:
         * 1. The start cell can be an obstacle.
         * 2. Intermediate cells must NOT be obstacles.
         * 3. The target cell can be an obstacle.
         * 4. If start == target, it is reachable only if a path exists out and back.
         */
        public boolean canReach(Point start, Point target) {
            if (!grid.isValid(start) || !grid.isValid(target)) return false;

            Deque<Point> queue = new ArrayDeque<>();
            boolean[][] visited = new boolean[grid.getRows()][grid.getCols()];

            visited[start.r()][start.c()] = true;
            queue.add(start);

            while (!queue.isEmpty()) {
                Point current = queue.poll();

                for (Point neighbor : grid.getNeighbors(current)) {
                    // Rule: Target reached (even if target is an obstacle)
                    if (neighbor.equals(target)) {
                        return true;
                    }

                    // Rule: Only move to non-obstacle cells
                    if (!visited[neighbor.r()][neighbor.c()] && !grid.isObstacle(neighbor)) {
                        visited[neighbor.r()][neighbor.c()] = true;
                        queue.add(neighbor);
                    }
                }
            }

            return false;
        }
    }

    /**
     * Encapsulates the core business logic of the problem.
     */
    static class ProblemSolver {
        private final Grid grid;
        private final Pathfinder pathfinder;

        public ProblemSolver(Grid grid) {
            this.grid = grid;
            this.pathfinder = new Pathfinder(grid);
        }

        public String solve(Point start, Point target) {
            boolean reachable = pathfinder.canReach(start, target);

            if (!reachable) {
                return "NO";
            }

            boolean targetIsObstacle = grid.isObstacle(target);
            boolean startIsTarget = start.equals(target);

            if (targetIsObstacle || startIsTarget) {
                return "YES";
            }

            // Check if target is a "leaf" node in the traversable graph
            int nonObstacleNeighborsCount = 0;
            for (Point neighbor : grid.getNeighbors(target)) {
                if (!grid.isObstacle(neighbor) || neighbor.equals(start)) {
                    nonObstacleNeighborsCount++;
                }
            }

            return (nonObstacleNeighborsCount > 1) ? "YES" : "NO";
        }
    }

    /**
     * Efficient utility for reading input.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(java.io.InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public char[][] readGrid(int rows, int cols) throws IOException {
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = reader.readLine();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }
            return grid;
        }

        public Point nextPoint() throws IOException {
            // Points are provided as 1-indexed in the input
            int r = nextInt() - 1;
            int c = nextInt() - 1;
            return new Point(r, c);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the Grid Pathfinding problem.
 * Uses BFS for optimal pathfinding on unweighted grids.
 */
public class Problem_540_C {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            GridSolver solver = new GridSolver(reader);
            solver.solve(out);
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.close();
        }
    }

    static class GridSolver {
        private final FastReader reader;
        private final int rows;
        private final int cols;
        private final char[][] grid;

        // Direction vectors for moving Up, Down, Left, Right
        private static final int[] DR = {-1, 1, 0, 0};
        private static final int[] DC = {0, 0, -1, 1};

        public GridSolver(FastReader reader) {
            this.reader = reader;
            this.rows = reader.nextInt();
            this.cols = reader.nextInt();
            this.grid = new char[rows][];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }
        }

        public void solve(PrintWriter out) {
            int startR = reader.nextInt() - 1;
            int startC = reader.nextInt() - 1;
            int targetR = reader.nextInt() - 1;
            int targetC = reader.nextInt() - 1;

            int[] parent = bfs(startR, startC, targetR, targetC);

            if (parent[targetR * cols + targetC] == -1 && (startR != targetR || startC != targetC)) {
                out.println("NO");
                return;
            }

            boolean targetWasObstacle = grid[targetR][targetC] == 'X';

            // Reconstruct path and mark nodes as obstacles ('X')
            // The original logic marks all nodes in the path (excluding the start) as 'X'
            int currentIdx = targetR * cols + targetC;
            int startIdx = startR * cols + startC;

            while (currentIdx != startIdx) {
                int r = currentIdx / cols;
                int c = currentIdx % cols;
                grid[r][c] = 'X';
                currentIdx = parent[currentIdx];
            }

            // Count adjacent empty cells ('.') around the target cell
            int adjacentEmptyCells = countAdjacentEmpty(targetR, targetC);

            // Condition based on original program logic:
            // 1. Target has an adjacent empty cell
            // OR 2. Target was originally an obstacle and we moved into it from elsewhere
            boolean canExitTarget = adjacentEmptyCells > 0;
            boolean targetWasAccessibleObstacle = targetWasObstacle && (startR != targetR || startC != targetC);

            if (canExitTarget || targetWasAccessibleObstacle) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        }

        /**
         * Performs Breadth-First Search to find the shortest path in an unweighted grid.
         * Returns a parent array for path reconstruction.
         */
        private int[] bfs(int startR, int startC, int targetR, int targetC) {
            int[] parent = new int[rows * cols];
            Arrays.fill(parent, -1);
            boolean[] visited = new boolean[rows * cols];

            Queue<Integer> queue = new LinkedList<>();
            int startIdx = startR * cols + startC;
            queue.add(startIdx);
            visited[startIdx] = true;

            while (!queue.isEmpty()) {
                int currIdx = queue.poll();
                int r = currIdx / cols;
                int c = currIdx % cols;

                if (r == targetR && c == targetC) break;

                for (int i = 0; i < 4; i++) {
                    int nr = r + DR[i];
                    int nc = c + DC[i];
                    int nIdx = nr * cols + nc;

                    if (isValid(nr, nc)) {
                        // A neighbor is traversable if it's not an obstacle 'X'
                        // OR if it is the specific target cell (which we can 'open')
                        boolean isTarget = (nr == targetR && nc == targetC);
                        if (!visited[nIdx] && (grid[nr][nc] != 'X' || isTarget)) {
                            visited[nIdx] = true;
                            parent[nIdx] = currIdx;
                            queue.add(nIdx);
                        }
                    }
                }
            }
            return parent;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        private int countAdjacentEmpty(int r, int c) {
            int count = 0;
            for (int i = 0; i < 4; i++) {
                int nr = r + DR[i];
                int nc = c + DC[i];
                if (isValid(nr, nc) && grid[nr][nc] == '.') {
                    count++;
                }
            }
            return count;
        }
    }

    /**
     * Efficient utility class for reading input.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * A program to determine if a target cell is reachable from a start cell 
 * based on specific grid traversal rules.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader();

        int rows = reader.nextInt();
        int cols = reader.nextInt();

        if (rows <= 0 || cols <= 0) {
            System.out.println("NO");
            return;
        }

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = reader.next().toCharArray();
        }

        // Input coordinates are 1-indexed; convert to 0-indexed
        int targetRow = reader.nextInt() - 1;
        int targetCol = reader.nextInt() - 1;
        int startRow = reader.nextInt() - 1;
        int startCol = reader.nextInt() - 1;

        GridPathfinder pathfinder = new GridPathfinder(grid, targetRow, targetCol);
        boolean isPossible = pathfinder.canReachTarget(startRow, startCol);

        System.out.println(isPossible ? "YES" : "NO");
    }

    /**
     * Logic engine for traversing the grid and checking connectivity.
     */
    static class GridPathfinder {
        private static final int[][] DIRECTIONS = {
            {1, 0}, {-1, 0}, {0, 1}, {0, -1}
        };

        private final char[][] grid;
        private final int targetRow;
        private final int targetCol;
        private final int rows;
        private final int cols;
        private final boolean[][] visited;
        private boolean found = false;

        public GridPathfinder(char[][] grid, int targetRow, int targetCol) {
            this.grid = grid;
            this.targetRow = targetRow;
            this.targetCol = targetCol;
            this.rows = grid.length;
            this.cols = grid[0].length;
            this.visited = new boolean[rows][cols];
        }

        /**
         * Determines if the target can be reached from the starting position 
         * following the movement rules.
         */
        public boolean canReachTarget(int startRow, int startCol) {
            if (isOutOfBounds(startRow, startCol)) {
                return false;
            }

            if (grid[startRow][startCol] == 'X') {
                // Rule: If start is 'X', explore all immediate neighbors
                exploreNeighbors(startRow, startCol);
            } else {
                // Rule: If start is '.', movement depends on surrounding '.' cells
                int dotNeighbors = countDotNeighbors(startRow, startCol);
                if (dotNeighbors >= 2) {
                    exploreNeighbors(startRow, startCol);
                } else if (dotNeighbors == 1) {
                    // Special case: Check if the target is immediately adjacent
                    if (isAdjacent(startRow, startCol, targetRow, targetCol)) {
                        found = true;
                    }
                }
            }
            return found;
        }

        private void exploreNeighbors(int r, int c) {
            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (isInBounds(nr, nc)) {
                    dfs(nr, nc);
                }
            }
        }

        /**
         * Standard DFS to traverse '.' cells and stop at 'X' cells.
         */
        private void dfs(int r, int c) {
            if (visited[r][c] || found) {
                return;
            }

            visited[r][c] = true;

            // If we hit an 'X', it's only a success if it's our target
            if (grid[r][c] == 'X') {
                if (r == targetRow && c == targetCol) {
                    found = true;
                }
                return;
            }

            // Continue exploration through empty '.' cells
            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (isInBounds(nr, nc)) {
                    dfs(nr, nc);
                }
            }
        }

        private int countDotNeighbors(int r, int c) {
            int count = 0;
            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (isInBounds(nr, nc) && grid[nr][nc] == '.') {
                    count++;
                }
            }
            return count;
        }

        private boolean isAdjacent(int r1, int c1, int r2, int c2) {
            return Math.abs(r1 - r2) + Math.abs(c1 - c2) == 1;
        }

        private boolean isInBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        private boolean isOutOfBounds(int r, int c) {
            return r < 0 || r >= rows || c < 0 || c >= cols;
        }
    }

    /**
     * Utility class for efficient input reading.
     */
    static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

