/**
 * Represents a coordinate in the 2D grid.
 */
record Point(int row, int col) {}

/**
 * Handles the grid-based pathfinding logic.
 */
class GridPathSolver {
    private static final int[] ROW_OFFSETS = {-1, 0, 0, 1};
    private static final int[] COL_OFFSETS = {0, -1, 1, 0};

    /**
     * Executes the core logic of the problem.
     */
    public void solve(FastReader reader, PrintWriter writer) {
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = reader.next().toCharArray();
        }

        Point start = new Point(reader.nextInt() - 1, reader.nextInt() - 1);
        Point end = new Point(reader.nextInt() - 1, reader.nextInt() - 1);

        boolean endIsAdjacentToPath = performBfs(grid, rows, cols, start, end);

        if (!endIsAdjacentToPath) {
            writer.println("NO");
        } else {
            processResult(grid, rows, cols, start, end, writer);
        }
    }

    /**
     * Standard BFS to determine if the target 'end' point is adjacent to a reachable path.
     */
    private boolean performBfs(char[][] grid, int rows, int cols, Point start, Point end) {
        boolean[][] visited = new boolean[rows][cols];
        Queue<Point> queue = new LinkedList<>();

        queue.add(start);
        // Note: In the original logic, start is not marked visited immediately, 
        // but we mark it as we traverse to prevent infinite loops.

        boolean found = false;

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            for (int i = 0; i < 4; i++) {
                int neighborRow = current.row() + ROW_OFFSETS[i];
                int neighborCol = current.col() + COL_OFFSETS[i];

                // Check if this neighbor is our target destination
                if (neighborRow == end.row() && neighborCol == end.col()) {
                    found = true;
                }

                if (isWithinBounds(neighborRow, neighborCol, rows, cols) 
                        && !visited[neighborRow][neighborCol] 
                        && grid[neighborRow][neighborCol] != 'X') {

                    visited[neighborRow][neighborCol] = true;
                    queue.add(new Point(neighborRow, neighborCol));
                }
            }
        }
        return found;
    }

    /**
     * Applies the specific win conditions after reachability is determined.
     */
    private void processResult(char[][] grid, int rows, int cols, Point start, Point end, PrintWriter writer) {
        if (grid[end.row()][end.col()] == 'X') {
            // If the destination itself is a wall, the reachability check (being adjacent) is enough.
            writer.println("YES");
        } else {
            // If the destination is a path cell, check if it has at least two valid connection points.
            int validConnections = countValidConnections(grid, rows, cols, start, end);
            if (validConnections >= 2) {
                writer.println("YES");
            } else {
                writer.println("NO");
            }
        }
    }

    /**
     * Counts how many neighbors of the end point are either the start point or a traversable path ('.').
     */
    private int countValidConnections(char[][] grid, int rows, int cols, Point start, Point end) {
        int count = 0;
        for (int i = 0; i < 4; i++) {
            int nr = end.row() + ROW_OFFSETS[i];
            int nc = end.col() + COL_OFFSETS[i];

            if (nr == start.row() && nc == start.col()) {
                count++;
            } else if (isWithinBounds(nr, nc, rows, cols) && grid[nr][nc] == '.') {
                count++;
            }
        }
        return count;
    }

    private boolean isWithinBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

