import java.util.Scanner;

/**
 * GridPathfinder solves a grid traversal problem.
 * It determines if a target cell is reachable via a path of empty cells 
 * and evaluates specific connectivity requirements at the destination.
 */
public class GridPathfinder {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }

        // Read grid dimensions
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        // Initialize and populate the grid
        // 0 represents an empty cell (.), 1 represents an obstacle (X)
        int[][] grid = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            String rowString = scanner.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = (rowString.charAt(j) == 'X') ? 1 : 0;
            }
        }

        // Read 1-indexed start and end coordinates and convert to 0-indexed
        int startX = scanner.nextInt() - 1;
        int startY = scanner.nextInt() - 1;
        int endX = scanner.nextInt() - 1;
        int endY = scanner.nextInt() - 1;

        PathSolver solver = new PathSolver(rows, cols, grid, startX, startY, endX, endY);
        solver.solve();

        scanner.close();
    }
}

class PathSolver {
    private final int rows;
    private final int cols;
    private final int[][] grid;
    private final int startX, startY, endX, endY;
    private final boolean[][] visited;

    // Directional vectors for moving Up, Down, Left, Right
    private static final int[] DX = {-1, 1, 0, 0};
    private static final int[] DY = {0, 0, -1, 1};

    public PathSolver(int rows, int cols, int[][] grid, int startX, int startY, int endX, int endY) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.startX = startX;
        this.startY = startY;
        this.endX = endX;
        this.endY = endY;
        this.visited = new boolean[rows][cols];
    }

    /**
     * Orchestrates the DFS traversal and prints the final result.
     */
    public void solve() {
        if (isWithinBounds(startX, startY)) {
            performDFS(startX, startY);
        }

        System.out.println(calculateResult() ? "YES" : "NO");
    }

    /**
     * Performs a Depth First Search to explore reachable cells.
     */
    private void performDFS(int r, int c) {
        visited[r][c] = true;

        for (int i = 0; i < 4; i++) {
            int nextR = r + DX[i];
            int nextC = c + DY[i];

            if (isWithinBounds(nextR, nextC) && !visited[nextR][nextC]) {
                // Rule: Can move into an empty cell (0) 
                // OR can move into the target cell even if it is an obstacle (1)
                if (grid[nextR][nextC] == 0 || (nextR == endX && nextC == endY)) {
                    performDFS(nextR, nextC);
                }
            }
        }
    }

    /**
     * Evaluates the pathfinding conditions based on the distance 
     * between start and end and the target's properties.
     */
    private boolean calculateResult() {
        // If the target cell was not reached during DFS
        if (!isWithinBounds(endX, endY) || !visited[endX][endY]) {
            return false;
        }

        int emptyNeighbors = countEmptyNeighbors(endX, endY);
        boolean isTargetObstacle = (grid[endX][endY] == 1);
        boolean isStartSameAsEnd = (startX == endX && startY == endY);
        boolean isStartAdjacentToEnd = (Math.abs(startX - endX) + Math.abs(startY - endY) == 1);

        if (isStartSameAsEnd) {
            return emptyNeighbors >= 1;
        } 

        if (isStartAdjacentToEnd) {
            return emptyNeighbors >= 1 || isTargetObstacle;
        }

        // General case for non-adjacent cells
        return emptyNeighbors >= 2 || isTargetObstacle;
    }

    private int countEmptyNeighbors(int r, int c) {
        int count = 0;
        for (int i = 0; i < 4; i++) {
            int nextR = r + DX[i];
            int nextC = c + DY[i];
            if (isWithinBounds(nextR, nextC) && grid[nextR][nextC] == 0) {
                count++;
            }
        }
        return count;
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

