/**
 * IceCave determines if there is a traversable path from a starting coordinate 
 * to a target coordinate within a grid of paths ('.') and obstacles ('X').
 */
public class IceCave {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        try {
            // Read grid dimensions
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            // Read the grid layout
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = scanner.next().toCharArray();
            }

            // Read coordinates (converting from 1-based to 0-based indexing)
            int startRow = scanner.nextInt() - 1;
            int startCol = scanner.nextInt() - 1;
            int targetRow = scanner.nextInt() - 1;
            int targetCol = scanner.nextInt() - 1;

            // Execute solver
            IceCaveSolver solver = new IceCaveSolver(grid, rows, cols);
            boolean isPathFound = solver.canReach(startRow, startCol, targetRow, targetCol);

            System.out.println(isPathFound ? "YES" : "NO");

        } catch (NoSuchElementException e) {
            // Handle unexpected end of input
        } finally {
            scanner.close();
        }
    }

    /**
     * Logic provider for the IceCave problem.
     */
    static class IceCaveSolver {
        private final char[][] grid;
        private final int rows;
        private final int cols;

        // Direction vectors for movement: Up, Down, Left, Right
        private static final int[] ROW_DIRECTIONS = {-1, 1, 0, 0};
        private static final int[] COL_DIRECTIONS = {0, 0, -1, 1};

        public IceCaveSolver(char[][] grid, int rows, int cols) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
        }

        /**
         * Uses Breadth-First Search (BFS) to find if a path exists.
         * BFS is used to ensure memory stability (avoiding StackOverflow) 
         * and to handle large grid sizes efficiently.
         *
         * @param startR Starting row (0-indexed)
         * @param startC Starting column (0-indexed)
         * @param targetR Target row (0-indexed)
         * @param targetC Target column (0-indexed)
         * @return true if the target is reachable, false otherwise
         */
        public boolean canReach(int startR, int startC, int targetR, int targetC) {
            // If the start point is the target, we have already arrived
            if (startR == targetR && startC == targetC) {
                return true;
            }

            // Validate that the starting point is within the grid
            if (!isWithinBounds(startR, startC)) {
                return false;
            }

            boolean[][] visited = new boolean[rows][cols];
            Queue<GridPoint> queue = new ArrayDeque<>();

            // Initialize BFS
            queue.add(new GridPoint(startR, startC));
            visited[startR][startC] = true;

            while (!queue.isEmpty()) {
                GridPoint current = queue.poll();

                for (int i = 0; i < 4; i++) {
                    int nextR = current.row + ROW_DIRECTIONS[i];
                    int nextC = current.col + COL_DIRECTIONS[i];

                    if (isWithinBounds(nextR, nextC) && !visited[nextR][nextC]) {
                        // A cell is traversable if it is a path ('.') 
                        // OR if it is the target destination (even if marked 'X')
                        if (grid[nextR][nextC] == '.' || (nextR == targetR && nextC == targetC)) {
                            if (nextR == targetR && nextC == targetC) {
                                return true;
                            }
                            visited[nextR][nextC] = true;
                            queue.add(new GridPoint(nextR, nextC));
                        }
                    }
                }
            }

            return false;
        }

        private boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        /**
         * Simple immutable data carrier for coordinates.
         */
        private static class GridPoint {
            final int row;
            final int col;

            GridPoint(int row, int col) {
                this.row = row;
                this.col = col;
            }
        }
    }
}

