import java.util.*;

/**
 * A solver to determine connectivity and accessibility between two points in a grid.
 */
public class GridConnectivitySolver {

    private static final char BLOCKED = 'X';
    private static final char EMPTY = '.';

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final Coordinate source;
    private final Coordinate sink;

    public GridConnectivitySolver(int rows, int cols, char[][] grid, Coordinate source, Coordinate sink) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.source = source;
        this.sink = sink;
    }

    /**
     * Represents a point in the 2D grid.
     */
    public record Coordinate(int row, int col) {
        public boolean isAdjacent(Coordinate other) {
            return Math.abs(this.row - other.row) + Math.abs(this.col - other.col) == 1;
        }

        public boolean isValid(int maxRows, int maxCols) {
            return row >= 0 && row < maxRows && col >= 0 && col < maxCols;
        }
    }

    /**
     * Executes the core logic to determine if the connectivity requirement is met.
     * @return true if the connectivity condition is "YES", false otherwise.
     */
    public boolean solve() {
        if (source.equals(sink)) {
            return countEmptyNeighbors(sink) >= 1;
        }

        boolean sinkIsBlocked = isCellBlocked(sink);
        boolean sourceIsBlocked = isCellBlocked(source);
        int sinkEmptyNeighbors = countEmptyNeighbors(sink);

        if (source.isAdjacent(sink)) {
            if (sinkIsBlocked) return true;
            return sinkEmptyNeighbors >= 2 || (sinkEmptyNeighbors >= 1 && sourceIsBlocked);
        }

        // Case: Not adjacent
        if (hasPath(source, sink)) {
            return sinkIsBlocked || sinkEmptyNeighbors >= 2;
        }

        return false;
    }

    private boolean isCellBlocked(Coordinate coord) {
        return grid[coord.row()][coord.col()] == BLOCKED;
    }

    /**
     * Counts how many neighbors of a specific coordinate are empty ('.').
     */
    private int countEmptyNeighbors(Coordinate coord) {
        int count = 0;
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int i = 0; i < 4; i++) {
            int nr = coord.row() + dr[i];
            int nc = coord.col() + dc[i];

            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
                if (grid[nr][nc] == EMPTY) {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Uses BFS to determine if there is a path from start to end moving only through EMPTY cells.
     * Note: The end cell itself can be BLOCKED.
     */
    private boolean hasPath(Coordinate start, Coordinate end) {
        Deque<Coordinate> queue = new ArrayDeque<>();
        boolean[][] visited = new boolean[rows][cols];

        queue.add(start);
        visited[start.row()][start.col()] = true;

        int[] dr = {0, 0, -1, 1};
        int[] dc = {-1, 1, 0, 0};

        while (!queue.isEmpty()) {
            Coordinate current = queue.poll();

            if (current.equals(end)) {
                return true;
            }

            // If we are at a cell that is NOT the start and is BLOCKED, we cannot pass through it.
            if (!current.equals(start) && isCellBlocked(current)) {
                continue;
            }

            for (int i = 0; i < 4; i++) {
                int nr = current.row() + dr[i];
                int nc = current.col() + dc[i];
                Coordinate neighbor = new Coordinate(nr, nc);

                if (neighbor.isValid(rows, cols) && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    queue.add(neighbor);
                }
            }
        }
        return false;
    }

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            // Input is 1-indexed in the original problem description
            Coordinate source = new Coordinate(reader.nextInt() - 1, reader.nextInt() - 1);
            Coordinate sink = new Coordinate(reader.nextInt() - 1, reader.nextInt() - 1);

            GridConnectivitySolver solver = new GridConnectivitySolver(rows, cols, grid, source, sink);
            System.out.println(solver.solve() ? "YES" : "NO");

        } catch (Exception e) {
            // Handle or log appropriately
        }
    }

    /**
     * Efficient input reader for competitive programming style tasks.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

