/**
 * Represents a coordinate in the 2D grid.
 */
record Point(int x, int y) {}

/**
 * Represents the Ice Cave map and its constraints.
 */
class IceCaveMap {
    private final int width;
    private final int height;
    private final boolean[][] obstacles;

    public IceCaveMap(int width, int height, boolean[][] obstacles) {
        this.width = width;
        this.height = height;
        this.obstacles = obstacles;
    }

    public int getWidth() {
        return width;
    }

    public int getHeight() {
        return height;
    }

    public boolean isOutOfBounds(int x, int y) {
        return x < 0 || y < 0 || x >= width || y >= height;
    }

    public boolean isObstacle(int x, int y) {
        return obstacles[x][y];
    }

    /**
     * Checks if a cell is "available" (walkable).
     * Per original logic: a cell is available if it is within bounds 
     * AND (it is not an obstacle OR it is the starting cell).
     */
    public boolean isAvailable(int x, int y, Point start) {
        if (isOutOfBounds(x, y)) {
            return false;
        }
        boolean isStart = (x == start.x() && y == start.y());
        return !isObstacle(x, y) || isStart;
    }
}

/**
 * Contains the logic to solve the pathfinding problem.
 */
class IceCaveSolver {
    private final IceCaveMap map;
    private final Point start;
    private final Point target;

    public IceCaveSolver(IceCaveMap map, Point start, Point target) {
        this.map = map;
        this.start = start;
        this.target = target;
    }

    public boolean solve() {
        if (isTargetIsolated()) {
            return false;
        }
        return performBFS();
    }

    /**
     * Replicates the original 'adj' check: 
     * If the target is not an obstacle but has 1 or 0 walkable neighbors, it's unreachable.
     */
    private boolean isTargetIsolated() {
        if (map.isObstacle(target.x(), target.y())) {
            return false;
        }

        int walkableNeighbors = 0;
        int[] dx = {1, -1, 0, 0};
        int[] dy = {0, 0, 1, -1};

        for (int i = 0; i < 4; i++) {
            if (map.isAvailable(target.x() + dx[i], target.y() + dy[i], start)) {
                walkableNeighbors++;
            }
        }

        return walkableNeighbors <= 1;
    }

    private boolean performBFS() {
        Queue<Point> queue = new ArrayDeque<>();
        boolean[][] visited = new boolean[map.getWidth()][map.getHeight()];

        // Initialize BFS with neighbors of the start point, 
        // matching the original implementation's behavior.
        int[] dx = {1, -1, 0, 0};
        int[] dy = {0, 0, 1, -1};

        for (int i = 0; i < 4; i++) {
            int nx = start.x() + dx[i];
            int ny = start.y() + dy[i];
            if (map.isAvailable(nx, ny, start)) {
                Point next = new Point(nx, ny);
                if (next.equals(target)) return true;

                if (!visited[nx][ny]) {
                    visited[nx][ny] = true;
                    queue.add(next);
                }
            }
        }

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            if (current.equals(target)) {
                return true;
            }

            for (int i = 0; i < 4; i++) {
                int nx = current.x() + dx[i];
                int ny = current.y() + dy[i];

                if (!map.isOutOfBounds(nx, ny) 
                        && !map.isObstacle(nx, ny) 
                        && !visited[nx][ny]) {

                    visited[nx][ny] = true;
                    queue.add(new Point(nx, ny));
                }
            }
        }

        return false;
    }
}

