}

import java.util.*;

/**
 * A refactored grid navigation program that finds paths in a 2D field
 * and applies specific business rules to determine the result.
 */
public class GridNavigator {

    private static final int[] ROW_DIRECTIONS = {-1, 1, 0, 0};
    private static final int[] COL_DIRECTIONS = {0, 0, -1, 1};
    private static final int UNVISITED = Integer.MAX_VALUE;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        // Input parsing
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        scanner.nextLine(); // Consume newline

        char[][] field = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.nextLine();
            field[i] = line.toCharArray();
        }

        int startRow = scanner.nextInt() - 1;
        int startCol = scanner.nextInt() - 1;
        int endRow = scanner.nextInt() - 1;
        int endCol = scanner.nextInt() - 1;

        // Execution
        GridNavigator navigator = new GridNavigator();
        String result = navigator.solve(rows, cols, field, startRow, startCol, endRow, endCol);

        // Output
        System.out.println(result);
    }

    /**
     * Orchestrates the pathfinding and rule evaluation.
     */
    public String solve(int rows, int cols, char[][] field, int startR, int startC, int endR, int endC) {
        Point start = new Point(startR, startC);
        Point end = new Point(endR, endC);

        int[][] distances = performBFS(rows, cols, field, start, end);
        int targetDistance = distances[endR][endC];
        boolean isReached = (targetDistance != UNVISITED);

        if (!isReached) {
            return "NO";
        }

        int dotNeighborCount = countDotNeighbors(rows, cols, field, endR, endC);
        return evaluateBusinessRules(field[endR][endC], targetDistance, dotNeighborCount, start, end);
    }

    /**
     * Performs Breadth-First Search to find the shortest distance to the target.
     * Logic follows the original rule: you can move to '.' cells or the target cell itself.
     */
    private int[][] performBFS(int rows, int cols, char[][] field, Point start, Point end) {
        int[][] distances = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            Arrays.fill(distances[i], UNVISITED);
        }

        Queue<Point> queue = new ArrayDeque<>();
        distances[start.row][start.col] = 0;
        queue.add(start);

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            // If we've popped the target, the shortest path is found.
            if (current.equals(end)) {
                break;
            }

            for (int i = 0; i < 4; i++) {
                int nr = current.row + ROW_DIRECTIONS[i];
                int nc = current.col + COL_DIRECTIONS[i];

                if (isWithinBounds(rows, cols, nr, nc)) {
                    Point neighbor = new Point(nr, nc);
                    boolean isTarget = neighbor.equals(end);
                    boolean isDot = field[nr][nc] == '.';

                    // Rule: Path can be formed through dots or by reaching the target cell.
                    if ((isDot || isTarget) && distances[nr][nc] == UNVISITED) {
                        distances[nr][nc] = distances[current.row][current.col] + 1;
                        queue.add(neighbor);
                    }
                }
            }
        }
        return distances;
    }

    private boolean isWithinBounds(int rows, int cols, int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Counts adjacent '.' cells for a given coordinate.
     */
    private int countDotNeighbors(int rows, int cols, char[][] field, int r, int c) {
        int count = 0;
        for (int i = 0; i < 4; i++) {
            int nr = r + ROW_DIRECTIONS[i];
            int nc = c + COL_DIRECTIONS[i];
            if (isWithinBounds(rows, cols, nr, nc) && field[nr][nc] == '.') {
                count++;
            }
        }
        return count;
    }

    /**
     * Encapsulates the specific/idiosyncratic rules of the original program 
     * to determine if the result is "YES" or "NO".
     */
    private String evaluateBusinessRules(char targetChar, int dist, int dotCount, Point start, Point end) {
        if (targetChar == 'X') {
            // If target is an obstacle: NO if no adjacent dots exist and we are already at the destination.
            return (dotCount == 0 && start.equals(end)) ? "NO" : "YES";
        } else {
            // If target is a path cell:
            if (dist == 1 && dotCount != 0) {
                return "YES";
            }
            // If target is a path cell with 0 or 1 dot neighbors, return NO.
            if (dotCount <= 1) {
                return "NO";
            }
            return "YES";
        }
    }

    /**
     * Immutable helper class representing a coordinate in the grid.
     */
    private static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Point)) return false;
            Point point = (Point) o;
            return row == point.row && col == point.col;
        }

        @Override
        public int hashCode() {
            return Objects.hash(row, col);
        }
    }
}

