        try {
            // Read grid dimensions
            String nInput = reader.next();
            if (nInput == null) return;

            int rows = Integer.parseInt(nInput);
            int cols = reader.nextInt();

            // Read grid layout
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            // Read start and end coordinates (converting 1-based to 0-based indexing)
            int startRow = reader.nextInt() - 1;
            int startCol = reader.nextInt() - 1;
            int endRow = reader.nextInt() - 1;
            int endCol = reader.nextInt() - 1;

            // Execute pathfinding logic
            GridPathfinder pathfinder = new GridPathfinder(rows, cols, grid);
            boolean isSuccessful = pathfinder.solve(startRow, startCol, endRow, endCol);

            out.println(isSuccessful ? "YES" : "NO");

        } catch (Exception e) {
            // In a production environment, replace with a proper logging framework
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Logic engine for grid traversal and validation.
     */
    static class GridPathfinder {
        private static final int[] ROW_OFFSETS = {-1, 1, 0, 0};
        private static final int[] COL_OFFSETS = {0, 0, -1, 1};

        private final int rows;
        private final int cols;
        private final char[][] grid;

        public GridPathfinder(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
        }

        /**
         * Determines if the target is reachable while satisfying the neighbor constraint.
         */
        public boolean solve(int startR, int startC, int endR, int endC) {
            // 1. Constraint Check: If the target is an empty cell ('.'), 
            // it must not be a 'dead end' unless it is adjacent to the start.
            if (grid[endR][endC] == '.') {
                if (!isTargetValid(startR, startC, endR, endC)) {
                    return false;
                }
            }

            // 2. Reachability Check: Standard BFS to find if a path exists.
            return isReachable(startR, startC, endR, endC);
        }

        /**
         * Validates if the target cell satisfies the connectivity requirement.
         */
        private boolean isTargetValid(int startR, int startC, int endR, int endC) {
            int emptyNeighborCount = 0;
            for (int i = 0; i < 4; i++) {
                int nr = endR + ROW_OFFSETS[i];
                int nc = endC + COL_OFFSETS[i];
                if (isWithinBounds(nr, nc) && grid[nr][nc] == '.') {
                    emptyNeighborCount++;
                }
            }

            boolean isAdjacentToStart = Math.abs(startR - endR) + Math.abs(startC - endC) == 1;
            return emptyNeighborCount > 1 || (emptyNeighborCount == 1 && isAdjacentToStart);
        }

        /**
         * Performs a Breadth-First Search to check if the end point can be reached.
         */
        private boolean isReachable(int startR, int startC, int endR, int endC) {
            // Base case: already at the destination
            if (startR == endR && startC == endC) {
                return true;
            }

            boolean[][] visited = new boolean[rows][cols];
            Deque<Point> queue = new ArrayDeque<>();

            // The original algorithm's specific BFS behavior:
            // 1. Start at the initial point.
            // 2. Mark neighbors as visited.
            // 3. Only add a neighbor to the queue if it is an empty cell ('.').
            queue.add(new Point(startR, startC));

            while (!queue.isEmpty()) {
                Point current = queue.poll();

                for (int i = 0; i < 4; i++) {
                    int nr = current.r + ROW_OFFSETS[i];
                    int nc = current.c + COL_OFFSETS[i];

                    if (isWithinBounds(nr, nc) && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        // Only allow traversal through empty cells
                        if (grid[nr][nc] == '.') {
                            queue.add(new Point(nr, nc));
                        }
                    }
                }
            }

            return visited[endR][endC];
        }

        private boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        /**
         * Simple data carrier for grid coordinates.
         */
        private static class Point {
            final int r, c;
            Point(int r, int c) {
                this.r = r;
                this.c = c;
            }
        }
    }

    /**
     * High-performance input reader for large datasets.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;

/**
 * A utility to determine if a path exists between two points in a grid.
 */
public class GridPathfinder {

    private record Coordinate(int row, int col) {}

    private final int rows;
    private final int cols;
    private final boolean[][] traversable;

    public GridPathfinder(int rows, int cols, String[] gridLines) {
        this.rows = rows;
        this.cols = cols;
        this.traversable = new boolean[rows][cols];
        parseGrid(gridLines);
    }

    private void parseGrid(String[] gridLines) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                // A cell is traversable if it contains '.'
                traversable[i][j] = gridLines[i].charAt(j) == '.';
            }
        }
    }

    /**
     * Uses Breadth-First Search to determine if there is a path from start to target.
     * 
     * @param startR Starting row (1-indexed)
     * @param startC Starting column (1-indexed)
     * @param targetR Target row (1-indexed)
     * @param targetC Target column (1-indexed)
     * @return true if target is reachable, false otherwise
     */
    public boolean isReachable(int startR, int startC, int targetR, int targetC) {
        // Convert 1-based indexing to 0-based indexing
        int startRow = startR - 1;
        int startCol = startC - 1;
        int targetRow = targetR - 1;
        int targetCol = targetC - 1;

        // Boundary and validity checks
        if (isInvalid(startRow, startCol) || isInvalid(targetRow, targetCol)) {
            return false;
        }

        if (startRow == targetRow && startCol == targetCol) {
            return traversable[startRow][startCol];
        }

        if (!traversable[startRow][startCol] || !traversable[targetRow][targetCol]) {
            return false;
        }

        return performBFS(new Coordinate(startRow, startCol), new Coordinate(targetRow, targetCol));
    }

    private boolean performBFS(Coordinate start, Coordinate target) {
        Queue<Coordinate> queue = new ArrayDeque<>();
        boolean[][] visited = new boolean[rows][cols];

        queue.add(start);
        visited[start.row()][start.col()] = true;

        int[][] directions = {
            {0, 1},  // Right
            {0, -1}, // Left
            {1, 0},  // Down
            {-1, 0}  // Up
        };

        while (!queue.isEmpty()) {
            Coordinate current = queue.poll();

            if (current.row() == target.row() && current.col() == target.col()) {
                return true;
            }

            for (int[] dir : directions) {
                int nextRow = current.row() + dir[0];
                int nextCol = current.col() + dir[1];

                if (!isInvalid(nextRow, nextCol) 
                        && traversable[nextRow][nextCol] 
                        && !visited[nextRow][nextCol]) {

                    visited[nextRow][nextCol] = true;
                    queue.add(new Coordinate(nextRow, nextCol));
                }
            }
        }

        return false;
    }

    private boolean isInvalid(int r, int c) {
        return r < 0 || r >= rows || c < 0 || c >= cols;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        String[] gridLines = new String[rows];
        for (int i = 0; i < rows; i++) {
            gridLines[i] = scanner.next();
        }

        int r1 = scanner.nextInt();
        int c1 = scanner.nextInt();
        int r2 = scanner.nextInt();
        int c2 = scanner.nextInt();

        GridPathfinder pathfinder = new GridPathfinder(rows, cols, gridLines);
        boolean possible = pathfinder.isReachable(r1, c1, r2, c2);

        System.out.println(possible ? "YES" : "NO");

        scanner.close();
    }
}

import java.util.*;

/**
 * A solver for finding paths through an ice grid.
 */
public class IcePathfinder {

    /**
     * Represents a coordinate in the 2D grid.
     */
    public record Point(int row, int col) {}

    /**
     * Represents the possible movement directions in the grid.
     */
    public enum Direction {
        UP(-1, 0),
        DOWN(1, 0),
        LEFT(0, -1),
        RIGHT(0, 1);

        private final int rowDelta;
        private final int colDelta;

        Direction(int rowDelta, int colDelta) {
            this.rowDelta = rowDelta;
            this.colDelta = colDelta;
        }

        public Point move(Point current) {
            return new Point(current.row() + rowDelta, current.col() + colDelta);
        }
    }

    /**
     * Handles the maze logic and pathfinding.
     */
    public static class IceMaze {
        private final char[][] grid;
        private final int rows;
        private final int cols;

        public IceMaze(char[][] grid) {
            this.grid = grid;
            this.rows = grid.length;
            this.cols = grid[0].length;
        }

        /**
         * Uses Depth-First Search to determine if a path exists from start to end.
         * 
         * @param start The starting coordinate.
         * @param end   The target coordinate.
         * @return true if a path of '.' cells exists, false otherwise.
         */
        public boolean solve(Point start, Point end) {
            if (!isValid(start) || !isValid(end) || !isWalkable(start) || !isWalkable(end)) {
                return false;
            }

            Deque<Point> stack = new ArrayDeque<>();
            boolean[][] visited = new boolean[rows][cols];

            stack.push(start);
            visited[start.row()][start.col()] = true;

            while (!stack.isEmpty()) {
                Point current = stack.pop();

                if (current.equals(end)) {
                    return true;
                }

                for (Direction dir : Direction.values()) {
                    Point next = dir.move(current);

                    if (isValid(next) && isWalkable(next) && !visited[next.row()][next.col()]) {
                        visited[next.row()][next.col()] = true;
                        stack.push(next);
                    }
                }
            }

            return false;
        }

        private boolean isValid(Point p) {
            return p.row() >= 0 && p.row() < rows && p.col() >= 0 && p.col() < cols;
        }

        private boolean isWalkable(Point p) {
            return grid[p.row()][p.col()] == '.';
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        try {
            // Read dimensions
            if (!scanner.hasNextInt()) return;
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            scanner.nextLine(); // Consume newline

            // Read grid
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = scanner.nextLine();
                grid[i] = line.toCharArray();
            }

            // Read coordinates (converted from 1-indexed to 0-indexed)
            int startRow = scanner.nextInt() - 1;
            int startCol = scanner.nextInt() - 1;
            int endRow = scanner.nextInt() - 1;
            int endCol = scanner.nextInt() - 1;

            IceMaze maze = new IceMaze(grid);
            Point start = new Point(startRow, startCol);
            Point end = new Point(endRow, endCol);

            // Special case: if start is end, path exists
            if (start.equals(end)) {
                System.out.println("YES");
            } else if (maze.solve(start, end)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }

        } catch (NoSuchElementException e) {
            System.err.println("Invalid input format.");
        } finally {
            scanner.close();
        }
    }
}

import java.util.*;

/**
 * Solution for a grid-based reachability problem.
 * The goal is to determine if a target point is reachable and satisfies specific proximity conditions.
 */
public class Solution {

    private static final char OBSTACLE = 'X';
    private static final int[][] DIRECTIONS = {
            {0, 1},  // Right
            {0, -1}, // Left
            {1, 0},  // Down
            {-1, 0}  // Up
    };

    /**
     * Represents a coordinate in the 2D grid.
     */
    private record Point(int r, int c) {}

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            scanner.nextLine(); // Consume newline

            char[][] map = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                map[i] = scanner.nextLine().toCharArray();
            }

            // Input coordinates are 1-indexed in the original problem
            Point start = new Point(scanner.nextInt() - 1, scanner.nextInt() - 1);
            Point end = new Point(scanner.nextInt() - 1, scanner.nextInt() - 1);

            boolean isPossible = solve(map, start, end);
            System.out.println(isPossible ? "YES" : "NO");
        }
    }

    /**
     * Core business logic to determine if the target is valid based on connectivity and neighbor counts.
     */
    public static boolean solve(char[][] map, Point start, Point end) {
        // 1. If already at target, must have at least one accessible neighbor
        if (start.equals(end) && countAccessibleNeighbors(map, start) > 0) {
            return true;
        }

        int distance = Math.abs(start.r() - end.r()) + Math.abs(start.c() - end.c());

        // 2. Special proximity rules for adjacent cells
        if (distance == 1) {
            if (map[end.r()][end.c()] == OBSTACLE) return true;
            if (countAccessibleNeighbors(map, end) > 0) return true;
        }

        // 3. Basic reachability check
        if (!hasPath(map, start, end)) {
            return false;
        }

        // 4. Post-path connectivity requirements
        if (map[end.r()][end.c()] == OBSTACLE && countAccessibleNeighbors(map, end) > 0) {
            return true;
        }
        if (countAccessibleNeighbors(map, end) > 1) {
            return true;
        }

        return false;
    }

    /**
     * Determines if a path exists from start to end avoiding obstacles.
     * Note: The end cell itself can be an obstacle, provided it is adjacent to a valid path.
     */
    private static boolean hasPath(char[][] map, Point start, Point end) {
        // Shortcut: if they are adjacent, a path is considered to exist regardless of target content
        if (Math.abs(start.r() - end.r()) + Math.abs(start.c() - end.c()) == 1) {
            return true;
        }

        int rows = map.length;
        int cols = map[0].length;
        Queue<Point> queue = new LinkedList<>();
        boolean[][] visited = new boolean[rows][cols];

        queue.add(start);
        visited[start.r()][start.c()] = true;

        while (!queue.isEmpty()) {
            Point curr = queue.poll();

            if (curr.equals(end)) {
                return true;
            }

            for (int[] dir : DIRECTIONS) {
                int nr = curr.r() + dir[0];
                int nc = curr.c() + dir[1];

                if (isWithinBounds(nr, nc, rows, cols) && !visited[nr][nc]) {
                    // If this neighbor is the target, we found it (even if target is an obstacle)
                    if (nr == end.r() && nc == end.c()) {
                        return true;
                    }

                    // Otherwise, only traverse if the cell is not an obstacle
                    if (map[nr][nc] != OBSTACLE) {
                        visited[nr][nc] = true;
                        queue.add(new Point(nr, nc));
                    }
                }
            }
        }
        return false;
    }

    /**
     * Counts neighbors that are within bounds and are not obstacles.
     */
    private static int countAccessibleNeighbors(char[][] map, Point p) {
        int count = 0;
        int rows = map.length;
        int cols = map[0].length;

        for (int[] dir : DIRECTIONS) {
            int nr = p.r() + dir[0];
            int nc = p.c() + dir[1];

            if (isWithinBounds(nr, nc, rows, cols) && map[nr][nc] != OBSTACLE) {
                count++;
            }
        }
        return count;
    }

    private static boolean isWithinBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

