/**
 * A refactored solution for the grid reachability problem.
 * The goal is to determine if a target cell can be reached in a grid 
 * of paths ('.') and obstacles ('X'), considering specific rules 
 * regarding whether the target is an obstacle or a path.
 */
public class Solution {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            String rowsStr = reader.next();
            if (rowsStr == null) return;

            int rows = Integer.parseInt(rowsStr);
            int cols = reader.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            // Convert 1-based input coordinates to 0-based
            int startX = reader.nextInt() - 1;
            int startY = reader.nextInt() - 1;
            int endX = reader.nextInt() - 1;
            int endY = reader.nextInt() - 1;

            MazeSolver solver = new MazeSolver(grid, rows, cols, startX, startY, endX, endY);
            writer.println(solver.solve() ? "YES" : "NO");

        } catch (Exception e) {
            // In a production environment, use a logger.
        } finally {
            writer.close();
        }
    }

    /**
     * Represents a coordinate in the 2D grid.
     */
    static class Point {
        final int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Point)) return false;
            Point point = (Point) o;
            return r == point.r && c == point.c;
        }

        @Override
        public int hashCode() {
            return Objects.hash(r, c);
        }
    }

    /**
     * Encapsulates the maze logic and reachability algorithms.
     */
    static class MazeSolver {
        private final char[][] grid;
        private final int rows;
        private final int cols;
        private final Point start;
        private final Point end;
        private final boolean targetWasX;

        private static final int[][] DIRECTIONS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

        public MazeSolver(char[][] grid, int rows, int cols, int startX, int startY, int endX, int endY) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
            this.start = new Point(startX, startY);
            this.end = new Point(endX, endY);
            this.targetWasX = (grid[endX][endY] == 'X');

            // Ensure the starting point is treated as a valid path cell
            this.grid[startX][startY] = '.';
        }

        /**
         * Determines if the target satisfies the problem requirements.
         */
        public boolean solve() {
            boolean reachable = isReachable();
            if (!reachable) {
                return false;
            }

            // Case 1: Target was an 'X'. 
            // If start != end, reaching an 'X' is a success.
            // If start == end, the logic treats it as a '.' and checks path connectivity.
            if (targetWasX && !start.equals(end)) {
                return true;
            }

            // Case 2: Target is a path ('.').
            // We must ensure the target is not a "dead end" in the path.
            int adjacentPaths = countAdjacentPaths(end.r, end.c);
            if (start.equals(end)) {
                return adjacentPaths > 0;
            } else {
                return adjacentPaths > 1;
            }
        }

        /**
         * Performs an iterative BFS to check if the end point is reachable.
         * Obstacles ('X') are treated as walls unless they are the target cell.
         */
        private boolean isReachable() {
            boolean[][] visited = new boolean[rows][cols];
            Deque<Point> queue = new ArrayDeque<>();

            queue.add(start);
            visited[start.r][start.c] = true;

            while (!queue.isEmpty()) {
                Point curr = queue.poll();

                if (curr.equals(end)) {
                    return true;
                }

                for (int[] dir : DIRECTIONS) {
                    int nr = curr.r + dir[0];
                    int nc = curr.c + dir[1];

                    if (isValid(nr, nc) && !visited[nr][nc]) {
                        // If the next cell is our target, we stop immediately
                        if (nr == end.r && nc == end.c) {
                            return true;
                        }
                        // If the next cell is a path, we add it to the queue
                        if (grid[nr][nc] == '.') {
                            visited[nr][nc] = true;
                            queue.add(new Point(nr, nc));
                        }
                    }
                }
            }
            return false;
        }

        private int countAdjacentPaths(int r, int c) {
            int count = 0;
            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (isValid(nr, nc) && grid[nr][nc] == '.') {
                    count++;
                }
            }
            return count;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * Fast I/O utility for efficient reading of input streams.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String n = next();
            return n == null ? 0 : Integer.parseInt(n);
        }
    }
}

