/**
 * A solution to determine path connectivity and target cell characteristics in a grid.
 */
public class Main {

    public static void main(String[] args) {
        try {
            FastReader reader = new FastReader(System.in);
            PrintWriter writer = new PrintWriter(System.out);

            // Input dimensions
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            // Build the grid
            int[][] grid = new int[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = reader.nextLine();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = (line.charAt(j) == 'X') ? 0 : 1;
                }
            }

            // Read start and end coordinates (converting 1-based to 0-based)
            int startRow = reader.nextInt() - 1;
            int startCol = reader.nextInt() - 1;
            int targetRow = reader.nextInt() - 1;
            int targetCol = reader.nextInt() - 1;

            GridNavigator navigator = new GridNavigator(grid, rows, cols);

            // Execute logic
            boolean isReachable = navigator.isTargetReachable(startRow, startCol, targetRow, targetCol);

            if (isReachable) {
                int neighborCount = navigator.countTargetNeighbors(targetRow, targetCol, startRow, startCol);

                // If target is a path cell, it must have more than one path connection to be 'YES'
                if (grid[targetRow][targetCol] == 1) {
                    writer.println(neighborCount > 1 ? "YES" : "NO");
                } else {
                    writer.println("YES");
                }
            } else {
                writer.println("NO");
            }

            writer.flush();
            writer.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /**
     * Handles navigation and connectivity logic within the grid.
     */
    static class GridNavigator {
        private final int[][] grid;
        private final int rows;
        private final int cols;

        private static final int[] ROW_OFFSETS = {0, 0, -1, 1};
        private static final int[] COL_OFFSETS = {-1, 1, 0, 0};

        public GridNavigator(int[][] grid, int rows, int cols) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
        }

        /**
         * Performs a BFS to check if the target is reachable from the start point.
         */
        public boolean isTargetReachable(int startR, int startC, int targetR, int targetC) {
            Queue<Point> queue = new LinkedList<>();
            boolean[][] visited = new boolean[rows][cols];

            queue.add(new Point(startR, startC));
            visited[startR][startC] = true;

            while (!queue.isEmpty()) {
                Point current = queue.poll();

                for (int i = 0; i < 4; i++) {
                    int nextR = current.row + ROW_OFFSETS[i];
                    int nextC = current.col + COL_OFFSETS[i];

                    if (isInBounds(nextR, nextC)) {
                        // Check if we reached the target
                        if (nextR == targetR && nextC == targetC) {
                            return true;
                        }

                        // Standard BFS movement: only through path cells (1)
                        if (grid[nextR][nextC] == 1 && !visited[nextR][nextC]) {
                            visited[nextR][nextC] = true;
                            queue.add(new Point(nextR, nextC));
                        }
                    }
                }
            }
            return false;
        }

        /**
         * Counts neighbors of the target that are either path cells or the starting cell.
         */
        public int countTargetNeighbors(int targetR, int targetC, int startR, int startC) {
            int count = 0;
            for (int i = 0; i < 4; i++) {
                int nr = targetR + ROW_OFFSETS[i];
                int nc = targetC + COL_OFFSETS[i];

                if (isInBounds(nr, nc)) {
                    if (grid[nr][nc] == 1 || (nr == startR && nc == startC)) {
                        count++;
                    }
                }
            }
            return count;
        }

        private boolean isInBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * Simple data carrier for grid coordinates.
     */
    static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public String nextLine() throws IOException {
            if (tokenizer != null && tokenizer.hasMoreElements()) {
                StringBuilder sb = new StringBuilder();
                while (tokenizer.hasMoreElements()) {
                    sb.append(tokenizer.nextToken());
                    if (tokenizer.hasMoreElements()) sb.append(" ");
                }
                tokenizer = null;
                return sb.toString();
            }
            return reader.readLine();
        }
    }
}

