/**
 * Logic for solving the grid traversal problem.
 */
class GridPathSolver {
    private static final int[][] DIRECTIONS = {{0, -1}, {-1, 0}, {0, 1}, {1, 0}};

    private final FastReader reader;
    private int rows;
    private int cols;

    public GridPathSolver(FastReader reader) {
        this.reader = reader;
    }

    /**
     * Represents a coordinate in the grid.
     */
    private static class Point {
        final int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Main logic execution.
     */
    public void solve(PrintWriter out) {
        rows = reader.nextInt();
        cols = reader.nextInt();

        String[] grid = new String[rows];
        for (int i = 0; i < rows; i++) {
            grid[i] = reader.nextString();
        }

        // Convert 1-indexed input to 0-indexed
        int startRow = reader.nextInt() - 1;
        int startCol = reader.nextInt() - 1;
        int endRow = reader.nextInt() - 1;
        int endCol = reader.nextInt() - 1;

        if (isStartEqualsEnd(startRow, startCol, endRow, endCol)) {
            out.println(canStartReachAdjacentEmpty(startRow, startCol, grid) ? "YES" : "NO");
            return;
        }

        // Check if the end point satisfies specific connectivity constraints
        if (grid[endRow].charAt(endCol) == '.' && !hasRequiredConnectivity(startRow, startCol, endRow, endCol, grid)) {
            out.println("NO");
            return;
        }

        // Perform BFS to find all reachable non-obstacle cells
        boolean[][] visited = performBFS(startRow, startCol, grid);

        // Check if any neighbor of the end point was reached
        if (isEndNeighborVisited(endRow, endCol, visited)) {
            out.println("YES");
        } else {
            out.println("NO");
        }
    }

    private boolean isStartEqualsEnd(int r1, int c1, int r2, int c2) {
        return r1 == r2 && c1 == c2;
    }

    private boolean canStartReachAdjacentEmpty(int r, int c, String[] grid) {
        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            if (isWithinBounds(nr, nc) && grid[nr].charAt(nc) == '.') {
                return true;
            }
        }
        return false;
    }

    private boolean hasRequiredConnectivity(int startRow, int startCol, int endRow, int endCol, String[] grid) {
        int connectivityCount = 0;
        for (int[] dir : DIRECTIONS) {
            int nr = endRow + dir[0];
            int nc = endCol + dir[1];

            if (isWithinBounds(nr, nc)) {
                boolean isStartPoint = (nr == startRow && nc == startCol);
                boolean isPathCell = (grid[nr].charAt(nc) == '.');
                if (isPathCell || isStartPoint) {
                    connectivityCount++;
                }
            }
        }
        return connectivityCount >= 2;
    }

    private boolean[][] performBFS(int startRow, int startCol, String[] grid) {
        boolean[][] visited = new boolean[rows][cols];
        Deque<Point> queue = new ArrayDeque<>();

        queue.addLast(new Point(startRow, startCol));
        visited[startRow][startCol] = true;

        while (!queue.isEmpty()) {
            Point current = queue.pollFirst();

            for (int[] dir : DIRECTIONS) {
                int nr = current.r + dir[0];
                int nc = current.c + dir[1];

                if (isWithinBounds(nr, nc) 
                        && !visited[nr][nc] 
                        && grid[nr].charAt(nc) != 'X') {
                    visited[nr][nc] = true;
                    queue.addLast(new Point(nr, nc));
                }
            }
        }
        return visited;
    }

    private boolean isEndNeighborVisited(int endRow, int endCol, boolean[][] visited) {
        for (int[] dir : DIRECTIONS) {
            int nr = endRow + dir[0];
            int nc = endCol + dir[1];
            if (isWithinBounds(nr, nc) && visited[nr][nc]) {
                return true;
            }
        }
        return false;
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

