/**
 * Encapsulates the logic for navigating the Ice Cave.
 */
class IceCaveSolver {
    private static final int[][] DIRECTIONS = {
        {0, 1},  // Right
        {1, 0},  // Down
        {0, -1}, // Left
        {-1, 0}  // Up
    };

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final Point start;
    private final Point end;
    private final char originalEndChar;

    public IceCaveSolver(int rows, int cols, char[][] grid, int startR, int startC, int endR, int endC) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.start = new Point(startR, startC);
        this.end = new Point(endR, endC);
        this.originalEndChar = grid[endR][endC];

        // Prepare the grid by treating start and end points as traversable paths
        this.grid[startR][startC] = '.';
        this.grid[endR][endC] = '.';
    }

    /**
     * Evaluates the core logic of the problem.
     * @return true if the path requirements are met, false otherwise.
     */
    public boolean solve() {
        int endPathNeighborCount = countPathNeighbors(end);

        // Case 1: Start and end points are identical
        if (start.equals(end)) {
            return endPathNeighborCount >= 1;
        }

        // Case 2: Start and end points are distinct
        if (isEndReachable()) {
            // Success if the destination has multiple neighbors or was an 'X' type cell
            return endPathNeighborCount > 1 || originalEndChar == 'X';
        }

        return false;
    }

    /**
     * Counts how many adjacent cells are currently traversable paths ('.').
     */
    private int countPathNeighbors(Point p) {
        int count = 0;
        for (int[] dir : DIRECTIONS) {
            int nr = p.r + dir[0];
            int nc = p.c + dir[1];
            if (isWithinBounds(nr, nc) && grid[nr][nc] == '.') {
                count++;
            }
        }
        return count;
    }

    /**
     * Checks if a path exists from the start point to the end point using DFS.
     */
    private boolean isEndReachable() {
        boolean[][] visited = new boolean[rows][cols];
        return performDFS(start, visited);
    }

    private boolean performDFS(Point current, boolean[][] visited) {
        if (current.equals(end)) {
            return true;
        }

        visited[current.r][current.c] = true;

        for (int[] dir : DIRECTIONS) {
            int nr = current.r + dir[0];
            int nc = current.c + dir[1];

            if (isWithinBounds(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                if (performDFS(new Point(nr, nc), visited)) {
                    return true;
                }
            }
        }
        return false;
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

