/**
 * Represents the maze grid and provides boundary and traversability checks.
 */
class Grid {
    private final char[][] cells;
    private final int rows;
    private final int cols;

    Grid(int rows, int cols, char[][] cells) {
        this.rows = rows;
        this.cols = cols;
        this.cells = cells;
    }

    public int getRows() { return rows; }
    public int getCols() { return cols; }

    public char getCell(int r, int c) {
        return cells[r][c];
    }

    public boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * A cell is traversable if it is not an obstacle ('X'), 
     * or if it is the starting cell.
     */
    public boolean isTraversable(int r, int c, Point start) {
        if (!isWithinBounds(r, c)) return false;
        return cells[r][c] != 'X' || new Point(r, c).equals(start);
    }

    /**
     * Specifically for the 'dead-end' rule: counts neighbors that are '.' or the start cell.
     */
    public int countIntactNeighbors(int r, int c, Point start) {
        int count = 0;
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int i = 0; i < 4; i++) {
            int nr = r + dr[i];
            int nc = c + dc[i];
            if (isWithinBounds(nr, nc)) {
                if (cells[nr][nc] == '.' || new Point(nr, nc).equals(start)) {
                    count++;
                }
            }
        }
        return count;
    }

    public List<Point> getNeighbors(int r, int c) {
        List<Point> neighbors = new ArrayList<>();
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int i = 0; i < 4; i++) {
            int nr = r + dr[i];
            int nc = c + dc[i];
            if (isWithinBounds(nr, nc)) {
                neighbors.add(new Point(nr, nc));
            }
        }
        return neighbors;
    }
}

/**
 * Contains the logic to solve the pathfinding problem.
 */
class MazeSolver {
    private final Grid grid;
    private final Point start;
    private final Point end;

    public MazeSolver(Grid grid, Point start, Point end) {
        this.grid = grid;
        this.start = start;
        this.end = end;
    }

    public boolean solve() {
        // Rule 1: A 1x1 grid cannot have a valid path/cycle.
        if (grid.getRows() * grid.getCols() == 1) {
            return false;
        }

        // Rule 2: If the end is a '.', it must not be a "dead end" (degree < 2).
        if (grid.getCell(end.row, end.col) == '.' && 
            grid.countIntactNeighbors(end.row, end.col, start) < 2) {
            return false;
        }

        if (!start.equals(end)) {
            return performBFS(start, end);
        } else {
            // If start is end, we look for a cycle (a non-trivial path returning to start).
            return findCycle();
        }
    }

    private boolean performBFS(Point startNode, Point targetNode) {
        Queue<Point> queue = new LinkedList<>();
        Set<Point> visited = new HashSet<>();

        queue.add(startNode);
        visited.add(startNode);

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            if (current.equals(targetNode)) {
                return true;
            }

            // If the current cell is traversable, we can explore its neighbors.
            if (grid.isTraversable(current.row, current.col, start)) {
                for (Point neighbor : grid.getNeighbors(current.row, current.col)) {
                    if (!visited.contains(neighbor)) {
                        // We allow adding the target to the queue even if it's 'X',
                        // as the 'equals(targetNode)' check happens immediately after polling.
                        if (neighbor.equals(targetNode) || grid.isTraversable(neighbor.row, neighbor.col, start)) {
                            visited.add(neighbor);
                            queue.add(neighbor);
                        }
                    }
                }
            }
        }
        return false;
    }

    private boolean findCycle() {
        Queue<Point> queue = new LinkedList<>();
        Set<Point> visited = new HashSet<>();

        // To find a cycle for start == end, we start BFS from all traversable neighbors.
        for (Point neighbor : grid.getNeighbors(start.row, start.col)) {
            if (grid.isTraversable(neighbor.row, neighbor.col, start)) {
                queue.add(neighbor);
                visited.add(neighbor);
            }
        }

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            if (current.equals(start)) {
                return true;
            }

            if (grid.isTraversable(current.row, current.col, start)) {
                for (Point neighbor : grid.getNeighbors(current.row, current.col)) {
                    if (!visited.contains(neighbor)) {
                        visited.add(neighbor);
                        queue.add(neighbor);
                    }
                }
            }
        }
        return false;
    }
}

