import java.util.*;

/**
 * A utility class to handle pathfinding logic on a 2D grid.
 */
class GridPathfinder {
    private final char[][] grid;
    private final int rows;
    private final int cols;

    // Direction vectors for Up, Down, Left, Right movement
    private static final int[][] DIRECTIONS = {
        {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    public GridPathfinder(char[][] grid) {
        this.grid = grid;
        this.rows = grid.length;
        this.cols = grid[0].length;
    }

    /**
     * Represents a coordinate point in the grid.
     */
    private record Point(int r, int c) {}

    /**
     * Determines if there is a path from the start point to the target point
     * using only '.' (walkable) cells.
     *
     * @param startRow Starting row index.
     * @param startCol Starting column index.
     * @param targetRow Destination row index.
     * @param targetCol Destination column index.
     * @return true if a path exists, false otherwise.
     */
    public boolean canReachTarget(int startRow, int startCol, int targetRow, int targetCol) {
        // Basic validation: bounds check and obstacle check
        if (!isValid(startRow, startCol) || !isValid(targetRow, targetCol)) {
            return false;
        }

        // If start or target is a wall, no path exists
        if (grid[startRow][startCol] == 'X' || grid[targetRow][targetCol] == 'X') {
            return false;
        }

        // If start is already target
        if (startRow == targetRow && startCol == targetCol) {
            return true;
        }

        return performBFS(new Point(startRow, startCol), new Point(targetRow, targetCol));
    }

    private boolean performBFS(Point start, Point target) {
        Queue<Point> queue = new LinkedList<>();
        boolean[][] visited = new boolean[rows][cols];

        queue.add(start);
        visited[start.r()][start.c()] = true;

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            for (int[] dir : DIRECTIONS) {
                int nextR = current.r() + dir[0];
                int nextC = current.c() + dir[1];

                if (isValid(nextR, nextC) && !visited[nextR][nextC] && grid[nextR][nextC] == '.') {
                    // Check if we found the target
                    if (nextR == target.r() && nextC == target.c()) {
                        return true;
                    }

                    visited[nextR][nextC] = true;
                    queue.add(new Point(nextR, nextC));
                }
            }
        }

        return false;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        try {
            if (!sc.hasNextInt()) return;
            int n = sc.nextInt();
            int m = sc.nextInt();

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                String line = sc.next();
                for (int j = 0; j < m; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }

            // Reading coordinates (assuming 1-based indexing based on original code)
            int startRow = sc.nextInt() - 1;
            int startCol = sc.nextInt() - 1;
            int targetRow = sc.nextInt() - 1;
            int targetCol = sc.nextInt() - 1;

            GridPathfinder pathfinder = new GridPathfinder(grid);
            boolean result = pathfinder.canReachTarget(startRow, startCol, targetRow, targetCol);

            System.out.println(result ? "YES" : "NO");

        } catch (Exception e) {
            // In a real application, use a logger instead of printStackTrace
            System.err.println("Error processing input: " + e.getMessage());
        } finally {
            sc.close();
        }
    }
}

