        }

        // Pre-calculate requirements based on the original state
        int dotNeighborCount = countDotNeighbors(endR, endC, originalGrid);
        boolean isAdjacent = Math.abs(startR - endR) + Math.abs(startC - endC) == 1;
        boolean endWasOriginallyCracked = originalGrid[endR][endC] == 'X';

        // Decision logic based on the original code's specific behavior
        if (isAdjacent) {
            if (endWasOriginallyCracked) {
                out.print("YES");
            } else {
                out.print(dotNeighborCount >= 1 ? "YES" : "NO");
            }
        } else if (endWasOriginallyCracked) {
            out.print(dotNeighborCount >= 1 ? "YES" : "NO");
        } else {
            out.print(dotNeighborCount >= 2 ? "YES" : "NO");
        }
    }

    /**
     * Performs a BFS to find if a path exists from start to end.
     * Replicates the original logic: the start node is always processed, 
     * but subsequent 'X' nodes do not expand to their neighbors.
     */
    private static boolean hasPath(int startR, int startC, int endR, int endC, char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        boolean[][] visited = new boolean[rows][cols];
        Queue<Point> queue = new LinkedList<>();

        queue.add(new Point(startR, startC));
        visited[startR][startC] = true;

        int[] dr = {1, -1, 0, 0};
        int[] dc = {0, 0, 1, -1};

        boolean isFirstNode = true;

        while (!queue.isEmpty()) {
            Point curr = queue.poll();

            if (curr.r == endR && curr.c == endC) {
                return true;
            }

            // The original logic allowed the first node to be processed regardless of its type.
            // Subsequent nodes are only processed if they are '.' (empty).
            if (isFirstNode || grid[curr.r][curr.c] == '.') {
                isFirstNode = false;
                for (int i = 0; i < 4; i++) {
                    int nr = curr.r + dr[i];
                    int nc = curr.c + dc[i];

                    if (isValid(nr, nc, rows, cols) && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        queue.add(new Point(nr, nc));
                    }
                }
            }
        }
        return false;
    }

    private static int countDotNeighbors(int r, int c, char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        int count = 0;
        int[] dr = {1, -1, 0, 0};
        int[] dc = {0, 0, 1, -1};

        for (int i = 0; i < 4; i++) {
            int nr = r + dr[i];
            int nc = c + dc[i];
            if (isValid(nr, nc, rows, cols) && grid[nr][nc] == '.') {
                count++;
            }
        }
        return count;
    }

    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Helper class to represent a coordinate in the grid.
     */
    private static class Point {
        int r, c;
        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Optimized reader for fast I/O operations.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
