/**
 * Represents a 2D grid map.
 */
class Grid {
    private final int rows;
    private final int cols;
    private final char[][] map;

    public Grid(int rows, int cols, String[] gridLines) {
        this.rows = rows;
        this.cols = cols;
        this.map = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            this.map[i] = gridLines[i].toCharArray();
        }
    }

    public boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Determines if a cell can be walked through.
     * 'X' is treated as an obstacle.
     */
    public boolean isTraversable(int r, int c) {
        return isWithinBounds(r, c) && map[r][c] != 'X';
    }

    public int getRows() {
        return rows;
    }

    public int getCols() {
        return cols;
    }
}

/**
 * Represents a single coordinate in the grid.
 */
record Coordinate(int row, int col) {}

/**
 * Contains the logic for finding paths within a Grid.
 */
class Pathfinder {
    private final Grid grid;
    private static final int[][] DIRECTIONS = {
        {1, 0}, {-1, 0}, {0, 1}, {0, -1}
    };

    public Pathfinder(Grid grid) {
        this.grid = grid;
    }

    /**
     * Uses Breadth-First Search (BFS) to determine if a path exists 
     * between start and end coordinates.
     */
    public boolean hasPath(Coordinate start, Coordinate end) {
        // If start or end is an obstacle or out of bounds, no path exists
        if (!grid.isTraversable(start.row(), start.col()) || 
            !grid.isTraversable(end.row(), end.col())) {
            return false;
        }

        // If start is the same as end
        if (start.equals(end)) {
            return true;
        }

        Queue<Coordinate> queue = new ArrayDeque<>();
        boolean[][] visited = new boolean[grid.getRows()][grid.getCols()];

        queue.add(start);
        visited[start.row()][start.col()] = true;

        while (!queue.isEmpty()) {
            Coordinate current = queue.poll();

            if (current.equals(end)) {
                return true;
            }

            for (int[] dir : DIRECTIONS) {
                int nextRow = current.row() + dir[0];
                int nextCol = current.col() + dir[1];
                Coordinate neighbor = new Coordinate(nextRow, nextCol);

                if (grid.isTraversable(nextRow, nextCol) && !visited[nextRow][nextCol]) {
                    visited[nextRow][nextCol] = true;
                    queue.add(neighbor);
                }
            }
        }

        return false;
    }
}

