/**
 * Handles the logic for determining if a path exists in the ice cave.
 */
class IceCaveSolver {
    private final FastReader reader;

    private char[][] maze;
    private boolean[][] visited;
    private int rows;
    private int cols;

    private int startRow, startCol;
    private int targetRow, targetCol;

    // Direction vectors for moving Up, Down, Left, Right
    private static final int[] DR = {1, -1, 0, 0};
    private static final int[] DC = {0, 0, 1, -1};

    public IceCaveSolver(FastReader reader) {
        this.reader = reader;
    }

    /**
     * Orchestrates the reading of input and the execution of the solver.
     */
    public void solve(PrintWriter out) {
        this.rows = reader.nextInt();
        this.cols = reader.nextInt();

        this.maze = new char[rows][cols];
        this.visited = new boolean[rows][cols];

        for (int i = 0; i < rows; i++) {
            this.maze[i] = reader.next().toCharArray();
        }

        // Convert 1-based indexing from input to 0-based indexing
        this.startRow = reader.nextInt() - 1;
        this.startCol = reader.nextInt() - 1;
        this.targetRow = reader.nextInt() - 1;
        this.targetCol = reader.nextInt() - 1;

        performDfs(startRow, startCol);

        if (visited[targetRow][targetCol]) {
            out.println("YES");
        } else {
            out.println("NO");
        }
    }

    /**
     * Standard Depth First Search to explore reachable cells.
     * 
     * @param r Current row
     * @param c Current column
     */
    private void performDfs(int r, int c) {
        // Boundary and validity checks
        if (r < 0 || r >= rows || c < 0 || c >= cols) return;
        if (visited[r][c] || maze[r][c] == 'X') return;

        // Mark current cell as visited
        visited[r][c] = true;

        // If we reached the target, we stop exploring this branch
        if (r == targetRow && c == targetCol) {
            return;
        }

        // Explore all 4 adjacent directions
        for (int i = 0; i < 4; i++) {
            performDfs(r + DR[i], c + DC[i]);
        }
    }
}

