/**
 * MazeSolverApp serves as the entry point for the grid-based pathfinding application.
 */
public class MazeSolverApp {

    public static void main(String[] args) {
        MazeSolver solver = new MazeSolver(System.in);
        solver.solve();
    }

    /**
     * FastReader provides efficient parsing of input streams using BufferedReader.
     * This is a standard pattern for high-performance I/O in Java.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            this.reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input stream", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            return next != null ? Integer.parseInt(next) : 0;
        }

        public char[] nextCharArray() {
            String next = next();
            return next != null ? next.toCharArray() : new char[0];
        }
    }

    /**
     * MazeSolver encapsulates the grid data and the logic for determining path connectivity.
     */
    static class MazeSolver {
        private static final int[][] DIRECTIONS = {
            {1, 0}, {-1, 0}, {0, 1}, {0, -1}
        };

        private final FastReader reader;
        private int rows;
        private int cols;
        private char[][] grid;

        public MazeSolver(InputStream inputStream) {
            this.reader = new FastReader(inputStream);
        }

        /**
         * Orchestrates the reading of input and triggers the solving process.
         */
        public void solve() {
            this.rows = reader.nextInt();
            this.cols = reader.nextInt();

            if (rows <= 0 || cols <= 0) return;

            this.grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.nextCharArray();
            }

            // Convert 1-based indexing from input to 0-based indexing used in arrays
            int startRow = reader.nextInt() - 1;
            int startCol = reader.nextInt() - 1;
            int endRow = reader.nextInt() - 1;
            int endCol = reader.nextInt() - 1;

            if (isPathPossible(startRow, startCol, endRow, endCol)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }

        /**
         * Evaluates if a path exists based on the specific problem constraints.
         */
        private boolean isPathPossible(int startRow, int startCol, int endRow, int endCol) {
            if (!isValid(startRow, startCol) || !isValid(endRow, endCol)) {
                return false;
            }

            // Calculate connections to the destination to satisfy original logic constraints.
            // This counts neighbors that are empty ('.') or are the start point.
            int targetConnections = countTargetConnections(startRow, startCol, endRow, endCol);

            // Constraint: If the target is an empty cell but has fewer than 2 connections.
            if (targetConnections < 2 && grid[endRow][endCol] == '.') {
                return false;
            }

            // Constraint: Special handling if start and end are the same cell.
            if (startRow == endRow && startCol == endCol) {
                return targetConnections > 0;
            }

            // Standard pathfinding using Breadth-First Search.
            return hasPathBFS(startRow, startCol, endRow, endCol);
        }

        /**
         * Replicates the connection logic from the original code, 
         * ensuring behavior parity.
         */
        private int countTargetConnections(int startRow, int startCol, int endRow, int endCol) {
            int count = 0;
            for (int[] dir : DIRECTIONS) {
                int r = endRow + dir[0];
                int c = endCol + dir[1];

                if (isValid(r, c)) {
                    if (grid[r][c] == '.') {
                        count++;
                    }
                    // Per original logic, if the neighbor is the starting point, increment again.
                    if (r == startRow && c == startCol) {
                        count++;
                    }
                }
            }
            return count;
        }

        /**
         * Performs BFS to find if a path exists from start to end.
         * Iterative BFS avoids StackOverflowError on large maps.
         */
        private boolean hasPathBFS(int startRow, int startCol, int endRow, int endCol) {
            Queue<int[]> queue = new LinkedList<>();
            boolean[][] visited = new boolean[rows][cols];

            queue.add(new int[]{startRow, startCol});
            visited[startRow][startCol] = true;

            while (!queue.isEmpty()) {
                int[] current = queue.poll();
                int r = current[0];
                int c = current[1];

                for (int[] dir : DIRECTIONS) {
                    int nextR = r + dir[0];
                    int nextC = c + dir[1];

                    if (isValid(nextR, nextC) && !visited[nextR][nextC]) {
                        // If the neighbor is the destination, path is found.
                        // This allows reaching the destination regardless of its character.
                        if (nextR == endRow && nextC == endCol) {
                            return true;
                        }

                        // If the neighbor is an empty path cell, add to queue for further exploration.
                        if (grid[nextR][nextC] == '.') {
                            visited[nextR][nextC] = true;
                            queue.add(new int[]{nextR, nextC});
                        }
                    }
                }
            }

            return false;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }
}

