/**
 * Logic for solving the grid reachability problem.
 */
class GridPathfinder {
    private static final int[] ROW_DIRECTIONS = {0, 0, 1, -1};
    private static final int[] COL_DIRECTIONS = {1, -1, 0, 0};

    private final FastReader reader;
    private int rows;
    private int cols;
    private boolean[][] isCracked;
    private boolean[][] visited;
    private int startRow, startCol;
    private int endRow, endCol;

    public GridPathfinder(FastReader reader) {
        this.reader = reader;
    }

    /**
     * Orchestrates the reading of input and execution of the pathfinding logic.
     */
    public void solve(PrintWriter out) {
        readInput();

        // Edge Case: Start and end positions are the same
        if (isStartSameAsEnd()) {
            out.println(canMoveFromStartToAdjacentNonCracked() ? "YES" : "NO");
            return;
        }

        performFloodFill(startRow, startCol);

        if (isEndCracked()) {
            out.println(visited[endRow][endCol] ? "YES" : "NO");
        } else {
            out.println(evaluateNonCrackedEnd() ? "YES" : "NO");
        }
    }

    private void readInput() {
        rows = reader.nextInt();
        cols = reader.nextInt();
        isCracked = new boolean[rows][cols];
        visited = new boolean[rows][cols];

        for (int i = 0; i < rows; i++) {
            String line = reader.next();
            for (int j = 0; j < cols; j++) {
                isCracked[i][j] = (line.charAt(j) == 'X');
            }
        }

        // Convert 1-based indexing to 0-based
        startRow = reader.nextInt() - 1;
        startCol = reader.nextInt() - 1;
        endRow = reader.nextInt() - 1;
        endCol = reader.nextInt() - 1;
    }

    private void performFloodFill(int r, int c) {
        visited[r][c] = true;

        for (int i = 0; i < 4; i++) {
            int nextR = r + ROW_DIRECTIONS[i];
            int nextC = c + COL_DIRECTIONS[i];

            if (isValid(nextR, nextC) && !visited[nextR][nextC]) {
                // We can only move into a cracked cell if it is the destination
                boolean isDestination = (nextR == endRow && nextC == endCol);
                boolean canEnter = !isCracked[nextR][nextC] || isDestination;

                if (canEnter) {
                    // If it's cracked (and thus the destination), we mark it visited but don't recurse further
                    if (isCracked[nextR][nextC]) {
                        visited[nextR][nextC] = true;
                    } else {
                        performFloodFill(nextR, nextC);
                    }
                }
            }
        }
    }

    private boolean evaluateNonCrackedEnd() {
        int neighborCountRequirement = 0;
        boolean hasVisitedNeighbor = false;

        for (int i = 0; i < 4; i++) {
            int nextR = endRow + ROW_DIRECTIONS[i];
            int nextC = endCol + COL_DIRECTIONS[i];

            if (isValid(nextR, nextC)) {
                if (visited[nextR][nextC]) {
                    hasVisitedNeighbor = true;
                }
                // Check if neighbor is the starting cell or is not cracked
                if (nextR == startRow && nextC == startCol || !isCracked[nextR][nextC]) {
                    neighborCountRequirement++;
                }
            }
        }
        return neighborCountRequirement >= 2 && hasVisitedNeighbor;
    }

    private boolean isStartSameAsEnd() {
        return startRow == endRow && startCol == endCol;
    }

    private boolean canMoveFromStartToAdjacentNonCracked() {
        for (int i = 0; i < 4; i++) {
            int nextR = startRow + ROW_DIRECTIONS[i];
            int nextC = startCol + COL_DIRECTIONS[i];
            if (isValid(nextR, nextC) && !isCracked[nextR][nextC]) {
                return true;
            }
        }
        return false;
    }

    private boolean isEndCracked() {
        return isCracked[endRow][endCol];
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

