import java.util.*;

/**
 * A program to determine if a path exists between two points in a 2D grid.
 */
public class GridPathfinder {

    /**
     * Represents a coordinate in the 2D grid.
     */
    private static class Point {
        private final int row;
        private final int col;

        public Point(int row, int col) {
            this.row = row;
            this.col = col;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            Point point = (Point) o;
            return row == point.row && col == point.col;
        }

        @Override
        public int hashCode() {
            return Objects.hash(row, col);
        }
    }

    /**
     * Represents the game board/grid.
     */
    private static class Grid {
        private final char[][] cells;
        private final int rows;
        private final int cols;

        public Grid(int rows, int cols, String[] inputLines) {
            this.rows = rows;
            this.cols = cols;
            this.cells = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                this.cells[i] = inputLines[i].toCharArray();
            }
        }

        public int getRows() { return rows; }
        public int getCols() { return cols; }

        public boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        public boolean isTraversable(int r, int c, Point target) {
            if (!isWithinBounds(r, c)) {
                return false;
            }
            // A cell is traversable if it is a path ('.') or if it is the destination.
            return cells[r][c] == '.' || new Point(r, c).equals(target);
        }
    }

    /**
     * Contains the logic for searching the grid.
     */
    private static class Pathfinder {
        private static final int[][] DIRECTIONS = {
            {0, 1},  // Right
            {0, -1}, // Left
            {1, 0},  // Down
            {-1, 0}  // Up
        };

        /**
         * Uses Depth First Search to find if a path exists from start to end.
         */
        public boolean hasPath(Grid grid, Point start, Point end) {
            if (!grid.isWithinBounds(start.row, start.col) || 
                !grid.isWithinBounds(end.row, end.col)) {
                return false;
            }

            // If start is already the end
            if (start.equals(end)) {
                return true;
            }

            Deque<Point> stack = new ArrayDeque<>();
            boolean[][] visited = new boolean[grid.getRows()][grid.getCols()];

            stack.push(start);

            while (!stack.isEmpty()) {
                Point current = stack.pop();

                if (current.equals(end)) {
                    return true;
                }

                if (visited[current.row][current.col]) {
                    continue;
                }

                visited[current.row][current.col] = true;

                for (int[] dir : DIRECTIONS) {
                    int nextRow = current.row + dir[0];
                    int nextCol = current.col + dir[1];
                    Point nextPoint = new Point(nextRow, nextCol);

                    if (grid.isTraversable(nextRow, nextCol, end) && !visited[nextRow][nextCol]) {
                        stack.push(nextPoint);
                    }
                }
            }

            return false;
        }
    }

    /**
     * Main entry point for the application.
     */
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        try {
            if (!scanner.hasNextInt()) return;
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            String[] gridLines = new String[rows];
            for (int i = 0; i < rows; i++) {
                gridLines[i] = scanner.next();
            }

            // Convert 1-based indexing from input to 0-based indexing
            Point start = new Point(scanner.nextInt() - 1, scanner.nextInt() - 1);
            Point end = new Point(scanner.nextInt() - 1, scanner.nextInt() - 1);

            Grid grid = new Grid(rows, cols, gridLines);
            Pathfinder pathfinder = new Pathfinder();

            boolean found = pathfinder.hasPath(grid, start, end);
            System.out.println(found ? "YES" : "NO");

        } catch (Exception e) {
            // In a real application, use a logger and handle specific exceptions
            System.err.println("Error processing input: " + e.getMessage());
        } finally {
            scanner.close();
        }
    }
}

