import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

/**
 * Solves the grid reachability problem based on specific movement and target rules.
 */
public class GridPathfinder {

    private static final char OBSTACLE = 'X';
    private static final char PASSABLE = '.';

    public static void main(String[] args) {
        FastReader reader = new FastReader();

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] gridData = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                gridData[i] = reader.readLine().toCharArray();
            }

            Grid grid = new Grid(gridData);

            Point start = reader.nextPoint();
            Point target = reader.nextPoint();

            Solver solver = new Solver(grid);
            String result = solver.solve(start, target);
            System.out.println(result);

        } catch (Exception e) {
            // In a production environment, use a logger.
            // For competitive programming, we can exit or handle gracefully.
        }
    }

    /**
     * Represents a coordinate in the 2D grid.
     */
    static class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }

        @Override
        public boolean equals(Object obj) {
            if (this == obj) return true;
            if (!(obj instanceof Point)) return false;
            Point other = (Point) obj;
            return this.x == other.x && this.y == other.y;
        }
    }

    /**
     * Encapsulates the grid structure and basic spatial queries.
     */
    static class Grid {
        private final char[][] cells;
        private final int rows;
        private final int cols;

        // Direction vectors for 4-way movement (Up, Right, Down, Left)
        private static final int[] DX = {-1, 0, 1, 0};
        private static final int[] DY = {0, 1, 0, -1};

        Grid(char[][] cells) {
            this.cells = cells;
            this.rows = cells.length;
            this.cols = cells[0].length;
        }

        public int getRows() { return rows; }
        public int getCols() { return cols; }

        public boolean isWithinBounds(int x, int y) {
            return x >= 0 && x < rows && y >= 0 && y < cols;
        }

        public char getCell(int x, int y) {
            return cells[x][y];
        }

        public boolean isSpecial(int x, int y) {
            return cells[x][y] == OBSTACLE;
        }

        public boolean isPassable(int x, int y) {
            return cells[x][y] == PASSABLE;
        }

        public boolean areAdjacent(Point p1, Point p2) {
            for (int i = 0; i < 4; i++) {
                if (p1.x + DX[i] == p2.x && p1.y + DY[i] == p2.y) {
                    return true;
                }
            }
            return false;
        }

        /**
         * Returns neighbors that are passable ('.').
         */
        public List<Point> getPassableNeighbors(int x, int y) {
            List<Point> neighbors = new ArrayList<>();
            for (int i = 0; i < 4; i++) {
                int nx = x + DX[i];
                int ny = y + DY[i];
                if (isWithinBounds(nx, ny) && isPassable(nx, ny)) {
                    neighbors.add(new Point(nx, ny));
                }
            }
            return neighbors;
        }

        /**
         * Returns all valid adjacent coordinates regardless of cell type.
         */
        public List<Point> getAllNeighbors(int x, int y) {
            List<Point> neighbors = new ArrayList<>();
            for (int i = 0; i < 4; i++) {
                int nx = x + DX[i];
                int ny = y + DY[i];
                if (isWithinBounds(nx, ny)) {
                    neighbors.add(new Point(nx, ny));
                }
            }
            return neighbors;
        }
    }

    /**
     * Contains the core logic for solving the reachability problem.
     */
    static class Solver {
        private final Grid grid;

        Solver(Grid grid) {
            this.grid = grid;
        }

        public String solve(Point start, Point target) {
            int targetPassableNeighbors = grid.getPassableNeighbors(target.x, target.y).size();
            boolean targetIsSpecial = grid.isSpecial(target.x, target.y);

            // Condition 1: Start and Target are adjacent and target satisfies special properties
            if (grid.areAdjacent(start, target)) {
                if (targetIsSpecial || targetPassableNeighbors > 0) {
                    return "YES";
                }
            }

            // Condition 2: Target is special or has many neighbors, check reachability from start
            if (targetIsSpecial || targetPassableNeighbors > 1) {
                boolean[][] visited = new boolean[grid.getRows()][grid.getCols()];
                visited[start.x][start.y] = true;
                performDfs(start, visited);

                // Check if any neighbor of the target has been visited
                for (Point neighbor : grid.getAllNeighbors(target.x, target.y)) {
                    if (visited[neighbor.x][neighbor.y]) {
                        return "YES";
                    }
                }
            }

            return "NO";
        }

        private void performDfs(Point current, boolean[][] visited) {
            for (Point neighbor : grid.getPassableNeighbors(current.x, current.y)) {
                if (!visited[neighbor.x][neighbor.y]) {
                    visited[neighbor.x][neighbor.y] = true;
                    performDfs(neighbor, visited);
                }
            }
        }
    }

    /**
     * Utility class for fast I/O operations.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader() {
            reader = new BufferedReader(new InputStreamReader(System.in));
        }

        public String readLine() throws IOException {
            return reader.readLine();
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public Point nextPoint() throws IOException {
            // Coordinates are 1-indexed in input, convert to 0-indexed
            int x = nextInt() - 1;
            int y = nextInt() - 1;
            return new Point(x, y);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to determine if a path exists through a cave grid based on specific movement rules.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            char[][] grid = new char[rows][];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            // Coordinates are 1-indexed in input, converted to 0-indexed
            int startRow = reader.nextInt() - 1;
            int startCol = reader.nextInt() - 1;
            int endRow = reader.nextInt() - 1;
            int endCol = reader.nextInt() - 1;

            CaveSolver solver = new CaveSolver(grid, rows, cols, startRow, startCol, endRow, endCol);
            System.out.println(solver.solve() ? "YES" : "NO");

        } catch (Exception e) {
            // In a production environment, use a logger
            e.printStackTrace();
        }
    }

    /**
     * Contains the logic for navigating the cave.
     */
    static class CaveSolver {
        private final char[][] grid;
        private final int rows;
        private final int cols;
        private final int startRow;
        private final int startCol;
        private final int endRow;
        private final int endCol;

        private static final int[][] DIRECTIONS = {
            {1, 0}, {-1, 0}, {0, 1}, {0, -1}
        };

        public CaveSolver(char[][] grid, int rows, int cols, int startRow, int startCol, int endRow, int endCol) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
            this.startRow = startRow;
            this.startCol = startCol;
            this.endRow = endRow;
            this.endCol = endCol;
        }

        /**
         * Executes the logic to determine if the destination is reachable.
         */
        public boolean solve() {
            // Case 1: Start is the same as the end
            if (startRow == endRow && startCol == endCol) {
                return hasDotNeighbor(startRow, startCol);
            }

            // Case 2: Start is adjacent to the end
            if (isAdjacent(startRow, startCol, endRow, endCol)) {
                if (grid[endRow][endCol] == 'X') {
                    return true;
                }
                return hasDotNeighbor(endRow, endCol);
            }

            // Case 3: General pathfinding via BFS
            if (runBfs()) {
                // If target is a '.', it must have at least two '.' neighbors to be valid
                if (grid[endRow][endCol] == '.') {
                    return countDotNeighbors(endRow, endCol) >= 2;
                }
                return true;
            }

            return false;
        }

        private boolean runBfs() {
            Deque<Point> queue = new ArrayDeque<>();
            boolean[][] visited = new boolean[rows][cols];

            queue.add(new Point(startRow, startCol));
            visited[startRow][startCol] = true;

            while (!queue.isEmpty()) {
                Point current = queue.poll();

                if (current.r == endRow && current.c == endCol) {
                    return true;
                }

                for (int[] dir : DIRECTIONS) {
                    int nextR = current.r + dir[0];
                    int nextC = current.c + dir[1];

                    if (canMoveTo(nextR, nextC) && !visited[nextR][nextC]) {
                        visited[nextR][nextC] = true;
                        queue.add(new Point(nextR, nextC));
                    }
                }
            }
            return false;
        }

        private boolean canMoveTo(int r, int c) {
            if (!isInBounds(r, c)) return false;
            // Can move to any '.' or the specific target 'X'
            if (grid[r][c] == '.') return true;
            if (r == endRow && c == endCol && grid[r][c] == 'X') return true;
            return false;
        }

        private boolean isDot(int r, int c) {
            return isInBounds(r, c) && grid[r][c] == '.';
        }

        private boolean isInBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        private boolean isAdjacent(int r1, int c1, int r2, int c2) {
            return Math.abs(r1 - r2) + Math.abs(c1 - c2) == 1;
        }

        private int countDotNeighbors(int r, int c) {
            int count = 0;
            for (int[] dir : DIRECTIONS) {
                if (isDot(r + dir[0], c + dir[1])) {
                    count++;
                }
            }
            return count;
        }

        private boolean hasDotNeighbor(int r, int c) {
            return countDotNeighbors(r, c) > 0;
        }
    }

    /**
     * Represents a coordinate in the grid.
     */
    static class Point {
        final int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Helper class for efficient input reading.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;

/**
 * A professional refactor of the C540 grid pathfinding program.
 * This program determines if a path exists between two points in a grid.
 */
public class GridPathfinder {

    /**
     * Represents a single coordinate point in the 2D grid.
     */
    private static class Point {
        final int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Handles the navigation logic and pathfinding algorithms within a grid.
     */
    public static class Navigator {
        private final int rows;
        private final int cols;
        private final char[][] grid;

        // Directions for traversing: Right, Left, Down, Up
        private static final int[][] DIRECTIONS = {
            {0, 1}, {0, -1}, {1, 0}, {-1, 0}
        };

        public Navigator(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
        }

        /**
         * Checks if a path exists from the starting point to the target point.
         * 
         * @param startR Starting row (0-indexed).
         * @param startC Starting column (0-indexed).
         * @param endR   Target row (0-indexed).
         * @param endC   Target column (0-indexed).
         * @return true if a path exists, false otherwise.
         */
        public boolean hasPath(int startR, int startC, int endR, int endC) {
            if (isOutOfBounds(startR, startC) || isOutOfBounds(endR, endC)) {
                return false;
            }

            // Edge Case: If start and end are the same, the original logic requires 
            // moving to an adjacent empty cell ('.') to return "YES".
            if (startR == endR && startC == endC) {
                return hasAdjacentEmptyCell(startR, startC);
            }

            return performBFS(startR, startC, endR, endC);
        }

        /**
         * Performs a Breadth-First Search to find a path to the target.
         */
        private boolean performBFS(int startR, int startC, int endR, int endC) {
            Queue<Point> queue = new ArrayDeque<>();
            boolean[][] visited = new boolean[rows][cols];

            queue.offer(new Point(startR, startC));
            visited[startR][startC] = true;

            while (!queue.isEmpty()) {
                Point current = queue.poll();

                for (int[] dir : DIRECTIONS) {
                    int nr = current.r + dir[0];
                    int nc = current.c + dir[1];

                    if (isOutOfBounds(nr, nc) || visited[nr][nc]) {
                        continue;
                    }

                    // If we have reached the target cell, path found.
                    if (nr == endR && nc == endC) {
                        return true;
                    }

                    // If the cell is a valid path ('.'), explore it.
                    if (grid[nr][nc] == '.') {
                        visited[nr][nc] = true;
                        queue.offer(new Point(nr, nc));
                    }
                }
            }

            return false;
        }

        private boolean hasAdjacentEmptyCell(int r, int c) {
            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (!isOutOfBounds(nr, nc) && grid[nr][nc] == '.') {
                    return true;
                }
            }
            return false;
        }

        private boolean isOutOfBounds(int r, int c) {
            return r < 0 || r >= rows || c < 0 || c >= cols;
        }
    }

    /**
     * Main entry point of the program. Handles I/O and initializes the navigator.
     */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;

            int n = scanner.nextInt();
            int m = scanner.nextInt();

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                grid[i] = scanner.next().toCharArray();
            }

            // Convert 1-based input coordinates to 0-based indices
            int r1 = scanner.nextInt() - 1;
            int c1 = scanner.nextInt() - 1;
            int r2 = scanner.nextInt() - 1;
            int c2 = scanner.nextInt() - 1;

            Navigator navigator = new Navigator(n, m, grid);
            boolean isPossible = navigator.hasPath(r1, c1, r2, c2);

            System.out.println(isPossible ? "YES" : "NO");
        } catch (Exception e) {
            // In a real-world application, use a Logger instead of printStackTrace
            System.err.println("An error occurred during execution: " + e.getMessage());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A solution to determine if a specific path condition is met on a grid.
 * The logic involves BFS traversal and a connectivity check on the destination cell.
 */
public class Solution {

    // Direction vectors for 4-way movement (Right, Left, Up, Down)
    private static final int[] ROW_DIRECTIONS = {0, 0, -1, 1};
    private static final int[] COL_DIRECTIONS = {1, -1, 0, 0};

    public static void main(String[] args) {
        try {
            new Solution().execute();
        } catch (IOException e) {
            System.err.println("Error processing input: " + e.getMessage());
        }
    }

    /**
     * Entry point for the solution execution.
     */
    public void execute() throws IOException {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        int rows = reader.nextInt();
        int cols = reader.nextInt();

        if (rows <= 0 || cols <= 0) {
            writer.println("NO");
            writer.close();
            return;
        }

        boolean[][] isPassable = readGrid(reader, rows, cols);

        // Input coordinates are 1-indexed in the original problem
        int startRow = reader.nextInt() - 1;
        int startCol = reader.nextInt() - 1;
        int endRow = reader.nextInt() - 1;
        int endCol = reader.nextInt() - 1;

        boolean result = solve(rows, cols, isPassable, startRow, startCol, endRow, endCol);
        writer.println(result ? "YES" : "NO");
        writer.close();
    }

    /**
     * Reads the grid from input.
     * '.' represents a passable/solid cell, 'X' represents an obstacle.
     */
    private boolean[][] readGrid(FastReader reader, int rows, int cols) throws IOException {
        boolean[][] grid = new boolean[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = reader.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = (line.charAt(j) == '.');
            }
        }
        return grid;
    }

    /**
     * Core logic to determine if the pathing criteria are met.
     */
    private boolean solve(int rows, int cols, boolean[][] isPassable, 
                          int startR, int startC, int endR, int endC) {

        // Case 1: Start and End are the same location
        if (startR == endR && startC == endC) {
            return hasAnyPassableNeighbor(rows, cols, isPassable, startR, startC);
        }

        // Case 2: Check if a path exists using BFS
        if (!hasPath(rows, cols, isPassable, startR, startC, endR, endC)) {
            return false;
        }

        // Case 3: If path exists, check destination properties
        // If the destination itself is an obstacle ('X'), the condition is satisfied
        if (!isPassable[endR][endC]) {
            return true;
        }

        // If destination is passable ('.'), it must meet a connectivity degree requirement
        return checkDestinationConnectivity(rows, cols, isPassable, startR, startC, endR, endC);
    }

    private boolean hasAnyPassableNeighbor(int rows, int cols, boolean[][] isPassable, int r, int c) {
        for (int i = 0; i < 4; i++) {
            int nr = r + ROW_DIRECTIONS[i];
            int nc = c + COL_DIRECTIONS[i];
            if (isWithinBounds(rows, cols, nr, nc) && isPassable[nr][nc]) {
                return true;
            }
        }
        return false;
    }

    private boolean hasPath(int rows, int cols, boolean[][] isPassable, 
                            int startR, int startC, int endR, int endC) {
        boolean[][] visited = new boolean[rows][cols];
        Queue<Point> queue = new LinkedList<>();

        queue.add(new Point(startR, startC));
        visited[startR][startC] = true;

        while (!queue.isEmpty()) {
            Point curr = queue.poll();

            if (curr.row == endR && curr.col == endC) {
                return true;
            }

            for (int i = 0; i < 4; i++) {
                int nr = curr.row + ROW_DIRECTIONS[i];
                int nc = curr.col + COL_DIRECTIONS[i];

                if (isWithinBounds(rows, cols, nr, nc) && !visited[nr][nc]) {
                    // Path can traverse passable cells OR the destination cell itself
                    if (isPassable[nr][nc] || (nr == endR && nc == endC)) {
                        visited[nr][nc] = true;
                        queue.add(new Point(nr, nc));
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if the destination cell has more than one "valid" connection.
     * A connection is valid if it is a passable cell OR the starting cell.
     */
    private boolean checkDestinationConnectivity(int rows, int cols, boolean[][] isPassable, 
                                                 int startR, int startC, int endR, int endC) {
        int connectivityCount = 0;
        for (int i = 0; i < 4; i++) {
            int nr = endR + ROW_DIRECTIONS[i];
            int nc = endC + COL_DIRECTIONS[i];

            boolean isStartCell = (nr == startR && nc == startC);
            boolean isPassableNeighbor = isWithinBounds(rows, cols, nr, nc) && isPassable[nr][nc];

            if (isStartCell || isPassableNeighbor) {
                connectivityCount++;
            }
        }
        return connectivityCount > 1;
    }

    private boolean isWithinBounds(int rows, int cols, int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Simple data structure to represent grid coordinates.
     */
    private static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Efficient reader for large inputs using BufferedReader and StringTokenizer.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * GridPathSolver determines if a path exists between a start and target coordinate
 * in a grid, subject to specific connectivity rules.
 */
public class GridPathSolver {

    // Direction vectors for Up, Down, Left, and Right movements
    private static final int[] ROW_DIRECTIONS = {0, -1, 0, 1};
    private static final int[] COL_DIRECTIONS = {-1, 0, 1, 0};

    public static void main(String[] args) {
        String filePath = args.length > 0 ? args[0] : null;
        try {
            execute(filePath);
        } catch (IOException e) {
            System.err.println("Critical I/O Error: " + e.getMessage());
        }
    }

    /**
     * Orchestrates the input reading, logic application, and output.
     */
    private static void execute(String filePath) throws IOException {
        FastReader reader = new FastReader(filePath);

        // 1. Parse Grid Dimensions
        Integer rows = reader.nextInt();
        Integer cols = reader.nextInt();
        if (rows == null || cols == null) return;

        // 2. Parse Grid Layout
        boolean[][] isPathGrid = new boolean[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = reader.nextLine();
            if (line != null) {
                for (int j = 0; j < cols; j++) {
                    if (j < line.length()) {
                        isPathGrid[i][j] = (line.charAt(j) == '.');
                    }
                }
            }
        }

        // 3. Parse Coordinates (Expected 1-indexed)
        Integer startR = reader.nextInt();
        Integer startC = reader.nextInt();
        Integer targetR = reader.nextInt();
        Integer targetC = reader.nextInt();

        if (startR == null || startC == null || targetR == null || targetC == null) return;

        // Convert to 0-indexed
        int sR = startR - 1;
        int sC = startC - 1;
        int tR = targetR - 1;
        int tC = targetC - 1;

        // 4. Apply connectivity constraints
        boolean canAttemptPath = checkInitialPossibility(isPathGrid, sR, sC, tR, tC, rows, cols);

        // 5. Perform Pathfinding
        boolean isTargetReached = false;
        if (canAttemptPath) {
            isTargetReached = performBFS(isPathGrid, sR, sC, tR, tC, rows, cols);
        }

        System.out.println(isTargetReached ? "YES" : "NO");
    }

    /**
     * Replicates the original program's specific logic regarding target cell connectivity.
     */
    private static boolean checkInitialPossibility(boolean[][] grid, int sR, int sC, int tR, int tC, int rows, int cols) {
        // If target is out of bounds or not a path cell, the original logic defaults to 'true'
        if (!isWithinBounds(tR, tC, rows, cols) || !grid[tR][tC]) {
            return true;
        }

        int pathNeighborCount = 0;
        for (int d = 0; d < 4; d++) {
            int nR = tR + ROW_DIRECTIONS[d];
            int nC = tC + COL_DIRECTIONS[d];
            if (isWithinBounds(nR, nC, rows, cols) && grid[nR][nC]) {
                pathNeighborCount++;
            }
        }

        // Original rule: if target is a path cell, it must have >= 2 path neighbors,
        // unless that one neighbor is the starting cell.
        if (pathNeighborCount < 2) {
            if (pathNeighborCount == 1) {
                for (int d = 0; d < 4; d++) {
                    int nR = tR + ROW_DIRECTIONS[d];
                    int nC = tC + COL_DIRECTIONS[d];
                    if (nR == sR && nC == sC) return true;
                }
            }
            return false;
        }

        return true;
    }

    /**
     * Iterative BFS to find if the target cell is reachable.
     * A neighbor is considered traversable if it is a path cell ('.') or the target cell itself.
     */
    private static boolean performBFS(boolean[][] grid, int sR, int sC, int tR, int tC, int rows, int cols) {
        boolean[][] visited = new boolean[rows][cols];
        Queue<int[]> queue = new ArrayDeque<>();

        // Initialize queue with neighbors of the starting cell to match original DFS behavior
        for (int d = 0; d < 4; d++) {
            int nR = sR + ROW_DIRECTIONS[d];
            int nC = sC + COL_DIRECTIONS[d];

            if (isWithinBounds(nR, nC, rows, cols)) {
                if (grid[nR][nC] || (nR == tR && nC == tC)) {
                    if (!visited[nR][nC]) {
                        visited[nR][nC] = true;
                        queue.add(new int[]{nR, nC});
                    }
                }
            }
        }

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int currR = current[0];
            int currC = current[1];

            if (currR == tR && currC == tC) {
                return true;
            }

            for (int d = 0; d < 4; d++) {
                int nR = currR + ROW_DIRECTIONS[d];
                int nC = currC + COL_DIRECTIONS[d];

                if (isWithinBounds(nR, nC, rows, cols) && !visited[nR][nC]) {
                    // Traversable if '.' OR target
                    if (grid[nR][nC] || (nR == tR && nC == tC)) {
                        visited[nR][nC] = true;
                        queue.add(new int[]{nR, nC});
                    }
                }
            }
        }

        return visited[tR][tC];
    }

    private static boolean isWithinBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(String filePath) throws IOException {
            if (filePath == null) {
                reader = new BufferedReader(new InputStreamReader(System.in));
            } else {
                reader = new BufferedReader(new FileReader(filePath));
            }
