    /**
     * Encapsulates the maze logic and state.
     */
    static class MazeSolver {
        private final char[][] grid;
        private final int rows;
        private final int cols;
        private final boolean[][] visited;

        private boolean pathFound = false;

        // Direction vectors for moving: Down, Up, Right, Left
        private static final int[] DR = {1, -1, 0, 0};
        private static final int[] DC = {0, 0, 1, -1};

        public MazeSolver(char[][] grid, int rows, int cols) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
            this.visited = new boolean[rows][cols];
        }

        /**
         * Core logic to determine if the task requirements are met.
         */
        public boolean solve(int startRow, int startCol, int endRow, int endCol) {
            // The original logic modifies the start cell to be walkable
            grid[startRow][startCol] = '.';

            // Search for a path from the end point back to the start point
            performDfs(endRow, endCol, startRow, startCol);

            // Case 1: Start and end are the same
            if (startRow == endRow && startCol == endCol) {
                return countAdjacentEmptyCells(startRow, startCol) > 0;
            }

            // Case 2: A path was found
            if (pathFound) {
                // If the destination was originally an 'X' (boundary)
                if (grid[endRow][endCol] == 'X') {
                    return true;
                }
                // Or if the destination has multiple exits/entries
                return countAdjacentEmptyCells(endRow, endCol) > 1;
            }

            return false;
        }

        /**
         * Recursive Depth First Search to find connectivity.
         */
        private void performDfs(int r, int c, int targetR, int targetC) {
            if (r == targetR && c == targetC) {
                pathFound = true;
            }

            visited[r][c] = true;

            for (int i = 0; i < 4; i++) {
                int nextR = r + DR[i];
                int nextC = c + DC[i];

                if (isValidMove(nextR, nextC)) {
                    performDfs(nextR, nextC, targetR, targetC);
                }
            }
        }

        private boolean isValidMove(int r, int c) {
            return r >= 0 && r < rows && 
                   c >= 0 && c < cols && 
                   !visited[r][c] && 
                   grid[r][c] == '.';
        }

        /**
         * Counts how many adjacent cells are empty ('.').
         */
        private int countAdjacentEmptyCells(int r, int c) {
            int count = 0;
            for (int i = 0; i < 4; i++) {
                int nr = r + DR[i];
                int nc = c + DC[i];
                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == '.') {
                    count++;
                }
            }
            return count;
        }
    }

