 * This class determines if a path exists from a starting point to a target point
 * in a grid based on specific movement and exit rules.
 */
public class IcePathSolverApp {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));

        try {
