            if (solver.solve()) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            out.close();
        }
    }

    /**
     * Represents a coordinate point in the grid.
     */
    private record Point(int row, int col) {}

    /**
     * Handles the core pathfinding logic.
     */
    private static class IcePathSolver {
        private static final int[][] DIRECTIONS = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final int startRow;
        private final int startCol;
        private final int targetRow;
        private final int targetCol;

        public IcePathSolver(int rows, int cols, char[][] grid, int startRow, int startCol, int targetRow, int targetCol) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            this.startRow = startRow;
            this.startCol = startCol;
            this.targetRow = targetRow;
            this.targetCol = targetCol;
        }

        /**
         * Executes the solver logic.
         * @return true if a valid path is found, false otherwise.
         */
        public boolean solve() {
            // The starting cell is always treated as traversable.
            grid[startRow][startCol] = '.';

            // Edge case: Start is the target.
            if (startRow == targetRow && startCol == targetCol) {
                return countAdjacentEmptyCells(startRow, startCol) > 0;
            }

            return performBFS();
        }

        private boolean performBFS() {
            Queue<Point> queue = new ArrayDeque<>();
            boolean[][] visited = new boolean[rows][cols];

            queue.offer(new Point(startRow, startCol));
            visited[startRow][startCol] = true;

            while (!queue.isEmpty()) {
                Point current = queue.poll();

                for (int[] dir : DIRECTIONS) {
                    int nextRow = current.row() + dir[0];
                    int nextCol = current.col() + dir[1];

                    if (isWithinBounds(nextRow, nextCol)) {
                        // Check if we have reached the target cell.
                        if (nextRow == targetRow && nextCol == targetCol) {
                            if (canExitTarget(nextRow, nextCol)) {
                                return true;
                            }
                        } 
                        // Otherwise, continue BFS through empty cells.
                        else if (grid[nextRow][nextCol] == '.' && !visited[nextRow][nextCol]) {
                            visited[nextRow][nextCol] = true;
                            queue.offer(new Point(nextRow, nextCol));
                        }
                    }
                }
            }
            return false;
        }

        private boolean canExitTarget(int r, int c) {
            // The target is valid if it was originally an 'X' or 
            // if it has more than one adjacent empty cell.
            return grid[r][c] == 'X' || countAdjacentEmptyCells(r, c) > 1;
        }

        private int countAdjacentEmptyCells(int r, int c) {
            int count = 0;
            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (isWithinBounds(nr, nc) && grid[nr][nc] == '.') {
                    count++;
                }
            }
            return count;
        }

        private boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * Optimized utility class for reading input.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
