/**
 * A class to find paths in a grid based on specific connectivity rules.
 */
public class GridPathFinder {

    private static final int[] ROW_OFFSETS = {-1, 1, 0, 0};
    private static final int[] COL_OFFSETS = {0, 0, -1, 1};

    private final char[][] grid;
    private final int rows;
    private final int cols;
    private final int startRow;
    private final int startCol;
    private final int endRow;
    private final int endCol;
    private final char destinationValue;

    private final boolean[][] visited;
    private int pathCount = 0;

    public GridPathFinder(int rows, int cols, char[][] grid, 
                          int startRow, int startCol, 
                          int endRow, int endCol) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.startRow = startRow;
        this.startCol = startCol;
        this.endRow = endRow;
        this.endCol = endCol;
        this.destinationValue = grid[endRow][endCol];
        this.visited = new boolean[rows][cols];
    }

    /**
     * Executes the pathfinding logic.
     * @return true if the path criteria are met, false otherwise.
     */
    public boolean solve() {
        // To mimic original behavior: ensure start and end are treated as traversable
        // even if they were originally walls ('X').
        char originalStartChar = grid[startRow][startCol];
        char originalEndChar = grid[endRow][endCol];

        grid[startRow][startCol] = '.';
        grid[endRow][endCol] = '.';

        performDfs(startRow, startCol);

        boolean conditionOne = (pathCount >= 1) && (destinationValue == 'X') 
                && (startCol != endCol || startRow != endRow);
        boolean conditionTwo = (pathCount >= 2);

        return conditionOne || conditionTwo;
    }

    /**
     * Depth First Search to explore the grid.
     */
    private void performDfs(int r, int c) {
        // Check if we reached the destination
        if (r == endRow && c == endCol) {
            pathCount++;
            // Specific exit condition from the original implementation
            if (destinationValue == 'X' && (startCol != endCol || startRow != endRow)) {
                return;
            }
        }

        // Check for walls or already visited cells
        if (grid[r][c] == 'X' || visited[r][c]) {
            return;
        }

        // Mark current cell as visited
        visited[r][c] = true;

        // Explore neighbors
        for (int i = 0; i < 4; i++) {
            int nextR = r + ROW_OFFSETS[i];
            int nextC = c + COL_OFFSETS[i];

            if (isWithinBounds(nextR, nextC)) {
                performDfs(nextR, nextC);
            }
        }
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

