/**
 * Handles the core logic for determining if a specific path condition is met in the maze.
 */
class MazeSolver {
    private final char[][] grid;
    private final int rows;
    private final int cols;
    private final int startR;
    private final int startC;
    private final int targetR;
    private final int targetC;

    private static final int[] DR = {1, -1, 0, 0};
    private static final int[] DC = {0, 0, 1, -1};

    public MazeSolver(char[][] grid, int startR, int startC, int targetR, int targetC) {
        this.grid = grid;
        this.rows = grid.length;
        this.cols = grid[0].length;
        this.startR = startR;
        this.startC = startC;
        this.targetR = targetR;
        this.targetC = targetC;
    }

    /**
     * Executes the solver logic based on the original problem requirements.
     */
    public boolean solve() {
        // Create a working copy to simulate the modification of the start cell
        char[][] workingGrid = copyGrid(grid);
        workingGrid[startR][startC] = '.';

        // Count neighbors of the target that are '.' in the working grid
        int emptyNeighborCount = countEmptyNeighbors(workingGrid, targetR, targetC);

        // Case 1: Start and Target are the same
        if (startR == targetR && startC == targetC) {
            return emptyNeighborCount >= 1;
        }

        // Case 2: Check if target is reachable via DFS
        boolean isReachable = canReachTarget(workingGrid);
        if (!isReachable) {
            return false;
        }

        // Case 3: Check specialized conditions for "YES"
        // Condition A: Target was originally 'X'
        // Condition B: Target has at least 2 '.' neighbors
        boolean targetWasOriginallyX = (grid[targetR][targetC] == 'X');
        return targetWasOriginallyX || emptyNeighborCount >= 2;
    }

    private boolean canReachTarget(char[][] workingGrid) {
        boolean[][] visited = new boolean[rows][cols];
        return dfs(workingGrid, startR, startC, visited);
    }

    private boolean dfs(char[][] workingGrid, int r, int c, boolean[][] visited) {
        if (r < 0 || r >= rows || c < 0 || c >= cols || visited[r][c] || workingGrid[r][c] == 'X') {
            return false;
        }

        if (r == targetR && c == targetC) {
            return true;
        }

        visited[r][c] = true;

        for (int i = 0; i < 4; i++) {
            if (dfs(workingGrid, r + DR[i], c + DC[i], visited)) {
                return true;
            }
        }

        return false;
    }

    private int countEmptyNeighbors(char[][] grid, int r, int c) {
        int count = 0;
        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];
            if (isValid(nr, nc) && grid[nr][nc] == '.') {
                count++;
            }
        }
        return count;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private char[][] copyGrid(char[][] original) {
        char[][] copy = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            System.arraycopy(original[i], 0, copy[i], 0, cols);
        }
        return copy;
    }
}

