import java.util.*;
import java.io.*;

/**
 * Represents a coordinate point in the grid.
 */
record Point(int x, int y) {}

/**
 * Handles navigation logic within a 2D grid.
 */
class GridNavigator {
    private final char[][] grid;
    private final int rows;
    private final int cols;

    private static final int[][] DIRECTIONS = {
        {0, 1},  // Right
        {0, -1}, // Left
        {1, 0},  // Down
        {-1, 0}  // Up
    };

    public GridNavigator(char[][] grid) {
        this.grid = grid;
        this.rows = grid.length;
        this.cols = grid[0].length;
    }

    /**
     * Determines if there is a path from the start point to the target point.
     * A path can consist of any cell that is not an obstacle ('X'), 
     * or the target cell itself (even if it is an 'X').
     */
    public boolean canReach(Point start, Point target) {
        // If start is already at the target, return true immediately.
        if (start.equals(target)) {
            return true;
        }

        Queue<Point> queue = new LinkedList<>();
        boolean[][] visited = new boolean[rows][cols];

        queue.add(start);
        visited[start.x()][start.y()] = true;

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            // Check if we have reached the destination
            if (current.equals(target)) {
                return true;
            }

            for (int[] dir : DIRECTIONS) {
                int nextX = current.x() + dir[0];
                int nextY = current.y() + dir[1];

                if (isValidMove(nextX, nextY, target, visited)) {
                    visited[nextX][nextY] = true;
                    queue.add(new Point(nextX, nextY));
                }
            }
        }

        return false;
    }

    private boolean isValidMove(int x, int y, Point target, boolean[][] visited) {
        // 1. Check bounds
        if (x < 0 || x >= rows || y < 0 || y >= cols) {
            return false;
        }

        // 2. Check if already visited
        if (visited[x][y]) {
            return false;
        }

        // 3. Check if traversable:
        // A cell is traversable if it is not an obstacle OR if it is the target destination.
        boolean isTarget = (x == target.x() && y == target.y());
        boolean isNotObstacle = grid[x][y] != 'X';

        return isTarget || isNotObstacle;
    }
}

/**
 * Main entry point for the application.
 */
public class Main {

    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            if (!sc.hasNextInt()) return;

            int rows = sc.nextInt();
            int cols = sc.nextInt();
            sc.nextLine(); // Consume the remaining newline

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = sc.nextLine().toCharArray();
            }

            // Input coordinates are 1-indexed in the original program
            int startX = sc.nextInt() - 1;
            int startY = sc.nextInt() - 1;
            int targetX = sc.nextInt() - 1;
            int targetY = sc.nextInt() - 1;

            Point start = new Point(startX, startY);
            Point target = new Point(targetX, targetY);

            GridNavigator navigator = new GridNavigator(grid);
