/**
 * Handles the pathfinding logic using Depth First Search with memoization.
 */
class IceCaveSolver {
    private static final char EMPTY_CELL = '.';
    private static final char OBSTACLE_CELL = 'X';

    private final int rows;
    private final int cols;
    private final char[][] grid;

    // deadEnd[r][c] is true if this cell has been explored and doesn't lead to the target
    private final boolean[][] deadEnd;
    // inCurrentPath[r][c] is true if we are currently visiting this cell in the recursive stack
    private final boolean[][] inCurrentPath;

    public IceCaveSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.deadEnd = new boolean[rows][cols];
        this.inCurrentPath = new boolean[rows][cols];
    }

    /**
     * Initiates the search from start position to target position.
     */
    public boolean solve(int startRow, int startCol, int targetRow, int targetCol) {
        // The problem states the starting cell is treated as passable
        grid[startRow][startCol] = EMPTY_CELL;
        return dfs(startRow, startCol, targetRow, targetCol);
    }

    private boolean dfs(int r, int c, int tr, int tc) {
        // 1. Bounds Check
        if (r < 0 || r >= rows || c < 0 || c >= cols) {
            return false;
        }

        // 2. Target Reached Check
        // Note: The target check is performed before obstacle/visited checks per original logic
        if (r == tr && c == tc) {
            return evaluateTargetCondition(tr, tc);
        }

        // 3. Pruning: Check if cell is an obstacle, part of current path (cycle), or a known dead end
        if (grid[r][c] == OBSTACLE_CELL || inCurrentPath[r][c] || deadEnd[r][c]) {
            return false;
        }

        // 4. Mark cell as part of the current traversal path
        inCurrentPath[r][c] = true;

        // 5. Recursive exploration of 4-directional neighbors
        if (dfs(r - 1, c, tr, tc) || // Up
            dfs(r + 1, c, tr, tc) || // Down
            dfs(r, c - 1, tr, tc) || // Left
            dfs(r, c + 1, tr, tc)) { // Right
            return true;
        }

        // 6. Backtrack and Memoize
        // If no path was found from this cell, mark it as a dead end to avoid re-processing
        inCurrentPath[r][c] = false;
        deadEnd[r][c] = true;
        return false;
    }

    /**
     * Implements the specific target reachability logic from the original requirement.
     */
    private boolean evaluateTargetCondition(int tr, int tc) {
        // If target is an obstacle, it is considered reached
        if (grid[tr][tc] == OBSTACLE_CELL) {
            return true;
        }

        // Otherwise, target is reached if it's adjacent to an empty cell
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int i = 0; i < 4; i++) {
            int nr = tr + dr[i];
            int nc = tc + dc[i];
            if (isValid(nr, nc) && grid[nr][nc] == EMPTY_CELL) {
                return true;
            }
        }
        return false;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

