/**
 * IceCave determines if a path exists between two points in a grid.
 * The grid consists of passable ('.') and impassable cells.
 */
public class IceCave {

    /**
     * Represents a coordinate in the 2D grid.
     * Using a record ensures immutability and correct equality checks for the BFS queue.
     */
    public record Point(int row, int col) {}

    /**
     * Encapsulates the grid data and provides boundary and passability checks.
     */
    public static class Maze {
        private final int rows;
        private final int cols;
        private final char[][] grid;

        public Maze(int rows, int cols, Scanner scanner) {
            this.rows = rows;
            this.cols = cols;
            this.grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = scanner.next();
                if (line.length() < cols) {
                    throw new IllegalArgumentException("Grid row length mismatch.");
                }
                grid[i] = line.toCharArray();
            }
        }

        public boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        public boolean isPassable(int r, int c) {
            return isWithinBounds(r, c) && grid[r][c] == '.';
        }

        public int getRows() { return rows; }
        public int getCols() { return cols; }
    }

    /**
     * Provides pathfinding capabilities using the Breadth-First Search (BFS) algorithm.
     */
    public static class PathFinder {
        private static final int[][] DIRECTIONS = {{1, 0}, {0, -1}, {-1, 0}, {0, 1}};

        /**
         * Determines if there is a path from the start point to the end point.
         *
         * @param maze  The grid to traverse.
         * @param start The starting Point.
         * @param end   The destination Point.
         * @return true if a path exists, false otherwise.
         */
        public boolean hasPath(Maze maze, Point start, Point end) {
            if (!maze.isWithinBounds(start.row(), start.col()) || 
                !maze.isWithinBounds(end.row(), end.col())) {
                return false;
            }

            if (start.equals(end)) {
                return true;
            }

            Queue<Point> queue = new LinkedList<>();
            boolean[][] visited = new boolean[maze.getRows()][maze.getCols()];

            queue.add(start);
            visited[start.row()][start.col()] = true;

            while (!queue.isEmpty()) {
                Point current = queue.poll();

                for (int[] dir : DIRECTIONS) {
                    int nextRow = current.row() + dir[0];
                    int nextCol = current.col() + dir[1];
                    Point nextPoint = new Point(nextRow, nextCol);

                    if (maze.isWithinBounds(nextRow, nextCol) && !visited[nextRow][nextCol]) {
                        // Check if the neighbor is the destination
                        if (nextPoint.equals(end)) {
                            return true;
                        }

                        // If the cell is a valid path, add it to the exploration queue
                        if (maze.isPassable(nextRow, nextCol)) {
                            visited[nextRow][nextCol] = true;
                            queue.add(nextPoint);
                        }
                    }
                }
            }

            return false;
        }
    }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;

            int n = scanner.nextInt();
            int m = scanner.nextInt();

            Maze maze = new Maze(n, m, scanner);

            // Coordinates are provided as 1-indexed; convert to 0-indexed for logic.
            Point start = new Point(scanner.nextInt() - 1, scanner.nextInt() - 1);
            Point end = new Point(scanner.nextInt() - 1, scanner.nextInt() - 1);

            PathFinder pathFinder = new PathFinder();
            boolean exists = pathFinder.hasPath(maze, start, end);

            System.out.println(exists ? "YES" : "NO");
        } catch (Exception e) {
            // In a production environment, replace with proper logging.
            System.err.println("An error occurred during execution: " + e.getMessage());
        }
    }
}

