            }

        } catch (Exception e) {
            // In a production environment, use a logger
        } finally {
            writer.close();
        }
    }

    /**
     * Handles the core logic of the grid traversal problem.
     */
    static class GridNavigator {
        private static final int[] DR = {-1, 1, 0, 0};
        private static final int[] DC = {0, 0, -1, 1};

        private final char[][] grid;
        private final int rows;
        private final int cols;
        private final int targetRow;
        private final int targetCol;
        private final boolean[][] visited;

        public GridNavigator(char[][] grid, int rows, int cols, int targetRow, int targetCol) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
            this.targetRow = targetRow;
            this.targetCol = targetCol;
            this.visited = new boolean[rows][cols];
        }

        /**
         * Executes the business logic to determine if the target is "reachable"
         * based on the specific problem rules.
         */
        public boolean solve(int startRow, int startCol) {
            if (startRow == targetRow && startCol == targetCol) {
                return countDotNeighbors(startRow, startCol) >= 1;
            }

            if (isNeighbor(startRow, startCol, targetRow, targetCol)) {
                if (grid[targetRow][targetCol] == 'X') {
                    return true;
                } else {
                    return countDotNeighbors(targetRow, targetCol) >= 1;
                }
            }

            // General case: Not same, not neighbors
            if (performDfs(startRow, startCol)) {
                if (grid[targetRow][targetCol] == 'X') {
                    return true;
                } else {
                    return countDotNeighbors(targetRow, targetCol) >= 2;
                }
            }

            return false;
        }

        /**
         * Standard DFS to find reachability. 
         * Note: As per original logic, it can "reach" an 'X' if it is adjacent to a '.'
         */
        private boolean performDfs(int r, int c) {
            visited[r][c] = true;
            if (r == targetRow && c == targetCol) {
                return true;
            }

            for (int i = 0; i < 4; i++) {
                int nr = r + DR[i];
                int nc = c + DC[i];

                if (isWithinBounds(nr, nc)) {
                    // If this neighbor is the target, we've reached it (even if it's 'X')
                    if (nr == targetRow && nc == targetCol) {
                        return true;
                    }
                    // Otherwise, we can only move into '.' cells
                    if (grid[nr][nc] == '.' && !visited[nr][nc]) {
                        if (performDfs(nr, nc)) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        private int countDotNeighbors(int r, int c) {
            int count = 0;
            for (int i = 0; i < 4; i++) {
                int nr = r + DR[i];
                int nc = c + DC[i];
                if (isWithinBounds(nr, nc) && grid[nr][nc] == '.') {
                    count++;
                }
            }
            return count;
        }

        private boolean isNeighbor(int r1, int c1, int r2, int c2) {
            return Math.abs(r1 - r2) + Math.abs(c1 - c2) == 1;
        }

        private boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * Fast I/O utility.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

