/**
 * A solver for the Ice Cave reachability problem using Breadth-First Search.
 */
public class Main {

    /**
     * Represents a coordinate in the 2D grid.
     */
    private record Point(int row, int col) {}

    /**
     * Logic handler for the Ice Cave exploration.
     */
    static class IceCaveSolver {
        private static final int[][] DIRECTIONS = {
            {-1, 0}, // Up
            {1, 0},  // Down
            {0, -1}, // Left
            {0, 1}   // Right
        };

        private final char[][] grid;
        private final int rows;
        private final int cols;

        public IceCaveSolver(char[][] grid) {
            this.grid = grid;
            this.rows = grid.length;
            this.cols = grid[0].length;
        }

        /**
         * Determines if there is a path from the start point to the end point.
         *
         * @param start The starting coordinate.
         * @param end   The target coordinate.
         * @return true if the destination is reachable, false otherwise.
         */
        public boolean canReachDestination(Point start, Point end) {
            // If start and end are the same, we are already there.
            if (start.equals(end)) {
                return true;
            }

            Queue<Point> queue = new LinkedList<>();
            boolean[][] visited = new boolean[rows][cols];

            queue.add(start);
            visited[start.row][start.col] = true;

            while (!queue.isEmpty()) {
                Point current = queue.poll();

                for (int[] dir : DIRECTIONS) {
                    int nextRow = current.row + dir[0];
                    int nextCol = current.col + dir[1];

                    if (isValidMove(nextRow, nextCol, visited)) {
                        // Check if we have reached the destination
                        if (nextRow == end.row() && nextCol == end.col()) {
                            return true;
                        }

                        // If the cell is not an obstacle ('X'), add it to the queue
                        if (grid[nextRow][nextCol] != 'X') {
                            visited[nextRow][nextCol] = true;
                            queue.add(new Point(nextRow, nextCol));
                        }
                    }
                }
            }

            return false;
        }

        private boolean isValidMove(int r, int c, boolean[][] visited) {
            return r >= 0 && r < rows && 
                   c >= 0 && c < cols && 
                   !visited[r][c];
        }
    }

