/**
 * A program to determine if a path exists in a grid from a start point to a target point.
 * 'X' represents an obstacle, while any other character represents a traversable path.
 */
public class GridPathfinder {

    /**
     * Represents a coordinate in the 2D grid.
     */
    public record Point(int row, int col) {}

    /**
     * Handles the core pathfinding logic using Breadth-First Search (BFS).
     */
    public static class Solver {
        private static final int[] ROW_OFFSETS = {0, 0, 1, -1};
        private static final int[] COL_OFFSETS = {1, -1, 0, 0};

        /**
         * Finds if there is a path from start to target.
         * 
         * @param grid   The 2D grid of characters.
         * @param start  The starting point.
         * @param target The destination point.
         * @return true if target is reachable, false otherwise.
         */
        public boolean canReachTarget(char[][] grid, Point start, Point target) {
            int rows = grid.length;
            int cols = grid[0].length;

            // Immediate success if start is the target
            if (start.equals(target)) {
                return true;
            }

            Queue<Point> queue = new LinkedList<>();
            boolean[][] visited = new boolean[rows][cols];

            // Initial check: If start is an obstacle, we cannot move (unless start == target)
            if (grid[start.row()][start.col()] == 'X') {
                return false;
            }

            queue.add(start);
            visited[start.row()][start.col()] = true;

            while (!queue.isEmpty()) {
                Point current = queue.poll();

                for (int i = 0; i < 4; i++) {
                    int nextRow = current.row() + ROW_OFFSETS[i];
                    int nextCol = current.col() + COL_OFFSETS[i];
                    Point neighbor = new Point(nextRow, nextCol);

                    if (isValidMove(grid, rows, cols, nextRow, nextCol)) {
                        // If the neighbor is the target, we've succeeded.
                        // This works even if the target itself is an 'X'.
                        if (neighbor.equals(target)) {
                            return true;
                        }

                        // If it's a valid path and not visited, continue BFS
                        if (!visited[nextRow][nextCol] && grid[nextRow][nextCol] != 'X') {
                            visited[nextRow][nextCol] = true;
                            queue.add(neighbor);
                        }
                    }
                }
            }

            return false;
        }

        private boolean isValidMove(char[][] grid, int rows, int cols, int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * Fast I/O utility class to handle large inputs efficiently.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) {
        // Using System.in for standard input. 
        // To use files, one would pass a FileInputStream(new File("input.txt"))
        FastReader fr = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            String firstToken = fr.next();
            if (firstToken == null) return;

            int rows = Integer.parseInt(firstToken);
            int cols = fr.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = fr.next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }

            // Convert 1-based indexing from input to 0-based indexing
            Point start = new Point(fr.nextInt() - 1, fr.nextInt() - 1);
            Point target = new Point(fr.nextInt() - 1, fr.nextInt() - 1);

            Solver solver = new Solver();
            if (solver.canReachTarget(grid, start, target)) {
                out.println("YES");
            } else {
                out.println("NO");
            }

        } catch (Exception e) {
            // In a production environment, use a proper Logger
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }
}

