/**
 * Manages the grid boundaries and walkability.
 */
class Grid {
    private final int rows;
    private final int cols;
    private final boolean[][] walkableCells;

    public Grid(int rows, int cols, boolean[][] walkableCells) {
        this.rows = rows;
        this.cols = cols;
        this.walkableCells = walkableCells;
    }

    public int getRows() { return rows; }
    public int getCols() { return cols; }

    public boolean isWalkable(Cell cell) {
        return isValid(cell.getRow(), cell.getCol()) && walkableCells[cell.getRow()][cell.getCol()];
    }

    public boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    public boolean isValid(Cell cell) {
