    }
}

/**
 * Contains the BFS algorithm and the specific problem-solving logic.
 */
class MazeSolver {
    private static final int[][] DIRECTIONS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    private final Grid grid;
    private final Cell start;
    private final Cell end;

    public MazeSolver(Grid grid, Cell start, Cell end) {
        this.grid = grid;
        this.start = start;
        this.end = end;
    }

    /**
     * Solves the maze based on the specific movement rules provided.
     */
    public boolean solve() {
        if (isAtDestination()) {
            return hasAdjacentWalkableCell(start);
        }

        if (grid.isWalkable(end)) {
            return checkNeighborsOfEnd();
        } else {
            return performBfs(null);
        }
    }

    private boolean isAtDestination() {
        return start.equals(end);
    }

    private boolean hasAdjacentWalkableCell(Cell cell) {
        for (int[] dir : DIRECTIONS) {
            int nr = cell.getRow() + dir[0];
            int nc = cell.getCol() + dir[1];
            if (grid.isValid(nr, nc) && grid.isWalkable(new Cell(nr, nc))) {
                return true;
            }
        }
        return false;
    }

    private boolean checkNeighborsOfEnd() {
        for (int[] dir : DIRECTIONS) {
            int nr = end.getRow() + dir[0];
            int nc = end.getCol() + dir[1];
            Cell neighbor = new Cell(nr, nc);
            if (grid.isValid(neighbor) && grid.isWalkable(neighbor)) {
                if (performBfs(neighbor)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Standard BFS implementation with specific expansion rules.
     * 
     * @param excludedCell A cell to be marked as visited before the BFS starts.
     * @return true if the end cell is reachable.
     */
    private boolean performBfs(Cell excludedCell) {
        Queue<Cell> queue = new LinkedList<>();
        boolean[][] visited = new boolean[grid.getRows()][grid.getCols()];

        if (excludedCell != null) {
            visited[excludedCell.getRow()][excludedCell.getCol()] = true;
        }

        queue.add(start);
        visited[start.getRow()][start.getCol()] = true;

        while (!queue.isEmpty()) {
            Cell current = queue.poll();

            if (current.equals(end)) {
                return true;
            }

            // Logic Rule: Can only move from a cell if it is the start or it is walkable ('.')
            if (current.equals(start) || grid.isWalkable(current)) {
                for (int[] dir : DIRECTIONS) {
                    int nr = current.getRow() + dir[0];
                    int nc = current.getCol() + dir[1];
                    Cell neighbor = new Cell(nr, nc);

                    if (grid.isValid(neighbor) && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        queue.add(neighbor);
                    }
                }
            }
        }
        return false;
    }
}

