import java.util.*;

/**
 * A utility to determine if a path exists between two points in a grid-based maze.
 */
public class MazeSolver {

    /**
     * Represents a coordinate point in the 2D grid.
     * Using a record for immutability and automatic equals/hashCode implementation.
     */
    public record Point(int row, int col) {}

    /**
     * Directional offsets for moving Up, Down, Left, and Right.
     */
    private static final int[][] DIRECTIONS = {
        {1, 0}, {-1, 0}, {0, 1}, {0, -1}
    };

    private static final char PATH = '.';
    private static final char WALL = 'X';

    /**
     * Solves the reachability problem using Breadth-First Search (BFS).
     *
     * @param in  The fast reader for input.
     * @param out The PrintWriter for output.
     * @throws IOException if an I/O error occurs.
     */
    public void solve(FastReader in, PrintWriter out) throws IOException {
        int rows = in.nextInt();
        int cols = in.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = in.next().toCharArray();
        }

        // Coordinates are 1-indexed in input, converting to 0-indexed
        Point start = new Point(in.nextInt() - 1, in.nextInt() - 1);
        Point end = new Point(in.nextInt() - 1, in.nextInt() - 1);

        if (isPathFound(grid, start, end)) {
            out.println("YES");
        } else {
            out.println("NO");
        }
    }

    /**
     * Performs BFS to find if there is a path from start to end.
     * 
     * @param grid The maze grid.
     * @param start Starting point.
     * @param end Target point.
     * @return true if a path exists, false otherwise.
     */
    private boolean isPathFound(char[][] grid, Point start, Point end) {
        int rows = grid.length;
        int cols = grid[0].length;

        // Basic boundary/validity check
        if (isInvalid(grid, start) || isInvalid(grid, end)) {
            return false;
        }

        if (start.equals(end)) {
            return true;
        }

        Queue<Point> queue = new LinkedList<>();
        boolean[][] visited = new boolean[rows][cols];

        queue.add(start);
        visited[start.row][start.col] = true;

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            for (int[] dir : DIRECTIONS) {
                int nextRow = current.row() + dir[0];
                int nextCol = current.col() + dir[1];
                Point neighbor = new Point(nextRow, nextCol);

                if (neighbor.equals(end)) {
                    return true;
                }

                if (isValidMove(grid, visited, nextRow, nextCol)) {
                    visited[nextRow][nextCol] = true;
                    queue.add(neighbor);
                }
            }
        }

        return false;
    }

    private boolean isInvalid(char[][] grid, Point p) {
        return p.row() < 0 || p.row() >= grid.length || 
               p.col() < 0 || p.col() >= grid[0].length || 
               grid[p.row()][p.col()] == WALL;
    }

    private boolean isValidMove(char[][] grid, boolean[][] visited, int r, int c) {
        return r >= 0 && r < grid.length && 
               c >= 0 && c < grid[0].length && 
               grid[r][c] == PATH && 
               !visited[r][c];
    }

    public static void main(String[] args) throws IOException {
        FastReader in = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        MazeSolver solver = new MazeSolver();
        solver.solve(in, out);

        out.flush();
        out.close();
    }

    /**
     * Efficient reader for large input datasets.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

