class GridSolver {
    private final char[][] grid;
    private final int rows;
    private final int cols;
    private final boolean[][] visited;
    private boolean isPathFound = false;

    private static final int[][] DIRECTIONS = {
        {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    public GridSolver(char[][] grid, int rows, int cols) {
        this.grid = grid;
        this.rows = rows;
        this.cols = cols;
        this.visited = new boolean[rows][cols];
    }

    /**
     * Initiates the pathfinding process.
     */
    public boolean solve(int startR, int startC, int endR, int endC) {
        // Edge case: Start and end are the same cell
        if (startR == endR && startC == endC) {
            return hasAtLeastOneEmptyNeighbor(startR, startC);
        }

        // As per original logic: treat the starting cell as an empty cell '.'
        grid[startR][startC] = '.';

        performDfs(startR, startC, endR, endC);
        return isPathFound;
    }

    /**
     * Depth First Search to traverse the grid.
     */
    private void performDfs(int r, int c, int targetR, int targetC) {
        // Base case: Out of bounds or already visited
        if (isOutOfBounds(r, c) || visited[r][c]) {
            return;
        }

        visited[r][c] = true;

        // Check if we have reached the destination cell
        if (r == targetR && c == targetC) {
            evaluateTargetCell(r, c);
            return;
        }

        // If the current cell is not a path ('.'), we cannot traverse through it
        if (grid[r][c] != '.') {
            return;
        }

        // Explore adjacent cells
        for (int[] dir : DIRECTIONS) {
            int nextR = r + dir[0];
            int nextC = c + dir[1];

            performDfs(nextR, nextC, targetR, targetC);

            // Optimization: If path is already found, stop searching
            if (isPathFound) {
                return;
            }
        }
    }

    /**
     * Logic to determine if reaching the target cell counts as a success.
     */
    private void evaluateTargetCell(int r, int c) {
        if (grid[r][c] != '.') {
            // If target is a wall/obstacle, reaching it is a success
            isPathFound = true;
        } else {
            // If target is an empty cell, it must have at least 2 empty neighbors to be a valid junction
            if (countEmptyNeighbors(r, c) >= 2) {
                isPathFound = true;
            }
        }
    }

    private boolean hasAtLeastOneEmptyNeighbor(int r, int c) {
        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            if (!isOutOfBounds(nr, nc) && grid[nr][nc] == '.') {
                return true;
            }
        }
        return false;
    }

    private int countEmptyNeighbors(int r, int c) {
        int count = 0;
        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            if (!isOutOfBounds(nr, nc) && grid[nr][nc] == '.') {
                count++;
            }
        }
        return count;
    }

    private boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= rows || c < 0 || c >= cols;
    }
}

