                System.out.println("NO");
                return;
            }

            GridSolver solver = new GridSolver(grid, rows, cols);
            boolean result = solver.solve(startRow, startCol, endRow, endCol);
            System.out.println(result ? "YES" : "NO");

        } catch (Exception e) {
            // In a real-world scenario, replace with a proper logging framework
        }
    }

    private static boolean isOutOfBounds(int r, int c, int rows, int cols) {
        return r < 0 || r >= rows || c < 0 || c >= cols;
    }

    /**
     * FastReader provides efficient input reading using BufferedReader and StringTokenizer.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            return next != null ? Integer.parseInt(next) : 0;
        }
    }

    /**
     * GridSolver encapsulates the grid traversal logic and state.
     */
    static class GridSolver {
        private final char[][] grid;
        private final int rows;
        private final int cols;
        private final boolean[][] visited;
        private boolean success = false;

        // Direction vectors for North, South, East, West
        private static final int[] DR = {1, -1, 0, 0};
        private static final int[] DC = {0, 0, 1, -1};

        public GridSolver(char[][] grid, int rows, int cols) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
            this.visited = new boolean[rows][cols];
        }

        /**
         * Entry point for solving the grid problem.
         */
        public boolean solve(int startR, int startC, int endR, int endC) {
            // Edge case: Start position is identical to End position
            if (startR == endR && startC == endC) {
                return checkStartIsEnd(startR, startC, endR, endC);
            }

            // Start DFS traversal
            visited[startR][startC] = true;
            dfs(startR, startC, endR, endC);

            return success;
        }

        private boolean checkStartIsEnd(int r, int c, int endR, int endC) {
            for (int i = 0; i < 4; i++) {
                int nr = r + DR[i];
                int nc = c + DC[i];
                // The original logic requires a valid '.' neighbor
                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == '.') {
                    return true;
                }
            }
            return false;
        }

        private void dfs(int r, int c, int endR, int endC) {
            if (success) return;

            // If current cell is the target destination
            if (r == endR && c == endC) {
                evaluateTarget(r, c, endR, endC);
                return;
            }

            for (int i = 0; i < 4; i++) {
                int nr = r + DR[i];
                int nc = c + DC[i];

                if (isValidMove(nr, nc, endR, endC)) {
                    visited[nr][nc] = true;
                    dfs(nr, nc, endR, endC);
                    if (success) return;
                }
            }
        }

        /**
         * Determines if a neighbor is a valid cell to step into.
         * If the neighbor is the target and is an 'X', it triggers success.
         */
        private boolean isValidMove(int nr, int nc, int endR, int endC) {
            if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) {
                return false;
            }

            // If we detect the target is an 'X' while checking neighbors, success is possible
            if (nr == endR && nc == endC && grid[nr][nc] == 'X') {
                success = true;
                return false;
            }

            return !visited[nr][nc] && grid[nr][nc] == '.';
        }

        /**
         * Evaluates the specific connectivity rules required when the '.' target is reached.
         */
        private void evaluateTarget(int r, int c, int endR, int endC) {
            int dotNeighborCount = 0;
            boolean hasXNeighbor = false;

            for (int i = 0; i < 4; i++) {
                int nr = r + DR[i];
                int nc = c + DC[i];

                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
                    if (grid[nr][nc] == 'X') {
                        hasXNeighbor = true;
                    } else if (grid[nr][nc] == '.') {
                        dotNeighborCount++;
                    }
                }
            }

            // The target '.' is considered valid if it has an 'X' neighbor 
            // or more than one '.' neighbor (including the one we used to arrive).
            if (hasXNeighbor || dotNeighborCount > 1) {
                success = true;
            }
        }
    }
}

import java.util.Scanner;

/**
 * A refactored solution for grid pathfinding with specific destination constraints.
 * The goal is to find a path from a starting coordinate to a target coordinate
 * while respecting the terrain ('.' or 'X') and specific target requirements.
 */
public class GridPathfinder {

    // Direction vectors for moving Up, Down, Left, Right
    private static final int[][] DIRECTIONS = {
        {0, -1}, {-1, 0}, {0, 1}, {1, 0}
    };

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int targetRow;
    private final int targetCol;
    private final int targetAdjacentDots;

    // Memoization table to store results of sub-problems (true/false)
    private final Boolean[][] memo;
    // Tracks cells in the current recursion stack to prevent infinite cycles
    private final boolean[][] visiting;

    /**
     * Initializes the pathfinder with grid dimensions, the grid itself, and target constraints.
     */
    public GridPathfinder(int rows, int cols, char[][] grid, int targetRow, int targetCol) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.targetRow = targetRow;
        this.targetCol = targetCol;
        this.targetAdjacentDots = countAdjacentDots(targetRow, targetCol);
        this.memo = new Boolean[rows][cols];
        this.visiting = new boolean[rows][cols];
    }

    /**
     * Entry point for the pathfinding algorithm.
     * @param startRow Starting row index.
     * @param startCol Starting column index.
     * @return true if a valid path exists, false otherwise.
     */
    public boolean solve(int startRow, int startCol) {
        return dfs(startRow, startCol);
    }

    /**
     * Depth-First Search with Memoization and Backtracking.
     */
    private boolean dfs(int r, int c) {
        // 1. Boundary check
        if (!isWithinBounds(r, c)) {
            return false;
        }

        // 2. Check if we have reached the destination
        if (r == targetRow && c == targetCol) {
            return satisfiesTargetCondition(r, c);
        }

        // 3. Check if the cell is a wall ('X') or already being visited in the current path
        // Note: According to the original logic, 'X' cells cannot be traversed as intermediate steps.
        if (grid[r][c] == 'X' || visiting[r][c]) {
            return false;
        }

        // 4. Check memoization table to see if we have already calculated this cell
        if (memo[r][c] != null) {
            return memo[r][c];
        }

        // 5. Mark as visiting and explore neighbors
        visiting[r][c] = true;
        boolean canReachTarget = false;

        for (int[] dir : DIRECTIONS) {
            int nextR = r + dir[0];
            int nextC = c + dir[1];
            if (dfs(nextR, nextC)) {
                canReachTarget = true;
                break;
            }
        }

        // 6. Backtrack: unmark visiting and store result in memo
        visiting[r][c] = false;
        memo[r][c] = canReachTarget;

        return canReachTarget;
    }

    /**
     * Validates if the destination cell satisfies the specific requirements
     * based on its character and the number of adjacent '.' cells.
     */
    private boolean satisfiesTargetCondition(int r, int c) {
        char cellValue = grid[r][c];
        if (cellValue == 'X') {
            return targetAdjacentDots > 0;
        } else {
            // cellValue == '.'
            return targetAdjacentDots > 1;
        }
    }

    /**
     * Counts how many adjacent cells contain the '.' character.
     */
    private int countAdjacentDots(int r, int c) {
        int count = 0;
        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            if (isWithinBounds(nr, nc) && grid[nr][nc] == '.') {
                count++;
            }
        }
        return count;
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String rowString = scanner.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = rowString.charAt(j);
            }
        }

        // Input coordinates are 1-indexed, convert to 0-indexed
        int startR = scanner.nextInt() - 1;
        int startC = scanner.nextInt() - 1;
        int endR = scanner.nextInt() - 1;
        int endC = scanner.nextInt() - 1;

        GridPathfinder pathfinder = new GridPathfinder(rows, cols, grid, endR, endC);

        if (pathfinder.solve(startR, startC)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }
}

