/**
 * Represents the layout of the Ice Cave.
 */
class IceCaveGrid {
    private final boolean[][] obstacles;
    private final int rows;
    private final int cols;

    public IceCaveGrid(int rows, int cols, boolean[][] obstacles) {
        this.rows = rows;
        this.cols = cols;
        this.obstacles = obstacles;
    }

    public int getRows() {
        return rows;
    }

    public int getCols() {
        return cols;
    }

    public boolean isObstacle(int r, int c) {
        return obstacles[r][c];
    }

    public boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    public void setObstacle(int r, int c, boolean isObstacle) {
        if (isWithinBounds(r, c)) {
            obstacles[r][c] = isObstacle;
        }
    }
}

/**
 * Handles pathfinding logic within an IceCaveGrid.
 */
class Pathfinder {
    private final IceCaveGrid grid;

    public Pathfinder(IceCaveGrid grid) {
        this.grid = grid;
    }

    /**
     * Determines if there is a path from the start to the destination.
     */
    public boolean canReachDestination(int startR, int startC, int destR, int destC) {
        boolean[][] visited = new boolean[grid.getRows()][grid.getCols()];
        return dfs(startR, startC, destR, destC, visited);
    }

    private boolean dfs(int r, int c, int destR, int destC, boolean[][] visited) {
        // 1. Boundary and Validity Check
        if (!grid.isWithinBounds(r, c) || grid.isObstacle(r, c) || visited[r][c]) {
            return false;
        }

        // 2. Destination Check
        if (r == destR && c == destC) {
            return true;
        }

        // 3. Mark as visited to prevent infinite loops and redundant processing
        visited[r][c] = true;

        // 4. Explore neighbors (Down, Up, Right, Left)
        if (dfs(r + 1, c, destR, destC, visited) ||
            dfs(r - 1, c, destR, destC, visited) ||
            dfs(r, c + 1, destR, destC, visited) ||
            dfs(r, c - 1, destR, destC, visited)) {
            return true;
        }

        return false;
    }
}

