            // Input Grid
            boolean[][] obstacleMap = new boolean[rows][cols];
            for (int i = 0; i < rows; i++) {
                String rowString = scanner.next();
                for (int j = 0; j < cols; j++) {
                    obstacleMap[i][j] = (rowString.charAt(j) == 'X');
                }
            }

            // Input Positions (Converting 1-based to 0-based indexing)
            int startRow = scanner.nextInt() - 1;
            int startCol = scanner.nextInt() - 1;
            int destRow = scanner.nextInt() - 1;
            int destCol = scanner.nextInt() - 1;

            // Initialize the grid and ensure starting position is passable
            IceCaveGrid caveGrid = new IceCaveGrid(rows, cols, obstacleMap);
            caveGrid.setObstacle(startRow, startCol, false);

            // Perform pathfinding
            Pathfinder pathfinder = new Pathfinder(caveGrid);
            boolean isPathPossible = pathfinder.canReachDestination(startRow, startCol, destRow, destCol);

            // Output Result
            System.out.println(isPathPossible ? "YES" : "NO");
        } catch (Exception e) {
            System.err.println("An error occurred while processing the input: " + e.getMessage());
        }
    }
}

