/**
 * Represents a coordinate on the 2D grid.
 */
record Point(int row, int col) {}

/**
 * Encapsulates the pathfinding logic using Breadth-First Search.
 */
class Pathfinder {
    private static final int[] ROW_OFFSETS = {0, 0, 1, -1};
    private static final int[] COL_OFFSETS = {1, -1, 0, 0};
    private static final char WALL = '#'; // Standard convention for walls

    /**
     * Determines if a path exists between start and end points.
     *
     * @param grid  The 2D character grid.
     * @param start The starting Point.
     * @param end   The target Point.
     * @return true if a path exists, false otherwise.
     */
    public boolean hasPath(char[][] grid, Point start, Point end) {
        int rows = grid.length;
        int cols = grid[0].length;

        // Validate bounds and initial conditions
        if (isOutOfBounds(start, rows, cols) || isOutOfBounds(end, rows, cols)) {
            return false;
        }
        if (grid[start.row()][start.col()] == WALL || grid[end.row()][end.col()] == WALL) {
            return false;
        }
        if (start.equals(end)) {
            return true;
        }

        Queue<Point> queue = new LinkedList<>();
        boolean[][] visited = new boolean[rows][cols];

        queue.add(start);
        visited[start.row()][start.col()] = true;

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            for (int i = 0; i < 4; i++) {
                int nextRow = current.row() + ROW_OFFSETS[i];
                int nextCol = current.col() + COL_OFFSETS[i];
                Point neighbor = new Point(nextRow, nextCol);

                if (isValidMove(grid, visited, neighbor, rows, cols)) {
                    if (neighbor.equals(end)) {
                        return true;
                    }
                    visited[nextRow][nextCol] = true;
                    queue.add(neighbor);
                }
            }
        }

        return false;
    }

    private boolean isValidMove(char[][] grid, boolean[][] visited, Point p, int rows, int cols) {
        return !isOutOfBounds(p, rows, cols) 
                && !visited[p.row()][p.col()] 
                && grid[p.row()][p.col()] != WALL;
    }

    private boolean isOutOfBounds(Point p, int rows, int cols) {
        return p.row() < 0 || p.row() >= rows || p.col() < 0 || p.col() >= cols;
    }
}

/**
 * Orchestrates the reading of input and execution of the task.
 */
class TaskSolver {
    private final Pathfinder pathfinder = new Pathfinder();

    public void solve(Scanner scanner, PrintWriter writer) {
        if (!scanner.hasNextInt()) return;

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        scanner.nextLine(); // Consume newline

