 */
record Point(int row, int col) {}

/**
 * Handles the logic for finding a path through a grid using Breadth-First Search.
 */
class GridPathfinder {
    private static final int[][] DIRECTIONS = {
        {0, 1}, {0, -1}, {1, 0}, {-1, 0}
    };
    private static final char OBSTACLE = 'X';

    /**
     * Solves the pathfinding problem.
     * 
     * @param in   The input reader.
     * @param out  The output writer.
     */
    public void solve(FastReader in, PrintWriter out) {
        int rows = in.nextInt();
        int cols = in.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = in.next().toCharArray();
        }

        // Convert 1-based indexing from input to 0-based indexing
        int startRow = in.nextInt() - 1;
        int startCol = in.nextInt() - 1;
        int targetRow = in.nextInt() - 1;
        int targetCol = in.nextInt() - 1;

        if (canReachTarget(grid, rows, cols, new Point(startRow, startCol), new Point(targetRow, targetCol))) {
            out.println("YES");
        } else {
            out.println("NO");
        }
    }

    /**
     * Performs a BFS to determine if a path exists between start and target.
     */
    private boolean canReachTarget(char[][] grid, int rows, int cols, Point start, Point target) {
        // Edge case: start is target
        if (start.equals(target)) {
            return true;
        }

        // Check if start or target are out of bounds or obstacles
        if (isInvalid(grid, rows, cols, start) || isInvalid(grid, rows, cols, target)) {
            return false;
        }

        Queue<Point> queue = new ArrayDeque<>();
        boolean[][] visited = new boolean[rows][cols];

        queue.add(start);
        visited[start.row()][start.col()] = true;

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            for (int[] dir : DIRECTIONS) {
                int newRow = current.row() + dir[0];
                int newCol = current.col() + dir[1];
                Point neighbor = new Point(newRow, newCol);

                if (neighbor.equals(target)) {
                    return true;
                }

                if (isValidMove(grid, rows, cols, neighbor, visited)) {
                    visited[neighbor.row()][neighbor.col()] = true;
                    queue.add(neighbor);
                }
            }
        }

        return false;
    }

    private boolean isValidMove(char[][] grid, int rows, int cols, Point p, boolean[][] visited) {
        return p.row() >= 0 && p.row() < rows &&
               p.col() >= 0 && p.col() < cols &&
               grid[p.row()][p.col()] != OBSTACLE &&
               !visited[p.row()][p.col()];
    }

    private boolean isInvalid(char[][] grid, int rows, int cols, Point p) {
        return p.row() < 0 || p.row() >= rows || p.col() < 0 || p.col() >= cols || grid[p.row()][p.col()] == OBSTACLE;
    }
}

/**
