/**
 * Handles the pathfinding logic within the ice cave.
 */
class IceCaveSolver {
    private static final char WALKABLE_CHAR = '.';
    private static final int[] ROW_OFFSETS = {-1, 1, 0, 0};
    private static final int[] COL_OFFSETS = {0, 0, -1, 1};

    private final char[][] grid;
    private final int rows;
    private final int cols;

    public IceCaveSolver(char[][] grid) {
        this.grid = grid;
        this.rows = grid.length;
        this.cols = grid[0].length;
    }

    /**
     * Determines if there is a path from start to target using Breadth-First Search.
     * 
     * @param start  The starting point.
     * @param target The destination point.
     * @return true if a path exists, false otherwise.
     */
    public boolean canReachDestination(Point start, Point target) {
        if (isInvalid(start) || isInvalid(target)) {
            return false;
        }

        // If start or target is not a walkable path, return false immediately
        if (grid[start.row()][start.col()] != WALKABLE_CHAR || 
            grid[target.row()][target.col()] != WALKABLE_CHAR) {
            return false;
        }

        Queue<Point> queue = new LinkedList<>();
        boolean[][] visited = new boolean[rows][cols];

        queue.add(start);
        visited[start.row()][start.col()] = true;

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            if (current.equals(target)) {
                return true;
            }

            for (int i = 0; i < 4; i++) {
                int nextRow = current.row() + ROW_OFFSETS[i];
                int nextCol = current.col() + COL_OFFSETS[i];
                Point neighbor = new Point(nextRow, nextCol);

                if (isValidMove(neighbor, visited)) {
                    visited[neighbor.row()][neighbor.col()] = true;
                    queue.add(neighbor);
                }
            }
        }

        return false;
    }

    private boolean isValidMove(Point p, boolean[][] visited) {
        return !isInvalid(p) && 
               grid[p.row()][p.col()] == WALKABLE_CHAR && 
               !visited[p.row()][p.col()];
    }

    private boolean isInvalid(Point p) {
        return p.row() < 0 || p.row() >= rows || 
               p.col() < 0 || p.col() >= cols;
    }
}

