/**
 * IceCaveSolver solves the problem of determining if a path exists 
 * between two coordinates in a grid of walkable paths ('.') and walls ('X').
 */
public class IceCaveSolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            // Coordinates are provided as 1-indexed in the input
            int startR = reader.nextInt() - 1;
            int startC = reader.nextInt() - 1;
            int endR = reader.nextInt() - 1;
            int endC = reader.nextInt() - 1;

            Maze maze = new Maze(grid, rows, cols);
            Pathfinder pathfinder = new Pathfinder(maze);

            if (pathfinder.hasPath(startR, startC, endR, endC)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }

        } catch (Exception e) {
            // In a real production environment, use a logger
            System.err.println("Error processing input: " + e.getMessage());
        }
    }

    /**
     * Represents a coordinate point in the grid.
     */
    private static record Point(int r, int c) {}

    /**
     * Handles the grid data and boundary validation.
     */
    private static class Maze {
        private final char[][] grid;
        private final int rows;
        private final int cols;

        public Maze(char[][] grid, int rows, int cols) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
        }

        public boolean isWalkable(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] == '.';
        }

        public boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        public int getRows() { return rows; }
        public int getCols() { return cols; }

        public char getCell(int r, int c) {
            return grid[r][c];
        }
    }

    /**
     * Implements pathfinding logic.
     */
    private static class Pathfinder {
        private final Maze maze;
        private static final int[] DR = {-1, 1, 0, 0};
        private static final int[] DC = {0, 0, -1, 1};

        public Pathfinder(Maze maze) {
            this.maze = maze;
        }

        /**
         * Uses Breadth-First Search to find if a path exists.
         */
        public boolean hasPath(int startR, int startC, int endR, int endC) {
            // Basic validation
            if (!maze.isWithinBounds(startR, startC) || !maze.isWithinBounds(endR, endC)) {
                return false;
            }
            if (maze.getCell(startR, startC) == 'X' || maze.getCell(endR, endC) == 'X') {
                return false;
            }
            if (startR == endR && startC == endC) {
                return true;
            }

            Queue<Point> queue = new ArrayDeque<>();
            boolean[][] visited = new boolean[maze.getRows()][maze.getCols()];

            queue.add(new Point(startR, startC));
            visited[startR][startC] = true;

            while (!queue.isEmpty()) {
                Point current = queue.poll();

                for (int i = 0; i < 4; i++) {
                    int nextR = current.r() + DR[i];
                    int nextC = current.c() + DC[i];

                    if (nextR == endR && nextC == endC) {
                        return true;
                    }

                    if (maze.isWalkable(nextR, nextC) && !visited[nextR][nextC]) {
                        visited[nextR][nextC] = true;
                        queue.add(new Point(nextR, nextC));
                    }
                }
            }

            return false;
        }
    }

    /**
     * Efficient input reader for large datasets.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read line", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

