/**
 * Logic for solving the pathfinding problem.
 */
class IceCaveSolver {
    private static final int[][] DIRECTIONS = {
        {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    /**
     * Determines if there is a path from start to end using BFS.
     */
    public boolean canReachTarget(IceCave cave, Cell start, Cell end) {
        // If start or end is an obstacle, no path exists
        if (!cave.isTraversable(start.getRow(), start.getCol()) || 
            !cave.isTraversable(end.getRow(), end.getCol())) {
            return false;
        }

        Queue<Cell> queue = new LinkedList<>();
        boolean[][] visited = new boolean[cave.getRows()][cave.getCols()];

        queue.add(start);
        visited[start.getRow()][start.getCol()] = true;

        while (!queue.isEmpty()) {
            Cell current = queue.poll();

            if (current.equals(end)) {
                return true;
            }

            for (int[] dir : DIRECTIONS) {
                int newRow = current.getRow() + dir[0];
                int newCol = current.getCol() + dir[1];

                if (cave.isTraversable(newRow, newCol) && !visited[newRow][newCol]) {
                    visited[newRow][newCol] = true;
                    queue.add(new Cell(newRow, newCol));
                }
            }
        }

        return false;
    }
}

