import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Solution for the IceCave problem.
 * Determines if a path exists between two points in an ice grid based on specific movement rules.
 */
public class IceCave {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(new BufferedReader(new InputStreamReader(System.in)));
        PrintWriter out = new PrintWriter(System.out);

        try {
            IceCaveSolver solver = new IceCaveSolver(scanner);
            out.println(solver.solve() ? "YES" : "NO");
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.close();
        }
    }

    /**
     * Represents a coordinate in the 2D grid.
     */
    record Point(int row, int col) {}

    /**
     * Logic controller for the IceCave puzzle.
     */
    static class IceCaveSolver {
        private static final char EMPTY_CELL = '.';
        private static final char SPECIAL_CELL = 'X';

        private final int rowCount;
        private final int columnCount;
        private final char[][] grid;
        private final Point start;
        private final Point end;

        private final boolean[][] visited;
        private final int[] dRow = {-1, 0, 0, 1};
        private final int[] dCol = {0, -1, 1, 0};

        public IceCaveSolver(FastScanner scanner) {
            this.rowCount = scanner.nextInt();
            this.columnCount = scanner.nextInt();
            this.grid = new char[rowCount][];
            for (int i = 0; i < rowCount; i++) {
                this.grid[i] = scanner.next().toCharArray();
            }
            this.start = new Point(scanner.nextInt() - 1, scanner.nextInt() - 1);
            this.end = new Point(scanner.nextInt() - 1, scanner.nextInt() - 1);
            this.visited = new boolean[rowCount][columnCount];
        }

        public boolean solve() {
            // Case 1: Start and End are the same location
            if (start.equals(end)) {
                return canMoveFromSameLocation();
            }

            // Case 2: Pathfinding via DFS
            performDFS(start.row(), start.col());

            // If destination is not reachable, return false
            if (!visited[end.row()][end.col()]) {
                return false;
            }

            // If destination is a special 'X' cell, it is considered a success
            if (grid[end.row()][end.col()] == SPECIAL_CELL) {
                return true;
            }

            // If destination is a standard cell, we must be able to "pass through" it
            // (i.e., have at least two available directions to move)
            return canPassThroughEnd();
        }

        private boolean canMoveFromSameLocation() {
            for (int i = 0; i < 4; i++) {
                int nr = start.row() + dRow[i];
                int nc = start.col() + dCol[i];
                if (isWithinBounds(nr, nc) && grid[nr][nc] == EMPTY_CELL) {
                    return true;
                }
            }
            return false;
        }

        private void performDFS(int r, int c) {
            visited[r][c] = true;

            for (int i = 0; i < 4; i++) {
                int nr = r + dRow[i];
                int nc = c + dCol[i];

                if (isWithinBounds(nr, nc) && !visited[nr][nc]) {
                    // Can move if the cell is empty OR if it is the destination
                    if (grid[nr][nc] == EMPTY_CELL || (nr == end.row() && nc == end.col())) {
                        performDFS(nr, nc);
                    }
                }
            }
        }

        private boolean canPassThroughEnd() {
            int availableDirections = 0;
            for (int i = 0; i < 4; i++) {
                int nr = end.row() + dRow[i];
                int nc = end.col() + dCol[i];

                if (isWithinBounds(nr, nc)) {
                    // A direction is valid if it's an empty cell or the starting point
                    if (grid[nr][nc] == EMPTY_CELL || (nr == start.row() && nc == start.col())) {
                        availableDirections++;
                    }
                }
            }
            return availableDirections >= 2;
        }

        private boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < rowCount && c >= 0 && c < columnCount;
        }
    }

    /**
     * Utility class for fast input reading.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(BufferedReader reader) {
            this.reader = reader;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
