/**
 * A program to determine if a path exists between two points in a 2D grid maze.
 */
public class MazeSolver {

    private static final int[][] DIRECTIONS = {
        {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    private final int rows;
    private final int cols;
    private final boolean[][] grid;

    /**
     * Initializes the maze with dimensions and grid data.
     * 
     * @param rows Number of rows in the grid.
     * @param cols Number of columns in the grid.
     * @param gridData 2D boolean array where true represents a walkable path.
     */
    public MazeSolver(int rows, int cols, boolean[][] gridData) {
        this.rows = rows;
        this.cols = cols;
        this.grid = gridData;
    }

    /**
     * Performs a Depth First Search to find if a path exists from start to target.
     *
     * @param startRow Starting row index.
     * @param startCol Starting column index.
     * @param targetRow Target row index.
     * @param targetCol Target column index.
     * @return true if a path exists, false otherwise.
     */
    public boolean canFindPath(int startRow, int startCol, int targetRow, int targetCol) {
        // Basic validation
        if (!isWithinBounds(startRow, startCol) || !isWithinBounds(targetRow, targetCol)) {
            return false;
        }

        // If the start or end is a wall, no path can exist
        if (!grid[startRow][startCol] || !grid[targetRow][targetCol]) {
            return false;
        }

        return dfs(startRow, startCol, targetRow, targetCol);
    }

    private boolean dfs(int r, int c, int targetR, int targetC) {
        // Base case: reached the destination
        if (r == targetR && c == targetC) {
            return true;
        }

        // Mark current cell as visited by setting it to false (wall)
        grid[r][c] = false;

        for (int[] dir : DIRECTIONS) {
            int nextR = r + dir[0];
            int nextC = c + dir[1];

            if (isWithinBounds(nextR, nextC) && grid[nextR][nextC]) {
                if (dfs(nextR, nextC, targetR, targetC)) {
                    return true;
                }
            }
        }

        return false;
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        try {
            int n = reader.nextInt();
            int m = reader.nextInt();

            boolean[][] gridData = new boolean[n][m];
            for (int i = 0; i < n; i++) {
                String line = reader.next();
                for (int j = 0; j < m; j++) {
                    // '.' is a walkable path
                    gridData[i][j] = (line.charAt(j) == '.');
                }
            }

            // Input coordinates are 1-indexed in the original problem
            int r1 = reader.nextInt() - 1;
            int c1 = reader.nextInt() - 1;
            int r2 = reader.nextInt() - 1;
            int c2 = reader.nextInt() - 1;

            // Ensure starting point is treated as walkable (per original logic)
            if (r1 >= 0 && r1 < n && c1 >= 0 && c1 < m) {
                gridData[r1][c1] = true;
            }

            MazeSolver solver = new MazeSolver(n, m, gridData);
            boolean result = solver.canFindPath(r1, c1, r2, c2);

            System.out.println(result ? "YES" : "NO");

        } catch (IOException | RuntimeException e) {
            System.err.println("Error processing input: " + e.getMessage());
        }
    }

    /**
     * Utility class for fast I/O operations.
     */
    static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream s) {
            br = new BufferedReader(new InputStreamReader(s));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;

/**
 * Represents a point on a 2D grid.
 */
record Coordinate(int row, int col) {}

/**
 * Provides functionality to find paths on a grid containing obstacles.
 */
class GridPathfinder {
    private static final char OBSTACLE = 'X';
    private static final char PATH = '.';

    private final char[][] grid;
    private final int rows;
    private final int cols;

    public GridPathfinder(char[][] grid) {
        this.grid = grid;
        this.rows = grid.length;
        this.cols = grid[0].length;
    }

    /**
     * Determines if there is a path from the start coordinate to the target coordinate.
     * Uses Breadth-First Search (BFS) to find reachability.
     *
     * @param start  The starting coordinate.
     * @param target The destination coordinate.
     * @return true if a path exists, false otherwise.
     */
    public boolean isReachable(Coordinate start, Coordinate target) {
        if (isInvalid(start) || isInvalid(target)) {
            return false;
        }

        if (start.equals(target)) {
            return true;
        }

        // If start or target is an obstacle, no path is possible
        if (isObstacle(start) || isObstacle(target)) {
            return false;
        }

        Queue<Coordinate> queue = new ArrayDeque<>();
        boolean[][] visited = new boolean[rows][cols];

        queue.add(start);
        visited[start.row()][start.col()] = true;

        while (!queue.isEmpty()) {
            Coordinate current = queue.poll();

            if (current.equals(target)) {
                return true;
            }

            for (Coordinate neighbor : getNeighbors(current)) {
                if (!visited[neighbor.row()][neighbor.col()] && !isObstacle(neighbor)) {
                    visited[neighbor.row()][neighbor.col()] = true;
                    queue.add(neighbor);
                }
            }
        }

        return false;
    }

    private List<Coordinate> getNeighbors(Coordinate coord) {
        List<Coordinate> neighbors = new ArrayList<>();
        int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

        for (int[] dir : directions) {
            int newRow = coord.row() + dir[0];
            int newCol = coord.col() + dir[1];
            Coordinate neighbor = new Coordinate(newRow, newCol);

            if (isInBounds(neighbor)) {
                neighbors.add(neighbor);
            }
        }
        return neighbors;
    }

    private boolean isInBounds(Coordinate coord) {
        return coord.row() >= 0 && coord.row() < rows &&
               coord.col() >= 0 && coord.col() < cols;
    }

    private boolean isInvalid(Coordinate coord) {
        return !isInBounds(coord);
    }

    private boolean isObstacle(Coordinate coord) {
        return grid[coord.row()][coord.col()] == OBSTACLE;
    }
}

public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] board = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            board[i] = scanner.next().toCharArray();
        }

        // Input is 1-indexed in the original problem, converting to 0-indexed
        Coordinate start = new Coordinate(scanner.nextInt() - 1, scanner.nextInt() - 1);
        Coordinate target = new Coordinate(scanner.nextInt() - 1, scanner.nextInt() - 1);

        GridPathfinder pathfinder = new GridPathfinder(board);
        boolean possible = pathfinder.isReachable(start, target);

        System.out.println(possible ? "YES" : "NO");

        scanner.close();
    }
}

import java.util.*;
import java.io.*;

/**
 * A refactored solution to solve a grid-based pathfinding problem.
 * The logic determines if a destination cell is "reachable" and satisfies
 * specific adjacency conditions based on the grid layout.
 */
public class Main {

    public static void main(String[] args) {
        new GridSolver().run();
    }

    private static class GridSolver {
        private static final int[] ROW_DIRECTIONS = {0, 1, 0, -1};
        private static final int[] COL_DIRECTIONS = {1, 0, -1, 0};

        private FastReader reader;
        private PrintWriter writer;

        /**
         * Orchestrates the execution flow: reading input, solving, and writing output.
         */
        public void run() {
            reader = new FastReader(System.in);
            writer = new PrintWriter(System.out);

            try {
                solve();
            } catch (IOException e) {
                // In a production environment, use a professional logging framework.
                e.printStackTrace();
            } finally {
                writer.close();
            }
        }

        private void solve() throws IOException {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] grid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            // Adjusting 1-based input to 0-based indexing
            int startRow = reader.nextInt() - 1;
            int startCol = reader.nextInt() - 1;
            int endRow = reader.nextInt() - 1;
            int endCol = reader.nextInt() - 1;

            // Ensure the starting cell is treated as a traversable path
            grid[startRow][startCol] = '.';

            boolean[][] visited = new boolean[rows][cols];
            boolean isEndReachable = performBfs(grid, rows, cols, startRow, startCol, endRow, endCol, visited);

            int adjacentPathCount = countAdjacentPathCells(grid, rows, cols, endRow, endCol);

            boolean canSatisfyRules = determineResult(
                    startRow, startCol, endRow, endCol, 
                    isEndReachable, adjacentPathCount, 
                    grid[endRow][endCol] == 'X'
            );

            writer.println(canSatisfyRules ? "YES" : "NO");
        }

        /**
         * Performs a Breadth-First Search to determine if the endpoint is reachable.
         */
        private boolean performBfs(char[][] grid, int rows, int cols, 
                                   int startRow, int startCol, 
                                   int endRow, int endCol, 
                                   boolean[][] visited) {

            Queue<Point> queue = new ArrayDeque<>();
            queue.add(new Point(startRow, startCol));
            visited[startRow][startCol] = true;

            while (!queue.isEmpty()) {
                Point current = queue.poll();

                if (current.row == endRow && current.col == endCol) {
                    return true;
                }

                for (int i = 0; i < 4; i++) {
                    int nextRow = current.row + ROW_DIRECTIONS[i];
                    int nextCol = current.col + COL_DIRECTIONS[i];

                    if (isValidMove(grid, rows, cols, nextRow, nextCol, endRow, endCol, visited)) {
                        visited[nextRow][nextCol] = true;
                        queue.add(new Point(nextRow, nextCol));
                    }
                }
            }
            return false;
        }

        /**
         * Checks if a movement to the specified cell is valid according to BFS rules.
         */
        private boolean isValidMove(char[][] grid, int rows, int cols, 
                                    int r, int c, int targetR, int targetC, 
                                    boolean[][] visited) {
            if (r < 0 || r >= rows || c < 0 || c >= cols || visited[r][c]) {
                return false;
            }
            // The BFS can move into a '.' cell OR the specific target cell (even if it's an 'X')
            return grid[r][c] == '.' || (r == targetR && c == targetC);
        }

        /**
         * Counts how many cells adjacent to the target are path cells ('.').
         */
        private int countAdjacentPathCells(char[][] grid, int rows, int cols, int r, int c) {
            int count = 0;
            for (int i = 0; i < 4; i++) {
                int nr = r + ROW_DIRECTIONS[i];
                int nc = c + COL_DIRECTIONS[i];
                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == '.') {
                    count++;
                }
            }
            return count;
        }

        /**
         * Encapsulates the business logic determining the "YES/NO" outcome.
         */
        private boolean determineResult(int startR, int startC, int endR, int endC, 
                                        boolean isReachable, int adjacentPaths, 
                                        boolean isEndObstacle) {

            boolean isStartAtEnd = (startR == endR && startC == endC);

            if (isStartAtEnd) {
                // If starting and ending at the same spot, requires at least one adjacent path
                return adjacentPaths > 0;
            } else {
                // If different, must be reachable AND (be an obstacle OR have 2+ adjacent paths)
                return isReachable && (isEndObstacle || adjacentPaths >= 2);
            }
        }
    }

    /**
     * Represents a coordinate in the 2D grid.
     */
    private static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Point)) return false;
            Point point = (Point) o;
            return row == point.row && col == point.col;
        }

        @Override
        public int hashCode() {
            return Objects.hash(row, col);
        }
    }

    /**
     * Utility class for high-performance input reading.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

