/**
 * A refactored solution to maintain the count of adjacent '.' cell pairs
 * in a 1D array under point updates.
 */
public class Main {

    public static void main(String[] args) throws IOException {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        // Read initial configuration
        int numCells = reader.nextInt();
        int numQueries = reader.nextInt();

        if (numCells <= 0) {
            out.close();
            return;
        }

        char[] cells = reader.next().toCharArray();

        // The 'cnt' variable tracks the number of adjacent '.' pairs.
        // e.g., "..." has 2 pairs, ".#." has 0 pairs.
        int adjacentDotCount = 0;
        for (int i = 0; i < numCells - 1; i++) {
            if (cells[i] == '.' && cells[i + 1] == '.') {
                adjacentDotCount++;
            }
        }

        // Process queries
        for (int i = 0; i < numQueries; i++) {
            int index = reader.nextInt() - 1; // Convert to 0-indexed
            char newType = reader.next().charAt(0);
            char oldType = cells[index];

            // Only update if the cell type actually changes
            if (oldType != newType) {
                if (oldType == '.') {
                    // Transitioning from '.' to something else: 
                    // check if we are breaking any existing dot-dot pairs.
                    if (index > 0 && cells[index - 1] == '.') {
                        adjacentDotCount--;
                    }
                    if (index < numCells - 1 && cells[index + 1] == '.') {
                        adjacentDotCount--;
                    }
                } else if (newType == '.') {
                    // Transitioning from something else to '.':
                    // check if we are creating new dot-dot pairs.
                    if (index > 0 && cells[index - 1] == '.') {
                        adjacentDotCount++;
                    }
                    if (index < numCells - 1 && cells[index + 1] == '.') {
                        adjacentDotCount++;
                    }
                }
                cells[index] = newType;
            }

            out.println(adjacentDotCount);
        }

        out.flush();
        out.close();
    }

    /**
     * Fast I/O utility class for efficient reading.
     */
    static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

