/**
 * A program that tracks the number of adjacent empty cells ('.') 
 * in a sequence as cells are toggled between empty and occupied states.
 */
public class Solution {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            // Read initial dimensions and configuration
            int gridLength = reader.nextInt();
            int queryCount = reader.nextInt();
            String initialConfig = reader.next();

            if (initialConfig == null) {
                return;
            }

            CellConfiguration config = new CellConfiguration(initialConfig);

            // Process queries
            for (int i = 0; i < queryCount; i++) {
                int targetIndex = reader.nextInt() - 1; // Convert 1-based input to 0-based index
                String newCharStr = reader.next();
                char newChar = newCharStr.charAt(0);

                config.update(targetIndex, newChar);
                writer.println(config.getEmptyPairCount());
            }
        } catch (Exception e) {
            // In a production environment, use a logger. 
            // For algorithmic purposes, we allow exceptions to propagate or handle gracefully.
        } finally {
            writer.close();
        }
    }

    /**
     * Manages the state of the cells and tracks the count of adjacent empty ('.') pairs.
     */
    static class CellConfiguration {
        private final boolean[] isOccupied;
        private final int length;
        private int emptyPairCount;

        /**
         * Initializes the configuration and calculates the initial pair count.
         * @param initialConfig The starting string of characters.
         */
        public CellConfiguration(String initialConfig) {
            this.length = initialConfig.length();
            this.isOccupied = new boolean[length];
            this.emptyPairCount = 0;

            for (int i = 0; i < length; i++) {
                isOccupied[i] = (initialConfig.charAt(i) != '.');
            }

            // Initial calculation of adjacent empty pairs ('.', '.')
            for (int i = 0; i < length - 1; i++) {
                if (!isOccupied[i] && !isOccupied[i + 1]) {
                    emptyPairCount++;
                }
            }
        }

        /**
         * Updates the character at the specified index and updates the pair count.
         * @param index The 0-based index to update.
         * @param newChar The new character to place at the index.
         */
        public void update(int index, char newChar) {
            if (index < 0 || index >= length) {
                return;
            }

            boolean shouldBeOccupied = (newChar != '.');

            // Only update if the state is actually changing
            if (isOccupied[index] != shouldBeOccupied) {
                // 1. Remove the contribution of the current state of this index to its neighbors
                emptyPairCount -= countPairsAt(index);

                // 2. Apply the state change
                isOccupied[index] = shouldBeOccupied;

                // 3. Add the contribution of the new state to its neighbors
                emptyPairCount += countPairsAt(index);
            }
        }

        /**
         * Helper method to count how many adjacent '.' pairs the given index participates in.
         * @param i The index to check.
         * @return The number of adjacent empty pairs (0, 1, or 2).
         */
        private int countPairsAt(int i) {
            int pairs = 0;

            // Check the pair consisting of (i-1, i)
            if (i > 0 && !isOccupied[i - 1] && !isOccupied[i]) {
                pairs++;
            }

            // Check the pair consisting of (i, i+1)
            if (i < length - 1 && !isOccupied[i] && !isOccupied[i + 1]) {
                pairs++;
            }

            return pairs;
        }

        public int getEmptyPairCount() {
            return emptyPairCount;
        }
    }

    /**
     * High-performance reader for processing large input streams.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

