/**
 * Manages a character array and tracks the number of adjacent '.' pairs.
 */
class DotPairTracker {
    private final char[] characters;
    private final int length;
    private int dotPairCount;

    public DotPairTracker(String initialString) {
        this.characters = initialString.toCharArray();
        this.length = characters.length;
        this.dotPairCount = calculateInitialDotPairs();
    }

    private int calculateInitialDotPairs() {
        int count = 0;
        for (int i = 0; i < length - 1; i++) {
            if (isDot(i) && isDot(i + 1)) {
                count++;
            }
        }
        return count;
    }

    /**
     * Updates the character at a specific position and adjusts the dot pair count.
     * 
     * @param index The 0-based index to update.
     * @param newChar The new character to place at the index.
     */
    public void update(int index, char newChar) {
        if (index < 0 || index >= length || characters[index] == newChar) {
            return;
        }

        // Remove the contribution of the current character and its neighbors
        updateCountDelta(index, -1);

        // Apply the change
        characters[index] = newChar;

        // Add the contribution of the new character and its neighbors
        updateCountDelta(index, 1);
    }

    /**
     * Adjusts the dotPairCount based on whether the character at index and its neighbors 
     * form new or broken '.' pairs.
     */
    private void updateCountDelta(int index, int delta) {
        // Check the pair with the left neighbor
        if (index > 0 && isDot(index - 1) && isDot(index)) {
            dotPairCount += delta;
        }
        // Check the pair with the right neighbor
        if (index < length - 1 && isDot(index) && isDot(index + 1)) {
            dotPairCount += delta;
        }
    }

    private boolean isDot(int index) {
        return characters[index] == '.';
    }

    public int getDotPairCount() {
        return dotPairCount;
    }
}

