            // Input provides 1-based index, convert to 0-based
            int pos = sc.nextInt() - 1;
            char newChar = sc.next().charAt(0);

            tracker.update(pos, newChar);
            out.println(tracker.getDotPairCount());
        }

        out.flush();
        out.close();
    }
}

