/**
 * Contains the core logic for solving the dot-pair counting problem.
 */
class DotPairSolver {

    /**
     * Processes a single test case.
     * 
     * @param reader The fast input reader.
     * @param writer The print writer for output.
     */
    public void solve(FastReader reader, PrintWriter writer) {
        int length = reader.nextInt();
        int queryCount = reader.nextInt();
        char[] sequence = reader.next().toCharArray();

        int dotPairCount = calculateInitialDotPairs(sequence);

        for (int i = 0; i < queryCount; i++) {
            int index = reader.nextInt() - 1; // Convert 1-based index to 0-based
            char newChar = reader.next().charAt(0);
            char oldChar = sequence[index];

            // Only update if the character actually changes
            if (oldChar != newChar) {
                dotPairCount = updateDotPairs(sequence, index, oldChar, newChar, dotPairCount);
                sequence[index] = newChar;
            }

            writer.println(dotPairCount);
        }
    }

    private int calculateInitialDotPairs(char[] sequence) {
        int count = 0;
        for (int i = 0; i < sequence.length - 1; i++) {
            if (sequence[i] == '.' && sequence[i + 1] == '.') {
                count++;
            }
        }
        return count;
    }

    /**
     * Updates the dot pair count based on a character change at a specific index.
     */
    private int updateDotPairs(char[] sequence, int index, char oldChar, char newChar, int currentCount) {
        int neighborsWithDots = 0;
        int len = sequence.length;

        // Check left neighbor
        if (index > 0 && sequence[index - 1] == '.') {
            neighborsWithDots++;
        }
        // Check right neighbor
        if (index < len - 1 && sequence[index + 1] == '.') {
            neighborsWithDots++;
        }

        if (newChar == '.') {
            // Changing something to a dot increases pairs by the number of adjacent dots
            return currentCount + neighborsWithDots;
        } else {
            // Changing a dot to something else decreases pairs by the number of adjacent dots
            // Note: This logic applies if the oldChar was a dot. 
            // If oldChar wasn't a dot, the count shouldn't change.
            if (oldChar == '.') {
                return currentCount - neighborsWithDots;
            }
        }
        return currentCount;
    }
}

