/**
 * A program that manages a sequence of characters and tracks the number of 
 * adjacent pairs of '.' characters using a Segment Tree.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            // Read n (size of sequence) and m (number of queries)
            int n = reader.nextInt();
            int m = reader.nextInt();

            // Read the initial sequence
            String initialSequence = reader.next();
            boolean[] isDotArray = new boolean[n];
            for (int i = 0; i < n; i++) {
                isDotArray[i] = (initialSequence.charAt(i) == '.');
            }

            // Initialize the Segment Tree with the starting state
            SegmentTree segmentTree = new SegmentTree(isDotArray);

            // Process queries
            for (int i = 0; i < m; i++) {
                int position = reader.nextInt() - 1; // Convert 1-based index to 0-based
                char newChar = reader.next().charAt(0);
                boolean newIsDot = (newChar == '.');

                // Only perform an update if the state of the character actually changes
                if (newIsDot != isDotArray[position]) {
                    isDotArray[position] = newIsDot;
                    segmentTree.update(position, newIsDot);
                }

                // Output the current count of adjacent dot pairs
                writer.println(segmentTree.getTotalAdjacentDots());
            }
        } catch (IOException | NoSuchElementException e) {
            // In a production environment, consider more robust error handling
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Represents a single node in the Segment Tree.
     * Stores the count of adjacent dots within its range and the boundary states.
     */
    static class Node {
        final int adjacentDotCount;
        final boolean leftIsDot;
        final boolean rightIsDot;

        Node(int adjacentDotCount, boolean leftIsDot, boolean rightIsDot) {
            this.adjacentDotCount = adjacentDotCount;
            this.leftIsDot = leftIsDot;
            this.rightIsDot = rightIsDot;
        }
    }

    /**
     * A Segment Tree implementation to efficiently update characters and 
     * query the number of adjacent pairs of dots.
     */
    static class SegmentTree {
        private final int n;
        private final Node[] tree;
        private final boolean[] initialStates;

        public SegmentTree(boolean[] states) {
            this.n = states.length;
            this.initialStates = states.clone();
            this.tree = new Node[4 * n];
            build(1, 0, n - 1);
        }

        /**
         * Recursively builds the Segment Tree.
         */
        private void build(int nodeIndex, int start, int end) {
            if (start == end) {
                tree[nodeIndex] = createLeafNode(initialStates[start]);
                return;
            }

            int mid = (start + end) / 2;
            int leftChild = 2 * nodeIndex;
            int rightChild = 2 * nodeIndex + 1;

            build(leftChild, start, mid);
            build(rightChild, mid + 1, end);
            tree[nodeIndex] = merge(tree[leftChild], tree[rightChild]);
        }

        /**
         * Updates the state of a specific index in the tree.
         */
        public void update(int targetIdx, boolean isDot) {
            updateRecursive(1, 0, n - 1, targetIdx, isDot);
        }

        private void updateRecursive(int nodeIndex, int start, int end, int targetIdx, boolean isDot) {
            if (start == end) {
                tree[nodeIndex] = createLeafNode(isDot);
                return;
            }

            int mid = (start + end) / 2;
            int leftChild = 2 * nodeIndex;
            int rightChild = 2 * nodeIndex + 1;

            if (targetIdx <= mid) {
                updateRecursive(leftChild, start, mid, targetIdx, isDot);
            } else {
                updateRecursive(rightChild, mid + 1, end, targetIdx, isDot);
            }
            tree[nodeIndex] = merge(tree[leftChild], tree[rightChild]);
        }

        /**
         * Merges two nodes into a parent node.
         * The count of adjacent dots is the sum of both children plus 1 
         * if the boundary between them forms a new dot-dot pair.
         */
        private Node merge(Node left, Node right) {
            int count = left.adjacentDotCount + right.adjacentDotCount;
            if (left.rightIsDot && right.leftIsDot) {
                count++;
            }
            return new Node(count, left.leftIsDot, right.rightIsDot);
        }

        private Node createLeafNode(boolean isDot) {
            return new Node(0, isDot, isDot);
        }

        public int getTotalAdjacentDots() {
            return tree[1].adjacentDotCount;
        }
    }

    /**
     * Fast I/O utility for reading input streams.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to manage contiguous segments of '.' characters and maintain 
 * a running sum of (segment_length - 1) for all segments.
 */
public class DotSegmentManager {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int n = reader.nextInt();
            int m = reader.nextInt();
            char[] initialState = reader.next().toCharArray();

            SegmentManager manager = new SegmentManager();
            manager.initialize(initialState);

            for (int i = 0; i < m; i++) {
                int pos = reader.nextInt() - 1; // Convert to 0-indexed
                char type = reader.next().charAt(0);

                if (type == '.') {
                    manager.addDot(pos);
                } else {
                    manager.removeDot(pos);
                }
                writer.println(manager.getAnswer());
            }
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Represents a contiguous range [l, r] of dots.
     */
    private static class Segment implements Comparable<Segment> {
        final int l, r;

        Segment(int l, int r) {
            this.l = l;
            this.r = r;
        }

        public int getWeight() {
            return r - l;
        }

        @Override
        public int compareTo(Segment other) {
            return Integer.compare(this.l, other.l);
        }
    }

    /**
     * Handles the logic of adding/removing dots and updating segment ranges.
     */
    private static class SegmentManager {
        private final TreeSet<Segment> segments = new TreeSet<>();
        private long currentAnswer = 0;

        public void initialize(char[] str) {
            int n = str.length;
            for (int i = 0; i < n; ) {
                if (str[i] == '.') {
                    int start = i;
                    while (i < n && str[i] == '.') {
                        i++;
                    }
                    int end = i - 1;
                    segments.add(new Segment(start, end));
                    currentAnswer += (end - start);
                } else {
                    i++;
                }
            }
        }

        public void addDot(int at) {
            // Find adjacent segments to merge
            Segment floor = segments.floor(new Segment(at, at));
            Segment ceil = segments.ceiling(new Segment(at, at));

            int newL = at;
            int newR = at;

            // Check if the dot bridges or extends a segment to the left
            if (floor != null && floor.r == at - 1) {
                newL = floor.l;
                currentAnswer -= floor.getWeight();
                segments.remove(floor);
            }

            // Check if the dot bridges or extends a segment to the right
            // We re-fetch ceiling because floor might have been part of a larger structure 
            // (though not possible with non-overlapping segments, it's safer)
            ceil = segments.ceiling(new Segment(at, at));
            if (ceil != null && ceil.l == at + 1) {
                newR = ceil.r;
                currentAnswer -= ceil.getWeight();
                segments.remove(ceil);
            }

            segments.add(new Segment(newL, newR));
            currentAnswer += (newR - newL);
        }

        public void removeDot(int at) {
            // Find the segment that contains the index 'at'
            Segment floor = segments.floor(new Segment(at, at));
            if (floor != null && floor.l <= at && floor.r >= at) {
                segments.remove(floor);
                currentAnswer -= floor.getWeight();

                // Split the segment into two parts: [l, at-1] and [at+1, r]
                if (floor.l < at) {
                    segments.add(new Segment(floor.l, at - 1));
                    currentAnswer += (at - 1 - floor.l);
                }
                if (floor.r > at) {
                    segments.add(new Segment(at + 1, floor.r));
                    currentAnswer += (floor.r - (at + 1));
                }
            }
        }

        public long getAnswer() {
            return currentAnswer;
        }
    }

    /**
     * Utility class for fast I/O operations.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

