/**
 * Solution to count and update adjacent pairs of '.' characters in a string.
 * Time Complexity: O(N + M) where N is the string length and M is the number of queries.
 * Space Complexity: O(N) to store the character array.
 */
public class Solution {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            new Solution().solve(reader, out);
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            out.close();
        }
    }

    /**
     * Reads input and processes the queries.
     * 
     * @param reader Fast I/O reader
     * @param out    Fast I/O writer
     * @throws IOException if an I/O error occurs
     */
    public void solve(FastReader reader, PrintWriter out) throws IOException {
        int n = reader.nextInt();
        int m = reader.nextInt();

        String initialString = reader.next();
        if (initialString == null) return;

        char[] arr = initialString.toCharArray();

        // Initial calculation of adjacent dot pairs
        int dotPairsCount = 0;
        for (int i = 0; i < n - 1; i++) {
            if (arr[i] == '.' && arr[i + 1] == '.') {
                dotPairsCount++;
            }
        }

        // Process M queries
        for (int i = 0; i < m; i++) {
            int pos = reader.nextInt() - 1; // Convert 1-based to 0-based index
            String nextCharStr = reader.next();
            if (nextCharStr == null) break;
            char newChar = nextCharStr.charAt(0);

            // Only process if the character actually changes
            if (arr[pos] != newChar) {
                // 1. Remove the contribution of existing dot pairs involving this position
                if (pos > 0 && arr[pos - 1] == '.' && arr[pos] == '.') {
                    dotPairsCount--;
                }
                if (pos < n - 1 && arr[pos] == '.' && arr[pos + 1] == '.') {
                    dotPairsCount--;
                }

                // 2. Update the character
                arr[pos] = newChar;

                // 3. Add the contribution of new dot pairs involving this position
                if (pos > 0 && arr[pos - 1] == '.' && arr[pos] == '.') {
                    dotPairsCount++;
                }
                if (pos < n - 1 && arr[pos] == '.' && arr[pos + 1] == '.') {
                    dotPairsCount++;
                }

                // Per original logic: output the count only if the character changed
                out.println(dotPairsCount);
            }
        }
    }

