/**
 * Refactored version of the TaskC solver.
 * The objective is to maintain the value (count - blocks), where:
 * - count is the number of '.' characters.
 * - blocks is the number of contiguous segments of '.' characters.
 * 
 * Mathematical Observation:
 * (count - blocks) is equivalent to the number of adjacent pairs of '.' characters.
 * Example: "..." -> count=3, blocks=1, ans=2. Pairs: (0,1), (1,2) -> 2.
 * Example: ". . ." -> count=2, blocks=2, ans=0. Pairs: none -> 0.
 */
public class Main {

    public static void main(String[] args) {
        try (FastReader in = new FastReader(System.in);
             FastWriter out = new FastWriter(System.out)) {

            int n = in.nextInt();
            int m = in.nextInt();
            String sStr = in.readLine();

            if (sStr == null) return;

            char[] s = sStr.toCharArray();
            TaskSolver solver = new TaskSolver(n, s);

            for (int i = 0; i < m; i++) {
                int index = in.nextInt() - 1; // Convert 1-based to 0-based
                char newChar = in.nextChar();
                solver.update(index, newChar);
                out.print(solver.getAns());
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /**
     * Encapsulates the logic for solving the task and maintaining the state.
     */
    static class TaskSolver {
        private final int n;
        private final char[] s;
        private int adjDots;

        public TaskSolver(int n, char[] s) {
            this.n = n;
            this.s = s;
            this.adjDots = calculateInitialAdjDots();
        }

        private int calculateInitialAdjDots() {
            int count = 0;
            for (int i = 0; i < n - 1; i++) {
                if (s[i] == '.' && s[i + 1] == '.') {
                    count++;
                }
            }
            return count;
        }

        /**
         * Updates the character at the given index and adjusts the adjDots count.
         * Time Complexity: O(1)
         */
        public void update(int i, char newChar) {
            if (i < 0 || i >= n || s[i] == newChar) {
                return;
            }

            // Remove old contribution of s[i] to adjacent dot pairs
            if (s[i] == '.') {
                if (i > 0 && s[i - 1] == '.') {
                    adjDots--;
                }
                if (i < n - 1 && s[i + 1] == '.') {
                    adjDots--;
                }
            }

            // Update the character
            s[i] = newChar;

            // Add new contribution of s[i] to adjacent dot pairs
            if (s[i] == '.') {
                if (i > 0 && s[i - 1] == '.') {
                    adjDots++;
                }
                if (i < n - 1 && s[i + 1] == '.') {
                    adjDots++;
                }
            }
        }

        public int getAns() {
            return adjDots;
        }
    }

    /**
     * Fast I/O reader class.
     */
    static class FastReader implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public char nextChar() {
            return next().charAt(0);
        }

        /**
         * Reads a full line, skipping empty lines to handle the newline 
         * character left by nextInt().
         */
        public String readLine() throws IOException {
            String line = reader.readLine();
            while (line != null && line.trim().isEmpty()) {
                line = reader.readLine();
            }
            return line;
