/**
 * A program to track the number of adjacent '.' character pairs in a string
 * subject to character replacement operations.
 */
public class Replacement {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            // Read initial configuration
            String nInput = reader.next();
            String mInput = reader.next();
            if (nInput == null || mInput == null) return;

            int sequenceLength = Integer.parseInt(nInput);
            int operationCount = Integer.parseInt(mInput);

            String initialSequence = reader.next();
            if (initialSequence == null) return;

            // Initialize the tracker with the starting string
            DotPairTracker tracker = new DotPairTracker(initialSequence);

            // Process each replacement operation
            for (int i = 0; i < operationCount; i++) {
                int index = reader.nextInt() - 1; // Convert 1-based input to 0-based index
                char newChar = reader.next().charAt(0);

                tracker.update(index, newChar);
                out.println(tracker.getDotPairCount());
            }
        } catch (Exception e) {
