        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Manages a character sequence and tracks the number of consecutive '.' pairs.
     */
    static class DotPairTracker {
        private final char[] sequence;
        private int dotPairCount;

        public DotPairTracker(String initialSequence) {
            this.sequence = initialSequence.toCharArray();
            this.dotPairCount = calculateInitialDotPairs();
        }

        /**
         * Updates the character at the specified index and adjusts the pair count.
         * 
         * @param index   The index to update.
         * @param newChar The character to place at the index.
         */
        public void update(int index, char newChar) {
            if (index < 0 || index >= sequence.length || sequence[index] == newChar) {
                return;
            }

            // Subtract the contribution of the current character to the dot pair count
            dotPairCount -= countPairsInvolvingIndex(index);

            // Apply the update
            sequence[index] = newChar;

            // Add the contribution of the new character to the dot pair count
            dotPairCount += countPairsInvolvingIndex(index);
        }

        public int getDotPairCount() {
            return dotPairCount;
        }

        /**
         * Calculates how many pairs of adjacent '.' characters include the given index.
         */
        private int countPairsInvolvingIndex(int index) {
            int pairs = 0;
            // Check if pair exists with the left neighbor
            if (index > 0 && sequence[index] == '.' && sequence[index - 1] == '.') {
                pairs++;
            }
            // Check if pair exists with the right neighbor
            if (index < sequence.length - 1 && sequence[index] == '.' && sequence[index + 1] == '.') {
                pairs++;
            }
            return pairs;
        }

        private int calculateInitialDotPairs() {
            int count = 0;
            for (int i = 0; i < sequence.length - 1; i++) {
                if (sequence[i] == '.' && sequence[i + 1] == '.') {
                    count++;
                }
            }
            return count;
        }
    }

