    /**
     * Manages the state of the character array and tracks the count
     * of adjacent dot ('.') pairs.
     */
    static class DotPairTracker {
        private final char[] grid;
        private final int size;
        private int adjacentDotPairs;

        public DotPairTracker(String initialContent) {
            this.grid = initialContent.toCharArray();
            this.size = grid.length;
            this.adjacentDotPairs = calculateInitialPairs();
        }

        private int calculateInitialPairs() {
            int count = 0;
            for (int i = 0; i < size - 1; i++) {
                if (grid[i] == '.' && grid[i + 1] == '.') {
                    count++;
                }
            }
            return count;
        }

        /**
         * Updates the character at the specified index and updates the pair count.
         * 
         * @param index The 0-based index to update.
         * @param newChar The new character to place at the index.
         */
        public void update(int index, char newChar) {
            if (index < 0 || index >= size || grid[index] == newChar) {
                return;
            }

            if (newChar == '.') {
                handleDotPlacement(index);
            } else {
                handleDotRemoval(index);
            }

            grid[index] = newChar;
        }

        private void handleDotPlacement(int index) {
            // If we place a dot, check if it creates new pairs with neighbors
            if (index > 0 && grid[index - 1] == '.') {
                adjacentDotPairs++;
            }
            if (index < size - 1 && grid[index + 1] == '.') {
                adjacentDotPairs++;
            }
        }

        private void handleDotRemoval(int index) {
            // If we remove a dot, check if it breaks existing pairs
            if (index > 0 && grid[index - 1] == '.') {
                adjacentDotPairs--;
            }
            if (index < size - 1 && grid[index + 1] == '.') {
                adjacentDotPairs--;
            }
        }

        public int getAdjacentDotPairs() {
            return adjacentDotPairs;
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(java.io.InputStream inputStream) {
            this.reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
