import java.io.*;
import java.util.*;

/**
 * A refactored solution to manage segments of consecutive '.' characters.
 * The program tracks the sum of (length - 1) for all continuous segments of dots.
 */
public class Main {

    public static void main(String[] args) {
        FastReader in = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        TaskSolver solver = new TaskSolver(in, out);
        solver.solve();

        out.close();
    }

    /**
     * Represents an immutable continuous segment of characters.
     */
    static final class Segment implements Comparable<Segment> {
        final int start;
        final int end;

        Segment(int start, int end) {
            this.start = start;
            this.end = end;
        }

        @Override
        public int compareTo(Segment other) {
            if (this.start != other.start) {
                return Integer.compare(this.start, other.start);
            }
            return Integer.compare(this.end, other.end);
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Segment)) return false;
            Segment segment = (Segment) o;
            return start == segment.start && end == segment.end;
        }

        @Override
        public int hashCode() {
            return Objects.hash(start, end);
        }
    }

    /**
     * Manages the set of dot-segments and tracks the sum of (length - 1).
     */
    static final class SegmentTracker {
        private final TreeSet<Segment> segments = new TreeSet<>();
        private long sumLenMinusOne = 0;

        /**
         * Adds a new segment and updates the running sum.
         */
        public void add(int start, int end) {
            if (start > end) return;
            segments.add(new Segment(start, end));
            sumLenMinusOne += (end - start);
        }

        /**
         * Removes a segment and updates the running sum.
         */
        public void remove(Segment seg) {
            if (seg == null) return;
            if (segments.remove(seg)) {
                sumLenMinusOne -= (seg.end - seg.start);
            }
        }

        /**
         * Finds the segment that contains the specified index.
         */
        public Segment findContaining(int index) {
            // Find the segment with the largest start <= index
            Segment floor = segments.floor(new Segment(index, index));
            if (floor != null && floor.end >= index) {
                return floor;
            }
            return null;
        }

        public long getSum() {
            return sumLenMinusOne;
        }
    }

    /**
     * Encapsulates the logic for solving the segment management problem.
     */
    static final class TaskSolver {
        private final FastReader in;
        private final PrintWriter out;

        TaskSolver(FastReader in, PrintWriter out) {
            this.in = in;
            this.out = out;
        }

        public void solve() {
            int n = in.nextInt();
            int m = in.nextInt();
            char[] s = in.next().toCharArray();

            SegmentTracker tracker = new SegmentTracker();
            initializeSegments(s, n, tracker);

            for (int i = 0; i < m; i++) {
                int x = in.nextInt() - 1; // 0-indexed
                char newChar = in.next().charAt(0);

                processUpdate(s, n, x, newChar, tracker);
                out.println(tracker.getSum());
            }
        }

        private void initializeSegments(char[] s, int n, SegmentTracker tracker) {
            int i = 0;
            while (i < n) {
                if (s[i] == '.') {
                    int start = i;
                    while (i < n && s[i] == '.') {
                        i++;
                    }
                    tracker.add(start, i - 1);
                } else {
                    i++;
                }
            }
        }

        private void processUpdate(char[] s, int n, int x, char newChar, SegmentTracker tracker) {
            if (s[x] == newChar) return;

            if (s[x] == '.') {
                // Transition: '.' -> Other (Splitting a segment)
                Segment seg = tracker.findContaining(x);
                // seg is guaranteed not to be null because s[x] == '.'
                tracker.remove(seg);
                if (seg.start < x) {
                    tracker.add(seg.start, x - 1);
                }
                if (seg.end > x) {
                    tracker.add(x + 1, seg.end);
                }
            } else if (newChar == '.') {
                // Transition: Other -> '.' (Merging adjacent segments)
                Segment left = (x > 0 && s[x - 1] == '.') ? tracker.findContaining(x - 1) : null;
                Segment right = (x < n - 1 && s[x + 1] == '.') ? tracker.findContaining(x + 1) : null;

                if (left != null && right != null) {
                    int newStart = left.start;
                    int newEnd = right.end;
                    tracker.remove(left);
                    tracker.remove(right);
                    tracker.add(newStart, newEnd);
                } else if (left != null) {
                    int newStart = left.start;
                    int newEnd = x;
                    tracker.remove(left);
                    tracker.add(newStart, newEnd);
                } else if (right != null) {
                    int newStart = x;
                    int newEnd = right.end;
                    tracker.remove(right);
                    tracker.add(newStart, newEnd);
                } else {
                    tracker.add(x, x);
                }
            }
            // If transition is Other -> Other, dot segments are unaffected.

            s[x] = newChar;
        }
    }

    /**
     * Utility class for fast input parsing.
     */
    static final class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

