/**
 * A program that tracks the number of consecutive dot pairs in a grid
 * as characters are updated.
 */
public class ConsecutiveDotTracker {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int gridSize = reader.nextInt();
            int queryCount = reader.nextInt();
            char[] initialGrid = reader.next().toCharArray();

            ConsecutiveDotScoreManager manager = new ConsecutiveDotScoreManager(initialGrid);

            for (int q = 0; q < queryCount; q++) {
                int index = reader.nextInt() - 1; // Convert to 0-based index
                char newChar = reader.next().charAt(0);

                manager.update(index, newChar);
                writer.println(manager.getScore());
            }
        } catch (Exception e) {
            // In a production environment, use a proper logger
            e.printStackTrace();
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Manages the grid state and calculates the score.
     * The score is defined as the sum of (length - 1) for every contiguous block of dots.
     * This is mathematically equivalent to the count of adjacent pairs of dots.
     */
    static class ConsecutiveDotScoreManager {
        private final char[] grid;
        private int currentScore;

        public ConsecutiveDotScoreManager(char[] initialGrid) {
            this.grid = initialGrid;
            this.currentScore = calculateInitialScore();
        }

        private int calculateInitialScore() {
            int score = 0;
            for (int i = 0; i < grid.length - 1; i++) {
                if (isDotPair(i, i + 1)) {
                    score++;
                }
            }
            return score;
        }

        /**
         * Updates the character at the given index and adjusts the score incrementally.
         * Complexity: O(1)
         */
        public void update(int index, char newChar) {
            if (index < 0 || index >= grid.length || grid[index] == newChar) {
                return;
            }

            // 1. Remove the contribution of the current index to the score
            if (isDotPair(index - 1, index)) {
                currentScore--;
            }
            if (isDotPair(index, index + 1)) {
                currentScore--;
            }

            // 2. Apply the change
            grid[index] = newChar;

            // 3. Add the new contribution to the score
            if (isDotPair(index - 1, index)) {
                currentScore++;
            }
            if (isDotPair(index, index + 1)) {
                currentScore++;
            }
        }

        public int getScore() {
            return currentScore;
        }

        private boolean isDotPair(int i, int j) {
            if (i < 0 || j >= grid.length) {
                return false;
            }
            return grid[i] == '.' && grid[j] == '.';
        }
    }

    /**
     * Efficient utility class for reading input.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }
    }
}

