/**
 * This program manages a grid of cells and tracks the number of adjacent 
 * pairs of empty cells ('.'). It supports updating individual cells 
 * and querying the current count of adjacent empty pairs.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int gridSize = reader.nextInt();
            int queryCount = reader.nextInt();
            String initialLayout = reader.next();

            CellGrid grid = new CellGrid(initialLayout);

            for (int i = 0; i < queryCount; i++) {
                int targetIndex = reader.nextInt() - 1; // Convert 1-based to 0-based
                char newChar = reader.next().charAt(0);

                grid.updateCell(targetIndex, newChar);
                writer.println(grid.getAdjacentDotCount());
            }
        } catch (Exception e) {
            // In a production environment, use a proper logging framework
            System.err.println("An error occurred during execution: " + e.getMessage());
        } finally {
            writer.close();
        }
    }

    /**
     * Manages the state of the grid and calculates the count of adjacent '.' cells.
     */
    static class CellGrid {
        private final char[] cells;
        private final int size;
        private int adjacentDotCount;

        public CellGrid(String initialLayout) {
            this.cells = initialLayout.toCharArray();
            this.size = cells.length;
            this.adjacentDotCount = calculateInitialAdjacentDots();
        }

        /**
         * Calculates the initial number of adjacent '.' pairs in O(N).
         */
        private int calculateInitialAdjacentDots() {
            int count = 0;
            for (int i = 0; i < size - 1; i++) {
                if (cells[i] == '.' && cells[i + 1] == '.') {
                    count++;
                }
            }
            return count;
        }

        /**
         * Updates a cell at the given index and updates the adjacent dot count.
         * Time Complexity: O(1)
         * 
         * @param index The index of the cell to update.
         * @param newChar The new character to place in the cell.
         */
        public void updateCell(int index, char newChar) {
            if (index < 0 || index >= size) {
                return;
            }

            // 1. Remove the contribution of the current cell and its neighbors
            // if the current cell is a dot.
            if (cells[index] == '.') {
                subtractNeighborContribution(index);
            }

            // 2. Apply the change
            cells[index] = newChar;

            // 3. Add the contribution of the new cell and its neighbors
            // if the new character is a dot.
            if (cells[index] == '.') {
                addNeighborContribution(index);
            }
        }

        private void subtractNeighborContribution(int index) {
            // Check pair with left neighbor
            if (index > 0 && cells[index - 1] == '.') {
                adjacentDotCount--;
            }
            // Check pair with right neighbor
            if (index < size - 1 && cells[index + 1] == '.') {
                adjacentDotCount--;
            }
        }

        private void addNeighborContribution(int index) {
            // Check pair with left neighbor
            if (index > 0 && cells[index - 1] == '.') {
                adjacentDotCount++;
            }
            // Check pair with right neighbor
            if (index < size - 1 && cells[index + 1] == '.') {
                adjacentDotCount++;
            }
        }

        public int getAdjacentDotCount() {
            return adjacentDotCount;
        }
    }

    /**
     * Fast I/O utility class for efficient reading of input.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
