/**
 * This program tracks the number of adjacent dot pairs (..) in a string
 * as characters in the string are updated via queries.
 */
public class DotPairTrackerApp {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            int n = scanner.nextInt();
            int queryCount = scanner.nextInt();
            String initialString = scanner.next();

            DotPairTracker tracker = new DotPairTracker(initialString);

            for (int i = 0; i < queryCount; i++) {
                int index = scanner.nextInt() - 1; // Convert to 0-based index
                char newChar = scanner.next().charAt(0);

                tracker.updateCharacter(index, newChar);
                out.println(tracker.getDotPairCount());
            }
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Manages the string content and maintains the count of adjacent '.' pairs.
     */
    static class DotPairTracker {
        private final StringBuilder grid;
        private final int length;
        private int dotPairCount;

        public DotPairTracker(String initialString) {
            this.grid = new StringBuilder(initialString);
            this.length = initialString.length();
            this.dotPairCount = calculateInitialPairs();
        }

        /**
         * Calculates the initial number of ".." pairs in O(N).
         */
        private int calculateInitialPairs() {
            int count = 0;
            for (int i = 0; i < length - 1; i++) {
                if (grid.charAt(i) == '.' && grid.charAt(i + 1) == '.') {
                    count++;
                }
            }
            return count;
        }

        /**
         * Updates a character at a specific index and updates the pair count in O(1).
         * 
         * @param index The index to change.
         * @param newChar The new character to place at that index.
         */
        public void updateCharacter(int index, char newChar) {
            if (index < 0 || index >= length || grid.charAt(index) == newChar) {
                return;
            }

            // 1. Remove the impact of the old character on the pair count
            if (grid.charAt(index) == '.') {
                dotPairCount -= countPairsAt(index);
            }

            // 2. Apply the change
            grid.setCharAt(index, newChar);

            // 3. Add the impact of the new character on the pair count
            if (grid.charAt(index) == '.') {
                dotPairCount += countPairsAt(index);
            }
        }

        /**
         * Helper to count how many '.' pairs involve the character at the given index.
         */
        private int countPairsAt(int index) {
            int pairs = 0;
            // Check pair with left neighbor
            if (index > 0 && grid.charAt(index - 1) == '.') {
                pairs++;
            }
            // Check pair with right neighbor
            if (index < length - 1 && grid.charAt(index + 1) == '.') {
                pairs++;
            }
            return pairs;
        }

        public int getDotPairCount() {
            return dotPairCount;
        }
    }

