import java.io.*;
import java.util.*;

/**
 * A program that tracks the number of adjacent dot ('.') pairs in a character sequence
 * as specific characters are updated.
 */
public class DotPairCounter {

    /**
     * Encapsulates the logic for managing a character sequence and 
     * maintaining the count of adjacent dot ('.') pairs.
     */
    private static class SequenceTracker {
        private final char[] sequence;
        private int dotPairCount;

        /**
         * Initializes the tracker with an initial sequence and calculates initial pairs.
         * 
         * @param initialSequence The starting string.
         */
        public SequenceTracker(String initialSequence) {
            this.sequence = initialSequence.toCharArray();
            this.dotPairCount = calculateInitialDotPairs();
        }

        private int calculateInitialDotPairs() {
            int count = 0;
            for (int i = 0; i < sequence.length - 1; i++) {
                if (isDotPair(i, i + 1)) {
                    count++;
                }
            }
            return count;
        }

        private boolean isDotPair(int i, int j) {
            return sequence[i] == '.' && sequence[j] == '.';
        }

        /**
         * Updates the character at a specific index and returns the updated pair count.
         *
         * @param index   The 0-based index to update.
         * @param newChar The new character to place at the index.
         * @return The updated count of adjacent dot pairs.
         */
        public int update(int index, char newChar) {
            // If index is out of bounds or the character is unchanged, return current count.
            if (index < 0 || index >= sequence.length || sequence[index] == newChar) {
                return dotPairCount;
            }

            // 1. Remove the contribution of pairs involving the current index before modification.
            dotPairCount -= countPairsInvolving(index);

            // 2. Apply the update.
            sequence[index] = newChar;

            // 3. Add the contribution of pairs involving the current index after modification.
            dotPairCount += countPairsAt(index);

            return dotPairCount;
        }

        /**
         * Counts how many adjacent dot pairs ('.') include the character at the given index.
         */
        private int countPairsAt(int index) {
            int count = 0;
            // Check pair with the left neighbor
            if (index > 0 && isDotPair(index - 1, index)) {
                count++;
            }
            // Check pair with the right neighbor
            if (index < sequence.length - 1 && isDotPair(index, index + 1)) {
                count++;
            }
            return count;
        }

        /**
         * Helper to count pairs involving an index by looking at the state *before* change.
         * This is logically identical to countPairsAt but used for subtraction logic.
         */
        private int countPairsInvolving(int index) {
            return countPairsAt(index);
        }
    }

    /**
     * Fast I/O utility to handle large input volumes efficiently.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            return next != null ? Integer.parseInt(next) : 0;
        }
    }

    public static void main(String[] args) {
        FastReader sc = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            String nToken = sc.next();
            if (nToken == null) return;

            int n = Integer.parseInt(nToken);
            int m = sc.nextInt();
            String initialString = sc.next();

            SequenceTracker tracker = new SequenceTracker(initialString);

            for (int i = 0; i < m; i++) {
                // Convert 1-based input index to 0-based
                int targetIndex = sc.nextInt() - 1;
                String charInput = sc.next();
                if (charInput == null) break;

                char newChar = charInput.charAt(0);
                out.println(tracker.update(targetIndex, newChar));
            }
        } catch (Exception e) {
            // In a real-world scenario, use a logging framework instead of printing stack traces.
        } finally {
            out.flush();
            out.close();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solution to track the number of dots and contiguous dot segments in a sequence
 * as characters are replaced.
 */
public class DotSegmentCalculator {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        Solver solver = new Solver();
        solver.solve(reader, writer);

        writer.flush();
        writer.close();
    }

    /**
     * Contains the logic for processing the sequence and queries.
     */
    static class Solver {
        private char[] sequence;
        private int n;
        private int dotCount = 0;
        private int segmentCount = 0;

        /**
         * Reads the input and processes each query.
         * 
         * @param in  The fast reader for input.
         * @param out The print writer for output.
         */
        public void solve(FastReader in, PrintWriter out) {
            int length = in.nextInt();
            int queries = in.nextInt();
            sequence = in.next().toCharArray();
            n = length;

            // Initial calculation of dots and contiguous dot segments
            for (int i = 0; i < n; i++) {
                if (isDotAt(i)) {
                    dotCount++;
                    // If it's the start of a new segment
                    if (i == 0 || !isDotAt(i - 1)) {
                        segmentCount++;
                    }
                }
            }

            for (int q = 0; q < queries; q++) {
                int position = in.nextInt() - 1; // Convert to 0-indexed
                char replacement = in.nextChar();

                updateSequence(position, replacement);

                // The problem asks for (total dots - number of segments)
                out.println(dotCount - segmentCount);
            }
        }

        /**
         * Updates the character at a position and adjusts segment/dot counts in O(1).
         */
        private void updateSequence(int i, char replacement) {
            if (i < 0 || i >= n || sequence[i] == replacement) {
                return;
            }

            if (sequence[i] == '.') {
                // Changing a dot to a non-dot
                dotCount--;
                if (isDotAt(i - 1) && isDotAt(i + 1)) {
                    // A single segment is split into two
                    segmentCount++;
                } else if (!isDotAt(i - 1) && !isDotAt(i + 1)) {
                    // An entire segment of length 1 disappeared
                    segmentCount--;
                }
                // If only one neighbor is a dot, the segment count remains the same
            } else {
                // Changing a non-dot to a dot
                dotCount++;
                if (isDotAt(i - 1) && isDotAt(i + 1)) {
                    // Two separate segments merged into one
                    segmentCount--;
                } else if (!isDotAt(i - 1) && !isDotAt(i + 1)) {
                    // A brand new segment of length 1 is created
                    segmentCount++;
                }
                // If only one neighbor is a dot, the segment count remains the same
            }

            sequence[i] = replacement;
        }

        private boolean isDotAt(int i) {
            return i >= 0 && i < n && sequence[i] == '.';
        }
    }

    /**
     * High-performance input reader for large datasets.
     */
    static class FastReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int curChar;
        private int numChars;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (numChars == -1) throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buffer);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) return -1;
            }
            return buffer[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isWhitespace(c)) c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res = res * 10 + (c - '0');
                c = read();
            } while (!isWhitespace(c));
            return res * sgn;
        }

        public String next() {
            int c = read();
            while (isWhitespace(c)) c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isWhitespace(c));
            return res.toString();
        }

        public char nextChar() {
            int c = read();
            while (isWhitespace(c)) c = read();
            return (char) c;
        }

        private boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

