/**
 * A program that manages a grid of characters and tracks the number of 
 * adjacent dot ('.') pairs after various updates.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = reader.nextInt(); // Length of the grid
            int m = reader.nextInt(); // Number of queries

            char[] initialChars = reader.next().toCharArray();
            DotGridManager gridManager = new DotGridManager(initialChars);

            for (int i = 0; i < m; i++) {
                int targetIndex = reader.nextInt() - 1; // Convert to 0-based indexing
                char newChar = reader.next().charAt(0);

                gridManager.update(targetIndex, newChar);
                out.println(gridManager.getAdjacentDotPairs());
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Manages the grid state and calculates the score.
     * The score (total dots - segment count) is mathematically equivalent 
     * to the number of adjacent pairs of dots.
     */
    static class DotGridManager {
        private final char[] grid;
        private int adjacentDotPairs;

        public DotGridManager(char[] initialGrid) {
            this.grid = initialGrid;
            this.adjacentDotPairs = calculateInitialPairs();
        }

        /**
         * Updates a character at a specific index and incrementally 
         * updates the adjacent dot pair count.
         */
        public void update(int index, char newChar) {
            if (index < 0 || index >= grid.length || grid[index] == newChar) {
                return;
            }

            // 1. Remove contribution of the old character
            removeContribution(index);

            // 2. Apply the change
            grid[index] = newChar;

            // 3. Add contribution of the new character
            addContribution(index);
        }

        public int getAdjacentDotPairs() {
            return adjacentDotPairs;
        }

        private int calculateInitialPairs() {
            int pairs = 0;
            for (int i = 0; i < grid.length - 1; i++) {
                if (isDotPair(i, i + 1)) {
                    pairs++;
                }
            }
            return pairs;
        }

        private void removeContribution(int index) {
            if (index > 0 && isDotPair(index - 1, index)) {
                adjacentDotPairs--;
            }
            if (index < grid.length - 1 && isDotPair(index, index + 1)) {
                adjacentDotPairs--;
            }
        }

        private void addContribution(int index) {
            if (index > 0 && isDotPair(index - 1, index)) {
                adjacentDotPairs++;
            }
            if (index < grid.length - 1 && isDotPair(index, index + 1)) {
                adjacentDotPairs++;
            }
        }

        private boolean isDotPair(int i, int j) {
            return grid[i] == '.' && grid[j] == '.';
        }
    }

    /**
     * Utility class for fast input reading.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * This class manages a sequence of positions that can be either empty ('.') or occupied ('#').
 * It tracks the number of adjacent pairs of empty positions and allows for efficient updates.
 */
class EmptySpotManager {
    private final boolean[] isEmpty;
    private int adjacentEmptyCount;
    private final int length;

    /**
     * Initializes the manager with an initial configuration string.
     *
     * @param configuration The initial string of '.' and '#' characters.
     */
    public EmptySpotManager(String configuration) {
        this.length = configuration.length();
        // Using n + 2 to prevent IndexOutOfBounds when checking neighbors of 1 or n
        this.isEmpty = new boolean[length + 2];
        this.adjacentEmptyCount = 0;

        char[] configChars = configuration.toCharArray();
        for (int i = 0; i < length; i++) {
            if (configChars[i] == '.') {
                isEmpty[i + 1] = true;
            }
        }

        // Calculate the initial count of adjacent empty spots
        for (int i = 1; i < length; i++) {
            if (isEmpty[i] && isEmpty[i + 1]) {
                adjacentEmptyCount++;
            }
        }
    }

    /**
     * Updates the status of a specific position and adjusts the adjacency count.
     *
     * @param position The 1-based position to update.
     * @param type     The new character type: '.' for empty or '#' for occupied.
     */
    public void update(int position, char type) {
        boolean targetEmpty = (type == '.');
        boolean currentlyEmpty = isEmpty[position];

        // If the status is not actually changing, return early
        if (targetEmpty == currentlyEmpty) {
            return;
        }

        if (targetEmpty) {
            // Transition: Occupied (#) -> Empty (.)
            // Check if this new empty spot creates new adjacent pairs with neighbors
            if (isEmpty[position - 1]) {
                adjacentEmptyCount++;
            }
            if (isEmpty[position + 1]) {
                adjacentEmptyCount++;
            }
            isEmpty[position] = true;
        } else {
            // Transition: Empty (.) -> Occupied (#)
            // Check if removing this empty spot breaks existing adjacent pairs
            if (isEmpty[position - 1]) {
                adjacentEmptyCount--;
            }
            if (isEmpty[position + 1]) {
                adjacentEmptyCount--;
            }
            isEmpty[position] = false;
        }
    }

    /**
     * @return The current number of adjacent empty spot pairs.
     */
    public int getAdjacentEmptyCount() {
        return adjacentEmptyCount;
    }
}

public class ConsecutiveEmptySpots {

    public static void main(String[] args) {
        // Using BufferedReader and PrintWriter for high-performance I/O
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)))) {

