/**
 * This program manages a sequence of characters and tracks the number of 
 * contiguous pairs of '.' characters. It supports efficient updates to the sequence.
 */
public class Major {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        try {
            String firstLine = reader.readLine();
            if (firstLine == null) return;

            StringTokenizer st = new StringTokenizer(firstLine);
            int n = Integer.parseInt(st.nextToken());
            int m = Integer.parseInt(st.nextToken());

            String initialSequence = reader.readLine();
            if (initialSequence == null) return;

            DotSequenceManager manager = new DotSequenceManager(initialSequence);
            StringBuilder output = new StringBuilder();

            for (int i = 0; i < m; i++) {
                String queryLine = reader.readLine();
                if (queryLine == null) break;

                StringTokenizer querySt = new StringTokenizer(queryLine);
                // Input is 1-indexed, convert to 0-indexed
                int index = Integer.parseInt(querySt.nextToken()) - 1;
                char newChar = querySt.nextToken().charAt(0);

                manager.update(index, newChar);
                output.append(manager.getAdjacentDotCount()).append('\n');
            }

            System.out.print(output);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /**
     * Manages a sequence of characters and maintains a running count of 
     * adjacent '.' pairs.
     */
    static class DotSequenceManager {
        private final char[] grid;
        private int adjacentDotCount;

        public DotSequenceManager(String initialStr) {
            this.grid = initialStr.toCharArray();
            this.adjacentDotCount = calculateInitialAdjacentDots(this.grid);
        }

        /**
         * Calculates the initial number of adjacent dot pairs in O(N).
         */
        private int calculateInitialAdjacentDots(char[] grid) {
            int count = 0;
            for (int i = 0; i < grid.length - 1; i++) {
                if (grid[i] == '.' && grid[i + 1] == '.') {
                    count++;
                }
            }
            return count;
        }

        /**
         * Updates the character at the specified index and adjusts the 
         * adjacent dot count in O(1).
         * 
         * @param index The 0-indexed position to update.
         * @param newChar The new character to place at the index.
         */
        public void update(int index, char newChar) {
            if (index < 0 || index >= grid.length) {
                return;
            }

            char oldChar = grid[index];
            if (oldChar == newChar) {
                return;
            }

            // Case 1: We are removing a dot
            if (oldChar == '.') {
                if (index > 0 && grid[index - 1] == '.') {
                    adjacentDotCount--;
                }
                if (index < grid.length - 1 && grid[index + 1] == '.') {
                    adjacentDotCount--;
                }
            } 
            // Case 2: We are adding a dot
            else if (newChar == '.') {
                if (index > 0 && grid[index - 1] == '.') {
                    adjacentDotCount++;
                }
                if (index < grid.length - 1 && grid[index + 1] == '.') {
                    adjacentDotCount++;
                }
            }
            // Case 3: Transitioning between two different non-dot characters 
            // (e.g., '#' to '*') does not affect adjacentDotCount.

            grid[index] = newChar;
        }

        public int getAdjacentDotCount() {
            return adjacentDotCount;
        }
    }

    /**
     * Helper class for fast I/O operations.
     */
    static class FastReader {
        private final BufferedReader reader;

        public FastReader(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String readLine() throws IOException {
            return reader.readLine();
        }
    }
}

