/**
 * Refactored solution for the Replacement problem.
 * This program maintains a count of adjacent '.' pairs in a string
 * while supporting character updates in O(1) time per update.
 */
public class Replacement {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        // Read initial constraints
        int n = reader.nextInt();
        int m = reader.nextInt();

        if (n <= 0) {
            writer.close();
            return;
        }

        String initialString = reader.next();
        char[] charArray = initialString.toCharArray();

        // Initialize the manager with the current state
        DotPairManager manager = new DotPairManager(charArray);

        // Process m updates
        for (int i = 0; i < m; i++) {
            int index = reader.nextInt() - 1; // Convert 1-based to 0-based index
            char newChar = reader.next().charAt(0);

            manager.update(index, newChar);
            writer.println(manager.getDotPairCount());
        }

        writer.flush();
        writer.close();
    }

    /**
     * Encapsulates the logic for tracking the number of adjacent dot pairs ('.').
     */
    static class DotPairManager {
        private final char[] characters;
        private final int length;
        private int dotPairCount;

        public DotPairManager(char[] initialChars) {
            this.characters = initialChars;
            this.length = initialChars.length;
            this.dotPairCount = 0;
            calculateInitialSum();
        }

        /**
         * Calculates the initial count of adjacent dot pairs.
         */
        private void calculateInitialSum() {
            for (int i = 0; i < length - 1; i++) {
                if (isDotPair(i, i + 1)) {
                    dotPairCount++;
                }
            }
        }

        /**
         * Updates a character at a specific index and adjusts the pair count.
         * Complexity: O(1)
         */
        public void update(int index, char newChar) {
            // Validate index and check if an update is actually needed
            if (index < 0 || index >= length || characters[index] == newChar) {
                return;
            }

            // 1. Remove contribution of current character to the pair count
            removeContributions(index);

            // 2. Update the character
            characters[index] = newChar;

            // 3. Add contribution of the new character to the pair count
            addContributions(index);
        }

        private void removeContributions(int i) {
            if (isDotPair(i - 1, i)) {
                dotPairCount--;
            }
            if (isDotPair(i, i + 1)) {
                dotPairCount--;
            }
        }

        private void addContributions(int i) {
            if (isDotPair(i - 1, i)) {
                dotPairCount++;
            }
            if (isDotPair(i, i + 1)) {
                dotPairCount++;
            }
        }

        private boolean isDotPair(int idx1, int idx2) {
            if (idx1 < 0 || idx2 >= length) {
                return false;
            }
            return characters[idx1] == '.' && characters[idx2] == '.';
        }

        public int getDotPairCount() {
            return dotPairCount;
        }
    }

    /**
     * Utility class for fast I/O operations.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

