        int queryCount = Integer.parseInt(mStr);

        // Read the initial grid configuration
        String gridString = reader.next();
        if (gridString == null) {
            return;
        }
        char[] grid = gridString.toCharArray();

        // Calculate the initial number of adjacent '.' pairs
        int dotPairCount = 0;
        for (int i = 0; i < gridSize - 1; i++) {
            if (grid[i] == '.' && grid[i + 1] == '.') {
                dotPairCount++;
            }
        }

        // Process each query
        for (int i = 0; i < queryCount; i++) {
            String posStr = reader.next();
            String charStr = reader.next();
            if (posStr == null || charStr == null) {
                break;
            }

            // Convert 1-based index to 0-based index
            int index = Integer.parseInt(posStr) - 1;
            char newChar = charStr.charAt(0);

            // Updates are only meaningful if the grid size allows for pairs
            if (gridSize > 1) {
                char oldChar = grid[index];

                // Only perform logic if the character actually changes
                if (oldChar != newChar) {
                    if (oldChar == '.') {
                        // Transitioning from '.' to another character:
                        // Decrement count if the neighbor was also a '.'
                        if (index > 0 && grid[index - 1] == '.') {
                            dotPairCount--;
                        }
                        if (index < gridSize - 1 && grid[index + 1] == '.') {
                            dotPairCount--;
                        }
                    } else {
                        // Transitioning from another character to '.':
                        // Increment count if the neighbor is a '.'
                        if (index > 0 && grid[index - 1] == '.') {
                            dotPairCount++;
                        }
                        if (index < gridSize - 1 && grid[index + 1] == '.') {
                            dotPairCount++;
                        }
