/**
 * This program tracks the number of adjacent pairs of '.' characters in a sequence
 * as characters are updated via queries.
 */
public class Solution {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            solve(reader, writer);
        } finally {
            writer.close();
        }
    }

    private static void solve(FastReader reader, PrintWriter writer) {
        int n = reader.nextInt();
        int queryCount = reader.nextInt();
        String initialSequence = reader.next();

        DotSequence dotSequence = new DotSequence(initialSequence);

        for (int i = 0; i < queryCount; i++) {
            // Input is 1-based, convert to 0-based index
            int position = reader.nextInt() - 1;
            char newChar = reader.next().charAt(0);

            dotSequence.update(position, newChar);
            writer.println(dotSequence.getScore());
        }
    }

    /**
     * Manages the state of the character sequence and maintains the count 
     * of adjacent '.' pairs efficiently.
     */
    static class DotSequence {
        private final char[] sequence;
        private int totalDotPairs;

        public DotSequence(String initialString) {
            this.sequence = initialString.toCharArray();
            this.totalDotPairs = calculateInitialScore();
        }

        /**
         * Calculates the initial score: the count of all indices i 
         * where sequence[i] == '.' and sequence[i+1] == '.'.
         */
        private int calculateInitialScore() {
            int score = 0;
            for (int i = 0; i < sequence.length - 1; i++) {
                if (sequence[i] == '.' && sequence[i + 1] == '.') {
                    score++;
                }
            }
            return score;
        }

        /**
         * Updates a character at a specific index and updates the score in O(1).
         * 
         * @param index The index to update.
         * @param newChar The new character to place at the index.
         */
        public void update(int index, char newChar) {
            char oldChar = sequence[index];
            if (oldChar == newChar) {
                return;
            }

            // If we are removing a dot, we lose pairs with neighbors
            if (oldChar == '.') {
                if (isDot(index - 1)) totalDotPairs--;
                if (isDot(index + 1)) totalDotPairs--;
            } 
            // If we are adding a dot, we gain pairs with neighbors
            else if (newChar == '.') {
                if (isDot(index - 1)) totalDotPairs++;
                if (isDot(index + 1)) totalDotPairs++;
            }

            sequence[index] = newChar;
        }

        private boolean isDot(int index) {
            return index >= 0 && index < sequence.length && sequence[index] == '.';
        }

        public int getScore() {
            return totalDotPairs;
        }
    }

    /**
     * Optimized reader for fast I/O performance.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }
    }
}

