         * Complexity: O(1)
         * 
         * @param index The 0-based index to update.
         * @param newChar The new character to place at the index.
         */
        public void update(int index, char newChar) {
            if (index < 0 || index >= n || characters[index] == newChar) {
                return;
            }

            // 1. Remove the contribution of existing pairs involving this index
            pairCount -= countPairsAt(index);

            // 2. Apply the change
            characters[index] = newChar;

            // 3. Add the contribution of new pairs involving this index
            pairCount += countPairsAt(index);
        }

        /**
         * Counts how many adjacent '.' pairs the current character at 'index' is part of.
         */
        private int countPairsAt(int index) {
            if (characters[index] != '.') {
                return 0;
            }

            int pairs = 0;
            // Check pair with left neighbor
            if (index > 0 && characters[index - 1] == '.') {
                pairs++;
            }
            // Check pair with right neighbor
            if (index < n - 1 && characters[index + 1] == '.') {
                pairs++;
            }
            return pairs;
        }

        public long getPairCount() {
            return pairCount;
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

