/**
 * This program calculates the sum of (length - 1) for all continuous segments 
 * of '.' characters in a string, and updates this sum as characters are modified.
 * Mathematically, this is equivalent to counting the number of adjacent pairs of dots.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            int size = reader.nextInt();
            int updateCount = reader.nextInt();
            char[] grid = reader.next().toCharArray();

            DotSegmentTracker tracker = new DotSegmentTracker(grid);

            for (int i = 0; i < updateCount; i++) {
                int position = reader.nextInt() - 1; // Convert to 0-indexed
                char newChar = reader.next().charAt(0);

                tracker.update(position, newChar);
                writer.println(tracker.getScore());
            }
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    /**
     * Encapsulates the logic for tracking the "score" (sum of segment lengths - 1).
     */
    static class DotSegmentTracker {
        private final char[] grid;
        private final int size;
        private long score;

        public DotSegmentTracker(char[] grid) {
            this.grid = grid;
            this.size = grid.length;
            this.score = 0;
            calculateInitialScore();
        }

        /**
         * Initial calculation: O(N)
         */
        private void calculateInitialScore() {
            for (int i = 0; i < size - 1; i++) {
                if (grid[i] == '.' && grid[i + 1] == '.') {
                    score++;
                }
            }
        }

        /**
         * Updates the grid and the score in O(1) time.
         * @param pos The index to update.
         * @param newChar The new character to place at the index.
         */
        public void update(int pos, char newChar) {
            if (pos < 0 || pos >= size || grid[pos] == newChar) {
                return;
            }

            if (grid[pos] == '.') {
                // Transitioning from '.' to something else: 
                // We lose adjacent pairs at this position.
                if (pos > 0 && grid[pos - 1] == '.') {
                    score--;
                }
                if (pos < size - 1 && grid[pos + 1] == '.') {
                    score--;
                }
            } else {
                // Transitioning from something else to '.': 
                // We gain adjacent pairs at this position.
                if (pos > 0 && grid[pos - 1] == '.') {
                    score++;
                }
                if (pos < size - 1 && grid[pos + 1] == '.') {
                    score++;
                }
            }

            grid[pos] = newChar;
        }

        public long getScore() {
            return score;
        }
    }

