/**
 * A program that tracks the relationship between the number of '.' characters 
 * and the number of contiguous segments of '.' characters in a grid/line.
 * 
 * Time Complexity: O(N + M) where N is the initial length and M is the number of queries.
 * Space Complexity: O(N) to store the grid state.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        PrintWriter writer = new PrintWriter(System.out);

        try {
            String firstLine = reader.readLine();
            if (firstLine == null) return;

            StringTokenizer st = new StringTokenizer(firstLine);
            int n = Integer.parseInt(st.nextToken());
            int m = Integer.parseInt(st.nextToken());

            String initialGridLine = reader.readLine();

            // If n is 0, there are no elements to process.
            if (n <= 0) {
                for (int i = 0; i < m; i++) {
                    reader.readLine(); // Consume query input
                    writer.println(0);
                }
            } else {
                GridTracker tracker = new GridTracker(initialGridLine, n);

                for (int i = 0; i < m; i++) {
                    String queryLine = reader.readLine();
                    if (queryLine == null) break;

                    StringTokenizer querySt = new StringTokenizer(queryLine);
                    if (querySt.countTokens() < 2) break;

                    // Input indices are 1-based, converting to 0-based.
                    int index = Integer.parseInt(querySt.nextToken()) - 1;
                    char newChar = querySt.nextToken().charAt(0);

                    tracker.update(index, newChar);
                    writer.println(tracker.getResult());
                }
            }
        } catch (Exception e) {
            // In a real-world application, use a proper logging framework.
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Manages the state of the grid and updates dot and segment counts incrementally.
     */
    static class GridTracker {
        private final char[] grid;
        private int dotCount;
        private int segmentCount;
        private final int n;

        public GridTracker(String initial, int n) {
            this.n = n;
            this.grid = (initial != null) ? initial.toCharArray() : new char[n];
            this.dotCount = 0;
            this.segmentCount = 0;

            initializeCounts();
        }

        private void initializeCounts() {
            for (int i = 0; i < n; i++) {
                if (grid[i] == '.') {
                    dotCount++;
                    // A segment starts if current is '.' and it's either the first element 
                    // or the previous element was not a '.'
                    if (i == 0 || grid[i - 1] != '.') {
                        segmentCount++;
                    }
                }
            }
        }

        /**
         * Updates the character at the given index and adjusts counts in O(1).
         * @param index 0-based index in the grid.
         * @param newChar The character to set at the index.
         */
        public void update(int index, char newChar) {
            if (index < 0 || index >= n || grid[index] == newChar) {
                return;
            }

            if (grid[index] == '.') {
                // Case: Changing '.' to a non-dot character
                dotCount--;
                int neighbors = countDotNeighbors(index);
                if (neighbors == 0) {
                    segmentCount--; // Segment is completely destroyed
                } else if (neighbors == 2) {
                    segmentCount++; // A single segment is split into two
                }
                // If neighbors == 1, the segment simply shrinks, so segmentCount is unchanged.
            } else {
                // Case: Changing a non-dot character to '.'
                dotCount++;
                int neighbors = countDotNeighbors(index);
                if (neighbors == 0) {
                    segmentCount++; // A new isolated segment is created
                } else if (neighbors == 2) {
                    segmentCount--; // Two existing segments are merged into one
                }
                // If neighbors == 1, the segment simply grows, so segmentCount is unchanged.
            }
            grid[index] = newChar;
        }

        /**
         * Counts how many immediate neighbors of the index are '.'
         */
        private int countDotNeighbors(int index) {
            int count = 0;
            if (index > 0 && grid[index - 1] == '.') {
                count++;
            }
            if (index < n - 1 && grid[index + 1] == '.') {
                count++;
            }
            return count;
        }

        /**
         * Returns the value required by the problem: (total dots - total segments).
         */
        public int getResult() {
            return dotCount - segmentCount;
        }
    }

    /**
     * Fast I/O utility.
     */
    static class FastReader {
        private final BufferedReader reader;

        public FastReader() {
            reader = new BufferedReader(new InputStreamReader(System.in));
        }

        public String readLine() {
            try {
                return reader.readLine();
            } catch (IOException e) {
                return null;
            }
        }
    }
}

