/**
 * A program that manages a sequence of characters and tracks the number of 
 * adjacent dot pairs ('.') after various updates.
 */
public class Solution {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            String nStr = scanner.next();
            if (nStr == null) return;

            int n = Integer.parseInt(nStr);
            int q = scanner.nextInt();
            String initialState = scanner.next();

            DotSequenceManager manager = new DotSequenceManager(n, initialState);

            for (int i = 0; i < q; i++) {
                int position = scanner.nextInt();
                String charInput = scanner.next();
                boolean targetIsDot = charInput.charAt(0) == '.';

                manager.update(position, targetIsDot);
                out.println(manager.getAdjacentDotPairs());
            }
        } catch (Exception e) {
            // In a production environment, use a logger.
            e.printStackTrace();
        } finally {
            out.close();
        }
    }

    /**
     * Manages the state of a sequence to efficiently track dot counts 
     * and contiguous dot segments.
     */
    static class DotSequenceManager {
        private final boolean[] isDot;
        private int dotCount = 0;
        private int segmentCount = 0;

        /**
         * Initializes the manager with the starting sequence.
         * @param n Total length of the sequence.
         * @param initial The initial string representation.
         */
        public DotSequenceManager(int n, String initial) {
            // We use n + 2 to support 1-based indexing and provide padding 
            // at index 0 and n+1 to avoid boundary checks during neighbor lookups.
            this.isDot = new boolean[n + 2];
            for (int i = 0; i < n; i++) {
                if (initial.charAt(i) == '.') {
                    int idx = i + 1; // Convert 0-based string index to 1-based
                    isDot[idx] = true;
                    dotCount++;
                    // If the previous element was not a dot, we've started a new segment.
                    if (!isDot[idx - 1]) {
                        segmentCount++;
                    }
                }
            }
        }

        /**
         * Updates the character at the specified index.
         * @param idx The 1-based index of the character to update.
         * @param becomesDot The new state (true if '.', false otherwise).
         */
        public void update(int idx, boolean becomesDot) {
            if (isDot[idx] == becomesDot) {
                return;
            }

            boolean leftIsDot = isDot[idx - 1];
            boolean rightIsDot = isDot[idx + 1];

            if (becomesDot) {
                dotCount++;
                if (leftIsDot && rightIsDot) {
                    // Two existing segments are merged into one.
                    segmentCount--;
                } else if (!leftIsDot && !rightIsDot) {
                    // A new isolated segment is created.
                    segmentCount++;
                }
                // If only one neighbor is a dot, the segment simply extends (count unchanged).
            } else {
                dotCount--;
                if (leftIsDot && rightIsDot) {
                    // One segment is split into two.
                    segmentCount++;
                } else if (!leftIsDot && !rightIsDot) {
                    // The segment is removed entirely.
                    segmentCount--;
                }
                // If only one neighbor is a dot, the segment simply shrinks (count unchanged).
            }
            isDot[idx] = becomesDot;
        }

        /**
         * Calculates the number of adjacent dot-dot pairs.
         * For a segment of length K, there are K-1 adjacent pairs.
         * Total pairs = Sum(k_i - 1) = Sum(k_i) - Sum(1) = totalDots - totalSegments.
         * 
         * @return The count of adjacent dot pairs.
         */
        public int getAdjacentDotPairs() {
            return dotCount - segmentCount;
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

