/**
 * A program to track the number of adjacent dot pairs in a character array
 * as cells are updated via queries.
 */
public class DotPairTracker {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            solve(reader, writer);
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            writer.flush();
            writer.close();
        }
    }

    private static void solve(FastReader reader, PrintWriter writer) {
        int gridLength = reader.nextInt();
        int queryCount = reader.nextInt();
        char[] initialCells = reader.next().toCharArray();

        DotGrid grid = new DotGrid(initialCells);

        for (int i = 0; i < queryCount; i++) {
            // Input positions are 1-indexed in the original problem
            int position = reader.nextInt() - 1;
            char newChar = reader.nextChar();

            int currentAdjacentPairs = grid.updateCell(position, newChar);
            writer.println(currentAdjacentPairs);
        }
    }

    /**
     * Encapsulates the grid state and the logic for counting adjacent '.' pairs.
     */
    static class DotGrid {
        private final char[] cells;
        private int adjacentDotPairs;

        public DotGrid(char[] initialCells) {
            this.cells = initialCells;
            this.adjacentDotPairs = calculateInitialPairs();
        }

        /**
         * Counts the number of pairs (i, i+1) where both cells are '.'.
         */
        private int calculateInitialPairs() {
            int count = 0;
            for (int i = 0; i < cells.length - 1; i++) {
                if (cells[i] == '.' && cells[i + 1] == '.') {
                    count++;
                }
            }
            return count;
        }

        /**
         * Updates a cell and returns the new count of adjacent dot pairs.
         * 
         * @param index The index of the cell to update.
         * @param newChar The new character to place in the cell.
         * @return The updated count of adjacent dot pairs.
         */
        public int updateCell(int index, char newChar) {
            if (index < 0 || index >= cells.length || cells[index] == newChar) {
                return adjacentDotPairs;
            }

            int neighboringDots = countAdjacentDots(index);

            // If we are turning a dot into something else, we lose pairs
            if (cells[index] == '.') {
                adjacentDotPairs -= neighboringDots;
            } 
            // If we are turning something else into a dot, we gain pairs
            else if (newChar == '.') {
                adjacentDotPairs += neighboringDots;
            }

            cells[index] = newChar;
            return adjacentDotPairs;
        }

        private int countAdjacentDots(int index) {
            int count = 0;
            if (index > 0 && cells[index - 1] == '.') {
                count++;
            }
            if (index < cells.length - 1 && cells[index + 1] == '.') {
                count++;
            }
            return count;
        }
    }

    /**
     * High-performance reader for efficient input processing.
     */
    static class FastReader {
        private final InputStream in;
        private final byte[] buffer = new byte[1024 * 16];
        private int pointer = 0;
        private int bufferLength = 0;

        public FastReader(InputStream in) {
            this.in = in;
        }

        private boolean fillBuffer() {
            try {
                bufferLength = in.read(buffer);
                pointer = 0;
                return bufferLength > 0;
            } catch (IOException e) {
                return false;
            }
        }

        private int read() {
            if (pointer >= bufferLength) {
                if (!fillBuffer()) return -1;
            }
            return buffer[pointer++] & 0xff;
        }

        public String next() {
            int b = read();
            while (b != -1 && b <= 32) b = read(); // Skip whitespace
            if (b == -1) return null;

            StringBuilder sb = new StringBuilder();
            while (b > 32) {
                sb.append((char) b);
                b = read();
            }
            return sb.toString();
        }

        public int nextInt() {
            return (int) nextLong();
        }

        public long nextLong() {
            int b = read();
            while (b != -1 && b <= 32) b = read();
            if (b == -1) throw new NoSuchElementException();

            boolean negative = false;
            if (b == '-') {
                negative = true;
                b = read();
            }

            long res = 0;
            while (b >= '0' && b <= '9') {
                res = res * 10 + (b - '0');
                b = read();
            }
            return negative ? -res : res;
        }

        public char nextChar() {
            int b = read();
            while (b != -1 && b <= 32) b = read();
            if (b == -1) throw new NoSuchElementException();
            return (char) b;
        }
    }
}

