/**
 * A program that tracks the number of adjacent dot pairs ('.') in a string
 * and updates the count as characters in the string are replaced.
 */
public class Replacement {

    public static void main(String[] args) throws IOException {
        FastReader reader = new FastReader();

        // Read n (length) and m (number of queries)
        String firstLine = reader.nextLine();
        if (firstLine == null) return;

        StringTokenizer st = new StringTokenizer(firstLine);
        int length = Integer.parseInt(st.nextToken());
        int queryCount = Integer.parseInt(st.nextToken());

        // Read the initial string
        String initialString = reader.nextLine();
        if (initialString == null) initialString = "";

        // Initialize the manager with the string
        DotPairManager manager = new DotPairManager(initialString);

        StringBuilder output = new StringBuilder();
        for (int i = 0; i < queryCount; i++) {
            String queryLine = reader.nextLine();
            if (queryLine == null) break;

            st = new StringTokenizer(queryLine);
            // Convert 1-based index from input to 0-based index for internal array
            int index = Integer.parseInt(st.nextToken()) - 1;
            char newChar = st.nextToken().charAt(0);

            manager.update(index, newChar);
            output.append(manager.getDotPairCount()).append("\n");
        }

        // Print all results at once for efficiency
        System.out.print(output.toString());
    }

    /**
     * Encapsulates the state of the character array and the count of adjacent dot pairs.
     */
    static class DotPairManager {
        private final char[] characters;
        private int dotPairCount;

        public DotPairManager(String initialString) {
            this.characters = initialString.toCharArray();
            this.dotPairCount = calculateInitialPairs();
        }

        private int calculateInitialPairs() {
            int count = 0;
            for (int i = 0; i < characters.length - 1; i++) {
                if (isDotPair(i, i + 1)) {
                    count++;
                }
            }
            return count;
        }

        /**
         * Updates a character at a specific index and adjusts the pair count.
         * @param index 0-based index of the character to change.
         * @param newChar The new character to place at the index.
         */
        public void update(int index, char newChar) {
            if (index < 0 || index >= characters.length || characters[index] == newChar) {
                return;
            }

            // 1. Remove contributions of existing pairs involving this index
            if (index > 0 && isDotPair(index - 1, index)) {
                dotPairCount--;
            }
            if (index < characters.length - 1 && isDotPair(index, index + 1)) {
                dotPairCount--;
            }

            // 2. Perform the update
            characters[index] = newChar;

            // 3. Add contributions of new pairs involving this index
            if (index > 0 && isDotPair(index - 1, index)) {
                dotPairCount++;
            }
            if (index < characters.length - 1 && isDotPair(index, index + 1)) {
                dotPairCount++;
            }
        }

        private boolean isDotPair(int i, int j) {
            return characters[i] == '.' && characters[j] == '.';
        }

        public int getDotPairCount() {
            return dotPairCount;
        }
    }

    /**
     * Helper class for faster input reading.
     */
    static class FastReader {
        private final BufferedReader br;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String nextLine() throws IOException {
            return br.readLine();
        }
    }
}

