/**
 * Solution manages a sequence of characters and tracks the number of 
 * consecutive '.' pairs in O(1) time per update.
 */
public class Solution {

    public static void main(String[] args) {
        FastReader sc = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            int n = sc.nextInt();
            int m = sc.nextInt();
            String initialString = sc.next();

            DotSequence sequence = new DotSequence(initialString);

            for (int i = 0; i < m; i++) {
                int index = sc.nextInt(); // 1-based index
                String updateVal = sc.next();
                char newChar = updateVal.charAt(0);

                // Update the sequence and print the new count
                // Subtract 1 because the input index is 1-based
                sequence.update(index - 1, newChar);
                out.println(sequence.getDotPairCount());
            }
        } catch (Exception e) {
            // In a production environment, use a proper logging framework
            e.printStackTrace();
        } finally {
            out.close();
        }
    }

    /**
     * Logic class that maintains the state of the character sequence
     * and the count of ".." substrings.
     */
    static class DotSequence {
        private final char[] elements;
        private final int length;
        private long dotPairCount;

        public DotSequence(String s) {
            this.elements = s.toCharArray();
            this.length = elements.length;
            this.dotPairCount = 0;
            calculateInitialCount();
        }

        private void calculateInitialCount() {
            for (int i = 0; i < length - 1; i++) {
                if (isDotPair(i)) {
                    dotPairCount++;
                }
            }
        }

        /**
         * Updates a character at a specific index and updates the pair count.
         * Complexity: O(1)
         */
        public void update(int index, char newChar) {
            if (index < 0 || index >= length) {
                return;
            }

            // 1. Remove the contribution of existing pairs involving this index
            if (isDotPair(index - 1)) dotPairCount--;
            if (isDotPair(index)) dotPairCount--;

            // 2. Apply the change
            elements[index] = newChar;

            // 3. Add the contribution of the new pairs created by this change
            if (isDotPair(index - 1)) dotPairCount++;
            if (isDotPair(index)) dotPairCount++;
        }

        /**
         * Checks if the pair starting at index i is a ".." pair.
         */
        private boolean isDotPair(int i) {
            return i >= 0 && i < length - 1 
                    && elements[i] == '.' 
                    && elements[i + 1] == '.';
        }

        public long getDotPairCount() {
            return dotPairCount;
        }
    }

    /**
     * Utility class for fast input reading.
     */
