/**
 * A program that maintains the count of adjacent '.' characters in a grid 
 * as characters are updated via queries.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            // Read initial grid size and number of queries
            int gridSize = reader.nextInt();
            int queryCount = reader.nextInt();

            // Read initial grid configuration
            char[] initialGrid = reader.next().toCharArray();

            // Initialize the logic manager
            GridManager gridManager = new GridManager(initialGrid);

            // Process queries
            for (int i = 0; i < queryCount; i++) {
                int targetIndex = reader.nextInt() - 1; // Convert to 0-based index
                char newChar = reader.next().charAt(0);

                gridManager.update(targetIndex, newChar);
                out.println(gridManager.getAdjacentDotsCount());
            }
        } catch (Exception e) {
            // In a production environment, use a proper logging framework
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Manages the state of the grid and calculates the number of adjacent '.' pairs.
     * An adjacent pair is defined as two '.' characters at indices i and i+1.
     */
    static class GridManager {
        private final char[] grid;
        private int adjacentDotsCount;

        public GridManager(char[] initialGrid) {
            this.grid = initialGrid;
            this.adjacentDotsCount = calculateInitialAdjacentDots();
        }

        /**
         * Calculates the initial number of adjacent dot pairs in O(N).
         */
        private int calculateInitialAdjacentDots() {
            int count = 0;
            int currentSegmentLength = 0;

            for (char c : grid) {
                if (c == '.') {
                    currentSegmentLength++;
                } else {
                    if (currentSegmentLength > 0) {
                        count += (currentSegmentLength - 1);
                        currentSegmentLength = 0;
                    }
                }
            }
            if (currentSegmentLength > 0) {
                count += (currentSegmentLength - 1);
            }
            return count;
        }

        /**
         * Updates the character at the specified index and updates the adjacency count in O(1).
         *
         * @param index    The 0-based index in the grid.
         * @param newChar  The new character to place at the index.
         */
        public void update(int index, char newChar) {
            char oldChar = grid[index];
            if (oldChar == newChar) {
                return;
            }

            if (newChar == '.') {
                // Transitioning from '#' to '.'
                // Check if this new '.' creates new adjacent pairs with neighbors
                if (index > 0 && grid[index - 1] == '.') {
                    adjacentDotsCount++;
                }
                if (index < grid.length - 1 && grid[index + 1] == '.') {
                    adjacentDotsCount++;
                }
            } else {
                // Transitioning from '.' to '#'
                // Check if removing this '.' breaks existing adjacent pairs
                if (index > 0 && grid[index - 1] == '.') {
                    adjacentDotsCount--;
                }
                if (index < grid.length - 1 && grid[index + 1] == '.') {
                    adjacentDotsCount--;
                }
            }
            grid[index] = newChar;
        }

        public int getAdjacentDotsCount() {
            return adjacentDotsCount;
        }
    }

    /**
     * Fast I/O utility for reading large inputs efficiently.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * This program manages a grid of cells that can be in two states (Empty or Occupied).
 * It tracks and updates the number of adjacent pairs of empty cells in O(1) time per update.
 */
public class CFTest54 {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = reader.nextInt();
            int m = reader.nextInt();
            String initialLayout = reader.next();

            GridManager gridManager = new GridManager(initialLayout);

            for (int i = 0; i < m; i++) {
                int index = reader.nextInt() - 1; // Convert 1-based input to 0-based index
                String cellChar = reader.next();
                boolean targetIsEmpty = cellChar.equals(".");

                gridManager.updateCell(index, targetIsEmpty);
                out.println(gridManager.getAdjacentEmptyPairsCount());
            }
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            out.close();
        }
    }

    /**
     * Manages the state of the grid and maintains the count of adjacent empty cells.
     */
    static class GridManager {
        private final boolean[] cells;
        private final int size;
        private int adjacentEmptyPairs;

        public GridManager(String layout) {
            this.size = layout.length();
            this.cells = new boolean[size];
            this.adjacentEmptyPairs = 0;

            // Initialize state
            for (int i = 0; i < size; i++) {
                cells[i] = (layout.charAt(i) == '.');
            }

            // Calculate initial adjacent empty pairs
            for (int i = 0; i < size - 1; i++) {
                if (cells[i] && cells[i + 1]) {
                    adjacentEmptyPairs++;
                }
            }
        }

        /**
         * Updates a cell's state and adjusts the adjacent pair count in O(1).
         * @param index The index of the cell to update.
         * @param shouldBeEmpty The new state of the cell.
         */
        public void updateCell(int index, boolean shouldBeEmpty) {
            if (index < 0 || index >= size || cells[index] == shouldBeEmpty) {
                return;
            }

            if (cells[index]) {
                // Current state: Empty -> New state: Occupied
                // We are losing potential pairs with neighbors
                if (index > 0 && cells[index - 1]) {
                    adjacentEmptyPairs--;
                }
                if (index < size - 1 && cells[index + 1]) {
                    adjacentEmptyPairs--;
                }
            } else {
                // Current state: Occupied -> New state: Empty
                // We are gaining potential pairs with neighbors
                if (index > 0 && cells[index - 1]) {
                    adjacentEmptyPairs++;
                }
                if (index < size - 1 && cells[index + 1]) {
                    adjacentEmptyPairs++;
                }
            }

            cells[index] = shouldBeEmpty;
        }

        public int getAdjacentEmptyPairsCount() {
            return adjacentEmptyPairs;
        }
    }

    /**
     * Efficient utility for reading input.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        public double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A program that manages segments of '.' characters in a sequence.
 * It tracks the sum of (end - start) for all continuous segments of dots.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        String nInput = reader.next();
        if (nInput == null) {
            out.close();
            return;
        }

        int n = Integer.parseInt(nInput);
        int m = reader.nextInt();
        char[] sequence = reader.next().toCharArray();

        SegmentManager manager = new SegmentManager(sequence);

        for (int i = 0; i < m; i++) {
            // Convert 1-based indexing from input to 0-based indexing
            int pos = reader.nextInt() - 1;
            char newChar = reader.next().charAt(0);

            manager.update(pos, newChar, sequence);
            out.println(manager.getTotalSum());
        }

        out.flush();
        out.close();
    }

    /**
     * Represents a continuous range of characters in the sequence.
     */
    static class Segment implements Comparable<Segment> {
        final int start;
        final int end;

        Segment(int start, int end) {
            this.start = start;
            this.end = end;
        }

        @Override
        public int compareTo(Segment other) {
            return Integer.compare(this.start, other.start);
        }

        @Override
        public String toString() {
            return start + " " + end;
        }
    }

    /**
     * Manages the set of segments and calculates the sum of (end - start) for all segments.
     */
    static class SegmentManager {
        private final TreeSet<Segment> segments = new TreeSet<>();
        private long totalSum = 0;

        public SegmentManager(char[] sequence) {
            int n = sequence.length;
            for (int i = 0; i < n; ) {
                if (sequence[i] != '.') {
                    i++;
                    continue;
                }
                int j = i;
                while (j < n && sequence[j] == '.') {
                    j++;
                }
                // Found a segment of dots from index i to j-1
                addSegment(i, j - 1);
                i = j;
            }
        }

        private void addSegment(int start, int end) {
            segments.add(new Segment(start, end));
            totalSum += (end - start);
        }

        private void removeSegment(Segment segment) {
            if (segment != null) {
                segments.remove(segment);
                totalSum -= (segment.end - segment.start);
            }
        }

        /**
         * Updates the character at a specific position and adjusts segments accordingly.
         */
        public void update(int pos, char newChar, char[] sequence) {
            // Case 1: Changing a non-dot character to a dot (Merging segments)
            if (newChar == '.' && sequence[pos] != '.') {
                int newStart = pos;
                int newEnd = pos;

                // Check if there is a segment immediately to the left
                Segment lower = segments.lower(new Segment(pos, pos));
                if (lower != null && lower.end == pos - 1) {
                    newStart = lower.start;
                    removeSegment(lower);
                }

                // Check if there is a segment immediately to the right
                Segment higher = segments.higher(new Segment(pos, pos));
                if (higher != null && higher.start == pos + 1) {
                    newEnd = higher.end;
                    removeSegment(higher);
                }

                addSegment(newStart, newEnd);
                sequence[pos] = '.';

            // Case 2: Changing a dot character to something else (Splitting a segment)
            } else if (newChar != '.' && sequence[pos] == '.') {
                Segment target = segments.floor(new Segment(pos, pos));
                if (target != null) {
                    removeSegment(target);

                    // Split the existing segment into two parts around 'pos'
                    if (target.start < pos) {
                        addSegment(target.start, pos - 1);
                    }
                    if (target.end > pos) {
                        addSegment(pos + 1, target.end);
                    }
                }
                sequence[pos] = newChar;
            }
        }

        public long getTotalSum() {
            return totalSum;
        }
    }

    /**
     * Fast I/O utility for reading input.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            return (next == null) ? 0 : Integer.parseInt(next);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Represents a sequence of characters and tracks the number of 
 * adjacent dot ('.') pairs.
 */
class DotSequence {
    private final char[] cells;
    private int adjacentDotCount;

    public DotSequence(String initialSequence) {
        this.cells = initialSequence.toCharArray();
        this.adjacentDotCount = calculateInitialDotPairs();
    }

    private int calculateInitialDotPairs() {
        int count = 0;
        for (int i = 0; i < cells.length - 1; i++) {
            if (isDot(i) && isDot(i + 1)) {
                count++;
            }
        }
        return count;
    }

    /**
     * Updates the character at a specific index and updates the adjacent dot count.
     * 
     * @param index The 0-based index to update.
     * @param newChar The new character to place at the index.
     */
    public void update(int index, char newChar) {
        if (index < 0 || index >= cells.length || cells[index] == newChar) {
            return;
        }

        // 1. Remove the contribution of the current character to the total count
        if (isDot(index)) {
            if (hasDotNeighbor(index, -1)) adjacentDotCount--;
            if (hasDotNeighbor(index, 1)) adjacentDotCount--;
        }

        // 2. Apply the change
        cells[index] = newChar;

        // 3. Add the contribution of the new character to the total count
        if (isDot(index)) {
            if (hasDotNeighbor(index, -1)) adjacentDotCount++;
            if (hasDotNeighbor(index, 1)) adjacentDotCount++;
        }
    }

    public int getAdjacentDotCount() {
        return adjacentDotCount;
    }

    private boolean isDot(int index) {
        return cells[index] == '.';
    }

    private boolean hasDotNeighbor(int index, int offset) {
        int neighborIndex = index + offset;
        return neighborIndex >= 0 && neighborIndex < cells.length && isDot(neighborIndex);
    }
}

/**
 * Utility class for fast I/O operations.
 */
class FastReader {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    public FastReader() {
        this.reader = new BufferedReader(new InputStreamReader(System.in));
    }

    public String next() {
        while (tokenizer == null || !tokenizer.hasMoreElements()) {
            try {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                throw new RuntimeException("Error reading input", e);
            }
        }
        return tokenizer.nextToken();
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }

    public char nextChar() {
        return next().charAt(0);
    }

    public void close() throws IOException {
        reader.close();
    }
}

/**
 * Main entry point for the application.
 */
public class Main {
    public static void main(String[] args) {
        FastReader sc = new FastReader();
        PrintWriter out = new PrintWriter(System.out);

        try {
            String firstToken = sc.next();
            if (firstToken == null) return;

            int n = Integer.parseInt(firstToken);
            int m = sc.nextInt();
            String initialString = sc.next();

            DotSequence sequence = new DotSequence(initialString);

            for (int i = 0; i < m; i++) {
                // Input indices are usually 1-based in competitive programming
                int index = sc.nextInt() - 1;
                char newChar = sc.nextChar();

                sequence.update(index, newChar);
                out.println(sequence.getAdjacentDotCount());
            }
        } catch (Exception e) {
