        } finally {
            out.close();
            try {
                sc.close();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Manages a 1D grid of characters (dots and hashes) and efficiently tracks
 * the number of dots and the number of contiguous dot groups.
 */
class DotGrid {
    private final boolean[] cells;
    private int totalDots;
    private int contiguousGroups;

    /**
     * Initializes the grid with an initial state string.
     * 
     * @param initialState The initial configuration of '.' and '#'
     * @param n The size of the grid
     */
    public DotGrid(String initialState, int n) {
        // We use n + 2 to implement the Sentinel Pattern.
        // Index 0 and Index n+1 will always be false (hash), 
        // allowing us to check neighbors without boundary checks.
        this.cells = new boolean[n + 2];
        this.totalDots = 0;
        this.contiguousGroups = 0;

        for (int i = 1; i <= n; i++) {
            if (initialState.charAt(i - 1) == '.') {
                cells[i] = true;
                totalDots++;
            }
        }

        // Calculate the initial number of contiguous groups
        for (int i = 1; i <= n; i++) {
            if (cells[i] && !cells[i - 1]) {
                contiguousGroups++;
            }
        }
    }

    /**
     * Updates the cell at the given index and updates the group count.
     * 
     * @param index The 1-based index of the cell to update
     * @param isDot True if the new character is '.', false if '#'
     */
    public void update(int index, boolean isDot) {
        if (cells[index] == isDot) {
            return;
        }

        // Count how many adjacent cells are currently dots
        int dotNeighbors = 0;
        if (cells[index - 1]) dotNeighbors++;
        if (cells[index + 1]) dotNeighbors++;

        if (isDot) {
            // Changing '#' -> '.'
            totalDots++;
            // If 0 neighbors: new group (+1)
            // If 1 neighbor: joins existing group (+0)
            // If 2 neighbors: merges two groups (-1)
            contiguousGroups += (1 - dotNeighbors);
        } else {
            // Changing '.' -> '#'
            totalDots--;
            // If 0 neighbors: group disappears (-1)
            // If 1 neighbor: group shortens (+0)
            // If 2 neighbors: group splits into two (+1)
            contiguousGroups -= (1 - dotNeighbors);
        }

        cells[index] = isDot;
    }

    /**
     * @return The number of dots that are not the start of a group.
     * Mathematically: Total Dots - Number of contiguous groups.
     */
    public int getResult() {
        return totalDots - contiguousGroups;
    }
}

public class Main {

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));

        String firstLine = reader.readLine();
        if (firstLine == null) return;

        StringTokenizer st = new StringTokenizer(firstLine);
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());

        String initialState = reader.readLine();
        if (initialState == null) initialState = "";

        DotGrid grid = new DotGrid(initialState, n);
        StringBuilder output = new StringBuilder();

        for (int i = 0; i < m; i++) {
            String queryLine = reader.readLine();
            if (queryLine == null) break;

            st = new StringTokenizer(queryLine);
            int index = Integer.parseInt(st.nextToken());
            char typeChar = st.nextToken().charAt(0);
            boolean targetIsDot = (typeChar == '.');

            grid.update(index, targetIsDot);
            output.append(grid.getResult()).append("\n");
        }

        System.out.print(output);
    }
}

import java.util.*;
import java.io.*;

/**
 * A program to track the number of adjacent pairs of '.' characters in a sequence
 * as individual characters are toggled.
 */
public class Replacement {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = reader.nextInt();
            int m = reader.nextInt();
            String sequence = reader.next();

            DotSequence dotSequence = new DotSequence(sequence);

            for (int i = 0; i < m; i++) {
                int index = reader.nextInt() - 1; // Convert to 0-based index
                String type = reader.next();
                boolean becomesDot = type.equals(".");

                dotSequence.update(index, becomesDot);
                out.println(dotSequence.getAdjacentDotCount());
            }
        } catch (Exception e) {
            // In a real-world production environment, use a logger
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Manages a sequence of characters and tracks the count of adjacent '.' pairs.
     */
    static class DotSequence {
        private final boolean[] isDot;
        private final int length;
        private int adjacentDotPairs;

        public DotSequence(String sequence) {
            this.length = sequence.length();
            this.isDot = new boolean[length];
            this.adjacentDotPairs = 0;

            for (int i = 0; i < length; i++) {
                isDot[i] = (sequence.charAt(i) == '.');
            }

            // Initial calculation of adjacent pairs
            for (int i = 0; i < length - 1; i++) {
                if (isDot[i] && isDot[i + 1]) {
                    adjacentDotPairs++;
                }
            }
        }

        /**
         * Updates the character at the given index and adjusts the pair count.
         * 
         * @param index The position to update.
         * @param becomesDot True if the character becomes '.', false otherwise.
         */
        public void update(int index, boolean becomesDot) {
            if (index < 0 || index >= length) return;

            boolean wasDot = isDot[index];
            if (wasDot == becomesDot) return;

            // If we add a dot, we might create new pairs.
            // If we remove a dot, we might destroy existing pairs.
            int change = becomesDot ? 1 : -1;

            // Check left neighbor
            if (index > 0 && isDot[index - 1]) {
                adjacentDotPairs += change;
            }

            // Check right neighbor
            if (index < length - 1 && isDot[index + 1]) {
                adjacentDotPairs += change;
            }

            isDot[index] = becomesDot;
        }

        public int getAdjacentDotCount() {
            return adjacentDotPairs;
        }
    }

    /**
     * Efficient reader for large input sets.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Manages a sequence of characters and tracks the number of 
 * consecutive dot ("..") occurrences efficiently.
 */
class DotSequenceManager {
    private final char[] sequence;
    private final int length;
    private int dotPairCount;

    public DotSequenceManager(String initialSequence) {
        this.sequence = initialSequence.toCharArray();
        this.length = sequence.length;
        this.dotPairCount = calculateInitialDotPairs();
    }

    /**
     * Calculates the initial count of ".." patterns in O(N).
     */
    private int calculateInitialDotPairs() {
        int count = 0;
        for (int i = 0; i < length - 1; i++) {
            if (isDotPair(i, i + 1)) {
                count++;
            }
        }
        return count;
    }

    /**
     * Updates a character at a specific position and adjusts the count in O(1).
     * 
     * @param position The 1-based position in the sequence.
     * @param newChar  The new character to place at that position.
     */
    public void update(int position, char newChar) {
        int index = position - 1;

        // Boundary check and redundancy check
        if (index < 0 || index >= length || sequence[index] == newChar) {
            return;
        }

        // 1. Remove contribution of existing pairs involving this index
        if (index > 0 && isDotPair(index - 1, index)) {
            dotPairCount--;
        }
        if (index < length - 1 && isDotPair(index, index + 1)) {
            dotPairCount--;
        }

        // 2. Apply the change
        sequence[index] = newChar;

        // 3. Add contribution of new pairs involving this index
        if (index > 0 && isDotPair(index - 1, index)) {
            dotPairCount++;
        }
        if (index < length - 1 && isDotPair(index, index + 1)) {
            dotPairCount++;
        }
    }

    private boolean isDotPair(int i, int j) {
        return sequence[i] == '.' && sequence[j] == '.';
    }

    public int getDotPairCount() {
        return dotPairCount;
    }
}

/**
 * Main application class handling I/O orchestration.
 */
public class Substituicao {

    public static void main(String[] args) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter writer = new PrintWriter(System.out)) {

            // Read first line: length of sequence and number of updates
            String firstLine = reader.readLine();
            if (firstLine == null) return;

            StringTokenizer st = new StringTokenizer(firstLine);
            int sequenceLength = Integer.parseInt(st.nextToken());
            int updateCount = Integer.parseInt(st.nextToken());

            // Read initial sequence
            String initialSequence = reader.readLine();
            if (initialSequence == null) return;

            DotSequenceManager manager = new DotSequenceManager(initialSequence);

            // Process updates
            for (int i = 0; i < updateCount; i++) {
                String updateLine = reader.readLine();
                if (updateLine == null) break;

                StringTokenizer updateSt = new StringTokenizer(updateLine);
