/**
 * A refactored solution to track the number of adjacent dot ('.') pairs in a sequence.
 * 
 * Design Principles:
 * 1. Separation of Concerns: Logic is separated from I/O.
 * 2. Encapsulation: State is managed within DotSequenceManager.
 * 3. Maintainability: The update logic uses a "delta" approach, which is far 
 *    simpler to read and debug than complex conditional branching.
 * 4. Performance: Uses Fast I/O and O(1) updates.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            String nStr = reader.next();
            if (nStr == null) return;

            int n = Integer.parseInt(nStr);
            int m = reader.nextInt();
            String initialString = reader.next();

            if (initialString == null) return;
            DotSequenceManager manager = new DotSequenceManager(initialString);

            for (int i = 0; i < m; i++) {
                int index = reader.nextInt() - 1; // Convert 1-based input to 0-based index
                String charStr = reader.next();
                if (charStr == null) break;
                char newChar = charStr.charAt(0);

                manager.update(index, newChar);
                writer.println(manager.getAdjacentDotPairs());
            }
        } catch (Exception e) {
            // In a production environment, use a proper logging framework.
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Manages the state of the character sequence and maintains the 
     * count of adjacent dot ('.') pairs incrementally.
     */
    static class DotSequenceManager {
        private static final char DOT = '.';
        private final char[] sequence;
        private long adjacentDotPairs;

        public DotSequenceManager(String initialString) {
            this.sequence = initialString.toCharArray();
            this.adjacentDotPairs = calculateInitialPairs();
        }

        /**
         * Computes the initial count of adjacent dot pairs in O(n).
         */
        private long calculateInitialPairs() {
            long count = 0;
            for (int i = 0; i < sequence.length - 1; i++) {
                if (sequence[i] == DOT && sequence[i + 1] == DOT) {
                    count++;
                }
            }
            return count;
        }

        /**
         * Updates the character at the given index and recalculates the pair count.
         * This is performed in O(1) by only checking the immediate neighbors 
         * of the changed index.
         * 
         * @param idx The 0-based index to modify.
         * @param newChar The character to set at the index.
         */
        public void update(int idx, char newChar) {
            // Boundary check and no-op check (if character is already the same)
            if (idx < 0 || idx >= sequence.length || sequence[idx] == newChar) {
                return;
            }

            // Step 1: Remove the contribution of the current character to the pair count.
            // If the character being replaced is a dot, it might have been part of a pair.
            if (sequence[idx] == DOT) {
                if (idx > 0 && sequence[idx - 1] == DOT) {
                    adjacentDotPairs--;
                }
                if (idx < sequence.length - 1 && sequence[idx + 1] == DOT) {
                    adjacentDotPairs--;
                }
            }

            // Step 2: Apply the character change.
            sequence[idx] = newChar;

            // Step 3: Add the contribution of the new character to the pair count.
            // If the new character is a dot, it might create new pairs with neighbors.
            if (sequence[idx] == DOT) {
                if (idx > 0 && sequence[idx - 1] == DOT) {
                    adjacentDotPairs++;
                }
                if (idx < sequence.length - 1 && sequence[idx + 1] == DOT) {
                    adjacentDotPairs++;
                }
            }
        }

        /**
         * @return The current number of adjacent pairs of dots.
         */
        public long getAdjacentDotPairs() {
            return adjacentDotPairs;
        }
    }

    /**
     * A high-performance reader for processing large input streams.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            return next != null ? Integer.parseInt(next) : 0;
        }
    }
}

