/**
 * A refactored solution to track the number of continuous segments of '.' characters.
 * The program allows for real-time character updates and provides the current segment count.
 */
public class Replacement_CF570C {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            // Read initial dimensions
            int stringLength = reader.nextInt();
            int queryCount = reader.nextInt();

            // Read initial grid state
            char[] grid = reader.next().toCharArray();

            // Initialize the counter logic
            SegmentCounter segmentCounter = new SegmentCounter(grid);

            // Process queries
            for (int i = 0; i < queryCount; i++) {
                int targetIndex = reader.nextInt() - 1; // Convert 1-based input to 0-based
                char newChar = reader.next().charAt(0);

                segmentCounter.update(targetIndex, newChar);
                out.println(segmentCounter.getCount());
            }
        } catch (IOException e) {
            System.err.println("Error processing input: " + e.getMessage());
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Manages the state of the character grid and maintains the count of '.' segments.
     */
    static class SegmentCounter {
        private final char[] grid;
        private final int n;
        private int currentSegmentCount;

        public SegmentCounter(char[] grid) {
            this.grid = grid;
            this.n = grid.length;
            this.currentSegmentCount = initializeCount();
        }

        /**
         * Calculates the initial number of dot segments.
         */
        private int initializeCount() {
            int count = 0;
            for (int i = 0; i < n; i++) {
                if (isSegmentStart(i)) {
                    count++;
                }
            }
            return count;
        }

        /**
         * A segment starts at index i if grid[i] is '.' AND 
         * (it is the first element OR the previous element is 'X').
         */
        private boolean isSegmentStart(int i) {
            if (i < 0 || i >= n) {
                return false;
            }
            return grid[i] == '.' && (i == 0 || grid[i - 1] == 'X');
        }

        /**
         * Updates the character at a specific index and incrementally updates the count.
         * 
         * @param index The index to update.
         * @param newChar The new character to place at the index.
         * @timeComplexity O(1)
         */
        public void update(int index, char newChar) {
            if (index < 0 || index >= n || grid[index] == newChar) {
                return;
            }

            // Changing grid[index] can only affect the "segment start" status 
            // of index itself and the index immediately following it.

            // 1. Remove the current contribution of affected indices
            if (isSegmentStart(index)) {
                currentSegmentCount--;
            }
            if (isSegmentStart(index + 1)) {
                currentSegmentCount--;
            }

            // 2. Apply the change
            grid[index] = newChar;

            // 3. Add the new contribution of affected indices
            if (isSegmentStart(index)) {
                currentSegmentCount++;
            }
            if (isSegmentStart(index + 1)) {
                currentSegmentCount++;
            }
        }

        public int getCount() {
            return currentSegmentCount;
        }
    }

    /**
     * A fast utility class for reading input from an InputStream.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) {
                    return null;
                }
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }
