/**
 * Refactored solution for tracking adjacent dot pairs in a string during character replacements.
 */
public class ReplacementTracker {

    public static void main(String[] args) {
        FastReader reader = new FastReader();

        try {
            int stringLength = reader.nextInt();
            int queryCount = reader.nextInt();
            String initialContent = reader.nextLine();

            // Initialize the tracker with the starting string
            DotPairTracker tracker = new DotPairTracker(initialContent);

            StringBuilder output = new StringBuilder();
            for (int i = 0; i < queryCount; i++) {
                int index = reader.nextInt();
                char newChar = reader.nextString().charAt(0);

                // Update the tracker and get the new count of adjacent dot pairs
                int currentCount = tracker.update(index, newChar);
                output.append(currentCount).append("\n");
            }

            System.out.print(output.toString());
        } catch (Exception e) {
            // In a production environment, use a proper logging framework
            System.err.println("Error processing input: " + e.getMessage());
        }
    }

    /**
     * Manages a grid of characters and maintains a running count of adjacent '.' pairs.
     */
    public static class DotPairTracker {
        private final char[] grid;
        private int adjacentDotPairsCount;

        /**
         * Initializes the tracker with padding to prevent index out of bounds.
         * @param content The initial string content.
         */
        public DotPairTracker(String content) {
            // Add '#' sentinels at start and end to simplify boundary checks
            this.grid = ("#" + content + "#").toCharArray();
            this.adjacentDotPairsCount = calculateInitialPairs();
        }

        private int calculateInitialPairs() {
            int count = 0;
            // Iterate through the actual content (skipping sentinels)
            for (int i = 1; i < grid.length - 1; i++) {
                if (grid[i] == '.' && grid[i - 1] == '.') {
                    count++;
                }
            }
            return count;
        }

        /**
         * Updates a character at a specific index and adjusts the pair count.
         * @param index The 1-based index of the character to change.
         * @param newChar The new character to place at the index.
         * @return The updated number of adjacent dot pairs.
         */
        public int update(int index, char newChar) {
            // Boundary check for the padded array
            if (index <= 0 || index >= grid.length - 1) {
                return adjacentDotPairsCount;
            }

            char oldChar = grid[index];
            if (oldChar == newChar) {
                return adjacentDotPairsCount;
            }

            if (oldChar == '.' && newChar != '.') {
                // Removing a dot: lose pairs with any existing dot neighbors
                adjacentDotPairsCount -= countDotNeighbors(index);
            } else if (oldChar != '.' && newChar == '.') {
                // Adding a dot: gain pairs with any existing dot neighbors
                adjacentDotPairsCount += countDotNeighbors(index);
            }

            grid[index] = newChar;
            return adjacentDotPairsCount;
        }

        private int countDotNeighbors(int index) {
            int dots = 0;
            if (grid[index - 1] == '.') dots++;
            if (grid[index + 1] == '.') dots++;
            return dots;
        }
    }

    /**
     * High-performance reader for large input datasets.
     */
    public static class FastReader {
        private final byte[] buffer = new byte[1024];
        private int cursor;
        private int bytesRead;

        public int read() {
            if (bytesRead == -1) return -1;
            if (cursor >= bytesRead) {
                cursor = 0;
                try {
                    bytesRead = System.in.read(buffer);
                } catch (IOException e) {
                    return -1;
                }
                if (bytesRead <= 0) return -1;
            }
            return buffer[cursor++] & 0xFF;
        }

        public String nextLine() {
            int c = read();
            while (c != -1 && isSpaceChar(c)) c = read();
            StringBuilder sb = new StringBuilder();
            while (c != -1 && !isEndOfLine(c)) {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        public String nextString() {
            int c = read();
            while (c != -1 && isSpaceChar(c)) c = read();
            if (c == -1) return "";
            StringBuilder sb = new StringBuilder();
            while (c != -1 && !isSpaceChar(c)) {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        public int nextInt() {
            int c = read();
            while (c != -1 && isSpaceChar(c)) c = read();
            if (c == -1) throw new InputMismatchException();

            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }

            int res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res = res * 10 + (c - '0');
                c = read();
            } while (c != -1 && !isSpaceChar(c));

            return res * sgn;
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        private boolean isEndOfLine(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }
    }
}

