 */
public class Main {
    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        ProblemSolver solver = new ProblemSolver();
        solver.solve(reader, writer);

        writer.flush();
        writer.close();
    }

    /**
     * ProblemSolver encapsulates the core logic of the task.
     */
    static class ProblemSolver {
        private static final char DOT = '.';

        private char[] sequence;
        private int sequenceLength;
        private int adjacentDotPairs;

        /**
         * Orchestrates the solving process.
         * 
         * @param in  The reader for input.
         * @param out The writer for output.
         */
        public void solve(FastReader in, PrintWriter out) {
            this.sequenceLength = in.nextInt();
            int queryCount = in.nextInt();
            this.sequence = in.next().toCharArray();

            initializeAdjacentPairs();

            for (int i = 0; i < queryCount; i++) {
                int index = in.nextInt() - 1; // Convert to 0-indexed
                char newChar = in.next().charAt(0);

                updateSequence(index, newChar);
                out.println(adjacentDotPairs);
            }
        }

        /**
         * Calculates the initial number of adjacent dot pairs.
         */
        private void initializeAdjacentPairs() {
            adjacentDotPairs = 0;
            for (int i = 0; i < sequenceLength - 1; i++) {
                if (isDotPair(i, i + 1)) {
                    adjacentDotPairs++;
                }
            }
        }

        /**
         * Updates the character at the given index and adjusts the count 
         * of adjacent dot pairs accordingly.
         * 
         * @param index   The position in the sequence to update.
         * @param newChar The new character to place at the index.
         */
        private void updateSequence(int index, char newChar) {
            if (index < 0 || index >= sequenceLength || sequence[index] == newChar) {
                return;
            }

            // 1. Remove current contributions of the index and its neighbors
            adjacentDotPairs -= countContributionsAt(index);

            // 2. Apply the change
            sequence[index] = newChar;

            // 3. Add the new contributions
            adjacentDotPairs += countContributionsAt(index);
        }

        /**
         * Calculates how many dot-dot pairs the current index is part of.
         * 
         * @param idx The index to check.
         * @return The number of adjacent dot pairs (0, 1, or 2).
         */
        private int countContributionsAt(int idx) {
            int contributions = 0;
            // Check pair with left neighbor
            if (idx > 0 && isDotPair(idx - 1, idx)) {
                contributions++;
            }
            // Check pair with right neighbor
            if (idx < sequenceLength - 1 && isDotPair(idx, idx + 1)) {
                contributions++;
            }
            return contributions;
        }

        private boolean isDotPair(int i, int j) {
            return sequence[i] == DOT && sequence[j] == DOT;
        }
    }

    /**
     * FastReader provides an efficient way to read input from an InputStream.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
