/**
 * Tracks the number of adjacent dot ('.') pairs in a character array
 * and provides efficient updates when characters are changed.
 */
class DotPairTracker {
    private final char[] characters;
    private int dotPairCount;

    /**
     * Initializes the tracker with a string and calculates the initial dot pair count.
     * @param initialString The starting string.
     */
    public DotPairTracker(String initialString) {
        this.characters = initialString.toCharArray();
        this.dotPairCount = calculateInitialDotPairs();
    }

    private int calculateInitialDotPairs() {
        int count = 0;
        for (int i = 0; i < characters.length - 1; i++) {
            if (isDot(i) && isDot(i + 1)) {
                count++;
            }
        }
        return count;
    }

    /**
     * Updates a character at a specific index and returns the new dot pair count.
     * @param index The 0-based index to update.
     * @param newChar The new character to place at the index.
     * @return The updated count of adjacent dot pairs.
     */
    public int update(int index, char newChar) {
        char oldChar = characters[index];

        // If the character is not actually changing, return current count immediately
        if (oldChar == newChar) {
            return dotPairCount;
        }

        // Case 1: We are removing a dot
        if (oldChar == '.') {
            if (hasDotNeighbor(index, -1)) dotPairCount--;
            if (hasDotNeighbor(index, 1)) dotPairCount--;
        } 
        // Case 2: We are adding a dot
        else if (newChar == '.') {
            if (hasDotNeighbor(index, -1)) dotPairCount++;
            if (hasDotNeighbor(index, 1)) dotPairCount++;
        }

        characters[index] = newChar;
        return dotPairCount;
    }

    private boolean isDot(int index) {
        return characters[index] == '.';
    }

    private boolean hasDotNeighbor(int index, int offset) {
        int neighborIndex = index + offset;
        return neighborIndex >= 0 && neighborIndex < characters.length && isDot(neighborIndex);
    }
}

