    /**
     * Reads the input and processes queries to update the character sequence.
     * 
     * @param in   The FastReader for efficient input.
     * @param out  The PrintWriter for efficient output.
     * @throws IOException If an I/O error occurs.
     */
    public void solve(FastReader in, PrintWriter out) throws IOException {
        int length = in.nextInt();
        int queryCount = in.nextInt();
        char[] sequence = in.next().toCharArray();

        int dotPairCount = countInitialDotPairs(sequence);

        for (int i = 0; i < queryCount; i++) {
            int index = in.nextInt() - 1; // Convert 1-based index to 0-based
            char newChar = in.next().charAt(0);

            dotPairCount = updateSequenceAndCount(sequence, index, newChar, dotPairCount);
            out.println(dotPairCount);
        }
    }

    /**
     * Performs the initial count of consecutive '.' pairs.
     */
    private int countInitialDotPairs(char[] sequence) {
        int count = 0;
        for (int i = 0; i < sequence.length - 1; i++) {
            if (sequence[i] == DOT && sequence[i + 1] == DOT) {
                count++;
            }
        }
        return count;
    }

    /**
     * Updates the sequence at a specific index and adjusts the dot pair count accordingly.
     * 
     * @param sequence      The current character array.
     * @param index         The position to change.
     * @param newChar       The character to place at the index.
     * @param currentCount  The current number of dot pairs.
     * @return The updated dot pair count.
     */
    private int updateSequenceAndCount(char[] sequence, int index, char newChar, int currentCount) {
        char oldChar = sequence[index];

        // If the character is not actually changing, return the current count
        if (oldChar == newChar) {
            return currentCount;
        }

        // 1. Remove influence of the old character on dot pairs
        if (oldChar == DOT) {
            if (isDot(sequence, index - 1)) currentCount--;
            if (isDot(sequence, index + 1)) currentCount--;
        }

        // 2. Update the sequence
        sequence[index] = newChar;

        // 3. Add influence of the new character on dot pairs
        if (newChar == DOT) {
            if (isDot(sequence, index - 1)) currentCount++;
            if (isDot(sequence, index + 1)) currentCount++;
        }

        return currentCount;
    }

    /**
     * Helper to check if a character at a given index is a dot, while handling bounds.
     */
    private boolean isDot(char[] sequence, int index) {
        return index >= 0 && index < sequence.length && sequence[index] == DOT;
    }
}

