 * adjacent '.' (dot) pairs during updates.
 */
public class DotPairManager {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int n = reader.nextInt();
            int m = reader.nextInt();
            char[] initialChars = reader.next().toCharArray();

            DotSequence dotSequence = new DotSequence(initialChars);

            for (int i = 0; i < m; i++) {
                int index = reader.nextInt() - 1; // Convert 1-based to 0-based index
                char newChar = reader.next().charAt(0);

                dotSequence.update(index, newChar);
                writer.println(dotSequence.getAdjacentDotPairs());
            }
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Manages a character sequence and maintains a running count of 
     * adjacent '.' pairs.
     */
    static class DotSequence {
        private final char[] sequence;
        private int adjacentDotPairs;

        public DotSequence(char[] initialSequence) {
            this.sequence = initialSequence;
            this.adjacentDotPairs = countInitialPairs(initialSequence);
        }

        /**
         * Updates the character at the specified index and adjusts 
         * the adjacent dot pair count accordingly.
         * 
         * @param index The index to update.
         * @param newChar The new character to place at the index.
         */
        public void update(int index, char newChar) {
            if (index < 0 || index >= sequence.length || sequence[index] == newChar) {
                return;
            }

            if (sequence[index] == '.') {
                // We are removing a dot
                if (isDot(index - 1)) adjacentDotPairs--;
                if (isDot(index + 1)) adjacentDotPairs--;
            } else {
                // We are adding a dot
                if (isDot(index - 1)) adjacentDotPairs++;
                if (isDot(index + 1)) adjacentDotPairs++;
            }

            sequence[index] = newChar;
        }

        public int getAdjacentDotPairs() {
            return adjacentDotPairs;
        }

        private boolean isDot(int index) {
            return index >= 0 && index < sequence.length && sequence[index] == '.';
        }

        private int countInitialPairs(char[] seq) {
            int count = 0;
            for (int i = 0; i < seq.length - 1; i++) {
                if (seq[i] == '.' && seq[i + 1] == '.') {
                    count++;
                }
            }
            return count;
        }
    }

