/**
 * Encapsulates the grid state and the logic for tracking adjacent dot pairs.
 */
class GridManager {
    private final char[] grid;
    private final int size;
    private long adjacentDotPairs;

    public GridManager(char[] initialGrid) {
        this.grid = initialGrid;
        this.size = initialGrid.length;
        this.adjacentDotPairs = calculateInitialPairs();
    }

    /**
     * Calculates the initial number of pairs of adjacent dots.
     */
    private long calculateInitialPairs() {
        long count = 0;
        for (int i = 0; i < size - 1; i++) {
            if (grid[i] == '.' && grid[i + 1] == '.') {
                count++;
            }
        }
        return count;
    }

    /**
     * Updates a cell in the grid and adjusts the adjacent dot pair count.
     * 
     * @param index The 0-based index to update.
     * @param newChar The character to place at the index.
     */
    public void updateCell(int index, char newChar) {
        if (index < 0 || index >= size || grid[index] == newChar) {
            return;
        }

        char oldChar = grid[index];

        // Logic: If we are adding a dot, check if neighbors are dots to increase count.
        // If we are removing a dot, check if neighbors were dots to decrease count.
        if (oldChar != '.' && newChar == '.') {
            if (hasDotNeighbor(index)) {
                adjacentDotPairs += countDotNeighbors(index);
            }
        } else if (oldChar == '.' && newChar != '.') {
            if (hasDotNeighbor(index)) {
                adjacentDotPairs -= countDotNeighbors(index);
            }
        }

        grid[index] = newChar;
    }

    private boolean hasDotNeighbor(int index) {
        return (index > 0 && grid[index - 1] == '.') || 
               (index < size - 1 && grid[index + 1] == '.');
    }

    private int countDotNeighbors(int index) {
        int neighbors = 0;
        if (index > 0 && grid[index - 1] == '.') neighbors++;
        if (index < size - 1 && grid[index + 1] == '.') neighbors++;
        return neighbors;
    }

    public long getAdjacentDotPairs() {
        return adjacentDotPairs;
    }
}

