/**
 * Manages a grid of characters and tracks the number of adjacent '.' pairs.
 */
class DotPairManager {
    private final char[] grid;
    private int dotPairCount;

    public DotPairManager(char[] initialGrid) {
        this.grid = initialGrid;
        this.dotPairCount = calculateInitialDotPairs();
    }

    /**
     * Calculates the initial count of adjacent '.' characters.
     */
    private int calculateInitialDotPairs() {
        int count = 0;
        for (int i = 0; i < grid.length - 1; i++) {
            if (isDotPair(i, i + 1)) {
                count++;
            }
        }
        return count;
    }

    /**
     * Updates a cell at a specific index and updates the pair count accordingly.
     * 
     * @param index The zero-based index of the cell to update.
     * @param newChar The new character to place in the cell.
     */
    public void updateCell(int index, char newChar) {
        // If the character is the same, no state changes occur.
        if (grid[index] == newChar) {
            return;
        }

        // 1. Subtract existing pairs involving this index before changing the character
        if (isDotPair(index - 1, index)) {
            dotPairCount--;
        }
        if (isDotPair(index, index + 1)) {
            dotPairCount--;
        }

        // 2. Perform the update
        grid[index] = newChar;

        // 3. Add new pairs involving this index after the change
        if (isDotPair(index - 1, index)) {
            dotPairCount++;
        }
        if (isDotPair(index, index + 1)) {
            dotPairCount++;
        }
    }

    /**
     * Helper to check if two indices form a pair of dots.
     */
    private boolean isDotPair(int i, int j) {
        if (i < 0 || j >= grid.length) {
            return false;
        }
        return grid[i] == '.' && grid[j] == '.';
    }

    public int getDotPairCount() {
        return dotPairCount;
    }
}

