import java.io.BufferedReader;
import java.io.IOException;
import java.io.PrintWriter;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * A program to track the number of consecutive dot pairs ("..") in a string
 * as characters are updated at specific indices.
 */
public class Solution {

    public static void main(String[] args) {
        DotPairTracker tracker = new DotPairTracker();
        tracker.solve();
    }

    /**
     * Handles the core logic of the problem.
     */
    static class DotPairTracker {
        private FastReader reader;
        private PrintWriter writer;

        public void solve() {
            reader = new FastReader();
            writer = new PrintWriter(System.out);

            try {
                int n = reader.nextInt();
                int m = reader.nextInt();
                String initialString = reader.next();

                // We use a padded array to avoid boundary checks (index 0 and n+1 are 'a')
                char[] grid = new char[n + 2];
                grid[0] = 'a';
                grid[n + 1] = 'a';

                for (int i = 0; i < n; i++) {
                    grid[i + 1] = initialString.charAt(i);
                }

                // Calculate initial count of consecutive dot pairs
                int consecutiveDotPairs = 0;
                for (int i = 1; i < n; i++) {
                    if (grid[i] == '.' && grid[i + 1] == '.') {
                        consecutiveDotPairs++;
                    }
                }

                // Process updates
                for (int i = 0; i < m; i++) {
                    int targetIndex = reader.nextInt();
                    char newChar = reader.next().charAt(0);

                    consecutiveDotPairs = updateGridAndGetNewCount(grid, targetIndex, newChar, consecutiveDotPairs);
                    writer.println(consecutiveDotPairs);
                }
            } catch (Exception e) {
                // In competitive programming, we typically allow the exception to propagate 
                // or handle it silently depending on requirements.
            } finally {
                writer.flush();
                writer.close();
            }
        }

        /**
         * Updates the grid at the specified index and recalculates the count of dot pairs.
         * 
         * @param grid The current character array.
         * @param index The 1-based index to update.
         * @param newChar The new character to place at the index.
         * @param currentCount The current number of consecutive dot pairs.
         * @return The updated count of consecutive dot pairs.
         */
        private int updateGridAndGetNewCount(char[] grid, int index, char newChar, int currentCount) {
            // 1. Calculate how many dot pairs involve this index before the change
            int pairsBefore = countDotPairsAt(grid, index);

            // 2. Apply the change
            grid[index] = newChar;

            // 3. Calculate how many dot pairs involve this index after the change
            int pairsAfter = countDotPairsAt(grid, index);

            // 4. The new count is the old count minus what we lost, plus what we gained
            return currentCount - pairsBefore + pairsAfter;
        }

        /**
         * Counts the number of ".." pairs that include the character at the given index.
         * This only checks the immediate neighbors.
         */
        private int countDotPairsAt(char[] grid, int index) {
            int count = 0;
            // Check pair (index-1, index)
            if (index > 0 && index < grid.length && grid[index - 1] == '.' && grid[index] == '.') {
                count++;
            }
            // Check pair (index, index+1)
            if (index < grid.length - 1 && grid[index] == '.' && grid[index + 1] == '.') {
                count++;
            }
            return count;
        }
    }

    /**
     * High-performance input reader.
     */
    static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }
    }
}

