/**
 * A solution to maintain the count of adjacent empty space ('.') pairs 
 * in a field during point updates.
 */
public class Solution {

    public static void main(String[] args) {
        FastReader sc = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        // Read N (length of field) and M (number of queries)
        int n = sc.nextInt();
        int m = sc.nextInt();

        if (n <= 0) {
            out.close();
            return;
        }

        // Read the initial field configuration
        String initialConfig = sc.next();

        // field array is size n+2 to allow for padding at index 0 and n+1.
        // This avoids index out of bounds errors when checking neighbors of index 1 or n.
        char[] field = new char[n + 2];
        field[0] = 'A'; // Padding character (non-dot)
        field[n + 1] = 'A'; // Padding character (non-dot)

        for (int i = 1; i <= n; i++) {
            field[i] = initialConfig.charAt(i - 1);
        }

        // Step 1: Calculate initial number of adjacent '.' pairs
        // A pair is defined as field[i] == '.' and field[i+1] == '.'
        long adjacentDotPairs = 0;
        for (int i = 1; i < n; i++) {
            if (field[i] == '.' && field[i + 1] == '.') {
                adjacentDotPairs++;
            }
        }

        // Step 2: Process M queries
        for (int i = 0; i < m; i++) {
            int x = sc.nextInt();
            char newChar = sc.next().charAt(0);

            // We only care about changes that toggle between '.' and a non-dot character.
            // Changing from one non-dot character to another does not affect the dot-pair count.
            if (field[x] == '.' && newChar != '.') {
                // Transition: Dot -> Non-Dot
                // We lose pairs formed with the left neighbor and the right neighbor
                if (field[x - 1] == '.') {
                    adjacentDotPairs--;
                }
                if (field[x + 1] == '.') {
                    adjacentDotPairs--;
                }
                field[x] = newChar;
            } else if (field[x] != '.' && newChar == '.') {
                // Transition: Non-Dot -> Dot
                // We gain pairs formed with the left neighbor and the right neighbor
                if (field[x - 1] == '.') {
                    adjacentDotPairs++;
                }
                if (field[x + 1] == '.') {
                    adjacentDotPairs++;
                }
                field[x] = '.';
            } else {
                // Transition: Dot -> Dot OR Non-Dot -> Different Non-Dot
                // The pair count remains the same, but we update the field character
                field[x] = newChar;
            }

            out.println(adjacentDotPairs);
        }

        out.flush();
        out.close();
    }

    /**
     * Fast I/O utility class for efficient reading.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

