        } finally {
            out.close();
        }
    }

    /**
     * Manages a sequence of characters and maintains the count of adjacent '.' pairs.
     */
    static class DotSequence {
        private final char[] elements;
        private int adjacentDotCount;

        public DotSequence(String initialString) {
            this.elements = initialString.toCharArray();
            this.adjacentDotCount = calculateInitialAdjacentDots();
        }

        /**
         * Calculates the initial number of adjacent dot pairs in O(N).
         */
        private int calculateInitialAdjacentDots() {
            int count = 0;
            for (int i = 0; i < elements.length - 1; i++) {
                if (elements[i] == '.' && elements[i + 1] == '.') {
                    count++;
                }
            }
            return count;
        }

        /**
         * Updates the character at a specific index and adjusts the score incrementally.
         * Complexity: O(1)
         * 
         * @param index The index to update.
         * @param newChar The new character to place at the index.
         */
        public void update(int index, char newChar) {
            if (index < 0 || index >= elements.length || elements[index] == newChar) {
                return;
            }

            // 1. Subtract the contribution of the current element to the score
            adjacentDotCount -= countContributionsAt(index);

            // 2. Apply the change
            elements[index] = newChar;

            // 3. Add the new contribution of the element to the score
            adjacentDotCount += countContributionsAt(index);
        }

        /**
         * Counts how many adjacent dot-dot pairs the element at the given index belongs to.
         */
        private int countContributionsAt(int index) {
            int contributions = 0;
            // Check pair with left neighbor
            if (index > 0 && elements[index] == '.' && elements[index - 1] == '.') {
                contributions++;
            }
            // Check pair with right neighbor
            if (index < elements.length - 1 && elements[index] == '.' && elements[index + 1] == '.') {
                contributions++;
            }
            return contributions;
        }

        public int getAdjacentDotCount() {
            return adjacentDotCount;
        }
    }

