    /**
     * Manages the state of the character grid and maintains the count 
     * of consecutive dot pairs.
     */
    static class DotGridManager {
        private static final char DOT_CHAR = '.';
        private final char[] grid;
        private int consecutiveDotPairs;

        public DotGridManager(String initialString) {
            this.grid = initialString.toCharArray();
            this.consecutiveDotPairs = calculateInitialDotPairs();
        }

        /**
         * Calculates the initial number of consecutive dot pairs.
         */
        private int calculateInitialDotPairs() {
            int count = 0;
            for (int i = 1; i < grid.length; i++) {
                if (isDot(i) && isDot(i - 1)) {
                    count++;
                }
            }
            return count;
        }

        /**
         * Updates a cell in the grid and returns the updated count of dot pairs.
         * 
         * @param index The index of the cell to update.
         * @param newChar The new character to place in the cell.
         * @return The updated count of consecutive dot pairs.
         */
        public int updateCell(int index, char newChar) {
            if (index < 0 || index >= grid.length || grid[index] == newChar) {
                return consecutiveDotPairs;
            }

            if (newChar == DOT_CHAR) {
                // Transitioning from a non-dot to a dot: potential to increase pairs
                handleDotAddition(index);
            } else if (grid[index] == DOT_CHAR) {
                // Transitioning from a dot to a non-dot: potential to decrease pairs
                handleDotRemoval(index);
            }

            grid[index] = newChar;
            return consecutiveDotPairs;
        }

        private void handleDotAddition(int index) {
            if (isDot(index - 1)) {
                consecutiveDotPairs++;
            }
            if (isDot(index + 1)) {
                consecutiveDotPairs++;
            }
        }

        private void handleDotRemoval(int index) {
            if (isDot(index - 1)) {
                consecutiveDotPairs--;
            }
            if (isDot(index + 1)) {
                consecutiveDotPairs--;
            }
        }

        private boolean isDot(int index) {
            return index >= 0 && index < grid.length && grid[index] == DOT_CHAR;
        }
    }

