    /**
     * Manages the character sequence and tracks the 'total' score.
     * The score is defined as the number of adjacent pairs of dots ('.').
     */
    static class SequenceManager {
        private final char[] sequence;
        private final int n;
        private int total;

        public SequenceManager(String initialString) {
            this.n = initialString.length();
            this.sequence = initialString.toCharArray();
            this.total = calculateInitialTotal();
        }

        /**
         * Calculates the initial number of adjacent '.' pairs.
         */
        private int calculateInitialTotal() {
            int count = 0;
            for (int i = 0; i < n - 1; i++) {
                if (sequence[i] == '.' && sequence[i + 1] == '.') {
                    count++;
                }
            }
            return count;
        }

        /**
         * Updates the character at the specified index and adjusts the total score.
         *
         * @param index    The index to update.
         * @param newChar  The new character to place at the index.
         */
        public void update(int index, char newChar) {
            if (index < 0 || index >= n || sequence[index] == newChar) {
                return;
            }

            boolean wasDot = (sequence[index] == '.');
            boolean isDot = (newChar == '.');

            // If the change involves a dot, we check its neighbors to update the pair count.
            if (wasDot && !isDot) {
                // Changing '.' to something else: we lose pairs with neighbors
                if (index > 0 && sequence[index - 1] == '.') {
                    total--;
                }
                if (index < n - 1 && sequence[index + 1] == '.') {
                    total--;
                }
            } else if (!wasDot && isDot) {
                // Changing something else to '.': we gain pairs with neighbors
                if (index > 0 && sequence[index - 1] == '.') {
                    total++;
                }
                if (index < n - 1 && sequence[index + 1] == '.') {
                    total++;
                }
            }

            sequence[index] = newChar;
        }

