    static class DotPairManager {
        private final char[] cells;
        private int dotPairCount;

        /**
         * Initializes the manager with the starting string.
         * Uses 1-based indexing internally to match problem requirements.
         *
         * @param initialString The starting sequence of characters.
         */
        public DotPairManager(String initialString) {
            // We use length + 2 to provide padding at index 0 and index N+1.
            // This prevents OutOfBounds exceptions when checking neighbors.
            this.cells = new char[initialString.length() + 2];
            this.dotPairCount = 0;

            for (int i = 0; i < initialString.length(); i++) {
                this.cells[i + 1] = initialString.charAt(i);
            }

            calculateInitialPairs();
        }

        private void calculateInitialPairs() {
            for (int i = 1; i < cells.length - 1; i++) {
                if (isDotPair(i, i + 1)) {
                    dotPairCount++;
                }
