         *
         * @param position The 1-based index to update.
         * @param newChar  The new character to place at the position.
         */
        public void updatePosition(int position, char newChar) {
            char oldChar = cells[position];

            if (oldChar == newChar) {
                return;
            }

            // If we are removing a dot, decrement pairs if neighbors are dots
            if (oldChar == '.') {
                if (isDot(position - 1)) dotPairCount--;
                if (isDot(position + 1)) dotPairCount--;
            } 
            // If we are adding a dot, increment pairs if neighbors are dots
            else if (newChar == '.') {
                if (isDot(position - 1)) dotPairCount++;
                if (isDot(position + 1)) dotPairCount++;
            }

            cells[position] = newChar;
        }

