    /**
     * Manages the state of the character sequence and tracks the count of adjacent '.' pairs.
     */
    static class DotPairManager {
        private final char[] cells;
        private long pairCount;

        /**
         * Initializes the manager with a sequence. 
         * Padding is added to boundaries to simplify neighbor checks.
         */
        public DotPairManager(String initialSequence) {
            int n = initialSequence.length();
            // Padding with '!' at index 0 and n+1 ensures we never check out of bounds
            // and that boundary characters never form a pair with dots.
            this.cells = new char[n + 2];
            this.cells[0] = '!';
            this.cells[n + 1] = '!';
            for (int i = 0; i < n; i++) {
                this.cells[i + 1] = initialSequence.charAt(i);
            }
            this.pairCount = calculateInitialPairs();
        }

        /**
         * Calculates the initial number of adjacent '.' pairs in O(n).
         */
        private long calculateInitialPairs() {
            long count = 0;
            for (int i = 1; i < cells.length - 1; i++) {
                if (cells[i] == '.' && cells[i + 1] == '.') {
                    count++;
                }
            }
            return count;
        }

        /**
         * Updates the character at the given 1-based index and updates the pair count.
         *
         * @param position The 1-based index in the original sequence.
         * @param newChar  The new character to place at that position.
         */
        public void update(int position, char newChar) {
            // Adjust 1-based index to internal array index
            int idx = position;

            if (idx <= 0 || idx >= cells.length - 1 || cells[idx] == newChar) {
                return;
            }

            // 1. Remove existing pairs involving this index
            if (cells[idx - 1] == '.' && cells[idx] == '.') {
                pairCount--;
            }
            if (cells[idx] == '.' && cells[idx + 1] == '.') {
                pairCount--;
            }

            // 2. Apply the change
            cells[idx] = newChar;

            // 3. Add new pairs created by this change
            if (cells[idx - 1] == '.' && cells[idx] == '.') {
                pairCount++;
            }
            if (cells[idx] == '.' && cells[idx + 1] == '.') {
                pairCount++;
            }
        }

        public long getPairCount() {
            return pairCount;
        }
    }

