     * Following the original logic: 
     * - A dot can be changed to a non-dot.
     * - A non-dot can be changed to a dot.
     * - Other changes (dot to dot, or non-dot to non-dot) are ignored.
     * 
     * @param index The 0-based index to update.
     * @param newChar The new character to place at the index.
     * @return The updated total count of dot-pair sequences.
     */
    public int update(int index, char newChar) {
        char oldChar = sequence.charAt(index);

        boolean canChangeToDot = (newChar == DOT && oldChar != DOT);
        boolean canChangeFromDot = (newChar != DOT && oldChar == DOT);

        // If the update does not meet the criteria for a state change, return current count
        if (!canChangeToDot && !canChangeFromDot) {
            return dotPairCount;
        }

        int delta = 0;

        // If we are removing a dot, we potentially lose pairs with neighbors
        if (oldChar == DOT) {
            if (isDot(index - 1)) delta--;
            if (isDot(index + 1)) delta--;
        }

        // If we are adding a dot, we potentially gain pairs with neighbors
        if (newChar == DOT) {
            if (isDot(index - 1)) delta++;
            if (isDot(index + 1)) delta++;
        }

        sequence.setCharAt(index, newChar);
        dotPairCount += delta;
        return dotPairCount;
    }

    private boolean isDot(int index) {
        return index >= 0 && index < sequence.length() && sequence.charAt(index) == DOT;
    }

    public int getDotPairCount() {
        return dotPairCount;
    }
}

