/**
 * Maintains the state of the cells and efficiently tracks the count 
 * of adjacent pairs of '.' characters.
 */
class DotPairTracker {
    private final char[] cells;
    private int pairCount;

    /**
     * Constructor calculates the initial number of adjacent dot pairs.
     * @param cells The initial character array.
     */
    public DotPairTracker(char[] cells) {
        this.cells = cells;
        this.pairCount = 0;
        for (int i = 0; i < cells.length - 1; i++) {
            if (isDotPair(i, i + 1)) {
                pairCount++;
            }
        }
    }

    /**
     * Updates a cell and adjusts the pair count based on the change.
     * @param index The 0-indexed position of the cell to update.
     * @param newChar The new character to place at the position.
     */
    public void update(int index, char newChar) {
        // If the character is not actually changing, do nothing
        if (index < 0 || index >= cells.length || cells[index] == newChar) {
            return;
        }

        // 1. Subtract the contribution of the old character to the pair count
        removeContribution(index);

        // 2. Apply the change
        cells[index] = newChar;

        // 3. Add the contribution of the new character to the pair count
        addContribution(index);
    }

    private void removeContribution(int index) {
        // Check pair with the left neighbor
        if (index > 0 && isDotPair(index - 1, index)) {
            pairCount--;
        }
        // Check pair with the right neighbor
        if (index < cells.length - 1 && isDotPair(index, index + 1)) {
            pairCount--;
        }
    }

    private void addContribution(int index) {
        // Check pair with the left neighbor
        if (index > 0 && isDotPair(index - 1, index)) {
            pairCount++;
        }
        // Check pair with the right neighbor
        if (index < cells.length - 1 && isDotPair(index, index + 1)) {
            pairCount++;
        }
    }

    private boolean isDotPair(int i, int j) {
        return cells[i] == '.' && cells[j] == '.';
    }

    public int getPairCount() {
        return pairCount;
    }
}

