/**
 * Manages a sequence of characters and maintains a running count 
 * of adjacent '.' (dot) pairs.
 */
class DotSequence {
    private final char[] grid;
    private int adjacentDotsCount;

    /**
     * Initializes the sequence with padding to allow O(1) boundary updates without 
     * index-out-of-bounds checks.
     * 
     * @param n Length of the sequence.
     * @param initial The starting character sequence.
     */
    public DotSequence(int n, String initial) {
        // Grid size n+2 allows using index 1 to n, with 0 and n+1 as safe buffers.
        this.grid = new char[n + 2];

        // Initialize buffers with a non-dot character ('#') to act as boundaries.
        for (int i = 0; i < grid.length; i++) {
            grid[i] = '#';
        }

        // Copy the initial string into the padded grid (1-based indexing).
        for (int i = 0; i < n; i++) {
            grid[i + 1] = initial.charAt(i);
        }

        // Pre-calculate the initial number of adjacent dot pairs.
        this.adjacentDotsCount = calculateInitialAdjacentDots(n);
    }

    /**
     * Iterates through the grid once to count initial pairs.
     */
    private int calculateInitialAdjacentDots(int n) {
        int count = 0;
        for (int i = 1; i < n; i++) {
            if (grid[i] == '.' && grid[i + 1] == '.') {
                count++;
            }
        }
        return count;
    }

    /**
     * Updates the character at a specific position and updates the adjacent dot count in O(1).
     * 
     * @param index The 1-based position in the sequence to update.
     * @param newChar The new character to place at the position.
     */
    public void update(int index, char newChar) {
        // If no change is required, return early to maintain stability.
        if (grid[index] == newChar) {
            return;
        }

        boolean wasDot = (grid[index] == '.');
        boolean isDot = (newChar == '.');

        // Case 1: A dot is being removed.
        if (wasDot && !isDot) {
            // If the neighbors were dots, we just broke two potential pairs.
            if (grid[index - 1] == '.') {
                adjacentDotsCount--;
            }
            if (grid[index + 1] == '.') {
                adjacentDotsCount--;
            }
        } 
        // Case 2: A dot is being added.
        else if (!wasDot && isDot) {
            // If the neighbors are dots, we just created two new pairs.
            if (grid[index - 1] == '.') {
                adjacentDotsCount++;
            }
            if (grid[index + 1] == '.') {
                adjacentDotsCount++;
            }
        }

        // Commit the change to the grid.
        grid[index] = newChar;
    }

    /**
     * @return The current number of adjacent '.' character pairs.
     */
    public int getAdjacentDotsCount() {
        return adjacentDotsCount;
    }
}

import java.util.Scanner;

/**
 * A refactored solution for tracking adjacent dot ('.') pairs in a string.
 * This program processes a sequence of character updates and reports 
 * the current number of adjacent dot pairs after each update.
 */
public class GoodStringProcessor {

    /**
     * Manages the character array and efficiently tracks the count of adjacent '.' pairs.
     */
    private static class DotPairTracker {
        private final char[] characters;
        private long totalDotPairs;

        /**
         * Initializes the tracker with the starting string.
         * 
         * @param initialString The initial string configuration.
         */
        public DotPairTracker(String initialString) {
            this.characters = initialString.toCharArray();
            this.totalDotPairs = calculateInitialPairs();
        }

        /**
         * Performs a linear scan to count initial adjacent dot pairs.
         * Time Complexity: O(N)
         */
        private long calculateInitialPairs() {
            long pairs = 0;
            for (int i = 0; i < characters.length - 1; i++) {
                if (isDotPair(i, i + 1)) {
                    pairs++;
                }
            }
            return pairs;
        }

        /**
         * Updates a character at a specific index and updates the pair count in constant time.
         * 
         * @param index    The 0-based index of the character to change.
         * @param newChar  The new character to be placed at the index.
         */
        public void update(int index, char newChar) {
            if (index < 0 || index >= characters.length) {
                return;
            }

            // 1. Remove the contribution of existing pairs involving this index
            // Check the pair to the left: (index-1, index)
            if (index > 0 && isDotPair(index - 1, index)) {
                totalDotPairs--;
            }
            // Check the pair to the right: (index, index+1)
            if (index < characters.length - 1 && isDotPair(index, index + 1)) {
                totalDotPairs--;
            }

            // 2. Update the character
            characters[index] = newChar;

            // 3. Add the contribution of new pairs formed by the updated character
            if (index > 0 && isDotPair(index - 1, index)) {
                totalDotPairs++;
            }
            if (index < characters.length - 1 && isDotPair(index, index + 1)) {
                totalDotPairs++;
            }
        }

        /**
         * Helper to check if two indices form a '.' pair.
         */
        private boolean isDotPair(int i, int j) {
            return characters[i] == '.' && characters[j] == '.';
        }

        public long getTotalDotPairs() {
            return totalDotPairs;
        }
    }

    public static void main(String[] args) {
        // Using try-with-resources to ensure the Scanner is closed automatically
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int stringLength = scanner.nextInt();
            int queryCount = scanner.nextInt();
            String initialString = scanner.next();

            DotPairTracker tracker = new DotPairTracker(initialString);
            StringBuilder outputBuffer = new StringBuilder();

            for (int i = 0; i < queryCount; i++) {
                if (!scanner.hasNextInt()) break;

                int position = scanner.nextInt();
                char newChar = scanner.next().charAt(0);

                // Convert 1-based input position to 0-based index
                tracker.update(position - 1, newChar);

                // Buffer the results to avoid multiple slow System.out.println calls
                outputBuffer.append(tracker.getTotalDotPairs()).append("\n");
            }

            // Print all results at once
            System.out.print(outputBuffer.toString());
        }
    }
}

