/**
 * Manages a sequence of characters and tracks the number of adjacent 
 * pairs of dot ('.') characters.
 */
class DotSequence {
    private final char[] sequence;
    private int dotPairCount;

    public DotSequence(String initialSequence) {
        this.sequence = initialSequence.toCharArray();
        this.dotPairCount = calculateInitialPairs();
    }

    /**
     * Calculates the initial number of adjacent dot pairs.
     */
    private int calculateInitialPairs() {
        int count = 0;
        for (int i = 0; i < sequence.length - 1; i++) {
            if (isDot(i) && isDot(i + 1)) {
                count++;
            }
        }
        return count;
    }

    /**
     * Updates a character at a specific index and returns the updated pair count.
     * 
     * @param index The 0-based index to update.
     * @param newChar The new character to place at the index.
     * @return The updated number of adjacent dot pairs.
     */
    public int update(int index, char newChar) {
        if (index < 0 || index >= sequence.length || sequence[index] == newChar) {
            return dotPairCount;
        }

        // 1. Remove the contribution of the old character to the pair count
        if (isDot(index)) {
            dotPairCount -= countAdjacentDots(index);
        }

        // 2. Perform the update
        sequence[index] = newChar;

        // 3. Add the contribution of the new character to the pair count
        if (isDot(index)) {
            dotPairCount += countAdjacentDots(index);
        }

        return dotPairCount;
    }

    private boolean isDot(int index) {
        return sequence[index] == '.';
    }

    /**
     * Counts how many neighbors of the given index are dots.
     */
    private int countAdjacentDots(int index) {
        int count = 0;
        if (index > 0 && isDot(index - 1)) {
            count++;
        }
        if (index < sequence.length - 1 && isDot(index + 1)) {
            count++;
        }
        return count;
    }
}

