/**
 * Manages a grid of characters and tracks the "segment score".
 * The score is defined as the sum of (length - 1) for all contiguous segments of '.' characters.
 */
class DotSegmentManager {
    private final char[] grid;
    private long segmentScore;

    public DotSegmentManager(char[] initialGrid) {
        this.grid = initialGrid;
        this.segmentScore = calculateInitialScore();
    }

    /**
     * Calculates the initial score based on the starting configuration.
     * Complexity: O(N)
     */
    private long calculateInitialScore() {
        long score = 0;
        int currentSegmentLength = 0;

        for (char c : grid) {
            if (c == '.') {
                currentSegmentLength++;
            } else {
                if (currentSegmentLength > 0) {
                    score += (currentSegmentLength - 1);
                }
                currentSegmentLength = 0;
            }
        }
        // Handle the last segment if the string ends with '.'
        if (currentSegmentLength > 0) {
            score += (currentSegmentLength - 1);
        }
        return score;
    }

    /**
     * Updates the grid at the specified index and updates the score.
     * Complexity: O(1)
     * 
     * @param index The 0-based index in the grid.
     * @param newChar The new character to place at the index.
     */
    public void update(int index, char newChar) {
        if (index < 0 || index >= grid.length || grid[index] == newChar) {
            return;
        }

        int dotNeighbors = countAdjacentDots(index);

        if (grid[index] == '.') {
            // Changing a '.' to a non-dot character:
            // The existing segment splits or shrinks, reducing the score.
            segmentScore -= dotNeighbors;
        } else {
            // Changing a non-dot character to a '.':
            // The new dot might merge existing segments, increasing the score.
            segmentScore += dotNeighbors;
        }

        grid[index] = newChar;
    }

    private int countAdjacentDots(int index) {
        int count = 0;
        if (index > 0 && grid[index - 1] == '.') {
            count++;
        }
        if (index < grid.length - 1 && grid[index + 1] == '.') {
            count++;
        }
        return count;
    }

    public long getSegmentScore() {
        return segmentScore;
    }
}

