/**
 * Segment Tree implementation to maintain scores and boundary characters
 * for efficient point updates and range queries.
 */
class SegmentTree {
    private final char[] leftChars;
    private final char[] rightChars;
    private final int[] scores;
    private final int offset;

    /**
     * Initializes the Segment Tree.
     * 
     * @param input The initial string of characters.
     */
    public SegmentTree(String input) {
        int length = input.length();
        // Find the next power of 2 to ensure a balanced tree
        this.offset = findNextPowerOfTwo(length);

        int treeSize = 2 * offset;
        this.leftChars = new char[treeSize];
        this.rightChars = new char[treeSize];
        this.scores = new int[treeSize];

        // Initialize leaves with input characters
        for (int i = 0; i < length; i++) {
            char c = input.charAt(i);
            int treeIdx = offset + i;
            leftChars[treeIdx] = c;
            rightChars[treeIdx] = c;
            scores[treeIdx] = 0;
        }

        // Initialize padding leaves with a non-dot character to avoid false score increases
        for (int i = length; i < offset; i++) {
            int treeIdx = offset + i;
            leftChars[treeIdx] = ' ';
            rightChars[treeIdx] = ' ';
            scores[treeIdx] = 0;
        }

        // Build the tree from bottom to top
        for (int i = offset - 1; i > 0; i--) {
            merge(i);
        }
    }

    /**
     * Updates the character at a specific index and propagates the change up the tree.
     * 
     * @param index The 0-based index in the original string.
     * @param newChar The character to place at that index.
     */
    public void update(int index, char newChar) {
        int treeIdx = index + offset;

        // Optimization: If the character is not actually changing, skip update
        if (leftChars[treeIdx] == newChar) {
            return;
        }

        leftChars[treeIdx] = newChar;
        rightChars[treeIdx] = newChar;

        // Update ancestors
        int parent = treeIdx / 2;
        while (parent >= 1) {
            merge(parent);
            parent /= 2;
        }
    }

    /**
     * Combines the data from the left and right children of a node into the node itself.
     * 
     * @param node The index of the parent node to update.
     */
    private void merge(int node) {
        int leftChild = 2 * node;
        int rightChild = 2 * node + 1;

        leftChars[node] = leftChars[leftChild];
        rightChars[node] = rightChars[rightChild];

        // The score of a parent is the sum of children scores + 1 if a connection forms at the junction
        int connectionBonus = (rightChars[leftChild] == '.' && leftChars[rightChild] == '.') ? 1 : 0;
        scores[node] = scores[leftChild] + scores[rightChild] + connectionBonus;
    }

    public int getTotalScore() {
        return scores[1];
    }

    private int findNextPowerOfTwo(int n) {
        int power = 1;
        while (power < n) {
            power <<= 1;
        }
        return power;
    }
}

