import java.util.StringTokenizer;

/**
 * Main entry point for the program.
 * Orchestrates the reading of input, the processing of queries, and the writing of output.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            run(reader, writer);
        } finally {
            writer.close();
        }
    }

    private static void run(FastReader reader, PrintWriter writer) {
        int stringLength = reader.nextInt();
        int queryCount = reader.nextInt();
        String initialPattern = reader.next();

        if (initialPattern == null) {
            return;
        }

        DotPatternManager manager = new DotPatternManager(initialPattern);

        for (int i = 0; i < queryCount; i++) {
            int index = reader.nextInt() - 1; // Convert to 0-based indexing
            char newChar = reader.next().charAt(0);

            int currentCount = manager.updateCharacter(index, newChar);
            writer.println(currentCount);
        }
    }

    /**
     * Manages the state of the character pattern and tracks the count 
     * of consecutive '.' characters efficiently.
     */
    static class DotPatternManager {
        private final char[] pattern;
        private int consecutiveDotCount;

        public DotPatternManager(String initialPattern) {
            this.pattern = initialPattern.toCharArray();
            this.consecutiveDotCount = calculateInitialConsecutiveDots();
        }

        /**
         * Calculates the initial number of ".." pairs in O(N) time.
         */
        private int calculateInitialConsecutiveDots() {
            int count = 0;
            for (int i = 0; i < pattern.length - 1; i++) {
                if (pattern[i] == '.' && pattern[i + 1] == '.') {
                    count++;
                }
            }
            return count;
        }

        /**
         * Updates the character at the specified index and updates the count in O(1) time.
         * 
         * @param index The 0-based index to update.
         * @param newChar The new character ('.' or '#').
         * @return The updated count of consecutive dot pairs.
         */
        public int updateCharacter(int index, char newChar) {
            char oldChar = pattern[index];

            // If the character is not actually changing, return the current count immediately.
            if (oldChar == newChar) {
                return consecutiveDotCount;
            }

            // Update count based on the transition
            if (oldChar == '.') {
                // We are removing a dot. Check if it was forming pairs with neighbors.
                if (index > 0 && pattern[index - 1] == '.') {
                    consecutiveDotCount--;
                }
                if (index < pattern.length - 1 && pattern[index + 1] == '.') {
                    consecutiveDotCount--;
                }
            } else {
                // We are adding a dot. Check if it creates new pairs with neighbors.
                if (index > 0 && pattern[index - 1] == '.') {
                    consecutiveDotCount++;
                }
                if (index < pattern.length - 1 && pattern[index + 1] == '.') {
                    consecutiveDotCount++;
                }
            }

            pattern[index] = newChar;
            return consecutiveDotCount;
        }
    }

    /**
     * Fast I/O utility for efficient reading of large input datasets.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            this.reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        return null;
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input stream", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            if (next == null) {
                throw new RuntimeException("Unexpected end of input");
            }
            return Integer.parseInt(next);
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Manages a grid of characters and tracks the number of adjacent '.' pairs.
 */
class DotPairTracker {
    private static final char DOT = '.';
    private final char[] grid;
    private int dotPairCount;

    /**
     * Initializes the tracker with an initial sequence of characters.
     * 
     * @param initialSequence The starting string representing the grid.
     */
    public DotPairTracker(String initialSequence) {
        this.grid = initialSequence.toCharArray();
        this.dotPairCount = 0;
        calculateInitialPairs();
    }

    private void calculateInitialPairs() {
        for (int i = 1; i < grid.length; i++) {
            if (grid[i] == DOT && grid[i - 1] == DOT) {
                dotPairCount++;
            }
        }
    }

    /**
     * Updates the character at the specified index and adjusts the pair count.
     * Based on the original logic, updates only occur when a character 
     * transitions to or from a dot ('.').
     *
     * @param index   The 0-based index to update.
     * @param newChar The new character to place at the index.
     */
    public void update(int index, char newChar) {
        if (index < 0 || index >= grid.length || grid[index] == newChar) {
            return;
        }

        boolean wasDot = (grid[index] == DOT);
        boolean isDot = (newChar == DOT);

        if (!wasDot && isDot) {
            // Transition: Non-dot -> Dot (Increases adjacent dot pairs)
            grid[index] = DOT;
            if (index > 0 && grid[index - 1] == DOT) {
                dotPairCount++;
            }
            if (index < grid.length - 1 && grid[index + 1] == DOT) {
                dotPairCount++;
            }
        } else if (wasDot && !isDot) {
            // Transition: Dot -> Non-dot (Decreases adjacent dot pairs)
            if (index > 0 && grid[index - 1] == DOT) {
                dotPairCount--;
            }
            if (index < grid.length - 1 && grid[index + 1] == DOT) {
                dotPairCount--;
            }
            grid[index] = newChar;
        }
        // Note: If transitioning between two non-dot characters, 
        // the original logic performs no change to the grid or the count.
    }

    public int getDotPairCount() {
        return dotPairCount;
    }
}

/**
 * High-performance scanner for reading input.
 */
class FastScanner {
    private final BufferedReader br;
    private StringTokenizer st;

    public FastScanner(InputStream stream) {
        br = new BufferedReader(new InputStreamReader(stream));
    }

    public String next() {
        while (st == null || !st.hasMoreElements()) {
            try {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            } catch (IOException e) {
                return null;
            }
        }
        return st.nextToken();
    }

    public int nextInt() {
        String next = next();
        return next != null ? Integer.parseInt(next) : 0;
    }
}

public class Main {

    public static void main(String[] args) {
        new Main().run();
    }

    /**
     * Orchestrates the program execution.
     */
    public void run() {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            solve(scanner, writer);
        } finally {
            writer.close();
        }
    }

    private void solve(FastScanner scanner, PrintWriter writer) {
        String nStr = scanner.next();
        if (nStr == null) return;

        int length = Integer.parseInt(nStr);
        int queryCount = scanner.nextInt();
        String initialGridString = scanner.next();

        if (initialGridString == null) return;

        DotPairTracker tracker = new DotPairTracker(initialGridString);

        for (int i = 0; i < queryCount; i++) {
            int position = scanner.nextInt() - 1; // Convert 1-based to 0-based index
            String charUpdate = scanner.next();

            if (charUpdate != null && !charUpdate.isEmpty()) {
                tracker.update(position, charUpdate.charAt(0));
            }

            writer.println(tracker.getDotPairCount());
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * A program that manages a sequence of characters and tracks 
 * the number of adjacent pairs of dot ('.') characters.
 */
public class DotPairManagerApp {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            int gridSize = reader.nextInt();
            int queryCount = reader.nextInt();
            String initialSequence = reader.next();

            DotPairManager manager = new DotPairManager(initialSequence.toCharArray());

            for (int i = 0; i < queryCount; i++) {
                int targetIndex = reader.nextInt() - 1; // Convert 1-based to 0-based index
                char newChar = reader.next().charAt(0);

                manager.updateCell(targetIndex, newChar);
                writer.println(manager.getAdjacentDotPairs());
            }
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        } finally {
            writer.close();
        }
    }

    /**
     * Manages the state of the character array and tracks the count 
     * of adjacent '.' pairs.
     */
    static class DotPairManager {
        private final char[] cells;
        private int adjacentDotPairs;

        public DotPairManager(char[] initialCells) {
            this.cells = initialCells;
            this.adjacentDotPairs = calculateInitialPairs();
        }

        /**
         * Updates the character at a specific index and updates the pair count.
         * 
         * @param index    The index to update.
         * @param newChar  The new character to place at the index.
         */
        public void updateCell(int index, char newChar) {
            if (index < 0 || index >= cells.length || cells[index] == newChar) {
                return;
            }

            // Step 1: Remove existing pairs affected by this index
            removePairsAt(index);

            // Step 2: Apply the change
            cells[index] = newChar;

            // Step 3: Add new pairs created by this change
            addPairsAt(index);
        }

        public int getAdjacentDotPairs() {
            return adjacentDotPairs;
        }

        private int calculateInitialPairs() {
            int count = 0;
            for (int i = 0; i < cells.length - 1; i++) {
                if (isDotPair(i, i + 1)) {
                    count++;
                }
            }
            return count;
        }

        private void removePairsAt(int index) {
            if (index > 0 && isDotPair(index - 1, index)) {
                adjacentDotPairs--;
            }
            if (index < cells.length - 1 && isDotPair(index, index + 1)) {
                adjacentDotPairs--;
            }
        }

        private void addPairsAt(int index) {
            if (index > 0 && isDotPair(index - 1, index)) {
                adjacentDotPairs++;
            }
            if (index < cells.length - 1 && isDotPair(index, index + 1)) {
                adjacentDotPairs++;
            }
        }

        private boolean isDotPair(int i, int j) {
            return cells[i] == '.' && cells[j] == '.';
        }
    }

    /**
     * Utility class for fast input reading.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A program that processes a grid, identifies connected components of '.' cells,
 * and calculates a value for each '#' cell based on the sizes of its adjacent '.' components.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            // Read grid dimensions
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            // Read the grid
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            // Process the grid logic
            GridProcessor processor = new GridProcessor(rows, cols, grid);
            char[][] result = processor.process();

            // Output the results
            for (char[] row : result) {
                writer.println(new String(row));
            }

        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Fast I/O utility for efficient reading of large inputs.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }
    }

    /**
     * Handles the logic of finding connected components and calculating cell values.
     */
    static class GridProcessor {
        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final int[][] componentIds;
        private final List<Integer> componentSizes;

        private static final int[][] DIRECTIONS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

        public GridProcessor(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            this.componentIds = new int[rows][cols];
            this.componentSizes = new ArrayList<>();
            // Component IDs start at 1; index 0 is a dummy value.
            this.componentSizes.add(0);
        }

        /**
         * Executes the two-step processing: 
         * 1. Identify components.
         * 2. Calculate resulting values.
         * 
         * @return The processed character grid.
         */
        public char[][] process() {
            boolean[][] visited = new boolean[rows][cols];
            int currentId = 1;

            // Step 1: Discover all connected components of '.' cells using BFS
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.' && !visited[i][j]) {
                        int size = performBfs(i, j, visited, currentId);
                        componentSizes.add(size);
                        currentId++;
                    }
                }
            }

            // Step 2: Calculate values for '#' cells based on adjacent component sizes
            char[][] result = new char[rows][cols];
            Set<Integer> adjacentComponentIds = new HashSet<>();

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.') {
                        result[i][j] = '.';
                    } else {
                        adjacentComponentIds.clear();
                        for (int[] dir : DIRECTIONS) {
                            int ni = i + dir[0];
                            int nj = j + dir[1];

                            if (isValidPosition(ni, nj) && grid[ni][nj] == '.') {
                                adjacentComponentIds.add(componentIds[ni][nj]);
                            }
                        }

                        int sumOfSizes = 1;
                        for (int id : adjacentComponentIds) {
                            sumOfSizes += componentSizes.get(id);
                        }
                        // The result is the last digit of the sum
                        result[i][j] = (char) ((sumOfSizes % 10) + '0');
                    }
                }
            }

            return result;
        }

        /**
         * Standard BFS to traverse a component and assign its ID and size.
         */
        private int performBfs(int startR, int startC, boolean[][] visited, int id) {
            int size = 0;
            Queue<int[]> queue = new ArrayDeque<>();

            queue.add(new int[]{startR, startC});
            visited[startR][startC] = true;
            componentIds[startR][startC] = id;

            while (!queue.isEmpty()) {
                int[] cell = queue.poll();
                int r = cell[0];
                int c = cell[1];
                size++;

                for (int[] dir : DIRECTIONS) {
                    int nr = r + dir[0];
                    int nc = c + dir[1];

                    if (isValidPosition(nr, nc) && !visited[nr][nc] && grid[nr][nc] == '.') {
                        visited[nr][nc] = true;
                        componentIds[nr][nc] = id;
                        queue.add(new int[]{nr, nc});
                    }
                }
            }
            return size;
        }

        private boolean isValidPosition(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the Grid Connectivity problem.
 * The goal is to identify connected components of '.' cells and, for every '#' cell,
 * calculate the sum of the sizes of its adjacent '.' components modulo 10.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        FastWriter writer = new FastWriter(System.out);

        try {
            GridConnectivitySolver solver = new GridConnectivitySolver(reader);
            solver.solve(writer);
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    /**
     * Logic for solving the grid-based connectivity problem.
     */
    static class GridConnectivitySolver {
        private final FastReader reader;
        private int rows;
        private int cols;
        private char[][] grid;
        private DisjointSetUnion dsu;

        // Directions for 4-connectivity: Up, Down, Left, Right
        private static final int[] DX = {-1, 1, 0, 0};
        private static final int[] DY = {0, 0, -1, 1};

        public GridConnectivitySolver(FastReader reader) {
            this.reader = reader;
        }

        public void solve(FastWriter writer) throws IOException {
            readInput();
            computeComponents();
            writeOutput(writer);
        }

        private void readInput() throws IOException {
            rows = reader.nextInt();
            cols = reader.nextInt();
            grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = reader.nextChar();
                }
            }
            dsu = new DisjointSetUnion(rows * cols);
        }

        private void computeComponents() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.') {
                        // We only need to check two directions (Right and Down) 
                        // to avoid redundant union operations.
                        checkAndUnion(i, j, i, j + 1);
                        checkAndUnion(i, j, i + 1, j);
                    }
                }
            }
        }

        private void checkAndUnion(int r1, int c1, int r2, int c2) {
            if (isValid(r2, c2) && grid[r2][c2] == '.') {
                dsu.union(toIndex(r1, c1), toIndex(r2, c2));
            }
        }

        private void writeOutput(FastWriter writer) {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.') {
                        sb.append('.');
                    } else {
                        sb.append(calculateAdjacentComponentSum(i, j));
                    }
                }
                sb.append('\n');
            }
            writer.print(sb.toString());
        }

        private int calculateAdjacentComponentSum(int r, int c) {
            Set<Integer> uniqueComponentRoots = new HashSet<>();
            for (int k = 0; k < 4; k++) {
                int ni = r + DX[k];
                int nj = c + DY[k];
                if (isValid(ni, nj) && grid[ni][nj] == '.') {
                    uniqueComponentRoots.add(dsu.find(toIndex(ni, nj)));
                }
            }

            int totalSize = 1; // Start with 1 for the '#' cell itself (as per original logic)
            for (int root : uniqueComponentRoots) {
                totalSize += dsu.getSize(root);
            }
            return totalSize % 10;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        private int toIndex(int r, int c) {
            return r * cols + c;
        }
    }

    /**
     * Disjoint Set Union (DSU) with Path Compression and Union by Size.
     */
    static class DisjointSetUnion {
        private final int[] parent;
        private final int[] size;

        public DisjointSetUnion(int n) {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        /**
         * Iterative find to prevent StackOverflow on large grids.
         */
        public int find(int i) {
            int root = i;
            while (parent[root] != root) {
                root = parent[root];
            }
            // Path compression
            while (parent[i] != root) {
                int next = parent[i];
                parent[i] = root;
                i = next;
            }
            return root;
        }

        public void union(int i, int j) {
            int rootI = find(i);
            int rootJ = find(j);
            if (rootI != rootJ) {
                // Union by size: attach smaller tree to larger tree
                if (size[rootI] < size[rootJ]) {
                    parent[rootI] = rootJ;
                    size[rootJ] += size[rootI];
                } else {
                    parent[rootJ] = rootI;
                    size[rootI] += size[rootJ];
                }
            }
        }

        public int getSize(int i) {
            return size[find(i)];
        }
    }

    /**
     * High-performance input reader.
     */
    static class FastReader {
        private final InputStream in;
        private final byte[] buffer = new byte[1024 * 16];
        private int pointer = 0;
        private int bufferLength = 0;

        public FastReader(InputStream in) {
            this.in = in;
        }

        private byte read() throws IOException {
            if (pointer >= bufferLength) {
                pointer = 0;
                bufferLength = in.read(buffer);
                if (bufferLength <= 0) return -1;
            }
            return buffer[pointer++];
        }

        public int nextInt() throws IOException {
            int c = read();
            while (c >= 0 && c <= 32) c = read();
            if (c == -1) return -1;
            int neg = 1;
            if (c == '-') {
                neg = -1;
                c = read();
            }
            int res = 0;
            while (c >= '0' && c <= '9') {
                res = res * 10 + (c - '0');
                c = read();
            }
            return res * neg;
        }

        public char nextChar() throws IOException {
            int c = read();
            while (c >= 0 && c <= 32) c = read();
            return (char) c;
        }
    }

    /**
     * High-performance output writer.
     */
    static class FastWriter {
        private final PrintWriter writer;

        public FastWriter(OutputStream out) {
            this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(out)));
        }

        public void print(String s) {
            writer.print(s);
        }

        public void close() {
            writer.close();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A utility to analyze a grid of characters, grouping connected '.' cells into components
 * and calculating a new value for non-dot cells based on the sum of the sizes of 
 * their neighboring components.
 */
public class GridComponentAnalyzer {

    /**
     * Represents a Disjoint Set Union (DSU) data structure to manage connected components.
     */
    private static class DisjointSetUnion {
        private final int[] parent;
        private final int[] size;

        public DisjointSetUnion(int n) {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        public int find(int i) {
            if (parent[i] == i) {
                return i;
            }
            return parent[i] = find(parent[i]); // Path compression
        }

        public void union(int i, int j) {
            int rootI = find(i);
            int rootJ = find(j);
            if (rootI != rootJ) {
                // Union by size to keep the tree flat
                if (size[rootI] < size[rootJ]) {
                    parent[rootI] = rootJ;
                    size[rootJ] += size[rootI];
                } else {
                    parent[rootJ] = rootI;
                    size[rootI] += size[rootJ];
                }
            }
        }

        public int getSize(int i) {
            return size[find(i)];
        }
    }

    /**
     * Fast I/O utility for efficient reading of large inputs.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }

    private static final int[][] DIRECTIONS = {
        {1, 0}, {0, 1}, {-1, 0}, {0, -1}
    };

    public void run() {
        FastReader in = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int rowCount = in.nextInt();
            int colCount = in.nextInt();
            char[][] grid = new char[rowCount][colCount];

            for (int i = 0; i < rowCount; i++) {
                grid[i] = in.next().toCharArray();
            }

            processGrid(rowCount, colCount, grid);

            for (int i = 0; i < rowCount; i++) {
                out.println(new String(grid[i]));
            }
        } catch (Exception e) {
            // In a real application, use a logger
            e.printStackTrace();
        } finally {
            out.close();
        }
    }

    private void processGrid(int rowCount, int colCount, char[][] grid) {
        DisjointSetUnion dsu = new DisjointSetUnion(rowCount * colCount);

        // Phase 1: Group all adjacent '.' cells into components
        for (int r = 0; r < rowCount; r++) {
            for (int c = 0; c < colCount; c++) {
                if (grid[r][c] == '.') {
                    // We only need to check right and down to avoid redundant unions
                    checkAndUnion(r, c, r + 1, c, rowCount, colCount, grid, dsu);
                    checkAndUnion(r, c, r, c + 1, rowCount, colCount, grid, dsu);
                }
            }
        }

        // Phase 2: Calculate new values for non-dot cells
        for (int r = 0; r < rowCount; r++) {
            for (int c = 0; c < colCount; c++) {
                if (grid[r][c] == '.') {
                    continue;
                }

                Set<Integer> uniqueNeighborRoots = new HashSet<>();
                for (int[] dir : DIRECTIONS) {
                    int nr = r + dir[0];
                    int nc = c + dir[1];

                    if (isWithinBounds(nr, nc, rowCount, colCount) && grid[nr][nc] == '.') {
                        uniqueNeighborRoots.add(dsu.find(nr * colCount + nc));
                    }
                }

                long totalNeighborSize = 0;
                for (int root : uniqueNeighborRoots) {
                    totalNeighborSize += dsu.getSize(root);
                }

                // Result is (sum of component sizes + 1) mod 10
                grid[r][c] = (char) ('0' + (totalNeighborSize + 1) % 10);
            }
        }
    }

    private void checkAndUnion(int r1, int c1, int r2, int c2, int maxR, int maxC, 
                               char[][] grid, DisjointSetUnion dsu) {
        if (isWithinBounds(r2, c2, maxR, maxC) && grid[r1][c1] == '.' && grid[r2][c2] == '.') {
            dsu.union(r1 * maxC + c1, r2 * maxC + c2);
        }
    }

    private boolean isWithinBounds(int r, int c, int maxR, int maxC) {
        return r >= 0 && r < maxR && c >= 0 && c < maxC;
    }

    public static void main(String[] args) {
        new GridComponentAnalyzer().run();
    }
}

import java.util.*;
import java.io.*;

/**
 * A solver for the grid problem where '*' cells are obstacles 
 * and '.' cells are empty spaces. The value of an obstacle cell 
 * is (1 + sum of sizes of unique adjacent empty-space components) % 10.
 */
public class Codechef {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] grid = reader.readGrid(rows, cols);

            GridSolver solver = new GridSolver(rows, cols, grid);
            solver.solve(writer);
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    static class GridSolver {
        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final int[][] componentIds;
        private final int[] componentSizes;
        private final boolean[][] visited;
        private int currentComponentId = 0;

        public GridSolver(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            this.componentIds = new int[rows][cols];
            this.componentSizes = new int[rows * cols + 1];
            this.visited = new boolean[rows][cols];
        }

        public void solve(PrintWriter out) {
            identifyComponents();
            printResults(out);
        }

        /**
         * Iterates through the grid to find all connected components of '.' cells.
         */
        private void identifyComponents() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.' && !visited[i][j]) {
                        currentComponentId++;
                        int size = performDFS(i, j, currentComponentId);
                        componentSizes[currentComponentId] = size;
                    }
                }
            }
        }

        /**
         * Depth First Search to traverse a component and assign it an ID and size.
         */
        private int performDFS(int r, int c, int id) {
            Stack<int[]> stack = new Stack<>();
            stack.push(new int[]{r, c});
            visited[r][c] = true;
            componentIds[r][c] = id;
            int size = 0;

            int[] dr = {0, 1, 0, -1};
            int[] dc = {1, 0, -1, 0};

            // Using an iterative DFS to avoid StackOverflowError on large grids
            // However, to keep the logic close to the original, a recursive approach 
            // is often used in competitive programming. Here is the recursive version:
            return recursiveDFS(r, c, id);
        }

        private int recursiveDFS(int r, int c, int id) {
            visited[r][c] = true;
            componentIds[r][c] = id;
            int size = 1;

            int[] dr = {0, 1, 0, -1};
            int[] dc = {1, 0, -1, 0};

            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i];
                int nc = c + dc[i];

                if (isValid(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                    size += recursiveDFS(nr, nc, id);
                }
            }
            return size;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        /**
         * Computes and prints the grid values.
         */
        private void printResults(PrintWriter out) {
            int[] dr = {0, 1, 0, -1};
            int[] dc = {1, 0, -1, 0};

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.') {
                        out.print('.');
                    } else {
                        Set<Integer> adjacentComponentIds = new HashSet<>();
                        for (int k = 0; k < 4; k++) {
                            int nr = i + dr[k];
                            int nc = j + dc[k];
                            if (isValid(nr, nc) && grid[nr][nc] == '.') {
                                adjacentComponentIds.add(componentIds[nr][nc]);
                            }
                        }

                        int totalSize = 1;
                        for (int id : adjacentComponentIds) {
                            totalSize += componentSizes[id];
                        }
                        out.print(totalSize % 10);
                    }
                }
                out.println();
            }
        }
    }

    /**
     * Efficient Input Reader for fast I/O.
     */
    static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public char[][] readGrid(int rows, int cols) throws IOException {
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }
            return grid;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.*;

/**
 * GridProcessor identifies connected components of '.' in a grid
 * and transforms '*' cells based on the sizes of adjacent '.' components.
 */
public class GridProcessor {

    private static final int[][] DIRECTIONS = {
            {-1, 0}, {1, 0}, {0, 1}, {0, -1}
    };

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int[][] componentIds;
    private final List<Integer> componentSizes;

    public GridProcessor(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.componentIds = new int[rows][cols];
        this.componentSizes = new ArrayList<>();
        // Initialize componentIds with 0 (unassigned)
    }

    /**
     * Performs a BFS to find all connected components of '.' and label them.
     */
    public void findComponents() {
        int currentComponentId = 1;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && componentIds[r][c] == 0) {
                    int size = bfs(r, c, currentComponentId);
                    componentSizes.add(size);
                    currentComponentId++;
                }
            }
        }
    }

    private int bfs(int startR, int startC, int id) {
        int size = 0;
        Queue<int[]> queue = new LinkedList<>();

        queue.add(new int[]{startR, startC});
        componentIds[startR][startC] = id;

        while (!queue.isEmpty()) {
            int[] cell = queue.poll();
            int currR = cell[0];
            int currC = cell[1];
            size++;

            for (int[] dir : DIRECTIONS) {
                int nextR = currR + dir[0];
                int nextC = currC + dir[1];

                if (isValid(nextR, nextC) && 
                    grid[nextR][nextC] == '.' && 
                    componentIds[nextR][nextC] == 0) {

                    componentIds[nextR][nextC] = id;
                    queue.add(new int[]{nextR, nextC});
                }
            }
        }
        return size;
    }

    /**
     * Transforms the grid based on the problem rules.
     * Returns a formatted string representation of the result.
     */
    public String transformGrid() {
        StringBuilder result = new StringBuilder();

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*') {
                    result.append(calculateStarValue(r, c));
                } else {
                    result.append('.');
                }
            }
            result.append("\n");
        }
        return result.toString();
    }

    private int calculateStarValue(int r, int c) {
        Set<Integer> adjacentComponentIds = new HashSet<>();

        for (int[] dir : DIRECTIONS) {
            int nextR = r + dir[0];
            int nextC = c + dir[1];

            if (isValid(nextR, nextC) && componentIds[nextR][nextC] > 0) {
                adjacentComponentIds.add(componentIds[nextR][nextC]);
            }
        }

        int totalSizeSum = 0;
        for (int id : adjacentComponentIds) {
            // componentIds are 1-based, componentSizes list is 0-based
            totalSizeSum += componentSizes.get(id - 1);
        }

        return (totalSizeSum + 1) % 10;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    public static void main(String[] args) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String firstLine = reader.readLine();
            if (firstLine == null) return;

            StringTokenizer st = new StringTokenizer(firstLine);
            int n = Integer.parseInt(st.nextToken());
            int m = Integer.parseInt(st.nextToken());

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                String line = reader.readLine();
                for (int j = 0; j < m; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }

            GridProcessor processor = new GridProcessor(n, m, grid);
            processor.findComponents();
            System.out.print(processor.transformGrid());

        } catch (IOException | NumberFormatException e) {
            e.printStackTrace();
        }
    }
}

