/**
 * Entry point for the Labyrinth application.
 * Handles user input and output formatting.
 */
public class TheLabyrinth {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        scanner.nextLine(); // Consume newline

        String[] gridLines = new String[rows];
        for (int i = 0; i < rows; i++) {
            gridLines[i] = scanner.nextLine();
        }

        Labyrinth labyrinth = new Labyrinth(rows, cols, gridLines);
        String[] result = labyrinth.solve();

