/**
 * Logic engine for processing the labyrinth grid.
 */
class Labyrinth {
    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int[][] componentIds;
    private final Map<Integer, Integer> componentSizes;

    private static final char PATH = '.';
    private static final char WALL = '#';
    private static final int UNASSIGNED = 0;

    public Labyrinth(int rows, int cols, String[] input) {
        this.rows = rows;
        this.cols = cols;
        this.grid = new char[rows][cols];
        this.componentIds = new int[rows][cols];
        this.componentSizes = new HashMap<>();

        for (int i = 0; i < rows; i++) {
            this.grid[i] = input[i].toCharArray();
        }
    }

    /**
     * Performs the transformation of the labyrinth.
     * @return A processed grid as an array of Strings.
     */
    public String[] solve() {
        identifyConnectedComponents();
        return constructResultGrid();
    }

    /**
     * Finds all connected regions of PATH ('.') and assigns them a unique ID.
     */
    private void identifyConnectedComponents() {
        int currentComponentId = 1;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == PATH && componentIds[r][c] == UNASSIGNED) {
                    int size = floodFill(r, c, currentComponentId);
                    componentSizes.put(currentComponentId, size);
                    currentComponentId++;
                }
            }
        }
    }

    /**
     * Uses recursion (DFS) to label a connected component.
     * 
     * @param r Starting row
     * @param c Starting column
     * @param id The ID to assign to this component
     * @return The total size of the component found
     */
    private int floodFill(int r, int c, int id) {
        if (isOutOfBounds(r, c) || grid[r][c] != PATH || componentIds[r][c] != UNASSIGNED) {
            return 0;
        }

        componentIds[r][c] = id;
        int size = 1;

        size += floodFill(r + 1, c, id);
        size += floodFill(r - 1, c, id);
        size += floodFill(r, c + 1, id);
        size += floodFill(r, c - 1, id);

        return size;
    }

    /**
     * Creates the final grid, replacing walls with the sum of adjacent component sizes.
     */
    private String[] constructResultGrid() {
        String[] result = new String[rows];

        for (int r = 0; r < rows; r++) {
            StringBuilder sb = new StringBuilder();
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == PATH) {
                    sb.append(PATH);
                } else {
                    sb.append(calculateWallValue(r, c));
                }
            }
            result[r] = sb.toString();
        }
        return result;
    }

    /**
     * Calculates the value for a wall '#' based on its 4-way neighbors.
     */
    private char calculateWallValue(int r, int c) {
        Set<Integer> neighboringComponentIds = new HashSet<>();

        // Check 4 cardinal directions
        int[][] directions = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};
        for (int[] dir : directions) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            if (!isOutOfBounds(nr, nc) && componentIds[nr][nc] != UNASSIGNED) {
                neighboringComponentIds.add(componentIds[nr][nc]);
            }
        }

        int totalSize = 0;
        for (int id : neighboringComponentIds) {
            totalSize += componentSizes.getOrDefault(id, 0);
        }

        // Return size modulo 10 as a character
        return (char) ((totalSize % 10) + '0');
    }

    private boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= rows || c < 0 || c >= cols;
    }
}

import java.io.*;
import java.util.*;

/**
 * GridAnalyzer processes a grid of '.' (empty spaces) and '*' (obstacles).
 * It identifies connected components of empty spaces and calculates a value 
 * for each obstacle based on the sum of the sizes of its unique adjacent components.
 */
public class GridAnalyzer {

    private static final int[][] DIRECTIONS = {
        {1, 0}, {-1, 0}, {0, 1}, {0, -1}
    };

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            GridAnalyzer analyzer = new GridAnalyzer();
            String result = analyzer.processGrid(rows, cols, grid);
            System.out.print(result);

        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Orchestrates the processing logic.
     */
    public String processGrid(int rows, int cols, char[][] grid) {
        ComponentMap componentMap = findComponents(rows, cols, grid);
        return computeFinalGrid(rows, cols, grid, componentMap);
    }

    /**
     * Represents the mapping of component IDs to their respective sizes.
     */
    private static class ComponentMap {
        final int[][] componentIds;
        final List<Integer> componentSizes;

        ComponentMap(int[][] componentIds, List<Integer> componentSizes) {
            this.componentIds = componentIds;
            this.componentSizes = componentSizes;
        }
    }

    /**
     * Uses BFS to identify all connected components of '.' cells.
     * 
     * @return A ComponentMap containing the ID of the component for each cell and a list of component sizes.
     */
    private ComponentMap findComponents(int rows, int cols, char[][] grid) {
        int[][] componentIds = new int[rows][cols];
        for (int[] row : componentIds) {
            Arrays.fill(row, -1);
        }

        List<Integer> componentSizes = new ArrayList<>();
        int componentCount = 0;

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.' && componentIds[i][j] == -1) {
                    int size = performBFS(i, j, rows, cols, grid, componentIds, componentCount);
                    componentSizes.add(size);
                    componentCount++;
                }
            }
        }

        return new ComponentMap(componentIds, componentSizes);
    }

    /**
     * Performs a Breadth-First Search to map out a single connected component.
     */
    private int performBFS(int startR, int startC, int rows, int cols, 
                           char[][] grid, int[][] componentIds, int currentId) {
        Queue<Integer> queue = new LinkedList<>();
        int size = 0;

        // Pack coordinates into a single integer to reduce object allocation
        queue.add(startR * cols + startC);
        componentIds[startR][startC] = currentId;

        while (!queue.isEmpty()) {
            int pos = queue.poll();
            int r = pos / cols;
            int c = pos % cols;
            size++;

            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                if (isValid(nr, nc, rows, cols) && grid[nr][nc] == '.' && componentIds[nr][nc] == -1) {
                    componentIds[nr][nc] = currentId;
                    queue.add(nr * cols + nc);
                }
            }
        }
        return size;
    }

    /**
     * Calculates the resulting grid values for '*' cells.
     */
    private String computeFinalGrid(int rows, int cols, char[][] grid, ComponentMap compMap) {
        StringBuilder output = new StringBuilder();

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*') {
                    output.append(calculateStarValue(i, j, rows, cols, compMap));
                } else {
                    output.append('.');
                }
            }
            output.append('\n');
        }
        return output.toString();
    }

    /**
     * Calculates the value for a star cell: (1 + sum of unique adjacent component sizes) % 10.
     */
    private int calculateStarValue(int r, int c, int rows, int cols, ComponentMap compMap) {
        Set<Integer> adjacentComponentIds = new HashSet<>();

        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            if (isValid(nr, nc, rows, cols) && compMap.componentIds[nr][nc] != -1) {
                adjacentComponentIds.add(compMap.componentIds[nr][nc]);
            }
        }

        int sumOfSizes = 1; // The original logic starts the count at 1
        for (int id : adjacentComponentIds) {
            sumOfSizes += compMap.componentSizes.get(id);
        }

        return sumOfSizes % 10;
    }

    private boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * An application to analyze grid-based components and calculate 
 * values for obstacle cells based on adjacent empty cell components.
 */
public class GridAnalyzerApp {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] grid = reader.readGrid(rows, cols);

            GridAnalyzer analyzer = new GridAnalyzer(grid, rows, cols);
            analyzer.process();
            analyzer.printResults(writer);
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    /**
     * Logic handler for analyzing the grid components.
     */
    static class GridAnalyzer {
        private static final char EMPTY_CELL = '.';
        private static final char OBSTACLE_CELL = '*';

        private static final int[] ROW_OFFSETS = {-1, 0, 0, 1};
        private static final int[] COL_OFFSETS = {0, -1, 1, 0};

        private final char[][] grid;
        private final int rows;
        private final int cols;
        private final int[][] componentIds;
        private final List<Integer> componentSizes;

        public GridAnalyzer(char[][] grid, int rows, int cols) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
            this.componentIds = new int[rows][cols];
            this.componentSizes = new ArrayList<>();
        }

        /**
         * Identifies all connected components of empty cells using BFS.
         */
        public void process() {
            int currentComponentId = 1;

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == EMPTY_CELL && componentIds[r][c] == 0) {
                        int size = performBfs(r, c, currentComponentId);
                        componentSizes.add(size);
                        currentComponentId++;
                    }
                }
            }
        }

        private int performBfs(int startRow, int startCol, int id) {
            int size = 0;
            Queue<Point> queue = new ArrayDeque<>();

            queue.add(new Point(startRow, startCol));
            componentIds[startRow][startCol] = id;
            size++;

            while (!queue.isEmpty()) {
                Point current = queue.poll();

                for (int i = 0; i < 4; i++) {
                    int nr = current.row + ROW_OFFSETS[i];
                    int nc = current.col + COL_OFFSETS[i];

                    if (isValid(nr, nc) && grid[nr][nc] == EMPTY_CELL && componentIds[nr][nc] == 0) {
                        componentIds[nr][nc] = id;
                        queue.add(new Point(nr, nc));
                        size++;
                    }
                }
            }
            return size;
        }

        /**
         * Prints the processed grid to the provided PrintWriter.
         */
        public void printResults(PrintWriter out) {
            StringBuilder sb = new StringBuilder();
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == EMPTY_CELL) {
                        sb.append(EMPTY_CELL);
                    } else {
                        sb.append(calculateObstacleValue(r, c));
                    }
                }
                sb.append("\n");
            }
            out.print(sb.toString());
        }

        private int calculateObstacleValue(int r, int c) {
            Set<Integer> adjacentComponentIds = new HashSet<>();

            for (int i = 0; i < 4; i++) {
                int nr = r + ROW_OFFSETS[i];
                int nc = c + COL_OFFSETS[i];

                if (isValid(nr, nc) && grid[nr][nc] == EMPTY_CELL) {
                    int id = componentIds[nr][nc];
                    if (id > 0) {
                        adjacentComponentIds.add(id);
                    }
                }
            }

            int totalAdjacentEmptyCells = 1; // Start with 1 for the obstacle itself
            for (int id : adjacentComponentIds) {
                // componentSizes is 0-indexed, so ID 1 is at index 0
                totalAdjacentEmptyCells += componentSizes.get(id - 1);
            }

            return totalAdjacentEmptyCells % 10;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * Represents a coordinate in the grid.
     */
    static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Utility class for fast input reading.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public char[][] readGrid(int rows, int cols) {
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }
            return grid;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * TheLabyrinth solver.
 * This program identifies connected components of paths ('.') in a grid
 * and calculates a value for each wall ('*') based on the sizes of 
 * adjacent unique path components.
 */
public class TheLabyrinth {

    public static void main(String[] args) {
        try {
            LabyrinthSolver solver = new LabyrinthSolver(System.in);
            solver.solve();
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    static class LabyrinthSolver {
        private static final int[] ROW_OFFSETS = {1, 0, -1, 0};
        private static final int[] COL_OFFSETS = {0, 1, 0, -1};

        private final FastReader reader;
        private int rows;
        private int cols;
        private char[][] grid;
        private int[][] componentIdGrid;
        private int[] componentSizes;

        public LabyrinthSolver(InputStream inputStream) {
            this.reader = new FastReader(inputStream);
        }

        public void solve() throws IOException {
            readInput();
            identifyComponents();
            char[][] resultGrid = computeWallValues();
            printOutput(resultGrid);
        }

        private void readInput() throws IOException {
            rows = reader.nextInt();
            cols = reader.nextInt();
            grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                // Using next() instead of nextLine() to avoid issues with leftover newlines
                grid[i] = reader.next().toCharArray();
            }
        }

        /**
         * Uses BFS to find all connected components of '.' and assigns them an ID.
         */
        private void identifyComponents() {
            componentIdGrid = new int[rows][cols];
            // Max possible components is (rows * cols) / 2
            componentSizes = new int[rows * cols + 1];
            int currentId = 1;

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.' && componentIdGrid[r][c] == 0) {
                        int size = bfs(r, c, currentId);
                        componentSizes[currentId] = size;
                        currentId++;
                    }
                }
            }
        }

        private int bfs(int startR, int startC, int id) {
            int size = 0;
            Queue<int[]> queue = new ArrayDeque<>();

            queue.add(new int[]{startR, startC});
            componentIdGrid[startR][startC] = id;
            size++;

            while (!queue.isEmpty()) {
                int[] cell = queue.poll();
                int r = cell[0];
                int c = cell[1];

                for (int i = 0; i < 4; i++) {
                    int nr = r + ROW_OFFSETS[i];
                    int nc = c + COL_OFFSETS[i];

                    if (isValid(nr, nc) && grid[nr][nc] == '.' && componentIdGrid[nr][nc] == 0) {
                        componentIdGrid[nr][nc] = id;
                        size++;
                        queue.add(new int[]{nr, nc});
                    }
                }
            }
            return size;
        }

        /**
         * Calculates the value for each '*' cell based on adjacent components.
         */
        private char[][] computeWallValues() {
            char[][] resultGrid = new char[rows][cols];

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.') {
                        resultGrid[r][c] = '.';
                    } else {
                        resultGrid[r][c] = calculateWallValue(r, c);
                    }
                }
            }
            return resultGrid;
        }

        private char calculateWallValue(int r, int c) {
            int totalReachableCells = 1; // The wall itself counts as 1
            Set<Integer> seenComponentIds = new HashSet<>();

            for (int i = 0; i < 4; i++) {
                int nr = r + ROW_OFFSETS[i];
                int nc = c + COL_OFFSETS[i];

                if (isValid(nr, nc) && grid[nr][nc] == '.') {
                    int compId = componentIdGrid[nr][nc];
                    if (compId > 0 && seenComponentIds.add(compId)) {
                        totalReachableCells += componentSizes[compId];
                    }
                }
            }

            int digit = totalReachableCells % 10;
            return (char) (digit + '0');
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        private void printOutput(char[][] resultGrid) {
            PrintWriter pw = new PrintWriter(System.out);
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    sb.append(resultGrid[i][j]);
                }
                sb.append('\n');
            }
            pw.print(sb.toString());
            pw.flush();
            pw.close();
        }
    }

    /**
     * High-performance input reader.
     */
    static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream s) {
            br = new BufferedReader(new InputStreamReader(s));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * GridMazeSolver processes a grid containing obstacles ('*') and empty spaces ('.').
 * It identifies connected components of empty spaces and replaces each obstacle
 * with a digit representing (1 + sum of sizes of unique adjacent components) % 10.
 */
public class GridMazeSolver {

    // Directions for 4-way connectivity: Up, Down, Left, Right
    private static final int[][] DIRECTIONS = {
            {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    private final int rows;
    private final int cols;
    private final boolean[][] isObstacle;
    private final int[][] componentIds;
    private final int[] componentSizes;
    private int componentCount = 0;

    /**
     * Initializes the grid and prepares the internal data structures.
     *
     * @param n          Number of rows
     * @param m          Number of columns
     * @param gridLines  The input grid as an array of Strings
     */
    public GridMazeSolver(int n, int m, String[] gridLines) {
        this.rows = n;
        this.cols = m;

        // Padding the grid with a 1-cell border of obstacles to simplify neighbor checks.
        // This avoids 'IndexOutOfBounds' when checking neighbors of edge cells.
        this.isObstacle = new boolean[n + 2][m + 2];
        this.componentIds = new int[n + 2][m + 2];
        this.componentSizes = new int[n * m + 1];

        // Initialize component IDs with -1 (meaning no component assigned)
        for (int i = 0; i < n + 2; i++) {
            Arrays.fill(componentIds[i], -1);
        }

        // Create the obstacle boundary padding
        for (int i = 0; i < n + 2; i++) {
            isObstacle[i][0] = true;
            isObstacle[i][m + 1] = true;
        }
        for (int j = 0; j < m + 2; j++) {
            isObstacle[0][j] = true;
            isObstacle[n + 1][j] = true;
        }

        // Load the actual grid data into the padded structure
        for (int i = 1; i <= n; i++) {
            String line = gridLines[i - 1];
            for (int j = 1; j <= m; j++) {
                if (line.charAt(j - 1) == '*') {
                    isObstacle[i][j] = true;
                }
            }
        }
    }

    /**
     * Orchestrates the component labeling and grid processing.
     */
    public void solve() throws IOException {
        labelConnectedComponents();
        printProcessedGrid();
    }

    /**
     * Traverses the grid to find and label all connected components of '.'
     * using an iterative BFS to prevent StackOverflowErrors on large inputs.
     */
    private void labelConnectedComponents() {
        for (int i = 1; i <= rows; i++) {
            for (int j = 1; j <= cols; j++) {
                // If cell is a '.' and hasn't been visited yet
                if (!isObstacle[i][j] && componentIds[i][j] == -1) {
                    bfs(i, j, componentCount++);
                }
            }
        }
    }

    /**
     * Performs BFS to label all cells within a single connected component.
     */
    private void bfs(int startR, int startC, int id) {
        int size = 0;
        Deque<int[]> queue = new ArrayDeque<>();

        queue.add(new int[]{startR, startC});
        componentIds[startR][startC] = id;

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int r = current[0];
            int c = current[1];
            size++;

            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                // Check if neighbor is part of a '.' component and not yet visited
                if (!isObstacle[nr][nc] && componentIds[nr][nc] == -1) {
                    componentIds[nr][nc] = id;
                    queue.add(new int[]{nr, nc});
                }
            }
        }
        componentSizes[id] = size;
    }

    /**
     * Constructs and prints the final grid with replaced obstacle values.
     */
    private void printProcessedGrid() throws IOException {
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
        for (int i = 1; i <= rows; i++) {
            StringBuilder sb = new StringBuilder();
            for (int j = 1; j <= cols; j++) {
                if (!isObstacle[i][j]) {
                    sb.append('.');
                } else {
                    sb.append(calculateObstacleDigit(i, j));
                }
            }
            out.println(sb.toString());
        }
        out.flush();
    }

    /**
     * Calculates the digit for an obstacle cell based on its neighboring components.
     */
    private char calculateObstacleDigit(int r, int c) {
        int sum = 1; // The original logic starts the sum at 1
        Set<Integer> uniqueAdjacentComponents = new HashSet<>();

        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            int id = componentIds[nr][nc];

            // If neighbor belongs to a '.' component
            if (id != -1) {
                uniqueAdjacentComponents.add(id);
            }
        }

        for (int id : uniqueAdjacentComponents) {
            sum += componentSizes[id];
        }

        return (char) ((sum % 10) + '0');
    }

    /**
     * Entry point of the application.
     */
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String firstLine = br.readLine();
        if (firstLine == null) return;

        StringTokenizer st = new StringTokenizer(firstLine);
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());

        String[] gridLines = new String[n];
        for (int i = 0; i < n; i++) {
            gridLines[i] = br.readLine();
        }

        GridMazeSolver solver = new GridMazeSolver(n, m, gridLines);
        solver.solve();
    }
}

import java.util.*;
import java.io.*;

/**
 * A solution to calculate the size of connected components in a grid.
 * For wall cells, it calculates the sum of sizes of adjacent unique components.
 */
public class Solution {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            String firstLine = reader.next();
            if (firstLine == null) return;

            int rows = Integer.parseInt(firstLine);
            int cols = reader.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            MazeSolver solver = new MazeSolver(grid, rows, cols);
            solver.solve(out);

        } catch (Exception e) {
            // In a production environment, use a proper logger.
            // e.printStackTrace();
        } finally {
            out.close();
        }
    }

    /**
     * Orchestrates the grid traversal and component calculation.
     */
    static class MazeSolver {
        private final char[][] grid;
        private final int rows;
        private final int cols;
        private final int[][] componentIds;
        private final Map<Integer, Integer> componentSizes;

        private static final int[][] DIRECTIONS = {
            {-1, 0}, {1, 0}, {0, -1}, {0, 1}
        };

        public MazeSolver(char[][] grid, int rows, int cols) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
            this.componentIds = new int[rows][cols];
            this.componentSizes = new HashMap<>();

            // Initialize component IDs with -1 (representing no component)
            for (int i = 0; i < rows; i++) {
                Arrays.fill(componentIds[i], -1);
            }
        }

        /**
         * Executes the algorithm: identifies components and computes output.
         */
        public void solve(PrintWriter out) {
            int currentId = 0;

            // Step 1: Identify all connected components of '.'
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.' && componentIds[r][c] == -1) {
                        performBFS(r, c, currentId++);
                    }
                }
            }

            // Step 2: Build the output grid
            StringBuilder output = new StringBuilder();
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.') {
                        output.append('.');
                    } else {
                        output.append(calculateWallValue(r, c));
                    }
                }
                output.append('\n');
            }
            out.print(output.toString());
        }

        private void performBFS(int startR, int startC, int id) {
            int size = 0;
            Deque<Point> queue = new ArrayDeque<>();

            queue.add(new Point(startR, startC));
            componentIds[startR][startC] = id;

            while (!queue.isEmpty()) {
                Point curr = queue.poll();
                size++;

                for (int[] dir : DIRECTIONS) {
                    int nr = curr.r + dir[0];
                    int nc = curr.c + dir[1];

                    if (isValid(nr, nc) && grid[nr][nc] == '.' && componentIds[nr][nc] == -1) {
                        componentIds[nr][nc] = id;
                        queue.add(new Point(nr, nc));
                    }
                }
            }
            componentSizes.put(id, size);
        }

        private int calculateWallValue(int r, int c) {
            int totalSize = 1; // Starting with 1 as per original logic
            Set<Integer> neighboringComponentIds = new HashSet<>();

            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                if (isValid(nr, nc) && componentIds[nr][nc] != -1) {
                    neighboringComponentIds.add(componentIds[nr][nc]);
                }
            }

            for (int id : neighboringComponentIds) {
                totalSize += componentSizes.getOrDefault(id, 0);
            }

            return totalSize % 10;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        /**
         * Simple data carrier for coordinates.
         */
        private static class Point {
            final int r, c;
            Point(int r, int c) {
                this.r = r;
                this.c = c;
            }
        }
    }

    /**
     * Fast I/O utility for efficient reading.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Main entry point for the Grid Component Analyzer application.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        GridProcessor processor = new GridProcessor(reader);
        processor.process(writer);

        writer.close();
    }

    /**
     * Handles the core logic of analyzing grid components and calculating adjacent component sums.
     */
    public static class GridProcessor {
        private static final int[][] DIRECTIONS = {
            {-1, 0}, {0, 1}, {1, 0}, {0, -1}
        };

        private final FastReader reader;

        public GridProcessor(FastReader reader) {
            this.reader = reader;
        }

        public void process(PrintWriter out) {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            char[][] originalGrid = new char[rows][cols];
            char[][] workingGrid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                for (int j = 0; j < cols; j++) {
                    char cell = line.charAt(j);
                    originalGrid[i][j] = cell;
                    workingGrid[i][j] = cell;
                }
            }

            int[][] componentIds = new int[rows][cols];
            Map<Integer, Integer> componentSizes = new HashMap<>();
            int componentIdCounter = 0;

            // Identify all connected components of '.'
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (workingGrid[i][j] == '.') {
                        componentIdCounter++;
                        int size = performBFS(workingGrid, i, j, componentIds, componentIdCounter);
                        componentSizes.put(componentIdCounter, size);
                    }
                }
            }

            // Generate output based on the original grid structure
            StringBuilder result = new StringBuilder();
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (originalGrid[i][j] == '.') {
                        result.append('.');
                    } else {
                        result.append(calculateAdjacentComponentSum(i, j, rows, cols, componentIds, componentSizes));
                    }
                }
                result.append('\n');
            }
            out.print(result.toString());
        }

        /**
         * Performs BFS to find all connected '.' cells and marks them with a component ID.
         * 
         * @return The number of cells found in this component.
         */
        private int performBFS(char[][] grid, int startI, int startJ, int[][] componentIds, int currentId) {
            int rows = grid.length;
            int cols = grid[0].length;
            int size = 0;

            Queue<Point> queue = new ArrayDeque<>();
            queue.add(new Point(startI, startJ));

            // Mark as visited immediately to prevent duplicate queue entries
            grid[startI][startJ] = '#';
            componentIds[startI][startJ] = currentId;
            size++;

            while (!queue.isEmpty()) {
                Point current = queue.poll();

                for (int[] dir : DIRECTIONS) {
                    int nextI = current.row + dir[0];
                    int nextJ = current.col + dir[1];

                    if (isInBounds(nextI, nextJ, rows, cols) && grid[nextI][nextJ] == '.') {
                        grid[nextI][nextJ] = '#'; // Mark as visited
                        componentIds[nextI][nextJ] = currentId;
                        size++;
                        queue.add(new Point(nextI, nextJ));
                    }
                }
            }
            return size;
        }

        /**
         * Calculates (Sum of unique adjacent component sizes + 1) % 10.
         */
        private int calculateAdjacentComponentSum(int r, int c, int rows, int cols, 
                                                 int[][] componentIds, Map<Integer, Integer> componentSizes) {
            Set<Integer> adjacentComponentIds = new HashSet<>();
            int totalSize = 0;

            for (int[] dir : DIRECTIONS) {
                int ni = r + dir[0];
                int nj = c + dir[1];

                if (isInBounds(ni, nj, rows, cols)) {
                    int id = componentIds[ni][nj];
                    // Only consider cells that belong to a valid component (id > 0)
                    if (id > 0 && adjacentComponentIds.add(id)) {
                        totalSize += componentSizes.getOrDefault(id, 0);
                    }
                }
            }
            return (totalSize + 1) % 10;
        }

        private boolean isInBounds(int r, int c, int rows, int cols) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        private static class Point {
            final int row, col;
            Point(int row, int col) {
                this.row = row;
                this.col = col;
            }
        }
    }

    /**
     * Efficient input reader for faster parsing of large datasets.
     */
    public static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

