/**
 * Represents a coordinate in the 2D grid.
 */
record Point(int row, int col) {}

/**
 * Analyzes a grid of characters to find connected components of non-wall cells.
 */
class GridAnalyzer {
    private static final char WALL = '*';
    private static final char PATH = '.';

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final boolean[][] visited;

    // Metadata to track component roots and their sizes
    private final int[][] rootRow;
    private final int[][] rootCol;
    private final int[][] componentSize;

    private final int[] dr = {-1, 1, 0, 0};
    private final int[] dc = {0, 0, -1, 1};

    public GridAnalyzer(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.visited = new boolean[rows][cols];
        this.rootRow = new int[rows][cols];
        this.rootCol = new int[rows][cols];
        this.componentSize = new int[rows][cols];

        // Initialize root pointers with -1
        for (int i = 0; i < rows; i++) {
            Arrays.fill(rootRow[i], -1);
            Arrays.fill(rootCol[i], -1);
        }
    }

    /**
     * Identifies all connected components in the grid.
     */
    public void findComponents() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == PATH && !visited[i][j]) {
                    exploreComponent(i, j);
                }
            }
        }
    }

    /**
     * Performs an iterative DFS to explore a component and mark its cells.
     */
    private void exploreComponent(int startR, int startC) {
        Deque<Point> stack = new ArrayDeque<>();
        stack.push(new Point(startR, startC));
        visited[startR][startC] = true;

        // All cells in this component will point to this root
        rootRow[startR][startC] = startR;
        rootCol[startR][startC] = startC;

        int count = 0;
        List<Point> componentCells = new ArrayList<>();

        while (!stack.isEmpty()) {
            Point curr = stack.pop();
            componentCells.add(curr);
            count++;

            for (int i = 0; i < 4; i++) {
                int nr = curr.row() + dr[i];
                int nc = curr.col() + dc[i];

                if (isValid(nr, nc) && grid[nr][nc] == PATH && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    rootRow[nr][nc] = startR;
                    rootCol[nr][nc] = startC;
                    stack.push(new Point(nr, nc));
                }
            }
        }
        // Store the total size at the root cell
        componentSize[startR][startC] = count;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Calculates the result for a specific cell based on adjacent components.
     */
    public char getCellResult(int r, int c) {
        if (grid[r][c] == WALL) {
            return WALL;
        }

        Set<Point> uniqueRoots = new HashSet<>();
        for (int i = 0; i < 4; i++) {
            int nr = r + dr[i];
            int nc = c + dc[i];

            if (isValid(nr, nc) && grid[nr][nc] == PATH) {
                int rr = rootRow[nr][nc];
                int rc = rootCol[nr][nc];
                if (rr != -1) {
                    uniqueRoots.add(new Point(rr, rc));
                }
            }
        }

        int totalSum = 1;
        for (Point root : uniqueRoots) {
            totalSum += componentSize[root.row()][root.col()];
        }

        // Based on original requirement: return last digit of the sum
        return (char) ((totalSum % 10) + '0');
    }

    public void printResults(PrintWriter out) {
        for (int i = 0; i < rows; i++) {
            StringBuilder sb = new StringBuilder();
            for (int j = 0; j < cols; j++) {
                sb.append(getCellResult(i, j));
            }
            out.println(sb.toString());
        }
    }
}

public class Main {
    public static void main(String[] args) {
        FastReader in = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            String nStr = in.next();
            if (nStr == null) return;

            int rows = Integer.parseInt(nStr);
