/**
 * Handles the core logic of identifying connected components in a grid
 * and calculating values based on adjacent component sizes.
 */
class GridSolver {
    private static final int[] ROW_OFFSETS = {-1, 0, 0, 1};
    private static final int[] COL_OFFSETS = {0, -1, 1, 0};

    private final FastReader reader;
    private int rowCount;
    private int colCount;
    private char[][] grid;
    private int[][] componentIds;
    private int[] componentSizes;

    public GridSolver(FastReader reader) {
        this.reader = reader;
    }

    public void solve(PrintWriter writer) {
        rowCount = reader.nextInt();
        colCount = reader.nextInt();
        grid = new char[rowCount][colCount];

        for (int i = 0; i < rowCount; i++) {
            grid[i] = reader.next().toCharArray();
        }

        identifyComponents();
        calculateAndPrintResult(writer);
    }

    /**
     * Uses BFS to find all connected components of '.' cells.
     */
    private void identifyComponents() {
        componentIds = new int[rowCount][colCount];
        componentSizes = new int[rowCount * colCount + 1];
        int currentComponentId = 1;

        for (int i = 0; i < rowCount; i++) {
            for (int j = 0; j < colCount; j++) {
                if (grid[i][j] == '.' && componentIds[i][j] == 0) {
                    bfs(i, j, currentComponentId);
                    currentComponentId++;
                }
            }
        }
    }

    private void bfs(int startR, int startC, int id) {
        Queue<int[]> queue = new LinkedList<>();
        queue.add(new int[]{startR, startC});
        componentIds[startR][startC] = id;
        int size = 0;

        while (!queue.isEmpty()) {
            int[] cell = queue.poll();
            int r = cell[0];
            int c = cell[1];
            size++;

            for (int k = 0; k < 4; k++) {
                int nr = r + ROW_OFFSETS[k];
                int nc = c + COL_OFFSETS[k];

                if (isValid(nr, nc) && grid[nr][nc] == '.' && componentIds[nr][nc] == 0) {
                    componentIds[nr][nc] = id;
                    queue.add(new int[]{nr, nc});
                }
            }
        }
        componentSizes[id] = size;
    }

    /**
     * Computes the result grid and writes it to the output stream.
     */
    private void calculateAndPrintResult(PrintWriter writer) {
        for (int i = 0; i < rowCount; i++) {
            StringBuilder rowResult = new StringBuilder();
            for (int j = 0; j < colCount; j++) {
                if (grid[i][j] == '.') {
                    rowResult.append('.');
                } else {
                    rowResult.append(calculateCellValue(i, j));
                }
            }
            writer.println(rowResult.toString());
        }
    }

    /**
     * Calculates the value for a non-'.' cell based on the sizes of adjacent '.' components.
     */
    private char calculateCellValue(int r, int c) {
        int sum = 1;
        // Using a small array instead of a HashSet to avoid heavy object allocation in tight loops
        int[] seenComponentIds = new int[4];
        int uniqueNeighborsCount = 0;

        for (int k = 0; k < 4; k++) {
            int nr = r + ROW_OFFSETS[k];
            int nc = c + COL_OFFSETS[k];

            if (isValid(nr, nc) && grid[nr][nc] == '.') {
                int id = componentIds[nr][nc];

                boolean alreadyCounted = false;
                for (int s = 0; s < uniqueNeighborsCount; s++) {
                    if (seenComponentIds[s] == id) {
                        alreadyCounted = true;
                        break;
                    }
                }

                if (!alreadyCounted) {
                    seenComponentIds[uniqueNeighborsCount++] = id;
                    sum += componentSizes[id];
                }
            }
        }
        return (char) ((sum % 10) + '0');
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rowCount && c >= 0 && c < colCount;
    }
}

