import java.io.*;
import java.util.*;

/**
 * GridComponentSolver analyzes a grid of '.' (empty) and '*' (obstacle) cells.
 * It identifies connected components of '.' cells, calculates their sizes,
 * and replaces '*' cells with a digit representing (1 + sum of unique adjacent component sizes) % 10.
 */
public class GridComponentSolver {

    private int rows;
    private int cols;
    private char[][] grid;
    private int[][] componentIdMap;
    private int[] componentSizes;
    private int componentCount;

    public static void main(String[] args) {
        new GridComponentSolver().run();
    }

    public void run() {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            String line = reader.readLine();
            if (line == null) return;
            StringTokenizer st = new StringTokenizer(line);
            this.rows = Integer.parseInt(st.nextToken());
            this.cols = Integer.parseInt(st.nextToken());

            initializeGrid(reader);
            identifyComponents();
            processGrid(out);

        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            out.close();
        }
    }

    /**
     * Initializes the grid with padding to simplify boundary checks.
     * Padding with '*' ensures we don't go out of bounds.
     */
    private void initializeGrid(FastReader reader) throws IOException {
        // Padding of 2 on each side (top, bottom, left, right)
        grid = new char[rows + 2][cols + 2];
        for (int i = 0; i < rows + 2; i++) {
            Arrays.fill(grid[i], '*');
        }

        for (int i = 1; i <= rows; i++) {
            String rowStr = reader.readLine();
            if (rowStr != null) {
                for (int j = 0; j < cols; j++) {
                    grid[i][j + 1] = rowStr.charAt(j);
                }
            }
        }
        componentIdMap = new int[rows + 2][cols + 2];
        componentSizes = new int[rows * cols + 1];
        componentCount = 0;
    }

    /**
     * Performs a Breadth-First Search to identify all connected components of '.' cells.
     */
    private void identifyComponents() {
        for (int i = 1; i <= rows; i++) {
            for (int j = 1; j <= cols; j++) {
                if (grid[i][j] == '.' && componentIdMap[i][j] == 0) {
                    componentCount++;
                    componentSizes[componentCount] = bfs(i, j, componentCount);
                }
            }
        }
    }

    private int bfs(int startX, int startY, int currentId) {
        int size = 0;
        Queue<int[]> queue = new ArrayDeque<>();

        queue.add(new int[]{startX, startY});
        componentIdMap[startX][startY] = currentId;

        int[] dx = {-1, 1, 0, 0};
        int[] dy = {0, 0, -1, 1};

        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            size++;

            for (int i = 0; i < 4; i++) {
                int nx = curr[0] + dx[i];
                int ny = curr[1] + dy[i];

                if (isValidCell(nx, ny) && grid[nx][ny] == '.' && componentIdMap[nx][ny] == 0) {
                    componentIdMap[nx][ny] = currentId;
                    queue.add(new int[]{nx, ny});
                }
            }
        }
        return size;
    }

    private boolean isValidCell(int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }

    /**
     * Generates the result grid based on the component calculations.
     */
    private void processGrid(PrintWriter out) {
        for (int i = 1; i <= rows; i++) {
            StringBuilder rowOutput = new StringBuilder();
            for (int j = 1; j <= cols; j++) {
                if (grid[i][j] == '.') {
                    rowOutput.append('.');
                } else {
                    rowOutput.append(calculateObstacleValue(i, j));
                }
            }
            out.println(rowOutput.toString());
        }
    }

    /**
     * Calculates the value for an obstacle cell '*' by summing the sizes 
     * of unique adjacent '.' components.
     */
    private char calculateObstacleValue(int r, int c) {
        // comp stores the component IDs of the 4 neighbors. 
        // comp[0] is initialized to 0 to represent non-component/obstacle cells.
        int[] neighborCompIds = new int[5];
        int idx = 1;

        int[] dx = {-1, 1, 0, 0};
        int[] dy = {0, 0, -1, 1};

        for (int i = 0; i < 4; i++) {
            int nr = r + dx[i];
            int nc = c + dy[i];
            if (isValidCell(nr, nc)) {
                neighborCompIds[idx++] = componentIdMap[nr][nc];
            }
        }

        // Sort to easily identify unique IDs
        Arrays.sort(neighborCompIds);

        // Original logic: sum = 1 + sum of sizes of unique non-zero neighbor components
        int sum = 1;
        for (int k = 1; k < neighborCompIds.length; k++) {
            if (neighborCompIds[k] != neighborCompIds[k - 1]) {
                int id = neighborCompIds[k];
                if (id > 0) {
                    sum += componentSizes[id];
                }
            }
        }

        return (char) ('0' + (sum % 10));
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private BufferedReader reader;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String readLine() throws IOException {
            return reader.readLine();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver for the Labyrinth problem.
 * The goal is to identify connected components of '.' cells and calculate 
 * their impact on adjacent '*' cells.
 */
public class TheLabyrinth {

    // Direction vectors for navigating 4-way adjacency (Up, Left, Down, Right)
    private static final int[] ROW_DIRECTIONS = {-1, 0, 1, 0};
    private static final int[] COL_DIRECTIONS = {0, -1, 0, 1};

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int[][] starImpacts;
    private final boolean[][] visited;

    /**
     * Initializes the solver with the provided grid.
     *
     * @param rows Total number of rows in the grid.
     * @param cols Total number of columns in the grid.
     * @param grid The character grid containing '.' and '*'.
     */
    public TheLabyrinth(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.starImpacts = new int[rows][cols];
        this.visited = new boolean[rows][cols];
        initializeStarImpacts();
    }

    /**
     * Sets initial values for star cells. 
     * Per the original logic, each star starts with a base impact of 1.
     */
    private void initializeStarImpacts() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*') {
                    starImpacts[i][j] = 1;
                }
            }
        }
    }

    /**
     * Executes the algorithm to process all connected components of '.' cells.
     */
    public void solve() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                // If we find an unvisited empty cell, it's a new component
                if (grid[i][j] == '.' && !visited[i][j]) {
                    processComponent(i, j);
                }
            }
        }
    }

    /**
     * Uses Breadth-First Search (BFS) to traverse a connected component of '.' cells.
     * Identifies the size of the component and all unique '*' cells adjacent to it.
     */
    private void processComponent(int startRow, int startCol) {
        Queue<Point> queue = new LinkedList<>();
        Set<Point> adjacentStars = new HashSet<>();

        queue.add(new Point(startRow, startCol));
        visited[startRow][startCol] = true;
        int componentSize = 0;

        while (!queue.isEmpty()) {
            Point current = queue.poll();
            componentSize++;

            for (int i = 0; i < 4; i++) {
                int nextRow = current.row + ROW_DIRECTIONS[i];
                int nextCol = current.col + COL_DIRECTIONS[i];

                if (isInBounds(nextRow, nextCol)) {
                    if (grid[nextRow][nextCol] == '.' && !visited[nextRow][nextCol]) {
                        // Part of the same '.' component
                        visited[nextRow][nextCol] = true;
                        queue.add(new Point(nextRow, nextCol));
                    } else if (grid[nextRow][nextCol] == '*') {
                        // A boundary star cell
                        adjacentStars.add(new Point(nextRow, nextCol));
                    }
                }
            }
        }

        // Apply the impact of this component's size to all adjacent unique stars
        for (Point star : adjacentStars) {
            starImpacts[star.row][star.col] += componentSize;
        }
    }

    private boolean isInBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Outputs the transformed grid to the provided PrintWriter.
     */
    public void printResult(PrintWriter out) {
        for (int i = 0; i < rows; i++) {
            StringBuilder sb = new StringBuilder();
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*') {
                    // The requirement specifies the last digit of the impact
                    sb.append(starImpacts[i][j] % 10);
                } else {
                    sb.append('.');
                }
            }
            out.println(sb.toString());
        }
    }

    /**
     * Immutable representation of a 2D coordinate.
     */
    private static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Point)) return false;
            Point point = (Point) o;
            return row == point.row && col == point.col;
        }

        @Override
        public int hashCode() {
            return Objects.hash(row, col);
        }
    }

    public static void main(String[] args) {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(System.out)) {

            String dimensionsLine = br.readLine();
            if (dimensionsLine == null) return;

            String[] dims = dimensionsLine.trim().split("\\s+");
            int r = Integer.parseInt(dims[0]);
            int c = Integer.parseInt(dims[1]);

            char[][] grid = new char[r][c];
            for (int i = 0; i < r; i++) {
                grid[i] = br.readLine().toCharArray();
            }

            TheLabyrinth solver = new TheLabyrinth(r, c, grid);
            solver.solve();
            solver.printResult(out);

        } catch (IOException | NumberFormatException e) {
            System.err.println("Error processing input: " + e.getMessage());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A program that processes a grid to identify connected components of '.' cells
 * and calculates a value for each non-'.' cell based on the sizes of its 
 * adjacent connected components.
 */
public class GridComponentAnalyzer {

    public static void main(String[] args) {
        try {
            FastReader reader = new FastReader(System.in);
            PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

            int rows = reader.nextInt();
            int cols = reader.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            GridProcessor processor = new GridProcessor(grid, rows, cols);
            String result = processor.process();

            out.println(result);
            out.flush();
            out.close();
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Logic for analyzing the grid components and transforming the grid.
     */
    static class GridProcessor {
        private final char[][] grid;
        private final int rows;
        private final int cols;

        private static final int[][] DIRECTIONS = {
            {0, 1}, {0, -1}, {1, 0}, {-1, 0}
        };

        private int[][] componentIds;
        private List<Integer> componentSizes;

        public GridProcessor(char[][] grid, int rows, int cols) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
            this.componentIds = new int[rows][cols];
            this.componentSizes = new ArrayList<>();
        }

        /**
         * Executes the BFS to find connected components and then builds the output string.
         * @return The transformed grid as a String.
         */
        public String process() {
            findConnectedComponents();
            return buildResultString();
        }

        private void findConnectedComponents() {
            int currentComponentId = 0;

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.' && componentIds[i][j] == 0) {
                        currentComponentId++;
                        int size = performBFS(i, j, currentComponentId);
                        componentSizes.add(size);
                    }
                }
            }
        }

        private int performBFS(int startR, int startC, int id) {
            int count = 0;
            Queue<Cell> queue = new LinkedList<>();

            componentIds[startR][startC] = id;
            queue.add(new Cell(startR, startC));
            count++;

            while (!queue.isEmpty()) {
                Cell current = queue.poll();

                for (int[] dir : DIRECTIONS) {
                    int nr = current.r + dir[0];
                    int nc = current.c + dir[1];

                    if (isValidDot(nr, nc) && componentIds[nr][nc] == 0) {
                        componentIds[nr][nc] = id;
                        count++;
                        queue.add(new Cell(nr, nc));
                    }
                }
            }
            return count;
        }

        private String buildResultString() {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.') {
                        sb.append('.');
                    } else {
                        sb.append(calculateNeighborSum(i, j));
                    }
                }
                sb.append('\n');
            }
            return sb.toString();
        }

        private int calculateNeighborSum(int r, int c) {
            Set<Integer> adjacentComponentIds = new HashSet<>();

            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                if (isValidDot(nr, nc)) {
                    adjacentComponentIds.add(componentIds[nr][nc]);
                }
            }

            int totalSize = 0;
            for (int id : adjacentComponentIds) {
                // componentIds are 1-indexed, componentSizes is 0-indexed
                totalSize += componentSizes.get(id - 1);
            }

            return (totalSize + 1) % 10;
        }

        private boolean isValidDot(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] == '.';
        }
    }

    /**
     * Simple representation of a coordinate in the grid.
     */
    private static class Cell {
        final int r, c;

        Cell(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * High-performance reader for parsing input.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }
}

