/**
 * Handles the logic of processing the grid components and calculating new values.
 */
class GridProcessor {
    private static final int[][] DIRECTIONS = {
        {1, 0}, {-1, 0}, {0, 1}, {0, -1}
    };

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int[][] componentMap;
    private final int[] componentSizes;

    public GridProcessor(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.componentMap = new int[rows][cols];
        // componentSizes can at most be rows * cols
        this.componentSizes = new int[rows * cols + 1];
    }

    /**
     * Identifies connected components of '.' and assigns each a unique ID.
     */
    public void labelComponents() {
        int currentComponentId = 1;

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.' && componentMap[i][j] == 0) {
                    int size = performBFS(i, j, currentComponentId);
                    componentSizes[currentComponentId] = size;
                    currentComponentId++;
                }
            }
        }
    }

    /**
     * Uses BFS to label a connected component and return its size.
     */
    private int performBFS(int startRow, int startCol, int componentId) {
        int size = 0;
        Queue<int[]> queue = new LinkedList<>();

        queue.add(new int[]{startRow, startCol});
        componentMap[startRow][startCol] = componentId;
        size++;

        while (!queue.isEmpty()) {
            int[] cell = queue.poll();
            int r = cell[0];
            int c = cell[1];

            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                if (isValid(nr, nc) && grid[nr][nc] == '.' && componentMap[nr][nc] == 0) {
                    componentMap[nr][nc] = componentId;
                    size++;
                    queue.add(new int[]{nr, nc});
                }
            }
        }
        return size;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Transforms '*' cells based on the sizes of adjacent '.' components.
     */
    public void transformCells() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*') {
                    grid[i][j] = calculateNewValue(i, j);
                }
            }
        }
    }

    private char calculateNewValue(int r, int c) {
        Set<Integer> uniqueNeighborComponents = new HashSet<>();

        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            if (isValid(nr, nc) && componentMap[nr][nc] != 0) {
                uniqueNeighborComponents.add(componentMap[nr][nc]);
            }
        }

        long sumOfSizes = 0;
        for (int componentId : uniqueNeighborComponents) {
            sumOfSizes += componentSizes[componentId];
        }

        // The formula: (sum of sizes + 1) mod 10
        int resultDigit = (int) ((sumOfSizes + 1) % 10);
        return (char) (resultDigit + '0');
    }

    public void printGrid() {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < rows; i++) {
            sb.append(new String(grid[i])).append("\n");
        }
        System.out.print(sb.toString());
    }
}

public final class Main {
    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        try {
            String firstLine = reader.next();
            if (firstLine == null) return;

            int rows = Integer.parseInt(firstLine);
            int cols = reader.nextInt();

            char[][] grid = new char[rows][];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.nextCharArray();
            }

            GridProcessor processor = new GridProcessor(rows, cols, grid);
            processor.labelComponents();
            processor.transformCells();
            processor.printGrid();

        } catch (Exception e) {
            // In a real production environment, use a logger
            e.printStackTrace();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
