/**
 * Analyzes a grid to find connected components of '.' cells and
 * calculates the sum of component sizes for adjacent '*' cells.
 */
public class GridAnalyzer {

    /**
     * Represents a coordinate in the grid.
     */
    private record Point(int row, int col) {}

    private static final int[][] DIRECTIONS = {
        {0, 1}, {0, -1}, {1, 0}, {-1, 0}
    };

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int[][] starBoundarySums;
    private final boolean[][] visited;

    public GridAnalyzer(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.starBoundarySums = new int[rows][cols];
        this.visited = new boolean[rows][cols];
    }

    /**
     * Executes the component analysis.
     */
    public void analyze() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                // Start a BFS if we find an unvisited empty cell
                if (grid[r][c] == '.' && !visited[r][c]) {
                    exploreComponent(r, c);
                }
            }
        }
    }

    /**
     * Performs BFS to find the size of a '.' component and identifies adjacent '*' cells.
     */
    private void exploreComponent(int startRow, int startCol) {
        Queue<Point> queue = new ArrayDeque<>();
        Set<Point> boundaryStars = new HashSet<>();

        queue.add(new Point(startRow, startCol));
        visited[startRow][startCol] = true;
        int componentSize = 0;

        while (!queue.isEmpty()) {
            Point current = queue.poll();
            componentSize++;

            for (int[] dir : DIRECTIONS) {
                int nr = current.row() + dir[0];
                int nc = current.col() + dir[1];

                if (isWithinBounds(nr, nc)) {
                    if (grid[nr][nc] == '.') {
                        if (!visited[nr][nc]) {
                            visited[nr][nc] = true;
                            queue.add(new Point(nr, nc));
                        }
                    } else if (grid[nr][nc] == '*') {
                        // Track unique '*' cells adjacent to this component
                        boundaryStars.add(new Point(nr, nc));
                    }
                }
            }
        }

        // Add the component size to the running total for each boundary star
        for (Point star : boundaryStars) {
            starBoundarySums[star.row()][star.col()] += componentSize;
        }
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Returns the transformed grid as a formatted string.
     */
    public String getFormattedResult() {
        StringBuilder sb = new StringBuilder();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    sb.append('.');
                } else {
                    // Apply the formula (sum + 1) mod 10
                    sb.append((starBoundarySums[r][c] + 1) % 10);
                }
            }
            sb.append('\n');
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String firstLine = br.readLine();
            if (firstLine == null) return;

            StringTokenizer st = new StringTokenizer(firstLine);
            int r = Integer.parseInt(st.nextToken());
            int c = Integer.parseInt(st.nextToken());

            char[][] grid = new char[r][c];
            for (int i = 0; i < r; i++) {
                String line = br.readLine();
                if (line != null) {
                    grid[i] = line.toCharArray();
                }
            }

            GridAnalyzer analyzer = new GridAnalyzer(r, c, grid);
            analyzer.analyze();
            System.out.print(analyzer.getFormattedResult());

        } catch (IOException | NumberFormatException e) {
            System.err.println("Error processing input: " + e.getMessage());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Edu5B Refactored
 * 
 * This program calculates the sum of the sizes of all adjacent connected components 
 * of empty cells ('.') for every target cell ('*') in a grid.
 */
public class Edu5B {

    // Direction offsets for traversing 4-way neighbors (Up, Down, Left, Right)
    private static final int[] ROW_OFFSETS = {1, -1, 0, 0};
    private static final int[] COL_OFFSETS = {0, 0, 1, -1};

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            String nStr = reader.next();
            if (nStr == null) return;
            int rows = Integer.parseInt(nStr);
            int cols = reader.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            int[][] starSums = solve(rows, cols, grid);
            printGrid(writer, rows, cols, grid, starSums);

        } catch (Exception e) {
            // In a production environment, use a logger
            e.printStackTrace();
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Processes the grid to calculate component sums for each '*' cell.
     */
    private static int[][] solve(int rows, int cols, char[][] grid) {
        int[][] starSums = new int[rows][cols];
        boolean[][] visited = new boolean[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                // If we find an unvisited empty cell, it's a new component
                if (grid[r][c] == '.' && !visited[r][c]) {
                    processComponent(r, c, rows, cols, grid, visited, starSums);
                }
            }
        }
        return starSums;
    }

    /**
     * Uses BFS to find all cells in a component, calculates its size, 
     * and identifies all unique '*' cells adjacent to it.
     */
    private static void processComponent(int startR, int startC, int rows, int cols, 
                                         char[][] grid, boolean[][] visited, int[][] starSums) {

        Queue<Integer> queue = new ArrayDeque<>();
        Set<Integer> adjacentStarIndices = new HashSet<>();

        // Encode 2D coordinates into a 1D integer: index = r * cols + c
        int startIdx = startR * cols + startC;
        queue.add(startIdx);
        visited[startR][startC] = true;

        int componentSize = 0;

        while (!queue.isEmpty()) {
            int currentPos = queue.poll();
            componentSize++;

            int r = currentPos / cols;
            int c = currentPos % cols;

            for (int i = 0; i < 4; i++) {
                int nr = r + ROW_OFFSETS[i];
                int nc = c + COL_OFFSETS[i];

                if (isValid(nr, nc, rows, cols)) {
                    if (grid[nr][nc] == '.') {
                        if (!visited[nr][nc]) {
                            visited[nr][nc] = true;
                            queue.add(nr * cols + nc);
                        }
                    } else if (grid[nr][nc] == '*') {
                        // Track unique stars adjacent to this component
                        adjacentStarIndices.add(nr * cols + nc);
                    }
                }
            }
        }

        // Add the size of this component to all unique adjacent stars
        for (int starIdx : adjacentStarIndices) {
            int sr = starIdx / cols;
            int sc = starIdx % cols;
            starSums[sr][sc] += componentSize;
        }
    }

    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private static void printGrid(PrintWriter out, int rows, int cols, char[][] grid, int[][] starSums) {
        StringBuilder sb = new StringBuilder();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*') {
                    // The original logic: (sum + 1) % 10
                    sb.append((starSums[r][c] + 1) % 10);
                } else {
                    sb.append('.');
                }
            }
            sb.append('\n');
        }
        out.print(sb.toString());
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * GridProcessor analyzes a grid of '.' and '*' characters.
 * It identifies connected components of '.' and calculates a value for each '*'
 * based on the sizes of its adjacent '.' components.
 */
public class GridProcessor {

    private static final int[] DIRECTION_X = {0, 0, 1, -1};
    private static final int[] DIRECTION_Y = {1, -1, 0, 0};

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int[][] componentMap;
    private final List<Integer> componentSizes;

    public GridProcessor(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.componentMap = new int[rows][cols];
        this.componentSizes = new ArrayList<>();
        // Initialize with a dummy size at index 0 to allow 1-based component IDs
        this.componentSizes.add(0);
    }

    /**
     * Orchestrates the processing of the grid.
     */
    public void processAndPrint() throws IOException {
        findConnectedComponents();
        printResult();
    }

    /**
     * Uses BFS to find all connected components of '.' and assigns each a unique ID.
     */
    private void findConnectedComponents() {
        boolean[][] visited = new boolean[rows][cols];
        int currentComponentId = 1;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && !visited[r][c]) {
                    int size = performBFS(r, c, visited, currentComponentId);
                    componentSizes.add(size);
                    currentComponentId++;
                }
            }
        }
    }

    private int performBFS(int startR, int startC, boolean[][] visited, int id) {
        int size = 0;
        Queue<int[]> queue = new LinkedList<>();

        queue.offer(new int[]{startR, startC});
        visited[startR][startC] = true;
        componentMap[startR][startC] = id;

        while (!queue.isEmpty()) {
            int[] cell = queue.poll();
            int r = cell[0];
            int c = cell[1];
            size++;

            for (int i = 0; i < 4; i++) {
                int nr = r + DIRECTION_X[i];
                int nc = c + DIRECTION_Y[i];

                if (isValidDot(nr, nc, visited)) {
                    visited[nr][nc] = true;
                    componentMap[nr][nc] = id;
                    queue.offer(new int[]{nr, nc});
                }
            }
        }
        return size;
    }

    private boolean isValidDot(int r, int c, boolean[][] visited) {
        return r >= 0 && r < rows && c >= 0 && c < cols 
                && grid[r][c] == '.' && !visited[r][c];
    }

    /**
     * Calculates the values for '*' and prints the final grid.
     */
    private void printResult() throws IOException {
        PrintWriter pw = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        for (int r = 0; r < rows; r++) {
            StringBuilder rowOutput = new StringBuilder();
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    rowOutput.append('.');
                } else {
                    rowOutput.append(calculateAsteriskValue(r, c));
                }
            }
            pw.println(rowOutput.toString());
        }
        pw.flush();
    }

    private int calculateAsteriskValue(int r, int c) {
        Set<Integer> adjacentComponentIds = new HashSet<>();

        for (int i = 0; i < 4; i++) {
            int nr = r + DIRECTION_X[i];
            int nc = c + DIRECTION_Y[i];

            // Check bounds and if the neighbor is a dot
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == '.') {
                int id = componentMap[nr][nc];
                if (id > 0) {
                    adjacentComponentIds.add(id);
                }
            }
        }

        int totalSize = 1; // Starting with 1 as per requirement
        for (int id : adjacentComponentIds) {
            totalSize += componentSizes.get(id);
        }

        return totalSize % 10;
    }

    /**
     * Main entry point.
     */
    public static void main(String[] args) {
        try {
            FastReader sc = new FastReader(System.in);
            int rows = sc.nextInt();
            int cols = sc.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = sc.next().toCharArray();
            }

            GridProcessor processor = new GridProcessor(rows, cols, grid);
            processor.processAndPrint();

        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /**
     * Fast I/O utility for reading large inputs.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * Solves the Labyrinth problem by calculating a digit for each wall '#' 
 * based on the sizes of adjacent path components '.'.
 */
public class LabyrinthSolver {

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final DisjointSetUnion dsu;

    public LabyrinthSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.dsu = new DisjointSetUnion(rows * cols);
    }

    /**
     * Core logic to process the grid and return the resulting labyrinth.
     */
    public void solve() {
        initializeComponents();
        printResult();
    }

    /**
     * Scans the grid and unions adjacent path cells ('.') into components.
     */
    private void initializeComponents() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    // Check right neighbor
                    if (c + 1 < cols && grid[r][c + 1] == '.') {
                        dsu.union(getIndex(r, c), getIndex(r, c + 1));
                    }
                    // Check bottom neighbor
                    if (r + 1 < rows && grid[r + 1][c] == '.') {
                        dsu.union(getIndex(r, c), getIndex(r + 1, c));
                    }
                }
            }
        }
    }

    /**
     * Prints the grid, replacing '#' with the calculated digit.
     */
    private void printResult() {
        StringBuilder output = new StringBuilder();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    output.append('.');
                } else {
                    output.append(calculateWallDigit(r, c));
                }
            }
            output.append("\n");
        }
        System.out.print(output);
    }

    /**
     * Calculates the digit for a wall cell based on adjacent components.
     */
    private int calculateWallDigit(int r, int c) {
        Set<Integer> uniqueComponentRoots = new HashSet<>();
        int[] dr = {1, 0, -1, 0}; // Down, Right, Up, Left
        int[] dc = {0, 1, 0, -1};

        for (int i = 0; i < 4; i++) {
            int nr = r + dr[i];
            int nc = c + dc[i];

            if (isValid(nr, nc) && grid[nr][nc] == '.') {
                uniqueComponentRoots.add(dsu.find(getIndex(nr, nc)));
            }
        }

        int sumOfSizesMod10 = 0;
        for (int root : uniqueComponentRoots) {
            sumOfSizesMod10 += (dsu.getSize(root) % 10);
        }

        return (sumOfSizesMod10 + 1) % 10;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private int getIndex(int r, int c) {
        return r * cols + c;
    }

    /**
     * Disjoint Set Union (DSU) implementation with path compression and union by size.
     */
    private static class DisjointSetUnion {
        private final int[] parent;
        private final int[] size;

        public DisjointSetUnion(int n) {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        public int find(int i) {
            if (parent[i] == i) {
                return i;
            }
            return parent[i] = find(parent[i]); // Path compression
        }

        public void union(int i, int j) {
            int rootI = find(i);
            int rootJ = find(j);
            if (rootI != rootJ) {
                // Union by size
                if (size[rootI] < size[rootJ]) {
                    parent[rootI] = rootJ;
                    size[rootJ] += size[rootI];
                } else {
                    parent[rootJ] = rootI;
                    size[rootI] += size[rootJ];
                }
            }
        }

        public int getSize(int i) {
            return size[find(i)];
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) return;

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        scanner.nextLine(); // consume newline

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.nextLine();
            grid[i] = line.toCharArray();
        }

        LabyrinthSolver solver = new LabyrinthSolver(rows, cols, grid);
        solver.solve();

        scanner.close();
    }
}

