/**
 * Logic for analyzing the grid and calculating component sums.
 */
class GridAnalyzer {
    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final DisjointSetUnion dsu;

    public GridAnalyzer(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.dsu = new DisjointSetUnion(rows * cols);
        initializeComponents();
    }

    /**
     * Pre-calculates all connected components of walkable cells ('.').
     */
    private void initializeComponents() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    // Check right neighbor
                    if (c + 1 < cols && grid[r][c + 1] == '.') {
                        dsu.union(r * cols + c, r * cols + (c + 1));
                    }
                    // Check bottom neighbor
                    if (r + 1 < rows && grid[r + 1][c] == '.') {
                        dsu.union(r * cols + c, (r + 1) * cols + c);
                    }
                }
            }
        }
    }

    /**
     * Generates the resulting grid representation.
     */
    public String solve() {
        StringBuilder sb = new StringBuilder();
        int[] dr = {1, -1, 0, 0};
        int[] dc = {0, 0, 1, -1};

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    sb.append('.');
                } else {
                    // It's an obstacle; find unique adjacent component sizes
                    Set<Integer> uniqueComponentRoots = new HashSet<>();
                    for (int i = 0; i < 4; i++) {
                        int nr = r + dr[i];
                        int nc = c + dc[i];

                        if (isValid(nr, nc) && grid[nr][nc] == '.') {
                            uniqueComponentRoots.add(dsu.find(nr * cols + nc));
                        }
                    }

                    int totalAdjacentSize = 1; // Base value as per original requirement
                    for (int root : uniqueComponentRoots) {
                        totalAdjacentSize += dsu.getSize(root);
                    }
                    sb.append(totalAdjacentSize % 10);
                }
            }
            sb.append('\n');
        }
        return sb.toString();
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

