import java.util.*;
import java.io.*;

/**
 * GridAnalyzer processes a grid to identify connected components of '.' cells.
 * For every '*' cell, it calculates a value based on the sum of the sizes 
 * of the unique neighboring '.' components.
 */
public class codeforces {

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int[][] componentIds;
    private final int[] componentSizes;

    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public codeforces(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.componentIds = new int[rows][cols];
        this.componentSizes = new int[rows * cols + 1];
    }

    private static class Point {
        int r, c;
        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    public void solve(PrintWriter out) {
        findComponents();
        printGrid(out);
    }

    private void findComponents() {
        boolean[][] visited = new boolean[rows][cols];
        int currentId = 1;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && !visited[r][c]) {
                    int size = bfs(r, c, visited, currentId);
                    componentSizes[currentId] = size;
                    currentId++;
                }
            }
        }
    }

    private int bfs(int startR, int startC, boolean[][] visited, int id) {
        Queue<Point> queue = new LinkedList<>();
        List<Point> componentMembers = new ArrayList<>();

        queue.add(new Point(startR, startC));
        visited[startR][startC] = true;
        int count = 0;

        while (!queue.isEmpty()) {
            Point curr = queue.poll();
            componentMembers.add(curr);
            componentIds[curr.r][curr.c] = id;
            count++;

            for (int i = 0; i < 4; i++) {
                int nr = curr.r + DR[i];
                int nc = curr.c + DC[i];

                if (isValid(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    queue.add(new Point(nr, nc));
                }
            }
        }
        return count;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private void printGrid(PrintWriter out) {
        StringBuilder sb = new StringBuilder();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    sb.append('.');
                } else {
                    sb.append(calculateStarValue(r, c));
                }
            }
            sb.append('\n');
        }
        out.print(sb.toString());
    }

    private int calculateStarValue(int r, int c) {
        Set<Integer> uniqueNeighborIds = new HashSet<>();
        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];
            if (isValid(nr, nc) && grid[nr][nc] == '.') {
                int id = componentIds[nr][nc];
                if (id > 0) {
                    uniqueNeighborIds.add(id);
                }
            }
        }

        int sumOfSizes = 0;
        for (int id : uniqueNeighborIds) {
            sumOfSizes += componentSizes[id];
        }
        return (sumOfSizes + 1) % 10;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);

        String line = br.readLine();
        if (line == null) return;

        StringTokenizer st = new StringTokenizer(line);
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String row = br.readLine();
            for (int j = 0; j < m; j++) {
                grid[i][j] = row.charAt(j);
            }
        }

        codeforces solver = new codeforces(n, m, grid);
        solver.solve(out);
        out.close();
    }
}

