/**
 * A solver for calculating component-based values in a grid.
 * For every '*' cell, the value is (1 + sum of sizes of adjacent distinct '.' components) % 10.
 */
public class Main {
    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        GridProblemSolver solver = new GridProblemSolver(reader);
        solver.solve();
    }
}

class GridProblemSolver {
    private final FastReader reader;
    private static final int[][] DIRECTIONS = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};

    public GridProblemSolver(FastReader reader) {
        this.reader = reader;
    }

    public void solve() {
        int rows = reader.nextInt();
        int cols = reader.nextInt();
        if (rows <= 0 || cols <= 0) return;

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = reader.next().toCharArray();
        }

        // 1. Build connectivity using Disjoint Set Union (DSU)
        DisjointSetUnion dsu = new DisjointSetUnion(rows * cols);
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    unionNeighbors(r, c, rows, cols, grid, dsu);
                }
            }
        }

        // 2. Process '*' cells based on adjacent component sizes
        StringBuilder output = new StringBuilder();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*') {
                    int resultValue = calculateStarValue(r, c, rows, cols, grid, dsu);
                    grid[r][c] = (char) (resultValue + '0');
                }
                output.append(grid[r][c]);
            }
            output.append('\n');
        }

        System.out.print(output);
    }

    private void unionNeighbors(int r, int c, int rows, int cols, char[][] grid, DisjointSetUnion dsu) {
        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            if (isValid(nr, nc, rows, cols) && grid[nr][nc] == '.') {
                dsu.union(r * cols + c, nr * cols + nc);
            }
        }
    }

    private int calculateStarValue(int r, int c, int rows, int cols, char[][] grid, DisjointSetUnion dsu) {
        Set<Integer> adjacentComponentRoots = new HashSet<>();

        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            if (isValid(nr, nc, rows, cols) && grid[nr][nc] == '.') {
                adjacentComponentRoots.add(dsu.find(nr * cols + nc));
            }
        }

        int sumOfSizes = 1;
        for (int root : adjacentComponentRoots) {
            sumOfSizes += dsu.getSize(root);
        }

        return sumOfSizes % 10;
    }

    private boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

/**
 * Efficient Disjoint Set Union implementation.
 */
class DisjointSetUnion {
    private final int[] parent;
    private final int[] size;

    public DisjointSetUnion(int n) {
        parent = new int[n];
        size = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
            size[i] = 1;
        }
    }

    public int find(int i) {
        if (parent[i] == i) {
            return i;
        }
        return parent[i] = find(parent[i]); // Path compression
    }

    public void union(int i, int j) {
        int rootI = find(i);
        int rootJ = find(j);
        if (rootI != rootJ) {
            // Union by size
            if (size[rootI] < size[rootJ]) {
                parent[rootI] = rootJ;
                size[rootJ] += size[rootI];
            } else {
                parent[rootJ] = rootI;
                size[rootI] += size[rootJ];
            }
        }
    }

    public int getSize(int root) {
        return size[root];
    }
}

