class GridComponentAnalyzer {
    private final int height;
    private final int width;
    private final char[][] grid;

    // Maps each cell coordinate to its component ID. 0 means no component.
    private final int[][] componentIdMap;
    // Stores the size of each component, indexed by component ID.
    private final List<Integer> componentSizes;

    private static final int[][] DIRECTIONS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    public GridComponentAnalyzer(int height, int width, char[][] grid) {
        this.height = height;
        this.width = width;
        this.grid = grid;
        this.componentIdMap = new int[height][width];
        this.componentSizes = new ArrayList<>();
        // Add a dummy entry at index 0 so component IDs can start from 1
        this.componentSizes.add(0);
    }

    /**
     * Identifies all connected components of '.' cells using BFS.
     */
    public void analyze() {
        int nextComponentId = 1;

        for (int r = 0; r < height; r++) {
            for (int c = 0; c < width; c++) {
                // If we find an unvisited empty cell, start a new component search
                if (grid[r][c] == '.' && componentIdMap[r][c] == 0) {
                    int size = bfs(r, c, nextComponentId);
                    componentSizes.add(size);
                    nextComponentId++;
                }
            }
        }
    }

    /**
     * Performs Breadth-First Search to find all cells in a component.
     * 
     * @param startRow Starting row coordinate
     * @param startCol Starting column coordinate
     * @param id The unique ID to assign to this component
     * @return The total number of cells in this component
     */
    private int bfs(int startRow, int startCol, int id) {
        int size = 0;
        Deque<Integer> queue = new ArrayDeque<>();

        // Encode (row, col) into a single integer to save memory/time
        queue.add(startRow * width + startCol);
        componentIdMap[startRow][startCol] = id;
        size++;

        while (!queue.isEmpty()) {
            int pos = queue.poll();
            int r = pos / width;
            int c = pos % width;

            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                if (isValidEmptyCell(nr, nc)) {
                    componentIdMap[nr][nc] = id;
                    queue.add(nr * width + nc);
                    size++;
                }
            }
        }
        return size;
    }

    private boolean isValidEmptyCell(int r, int c) {
        return r >= 0 && r < height && c >= 0 && c < width 
               && grid[r][c] == '.' && componentIdMap[r][c] == 0;
    }

    /**
     * Prints the processed grid to the provided writer.
     */
    public void printResults(PrintWriter writer) {
        StringBuilder output = new StringBuilder();
        for (int r = 0; r < height; r++) {
            output.setLength(0);
            for (int c = 0; c < width; c++) {
                if (grid[r][c] == '.') {
                    output.append('.');
                } else {
                    output.append(calculateObstacleValue(r, c));
                }
            }
            writer.println(output.toString());
        }
    }

    /**
     * Calculates the value for '*' cells based on the sum of the sizes 
     * of adjacent unique components, plus one.
     */
    private int calculateObstacleValue(int r, int c) {
        long sumOfSizes = 1; // The original algorithm starts with k = 1
        Set<Integer> uniqueAdjacentComponentIds = new HashSet<>();

        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            if (nr >= 0 && nr < height && nc >= 0 && nc < width) {
                int id = componentIdMap[nr][nc];
                if (id > 0 && uniqueAdjacentComponentIds.add(id)) {
                    sumOfSizes += componentSizes.get(id);
                }
            }
        }
        return (int) (sumOfSizes % 10);
    }
}

