import java.io.*;
import java.util.*;

/**
 * A utility to process a grid of characters, identifying connected components 
 * of '.' cells and calculating a value for each '*' cell based on the 
 * sizes of adjacent '.' components.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] grid = reader.readGrid(rows, cols);

            GridComponentAnalyzer analyzer = new GridComponentAnalyzer(rows, cols, grid);
            char[][] result = analyzer.process();

            for (char[] row : result) {
                writer.println(new String(row));
            }
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Core logic for analyzing the grid components.
     */
    static class GridComponentAnalyzer {
        private static final int[][] DIRECTIONS = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

        // Constants to represent cell states
        private static final int STATE_STAR = -1;
        private static final int STATE_UNVISITED_DOT = -2;

        private final int rowCount;
        private final int colCount;
        private final char[][] originalGrid;
        private final int[][] componentIdGrid;
        private final Map<Integer, Integer> componentSizeMap;

        public GridComponentAnalyzer(int rows, int cols, char[][] grid) {
            this.rowCount = rows;
            this.colCount = cols;
            this.originalGrid = grid;
            this.componentIdGrid = new int[rows][cols];
            this.componentSizeMap = new HashMap<>();
            initializeComponentGrid();
        }

        private void initializeComponentGrid() {
            for (int i = 0; i < rowCount; i++) {
                for (int j = 0; j < colCount; j++) {
                    componentIdGrid[i][j] = (originalGrid[i][j] == '*') ? STATE_STAR : STATE_UNVISITED_DOT;
                }
            }
        }

        /**
         * Executes the component identification and the star-value calculation.
         * @return The transformed grid.
         */
        public char[][] process() {
            identifyComponents();
            return calculateResultGrid();
        }

        /**
         * Finds all connected components of '.' cells using BFS.
         */
        private void identifyComponents() {
            int currentComponentId = 0;

            for (int r = 0; r < rowCount; r++) {
                for (int c = 0; c < colCount; c++) {
                    if (componentIdGrid[r][c] == STATE_UNVISITED_DOT) {
                        int size = performBFS(r, c, currentComponentId);
                        componentSizeMap.put(currentComponentId, size);
                        currentComponentId++;
                    }
                }
            }
        }

        private int performBFS(int startR, int startC, int id) {
            int size = 0;
            Queue<int[]> queue = new ArrayDeque<>();

            queue.offer(new int[]{startR, startC});
            componentIdGrid[startR][startC] = id;
            size++;

            while (!queue.isEmpty()) {
                int[] current = queue.poll();
                int currR = current[0];
                int currC = current[1];

                for (int[] dir : DIRECTIONS) {
                    int nextR = currR + dir[0];
                    int nextC = currC + dir[1];

                    if (isValid(nextR, nextC) && componentIdGrid[nextR][nextC] == STATE_UNVISITED_DOT) {
                        componentIdGrid[nextR][nextC] = id;
                        size++;
                        queue.offer(new int[]{nextR, nextC});
                    }
                }
            }
            return size;
        }

        /**
         * Calculates the new value for each '*' cell.
         */
        private char[][] calculateResultGrid() {
            char[][] resultGrid = new char[rowCount][colCount];

            for (int r = 0; r < rowCount; r++) {
                for (int c = 0; c < colCount; c++) {
                    if (originalGrid[r][c] == '*') {
                        resultGrid[r][c] = computeStarValue(r, c);
                    } else {
                        resultGrid[r][c] = originalGrid[r][c];
                    }
                }
            }
            return resultGrid;
        }

        private char computeStarValue(int r, int c) {
            Set<Integer> adjacentComponentIds = new HashSet<>();

            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                if (isValid(nr, nc) && componentIdGrid[nr][nc] >= 0) {
                    adjacentComponentIds.add(componentIdGrid[nr][nc]);
                }
            }

            int sumOfAdjacentSizes = 1; // Base value is 1
            for (int id : adjacentComponentIds) {
                sumOfAdjacentSizes += componentSizeMap.getOrDefault(id, 0);
            }

            int finalValue = sumOfAdjacentSizes % 10;
            return (char) ('0' + finalValue);
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rowCount && c >= 0 && c < colCount;
        }
    }

    /**
     * Fast I/O utility for efficient reading.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public char[][] readGrid(int rows, int cols) throws IOException {
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = next().toCharArray();
            }
            return grid;
        }
    }
}

