/**
 * Core logic class that identifies connected components of passable cells 
 * and calculates values for impassable cells.
 */
class GridAnalyzer {
    private static final int[][] DIRECTIONS = {
        {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    private final int rows;
    private final int cols;
    private final boolean[][] passableGrid;
    private final int[][] componentMap;
    private final int[] componentSizes;

    /**
     * Represents a coordinate in the grid.
     */
    private record Point(int r, int c) {}

    public GridAnalyzer(int rows, int cols, char[][] inputGrid) {
        this.rows = rows;
        this.cols = cols;
        this.passableGrid = new boolean[rows][cols];
        this.componentMap = new int[rows][cols];
        this.componentSizes = new int[rows * cols + 1];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                this.passableGrid[i][j] = (inputGrid[i][j] == '.');
            }
        }
    }

    /**
     * Performs BFS to find all connected components of passable cells.
     */
    public void process() {
        int componentIdCounter = 1;

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (passableGrid[i][j] && componentMap[i][j] == 0) {
                    int size = performBfs(i, j, componentIdCounter);
                    componentSizes[componentIdCounter] = size;
                    componentIdCounter++;
                }
            }
        }
    }

    private int performBfs(int startR, int startC, int id) {
        Deque<Point> queue = new ArrayDeque<>();
        queue.add(new Point(startR, startC));
        componentMap[startR][startC] = id;

        int count = 0;

        while (!queue.isEmpty()) {
            Point current = queue.poll();
            count++;

            for (int[] dir : DIRECTIONS) {
                int nr = current.r() + dir[0];
                int nc = current.c() + dir[1];

                if (isValidMove(nr, nc)) {
                    queue.add(new Point(nr, nc));
                    componentMap[nr][nc] = id;
                }
            }
        }
        return count;
    }

    private boolean isValidMove(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols 
               && passableGrid[r][c] && componentMap[r][c] == 0;
    }

    /**
     * Constructs the final output string based on the processed grid.
     */
    public String getFormattedResult() {
        StringBuilder output = new StringBuilder();

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (passableGrid[i][j]) {
                    output.append(".");
                } else {
                    output.append(calculateWallValue(i, j));
                }
            }
            output.append("\n");
        }
        return output.toString();
    }

    private int calculateWallValue(int r, int c) {
        Set<Integer> neighboringComponentIds = new HashSet<>();

        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && passableGrid[nr][nc]) {
                neighboringComponentIds.add(componentMap[nr][nc]);
            }
        }

        int totalAdjacentSize = 1; // Start with 1 to include the wall itself
        for (int id : neighboringComponentIds) {
            totalAdjacentSize += componentSizes[id];
        }

        return totalAdjacentSize % 10;
    }
}

