/**
 * GridAnalyzer processes a grid of '.' and '*' characters.
 * It identifies connected components of '.' cells and calculates a value for each '*' 
 * cell based on the sizes of its adjacent unique '.' components.
 */
public class GridAnalyzer {

    private static final int[][] DIRECTIONS = {
        {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    private final int rowCount;
    private final int columnCount;
    private final String[] grid;
    private final int[][] componentIdGrid;
    private final int[] componentSizes;

    public GridAnalyzer(int rowCount, int columnCount, String[] grid) {
        this.rowCount = rowCount;
        this.columnCount = columnCount;
        this.grid = grid;
        this.componentIdGrid = new int[rowCount][columnCount];
        this.componentSizes = new int[rowCount * columnCount];

        // Initialize componentIdGrid with -1 to signify unvisited cells
        for (int[] row : componentIdGrid) {
            Arrays.fill(row, -1);
        }
    }

    /**
     * Main execution logic to process the grid and output the result.
     */
    public void run(PrintWriter out) {
        identifyComponents();
        generateOutput(out);
    }

    /**
     * Iterates through the grid to find all connected components of '.' cells.
     */
    private void identifyComponents() {
        for (int r = 0; r < rowCount; r++) {
            for (int c = 0; c < columnCount; c++) {
                if (grid[r].charAt(c) == '.' && componentIdGrid[r][c] == -1) {
                    bfsIdentifyComponent(r, c);
                }
            }
        }
    }

    /**
     * Performs a Breadth-First Search to map a connected component.
     * 
     * @param startR Starting row index.
     * @param startC Starting column index.
     */
    private void bfsIdentifyComponent(int startR, int startC) {
        int componentId = startR * columnCount + startC;
        Deque<int[]> queue = new ArrayDeque<>();

        queue.add(new int[]{startR, startC});
        componentIdGrid[startR][startC] = componentId;

        int size = 0;

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int r = current[0];
            int c = current[1];
            size++;

            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                if (isValid(nr, nc) && grid[nr].charAt(nc) == '.' && componentIdGrid[nr][nc] == -1) {
                    componentIdGrid[nr][nc] = componentId;
                    queue.add(new int[]{nr, nc});
                }
            }
        }
        componentSizes[componentId] = size;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rowCount && c >= 0 && c < columnCount;
    }

    /**
     * Calculates and prints the resulting grid based on component sizes.
     */
    private void generateOutput(PrintWriter out) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < rowCount; i++) {
            for (int j = 0; j < columnCount; j++) {
                if (grid[i].charAt(j) == '.') {
                    sb.append('.');
                } else {
                    sb.append(calculateStarValue(i, j));
                }
            }
            sb.append('\n');
        }
        out.print(sb.toString());
    }

    /**
     * Calculates the value for a '*' cell: (1 + sum of sizes of unique adjacent '.' components) % 10.
     */
    private int calculateStarValue(int r, int c) {
        TreeSet<Integer> uniqueComponentIds = new TreeSet<>();

        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            if (isValid(nr, nc) && grid[nr].charAt(nc) == '.') {
                int id = componentIdGrid[nr][nc];
                if (id != -1) {
                    uniqueComponentIds.add(id);
                }
            }
        }

        int totalValue = 1;
        for (int id : uniqueComponentIds) {
            totalValue = (totalValue + componentSizes[id]) % 10;
        }
        return totalValue % 10;
    }

    public static void main(String[] args) throws IOException {
        FastReader in = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = in.nextInt();
        int m = in.nextInt();
        String[] grid = new String[n];
        for (int i = 0; i < n; i++) {
            grid[i] = in.next();
        }

        GridAnalyzer analyzer = new GridAnalyzer(n, m, grid);
        analyzer.run(out);

        out.flush();
        out.close();
        in.close();
    }

    /**
     * Utility class for fast input reading.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
            st = new StringTokenizer("");
        }

        public String next() throws IOException {
            while (!st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public void close() throws IOException {
            br.close();
        }
    }
}

