/**
 * Represents a coordinate in the grid.
 */
record Point(int r, int c) {}

/**
 * Handles the logic of identifying connected components of '.' 
 * and calculating values for '#' cells.
 */
class ComponentAnalyzer {
    private final char[][] grid;
    private final int rows;
    private final int cols;

    private final int[][] componentIds;
    private final Map<Integer, Integer> componentSizes;

    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};
    private static final char DOT = '.';
    private static final char HASH = '#';

    public ComponentAnalyzer(char[][] grid, int rows, int cols) {
        this.grid = grid;
        this.rows = rows;
        this.cols = cols;
        this.componentIds = new int[rows][cols];
        this.componentSizes = new HashMap<>();
    }

    /**
     * Processes the grid to find components and generates the resulting string.
     */
    public String solve() {
        findComponents();
        return buildResult();
    }

    /**
     * Uses BFS to find all connected components of '.' characters.
     */
    private void findComponents() {
        int currentComponentId = 1;
        boolean[][] visited = new boolean[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == DOT && !visited[r][c]) {
                    int size = bfs(r, c, visited, currentComponentId);
                    componentSizes.put(currentComponentId, size);
                    currentComponentId++;
                }
            }
        }
    }

    private int bfs(int startR, int startC, boolean[][] visited, int id) {
        int size = 0;
        Queue<Point> queue = new LinkedList<>();

        queue.add(new Point(startR, startC));
        visited[startR][startC] = true;

        while (!queue.isEmpty()) {
            Point p = queue.poll();
            componentIds[p.r()][p.c()] = id;
            size++;

            for (int i = 0; i < 4; i++) {
                int nr = p.r() + DR[i];
                int nc = p.c() + DC[i];

                if (isValid(nr, nc) && grid[nr][nc] == DOT && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    queue.add(new Point(nr, nc));
                }
            }
        }
        return size;
    }

    /**
     * Constructs the output string based on the component analysis.
     */
    private String buildResult() {
        StringBuilder sb = new StringBuilder();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == DOT) {
                    sb.append(DOT);
                } else {
                    sb.append(calculateHashValue(r, c));
                }
            }
            sb.append("\n");
        }
        return sb.toString();
    }

    private int calculateHashValue(int r, int c) {
        Set<Integer> adjacentComponentIds = new HashSet<>();

        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];
            if (isValid(nr, nc) && grid[nr][nc] == DOT) {
                int id = componentIds[nr][nc];
                if (id != 0) {
                    adjacentComponentIds.add(id);
                }
            }
        }

        int totalNeighboringDots = 1; // The hash itself is not a dot, but the logic adds 1? 
        // Note: The original code logic used: countMembers = 1; and then added component sizes.
        // I will replicate the exact logic: 1 + sum of unique adjacent component sizes.
        for (int id : adjacentComponentIds) {
            totalNeighboringDots += componentSizes.getOrDefault(id, 0);
        }

        return totalNeighboringDots % 10;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

