/**
 * TheLabyrinth calculates the impact of 'walls' (*) on connected 'paths' (.).
 * Each wall's value is determined by the sum of the sizes of its unique adjacent 
 * path components, plus 1, modulo 10.
 */
public class TheLabyrinth {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            String rowsStr = reader.next();
            String colsStr = reader.next();
            if (rowsStr == null || colsStr == null) return;

            int rows = Integer.parseInt(rowsStr);
            int cols = Integer.parseInt(colsStr);

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                if (line != null) {
                    grid[i] = line.toCharArray();
                }
            }

            LabyrinthSolver solver = new LabyrinthSolver(grid, rows, cols);
            solver.solve();
            solver.printGrid(writer);
        } catch (Exception e) {
            // In a production environment, replace with proper logging.
        } finally {
            writer.close();
        }
    }

    /**
     * Encapsulates the logic for solving the labyrinth puzzle.
     */
    static class LabyrinthSolver {
        private final char[][] grid;
        private final int rows;
        private final int cols;
        private final int[][] componentIds;
        private final List<Integer> componentSizes;

        private static final int[] ROW_OFFSETS = {1, -1, 0, 0};
        private static final int[] COL_OFFSETS = {0, 0, 1, -1};

        public LabyrinthSolver(char[][] grid, int rows, int cols) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
            this.componentIds = new int[rows][cols];
            this.componentSizes = new ArrayList<>();

            // Initialize component IDs with -1 (unvisited)
            for (int i = 0; i < rows; i++) {
                Arrays.fill(componentIds[i], -1);
            }
        }

        /**
         * Executes the primary steps of the algorithm.
         */
        public void solve() {
            identifyPathComponents();
            calculateWallValues();
        }

        /**
         * Identifies all connected components of '.' cells using BFS.
         * Iterative BFS is used to avoid StackOverflowError on large inputs.
         */
        private void identifyPathComponents() {
            int currentId = 0;
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.' && componentIds[r][c] == -1) {
                        int size = performBFS(r, c, currentId);
                        componentSizes.add(size);
                        currentId++;
                    }
                }
            }
        }

        private int performBFS(int startR, int startC, int componentId) {
            int size = 0;
            Queue<int[]> queue = new ArrayDeque<>();

            queue.offer(new int[]{startR, startC});
            componentIds[startR][startC] = componentId;

            while (!queue.isEmpty()) {
                int[] current = queue.poll();
                int r = current[0];
                int c = current[1];
                size++;

                for (int i = 0; i < 4; i++) {
                    int nr = r + ROW_OFFSETS[i];
                    int nc = c + COL_OFFSETS[i];

                    if (isInsideGrid(nr, nc) && grid[nr][nc] == '.' && componentIds[nr][nc] == -1) {
                        componentIds[nr][nc] = componentId;
                        queue.offer(new int[]{nr, nc});
                    }
                }
            }
            return size;
        }

        /**
         * Updates every '*' cell with the required sum based on adjacent component sizes.
         */
        private void calculateWallValues() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '*') {
                        updateWallCell(r, c);
                    }
                }
            }
        }

        private void updateWallCell(int r, int c) {
            Set<Integer> adjacentComponentIds = new HashSet<>();
            for (int i = 0; i < 4; i++) {
                int nr = r + ROW_OFFSETS[i];
                int nc = c + COL_OFFSETS[i];

                if (isInsideGrid(nr, nc) && componentIds[nr][nc] != -1) {
                    adjacentComponentIds.add(componentIds[nr][nc]);
                }
            }

            int sumOfAdjacentSizes = 1;
            for (int id : adjacentComponentIds) {
                sumOfAdjacentSizes += componentSizes.get(id);
            }

            // Calculate value modulo 10 and convert to char digit
            grid[r][c] = (char) ((sumOfAdjacentSizes % 10) + '0');
        }

        private boolean isInsideGrid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        public void printGrid(PrintWriter writer) {
            for (int r = 0; r < rows; r++) {
                writer.println(new String(grid[r]));
            }
        }
    }

    /**
     * Fast input reader using BufferedReader and StringTokenizer.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }
    }
}

