class GridAnalyzer {
    private final FastReader reader;
    private int rowCount;
    private int colCount;
    private int[][] componentMap; // Stores component ID for '.' cells, -1 for '#' cells
    private int[] componentSizes;

    private static final int[] DX = {-1, 0, 1, 0};
    private static final int[] DY = {0, 1, 0, -1};

    public GridAnalyzer(FastReader reader) {
        this.reader = reader;
    }

    public void solve(PrintWriter out) throws IOException {
        int[] dimensions = reader.nextIntArray();
        if (dimensions.length < 2) return;

        rowCount = dimensions[0];
        colCount = dimensions[1];
        componentMap = new int[rowCount][colCount];

        // Initialize grid: 0 for '.', -1 for '#'
        for (int i = 0; i < rowCount; i++) {
            String line = reader.readLine();
            for (int j = 0; j < colCount; j++) {
                char c = line.charAt(j);
                componentMap[i][j] = (c == '.') ? 0 : -1;
            }
        }

        // Identify connected components using BFS
        findComponents();

        // Calculate and print the result grid
        processResults(out);
    }

    private void findComponents() {
        // Max possible components is (N*M)/2
        componentSizes = new int[rowCount * colCount + 1];
        int nextComponentId = 1;

        for (int i = 0; i < rowCount; i++) {
            for (int j = 0; j < colCount; j++) {
                if (componentMap[i][j] == 0) {
                    int size = performBFS(i, j, nextComponentId);
                    componentSizes[nextComponentId] = size;
                    nextComponentId++;
                }
            }
        }
    }

    private int performBFS(int startX, int startY, int componentId) {
        int size = 0;
        Queue<int[]> queue = new ArrayDeque<>();

        queue.add(new int[]{startX, startY});
        componentMap[startX][startY] = componentId;
        size++;

        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            int x = curr[0];
            int y = curr[1];

            for (int k = 0; k < 4; k++) {
                int nx = x + DX[k];
                int ny = y + DY[k];

                if (isWithinBounds(nx, ny) && componentMap[nx][ny] == 0) {
                    componentMap[nx][ny] = componentId;
                    queue.add(new int[]{nx, ny});
                    size++;
                }
            }
        }
        return size;
    }

    private void processResults(PrintWriter out) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < rowCount; i++) {
            sb.setLength(0);
            for (int j = 0; j < colCount; j++) {
                if (componentMap[i][j] != -1) {
                    // It's a '.' cell
                    sb.append('.');
                } else {
                    // It's a '#' cell: calculate sum of adjacent unique component sizes
                    sb.append(calculateHashValue(i, j) % 10);
                }
            }
            out.println(sb.toString());
        }
    }

    private int calculateHashValue(int r, int c) {
        Set<Integer> adjacentComponentIds = new HashSet<>();
        for (int k = 0; k < 4; k++) {
            int nr = r + DX[k];
            int nc = c + DY[k];

            if (isWithinBounds(nr, nc) && componentMap[nr][nc] > 0) {
                adjacentComponentIds.add(componentMap[nr][nc]);
            }
        }

        int totalSize = 1; // The '#' cell itself counts as 1
        for (int id : adjacentComponentIds) {
            totalSize += componentSizes[id];
        }
        return totalSize;
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rowCount && c >= 0 && c < colCount;
    }
}

/**
 * Optimized reader for fast input processing.
 */
class FastReader {
    private final BufferedReader br;
    private StringTokenizer st;

    public FastReader(InputStream in) {
        br = new BufferedReader(new InputStreamReader(in));
    }

    public String readLine() throws IOException {
        return br.readLine();
    }

    public int[] nextIntArray() throws IOException {
        String line = br.readLine();
        if (line == null || line.isEmpty()) return new int[0];
        String[] parts = line.trim().split("\\s+");
        int[] result = new int[parts.length];
        for (int i = 0; i < parts.length; i++) {
            result[i] = Integer.parseInt(parts[i]);
        }
        return result;
    }
}

