import java.util.*;

/**
 * GridComponentProcessor processes a grid where '.' represents empty spaces
 * and other characters represent obstacles. It identifies connected components 
 * of empty spaces and calculates a value for each obstacle based on the 
 * sizes of its adjacent empty space components.
 */
public class GridComponentProcessor {

    public static void main(String[] args) {
        try (FastReader sc = new FastReader(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            // Read grid dimensions
            String firstLine = sc.next();
            if (firstLine == null) return;
            int n = Integer.parseInt(firstLine);
            int m = sc.nextInt();

            // Read grid data
            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                grid[i] = sc.next().toCharArray();
            }

            // Execute analysis
            GridAnalyzer analyzer = new GridAnalyzer(grid, n, m);
            analyzer.process();

            // Output result
            analyzer.printGrid(out);
            out.flush();

        } catch (IOException | NumberFormatException e) {
            System.err.println("Error processing grid: " + e.getMessage());
        }
    }

    /**
     * Handles the core logic of identifying components and calculating values.
     */
    static class GridAnalyzer {
        private final char[][] grid;
        private final int rows;
        private final int cols;

        private static final int[] ROW_DIRECTIONS = {0, 1, 0, -1};
        private static final int[] COL_DIRECTIONS = {1, 0, -1, 0};

        public GridAnalyzer(char[][] grid, int rows, int cols) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
        }

        /**
         * Performs the two-pass processing: 
         * 1. Identify component sizes for '.' cells.
         * 2. Update non-'.' cells.
         */
        public void process() {
            int[][] componentIdMap = new int[rows][cols];
            for (int[] row : componentIdMap) {
                Arrays.fill(row, -1);
            }
            List<Integer> componentSizes = new ArrayList<>();

            // Pass 1: Find connected components of '.' cells using BFS
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.' && componentIdMap[r][c] == -1) {
                        int currentId = componentSizes.size();
                        int size = performBFS(r, c, currentId, componentIdMap);
                        componentSizes.add(size);
                    }
                }
            }

            // Pass 2: Calculate values for obstacle cells
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] != '.') {
                        grid[r][c] = calculateObstacleValue(r, c, componentIdMap, componentSizes);
                    }
                }
            }
        }

        private int performBFS(int startR, int startC, int id, int[][] componentIdMap) {
            int size = 0;
            ArrayDeque<Integer> queue = new ArrayDeque<>();

            // Encode 2D coordinates into a 1D integer to save object allocation
            queue.add(startR * cols + startC);
            componentIdMap[startR][startC] = id;

            while (!queue.isEmpty()) {
                int pos = queue.poll();
                int r = pos / cols;
                int c = pos % cols;
                size++;

                for (int i = 0; i < 4; i++) {
                    int nr = r + ROW_DIRECTIONS[i];
                    int nc = c + COL_DIRECTIONS[i];

                    if (isValid(nr, nc) && grid[nr][nc] == '.' && componentIdMap[nr][nc] == -1) {
                        componentIdMap[nr][nc] = id;
                        queue.add(nr * cols + nc);
                    }
                }
            }
            return size;
        }

        private char calculateObstacleValue(int r, int c, int[][] componentIdMap, List<Integer> componentSizes) {
            int totalValue = 1;
            Set<Integer> seenComponents = new HashSet<>();

            for (int i = 0; i < 4; i++) {
                int nr = r + ROW_DIRECTIONS[i];
                int nc = c + COL_DIRECTIONS[i];

                if (isValid(nr, nc) && grid[nr][nc] == '.') {
                    int compId = componentIdMap[nr][nc];
                    // Ensure we only count each unique adjacent component once
                    if (seenComponents.add(compId)) {
                        totalValue = (totalValue + componentSizes.get(compId)) % 10;
                    }
                }
            }
            return (char) ('0' + totalValue);
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        public void printGrid(PrintWriter out) {
            for (char[] row : grid) {
                out.println(new String(row));
            }
        }
    }

    /**
     * Fast I/O utility for reading input efficiently.
     */
    static class FastReader implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        @Override
        public void close() throws IOException {
            reader.close();
        }
    }
}

import java.util.*;
