/**
 * A solution to process a grid of '.' and '*' characters.
 * Components of '.' are identified, and for each '*', a value is calculated
 * based on the sum of the sizes of unique adjacent '.' components.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            GridSolver solver = new GridSolver(rows, cols, grid);
            System.out.print(solver.solve());

        } catch (IOException | NoSuchElementException e) {
            // In a real-world scenario, use a logger.
        }
    }

    /**
     * Handles the core logic of the grid processing.
     */
    static class GridSolver {
        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final int[][] componentIds;
        private final int[] componentSizes;

        public GridSolver(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            this.componentIds = new int[rows][cols];
            // Max possible components is (rows * cols) / 2
            this.componentSizes = new int[rows * cols + 1];
        }

        /**
         * Orchestrates the component identification and result calculation.
         * @return The formatted result string.
         */
        public String solve() {
            identifyComponents();

            StringBuilder result = new StringBuilder();
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.') {
                        result.append('.');
                    } else {
                        result.append(calculateStarValue(r, c));
                    }
                }
                result.append("\n");
            }
            return result.toString();
        }

        /**
         * Uses BFS to find connected components of '.' cells and assign IDs.
         */
        private void identifyComponents() {
            int currentId = 1;
            int[] dr = {-1, 1, 0, 0};
            int[] dc = {0, 0, -1, 1};

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.' && componentIds[r][c] == 0) {
                        int size = performBFS(r, c, currentId, dr, dc);
                        componentSizes[currentId] = size;
                        currentId++;
                    }
                }
            }
        }

        private int performBFS(int startR, int startC, int id, int[] dr, int[] dc) {
            int size = 0;
            Deque<int[]> queue = new ArrayDeque<>();

            queue.add(new int[]{startR, startC});
            componentIds[startR][startC] = id;

            while (!queue.isEmpty()) {
                int[] curr = queue.poll();
                int r = curr[0];
                int c = curr[1];
                size++;

                for (int i = 0; i < 4; i++) {
                    int nr = r + dr[i];
                    int nc = c + dc[i];

                    if (isValid(nr, nc) && grid[nr][nc] == '.' && componentIds[nr][nc] == 0) {
                        componentIds[nr][nc] = id;
                        queue.add(new int[]{nr, nc});
                    }
                }
            }
            return size;
        }

        /**
         * Calculates the value for a '*' cell based on adjacent components.
         */
        private char calculateStarValue(int r, int c) {
            int sumOfNeighboringComponentSizes = 0;
            int[] neighborIds = new int[4];
            int uniqueCount = 0;

            int[] dr = {-1, 1, 0, 0};
            int[] dc = {0, 0, -1, 1};

            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i];
                int nc = c + dc[i];

                if (isValid(nr, nc)) {
                    int id = componentIds[nr][nc];
                    // Only process components (id > 0) and skip duplicates
                    if (id > 0 && !isAlreadySeen(id, neighborIds, uniqueCount)) {
                        neighborIds[uniqueCount++] = id;
                        sumOfNeighboringComponentSizes += componentSizes[id];
                    }
                }
            }

            int finalValue = (sumOfNeighboringComponentSizes + 1) % 10;
            return (char) (finalValue + '0');
        }

        private boolean isAlreadySeen(int id, int[] seenIds, int count) {
            for (int i = 0; i < count; i++) {
                if (seenIds[i] == id) return true;
            }
            return false;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * Fast I/O utility for reading large inputs.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.HashSet;
import java.util.Set;
import java.util.StringTokenizer;

/**
 * LabyrinthSolver solves the grid problem by identifying connected components of path cells
 * and calculating a value for each wall cell based on the sizes of adjacent path components.
 */
public class LabyrinthSolver {

    private static final int[][] DIRECTIONS = {
        {1, 0}, {-1, 0}, {0, 1}, {0, -1}
    };

    private final int rows;
    private final int cols;
    private final boolean[][] isWall;
    private final int[][] componentIds;
    private final int[] componentSizes;

    public LabyrinthSolver(int rows, int cols, boolean[][] isWall) {
        this.rows = rows;
        this.cols = cols;
        this.isWall = isWall;
        this.componentIds = new int[rows][cols];
        // The maximum number of components possible is rows * cols
        this.componentSizes = new int[rows * cols + 1];
    }

    /**
     * Scans the grid to identify all path components and their sizes.
     */
    public void computeComponents() {
        int currentComponentId = 1;

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (isWall[i][j]) {
                    componentIds[i][j] = -1; // Mark walls
                } else if (componentIds[i][j] == 0) {
                    // Found an unvisited path cell
                    int size = floodFill(i, j, currentComponentId);
                    componentSizes[currentComponentId] = size;
                    currentComponentId++;
                }
            }
        }
    }

    /**
     * Iterative BFS to find all connected path cells for a component.
     */
    private int floodFill(int startR, int startC, int componentId) {
        int size = 0;
        Deque<int[]> queue = new ArrayDeque<>();

        queue.add(new int[]{startR, startC});
        componentIds[startR][startC] = componentId;

        while (!queue.isEmpty()) {
            int[] cell = queue.poll();
            int r = cell[0];
            int c = cell[1];
            size++;

            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                if (isValidPath(nr, nc)) {
                    componentIds[nr][nc] = componentId;
                    queue.add(new int[]{nr, nc});
                }
            }
        }
        return size;
    }

    private boolean isValidPath(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols 
               && !isWall[r][c] && componentIds[r][c] == 0;
    }

    /**
     * Generates the output grid as a single string.
     */
    public String getResultString() {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (!isWall[i][j]) {
                    sb.append('.');
                } else {
                    sb.append(calculateWallValue(i, j));
                }
            }
            sb.append('\n');
        }
        return sb.toString();
    }

    /**
     * Calculates the sum of sizes of unique adjacent path components modulo 10.
     * Note: The original logic initialized the sum to 1.
     */
    private int calculateWallValue(int r, int c) {
        Set<Integer> adjacentComponentIds = new HashSet<>();

        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
                int id = componentIds[nr][nc];
                // Only consider IDs belonging to path components (id > 0)
                if (id > 0) {
                    adjacentComponentIds.add(id);
                }
            }
        }

        int sum = 1; 
        for (int id : adjacentComponentIds) {
            sum = (sum + componentSizes[id]) % 10;
        }
        return sum;
    }

    public static void main(String[] args) {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(System.out)) {

            String header = br.readLine();
            if (header == null) return;

            StringTokenizer st = new StringTokenizer(header);
            int n = Integer.parseInt(st.nextToken());
            int m = Integer.parseInt(st.nextToken());

            boolean[][] isWall = new boolean[n][m];
            for (int i = 0; i < n; i++) {
                String rowLine = br.readLine();
                for (int j = 0; j < m; j++) {
                    if (rowLine.charAt(j) == '*') {
                        isWall[i][j] = true;
                    }
                }
            }

            LabyrinthSolver solver = new LabyrinthSolver(n, m, isWall);
            solver.computeComponents();
            out.print(solver.getResultString());
            out.flush();

        } catch (IOException | NumberFormatException e) {
            e.printStackTrace();
        }
    }
}

import java.util.*;
