/**
 * A program that processes a grid of '.' and '*' characters.
 * It identifies connected components of '.' cells and, for every '*' cell,
 * calculates (1 + sum of the sizes of all unique adjacent '.' components) % 10.
 */
public class Main {
    public static void main(String[] args) {
        try {
            FastReader reader = new FastReader(System.in);
            int n = reader.nextInt();
            int m = reader.nextInt();

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                grid[i] = reader.readLine().toCharArray();
            }

            GridSolver solver = new GridSolver(grid);
            String result = solver.solve();
            System.out.print(result);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /**
     * Helper class for fast I/O operations.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String readLine() throws IOException {
