        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
            return tokenizer.nextToken();
        }
    }

    /**
     * Logic for processing the grid and calculating the component-based values.
     */
    static class GridSolver {
        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final int[][] componentId;
        private final int[] componentSizes;

        private int currentComponentId = 0;

        // Direction vectors for traversing neighbors (Up, Down, Left, Right)
        private static final int[] DR = {-1, 1, 0, 0};
        private static final int[] DC = {0, 0, -1, 1};

        public GridSolver(char[][] grid) {
            this.grid = grid;
            this.rows = grid.length;
            this.cols = grid[0].length;
            this.componentId = new int[rows][cols];
            // Max possible components is half the total cells in a checkerboard pattern
            this.componentSizes = new int[rows * cols + 1];
        }

        /**
         * Orchestrates the component identification and result generation.
         * @return A string representing the processed grid.
         */
        public String solve() {
            findComponents();

            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '*') {
                        sb.append(calculateStarValue(i, j));
                    } else {
                        sb.append('.');
                    }
                }
                sb.append('\n');
            }
            return sb.toString();
        }

        /**
         * Scans the grid to find all connected components of '.' cells using BFS.
         */
        private void findComponents() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.' && componentId[i][j] == 0) {
                        currentComponentId++;
                        int size = bfs(i, j, currentComponentId);
                        componentSizes[currentComponentId] = size;
                    }
                }
            }
        }

        /**
         * BFS to explore a single connected component.
         */
        private int bfs(int startR, int startC, int id) {
            int size = 0;
            Deque<int[]> queue = new ArrayDeque<>();

            queue.offer(new int[]{startR, startC});
            componentId[startR][startC] = id;

            while (!queue.isEmpty()) {
                int[] curr = queue.poll();
                int r = curr[0];
                int c = curr[1];
                size++;

                for (int i = 0; i < 4; i++) {
                    int nr = r + DR[i];
                    int nc = c + DC[i];

                    if (isValid(nr, nc) && grid[nr][nc] == '.' && componentId[nr][nc] == 0) {
                        componentId[nr][nc] = id;
                        queue.offer(new int[]{nr, nc});
                    }
                }
            }
            return size;
        }

        /**
         * Calculates the value for a '*' cell based on adjacent components.
         */
        private int calculateStarValue(int r, int c) {
            int totalAdjacentSize = 0;
            Set<Integer> seenIds = new HashSet<>();

            for (int i = 0; i < 4; i++) {
                int nr = r + DR[i];
                int nc = c + DC[i];

                if (isValid(nr, nc) && grid[nr][nc] == '.') {
                    int id = componentId[nr][nc];
                    // Only add the size if we haven't counted this component for this star yet
                    if (!seenIds.contains(id)) {
                        totalAdjacentSize += componentSizes[id];
                        seenIds.add(id);
                    }
                }
            }

            return (1 + totalAdjacentSize) % 10;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * GridComponentSolver identifies connected components of empty cells ('.') in a grid
 * and calculates a value for each obstacle ('*') based on the sizes of adjacent 
 * unique components.
 */
public class GridComponentSolver {

    private static final char EMPTY = '.';
    private static final char OBSTACLE = '*';

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int[][] componentIds;
    private final int[] componentSizes;

    public GridComponentSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.componentIds = new int[rows][cols];
        // Max possible components is (rows * cols) / 2 + 1
        this.componentSizes = new int[(rows * cols) / 2 + 2];
    }

    /**
     * Executes the core logic: identifying components and calculating results.
     */
    public void solve(PrintWriter out) {
        identifyComponents();
        processGrid(out);
    }

    /**
     * Iterates through the grid to find unvisited empty cells and triggers BFS 
     * to map out connected components.
     */
    private void identifyComponents() {
        int currentComponentId = 1;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == EMPTY && componentIds[r][c] == 0) {
                    bfs(r, c, currentComponentId);
                    currentComponentId++;
                }
            }
        }
    }

    /**
     * Iterative BFS to avoid StackOverflowError on large grids.
     */
    private void bfs(int startR, int startC, int id) {
        Deque<int[]> queue = new ArrayDeque<>();
        queue.add(new int[]{startR, startC});
        componentIds[startR][startC] = id;

        int size = 0;
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            int r = curr[0];
            int c = curr[1];
            size++;

            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i];
                int nc = c + dc[i];

                if (isValid(nr, nc) && grid[nr][nc] == EMPTY && componentIds[nr][nc] == 0) {
                    componentIds[nr][nc] = id;
                    queue.add(new int[]{nr, nc});
                }
            }
        }
        componentSizes[id] = size;
    }

    /**
     * Iterates through the grid to print '.' for empty cells and the computed 
     * value for obstacle cells.
     */
    private void processGrid(PrintWriter out) {
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == OBSTACLE) {
                    out.print(calculateObstacleValue(r, c, dr, dc));
                } else {
                    out.print(EMPTY);
                }
            }
            out.println();
        }
    }

    private int calculateObstacleValue(int r, int c, int[] dr, int[] dc) {
        Set<Integer> adjacentComponentIds = new HashSet<>();
        for (int i = 0; i < 4; i++) {
            int nr = r + dr[i];
            int nc = c + dc[i];
            if (isValid(nr, nc) && componentIds[nr][nc] > 0) {
                adjacentComponentIds.add(componentIds[nr][nc]);
            }
        }

        int sumOfSizes = 1; // Base value per original logic
        for (int id : adjacentComponentIds) {
            sumOfSizes += componentSizes[id];
        }

        return sumOfSizes % 10;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    public static void main(String[] args) {
        FastReader sc = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = sc.nextInt();
            int m = sc.nextInt();
            char[][] grid = new char[n][m];

            for (int i = 0; i < n; i++) {
                String line = sc.next();
                for (int j = 0; j < m; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }

            GridComponentSolver solver = new GridComponentSolver(n, m, grid);
            solver.solve(out);
        } catch (Exception e) {
            // Handle or log exception
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

