/**
 * A program that processes a grid of cells. 
 * It identifies connected components of empty cells and calculates a 
 * numeric value for obstacle cells based on the sizes of adjacent empty components.
 */
public class GridExpansionSolver {

    private static final char EMPTY_CELL = '.';
    private static final char OBSTACLE_CELL = '*';

    private static final int[][] DIRECTIONS = {
        {1, 0}, {-1, 0}, {0, -1}, {0, 1}
    };

    public static void main(String[] args) {
        try (InputReader reader = new InputReader(System.in);
             PrintWriter writer = new PrintWriter(System.out)) {

            int rows = reader.nextInt();
            int cols = reader.nextInt();
