    /**
     * Handles the core logic of finding connected components and calculating grid values.
     */
    private static class GridProcessor {
        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final int[][] componentIdGrid;
        private final Map<Integer, Integer> componentSizes;
        private int nextComponentId = 1;

        public GridProcessor(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            this.componentIdGrid = new int[rows][cols];
            this.componentSizes = new HashMap<>();
        }

        /**
         * Performs BFS to find all connected components of EMPTY_CELLs.
         */
        public void identifyComponents() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == EMPTY_CELL && componentIdGrid[r][c] == 0) {
                        bfsAssignComponent(r, c);
                    }
                }
            }
        }

        private void bfsAssignComponent(int startR, int startC) {
            int currentId = nextComponentId++;
            int size = 0;
            Queue<Point> queue = new LinkedList<>();

            componentIdGrid[startR][startC] = currentId;
            queue.offer(new Point(startR, startC));
            size++;

            while (!queue.isEmpty()) {
                Point current = queue.poll();

                for (int[] dir : DIRECTIONS) {
                    int nr = current.row + dir[0];
                    int nc = current.col + dir[1];

                    if (isValidEmptyCell(nr, nc)) {
                        componentIdGrid[nr][nc] = currentId;
                        size++;
                        queue.offer(new Point(nr, nc));
                    }
                }
            }
            componentSizes.put(currentId, size);
        }

        private boolean isValidEmptyCell(int r, int c) {
            return r >= 0 && r < rows && 
                   c >= 0 && c < cols && 
                   grid[r][c] == EMPTY_CELL && 
                   componentIdGrid[r][c] == 0;
        }

        /**
         * Generates the output grid based on the calculated component sizes.
         */
        public void printResult(PrintWriter writer) {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == EMPTY_CELL) {
                        writer.print(EMPTY_CELL);
                    } else {
                        writer.print(calculateObstacleValue(r, c));
                    }
                }
                writer.println();
            }
        }

        private int calculateObstacleValue(int r, int c) {
            Set<Integer> adjacentComponentIds = new HashSet<>();
            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
                    if (grid[nr][nc] == EMPTY_CELL) {
                        adjacentComponentIds.add(componentIdGrid[nr][nc]);
                    }
                }
            }

            int totalSize = 1;
            for (int id : adjacentComponentIds) {
                totalSize += componentSizes.getOrDefault(id, 0);
            }
            return totalSize % 10;
        }
    }

    /**
     * Represents a single coordinate in the grid.
     */
    private static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Utility class for fast input reading.
     */
    private static class InputReader implements AutoCloseable {
        private final BufferedReader reader;
        private String[] tokens;
        private int nextIndex;

        public InputReader(InputStream is) {
            this.reader = new BufferedReader(new InputStreamReader(is));
        }

        public String next() throws IOException {
            while (tokens == null || nextIndex >= tokens.length) {
                String line = reader.readLine();
                if (line == null) return null;
                tokens = line.trim().split("\\s+");
                nextIndex = 0;
            }
            return tokens[nextIndex++];
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        @Override
        public void close() throws IOException {
            reader.close();
        }
    }
}

