/**
 * Handles the core logic of identifying connected components in the grid
 * and calculating the neighbor-based values for obstacles.
 */
class GridSolver {
    private final FastReader reader;
    private final int[] DX = {-1, 0, 1, 0};
    private final int[] DY = {0, -1, 0, 1};

    private int rows;
    private int cols;
    private boolean[][] isObstacle;
    private int[][] componentIds;
    private int[] componentSizes;

    public GridSolver(FastReader reader) {
        this.reader = reader;
    }

    public void solve() throws IOException {
        rows = reader.nextInt();
        cols = reader.nextInt();

        if (rows <= 0 || cols <= 0) return;

        isObstacle = new boolean[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = reader.next();
            for (int j = 0; j < cols; j++) {
                if (line.charAt(j) == '*') {
                    isObstacle[i][j] = true;
                }
            }
        }

        // 1. Identify connected components of '.' (empty cells)
        identifyComponents();

        // 2. Process obstacles and build the output grid
        StringBuilder output = new StringBuilder();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (isObstacle[i][j]) {
                    output.append(calculateObstacleValue(i, j));
                } else {
                    output.append('.');
                }
            }
            output.append('\n');
        }

        System.out.print(output.toString());
    }

    /**
     * Uses BFS to find all connected components of empty cells ('.').
     */
    private void identifyComponents() {
        componentIds = new int[rows][cols];
        // Maximum possible components is rows * cols
        componentSizes = new int[rows * cols + 1];
        int currentComponentId = 1;

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (!isObstacle[i][j] && componentIds[i][j] == 0) {
                    int size = bfs(i, j, currentComponentId);
                    componentSizes[currentComponentId] = size;
                    currentComponentId++;
                }
            }
        }
    }

    /**
     * Iterative BFS to avoid StackOverflowError on large components.
     */
    private int bfs(int startR, int startC, int id) {
        int size = 0;
        Queue<int[]> queue = new ArrayDeque<>();

        queue.add(new int[]{startR, startC});
        componentIds[startR][startC] = id;

        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            int r = curr[0];
            int c = curr[1];
            size++;

            for (int i = 0; i < 4; i++) {
                int nr = r + DX[i];
                int nc = c + DY[i];

                if (isValid(nr, nc) && !isObstacle[nr][nc] && componentIds[nr][nc] == 0) {
                    componentIds[nr][nc] = id;
                    queue.add(new int[]{nr, nc});
                }
            }
        }
        return size;
    }

    /**
     * Calculates the value for an obstacle based on the unique component sizes of adjacent empty cells.
     * Value = (1 + sum of sizes of distinct neighboring components) % 10
     */
    private int calculateObstacleValue(int r, int c) {
        Set<Integer> adjacentComponentIds = new HashSet<>();

        for (int i = 0; i < 4; i++) {
            int nr = r + DX[i];
            int nc = c + DY[i];

            if (isValid(nr, nc)) {
                int id = componentIds[nr][nc];
                if (id > 0) {
                    adjacentComponentIds.add(id);
                }
            }
        }

        int sumOfNeighborSizes = 0;
        for (int id : adjacentComponentIds) {
            sumOfNeighborSizes += componentSizes[id];
        }

        return (1 + sumOfNeighborSizes) % 10;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

/**
 * High-performance input reader.
 */
class FastReader {
    private final InputStream inputStream;
    private final byte[] buffer = new byte[1024];
    private int pointer = 0;
    private int bufferLength = 0;

    public FastReader(InputStream is) {
        this.inputStream = is;
    }

    private byte read() throws IOException {
        if (pointer >= bufferLength) {
            pointer = 0;
            bufferLength = inputStream.read(buffer);
            if (bufferLength <= 0) return -1;
        }
        return buffer[pointer++];
    }

    public String next() throws IOException {
        StringBuilder sb = new StringBuilder();
        byte b = read();
        while (b != -1 && b <= 32) b = read();
        if (b == -1) return "";
        while (b != -1 && b > 32) {
            sb.append((char) b);
            b = read();
        }
        return sb.toString();
    }

    public int nextInt() throws IOException {
        int num = 0;
        byte b = read();
        while (b != -1 && b <= 32) b = read();
        boolean negative = false;
        if (b == '-') {
            negative = true;
            b = read();
        }
        while (b >= '0' && b <= '9') {
            num = num * 10 + (b - '0');
            b = read();
        }
        return negative ? -num : num;
    }
}

