/**
 * Logic for solving the labyrinth grid problem.
 */
class LabyrinthSolver {

    private static final int[][] DIRECTIONS = {
        {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    /**
     * Processes the grid to calculate neighbor counts for '#' cells 
     * based on the sizes of adjacent '.' component groups.
     *
     * @param grid The input character grid.
     * @param out  The PrintWriter to output the resulting grid.
     */
    public void solve(char[][] grid, PrintWriter out) {
        int rows = grid.length;
        int cols = grid[0].length;
        DisjointSetUnion dsu = new DisjointSetUnion(rows * cols);

        // Step 1: Build connected components for all '.' cells
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    // Check top neighbor
                    if (r > 0 && grid[r - 1][c] == '.') {
                        dsu.union(r * cols + c, (r - 1) * cols + c);
                    }
                    // Check left neighbor
                    if (c > 0 && grid[r][c - 1] == '.') {
                        dsu.union(r * cols + c, r * cols + (c - 1));
                    }
                }
            }
        }

        // Step 2: Generate the output grid
        for (int r = 0; r < rows; r++) {
            StringBuilder rowOutput = new StringBuilder();
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    rowOutput.append('.');
                } else {
                    rowOutput.append(calculateReplacementValue(grid, dsu, r, c, rows, cols));
                }
            }
            out.println(rowOutput.toString());
        }
        out.flush();
    }

    private int calculateReplacementValue(char[][] grid, DisjointSetUnion dsu, int r, int c, int rows, int cols) {
        Set<Integer> uniqueComponentRoots = new HashSet<>();
        int totalCount = 1; // Start with 1 to count the '#' cell itself

        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            if (isValid(nr, nc, rows, cols) && grid[nr][nc] == '.') {
                int root = dsu.find(nr * cols + nc);
                // If this component hasn't been added to the count for this '#' yet
                if (uniqueComponentRoots.add(root)) {
                    totalCount += dsu.getSize(root);
                }
            }
        }
        return totalCount % 10;
    }

    private boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

/**
 * Disjoint Set Union (DSU) implementation with path compression and union by size.
 */
class DisjointSetUnion {
    private final int[] parent;
    private final int[] componentSize;

    public DisjointSetUnion(int n) {
        parent = new int[n];
        componentSize = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
            componentSize[i] = 1;
        }
    }

    /**
     * Finds the representative of the set containing 'i' with path compression.
     * Uses an iterative approach to prevent StackOverflow on deep trees.
     */
    public int find(int i) {
        int root = i;
        while (parent[root] != root) {
            root = parent[root];
        }
        // Path compression
        while (parent[i] != root) {
            int next = parent[i];
            parent[i] = root;
            i = next;
        }
        return root;
    }

    /**
     * Unites the sets containing 'i' and 'j' using union by size.
     */
    public void union(int i, int j) {
        int rootI = find(i);
        int rootJ = find(j);

        if (rootI != rootJ) {
            if (componentSize[rootI] < componentSize[rootJ]) {
                parent[rootI] = rootJ;
                componentSize[rootJ] += componentSize[rootI];
            } else {
                parent[rootJ] = rootI;
                componentSize[rootI] += componentSize[rootJ];
            }
        }
    }

    /**
     * Returns the size of the component containing 'i'.
     */
    public int getSize(int i) {
        return componentSize[find(i)];
    }
}

import java.util.*;
