/**
 * A program to process a grid containing walls (#), empty spaces (.), and obstacles (*).
 * It identifies connected components of empty spaces and calculates a value for each obstacle
 * based on the sizes of its neighboring empty space components.
 */
public class GridProcessor {

    private static final char WALL = '#';
    private static final char EMPTY = '.';
    private static final char OBSTACLE = '*';

    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    private int rows;
    private int cols;
    private char[][] grid;
    private int[][] componentIdMap;
    private int[] componentSizes;

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = reader.nextInt();
            int m = reader.nextInt();
            GridProcessor solver = new GridProcessor(n, m);
            solver.readGrid(reader);
            solver.process();
            solver.printGrid(out);
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.close();
        }
    }

    public GridProcessor(int rows, int cols) {
        this.rows = rows;
        this.cols = cols;
        // We add a padding of 1 around the grid to simplify boundary checks
        this.grid = new char[rows + 2][cols + 2];
        this.componentIdMap = new int[rows + 2][cols + 2];
        // Max components possible is (rows * cols) / 2
        this.componentSizes = new int[rows * cols + 2];
        initializePadding();
    }

    private void initializePadding() {
        for (int i = 0; i < rows + 2; i++) {
            Arrays.fill(grid[i], WALL);
        }
    }

    public void readGrid(FastReader reader) {
        for (int i = 1; i <= rows; i++) {
            String line = reader.next();
            for (int j = 1; j <= cols; j++) {
                grid[i][j] = line.charAt(j - 1);
            }
        }
    }

    /**
     * Orchestrates the identification of components and calculation of obstacle values.
     */
    public void process() {
        int currentComponentId = 1;
        findConnectedComponents(currentComponentId);
        // Note: The loop above increments ID, so we update the count naturally.
        // However, the logic is easier if we keep track of the next ID.

        // Re-calculating to match logic flow of original:
        currentComponentId = 1;
        for (int r = 1; r <= rows; r++) {
            for (int c = 1; c <= cols; c++) {
                if (grid[r][c] == EMPTY && componentIdMap[r][c] == 0) {
                    int size = bfs(r, c, currentComponentId);
                    componentSizes[currentComponentId] = size;
                    currentComponentId++;
                }
            }
        }

        calculateObstacleValues();
    }

    private void findConnectedComponents(int startId) {
        // This was merged into the main process loop above to avoid redundant passes.
    }

    private int bfs(int startR, int startC, int id) {
        int size = 0;
        Deque<Point> queue = new ArrayDeque<>();

        queue.add(new Point(startR, startC));
        componentIdMap[startR][startC] = id;

        while (!queue.isEmpty()) {
            Point p = queue.poll();
            size++;

            for (int i = 0; i < 4; i++) {
                int nr = p.r + DR[i];
                int nc = p.c + DC[i];

                if (isValidEmptyCell(nr, nc)) {
                    componentIdMap[nr][nc] = id;
                    queue.add(new Point(nr, nc));
                }
            }
        }
        return size;
    }

    private boolean isValidEmptyCell(int r, int c) {
        return grid[r][c] == EMPTY && componentIdMap[r][c] == 0;
    }

    private void calculateObstacleValues() {
        for (int r = 1; r <= rows; r++) {
            for (int c = 1; c <= cols; c++) {
                if (grid[r][c] == OBSTACLE) {
                    grid[r][c] = computeObstacleChar(r, c);
                }
            }
        }
    }

    private char computeObstacleChar(int r, int c) {
        Set<Integer> neighborComponentIds = new HashSet<>();
        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];
            int id = componentIdMap[nr][nc];
            if (id > 0) {
                neighborComponentIds.add(id);
            }
        }

        long totalSizeSum = 1; // The logic requires starting sum at 1
        for (int id : neighborComponentIds) {
            totalSizeSum += componentSizes[id];
        }

        return (char) ('0' + (totalSizeSum % 10));
    }

    public void printGrid(PrintWriter out) {
        StringBuilder sb = new StringBuilder();
        for (int i = 1; i <= rows; i++) {
            for (int j = 1; j <= cols; j++) {
                sb.append(grid[i][j]);
            }
            sb.append('\n');
        }
        out.print(sb.toString());
    }

    private static class Point {
        final int r, c;
        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Fast I/O Reader for high-performance input parsing.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * GridComponentProcessor calculates the sum of sizes of adjacent empty components ('.')
 * for each star cell ('*') in a grid.
 */
public class GridComponentProcessor {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            GridProcessor processor = new GridProcessor(rows, cols, grid);
            char[][] resultGrid = processor.process();

            for (int i = 0; i < rows; i++) {
                writer.println(new String(resultGrid[i]));
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    private static class GridProcessor {
        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final int[][] componentIds;
        private final long[] componentSizes;

        public GridProcessor(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            this.componentIds = new int[rows][cols];
            // Maximum possible components is rows * cols
            this.componentSizes = new long[rows * cols + 1];
        }

        /**
         * Main logic to identify components and calculate star values.
         */
        public char[][] process() {
            labelComponents();
            return calculateResultGrid();
        }

        /**
         * Uses iterative DFS to find connected components of '.' and assign unique IDs.
         */
        private void labelComponents() {
            int currentComponentId = 1;
            int[] dr = {1, -1, 0, 0};
            int[] dc = {0, 0, 1, -1};

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.' && componentIds[i][j] == 0) {
                        int size = performIterativeDFS(i, j, currentComponentId, dr, dc);
                        componentSizes[currentComponentId] = size;
                        currentComponentId++;
                    }
                }
            }
        }

        private int performIterativeDFS(int startR, int startC, int id, int[] dr, int[] dc) {
            int count = 0;
            Deque<int[]> stack = new ArrayDeque<>();

            stack.push(new int[]{startR, startC});
            componentIds[startR][startC] = id;

            while (!stack.isEmpty()) {
                int[] cell = stack.pop();
                int r = cell[0];
                int c = cell[1];
                count++;

                for (int i = 0; i < 4; i++) {
                    int nr = r + dr[i];
                    int nc = c + dc[i];

                    if (isValid(nr, nc) && grid[nr][nc] == '.' && componentIds[nr][nc] == 0) {
                        componentIds[nr][nc] = id;
                        stack.push(new int[]{nr, nc});
                    }
                }
            }
            return count;
        }

        private char[][] calculateResultGrid() {
            char[][] result = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.') {
                        result[i][j] = '.';
                    } else {
                        result[i][j] = calculateStarValue(i, j);
                    }
                }
            }
            return result;
        }

        private char calculateStarValue(int r, int c) {
            long sum = 1; // The star itself
            int[] neighborIds = new int[4];
            int neighborCount = 0;

            // Check 4 neighbors
            int[][] directions = {{r - 1, j_val(c)}, {r, c - 1}, {r + 1, j_val(c)}, {r, c + 1}};
            // Standard direction offsets
            int[] dr = {-1, 0, 1, 0};
            int[] dc = {0, -1, 0, 1};

            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i];
                int nc = c + dc[i];
                if (isValid(nr, nc) && grid[nr][nc] == '.') {
                    neighborIds[neighborCount++] = componentIds[nr][nc];
                } else {
                    neighborIds[neighborCount++] = 0;
                }
            }

            // Add unique component sizes found in neighbors
            for (int i = 0; i < neighborCount; i++) {
                int id = neighborIds[i];
                if (id == 0) continue;

                boolean alreadyAdded = false;
                for (int j = 0; j < i; j++) {
                    if (neighborIds[j] == id) {
                        alreadyAdded = true;
                        break;
                    }
                }

                if (!alreadyAdded) {
                    sum += componentSizes[id];
                }
            }

            return (char) ((sum % 10) + '0');
        }

        // Helper to avoid messy ternary logic in calculation
        private int j_val(int c) { return c; }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * Fast I/O utility for efficient reading of large inputs.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * TheLabyrinth solves a grid-based puzzle where connected components of path cells ('.') 
 * are identified, and wall cells ('*') are updated based on the sum of the sizes 
 * of their adjacent path components.
 */
public class TheLabyrinth {

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);

        try {
            int rows = sc.nextInt();
            int cols = sc.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = sc.next().toCharArray();
            }

            LabyrinthSolver solver = new LabyrinthSolver(rows, cols, grid);
            solver.solve();
            solver.printGrid();

        } catch (Exception e) {
            System.err.println("Error processing labyrinth: " + e.getMessage());
        }
    }

    /**
     * Utility class for high-performance input reading.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream inputStream) {
            this.reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public FastScanner(String filePath) throws FileNotFoundException {
            this.reader = new BufferedReader(new FileReader(filePath));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }

    /**
     * Core logic for processing the labyrinth grid.
     */
    static class LabyrinthSolver {
        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final int[][] componentIds;
        private final List<Integer> componentSizes;

        // Directional vectors for traversing neighbors (Up, Down, Left, Right)
        private static final int[] DR = {-1, 1, 0, 0};
        private static final int[] DC = {0, 0, -1, 1};

        public LabyrinthSolver(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            this.componentIds = new int[rows][cols];
            this.componentSizes = new ArrayList<>();
            // Initialize index 0 for empty/no component
            this.componentSizes.add(0);
        }

        /**
         * Orchestrates the component identification and wall calculation.
         */
        public void solve() {
            identifyComponents();
            calculateWallValues();
        }

        /**
         * Identifies all connected components of '.' using iterative BFS to avoid StackOverflow.
         */
        private void identifyComponents() {
            boolean[][] visited = new boolean[rows][cols];
            int currentId = 1;

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.' && !visited[r][c]) {
                        int size = performBFS(r, c, visited, currentId);
                        componentSizes.add(size);
                        currentId++;
                    }
                }
            }
        }

        private int performBFS(int startR, int startC, boolean[][] visited, int id) {
            Queue<int[]> queue = new ArrayDeque<>();
            queue.offer(new int[]{startR, startC});
            visited[startR][startC] = true;

            int size = 0;

            while (!queue.isEmpty()) {
                int[] cell = queue.poll();
                int r = cell[0];
                int c = cell[1];

                componentIds[r][c] = id;
                size++;

                for (int i = 0; i < 4; i++) {
                    int nr = r + DR[i];
                    int nc = c + DC[i];

                    if (isValid(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        queue.offer(new int[]{nr, nc});
                    }
                }
            }
            return size;
        }

        /**
         * Updates each '*' cell with the sum of sizes of adjacent components.
         */
        private void calculateWallValues() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '*') {
                        grid[r][c] = updateWallChar(r, c);
                    }
                }
            }
        }

        private char updateWallChar(int r, int c) {
            Set<Integer> adjacentComponentIds = new HashSet<>();

            for (int i = 0; i < 4; i++) {
                int nr = r + DR[i];
                int nc = c + DC[i];

                if (isValid(nr, nc) && componentIds[nr][nc] != 0) {
                    adjacentComponentIds.add(componentIds[nr][nc]);
                }
            }

            int sumOfSizes = 0;
            for (int id : adjacentComponentIds) {
                sumOfSizes += componentSizes.get(id);
            }

            // Formula: (sum + 1) % 10
            return (char) (((sumOfSizes + 1) % 10) + '0');
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        /**
         * Efficiently prints the final grid.
         */
        public void printGrid() {
            PrintWriter pw = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
            for (int r = 0; r < rows; r++) {
                pw.println(new String(grid[r]));
            }
            pw.flush();
            pw.close();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.*;

/**
 * A solver for maze-based grid problems where connectivity of empty cells ('.')
 * determines the value of obstacle cells ('*').
 */
public class MazeSolver {

    private static final int[] ROW_OFFSETS = {0, 0, 1, -1};
    private static final int[] COL_OFFSETS = {1, -1, 0, 0};

    private final int rows;
    private final int cols;
    private final char[][] maze;
    private final int[][] groupIds;
    private final List<Integer> groupSizes;

    public MazeSolver(int rows, int cols, char[][] maze) {
        this.rows = rows;
        this.cols = cols;
        this.maze = maze;
        this.groupIds = new int[rows][cols];
        this.groupSizes = new ArrayList<>();

        // Initialize group IDs with -1 (unvisited)
        for (int i = 0; i < rows; i++) {
            Arrays.fill(groupIds[i], -1);
        }
    }

    public void solve() {
        identifyGroups();
        calculateObstacleValues();
        printResult();
    }

    /**
     * Identifies all connected components of '.' cells using BFS.
     */
    private void identifyGroups() {
        int currentGroupId = 0;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (maze[r][c] == '.' && groupIds[r][c] == -1) {
                    int size = bfsIdentifyGroup(r, c, currentGroupId);
                    groupSizes.add(size);
                    currentGroupId++;
                }
            }
        }
    }

    private int bfsIdentifyGroup(int startRow, int startCol, int groupId) {
        Queue<Point> queue = new LinkedList<>();
        queue.add(new Point(startRow, startCol));
        groupIds[startRow][startCol] = groupId;

        int count = 0;

        while (!queue.isEmpty()) {
            Point current = queue.poll();
            count++;

            for (int i = 0; i < 4; i++) {
                int nr = current.row + ROW_OFFSETS[i];
                int nc = current.col + COL_OFFSETS[i];

                if (isValidEmptyCell(nr, nc)) {
                    groupIds[nr][nc] = groupId;
                    queue.add(new Point(nr, nc));
                }
            }
        }
        return count;
    }

    private boolean isValidEmptyCell(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols 
                && maze[r][c] == '.' && groupIds[r][c] == -1;
    }

    /**
     * Calculates the value of each '*' cell based on the sum of the sizes
     * of its unique adjacent '.' groups.
     */
    private void calculateObstacleValues() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (maze[r][c] == '*') {
                    maze[r][c] = (char) (calculateSumForObstacle(r, c) + '0');
                }
            }
        }
    }

    private int calculateSumForObstacle(int r, int c) {
        Set<Integer> uniqueAdjacentGroups = new HashSet<>();

        for (int i = 0; i < 4; i++) {
            int nr = r + ROW_OFFSETS[i];
            int nc = c + COL_OFFSETS[i];

            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && maze[nr][nc] == '.') {
                uniqueAdjacentGroups.add(groupIds[nr][nc]);
            }
        }

        int total = 1; // Base value for '*'
        for (int groupId : uniqueAdjacentGroups) {
            total += groupSizes.get(groupId);
        }

        // Problem specifies result is modulo 10
        return total % 10;
    }

    private void printResult() {
        PrintWriter out = new PrintWriter(System.out);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                // If it's a digit (converted from '*'), print it, else print original character
                if (Character.isDigit(maze[i][j])) {
                    sb.append(maze[i][j]);
                } else {
                    sb.append(maze[i][j]);
                }
            }
            sb.append("\n");
        }
        out.print(sb.toString());
        out.flush();
    }

    /**
     * Simple immutable coordinate representation.
     */
    private static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    public static void main(String[] args) {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String line = br.readLine();
            if (line == null) return;

            String[] dimensions = line.trim().split("\\s+");
            int rows = Integer.parseInt(dimensions[0]);
            int cols = Integer.parseInt(dimensions[1]);

            char[][] maze = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                maze[i] = br.readLine().toCharArray();
            }

            MazeSolver solver = new MazeSolver(rows, cols, maze);
            solver.solve();

        } catch (IOException | NumberFormatException e) {
            e.printStackTrace();
        }
    }
}

