/**
 * Represents a coordinate in the 2D grid.
 */
record Coordinate(int r, int c) {}

/**
 * Represents a connected component of '.' cells.
 */
class Component {
    private int size = 0;

    public void incrementSize() {
        this.size++;
    }

    public int getSize() {
        return size;
    }
}

/**
 * Logic for processing the grid and calculating component-based values.
 */
class GridSolver {
    private static final int[][] DIRECTIONS = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final Component[][] componentMap;

    public GridSolver(int rows, int cols, String[] gridData) {
        this.rows = rows;
        this.cols = cols;
        this.grid = new char[rows][cols];
        this.componentMap = new Component[rows][cols];

        for (int i = 0; i < rows; i++) {
            this.grid[i] = gridData[i].toCharArray();
        }
    }

    /**
     * Solves the grid problem by finding connected components of '.'
     * and calculating values for '*' cells.
     */
    public String[] solve() {
        findConnectedComponents();
        return generateResultGrid();
    }

    /**
     * Identifies all connected components of '.' cells using BFS.
     */
    private void findConnectedComponents() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && componentMap[r][c] == null) {
                    Component component = new Component();
                    bfsAssignComponent(r, c, component);
                }
            }
        }
    }

    private void bfsAssignComponent(int startR, int startC, Component component) {
        Queue<Coordinate> queue = new LinkedList<>();
        Coordinate start = new Coordinate(startR, startC);

        queue.add(start);
        componentMap[startR][startC] = component;
        component.incrementSize();

        while (!queue.isEmpty()) {
            Coordinate current = queue.poll();

            for (int[] dir : DIRECTIONS) {
                int nr = current.r() + dir[0];
                int nc = current.c() + dir[1];

                if (isValid(nr, nc) && grid[nr][nc] == '.' && componentMap[nr][nc] == null) {
                    componentMap[nr][nc] = component;
                    component.incrementSize();
                    queue.add(new Coordinate(nr, nc));
                }
            }
        }
    }

    /**
     * Builds the resulting grid based on the rules.
     */
    private String[] generateResultGrid() {
        String[] result = new String[rows];

        for (int r = 0; r < rows; r++) {
            StringBuilder rowBuilder = new StringBuilder();
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    rowBuilder.append('.');
                } else {
                    rowBuilder.append(calculateStarValue(r, c));
                }
            }
            result[r] = rowBuilder.toString();
        }
        return result;
    }

    private int calculateStarValue(int r, int c) {
        int count = 1; // Start with the star itself
        Set<Component> seenComponents = new HashSet<>();

        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            if (isValid(nr, nc) && grid[nr][nc] == '.') {
                Component comp = componentMap[nr][nc];
                if (comp != null && seenComponents.add(comp)) {
                    count += comp.getSize();
                }
            }
        }
        return count % 10;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

