import java.io.*;
import java.util.*;

/**
 * TheLabyrinth solver finds connected components of '.' in a grid.
 * For every '*' cell, it calculates the sum of the sizes of its unique 
 * adjacent '.' components (plus one), and outputs that sum modulo 10.
 */
public class TheLabyrinth {

    public static void main(String[] args) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)))) {

            String line = reader.readLine();
            if (line == null) return;

            String[] dimensions = line.trim().split("\\s+");
            int rows = Integer.parseInt(dimensions[0]);
            int cols = Integer.parseInt(dimensions[1]);

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String rowStr = reader.readLine();
                if (rowStr != null) {
                    grid[i] = rowStr.toCharArray();
                }
            }

            LabyrinthSolver solver = new LabyrinthSolver(rows, cols, grid);
            solver.solve(writer);

        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Represents a coordinate in the grid.
     */
    private record Point(int r, int c) {}

    private static class LabyrinthSolver {
        private final int rows;
        private final int cols;
        private final char[][] grid;

        // Direction vectors for 4-connectivity (Up, Down, Left, Right)
        private static final int[] DR = {-1, 1, 0, 0};
        private static final int[] DC = {0, 0, -1, 1};

        // Metadata for components
        private final int[][] componentIdGrid;
        private final int[][] componentSizeGrid;
        private int componentIdCounter = 0;

        public LabyrinthSolver(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            this.componentIdGrid = new int[rows][cols];
            this.componentSizeGrid = new int[rows][cols];
        }

        public void solve(PrintWriter writer) {
            findComponents();
            computeAndPrintResult(writer);
        }

        /**
         * Uses BFS to identify all connected components of '.' cells.
         */
        private void findComponents() {
            boolean[][] visited = new boolean[rows][cols];

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.' && !visited[r][c]) {
                        bfsIdentifyComponent(r, c, visited);
                    }
                }
            }
        }

        private void bfsIdentifyComponent(int startR, int startC, boolean[][] visited) {
            List<Point> componentCells = new ArrayList<>();
            Queue<Point> queue = new LinkedList<>();

            visited[startR][startC] = true;
            Point start = new Point(startR, startC);
            queue.add(start);
            componentCells.add(start);

            while (!queue.isEmpty()) {
                Point current = queue.poll();

                for (int i = 0; i < 4; i++) {
                    int nr = current.r + DR[i];
                    int nc = current.c + DC[i];

                    if (isValid(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        Point next = new Point(nr, nc);
                        queue.add(next);
                        componentCells.add(next);
                    }
                }
            }

            // Assign unique ID and size to all cells in this component
            componentIdCounter++;
            int size = componentCells.size();
            for (Point p : componentCells) {
                componentIdGrid[p.r][p.c] = componentIdCounter;
                componentSizeGrid[p.r][p.c] = size;
            }
        }

        /**
         * Iterates through the grid and computes the requested digit for each '*' cell.
         */
        private void computeAndPrintResult(PrintWriter writer) {
            StringBuilder output = new StringBuilder();

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.') {
                        output.append('.');
                    } else {
                        output.append(calculateStarValue(r, c));
                    }
                }
                output.append('\n');
            }
            writer.print(output.toString());
        }

        private int calculateStarValue(int r, int c) {
            Set<Integer> uniqueNeighboringComponentIds = new HashSet<>();
            int totalSizeSum = 1; // Starting base value as per original logic

            for (int i = 0; i < 4; i++) {
                int nr = r + DR[i];
                int nc = c + DC[i];

                if (isValid(nr, nc) && grid[nr][nc] == '.') {
                    int compId = componentIdGrid[nr][nc];
                    // If we haven't processed this specific component for this star yet
                    if (compId != 0 && !uniqueNeighboringComponentIds.contains(compId)) {
                        uniqueNeighboringComponentIds.add(compId);
                        totalSizeSum += componentSizeGrid[nr][nc];
                    }
                }
            }
            return totalSizeSum % 10;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A program to analyze a grid of obstacles ('*') and empty cells ('.').
 * It identifies connected components of empty cells and calculates a value 
 * for each obstacle based on the sum of the sizes of its adjacent components.
 */
public class GridAnalyzer {

    private static final int[] ROW_DIRECTIONS = {1, 0, -1, 0};
    private static final int[] COL_DIRECTIONS = {0, 1, 0, -1};

    public static void main(String[] args) {
        try {
            FastScanner scanner = new FastScanner(System.in);
            PrintWriter writer = new PrintWriter(System.out);

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            char[][] inputGrid = new char[rows][cols];
            boolean[][] isObstacle = new boolean[rows][cols];

            for (int i = 0; i < rows; i++) {
                String line = scanner.next();
                for (int j = 0; j < cols; j++) {
                    char cell = line.charAt(j);
                    inputGrid[i][j] = cell;
                    if (cell == '*') {
                        isObstacle[i][j] = true;
                    }
                }
            }

            GridSolver solver = new GridSolver(rows, cols, isObstacle);
            char[][] resultGrid = solver.solve();

            for (char[] row : resultGrid) {
                writer.println(new String(row));
            }

            writer.flush();
            writer.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /**
     * Represents a coordinate in the 2D grid.
     */
    private record Point(int r, int c) {}

    /**
     * Handles the core logic of component identification and value calculation.
     */
    private static class GridSolver {
        private final int rows;
        private final int cols;
        private final boolean[][] isObstacle;
        private final int[][] componentIds;
        private final Map<Integer, Integer> componentSizes;

        public GridSolver(int rows, int cols, boolean[][] isObstacle) {
            this.rows = rows;
            this.cols = cols;
            this.isObstacle = isObstacle;
            this.componentIds = new int[rows][cols];
            this.componentSizes = new HashMap<>();
        }

        public char[][] solve() {
            labelComponents();
            return calculateResult();
        }

        /**
         * Uses BFS to find all connected components of empty cells and assigns them unique IDs.
         */
        private void labelComponents() {
            int nextComponentId = 1;

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    // If it's an empty cell and hasn't been visited yet
                    if (!isObstacle[r][c] && componentIds[r][c] == 0) {
                        int size = bfsLabelComponent(r, c, nextComponentId);
                        componentSizes.put(nextComponentId, size);
                        nextComponentId++;
                    }
                }
            }
        }

        private int bfsLabelComponent(int startR, int startC, int id) {
            int size = 0;
            Queue<Point> queue = new ArrayDeque<>();

            queue.add(new Point(startR, startC));
            componentIds[startR][startC] = id;

            while (!queue.isEmpty()) {
                Point current = queue.poll();
                size++;

                for (int i = 0; i < 4; i++) {
                    int nr = current.r + ROW_DIRECTIONS[i];
                    int nc = current.c + COL_DIRECTIONS[i];

                    if (isValidEmptyCell(nr, nc)) {
                        componentIds[nr][nc] = id;
                        queue.add(new Point(nr, nc));
                    }
                }
            }
            return size;
        }

        private boolean isValidEmptyCell(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols 
                   && !isObstacle[r][c] && componentIds[r][c] == 0;
        }

        /**
         * Constructs the output grid based on the obstacle adjacency rules.
         */
        private char[][] calculateResult() {
            char[][] result = new char[rows][cols];

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (isObstacle[r][c]) {
                        result[r][c] = calculateObstacleValue(r, c);
                    } else {
                        result[r][c] = '.';
                    }
                }
            }
            return result;
        }

        private char calculateObstacleValue(int r, int c) {
            Set<Integer> seenComponents = new HashSet<>();
            int totalAdjacentSize = 1; // Starting with 1 as per original logic

            for (int i = 0; i < 4; i++) {
                int nr = r + ROW_DIRECTIONS[i];
                int nc = c + COL_DIRECTIONS[i];

                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && !isObstacle[nr][nc]) {
                    int id = componentIds[nr][nc];
                    if (id != 0 && !seenComponents.contains(id)) {
                        seenComponents.add(id);
                        totalAdjacentSize += componentSizes.getOrDefault(id, 0);
                    }
                }
            }

            return (char) ('0' + (totalAdjacentSize % 10));
        }
    }

    /**
     * Efficient input reader.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream input) {
            br = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

