class GridAnalyzer {
    private final char[][] grid;
    private final int rows;
    private final int cols;

    private static final int[] ROW_OFFSETS = {-1, 0, 0, 1};
    private static final int[] COL_OFFSETS = {0, -1, 1, 0};
    private static final char EMPTY_CELL = '.';

    private int[][] componentIds;
    private int[] componentSizes;
    private int componentCount = 0;

    public GridAnalyzer(char[][] grid) {
        this.grid = grid;
        this.rows = grid.length;
        this.cols = grid[0].length;
        this.componentIds = new int[rows][cols];
        // Max possible components is (rows * cols) / 2 + 1
        this.componentSizes = new int[rows * cols + 1];
    }

    /**
     * Processes the grid to find components and compute the final values.
     * @return A new grid containing the transformed values.
     */
    public char[][] computeResult() {
        identifyComponents();
        return generateResultGrid();
    }

    /**
     * Uses an iterative DFS to find and label all connected components of '.' cells.
     */
    private void identifyComponents() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == EMPTY_CELL && componentIds[i][j] == 0) {
                    componentCount++;
                    int size = performIterativeDFS(i, j, componentCount);
                    componentSizes[componentCount] = size;
                }
            }
        }
    }

    private int performIterativeDFS(int startRow, int startCol, int id) {
        int size = 0;
        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{startRow, startCol});
        componentIds[startRow][startCol] = id;

        while (!stack.isEmpty()) {
            int[] current = stack.pop();
            int r = current[0];
            int c = current[1];
            size++;

            for (int k = 0; k < 4; k++) {
                int nr = r + ROW_OFFSETS[k];
                int nc = c + COL_OFFSETS[k];

                if (isValid(nr, nc) && grid[nr][nc] == EMPTY_CELL && componentIds[nr][nc] == 0) {
                    componentIds[nr][nc] = id;
                    stack.push(new int[]{nr, nc});
                }
            }
        }
        return size;
    }

    private char[][] generateResultGrid() {
        char[][] result = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == EMPTY_CELL) {
                    result[i][j] = EMPTY_CELL;
                } else {
                    result[i][j] = (char) ('0' + calculateNeighborScore(i, j));
                }
            }
        }
        return result;
    }

    private int calculateNeighborScore(int r, int c) {
        Set<Integer> uniqueNeighboringComponentIds = new HashSet<>();
        for (int k = 0; k < 4; k++) {
            int nr = r + ROW_OFFSETS[k];
            int nc = c + COL_OFFSETS[k];

            if (isValid(nr, nc)) {
                int id = componentIds[nr][nc];
                if (id > 0) {
                    uniqueNeighboringComponentIds.add(id);
                }
            }
        }

        int totalNeighboringSize = 0;
        for (int id : uniqueNeighboringComponentIds) {
            totalNeighboringSize += componentSizes[id];
        }

        return (totalNeighboringSize + 1) % 10;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

