class GridAnalyzer {
    private static final char WALL_CHAR = '*';
    private static final char EMPTY_CHAR = '.';

    // Direction offsets for 4-way connectivity (Up, Right, Down, Left)
    private static final int[] DR = {-1, 0, 1, 0};
    private static final int[] DC = {0, 1, 0, -1};

    private final int rows;
    private final int cols;
    private final char[][] inputGrid;

    // regionIds[r][c] stores the ID of the region the cell belongs to.
    // -1 represents a wall, 0 represents an empty cell, and >0 represents a region ID.
    private final int[][] regionIds;
    private final Map<Integer, Integer> regionSizes;

    public GridAnalyzer(int rows, int cols, char[][] inputGrid) {
        this.rows = rows;
        this.cols = cols;
        this.inputGrid = inputGrid;
        this.regionIds = new int[rows][cols];
        this.regionSizes = new HashMap<>();
    }

    /**
     * Performs the core analysis: identifies regions and calculates obstacle values.
     * @return A char grid containing the processed results.
     */
    public char[][] analyze() {
        initializeRegionIds();
        identifyRegions();
        return generateOutputGrid();
    }

    private void initializeRegionIds() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (inputGrid[r][c] == WALL_CHAR) {
                    regionIds[r][c] = -1;
                } else {
                    regionIds[r][c] = 0;
                }
            }
        }
    }

    private void identifyRegions() {
        int currentRegionId = 1;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                // If we find an unvisited empty cell, start a BFS to map the region
                if (regionIds[r][c] == 0) {
                    int size = bfsExploreRegion(r, c, currentRegionId);
                    regionSizes.put(currentRegionId, size);
                    currentRegionId++;
                }
            }
        }
    }

    /**
     * Iterative BFS to find all connected empty cells.
     */
    private int bfsExploreRegion(int startR, int startC, int regionId) {
        Deque<Point> queue = new ArrayDeque<>();
        queue.add(new Point(startR, startC));
        regionIds[startR][startC] = regionId;

        int count = 0;
        while (!queue.isEmpty()) {
            Point curr = queue.poll();
            count++;

            for (int i = 0; i < 4; i++) {
                int nr = curr.row + DR[i];
                int nc = curr.col + DC[i];

                if (isValid(nr, nc) && regionIds[nr][nc] == 0) {
                    regionIds[nr][nc] = regionId;
                    queue.add(new Point(nr, nc));
                }
            }
        }
        return count;
    }

    private char[][] generateOutputGrid() {
        char[][] output = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (inputGrid[r][c] == WALL_CHAR) {
                    output[r][c] = calculateObstacleValue(r, c);
                } else {
                    output[r][c] = EMPTY_CHAR;
                }
            }
        }
        return output;
    }

    private char calculateObstacleValue(int r, int c) {
        int sum = 1; // Base value for the obstacle itself
        Set<Integer> uniqueAdjacentRegions = new HashSet<>();

        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];

            if (isValid(nr, nc)) {
                int id = regionIds[nr][nc];
                // If the neighbor belongs to a region (id > 0)
                if (id > 0) {
                    uniqueAdjacentRegions.add(id);
                }
            }
        }

        for (int id : uniqueAdjacentRegions) {
            sum += regionSizes.getOrDefault(id, 0);
        }

        return (char) ((sum % 10) + '0');
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Simple data carrier for coordinates.
     */
    private static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }
}

