/**
 * A refactored solution for the grid-based connectivity problem.
 * The goal is to find connected components of '.' cells and, for each '#' cell,
 * output the sum of the sizes of its 4-directionally adjacent '.' components modulo 10.
 */
public class CF5CSolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            String firstLine = reader.next();
            if (firstLine == null) return;

            int testCases = Integer.parseInt(firstLine);
            while (testCases-- > 0) {
                int N = reader.nextInt();
                int M = reader.nextInt();
                char[][] grid = new char[N][M];
                for (int i = 0; i < N; i++) {
                    grid[i] = reader.next().toCharArray();
                }

                GridSolver solver = new GridSolver(N, M, grid);
                out.println(solver.solve());
            }
        } catch (Exception e) {
            // In competitive programming, we usually swallow or print minimal errors
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Logic for solving a single test case.
     */
    static class GridSolver {
        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final int[][] componentId;
        private final List<Integer> componentSizes;

        // Directions for 4-connectivity: Right, Left, Down, Up
        private static final int[] DR = {0, 0, 1, -1};
        private static final int[] DC = {1, -1, 0, 0};

        public GridSolver(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            this.componentId = new int[rows][cols];
            for (int i = 0; i < rows; i++) {
                Arrays.fill(componentId[i], -1);
            }
            this.componentSizes = new ArrayList<>();
        }

        public String solve() {
            identifyComponents();
            return buildResult();
        }

        /**
         * Uses BFS to find all connected components of '.' cells.
         */
        private void identifyComponents() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.' && componentId[i][j] == -1) {
                        int newId = componentSizes.size();
                        int size = bfs(i, j, newId);
                        componentSizes.add(size);
                    }
                }
            }
        }

        private int bfs(int startR, int startC, int id) {
            int count = 0;
            Deque<Integer> queue = new ArrayDeque<>();

            // Encode 2D coordinate into 1D to save memory/object creation
            queue.add(startR * cols + startC);
            componentId[startR][startC] = id;
            count++;

            while (!queue.isEmpty()) {
                int pos = queue.poll();
                int r = pos / cols;
                int c = pos % cols;

                for (int i = 0; i < 4; i++) {
                    int nr = r + DR[i];
                    int nc = c + DC[i];

                    if (isValid(nr, nc) && grid[nr][nc] == '.' && componentId[nr][nc] == -1) {
                        componentId[nr][nc] = id;
                        count++;
                        queue.add(nr * cols + nc);
                    }
                }
            }
            return count;
        }

        /**
         * Constructs the output string by iterating through the grid.
         */
        private String buildResult() {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.') {
                        sb.append('.');
                    } else {
                        sb.append(calculateHashValue(i, j));
                    }
                }
                if (i < rows - 1) sb.append('\n');
            }
            return sb.toString();
        }

        /**
         * For a '#' cell, sums the sizes of unique adjacent '.' components.
         * Replicates the original logic: (Sum of sizes + 1) % 10.
         */
        private int calculateHashValue(int r, int c) {
            Set<Integer> uniqueComponentIds = new HashSet<>();
            for (int i = 0; i < 4; i++) {
                int nr = r + DR[i];
                int nc = c + DC[i];
                if (isValid(nr, nc) && grid[nr][nc] == '.') {
                    int id = componentId[nr][nc];
                    if (id != -1) {
                        uniqueComponentIds.add(id);
                    }
                }
            }

            int totalSizeSum = 0;
            for (int id : uniqueComponentIds) {
                totalSizeSum += componentSizes.get(id);
            }

            // Per original implementation: (Sum + 1) % 10
            return (totalSizeSum + 1) % 10;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * High-performance input reader.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

