/**
 * GridAnalyzer calculates a value for each obstacle '*' based on the size 
 * of adjacent connected components of empty spaces '.'.
 */
public class GridAnalyzer {

    private static final int[] DIRECTION_X = {1, -1, 0, 0};
    private static final int[] DIRECTION_Y = {0, 0, 1, -1};

    private final int rows;
    private final int cols;
    private final boolean[][] isObstacle;
    private final int[][] componentIds;
    private final int[] componentSizes;

    public GridAnalyzer(int rows, int cols, boolean[][] isObstacle) {
        this.rows = rows;
        this.cols = cols;
        this.isObstacle = isObstacle;
        this.componentIds = new int[rows][cols];
        this.componentSizes = new int[rows * cols + 1];

        // Initialize component IDs with -1 (representing no component)
        for (int i = 0; i < rows; i++) {
            Arrays.fill(componentIds[i], -1);
        }
    }

    /**
     * Represents a coordinate on the grid.
     */
    private record Point(int r, int c) {}

    /**
     * Identifies all connected components of empty spaces using BFS.
     */
    public void findComponents() {
        int currentComponentId = 0;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (!isObstacle[r][c] && componentIds[r][c] == -1) {
                    currentComponentId++;
                    int size = performBFS(r, c, currentComponentId);
                    componentSizes[currentComponentId] = size;
                }
            }
        }
    }

    private int performBFS(int startR, int startC, int id) {
        Queue<Point> queue = new ArrayDeque<>();
        queue.add(new Point(startR, startC));
        componentIds[startR][startC] = id;

        int count = 0;

        while (!queue.isEmpty()) {
            Point current = queue.poll();
            count++;

            for (int i = 0; i < 4; i++) {
                int nr = current.r + DIRECTION_Y[i];
                int nc = current.c + DIRECTION_X[i];

                if (isValid(nr, nc) && !isObstacle[nr][nc] && componentIds[nr][nc] == -1) {
                    componentIds[nr][nc] = id;
                    queue.add(new Point(nr, nc));
                }
            }
        }
        return count;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Generates the output grid as a list of strings.
     */
    public List<String> generateResult() {
        List<String> result = new ArrayList<>();

        for (int r = 0; r < rows; r++) {
            StringBuilder rowBuilder = new StringBuilder();
            for (int c = 0; c < cols; c++) {
                if (isObstacle[r][c]) {
                    rowBuilder.append(calculateObstacleValue(r, c));
                } else {
                    rowBuilder.append(".");
                }
            }
            result.add(rowBuilder.toString());
        }
        return result;
    }

    private int calculateObstacleValue(int r, int c) {
        Set<Integer> adjacentComponentIds = new HashSet<>();

        for (int i = 0; i < 4; i++) {
            int nr = r + DIRECTION_Y[i];
            int nc = c + DIRECTION_X[i];

            if (isValid(nr, nc) && componentIds[nr][nc] != -1) {
                adjacentComponentIds.add(componentIds[nr][nc]);
            }
        }

        int totalAdjacentSize = 1; // Starts with 1 as per logic requirement
        for (int id : adjacentComponentIds) {
            totalAdjacentSize += componentSizes[id];
        }

        return totalAdjacentSize % 10;
    }

    public static void main(String[] args) {
        try (BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(System.out)) {

            String line = in.readLine();
            if (line == null) return;

            String[] dimensions = line.trim().split("\\s+");
            int rows = Integer.parseInt(dimensions[0]);
            int cols = Integer.parseInt(dimensions[1]);

            boolean[][] isObstacle = new boolean[rows][cols];
            for (int r = 0; r < rows; r++) {
                String rowString = in.readLine();
                for (int c = 0; c < cols; c++) {
                    isObstacle[r][c] = (rowString.charAt(c) == '*');
                }
            }

            GridAnalyzer analyzer = new GridAnalyzer(rows, cols, isObstacle);
            analyzer.findComponents();

            List<String> outputGrid = analyzer.generateResult();
            for (String row : outputGrid) {
                out.println(row);
            }
            out.flush();

        } catch (IOException | NumberFormatException e) {
            e.printStackTrace();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.*;

/**
 * GridSolver identifies connected components of '.' cells in a grid.
 * It then calculates a new value for each '*' cell based on the sum of the 
 * sizes of its unique adjacent '.' components.
 */
public class GridSolver {

    private static final char DOT = '.';
    private static final char STAR = '*';
    private static final char VISITED = '_';

    // Directional offsets for 4-way connectivity (Up, Down, Left, Right)
    private static final int[] ROW_OFFSETS = {1, -1, 0, 0};
    private static final int[] COL_OFFSETS = {0, 0, 1, -1};

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int[][] componentIdMap;
    private final Map<Integer, Integer> componentSizeMap;

    public GridSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.componentIdMap = new int[rows][cols];
        this.componentSizeMap = new HashMap<>();
    }

    /**
     * Orchestrates the component discovery and result printing.
     */
    public void solve() {
        findComponents();
        printResult();
    }

    /**
     * Scans the grid to find and label all connected components of '.' cells.
     */
    private void findComponents() {
        int nextComponentId = 1;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == DOT) {
                    int size = performBFS(r, c, nextComponentId);
                    componentSizeMap.put(nextComponentId, size);
                    nextComponentId++;
                }
            }
        }
    }

    /**
     * Standard Breadth-First Search to traverse a component and mark its cells.
     */
    private int performBFS(int startR, int startC, int id) {
        int size = 0;
        Deque<Point> queue = new ArrayDeque<>();

        // Mark as visited immediately to prevent redundant queuing
        grid[startR][startC] = VISITED;
        componentIdMap[startR][startC] = id;
        queue.addLast(new Point(startR, startC));

        while (!queue.isEmpty()) {
            Point current = queue.removeFirst();
            size++;

            for (int i = 0; i < 4; i++) {
                int nr = current.r + ROW_OFFSETS[i];
                int nc = current.c + COL_OFFSETS[i];

                if (isWithinBounds(nr, nc) && grid[nr][nc] == DOT) {
                    grid[nr][nc] = VISITED;
                    componentIdMap[nr][nc] = id;
                    queue.addLast(new Point(nr, nc));
                }
            }
        }
        return size;
    }

    /**
     * Iterates through the grid and prints the transformed values.
     */
    private void printResult() {
        PrintWriter out = new PrintWriter(System.out);
        for (int r = 0; r < rows; r++) {
            StringBuilder rowBuilder = new StringBuilder();
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == STAR) {
                    rowBuilder.append(calculateStarValue(r, c));
                } else {
                    // If it was '.', it's now '_', but we output '.' as per original logic
                    rowBuilder.append(DOT);
                }
            }
            out.println(rowBuilder.toString());
        }
        out.flush();
    }

    /**
     * Calculates the value for a '*' cell: 1 + sum of unique adjacent component sizes.
     */
    private int calculateStarValue(int r, int c) {
        int totalSum = 1;
        Set<Integer> adjacentComponentIds = new HashSet<>();

        for (int i = 0; i < 4; i++) {
            int nr = r + ROW_OFFSETS[i];
            int nc = c + COL_OFFSETS[i];

            if (isWithinBounds(nr, nc)) {
                int id = componentIdMap[nr][nc];
                // If id > 0, the neighbor belongs to a discovered '.' component
                if (id > 0 && !adjacentComponentIds.contains(id)) {
                    totalSum += componentSizeMap.get(id);
                    adjacentComponentIds.add(id);
                }
            }
        }
        return totalSum % 10;
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Simple data carrier for grid coordinates.
     */
    private static class Point {
        final int r, c;
        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    public static void main(String[] args) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String firstLine = reader.readLine();
            if (firstLine == null) return;

            String[] dimensions = firstLine.trim().split("\\s+");
            int r = Integer.parseInt(dimensions[0]);
            int c = Integer.parseInt(dimensions[1]);

            char[][] grid = new char[r][c];
            for (int i = 0; i < r; i++) {
                String line = reader.readLine();
                if (line != null) {
                    grid[i] = line.toCharArray();
                }
            }

            GridSolver solver = new GridSolver(r, c, grid);
            solver.solve();

        } catch (IOException | NumberFormatException e) {
            System.err.println("Error processing input: " + e.getMessage());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * GridIslandAnalyzer identifies connected components (islands) of empty spaces in a grid
 * and calculates a value for each block ('*') based on the sizes of its adjacent islands.
 */
public class GridIslandAnalyzer {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            char[][] layout = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                layout[i] = reader.next().toCharArray();
            }

            Grid grid = new Grid(rows, cols, layout);
            IslandAnalyzer analyzer = new IslandAnalyzer(grid);
            analyzer.analyze();

            printResults(grid, out);

        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    private static void printResults(Grid grid, PrintWriter out) {
        for (int r = 0; r < grid.getRows(); r++) {
            for (int c = 0; c < grid.getCols(); c++) {
                if (!grid.isBlock(r, c)) {
                    out.print(".");
                } else {
                    out.print(grid.calculateBlockValue(r, c));
                }
            }
            out.println();
        }
    }

    /**
     * Represents the spatial layout of the grid.
     */
    static class Grid {
        private final int rows;
        private final int cols;
        private final boolean[][] blockMap;
        private final int[][] islandIdMap;
        private final List<Integer> islandSizes;

        private static final int UNASSIGNED = -1;

        public Grid(int rows, int cols, char[][] layout) {
            this.rows = rows;
            this.cols = cols;
            this.blockMap = new boolean[rows][cols];
            this.islandIdMap = new int[rows][cols];
            this.islandSizes = new ArrayList<>();

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    this.blockMap[r][c] = (layout[r][c] == '*');
                    this.islandIdMap[r][c] = UNASSIGNED;
                }
            }
        }

        public int getRows() { return rows; }
        public int getCols() { return cols; }

        public boolean isBlock(int r, int c) {
            return blockMap[r][c];
        }

        public boolean isInBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        public int getIslandId(int r, int c) {
            return islandIdMap[r][c];
        }

        public void setIslandId(int r, int c, int id) {
            islandIdMap[r][c] = id;
        }

        public void addIslandSize(int size) {
            islandSizes.add(size);
        }

        public int getIslandSize(int id) {
            return islandSizes.get(id);
        }

        /**
         * Calculates the sum of sizes of unique adjacent islands plus 1, modulo 10.
         */
        public int calculateBlockValue(int r, int c) {
            long totalSize = 1;
            Set<Integer> adjacentIslandIds = new HashSet<>();

            int[][] directions = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
            for (int[] dir : directions) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                if (isInBounds(nr, nc) && !blockMap[nr][nc]) {
                    int islandId = islandIdMap[nr][nc];
                    if (islandId != UNASSIGNED && adjacentIslandIds.add(islandId)) {
                        totalSize += getIslandSize(islandId);
                    }
                }
            }
            return (int) (totalSize % 10);
        }
    }

    /**
     * Handles the logic for identifying and measuring islands via BFS.
     */
    static class IslandAnalyzer {
        private final Grid grid;
        private static final int[][] DIRECTIONS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

        public IslandAnalyzer(Grid grid) {
            this.grid = grid;
        }

        public void analyze() {
            int currentIslandId = 0;
            for (int r = 0; r < grid.getRows(); r++) {
                for (int c = 0; c < grid.getCols(); c++) {
                    if (!grid.isBlock(r, c) && grid.getIslandId(r, c) == -1) {
                        int size = performBFS(r, c, currentIslandId);
                        grid.addIslandSize(size);
                        currentIslandId++;
                    }
                }
            }
        }

        private int performBFS(int startR, int startC, int id) {
            int size = 0;
            Deque<Point> queue = new ArrayDeque<>();

            grid.setIslandId(startR, startC, id);
            queue.add(new Point(startR, startC));
            size++;

            while (!queue.isEmpty()) {
                Point p = queue.poll();

                for (int[] dir : DIRECTIONS) {
                    int nr = p.r + dir[0];
                    int nc = p.c + dir[1];

                    if (grid.isInBounds(nr, nc) && !grid.isBlock(nr, nc) && grid.getIslandId(nr, nc) == -1) {
                        grid.setIslandId(nr, nc, id);
                        queue.add(new Point(nr, nc));
                        size++;
                    }
                }
            }
            return size;
        }

        private static class Point {
            final int r, c;
            Point(int r, int c) { this.r = r; this.c = c; }
        }
    }

    /**
     * Fast I/O utility.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * MazeTransformer processes a grid of '.' (paths) and '#' (obstacles).
 * It identifies connected components of path cells and calculates a value 
 * for each obstacle cell based on the sum of the sizes of its adjacent path components.
 */
public class MazeTransformer {

    private static final int[][] DIRECTIONS = {
        {0, 1}, {0, -1}, {-1, 0}, {1, 0}
    };

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int[][] componentIds;
    private final int[] componentSizes;

    public MazeTransformer(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.componentIds = new int[rows][cols];
        // In the worst case, every cell is its own component
        this.componentSizes = new int[rows * cols + 1];
    }

    /**
     * Executes the main algorithm: identifies components and transforms the grid.
     */
    public void solve() {
        int currentId = 0;

        // Step 1: Identify all connected components of '.' cells using iterative DFS
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.' && componentIds[i][j] == 0) {
                    currentId++;
                    floodFill(i, j, currentId);
                }
            }
        }

        // Step 2: Construct and print the result grid
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.') {
                    out.print('.');
                } else {
                    out.print(calculateObstacleValue(i, j));
                }
            }
            out.println();
        }
        out.flush();
        out.close();
    }

    /**
     * Uses an iterative approach to perform flood fill and assign component IDs.
     */
    private void floodFill(int startX, int startY, int id) {
        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{startX, startY});
        componentIds[startX][startY] = id;
        int count = 0;

        while (!stack.isEmpty()) {
            int[] curr = stack.pop();
            int x = curr[0];
            int y = curr[1];
            count++;

            for (int[] dir : DIRECTIONS) {
                int nx = x + dir[0];
                int ny = y + dir[1];

                if (isValid(nx, ny) && grid[nx][ny] == '.' && componentIds[nx][ny] == 0) {
                    componentIds[nx][ny] = id; // Mark as visited immediately to prevent duplicate stack entries
                    stack.push(new int[]{nx, ny});
                }
            }
        }
        componentSizes[id] = count;
    }

    /**
     * Calculates the value for a '#' cell: 1 + sum(sizes of unique adjacent path components) % 10.
     */
    private char calculateObstacleValue(int r, int c) {
        int sum = 1;
        // Track unique component IDs encountered in the 4 directions
        int[] seenIds = new int[4];
        int seenCount = 0;

        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            if (isValid(nr, nc) && grid[nr][nc] == '.') {
                int id = componentIds[nr][nc];
                if (id != 0) {
                    boolean alreadyProcessed = false;
                    for (int i = 0; i < seenCount; i++) {
                        if (seenIds[i] == id) {
                            alreadyProcessed = true;
                            break;
                        }
                    }
                    if (!alreadyProcessed) {
                        sum += componentSizes[id];
                        seenIds[seenCount++] = id;
                    }
                }
            }
        }
        return (char) ('0' + (sum % 10));
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    public static void main(String[] args) {
        try {
            FastReader reader = new FastReader(System.in);
            String firstLine = reader.nextLine();
            if (firstLine == null || firstLine.trim().isEmpty()) return;

            String[] dimensions = firstLine.trim().split("\\s+");
            int n = Integer.parseInt(dimensions[0]);
            int m = Integer.parseInt(dimensions[1]);

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                String line = reader.nextLine();
                for (int j = 0; j < m; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }

            MazeTransformer transformer = new MazeTransformer(n, m, grid);
            transformer.solve();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /**
     * High-performance reader for large input datasets.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String nextLine() throws IOException {
            return br.readLine();
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A refactored solution for the grid processing task.
 * This program identifies connected components of '.' cells and updates '*' cells 
 * based on the sum of the sizes of their unique adjacent components.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            GridSolver solver = new GridSolver(reader);
            solver.solve(writer);
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    /**
     * Core engine responsible for processing the grid logic.
     */
    static class GridSolver {
        private static final int[] DX = {-1, 0, 1, 0};
        private static final int[] DY = {0, -1, 0, 1};

        private final FastReader reader;
        private int rows;
        private int cols;
        private char[][] grid;
        private int[][] componentIds;
        private int[] componentSizes;
        private int componentCount;

        public GridSolver(FastReader reader) {
            this.reader = reader;
        }

        /**
         * Orchestrates the steps of the solver.
         */
        public void solve(PrintWriter writer) throws IOException {
            // 1. Parse dimensions and grid content
            this.rows = reader.nextInt();
            this.cols = reader.nextInt();
            this.grid = new char[rows][];
            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                if (line == null) throw new IOException("Unexpected end of input");
                grid[i] = line.toCharArray();
            }

            // 2. Initialize tracking structures
            // componentIds stores which component index (0 to N-1) a cell belongs to.
            this.componentIds = new int[rows][cols];
            for (int i = 0; i < rows; i++) {
                Arrays.fill(componentIds[i], -1);
            }
            this.componentSizes = new int[rows * cols];
            this.componentCount = 0;

            // 3. Identify connected components of '.' cells using iterative BFS
            identifyComponents();

            // 4. Calculate and update '*' cells
            calculateStarValues();

            // 5. Output the final grid
            for (int i = 0; i < rows; i++) {
                writer.println(new String(grid[i]));
            }
        }

        /**
         * Scans the grid for unvisited '.' cells to start new component identification.
         */
        private void identifyComponents() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.' && componentIds[r][c] == -1) {
                        performBFS(r, c, componentCount++);
                    }
                }
            }
        }

        /**
         * Uses BFS to find all connected '.' cells and assign them a unique component ID.
         */
        private void performBFS(int startR, int startC, int compId) {
            Deque<Integer> queue = new ArrayDeque<>();
            queue.add(startR * cols + startC);
            componentIds[startR][startC] = compId;
            int size = 0;

            while (!queue.isEmpty()) {
                int pos = queue.poll();
                int r = pos / cols;
                int c = pos % cols;
                size++;

                for (int i = 0; i < 4; i++) {
                    int nr = r + DX[i];
                    int nc = c + DY[i];

                    if (isValid(nr, nc) && grid[nr][nc] == '.' && componentIds[nr][nc] == -1) {
                        // Mark as visited immediately upon adding to queue to prevent duplicate processing
                        componentIds[nr][nc] = compId;
                        queue.add(nr * cols + nc);
                    }
                }
            }
            componentSizes[compId] = size;
        }

        /**
         * Updates '*' cells based on the sizes of adjacent '.' components.
         */
        private void calculateStarValues() {
            // To avoid re-allocating sets or boolean arrays for every '*', 
            // we use a 'timestamp' array to track which components were seen for the current cell.
            int[] lastVisitedCompId = new int[rows * cols];
            Arrays.fill(lastVisitedCompId, -1);
            int starIterationTracker = 0;

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '*') {
                        int totalValue = 1; // The problem logic starts with a base of 1

                        for (int i = 0; i < 4; i++) {
                            int nr = r + DX[i];
                            int nc = c + DY[i];

                            if (isValid(nr, nc) && componentIds[nr][nc] != -1) {
                                int compId = componentIds[nr][nc];
                                // Only add the size if this component hasn't been added for this specific '*'
                                if (lastVisitedCompId[compId] != starIterationTracker) {
                                    lastVisitedCompId[compId] = starIterationTracker;
                                    totalValue += componentSizes[compId];
                                }
                            }
                        }

                        // Transform '*' into the digit representing (totalValue % 10)
                        grid[r][c] = (char) ('0' + (totalValue % 10));
                        starIterationTracker++;
                    }
                }
            }
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * A utility class for high-performance input reading.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            String next = next();
            return next == null ? 0 : Integer.parseInt(next);
        }
    }
}

import java.util.*;

/**
 * A program to solve a labyrinth puzzle where walls (*) are replaced 
 * by the last digit of the sum of the sizes of adjacent connected path components.
 */
public class Labyrinth {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String rowString = scanner.next();
            grid[i] = rowString.toCharArray();
        }

        LabyrinthSolver solver = new LabyrinthSolver(rows, cols, grid);
        System.out.print(solver.solve());
    }
}

class LabyrinthSolver {
    private final int rows;
    private final int cols;
    private final char[][] grid;

    private final int[][] componentIds;
    private final List<Integer> componentSizes;

    private static final int[][] DIRECTIONS = {
        {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    public LabyrinthSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.componentIds = new int[rows][cols];
        this.componentSizes = new ArrayList<>();

        // Initialize component IDs with -1 (indicating no component)
        for (int i = 0; i < rows; i++) {
            Arrays.fill(componentIds[i], -1);
        }
    }

    /**
     * Orchestrates the solving process.
     * @return The formatted result string.
     */
    public String solve() {
        findConnectedComponents();
        return generateResultGrid();
    }

    /**
     * Identifies all connected components of '.' cells using iterative DFS.
     */
    private void findConnectedComponents() {
        boolean[][] visited = new boolean[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && !visited[r][c]) {
                    int currentComponentId = componentSizes.size();
                    int size = performDFS(r, c, visited, currentComponentId);
                    componentSizes.add(size);
                }
            }
        }
    }

    /**
     * Iterative DFS to traverse a connected component.
     */
    private int performDFS(int startR, int startC, boolean[][] visited, int componentId) {
        int size = 0;
        Deque<Point> stack = new ArrayDeque<>();

        stack.push(new Point(startR, startC));
        visited[startR][startC] = true;

        while (!stack.isEmpty()) {
            Point current = stack.pop();
            componentIds[current.row][current.col] = componentId;
            size++;

            for (int[] dir : DIRECTIONS) {
                int nr = current.row + dir[0];
                int nc = current.col + dir[1];

                if (isValidPath(nr, nc) && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    stack.push(new Point(nr, nc));
                }
            }
        }
        return size;
    }

    /**
     * Iterates through the grid to build the final output string.
     */
    private String generateResultGrid() {
        StringBuilder output = new StringBuilder();

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    output.append('.');
                } else {
                    output.append(calculateWallValue(r, c));
                }
            }
            output.append('\n');
        }
        return output.toString();
    }

    /**
     * Calculates the digit for a '*' cell based on adjacent component sizes.
     */
    private char calculateWallValue(int r, int c) {
        Set<Integer> uniqueAdjacentComponentIds = new HashSet<>();

        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            if (isValidPath(nr, nc)) {
                int id = componentIds[nr][nc];
                if (id != -1) {
                    uniqueAdjacentComponentIds.add(id);
                }
            }
        }

        int totalSizeSum = 0;
        for (int id : uniqueAdjacentComponentIds) {
            totalSizeSum += componentSizes.get(id);
        }

        return (char) ('0' + (totalSizeSum % 10));
    }

    private boolean isValidPath(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] == '.';
    }

    /**
     * Simple data structure to hold grid coordinates.
     */
    private static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for grid-based connected component counting.
 * The goal is to find components of '.' cells and for every '*' cell,
 * return (1 + sum of sizes of adjacent '.' components) % 10.
 */
public class CF616C {

    public static void main(String[] args) {
        FastReader in = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        GridSolver solver = new GridSolver();
        solver.solve(in, out);

        out.flush();
        out.close();
    }

    static class GridSolver {
        private static final int[] DR = {1, -1, 0, 0};
        private static final int[] DC = {0, 0, 1, -1};

        public void solve(FastReader in, PrintWriter out) {
            int rows = in.nextInt();
            int cols = in.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = in.next().toCharArray();
            }

            int[][] componentId = new int[rows][cols];
            int[] componentSize = new int[rows * cols + 1];
            int currentComponentId = 0;

            // 1. Identify connected components of '.' cells using BFS
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.' && componentId[i][j] == 0) {
                        currentComponentId++;
                        int size = performBFS(grid, componentId, i, j, currentComponentId, rows, cols);
                        componentSize[currentComponentId] = size;
                    }
                }
            }

            // 2. Calculate the result for each '*' cell
            StringBuilder output = new StringBuilder();
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '*') {
                        int totalAdjacentSize = calculateAdjacentComponentSize(grid, componentId, componentSize, i, j, rows, cols);
                        output.append((char) ('0' + (1 + totalAdjacentSize) % 10));
                    } else {
                        output.append('.');
                    }
                }
                output.append('\n');
            }
            out.print(output.toString());
        }

        /**
         * Performs BFS to label a connected component of '.' cells.
         * Uses a primitive array as a queue to avoid object allocation overhead.
         */
        private int performBFS(char[][] grid, int[][] componentId, int startR, int startC, int id, int rows, int cols) {
            int size = 0;
            int[] queueR = new int[rows * cols];
            int[] queueC = new int[rows * cols];
            int head = 0;
            int tail = 0;

            queueR[tail] = startR;
            queueC[tail] = startC;
            tail++;
            componentId[startR][startC] = id;

            while (head < tail) {
                int r = queueR[head];
                int c = queueC[head];
                head++;
                size++;

                for (int i = 0; i < 4; i++) {
                    int nr = r + DR[i];
                    int nc = c + DC[i];

                    if (isValid(nr, nc, rows, cols) && grid[nr][nc] == '.' && componentId[nr][nc] == 0) {
                        componentId[nr][nc] = id;
                        queueR[tail] = nr;
                        queueC[tail] = nc;
                        tail++;
                    }
                }
            }
            return size;
        }

        /**
         * Checks the 4 neighbors of a '*' cell and sums the sizes of unique adjacent '.' components.
         */
        private int calculateAdjacentComponentSize(char[][] grid, int[][] componentId, int[] componentSize, int r, int c, int rows, int cols) {
            int sum = 0;
            int[] foundIds = new int[4];
            int foundCount = 0;

            for (int i = 0; i < 4; i++) {
                int nr = r + DR[i];
                int nc = c + DC[i];

                if (isValid(nr, nc, rows, cols) && grid[nr][nc] == '.') {
                    int id = componentId[nr][nc];

                    // Check if this component ID was already counted for this specific '*' cell
                    boolean alreadyCounted = false;
                    for (int k = 0; k < foundCount; k++) {
                        if (foundIds[k] == id) {
                            alreadyCounted = true;
                            break;
                        }
                    }

                    if (!alreadyCounted) {
                        foundIds[foundCount++] = id;
                        sum += componentSize[id];
                    }
                }
            }
            return sum;
        }

        private boolean isValid(int r, int c, int rows, int cols) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * Fast I/O Reader for competitive programming.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * GridComponentCalculator processes a grid map to identify connected components of empty spaces ('.')
 * and updates obstacle cells ('*') based on the size of adjacent components.
 */
public class GridComponentCalculator {

    private static final int[][] DIRECTIONS = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

    /**
     * Represents a coordinate point in the grid.
     */
    private record Point(int r, int c) {}

    public static void main(String[] args) {
        try {
            GridComponentCalculator app = new GridComponentCalculator();
            app.run();
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    public void run() throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String firstLine = reader.readLine();
        if (firstLine == null) return;

        StringTokenizer st = new StringTokenizer(firstLine);
        int rows = Integer.parseInt(st.nextToken());
        int cols = Integer.parseInt(st.nextToken());

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = reader.readLine().toCharArray();
        }

        processGrid(grid, rows, cols);
        printGrid(grid, rows);
    }

    private void processGrid(char[][] grid, int rows, int cols) {
        int[][] componentIds = new int[rows][cols];
        int[] componentSizes = new int[rows * cols + 1];
        int nextComponentId = 1;

        // Phase 1: Identify connected components of '.' using BFS
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && componentIds[r][c] == 0) {
                    int size = performBFS(grid, r, c, rows, cols, componentIds, nextComponentId);
                    componentSizes[nextComponentId] = size;
                    nextComponentId++;
                }
            }
        }

        // Phase 2: Calculate new values for '*' based on adjacent components
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*') {
                    grid[r][c] = calculateObstacleValue(grid, r, c, rows, cols, componentIds, componentSizes);
                }
            }
        }
    }

    private int performBFS(char[][] grid, int startR, int startC, int rows, int cols, 
                           int[][] componentIds, int currentId) {
        int size = 0;
        Deque<Point> queue = new ArrayDeque<>();

        Point start = new Point(startR, startC);
        queue.add(start);
        componentIds[startR][startC] = currentId;
        size++;

        while (!queue.isEmpty()) {
            Point curr = queue.poll();

            for (int[] dir : DIRECTIONS) {
                int nr = curr.r + dir[0];
                int nc = curr.c + dir[1];

                if (isValid(nr, nc, rows, cols) && grid[nr][nc] == '.' && componentIds[nr][nc] == 0) {
                    componentIds[nr][nc] = currentId;
                    queue.add(new Point(nr, nc));
                    size++;
                }
            }
        }
        return size;
    }

    private char calculateObstacleValue(char[][] grid, int r, int c, int rows, int cols, 
                                       int[][] componentIds, int[] componentSizes) {
        int totalSum = 1; // Start with 1 as per original logic
        Set<Integer> adjacentComponentIds = new HashSet<>();

        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            if (isValid(nr, nc, rows, cols) && grid[nr][nc] == '.') {
                int id = componentIds[nr][nc];
                if (id != 0) {
                    adjacentComponentIds.add(id);
                }
            }
        }

        for (int id : adjacentComponentIds) {
            totalSum += componentSizes[id];
        }

        // Return the last digit of the sum as a character
        return (char) ((totalSum % 10) + '0');
    }

    private boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private void printGrid(char[][] grid, int rows) {
        PrintWriter pw = new PrintWriter(System.out);
        for (int i = 0; i < rows; i++) {
            pw.println(new String(grid[i]));
        }
        pw.flush();
        pw.close();
    }
}

import java.util.*;
import java.io.*;

/**
 * Analyzes a grid containing obstacles ('*') and empty spaces ('.').
 * Identifies connected components of empty spaces and calculates a value for 
 * each obstacle based on the sizes of its adjacent empty space components.
 */
class MazeAnalyzer {
    private static final int[][] DIRECTIONS = {
        {-1, 0}, {0, -1}, {1, 0}, {0, 1}
    };

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int[][] componentIdMap;
    private final int[] componentSizes;

    public MazeAnalyzer(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.componentIdMap = new int[rows][cols];
        // Maximum number of components is (rows * cols) / 2, 
        // but we use rows * cols + 1 for a safe upper bound.
        this.componentSizes = new int[rows * cols + 1];
    }

    /**
     * Orchestrates the component labeling and result calculation.
     * @return A 2D char array representing the processed grid.
     */
    public char[][] solve() {
        labelComponents();
        return calculateResultGrid();
    }

    /**
     * Iterates through the grid to find and label connected components of '.' cells.
     */
    private void labelComponents() {
        int componentCount = 0;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    if (componentIdMap[r][c] == 0) {
                        // Found an unvisited empty space component
                        componentCount++;
                        int size = bfsLabeling(r, c, componentCount);
                        componentSizes[componentCount] = size;
                    }
                } else if (grid[r][c] == '*') {
                    // Mark obstacle cells with a special ID
                    componentIdMap[r][c] = -1;
                }
            }
        }
    }

    /**
     * Uses Breadth-First Search to explore a connected component.
     */
    private int bfsLabeling(int startR, int startC, int componentId) {
        int size = 0;
        Queue<int[]> queue = new ArrayDeque<>();

        queue.add(new int[]{startR, startC});
        componentIdMap[startR][startC] = componentId;
        size++;

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int r = current[0];
            int c = current[1];

            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                if (isValid(nr, nc) && grid[nr][nc] == '.' && componentIdMap[nr][nc] == 0) {
                    componentIdMap[nr][nc] = componentId;
                    size++;
                    queue.add(new int[]{nr, nc});
                }
            }
        }
        return size;
    }

    /**
     * Generates the final grid where obstacles are replaced by calculated values.
     */
    private char[][] calculateResultGrid() {
        char[][] result = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*') {
                    result[r][c] = calculateObstacleValue(r, c);
                } else {
                    result[r][c] = '.';
                }
            }
        }
        return result;
    }

    /**
     * Calculates the value for a specific obstacle cell.
     * Value = (1 + sum of sizes of unique adjacent '.' components) % 10.
     */
    private char calculateObstacleValue(int r, int c) {
        Set<Integer> adjacentComponentIds = new HashSet<>();
        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            if (isValid(nr, nc)) {
                int id = componentIdMap[nr][nc];
                // Only add component IDs > 0 (ignores unvisited or obstacle cells)
                if (id > 0) {
                    adjacentComponentIds.add(id);
                }
            }
        }

        int totalSizeSum = 1;
        for (int id : adjacentComponentIds) {
            totalSizeSum += componentSizes[id];
        }

        return (char) ('0' + (totalSizeSum % 10));
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

public class Main {
    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            if (!sc.hasNextInt()) return;

            int n = sc.nextInt();
            int m = sc.nextInt();
            char[][] grid = new char[n][m];

            for (int i = 0; i < n; i++) {
                String rowStr = sc.next();
                grid[i] = rowStr.toCharArray();
            }

            MazeAnalyzer analyzer = new MazeAnalyzer(n, m, grid);
            char[][] result = analyzer.solve();

            printGrid(result);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private static void printGrid(char[][] grid) {
        StringBuilder sb = new StringBuilder();
        for (char[] row : grid) {
            sb.append(new String(row)).append('\n');
        }
        System.out.print(sb.toString());
    }
}

import java.util.*;
import java.io.*;

/**
 * A utility class to process a grid where '.' represents empty space 
 * and '*' represents a wall/boundary. The goal is to calculate 
 * a new value for each wall based on the sizes of adjacent empty space components.
 */
class GridProcessor {
    private static final char EMPTY_CELL = '.';
    private static final char WALL_CELL = '*';

    private static final int[][] DIRECTIONS = {
        {0, 1}, {1, 0}, {0, -1}, {-1, 0}
    };

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int[][] componentIds;
    private final int[] componentSizes;
    private int currentComponentId = 0;

    public GridProcessor(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.componentIds = new int[rows][cols];
        for (int[] row : componentIds) {
            Arrays.fill(row, -1);
        }
        this.componentSizes = new int[rows * cols];
    }

    /**
     * Executes the main algorithm: 
     * 1. Identify connected components of empty cells.
     * 2. Calculate the new values for wall cells.
     * 
     * @return A 2D character array representing the processed grid.
     */
    public char[][] process() {
        identifyComponents();
        return calculateResultGrid();
    }

    /**
     * Iterates through the grid to find all connected components of empty cells using BFS.
     */
    private void identifyComponents() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == EMPTY_CELL && componentIds[i][j] == -1) {
                    bfs(i, j, currentComponentId);
                    currentComponentId++;
                }
            }
        }
    }

    /**
     * Uses Breadth-First Search to label a component and calculate its size.
     */
    private void bfs(int startRow, int startCol, int id) {
        Deque<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[]{startRow, startCol});
        componentIds[startRow][startCol] = id;

        int size = 0;

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int r = current[0];
            int c = current[1];
            size++;

            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                if (isValid(nr, nc) && grid[nr][nc] == EMPTY_CELL && componentIds[nr][nc] == -1) {
                    componentIds[nr][nc] = id;
                    queue.offer(new int[]{nr, nc});
                }
            }
        }
        componentSizes[id] = size;
    }

    /**
     * Calculates the resulting grid based on the neighbors of wall cells.
     */
    private char[][] calculateResultGrid() {
        char[][] resultGrid = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == EMPTY_CELL) {
                    resultGrid[i][j] = EMPTY_CELL;
                } else {
                    resultGrid[i][j] = calculateWallValue(i, j);
                }
            }
        }
        return resultGrid;
    }

    /**
     * Determines the value of a wall cell: (1 + sum of sizes of unique adjacent components) % 10.
     */
    private char calculateWallValue(int r, int c) {
        Set<Integer> adjacentComponentIds = new HashSet<>();

        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            if (isValid(nr, nc) && grid[nr][nc] == EMPTY_CELL) {
                int id = componentIds[nr][nc];
                if (id != -1) {
                    adjacentComponentIds.add(id);
                }
            }
        }

        int sum = 1;
        for (int id : adjacentComponentIds) {
            sum += componentSizes[id];
        }

        return (char) ((sum % 10) + '0');
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

public class Solution {
    public static void main(String[] args) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter writer = new PrintWriter(System.out)) {

            String line = reader.readLine();
            if (line == null) return;

            String[] dimensions = line.split(" ");
            int rows = Integer.parseInt(dimensions[0]);
            int cols = Integer.parseInt(dimensions[1]);

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.readLine().toCharArray();
            }

            GridProcessor processor = new GridProcessor(rows, cols, grid);
            char[][] result = processor.process();

            for (int i = 0; i < rows; i++) {
                writer.println(new String(result[i]));
            }
            writer.flush();

        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        } catch (NumberFormatException e) {
            System.err.println("Invalid input format: " + e.getMessage());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * GridComponentAnalyzer processes a grid to identify connected components of '.' characters
 * and calculates a specific value for each '#' cell based on its adjacent components.
 */
public class GridComponentAnalyzer {

    // Directions for 4-way connectivity (Right, Left, Down, Up)
    private static final int[] DX = {0, 0, 1, -1};
    private static final int[] DY = {1, -1, 0, 0};

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int[][] componentIds;
    private final int[] componentSizes;

    /**
     * Initializes the analyzer with the grid dimensions and content.
     * 
     * @param rows Number of rows in the grid
     * @param cols Number of columns in the grid
     * @param grid The 2D character array representing the grid
     */
    public GridComponentAnalyzer(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.componentIds = new int[rows][cols];
        // Maximum possible components in a grid is rows * cols / 2
        this.componentSizes = new int[rows * cols + 1];
    }

    /**
     * Orchestrates the analysis: finds components and generates the resulting grid.
     */
    public void solve() throws IOException {
        findComponents();
        printResult();
    }

    /**
     * Uses BFS to identify all connected components of '.' cells.
     */
    private void findComponents() {
        int componentCount = 0;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                // If we find an unvisited '.' cell, start a new component discovery
                if (grid[r][c] == '.' && componentIds[r][c] == 0) {
                    componentCount++;
                    int size = performBFS(r, c, componentCount);
                    componentSizes[componentCount] = size;
                }
            }
        }
    }

    /**
     * Performs an iterative BFS to find all cells in a component.
     * 
     * @param startR Starting row
     * @param startC Starting column
     * @param id The unique ID to assign to this component
     * @return Total number of cells in the component
     */
    private int performBFS(int startR, int startC, int id) {
        int size = 0;
        Deque<int[]> queue = new ArrayDeque<>();

        queue.add(new int[]{startR, startC});
        componentIds[startR][startC] = id;

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int r = current[0];
            int c = current[1];
            size++;

            for (int i = 0; i < 4; i++) {
                int nr = r + DX[i];
                int nc = c + DY[i];

                if (isValid(nr, nc) && grid[nr][nc] == '.' && componentIds[nr][nc] == 0) {
                    componentIds[nr][nc] = id;
                    queue.add(new int[]{nr, nc});
                }
            }
        }
        return size;
    }

    /**
     * Iterates through the grid and prints either '.' or the calculated value for '#' cells.
     */
    private void printResult() throws IOException {
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    out.print(".");
                } else {
                    out.print(calculateValueForHashCell(r, c));
                }
            }
            out.println();
        }
        out.flush();
        out.close();
    }

    /**
     * Calculates the sum of the sizes of unique adjacent '.' components + 1, modulo 10.
     */
    private int calculateValueForHashCell(int r, int c) {
        int sumOfAdjacentSizes = 0;
        Set<Integer> uniqueAdjacentIds = new HashSet<>();

        for (int i = 0; i < 4; i++) {
            int nr = r + DX[i];
            int nc = c + DY[i];

            if (isValid(nr, nc) && componentIds[nr][nc] != 0) {
                uniqueAdjacentIds.add(componentIds[nr][nc]);
            }
        }

        for (int id : uniqueAdjacentIds) {
            sumOfAdjacentSizes += componentSizes[id];
        }

        return (sumOfAdjacentSizes + 1) % 10;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Entry point of the program.
     */
    public static void main(String[] args) {
        try {
            FastReader reader = new FastReader(System.in);
            int n = reader.nextInt();
            int m = reader.nextInt();

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                grid[i] = reader.next().toCharArray();
            }

            GridComponentAnalyzer analyzer = new GridComponentAnalyzer(n, m, grid);
            analyzer.solve();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /**
     * Fast I/O helper class.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
            tokenizer = null;
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
