/**
 * A solver for the grid-based component size problem.
 * The goal is to find connected components of empty spaces ('.') and, 
 * for every wall ('*'), calculate the sum of the sizes of its unique 
 * adjacent empty space components.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            if (rows <= 0 || cols <= 0) {
                return;
            }

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            GridSolver solver = new GridSolver(rows, cols, grid);
            out.print(solver.solve());

        } catch (Exception e) {
            // In a production environment, use a logger
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Fast I/O class to replace the custom complex Reader.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /**
     * Encapsulates the logic for solving the grid problem.
     */
    static class GridSolver {
        private static final int MODULO = 10;
        private static final char EMPTY = '.';
        private static final char WALL = '*';
        private static final int[][] DIRECTIONS = {
            {-1, 0}, {1, 0}, {0, -1}, {0, 1}
        };

        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final int[][] componentIdMap;
        private final List<Integer> componentSizes;

        public GridSolver(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            this.componentIdMap = new int[rows][cols];
            this.componentSizes = new ArrayList<>();

            // Initialize ID map with -1 (unvisited)
            for (int i = 0; i < rows; i++) {
                Arrays.fill(componentIdMap[i], -1);
            }
        }

        /**
         * Orchestrates the solving process.
         * @return The formatted result as a String.
         */
        public String solve() {
            identifyComponents();
            return buildResultString();
        }

        /**
         * Traverses the grid to find all connected components of '.' cells.
         */
        private void identifyComponents() {
            int currentComponentId = 0;
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == EMPTY && componentIdMap[i][j] == -1) {
                        int size = performBFS(i, j, currentComponentId);
                        componentSizes.add(size);
                        currentComponentId++;
                    }
                }
            }
        }

        /**
         * Uses BFS to find all reachable '.' cells in a single component.
         */
        private int performBFS(int startR, int startC, int componentId) {
            int size = 0;
            Queue<int[]> queue = new LinkedList<>();

            queue.offer(new int[]{startR, startC});
            componentIdMap[startR][startC] = componentId;

            while (!queue.isEmpty()) {
                int[] current = queue.poll();
                int r = current[0];
                int c = current[1];
                size++;

                for (int[] dir : DIRECTIONS) {
                    int nr = r + dir[0];
                    int nc = c + dir[1];

                    if (isValid(nr, nc) && grid[nr][nc] == EMPTY && componentIdMap[nr][nc] == -1) {
                        componentIdMap[nr][nc] = componentId;
                        queue.offer(new int[]{nr, nc});
                    }
                }
            }
            return size;
        }

        /**
         * Builds the final grid output by checking neighbors of each wall.
         */
        private String buildResultString() {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == WALL) {
                        sb.append(calculateWallValue(i, j));
                    } else {
                        sb.append(EMPTY);
                    }
                }
                sb.append('\n');
            }
            return sb.toString();
        }

        private int calculateWallValue(int r, int c) {
            Set<Integer> adjacentComponentIds = new HashSet<>();

            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                if (isValid(nr, nc) && grid[nr][nc] == EMPTY) {
                    int id = componentIdMap[nr][nc];
                    if (id != -1) {
                        adjacentComponentIds.add(id);
                    }
                }
            }

            int totalAdjacentSize = 0;
            for (int id : adjacentComponentIds) {
                totalAdjacentSize += componentSizes.get(id);
            }

            return (totalAdjacentSize + 1) % MODULO;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver for grid-based component analysis.
 * It identifies connected components of '.' cells and calculates 
 * a value for each '*' cell based on the sizes of adjacent components.
 */
public class C616 {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] grid = reader.readGrid(rows, cols);

            GridSolver solver = new GridSolver(rows, cols, grid);
            solver.solve(out);
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.close();
        }
    }

    static class GridSolver {
        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final int[][] componentIds;
        private final List<Integer> componentSizes;

        private static final int[] DIRECTIONS_Y = {0, -1, 0, 1};
        private static final int[] DIRECTIONS_X = {-1, 0, 1, 0};

        public GridSolver(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            this.componentIds = new int[rows][cols];
            this.componentSizes = new ArrayList<>();

            // Initialize component IDs with -1 (unvisited)
            for (int i = 0; i < rows; i++) {
                Arrays.fill(componentIds[i], -1);
            }
        }

        public void solve(PrintWriter out) {
            identifyComponents();
            printResultGrid(out);
        }

        /**
         * Uses iterative BFS to find all connected components of '.' cells.
         */
        private void identifyComponents() {
            int currentId = 0;

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.' && componentIds[r][c] == -1) {
                        int size = bfs(r, c, currentId);
                        componentSizes.add(size);
                        currentId++;
                    }
                }
            }
        }

        private int bfs(int startY, int startX, int id) {
            int size = 0;
            Deque<int[]> queue = new ArrayDeque<>();

            queue.offer(new int[]{startY, startX});
            componentIds[startY][startX] = id;
            size++;

            while (!queue.isEmpty()) {
                int[] cell = queue.poll();
                int y = cell[0];
                int x = cell[1];

                for (int i = 0; i < 4; i++) {
                    int ny = y + DIRECTIONS_Y[i];
                    int nx = x + DIRECTIONS_X[i];

                    if (isValid(ny, nx) && grid[ny][nx] == '.' && componentIds[ny][nx] == -1) {
                        componentIds[ny][nx] = id;
                        size++;
                        queue.offer(new int[]{ny, nx});
                    }
                }
            }
            return size;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        /**
         * Iterates through the grid and calculates the requested value for '*' cells.
         */
        private void printResultGrid(PrintWriter out) {
            StringBuilder sb = new StringBuilder();
            for (int r = 0; r < rows; r++) {
                sb.setLength(0);
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '*') {
                        sb.append(calculateStarValue(r, c));
                    } else {
                        sb.append('.');
                    }
                }
                out.println(sb.toString());
            }
        }

        private int calculateStarValue(int r, int c) {
            int sumOfNeighborSizes = 1;
            Set<Integer> seenComponents = new HashSet<>();

            for (int i = 0; i < 4; i++) {
                int ny = r + DIRECTIONS_Y[i];
                int nx = c + DIRECTIONS_X[i];

                if (isValid(ny, nx) && componentIds[ny][nx] != -1) {
                    int id = componentIds[ny][nx];
                    if (!seenComponents.contains(id)) {
                        sumOfNeighborSizes += componentSizes.get(id);
                        seenComponents.add(id);
                    }
                }
            }
            return sumOfNeighborSizes % 10;
        }
    }

    /**
     * Utility class for fast input reading.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public char[][] readGrid(int rows, int cols) throws IOException {
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = reader.readLine();
                // Handle potential empty lines from nextInt() leftovers
                if (line == null || line.isEmpty()) {
                    i--; 
                    continue;
                }
                grid[i] = line.toCharArray();
            }
            return grid;
        }
    }
