/**
 * GridProcessor handles the core logic of identifying connected components
 * of '.' characters and transforming non-'.' characters based on adjacent region sizes.
 */
class GridProcessor {
    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int[][] regionIdMap;
    private final int[] regionSizes;

    private static final int[][] DIRECTIONS = {
        {0, 1}, {0, -1}, {1, 0}, {-1, 0}
    };

    public GridProcessor(char[][] grid) {
        this.grid = grid;
        this.rows = grid.length;
        this.cols = grid[0].length;
        this.regionIdMap = new int[rows][cols];
        // Max possible regions is rows * cols
        this.regionSizes = new int[rows * cols + 1];
    }

    /**
     * Orchestrates the processing steps.
     */
    public void process() {
        mapRegions();
        transformNonEmptyCells();
    }

    /**
     * Uses BFS to find all connected components of '.' and assign them unique IDs.
     */
    private void mapRegions() {
        int regionCounter = 1;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && regionIdMap[r][c] == 0) {
                    bfsAssignRegion(r, c, regionCounter++);
                }
            }
        }
    }

    private void bfsAssignRegion(int startR, int startC, int regionId) {
        Queue<int[]> queue = new LinkedList<>();
        queue.add(new int[]{startR, startC});
        regionIdMap[startR][startC] = regionId;
        int size = 0;

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int r = current[0];
            int c = current[1];
            size++;

            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                if (isValid(nr, nc) && grid[nr][nc] == '.' && regionIdMap[nr][nc] == 0) {
                    regionIdMap[nr][nc] = regionId;
                    queue.add(new int[]{nr, nc});
                }
            }
        }
        regionSizes[regionId] = size;
    }

    /**
     * Updates non-'.' cells with the calculated value (1 + sum of adjacent region sizes) % 10.
     */
    private void transformNonEmptyCells() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    continue;
                }

                Set<Integer> adjacentRegions = new HashSet<>();
                for (int[] dir : DIRECTIONS) {
                    int nr = r + dir[0];
                    int nc = c + dir[1];

                    if (isValid(nr, nc) && regionIdMap[nr][nc] != 0) {
                        adjacentRegions.add(regionIdMap[nr][nc]);
                    }
                }

                int sum = 1;
                for (int id : adjacentRegions) {
                    sum += regionSizes[id];
                }

                grid[r][c] = (char) ('0' + (sum % 10));
            }
        }
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    public void printGrid() {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < rows; i++) {
            sb.append(new String(grid[i])).append("\n");
        }
        System.out.print(sb.toString());
    }
}

