import java.util.*;
import java.io.*;

/**
 * Solves the Labyrinth problem by identifying connected components of passable cells
 * and calculating the impact of obstacles on their surrounding components.
 */
public class TheLabyrinth {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        FastWriter writer = new FastWriter(System.out);

        try {
            LabyrinthSolver solver = new LabyrinthSolver(reader);
            solver.solve(writer);
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            reader.close();
            writer.close();
        }
    }

    /**
     * Core logic for processing the labyrinth grid.
     */
    static class LabyrinthSolver {
        private static final char PASSABLE = '.';
        private static final char OBSTACLE = '*';

        private final FastReader reader;
        private int rows;
        private int cols;
        private char[][] grid;

        public LabyrinthSolver(FastReader reader) {
            this.reader = reader;
        }

        public void solve(FastWriter writer) throws IOException {
            this.rows = reader.nextInt();
            this.cols = reader.nextInt();
            this.grid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            DisjointSetUnion dsu = buildDisjointSetUnion();
            char[][] resultGrid = computeResultGrid(dsu);

            for (int i = 0; i < rows; i++) {
                writer.println(new String(resultGrid[i]));
            }
        }

        /**
         * Builds the DSU structure by connecting all adjacent passable cells.
         */
        private DisjointSetUnion buildDisjointSetUnion() {
            DisjointSetUnion dsu = new DisjointSetUnion(rows * cols);

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == PASSABLE) {
                        int currentIdx = getIndex(r, c);
                        // Only need to check right and down to avoid redundant unions
                        unionIfPassable(dsu, r, c, r, c + 1);
                        unionIfPassable(dsu, r, c, r + 1, c);
                    }
                }
            }
            return dsu;
        }

        private void unionIfPassable(DisjointSetUnion dsu, int r1, int c1, int r2, int c2) {
            if (isWithinBounds(r2, c2) && grid[r2][c2] == PASSABLE) {
                dsu.union(getIndex(r1, c1), getIndex(r2, c2));
            }
        }

        /**
         * Calculates the output grid based on component sizes.
         */
        private char[][] computeResultGrid(DisjointSetUnion dsu) {
            char[][] result = new char[rows][cols];

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == PASSABLE) {
                        result[r][c] = PASSABLE;
                    } else {
                        result[r][c] = calculateObstacleValue(r, c, dsu);
                    }
                }
            }
            return result;
        }

        /**
         * For an obstacle, calculates: (1 + sum of sizes of unique adjacent passable components) % 10
         */
        private char calculateObstacleValue(int r, int c, DisjointSetUnion dsu) {
            Set<Integer> uniqueComponentRoots = new HashSet<>();
            int[] dr = {1, -1, 0, 0};
            int[] dc = {0, 0, 1, -1};

            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i];
                int nc = c + dc[i];

                if (isWithinBounds(nr, nc) && grid[nr][nc] == PASSABLE) {
                    uniqueComponentRoots.add(dsu.find(getIndex(nr, nc)));
                }
            }

            int totalSize = 1;
            for (int root : uniqueComponentRoots) {
                totalSize += dsu.getSize(root);
            }

            return (char) ('0' + (totalSize % 10));
        }

        private boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        private int getIndex(int r, int c) {
            return r * cols + c;
        }
    }

    /**
     * Efficient Disjoint Set Union (DSU) implementation with Path Compression and Union by Size.
     */
    static class DisjointSetUnion {
        private final int[] parent;
        private final int[] size;

        public DisjointSetUnion(int n) {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        public int find(int i) {
            while (i != parent[i]) {
                parent[i] = parent[parent[i]]; // Path halving
                i = parent[i];
            }
            return i;
        }

        public void union(int i, int j) {
            int rootI = find(i);
            int rootJ = find(j);
            if (rootI != rootJ) {
                // Union by size
                if (size[rootI] < size[rootJ]) {
                    parent[rootI] = rootJ;
                    size[rootJ] += size[rootI];
                } else {
                    parent[rootJ] = rootI;
                    size[rootI] += size[rootJ];
                }
            }
        }

        public int getSize(int i) {
            return size[find(i)];
        }
    }

    /**
     * High-performance input reader.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public void close() throws IOException {
            reader.close();
        }
    }

    /**
     * High-performance output writer.
     */
    static class FastWriter {
        private final PrintWriter writer;

        public FastWriter(OutputStream stream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(stream)));
        }

        public void println(String s) {
            writer.println(s);
        }

        public void close() {
            writer.flush();
            writer.close();
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * StarGridAnalyzer processes a grid of characters to find connected components 
 * of '.' cells and calculates a sum-based value for '*' cells.
 */
public class StarGridAnalyzer {

    // Represents a coordinate in the grid
    private record Cell(int row, int col) {}

    // Possible movements: Up, Down, Left, Right
    private static final int[][] DIRECTIONS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int[][] componentId;
    private final int[][] componentSize;

    public StarGridAnalyzer(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.componentId = new int[rows][cols];
        this.componentSize = new int[rows][cols];
    }

    /**
     * Orchestrates the component finding and result calculation.
     */
    public void run() {
        findComponents();
        char[][] resultGrid = calculateStarValues();
        printGrid(resultGrid);
    }

    /**
     * Uses BFS to identify all connected components of '.' cells.
     * Assigns a unique ID and stores the size of the component in each cell.
     */
    private void findComponents() {
        boolean[][] visited = new boolean[rows][cols];
        int currentId = 1;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && !visited[r][c]) {
                    List<Cell> componentCells = new ArrayList<>();
                    Queue<Cell> queue = new ArrayDeque<>();

                    Cell start = new Cell(r, c);
                    visited[r][c] = true;
                    queue.add(start);
                    componentCells.add(start);

                    while (!queue.isEmpty()) {
                        Cell current = queue.poll();

                        for (int[] dir : DIRECTIONS) {
                            int nr = current.row + dir[0];
                            int nc = current.col + dir[1];

                            if (isValid(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                                visited[nr][nc] = true;
                                Cell next = new Cell(nr, nc);
                                queue.add(next);
                                componentCells.add(next);
                            }
                        }
                    }

                    // Once the component is fully traversed, assign ID and size to all its members
                    int size = componentCells.size();
                    for (Cell cell : componentCells) {
                        componentId[cell.row][cell.col] = currentId;
                        componentSize[cell.row][cell.col] = size;
                    }
                    currentId++;
                }
            }
        }
    }

    /**
     * Calculates the new grid values based on the proximity of '*' to '.' components.
     */
    private char[][] calculateStarValues() {
        char[][] result = new char[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*') {
                    int sum = 1; // Base value per original logic
                    Set<Integer> seenComponentIds = new HashSet<>();

                    for (int[] dir : DIRECTIONS) {
                        int nr = r + dir[0];
                        int nc = c + dir[1];

                        if (isValid(nr, nc)) {
                            int id = componentId[nr][nc];
                            // If the neighbor is part of a '.' component and we haven't counted it yet
                            if (id != 0 && !seenComponentIds.contains(id)) {
                                sum += componentSize[nr][nc];
                                seenComponentIds.add(id);
                            }
                        }
                    }
                    // Result is the sum modulo 10
                    result[r][c] = (char) ((sum % 10) + '0');
                } else {
                    // Non-star cells are rendered as '.'
                    result[r][c] = '.';
                }
            }
        }
        return result;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private void printGrid(char[][] result) {
        PrintWriter out = new PrintWriter(System.out);
        for (int r = 0; r < rows; r++) {
            out.println(new String(result[r]));
        }
        out.flush();
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        if (!sc.hasNextInt()) return;
        int n = sc.nextInt();
        int m = sc.nextInt();
        sc.nextLine(); // Consume newline

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String line = sc.nextLine();
            grid[i] = line.toCharArray();
        }

        StarGridAnalyzer analyzer = new StarGridAnalyzer(n, m, grid);
        analyzer.run();

        sc.close();
    }
}

import java.util.*;
import java.io.*;

/**
 * Analyzes a grid of '*' and '.' characters.
 * It identifies connected components of '.' and, for every '*', 
 * calculates the sum of the sizes of its adjacent '.' components.
 */
public class GridComponentAnalyzer {

    private static final int[] ROW_DIRECTIONS = {1, -1, 0, 0};
    private static final int[] COL_DIRECTIONS = {0, 0, 1, -1};

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int[][] componentMap;
    private final int[] componentSizes;

    public GridComponentAnalyzer(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.componentMap = new int[rows][cols];
        // Maximum possible components is rows * cols
        this.componentSizes = new int[rows * cols + 1];
    }

    /**
     * Performs an iterative DFS to identify all connected components of '.'
     */
    public void identifyComponents() {
        int currentComponentId = 1;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && componentMap[r][c] == 0) {
                    int size = performIterativeDFS(r, c, currentComponentId);
                    componentSizes[currentComponentId] = size;
                    currentComponentId++;
                }
            }
        }
    }

    private int performIterativeDFS(int startRow, int startCol, int componentId) {
        int size = 0;
        Deque<Coordinate> stack = new ArrayDeque<>();

        stack.push(new Coordinate(startRow, startCol));
        componentMap[startRow][startCol] = componentId;

        while (!stack.isEmpty()) {
            Coordinate current = stack.pop();
            size++;

            for (int i = 0; i < 4; i++) {
                int nextRow = current.row + ROW_DIRECTIONS[i];
                int nextCol = current.col + COL_DIRECTIONS[i];

                if (isValidNeighbor(nextRow, nextCol)) {
                    componentMap[nextRow][nextCol] = componentId;
                    stack.push(new Coordinate(nextRow, nextCol));
                }
            }
        }
        return size;
    }

    private boolean isValidNeighbor(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols 
               && grid[r][c] == '.' && componentMap[r][c] == 0;
    }

    /**
     * Calculates and prints the resulting grid based on component sizes.
     */
    public void printResult(FastReader out) {
        StringBuilder sb = new StringBuilder();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    sb.append('.');
                } else {
                    sb.append(calculateStarValue(r, c));
                }
            }
            sb.append('\n');
        }
        out.print(sb.toString());
    }

    private int calculateStarValue(int r, int c) {
        int totalAdjacentSize = 1;
        Set<Integer> seenComponents = new HashSet<>();

        for (int i = 0; i < 4; i++) {
            int nr = r + ROW_DIRECTIONS[i];
            int nc = c + COL_DIRECTIONS[i];

            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == '.') {
                int compId = componentMap[nr][nc];
                if (compId != 0 && !seenComponents.contains(compId)) {
                    totalAdjacentSize += componentSizes[compId];
                    seenComponents.add(compId);
                }
            }
        }
        return totalAdjacentSize % 10;
    }

    public static void main(String[] args) {
        FastReader in = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            String line1 = in.next();
            if (line1 == null) return;
            int n = Integer.parseInt(line1);
            int m = in.nextInt();

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                grid[i] = in.next().toCharArray();
            }

            GridComponentAnalyzer analyzer = new GridComponentAnalyzer(n, m, grid);
            analyzer.identifyComponents();
            analyzer.printResult(out);

        } catch (Exception e) {
            // In competitive programming, we usually ignore or print to stderr
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Simple immutable data holder for coordinates.
     */
    private static class Coordinate {
        final int row;
        final int col;

        Coordinate(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Efficient I/O Reader.
     */
    private static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public void print(String s) {
            System.out.print(s);
        }
    }
}

