import java.util.*;

/**
 * MazeSolver solves the problem of calculating the size of connected 
 * components of empty cells ('.') adjacent to obstacle cells ('*').
 */
public class MazeSolver {

    public static void main(String[] args) {
        try (InputStream inputStream = System.in;
             PrintWriter out = new PrintWriter(System.out)) {

            MazeSolver solver = new MazeSolver();
            solver.solve(inputStream, out);

        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /**
     * Core logic for processing the maze.
     */
    public void solve(InputStream inputStream, PrintWriter out) throws IOException {
        FastReader reader = new FastReader(inputStream);

        int rows = reader.nextInt();
        int cols = reader.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = reader.next().toCharArray();
        }

        DisjointSetUnion dsu = new DisjointSetUnion(rows * cols);

        // Step 1: Build connectivity between adjacent '.' cells
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.') {
                    int currentIndex = i * cols + j;

                    // Check top neighbor
                    if (i > 0 && grid[i - 1][j] == '.') {
                        dsu.union(currentIndex, (i - 1) * cols + j);
                    }
                    // Check left neighbor
                    if (j > 0 && grid[i][j - 1] == '.') {
                        dsu.union(currentIndex, i * cols + (j - 1));
                    }
                }
            }
        }

        // Step 2: Process '*' cells and calculate adjacent component sizes
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int i = 0; i < rows; i++) {
            StringBuilder outputRow = new StringBuilder();
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.') {
                    outputRow.append('.');
                } else {
                    int totalSize = 1;
                    Set<Integer> uniqueNeighborRoots = new HashSet<>();

                    // Check all 4 neighbors
                    for (int k = 0; k < 4; k++) {
                        int ni = i + dr[k];
                        int nj = j + dc[k];

                        if (isWithinBounds(ni, nj, rows, cols) && grid[ni][nj] == '.') {
                            uniqueNeighborRoots.add(dsu.find(ni * cols + nj));
                        }
                    }

                    // Sum up sizes of unique connected components
                    for (int root : uniqueNeighborRoots) {
                        totalSize += dsu.getSize(root);
                    }

                    // The problem asks for the last digit of the size
                    outputRow.append(totalSize % 10);
                }
            }
            out.println(outputRow.toString());
        }
    }

    private boolean isWithinBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Disjoint Set Union (DSU) implementation with Path Compression and Union by Size.
     */
    static class DisjointSetUnion {
        private final int[] parent;
        private final int[] size;

        public DisjointSetUnion(int n) {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        public int find(int i) {
            if (parent[i] == i) {
                return i;
            }
            // Path compression
            return parent[i] = find(parent[i]);
        }

        public void union(int i, int j) {
            int rootI = find(i);
            int rootJ = find(j);

            if (rootI != rootJ) {
                // Union by size: attach the smaller tree to the larger tree
                if (size[rootI] < size[rootJ]) {
                    parent[rootI] = rootJ;
                    size[rootJ] += size[rootI];
                } else {
                    parent[rootJ] = rootI;
                    size[rootI] += size[rootJ];
                }
            }
        }

        public int getSize(int i) {
            return size[find(i)];
        }
    }

    /**
     * Fast I/O reader for efficient input processing.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

