/**
 * Handles the core logic of solving the grid problem.
 */
class GridSolver {
    private static final int[] DX = {0, 0, 1, -1};
    private static final int[] DY = {1, -1, 0, 0};

    private final FastReader reader;
    private final PrintWriter writer;

    public GridSolver(FastReader reader, PrintWriter writer) {
        this.reader = reader;
        this.writer = writer;
    }

    public void solve() {
        int rows = reader.nextInt();
        int cols = reader.nextInt();
        char[][] grid = reader.nextCharMap(rows, cols);

        UnionFind uf = new UnionFind(rows * cols);

        // Step 1: Group all connected '.' cells into components using Union-Find
        buildComponents(rows, cols, grid, uf);

        // Step 2: Calculate the value for each cell and build the output
        StringBuilder output = new StringBuilder();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.') {
                    output.append('.');
                } else {
                    output.append(calculateCellResult(i, j, rows, cols, grid, uf));
                }
            }
            output.append('\n');
        }
        writer.print(output.toString());
    }

    private void buildComponents(int rows, int cols, char[][] grid, UnionFind uf) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    for (int k = 0; k < 4; k++) {
                        int nr = r + DX[k];
                        int nc = c + DY[k];

                        if (isWithinBounds(nr, nc, rows, cols) && grid[nr][nc] == '.') {
                            uf.union(r * cols + c, nr * cols + nc);
                        }
                    }
                }
            }
        }
    }

    private int calculateCellResult(int r, int c, int rows, int cols, char[][] grid, UnionFind uf) {
        int totalSize = 1;
        int[] uniqueComponentRoots = new int[4];
        int uniqueCount = 0;

        for (int k = 0; k < 4; k++) {
            int nr = r + DX[k];
            int nc = c + DY[k];

            if (isWithinBounds(nr, nc, rows, cols) && grid[nr][nc] == '.') {
                int root = uf.find(nr * cols + nc);

                // Check if we have already accounted for this component among current neighbors
                boolean alreadyAdded = false;
                for (int i = 0; i < uniqueCount; i++) {
                    if (uniqueComponentRoots[i] == root) {
                        alreadyAdded = true;
                        break;
                    }
                }

                if (!alreadyAdded) {
                    uniqueComponentRoots[uniqueCount++] = root;
                    totalSize += uf.getSize(root);
                }
            }
        }
        return totalSize % 10;
    }

    private boolean isWithinBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

/**
 * Disjoint Set Union (DSU) implementation with path compression and union by size.
 */
class UnionFind {
    // parent[i] < 0 means i is a root, and -parent[i] is the size of the set
    private final int[] parent;

    public UnionFind(int size) {
        parent = new int[size];
        Arrays.fill(parent, -1);
    }

    public int find(int i) {
        if (parent[i] < 0) {
            return i;
        }
        return parent[i] = find(parent[i]);
    }

    public void union(int i, int j) {
        int rootI = find(i);
        int rootJ = find(j);

        if (rootI != rootJ) {
            // Union by size: attach the smaller tree to the larger tree
            if (parent[rootI] < parent[rootJ]) { // rootI has a larger absolute size
                parent[rootI] += parent[rootJ];
                parent[rootJ] = rootI;
            } else {
                parent[rootJ] += parent[rootI];
                parent[rootI] = rootJ;
            }
        }
    }

    public int getSize(int i) {
        return -parent[find(i)];
    }
}

/**
 * Fast I/O reader for efficient processing of large inputs.
 */
class FastReader {
    private final InputStream in;
    private final byte[] buffer = new byte[1024];
    private int pointer = 0;
    private int bufferLength = 0;

    public FastReader(InputStream in) {
        this.in = in;
    }

    private boolean hasNextByte() {
        if (pointer >= bufferLength) {
            pointer = 0;
            try {
                bufferLength = in.read(buffer);
            } catch (IOException e) {
                return false;
            }
            if (bufferLength <= 0) return false;
        }
        return true;
    }

    private int readByte() {
        return hasNextByte() ? buffer[pointer++] : -1;
    }

    private boolean isSpaceChar(int c) {
        return !(c >= 33 && c <= 126);
    }

    public String next() {
        int b = readByte();
        while (b != -1 && isSpaceChar(b)) b = readByte();
        if (b == -1) return null;
        StringBuilder sb = new StringBuilder();
        while (b != -1 && !isSpaceChar(b)) {
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }

    public int nextInt() {
        int c = readByte();
        while (c != -1 && isSpaceChar(c)) c = readByte();
        boolean minus = false;
        if (c == '-') {
            minus = true;
            c = readByte();
        }
        int res = 0;
        do {
            if (c < '0' || c > '9') throw new InputMismatchException();
            res = res * 10 + (c - '0');
            c = readByte();
        } while (c != -1 && !isSpaceChar(c));
        return minus ? -res : res;
    }

    public char[][] nextCharMap(int n, int m) {
        char[][] map = new char[n][m];
        for (int i = 0; i < n; i++) {
            String line = next();
            if (line != null) {
                map[i] = line.toCharArray();
            }
        }
        return map;
    }
}

