/**
 * GridComponentAnalyzer identifies connected components of '.' (dots) in a grid.
 * It replaces every '*' (star) with a value derived from the sizes of its 
 * unique adjacent '.' components.
 */
public class GridComponentAnalyzer {

    private static final int[][] DIRECTIONS = {
            {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    public static void main(String[] args) {
        new GridComponentAnalyzer().solve();
    }

    /**
     * Orchestrates the reading, processing, and output of the grid.
     */
    public void solve() {
        FastReader sc = new FastReader(System.in);

        String rowsStr = sc.next();
        String colsStr = sc.next();
        if (rowsStr == null || colsStr == null) return;

        int rows = Integer.parseInt(rowsStr);
        int cols = Integer.parseInt(colsStr);

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = sc.next();
            if (line != null) {
                grid[i] = line.toCharArray();
            }
        }

        // componentIds[i][j] stores the ID of the component cell (i, j) belongs to.
        // 0 means the cell is either a '*' or not yet visited.
        int[][] componentIds = new int[rows][cols];
        // componentSizes[id] stores the number of cells in that component.
        int[] componentSizes = new int[rows * cols + 1];
        int componentCount = 0;

        // Step 1: Identify connected components of '.' using BFS
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.' && componentIds[i][j] == 0) {
                    componentCount++;
                    int size = performBFS(grid, componentIds, i, j, componentCount, rows, cols);
                    componentSizes[componentCount] = size;
                }
            }
        }

        // Step 2: Construct the result string
        StringBuilder resultBuilder = new StringBuilder();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.') {
                    resultBuilder.append('.');
                } else {
                    resultBuilder.append(calculateStarValue(grid, componentIds, componentSizes, i, j, rows, cols));
                }
            }
            resultBuilder.append('\n');
        }

        System.out.print(resultBuilder.toString());
    }

    /**
     * Performs an iterative BFS to find all connected '.' cells.
     * 
     * @return the size of the discovered component.
     */
    private int performBFS(char[][] grid, int[][] componentIds, int startR, int startC, int id, int rows, int cols) {
        int size = 0;
        Queue<int[]> queue = new ArrayDeque<>();

        queue.offer(new int[]{startR, startC});
        componentIds[startR][startC] = id;

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int r = current[0];
            int c = current[1];
            size++;

            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                if (isValid(nr, nc, rows, cols) && grid[nr][nc] == '.' && componentIds[nr][nc] == 0) {
                    componentIds[nr][nc] = id;
                    queue.offer(new int[]{nr, nc});
                }
            }
        }
        return size;
    }

    /**
     * Calculates the replacement value for a '*' cell based on unique adjacent components.
     */
    private int calculateStarValue(char[][] grid, int[][] componentIds, int[] componentSizes, int r, int c, int rows, int cols) {
        // Use a small array to track unique component IDs found in the 4 adjacent neighbors
        int[] neighborComponentIds = new int[4];
        int uniqueCount = 0;

        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            if (isValid(nr, nc, rows, cols) && grid[nr][nc] == '.') {
                int id = componentIds[nr][nc];

                // Check if we have already encountered this component ID for this '*' cell
                boolean isNew = true;
                for (int i = 0; i < uniqueCount; i++) {
                    if (neighborComponentIds[i] == id) {
                        isNew = false;
                        break;
                    }
                }
                if (isNew) {
                    neighborComponentIds[uniqueCount++] = id;
                }
            }
        }

        // The logic from the original code: 1 + (sum of sizes of unique neighbor components) mod 10
        int val = 1;
        for (int i = 0; i < uniqueCount; i++) {
            val = (val + componentSizes[neighborComponentIds[i]]) % 10;
        }
        return val;
    }

    private boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Fast I/O utility for efficient reading of large inputs.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }
    }
}

