/**
 * Solves the grid-based problem of calculating component sizes 
 * adjacent to obstacles.
 */
class GridProblemSolver {
    private static final int[] DIRECTIONS = { 0, 1, 0, -1, 0 }; // Combined dx, dy for easier iteration

    private int rows;
    private int cols;
    private char[][] grid;
    private int[][] componentIdMap;
    private int[] componentSizes;
    private int componentCounter;

    private static final char EMPTY = '.';
    private static final char OBSTACLE = '*';

    public void solve(InputReader in, PrintWriter out) {
        rows = in.nextInt();
        cols = in.nextInt();
        grid = new char[rows][cols];
        componentIdMap = new int[rows][cols];
        // Maximum possible components is rows * cols
        componentSizes = new int[rows * cols + 1];
        componentCounter = 0;

        for (int i = 0; i < rows; i++) {
            grid[i] = in.next().toCharArray();
        }

        findComponents();
        String result = computeResult();
        out.println(result);
    }

    /**
     * Identifies all connected components of empty cells using BFS.
     */
    private void findComponents() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == EMPTY && componentIdMap[r][c] == 0) {
                    componentCounter++;
                    bfs(r, c, componentCounter);
                }
            }
        }
    }

    private void bfs(int startR, int startC, int id) {
        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[]{startR, startC});
        componentIdMap[startR][startC] = id;
        int size = 0;

        while (!queue.isEmpty()) {
            int[] cell = queue.poll();
            int r = cell[0];
            int c = cell[1];
            size++;

            for (int i = 0; i < 4; i++) {
                int nr = r + DIRECTIONS[i * 2];
                int nc = c + DIRECTIONS[i * 2 + 1];

                if (isValid(nr, nc) && grid[nr][nc] == EMPTY && componentIdMap[nr][nc] == 0) {
                    componentIdMap[nr][nc] = id;
                    queue.offer(new int[]{nr, nc});
                }
            }
        }
        componentSizes[id] = size;
    }

    /**
     * Processes the grid to build the output string.
     */
    private String computeResult() {
        StringBuilder sb = new StringBuilder();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == OBSTACLE) {
                    sb.append(calculateObstacleValue(r, c));
                } else {
                    sb.append(EMPTY);
                }
            }
            sb.append("\n");
        }
        return sb.toString().trim();
    }

    private int calculateObstacleValue(int r, int c) {
        Set<Integer> adjacentComponentIds = new HashSet<>();
        for (int i = 0; i < 4; i++) {
            int nr = r + DIRECTIONS[i * 2];
            int nc = c + DIRECTIONS[i * 2 + 1];

            if (isValid(nr, nc) && grid[nr][nc] == EMPTY) {
                int id = componentIdMap[nr][nc];
                if (id > 0) {
                    adjacentComponentIds.add(id);
                }
            }
        }

        int totalSizeSum = 1; // The problem logic adds 1 to the sum
        for (int id : adjacentComponentIds) {
            totalSizeSum += componentSizes[id];
        }
        return totalSizeSum % 10;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

