    }

    public String next() {
        while (tokenizer == null || !tokenizer.hasMoreElements()) {
            try {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                return null;
            }
        }
        return tokenizer.nextToken();
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }
}

/**
 * Handles the grid processing logic.
 */
class GridAnalyzer {
    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int[][] componentIds;
    private final int[] componentSizes;

    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public GridAnalyzer(int rows, int cols, FastReader reader) {
        this.rows = rows;
        this.cols = cols;
        this.grid = new char[rows][cols];
        this.componentIds = new int[rows][cols];
        // Maximum possible components in a grid is (rows * cols) / 2
        this.componentSizes = new int[rows * cols + 1];

        for (int i = 0; i < rows; i++) {
            String line = reader.next();
            if (line != null) {
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }
        }
    }

    /**
     * Executes the component identification and grid calculation.
     */
    public void solve(PrintWriter out) {
        identifyComponents();
        calculateAndPrint(out);
    }

    /**
     * Uses BFS to find all connected components of '.' cells.
     */
    private void identifyComponents() {
        int nextComponentId = 1;
        int[] queue = new int[rows * cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && componentIds[r][c] == 0) {
                    int size = bfs(r, c, nextComponentId, queue);
                    componentSizes[nextComponentId] = size;
                    nextComponentId++;
                }
            }
        }
    }

    private int bfs(int startR, int startC, int id, int[] queue) {
        int head = 0;
        int tail = 0;
        int size = 0;

        // Store coordinates in a single integer to save memory/object creation
        queue[tail++] = startR * cols + startC;
        componentIds[startR][startC] = id;

        while (head < tail) {
            int pos = queue[head++];
            int r = pos / cols;
            int c = pos % cols;
            size++;

            for (int i = 0; i < 4; i++) {
                int nr = r + DR[i];
                int nc = c + DC[i];

                if (isValid(nr, nc) && grid[nr][nc] == '.' && componentIds[nr][nc] == 0) {
                    componentIds[nr][nc] = id;
                    queue[tail++] = nr * cols + nc;
                }
            }
        }
        return size;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Calculates the neighbor sum for '#' cells and prints the result.
     */
    private void calculateAndPrint(PrintWriter out) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    out.print('.');
                } else {
                    out.print(calculateCellValue(r, c) % 10);
                }
            }
            out.println();
        }
    }

    private int calculateCellValue(int r, int c) {
        int sum = 1;
        int[] neighborIds = new int[4];
        int count = 0;

        // Collect IDs of adjacent components
        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];
            if (isValid(nr, nc) && componentIds[nr][nc] > 0) {
                neighborIds[count++] = componentIds[nr][nc];
            }
        }

        // Sum only unique neighboring components
        for (int i = 0; i < count; i++) {
            boolean isUnique = true;
            for (int j = 0; j < i; j++) {
                if (neighborIds[i] == neighborIds[j]) {
                    isUnique = false;
                    break;
                }
            }
            if (isUnique) {
                sum += componentSizes[neighborIds[i]];
            }
        }
        return sum;
    }
}

public class Main {
    public static void main(String[] args) {
        FastReader sc = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            String nStr = sc.next();
            if (nStr == null) return;
            int n = Integer.parseInt(nStr);
            int m = sc.nextInt();

            if (n > 0 && m > 0) {
                GridAnalyzer analyzer = new GridAnalyzer(n, m, sc);
                analyzer.solve(out);
            }
        } catch (Exception e) {
            // In a real production environment, use a Logger
        } finally {
            out.flush();
            out.close();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * TheLabyrinth refactored for maintainability and robustness.
 * This program calculates a value for each obstacle '*' based on the sizes 
 * of adjacent connected components of empty spaces '.'.
 */
public class TheLabyrinth {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            LabyrinthSolver solver = new LabyrinthSolver(grid, rows, cols);
            solver.solve(writer);

        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Handles the core logic of finding components and calculating results.
     */
    static class LabyrinthSolver {
        private final char[][] grid;
        private final int rows;
        private final int cols;

        private static final int[] ROW_DIR = {1, 0, -1, 0};
        private static final int[] COL_DIR = {0, 1, 0, -1};

        private final int[][] componentIdMap;
        private final List<Integer> componentSizes;

        public LabyrinthSolver(char[][] grid, int rows, int cols) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
            this.componentIdMap = new int[rows][cols];
            this.componentSizes = new ArrayList<>();

            // Initialize map with -1 (no component assigned)
            for (int i = 0; i < rows; i++) {
                Arrays.fill(componentIdMap[i], -1);
            }
        }

        public void solve(PrintWriter writer) {
            identifyComponents();
            generateOutput(writer);
        }

        /**
         * Uses BFS to identify all connected components of '.' and store their sizes.
         */
        private void identifyComponents() {
            int currentComponentId = 0;

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.' && componentIdMap[r][c] == -1) {
                        int size = performBFS(r, c, currentComponentId);
                        componentSizes.add(size);
                        currentComponentId++;
                    }
                }
            }
        }

        private int performBFS(int startR, int startC, int id) {
            Queue<int[]> queue = new LinkedList<>();
            queue.add(new int[]{startR, startC});
            componentIdMap[startR][startC] = id;

            int count = 0;

            while (!queue.isEmpty()) {
                int[] current = queue.poll();
                int r = current[0];
                int c = current[1];
                count++;

                for (int i = 0; i < 4; i++) {
                    int nr = r + ROW_DIR[i];
                    int nc = c + COL_DIR[i];

                    if (isValid(nr, nc) && grid[nr][nc] == '.' && componentIdMap[nr][nc] == -1) {
                        componentIdMap[nr][nc] = id;
                        queue.add(new int[]{nr, nc});
                    }
                }
            }
            return count;
        }

        /**
         * Iterates through the grid and calculates the result for '*' cells.
         */
        private void generateOutput(PrintWriter writer) {
            for (int r = 0; r < rows; r++) {
                StringBuilder rowResult = new StringBuilder();
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '*') {
                        rowResult.append(calculateWallValue(r, c));
                    } else {
                        rowResult.append('.');
                    }
                }
                writer.println(rowResult.toString());
            }
        }

        private int calculateWallValue(int r, int c) {
            Set<Integer> adjacentComponentIds = new HashSet<>();

            for (int i = 0; i < 4; i++) {
                int nr = r + ROW_DIR[i];
                int nc = c + COL_DIR[i];

                if (isValid(nr, nc) && grid[nr][nc] == '.') {
                    int id = componentIdMap[nr][nc];
                    if (id != -1) {
                        adjacentComponentIds.add(id);
                    }
                }
            }

            int sumOfSizes = 1;
            for (int id : adjacentComponentIds) {
                sumOfSizes += componentSizes.get(id);
            }

            return sumOfSizes % 10;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * Optimized reader for faster I/O performance.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * GridAnalyzer processes a grid containing empty spaces ('.') and obstacles ('*').
 * It identifies connected components of empty spaces and calculates a new value
 * for each obstacle based on the sum of the sizes of its unique adjacent components.
 */
public class GridAnalyzer {

    private static final char EMPTY_CELL = '.';
    private static final char OBSTACLE_CELL = '*';

    // Direction vectors for moving Up, Down, Left, Right
    private static final int[] ROW_DIRECTIONS = {-1, 1, 0, 0};
    private static final int[] COL_DIRECTIONS = {0, 0, -1, 1};

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int[][] componentIds;
    private final Map<Integer, Integer> componentSizes;

    public GridAnalyzer(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.componentIds = new int[rows][cols];
        this.componentSizes = new HashMap<>();
    }

    /**
     * Orchestrates the processing of the grid.
     */
    public void process() {
        identifyComponents();
        char[][] resultGrid = calculateResultGrid();
        printGrid(resultGrid);
    }

    /**
     * Finds all connected components of '.' cells using BFS and assigns them unique IDs.
     */
    private void identifyComponents() {
        int currentId = 0;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == EMPTY_CELL && componentIds[r][c] == 0) {
                    currentId++;
                    int size = performBFS(r, c, currentId);
                    componentSizes.put(currentId, size);
                }
            }
        }
    }

    /**
     * Performs an iterative BFS to label a component and calculate its size.
     */
    private int performBFS(int startR, int startC, int id) {
        int size = 0;
        Deque<int[]> queue = new ArrayDeque<>();

        queue.offer(new int[]{startR, startC});
        componentIds[startR][startC] = id;

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int r = current[0];
            int c = current[1];
            size++;

            for (int i = 0; i < 4; i++) {
                int nr = r + ROW_DIRECTIONS[i];
                int nc = c + COL_DIRECTIONS[i];

                if (isValid(nr, nc) && grid[nr][nc] == EMPTY_CELL && componentIds[nr][nc] == 0) {
                    componentIds[nr][nc] = id;
                    queue.offer(new int[]{nr, nc});
                }
            }
        }
        return size;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Creates a new grid where '*' cells are replaced by the calculated digit.
     */
    private char[][] calculateResultGrid() {
        char[][] result = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == OBSTACLE_CELL) {
                    result[r][c] = calculateObstacleValue(r, c);
                } else {
                    result[r][c] = grid[r][c];
                }
            }
        }
        return result;
    }

    /**
     * Sums the sizes of unique adjacent '.' components and returns (sum + 1) % 10 as a char.
     */
    private char calculateObstacleValue(int r, int c) {
        Set<Integer> adjacentComponentIds = new HashSet<>();
        for (int i = 0; i < 4; i++) {
            int nr = r + ROW_DIRECTIONS[i];
            int nc = c + COL_DIRECTIONS[i];

            if (isValid(nr, nc) && grid[nr][nc] == EMPTY_CELL) {
                adjacentComponentIds.add(componentIds[nr][nc]);
            }
        }

        int totalSizeSum = 0;
        for (int id : adjacentComponentIds) {
            totalSizeSum += componentSizes.getOrDefault(id, 0);
        }

        int digitValue = (totalSizeSum + 1) % 10;
        return (char) ('0' + digitValue);
    }

    private void printGrid(char[][] resultGrid) {
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
        for (int r = 0; r < rows; r++) {
            out.println(new String(resultGrid[r]));
        }
        out.flush();
        out.close();
    }

    public static void main(String[] args) throws IOException {
        FastReader reader = new FastReader(System.in);

        String firstLine = reader.nextLine();
        if (firstLine == null || firstLine.isEmpty()) return;

        StringTokenizer st = new StringTokenizer(firstLine);
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String rowStr = reader.nextLine();
            for (int j = 0; j < m; j++) {
                grid[i][j] = rowStr.charAt(j);
            }
        }

        GridAnalyzer analyzer = new GridAnalyzer(n, m, grid);
        analyzer.process();
    }

    /**
     * Fast I/O helper class.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                return null;
            }
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solution to calculate grid values based on adjacent connected component sizes.
 * '.' cells form connected components.
 * '*' cells result in a value of: 1 + sum of the sizes of unique adjacent '.' components.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        FastWriter writer = new FastWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] grid = reader.readGrid(rows, cols);

            GridProblemSolver solver = new GridProblemSolver(rows, cols, grid);
            char[][] result = solver.solve();

            writer.printGrid(result);
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    /**
     * Handles the core logic of the grid processing.
     */
    static class GridProblemSolver {
        private final int rows;
        private final int cols;
        private final char[][] grid;

        private static final int[][] DIRECTIONS = {
            {1, 0}, {0, -1}, {-1, 0}, {0, 1}
        };

        public GridProblemSolver(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
        }

        public char[][] solve() {
            DisjointSetUnion dsu = new DisjointSetUnion(rows * cols);

            // 1. Build components of '.' cells using DSU
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.') {
                        connectNeighbors(r, c, dsu);
                    }
                }
            }

            char[][] result = new char[rows][cols];

            // 2. Calculate values for each cell
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.') {
                        result[r][c] = '.';
                    } else {
                        result[r][c] = calculateStarValue(r, c, dsu);
                    }
                }
            }

            return result;
        }

        private void connectNeighbors(int r, int c, DisjointSetUnion dsu) {
            // Check Right and Down to avoid redundant union operations
            int[][] adj = {{0, 1}, {1, 0}};
            for (int[] dir : adj) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                if (isValid(nr, nc) && grid[nr][nc] == '.') {
                    dsu.union(getIndex(r, c), getIndex(nr, nc));
                }
            }
        }

        private char calculateStarValue(int r, int c, DisjointSetUnion dsu) {
            Set<Integer> uniqueComponentRoots = new HashSet<>();

            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                if (isValid(nr, nc) && grid[nr][nc] == '.') {
                    uniqueComponentRoots.add(dsu.find(getIndex(nr, nc)));
                }
            }

            int sumOfSizes = 1;
            for (int root : uniqueComponentRoots) {
                sumOfSizes += dsu.getSize(root);
            }

            return (char) ('0' + (sumOfSizes % 10));
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        private int getIndex(int r, int c) {
            return r * cols + c;
        }
    }

    /**
     * Efficient Disjoint Set Union (DSU) implementation with Union by Size.
     */
    static class DisjointSetUnion {
        private final int[] parent;
        private final int[] size;

        public DisjointSetUnion(int n) {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        public int find(int i) {
            if (parent[i] == i) return i;
            return parent[i] = find(parent[i]); // Path compression
        }

        public void union(int i, int j) {
            int rootI = find(i);
            int rootJ = find(j);
            if (rootI != rootJ) {
                // Union by size
                if (size[rootI] < size[rootJ]) {
                    parent[rootI] = rootJ;
                    size[rootJ] += size[rootI];
                } else {
                    parent[rootJ] = rootI;
                    size[rootI] += size[rootJ];
                }
            }
        }

        public int getSize(int root) {
            return size[root];
        }
    }

    /**
     * High-performance input reader.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public char[][] readGrid(int rows, int cols) throws IOException {
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = reader.readLine();
                // Handle potential empty lines between inputs
                while (line == null || line.isEmpty()) {
                    line = reader.readLine();
                }
                grid[i] = line.toCharArray();
            }
            return grid;
        }
    }

    /**
     * High-performance output writer.
     */
    static class FastWriter {
        private final PrintWriter writer;

        public FastWriter(OutputStream outputStream) {
            this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public void printGrid(char[][] grid) {
            for (char[] row : grid) {
                writer.println(new String(row));
            }
        }

        public void close() {
            writer.close();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for identifying connected components in a grid
 * and calculating the sum of adjacent component sizes for wall cells.
 */
public class FencePainter {

    private static final char EMPTY_CHAR = '.';
    private static final char WALL_CHAR = '#';

    // Direction vectors for traversing neighbors (Up, Down, Left, Right)
    private static final int[] DX = {-1, 1, 0, 0};
    private static final int[] DY = {0, 0, -1, 1};

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            if (rows <= 0 || cols <= 0) {
                out.close();
                return;
            }

            char[][] grid = reader.readGrid(rows, cols);
            FencePainter solver = new FencePainter();
            solver.solve(rows, cols, grid, out);

        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Orchestrates the process of identifying components and printing the result.
     */
    public void solve(int rows, int cols, char[][] grid, PrintWriter out) {
        // componentGrid stores the ID of the component each '.' belongs to.
        // 0 represents a wall ('#'), positive integers represent component IDs.
        int[][] componentGrid = new int[rows][cols];
        List<Integer> componentSizes = new ArrayList<>();
        int nextComponentId = 1;

        // 1. Identify all connected components of '.'
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == EMPTY_CHAR && componentGrid[i][j] == 0) {
                    int size = performIterativeDFS(grid, componentGrid, i, j, nextComponentId);
                    componentSizes.add(size);
                    nextComponentId++;
                }
            }
        }

        // 2. Calculate the value for each '#' cell
        for (int i = 0; i < rows; i++) {
            StringBuilder rowOutput = new StringBuilder();
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == WALL_CHAR) {
                    rowOutput.append(calculateWallValue(i, j, rows, cols, componentGrid, componentSizes));
                } else {
                    rowOutput.append(EMPTY_CHAR);
                }
            }
            out.println(rowOutput.toString());
        }
    }

    /**
     * Uses an iterative DFS to label a connected component and return its size.
     * Iterative approach prevents StackOverflowError on very large grids.
     */
    private int performIterativeDFS(char[][] grid, int[][] componentGrid, int startX, int startY, int id) {
        int rows = grid.length;
        int cols = grid[0].length;
        int size = 0;

        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{startX, startY});
        componentGrid[startX][startY] = id;

        while (!stack.isEmpty()) {
            int[] current = stack.pop();
            int r = current[0];
            int c = current[1];
            size++;

            for (int i = 0; i < 4; i++) {
                int nr = r + DX[i];
                int nc = c + DY[i];

                if (isValid(nr, nc, rows, cols) && 
                    grid[nr][nc] == EMPTY_CHAR && 
                    componentGrid[nr][nc] == 0) {

                    componentGrid[nr][nc] = id;
                    stack.push(new int[]{nr, nc});
                }
            }
        }
        return size;
    }

    /**
     * Determines the digit to place in a wall cell based on adjacent components.
     */
    private char calculateWallValue(int r, int c, int rows, int cols, int[][] componentGrid, List<Integer> componentSizes) {
        Set<Integer> adjacentComponentIds = new HashSet<>();

        for (int i = 0; i < 4; i++) {
            int nr = r + DX[i];
            int nc = c + DY[i];

            if (isValid(nr, nc, rows, cols)) {
                int id = componentGrid[nr][nc];
                if (id > 0) {
                    adjacentComponentIds.add(id);
                }
            }
        }

        int totalSizeSum = 0;
        for (int id : adjacentComponentIds) {
            // Component IDs are 1-indexed, List is 0-indexed
            totalSizeSum += componentSizes.get(id - 1);
        }

        return (char) ('0' + (totalSizeSum % 10));
    }

    private boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Utility class for fast input reading.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public char[][] readGrid(int rows, int cols) throws IOException {
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = reader.readLine();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }
            return grid;
        }
    }
}

