/**
 * Engine responsible for solving the labyrinth logic.
 */
class LabyrinthSolver {
    private final char[][] grid;
    private final int rows;
    private final int cols;

    // Stores which component ID each '.' cell belongs to (0 if it's a '*' or unvisited)
    private final int[][] componentIdGrid;
    // Maps component ID to the total number of '.' cells in that component
    private final Map<Integer, Integer> componentSizeMap;

    private static final int[][] DIRECTIONS = {
            {0, 1}, {1, 0}, {0, -1}, {-1, 0}
    };

    public LabyrinthSolver(char[][] grid, int rows, int cols) {
        this.grid = grid;
        this.rows = rows;
        this.cols = cols;
        this.componentIdGrid = new int[rows][cols];
        this.componentSizeMap = new HashMap<>();
    }

    /**
     * Orchestrates the identification of components and calculation of the result grid.
     */
    public char[][] solve() {
        identifyComponents();
        return calculateResultGrid();
    }

    /**
     * Uses BFS to find all connected components of '.' cells.
     */
    private void identifyComponents() {
        int currentComponentId = 1;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && componentIdGrid[r][c] == 0) {
                    int size = performBFS(r, c, currentComponentId);
                    componentSizeMap.put(currentComponentId, size);
                    currentComponentId++;
                }
            }
        }
    }

    /**
     * Standard BFS to explore a connected component.
     */
    private int performBFS(int startR, int startC, int id) {
        int size = 0;
        Queue<Cell> queue = new LinkedList<>();

        queue.add(new Cell(startR, startC));
        componentIdGrid[startR][startC] = id;

        while (!queue.isEmpty()) {
            Cell current = queue.poll();
            size++;

            for (int[] dir : DIRECTIONS) {
                int nr = current.row + dir[0];
                int nc = current.col + dir[1];

                if (isValid(nr, nc) && grid[nr][nc] == '.' && componentIdGrid[nr][nc] == 0) {
                    componentIdGrid[nr][nc] = id;
                    queue.add(new Cell(nr, nc));
                }
            }
        }
        return size;
    }

    /**
     * Constructs the final grid by calculating values for '*' cells.
     */
    private char[][] calculateResultGrid() {
        char[][] result = new char[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    result[r][c] = '.';
                } else {
                    result[r][c] = calculateStarValue(r, c);
                }
            }
        }
        return result;
    }

    /**
     * For a '*' cell, sums the sizes of all unique adjacent '.' components + 1.
     */
    private char calculateStarValue(int r, int c) {
        Set<Integer> adjacentComponentIds = new HashSet<>();

        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            if (isValid(nr, nc) && grid[nr][nc] == '.') {
                int id = componentIdGrid[nr][nc];
                if (id > 0) {
                    adjacentComponentIds.add(id);
                }
            }
        }

        int sum = 1;
        for (int id : adjacentComponentIds) {
            sum += componentSizeMap.getOrDefault(id, 0);
        }

        // Convert the digit to a char (e.g., 6 -> '6')
        return (char) ((sum % 10) + '0');
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Simple immutable data carrier for grid coordinates.
     */
    private static class Cell {
        final int row;
        final int col;

        Cell(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Analyzes a grid to identify connected components of '.' cells and 
 * calculates a specific value for '*' cells based on their adjacent components.
 */
public class GridComponentAnalyzer {

    /**
     * Represents a coordinate on the grid.
     */
    private record Point(int row, int col) {}

    // Direction vectors for 4-connectivity (Up, Down, Right, Left)
    private static final int[] DX = {-1, 1, 0, 0};
    private static final int[] DY = {0, 0, 1, -1};

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int[][] componentIds;
    private final Map<Integer, Integer> componentSizes;
    private int nextComponentId = 1;

    public GridComponentAnalyzer(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.componentIds = new int[rows][cols];
        this.componentSizes = new HashMap<>();
    }

    /**
     * Orchestrates the execution of the analysis.
     */
    public void run() throws IOException {
        identifyComponents();
        printResult();
    }

    /**
     * Iterates through the grid to find and label all connected components of '.' cells.
     */
    private void identifyComponents() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    bfsMarkComponent(r, c);
                }
            }
        }
    }

    /**
     * Uses BFS to find all connected '.' cells, assigns them a unique ID, 
     * and stores the component size.
     */
    private void bfsMarkComponent(int startRow, int startCol) {
        List<Point> componentCells = new ArrayList<>();
        Deque<Point> queue = new ArrayDeque<>();

        Point start = new Point(startRow, startCol);
        queue.add(start);
        componentCells.add(start);

        // Mark the cell as part of a component to avoid re-visiting
        grid[startRow][startCol] = '+';

        while (!queue.isEmpty()) {
            Point curr = queue.poll();
            for (int i = 0; i < 4; i++) {
                int nr = curr.row + DX[i];
                int nc = curr.col + DY[i];

                if (isValid(nr, nc) && grid[nr][nc] == '.') {
                    grid[nr][nc] = '+'; // Mark as visited
                    Point next = new Point(nr, nc);
                    queue.add(next);
                    componentCells.add(next);
                }
            }
        }

        int currentId = nextComponentId++;
        int size = componentCells.size();
        componentSizes.put(currentId, size);

        for (Point p : componentCells) {
            componentIds[p.row][p.col] = currentId;
        }
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Prints the resulting grid. '*' cells are replaced by their calculated value.
     * All other cells are printed as '.'.
     */
    private void printResult() throws IOException {
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*') {
                    out.print(calculateStarValue(r, c));
                } else {
                    out.print('.');
                }
            }
            out.println();
        }
        out.flush();
        out.close();
    }

    /**
     * Calculates the value for a '*' cell: (1 + sum of unique adjacent component sizes) % 10.
     */
    private int calculateStarValue(int r, int c) {
        Set<Integer> seenComponentIds = new HashSet<>();
        int sum = 1; // The original logic starts the summation from 1

        for (int i = 0; i < 4; i++) {
            int nr = r + DX[i];
            int nc = c + DY[i];

            // Check if the neighbor is a part of a component (marked as '+')
            if (isValid(nr, nc) && grid[nr][nc] == '+') {
                int id = componentIds[nr][nc];
                // Ensure we only add each unique component size once
                if (id != 0 && seenComponentIds.add(id)) {
                    sum = (sum + componentSizes.get(id)) % 10;
                }
            }
        }
        return sum;
    }

    public static void main(String[] args) {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String firstLine = br.readLine();
            if (firstLine == null) return;

            StringTokenizer st = new StringTokenizer(firstLine);
            int rows = Integer.parseInt(st.nextToken());
            int cols = Integer.parseInt(st.nextToken());

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = br.readLine();
                if (line != null) {
                    grid[i] = line.toCharArray();
                }
            }

            GridComponentAnalyzer analyzer = new GridComponentAnalyzer(rows, cols, grid);
            analyzer.run();

        } catch (IOException | NumberFormatException e) {
            System.err.println("Error processing input: " + e.getMessage());
        }
    }
}

