/**
 * A solver for grid-based connectivity problems.
 * The goal is to find the sum of the sizes of unique connected components of '.' cells 
 * adjacent to each '#' cell, outputting the result modulo 10.
 */
public class GridProblemSolver {

    private static final char EMPTY_CELL = '.';
    private static final int[] DIRECTIONS_ROW = {-1, 1, 0, 0};
    private static final int[] DIRECTIONS_COL = {0, 0, -1, 1};

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int[][] componentIdMap;
    private final int[] componentSizes;

    public GridProblemSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.componentIdMap = new int[rows][cols];
        // The maximum number of components in an R*C grid is (R*C)/2.
        this.componentSizes = new int[rows * cols + 1];
    }

    /**
     * Executes the solving logic: identifies components and calculates neighbor sums.
     * 
     * @param out The PrintWriter to output results to.
     */
    public void solve(PrintWriter out) {
        int currentComponentId = 1;

        // Phase 1: Identify all connected components of '.' cells using BFS.
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == EMPTY_CELL && componentIdMap[i][j] == 0) {
                    int size = performBFS(i, j, currentComponentId);
                    componentSizes[currentComponentId] = size;
                    currentComponentId++;
                }
            }
        }

        // Phase 2: For every non-empty cell, calculate the sum of adjacent component sizes.
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == EMPTY_CELL) {
                    out.print('.');
                } else {
                    out.print(calculateAdjacentSumMod10(i, j));
                }
            }
            out.println();
        }
    }

    /**
     * Uses Breadth-First Search to explore a connected component of '.' cells.
     */
    private int performBFS(int startRow, int startCol, int id) {
        int size = 0;
        Deque<int[]> queue = new ArrayDeque<>();

        queue.offer(new int[]{startRow, startCol});
        componentIdMap[startRow][startCol] = id;

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int r = current[0];
            int c = current[1];
            size++;

            for (int k = 0; k < 4; k++) {
                int nr = r + DIRECTIONS_ROW[k];
                int nc = c + DIRECTIONS_COL[k];

                if (isValid(nr, nc) && grid[nr][nc] == EMPTY_CELL && componentIdMap[nr][nc] == 0) {
                    componentIdMap[nr][nc] = id;
                    queue.offer(new int[]{nr, nc});
                }
            }
        }
        return size;
    }

    /**
     * Calculates the sum of unique adjacent component sizes for a given cell.
     */
    private int calculateAdjacentSumMod10(int r, int c) {
        Set<Integer> adjacentComponentIds = new HashSet<>();
        for (int k = 0; k < 4; k++) {
            int nr = r + DIRECTIONS_ROW[k];
            int nc = c + DIRECTIONS_COL[k];

            if (isValid(nr, nc) && grid[nr][nc] == EMPTY_CELL) {
                adjacentComponentIds.add(componentIdMap[nr][nc]);
            }
        }

        long totalSum = 0;
        for (int id : adjacentComponentIds) {
            totalSum += componentSizes[id];
        }
        return (int) (totalSum % 10);
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * High-performance input reader.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            return next != null ? Integer.parseInt(next) : 0;
        }
    }

    public static void main(String[] args) {
        FastReader sc = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        String nInput = sc.next();
        if (nInput != null) {
            int n = Integer.parseInt(nInput);
            int m = sc.nextInt();

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                String rowString = sc.next();
                if (rowString != null) {
                    for (int j = 0; j < m; j++) {
                        grid[i][j] = rowString.charAt(j);
                    }
                }
            }

            GridProblemSolver solver = new GridProblemSolver(n, m, grid);
            solver.solve(out);
        }

        out.flush();
        out.close();
    }
}

