class LabyrinthSolver {
    private final FastReader reader;
    private final FastWriter writer;

    // Direction vectors for 4-connectivity (Up, Down, Left, Right)
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public LabyrinthSolver(FastReader reader, FastWriter writer) {
        this.reader = reader;
        this.writer = writer;
    }

    public void solve() throws IOException {
        int rows = reader.nextInt();
        int cols = reader.nextInt();
        if (rows <= 0 || cols <= 0) return;

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = reader.nextRow(cols);
        }

        DisjointSet ds = new DisjointSet(rows * cols);

        // Phase 1: Group all connected '.' cells into components using DSU
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    for (int i = 0; i < 4; i++) {
                        int nr = r + DR[i];
                        int nc = c + DC[i];

                        if (isValid(nr, nc, rows, cols) && grid[nr][nc] == '.') {
                            ds.union(getIndex(r, c, cols), getIndex(nr, nc, cols));
                        }
                    }
                }
            }
        }

        // Phase 2: Calculate the value for each '#' cell
        StringBuilder output = new StringBuilder();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    output.append('.');
                } else {
                    output.append(calculateHashValue(r, c, rows, cols, grid, ds));
                }
            }
            output.append('\n');
            writer.print(output.toString());
            output.setLength(0); // Clear StringBuilder for next row
        }
    }

    private int calculateHashValue(int r, int c, int rows, int cols, char[][] grid, DisjointSet ds) {
        Set<Integer> neighborSetRoots = new HashSet<>();

        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];

            if (isValid(nr, nc, rows, cols) && grid[nr][nc] == '.') {
                neighborSetRoots.add(ds.find(getIndex(nr, nc, cols)));
            }
        }

        int totalSize = 1; // Start with 1 as per problem logic
        for (int root : neighborSetRoots) {
            totalSize += ds.getSize(root);
        }

        return totalSize % 10;
    }

    private boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private int getIndex(int r, int c, int cols) {
        return r * cols + c;
    }
}

/**
 * Disjoint Set Union (DSU) with Path Compression and Union by Size.
 */
class DisjointSet {
    private final int[] parent;
    private final int[] size;

    public DisjointSet(int n) {
        parent = new int[n];
        size = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
            size[i] = 1;
        }
    }

    public int find(int i) {
        if (parent[i] == i) {
            return i;
        }
        return parent[i] = find(parent[i]); // Path compression
    }

    public void union(int i, int j) {
        int rootI = find(i);
        int rootJ = find(j);
        if (rootI != rootJ) {
            // Union by size
            if (size[rootI] < size[rootJ]) {
                parent[rootI] = rootJ;
                size[rootJ] += size[rootI];
            } else {
                parent[rootJ] = rootI;
                size[rootI] += size[rootJ];
            }
        }
    }

    public int getSize(int root) {
        return size[root];
    }
}

/**
 * Fast I/O implementation for high-performance reading.
 */
class FastReader {
    private final InputStream in;
    private final byte[] buffer = new byte[8192];
    private int pointer = 0;
    private int bufferLength = 0;

    public FastReader(InputStream in) {
        this.in = in;
    }

    private int readByte() throws IOException {
        if (pointer >= bufferLength) {
            pointer = 0;
            bufferLength = in.read(buffer);
            if (bufferLength <= 0) return -1;
        }
        return buffer[pointer++];
    }

    public int nextInt() throws IOException {
        int c = readByte();
        while (c != -1 && c <= 32) c = readByte();
        if (c == -1) return 0;
        int sign = 1;
        if (c == '-') {
            sign = -1;
            c = readByte();
        }
        int res = 0;
        while (c >= '0' && c <= '9') {
            res = res * 10 + (c - '0');
            c = readByte();
        }
        return res * sign;
    }

    public char[] nextRow(int cols) throws IOException {
        char[] row = new char[cols];
        int skipped = 0;
        // Skip leading whitespace/newlines
        int c = readByte();
        while (c != -1 && (c == '\n' || c == '\r' || c == ' ')) {
            c = readByte();
        }

        // Read the actual row content
        for (int i = 0; i < cols; i++) {
            if (c == -1) break;
            row[i] = (char) c;
            c = readByte();
        }
        return row;
    }
}

