/**
 * Handles the core logic of identifying connected components of '.' 
 * and calculating the values for '#' cells.
 */
class GridAnalyzer {
    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int[][] componentIdGrid;
    private final int[] componentSizes;
    private final int[][] resultGrid;

    private static final int[][] DIRECTIONS = {{0, 1}, {1, 0}, {-1, 0}, {0, -1}};

    public GridAnalyzer(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.componentIdGrid = new int[rows][cols];
        // Max possible components is (rows * cols) / 2, but we size for safety.
        this.componentSizes = new int[rows * cols + 1];
        this.resultGrid = new int[rows][cols];
    }

    public void process() {
        int componentCounter = 0;

        // Step 1: Identify connected components of '.' using BFS
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && componentIdGrid[r][c] == 0) {
                    componentCounter++;
                    int size = performBFS(r, c, componentCounter);
                    componentSizes[componentCounter] = size;
                }
            }
        }

        // Step 2: Calculate result values for '#' cells
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] != '.') {
                    calculateCellResult(r, c);
                }
            }
        }
    }

    private int performBFS(int startR, int startC, int componentId) {
        int size = 0;
        Queue<int[]> queue = new ArrayDeque<>();

        queue.add(new int[]{startR, startC});
        componentIdGrid[startR][startC] = componentId;

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int r = current[0];
            int c = current[1];
            size++;

            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                if (isValid(nr, nc) && grid[nr][nc] == '.' && componentIdGrid[nr][nc] == 0) {
                    componentIdGrid[nr][nc] = componentId;
                    queue.add(new int[]{nr, nc});
                }
            }
        }
        return size;
    }

    private void calculateCellResult(int r, int c) {
        Set<Integer> adjacentComponentIds = new HashSet<>();
        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            if (isValid(nr, nc) && grid[nr][nc] == '.') {
                int id = componentIdGrid[nr][nc];
                if (id > 0) {
                    adjacentComponentIds.add(id);
                }
            }
        }

        // Per original logic: base value is 1, plus the sum of adjacent component sizes
        int sum = 1;
        for (int id : adjacentComponentIds) {
            sum += componentSizes[id];
        }
        resultGrid[r][c] = sum;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    public void printResults(FastWriter writer) throws IOException {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    writer.print('.');
                } else {
                    // The original logic used (sum % 10)
                    writer.print(resultGrid[r][c] % 10);
                }
            }
            writer.println("");
        }
    }
}

