import java.util.*;

/**
 * GridProcessor solves the problem of calculating the sum of sizes of adjacent 
 * connected empty components for every obstacle in a grid.
 */
public class GridProcessor {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] grid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            GridAnalyzer analyzer = new GridAnalyzer(rows, cols, grid);
            analyzer.analyze();
            analyzer.printResult(writer);

        } catch (Exception e) {
            // In a production environment, use a logger.
            e.printStackTrace();
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Core logic for analyzing the grid and calculating component sizes.
     */
    static class GridAnalyzer {
        private static final int[][] DIRECTIONS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final int[][] componentIds;
        private final int[] componentSizes;

        public GridAnalyzer(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            this.componentIds = new int[rows][cols];
            // Maximum possible components is rows * cols
            this.componentSizes = new int[rows * cols + 1];
        }

        /**
         * Identifies all connected components of '.' and calculates their sizes.
         */
        public void analyze() {
            int currentId = 0;
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.' && componentIds[r][c] == 0) {
                        currentId++;
                        performBFS(r, c, currentId);
                    }
                }
            }
        }

        /**
         * Iterative BFS to prevent StackOverflowError on large connected components.
         */
        private void performBFS(int startR, int startC, int id) {
            int size = 0;
            Deque<Integer> queue = new ArrayDeque<>();

            // Store position as a single integer to avoid object allocation
            queue.add(startR * cols + startC);
            componentIds[startR][startC] = id;

            while (!queue.isEmpty()) {
                int pos = queue.poll();
                int r = pos / cols;
                int c = pos % cols;
                size++;

                for (int[] dir : DIRECTIONS) {
                    int nr = r + dir[0];
                    int nc = c + dir[1];

                    if (isValid(nr, nc) && grid[nr][nc] == '.' && componentIds[nr][nc] == 0) {
                        componentIds[nr][nc] = id;
                        queue.add(nr * cols + nc);
                    }
                }
            }
            componentSizes[id] = size;
        }

        /**
         * Prints the modified grid to the provided PrintWriter.
         */
        public void printResult(PrintWriter out) {
            StringBuilder rowBuilder = new StringBuilder();
            for (int r = 0; r < rows; r++) {
                rowBuilder.setLength(0);
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.') {
                        rowBuilder.append('.');
                    } else {
                        rowBuilder.append(calculateObstacleValue(r, c));
                    }
                }
                out.println(rowBuilder.toString());
            }
        }

        /**
         * Calculates the sum of unique adjacent component sizes for a '#' cell.
         */
        private int calculateObstacleValue(int r, int c) {
            int totalSum = 1;
            // Use a small fixed-size array to track unique neighbor IDs 
            // to avoid the overhead of HashSet allocation in the hot loop.
            int[] seenIds = new int[4];
            int uniqueCount = 0;

            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                if (isValid(nr, nc) && componentIds[nr][nc] > 0) {
                    int id = componentIds[nr][nc];
                    boolean alreadyFound = false;
                    for (int i = 0; i < uniqueCount; i++) {
                        if (seenIds[i] == id) {
                            alreadyFound = true;
                            break;
                        }
                    }

                    if (!alreadyFound) {
                        seenIds[uniqueCount++] = id;
                        totalSum += componentSizes[id];
                    }
                }
            }
            return totalSum % 10;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

