class LabyrinthSolver {
    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int[][] componentIds;
    private final int[] componentSizes;

    private static final int[][] DIRECTIONS = {
        {1, 0}, {-1, 0}, {0, 1}, {0, -1}
    };

    public LabyrinthSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.componentIds = new int[rows][cols];
        // Maximum possible components is (rows * cols) / 2
        this.componentSizes = new int[rows * cols + 1];
    }

    /**
     * Executes the solving logic and returns the resulting grid as a String.
     */
    public String solve() {
        identifyComponents();
        return buildResultString();
    }

    /**
     * Finds all connected components of '.' and assigns them unique IDs and sizes.
     */
    private void identifyComponents() {
        int nextId = 1;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && componentIds[r][c] == 0) {
                    int size = performBFS(r, c, nextId);
                    componentSizes[nextId] = size;
                    nextId++;
                }
            }
        }
    }

    /**
     * Iterative BFS to avoid StackOverflowError on large grids.
     */
    private int performBFS(int startR, int startC, int id) {
        int size = 0;
        Deque<Integer> queue = new ArrayDeque<>();

        // Pack 2D coordinates into a single integer for memory efficiency
        int startPos = startR * cols + startC;
        queue.offer(startPos);
        componentIds[startR][startC] = id;
        size++;

        while (!queue.isEmpty()) {
            int pos = queue.poll();
            int r = pos / cols;
            int c = pos % cols;

            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                if (isValidPath(nr, nc) && componentIds[nr][nc] == 0) {
                    componentIds[nr][nc] = id;
                    size++;
                    queue.offer(nr * cols + nc);
                }
            }
        }
        return size;
    }

    private boolean isValidPath(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] == '.';
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Constructs the final output string.
     */
    private String buildResultString() {
        StringBuilder sb = new StringBuilder(rows * cols);
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*') {
                    sb.append(calculateWallValue(r, c));
                } else {
                    sb.append('.');
                }
            }
            sb.append('\n');
        }
        return sb.toString();
    }

    /**
     * Calculates the sum of sizes of unique adjacent components for a wall cell.
     */
    private int calculateWallValue(int r, int c) {
        Set<Integer> adjacentComponentIds = new HashSet<>();

        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            if (isWithinBounds(nr, nc) && grid[nr][nc] == '.') {
                adjacentComponentIds.add(componentIds[nr][nc]);
            }
        }

        int sumOfSizes = 0;
        for (int id : adjacentComponentIds) {
            sumOfSizes += componentSizes[id];
        }

        // Replicating original logic: (sum + 1) % 10
        return (sumOfSizes + 1) % 10;
    }
}

