/**
 * A program that processes a grid of '.' and '*' characters.
 * It identifies connected components of '.' cells and replaces '*' cells 
 * with a value derived from the sizes of adjacent '.' components.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] grid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            GridSolver solver = new GridSolver(rows, cols, grid);
            String[] result = solver.solve();

            for (String line : result) {
                out.println(line);
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Core logic for processing the grid.
     */
    static class GridSolver {
        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final int[][] componentIdGrid;
        private final int[] componentSizes;

        private static final int[][] DIRECTIONS = {
            {-1, 0}, {1, 0}, {0, 1}, {0, -1}
        };

        private int componentCounter = 0;

        public GridSolver(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            this.componentIdGrid = new int[rows][cols];
            // Max possible components is rows * cols / 2 (approx)
            this.componentSizes = new int[rows * cols + 1];
        }

        /**
         * Executes the main algorithm.
         * @return The modified grid as an array of strings.
         */
        public String[] solve() {
            identifyComponents();
            return generateResultGrid();
        }

        /**
         * Uses BFS to find all connected components of '.' cells.
         */
        private void identifyComponents() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.' && componentIdGrid[i][j] == 0) {
                        bfsMarkComponent(i, j);
                    }
                }
            }
        }

        private void bfsMarkComponent(int startR, int startC) {
            componentCounter++;
            int currentComponentId = componentCounter;
            int size = 0;

            Queue<int[]> queue = new ArrayDeque<>();
            queue.add(new int[]{startR, startC});
            componentIdGrid[startR][startC] = currentComponentId;

            while (!queue.isEmpty()) {
                int[] curr = queue.poll();
                int r = curr[0];
                int c = curr[1];
                size++;

                for (int[] dir : DIRECTIONS) {
                    int nr = r + dir[0];
                    int nc = c + dir[1];

                    if (isValid(nr, nc) && grid[nr][nc] == '.' && componentIdGrid[nr][nc] == 0) {
                        componentIdGrid[nr][nc] = currentComponentId;
                        queue.add(new int[]{nr, nc});
                    }
                }
            }
            componentSizes[currentComponentId] = size;
        }

        /**
         * Builds the output grid based on the requirements.
         */
        private String[] generateResultGrid() {
            String[] result = new String[rows];
            for (int i = 0; i < rows; i++) {
                StringBuilder sb = new StringBuilder();
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.') {
                        sb.append('.');
                    } else {
                        sb.append(calculateReplacementValue(i, j));
                    }
                }
                result[i] = sb.toString();
            }
            return result;
        }

        private int calculateReplacementValue(int r, int c) {
            Set<Integer> adjacentComponentIds = new HashSet<>();
            int sumOfAdjacentSizes = 0;

            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                if (isValid(nr, nc) && grid[nr][nc] == '.') {
                    int id = componentIdGrid[nr][nc];
                    if (id != 0 && adjacentComponentIds.add(id)) {
                        sumOfAdjacentSizes += componentSizes[id];
                    }
                }
            }
            return (sumOfAdjacentSizes + 1) % 10;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * Efficient input reader for large datasets.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

