/**
 * A solution to calculate the sum of adjacent empty component sizes for each obstacle.
 * The grid contains '*' (obstacles) and '.' (empty spaces).
 * For each '*', the result is the sum of the sizes of unique connected components 
 * of '.' surrounding it, modulo 10.
 */
public class GridComponentAnalyzer {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            char[][] inputGrid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                inputGrid[i] = reader.next().toCharArray();
            }

            GridSolver solver = new GridSolver(rows, cols, inputGrid);
            solver.solve(writer);

        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Represents a coordinate in the grid.
     */
    private record Cell(int r, int c) {}

    /**
     * Handles the core logic of processing the grid.
     */
    private static class GridSolver {
        private final int rows;
        private final int cols;
        private final int[][] grid; // 1 for obstacle (*), 0 for empty (.)
        private final int[][] componentMap; // Maps each empty cell to a component ID
        private final List<Integer> componentSizes;

        private static final int[][] DIRECTIONS = {
            {0, 1}, {1, 0}, {0, -1}, {-1, 0}
        };

        public GridSolver(int rows, int cols, char[][] inputGrid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = new int[rows][cols];
            this.componentMap = new int[rows][cols];
            this.componentSizes = new ArrayList<>();

            for (int i = 0; i < rows; i++) {
                Arrays.fill(componentMap[i], -1);
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = (inputGrid[i][j] == '*') ? 1 : 0;
                }
            }
        }

        public void solve(PrintWriter out) {
            findComponents();
            printResults(out);
        }

        /**
         * Uses BFS to identify all connected components of empty cells.
         */
        private void findComponents() {
            int componentIdCounter = 0;

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == 0 && componentMap[i][j] == -1) {
                        int size = performBFS(i, j, componentIdCounter);
                        componentSizes.add(size);
                        componentIdCounter++;
                    }
                }
            }
        }

        private int performBFS(int startR, int startC, int id) {
            Queue<Cell> queue = new LinkedList<>();
            componentMap[startR][startC] = id;
            queue.add(new Cell(startR, startC));
            int count = 0;

            while (!queue.isEmpty()) {
                Cell current = queue.poll();
                count++;

                for (int[] dir : DIRECTIONS) {
                    int nr = current.r + dir[0];
                    int nc = current.c + dir[1];

                    if (isValid(nr, nc) && grid[nr][nc] == 0 && componentMap[nr][nc] == -1) {
                        componentMap[nr][nc] = id;
                        queue.add(new Cell(nr, nc));
                    }
                }
            }
            return count;
        }

        /**
         * Iterates through the grid and prints the calculated values.
         */
        private void printResults(PrintWriter out) {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == 0) {
                        out.print('.');
                    } else {
                        out.print(calculateObstacleValue(i, j));
                    }
                }
                out.println();
            }
        }

        private int calculateObstacleValue(int r, int c) {
            Set<Integer> neighborComponentIds = new HashSet<>();
            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                if (isValid(nr, nc) && grid[nr][nc] == 0) {
                    neighborComponentIds.add(componentMap[nr][nc]);
                }
            }

            int totalSizeSum = 0;
            for (int id : neighborComponentIds) {
                totalSizeSum += componentSizes.get(id);
            }
            return totalSizeSum % 10;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * Fast I/O utility class.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

