        cols = in.nextInt();
        grid = new char[rows][cols];
        componentIdMap = new int[rows][cols]; // 0 means not part of a '.' component

        // A safe upper bound for the number of components is the number of cells.
        componentSizes = new int[rows * cols + 1];

        for (int i = 0; i < rows; i++) {
            grid[i] = in.next().toCharArray();
        }

        findComponents();
        calculateAndPrintResults(out);
    }

    /**
     * Identifies all connected components of '.' cells using BFS.
     */
    private void findComponents() {
        int currentComponentId = 1;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && componentIdMap[r][c] == 0) {
                    performBfs(r, c, currentComponentId);
                    currentComponentId++;
                }
            }
        }
    }

    private void performBfs(int startR, int startC, int id) {
        Queue<Point> queue = new ArrayDeque<>();
        queue.add(new Point(startR, startC));
        componentIdMap[startR][startC] = id;
        int size = 0;

        while (!queue.isEmpty()) {
            Point curr = queue.poll();
            size++;

            for (int i = 0; i < 4; i++) {
                int nr = curr.r() + DR[i];
                int nc = curr.c() + DC[i];

                if (isValid(nr, nc) && grid[nr][nc] == '.' && componentIdMap[nr][nc] == 0) {
                    componentIdMap[nr][nc] = id; // Mark as visited immediately
                    queue.add(new Point(nr, nc));
                }
            }
        }
        componentSizes[id] = size;
    }

    /**
     * Iterates through the grid to calculate results for '*' cells and prints them.
     */
    private void calculateAndPrintResults(FastWriter out) {
        StringBuilder sb = new StringBuilder();

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*') {
                    sb.append(calculateObstacleValue(r, c));
                } else {
                    sb.append('.');
                }
            }
            sb.append('\n');
        }
        out.print(sb.toString());
    }

    private int calculateObstacleValue(int r, int c) {
        Set<Integer> adjacentComponentIds = new HashSet<>();
        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];

            if (isValid(nr, nc) && componentIdMap[nr][nc] > 0) {
                adjacentComponentIds.add(componentIdMap[nr][nc]);
            }
        }

        int totalSize = 1; // Base value as per original logic
        for (int id : adjacentComponentIds) {
            totalSize += componentSizes[id];
        }
        return totalSize % 10;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

