/**
 * A solver for the grid-based component size problem.
 * The goal is to identify connected components of '.' and for each '#' cell,
 * calculate (1 + sum of sizes of unique adjacent components) mod 10.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
