/**
 * Represents a point in the 2D grid.
 */
record Coordinate(int row, int col) {}

/**
 * Handles the core logic of component identification and grid transformation.
 */
class GridSolver {
    private final int rows;
    private final int cols;
    private final char[][] grid;

    private static final int[] ROW_DIRECTIONS = {1, -1, 0, 0};
    private static final int[] COL_DIRECTIONS = {0, 0, 1, -1};

    private final int[][] componentMap;
    private final Map<Integer, Integer> componentSizes;
    private int componentIdCounter = 0;

    public GridSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.componentMap = new int[rows][cols];
        this.componentSizes = new HashMap<>();
    }

    /**
     * Executes the logic and returns the formatted grid as a string.
     */
    public String solve() {
        identifyComponents();
        return buildResultString();
    }

    /**
     * Traverses the grid to find all connected components of '.' cells.
     */
    private void identifyComponents() {
        boolean[][] visited = new boolean[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && !visited[r][c]) {
                    componentIdCounter++;
                    int size = performBFS(r, c, visited, componentIdCounter);
                    componentSizes.put(componentIdCounter, size);
                }
            }
        }
    }

    /**
     * Performs BFS to map a component and calculate its size.
     */
    private int performBFS(int startR, int startC, boolean[][] visited, int currentId) {
        int size = 0;
        Queue<Coordinate> queue = new LinkedList<>();

        visited[startR][startC] = true;
        queue.add(new Coordinate(startR, startC));

        while (!queue.isEmpty()) {
            Coordinate curr = queue.poll();
            componentMap[curr.row()][curr.col()] = currentId;
            size++;

            for (int i = 0; i < 4; i++) {
                int nextR = curr.row() + ROW_DIRECTIONS[i];
                int nextC = curr.col() + COL_DIRECTIONS[i];

                if (isValid(nextR, nextC) && !visited[nextR][nextC] && grid[nextR][nextC] == '.') {
                    visited[nextR][nextC] = true;
                    queue.add(new Coordinate(nextR, nextC));
                }
            }
        }
        return size;
    }

    /**
     * Constructs the final output string based on the component rules.
     */
    private String buildResultString() {
        StringBuilder sb = new StringBuilder();

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    sb.append('.');
                } else {
                    sb.append(calculateWaterCellValue(r, c));
                }
            }
            sb.append('\n');
        }
        return sb.toString();
    }

    /**
     * Calculates the value for a '#' cell: (1 + sum of sizes of unique adjacent components) % 10.
     */
    private int calculateWaterCellValue(int r, int c) {
        Set<Integer> adjacentComponentIds = new HashSet<>();

        for (int i = 0; i < 4; i++) {
            int nextR = r + ROW_DIRECTIONS[i];
            int nextC = c + COL_DIRECTIONS[i];

            if (isValid(nextR, nextC) && componentMap[nextR][nextC] != 0) {
                adjacentComponentIds.add(componentMap[nextR][nextC]);
            }
        }

        int totalSizeSum = 1; // Starting with 1 as per requirement
        for (int id : adjacentComponentIds) {
            totalSizeSum += componentSizes.getOrDefault(id, 0);
        }

        return totalSizeSum % 10;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

