import java.io.BufferedReader;
import java.io.Closeable;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.StringTokenizer;

/**
 * TheLabyrinth solves a grid-based puzzle where wall values are determined 
 * by the sum of the sizes of unique adjacent connected components of empty cells.
 */
public class TheLabyrinth implements Closeable {

    private final FastReader inputReader;
    private final PrintWriter outputWriter;

    private static final int[][] DIRECTIONS = {{1, 0}, {-1, 0}, {0, -1}, {0, 1}};

    public TheLabyrinth() {
        this.inputReader = new FastReader(System.in);
        this.outputWriter = new PrintWriter(System.out);
    }

    /**
     * Disjoint Set Union (DSU) data structure to manage connected components.
     */
    static class DisjointSet {
        private final int[] parent;
        private final int[] size;

        public DisjointSet(int n) {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        public int find(int i) {
            if (parent[i] == i) {
                return i;
            }
            return parent[i] = find(parent[i]); // Path compression
        }

        public void union(int i, int j) {
            int rootI = find(i);
            int rootJ = find(j);
            if (rootI != rootJ) {
                // Union by size
                if (size[rootI] < size[rootJ]) {
                    parent[rootI] = rootJ;
                    size[rootJ] += size[rootI];
                } else {
                    parent[rootJ] = rootI;
                    size[rootI] += size[rootJ];
                }
            }
        }

        public int getSize(int i) {
            return size[find(i)];
        }
    }

    public void solve() {
        int rows = inputReader.nextInt();
        int cols = inputReader.nextInt();
        char[][] grid = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            grid[i] = inputReader.next().toCharArray();
        }

        DisjointSet dsu = groupEmptyCells(grid, rows, cols);
        calculateWallValues(grid, dsu, rows, cols);
        printGrid(grid, rows);
    }

    /**
     * Connects all adjacent '.' cells into components using DSU.
     */
    private DisjointSet groupEmptyCells(char[][] grid, int rows, int cols) {
        DisjointSet dsu = new DisjointSet(rows * cols);

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    // Check right neighbor
                    if (c + 1 < cols && grid[r][c + 1] == '.') {
                        dsu.union(r * cols + c, r * cols + (c + 1));
                    }
                    // Check bottom neighbor
                    if (r + 1 < rows && grid[r + 1][c] == '.') {
                        dsu.union(r * cols + c, (r + 1) * cols + c);
                    }
                }
            }
        }
        return dsu;
    }

    /**
     * Updates '#' cells with a value based on the sum of sizes of unique adjacent '.' components.
     */
    private void calculateWallValues(char[][] grid, DisjointSet dsu, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    continue;
                }

                int[] uniqueRoots = new int[4];
                int uniqueCount = 0;

                for (int[] dir : DIRECTIONS) {
                    int nr = r + dir[0];
                    int nc = c + dir[1];

                    if (isValid(nr, nc, rows, cols) && grid[nr][nc] == '.') {
                        int root = dsu.find(nr * cols + nc);

                        // Check if we have already processed this component root
                        boolean alreadyFound = false;
                        for (int i = 0; i < uniqueCount; i++) {
                            if (uniqueRoots[i] == root) {
                                alreadyFound = true;
                                break;
                            }
                        }

                        if (!alreadyFound) {
                            uniqueRoots[uniqueCount++] = root;
                        }
                    }
                }

                int totalAdjacentSize = 0;
                for (int i = 0; i < uniqueCount; i++) {
                    totalAdjacentSize += dsu.getSize(uniqueRoots[i]);
                }

                grid[r][c] = (char) ('0' + (1 + totalAdjacentSize) % 10);
            }
        }
    }

    private boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private void printGrid(char[][] grid, int rows) {
        for (int i = 0; i < rows; i++) {
            outputWriter.println(new String(grid[i]));
        }
    }

    @Override
    public void close() throws IOException {
        inputReader.close();
        outputWriter.close();
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader implements Closeable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        @Override
        public void close() throws IOException {
            reader.close();
        }
    }

    public static void main(String[] args) {
        try (TheLabyrinth solver = new TheLabyrinth()) {
            solver.solve();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

import java.util.Scanner;

/**
 * Represents a 2D point with integer coordinates.
 */
class Point {
    private final int x;
    private final int y;

    public Point(int x, int y) {
        this.x = x;
        this.y = y;
    }

    public int getX() { return x; }
    public int getY() { return y; }
}

public class Main {

    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            if (!sc.hasNextInt()) return;

            Point p1 = new Point(sc.nextInt(), sc.nextInt());
            Point p2 = new Point(sc.nextInt(), sc.nextInt());
            Point p3 = new Point(sc.nextInt(), sc.nextInt());

            System.out.println(solve(p1, p2, p3));
        }
    }

    /**
     * Determines the minimum number of axis-aligned segments required to connect three points.
     *
     * @param p1 The first point.
     * @param p2 The second point.
     * @param p3 The third point.
     * @return 1, 2, or 3 segments.
     */
    public static int solve(Point p1, Point p2, Point p3) {
        // Case 1: All points lie on the same vertical or horizontal line.
        if (isAllCollinearAxisAligned(p1, p2, p3)) {
            return 1;
        }

        // Case 2: The points can be connected using 2 segments.
        // This occurs if any two points are axis-aligned and the third point 
        // can be joined via a single turn (L-shape) or by extending the existing line.
        if (canConnectInTwoSegments(p1, p2, p3)) {
            return 2;
        }

        // Case 3: Otherwise, 3 segments are the minimum required to connect all points.
        return 3;
    }

    private static boolean isAllCollinearAxisAligned(Point p1, Point p2, Point p3) {
        boolean allXSame = (p1.getX() == p2.getX() && p2.getX() == p3.getX());
        boolean allYSame = (p1.getY() == p2.getY() && p2.getY() == p3.getY());
        return allXSame || allYSame;
    }

    private static boolean canConnectInTwoSegments(Point p1, Point p2, Point p3) {
        // Check every permutation of pairs to see if any pair is axis-aligned
        // and can accommodate the third point in a 2-segment path.
        return checkPair(p1, p2, p3) || 
               checkPair(p1, p3, p2) || 
               checkPair(p2, p3, p1);
    }

    /**
     * Checks if points 'a' and 'b' are axis-aligned and if point 'c' 
     * can be connected to that axis-aligned line in a way that results in 2 segments total.
     */
    private static boolean checkPair(Point a, Point b, Point c) {
        // If a and b are on a vertical line
        if (a.getX() == b.getX()) {
            int minY = Math.min(a.getY(), b.getY());
            int maxY = Math.max(a.getY(), b.getY());
            // If c's y-coordinate is outside the range (minY, maxY), 
            // we can connect c by extending the line or making one turn.
            return c.getY() <= minY || c.getY() >= maxY;
        }

        // If a and b are on a horizontal line
        if (a.getY() == b.getY()) {
            int minX = Math.min(a.getX(), b.getX());
            int maxX = Math.max(a.getX(), b.getX());
            // If c's x-coordinate is outside the range (minX, maxX), 
            // we can connect c by extending the line or making one turn.
            return c.getX() <= minX || c.getX() >= maxX;
        }

        return false;
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to calculate the minimum number of segments required to connect three points
 * based on specific geometric axis-aligned constraints.
 */
public class Main {

    public static void main(String[] args) {
        new Main().run();
    }

    public void run() {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            PolylineSolver solver = new PolylineSolver();

            // Read three points from input
            Point p1 = new Point(reader.scanInt(), reader.scanInt());
            Point p2 = new Point(reader.scanInt(), reader.scanInt());
            Point p3 = new Point(reader.scanInt(), reader.scanInt());

            int result = solver.calculateMinSegments(p1, p2, p3);
            writer.println(result);
        } catch (Exception e) {
            // In a production environment, use a proper logging framework
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    /**
     * Represents a 2D coordinate.
     */
    static class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    /**
     * Contains the core logic for determining the minimum segments needed.
     */
    static class PolylineSolver {

        /**
         * Calculates the minimum segments needed for three points.
         * Logic:
         * 1 segment: All points are on the same horizontal or vertical line.
         * 2 segments: Two points form an axis-aligned segment and the third point 
         *             extends that line or can be reached via one perpendicular segment.
         * 3 segments: Default case.
         */
        public int calculateMinSegments(Point p1, Point p2, Point p3) {
            if (isCollinearVertical(p1, p2, p3) || isCollinearHorizontal(p1, p2, p3)) {
                return 1;
            }

            if (isAxisAlignedWithExtension(p1, p2, p3)) {
                return 2;
            }

            return 3;
        }

        private boolean isCollinearVertical(Point p1, Point p2, Point p3) {
            return p1.x == p2.x && p2.x == p3.x;
        }

        private boolean isCollinearHorizontal(Point p1, Point p2, Point p3) {
            return p1.y == p2.y && p2.y == p3.y;
        }

        private boolean isAxisAlignedWithExtension(Point p1, Point p2, Point p3) {
            return isVerticalWithExtension(p1, p2, p3) ||
                   isVerticalWithExtension(p1, p3, p2) ||
                   isVerticalWithExtension(p2, p3, p1) ||
                   isHorizontalWithExtension(p1, p2, p3) ||
                   isHorizontalWithExtension(p1, p3, p2) ||
                   isHorizontalWithExtension(p2, p3, p1);
        }

        private boolean isVerticalWithExtension(Point p1, Point p2, Point p3) {
            // Check if p1 and p2 are on a vertical line and p3's y is outside their range
            return p1.x == p2.x && (p3.y >= Math.max(p1.y, p2.y) || p3.y <= Math.min(p1.y, p2.y));
        }

        private boolean isHorizontalWithExtension(Point p1, Point p2, Point p3) {
            // Check if p1 and p2 are on a horizontal line and p3's x is outside their range
            return p1.y == p2.y && (p3.x >= Math.max(p1.x, p2.x) || p3.x <= Math.min(p1.x, p2.x));
        }
    }

    /**
     * High-performance reader for fast integer parsing.
     */
    static class FastReader {
        private static final int BUFFER_SIZE = 4096;
        private final BufferedInputStream in;
        private final byte[] buffer = new byte[BUFFER_SIZE];
        private int pointer = 0;
        private int bytesRead = 0;

        public FastReader(InputStream inputStream) {
            this.in = new BufferedInputStream(inputStream);
        }

        private int readByte() throws IOException {
            if (pointer >= bytesRead) {
                pointer = 0;
                bytesRead = in.read(buffer);
                if (bytesRead <= 0) return -1;
            }
            return buffer[pointer++] & 0xFF;
        }

        public int scanInt() throws IOException {
            int c = readByte();
            while (c != -1 && isWhiteSpace(c)) {
                c = readByte();
            }
            if (c == -1) return 0;

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }

            int res = 0;
            while (c != -1 && !isWhiteSpace(c)) {
                if (c >= '0' && c <= '9') {
                    res = res * 10 + (c - '0');
                }
                c = readByte();
            }
            return res * sign;
        }

        private boolean isWhiteSpace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver that determines the alignment type of three points on a 2D plane.
 * Result 1: All three points lie on a single horizontal or vertical line.
 * Result 2: At least two points are aligned on an axis, and the third is not between them.
 * Result 3: No two points share an X or Y coordinate.
 */
public class PointAlignmentSolver {

    public static void main(String[] args) {
        try {
            new PointAlignmentSolver().run();
        } catch (IOException e) {
            System.err.println("An error occurred while processing input: " + e.getMessage());
        }
    }

    public void run() throws IOException {
        try (FastReader reader = new FastReader(System.in);
             PrintWriter writer = new PrintWriter(System.out)) {

            solve(reader, writer);
        }
    }

    private void solve(FastReader reader, PrintWriter writer) throws IOException {
        Point p1 = new Point(reader.nextLong(), reader.nextLong());
        Point p2 = new Point(reader.nextLong(), reader.nextLong());
        Point p3 = new Point(reader.nextLong(), reader.nextLong());

        int result = calculateAlignmentType(p1, p2, p3);
        writer.println(result);
    }

    /**
     * Determines the result code based on point alignment.
     */
    private int calculateAlignmentType(Point p1, Point p2, Point p3) {
        if (isAllOnSingleAxis(p1, p2, p3)) {
            return 1;
        }
        if (isPartiallyAligned(p1, p2, p3)) {
            return 2;
        }
        return 3;
    }

    private boolean isAllOnSingleAxis(Point p1, Point p2, Point p3) {
        boolean allXEqual = (p1.x == p2.x && p2.x == p3.x);
        boolean allYEqual = (p1.y == p2.y && p2.y == p3.y);
        return allXEqual || allYEqual;
    }

    private boolean isPartiallyAligned(Point p1, Point p2, Point p3) {
        return isTwoPointsAlignedAndThirdIsOutside(p1, p2, p3) ||
               isTwoPointsAlignedAndThirdIsOutside(p1, p3, p2) ||
               isTwoPointsAlignedAndThirdIsOutside(p2, p3, p1);
    }

    /**
     * Checks if two points (a and b) share an axis and if the target point
     * lies outside the range of the first two on that axis.
     */
    private boolean isTwoPointsAlignedAndThirdIsOutside(Point a, Point b, Point target) {
        if (a.x == b.x) {
            return target.y <= Math.min(a.y, b.y) || target.y >= Math.max(a.y, b.y);
        }
        if (a.y == b.y) {
            return target.x <= Math.min(a.x, b.x) || target.x >= Math.max(a.x, b.x);
        }
        return false;
    }

    /**
     * Represents a coordinate in 2D space.
     */
    private static class Point {
        final long x;
        final long y;

        Point(long x, long y) {
            this.x = x;
            this.y = y;
        }
    }

    /**
     * Efficient reader for large inputs.
     */
    private static class FastReader implements AutoCloseable {
