import java.io.*;
import java.util.*;

/**
 * Main class containing the solution logic.
 */
public class Main {

    public static void main(String[] args) {
        try (FastReader in = new FastReader(System.in);
             FastWriter out = new FastWriter(System.out)) {

            Main solver = new Main();
            solver.solve(in, out);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /**
     * Solves the specific problem: determining the minimum number of lines 
     * required to cover three given points.
     */
    public void solve(FastReader in, FastWriter out) throws IOException {
        int[] x = new int[3];
        int[] y = new int[3];

        for (int i = 0; i < 3; i++) {
            x[i] = in.nextInt();
            y[i] = in.nextInt();
        }

        // If all points share the same X or same Y, they are on a single horizontal/vertical line.
        if (isPerfectlyCollinearHorizontalOrVertical(x, y)) {
            out.println(1);
            return;
        }

        int minLines = 3;

        for (int i = 0; i < 3; i++) {
            for (int j = i + 1; j < 3; j++) {
                int k = 3 - i - j; // The third point index

                if (x[i] == x[j]) {
                    // Points i and j are on a vertical line.
                    int minY = Math.min(y[i], y[j]);
                    int maxY = Math.max(y[i], y[j]);
                    if (isBoundaryOrOutside(y[k], minY, maxY)) {
                        minLines = Math.min(minLines, 2);
                    }
                } else if (y[i] == y[j]) {
                    // Points i and j are on a horizontal line.
                    int minX = Math.min(x[i], x[j]);
                    int maxX = Math.max(x[i], x[j]);
                    if (isBoundaryOrOutside(x[k], minX, maxX)) {
                        minLines = Math.min(minLines, 2);
                    }
                }
            }
        }

        out.println(minLines);
    }

    private boolean isPerfectlyCollinearHorizontalOrVertical(int[] x, int[] y) {
        return (x[0] == x[1] && x[1] == x[2]) || (y[0] == y[1] && y[1] == y[2]);
    }

    /**
     * Checks if a value is on the boundary or outside the range [min, max].
     * This preserves the original logic of the provided snippet.
     */
    private boolean isBoundaryOrOutside(int value, int min, int max) {
        return value <= min || max <= value;
    }
}

