/**
 * Result object for Segment Tree queries to avoid complex bit-packing.
 */
class QueryResult {
    public final int index;
    public final int value;

    public QueryResult(int index, int value) {
        this.index = index;
        this.value = value;
    }
}

/**
 * Segment Tree for Range Minimum Queries.
 */
class RangeMinimumSegTree {
    private final int[] tree;
    private final int[] indices;
    private final int size;

    public RangeMinimumSegTree(int n) {
        int powerOfTwo = 1;
        while (powerOfTwo < n) powerOfTwo <<= 1;
        this.size = powerOfTwo;
        this.tree = new int[size << 1];
        this.indices = new int[size << 1];
        Arrays.fill(tree, Integer.MAX_VALUE);
    }

    public void set(int id, int val) {
        int i = id | size;
        tree[i] = val;
        indices[i] = id;
        for (i >>= 1; i > 0; i >>= 1) {
            int left = i << 1;
            int right = (i << 1) + 1;
            if (tree[left] < tree[right]) {
                tree[i] = tree[left];
                indices[i] = indices[left];
            } else {
                tree[i] = tree[right];
                indices[i] = indices[right];
            }
        }
    }

    public QueryResult queryMin(int left, int right) {
        int minVal = Integer.MAX_VALUE;
        int minIdx = -1;
        int l = left | size;
        int r = (right | size) + 1;

        while (l < r) {
            if ((r & 1) == 1) {
                r--;
                if (tree[r] < minVal) {
                    minVal = tree[r];
                    minIdx = indices[r];
                }
            }
            if ((l & 1) == 1) {
                if (tree[l] < minVal) {
                    minVal = tree[l];
                    minIdx = indices[l];
                }
                l++;
            }
            l >>= 1;
            r >>= 1;
        }
        return new QueryResult(minIdx, minVal);
    }
}

