/**
 * A MultiSet implementation using a HashMap.
 */
class MultiSet<T> extends HashMap<T, Integer> {
    public void add(T key) {
        merge(key, 1, Integer::sum);
    }

    public void add(T key, int count) {
        merge(key, count, Integer::sum);
    }

    public void removeOne(T key) {
        Integer count = get(key);
        if (count == null) return;
        if (count <= 1) {
            remove(key);
        } else {
            put(key, count - 1);
        }
    }

    @Override
    public Integer get(Object key) {
        return super.getOrDefault(key, 0);
    }
}

/**
 * A sorted MultiSet implementation using a TreeMap.
