/**
 * A utility to analyze the relationship between three points on a 2D plane,
 * specifically focusing on axis-aligned collinearity.
 */
public class Main {

    /**
     * Represents a point in 2D space.
     */
    private static class Point {
        final long x;
        final long y;

        Point(long x, long y) {
            this.x = x;
            this.y = y;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        try {
            if (!scanner.hasNextLong()) {
                return;
            }

            // Parse coordinates for three points
            Point p1 = new Point(scanner.nextLong(), scanner.nextLong());
            Point p2 = new Point(scanner.nextLong(), scanner.nextLong());
            Point p3 = new Point(scanner.nextLong(), scanner.nextLong());

            // Output the relationship result
            System.out.println(analyzePointRelationship(p1, p2, p3));

        } catch (Exception e) {
            // In a real-world application, use a logging framework here
        } finally {
            scanner.close();
        }
    }

    /**
     * Determines the relationship between three points based on axis-aligned collinearity.
     *
     * @param p1 First point
     * @param p2 Second point
     * @param p3 Third point
     * @return "1" if all points are collinear on an axis, "2" if they form an axis-aligned 
     *         segment but the third point is outside, "3" if one point is between the others 
     *         or no axis-aligned relationship exists.
     */
    private static String analyzePointRelationship(Point p1, Point p2, Point p3) {
        // --- 1. Check for Vertical Alignment (Shared X) ---
        if (p1.x == p2.x && p1.x == p3.x) {
            return "1";
        }
        if (p1.x == p2.x) {
            return isStrictlyBetween(p3.y, p1.y, p2.y) ? "3" : "2";
        }
        if (p1.x == p3.x) {
            return isStrictlyBetween(p2.y, p1.y, p3.y) ? "3" : "2";
        }
        if (p2.x == p3.x) {
            return isStrictlyBetween(p1.y, p2.y, p3.y) ? "3" : "2";
        }

        // --- 2. Check for Horizontal Alignment (Shared Y) ---
        if (p1.y == p2.y && p1.y == p3.y) {
            return "1";
        }
        if (p1.y == p2.y) {
            return isStrictlyBetween(p3.x, p1.x, p2.x) ? "3" : "2";
        }
        if (p1.y == p3.y) {
            return isStrictlyBetween(p2.x, p1.x, p3.x) ? "3" : "2";
        }
        if (p2.y == p3.y) {
            return isStrictlyBetween(p1.x, p2.x, p3.x) ? "3" : "2";
        }

        // --- 3. Default Case ---
        // If no axis-aligned equalities are found, the original logic returns "3"
        return "3";
    }

    /**
     * Checks if a value is strictly between two other values.
     *
     * @param value The value to check.
     * @param a     The first boundary.
     * @param b     The second boundary.
     * @return true if value is strictly between a and b.
     */
    private static boolean isStrictlyBetween(long value, long a, long b) {
        return value > Math.min(a, b) && value < Math.max(a, b);
    }
}

import java.util.Scanner;

/**
 * PointGeometry classifies the relationship between three points based on 
 * their axis-aligned alignment and relative positions.
 */
public class PointGeometry {

    /**
     * Represents a 2D point with long coordinates.
     */
    private static class Point {
        final long x;
        final long y;

        Point(long x, long y) {
            this.x = x;
            this.y = y;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        try {
            if (!scanner.hasNextLong()) {
                return;
            }

            // Read coordinates for three points
            Point p1 = new Point(scanner.nextLong(), scanner.nextLong());
            Point p2 = new Point(scanner.nextLong(), scanner.nextLong());
            Point p3 = new Point(scanner.nextLong(), scanner.nextLong());

            // Process and output classification
            System.out.println(classifyPoints(p1, p2, p3));
        } finally {
            scanner.close();
        }
    }

    /**
     * Classifies the three points into one of three categories:
     * 1: All points lie on the same horizontal or vertical line.
     * 2: Two points share an axis-aligned coordinate, and the third is not between them.
     * 3: The points form a triangle, or the third point lies between the others on an axis-aligned line.
     *
     * @param p1 The first point.
     * @param p2 The second point.
     * @param p3 The third point.
     * @return The classification code (1, 2, or 3).
     */
    public static int classifyPoints(Point p1, Point p2, Point p3) {
        // Case 1: All three points are collinear on a single vertical or horizontal line.
        if (isAllXSame(p1, p2, p3) || isAllYSame(p1, p2, p3)) {
            return 1;
        }

        // Case 2: Check if any pair is vertically aligned (sharing X).
        Integer verticalResult = checkVerticalAlignment(p1, p2, p3);
        if (verticalResult != null) {
            return verticalResult;
        }

        // Case 3: Check if any pair is horizontally aligned (sharing Y).
        Integer horizontalResult = checkHorizontalAlignment(p1, p2, p3);
        if (horizontalResult != null) {
            return horizontalResult;
        }

        // Case 4: Default case (points form a triangle or are not axis-aligned).
        return 3;
    }

    private static boolean isAllXSame(Point p1, Point p2, Point p3) {
        return p1.x == p2.x && p2.x == p3.x;
    }

    private static boolean isAllYSame(Point p1, Point p2, Point p3) {
        return p1.y == p2.y && p2.y == p3.y;
    }

    /**
     * Checks pairs for vertical alignment and determines if the third point's 
     * Y coordinate falls between the pair's Y coordinates.
     * 
     * @return 3 if between, 2 if not between, or null if no vertical pair found.
     */
    private static Integer checkVerticalAlignment(Point p1, Point p2, Point p3) {
        if (p1.x == p2.x) return isBetween(p3.y, p1.y, p2.y) ? 3 : 2;
        if (p1.x == p3.x) return isBetween(p2.y, p1.y, p3.y) ? 3 : 2;
        if (p2.x == p3.x) return isBetween(p1.y, p2.y, p3.y) ? 3 : 2;
        return null;
    }

    /**
     * Checks pairs for horizontal alignment and determines if the third point's 
     * X coordinate falls between the pair's X coordinates.
     * 
     * @return 3 if between, 2 if not between, or null if no horizontal pair found.
     */
    private static Integer checkHorizontalAlignment(Point p1, Point p2, Point p3) {
        if (p1.y == p2.y) return isBetween(p3.x, p1.x, p2.x) ? 3 : 2;
        if (p1.y == p3.y) return isBetween(p2.x, p1.x, p3.x) ? 3 : 2;
        if (p2.y == p3.y) return isBetween(p1.x, p2.x, p3.x) ? 3 : 2;
        return null;
    }

    /**
     * Determines if a target value is strictly between two other values.
     */
    private static boolean isBetween(long target, long start, long end) {
        return target > Math.min(start, end) && target < Math.max(start, end);
    }
}

