/**
 * A utility to solve the geometry problem of finding the minimum number 
 * of axis-aligned segments required to connect three points on a 2D plane.
 */
public class PointConnectionSolver {

    /**
     * Represents a point in 2D space with integer coordinates.
     */
    private static class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        try {
            if (!scanner.hasNextInt()) return;

            // Read three points from standard input
            Point p1 = new Point(scanner.nextInt(), scanner.nextInt());
            Point p2 = new Point(scanner.nextInt(), scanner.nextInt());
            Point p3 = new Point(scanner.nextInt(), scanner.nextInt());

            System.out.println(calculateMinimumSegments(p1, p2, p3));
        } catch (Exception e) {
            // In a production environment, use a proper logging framework
            System.err.println("Error reading input: " + e.getMessage());
        } finally {
            scanner.close();
        }
    }

    /**
     * Calculates the minimum number of axis-aligned segments to connect three points.
     *
     * @param p1 The first point.
     * @param p2 The second point.
     * @param p3 The third point.
     * @return 1 if points are on one axis-aligned line, 
     *         2 if they can be connected by two segments, 
     *         3 otherwise.
     */
    public static int calculateMinimumSegments(Point p1, Point p2, Point p3) {
        if (isCollinearOnAxis(p1, p2, p3)) {
            return 1;
        }

        if (canConnectWithTwoSegments(p1, p2, p3)) {
            return 2;
        }

        return 3;
    }

    /**
     * Checks if all three points lie on the same horizontal or vertical line.
     */
    private static boolean isCollinearOnAxis(Point p1, Point p2, Point p3) {
        boolean allXEqual = (p1.x == p2.x && p2.x == p3.x);
        boolean allYEqual = (p1.y == p2.y && p2.y == p3.y);
        return allXEqual || allYEqual;
    }

    /**
     * Checks if the points can be connected using exactly two axis-aligned segments.
     * This is possible if any two points share an axis and the third point 
     * can be connected to that axis via a single perpendicular segment 
     * without requiring a third segment to reach the other points.
     */
    private static boolean canConnectWithTwoSegments(Point p1, Point p2, Point p3) {
        return checkPair(p1, p2, p3) || 
               checkPair(p1, p3, p2) || 
               checkPair(p2, p3, p1);
    }

    /**
     * Helper to check if two points (a, b) share an axis and if point c 
     * can be covered by a second axis-aligned segment.
     *
     * @param a First point of the pair.
     * @param b Second point of the pair.
     * @param c The third point to be connected.
     * @return true if two segments are sufficient.
     */
    private static boolean checkPair(Point a, Point b, Point c) {
        if (a.x == b.x) {
            // Points a and b form a vertical line.
            // We can connect c with one more segment if the junction point (a.x, c.y)
            // is not strictly between a.y and b.y (which would require 3 segments).
            // Note: being exactly at a.y or b.y (L-shape) also returns true.
            return c.y >= Math.max(a.y, b.y) || c.y <= Math.min(a.y, b.y);
        }

        if (a.y == b.y) {
            // Points a and b form a horizontal line.
            return c.x >= Math.max(a.x, b.x) || c.x <= Math.min(a.x, b.x);
        }

        return false;
    }
}

