/**
 * Represents a 2D coordinate point.
 */
class Point {
    final int x;
    final int y;

    Point(int x, int y) {
        this.x = x;
        this.y = y;
    }
}

/**
 * Contains the logic for analyzing the relationship between points.
 */
class GeometrySolver {

    /**
     * Calculates the result based on the alignment of the three points.
     * 
     * @param points An array of exactly 3 Point objects.
     * @return 1 if collinear on an axis, 2 if they form a specific L-shape 
     *         or extension, 3 otherwise.
     */
    public int calculateMinimumSegments(Point[] points) {
        if (points == null || points.length < 3) {
            throw new IllegalArgumentException("Exactly three points are required.");
        }

        if (areAllXCoordinatesEqual(points) || areAllYCoordinatesEqual(points)) {
            return 1;
        }

        if (hasSpecialAxisAlignment(points)) {
            return 2;
        }

        return 3;
    }

    private boolean areAllXCoordinatesEqual(Point[] points) {
        return points[0].x == points[1].x && points[1].x == points[2].x;
    }

    private boolean areAllYCoordinatesEqual(Point[] points) {
        return points[0].y == points[1].y && points[1].y == points[2].y;
    }

    /**
     * Checks if any two points share an axis and the third point 
     * lies outside the range defined by that axis.
     */
    private boolean hasSpecialAxisAlignment(Point[] p) {
        // Check pairs: (0,1) with 2, (0,2) with 1, (1,2) with 0
        return isSpecialPair(p[0], p[1], p[2]) ||
               isSpecialPair(p[0], p[2], p[1]) ||
               isSpecialPair(p[1], p[2], p[0]);
    }

    private boolean isSpecialPair(Point a, Point b, Point c) {
        if (a.x == b.x) {
            return isOutsideRange(c.y, a.y, b.y);
        }
        if (a.y == b.y) {
            return isOutsideRange(c.x, a.x, b.x);
        }
        return false;
    }

    private boolean isOutsideRange(int target, int val1, int val2) {
        int min = Math.min(val1, val2);
        int max = Math.max(val1, val2);
        // The original logic used >= and <= which includes the endpoints
        return target >= max || target <= min;
    }
}

import java.util.Scanner;

/**
 * A program to determine the geometric relationship between three points
 * based on axis-parallel collinearity and segment positioning.
 */
public class Main {

    /**
     * Represents a point in a 2D coordinate system.
     */
    public record Point(int x, int y) {}

    /**
     * Represents the possible relationship results between three points.
     */
    public enum Relationship {
        ALL_COLLINEAR_AXIS_PARALLEL(1),
        POINT_AT_OR_OUTSIDE_SEGMENT(2),
        POINT_INSIDE_SEGMENT_OR_NON_AXIS_COLLINEAR(3);

        private final int value;

        Relationship(int value) {
            this.value = value;
        }

        public int getValue() {
            return value;
        }
    }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;

            Point p1 = new Point(scanner.nextInt(), scanner.nextInt());
            Point p2 = new Point(scanner.nextInt(), scanner.nextInt());
            Point p3 = new Point(scanner.nextInt(), scanner.nextInt());

            Relationship result = RelationshipSolver.solve(p1, p2, p3);
            System.out.println(result.getValue());
        } catch (Exception e) {
            // In a production environment, use a logging framework
            System.err.println("Error processing input: " + e.getMessage());
        }
    }

    /**
     * Logic engine to determine the relationship between three points.
     */
    public static class RelationshipSolver {

        /**
         * Solves the relationship problem using axis-parallel logic.
         *
         * @param p1 First point
         * @param p2 Second point
         * @param p3 Third point
         * @return The Relationship type
         */
        public static Relationship solve(Point p1, Point p2, Point p3) {
            // Case 1: All three points are on the same horizontal or vertical line
            if (isAllSameX(p1, p2, p3) || isAllSameY(p1, p2, p3)) {
                return Relationship.ALL_COLLINEAR_AXIS_PARALLEL;
            }

            // Case 2 & 3: Check axis-parallel segments and the position of the 3rd point

            // Horizontal alignment checks
            if (p1.y() == p2.y()) {
                return isAtOrOutsideRange(p3.x(), p1.x(), p2.x()) 
                        ? Relationship.POINT_AT_OR_OUTSIDE_SEGMENT 
                        : Relationship.POINT_INSIDE_SEGMENT_OR_NON_AXIS_COLLINEAR;
            }
            if (p3.y() == p2.y()) {
                return isAtOrOutsideRange(p1.x(), p3.x(), p2.x()) 
                        ? Relationship.POINT_AT_OR_OUTSIDE_SEGMENT 
                        : Relationship.POINT_INSIDE_SEGMENT_OR_NON_AXIS_COLLINEAR;
            }
            if (p1.y() == p3.y()) {
                return isAtOrOutsideRange(p2.x(), p1.x(), p3.x()) 
                        ? Relationship.POINT_AT_OR_OUTSIDE_SEGMENT 
                        : Relationship.POINT_INSIDE_SEGMENT_OR_NON_AXIS_COLLINEAR;
            }

            // Vertical alignment checks
            if (p1.x() == p2.x()) {
                return isAtOrOutsideRange(p3.y(), p1.y(), p2.y()) 
                        ? Relationship.POINT_AT_OR_OUTSIDE_SEGMENT 
                        : Relationship.POINT_INSIDE_SEGMENT_OR_NON_AXIS_COLLINEAR;
            }
            if (p3.x() == p2.x()) {
                return isAtOrOutsideRange(p1.y(), p3.y(), p2.y()) 
                        ? Relationship.POINT_AT_OR_OUTSIDE_SEGMENT 
                        : Relationship.POINT_INSIDE_SEGMENT_OR_NON_AXIS_COLLINEAR;
            }
            if (p1.x() == p3.x()) {
                return isAtOrOutsideRange(p2.y(), p1.y(), p3.y()) 
                        ? Relationship.POINT_AT_OR_OUTSIDE_SEGMENT 
                        : Relationship.POINT_INSIDE_SEGMENT_OR_NON_AXIS_COLLINEAR;
            }

            // Default case: No axis-parallel relationship or they form a triangle
            return Relationship.POINT_INSIDE_SEGMENT_OR_NON_AXIS_COLLINEAR;
        }

        private static boolean isAllSameX(Point p1, Point p2, Point p3) {
            return p1.x() == p2.x() && p2.x() == p3.x();
        }

        private static boolean isAllSameY(Point p1, Point p2, Point p3) {
            return p1.y() == p2.y() && p2.y() == p3.y();
        }

        /**
         * Replicates the specific logic: value <= min || value >= max
         */
        private static boolean isAtOrOutsideRange(int value, int start, int end) {
            int min = Math.min(start, end);
            int max = Math.max(start, end);
            return value <= min || value >= max;
        }
    }
}

