/**
 * Provides logic to solve the geometric problem based on 3 input points.
 */
class GeometrySolver {

    /**
     * Calculates the result based on the arrangement of three points.
     * The logic determines a value based on the number of unique x and y coordinates
     * and specific collinearity/alignment conditions.
     *
     * @param points An array of exactly 3 Point objects.
     * @return The calculated integer result.
     */
    public static int solve(Point[] points) {
        int uniqueX = countUniqueCoordinates(points, true);
        int uniqueY = countUniqueCoordinates(points, false);

        int ans = Math.min(uniqueX, uniqueY);

        // Special case: if one dimension has 2 unique values and the other has 3,
        // check if the point with the unique coordinate is "between" the other two.
        if (ans == 2) {
            if (uniqueX == 2 && uniqueY == 3) {
                return checkAlignment(points, true);
            } else if (uniqueX == 3 && uniqueY == 2) {
                return checkAlignment(points, false);
            }
        }

        return ans;
    }

    private static int countUniqueCoordinates(Point[] points, boolean useX) {
        Set<Integer> set = new HashSet<>();
        for (Point p : points) {
            set.add(useX ? p.x : p.y);
        }
        return set.size();
    }

    /**
     * Checks if the third point's perpendicular coordinate lies between the 
     * coordinates of the two points that share a common coordinate.
     */
    private static int checkAlignment(Point[] points, boolean checkXAlignment) {
        for (int i = 0; i < 3; i++) {
            for (int j = i + 1; j < 3; j++) {
                int valI = checkXAlignment ? points[i].x : points[i].y;
                int valJ = checkXAlignment ? points[j].x : points[j].y;

                // If we found the two points sharing the same coordinate
                if (valI == valJ) {
                    int k = 3 - i - j; // The index of the third point

                    // Determine the values to check for "betweenness"
                    int otherValI = checkXAlignment ? points[i].y : points[i].x;
                    int otherValJ = checkXAlignment ? points[j].y : points[j].x;
                    int otherValK = checkXAlignment ? points[k].y : points[k].x;

                    if (isStrictlyBetween(otherValK, otherValI, otherValJ)) {
                        return 3;
                    }
                }
            }
        }
        return 2;
    }

    private static boolean isStrictlyBetween(int val, int a, int b) {
        return val > Math.min(a, b) && val < Math.max(a, b);
    }
}

