/**
 * A utility to classify sets of three points based on their geometric arrangement.
 * The classification follows the logic of determining if points are collinear,
 * form specific axis-aligned right triangles, or general triangles.
 */
public class PointClassifier {

    /**
     * Represents a 2D point with integer coordinates.
     */
    private static class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        try {
            Point p1 = new Point(scanner.nextInt(), scanner.nextInt());
            Point p2 = new Point(scanner.nextInt(), scanner.nextInt());
            Point p3 = new Point(scanner.nextInt(), scanner.nextInt());

            System.out.println(classifyPoints(p1, p2, p3));
        } catch (Exception e) {
            // Handle potential input errors gracefully
        } finally {
            scanner.close();
        }
    }

    /**
     * Classifies the three points into one of three categories.
     * 
     * @param p1 First point
     * @param p2 Second point
     * @param p3 Third point
     * @return 1 if collinear on an axis, 2 if an axis-aligned right triangle or special alignment, 3 otherwise.
     */
    public static int classifyPoints(Point p1, Point p2, Point p3) {
        if (isCollinearOnAxis(p1, p2, p3)) {
            return 1;
        }

        if (isSpecialGeometricCase(p1, p2, p3)) {
            return 2;
        }

        return 3;
    }

    private static boolean isCollinearOnAxis(Point p1, Point p2, Point p3) {
        return (p1.x == p2.x && p2.x == p3.x) || (p1.y == p2.y && p2.y == p3.y);
    }

    private static boolean isSpecialGeometricCase(Point p1, Point p2, Point p3) {
        // Case: The points form a right triangle where the legs are parallel to the axes
        if (isAxisAlignedRightTriangle(p1, p2, p3)) {
            return true;
        }

        // Case: Specific bounding box/alignment conditions from the original implementation
        if (isVerticalSpecialCase(p1, p2, p3) || isHorizontalSpecialCase(p1, p2, p3)) {
            return true;
        }

        return false;
    }

    private static boolean isAxisAlignedRightTriangle(Point p1, Point p2, Point p3) {
        long d12 = getSquaredDistance(p1, p2);
        long d23 = getSquaredDistance(p2, p3);
        long d31 = getSquaredDistance(p3, p1);

        // Pythagoras theorem: a^2 + b^2 = c^2
        boolean isRightTriangle = (d12 + d23 == d31) || (d12 + d31 == d23) || (d23 + d31 == d12);

        // Check if at least one side is vertical or horizontal
        boolean hasAxisAlignment = (p1.x == p2.x || p1.x == p3.x || p2.x == p3.x ||
                                    p1.y == p2.y || p1.y == p3.y || p2.y == p3.y);

        return isRightTriangle && hasAxisAlignment;
    }

    private static boolean isVerticalSpecialCase(Point p1, Point p2, Point p3) {
        return checkVerticalCondition(p1, p2, p3) ||
               checkVerticalCondition(p2, p3, p1) ||
               checkVerticalCondition(p3, p1, p2);
    }

    private static boolean checkVerticalCondition(Point a, Point b, Point c) {
        if (a.x == b.x) {
            int minY = Math.min(a.y, b.y);
            int maxY = Math.max(a.y, b.y);
            // Condition: Third point's X is different and Y is outside the vertical segment's range
            return (c.x != a.x) && (c.y < minY || c.y > maxY);
        }
        return false;
    }

    private static boolean isHorizontalSpecialCase(Point p1, Point p2, Point p3) {
        return checkHorizontalCondition(p1, p2, p3) ||
               checkHorizontalCondition(p2, p3, p1) ||
               checkHorizontalCondition(p3, p1, p2);
    }

    private static boolean checkHorizontalCondition(Point a, Point b, Point c) {
        if (a.y == b.y) {
            int minX = Math.min(a.x, b.x);
            int maxX = Math.max(a.x, b.x);
            // Condition: Third point's Y is different and X is outside the horizontal segment's range
            return (c.y != a.y) && (c.x < minX || c.x > maxX);
        }
        return false;
    }

    /**
     * Calculates the squared Euclidean distance between two points to maintain integer precision.
     */
    private static long getSquaredDistance(Point p1, Point p2) {
        long dx = (long) p1.x - p2.x;
        long dy = (long) p1.y - p2.y;
        return dx * dx + dy * dy;
    }
}

