/**
 * A solution to classify three points into one of three geometric types:
 * Type 1: All points are on the same axis-aligned line.
 * Type 2: Two points are axis-aligned, but the third point's coordinate 
 *         is not between the other two in the perpendicular axis.
 * Type 3: Any other configuration.
 */
public class Solution {

    /**
     * Represents a 2D coordinate.
     */
    public record Point(int x, int y) {}

    public static void main(String[] args) {
        try (FastReader in = new FastReader(System.in);
             FastWriter out = new FastWriter(System.out)) {

            Point[] points = new Point[3];
            for (int i = 0; i < 3; i++) {
                points[i] = new Point(in.nextInt(), in.nextInt());
            }

            out.print(classifyPoints(points));

        } catch (Exception e) {
            // In a production environment, use a logging framework.
            e.printStackTrace();
        }
    }

    /**
     * Orchestrates the classification of the points.
     * 
     * @param points An array of 3 Point objects.
     * @return The classification type (1, 2, or 3).
     */
    private static int classifyPoints(Point[] points) {
        if (isAllPointsOnSameX(points) || isAllPointsOnSameY(points)) {
            return 1;
        }

        if (hasUnsandwichedAxisAlignedPair(points)) {
            return 2;
        }

        return 3;
    }

    private static boolean isAllPointsOnSameX(Point[] points) {
        return points[0].x() == points[1].x() && points[1].x() == points[2].x();
    }

    private static boolean isAllPointsOnSameY(Point[] points) {
        return points[0].y() == points[1].y() && points[1].y() == points[2].y();
    }

    /**
     * Checks if any two points form an axis-aligned segment where the third 
     * point's perpendicular coordinate does not lie between the segment's endpoints.
     */
    private static boolean hasUnsandwichedAxisAlignedPair(Point[] p) {
        // Check for vertical pairs (same X) and unsandwiched Y
        if (p[0].x() == p[1].x() && !isBetween(p[2].y(), p[0].y(), p[1].y())) return true;
        if (p[0].x() == p[2].x() && !isBetween(p[1].y(), p[0].y(), p[2].y())) return true;
        if (p[1].x() == p[2].x() && !isBetween(p[0].y(), p[1].y(), p[2].y())) return true;

        // Check for horizontal pairs (same Y) and unsandwiched X
        if (p[0].y() == p[1].y() && !isBetween(p[2].x(), p[0].x(), p[1].x())) return true;
        if (p[0].y() == p[2].y() && !isBetween(p[1].x(), p[0].x(), p[2].x())) return true;
        if (p[1].y() == p[2].y() && !isBetween(p[0].x(), p[1].x(), p[2].x())) return true;

        return false;
    }

    /**
     * Helper to determine if a target value is strictly between two bounds.
     */
    private static boolean isBetween(int target, int boundA, int boundB) {
        return target > Math.min(boundA, boundB) && target < Math.max(boundA, boundB);
    }

    // --- IO Utilities ---

    /**
     * High-performance input reader.
     */
    static class FastReader implements AutoCloseable {
