/**
 * ShapeClassifier determines the geometric relationship between three points.
 * Result types:
 * 1: All three points are collinear on an axis-parallel line.
 * 2: Two points share a coordinate, but the third point does not fall between them.
 * 3: General triangle or a right-angle configuration where the third point falls between the others.
 */
public class ShapeClassifier {

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        Point[] points = new Point[3];

        try {
            for (int i = 0; i < 3; i++) {
                points[i] = new Point(sc.nextInt(), sc.nextInt());
            }
            System.out.println(calculateShapeType(points));
        } catch (Exception e) {
            // In a production environment, use a proper logging framework
            System.err.println("Error processing input: " + e.getMessage());
        }
    }

    /**
     * Core logic to classify the shape formed by three points.
     */
    private static int calculateShapeType(Point[] p) {
        // Case 1: All points share the same X or the same Y (Collinear on an axis-parallel line)
        if (allXEqual(p) || allYEqual(p)) {
            return 1;
        }

        // Case 2: Check for vertical segments (Two points share the same X)
        if (p[0].x == p[1].x) return isBetween(p[2].y, p[0].y, p[1].y) ? 3 : 2;
        if (p[0].x == p[2].x) return isBetween(p[1].y, p[0].y, p[2].y) ? 3 : 2;
        if (p[1].x == p[2].x) return isBetween(p[0].y, p[1].y, p[2].y) ? 3 : 2;

        // Case 3: Check for horizontal segments (Two points share the same Y)
        if (p[0].y == p[1].y) return isBetween(p[2].x, p[0].x, p[1].x) ? 3 : 2;
        if (p[0].y == p[2].y) return isBetween(p[1].x, p[0].x, p[2].x) ? 3 : 2;
        if (p[1].y == p[2].y) return isBetween(p[0].x, p[1].x, p[2].x) ? 3 : 2;

        // Case 4: No coordinates are shared
        return 3;
    }

    private static boolean allXEqual(Point[] p) {
        return p[0].x == p[1].x && p[1].x == p[2].x;
    }

    private static boolean allYEqual(Point[] p) {
        return p[0].y == p[1].y && p[1].y == p[2].y;
    }

    /**
     * Checks if the target value is strictly between the bounds.
     */
    private static boolean isBetween(int target, int valA, int valB) {
        return target > Math.min(valA, valB) && target < Math.max(valA, valB);
