/**
 * Utility class for array manipulations.
 */
class ArrayUtils {
    private static final Random RANDOM = new Random();

    /**
     * Shuffles an array to prevent worst-case O(n^2) scenarios in dual-pivot quicksort.
     */
    public static void shuffle(int[] array) {
        for (int i = array.length - 1; i > 0; i--) {
            int index = RANDOM.nextInt(i + 1);
            int temp = array[index];
            array[index] = array[i];
            array[i] = temp;
        }
    }

    public static void shuffle(long[] array) {
        for (int i = array.length - 1; i > 0; i--) {
            int index = RANDOM.nextInt(i + 1);
            long temp = array[index];
            array[index] = array[i];
            array[i] = temp;
        }
    }

    public static void sort(int[] array) {
        shuffle(array);
        Arrays.sort(array);
    }

    public static void sort(long[] array) {
        shuffle(array);
        Arrays.sort(array);
    }
}

/**
 * Contains the logic to solve the segment connectivity problem.
 */
class SegmentProblemSolver {

    /**
     * Reads segment data and determines the connectivity score.
     * 
     * @param reader The input reader.
     * @return A score: 1 (highly connected), 2 (partially connected), or 3 (disconnected).
     */
    public int solve(FastReader reader) {
        int s1 = reader.nextInt(), e1 = reader.nextInt();
        int s2 = reader.nextInt(), e2 = reader.nextInt();
        int s3 = reader.nextInt(), e3 = reader.nextInt();

        int score = 3;

        // Check if segments share a starting point but the third end is outside the other ends' range
        if (s1 == s2 && isOutsideRange(e3, e1, e2)) score = 2;
        if (s1 == s3 && isOutsideRange(e2, e1, e3)) score = 2;
        if (s2 == s3 && isOutsideRange(e1, e2, e3)) score = 2;

        // Check if segments share an ending point but the third start is outside the other starts' range
        if (e1 == e2 && isOutsideRange(s3, s1, s2)) score = 2;
        if (e1 == e3 && isOutsideRange(s2, s1, s3)) score = 2;
        if (e2 == e3 && isOutsideRange(s1, s2, s3)) score = 2;

        // Check if all starts are identical or all ends are identical
        if ((s1 == s2 && s2 == s3) || (e1 == e2 && e2 == e3)) {
            score = 1;
        }

        return score;
    }

    /**
     * Helper to determine if a value is outside the range formed by two other values.
     */
    private boolean isOutsideRange(int target, int valA, int valB) {
        return target >= Math.max(valA, valB) || target <= Math.min(valA, valB);
    }
}

