/**
 * A utility class to classify the shape formed by three points.
 * The classification is based on axis-aligned properties.
 */
public class TriangleShapeClassifier {

    /**
     * Represents a 2D coordinate.
     */
    public record Point(int x, int y) {}

    /**
     * Defines the possible classifications for the set of points.
     */
    public enum ShapeType {
        AXIS_ALIGNED_LINE(1),
        AXIS_ALIGNED_RIGHT_TRIANGLE(2),
        OTHER(3);

        private final int value;

        ShapeType(int value) {
            this.value = value;
        }

        public int getValue() {
            return value;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        try {
            List<Point> points = new ArrayList<>();
            for (int i = 0; i < 3; i++) {
                if (scanner.hasNextInt()) {
                    int x = scanner.nextInt();
                    int y = scanner.nextInt();
                    points.add(new Point(x, y));
                }
            }

            if (points.size() < 3) {
                return;
            }

            ShapeType result = classify(points.get(0), points.get(1), points.get(2));
            System.out.println(result.getValue());

        } catch (NoSuchElementException e) {
            // Handle unexpected end of input
        } finally {
            scanner.close();
        }
    }

    /**
     * Classifies the relationship between three points.
     * 
     * @param p1 First point
     * @param p2 Second point
     * @param p3 Third point
     * @return The ShapeType classification
     */
    public static ShapeType classify(Point p1, Point p2, Point p3) {
        if (isAxisAlignedCollinear(p1, p2, p3)) {
            return ShapeType.AXIS_ALIGNED_LINE;
        }

        if (isAxisAlignedRightTriangle(p1, p2, p3)) {
            return ShapeType.AXIS_ALIGNED_RIGHT_TRIANGLE;
        }

        return ShapeType.OTHER;
    }

    /**
     * Checks if all three points lie on the same horizontal or vertical line.
     */
    private static boolean isAxisAlignedCollinear(Point p1, Point p2, Point p3) {
        boolean allXSame = (p1.x() == p2.x()) && (p2.x() == p3.x());
        boolean allYSame = (p1.y() == p2.y()) && (p2.y() == p3.y());
        return allXSame || allYSame;
    }

    /**
     * Checks if the points form a right-angled triangle where the legs 
     * are parallel to the X and Y axes.
     */
    private static boolean isAxisAlignedRightTriangle(Point p1, Point p2, Point p3) {
        return isCornerOfRightTriangle(p1, p2, p3) ||
               isCornerOfRightTriangle(p2, p1, p3) ||
               isCornerOfRightTriangle(p3, p1, p2);
    }

    /**
     * Checks if a specific point acts as the vertex (corner) of an axis-aligned right triangle.
     * 
     * @param corner The potential vertex of the right angle
     * @param pA An adjacent point
     * @param pB The other adjacent point
     * @return true if the corner forms a right angle with sides parallel to the axes
     */
    private static boolean isCornerOfRightTriangle(Point corner, Point pA, Point pB) {
        // A corner is axis-aligned if it shares an X with one point and a Y with the other
        boolean sharesXWithA = (corner.x() == pA.x());
        boolean sharesYWithB = (corner.y() == pB.y());

        boolean sharesXWithB = (corner.x() == pB.x());
        boolean sharesYWithA = (corner.y() == pA.y());

        return (sharesXWithA && sharesYWithB) || (sharesXWithB && sharesYWithA);
    }
}

