/**
 * Contains the logic for analyzing geometric relationships between points.
 */
class GeometrySolver {

    /**
     * Determines the type of geometric arrangement of three points.
     * 
     * @param a First point
     * @param b Second point
     * @param c Third point
     * @return 1 if all points are on a single horizontal/vertical line,
     *         2 if they form an axis-aligned right triangle/segment,
     *         3 otherwise.
     */
    public int determineTriangleType(Point a, Point b, Point c) {
        if (isAllOnSameAxis(a, b, c)) {
            return 1;
        }

        if (hasAxisAlignedRightAngle(a, b, c)) {
            return 2;
        }

        return 3;
    }

    /**
     * Checks if all three points share the same X or same Y coordinate.
     */
    private boolean isAllOnSameAxis(Point a, Point b, Point c) {
        boolean sameX = (a.getX() == b.getX() && b.getX() == c.getX());
        boolean sameY = (a.getY() == b.getY() && b.getY() == c.getY());
        return sameX || sameY;
    }

    /**
     * Checks if any permutation of the points forms an axis-aligned right angle 
     * where the third point lies on a segment formed by the others.
     */
    private boolean hasAxisAlignedRightAngle(Point a, Point b, Point c) {
        return isPointOnAxisAlignedSegment(a, b, c) ||
               isPointOnAxisAlignedSegment(b, a, c) ||
               isPointOnAxisAlignedSegment(a, c, b) ||
               isPointOnAxisAlignedSegment(c, a, b) ||
               isPointOnAxisAlignedSegment(b, c, a) ||
               isPointOnAxisAlignedSegment(c, b, a);
    }

    /**
     * Checks if the target point lies on an axis-aligned segment formed by p1 and p2.
     * Specifically follows the original logic where the corner is defined by p1 and p2.
     */
    private boolean isPointOnAxisAlignedSegment(Point p1, Point p2, Point target) {
        // Check if target is on a vertical segment through p1
        boolean onVerticalSegment = (target.getX() == p1.getX()) &&
                isBetween(target.getY(), p1.getY(), p2.getY());

        // Check if target is on a horizontal segment through p2
        boolean onHorizontalSegment = (target.getY() == p2.getY()) &&
                isBetween(target.getX(), p2.getX(), p1.getX());

        return onVerticalSegment || onHorizontalSegment;
    }

    private boolean isBetween(int value, int start, int end) {
        return value >= Math.min(start, end) && value <= Math.max(start, end);
    }
}

