/**
 * Logic solver for the geometric point connectivity problem.
 */
class ProblemSolver {

    /**
     * Solves the problem based on the spatial relationship of 3 points.
     * Returns the minimum number of axis-aligned segments required to connect them.
     */
    public void solve(FastReader in, PrintWriter out) {
        Point[] points = new Point[3];
        for (int i = 0; i < 3; i++) {
            points[i] = new Point(in.nextInt(), in.nextInt());
        }

        out.println(calculateResult(points));
    }

    private int calculateResult(Point[] points) {
        if (isCollinearOnAxis(points)) {
            return 1;
        }

        int pointsWithNeighbors = countPointsWithAxisAlignedNeighbors(points);

        // If every point shares an axis with at least one other point (e.g., L-shape)
        if (pointsWithNeighbors == 3) {
            return 2;
        }

        // If no points share an axis with any other point
        if (pointsWithNeighbors == 0) {
            return 3;
        }

        // Case: Exactly one pair of points shares an axis, and the third is isolated
        return handleIsolatedPointCase(points);
    }

    private boolean isCollinearOnAxis(Point[] points) {
        boolean allSameX = points[0].x == points[1].x && points[1].x == points[2].x;
        boolean allSameY = points[0].y == points[1].y && points[1].y == points[2].y;
        return allSameX || allSameY;
    }

    private int countPointsWithAxisAlignedNeighbors(Point[] points) {
        int count = 0;
        for (int i = 0; i < points.length; i++) {
            if (hasNeighbor(points[i], points, i)) {
                count++;
            }
        }
        return count;
    }

    private boolean hasNeighbor(Point p, Point[] allPoints, int currentIndex) {
        for (int i = 0; i < allPoints.length; i++) {
            if (i == currentIndex) continue;
            if (p.x == allPoints[i].x || p.y == allPoints[i].y) {
                return true;
            }
        }
        return false;
    }

    private int handleIsolatedPointCase(Point[] points) {
        Point first = null, second = null, third = null;
        boolean[] used = new boolean[3];

        // Find the pair that shares an axis
        for (int i = 0; i < 3; i++) {
            for (int j = i + 1; j < 3; j++) {
                if (points[i].x == points[j].x || points[i].y == points[j].y) {
                    first = points[i];
                    second = points[j];
                    used[i] = used[j] = true;
                    break;
                }
            }
            if (first != null) break;
        }

        // Find the remaining isolated point
        for (int i = 0; i < 3; i++) {
            if (!used[i]) {
                third = points[i];
                break;
            }
        }

        // If pair is vertical, check if third point's Y is between the pair's Y range
        if (first.x == second.x) {
            int minY = Math.min(first.y, second.y);
            int maxY = Math.max(first.y, second.y);
            return (third.y > minY && third.y < maxY) ? 3 : 2;
        } else {
            // If pair is horizontal, check if third point's X is between the pair's X range
            int minX = Math.min(first.x, second.x);
            int maxX = Math.max(first.x, second.x);
            return (third.x > minX && third.x < maxX) ? 3 : 2;
        }
    }
}

