/**
 * Solves the problem of determining the minimum number of lines (1, 2, or 3)
 * required to connect three points based on specific axial constraints.
 */
public class Round340 {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            Point p1 = reader.nextPoint();
            Point p2 = reader.nextPoint();
            Point p3 = reader.nextPoint();

            int result = calculateMinimumLines(p1, p2, p3);
            writer.println(result);
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Core logic to determine the line count.
     * 
     * @param p1 First point
     * @param p2 Second point
     * @param p3 Third point
     * @return 1, 2, or 3 lines depending on the geometric alignment.
     */
    private static int calculateMinimumLines(Point p1, Point p2, Point p3) {
        // Case 1: All three points are on the same horizontal or vertical line
        if (allXSame(p1, p2, p3) || allYSame(p1, p2, p3)) {
            return 1;
        }

        // Case 2: Two points share an X coordinate (forming a vertical segment)
        if (p1.x == p2.x) return isBetween(p3.y, p1.y, p2.y) ? 3 : 2;
        if (p2.x == p3.x) return isBetween(p1.y, p2.y, p3.y) ? 3 : 2;
        if (p1.x == p3.x) return isBetween(p2.y, p1.y, p3.y) ? 3 : 2;

        // Case 3: Two points share a Y coordinate (forming a horizontal segment)
        if (p1.y == p2.y) return isBetween(p3.x, p1.x, p2.x) ? 3 : 2;
        if (p2.y == p3.y) return isBetween(p1.x, p2.x, p3.x) ? 3 : 2;
        if (p1.y == p3.y) return isBetween(p2.x, p1.x, p3.x) ? 3 : 2;

        // Case 4: General case (no axis-aligned relationships found)
        return 3;
    }

    private static boolean isBetween(int val, int a, int b) {
        return val > Math.min(a, b) && val < Math.max(a, b);
    }

    private static boolean allXSame(Point p1, Point p2, Point p3) {
        return p1.x == p2.x && p1.x == p3.x;
    }

    private static boolean allYSame(Point p1, Point p2, Point p3) {
        return p1.y == p2.y && p1.y == p3.y;
    }

    /**
     * Represents a 2D coordinate.
     */
    static class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    /**
     * Fast I/O utility for efficient reading.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream s) {
            br = new BufferedReader(new InputStreamReader(s));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public Point nextPoint() throws IOException {
            return new Point(nextInt(), nextInt());
        }
    }
}

