/**
 * Contains the core logic to solve the minimum segment coverage problem.
 */
class ProblemSolver {

    /**
     * Reads three points from the input and determines the minimum number of 
     * axis-aligned segments needed to cover them.
     * 
     * @param reader The FastReader utility to fetch input.
     * @return 1, 2, or 3 segments.
     */
    public int solve(FastReader reader) {
        Point[] points = new Point[3];
        for (int i = 0; i < 3; i++) {
            points[i] = new Point(reader.nextInt(), reader.nextInt());
        }

        if (isAllOnOneLine(points)) {
            return 1;
        }

        if (canCoverWithTwoSegments(points)) {
            return 2;
        }

        return 3;
    }

    /**
     * Returns true if all points lie on the same horizontal or vertical line.
     */
    private boolean isAllOnOneLine(Point[] points) {
        boolean allSameX = (points[0].x == points[1].x && points[1].x == points[2].x);
        boolean allSameY = (points[0].y == points[1].y && points[1].y == points[2].y);
        return allSameX || allSameY;
    }

    /**
     * Determines if the three points can be covered by exactly two axis-aligned segments.
     * This is possible if any two points share a coordinate and the third point 
     * can be connected via an axis-aligned segment to one of the endpoints 
     * of the segment formed by the first two.
     */
    private boolean canCoverWithTwoSegments(Point[] points) {
        // Check every pair of points (i, j) to see if they can form the first segment,
        // and if the remaining point k can be covered by a second axis-aligned segment.
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                if (i == j) continue;

                int k = 3 - i - j; // The index of the third point (0+1+2=3)

                if (isVerticalConnectionPossible(points[i], points[j], points[k]) || 
                    isHorizontalConnectionPossible(points[i], points[j], points[k])) {
                    return true;
                }
            }
        }
        return false;
    }

    private boolean isVerticalConnectionPossible(Point p1, Point p2, Point p3) {
        // If p1 and p2 are on a vertical line, p3 can be covered with 2 segments if 
        // its Y-coordinate is not strictly between the Y-coordinates of p1 and p2.
        if (p1.x != p2.x) return false;
        return p3.y <= Math.min(p1.y, p2.y) || p3.y >= Math.max(p1.y, p2.y);
    }

    private boolean isHorizontalConnectionPossible(Point p1, Point p2, Point p3) {
        // If p1 and p2 are on a horizontal line, p3 can be covered with 2 segments if 
        // its X-coordinate is not strictly between the X-coordinates of p1 and p2.
        if (p1.y != p2.y) return false;
        return p3.x <= Math.min(p1.x, p2.x) || p3.x >= Math.max(p1.x, p2.x);
    }
}

