/**
 * Represents a 2D point with integer coordinates.
 * Using a record provides immutability and reduces boilerplate.
 */
record Point(int x, int y) {}

/**
 * Encapsulates the geometric logic required to solve the problem.
 */
class GeometryCalculator {

    /**
     * Calculates the relationship value for three given points.
     * 
     * @param p1 First point
     * @param p2 Second point
     * @param p3 Third point
     * @return 1 if all points share an axis, 2 or 3 based on positional logic.
     */
    public int calculateRelationship(Point p1, Point p2, Point p3) {
        if (isCollinearOnAxis(p1, p2, p3)) {
            return 1;
        }

        // Check if any pair of points shares an X or Y coordinate.
        // The order of checks preserves the original program's priority logic.
        if (p1.x() == p2.x()) {
            return isBetween(p3.y(), p1.y(), p2.y()) ? 3 : 2;
        } else if (p1.x() == p3.x()) {
            return isBetween(p2.y(), p1.y(), p3.y()) ? 3 : 2;
        } else if (p2.x() == p3.x()) {
            return isBetween(p1.y(), p2.y(), p3.y()) ? 3 : 2;
        } else if (p1.y() == p2.y()) {
            return isBetween(p3.x(), p1.x(), p2.x()) ? 3 : 2;
        } else if (p1.y() == p3.y()) {
            return isBetween(p2.x(), p1.x(), p3.x()) ? 3 : 2;
        } else if (p2.y() == p3.y()) {
            return isBetween(p1.x(), p2.x(), p3.x()) ? 3 : 2;
        }

        // If no two points share an X or Y coordinate, the result is 3.
        return 3;
    }

    /**
     * Checks if all three points lie on the same horizontal or vertical line.
     */
    private boolean isCollinearOnAxis(Point p1, Point p2, Point p3) {
        boolean allXSame = (p1.x() == p2.x() && p2.x() == p3.x());
        boolean allYSame = (p1.y() == p2.y() && p2.y() == p3.y());
        return allXSame || allYSame;
    }

    /**
     * Determines if the target value is strictly between start and end.
     */
    private boolean isBetween(int target, int start, int end) {
        return (start < target && target < end) || (end < target && target < start);
    }
}

