/**
 * Contains the core logic for solving the point coverage problem.
 */
class ProblemSolver {
    private final FastReader reader;

    public ProblemSolver(FastReader reader) {
        this.reader = reader;
    }

    /**
     * Processes the input and calculates the minimum number of axis-parallel lines 
     * required to cover the three points.
     */
    public int solve() throws IOException {
        Point[] points = new Point[3];
        Set<Integer> uniqueX = new HashSet<>();
        Set<Integer> uniqueY = new HashSet<>();

        for (int i = 0; i < 3; i++) {
            int x = reader.nextInt();
            int y = reader.nextInt();
            points[i] = new Point(x, y);
            uniqueX.add(x);
            uniqueY.add(y);
        }

        int ans = Math.min(uniqueX.size(), uniqueY.size());

        // If the minimum lines needed based on unique coordinates is 2, 
        // we must check for a "staggered" configuration that requires 3 lines.
        if (ans == 2) {
            if (isStaggered(points)) {
                return 3;
            }
        }

        return ans;
    }

    /**
     * Determines if the points are arranged in a way that prevents 
     * coverage with only 2 axis-parallel lines.
     */
    private boolean isStaggered(Point[] points) {
        // Check configuration based on X-axis sorting
        Arrays.sort(points, Comparator.comparingInt(Point::x).thenComparingInt(Point::y));
        if (points[0].x() == points[1].x() && isBetween(points[2].y(), points[0].y(), points[1].y())) {
            return true;
        }
        if (points[1].x() == points[2].x() && isBetween(points[0].y(), points[1].y(), points[2].y())) {
            return true;
        }

        // Check configuration based on Y-axis sorting
        Arrays.sort(points, Comparator.comparingInt(Point::y).thenComparingInt(Point::x));
        if (points[0].y() == points[1].y() && isBetween(points[2].x(), points[0].x(), points[1].x())) {
            return true;
        }
        if (points[1].y() == points[2].y() && isBetween(points[0].x(), points[1].x(), points[2].x())) {
            return true;
        }

        return false;
    }

    /**
     * Checks if a value lies strictly between two other values.
     */
    private boolean isBetween(int val, int low, int high) {
        return val > Math.min(low, high) && val < Math.max(low, high);
    }
}

