/**
 * A solver to determine the minimum number of axis-aligned lines 
 * required to cover a set of three points based on specific 
 * geometric alignment rules.
 */
public class PointCoverageSolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            Point[] points = readPoints(reader, 3);
            out.println(calculateMinimumLines(points));
        } catch (Exception e) {
            // In a production environment, use a proper logging framework
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Reads a specified number of points from the input stream.
     */
    private static Point[] readPoints(FastReader reader, int count) {
        Point[] points = new Point[count];
        for (int i = 0; i < count; i++) {
            long x = reader.nextLong();
            long y = reader.nextLong();
            points[i] = new Point(x, y);
        }
        return points;
    }

    /**
     * Determines the line coverage count (1, 2, or 3) based on the 
     * provided geometric rules.
     */
    private static int calculateMinimumLines(Point[] points) {
        if (isCollinearAxisAligned(points)) {
            return 1;
        }

        if (canBeCoveredByTwoLines(points)) {
            return 2;
        }

        return 3;
    }

    /**
     * Checks if all points lie on a single vertical or horizontal line.
     */
    private static boolean isCollinearAxisAligned(Point[] points) {
        boolean allXSame = true;
        boolean allYSame = true;

        for (int i = 1; i < points.length; i++) {
            if (points[i].x != points[0].x) {
                allXSame = false;
            }
            if (points[i].y != points[0].y) {
                allYSame = false;
            }
        }
        return allXSame || allYSame;
    }

    /**
     * Implements the specific check: if any two points share an axis, 
     * checks if the third point lies outside the bounds of the shared segment.
     */
    private static boolean canBeCoveredByTwoLines(Point[] points) {
        for (int i = 0; i < points.length; i++) {
            for (int j = 0; j < points.length; j++) {
                if (i == j) continue;

                // Identify the third point index
                int k = getThirdIndex(i, j, points.length);
                Point pI = points[i];
                Point pJ = points[j];
                Point pK = points[k];

                // If pI and pJ share an X coordinate
                if (pI.x == pJ.x) {
                    if (pK.y <= Math.min(pI.y, pJ.y) || pK.y >= Math.max(pI.y, pJ.y)) {
                        return true;
                    }
                }

                // If pI and pJ share a Y coordinate
                if (pI.y == pJ.y) {
                    if (pK.x <= Math.min(pI.x, pJ.x) || pK.x >= Math.max(pI.x, pJ.x)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    private static int getThirdIndex(int i, int j, int total) {
        for (int idx = 0; idx < total; idx++) {
            if (idx != i && idx != j) return idx;
        }
        return -1;
    }

    /**
     * Represents a 2D coordinate.
     */
    static class Point {
        final long x;
        final long y;

        Point(long x, long y) {
            this.x = x;
            this.y = y;
        }
    }

    /**
     * High-performance input reader for large data volumes.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public long nextLong() {
            return Long.parseLong(next());
        }
    }
}

