/**
 * Refactored solution for the "Three Points" problem.
 * Determines the minimum number of straight lines needed to connect three points.
 */
public class CF617D {

    public static void main(String[] args) {
        FastReader sc = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            Point p1 = new Point(sc.nextInt(), sc.nextInt());
            Point p2 = new Point(sc.nextInt(), sc.nextInt());
            Point p3 = new Point(sc.nextInt(), sc.nextInt());

            out.println(solve(p1, p2, p3));
        } catch (Exception e) {
            // In a competitive programming context, we usually let the error exit,
            // but in production, we would log this.
        } finally {
            out.close();
        }
    }

    /**
     * Logic to determine the required number of lines.
     * 
     * @param p1 First point
     * @param p2 Second point
     * @param p3 Third point
     * @return 1 (collinear), 2 (two points same), or 3 (triangle)
     */
    private static int solve(Point p1, Point p2, Point p3) {
        // Case 1: All three points are identical
        if (p1.equals(p2) && p2.equals(p3)) {
            return 1;
        }

        // Case 2: Exactly two points are identical
        // According to problem constraints, if two points are identical, 
        // it takes 2 lines to "connect" the three points (one line for the pair, one for the third).
        if (p1.equals(p2) || p2.equals(p3) || p1.equals(p3)) {
            return 2;
        }

        // Case 3: The three distinct points are collinear
        if (GeometryUtils.isCollinear(p1, p2, p3)) {
            return 1;
        }

        // Case 4: The points form a triangle
        return 3;
    }

    /**
     * Represents a 2D coordinate.
     */
    static class Point {
        final int x, y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Point)) return false;
            Point point = (Point) o;
            return x == point.x && y == point.y;
        }

        @Override
        public int hashCode() {
            return Objects.hash(x, y);
        }
    }

    /**
     * Geometric utility methods.
     */
    static class GeometryUtils {
        /**
         * Checks if three points are collinear using the cross product.
         * (y2 - y1) * (x3 - x2) == (y3 - y2) * (x2 - x1)
         * Using long to prevent integer overflow during multiplication.
         */
        public static boolean isCollinear(Point p1, Point p2, Point p3) {
            long val = (long) (p2.y - p1.y) * (p3.x - p2.x) -
                       (long) (p3.y - p2.y) * (p2.x - p1.x);
            return val == 0;
        }
    }

    /**
     * Fast I/O implementation for efficient reading.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

/**
 * Represents a point in a 2D coordinate system.
 */
class Point {
    final int x;
    final int y;

    Point(int x, int y) {
        this.x = x;
        this.y = y;
    }
}

/**
 * Provides logic to solve the minimum axis-aligned segments problem.
 */
class PointSolver {

    /**
     * Calculates the minimum number of axis-aligned segments needed to connect three points.
     * 
     * @param p1 First point
     * @param p2 Second point
     * @param p3 Third point
     * @return 1, 2, or 3 segments.
     */
    public static int solve(Point p1, Point p2, Point p3) {
        if (isCollinearAxisAligned(p1, p2, p3)) {
            return 1;
        }
        if (canConnectWithTwoSegments(p1, p2, p3)) {
            return 2;
        }
        return 3;
    }

    /**
     * Checks if all three points lie on a single horizontal or vertical line.
     */
    private static boolean isCollinearAxisAligned(Point p1, Point p2, Point p3) {
        boolean allXEqual = (p1.x == p2.x && p2.x == p3.x);
        boolean allYEqual = (p1.y == p2.y && p2.y == p3.y);
        return allXEqual || allYEqual;
    }

    /**
     * Checks if the points can be connected using exactly two axis-aligned segments.
     * This happens if two points share an axis and the third point can be 
     * reached by extending that axis or by forming an L-shape.
     */
    private static boolean canConnectWithTwoSegments(Point p1, Point p2, Point p3) {
        return checkPair(p1, p2, p3) || 
               checkPair(p1, p3, p2) || 
               checkPair(p2, p3, p1);
    }

    /**
     * Helper to check if a pair of points forms an axis-aligned line that can 
     * accommodate the third point within two segments.
     */
    private static boolean checkPair(Point a, Point b, Point other) {
        if (a.x == b.x) {
            // Vertical line: segment is valid if 'other' is not strictly between a and b on the Y axis
            return other.y <= Math.min(a.y, b.y) || other.y >= Math.max(a.y, b.y);
        }
        if (a.y == b.y) {
            // Horizontal line: segment is valid if 'other' is not strictly between a and b on the X axis
            return other.x <= Math.min(a.x, b.x) || other.x >= Math.max(a.x, b.x);
        }
        return false;
    }
}

