/**
 * Analyzes the geometric configuration of sets of three points.
 * 
 * Results:
 * 1 - All points lie on the same vertical or horizontal line.
 * 2 - One point is an extreme in one dimension while the other two share a coordinate in the other.
 * 3 - Otherwise.
 */
public class PointGeometryAnalyzer {

    private static final int NUM_POINTS = 3;

    /**
     * Represents a coordinate point in 2D space.
     */
    private static class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        while (scanner.hasNextInt()) {
            List<Point> points = readPoints(scanner);

            if (points.size() == NUM_POINTS) {
                int result = determineConfiguration(points);
                System.out.println(result);
            }
        }
        scanner.close();
    }

    /**
     * Reads exactly NUM_POINTS from the scanner.
     */
    private static List<Point> readPoints(Scanner scanner) {
        List<Point> points = new ArrayList<>();
        for (int i = 0; i < NUM_POINTS; i++) {
            if (scanner.hasNextInt()) {
                int x = scanner.nextInt();
                if (scanner.hasNextInt()) {
                    int y = scanner.nextInt();
                    points.add(new Point(x, y));
                }
            }
        }
        return points;
    }

    /**
     * Determines the geometric result code for the given points.
     */
    private static int determineConfiguration(List<Point> points) {
        if (isCollinearHorizontalOrVertical(points)) {
            return 1;
        }
        if (hasSpecialAlignment(points)) {
            return 2;
        }
        return 3;
    }

    /**
     * Checks if all points share the same X or same Y coordinate.
     */
    private static boolean isCollinearHorizontalOrVertical(List<Point> points) {
        Point p1 = points.get(0);
        Point p2 = points.get(1);
        Point p3 = points.get(2);

        boolean allXSame = (p1.x == p2.x && p2.x == p3.x);
        boolean allYSame = (p1.y == p2.y && p2.y == p3.y);

        return allXSame || allYSame;
    }

    /**
     * Checks if any permutation of the points satisfies the special alignment condition.
     */
    private static boolean hasSpecialAlignment(List<Point> points) {
        // All permutations of indices {0, 1, 2} to ensure every point is tested as the "extreme"
        int[][] permutations = {
            {0, 1, 2}, {0, 2, 1}, {1, 0, 2},
            {1, 2, 0}, {2, 0, 1}, {2, 1, 0}
        };

        for (int[] p : permutations) {
            if (isAlignmentConditionMet(points.get(p[0]), points.get(p[1]), points.get(p[2]))) {
                return true;
            }
        }
        return false;
    }

    /**
     * Evaluates if the first point (p1) is an extreme value in one dimension 
     * while the other two (p2, p3) share a coordinate in the other dimension.
     */
    private static boolean isAlignmentConditionMet(Point p1, Point p2, Point p3) {
        // Case A: p2 and p3 share a Y coordinate; check if p1 is the min or max X
        if (p2.y == p3.y) {
            if (p1.x >= p2.x && p1.x >= p3.x) return true;
            if (p1.x <= p2.x && p1.x <= p3.x) return true;
        }

        // Case B: p2 and p3 share an X coordinate; check if p1 is the min or max Y
        if (p2.x == p3.x) {
            if (p1.y >= p2.y && p1.y >= p3.y) return true;
            if (p1.y <= p2.y && p1.y <= p3.y) return true;
        }

        return false;
    }
}

