/**
 * Represents an immutable 2D coordinate.
 */
record Point(int x, int y) {}

/**
 * Defines the possible geometric classifications for a set of points.
 */
enum ClassificationResult {
    ALL_ALIGNED(1),
    CORNER_SHAPE(2),
    OTHER(3);

    private final int code;

    ClassificationResult(int code) {
        this.code = code;
    }

    public int getCode() {
        return code;
    }
}

/**
 * Provides logic to analyze the geometric arrangement of points.
 */
class PointClassifier {

    /**
     * Determines the classification of the provided points.
     * 
     * @param points A list of points to analyze.
     * @return The resulting ClassificationResult.
     */
    public ClassificationResult classify(List<Point> points) {
        if (isCollinearOnAxis(points)) {
            return ClassificationResult.ALL_ALIGNED;
        }
        if (isAxisAlignedCorner(points)) {
            return ClassificationResult.CORNER_SHAPE;
        }
        return ClassificationResult.OTHER;
    }

    /**
     * Checks if all points lie on the same vertical or horizontal line.
     */
    private boolean isCollinearOnAxis(List<Point> points) {
        boolean allXSame = points.stream().map(Point::x).distinct().count() == 1;
        boolean allYSame = points.stream().map(Point::y).distinct().count() == 1;
        return allXSame || allYSame;
    }

    /**
     * Checks if the points form a right-angle 'L' shape with sides parallel to the axes.
     * This occurs if two points share an axis and the third point's coordinate 
     * on the opposite axis is not strictly between them.
     */
    private boolean isAxisAlignedCorner(List<Point> points) {
        // Iterate through all permutations of pairs (i, j) and the remaining point (k)
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                if (i == j) continue;

                // In a set of 3, the remaining index k is 3 - i - j
                int k = 3 - i - j;

                Point pi = points.get(i);
                Point pj = points.get(j);
                Point pk = points.get(k);

                // Check vertical alignment
                if (pi.x() == pj.x()) {
                    if (isOutsideRange(pk.y(), pi.y(), pj.y())) {
                        return true;
                    }
                }

                // Check horizontal alignment
                if (pi.y() == pj.y()) {
                    if (isOutsideRange(pk.x(), pi.x(), pj.x())) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Helper to check if the target value is outside the range defined by val1 and val2.
     */
    private boolean isOutsideRange(int target, int val1, int val2) {
        return target >= Math.max(val1, val2) || target <= Math.min(val1, val2);
    }
}

import java.util.*;
import java.io.*;

/**
 * A solver that determines the minimum number of axis-aligned lines 
 * (horizontal or vertical) required to cover three given points.
 */
public class AxisAlignedLineSolver {

    /**
     * Represents a point in a 2D coordinate system.
     */
    public record Point(int x, int y) {}

    /**
     * Contains the business logic for geometric calculations.
     */
    public static class GeometrySolver {

        /**
         * Calculates the minimum number of axis-aligned lines to cover three points.
         * 
         * @param p1 First point
         * @param p2 Second point
         * @param p3 Third point
         * @return 1, 2, or 3 lines required.
         */
        public int countMinimumLines(Point p1, Point p2, Point p3) {
            if (isCollinearAxisAligned(p1, p2, p3)) {
                return 1;
            }
            if (hasSharedAxis(p1, p2, p3)) {
                return 2;
            }
            return 3;
        }

        /**
         * Checks if all three points lie on a single horizontal or vertical line.
         */
        private boolean isCollinearAxisAligned(Point p1, Point p2, Point p3) {
            return (p1.x() == p2.x() && p2.x() == p3.x()) || 
                   (p1.y() == p2.y() && p2.y() == p3.y());
        }

        /**
         * Checks if at least two points share an x or y coordinate, 
         * which allows them to be covered by 2 axis-aligned lines.
         */
        private boolean hasSharedAxis(Point p1, Point p2, Point p3) {
            return (p1.x() == p2.x() || p1.x() == p3.x() || p2.x() == p3.x() ||
                    p1.y() == p2.y() || p1.y() == p3.y() || p2.y() == p3.y());
        }
    }

    /**
     * Entry point of the application.
     */
    public static void main(String[] args) {
        try (FastReader reader = new FastReader(System.in);
             PrintWriter writer = new PrintWriter(System.out)) {

            // Reading coordinates for three points
            Point p1 = new Point(reader.nextInt(), reader.nextInt());
            Point p2 = new Point(reader.nextInt(), reader.nextInt());
