import java.io.*;
import java.util.*;

/**
 * Represents a 2D coordinate point.
 */
class Point {
    final int x;
    final int y;

    Point(int x, int y) {
        this.x = x;
        this.y = y;
    }
}

/**
 * Logic for solving the coordinate arrangement problem.
 */
class GeometrySolver {

    /**
     * Solves the problem based on the arrangement of three points.
     * 
     * @param points An array of exactly 3 Point objects.
     * @return 1 if points are collinear on an axis-aligned line, 
     *         2 if they form an L-shape or specific partial alignment,
     *         3 otherwise.
     */
    public int solve(Point[] points) {
        int xMatches = countAxisMatches(points, true);
        int yMatches = countAxisMatches(points, false);

        // If all three points share the same X or same Y, they are on a single axis-aligned line.
        if (xMatches == 3 || yMatches == 3) {
            return 1;
        }

        // If exactly one pair shares an X or Y coordinate.
        if (xMatches == 1 || yMatches == 1) {
            if (isPartialAlignment(points)) {
                return 2;
            }
        }

        return 3;
    }

    private int countAxisMatches(Point[] points, boolean checkX) {
        int matches = 0;
        for (int i = 0; i < points.length; i++) {
            for (int j = i + 1; j < points.length; j++) {
                if (checkX) {
                    if (points[i].x == points[j].x) matches++;
                } else {
                    if (points[i].y == points[j].y) matches++;
                }
            }
        }
        return matches;
    }

    /**
     * Checks if the points satisfy the specific geometric condition for result '2'.
     * This checks if a pair of points shares a coordinate and the third point 
     * is not "between" them on the perpendicular axis.
     */
    private boolean isPartialAlignment(Point[] points) {
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                if (i == j) continue;
                for (int k = 0; k < 3; k++) {
                    if (k == i || k == j) continue;

                    // Case 1: i and j share the same Y-coordinate
                    if (points[i].y == points[j].y) {
                        // Ensure consistent direction for the comparison
                        if (points[i].x < points[j].x) {
                            if (points[k].x <= points[i].x || points[k].x >= points[j].x) {
                                return true;
                            }
                        }
                    }

                    // Case 2: i and j share the same X-coordinate
                    if (points[i].x == points[j].x) {
                        // Ensure consistent direction for the comparison
                        if (points[i].y <= points[j].y) {
                            if (points[k].y <= points[i].y || points[k].y >= points[j].y) {
                                return true;
                            }
                        }
                    }
                }
            }
        }
        return false;
    }
}

