/**
 * The Arena class calculates the relationship type between three points in a 2D plane.
 */
public class Arena {

    private static final int TYPE_COLLINEAR = 1;
    private static final int TYPE_RIGHT_ANGLE_EXTENDED = 2;
    private static final int TYPE_GENERAL = 3;

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();

        try (PrintWriter output = new PrintWriter(new BufferedOutputStream(System.out))) {
            Point p1 = new Point(scanner.nextLong(), scanner.nextLong());
            Point p2 = new Point(scanner.nextLong(), scanner.nextLong());
            Point p3 = new Point(scanner.nextLong(), scanner.nextLong());

            int result = calculateArenaType(p1, p2, p3);
            output.println(result);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * Determines the relationship type between three points.
     * 
     * @param p1 First point
     * @param p2 Second point
     * @param p3 Third point
     * @return 1 if collinear (horizontal/vertical), 
     *         2 if they form a specific right-angle/boundary pattern, 
     *         3 otherwise.
     */
    private static int calculateArenaType(Point p1, Point p2, Point p3) {
        if (isCollinear(p1, p2, p3)) {
            return TYPE_COLLINEAR;
        }

        if (isTypeTwo(p1, p2, p3)) {
            return TYPE_RIGHT_ANGLE_EXTENDED;
        }

        return TYPE_GENERAL;
    }

    private static boolean isCollinear(Point p1, Point p2, Point p3) {
        boolean allSameX = (p1.x == p2.x && p2.x == p3.x);
        boolean allSameY = (p1.y == p2.y && p2.y == p3.y);
        return allSameX || allSameY;
    }

    private static boolean isTypeTwo(Point p1, Point p2, Point p3) {
        // Check vertical alignment patterns
        if (p1.x == p2.x && isOutsideRange(p3.y, p1.y, p2.y)) return true;
        if (p1.x == p3.x && isOutsideRange(p2.y, p1.y, p3.y)) return true;
        if (p2.x == p3.x && isOutsideRange(p1.y, p2.y, p3.y)) return true;

        // Check horizontal alignment patterns
        if (p1.y == p2.y && isOutsideRange(p3.x, p1.x, p2.x)) return true;
        if (p1.y == p3.y && isOutsideRange(p2.x, p1.x, p3.x)) return true;
        if (p2.y == p3.y && isOutsideRange(p1.x, p2.x, p3.x)) return true;

        return false;
    }

    /**
     * Checks if the target value is outside (or on the boundary of) the range [min, max].
     */
    private static boolean isOutsideRange(long target, long val1, long val2) {
        long min = Math.min(val1, val2);
        long max = Math.max(val1, val2);
        return target <= min || target >= max;
    }

    /**
     * Immutable representation of a 2D point.
     */
    private static final class Point {
        private final long x;
        private final long y;

        public Point(long x, long y) {
            this.x = x;
            this.y = y;
        }

        public long getX() { return x; }
        public long getY() { return y; }
    }

    /**
     * Fast I/O utility for reading large inputs.
     */
    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner() {
            this.reader = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
