import java.io.*;
import java.util.*;

/**
 * Problem: Calculate the minimum number of axis-aligned segments required 
 * to connect three given points.
 */
public class PointConnectivity {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            Point p1 = reader.nextPoint();
            Point p2 = reader.nextPoint();
            Point p3 = reader.nextPoint();

            int result = GeometrySolver.calculateMinSegments(p1, p2, p3);
            out.println(result);
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Represents a 2D point with integer coordinates.
     */
    public record Point(int x, int y) {}

    /**
     * Logic for determining the minimum segments needed to connect three points.
     */
    public static class GeometrySolver {

        /**
         * Returns 1 if all points are on a single axis-aligned line,
         * 2 if they can be connected with two segments,
         * and 3 otherwise.
         */
        public static int calculateMinSegments(Point p1, Point p2, Point p3) {
            // Case 1: All three points are collinear and axis-aligned
            if (isCollinearAxisAligned(p1, p2, p3)) {
                return 1;
            }

            // Case 2: Check if any pair forms an axis-aligned line segment 
            // such that the third point can be part of a 2-segment path.
            if (canConnectWithTwoSegments(p1, p2, p3) ||
                canConnectWithTwoSegments(p1, p3, p2) ||
                canConnectWithTwoSegments(p2, p3, p1)) {
                return 2;
            }

            // Case 3: Otherwise, 3 segments are required.
            return 3;
        }

        private static boolean isCollinearAxisAligned(Point p1, Point p2, Point p3) {
            boolean allXSame = (p1.x() == p2.x() && p2.x() == p3.x());
            boolean allYSame = (p1.y() == p2.y() && p2.y() == p3.y());
            return allXSame || allYSame;
        }

        private static boolean canConnectWithTwoSegments(Point a, Point b, Point c) {
            // If A and B are on a vertical line
            if (a.x() == b.x()) {
                int minY = Math.min(a.y(), b.y());
                int maxY = Math.max(a.y(), b.y());
                // If C's y-coordinate is outside the A-B range, 
                // we can connect them using 2 segments (C -> corner -> A/B).
                return c.y() >= maxY || c.y() <= minY;
            }
            // If A and B are on a horizontal line
            if (a.y() == b.y()) {
                int minX = Math.min(a.x(), b.x());
                int maxX = Math.max(a.x(), b.x());
                return c.x() >= maxX || c.x() <= minX;
            }
            return false;
        }
    }

    /**
     * High-performance input reader.
     */
    public static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public Point nextPoint() throws IOException {
            return new Point(nextInt(), nextInt());
        }
    }

    /**
     * A standard Lazy Segment Tree implementation for Range Add and Range Sum queries.
     */
    public static class LazySegmentTree {
        private final int n;
        private final long[] tree;
        private final long[] lazy;

        public LazySegmentTree(int n) {
            this.n = n;
            this.tree = new long[4 * n];
            this.lazy = new long[4 * n];
        }

        public void updateRange(int l, int r, int val) {
            update(1, 0, n - 1, l, r, val);
        }

        private void update(int node, int start, int end, int l, int r, int val) {
            push(node, start, end);
            if (start > end || start > r || end < l) return;

            if (start >= l && end <= r) {
                lazy[node] += val;
                push(node, start, end);
                return;
            }

            int mid = (start + end) / 2;
            update(2 * node, start, mid, l, r, val);
            update(2 * node + 1, mid + 1, end, l, r, val);
            tree[node] = tree[2 * node] + tree[2 * node + 1];
        }

        public long queryRange(int l, int r) {
            return query(1, 0, n - 1, l, r);
        }

        private long query(int node, int start, int end, int l, int r) {
            push(node, start, end);
            if (start > end || start > r || end < l) return 0;
            if (start >= l && end <= r) return tree[node];

            int mid = (start + end) / 2;
            return query(2 * node, start, mid, l, r) + query(2 * node + 1, mid + 1, end, l, r);
        }

        private void push(int node, int start, int end) {
            if (lazy[node] != 0) {
                tree[node] += (long) (end - start + 1) * lazy[node];
                if (start != end) {
                    lazy[2 * node] += lazy[node];
                    lazy[2 * node + 1] += lazy[node];
                }
                lazy[node] = 0;
            }
        }
    }
}

