/**
 * ProblemD Refactored
 * 
 * This program determines the alignment of three points in a 2D plane.
 * Result 1: All points are collinear on a horizontal or vertical line.
 * Result 2: Two points form a line, and the third is outside the segment.
 * Result 3: Two points form a line and the third is between them, or no two points share an axis.
 */
public class ProblemD {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        Solution solver = new Solution();
        solver.solve(reader, writer);

        writer.flush();
        writer.close();
    }

    /**
     * Represents a point in 2D space.
     */
    static class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    /**
     * Contains the core logic for solving the coordinate problem.
     */
    static class Solution {

        public void solve(FastReader in, PrintWriter out) {
            Point[] points = new Point[3];
            for (int i = 0; i < 3; i++) {
                points[i] = new Point(in.nextInt(), in.nextInt());
            }

            out.println(calculateAlignment(points));
        }

        private int calculateAlignment(Point[] p) {
            // Case 1: All points are collinear on a single horizontal or vertical line
            if (allPointsHaveSameX(p) || allPointsHaveSameY(p)) {
                return 1;
            }

            // Check all pairs of points
            for (int i = 0; i < 3; i++) {
                for (int j = i + 1; j < 3; j++) {
                    // Since there are only 3 points (0, 1, 2), 
                    // the remaining index k is always 3 - i - j.
                    int k = 3 - i - j;

                    if (isHorizontal(p[i], p[j])) {
                        return isStrictlyBetween(p[k].x, p[i].x, p[j].x) ? 3 : 2;
                    }

                    if (isVertical(p[i], p[j])) {
                        return isStrictlyBetween(p[k].y, p[i].y, p[j].y) ? 3 : 2;
                    }
                }
            }

            // Case 3: No two points share an X or Y coordinate
            return 3;
        }

        private boolean allPointsHaveSameX(Point[] points) {
            return points[0].x == points[1].x && points[1].x == points[2].x;
        }

        private boolean allPointsHaveSameY(Point[] points) {
            return points[0].y == points[1].y && points[1].y == points[2].y;
        }

        private boolean isHorizontal(Point p1, Point p2) {
            return p1.y == p2.y;
        }

        private boolean isVertical(Point p1, Point p2) {
            return p1.x == p2.x;
        }

        private boolean isStrictlyBetween(int target, int a, int b) {
            return target > Math.min(a, b) && target < Math.max(a, b);
        }
    }

    /**
     * Efficient input reader for competitive programming style input.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(java.io.InputStream inputStream) {
            br = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

