/**
 * TaskD handles geometric relationship analysis for three points.
 * The relationship is classified into three levels:
 * 1: All points are collinear on a single horizontal or vertical line.
 * 2: Two points form a segment on an axis, and the third point is vertically/horizontally outside that segment.
 * 3: All other cases.
 */
public class TaskD {

    public static void main(String[] args) {
        new TaskD().run();
    }

    /**
     * Orchestrates the input reading and output printing.
     */
    public void run() {
        FastReader reader = new FastReader(System.in);
        try {
            Point p1 = reader.nextPoint();
            Point p2 = reader.nextPoint();
            Point p3 = reader.nextPoint();

            int result = calculateRelationship(p1, p2, p3);
            System.out.println(result);
        } catch (Exception e) {
            // In a production environment, use a logger here.
        }
    }

    /**
     * Calculates the relationship level between three points.
     * Preserves the precedence logic of the original implementation.
     */
    private int calculateRelationship(Point p1, Point p2, Point p3) {
        if (isCollinear(p1, p2, p3)) {
            return 1;
        }

        // The original code used an 'else if' chain. This means if a coordinate 
        // match is found (e.g., p1.x == p2.x), the result is determined 
        // solely by that match, and no other pairs are checked.

        // Vertical alignment checks
        if (p1.x == p2.x) return isOutside(p3.y, p1.y, p2.y) ? 2 : 3;
        if (p2.x == p3.x) return isOutside(p1.y, p2.y, p3.y) ? 2 : 3;
        if (p1.x == p3.x) return isOutside(p2.y, p1.y, p3.y) ? 2 : 3;

        // Horizontal alignment checks
        if (p1.y == p2.y) return isOutside(p3.x, p1.x, p2.x) ? 2 : 3;
        if (p2.y == p3.y) return isOutside(p1.x, p2.x, p3.x) ? 2 : 3;
        if (p1.y == p3.y) return isOutside(p2.x, p1.x, p3.x) ? 2 : 3;

        return 3;
    }

    private boolean isCollinear(Point p1, Point p2, Point p3) {
        boolean allXSame = (p1.x == p2.x && p2.x == p3.x);
        boolean allYSame = (p1.y == p2.y && p2.y == p3.y);
        return allXSame || allYSame;
    }

    private boolean isOutside(int target, int segmentStart, int segmentEnd) {
        return target < Math.min(segmentStart, segmentEnd) || 
               target > Math.max(segmentStart, segmentEnd);
    }

    /**
     * Represents a 2D coordinate.
     */
    private static class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
