import java.util.Scanner;

/**
 * Represents a 2D point in a Cartesian coordinate system.
 */
record Point(int x, int y) {}

/**
 * Service class containing geometric logic to determine the number of lines
 * formed by a set of points.
 */
class GeometryCalculator {

    /**
     * Calculates the number of lines formed by three points.
     * 
     * @param p1 The first point.
     * @param p2 The second point.
     * @param p3 The third point.
     * @return 1 if collinear (axial), 2 if they satisfy specific axial constraints, 
     *         or 3 if they form a triangle.
     */
    public int countLines(Point p1, Point p2, Point p3) {
        if (isAxiallyCollinear(p1, p2, p3)) {
            return 1;
        }

        if (isSpecialAxialCase(p1, p2, p3)) {
            return 2;
        }

        return 3;
    }

    private boolean isAxiallyCollinear(Point p1, Point p2, Point p3) {
        boolean allXSame = (p1.x() == p2.x() && p2.x() == p3.x());
        boolean allYSame = (p1.y() == p2.y() && p2.y() == p3.y());
        return allXSame || allYSame;
    }

    private boolean isSpecialAxialCase(Point p1, Point p2, Point p3) {
        // Check all permutations for vertical special cases
        if (hasVerticalSpecialCase(p1, p2, p3) || 
            hasVerticalSpecialCase(p1, p3, p2) || 
            hasVerticalSpecialCase(p2, p3, p1)) {
            return true;
        }

        // Check all permutations for horizontal special cases
        return hasHorizontalSpecialCase(p1, p2, p3) || 
               hasHorizontalSpecialCase(p1, p3, p2) || 
               hasHorizontalSpecialCase(p2, p3, p1);
    }

    private boolean hasVerticalSpecialCase(Point a, Point b, Point c) {
        if (a.x() == b.x()) {
            int minY = Math.min(a.y(), b.y());
            int maxY = Math.max(a.y(), b.y());
            // Returns true if the third point's Y is outside the segment formed by a and b
            return c.y() >= maxY || c.y() <= minY;
        }
        return false;
    }

    private boolean hasHorizontalSpecialCase(Point a, Point b, Point c) {
        if (a.y() == b.y()) {
            int minX = Math.min(a.x(), b.x());
            int maxX = Math.max(a.x(), b.x());
            // Returns true if the third point's X is outside the segment formed by a and b
            return c.x() >= maxX || c.x() <= minX;
        }
        return false;
    }
}

