import java.util.Scanner;

/**
 * Analyzes the alignment of a triangle's sides relative to the X and Y axes.
 */
public class TriangleAlignment {

    /**
     * Represents a 2D coordinate point.
     */
    public static class Point {
        private final long x;
        private final long y;

        public Point(long x, long y) {
            this.x = x;
            this.y = y;
        }

        public long getX() { return x; }
        public long getY() { return y; }
    }

    /**
     * Represents a line segment between two points.
     */
    public static class Line {
        private final Point p1;
        private final Point p2;

        public Line(Point p1, Point p2) {
            this.p1 = p1;
            this.p2 = p2;
        }

        public boolean isVertical() {
            return p1.getX() == p2.getX();
        }

        public boolean isHorizontal() {
            return p1.getY() == p2.getY();
        }

        public long getMinX() { return Math.min(p1.getX(), p2.getX()); }
        public long getMaxX() { return Math.max(p1.getX(), p2.getX()); }
        public long getMinY() { return Math.min(p1.getY(), p2.getY()); }
        public long getMaxY() { return Math.max(p1.getY(), p2.getY()); }
    }

    /**
     * Logic for determining the axis-alignment status of the triangle.
     */
    public static class TriangleSolver {

        public static int calculateAlignmentScore(Point p1, Point p2, Point p3) {
            Line ab = new Line(p1, p2);
            Line ac = new Line(p1, p3);
            Line bc = new Line(p2, p3);

            // Case 1: Two sides are parallel to the same axis
            if ((ab.isVertical() && ac.isVertical()) || (ab.isHorizontal() && ac.isHorizontal())) {
                return 1;
            }

            Line[] lines = {ab, ac, bc};
            Point[] otherPoints = {p3, p2, p1}; // The point not included in the current line

            // Case 2: One side is axis-aligned and satisfies specific boundary conditions
            for (int i = 0; i < 3; i++) {
                Line side = lines[i];
                Point externalPoint = otherPoints[i];

                if (side.isVertical()) {
                    if (isPointYOutsideRange(externalPoint, side)) {
                        return 2;
                    }
                    // The original logic breaks the loop if a side is vertical
                    break; 
                }

                if (side.isHorizontal()) {
                    if (isPointXOutsideRange(externalPoint, side)) {
                        return 2;
                    }
                    // The original logic breaks the loop if a side is horizontal
                    break;
                }
            }

            // Case 3: Default state
            return 3;
        }

        private static boolean isPointYOutsideRange(Point p, Line line) {
            return p.getY() <= line.getMinY() || p.getY() >= line.getMaxY();
        }

        private static boolean isPointXOutsideRange(Point p, Line line) {
            return p.getX() <= line.getMinX() || p.getX() >= line.getMaxX();
        }
    }

    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            if (!sc.hasNextLong()) return;

            Point p1 = new Point(sc.nextLong(), sc.nextLong());
            Point p2 = new Point(sc.nextLong(), sc.nextLong());
            Point p3 = new Point(sc.nextLong(), sc.nextLong());

            int result = TriangleSolver.calculateAlignmentScore(p1, p2, p3);
            System.out.println(result);
        } catch (Exception e) {
            System.err.println("Error processing input: " + e.getMessage());
        }
    }
}

