/**
 * Contains the business logic for calculating the minimum line coverage.
 */
class LinePathCalculator {

    /**
     * Calculates the minimum number of axis-aligned lines needed to cover the points.
     * Returns 1 if all points are on one axis-aligned line, 
     * 2 if they meet specific two-line configurations, 
     * and 3 otherwise.
     */
    public int calculateMinLines(LinePathSolver.Point p1, LinePathSolver.Point p2, LinePathSolver.Point p3) {
        if (isAllCollinearAxisAligned(p1, p2, p3)) {
            return 1;
        }

        if (isTwoLineConfiguration(p1, p2, p3)) {
            return 2;
        }

        return 3;
    }

    /**
     * Checks if all three points share the same X or Y coordinate.
     */
    private boolean isAllCollinearAxisAligned(LinePathSolver.Point p1, LinePathSolver.Point p2, LinePathSolver.Point p3) {
        boolean allXSame = (p1.x() == p2.x() && p2.x() == p3.x());
        boolean allYSame = (p1.y() == p2.y() && p2.y() == p3.y());
        return allXSame || allYSame;
    }

    /**
     * Checks for specific configurations where two points share an axis 
     * and the third point is positioned outside their range.
     */
    private boolean isTwoLineConfiguration(LinePathSolver.Point p1, LinePathSolver.Point p2, LinePathSolver.Point p3) {
        return (p1.x() == p2.x() && isOutsideRange(p1.y(), p2.y(), p3.y())) ||
               (p1.y() == p2.y() && isOutsideRange(p1.x(), p2.x(), p3.x())) ||
               (p1.x() == p3.x() && isOutsideRange(p1.y(), p3.y(), p2.y())) ||
               (p1.y() == p3.y() && isOutsideRange(p1.x(), p3.x(), p2.x())) ||
               (p3.x() == p2.x() && isOutsideRange(p3.y(), p2.y(), p1.y())) ||
               (p3.y() == p2.y() && isOutsideRange(p3.x(), p2.x(), p1.x()));
    }

    /**
     * Helper to determine if the target value is outside the range [min(a, b), max(a, b)].
     * Note: The original logic returned true if the value was exactly equal to a or b.
     */
    private boolean isOutsideRange(long a, long b, long target) {
        long min = Math.min(a, b);
        long max = Math.max(a, b);
        // Returns true if target is not strictly between a and b
        return target <= min || target >= max;
    }
}

