/**
 * Contains the business logic to solve the specific coordinate problem.
 */
class CoordinateProblemSolver {

    /**
     * Reads input and determines the result based on coordinate patterns.
     */
    public void solve(FastReader in, PrintWriter out) throws IOException {
        Point[] points = new Point[3];
        for (int i = 0; i < 3; i++) {
            points[i] = new Point(in.nextInt(), in.nextInt());
        }

        out.println(calculateResult(points));
    }

    /**
     * The core logic to determine the result (1, 2, or 3) based on point configuration.
     */
    private int calculateResult(Point[] points) {
        // Case 1: All points share the same X or same Y coordinate.
        if (allPointsSameInDimension(points, 0) || allPointsSameInDimension(points, 1)) {
            return 1;
        }

        // Case 2: All X coordinates are distinct AND all Y coordinates are distinct.
        if (areAllCoordinatesDistinct(points, 0) && areAllCoordinatesDistinct(points, 1)) {
            return 3;
        }

        // Case 3: Check if two points share a coordinate and the third point's 
        // other coordinate is not strictly between them.
        if (canFormTwoPattern(points)) {
            return 2;
        }

        // Default Case
        return 3;
    }

    private boolean allPointsSameInDimension(Point[] points, int dimension) {
        int firstVal = points[0].getCoordinate(dimension);
        return points[1].getCoordinate(dimension) == firstVal && 
               points[2].getCoordinate(dimension) == firstVal;
    }

    private boolean areAllCoordinatesDistinct(Point[] points, int dimension) {
        for (int i = 0; i < 3; i++) {
            for (int j = i + 1; j < 3; j++) {
                if (points[i].getCoordinate(dimension) == points[j].getCoordinate(dimension)) {
                    return false;
                }
            }
        }
        return true;
    }

    private boolean canFormTwoPattern(Point[] points) {
        for (int dim = 0; dim < 2; dim++) {
            for (int i = 0; i < 3; i++) {
                for (int j = i + 1; j < 3; j++) {
                    // If two points share a coordinate in the current dimension
                    if (points[i].getCoordinate(dim) == points[j].getCoordinate(dim)) {
                        int k = 3 - i - j; // The index of the remaining third point
                        int otherDim = 1 - dim;

                        int valI = points[i].getCoordinate(otherDim);
                        int valJ = points[j].getCoordinate(otherDim);
                        int valK = points[k].getCoordinate(otherDim);

                        // Check if the third point's coordinate is outside the range of the other two
                        if (valK <= Math.min(valI, valJ) || valK >= Math.max(valI, valJ)) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }
}

/**
 * Optimized reader for fast input parsing.
 */
class FastReader implements AutoCloseable {
    private final InputStream stream;
    private final byte[] buffer = new byte[8192];
    private int currentChar;
    private int numChars;

    public FastReader(InputStream stream) {
        this.stream = stream;
    }

    private int read() throws IOException {
        if (numChars == -1) {
            throw new InputMismatchException();
        }
        if (currentChar >= numChars) {
            currentChar = 0;
            numChars = stream.read(buffer);
            if (numChars <= 0) {
                return -1;
            }
        }
        return buffer[currentChar++];
    }

    /**
     * Reads the next integer. Skips whitespace and handles commas.
     */
    public int nextInt() throws IOException {
        int c = read();
        while (c != -1 && isWhitespace(c)) {
            c = read();
        }
        if (c == -1) throw new InputMismatchException();

        int sign = 1;
        if (c == '-') {
            sign = -1;
            c = read();
        }

        int result = 0;
        do {
            if (c == ',') {
                c = read();
                continue;
            }
            if (c < '0' || c > '9') {
                throw new InputMismatchException();
            }
            result = result * 10 + (c - '0');
            c = read();
        } while (c != -1 && !isWhitespace(c));

        return result * sign;
    }

    private boolean isWhitespace(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    @Override
    public void close() throws IOException {
        stream.close();
    }
}

