/**
 * Contains the logic to determine the complexity of a set of points.
 */
class PointComplexitySolver {

    private static final int COMPLEXITY_LINEAR = 1;
    private static final int COMPLEXITY_CORNER = 2;
    private static final int COMPLEXITY_GENERAL = 3;

    /**
     * Calculates the minimum complexity of the given points.
     * 
     * @param points An array of 3 points.
     * @return 1 if points are collinear on an axis, 
     *         2 if a pair shares an axis and the third is outside their range,
     *         3 otherwise.
     */
    public int calculateMinimumComplexity(Point[] points) {
        if (isCollinearOnAxis(points)) {
            return COMPLEXITY_LINEAR;
        }

        int minComplexity = COMPLEXITY_GENERAL;

        // Check all permutations of points to find if any pair meets the 'corner' condition
        for (int i = 0; i < points.length; i++) {
            for (int j = 0; j < points.length; j++) {
                if (i == j) continue;

                for (int k = 0; k < points.length; k++) {
                    if (k == i || k == j) continue;

                    // Check both X and Y dimensions for the shared-coordinate condition
                    int resultX = evaluateDimension(points[i], points[j], points[k], Dimension.X);
                    int resultY = evaluateDimension(points[i], points[j], points[k], Dimension.Y);

                    minComplexity = Math.min(minComplexity, Math.min(resultX, resultY));
                }
            }
        }

        return minComplexity;
    }

    private boolean isCollinearOnAxis(Point[] points) {
        boolean allXSame = true;
        boolean allYSame = true;

        for (int i = 1; i < points.length; i++) {
            if (points[i].x != points[0].x) allXSame = false;
            if (points[i].y != points[0].y) allYSame = false;
        }

        return allXSame || allYSame;
    }

    private int evaluateDimension(Point p1, Point p2, Point p3, Dimension dim) {
        if (dim == Dimension.X) {
            if (p1.x == p2.x) {
                int minY = Math.min(p1.y, p2.y);
                int maxY = Math.max(p1.y, p2.y);
                if (p3.y >= maxY || p3.y <= minY) {
                    return COMPLEXITY_CORNER;
                }
            }
        } else { // Dimension.Y
            if (p1.y == p2.y) {
                int minX = Math.min(p1.x, p2.x);
                int maxX = Math.max(p1.x, p2.x);
                if (p3.x >= maxX || p3.x <= minX) {
                    return COMPLEXITY_CORNER;
                }
            }
        }
        return COMPLEXITY_GENERAL;
    }

    private enum Dimension { X, Y }
}

