/**
 * Represents a 2D point with x and y coordinates.
 */
class Point {
    final long x;
    final long y;

    Point(long x, long y) {
        this.x = x;
        this.y = y;
    }
}

/**
 * Contains the logic to solve the point configuration problem.
 */
class PointConfigurationSolver {

    /**
     * Reads three points and determines the required number of rectangles.
     * 
     * @param in  The reader for input.
     * @param out The writer for output.
     */
    public void solve(FastReader in, PrintWriter out) {
        Point[] points = new Point[3];
        Set<Long> xCoords = new HashSet<>();
        Set<Long> yCoords = new HashSet<>();

        for (int i = 0; i < 3; i++) {
            long x = in.nextLong();
            long y = in.nextLong();
            points[i] = new Point(x, y);
            xCoords.add(x);
            yCoords.add(y);
        }

        // Case 1: All points are on a single axis-aligned line.
        // If all X are the same or all Y are the same, only 1 rectangle is needed.
        if (xCoords.size() == 1 || yCoords.size() == 1) {
            out.println(1);
            return;
        }

        // Case 2: Check if any point forms an axis-aligned "corner" or "middle" 
        // with the other two, allowing coverage by 2 rectangles.
        if (canBeCoveredByTwo(points)) {
            out.println(2);
        } else {
            // Case 3: Otherwise, 3 rectangles are required.
            out.println(3);
        }
    }

    /**
     * Checks if the points can be covered by 2 axis-aligned rectangles.
     */
    private boolean canBeCoveredByTwo(Point[] points) {
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                for (int k = 0; k < 3; k++) {
                    // Ensure we are checking three distinct points
                    if (i != j && j != k && i != k) {
                        if (isAxisAlignedConfiguration(points[i], points[j], points[k])) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Determines if the third point (p3) lies on an axis-aligned 
     * segment/path related to p1 and p2.
     */
    private boolean isAxisAlignedConfiguration(Point p1, Point p2, Point p3) {
        // Check horizontal alignment: p3.x is between p1.x and p2.x 
        // AND p3 shares a y-coordinate with either p1 or p2.
        boolean horizontal = isBetween(p1.x, p2.x, p3.x) && (p3.y == p1.y || p3.y == p2.y);

        // Check vertical alignment: p3.y is between p1.y and p2.y 
        // AND p3 shares an x-coordinate with either p1 or p2.
        boolean vertical = isBetween(p1.y, p2.y, p3.y) && (p3.x == p1.x || p3.x == p2.x);

        return horizontal || vertical;
    }

    private boolean isBetween(long a, long b, long target) {
        return target >= Math.min(a, b) && target <= Math.max(a, b);
    }
}

