/**
 * Represents a 2D point with integer coordinates.
 */
record Point(int x, int y) {}

/**
 * Logic engine for calculating geometric relationships between three points.
 */
class PointRelationshipCalculator {

    /**
     * Determines the arrangement value based on the coordinates of three points.
     * 
     * @param p1 The first point.
     * @param p2 The second point.
     * @param p3 The third point.
     * @return An integer representing the calculated geometric relationship.
     */
    public int calculateRelationship(Point p1, Point p2, Point p3) {
        if (isAllXEqual(p1, p2, p3) || isAllYEqual(p1, p2, p3)) {
            return 1;
        }

        if (hasAnyTwoXEqual(p1, p2, p3)) {
            return calculateVerticalAlignment(p1, p2, p3);
        }

        if (hasAnyTwoYEqual(p1, p2, p3)) {
            return calculateHorizontalAlignment(p1, p2, p3);
        }

        return 3;
    }

    private boolean isAllXEqual(Point p1, Point p2, Point p3) {
        return p1.x() == p2.x() && p2.x() == p3.x();
    }

    private boolean isAllYEqual(Point p1, Point p2, Point p3) {
        return p1.y() == p2.y() && p2.y() == p3.y();
    }

    private boolean hasAnyTwoXEqual(Point p1, Point p2, Point p3) {
        return p1.x() == p2.x() || p2.x() == p3.x() || p1.x() == p3.x();
    }

    private boolean hasAnyTwoYEqual(Point p1, Point p2, Point p3) {
        return p1.y() == p2.y() || p2.y() == p3.y() || p1.y() == p3.y();
    }

    /**
     * Handles cases where exactly two points share the same X coordinate.
     */
    private int calculateVerticalAlignment(Point p1, Point p2, Point p3) {
        if (p1.x() == p2.x()) {
            return isBetween(p3.y(), p2.y(), p1.y()) ? 3 : 2;
        } else if (p2.x() == p3.x()) {
            return isBetween(p1.y(), p2.y(), p3.y()) ? 3 : 2;
        } else { // p1.x == p3.x
            return isBetween(p2.y(), p3.y(), p1.y()) ? 3 : 2;
        }
    }

    /**
     * Handles cases where exactly two points share the same Y coordinate.
     */
    private int calculateHorizontalAlignment(Point p1, Point p2, Point p3) {
        if (p1.y() == p2.y()) {
            return isBetween(p3.x(), p2.x(), p1.x()) ? 3 : 2;
        } else if (p2.y() == p3.y()) {
            return isBetween(p1.x(), p2.x(), p3.x()) ? 3 : 2;
        } else { // p1.y == p3.y
            return isBetween(p2.x(), p3.x(), p1.x()) ? 3 : 2;
        }
    }

    /**
     * Checks if a value is strictly between two other values.
     */
    private boolean isBetween(int target, int valA, int valB) {
        return (target > valA && target < valB) || (target < valA && target > valB);
    }
}

