     */
    private static Point readPoint(Scanner scanner) {
        int x = scanner.nextInt();
        int y = scanner.nextInt();
        return new Point(x, y);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;

/**
 * Refactored solution to determine the minimum number of steps (1, 2, or 3) 
 * required to arrange three points based on their spatial configuration.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        GeometrySolver solver = new GeometrySolver(reader, writer);
        solver.solve();

        writer.flush();
        writer.close();
    }

    /**
     * Represents a 2D point with long coordinates to prevent overflow.
     */
    static class Point {
        final long x;
        final long y;

        Point(long x, long y) {
            this.x = x;
            this.y = y;
        }
    }

    /**
     * Encapsulates the geometric logic required to solve the problem.
     */
    static class GeometrySolver {
        private final FastReader reader;
        private final PrintWriter writer;

        GeometrySolver(FastReader reader, PrintWriter writer) {
            this.reader = reader;
            this.writer = writer;
        }

        /**
         * Reads three points and determines the solution (1, 2, or 3).
         */
        public void solve() {
            Point p1 = readPoint();
            Point p2 = readPoint();
            Point p3 = readPoint();

            if (p1 == null || p2 == null || p3 == null) {
                return;
            }

            if (isCollinearOnAxis(p1, p2, p3)) {
                writer.println("1");
            } else if (isConditionMet(p1, p2, p3) || isConditionMetInverted(p1, p2, p3)) {
                writer.println("2");
            } else {
                writer.println("3");
            }
        }

        private Point readPoint() {
            long[] coords = reader.readLongArray();
            if (coords.length < 2) {
                return null;
            }
            return new Point(coords[0], coords[1]);
        }

        /**
         * Returns true if all points lie on the same horizontal or vertical line.
         */
        private boolean isCollinearOnAxis(Point p1, Point p2, Point p3) {
            boolean allXSame = (p1.x == p2.x && p2.x == p3.x);
            boolean allYSame = (p1.y == p2.y && p2.y == p3.y);
            return allXSame || allYSame;
        }

        /**
         * Evaluates the specific spatial condition for the X dimension.
         */
        private boolean isConditionMet(Point p1, Point p2, Point p3) {
            return checkDimensionExtremum(p1.x, p2.x, p3.x, p1.y, p2.y, p3.y);
        }

        /**
         * Evaluates the specific spatial condition for the Y dimension.
         */
        private boolean isConditionMetInverted(Point p1, Point p2, Point p3) {
            return checkDimensionExtremum(p1.y, p2.y, p3.y, p1.x, p2.x, p3.x);
        }

        /**
         * Checks if two points share a coordinate in dimension 'a', and if the 
         * third point's 'b' coordinate is an extremum (minimum or maximum) 
         * relative to the other two points in dimension 'b'.
         */
        private boolean checkDimensionExtremum(long a1, long a2, long a3, long b1, long b2, long b3) {
            if (a1 == a2) {
                return b3 <= Math.min(b1, b2) || b3 >= Math.max(b1, b2);
            } else if (a1 == a3) {
                return b2 <= Math.min(b1, b3) || b2 >= Math.max(b1, b3);
            } else if (a2 == a3) {
                return b1 <= Math.min(b2, b3) || b1 >= Math.max(b2, b3);
            }
            return false;
        }
    }

    /**
     * High-performance utility for reading input.
     */
    static class FastReader {
        private final BufferedReader br;

        public FastReader(InputStream is) {
            this.br = new BufferedReader(new InputStreamReader(is));
        }

        public String readLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                return "";
            }
        }

        /**
         * Reads a line of space-separated numbers and converts them to a long array.
         */
        public long[] readLongArray() {
            String line = readLine();
            if (line == null || line.trim().isEmpty()) {
                return new long[0];
            }
            String[] parts = line.trim().split("\\s+");
            long[] result = new long[parts.length];
            for (int i = 0; i < parts.length; i++) {
                try {
                    result[i] = Long.parseLong(parts[i]);
                } catch (NumberFormatException e) {
                    result[i] = 0;
                }
            }
            return result;
        }
    }
}

