/**
 * Represents a 2D coordinate.
 */
record Point(int x, int y) {}

/**
 * Handles the logic for determining the line coverage for a set of points.
 */
class PointSolver {

    /**
     * Calculates the minimum number of lines (1, 2, or 3) based on the 
     * provided points and original logic.
     *
     * @param points An array of exactly 3 points.
     * @return The minimum number of lines.
     */
    public int solve(Point[] points) {
        if (points == null || points.length < 3) {
            return 0;
        }

        // Case 1: All points lie on a single vertical or horizontal line.
        if (areAllXSame(points) || areAllYSame(points)) {
            return 1;
        }

        // Case 2: Check if any two points form a line where the third point 
        // is not strictly between them on the shared axis.
        if (checkAllPermutations(points)) {
            return 2;
        }

        // Case 3: Default case.
        return 3;
    }

    private boolean areAllXSame(Point[] p) {
        return p[0].x() == p[1].x() && p[1].x() == p[2].x();
    }

    private boolean areAllYSame(Point[] p) {
        return p[0].y() == p[1].y() && p[1].y() == p[2].y();
    }

    /**
     * Evaluates all permutations of point indices to match the original judge logic.
     */
    private boolean checkAllPermutations(Point[] p) {
        return isPointOutsideSegment(p, 0, 1, 2) || isPointOutsideSegment(p, 0, 2, 1) ||
               isPointOutsideSegment(p, 1, 0, 2) || isPointOutsideSegment(p, 1, 2, 0) ||
               isPointOutsideSegment(p, 2, 0, 1) || isPointOutsideSegment(p, 2, 1, 0);
    }

    /**
     * Preserves the original 'judge' logic: 
     * Returns true if points a and b share an axis and point c's coordinate 
     * on that axis is not strictly between a and b.
     */
    private boolean isPointOutsideSegment(Point[] p, int a, int b, int c) {
        // Check vertical alignment (shared X)
        if (p[a].x() == p[b].x()) {
            int minY = Math.min(p[a].y(), p[b].y());
            int maxY = Math.max(p[a].y(), p[b].y());
            if (p[c].y() <= minY || p[c].y() >= maxY) {
                return true;
            }
        }

        // Check horizontal alignment (shared Y)
        if (p[a].y() == p[b].y()) {
            int minX = Math.min(p[a].x(), p[b].x());
            int maxX = Math.max(p[a].x(), p[b].x());
            if (p[c].x() <= minX || p[c].x() >= maxX) {
                return true;
            }
        }

        return false;
    }
}

import java.util.Scanner;

/**
 * A utility class to analyze the geometric characteristics of a polyline 
 * formed by three points.
 */
public class Polyline {

    /**
     * Represents a simple 2D coordinate.
     */
    private static class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            // Read three points from input
            Point p1 = new Point(scanner.nextInt(), scanner.nextInt());
            Point p2 = new Point(scanner.nextInt(), scanner.nextInt());
            Point p3 = new Point(scanner.nextInt(), scanner.nextInt());

            int result = calculatePolylineType(p1, p2, p3);
            System.out.println(result);
        }
    }

    /**
     * Determines the type of polyline based on the alignment of the three points.
     * 
     * @param p1 The first point.
     * @param p2 The second point.
     * @param p3 The third point.
     * @return 1 if all points are collinear on a single vertical or horizontal line.
     *         2 if two points share a coordinate and the third point is aligned 
     *         perpendicularly but falls outside the bounds of the first two.
     *         3 otherwise (e.g., diagonal lines, triangles, or points within bounds).
     */
    private static int calculatePolylineType(Point p1, Point p2, Point p3) {
        // Case 1: All points are on the same horizontal or vertical line
        if (areAllXEqual(p1, p2, p3) || areAllYEqual(p1, p2, p3)) {
            return 1;
        }

        // Case 2: Check for vertical alignments (shared X coordinates)
        if (p1.x == p2.x) {
            return isBetween(p3.y, p1.y, p2.y) ? 3 : 2;
        }
        if (p1.x == p3.x) {
            return isBetween(p2.y, p1.y, p3.y) ? 3 : 2;
        }
        if (p2.x == p3.x) {
            return isBetween(p1.y, p2.y, p3.y) ? 3 : 2;
        }

        // Case 3: Check for horizontal alignments (shared Y coordinates)
        if (p1.y == p2.y) {
            return isBetween(p3.x, p1.x, p2.x) ? 3 : 2;
        }
        if (p1.y == p3.y) {
            return isBetween(p2.x, p1.x, p3.x) ? 3 : 2;
        }
        if (p2.y == p3.y) {
            return isBetween(p1.x, p2.x, p3.x) ? 3 : 2;
        }

        // Case 4: Default case for diagonal lines or non-aligned points
        return 3;
    }

    /**
     * Checks if all three points share the same X coordinate.
     */
    private static boolean areAllXEqual(Point p1, Point p2, Point p3) {
        return p1.x == p2.x && p2.x == p3.x;
    }

    /**
     * Checks if all three points share the same Y coordinate.
     */
    private static boolean areAllYEqual(Point p1, Point p2, Point p3) {
        return p1.y == p2.y && p2.y == p3.y;
    }

    /**
     * Checks if a target value lies strictly between two other values.
     * 
     * @param target The value to check.
     * @param a The lower bound (order independent).
     * @param b The upper bound (order independent).
     * @return true if target is between a and b.
     */
    private static boolean isBetween(int target, int a, int b) {
        return target > Math.min(a, b) && target < Math.max(a, b);
    }
}

import java.util.*;
import java.util.stream.Collectors;

/**
 * A utility to solve geometric problems involving coordinate alignment.
 */
public class Main {

    private static final int TOTAL_POINTS = 3;

    /**
     * Represents a 2D coordinate point.
     */
    public record Point(int x, int y) {}

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        try {
            List<Point> points = readPoints(scanner, TOTAL_POINTS);

            // Calculate minimum segments based on X alignment
            int minSegmentsX = calculateMinSegments(points);

            // Calculate minimum segments based on Y alignment 
            // (by swapping X and Y coordinates)
            List<Point> pointsByY = points.stream()
                    .map(p -> new Point(p.y(), p.x()))
                    .collect(Collectors.toList());
            int minSegmentsY = calculateMinSegments(pointsByY);

            System.out.println(Math.min(minSegmentsX, minSegmentsY));

        } finally {
            scanner.close();
        }
    }

    /**
     * Reads a specified number of points from the input source.
     */
    private static List<Point> readPoints(Scanner scanner, int count) {
        List<Point> points = new ArrayList<>();
        for (int i = 0; i < count; i++) {
            int x = scanner.nextInt();
            int y = scanner.nextInt();
            points.add(new Point(x, y));
        }
        return points;
    }

    /**
     * Calculates the minimum segments required based on the primary coordinate (x).
     * The points are sorted by X to identify collinearity or alignment.
     *
     * @param points A list of points to evaluate.
     * @return The minimum segment count (1, 2, or 3).
     */
    private static int calculateMinSegments(List<Point> points) {
        List<Point> sortedPoints = new ArrayList<>(points);
        sortedPoints.sort(Comparator.comparingInt(Point::x));

        if (areAllXCoordinatesEqual(sortedPoints)) {
            return 1;
        }

        // Check for cases where two points share an X coordinate
        for (int i = 0; i < sortedPoints.size() - 1; i++) {
            Point current = sortedPoints.get(i);
            Point next = sortedPoints.get(i + 1);

            if (current.x() == next.x()) {
                return evaluateIntermediatePoint(sortedPoints, i, i + 1);
            }
        }

        // Default case if no two points share an X coordinate
        return 3;
    }

    /**
     * Checks if all points in the list share the same X coordinate.
     */
    private static boolean areAllXCoordinatesEqual(List<Point> points) {
        if (points.isEmpty()) return true;
        int firstX = points.get(0).x();
        return points.stream().allMatch(p -> p.x() == firstX);
    }

    /**
     * Determines if the remaining point lies between the two aligned points.
     * 
     * @param sortedPoints The sorted list of points.
     * @param idx1 Index of the first aligned point.
     * @param idx2 Index of the second aligned point.
     * @return 3 if the third point is between the Y-range of the aligned points, else 2.
     */
    private static int evaluateIntermediatePoint(List<Point> sortedPoints, int idx1, int idx2) {
        // Identify the index of the point that is not part of the aligned pair
        int otherIdx = 0;
        for (int i = 0; i < TOTAL_POINTS; i++) {
            if (i != idx1 && i != idx2) {
                otherIdx = i;
                break;
            }
        }

        int otherY = sortedPoints.get(otherIdx).y();
        int minY = Math.min(sortedPoints.get(idx1).y(), sortedPoints.get(idx2).y());
        int maxY = Math.max(sortedPoints.get(idx1).y(), sortedPoints.get(idx2).y());

        // If the third point's Y is between the others, it breaks the line into 3 segments 
        // (in the context of the specific logic provided)
        return (otherY > minY && otherY < maxY) ? 3 : 2;
    }
}

