/**
 * Handles high-performance input reading.
 */
class FastReader {
    private BufferedReader reader;
    private StringTokenizer tokenizer;

    public FastReader(InputStream input) {
        reader = new BufferedReader(new InputStreamReader(input));
        tokenizer = null;
    }

    public String next() {
        while (tokenizer == null || !tokenizer.hasMoreElements()) {
            try {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                return null;
            }
        }
        return tokenizer.nextToken();
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }
}

/**
 * Contains the geometric logic to solve the problem.
 */
class GeometrySolver {

    /**
     * Calculates the minimum number of axis-aligned segments 
     * required to connect three given points.
     */
    public int solve(Point p1, Point p2, Point p3) {
        if (isAllCollinearOnAxis(p1, p2, p3)) {
            return 1;
        }
        if (canConnectWithTwoSegments(p1, p2, p3)) {
            return 2;
        }
        return 3;
    }

    private boolean isAllCollinearOnAxis(Point p1, Point p2, Point p3) {
        boolean allSameX = (p1.x() == p2.x() && p2.x() == p3.x());
        boolean allSameY = (p1.y() == p2.y() && p2.y() == p3.y());
        return allSameX || allSameY;
    }

    private boolean canConnectWithTwoSegments(Point p1, Point p2, Point p3) {
        // Check if any pair of points can form a segment that allows 
        // the third point to be connected via one additional segment.
        return isTwoSegmentsPossible(p1, p2, p3) ||
               isTwoSegmentsPossible(p1, p3, p2) ||
               isTwoSegmentsPossible(p2, p3, p1);
    }

    private boolean isTwoSegmentsPossible(Point a, Point b, Point other) {
        if (a.x() == b.x()) {
            // If 'a' and 'b' share an X-coordinate, they form a vertical line.
            // We can connect 'other' in 2 segments only if 'other.y' is not 
            // strictly between 'a.y' and 'b.y'.
            return other.y() <= Math.min(a.y(), b.y()) || 
                   other.y() >= Math.max(a.y(), b.y());
        }
        if (a.y() == b.y()) {
            // If 'a' and 'b' share a Y-coordinate, they form a horizontal line.
            // We can connect 'other' in 2 segments only if 'other.x' is not 
            // strictly between 'a.x' and 'b.x'.
            return other.x() <= Math.min(a.x(), b.x()) || 
                   other.x() >= Math.max(a.x(), b.x());
        }
        return false;
    }
}

