/**
 * A program to calculate the minimum "alignment score" for a set of three points.
 * The score is determined based on how the points align vertically, horizontally, or otherwise.
 */
public class Main {

    /**
     * Represents a 2D point with integer coordinates.
     */
    public record Point(int x, int y) {}

    /**
     * Defines the types of alignment between two points.
     */
    private enum Alignment {
        VERTICAL,
        HORIZONTAL,
        NONE
    }

    public static void main(String[] args) {
        List<Point> points = readPointsFromConsole(3);

        if (points.size() < 3) {
            return;
        }

        int minScore = calculateMinimumScore(points);
        System.out.println(minScore);
    }

    /**
     * Reads points from standard input.
     * 
     * @param count The number of points to read.
     * @return A list of Point objects.
     */
    private static List<Point> readPointsFromConsole(int count) {
        List<Point> points = new ArrayList<>();
        try (Scanner scanner = new Scanner(System.in)) {
            for (int i = 0; i < count; i++) {
                if (scanner.hasNextInt()) {
                    int x = scanner.nextInt();
                    if (scanner.hasNextInt()) {
                        int y = scanner.nextInt();
                        points.add(new Point(x, y));
                    }
                }
            }
        }
        return points;
    }

    /**
     * Iterates through all permutations of the points to find the minimum score.
     * 
     * @param points The list of points to evaluate.
     * @return The minimum score found.
     */
    private static int calculateMinimumScore(List<Point> points) {
        int minScore = Integer.MAX_VALUE;

        // All permutations of indices 0, 1, 2
        int[][] permutations = {
            {0, 1, 2}, {0, 2, 1}, {1, 0, 2},
            {1, 2, 0}, {2, 0, 1}, {2, 1, 0}
        };

        for (int[] p : permutations) {
            int currentScore = calculateScore(
                points.get(p[0]), 
                points.get(p[1]), 
                points.get(p[2])
            );
            minScore = Math.min(minScore, currentScore);
        }

        return minScore;
    }

    /**
     * Calculates the score for a specific triplet of points.
     * 
     * @param a The first point.
     * @param b The second point.
     * @param c The third point.
     * @return The alignment score.
     */
    private static int calculateScore(Point a, Point b, Point c) {
        Alignment ab = getAlignment(a, b);
        Alignment ac = getAlignment(a, c);
        Alignment bc = getAlignment(b, c);

        // Case 1: All points are aligned on the same line (all vertical or all horizontal)
        if (ab != Alignment.NONE && ab == ac && ac == bc) {
            return 1;
        }

        // Case 2: Evaluate based on the relationship between the first two points
        if (ab == Alignment.VERTICAL) {
            // If C's Y is an extreme (not strictly between A and B), return 2, else 3
            return isCoordinateExtreme(c.y(), a.y(), b.y()) ? 2 : 3;
        } else if (ab == Alignment.HORIZONTAL) {
            // If C's X is an extreme (not strictly between A and B), return 2, else 3
            return isCoordinateExtreme(c.x(), a.x(), b.x()) ? 2 : 3;
        }

        // Case 3: No specific alignment between A and B
        return 3;
    }

    /**
     * Determines if two points are aligned vertically or horizontally.
     */
    private static Alignment getAlignment(Point p1, Point p2) {
        if (p1.x() == p2.x()) {
            return Alignment.VERTICAL;
        } else if (p1.y() == p2.y()) {
            return Alignment.HORIZONTAL;
        }
        return Alignment.NONE;
    }

    /**
     * Helper to check if the 'target' coordinate is at the boundary or outside the range of p1 and p2.
     */
    private static boolean isCoordinateExtreme(int target, int coord1, int coord2) {
        return target <= Math.min(coord1, coord2) || target >= Math.max(coord1, coord2);
    }
}

