/**
 * Refactored solution for determining the minimum number of axis-parallel 
 * segments needed to connect three points.
 */
public class Main {

    public static void main(String[] args) {
        new Solver(System.in, System.out).run();
    }

    /**
     * Represents a 2D coordinate point.
     */
    static class Point {
        final long x;
        final long y;

        Point(long x, long y) {
            this.x = x;
            this.y = y;
        }
    }

    /**
     * Contains the core logic for solving the problem.
     */
    static class Solver {
        private final FastReader reader;
        private final PrintWriter writer;

        Solver(InputStream is, OutputStream os) {
            this.reader = new FastReader(is);
            this.writer = new PrintWriter(os);
        }

        public void run() {
            try {
                solve();
            } finally {
                writer.close();
            }
        }

        private void solve() {
            Point p1 = new Point(reader.nextLong(), reader.nextLong());
            Point p2 = new Point(reader.nextLong(), reader.nextLong());
            Point p3 = new Point(reader.nextLong(), reader.nextLong());

            if (isAllCollinearOnAxisParallelLine(p1, p2, p3)) {
                writer.println(1);
            } else if (hasAxisParallelSegmentWithOutsidePoint(p1, p2, p3)) {
                writer.println(2);
            } else {
                writer.println(3);
            }
        }

        /**
         * Returns true if all three points lie on the same horizontal or vertical line.
         */
        private boolean isAllCollinearOnAxisParallelLine(Point p1, Point p2, Point p3) {
            boolean allXSame = (p1.x == p2.x && p2.x == p3.x);
            boolean allYSame = (p1.y == p2.y && p2.y == p3.y);
            return allXSame || allYSame;
        }

        /**
         * Checks if any pair of points forms an axis-parallel segment such that 
         * the third point's coordinate on that axis is not strictly between the pair.
         */
        private boolean hasAxisParallelSegmentWithOutsidePoint(Point p1, Point p2, Point p3) {
            return checkPair(p1, p2, p3) || 
                   checkPair(p2, p3, p1) || 
                   checkPair(p3, p1, p2);
        }

        /**
         * If points a and b form an axis-parallel line, checks if point c 
         * is "outside" the range of that segment on the relevant axis.
         */
        private boolean checkPair(Point a, Point b, Point c) {
            // If a and b form a horizontal line
            if (a.y == b.y) {
                return isCoordinateOutsideRange(c.x, a.x, b.x);
            }
            // If a and b form a vertical line
            if (a.x == b.x) {
                return isCoordinateOutsideRange(c.y, a.y, b.y);
            }
            return false;
        }

        /**
         * Logic equivalent to the original condition: 
         * (val >= end1 && val >= end2) || (val <= end1 && val <= end2)
         */
        private boolean isCoordinateOutsideRange(long val, long end1, long end2) {
            return (val >= end1 && val >= end2) || (val <= end1 && val <= end2);
        }
    }

    /**
     * Efficient utility for reading input.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
