/**
 * A solution to determine the minimum number of axis-aligned segments 
 * required to connect three given points in a 2D plane.
 */
public class PointPathSolver {

    /**
     * Represents a 2D point with integer coordinates.
     * Using a record ensures immutability and provides clean data access.
     */
    public record Point(int x, int y) {}

    public static void main(String[] args) {
        PointPathSolver solver = new PointPathSolver();
        solver.run();
    }

    /**
     * Orchestrates the reading of input and the writing of the result.
     */
    public void run() {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            Point[] points = new Point[3];
            for (int i = 0; i < 3; i++) {
                String xStr = reader.next();
                String yStr = reader.next();
                if (xStr == null || yStr == null) break;
                points[i] = new Point(Integer.parseInt(xStr), Integer.parseInt(yStr));
            }

            writer.println(calculateMinSegments(points));
        } catch (Exception e) {
            // In a production environment, use a professional logging framework.
            e.printStackTrace();
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Determines the minimum number of segments (1, 2, or 3) needed to connect the points.
     * 
     * @param points An array of exactly 3 points.
     * @return The minimum number of axis-aligned segments.
     */
    private int calculateMinSegments(Point[] points) {
        if (isCollinear(points)) {
            return 1;
        }

        if (canConnectWithTwoSegments(points)) {
            return 2;
        }

        return 3;
    }

    /**
     * Checks if all three points lie on a single horizontal or vertical line.
     */
    private boolean isCollinear(Point[] points) {
        boolean allXSame = points[0].x == points[1].x && points[1].x == points[2].x;
        boolean allYSame = points[0].y == points[1].y && points[1].y == points[2].y;
        return allXSame || allYSame;
    }

    /**
     * Checks if the three points can be connected using exactly two axis-aligned segments.
     * This occurs if there exists a "corner" point (which may or may not be one 
     * of the given points) such that all three points lie on the two segments 
     * forming the resulting L-shape.
     */
    private boolean canConnectWithTwoSegments(Point[] points) {
        // We test every possible pair of points (i, j) as the endpoints of an L-shape.
        // The corner of such an L-shape is defined by (points[i].x, points[j].y).
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                if (i == j) continue;

                Point pI = points[i];
                Point pJ = points[j];
                Point corner = new Point(pI.x, pJ.y);

                int thirdIndex = findThirdIndex(i, j);
                Point pK = points[thirdIndex];

                // If the third point lies on either the vertical or horizontal 
                // leg of the L-shape formed by pI, corner, and pJ, then 2 segments suffice.
                if (isOnSegment(pK, pI, corner) || isOnSegment(pK, corner, pJ)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Helper to find the index of the point not used in the current pair.
     */
    private int findThirdIndex(int i, int j) {
        for (int idx = 0; idx < 3; idx++) {
            if (idx != i && idx != j) return idx;
        }
        return -1;
    }

    /**
     * Checks if point p lies on the axis-aligned segment between s1 and s2.
     */
    private boolean isOnSegment(Point p, Point s1, Point s2) {
        // Check if the point is within the bounding box of the segment
        boolean withinX = p.x >= Math.min(s1.x, s2.x) && p.x <= Math.max(s1.x, s2.x);
        boolean withinY = p.y >= Math.min(s1.y, s2.y) && p.y <= Math.max(s1.y, s2.y);

        if (!withinX || !withinY) {
            return false;
        }

        // Ensure the segment is axis-aligned (vertical or horizontal)
        // and that the point p lies on that specific axis.
        boolean isVertical = (s1.x == s2.x && p.x == s1.x);
        boolean isHorizontal = (s1.y == s2.y && p.y == s1.y);

        return isVertical || isHorizontal;
    }

    /**
     * Fast I/O class for efficient reading of input.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }
    }
}

