/**
 * A solution to determine the minimum number of lines (horizontal or vertical)
 * required to satisfy specific coordinate patterns for three points.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            List<Point> points = new ArrayList<>();
            for (int i = 0; i < 3; i++) {
                points.add(new Point(reader.nextInt(), reader.nextInt()));
            }

            CoordinateSolver solver = new CoordinateSolver(points);
            writer.println(solver.solve());
        } catch (Exception e) {
            // In a production environment, use a proper logger
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    /**
     * Represents a 2D coordinate point.
     */
    static class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }

        /**
         * Returns a new point with the x and y coordinates swapped.
         */
        Point swapped() {
            return new Point(y, x);
        }
    }

    /**
     * Contains the logic to calculate the result based on point coordinates.
     */
    static class CoordinateSolver {
        private final List<Point> points;

        CoordinateSolver(List<Point> points) {
            this.points = points;
        }

        /**
         * Solves the problem and returns the minimum number of lines (1, 2, or 3).
         */
        public int solve() {
            if (isAllXEqual() || isAllYEqual()) {
                return 1;
            }

            if (hasTwoLinePattern(points)) {
                return 2;
            }

            // Check the pattern by swapping axes (equivalent to checking horizontal segments)
            List<Point> swappedPoints = new ArrayList<>();
            for (Point p : points) {
                swappedPoints.add(p.swapped());
            }

            if (hasTwoLinePattern(swappedPoints)) {
                return 2;
            }

            return 3;
        }

        private boolean isAllXEqual() {
            return points.get(0).x == points.get(1).x && points.get(1).x == points.get(2).x;
        }

        private boolean isAllYEqual() {
            return points.get(0).y == points.get(1).y && points.get(1).y == points.get(2).y;
        }

        /**
         * Checks if there exists a pair of points sharing an X coordinate
         * such that the third point's Y coordinate is outside their range.
         */
        private boolean hasTwoLinePattern(List<Point> pts) {
            for (int i = 0; i < 3; i++) {
                for (int j = i + 1; j < 3; j++) {
                    Point p1 = pts.get(i);
                    Point p2 = pts.get(j);

                    // Check if two points share the same X coordinate
                    if (p1.x == p2.x) {
                        int k = getThirdIndex(i, j);
                        Point p3 = pts.get(k);

                        // The pattern requires the third point to have a different X
                        if (p3.x != p1.x) {
                            int minY = Math.min(p1.y, p2.y);
                            int maxY = Math.max(p1.y, p2.y);

                            if (p3.y >= maxY || p3.y <= minY) {
                                return true;
                            }
                        }
                    }
                }
            }
            return false;
        }

        private int getThirdIndex(int i, int j) {
            for (int k = 0; k < 3; k++) {
                if (k != i && k != j) return k;
            }
            return -1;
        }
    }

    /**
     * High-performance reader for fast I/O.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
