/**
 * A program to determine the minimum number of axis-parallel lines 
 * required to connect three given points.
 */
public class PointConnectivity {

    public static void main(String[] args) {
        try {
            FastReader reader = new FastReader();
            solve(reader);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * Orchestrates the input reading and output logic.
     * 
     * @param reader The FastReader instance for efficient input reading.
     */
    private static void solve(FastReader reader) {
        Point[] points = new Point[3];
        for (int i = 0; i < 3; i++) {
            points[i] = new Point(reader.nextInt(), reader.nextInt());
        }

        if (isCollinearAxisParallel(points)) {
            System.out.println(1);
        } else if (canConnectWithTwoLines(points)) {
            System.out.println(2);
        } else {
            System.out.println(3);
        }
    }

    /**
     * Checks if all three points lie on a single horizontal or vertical line.
     */
    private static boolean isCollinearAxisParallel(Point[] p) {
        return isAllXSame(p) || isAllYSame(p);
    }

    private static boolean isAllXSame(Point[] p) {
        return p[0].x == p[1].x && p[1].x == p[2].x;
    }

    private static boolean isAllYSame(Point[] p) {
        return p[0].y == p[1].y && p[1].y == p[2].y;
    }

    /**
     * Determines if the points can be connected using exactly two axis-parallel lines.
     * This occurs if two points share a coordinate and the third point is not 
     * positioned between them on the perpendicular axis.
     */
    private static boolean canConnectWithTwoLines(Point[] p) {
        // Vertical alignment checks
        if (p[0].x == p[1].x && isOutsideRange(p[2].y, p[0].y, p[1].y)) return true;
        if (p[0].x == p[2].x && isOutsideRange(p[1].y, p[0].y, p[2].y)) return true;
        if (p[1].x == p[2].x && isOutsideRange(p[0].y, p[1].y, p[2].y)) return true;

        // Horizontal alignment checks
        if (p[0].y == p[1].y && isOutsideRange(p[2].x, p[0].x, p[1].x)) return true;
        if (p[0].y == p[2].y && isOutsideRange(p[1].x, p[0].x, p[2].x)) return true;
        if (p[1].y == p[2].y && isOutsideRange(p[0].x, p[1].x, p[2].x)) return true;

        return false;
    }

    /**
     * Helper to check if a value is outside the inclusive range [min, max].
     */
    private static boolean isOutsideRange(int target, int a, int b) {
        return target >= Math.max(a, b) || target <= Math.min(a, b);
    }

    /**
     * Represents a coordinate in 2D space.
     */
    static class Point {
        final int x, y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

