/**
 * A utility to calculate the minimum number of horizontal or vertical 
 * segments required to connect three points.
 */
public class PointGeometry {

    /**
     * Represents a 2D point with integer coordinates.
     */
    static class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        try {
            Point[] points = new Point[3];
            for (int i = 0; i < 3; i++) {
                if (scanner.hasNextInt()) {
                    int x = scanner.nextInt();
                    int y = scanner.nextInt();
                    points[i] = new Point(x, y);
                }
            }

            System.out.println(calculateMinSegments(points));
        } catch (Exception e) {
            // In a real application, use a logger. 
            // For this refactor, we handle basic input errors gracefully.
        } finally {
            scanner.close();
        }
    }

    /**
     * Determines the minimum number of horizontal or vertical segments 
     * needed to connect the three points.
     * 
     * @param points An array of exactly 3 Point objects.
     * @return 1 if all points are on one line, 2 if they can be connected 
     *         by an L-shape, 3 otherwise.
     */
    public static int calculateMinSegments(Point[] points) {
        if (isSingleLine(points)) {
            return 1;
        }
        if (canConnectWithTwoSegments(points)) {
            return 2;
        }
        return 3;
    }

    /**
     * Checks if all three points lie on the same horizontal or vertical line.
     */
    private static boolean isSingleLine(Point[] p) {
        boolean allXSame = (p[0].x == p[1].x && p[1].x == p[2].x);
        boolean allYSame = (p[0].y == p[1].y && p[1].y == p[2].y);
        return allXSame || allYSame;
    }

    /**
     * Checks if the points can be connected using exactly two segments 
     * (forming an 'L' shape or a T-junction).
     */
    private static boolean canConnectWithTwoSegments(Point[] p) {
        // We check every combination of two points to see if they form 
        // a base segment (horizontal or vertical) that the third point 
        // can connect to via a perpendicular segment.
        int[][] pairs = {{0, 1, 2}, {1, 2, 0}, {2, 0, 1}};

        for (int[] triplet : pairs) {
            Point a = p[triplet[0]];
            Point b = p[triplet[1]];
            Point c = p[triplet[2]];

            // Check if points 'a' and 'b' form a vertical segment
            if (a.x == b.x && a.y != b.y) {
                int minY = Math.min(a.y, b.y);
                int maxY = Math.max(a.y, b.y);
                // If 'c' is not strictly between 'a' and 'b' on the Y axis,
                // it can form a right angle at 'a' or 'b'.
                if (c.y >= maxY || c.y <= minY) {
                    return true;
                }
            }

            // Check if points 'a' and 'b' form a horizontal segment
            if (a.y == b.y && a.x != b.x) {
                int minX = Math.min(a.x, b.x);
                int maxX = Math.max(a.x, b.x);
                // If 'c' is not strictly between 'a' and 'b' on the X axis,
                // it can form a right angle at 'a' or 'b'.
                if (c.x >= maxX || c.x <= minX) {
                    return true;
                }
            }
        }
        return false;
    }
}

import java.util.*;

/**
 * A program to determine the configuration of three points in a 2D plane.
 * The result represents the number of segments/lines needed to connect them
 * based on their collinearity and axis-alignment.
 */
public class Main {

    /**
     * Represents a point in 2D space.
     */
    static class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        List<Point> points = new ArrayList<>();

        try {
            for (int i = 0; i < 3; i++) {
                if (scanner.hasNextInt()) {
                    int x = scanner.nextInt();
                    int y = scanner.nextInt();
                    points.add(new Point(x, y));
                }
            }

            if (points.size() == 3) {
                System.out.println(calculateConfiguration(points));
            }
        } catch (Exception e) {
            // In a production environment, use a logger.
            System.err.println("Error processing input: " + e.getMessage());
        } finally {
            scanner.close();
        }
    }

    /**
     * Calculates the configuration value based on the arrangement of the three points.
     * 
     * @param points A list containing exactly three Point objects.
     * @return An integer representing the configuration (1, 2, or 3).
     */
    public static int calculateConfiguration(List<Point> points) {
        Set<Integer> distinctXCoords = new HashSet<>();
        Set<Integer> distinctYCoords = new HashSet<>();

        for (Point p : points) {
            distinctXCoords.add(p.x);
            distinctYCoords.add(p.y);
        }

        int xSize = distinctXCoords.size();
        int ySize = distinctYCoords.size();

        // Case 1: All points are on a single vertical or horizontal line.
        if (xSize == 1 || ySize == 1) {
            return 1;
        }

        // Case 2: All points have unique X and Y coordinates (forming a triangle).
        if (xSize == 3 && ySize == 3) {
            return 3;
        }

        // Case 3: Points form an L-shape (two distinct X and two distinct Y).
        if (xSize == 2 && ySize == 2) {
            return 2;
        }

        // Case 4: Mixed cases where one dimension has 2 unique values and the other has 3.
        // This checks if the "lonely" point's coordinate falls between the other two.
        if (xSize == 2) {
            return isThirdCoordinateBetweenOthers(points, true) ? 3 : 2;
        } else {
            // This implies ySize == 2 and xSize == 3
            return isThirdCoordinateBetweenOthers(points, false) ? 3 : 2;
        }
    }

    /**
     * Determines if the coordinate of the point with the unique value 
     * lies between the values of the other two points.
     * 
     * @param points The list of points.
     * @param checkX If true, find the pair sharing X and check their Ys. 
     *               If false, find the pair sharing Y and check their Xs.
     * @return true if the third value is between the other two.
     */
    private static boolean isThirdCoordinateBetweenOthers(List<Point> points, boolean checkX) {
        Point p1 = points.get(0);
        Point p2 = points.get(1);
        Point p3 = points.get(2);

        int valA, valB, valOther;

        if (checkX) {
            // Identify the two points sharing the same X and retrieve their Ys
            if (p1.x == p2.x) {
                valA = p1.y; valB = p2.y; valOther = p3.y;
            } else if (p2.x == p3.x) {
                valA = p2.y; valB = p3.y; valOther = p1.y;
            } else {
                valA = p1.y; valB = p3.y; valOther = p2.y;
            }
        } else {
            // Identify the two points sharing the same Y and retrieve their Xs
            if (p1.y == p2.y) {
                valA = p1.x; valB = p2.x; valOther = p3.x;
            } else if (p2.y == p3.y) {
                valA = p2.x; valB = p3.x; valOther = p1.x;
            } else {
                valA = p1.x; valB = p3.x; valOther = p2.x;
            }
        }

        return isBetween(valOther, valA, valB);
    }

    /**
     * Helper to check if a value is strictly between two others.
     */
    private static boolean isBetween(int value, int start, int end) {
        return value > Math.min(start, end) && value < Math.max(start, end);
    }
}

