/**
 * Logic for solving the geometric problem.
 */
class GeometrySolver {

    /**
     * Determines the minimum number of axis-aligned segments required to connect three points.
     */
    public int solve(Point a, Point b, Point c) {
        if (areAllOnSameAxis(a, b, c)) {
            return 1;
        }

        if (canBeCoveredByTwoSegments(a, b, c)) {
            return 2;
        }

        return 3;
    }

    private boolean areAllOnSameAxis(Point a, Point b, Point c) {
        boolean sameX = (a.getX() == b.getX() && a.getX() == c.getX());
        boolean sameY = (a.getY() == b.getY() && a.getY() == c.getY());
        return sameX || sameY;
    }

    private boolean canBeCoveredByTwoSegments(Point a, Point b, Point c) {
        // Check all permutations to see if any two points form an axis-aligned segment 
        // such that the third point is "outside" the range of the segment on the other axis.
        return isThirdPointOutsideAxisAlignedSegment(a, b, c) ||
               isThirdPointOutsideAxisAlignedSegment(a, c, b) ||
               isThirdPointOutsideAxisAlignedSegment(b, a, c) ||
               isThirdPointOutsideAxisAlignedSegment(b, c, a) ||
               isThirdPointOutsideAxisAlignedSegment(c, a, b) ||
               isThirdPointOutsideAxisAlignedSegment(c, b, a);
    }

    private boolean isThirdPointOutsideAxisAlignedSegment(Point p1, Point p2, Point target) {
        if (p1.getX() == p2.getX()) {
            // Vertical segment: check if target Y is outside segment Y bounds
            return target.getY() <= Math.min(p1.getY(), p2.getY()) || 
                   target.getY() >= Math.max(p1.getY(), p2.getY());
        }
        if (p1.getY() == p2.getY()) {
            // Horizontal segment: check if target X is outside segment X bounds
            return target.getX() <= Math.min(p1.getX(), p2.getX()) || 
                   target.getX() >= Math.max(p1.getX(), p2.getX());
        }
        return false;
    }
}

