/**
 * Logic service to analyze point configurations.
 */
class PointAnalyzer {

    private static final int ALL_POINTS_ON_ONE_LINE = 1;
    private static final int TWO_LINES_REQUIRED = 2;
    private static final int THREE_LINES_REQUIRED = 3;

    /**
     * Calculates the minimum number of axis-aligned lines (horizontal or vertical) 
     * required to cover the given points.
     * 
     * Logic for 3 points:
     * - If all X or all Y are the same, they lie on 1 line.
     * - If at least two points share an X or a Y, they can be covered by 2 lines.
     * - Otherwise, 3 lines are required.
     *
     * @param points An array of 3 Point objects.
     * @return The minimum number of lines required.
     */
    public int calculateMinLines(Point[] points) {
        if (points == null || points.length == 0) {
            return 0;
        }

        Set<Long> uniqueX = new HashSet<>();
        Set<Long> uniqueY = new HashSet<>();

        for (Point p : points) {
            uniqueX.add(p.getX());
            uniqueY.add(p.getY());
        }

        // Case 1: All points share the same X or the same Y
        if (uniqueX.size() == 1 || uniqueY.size() == 1) {
            return ALL_POINTS_ON_ONE_LINE;
        }

        // Case 2: Two points share an X or a Y 
        // (This happens if there are only 2 unique X coordinates or 2 unique Y coordinates)
        if (uniqueX.size() < 3 || uniqueY.size() < 3) {
            return TWO_LINES_REQUIRED;
        }

        // Case 3: All X and all Y are unique
        return THREE_LINES_REQUIRED;
    }
}

