/**
 * Logic for analyzing the properties of a polyline formed by points.
 */
class PolylineAnalyzer {

    /**
     * Calculates the minimum number of segments required to connect the three points.
     * 
     * @param points An array of 3 points.
     * @return 1 if collinear on a single axis, 2 if one point lies on the segment of others, 3 otherwise.
     */
    public int calculateMinimumSegments(Point[] points) {
        if (points.length < 3) {
            throw new IllegalArgumentException("Analysis requires exactly 3 points.");
        }

        if (arePointsOnSameAxis(points[0], points[1], points[2])) {
            return 1;
        }

        if (isOnePointOnSegmentOfOthers(points)) {
            return 2;
        }

        return 3;
    }

    private boolean arePointsOnSameAxis(Point p1, Point p2, Point p3) {
        boolean allXSame = (p1.getX() == p2.getX() && p2.getX() == p3.getX());
        boolean allYSame = (p1.getY() == p2.getY() && p2.getY() == p3.getY());
        return allXSame || allYSame;
    }

    private boolean isOnePointOnSegmentOfOthers(Point[] p) {
        // Checks if any point k lies on the axis-aligned segment formed by points i and j
        return isPointOnAxisAlignedSegment(p[0], p[1], p[2]) ||
               isPointOnAxisAlignedSegment(p[0], p[2], p[1]) ||
               isPointOnAxisAlignedSegment(p[1], p[2], p[0]);
    }

    /**
     * Determines if point 'k' lies on the axis-aligned segment formed by 'i' and 'j'.
     */
    private boolean isPointOnAxisAlignedSegment(Point i, Point j, Point k) {
        // Vertical segment check
        if (k.getX() == i.getX() || k.getX() == j.getX()) {
            int minY = Math.min(i.getY(), j.getY());
            int maxY = Math.max(i.getY(), j.getY());
            if (k.getY() >= minY && k.getY() <= maxY) {
                // Ensure k is on the same vertical line as the segment
                if (i.getX() == j.getX() || k.getX() == i.getX() || k.getX() == j.getX()) {
                    // To strictly match original logic: if segment isn't vertical, 
                    // k must match one of the x-coords of the endpoints.
                    return true;
                }
            }
        }

        // Horizontal segment check
        if (k.getY() == i.getY() || k.getY() == j.getY()) {
            int minX = Math.min(i.getX(), j.getX());
            int maxX = Math.max(i.getX(), j.getX());
            if (k.getX() >= minX && k.getX() <= maxX) {
                return true;
            }
        }

        return false;
    }
}

