/**
 * A program to determine the minimum number of horizontal/vertical segments 
 * required to connect three given points.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);
        GeometrySolver solver = new GeometrySolver();

        // The original logic processed 1 test case
        int testCases = 1;
        for (int i = 1; i <= testCases; i++) {
            solver.solve(reader, writer);
        }

        writer.flush();
        writer.close();
    }

    /**
     * Represents a 2D coordinate.
     */
    static class Point {
        final int x, y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    static class GeometrySolver {

        /**
         * Solves a single test case.
         */
        public void solve(FastReader reader, PrintWriter writer) {
            Point[] points = new Point[3];
            for (int i = 0; i < 3; i++) {
                points[i] = new Point(reader.nextInt(), reader.nextInt());
            }

            writer.println(calculateMinSegments(points));
        }

        /**
         * Calculates the minimum segments (1, 2, or 3) required to connect the points.
         */
        private int calculateMinSegments(Point[] points) {
            if (isCollinearOnAxis(points)) {
                return 1;
            }
            if (canConnectWithTwoSegments(points)) {
                return 2;
            }
            return 3;
        }

        /**
         * Checks if all points lie on the same vertical or horizontal line.
         */
        private boolean isCollinearOnAxis(Point[] p) {
            boolean allXSame = (p[0].x == p[1].x && p[1].x == p[2].x);
            boolean allYSame = (p[0].y == p[1].y && p[1].y == p[2].y);
            return allXSame || allYSame;
        }

        /**
         * Checks if the points can be connected using 2 segments.
         * This occurs if two points share a coordinate, and the third point's 
         * opposite coordinate is an extreme (max or min) relative to the pair.
         */
        private boolean canConnectWithTwoSegments(Point[] p) {
            for (int i = 0; i < 3; i++) {
                for (int j = i + 1; j < 3; j++) {
                    // The third point index
                    int k = 3 - i - j;

                    // Case 1: Two points share the same X-coordinate
                    if (p[i].x == p[j].x) {
                        if (p[k].y >= Math.max(p[i].y, p[j].y) || 
                            p[k].y <= Math.min(p[i].y, p[j].y)) {
                            return true;
                        }
                    }

                    // Case 2: Two points share the same Y-coordinate
                    if (p[i].y == p[j].y) {
                        if (p[k].x >= Math.max(p[i].x, p[j].x) || 
                            p[k].x <= Math.min(p[i].x, p[j].x)) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }
    }

