import java.util.HashSet;
import java.util.Scanner;
import java.util.Set;

/**
 * A program to determine the minimum number of axis-aligned segments 
 * required to connect three given points.
 */
public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        Point[] points = new Point[3];

        try {
            for (int i = 0; i < 3; i++) {
                int x = scanner.nextInt();
                int y = scanner.nextInt();
                points[i] = new Point(x, y);
            }

            int result = solve(points);
            System.out.println(result);
        } catch (Exception e) {
            // In a real application, use a logger and handle specific exceptions
            System.err.println("Error processing input: " + e.getMessage());
        } finally {
            scanner.close();
        }
    }

    /**
     * Orchestrates the logic to find the minimum segments needed.
     * 
     * @param points An array of exactly 3 Point objects.
     * @return 1 if all points are on a single axis-aligned line, 
     *         2 if they can be connected via two segments, 
     *         3 otherwise.
     */
    private static int solve(Point[] points) {
        if (areAllPointsOnSingleAxis(points)) {
            return 1;
        }

        if (canConnectWithTwoSegments(points)) {
            return 2;
        }

        return 3;
    }

    /**
     * Determines if all provided points lie on a single horizontal or vertical line.
     */
    private static boolean areAllPointsOnSingleAxis(Point[] points) {
        Set<Integer> uniqueXCoordinates = new HashSet<>();
        Set<Integer> uniqueYCoordinates = new HashSet<>();

        for (Point p : points) {
            uniqueXCoordinates.add(p.x);
            uniqueYCoordinates.add(p.y);
        }

        // If all points share the same X or the same Y, they are collinear on an axis-aligned line.
        return uniqueXCoordinates.size() == 1 || uniqueYCoordinates.size() == 1;
    }

    /**
     * Checks if the points can be connected using exactly two axis-aligned segments.
     */
    private static boolean canConnectWithTwoSegments(Point[] points) {
        // A configuration of 3 points can be connected by 2 segments if one point
        // serves as an endpoint or corner that is not strictly trapped between 
        // the other two on an axis-aligned segment.
        return points[0].isNotBetweenOnAxis(points[1], points[2]) ||
               points[1].isNotBetweenOnAxis(points[0], points[2]) ||
               points[2].isNotBetweenOnAxis(points[0], points[1]);
    }

    /**
     * Represents a point in 2D space with immutable integer coordinates.
     */
    static class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }

        /**
         * Checks if this point is NOT strictly between p1 and p2 
         * when p1 and p2 form an axis-aligned segment.
         *
         * @param p1 First point of the reference segment.
         * @param p2 Second point of the reference segment.
         * @return true if the point is not strictly between p1 and p2 on their axis.
         */
        boolean isNotBetweenOnAxis(Point p1, Point p2) {
            if (p1.y == p2.y) {
                return !isStrictlyBetween(this.x, p1.x, p2.x);
            }
            if (p1.x == p2.x) {
                return !isStrictlyBetween(this.y, p1.y, p2.y);
            }
            return false;
        }

        private boolean isStrictlyBetween(int value, int start, int end) {
            return value > Math.min(start, end) && value < Math.max(start, end);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A utility to classify the geometric relationship between three points.
 */
public class Codeforces {

    /**
     * Represents an immutable 2D point with integer coordinates.
     */
    static class Point implements Comparable<Point> {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }

        @Override
        public int compareTo(Point other) {
            if (this.x != other.x) {
                return Integer.compare(this.x, other.x);
            }
            return Integer.compare(this.y, other.y);
        }
    }

    /**
     * Classifies three points into one of three categories based on their geometric arrangement.
     * The logic preserves the specific behavioral rules of the original implementation.
     *
     * @param points An array of exactly 3 Point objects, sorted lexicographically.
     * @return An integer representing the classification (1, 2, or 3).
     */
    public static int classifyPoints(Point[] points) {
        // Case 1: Vertical orientation checks
        if (points[0].x == points[1].x) {
            if (points[1].x == points[2].x) {
                return 1; // All three points are on a vertical line
            }
            // Specific vertical-to-non-vertical relationship rules
            if (points[1].y <= points[2].y || points[0].y == points[2].y) {
                return 2;
            }
            if (points[0].y >= points[2].y) {
                return 2;
            }
            return 3;
        }

        // Case 2: Horizontal orientation checks
        if (points[0].y == points[1].y) {
            return (points[1].y == points[2].y) ? 1 : 2;
        }

        // Case 3: Relationship between Point 0 and Point 2
        if (points[0].y == points[2].y) {
            return (points[2].x == points[1].x) ? 2 : 3;
        }

        // Case 4: Vertical relationship between Point 1 and Point 2
        if (points[1].x == points[2].x) {
            boolean bothAbove = (points[1].y > points[0].y && points[2].y > points[0].y);
            boolean bothBelow = (points[1].y < points[0].y && points[2].y < points[0].y);
            return (bothAbove || bothBelow) ? 2 : 3;
        }

        // Case 5: Horizontal relationship between Point 1 and Point 2
        if (points[1].y == points[2].y) {
            return 2;
        }

        // Default case
        return 3;
    }

    public static void main(String[] args) {
        FastReader sc = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            Point[] points = new Point[3];
            for (int i = 0; i < 3; i++) {
                int x = sc.nextInt();
                int y = sc.nextInt();
                points[i] = new Point(x, y);
            }

            // Sorting is required for the classification logic to work correctly
            Arrays.sort(points);
            out.println(classifyPoints(points));

        } catch (Exception e) {
            // In a production environment, use a logger.
            // In competitive programming, we let the exception propagate or handle silently.
        } finally {
            out.close();
        }
    }

    /**
     * Fast I/O utility class for efficient reading of input.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            return (next == null) ? 0 : Integer.parseInt(next);
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Entry point for the application.
 * Coordinates input, execution of the solver, and output.
 */
public class Main {
    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        GeometrySolver solver = new GeometrySolver();
        solver.solve(reader, writer);

        writer.flush();
        writer.close();
    }

    /**
     * Represents a 2D point with long coordinates.
     * This class is immutable to ensure thread safety and predictability.
     */
    static final class Point {
        final long x;
        final long y;

        Point(long x, long y) {
            this.x = x;
            this.y = y;
        }

        Point subtract(Point other) {
            return new Point(this.x - other.x, this.y - other.y);
        }

        /**
         * Calculates the determinant (cross product) of this vector and another.
         * Used to determine collinearity.
         */
        long determinant(Point other) {
            return this.x * other.y - this.y * other.x;
        }
    }

    /**
     * Contains the core logic for solving the geometric problem.
     */
    static class GeometrySolver {

        /**
         * Main logic to determine the minimum number of rays/lines 
         * needed to cover the three points.
         */
        public void solve(FastReader in, PrintWriter out) {
            Point a = new Point(in.nextInt(), in.nextInt());
            Point b = new Point(in.nextInt(), in.nextInt());
            Point c = new Point(in.nextInt(), in.nextInt());
            Point[] points = {a, b, c};

            if (isCollinearAndAxisAligned(a, b, c)) {
                out.println(1);
                return;
            }

            if (canBeCoveredByTwoRays(points)) {
                out.println(2);
            } else {
                out.println(3);
            }
        }

        /**
         * Checks if all three points are collinear and lie on a 
         * horizontal or vertical line.
         */
        private boolean isCollinearAndAxisAligned(Point a, Point b, Point c) {
            Point vectorAB = a.subtract(b);
            Point vectorAC = a.subtract(c);

            boolean isCollinear = vectorAB.determinant(vectorAC) == 0;
            boolean isAxisAligned = (vectorAB.x == 0 || vectorAB.y == 0);

            return isCollinear && isAxisAligned;
        }

        /**
         * Checks if there exists a candidate origin point (formed by the 
         * intersections of the x and y coordinates of the input points) 
         * that can cover all points using exactly two rays.
         */
        private boolean canBeCoveredByTwoRays(Point[] points) {
            // Generate candidate X and Y coordinates from existing points
            long[] candidateXs = {points[0].x, points[1].x, points[2].x};
            long[] candidateYs = {points[0].y, points[1].y, points[2].y};

            for (long x : candidateXs) {
                for (long y : candidateYs) {
                    Point origin = new Point(x, y);
                    int raysCount = countRaysFromOrigin(origin, points);

                    if (raysCount == 2) {
                        return true;
                    }
                }
            }
            return false;
        }

        /**
         * Counts how many distinct directions (rays) are needed to cover 
         * the points relative to an origin.
         * 
         * Returns -1 if any point is not on the X or Y axis relative to the origin.
         */
        private int countRaysFromOrigin(Point origin, Point[] points) {
            int directionMask = 0;

            for (Point target : points) {
                long dx = target.x - origin.x;
                long dy = target.y - origin.y;

                // If the target point is the origin itself, it doesn't require a ray
                if (dx == 0 && dy == 0) {
                    continue;
                }

                if (dx == 0) {
                    // Vertical ray: bit 0 for down, bit 1 for up
                    directionMask |= (dy < 0) ? (1 << 0) : (1 << 1);
                } else if (dy == 0) {
                    // Horizontal ray: bit 2 for left, bit 3 for right
                    directionMask |= (dx < 0) ? (1 << 2) : (1 << 3);
                } else {
                    // Target point is not on an axis relative to origin
                    return -1;
                }
            }

            return Integer.bitCount(directionMask);
        }
    }

