/**
 * A program to analyze the configuration of three points in a 2D plane.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            List<Point> points = readPoints(reader, 3);
            int result = GeometrySolver.solve(points);
            writer.println(result);
        } catch (Exception e) {
            // In a real-world application, use a proper logging framework
            e.printStackTrace();
        } finally {
            writer.flush();
            writer.close();
        }
    }

    private static List<Point> readPoints(FastReader reader, int count) {
        List<Point> points = new ArrayList<>(count);
        for (int i = 0; i < count; i++) {
            points.add(new Point(reader.nextInt(), reader.nextInt()));
        }
        return points;
    }

    /**
     * Represents a point in a 2D coordinate system.
     */
    static final class Point {
        private final int x;
        private final int y;

        public Point(int x, int y) {
            this.x = x;
            this.y = y;
        }

        public int getX() { return x; }
        public int getY() { return y; }
    }

    /**
     * Contains the domain logic for geometric calculations.
     */
    static class GeometrySolver {

        /**
         * Determines the specific configuration value of the given points.
         * 
         * @param points A list of 3 points.
         * @return The calculated result based on point distribution.
         */
        public static int solve(List<Point> points) {
            if (points.size() < 3) return points.size();

            Set<Integer> uniqueX = points.stream().map(Point::getX).collect(Collectors.toSet());
            Set<Integer> uniqueY = points.stream().map(Point::getY).collect(Collectors.toSet());

            int minUniqueCoords = Math.min(uniqueX.size(), uniqueY.size());

            // If the number of unique coordinates on both axes isn't exactly 2,
            // return the minimum count of unique coordinates.
            if (minUniqueCoords != 2) {
                return minUniqueCoords;
            }

            // If we have exactly 2 unique X coordinates, check if they form a vertical segment
            // that contains the third point's Y-level.
            if (uniqueX.size() == 2) {
                return evaluateSegment(points, true);
            } else {
                // Otherwise, check if they form a horizontal segment
                return evaluateSegment(points, false);
            }
        }

        /**
         * Finds two points sharing a coordinate on a specified axis and checks if the
         * third point lies strictly between them on the perpendicular axis.
         *
         * @param points The list of points.
         * @param checkX If true, looks for shared X and checks Y. If false, looks for shared Y and checks X.
         * @return 3 if the third point is "inside" the segment, 2 otherwise.
         */
        private static int evaluateSegment(List<Point> points, boolean checkX) {
            for (int i = 0; i < points.size(); i++) {
                for (int j = i + 1; j < points.size(); j++) {
                    Point p1 = points.get(i);
                    Point p2 = points.get(j);

                    if (checkX && p1.getX() == p2.getX()) {
                        int thirdIndex = findThirdIndex(points.size(), i, j);
                        return isStrictlyBetween(points.get(thirdIndex).getY(), p1.getY(), p2.getY()) ? 3 : 2;
                    } 

                    if (!checkX && p1.getY() == p2.getY()) {
                        int thirdIndex = findThirdIndex(points.size(), i, j);
                        return isStrictlyBetween(points.get(thirdIndex).getX(), p1.getX(), p2.getX()) ? 3 : 2;
                    }
                }
            }
            return 2; // Default fallback
        }

        private static int findThirdIndex(int total, int i, int j) {
            // For 3 points, this finds the index not equal to i or j
            return 3 - i - j - (total == 3 ? 0 : 0); // Simplified for N=3 logic
            // Note: A more robust implementation for N > 3 would be:
            // return IntStream.range(0, total).filter(idx -> idx != i && idx != j).findFirst().getAsInt();
        }

        // Overload for safety in logic
        private static int findThirdIndex(int size, int i, int j) {
            for (int k = 0; k < size; k++) {
                if (k != i && k != j) return k;
            }
            return -1;
        }

        private static boolean isStrictlyBetween(int value, int start, int end) {
            return value > Math.min(start, end) && value < Math.max(start, end);
        }
    }

    /**
     * Fast I/O utility for reading input.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public void close() throws IOException {
            reader.close();
        }
    }
}

