/**
 * Contains the geometric logic to determine the minimum number of segments
 * required to connect three points based on specific axis-aligned rules.
 */
class PointSolver {

    /**
     * Solves the problem for a sorted array of 3 points.
     * 
     * @param points An array of 3 Point objects, sorted by x then y.
     * @return The number of segments (1, 2, or 3).
     */
    public int solve(Point[] points) {
        Point a = points[0];
        Point b = points[1];
        Point c = points[2];

        if (isCollinearOnAxis(a, b, c)) {
            return 1;
        }

        return calculateSegments(a, b, c);
    }

    private boolean isCollinearOnAxis(Point a, Point b, Point c) {
        boolean allSameX = (a.x() == b.x() && b.x() == c.x());
        boolean allSameY = (a.y() == b.y() && b.y() == c.y());
        return allSameX || allSameY;
    }

    /**
     * Re-implemented the original logic using guard clauses to improve readability.
     */
    private int calculateSegments(Point a, Point b, Point c) {
        // Case: Vertical alignment of first two points
        if (a.x() == b.x()) {
            // Since sorted, a.y < b.y is guaranteed. 
            // Check if c.y is strictly between a.y and b.y
            return (c.y() > a.y() && c.y() < b.y()) ? 3 : 2;
        }

        // Case: Horizontal alignment of first two points
        if (a.y() == b.y()) {
            return 2;
        }

        // Case: Descending y-order for the first two points
        if (b.y() < a.y()) {
            if (c.x() == b.x()) {
                return (c.y() <= a.y()) ? 2 : 3;
            }
            return (c.y() == b.y()) ? 2 : 3;
        }

        // Case: Ascending y-order for the first two points (b.y > a.y)
        if (c.x() == b.x() || c.y() == b.y()) {
            return 2;
        }

        return 3;
    }
}

