/**
 * Logic for determining the minimum number of axis-aligned lines 
 * required to cover a set of points based on specific geometric rules.
 */
class LineCoverageSolver {

    private static final int THREE_POINTS = 3;

    /**
     * Calculates the minimum number of lines needed to cover three points.
     * Rules:
     * 1. If all points share the same X or same Y, 1 line is needed.
     * 2. If any two points share an axis and the third point lies outside 
     *    the segment formed by them, 2 lines are needed.
     * 3. Otherwise, 3 lines are needed.
     *
     * @param points An array of exactly 3 points.
     * @return The minimum number of lines (1, 2, or 3).
     */
    public int solve(Point[] points) {
        if (isAllCollinearAxisAligned(points)) {
            return 1;
        }

        if (canCoverWithTwoLines(points)) {
            return 2;
        }

        return 3;
    }

    private boolean isAllCollinearAxisAligned(Point[] pts) {
        boolean allXSame = pts[0].x == pts[1].x && pts[1].x == pts[2].x;
        boolean allYSame = pts[0].y == pts[1].y && pts[1].y == pts[2].y;
        return allXSame || allYSame;
    }

    private boolean canCoverWithTwoLines(Point[] pts) {
        // Check all combinations of pairs (i, j) and the remaining point k
        for (int i = 0; i < THREE_POINTS; i++) {
            for (int j = i + 1; j < THREE_POINTS; j++) {
                int k = findThirdIndex(i, j);
                if (isSpecialPair(pts[i], pts[j], pts[k])) {
                    return true;
                }
            }
        }
        return false;
    }

    private int findThirdIndex(int i, int j) {
        // Since we only have 3 points (0, 1, 2), the sum is always 3
        return 3 - i - j;
    }

    private boolean isSpecialPair(Point p1, Point p2, Point p3) {
        if (p1.x == p2.x) {
            // If pair is vertical, check if p3 is outside the Y-range of the segment
            return p3.y >= Math.max(p1.y, p2.y) || p3.y <= Math.min(p1.y, p2.y);
        }
        if (p1.y == p2.y) {
            // If pair is horizontal, check if p3 is outside the X-range of the segment
            return p3.x >= Math.max(p1.x, p2.x) || p3.x <= Math.min(p1.x, p2.x);
        }
        return false;
    }
}

