/**
 * Solution for Codeforces problem regarding minimum lines to connect three points.
 */
public class CodeforcesD {

    /**
     * Represents a 2D point with integer coordinates.
     */
    static class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        try {
            Point p1 = new Point(reader.nextInt(), reader.nextInt());
            Point p2 = new Point(reader.nextInt(), reader.nextInt());
            Point p3 = new Point(reader.nextInt(), reader.nextInt());

            int result = calculateMinLines(p1, p2, p3);
            System.out.println(result);
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Calculates the minimum number of horizontal or vertical segments 
     * required to connect three points based on their alignment.
     *
     * @param p1 The first point
     * @param p2 The second point
     * @param p3 The third point
     * @return The minimum number of segments (1, 2, or 3)
     */
    public static int calculateMinLines(Point p1, Point p2, Point p3) {
        // Case 1: All points are collinear on a single horizontal or vertical line
        if ((p1.x == p2.x && p2.x == p3.x) || (p1.y == p2.y && p2.y == p3.y)) {
            return 1;
        }

        // Case 2: Check for vertical alignment between any two points
        if (p1.x == p2.x) return isBetween(p3.y, p1.y, p2.y) ? 3 : 2;
        if (p2.x == p3.x) return isBetween(p1.y, p2.y, p3.y) ? 3 : 2;
        if (p1.x == p3.x) return isBetween(p2.y, p1.y, p3.y) ? 3 : 2;

        // Case 3: Check for horizontal alignment between any two points
        if (p1.y == p2.y) return isBetween(p3.x, p1.x, p2.x) ? 3 : 2;
        if (p2.y == p3.y) return isBetween(p1.x, p2.x, p3.x) ? 3 : 2;
        if (p1.y == p3.y) return isBetween(p2.x, p1.x, p3.x) ? 3 : 2;

        // Case 4: Default case for non-aligned points
        return 3;
    }

    /**
     * Helper to check if a value is strictly between two other values.
     */
    private static boolean isBetween(int target, int a, int b) {
        return target > Math.min(a, b) && target < Math.max(a, b);
    }

