/**
 * Contains the geometric logic to determine the minimum segments needed.
 */
class GeometrySolver {

    /**
     * Determines the minimum number of lines (1, 2, or 3) required to 
     * connect three given points based on the original logic.
     */
    public static int solve(Point p1, Point p2, Point p3) {
        // Case 1: All points are on a single horizontal or vertical line
        if (isAllSameX(p1, p2, p3) || isAllSameY(p1, p2, p3)) {
            return 1;
        }

        // Case 2: Check if any two points form an axis-aligned segment 
        // where the third point is not strictly between them.
        if (checkAxisAlignedTwoSegments(p1, p2, p3)) {
            return 2;
        }

        // Case 3: Otherwise, 3 segments are needed.
        return 3;
    }

    private static boolean isAllSameX(Point p1, Point p2, Point p3) {
        return p1.x == p2.x && p2.x == p3.x;
    }

    private static boolean isAllSameY(Point p1, Point p2, Point p3) {
        return p1.y == p2.y && p2.y == p3.y;
    }

    private static boolean checkAxisAlignedTwoSegments(Point p1, Point p2, Point p3) {
        // Vertical alignment checks
        if (p1.x == p2.x && isOutside(p3.y, p1.y, p2.y)) return true;
        if (p1.x == p3.x && isOutside(p2.y, p1.y, p3.y)) return true;
        if (p2.x == p3.x && isOutside(p1.y, p2.y, p3.y)) return true;

        // Horizontal alignment checks
        if (p1.y == p2.y && isOutside(p3.x, p1.x, p2.x)) return true;
        if (p1.y == p3.y && isOutside(p2.x, p1.x, p3.x)) return true;
        if (p2.y == p3.y && isOutside(p1.x, p2.x, p3.x)) return true;

        return false;
    }

    /**
     * Helper to replicate the original logic: checks if a value is 
     * outside the semi-open interval formed by a and b.
     */
    private static boolean isOutside(int val, int a, int b) {
        if (a < b) {
            return val <= a || val >= b;
        } else {
            return val >= a || val <= b;
        }
    }
}

