/**
 * A refactored solution to determine the minimum moves required to align 
 * points based on specific coordinate constraints.
 */
public class CollinearPointsSolver {

    private static final int EXPECTED_POINTS = 3;

    /**
     * Represents a 2D point with integer coordinates.
     */
    private static class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        List<Point> points = new ArrayList<>();

        try {
            for (int i = 0; i < EXPECTED_POINTS; i++) {
                if (scanner.hasNextInt()) {
                    int x = scanner.nextInt();
                    if (scanner.hasNextInt()) {
                        int y = scanner.nextInt();
                        points.add(new Point(x, y));
                    }
                }
            }

            if (points.size() == EXPECTED_POINTS) {
                System.out.println(calculateMinimumMoves(points));
            }
        } finally {
            scanner.close();
        }
    }

    /**
     * Processes the points to determine the result based on coordinate distribution.
     *
     * @param points A list of 3 points.
     * @return The calculated integer result.
     */
    public static int calculateMinimumMoves(List<Point> points) {
        long uniqueXCount = points.stream().map(p -> p.x).distinct().count();
        long uniqueYCount = points.stream().map(p -> p.y).distinct().count();

        // Case 1: All points share the same X or the same Y.
        if (uniqueXCount == 1 || uniqueYCount == 1) {
            return 1;
        }

        // Case 2: Exactly two unique values on both axes.
        if (uniqueXCount == 2 && uniqueYCount == 2) {
            return 2;
        }

        // Case 3: Two unique X values. Evaluate based on the Y distribution.
        if (uniqueXCount == 2) {
            return evaluateAxisAlignment(points, true);
        }

        // Case 4: Two unique Y values. Evaluate based on the X distribution.
        if (uniqueYCount == 2) {
            return evaluateAxisAlignment(points, false);
        }

        // Default case.
        return 3;
    }

    /**
     * Evaluates whether the "lonely" point (the one with the unique coordinate on the target axis)
     * falls within the range of the other two points on the perpendicular axis.
     *
     * @param points    The list of points.
     * @param checkX    True to analyze X-axis alignment (evaluating Y distribution), 
     *                  false to analyze Y-axis alignment (evaluating X distribution).
     * @return 2 if the lonely point is outside the range of the others, otherwise 3.
     */
    private static int evaluateAxisAlignment(List<Point> points, boolean checkX) {
        int lonelyIdx = findLonelyIndex(points, checkX);

        // Identify indices of the two points that share the same coordinate on the target axis.
        int pairIdx1 = (lonelyIdx + 1) % EXPECTED_POINTS;
        int pairIdx2 = (lonelyIdx + 2) % EXPECTED_POINTS;

        // Determine the values on the perpendicular axis.
        int val1 = checkX ? points.get(pairIdx1).y : points.get(pairIdx1).x;
        int val2 = checkX ? points.get(pairIdx2).y : points.get(pairIdx2).x;
        int lonelyVal = checkX ? points.get(lonelyIdx).y : points.get(lonelyIdx).x;

        int rangeMin = Math.min(val1, val2);
        int rangeMax = Math.max(val1, val2);

        // If the lonely point is outside the range (inclusive) of the pair, return 2.
        return (lonelyVal <= rangeMin || lonelyVal >= rangeMax) ? 2 : 3;
    }

    /**
     * Finds the index of the point that possesses a unique coordinate on the specified axis.
     */
    private static int findLonelyIndex(List<Point> points, boolean checkX) {
        if (checkX) {
            if (points.get(0).x == points.get(1).x) return 2;
            if (points.get(1).x == points.get(2).x) return 0;
            return 1;
        } else {
            if (points.get(0).y == points.get(1).y) return 2;
            if (points.get(1).y == points.get(2).y) return 0;
            return 1;
        }
    }
}

