/**
 * Represents a 2D coordinate.
 */
class Point {
    final int x;
    final int y;

    Point(int x, int y) {
        this.x = x;
        this.y = y;
    }
}

/**
 * Contains the core logic for solving the coordinate alignment problem.
 */
class Solver {

    /**
     * Solves the problem based on the input points.
     * 
     * @param reader The input reader to fetch points.
     * @return The calculated result (1, 2, or 3).
     */
    public int solve(FastReader reader) {
        Point[] points = new Point[3];
        for (int i = 0; i < 3; i++) {
            points[i] = new Point(reader.nextInt(), reader.nextInt());
        }

        // Case 1: All points are aligned on a single horizontal or vertical line.
        if (areAllXSame(points) || areAllYSame(points)) {
            return 1;
        }

        // Case 2 & 3: Check if any two points share an axis.
        // We check X-axis matches first, then Y-axis matches, to preserve original logic flow.

        // Check X-axis matches (Vertical alignment of pairs)
        for (int i = 0; i < 3; i++) {
            for (int j = i + 1; j < 3; j++) {
                if (points[i].x == points[j].x) {
                    int thirdIdx = getThirdIndex(i, j);
                    // If the third point's Y is strictly between the others, return 3, else 2.
                    return isStrictlyBetween(points[thirdIdx].y, points[i].y, points[j].y) ? 3 : 2;
                }
            }
        }

        // Check Y-axis matches (Horizontal alignment of pairs)
        for (int i = 0; i < 3; i++) {
            for (int j = i + 1; j < 3; j++) {
                if (points[i].y == points[j].y) {
                    int thirdIdx = getThirdIndex(i, j);
                    // If the third point's X is strictly between the others, return 3, else 2.
                    return isStrictlyBetween(points[thirdIdx].x, points[i].x, points[j].x) ? 3 : 2;
                }
            }
        }

        // Default Case: No two points share an axis.
        return 3;
    }

    private boolean areAllXSame(Point[] points) {
        return points[0].x == points[1].x && points[1].x == points[2].x;
    }

    private boolean areAllYSame(Point[] points) {
        return points[0].y == points[1].y && points[1].y == points[2].y;
    }

    /**
     * Determines if the 'target' value lies strictly between 'a' and 'b'.
     * Uses long to prevent integer overflow during multiplication.
     */
    private boolean isStrictlyBetween(int target, int a, int b) {
        return (long) (a - target) * (target - b) > 0;
    }

    /**
     * Returns the index of the point that is not i or j.
     */
    private int getThirdIndex(int i, int j) {
        for (int idx = 0; idx < 3; idx++) {
            if (idx != i && idx != j) {
                return idx;
            }
        }
        return -1; // Should not be reachable
    }
}

/**
 * A fast and maintainable input reader for reading primitives and strings.
 */
class FastReader {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    public FastReader(InputStream inputStream) {
        reader = new BufferedReader(new InputStreamReader(inputStream));
    }

    public String next() {
        while (tokenizer == null || !tokenizer.hasMoreElements()) {
            try {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                return null;
            }
        }
        return tokenizer.nextToken();
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }
}

import java.util.*;

/**
 * A solution to determine the relationship between three 2D points.
 * The result represents a classification based on coordinate distribution.
 */
public class ProblemD2 {

    /**
     * Represents a point in 2D space.
     */
    public record Point(int x, int y) {}

    /**
     * Core logic class to handle the computation.
     */
    public static class Solution {

        /**
         * Computes the result based on the coordinates of the provided points.
         * 
         * @param points A list of 3 points.
         * @return An integer result (1, 2, or 3) based on coordinate distribution.
         */
        public int solve(List<Point> points) {
            Map<Integer, Integer> xCounts = countOccurrences(points, true);
            Map<Integer, Integer> yCounts = countOccurrences(points, false);

            // Case 1: All points are collinear on a single horizontal or vertical line.
            if (xCounts.size() == 1 || yCounts.size() == 1) {
                return 1;
            }

            // Case 2: Two unique X-coordinates.
            // Note: If both X and Y have 2 unique values, the original logic prioritizes X.
            if (xCounts.size() == 2) {
                return calculateResultForTwoDimensions(points, xCounts, true);
            }

            // Case 3: Two unique Y-coordinates.
            if (yCounts.size() == 2) {
                return calculateResultForTwoDimensions(points, yCounts, false);
            }

            // Case 4: General case (e.g., 3 unique X and 3 unique Y).
            return 3;
        }

        /**
         * Counts how many times each coordinate appears in a specific dimension.
         */
        private Map<Integer, Integer> countOccurrences(List<Point> points, boolean isXDimension) {
            Map<Integer, Integer> counts = new HashMap<>();
            for (Point p : points) {
                int coord = isXDimension ? p.x : p.y;
                counts.merge(coord, 1, Integer::sum);
            }
            return counts;
        }

        /**
         * Evaluates the relationship when one dimension has exactly two unique values.
         * It checks if the 'singleton' point's other coordinate is sandwiched between 
         * the other two points.
         */
        private int calculateResultForTwoDimensions(List<Point> points, Map<Integer, Integer> counts, boolean isXDimension) {
            // Identify the coordinate value that appears exactly once.
            int uniqueCoordValue = counts.entrySet().stream()
                    .filter(entry -> entry.getValue() == 1)
                    .map(Map.Entry::getKey)
                    .findFirst()
                    .orElseThrow(() -> new IllegalStateException("Expected exactly one unique coordinate value with frequency 1"));

            int singletonOtherCoord = 0;
            List<Integer> otherDimensionCoords = new ArrayList<>();

            for (Point p : points) {
                int currentDimCoord = isXDimension ? p.x : p.y;
                int otherDimCoord = isXDimension ? p.y : p.x;

                if (currentDimCoord == uniqueCoordValue) {
                    singletonOtherCoord = otherDimCoord;
                } else {
                    otherDimensionCoords.add(otherDimCoord);
                }
            }

            // Sort or find min/max of the other two coordinates in the perpendicular dimension.
            int minOther = Math.min(otherDimensionCoords.get(0), otherDimensionCoords.get(1));
            int maxOther = Math.max(otherDimensionCoords.get(0), otherDimensionCoords.get(1));

            // If the unique point's perpendicular coordinate is outside the range of the others, return 2, else 3.
            if (singletonOtherCoord <= minOther || singletonOtherCoord >= maxOther) {
                return 2;
            } else {
                return 3;
            }
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        List<Point> points = new ArrayList<>();

        try {
            // Read 3 points from input.
            for (int i = 0; i < 3; i++) {
                if (scanner.hasNextInt()) {
                    int x = scanner.nextInt();
                    int y = scanner.nextInt();
                    points.add(new Point(x, y));
                }
            }

            if (points.size() == 3) {
                Solution solution = new Solution();
                System.out.println(solution.solve(points));
            }
        } catch (Exception e) {
            // In a production environment, use a proper logging framework.
            System.err.println("Error reading input: " + e.getMessage());
        } finally {
            scanner.close();
        }
    }
}

import java.util.*;
import java.io.*;
import java.util.function.ToLongFunction;

/**
 * A solver for geometric problems involving the minimum number of lines 
 * required to connect a set of points.
 */
public class GeometrySolver {

    /**
     * Represents a 2D point with long coordinates.
     */
    private static class Point {
        final long x;
        final long y;

        Point(long x, long y) {
            this.x = x;
            this.y = y;
        }
    }

    public static void main(String[] args) {
        try {
            new GeometrySolver().run();
        } catch (IOException e) {
            System.err.println("An error occurred while reading input: " + e.getMessage());
        }
    }

    /**
     * Orchestrates the reading of input and printing of the result.
     */
    public void run() throws IOException {
        FastReader reader = new FastReader(System.in);

        // The problem specifies 3 points
        final int numPoints = 3;
        Point[] points = new Point[numPoints];

        for (int i = 0; i < numPoints; i++) {
            long x = reader.nextLong();
            long y = reader.nextLong();
            points[i] = new Point(x, y);
        }

        int result = calculateMinimumLines(points);
        System.out.println(result);
    }

    /**
     * Determines the minimum number of lines required based on the 
     * geometric arrangement of the provided points.
     * 
     * @param points An array of Point objects.
     * @return The result representing the number of lines.
     */
    private int calculateMinimumLines(Point[] points) {
        // Case 1: All points are collinear on a single horizontal or vertical line.
        if (allCoordinatesSame(points, p -> p.x) || allCoordinatesSame(points, p -> p.y)) {
            return 1;
        }

        int n = points.length;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                int k = findThirdIndex(i, j, n);

                // Case 2: Two points share the same X coordinate (Vertical alignment)
                if (points[i].x == points[j].x) {
                    return isValueBetween(points[i].y, points[j].y, points[k].y) ? 3 : 2;
                }

                // Case 3: Two points share the same Y coordinate (Horizontal alignment)
                if (points[i].y == points[j].y) {
                    return isValueBetween(points[i].x, points[j].x, points[k].x) ? 3 : 2;
                }
            }
        }

        // Case 4: No two points share an axis, forming a triangle.
        return 3;
    }

    /**
     * Checks if a specific coordinate (X or Y) is the same for all points.
     */
    private boolean allCoordinatesSame(Point[] points, ToLongFunction<Point> coordinateExtractor) {
        long firstValue = coordinateExtractor.applyAsLong(points[0]);
        for (int i = 1; i < points.length; i++) {
            if (coordinateExtractor.applyAsLong(points[i]) != firstValue) {
                return false;
            }
        }
        return true;
    }

    /**
     * Finds the index of the point that is not i or j.
     */
    private int findThirdIndex(int i, int j, int n) {
        for (int idx = 0; idx < n; idx++) {
            if (idx != i && idx != j) {
                return idx;
            }
        }
        return -1;
    }

    /**
     * Returns true if the target value lies strictly between val1 and val2.
     */
    private boolean isValueBetween(long val1, long val2, long target) {
        return target > Math.min(val1, val2) && target < Math.max(val1, val2);
    }

    /**
     * A utility class for efficient input reading.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public long nextLong() throws IOException {
            String next = next();
            return (next == null) ? 0L : Long.parseLong(next);
        }
    }
}

