/**
 * Represents an immutable 2D coordinate.
 */
record Point(int x, int y) {}

/**
 * Service responsible for geometric calculations regarding line configurations.
 */
class LineCalculator {

    /**
     * Calculates the minimum number of lines (1, 2, or 3) based on 
     * horizontal and vertical alignments.
     *
     * @param p1 The first point.
     * @param p2 The second point.
     * @param p3 The third point.
     * @return 1 if all points are on a single horizontal or vertical line,
     *         2 if they form a specific corner/extension pattern,
     *         3 otherwise.
     */
    public int calculateMinimumLines(Point p1, Point p2, Point p3) {
        if (isFullyCollinear(p1, p2, p3)) {
            return 1;
        }

        if (isTwoLineConfiguration(p1, p2, p3)) {
            return 2;
        }

        return 3;
    }

    private boolean isFullyCollinear(Point p1, Point p2, Point p3) {
        return isAllXSame(p1, p2, p3) || isAllYSame(p1, p2, p3);
    }

    private boolean isAllXSame(Point p1, Point p2, Point p3) {
        return p1.x() == p2.x() && p2.x() == p3.x();
    }

    private boolean isAllYSame(Point p1, Point p2, Point p3) {
        return p1.y() == p2.y() && p2.y() == p3.y();
    }

    /**
     * Checks if any two points form a vertical/horizontal segment where 
     * the third point extends the range of that segment.
     */
    private boolean isTwoLineConfiguration(Point p1, Point p2, Point p3) {
        return isVerticalSegmentExtending(p1, p2, p3) ||
               isVerticalSegmentExtending(p1, p3, p2) ||
               isVerticalSegmentExtending(p2, p3, p1) ||
               isHorizontalSegmentExtending(p1, p2, p3) ||
               isHorizontalSegmentExtending(p1, p3, p2) ||
               isHorizontalSegmentExtending(p2, p3, p1);
    }

    /**
     * Returns true if 'a' and 'b' share an X-coordinate and 'third' 
     * is outside the Y-range of 'a' and 'b'.
     */
    private boolean isVerticalSegmentExtending(Point a, Point b, Point third) {
        boolean sharedX = (a.x() == b.x());
        boolean outsideYRange = (third.y() >= Math.max(a.y(), b.y()) || 
                                 third.y() <= Math.min(a.y(), b.y()));
        return sharedX && outsideYRange;
    }

    /**
     * Returns true if 'a' and 'b' share a Y-coordinate and 'third' 
     * is outside the X-range of 'a' and 'b'.
     */
    private boolean isHorizontalSegmentExtending(Point a, Point b, Point third) {
        boolean sharedY = (a.y() == b.y());
        boolean outsideXRange = (third.x() >= Math.max(a.x(), b.x()) || 
                                 third.x() <= Math.min(a.x(), b.x()));
        return sharedY && outsideXRange;
    }
}

import java.util.Scanner;

/**
 * Refactored solution for AimTech Task C.
 * The goal is to partition nodes into three types (a, b, c) such that:
 * - Type 'b' nodes are connected to all other nodes.
 * - Type 'a' and 'c' nodes have no edges between them.
 * - All other pairs (a-a, a-b, b-b, b-c, c-c) must have edges.
 */
public class AimTech_Task_C {

    private enum NodeType {
        A('a'), B('b'), C('c');

        private final char label;

        NodeType(char label) {
            this.label = label;
        }

        public char getLabel() {
            return label;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int n = scanner.nextInt();
        int m = scanner.nextInt();

        // Edge case: single node
        if (n == 1) {
            printResult(true, new NodeType[]{NodeType.A});
            return;
        }

        boolean[][] adjacencyMatrix = buildAdjacencyMatrix(n, m, scanner);
        NodeType[] nodeTypes = classifyNodes(n, adjacencyMatrix);

        if (validatePartition(n, adjacencyMatrix, nodeTypes)) {
            printResult(true, nodeTypes);
        } else {
            printResult(false, null);
        }

        scanner.close();
    }

    /**
     * Reads edge input and constructs an adjacency matrix.
     */
    private static boolean[][] buildAdjacencyMatrix(int n, int m, Scanner scanner) {
        boolean[][] adj = new boolean[n][n];
        for (int i = 0; i < m; i++) {
            int u = scanner.nextInt() - 1;
            int v = scanner.nextInt() - 1;
            if (u >= 0 && u < n && v >= 0 && v < n) {
                adj[u][v] = true;
                adj[v][u] = true;
            }
        }
        return adj;
    }

    /**
     * Classifies each node into NodeType A, B, or C based on connectivity.
     */
    private static NodeType[] classifyNodes(int n, boolean[][] adj) {
        NodeType[] types = new NodeType[n];
        boolean[] isTypeB = new boolean[n];

        // Step 1: Identify Type B nodes (connected to every other node)
        for (int i = 0; i < n; i++) {
            boolean connectedToAll = true;
            for (int j = 0; j < n; j++) {
                if (i != j && !adj[i][j]) {
                    connectedToAll = false;
                    break;
                }
            }
            if (connectedToAll) {
                isTypeB[i] = true;
                types[i] = NodeType.B;
            }
        }

        // Step 2: Identify the first node that is not Type B to act as a seed for A/C partitioning
        int firstNonBIndex = -1;
        for (int i = 0; i < n; i++) {
            if (!isTypeB[i]) {
                firstNonBIndex = i;
                break;
            }
        }

        // Step 3: Distribute remaining nodes into Type A or Type C
        if (firstNonBIndex != -1) {
            for (int i = 0; i < n; i++) {
                if (isTypeB[i]) continue;

                if (i == firstNonBIndex || adj[firstNonBIndex][i]) {
                    types[i] = NodeType.A;
                } else {
                    types[i] = NodeType.C;
                }
            }
        }

        return types;
    }

    /**
     * Validates if the current node types follow the structural requirements of the graph.
     */
    private static boolean validatePartition(int n, boolean[][] adj, NodeType[] types) {
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                NodeType t1 = types[i];
                NodeType t2 = types[j];

                // Rule logic:
                // 1. A-C pairs must NOT have an edge.
                // 2. All other pairs MUST have an edge.
                boolean isACPair = (t1 == NodeType.A && t2 == NodeType.C) || 
                                   (t1 == NodeType.C && t2 == NodeType.A);

                if (isACPair) {
                    if (adj[i][j]) return false; // Forbidden edge found
                } else {
                    if (!adj[i][j]) return false; // Missing required edge found
                }
            }
        }
        return true;
    }

    /**
     * Handles standard output formatting.
     */
    private static void printResult(boolean success, NodeType[] types) {
        if (!success) {
            System.out.println("No");
        } else {
            System.out.println("Yes");
            StringBuilder sb = new StringBuilder();
            for (NodeType type : types) {
                sb.append(type.getLabel());
            }
            System.out.println(sb.toString());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver for the graph partitioning problem.
 * The goal is to partition vertices into three types (0, 1, 2) such that:
 * - Type 1 nodes are connected to all other nodes.
 * - Type 0 and Type 2 nodes have no edges between them.
 * - Certain edge/non-edge constraints are met based on vertex types.
 */
public class Main {

    public static void main(String[] args) {
        try {
            FastReader reader = new FastReader(System.in);
            PrintWriter out = new PrintWriter(System.out);

            GraphProblemSolver solver = new GraphProblemSolver(reader);
            solver.solve(out);

            out.flush();
            out.close();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * Core logic for solving the graph problem.
     */
    static class GraphProblemSolver {
        private final FastReader reader;

        private static final int TYPE_ZERO = 0;
        private static final int TYPE_ONE = 1;
        private static final int TYPE_TWO = 2;
        private static final int UNASSIGNED = -1;

        public GraphProblemSolver(FastReader reader) {
            this.reader = reader;
        }

        public void solve(PrintWriter out) throws IOException {
            int vertexCount = reader.nextInt();
            int edgeCount = reader.nextInt();

            if (vertexCount == 0) {
                out.println("Yes");
                return;
            }

            boolean[][] isAdjacent = new boolean[vertexCount][vertexCount];
            int[] degrees = new int[vertexCount];

            // 1. Build the graph
            for (int i = 0; i < edgeCount; i++) {
                int u = reader.nextInt() - 1; // Convert to 0-based indexing
                int v = reader.nextInt() - 1;
                if (u >= 0 && u < vertexCount && v >= 0 && v < vertexCount) {
                    if (!isAdjacent[u][v]) {
                        isAdjacent[u][v] = isAdjacent[v][u] = true;
                        degrees[u]++;
                        degrees[v]++;
                    }
                }
            }

            int[] vertexTypes = new int[vertexCount];
            Arrays.fill(vertexTypes, UNASSIGNED);

            // 2. Identify central nodes (Type 1)
            for (int i = 0; i < vertexCount; i++) {
                if (degrees[i] == vertexCount - 1) {
                    vertexTypes[i] = TYPE_ONE;
                }
            }

            // 3. Assign Type 0 and Type 2 based on non-adjacency
            for (int i = 0; i < vertexCount; i++) {
                if (vertexTypes[i] != UNASSIGNED) {
                    continue;
                }

                // Assume this node is Type 0
                vertexTypes[i] = TYPE_ZERO;

                for (int j = i + 1; j < vertexCount; j++) {
                    if (!isAdjacent[i][j]) {
                        if (vertexTypes[j] == UNASSIGNED) {
                            vertexTypes[j] = TYPE_TWO;
                        } else if (vertexTypes[j] != TYPE_TWO) {
                            // Conflict: Node was already assigned Type 0 or Type 1
                            out.println("No");
                            return;
                        }
                    }
                }
            }

            // 4. Validate the complete graph configuration
            for (int i = 0; i < vertexCount; i++) {
                for (int j = i + 1; j < vertexCount; j++) {
                    int typeDiff = Math.abs(vertexTypes[i] - vertexTypes[j]);

                    if (isAdjacent[i][j]) {
                        // Rule: Edges must connect nodes with type difference <= 1
                        if (typeDiff > 1) {
                            out.println("No");
                            return;
                        }
                    } else {
                        // Rule: Non-edges must connect nodes with type difference == 2
                        if (typeDiff != 2) {
                            out.println("No");
                            return;
                        }
                    }
                }
            }

            // 5. Output Result
            out.println("Yes");
            StringBuilder result = new StringBuilder();
            for (int i = 0; i < vertexCount; i++) {
                result.append((char) ('a' + vertexTypes[i]));
            }
            out.println(result.toString());
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
