import java.util.*;

/**
 * GraphAnalyzer identifies specific coloring patterns in a graph.
 * It determines if a graph can be partitioned into specific sets 
 * based on node degrees and adjacency.
 */
public class GraphAnalyzer {

    private static final char COLOR_A = 'a';
    private static final char COLOR_B = 'b';
    private static final char COLOR_C = 'c';
    private static final char UNASSIGNED = 'x';

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int nodeCount = scanner.nextInt();
            int edgeCount = scanner.nextInt();

            List<List<Integer>> adjacencyList = new ArrayList<>(nodeCount);
            boolean[][] adjacencyMatrix = new boolean[nodeCount][nodeCount];

            for (int i = 0; i < nodeCount; i++) {
                adjacencyList.add(new ArrayList<>());
            }

            for (int i = 0; i < edgeCount; i++) {
                int u = scanner.nextInt() - 1; // Convert to 0-based index
                int v = scanner.nextInt() - 1;

                if (isValidIndex(u, nodeCount) && isValidIndex(v, nodeCount)) {
                    adjacencyList.get(u).add(v);
                    adjacencyList.get(v).add(u);
                    adjacencyMatrix[u][v] = true;
                    adjacencyMatrix[v][u] = true;
                }
            }

            char[] nodeColors = computeNodeColors(nodeCount, adjacencyList);
            boolean isInvalid = isColoringInvalid(nodeCount, adjacencyMatrix, nodeColors);

            printResult(isInvalid, nodeColors);
        }
    }

    /**
     * Assigns colors to nodes based on their degrees and connections.
     * Nodes with degree (n-1) are assigned 'b'. 
     * Others are partitioned into 'a' and 'c'.
     */
    private static char[] computeNodeColors(int n, List<List<Integer>> adjacencyList) {
        char[] colors = new char[n];
        Arrays.fill(colors, UNASSIGNED);

        // Assign 'b' to universal nodes (connected to everyone else)
        for (int i = 0; i < n; i++) {
            if (adjacencyList.get(i).size() == n - 1) {
                colors[i] = COLOR_B;
            }
        }

        // Find the first non-universal node to start partitioning
        int firstNonUniversal = -1;
        for (int i = 0; i < n; i++) {
            if (colors[i] == UNASSIGNED) {
                firstNonUniversal = i;
                break;
            }
        }

        // If we found a non-universal node, partition remaining nodes into 'a' and 'c'
        if (firstNonUniversal != -1) {
            colors[firstNonUniversal] = COLOR_A;
            for (int neighbor : adjacencyList.get(firstNonUniversal)) {
                if (colors[neighbor] == UNASSIGNED) {
                    colors[neighbor] = COLOR_A;
                }
            }
            for (int i = 0; i < n; i++) {
                if (colors[i] == UNASSIGNED) {
                    colors[i] = COLOR_C;
                }
            }
        }

        return colors;
    }

    /**
     * Validates the assigned coloring against the adjacency matrix.
     * Replicates the specific logical requirements of the original implementation.
     */
    private static boolean isColoringInvalid(int n, boolean[][] matrix, char[] colors) {
        for (int i = 0; i < n; i++) {
            // Original logic only checks validation for nodes that are not color 'b'
            if (colors[i] == COLOR_B) {
                continue;
            }

            for (int j = 0; j < n; j++) {
                if (i == j) {
                    continue;
                }

                if (matrix[i][j]) {
                    // If an edge exists, check if colors are different and target is not 'b'
                    if (colors[i] != colors[j] && colors[j] != COLOR_B) {
                        return true;
                    }
                } else {
                    // If no edge exists, check if colors are the same or target is 'b'
                    if (colors[j] == colors[i] || colors[j] == COLOR_B) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    private static void printResult(boolean isInvalid, char[] colors) {
        if (isInvalid) {
            System.out.println("No");
        } else {
            System.out.println("Yes");
            System.out.println(new String(colors));
        }
    }

    private static boolean isValidIndex(int index, int limit) {
        return index >= 0 && index < limit;
    }
}

import java.io.*;
import java.util.*;

/**
 * A service to solve the graph coloring problem based on the complement graph.
 * The goal is to assign colors 'a', 'b', or 'c' such that:
 * 1. Nodes connected in the complement graph have different colors ('a' and 'c').
 * 2. Nodes connected in the original graph do not have the color combination {'a', 'c'}.
 */
public class GraphColoringProblem {

    private static final char COLOR_A = 'a';
    private static final char COLOR_C = 'c';
    private static final char COLOR_B = 'b';
    private static final char UNCOLORED = '\u0000';

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        GraphColoringService service = new GraphColoringService();
        service.execute(reader, writer);

        writer.close();
    }

    static class GraphColoringService {
        private int nodeCount;
        private int edgeCount;
        private boolean[][] adjacencyMatrix;
        private char[] nodeColors;

        /**
         * Orchestrates the reading of input and the execution of the coloring logic.
         */
        public void execute(FastReader reader, PrintWriter writer) {
            nodeCount = reader.nextInt();
            edgeCount = reader.nextInt();

            initializeGraph();
            readEdges(reader);

            String result = findValidColoring();

            if (result == null) {
                writer.println("No");
            } else {
                writer.println("Yes");
                writer.println(result);
            }
        }

        private void initializeGraph() {
            // Using 1-based indexing to match input format
            adjacencyMatrix = new boolean[nodeCount + 1][nodeCount + 1];
            nodeColors = new char[nodeCount + 1];
        }

        private void readEdges(FastReader reader) {
            for (int i = 0; i < edgeCount; i++) {
                int u = reader.nextInt();
                int v = reader.nextInt();
                adjacencyMatrix[u][v] = adjacencyMatrix[v][u] = true;
            }
        }

        /**
         * Primary logic to determine if a valid coloring exists.
         * @return The colored string if valid, otherwise null.
         */
        private String findValidColoring() {
            if (!assignColorsToComplementComponents()) {
                return null;
            }

            assignDefaultColorsToIsolatedNodes();

            if (!isColoringValid()) {
                return null;
            }

            return formatResult();
        }

        /**
         * Performs a BFS on the complement graph to assign 'a' and 'c' colors.
         * A complement graph edge exists between u and v if adjacencyMatrix[u][v] is false.
         */
        private boolean assignColorsToComplementComponents() {
            Queue<Integer> queue = new LinkedList<>();

            for (int i = 1; i <= nodeCount; i++) {
                if (isIsolatedInComplementGraph(i)) {
                    continue;
                }

                // If node is not yet colored, it's a new component in the complement graph
                if (nodeColors[i] == UNCOLORED) {
                    nodeColors[i] = COLOR_A;
                    queue.add(i);

                    while (!queue.isEmpty()) {
                        int currentNode = queue.poll();

                        for (int nextNode = 1; nextNode <= nodeCount; nextNode++) {
                            if (currentNode == nextNode || adjacencyMatrix[currentNode][nextNode]) {
                                continue; // This is an edge in the original graph, not the complement
                            }

                            // If color conflict occurs in the complement graph, it's not bipartite
                            if (nodeColors[nextNode] == nodeColors[currentNode]) {
                                return false;
                            }

                            if (nodeColors[nextNode] == UNCOLORED) {
                                nodeColors[nextNode] = (nodeColors[currentNode] == COLOR_A) ? COLOR_C : COLOR_A;
                                queue.add(nextNode);
                            }
                        }
                    }
                }
            }
            return true;
        }

        private boolean isIsolatedInComplementGraph(int node) {
            for (int j = 1; j <= nodeCount; j++) {
                if (node != j && !adjacencyMatrix[node][j]) {
                    return false;
                }
            }
            return true;
        }

        private void assignDefaultColorsToIsolatedNodes() {
            for (int i = 1; i <= nodeCount; i++) {
                if (nodeColors[i] == UNCOLORED) {
                    nodeColors[i] = COLOR_B;
                }
            }
        }

        /**
         * Validates that no edge in the original graph connects an 'a' node to a 'c' node.
         */
        private boolean isColoringValid() {
            for (int i = 1; i <= nodeCount; i++) {
                for (int j = i + 1; j <= nodeCount; j++) {
                    if (adjacencyMatrix[i][j]) {
                        if (isForbiddenCombination(nodeColors[i], nodeColors[j])) {
                            return false;
                        }
                    }
                }
            }
            return true;
        }

        private boolean isForbiddenCombination(char c1, char c2) {
            return (c1 == COLOR_A && c2 == COLOR_C) || (c1 == COLOR_C && c2 == COLOR_A);
        }

        private String formatResult() {
            StringBuilder sb = new StringBuilder();
            for (int i = 1; i <= nodeCount; i++) {
                sb.append(nodeColors[i]);
            }
            return sb.toString();
        }
    }

    /**
     * Fast I/O utility for reading input streams.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Queue;
import java.util.StringTokenizer;

/**
 * A solver for a graph coloring problem where:
 * 1. Non-edges (complement graph) must be bipartite (using colors 1 and 3).
 * 2. Edges in the original graph must not connect nodes with colors differing by 2.
 */
public class GraphColoringSolver {

    private static final int COLOR_NONE = 0;
    private static final int COLOR_A = 1;
    private static final int COLOR_B = 2;
    private static final int COLOR_C = 3;

    private final int numNodes;
    private final boolean[][] adjacencyMatrix;
    private final int[] nodeColors;

    public GraphColoringSolver(int numNodes, boolean[][] adjacencyMatrix) {
        this.numNodes = numNodes;
        this.adjacencyMatrix = adjacencyMatrix;
        this.nodeColors = new int[numNodes];
    }

    /**
     * Executes the two-phase coloring and validation logic.
     * 
     * @return A string containing the coloring ('a', 'b', 'c'...) or "No" if impossible.
     */
    public String solve() {
        if (!colorComplementGraph()) {
            return "No";
        }

        if (!colorAndValidateOriginalGraph()) {
            return "No";
        }

        return formatResult();
    }

    /**
     * Phase 1: Color the complement graph using colors 1 and 3.
     * The complement graph must be bipartite.
     */
    private boolean colorComplementGraph() {
        boolean[] visited = new boolean[numNodes];

        for (int i = 0; i < numNodes; i++) {
            if (visited[i]) continue;

            // Check if node i has any connections in the complement graph
            if (hasComplementEdges(i)) {
                if (!bfsColorComplement(i, visited)) {
                    return false;
                }
            }
        }
        return true;
    }

    private boolean hasComplementEdges(int u) {
        for (int v = 0; v < numNodes; v++) {
            if (u != v && !adjacencyMatrix[u][v]) {
                return true;
            }
        }
        return false;
    }

    private boolean bfsColorComplement(int startNode, boolean[] visited) {
        Queue<Integer> queue = new ArrayDeque<>();

        nodeColors[startNode] = COLOR_A;
        visited[startNode] = true;
        queue.add(startNode);

        while (!queue.isEmpty()) {
            int u = queue.poll();

            for (int v = 0; v < numNodes; v++) {
                // If there is a non-edge in the original graph, it's an edge in the complement
                if (u != v && !adjacencyMatrix[u][v]) {
                    int expectedColor = 4 - nodeColors[u]; // Alternates between 1 and 3

                    if (!visited[v]) {
                        visited[v] = true;
                        nodeColors[v] = expectedColor;
                        queue.add(v);
                    } else if (nodeColors[v] != expectedColor) {
                        return false; // Not bipartite in complement graph
                    }
                }
            }
        }
        return true;
    }

    /**
     * Phase 2: Assign color 2 to nodes not touched in Phase 1, 
     * then validate that no original edges connect colors with a difference of 2.
     */
    private boolean colorAndValidateOriginalGraph() {
        boolean[] visited = new boolean[numNodes];

        // Assign color 2 to all remaining uncolored nodes
        for (int i = 0; i < numNodes; i++) {
            if (nodeColors[i] == COLOR_NONE) {
                nodeColors[i] = COLOR_B;
            }
        }

        for (int i = 0; i < numNodes; i++) {
            if (visited[i]) continue;

            Queue<Integer> queue = new ArrayDeque<>();
            visited[i] = true;
            queue.add(i);

            while (!queue.isEmpty()) {
                int u = queue.poll();

                for (int v = 0; v < numNodes; v++) {
                    if (u != v && adjacencyMatrix[u][v]) {
                        // If an edge exists, colors cannot be (1,3) or (3,1)
                        if (Math.abs(nodeColors[u] - nodeColors[v]) == 2) {
                            return false;
                        }

                        if (!visited[v]) {
                            visited[v] = true;
                            queue.add(v);
                        }
                    }
                }
            }
        }
        return true;
    }

    private String formatResult() {
        StringBuilder sb = new StringBuilder("Yes\n");
        for (int color : nodeColors) {
            sb.append((char) ('a' + color - 1));
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        try {
            FastReader reader = new FastReader(System.in);
            int n = reader.nextInt();
            int m = reader.nextInt();

            boolean[][] adj = new boolean[n][n];
            for (int i = 0; i < m; i++) {
                int u = reader.nextInt() - 1;
                int v = reader.nextInt() - 1;
                adj[u][v] = true;
                adj[v][u] = true;
            }

            GraphColoringSolver solver = new GraphColoringSolver(n, adj);
            System.out.println(solver.solve());

        } catch (Exception e) {
            // In a competitive programming context, we usually ignore or print nothing
        }
    }

    /**
     * Fast I/O utility for efficient reading of large input.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(java.io.InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Analyzes a graph to see if it follows a specific structural pattern:
 * A partition into three sets (A, B, C) where:
 * - Set B contains nodes connected to all other nodes in the graph.
 * - Sets A and C are cliques (completely connected subgraphs).
 * - There are no edges between Set A and Set C.
 */
public class GraphStructureAnalyzer {

    // Constants for node classifications
    private static final int TYPE_A = 0;
    private static final int TYPE_B = 1;
    private static final int TYPE_C = 2;
    private static final int UNASSIGNED = -1;

    private final int numNodes;
    private final boolean[][] adjacencyMatrix;
    private final int[] degrees;
    private final int[] nodeTypes;
    private boolean isValidStructure = true;

    public GraphStructureAnalyzer(int n, int m, FastReader reader) {
        this.numNodes = n;
        this.adjacencyMatrix = new boolean[n][n];
        this.degrees = new int[n];
        this.nodeTypes = new int[n];
        Arrays.fill(nodeTypes, UNASSIGNED);

        buildGraph(m, reader);
        calculateDegrees();
    }

    private void buildGraph(int m, FastReader reader) {
        for (int i = 0; i < m; i++) {
            int u = reader.nextInt() - 1;
            int v = reader.nextInt() - 1;
            if (u >= 0 && u < numNodes && v >= 0 && v < numNodes) {
                adjacencyMatrix[u][v] = adjacencyMatrix[v][u] = true;
            }
        }
    }

    private void calculateDegrees() {
        for (int i = 0; i < numNodes; i++) {
            for (int j = 0; j < numNodes; j++) {
                if (adjacencyMatrix[i][j]) {
                    degrees[i]++;
                }
            }
        }
    }

    /**
     * Orchestrates the logic to identify node types and validate the structure.
     */
    public void solve(PrintWriter writer) {
        identifyUniversalNodes();
        assignComponentType(TYPE_A);
        assignComponentType(TYPE_C);
        validateAllNodesAssigned();

        printResult(writer);
    }

    /**
     * Nodes connected to everyone else are Type B.
     */
    private void identifyUniversalNodes() {
        for (int i = 0; i < numNodes; i++) {
            if (degrees[i] == numNodes - 1) {
                nodeTypes[i] = TYPE_B;
            }
        }
    }

    /**
     * Identifies a component of unassigned nodes and attempts to assign them a specific type.
     * This follows the original logic of finding the first unassigned cluster and validating its structure.
     */
    private void assignComponentType(int targetType) {
        for (int i = 0; i < numNodes; i++) {
            if (nodeTypes[i] == UNASSIGNED) {
                boolean[] componentMask = identifyComponent(i);

                for (int j = 0; j < numNodes; j++) {
                    if (componentMask[j]) {
                        verifyComponentConnectivity(j, componentMask);
                        nodeTypes[j] = targetType;
                    }
                }
                // Original logic only attempts to process the first unassigned component found
                break;
            }
        }
    }

    private boolean[] identifyComponent(int startIndex) {
        boolean[] mask = new boolean[numNodes];
        mask[startIndex] = true;
        for (int j = 0; j < numNodes; j++) {
            if (adjacencyMatrix[startIndex][j] && nodeTypes[j] == UNASSIGNED) {
                mask[j] = true;
            }
        }
        return mask;
    }

    /**
     * Validates that a component is a clique and has no edges to other unassigned nodes.
     */
    private void verifyComponentConnectivity(int nodeIdx, boolean[] componentMask) {
        for (int k = 0; k < numNodes; k++) {
            // Skip self and Type B nodes as per original logic
            if (k == nodeIdx || nodeTypes[k] == TYPE_B) {
                continue;
            }

            if (componentMask[k]) {
                // Within the same component, nodes must be connected
                if (!adjacencyMatrix[nodeIdx][k]) {
                    isValidStructure = false;
                }
            } else {
                // Nodes in different components must not be connected
                if (adjacencyMatrix[nodeIdx][k]) {
                    isValidStructure = false;
                }
            }
        }
    }

    private void validateAllNodesAssigned() {
        for (int type : nodeTypes) {
            if (type == UNASSIGNED) {
                isValidStructure = false;
                break;
            }
        }
    }

    private void printResult(PrintWriter writer) {
        if (isValidStructure) {
            writer.println("Yes");
            StringBuilder sb = new StringBuilder();
            for (int type : nodeTypes) {
                sb.append((char) (type + 'a'));
            }
            writer.println(sb.toString());
        } else {
            writer.println("No");
        }
    }

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        int n = reader.nextInt();
        int m = reader.nextInt();

        GraphStructureAnalyzer analyzer = new GraphStructureAnalyzer(n, m, reader);
        analyzer.solve(writer);

        writer.flush();
        writer.close();
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[8192];
        private int curChar;
        private int numChars;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (numChars == -1) throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buffer);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) return -1;
            }
            return buffer[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver for the graph partitioning problem.
 * The goal is to partition vertices into three sets:
 * 'b' (universal nodes connected to all other nodes),
 * 'a' (a specific clique-based subset), and
 * 'c' (the remaining nodes).
 */
public class GraphPartitionSolver {

    private static final char TYPE_A = 'a';
    private static final char TYPE_B = 'b';
    private static final char TYPE_C = 'c';

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int nodeCount = reader.nextInt();
            int edgeCount = reader.nextInt();

            boolean[][] adjacencyMatrix = new boolean[nodeCount][nodeCount];
            for (int i = 0; i < edgeCount; i++) {
                int u = reader.nextInt() - 1;
                int v = reader.nextInt() - 1;
                if (isValidIndex(u, nodeCount) && isValidIndex(v, nodeCount)) {
                    adjacencyMatrix[u][v] = true;
                    adjacencyMatrix[v][u] = true;
                }
            }

            char[] nodeLabels = computeNodeLabels(nodeCount, adjacencyMatrix);

            if (validatePartition(nodeCount, adjacencyMatrix, nodeLabels)) {
                writer.println("Yes");
                writer.println(new String(nodeLabels));
            } else {
                writer.println("No");
            }
        } catch (Exception e) {
            // In a production environment, use a proper logging framework
        } finally {
            writer.close();
        }
    }

    private static boolean isValidIndex(int index, int boundary) {
        return index >= 0 && index < boundary;
    }

    /**
     * Logic to assign labels 'a', 'b', or 'c' to each node based on graph connectivity.
     */
    private static char[] computeNodeLabels(int n, boolean[][] adj) {
        char[] labels = new char[n];
        Arrays.fill(labels, ' '); // Placeholder for unassigned nodes

        // 1. Identify universal nodes ('b')
        // A universal node is connected to every other node in the graph.
        for (int i = 0; i < n; i++) {
            boolean isUniversal = true;
            for (int j = 0; j < n; j++) {
                if (i != j && !adj[i][j]) {
                    isUniversal = false;
                    break;
                }
            }
            if (isUniversal) {
                labels[i] = TYPE_B;
            }
        }

        // 2. Identify 'a' nodes
        // The first non-universal node and its neighbors (that aren't 'b') are labeled 'a'.
        int firstNonUniversal = -1;
        for (int i = 0; i < n; i++) {
            if (labels[i] != TYPE_B) {
                firstNonUniversal = i;
                labels[i] = TYPE_A;
                break;
            }
        }

        if (firstNonUniversal != -1) {
            for (int i = firstNonUniversal + 1; i < n; i++) {
                if (labels[i] != TYPE_B && adj[firstNonUniversal][i]) {
                    labels[i] = TYPE_A;
                }
            }
        }

        // 3. All remaining unassigned nodes are labeled 'c'
        for (int i = 0; i < n; i++) {
            if (labels[i] == ' ') {
                labels[i] = TYPE_C;
            }
        }

        return labels;
    }

    /**
     * Validates whether the assigned labels satisfy the required connectivity constraints.
     */
    private static boolean validatePartition(int n, boolean[][] adj, char[] labels) {
        for (int i = 0; i < n; i++) {
            char typeI = labels[i];

            // 'b' nodes are universal by definition, so we skip their validation check.
            if (typeI == TYPE_B) continue;

            for (int j = 0; j < n; j++) {
                if (i == j) continue;

                char typeJ = labels[j];
                boolean isConnected = adj[i][j];

                if (typeI == TYPE_A) {
                    // 'a' nodes must be connected to all 'a' and 'b' nodes, but not to 'c' nodes.
                    if ((typeJ == TYPE_A || typeJ == TYPE_B) && !isConnected) return false;
                    if (typeJ == TYPE_C && isConnected) return false;
                } else if (typeI == TYPE_C) {
                    // 'c' nodes must be connected to all 'b' and 'c' nodes, but not to 'a' nodes.
                    if ((typeJ == TYPE_B || typeJ == TYPE_C) && !isConnected) return false;
                    if (typeJ == TYPE_A && isConnected) return false;
                }
            }
        }
        return true;
    }

    /**
     * Efficient utility for reading input.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A refactored solution for the graph partitioning problem.
 * The goal is to partition nodes into three types (A, B, C) based on specific 
 * connectivity requirements.
 */
public class AIMDiv2C {

    // Type constants for better readability
    private static final int TYPE_A = 0;
    private static final int TYPE_B = 1;
    private static final int TYPE_C = 2;

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        // Read number of nodes and edges
        int n = reader.nextInt();
        int m = reader.nextInt();

        // Build adjacency matrix
        boolean[][] adjacencyMatrix = new boolean[n][n];
        for (int i = 0; i < m; i++) {
            int u = reader.nextInt() - 1;
            int v = reader.nextInt() - 1;
            if (u >= 0 && u < n && v >= 0 && v < n) {
                adjacencyMatrix[u][v] = adjacencyMatrix[v][u] = true;
            }
        }

        GraphSolver solver = new GraphSolver(n, adjacencyMatrix);
        solver.solve();
    }

    /**
     * Encapsulates the logic for solving the graph labeling problem.
     */
    static class GraphSolver {
        private final int n;
        private final boolean[][] adj;
        private final int[] labels;

        // State used during the BFS-based labeling process
        private boolean specialModeTriggered = false;
        private boolean isFirstInComponent = false;

        public GraphSolver(int n, boolean[][] adj) {
            this.n = n;
            this.adj = adj;
            this.labels = new int[n];
            Arrays.fill(this.labels, -1); // -1 represents unassigned
        }

        /**
         * Orchestrates the steps of the algorithm.
         */
        public void solve() {
            // Step 1: Label assignment using BFS
            for (int i = 0; i < n; i++) {
                if (labels[i] == -1) {
                    runBfsLabeling(i);
                }
            }

            // Step 2: Validate initial connectivity requirements
            if (!isInitialAssignmentValid()) {
                System.out.println("No");
                return;
            }

            // Step 3: Upgrade nodes that meet criteria for Type B
            upgradeNodesToTypeB();

            // Step 4: Final validation of edge constraints (e.g., Type A vs Type C edges)
            if (!isFinalEdgeConfigurationValid()) {
                System.out.println("No");
                return;
            }

            // Step 5: Success output
            printSuccessResult();
        }

        /**
         * Performs a BFS to assign labels to nodes in a connected component.
         */
        private void runBfsLabeling(int startNode) {
            Queue<Integer> queue = new LinkedList<>();
            queue.add(startNode);

            // Use the parity flag to assign initial types
            labels[startNode] = isFirstInComponent ? TYPE_C : TYPE_A;
            isFirstInComponent = true;

            while (!queue.isEmpty()) {
                int u = queue.poll();

                for (int v = 0; v < n; v++) {
                    if (adj[u][v] && labels[v] == -1) {
                        queue.add(v);

                        if (!specialModeTriggered) {
                            assignLabelInStandardMode(u, v);
                        } else {
                            if (!assignLabelInSpecialMode(v)) {
                                // If special mode labeling fails, terminate this BFS traversal
                                return;
                            }
                        }
                    }
                }
            }
        }

        private void assignLabelInStandardMode(int u, int v) {
            if (labels[u] == TYPE_C) {
                labels[v] = TYPE_C;
            } else if (isNodeConnectedToAllOfType(v, TYPE_A)) {
                labels[v] = TYPE_A;
            } else {
                // Trigger special mode by adjusting current node and neighbor
                labels[u] = TYPE_B;
                labels[v] = TYPE_C;
                specialModeTriggered = true;
            }
        }

        private boolean assignLabelInSpecialMode(int v) {
            if (isNodeConnectedToAllOfType(v, TYPE_B)) {
                if (isNodeConnectedToAllOfType(v, TYPE_C)) {
                    labels[v] = isNodeConnectedToAllOfType(v, TYPE_A) ? TYPE_B : TYPE_C;
                } else if (isNodeConnectedToAllOfType(v, TYPE_A)) {
                    labels[v] = TYPE_A;
                } else {
                    labels[v] = TYPE_B;
                }
            } else {
                return false; // Triggers early exit of BFS
            }
            return true;
        }

        private boolean isNodeConnectedToAllOfType(int node, int type) {
            for (int i = 0; i < n; i++) {
                if (i == node) continue;
                if (labels[i] == type && !adj[node][i]) {
                    return false;
                }
            }
            return true;
        }

        private boolean isInitialAssignmentValid() {
            for (int i = 0; i < n; i++) {
                // Every node must be connected to all Type B nodes
                if (labels[i] == -1 || !isNodeConnectedToAllOfType(i, TYPE_B)) {
                    return false;
                }

                // Validate specific type constraints
                if (labels[i] == TYPE_A) {
                    if (!isNodeConnectedToAllOfType(i, TYPE_A)) return false;
                } else if (labels[i] == TYPE_B) {
                    if (!isNodeConnectedToAllOfType(i, TYPE_A) || !isNodeConnectedToAllOfType(i, TYPE_C)) {
                        return false;
                    }
                } else { // TYPE_C
                    if (!isNodeConnectedToAllOfType(i, TYPE_C)) return false;
                }
            }
            return true;
        }

        private void upgradeNodesToTypeB() {
            for (int i = 0; i < n; i++) {
                boolean connectedToAll = true;
                for (int type = 0; type < 3; type++) {
                    if (!isNodeConnectedToAllOfType(i, type)) {
                        connectedToAll = false;
                        break;
                    }
                }
                if (connectedToAll) {
                    labels[i] = TYPE_B;
                }
            }
        }

        private boolean isFinalEdgeConfigurationValid() {
            for (int i = 0; i < n; i++) {
                // Constraint: No edges allowed between Type A and Type C
                if (labels[i] == TYPE_A || labels[i] == TYPE_C) {
                    int targetType = (labels[i] == TYPE_A) ? TYPE_C : TYPE_A;
                    for (int j = 0; j < n; j++) {
                        if (i != j && labels[j] == targetType && adj[i][j]) {
                            return false;
                        }
                    }
                }
            }
            return true;
        }

        private void printSuccessResult() {
            StringBuilder sb = new StringBuilder();
            for (int label : labels) {
                sb.append((char) (label + 'a'));
            }
            System.out.println("Yes");
            System.out.println(sb.toString());
        }
    }

    /**
     * Utility class for fast input reading.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A refactored solution to determine if a graph can be partitioned into 
 * three specific sets (cliques A, B, and C) based on node degrees and adjacency.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int n = reader.nextInt();
            int m = reader.nextInt();

            GraphSolver solver = new GraphSolver(n, m, reader);
            solver.solve(writer);
        } catch (Exception e) {
            // Handle potential parsing errors
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Handles the graph logic and validation.
     */
    static class GraphSolver {
        private final int n;
        private final int m;
        private final List<Integer>[] adjacencyList;
        private final char[] nodeColors;

        // Color Constants
        private static final char UNCOLORED = '\0';
        private static final char COLOR_A = 'a';
        private static final char COLOR_B = 'b';
        private static final char COLOR_C = 'c';

        public GraphSolver(int n, int m, FastReader reader) throws IOException {
            this.n = n;
            this.m = m;
            this.adjacencyList = new ArrayList[n];
            for (int i = 0; i < n; i++) {
                adjacencyList[i] = new ArrayList<>();
            }
            this.nodeColors = new char[n];

            for (int i = 0; i < m; i++) {
                int u = reader.nextInt() - 1;
                int v = reader.nextInt() - 1;
                adjacencyList[u].add(v);
                adjacencyList[v].add(u);
            }
        }

        public void solve(PrintWriter writer) {
            identifyUniversalNodes();

            // Attempt to form Clique A and then Clique C
            if (!processCliques()) {
                writer.println("No");
                return;
            }

            if (validateFinalState(writer)) {
                writer.println("Yes");
                writer.println(new String(nodeColors));
            } else {
                writer.println("No");
            }
        }

        /**
         * Nodes connected to all other (n-1) nodes are assigned color 'b'.
         */
        private void identifyUniversalNodes() {
            for (int i = 0; i < n; i++) {
                if (adjacencyList[i].size() == n - 1) {
                    nodeColors[i] = COLOR_B;
                }
            }
        }

        /**
         * Orchestrates the grouping of nodes into Clique A and Clique C.
         */
        private boolean processCliques() {
            // 1. Try to form Clique A
            for (int i = 0; i < n; i++) {
                if (nodeColors[i] != COLOR_B) {
                    if (!formClique(i, COLOR_A, COLOR_B)) {
                        return false;
                    }
                    break; // Only attempt to form one 'a' clique
                }
            }

            // 2. Try to form Clique C
            for (int i = 0; i < n; i++) {
                if (nodeColors[i] != COLOR_A && nodeColors[i] != COLOR_B) {
                    if (!formClique(i, COLOR_C, COLOR_A, COLOR_B)) {
                        return false;
                    }
                    break; // Only attempt to form one 'c' clique
                }
            }

            return true;
        }

        /**
         * Forms a clique of a specific color starting from a seed node.
         * 
         * @param seed The starting node for the clique.
         * @param targetColor The color to assign (e.g., 'a' or 'c').
         * @param forbiddenColors Colors that the neighbors must not have to be included.
         * @return true if the formed set constitutes a valid clique.
         */
        private boolean formClique(int seed, char targetColor, char... forbiddenColors) {
            nodeColors[seed] = targetColor;
            int cliqueSize = 1;

            // Color the seed and its valid neighbors
            for (int neighbor : adjacencyList[seed]) {
                if (!isForbidden(neighbor, forbiddenColors)) {
                    nodeColors[neighbor] = targetColor;
                    cliqueSize++;
                }
            }

            // Verify that every node in this new clique is connected to every other node in it
            int[] internalDegrees = new int[n];
            for (int i = 0; i < n; i++) {
                if (nodeColors[i] == targetColor) {
                    for (int neighbor : adjacencyList[i]) {
                        if (nodeColors[neighbor] == targetColor) {
                            internalDegrees[neighbor]++;
                        }
                    }
                }
            }

            for (int i = 0; i < n; i++) {
                if (nodeColors[i] == targetColor && internalDegrees[i] != cliqueSize - 1) {
                    return false;
                }
            }

            return true;
        }

        private boolean isForbidden(int node, char[] forbidden) {
            for (char f : forbidden) {
                if (nodeColors[node] == f) return true;
            }
            return false;
        }

        /**
         * Performs the final check:
         * 1. All nodes must be assigned a color (a, b, or c).
         * 2. There must be no edges between nodes of color 'a' and 'c'.
         */
        private boolean validateFinalState(PrintWriter writer) {
            int coloredNodesCount = 0;
            for (int i = 0; i < n; i++) {
                if (nodeColors[i] != UNCOLORED) {
                    coloredNodesCount++;
                }
            }

            // The original code uses a mathematical shortcut:
            // It decrements 't' for every edge connecting 'a' and 'c'.
            // Since edges are bidirectional, it checks each edge twice.
            // t == n is only possible if coloredNodesCount == n AND no a-c edges exist.
            int aMinusCEdgesCount = 0;
            for (int u = 0; u < n; u++) {
                for (int v : adjacencyList[u]) {
                    if (isAAndC(nodeColors[u], nodeColors[v])) {
                        aMinusCEdgesCount++;
                    }
                }
            }

            // aMinusCEdgesCount is actually 2 * actual edges because of undirected traversal
            return (coloredNodesCount - aMinusCEdgesCount) == n;
        }

        private boolean isAAndC(char c1, char c2) {
            return (c1 == COLOR_A && c2 == COLOR_C) || (c1 == COLOR_C && c2 == COLOR_A);
        }
    }

    /**
     * Fast I/O utility.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A refactored solution for the ATM problem.
 * The goal is to partition nodes into three sets:
 * Set B: Nodes connected to all other nodes.
 * Set A and C: Two disjoint cliques with no edges between them.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            AtmProblemSolver solver = new AtmProblemSolver(reader);
            solver.solve(writer);
        } catch (Exception e) {
            // In a production environment, use a logger.
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    /**
     * Represents the three possible classifications for a node.
     */
    enum NodeType {
        A, B, C, UNDEFINED
    }

    /**
     * Handles the core logic of solving the ATM problem.
     */
    static class AtmProblemSolver {
        private final int nodeCount;
        private final int edgeCount;
        private final boolean[][] adjacencyMatrix;
        private final FastReader reader;

        public AtmProblemSolver(FastReader reader) {
            this.reader = reader;
            this.nodeCount = reader.nextInt();
            this.edgeCount = reader.nextInt();
            this.adjacencyMatrix = new boolean[nodeCount][nodeCount];
            initializeGraph();
        }

        private void initializeGraph() {
            for (int i = 0; i < edgeCount; i++) {
                int u = reader.nextInt() - 1;
                int v = reader.nextInt() - 1;
                adjacencyMatrix[u][v] = adjacencyMatrix[v][u] = true;
            }
            // A node is always considered "connected" to itself for the purpose of Set B identification
            for (int i = 0; i < nodeCount; i++) {
                adjacencyMatrix[i][i] = true;
            }
        }

        public void solve(PrintWriter out) {
            NodeType[] nodeTypes = identifyNodeTypes();

            if (validatePartition(nodeTypes)) {
                out.println("Yes");
                printResult(nodeTypes, out);
            } else {
                out.println("No");
            }
        }

        /**
         * Identifies which nodes belong to which group.
         */
        private NodeType[] identifyNodeTypes() {
            NodeType[] nodeTypes = new NodeType[nodeCount];
            Arrays.fill(nodeTypes, NodeType.UNDEFINED);

            // Step 1: Identify Group B (nodes connected to everything)
            for (int i = 0; i < nodeCount; i++) {
                boolean connectedToAll = true;
                for (int j = 0; j < nodeCount; j++) {
                    if (!adjacencyMatrix[i][j]) {
                        connectedToAll = false;
                        break;
                    }
                }
                if (connectedToAll) {
                    nodeTypes[i] = NodeType.B;
                }
            }

            // Step 2: Identify Group A via DFS from the first non-B node
            boolean[] visitedInA = new boolean[nodeCount];
            for (int i = 0; i < nodeCount; i++) {
                if (nodeTypes[i] == NodeType.UNDEFINED) {
                    performDfs(i, visitedInA, nodeTypes);
                    break;
                }
            }

            // Step 3: Assign remaining UNDEFINED nodes to Group C
            for (int i = 0; i < nodeCount; i++) {
                if (nodeTypes[i] == NodeType.UNDEFINED) {
                    if (visitedInA[i]) {
                        nodeTypes[i] = NodeType.A;
                    } else {
                        nodeTypes[i] = NodeType.C;
                    }
                }
            }

            return nodeTypes;
        }

        private void performDfs(int startNode, boolean[] visited, NodeType[] nodeTypes) {
            Stack<Integer> stack = new Stack<>();
            stack.push(startNode);
            visited[startNode] = true;

            while (!stack.isEmpty()) {
                int v = stack.pop();
                for (int neighbor = 0; neighbor < nodeCount; neighbor++) {
                    if (adjacencyMatrix[v][neighbor] && !visited[neighbor] && nodeTypes[neighbor] == NodeType.UNDEFINED) {
                        visited[neighbor] = true;
                        stack.push(neighbor);
                    }
                }
            }
        }

        /**
         * Validates that A and C are cliques and there are no edges between them.
         */
        private boolean validatePartition(NodeType[] nodeTypes) {
            for (int i = 0; i < nodeCount; i++) {
                if (nodeTypes[i] == NodeType.B) continue;

                for (int j = 0; j < nodeCount; j++) {
                    if (nodeTypes[j] == NodeType.B) continue;

                    boolean hasEdge = adjacencyMatrix[i][j];

                    if (nodeTypes[i] == NodeType.A) {
                        // If i is in A, any connection must be to another node in A
                        if (hasEdge && nodeTypes[j] == NodeType.C) return false;
                        // If i is in A, any non-connection must be to a node in C
                        if (!hasEdge && nodeTypes[j] == NodeType.A) return false;
                    } else { // nodeTypes[i] is C
                        // If i is in C, any connection must be to another node in C
                        if (hasEdge && nodeTypes[j] == NodeType.A) return false;
                        // If i is in C, any non-connection must be to a node in A
                        if (!hasEdge && nodeTypes[j] == NodeType.C) return false;
                    }
                }
            }
            return true;
        }

        private void printResult(NodeType[] nodeTypes, PrintWriter out) {
            StringBuilder sb = new StringBuilder();
            for (NodeType type : nodeTypes) {
                switch (type) {
                    case A -> sb.append('a');
                    case B -> sb.append('b');
                    case C -> sb.append('c');
                    default -> sb.append('c');
                }
            }
            out.println(sb.toString());
        }
    }

    /**
     * Efficient reader for fast I/O operations.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * Represents the possible labels for a node in the graph.
 */
enum NodeLabel {
    A(1, 'a'),
    B(2, 'b'),
    C(3, 'c');

    private final int value;
    private final char symbol;

    NodeLabel(int value, char symbol) {
        this.value = value;
        this.symbol = symbol;
    }

    public int getValue() {
        return value;
    }

    public char getSymbol() {
        return symbol;
    }

    public static NodeLabel fromValue(int value) {
        for (NodeLabel label : NodeLabel.values()) {
            if (label.value == value) {
                return label;
            }
        }
        throw new IllegalArgumentException("Invalid label value: " + value);
    }
}

/**
 * Represents a Graph structure with adjacency information.
 */
class Graph {
    private final int vertexCount;
    private final boolean[][] adjacencyMatrix;
    private final int[] degrees;

    public Graph(int vertexCount) {
        this.vertexCount = vertexCount;
        this.adjacencyMatrix = new boolean[vertexCount][vertexCount];
        this.degrees = new int[vertexCount];
    }

    public void addEdge(int source, int destination) {
        if (source >= 0 && source < vertexCount && destination >= 0 && destination < vertexCount) {
            if (!adjacencyMatrix[source][destination]) {
                adjacencyMatrix[source][destination] = true;
                adjacencyMatrix[destination][source] = true;
                degrees[source]++;
                degrees[destination]++;
            }
        }
    }

    public int getVertexCount() {
        return vertexCount;
    }

    public boolean isAdjacent(int u, int v) {
        return adjacencyMatrix[u][v];
    }

    public int getDegree(int vertex) {
        return degrees[vertex];
    }
}

/**
 * Result container for the labeling algorithm.
 */
class LabelingResult {
    private final boolean possible;
    private final NodeLabel[] labels;

    public LabelingResult(boolean possible, NodeLabel[] labels) {
        this.possible = possible;
        this.labels = labels;
    }

    public boolean isPossible() {
        return possible;
    }

    public NodeLabel[] getLabels() {
        return labels;
    }
}

/**
 * Contains the logic to solve the graph labeling problem.
 */
class LabelingSolver {

    /**
     * Solves the labeling problem for the given graph.
     * Labels are assigned such that:
     * - Adjacent nodes have labels differing by exactly 1.
     * - Non-adjacent nodes have labels differing by more than 1.
     */
    public LabelingResult solve(Graph graph) {
        int n = graph.getVertexCount();
        int[] labelValues = new int[n];

        // Step 1: Initial Label Assignment
        for (int i = 0; i < n; i++) {
            if (labelValues[i] == 0) {
                if (graph.getDegree(i) == n - 1) {
                    labelValues[i] = NodeLabel.B.getValue();
                } else {
                    labelValues[i] = NodeLabel.A.getValue();
                    // All non-neighbors of i must be labeled 'c' (3)
                    for (int j = 0; j < n; j++) {
                        if (i != j && !graph.isAdjacent(i, j)) {
                            labelValues[j] = NodeLabel.C.getValue();
                        }
                    }
                }
            }
        }

        // Step 2: Validation
        boolean isValid = validateLabels(graph, labelValues);

        if (!isValid) {
            return new LabelingResult(false, null);
        }

        NodeLabel[] finalLabels = new NodeLabel[n];
        for (int i = 0; i < n; i++) {
            finalLabels[i] = NodeLabel.fromValue(labelValues[i]);
        }

        return new LabelingResult(true, finalLabels);
    }

    private boolean validateLabels(Graph graph, int[] labels) {
        int n = graph.getVertexCount();
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                int diff = Math.abs(labels[i] - labels[j]);
                boolean adjacent = graph.isAdjacent(i, j);

                if (adjacent) {
                    // Adjacent nodes must have labels with a difference of exactly 1
                    if (diff != 1) return false;
                } else {
                    // Non-adjacent nodes must have labels with a difference > 1
                    if (diff <= 1) return false;
                }
            }
        }
        return true;
    }
}

/**
 * Entry point for the application.
 */
public class Main {

