/**
 * Handles the logic for solving the graph labeling problem.
 */
class GraphLabelingSolver {

    /**
     * Executes the primary logic: reading the graph, assigning labels, 
     * and validating the solution.
     */
    public void solve(FastReader in, FastWriter out) throws IOException {
        int vertexCount = in.readInt();
        int edgeCount = in.readInt();

        boolean[][] adjacencyMatrix = new boolean[vertexCount][vertexCount];
        for (int i = 0; i < edgeCount; i++) {
            int u = in.readInt() - 1;
            int v = in.readInt() - 1;
            if (u >= 0 && u < vertexCount && v >= 0 && v < vertexCount) {
                adjacencyMatrix[u][v] = adjacencyMatrix[v][u] = true;
            }
        }

        int seedVertex = findSeedVertex(vertexCount, adjacencyMatrix);
        char[] labels = assignLabels(vertexCount, seedVertex, adjacencyMatrix);

        if (validateLabels(vertexCount, adjacencyMatrix, labels)) {
            out.printLine("Yes");
            out.printLine(new String(labels));
        } else {
            out.printLine("No");
        }
    }

    /**
     * Finds a seed vertex that forms an induced path of length 2 (i-j-k where i is not connected to k).
     */
    private int findSeedVertex(int n, boolean[][] adj) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i == j || !adj[i][j]) continue;
                for (int k = 0; k < n; k++) {
                    // Check if i-j-k is an induced path: (i~j) AND (j~k) AND (i !~ k)
                    if (k != i && k != j && adj[j][k] && !adj[i][k]) {
                        return i;
                    }
                }
            }
        }
        return 0; // Default fallback
    }

    /**
     * Assigns 'a', 'b', or 'c' labels to vertices based on the graph structure.
     */
    private char[] assignLabels(int n, int seedVertex, boolean[][] adj) {
        char[] labels = new char[n];
        Arrays.fill(labels, 'b');
        labels[seedVertex] = 'a';

        // Rule 1: If vertex is not connected to seed, label it 'c'
        for (int i = 0; i < n; i++) {
            if (i != seedVertex && !adj[seedVertex][i]) {
                labels[i] = 'c';
            }
        }

        // Rule 2: If a 'b' vertex is not connected to any 'c' vertex, label it 'a'
        for (int i = 0; i < n; i++) {
            if (labels[i] == 'b') {
                for (int j = 0; j < n; j++) {
                    if (labels[j] == 'c' && !adj[i][j]) {
                        labels[i] = 'a';
                        break; 
                    }
                }
            }
        }
        return labels;
    }

    /**
     * Validates if the label assignment satisfies the distance constraints:
     * - If an edge exists, the absolute difference between label characters must be <= 1.
     * - If no edge exists, the absolute difference must be >= 2.
     */
    private boolean validateLabels(int n, boolean[][] adj, char[] labels) {
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                boolean hasEdge = adj[i][j];
                int labelDiff = Math.abs(labels[i] - labels[j]);

                if (hasEdge && labelDiff > 1) {
                    return false;
                }
                if (!hasEdge && labelDiff < 2) {
                    return false;
                }
            }
        }
        return true;
    }
}

