/**
 * Refactored solution for the graph labeling problem.
 * The goal is to assign 'a', 'b', or 'c' to nodes such that:
 * - 'a' and 'c' nodes have no edges between them.
 * - All other pairs (a-a, b-b, c-c, a-b, b-c) must have edges.
 */
public class CodeForcesC {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        FastWriter writer = new FastWriter(System.out);

        Solver solver = new Solver(reader, writer);
        solver.solve();

        writer.close();
    }

    static class Solver {
        private final FastReader reader;
        private final FastWriter writer;

        public Solver(FastReader reader, FastWriter writer) {
            this.reader = reader;
            this.writer = writer;
        }

        public void solve() {
            try {
                int n = reader.nextInt();
                int m = reader.nextInt();

                boolean[][] adjMatrix = new boolean[n + 1][n + 1];
                int[] degrees = new int[n + 1];

                for (int i = 0; i < m; i++) {
                    int u = reader.nextInt();
                    int v = reader.nextInt();
                    if (u >= 1 && u <= n && v >= 1 && v <= n) {
                        if (!adjMatrix[u][v]) {
                            adjMatrix[u][v] = adjMatrix[v][u] = true;
                            degrees[u]++;
                            degrees[v]++;
                        }
                    }
                }

                char[] labels = determineLabels(n, adjMatrix, degrees);

                if (validateLabels(n, adjMatrix, labels)) {
                    writer.println("Yes");
                    for (int i = 1; i <= n; i++) {
                        writer.print(labels[i]);
                    }
                    writer.println();
                } else {
                    writer.println("No");
                }

            } catch (Exception e) {
                writer.println("Error: " + e.getMessage());
            }
        }

        /**
         * Determines the labels 'a', 'b', or 'c' based on vertex degrees and connectivity.
         */
        private char[] determineLabels(int n, boolean[][] adjMatrix, int[] degrees) {
            char[] labels = new char[n + 1];

            // Step 1: Nodes with degree n-1 are connected to everything; they are 'b'.
            for (int i = 1; i <= n; i++) {
                if (degrees[i] == n - 1) {
                    labels[i] = 'b';
                }
            }

            // Step 2: Find the first non-'b' node to act as a seed for the 'a' group.
            int seedNode = -1;
            for (int i = 1; i <= n; i++) {
                if (labels[i] == 0) {
                    seedNode = i;
                    break;
                }
            }

            // Step 3: If there are non-'b' nodes, partition them into 'a' and 'c'.
            if (seedNode != -1) {
                labels[seedNode] = 'a';
                for (int i = 1; i <= n; i++) {
                    if (labels[i] != 0) continue;

                    // If a non-'b' node is connected to our 'a' seed, it belongs to group 'a'.
                    // Otherwise, it belongs to group 'c'.
                    if (adjMatrix[seedNode][i]) {
                        labels[i] = 'a';
                    } else {
                        labels[i] = 'c';
                    }
                }
            }
            return labels;
        }

        /**
         * Validates that the assigned labels satisfy the graph requirements.
         */
        private boolean validateLabels(int n, boolean[][] adjMatrix, char[] labels) {
            for (int i = 1; i <= n; i++) {
                for (int j = i + 1; j <= n; j++) {
                    boolean hasEdge = adjMatrix[i][j];
                    int labelDiff = Math.abs(labels[i] - labels[j]);

                    if (labelDiff == 2) { 
                        // Case: 'a' and 'c' (97 and 99). Must NOT have an edge.
                        if (hasEdge) return false;
                    } else { 
                        // Case: 'a'-'a', 'b'-'b', 'c'-'c', 'a'-'b', or 'b'-'c'. Must have an edge.
                        if (!hasEdge) return false;
                    }
                }
            }
            return true;
        }
    }

    /**
     * Fast I/O utility for reading large input streams.
     */
    static class FastReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[131072];
        private int currentIndex;
        private int bytesRead;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() throws IOException {
            if (currentIndex >= bytesRead) {
                currentIndex = 0;
                bytesRead = stream.read(buffer);
                if (bytesRead <= 0) return -1;
            }
            return buffer[currentIndex++];
        }

        public int nextInt() throws IOException {
            int c = read();
            while (c != -1 && !isPrintable(c)) c = read();
            if (c == -1) throw new EOFException();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int result = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                result = result * 10 + (c - '0');
                c = read();
            } while (isPrintable(c));
            return sign * result;
        }

        private boolean isPrintable(int c) {
            return (c > 32 && c < 127);
        }
    }

    /**
     * Fast I/O utility for writing large output streams.
     */
    static class FastWriter {
        private final PrintWriter writer;

        public FastWriter(OutputStream outputStream) {
            this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public void print(Object obj) {
            writer.print(obj);
        }

        public void println(Object obj) {
            writer.println(obj);
        }

        public void println() {
            writer.println();
        }

        public void close() {
            writer.close();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to solve the graph partitioning problem.
 * The goal is to partition nodes into three groups:
 * - Group B: Nodes connected to every other node in the graph.
 * - Group A: A clique (every node in A is connected to every other node in A).
 * - Group C: A clique (every node in C is connected to every other node in C).
 * Constraint: No edges may exist between Group A and Group C.
 */
public class GraphPartitionSolver {

    /**
     * Represents the possible labels for a node in the graph.
     */
    private enum NodeGroup {
        A, B, C, UNASSIGNED
    }

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            // Read graph dimensions
            String nStr = reader.next();
            if (nStr == null) return;
            int nodeCount = Integer.parseInt(nStr);
            int edgeCount = reader.nextInt();

            GraphPartitionSolver solver = new GraphPartitionSolver();
            solver.solve(nodeCount, edgeCount, reader, writer);
        } catch (Exception e) {
            // In a production environment, use a proper logging framework.
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    /**
     * Orchestrates the solving process.
     */
    public void solve(int nodeCount, int edgeCount, FastReader reader, PrintWriter writer) {
        boolean[][] adjMatrix = new boolean[nodeCount][nodeCount];

        // Construct the adjacency matrix
        for (int i = 0; i < edgeCount; i++) {
            int u = reader.nextInt() - 1;
            int v = reader.nextInt() - 1;
            if (isValidIndex(u, nodeCount) && isValidIndex(v, nodeCount)) {
                adjMatrix[u][v] = true;
                adjMatrix[v][u] = true;
            }
        }

        NodeGroup[] assignments = assignGroups(nodeCount, adjMatrix);

        if (validatePartition(nodeCount, adjMatrix, assignments)) {
            writer.println("Yes");
            writer.println(formatAssignments(assignments));
        } else {
            writer.println("No");
        }
    }

    private boolean isValidIndex(int index, int limit) {
        return index >= 0 && index < limit;
    }

    /**
     * Implements the logic to assign nodes to A, B, or C.
     */
    private NodeGroup[] assignGroups(int n, boolean[][] adj) {
        NodeGroup[] groups = new NodeGroup[n];
        Arrays.fill(groups, NodeGroup.UNASSIGNED);

        // 1. Identify 'B' nodes: nodes with degree equal to (n - 1)
        for (int i = 0; i < n; i++) {
            int degree = 0;
            for (int j = 0; j < n; j++) {
                if (i != j && adj[i][j]) {
                    degree++;
                }
            }
            if (degree == n - 1) {
                groups[i] = NodeGroup.B;
            }
        }

        // 2. Find the first node not in Group B to act as a seed for Group A
        int seedNode = -1;
        for (int i = 0; i < n; i++) {
            if (groups[i] == NodeGroup.UNASSIGNED) {
                seedNode = i;
                break;
            }
        }

        // 3. If a seed exists, partition remaining non-B nodes into A or C
        if (seedNode != -1) {
            groups[seedNode] = NodeGroup.A;
            for (int i = 0; i < n; i++) {
                if (groups[i] == NodeGroup.UNASSIGNED) {
                    // If neighbor of seed, it belongs to Group A, otherwise Group C
                    groups[i] = adj[seedNode][i] ? NodeGroup.A : NodeGroup.C;
                }
            }
        }

        return groups;
    }

    /**
     * Validates that the assigned groups satisfy the clique and connectivity constraints.
     */
    private boolean validatePartition(int n, boolean[][] adj, NodeGroup[] groups) {
        for (int i = 0; i < n; i++) {
            // Safety check for unassigned nodes
            if (groups[i] == NodeGroup.UNASSIGNED) return false;

            for (int j = 0; j < n; j++) {
                if (i == j) continue;

                NodeGroup groupI = groups[i];
                NodeGroup groupJ = groups[j];

                if (groupI == NodeGroup.A) {
                    // Rule: A must be a clique
                    if (groupJ == NodeGroup.A && !adj[i][j]) return false;
                    // Rule: No edges between A and C
                    if (groupJ == NodeGroup.C && adj[i][j]) return false;
                } else if (groupI == NodeGroup.C) {
                    // Rule: C must be a clique
                    if (groupJ == NodeGroup.C && !adj[i][j]) return false;
                    // Rule: No edges between C and A
                    if (groupJ == NodeGroup.A && adj[i][j]) return false;
                }
                // Group B nodes are implicitly valid due to the degree assignment logic
            }
        }
        return true;
    }

    /**
     * Converts the NodeGroup array into the required string format.
     */
    private String formatAssignments(NodeGroup[] groups) {
        StringBuilder sb = new StringBuilder(groups.length);
        for (NodeGroup group : groups) {
            switch (group) {
                case A: sb.append('a'); break;
                case B: sb.append('b'); break;
                case C: sb.append('c'); break;
                default: sb.append('?'); break;
            }
        }
        return sb.toString();
    }

    /**
     * High-performance reader for faster input processing.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            return next != null ? Integer.parseInt(next) : 0;
        }
    }
}

