                if (adjacencyMatrix[firstNotB][i] && labels[i] != LABEL_B) {
                    labels[i] = LABEL_A;
                }
            }

            int firstNotAB = 0;
            while (firstNotAB < n && (labels[firstNotAB] == LABEL_A || labels[firstNotAB] == LABEL_B)) {
                firstNotAB++;
            }

            if (firstNotAB < n) {
                labels[firstNotAB] = LABEL_C;
                for (int i = 0; i < n; i++) {
                    if (adjacencyMatrix[firstNotAB][i] && labels[i] != LABEL_A && labels[i] != LABEL_B) {
                        labels[i] = LABEL_C;
                    }
                }

                int firstNotABC = 0;
                while (firstNotABC < n && (labels[firstNotABC] == LABEL_A || labels[firstNotABC] == LABEL_B || labels[firstNotABC] == LABEL_C)) {
                    firstNotABC++;
                }

                if (firstNotABC < n) {
                    System.out.println("No");
                    return;
                } else {
                    if (validate(n, adjacencyMatrix, labels)) {
                        System.out.println("Yes");
                        System.out.println(new String(labels));
                    } else {
                        System.out.println("No");
                    }
                }
            } else {
                // If we didn't reach the 'C' block, we still need to check if the assignment is valid
                // However, original code only prints "Yes" if it successfully completes the logic flow.
                // Following original structure:
                System.out.println("Yes");
                System.out.println(new String(labels));
            }
        } else {
            System.out.println("Yes");
            System.out.println(new String(labels));
        }
    }

    private static boolean validate(int n, boolean[][] adj, char[] labels) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i != j) {
                    int diff = Math.abs(labels[i] - labels[j]);
                    if ((diff <= 1 && !adj[i][j]) || (diff == 2 && adj[i][j])) {
                        return false;
                    }
                }
            }
        }
        return true;
    }
