/**
 * A refactored solution for the graph coloring problem.
 * The program identifies specific node types ('a', 'b', 'c') based on 
 * graph connectivity and completeness properties.
 */
public class Main {
    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        GraphColoringSolver solver = new GraphColoringSolver(reader, writer);
        try {
            solver.solve();
        } catch (IOException e) {
            // In a production environment, use a logger.
        } finally {
            writer.flush();
            writer.close();
        }
    }
