class GraphColoringSolver {
    private final FastReader reader;
    private final PrintWriter writer;

    public GraphColoringSolver(FastReader reader, PrintWriter writer) {
        this.reader = reader;
        this.writer = writer;
    }

    /**
     * Executes the core logic of the graph coloring algorithm.
     */
    public void solve() throws IOException {
        int n = reader.nextInt();
        int m = reader.nextInt();

        // Special Case: If the graph is already complete, color all nodes 'a'.
        if (m == n * (n - 1) / 2) {
            writer.println("Yes");
            for (int i = 0; i < n; i++) {
                writer.print('a');
            }
            writer.println();
            return;
        }

        Node[] nodes = buildGraph(n, m);
        char[] nodeColors = new char[n];
        int labeledCount = 0;

        // Phase 1: Identify and color Type 'b' nodes.
        // These are nodes that were initially connected to every other node.
        for (int i = 0; i < n; i++) {
            if (nodes[i].getDegree() == n - 1) {
                nodeColors[i] = 'b';
                labeledCount++;
                // Remove these nodes from the connectivity of their neighbors.
                for (Node neighbor : nodes[i].getNeighbors()) {
                    neighbor.removeNeighbor(nodes[i]);
                }
            }
        }

        // Phase 2: Identify and color Type 'a' nodes.
        // Pick the first available non-'b' node that forms a complete local component.
        boolean foundA = false;
        for (int i = 0; i < n; i++) {
            if (nodeColors[i] != 0) continue;

            if (!isLocalCompleteComponent(nodes[i], n)) {
                writer.println("No");
                return;
            }

            nodeColors[i] = 'a';
            labeledCount++;
            for (Node neighbor : nodes[i].getNeighbors()) {
                nodeColors[neighbor.getId()] = 'a';
                labeledCount++;
            }
            foundA = true;
            break;
        }

        // Phase 3: Identify and color Type 'c' nodes.
        // Pick the first available node not colored 'a' or 'b' that forms a complete local component.
        boolean foundC = false;
        for (int i = 0; i < n; i++) {
            if (nodeColors[i] != 0) continue;

            if (!isLocalCompleteComponent(nodes[i], n)) {
                writer.println("No");
                return;
            }

            nodeColors[i] = 'c';
            labeledCount++;
            for (Node neighbor : nodes[i].getNeighbors()) {
                nodeColors[neighbor.getId()] = 'c';
                labeledCount++;
            }
            foundC = true;
            break;
        }

        // Final Validation: Ensure all nodes are colored and the label count is consistent.
        if (validateColoring(nodeColors, labeledCount, n)) {
            writer.println("Yes");
            for (char color : nodeColors) {
                writer.print(color);
            }
            writer.println();
        } else {
            writer.println("No");
        }
    }

    private Node[] buildGraph(int n, int m) throws IOException {
        Node[] nodes = new Node[n];
        for (int i = 0; i < n; i++) {
            nodes[i] = new Node(i);
        }
        for (int i = 0; i < m; i++) {
            int u = reader.nextInt() - 1;
            int v = reader.nextInt() - 1;
            nodes[u].addNeighbor(nodes[v]);
            nodes[v].addNeighbor(nodes[u]);
        }
        return nodes;
    }

    private boolean validateColoring(char[] nodeColors, int labeledCount, int n) {
        for (char color : nodeColors) {
            if (color == 0) return false;
        }
        return labeledCount == n;
    }

    /**
     * Checks if the node and its immediate neighbors form a complete component
     * where every neighbor's neighborhood is identical to the center node's neighborhood.
     */
    private boolean isLocalCompleteComponent(Node s, int n) {
        BitSet centerNeighborhood = new BitSet(n);
        for (Node neighbor : s.getNeighbors()) {
            centerNeighborhood.set(neighbor.getId());
        }
        centerNeighborhood.set(s.getId());

        for (Node neighbor : s.getNeighbors()) {
            BitSet neighborNeighborhood = new BitSet(n);
            neighborNeighborhood.set(neighbor.getId());
            for (Node neighborOfNeighbor : neighbor.getNeighbors()) {
                neighborNeighborhood.set(neighborOfNeighbor.getId());
            }
            if (!neighborNeighborhood.equals(centerNeighborhood)) {
                return false;
            }
        }
        return true;
    }
}

