import java.io.*;
import java.util.*;

/**
 * This program solves a graph partitioning problem.
 * The goal is to determine if the graph can be partitioned into at most three sets:
 * 1. A set of 'universal' nodes (labeled 'b') that are connected to every other node.
 * 2. Up to two other sets (labeled 'a' and 'c') where each set forms a clique 
 *    (a complete subgraph).
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            String nInput = reader.next();
            if (nInput == null) return;
            int n = Integer.parseInt(nInput);

            int m = reader.nextInt();

            // Adjacency matrix is used for O(1) edge lookups during clique validation
            boolean[][] adjMatrix = new boolean[n][n];
            int[] degrees = new int[n];

            for (int i = 0; i < m; i++) {
                int u = reader.nextInt() - 1;
                int v = reader.nextInt() - 1;

                // Boundary check to prevent ArrayIndexOutOfBounds
                if (u >= 0 && u < n && v >= 0 && v < n && u != v) {
                    if (!adjMatrix[u][v]) {
                        adjMatrix[u][v] = true;
                        adjMatrix[v][u] = true;
                        degrees[u]++;
                        degrees[v]++;
                    }
                }
            }

            solve(n, adjMatrix, degrees, writer);

        } catch (Exception e) {
            // Silent catch for standard competitive programming environments
        } finally {
            writer.close();
        }
    }

    /**
     * Core logic to partition nodes and validate the graph structure.
     */
    private static void solve(int n, boolean[][] adjMatrix, int[] degrees, PrintWriter writer) {
        char[] labels = new char[n];
        boolean[] visited = new boolean[n];

        // 1. Identify 'universal' nodes (nodes connected to all n-1 other nodes)
        for (int i = 0; i < n; i++) {
            if (degrees[i] == n - 1) {
                labels[i] = 'b';
                visited[i] = true;
            }
        }

        int componentCount = 0;
        boolean isValid = true;

        // 2. Identify remaining connected components
        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                componentCount++;

                // The problem constraints imply a maximum of two additional clique components ('a' and 'c')
                if (componentCount > 2) {
                    isValid = false;
                    break;
                }

                char currentLabel = (componentCount == 1) ? 'a' : 'c';
                List<Integer> componentNodes = findComponent(i, n, adjMatrix, visited, labels, currentLabel);

                // 3. Validate that the identified component is a clique
                if (!isClique(componentNodes, adjMatrix)) {
                    isValid = false;
                    break;
                }
            }
        }

        // 4. Final verification: ensure all nodes were assigned a label
        if (isValid) {
            for (int i = 0; i < n; i++) {
                if (!visited[i]) {
                    isValid = false;
                    break;
                }
            }
        }

        // 5. Output results
        if (isValid) {
            writer.println("Yes");
            writer.println(new String(labels));
        } else {
            writer.println("No");
        }
    }

    /**
     * Uses Breadth-First Search to find all nodes belonging to the same connected component.
     */
    private static List<Integer> findComponent(int startNode, int n, boolean[][] adjMatrix, 
                                              boolean[] visited, char[] labels, char label) {
        List<Integer> component = new ArrayList<>();
        Deque<Integer> queue = new ArrayDeque<>();

        visited[startNode] = true;
        labels[startNode] = label;
        queue.add(startNode);
        component.add(startNode);

        while (!queue.isEmpty()) {
            int u = queue.poll();
            for (int v = 0; v < n; v++) {
                if (adjMatrix[u][v] && !visited[v]) {
                    visited[v] = true;
                    labels[v] = label;
                    queue.add(v);
                    component.add(v);
                }
            }
        }
        return component;
    }

    /**
     * Verifies if the provided subset of nodes forms a complete subgraph (clique).
     */
    private static boolean isClique(List<Integer> nodes, boolean[][] adjMatrix) {
        for (int i = 0; i < nodes.size(); i++) {
            for (int j = i + 1; j < nodes.size(); j++) {
                if (!adjMatrix[nodes.get(i)][nodes.get(j)]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Fast I/O utility for high-performance input reading.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A refactored solution for solving a graph-based constraint problem.
 * The problem involves assigning states to nodes based on adjacency and non-adjacency constraints.
 */
public class Main {

    public static void main(String[] args) {
        try {
            GraphSolver solver = new GraphSolver(new FastScanner(System.in));
            solver.solve();
        } catch (IOException e) {
            e.printStackTrace();
            System.exit(42);
        }
    }

    /**
     * Handles the core logic of the graph problem.
     */
    static class GraphSolver {
        // Constants for node states and markers
        private static final int UNASSIGNED = -1;
        private static final int UNIVERSAL_NODE = 1;
        private static final int TEMPORARY_STATE = -2;
        private static final int NO_EDGE_MARKER = -5;

        private final int numNodes;
        private final int numEdges;
        private final List<Integer>[] adjacencyList;
        private final int[][] adjacencyMatrix;
        private final int[] nodeStates;
        private final FastScanner scanner;
        private boolean isPossible = true;

        @SuppressWarnings("unchecked")
        public GraphSolver(FastScanner scanner) throws IOException {
            this.scanner = scanner;
            this.numNodes = scanner.nextInt();
            this.numEdges = scanner.nextInt();

            this.adjacencyList = new ArrayList[numNodes];
            for (int i = 0; i < numNodes; i++) {
                this.adjacencyList[i] = new ArrayList<>();
            }

            this.adjacencyMatrix = new int[numNodes][numNodes];
            for (int i = 0; i < numNodes; i++) {
                Arrays.fill(this.adjacencyMatrix[i], NO_EDGE_MARKER);
            }

            this.nodeStates = new int[numNodes];
            Arrays.fill(this.nodeStates, UNASSIGNED);
        }

        public void solve() throws IOException {
            readEdges();
            identifyUniversalNodes();
            applyConstraints();
            finalizeStates();
            printResults();
        }

        private void readEdges() throws IOException {
            for (int i = 0; i < numEdges; i++) {
                int u = scanner.nextInt() - 1;
                int v = scanner.nextInt() - 1;
                adjacencyList[u].add(v);
                adjacencyList[v].add(u);
                adjacencyMatrix[u][v] = 1;
                adjacencyMatrix[v][u] = 1;
            }
        }

        private void identifyUniversalNodes() {
            for (int i = 0; i < numNodes; i++) {
                if (adjacencyList[i].size() == numNodes - 1) {
                    nodeStates[i] = UNIVERSAL_NODE;
                }
            }
        }

        private void applyConstraints() {
            for (int i = 0; i < numNodes; i++) {
                if (nodeStates[i] != UNASSIGNED) {
                    continue;
                }

                int currentColor = TEMPORARY_STATE;

                // Step 1: Process neighbors in the graph
                for (int neighbor : adjacencyList[i]) {
                    int neighborState = nodeStates[neighbor];
                    if (neighborState == UNASSIGNED || neighborState == UNIVERSAL_NODE) {
                        continue;
                    }

                    // Constraint: Specific conflicting colors cannot be adjacent
                    if ((neighborState == 0 && currentColor == 2) || (neighborState == 2 && currentColor == 0)) {
                        isPossible = false;
                        break;
                    }
                    currentColor = neighborState;
                }

                if (!isPossible) break;

                // Step 2: Process non-neighbors (complement graph)
                for (int j = 0; j < numNodes; j++) {
                    if (i != j && adjacencyMatrix[i][j] == NO_EDGE_MARKER) {
                        int nonNeighborState = nodeStates[j];
                        if (nonNeighborState == UNASSIGNED || nonNeighborState == UNIVERSAL_NODE) {
                            continue;
                        }

                        // Constraint: Specific colors cannot exist in the complement graph
                        if ((nonNeighborState == 0 && currentColor == 0) || (nonNeighborState == 2 && currentColor == 2)) {
                            isPossible = false;
                            break;
                        }
                        currentColor = (2 + nonNeighborState) % 4;
                    }
                }

                if (!isPossible) break;

                // Assign determined color or default to 0
                nodeStates[i] = (currentColor == TEMPORARY_STATE) ? 0 : currentColor;
            }
        }

        private void finalizeStates() {
            for (int i = 0; i < numNodes; i++) {
                if (nodeStates[i] == UNASSIGNED) {
                    nodeStates[i] = 0;
                }
            }
        }

        private void printResults() throws IOException {
            PrintWriter out = new PrintWriter(System.out);
            if (isPossible) {
                out.println("Yes");
                for (int state : nodeStates) {
                    out.print((char) ('a' + state));
                }
                out.println();
            } else {
                out.println("No");
            }
            out.flush();
            out.close();
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream in) {
            this.reader = new BufferedReader(new InputStreamReader(in));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        public double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Main class to execute the graph task.
 */
public class Main {
    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        GraphTask solver = new GraphTask();
        solver.solve(reader, writer);

        writer.close();
    }

    /**
     * Handles the logic for solving the specific graph problem.
     */
    static class GraphTask {

        public void solve(FastReader in, PrintWriter out) {
            int numVertices = in.nextInt();
            int numEdges = in.nextInt();

            boolean[][] adjacencyMatrix = new boolean[numVertices][numVertices];
            for (int i = 0; i < numEdges; i++) {
                int u = in.nextInt() - 1;
                int v = in.nextInt() - 1;
                adjacencyMatrix[u][v] = adjacencyMatrix[v][u] = true;
            }

            // Phase 1: Check for an independent set of size 3 (three nodes with no edges between them)
            if (hasIndependentSetOfThree(numVertices, adjacencyMatrix)) {
                out.println("No");
                return;
            }

            // Phase 2: Identify node types and constraints
            char[] nodeLabels = new char[numVertices];
            Set<Integer>[] nonNeighbors = initializeNonNeighbors(numVertices, adjacencyMatrix);

            if (!identifyBTypeNodes(numVertices, adjacencyMatrix, nodeLabels, nonNeighbors)) {
                out.println("No");
                return;
            }

            // Phase 3: Assign remaining labels ('a' and 'c')
            assignRemainingLabels(numVertices, nodeLabels, nonNeighbors);

            out.println("Yes");
            out.println(new String(nodeLabels));
        }

        /**
         * Checks if there exists any set of three vertices where no two vertices are connected.
         */
        private boolean hasIndependentSetOfThree(int n, boolean[][] adj) {
            for (int i = 0; i < n; i++) {
                for (int j = i + 1; j < n; j++) {
                    if (adj[i][j]) continue;
                    for (int k = j + 1; k < n; k++) {
                        if (!adj[i][k] && !adj[j][k]) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        /**
         * Pre-calculates the sets of non-neighboring nodes for each vertex.
         */
        @SuppressWarnings("unchecked")
        private Set<Integer>[] initializeNonNeighbors(int n, boolean[][] adj) {
            Set<Integer>[] nonNeighbors = new HashSet[n];
            for (int i = 0; i < n; i++) {
                nonNeighbors[i] = new HashSet<>();
            }
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (i != j && !adj[i][j]) {
                        nonNeighbors[i].add(j);
                    }
                }
            }
            return nonNeighbors;
        }

        /**
         * Identifies nodes that must be labeled 'b' based on the induced path pattern.
         * Returns false if the constraints are violated.
         */
        private boolean identifyBTypeNodes(int n, boolean[][] adj, char[] labels, Set<Integer>[] nonNeighbors) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    // We are looking for edges (i, j)
                    if (i == j || !adj[i][j]) continue;

                    for (int k = 0; k < n; k++) {
                        if (i == k) continue;

                        // Pattern: i-j is edge, j-k is edge, but i-k is NOT an edge
                        if (adj[j][k] && !adj[i][k]) {
                            // If an endpoint of this path is already 'b', the configuration is invalid
                            if (labels[i] == 'b' || labels[k] == 'b') {
                                return false;
                            }
                            labels[j] = 'b';
                        }
                    }
                }
            }
            return true;
        }

        /**
         * Fills in the unassigned nodes with 'a' and their non-neighbors with 'c'.
         */
        private void assignRemainingLabels(int n, char[] labels, Set<Integer>[] nonNeighbors) {
            for (int i = 0; i < n; i++) {
                if (labels[i] == '\u0000') {
                    labels[i] = 'a';
                    for (int neighbor : nonNeighbors[i]) {
                        if (labels[neighbor] == '\u0000') {
                            labels[neighbor] = 'c';
                        }
                    }
                }
            }
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver for determining if a graph can be partitioned into three specific sets:
 * Set B (universal nodes), Set A, and Set C, such that:
 * - Nodes in B are connected to all other nodes.
 * - Nodes in A are connected to all nodes in A and B.
 * - Nodes in C are connected to all nodes in C and B.
 * - No edges exist between Set A and Set C.
 */
public class GraphPartitionSolver {

    private enum NodeLabel {
        A('a'), B('b'), C('c'), NONE(' ');

        private final char symbol;

        NodeLabel(char symbol) {
            this.symbol = symbol;
        }

        @Override
        public String toString() {
            return String.valueOf(symbol);
        }
    }

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int testCases = 1; // Defaulting to 1 as per original logic
            while (testCases-- > 0) {
                solve(reader, writer);
            }
        } finally {
            writer.close();
        }
    }

    private static void solve(FastReader reader, PrintWriter writer) {
        int n = reader.nextInt();
        int m = reader.nextInt();

        List<Integer>[] adj = new ArrayList[n + 1];
        for (int i = 0; i <= n; i++) {
            adj[i] = new ArrayList<>();
        }

        for (int i = 0; i < m; i++) {
            int u = reader.nextInt();
            int v = reader.nextInt();
            adj[u].add(v);
            adj[v].add(u);
        }

        NodeLabel[] labels = new NodeLabel[n + 1];
        Arrays.fill(labels, NodeLabel.NONE);

        int countA = 0;
        int countB = 0;
        int countC = 0;

        // 1. Identify Set B (Universal Nodes: degree == n - 1)
        for (int i = 1; i <= n; i++) {
            if (adj[i].size() == n - 1) {
                labels[i] = NodeLabel.B;
                countB++;
            }
        }

        // 2. Identify Set A (First unlabelled node and its unlabelled neighbors)
        int firstUnlabelledA = -1;
        for (int i = 1; i <= n; i++) {
            if (labels[i] == NodeLabel.NONE) {
                firstUnlabelledA = i;
                break;
            }
        }

        if (firstUnlabelledA != -1) {
            labels[firstUnlabelledA] = NodeLabel.A;
            countA++;
            for (int neighbor : adj[firstUnlabelledA]) {
                if (labels[neighbor] == NodeLabel.NONE) {
                    labels[neighbor] = NodeLabel.A;
                    countA++;
                }
            }
        }

        // 3. Identify Set C (Next unlabelled node and its unlabelled neighbors)
        int firstUnlabelledC = -1;
        for (int i = 1; i <= n; i++) {
            if (labels[i] == NodeLabel.NONE) {
                firstUnlabelledC = i;
                break;
            }
        }

        boolean isPossible = true;
        if (firstUnlabelledC != -1) {
            labels[firstUnlabelledC] = NodeLabel.C;
            countC++;
            for (int neighbor : adj[firstUnlabelledC]) {
                if (labels[neighbor] == NodeLabel.NONE) {
                    labels[neighbor] = NodeLabel.C;
                    countC++;
                } else if (labels[neighbor] == NodeLabel.A) {
                    // If a node in C is connected to a node in A, the partition is invalid
                    isPossible = false;
                    break;
                }
            }
        }

        // 4. Final Validation
        // Check if all nodes are assigned to a group
        if (countA + countB + countC != n) {
            isPossible = false;
        }

        // Check if the degree of each node matches the required connectivity
        if (isPossible) {
            for (int i = 1; i <= n; i++) {
                int degree = adj[i].size();
                if (labels[i] == NodeLabel.A) {
                    if (degree != countA + countB - 1) {
                        isPossible = false;
                        break;
                    }
                } else if (labels[i] == NodeLabel.C) {
                    if (degree != countC + countB - 1) {
                        isPossible = false;
                        break;
                    }
                }
            }
        }

        // 5. Output Result
        if (isPossible) {
            writer.println("Yes");
            StringBuilder sb = new StringBuilder();
            for (int i = 1; i <= n; i++) {
                sb.append(labels[i].toString());
            }
            writer.println(sb.toString());
        } else {
            writer.println("No");
        }
    }

    /**
     * Efficient reader for fast I/O operations.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public boolean nextBoolean() {
            return Boolean.parseBoolean(next());
        }
    }
}

