/**
 * A solver for the Graph and String problem.
 * The goal is to assign labels 'a', 'b', or 'c' to nodes in a graph
 * such that specific connectivity constraints are satisfied.
 */
public class GraphStringSolver {

    /**
     * Represents the possible labels for each node in the graph.
     */
    private enum NodeLabel {
        A("a"), 
        B("b"), 
        C("c"), 
        UNLABELED("");

        private final String representation;

        NodeLabel(String representation) {
            this.representation = representation;
        }

        @Override
        public String toString() {
            return representation;
        }
    }

    private final boolean isDebug;
    private int nodesCount;
    private int edgesCount;
    private boolean[][] adjacencyMatrix;
    private NodeLabel[] labels;

    public GraphStringSolver(boolean isDebug) {
        this.isDebug = isDebug;
    }

    public static void main(String[] args) {
        // Set to true to use the debug file input, false for System.in
        GraphStringSolver solver = new GraphStringSolver(false);
        solver.execute();
    }

    /**
     * Orchestrates the reading, solving, and output process.
     */
    public void execute() {
        try {
            readInput();
            solve();
        } catch (IOException e) {
            if (isDebug) {
                e.printStackTrace();
            } else {
                System.err.println("Error reading input: " + e.getMessage());
            }
        }
    }

    private void readInput() throws IOException {
        Scanner sc;
        if (isDebug) {
            // Note: Hardcoded paths should ideally be passed via configuration
            File debugFile = new File("src/x0001_aim_tech_round_div_1/A_input1.txt");
            if (!debugFile.exists()) {
                throw new FileNotFoundException("Debug input file not found: " + debugFile.getAbsolutePath());
            }
            sc = new Scanner(new FileInputStream(debugFile));
        } else {
            sc = new Scanner(System.in);
        }

        if (!sc.hasNextInt()) {
            sc.close();
            return;
        }

        nodesCount = sc.nextInt();
        edgesCount = sc.nextInt();

        if (isDebug) {
            System.out.format("n=%d m=%d%n", nodesCount, edgesCount);
        }

        adjacencyMatrix = new boolean[nodesCount][nodesCount];
        for (int i = 0; i < edgesCount; i++) {
            int u = sc.nextInt() - 1;
            int v = sc.nextInt() - 1;
            if (isDebug) {
                System.out.format("%d %d%n", u + 1, v + 1);
            }
            if (isValidIndex(u) && isValidIndex(v)) {
                adjacencyMatrix[u][v] = true;
                adjacencyMatrix[v][u] = true; // Graph is treated as undirected
            }
        }

        labels = new NodeLabel[nodesCount];
        Arrays.fill(labels, NodeLabel.UNLABELED);
        sc.close();
    }

    private boolean isValidIndex(int index) {
        return index >= 0 && index < nodesCount;
    }

    private void solve() {
        if (edgesCount == 0) {
            handleZeroEdgesCase();
            return;
        }

        performLabelingLogic();
    }

    /**
     * Preserves the original logic for the specific edge case where m = 0.
     */
    private void handleZeroEdgesCase() {
        switch (nodesCount) {
            case 1:
                System.out.println("Yes");
                System.out.println("a");
                break;
            case 2:
                System.out.println("Yes");
                System.out.println("ac");
                break;
            default:
                System.out.println("No");
                break;
        }
    }

    private void performLabelingLogic() {
        markNodesAsB();

        if (!markNodesAsA()) {
            return; // All nodes were labeled B
        }

        if (!markNodesAsC()) {
            return; // Either labeling failed or all nodes are already A or B
        }

        if (validateGraphConstraints()) {
            System.out.println("Yes");
            printLabelString();
        } else {
            System.out.println("No");
        }
    }

    /**
     * Nodes labeled B are connected to every other node in the graph.
     */
    private void markNodesAsB() {
        for (int i = 0; i < nodesCount; i++) {
            boolean connectedToAll = true;
            for (int j = 0; j < nodesCount; j++) {
                if (i != j && !isConnected(i, j)) {
                    connectedToAll = false;
                    break;
                }
            }
            if (connectedToAll) {
                labels[i] = NodeLabel.B;
            }
        }
    }

    /**
     * Finds the first unlabeled node, labels it A, and labels its unlabeled neighbors as A.
     * @return false if all nodes are already labeled, true otherwise.
     */
    private boolean markNodesAsA() {
        int firstUnlabeled = findFirstUnlabeled();

        if (firstUnlabeled == -1) {
            System.out.println("Yes");
            printRepeatingLabel(NodeLabel.B);
            return false;
        }

        labels[firstUnlabeled] = NodeLabel.A;
        for (int i = firstUnlabeled + 1; i < nodesCount; i++) {
            if (isConnected(firstUnlabeled, i) && labels[i] == NodeLabel.UNLABELED) {
                labels[i] = NodeLabel.A;
            }
        }
        return true;
    }

    /**
     * Finds the first remaining unlabeled node, labels it C, and labels its unlabeled neighbors as C.
     * @return false if logic cannot continue, true if labeling was successful.
     */
    private boolean markNodesAsC() {
        int firstUnlabeled = findFirstUnlabeled();

        if (firstUnlabeled == -1) {
            if (validateGraphConstraints()) {
                System.out.println("Yes");
                printMixedLabels(NodeLabel.A, NodeLabel.B);
            } else {
                System.out.println("No");
            }
            return false;
        }

        labels[firstUnlabeled] = NodeLabel.C;
        for (int i = firstUnlabeled + 1; i < nodesCount; i++) {
            if (labels[i] == NodeLabel.UNLABELED) {
                if (isConnected(firstUnlabeled, i)) {
                    labels[i] = NodeLabel.C;
                } else {
                    System.out.println("No");
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Validates if the current labeling satisfies the adjacency requirements.
     */
    private boolean validateGraphConstraints() {
        for (int i = 0; i < nodesCount; i++) {
            if (labels[i] == NodeLabel.A || labels[i] == NodeLabel.C) {
                NodeLabel opposite = (labels[i] == NodeLabel.A) ? NodeLabel.C : NodeLabel.A;
                for (int j = 0; j < nodesCount; j++) {
                    if (i == j) continue;

                    boolean isOpposite = (labels[j] == opposite);
                    boolean isConnected = isConnected(i, j);

                    // Logic: If node is A, it must be connected to all non-C nodes and not connected to C nodes.
                    if ((!isOpposite && !isConnected) || (isOpposite && isConnected)) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    private boolean isConnected(int u, int v) {
        return adjacencyMatrix[u][v] || adjacencyMatrix[v][u];
    }

    private int findFirstUnlabeled() {
        for (int i = 0; i < nodesCount; i++) {
            if (labels[i] == NodeLabel.UNLABELED) {
                return i;
            }
        }
        return -1;
    }

    private void printLabelString() {
        StringBuilder sb = new StringBuilder();
        for (NodeLabel label : labels) {
            sb.append(label.toString());
        }
        System.out.println(sb.toString());
    }

    private void printRepeatingLabel(NodeLabel label) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < nodesCount; i++) {
            sb.append(label.toString());
        }
        System.out.println(sb.toString());
    }

    private void printMixedLabels(NodeLabel labelIfA, NodeLabel labelIfB) {
        StringBuilder sb = new StringBuilder();
        for (NodeLabel label : labels) {
            sb.append(label == NodeLabel.B ? labelIfB.toString() : labelIfA.toString());
        }
        System.out.println(sb.toString());
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to validate if a graph follows a specific multipartite structure:
 * A set of vertices (Type B) connected to everyone, and the remaining vertices 
 * partitioned into two cliques (Type A and Type C) with no edges between them.
 */
public class Main {

    public static void main(String[] args) {
        try {
            FastReader reader = new FastReader(System.in);
            PrintWriter writer = new PrintWriter(System.out);

            GraphSolver solver = new GraphSolver(reader);
            solver.solve(writer);

            writer.flush();
            writer.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /**
     * Represents the three possible roles a vertex can play in the graph structure.
     */
    enum VertexType {
        A, B, C;

        @Override
        public String toString() {
            return name().toLowerCase();
        }
    }

    /**
     * Encapsulates the graph data structure and its properties.
     */
    static class Graph {
        private final int vertexCount;
        private final boolean[][] adjacencyMatrix;
        private final List<List<Integer>> adjacencyList;
        private final int[] degrees;

        public Graph(int n) {
            this.vertexCount = n;
            this.adjacencyMatrix = new boolean[n + 1][n + 1];
            this.adjacencyList = new ArrayList<>(n + 1);
            this.degrees = new int[n + 1];
            for (int i = 0; i <= n; i++) {
                adjacencyList.add(new ArrayList<>());
            }
        }

        public void addEdge(int u, int v) {
            adjacencyMatrix[u][v] = true;
            adjacencyMatrix[v][u] = true;
            adjacencyList.get(u).add(v);
            adjacencyList.get(v).add(u);
            degrees[u]++;
            degrees[v]++;
        }

        public int getVertexCount() {
            return vertexCount;
        }

        public boolean hasEdge(int u, int v) {
            return adjacencyMatrix[u][v];
        }

        public List<Integer> getNeighbors(int u) {
            return adjacencyList.get(u);
        }

        public int getDegree(int u) {
            return degrees[u];
        }
    }

    /**
     * Handles the logic of partitioning the graph and validating the structure.
     */
    static class GraphSolver {
        private final FastReader reader;

        public GraphSolver(FastReader reader) {
            this.reader = reader;
        }

        public void solve(PrintWriter writer) throws IOException {
            int n = reader.nextInt();
            int m = reader.nextInt();

            Graph graph = new Graph(n);
            for (int i = 0; i < m; i++) {
                int u = reader.nextInt();
                int v = reader.nextInt();
                graph.addEdge(u, v);
            }

            VertexType[] vertexTypes = partitionVertices(graph);

            if (isStructureValid(graph, vertexTypes)) {
                writer.println("Yes");
                for (int i = 1; i <= n; i++) {
                    writer.print(vertexTypes[i]);
                }
                writer.println();
            } else {
                writer.println("No");
            }
        }

        /**
         * Assigns each vertex to Type A, B, or C based on the degree and connectivity.
         */
        private VertexType[] partitionVertices(Graph graph) {
            int n = graph.getVertexCount();
            VertexType[] types = new VertexType[n + 1];

            // 1. Identify Type B: Vertices connected to all other vertices
            for (int i = 1; i <= n; i++) {
                if (graph.getDegree(i) == n - 1) {
                    types[i] = VertexType.B;
                }
            }

            // 2. Identify Type A: The first non-B vertex and its non-B neighbors
            for (int i = 1; i <= n; i++) {
                if (types[i] == null) {
                    types[i] = VertexType.A;
                    for (int neighbor : graph.getNeighbors(i)) {
                        if (types[neighbor] == null) {
                            types[neighbor] = VertexType.A;
                        }
                    }
                    break;
                }
            }

            // 3. Identify Type C: All remaining vertices
            for (int i = 1; i <= n; i++) {
                if (types[i] == null) {
                    types[i] = VertexType.C;
                }
            }

            return types;
        }

        /**
         * Validates the graph against the required adjacency rules.
         */
        private boolean isStructureValid(Graph graph, VertexType[] types) {
            int n = graph.getVertexCount();
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    if (i == j) continue;

                    boolean hasEdge = graph.hasEdge(i, j);
                    VertexType typeI = types[i];
                    VertexType typeJ = types[j];

                    if (typeI == VertexType.B) {
                        // Type B must be connected to everyone
                        if (!hasEdge) return false;
                    } else if (typeI == VertexType.A) {
                        // Type A: No edges to C, must have edges to A and B
                        if (typeJ == VertexType.C) {
                            if (hasEdge) return false;
                        } else {
                            if (!hasEdge) return false;
                        }
                    } else if (typeI == VertexType.C) {
                        // Type C: No edges to A, must have edges to C and B
                        if (typeJ == VertexType.A) {
                            if (hasEdge) return false;
                        } else {
                            if (!hasEdge) return false;
                        }
                    }
                }
            }
            return true;
        }
    }

    /**
     * Efficient utility for reading input.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        public double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }
}

import java.util.*;

/**
 * This program determines if a graph can be partitioned into three cliques (A, B, and C)
 * such that:
 * 1. There are no edges between Set A and Set C.
 * 2. All possible edges exist between Set A and Set B.
 * 3. All possible edges exist between Set B and Set C.
 */
public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int numVertices = scanner.nextInt();
        int numEdges = scanner.nextInt();

        boolean[][] adjacencyMatrix = new boolean[numVertices][numVertices];

        // Initialize the adjacency matrix. 
        // A node is always connected to itself.
        for (int i = 0; i < numVertices; i++) {
            adjacencyMatrix[i][i] = true;
        }

        for (int i = 0; i < numEdges; i++) {
            int u = scanner.nextInt() - 1;
            int v = scanner.nextInt() - 1;
            if (u >= 0 && u < numVertices && v >= 0 && v < numVertices) {
                adjacencyMatrix[u][v] = adjacencyMatrix[v][u] = true;
            }
        }

        GraphProcessor processor = new GraphProcessor(numVertices, adjacencyMatrix);
        processor.execute();

        scanner.close();
    }
}

class GraphProcessor {
    private final int n;
    private final boolean[][] adj;

    public GraphProcessor(int n, boolean[][] adj) {
        this.n = n;
        this.adj = adj;
    }

    /**
     * Orchestrates the partitioning and validation logic.
     */
    public void execute() {
        int[] nonAdjacentPair = findNonAdjacentPair();

        // If no two nodes are non-adjacent, the graph is a complete clique.
        if (nonAdjacentPair == null) {
            System.out.println("Yes");
            System.out.println("a".repeat(n));
            return;
        }

        int u = nonAdjacentPair[0];
        int v = nonAdjacentPair[1];

        // Identify candidate sets based on non-adjacent nodes u and v.
        // Set A: nodes not connected to v.
        // Set C: nodes not connected to u.
        List<Integer> setA = new ArrayList<>();
        List<Integer> setC = new ArrayList<>();
        boolean[] isA = new boolean[n];
        boolean[] isC = new boolean[n];

        for (int i = 0; i < n; i++) {
            if (!adj[v][i]) {
                setA.add(i);
                isA[i] = true;
            }
            if (!adj[u][i]) {
                setC.add(i);
                isC[i] = true;
            }
        }

        // Requirement 1: Validate sets A and C (cliques and no edges between them).
        if (!validateACRelationship(setA, setC)) {
            System.out.println("No");
            return;
        }

        // Construct the final labels and identify Set B.
        StringBuilder labels = new StringBuilder();
        List<Integer> setB = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            if (isA[i]) {
                labels.append('a');
            } else if (isC[i]) {
                labels.append('c');
            } else {
                labels.append('b');
                setB.add(i);
            }
        }

        // Requirement 2: Validate set B (clique and full connectivity to A and C).
        if (validateSetB(setB, setA, setC)) {
            System.out.println("Yes");
            System.out.println(labels.toString());
        } else {
            System.out.println("No");
        }
    }

    /**
     * Searches for any two vertices that do not have an edge between them.
     * @return an array of two vertex indices, or null if the graph is a clique.
     */
    private int[] findNonAdjacentPair() {
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (!adj[i][j]) {
                    return new int[]{i, j};
                }
            }
        }
        return null;
    }

    /**
     * Checks if set A and set C are both cliques and have no edges between them.
     */
    private boolean validateACRelationship(List<Integer> setA, List<Integer> setC) {
        if (!isClique(setA) || !isClique(setC)) {
            return false;
        }

        for (int a : setA) {
            for (int c : setC) {
                // If there is an edge between a node in A and a node in C, fail.
                // This also implicitly fails if A and C overlap, because adj[i][i] is true.
                if (adj[a][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Checks if set B is a clique and is fully connected to all nodes in A and C.
     */
    private boolean validateSetB(List<Integer> setB, List<Integer> setA, List<Integer> setC) {
        if (!isClique(setB)) {
            return false;
        }

        for (int b : setB) {
            // Check connectivity to Set A
            for (int a : setA) {
                if (!adj[b][a]) return false;
            }
            // Check connectivity to Set C
            for (int c : setC) {
                if (!adj[b][c]) return false;
            }
        }
        return true;
    }

    /**
     * Helper method to determine if a specific collection of nodes forms a clique.
     */
    private boolean isClique(List<Integer> nodes) {
        for (int i = 0; i < nodes.size(); i++) {
            for (int j = i + 1; j < nodes.size(); j++) {
                if (!adj[nodes.get(i)][nodes.get(j)]) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.util.*;
import java.io.*;

/**
 * A solver for partitioning a graph into three specific types of vertex sets:
 * Type B: Connected to all other vertices.
 * Type A: A clique that is connected to all Type B vertices but no Type C vertices.
 * Type C: A clique that is connected to all Type B vertices but no Type A vertices.
 */
public class GraphPartitionSolver {

    private enum VertexType {
        A('a'), B('b'), C('c');

        final char label;

        VertexType(char label) {
            this.label = label;
        }
    }

    public static void main(String[] args) {
        FastReader sc = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = sc.nextInt();
            int m = sc.nextInt();

            boolean[][] adjacencyMatrix = new boolean[n][n];
            int[] degrees = new int[n];

            for (int i = 0; i < m; i++) {
                int u = sc.nextInt() - 1;
                int v = sc.nextInt() - 1;
                if (!adjacencyMatrix[u][v]) {
                    adjacencyMatrix[u][v] = adjacencyMatrix[v][u] = true;
                    degrees[u]++;
                    degrees[v]++;
                }
            }

            String result = solve(n, adjacencyMatrix, degrees);
            out.println(result);

        } catch (Exception e) {
            // In competitive programming, we usually don't print stack traces 
            // unless debugging, but we handle it for stability.
        } finally {
            out.close();
        }
    }

    /**
     * Core logic to determine if the graph can be partitioned into sets A, B, and C.
     * 
     * @param n Number of vertices.
     * @param adj Adjacency matrix.
     * @param degrees Array of vertex degrees.
     * @return "Yes" followed by the labels, or "No".
     */
    private static String solve(int n, boolean[][] adj, int[] degrees) {
        VertexType[] partition = new VertexType[n];
        int[] typeCounts = new int[3]; // To track how many of each type we found

        // 1. Identify Group B: Vertices connected to everyone else (degree == n - 1)
        for (int i = 0; i < n; i++) {
            if (degrees[i] == n - 1) {
                partition[i] = VertexType.B;
                typeCounts[VertexType.B.ordinal()]++;
            }
        }

        // 2. Identify Group A: The first cluster of non-B vertices
        int firstNonB = -1;
        for (int i = 0; i < n; i++) {
            if (partition[i] == null) {
                firstNonB = i;
                break;
            }
        }

        if (firstNonB != -1) {
            partition[firstNonB] = VertexType.A;
            typeCounts[VertexType.A.ordinal()]++;
            for (int j = 0; j < n; j++) {
                if (j != firstNonB && partition[j] == null && adj[firstNonB][j]) {
                    partition[j] = VertexType.A;
                    typeCounts[VertexType.A.ordinal()]++;
                }
            }
        }

        // 3. Identify Group C: Everything else that is not B or A
        for (int i = 0; i < n; i++) {
            if (partition[i] == null) {
                partition[i] = VertexType.C;
                typeCounts[VertexType.C.ordinal()]++;
            }
        }

        // 4. Validation
        // The sum of counts must equal n (inherent in logic, but good for clarity)
        if (typeCounts[0] + typeCounts[1] + typeCounts[2] != n) {
            return "No";
        }

        // Verify all pairwise connections follow the rules:
        // - B connects to everyone.
        // - A connects to B and A, but NOT C.
        // - C connects to B and C, but NOT A.
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                VertexType typeI = partition[i];
                VertexType typeJ = partition[j];

                if (typeI == VertexType.B || typeJ == VertexType.B) {
                    // Type B must be connected to everyone
                    if (!adj[i][j]) return "No";
                } else if (typeI == typeJ) {
                    // Inside A or inside C, they must be connected (cliques)
                    if (!adj[i][j]) return "No";
                } else {
                    // One is A and one is C: they must NOT be connected
                    if (adj[i][j]) return "No";
                }
            }
        }

        // 5. Check degree consistency (all nodes in the same group must have same degree)
        // This is a requirement for the specific structure being solved.
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (partition[i] == partition[j] && degrees[i] != degrees[j]) {
                    return "No";
                }
            }
        }

        // Build success string
        StringBuilder sb = new StringBuilder("Yes\n");
        for (VertexType t : partition) {
            sb.append(t.label);
        }
        return sb.toString();
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * Problem: Color a graph with three colors (a, b, c) such that an edge exists 
 * between two nodes if and only if they are NOT colored (a, c) or (c, a).
 * 
 * Logic:
 * 1. The complement graph (where edges represent the absence of edges in the original) 
 *    must be bipartite, using only colors 'a' and 'c'.
 * 2. Any node that has no edges in the complement graph (connected to all nodes in 
 *    the original graph) must be colored 'b'.
 */
public class CodeForces {

    private static final int COLOR_A = 0;
    private static final int COLOR_B = 1;
    private static final int COLOR_C = 2;
    private static final int UNCOLORED = -1;

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            String nStr = reader.next();
            if (nStr == null) return;
            int numNodes = Integer.parseInt(nStr);
            int numEdges = reader.nextInt();

            boolean[][] adjMatrix = new boolean[numNodes][numNodes];
            for (int i = 0; i < numEdges; i++) {
                int u = reader.nextInt() - 1;
                int v = reader.nextInt() - 1;
                if (u >= 0 && u < numNodes && v >= 0 && v < numNodes) {
                    adjMatrix[u][v] = adjMatrix[v][u] = true;
                }
            }

            processGraph(numNodes, adjMatrix, writer);

        } catch (Exception e) {
            // Silent catch for competitive programming context
        } finally {
            writer.flush();
            writer.close();
        }
    }

    private static void processGraph(int n, boolean[][] adj, PrintWriter out) {
        int[] colors = new int[n];
        Arrays.fill(colors, UNCOLORED);

        // 1. Identify nodes with no non-edges (degree 0 in complement graph).
        // These nodes MUST be color 'b'.
        int[] complementDegree = new int[n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i != j && !adj[i][j]) {
                    complementDegree[i]++;
                }
            }
        }

        for (int i = 0; i < n; i++) {
            if (complementDegree[i] == 0) {
                colors[i] = COLOR_B;
            }
        }

        // 2. Color the connected components of the complement graph using A and C.
        for (int i = 0; i < n; i++) {
            if (colors[i] == UNCOLORED) {
                if (!bfsBipartiteColoring(i, adj, colors, n)) {
                    out.println("No");
                    return;
                }
            }
        }

        // 3. Verify all pairs satisfy the edge/color constraints.
        if (!isValidColoring(n, adj, colors)) {
            out.println("No");
            return;
        }

        // 4. Output the valid coloring.
        out.println("Yes");
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            sb.append((char) ('a' + colors[i]));
        }
        out.println(sb.toString());
    }

    /**
     * Performs BFS on the complement graph to assign colors A and C.
     */
    private static boolean bfsBipartiteColoring(int startNode, boolean[][] adj, int[] colors, int n) {
        Queue<Integer> queue = new LinkedList<>();
        queue.add(startNode);
        colors[startNode] = COLOR_A;

        while (!queue.isEmpty()) {
            int u = queue.poll();

            for (int v = 0; v < n; v++) {
                if (u == v || adj[u][v]) {
                    continue; // This is an edge in the original graph, not the complement.
                }

                if (colors[v] == UNCOLORED) {
                    colors[v] = (colors[u] == COLOR_A) ? COLOR_C : COLOR_A;
                    queue.add(v);
                } else if (colors[v] == COLOR_B) {
                    // A node assigned 'b' cannot have a non-edge connection.
                    return false;
                } else if (colors[v] == colors[u]) {
                    // The complement graph is not bipartite.
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Validates that the coloring satisfies: 
     * edge exists <=> NOT (color pair is {a, c})
     */
    private static boolean isValidColoring(int n, boolean[][] adj, int[] colors) {
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                boolean hasEdge = adj[i][j];
                boolean isACPair = (colors[i] == COLOR_A && colors[j] == COLOR_C) ||
                                   (colors[i] == COLOR_C && colors[j] == COLOR_A);

                // If there is an edge, it cannot be an (a, c) pair.
                if (hasEdge && isACPair) return false;
                // If there is no edge, it MUST be an (a, c) pair.
                if (!hasEdge && !isACPair) return false;
            }
        }
        return true;
    }

    /**
     * Efficient reader for large inputs.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.*;

/**
 * A program to solve a graph labeling problem based on specific connectivity 
 * and value-proximity constraints.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = reader.nextInt();
            int m = reader.nextInt();

            GraphLabelingSolver solver = new GraphLabelingSolver(n, m, reader);
            solver.solve(out);
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            out.close();
        }
    }

    /**
     * Fast I/O utility class for efficient reading of input.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
            tokenizer = new StringTokenizer("");
        }

        public String next() throws IOException {
            while (!tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        public double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }

    /**
     * Disjoint Set Union (DSU) to manage connected components.
     */
    static class DisjointSetUnion {
        private final int[] parent;

        public DisjointSetUnion(int n) {
            parent = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
            }
        }

        public int find(int i) {
            if (parent[i] == i) {
                return i;
            }
            return parent[i] = find(parent[i]);
        }

        public void union(int i, int j) {
            int rootI = find(i);
            int rootJ = find(j);
            if (rootI != rootJ) {
                parent[rootI] = rootJ;
            }
        }

        public boolean isConnected(int i, int j) {
            return find(i) == find(j);
        }
    }

    /**
     * Core logic for solving the graph labeling problem.
     */
    static class GraphLabelingSolver {
        private final int n;
        private final List<Integer>[] adjacencyList;
        private final Set<Integer>[] adjacencySet;
        private final DisjointSetUnion dsu;

        private int[] labels;
        private boolean[] visited;
        private boolean isPossible;

        @SuppressWarnings("unchecked")
        public GraphLabelingSolver(int n, int m, FastReader reader) throws IOException {
            this.n = n;
            this.adjacencyList = new ArrayList[n];
            this.adjacencySet = new HashSet[n];
            this.dsu = new DisjointSetUnion(n);

            for (int i = 0; i < n; i++) {
                adjacencyList[i] = new ArrayList<>();
                adjacencySet[i] = new HashSet<>();
            }

            for (int i = 0; i < m; i++) {
                int u = reader.nextInt() - 1;
                int v = reader.nextInt() - 1;
                adjacencyList[u].add(v);
                adjacencyList[v].add(u);
                adjacencySet[u].add(v);
                adjacencySet[v].add(u);
            }
        }

        /**
         * Executes the solving algorithm and prints the result.
         */
        public void solve(PrintWriter out) {
            identifySimilarNodes();

            for (int startColor = 0; startColor < 3; startColor++) {
                resetState();
                isPossible = true;

                // Attempt to label the first component
                performDfs(0, startColor);

                // If possible, attempt to label all other disconnected components
                if (isPossible) {
                    for (int i = 0; i < n && isPossible; i++) {
                        if (!visited[i]) {
                            boolean componentLabeled = false;
                            for (int color = 0; color < 3; color++) {
                                if (isValidLabel(i, color)) {
                                    performDfs(i, color);
                                    componentLabeled = true;
                                    break;
                                }
                            }
                            if (!componentLabeled) {
                                isPossible = false;
                            }
                        }
                    }
                }

                if (isPossible) {
                    out.println("Yes");
                    for (int i = 0; i < n; i++) {
                        out.print((char) (labels[i] + 'a'));
                    }
                    out.println();
                    return;
                }
            }

            out.println("No");
        }

        /**
         * Finds nodes with identical connectivity properties and joins them in DSU.
         */
        private void identifySimilarNodes() {
            for (int i = 0; i < n; i++) {
                for (int j = i + 1; j < n; j++) {
                    if (adjacencyList[i].size() != adjacencyList[j].size() || dsu.isConnected(i, j)) {
                        continue;
                    }

                    boolean sameNeighbors = true;
                    for (int neighbor : adjacencyList[i]) {
                        if (neighbor == j || !adjacencySet[j].contains(neighbor)) {
                            sameNeighbors = false;
                            break;
                        }
                    }

                    if (sameNeighbors) {
                        dsu.union(i, j);
                    }
                }
            }
        }

        private void resetState() {
            labels = new int[n];
            Arrays.fill(labels, -5); // Use -5 to represent unassigned
            visited = new boolean[n];
        }

        /**
         * Validates if assigning a specific color to a node violates constraints.
         */
        private boolean isValidLabel(int node, int color) {
            for (int i = 0; i < n; i++) {
                // Constraint 1: If another node has the same color, they must be in the same DSU component
                if (labels[i] == color && !dsu.isConnected(node, i)) {
                    return false;
                }
                // Constraint 2: If labels are numerically close, nodes must be adjacent
                if (Math.abs(labels[i] - color) <= 1 && !adjacencySet[node].contains(i)) {
                    return false;
                }
            }
            return true;
        }

        /**
         * Greedy DFS to assign labels to nodes.
         */
        private void performDfs(int node, int color) {
            visited[node] = true;
            labels[node] = color;
            if (!isPossible) return;

            for (int neighbor : adjacencyList[node]) {
                if (visited[neighbor]) continue;

                // Determine alternative colors based on the current color (Greedy heuristic)
                int alt1 = -1;
                int alt2 = -1;

                if (color == 0) {
                    alt1 = 1;
                } else if (color == 1) {
                    alt1 = 0;
                    alt2 = 2;
                } else {
                    alt2 = 1;
                }

                if (isValidLabel(neighbor, color)) {
                    performDfs(neighbor, color);
                } else if (alt1 != -1 && isValidLabel(neighbor, alt1)) {
                    performDfs(neighbor, alt1);
                } else if (alt2 != -1 && isValidLabel(neighbor, alt2)) {
                    performDfs(neighbor, alt2);
                } else {
                    isPossible = false;
                    return;
                }

                if (!isPossible) return;
            }
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A program to solve a graph labeling problem where connectivity 
 * must correspond to the difference between node labels ('a', 'b', or 'c').
 */
public class GraphLabelingSolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        try {
            int numNodes = reader.nextInt();
            int numEdges = reader.nextInt();

            Graph graph = new Graph(numNodes);
            for (int i = 0; i < numEdges; i++) {
                int u = reader.nextInt() - 1;
                int v = reader.nextInt() - 1;
                graph.addEdge(u, v);
            }

            Solver solver = new Solver(graph);
            SolverResult result = solver.solve();

            System.out.println(result.isPossible() ? "Yes" : "No");
            if (result.isPossible()) {
                System.out.println(result.getLabels());
            }

        } catch (Exception e) {
            // In a real-world application, use a logger.
            // For competitive programming/algorithmic contexts, standard error is fine.
            System.err.println("An error occurred during execution: " + e.getMessage());
        }
    }

    /**
     * Represents an undirected graph using BitSets for memory efficiency 
     * and O(1) edge lookups.
     */
    static class Graph {
        private final int size;
        private final BitSet[] adjacencies;

        public Graph(int size) {
            this.size = size;
            this.adjacencies = new BitSet[size];
            for (int i = 0; i < size; i++) {
                adjacencies[i] = new BitSet(size);
            }
        }

        public void addEdge(int u, int v) {
            if (u >= 0 && u < size && v >= 0 && v < size) {
                adjacencies[u].set(v);
                adjacencies[v].set(u);
            }
        }

        public boolean isConnected(int u, int v) {
            return adjacencies[u].get(v);
        }

        public int getDegree(int u) {
            return adjacencies[u].cardinality();
        }

        public int getSize() {
            return size;
        }
    }

    /**
     * Result container for the solver.
     */
    static class SolverResult {
        private final boolean possible;
        private final String labels;

        public SolverResult(boolean possible, String labels) {
            this.possible = possible;
            this.labels = labels;
        }

        public boolean isPossible() { return possible; }
        public String getLabels() { return labels; }
    }

    /**
     * Logic handler for the graph labeling algorithm.
     */
    static class Solver {
        private final Graph graph;

        public Solver(Graph graph) {
            this.graph = graph;
        }

        public SolverResult solve() {
            int n = graph.getSize();
            char[] labels = new char[n];

            // Step 1: Identify 'b' nodes (nodes connected to every other node)
            for (int i = 0; i < n; i++) {
                if (graph.getDegree(i) == n - 1) {
                    labels[i] = 'b';
                }
            }

            // Step 2: Identify 'a' and 'c' nodes
            for (int i = 0; i < n; i++) {
                if (labels[i] == '\0') {
                    labels[i] = 'a';
                    for (int j = i + 1; j < n; j++) {
                        if (!graph.isConnected(i, j)) {
                            // If not connected to an 'a' node, it must be 'c'
                            // We only override if it hasn't been set to 'b'
                            if (labels[j] == '\0') {
                                labels[j] = 'c';
                            }
                        }
                    }
                }
            }

            // Ensure any remaining nodes (though unlikely per logic) are filled
            for (int i = 0; i < n; i++) {
                if (labels[i] == '\0') labels[i] = 'a';
            }

            // Step 3: Validate the assignment
            if (validate(n, labels)) {
                return new SolverResult(true, new String(labels));
            } else {
                return new SolverResult(false, "");
            }
        }

        private boolean validate(int n, char[] labels) {
            for (int i = 0; i < n; i++) {
                for (int j = i + 1; j < n; j++) {
                    boolean edgeExists = graph.isConnected(i, j);
                    // Connectivity rule: edge exists if and only if label difference <= 1
                    // 'a'=97, 'b'=98, 'c'=99
                    boolean labelsCompatible = Math.abs(labels[i] - labels[j]) <= 1;

                    if (edgeExists != labelsCompatible) {
                        return false;
                    }
                }
            }
            return true;
        }
    }

    /**
     * High-performance input reader.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to solve a graph assignment problem where nodes are assigned 
 * characters 'a', 'b', or 'c' based on their connectivity.
 */
public class Main {

    public static void main(String[] args) {
        try (InputReader in = new InputReader(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            GraphSolver solver = new GraphSolver();
            solver.solve(in, out);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    static class GraphSolver {
        private static final char CHAR_A = 'a';
        private static final char CHAR_B = 'b';
        private static final char CHAR_C = 'c';
        private static final char UNASSIGNED = '\0';

        /**
         * Orchestrates the reading, solving, and printing of the task.
         */
        public void solve(InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();

            List<List<Integer>> adj = buildAdjacencyList(n, m, in);
            char[] assignment = assignCharacters(n, m, adj);

            if (isValid(n, m, adj, assignment)) {
                out.println("Yes");
                for (int i = 1; i <= n; i++) {
                    out.print(assignment[i]);
                }
                out.println();
            } else {
                out.println("No");
            }
        }

        private List<List<Integer>> buildAdjacencyList(int n, int m, InputReader in) {
            List<List<Integer>> adj = new ArrayList<>(n + 1);
            for (int i = 0; i <= n; i++) {
                adj.add(new ArrayList<>());
            }
            for (int i = 0; i < m; i++) {
                int u = in.nextInt();
                int v = in.nextInt();
                adj.get(u).add(v);
                adj.get(v).add(u);
            }
            return adj;
        }

        /**
         * Generates character assignments based on the specific logic:
         * 1. Nodes connected to everyone else are 'b'.
         * 2. The first component of unassigned nodes is 'a'.
         * 3. All other unassigned nodes are 'c'.
         */
        private char[] assignCharacters(int n, int m, List<List<Integer>> adj) {
            char[] assignment = new char[n + 1];
            Arrays.fill(assignment, UNASSIGNED);

            // Step 1: Assign 'b' to nodes with degree n-1
            for (int i = 1; i <= n; i++) {
                if (adj.get(i).size() == n - 1) {
                    assignment[i] = CHAR_B;
                }
            }

            // Step 2: Assign 'a' to the first available component
            for (int i = 1; i <= n; i++) {
                if (assignment[i] == UNASSIGNED) {
                    dfsAssign(assignment, adj, i, CHAR_A);
                    break; // Original logic only processes the first component
                }
            }

            // Step 3: Assign 'c' to everything else
            for (int i = 1; i <= n; i++) {
                if (assignment[i] == UNASSIGNED) {
                    assignment[i] = CHAR_C;
                }
            }
            return assignment;
        }

        private void dfsAssign(char[] assignment, List<List<Integer>> adj, int node, char targetChar) {
            assignment[node] = targetChar;
            for (int neighbor : adj.get(node)) {
                if (assignment[neighbor] == UNASSIGNED) {
                    dfsAssign(assignment, adj, neighbor, targetChar);
                }
            }
        }

        /**
         * Validates the assignment in O(N + M) time.
         * 1. Checks if every existing edge satisfies |char1 - char2| <= 1.
         * 2. Checks if the total number of edges matches the expected count 
         *    of pairs that satisfy |char1 - char2| <= 1.
         */
        private boolean isValid(int n, int m, List<List<Integer>> adj, char[] assignment) {
            // Verify all existing edges satisfy the adjacency condition
            for (int u = 1; u <= n; u++) {
                for (int v : adj.get(u)) {
                    if (u < v) { // Ensure each edge is checked once
                        if (Math.abs(assignment[u] - assignment[v]) > 1) {
                            return false;
                        }
                    }
                }
            }

            // Count character frequencies to calculate expected edges
            long countA = 0, countB = 0, countC = 0;
            for (int i = 1; i <= n; i++) {
                if (assignment[i] == CHAR_A) countA++;
                else if (assignment[i] == CHAR_B) countB++;
                else if (assignment[i] == CHAR_C) countC++;
            }

            // Total allowed edges are: (same char pairs) + (a-b pairs) + (b-c pairs)
            long expectedEdges = (countA * (countA - 1) / 2) +
                                 (countB * (countB - 1) / 2) +
                                 (countC * (countC - 1) / 2) +
                                 (countA * countB) +
                                 (countB * countC);

            return m == expectedEdges;
        }
    }

    /**
     * Fast I/O reader for efficient input processing.
     */
    static class InputReader implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream inputStream) {
            this.reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        @Override
        public void close() throws IOException {
            reader.close();
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * This program determines if a given graph can be partitioned into a set of disjoint cliques.
 * 
 * Logic:
 * A graph is a disjoint union of cliques if and only if its complement graph is bipartite.
 * Additionally, nodes that are connected to every other node in the original graph 
 * (universal vertices) do not have edges in the complement graph and can be treated
 * as their own special group.
 */
public class CliquePartitionSolver {

    /**
     * Fast I/O helper class for efficient reading of large inputs.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            return next == null ? -1 : Integer.parseInt(next);
        }
    }

    private int numNodes;
    private int numEdges;
    private int[][] adjacencyMatrix;
    private int[] nodeColors; // Stores clique assignments: -1, 0, or 1
    private boolean isPossible;

    /**
     * Main execution flow of the solver.
     */
    public void solve() {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        // 1. Read Input
        String nToken = reader.next();
        if (nToken == null) {
            out.close();
            return;
        }
        numNodes = Integer.parseInt(nToken);
        numEdges = reader.nextInt();

        adjacencyMatrix = new int[numNodes][numNodes];
        nodeColors = new int[numNodes];
        isPossible = true;

        for (int i = 0; i < numEdges; i++) {
            int u = reader.nextInt() - 1;
            int v = reader.nextInt() - 1;
            if (u >= 0 && u < numNodes && v >= 0 && v < numNodes) {
                adjacencyMatrix[u][v] = 1;
                adjacencyMatrix[v][u] = 1;
            }
        }

        // 2. Bipartite coloring of the complement graph
        // A node is only part of a colored component if it has neighbors in the complement graph.
        for (int i = 0; i < numNodes && isPossible; i++) {
            if (nodeColors[i] != 0) continue;

            boolean hasComplementNeighbor = false;
            for (int j = 0; j < numNodes; j++) {
                if (i != j && adjacencyMatrix[i][j] == 0) {
                    hasComplementNeighbor = true;
                    break;
                }
            }

            if (hasComplementNeighbor) {
                dfsColoring(i, -1);
            }
        }

        // 3. Validation
        // Ensure that no edges in the original graph connect two different colored components.
        if (isPossible) {
            for (int i = 0; i < numNodes; i++) {
                for (int j = i + 1; j < numNodes; j++) {
                    if (adjacencyMatrix[i][j] == 1) {
                        int colorI = nodeColors[i];
                        int colorJ = nodeColors[j];
                        // If both nodes are assigned to different cliques, the partition is invalid.
                        if (colorI != 0 && colorJ != 0 && colorI != colorJ) {
                            isPossible = false;
                            break;
                        }
                    }
                }
                if (!isPossible) break;
            }
        }

        // 4. Output Result
        if (isPossible) {
            out.println("Yes");
            StringBuilder result = new StringBuilder();
            for (int i = 0; i < numNodes; i++) {
                // Map colors to 'a', 'b', 'c' to maintain functional parity with original code
                // -1 -> 'a', 0 -> 'b', 1 -> 'c'
                result.append((char) ('a' + nodeColors[i] + 1));
            }
            out.println(result.toString());
        } else {
            out.println("No");
        }

        out.flush();
        out.close();
    }

    /**
     * Performs DFS to 2-color the complement graph.
     * 
     * @param u current node
     * @param color color to assign
     */
    private void dfsColoring(int u, int color) {
        nodeColors[u] = color;
        for (int v = 0; v < numNodes; v++) {
            if (u == v || !isPossible) continue;

            // An edge in the complement graph exists if there is NO edge in the original graph
            if (adjacencyMatrix[u][v] == 0) {
                if (nodeColors[v] == color) {
                    isPossible = false;
                    return;
                }
                if (nodeColors[v] == 0) {
                    dfsColoring(v, -color);
                }
            }
        }
    }

    public static void main(String[] args) {
        new CliquePartitionSolver().solve();
    }
}

