/**
 * A program to label graph vertices into three categories ('a', 'b', 'c') 
 * based on specific connectivity rules and validate the resulting configuration.
 */
public class GraphAndString {

    public static void main(String[] args) {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter pw = new PrintWriter(System.out)) {

            String firstLine = br.readLine();
            if (firstLine == null) return;

            StringTokenizer st = new StringTokenizer(firstLine);
            int numVertices = Integer.parseInt(st.nextToken());
            int numEdges = Integer.parseInt(st.nextToken());

            Graph graph = new Graph(numVertices);

            for (int i = 0; i < numEdges; i++) {
                String edgeLine = br.readLine();
                if (edgeLine != null) {
                    StringTokenizer edgeSt = new StringTokenizer(edgeLine);
                    int u = Integer.parseInt(edgeSt.nextToken());
                    int v = Integer.parseInt(edgeSt.nextToken());
                    graph.addEdge(u, v);
                }
            }

            GraphLabeler labeler = new GraphLabeler();
            LabelingResult result = labeler.solve(graph);

            if (result.isValid()) {
                pw.println("Yes");
                pw.println(result.getLabelString());
            } else {
                pw.println("No");
            }

        } catch (IOException | NumberFormatException e) {
            System.err.println("Error processing input: " + e.getMessage());
        }
    }

    /**
     * Represents the graph structure using an adjacency list.
     */
    static class Graph {
        private final int vertices;
        private final List<List<Integer>> adjacencyList;

        public Graph(int vertices) {
            this.vertices = vertices;
            this.adjacencyList = new ArrayList<>(vertices + 1);
            for (int i = 0; i <= vertices; i++) {
                adjacencyList.add(new ArrayList<>());
            }
        }

        public void addEdge(int u, int v) {
            if (u <= vertices && v <= vertices) {
                adjacencyList.get(u).add(v);
                adjacencyList.get(v).add(u);
            }
        }

        public List<Integer> getNeighbors(int u) {
            return adjacencyList.get(u);
        }

        public int getDegree(int u) {
            return adjacencyList.get(u).size();
        }

        public int getVerticesCount() {
            return vertices;
        }
    }

    /**
     * Result object to hold the outcome of the labeling algorithm.
     */
    static class LabelingResult {
        private final boolean valid;
        private final char[] labels;

        public LabelingResult(boolean valid, char[] labels) {
            this.valid = valid;
            this.labels = labels;
        }

        public boolean isValid() {
            return valid;
        }

        public String getLabelString() {
            if (labels == null) return "";
            StringBuilder sb = new StringBuilder();
            // Labels start from index 1 as per original logic
            for (int i = 1; i < labels.length; i++) {
                sb.append(labels[i]);
            }
            return sb.toString();
        }
    }

    /**
     * Logic handler for determining and validating vertex labels.
     */
    static class GraphLabeler {
        private static final char LABEL_A = 'a';
        private static final char LABEL_B = 'b';
        private static final char LABEL_C = 'c';
        private static final char UNASSIGNED = '\0';

        public LabelingResult solve(Graph graph) {
            int n = graph.getVerticesCount();
            char[] labels = new char[n + 1];
            Arrays.fill(labels, UNASSIGNED);

            // 1. Identify 'b' nodes: Universal nodes connected to all other V-1 vertices
            for (int i = 1; i <= n; i++) {
                if (graph.getDegree(i) == n - 1) {
                    labels[i] = LABEL_B;
                }
            }

            // 2. Identify 'a' group: First non-'b' node and its non-'b' neighbors
            int countA = 0;
            int firstA = findFirstUnassigned(labels, n);
            if (firstA != -1) {
                labels[firstA] = LABEL_A;
                countA++;
                for (int neighbor : graph.getNeighbors(firstA)) {
                    if (labels[neighbor] == UNASSIGNED) {
                        labels[neighbor] = LABEL_A;
                        countA++;
                    }
                }
            }

            // 3. Identify 'c' group: First remaining non-'b' node and its non-'b' neighbors
            int countC = 0;
            int firstC = findFirstUnassigned(labels, n);
            if (firstC != -1) {
                labels[firstC] = LABEL_C;
                countC++;
                for (int neighbor : graph.getNeighbors(firstC)) {
                    if (labels[neighbor] == UNASSIGNED) {
                        labels[neighbor] = LABEL_C;
                        countC++;
                    }
                }
            }

            // 4. Validate the labeling configuration
            if (validate(graph, labels, countA, countC)) {
                return new LabelingResult(true, labels);
            } else {
                return new LabelingResult(false, null);
            }
        }

        private int findFirstUnassigned(char[] labels, int n) {
            for (int i = 1; i <= n; i++) {
                if (labels[i] == UNASSIGNED) return i;
            }
            return -1;
        }

        private boolean validate(Graph graph, char[] labels, int countA, int countC) {
            int n = graph.getVerticesCount();
            for (int i = 1; i <= n; i++) {
                // Check if all nodes are assigned a label
                if (labels[i] == UNASSIGNED) return false;

                char currentLabel = labels[i];

                // 'b' nodes are universal, so we validate 'a' and 'c' groups specifically
                if (currentLabel != LABEL_B) {
                    int sameLabelNeighborsCount = 0;

                    for (int neighbor : graph.getNeighbors(i)) {
                        char neighborLabel = labels[neighbor];

                        // Rule: Non-'b' nodes can only be connected to nodes of the same label or 'b'
                        if (neighborLabel != currentLabel && neighborLabel != LABEL_B) {
                            return false;
                        }

                        if (neighborLabel == currentLabel) {
                            sameLabelNeighborsCount++;
                        }
                    }

                    // Rule: 'a' and 'c' groups must form a complete clique (excluding 'b' connections)
                    int expectedCliqueSize = (currentLabel == LABEL_A) ? (countA - 1) : (countC - 1);
                    if (sameLabelNeighborsCount != expectedCliqueSize) {
                        return false;
                    }
                }
            }
            return true;
        }
    }
}

