/**
 * Result object containing the status of the partition and the resulting labels.
 */
record PartitionResult(boolean isValid, String labels) {
    public static PartitionResult failure() {
        return new PartitionResult(false, "No");
    }

    public static PartitionResult success(String labels) {
        return new PartitionResult(true, labels);
    }
}

/**
 * Solver responsible for partitioning the graph into three specific sets:
 * Group B (Universal nodes), Group A (Clique connected to B), and Group C (Clique connected to B).
 */
class GraphPartitionSolver {
    private final Graph graph;

    public GraphPartitionSolver(Graph graph) {
        this.graph = graph;
    }

    public PartitionResult solve() {
        int n = graph.getNodeCount();
        Set<Integer> groupA = new HashSet<>();
        Set<Integer> groupB = identifyGroupB(n);
        Set<Integer> groupC = new HashSet<>();

        // Identify Group A
        for (int i = 0; i < n; i++) {
            if (!groupB.contains(i)) {
                groupA.add(i);
                for (int neighbor : graph.getNeighbors(i)) {
                    if (!groupB.contains(neighbor)) {
                        groupA.add(neighbor);
                    }
                }
                break;
            }
        }

        // Identify Group C
        for (int i = 0; i < n; i++) {
            if (!groupB.contains(i) && !groupA.contains(i)) {
                groupC.add(i);
                for (int neighbor : graph.getNeighbors(i)) {
                    if (!groupB.contains(neighbor)) {
                        groupC.add(neighbor);
                    }
                }
                break;
            }
        }

        if (!validatePartition(groupA, groupB, groupC, n)) {
            return PartitionResult.failure();
        }

        return PartitionResult.success(generateLabels(groupA, groupB, groupC, n));
    }

    private Set<Integer> identifyGroupB(int n) {
        Set<Integer> groupB = new HashSet<>();
        for (int i = 0; i < n; i++) {
            if (graph.getDegree(i) == n - 1) {
                groupB.add(i);
            }
        }
        return groupB;
    }

    private boolean validatePartition(Set<Integer> a, Set<Integer> b, Set<Integer> c, int n) {
        // Check if all nodes are accounted for
        if (a.size() + b.size() + c.size() != n) {
            return false;
        }

        for (int i = 0; i < n; i++) {
            if (a.contains(i)) {
                if (!isValidCliqueConnection(i, a, b)) return false;
            } else if (c.contains(i)) {
                if (!isValidCliqueConnection(i, c, b)) return false;
            }
        }
        return true;
    }

    private boolean isValidCliqueConnection(int node, Set<Integer> currentGroup, Set<Integer> groupB) {
        // Expected degree: size of current clique + size of universal group - 1 (self)
        int expectedDegree = currentGroup.size() + groupB.size() - 1;
        if (graph.getDegree(node) != expectedDegree) {
            return false;
        }

        // All neighbors must belong to either the current clique or the universal group
        for (int neighbor : graph.getNeighbors(node)) {
            if (!currentGroup.contains(neighbor) && !groupB.contains(neighbor)) {
                return false;
            }
        }
        return true;
    }

    private String generateLabels(Set<Integer> a, Set<Integer> b, Set<Integer> c, int n) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            if (a.contains(i)) {
                sb.append('a');
            } else if (b.contains(i)) {
                sb.append('b');
            } else {
                sb.append('c');
            }
        }
        return sb.toString();
    }
}

/**
 * Entry point of the application.
 */
public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int nodeCount = scanner.nextInt();
        int edgeCount = scanner.nextInt();

        Graph graph = new Graph(nodeCount);

        for (int i = 0; i < edgeCount; i++) {
            int u = scanner.nextInt() - 1;
            int v = scanner.nextInt() - 1;
            graph.addEdge(u, v);
        }

        GraphPartitionSolver solver = new GraphPartitionSolver(graph);
        PartitionResult result = solver.solve();

        if (result.isValid()) {
            System.out.println("Yes");
            System.out.println(result.labels());
        } else {
            System.out.println("No");
        }

        scanner.close();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.*;

/**
 * A program that analyzes a graph to determine if it is a specific type of 
 * complete multipartite graph based on its complement's properties.
 */
public class GraphRefactored {

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        try {
            int n = reader.nextInt();
            int m = reader.nextInt();

            boolean[][] adjacencyMatrix = new boolean[n][n];
            for (int i = 0; i < m; i++) {
                int u = reader.nextInt() - 1;
                int v = reader.nextInt() - 1;
                if (u >= 0 && u < n && v >= 0 && v < n) {
                    adjacencyMatrix[u][v] = true;
                    adjacencyMatrix[v][u] = true;
                }
            }

            GraphAnalyzer analyzer = new GraphAnalyzer(n, adjacencyMatrix);
            String result = analyzer.analyze();
            System.out.println(result);

        } catch (Exception e) {
            // In a real-world scenario, use a logger.
            System.err.println("Error processing graph: " + e.getMessage());
        }
    }

    /**
     * Logic for analyzing the graph structure.
     */
    private static class GraphAnalyzer {
        private final int numVertices;
        private final boolean[][] complementMatrix;
        private final int[] complementDegrees;
        private final int[] vertexGroups; // 1: Group A, 2: Isolated, 3: Group B

        // Mapping for vertex group to character
        private static final char[] GROUP_TO_CHAR = {'a', 'b', 'c'};

        public GraphAnalyzer(int n, boolean[][] adjacencyMatrix) {
            this.numVertices = n;
            this.complementMatrix = new boolean[n][n];
            this.complementDegrees = new int[n];
            this.vertexGroups = new int[n];
            buildComplementGraph(adjacencyMatrix);
        }

        private void buildComplementGraph(boolean[][] adjacencyMatrix) {
            for (int i = 0; i < numVertices; i++) {
                int degree = 0;
                for (int j = 0; j < numVertices; j++) {
                    if (i != j && !adjacencyMatrix[i][j]) {
                        complementMatrix[i][j] = true;
                        degree++;
                    }
                }
                complementDegrees[i] = degree;
                // If a node has no neighbors in the complement, it's connected to everyone in the original graph.
                if (degree == 0) {
                    vertexGroups[i] = 2;
                }
            }
        }

        public String analyze() {
            int root = findFirstNonIsolatedNode();

            if (root == -1) {
                // All nodes are isolated in the complement (connected to everything in original).
                return "Yes\n" + generateColoringString();
            }

            // Perform BFS to color the bipartite component of the complement graph.
            if (!applyBipartiteColoring(root)) {
                return "No";
            }

            // Ensure all nodes are accounted for (complement must be one bipartite component + isolated nodes).
            for (int i = 0; i < numVertices; i++) {
                if (vertexGroups[i] == 0) {
                    return "No";
                }
            }

            // Check if the bipartite component is "complete" (every A connects to every B).
            if (!isComplementBipartiteComplete()) {
                return "No";
            }

            return "Yes\n" + generateColoringString();
        }

        private int findFirstNonIsolatedNode() {
            for (int i = 0; i < numVertices; i++) {
                if (complementDegrees[i] > 0) {
                    return i;
                }
            }
            return -1;
        }

        private boolean applyBipartiteColoring(int root) {
            Queue<Integer> queue = new ArrayDeque<>();
            vertexGroups[root] = 1;
            queue.add(root);

            while (!queue.isEmpty()) {
                int u = queue.poll();
                for (int v = 0; v < numVertices; v++) {
                    if (u != v && complementMatrix[u][v]) {
                        if (vertexGroups[v] == 2) return false; // Should not happen for neighbors

                        if (vertexGroups[v] == 0) {
                            vertexGroups[v] = (vertexGroups[u] == 1) ? 3 : 1;
                            queue.add(v);
                        } else if (vertexGroups[v] == vertexGroups[u]) {
                            return false; // Not bipartite
                        }
                    }
                }
            }
            return true;
        }

        private boolean isComplementBipartiteComplete() {
            int countA = 0;
            int countB = 0;

            for (int i = 0; i < numVertices; i++) {
                if (vertexGroups[i] == 1) countA++;
                else if (vertexGroups[i] == 3) countB++;
            }

            for (int i = 0; i < numVertices; i++) {
                if (vertexGroups[i] == 1) {
                    if (complementDegrees[i] != countB) return false;
                } else if (vertexGroups[i] == 3) {
                    if (complementDegrees[i] != countA) return false;
                }
            }
            return true;
        }

        private String generateColoringString() {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < numVertices; i++) {
                // vertexGroups 1, 2, 3 map to indices 0, 1, 2
                sb.append(GROUP_TO_CHAR[vertexGroups[i] - 1]);
            }
            return sb.toString();
        }
    }

    /**
     * Efficient helper class for reading input.
     */
    private static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader() {
            reader = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A refactored solution to the graph coloring and bipartiteness problem.
 * 
 * The program determines if the complement of a set of removed edges 
 * from a complete graph is bipartite, and if so, calculates a 
 * specific node assignment pattern.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            // Read number of vertices (N) and number of removed edges (M)
            String nStr = reader.next();
            String mStr = reader.next();
            if (nStr == null || mStr == null) return;

            int n = Integer.parseInt(nStr);
            int m = Integer.parseInt(mStr);

            GraphSolver solver = new GraphSolver(n, m);

            // Process the M edges to be removed from the complete graph
            for (int i = 0; i < m; i++) {
                int u = reader.nextInt() - 1;
                int v = reader.nextInt() - 1;
                solver.addRemovedEdge(u, v);
            }

            solver.solve(writer);
        } catch (Exception e) {
            // In a production environment, replace with a proper logging framework.
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Encapsulates the graph data structure and the algorithms 
     * required to solve the problem.
     */
    static class GraphSolver {
        private final int vertexCount;
        private final int removedEdgeCount;
        private final boolean[][] adjacencyMatrix;
        private final int[] degrees;
        private final boolean[] visited;
        private final int[] partitionColors;

        public GraphSolver(int n, int m) {
            this.vertexCount = n;
            this.removedEdgeCount = m;
            this.adjacencyMatrix = new boolean[n][n];
            this.degrees = new int[n];
            this.visited = new boolean[n];
            this.partitionColors = new int[n];

            // Initialize as a complete graph (all vertices connected)
            for (int i = 0; i < n; i++) {
                Arrays.fill(adjacencyMatrix[i], true);
                adjacencyMatrix[i][i] = false; // No self-loops
                degrees[i] = n - 1;
            }
        }

        /**
         * Updates the graph by removing a specified edge.
         */
        public void addRemovedEdge(int u, int v) {
            if (u >= 0 && u < vertexCount && v >= 0 && v < vertexCount) {
                adjacencyMatrix[u][v] = false;
                adjacencyMatrix[v][u] = false;
                degrees[u]--;
                degrees[v]--;
            }
        }

        /**
         * Orchestrates the algorithm steps: bipartiteness check, 
         * coloring, and validation.
         */
        public void solve(PrintWriter writer) {
            // Step 1: Check if the resulting graph is bipartite
            for (int i = 0; i < vertexCount; i++) {
                if (!visited[i]) {
                    if (!isBipartiteDFS(i, 0)) {
                        writer.println("No");
                        return;
                    }
                }
            }

            // Step 2: Determine the node assignments based on bipartite colors and degrees
            int[] assignments = calculateAssignments();

            // Step 3: Verify if the number of pairs satisfying the coloring condition 
            // matches the original number of removed edges.
            if (validateAssignment(assignments)) {
                writer.println("Yes");
                for (int assignment : assignments) {
                    writer.print((char) (assignment + 'a'));
                }
                writer.println();
            } else {
                writer.println("No");
            }
        }

        /**
         * Performs a Depth First Search to verify if the graph can be 2-colored (bipartite).
         */
        private boolean isBipartiteDFS(int u, int color) {
            visited[u] = true;
            partitionColors[u] = color;

            for (int v = 0; v < vertexCount; v++) {
                if (!adjacencyMatrix[u][v]) {
                    continue;
                }

                if (!visited[v]) {
                    if (!isBipartiteDFS(v, 1 - color)) {
                        return false;
                    }
                } else if (partitionColors[v] == color) {
                    return false;
                }
            }
            return true;
        }

        /**
         * Generates a mapping of nodes to color indices (0, 1, 2) 
         * based on the problem constraints.
         */
        private int[] calculateAssignments() {
            int[] assignments = new int[vertexCount];
            for (int i = 0; i < vertexCount; i++) {
                if (degrees[i] == 0) {
                    assignments[i] = 1;
                } else if (partitionColors[i] == 1) {
                    assignments[i] = 2;
                } else {
                    assignments[i] = 0;
                }
            }
            return assignments;
        }

        /**
         * Validates the resulting assignment against the expected edge count.
         */
        private boolean validateAssignment(int[] assignments) {
            int validPairsFound = 0;
            for (int i = 0; i < vertexCount; i++) {
                for (int j = i + 1; j < vertexCount; j++) {
                    // Condition: |assignment[i] - assignment[j]| <= 1
                    if (Math.abs(assignments[i] - assignments[j]) <= 1) {
                        validPairsFound++;
                    }
                }
            }
            return validPairsFound == removedEdgeCount;
        }
    }

    /**
     * Utility class for efficient input reading.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            this.reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            return (next == null) ? 0 : Integer.parseInt(next);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver for the graph coloring problem.
 * The goal is to determine if a graph (defined as the complement of input edges)
 * can be colored with 'a', 'b', or 'c' such that:
 * 1. There is at most one bipartite component colored with 'a' and 'c'.
 * 2. All other nodes remain 'b'.
 * 3. No input edge (non-edge in the graph) connects an 'a' node and a 'c' node.
 */
public class Main {

    private static final char COLOR_A = 'a';
    private static final char COLOR_B = 'b';
    private static final char COLOR_C = 'c';

    private int nodeCount;
    private boolean[][] adjacencyMatrix;
    private char[] nodeColors;

    public static void main(String[] args) {
        new Main().run();
    }

    /**
     * Entry point that manages the lifecycle of the solver.
     */
    public void run() {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            solve(reader, out);
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.close();
        }
    }

    /**
     * Orchestrates the graph construction, coloring, and validation.
     */
    private void solve(FastReader reader, PrintWriter out) throws IOException {
        String firstToken = reader.next();
        if (firstToken == null) return;

        nodeCount = Integer.parseInt(firstToken);
        int nonEdgeCount = reader.nextInt();

        // Initialize graph: initially a complete graph
        initializeAdjacencyMatrix();

        // Remove edges specified in the input (the "non-edges")
        for (int i = 0; i < nonEdgeCount; i++) {
            int u = reader.nextInt() - 1;
            int v = reader.nextInt() - 1;
            adjacencyMatrix[u][v] = false;
            adjacencyMatrix[v][u] = false;
        }

        nodeColors = new char[nodeCount];
        Arrays.fill(nodeColors, COLOR_B);

        int bipartiteComponentCount = 0;

        // Perform bipartite coloring on all connected components
        for (int i = 0; i < nodeCount; i++) {
            if (nodeColors[i] == COLOR_B) {
                int componentSize = performBipartiteDFS(i, COLOR_A);

                if (componentSize == -1) {
                    out.println("No");
                    return;
                }

                if (componentSize == 1) {
                    // If the component is just a single node, keep it as color 'b'
                    nodeColors[i] = COLOR_B;
                } else {
                    bipartiteComponentCount++;
                }
            }
        }

        // The problem requires at most one bipartite component of 'a's and 'c's
        if (bipartiteComponentCount > 1) {
            out.println("No");
            return;
        }

        // Final validation: Ensure no input edge connects an 'a' node to a 'c' node
        if (!validateColoringConstraints()) {
            out.println("No");
            return;
        }

        out.println("Yes");
        out.println(new String(nodeColors));
    }

    private void initializeAdjacencyMatrix() {
        adjacencyMatrix = new boolean[nodeCount][nodeCount];
        for (int i = 0; i < nodeCount; i++) {
            Arrays.fill(adjacencyMatrix[i], true);
            adjacencyMatrix[i][i] = false; // No self-loops
        }
    }

    /**
     * Uses DFS to color a component bipartitely.
     * 
     * @param u The current node.
     * @param targetColor The color to assign to this node.
     * @return The size of the component, or -1 if the component is not bipartite.
     */
    private int performBipartiteDFS(int u, char targetColor) {
        nodeColors[u] = targetColor;
        int size = 1;
        char nextColor = (targetColor == COLOR_A) ? COLOR_C : COLOR_A;

        for (int v = 0; v < nodeCount; v++) {
            if (adjacencyMatrix[u][v]) {
                if (nodeColors[v] == targetColor) {
                    return -1; // Conflict detected: not bipartite
                }
                if (nodeColors[v] == COLOR_B) {
                    int subSize = performBipartiteDFS(v, nextColor);
                    if (subSize == -1) return -1;
                    size += subSize;
                }
            }
        }
        return size;
    }

    /**
     * Verifies that no pair of nodes lacking an edge in the graph (input edges)
     * are colored with opposite 'a' and 'c' colors.
     */
    private boolean validateColoringConstraints() {
        for (int i = 0; i < nodeCount; i++) {
            for (int j = 0; j < nodeCount; j++) {
                if (!adjacencyMatrix[i][j]) {
                    if (isOppositeColor(nodeColors[i], nodeColors[j])) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    private boolean isOppositeColor(char c1, char c2) {
        return (c1 == COLOR_A && c2 == COLOR_C) || (c1 == COLOR_C && c2 == COLOR_A);
    }

    /**
     * Fast I/O utility class.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            return next != null ? Integer.parseInt(next) : 0;
        }
    }
}

