/**
 * A program to solve a graph partitioning problem where vertices are assigned 
 * characters 'a', 'b', or 'c' based on specific connectivity rules.
 */
public class GraphAndString {

    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int vCount = in.nextInt();
            int eCount = in.nextInt();

            // Handle the special case where there are no edges
            if (eCount == 0) {
                handleZeroEdges(vCount, out);
            } else {
                Graph graph = new Graph(vCount);
                for (int i = 0; i < eCount; i++) {
                    graph.addEdge(in.nextInt(), in.nextInt());
                }

                GraphSolver solver = new GraphSolver(graph);
                String result = solver.solve();

                if (result != null) {
                    out.println("Yes");
                    out.println(result);
                } else {
                    out.println("No");
                }
            }
        } catch (Exception e) {
            // In competitive programming, we often swallow or print errors simply
        } finally {
            in.close();
            out.close();
        }
    }

    private static void handleZeroEdges(int v, PrintWriter out) {
        if (v == 1 || v == 2) {
            out.println("Yes");
            out.println(v == 1 ? "a" : "ac");
        } else {
            out.println("No");
        }
    }

    /**
     * Represents an undirected graph.
     */
    static class Graph {
        private final int vertexCount;
        private final List<Set<Integer>> adjacencyList;

        public Graph(int vertexCount) {
            this.vertexCount = vertexCount;
            this.adjacencyList = new ArrayList<>(vertexCount + 1);
            for (int i = 0; i <= vertexCount; i++) {
                adjacencyList.add(new HashSet<>());
            }
        }

        public void addEdge(int u, int v) {
            adjacencyList.get(u).add(v);
            adjacencyList.get(v).add(u);
        }

        public int getVertexCount() {
            return vertexCount;
        }

        public Set<Integer> getNeighbors(int u) {
            return adjacencyList.get(u);
        }

        public int getDegree(int u) {
            return adjacencyList.get(u).size();
        }
    }

    /**
     * Contains the logic for partitioning the graph into sets A, B, and C.
     */
    static class GraphSolver {
        private final Graph graph;
        private final Set<Integer> setA = new HashSet<>();
        private final Set<Integer> setB = new HashSet<>();
        private final Set<Integer> setC = new HashSet<>();

        public GraphSolver(Graph graph) {
            this.graph = graph;
        }

        /**
         * Executes the partitioning and validation logic.
         * @return The resulting string if successful, null otherwise.
         */
        public String solve() {
            partitionVertices();

            if (!validatePartitions()) {
                return null;
            }

            return buildResultString();
        }

        /**
         * Partitions vertices into sets A, B, and C based on degree and connectivity.
         */
        private void partitionVertices() {
            int vCount = graph.getVertexCount();

            // Set B: Vertices connected to all other vertices
            for (int i = 1; i <= vCount; i++) {
                if (graph.getDegree(i) == vCount - 1) {
                    setB.add(i);
                }
            }

            // Set A: Pick first non-B vertex and its non-B neighbors
            for (int i = 1; i <= vCount; i++) {
                if (!setB.contains(i)) {
                    setA.add(i);
                    for (int neighbor : graph.getNeighbors(i)) {
                        if (!setB.contains(neighbor)) {
                            setA.add(neighbor);
                        }
                    }
                    break;
                }
            }

            // Set C: All remaining vertices
            for (int i = 1; i <= vCount; i++) {
                if (!setA.contains(i) && !setB.contains(i)) {
                    setC.add(i);
                }
            }
        }

        /**
         * Validates if the constructed sets satisfy the graph properties.
         */
        private boolean validatePartitions() {
            int sizeA = setA.size();
            int sizeB = setB.size();
            int sizeC = setC.size();

            // Validate Set A
            for (int a : setA) {
                int connectedInAorB = 0;
                for (int v : graph.getNeighbors(a)) {
                    if (setA.contains(v) || setB.contains(v)) {
                        connectedInAorB++;
                    }
                    if (setC.contains(v)) return false; // A and C must not be connected
                }
                if (connectedInAorB != (sizeA + sizeB - 1)) return false;
            }

            // Validate Set B
            for (int b : setB) {
                if (graph.getDegree(b) != graph.getVertexCount() - 1) return false;
            }

            // Validate Set C
            for (int c : setC) {
                int connectedInCorB = 0;
                for (int v : graph.getNeighbors(c)) {
                    if (setC.contains(v) || setB.contains(v)) {
                        connectedInCorB++;
                    }
                    if (setA.contains(v)) return false; // C and A must not be connected
                }
                if (connectedInCorB != (sizeC + sizeB - 1)) return false;
            }

            return true;
        }

        private String buildResultString() {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < graph.getVertexCount(); i++) {
                sb.append('?'); // Placeholder
            }

            for (int i : setA) sb.setCharAt(i - 1, 'a');
            for (int i : setB) sb.setCharAt(i - 1, 'b');
            for (int i : setC) sb.setCharAt(i - 1, 'c');

            return sb.toString();
        }
    }

    /**
     * High-performance input reader.
     */
    static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public void close() throws IOException {
            reader.close();
        }
    }
}

