/**
 * A refactored solution to solve the graph labeling problem.
 * The problem asks to partition nodes into three sets (a, b, c) such that
 * the complement graph of the input is a complete bipartite graph 
 * between sets 'a' and 'c', and set 'b' contains isolated nodes.
 */
public class Codeforces {

    public static void main(String[] args) {
        Solver solver = new Solver(System.in);
        solver.solve();
    }
}

/**
 * Fast I/O utility for efficient data reading.
 */
class FastReader {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    public FastReader(InputStream input) {
        reader = new BufferedReader(new InputStreamReader(input));
        tokenizer = null;
    }

    public String next() {
