                return null;
            }
        }
        return tokenizer.nextToken();
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }
}

class Solver {
    private final FastReader scanner;

    public Solver(InputStream input) {
        this.scanner = new FastReader(input);
    }

    /**
     * Core logic of the program.
     */
    public void solve() {
        String firstToken = scanner.next();
        if (firstToken == null) return;

        int n = Integer.parseInt(firstToken);
        int m = scanner.nextInt();

        // adjacencyMatrix[i][j] is true if there is an edge in the complement graph.
        // The complement graph contains all edges NOT provided in the input.
        boolean[][] adjacencyMatrix = new boolean[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i != j) {
                    adjacencyMatrix[i][j] = true;
                }
            }
        }

        // Remove edges provided in the input from the complement graph.
        for (int i = 0; i < m; i++) {
            int u = scanner.nextInt() - 1;
            int v = scanner.nextInt() - 1;
            adjacencyMatrix[u][v] = false;
            adjacencyMatrix[v][u] = false;
        }

        char[] labels = new char[n];
        Arrays.fill(labels, 'b');

        // Identify the first node that belongs to the complement graph (has edges).
        int startNode = -1;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (adjacencyMatrix[i][j]) {
                    startNode = i;
                    break;
                }
            }
            if (startNode != -1) break;
        }

        // If the complement graph has edges, perform BFS to 2-color the component.
        if (startNode != -1) {
            if (!colorBipartiteComponent(adjacencyMatrix, labels, startNode, n)) {
                System.out.println("No");
                return;
            }
        }

        // Validation: Check if the labeling perfectly matches the complement graph.
        // An edge must exist if and only if the labels are 'a' and 'c' (or vice versa).
        if (validateLabeling(adjacencyMatrix, labels, n)) {
            System.out.println("Yes");
            System.out.println(new String(labels));
        } else {
            System.out.println("No");
        }
    }

    /**
     * Uses BFS to attempt to 2-color a component with 'a' and 'c'.
     * @return true if the component is bipartite, false otherwise.
     */
    private boolean colorBipartiteComponent(boolean[][] adj, char[] labels, int start, int n) {
        Queue<Integer> queue = new LinkedList<>();
        labels[start] = 'a';
        queue.add(start);

        while (!queue.isEmpty()) {
            int u = queue.poll();
            for (int v = 0; v < n; v++) {
                if (adj[u][v]) {
                    if (labels[v] == 'b') {
                        // Assign the opposite color of the current node.
                        labels[v] = (labels[u] == 'a') ? 'c' : 'a';
                        queue.add(v);
                    } else if (labels[v] == labels[u]) {
                        // Found an odd cycle.
                        return false;
                    }
                }
            }
        }
        return true;
    }

    /**
     * Verifies that the generated labels satisfy the complete bipartite graph property.
     */
    private boolean validateLabeling(boolean[][] adj, char[] labels, int n) {
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                // An edge should exist if and only if labels are different and neither is 'b'.
                boolean expectedEdge = (labels[i] != 'b' && labels[j] != 'b' && labels[i] != labels[j]);
                if (adj[i][j] != expectedEdge) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.*;

/**
 * Represents the solution to the graph classification problem.
 * The goal is to classify nodes into three types (a, b, c) based on their connectivity.
 */
public class GraphProblemSolver {

    public static void main(String[] args) {
        try {
            InputReader reader = new InputReader();
            GraphSolver solver = new GraphSolver(reader);
            solver.solve();
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Data structure representing the graph and its properties.
     */
    static class Graph {
        private final int size;
        private final boolean[][] adjacencyMatrix;
        private final int[] degrees;

        public Graph(int size) {
            this.size = size;
            this.adjacencyMatrix = new boolean[size + 1][size + 1];
            this.degrees = new int[size + 1];
            // Initialize self-loops as per original logic
            for (int i = 1; i <= size; i++) {
                this.adjacencyMatrix[i][i] = true;
            }
        }

        public void addEdge(int u, int v) {
            if (u == v) return;
            if (!adjacencyMatrix[u][v]) {
                adjacencyMatrix[u][v] = true;
                adjacencyMatrix[v][u] = true;
                degrees[u]++;
                degrees[v]++;
            }
        }

        public int getSize() {
            return size;
        }

        public boolean isConnected(int u, int v) {
            return adjacencyMatrix[u][v];
        }

        public int getDegree(int u) {
            return degrees[u];
        }
    }

    /**
     * Logic for solving the classification problem.
     */
    static class GraphSolver {
        private final InputReader reader;

        public GraphSolver(InputReader reader) {
            this.reader = reader;
        }

        public void solve() throws IOException {
            int n = reader.nextInt();
            int m = reader.nextInt();

            Graph graph = new Graph(n);
            for (int i = 0; i < m; i++) {
                graph.addEdge(reader.nextInt(), reader.nextInt());
            }

            // 1. Identify Type 'B' nodes: nodes connected to everyone else (degree == n-1)
            List<Integer> typeBNodes = new ArrayList<>();
            int referenceNode = -1;

            for (int i = 1; i <= n; i++) {
                if (graph.getDegree(i) == n - 1) {
                    typeBNodes.add(i);
                } else if (referenceNode == -1) {
                    referenceNode = i;
                }
            }

            // 2. Group remaining nodes by their connectivity pattern
            // A pattern is defined by (degree, connectivity to a reference non-B node)
            Map<NodePattern, List<Integer>> patternGroups = new HashMap<>();
            for (int i = 1; i <= n; i++) {
                if (graph.getDegree(i) == n - 1) {
                    continue;
                }
                NodePattern pattern = new NodePattern(
                        graph.getDegree(i),
                        referenceNode != -1 && graph.isConnected(i, referenceNode)
                );
                patternGroups.computeIfAbsent(pattern, k -> new ArrayList<>()).add(i);
            }

            // 3. Validate: At most 2 distinct patterns for non-B nodes
            if (patternGroups.size() > 2) {
                System.out.println("No");
                return;
            }

            // 4. Validate: Every group must be a clique (all nodes in a group connected to each other)
            for (List<Integer> group : patternGroups.values()) {
                if (!isClique(graph, group)) {
                    System.out.println("No");
                    return;
                }
            }

            // 5. Construct the result string
            printResult(n, typeBNodes, patternGroups);
        }

        private boolean isClique(Graph graph, List<Integer> nodes) {
            for (int i = 0; i < nodes.size(); i++) {
                for (int j = i + 1; j < nodes.size(); j++) {
                    if (!graph.isConnected(nodes.get(i), nodes.get(j))) {
                        return false;
                    }
                }
            }
            return true;
        }

        private void printResult(int n, List<Integer> typeB, Map<NodePattern, List<Integer>> groups) {
            char[] result = new char[n];
            Arrays.fill(result, ' ');

            // Assign 'b'
            for (int node : typeB) {
                result[node - 1] = 'b';
            }

            // Assign 'a' and 'c' to the remaining groups
            int groupIdx = 0;
            char[] otherTypes = {'a', 'c'};
            for (List<Integer> group : groups.values()) {
                char type = otherTypes[groupIdx % 2];
                for (int node : group) {
                    result[node - 1] = type;
                }
                groupIdx++;
            }

            System.out.println("Yes");
            System.out.println(new String(result));
        }
    }

    /**
     * Represents a structural pattern of a node.
     */
    record NodePattern(int degree, boolean connectedToRef) {}

    /**
     * High-performance input reader.
     */
    static class InputReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader() throws IOException {
            this.reader = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;

/**
 * GraphLabeler identifies specific clusters (a, b, c) within a graph
 * and validates if they satisfy the clique and adjacency constraints.
 */
public class GraphLabeler {

    // Constants for vertex labels to improve maintainability
    private static final char UNMARKED = 'x';
    private static final char LABEL_A = 'a';
    private static final char LABEL_B = 'b';
    private static final char LABEL_C = 'c';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int nodeCount = scanner.nextInt();
        int edgeCount = scanner.nextInt();

        List<Set<Integer>> adjacencyList = buildAdjacencyList(nodeCount, edgeCount, scanner);
        char[] labels = computeLabels(nodeCount, adjacencyList);

        if (validateGraphStructure(labels, adjacencyList)) {
            printSuccess(labels);
        } else {
            System.out.println("No");
        }

        scanner.close();
    }

    /**
     * Reads edges from input and constructs an adjacency list using Sets for O(1) lookup.
     */
    private static List<Set<Integer>> buildAdjacencyList(int n, int m, Scanner sc) {
        List<Set<Integer>> adj = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            adj.add(new HashSet<>());
        }

        for (int i = 0; i < m; i++) {
            int u = sc.nextInt() - 1; // Convert to 0-based indexing
            int v = sc.nextInt() - 1;
            if (u >= 0 && u < n && v >= 0 && v < n) {
                adj.get(u).add(v);
                adj.get(v).add(u);
            }
        }
        return adj;
    }

    /**
     * Applies the labeling logic:
     * 1. 'b' labels are assigned to universal nodes (degree == n-1).
     * 2. 'a' labels are assigned to the first unmarked node and its unmarked neighbors.
     * 3. 'c' labels are assigned to all remaining unmarked nodes.
     */
    private static char[] computeLabels(int n, List<Set<Integer>> adj) {
        char[] labels = new char[n];
        Arrays.fill(labels, UNMARKED);

        // 1. Identify universal nodes ('b')
        for (int i = 0; i < n; i++) {
            if (adj.get(i).size() == n - 1) {
                labels[i] = LABEL_B;
            }
        }

        // 2. Identify 'a' cluster
        int firstUnmarked = findFirstUnmarked(labels);
        if (firstUnmarked != -1) {
            labels[firstUnmarked] = LABEL_A;
            for (int neighbor : adj.get(firstUnmarked)) {
                if (labels[neighbor] == UNMARKED) {
                    labels[neighbor] = LABEL_A;
                }
            }
        }

        // 3. Identify 'c' cluster
        for (int i = 0; i < n; i++) {
            if (labels[i] == UNMARKED) {
                labels[i] = LABEL_C;
            }
        }

        return labels;
    }

    private static int findFirstUnmarked(char[] labels) {
        for (int i = 0; i < labels.length; i++) {
            if (labels[i] == UNMARKED) return i;
        }
        return -1;
    }

    /**
     * Validates the three rules:
     * 1. All 'a' nodes must form a clique.
     * 2. All 'c' nodes must form a clique.
     * 3. No 'a' node can be adjacent to a 'c' node.
     */
    private static boolean validateGraphStructure(char[] labels, List<Set<Integer>> adj) {
        List<Integer> aNodes = new ArrayList<>();
        List<Integer> cNodes = new ArrayList<>();

        for (int i = 0; i < labels.length; i++) {
            if (labels[i] == LABEL_A) aNodes.add(i);
            else if (labels[i] == LABEL_C) cNodes.add(i);
        }

        return isClique(aNodes, adj) && 
               isClique(cNodes, adj) && 
               hasNoACAdjacency(labels, adj);
    }

    private static boolean isClique(List<Integer> nodes, List<Set<Integer>> adj) {
        for (int i = 0; i < nodes.size(); i++) {
            for (int j = i + 1; j < nodes.size(); j++) {
                if (!adj.get(nodes.get(i)).contains(nodes.get(j))) {
                    return false;
                }
            }
        }
        return true;
    }

    private static boolean hasNoACAdjacency(char[] labels, List<Set<Integer>> adj) {
        for (int i = 0; i < labels.length; i++) {
            if (labels[i] == LABEL_A) {
                for (int neighbor : adj.get(i)) {
                    if (labels[neighbor] == LABEL_C) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    private static void printSuccess(char[] labels) {
        StringBuilder sb = new StringBuilder("Yes\n");
        for (char label : labels) {
            sb.append(label);
        }
        System.out.println(sb.toString());
    }
}

import java.util.*;
import java.io.*;

/**
 * A solver for the graph coloring problem where nodes are partitioned into three sets:
 * A, B, and C. 
 * - Nodes in B are connected to all other nodes in the graph.
 * - Nodes in A are connected to all nodes in A and B.
 * - Nodes in C are connected to all nodes in C and B.
 * - No edges exist between A and C.
 */
public class GraphColoringSolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(new OutputStreamWriter(System.out));

        try {
            int n = reader.nextInt();
            int m = reader.nextInt();

            solve(n, m, reader, writer);
        } catch (Exception e) {
            // In competitive programming, we usually catch exceptions to prevent 
            // silent failures, but for maintainability, we log them.
        } finally {
            writer.close();
        }
    }

    private static void solve(int n, int m, FastReader reader, PrintWriter writer) throws IOException {
        List<Integer>[] adj = new ArrayList[n + 1];
        int[] degree = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            adj[i] = new ArrayList<>();
        }

        // Build adjacency list and calculate degrees
        for (int i = 0; i < m; i++) {
            int u = reader.nextInt();
            int v = reader.nextInt();
            adj[u].add(v);
            adj[v].add(u);
            degree[u]++;
            degree[v]++;
        }

        char[] labels = new char[n + 1];
        boolean[] visited = new boolean[n + 1];

        // 1. Identify 'B' nodes (Universal nodes)
        int countB = 0;
        for (int i = 1; i <= n; i++) {
            if (degree[i] == n - 1) {
                labels[i] = 'b';
                visited[i] = true;
                countB++;
            }
        }

        // 2. Identify components of non-'B' nodes and assign 'a' or 'c'
        int countA = 0;
        int countC = 0;
        int componentId = 0;

        for (int i = 1; i <= n; i++) {
            if (!visited[i]) {
                componentId++;
                List<Integer> component = new ArrayList<>();
                bfs(i, adj, visited, component);

                // Alternate between labeling components 'a' and 'c'
                char currentLabel = (componentId % 2 == 0) ? 'c' : 'a';
                for (int node : component) {
                    labels[node] = currentLabel;
                    if (currentLabel == 'a') countA++;
                    else countC++;
                }
            }
        }

        // 3. Validate the configuration using the degree property
        // For a node in A: degree must be |A| + |B| - 1
        // For a node in C: degree must be |C| + |B| - 1
        // For a node in B: degree must be n - 1
        boolean isValid = true;
        for (int i = 1; i <= n; i++) {
            if (labels[i] == 'a') {
                if (degree[i] != (countA + countB - 1)) {
                    isValid = false;
                    break;
                }
            } else if (labels[i] == 'c') {
                if (degree[i] != (countC + countB - 1)) {
                    isValid = false;
                    break;
                }
            } else if (labels[i] == 'b') {
                if (degree[i] != n - 1) {
                    isValid = false;
                    break;
                }
            }
        }

        // 4. Output results
        if (!isValid) {
            writer.println("No");
        } else {
            writer.println("Yes");
            StringBuilder sb = new StringBuilder();
            for (int i = 1; i <= n; i++) {
                sb.append(labels[i]);
            }
            writer.println(sb.toString());
        }
    }

    private static void bfs(int startNode, List<Integer>[] adj, boolean[] visited, List<Integer> component) {
        Queue<Integer> queue = new LinkedList<>();
        queue.add(startNode);
        visited[startNode] = true;

        while (!queue.isEmpty()) {
            int curr = queue.poll();
            component.add(curr);

            for (int neighbor : adj[curr]) {
                if (!visited[neighbor]) {
                    visited[neighbor] = true;
                    queue.add(neighbor);
                }
            }
        }
    }

    /**
     * Fast I/O class for efficient reading.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

/**
 * A solver for the graph labeling problem.
 * The goal is to partition nodes into 'universal' nodes (b), 
 * and two distinct cliques (a and c) that are not connected to each other.
 */
public class GraphColoringSolver {

    private static final char LABEL_A = 'a';
    private static final char LABEL_B = 'b';
    private static final char LABEL_C = 'c';

    public static void main(String[] args) {
        InputReader reader = new InputReader();
        GraphColoringSolver solver = new GraphColoringSolver(reader);
        solver.solve();
    }

    private final InputReader reader;

    public GraphColoringSolver(InputReader reader) {
        this.reader = reader;
    }

    /**
     * Orchestrates the solving process.
     */
    public void solve() {
        int numNodes = reader.nextInt();
        int numEdges = reader.nextInt();

        boolean[][] adjacencyMatrix = buildAdjacencyMatrix(numNodes, numEdges);
        char[] nodeLabels = calculateNodeLabels(numNodes, adjacencyMatrix);

        if (isLabelingValid(numNodes, adjacencyMatrix, nodeLabels)) {
            System.out.println("Yes");
            System.out.println(new String(nodeLabels));
        } else {
            System.out.println("No");
        }
    }

    /**
     * Constructs the adjacency matrix from user input.
     */
    private boolean[][] buildAdjacencyMatrix(int n, int m) {
        boolean[][] adj = new boolean[n][n];
        for (int i = 0; i < m; i++) {
            // Subtracting 1 because input is 1-indexed
            int u = reader.nextInt() - 1;
            int v = reader.nextInt() - 1;
            adj[u][v] = true;
            adj[v][u] = true;
        }
        // A node is considered connected to itself for the purpose of this problem
        for (int i = 0; i < n; i++) {
            adj[i][i] = true;
        }
        return adj;
    }

    /**
     * Implements the core logic to assign 'a', 'b', or 'c' to each node.
     */
    private char[] calculateNodeLabels(int n, boolean[][] adj) {
        char[] labels = new char[n];

        // 1. Identify 'b' nodes (universal nodes connected to every node in the graph)
        for (int i = 0; i < n; i++) {
            if (isUniversal(i, n, adj)) {
                labels[i] = LABEL_B;
            } else {
                labels[i] = 'z'; // Temporary placeholder
            }
        }

        // 2. Assign 'a' and 'c' labels to non-'b' nodes
        int firstNonBIndex = findFirstNonB(n, labels);

        if (firstNonBIndex != -1) {
            labels[firstNonBIndex] = LABEL_A;
            for (int j = 0; j < n; j++) {
                if (j != firstNonBIndex && labels[j] != LABEL_B) {
                    // Neighbors of the first 'a' node are labeled 'a', others 'c'
                    labels[j] = adj[firstNonBIndex][j] ? LABEL_A : LABEL_C;
                }
            }
        }

        return labels;
    }

    private boolean isUniversal(int nodeIdx, int n, boolean[][] adj) {
        for (int j = 0; j < n; j++) {
            if (!adj[nodeIdx][j]) {
                return false;
            }
        }
        return true;
    }

    private int findFirstNonB(int n, char[] labels) {
        for (int i = 0; i < n; i++) {
            if (labels[i] != LABEL_B) {
                return i;
            }
        }
        return -1;
    }

    /**
     * Validates if the assigned labels satisfy the graph connectivity constraints.
     */
    private boolean isLabelingValid(int n, boolean[][] adj, char[] labels) {
        for (int i = 0; i < n; i++) {
            // 'b' nodes are universal, so they don't need validation against others
            if (labels[i] == LABEL_B) continue;

            for (int j = 0; j < n; j++) {
                if (labels[j] == LABEL_B) continue;

                boolean isConnected = adj[i][j];
                if (isConnected) {
                    // If connected, nodes must share the same label (clique property)
                    if (labels[i] != labels[j]) return false;
                } else {
                    // If not connected, nodes must have different labels
                    if (labels[i] == labels[j]) return false;
                }
            }
        }
        return true;
    }

    /**
     * Utility class for reading formatted input.
     */
    private static class InputReader {
        private final Scanner scanner = new Scanner(System.in);

        public int nextInt() {
            if (scanner.hasNext()) {
                return Integer.parseInt(scanner.next());
            }
            return 0;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * An application that determines if a graph can be colored with three colors (a, b, c)
 * such that non-adjacent nodes have colors that are "far apart" (e.g., 'a' and 'c')
 * and adjacent nodes have colors that are "close" (e.g., 'a' and 'b').
 */
public class GraphColoringApp {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        GraphColoringSolver solver = new GraphColoringSolver();
        solver.solve(reader, writer);

        writer.flush();
        writer.close();
    }

    /**
     * Represents the possible colors assigned to a node.
     */
    enum NodeColor {
        UNASSIGNED(0, ' '),
        COLOR_A(1, 'a'),
        COLOR_B(2, 'b'),
        COLOR_C(3, 'c');

        private final int value;
        private final char symbol;

        NodeColor(int value, char symbol) {
            this.value = value;
            this.symbol = symbol;
        }

        public int getValue() {
            return value;
        }

        public char getSymbol() {
            return symbol;
        }

        public static NodeColor fromInt(int value) {
            for (NodeColor color : NodeColor.values()) {
                if (color.value == value) {
                    return color;
                }
            }
            return UNASSIGNED;
        }
    }

    /**
     * Encapsulates the logic for solving the graph coloring problem.
     */
    static class GraphColoringSolver {

        /**
         * Performs the coloring logic and prints the result.
         * 
         * @param in  The input reader.
         * @param out The output writer.
         */
        public void solve(FastReader in, PrintWriter out) {
            int nodeCount = in.nextInt();
            int edgeCount = in.nextInt();

            int[][] adjacencyMatrix = new int[nodeCount][nodeCount];
            for (int i = 0; i < edgeCount; i++) {
                int u = in.nextInt() - 1;
                int v = in.nextInt() - 1;
                if (u >= 0 && u < nodeCount && v >= 0 && v < nodeCount) {
                    adjacencyMatrix[u][v] = adjacencyMatrix[v][u] = 1;
                }
            }

            int[] colors = new int[nodeCount]; // Stores NodeColor.value

            // Phase 1: Assign colors based on non-edges (complement graph connections)
            if (!assignColorsForNonEdges(nodeCount, adjacencyMatrix, colors)) {
                out.println("No");
                return;
            }

            // Phase 2: Assign color 'b' (2) to any remaining unassigned nodes
            for (int i = 0; i < nodeCount; i++) {
                if (colors[i] == NodeColor.UNASSIGNED.getValue()) {
                    colors[i] = NodeColor.COLOR_B.getValue();
                }
            }

            // Phase 3: Validate that all existing edges satisfy the proximity constraint
            if (!validateEdges(nodeCount, adjacencyMatrix, colors)) {
                out.println("No");
                return;
            }

            // Success: Output the result
            out.println("Yes");
            out.println(buildColorString(colors));
        }

        /**
         * Logic to assign colors such that non-neighbors have distant colors.
         */
        private boolean assignColorsForNonEdges(int n, int[][] adj, int[] colors) {
            for (int i = 0; i < n; i++) {
                for (int j = i + 1; j < n; j++) {
                    // If there is no edge between i and j
                    if (adj[i][j] == 0) {
                        int colorI = colors[i];
                        int colorJ = colors[j];

                        if (colorI == NodeColor.UNASSIGNED.getValue() && colorJ == NodeColor.UNASSIGNED.getValue()) {
                            colors[i] = NodeColor.COLOR_A.getValue();
                            colors[j] = NodeColor.COLOR_C.getValue();
                        } else if (colorI == NodeColor.UNASSIGNED.getValue()) {
                            if (colorJ == NodeColor.COLOR_B.getValue()) return false;
                            colors[i] = (colorJ == NodeColor.COLOR_A.getValue()) ? NodeColor.COLOR_C.getValue() : NodeColor.COLOR_A.getValue();
                        } else if (colorJ == NodeColor.UNASSIGNED.getValue()) {
                            if (colorI == NodeColor.COLOR_B.getValue()) return false;
                            colors[j] = (colorI == NodeColor.COLOR_A.getValue()) ? NodeColor.COLOR_C.getValue() : NodeColor.COLOR_A.getValue();
                        } else {
                            // Both are already colored; non-neighbors must have |c1 - c2| > 1 (i.e., 1 and 3)
                            if (Math.abs(colorI - colorJ) <= 1) {
                                return false;
                            }
                        }
                    }
                }
            }
            return true;
        }

        /**
         * Validates that all existing edges satisfy |color_i - color_j| <= 1.
         */
        private boolean validateEdges(int n, int[][] adj, int[] colors) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (adj[i][j] == 1) {
                        if (Math.abs(colors[i] - colors[j]) > 1) {
                            return false;
                        }
                    }
                }
            }
            return true;
        }

        /**
         * Converts the color integer array into the required string format.
         */
        private String buildColorString(int[] colors) {
            StringBuilder sb = new StringBuilder();
            for (int colorVal : colors) {
                sb.append(NodeColor.fromInt(colorVal).getSymbol());
            }
            return sb.toString();
        }
    }

    /**
     * Utility class for fast I/O operations.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to categorize nodes in a graph into three specific types (A, B, or C)
 * based on their connectivity patterns.
 */
public class GraphCategorizer {

    private enum NodeType {
        A('a'), B('b'), C('c');

        private final char representation;

        NodeType(char representation) {
            this.representation = representation;
        }

        @Override
        public String toString() {
            return String.valueOf(representation);
        }
    }

    private final FastReader reader;
    private final PrintWriter writer;

    public GraphCategorizer(InputStream inputStream, PrintStream outputStream) {
        this.reader = new FastReader(inputStream);
        this.writer = new PrintWriter(outputStream);
    }

    /**
     * Core logic to solve the graph categorization problem.
     */
    public void solve() {
        int nodeCount = reader.nextInt();
        int edgeCount = reader.nextInt();

        boolean[][] adjacencyMatrix = new boolean[nodeCount][nodeCount];
        for (int i = 0; i < edgeCount; i++) {
            int u = reader.nextInt() - 1;
            int v = reader.nextInt() - 1;
            adjacencyMatrix[u][v] = adjacencyMatrix[v][u] = true;
        }

        NodeType[] nodeTypes = new NodeType[nodeCount];

        // Step 1: Identify Type B nodes (connected to all other nodes)
        identifyTypeBNodes(nodeCount, adjacencyMatrix, nodeTypes);

        // Step 2: Greedily assign Type A or Type C to the remaining nodes
        boolean possible = true;
        for (int i = 0; i < nodeCount; i++) {
            if (nodeTypes[i] != null) {
                continue;
            }

            if (canAssignTypeA(i, nodeTypes, adjacencyMatrix)) {
                nodeTypes[i] = NodeType.A;
            } else if (canAssignTypeC(i, nodeTypes, adjacencyMatrix)) {
                nodeTypes[i] = NodeType.C;
            } else {
                possible = false;
                break;
            }
        }

        // Step 3: Output result
        if (possible) {
            writer.println("Yes");
            for (NodeType type : nodeTypes) {
                writer.print(type);
            }
            writer.println();
        } else {
            writer.println("No");
        }
        writer.flush();
    }

    private void identifyTypeBNodes(int n, boolean[][] adj, NodeType[] types) {
        for (int i = 0; i < n; i++) {
            int degree = 0;
            for (int j = 0; j < n; j++) {
                if (i != j && adj[i][j]) {
                    degree++;
                }
            }
            if (degree == n - 1) {
                types[i] = NodeType.B;
            }
        }
    }

    private boolean canAssignTypeA(int nodeIdx, NodeType[] types, boolean[][] adj) {
        for (int j = 0; j < nodeIdx; j++) {
            if (types[j] == null) continue;

            // If connected, neighbor cannot be Type C
            if (adj[nodeIdx][j] && types[j] == NodeType.C) {
                return false;
            }
            // If not connected, neighbor cannot be Type A or Type B
            if (!adj[nodeIdx][j] && (types[j] == NodeType.A || types[j] == NodeType.B)) {
                return false;
            }
        }
        return true;
    }

    private boolean canAssignTypeC(int nodeIdx, NodeType[] types, boolean[][] adj) {
        for (int j = 0; j < nodeIdx; j++) {
            if (types[j] == null) continue;

            // If connected, neighbor cannot be Type A
            if (adj[nodeIdx][j] && types[j] == NodeType.A) {
                return false;
            }
            // If not connected, neighbor cannot be Type C or Type B
            if (!adj[nodeIdx][j] && (types[j] == NodeType.C || types[j] == NodeType.B)) {
                return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        GraphCategorizer solver = new GraphCategorizer(System.in, System.out);
        solver.solve();
    }

    /**
     * Utility class for fast I/O operations.
     */
    private static class FastReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int curChar;
        private int numChars;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (numChars == -1) throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buffer);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) return -1;
            }
            return buffer[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

