/**
 * Solves the specific graph coloring problem.
 */
class GraphSolver {

    private enum NodeType {
        A(0, 'a'),
        B(1, 'b'),
        C(2, 'c');

        final int value;
        final char label;

        NodeType(int value, char label) {
            this.value = value;
            this.label = label;
        }

        static NodeType fromInt(int i) {
            if (i == 0) return A;
            if (i == 1) return B;
            return C;
        }
    }

    public void solve(FastReader in, FastWriter out) throws IOException {
        int n = in.readInt();
        int m = in.readInt();

        boolean[][] adjacencyMatrix = new boolean[n][n];
        for (int i = 0; i < m; i++) {
            int u = in.readInt() - 1;
            int v = in.readInt() - 1;
            if (u >= 0 && u < n && v >= 0 && v < n) {
                adjacencyMatrix[u][v] = adjacencyMatrix[v][u] = true;
            }
        }

        // Find two nodes that are not connected
        int nonAdjacentU = -1;
        int nonAdjacentV = -1;
        search:
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (!adjacencyMatrix[i][j]) {
                    nonAdjacentU = i;
                    nonAdjacentV = j;
                    break search;
                }
            }
        }

        // Case 1: Complete Graph
        if (nonAdjacentU == -1) {
            out.println("Yes");
            for (int i = 0; i < n; i++) {
                out.append('a');
            }
            out.println();
            return;
        }

        // Case 2: Classify nodes based on relationship to the non-adjacent pair
        int[] nodeTypes = new int[n];
        Arrays.fill(nodeTypes, -1); // -1 means unassigned

        for (int i = 0; i < n; i++) {
            boolean adjToU = adjacencyMatrix[i][nonAdjacentU];
            boolean adjToV = adjacencyMatrix[i][nonAdjacentV];

            if (i == nonAdjacentU || (adjToU && !adjToV)) {
                nodeTypes[i] = NodeType.A.value;
            } else if (i == nonAdjacentV || (adjToV && !adjToU)) {
                nodeTypes[i] = NodeType.C.value;
            } else if (adjToU && adjToV) {
                nodeTypes[i] = NodeType.B.value;
            }
        }

        // Validate assignment: every node must have a type
        for (int i = 0; i < n; i++) {
            if (nodeTypes[i] == -1) {
                out.println("No");
                return;
            }
        }

        // Validate adjacency constraints: 
        // Edge exists IF AND ONLY IF |type(i) - type(j)| <= 1
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                boolean shouldHaveEdge = Math.abs(nodeTypes[i] - nodeTypes[j]) <= 1;
                if (shouldHaveEdge != adjacencyMatrix[i][j]) {
                    out.println("No");
                    return;
                }
            }
        }

        // Output result
        out.println("Yes");
        for (int i = 0; i < n; i++) {
            out.append(NodeType.fromInt(nodeTypes[i]).label);
        }
        out.println();
    }
}

/**
 * High-performance input reader.
 */
class FastReader implements AutoCloseable {
    private final InputStream inputStream;
    private final byte[] buffer = new byte[1 << 13];
    private int bufferLen;
    private int bufferOffset;
    private int nextByte;

    public FastReader(InputStream is) throws IOException {
        this.inputStream = is;
        this.nextByte = readByte();
    }

    private int readByte() throws IOException {
        if (bufferOffset >= bufferLen) {
            bufferOffset = 0;
            bufferLen = inputStream.read(buffer);
            if (bufferLen <= 0) return -1;
        }
        return buffer[bufferOffset++] & 0xFF;
    }

    public int readInt() throws IOException {
        skipWhitespace();
        if (nextByte == -1) return 0;

        int sign = 1;
        if (nextByte == '+') {
            nextByte = readByte();
        } else if (nextByte == '-') {
            sign = -1;
            nextByte = readByte();
        }

        int val = 0;
        while (nextByte >= '0' && nextByte <= '9') {
            val = val * 10 + (nextByte - '0');
            nextByte = readByte();
        }
        return val * sign;
    }

    private void skipWhitespace() throws IOException {
        while (nextByte != -1 && nextByte <= 32) {
            nextByte = readByte();
        }
    }

    @Override
    public void close() throws IOException {
        inputStream.close();
    }
}

/**
 * High-performance output writer.
 */
class FastWriter implements AutoCloseable, Appendable {
    private static final int THRESHOLD = 1 << 13;
    private final Writer writer;
    private final StringBuilder cache = new StringBuilder(THRESHOLD * 2);

    public FastWriter(OutputStream os) {
        this.writer = new OutputStreamWriter(os);
    }

    public FastWriter append(char c) throws IOException {
        cache.append(c);
        checkThreshold();
        return this;
    }

    public FastWriter append(String s) throws IOException {
        cache.append(s);
        checkThreshold();
        return this;
    }

    @Override
    public Appendable append(CharSequence cs) throws IOException {
        cache.append(cs);
        checkThreshold();
        return this;
    }

    @Override
    public Appendable append(CharSequence cs, int start, int end) throws IOException {
        cache.append(cs, start, end);
        checkThreshold();
        return this;
    }

    public void println(String s) throws IOException {
        append(s).append('\n');
    }

    public void println() throws IOException {
        append('\n');
    }

    private void checkThreshold() throws IOException {
        if (cache.length() >= THRESHOLD) {
            flush();
        }
    }

    public void flush() throws IOException {
        if (cache.length() > 0) {
            writer.write(cache.toString());
            cache.setLength(0);
        }
        writer.flush();
    }

    @Override
    public void close() throws IOException {
        flush();
        writer.close();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * GraphAnalyzer solves a graph property problem where we identify "universal" nodes
 * (connected to all other nodes) and validate the structure of the remaining subgraph.
 * 
 * The non-universal subgraph must consist of at most two disjoint cliques 
 * such that no three nodes form an independent set or a path of length 2.
 */
public class GraphAnalyzer {

    private static final char LABEL_A = 'a';
    private static final char LABEL_B = 'b';
    private static final char LABEL_C = 'c';
    private static final char UNLABELED = '\0';

    private final int nodeCount;
    private final int edgeCount;
    private final boolean[][] adjacencyMatrix;
    private final char[] nodeLabels;

    public GraphAnalyzer(int nodeCount, int edgeCount, boolean[][] adjacencyMatrix) {
        this.nodeCount = nodeCount;
        this.edgeCount = edgeCount;
        this.adjacencyMatrix = adjacencyMatrix;
        this.nodeLabels = new char[nodeCount];
    }

    /**
     * Orchestrates the logic: Identifying universal nodes, validating triplets,
     * and assigning labels.
     */
    public void solve() {
        identifyUniversalNodes();

        if (!validateNonUniversalTriplets()) {
            System.out.println("No");
            return;
        }

        System.out.println("Yes");
        assignNodeLabels();
        System.out.println(new String(nodeLabels));
    }

    /**
     * Marks nodes that are connected to every other node as 'b'.
     */
    private void identifyUniversalNodes() {
        for (int i = 0; i < nodeCount; i++) {
            boolean isConnectedToAll = true;
            for (int j = 0; j < nodeCount; j++) {
                if (i == j) continue;
                if (!adjacencyMatrix[i][j]) {
                    isConnectedToAll = false;
                    break;
                }
            }
            if (isConnectedToAll) {
                nodeLabels[i] = LABEL_B;
            }
        }
    }

    /**
     * Validates that for every triplet of non-universal nodes, 
     * the number of edges is either 1 or 3.
     * 
     * @return true if the condition holds, false otherwise.
     */
    private boolean validateNonUniversalTriplets() {
        for (int i = 0; i < nodeCount; i++) {
            for (int j = i + 1; j < nodeCount; j++) {
                for (int k = j + 1; k < nodeCount; k++) {
                    // We only check triplets consisting entirely of non-universal nodes
                    if (nodeLabels[i] != UNLABELED || nodeLabels[j] != UNLABELED || nodeLabels[k] != UNLABELED) {
                        continue;
                    }

                    int edgeCountInTriplet = countEdgesInTriplet(i, j, k);
                    // The problem constraint: edge count must not be 0 or 2
                    if (edgeCountInTriplet == 0 || edgeCountInTriplet == 2) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    private int countEdgesInTriplet(int i, int j, int k) {
        int count = 0;
        if (adjacencyMatrix[i][j]) count++;
        if (adjacencyMatrix[j][k]) count++;
        if (adjacencyMatrix[i][k]) count++;
        return count;
    }

    /**
     * Assigns 'a' or 'c' to the non-universal nodes based on their connectivity.
     * This effectively colors the disjoint components of the non-universal subgraph.
     */
    private void assignNodeLabels() {
        char nextAvailableLabel = LABEL_A;

        for (int i = 0; i < nodeCount; i++) {
            if (nodeLabels[i] != UNLABELED) {
                continue;
            }

            boolean componentFound = false;
            // Try to see if this node belongs to a component already labeled
            for (int j = 0; j < nodeCount; j++) {
                if (adjacencyMatrix[i][j] && nodeLabels[j] != UNLABELED && nodeLabels[j] != LABEL_B) {
                    nodeLabels[i] = nodeLabels[j];
                    componentFound = true;
                    break;
                }
            }

            // If it's a new component, assign the current available label
            if (!componentFound) {
                nodeLabels[i] = nextAvailableLabel;
                // After the first component ('a'), we switch to the next label ('c')
                if (nextAvailableLabel == LABEL_A) {
                    nextAvailableLabel = LABEL_C;
                }
            }
        }
    }

    /**
     * Fast I/O reader for efficient input processing.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        String nStr = reader.next();
        if (nStr == null) return;

        int n = Integer.parseInt(nStr);
        int m = reader.nextInt();

        boolean[][] adj = new boolean[n][n];
        for (int i = 0; i < m; i++) {
            int u = reader.nextInt() - 1;
            int v = reader.nextInt() - 1;
            // Guard against out of bounds or self-loops if necessary
            if (u >= 0 && u < n && v >= 0 && v < n) {
                adj[u][v] = adj[v][u] = true;
            }
        }

        GraphAnalyzer analyzer = new GraphAnalyzer(n, m, adj);
        analyzer.solve();
    }
}

import java.io.*;
import java.util.*;

/**
 * This program solves a graph coloring problem: 
 * Can we color the graph with colors 'a', 'b', and 'c' such that 
 * no two adjacent nodes have the same color AND no node of color 'a' 
 * is adjacent to a node of color 'c'?
 * 
 * Logic:
 * 1. The nodes colored 'a' and 'c' must form a bipartite graph in the 
 *    complement of the original graph.
 * 2. Nodes connected to all other nodes (universal nodes) are assigned color 'b'.
 * 3. We verify if any original edges exist between 'a' and 'c' nodes.
 */
public class Main {

    public static void main(String[] args) {
        try (FastReader in = new FastReader(System.in);
             PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)))) {

            GraphColoringSolver solver = new GraphColoringSolver();
            solver.solve(in, out);

        } catch (IOException e) {
            System.err.println("Error reading/writing: " + e.getMessage());
        }
    }

    static class GraphColoringSolver {
        private static final int COLOR_A = 1;
        private static final int COLOR_B = 2;
        private static final int COLOR_C = 3;
        private static final char[] COLOR_CHARS = {'a', 'b', 'c'};

        private boolean[][] adjMatrix;
        private int[] nodeColors;
        private int nodeCount;

        public void solve(FastReader in, PrintWriter out) throws IOException {
            this.nodeCount = in.nextInt();
            int edgeCount = in.nextInt();

            if (nodeCount == 0) {
                out.println("Yes");
                return;
            }

            adjMatrix = new boolean[nodeCount][nodeCount];
            nodeColors = new int[nodeCount];

            for (int i = 0; i < edgeCount; i++) {
                int u = in.nextInt() - 1;
                int v = in.nextInt() - 1;
                if (u >= 0 && u < nodeCount && v >= 0 && v < nodeCount) {
                    adjMatrix[u][v] = adjMatrix[v][u] = true;
                }
            }

            // Step 1: Try to color the complement graph with colors A (1) and C (3).
            // The complement graph being bipartite ensures 'a' and 'c' nodes 
            // can be separated effectively.
            for (int i = 0; i < nodeCount; i++) {
                if (nodeColors[i] == 0) {
                    if (!isComplementBipartite(i, -1, COLOR_A)) {
                        out.println("No");
                        return;
                    }
                }
            }

            // Step 2: Identify universal nodes (connected to everyone else).
            // These nodes are assigned color B (2).
            int[] degrees = new int[nodeCount];
            for (int i = 0; i < nodeCount; i++) {
                int degree = 0;
                for (int j = 0; j < nodeCount; j++) {
                    if (i != j && adjMatrix[i][j]) {
                        degree++;
                    }
                }
                degrees[i] = degree;
                if (degree == nodeCount - 1) {
                    nodeColors[i] = COLOR_B;
                }
            }

            // Step 3: Conflict check.
            // Verify no edge exists in the original graph between color A and color C.
            for (int i = 0; i < nodeCount; i++) {
                for (int j = i + 1; j < nodeCount; j++) {
                    if (adjMatrix[i][j]) {
                        if (isConflict(nodeColors[i], nodeColors[j])) {
                            out.println("No");
                            return;
                        }
                    }
                }
            }

            // Output results
            out.println("Yes");
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < nodeCount; i++) {
                sb.append(COLOR_CHARS[nodeColors[i] - 1]);
            }
            out.println(sb.toString());
        }

        /**
         * Performs a DFS on the complement graph to check for bipartiteness.
         * Colors used: COLOR_A (1) and COLOR_C (3).
         */
        private boolean isComplementBipartite(int u, int p, int color) {
            nodeColors[u] = color;
            int nextColor = (color == COLOR_A) ? COLOR_C : COLOR_A;

            for (int v = 0; v < nodeCount; v++) {
                if (u == v) continue;

                // In the complement graph, an edge exists if adjMatrix[u][v] is false.
                if (!adjMatrix[u][v]) {
                    if (nodeColors[v] == 0) {
                        if (!isComplementBipartite(v, u, nextColor)) {
                            return false;
                        }
                    } else if (nodeColors[v] == color) {
                        // Found an odd cycle in the complement graph
                        return false;
                    }
                }
            }
            return true;
        }

        private boolean isConflict(int color1, int color2) {
            // Conflict if one is A (1) and the other is C (3)
            return Math.abs(color1 - color2) == 2;
        }
    }

    /**
     * Efficiently reads input using a byte buffer.
     */
    static class FastReader implements AutoCloseable {
        private final InputStream inputStream;
        private final byte[] buffer = new byte[1024];
        private int pointer = 0;
        private int bufferLength = 0;

        public FastReader(InputStream inputStream) {
            this.inputStream = inputStream;
        }

        private int readByte() throws IOException {
            if (pointer >= bufferLength) {
                pointer = 0;
                bufferLength = inputStream.read(buffer);
                if (bufferLength <= 0) return -1;
            }
            return buffer[pointer++];
        }

        public int nextInt() throws IOException {
            int num = 0;
            int b = readByte();
            boolean negative = false;

            while (b != -1 && b <= 32) b = readByte();
            if (b == -1) return 0;

            if (b == '-') {
                negative = true;
                b = readByte();
            }

            while (b >= '0' && b <= '9') {
                num = num * 10 + (b - '0');
                b = readByte();
            }

            return negative ? -num : num;
        }

        @Override
        public void close() throws IOException {
            inputStream.close();
        }
    }
}

import java.io.*;
