/**
 * A program to solve a graph coloring constraint problem.
 * Constraints:
 * - For every edge (u, v): |color[u] - color[v]| != 2
 * - For every non-edge (u, v): |color[u] - color[v]| > 1
 * Colors used are 'a', 'b', and 'c'.
 */
public class Main {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);

        try (PrintWriter writer = new PrintWriter(System.out)) {
            int nodesCount = scanner.nextInt();
            int edgesCount = scanner.nextInt();

            Graph graph = new Graph(nodesCount);
            for (int i = 0; i < edgesCount; i++) {
                int u = scanner.nextInt() - 1;
                int v = scanner.nextInt() - 1;
                graph.addEdge(u, v);
            }

            ColoringSolver solver = new ColoringSolver(graph);
            Result result = solver.solve();

            if (result.isSuccessful()) {
                writer.println("Yes");
                writer.println(result.getColors());
            } else {
                writer.println("No");
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * Represents the result of the coloring operation.
     */
    static class Result {
        private final boolean success;
        private final String colors;

        public Result(boolean success, String colors) {
            this.success = success;
            this.colors = colors;
        }

        public boolean isSuccessful() {
            return success;
        }

        public String getColors() {
            return colors;
        }
    }

    /**
     * Encapsulates the graph structure.
     */
    static class Graph {
        private final int nodesCount;
        private final boolean[][] adjacencyMatrix;

        public Graph(int nodesCount) {
            this.nodesCount = nodesCount;
            this.adjacencyMatrix = new boolean[nodesCount][nodesCount];
        }

        public void addEdge(int u, int v) {
            if (u >= 0 && u < nodesCount && v >= 0 && v < nodesCount) {
                adjacencyMatrix[u][v] = true;
                adjacencyMatrix[v][u] = true;
            }
        }

        public int getNodesCount() {
            return nodesCount;
        }

        public boolean isAdjacent(int u, int v) {
            return adjacencyMatrix[u][v];
        }
    }

    /**
     * Contains the logic to assign colors and validate constraints.
     */
    static class ColoringSolver {
        private final Graph graph;
        private static final char COLOR_A = 'a';
        private static final char COLOR_B = 'b';
        private static final char COLOR_C = 'c';

        public ColoringSolver(Graph graph) {
            this.graph = graph;
        }

        public Result solve() {
            int n = graph.getNodesCount();
            char[] nodeColors = new char[n];
            Arrays.fill(nodeColors, COLOR_B);

            // Greedy assignment based on non-edge constraints
            assignColors(n, nodeColors);

            // Validation based on adjacency constraints
            if (isValid(n, nodeColors)) {
                return new Result(true, new String(nodeColors));
            } else {
                return new Result(false, null);
            }
        }

        private void assignColors(int n, char[] nodeColors) {
            for (int i = 0; i < n; i++) {
                for (int j = i + 1; j < n; j++) {
                    if (!graph.isAdjacent(i, j)) {
                        applyNonEdgeConstraint(i, j, nodeColors);
                    }
                }
            }
        }

        private void applyNonEdgeConstraint(int i, int j, char[] nodeColors) {
            if (nodeColors[i] == COLOR_A) {
                nodeColors[j] = COLOR_C;
            } else if (nodeColors[i] == COLOR_C) {
                nodeColors[j] = COLOR_A;
            } else if (nodeColors[j] == COLOR_A) {
                nodeColors[i] = COLOR_C;
            } else if (nodeColors[j] == COLOR_C) {
                nodeColors[i] = COLOR_A;
            } else {
                // Both are 'b', force an 'a'-'c' relationship
                nodeColors[i] = COLOR_A;
                nodeColors[j] = COLOR_C;
            }
        }

        private boolean isValid(int n, char[] nodeColors) {
            for (int i = 0; i < n; i++) {
                for (int j = i + 1; j < n; j++) {
                    int colorDiff = Math.abs(nodeColors[i] - nodeColors[j]);
                    boolean isEdge = graph.isAdjacent(i, j);

                    // Edge constraint: diff cannot be 2 (i.e., cannot be 'a' and 'c')
                    if (isEdge && colorDiff == 2) {
                        return false;
                    }
                    // Non-edge constraint: diff must be > 1 (i.e., must be 'a' and 'c')
                    if (!isEdge && colorDiff <= 1) {
                        return false;
                    }
                }
            }
            return true;
        }
    }

    /**
     * High-performance utility for reading input.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream inputStream) {
            this.reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

