/**
 * Solves the specific graph coloring and partitioning problem.
 */
class GraphColoringSolver {
    private final int nodeCount;
    private final int[][] adjacencyMatrix;
    private final int[] degrees;

    // Character constants to avoid magic characters
    private static final char LABEL_A = 'a';
    private static final char LABEL_B = 'b';
    private static final char LABEL_C = 'c';
    private static final char UNASSIGNED = ' ';

    public GraphColoringSolver(int nodeCount, int[][] adjacencyMatrix, int[] degrees) {
        this.nodeCount = nodeCount;
        this.adjacencyMatrix = adjacencyMatrix;
        this.degrees = degrees;
    }

    /**
     * Executes the coloring algorithm and validates the result.
     * @return A Solution object containing the outcome and labels.
     */
    public Solution solve() {
        char[] labels = assignLabels();
        if (validateLabels(labels)) {
            return new Solution(true, labels);
        }
        return new Solution(false, null);
    }

    private char[] assignLabels() {
        char[] labels = new char[nodeCount];
        Arrays.fill(labels, UNASSIGNED);

        // Rule 1: Nodes connected to every other node are assigned label 'b'
        for (int i = 0; i < nodeCount; i++) {
            if (degrees[i] == nodeCount - 1) {
                labels[i] = LABEL_B;
            }
        }

        // Rule 2: Partition the remaining unassigned nodes into 'a' and 'c' groups
        for (int i = 0; i < nodeCount; i++) {
            if (labels[i] == UNASSIGNED) {
                labels[i] = LABEL_A;
                for (int j = 0; j < nodeCount; j++) {
                    if (i != j && labels[j] == UNASSIGNED) {
                        // If node j is connected to the representative 'a' node, label it 'a', else 'c'
                        labels[j] = (adjacencyMatrix[i][j] == 1) ? LABEL_A : LABEL_C;
                    }
                }
            }
        }
        return labels;
    }

    private boolean validateLabels(char[] labels) {
        for (int i = 0; i < nodeCount; i++) {
            for (int j = i + 1; j < nodeCount; j++) {
                boolean hasEdge = (adjacencyMatrix[i][j] == 1);
                int diff = Math.abs(labels[i] - labels[j]);

                // Rule: 'a' and 'c' nodes (distance 2) must not have an edge between them
                if (diff == 2 && hasEdge) {
                    return false;
                }
                // Rule: 'a'-'b', 'b'-'c', or identical labels (distance < 2) must have an edge
                if (diff < 2 && !hasEdge) {
                    return false;
                }
            }
        }
        return true;
    }
}

