import java.util.*;
import java.io.*;

/**
 * Problem: Assign labels 'a', 'b', or 'c' to nodes such that:
 * 1. Connected nodes have the same label.
 * 2. Non-connected nodes have different labels.
 * 
 * Solution:
 * This condition implies that every connected component must be a clique 
 * (all nodes in a component must be connected to each other).
 * Additionally, since nodes in different components are by definition 
 * not connected, every component must have a unique label.
 * Since we only have 3 labels, there can be at most 3 components.
 */
public class GraphColorer {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = reader.nextInt();
            int m = reader.nextInt();

            DSU dsu = new DSU(n);
            for (int i = 0; i < m; i++) {
                int u = reader.nextInt() - 1;
                int v = reader.nextInt() - 1;
                dsu.union(u, v);
            }

            if (solve(n, m, dsu, out)) {
                // Success handled inside solve
            } else {
                out.println("No");
            }

        } catch (Exception e) {
            // Handle empty input or parsing errors
        } finally {
            out.flush();
            out.close();
        }
    }

    private static boolean solve(int n, int m, DSU dsu, PrintWriter out) {
        // Rule 1: There must be at most 3 components to satisfy the unique label requirement
        if (dsu.numComponents > 3) {
            return false;
        }

        // Rule 2: Every component must be a clique.
        // In a clique of size S, there are exactly S*(S-1)/2 edges.
        // Since edges only exist within components, the total number of edges M 
        // must equal the sum of (size * (size - 1) / 2) for all components.
        long expectedEdges = 0;
        Map<Integer, Integer> componentSizes = new HashMap<>();
        for (int i = 0; i < n; i++) {
            int root = dsu.find(i);
            componentSizes.put(root, dsu.size[root]);
        }

        for (int size : componentSizes.values()) {
            expectedEdges += (long) size * (size - 1) / 2;
        }

        if (expectedEdges != m) {
            return false;
        }

        // If both conditions pass, it is possible to color the graph.
        out.println("Yes");
        char[] availableLabels = {'a', 'b', 'c'};
        Map<Integer, Character> rootToLabel = new HashMap<>();
        char[] result = new char[n];
        int labelIdx = 0;

        for (int i = 0; i < n; i++) {
            int root = dsu.find(i);
            if (!rootToLabel.containsKey(root)) {
                rootToLabel.put(root, availableLabels[labelIdx++]);
            }
            result[i] = rootToLabel.get(root);
        }

        out.println(new String(result));
        return true;
    }

    /**
     * Disjoint Set Union (DSU) to manage connected components.
     */
    static class DSU {
        int[] parent;
        int[] size;
        int numComponents;

        DSU(int n) {
            parent = new int[n];
            size = new int[n];
            numComponents = n;
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        int find(int i) {
            if (parent[i] == i) return i;
            return parent[i] = find(parent[i]); // Path compression
        }

        void union(int i, int j) {
            int rootI = find(i);
            int rootJ = find(j);
            if (rootI != rootJ) {
                // Union by size
                if (size[rootI] < size[rootJ]) {
                    int temp = rootI;
                    rootI = rootJ;
                    rootJ = temp;
                }
                parent[rootJ] = rootI;
                size[rootI] += size[rootJ];
                numComponents--;
            }
        }
    }

    /**
     * Efficient input reader.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

