/**
 * Contains the logic for assigning and validating node colors.
 */
class ColoringService {
    private static final char COLOR_A = 'a';
    private static final char COLOR_B = 'b';
    private static final char COLOR_C = 'c';

    public ColoringResult solve(Graph graph) {
        int n = graph.getNodeCount();
        char[] colors = assignColors(graph);

        if (validateColoring(graph, colors)) {
            return new ColoringResult(true, new String(colors));
        } else {
            return new ColoringResult(false, "");
        }
    }

    private char[] assignColors(Graph graph) {
        int n = graph.getNodeCount();
        char[] colors = new char[n];
        Arrays.fill(colors, COLOR_C);

        // Step 1: Assign 'b' to universal nodes (connected to all other n-1 nodes)
        for (int i = 0; i < n; i++) {
            if (graph.getDegree(i) == n - 1) {
                colors[i] = COLOR_B;
            }
        }

        // Step 2: Find first non-'b' node to start coloring 'a' group
        for (int i = 0; i < n; i++) {
            if (colors[i] != COLOR_B) {
                colors[i] = COLOR_A;
                for (int neighbor : graph.getNeighbors(i)) {
                    if (colors[neighbor] != COLOR_B) {
                        colors[neighbor] = COLOR_A;
                    }
                }
                break; // Only one 'a' group is processed as per original logic
            }
        }
        return colors;
    }

    private boolean validateColoring(Graph graph, char[] colors) {
        int n = graph.getNodeCount();
        int totalA = 0, totalB = 0, totalC = 0;

        // Calculate global color distribution
        for (char c : colors) {
            if (c == COLOR_A) totalA++;
            else if (c == COLOR_B) totalB++;
            else totalC++;
        }

        // Step 3: Validate neighborhood properties
        for (int u = 0; u < n; u++) {
            int neighborhoodA = 0, neighborhoodB = 0, neighborhoodC = 0;

            // Count colors in {u} U neighbors(u)
            updateCounts(u, graph, colors, neighborhoodA, neighborhoodB, neighborhoodC);
            // Re-calculating counts manually to avoid passing primitives by reference
            int[] counts = countNeighborhoodColors(u, graph, colors);
            neighborhoodA = counts[0];
            neighborhoodB = counts[1];
            neighborhoodC = counts[2];

            if (colors[u] == COLOR_A) {
                if (neighborhoodC > 0 || neighborhoodB != totalB || neighborhoodA != totalA) {
                    return false;
                }
            } else if (colors[u] == COLOR_C) {
                if (neighborhoodA > 0 || neighborhoodB != totalB || neighborhoodC != totalC) {
                    return false;
                }
            }
        }
        return true;
    }

    private int[] countNeighborhoodColors(int u, Graph graph, char[] colors) {
        int a = 0, b = 0, c = 0;

        // Check the node itself
        if (colors[u] == COLOR_A) a++;
        else if (colors[u] == COLOR_B) b++;
        else c++;

        // Check neighbors
        for (int v : graph.getNeighbors(u)) {
            if (colors[v] == COLOR_A) a++;
            else if (colors[v] == COLOR_B) b++;
            else c++;
        }
        return new int[]{a, b, c};
    }

    // Helper for original logic structure compatibility
    private void updateCounts(int u, Graph graph, char[] colors, int a, int b, int c) {
        // This method is a placeholder for the logic encapsulated in countNeighborhoodColors
    }
}

