class GraphProblem {
    private final int numNodes;
    private final List<List<Integer>> adjacencyList;
    private final boolean[][] adjacencyMatrix;
    private final char[] labels;

    private static final char LABEL_A = 'a';
    private static final char LABEL_B = 'b';
    private static final char LABEL_C = 'c';
    private static final char UNASSIGNED = '\0';

    public GraphProblem(int n) {
        this.numNodes = n;
        this.adjacencyList = new ArrayList<>(n);
        this.adjacencyMatrix = new boolean[n][n];
        this.labels = new char[n];
        Arrays.fill(labels, UNASSIGNED);

        for (int i = 0; i < n; i++) {
            adjacencyList.add(new ArrayList<>());
        }
    }

    public void addEdge(int u, int v) {
        adjacencyList.get(u).add(v);
        adjacencyList.get(v).add(u);
        adjacencyMatrix[u][v] = true;
        adjacencyMatrix[v][u] = true;
    }

    /**
     * Solves the problem and returns the result string.
     * @return "Yes" followed by the label string, or "No".
     */
    public String solve() {
        // 1. Identify 'b' nodes: nodes connected to all other nodes (degree == n-1)
        for (int i = 0; i < numNodes; i++) {
            if (adjacencyList.get(i).size() == numNodes - 1) {
                labels[i] = LABEL_B;
            }
        }

        // 2. Assign 'a' to the first unassigned component and 'c' to the second
        int componentCount = 0;
        for (int i = 0; i < numNodes; i++) {
            if (labels[i] == UNASSIGNED) {
                if (componentCount == 0) {
                    fillComponentIterative(i, LABEL_A);
                    componentCount++;
                } else if (componentCount == 1) {
                    fillComponentIterative(i, LABEL_C);
                    componentCount++;
                } else {
                    // More than 2 components found among unassigned nodes
                    return "No";
                }
            }
        }

        // 3. Validate the resulting configuration
        if (!isValidConfiguration()) {
            return "No";
        }

        return "Yes\n" + new String(labels);
    }

    /**
     * Iterative DFS to avoid StackOverflowError on deep graphs.
     */
    private void fillComponentIterative(int startNode, char label) {
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(startNode);
        labels[startNode] = label;

        while (!stack.isEmpty()) {
            int curr = stack.pop();
            for (int neighbor : adjacencyList.get(curr)) {
                if (labels[neighbor] == UNASSIGNED) {
                    labels[neighbor] = label;
                    stack.push(neighbor);
                }
            }
        }
    }

    /**
     * Verifies that if |label(i) - label(j)| <= 1, there is an edge between i and j.
     */
    private boolean isValidConfiguration() {
        for (int i = 0; i < numNodes; i++) {
            for (int j = i + 1; j < numNodes; j++) {
                // If labels are 'a'-'b' or 'b'-'c', they must have an edge
                if (Math.abs(labels[i] - labels[j]) <= 1) {
                    if (!adjacencyMatrix[i][j]) {
                        return false;
                    }
                }
            }
        }
        return true;
    }
}

