import java.io.*;
import java.util.*;

/**
 * Main class to execute the graph coloring task.
 */
public class Main {
    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        TaskSolver solver = new TaskSolver();
        solver.solve(reader, writer);

        writer.flush();
        writer.close();
    }

    /**
     * Represents the possible colors assigned to a node.
     */
    enum NodeColor {
        UNASSIGNED('\0'),
        A('a'),
        B('b'),
        C('c');

        private final char label;

        NodeColor(char label) {
            this.label = label;
        }

        public char getLabel() {
            return label;
        }
    }

    /**
     * Encapsulates the graph structure and its properties.
     */
    static class Graph {
        private final int nodeCount;
        private final boolean[][] adjacencyMatrix;
        private final int[] degrees;

        public Graph(int nodeCount) {
            this.nodeCount = nodeCount;
            this.adjacencyMatrix = new boolean[nodeCount][nodeCount];
            this.degrees = new int[nodeCount];
        }

        public void addEdge(int u, int v) {
            if (!adjacencyMatrix[u][v]) {
                adjacencyMatrix[u][v] = adjacencyMatrix[v][u] = true;
                degrees[u]++;
                degrees[v]++;
            }
        }

        public boolean isConnected(int u, int v) {
            return adjacencyMatrix[u][v];
        }

        public int getNodeCount() {
            return nodeCount;
        }

        public int getDegree(int u) {
            return degrees[u];
        }
    }

    /**
     * Contains the logic to solve the specific graph coloring problem.
     */
    static class TaskSolver {

        public void solve(FastReader in, PrintWriter out) {
            int nodeCount = in.nextInt();
            int edgeCount = in.nextInt();

            Graph graph = new Graph(nodeCount);
            for (int i = 0; i < edgeCount; i++) {
                int u = in.nextInt() - 1;
                int v = in.nextInt() - 1;
                graph.addEdge(u, v);
            }

            NodeColor[] colors = assignColors(graph);

            if (validateColoring(graph, colors)) {
                out.println("Yes");
                printColors(colors, out);
            } else {
                out.println("No");
            }
        }

        /**
         * Logic to assign colors based on node degrees and connectivity.
         */
        private NodeColor[] assignColors(Graph graph) {
            int n = graph.getNodeCount();
            NodeColor[] colors = new NodeColor[n];
            Arrays.fill(colors, NodeColor.UNASSIGNED);

            // Step 1: Universal nodes (connected to all others) are colored 'B'
            for (int i = 0; i < n; i++) {
                if (graph.getDegree(i) == n - 1) {
                    colors[i] = NodeColor.B;
                }
            }

            // Step 2: Pick the first non-B node, color it 'A' and its non-B neighbors 'A'
            for (int i = 0; i < n; i++) {
                if (colors[i] != NodeColor.B) {
                    colors[i] = NodeColor.A;
                    for (int j = 0; j < n; j++) {
                        if (i != j && graph.isConnected(i, j) && colors[j] == NodeColor.UNASSIGNED) {
                            colors[j] = NodeColor.A;
                        }
                    }
                    break;
                }
            }

            // Step 3: All remaining unassigned nodes are colored 'C'
            for (int i = 0; i < n; i++) {
                if (colors[i] == NodeColor.UNASSIGNED) {
                    colors[i] = NodeColor.C;
                }
            }

            return colors;
        }

        /**
         * Validates if the coloring follows the rule: 
         * Nodes are connected IF AND ONLY IF they are not an (A, C) pair.
         */
        private boolean validateColoring(Graph graph, NodeColor[] colors) {
            int n = graph.getNodeCount();
            for (int i = 0; i < n; i++) {
                for (int j = i + 1; j < n; j++) {
                    boolean connected = graph.isConnected(i, j);
                    boolean isACPair = isAandCColorPair(colors[i], colors[j]);

                    // If connected, they must NOT be an A-C pair
                    if (connected && isACPair) return false;
                    // If not connected, they MUST be an A-C pair
                    if (!connected && !isACPair) return false;
                }
            }
            return true;
        }

        private boolean isAandCColorPair(NodeColor c1, NodeColor c2) {
            return (c1 == NodeColor.A && c2 == NodeColor.C) || 
                   (c1 == NodeColor.C && c2 == NodeColor.A);
        }

        private void printColors(NodeColor[] colors, PrintWriter out) {
            StringBuilder sb = new StringBuilder();
            for (NodeColor color : colors) {
                sb.append(color.getLabel());
            }
            out.println(sb.toString());
        }
    }

    /**
     * Optimized reader for fast I/O operations.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * Refactored Graph Analysis Program.
 * The program identifies if a graph consists of a set of universal nodes 
 * and at most two disjoint cliques among the remaining nodes.
 */
public class AimFundC {

    /**
     * Represents the role of each node in the graph structure.
     */
    enum NodeRole {
        COMPONENT_A('a'),
        UNIVERSAL('b'),
        COMPONENT_C('c');

        private final char label;

        NodeRole(char label) {
            this.label = label;
        }

        public char getLabel() {
            return label;
        }
    }

    /**
     * Data Transfer Object to hold the results of the graph analysis.
     */
    static class AnalysisResult {
        private final boolean valid;
        private final NodeRole[] roles;

        public AnalysisResult(boolean valid, NodeRole[] roles) {
            this.valid = valid;
            this.roles = roles;
        }

        public boolean isValid() {
            return valid;
        }

        public NodeRole[] getRoles() {
            return roles;
        }
    }

    /**
     * Encapsulates graph data and the algorithms required to analyze its structure.
     */
    static class Graph {
        private final int nodeCount;
        private final boolean[][] adj;

        public Graph(int nodeCount) {
            this.nodeCount = nodeCount;
            this.adj = new boolean[nodeCount][nodeCount];
        }

        public void addEdge(int u, int v) {
            if (isValidIndex(u) && isValidIndex(v)) {
                adj[u][v] = true;
                adj[v][u] = true;
            }
        }

        private boolean isValidIndex(int index) {
            return index >= 0 && index < nodeCount;
        }

        /**
         * Performs the structural analysis of the graph.
         * @return An AnalysisResult containing validity and node roles.
         */
        public AnalysisResult analyze() {
            NodeRole[] roles = new NodeRole[nodeCount];
            boolean[] isUniversal = new boolean[nodeCount];

            // 1. Identify Universal Nodes (connected to all other N-1 nodes)
            for (int i = 0; i < nodeCount; i++) {
                if (calculateDegree(i) == nodeCount - 1) {
                    isUniversal[i] = true;
                    roles[i] = NodeRole.UNIVERSAL;
                }
            }

            // 2. Find the first non-universal component using DFS
            boolean[] visited = new boolean[nodeCount];
            int startNode = findFirstNonUniversal(isUniversal);
            if (startNode != -1) {
                performDFS(startNode, isUniversal, visited);
            }

            // 3. Assign roles for the remaining non-universal nodes
            for (int i = 0; i < nodeCount; i++) {
                if (!isUniversal[i]) {
                    roles[i] = visited[i] ? NodeRole.COMPONENT_A : NodeRole.COMPONENT_C;
                }
            }

            // 4. Validate that each identified non-universal component is a clique
            boolean isValid = validateCliques(isUniversal, visited);

            return new AnalysisResult(isValid, roles);
        }

        private int calculateDegree(int node) {
            int degree = 0;
            for (int i = 0; i < nodeCount; i++) {
                if (i != node && adj[node][i]) {
                    degree++;
                }
            }
            return degree;
        }

        private int findFirstNonUniversal(boolean[] isUniversal) {
            for (int i = 0; i < nodeCount; i++) {
                if (!isUniversal[i]) return i;
            }
            return -1;
        }

        private void performDFS(int u, boolean[] isUniversal, boolean[] visited) {
            visited[u] = true;
            for (int v = 0; v < nodeCount; v++) {
                // Only traverse nodes that are not universal and not yet visited
                if (adj[u][v] && !isUniversal[v] && !visited[v]) {
                    performDFS(v, isUniversal, visited);
                }
            }
        }

        private boolean validateCliques(boolean[] isUniversal, boolean[] visited) {
            // Check if nodes in Component A form a complete subgraph (clique)
            for (int i = 0; i < nodeCount; i++) {
                if (visited[i]) {
                    for (int j = i + 1; j < nodeCount; j++) {
                        if (visited[j] && !adj[i][j]) return false;
                    }
                }
            }

            // Check if nodes in Component C form a complete subgraph (clique)
            for (int i = 0; i < nodeCount; i++) {
                if (!isUniversal[i] && !visited[i]) {
                    for (int j = i + 1; j < nodeCount; j++) {
                        if (!isUniversal[j] && !visited[j] && !adj[i][j]) return false;
                    }
                }
            }
            return true;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) return;

        int n = scanner.nextInt();
        int m = scanner.nextInt();

        Graph graph = new Graph(n);
        for (int i = 0; i < m; i++) {
            int u = scanner.nextInt() - 1;
            int v = scanner.nextInt() - 1;
            graph.addEdge(u, v);
        }

        AnalysisResult result = graph.analyze();
        printResult(result);
    }

    /**
     * Outputs the analysis result to the standard output.
     */
    private static void printResult(AnalysisResult result) {
        PrintWriter writer = new PrintWriter(System.out);
        if (!result.isValid()) {
            writer.println("No");
        } else {
            writer.println("Yes");
            for (NodeRole role : result.getRoles()) {
                writer.print(role.getLabel());
            }
            writer.println();
        }
        writer.flush();
    }
}

import java.util.*;
import java.io.*;

/**
 * Refactored solution for the Graph Partitioning problem.
 * The goal is to partition vertices into three sets A, B, and C such that:
 * - B contains vertices connected to all other vertices.
 * - A and C are disjoint cliques.
 * - There are no edges between A and C.
 */
public class CF_624C {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = reader.nextInt();
            int m = reader.nextInt();

            Graph graph = new Graph(n);
            for (int i = 0; i < m; i++) {
                int u = reader.nextInt() - 1;
                int v = reader.nextInt() - 1;
                graph.addEdge(u, v);
            }

            ProblemSolver solver = new ProblemSolver(graph);
            solver.solve(out);
        } catch (Exception e) {
            // In a real-world scenario, use a logger.
        } finally {
            out.flush();
            out.close();
        }
    }

    static class Graph {
        int numVertices;
        List<Integer>[] adjacencyList;
        int[] degrees;

        @SuppressWarnings("unchecked")
        public Graph(int n) {
            this.numVertices = n;
            this.adjacencyList = new ArrayList[n];
            this.degrees = new int[n];
            for (int i = 0; i < n; i++) {
                adjacencyList[i] = new ArrayList<>();
            }
        }

        public void addEdge(int u, int v) {
            adjacencyList[u].add(v);
            adjacencyList[v].add(u);
            degrees[u]++;
            degrees[v]++;
        }
    }

    static class ProblemSolver {
        private final Graph graph;
        private final int n;
        private final boolean[] isTypeB;
        private final int countB;

        public ProblemSolver(Graph graph) {
            this.graph = graph;
            this.n = graph.numVertices;
            this.isTypeB = new boolean[n];

            int bCount = 0;
            for (int i = 0; i < n; i++) {
                if (graph.degrees[i] == n - 1) {
                    isTypeB[i] = true;
                    bCount++;
                }
            }
            this.countB = bCount;
        }

        public void solve(PrintWriter out) {
            char[] nodeTypes = new char[n];
            Arrays.fill(nodeTypes, '\0');

            // Assign type 'b'
            for (int i = 0; i < n; i++) {
                if (isTypeB[i]) {
                    nodeTypes[i] = 'b';
                }
            }

            List<List<Integer>> components = findNonBComponents();

            // Requirement: At most 2 cliques (A and C)
            if (components.size() > 2) {
                out.println("No");
                return;
            }

            // Assign types 'a' and 'c' to components
            char[] componentLabels = {'a', 'c'};
            for (int i = 0; i < components.size(); i++) {
                List<Integer> component = components.get(i);
                char label = componentLabels[i];

                // Verify if the component is a clique
                // A component is a clique if every node in it has a degree equal to
                // (size of component - 1) + (number of B nodes).
                int expectedDegree = (component.size() - 1) + countB;
                for (int node : component) {
                    if (graph.degrees[node] != expectedDegree) {
                        out.println("No");
                        return;
                    }
                    nodeTypes[node] = label;
                }
            }

            // Final check: Ensure all non-B nodes were assigned a type
            for (int i = 0; i < n; i++) {
                if (nodeTypes[i] == '\0') {
                    // This case handles if there are no B nodes and components logic is somehow bypassed
                    // though the component logic covers all non-B nodes.
                    out.println("No");
                    return;
                }
            }

            out.println("Yes");
            out.println(new String(nodeTypes));
        }

        /**
         * Finds connected components in the subgraph induced by non-B vertices.
         */
        private List<List<Integer>> findNonBComponents() {
            List<List<Integer>> components = new ArrayList<>();
            boolean[] visited = new boolean[n];

            for (int i = 0; i < n; i++) {
                if (!isTypeB[i] && !visited[i]) {
                    List<Integer> component = new ArrayList<>();
                    Queue<Integer> queue = new LinkedList<>();

                    queue.add(i);
                    visited[i] = true;

                    while (!queue.isEmpty()) {
                        int curr = queue.poll();
                        component.add(curr);

                        for (int neighbor : graph.adjacencyList[curr]) {
                            // Only traverse edges between non-B nodes
                            if (!isTypeB[neighbor] && !visited[neighbor]) {
                                visited[neighbor] = true;
                                queue.add(neighbor);
                            }
                        }
                    }
                    components.add(component);
                }
            }
            return components;
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

