/**
 * A solver for the graph labeling problem.
 * The goal is to assign labels {1, 2, 3} to nodes such that:
 * 1. For edges NOT in the input list (complement edges), labels must be far apart (difference > 1).
 * 2. For edges IN the input list, labels must be close (difference <= 1).
 */
public class GraphLabelingSolver {

    public static void main(String[] args) {
        // If a file path is provided, use it; otherwise, read from standard input.
        String filePath = (args.length > 0) ? args[0] : null;
        GraphLabelingSolver solver = new GraphLabelingSolver();
        solver.execute(filePath);
    }

    /**
     * Orchestrates the execution of the solver.
     *
     * @param filePath Path to the input file or null for System.in.
     */
    public void execute(String filePath) {
        try (FastReader reader = new FastReader(filePath)) {
            solve(reader);
        } catch (IOException e) {
            System.err.println("An error occurred while reading input: " + e.getMessage());
        }
    }

    /**
     * Contains the core logic of the graph labeling algorithm.
     *
     * @param reader The FastReader instance for efficient input processing.
     * @throws IOException If an I/O error occurs.
     */
    private void solve(FastReader reader) throws IOException {
        // The original code assumes exactly one test case (T=1).
        int testCases = 1;
        StringBuilder output = new StringBuilder();

        for (int t = 0; t < testCases; t++) {
            int nodeCount = reader.nextInt();
            int edgeCount = reader.nextInt();

            if (nodeCount <= 0) continue;

            // isComplementEdge[i][j] is true if the edge (i, j) is NOT in the provided input list.
            // Based on the original logic, we start with a complete graph and remove input edges.
            boolean[][] isComplementEdge = new boolean[nodeCount][nodeCount];
            for (int i = 0; i < nodeCount; i++) {
                Arrays.fill(isComplementEdge[i], true);
            }

            for (int i = 0; i < edgeCount; i++) {
                int u = reader.nextInt() - 1;
                int v = reader.nextInt() - 1;
                if (u >= 0 && u < nodeCount && v >= 0 && v < nodeCount) {
                    isComplementEdge[u][v] = isComplementEdge[v][u] = false;
                }
            }

            int[] nodeLabels = new int[nodeCount]; // 0: unassigned, 1, 2, 3: assigned labels
            boolean isValid = true;

            // Greedy label assignment logic preserved from the original implementation
            for (int i = 0; i < nodeCount; i++) {
                if (nodeLabels[i] == 1) {
                    for (int j = i + 1; j < nodeCount; j++) {
                        if (isComplementEdge[i][j]) {
                            if (nodeLabels[j] == 1) isValid = false;
                            else nodeLabels[j] = 3;
                        } else {
                            if (nodeLabels[j] == 3) isValid = false;
                        }
                    }
                } else if (nodeLabels[i] == 3) {
                    for (int j = i + 1; j < nodeCount; j++) {
                        if (isComplementEdge[i][j]) {
                            if (nodeLabels[j] == 3) isValid = false;
                            else nodeLabels[j] = 1;
                        } else {
                            if (nodeLabels[j] == 1) isValid = false;
                        }
                    }
                } else {
                    // Node is unassigned (labels[i] == 0)
                    int neededLabel = 0;
                    boolean canAssign1 = true;
                    boolean canAssign3 = true;

                    for (int j = i + 1; j < nodeCount; j++) {
                        if (isComplementEdge[i][j]) {
                            if (nodeLabels[j] == 3) {
                                if (neededLabel == 3) isValid = false;
                                neededLabel = 1;
                            } else {
                                if (neededLabel == 1) isValid = false;
                                neededLabel = 3;
                            }
                            nodeLabels[j] = (neededLabel == 1) ? 3 : 1;
                        } else {
                            if (nodeLabels[j] == 3) canAssign1 = false;
                            if (nodeLabels[j] == 1) canAssign3 = false;
                        }
                    }

                    if (neededLabel > 0) {
                        if (neededLabel == 1 && !canAssign1) isValid = false;
                        if (neededLabel == 3 && !canAssign3) isValid = false;
                        nodeLabels[i] = neededLabel;
                    } else {
                        nodeLabels[i] = 2;
                    }
                }
                if (!isValid) break;
            }

            // Final validation of the labeling against problem constraints
            if (isValid) {
                for (int i = 0; i < nodeCount; i++) {
                    for (int j = i + 1; j < nodeCount; j++) {
                        int diff = Math.abs(nodeLabels[i] - nodeLabels[j]);
                        if (isComplementEdge[i][j]) {
                            // Complement edges must have distance > 1 (e.g., 1 and 3)
                            if (diff <= 1) {
                                isValid = false;
                                break;
                            }
                        } else {
                            // Input edges must have distance <= 1
                            if (diff > 1) {
                                isValid = false;
                                break;
                            }
                        }
                    }
                    if (!isValid) break;
                }
            }

            // Build the output string
            if (isValid) {
                output.append("Yes\n");
                for (int i = 0; i < nodeCount; i++) {
                    output.append((char) ('a' + nodeLabels[i] - 1));
                }
                output.append("\n");
            } else {
                output.append("No\n");
            }
        }
        System.out.print(output.toString());
    }

    /**
     * A utility class for high-performance token-based input reading.
     */
    private static class FastReader implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(String filePath) throws IOException {
            if (filePath == null) {
                reader = new BufferedReader(new InputStreamReader(System.in));
            } else {
                reader = new BufferedReader(new FileReader(filePath));
            }
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            String s = next();
            return (s == null) ? 0 : Integer.parseInt(s);
        }

        public long nextLong() throws IOException {
            String s = next();
            return (s == null) ? 0L : Long.parseLong(s);
        }

        public double nextDouble() throws IOException {
            String s = next();
            return (s == null) ? 0.0 : Double.parseDouble(s);
        }

        @Override
        public void close() throws IOException {
            reader.close();
        }
    }
