/**
 * A utility to solve the Bipartite Graph coloring problem.
 * A graph is bipartite if we can color its vertices using two colors 
 * such that no two adjacent vertices share the same color.
 */
public class BipartiteGraphSolver {

    private static final int UNCOLORED = -1;
    private static final int COLOR_A = 0;
    private static final int COLOR_B = 1;

    private final int verticesCount;
    private final List<List<Integer>> adjacencyList;

    public BipartiteGraphSolver(int verticesCount) {
        this.verticesCount = verticesCount;
        this.adjacencyList = new ArrayList<>(verticesCount);
        for (int i = 0; i < verticesCount; i++) {
            this.adjacencyList.add(new ArrayList<>());
        }
    }

    /**
     * Adds an undirected edge between two vertices.
     * @param u source vertex (0-indexed)
     * @param v destination vertex (0-indexed)
     */
    public void addEdge(int u, int v) {
        adjacencyList.get(u).add(v);
        adjacencyList.get(v).add(u);
    }

    /**
     * Attempts to color the graph using two colors.
     * @return An array of colors (0 or 1) if bipartite, otherwise null.
     */
    public int[] solveColoring() {
        int[] colors = new int[verticesCount];
        Arrays.fill(colors, UNCOLORED);

        for (int i = 0; i < verticesCount; i++) {
            if (colors[i] == UNCOLORED) {
                if (!bfsColoring(i, colors)) {
                    return null;
                }
            }
        }
        return colors;
    }

    private boolean bfsColoring(int startNode, int[] colors) {
        Queue<Integer> queue = new LinkedList<>();

        colors[startNode] = COLOR_A;
        queue.add(startNode);

        while (!queue.isEmpty()) {
            int current = queue.poll();

            for (int neighbor : adjacencyList.get(current)) {
                if (colors[neighbor] == UNCOLORED) {
                    // Assign opposite color to neighbor
                    colors[neighbor] = 1 - colors[current];
                    queue.add(neighbor);
                } else if (colors[neighbor] == colors[current]) {
                    // Found a conflict: adjacent nodes have the same color
                    return false;
                }
            }
        }
        return true;
    }

    public static void main(String[] args) {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String line = br.readLine();
            if (line == null) return;

            StringTokenizer st = new StringTokenizer(line);
            int V = Integer.parseInt(st.nextToken());
            int E = Integer.parseInt(st.nextToken());

            BipartiteGraphSolver solver = new BipartiteGraphSolver(V);

            for (int i = 0; i < E; i++) {
                st = new StringTokenizer(br.readLine());
                int u = Integer.parseInt(st.nextToken()) - 1; // Convert 1-based to 0-based
                int v = Integer.parseInt(st.nextToken()) - 1;
                solver.addEdge(u, v);
            }

            int[] resultColors = solver.solveColoring();

            if (resultColors == null) {
                System.out.println("No");
            } else {
                System.out.println("Yes");
                System.out.println(formatColoring(resultColors));
            }

        } catch (IOException | NumberFormatException e) {
            System.err.println("Error processing input: " + e.getMessage());
        }
    }

    /**
     * Converts the integer color array into the required character format.
     * 0 -> 'a', 1 -> 'b'
     */
    private static String formatColoring(int[] colors) {
        StringBuilder sb = new StringBuilder();
        for (int color : colors) {
            // If for some reason a node is still uncolored (isolated), default to 'b'
            if (color == UNCOLORED) {
                sb.append('b');
            } else {
                sb.append((char) ('a' + color));
            }
        }
        return sb.toString();
    }
}

