/**
 * Logic for determining if a graph (derived from a complete graph by removing edges)
 * is a complete bipartite graph.
 */
class BipartiteSolver {
    private static final char COLOR_UNVISITED = 'b';
    private static final char COLOR_A = 'a';
    private static final char COLOR_C = 'c';

    private boolean isBipartite = true;

    /**
     * Orchestrates the solving process.
     * 
     * @param in  The input scanner.
     * @param out The output writer.
     */
    public void solve(FastScanner in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();

        // Step 1: Initialize the graph.
        // The problem defines the graph as a complete graph minus M specific edges.
        boolean[][] adjacencyMatrix = new boolean[n][n];
        int[] degrees = new int[n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i != j) {
                    adjacencyMatrix[i][j] = true;
                    degrees[i]++;
                }
            }
        }

        // Step 2: Remove the edges provided in the input.
        for (int i = 0; i < m; i++) {
            int u = in.nextInt() - 1;
            int v = in.nextInt() - 1;
            // Ensure edge removal is only performed for valid, existing, non-self edges
            if (u >= 0 && u < n && v >= 0 && v < n && u != v) {
                if (adjacencyMatrix[u][v]) {
                    adjacencyMatrix[u][v] = false;
                    adjacencyMatrix[v][u] = false;
                    degrees[u]--;
                    degrees[v]--;
                }
            }
        }

        // Step 3: Attempt to color the graph using DFS.
        char[] nodeColors = new char[n];
        Arrays.fill(nodeColors, COLOR_UNVISITED);
        isBipartite = true;

        for (int i = 0; i < n; i++) {
            // Only start DFS on unvisited nodes that belong to a component with edges.
            // Isolated nodes remain 'b' per the original logic.
            if (nodeColors[i] == COLOR_UNVISITED && degrees[i] > 0) {
                performDfsColoring(i, adjacencyMatrix, nodeColors, COLOR_A);
            }
        }

        // Step 4: Final validation.
        // A graph must be bipartite AND it must be a complete bipartite graph
        // (all edges between color A and C must exist, and no edges within a color).
        if (!isBipartite || !isCompleteBipartite(n, adjacencyMatrix, nodeColors)) {
            out.println("No");
        } else {
            out.println("Yes");
            out.println(new String(nodeColors));
        }
    }

    /**
     * Performs a Depth First Search to assign bipartite colors to nodes.
     */
    private void performDfsColoring(int u, boolean[][] matrix, char[] colors, char color) {
        colors[u] = color;
        char targetColor = (color == COLOR_A) ? COLOR_C : COLOR_A;

        for (int v = 0; v < matrix.length; v++) {
            if (!matrix[u][v]) {
                continue;
            }

            if (colors[v] == COLOR_UNVISITED) {
                performDfsColoring(v, matrix, colors, targetColor);
            } else if (colors[v] != targetColor) {
                isBipartite = false;
            }
        }
    }

    /**
     * Verifies if the current coloring results in a complete bipartite graph.
     */
    private boolean isCompleteBipartite(int n, boolean[][] matrix, char[] colors) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i == j) continue;

                // An edge must exist if and only if the nodes have different colors (and are not 'b')
                boolean shouldHaveEdge = (colors[i] == COLOR_A && colors[j] == COLOR_C) ||
                                         (colors[i] == COLOR_C && colors[j] == COLOR_A);

                if (matrix[i][j] != shouldHaveEdge) {
                    return false;
                }
            }
        }
        return true;
    }
}

