/**
 * Problem Solver for Graph Labeling.
 * The goal is to assign labels to nodes such that nodes are connected 
 * if and only if the absolute difference between their labels is <= 1.
 */
public class Solution {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int numNodes = scanner.nextInt();
            int numEdges = scanner.nextInt();

            GraphSolver solver = new GraphSolver(numNodes, numEdges, scanner);
            solver.solve(writer);
        } catch (Exception e) {
            // In a real production environment, use a logger
            e.printStackTrace();
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Logic for solving the graph labeling problem.
     */
    static class GraphSolver {
        private static final int UNIVERSAL_NODE_LABEL = 1;
        private static final int UNLABELED = -1;
        private static final char[] LABEL_MAP = {'a', 'b', 'c'};
        private static final int MAX_ALLOWED_LABEL_INDEX = 2; // Based on original 'k > 4' logic

        private final int numNodes;
        private final List<List<Integer>> adjacencyList;
        private final int[][] adjacencyMatrix;
        private final int[] nodeLabels;

        public GraphSolver(int numNodes, int numEdges, FastScanner scanner) throws IOException {
            this.numNodes = numNodes;
            this.adjacencyList = new ArrayList<>(numNodes);
            this.adjacencyMatrix = new int[numNodes][numNodes];
            this.nodeLabels = new int[numNodes];

            for (int i = 0; i < numNodes; i++) {
                adjacencyList.add(new ArrayList<>());
                nodeLabels[i] = UNLABELED;
            }

            for (int i = 0; i < numEdges; i++) {
                int u = scanner.nextInt() - 1;
                int v = scanner.nextInt() - 1;
                addEdge(u, v);
            }
        }

        private void addEdge(int u, int v) {
            adjacencyList.get(u).add(v);
            adjacencyList.get(v).add(u);
            adjacencyMatrix[u][v] = 1;
            adjacencyMatrix[v][u] = 1;
        }

        public void solve(PrintWriter out) {
            // 1. Identify universal nodes (connected to all other nodes)
            for (int i = 0; i < numNodes; i++) {
                if (adjacencyList.get(i).size() == numNodes - 1) {
                    nodeLabels[i] = UNIVERSAL_NODE_LABEL;
                }
            }

            // 2. Assign labels to remaining components using DFS
            int labelCounter = 0;
            for (int i = 0; i < numNodes; i++) {
                if (nodeLabels[i] == UNLABELED) {
                    assignComponentLabels(i, labelCounter);
                    labelCounter += 2;
                }
            }

            // 3. Validate constraints
            // The original logic used 'k > 4' which implies a limit on components/labels
            if (labelCounter > 4) {
                out.println("No");
                return;
            }

            if (!validateLabeling()) {
                out.println("No");
                return;
            }

            // 4. Output result
            out.println("Yes");
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < numNodes; i++) {
                sb.append(LABEL_MAP[nodeLabels[i]]);
            }
            out.println(sb.toString());
        }

        private void assignComponentLabels(int startNode, int label) {
            Stack<Integer> stack = new Stack<>();
            stack.push(startNode);
            nodeLabels[startNode] = label;

            while (!stack.isEmpty()) {
                int curr = stack.pop();
                for (int neighbor : adjacencyList.get(curr)) {
                    if (nodeLabels[neighbor] == UNLABELED) {
                        nodeLabels[neighbor] = label;
                        stack.push(neighbor);
                    }
                }
            }
        }

        /**
         * Verifies if the assigned labels satisfy the connectivity condition:
         * Nodes are connected iff |label_i - label_j| <= 1
         */
        private boolean validateLabeling() {
            for (int i = 0; i < numNodes; i++) {
                for (int j = i + 1; j < numNodes; j++) {
                    boolean shouldBeConnected = Math.abs(nodeLabels[i] - nodeLabels[j]) <= 1;
                    boolean isConnected = adjacencyMatrix[i][j] == 1;

                    if (shouldBeConnected != isConnected) {
                        return false;
                    }
                }
            }
            return true;
        }
    }

    /**
     * Utility class for high-performance input reading.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }
    }
}

