/**
 * Represents an undirected graph.
 */
class Graph {
    private final int nodeCount;
    private final List<Set<Integer>> adjacencyList;

    public Graph(int nodeCount) {
        this.nodeCount = nodeCount;
        this.adjacencyList = new ArrayList<>(nodeCount);
        for (int i = 0; i < nodeCount; i++) {
            this.adjacencyList.add(new HashSet<>());
        }
    }

    public void addEdge(int u, int v) {
        if (u >= 0 && u < nodeCount && v >= 0 && v < nodeCount) {
            adjacencyList.get(u).add(v);
            adjacencyList.get(v).add(u);
        }
    }

    public boolean areConnected(int u, int v) {
        return adjacencyList.get(u).contains(v);
    }

    public int getNodeCount() {
        return nodeCount;
    }

    public Set<Integer> getNeighbors(int node) {
        return Collections.unmodifiableSet(adjacencyList.get(node));
    }

    public Set<Integer> getAllNodes() {
        Set<Integer> all = new HashSet<>();
        for (int i = 0; i < nodeCount; i++) {
            all.add(i);
        }
        return all;
    }
}

