/**
 * Service responsible for finding the specific A-B-C partition.
 */
class GraphPartitioningService {

    /**
     * Attempts to partition the graph into sets A, B, and C based on the criteria:
     * B: Nodes connected to all other nodes.
     * A: A clique.
     * C: A clique.
     * Constraint: No edges exist between A and C.
     */
    public PartitionResult solve(Graph graph) {
        int n = graph.getNodeCount();
        Set<Integer> allNodes = graph.getAllNodes();

        // 1. Find Set B (Universal nodes)
        Set<Integer> setB = findUniversalNodes(graph);

        // 2. Find Set A from the remaining nodes
        Set<Integer> remainingAfterB = new HashSet<>(allNodes);
        remainingAfterB.removeAll(setB);
        Set<Integer> setA = findGreedyClique(graph, remainingAfterB);

        // 3. Find Set C from the remaining nodes
        Set<Integer> remainingAfterBA = new HashSet<>(remainingAfterB);
        remainingAfterBA.removeAll(setA);
        Set<Integer> setC = findGreedyClique(graph, remainingAfterBA);

        // 4. Validate the partition
        if (isValidPartition(graph, setA, setB, setC, n)) {
            return PartitionResult.success(generateLabelString(n, setA, setB, setC));
        }

        return PartitionResult.failure();
    }

    private Set<Integer> findUniversalNodes(Graph graph) {
        Set<Integer> universalNodes = new HashSet<>();
        int n = graph.getNodeCount();
        for (int i = 0; i < n; i++) {
            if (isNodeConnectedToAll(graph, i)) {
                universalNodes.add(i);
            }
        }
        return universalNodes;
    }

    private boolean isNodeConnectedToAll(Graph graph, int candidate) {
        for (int i = 0; i < graph.getNodeCount(); i++) {
            if (i != candidate && !graph.areConnected(candidate, i)) {
                return false;
            }
        }
        return true;
    }

    private Set<Integer> findGreedyClique(Graph graph, Collection<Integer> candidates) {
        Set<Integer> clique = new HashSet<>();
        for (Integer node : candidates) {
            boolean canBeInClique = true;
            for (Integer member : clique) {
                if (!graph.areConnected(node, member)) {
                    canBeInClique = false;
                    break;
                }
            }
            if (canBeInClique) {
                clique.add(node);
            }
        }
        return clique;
    }

    private boolean isValidPartition(Graph graph, Set<Integer> a, Set<Integer> b, Set<Integer> c, int n) {
        // Check if all nodes are covered
        if (a.size() + b.size() + c.size() != n) {
            return false;
        }

        // Check if there are any edges between set A and set C
        for (Integer nodeA : a) {
            for (Integer nodeC : c) {
                if (graph.areConnected(nodeA, nodeC)) {
                    return false;
                }
            }
        }
        return true;
    }

    private String generateLabelString(int n, Set<Integer> a, Set<Integer> b, Set<Integer> c) {
        char[] labels = new char[n];
        // Default to a null-like character if necessary, though isValidPartition ensures coverage
        Arrays.fill(labels, ' '); 

        for (int node : a) labels[node] = 'a';
        for (int node : b) labels[node] = 'b';
        for (int node : c) labels[node] = 'c';

        return new String(labels);
    }
}

