import java.io.*;
import java.util.*;

/**
 * A solver for the graph partitioning problem.
 * The objective is to determine if the graph can be partitioned into three specific sets:
 * 1. Universal nodes (connected to all other nodes).
 * 2. A clique of equivalent nodes (set 'a').
 * 3. A second clique of equivalent nodes (set 'c').
 */
public class GraphColoringSolver {

    /**
     * Fast I/O utility class to handle large inputs efficiently.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    private int vertexCount;
    private List<Integer>[] adjacencyLists;
    private int[] nodeColors;

    /**
     * Main logic to process the graph and determine if the coloring condition is met.
     */
    public void solve() throws IOException {
        FastReader fr = new FastReader(System.in);
        String firstToken = fr.next();
        if (firstToken == null) return;

        vertexCount = Integer.parseInt(firstToken);
        adjacencyLists = new ArrayList[vertexCount];
        nodeColors = new int[vertexCount];

        // Initialize adjacency lists with self-loops as per original logic
        for (int i = 0; i < vertexCount; i++) {
            adjacencyLists[i] = new ArrayList<>();
            adjacencyLists[i].add(i);
        }

        int edgeCount = fr.nextInt();
        for (int i = 0; i < edgeCount; i++) {
            int u = fr.nextInt() - 1;
            int v = fr.nextInt() - 1;
            adjacencyLists[u].add(v);
            adjacencyLists[v].add(u);
        }

        // Sort adjacency lists to enable O(N) equality checks via List.equals()
        for (int i = 0; i < vertexCount; i++) {
            Collections.sort(adjacencyLists[i]);
        }

        // 1. Identify and color universal nodes (connected to all N nodes)
        for (int i = 0; i < vertexCount; i++) {
            if (adjacencyLists[i].size() == vertexCount) {
                nodeColors[i] = 2; // Color 'b'
            }
        }

        // 2. Try to color the first equivalence component with color 1 ('a')
        for (int i = 0; i < vertexCount; i++) {
            if (nodeColors[i] == 0) {
                if (!assignColorToComponent(i, 1)) {
                    System.out.println("No");
                    return;
                }
                break;
            }
        }

        // 3. Try to color the second equivalence component with color 3 ('c')
        for (int i = 0; i < vertexCount; i++) {
            if (nodeColors[i] == 0) {
                if (!assignColorToComponent(i, 3)) {
                    System.out.println("No");
                    return;
                }
                break;
            }
        }

        // 4. Validate that no nodes were left uncolored
        for (int i = 0; i < vertexCount; i++) {
            if (nodeColors[i] == 0) {
                System.out.println("No");
                return;
            }
        }

        printResult();
    }

    /**
     * Recursively traverses the graph to color a component of equivalent nodes.
     *
     * @param v     The current vertex.
     * @param color The color to assign.
     * @return true if the component is valid (all neighbors are equivalent), false otherwise.
     */
    private boolean assignColorToComponent(int v, int color) {
        nodeColors[v] = color;
        for (int neighbor : adjacencyLists[v]) {
            // We only process non-universal, unvisited neighbors.
            // The original logic skips self, universal nodes, and already colored nodes.
            if (neighbor != v && adjacencyLists[neighbor].size() != vertexCount && nodeColors[neighbor] == 0) {

                // Verify if the neighbor is equivalent to the current node.
                // Since lists are sorted, equals() effectively checks if the sets of neighbors are identical.
                if (adjacencyLists[neighbor].size() != adjacencyLists[v].size() || 
                    !adjacencyLists[neighbor].equals(adjacencyLists[v])) {
                    return false;
                }

                if (!assignColorToComponent(neighbor, color)) {
                    return false;
                }
            }
        }
        return true;
    }

    private void printResult() {
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
        out.println("Yes");
        for (int i = 0; i < vertexCount; i++) {
            out.print((char) ('a' + nodeColors[i] - 1));
        }
        out.println();
        out.flush();
    }

    public static void main(String[] args) {
        try {
            new GraphColoringSolver().solve();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A refactored solution for the graph-based task.
 * The program identifies specific types of components in a graph, 
 * validates their properties, and assigns character labels to nodes.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            ProblemSolver solver = new ProblemSolver();
            solver.solve(reader, writer);
        } catch (Exception e) {
            // In a production environment, use a logger.
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    /**
     * Represents the graph structure and its properties.
     */
    static class Graph {
        private final int nodesCount;
        private final List<List<Integer>> adjacencyList;
        private final boolean[][] edgeMatrix;

        public Graph(int n) {
            this.nodesCount = n;
            this.adjacencyList = new ArrayList<>(n);
            this.edgeMatrix = new boolean[n][n];
            for (int i = 0; i < n; i++) {
                adjacencyList.add(new ArrayList<>());
            }
        }

        public void addEdge(int u, int v) {
            adjacencyList.get(u).add(v);
            adjacencyList.get(v).add(u);
            edgeMatrix[u][v] = true;
            edgeMatrix[v][u] = true;
        }

        public List<Integer> getNeighbors(int u) {
            return adjacencyList.get(u);
        }

        public boolean hasEdge(int u, int v) {
            return edgeMatrix[u][v];
        }

        public int getNodeCount() {
            return nodesCount;
        }
    }

    /**
     * Core logic for solving the specific task.
     */
    static class ProblemSolver {
        private int[] nodeSpecialDegree;
        private List<List<Integer>> components;
        private boolean[] componentVisited;
        private char[] nodeLabels;
        private int alphabetIndex;
        private Graph graph;

        public void solve(FastReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();

            graph = new Graph(n);
            for (int i = 0; i < m; i++) {
                int u = in.nextInt() - 1;
                int v = in.nextInt() - 1;
                graph.addEdge(u, v);
            }

            nodeSpecialDegree = new int[n];
            components = new ArrayList<>();
            int componentCount = 0;

            // 1. Find components using the specific "clique-growth" logic
            for (int i = 0; i < n; i++) {
                if (nodeSpecialDegree[i] == 0) {
                    // The original logic limits the number of valid components to 2.
                    if (componentCount == 2) {
                        out.println("No");
                        return;
                    }

                    List<Integer> currentComponent = findSpecialComponent(i);
                    componentCount++;
                    components.add(currentComponent);
                }
            }

            // 2. Validate node degrees
            for (int degree : nodeSpecialDegree) {
                if (degree > 2) {
                    out.println("No");
                    return;
                }
            }

            // 3. Validate inter-component connectivity
            if (!validateComponentConnectivity()) {
                out.println("No");
                return;
            }

            // 4. Assign character labels via component traversal
            componentVisited = new boolean[components.size()];
            nodeLabels = new char[n];
            alphabetIndex = 0;

            for (int i = 0; i < components.size(); i++) {
                if (!componentVisited[i] && isComponentAStart(components.get(i))) {
                    traverseComponents(i);
                }
            }

            // 5. Final validation and output
            if (alphabetIndex > 4) {
                out.println("No");
                return;
            }

            out.println("Yes");
            for (char label : nodeLabels) {
                out.print(label);
            }
            out.println();
        }

        private List<Integer> findSpecialComponent(int startNode) {
            List<Integer> subGraph = new ArrayList<>();
            Set<Integer> subset = new HashSet<>();

            subGraph.add(startNode);
            subset.add(startNode);
            nodeSpecialDegree[startNode]++;

            int iterator = 0;
            while (iterator < subGraph.size()) {
                int current = subGraph.get(iterator++);
                for (int neighbor : graph.getNeighbors(current)) {
                    if (!subset.contains(neighbor)) {
                        // Check if the neighbor is connected to ALL nodes currently in the subset
                        if (isFullyConnectedToSubset(neighbor, subset)) {
                            subGraph.add(neighbor);
                            subset.add(neighbor);
                            nodeSpecialDegree[neighbor]++;
                        }
                    }
                }
            }
            return subGraph;
        }

        private boolean isFullyConnectedToSubset(int node, Set<Integer> subset) {
            Set<Integer> neighborSet = new HashSet<>(graph.getNeighbors(node));
            return neighborSet.containsAll(subset);
        }

        private boolean validateComponentConnectivity() {
            for (int i = 0; i < components.size(); i++) {
                for (int j = i + 1; j < components.size(); j++) {
                    for (int u : components.get(i)) {
                        for (int v : components.get(j)) {
                            if (graph.hasEdge(u, v) && nodeSpecialDegree[u] == 1 && nodeSpecialDegree[v] == 1) {
                                return false;
                            }
                        }
                    }
                }
            }
            return true;
        }

        private boolean isComponentAStart(List<Integer> component) {
            for (int node : component) {
                if (nodeSpecialDegree[node] == 1) {
                    return true;
                }
            }
            return false;
        }

        private void traverseComponents(int componentId) {
            componentVisited[componentId] = true;
            char currentChar = (char) (alphabetIndex + 'a');
            char nextChar = (char) (alphabetIndex + 1 + 'a');

            // Look for a connected component to traverse into
            for (int i = 0; i < components.size(); i++) {
                if (!componentVisited[i] && areComponentsConnected(components.get(componentId), components.get(i))) {
                    // Assign labels to the current component
                    for (int node : components.get(componentId)) {
                        if (nodeLabels[node] == 0) {
                            // Due to component disjointness, node is always assigned currentChar
                            nodeLabels[node] = currentChar;
                        }
                    }
                    alphabetIndex += 2;
                    traverseComponents(i);
                    return;
                }
            }

            // Fallback: assign labels if no connected component is found
            for (int node : components.get(componentId)) {
                if (nodeLabels[node] == 0) {
                    nodeLabels[node] = currentChar;
                }
            }
            alphabetIndex += 2;
        }

        private boolean areComponentsConnected(List<Integer> compA, List<Integer> compB) {
            for (int u : compA) {
                for (int v : compB) {
                    if (graph.hasEdge(u, v)) {
                        return true;
                    }
                }
            }
            return false;
        }
    }

    /**
     * Utility class for fast input reading.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

