/**
 * A solver for the graph partitioning problem.
 * The goal is to partition vertices into three sets (a, b, c) such that 
 * no vertex in set 'a' is connected to a vertex in set 'c'.
 */
public class GraphBipartiteSolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int numVertices = reader.nextInt();
            int numEdges = reader.nextInt();

            boolean[][] adjacencyMatrix = new boolean[numVertices][numVertices];
            int[] degrees = new int[numVertices];

            for (int i = 0; i < numEdges; i++) {
                int u = reader.nextInt() - 1;
                int v = reader.nextInt() - 1;

                if (isValidIndex(u, numVertices) && isValidIndex(v, numVertices)) {
                    // Avoid self-loops and duplicate counting for degree
                    if (u != v && !adjacencyMatrix[u][v]) {
                        adjacencyMatrix[u][v] = adjacencyMatrix[v][u] = true;
                        degrees[u]++;
                        degrees[v]++;
                    }
                }
            }

            Solver solver = new Solver(numVertices, adjacencyMatrix, degrees);
            Solution solution = solver.solve();

            if (solution.isPossible()) {
                writer.println("Yes");
                writer.println(solution.getAssignment());
            } else {
                writer.println("No");
            }

        } catch (IOException | NoSuchElementException e) {
            // In a production environment, use a logger.
        } finally {
            writer.flush();
            writer.close();
        }
    }

    private static boolean isValidIndex(int index, int limit) {
        return index >= 0 && index < limit;
    }

    /**
     * Represents the result of the graph solving process.
     */
    static class Solution {
        private final boolean possible;
        private final String assignment;

        private Solution(boolean possible, String assignment) {
            this.possible = possible;
            this.assignment = assignment;
        }

        public static Solution impossible() {
            return new Solution(false, "");
        }

        public static Solution possible(String assignment) {
            return new Solution(true, assignment);
        }

        public boolean isPossible() {
            return possible;
        }

        public String getAssignment() {
            return assignment;
        }
    }

    /**
     * Contains the core logic for solving the bipartite complement problem.
     */
    static class Solver {
        private final int numVertices;
        private final boolean[][] adjacencyMatrix;
        private final int[] degrees;
        private final int[] nodeColors; // -1: uncolored (b), 0: color 'a', 1: color 'c'

        private static final int UNCOLORED = -1;
        private static final int COLOR_A = 0;
        private static final int COLOR_C = 1;

        public Solver(int numVertices, boolean[][] adjacencyMatrix, int[] degrees) {
            this.numVertices = numVertices;
            this.adjacencyMatrix = adjacencyMatrix;
            this.degrees = degrees;
            this.nodeColors = new int[numVertices];
            Arrays.fill(this.nodeColors, UNCOLORED);
        }

        public Solution solve() {
            // 1. Attempt to 2-color the complement graph for all nodes 
            // that are not connected to every other node.
            for (int i = 0; i < numVertices; i++) {
                if (nodeColors[i] == UNCOLORED && degrees[i] < numVertices - 1) {
                    if (!applyBipartiteColoring(i, COLOR_A)) {
                        return Solution.impossible();
                    }
                }
            }

            // 2. Validate the constraint: No edge can exist between color A (0) and color C (1).
            if (!validateNoEdgesBetweenAAndC()) {
                return Solution.impossible();
            }

            return Solution.possible(buildAssignmentString());
        }

        /**
         * Performs a DFS to color the complement graph.
         * An edge in the complement graph exists if adjacencyMatrix[u][v] is false.
         */
        private boolean applyBipartiteColoring(int u, int color) {
            nodeColors[u] = color;

            for (int v = 0; v < numVertices; v++) {
                if (u == v || adjacencyMatrix[u][v]) {
                    continue; // This is an edge in the original graph, so not in the complement
                }

                // There is an edge in the complement graph
                if (nodeColors[v] == UNCOLORED) {
                    if (!applyBipartiteColoring(v, 1 - color)) {
                        return false;
                    }
                } else if (nodeColors[v] == color) {
                    return false; // Conflict found
                }
            }
            return true;
        }

        private boolean validateNoEdgesBetweenAAndC() {
            for (int i = 0; i < numVertices; i++) {
                for (int j = i + 1; j < numVertices; j++) {
                    if (adjacencyMatrix[i][j]) {
                        if (isOppositeColors(nodeColors[i], nodeColors[j])) {
                            return false;
                        }
                    }
                }
            }
            return true;
        }

        private boolean isOppositeColors(int c1, int c2) {
            return (c1 == COLOR_A && c2 == COLOR_C) || (c1 == COLOR_C && c2 == COLOR_A);
        }

        private String buildAssignmentString() {
            StringBuilder sb = new StringBuilder();
            for (int color : nodeColors) {
                if (color == UNCOLORED) sb.append('b');
                else if (color == COLOR_A) sb.append('a');
                else sb.append('c');
            }
            return sb.toString();
        }
    }

    /**
     * Efficient utility class for reading input.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A refactored solution to the graph coloring problem.
 * 
 * Problem Summary:
 * Given an undirected graph, assign colors 'a', 'b', or 'c' to nodes such that:
 * 1. Nodes with the same color or adjacent colors ('a'-'b' or 'b'-'c') must be connected.
 * 2. Nodes with non-adjacent colors ('a'-'c') must NOT be connected.
 * 
 * Implementation Details:
 * - Complexity: O(N^2) due to the connectivity validation step.
 * - Data Structures: Adjacency list for efficient BFS traversal and an 
 *   adjacency matrix for O(1) edge lookups during validation.
 */
public class GraphColoringProblem {

    /**
     * Fast I/O utility for efficient input reading.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader() {
            reader = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            return next != null ? Integer.parseInt(next) : 0;
        }
    }

    private final int numNodes;
    private final List<Integer>[] adjacencyList;
    private final boolean[][] adjacencyMatrix;
    private final int[] colors;

    // Color constants to improve code readability and prevent magic numbers
    private static final int COLOR_NONE = 0;
    private static final int COLOR_A = 1;
    private static final int COLOR_B = 2;
    private static final int COLOR_C = 3;

    @SuppressWarnings("unchecked")
    public GraphColoringProblem(int n) {
        this.numNodes = n;
        this.adjacencyList = new ArrayList[n + 1];
        this.adjacencyMatrix = new boolean[n + 1][n + 1];
        this.colors = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            adjacencyList[i] = new ArrayList<>();
        }
    }

    /**
     * Adds an undirected edge between two nodes.
     * 
     * @param u Node u
     * @param v Node v
     */
    public void addEdge(int u, int v) {
        if (u <= 0 || u > numNodes || v <= 0 || v > numNodes) return;
        adjacencyList[u].add(v);
        adjacencyList[v].add(u);
        adjacencyMatrix[u][v] = true;
        adjacencyMatrix[v][u] = true;
    }

    /**
     * Orchestrates the coloring process and outputs the result.
     */
    public void solve() {
        // Step 1: Assign color 'b' to nodes with degree N-1.
        // These nodes act as "connectors" that must be adjacent to everyone.
        for (int i = 1; i <= numNodes; i++) {
            if (adjacencyList[i].size() == numNodes - 1) {
                colors[i] = COLOR_B;
            }
        }

        // Step 2: Identify the first uncolored component and assign it color 'a'.
        for (int i = 1; i <= numNodes; i++) {
            if (colors[i] == COLOR_NONE) {
                bfsColorComponent(i, COLOR_A);
                break; 
            }
        }

        // Step 3: Identify the next uncolored component and assign it color 'c'.
        for (int i = 1; i <= numNodes; i++) {
            if (colors[i] == COLOR_NONE) {
                bfsColorComponent(i, COLOR_C);
                break;
            }
        }

        // Step 4: Final validation of the coloring against graph constraints.
        if (isColoringValid()) {
            System.out.println("Yes");
            printColoring();
        } else {
            System.out.println("No");
        }
    }

    /**
     * Traverses a connected component using BFS and assigns a specific color to all nodes.
     * 
     * @param startNode The starting node of the component.
     * @param color The color value to assign.
     */
    private void bfsColorComponent(int startNode, int color) {
        Queue<Integer> queue = new LinkedList<>();
        queue.add(startNode);
        colors[startNode] = color;

        while (!queue.isEmpty()) {
            int u = queue.poll();
            for (int v : adjacencyList[u]) {
                if (colors[v] == COLOR_NONE) {
                    colors[v] = color;
                    queue.add(v);
                }
            }
        }
    }

    /**
     * Verifies that the coloring satisfies both:
     * 1. All nodes are colored.
     * 2. Connectivity constraints (edge exists iff colors are within 1 of each other).
     * 
     * @return true if the coloring is valid, false otherwise.
     */
    private boolean isColoringValid() {
        // Check if all nodes were assigned a color.
        for (int i = 1; i <= numNodes; i++) {
            if (colors[i] == COLOR_NONE) return false;
        }

        // Validate connectivity constraints for every pair of nodes.
        for (int i = 1; i <= numNodes; i++) {
            for (int j = i + 1; j <= numNodes; j++) {
                boolean hasEdge = adjacencyMatrix[i][j];
                // Rule: |color_i - color_j| <= 1 means an edge must exist.
                boolean shouldHaveEdge = Math.abs(colors[i] - colors[j]) <= 1;

                if (hasEdge != shouldHaveEdge) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Converts numeric colors to character format and prints them.
     */
    private void printColoring() {
        StringBuilder sb = new StringBuilder();
        for (int i = 1; i <= numNodes; i++) {
            // Map 1 -> 'a', 2 -> 'b', 3 -> 'c'
            sb.append((char) (colors[i] - 1 + 'a'));
        }
        System.out.println(sb.toString());
    }

    public static void main(String[] args) {
        FastReader fr = new FastReader();
        String firstToken = fr.next();
        if (firstToken == null) return;

        int n = Integer.parseInt(firstToken);
        int m = fr.nextInt();

        GraphColoringProblem problem = new GraphColoringProblem(n);
        for (int i = 0; i < m; i++) {
            int u = fr.nextInt();
            int v = fr.nextInt();
            problem.addEdge(u, v);
        }

        problem.solve();
    }
}

