import java.util.*;

/**
 * Solution for identifying and filling the smallest lakes in a grid.
 */
public class Solution {

    public static void main(String[] args) {
        FastReader fr = new FastReader(System.in);

        try {
            int rows = fr.nextInt();
            int cols = fr.nextInt();
            int k = fr.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = fr.next().toCharArray();
            }

            LakeManager manager = new LakeManager(rows, cols, grid);
            manager.process(k);
            manager.printResults();

        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * Encapsulates the logic for managing and processing lakes in the grid.
     */
    static class LakeManager {
        private final int rows;
        private final int cols;
        private final char[][] grid;
        private int totalCellsFilled = 0;

        public LakeManager(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
        }

        /**
         * Executes the core algorithm: mark boundary water, find lakes, and fill the smallest.
         * @param k The number of lakes to remain after filling.
         */
        public void process(int k) {
            boolean[][] visited = new boolean[rows][cols];

            // 1. Mark all water cells connected to the boundary (not lakes)
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (isBoundary(r, c) && grid[r][c] == '.' && !visited[r][c]) {
                        markBoundaryWater(r, c, visited);
                    }
                }
            }

            // 2. Identify all isolated water bodies (lakes)
            List<Lake> lakes = new ArrayList<>();
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.' && !visited[r][c]) {
                        lakes.add(collectLake(r, c, visited));
                    }
                }
            }

            // 3. Sort lakes by size (ascending) and fill until target k is met
            lakes.sort(Comparator.comparingInt(Lake::size));

            int lakesToFill = lakes.size() - k;
            for (int i = 0; i < lakesToFill; i++) {
                Lake lake = lakes.get(i);
                for (Point p : lake.points()) {
                    grid[p.row()][p.col()] = '*';
                }
                totalCellsFilled += lake.size();
            }
        }

        private boolean isBoundary(int r, int c) {
            return r == 0 || r == rows - 1 || c == 0 || c == cols - 1;
        }

        /**
         * Uses iterative DFS to mark water connected to the boundary.
         */
        private void markBoundaryWater(int startR, int startC, boolean[][] visited) {
            Deque<Point> stack = new ArrayDeque<>();
            stack.push(new Point(startR, startC));
            visited[startR][startC] = true;

            while (!stack.isEmpty()) {
                Point curr = stack.pop();
                for (Direction dir : Direction.values()) {
                    int nr = curr.row() + dir.dr;
                    int nc = curr.col() + dir.dc;

                    if (isValidMove(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        stack.push(new Point(nr, nc));
                    }
                }
            }
        }

        /**
         * Uses iterative DFS to collect all points belonging to a single lake.
         */
        private Lake collectLake(int startR, int startC, boolean[][] visited) {
            List<Point> points = new ArrayList<>();
            Deque<Point> stack = new ArrayDeque<>();
            stack.push(new Point(startR, startC));
            visited[startR][startC] = true;

            while (!stack.isEmpty()) {
                Point curr = stack.pop();
                points.add(curr);
                for (Direction dir : Direction.values()) {
                    int nr = curr.row() + dir.dr;
                    int nc = curr.col() + dir.dc;

                    if (isValidMove(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        stack.push(new Point(nr, nc));
                    }
                }
            }
            return new Lake(points);
        }

        private boolean isValidMove(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        public void printResults() {
            PrintWriter pw = new PrintWriter(System.out);
            pw.println(totalCellsFilled);
            for (int i = 0; i < rows; i++) {
                pw.println(new String(grid[i]));
            }
            pw.flush();
            pw.close();
        }
    }

    /**
     * Represents a coordinate in the grid.
     */
    record Point(int row, int col) {}

    /**
     * Represents a cluster of water cells forming a lake.
     */
    record Lake(List<Point> points) {
        int size() {
            return points.size();
        }
    }

    /**
     * Represents movement directions in the grid.
     */
    enum Direction {
        UP(-1, 0), DOWN(1, 0), LEFT(0, -1), RIGHT(0, 1);
        final int dr, dc;
        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }
    }

    /**
     * Efficient utility for reading input.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

