class BerlandMap {
    private final int rows;
    private final int cols;
    private final char[][] grid;
    private static final int[][] DIRECTIONS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    public BerlandMap(char[][] grid) {
        this.rows = grid.length;
        this.cols = grid[0].length;
        this.grid = grid;
    }

    /**
     * Executes the core logic: identifying lakes and filling the smallest ones.
     */
    public void solve(int kTargetLakes) {
        boolean[][] isOcean = identifyOcean();
        List<Lake> lakes = findLakes(isOcean);

        // Sort lakes by size (ascending) to remove the smallest ones first
        Collections.sort(lakes);

        int lakesToRemoveCount = lakes.size() - kTargetLakes;
        int totalLandAdded = 0;

        for (int i = 0; i < lakesToRemoveCount; i++) {
            Lake lake = lakes.get(i);
            totalLandAdded += lake.getSize();
            fillLake(lake);
        }

        System.out.println(totalLandAdded);
    }

    /**
     * Uses BFS to mark all water cells ('.') connected to the boundaries as 'Ocean'.
     */
    private boolean[][] identifyOcean() {
        boolean[][] isOcean = new boolean[rows][cols];
        Queue<Point> queue = new ArrayDeque<>();

        // Add all boundary water cells to the queue
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (isBoundary(r, c) && grid[r][c] == '.') {
                    isOcean[r][c] = true;
                    queue.add(new Point(r, c));
                }
            }
        }

        // BFS to expand ocean coverage
        while (!queue.isEmpty()) {
            Point curr = queue.poll();
            for (int[] dir : DIRECTIONS) {
                int nr = curr.row + dir[0];
                int nc = curr.col + dir[1];

                if (isValid(nr, nc) && grid[nr][nc] == '.' && !isOcean[nr][nc]) {
                    isOcean[nr][nc] = true;
                    queue.add(new Point(nr, nc));
                }
            }
        }
        return isOcean;
    }

    /**
     * Traverses the grid to find enclosed water bodies (lakes).
     */
    private List<Lake> findLakes(boolean[][] isOcean) {
        List<Lake> lakes = new ArrayList<>();
        boolean[][] visited = new boolean[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                // A lake is water that is not ocean and hasn't been visited yet
                if (grid[r][c] == '.' && !isOcean[r][c] && !visited[r][c]) {
                    lakes.add(bfsFindLake(r, c, visited));
                }
            }
        }
        return lakes;
    }

    /**
     * BFS to collect all points belonging to a single lake.
     */
    private Lake bfsFindLake(int startR, int startC, boolean[][] visited) {
        List<Point> lakePoints = new ArrayList<>();
        Queue<Point> queue = new ArrayDeque<>();

        Point start = new Point(startR, startC);
        queue.add(start);
        visited[startR][startC] = true;

        while (!queue.isEmpty()) {
            Point curr = queue.poll();
            lakePoints.add(curr);

            for (int[] dir : DIRECTIONS) {
                int nr = curr.row + dir[0];
                int nc = curr.col + dir[1];

                if (isValid(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                    // We don't need to check isOcean here because identifyOcean() 
                    // already partitioned the grid.
                    visited[nr][nc] = true;
                    queue.add(new Point(nr, nc));
                }
            }
        }
        return new Lake(lakePoints);
    }

    private void fillLake(Lake lake) {
        for (Point p : lake.getPoints()) {
            grid[p.row][p.col] = '*';
        }
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private boolean isBoundary(int r, int c) {
        return r == 0 || r == rows - 1 || c == 0 || c == cols - 1;
    }

    public void print() {
        StringBuilder sb = new StringBuilder();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                sb.append(grid[r][c]);
            }
            sb.append("\n");
        }
        System.out.print(sb.toString());
    }
}

