/**
 * Manages the Berland grid, handling connectivity and cell modifications.
 */
class BerlandGrid {
    private final int rows;
    private final int cols;
    private final char[][] grid;

    private static final int[] ROW_OFFSETS = {-1, 0, 1, 0};
    private static final int[] COL_OFFSETS = {0, -1, 0, 1};

    public BerlandGrid(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
    }

    public int getRows() { return rows; }
    public int getCols() { return cols; }

    public boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    public char getCell(int r, int c) {
        return grid[r][c];
    }

    public void setCell(int r, int c, char value) {
        grid[r][c] = value;
    }

    /**
     * Identifies all water components that do not touch the boundary (lakes).
     */
    public List<Lake> findLakes() {
        List<Lake> lakes = new ArrayList<>();
        boolean[][] visited = new boolean[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.' && !visited[i][j]) {
                    Lake lake = exploreComponent(i, j, visited);
                    if (lake != null) {
                        lakes.add(lake);
                    }
                }
            }
        }
        return lakes;
    }

    private Lake exploreComponent(int startR, int startC, boolean[][] visited) {
        Deque<Coordinate> stack = new ArrayDeque<>();
        List<Coordinate> componentCells = new ArrayList<>();
        boolean touchesOcean = false;

        stack.push(new Coordinate(startR, startC));
        visited[startR][startC] = true;

        while (!stack.isEmpty()) {
            Coordinate current = stack.pop();
            componentCells.add(current);

            for (int i = 0; i < 4; i++) {
                int nextR = current.getRow() + ROW_OFFSETS[i];
                int nextC = current.getCol() + COL_OFFSETS[i];

                if (!isValid(nextR, nextC)) {
                    touchesOcean = true;
                    continue;
                }

                if (grid[nextR][nextC] == '.' && !visited[nextR][nextC]) {
                    visited[nextR][nextC] = true;
                    stack.push(new Coordinate(nextR, nextC));
                }
            }
        }

        // If the component doesn't touch the boundary, it's a lake.
        return touchesOcean ? null : new Lake(componentCells.size(), componentCells);
    }

    public void printGrid() {
        for (int i = 0; i < rows; i++) {
            System.out.println(new String(grid[i]));
        }
    }
}

/**
 * Orchestrates the logic for solving the Lakes in Berland problem.
 */
public class LakesInBerland {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        int k = scanner.nextInt();

        char[][] maze = new char[n][m];
        for (int i = 0; i < n; i++) {
            maze[i] = scanner.next().toCharArray();
        }

        BerlandGrid berlandGrid = new BerlandGrid(n, m, maze);
        List<Lake> lakes = berlandGrid.findLakes();

        // Sort lakes by size ascending to remove the smallest ones first
        lakes.sort(Comparator.comparingInt(Lake::getSize));

        int totalWaterRemoved = 0;
        if (lakes.size() > k) {
            int numToRemove = lakes.size() - k;
            for (int i = 0; i < numToRemove; i++) {
                Lake lakeToRemove = lakes.get(i);
                totalWaterRemoved += lakeToRemove.getSize();
                for (Coordinate coord : lakeToRemove.getCells()) {
                    berlandGrid.setCell(coord.getRow(), coord.getCol(), '*');
                }
            }
        }

        System.out.println(totalWaterRemoved);
        berlandGrid.printGrid();

        scanner.close();
    }
}

import java.util.*;
import java.io.*;

/**
 * Refactored solution for the "Lakes in Berland" problem.
 * Goal: Identify lakes (water components not touching the boundary),
 * keep the K largest lakes, and fill the rest with land ('*').
 */
public class Main {
    public static void main(String[] args) {
        FastReader in = new FastReader(System.in);
        FastWriter out = new FastWriter(System.out);

        int n = in.nextInt();
        int m = in.nextInt();
        int k = in.nextInt();

        char[][] map = new char[n][m];
        for (int i = 0; i < n; i++) {
            map[i] = in.next().toCharArray();
        }

        LakesSolver solver = new LakesSolver(n, m, k, map);
        solver.solve(out);

        out.close();
    }

    static class Cell {
        int r, c;
        Cell(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    static class Lake {
        List<Cell> cells;
        int size;

        Lake(List<Cell> cells) {
            this.cells = cells;
            this.size = cells.size();
        }
    }

    static class LakesSolver {
        private final int n, m, k;
        private final char[][] map;
        private final int[] dr = {1, -1, 0, 0};
        private final int[] dc = {0, 0, 1, -1};

        public LakesSolver(int n, int m, int k, char[][] map) {
            this.n = n;
            this.m = m;
            this.k = k;
            this.map = map;
        }

        public void solve(FastWriter out) {
            // 1. Mark all water connected to the boundary as 'S' (Sea)
            markSea();

            // 2. Find all isolated water components (Lakes)
            List<Lake> lakes = findLakes();

            // 3. Sort lakes by size (ascending) to remove the smallest ones first
            lakes.sort(Comparator.comparingInt(l -> l.size));

            int totalRemovedCells = 0;
            int numToRemove = Math.max(0, lakes.size() - k);

            for (int i = 0; i < numToRemove; i++) {
                Lake lake = lakes.get(i);
                totalRemovedCells += lake.size;
                for (Cell cell : lake.cells) {
                    map[cell.r][cell.c] = '*';
                }
            }

            // 4. Convert 'S' (Sea) back to '.' (Water)
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (map[i][j] == 'S') {
                        map[i][j] = '.';
                    }
                }
            }

            // 5. Output results
            out.println(totalRemovedCells);
            for (int i = 0; i < n; i++) {
                out.println(new String(map[i]));
            }
        }

        private void markSea() {
            for (int i = 0; i < n; i++) {
                if (map[i][0] == '.') bfsMark(i, 0, '.', 'S');
                if (map[i][m - 1] == '.') bfsMark(i, m - 1, '.', 'S');
            }
            for (int j = 0; j < m; j++) {
                if (map[0][j] == '.') bfsMark(0, j, '.', 'S');
                if (map[n - 1][j] == '.') bfsMark(n - 1, j, '.', 'S');
            }
        }

        private void bfsMark(int startR, int startC, char target, char replacement) {
            Queue<int[]> queue = new ArrayDeque<>();
            queue.add(new int[]{startR, startC});
            map[startR][startC] = replacement;

            while (!queue.isEmpty()) {
                int[] curr = queue.poll();
                for (int i = 0; i < 4; i++) {
                    int nr = curr[0] + dr[i];
                    int nc = curr[1] + dc[i];
                    if (isValid(nr, nc) && map[nr][nc] == target) {
                        map[nr][nc] = replacement;
                        queue.add(new int[]{nr, nc});
                    }
                }
            }
        }

        private List<Lake> findLakes() {
            List<Lake> lakes = new ArrayList<>();
            boolean[][] visited = new boolean[n][m];

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (map[i][j] == '.' && !visited[i][j]) {
                        List<Cell> lakeCells = new ArrayList<>();
                        bfsCollectLake(i, j, visited, lakeCells);
                        lakes.add(new Lake(lakeCells));
                    }
                }
            }
            return lakes;
        }

        private void bfsCollectLake(int startR, int startC, boolean[][] visited, List<Cell> cells) {
            Queue<int[]> queue = new ArrayDeque<>();
            queue.add(new int[]{startR, startC});
            visited[startR][startC] = true;

            while (!queue.isEmpty()) {
                int[] curr = queue.poll();
                cells.add(new Cell(curr[0], curr[1]));

                for (int i = 0; i < 4; i++) {
                    int nr = curr[0] + dr[i];
                    int nc = curr[1] + dc[i];
                    if (isValid(nr, nc) && map[nr][nc] == '.' && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        queue.add(new int[]{nr, nc});
                    }
                }
            }
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < n && c >= 0 && c < m;
        }
    }

    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }

    static class FastWriter {
        private final PrintWriter writer;

        public FastWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public void println(int i) {
            writer.println(i);
        }

        public void println(String s) {
            writer.println(s);
        }

        public void close() {
            writer.close();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A refactored solution for the grid component problem.
 * The goal is to find "enclosed" components of '.' (those not touching the boundary)
 * and fill the smallest ones with '*' until only k enclosed components remain.
 */
public class GridProblemSolver {

    /**
     * Represents a single coordinate in the grid.
     */
    private record Cell(int r, int c) {}

    /**
     * Represents a connected component of '.' cells.
     */
    private static class Component implements Comparable<Component> {
        private final List<Cell> cells = new ArrayList<>();

        void add(int r, int c) {
            cells.add(new Cell(r, c));
        }

        int size() {
            return cells.size();
        }

        List<Cell> getCells() {
            return cells;
        }

        @Override
        public int compareTo(Component other) {
            // Min-priority queue: smallest components first
            return Integer.compare(this.size(), other.size());
        }
    }

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int targetComponentCount;

    public GridProblemSolver(int rows, int cols, char[][] grid, int k) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.targetComponentCount = k;
    }

    /**
     * Executes the core logic of the problem.
     * @return The number of cells that were changed from '.' to '*'.
     */
    public int solve() {
        boolean[][] visited = new boolean[rows][cols];
        PriorityQueue<Component> enclosedComponents = new PriorityQueue<>();

        int[] rowDirections = {0, 0, 1, -1};
        int[] colDirections = {1, -1, 0, 0};

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (visited[i][j] || grid[i][j] == '*') {
                    continue;
                }

                // Start BFS to find a new component
                Component component = new Component();
                boolean touchesBoundary = false;

                Deque<Cell> queue = new ArrayDeque<>();
                Cell start = new Cell(i, j);
                queue.add(start);
                visited[i][j] = true;

                while (!queue.isEmpty()) {
                    Cell current = queue.poll();
                    component.add(current.r(), current.c());

                    if (isBoundary(current.r(), current.c())) {
                        touchesBoundary = true;
                    }

                    for (int d = 0; d < 4; d++) {
                        int nr = current.r() + rowDirections[d];
                        int nc = current.c() + colDirections[d];

                        if (isValid(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                            visited[nr][nc] = true;
                            queue.add(new Cell(nr, nc));
                        }
                    }
                }

                // If the component does not touch the boundary, it is "enclosed"
                if (!touchesBoundary) {
                    enclosedComponents.add(component);
                }
            }
        }

        // Fill the smallest enclosed components until we satisfy the k requirement
        int filledCount = 0;
        while (enclosedComponents.size() > targetComponentCount) {
            Component smallest = enclosedComponents.poll();
            for (Cell cell : smallest.getCells()) {
                grid[cell.r()][cell.c()] = '*';
                filledCount++;
            }
        }

        return filledCount;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private boolean isBoundary(int r, int c) {
        return r == 0 || r == rows - 1 || c == 0 || c == cols - 1;
    }

    public char[][] getGrid() {
        return grid;
    }

    // --- I/O Utilities ---

    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line, " :");
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }

    static class FastWriter {
        private final PrintWriter writer;

        public FastWriter(OutputStream stream) {
            writer = new PrintWriter(stream);
        }

        public void println(Object obj) {
            writer.println(obj);
        }

        public void close() {
            writer.close();
        }
    }

    // --- Main Execution ---

    public static void main(String[] args) {
        // Use a separate thread to provide larger stack size if needed for deep recursion
        Thread thread = new Thread(null, () -> {
            try {
                run();
            } catch (Exception e) {
                e.printStackTrace();
            }
        }, "solver", 1L * 256 * 1024 * 1024);
        thread.start();
    }

    private static void run() throws IOException {
        long startTime = System.currentTimeMillis();

        FastReader sc = new FastReader(System.in);
        FastWriter out = new FastWriter(System.out);

        // Read Dimensions
        String nStr = sc.next();
        if (nStr == null) return;
        int n = Integer.parseInt(nStr);
        int m = sc.nextInt();
        int k = sc.nextInt();

        // Read Grid
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = sc.next().toCharArray();
        }

        // Solve
        GridProblemSolver solver = new GridProblemSolver(n, m, grid, k);
        int filledCount = solver.solve();

        // Output Results
        out.println(filledCount);
        for (char[] row : solver.getGrid()) {
            out.println(new String(row));
        }
        out.close();

        // Profiling (only if not in online judge environment)
        if (System.getProperty("ONLINE_JUDGE") == null) {
            long endTime = System.currentTimeMillis();
            Runtime runtime = Runtime.getRuntime();
            long usedMemory = (runtime.totalMemory() - runtime.freeMemory()) / 1024;
            System.err.println("Time: " + (endTime - startTime) + "ms");
            System.err.println("Memory: " + usedMemory + " KB");
        }
    }
}

import java.util.*;

/**
 * Represents a connected component of water (a lake) in the grid.
 */
class Lake implements Comparable<Lake> {
    private final int startRow;
    private final int startCol;
    private final int size;

    public Lake(int startRow, int startCol, int size) {
        this.startRow = startRow;
        this.startCol = startCol;
        this.size = size;
    }

    public int getStartRow() { return startRow; }
    public int getStartCol() { return startCol; }
    public int getSize() { return size; }

    @Override
    public int compareTo(Lake other) {
        // Sort in ascending order of size
        return Integer.compare(this.size, other.size);
    }
}

/**
 * Handles the processing of the grid to identify and manipulate lakes.
 */
class LakeProcessor {
    private final int rows;
    private final int cols;
    private final int keepCount;
    private final char[][] grid;
    private final boolean[][] visited;

    private static final int[][] DIRECTIONS = {
        {1, 0}, {-1, 0}, {0, 1}, {0, -1}
    };

    public LakeProcessor(int rows, int cols, int keepCount, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.keepCount = keepCount;
        this.grid = grid;
        this.visited = new boolean[rows][cols];
    }

    /**
     * Orchestrates the finding, sorting, and filling of lakes.
     */
    public void process() {
        List<Lake> lakes = findLakes();
        Collections.sort(lakes);

        int totalFilledSize = 0;
        // The requirement is to keep the 'k' largest lakes.
        // Since lakes are sorted ascending, we fill from the start up to (size - k).
        int numToFill = Math.max(0, lakes.size() - keepCount);

        for (int i = 0; i < numToFill; i++) {
            Lake lake = lakes.get(i);
            totalFilledSize += lake.getSize();
            fillLakeWithLand(lake.getStartRow(), lake.getStartCol());
        }

        printResults(totalFilledSize);
    }

    /**
     * Uses BFS to find all distinct lakes and their sizes.
     */
    private List<Lake> findLakes() {
        List<Lake> foundLakes = new ArrayList<>();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && !visited[r][c]) {
                    int size = countLakeSizeBFS(r, c);
                    if (size > 0) {
                        foundLakes.add(new Lake(r, c, size));
                    }
                }
            }
        }
        return foundLakes;
    }

    /**
     * BFS implementation to count the size of a lake component.
     */
    private int countLakeSizeBFS(int startR, int startC) {
        int size = 0;
        Queue<int[]> queue = new LinkedList<>();

        queue.add(new int[]{startR, startC});
        visited[startR][startC] = true;

        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            size++;

            for (int[] dir : DIRECTIONS) {
                int nr = curr[0] + dir[0];
                int nc = curr[1] + dir[1];

                if (isValid(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    queue.add(new int[]{nr, nc});
                }
            }
        }
        return size;
    }

    /**
     * BFS implementation to convert a lake component into land ('*').
     */
    private void fillLakeWithLand(int startR, int startC) {
        Queue<int[]> queue = new LinkedList<>();
        queue.add(new int[]{startR, startC});
        grid[startR][startC] = '*';

        while (!queue.isEmpty()) {
            int[] curr = queue.poll();

            for (int[] dir : DIRECTIONS) {
                int nr = curr[0] + dir[0];
                int nc = curr[1] + dir[1];

                if (isValid(nr, nc) && grid[nr][nc] == '.') {
                    grid[nr][nc] = '*';
                    queue.add(new int[]{nr, nc});
                }
            }
        }
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private void printResults(int totalSize) {
        System.out.println(totalSize);
        StringBuilder sb = new StringBuilder();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                sb.append(grid[r][c]);
            }
            sb.append("\n");
        }
        System.out.print(sb.toString());
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        int keepCount = scanner.nextInt();
        scanner.nextLine(); // Consume newline

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.nextLine();
            grid[i] = line.toCharArray();
        }

        LakeProcessor processor = new LakeProcessor(rows, cols, keepCount, grid);
        processor.process();

        scanner.close();
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to identify "lakes" (connected components of '.') in a grid
 * and fill the smallest lakes with '*' until a target number of lakes (k) is reached.
 */
public class Solution {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            int targetLakeCount = reader.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.nextLine().toCharArray();
            }

            GridProcessor processor = new GridProcessor(grid, rows, cols);
            processor.solve(targetLakeCount, writer);

        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Represents a coordinate in the 2D grid.
     */
    record Point(int r, int c) {}

    /**
     * Represents a lake found in the grid.
     */
    static class Lake {
        private final List<Point> points;

        Lake(List<Point> points) {
            this.points = points;
        }

        public int getSize() {
            return points.size();
        }

        public List<Point> getPoints() {
            return points;
        }
    }

    /**
     * Handles the logic of processing the grid and identifying lakes.
     */
    static class GridProcessor {
        private final char[][] grid;
        private final int rows;
        private final int cols;
        private final boolean[][] visited;

        private static final int[] DR = {0, 0, 1, -1};
        private static final int[] DC = {1, -1, 0, 0};

        public GridProcessor(char[][] grid, int rows, int cols) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
            this.visited = new boolean[rows][cols];
        }

        public void solve(int k, PrintWriter out) {
            // 1. Mark all '.' connected to the boundaries (the "ocean") as visited.
            // These are not lakes.
            markOcean();

            // 2. Identify all isolated lakes.
            List<Lake> lakes = findLakes();

            // 3. If we have exactly k lakes, we don't need to fill anything.
            if (lakes.size() == k) {
                printGrid(out);
                return;
            }

            // 4. If we have more than k lakes, fill the smallest lakes first.
            if (lakes.size() > k) {
                lakes.sort(Comparator.comparingInt(Lake::getSize));

                int lakesToRemove = lakes.size() - k;
                int cellsFilled = 0;

                for (int i = 0; i < lakesToRemove; i++) {
                    for (Point p : lakes.get(i).getPoints()) {
                        grid[p.r][p.c] = '*';
                        cellsFilled++;
                    }
                }
                out.println(cellsFilled);
            } else {
                // If lakes.size() < k, the original logic implies doing nothing.
                out.println(0);
            }

            printGrid(out);
        }

        private void markOcean() {
            // Check first and last rows
            for (int j = 0; j < cols; j++) {
                if (grid[0][j] == '.') bfs(0, j);
                if (grid[rows - 1][j] == '.') bfs(rows - 1, j);
            }
            // Check first and last columns
            for (int i = 0; i < rows; i++) {
                if (grid[i][0] == '.') bfs(i, 0);
                if (grid[i][cols - 1] == '.') bfs(i, cols - 1);
            }
        }

        private List<Lake> findLakes() {
            List<Lake> lakes = new ArrayList<>();
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.' && !visited[i][j]) {
                        List<Point> lakePoints = bfs(i, j);
                        lakes.add(new Lake(lakePoints));
                    }
                }
            }
            return lakes;
        }

        /**
         * Iterative BFS to find all connected '.' cells.
         * Returns the list of points in the component.
         */
        private List<Point> bfs(int startR, int startC) {
            List<Point> component = new ArrayList<>();
            // If already visited, we still return the component if used for marking ocean,
            // but here we only call BFS on unvisited cells.
            if (visited[startR][startC]) {
                // This part handles the boundary 'markOcean' logic where we 
                // don't want to return a component list, just mark visited.
                // However, for code simplicity, we'll use this to return points.
                // If this is just marking ocean, the caller ignores the list.
            }

            Queue<Point> queue = new ArrayDeque<>();
            Point start = new Point(startR, startC);
            queue.add(start);
            visited[startR][startC] = true;

            while (!queue.isEmpty()) {
                Point curr = queue.poll();
                component.add(curr);

                for (int i = 0; i < 4; i++) {
                    int nr = curr.r + DR[i];
                    int nc = curr.c + DC[i];

                    if (isValid(nr, nc) && !visited[nr][nc] && grid[nr][nc] == '.') {
                        visited[nr][nc] = true;
                        queue.add(new Point(nr, nc));
                    }
                }
            }
            return component;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        private void printGrid(PrintWriter out) {
            for (int i = 0; i < rows; i++) {
                out.println(new String(grid[i]));
            }
        }
    }

    /**
     * Fast I/O utility.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public String nextLine() throws IOException {
            return reader.readLine();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for finding the maximum area of at most K enclosed components in a grid.
 */
public class Round375D {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int n = reader.nextInt();
            int m = reader.nextInt();
            int k = reader.nextInt();

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                String line = reader.next();
                for (int j = 0; j < m; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }

            GridSolver solver = new GridSolver(n, m, k, grid);
            solver.solve(writer);

        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Logic handler for the grid processing problem.
     */
    static class GridSolver {
        private final int n;
        private final int m;
        private final int k;
        private final char[][] grid;
        private final boolean[][] visited;

        private static final int[] DR = {1, -1, 0, 0};
        private static final int[] DC = {0, 0, 1, -1};

        public GridSolver(int n, int m, int k, char[][] grid) {
            this.n = n;
            this.m = m;
            this.k = k;
            this.grid = grid;
            this.visited = new boolean[n][m];
        }

        public void solve(PrintWriter out) {
            // 1. Mark all '.' cells connected to the boundary (not enclosed)
            markBoundaryComponents();

            // 2. Find all enclosed components
            List<Component> components = findEnclosedComponents();

            // 3. Sort components by size in descending order
            Collections.sort(components);

            // 4. Calculate maximum area using at most k components
            long maxArea = 0;
            int componentsToKeep = Math.min(k, components.size());
            for (int i = 0; i < componentsToKeep; i++) {
                maxArea += components.get(i).size;
            }

            // 5. Construct the final grid
            // All '.' become '*' unless they belong to the top K largest components
            char[][] resultGrid = new char[n][m];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    resultGrid[i][j] = (grid[i][j] == '*') ? '*' : '*';
                }
            }

            for (int i = 0; i < componentsToKeep; i++) {
                for (int cellIdx : components.get(i).cells) {
                    int r = cellIdx / m;
                    int c = cellIdx % m;
                    resultGrid[r][c] = '.';
                }
            }

            // Print results
            out.println(maxArea);
            for (int i = 0; i < n; i++) {
                out.println(new String(resultGrid[i]));
            }
        }

        private void markBoundaryComponents() {
            for (int i = 0; i < n; i++) {
                if (grid[i][0] == '.' && !visited[i][0]) bfs(i, 0);
                if (grid[i][m - 1] == '.' && !visited[i][m - 1]) bfs(i, m - 1);
            }
            for (int j = 0; j < m; j++) {
                if (grid[0][j] == '.' && !visited[0][j]) bfs(0, j);
                if (grid[n - 1][j] == '.' && !visited[n - 1][j]) bfs(n - 1, j);
            }
        }

        private List<Component> findEnclosedComponents() {
            List<Component> components = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == '.' && !visited[i][j]) {
                        components.add(bfs(i, j));
                    }
                }
            }
            return components;
        }

        /**
         * Iterative BFS to find and mark a connected component.
         * @return A Component object containing size and cell indices.
         */
        private Component bfs(int startR, int startC) {
            List<Integer> cellList = new ArrayList<>();
            Deque<Integer> queue = new ArrayDeque<>();

            int startIdx = startR * m + startC;
            queue.add(startIdx);
            visited[startR][startC] = true;

            while (!queue.isEmpty()) {
                int currIdx = queue.poll();
                cellList.add(currIdx);

                int r = currIdx / m;
                int c = currIdx % m;

                for (int i = 0; i < 4; i++) {
                    int nr = r + DR[i];
                    int nc = c + DC[i];

                    if (nr >= 0 && nr < n && nc >= 0 && nc < m &&
                            grid[nr][nc] == '.' && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        queue.add(nr * m + nc);
                    }
                }
            }

            // Convert to primitive array for memory efficiency
            int[] cells = new int[cellList.size()];
            for (int i = 0; i < cellList.size(); i++) {
                cells[i] = cellList.get(i);
            }
            return new Component(cells);
        }
    }

    /**
     * Represents a connected component of '.' cells.
     */
    static class Component implements Comparable<Component> {
        final int size;
        final int[] cells;

        Component(int[] cells) {
            this.cells = cells;
            this.size = cells.length;
        }

        @Override
        public int compareTo(Component other) {
            // Sort descending by size
            return Integer.compare(other.size, this.size);
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * Refactored solution for the grid component optimization problem.
 * The goal is to identify connected components of '.' cells, 
 * separating those connected to the boundary, and removing the smallest 
 * internal components to satisfy the target count k.
 */
public class GridBorderOptimizer {

    public static void main(String[] args) throws IOException {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        Solver solver = new Solver(reader);
        solver.solve(writer);

        writer.flush();
        writer.close();
    }

    /**
     * Represents a coordinate in the grid.
     */
    static class Point {
        int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Represents a connected component of '.' cells.
     */
    static class Component implements Comparable<Component> {
        int size;
        int id;
        List<Point> cells;

        Component(int id, List<Point> cells) {
            this.id = id;
            this.cells = cells;
            this.size = cells.size();
        }

        @Override
        public int compareTo(Component other) {
            return Integer.compare(this.size, other.size);
        }
    }

    static class Solver {
        private final int n, m, k;
        private final char[][] grid;
        private final int[][] visited;
        private final int[] dr = {0, 1, 0, -1};
        private final int[] dc = {1, 0, -1, 0};

        public Solver(FastReader reader) throws IOException {
            this.n = reader.nextInt();
            this.m = reader.nextInt();
            this.k = reader.nextInt();
            this.grid = new char[n][m];
            this.visited = new int[n][m];

            for (int i = 0; i < n; i++) {
                String line = reader.next();
                for (int j = 0; j < m; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }
        }

        public void solve(PrintWriter out) {
            // 1. Mark boundary-connected components
            // We use -1 to distinguish boundary-connected '.' from internal components.
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (isBoundary(i, j) && grid[i][j] == '.' && visited[i][j] == 0) {
                        bfs(i, j, -1);
                    }
                }
            }

            // 2. Find all internal components
            List<Component> internalComponents = new ArrayList<>();
            int componentIdCounter = 1;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == '.' && visited[i][j] == 0) {
                        List<Point> componentCells = bfs(i, j, componentIdCounter);
                        internalComponents.add(new Component(componentIdCounter++, componentCells));
                    }
                }
            }

            // 3. Sort components to remove the smallest ones first
            Collections.sort(internalComponents);

            // 4. Remove (InternalSize - k) smallest components
            int componentsToRemoveCount = Math.max(0, internalComponents.size() - k);
            int turnedToAsteriskCount = 0;

            for (int i = 0; i < componentsToRemoveCount; i++) {
                Component comp = internalComponents.get(i);
                turnedToAsteriskCount += comp.size;
                for (Point p : comp.cells) {
                    grid[p.r][p.c] = '*';
                }
            }

            // 5. Output results
            out.println(turnedToAsteriskCount);
            for (int i = 0; i < n; i++) {
                out.println(new String(grid[i]));
            }
        }

        private boolean isBoundary(int r, int c) {
            return r == 0 || r == n - 1 || c == 0 || c == m - 1;
        }

        /**
         * Breadth-First Search to traverse connected '.' cells.
         * @return A list of points belonging to the component.
         */
        private List<Point> bfs(int startR, int startC, int id) {
            List<Point> componentCells = new ArrayList<>();
            Queue<Point> queue = new LinkedList<>();

            Point start = new Point(startR, startC);
            queue.add(start);
            visited[startR][startC] = id;
            componentCells.add(start);

            while (!queue.isEmpty()) {
                Point curr = queue.poll();

                for (int i = 0; i < 4; i++) {
                    int nr = curr.r + dr[i];
                    int nc = curr.c + dc[i];

                    if (isValid(nr, nc)) {
                        visited[nr][nc] = id;
                        Point next = new Point(nr, nc);
                        queue.add(next);
                        componentCells.add(next);
                    }
                }
            }
            return componentCells;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < n && c >= 0 && c < m && grid[r][c] == '.' && visited[r][c] == 0;
        }
    }

    /**
     * High-performance input reader.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.*;

/**
 * IslandManager identifies connected land components in a grid.
 * It distinguishes between coastal land (ocean) and isolated islands,
 * and ensures only the K largest islands are preserved.
 */
public class IslandManager {

    public record Point(int row, int col) {}

    private static class Island implements Comparable<Island> {
        private final List<Point> points;
        private final boolean isOcean;

        public Island(List<Point> points, boolean isOcean) {
            this.points = points;
            this.isOcean = isOcean;
        }

        public int getSize() {
            return points.size();
        }

        public boolean isOcean() {
            return isOcean;
        }

        public List<Point> getPoints() {
            return points;
        }

        @Override
        public int compareTo(Island other) {
            return Integer.compare(this.getSize(), other.getSize());
        }
    }

    private static final int[][] DIRECTIONS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
    private static final char LAND = '.';
    private static final char OCEAN = '*';

    public static void main(String[] args) {
        try {
            new IslandSolver(System.in).run();
        } catch (IOException e) {
            System.err.println("Fatal error: " + e.getMessage());
        }
    }

    private static class IslandSolver {
        private final BufferedReader reader;
        private int rows;
        private int cols;
        private int k;
        private char[][] grid;

        public IslandSolver(java.io.InputStream in) {
            this.reader = new BufferedReader(new InputStreamReader(in));
        }

        public void run() throws IOException {
            if (!readInput()) return;

            boolean[][] visited = new boolean[rows][cols];
            PriorityQueue<Island> islands = new PriorityQueue<>();

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == LAND && !visited[r][c]) {
                        Island island = exploreComponent(r, c, visited);
                        if (!island.isOcean()) {
                            islands.add(island);
                        }
                    }
                }
            }

            int removedLandCount = 0;
            while (islands.size() > k) {
                Island smallest = islands.poll();
                removedLandCount += smallest.getSize();
                for (Point p : smallest.getPoints()) {
                    grid[p.row()][p.col()] = OCEAN;
                }
            }

            printOutput(removedLandCount);
        }

        private boolean readInput() throws IOException {
            String line = reader.readLine();
            if (line == null) return false;

            StringTokenizer st = new StringTokenizer(line);
            rows = Integer.parseInt(st.nextToken());
            cols = Integer.parseInt(st.nextToken());
            k = Integer.parseInt(st.nextToken());

            grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.readLine().trim().toCharArray();
            }
            return true;
        }

        private Island exploreComponent(int startR, int startC, boolean[][] visited) {
            List<Point> component = new ArrayList<>();
            Deque<Point> queue = new ArrayDeque<>();
            boolean touchesBoundary = false;

            queue.add(new Point(startR, startC));
            visited[startR][startC] = true;

            while (!queue.isEmpty()) {
                Point curr = queue.poll();
                component.add(curr);

                if (curr.row() == 0 || curr.row() == rows - 1 || 
                    curr.col() == 0 || curr.col() == cols - 1) {
                    touchesBoundary = true;
                }

                for (int[] d : DIRECTIONS) {
                    int nr = curr.row() + d[0];
                    int nc = curr.col() + d[1];

                    if (isValid(nr, nc, visited)) {
                        visited[nr][nc] = true;
                        queue.add(new Point(nr, nc));
                    }
                }
            }
            return new Island(component, touchesBoundary);
        }

        private boolean isValid(int r, int c, boolean[][] visited) {
            return r >= 0 && r < rows && c >= 0 && c < cols 
                   && grid[r][c] == LAND && !visited[r][c];
        }

        private void printOutput(int removedCount) {
            System.out.println(removedCount);
            for (char[] row : grid) {
                System.out.println(new String(row));
            }
        }
    }
}

import java.util.*;

/**
 * A program that identifies enclosed water bodies (lakes) in a grid,
 * sorts them by size, and simulates filling specific lakes with land.
 */
public class LakeManager {

    private static final int[] ROW_DIRECTIONS = {-1, 1, 0, 0};
    private static final int[] COL_DIRECTIONS = {0, 0, -1, 1};

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        int skipCount = scanner.nextInt();
        scanner.nextLine(); // Consume newline

        char[][] originalGrid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.nextLine();
            for (int j = 0; j < cols; j++) {
                originalGrid[i][j] = line.charAt(j);
            }
        }

        solve(originalGrid, rows, cols, skipCount);
        scanner.close();
    }

    /**
     * Executes the core logic of the lake filling simulation.
     */
    private static void solve(char[][] originalGrid, int rows, int cols, int skipCount) {
        // 'workingGrid' is used to identify which water is 'ocean' (connected to boundary)
        char[][] workingGrid = copyGrid(originalGrid, rows, cols);
        // 'outputGrid' will be the grid where specific lakes are filled with land '*'
        char[][] outputGrid = copyGrid(originalGrid, rows, cols);

        // 1. Convert all ocean water to land in the working grid to isolate lakes
        markOceanAsLand(workingGrid, rows, cols);

        // 2. Find all enclosed lakes in the working grid
        List<Lake> lakes = findLakes(workingGrid, rows, cols);

        // 3. Sort lakes by size in descending order
        lakes.sort(Comparator.comparingInt((Lake l) -> l.size).reversed());

        // 4. Calculate area and fill lakes based on the skipCount logic
        // The original logic fills all lakes starting from index 'skipCount'
        int filledArea = 0;
        for (int i = skipCount; i < lakes.size(); i++) {
            Lake lakeToFill = lakes.get(i);
            filledArea += lakeToFill.size;
            fillLakeInGrid(outputGrid, lakeToFill, rows, cols);
        }

        // 5. Output results
        System.out.println(filledArea);
        printGrid(outputGrid, rows, cols);
    }

    /**
     * Identifies all water cells connected to the boundaries and turns them into land.
     */
    private static void markOceanAsLand(char[][] grid, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            if (grid[i][0] == '.') floodFill(grid, i, 0, rows, cols, '*');
            if (grid[i][cols - 1] == '.') floodFill(grid, i, cols - 1, rows, cols, '*');
        }
        for (int j = 0; j < cols; j++) {
            if (grid[0][j] == '.') floodFill(grid, 0, j, rows, cols, '*');
            if (grid[rows - 1][j] == '.') floodFill(grid, rows - 1, j, rows, cols, '*');
        }
    }

    /**
     * Scans the grid to find all isolated water bodies (lakes).
     */
    private static List<Lake> findLakes(char[][] grid, int rows, int cols) {
        List<Lake> lakes = new ArrayList<>();
        boolean[][] visited = new boolean[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.' && !visited[i][j]) {
                    lakes.add(discoverLake(grid, i, j, rows, cols, visited));
                }
            }
        }
        return lakes;
    }

    /**
     * Uses BFS to discover all coordinates belonging to a single lake.
     */
    private static Lake discoverLake(char[][] grid, int startR, int startC, int rows, int cols, boolean[][] visited) {
        Queue<int[]> queue = new LinkedList<>();
        queue.add(new int[]{startR, startC});
        visited[startR][startC] = true;

        Lake newLake = new Lake(startR, startC);

        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            int r = curr[0];
            int c = curr[1];
            newLake.addCell(r, c);

            for (int i = 0; i < 4; i++) {
                int nr = r + ROW_DIRECTIONS[i];
                int nc = c + COL_DIRECTIONS[i];

                if (isValid(nr, nc, rows, cols) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    queue.add(new int[]{nr, nc});
                }
            }
        }
        newLake.size = newLake.cells.size();
        return newLake;
    }

    /**
     * Standard Flood Fill algorithm.
     */
    private static void floodFill(char[][] grid, int r, int c, int rows, int cols, char targetChar) {
        floodFill(grid, r, c, rows, cols, targetChar, '*');
    }

    private static void floodFill(char[][] grid, int r, int c, int rows, int cols, char targetChar, char replacement) {
        if (!isValid(r, c, rows, cols) || grid[r][c] != targetChar) {
            return;
        }
        grid[r][c] = replacement;
        for (int i = 0; i < 4; i++) {
            floodFill(grid, r + ROW_DIRECTIONS[i], c + COL_DIRECTIONS[i], rows, cols, targetChar, replacement);
        }
    }

    /**
     * Fills a specific lake's coordinates with land in the output grid.
     */
    private static void fillLakeInGrid(char[][] grid, Lake lake, int rows, int cols) {
        for (int[] cell : lake.cells) {
            grid[cell[0]][cell[1]] = '*';
        }
    }

    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private static char[][] copyGrid(char[][] original, int rows, int cols) {
        char[][] copy = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            System.arraycopy(original[i], 0, copy[i], 0, cols);
        }
        return copy;
    }

    private static void printGrid(char[][] grid, int rows, int cols) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                sb.append(grid[i][j]);
            }
            sb.append("\n");
        }
        System.out.print(sb.toString());
    }

    /**
     * Represents a single water body.
     */
    static class Lake {
        int size;
        int startRow;
        int startCol;
        List<int[]> cells;

        Lake(int row, int col) {
            this.startRow = row;
            this.startCol = col;
            this.cells = new ArrayList<>();
        }

        void addCell(int r, int c) {
            cells.add(new int[]{r, c});
        }
    }
}

