import java.util.*;

/**
 * Solves the problem of identifying lakes in a grid and destroying the smallest ones
 * until a required number of lakes remain.
 */
public class Codeforces {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        int requiredLakesCount = scanner.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            grid[i] = line.toCharArray();
        }

        LakeSolver solver = new LakeSolver(rows, cols, grid);
        solver.solve(requiredLakesCount);
    }

    /**
     * Represents a coordinate in the 2D grid.
     */
    private record Point(int row, int col) {}

    private static class LakeSolver {
        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final boolean[][] visited;

        // Direction vectors for 4-connectivity (up, down, left, right)
        private static final int[] ROW_OFFSETS = {0, 0, 1, -1};
        private static final int[] COL_OFFSETS = {1, -1, 0, 0};

        public LakeSolver(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            this.visited = new boolean[rows][cols];
        }

        /**
         * Executes the main logic: find lakes, sort them, destroy necessary ones, and print.
         */
        public void solve(int requiredLakesCount) {
            // 1. Identify all water connected to the boundary (the ocean)
            markOcean();

            // 2. Identify all disconnected water bodies (the lakes)
            List<List<Point>> lakes = findLakes();

            // 3. Sort lakes by size (ascending) to target the smallest ones first
            lakes.sort(Comparator.comparingInt(List::size));

            // 4. Destroy lakes until the required number remains
            int lakesToDestroy = Math.max(0, lakes.size() - requiredLakesCount);
            int totalCellsChanged = 0;

            for (int i = 0; i < lakesToDestroy; i++) {
                for (Point p : lakes.get(i)) {
                    grid[p.row][p.col] = '*';
                    totalCellsChanged++;
                }
            }

            // 5. Output results
            System.out.println(totalCellsChanged);
            printGrid();
        }

        /**
         * Performs BFS from all boundary '.' cells to mark the entire ocean as visited.
         */
        private void markOcean() {
            Queue<Point> queue = new ArrayDeque<>();

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (isBoundary(r, c) && grid[r][c] == '.' && !visited[r][c]) {
                        visited[r][c] = true;
                        queue.add(new Point(r, c));
                    }
                }
            }

            bfs(queue);
        }

        /**
         * Iterates through the grid to find unvisited '.' cells, which represent lakes.
         */
        private List<List<Point>> findLakes() {
            List<List<Point>> lakes = new ArrayList<>();
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.' && !visited[r][c]) {
                        lakes.add(extractLake(r, c));
                    }
                }
            }
            return lakes;
        }

        /**
         * Uses BFS to collect all points belonging to a specific lake.
         */
        private List<Point> extractLake(int startRow, int startCol) {
            List<Point> lakePoints = new ArrayList<>();
            Queue<Point> queue = new ArrayDeque<>();

            visited[startRow][startCol] = true;
            queue.add(new Point(startRow, startCol));

            while (!queue.isEmpty()) {
                Point current = queue.poll();
                lakePoints.add(current);

                for (int i = 0; i < 4; i++) {
                    int nr = current.row + ROW_OFFSETS[i];
                    int nc = current.col + COL_OFFSETS[i];

                    if (isValid(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        queue.add(new Point(nr, nc));
                    }
                }
            }
            return lakePoints;
        }

        /**
         * Generic BFS helper for marking visited cells.
         */
        private void bfs(Queue<Point> queue) {
            while (!queue.isEmpty()) {
                Point current = queue.poll();
                for (int i = 0; i < 4; i++) {
                    int nr = current.row + ROW_OFFSETS[i];
                    int nc = current.col + COL_OFFSETS[i];

                    if (isValid(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        queue.add(new Point(nr, nc));
                    }
                }
            }
        }

        private boolean isBoundary(int r, int c) {
            return r == 0 || r == rows - 1 || c == 0 || c == cols - 1;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        private void printGrid() {
            StringBuilder sb = new StringBuilder();
            for (int r = 0; r < rows; r++) {
                sb.append(new String(grid[r])).append('\n');
            }
            System.out.print(sb.toString());
        }
    }
}

