/**
 * Manages the grid data and provides operations to modify the terrain.
 */
class Grid {
    private final int rows;
    private final int cols;
    private final char[][] matrix;

    public Grid(int rows, int cols, char[][] initialMatrix) {
        this.rows = rows;
        this.cols = cols;
        this.matrix = initialMatrix;
    }

    public int getRows() { return rows; }
    public int getCols() { return cols; }

    public char getCell(int r, int c) {
        return matrix[r][c];
    }

    public void setCell(int r, int c, char value) {
        matrix[r][c] = value;
    }

    public boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    public boolean isEdge(int r, int c) {
        return r == 0 || r == rows - 1 || c == 0 || c == cols - 1;
    }

    public void print() {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                sb.append(matrix[i][j]);
            }
            sb.append("\n");
        }
        System.out.print(sb.toString());
    }
}

/**
 * Core engine to identify and process lakes.
 */
class LakeManager {
    private static final int[] DR = {1, -1, 0, 0};
    private static final int[] DC = {0, 0, 1, -1};

    private final Grid grid;

    public LakeManager(Grid grid) {
        this.grid = grid;
    }

    /**
     * Finds all lakes in the grid. A lake is a connected component 
     * of '.' that does not touch the grid boundaries.
     */
    public List<Lake> findLakes() {
        List<Lake> lakes = new ArrayList<>();
        boolean[][] visited = new boolean[grid.getRows()][grid.getCols()];

        for (int r = 0; r < grid.getRows(); r++) {
            for (int c = 0; c < grid.getCols(); c++) {
                if (grid.getCell(r, c) == '.' && !visited[r][c]) {
                    Optional<Lake> lake = bfs(r, c, visited);
                    lake.ifPresent(lakes::add);
                }
            }
        }
        return lakes;
    }

    private Optional<Lake> bfs(int startR, int startC, boolean[][] visited) {
        List<Point> componentCells = new ArrayList<>();
        Queue<Point> queue = new LinkedList<>();

        Point start = new Point(startR, startC);
        queue.add(start);
        visited[startR][startC] = true;

        boolean touchesBoundary = false;

        while (!queue.isEmpty()) {
            Point curr = queue.poll();
            componentCells.add(curr);

            if (grid.isEdge(curr.r(), curr.c())) {
                touchesBoundary = true;
            }

            for (int i = 0; i < 4; i++) {
                int nr = curr.r() + DR[i];
                int nc = curr.c() + DC[i];

                if (grid.isWithinBounds(nr, nc) 
                        && grid.getCell(nr, nc) == '.' 
                        && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    queue.add(new Point(nr, nc));
                }
            }
        }

        // If the component touches the boundary, it's not a lake (it's part of the sea/land).
        return touchesBoundary ? Optional.empty() : Optional.of(new Lake(componentCells));
    }

    public int coverLakes(List<Lake> lakesToCover) {
        int totalCovered = 0;
        for (Lake lake : lakesToCover) {
            totalCovered += lake.getSize();
            for (Point p : lake.getCells()) {
                grid.setCell(p.r(), p.c(), '*');
            }
        }
        return totalCovered;
    }
}

public class Main {
    public static void main(String[] args) throws IOException {
        FastReader reader = new FastReader(System.in);

        int rows = reader.nextInt();
        int cols = reader.nextInt();
        int k = reader.nextInt();

        char[][] mapData = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            mapData[i] = reader.next().toCharArray();
        }

        Grid grid = new Grid(rows, cols, mapData);
        LakeManager manager = new LakeManager(grid);

        List<Lake> allLakes = manager.findLakes();
        Collections.sort(allLakes);

        // We want to have exactly 'k' lakes remaining.
        // To maximize cells covered (based on original logic), we cover the smallest lakes first.
        int numToRemove = allLakes.size() - k;
        int coveredCount = 0;

        if (numToRemove > 0) {
            List<Lake> toCover = allLakes.subList(0, numToRemove);
            coveredCount = manager.coverLakes(toCover);
        }

        System.out.println(coveredCount);
        grid.print();
    }

    /**
     * Utility class for fast I/O.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;

/**
 * A program that identifies "real" lakes (connected components of '.' not touching the border)
 * and removes all but the k largest ones.
 */
public class LakeSolver {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        int kToKeep = scanner.nextInt();

        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        LakeProcessor processor = new LakeProcessor(grid, rows, cols);
        int totalDeletedCells = processor.processLakes(kToKeep);

        System.out.println(totalDeletedCells);
        printGrid(grid);
    }

    private static void printGrid(char[][] grid) {
        for (char[] row : grid) {
            System.out.println(new String(row));
        }
    }

    /**
     * Represents a specific coordinate in the grid.
     */
    private record Point(int r, int c) {}

    /**
     * Represents a connected component of '.' cells.
     */
    private static class Lake {
        private final List<Point> points;

        public Lake(List<Point> points) {
            this.points = points;
        }

        public int getSize() {
            return points.size();
        }

        public List<Point> getPoints() {
            return points;
        }
    }

    /**
     * Handles the logic of finding and manipulating lakes within the grid.
     */
    private static class LakeProcessor {
        private final char[][] grid;
        private final int rows;
        private final int cols;

        private static final int[][] DIRECTIONS = {
            {0, 1}, {0, -1}, {1, 0}, {-1, 0}
        };

        public LakeProcessor(char[][] grid, int rows, int cols) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
        }

        /**
         * Identifies real lakes, sorts them, and removes the smallest ones 
         * such that only kToKeep lakes remain.
         * 
         * @param kToKeep The number of largest real lakes to preserve.
         * @return The total number of '.' cells converted to '*'.
         */
        public int processLakes(int kToKeep) {
            List<Lake> realLakes = findAllRealLakes();

            // Sort lakes by size ascending (smallest first)
            realLakes.sort(Comparator.comparingInt(Lake::getSize));

            // The original logic: Keep the k largest. 
            // Therefore, we delete (Total - k) smallest lakes.
            int numToRemove = Math.max(0, realLakes.size() - kToKeep);
            int totalDeletedPoints = 0;

            for (int i = 0; i < numToRemove; i++) {
                Lake lake = realLakes.get(i);
                totalDeletedPoints += lake.getSize();
                for (Point p : lake.getPoints()) {
                    grid[p.r][p.c] = '*';
                }
            }

            return totalDeletedPoints;
        }

        private List<Lake> findAllRealLakes() {
            List<Lake> realLakes = new ArrayList<>();
            boolean[][] visited = new boolean[rows][cols];

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.' && !visited[r][c]) {
                        Lake lake = performBFS(r, c, visited);
                        if (!isBorderLake(lake)) {
                            realLakes.add(lake);
                        }
                    }
                }
            }
            return realLakes;
        }

        /**
         * Uses iterative BFS to find all connected '.' cells.
         */
        private Lake performBFS(int startR, int startC, boolean[][] visited) {
            List<Point> component = new ArrayList<>();
            Deque<Point> queue = new ArrayDeque<>();

            Point start = new Point(startR, startC);
            queue.add(start);
            visited[startR][startC] = true;

            while (!queue.isEmpty()) {
                Point curr = queue.poll();
                component.add(curr);

                for (int[] dir : DIRECTIONS) {
                    int nr = curr.r + dir[0];
                    int nc = curr.c + dir[1];

                    if (isValid(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        queue.add(new Point(nr, nc));
                    }
                }
            }
            return new Lake(component);
        }

        private boolean isBorderLake(Lake lake) {
            for (Point p : lake.getPoints()) {
                if (p.r == 0 || p.r == rows - 1 || p.c == 0 || p.c == cols - 1) {
                    return true;
                }
            }
            return false;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }
}

