/**
 * Represents a connected component of '.' cells in the grid.
 *
 * @param startRow The starting row index of the component.
 * @param startCol The starting column index of the component.
 * @param size     The total number of cells in the component.
 */
record Component(int startRow, int startCol, int size) {}

class GridSolver {
    private final char[][] grid;
    private final int rows;
    private final int cols;
    private final boolean[][] visited;
    private int totalRemovedSize = 0;

    private static final int[][] DIRECTIONS = {
        {1, 0}, {-1, 0}, {0, 1}, {0, -1}
    };

    public GridSolver(char[][] grid, int rows, int cols) {
        this.grid = grid;
        this.rows = rows;
        this.cols = cols;
        this.visited = new boolean[rows][cols];
    }

    /**
     * Executes the core logic: finding components, sorting them, 
     * and filling the smallest non-boundary components.
     *
     * @param k The threshold for how many components to keep.
     */
    public void solve(int k) {
        List<Component> nonBoundaryComponents = new ArrayList<>();

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.' && !visited[i][j]) {
                    DFSResult result = findComponent(i, j);
                    if (!result.touchesBoundary) {
                        nonBoundaryComponents.add(new Component(result.startRow, result.startCol, result.size));
                    }
                }
            }
        }

        // Sort components by size ascending
        nonBoundaryComponents.sort(Comparator.comparingInt(Component::size));

        // The original logic processes (total - k) smallest components
        int componentsToFill = nonBoundaryComponents.size() - k;
        for (int i = 0; i < componentsToFill; i++) {
            Component comp = nonBoundaryComponents.get(i);
            fillComponentWithAsterisk(comp.startRow(), comp.startCol());
            totalRemovedSize += comp.size();
        }
    }

    /**
     * Performs DFS to find the size and boundary status of a component.
     */
    private DFSResult findComponent(int r, int c) {
        int size = 0;
        boolean touchesBoundary = false;
        Stack<int[]> stack = new Stack<>();

        stack.push(new int[]{r, c});
        visited[r][c] = true;

        while (!stack.isEmpty()) {
            int[] curr = stack.pop();
            int currR = curr[0];
            int currC = curr[1];
            size++;

            // Check if cell is on the grid boundary
            if (currR == 0 || currR == rows - 1 || currC == 0 || currC == cols - 1) {
                touchesBoundary = true;
            }

            for (int[] dir : DIRECTIONS) {
                int nr = currR + dir[0];
                int nc = currC + dir[1];

                if (isValid(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    stack.push(new int[]{nr, nc});
                }
            }
        }

        return new DFSResult(r, c, size, touchesBoundary);
    }

    /**
     * Flood-fills a component by replacing '.' with '*'.
     */
    private void fillComponentWithAsterisk(int r, int c) {
        if (!isValid(r, c) || grid[r][c] != '.') {
            return;
        }

        Stack<int[]> stack = new Stack<>();
        stack.push(new int[]{r, c});
        grid[r][c] = '*';

        while (!stack.isEmpty()) {
            int[] curr = stack.pop();
            for (int[] dir : DIRECTIONS) {
                int nr = curr[0] + dir[0];
                int nc = curr[1] + dir[1];
                if (isValid(nr, nc) && grid[nr][nc] == '.') {
                    grid[nr][nc] = '*';
                    stack.push(new int[]{nr, nc});
                }
            }
        }
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    public void printResult() {
        System.out.println(totalRemovedSize);
        for (int i = 0; i < rows; i++) {
            System.out.println(new String(grid[i]));
        }
    }

    /**
     * Helper class to return multiple values from the DFS search.
     */
    private static class DFSResult {
        final int startRow;
        final int startCol;
        final int size;
        final boolean touchesBoundary;

        DFSResult(int startRow, int startCol, int size, boolean touchesBoundary) {
            this.startRow = startRow;
            this.startCol = startCol;
            this.size = size;
            this.touchesBoundary = touchesBoundary;
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * Problem: Lakes in Berland
 * Identifies connected components of '.' that do not touch the grid boundaries (lakes)
 * and fills the smallest lakes with '*' until only K lakes remain.
 */
public class LakesinBerland {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            int k = reader.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            LakeSolver solver = new LakeSolver(grid, rows, cols, k);
            solver.solve(out);
        } catch (Exception e) {
            // In a production environment, use a logger
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Core logic for identifying and manipulating lakes.
     */
    static class LakeSolver {
        private final char[][] grid;
        private final int rows;
        private final int cols;
        private final int targetLakeCount;
        private final boolean[][] visited;

        private static final int[] DX = {-1, 0, 1, 0};
        private static final int[] DY = {0, 1, 0, -1};

        public LakeSolver(char[][] grid, int rows, int cols, int targetLakeCount) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
            this.targetLakeCount = targetLakeCount;
            this.visited = new boolean[rows][cols];
        }

        public void solve(PrintWriter out) {
            List<Lake> lakes = findLakes();

            // Sort lakes by size ascending to fill the smallest ones first
            lakes.sort(Comparator.comparingInt(lake -> lake.size));

            int totalFilledSize = 0;
            int lakesToFill = Math.max(0, lakes.size() - targetLakeCount);

            // Reset visited array for the filling phase
            for (int i = 0; i < rows; i++) {
                Arrays.fill(visited[i], false);
            }

            for (int i = 0; i < lakesToFill; i++) {
                Lake lake = lakes.get(i);
                totalFilledSize += fillLake(lake.startRow, lake.startCol);
            }

            out.println(totalFilledSize);
            for (int i = 0; i < rows; i++) {
                out.println(new String(grid[i]));
            }
        }

        /**
         * Iterates through the grid to find all valid lakes using BFS.
         */
        private List<Lake> findLakes() {
            List<Lake> lakes = new ArrayList<>();

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.' && !visited[i][j]) {
                        Component comp = exploreComponent(i, j);
                        if (!comp.touchesEdge) {
                            lakes.add(new Lake(comp.startRow, comp.startCol, comp.size));
                        }
                    }
                }
            }
            return lakes;
        }

        /**
         * BFS to explore a connected component of '.' cells.
         */
        private Component exploreComponent(int startR, int startC) {
            int size = 0;
            boolean touchesEdge = false;
            Queue<int[]> queue = new LinkedList<>();

            queue.add(new int[]{startR, startC});
            visited[startR][startC] = true;

            while (!queue.isEmpty()) {
                int[] curr = queue.poll();
                int r = curr[0];
                int c = curr[1];
                size++;

                if (isAtBoundary(r, c)) {
                    touchesEdge = true;
                }

                for (int i = 0; i < 4; i++) {
                    int nr = r + DX[i];
                    int nc = c + DY[i];

                    if (isValid(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        queue.add(new int[]{nr, nc});
                    }
                }
            }
            return new Component(size, touchesEdge, startR, startC);
        }

        /**
         * Uses BFS to convert a lake's cells from '.' to '*'.
         * Returns the number of cells changed.
         */
        private int fillLake(int startR, int startC) {
            int filledCount = 0;
            Queue<int[]> queue = new LinkedList<>();

            queue.add(new int[]{startR, startC});
            grid[startR][startC] = '*';
            visited[startR][startC] = true;
            filledCount++;

            while (!queue.isEmpty()) {
                int[] curr = queue.poll();
                int r = curr[0];
                int c = curr[1];

                for (int i = 0; i < 4; i++) {
                    int nr = r + DX[i];
                    int nc = c + DY[i];

                    if (isValid(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        grid[nr][nc] = '*';
                        filledCount++;
                        queue.add(new int[]{nr, nc});
                    }
                }
            }
            return filledCount;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        private boolean isAtBoundary(int r, int c) {
            return r == 0 || r == rows - 1 || c == 0 || c == cols - 1;
        }
    }

    /**
     * Represents a discovered lake.
     */
    static class Lake {
        final int startRow;
        final int startCol;
        final int size;

        Lake(int startRow, int startCol, int size) {
            this.startRow = startRow;
            this.startCol = startCol;
            this.size = size;
        }
    }

    /**
     * Internal helper to store data during grid exploration.
     */
    static class Component {
        final int size;
        final boolean touchesEdge;
        final int startRow;
        final int startCol;

        Component(int size, boolean touchesEdge, int startRow, int startCol) {
            this.size = size;
            this.touchesEdge = touchesEdge;
            this.startRow = startRow;
            this.startCol = startCol;
        }
    }

    /**
     * Efficient input reader for large datasets.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public void close() throws IOException {
            reader.close();
        }
    }
}

import java.util.*;

/**
 * Represents a single coordinate in the grid.
 */
class Point {
    private final int row;
    private final int col;

    public Point(int row, int col) {
        this.row = row;
        this.col = col;
    }

    public int getRow() { return row; }
    public int getCol() { return col; }
}

/**
 * Represents a collection of connected water cells (a lake).
 */
class Lake {
    private final List<Point> points;

    public Lake(List<Point> points) {
        this.points = points;
    }

    public List<Point> getPoints() {
        return points;
    }

    public int getSize() {
        return points.size();
    }
}

/**
 * Handles the logic for identifying and manipulating lakes within a grid.
 */
class LakeManager {
    private static final int[][] DIRECTIONS = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final boolean[][] visited;

    public LakeManager(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.visited = new boolean[rows][cols];
    }

    /**
     * Finds all lakes (connected water components not touching the border).
     * @return A list of identified lakes.
     */
    public List<Lake> findLakes() {
        List<Lake> lakes = new ArrayList<>();

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (isWater(r, c) && !visited[r][c]) {
                    Lake lake = exploreComponent(r, c);
                    if (lake != null) {
                        lakes.add(lake);
                    }
                }
            }
        }
        return lakes;
    }

    private Lake exploreComponent(int startR, int startC) {
        Deque<Point> stack = new ArrayDeque<>();
        List<Point> componentPoints = new ArrayList<>();
        boolean touchesBorder = false;

        visited[startR][startC] = true;
        stack.push(new Point(startR, startC));

        while (!stack.isEmpty()) {
            Point current = stack.pop();
            componentPoints.add(current);

            if (isOnBorder(current.getRow(), current.getCol())) {
                touchesBorder = true;
            }

            for (int[] dir : DIRECTIONS) {
                int nextR = current.getRow() + dir[0];
                int nextC = current.getCol() + dir[1];

                if (isValid(nextR, nextC) && isWater(nextR, nextC) && !visited[nextR][nextC]) {
                    visited[nextR][nextC] = true;
                    stack.push(new Point(nextR, nextC));
                }
            }
        }

        // If the component touches the border, it's considered ocean, not a lake.
        return touchesBorder ? null : new Lake(componentPoints);
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private boolean isWater(int r, int c) {
        return grid[r][c] == '.';
    }

    private boolean isOnBorder(int r, int c) {
        return r == 0 || r == rows - 1 || c == 0 || c == cols - 1;
    }

    /**
     * Fills the smallest lakes with '*' up to the specified count.
     * @param lakes The list of found lakes.
     * @param lakesToKeep The number of lakes to remain unfilled.
     * @return The total number of cells filled.
     */
    public int fillSmallestLakes(List<Lake> lakes, int lakesToKeep) {
        // Sort lakes by size ascending
        lakes.sort(Comparator.comparingInt(Lake::getSize));

        int totalFilledCells = 0;
        int lakesToFill = lakes.size() - lakesToKeep;

        for (int i = 0; i < lakesToFill; i++) {
            Lake lake = lakes.get(i);
            totalFilledCells += lake.getSize();
            for (Point p : lake.getPoints()) {
                grid[p.getRow()][p.getCol()] = '*';
            }
        }

        return totalFilledCells;
    }

    public void printGrid() {
        for (int r = 0; r < rows; r++) {
            System.out.println(new String(grid[r]));
        }
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        if (!sc.hasNextInt()) return;
        int rows = sc.nextInt();
        int cols = sc.nextInt();
        int lakesToKeep = sc.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = sc.next().toCharArray();
        }

        LakeManager manager = new LakeManager(rows, cols, grid);
        List<Lake> lakes = manager.findLakes();

        int filledCellsCount = manager.fillSmallestLakes(lakes, lakesToKeep);

        System.out.println(filledCellsCount);
        manager.printGrid();

        sc.close();
    }
}

import java.io.*;
import java.util.*;

/**
 * Problem: Reduce the number of disconnected water components (lakes) in a grid 
 * to exactly k by converting the minimum number of '.' cells into '*' cells.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        LakeSolver solver = new LakeSolver(reader);
        solver.solve(out);

        out.close();
    }

    static class LakeSolver {
        private final FastReader reader;
        private int rows;
        private int cols;
        private char[][] grid;
        private int[][] componentIds;
        private final List<Lake> lakes = new ArrayList<>();

        private static final int[] DR = {1, -1, 0, 0};
        private static final int[] DC = {0, 0, 1, -1};

        public LakeSolver(FastReader reader) {
            this.reader = reader;
        }

        /**
         * Represents a connected component of water.
         */
        private static class Lake {
            int id;
            int size;

            Lake(int id, int size) {
                this.id = id;
                this.size = size;
            }
        }

        public void solve(PrintWriter out) {
            rows = reader.nextInt();
            cols = reader.nextInt();
            int targetLakeCount = reader.nextInt();
            reader.nextLine(); // Consume the newline after nextInt()

            // We pad the grid with '.' to treat the border as a single "ocean" component.
            // This ensures any '.' connected to the edge is not counted as an isolated lake.
            grid = new char[rows + 2][cols + 2];
            for (int i = 0; i < rows + 2; i++) {
                Arrays.fill(grid[i], '.');
            }

            for (int i = 1; i <= rows; i++) {
                String line = reader.nextLine();
                for (int j = 1; j <= cols; j++) {
                    grid[i][j] = line.charAt(j - 1);
                }
            }

            componentIds = new int[rows + 2][cols + 2];
            int nextComponentId = 1;

            // 1. Identify the "ocean" component by starting BFS from the padding (0,0)
            bfs(0, 0, nextComponentId++);

            // 2. Identify all internal lakes
            for (int i = 1; i <= rows; i++) {
                for (int j = 1; j <= cols; j++) {
                    if (grid[i][j] == '.' && componentIds[i][j] == 0) {
                        bfs(i, j, nextComponentId++);
                    }
                }
            }

            // The number of lakes is the number of components found, excluding the ocean (ID 1).
            int currentLakeCount = nextComponentId - 2;

            if (currentLakeCount == targetLakeCount) {
                out.println(0);
                printGrid(out);
                return;
            }

            // 3. Sort lakes by size to minimize cells changed
            Collections.sort(lakes, Comparator.comparingInt(l -> l.size));

            int lakesToRemoveCount = currentLakeCount - targetLakeCount;
            Set<Integer> lakesToRemoveIds = new HashSet<>();
            int totalCellsChanged = 0;

            for (int i = 0; i < lakesToRemoveCount; i++) {
                Lake lake = lakes.get(i);
                totalCellsChanged += lake.size;
                lakesToRemoveIds.add(lake.id);
            }

            // 4. Convert chosen lakes to '*'
            for (int i = 1; i <= rows; i++) {
                for (int j = 1; j <= cols; j++) {
                    if (grid[i][j] == '.' && lakesToRemoveIds.contains(componentIds[i][j])) {
                        grid[i][j] = '*';
                    }
                }
            }

            out.println(totalCellsChanged);
            printGrid(out);
        }

        private void bfs(int startR, int startC, int id) {
            Deque<int[]> queue = new ArrayDeque<>();
            queue.offer(new int[]{startR, startC});
            componentIds[startR][startC] = id;
            int size = 0;

            while (!queue.isEmpty()) {
                int[] curr = queue.poll();
                int r = curr[0];
                int c = curr[1];
                size++;

                for (int i = 0; i < 4; i++) {
                    int nr = r + DR[i];
                    int nc = c + DC[i];

                    if (isValid(nr, nc) && grid[nr][nc] == '.' && componentIds[nr][nc] == 0) {
                        componentIds[nr][nc] = id;
                        queue.offer(new int[]{nr, nc});
                    }
                }
            }
            // Only add to lakes list if it's not the ocean (ocean is ID 1)
            if (id > 1) {
                lakes.add(new Lake(id, size));
            }
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows + 2 && c >= 0 && c < cols + 2;
        }

        private void printGrid(PrintWriter out) {
            for (int i = 1; i <= rows; i++) {
                for (int j = 1; j <= cols; j++) {
                    out.print(grid[i][j]);
                }
                out.println();
            }
        }
    }

    /**
     * Efficient input reader for large datasets.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public String nextLine() {
            String str = "";
            try {
                str = reader.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }
}

import java.util.*;

/**
 * GridIslandManager processes a 2D grid of characters to identify "islands" of '.' cells.
 * It distinguishes between islands connected to the grid boundaries and internal islands.
 * It then removes the (N - K) smallest internal islands by converting them to '*'.
 */
public class GridIslandManager {

    // Direction vectors for 4-way movement (Up, Down, Left, Right)
    private static final int[] DX = {0, 0, 1, -1};
    private static final int[] DY = {1, -1, 0, 0};

    /**
     * Represents a coordinate in the 2D grid.
     */
    static class Point {
        final int row, col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Represents a connected component of '.' cells.
     */
    static class Island implements Comparable<Island> {
        final int size;
        final List<Point> points;

        Island(List<Point> points) {
            this.size = points.size();
            this.points = points;
        }

        @Override
        public int compareTo(Island other) {
            // Sort by size in ascending order
            return Integer.compare(this.size, other.size);
        }
    }

    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            if (!sc.hasNextInt()) return;

            int rows = sc.nextInt();
            int cols = sc.nextInt();
            int k = sc.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = sc.next().toCharArray();
            }

            boolean[][] visited = new boolean[rows][cols];
            List<Island> internalIslands = new ArrayList<>();

            // 1. Identify and mark all islands connected to the boundaries.
            // These are not considered "internal" islands.
            markBoundaryIslands(rows, cols, grid, visited);

            // 2. Find all internal islands (islands not connected to the boundary).
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.' && !visited[i][j]) {
                        List<Point> componentPoints = bfs(i, j, rows, cols, grid, visited);
                        internalIslands.add(new Island(componentPoints));
                    }
                }
            }

            // 3. Sort islands by size (ascending order).
            Collections.sort(internalIslands);

            // 4. The goal is to keep the K largest islands.
            // Therefore, we remove the (Size - K) smallest islands.
            int totalRemovedSize = 0;
            int numToRemove = internalIslands.size() - k;

            if (numToRemove > 0) {
                for (int i = 0; i < numToRemove; i++) {
                    Island islandToRemove = internalIslands.get(i);
                    totalRemovedSize += islandToRemove.size;
                    for (Point p : islandToRemove.points) {
                        grid[p.row][p.col] = '*';
                    }
                }
            }

            // 5. Output the sum of the sizes of removed islands and the modified grid.
            System.out.println(totalRemovedSize);
            for (int i = 0; i < rows; i++) {
                System.out.println(new String(grid[i]));
            }
        }
    }

    /**
     * Scans the edges of the grid and triggers BFS for any '.' cell found on the boundary.
     */
    private static void markBoundaryIslands(int rows, int cols, char[][] grid, boolean[][] visited) {
        for (int i = 0; i < rows; i++) {
            if (grid[i][0] == '.' && !visited[i][0]) {
                bfs(i, 0, rows, cols, grid, visited);
            }
            if (grid[i][cols - 1] == '.' && !visited[i][cols - 1]) {
                bfs(i, cols - 1, rows, cols, grid, visited);
            }
        }
        for (int j = 0; j < cols; j++) {
            if (grid[0][j] == '.' && !visited[0][j]) {
                bfs(0, j, rows, cols, grid, visited);
            }
            if (grid[rows - 1][j] == '.' && !visited[rows - 1][j]) {
                bfs(rows - 1, j, rows, cols, grid, visited);
            }
        }
    }

    /**
     * Uses BFS to find all connected '.' cells from a starting point.
     * 
     * @return A list of points belonging to the identified component.
     */
    private static List<Point> bfs(int startR, int startC, int rows, int cols, char[][] grid, boolean[][] visited) {
        List<Point> component = new ArrayList<>();
        Queue<Point> queue = new LinkedList<>();

        Point start = new Point(startR, startC);
        queue.add(start);
        visited[startR][startC] = true;

        while (!queue.isEmpty()) {
            Point current = queue.poll();
            component.add(current);

            for (int i = 0; i < 4; i++) {
                int nextR = current.row + DX[i];
                int nextC = current.col + DY[i];

                if (isValid(nextR, nextC, rows, cols) && 
                    grid[nextR][nextC] == '.' && 
                    !visited[nextR][nextC]) {

                    visited[nextR][nextC] = true;
                    queue.add(new Point(nextR, nextC));
                }
            }
        }
        return component;
    }

    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

import java.io.*;
import java.util.*;

/**
 * SolveDD refactored to handle large grids using BFS instead of DFS 
 * to avoid StackOverflowErrors, and to improve maintainability through 
 * better encapsulation and naming.
 */
public class SolveDD {

    /**
     * Represents a connected component of '.' cells.
     */
    static class Component implements Comparable<Component> {
        final int size;
        final int startX;
        final int startY;

        Component(int size, int startX, int startY) {
            this.size = size;
            this.startX = startX;
            this.startY = startY;
        }

        @Override
        public int compareTo(Component other) {
            return Integer.compare(this.size, other.size);
        }
    }

    private static final int[][] DIRECTIONS = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

    public static void main(String[] args) throws IOException {
        FastReader sc = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        int n = sc.nextInt();
        int m = sc.nextInt();
        int k = sc.nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = sc.next().toCharArray();
        }

        processGrid(n, m, k, grid, out);

        out.flush();
        out.close();
    }

    /**
     * Core logic to solve the grid problem.
     */
    private static void processGrid(int n, int m, int k, char[][] grid, PrintWriter out) {
        // resultGrid will store the final modified grid to be printed
        char[][] resultGrid = new char[n][m];
        for (int i = 0; i < n; i++) {
            resultGrid[i] = grid[i].clone();
        }

        // floodGrid is used to isolate enclosed components by marking boundary-connected cells as '*'
        char[][] floodGrid = new char[n][m];
        for (int i = 0; i < n; i++) {
            floodGrid[i] = grid[i].clone();
        }

        // 1. Mark all '.' cells reachable from the boundaries as '*' in floodGrid
        for (int i = 0; i < n; i++) {
            if (floodGrid[i][0] == '.') floodFill(floodGrid, i, 0, n, m);
            if (floodGrid[i][m - 1] == '.') floodFill(floodGrid, i, m - 1, n, m);
        }
        for (int j = 0; j < m; j++) {
            if (floodGrid[0][j] == '.') floodFill(floodGrid, 0, j, n, m);
            if (floodGrid[n - 1][j] == '.') floodFill(floodGrid, n - 1, j, n, m);
        }

        // 2. Find all enclosed '.' components remaining in floodGrid
        List<Component> components = new ArrayList<>();
        boolean[][] visited = new boolean[n][m];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (floodGrid[i][j] == '.' && !visited[i][j]) {
                    components.add(findComponent(floodGrid, i, j, n, m, visited));
                }
            }
        }

        // 3. Sort components by size (ascending)
        Collections.sort(components);

        // 4. Fill the smallest components until at most 'k' components remain
        int numToFill = Math.max(0, components.size() - k);
        int totalChanged = 0;

        for (int i = 0; i < numToFill; i++) {
            Component comp = components.get(i);
            totalChanged += comp.size;
            floodFill(resultGrid, comp.startX, comp.startY, n, m);
        }

        // 5. Output results
        out.println(totalChanged);
        for (int i = 0; i < n; i++) {
            out.println(new String(resultGrid[i]));
        }
    }

    /**
     * Iterative BFS to fill a connected component of '.' with '*'
     */
    private static void floodFill(char[][] grid, int startX, int startY, int n, int m) {
        Queue<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[]{startX, startY});
        grid[startX][startY] = '*';

        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            for (int[] dir : DIRECTIONS) {
                int nx = curr[0] + dir[0];
                int ny = curr[1] + dir[1];

                if (isValid(nx, ny, n, m) && grid[nx][ny] == '.') {
                    grid[nx][ny] = '*';
                    queue.offer(new int[]{nx, ny});
                }
            }
        }
    }

    /**
     * Iterative BFS to identify a component and return its size and starting point.
     */
    private static Component findComponent(char[][] grid, int startX, int startY, int n, int m, boolean[][] visited) {
        int size = 0;
        Queue<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[]{startX, startY});
        visited[startX][startY] = true;

        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            size++;

            for (int[] dir : DIRECTIONS) {
                int nx = curr[0] + dir[0];
                int ny = curr[1] + dir[1];

                if (isValid(nx, ny, n, m) && grid[nx][ny] == '.' && !visited[nx][ny]) {
                    visited[nx][ny] = true;
                    queue.offer(new int[]{nx, ny});
                }
            }
        }
        return new Component(size, startX, startY);
    }

    private static boolean isValid(int x, int y, int n, int m) {
        return x >= 0 && x < n && y >= 0 && y < m;
    }

    /**
     * Faster input reader for competitive programming tasks.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;

/**
 * WaterAreaManager handles the identification and management of water regions
 * within a grid-based map. It identifies enclosed water regions and provides
 * functionality to "fill" them based on their size.
 */
public class WaterAreaManager {

    private static final int[][] DIRECTIONS = {{1, 0}, {0, 1}, {-1, 0}, {0, -1}};

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        int k = scanner.nextInt();

        char[][] originalMap = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            originalMap[i] = line.toCharArray();
        }
        scanner.close();

        processWaterRegions(rows, cols, k, originalMap);
    }

    /**
     * Orchestrates the process of finding enclosed water regions, 
     * removing the smallest ones to satisfy the k-region constraint, 
     * and printing the result.
     */
    private static void processWaterRegions(int rows, int cols, int k, char[][] originalMap) {
        // workingMap is used to identify which water regions are enclosed
        char[][] workingMap = deepCopy(originalMap);

        // 1. Mark all water connected to the boundaries as '*' (not an enclosed region)
        for (int j = 0; j < cols; j++) {
            floodFill(workingMap, 0, j);
            floodFill(workingMap, rows - 1, j);
        }
        for (int i = 0; i < rows; i++) {
            floodFill(workingMap, i, 0);
            floodFill(workingMap, i, cols - 1);
        }

        // 2. Identify all remaining enclosed water regions using BFS
        PriorityQueue<WaterRegion> enclosedRegions = new PriorityQueue<>();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (workingMap[i][j] == '.') {
                    int size = floodFill(workingMap, i, j);
                    enclosedRegions.add(new WaterRegion(i, j, size));
                }
            }
        }

        // 3. Create the result map and fill the smallest regions until only k regions remain
        char[][] resultMap = deepCopy(originalMap);
        int totalCellsFilled = 0;

        while (enclosedRegions.size() > k) {
            WaterRegion smallestRegion = enclosedRegions.poll();
            totalCellsFilled += floodFill(resultMap, smallestRegion.x, smallestRegion.y);
        }

        // 4. Output the total area filled and the resulting map
        System.out.println(totalCellsFilled);
        printMap(resultMap);
    }

    /**
     * Performs a Breadth-First Search to find and mark a connected component of '.' cells.
     * Returns the total count of cells in the component.
     */
    private static int floodFill(char[][] map, int startX, int startY) {
        if (!isWithinBounds(map, startX, startY) || map[startX][startY] != '.') {
            return 0;
        }

        int count = 0;
        Queue<int[]> queue = new ArrayDeque<>();

        // Start BFS
        queue.offer(new int[]{startX, startY});
        map[startX][startY] = '*';
        count++;

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int r = current[0];
            int c = current[1];

            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                if (isWithinBounds(map, nr, nc) && map[nr][nc] == '.') {
                    map[nr][nc] = '*'; // Mark as visited/filled
                    count++;
                    queue.offer(new int[]{nr, nc});
                }
            }
        }
        return count;
    }

    private static boolean isWithinBounds(char[][] map, int r, int c) {
        return r >= 0 && r < map.length && c >= 0 && c < map[0].length;
    }

    private static char[][] deepCopy(char[][] map) {
        int rows = map.length;
        int cols = map[0].length;
        char[][] copy = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            System.arraycopy(map[i], 0, copy[i], 0, cols);
        }
        return copy;
    }

    private static void printMap(char[][] map) {
        StringBuilder sb = new StringBuilder();
        for (char[] row : map) {
            sb.append(row).append('\n');
        }
        System.out.print(sb.toString());
    }

    /**
     * Represents a connected component of water.
     */
    private static class WaterRegion implements Comparable<WaterRegion> {
        final int x;
        final int y;
        final int size;

        WaterRegion(int x, int y, int size) {
            this.x = x;
            this.y = y;
            this.size = size;
        }

        @Override
        public int compareTo(WaterRegion other) {
            // Ascending order: smallest regions first
            return Integer.compare(this.size, other.size);
        }
    }
}

import java.util.*;

/**
 * Problem723D refactored for maintainability and quality.
 * This program identifies "lakes" (water bodies not connected to the edge)
 * and fills the smallest lakes until a target number of lakes remains.
 */
public final class Problem723D {

    private static final char WATER = '.';
    private static final char LAND = '*';

    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);

        if (!input.hasNextInt()) {
            input.close();
            return;
        }

        int rows = input.nextInt();
        int cols = input.nextInt();
        int targetLakes = input.nextInt();
        input.nextLine(); // Consume newline

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = input.nextLine().toCharArray();
        }
        input.close();

        LakeSolver solver = new LakeSolver(rows, cols, grid);
        solver.solve(targetLakes);
    }

    /**
     * Logic engine to process the grid and manage lake elimination.
     */
    static class LakeSolver {
        private final int rows;
        private final int cols;
        private final char[][] grid;

        public LakeSolver(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
        }

        public void solve(int targetLakes) {
            DisjointSetUnion dsu = buildConnectivity();
            List<Lake> lakes = identifyLakes(dsu);

            // Sort lakes by size ascending to fill the smallest ones first
            lakes.sort(Comparator.comparingInt(Lake::size));

            int numLakesToFill = Math.max(0, lakes.size() - targetLakes);
            int totalAreaFilled = 0;
            Set<Integer> rootsToFill = new HashSet<>();

            for (int i = 0; i < numLakesToFill; i++) {
                Lake lake = lakes.get(i);
                totalAreaFilled += lake.size();
                rootsToFill.add(lake.root());
            }

            // Modify the grid: turn lakes that need to be eliminated into LAND
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == WATER) {
                        int id = r * cols + c;
                        if (rootsToFill.contains(dsu.find(id))) {
                            grid[r][c] = LAND;
                        }
                    }
                }
            }

            System.out.println(totalAreaFilled);
            printGrid();
        }

        private DisjointSetUnion buildConnectivity() {
            boolean[] initialOceanStatus = new boolean[rows * cols];

            // Pre-identify water cells on the boundary as part of the "ocean"
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == WATER) {
                        if (r == 0 || r == rows - 1 || c == 0 || c == cols - 1) {
                            initialOceanStatus[r * cols + c] = true;
                        }
                    }
                }
            }

            DisjointSetUnion dsu = new DisjointSetUnion(rows * cols, initialOceanStatus);

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == WATER) {
                        // Check only right and down to avoid redundant unions
                        if (r + 1 < rows && grid[r + 1][c] == WATER) {
                            dsu.union(r * cols + c, (r + 1) * cols + c);
                        }
                        if (c + 1 < cols && grid[r][c + 1] == WATER) {
                            dsu.union(r * cols + c, r * cols + (c + 1));
                        }
                    }
                }
            }
            return dsu;
        }

        private List<Lake> identifyLakes(DisjointSetUnion dsu) {
            Set<Integer> lakeRoots = new HashSet<>();
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == WATER) {
                        int root = dsu.find(r * cols + c);
                        if (!dsu.isOcean(root)) {
                            lakeRoots.add(root);
                        }
                    }
                }
            }

            List<Lake> lakes = new ArrayList<>();
            for (int root : lakeRoots) {
                lakes.add(new Lake(root, dsu.getSize(root)));
            }
            return lakes;
        }

        private void printGrid() {
            StringBuilder sb = new StringBuilder();
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    sb.append(grid[r][c]);
                }
                sb.append("\n");
            }
            System.out.print(sb.toString());
        }
    }

    /**
     * Represents a connected body of water.
     */
    private record Lake(int root, int size) {}

    /**
     * Standard Disjoint Set Union (DSU) with Path Compression, 
     * Union by Size, and Ocean tracking.
     */
    static class DisjointSetUnion {
        private final int[] parent;
        private final int[] size;
        private final boolean[] isOcean;

        public DisjointSetUnion(int n, boolean[] initialOcean) {
            this.parent = new int[n];
            this.size = new int[n];
            this.isOcean = new boolean[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
                isOcean[i] = initialOcean[i];
            }
        }

        public int find(int i) {
            if (parent[i] == i) {
                return i;
            }
            return parent[i] = find(parent[i]); // Path compression
        }

        public void union(int i, int j) {
            int rootI = find(i);
            int rootJ = find(j);

            if (rootI != rootJ) {
                // Union by size: attach smaller tree to larger tree
                if (size[rootI] < size[rootJ]) {
                    int temp = rootI;
                    rootI = rootJ;
                    rootJ = temp;
                }
                parent[rootJ] = rootI;
                size[rootI] += size[rootJ];
                // If either component is ocean, the merged component is ocean
                isOcean[rootI] = isOcean[rootI] || isOcean[rootJ];
            }
        }

        public boolean isOcean(int root) {
            return isOcean[root];
        }

        public int getSize(int root) {
            return size[root];
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * IslandManager identifies connected components (islands) in a grid.
 * It removes the smallest islands until only K islands remain.
 */
public class IslandManager {

    public static void main(String[] args) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             BufferedWriter writer = new BufferedWriter(new OutputStreamWriter(System.out))) {

            String firstLine = reader.readLine();
            if (firstLine == null) return;

            String[] params = firstLine.trim().split("\\s+");
            int rows = Integer.parseInt(params[0]);
            int cols = Integer.parseInt(params[1]);
            int k = Integer.parseInt(params[2]);

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.readLine().trim().toCharArray();
            }

            GridProcessor processor = new GridProcessor(grid, rows, cols);
            ProcessingResult result = processor.process(k);

            // Output the number of removed cells
            writer.write(String.valueOf(result.removedCellsCount));
            writer.newLine();

            // Output the resulting grid
            for (int i = 0; i < rows; i++) {
                writer.write(new String(result.finalGrid[i]));
                writer.newLine();
            }

            writer.flush();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /**
     * Represents a single coordinate in the grid.
     */
    static final class Cell {
        final int r, c;

        Cell(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Represents a connected component of non-'*' characters.
     */
    static final class Island implements Comparable<Island> {
        final List<Cell> cells;
        final int size;

        Island(List<Cell> cells) {
            this.cells = cells;
            this.size = cells.size();
        }

        @Override
        public int compareTo(Island other) {
            return Integer.compare(this.size, other.size);
        }
    }

    /**
     * Holds the outcome of the grid processing.
     */
    static final class ProcessingResult {
        final char[][] finalGrid;
        final int removedCellsCount;

        ProcessingResult(char[][] finalGrid, int removedCellsCount) {
            this.finalGrid = finalGrid;
            this.removedCellsCount = removedCellsCount;
        }
    }

    /**
     * Handles the logic of identifying and modifying islands in the grid.
     */
    static class GridProcessor {
        private final char[][] grid;
        private final int rows;
        private final int cols;

        private static final int[] DR = {-1, 1, 0, 0};
        private static final int[] DC = {0, 0, -1, 1};

        GridProcessor(char[][] grid, int rows, int cols) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
        }

        public ProcessingResult process(int maxIslandsAllowed) {
            // Create a deep copy to preserve the original input for modification
            char[][] workingGrid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                workingGrid[i] = grid[i].clone();
            }

            boolean[][] visited = new boolean[rows][cols];

            // 1. Mark all cells connected to the boundary as 'visited' (the "sea")
            // These are not considered "enclosed islands"
            for (int i = 0; i < rows; i++) {
                bfsMarkVisited(i, 0, visited, workingGrid);
                bfsMarkVisited(i, cols - 1, visited, workingGrid);
            }
            for (int j = 0; j < cols; j++) {
                bfsMarkVisited(0, j, visited, workingGrid);
                bfsMarkVisited(rows - 1, j, visited, workingGrid);
            }

            // 2. Find all enclosed islands in the interior
            List<Island> islands = new ArrayList<>();
            for (int i = 1; i < rows - 1; i++) {
                for (int j = 1; j < cols - 1; j++) {
                    if (workingGrid[i][j] != '*' && !visited[i][j]) {
                        List<Cell> islandCells = bfsFindIsland(i, j, visited, workingGrid);
                        islands.add(new Island(islandCells));
                    }
                }
            }

            // 3. Sort islands by size (ascending) and remove smallest if count > k
            Collections.sort(islands);
            int removedCellsCount = 0;
            int islandsToRemove = islands.size() - maxIslandsAllowed;

            for (int i = 0; i < islandsToRemove; i++) {
                Island smallestIsland = islands.get(i);
                removedCellsCount += smallestIsland.size;
                for (Cell cell : smallestIsland.cells) {
                    workingGrid[cell.r][cell.c] = '*';
                }
            }

            return new ProcessingResult(workingGrid, removedCellsCount);
        }

        /**
         * Standard BFS to mark boundary-connected components as visited.
         */
        private void bfsMarkVisited(int startR, int startC, boolean[][] visited, char[][] grid) {
            if (grid[startR][startC] == '*' || visited[startR][startC]) return;

            Deque<Cell> queue = new ArrayDeque<>();
            queue.add(new Cell(startR, startC));
            visited[startR][startC] = true;

            while (!queue.isEmpty()) {
                Cell curr = queue.poll();
                for (int i = 0; i < 4; i++) {
                    int nr = curr.r + DR[i];
                    int nc = curr.c + DC[i];

                    if (isValid(nr, nc) && grid[nr][nc] != '*' && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        queue.add(new Cell(nr, nc));
                    }
                }
            }
        }

        /**
         * Standard BFS to collect all cells belonging to an island.
         */
        private List<Cell> bfsFindIsland(int startR, int startC, boolean[][] visited, char[][] grid) {
            List<Cell> component = new ArrayList<>();
            Deque<Cell> queue = new ArrayDeque<>();

            queue.add(new Cell(startR, startC));
            visited[startR][startC] = true;

            while (!queue.isEmpty()) {
                Cell curr = queue.poll();
                component.add(curr);

                for (int i = 0; i < 4; i++) {
                    int nr = curr.r + DR[i];
                    int nc = curr.c + DC[i];

                    if (isValid(nr, nc) && grid[nr][nc] != '*' && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        queue.add(new Cell(nr, nc));
                    }
                }
            }
            return component;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for identifying and removing the smallest internal 
 * connected components in a grid.
 */
public class D723 {

    public static void main(String[] args) throws IOException {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int rows = reader.nextInt();
        int cols = reader.nextInt();
        int numToRemove = reader.nextInt();

        char[][] grid = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            String line = reader.nextLine();
            for (int c = 0; c < cols; c++) {
                grid[r][c] = line.charAt(c);
            }
        }

        GridSolver solver = new GridSolver(rows, cols, numToRemove, grid);
        solver.solve(out);
        out.close();
    }

    /**
     * Encapsulates the grid processing logic.
     */
    private static class GridSolver {
        private final int rows;
        private final int cols;
        private final int numToRemove;
        private final char[][] grid;
        private final boolean[][] visited;

        private static final int[] DR = {-1, 1, 0, 0};
        private static final int[] DC = {0, 0, -1, 1};

        public GridSolver(int rows, int cols, int numToRemove, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.numToRemove = numToRemove;
            this.grid = grid;
            this.visited = new boolean[rows][cols];
        }

        /**
         * Executes the component detection and removal process.
         */
        public void solve(PrintWriter out) {
            // Step 1: Identify all open spaces connected to the boundaries.
            // These are considered "outside" and not internal components.
            markBoundaryComponents();

            // Step 2: Find all internal components of '.'
            List<Component> internalComponents = findInternalComponents();

            // Step 3: Sort components by size (ascending) to remove the smallest ones.
            Collections.sort(internalComponents, Comparator.comparingInt(c -> c.size));

            int totalRemovedArea = 0;
            int actuallyRemoved = 0;

            // Step 4: Remove the smallest components up to 'numToRemove'
            for (Component comp : internalComponents) {
                if (actuallyRemoved >= numToRemove) break;

                totalRemovedArea += comp.size;
                for (int[] cell : comp.cells) {
                    grid[cell[0]][cell[1]] = '*';
                }
                actuallyRemoved++;
            }

            // Step 5: Output results
            out.println(totalRemovedArea);
            for (int r = 0; r < rows; r++) {
                out.println(new String(grid[r]));
            }
        }

        private void markBoundaryComponents() {
            for (int r = 0; r < rows; r++) {
                if (grid[r][0] == '.' && !visited[r][0]) bfs(r, 0, true);
                if (grid[r][cols - 1] == '.' && !visited[r][cols - 1]) bfs(r, cols - 1, true);
            }
            for (int c = 0; c < cols; c++) {
                if (grid[0][c] == '.' && !visited[0][c]) bfs(0, c, true);
                if (grid[rows - 1][c] == '.' && !visited[rows - 1][c]) bfs(rows - 1, c, true);
            }
        }

        private List<Component> findInternalComponents() {
            List<Component> components = new ArrayList<>();
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.' && !visited[r][c]) {
                        components.add(bfs(r, c, false));
                    }
                }
            }
            return components;
        }

        /**
         * Iterative BFS to avoid StackOverflowError.
         * @param isBoundaryMode If true, simply marks cells as visited.
         *                        If false, returns a Component object.
         */
        private Component bfs(int startR, int startC, boolean isBoundaryMode) {
            List<int[]> cells = new ArrayList<>();
            Deque<int[]> queue = new ArrayDeque<>();

            queue.add(new int[]{startR, startC});
            visited[startR][startC] = true;

            while (!queue.isEmpty()) {
                int[] curr = queue.poll();
                int r = curr[0];
                int c = curr[1];

                if (!isBoundaryMode) {
                    cells.add(new int[]{r, c});
                }

                for (int i = 0; i < 4; i++) {
                    int nr = r + DR[i];
                    int nc = c + DC[i];

                    if (isValid(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        queue.add(new int[]{nr, nc});
                    }
                }
            }

            return isBoundaryMode ? null : new Component(cells.size(), cells);
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * Represents a connected group of grid cells.
     */
    private static class Component {
        final int size;
        final List<int[]> cells;

        Component(int size, List<int[]> cells) {
            this.size = size;
            this.cells = cells;
        }
    }

    /**
     * Faster input reading utility.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public String nextLine() {
            try {
                return reader.readLine();
            } catch (IOException e) {
                return null;
            }
        }
    }
}

import java.util.*;

/**
 * Represents a coordinate in the grid.
 * Using a record automatically provides correct equals() and hashCode() implementations.
 */
record Point(int row, int col) {}

class LakeManager {
    private final int rows;
    private final int cols;
    private final char[][] grid;
    private static final char WATER = '.';
    private static final char FILLED = '*';

    public LakeManager(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
    }

    /**
     * Identifies all lakes in the grid. 
     * A lake is a connected component of '.' that does not touch the grid boundary.
     */
    public List<List<Point>> findLakes() {
        List<List<Point>> lakes = new ArrayList<>();
        boolean[][] visited = new boolean[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == WATER && !visited[r][c]) {
                    List<Point> component = bfsExploreComponent(r, c, visited);
                    if (isContainedLake(component)) {
                        lakes.add(component);
                    }
                }
            }
        }
        return lakes;
    }

    /**
     * Uses BFS to find all connected '.' cells starting from (startR, startC).
     */
    private List<Point> bfsExploreComponent(int startR, int startC, boolean[][] visited) {
        List<Point> component = new ArrayList<>();
        Queue<Point> queue = new LinkedList<>();

        Point start = new Point(startR, startC);
        queue.add(start);
        visited[startR][startC] = true;

        int[][] directions = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

        while (!queue.isEmpty()) {
            Point current = queue.poll();
            component.add(current);

            for (int[] dir : directions) {
                int nr = current.row() + dir[0];
                int nc = current.col() + dir[1];

                if (isInBounds(nr, nc) && grid[nr][nc] == WATER && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    queue.add(new Point(nr, nc));
                }
            }
        }
        return component;
    }

    /**
     * A component is a "lake" only if no part of it touches the boundary.
     */
    private boolean isContainedLake(List<Point> component) {
        for (Point p : component) {
            if (p.row() == 0 || p.row() == rows - 1 || p.col() == 0 || p.col() == cols - 1) {
                return false;
            }
        }
        return true;
    }

    private boolean isInBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Fills the smallest lakes with '*' until the target count is reached.
     * @return The number of cells changed.
     */
    public int reduceLakesToTarget(List<List<Point>> lakes, int targetCount) {
        if (lakes.size() <= targetCount) {
            return 0;
        }

        // Sort lakes by size ascending so we can remove the smallest ones first
        lakes.sort(Comparator.comparingInt(List::size));

        int cellsChanged = 0;
        int lakesToRemove = lakes.size() - targetCount;

        for (int i = 0; i < lakesToRemove; i++) {
            for (Point p : lakes.get(i)) {
                grid[p.row()][p.col()] = FILLED;
                cellsChanged++;
            }
        }

        return cellsChanged;
    }

    public void printGrid() {
        StringBuilder sb = new StringBuilder();
        for (char[] row : grid) {
            sb.append(row).append('\n');
        }
        System.out.print(sb.toString());
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        if (!sc.hasNextInt()) return;
        int rows = sc.nextInt();
        int cols = sc.nextInt();
        int needLakes = sc.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = sc.next();
            grid[i] = line.toCharArray();
        }

        LakeManager manager = new LakeManager(rows, cols, grid);

        List<List<Point>> lakes = manager.findLakes();
        int changes = manager.reduceLakesToTarget(lakes, needLakes);

        System.out.println(changes);
        manager.printGrid();

        sc.close();
    }
}

import java.io.*;
import java.util.*;

/**
 * A refactored solution to the grid component problem.
 * The goal is to identify connected components of empty spaces ('.').
 * Components touching the grid boundary are preserved.
 * Among internal components, only the 'k' largest are preserved.
 * All other internal components are converted into obstacles ('*').
 */
public class GridComponentManager {

    // Represents a connected component of empty cells
    private static class Component {
        private final List<Point> cells = new ArrayList<>();
        private boolean touchesBoundary = false;

        public void addCell(int r, int c) {
            cells.add(new Point(r, c));
        }

        public void setTouchesBoundary(boolean touchesBoundary) {
            this.touchesBoundary = touchesBoundary;
        }

        public boolean isBoundaryComponent() {
            return touchesBoundary;
        }

        public int getSize() {
            return cells.size();
        }

        public List<Point> getCells() {
            return cells;
        }
    }

    private static class Point {
        final int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            int k = reader.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                grid[i] = line.toCharArray();
            }

            solve(rows, cols, k, grid, out);

        } catch (Exception e) {
            // Handle potential input errors gracefully
        } finally {
            out.flush();
            out.close();
        }
    }

    private static void solve(int rows, int cols, int k, char[][] grid, PrintWriter out) {
        boolean[][] visited = new boolean[rows][cols];
        List<Component> internalComponents = new ArrayList<>();
        int totalAreaRemoved = 0;

        // 1. Identify all components using BFS
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.' && !visited[i][j]) {
                    Component component = findComponent(grid, visited, i, j, rows, cols);
                    if (!component.isBoundaryComponent()) {
                        internalComponents.add(component);
                    }
                }
            }
        }

        // 2. Sort internal components by size (descending) to keep the largest ones
        internalComponents.sort((a, b) -> Integer.compare(b.getSize(), a.getSize()));

        // 3. If we have more than k internal components, turn the smallest ones into '*'
        // The original logic: if pq.size() > k, remove the smallest.
        // This means we keep the first k elements in the sorted list.
        if (internalComponents.size() > k) {
            for (int i = k; i < internalComponents.size(); i++) {
                Component toRemove = internalComponents.get(i);
                totalAreaRemoved += toRemove.getSize();
                for (Point p : toRemove.getCells()) {
                    grid[p.r][p.c] = '*';
                }
            }
        }

        // 4. Output the results
        out.println(totalAreaRemoved);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < rows; i++) {
            sb.setLength(0);
            for (int j = 0; j < cols; j++) {
                sb.append(grid[i][j]);
            }
            out.println(sb.toString());
        }
    }

    /**
     * Finds a connected component of '.' using Breadth-First Search.
     */
    private static Component findComponent(char[][] grid, boolean[][] visited, int startR, int startC, int rows, int cols) {
        Component component = new Component();
        Deque<Point> queue = new ArrayDeque<>();

        Point start = new Point(startR, startC);
        queue.add(start);
        visited[startR][startC] = true;

        int[] dr = {1, -1, 0, 0};
        int[] dc = {0, 0, 1, -1};

        while (!queue.isEmpty()) {
            Point curr = queue.poll();
            component.addCell(curr.r, curr.c);

            // Check if this specific cell is on the boundary
            if (curr.r == 0 || curr.r == rows - 1 || curr.c == 0 || curr.c == cols - 1) {
                component.setTouchesBoundary(true);
            }

            for (int i = 0; i < 4; i++) {
                int nr = curr.r + dr[i];
                int nc = curr.c + dc[i];

                if (isValid(nr, nc, rows, cols) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    queue.add(new Point(nr, nc));
                }
            }
        }
        return component;
    }

    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Fast I/O utility class.
     */
    private static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

