/**
 * GridOptimizer identifies water components in a grid and converts 
 * specific components into land to maximize land area based on a limit.
 */
public class GridLandOptimizer {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            int k = reader.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            GridOptimizer optimizer = new GridOptimizer(rows, cols, grid);
            optimizer.solve(k, writer);

        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Represents a connected component of water cells.
     */
    static class WaterComponent implements Comparable<WaterComponent> {
        final int id;
        final List<Point> cells;
        final boolean touchesBoundary;

        WaterComponent(int id, List<Point> cells, boolean touchesBoundary) {
            this.id = id;
            this.cells = cells;
            this.touchesBoundary = touchesBoundary;
        }

        public int getSize() {
            return cells.size();
        }

        @Override
        public int compareTo(WaterComponent other) {
            // Sort by size ascending to match original logic's selection behavior
            return Integer.compare(this.getSize(), other.getSize());
        }
    }

    static class Point {
        final int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    static class GridOptimizer {
        private final int rows;
        private final int cols;
        private final char[][] grid;

        private static final int[] DR = {0, 0, 1, -1};
        private static final int[] DC = {-1, 1, 0, 0};

        GridOptimizer(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
        }

        public void solve(int k, PrintWriter out) {
            List<WaterComponent> allComponents = findWaterComponents();

            // Filter components that do not touch the grid boundary
            List<WaterComponent> validComponents = new ArrayList<>();
            for (WaterComponent comp : allComponents) {
                if (!comp.touchesBoundary) {
                    validComponents.add(comp);
                }
            }

            // Sort valid components by size ascending
            Collections.sort(validComponents);

            // The original logic picks (total_valid_components - k) smallest components
            int numToFill = Math.max(0, validComponents.size() - k);
            int totalCellsAdded = 0;

            for (int i = 0; i < numToFill; i++) {
                WaterComponent comp = validComponents.get(i);
                totalCellsAdded += comp.getSize();
                for (Point p : comp.cells) {
                    grid[p.r][p.c] = '*';
                }
            }

            out.println(totalCellsAdded);
            for (int i = 0; i < rows; i++) {
                out.println(new String(grid[i]));
            }
        }

        private List<WaterComponent> findWaterComponents() {
            List<WaterComponent> components = new ArrayList<>();
            boolean[][] visited = new boolean[rows][cols];
            int componentIdCounter = 0;

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.' && !visited[r][c]) {
                        components.add(bfs(r, c, visited, componentIdCounter++));
                    }
                }
            }
            return components;
        }

        private WaterComponent bfs(int startR, int startC, boolean[][] visited, int id) {
            List<Point> componentCells = new ArrayList<>();
            Queue<Point> queue = new LinkedList<>();
            boolean touchesBoundary = false;

            visited[startR][startC] = true;
            Point start = new Point(startR, startC);
            queue.add(start);

            while (!queue.isEmpty()) {
                Point curr = queue.poll();
                componentCells.add(curr);

                // Check if this cell is on the boundary
                if (curr.r == 0 || curr.r == rows - 1 || curr.c == 0 || curr.c == cols - 1) {
                    touchesBoundary = true;
                }

                for (int i = 0; i < 4; i++) {
                    int nr = curr.r + DR[i];
                    int nc = curr.c + DC[i];

                    if (isValid(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        queue.add(new Point(nr, nc));
                    }
                }
            }

            return new WaterComponent(id, componentCells, touchesBoundary);
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * Fast I/O utility for efficient reading.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

