/**
 * A program that identifies connected components of '.' in a grid,
 * selects the K largest components, and fills them with '*' characters.
 */
public class GridComponentProcessor {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            int maxComponentsToFill = reader.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            GridAnalyzer analyzer = new GridAnalyzer(rows, cols, grid);
            analyzer.process(maxComponentsToFill, writer);

        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Represents a coordinate in the 2D grid.
     */
    private static class Point {
        final int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Represents a connected component of '.' cells.
     */
    private static class Component implements Comparable<Component> {
        final List<Point> points;
        final int size;

        Component(List<Point> points) {
            this.points = points;
            this.size = points.size();
        }

        @Override
        public int compareTo(Component other) {
            // Sort in descending order of size for the PriorityQueue/Sorting logic
            return Integer.compare(other.size, this.size);
        }
    }

    /**
     * Handles the logic of finding and manipulating grid components.
     */
    private static class GridAnalyzer {
        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final int[] dr = {-1, 1, 0, 0};
        private final int[] dc = {0, 0, -1, 1};

        GridAnalyzer(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
        }

        public void process(int k, PrintWriter writer) {
            List<Component> components = findAllComponents();

            // Sort components by size descending
            Collections.sort(components);

            int totalCellsFilled = 0;
            int componentsToFill = Math.min(k, components.size());

            for (int i = 0; i < componentsToFill; i++) {
                Component comp = components.get(i);
                totalCellsFilled += comp.size;
                for (Point p : comp.points) {
                    grid[p.r][p.c] = '*';
                }
            }

            writer.println(totalCellsFilled);
            printGrid(writer);
        }

        private List<Component> findAllComponents() {
            List<Component> components = new ArrayList<>();
            boolean[][] visited = new boolean[rows][cols];

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.' && !visited[r][c]) {
                        components.add(bfs(r, c, visited));
                    }
                }
            }
            return components;
        }

        /**
         * Uses iterative BFS to find all cells in a component.
         * Iterative approach avoids StackOverflowError on large grids.
         */
        private Component bfs(int startR, int startC, boolean[][] visited) {
            List<Point> componentPoints = new ArrayList<>();
            Queue<Point> queue = new LinkedList<>();

            Point start = new Point(startR, startC);
            queue.offer(start);
            visited[startR][startC] = true;

            while (!queue.isEmpty()) {
                Point curr = queue.poll();
                componentPoints.add(curr);

                for (int i = 0; i < 4; i++) {
                    int nr = curr.r + dr[i];
                    int nc = curr.c + dc[i];

                    if (isValid(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        queue.offer(new Point(nr, nc));
                    }
                }
            }
            return new Component(componentPoints);
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        private void printGrid(PrintWriter writer) {
            StringBuilder sb = new StringBuilder();
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    sb.append(grid[r][c]);
                }
                sb.append('\n');
            }
            writer.print(sb.toString());
        }
    }

    /**
     * Fast I/O utility class.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

public class Solution {

    private static final int[] DX = {0, 0, -1, 1};
    private static final int[] DY = {1, -1, 0, 0};

    private int rows;
    private int cols;
    private char[][] grid;
    private boolean[][] visited;

    public static void main(String[] args) throws IOException {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        // Read N, M, K
        String firstLine = reader.next();
        if (firstLine == null) return;
        int n = Integer.parseInt(firstLine);
        int m = reader.nextInt();
        int k = reader.nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = reader.next().toCharArray();
        }

        Solution solver = new Solution(n, m, grid);
        solver.run(k, out);
        out.flush();
        out.close();
    }

    public Solution(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
    }

    public void run(int k, PrintWriter out) {
        // 1. Identify boundary-connected components
        markBoundaryConnected();

        // 2. Find enclosed components
        List<Component> components = findEnclosedComponents();

        // 3. Sort components by size (Ascending)
        Collections.sort(components);

        // 4. Fill smallest components until k are left
        long totalCellsFilled = 0;
        int numToFill = components.size() - k;
        if (numToFill > 0) {
            for (int i = 0; i < numToFill; i++) {
                Component comp = components.get(i);
                totalCellsFilled += comp.size;
                fillWithAsterisk(comp.startRow, comp.startCol);
            }
        }

        // 5. Output
        out.println(totalCellsFilled);
        for (int i = 0; i < rows; i++) {
            out.println(new String(grid[i]));
        }
    }

    private void markBoundaryConnected() {
        visited = new boolean[rows][cols];
        Queue<int[]> queue = new ArrayDeque<>();

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.' && (i == 0 || i == rows - 1 || j == 0 || j == cols - 1)) {
                    if (!visited[i][j]) {
                        visited[i][j] = true;
                        queue.add(new int[]{i, j});
                    }
                }
            }
        }

        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            for (int i = 0; i < 4; i++) {
                int ni = curr[0] + DX[i];
                int nj = curr[1] + DY[i];
                if (ni >= 0 && ni < rows && nj >= 0 && nj < cols && grid[ni][nj] == '.' && !visited[ni][nj]) {
                    visited[ni][nj] = true;
                    queue.add(new int[]{ni, nj});
                }
            }
        }
    }

    private List<Component> findEnclosedComponents() {
        List<Component> components = new ArrayList<>();
        // We reuse the 'visited' array from the boundary step
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.' && !visited[i][j]) {
                    int size = bfsCollectSize(i, j);
                    components.add(new Component(i, j, size));
                }
            }
        }
        return components;
    }

    private int bfsCollectSize(int startR, int startC) {
        int size = 0;
        Queue<int[]> queue = new ArrayDeque<>();
        queue.add(new int[]{startR, startC});
        visited[startR][startC] = true;

        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            size++;
            for (int i = 0; i < 4; i++) {
                int ni = curr[0] + DX[i];
                int nj = curr[1] + DY[i];
                if (ni >= 0 && ni < rows && nj >= 0 && nj < cols && grid[ni][nj] == '.' && !visited[ni][nj]) {
                    visited[ni][nj] = true;
                    queue.add(new int[]{ni, nj});
                }
            }
        }
        return size;
    }

    private void fillWithAsterisk(int startR, int startC) {
        Queue<int[]> queue = new ArrayDeque<>();
        queue.add(new int[]{startR, startC});
        grid[startR][startC] = '*';

        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            for (int i = 0; i < 4; i++) {
                int ni = curr[0] + DX[i];
                int nj = curr[1] + DY[i];
                if (ni >= 0 && ni < rows && nj >= 0 && nj < cols && grid[ni][nj] == '.') {
                    grid[ni][nj] = '*';
                    queue.add(new int[]{ni, nj});
                }
            }
        }
    }

    private static class Component implements Comparable<Component> {
        int startRow, startCol, size;

        Component(int r, int c, int size) {
            this.startRow = r;
            this.startCol = c;
            this.size = size;
        }

        @Override
        public int compareTo(Component other) {
            return Integer.compare(this.size, other.size);
        }
    }

    static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

