/**
 * A refactored solution to minimize the number of '.' cells remaining 
 * in a grid after removing at most k connected components.
 */
public class GridOptimizer {

    /**
     * Represents a single coordinate in the 2D grid.
     */
    private static class Point {
        int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Represents a connected component of '.' cells.
     */
    private static class Component implements Comparable<Component> {
        private final List<Point> points;
        private final int size;

        Component(List<Point> points) {
            this.points = points;
            this.size = points.size();
        }

        public int getSize() {
            return size;
        }

        public List<Point> getPoints() {
            return points;
        }

        @Override
        public int compareTo(Component other) {
            // Sort descending by size to easily pick the largest components
            return Integer.compare(other.size, this.size);
        }
    }

    /**
     * Handles the logic of finding and processing grid components.
     */
    public static class Solver {
        private final int rows;
        private final int cols;
        private final int k;
        private final char[][] grid;
        private final boolean[][] visited;

        private static final int[] DR = {-1, 1, 0, 0};
        private static final int[] DC = {0, 0, -1, 1};

        public Solver(int rows, int cols, int k, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.k = k;
            this.grid = grid;
            this.visited = new boolean[rows][cols];
        }

        public void solve(PrintWriter out) {
            List<Component> components = findAllComponents();
            Collections.sort(components);

            int totalDots = 0;
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.') {
                        totalDots++;
                    }
                }
            }

            int removedDots = 0;
            int componentsRemovedCount = 0;

            // Remove the k largest components
            for (Component comp : components) {
                if (componentsRemovedCount < k) {
                    removedDots += comp.getSize();
                    for (Point p : comp.getPoints()) {
                        grid[p.r][p.c] = '*';
                    }
                    componentsRemovedCount++;
                } else {
                    break;
                }
            }

            // The problem asks for the minimum '.' cells remaining
            out.println(totalDots - removedDots);
            printGrid(out);
        }

        private List<Component> findAllComponents() {
            List<Component> components = new ArrayList<>();

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.' && !visited[i][j]) {
                        components.add(bfs(i, j));
                    }
                }
            }
            return components;
        }

        private Component bfs(int startR, int startC) {
            List<Point> componentPoints = new ArrayList<>();
            Deque<Point> queue = new ArrayDeque<>();

            Point start = new Point(startR, startC);
            queue.add(start);
            visited[startR][startC] = true;

            while (!queue.isEmpty()) {
                Point curr = queue.poll();
                componentPoints.add(curr);

                for (int i = 0; i < 4; i++) {
                    int nr = curr.r + DR[i];
                    int nc = curr.c + DC[i];

                    if (isValid(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        queue.add(new Point(nr, nc));
                    }
                }
            }
            return new Component(componentPoints);
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        private void printGrid(PrintWriter out) {
            for (int i = 0; i < rows; i++) {
                out.println(new String(grid[i]));
            }
        }
    }

    /**
     * Fast I/O Utility.
     */
    private static class FastReader {
