     */
    static class Point {
        final int r, c;
        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Represents a connected component of '.' cells.
     */
    static class Component implements Comparable<Component> {
        final int size;
        final List<Point> cells;
        final boolean isEnclosed;

        Component(int size, List<Point> cells, boolean isEnclosed) {
            this.size = size;
            this.cells = cells;
            this.isEnclosed = isEnclosed;
        }

        @Override
        public int compareTo(Component other) {
            // Sort by size ascending to allow removing the smallest components first
            return Integer.compare(this.size, other.size);
        }
    }

    /**
     * Logic handler for identifying and manipulating grid components.
     */
    static class GridSolver {
        private final char[][] grid;
        private final int rows;
        private final int cols;
        private final boolean[][] visited;
        private static final int[][] DIRECTIONS = {{-1, 0}, {1, 0}, {0, 1}, {0, -1}};

        public GridSolver(char[][] grid, int rows, int cols) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
            this.visited = new boolean[rows][cols];
        }

        /**
         * Solves the problem and prints the results.
         */
        public void solve(int targetK) {
            List<Component> enclosedComponents = new ArrayList<>();

            // 1. Find all connected components using BFS
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.' && !visited[i][j]) {
                        Component comp = findComponent(i, j);
                        if (comp.isEnclosed) {
                            enclosedComponents.add(comp);
                        }
                    }
                }
            }

            PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
            int currentCount = enclosedComponents.size();

            if (currentCount == targetK) {
                // Already meets the target
                out.println(0);
                printGrid(out);
            } else if (currentCount > targetK) {
                // Need to remove components to reach targetK
                Collections.sort(enclosedComponents);

                int totalCost = 0;
                int componentsToRemove = currentCount - targetK;

                for (int i = 0; i < componentsToRemove; i++) {
                    Component comp = enclosedComponents.get(i);
                    totalCost += comp.size;
                    for (Point p : comp.cells) {
                        grid[p.r][p.c] = '*';
                    }
                }

                out.println(totalCost);
                printGrid(out);
            } else {
                // targetK > currentCount: impossible to increase components by adding '*'
                // Defaulting to original grid as per original code behavior
                out.println(0);
                printGrid(out);
            }
            out.flush();
            out.close();
        }

        /**
         * Performs BFS to discover a connected component and check if it is enclosed.
         */
        private Component findComponent(int startR, int startC) {
            List<Point> cells = new ArrayList<>();
            Queue<Point> queue = new LinkedList<>();

            queue.add(new Point(startR, startC));
            visited[startR][startC] = true;

            boolean touchesBoundary = false;
            int size = 0;

            while (!queue.isEmpty()) {
                Point curr = queue.poll();
                cells.add(curr);
                size++;

                // Check if this cell is on the boundary of the grid
                if (curr.r == 0 || curr.r == rows - 1 || curr.c == 0 || curr.c == cols - 1) {
                    touchesBoundary = true;
                }

                for (int[] dir : DIRECTIONS) {
                    int nr = curr.r + dir[0];
                    int nc = curr.c + dir[1];

                    if (isValid(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        queue.add(new Point(nr, nc));
                    }
                }
            }

            return new Component(size, cells, !touchesBoundary);
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        private void printGrid(PrintWriter out) {
            for (int i = 0; i < rows; i++) {
                out.println(new String(grid[i]));
            }
        }
    }
}

import java.util.*;

/**
 * A utility to process grid-based maps, identifying islands of empty cells
 * and removing the smallest islands to reach a target number of islands.
 */
public class GridChecker {

    private static final char EMPTY = '.';
    private static final char WALL = '*';
    private static final char BOUNDARY_CONNECTED = '+';

    private static final int[][] DIRECTIONS = {
            {0, 1}, {0, -1}, {1, 0}, {-1, 0}
    };

    /**
     * Represents a coordinate on the grid.
     */
    private static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    private final int rows;
    private final int cols;
    private final int targetIslandCount;
    private final char[][] grid;
    private final boolean[][] visited;

    public GridChecker(int rows, int cols, int targetIslandCount, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.targetIslandCount = targetIslandCount;
        this.grid = grid;
        this.visited = new boolean[rows][cols];
    }

    /**
     * Main execution logic for processing the grid.
     */
    public void process() {
        markBoundaryConnectedCells();
        List<List<Point>> islands = findInternalIslands();

        // Sort islands by size (ascending) to remove the smallest ones first
        islands.sort(Comparator.comparingInt(List::size));

        int cellsRemoved = 0;
        int islandsToRemove = Math.max(0, islands.size() - targetIslandCount);

        for (int i = 0; i < islandsToRemove; i++) {
            List<Point> island = islands.get(i);
            cellsRemoved += island.size();
            for (Point p : island) {
                grid[p.row][p.col] = WALL;
            }
        }

        printResult(cellsRemoved);
    }

    /**
     * Identifies all empty cells connected to the boundary and marks them 
     * with a special character to distinguish them from internal islands.
     */
    private void markBoundaryConnectedCells() {
        Queue<Point> queue = new ArrayDeque<>();
        boolean[][] boundaryVisited = new boolean[rows][cols];

        // Add all boundary empty cells to the queue
        for (int i = 0; i < rows; i++) {
            checkAndEnqueue(i, 0, queue, boundaryVisited);
            checkAndEnqueue(i, cols - 1, queue, boundaryVisited);
        }
        for (int j = 0; j < cols; j++) {
            checkAndEnqueue(0, j, queue, boundaryVisited);
            checkAndEnqueue(rows - 1, j, queue, boundaryVisited);
        }

        // BFS to mark boundary-connected cells
        while (!queue.isEmpty()) {
            Point curr = queue.poll();
            if (grid[curr.row][curr.col] == EMPTY) {
                grid[curr.row][curr.col] = BOUNDARY_CONNECTED;

                for (int[] dir : DIRECTIONS) {
                    int nr = curr.row + dir[0];
                    int nc = curr.col + dir[1];
                    if (isValid(nr, nc) && grid[nr][nc] == EMPTY && !boundaryVisited[nr][nc]) {
                        boundaryVisited[nr][nc] = true;
                        queue.add(new Point(nr, nc));
                    }
                }
            }
        }
    }

    private void checkAndEnqueue(int r, int c, Queue<Point> q, boolean[][] bv) {
        if (isValid(r, c) && grid[r][c] == EMPTY && !bv[r][c]) {
            bv[r][c] = true;
            q.add(new Point(r, c));
        }
    }

    /**
     * Scans the grid for islands of empty cells that are not connected to the boundary.
     */
    private List<List<Point>> findInternalIslands() {
        List<List<Point>> islands = new ArrayList<>();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == EMPTY && !visited[i][j]) {
                    islands.add(bfsFindIsland(i, j));
                }
            }
        }
        return islands;
    }

    /**
     * Performs BFS to find all connected empty cells for a single island.
     */
    private List<Point> bfsFindIsland(int startR, int startC) {
        List<Point> island = new ArrayList<>();
        Queue<Point> queue = new ArrayDeque<>();

        Point start = new Point(startR, startC);
        queue.add(start);
        visited[startR][startC] = true;

        while (!queue.isEmpty()) {
            Point curr = queue.poll();
            island.add(curr);

            for (int[] dir : DIRECTIONS) {
                int nr = curr.row + dir[0];
                int nc = curr.col + dir[1];
                if (isValid(nr, nc) && grid[nr][nc] == EMPTY && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    queue.add(new Point(nr, nc));
                }
            }
        }
        return island;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Prints the number of removed cells and the final state of the grid.
     */
    private void printResult(int cellsRemoved) {
        System.out.println(cellsRemoved);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                char c = grid[i][j];
                // Restore boundary-connected marker to empty cell
                if (c == BOUNDARY_CONNECTED) {
                    c = EMPTY;
                }
                sb.append(c);
            }
            sb.append('\n');
        }
        System.out.print(sb.toString());
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        if (!sc.hasNextInt()) {
            sc.close();
            return;
        }

        int n = sc.nextInt();
        int m = sc.nextInt();
        int k = sc.nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String line = sc.next();
            for (int j = 0; j < m; j++) {
                grid[i][j] = line.charAt(j);
            }
        }
        sc.close();

        GridChecker checker = new GridChecker(n, m, k, grid);
        checker.process();
    }
}

