/**
 * A program to identify "lakes" (connected components of water cells that do not 
 * touch the grid boundary) and fill the smallest lakes with '*' until the 
 * number of lakes is reduced to K.
 */
public class Main {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        if (!sc.hasNextInt()) return;
        int rows = sc.nextInt();
        int cols = sc.nextInt();
        int k = sc.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = sc.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
            }
        }

        LakeSolver solver = new LakeSolver(grid, rows, cols, k);
        solver.solve();
    }
}

class LakeSolver {
    private final char[][] grid;
    private final int rows;
    private final int cols;
    private final int targetLakeCount;

    // Direction vectors for 4-way connectivity (Up, Down, Left, Right)
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    /**
     * Represents a coordinate in the grid.
     */
    private record Point(int r, int c) {}

    public LakeSolver(char[][] grid, int rows, int cols, int targetLakeCount) {
        this.grid = grid;
        this.rows = rows;
        this.cols = cols;
        this.targetLakeCount = targetLakeCount;
    }

    public void solve() {
        List<List<Point>> lakes = findLakes();

        // Sort lakes by size (ascending) to fill the smallest ones first
        lakes.sort(Comparator.comparingInt(List::size));

        int lakesToRemove = lakes.size() - targetLakeCount;
        int cellsChanged = 0;

        for (int i = 0; i < lakesToRemove; i++) {
            for (Point p : lakes.get(i)) {
                grid[p.r][p.c] = '*';
                cellsChanged++;
            }
        }

        printResult(cellsChanged);
    }

    /**
     * Uses BFS to find all connected components of '.' that do not touch the boundary.
     */
    private List<List<Point>> findLakes() {
        List<List<Point>> lakes = new ArrayList<>();
        boolean[][] visited = new boolean[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && !visited[r][c]) {
                    List<Point> component = bfs(r, c, visited);
                    if (!isComponentTouchingBoundary(component)) {
                        lakes.add(component);
                    }
                }
            }
        }
        return lakes;
    }

    private List<Point> bfs(int startR, int startC, boolean[][] visited) {
        List<Point> component = new ArrayList<>();
        Deque<Point> queue = new ArrayDeque<>();

        Point start = new Point(startR, startC);
        queue.add(start);
        visited[startR][startC] = true;

        while (!queue.isEmpty()) {
            Point curr = queue.poll();
            component.add(curr);

            for (int i = 0; i < 4; i++) {
                int nr = curr.r + DR[i];
                int nc = curr.c + DC[i];

                if (isValid(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    queue.add(new Point(nr, nc));
                }
            }
        }
        return component;
    }

    private boolean isComponentTouchingBoundary(List<Point> component) {
        for (Point p : component) {
            if (p.r == 0 || p.r == rows - 1 || p.c == 0 || p.c == cols - 1) {
                return true;
            }
        }
        return false;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private void printResult(int cellsChanged) {
        System.out.println(cellsChanged);
        StringBuilder sb = new StringBuilder();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                sb.append(grid[r][c]);
            }
            sb.append('\n');
        }
        System.out.print(sb.toString());
    }
}

