/**
 * Handles the logic of finding and manipulating lakes within a grid.
 */
class LakeManager {
    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final boolean[][] visited;

    private static final int[] ROW_OFFSETS = {-1, 1, 0, 0};
    private static final int[] COL_OFFSETS = {0, 0, -1, 1};

    public LakeManager(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.visited = new boolean[rows][cols];
    }

    /**
     * Processes the grid to ensure the number of enclosed lakes equals the target count.
     * 
     * @param targetLakeCount The desired number of enclosed lakes to keep.
     * @return The number of cells transformed from '.' to '*'.
     */
    public int processLakes(int targetLakeCount) {
        List<Lake> enclosedLakes = findEnclosedLakes();

        int redundancy = enclosedLakes.size() - targetLakeCount;
        if (redundancy <= 0) {
            return 0;
        }

        // Sort lakes by size ascending to minimize transformed cells
        enclosedLakes.sort(Comparator.comparingInt(Lake::getSize));

        int transformedCellsCount = 0;
        for (int i = 0; i < redundancy; i++) {
            Lake lakeToTransform = enclosedLakes.get(i);
            transformedCellsCount += lakeToTransform.getSize();
            for (Point p : lakeToTransform.getCells()) {
                grid[p.r()][p.c()] = '*';
            }
        }

        return transformedCellsCount;
    }

    private List<Lake> findEnclosedLakes() {
        List<Lake> enclosedLakes = new ArrayList<>();

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && !visited[r][c]) {
                    List<Point> component = new ArrayList<>();
                    boolean touchesBoundary = performDFS(r, c, component);

                    // If the component of '.' does not touch the edge, it's an enclosed lake
                    if (!touchesBoundary) {
                        enclosedLakes.add(new Lake(component));
                    }
                }
            }
        }
        return enclosedLakes;
    }

    private boolean performDFS(int r, int c, List<Point> component) {
        Queue<Point> queue = new LinkedList<>();
        Point start = new Point(r, c);
        queue.add(start);
        visited[r][c] = true;

        boolean touchesBoundary = false;

        while (!queue.isEmpty()) {
            Point curr = queue.poll();
            component.add(curr);

            // Check if this cell is on the boundary
            if (curr.r() == 0 || curr.r() == rows - 1 || curr.c() == 0 || curr.c() == cols - 1) {
                touchesBoundary = true;
            }

            for (int i = 0; i < 4; i++) {
                int nr = curr.r() + ROW_OFFSETS[i];
                int nc = curr.c() + COL_OFFSETS[i];

                if (isValidMove(nr, nc)) {
                    visited[nr][nc] = true;
                    queue.add(new Point(nr, nc));
                }
            }
        }
        return touchesBoundary;
    }

    private boolean isValidMove(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols 
                && grid[r][c] == '.' && !visited[r][c];
    }

    public void printGrid() {
        for (int i = 0; i < rows; i++) {
            System.out.println(new String(grid[i]));
        }
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        int targetLakeCount = scanner.nextInt();
        scanner.nextLine(); // Consume newline

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.nextLine();
            grid[i] = line.toCharArray();
        }

        LakeManager manager = new LakeManager(rows, cols, grid);
        int transformedCount = manager.processLakes(targetLakeCount);

        System.out.println(transformedCount);
        manager.printGrid();

        scanner.close();
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for grid-based landmass processing.
 * The goal is to identify landmasses not connected to the ocean 
 * and "cover" (convert to water) the smallest ones until a target 
 * number of components remains.
 */
public class Training2_C {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            int k = reader.nextInt();

            boolean[][] initialGrid = new boolean[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                for (int j = 0; j < cols; j++) {
                    initialGrid[i][j] = (line.charAt(j) == '.');
                }
            }

            GridProcessor processor = new GridProcessor(rows, cols, initialGrid);
            processor.process(k);

            out.println(processor.getTotalCellsCovered());
            processor.printGrid(out);

        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Represents a single coordinate in the grid.
     */
    record Cell(int r, int c) {}

    /**
     * Represents a connected component of land.
     */
    static class Component implements Comparable<Component> {
        final List<Cell> cells;
        final int size;
        final boolean touchesOcean;

        Component(List<Cell> cells, boolean touchesOcean) {
            this.cells = cells;
            this.size = cells.size();
            this.touchesOcean = touchesOcean;
        }

        @Override
        public int compareTo(Component other) {
            return Integer.compare(this.size, other.size);
        }
    }

    /**
     * Handles the core logic of finding and modifying land components.
     */
    static class GridProcessor {
        private final int rows;
        private final int cols;
        private final boolean[][] grid;
        private final boolean[][] resultGrid;
        private int totalCellsCovered = 0;

        private static final int[] DR = {-1, 1, 0, 0};
        private static final int[] DC = {0, 0, -1, 1};

        public GridProcessor(int rows, int cols, boolean[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            this.resultGrid = new boolean[rows][cols];
            for (int i = 0; i < rows; i++) {
                System.arraycopy(grid[i], 0, this.resultGrid[i], 0, cols);
            }
        }

        public void process(int k) {
            boolean[][] visited = new boolean[rows][cols];
            List<Component> isolatedComponents = new ArrayList<>();

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] && !visited[i][j]) {
                        Component comp = findComponent(i, j, visited);
                        if (!comp.touchesOcean) {
                            isolatedComponents.add(comp);
                        }
                    }
                }
            }

            // Sort components by size to cover the smallest ones first
            Collections.sort(isolatedComponents);

            // We want to keep k components, so we cover (total - k) components
            int componentsToCover = Math.max(0, isolatedComponents.size() - k);

            for (int i = 0; i < componentsToCover; i++) {
                Component comp = isolatedComponents.get(i);
                coverComponent(comp);
            }
        }

        /**
         * Uses BFS to find all connected land cells and determine if it touches the ocean.
         */
        private Component findComponent(int startR, int startC, boolean[][] visited) {
            List<Cell> componentCells = new ArrayList<>();
            Queue<Cell> queue = new LinkedList<>();

            Cell start = new Cell(startR, startC);
            queue.add(start);
            visited[startR][startC] = true;

            boolean touchesOcean = false;

            while (!queue.isEmpty()) {
                Cell curr = queue.poll();
                componentCells.add(curr);

                if (curr.r == 0 || curr.r == rows - 1 || curr.c == 0 || curr.c == cols - 1) {
                    touchesOcean = true;
                }

                for (int i = 0; i < 4; i++) {
                    int nr = curr.r + DR[i];
                    int nc = curr.c + DC[i];

                    if (isValid(nr, nc) && grid[nr][nc] && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        queue.add(new Cell(nr, nc));
                    }
                }
            }
            return new Component(componentCells, touchesOcean);
        }

        private void coverComponent(Component comp) {
            totalCellsCovered += comp.size;
            for (Cell cell : comp.cells) {
                resultGrid[cell.r][cell.c] = false;
            }
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        public int getTotalCellsCovered() {
            return totalCellsCovered;
        }

        public void printGrid(PrintWriter out) {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    out.print(resultGrid[i][j] ? "." : "*");
                }
                out.println();
            }
        }
    }

    /**
     * Utility class for fast I/O operations.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the Lakes in Berland problem.
 * This program identifies "lakes" (connected water cells not connected to the border),
 * sorts them by size, and removes the k smallest lakes.
 */
public class LakesInBerland {

    // Constants for better maintainability
    private static final char WATER = '.';
    private static final char LAND = '#';
    private static final char BORDER_WATER_MARKER = 'B'; // Temporary marker for ocean/border water

    /**
     * Represents a single lake in the grid.
     */
    private static class Lake {
        final int size;
        final List<int[]> coordinates;

        Lake(int size, List<int[]> coordinates) {
            this.size = size;
            this.coordinates = coordinates;
        }
    }

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = reader.nextInt();
            int m = reader.nextInt();
            int k = reader.nextInt();

            if (n <= 0 || m <= 0) {
                out.close();
                return;
            }

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                String line = reader.nextLine();
                grid[i] = line.toCharArray();
            }

            processLakes(grid, n, m, k, out);

        } catch (Exception e) {
            // In a production environment, use a logger
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    private static void processLakes(char[][] grid, int n, int m, int k, PrintWriter out) {
        // 1. Mark all water cells connected to the border as 'ocean' (non-lakes)
        markBorderWater(grid, n, m);

        // 2. Find all internal lakes
        List<Lake> lakes = findLakes(grid, n, m);

        // 3. Sort lakes by size (ascending) to identify the smallest ones
        lakes.sort(Comparator.comparingInt(lake -> lake.size));

        // 4. Remove the k smallest lakes
        int totalRemovedArea = 0;
        int lakesToRemove = Math.min(k, lakes.size());
        for (int i = 0; i < lakesToRemove; i++) {
            Lake lake = lakes.get(i);
            totalRemovedArea += lake.size;
            for (int[] coord : lake.coordinates) {
                grid[coord[0]][coord[1]] = LAND;
            }
        }

        // 5. Output the result
        out.println(totalRemovedArea);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                // Convert the temporary border marker back to standard water
                if (grid[i][j] == BORDER_WATER_MARKER) {
                    out.print(WATER);
                } else {
                    out.print(grid[i][j]);
                }
            }
            out.println();
        }
    }

    /**
     * Uses BFS to mark all '.' cells connected to the edge of the grid.
     */
    private static void markBorderWater(char[][] grid, int n, int m) {
        Queue<int[]> queue = new LinkedList<>();

        // Add all border cells to the queue
        for (int i = 0; i < n; i++) {
            if (grid[i][0] == WATER) {
                grid[i][0] = BORDER_WATER_MARKER;
                queue.add(new int[]{i, 0});
            }
            if (m > 1 && grid[i][m - 1] == WATER) {
                grid[i][m - 1] = BORDER_WATER_MARKER;
                queue.add(new int[]{i, m - 1});
            }
        }
        for (int j = 1; j < m - 1; j++) {
            if (grid[0][j] == WATER) {
                grid[0][j] = BORDER_WATER_MARKER;
                queue.add(new int[]{0, j});
            }
            if (n > 1 && grid[n - 1][j] == WATER) {
                grid[n - 1][j] = BORDER_WATER_MARKER;
                queue.add(new int[]{n - 1, j});
            }
        }

        int[][] dirs = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            for (int[] d : dirs) {
                int ni = curr[0] + d[0];
                int nj = curr[1] + d[1];

                if (ni >= 0 && ni < n && nj >= 0 && nj < m && grid[ni][nj] == WATER) {
                    grid[ni][nj] = BORDER_WATER_MARKER;
                    queue.add(new int[]{ni, nj});
                }
            }
        }
    }

    /**
     * Iterates through the grid to find all connected components of '.' (lakes).
     */
    private static List<Lake> findLakes(char[][] grid, int n, int m) {
        List<Lake> lakes = new ArrayList<>();
        boolean[][] visited = new boolean[n][m];
        int[][] dirs = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                // A lake is a water cell that is not part of the border ocean
                if (grid[i][j] == WATER && !visited[i][j]) {
                    lakes.add(bfsFindLake(grid, i, j, n, m, visited, dirs));
                }
            }
        }
        return lakes;
    }

    private static Lake bfsFindLake(char[][] grid, int startI, int startJ, int n, int m, boolean[][] visited, int[][] dirs) {
        List<int[]> coords = new ArrayList<>();
        Queue<int[]> queue = new LinkedList<>();

        queue.add(new int[]{startI, startJ});
        visited[startI][startJ] = true;

        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            coords.add(curr);

            for (int[] d : dirs) {
                int ni = curr[0] + d[0];
                int nj = curr[1] + d[1];

                if (ni >= 0 && ni < n && nj >= 0 && nj < m && grid[ni][nj] == WATER && !visited[ni][nj]) {
                    visited[ni][nj] = true;
                    queue.add(new int[]{ni, nj});
                }
            }
        }
        return new Lake(coords.size(), coords);
    }

    /**
     * Fast I/O helper class.
     */
    private static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                return "";
            }
        }
    }
}

import java.util.*;

/**
 * LakeProcessor handles the identification and conversion of water components (lakes) 
 * into land components based on a specified threshold.
 */
public class LakeProcessor {

    // Direction vectors for 4-connectivity (Up, Down, Left, Right)
    private static final int[] DIRECTIONS_X = {0, 0, 1, -1};
    private static final int[] DIRECTIONS_Y = {1, -1, 0, 0};

    /**
     * Represents a single coordinate in the grid.
     */
    private static class Point {
        final int x, y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    /**
     * Represents a connected component of water cells.
     */
    private static class Lake {
        private final List<Point> points;
        private final boolean isLake; // A lake is a component that does not touch the grid boundary

        Lake(List<Point> points, boolean isLake) {
            this.points = points;
            this.isLake = isLake;
        }

        int size() {
            return points.size();
        }

        boolean isLake() {
            return isLake;
        }

        List<Point> getPoints() {
            return points;
        }
    }

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final boolean[][] visited;

    public LakeProcessor(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.visited = new boolean[rows][cols];
    }

    /**
     * Main logic to find lakes and fill the smallest ones if the count exceeds the threshold.
     * 
     * @param k The maximum number of lakes allowed.
     */
    public void process(int k) {
        List<Lake> lakes = findLakes();
        int totalCellsConverted = 0;

        if (lakes.size() > k) {
            // We need to convert (totalLakes - k) lakes to land.
            // To minimize the number of cells changed, we sort by size ascending.
            int numToConvert = lakes.size() - k;
            lakes.sort(Comparator.comparingInt(Lake::size));

            for (int i = 0; i < numToConvert; i++) {
                Lake lakeToFill = lakes.get(i);
                totalCellsConverted += lakeToFill.size();
                for (Point p : lakeToFill.getPoints()) {
                    grid[p.x][p.y] = '*';
                }
            }
        }

        printResult(totalCellsConverted);
    }

    /**
     * Traverses the grid to find all water components and distinguishes lakes from coastal water.
     */
    private List<Lake> findLakes() {
        List<Lake> lakes = new ArrayList<>();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                // If we find unvisited water, it's a new connected component
                if (grid[i][j] == '.' && !visited[i][j]) {
                    Lake component = performBFS(i, j);
                    if (component.isLake()) {
                        lakes.add(component);
                    }
                }
            }
        }
        return lakes;
    }

    /**
     * Uses BFS to find all connected '.' cells and determines if the component is a lake.
     */
    private Lake performBFS(int startX, int startY) {
        List<Point> componentPoints = new ArrayList<>();
        Queue<Point> queue = new LinkedList<>();
        boolean touchesBoundary = false;

        visited[startX][startY] = true;
        queue.add(new Point(startX, startY));

        while (!queue.isEmpty()) {
            Point current = queue.poll();
            componentPoints.add(current);

            // If any cell in the component is on the edge, the component is not a "lake"
            if (current.x == 0 || current.x == rows - 1 || current.y == 0 || current.y == cols - 1) {
                touchesBoundary = true;
            }

            for (int i = 0; i < 4; i++) {
                int nextX = current.x + DIRECTIONS_X[i];
                int nextY = current.y + DIRECTIONS_Y[i];

                if (isValid(nextX, nextY) && grid[nextX][nextY] == '.' && !visited[nextX][nextY]) {
                    visited[nextX][nextY] = true;
                    queue.add(new Point(nextX, nextY));
                }
            }
        }

        return new Lake(componentPoints, !touchesBoundary);
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private void printResult(int convertedCount) {
        System.out.println(convertedCount);
        for (int i = 0; i < rows; i++) {
            System.out.println(new String(grid[i]));
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        int k = scanner.nextInt();
        scanner.nextLine(); // consume the remaining newline

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.nextLine().toCharArray();
        }

        LakeProcessor processor = new LakeProcessor(rows, cols, grid);
        processor.process(k);

        scanner.close();
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for grid component processing.
 * Identifies connected components of '.' cells that do not touch the boundary,
 * and fills the k smallest such components with '*'.
 */
public class Solution {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            int k = reader.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }

            GridProcessor processor = new GridProcessor(grid, rows, cols);
            processor.process(k);
            processor.printResult();

        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Represents a connected component of '.' cells.
     */
    static class Component implements Comparable<Component> {
        private final List<Point> cells = new ArrayList<>();
        private boolean touchesBoundary = false;

        public void addCell(int r, int c, boolean isBoundary) {
            cells.add(new Point(r, c));
            if (isBoundary) {
                touchesBoundary = true;
            }
        }

        public int getSize() {
            return cells.size();
        }

        public boolean touchesBoundary() {
            return touchesBoundary;
        }

        public List<Point> getCells() {
            return cells;
        }

        @Override
        public int compareTo(Component other) {
            return Integer.compare(this.getSize(), other.getSize());
        }
    }

    /**
     * Simple data holder for coordinates.
     */
    static class Point {
        final int r, c;
        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Logic for processing the grid and managing components.
     */
    static class GridProcessor {
        private final char[][] grid;
        private final int rows;
        private final int cols;
        private int totalCellsChanged = 0;

        public GridProcessor(char[][] grid, int rows, int cols) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
        }

        public void process(int k) {
            boolean[][] visited = new boolean[rows][cols];
            PriorityQueue<Component> interiorComponents = new PriorityQueue<>();

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.' && !visited[i][j]) {
                        Component component = findComponent(i, j, visited);
                        if (!component.touchesBoundary()) {
                            interiorComponents.add(component);
                        }
                    }
                }
            }

            // Fill the k smallest interior components
            int count = 0;
            while (count < k && !interiorComponents.isEmpty()) {
                Component comp = interiorComponents.poll();
                for (Point p : comp.getCells()) {
                    grid[p.r][p.c] = '*';
                }
                totalCellsChanged += comp.getSize();
                count++;
            }
        }

        /**
         * Uses BFS to find all connected '.' cells to avoid StackOverflowError.
         */
        private Component findComponent(int startR, int startC, boolean[][] visited) {
            Component component = new Component();
            Queue<Point> queue = new LinkedList<>();

            queue.offer(new Point(startR, startC));
            visited[startR][startC] = true;

            int[] dr = {1, -1, 0, 0};
            int[] dc = {0, 0, 1, -1};

            while (!queue.isEmpty()) {
                Point curr = queue.poll();
                boolean isBoundary = (curr.r == 0 || curr.r == rows - 1 || curr.c == 0 || curr.c == cols - 1);
                component.addCell(curr.r, curr.c, isBoundary);

                for (int i = 0; i < 4; i++) {
                    int nr = curr.r + dr[i];
                    int nc = curr.c + dc[i];

                    if (isValid(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        queue.offer(new Point(nr, nc));
                    }
                }
            }
            return component;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        public void printResult() {
            System.out.println(totalCellsChanged);
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    sb.append(grid[i][j]);
                }
                sb.append("\n");
            }
            System.out.print(sb.toString());
        }
    }

    /**
     * Faster input reader for competitive programming scenarios.
     */
    static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * LakeSolver identifies connected components of '.' in a grid.
 * It classifies them as 'sea' (connected to the boundary) or 'lakes' (enclosed).
 * It retains the K largest lakes and fills the remaining lakes with '*'.
 */
public class LakeSolver {

    // Direction vectors for 4-way connectivity (Up, Down, Left, Right)
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    /**
     * Represents a single coordinate in the grid.
     */
    private static class Point {
        final int r, c;
        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Represents an enclosed lake containing a list of its coordinates.
     */
    private static class Lake {
        final List<Point> points;
        Lake(List<Point> points) {
            this.points = points;
        }
        int size() {
            return points.size();
        }
    }

    /**
     * Fast I/O utility for efficient reading of large input sets.
     */
    private static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String next = next();
            return next == null ? 0 : Integer.parseInt(next);
        }
    }

    public static void main(String[] args) {
        new LakeSolver().solve();
    }

    public void solve() {
        FastReader fr = new FastReader();

        String firstToken = fr.next();
        if (firstToken == null) return;

        int n = Integer.parseInt(firstToken);
        int m = fr.nextInt();
        int k = fr.nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String row = fr.next();
            if (row != null) {
                grid[i] = row.toCharArray();
            }
        }

        // visited[i][j] tracks if a cell has been processed as sea or lake
        boolean[][] visited = new boolean[n][m];

        // 1. Identify and mark the "sea" (all '.' reachable from the boundary)
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (isBoundary(i, j, n, m) && grid[i][j] == '.' && !visited[i][j]) {
                    bfsMarkSea(i, j, n, m, grid, visited);
                }
            }
        }

        // 2. Identify all remaining '.' areas as enclosed "lakes"
        List<Lake> lakes = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.' && !visited[i][j]) {
                    lakes.add(bfsCollectLake(i, j, n, m, grid, visited));
                }
            }
        }

        // 3. Sort lakes by size ascending to identify the smallest ones for removal
        lakes.sort(Comparator.comparingInt(Lake::size));

        // 4. Fill the smallest (TotalLakes - K) lakes with '*'
        int numToRemove = Math.max(0, lakes.size() - k);
        for (int i = 0; i < numToRemove; i++) {
            for (Point p : lakes.get(i).points) {
                grid[p.r][p.c] = '*';
            }
        }

        // 5. Print the modified grid
        PrintWriter out = new PrintWriter(System.out);
        for (int i = 0; i < n; i++) {
            out.println(new String(grid[i]));
        }
        out.flush();
        out.close();
    }

    private boolean isBoundary(int r, int c, int n, int m) {
        return r == 0 || r == n - 1 || c == 0 || c == m - 1;
    }

    private void bfsMarkSea(int startR, int startC, int n, int m, char[][] grid, boolean[][] visited) {
        Queue<Point> queue = new ArrayDeque<>();
        queue.add(new Point(startR, startC));
        visited[startR][startC] = true;

        while (!queue.isEmpty()) {
            Point curr = queue.poll();
            for (int i = 0; i < 4; i++) {
                int nr = curr.r + DR[i];
                int nc = curr.c + DC[i];

                if (isValid(nr, nc, n, m) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    queue.add(new Point(nr, nc));
                }
            }
        }
    }

    private Lake bfsCollectLake(int startR, int startC, int n, int m, char[][] grid, boolean[][] visited) {
        List<Point> lakePoints = new ArrayList<>();
        Queue<Point> queue = new ArrayDeque<>();

        queue.add(new Point(startR, startC));
        visited[startR][startC] = true;
        lakePoints.add(new Point(startR, startC));

        while (!queue.isEmpty()) {
            Point curr = queue.poll();
            for (int i = 0; i < 4; i++) {
                int nr = curr.r + DR[i];
                int nc = curr.c + DC[i];

                if (isValid(nr, nc, n, m) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    Point next = new Point(nr, nc);
                    lakePoints.add(next);
                    queue.add(next);
                }
            }
        }
        return new Lake(lakePoints);
    }

    private boolean isValid(int r, int c, int n, int m) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to find enclosed connected components in a grid and remove the smallest ones.
 * An enclosed component is a group of '.' cells that does not touch the grid boundary.
 */
public class EnclosedComponentManager {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            int k = reader.nextInt();

            char[][] gridData = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = reader.nextLine();
                for (int j = 0; j < cols; j++) {
                    gridData[i][j] = line.charAt(j);
                }
            }

            GridSolver solver = new GridSolver(rows, cols, gridData);
            solver.solve(k);
            solver.printGrid(out);

        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.close();
        }
    }

    /**
     * Represents a single coordinate in the grid.
     */
    record Cell(int r, int c) {}

    /**
     * Represents a connected component of '.' cells.
     */
    static class Component implements Comparable<Component> {
        private final int id;
        private final List<Cell> cells;

        public Component(int id, List<Cell> cells) {
            this.id = id;
            this.cells = cells;
        }

        public int size() {
            return cells.size();
        }

        public List<Cell> getCells() {
            return cells;
        }

        @Override
        public int compareTo(Component other) {
            if (this.size() != other.size()) {
                return Integer.compare(this.size(), other.size());
            }
            return Integer.compare(this.id, other.id);
        }
    }

    /**
     * Handles the logic of finding and manipulating grid components.
     */
    static class GridSolver {
        private final int rows;
        private final int cols;
        private final char[][] grid;

        private static final int[] ROW_OFFSETS = {-1, 0, 1, 0};
        private static final int[] COL_OFFSETS = {0, 1, 0, -1};

        public GridSolver(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
        }

        public void solve(int kToKeep) {
            boolean[][] visited = new boolean[rows][cols];
            List<Component> enclosedComponents = new ArrayList<>();
            int componentIdCounter = 0;

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.' && !visited[i][j]) {
                        Component comp = findComponent(i, j, visited);
                        // Only consider components that are fully enclosed (don't touch boundaries)
                        if (isEnclosed(comp)) {
                            enclosedComponents.add(new Component(componentIdCounter++, comp.getCells()));
                        }
                    }
                }
            }

            // The original logic: remove the smallest components until only k remain.
            // If k is greater than total found, nothing is removed.
            Collections.sort(enclosedComponents);
            int numToRemove = Math.max(0, enclosedComponents.size() - kToKeep);

            for (int i = 0; i < numToRemove; i++) {
                for (Cell cell : enclosedComponents.get(i).getCells()) {
                    grid[cell.r()][cell.c()] = '*';
                }
            }
        }

        /**
         * Uses BFS to find all connected '.' cells. 
         * BFS is used instead of DFS to prevent StackOverflowError on large grids.
         */
        private Component findComponent(int startR, int startC, boolean[][] visited) {
            List<Cell> componentCells = new ArrayList<>();
            Deque<Cell> queue = new ArrayDeque<>();

            Cell start = new Cell(startR, startC);
            queue.add(start);
            visited[startR][startC] = true;

            while (!queue.isEmpty()) {
                Cell current = queue.poll();
                componentCells.add(current);

                for (int i = 0; i < 4; i++) {
                    int nr = current.r() + ROW_OFFSETS[i];
                    int nc = current.c() + COL_OFFSETS[i];

                    if (isInBounds(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        queue.add(new Cell(nr, nc));
                    }
                }
            }
            return new Component(-1, componentCells);
        }

        private boolean isEnclosed(Component comp) {
            for (Cell cell : comp.getCells()) {
                if (cell.r() == 0 || cell.r() == rows - 1 || cell.c() == 0 || cell.c() == cols - 1) {
                    return false;
                }
            }
            return true;
        }

        private boolean isInBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        public void printGrid(PrintWriter out) {
            for (int i = 0; i < rows; i++) {
                out.println(new String(grid[i]));
            }
        }
    }

    /**
     * Utility class for fast I/O operations.
     */
    static class FastReader {
        private final InputStream in;
        private final byte[] buffer = new byte[1024];
        private int pointer = 0;
        private int bufferLength = 0;

        public FastReader(InputStream in) {
            this.in = in;
        }

        private int read() throws IOException {
            if (pointer >= bufferLength) {
                pointer = 0;
                bufferLength = in.read(buffer);
                if (bufferLength <= 0) return -1;
            }
            return buffer[pointer++];
        }

        public int nextInt() throws IOException {
            int c = read();
            while (c != -1 && c <= 32) c = read();
            if (c == -1) return 0;
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            while (c >= '0' && c <= '9') {
                res = res * 10 + (c - '0');
                c = read();
            }
            return res * sgn;
        }

        public String nextLine() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c = read();
            while (c != -1 && (c == '\r' || c == '\n')) c = read();
            while (c != -1 && c != '\r' && c != '\n') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }
    }
}

import java.io.InputStream;
import java.io.PrintStream;
import java.util.*;

/**
 * A program to identify lakes in a grid and fill the smallest ones 
 * until only 'k' lakes remain.
 */
public class MainD {

    // Cell Type Constants
    private static final int WATER = 0;
    private static final int LAND = 1;
    private static final int OCEAN = -1;

    // Direction vectors for 4-way connectivity (Up, Down, Left, Right)
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    /**
     * Represents a coordinate in the grid.
     */
    private record Point(int r, int c) {}

    /**
     * Represents a discovered lake, containing its size and the coordinates of its cells.
     */
    private record Lake(int size, List<Point> points) {}

    public static void main(String[] args) {
        run(System.in, System.out);
    }

    /**
     * Orchestrates the lake identification and filling process.
     */
    public static void run(InputStream in, PrintStream out) {
        Scanner sc = new Scanner(in);
        if (!sc.hasNextInt()) return;

        int rows = sc.nextInt();
        int cols = sc.nextInt();
        int k = sc.nextInt();

        int[][] grid = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = sc.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = (line.charAt(j) == '*') ? LAND : WATER;
            }
        }

        // 1. Mark water cells connected to the boundary as OCEAN
        identifyOcean(grid, rows, cols);

        // 2. Identify all isolated lakes (water components not connected to ocean)
        List<Lake> lakes = identifyLakes(grid, rows, cols);

        // 3. Determine how many lakes must be filled to leave exactly k lakes
        // We sort by size ascending so we fill the smallest lakes first.
        int lakesToFillCount = Math.max(0, lakes.size() - k);
        lakes.sort(Comparator.comparingInt(Lake::size));

        int totalCellsFilled = 0;
        for (int i = 0; i < lakesToFillCount; i++) {
            Lake lake = lakes.get(i);
            totalCellsFilled += lake.size();
            for (Point p : lake.points()) {
                grid[p.r][p.c] = LAND;
            }
        }

        // 4. Output results
        out.println(totalCellsFilled);
        printGrid(grid, rows, cols, out);
    }

    /**
     * Performs BFS from all boundary water cells to mark them and their 
     * connected components as OCEAN.
     */
    private static void identifyOcean(int[][] grid, int rows, int cols) {
        Deque<Point> queue = new ArrayDeque<>();

        // Initialize queue with all water cells on the boundary
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (i == 0 || i == rows - 1 || j == 0 || j == cols - 1) {
                    if (grid[i][j] == WATER) {
                        grid[i][j] = OCEAN;
                        queue.add(new Point(i, j));
                    }
                }
            }
        }

        // Standard BFS
        while (!queue.isEmpty()) {
            Point curr = queue.poll();
            for (int i = 0; i < 4; i++) {
                int nr = curr.r + DR[i];
                int nc = curr.c + DC[i];

                if (isValid(nr, nc, rows, cols) && grid[nr][nc] == WATER) {
                    grid[nr][nc] = OCEAN;
                    queue.add(new Point(nr, nc));
                }
            }
        }
    }

    /**
     * Scans the grid for WATER components to identify individual lakes.
     */
    private static List<Lake> identifyLakes(int[][] grid, int rows, int cols) {
        List<Lake> lakes = new ArrayList<>();
        boolean[][] visited = new boolean[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == WATER && !visited[i][j]) {
                    lakes.add(bfsFindLake(grid, visited, i, j, rows, cols));
                }
            }
        }
        return lakes;
    }

    /**
     * Uses BFS to find all connected water cells forming a single lake.
     */
    private static Lake bfsFindLake(int[][] grid, boolean[][] visited, int startR, int startC, int rows, int cols) {
        List<Point> points = new ArrayList<>();
        Deque<Point> queue = new ArrayDeque<>();

        Point start = new Point(startR, startC);
        visited[startR][startC] = true;
        queue.add(start);
        points.add(start);

        while (!queue.isEmpty()) {
            Point curr = queue.poll();
            for (int i = 0; i < 4; i++) {
                int nr = curr.r + DR[i];
                int nc = curr.c + DC[i];

                if (isValid(nr, nc, rows, cols) && grid[nr][nc] == WATER && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    Point next = new Point(nr, nc);
                    queue.add(next);
                    points.add(next);
                }
            }
        }
        return new Lake(points.size(), points);
    }

    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Prints the final state of the grid.
     */
    private static void printGrid(int[][] grid, int rows, int cols, PrintStream out) {
        for (int i = 0; i < rows; i++) {
            StringBuilder sb = new StringBuilder();
            for (int j = 0; j < cols; j++) {
                sb.append(grid[i][j] == LAND ? '*' : '.');
            }
            out.println(sb.toString());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * This program identifies connected components of empty cells ('.') in a grid.
 * If the number of components exceeds a given threshold K, it removes the smallest 
 * components by converting them into walls ('*') until the number of components 
 * is within the limit.
 */
public class GridComponentManager {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            int k = reader.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            GridSolver solver = new GridSolver(rows, cols, k, grid);
            solver.solve(writer);
        } catch (Exception e) {
            // In a production environment, use a proper logging framework.
        } finally {
            writer.close();
        }
    }

    /**
     * Represents a 2D coordinate in the grid.
     */
    private static class Point {
        final int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Represents a connected group of '.' cells.
     * Implements Comparable to allow sorting components by size.
     */
    private static class Component implements Comparable<Component> {
        final List<Point> cells;
        final int size;

        Component(List<Point> cells) {
            this.cells = cells;
            this.size = cells.size();
        }

        @Override
        public int compareTo(Component other) {
            return Integer.compare(this.size, other.size);
        }
    }

    /**
     * Handles the core logic of identifying components and modifying the grid.
     */
    private static class GridSolver {
        private final int rows;
        private final int cols;
        private final int maxComponentsAllowed;
        private final char[][] grid;

        GridSolver(int rows, int cols, int maxComponentsAllowed, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.maxComponentsAllowed = maxComponentsAllowed;
            this.grid = grid;
        }

        /**
         * Executes the logic: finds components, sorts them by size, 
         * and removes the smallest ones if necessary.
         */
        public void solve(PrintWriter out) {
            List<Component> components = findComponents();

            // Sort components by size ascending (smallest first)
            Collections.sort(components);

            int totalRemovedCells = 0;
            int numToRemove = Math.max(0, components.size() - maxComponentsAllowed);

            // Convert the smallest 'numToRemove' components into '*'
            for (int i = 0; i < numToRemove; i++) {
                Component comp = components.get(i);
                totalRemovedCells += comp.size;
                for (Point p : comp.cells) {
                    grid[p.r][p.c] = '*';
                }
            }

            // Print the count of removed cells and the updated grid
            out.println(totalRemovedCells);
            for (int i = 0; i < rows; i++) {
                out.println(new String(grid[i]));
            }
        }

        /**
         * Scans the grid to find all disjoint connected components of '.' cells.
         */
        private List<Component> findComponents() {
            List<Component> components = new ArrayList<>();
            boolean[][] visited = new boolean[rows][cols];

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.' && !visited[i][j]) {
                        components.add(bfs(i, j, visited));
                    }
                }
            }
            return components;
        }

        /**
         * Uses Breadth-First Search to traverse a single component.
         */
        private Component bfs(int startR, int startC, boolean[][] visited) {
            List<Point> componentCells = new ArrayList<>();
            Queue<Point> queue = new LinkedList<>();

            Point start = new Point(startR, startC);
            queue.add(start);
            visited[startR][startC] = true;

            // Direction vectors for 4-connectivity (Up, Down, Left, Right)
            int[] dr = {1, -1, 0, 0};
            int[] dc = {0, 0, 1, -1};

            while (!queue.isEmpty()) {
                Point curr = queue.poll();
                componentCells.add(curr);

                for (int i = 0; i < 4; i++) {
                    int nr = curr.r + dr[i];
                    int nc = curr.c + dc[i];

                    if (isValid(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        queue.add(new Point(nr, nc));
                    }
                }
            }
            return new Component(componentCells);
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * Optimized reader for faster input processing.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

