/**
 * Manages the grid state and provides bounds-checked access.
 */
class Grid {
    private final int rows;
    private final int cols;
    private final char[][] map;
    private final boolean[][] visited;

    private static final char EMPTY = '.';
    private static final char FILLED = '*';

    public Grid(int rows, int cols, char[][] map) {
        this.rows = rows;
        this.cols = cols;
        this.map = map;
        this.visited = new boolean[rows][cols];
    }

    public int getRows() { return rows; }
    public int getCols() { return cols; }

    public boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    public boolean isEmpty(int r, int c) {
        return isWithinBounds(r, c) && map[r][c] == EMPTY;
    }

    public boolean isVisited(int r, int c) {
        return visited[r][c];
    }

    public void markVisited(int r, int c) {
        visited[r][c] = true;
    }

    public void fillCell(int r, int c) {
        map[r][c] = FILLED;
    }

    public char getCell(int r, int c) {
        return map[r][c];
    }

    public void printGrid(PrintWriter out) {
        for (int r = 0; r < rows; r++) {
            out.println(new String(map[r]));
        }
    }
}

/**
 * Logic for identifying and filling lakes.
 */
class LakeSolver {
    private static final int[] ROW_OFFSETS = {0, 0, -1, 1};
    private static final int[] COL_OFFSETS = {-1, 1, 0, 0};

    private final FastReader reader;

    public LakeSolver(FastReader reader) {
        this.reader = reader;
    }

    public void solve(PrintWriter out) {
        int numRows = reader.nextInt();
        int numCols = reader.nextInt();
        int targetNumLakes = reader.nextInt();

        char[][] mapData = new char[numRows][];
        for (int i = 0; i < numRows; i++) {
            mapData[i] = reader.next().toCharArray();
        }

        Grid grid = new Grid(numRows, numCols, mapData);

        // 1. Mark all '.' connected to the edges as visited (these are not lakes, but "sea")
        markBoundaryConnectedCells(grid);

        // 2. Find all enclosed '.' components (lakes)
        List<Lake> lakes = findLakes(grid);

        // 3. Sort lakes by area (ascending) and fill the smallest ones
        Collections.sort(lakes);

        int numLakesToFill = lakes.size() - targetNumLakes;
        int totalFilledArea = 0;

        for (int i = 0; i < numLakesToFill; i++) {
            Lake lake = lakes.get(i);
            totalFilledArea += fillLake(grid, lake.getStartRow(), lake.getStartCol());
        }

        out.println(totalFilledArea);
        grid.printGrid(out);
    }

    private void markBoundaryConnectedCells(Grid grid) {
        for (int r = 0; r < grid.getRows(); r++) {
            for (int c : new int[]{0, grid.getCols() - 1}) {
                if (grid.isEmpty(r, c) && !grid.isVisited(r, c)) {
                    traverse(grid, r, c, true);
                }
            }
        }
        for (int c = 0; c < grid.getCols(); c++) {
            for (int r : new int[]{0, grid.getRows() - 1}) {
                if (grid.isEmpty(r, c) && !grid.isVisited(r, c)) {
                    traverse(grid, r, c, true);
                }
            }
        }
    }

    private List<Lake> findLakes(Grid grid) {
        List<Lake> lakes = new ArrayList<>();
        // Lakes are strictly inside the boundaries
        for (int r = 1; r < grid.getRows() - 1; r++) {
            for (int c = 1; c < grid.getCols() - 1; c++) {
                if (grid.isEmpty(r, c) && !grid.isVisited(r, c)) {
                    int area = traverse(grid, r, c, false);
                    lakes.add(new Lake(r, c, area));
                }
            }
        }
        return lakes;
    }

    /**
     * Generic DFS traversal. 
     * If 'markVisitedOnly' is true, it just marks cells (for boundary/sea logic).
     * If false, it returns the area of the component found.
     */
    private int traverse(Grid grid, int r, int c, boolean markVisitedOnly) {
        Stack<int[]> stack = new Stack<>();
        stack.push(new int[]{r, c});
        grid.markVisited(r, c);

        int count = 0;

        while (!stack.isEmpty()) {
            int[] curr = stack.pop();
            int currR = curr[0];
            int currC = curr[1];
            count++;

            for (int i = 0; i < 4; i++) {
                int nr = currR + ROW_OFFSETS[i];
                int nc = currC + COL_OFFSETS[i];

                if (grid.isWithinBounds(nr, nc) && grid.isEmpty(nr, nc) && !grid.isVisited(nr, nc)) {
                    grid.markVisited(nr, nc);
                    stack.push(new int[]{nr, nc});
                }
            }
        }
        return count;
    }

    private int fillLake(Grid grid, int r, int c) {
        // Using a simple DFS to turn '.' into '*'
        // We don't need a visited array here because we change the cell type
        int area = 0;
        Stack<int[]> stack = new Stack<>();
        stack.push(new int[]{r, c});
        grid.fillCell(r, c);
        area++;

        while (!stack.isEmpty()) {
            int[] curr = stack.pop();
            for (int i = 0; i < 4; i++) {
                int nr = curr[0] + ROW_OFFSETS[i];
                int nc = curr[1] + COL_OFFSETS[i];
                if (grid.isEmpty(nr, nc)) {
                    grid.fillCell(nr, nc);
                    area++;
                    stack.push(new int[]{nr, nc});
                }
            }
        }
        return area;
    }
}

