        return Integer.compare(this.size, other.size);
    }
}

/**
 * Handles the logic for identifying and removing land components based on 
 * boundary connectivity and target island counts.
 */
class IslandSolver {
    private static final char LAND = '.';
    private static final char VISITED = 'v';
    private static final char REMOVED = '*';
    private static final int[][] DIRECTIONS = {{0, 1}, {1, 0}, {-1, 0}, {0, -1}};

    private final char[][] grid;
    private final int rows;
    private final int cols;

    public IslandSolver(char[][] grid, int rows, int cols) {
        this.grid = grid;
        this.rows = rows;
        this.cols = cols;
    }

    /**
     * Executes the island processing logic.
     * 
     * @param targetInternalIslands The desired number of non-boundary islands to remain.
     * @return The total number of cells replaced with the REMOVED character.
     */
    public int solve(int targetInternalIslands) {
        // 1. Identify and mark land connected to the grid boundaries.
        markBoundaryLand();

        // 2. Identify all internal land components and store them.
        List<Island> internalIslands = findAndMarkInternalIslands();
        int currentInternalCount = internalIslands.size();

        // Sort islands by size to match the original requirement of removing smallest islands first.
        Collections.sort(internalIslands);

        int totalRemovedCells = 0;
        for (Island island : internalIslands) {
            // If we have reached the target number of internal islands, stop removing.
            if (currentInternalCount == targetInternalIslands) {
                break;
            }

            totalRemovedCells += removeIsland(island.getRow(), island.getCol());
            currentInternalCount--;
        }

        // 3. Convert boundary-marked land back to its original state.
        restoreBoundaryLand();

        return totalRemovedCells;
    }

    private void markBoundaryLand() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (isAtBoundary(r, c) && grid[r][c] == LAND) {
                    floodFill(r, c, VISITED, LAND);
                }
            }
        }
    }

    private List<Island> findAndMarkInternalIslands() {
        List<Island> islands = new ArrayList<>();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == LAND) {
                    int size = floodFill(r, c, VISITED, LAND);
                    islands.add(new Island(size, r, c));
                }
            }
        }
        return islands;
    }

    private int removeIsland(int r, int c) {
        // Internal islands were marked with VISITED during discovery.
        return floodFill(r, c, REMOVED, VISITED);
    }

    private void restoreBoundaryLand() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == VISITED) {
                    grid[r][c] = LAND;
                }
            }
        }
    }

    private boolean isAtBoundary(int r, int c) {
        return r == 0 || r == rows - 1 || c == 0 || c == cols - 1;
    }

    /**
     * Standard recursive flood-fill to traverse connected components.
     * 
     * @param r Starting row.
     * @param c Starting column.
     * @param marker The character to mark the visited cells with.
     * @param target The character we are looking to traverse.
     * @return The number of cells in the component.
     */
    private int floodFill(int r, int c, char marker, char target) {
        if (r < 0 || r >= rows || c < 0 || c >= cols || grid[r][c] != target) {
            return 0;
        }

        grid[r][c] = marker;
        int count = 1;

        for (int[] dir : DIRECTIONS) {
            count += floodFill(r + dir[0], c + dir[1], marker, target);
        }

        return count;
    }
}

import java.util.*;

/**
 * A program that identifies isolated components of '.' in a grid,
 * keeps the k largest components, and replaces the smaller components with '*'.
 * Boundary-connected '.' cells are treated differently and remain untouched.
 */
public class Main {

    public static void main(String[] args) {
        GridProcessor processor = new GridProcessor(System.in);
        processor.run();
    }
}

class GridProcessor {
    private final Scanner scanner;

    // Directions for 4-way adjacency (Up, Right, Down, Left)
    private static final int[][] DIRECTIONS = {
        {1, 0}, {0, 1}, {-1, 0}, {0, -1}
    };

    private int rows;
    private int cols;
    private int keepK;

    private char[][] displayGrid;
    private char[][] workingGrid;
    private int[][] componentIds;

    public GridProcessor(java.io.InputStream inputStream) {
        this.scanner = new Scanner(inputStream);
    }

    /**
     * Main execution flow.
     */
    public void run() {
        if (!readInput()) return;

        prepareWorkingGrid();
        identifyComponents();
        processResults();
    }

    private boolean readInput() {
        if (!scanner.hasNextInt()) return false;
        rows = scanner.nextInt();
        cols = scanner.nextInt();
        keepK = scanner.nextInt();
        scanner.nextLine(); // Consume newline

        displayGrid = new char[rows][cols];
        workingGrid = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            String line = scanner.nextLine();
            for (int j = 0; j < cols; j++) {
                char c = line.charAt(j);
                displayGrid[i][j] = c;
                workingGrid[i][j] = c;
            }
        }
        return true;
    }

    /**
     * Marks all '.' cells connected to the grid boundaries as '*'.
     * This ensures only "enclosed" components are processed.
     */
    private void prepareWorkingGrid() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                boolean isBoundary = (i == 0 || i == rows - 1 || j == 0 || j == cols - 1);
                if (isBoundary && workingGrid[i][j] == '.') {
                    floodFill(i, j, '*');
                }
            }
        }
    }

    /**
     * Finds all remaining '.' components in the working grid and assigns them IDs.
     */
    private void identifyComponents() {
        componentIds = new int[rows][cols];
        int currentId = 1;

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (workingGrid[i][j] == '.' && componentIds[i][j] == 0) {
                    assignComponentId(i, j, currentId);
                    currentId++;
                }
            }
        }
    }

    private void assignComponentId(int r, int c, int id) {
        // Using a stack for iterative DFS to prevent StackOverflowError on large grids
        Stack<int[]> stack = new Stack<>();
        stack.push(new int[]{r, c});
        componentIds[r][c] = id;

        while (!stack.isEmpty()) {
            int[] curr = stack.pop();
            int currR = curr[0];
            int currC = curr[1];

            for (int[] dir : DIRECTIONS) {
                int nr = currR + dir[0];
                int nc = currC + dir[1];

                if (isValid(nr, nc) && workingGrid[nr][nc] == '.' && componentIds[nr][nc] == 0) {
                    componentIds[nr][nc] = id;
                    stack.push(new int[]{nr, nc});
                }
            }
        }
    }

    private void floodFill(int r, int c, char targetChar) {
        Stack<int[]> stack = new Stack<>();
        stack.push(new int[]{r, c});
        workingGrid[r][c] = targetChar;

        while (!stack.isEmpty()) {
            int[] curr = stack.pop();
            for (int[] dir : DIRECTIONS) {
                int nr = curr[0] + dir[0];
                int nc = curr[1] + dir[1];
                if (isValid(nr, nc) && workingGrid[nr][nc] == '.') {
                    workingGrid[nr][nc] = targetChar;
                    stack.push(new int[]{nr, nc});
                }
            }
        }
    }

    /**
     * Sorts components by size, removes the smallest ones, and prints output.
     */
    private void processResults() {
        int maxId = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                maxId = Math.max(maxId, componentIds[i][j]);
            }
        }

        // Count sizes of each component
        int[] componentSizes = new int[maxId + 1];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int id = componentIds[i][j];
                if (id > 0) {
                    componentSizes[id]++;
                }
            }
        }

        // Create list of components for sorting
        List<Component> components = new ArrayList<>();
        for (int i = 1; i <= maxId; i++) {
            if (componentSizes[i] > 0) {
                components.add(new Component(i, componentSizes[i]));
            }
        }
        Collections.sort(components);

        // Identify components to remove (the smallest ones)
        int numToRemove = Math.max(0, components.size() - keepK);
        int totalRemovedCells = 0;
        Set<Integer> idsToRemove = new HashSet<>();

        for (int i = 0; i < numToRemove; i++) {
            Component comp = components.get(i);
            totalRemovedCells += comp.size;
            idsToRemove.add(comp.id);
        }

        // Update the display grid
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (idsToRemove.contains(componentIds[i][j])) {
                    displayGrid[i][j] = '*';
                }
            }
        }

        printOutput(totalRemovedCells);
    }

    private void printOutput(int totalRemoved) {
        System.out.println(totalRemoved);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                sb.append(displayGrid[i][j]);
            }
            sb.append("\n");
        }
        System.out.print(sb.toString());
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Represents a connected component of '.' cells.
     */
    private static class Component implements Comparable<Component> {
        final int id;
        final int size;

        Component(int id, int size) {
            this.id = id;
            this.size = size;
        }

        @Override
        public int compareTo(Component other) {
            return Integer.compare(this.size, other.size);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Problem: Grid Component Optimizer
 * Goal: Minimize the number of '.' cells by converting up to K connected 
 * components of '.' into '*' (obstacles), provided the components 
 * do not touch the grid boundaries.
 */
public class GridOptimizer {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            int k = reader.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            solve(rows, cols, k, grid, writer);
        } catch (Exception e) {
            // Handle or log potential input errors
        } finally {
            writer.close();
        }
    }

    /**
     * Core logic to identify components and optimize the grid.
     */
    private static void solve(int rows, int cols, int k, char[][] grid, PrintWriter out) {
        boolean[][] visited = new boolean[rows][cols];
        List<Component> innerComponents = new ArrayList<>();
        int totalDotsRemoved = 0;

        // 1. Identify all connected components of '.'
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && !visited[r][c]) {
                    Component component = findComponentViaBFS(r, c, grid, visited, rows, cols);

                    // 2. Only consider components that do not touch the grid boundaries
                    if (!component.touchesBoundary()) {
                        innerComponents.add(component);
                    }
                }
            }
        }

        // 3. Sort inner components by size in descending order 
        // to maximize the number of dots removed.
        innerComponents.sort((a, b) -> Integer.compare(b.size(), a.size()));

        // 4. Convert up to K largest inner components into obstacles '*'
        int componentsToConvert = Math.min(k, innerComponents.size());
        for (int i = 0; i < componentsToConvert; i++) {
            Component comp = innerComponents.get(i);
            for (Point p : comp.getPoints()) {
                grid[p.row][p.col] = '*';
            }
            totalDotsRemoved += comp.size();
        }

        // 5. Output result
        out.println(totalDotsRemoved);
        for (int r = 0; r < rows; r++) {
            out.println(new String(grid[r]));
        }
    }

    /**
     * Performs an iterative BFS to find all cells in a connected component.
     */
    private static Component findComponentViaBFS(int startR, int startC, char[][] grid, 
                                                boolean[][] visited, int rows, int cols) {
        List<Point> componentPoints = new ArrayList<>();
        Deque<Point> queue = new ArrayDeque<>();
        boolean touchesBoundary = false;

        Point start = new Point(startR, startC);
        queue.add(start);
        visited[startR][startC] = true;

        // Directions for 4-connectivity (Up, Down, Left, Right)
        int[] dr = {0, 0, 1, -1};
        int[] dc = {1, -1, 0, 0};

        while (!queue.isEmpty()) {
            Point current = queue.poll();
            componentPoints.add(current);

            // Check if this cell is on the boundary
            if (current.row == 0 || current.row == rows - 1 || 
                current.col == 0 || current.col == cols - 1) {
                touchesBoundary = true;
            }

            for (int i = 0; i < 4; i++) {
                int nr = current.row + dr[i];
                int nc = current.col + dc[i];

                if (isValid(nr, nc, rows, cols) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    queue.add(new Point(nr, nc));
                }
            }
        }

        return new Component(componentPoints, touchesBoundary);
    }

    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Represents a single coordinate in the grid.
     */
    static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Represents a collection of connected cells.
     */
    static class Component {
        private final List<Point> points;
        private final boolean touchesBoundary;

        Component(List<Point> points, boolean touchesBoundary) {
            this.points = points;
            this.touchesBoundary = touchesBoundary;
        }

        int size() {
            return points.size();
        }

        boolean touchesBoundary() {
            return touchesBoundary;
        }

        List<Point> getPoints() {
            return points;
        }
    }

    /**
     * Efficient input reader for large datasets.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored Grid Component Processor.
 * This version is memory-efficient, avoids recursion, and follows Clean Code principles.
 */
public class Main {

    public static void main(String[] args) {
        FastReader sc = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = sc.nextInt();
            int m = sc.nextInt();
            int k = sc.nextInt();

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                String line = sc.next();
                grid[i] = line.toCharArray();
            }

            solve(n, m, k, grid, out);
        } catch (Exception e) {
            // In a real-world app, use a logger
        } finally {
            out.close();
        }
    }

    private static void solve(int rows, int cols, int k, char[][] grid, PrintWriter out) {
        GridProcessor processor = new GridProcessor(rows, cols, grid);
        List<Component> allComponents = processor.findComponents();

        // Filter components that are "internal" (do not touch the boundary)
        List<Component> internalComponents = new ArrayList<>();
        for (Component comp : allComponents) {
            if (comp.isInternal) {
                internalComponents.add(comp);
            }
        }

        // Sort internal components by size ascending
        internalComponents.sort(Comparator.comparingInt(c -> c.size));

        // The logic from the original code:
        // Turn (internalComponents.size() - k) smallest components into '*'
        int numToTurn = Math.max(0, internalComponents.size() - k);
        long totalDotsTurned = 0;

        for (int i = 0; i < numToTurn; i++) {
            Component comp = internalComponents.get(i);
            totalDotsTurned += comp.size;
            processor.turnComponentToAsterisk(comp.startRow, comp.startCol);
        }

        out.println(totalDotsTurned);
        for (int i = 0; i < rows; i++) {
            out.println(new String(grid[i]));
        }
    }

    static class Component {
        int startRow, startCol, size;
        boolean isInternal;

        public Component(int r, int c, int size, boolean isInternal) {
            this.startRow = r;
            this.startCol = c;
            this.size = size;
            this.isInternal = isInternal;
        }
    }

    static class GridProcessor {
        private final int rows, cols;
        private final char[][] grid;
        private final boolean[][] visited;
        private static final int[] DR = {-1, 1, 0, 0};
        private static final int[] DC = {0, 0, -1, 1};

        public GridProcessor(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            this.visited = new boolean[rows][cols];
        }

        public List<Component> findComponents() {
            List<Component> components = new ArrayList<>();
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.' && !visited[i][j]) {
                        components.add(bfs(i, j));
                    }
                }
            }
            return components;
        }

        private Component bfs(int startR, int startC) {
            Queue<int[]> queue = new LinkedList<>();
            queue.add(new int[]{startR, startC});
            visited[startR][startC] = true;

            int size = 0;
            boolean isInternal = true;

            while (!queue.isEmpty()) {
                int[] curr = queue.poll();
                int r = curr[0];
                int c = curr[1];
                size++;

                if (r == 0 || r == rows - 1 || c == 0 || c == cols - 1) {
                    isInternal = false;
                }

                for (int i = 0; i < 4; i++) {
                    int nr = r + DR[i];
                    int nc = c + DC[i];

                    if (isValid(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        queue.add(new int[]{nr, nc});
                    }
                }
            }
            return new Component(startR, startC, size, isInternal);
        }

        public void turnComponentToAsterisk(int startR, int startC) {
            Queue<int[]> queue = new LinkedList<>();
            queue.add(new int[]{startR, startC});
            grid[startR][startC] = '*';

            while (!queue.isEmpty()) {
                int[] curr = queue.poll();
                for (int i = 0; i < 4; i++) {
                    int nr = curr[0] + DR[i];
                    int nc = curr[1] + DC[i];
                    if (isValid(nr, nc) && grid[nr][nc] == '.') {
                        grid[nr][nc] = '*';
                        queue.add(new int[]{nr, nc});
                    }
                }
            }
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A refactored solution to identify connected components in a grid,
 * categorize them by their proximity to boundaries, and modify the grid
 * based on size-based constraints.
 */
public class Main {

    public static void main(String[] args) {
        try {
            GridSolver solver = new GridSolver(System.in, System.out);
            solver.solve();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

class GridSolver {
    private static final int EMPTY = 0;
    private static final int WALL = 1;

    private final int rows;
    private final int cols;
    private final int k;
    private final int[][] grid;
    private final FastReader reader;
    private final PrintWriter out;

    // Directions for 4-connectivity (Up, Right, Down, Left)
    private static final int[] DR = {1, 0, -1, 0};
    private static final int[] DC = {0, 1, 0, -1};

    public GridSolver(InputStream in, OutputStream out) throws IOException {
        this.reader = new FastReader(in);
        this.out = new PrintWriter(new OutputStreamWriter(out));

        this.rows = reader.nextInt();
        this.cols = reader.nextInt();
        this.k = reader.nextInt();
        this.grid = new int[rows][cols];

        for (int i = 0; i < rows; i++) {
            String line = reader.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = (line.charAt(j) == '*') ? WALL : EMPTY;
            }
        }
    }

    /**
     * Main logic to find components, sort them, and apply transformations.
     */
    public void solve() throws IOException {
        List<Component> allComponents = findComponents();

        // Identify "safe" components (those that do not touch the grid boundary)
        List<Component> safeComponents = new ArrayList<>();
        for (Component comp : allComponents) {
            if (!comp.isBoundary) {
                safeComponents.add(comp);
            }
        }

        // Sort safe components by size ascending
        Collections.sort(safeComponents);

        int cellsChanged = 0;
        int remainingSafeCount = safeComponents.size();

        // The logic dictates we keep the K largest safe components.
        // We convert the smallest safe components into walls until only K remain.
        for (Component comp : safeComponents) {
            if (remainingSafeCount <= k) {
                break;
            }

            // Convert component to walls
            for (Point p : comp.cells) {
                grid[p.r][p.c] = WALL;
                cellsChanged++;
            }
            remainingSafeCount--;
        }

        printResult(cellsChanged);
        out.flush();
        out.close();
    }

    /**
     * Finds all connected components of EMPTY cells using BFS.
     * @return A list of all found components.
     */
    private List<Component> findComponents() {
        List<Component> components = new ArrayList<>();
        boolean[][] visited = new boolean[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == EMPTY && !visited[r][c]) {
                    components.add(bfs(r, c, visited));
                }
            }
        }
        return components;
    }

    private Component bfs(int startR, int startC, boolean[][] visited) {
        List<Point> componentCells = new ArrayList<>();
        Deque<Point> queue = new ArrayDeque<>();

        Point start = new Point(startR, startC);
        queue.add(start);
        visited[startR][startC] = true;

        boolean touchesBoundary = false;

        while (!queue.isEmpty()) {
            Point curr = queue.poll();
            componentCells.add(curr);

            // Check if this cell is on the boundary
            if (curr.r == 0 || curr.r == rows - 1 || curr.c == 0 || curr.c == cols - 1) {
                touchesBoundary = true;
            }

            for (int i = 0; i < 4; i++) {
                int nr = curr.r + DR[i];
                int nc = curr.c + DC[i];

                if (isValid(nr, nc) && grid[nr][nc] == EMPTY && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    queue.add(new Point(nr, nc));
                }
            }
        }

        return new Component(componentCells, touchesBoundary);
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private void printResult(int changedCount) {
        out.println(changedCount);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < rows; i++) {
            sb.setLength(0);
            for (int j = 0; j < cols; j++) {
                sb.append(grid[i][j] == WALL ? '*' : '.');
            }
            out.println(sb.toString());
        }
    }

    /**
     * Represents a single cell in the grid.
     */
    private static class Point {
        final int r, c;
        Point(int r, int c) { this.r = r; this.c = c; }
    }

    /**
     * Represents a connected component of cells.
     */
    private static class Component implements Comparable<Component> {
        final List<Point> cells;
        final int size;
        final boolean isBoundary;

        Component(List<Point> cells, boolean isBoundary) {
            this.cells = cells;
            this.size = cells.size();
            this.isBoundary = isBoundary;
        }

        @Override
        public int compareTo(Component other) {
            return Integer.compare(this.size, other.size);
        }
    }

    /**
     * Fast I/O utility class.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

