/**
 * Refactored program to find the minimum number of changes to reduce 
 * the number of internal connected components in a grid to at most K.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        GridSolver solver = new GridSolver(reader);
        solver.solve(writer);

        writer.close();
    }

    /**
     * Represents a single cell in the grid.
     */
    static class Point {
        final int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Represents a connected component of '.' cells.
     */
    static class Component {
        final List<Point> points;
        final boolean isBorderComponent;

        Component(List<Point> points, boolean isBorderComponent) {
            this.points = points;
            this.isBorderComponent = isBorderComponent;
        }

        int size() {
            return points.size();
        }
    }

    /**
     * Handles the logic of parsing the grid, finding components, 
     * and applying the required transformations.
     */
    static class GridSolver {
        private final int rows;
        private final int cols;
        private final int k;
        private final char[][] grid;
        private final boolean[][] visited;

        private static final int[] DR = {-1, 1, 0, 0};
        private static final int[] DC = {0, 0, -1, 1};

        public GridSolver(FastReader reader) {
            this.rows = reader.nextInt();
            this.cols = reader.nextInt();
            this.k = reader.nextInt();
            this.grid = new char[rows][cols];
            this.visited = new boolean[rows][cols];

            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }
        }

        /**
         * Executes the primary solving algorithm.
         */
        public void solve(PrintWriter out) {
            List<Component> internalComponents = new ArrayList<>();

            // Identify all connected components
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.' && !visited[i][j]) {
                        Component comp = findComponentBFS(i, j);
                        // Only track components that do not touch the grid border
                        if (!comp.isBorderComponent) {
                            internalComponents.add(comp);
                        }
                    }
                }
            }

            // Sort internal components by size (ascending) to minimize changes
            internalComponents.sort(Comparator.comparingInt(Component::size));

            int changes = 0;
            int numToRemove = Math.max(0, internalComponents.size() - k);

            // Flip the smallest components into '*' until target count is met
            for (int i = 0; i < numToRemove; i++) {
                for (Point p : internalComponents.get(i).points) {
                    grid[p.r][p.c] = '*';
                    changes++;
                }
            }

            // Output results
            out.println(changes);
            for (int i = 0; i < rows; i++) {
                out.println(new String(grid[i]));
            }
        }

        /**
         * Finds a connected component using Breadth-First Search.
         */
        private Component findComponentBFS(int startR, int startC) {
            List<Point> componentPoints = new ArrayList<>();
            Queue<Point> queue = new LinkedList<>();
            boolean isBorder = false;

            Point start = new Point(startR, startC);
            queue.add(start);
            visited[startR][startC] = true;

            while (!queue.isEmpty()) {
                Point curr = queue.poll();
                componentPoints.add(curr);

                // Check if the current cell is on the boundary
                if (curr.r == 0 || curr.r == rows - 1 || curr.c == 0 || curr.c == cols - 1) {
                    isBorder = true;
                }

                // Explore 4-directional neighbors
                for (int i = 0; i < 4; i++) {
                    int nr = curr.r + DR[i];
                    int nc = curr.c + DC[i];

                    if (isValid(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        queue.add(new Point(nr, nc));
                    }
                }
            }
            return new Component(componentPoints, isBorder);
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * High-performance input reader.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

