/**
 * Represents a coordinate point in the 2D grid.
 */
class Point {
    final int x;
    final int y;

    Point(int x, int y) {
        this.x = x;
        this.y = y;
    }
}

/**
 * Represents an isolated island of '.' cells.
 * Implements Comparable to allow sorting by size.
 */
class Island implements Comparable<Island> {
    final int size;
    final List<Point> points;

    Island(List<Point> points) {
        this.points = points;
        this.size = points.size();
    }

    @Override
    public int compareTo(Island other) {
        // Sort in ascending order (smallest islands first)
        return Integer.compare(this.size, other.size);
    }
}

/**
 * Logic handler for the grid processing task.
 */
class GridSolver {
    private static final int[] DX = {-1, 1, 0, 0};
    private static final int[] DY = {0, 0, -1, 1};

    private final int rows;
    private final int cols;
    private final int k;
    private final char[][] grid;
    private final boolean[][] isSafe; // True if cell is connected to the boundary

    public GridSolver(int rows, int cols, int k, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.k = k;
        this.grid = grid;
        this.isSafe = new boolean[rows][cols];
    }

    /**
     * Orchestrates the solver logic.
     */
    public void solve(PrintWriter out) {
        // 1. Identify all '.' cells that can reach the boundary
        markSafeCells();

        // 2. Find all isolated islands ('.' cells not marked as safe)
        List<Island> islands = findIslands();

        // 3. Sort islands by size (ascending) to remove the smallest ones first
        Collections.sort(islands);

        int totalRemovedCells = 0;
        int remainingIslands = islands.size();
        int islandIndex = 0;

        // 4. Remove islands until we have at most K islands left
        while (remainingIslands > k && islandIndex < islands.size()) {
            Island island = islands.get(islandIndex++);
            totalRemovedCells += island.size;
            applyIslandRemoval(island);
            remainingIslands--;
        }

        // 5. Output the result
        out.println(totalRemovedCells);
        for (int i = 0; i < rows; i++) {
            out.println(new String(grid[i]));
        }
        out.flush();
    }

    /**
     * Marks '.' cells that are reachable from the boundary as "safe".
     */
    private void markSafeCells() {
        Deque<Point> queue = new ArrayDeque<>();

        // Start BFS from all '.' cells on the perimeter
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (isPerimeter(r, c) && grid[r][c] == '.' && !isSafe[r][c]) {
                    isSafe[r][c] = true;
                    queue.offer(new Point(r, c));
                }
            }
        }

        // Standard BFS to propagate "safeness"
        while (!queue.isEmpty()) {
            Point curr = queue.poll();
            for (int i = 0; i < 4; i++) {
                int nr = curr.x + DX[i];
                int nc = curr.y + DY[i];

                if (isValid(nr, nc) && grid[nr][nc] == '.' && !isSafe[nr][nc]) {
                    isSafe[nr][nc] = true;
                    queue.offer(new Point(nr, nc));
                }
            }
        }
    }

    /**
     * Scans the grid to find all components of '.' cells that are not safe.
     */
    private List<Island> findIslands() {
        List<Island> islands = new ArrayList<>();
        boolean[][] visited = new boolean[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                // An island is a '.' cell that is not safe and hasn't been visited
                if (grid[r][c] == '.' && !isSafe[r][c] && !visited[r][c]) {
                    islands.add(bfsForIsland(r, c, visited));
                }
            }
        }
        return islands;
    }

    /**
     * Uses BFS to find all cells belonging to a single isolated island.
     */
    private Island bfsForIsland(int startR, int startC, boolean[][] visited) {
        List<Point> islandPoints = new ArrayList<>();
        Deque<Point> queue = new ArrayDeque<>();

        Point start = new Point(startR, startC);
        queue.offer(start);
        visited[startR][startC] = true;

        while (!queue.isEmpty()) {
            Point curr = queue.poll();
            islandPoints.add(curr);

            for (int i = 0; i < 4; i++) {
                int nr = curr.x + DX[i];
                int nc = curr.y + DY[i];

                if (isValid(nr, nc) && grid[nr][nc] == '.' && !isSafe[nr][nc] && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    queue.offer(new Point(nr, nc));
                }
            }
        }
        return new Island(islandPoints);
    }

    /**
     * Converts all cells of a given island into obstacles ('*').
     */
    private void applyIslandRemoval(Island island) {
        for (Point p : island.points) {
            grid[p.x][p.y] = '*';
        }
    }

    private boolean isPerimeter(int r, int c) {
        return r == 0 || r == rows - 1 || c == 0 || c == cols - 1;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

