import java.io.*;

/**
 * A refactored solution to identify and manage connected components in a grid.
 * The goal is to keep all components touching the grid boundary and the 'k' largest 
 * internal components, while converting the remaining smallest internal components into walls ('*').
 */
public class GridComponentSolver {

    // A sentinel value to represent the size of components that touch the boundary.
    private static final long BOUNDARY_SIZE = Integer.MAX_VALUE;

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            String line1 = reader.next();
            if (line1 == null) return;

            int n = Integer.parseInt(line1);
            int m = reader.nextInt();
            int k = reader.nextInt();

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                grid[i] = reader.next().toCharArray();
            }

            solve(n, m, k, grid, out);
        } catch (Exception e) {
            // In a production environment, replace with a proper logging framework.
        } finally {
            out.close();
        }
    }

    /**
     * Core logic to find components, sort them, and modify the grid.
     */
    private static void solve(int n, int m, int k, char[][] grid, PrintWriter out) {
        boolean[][] visited = new boolean[n][m];
        List<Component> components = new ArrayList<>();

        // 1. Discover all connected components of '.' cells using iterative DFS.
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.' && !visited[i][j]) {
                    components.add(findComponent(i, j, n, m, grid, visited));
                }
            }
        }

        // 2. Sort components by size in ascending order.
        // Boundary components (size = BOUNDARY_SIZE) will naturally sort to the end.
        Collections.sort(components, Comparator.comparingLong(c -> c.size));

        // 3. Identify how many components are boundary components.
        int boundaryCount = 0;
        for (Component comp : components) {
            if (comp.size == BOUNDARY_SIZE) {
                boundaryCount++;
            }
        }

        // 4. Calculate the number of internal components to remove.
        // We want to keep all boundary components and the top 'k' largest internal components.
        int internalCount = components.size() - boundaryCount;
        int numToKeepInternal = Math.min(k, internalCount);
        int numToRemove = Math.max(0, components.size() - boundaryCount - numToKeepInternal);

        // 5. Remove the smallest components.
        long totalRemovedSize = 0;
        for (int i = 0; i < numToRemove; i++) {
            Component comp = components.get(i);
            totalRemovedSize += comp.size;
            fillComponentWithWalls(comp.cells, grid);
        }

        // 6. Output the sum of removed sizes and the resulting grid.
        out.println(totalRemovedSize);
        for (int i = 0; i < n; i++) {
            out.println(new String(grid[i]));
        }
    }

    /**
     * Performs an iterative DFS to find all cells in a connected component.
     */
    private static Component findComponent(int startR, int startC, int n, int m, char[][] grid, boolean[][] visited) {
        List<Point> componentCells = new ArrayList<>();
        Deque<Point> stack = new ArrayDeque<>();

        stack.push(new Point(startR, startC));
        visited[startR][startC] = true;

        boolean touchesBoundary = false;
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        while (!stack.isEmpty()) {
            Point curr = stack.pop();
            componentCells.add(curr);

            // Check if the current cell is on the edge of the grid.
            if (curr.r == 0 || curr.r == n - 1 || curr.c == 0 || curr.c == m - 1) {
                touchesBoundary = true;
            }

            for (int i = 0; i < 4; i++) {
                int nr = curr.r + dr[i];
                int nc = curr.c + dc[i];

                if (nr >= 0 && nr < n && nc >= 0 && nc < m && grid[nr][nc] == '.' && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    stack.push(new Point(nr, nc));
                }
            }
        }

        long size = touchesBoundary ? BOUNDARY_SIZE : componentCells.size();
        return new Component(componentCells, size);
    }

    /**
     * Converts the cells of a component into walls ('*').
     */
    private static void fillComponentWithWalls(List<Point> cells, char[][] grid) {
        for (Point p : cells) {
            grid[p.r][p.c] = '*';
        }
    }

    /**
     * Represents a single coordinate in the grid.
     */
    private static class Point {
        final int r, c;
        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Represents a connected component of '.' cells.
     */
    private static class Component {
        final List<Point> cells;
        final long size;

        Component(List<Point> cells, long size) {
            this.cells = cells;
            this.size = size;
        }
    }

    /**
     * Utility class for fast input reading.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

