class GridSolver {
    private static final int[][] DIRECTIONS = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

    private final char[][] grid;
    private final int rows;
    private final int cols;
    private final int targetLakeCount;
    private final boolean[][] visited;

    /**
     * Represents a coordinate in the grid.
     */
    private record Cell(int r, int c) {}

    /**
     * Represents a detected lake.
     */
    private record Lake(Cell representative, int size) implements Comparable<Lake> {
        @Override
        public int compareTo(Lake other) {
            // Sort descending by size to maximize the area filled
            return Integer.compare(other.size, this.size);
        }
    }

    public GridSolver(char[][] grid, int rows, int cols, int targetLakeCount) {
        this.grid = grid;
        this.rows = rows;
        this.cols = cols;
        this.targetLakeCount = targetLakeCount;
        this.visited = new boolean[rows][cols];
    }

    public void solve(PrintWriter writer) {
        // 1. Identify the ocean (water connected to boundaries)
        markOcean();

        // 2. Identify all isolated lakes
        List<Lake> lakes = findLakes();

        // 3. Fill the largest lakes until the lake count meets the target
        int filledCellsCount = fillLakes(lakes);

        // 4. Output results
        writer.println(filledCellsCount);
        for (int i = 0; i < rows; i++) {
            writer.println(new String(grid[i]));
        }
        writer.flush();
    }

    private void markOcean() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                // If cell is on boundary and is water, it's ocean
                boolean isBoundary = (i == 0 || i == rows - 1 || j == 0 || j == cols - 1);
                if (isBoundary && grid[i][j] == '.' && !visited[i][j]) {
                    floodFill(i, j, true);
                }
            }
        }
    }

    private List<Lake> findLakes() {
        List<Lake> lakes = new ArrayList<>();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.' && !visited[i][j]) {
                    int size = countLakeSize(i, j);
                    lakes.add(new Lake(new Cell(i, j), size));
                }
            }
        }
        return lakes;
    }

    private int countLakeSize(int startR, int startC) {
        int size = 0;
        Deque<Cell> queue = new ArrayDeque<>();

        queue.add(new Cell(startR, startC));
        visited[startR][startC] = true;

        while (!queue.isEmpty()) {
            Cell curr = queue.poll();
            size++;

            for (int[] dir : DIRECTIONS) {
                int nr = curr.r + dir[0];
                int nc = curr.c + dir[1];

                if (isValidWater(nr, nc)) {
                    visited[nr][nc] = true;
                    queue.add(new Cell(nr, nc));
                }
            }
        }
        return size;
    }

    private int fillLakes(List<Lake> lakes) {
        // Sort lakes by size descending
        Collections.sort(lakes);

        int currentLakeCount = lakes.size();
        int totalFilledCells = 0;

        // Reset visited to use it for the filling process
        for (boolean[] row : visited) Arrays.fill(row, false);

        for (Lake lake : lakes) {
            if (currentLakeCount > targetLakeCount) {
                // Fill the lake by turning '.' into '*'
                floodFill(lake.representative.r, lake.representative.c, true);
                totalFilledCells += lake.size;
                currentLakeCount--;
            } else {
                break;
            }
        }
        return totalFilledCells;
    }

    /**
     * Performs a DFS/BFS to fill water with land or mark ocean.
     * @param fillWithLand if true, changes '.' to '*'
     */
    private void floodFill(int startR, int startC, boolean fillWithLand) {
        Deque<Cell> stack = new ArrayDeque<>();
        stack.push(new Cell(startR, startC));
        visited[startR][startC] = true;

        if (fillWithLand) {
            grid[startR][startC] = '*';
        }

        while (!stack.isEmpty()) {
            Cell curr = stack.pop();

            for (int[] dir : DIRECTIONS) {
                int nr = curr.r + dir[0];
                int nc = curr.c + dir[1];

                if (isValidWater(nr, nc) && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    if (fillWithLand) {
                        grid[nr][nc] = '*';
                    }
                    stack.push(new Cell(nr, nc));
                }
            }
        }
    }

    private boolean isValidWater(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] == '.' && !visited[r][c];
    }
}

import java.io.*;
import java.util.*;

/**
 * LakeManager solves the problem of reducing the number of "lakes" (connected components of '.')
 * in a grid to a target number K by converting the smallest enclosed lakes into walls ('*').
 */
public class LakeManager {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            int targetLakeCount = reader.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            Solver solver = new Solver(rows, cols, grid);
            solver.solve(targetLakeCount, writer);

        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    /**
     * Represents a single coordinate in the grid.
     */
    private static record Cell(int r, int c) {}

    /**
     * Represents a connected component of '.' cells.
     */
    private static class Lake implements Comparable<Lake> {
        private final List<Cell> cells;
        private final boolean isEnclosed;

        public Lake(List<Cell> cells, boolean isEnclosed) {
            this.cells = cells;
            this.isEnclosed = isEnclosed;
        }

        public int size() {
            return cells.size();
        }

        public boolean isEnclosed() {
            return isEnclosed;
        }

        public List<Cell> getCells() {
            return cells;
        }

        @Override
        public int compareTo(Lake other) {
            return Integer.compare(this.size(), other.size());
        }
    }

    private static class Solver {
        private final int rows;
        private final int cols;
        private final char[][] grid;

        private static final int[] DR = {1, -1, 0, 0};
        private static final int[] DC = {0, 0, 1, -1};

        public Solver(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
        }

        public void solve(int k, PrintWriter writer) {
            boolean[][] visited = new boolean[rows][cols];
            List<Lake> allLakes = new ArrayList<>();

            // 1. Identify all connected components (lakes)
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.' && !visited[r][c]) {
                        allLakes.add(findLake(r, c, visited));
                    }
                }
            }

            // 2. Separate enclosed lakes (those not touching the border)
            List<Lake> enclosedLakes = new ArrayList<>();
            for (Lake lake : allLakes) {
                if (lake.isEnclosed()) {
                    enclosedLakes.add(lake);
                }
            }

            // 3. Sort enclosed lakes by size to minimize changes
            Collections.sort(enclosedLakes);

            // 4. Remove the smallest enclosed lakes until we reach K lakes
            int currentLakeCount = allLakes.size();
            int totalCellsChanged = 0;
            int enclosedIdx = 0;

            while (currentLakeCount > k && enclosedIdx < enclosedLakes.size()) {
                Lake lakeToFill = enclosedLakes.get(enclosedIdx++);
                totalCellsChanged += lakeToFill.size();
                for (Cell cell : lakeToFill.getCells()) {
                    grid[cell.r][cell.c] = '*';
                }
                currentLakeCount--;
            }

            // 5. Output results
            writer.println(totalCellsChanged);
            for (int r = 0; r < rows; r++) {
                writer.println(new String(grid[r]));
            }
        }

        /**
         * Uses BFS to find all cells in a component and determines if it is enclosed.
         */
        private Lake findLake(int startR, int startC, boolean[][] visited) {
            List<Cell> componentCells = new ArrayList<>();
            boolean isEnclosed = true;
            Deque<Cell> queue = new ArrayDeque<>();

            Cell start = new Cell(startR, startC);
            queue.add(start);
            visited[startR][startC] = true;

            while (!queue.isEmpty()) {
                Cell curr = queue.poll();
                componentCells.add(curr);

                // If the cell is on the boundary, the lake is not enclosed
                if (curr.r == 0 || curr.r == rows - 1 || curr.c == 0 || curr.c == cols - 1) {
                    isEnclosed = false;
                }

                for (int i = 0; i < 4; i++) {
                    int nr = curr.r + DR[i];
                    int nc = curr.c + DC[i];

                    if (isValid(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        queue.add(new Cell(nr, nc));
                    }
                }
            }
            return new Lake(componentCells, isEnclosed);
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * Utility class for fast I/O.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;

/**
 * A solution for the Berland Lakes problem.
 * Finds all lakes (water bodies not touching the edges) and buries the smallest ones
 * until only k lakes remain.
 */
public class LakesInBerlands {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        int k = scanner.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
            }
        }

        LakeSolver solver = new LakeSolver(grid, rows, cols);
        solver.solve(k);
        solver.printGrid();
    }

    /**
     * Represents a single coordinate on the grid.
     */
    static class Coordinate {
        final int r, c;

        Coordinate(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Represents a lake, containing all its constituent coordinates.
     */
    static class Lake implements Comparable<Lake> {
        private final List<Coordinate> cells;
        private final int size;

        Lake(List<Coordinate> cells) {
            this.cells = cells;
            this.size = cells.size();
        }

        public List<Coordinate> getCells() {
            return cells;
        }

        public int getSize() {
            return size;
        }

        @Override
        public int compareTo(Lake other) {
            return Integer.compare(this.size, other.size);
        }
    }

    /**
     * Contains the core logic for finding and filling lakes.
     */
    static class LakeSolver {
        private final char[][] grid;
        private final int rows;
        private final int cols;
        private final boolean[][] visited;

        private static final int[] DR = {1, -1, 0, 0};
        private static final int[] DC = {0, 0, 1, -1};

        public LakeSolver(char[][] grid, int rows, int cols) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
            this.visited = new boolean[rows][cols];
        }

        public void solve(int k) {
            List<Lake> lakes = findLakes();
            Collections.sort(lakes);

            int totalBuriedCells = 0;
            int lakesToBury = Math.max(0, lakes.size() - k);

            for (int i = 0; i < lakesToBury; i++) {
                Lake lake = lakes.get(i);
                totalBuriedCells += lake.getSize();
                buryLake(lake);
            }

            System.out.println(totalBuriedCells);
        }

        private List<Lake> findLakes() {
            List<Lake> lakes = new ArrayList<>();

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.' && !visited[r][c]) {
                        Lake lake = bfsExploreComponent(r, c);
                        if (lake != null) {
                            lakes.add(lake);
                        }
                    }
                }
            }
            return lakes;
        }

        /**
         * Explores a connected component of water using BFS.
         * @return A Lake object if the component does not touch the boundary, otherwise null.
         */
        private Lake bfsExploreComponent(int startR, int startC) {
            List<Coordinate> componentCells = new ArrayList<>();
            Deque<Coordinate> queue = new ArrayDeque<>();
            boolean touchesEdge = false;

            Coordinate start = new Coordinate(startR, startC);
            queue.add(start);
            visited[startR][startC] = true;

            while (!queue.isEmpty()) {
                Coordinate curr = queue.poll();
                componentCells.add(curr);

                if (isEdge(curr.r, curr.c)) {
                    touchesEdge = true;
                }

                for (int i = 0; i < 4; i++) {
                    int nr = curr.r + DR[i];
                    int nc = curr.c + DC[i];

                    if (isValid(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        queue.add(new Coordinate(nr, nc));
                    }
                }
            }

            return touchesEdge ? null : new Lake(componentCells);
        }

        private void buryLake(Lake lake) {
            for (Coordinate cell : lake.getCells()) {
                grid[cell.r][cell.c] = '*';
            }
        }

        private boolean isEdge(int r, int c) {
            return r == 0 || r == rows - 1 || c == 0 || c == cols - 1;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        public void printGrid() {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    sb.append(grid[i][j]);
                }
                sb.append('\n');
            }
            System.out.print(sb.toString());
        }
    }
}

