/**
 * A program to identify connected components in a grid and remove the smallest 
 * interior components until only 'k' interior components remain.
 */
public class Main {
    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        try {
            GridSolver solver = new GridSolver(reader);
            solver.solve(out);
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            out.close();
        }
    }
}

class GridSolver {
    private final FastReader reader;
    private int rows;
    private int cols;
    private int k;
    private boolean[][] grid;

    public GridSolver(FastReader reader) {
        this.reader = reader;
    }

    /**
     * Executes the core logic: reading the grid, identifying components,
     * calculating removals, and printing the result.
     */
    public void solve(PrintWriter out) throws IOException {
        // 1. Read input dimensions and target number of components to keep
        rows = reader.nextInt();
        cols = reader.nextInt();
        k = reader.nextInt();
        grid = new boolean[rows][cols];

        for (int i = 0; i < rows; i++) {
            String line = reader.next();
            for (int j = 0; j < cols; j++) {
                if (line.charAt(j) == '.') {
                    grid[i][j] = true;
                }
            }
        }

        // 2. Identify connected components using BFS
        // componentIdMap stores the ID of the component each cell belongs to
        int[][] componentIdMap = new int[rows][cols];
        for (int[] row : componentIdMap) {
            Arrays.fill(row, -1);
        }

        List<Integer> componentSizes = new ArrayList<>();
        List<Boolean> isBoundaryComponent = new ArrayList<>();
        int currentComponentId = 0;

        // Direction vectors for 4-connectivity (Up, Down, Left, Right)
        int[] dr = {1, -1, 0, 0};
        int[] dc = {0, 0, 1, -1};

        // Pre-allocate queue arrays to avoid frequent memory allocation
        int[] queueR = new int[rows * cols];
        int[] queueC = new int[rows * cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                // If we find an unvisited land cell ('.')
                if (grid[i][j] && componentIdMap[i][j] == -1) {
                    int size = 0;
                    boolean touchesBoundary = false;

                    int head = 0, tail = 0;
                    queueR[tail] = i;
                    queueC[tail] = j;
                    tail++;
                    componentIdMap[i][j] = currentComponentId;

                    while (head < tail) {
                        int r = queueR[head];
                        int c = queueC[head];
                        head++;
                        size++;

                        // Check if this cell is on the boundary of the grid
                        if (r == 0 || r == rows - 1 || c == 0 || c == cols - 1) {
                            touchesBoundary = true;
                        }

                        for (int d = 0; d < 4; d++) {
                            int nr = r + dr[d];
                            int nc = c + dc[d];

                            if (isValid(nr, nc) && grid[nr][nc] && componentIdMap[nr][nc] == -1) {
                                componentIdMap[nr][nc] = currentComponentId;
                                queueR[tail] = nr;
                                queueC[tail] = nc;
                                tail++;
                            }
                        }
                    }
                    componentSizes.add(size);
                    isBoundaryComponent.add(touchesBoundary);
                    currentComponentId++;
                }
            }
        }

        // 3. Separate interior components from boundary components
        List<Integer> interiorComponentIds = new ArrayList<>();
        for (int id = 0; id < currentComponentId; id++) {
            if (!isBoundaryComponent.get(id)) {
                interiorComponentIds.add(id);
            }
        }

        // 4. Sort interior components by size (ascending) to minimize removal cost
        interiorComponentIds.sort(Comparator.comparingInt(componentSizes::get));

        // 5. Calculate how many components to remove (to leave exactly 'k' components)
        int numToRemove = Math.max(0, interiorComponentIds.size() - k);
        int totalCellsRemoved = 0;
        Set<Integer> idsToRemove = new HashSet<>();

        for (int i = 0; i < numToRemove; i++) {
            int id = interiorComponentIds.get(i);
            totalCellsRemoved += componentSizes.get(id);
            idsToRemove.add(id);
        }

        // 6. Update the grid by converting '.' to '*' for removed components
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (idsToRemove.contains(componentIdMap[i][j])) {
                    grid[i][j] = false;
                }
            }
        }

        // 7. Final Output
        out.println(totalCellsRemoved);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < rows; i++) {
            sb.setLength(0);
            for (int j = 0; j < cols; j++) {
                sb.append(grid[i][j] ? '.' : '*');
            }
            out.println(sb.toString());
        }
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

/**
 * Fast I/O utility class for reading input efficiently.
 */
class FastReader {
    private BufferedReader br;
    private StringTokenizer st;

    public FastReader(InputStream inputStream) {
