    }
}

import java.util.*;

/**
 * Refactored solution for the "Lakes in Berland" problem.
 * This program identifies connected components of '.' cells (lakes) in a grid.
 * Lakes that touch the boundary of the grid are considered "ocean" and are not counted.
 * If the number of lakes exceeds K, the smallest lakes are filled with '*' until 
 * only K lakes remain.
 */
public class LakesInBerland {

    // Directions for moving in the grid: Up, Down, Left, Right
    private static final int[][] DIRECTIONS = {
        {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    /**
     * Represents a single coordinate in the grid.
     */
    private static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Represents a lake, storing its constituent cells and its total area (size).
     */
    private static class Lake implements Comparable<Lake> {
        final List<Point> cells;
        final int size;

        Lake(List<Point> cells) {
            this.cells = cells;
            this.size = cells.size();
        }

        @Override
        public int compareTo(Lake other) {
            // Sort lakes by size in ascending order
            return Integer.compare(this.size, other.size);
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        int k = scanner.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
            }
        }

        // visited[i][j] tracks cells already assigned to the ocean or a processed lake.
        boolean[][] visited = new boolean[rows][cols];

        // Phase 1: Identify "Ocean" cells.
        // Any '.' cell on the grid boundary or connected to a boundary '.' is part of the ocean.
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (isBoundary(i, j, rows, cols) && grid[i][j] == '.' && !visited[i][j]) {
                    markOcean(i, j, rows, cols, grid, visited);
                }
            }
        }

        // Phase 2: Identify "Lakes".
        // Any '.' cell remaining that has not been visited is part of an enclosed lake.
        List<Lake> lakes = new ArrayList<>();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.' && !visited[i][j]) {
                    lakes.add(findLake(i, j, rows, cols, grid, visited));
                }
            }
        }

        // Phase 3: Fill the smallest lakes if the number of lakes exceeds K.
        Collections.sort(lakes);
        int numLakesToFill = Math.max(0, lakes.size() - k);
        for (int i = 0; i < numLakesToFill; i++) {
            for (Point p : lakes.get(i).cells) {
                grid[p.row][p.col] = '*';
            }
        }

        // Phase 4: Output the final grid.
        printGrid(grid);
        scanner.close();
    }

    private static boolean isBoundary(int r, int c, int rows, int cols) {
        return r == 0 || r == rows - 1 || c == 0 || c == cols - 1;
    }

    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Performs BFS to mark all '.' cells connected to the ocean boundary as visited.
     */
    private static void markOcean(int startR, int startC, int rows, int cols, char[][] grid, boolean[][] visited) {
        Queue<Point> queue = new ArrayDeque<>();
        queue.offer(new Point(startR, startC));
        visited[startR][startC] = true;

        while (!queue.isEmpty()) {
            Point curr = queue.poll();

            for (int[] dir : DIRECTIONS) {
                int nr = curr.row + dir[0];
                int nc = curr.col + dir[1];

                if (isValid(nr, nc, rows, cols) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    queue.offer(new Point(nr, nc));
                }
            }
        }
    }

    /**
     * Performs BFS to find all '.' cells belonging to a single enclosed lake.
     */
    private static Lake findLake(int startR, int startC, int rows, int cols, char[][] grid, boolean[][] visited) {
        List<Point> lakeCells = new ArrayList<>();
        Queue<Point> queue = new ArrayDeque<>();

        queue.offer(new Point(startR, startC));
        visited[startR][startC] = true;

        while (!queue.isEmpty()) {
            Point curr = queue.poll();
            lakeCells.add(curr);

            for (int[] dir : DIRECTIONS) {
                int nr = curr.row + dir[0];
                int nc = curr.col + dir[1];

                if (isValid(nr, nc, rows, cols) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    queue.offer(new Point(nr, nc));
                }
            }
        }
        return new Lake(lakeCells);
    }

    private static void printGrid(char[][] grid) {
        StringBuilder sb = new StringBuilder();
        for (char[] row : grid) {
            sb.append(new String(row)).append('\n');
        }
        System.out.print(sb.toString());
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to identify connected components in a grid and remove 
 * a specific number of non-boundary components to maximize cell removal.
 */
public class Main {

    public static void main(String[] args) {
        FastReader in = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = in.nextInt();
            int m = in.nextInt();
            int k = in.nextInt();

            char[][] board = new char[n][m];
            for (int i = 0; i < n; i++) {
                board[i] = in.next().toCharArray();
            }

            GridSolver solver = new GridSolver(n, m, k, board);
            solver.solve(out);
        } catch (Exception e) {
            // In a real production environment, use a logger
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Represents a connected component of '.' cells in the grid.
     */
    static class Component implements Comparable<Component> {
        final int id;
        final int size;
        final boolean touchesBoundary;

        Component(int id, int size, boolean touchesBoundary) {
            this.id = id;
            this.size = size;
            this.touchesBoundary = touchesBoundary;
        }

        @Override
        public int compareTo(Component other) {
            // Sort primarily by size, secondarily by ID
            if (this.size != other.size) {
                return Integer.compare(this.size, other.size);
            }
            return Integer.compare(this.id, other.id);
        }
    }

    /**
     * Represents a 2D coordinate in the grid.
     */
    static class Point {
        final int r, c;
        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Core logic for solving the grid component problem.
     */
    static class GridSolver {
        private final int rows;
        private final int cols;
        private final int k;
        private final char[][] board;
        private final int[][] componentIdGrid;
        private final List<Component> components = new ArrayList<>();

        private static final int[] DR = {-1, 0, 1, 0};
        private static final int[] DC = {0, -1, 0, 1};

        GridSolver(int rows, int cols, int k, char[][] board) {
            this.rows = rows;
            this.cols = cols;
            this.k = k;
            this.board = board;
            this.componentIdGrid = new int[rows][cols];
        }

        public void solve(PrintWriter out) {
            findComponents();

            // Identify components that do not touch the boundary
            List<Component> nonBoundaryComponents = new ArrayList<>();
            for (Component comp : components) {
                if (!comp.touchesBoundary) {
                    nonBoundaryComponents.add(comp);
                }
            }

            // Sort components by size to pick the smallest ones (matching original logic)
            Collections.sort(nonBoundaryComponents);

            // Determine which component IDs should be turned into '*'
            Set<Integer> idsToRemove = new HashSet<>();
            int numNonBoundary = nonBoundaryComponents.size();
            for (int i = 0; i < numNonBoundary - k; i++) {
                idsToRemove.add(nonBoundaryComponents.get(i).id);
            }

            // Apply changes to the board and count cells modified
            int cellsChanged = 0;
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (idsToRemove.contains(componentIdGrid[r][c])) {
                        board[r][c] = '*';
                        cellsChanged++;
                    }
                }
            }

            // Output the result
            out.println(cellsChanged);
            for (int r = 0; r < rows; r++) {
                out.println(new String(board[r]));
            }
        }

        /**
         * Traverses the grid to find all connected components of '.' cells.
         */
        private void findComponents() {
            int componentIdCounter = 0;
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (board[r][c] == '.' && componentIdGrid[r][c] == 0) {
                        componentIdCounter++;
                        processComponent(r, c, componentIdCounter);
                    }
                }
            }
        }

        /**
         * Performs a DFS to map out a single component.
         */
        private void processComponent(int startR, int startC, int id) {
            int size = 0;
            boolean touchesBoundary = false;
            Deque<Point> stack = new ArrayDeque<>();
            stack.push(new Point(startR, startC));

            while (!stack.isEmpty()) {
                Point curr = stack.pop();

                // If this cell is already processed by another branch of the DFS, skip
                if (componentIdGrid[curr.r][curr.c] != 0) {
                    continue;
                }

                componentIdGrid[curr.r][curr.c] = id;
                size++;

                // Check if the current cell is on the boundary
                if (curr.r == 0 || curr.r == rows - 1 || curr.c == 0 || curr.c == cols - 1) {
                    touchesBoundary = true;
                }

                // Check neighbors
                for (int i = 0; i < 4; i++) {
                    int nr = curr.r + DR[i];
                    int nc = curr.c + DC[i];

                    if (isValidNeighbor(nr, nc)) {
                        stack.push(new Point(nr, nc));
                    }
                }
            }
            components.add(new Component(id, size, touchesBoundary));
        }

        private boolean isValidNeighbor(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols 
                   && board[r][c] == '.' && componentIdGrid[r][c] == 0;
        }
    }

    /**
     * Utility class for fast input reading.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;

/**
 * Solution for the Berland Lakes problem.
 * Goal: Fill the minimum number of water cells so that exactly k lakes remain.
 * A lake is a connected component of water '.' that does not touch the grid boundary.
 */
public class BerlandLakes {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        if (!sc.hasNextInt()) return;
        int n = sc.nextInt();
        int m = sc.nextInt();
        int k = sc.nextInt();

        char[][] board = new char[n][m];
        for (int i = 0; i < n; i++) {
            String line = sc.next();
            board[i] = line.toCharArray();
        }

        LakeSolver solver = new LakeSolver(n, m, k, board);
        solver.solve();
    }

    /**
     * Represents a connected component of water.
     */
    private static class Lake implements Comparable<Lake> {
        int size;
        List<Point> cells;

        Lake(List<Point> cells) {
            this.cells = cells;
            this.size = cells.size();
        }

        @Override
        public int compareTo(Lake other) {
            return Integer.compare(this.size, other.size);
        }
    }

    /**
     * Simple coordinate representation.
     */
    private static class Point {
        int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    private static class LakeSolver {
        private final int rows;
        private final int cols;
        private final int targetLakeCount;
        private final char[][] board;
        private final boolean[][] visited;

        private static final int[][] DIRECTIONS = {
            {-1, 0}, {1, 0}, {0, -1}, {0, 1}
        };

        public LakeSolver(int rows, int cols, int targetLakeCount, char[][] board) {
            this.rows = rows;
            this.cols = cols;
            this.targetLakeCount = targetLakeCount;
            this.board = board;
            this.visited = new boolean[rows][cols];
        }

        public void solve() {
            List<Lake> lakes = findLakes();
            int filledCellsCount = 0;

            // If we have more lakes than the target, fill the smallest ones first
            if (lakes.size() > targetLakeCount) {
                Collections.sort(lakes);
                int lakesToFill = lakes.size() - targetLakeCount;

                for (int i = 0; i < lakesToFill; i++) {
                    Lake lake = lakes.get(i);
                    filledCellsCount += lake.size;
                    for (Point p : lake.cells) {
                        board[p.r][p.c] = '*';
                    }
                }
            }

            printResult(filledCellsCount);
        }

        /**
         * Identifies all connected components of '.' and separates lakes from boundary water.
         */
        private List<Lake> findLakes() {
            List<Lake> lakes = new ArrayList<>();

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (board[r][c] == '.' && !visited[r][c]) {
                        List<Point> componentCells = new ArrayList<>();
                        boolean touchesBoundary = bfs(r, c, componentCells);

                        // If the component never touched the boundary, it is a lake
                        if (!touchesBoundary) {
                            lakes.add(new Lake(componentCells));
                        }
                    }
                }
            }
            return lakes;
        }

        /**
         * Standard BFS to traverse a water component.
         * @return true if the component touches the grid boundary.
         */
        private boolean bfs(int startR, int startC, List<Point> componentCells) {
            boolean touchesBoundary = false;
            Deque<Point> queue = new ArrayDeque<>();

            Point start = new Point(startR, startC);
            queue.add(start);
            visited[startR][startC] = true;

            while (!queue.isEmpty()) {
                Point curr = queue.poll();
                componentCells.add(curr);

                if (isBoundary(curr.r, curr.c)) {
                    touchesBoundary = true;
                }

                for (int[] dir : DIRECTIONS) {
                    int nr = curr.r + dir[0];
                    int nc = curr.c + dir[1];

                    if (isValid(nr, nc) && board[nr][nc] == '.' && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        queue.add(new Point(nr, nc));
                    }
                }
            }
            return touchesBoundary;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        private boolean isBoundary(int r, int c) {
            return r == 0 || r == rows - 1 || c == 0 || c == cols - 1;
        }

        private void printResult(int filledCells) {
            System.out.println(filledCells);
            StringBuilder sb = new StringBuilder();
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    sb.append(board[r][c]);
                }
                sb.append('\n');
            }
            System.out.print(sb.toString());
        }
    }
}

