class LakeSolver {
    private static final char WATER = '.';
    private static final char LAND = '#';
    private static final char REMOVED_WATER = '*';
    private static final int[][] DIRECTIONS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    private final int rows;
    private final int cols;
    private final char[][] grid;

    public LakeSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
    }

    /**
     * Executes the core logic: finding lakes, sorting them, and removing the smallest.
     */
    public void solve(int maxLakesAllowed) {
        List<Lake> lakes = findLakes();
        Collections.sort(lakes);

        int removedCellsCount = 0;
        int lakeIndex = 0;

        // Remove the smallest lakes until we reach the allowed count
        while (lakes.size() - lakeIndex > maxLakesAllowed) {
            Lake smallestLake = lakes.get(lakeIndex++);
            removedCellsCount += smallestLake.getSize();
            markLakeAsRemoved(smallestLake);
        }

        printResults(removedCellsCount);
    }

    /**
     * Traverses the grid to identify all connected water components.
     * Components touching the boundary are treated as ocean, others as lakes.
     */
    private List<Lake> findLakes() {
        List<Lake> lakes = new ArrayList<>();
        boolean[][] visited = new boolean[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == WATER && !visited[i][j]) {
                    Lake component = floodFill(i, j, visited);
                    if (!component.touchesBoundary()) {
                        lakes.add(component);
                    }
                }
            }
        }
        return lakes;
    }

    /**
     * Standard flood-fill algorithm to find all connected cells of a component.
     */
    private Lake floodFill(int startX, int startY, boolean[][] visited) {
        List<Point> componentCells = new ArrayList<>();
        boolean touchesBoundary = false;
        Queue<Point> queue = new LinkedList<>();

        Point start = new Point(startX, startY);
        queue.add(start);
        visited[startX][startY] = true;

        while (!queue.isEmpty()) {
            Point current = queue.poll();
            componentCells.add(current);

            // Check if this cell is on the boundary
            if (current.x == 0 || current.x == rows - 1 || current.y == 0 || current.y == cols - 1) {
                touchesBoundary = true;
            }

            for (int[] dir : DIRECTIONS) {
                int nextX = current.x + dir[0];
                int nextY = current.y + dir[1];

                if (isInBounds(nextX, nextY) && !visited[nextX][nextY] && grid[nextX][nextY] == WATER) {
                    visited[nextX][nextY] = true;
                    queue.add(new Point(nextX, nextY));
                }
            }
        }

        return new Lake(componentCells, touchesBoundary);
    }

    private void markLakeAsRemoved(Lake lake) {
        for (Point p : lake.getCells()) {
            grid[p.x][p.y] = REMOVED_WATER;
        }
    }

    private boolean isInBounds(int x, int y) {
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }

    private void printResults(int removedCount) {
        System.out.println(removedCount);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                sb.append(grid[i][j]);
            }
            sb.append("\n");
        }
        System.out.print(sb.toString());
    }

    /**
     * Represents a connected component of water.
     */
    private static class Lake implements Comparable<Lake> {
        private final List<Point> cells;
        private final boolean touchesBoundary;

        public Lake(List<Point> cells, boolean touchesBoundary) {
            this.cells = cells;
            this.touchesBoundary = touchesBoundary;
        }

        public List<Point> getCells() { return cells; }
        public int getSize() { return cells.size(); }
        public boolean touchesBoundary() { return touchesBoundary; }

        @Override
        public int compareTo(Lake other) {
            return Integer.compare(this.getSize(), other.getSize());
        }
    }

    /**
     * Simple wrapper for grid coordinates.
     */
    private static class Point {
        final int x, y;
        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }
}

