/**
 * Handles the logic of processing the grid to fill the smallest lakes.
 */
class GridProcessor {
    private static final int[][] DIRECTIONS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
    private final int rows;
    private final int cols;
    private final char[][] grid;

    public GridProcessor(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
    }

    /**
     * Fills the smallest (totalLakes - k) lakes with land ('*').
     * @param k The number of lakes to remain after filling.
     */
    public void fillLakes(int k) {
        List<Lake> lakes = findLakes();
        Collections.sort(lakes);

        int lakesToFillCount = lakes.size() - k;
        for (int i = 0; i < lakesToFillCount; i++) {
            fillLake(lakes.get(i));
        }
    }

    private List<Lake> findLakes() {
        List<Lake> lakes = new ArrayList<>();
        boolean[][] visited = new boolean[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && !visited[r][c]) {
                    Lake component = bfs(r, c, visited);
                    if (!isConnectedToBoundary(component)) {
                        lakes.add(component);
                    }
                }
            }
        }
        return lakes;
    }

    private Lake bfs(int startR, int startC, boolean[][] visited) {
        List<int[]> componentCells = new ArrayList<>();
        Queue<int[]> queue = new LinkedList<>();

        queue.add(new int[]{startR, startC});
        visited[startR][startC] = true;

        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            componentCells.add(curr);

            for (int[] dir : DIRECTIONS) {
                int nr = curr[0] + dir[0];
                int nc = curr[1] + dir[1];

                if (isValid(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    queue.add(new int[]{nr, nc});
                }
            }
        }
        return new Lake(componentCells);
    }

    private boolean isConnectedToBoundary(Lake lake) {
        for (int[] coord : lake.getCoordinates()) {
            int r = coord[0];
            int c = coord[1];
            if (r == 0 || r == rows - 1 || c == 0 || c == cols - 1) {
                return true;
            }
        }
        return false;
    }

    private void fillLake(Lake lake) {
        for (int[] coord : lake.getCoordinates()) {
            grid[coord[0]][coord[1]] = '*';
        }
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    public void printGrid() {
        StringBuilder sb = new StringBuilder();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                sb.append(grid[r][c]);
            }
            sb.append("\n");
        }
        System.out.print(sb.toString());
    }
}

public class Main {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        if (!sc.hasNextInt()) return;

        int n = sc.nextInt();
        int m = sc.nextInt();
        int k = sc.nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String line = sc.next();
            for (int j = 0; j < m; j++) {
                grid[i][j] = line.charAt(j);
            }
        }

        GridProcessor processor = new GridProcessor(n, m, grid);
        processor.fillLakes(k);
        processor.printGrid();

        sc.close();
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver for grid-based connectivity problems.
 * The goal is to identify enclosed components of empty cells ('.') and 
 * turn the smallest ones into walls ('*') while keeping at most K components.
 */
public class D723 {
    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            int k = reader.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            GridProblemSolver solver = new GridProblemSolver(rows, cols, k, grid);
            solver.solve(writer);
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    static class Component implements Comparable<Component> {
        int size;
        int r, c;

        Component(int size, int r, int c) {
            this.size = size;
            this.r = r;
            this.c = c;
        }

        @Override
        public int compareTo(Component other) {
            return Integer.compare(this.size, other.size);
        }
    }

    static class GridProblemSolver {
        private final int rows;
        private final int cols;
        private final int k;
        private final char[][] grid;

        private final boolean[][] isBorderConnected;
        private final boolean[][] visited;

        // Primitive stacks for iterative DFS to avoid StackOverflow and object overhead
        private final int[] stackR;
        private final int[] stackC;
        private int stackTop;

        private static final int[][] DIRS = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

        public GridProblemSolver(int rows, int cols, int k, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.k = k;
            this.grid = grid;
            this.isBorderConnected = new boolean[rows][cols];
            this.visited = new boolean[rows][cols];
            this.stackR = new int[rows * cols];
            this.stackC = new int[rows * cols];
            this.stackTop = -1;
        }

        public void solve(PrintWriter pw) {
            // 1. Identify cells reachable from the border
            markBorderConnected();

            // 2. Find all enclosed components
            List<Component> components = findEnclosedComponents();

            // 3. Determine components to be converted to '*'
            // We sort ascending and keep the K largest components.
            // Therefore, we remove (Total - K) smallest components.
            Collections.sort(components);
            int numToRemove = Math.max(0, components.size() - k);

            long totalRemovedCells = 0;
            for (int i = 0; i < numToRemove; i++) {
                Component comp = components.get(i);
                totalRemovedCells += comp.size;
                destroyComponent(comp.r, comp.c);
            }

            // 4. Output result
            pw.println(totalRemovedCells);
            for (int i = 0; i < rows; i++) {
                pw.println(new String(grid[i]));
            }
        }

        private void markBorderConnected() {
            for (int r = 0; r < rows; r++) {
                if (grid[r][0] == '.') checkAndDFS(r, 0, true);
                if (grid[r][cols - 1] == '.') checkAndDFS(r, cols - 1, true);
            }
            for (int c = 0; c < cols; c++) {
                if (grid[0][c] == '.') checkAndDFS(0, c, true);
                if (grid[rows - 1][c] == '.') checkAndDFS(rows - 1, c, true);
            }
        }

        private void checkAndDFS(int r, int c, boolean borderMode) {
            if (borderMode) {
                if (isBorderConnected[r][c]) return;
                iterativeDFS(r, c, isBorderConnected, null);
            }
        }

        private List<Component> findEnclosedComponents() {
            List<Component> components = new ArrayList<>();
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.' && !isBorderConnected[r][c] && !visited[r][c]) {
                        int size = iterativeDFS(r, c, visited, null);
                        components.add(new Component(size, r, c));
                    }
                }
            }
            return components;
        }

        /**
         * Iterative DFS that works for marking connectivity or calculating component size.
         * @param targetVisited The boolean array to mark visited nodes.
         * @param replacementChar If not null, cells will be changed to this char (for destruction).
         * @return The size of the component found.
         */
        private int iterativeDFS(int startR, int startC, boolean[][] targetVisited, Character replacementChar) {
            int size = 0;
            stackTop = -1;
            stackR[++stackTop] = startR;
            stackC[stackTop] = startC;
            targetVisited[startR][startC] = true;

            while (stackTop >= 0) {
                int r = stackR[stackTop];
                int c = stackC[stackTop--];
                size++;

                if (replacementChar != null) {
                    grid[r][c] = replacementChar;
                }

                for (int[] dir : DIRS) {
                    int nr = r + dir[0];
                    int nc = c + dir[1];

                    if (isValid(nr, nc) && grid[nr][nc] == '.' && !targetVisited[nr][nc]) {
                        // If we are in 'finding components' mode, ensure we don't cross border-connected cells
                        if (targetVisited == visited && isBorderConnected[nr][nc]) continue;

                        targetVisited[nr][nc] = true;
                        stackR[++stackTop] = nr;
                        stackC[stackTop] = nc;
                    }
                }
            }
            return size;
        }

        private void destroyComponent(int r, int c) {
            // For destruction, we don't need a visited array because we change '.' to '*'
            stackTop = -1;
            stackR[++stackTop] = r;
            stackC[stackTop] = c;
            grid[r][c] = '*';

            while (stackTop >= 0) {
                int currR = stackR[stackTop];
                int currC = stackC[stackTop--];

                for (int[] dir : DIRS) {
                    int nr = currR + dir[0];
                    int nc = currC + dir[1];
                    if (isValid(nr, nc) && grid[nr][nc] == '.') {
                        grid[nr][nc] = '*'; // Mark immediately to avoid duplicate stack entries
                        stackR[++stackTop] = nr;
                        stackC[stackTop] = nc;
                    }
                }
            }
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.util.*;

/**
 * Refactored solution for Codeforces 375B - Lakes.
 * The goal is to fill up to k smallest lakes (disconnected water components not touching the border).
 */
public class Codeforces375_2D {

    /**
     * Represents a coordinate in the grid.
     */
    public record Point(int r, int c) {}

    /**
     * Manages the grid state and cell access.
     */
    static class Grid {
        private final int rows;
        private final int cols;
        private final char[][] cells;

        public Grid(int rows, int cols, char[][] cells) {
            this.rows = rows;
            this.cols = cols;
            this.cells = cells;
        }

        public int getRows() { return rows; }
        public int getCols() { return cols; }

        public boolean isWater(int r, int c) {
            return cells[r][c] == '.';
        }

        public void setCell(int r, int c, char value) {
            cells[r][c] = value;
        }

        public boolean isBorder(int r, int c) {
            return r == 0 || r == rows - 1 || c == 0 || c == cols - 1;
        }

        public void print() {
            for (int i = 0; i < rows; i++) {
                System.out.println(new String(cells[i]));
            }
        }
    }

    /**
     * Contains the business logic for finding and filling lakes.
     */
    static class LakeManager {
        private static final int[] DR = {-1, 1, 0, 0};
        private static final int[] DC = {0, 0, -1, 1};

        /**
         * Identifies all lakes (connected water components that do not touch the boundary).
         * @param grid The field grid.
         * @return A list of lakes, where each lake is a list of points.
         */
        public List<List<Point>> findLakes(Grid grid) {
            List<List<Point>> lakes = new ArrayList<>();
            boolean[][] visited = new boolean[grid.getRows()][grid.getCols()];

            for (int i = 0; i < grid.getRows(); i++) {
                for (int j = 0; j < grid.getCols(); j++) {
                    if (grid.isWater(i, j) && !visited[i][j]) {
                        List<Point> component = bfs(grid, i, j, visited);
                        if (!touchesBorder(grid, component)) {
                            lakes.add(component);
                        }
                    }
                }
            }
            return lakes;
        }

        private List<Point> bfs(Grid grid, int startR, int startC, boolean[][] visited) {
            List<Point> component = new ArrayList<>();
            Queue<Point> queue = new ArrayDeque<>();

            Point start = new Point(startR, startC);
            queue.add(start);
            visited[startR][startC] = true;

            while (!queue.isEmpty()) {
                Point curr = queue.poll();
                component.add(curr);

                for (int i = 0; i < 4; i++) {
                    int nr = curr.r() + DR[i];
                    int nc = curr.c() + DC[i];

                    if (isValid(grid, nr, nc) && grid.isWater(nr, nc) && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        queue.add(new Point(nr, nc));
                    }
                }
            }
            return component;
        }

        private boolean isValid(Grid grid, int r, int c) {
            return r >= 0 && r < grid.getRows() && c >= 0 && c < grid.getCols();
        }

        private boolean touchesBorder(Grid grid, List<Point> component) {
            for (Point p : component) {
                if (grid.isBorder(p.r(), p.c())) {
                    return true;
                }
            }
            return false;
        }

        /**
         * Fills the smallest k lakes with land ('*').
         * @param grid The grid to modify.
         * @param lakes The identified lakes.
         * @param k The maximum number of lakes to fill.
         * @return The total number of cells filled.
         */
        public int fillLakes(Grid grid, List<List<Point>> lakes, int k) {
            // Sort lakes by size (ascending)
            lakes.sort(Comparator.comparingInt(List::size));

            int totalFilledCells = 0;
            int lakesToFill = Math.min(k, lakes.size());

            for (int i = 0; i < lakesToFill; i++) {
                for (Point p : lakes.get(i)) {
                    grid.setCell(p.r(), p.c(), '*');
                    totalFilledCells++;
                }
            }
            return totalFilledCells;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextInt()) return;

        int rows = sc.nextInt();
        int cols = sc.nextInt();
        int k = sc.nextInt();
        sc.nextLine(); // consume newline

        char[][] initialCells = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            initialCells[i] = sc.nextLine().toCharArray();
        }

        Grid grid = new Grid(rows, cols, initialCells);
        LakeManager lakeManager = new LakeManager();

        // 1. Find all lakes
        List<List<Point>> lakes = lakeManager.findLakes(grid);

        // 2. Fill up to k smallest lakes and get the count of cells filled
        int filledCount = lakeManager.fillLakes(grid, lakes, k);

        // 3. Output results
        System.out.println(filledCount);
        grid.print();

        sc.close();
    }
}

import java.util.*;
import java.io.*;

/**
 * Problem: Identify connected components of water cells (lakes).
 * Components touching the grid boundary are considered "oceans" and cannot be removed.
 * The goal is to remove the smallest lakes until only 'k' lakes remain.
 */
public class LakesInBerland {

    private static final int LAND = 0;
    private static final int UNVISITED_WATER = -1;

    // Direction vectors for 4-connectivity (Up, Down, Left, Right)
    private static final int[] DR = {0, 0, 1, -1};
    private static final int[] DC = {1, -1, 0, 0};

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        int rows = reader.nextInt();
        int cols = reader.nextInt();
        int targetLakesCount = reader.nextInt();

        if (rows <= 0 || cols <= 0) return;

        int[][] grid = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = reader.nextLine();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = (line.charAt(j) == '*') ? LAND : UNVISITED_WATER;
            }
        }

        List<Lake> lakes = findLakes(grid, rows, cols);

        // Sort lakes by size ascending to remove the smallest ones first
        Collections.sort(lakes);

        Set<Integer> lakesToRemove = new HashSet<>();
        int totalCost = 0;
        int lakesToRemoveCount = Math.max(0, lakes.size() - targetLakesCount);

        for (int i = 0; i < lakesToRemoveCount; i++) {
            Lake lake = lakes.get(i);
            totalCost += lake.size;
            lakesToRemove.add(lake.id);
        }

        printResult(grid, rows, cols, totalCost, lakesToRemove);
    }

    /**
     * Finds all connected components of water that do not touch the boundary.
     */
    private static List<Lake> findLakes(int[][] grid, int rows, int cols) {
        List<Lake> lakes = new ArrayList<>();
        int currentLakeId = 1;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == UNVISITED_WATER) {
                    Lake result = bfs(grid, r, c, rows, cols, currentLakeId);
                    if (!result.isOcean) {
                        lakes.add(result);
                    }
                    currentLakeId++;
                }
            }
        }
        return lakes;
    }

    /**
     * Performs BFS to find the size of a component and whether it touches the boundary.
     */
    private static Lake bfs(int[][] grid, int startR, int startC, int rows, int cols, int id) {
        Deque<Point> queue = new ArrayDeque<>();
        queue.add(new Point(startR, startC));
        grid[startR][startC] = id;

        int size = 0;
        boolean isOcean = false;

        while (!queue.isEmpty()) {
            Point curr = queue.poll();
            size++;

            // If the cell is on the boundary, the entire component is an ocean
            if (curr.r == 0 || curr.r == rows - 1 || curr.c == 0 || curr.c == cols - 1) {
                isOcean = true;
            }

            for (int i = 0; i < 4; i++) {
                int nr = curr.r + DR[i];
                int nc = curr.c + DC[i];

                if (isValid(nr, nc, rows, cols) && grid[nr][nc] == UNVISITED_WATER) {
                    grid[nr][nc] = id; // Mark as visited by assigning component ID
                    queue.add(new Point(nr, nc));
                }
            }
        }

        return new Lake(id, size, isOcean);
    }

    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private static void printResult(int[][] grid, int rows, int cols, int cost, Set<Integer> removeSet) {
        StringBuilder out = new StringBuilder();
        out.append(cost).append("\n");

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int cellValue = grid[r][c];
                // If land OR if the cell belongs to a lake marked for removal
                if (cellValue == LAND || removeSet.contains(cellValue)) {
                    out.append('*');
                } else {
                    out.append('.');
                }
            }
            out.append("\n");
        }
        System.out.print(out);
    }

    /**
     * Data structure to represent a lake component.
     */
    private static class Lake implements Comparable<Lake> {
        int id;
        int size;
        boolean isOcean;

        Lake(int id, int size, boolean isOcean) {
            this.id = id;
            this.size = size;
            this.isOcean = isOcean;
        }

        @Override
        public int compareTo(Lake other) {
            return Integer.compare(this.size, other.size);
        }
    }

    /**
     * Lightweight point representation.
     */
    private static class Point {
        int r, c;
        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Fast I/O utility.
     */
    private static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public String nextLine() {
            try {
                return reader.readLine();
            } catch (IOException e) {
                return null;
            }
        }
    }
