import java.io.*;
import java.util.*;

public class LakesInBerland {

    public static void main(String[] args) {
        FastReader sc = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = sc.nextInt();
            int m = sc.nextInt();
            int minLakesAllowed = sc.nextInt();

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                grid[i] = sc.next().toCharArray();
            }

            LakeProcessor processor = new LakeProcessor(n, m, grid);
            processor.execute(minLakesAllowed);
            processor.printOutput(out);

        } catch (Exception e) {
            // Silent fail for competitive programming context
        } finally {
            out.flush();
            out.close();
        }
    }

    static class Point {
        int r, c;
        Point(int r, int c) { this.r = r; this.c = c; }
    }

    static class Lake implements Comparable<Lake> {
        List<Point> coordinates = new ArrayList<>();
        int size = 0;

        void add(int r, int c) {
            coordinates.add(new Point(r, c));
            size++;
        }

        @Override
        public int compareTo(Lake other) {
            // Sort descending by size
            return Integer.compare(other.size, this.size);
        }
    }

    static class LakeProcessor {
        private final int rows, cols;
        private final char[][] grid;
        private final int[][] directions = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};
        private int filledCellsCount = 0;
        private static final char OCEAN = 'O';

        public LakeProcessor(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
        }

        public void execute(int k) {
            markOcean();
            List<Lake> lakes = findLakes();
            Collections.sort(lakes);

            if (lakes.size() > k) {
                for (int i = k; i < lakes.size(); i++) {
                    Lake lake = lakes.get(i);
                    filledCellsCount += lake.size;
                    for (Point p : lake.coordinates) {
                        grid[p.r][p.c] = '*';
                    }
                }
            }
            restoreOcean();
        }

        private void markOcean() {
            Queue<Point> queue = new ArrayDeque<>();
            // Check boundaries
            for (int i = 0; i < rows; i++) {
                if (grid[i][0] == '.') queue.add(new Point(i, 0));
                if (grid[i][cols - 1] == '.') queue.add(new Point(i, cols - 1));
            }
            for (int j = 0; j < cols; j++) {
                if (grid[0][j] == '.') queue.add(new Point(0, j));
                if (grid[rows - 1][j] == '.') queue.add(new Point(rows - 1, j));
            }

            // BFS to mark ocean
            boolean[][] visited = new boolean[rows][cols];
            // Initialize visited for boundary points added
            for (Point p : queue) visited[p.r][p.c] = true;

            while (!queue.isEmpty()) {
                Point curr = queue.poll();
                grid[curr.r][curr.c] = OCEAN;

                for (int[] d : directions) {
                    int nr = curr.r + d[0], nc = curr.c + d[1];
                    if (isValid(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        queue.add(new Point(nr, nc));
                    }
                }
            }
        }

        private List<Lake> findLakes() {
            List<Lake> lakes = new ArrayList<>();
            boolean[][] visited = new boolean[rows][cols];

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.' && !visited[i][j]) {
                        lakes.add(bfsLake(i, j, visited));
                    }
                }
            }
            return lakes;
        }

        private Lake bfsLake(int r, int c, boolean[][] visited) {
            Lake lake = new Lake();
            Queue<Point> queue = new ArrayDeque<>();
            queue.add(new Point(r, c));
            visited[r][c] = true;

            while (!queue.isEmpty()) {
                Point curr = queue.poll();
                lake.add(curr.r, curr.c);

                for (int[] d : directions) {
                    int nr = curr.r + d[0], nc = curr.c + d[1];
                    if (isValid(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        queue.add(new Point(nr, nc));
                    }
                }
            }
            return lake;
        }

        private void restoreOcean() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == OCEAN) grid[i][j] = '.';
                }
            }
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        public void printOutput(PrintWriter out) {
            out.println(filledCellsCount);
            for (int i = 0; i < rows; i++) {
                out.println(new String(grid[i]));
            }
        }
    }

    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves the "Lakes in Berland" problem.
 * The goal is to reduce the number of isolated lakes (connected components of '.' 
 * not touching the boundary) to at most k by converting the smallest lakes to '*'.
 */
public class LakesInBerland {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int rows = reader.nextInt();
        int cols = reader.nextInt();
        int maxLakesAllowed = reader.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = reader.next().toCharArray();
        }

        LakeSolver solver = new LakeSolver(rows, cols, grid);
        solver.solve(maxLakesAllowed, out);

        out.flush();
        out.close();
    }

    /**
     * Represents a single coordinate in the grid.
     */
    static class Point {
        final int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Represents an isolated lake found in the grid.
     */
    static class Lake {
        final int size;
        final List<Point> cells;

        Lake(List<Point> cells) {
            this.cells = cells;
            this.size = cells.size();
        }
    }

    /**
     * Contains the core logic for finding and removing lakes.
     */
    static class LakeSolver {
        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final boolean[][] visited;

        // Standard 4-directional movement (Up, Down, Left, Right)
        private static final int[] DR = {-1, 1, 0, 0};
        private static final int[] DC = {0, 0, -1, 1};

        public LakeSolver(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            this.visited = new boolean[rows][cols];
        }

        public void solve(int k, PrintWriter out) {
            List<Lake> lakes = findLakes();

            // Sort lakes by size (ascending) to remove the smallest ones first
            lakes.sort(Comparator.comparingInt(lake -> lake.size));

            int totalDotsRemoved = 0;
            int lakesToRemove = Math.max(0, lakes.size() - k);

            for (int i = 0; i < lakesToRemove; i++) {
                Lake lake = lakes.get(i);
                totalDotsRemoved += lake.size;
                for (Point p : lake.cells) {
                    grid[p.r][p.c] = '*';
                }
            }

            // Output the result
            out.println(totalDotsRemoved);
            for (int i = 0; i < rows; i++) {
                out.println(new String(grid[i]));
            }
        }

        /**
         * Traverses the grid to find all components of '.' that do not touch the boundary.
         */
        private List<Lake> findLakes() {
            List<Lake> lakes = new ArrayList<>();

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.' && !visited[i][j]) {
                        Lake lake = bfs(i, j);
                        if (lake != null) {
                            lakes.add(lake);
                        }
                    }
                }
            }
            return lakes;
        }

        /**
         * Performs BFS to find a connected component of '.' and determines if it's a lake.
         * @return A Lake object if the component is isolated, otherwise null.
         */
        private Lake bfs(int startR, int startC) {
            List<Point> componentCells = new ArrayList<>();
            Queue<Point> queue = new LinkedList<>();

            queue.add(new Point(startR, startC));
            visited[startR][startC] = true;

            boolean touchesBoundary = false;

            while (!queue.isEmpty()) {
                Point curr = queue.poll();
                componentCells.add(curr);

                // Check if the current cell is on the boundary
                if (curr.r == 0 || curr.r == rows - 1 || curr.c == 0 || curr.c == cols - 1) {
                    touchesBoundary = true;
                }

                for (int i = 0; i < 4; i++) {
                    int nr = curr.r + DR[i];
                    int nc = curr.c + DC[i];

                    if (isValid(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        queue.add(new Point(nr, nc));
                    }
                }
            }

            // If the component touches the boundary, it's not a lake
            return touchesBoundary ? null : new Lake(componentCells);
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * High-performance input reader.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A refactored version of the Grid Component Solver.
 * 
 * The program identifies connected components of '.' cells in a grid.
 * It specifically focuses on components that do not touch the grid boundaries.
 * Among these "internal" components, it identifies the smallest ones 
 * to be converted into '*' cells, such that exactly 'k' internal components 
 * remain.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            String firstToken = reader.next();
            if (firstToken == null) return;

            int n = Integer.parseInt(firstToken);
            int m = reader.nextInt();
            int k = reader.nextInt();

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                grid[i] = reader.next().toCharArray();
            }

            GridSolver solver = new GridSolver(n, m, k, grid);
            solver.solve(writer);

        } catch (Exception e) {
            // Handle exceptions silently or log them as per environment requirements
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Encapsulates the logic for solving the grid problem.
     */
    static class GridSolver {
        private final int rows;
        private final int cols;
        private final int k;
        private final char[][] grid;

        // Direction vectors for 4-connectivity (Up, Down, Left, Right)
        private static final int[] DR = {-1, 1, 0, 0};
        private static final int[] DC = {0, 0, -1, 1};

        public GridSolver(int rows, int cols, int k, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.k = k;
            this.grid = grid;
        }

        /**
         * Represents a group of connected '.' cells.
         */
        private static class Component implements Comparable<Component> {
            final int size;
            final int id;

            Component(int size, int id) {
                this.size = size;
                this.id = id;
            }

            @Override
            public int compareTo(Component other) {
                // Sort in ascending order: smallest components first
                return Integer.compare(this.size, other.size);
            }
        }

        /**
         * Executes the component finding and removal logic.
         */
        public void solve(PrintWriter out) {
            int[][] componentIds = new int[rows][cols];
            for (int i = 0; i < rows; i++) {
                Arrays.fill(componentIds[i], -1);
            }

            List<Component> internalComponents = new ArrayList<>();
            int componentCounter = 0;

            // 1. Find all connected components using iterative DFS
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.' && componentIds[i][j] == -1) {
                        Component comp = findComponent(i, j, componentCounter, componentIds);
                        // Only track components that do not touch the boundary
                        if (comp != null) {
                            internalComponents.add(comp);
                        }
                        componentCounter++;
                    }
                }
            }

            // 2. Sort internal components by size (ascending)
            Collections.sort(internalComponents);

            // 3. Determine which components to convert to '*'
            int removedDotsCount = 0;
            boolean[] componentsToMark = new boolean[componentCounter];

            // The objective is to leave exactly 'k' components. 
            // To match original logic, we remove the (total - k) smallest components.
            int numToRemove = internalComponents.size() - k;
            for (int i = 0; i < numToRemove; i++) {
                Component comp = internalComponents.get(i);
                removedDotsCount += comp.size;
                componentsToMark[comp.id] = true;
            }

            // 4. Output the results
            out.println(removedDotsCount);
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (componentIds[i][j] != -1 && componentsToMark[componentIds[i][j]]) {
                        grid[i][j] = '*';
                    }
                }
                out.println(new String(grid[i]));
            }
        }

        /**
         * Performs an iterative DFS to explore a connected component.
         * 
         * @param startR Starting row index.
         * @param startC Starting column index.
         * @param id The unique ID assigned to this component.
         * @param componentIds The 2D array tracking component membership.
         * @return A Component object if the component is "internal" (doesn't touch boundary), else null.
         */
        private Component findComponent(int startR, int startC, int id, int[][] componentIds) {
            Deque<int[]> stack = new ArrayDeque<>();
            stack.push(new int[]{startR, startC});
            componentIds[startR][startC] = id;

            int size = 0;
            boolean touchesBoundary = false;

            while (!stack.isEmpty()) {
                int[] current = stack.pop();
                int r = current[0];
                int c = current[1];
                size++;

                // Check if this specific cell is on the grid boundary
                if (r == 0 || r == rows - 1 || c == 0 || c == cols - 1) {
                    touchesBoundary = true;
                }

                for (int i = 0; i < 4; i++) {
                    int nr = r + DR[i];
                    int nc = c + DC[i];

                    if (isValid(nr, nc) && grid[nr][nc] == '.' && componentIds[nr][nc] == -1) {
                        componentIds[nr][nc] = id;
                        stack.push(new int[]{nr, nc});
                    }
                }
            }

            return touchesBoundary ? null : new Component(size, id);
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * Fast I/O utility class for efficient input reading.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            return next == null ? 0 : Integer.parseInt(next);
        }
    }
}

