/**
 * Represents a single lake found in the grid.
 */
class Lake {
    private final int size;
    private final List<Point> cells;

    public Lake(int size, List<Point> cells) {
        this.size = size;
        this.cells = cells;
    }

    public int getSize() {
        return size;
    }

    public List<Point> getCells() {
        return cells;
    }
