/**
 * Represents a coordinate in the grid.
 */
record Point(int r, int c) {}

/**
 * Manages the logic for identifying, sorting, and modifying lakes in a grid.
 */
class LakeManager {
    private static final int[] DR = {1, -1, 0, 0};
    private static final int[] DC = {0, 0, 1, -1};

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final boolean[][] visited;

    public LakeManager(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.visited = new boolean[rows][cols];
    }

    /**
     * Identifies all lakes and fills the smallest ones with '*' until only k lakes remain.
     * 
     * @param k The number of lakes to keep.
     * @return The total number of cells converted to '*'.
     */
    public int processLakes(int k) {
        List<Lake> allLakes = findAllLakes();

        // Sort lakes by size (ascending) to remove the smallest ones first
        allLakes.sort(Comparator.comparingInt(Lake::getSize));

        int totalCellsRemoved = 0;
        int numToRemove = allLakes.size() - k;

        for (int i = 0; i < numToRemove; i++) {
            Lake lake = allLakes.get(i);
            totalCellsRemoved += lake.getSize();
            for (Point p : lake.getCells()) {
                grid[p.r()][p.c()] = '*';
            }
        }

        return totalCellsRemoved;
    }

    private List<Lake> findAllLakes() {
        List<Lake> lakes = new ArrayList<>();

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.' && !visited[i][j]) {
                    Lake lake = bfsFindLake(i, j);
                    if (lake != null) {
                        lakes.add(lake);
                    }
                }
            }
        }
        return lakes;
    }

    /**
     * Uses BFS to find a connected component of '.' cells.
     * A component is considered a "lake" only if it does not touch the grid boundary.
     */
    private Lake bfsFindLake(int startR, int startC) {
        List<Point> componentCells = new ArrayList<>();
        Deque<Point> queue = new ArrayDeque<>();
        boolean touchesBoundary = false;

        Point start = new Point(startR, startC);
        queue.add(start);
        visited[startR][startC] = true;

        while (!queue.isEmpty()) {
            Point current = queue.poll();
            componentCells.add(current);

            // Check if this cell is on the boundary
            if (current.r() == 0 || current.r() == rows - 1 || 
                current.c() == 0 || current.c() == cols - 1) {
                touchesBoundary = true;
            }

            for (int i = 0; i < 4; i++) {
                int nr = current.r() + DR[i];
                int nc = current.c() + DC[i];

                if (isValid(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    queue.add(new Point(nr, nc));
                }
            }
        }

        // If the component touches the boundary, it's not a lake
        return touchesBoundary ? null : new Lake(componentCells.size(), componentCells);
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

public class Main {

    public static void main(String[] args) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String firstLine = reader.readLine();
            if (firstLine == null) return;

            StringTokenizer st = new StringTokenizer(firstLine);
            int n = Integer.parseInt(st.nextToken());
