class LakeDryingSolver {
    private static final int[] ROW_DIRECTIONS = {0, 0, 1, -1};
    private static final int[] COL_DIRECTIONS = {1, -1, 0, 0};

    private final char[][] grid;
    private final int rows;
    private final int cols;
    private final int targetLakeCount;

    /**
     * Represents a single coordinate in the grid.
     */
    private static class Cell {
        final int r, c;
        Cell(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Represents a lake, containing all its constituent cells.
     */
    private static class Lake implements Comparable<Lake> {
        final List<Cell> cells;
        final int size;

        Lake(List<Cell> cells) {
            this.cells = cells;
            this.size = cells.size();
        }

        @Override
        public int compareTo(Lake other) {
            return Integer.compare(this.size, other.size);
        }
    }

    public LakeDryingSolver(char[][] grid, int rows, int cols, int targetLakeCount) {
        this.grid = grid;
        this.rows = rows;
        this.cols = cols;
        this.targetLakeCount = targetLakeCount;
    }

    public void solve() {
        boolean[][] visited = new boolean[rows][cols];
        List<Lake> lakes = new ArrayList<>();

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && !visited[r][c]) {
                    Lake component = findComponent(r, c, visited);
                    // If the component does not touch the boundary, it's a lake.
                    // The original logic considers edge-connected '.' as "sea".
                    if (!isEdgeConnected(component)) {
                        lakes.add(component);
                    }
                }
            }
        }

        // Sort lakes by size (ascending) to dry the smallest ones first.
        Collections.sort(lakes);

        int lakesToDry = Math.max(0, lakes.size() - targetLakeCount);
        int totalDriedArea = 0;

        for (int i = 0; i < lakesToDry; i++) {
            Lake lakeToDry = lakes.get(i);
            totalDriedArea += lakeToDry.size;
            for (Cell cell : lakeToDry.cells) {
                grid[cell.r][cell.c] = '*';
            }
        }

        printResult(totalDriedArea);
    }

    /**
     * Uses BFS to find all connected '.' cells starting from (startR, startC).
     */
    private Lake findComponent(int startR, int startC, boolean[][] visited) {
        List<Cell> componentCells = new ArrayList<>();
        Queue<Cell> queue = new LinkedList<>();

        Cell start = new Cell(startR, startC);
        queue.add(start);
        visited[startR][startC] = true;

        while (!queue.isEmpty()) {
            Cell current = queue.poll();
            componentCells.add(current);

            for (int i = 0; i < 4; i++) {
                int nr = current.r + ROW_DIRECTIONS[i];
                int nc = current.c + COL_DIRECTIONS[i];

                if (isValid(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    queue.add(new Cell(nr, nc));
                }
            }
        }
        return new Lake(componentCells);
    }

    /**
     * Checks if any cell in the lake component is on the boundary of the grid.
     */
    private boolean isEdgeConnected(Lake lake) {
        for (Cell cell : lake.cells) {
            if (cell.r == 0 || cell.r == rows - 1 || cell.c == 0 || cell.c == cols - 1) {
                return true;
            }
        }
        return false;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private void printResult(int driedArea) {
        System.out.println(driedArea);
        StringBuilder sb = new StringBuilder();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                sb.append(grid[r][c]);
            }
            sb.append('\n');
        }
        System.out.print(sb.toString());
    }
}

