/**
 * Handles the grid logic, finding and filling enclosed islands.
 */
class IslandManager {
    private static final int[][] DIRECTIONS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final boolean[][] visited;

    public IslandManager(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.visited = new boolean[rows][cols];
    }

    /**
     * Finds all islands of '.' that do not touch the grid boundaries.
     */
    public List<Island> findEnclosedIslands() {
        List<Island> enclosedIslands = new ArrayList<>();

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.' && !visited[i][j]) {
                    Island island = performBFS(i, j);
                    if (island.getSize() > 0 && !touchesBoundary(island)) {
                        enclosedIslands.add(island);
                    }
                }
            }
        }
        return enclosedIslands;
    }

    private Island performBFS(int startX, int startY) {
        List<Point> componentCells = new ArrayList<>();
        Queue<Point> queue = new LinkedList<>();

        Point start = new Point(startX, startY);
        queue.add(start);
        visited[startX][startY] = true;

        while (!queue.isEmpty()) {
            Point curr = queue.poll();
            componentCells.add(curr);

            for (int[] dir : DIRECTIONS) {
                int nx = curr.getX() + dir[0];
                int ny = curr.getY() + dir[1];

                if (isValidMove(nx, ny) && grid[nx][ny] == '.' && !visited[nx][ny]) {
                    visited[nx][ny] = true;
                    queue.add(new Point(nx, ny));
                }
            }
        }
        return new Island(componentCells);
    }

    private boolean touchesBoundary(Island island) {
        for (Point p : island.getCells()) {
            if (p.getX() == 0 || p.getX() == rows - 1 || p.getY() == 0 || p.getY() == cols - 1) {
                return true;
            }
        }
        return false;
    }

    public void fillIsland(Island island) {
        for (Point p : island.getCells()) {
            grid[p.getX()][p.getY()] = '*';
        }
    }

    private boolean isValidMove(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    public void printGrid() {
        for (int i = 0; i < rows; i++) {
            System.out.println(new String(grid[i]));
        }
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        int k = scanner.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        IslandManager manager = new IslandManager(rows, cols, grid);
        List<Island> islands = manager.findEnclosedIslands();

        // Sort islands by size (ascending)
        islands.sort(Comparator.comparingInt(Island::getSize));

        int totalFilledCells = 0;
        // The requirement: fill (total - k) smallest islands
        int islandsToFill = islands.size() - k;

        for (int i = 0; i < islandsToFill; i++) {
            Island target = islands.get(i);
            totalFilledCells += target.getSize();
            manager.fillIsland(target);
        }

        System.out.println(totalFilledCells);
        manager.printGrid();

        scanner.close();
    }
}

