/**
 * Represents a coordinate on the grid.
 * Using a record ensures proper equals() and hashCode() implementation,
 * which is essential when using coordinates in Sets or Maps.
 */
record Point(int row, int col) {}

/**
 * Manages the grid operations, specifically finding and processing "lakes".
 * A lake is defined as a connected component of '.' that does not touch the grid boundaries.
 */
class LakeManager {
    private static final int[] DR = {0, 0, -1, 1};
    private static final int[] DC = {-1, 1, 0, 0};

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final boolean[][] visited;

    public LakeManager(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.visited = new boolean[rows][cols];
    }

    /**
     * Finds all valid lakes (connected components of '.' not touching the edge).
     * @return A list of sets, where each set contains the points of a single lake.
     */
    public List<Set<Point>> findLakes() {
        List<Set<Point>> lakes = new ArrayList<>();

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && !visited[r][c]) {
                    Set<Point> component = bfs(r, c);
                    if (component != null) {
                        lakes.add(component);
                    }
                }
            }
        }
        return lakes;
    }

    /**
     * Performs BFS to find a connected component.
     * @return A set of points if the component is a lake, or null if it touches the boundary.
     */
    private Set<Point> bfs(int startRow, int startCol) {
        Set<Point> component = new HashSet<>();
        Queue<Point> queue = new LinkedList<>();
        boolean touchesEdge = false;

        Point start = new Point(startRow, startCol);
        queue.add(start);
        visited[startRow][startCol] = true;

        while (!queue.isEmpty()) {
            Point current = queue.poll();
            component.add(current);

            // Check if current point is on the boundary
            if (current.row() == 0 || current.row() == rows - 1 ||
                current.col() == 0 || current.col() == cols - 1) {
                touchesEdge = true;
            }

            for (int i = 0; i < 4; i++) {
                int nr = current.row() + DR[i];
                int nc = current.col() + DC[i];

                if (isValidMove(nr, nc)) {
                    visited[nr][nc] = true;
                    queue.add(new Point(nr, nc));
                }
            }
        }

        // If the component touched the edge, it is not a lake.
        return touchesEdge ? null : component;
    }

    private boolean isValidMove(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols 
                && grid[r][c] == '.' && !visited[r][c];
    }

    /**
     * Fills the smallest lakes with '*' until only K lakes remain.
     * @param k The number of largest lakes to keep.
     * @return The total number of '.' cells converted to '*'.
     */
    public int fillSmallestLakes(int k) {
        List<Set<Point>> lakes = findLakes();

        // Sort lakes by size in ascending order
        lakes.sort(Comparator.comparingInt(Set::size));

        int filledCount = 0;
        int lakesToRemove = lakes.size() - k;

        for (int i = 0; i < lakesToRemove; i++) {
            for (Point p : lakes.get(i)) {
                grid[p.row()][p.col()] = '*';
                filledCount++;
            }
        }
        return filledCount;
    }

    public void printGrid() {
        for (int r = 0; r < rows; r++) {
            System.out.println(new String(grid[r]));
        }
    }
}

