/**
 * A refactored solution for the Lake Filling problem.
 * The goal is to identify enclosed water components (lakes) and fill the smallest 
 * ones until the number of lakes remaining is at most k.
 */
public class Main {
    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);

        // Read N, M, and K
        String firstLine = sc.next();
        if (firstLine == null) return;

        int n = Integer.parseInt(firstLine);
        int m = sc.nextInt();
        int k = sc.nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = sc.next().toCharArray();
        }

        LakeSolver solver = new LakeSolver(n, m, k, grid);
        solver.solve();
    }

    /**
     * Encapsulates the logic for identifying, sorting, and filling lakes.
     */
    static class LakeSolver {
        private final int rows;
        private final int cols;
        private final int maxAllowedLakes;
        private final char[][] grid;

        private static final int[] DR = {-1, 0, 1, 0};
        private static final int[] DC = {0, 1, 0, -1};

        public LakeSolver(int rows, int cols, int maxAllowedLakes, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.maxAllowedLakes = maxAllowedLakes;
            this.grid = grid;
        }

        public void solve() {
            // Map grid to a boolean representation of water
            boolean[][] isWater = new boolean[rows][cols];
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    isWater[i][j] = (grid[i][j] == '.');
                }
            }

            // 1. Identify water connected to the boundary (not lakes)
            boolean[][] isEdgeConnected = markEdgeConnectedWater(isWater);

            // 2. Find all enclosed lakes
            List<Lake> lakes = findLakes(isWater, isEdgeConnected);

            // 3. Sort lakes by size to fill the smallest ones first
            Collections.sort(lakes);

            // 4. If lakes exceed k, fill the smallest ones by turning '.' into '*'
            int lakesToFill = Math.max(0, lakes.size() - maxAllowedLakes);
            for (int i = 0; i < lakesToFill; i++) {
                for (Point p : lakes.get(i).cells) {
                    isWater[p.r][p.c] = false;
                }
            }

            printGrid(isWater);
        }

        /**
         * Uses BFS to find all water cells connected to the grid boundary.
         */
        private boolean[][] markEdgeConnectedWater(boolean[][] isWater) {
            boolean[][] edgeConnected = new boolean[rows][cols];
            Queue<Point> queue = new ArrayDeque<>();

            // Initialize queue with all water cells on the boundary
            for (int i = 0; i < rows; i++) {
                checkAndAddBoundary(i, 0, isWater, edgeConnected, queue);
                checkAndAddBoundary(i, cols - 1, isWater, edgeConnected, queue);
            }
            for (int j = 0; j < cols; j++) {
                checkAndAddBoundary(0, j, isWater, edgeConnected, queue);
                checkAndAddBoundary(rows - 1, j, isWater, edgeConnected, queue);
            }

            while (!queue.isEmpty()) {
                Point curr = queue.poll();
                for (int i = 0; i < 4; i++) {
                    int nr = curr.r + DR[i];
                    int nc = curr.c + DC[i];
                    if (isValid(nr, nc) && isWater[nr][nc] && !edgeConnected[nr][nc]) {
                        edgeConnected[nr][nc] = true;
                        queue.add(new Point(nr, nc));
                    }
                }
            }
            return edgeConnected;
        }

        private void checkAndAddBoundary(int r, int c, boolean[][] isWater, 
                                        boolean[][] edgeConnected, Queue<Point> queue) {
            if (isWater[r][c] && !edgeConnected[r][c]) {
                edgeConnected[r][c] = true;
                queue.add(new Point(r, c));
            }
        }

        /**
         * Iterates through the grid to find isolated water components.
         */
        private List<Lake> findLakes(boolean[][] isWater, boolean[][] isEdgeConnected) {
            List<Lake> lakes = new ArrayList<>();
            boolean[][] visited = new boolean[rows][cols];

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    // A lake is water that is not connected to the edge and not yet visited
                    if (isWater[i][j] && !isEdgeConnected[i][j] && !visited[i][j]) {
                        List<Point> cells = new ArrayList<>();
                        bfsCollectLakeCells(i, j, isWater, isEdgeConnected, visited, cells);
                        lakes.add(new Lake(cells));
                    }
                }
            }
            return lakes;
        }

        private void bfsCollectLakeCells(int startR, int startC, boolean[][] isWater, 
                                        boolean[][] isEdgeConnected, boolean[][] visited, 
                                        List<Point> cells) {
            Queue<Point> queue = new ArrayDeque<>();
            Point start = new Point(startR, startC);
            queue.add(start);
            visited[startR][startC] = true;

            while (!queue.isEmpty()) {
                Point curr = queue.poll();
                cells.add(curr);

                for (int i = 0; i < 4; i++) {
                    int nr = curr.r + DR[i];
                    int nc = curr.c + DC[i];
                    if (isValid(nr, nc) && isWater[nr][nc] && !isEdgeConnected[nr][nc] && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        queue.add(new Point(nr, nc));
                    }
                }
            }
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        private void printGrid(boolean[][] isWater) {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    sb.append(isWater[i][j] ? '.' : '*');
                }
                sb.append('\n');
            }
            System.out.print(sb.toString());
        }
    }

    /**
     * Represents a coordinate in the grid.
     */
    static class Point {
        final int r, c;
        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Represents a lake component.
     */
    static class Lake implements Comparable<Lake> {
        final List<Point> cells;
        final int size;

        Lake(List<Point> cells) {
            this.cells = cells;
            this.size = cells.size();
        }

        @Override
        public int compareTo(Lake other) {
            return Integer.compare(this.size, other.size);
        }
    }

    /**
     * High-performance input reader.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

