/**
 * Manages the grid and the logic for identifying and filling lakes.
 */
class LakeManager {
    private static final int[][] DIRECTIONS = {
        {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    private final char[][] grid;
    private final int rows;
    private final int cols;

    public LakeManager(char[][] grid) {
        this.grid = grid;
        this.rows = grid.length;
        this.cols = grid[0].length;
    }

    /**
     * Identifies lakes, sorts them by size, and fills the smallest ones
     * until only targetLakeCount lakes remain.
     * 
     * @param targetLakeCount The number of largest lakes to keep.
     * @return The total number of cells filled with '*'.
     */
    public int process(int targetLakeCount) {
        List<Lake> lakes = findLakes();

        // Sort lakes by size in ascending order (smallest first)
        lakes.sort(Comparator.comparingInt(Lake::size));

        // We want to keep the 'targetLakeCount' largest lakes.
        // Therefore, we fill the first (total - targetLakeCount) smallest lakes.
        int numToFill = Math.max(0, lakes.size() - targetLakeCount);
        int totalFilledCells = 0;

        for (int i = 0; i < numToFill; i++) {
            Lake lake = lakes.get(i);
            totalFilledCells += lake.size();
            fillLake(lake.startRow, lake.startCol);
        }

        return totalFilledCells;
    }

    /**
     * Uses BFS to find all connected components of '.' that do not touch the grid boundary.
     */
    private List<Lake> findLakes() {
        List<Lake> lakes = new ArrayList<>();
        boolean[][] visited = new boolean[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && !visited[r][c]) {
                    ComponentInfo component = bfsIdentifyComponent(r, c, visited);
                    if (!component.touchesBoundary) {
                        lakes.add(new Lake(component.size, component.startR, component.startC));
                    }
                }
            }
        }
        return lakes;
    }

    /**
     * Iterative BFS to explore a component and check if it touches the boundary.
     */
    private ComponentInfo bfsIdentifyComponent(int startR, int startC, boolean[][] visited) {
        int size = 0;
        boolean touchesBoundary = false;
        Queue<Coordinate> queue = new ArrayDeque<>();

        queue.add(new Coordinate(startR, startC));
        visited[startR][startC] = true;

        while (!queue.isEmpty()) {
            Coordinate curr = queue.poll();
            size++;

            if (curr.isBoundary(rows, cols)) {
                touchesBoundary = true;
            }

            for (int[] dir : DIRECTIONS) {
                int nr = curr.row + dir[0];
                int nc = curr.col + dir[1];

                if (isValidMove(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    queue.add(new Coordinate(nr, nc));
                }
            }
        }
        return new ComponentInfo(size, touchesBoundary, startR, startC);
    }

    /**
     * Iterative BFS to fill a lake component with '*' characters.
     */
    private void fillLake(int startR, int startC) {
        Queue<Coordinate> queue = new ArrayDeque<>();
        queue.add(new Coordinate(startR, startC));
        grid[startR][startC] = '*';

        while (!queue.isEmpty()) {
            Coordinate curr = queue.poll();

            for (int[] dir : DIRECTIONS) {
                int nr = curr.row + dir[0];
                int nc = curr.col + dir[1];

                if (isValidMove(nr, nc) && grid[nr][nc] == '.') {
                    grid[nr][nc] = '*';
                    queue.add(new Coordinate(nr, nc));
                }
            }
        }
    }

    private boolean isValidMove(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    public char[][] getGrid() {
        return grid;
    }

    // --- Helper Data Structures ---

    private static class Coordinate {
        final int row;
        final int col;

        Coordinate(int row, int col) {
            this.row = row;
            this.col = col;
        }

        boolean isBoundary(int rows, int cols) {
            return row == 0 || row == rows - 1 || col == 0 || col == cols - 1;
        }
    }

    private static class Lake {
        private final int size;
        private final int startRow;
        private final int startCol;

        Lake(int size, int startRow, int startCol) {
            this.size = size;
            this.startRow = startRow;
            this.startCol = startCol;
        }

        int size() { return size; }
    }

    /**
     * Temporary holder for BFS results during component discovery.
     */
    private static class ComponentInfo {
        final int size;
        final boolean touchesBoundary;
        final int startR;
        final int startC;

        ComponentInfo(int size, boolean touchesBoundary, int startR, int startC) {
            this.size = size;
            this.touchesBoundary = touchesBoundary;
            this.startR = startR;
            this.startC = startC;
        }
    }
}

