/**
 * Represents a coordinate in the 2D grid.
 */
record Coordinate(int row, int col) {}

/**
 * Represents a connected component of water cells.
 */
class Lake {
    private final List<Coordinate> cells;

    public Lake(List<Coordinate> cells) {
        this.cells = cells;
    }

    public int getSize() {
        return cells.size();
    }

    public List<Coordinate> getCells() {
        return cells;
    }
}

/**
 * Manages the logic for identifying and manipulating lakes in a grid.
 */
class LakeManager {
    private static final int[] ROW_DELTA = {0, 0, 1, -1};
    private static final int[] COL_DELTA = {1, -1, 0, 0};

    private final int rows;
    private final int cols;
    private final char[][] grid;

    public LakeManager(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
    }

    /**
     * Processes the grid to fill the smallest lakes until only K lakes remain.
     * @param targetLakeCount The desired number of lakes to remain.
     * @return The total number of water cells filled with land.
     */
    public int reduceLakesToCount(int targetLakeCount) {
        List<Lake> lakes = findLakes();

        // Sort lakes by size ascending to ensure we fill the smallest ones first
        lakes.sort(Comparator.comparingInt(Lake::getSize));

        int lakesToRemove = Math.max(0, lakes.size() - targetLakeCount);
        int totalCellsFilled = 0;

        for (int i = 0; i < lakesToRemove; i++) {
            Lake lakeToFill = lakes.get(i);
            totalCellsFilled += lakeToFill.getSize();
            for (Coordinate coord : lakeToFill.getCells()) {
                grid[coord.row()][coord.col()] = '*';
            }
        }

        return totalCellsFilled;
    }

    /**
     * Finds all connected water components that do not touch the boundary.
     */
    private List<Lake> findLakes() {
        List<Lake> lakes = new ArrayList<>();
        boolean[][] visited = new boolean[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && !visited[r][c]) {
                    List<Coordinate> component = new ArrayList<>();
                    boolean touchesEdge = bfs(r, c, visited, component);

                    // If the component doesn't touch the edge, it's a lake
                    if (!touchesEdge) {
                        lakes.add(new Lake(component));
                    }
                }
            }
        }
        return lakes;
    }

    /**
     * Standard BFS to find all connected water cells.
     * @return true if the component touches the boundary of the grid.
     */
    private boolean bfs(int startR, int startC, boolean[][] visited, List<Coordinate> component) {
        Queue<Coordinate> queue = new LinkedList<>();
        Coordinate start = new Coordinate(startR, startC);

        queue.add(start);
        visited[startR][startC] = true;

        boolean touchesEdge = false;

        while (!queue.isEmpty()) {
            Coordinate curr = queue.poll();
            component.add(curr);

            // Check if this cell is on the boundary
            if (curr.row() == 0 || curr.row() == rows - 1 || 
                curr.col() == 0 || curr.col() == cols - 1) {
                touchesEdge = true;
            }

            for (int i = 0; i < 4; i++) {
                int nr = curr.row() + ROW_DELTA[i];
                int nc = curr.col() + COL_DELTA[i];

                if (isValid(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    queue.add(new Coordinate(nr, nc));
                }
            }
        }
        return touchesEdge;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        if (!sc.hasNextInt()) return;
        int n = sc.nextInt();
        int m = sc.nextInt();
        int k = sc.nextInt();
        sc.nextLine(); // Consume newline

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String line = sc.nextLine();
            grid[i] = line.toCharArray();
        }

        LakeManager manager = new LakeManager(n, m, grid);
        int erasedCells = manager.reduceLakesToCount(k);

        // Output results
        System.out.println(erasedCells);
        printGrid(grid);

        sc.close();
    }

    private static void printGrid(char[][] grid) {
        StringBuilder sb = new StringBuilder();
        for (char[] row : grid) {
            sb.append(new String(row)).append("\n");
        }
        System.out.print(sb.toString());
    }
}

import java.util.*;
import java.io.*;

/**
 * Manages a grid of cells and performs operations to remove specific 
 * internal connected components (islands) to meet a target count.
 */
public class GridIslandManager {

    private static final char EMPTY_CELL = '.';
    private static final char FILLED_CELL = '*';

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            int rowCount = reader.nextInt();
            int colCount = reader.nextInt();
            int targetInternalComponents = reader.nextInt();

            char[][] grid = new char[rowCount][colCount];
            for (int r = 0; r < rowCount; r++) {
                grid[r] = reader.next().toCharArray();
            }

            GridProcessor processor = new GridProcessor(grid, rowCount, colCount);
            processor.process(targetInternalComponents);

            writer.println(processor.getRemovedCellCount());
            for (char[] row : processor.getGrid()) {
                writer.println(new String(row));
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    /**
     * Core logic for analyzing the grid and removing components.
     */
    static class GridProcessor {
        private final char[][] grid;
        private final int rows;
        private final int cols;
        private int removedCellCount = 0;

        public GridProcessor(char[][] grid, int rows, int cols) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
        }

        public void process(int targetInternalCount) {
            DisjointSetUnion dsu = buildConnectivity();

            Map<Integer, Integer> componentSizes = new HashMap<>();
            Set<Integer> allComponentRoots = new HashSet<>();
            Set<Integer> borderComponentRoots = new HashSet<>();

            // Analyze components and identify which ones touch the border
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == EMPTY_CELL) {
                        int cellIndex = r * cols + c;
                        int root = dsu.find(cellIndex);

                        allComponentRoots.add(root);
                        componentSizes.put(root, componentSizes.getOrDefault(root, 0) + 1);

                        if (isBorderCell(r, c)) {
                            borderComponentRoots.add(root);
                        }
                    }
                }
            }

            // Identify internal components (those not touching the border)
            List<ComponentInfo> internalComponents = new ArrayList<>();
            for (int root : allComponentRoots) {
                if (!borderComponentRoots.contains(root)) {
                    internalComponents.add(new ComponentInfo(root, componentSizes.get(root)));
                }
            }

            // Determine how many internal components must be removed
            int numToRemove = Math.max(0, internalComponents.size() - targetInternalCount);

            // Sort internal components by size (ascending) to remove the smallest ones first
            internalComponents.sort(Comparator.comparingInt(ComponentInfo::size));

            Set<Integer> rootsToRemove = new HashSet<>();
            for (int i = 0; i < numToRemove; i++) {
                rootsToRemove.add(internalComponents.get(i).root());
            }

            // Apply removal to the grid
            applyRemoval(dsu, rootsToRemove);
        }

        private DisjointSetUnion buildConnectivity() {
            DisjointSetUnion dsu = new DisjointSetUnion(rows * cols);
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == EMPTY_CELL) {
                        // Check neighbor above
                        if (r > 0 && grid[r - 1][c] == EMPTY_CELL) {
                            dsu.union(r * cols + c, (r - 1) * cols + c);
                        }
                        // Check neighbor to the left
                        if (c > 0 && grid[r][c - 1] == EMPTY_CELL) {
                            dsu.union(r * cols + c, r * cols + (c - 1));
                        }
                    }
                }
            }
            return dsu;
        }

        private boolean isBorderCell(int r, int c) {
            return r == 0 || r == rows - 1 || c == 0 || c == cols - 1;
        }

        private void applyRemoval(DisjointSetUnion dsu, Set<Integer> rootsToRemove) {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == EMPTY_CELL) {
                        int root = dsu.find(r * cols + c);
                        if (rootsToRemove.contains(root)) {
                            grid[r][c] = FILLED_CELL;
                            removedCellCount++;
                        }
                    }
                }
            }
        }

        public char[][] getGrid() { return grid; }
        public int getRemovedCellCount() { return removedCellCount; }

        private record ComponentInfo(int root, int size) {}
    }

    /**
     * Disjoint Set Union (DSU) with Path Compression and Union by Size.
     */
    static class DisjointSetUnion {
        private final int[] parent;
        private final int[] size;

        public DisjointSetUnion(int n) {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        public int find(int i) {
            if (parent[i] == i) {
                return i;
            }
            return parent[i] = find(parent[i]); // Path compression
        }

        public void union(int i, int j) {
            int rootI = find(i);
            int rootJ = find(j);
            if (rootI != rootJ) {
                // Union by size
                if (size[rootI] < size[rootJ]) {
                    parent[rootI] = rootJ;
                    size[rootJ] += size[rootI];
                } else {
                    parent[rootJ] = rootI;
                    size[rootI] += size[rootJ];
                }
            }
        }
    }

    /**
     * High-performance input reader.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.util.*;

/**
 * A program that identifies connected components (islands) in a grid.
 * It distinguishes between boundary-touching components and internal components.
 * It then keeps the K largest internal components and "fills" the rest.
 */
public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        int k = scanner.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
            }
        }

        GridSolver solver = new GridSolver(grid, rows, cols);
        solver.solve(k);
        solver.printResult();

        scanner.close();
    }
}

/**
 * Represents a connected component of '.' cells.
 */
class Component {
    final int startX;
    final int startY;
    final int size;

    Component(int startX, int startY, int size) {
        this.startX = startX;
        this.startY = startY;
        this.size = size;
    }
}

/**
 * Handles the logic of finding, sorting, and modifying grid components.
 */
class GridSolver {
    private final int rows;
    private final int cols;
    private final char[][] originalGrid;
    private final char[][] workingGrid;
    private int removedCellCount = 0;

    private static final int[] DX = {1, -1, 0, 0};
    private static final int[] DY = {0, 0, 1, -1};

    public GridSolver(char[][] grid, int rows, int cols) {
        this.rows = rows;
        this.cols = cols;
        this.originalGrid = grid;
        this.workingGrid = new char[rows][cols];
        // Deep copy the grid to maintain a working copy
        for (int i = 0; i < rows; i++) {
            System.arraycopy(grid[i], 0, workingGrid[i], 0, cols);
        }
    }

    /**
     * Executes the core logic: find internal components, sort them, 
     * and fill the smallest ones if they exceed the capacity K.
     */
    public void solve(int k) {
        boolean[][] visited = new boolean[rows][cols];

        // 1. Identify and mark all components that touch the grid boundaries.
        // These are not considered "internal" components.
        for (int i = 0; i < rows; i++) {
            if (isDot(i, 0, visited)) markComponent(i, 0, visited);
            if (isDot(i, cols - 1, visited)) markComponent(i, cols - 1, visited);
        }
        for (int j = 0; j < cols; j++) {
            if (isDot(0, j, visited)) markComponent(0, j, visited);
            if (isDot(rows - 1, j, visited)) markComponent(rows - 1, j, visited);
        }

        // 2. Identify all remaining components (internal components).
        List<Component> internalComponents = new ArrayList<>();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (isDot(i, j, visited)) {
                    int size = markComponent(i, j, visited);
                    internalComponents.add(new Component(i, j, size));
                }
            }
        }

        // 3. Sort internal components by size ascending.
        internalComponents.sort(Comparator.comparingInt(c -> c.size));

        // 4. Calculate how many internal components must be removed to keep only K.
        int numToRemove = internalComponents.size() - k;
        for (int i = 0; i < numToRemove; i++) {
            Component comp = internalComponents.get(i);
            removedCellCount += comp.size;
            fillComponent(comp.startX, comp.startY, '*');
        }
    }

    private boolean isDot(int r, int c, boolean[][] visited) {
        return r >= 0 && r < rows && c >= 0 && c < cols 
               && originalGrid[r][c] == '.' && !visited[r][c];
    }

    /**
     * Uses BFS to mark a component as visited and return its total size.
     */
    private int markComponent(int startR, int startC, boolean[][] visited) {
        int size = 0;
        Queue<int[]> queue = new LinkedList<>();

        queue.add(new int[]{startR, startC});
        visited[startR][startC] = true;

        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            size++;

            for (int i = 0; i < 4; i++) {
                int nr = curr[0] + DX[i];
                int nc = curr[1] + DY[i];
                if (isDot(nr, nc, visited)) {
                    visited[nr][nc] = true;
                    queue.add(new int[]{nr, nc});
                }
            }
        }
        return size;
    }

    /**
     * Uses BFS to fill a component in the workingGrid with a specific character.
     */
    private void fillComponent(int startR, int startC, char fillChar) {
        Queue<int[]> queue = new LinkedList<>();
        queue.add(new int[]{startR, startC});
        workingGrid[startR][startC] = fillChar;

        while (!queue.isEmpty()) {
            int[] curr = queue.poll();

            for (int i = 0; i < 4; i++) {
                int nr = curr[0] + DX[i];
                int nc = curr[1] + DY[i];

                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols 
                    && workingGrid[nr][nc] == '.') {
                    workingGrid[nr][nc] = fillChar;
                    queue.add(new int[]{nr, nc});
                }
            }
        }
    }

    public void printResult() {
        System.out.println(removedCellCount);
        for (int i = 0; i < rows; i++) {
            System.out.println(new String(workingGrid[i]));
        }
    }
}

