/**
 * Represents a lake identified within the grid.
 */
final class Lake implements Comparable<Lake> {
    private final int row;
    private final int col;
    private final int size;

    public Lake(int row, int col, int size) {
        this.row = row;
        this.col = col;
        this.size = size;
    }

    public int getRow() { return row; }
    public int getCol() { return col; }
    public int getSize() { return size; }

