    public int compareTo(Lake other) {
        // Sort by size ascending (smallest lakes first)
        return Integer.compare(this.size, other.size);
    }
}

/**
 * Handles the logic for identifying and filling lakes in a grid.
 */
class WaterGridProcessor {
    private static final int[] ROW_DIRECTIONS = {-1, 1, 0, 0};
    private static final int[] COL_DIRECTIONS = {0, 0, 1, -1};

    private final int rowCount;
    private final int colCount;
    private final char[][] grid;

    public WaterGridProcessor(int rows, int cols, char[][] grid) {
        this.rowCount = rows;
        this.colCount = cols;
        this.grid = grid;
    }

    /**
     * Processes the grid to fill the smallest lakes until only maxLakes remain.
     * @param maxLakes The number of lakes to keep.
     * @return The total number of cells filled.
     */
    public int process(int maxLakes) {
        markBoundaryOceans();
        PriorityQueue<Lake> lakes = identifyLakes();

        int totalFilledCells = 0;
        while (lakes.size() > maxLakes) {
            Lake smallestLake = lakes.poll();
            totalFilledCells += smallestLake.getSize();
            floodFill(smallestLake.getRow(), smallestLake.getCol(), 'L', '*');
        }

        cleanupGrid();
        return totalFilledCells;
    }

    /**
     * Marks all '.' cells connected to the boundary as 'O' (Ocean).
     */
    private void markBoundaryOceans() {
        for (int i = 0; i < rowCount; i++) {
            if (grid[i][0] == '.') floodFill(i, 0, '.', 'O');
            if (grid[i][colCount - 1] == '.') floodFill(i, colCount - 1, '.', 'O');
        }
        for (int j = 0; j < colCount; j++) {
            if (grid[0][j] == '.') floodFill(0, j, '.', 'O');
            if (grid[rowCount - 1][j] == '.') floodFill(rowCount - 1, j, '.', 'O');
        }
    }

    /**
     * Finds all connected components of '.' (Lakes) and stores them in a PriorityQueue.
     */
    private PriorityQueue<Lake> identifyLakes() {
        PriorityQueue<Lake> lakeQueue = new PriorityQueue<>();
        for (int i = 0; i < rowCount; i++) {
            for (int j = 0; j < colCount; j++) {
                if (grid[i][j] == '.') {
                    int size = floodFill(i, j, '.', 'L');
                    lakeQueue.add(new Lake(i, j, size));
                }
            }
        }
        return lakeQueue;
    }

    /**
     * Performs an iterative BFS flood fill to avoid StackOverflowError.
     * @return The number of cells filled during this operation.
     */
    private int floodFill(int startRow, int startCol, char target, char replacement) {
        int count = 0;
        Queue<int[]> queue = new ArrayDeque<>();

        if (isValid(startRow, startCol) && grid[startRow][startCol] == target) {
            grid[startRow][startCol] = replacement;
            queue.add(new int[]{startRow, startCol});
            count++;
        }

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int r = current[0];
            int c = current[1];

            for (int i = 0; i < 4; i++) {
                int nextR = r + ROW_DIRECTIONS[i];
                int nextC = c + COL_DIRECTIONS[i];

                if (isValid(nextR, nextC) && grid[nextR][nextC] == target) {
                    grid[nextR][nextC] = replacement;
                    count++;
                    queue.add(new int[]{nextR, nextC});
                }
            }
        }
        return count;
    }

    /**
     * Resets 'L' (Lakes) and 'O' (Oceans) back to '.' for final output.
     */
    private void cleanupGrid() {
        for (int i = 0; i < rowCount; i++) {
            for (int j = 0; j < colCount; j++) {
                if (grid[i][j] == 'L' || grid[i][j] == 'O') {
                    grid[i][j] = '.';
                }
            }
        }
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rowCount && c >= 0 && c < colCount;
    }

    public void printGrid() {
        for (int i = 0; i < rowCount; i++) {
            System.out.println(new String(grid[i]));
        }
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        if (!sc.hasNextInt()) return;
        int rows = sc.nextInt();
        int cols = sc.nextInt();
        int maxLakes = sc.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = sc.next().toCharArray();
        }

        WaterGridProcessor processor = new WaterGridProcessor(rows, cols, grid);
        int filledCount = processor.process(maxLakes);

        System.out.println(filledCount);
        processor.printGrid();

        sc.close();
    }
}

