        }
    }

    private void solve(char[][] grid, int rows, int cols, int k, PrintWriter out) {
        int[][] lakeIdMap = new int[rows][cols];
        List<Lake> validLakes = new ArrayList<>();
        int currentLakeId = 1;

        // 1. Identify all connected components (lakes and seas)
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && lakeIdMap[r][c] == 0) {
                    Lake component = bfs(grid, lakeIdMap, r, c, rows, cols, currentLakeId);
                    if (!component.touchesBoundary) {
                        validLakes.add(new Lake(currentLakeId, component.size, false));
                    }
                    currentLakeId++;
                }
            }
        }

        // 2. Determine which lakes to remove (the smallest ones)
        Collections.sort(validLakes);

        int totalAreaRemoved = 0;
        Set<Integer> idsToRemove = new HashSet<>();
        int lakesToRemoveCount = Math.max(0, validLakes.size() - k);

        for (int i = 0; i < lakesToRemoveCount; i++) {
            Lake lake = validLakes.get(i);
            totalAreaRemoved += lake.size;
            idsToRemove.add(lake.id);
        }

        // 3. Transform the grid by filling removed lakes with '*'
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (idsToRemove.contains(lakeIdMap[r][c])) {
                    grid[r][c] = '*';
                }
            }
        }

        // 4. Output results
        out.println(totalAreaRemoved);
        for (int r = 0; r < rows; r++) {
            out.println(new String(grid[r]));
        }
    }

    /**
     * Performs an iterative BFS to find the size and boundary status of a water component.
     */
    private Lake bfs(char[][] grid, int[][] lakeIdMap, int startR, int startC, int rows, int cols, int id) {
        int size = 0;
        boolean touchesBoundary = false;
        Deque<int[]> queue = new ArrayDeque<>();

        queue.add(new int[]{startR, startC});
        lakeIdMap[startR][startC] = id;

        while (!queue.isEmpty()) {
            int[] cell = queue.poll();
            int r = cell[0];
            int c = cell[1];
            size++;

            if (r == 0 || r == rows - 1 || c == 0 || c == cols - 1) {
                touchesBoundary = true;
            }

            for (int i = 0; i < 4; i++) {
                int nr = r + DIRECTIONS_R[i];
                int nc = c + DIRECTIONS_C[i];

                if (isValid(nr, nc, rows, cols) && grid[nr][nc] == '.' && lakeIdMap[nr][nc] == 0) {
                    lakeIdMap[nr][nc] = id;
                    queue.add(new int[]{nr, nc});
                }
            }
        }

        return new Lake(id, size, touchesBoundary);
    }

    private boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Data model representing a lake.
     */
    private static class Lake implements Comparable<Lake> {
        final int id;
        final int size;
        final boolean touchesBoundary;

        Lake(int id, int size, boolean touchesBoundary) {
            this.id = id;
            this.size = size;
            this.touchesBoundary = touchesBoundary;
        }

        @Override
        public int compareTo(Lake other) {
            return Integer.compare(this.size, other.size);
        }
    }

    /**
     * High-performance input reader.
     */
    private static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * LakeManager identifies "lakes" in a grid (components of '.' not touching the boundary)
 * and fills the smallest lakes with '*' until only K lakes remain.
 */
public class LakeManager {

    private static final int[] ROW_OFFSETS = {-1, 0, 1, 0};
    private static final int[] COL_OFFSETS = {0, 1, 0, -1};

    public static void main(String[] args) {
        FastReader sc = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int rows = sc.nextInt();
            int cols = sc.nextInt();
            int targetLakeCount = sc.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = sc.next().toCharArray();
            }

            LakeManager manager = new LakeManager();
            manager.processLakes(grid, rows, cols, targetLakeCount, out);

        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    private void processLakes(char[][] grid, int rows, int cols, int k, PrintWriter out) {
        boolean[][] visited = new boolean[rows][cols];
        List<Lake> lakes = new ArrayList<>();

        // 1. Discover all components using BFS
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && !visited[r][c]) {
                    Lake component = findComponent(grid, visited, r, c, rows, cols);
                    // A component is a lake only if it doesn't touch the boundary
                    if (!component.touchesBoundary) {
                        lakes.add(component);
                    }
                }
            }
        }

        // 2. Sort lakes by size to identify the smallest ones to fill
        Collections.sort(lakes, Comparator.comparingInt(lake -> lake.size));

        // 3. Fill the smallest lakes until we reach the target count K
        int totalFilledArea = 0;
        int lakesToRemove = lakes.size() - k;

        for (int i = 0; i < lakesToRemove; i++) {
            Lake lakeToFill = lakes.get(i);
            totalFilledArea += lakeToFill.size;
            for (Point p : lakeToFill.cells) {
                grid[p.r][p.c] = '*';
            }
        }

        // 4. Output results
        out.println(totalFilledArea);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < rows; i++) {
            sb.append(new String(grid[i])).append("\n");
        }
        out.print(sb.toString());
    }

    /**
     * Performs BFS to find all connected '.' cells in a component.
     */
    private Lake findComponent(char[][] grid, boolean[][] visited, int startR, int startC, int rows, int cols) {
        List<Point> componentCells = new ArrayList<>();
        Deque<Point> queue = new ArrayDeque<>();
        boolean touchesBoundary = false;

        Point start = new Point(startR, startC);
        queue.add(start);
        visited[startR][startC] = true;

        while (!queue.isEmpty()) {
            Point curr = queue.poll();
            componentCells.add(curr);

            // Check if this cell is on the edge of the grid
            if (curr.r == 0 || curr.r == rows - 1 || curr.c == 0 || curr.c == cols - 1) {
                touchesBoundary = true;
            }

            for (int i = 0; i < 4; i++) {
                int nextR = curr.r + ROW_OFFSETS[i];
                int nextC = curr.c + COL_OFFSETS[i];

                if (isInside(nextR, nextC, rows, cols) && 
                    grid[nextR][nextC] == '.' && 
                    !visited[nextR][nextC]) {

                    visited[nextR][nextC] = true;
                    queue.add(new Point(nextR, nextC));
                }
            }
        }

        return new Lake(componentCells, touchesBoundary);
    }

    private boolean isInside(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Represents a single cell coordinate.
     */
    private static class Point {
        int r, c;
        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Represents a discovered component of '.' cells.
     */
    private static class Lake {
        List<Point> cells;
        int size;
        boolean touchesBoundary;

        Lake(List<Point> cells, boolean touchesBoundary) {
            this.cells = cells;
            this.size = cells.size();
            this.touchesBoundary = touchesBoundary;
        }
    }

    /**
     * High-performance input reader.
     */
    private static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A solver for the grid component removal problem.
 * The goal is to identify internal components (those not touching the grid boundary)
 * and convert the largest k components into '*' characters.
 */
public class GridProblemSolver {

    private static final int[] DIRECTIONS_R = {-1, 1, 0, 0};
    private static final int[] DIRECTIONS_C = {0, 0, -1, 1};

    private int rows;
    private int cols;
    private int maxRemovals;
    private char[][] grid;
    private int cellsChangedToStar;

    public static void main(String[] args) {
        try {
            GridProblemSolver solver = new GridProblemSolver();
            solver.solve();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public void solve() throws IOException {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        // Input parsing
        this.rows = reader.nextInt();
        this.cols = reader.nextInt();
        this.maxRemovals = reader.nextInt();
        this.grid = new char[rows][cols];
        this.cellsChangedToStar = 0;

        for (int i = 0; i < rows; i++) {
            grid[i] = reader.next().toCharArray();
        }

        // 1. Group identical adjacent cells into components using DSU
        DisjointSetUnion dsu = new DisjointSetUnion(rows * cols);
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                for (int i = 0; i < 4; i++) {
                    int nr = r + DIRECTIONS_R[i];
                    int nc = c + DIRECTIONS_C[i];

                    if (isValid(nr, nc) && grid[r][c] == grid[nr][nc]) {
                        dsu.union(r * cols + c, nr * cols + nc);
                    }
                }
            }
        }

        // 2. Identify components that touch the boundary
        Set<Integer> boundaryComponentRoots = new HashSet<>();
        for (int r = 0; r < rows; r++) {
            boundaryComponentRoots.add(dsu.find(r * cols + 0));
            boundaryComponentRoots.add(dsu.find(r * cols + (cols - 1)));
        }
        for (int c = 0; c < cols; c++) {
            boundaryComponentRoots.add(dsu.find(0 * cols + c));
            boundaryComponentRoots.add(dsu.find((rows - 1) * cols + c));
        }

        // 3. Collect all "island" components (not touching boundaries) into a Max-Heap by size
        PriorityQueue<Integer> componentHeap = new PriorityQueue<>(
            (a, b) -> Integer.compare(dsu.getSize(b), dsu.getSize(a))
        );

        boolean[] processedRoot = new boolean[rows * cols];
        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < cols - 1; c++) {
                if (grid[r][c] == '*') continue;

                int root = dsu.find(r * cols + c);
                if (!processedRoot[root] && !boundaryComponentRoots.contains(root)) {
                    componentHeap.add(root);
                    processedRoot[root] = true;
                }
            }
        }

        // 4. Remove the largest k components
        for (int i = 0; i < maxRemovals && !componentHeap.isEmpty(); i++) {
            int rootIdx = componentHeap.poll();
            floodFill(rootIdx / cols, rootIdx % cols);
        }

        // Output results
        writer.println(cellsChangedToStar);
        for (int r = 0; r < rows; r++) {
            writer.println(new String(grid[r]));
        }

        reader.close();
        writer.close();
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Iterative flood fill to avoid StackOverflowError on large grids.
     */
    private void floodFill(int startR, int startC) {
        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{startR, startC});

        while (!stack.isEmpty()) {
            int[] curr = stack.pop();
            int r = curr[0];
            int c = curr[1];

            if (!isValid(r, c) || grid[r][c] == '*') {
                continue;
            }

            grid[r][c] = '*';
            cellsChangedToStar++;

            for (int i = 0; i < 4; i++) {
                stack.push(new int[]{r + DIRECTIONS_R[i], c + DIRECTIONS_C[i]});
            }
        }
    }

    /**
     * Disjoint Set Union (DSU) with path compression and union by size.
     */
    private static class DisjointSetUnion {
        private final int[] parent;
        private final int[] size;

        public DisjointSetUnion(int n) {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        public int find(int i) {
            if (parent[i] == i) return i;
            return parent[i] = find(parent[i]); // Path compression
        }

        public void union(int i, int j) {
            int rootI = find(i);
            int rootJ = find(j);
            if (rootI != rootJ) {
                // Union by size
                if (size[rootI] < size[rootJ]) {
                    parent[rootI] = rootJ;
                    size[rootJ] += size[rootI];
                } else {
                    parent[rootJ] = rootI;
                    size[rootI] += size[rootJ];
                }
            }
        }

        public int getSize(int root) {
            return size[find(root)];
        }
    }

    /**
     * Fast I/O utility for performance.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public void close() throws IOException {
            reader.close();
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * ProblemD Refactored
 * 
 * This program identifies enclosed "lakes" in a grid and fills the smallest 
 * ones until a specific number of lakes remain.
 */
public class ProblemD {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int n = reader.nextInt();
            int m = reader.nextInt();
            int k = reader.nextInt();

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                grid[i] = reader.readLine().toCharArray();
            }

            LakeManager manager = new LakeManager(n, m, grid);
            manager.process(k);

            writer.println(manager.getTotalFilledArea());
            manager.printGrid(writer);

        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Represents an enclosed body of water.
     */
    static class Lake implements Comparable<Lake> {
        private final int startX;
        private final int startY;
        private final int area;

        public Lake(int startX, int startY, int area) {
            this.startX = startX;
            this.startY = startY;
            this.area = area;
        }

        public int getStartX() { return startX; }
        public int getStartY() { return startY; }
        public int getArea() { return area; }

        @Override
        public int compareTo(Lake other) {
            return Integer.compare(this.area, other.area);
        }
    }

    /**
     * Handles the logic for identifying, managing, and filling lakes.
     */
    static class LakeManager {
        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final boolean[][] visited;
        private int totalFilledArea = 0;

        private static final int[] DR = {-1, 1, 0, 0};
        private static final int[] DC = {0, 0, -1, 1};

        public LakeManager(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            this.visited = new boolean[rows][cols];
        }

        public void process(int k) {
            // Phase 1: Mark all '.' cells connected to the boundaries (not lakes)
            markBoundaryConnectedCells();

            // Phase 2: Identify enclosed lakes
            PriorityQueue<Lake> lakes = new PriorityQueue<>();
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.' && !visited[i][j]) {
                        int area = bfsCountArea(i, j);
                        lakes.add(new Lake(i, j, area));
                    }
                }
            }

            // Phase 3: Fill the smallest lakes until 'k' lakes remain
            // Note: Following original logic where we fill until lakes.size() <= k
            while (lakes.size() > k) {
                Lake smallestLake = lakes.poll();
                fillLake(smallestLake.getStartX(), smallestLake.getStartY());
                totalFilledArea += smallestLake.getArea();
            }
        }

        private void markBoundaryConnectedCells() {
            for (int i = 0; i < rows; i++) {
                if (grid[i][0] == '.' && !visited[i][0]) bfsMark(i, 0);
                if (grid[i][cols - 1] == '.' && !visited[i][cols - 1]) bfsMark(i, cols - 1);
            }
            for (int j = 0; j < cols; j++) {
                if (grid[0][j] == '.' && !visited[0][j]) bfsMark(0, j);
                if (grid[rows - 1][j] == '.' && !visited[rows - 1][j]) bfsMark(rows - 1, j);
            }
        }

        private void bfsMark(int startR, int startC) {
            Deque<int[]> queue = new ArrayDeque<>();
            queue.add(new int[]{startR, startC});
            visited[startR][startC] = true;

            while (!queue.isEmpty()) {
                int[] curr = queue.poll();
                for (int i = 0; i < 4; i++) {
                    int nr = curr[0] + DR[i];
                    int nc = curr[1] + DC[i];
                    if (isValid(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        queue.add(new int[]{nr, nc});
                    }
                }
            }
        }

        private int bfsCountArea(int startR, int startC) {
            Deque<int[]> queue = new ArrayDeque<>();
            queue.add(new int[]{startR, startC});
            visited[startR][startC] = true;
            int area = 0;

            while (!queue.isEmpty()) {
                int[] curr = queue.poll();
                area++;
                for (int i = 0; i < 4; i++) {
                    int nr = curr[0] + DR[i];
                    int nc = curr[1] + DC[i];
                    if (isValid(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        queue.add(new int[]{nr, nc});
                    }
                }
            }
            return area;
        }

        private void fillLake(int startR, int startC) {
            Deque<int[]> queue = new ArrayDeque<>();
            queue.add(new int[]{startR, startC});
            grid[startR][startC] = '*';

            while (!queue.isEmpty()) {
                int[] curr = queue.poll();
                for (int i = 0; i < 4; i++) {
                    int nr = curr[0] + DR[i];
                    int nc = curr[1] + DC[i];
                    if (isValid(nr, nc) && grid[nr][nc] == '.') {
                        grid[nr][nc] = '*';
                        queue.add(new int[]{nr, nc});
                    }
                }
            }
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        public int getTotalFilledArea() {
            return totalFilledArea;
        }

        public void printGrid(PrintWriter writer) {
            for (int i = 0; i < rows; i++) {
                writer.println(new String(grid[i]));
            }
        }
    }

    /**
     * Utility class for fast I/O.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String readLine() throws IOException {
            return reader.readLine();
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to identify enclosed "lakes" in a grid and fill the smallest ones
 * with land ('*') until only K enclosed lakes remain.
 */
public class D375 {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            int k = reader.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            LakeSolver solver = new LakeSolver(grid, rows, cols);
            solver.solve(k, out);
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.close();
        }
    }

    /**
     * Represents a single connected component of water ('.') in the grid.
     */
    static class Lake {
        private final List<Point> cells = new ArrayList<>();
        private boolean isEnclosed = true;

        void addCell(int r, int c) {
            cells.add(new Point(r, c));
        }

        void setEnclosed(boolean enclosed) {
            isEnclosed = enclosed;
        }

        boolean isEnclosed() {
            return isEnclosed;
        }

        int size() {
            return cells.size();
        }

        List<Point> getCells() {
            return cells;
        }
    }

    /**
     * Simple data structure to represent a 2D coordinate.
     */
    static class Point {
        final int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Orchestrates the logic of finding, sorting, and filling lakes.
     */
    static class LakeSolver {
        private final char[][] grid;
        private final int rows;
        private final int cols;

        private static final int[] ROW_OFFSETS = {-1, 1, 0, 0};
        private static final int[] COL_OFFSETS = {0, 0, -1, 1};

        public LakeSolver(char[][] grid, int rows, int cols) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
        }

        public void solve(int k, PrintWriter out) {
            List<Lake> allLakes = findLakes();

            // Filter only those lakes that do not touch the boundary
            List<Lake> enclosedLakes = new ArrayList<>();
            for (Lake lake : allLakes) {
                if (lake.isEnclosed()) {
                    enclosedLakes.add(lake);
                }
            }

            int filledCount = 0;
            if (enclosedLakes.size() > k) {
                // Sort enclosed lakes by size ascending to fill the smallest ones first
                enclosedLakes.sort(Comparator.comparingInt(Lake::size));

                int lakesToFill = enclosedLakes.size() - k;
                for (int i = 0; i < lakesToFill; i++) {
                    for (Point p : enclosedLakes.get(i).getCells()) {
                        grid[p.r][p.c] = '*';
                        filledCount++;
                    }
                }
            }

            // Output result
            out.println(filledCount);
            printGrid(out);
        }

        private List<Lake> findLakes() {
            List<Lake> lakes = new ArrayList<>();
            boolean[][] visited = new boolean[rows][cols];

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.' && !visited[i][j]) {
                        lakes.add(bfs(i, j, visited));
                    }
                }
            }
            return lakes;
        }

        private Lake bfs(int startR, int startC, boolean[][] visited) {
            Lake lake = new Lake();
            Deque<Point> queue = new ArrayDeque<>();

            visited[startR][startC] = true;
            queue.add(new Point(startR, startC));

            while (!queue.isEmpty()) {
                Point curr = queue.poll();
                lake.addCell(curr.r, curr.c);

                // If the cell is on the boundary, the lake is not enclosed
                if (curr.r == 0 || curr.r == rows - 1 || curr.c == 0 || curr.c == cols - 1) {
                    lake.setEnclosed(false);
                }

                for (int i = 0; i < 4; i++) {
                    int nr = curr.r + ROW_OFFSETS[i];
                    int nc = curr.c + COL_OFFSETS[i];

                    if (isValidNeighbor(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        queue.add(new Point(nr, nc));
                    }
                }
            }
            return lake;
        }

        private boolean isValidNeighbor(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        private void printGrid(PrintWriter out) {
            for (int i = 0; i < rows; i++) {
                out.println(new String(grid[i]));
            }
        }
    }

    /**
     * Fast I/O utility for reading input.
