/**
 * A refactored solution to identify and manage "lakes" within a grid.
 * A lake is defined as a connected component of water ('.') that does not touch the grid boundary.
 */
public class Main {
    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        LakeSolver solver = new LakeSolver(reader);
        solver.solve(writer);

        writer.close();
    }

    static class LakeSolver {
        private final FastReader reader;

        public LakeSolver(FastReader reader) {
            this.reader = reader;
        }

        public void solve(PrintWriter out) {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            int targetLakeCount = reader.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            List<Lake> lakes = findLakes(rows, cols, grid);

            // Sort lakes by size in ascending order
            Collections.sort(lakes, Comparator.comparingInt(l -> l.size));

            int removedCellsCount = 0;
            // We need to remove lakes until we are left with 'targetLakeCount' lakes
            int lakesToRemove = lakes.size() - targetLakeCount;

            for (int i = 0; i < lakesToRemove; i++) {
                Lake lake = lakes.get(i);
                removedCellsCount += lake.size;
                for (int[] cell : lake.cells) {
                    grid[cell[0]][cell[1]] = '*';
                }
            }

            // Output the total number of cells converted to '*'
            out.println(removedCellsCount);

            // Output the modified grid
            for (int i = 0; i < rows; i++) {
                out.println(new String(grid[i]));
            }
        }

        /**
         * Uses BFS to find all connected components of '.' that do not touch the grid boundaries.
         */
        private List<Lake> findLakes(int rows, int cols, char[][] grid) {
            boolean[][] visited = new boolean[rows][cols];
            List<Lake> lakes = new ArrayList<>();

            int[] dr = {-1, 1, 0, 0};
            int[] dc = {0, 0, -1, 1};

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.' && !visited[r][c]) {
                        List<int[]> componentCells = new ArrayList<>();
                        boolean touchesBoundary = false;

                        // BFS initialization
                        Queue<int[]> queue = new ArrayDeque<>();
                        queue.add(new int[]{r, c});
                        visited[r][c] = true;

                        while (!queue.isEmpty()) {
                            int[] curr = queue.poll();
                            int currR = curr[0];
                            int currC = curr[1];
                            componentCells.add(curr);

                            // Check if this cell is on the boundary
                            if (currR == 0 || currR == rows - 1 || currC == 0 || currC == cols - 1) {
                                touchesBoundary = true;
                            }

                            // Explore 4-directional neighbors
                            for (int i = 0; i < 4; i++) {
                                int nr = currR + dr[i];
                                int nc = currC + dc[i];

                                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols 
                                    && grid[nr][nc] == '.' && !visited[nr][nc]) {
                                    visited[nr][nc] = true;
                                    queue.add(new int[]{nr, nc});
                                }
                            }
                        }

                        // If the component doesn't touch the boundary, it is a valid lake
                        if (!touchesBoundary) {
                            lakes.add(new Lake(componentCells.size(), componentCells));
                        }
                    }
                }
            }
            return lakes;
        }
    }

    /**
     * Represents a valid lake found in the grid.
     */
    static class Lake {
        final int size;
        final List<int[]> cells;

        Lake(int size, List<int[]> cells) {
            this.size = size;
            this.cells = cells;
        }
    }

    /**
     * Efficient utility class for fast input reading.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
