/**
 * Logic for finding and managing lakes in the Berland grid.
 */
class LakeSolver {
    private final int rows;
    private final int cols;
    private final int targetLakeCount;
    private final char[][] grid;

    private static final int[] ROW_DIRECTIONS = {-1, 1, 0, 0};
    private static final int[] COL_DIRECTIONS = {0, 0, -1, 1};

    public LakeSolver(int rows, int cols, int targetLakeCount, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.targetLakeCount = targetLakeCount;
        this.grid = grid;
    }

    public void solve() {
        List<Lake> lakes = findLakes();

        // Sort lakes by size ascending so we fill the smallest ones first
        lakes.sort(Comparator.comparingInt(Lake::getSize));

        int lakesToRemove = lakes.size() - targetLakeCount;
        int cellsFilled = 0;

        for (int i = 0; i < lakesToRemove; i++) {
            Lake lakeToFill = lakes.get(i);
            cellsFilled += lakeToFill.getSize();
            for (Point p : lakeToFill.getCells()) {
                grid[p.row][p.col] = '*';
            }
        }

        printResults(cellsFilled);
    }

    private List<Lake> findLakes() {
        List<Lake> lakes = new ArrayList<>();
        boolean[][] visited = new boolean[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && !visited[r][c]) {
                    Lake lake = bfs(r, c, visited);
                    if (lake != null) {
                        lakes.add(lake);
                    }
                }
            }
        }
        return lakes;
    }

    private Lake bfs(int startRow, int startCol, boolean[][] visited) {
        Deque<Point> queue = new ArrayDeque<>();
        List<Point> componentCells = new ArrayList<>();
        boolean touchesBoundary = false;

        queue.add(new Point(startRow, startCol));
        visited[startRow][startCol] = true;

        while (!queue.isEmpty()) {
            Point current = queue.poll();
            componentCells.add(current);

            if (isBoundary(current.row, current.col)) {
                touchesBoundary = true;
            }

            for (int i = 0; i < 4; i++) {
                int nextRow = current.row + ROW_DIRECTIONS[i];
                int nextCol = current.col + COL_DIRECTIONS[i];

                if (isValid(nextRow, nextCol) && grid[nextRow][nextCol] == '.' && !visited[nextRow][nextCol]) {
                    visited[nextRow][nextCol] = true;
                    queue.add(new Point(nextRow, nextCol));
                }
            }
        }

        // If the component touches the boundary, it's part of the ocean, not a lake
        return touchesBoundary ? null : new Lake(componentCells);
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private boolean isBoundary(int r, int c) {
        return r == 0 || r == rows - 1 || c == 0 || c == cols - 1;
    }

    private void printResults(int cellsFilled) {
        System.out.println(cellsFilled);
        for (int r = 0; r < rows; r++) {
            System.out.println(new String(grid[r]));
        }
    }
}

