/**
 * A program that identifies enclosed "islands" of '.' characters in a grid.
 * It removes the smallest enclosed islands (replacing them with '*') 
 * until only a specified number of enclosed islands remain.
 */
public class Task2 {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

