        for (int i = 0; i < rows; i++) {
            grid[i] = sc.next().toCharArray();
        }

        GridProcessor processor = new GridProcessor(grid, rows, cols, maxAllowedIslands);
        processor.process();
    }
}

class GridProcessor {
    private final char[][] grid;
    private final int rows;
    private final int cols;
    private final int maxAllowedIslands;

    private static final int[] DR = {0, 0, -1, 1};
    private static final int[] DC = {1, -1, 0, 0};

    /**
     * Represents an island of connected '.' characters.
     */
    private static class Island {
        final int size;
        final List<int[]> cells;
        final boolean isBoundary;

        Island(int size, List<int[]> cells, boolean isBoundary) {
            this.size = size;
            this.cells = cells;
            this.isBoundary = isBoundary;
        }
    }

    public GridProcessor(char[][] grid, int rows, int cols, int maxAllowedIslands) {
        this.grid = grid;
        this.rows = rows;
        this.cols = cols;
        this.maxAllowedIslands = maxAllowedIslands;
    }

    public void process() {
        boolean[][] visited = new boolean[rows][cols];
        List<Island> enclosedIslands = new ArrayList<>();

        // 1. Identify all islands using BFS
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && !visited[r][c]) {
                    Island island = findIsland(r, c, visited);
                    if (!island.isBoundary) {
                        enclosedIslands.add(island);
                    }
                }
            }
        }

        // 2. Sort enclosed islands by size (ascending)
        enclosedIslands.sort(Comparator.comparingInt(island -> island.size));

        // 3. Determine how many islands to "fill" with '*'
        // We want to keep the largest islands, so we remove the smallest ones 
        // until the count of enclosed islands is <= maxAllowedIslands.
        int numToRemove = Math.max(0, enclosedIslands.size() - maxAllowedIslands);
        int totalAreaRemoved = 0;

        for (int i = 0; i < numToRemove; i++) {
            Island islandToFill = enclosedIslands.get(i);
            totalAreaRemoved += islandToFill.size;
            for (int[] cell : islandToFill.cells) {
                grid[cell[0]][cell[1]] = '*';
            }
        }

        // 4. Output results
        printResults(totalAreaRemoved);
    }

    private Island findIsland(int startR, int startC, boolean[][] visited) {
        List<int[]> cells = new ArrayList<>();
        boolean isBoundary = false;
        Queue<int[]> queue = new LinkedList<>();

        queue.add(new int[]{startR, startC});
        visited[startR][startC] = true;

        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            int r = curr[0];
            int c = curr[1];
            cells.add(curr);

            // Check if this cell is on the boundary of the grid
            if (r == 0 || r == rows - 1 || c == 0 || c == cols - 1) {
                isBoundary = true;
            }

            // Explore neighbors
            for (int i = 0; i < 4; i++) {
                int nr = r + DR[i];
                int nc = c + DC[i];

                if (isValid(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    queue.add(new int[]{nr, nc});
                }
            }
        }

        return new Island(cells.size(), cells, isBoundary);
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private void printResults(int areaRemoved) {
        StringBuilder output = new StringBuilder();
        output.append(areaRemoved).append("\n");
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                output.append(grid[r][c]);
            }
            output.append("\n");
        }
        System.out.print(output.toString());
    }
}

