/**
 * Represents the possible states of a cell in the grid.
 */
enum CellType {
    LAND,       // Solid ground ('*')
    WATER,      // Potential lake water ('.')
    OCEAN,      // Water connected to the boundary ('.')
    PROCESSED   // Temporary state used during traversal
}

/**
 * Represents a single point in the 2D grid.
 */
class Point {
    final int r, c;

    Point(int r, int c) {
        this.r = r;
        this.c = c;
    }
}

/**
 * Represents a cluster of water cells.
 */
class Lake implements Comparable<Lake> {
    private final List<Point> cells;

    public Lake(List<Point> cells) {
        this.cells = cells;
    }

    public int getSize() {
        return cells.size();
    }

    public void fillWithLand(Grid grid) {
        for (Point p : cells) {
            grid.setCell(p.r, p.c, CellType.LAND);
        }
    }

    @Override
    public int compareTo(Lake other) {
        return Integer.compare(this.getSize(), other.getSize());
    }
}

/**
 * Manages the grid data structure and bounds checking.
 */
class Grid {
    private final int rows;
    private final int cols;
    private final CellType[][] matrix;

    public Grid(int rows, int cols) {
        this.rows = rows;
        this.cols = cols;
        this.matrix = new CellType[rows][cols];
    }

    public void setCell(int r, int c, CellType type) {
        matrix[r][c] = type;
    }

    public CellType getCell(int r, int c) {
        return matrix[r][c];
    }

    public int getRows() { return rows; }
    public int getCols() { return cols; }

    public boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    public boolean isBoundary(int r, int c) {
        return r == 0 || r == rows - 1 || c == 0 || c == cols - 1;
    }

    public void print(PrintWriter out) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                out.print(matrix[r][c] == CellType.LAND ? '*' : '.');
            }
            out.println();
        }
    }
}

/**
 * Contains the logic for solving the lake problem.
 */
class LakeSolver {
    private final Grid grid;
    private static final int[][] DIRECTIONS = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

    public LakeSolver(Grid grid) {
        this.grid = grid;
    }

    public void solve(int k, PrintWriter out) {
        markOcean();
        List<Lake> lakes = findLakes();

        int cellsFilled = 0;
        int lakesToRemove = Math.max(0, lakes.size() - k);

        // Sort lakes by size (ascending) to fill the smallest ones first
        Collections.sort(lakes);

        for (int i = 0; i < lakesToRemove; i++) {
            Lake lake = lakes.get(i);
            cellsFilled += lake.getSize();
            lake.fillWithLand(grid);
        }

        out.println(cellsFilled);
        grid.print(out);
    }

    /**
     * Identifies all water connected to the edges and marks them as OCEAN.
     */
    private void markOcean() {
        Queue<Point> queue = new ArrayDeque<>();

        for (int r = 0; r < grid.getRows(); r++) {
            for (int c = 0; c < grid.getCols(); c++) {
                if (grid.isBoundary(r, c) && grid.getCell(r, c) == CellType.WATER) {
                    queue.add(new Point(r, c));
                    grid.setCell(r, c, CellType.OCEAN);
                }
            }
        }

        bfs(queue, CellType.WATER, CellType.OCEAN);
    }

    /**
     * Identifies all isolated water clusters (lakes).
     */
    private List<Lake> findLakes() {
        List<Lake> lakes = new ArrayList<>();

        for (int r = 0; r < grid.getRows(); r++) {
            for (int c = 0; c < grid.getCols(); c++) {
                if (grid.getCell(r, c) == CellType.WATER) {
                    lakes.add(bfsFindLake(r, c));
                }
            }
        }
        return lakes;
    }

    private Lake bfsFindLake(int startR, int startC) {
        List<Point> cluster = new ArrayList<>();
        Queue<Point> queue = new ArrayDeque<>();

        Point start = new Point(startR, startC);
        queue.add(start);
        grid.setCell(startR, startC, CellType.PROCESSED);
        cluster.add(start);

        while (!queue.isEmpty()) {
            Point curr = queue.poll();
            for (int[] dir : DIRECTIONS) {
                int nr = curr.r + dir[0];
                int nc = curr.c + dir[1];

                if (grid.isValid(nr, nc) && grid.getCell(nr, nc) == CellType.WATER) {
                    grid.setCell(nr, nc, CellType.PROCESSED);
                    Point next = new Point(nr, nc);
                    queue.add(next);
                    cluster.add(next);
                }
            }
        }
        // After finding the lake, the cells are marked PROCESSED. 
        // We convert them back to WATER so they aren't lost if not filled.
        for (Point p : cluster) {
            grid.setCell(p.r, p.c, CellType.WATER);
        }
        return new Lake(cluster);
    }

    private void bfs(Queue<Point> queue, CellType target, CellType replacement) {
        while (!queue.isEmpty()) {
            Point curr = queue.poll();
            for (int[] dir : DIRECTIONS) {
                int nr = curr.r + dir[0];
                int nc = curr.c + dir[1];

                if (grid.isValid(nr, nc) && grid.getCell(nr, nc) == target) {
                    grid.setCell(nr, nc, replacement);
                    queue.add(new Point(nr, nc));
                }
            }
        }
    }
}

