            processor.process(k);
            processor.printOutput(out);

        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.close();
        }
    }

    /**
     * Represents a discovered island in the grid.
     */
    private record Island(int size, int startRow, int startCol) {}

    /**
     * Handles the logic of finding, sorting, and modifying grid islands.
     */
    private static class GridProcessor {
        private final char[][] grid;
        private final int rows;
        private final int cols;
        private final boolean[][] visited;
        private final List<Island> islands = new ArrayList<>();
        private int totalCellsConverted = 0;

        private static final int[][] DIRECTIONS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

        public GridProcessor(char[][] grid, int rows, int cols) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
            this.visited = new boolean[rows][cols];
        }

        public void process(int k) {
            markBorderConnectedCells();
            findEnclosedIslands();

            // Sort islands by size in descending order
            islands.sort((a, b) -> Integer.compare(b.size(), a.size()));

            // Keep the 'k' largest islands, convert the rest to '*'
            for (int i = k; i < islands.size(); i++) {
                Island island = islands.get(i);
                totalCellsConverted += island.size();
                fillIslandWithAsterisks(island.startRow, island.startCol);
            }
        }

        /**
         * Marks all '.' cells connected to the grid boundaries as visited.
         */
        private void markBorderConnectedCells() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    boolean isBorder = (r == 0 || r == rows - 1 || c == 0 || c == cols - 1);
                    if (isBorder && grid[r][c] == '.' && !visited[r][c]) {
                        dfsMark(r, c);
                    }
                }
            }
        }

        /**
         * Finds all islands of '.' that are not connected to the border.
         */
        private void findEnclosedIslands() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.' && !visited[r][c]) {
                        int size = countIslandSize(r, c);
                        islands.add(new Island(size, r, c));
                    }
                }
            }
        }

        private void dfsMark(int r, int c) {
            visited[r][c] = true;
            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (isValid(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                    dfsMark(nr, nc);
                }
            }
        }

        private int countIslandSize(int r, int c) {
            visited[r][c] = true;
            int count = 1;
            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (isValid(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                    count += countIslandSize(nr, nc);
                }
            }
            return count;
        }

        private void fillIslandWithAsterisks(int r, int c) {
            grid[r][c] = '*';
            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (isValid(nr, nc) && grid[nr][nc] == '.') {
                    fillIslandWithAsterisks(nr, nc);
                }
            }
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        public void printOutput(PrintWriter out) {
            out.println(totalCellsConverted);
            for (int i = 0; i < rows; i++) {
                out.println(new String(grid[i]));
            }
        }
    }

    /**
     * Utility class for fast input reading.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.*;

/**
 * A program to identify enclosed lakes in a grid and fill the smallest ones
 * until only a specified number of lakes remain.
 */
public class LakeManager {

    /**
     * Represents a single coordinate point in the grid.
     */
    private record Coordinate(int row, int col) {}

    /**
     * Represents a collection of coordinates forming a lake.
     */
    private record Lake(List<Coordinate> coordinates) {
        int size() {
            return coordinates.size();
        }
    }

    public static void main(String[] args) {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String firstLine = br.readLine();
            if (firstLine == null) return;

            StringTokenizer st = new StringTokenizer(firstLine);
            int rowCount = Integer.parseInt(st.nextToken());
            int colCount = Integer.parseInt(st.nextToken());
            int lakesToKeep = Integer.parseInt(st.nextToken());

            char[][] grid = new char[rowCount][colCount];
            for (int i = 0; i < rowCount; i++) {
                grid[i] = br.readLine().toCharArray();
            }

            LakeSolver solver = new LakeSolver(grid, rowCount, colCount);
            solver.process(lakesToKeep);
            solver.printGrid();

        } catch (IOException | NumberFormatException e) {
            System.err.println("Error processing input: " + e.getMessage());
        }
    }

    /**
     * Logic engine for solving the lake problem.
     */
    private static class LakeSolver {
        private final char[][] grid;
        private final int rowCount;
        private final int colCount;
        private final boolean[][] visited;
        private final List<Lake> enclosedLakes;

        private static final int[] ROW_OFFSETS = {-1, 1, 0, 0};
        private static final int[] COL_OFFSETS = {0, 0, -1, 1};

        public LakeSolver(char[][] grid, int rowCount, int colCount) {
            this.grid = grid;
            this.rowCount = rowCount;
            this.colCount = colCount;
            this.visited = new boolean[rowCount][colCount];
            this.enclosedLakes = new ArrayList<>();
        }

        /**
         * Executes the core algorithm: find lakes, sort them, and fill the smallest.
         */
        public void process(int lakesToKeep) {
            findEnclosedLakes();

            // Sort lakes by size (ascending)
            enclosedLakes.sort(Comparator.comparingInt(Lake::size));

            int lakesToFill = enclosedLakes.size() - lakesToKeep;
            int totalFilledCells = 0;

            // Fill the smallest lakes
            for (int i = 0; i < lakesToFill; i++) {
                for (Coordinate coord : enclosedLakes.get(i).coordinates()) {
                    grid[coord.row()][coord.col()] = '*';
                    totalFilledCells++;
                }
            }

            System.out.println(totalFilledCells);
        }

        private void findEnclosedLakes() {
            for (int r = 0; r < rowCount; r++) {
                for (int c = 0; c < colCount; c++) {
                    if (grid[r][c] == '.' && !visited[r][c]) {
                        exploreComponent(r, c);
                    }
                }
            }
        }

        /**
         * Uses iterative DFS to find all connected '.' cells and determines
         * if the component is an "enclosed" lake.
         */
        private void exploreComponent(int startRow, int startCol) {
            List<Coordinate> component = new ArrayList<>();
            Deque<Coordinate> stack = new ArrayDeque<>();
            boolean touchesBoundary = false;

            stack.push(new Coordinate(startRow, startCol));
            visited[startRow][startCol] = true;

            while (!stack.isEmpty()) {
                Coordinate current = stack.pop();
                component.add(current);

                // If the component touches the boundary, it is not an enclosed lake
                if (current.row() == 0 || current.row() == rowCount - 1 ||
                    current.col() == 0 || current.col() == colCount - 1) {
                    touchesBoundary = true;
                }

                for (int i = 0; i < 4; i++) {
                    int nextRow = current.row() + ROW_OFFSETS[i];
                    int nextCol = current.col() + COL_OFFSETS[i];

                    if (isValidMove(nextRow, nextCol)) {
                        visited[nextRow][nextCol] = true;
                        stack.push(new Coordinate(nextRow, nextCol));
                    }
                }
            }

            if (!touchesBoundary) {
                enclosedLakes.add(new Lake(component));
            }
        }

        private boolean isValidMove(int r, int c) {
            return r >= 0 && r < rowCount && c >= 0 && c < colCount 
                   && grid[r][c] == '.' && !visited[r][c];
        }

        public void printGrid() {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < rowCount; i++) {
                sb.append(new String(grid[i])).append("\n");
            }
            System.out.print(sb.toString());
        }
    }
}

import java.util.*;

/**
 * A solution for the "Lakes in Berland" problem.
 * The goal is to maximize the amount of land ('*') by converting up to k lakes ('.') into land.
 */
public class BerlandLakesSolver {

    private final int rows;
    private final int cols;
    private final int maxLakesToFill;
    private final char[][] grid;

    public BerlandLakesSolver(int rows, int cols, int maxLakesToFill, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.maxLakesToFill = maxLakesToFill;
        this.grid = grid;
    }

    /**
     * Represents a connected component of water cells.
     */
    private static class Lake {
        final int size;
        final List<Point> coordinates;

        Lake(int size, List<Point> coordinates) {
            this.size = size;
            this.coordinates = coordinates;
        }
    }

    /**
     * Simple coordinate wrapper.
     */
    private static class Point {
        final int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    public void solve() {
        List<Lake> lakes = findAllLakes();

        // Sort lakes by size in descending order to pick the largest ones first
        lakes.sort((a, b) -> Integer.compare(b.size, a.size));

        // Convert the largest k lakes into land
        int lakesFilled = 0;
        for (Lake lake : lakes) {
            if (lakesFilled >= maxLakesToFill) {
                break;
            }
            fillLake(lake);
            lakesFilled++;
        }

        printResult();
    }

    /**
     * Iterates through the grid to find all distinct lakes using BFS.
     */
    private List<Lake> findAllLakes() {
        List<Lake> lakes = new ArrayList<>();
        boolean[][] visited = new boolean[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.' && !visited[i][j]) {
                    lakes.add(bfs(i, j, visited));
                }
            }
        }
        return lakes;
    }

    /**
     * Uses BFS to find all connected '.' cells starting from (startR, startC).
     */
    private Lake bfs(int startR, int startC, boolean[][] visited) {
        List<Point> coords = new ArrayList<>();
        Queue<Point> queue = new LinkedList<>();

        Point start = new Point(startR, startC);
        queue.add(start);
        visited[startR][startC] = true;

        int[][] directions = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

        while (!queue.isEmpty()) {
            Point curr = queue.poll();
            coords.add(curr);

            for (int[] dir : directions) {
                int nextR = curr.r + dir[0];
                int nextC = curr.c + dir[1];

                if (isValid(nextR, nextC) && grid[nextR][nextC] == '.' && !visited[nextR][nextC]) {
                    visited[nextR][nextC] = true;
                    queue.add(new Point(nextR, nextC));
                }
            }
        }

        return new Lake(coords.size(), coords);
    }

    private void fillLake(Lake lake) {
        for (Point p : lake.coordinates) {
            grid[p.r][p.c] = '*';
        }
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private void printResult() {
        int landCount = 0;
        StringBuilder gridOutput = new StringBuilder();

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*') {
                    landCount++;
                }
                gridOutput.append(grid[i][j]);
            }
            gridOutput.append("\n");
        }

        System.out.println(landCount);
        System.out.print(gridOutput.toString());
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        int k = scanner.nextInt();
        scanner.nextLine(); // Consume newline

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String line = scanner.nextLine();
            grid[i] = line.toCharArray();
        }

        BerlandLakesSolver solver = new BerlandLakesSolver(n, m, k, grid);
        solver.solve();

        scanner.close();
    }
}

