/**
 * A program to identify "lakes" (connected components of '.' not touching the boundary)
 * and fill the smallest lakes with '*' until a target number of lakes remains.
 */
public class Main {
    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            int targetLakeCount = reader.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.readLine().toCharArray();
            }

            LakeSolver solver = new LakeSolver(rows, cols, grid);
            solver.solve(targetLakeCount);

            // Output the resulting grid
            for (int i = 0; i < rows; i++) {
                out.println(new String(grid[i]));
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.close();
        }
    }

    /**
     * Handles the core logic of finding and filling lakes.
     */
    static class LakeSolver {
        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final boolean[][] visited;

        private static final int[] ROW_DIRECTIONS = {-1, 1, 0, 0};
        private static final int[] COL_DIRECTIONS = {0, 0, -1, 1};

        public LakeSolver(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            this.visited = new boolean[rows][cols];
        }

        public void solve(int targetLakeCount) {
            PriorityQueue<Lake> lakeQueue = new PriorityQueue<>();

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.' && !visited[i][j]) {
                        Lake lake = findComponent(i, j);
                        if (lake.isLake()) {
                            lakeQueue.add(lake);
                        }
                    }
                }
            }

            // Fill the smallest lakes until we hit the target count
            while (lakeQueue.size() > targetLakeCount) {
                Lake smallestLake = lakeQueue.poll();
                fillLake(smallestLake);
            }
        }

        /**
         * Uses BFS to find all connected '.' cells and determines if the component is a lake.
         */
        private Lake findComponent(int startR, int startC) {
            List<Cell> componentCells = new ArrayList<>();
            Queue<Cell> queue = new ArrayDeque<>();
            boolean touchesBoundary = false;

            Cell start = new Cell(startR, startC);
            queue.add(start);
            visited[startR][startC] = true;

            while (!queue.isEmpty()) {
                Cell current = queue.poll();
                componentCells.add(current);

                // Check if this cell is on the boundary
                if (current.r == 0 || current.r == rows - 1 || current.c == 0 || current.c == cols - 1) {
                    touchesBoundary = true;
                }

                for (int i = 0; i < 4; i++) {
                    int nr = current.r + ROW_DIRECTIONS[i];
                    int nc = current.c + COL_DIRECTIONS[i];

                    if (isValid(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        queue.add(new Cell(nr, nc));
                    }
                }
            }

            return new Lake(componentCells, !touchesBoundary);
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        private void fillLake(Lake lake) {
            for (Cell cell : lake.getCells()) {
                grid[cell.r][cell.c] = '*';
            }
        }
    }

    /**
     * Represents a single coordinate in the grid.
     */
    static class Cell {
        final int r, c;

        Cell(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Represents a collection of connected cells forming a lake.
     */
    static class Lake implements Comparable<Lake> {
        private final List<Cell> cells;
        private final boolean isLake;

        Lake(List<Cell> cells, boolean isLake) {
            this.cells = cells;
            this.isLake = isLake;
        }

        public boolean isLake() {
            return isLake;
        }

        public List<Cell> getCells() {
            return cells;
        }

        public int getSize() {
            return cells.size();
        }

        @Override
        public int compareTo(Lake other) {
            // Sort by size ascending
            return Integer.compare(this.getSize(), other.getSize());
        }
    }

    /**
     * Efficient input reader.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String readLine() throws IOException {
            return reader.readLine();
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A solution to identify connected components in a grid and remove the smallest
 * non-border components until a target number of components remains.
 */
public class GridComponentManager {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            int k = reader.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            GridSolver solver = new GridSolver(rows, cols, grid);
            solver.solve(k, out);

        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.close();
        }
    }

    /**
     * Represents a connected component of '.' cells.
     */
    static class Component implements Comparable<Component> {
        final int id;
        final int size;
        final boolean isBorder;
        final List<Integer> cellIndices;

        Component(int id, int size, boolean isBorder, List<Integer> cellIndices) {
            this.id = id;
            this.size = size;
            this.isBorder = isBorder;
            this.cellIndices = cellIndices;
        }

        @Override
        public int compareTo(Component other) {
            return Integer.compare(this.size, other.size);
        }
    }

    static class GridSolver {
        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final boolean[][] visited;

        private static final int[] DX = {-1, 0, 1, 0};
        private static final int[] DY = {0, 1, 0, -1};

        public GridSolver(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            this.visited = new boolean[rows][cols];
        }

        public void solve(int k, PrintWriter out) {
            List<Component> allComponents = findComponents();

            // Separate internal components (those not touching the border)
            List<Component> internalComponents = new ArrayList<>();
            for (Component comp : allComponents) {
                if (!comp.isBorder) {
                    internalComponents.add(comp);
                }
            }

            // Sort internal components by size to remove the smallest ones first
            Collections.sort(internalComponents);

            // Logic: We want to leave 'k' internal components untouched.
            // Number of components to remove = (total internal) - k.
            int numToRemove = internalComponents.size() - k;

            for (int i = 0; i < numToRemove; i++) {
                Component toRemove = internalComponents.get(i);
                for (int cellIdx : toRemove.cellIndices) {
                    int r = cellIdx / cols;
                    int c = cellIdx % cols;
                    grid[r][c] = '*';
                }
            }

            printGrid(out);
        }

        private List<Component> findComponents() {
            List<Component> components = new ArrayList<>();
            int componentIdCounter = 0;

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.' && !visited[i][j]) {
                        components.add(bfs(i, j, componentIdCounter++));
                    }
                }
            }
            return components;
        }

        /**
         * Uses BFS to find all connected '.' cells. 
         * BFS is used instead of DFS to avoid StackOverflowError on large grids.
         */
        private Component bfs(int startR, int startC, int id) {
            List<Integer> cellIndices = new ArrayList<>();
            boolean isBorder = false;
            int size = 0;

            Queue<int[]> queue = new LinkedList<>();
            queue.offer(new int[]{startR, startC});
            visited[startR][startC] = true;

            while (!queue.isEmpty()) {
                int[] curr = queue.poll();
                int r = curr[0];
                int c = curr[1];

                size++;
                cellIndices.add(r * cols + c);

                // Check if this cell is on the boundary
                if (r == 0 || r == rows - 1 || c == 0 || c == cols - 1) {
                    isBorder = true;
                }

                for (int i = 0; i < 4; i++) {
                    int nr = r + DX[i];
                    int nc = c + DY[i];

                    if (isValid(nr, nc)) {
                        visited[nr][nc] = true;
                        queue.offer(new int[]{nr, nc});
                    }
                }
            }

            return new Component(id, size, isBorder, cellIndices);
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols 
                    && grid[r][c] == '.' && !visited[r][c];
        }

        private void printGrid(PrintWriter out) {
            for (int i = 0; i < rows; i++) {
                out.println(new String(grid[i]));
            }
        }
    }

    /**
     * Efficient input reader.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;

/**
 * Refactored Berland Map Problem Solver.
 * This program identifies enclosed water bodies (lakes) in a grid
 * and fills the k smallest lakes with land.
 */
public class BerlandMapSolver {

    private static final int[] DX = {0, 0, 1, -1};
    private static final int[] DY = {1, -1, 0, 0};

    /**
     * Represents a coordinate in the grid.
     */
    private record Point(int r, int c) {}

    /**
     * Represents an enclosed lake.
     */
    private record Lake(int size, List<Point> points) implements Comparable<Lake> {
        @Override
        public int compareTo(Lake other) {
            return Integer.compare(this.size, other.size);
        }
    }

    private final int rows;
    private final int cols;
    private final int kToFill;
    private final char[][] grid;

    public BerlandMapSolver(int rows, int cols, int kToFill, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.kToFill = kToFill;
        this.grid = grid;
    }

    /**
     * Main execution flow of the solver.
     */
    public void solve() {
        List<Lake> lakes = findLakes();
        Collections.sort(lakes);

        int totalFilledCells = fillLakes(lakes);
        printResult(totalFilledCells);
    }

    /**
     * Uses BFS to find all water components and identifies which are lakes.
     * A lake is defined as a water component that does not touch the grid boundary.
     */
    private List<Lake> findLakes() {
        List<Lake> lakes = new ArrayList<>();
        boolean[][] visited = new boolean[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && !visited[r][c]) {
                    Lake lake = bfsExploreComponent(r, c, visited);
                    if (lake != null) {
                        lakes.add(lake);
                    }
                }
            }
        }
        return lakes;
    }

    private Lake bfsExploreComponent(int startR, int startC, boolean[][] visited) {
        Queue<Point> queue = new LinkedList<>();
        List<Point> componentPoints = new ArrayList<>();
        boolean touchesOcean = false;

        Point start = new Point(startR, startC);
        queue.add(start);
        visited[startR][startC] = true;

        while (!queue.isEmpty()) {
            Point curr = queue.poll();
            componentPoints.add(curr);

            // Check if this point is on the boundary (ocean)
            if (curr.r == 0 || curr.r == rows - 1 || curr.c == 0 || curr.c == cols - 1) {
                touchesOcean = true;
            }

            for (int i = 0; i < 4; i++) {
                int nr = curr.r + DX[i];
                int nc = curr.c + DY[i];

                if (isValid(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    queue.add(new Point(nr, nc));
                }
            }
        }

        // If the component touches the boundary, it's ocean, not a lake
        return touchesOcean ? null : new Lake(componentPoints.size(), componentPoints);
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Fills the k smallest lakes with land ('*').
     * @return total number of cells converted from water to land.
     */
    private int fillLakes(List<Lake> lakes) {
        int cellsFilled = 0;
        int lakesToProcess = Math.min(kToFill, lakes.size());

        for (int i = 0; i < lakesToProcess; i++) {
            Lake lake = lakes.get(i);
            cellsFilled += lake.size();
            for (Point p : lake.points()) {
                grid[p.r][p.c] = '*';
            }
        }
        return cellsFilled;
    }

    private void printResult(int totalFilled) {
        System.out.println(totalFilled);
        StringBuilder sb = new StringBuilder();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                sb.append(grid[r][c]);
            }
            sb.append('\n');
        }
        System.out.print(sb.toString());
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        if (!sc.hasNextInt()) return;
        int n = sc.nextInt();
        int m = sc.nextInt();
        int k = sc.nextInt();

        char[][] inputGrid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String line = sc.next();
            inputGrid[i] = line.toCharArray();
        }

        BerlandMapSolver solver = new BerlandMapSolver(n, m, k, inputGrid);
        solver.solve();

        sc.close();
    }
}

