import java.io.*;

/**
 * Refactored solution for the Lake Filling problem.
 * The program identifies enclosed land components (lakes) and fills the smallest ones
 * until only K lakes remain.
 */
public class Main {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        LakeSolver solver = new LakeSolver();
        solver.solve(sc, out);

        out.flush();
        out.close();
        sc.close();
    }
}

class LakeSolver {

    /**
     * Represents a connected component of land (a lake).
     */
    private static class Lake implements Comparable<Lake> {
        final int rootId;
        final int size;

        Lake(int rootId, int size) {
            this.rootId = rootId;
            this.size = size;
        }

        @Override
        public int compareTo(Lake other) {
            // Sort by size ascending so we can easily pick the smallest lakes
            return Integer.compare(this.size, other.size);
        }
    }

    /**
     * Disjoint Set Union (DSU) implementation for efficient grouping.
     */
    private static class UnionFind {
        private final int[] parent;
        private final int[] rank;

        public UnionFind(int n) {
            parent = new int[n];
            rank = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
            }
        }

        /**
         * Iterative find with path compression to prevent StackOverflowError.
         */
        public int find(int i) {
            int root = i;
            while (parent[root] != root) {
                root = parent[root];
            }
            // Path compression
            while (parent[i] != root) {
                int next = parent[i];
                parent[i] = root;
                i = next;
            }
            return root;
        }

        public void union(int i, int j) {
            int root1 = find(i);
            int root2 = find(j);

            if (root1 != root2) {
                // Union by rank
                if (rank[root1] < rank[root2]) {
                    parent[root1] = root2;
                } else if (rank[root1] > rank[root2]) {
                    parent[root2] = root1;
                } else {
                    parent[root2] = root1;
                    rank[root1]++;
                }
            }
        }

        public boolean isRoot(int i) {
            return parent[i] == i;
        }
    }

    public void solve(Scanner in, PrintWriter out) {
        if (!in.hasNextInt()) return;

        int rows = in.nextInt();
        int cols = in.nextInt();
        int k = in.nextInt();
        in.nextLine(); // Consume leftover newline

        boolean[][] isLand = new boolean[rows][cols];
        for (int r = 0; r < rows; r++) {
            String line = in.nextLine();
            for (int c = 0; c < cols; c++) {
                isLand[r][c] = (line.charAt(c) == '.');
            }
        }

        // seaNode acts as a sentinel component representing everything connected to the boundary
        int seaNode = rows * cols;
        UnionFind uf = new UnionFind(rows * cols + 1);

        // 1. Build components using Union-Find
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int currentIndex = r * cols + c;

                if (isLand[r][c]) {
                    // Connect adjacent land cells
                    if (r + 1 < rows && isLand[r + 1][c]) {
                        uf.union(currentIndex, (r + 1) * cols + c);
                    }
                    if (c + 1 < cols && isLand[r][c + 1]) {
                        uf.union(currentIndex, r * cols + (c + 1));
                    }

                    // If cell is on the boundary, it's part of the "sea"
                    if (r == 0 || r == rows - 1 || c == 0 || c == cols - 1) {
                        uf.union(currentIndex, seaNode);
                    }
                } else {
                    // Water cells are part of the sea
                    uf.union(currentIndex, seaNode);
                }
            }
        }

        // 2. Calculate component sizes
        int[] componentSizes = new int[rows * cols + 1];
        for (int i = 0; i < rows * cols; i++) {
            componentSizes[uf.find(i)]++;
        }

        // 3. Identify all enclosed lakes (non-sea components containing land)
        List<Lake> lakes = new ArrayList<>();
        int seaRoot = uf.find(seaNode);

        for (int i = 0; i < rows * cols; i++) {
            if (uf.isRoot(i) && i != seaRoot && componentSizes[i] > 0) {
                lakes.add(new Lake(i, componentSizes[i]));
            }
        }

        // 4. Sort lakes by size (ascending) to prioritize filling the smallest ones
        Collections.sort(lakes);

        // 5. Determine which lakes must be filled to leave exactly K lakes remaining
        int numToFill = Math.max(0, lakes.size() - k);
        Set<Integer> rootsToFill = new HashSet<>();
        for (int i = 0; i < numToFill; i++) {
            rootsToFill.add(lakes.get(i).rootId);
        }

        // 6. Update the grid and count filled cells
        int totalFilledCells = 0;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (isLand[r][c] && rootsToFill.contains(uf.find(r * cols + c))) {
                    isLand[r][c] = false;
                    totalFilledCells++;
                }
            }
        }

        // 7. Final output
        out.println(totalFilledCells);
        StringBuilder sb = new StringBuilder();
        for (int r = 0; r < rows; r++) {
            sb.setLength(0);
            for (int c = 0; c < cols; c++) {
                sb.append(isLand[r][c] ? '.' : '*');
            }
            out.println(sb.toString());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * This program identifies "lakes" (enclosed components of '.') in a grid,
 * and fills the smallest lakes with '*' until only a target number of lakes remain.
 */
public class LakeManager {

    private static final int[] ROW_DIRECTION = {-1, 1, 0, 0};
    private static final int[] COL_DIRECTION = {0, 0, -1, 1};

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            int rowCount = reader.nextInt();
            int colCount = reader.nextInt();
            int targetLakeCount = reader.nextInt();

            char[][] grid = new char[rowCount][colCount];
            for (int i = 0; i < rowCount; i++) {
                grid[i] = reader.next().toCharArray();
            }

            LakeProcessor processor = new LakeProcessor(grid, rowCount, colCount, targetLakeCount);
            processor.process(writer);

        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Represents a single coordinate in the grid.
     */
    static class Point {
        final int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Represents an enclosed component of '.' cells.
     */
    static class Lake {
        final List<Point> cells;
        final int size;

        Lake(List<Point> cells) {
            this.cells = cells;
            this.size = cells.size();
        }
    }

    /**
     * Handles the logic of finding, sorting, and filling lakes.
     */
    static class LakeProcessor {
        private final char[][] grid;
        private final int rows;
        private final int cols;
        private final int targetLakeCount;

        LakeProcessor(char[][] grid, int rows, int cols, int targetLakeCount) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
            this.targetLakeCount = targetLakeCount;
        }

        public void process(PrintWriter writer) {
            List<Lake> lakes = findLakes();

            // Sort lakes by size in ascending order to fill the smallest ones first
            lakes.sort(Comparator.comparingInt(lake -> lake.size));

            int totalFilledCells = 0;
            int numToFill = Math.max(0, lakes.size() - targetLakeCount);

            for (int i = 0; i < numToFill; i++) {
                Lake lakeToFill = lakes.get(i);
                totalFilledCells += lakeToFill.size;
                for (Point p : lakeToFill.cells) {
                    grid[p.r][p.c] = '*';
                }
            }

            // Output results
            writer.println(totalFilledCells);
            for (int i = 0; i < rows; i++) {
                writer.println(new String(grid[i]));
            }
        }

        /**
         * Performs a BFS to find all components of '.' cells.
         * Components that touch the boundary are considered "ocean" and ignored.
         */
        private List<Lake> findLakes() {
            List<Lake> lakes = new ArrayList<>();
            boolean[][] visited = new boolean[rows][cols];

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.' && !visited[r][c]) {
                        Lake lake = bfs(r, c, visited);
                        if (lake != null) {
                            lakes.add(lake);
                        }
                    }
                }
            }
            return lakes;
        }

        private Lake bfs(int startR, int startC, boolean[][] visited) {
            List<Point> componentCells = new ArrayList<>();
            Deque<Point> queue = new ArrayDeque<>();
            boolean touchesBoundary = false;

            Point start = new Point(startR, startC);
            queue.add(start);
            visited[startR][startC] = true;

            while (!queue.isEmpty()) {
                Point curr = queue.poll();
                componentCells.add(curr);

                // Check if the component touches the edge of the grid
                if (curr.r == 0 || curr.r == rows - 1 || curr.c == 0 || curr.c == cols - 1) {
                    touchesBoundary = true;
                }

                for (int i = 0; i < 4; i++) {
                    int nr = curr.r + ROW_DIRECTION[i];
                    int nc = curr.c + COL_DIRECTION[i];

                    if (isValid(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        queue.add(new Point(nr, nc));
                    }
                }
            }

            // If it touches the boundary, it's part of the ocean, not a lake
            return touchesBoundary ? null : new Lake(componentCells);
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * Utility class for fast input reading.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.*;

/**
 * LakeSolver identifies enclosed "lakes" in a grid and allows for 
 * filling the smallest lakes with '*' until a target number of lakes remains.
 */
public class LakeSolver {

    private static final int[][] DIRECTIONS = {
            {0, 1}, {0, -1}, {1, 0}, {-1, 0}
    };

    /**
     * Represents a single coordinate in the grid.
     */
    private static class Cell {
        final int row;
        final int col;

        Cell(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Represents a collection of connected '.' cells that do not touch the boundary.
     */
    private static class Lake implements Comparable<Lake> {
        private final List<Cell> cells;
        private final int size;

        Lake(List<Cell> cells) {
            this.cells = cells;
            this.size = cells.size();
        }

        public List<Cell> getCells() {
            return cells;
        }

        public int getSize() {
            return size;
        }

        @Override
        public int compareTo(Lake other) {
            return Integer.compare(this.size, other.size);
        }
    }

    private final int rows;
    private final int cols;
    private final int minLakesToKeep;
    private final char[][] grid;
    private final boolean[][] visited;

    public LakeSolver(int rows, int cols, int minLakesToKeep, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.minLakesToKeep = minLakesToKeep;
        this.grid = grid;
        this.visited = new boolean[rows][cols];
    }

    /**
     * Executes the core logic: finding lakes, sorting them, and filling the smallest ones.
     */
    public void solve() {
        List<Lake> lakes = findLakes();
        Collections.sort(lakes);

        int totalCellsFilled = 0;

        // Remove the smallest lakes until we only have the requested amount left
        while (lakes.size() > minLakesToKeep) {
            Lake smallestLake = lakes.remove(0);
            totalCellsFilled += smallestLake.getSize();
            for (Cell cell : smallestLake.getCells()) {
                grid[cell.row][cell.col] = '*';
            }
        }

        printResult(totalCellsFilled);
    }

    /**
     * Scans the grid to find all connected components of '.' that are fully enclosed.
     */
    private List<Lake> findLakes() {
        List<Lake> lakes = new ArrayList<>();

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && !visited[r][c]) {
                    Lake foundLake = bfsExploreComponent(r, c);
                    if (foundLake != null) {
                        lakes.add(foundLake);
                    }
                }
            }
        }
        return lakes;
    }

    /**
     * Uses BFS to find all connected '.' cells. 
     * Returns a Lake object if the component is enclosed, or null if it touches the boundary.
     */
    private Lake bfsExploreComponent(int startRow, int startCol) {
        List<Cell> componentCells = new ArrayList<>();
        Queue<Cell> queue = new LinkedList<>();
        boolean isEnclosed = true;

        queue.add(new Cell(startRow, startCol));
        visited[startRow][startCol] = true;

        while (!queue.isEmpty()) {
            Cell current = queue.poll();
            componentCells.add(current);

            // If any cell in the component is on the boundary, the whole component is not a "lake"
            if (isBoundary(current.row, current.col)) {
                isEnclosed = false;
            }

            for (int[] dir : DIRECTIONS) {
                int nextRow = current.row + dir[0];
                int nextCol = current.col + dir[1];

                if (isInBounds(nextRow, nextCol) && 
                    !visited[nextRow][nextCol] && 
                    grid[nextRow][nextCol] == '.') {

                    visited[nextRow][nextCol] = true;
                    queue.add(new Cell(nextRow, nextCol));
                }
            }
        }

        return isEnclosed ? new Lake(componentCells) : null;
    }

    private boolean isBoundary(int r, int c) {
        return r == 0 || r == rows - 1 || c == 0 || c == cols - 1;
    }

    private boolean isInBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private void printResult(int filledCount) {
        StringBuilder sb = new StringBuilder();
        sb.append(filledCount).append("\n");
        for (int r = 0; r < rows; r++) {
            sb.append(new String(grid[r])).append("\n");
        }
        System.out.print(sb.toString());
    }

    public static void main(String[] args) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String line = reader.readLine();
            if (line == null) return;

            String[] dims = line.split("\\s+");
            int rows = Integer.parseInt(dims[0]);
            int cols = Integer.parseInt(dims[1]);
            int k = Integer.parseInt(dims[2]);

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.readLine().toCharArray();
            }

            LakeSolver solver = new LakeSolver(rows, cols, k, grid);
            solver.solve();

        } catch (IOException | NumberFormatException e) {
            System.err.println("Error processing input: " + e.getMessage());
        }
    }
}

