/**
 * Handles the logic for solving the grid problem.
 */
class GridProblemSolver {
    private final int rows;
    private final int cols;
    private final int k;
    private final char[][] displayGrid;
    private final int[][] componentIdGrid;

    private static final int[] DX = {-1, 1, 0, 0};
    private static final int[] DY = {0, 0, -1, 1};

    /**
     * Represents an enclosed component of empty cells.
     */
    private static class Component implements Comparable<Component> {
        final int id;
        final int size;

        Component(int id, int size) {
            this.id = id;
            this.size = size;
        }

        @Override
        public int compareTo(Component other) {
            // Sort by size ascending
            return Integer.compare(this.size, other.size);
        }
    }

    public GridProblemSolver(int rows, int cols, int k) {
        this.rows = rows;
        this.cols = cols;
        this.k = k;
        this.displayGrid = new char[rows][cols];
        this.componentIdGrid = new int[rows][cols];
    }

    public void solve(InputReader in) throws IOException {
        // 1. Initialize grids
        for (int i = 0; i < rows; i++) {
            String line = in.next();
            for (int j = 0; j < cols; j++) {
                displayGrid[i][j] = line.charAt(j);
                if (displayGrid[i][j] == '.') {
                    componentIdGrid[i][j] = 1; // 1 represents an unvisited potential component
                }
            }
        }

        // 2. Remove '.' cells connected to the boundary (not enclosed)
        for (int i = 0; i < rows; i++) {
            if (componentIdGrid[i][0] == 1) bfsMarkAsNonEnclosed(i, 0);
            if (componentIdGrid[i][cols - 1] == 1) bfsMarkAsNonEnclosed(i, cols - 1);
        }
        for (int j = 0; j < cols; j++) {
            if (componentIdGrid[0][j] == 1) bfsMarkAsNonEnclosed(0, j);
            if (componentIdGrid[rows - 1][j] == 1) bfsMarkAsNonEnclosed(rows - 1, j);
        }

        // 3. Find all remaining enclosed components using BFS
        List<Component> components = new ArrayList<>();
        int nextComponentId = 2; // Start IDs from 2 to distinguish from boundary/unvisited
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (componentIdGrid[i][j] == 1) {
                    int size = bfsLabelComponent(i, j, nextComponentId);
                    components.add(new Component(nextComponentId, size));
                    nextComponentId++;
                }
            }
        }

        // 4. Sort components by size and identify the smallest (ind - k) components to mark
        Collections.sort(components);
        int numToMark = Math.max(0, components.size() - k);
        Set<Integer> idsToMark = new HashSet<>();
        for (int i = 0; i < numToMark; i++) {
            idsToMark.add(components.get(i).id);
        }

        // 5. Mark selected components with '*' in the display grid
        int starsCount = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (idsToMark.contains(componentIdGrid[i][j])) {
                    displayGrid[i][j] = '*';
                    starsCount++;
                }
            }
        }

        // Store the count of stars in a temporary way for printing
        this.totalStarsPlaced = starsCount;
    }

    private int totalStarsPlaced = 0;

    public void printResult(PrintWriter out) {
        out.println(totalStarsPlaced);
        for (int i = 0; i < rows; i++) {
            out.println(new String(displayGrid[i]));
        }
    }

    /**
     * Iterative BFS to mark boundary-connected cells as 0 (non-enclosed).
     */
    private void bfsMarkAsNonEnclosed(int startI, int startJ) {
        Deque<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[]{startI, startJ});
        componentIdGrid[startI][startJ] = 0;

        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            for (int i = 0; i < 4; i++) {
                int ni = curr[0] + DX[i];
                int nj = curr[1] + DY[i];
                if (isValid(ni, nj) && componentIdGrid[ni][nj] == 1) {
                    componentIdGrid[ni][nj] = 0;
                    queue.offer(new int[]{ni, nj});
                }
            }
        }
    }

    /**
     * Iterative BFS to label an enclosed component with a unique ID and return its size.
     */
    private int bfsLabelComponent(int startI, int startJ, int newId) {
        Deque<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[]{startI, startJ});
        componentIdGrid[startI][startJ] = newId;
        int size = 0;

        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            size++;
            for (int i = 0; i < 4; i++) {
                int ni = curr[0] + DX[i];
                int nj = curr[1] + DY[i];
                if (isValid(ni, nj) && componentIdGrid[ni][nj] == 1) {
                    componentIdGrid[ni][nj] = newId;
                    queue.offer(new int[]{ni, nj});
                }
            }
        }
        return size;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

