/**
 * Problem: CF375D - Lakes
 * Refactored for maintainability, readability, and performance.
 */
public class CF375D {

    // Represents a single point in the grid
    static class Point {
        int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    // Represents a lake (a connected component of '.' cells)
    static class Lake implements Comparable<Lake> {
        int size;
        List<Point> cells;
        boolean touchesOcean;

        Lake() {
            this.size = 0;
            this.cells = new ArrayList<>();
            this.touchesOcean = false;
        }

        @Override
        public int compareTo(Lake other) {
            // Sort by size ascending to easily pick the smallest lakes to fill
            return Integer.compare(this.size, other.size);
        }
    }

    public static void main(String[] args) throws IOException {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        // Read dimensions
        int rows = reader.nextInt();
        int cols = reader.nextInt();
        int k = reader.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = reader.next().toCharArray();
        }

        List<Lake> lakes = findLakes(grid, rows, cols);
        Collections.sort(lakes);

        int totalCellsConverted = 0;
        // The problem asks to leave exactly k largest lakes. 
        // Therefore, we fill the (totalLakes - k) smallest lakes.
        int lakesToFillCount = Math.max(0, lakes.size() - k);

        for (int i = 0; i < lakesToFillCount; i++) {
            Lake lake = lakes.get(i);
            totalCellsConverted += lake.size;
            for (Point p : lake.cells) {
                grid[p.r][p.c] = '*';
            }
        }

        // Output result
        writer.println(totalCellsConverted);
        for (int i = 0; i < rows; i++) {
            writer.println(new String(grid[i]));
        }
        writer.flush();
        writer.close();
    }

    /**
     * Scans the grid to find all valid lakes (components of '.' not touching '~').
     */
    private static List<Lake> findLakes(char[][] grid, int rows, int cols) {
        List<Lake> lakes = new ArrayList<>();
        boolean[][] visited = new boolean[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.' && !visited[i][j]) {
                    Lake lake = new Lake();
                    performDFS(grid, i, j, rows, cols, visited, lake);

                    // Only add if the component is a valid lake (doesn't touch ocean)
                    if (!lake.touchesOcean && lake.size > 0) {
                        lakes.add(lake);
                    }
                }
            }
        }
        return lakes;
    }

    /**
     * Depth First Search to explore a connected component of '.' cells.
     */
    private static void performDFS(char[][] grid, int r, int c, int rows, int cols, 
                                   boolean[][] visited, Lake lake) {
        // Boundary and validity checks
        if (r < 0 || r >= rows || c < 0 || c >= cols) {
            lake.touchesOcean = true;
            return;
        }

        if (grid[r][c] == '~') {
            lake.touchesOcean = true;
            return;
        }

        if (grid[r][c] != '.' || visited[r][c]) {
            return;
        }

        // Mark as visited and add to component
        visited[r][c] = true;
        lake.cells.add(new Point(r, c));
        lake.size++;

        // Explore neighbors
        performDFS(grid, r - 1, c, rows, cols, visited, lake);
        performDFS(grid, r + 1, c, rows, cols, visited, lake);
        performDFS(grid, r, c - 1, rows, cols, visited, lake);
        performDFS(grid, r, c + 1, rows, cols, visited, lake);
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;

/**
 * A program to identify "lakes" in a grid (connected water cells not touching the boundary)
 * and fill the smallest lakes with '*' until the number of remaining lakes is <= k.
 */
public class LakeRefactorer {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        int targetLakeCount = scanner.nextInt();
        scanner.nextLine(); // Consume newline

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.nextLine();
            grid[i] = line.toCharArray();
        }

        LakeProcessor processor = new LakeProcessor(grid, targetLakeCount);
        processor.process();
        processor.printResult();
    }

    static class LakeProcessor {
        private final char[][] grid;
        private final int rows;
        private final int cols;
        private final int targetLakeCount;
        private final List<Set<Point>> lakes = new ArrayList<>();
        private int totalCellsReplaced = 0;

        // Direction vectors for BFS (Up, Down, Left, Right)
        private static final int[][] DIRECTIONS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

        public LakeProcessor(char[][] grid, int targetLakeCount) {
            this.grid = grid;
            this.rows = grid.length;
            this.cols = grid[0].length;
            this.targetLakeCount = targetLakeCount;
        }

        /**
         * Orchestrates the lake discovery and filling process.
         */
        public void process() {
            findLakes();
            fillSmallestLakes();
        }

        /**
         * Uses BFS to find all connected components of '.' cells.
         * Components touching the grid boundary are ignored.
         */
        private void findLakes() {
            boolean[][] visited = new boolean[rows][cols];

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.' && !visited[r][c]) {
                        discoverComponent(r, c, visited);
                    }
                }
            }
        }

        private void discoverComponent(int startRow, int startCol, boolean[][] visited) {
            Queue<Point> queue = new LinkedList<>();
            Set<Point> component = new HashSet<>();
            boolean touchesBoundary = false;

            Point start = new Point(startRow, startCol);
            queue.add(start);
            visited[startRow][startCol] = true;

            while (!queue.isEmpty()) {
                Point current = queue.poll();
                component.add(current);

                // Check if this cell is on the boundary
                if (current.row == 0 || current.row == rows - 1 || 
                    current.col == 0 || current.col == cols - 1) {
                    touchesBoundary = true;
                }

                for (int[] dir : DIRECTIONS) {
                    int nr = current.row + dir[0];
                    int nc = current.col + dir[1];

                    if (isValid(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        queue.add(new Point(nr, nc));
                    }
                }
            }

            // If the component does not touch the boundary, it's a lake
            if (!touchesBoundary) {
                lakes.add(component);
            }
        }

        /**
         * Fills the smallest lakes with '*' using a PriorityQueue until
         * the number of lakes is within the target count.
         */
        private void fillSmallestLakes() {
            // Sort lakes by size ascending
            PriorityQueue<Set<Point>> lakeQueue = new PriorityQueue<>(
                Comparator.comparingInt(Set::size)
            );
            lakeQueue.addAll(lakes);

            while (lakeQueue.size() > targetLakeCount) {
                Set<Point> smallestLake = lakeQueue.poll();
                totalCellsReplaced += smallestLake.size();

                for (Point p : smallestLake) {
                    grid[p.row][p.col] = '*';
                }
            }
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        public void printResult() {
            System.out.println(totalCellsReplaced);
            for (int i = 0; i < rows; i++) {
                System.out.println(new String(grid[i]));
            }
        }
    }

    /**
     * Represents a coordinate in the grid.
     */
    private static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Point)) return false;
            Point point = (Point) o;
            return row == point.row && col == point.col;
        }

        @Override
        public int hashCode() {
            return Objects.hash(row, col);
        }
    }
}

