/**
 * Handles the logic of identifying and processing lakes.
 */
class LakeSolver {
    private final FastReader reader;
    private int rows;
    private int cols;
    private int k;
    private char[][] grid;

    private static final int[] ROW_OFFSETS = {1, -1, 0, 0};
    private static final int[] COL_OFFSETS = {0, 0, -1, 1};

    public LakeSolver(FastReader reader) {
        this.reader = reader;
    }

    public void solve(PrintWriter out) {
        rows = reader.nextInt();
        cols = reader.nextInt();
        k = reader.nextInt();
        grid = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            grid[i] = reader.next().toCharArray();
        }

        List<Lake> enclosedLakes = findEnclosedLakes();

        // Sort lakes by size ascending to identify the smallest ones to fill.
        Collections.sort(enclosedLakes, Comparator.comparingInt(l -> l.size));

        int totalCellsConverted = 0;
        int lakesToFillCount = Math.max(0, enclosedLakes.size() - k);

        // Fill the smallest (enclosedLakes.size() - k) lakes with land ('*').
        for (int i = 0; i < lakesToFillCount; i++) {
            Lake lake = enclosedLakes.get(i);
            totalCellsConverted += lake.size;
            for (Cell cell : lake.cells) {
                grid[cell.r][cell.c] = '*';
            }
        }

        out.println(totalCellsConverted);
        printGrid(out);
    }

    /**
     * Uses BFS to find all connected components of '.' and identifies those 
     * that do not touch the grid boundary.
     */
    private List<Lake> findEnclosedLakes() {
        List<Lake> enclosedLakes = new ArrayList<>();
        boolean[][] visited = new boolean[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && !visited[r][c]) {
                    Lake component = bfs(r, c, visited);
                    if (component.isEnclosed()) {
                        enclosedLakes.add(component);
                    }
                }
            }
        }
        return enclosedLakes;
    }

    private Lake bfs(int startR, int startC, boolean[][] visited) {
        Deque<Cell> queue = new ArrayDeque<>();
        List<Cell> componentCells = new ArrayList<>();
        boolean touchesBoundary = false;

        Cell start = new Cell(startR, startC);
        queue.add(start);
        visited[startR][startC] = true;

        while (!queue.isEmpty()) {
            Cell curr = queue.poll();
            componentCells.add(curr);

            // If the component touches the boundary, it is not an enclosed lake.
            if (curr.r == 0 || curr.r == rows - 1 || curr.c == 0 || curr.c == cols - 1) {
                touchesBoundary = true;
            }

            for (int i = 0; i < 4; i++) {
                int nr = curr.r + ROW_OFFSETS[i];
                int nc = curr.c + COL_OFFSETS[i];

                if (isValid(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    queue.add(new Cell(nr, nc));
                }
            }
        }

        return new Lake(componentCells, !touchesBoundary);
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private void printGrid(PrintWriter out) {
        StringBuilder sb = new StringBuilder();
        for (int r = 0; r < rows; r++) {
            sb.setLength(0);
            for (int c = 0; c < cols; c++) {
                sb.append(grid[r][c]);
            }
            out.println(sb.toString());
        }
    }

    /**
     * Represents a single cell in the grid.
     */
    private static class Cell {
        final int r, c;
        Cell(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Represents a component of connected '.' cells.
     */
    private static class Lake {
        final int size;
        final List<Cell> cells;
        final boolean enclosed;

        Lake(List<Cell> cells, boolean enclosed) {
            this.cells = cells;
            this.size = cells.size();
            this.enclosed = enclosed;
        }

        boolean isEnclosed() {
            return enclosed;
        }
    }
}

