import java.io.*;
import java.util.*;

/**
 * A refactored solution to identify and fill the smallest "lakes" in a grid.
 * A lake is defined as a connected component of '.' cells that does not touch the grid boundary.
 */
public class LakeSolver {

    /**
     * Represents a coordinate in the 2D grid.
     */
    private static class Point {
        final int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Represents a discovered lake, containing all its constituent cells.
     */
    private static class Lake implements Comparable<Lake> {
        final List<Point> cells;
        final int size;

        Lake(List<Point> cells) {
            this.cells = cells;
            this.size = cells.size();
        }

        @Override
        public int compareTo(Lake other) {
            return Integer.compare(this.size, other.size);
        }
    }

    public static void main(String[] args) {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)))) {

            String firstLine = br.readLine();
            if (firstLine == null) return;

            StringTokenizer st = new StringTokenizer(firstLine);
            int rows = Integer.parseInt(st.nextToken());
            int cols = Integer.parseInt(st.nextToken());
            int k = Integer.parseInt(st.nextToken());

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = br.readLine().toCharArray();
            }

            List<Lake> lakes = findLakes(grid, rows, cols);

            // Sort lakes by size (ascending) to fill the smallest ones first
            Collections.sort(lakes);

            int totalFilledCells = 0;
            // Fill up to k smallest lakes
            for (int i = 0; i < k && i < lakes.size(); i++) {
                Lake lake = lakes.get(i);
                totalFilledCells += lake.size;
                for (Point p : lake.cells) {
                    grid[p.r][p.c] = '*';
                }
            }

            // Output results
            out.println(totalFilledCells);
            for (int i = 0; i < rows; i++) {
                out.println(new String(grid[i]));
            }
            out.flush();

        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Traverses the grid to find all connected components of '.' that are not on the boundary.
     * 
     * @param grid The input character grid.
     * @param rows Total rows.
     * @param cols Total columns.
     * @return A list of Lake objects.
     */
    private static List<Lake> findLakes(char[][] grid, int rows, int cols) {
        List<Lake> lakes = new ArrayList<>();
        boolean[][] visited = new boolean[rows][cols];

        // Direction vectors for 4-connectivity (Up, Down, Left, Right)
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                // If we find an unvisited water cell, start a BFS to explore the component
                if (grid[i][j] == '.' && !visited[i][j]) {
                    List<Point> componentCells = new ArrayList<>();
                    boolean touchesBoundary = false;

                    Queue<Point> queue = new ArrayDeque<>();
                    Point start = new Point(i, j);

                    queue.add(start);
                    visited[i][j] = true;

                    while (!queue.isEmpty()) {
                        Point curr = queue.poll();
                        componentCells.add(curr);

                        // Check if this cell is on the boundary of the grid
                        if (curr.r == 0 || curr.r == rows - 1 || curr.c == 0 || curr.c == cols - 1) {
                            touchesBoundary = true;
                        }

                        for (int d = 0; d < 4; d++) {
                            int nr = curr.r + dr[d];
                            int nc = curr.c + dc[d];

                            // Standard bounds and connectivity check
                            if (isValid(nr, nc, rows, cols) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                                visited[nr][nc] = true;
                                queue.add(new Point(nr, nc));
                            }
                        }
                    }

                    // If the component never touched the boundary, it is a lake
                    if (!touchesBoundary) {
                        lakes.add(new Lake(componentCells));
                    }
                }
            }
        }
        return lakes;
    }

    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

import java.io.*;
import java.util.*;

/**
 * GridIslandManager processes a grid of characters to identify connected components (islands)
 * of '.' cells and determines which islands to "destroy" (replace with '*') to reach a 
 * target number of non-boundary islands.
 */
public class GridIslandManager {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            int targetIslandCount = reader.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = reader.nextLine();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }

            processGrid(rows, cols, targetIslandCount, grid, writer);

        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            writer.flush();
            writer.close();
        }
    }

    private static void processGrid(int rows, int cols, int targetCount, char[][] grid, PrintWriter writer) {
        UnionFind uf = new UnionFind(rows * cols);

        // Step 1: Build the Disjoint Set Union for all '.' cells
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    // Check right neighbor
                    if (c + 1 < cols && grid[r][c + 1] == '.') {
                        uf.union(r * cols + c, r * cols + (c + 1));
                    }
                    // Check bottom neighbor
                    if (r + 1 < rows && grid[r + 1][c] == '.') {
                        uf.union(r * cols + c, (r + 1) * cols + c);
                    }
                }
            }
        }

        // Step 2: Group cells into Islands
        Map<Integer, List<Cell>> componentMap = new HashMap<>();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    int root = uf.find(r * cols + c);
                    componentMap.computeIfAbsent(root, k -> new ArrayList<>()).add(new Cell(r, c));
                }
            }
        }

        // Step 3: Identify "Safe Islands" (those that do not touch the boundary)
        List<Island> safeIslands = new ArrayList<>();
        for (List<Cell> cells : componentMap.values()) {
            boolean touchesBoundary = false;
            for (Cell cell : cells) {
                if (cell.isAtBoundary(rows, cols)) {
                    touchesBoundary = true;
                    break;
                }
            }
            if (!touchesBoundary) {
                safeIslands.add(new Island(cells));
            }
        }

        // Step 4: Sort safe islands by size (ascending) to minimize changes
        Collections.sort(safeIslands, Comparator.comparingInt(Island::size));

        // Step 5: Destroy the smallest safe islands until target count is met
        int numToDestroy = safeIslands.size() - targetCount;
        int cellsChanged = 0;

        if (numToDestroy > 0) {
            for (int i = 0; i < numToDestroy; i++) {
                Island islandToDestroy = safeIslands.get(i);
                for (Cell cell : islandToDestroy.getCells()) {
                    grid[cell.r][cell.c] = '*';
                    cellsChanged++;
                }
            }
        }

        // Step 6: Output Results
        writer.println(cellsChanged);
        for (int i = 0; i < rows; i++) {
            writer.println(new String(grid[i]));
        }
    }

    /**
     * Represents a single coordinate in the grid.
     */
    static class Cell {
        final int r, c;

        Cell(int r, int c) {
            this.r = r;
            this.c = c;
        }

        boolean isAtBoundary(int rows, int cols) {
            return r == 0 || r == rows - 1 || c == 0 || c == cols - 1;
        }
    }

    /**
     * Represents a collection of connected cells.
     */
    static class Island {
        private final List<Cell> cells;

        Island(List<Cell> cells) {
            this.cells = cells;
        }

        int size() {
            return cells.size();
        }

        List<Cell> getCells() {
            return cells;
        }
    }

    /**
     * Standard Union-Find (Disjoint Set Union) with path compression and union by rank.
     */
    static class UnionFind {
        private final int[] parent;
        private final int[] rank;

        UnionFind(int n) {
            parent = new int[n];
            rank = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
            }
        }

        int find(int i) {
            if (parent[i] == i) return i;
            return parent[i] = find(parent[i]); // Path compression
        }

        void union(int i, int j) {
            int rootI = find(i);
            int rootJ = find(j);
            if (rootI != rootJ) {
                // Union by rank
                if (rank[rootI] < rank[rootJ]) {
                    parent[rootI] = rootJ;
                } else if (rank[rootI] > rank[rootJ]) {
                    parent[rootJ] = rootI;
                } else {
                    parent[rootI] = rootJ;
                    rank[rootJ]++;
                }
            }
        }
    }

    /**
     * Efficient input reader for large datasets.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public String nextLine() {
            if (tokenizer != null && tokenizer.hasMoreElements()) {
                StringBuilder sb = new StringBuilder();
                while (tokenizer.hasMoreElements()) {
                    sb.append(tokenizer.nextToken());
                    if (tokenizer.hasMoreElements()) sb.append(" ");
                }
                tokenizer = null;
                return sb.toString();
            }
            try {
                return reader.readLine();
            } catch (IOException e) {
                return null;
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.*;

/**
 * This program identifies connected components of '.' characters in a grid,
 * selects the k largest components, replaces them with '*', and outputs 
 * the sum of their sizes and the modified grid.
 */
public class GridComponentProcessor {

    // Direction vectors for exploring adjacent cells (Down, Up, Right, Left)
    private static final int[] ROW_OFFSETS = {1, -1, 0, 0};
    private static final int[] COL_OFFSETS = {0, 0, 1, -1};

    /**
     * Represents a connected component found in the grid.
     */
    private static class Component implements Comparable<Component> {
        private final int startRow;
        private final int startCol;
        private final int size;

        public Component(int startRow, int startCol, int size) {
            this.startRow = startRow;
            this.startCol = startCol;
            this.size = size;
        }

        public int getSize() {
            return size;
        }

        @Override
        public int compareTo(Component other) {
            // Sort in descending order of size to pick the largest components first
            return Integer.compare(other.size, this.size);
        }
    }

    public static void main(String[] args) {
        FastReader reader = new FastReader();

        // Read dimensions and the number of components to process
        String firstToken = reader.next();
        if (firstToken == null) return;

        int rows = Integer.parseInt(firstToken);
        int cols = reader.nextInt();
        int targetCount = reader.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = reader.nextRow(cols);
        }

        processGrid(grid, rows, cols, targetCount);
    }

    /**
     * Orchestrates the discovery, selection, and modification of grid components.
     */
    private static void processGrid(char[][] grid, int rows, int cols, int targetCount) {
        boolean[][] visited = new boolean[rows][cols];
        List<Component> components = new ArrayList<>();

        // 1. Identify all '.' components using BFS to avoid StackOverflowError
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && !visited[r][c]) {
                    components.add(findComponentBFS(grid, visited, r, c, rows, cols));
                }
            }
        }

        // 2. Sort components by size (descending)
        Collections.sort(components);

        // 3. Select up to 'targetCount' largest components and change them to '*'
        int totalSizeSum = 0;
        int limit = Math.min(targetCount, components.size());
        for (int i = 0; i < limit; i++) {
            Component comp = components.get(i);
            totalSizeSum += comp.getSize();
            applyAsteriskToComponent(grid, comp, rows, cols);
        }

        // 4. Output the total size sum and the modified grid
        System.out.println(totalSizeSum);
        printGrid(grid);
    }

    /**
     * BFS implementation to find the size and starting position of a connected component.
     */
    private static Component findComponentBFS(char[][] grid, boolean[][] visited, int startR, int startC, int rows, int cols) {
        int size = 0;
        Queue<int[]> queue = new LinkedList<>();

        queue.add(new int[]{startR, startC});
        visited[startR][startC] = true;

        while (!queue.isEmpty()) {
            int[] cell = queue.poll();
            size++;

            for (int i = 0; i < 4; i++) {
                int nr = cell[0] + ROW_OFFSETS[i];
                int nc = cell[1] + COL_OFFSETS[i];

                if (isWithinBounds(nr, nc, rows, cols) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    queue.add(new int[]{nr, nc});
                }
            }
        }
        return new Component(startR, startC, size);
    }

    /**
     * BFS implementation to transform a specific component into '*' characters.
     */
    private static void applyAsteriskToComponent(char[][] grid, Component component, int rows, int cols) {
        Queue<int[]> queue = new LinkedList<>();
        queue.add(new int[]{component.startRow, component.startCol});
        grid[component.startRow][component.startCol] = '*';

        while (!queue.isEmpty()) {
            int[] cell = queue.poll();

            for (int i = 0; i < 4; i++) {
                int nr = cell[0] + ROW_OFFSETS[i];
                int nc = cell[1] + COL_OFFSETS[i];

                if (isWithinBounds(nr, nc, rows, cols) && grid[nr][nc] == '.') {
                    grid[nr][nc] = '*';
                    queue.add(new int[]{nr, nc});
                }
            }
        }
    }

    private static boolean isWithinBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private static void printGrid(char[][] grid) {
        StringBuilder sb = new StringBuilder();
        for (char[] row : grid) {
            sb.append(row).append('\n');
        }
        System.out.print(sb.toString());
    }

    /**
     * Utility class for efficient input reading.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader() {
            reader = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            return next != null ? Integer.parseInt(next) : 0;
        }

        public char[] nextRow(int cols) {
            try {
                String line = reader.readLine();
                char[] row = new char[cols];
                for (int i = 0; i < cols; i++) {
                    row[i] = line.charAt(i);
                }
                return row;
            } catch (Exception e) {
                return new char[cols];
            }
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * LakeManager identifies "lakes" (enclosed areas of '.' characters) 
 * in a grid and fills the smallest ones with '*' until only k lakes remain.
 */
public class LakeManager {

    // Directions for 4-way connectivity (Up, Down, Left, Right)
    private static final int[][] DIRECTIONS = {
        {0, 1}, {0, -1}, {1, 0}, {-1, 0}
    };

    private final int rows;
    private final int cols;
    private final char[][] grid;

    /**
     * Represents a connected component of '.' cells.
     */
    private static class Lake {
        final List<int[]> cells = new ArrayList<>();
        boolean isEnclosed = true;

        int size() {
            return cells.size();
        }
    }

    public LakeManager(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
    }

    /**
     * Main logic to process lakes based on the requirement to keep k lakes.
     * 
     * @param k The number of lakes to remain after processing.
     */
    public void processLakes(int k) {
        List<Lake> lakes = findEnclosedLakes();

        // Sort lakes by size ascending so we fill the smallest ones first
        lakes.sort(Comparator.comparingInt(Lake::size));

        int totalLakes = lakes.size();
        int lakesToRemove = Math.max(0, totalLakes - k);
        int totalCellsFilled = 0;

        for (int i = 0; i < lakesToRemove; i++) {
            for (int[] cell : lakes.get(i).cells) {
                grid[cell[0]][cell[1]] = '*';
                totalCellsFilled++;
            }
        }

        printOutput(totalCellsFilled);
    }

    /**
     * Traverses the grid to find all connected components of '.' that do not touch the boundary.
     * 
     * @return A list of enclosed Lake objects.
     */
    private List<Lake> findEnclosedLakes() {
        List<Lake> enclosedLakes = new ArrayList<>();
        boolean[][] visited = new boolean[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && !visited[r][c]) {
                    Lake lake = bfs(r, c, visited);
                    if (lake.isEnclosed) {
                        enclosedLakes.add(lake);
                    }
                }
            }
        }
        return enclosedLakes;
    }

    /**
     * Uses BFS to find all connected '.' cells and determines if the component is enclosed.
     */
    private Lake bfs(int startR, int startC, boolean[][] visited) {
        Lake lake = new Lake();
        Deque<int[]> queue = new ArrayDeque<>();

        queue.add(new int[]{startR, startC});
        visited[startR][startC] = true;

        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            int r = curr[0];
            int c = curr[1];

            lake.cells.add(curr);

            // If any cell in the component is on the grid boundary, it's not a "lake"
            if (r == 0 || r == rows - 1 || c == 0 || c == cols - 1) {
                lake.isEnclosed = false;
            }

            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                if (isValid(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    queue.add(new int[]{nr, nc});
                }
            }
        }
        return lake;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private void printOutput(int cellsFilled) {
        StringBuilder sb = new StringBuilder();
        sb.append(cellsFilled).append("\n");
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                sb.append(grid[i][j]);
            }
            sb.append("\n");
        }
        System.out.print(sb.toString());
    }

    public static void main(String[] args) throws IOException {
        // Use Fast I/O for better performance
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String firstLine = reader.readLine();
        if (firstLine == null) return;

        StringTokenizer st = new StringTokenizer(firstLine);
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String rowStr = reader.readLine();
            if (rowStr != null) {
                grid[i] = rowStr.toCharArray();
            }
        }

        LakeManager manager = new LakeManager(n, m, grid);
        manager.processLakes(k);
    }
}

import java.util.*;

/**
 * A program to identify "lakes" (connected water components not touching the boundary)
 * and fill the largest lakes with '*' until only K lakes remain.
 */
public class LakeManagementSystem {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        int targetLakeCount = scanner.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String rowString = scanner.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = rowString.charAt(j);
            }
        }

        LakeManager manager = new LakeManager(grid, rows, cols);
        manager.processLakes(targetLakeCount);
        manager.printResult();
    }

    /**
     * Represents a single coordinate in the grid.
     */
    static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Represents a collection of connected water cells.
     */
    static class Lake implements Comparable<Lake> {
        private final List<Point> cells;

        Lake(List<Point> cells) {
            this.cells = cells;
        }

        public List<Point> getCells() {
            return cells;
        }

        public int getSize() {
            return cells.size();
        }

        @Override
        public int compareTo(Lake other) {
            // Sort in descending order of size
            return Integer.compare(other.getSize(), this.getSize());
        }
    }

    /**
     * Handles the logic of finding, sorting, and filling lakes.
     */
    static class LakeManager {
        private final char[][] grid;
        private final int rows;
        private final int cols;
        private final List<Lake> lakes = new ArrayList<>();
        private int filledCellsCount = 0;

        private static final int[] DR = {-1, 1, 0, 0};
        private static final int[] DC = {0, 0, -1, 1};

        public LakeManager(char[][] grid, int rows, int cols) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
        }

        /**
         * Identifies all lakes and fills the largest ones to reach targetLakeCount.
         */
        public void processLakes(int targetLakeCount) {
            boolean[][] visited = new boolean[rows][cols];

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.' && !visited[r][c]) {
                        findComponent(r, c, visited);
                    }
                }
            }

            Collections.sort(lakes);

            // Calculate how many lakes need to be filled to leave exactly K lakes
            int numToFill = Math.max(0, lakes.size() - targetLakeCount);
            for (int i = 0; i < numToFill; i++) {
                fillLake(lakes.get(i));
            }
        }

        /**
         * Uses BFS to find a connected component of water. 
         * If the component doesn't touch the boundary, it's a lake.
         */
        private void findComponent(int startR, int startC, boolean[][] visited) {
            List<Point> component = new ArrayList<>();
            Queue<Point> queue = new ArrayDeque<>();
            boolean touchesBoundary = false;

            Point start = new Point(startR, startC);
            queue.add(start);
            visited[startR][startC] = true;

            while (!queue.isEmpty()) {
                Point curr = queue.poll();
                component.add(curr);

                if (isBoundary(curr.row, curr.col)) {
                    touchesBoundary = true;
                }

                for (int i = 0; i < 4; i++) {
                    int nr = curr.row + DR[i];
                    int nc = curr.col + DC[i];

                    if (isValidMove(nr, nc, visited)) {
                        visited[nr][nc] = true;
                        queue.add(new Point(nr, nc));
                    }
                }
            }

            if (!touchesBoundary) {
                lakes.add(new Lake(component));
            }
        }

        private boolean isValidMove(int r, int c, boolean[][] visited) {
            return r >= 0 && r < rows && c >= 0 && c < cols 
                    && grid[r][c] == '.' && !visited[r][c];
        }

        private boolean isBoundary(int r, int c) {
            return r == 0 || r == rows - 1 || c == 0 || c == cols - 1;
        }

        private void fillLake(Lake lake) {
            for (Point p : lake.getCells()) {
                grid[p.row][p.col] = '*';
                filledCellsCount++;
            }
        }

        public void printResult() {
            System.out.println(filledCellsCount);
            StringBuilder sb = new StringBuilder();
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    sb.append(grid[r][c]);
                }
                sb.append("\n");
            }
            System.out.print(sb.toString());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver for the grid component reduction problem.
 * The goal is to remove the minimum number of '.' cells to reduce the number of 
 * non-boundary connected components to a target value k.
 */
public class GridComponentReducer {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            int targetK = reader.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            GridComponentSolver solver = new GridComponentSolver(grid, targetK);
            solver.solve(writer);
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Represents a single coordinate in the grid.
     */
    record Point(int r, int c) {}

    /**
     * Represents a connected component of '.' cells.
     */
    private static class Component {
        private final List<Point> cells = new ArrayList<>();
        private boolean touchesBoundary = false;

        public void addCell(int r, int c, int rows, int cols) {
            cells.add(new Point(r, c));
            if (r == 0 || r == rows - 1 || c == 0 || c == cols - 1) {
                touchesBoundary = true;
            }
        }

        public int size() {
            return cells.size();
        }

        public boolean touchesBoundary() {
            return touchesBoundary;
        }

        public List<Point> getCells() {
            return cells;
        }
    }

    private static class GridComponentSolver {
        private final int rows;
        private final int cols;
        private final int targetK;
        private final char[][] grid;
        private final boolean[][] visited;

        private static final int[] DR = {0, 0, 1, -1};
        private static final int[] DC = {1, -1, 0, 0};

        public GridComponentSolver(char[][] grid, int targetK) {
            this.grid = grid;
            this.rows = grid.length;
            this.cols = grid[0].length;
            this.targetK = targetK;
            this.visited = new boolean[rows][cols];
        }

        public void solve(PrintWriter out) {
            List<Component> allComponents = findComponents();

            List<Component> innerComponents = new ArrayList<>();
            for (Component comp : allComponents) {
                if (!comp.touchesBoundary()) {
                    innerComponents.add(comp);
                }
            }

            // Sort inner components by size to remove the smallest ones first (greedy approach)
            innerComponents.sort(Comparator.comparingInt(Component::size));

            int removedCellsCount = 0;
            int currentInnerCount = innerComponents.size();
            int index = 0;

            // While we have more inner components than the target k, remove the smallest
            while (currentInnerCount > targetK && index < innerComponents.size()) {
                Component toRemove = innerComponents.get(index++);
                for (Point p : toRemove.getCells()) {
                    grid[p.r()][p.c()] = '*';
                }
                removedCellsCount += toRemove.size();
                currentInnerCount--;
            }

            // Output results
            out.println(removedCellsCount);
            for (int i = 0; i < rows; i++) {
                out.println(new String(grid[i]));
            }
        }

        /**
         * Uses BFS to identify all connected components of '.' cells.
         */
        private List<Component> findComponents() {
            List<Component> components = new ArrayList<>();

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.' && !visited[i][j]) {
                        components.add(bfs(i, j));
                    }
                }
            }
            return components;
        }

        private Component bfs(int startR, int startC) {
            Component component = new Component();
            Queue<Point> queue = new LinkedList<>();

            Point start = new Point(startR, startC);
            queue.add(start);
            visited[startR][startC] = true;

            while (!queue.isEmpty()) {
                Point current = queue.poll();
                component.addCell(current.r(), current.c(), rows, cols);

                for (int i = 0; i < 4; i++) {
                    int nr = current.r() + DR[i];
                    int nc = current.c() + DC[i];

                    if (isValid(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        queue.add(new Point(nr, nc));
                    }
                }
            }
            return component;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * Utility class for fast input parsing.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

