/**
 * Represents a connected component of empty cells ('.') in the grid.
 */
class Component implements Comparable<Component> {
    private final int size;
    private final int row;
    private final int col;

    public Component(int size, int row, int col) {
        this.size = size;
        this.row = row;
        this.col = col;
    }

    public int getSize() {
        return size;
    }

    public int getRow() {
        return row;
    }

    public int getCol() {
        return col;
    }

    @Override
    public int compareTo(Component other) {
        // Sorts components in ascending order by size
        return Integer.compare(this.size, other.size);
    }
}

/**
 * Manages the grid operations including finding and modifying components.
 */
class GridManager {
    private final int rows;
    private final int cols;
    private final char[][] grid;
    private boolean[][] visited;
    private boolean touchesBoundary;

    public GridManager(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.visited = new boolean[rows][cols];
    }

    /**
     * Scans the grid to find all connected components of '.' that do not touch the grid boundary.
     * @return A list of valid Components.
     */
    public List<Component> findValidComponents() {
        List<Component> components = new ArrayList<>();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && !visited[r][c]) {
                    touchesBoundary = false;
                    int size = performDFSCount(r, c);
                    if (!touchesBoundary) {
                        components.add(new Component(size, r, c));
                    }
                }
            }
        }
        return components;
    }

    private int performDFSCount(int r, int c) {
        // If we step out of bounds, the component touches the boundary
        if (r < 0 || r >= rows || c < 0 || c >= cols) {
            touchesBoundary = true;
            return 0;
        }

        // If we hit an obstacle or an already visited cell, stop recursion
        if (grid[r][c] == '*' || visited[r][c]) {
            return 0;
        }

        visited[r][c] = true;
        int count = 1;
        count += performDFSCount(r + 1, c);
        count += performDFSCount(r - 1, c);
        count += performDFSCount(r, c + 1);
        count += performDFSCount(r, c - 1);
        return count;
    }

    /**
     * Converts specified components into obstacles ('*').
     * @param componentsToFill The list of components to be filled.
     */
    public void fillComponents(List<Component> componentsToFill) {
        // Reset visited array for the modification phase
        visited = new boolean[rows][cols];
        for (Component comp : componentsToFill) {
            performDFSFill(comp.getRow(), comp.getCol());
        }
    }

    private void performDFSFill(int r, int c) {
        if (r < 0 || r >= rows || c < 0 || c >= cols || grid[r][c] == '*' || visited[r][c]) {
            return;
        }
        visited[r][c] = true;
        grid[r][c] = '*';
        performDFSFill(r + 1, c);
        performDFSFill(r - 1, c);
        performDFSFill(r, c + 1);
        performDFSFill(r, c - 1);
    }

    public void printGrid() {
        for (int i = 0; i < rows; i++) {
            System.out.println(new String(grid[i]));
        }
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int n = scanner.nextInt();
        int m = scanner.nextInt();
        int k = scanner.nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        GridManager gridManager = new GridManager(n, m, grid);

        // 1. Identify all valid components (those not touching the edge)
        List<Component> components = gridManager.findValidComponents();

        // 2. Sort components by size ascending
        Collections.sort(components);

        // 3. Calculate how many of the smallest components to remove
        // The original logic: remove the (Total - K) smallest components
        int numToFill = components.size() - k;
        int totalCellsRemoved = 0;
        List<Component> componentsToRemove = new ArrayList<>();

        if (numToFill > 0) {
            for (int i = 0; i < numToFill; i++) {
                Component comp = components.get(i);
                totalCellsRemoved += comp.getSize();
                componentsToRemove.add(comp);
            }
            // 4. Apply the changes to the grid
            gridManager.fillComponents(componentsToRemove);
        }

        // 5. Output Results
        System.out.println(totalCellsRemoved);
        gridManager.printGrid();

        scanner.close();
    }
}

import java.util.*;

/**
 * Application to identify "lakes" in a grid and fill the smallest ones with '*'.
 * A lake is defined as a connected component of '.' cells that does not touch the grid boundary.
 */
public class LakeManager {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        int k = scanner.nextInt();

        char[][] gridData = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            gridData[i] = line.toCharArray();
        }

        Grid grid = new Grid(gridData);
        processLakes(grid, k);
        grid.print();

        scanner.close();
    }

    private static void processLakes(Grid grid, int k) {
        List<Lake> lakes = grid.findLakes();

        // Sort lakes by size ascending (smallest first)
        lakes.sort(Comparator.comparingInt(Lake::size));

        // The requirement is to fill (totalLakes - k) smallest lakes.
        // This leaves the k largest lakes untouched.
        int lakesToFillCount = lakes.size() - k;
        int totalFilledCells = 0;

        for (int i = 0; i < lakesToFillCount; i++) {
            Lake lake = lakes.get(i);
            totalFilledCells += lake.size();
            grid.fillLake(lake);
        }

        System.out.println(totalFilledCells);
    }

    /**
     * Represents a single coordinate in the grid.
     */
    private record Point(int r, int c) {}

    /**
     * Represents a collection of connected points forming a lake.
     */
    private static class Lake {
        private final List<Point> points;

        public Lake(List<Point> points) {
            this.points = Collections.unmodifiableList(points);
        }

        public int size() {
            return points.size();
        }

        public List<Point> getPoints() {
            return points;
        }
    }

    /**
     * Handles the grid logic, including component searching and filling.
     */
    private static class Grid {
        private final int rows;
        private final int cols;
        private final char[][] cells;

        private static final int[] DR = {-1, 1, 0, 0};
        private static final int[] DC = {0, 0, -1, 1};

        public Grid(char[][] cells) {
            this.rows = cells.length;
            this.cols = cells[0].length;
            this.cells = cells;
        }

        /**
         * Finds all connected components of '.' that do not touch the boundary.
         */
        public List<Lake> findLakes() {
            List<Lake> lakes = new ArrayList<>();
            boolean[][] visited = new boolean[rows][cols];

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (cells[r][c] == '.' && !visited[r][c]) {
                        Lake component = exploreComponent(r, c, visited);
                        if (component != null) {
                            lakes.add(component);
                        }
                    }
                }
            }
            return lakes;
        }

        /**
         * Uses BFS to find all connected '.' cells and determines if it's a valid lake.
         */
        private Lake exploreComponent(int startR, int startC, boolean[][] visited) {
            List<Point> componentPoints = new ArrayList<>();
            Queue<Point> queue = new LinkedList<>();
            boolean touchesBoundary = false;

            Point start = new Point(startR, startC);
            queue.add(start);
            visited[startR][startC] = true;

            while (!queue.isEmpty()) {
                Point current = queue.poll();
                componentPoints.add(current);

                // Check if this point is on the edge
                if (current.r() == 0 || current.r() == rows - 1 || 
                    current.c() == 0 || current.c() == cols - 1) {
                    touchesBoundary = true;
                }

                for (int i = 0; i < 4; i++) {
                    int nr = current.r() + DR[i];
                    int nc = current.c() + DC[i];

                    if (isValidMove(nr, nc, visited)) {
                        visited[nr][nc] = true;
                        queue.add(new Point(nr, nc));
                    }
                }
            }

            // If the component touches the boundary, it is not a lake
            return touchesBoundary ? null : new Lake(componentPoints);
        }

        private boolean isValidMove(int r, int c, boolean[][] visited) {
            return r >= 0 && r < rows && c >= 0 && c < cols 
                   && cells[r][c] == '.' && !visited[r][c];
        }

        public void fillLake(Lake lake) {
            for (Point p : lake.getPoints()) {
                cells[p.r()][p.c()] = '*';
            }
        }

        public void print() {
            StringBuilder sb = new StringBuilder();
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    sb.append(cells[r][c]);
                }
                sb.append("\n");
            }
            System.out.print(sb.toString());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * BerlandLakes solves the problem of finding enclosed water bodies (lakes)
 * and filling the smallest ones with land to keep exactly K lakes.
 */
public class BerlandLakes {

    private static final int[][] DIRECTIONS = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

    // Data transfer objects for better readability
    private record Point(int r, int c) {}
    private record Lake(int size, int startR, int startC) {}

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        int rows = reader.nextInt();
        int cols = reader.nextInt();
        int k = reader.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = reader.next().toCharArray();
        }

        BerlandLakes solver = new BerlandLakes();
        solver.solve(grid, rows, cols, k);
    }

    public void solve(char[][] grid, int rows, int cols, int k) {
        // 1. Mark all water connected to the boundary (the "Sea")
        // We use 'S' to distinguish sea water from enclosed lakes.
        markSea(grid, rows, cols);

        // 2. Find all enclosed lakes (remaining '.' cells)
        List<Lake> lakes = findEnclosedLakes(grid, rows, cols);

        // 3. Sort lakes by size in descending order to keep the largest K
        lakes.sort((a, b) -> Integer.compare(b.size(), a.size()));

        int totalFilledCells = 0;

        // 4. Fill the lakes that we don't keep (from index k onwards)
        if (k < lakes.size()) {
            for (int i = k; i < lakes.size(); i++) {
                Lake lakeToFill = lakes.get(i);
                totalFilledCells += lakeToFill.size();
                fillLake(grid, lakeToFill.startR, lakeToFill.startC);
            }
        }

        // 5. Output the result
        System.out.println(totalFilledCells);
        printGrid(grid, rows, cols);
    }

    private void markSea(char[][] grid, int rows, int cols) {
        Deque<Point> queue = new ArrayDeque<>();

        // Add all boundary water cells to the queue
        for (int i = 0; i < rows; i++) {
            if (grid[i][0] == '.') { grid[i][0] = 'S'; queue.add(new Point(i, 0)); }
            if (grid[i][cols - 1] == '.') { grid[i][cols - 1] = 'S'; queue.add(new Point(i, cols - 1)); }
        }
        for (int j = 0; j < cols; j++) {
            if (grid[0][j] == '.') { grid[0][j] = 'S'; queue.add(new Point(0, j)); }
            if (grid[rows - 1][j] == '.') { grid[rows - 1][j] = 'S'; queue.add(new Point(rows - 1, j)); }
        }

        // BFS to mark the entire sea area
        bfs(grid, queue, 'S');
    }

    private List<Lake> findEnclosedLakes(char[][] grid, int rows, int cols) {
        List<Lake> lakes = new ArrayList<>();
        boolean[][] visited = new boolean[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.' && !visited[i][j]) {
                    // Found a new enclosed lake
                    int size = 0;
                    Deque<Point> queue = new ArrayDeque<>();
                    Point start = new Point(i, j);
                    queue.add(start);
                    visited[i][j] = true;

                    while (!queue.isEmpty()) {
                        Point curr = queue.poll();
                        size++;
                        for (int[] dir : DIRECTIONS) {
                            int nr = curr.r + dir[0];
                            int nc = curr.c + dir[1];
                            if (isValid(nr, nc, rows, cols) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                                visited[nr][nc] = true;
                                queue.add(new Point(nr, nc));
                            }
                        }
                    }
                    lakes.add(new Lake(size, i, j));
                }
            }
        }
        return lakes;
    }

    private void fillLake(char[][] grid, int startR, int startC) {
        Deque<Point> queue = new ArrayDeque<>();
        queue.add(new Point(startR, startC));
        grid[startR][startC] = '*';

        while (!queue.isEmpty()) {
            Point curr = queue.poll();
            for (int[] dir : DIRECTIONS) {
                int nr = curr.r + dir[0];
                int nc = curr.c + dir[1];
                if (isValid(nr, nc, grid.length, grid[0].length) && grid[nr][nc] == '.') {
                    grid[nr][nc] = '*';
                    queue.add(new Point(nr, nc));
                }
            }
        }
    }

    private void bfs(char[][] grid, Deque<Point> queue, char marker) {
        int rows = grid.length;
        int cols = grid[0].length;

        while (!queue.isEmpty()) {
            Point curr = queue.poll();
            for (int[] dir : DIRECTIONS) {
                int nr = curr.r + dir[0];
                int nc = curr.c + dir[1];
                if (isValid(nr, nc, rows, cols) && grid[nr][nc] == '.') {
                    grid[nr][nc] = marker;
                    queue.add(new Point(nr, nc));
                }
            }
        }
    }

    private boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private void printGrid(char[][] grid, int rows, int cols) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                // Convert 'S' (sea) back to '.' (water) for output
                if (grid[i][j] == 'S') sb.append('.');
                else sb.append(grid[i][j]);
            }
            sb.append('\n');
        }
        System.out.print(sb);
    }

    /**
     * Fast I/O implementation for efficient input reading.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A solver for determining if a specific color/type is reachable 
 * along orthogonal or diagonal lines from a given origin.
 */
public class GameGridSolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int testCases = 1; // Defaulting to 1 as per original code
        while (testCases-- > 0) {
            solve(reader, out);
        }
        out.close();
    }

    private static void solve(FastReader reader, PrintWriter out) {
        int n = reader.nextInt();
        int originX = reader.nextInt();
        int originY = reader.nextInt();

        // Directions: 0:N, 1:S, 2:E, 3:W, 4:NE, 5:NW, 6:SE, 7:SW
        int[] minDistances = new int[8];
        Item[] bestItems = new Item[8];
        Arrays.fill(minDistances, Integer.MAX_VALUE);

        for (int i = 0; i < n; i++) {
            char type = reader.nextChar();
            int x = reader.nextInt();
            int y = reader.nextInt();

            int dx = x - originX;
            int dy = y - originY;

            int direction = getDirection(dx, dy);
            if (direction != -1) {
                int distance = Math.abs(dx) != 0 ? Math.abs(dx) : Math.abs(dy);
                if (distance < minDistances[direction]) {
                    minDistances[direction] = distance;
                    bestItems[direction] = new Item(type, dx, dy);
                }
            }
        }

        out.println(isTargetFound(bestItems) ? "YES" : "NO");
    }

    /**
     * Maps relative coordinates to one of 8 directions.
     * Returns -1 if the point is not on an orthogonal or 45-degree diagonal line.
     */
    private static int getDirection(int dx, int dy) {
        if (dx == 0 && dy > 0) return 0;  // North
        if (dx == 0 && dy < 0) return 1;  // South
        if (dx > 0 && dy == 0) return 2;  // East
        if (dx < 0 && dy == 0) return 3;  // West

        int absDx = Math.abs(dx);
        int absDy = Math.abs(dy);

        if (absDx == absDy && absDx != 0) {
            if (dx > 0 && dy > 0) return 4;  // NE
            if (dx < 0 && dy > 0) return 5;  // NW
            if (dx > 0 && dy < 0) return 6;  // SE
            if (dx < 0 && dy < 0) return 7;  // SW
        }
        return -1;
    }

    /**
     * Checks if any of the closest items in the 8 directions satisfy the win condition.
     */
    private static boolean isTargetFound(Item[] bestItems) {
        for (int i = 0; i < 8; i++) {
            if (bestItems[i] == null) continue;

            char type = bestItems[i].type;
            // Directions 0-3 are orthogonal (N, S, E, W)
            if (i <= 3) {
                if (type == 'R' || type == 'Q') return true;
            } 
            // Directions 4-7 are diagonal (NE, NW, SE, SW)
            else {
                if (type == 'B' || type == 'Q') return true;
            }
        }
        return false;
    }

    static class Item {
        char type;
        int dx, dy;

        Item(char type, int dx, int dy) {
            this.type = type;
            this.dx = dx;
            this.dy = dy;
        }
    }

    /**
     * Optimized reader for faster I/O performance.
     */
    static class FastReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int curChar;
        private int numChars;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (numChars == -1) throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buffer);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) return -1;
            }
            return buffer[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res *= 10;
                res += (c - '0');
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public char nextChar() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            return (char) c;
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.util.*;

/**
 * Refactored solution for the Anton and Chess problem.
 * Determines if a King is under attack by any other chess piece on the board.
 */
public class AntonAndChess {

    /**
     * Represents the 8 directions on a chess board.
     */
    enum Direction {
        N, NE, E, SE, S, SW, W, NW;

        /**
         * Checks if a piece type can attack in this specific direction.
         * Orthogonal directions: Rook or Queen.
         * Diagonal directions: Bishop or Queen.
         */
        boolean isAttackingDirection(char type) {
            boolean isDiagonal = this == NE || this == SE || this == SW || this == NW;
            if (isDiagonal) {
                return type == 'B' || type == 'Q';
            } else {
                return type == 'R' || type == 'Q';
            }
        }
    }

    /**
     * Represents a piece and its distance from the King.
     */
    private static class Piece {
        final char type;
        final int distance;

        Piece(char type, int distance) {
            this.type = type;
            this.distance = distance;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int n = scanner.nextInt();

        int kingX = scanner.nextInt();
        int kingY = scanner.nextInt();

        // Map to store the closest piece found in each of the 8 directions
        Map<Direction, Piece> closestPieces = new EnumMap<>(Direction.class);

        for (int i = 0; i < n; i++) {
            char type = scanner.next().charAt(0);
            int px = scanner.nextInt();
            int py = scanner.nextInt();

            Direction dir = getDirection(kingX, kingY, px, py);

            if (dir != null) {
                int distance = calculateChebyshevDistance(kingX, kingY, px, py);
                updateClosestPiece(closestPieces, dir, new Piece(type, distance));
            }
        }

        if (isKingInCheck(closestPieces)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Determines the direction of a piece relative to the king.
     */
    private static Direction getDirection(int kX, int kY, int pX, int pY) {
        int dx = pX - kX;
        int dy = pY - kY;

        if (dx == 0 && dy != 0) {
            return dy > 0 ? Direction.N : Direction.S;
        } else if (dy == 0 && dx != 0) {
            return dx > 0 ? Direction.E : Direction.W;
        } else if (Math.abs(dx) == Math.abs(dy)) {
            if (dx > 0 && dy > 0) return Direction.NE;
            if (dx > 0 && dy < 0) return Direction.SE;
            if (dx < 0 && dy < 0) return Direction.SW;
            if (dx < 0 && dy > 0) return Direction.NW;
        }
        return null;
    }

    /**
     * Calculates Chebyshev distance, which works for both orthogonal and diagonal moves.
     */
    private static int calculateChebyshevDistance(int x1, int y1, int x2, int y2) {
        return Math.max(Math.abs(x1 - x2), Math.abs(y1 - y2));
    }

    /**
     * Updates the map if the current piece is closer than the previously recorded piece in that direction.
     */
    private static void updateClosestPiece(Map<Direction, Piece> map, Direction dir, Piece newPiece) {
        if (!map.containsKey(dir) || newPiece.distance < map.get(dir).distance) {
            map.put(dir, newPiece);
        }
    }

    /**
     * Checks if any of the closest pieces found can attack the king.
     */
    private static boolean isKingInCheck(Map<Direction, Piece> closestPieces) {
        for (Map.Entry<Direction, Piece> entry : closestPieces.entrySet()) {
            Direction dir = entry.getKey();
            Piece piece = entry.getValue();
            if (dir.isAttackingDirection(piece.type)) {
                return true;
            }
        }
        return false;
    }
}

import java.util.Scanner;

/**
 * A utility to determine if a target position is under threat from 
 * chess pieces (Rook, Bishop, or Queen) based on their closest proximity.
 */
public class ChessThreatDetector {

    /**
     * Represents a chess piece with its type and coordinates.
     * 
     * @param type The piece type ('R' for Rook, 'B' for Bishop, 'Q' for Queen)
     * @param x    The x-coordinate
     * @param y    The y-coordinate
     */
    private record Piece(char type, long x, long y) {}

    /**
     * Represents the 8 possible directions of movement on a chessboard.
     */
    private enum Direction {
        UP(0, 1, true),
        DOWN(0, -1, true),
        RIGHT(1, 0, true),
        LEFT(-1, 0, true),
        UP_RIGHT(1, 1, false),
        DOWN_RIGHT(1, -1, false),
        DOWN_LEFT(-1, -1, false),
        UP_LEFT(-1, 1, false);

        private final int dx;
        private final int dy;
        private final boolean isOrthogonal;

        Direction(int dx, int dy, boolean isOrthogonal) {
            this.dx = dx;
            this.dy = dy;
            this.isOrthogonal = isOrthogonal;
        }

        /**
         * Determines the direction of a piece relative to the target coordinates.
         * 
         * @param deltaX The difference in x-coordinates
         * @param deltaY The difference in y-coordinates
         * @return The Direction enum, or null if the piece is not on a valid line
         */
        public static Direction getDirection(long deltaX, long deltaY) {
            if (deltaX == 0 && deltaY != 0) {
                return deltaY > 0 ? UP : DOWN;
            }
            if (deltaY == 0 && deltaX != 0) {
                return deltaX > 0 ? RIGHT : LEFT;
            }
            if (Math.abs(deltaX) == Math.abs(deltaY)) {
                if (deltaX > 0 && deltaY > 0) return UP_RIGHT;
                if (deltaX > 0 && deltaY < 0) return DOWN_RIGHT;
                if (deltaX < 0 && deltaY < 0) return DOWN_LEFT;
                if (deltaX < 0 && deltaY > 0) return UP_LEFT;
            }
            return null;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextLong()) return;
        long numPieces = scanner.nextLong();
        long targetX = scanner.nextLong();
        long targetY = scanner.nextLong();

        // Tracks the closest piece found so far for each direction
        Piece[] closestPieces = new Piece[Direction.values().length];

        for (long i = 0; i < numPieces; i++) {
            char type = scanner.next().charAt(0);
            long x = scanner.nextLong();
            long y = scanner.nextLong();
            Piece currentPiece = new Piece(type, x, y);

            processPiece(currentPiece, targetX, targetY, closestPieces);
        }

        System.out.println(isUnderThreat(closestPieces) ? "YES" : "NO");
        scanner.close();
    }

    /**
     * Updates the closest piece for a specific direction if the current piece is closer.
     */
    private static void processPiece(Piece piece, long tx, long ty, Piece[] closestPieces) {
        long dx = piece.x() - tx;
        long dy = piece.y() - ty;

        Direction dir = Direction.getDirection(dx, dy);
        if (dir != null) {
            int dirIdx = dir.ordinal();
            if (closestPieces[dirIdx] == null || getDistance(piece, tx, ty) < getDistance(closestPieces[dirIdx], tx, ty)) {
                closestPieces[dirIdx] = piece;
            }
        }
    }

    /**
     * Calculates distance. Since pieces are on the same line, Manhattan distance is sufficient.
     */
    private static long getDistance(Piece p, long tx, long ty) {
        return Math.abs(p.x() - tx) + Math.abs(p.y() - ty);
    }

    /**
     * Checks if the closest piece in any direction can attack the target.
     */
    private static boolean isUnderThreat(Piece[] closestPieces) {
        for (Direction dir : Direction.values()) {
            Piece closest = closestPieces[dir.ordinal()];
            if (closest != null) {
                char type = closest.type();
                if (dir.isOrthogonal) {
                    // Orthogonal directions are attacked by Rooks or Queens
                    if (type == 'R' || type == 'Q') return true;
                } else {
                    // Diagonal directions are attacked by Bishops or Queens
                    if (type == 'B' || type == 'Q') return true;
                }
            }
        }
        return false;
    }
}

import java.io.*;
import java.util.*;
import java.util.function.BiPredicate;

/**
 * Refactored solution for checking piece interference in 8 directions.
 */
public class Main {
    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        TaskDSolver solver = new TaskDSolver(reader, out);
        solver.solve();

        out.close();
    }

    /**
     * Represents a game piece on the board.
     */
    static class Piece {
        final char type;
        final int x;
        final int y;

        Piece(char type, int x, int y) {
            this.type = type;
            this.x = x;
            this.y = y;
        }
    }

    /**
     * Defines the 8 movement directions and their specific rules.
     */
    enum Direction {
        // Cardinal directions (Rook/Queen)
        EAST(true,  (dx, dy) -> dy == 0 && dx > 0),
        NORTH(true, (dx, dy) -> dx == 0 && dy > 0),
        WEST(true,  (dx, dy) -> dy == 0 && dx < 0),
        SOUTH(true, (dx, dy) -> dx == 0 && dy < 0),

        // Diagonal directions (Bishop/Queen)
        NE(false, (dx, dy) -> dx > 0 && dy > 0 && dx == dy),
        NW(false, (dx, dy) -> dx < 0 && dy > 0 && dx == -dy),
        SW(false, (dx, dy) -> dx < 0 && dy < 0 && dx == dy),
        SE(false, (dx, dy) -> dx > 0 && dy < 0 && dx == -dy);

        private final boolean isCardinal;
        private final BiPredicate<Integer, Integer> matches;

        Direction(boolean isCardinal, BiPredicate<Integer, Integer> matches) {
            this.isCardinal = isCardinal;
            this.matches = matches;
        }

        public boolean isMatch(int dx, int dy) {
            return matches.test(dx, dy);
        }

        public boolean isValidType(char type) {
            if (isCardinal) {
                return type == 'Q' || type == 'R';
            } else {
                return type == 'Q' || type == 'B';
            }
        }
    }

    /**
     * Contains the core logic of the problem.
     */
    static class TaskDSolver {
        private final FastReader reader;
        private final PrintWriter out;

        TaskDSolver(FastReader reader, PrintWriter out) {
            this.reader = reader;
            this.out = out;
        }

        public void solve() {
            int n = reader.nextInt();
            int targetX = reader.nextInt();
            int targetY = reader.nextInt();
            Piece target = new Piece(' ', targetX, targetY);

            List<Piece> pieces = new ArrayList<>(n);
            for (int i = 0; i < n; i++) {
                char type = reader.next().charAt(0);
                int x = reader.nextInt();
                int y = reader.nextInt();
                pieces.add(new Piece(type, x, y));
            }

            if (checkInterference(target, pieces)) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        }

        private boolean checkInterference(Piece target, List<Piece> pieces) {
            for (Direction dir : Direction.values()) {
                Piece closest = findClosestPieceInDirection(target, pieces, dir);
                if (closest != null && dir.isValidType(closest.type)) {
                    return true;
                }
            }
            return false;
        }

        private Piece findClosestPieceInDirection(Piece target, List<Piece> pieces, Direction dir) {
            Piece closest = null;
            int minDistance = Integer.MAX_VALUE;

            for (Piece p : pieces) {
                int dx = p.x - target.x;
                int dy = p.y - target.y;

                if (dir.isMatch(dx, dy)) {
                    // Manhattan distance is sufficient for comparison in these specific directions
                    int distance = Math.abs(dx) + Math.abs(dy);
                    if (distance < minDistance) {
                        minDistance = distance;
                        closest = p;
                    }
                }
            }
            return closest;
        }
    }

    /**
     * High-performance input reader.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * PointProcessor solves the problem of determining if a specific color 
 * can be reached at the closest boundaries of a coordinate system 
 * across two coordinate transformations.
 */
public class PointProcessor {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = reader.nextInt();
            Point origin = new Point(' ', reader.nextLong(), reader.nextLong());

            List<Point> points = new ArrayList<>(n);
            for (int i = 0; i < n; i++) {
                char color = reader.nextChar();
                long x = reader.nextLong();
                long y = reader.nextLong();
                points.add(new Point(color, x, y));
            }

            boolean isWinningConditionMet = solve(origin, points);
            out.println(isWinningConditionMet ? "YES" : "NO");

        } catch (Exception e) {
            // In a production environment, use a logger
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Executes the core logic: checks boundaries and transforms coordinates.
     */
    private static boolean solve(Point origin, List<Point> points) {
        for (int iteration = 0; iteration < 2; iteration++) {
            if (hasTargetColorAtBoundaries(origin, points, iteration)) {
                return true;
            }
            transformCoordinates(origin, points);
        }
        return false;
    }

    /**
     * Checks if the 'closest' points in the four cardinal directions 
     * meet the color requirements for the current iteration.
     */
    private static boolean hasTargetColorAtBoundaries(Point origin, List<Point> points, int iteration) {
        Point closestLeft = null;   // Max x < origin.x where y == origin.y
        Point closestRight = null;  // Min x > origin.x where y == origin.y
        Point closestDown = null;   // Max y < origin.y where x == origin.x
        Point closestUp = null;     // Min y > origin.y where x == origin.x

        for (Point p : points) {
            if (p.y == origin.y) {
                if (p.x < origin.x) {
                    if (closestLeft == null || p.x > closestLeft.x) closestLeft = p;
                } else if (p.x > origin.x) {
                    if (closestRight == null || p.x < closestRight.x) closestRight = p;
                }
            } else if (p.x == origin.x) {
                if (p.y < origin.y) {
                    if (closestDown == null || p.y > closestDown.y) closestDown = p;
                } else if (p.y > origin.y) {
                    if (closestUp == null || p.y < closestUp.y) closestUp = p;
                }
            }
        }

        List<Point> candidates = Arrays.asList(closestLeft, closestRight, closestDown, closestUp);

        for (Point p : candidates) {
            if (p == null) continue;

            if (p.color == 'Q') return true;
            if (iteration == 0 && p.color == 'R') return true;
            if (iteration == 1 && p.color == 'B') return true;
        }

        return false;
    }

    /**
     * Performs the coordinate transformation: (x, y) -> (x + y, x - y)
     */
    private static void transformCoordinates(Point origin, List<Point> points) {
        // Transform origin
        long newOriginX = origin.x + origin.y;
        long newOriginY = origin.x - origin.y;
        origin.x = newOriginX;
        origin.y = newOriginY;

        // Transform all points
        for (Point p : points) {
            long newX = p.x + p.y;
            long newY = p.x - p.y;
            p.x = newX;
            p.y = newY;
        }
    }

    /**
     * Represents a point in a 2D coordinate system with an associated color.
     */
    static class Point {
        char color;
        long x;
        long y;

        Point(char color, long x, long y) {
            this.color = color;
            this.x = x;
            this.y = y;
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int pointer = 0;
        private int bytesRead = 0;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() {
            if (pointer >= bytesRead) {
                pointer = 0;
                try {
                    bytesRead = stream.read(buffer);
                } catch (IOException e) {
                    return -1;
                }
                if (bytesRead <= 0) return -1;
            }
            return buffer[pointer++];
        }

        public String nextToken() {
            int c = readByte();
            while (c != -1 && isSpaceChar(c)) c = readByte();
            if (c == -1) return null;
            StringBuilder res = new StringBuilder();
            do {
                res.append((char) c);
                c = readByte();
            } while (c != -1 && !isSpaceChar(c));
            return res.toString();
        }

        public int nextInt() {
            return (int) nextLong();
        }

        public long nextLong() {
            int c = readByte();
            while (c != -1 && isSpaceChar(c)) c = readByte();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res = res * 10 + (c - '0');
                c = readByte();
            } while (c != -1 && !isSpaceChar(c));
            return res * sign;
        }

        public char nextChar() {
            String token = nextToken();
            return (token != null && token.length() > 0) ? token.charAt(0) : ' ';
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * Refactored solution for the Anton Chess problem.
 * Determines if a King is under attack by the closest piece in any of the 8 directions.
 */
public class AntonChess {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = reader.nextInt();
            int kingX = reader.nextInt();
            int kingY = reader.nextInt();

            List<Piece> pieces = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                char type = reader.next().charAt(0);
                int x = reader.nextInt();
                int y = reader.nextInt();
                pieces.add(new Piece(type, x, y));
            }

            if (isKingUnderAttack(pieces, kingX, kingY)) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            out.close();
        }
    }

    /**
     * Core logic to determine if the king is under attack.
     */
    private static boolean isKingUnderAttack(List<Piece> pieces, int kX, int kY) {
        // Maps a direction (represented as a string "dx,dy") to the closest piece found so far
        Map<String, Piece> closestPieces = new HashMap<>();
        Map<String, Integer> minDistances = new HashMap<>();

        for (Piece p : pieces) {
            int dx = p.x - kX;
            int dy = p.y - kY;

            // Check if the piece is in a valid direction: Cardinal or 45-degree Diagonal
            if (isCardinal(dx, dy) || isDiagonal(dx, dy)) {
                int distance = Math.max(Math.abs(dx), Math.abs(dy));

                // Normalize direction to a unit vector (-1, 0, or 1)
                int unitX = Integer.compare(dx, 0);
                int unitY = Integer.compare(dy, 0);
                String directionKey = unitX + "," + unitY;

                // If this is the first piece in this direction or closer than the previous one
                if (!minDistances.containsKey(directionKey) || distance < minDistances.get(directionKey)) {
                    minDistances.put(directionKey, distance);
                    closestPieces.put(directionKey, p);
                }
            }
        }

        // Check if any of the closest pieces in their respective directions are attackers
        for (Map.Entry<String, Piece> entry : closestPieces.entrySet()) {
            String[] dirParts = entry.getKey().split(",");
            int ux = Integer.parseInt(dirParts[0]);
            int uy = Integer.parseInt(dirParts[1]);

            if (isThreatening(entry.getValue(), ux, uy)) {
                return true;
            }
        }

        return false;
    }

    private static boolean isCardinal(int dx, int dy) {
        return dx == 0 || dy == 0;
    }

    private static boolean isDiagonal(int dx, int dy) {
        return Math.abs(dx) == Math.abs(dy);
    }

    /**
     * Determines if a specific piece can attack the king based on its position/direction.
     */
    private static boolean isThreatening(Piece p, int ux, int uy) {
        boolean isCardinal = (ux == 0 || uy == 0);
        if (isCardinal) {
            // Rooks and Queens attack on cardinal lines
            return p.type == 'R' || p.type == 'Q';
        } else {
            // Bishops and Queens attack on diagonals
            return p.type == 'B' || p.type == 'Q';
        }
    }

    /**
     * Represents a Chess Piece.
     */
    static class Piece {
        final char type;
        final int x;
        final int y;

        Piece(char type, int x, int y) {
            this.type = type;
            this.x = x;
            this.y = y;
        }
    }

    /**
     * Efficient input reader.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for determining valid directional moves.
 * 
 * The program reads a series of moves from an initial starting point. Each move
 * consists of a type ('Q', 'R', or 'B') and target coordinates. It determines
 * if the first object encountered in any of the 8 primary directions (horizontal, 
 * vertical, or diagonal) allows for a specific movement type.
 * 
 * Rules:
 * - 'Q' is always a valid move.
 * - For odd-indexed directions (1, 3, 5, 7), 'R' is a valid move.
 * - For even-indexed directions (0, 2, 4, 6), 'B' is a valid move.
 */
public class DirectionalMoveSolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            solve(reader, writer);
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    /**
     * Core logic to process moves and determine the result.
     */
    private static void solve(FastReader reader, PrintWriter writer) {
        int n = reader.nextInt();
        if (n <= 0) {
            writer.println("NO");
            return;
        }

        long startX = reader.nextLong();
        long startY = reader.nextLong();

        // Stores the minimum squared distance found so far in each of the 8 directions.
        long[] minDistanceSq = new long[8];
        Arrays.fill(minDistanceSq, Long.MAX_VALUE);

        // Stores the movement type of the closest object found in each direction.
        char[] closestType = new char[8];

        for (int i = 0; i < n; i++) {
            char type = reader.next().charAt(0);
            long targetX = reader.nextLong();
            long targetY = reader.nextLong();

            long dx = targetX - startX;
            long dy = targetY - startY;

            int direction = getDirectionIndex(dx, dy);

            // If the move is in one of the 8 allowed directions (H, V, or D)
            if (direction != -1) {
                long distSq = dx * dx + dy * dy;
                // We only care about the closest object encountered in each direction.
                if (distSq < minDistanceSq[direction]) {
                    minDistanceSq[direction] = distSq;
                    closestType[direction] = type;
                }
            }
        }

        if (isAnyMoveValid(closestType)) {
            writer.println("YES");
        } else {
            writer.println("NO");
        }
    }

    /**
     * Maps relative coordinates (dx, dy) to a direction index (0-7).
     * 
     * Mapping:
     * 0: Up-Left (-1, 1), 1: Up (0, 1), 2: Up-Right (1, 1), 3: Right (1, 0),
     * 4: Down-Right (1, -1), 5: Down (0, -1), 6: Down-Left (-1, -1), 7: Left (-1, 0)
     * 
     * @return Direction index or -1 if not a valid primary/diagonal direction.
     */
    private static int getDirectionIndex(long dx, long dy) {
        if (dx == 0 && dy != 0) {
            return (dy > 0) ? 1 : 5;
        } else if (dy == 0 && dx != 0) {
            return (dx > 0) ? 3 : 7;
        } else if (Math.abs(dx) == Math.abs(dy) && dx != 0) {
            if (dy > 0) {
                return (dx > 0) ? 2 : 0;
            } else {
                return (dx > 0) ? 4 : 6;
            }
        }
        return -1;
    }

    /**
     * Evaluates whether any of the closest objects found satisfy the movement criteria.
     * 
     * @param closestType Array containing types of closest objects per direction.
     * @return True if a valid move is possible.
     */
    private static boolean isAnyMoveValid(char[] closestType) {
        for (int i = 0; i < 8; i++) {
            char type = closestType[i];
            if (type == '\0') continue; // No object detected in this direction

            // 'Q' is always valid regardless of direction
            if (type == 'Q') return true;

            // For odd direction indices, 'R' is valid. For even, 'B' is valid.
            boolean isOddDirection = (i % 2 != 0);
            if (isOddDirection && type == 'R') return true;
            if (!isOddDirection && type == 'B') return true;
        }
        return false;
    }

    /**
     * High-performance input reader utility.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }
    }
}

import java.util.*;

/**
 * Refactored solution for the Anton and Chess problem.
 * Determines if a target square on a chessboard is reachable by any piece
 * given that Rooks block orthogonal paths and Bishops block diagonal paths.
 */
public class AntonAndChess {

    /**
     * Represents the 8 possible directions on a chessboard.
     */
    enum Direction {
        NORTH(0, 1, true),
        SOUTH(0, -1, true),
        EAST(1, 0, true),
        WEST(-1, 0, true),
        NE(1, 1, false),
        SE(1, -1, false),
        NW(-1, 1, false),
        SW(-1, -1, false);

        private final int dx;
        private final int dy;
        private final boolean isOrthogonal;

        Direction(int dx, int dy, boolean isOrthogonal) {
            this.dx = dx;
            this.dy = dy;
            this.isOrthogonal = isOrthogonal;
        }

        /**
         * Identifies the direction given the relative coordinate differences.
         * 
         * @param dx Difference in X (pieceX - targetX)
         * @param dy Difference in Y (pieceY - targetY)
         * @return The corresponding Direction, or null if not in one of the 8 directions.
         */
        static Direction getDirection(long dx, long dy) {
            if (dx == 0 && dy > 0) return NORTH;
            if (dx == 0 && dy < 0) return SOUTH;
            if (dy == 0 && dx > 0) return EAST;
            if (dy == 0 && dx < 0) return WEST;
            if (dx > 0 && dy > 0) return NE;
            if (dx > 0 && dy < 0) return SE;
            if (dx < 0 && dy > 0) return NW;
            if (dx < 0 && dy < 0) return SW;
            return null;
        }
    }

    /**
     * Represents a piece found on the board.
     */
    static class Piece {
        final char type;
        final long distance;

        Piece(char type, long distance) {
            this.type = type;
            this.distance = distance;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int numberOfPieces = scanner.nextInt();
        long targetX = scanner.nextLong();
        long targetY = scanner.nextLong();

        // Stores the closest piece found in each of the 8 directions.
        Map<Direction, Piece> closestPiecesPerDirection = new EnumMap<>(Direction.class);

        for (int i = 0; i < numberOfPieces; i++) {
            char type = scanner.next().charAt(0);
            long pieceX = scanner.nextLong();
            long pieceY = scanner.nextLong();

            long dx = pieceX - targetX;
            long dy = pieceY - targetY;

            Direction dir = Direction.getDirection(dx, dy);
            if (dir != null) {
                // Manhattan distance is sufficient here because we only care about 
                // orthogonal or 45-degree diagonal alignment.
                long distance = Math.max(Math.abs(dx), Math.abs(dy));

                if (!closestPiecesPerDirection.containsKey(dir) || 
                     distance < closestPiecesPerDirection.get(dir).distance) {
                    closestPiecesPerDirection.put(dir, new Piece(type, distance));
                }
            }
        }

        boolean canReachTarget = checkReachability(closestPiecesPerDirection);
        System.out.println(canReachTarget ? "YES" : "NO");

        scanner.close();
    }

    /**
     * Checks if any of the closest pieces in their respective directions 
     * are capable of attacking the target square.
     *
     * @param closestPieces Map of direction to the closest piece in that direction.
     * @return true if at least one piece can reach the target, false otherwise.
     */
    private static boolean checkReachability(Map<Direction, Piece> closestPieces) {
        for (Map.Entry<Direction, Piece> entry : closestPieces.entrySet()) {
            Direction dir = entry.getKey();
            Piece piece = entry.getValue();

            if (dir.isOrthogonal) {
                // In orthogonal directions, a Rook ('R') can reach the target.
                if (piece.type == 'R') {
                    return true;
                }
            } else {
                // In diagonal directions, a Bishop ('B') can reach the target.
                if (piece.type == 'B') {
                    return true;
                }
            }
        }
        return false;
    }
}

import java.util.*;
import java.io.*;

/**
 * A solver for determining if a path is available based on the colors 
 * of obstacles located in specific cardinal and ordinal directions.
 */
public class ColorPathSolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));

        try {
            int n = reader.nextInt();
            long startX = reader.nextLong();
            long startY = reader.nextLong();

            EnumMap<Direction, List<Obstacle>> directionMap = new EnumMap<>(Direction.class);
            for (Direction dir : Direction.values()) {
                directionMap.put(dir, new ArrayList<>());
            }

            for (int i = 0; i < n; i++) {
                char color = reader.next().charAt(0);
                long obsX = reader.nextLong();
                long obsY = reader.nextLong();

                Direction dir = Direction.fromCoordinates(startX, startY, obsX, obsY);
                if (dir != null) {
                    long distance = Obstacle.calculateDistance(startX, startY, obsX, obsY);
                    directionMap.get(dir).add(new Obstacle(color, obsX, obsY, distance));
                }
            }

            boolean canMove = false;
            for (Direction dir : Direction.values()) {
                List<Obstacle> obstacles = directionMap.get(dir);
                if (!obstacles.isEmpty()) {
                    Collections.sort(obstacles);
                    Obstacle nearest = obstacles.get(0);
                    if (nearest.color == 'Q' || nearest.color == dir.requiredColor) {
                        canMove = true;
                        break;
                    }
                }
            }

            out.println(canMove ? "YES" : "NO");

        } catch (Exception e) {
            // In a production environment, use a proper logger
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Represents the 8 possible valid directions from a starting point.
     */
    enum Direction {
        // Cardinal directions require Red ('R')
        NORTH(0, 1, 'R'),
        SOUTH(0, -1, 'R'),
        EAST(1, 0, 'R'),
        WEST(-1, 0, 'R'),

        // Ordinal directions require Blue ('B')
        NORTH_EAST(1, 1, 'B'),
        SOUTH_EAST(1, -1, 'B'),
        SOUTH_WEST(-1, -1, 'B'),
        NORTH_WEST(-1, 1, 'B');

        final int dx;
        final int dy;
        final char requiredColor;

        Direction(int dx, int dy, char requiredColor) {
            this.dx = dx;
            this.dy = dy;
            this.requiredColor = requiredColor;
        }

        /**
         * Determines the direction from start to target.
         * Returns null if the target is not on a cardinal or 45-degree diagonal.
         */
        public static Direction fromCoordinates(long sx, long sy, long tx, long ty) {
            long dx = tx - sx;
            long dy = ty - sy;

            if (dx == 0) {
                return dy > 0 ? NORTH : SOUTH;
            } else if (dy == 0) {
                return dx > 0 ? EAST : WEST;
            } else if (Math.abs(dx) == Math.abs(dy)) {
                if (dx > 0 && dy > 0) return NORTH_EAST;
                if (dx > 0 && dy < 0) return SOUTH_EAST;
                if (dx < 0 && dy < 0) return SOUTH_WEST;
                if (dx < 0 && dy > 0) return NORTH_WEST;
            }
            return null;
        }
    }

    /**
     * Represents an obstacle in the grid.
     */
    static class Obstacle implements Comparable<Obstacle> {
        final char color;
        final long x;
        final long y;
        final long distance;

        Obstacle(char color, long x, long y, long distance) {
            this.color = color;
            this.x = x;
            this.y = y;
            this.distance = distance;
        }

        public static long calculateDistance(long x1, long y1, long x2, long y2) {
            return Math.max(Math.abs(x1 - x2), Math.abs(y1 - y2));
        }

        @Override
        public int compareTo(Obstacle other) {
            return Long.compare(this.distance, other.distance);
        }
    }

    /**
     * Fast I/O utility.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }
    }
}

import java.util.EnumMap;
import java.util.Map;
import java.util.Scanner;

/**
 * A program to determine if a King is in check on a chessboard
 * based on the positions and types of surrounding pieces.
 */
public class Chess {

    /**
     * Represents the 8 possible directions of movement from the King.
     */
    enum Direction {
        LEFT, RIGHT, UP, DOWN, UP_LEFT, UP_RIGHT, DOWN_LEFT, DOWN_RIGHT, NONE;

        /**
         * Determines the direction of a piece relative to the king based on coordinate deltas.
         *
         * @param dx Delta X (pieceX - kingX)
         * @param dy Delta Y (pieceY - kingY)
         * @return The corresponding Direction enum
         */
        public static Direction fromDelta(long dx, long dy) {
            if (dy == 0) {
                return dx < 0 ? LEFT : RIGHT;
            }
            if (dx == 0) {
                return dy > 0 ? UP : DOWN;
            }
            if (Math.abs(dx) == Math.abs(dy)) {
                if (dx < 0 && dy > 0) return UP_LEFT;
                if (dx > 0 && dy > 0) return UP_RIGHT;
                if (dx < 0 && dy < 0) return DOWN_LEFT;
                if (dx > 0 && dy < 0) return DOWN_RIGHT;
            }
            return NONE;
        }

        public boolean isOrthogonal() {
            return this == LEFT || this == RIGHT || this == UP || this == DOWN;
        }

        public boolean isDiagonal() {
            return this == UP_LEFT || this == UP_RIGHT || this == DOWN_LEFT || this == DOWN_RIGHT;
        }
    }

    /**
     * Represents a chess piece with its type and coordinates.
     */
    static class Piece {
        final char type;
        final long x;
        final long y;

        Piece(char type, long x, long y) {
            this.type = type;
            this.x = x;
            this.y = y;
        }

        /**
         * Calculates squared Euclidean distance to avoid costly Math.sqrt calls.
         */
        long distanceSq(long kx, long ky) {
            return (x - kx) * (x - kx) + (y - ky) * (y - ky);
        }
    }

    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);

        if (!scan.hasNextInt()) {
            scan.close();
            return;
        }

        int pieceCount = scan.nextInt();
        long kingX = scan.nextLong();
        long kingY = scan.nextLong();

        // Stores the closest piece found so far for each direction
        Map<Direction, Piece> closestPiecesByDirection = new EnumMap<>(Direction.class);

        for (int i = 0; i < pieceCount; i++) {
            char type = scan.next().charAt(0);
            long px = scan.nextLong();
            long py = scan.nextLong();

            long dx = px - kingX;
            long dy = py - kingY;

            Direction dir = Direction.fromDelta(dx, dy);

            if (dir != Direction.NONE) {
                Piece currentPiece = new Piece(type, px, py);

                if (!closestPiecesByDirection.containsKey(dir) || 
                    currentPiece.distanceSq(kingX, kingY) < closestPiecesByDirection.get(dir).distanceSq(kingX, kingY)) {
                    closestPiecesByDirection.put(dir, currentPiece);
                }
            }
        }

        boolean isKingInCheck = checkIfKingIsUnderThreat(closestPiecesByDirection);
        System.out.println(isKingInCheck ? "YES" : "NO");

        scan.close();
    }

    /**
     * Iterates through the closest pieces in every direction to see if any can attack the king.
     *
     * @param closestPieces A map of directions to the closest piece in that direction.
     * @return true if the king is in check, false otherwise.
     */
    private static boolean checkIfKingIsUnderThreat(Map<Direction, Piece> closestPieces) {
        for (Map.Entry<Direction, Piece> entry : closestPieces.entrySet()) {
            Direction dir = entry.getKey();
            Piece piece = entry.getValue();

            if (dir.isOrthogonal()) {
                // Rooks and Queens attack orthogonally
                if (piece.type == 'R' || piece.type == 'Q') {
                    return true;
                }
            } else if (dir.isDiagonal()) {
                // Bishops and Queens attack diagonally
                if (piece.type == 'B' || piece.type == 'Q') {
                    return true;
                }
            }
        }
        return false;
    }
}

import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

/**
 * A utility to detect if a target position on a grid is threatened by 
 * chess pieces (Rook, Bishop, or Queen) based on line-of-sight rules.
 */
public class ChessThreatDetector {

    /**
     * Represents the 8 possible directions of movement on a grid.
     */
    private enum Direction {
        NORTH, SOUTH, EAST, WEST,
        NORTH_EAST, NORTH_WEST, SOUTH_EAST, SOUTH_WEST
    }

    /**
     * Represents a piece found in a specific direction.
     */
    private static class Piece {
        final char type;
        final int distance;

        Piece(char type, int distance) {
            this.type = type;
            this.distance = distance;
        }
    }

    private final int targetRow;
    private final int targetCol;
    private final Map<Direction, Piece> closestPiecesInDirection = new HashMap<>();

    public ChessThreatDetector(int targetRow, int targetCol) {
        this.targetRow = targetRow;
        this.targetCol = targetCol;
    }

    /**
     * Processes a piece and updates the closest piece in its direction if applicable.
     * 
     * @param type The character representing the piece type (e.g., 'R', 'B', 'Q').
     * @param row  The row coordinate of the piece.
     * @param col  The column coordinate of the piece.
     */
    public void processPiece(char type, int row, int col) {
        int dr = row - targetRow;
        int dc = col - targetCol;

        Direction dir = getDirection(dr, dc);
        if (dir == null) {
            return; // Piece is not in a straight or diagonal line of sight
        }

        // Distance is calculated based on the maximum movement required in any one axis
        int distance = Math.max(Math.abs(dr), Math.abs(dc));
        Piece currentClosest = closestPiecesInDirection.get(dir);

        if (currentClosest == null || distance < currentClosest.distance) {
            closestPiecesInDirection.put(dir, new Piece(type, distance));
        }
    }

    /**
     * Determines the direction of a piece relative to the target.
     */
    private Direction getDirection(int dr, int dc) {
        if (dr == 0 && dc == 0) return null;

        // Orthogonal directions (Rook/Queen movement)
        if (dc == 0) {
            return dr > 0 ? Direction.NORTH : Direction.SOUTH;
        } else if (dr == 0) {
            return dc > 0 ? Direction.EAST : Direction.WEST;
        } 

        // Diagonal directions (Bishop/Queen movement)
        if (Math.abs(dr) == Math.abs(dc)) {
            if (dr > 0) {
                return dc > 0 ? Direction.NORTH_EAST : Direction.NORTH_WEST;
            } else {
                return dc > 0 ? Direction.SOUTH_EAST : Direction.SOUTH_WEST;
            }
        }

        return null;
    }

    /**
     * Checks if the target position is currently threatened by any closest piece.
     * 
     * @return true if a valid attacking piece is the closest in its direction.
     */
    public boolean isTargetThreatened() {
        for (Map.Entry<Direction, Piece> entry : closestPiecesInDirection.entrySet()) {
            Direction dir = entry.getKey();
            Piece piece = entry.getValue();

            if (isOrthogonal(dir)) {
                // Orthogonal threats: Rook ('R') or Queen ('Q')
                if (piece.type == 'R' || piece.type == 'Q') return true;
            } else {
                // Diagonal threats: Bishop ('B') or Queen ('Q')
                if (piece.type == 'B' || piece.type == 'Q') return true;
            }
        }
        return false;
    }

    private boolean isOrthogonal(Direction dir) {
        return dir == Direction.NORTH || dir == Direction.SOUTH ||
               dir == Direction.EAST || dir == Direction.WEST;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int n = scanner.nextInt();
        int targetRow = scanner.nextInt();
        int targetCol = scanner.nextInt();

        ChessThreatDetector detector = new ChessThreatDetector(targetRow, targetCol);

        for (int i = 0; i < n; i++) {
            String typeStr = scanner.next();
            char type = typeStr.charAt(0);
            int r = scanner.nextInt();
            int c = scanner.nextInt();
            detector.processPiece(type, r, c);
        }

        System.out.println(detector.isTargetThreatened() ? "YES" : "NO");

        scanner.close();
    }
}

import java.util.*;
import java.io.*;

/**
 * A refactored solution to determine if a player is obstructed by specific colors
 * in orthogonal or diagonal directions.
 */
public class Main {

    /**
     * Represents the colors of the obstacles.
     */
    enum Color {
        RED, BLUE, GREEN;

        public static Color fromChar(char c) {
            return switch (c) {
                case 'R' -> RED;
                case 'B' -> BLUE;
                case 'G' -> GREEN;
                default -> throw new IllegalArgumentException("Invalid color: " + c);
            };
        }
    }

    /**
     * Represents the 8 possible directions from a central point.
     */
    enum Direction {
        UP, DOWN, LEFT, RIGHT,
        UP_RIGHT, DOWN_LEFT, UP_LEFT, DOWN_RIGHT
    }

    /**
     * Represents an obstacle with coordinates and a color.
     */
    static class Obstacle {
        final long x, y;
        final Color color;

        Obstacle(long x, long y, Color color) {
            this.x = x;
            this.y = y;
            this.color = color;
        }

        /**
         * Calculates Manhattan distance to a reference point.
         */
        long distanceTo(long refX, long refY) {
            return Math.abs(x - refX) + Math.abs(y - refY);
        }
    }

    public static void main(String[] args) throws IOException {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = reader.nextInt();
        long x0 = reader.nextLong();
        long y0 = reader.nextLong();

        // Map to track the closest obstacle found so far for each direction
        Map<Direction, Obstacle> closestObstacles = new EnumMap<>(Direction.class);

        for (int i = 0; i < n; i++) {
            String colorStr = reader.next();
            long x = reader.nextLong();
            long y = reader.nextLong();
            Color color = Color.fromChar(colorStr.charAt(0));

            Direction dir = getDirection(x0, y0, x, y);
            if (dir != null) {
                Obstacle current = new Obstacle(x, y, color);
                if (!closestObstacles.containsKey(dir) || 
                    current.distanceTo(x0, y0) < closestObstacles.get(dir).distanceTo(x0, y0)) {
                    closestObstacles.put(dir, current);
                }
            }
        }

        boolean isObstructed = checkObstruction(closestObstacles);
        out.println(isObstructed ? "YES" : "NO");
        out.flush();
        out.close();
    }

    /**
     * Identifies the direction of a point (x, y) relative to (x0, y0).
     * Only returns directions that are strictly orthogonal or 45-degree diagonal.
     */
    private static Direction getDirection(long x0, long y0, long x, long y) {
        long dx = x - x0;
        long dy = y - y0;

        if (dx == 0 && dy == 0) return null;

        // Orthogonal directions
        if (dx == 0) {
            return dy > 0 ? Direction.UP : Direction.DOWN;
        }
        if (dy == 0) {
            return dx > 0 ? Direction.RIGHT : Direction.LEFT;
        }

        // Diagonal directions
        if (dx == dy) {
            return dx > 0 ? Direction.UP_RIGHT : Direction.DOWN_LEFT;
        }
        if (dx == -dy) {
            return dx > 0 ? Direction.DOWN_RIGHT : Direction.UP_LEFT;
        }

        return null;
    }

    /**
     * Validates if any of the closest obstacles meet the condition:
     * - Orthogonal obstacles must be Red or Green.
     * - Diagonal obstacles must be Blue or Green.
     */
    private static boolean checkObstruction(Map<Direction, Obstacle> closestObstacles) {
        for (Map.Entry<Direction, Obstacle> entry : closestObstacles.entrySet()) {
            Direction dir = entry.getKey();
            Color color = entry.getValue().color;

            boolean isOrthogonal = (dir == Direction.UP || dir == Direction.DOWN || 
                                    dir == Direction.LEFT || dir == Direction.RIGHT);

            if (isOrthogonal) {
                if (color == Color.RED || color == Color.GREEN) return true;
            } else {
                if (color == Color.BLUE || color == Color.GREEN) return true;
            }
        }
        return false;
    }

    /**
     * Helper class for fast I/O operations.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }
    }
}

import java.util.*;

/**
 * Refactored Chess piece interaction checker.
 * Determines if any of the nearest pieces in the 8 cardinal/ordinal directions
 * can attack the primary (first) piece.
 */
public class DAntonAndChess2 {

    /**
     * Represents the types of chess pieces available.
     */
    enum PieceType {
        QUEEN('Q'), 
        ROOK('R'), 
        BISHOP('B'), 
        UNKNOWN(' ');

        private final char symbol;

        PieceType(char symbol) {
            this.symbol = symbol;
        }

        public static PieceType fromChar(char c) {
            for (PieceType type : values()) {
                if (type.symbol == c) return type;
            }
            return UNKNOWN;
        }
    }

    /**
     * Represents the 8 directions on a chess board.
     */
    enum Direction {
        NORTH(0, 1), SOUTH(0, -1), EAST(1, 0), WEST(-1, 0),
        NORTH_EAST(1, 1), NORTH_WEST(-1, 1), SOUTH_EAST(1, -1), SOUTH_WEST(-1, -1);

        final int dx, dy;

        Direction(int dx, int dy) {
            this.dx = dx;
            this.dy = dy;
        }

        /**
         * Maps a coordinate delta to a Direction enum.
         */
        public static Direction getDirection(int dx, int dy) {
            int sigX = Integer.compare(dx, 0);
            int sigY = Integer.compare(dy, 0);
            for (Direction dir : values()) {
                if (dir.dx == sigX && dir.dy == sigY) return dir;
            }
            return null;
        }
    }

    /**
     * Encapsulates piece data and its attack movement logic.
     */
    static class Piece {
        private final PieceType type;
        private final int x;
        private final int y;

        public Piece(PieceType type, int x, int y) {
            this.type = type;
            this.x = x;
            this.y = y;
        }

        public PieceType getType() { return type; }
        public int getX() { return x; }
        public int getY() { return y; }

        /**
         * Checks if this piece can attack the target piece based on chess rules.
         */
        public boolean canAttack(Piece target) {
            int dx = Math.abs(this.x - target.x);
            int dy = Math.abs(this.y - target.y);

            switch (this.type) {
                case QUEEN:
                    return dx == dy || dx == 0 || dy == 0;
                case ROOK:
                    return dx == 0 || dy == 0;
                case BISHOP:
                    return dx == dy;
                default:
                    return false;
            }
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextLine()) return;
        int n = Integer.parseInt(scanner.nextLine().trim());

        List<Piece> pieces = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (scanner.hasNextLine()) {
                pieces.add(parsePiece(scanner.nextLine()));
            }
        }

        if (pieces.isEmpty()) {
            System.out.println("NO");
            return;
        }

        // The first piece is the primary target
        Piece target = pieces.get(0);

        // Maps to store the closest piece found in each of the 8 directions
        Map<Direction, Piece> closestPieces = new EnumMap<>(Direction.class);
        Map<Direction, Integer> minDistances = new EnumMap<>(Direction.class);

        for (int i = 1; i < pieces.size(); i++) {
            Piece current = pieces.get(i);
            int dx = current.getX() - target.getX();
            int dy = current.getY() - target.getY();

            // Check if the piece is in a valid direction (Horizontal, Vertical, or Diagonal)
            if (dx == 0 || dy == 0 || Math.abs(dx) == Math.abs(dy)) {
                Direction dir = Direction.getDirection(dx, dy);
                if (dir != null) {
                    // Distance can be measured by the max delta since we are in 8 cardinal directions
                    int distance = Math.max(Math.abs(dx), Math.abs(dy));

                    if (!minDistances.containsKey(dir) || distance < minDistances.get(dir)) {
                        minDistances.put(dir, distance);
                        closestPieces.put(dir, current);
                    }
                }
            }
        }

        // Check if any of the identified boundary pieces can attack the target
        boolean isAttacked = false;
        for (Piece attacker : closestPieces.values()) {
            if (attacker.canAttack(target)) {
                isAttacked = true;
                break;
            }
        }

        System.out.println(isAttacked ? "YES" : "NO");
        scanner.close();
    }

    /**
     * Parses a line of input into a Piece object.
     * Handles formats like "Q 1 2" or "1 2".
     */
    private static Piece parsePiece(String line) {
        String[] parts = line.trim().split("\\s+");
        PieceType type;
        int x, y;

        if (parts.length >= 3 && isTypeChar(parts[0].charAt(0))) {
            type = PieceType.fromChar(parts[0].charAt(0));
            x = Integer.parseInt(parts[1]);
            y = Integer.parseInt(parts[2]);
        } else if (parts.length >= 2) {
            type = PieceType.UNKNOWN;
            x = Integer.parseInt(parts[0]);
            y = Integer.parseInt(parts[1]);
        } else {
            throw new IllegalArgumentException("Invalid input format: " + line);
        }
        return new Piece(type, x, y);
    }

    private static boolean isTypeChar(char c) {
        return c == 'Q' || c == 'R' || c == 'B';
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * This program determines if any threat (Red or Blue pieces, or Queens) 
 * is visible from a starting position along cardinal or diagonal lines of sight.
 */
public class Main {

    // Constants for obstacle types
    private static final char RED = 'R';
    private static final char BLUE = 'B';
    private static final char QUEEN = 'Q';

    // Direction vectors for the 8 possible directions (Cardinal and Diagonal)
    // Indices 0, 2, 4, 6 are Cardinal; 1, 3, 5, 7 are Diagonal
    private static final int[][] DIRECTIONS = {
        {0, 1},   // North
        {1, 1},   // North-East
        {1, 0},   // East
        {1, -1},  // South-East
        {0, -1},  // South
        {-1, -1}, // South-West
        {-1, 0},  // West
        {-1, 1}   // North-West
    };

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);

        int n = sc.nextInt();
        int startX = sc.nextInt();
        int startY = sc.nextInt();

        // Array to store the closest obstacle found in each of the 8 directions
        Obstacle[] closestObstacles = new Obstacle[8];

        for (int i = 0; i < n; i++) {
            char type = sc.next().charAt(0);
            int targetX = sc.nextInt();
            int targetY = sc.nextInt();

            int deltaX = targetX - startX;
            int deltaY = targetY - startY;

            int directionIndex = findDirectionIndex(deltaX, deltaY);

            // If the obstacle is in one of the 8 valid directions
            if (directionIndex != -1) {
                int distance = calculateChebyshevDistance(deltaX, deltaY);

                // Update if this is the first obstacle in this direction or if it's closer
                if (closestObstacles[directionIndex] == null || 
                    distance < closestObstacles[directionIndex].distance) {
                    closestObstacles[directionIndex] = new Obstacle(type, distance);
                }
            }
        }

        System.out.println(isThreatVisible(closestObstacles) ? "YES" : "NO");
    }

    /**
     * Identifies which of the 8 directions a relative coordinate belongs to.
     * Returns -1 if the coordinate is not on a cardinal or diagonal line.
     */
    private static int findDirectionIndex(int dx, int dy) {
        if (dx == 0 && dy == 0) return -1;

        boolean isCardinal = (dx == 0 || dy == 0);
        boolean isDiagonal = (Math.abs(dx) == Math.abs(dy));

        if (!isCardinal && !isDiagonal) {
            return -1;
        }

        // Normalize the direction to a unit vector (-1, 0, or 1)
        int unitX = Integer.compare(dx, 0);
        int unitY = Integer.compare(dy, 0);

        for (int i = 0; i < DIRECTIONS.length; i++) {
            if (DIRECTIONS[i][0] == unitX && DIRECTIONS[i][1] == unitY) {
                return i;
            }
        }
        return -1;
    }

    /**
     * Calculates the distance. Since we only care about cardinal/diagonal paths,
     * Chebyshev distance works perfectly.
     */
    private static int calculateChebyshevDistance(int dx, int dy) {
        return Math.max(Math.abs(dx), Math.abs(dy));
    }

    /**
     * Checks if any of the closest obstacles meet the threat criteria.
     */
    private static boolean isThreatVisible(Obstacle[] obstacles) {
        for (int i = 0; i < 8; i++) {
            if (obstacles[i] == null) continue;

            char type = obstacles[i].type;
            boolean isDiagonal = (i % 2 != 0);

            if (isDiagonal) {
                // Diagonal directions: Blue or Queen
                if (type == BLUE || type == QUEEN) return true;
            } else {
                // Cardinal directions: Red or Queen
                if (type == RED || type == QUEEN) return true;
            }
        }
        return false;
    }

    /**
     * Represents an obstacle at a specific distance.
     */
    private static class Obstacle {
        final char type;
        final int distance;

        Obstacle(char type, int distance) {
            this.type = type;
            this.distance = distance;
        }
    }

    /**
     * High-performance scanner for efficient input reading.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * RaySolver determines if specific character conditions are met along 8 radial directions 
 * from a central point (x0, y0).
 */
public class RaySolver {

    public static void main(String[] args) {
        try {
            solve();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * Represents a point discovered on one of the radial lines.
     */
    static class Point {
        final char type;
        final long distance;

        Point(char type, long distance) {
            this.type = type;
            this.distance = distance;
        }
    }

    /**
     * Core logic to solve the problem.
     */
    public static void solve() throws IOException {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = reader.nextInt();
        if (n <= 0) {
            out.println("NO");
            out.close();
            return;
        }

        long centerX = reader.nextLong();
        long centerY = reader.nextLong();

        // Rays 1-8 represent the 8 directions. 
        // We use a PriorityQueue to automatically keep the closest point at the head.
        @SuppressWarnings("unchecked")
        PriorityQueue<Point>[] rays = new PriorityQueue[9];
        for (int i = 1; i <= 8; i++) {
            rays[i] = new PriorityQueue<>(Comparator.comparingLong(p -> p.distance));
        }

        boolean originFound = false;

        for (int i = 0; i < n; i++) {
            char type = reader.next().charAt(0);
            long x = reader.nextLong() - centerX;
            long y = reader.nextLong() - centerY;

            if (x == 0 && y == 0) {
                originFound = true;
                // We continue reading all input to prevent stream corruption, 
                // but we stop processing directions.
                continue;
            }

            if (originFound) continue;

            int direction = getDirectionIndex(x, y);
            if (direction != -1) {
                // Using Manhattan distance is sufficient since points are on axes or diagonals
                long distance = Math.abs(x) + Math.abs(y);
                rays[direction].add(new Point(type, distance));
            }
        }

        if (originFound) {
            out.println("YES");
        } else {
            boolean resultFound = checkConditions(rays);
            out.println(resultFound ? "YES" : "NO");
        }

        out.flush();
        out.close();
    }

    /**
     * Maps a relative (x, y) coordinate to one of the 8 defined radial directions.
     * 
     * @param x relative x
     * @param y relative y
     * @return direction index 1-8, or -1 if not on a valid ray
     */
    private static int getDirectionIndex(long x, long y) {
        if (y == 0 && x > 0) return 1;               // Right
        if (x > 0 && y > 0 && x == y) return 2;      // Top-Right Diagonal
        if (x == 0 && y > 0) return 3;               // Top
        if (x < 0 && y > 0 && x + y == 0) return 4;  // Top-Left Diagonal
        if (x < 0 && y == 0) return 5;               // Left
        if (x < 0 && y < 0 && x == y) return 6;      // Bottom-Left Diagonal
        if (x == 0 && y < 0) return 7;               // Bottom
        if (x > 0 && y < 0 && x + y == 0) return 8;  // Bottom-Right Diagonal
        return -1;
    }

    /**
     * Checks the closest point on each ray to see if it meets the character criteria.
     */
    private static boolean checkConditions(PriorityQueue<Point>[] rays) {
        for (int d = 1; d <= 8; d++) {
            if (!rays[d].isEmpty()) {
                Point closest = rays[d].peek();
                if (isTypeValidForDirection(d, closest.type)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Defines which characters are valid for which ray direction.
     */
    private static boolean isTypeValidForDirection(int direction, char type) {
        // Odd directions (1, 3, 5, 7) check for 'R' or 'Q'
        // Even directions (2, 4, 6, 8) check for 'B' or 'Q'
        if (direction % 2 != 0) {
            return type == 'R' || type == 'Q';
        } else {
            return type == 'B' || type == 'Q';
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * Problem: Anton and Chess
 * Determines if a white piece at (x0, y0) is attacked by a red or blue piece 
 * in any of the 8 directions (horizontal, vertical, or diagonal), 
 * provided no other piece is in between.
 */
public class AntonAndChess {

    enum PieceType {
        RED, BLUE, WHITE;

        public static PieceType fromChar(char c) {
            return switch (c) {
                case 'R' -> RED;
                case 'B' -> BLUE;
                default -> WHITE;
            };
        }

        public boolean isAttacker() {
            return this == RED || this == BLUE;
        }
    }

    /**
     * Represents the chess board using maps of TreeMaps to allow 
     * efficient O(log N) spatial queries in four axes.
     */
    static class ChessBoard {
        // Maps for the 4 directions:
        // 1. Vertical: x -> (y -> Type)
        // 2. Horizontal: y -> (x -> Type)
        // 3. Diagonal Sum (x+y=C): (x+y) -> (x -> Type)
        // 4. Diagonal Diff (x-y=C): (x-y) -> (x -> Type)
        private final Map<Integer, TreeMap<Integer, PieceType>> vertical = new HashMap<>();
        private final Map<Integer, TreeMap<Integer, PieceType>> horizontal = new HashMap<>();
        private final Map<Integer, TreeMap<Integer, PieceType>> diagSum = new HashMap<>();
        private final Map<Integer, TreeMap<Integer, PieceType>> diagDiff = new HashMap<>();

        public void addPiece(int x, int y, PieceType type) {
            vertical.computeIfAbsent(x, k -> new TreeMap<>()).put(y, type);
            horizontal.computeIfAbsent(y, k -> new TreeMap<>()).put(x, type);
            diagSum.computeIfAbsent(x + y, k -> new TreeMap<>()).put(x, type);
            diagDiff.computeIfAbsent(x - y, k -> new TreeMap<>()).put(x, type);
        }

        public boolean isWhitePieceAttacked(int x, int y) {
            return checkDirection(vertical.get(x), y) ||
                   checkDirection(horizontal.get(y), x) ||
                   checkDirection(diagSum.get(x + y), x) ||
                   checkDirection(diagDiff.get(x - y), x);
        }

        /**
         * Finds the closest piece in a specific line/direction by looking 
         * for the immediate floor and ceiling of the target coordinate.
         */
        private boolean checkDirection(TreeMap<Integer, PieceType> line, int targetCoord) {
            if (line == null) return false;

            // Check piece strictly before the target coordinate on this line
            Integer floor = line.floorKey(targetCoord - 1);
            if (floor != null && line.get(floor).isAttacker()) {
                return true;
            }

            // Check piece strictly after the target coordinate on this line
            Integer ceil = line.ceilingKey(targetCoord + 1);
            if (ceil != null && line.get(ceil).isAttacker()) {
                return true;
            }

            return false;
        }
    }

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = reader.nextInt();
            int x0 = reader.nextInt();
            int y0 = reader.nextInt();

            ChessBoard board = new ChessBoard();

            for (int i = 0; i < n; i++) {
                String typeStr = reader.next();
                PieceType type = PieceType.fromChar(typeStr.charAt(0));
                int x = reader.nextInt();
                int y = reader.nextInt();
                board.addPiece(x, y, type);
            }

            if (board.isWhitePieceAttacked(x0, y0)) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        } catch (Exception e) {
            // Handle or log error
        } finally {
            out.close();
        }
    }

    /**
     * Efficient input reader for competitive programming.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;

/**
 * Represents the type of a chess piece and its movement capabilities.
 */
enum PieceType {
    QUEEN, ROOK, BISHOP;

    public static PieceType fromChar(char c) {
        return switch (c) {
            case 'Q' -> QUEEN;
            case 'R' -> ROOK;
            case 'B' -> BISHOP;
            default -> throw new IllegalArgumentException("Unknown piece type: " + c);
        };
    }

    /**
     * Determines if this piece type can attack in a specific direction.
     */
    public boolean canAttack(Direction direction) {
        if (direction.isOrthogonal()) {
            return this == QUEEN || this == ROOK;
        } else {
            return this == QUEEN || this == BISHOP;
        }
    }
}

/**
 * Represents the 8 possible directions from a target position.
 */
enum Direction {
    NORTH(true), SOUTH(true), EAST(true), WEST(true),
    NORTH_WEST(false), SOUTH_WEST(false), SOUTH_EAST(false), NORTH_EAST(false);

    private final boolean orthogonal;

    Direction(boolean orthogonal) {
        this.orthogonal = orthogonal;
    }

    public boolean isOrthogonal() {
        return orthogonal;
    }
}

/**
 * Represents a single piece on the board.
 */
class Piece {
    private final int x;
    private final int y;
    private final PieceType type;

    public Piece(int x, int y, char typeChar) {
        this.x = x;
        this.y = y;
        this.type = PieceType.fromChar(typeChar);
    }

    public int getX() { return x; }
    public int getY() { return y; }
    public PieceType getType() { return type; }

    /**
     * Calculates Manhattan distance. Since we only compare pieces 
     * on the same line, this is more efficient than Euclidean distance.
     */
    public int distanceTo(int tx, int ty) {
        return Math.abs(this.x - tx) + Math.abs(this.y - ty);
    }
}

/**
 * Engine responsible for detecting threats to a target position.
 */
class ThreatDetector {
    private final int targetX;
    private final int targetY;
    private final Map<Direction, Piece> closestPieces = new EnumMap<>(Direction.class);

    public ThreatDetector(int targetX, int targetY) {
        this.targetX = targetX;
        this.targetY = targetY;
    }

    public void addPiece(Piece piece) {
        Direction dir = calculateDirection(piece);
        if (dir != null) {
            updateClosestPiece(dir, piece);
        }
    }

    /**
     * Determines the direction of the piece relative to the target.
     * Returns null if the piece is not on the same row, column, or diagonal.
     */
    private Direction calculateDirection(Piece p) {
        int x = p.getX();
        int y = p.getY();

        if (x == targetX) {
            return y > targetY ? Direction.NORTH : Direction.SOUTH;
        } 
        if (y == targetY) {
            return x > targetX ? Direction.EAST : Direction.WEST;
        }
        if (x + y == targetX + targetY) {
            return x < targetX ? Direction.NORTH_WEST : Direction.SOUTH_EAST;
        }
        if (y - x == targetY - targetX) {
            return x < targetX ? Direction.SOUTH_WEST : Direction.NORTH_EAST;
        }
        return null;
    }

    private void updateClosestPiece(Direction dir, Piece piece) {
        Piece currentClosest = closestPieces.get(dir);
        if (currentClosest == null || piece.distanceTo(targetX, targetY) < currentClosest.distanceTo(targetX, targetY)) {
            closestPieces.put(dir, piece);
        }
    }

    public boolean isTargetUnderAttack() {
        for (Piece closest : closestPieces.values()) {
            Direction dir = calculateDirection(closest);
            if (dir != null && closest.getType().canAttack(dir)) {
                return true;
            }
        }
        return false;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        if (!sc.hasNextInt()) return;
        int n = sc.nextInt();
        int tx = sc.nextInt();
        int ty = sc.nextInt();

        ThreatDetector detector = new ThreatDetector(tx, ty);

        for (int i = 0; i < n; i++) {
            char typeChar = sc.next().charAt(0);
            int x = sc.nextInt();
            int y = sc.nextInt();
            detector.addPiece(new Piece(x, y, typeChar));
        }

        System.out.println(detector.isTargetUnderAttack() ? "YES" : "NO");
        sc.close();
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the Chess Problem.
 * The goal is to determine if a target coordinate (x, y) is under attack
 * by the closest piece in any of the 8 cardinal or intercardinal directions.
 */
public class Main {
    public static void main(String[] args) {
        FastReader in = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        ChessSolver solver = new ChessSolver();
        solver.solve(in, out);

        out.flush();
        out.close();
    }

    static class ChessSolver {
        private enum PieceType {
            ROOK, BISHOP, UNKNOWN;

            static PieceType fromChar(char c) {
                if (c == 'R') return ROOK;
                if (c == 'B') return BISHOP;
                return UNKNOWN;
            }
        }

        private enum Direction {
            // Directions: 0-3 are straight (Rook), 4-7 are diagonal (Bishop)
            NORTH(0, 1, true), SOUTH(0, -1, true),
            EAST(1, 0, true), WEST(-1, 0, true),
            NE(1, 1, false), NW(-1, 1, false),
            SE(1, -1, false), SW(-1, -1, false);

            final int dx, dy;
            final boolean isStraight;

            Direction(int dx, int dy, boolean isStraight) {
                this.dx = dx;
                this.dy = dy;
                this.isStraight = isStraight;
            }

            /**
             * Maps a relative coordinate (dx, dy) to a Direction index.
             * @return direction index 0-7, or -1 if the piece is not in a valid direction.
             */
            static int getDirectionIndex(long dx, long dy) {
                if (dx == 0 && dy == 0) return -1;

                if (dx == 0) {
                    return (dy > 0) ? 0 : 1; // North or South
                }
                if (dy == 0) {
                    return (dx > 0) ? 2 : 3; // East or West
                }
                if (Math.abs(dx) == Math.abs(dy)) {
                    if (dx > 0 && dy > 0) return 4; // NE
                    if (dx < 0 && dy > 0) return 5; // NW
                    if (dx > 0 && dy < 0) return 6; // SE
                    if (dx < 0 && dy < 0) return 7; // SW
                }
                return -1;
            }
        }

        public void solve(FastReader in, PrintWriter out) {
            int n = in.nextInt();
            if (n <= 0) {
                out.println("NO");
                return;
            }

            long targetX = in.nextLong();
            long targetY = in.nextLong();

            // Track the closest piece's distance and type for each of the 8 directions
            long[] minDists = new long[8];
            Arrays.fill(minDists, Long.MAX_VALUE);
            PieceType[] closestTypes = new PieceType[8];

            for (int i = 0; i < n; i++) {
                char typeChar = in.next().charAt(0);
                long xi = in.nextLong();
                long yi = in.nextLong();

                long dx = xi - targetX;
                long dy = yi - targetY;

                int dirIdx = Direction.getDirectionIndex(dx, dy);
                if (dirIdx != -1) {
                    long dist = Math.max(Math.abs(dx), Math.abs(dy));
                    if (dist < minDists[dirIdx]) {
                        minDists[dirIdx] = dist;
                        closestTypes[dirIdx] = PieceType.fromChar(typeChar);
                    }
                }
            }

            if (isUnderAttack(minDists, closestTypes)) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        }

        private boolean isUnderAttack(long[] minDists, PieceType[] closestTypes) {
            Direction[] directions = Direction.values();
            for (int i = 0; i < 8; i++) {
                if (minDists[i] == Long.MAX_VALUE) continue;

                boolean isStraightLine = directions[i].isStraight;
                PieceType type = closestTypes[i];

                // A Rook checks on straight lines, a Bishop checks on diagonals
                if (isStraightLine && type == PieceType.ROOK) {
                    return true;
                }
                if (!isStraightLine && type == PieceType.BISHOP) {
                    return true;
                }
            }
            return false;
        }
    }

    /**
     * Efficient input reader using BufferedReader and StringTokenizer.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            this.reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }
    }
}

import java.util.*;

/**
 * A program to determine if a target square on a chessboard is under attack
 * by a given set of chess pieces (Queen, Rook, or Bishop).
 * 
 * The program accounts for "blocking" by only considering the closest piece 
 * in any of the 8 cardinal and diagonal directions.
 */
public class ChessAttackDetector {

    /**
     * Represents the types of chess pieces available.
     */
    enum PieceType {
        QUEEN, ROOK, BISHOP;

        /**
         * Parses a string representation of a piece type.
         * @param s The string (e.g., "Q", "R", "B")
         * @return The corresponding PieceType
         * @throws IllegalArgumentException if the piece type is unknown
         */
        static PieceType fromString(String s) {
            return switch (s) {
                case "Q" -> QUEEN;
                case "R" -> ROOK;
                case "B" -> BISHOP;
                default -> throw new IllegalArgumentException("Unknown piece type: " + s);
            };
        }

        /**
         * Determines if this piece type can attack in a given direction type.
         * @param isDiagonal Whether the direction is diagonal.
         * @return True if the piece can move in that direction.
         */
        boolean canAttack(boolean isDiagonal) {
            return switch (this) {
                case QUEEN -> true;
                case ROOK -> !isDiagonal;
                case BISHOP -> isDiagonal;
            };
        }
    }

    /**
     * Represents the 8 possible directions on a chessboard.
     */
    enum Direction {
        NORTH(false), SOUTH(false), EAST(false), WEST(false),
        NE(true), NW(true), SE(true), SW(true);

        private final boolean isDiagonal;

        Direction(boolean isDiagonal) {
            this.isDiagonal = isDiagonal;
        }

        boolean isDiagonal() {
            return isDiagonal;
        }
    }

    /**
     * Helper class to track the closest piece found in a specific direction.
     */
    static class ClosestPiece {
        int distance = Integer.MAX_VALUE;
        PieceType type = null;

        /**
         * Updates the closest piece if the new piece is closer than the current one.
         * @param newDist The distance to the new piece.
         * @param newType The type of the new piece.
         */
        void update(int newDist, PieceType newType) {
            if (newDist < distance) {
                distance = newDist;
                type = newType;
            }
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int n = scanner.nextInt();
        int targetX = scanner.nextInt();
        int targetY = scanner.nextInt();

        // Map to store the closest piece found for each of the 8 directions.
        Map<Direction, ClosestPiece> closestPiecesByDirection = new EnumMap<>(Direction.class);
        for (Direction dir : Direction.values()) {
            closestPiecesByDirection.put(dir, new ClosestPiece());
        }

        for (int i = 0; i < n; i++) {
            String pieceStr = scanner.next();
            int px = scanner.nextInt();
            int py = scanner.nextInt();

            processPiece(closestPiecesByDirection, pieceStr, px, py, targetX, targetY);
        }

        boolean isUnderAttack = checkIfUnderAttack(closestPiecesByDirection);
        System.out.println(isUnderAttack ? "YES" : "NO");

        scanner.close();
    }

    /**
     * Processes an individual piece and updates the proximity map if the piece 
     * lies on an attacking line (orthogonal or diagonal).
     */
    private static void processPiece(Map<Direction, ClosestPiece> closestMap, 
                                    String pieceStr, int px, int py, 
                                    int targetX, int targetY) {
        int dx = px - targetX;
        int dy = py - targetY;

        Direction dir = getDirection(dx, dy);
        if (dir != null) {
            // Chebyshev distance is the standard metric for chess movement.
            int distance = Math.max(Math.abs(dx), Math.abs(dy));
            PieceType type = PieceType.fromString(pieceStr);
            closestMap.get(dir).update(distance, type);
        }
    }

    /**
     * Determines the direction from the target square to the piece.
     * @param dx The horizontal offset.
     * @param dy The vertical offset.
     * @return The Direction enum, or null if the piece is not in an attacking line.
     */
    private static Direction getDirection(int dx, int dy) {
        if (dx == 0 && dy == 0) return null; 

        // Orthogonal directions
        if (dx == 0) {
            return (dy > 0) ? Direction.NORTH : Direction.SOUTH;
        } 
        if (dy == 0) {
            return (dx > 0) ? Direction.EAST : Direction.WEST;
        } 

        // Diagonal directions
        if (Math.abs(dx) == Math.abs(dy)) {
            if (dx > 0 && dy > 0) return Direction.NE;
            if (dx > 0 && dy < 0) return Direction.SE;
            if (dx < 0 && dy < 0) return Direction.SW;
            return Direction.NW; // dx < 0 && dy > 0
        }

        return null;
    }

    /**
     * Checks if the closest piece in any of the 8 directions is capable 
     * of attacking the target square.
     */
    private static boolean checkIfUnderAttack(Map<Direction, ClosestPiece> closestMap) {
        for (Map.Entry<Direction, ClosestPiece> entry : closestMap.entrySet()) {
            Direction dir = entry.getKey();
            ClosestPiece cp = entry.getValue();

            if (cp.type != null && cp.type.canAttack(dir.isDiagonal())) {
                return true;
            }
        }
        return false;
    }
}

import java.util.Scanner;

/**
 * Represents the possible directions relative to a center point.
 */
enum Direction {
    SOUTH(0), NORTH_WEST(1), EAST(2), SOUTH_EAST(3), 
    NORTH(4), SOUTH_WEST(5), WEST(6), NORTH_EAST(7);

    private final int id;
    Direction(int id) { this.id = id; }
    public int getId() { return id; }
}

class ClosestNode {
    private char type = ' ';
    private int distance = Integer.MAX_VALUE;

    public void updateIfCloser(char type, int distance) {
        if (distance < this.distance) {
            this.type = type;
            this.distance = distance;
        }
    }

    public char getType() { return type; }
}

class DirectionTracker {
    private final ClosestNode[] nodes = new ClosestNode[8];

    public DirectionTracker() {
        for (int i = 0; i < 8; i++) nodes[i] = new ClosestNode();
    }

    public void recordPoint(int dx, int dy, char type) {
        Direction dir = determineDirection(dx, dy);
        if (dir != null) {
            int distance = Math.max(Math.abs(dx), Math.abs(dy));
            nodes[dir.getId()].updateIfCloser(type, distance);
        }
    }

    private Direction determineDirection(int dx, int dy) {
        if (dx == 0 && dy < 0) return Direction.SOUTH;
        if (dx == 0 && dy > 0) return Direction.NORTH;
        if (dy == 0 && dx < 0) return Direction.WEST;
        if (dy == 0 && dx > 0) return Direction.EAST;
        if (Math.abs(dx) == Math.abs(dy)) {
            if (dx < 0 && dy > 0) return Direction.NORTH_WEST;
            if (dx > 0 && dy < 0) return Direction.SOUTH_EAST;
            if (dx < 0 && dy < 0) return Direction.SOUTH_WEST;
            if (dx > 0 && dy > 0) return Direction.NORTH_EAST;
        }
        return null;
    }

    public ClosestNode getNode(Direction direction) {
        return nodes[direction.getId()];
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) return;

        int n = scanner.nextInt();
        int x = scanner.nextInt();
        int y = scanner.nextInt();

        DirectionTracker tracker = new DirectionTracker();

        for (int i = 0; i < n; i++) {
            char type = scanner.next().charAt(0);
            int x1 = scanner.nextInt();
            int y1 = scanner.nextInt();
            tracker.recordPoint(x1 - x, y1 - y, type);
        }

        if (evaluateResult(tracker)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
        scanner.close();
    }

    private static boolean evaluateResult(DirectionTracker tracker) {
        // Original logic: Orthogonal (0,2,4,6) check for 'R' or 'Q'
        boolean orthogonalCondition = 
            isMatch(tracker.getNode(Direction.SOUTH), 'R', 'Q') ||
            isMatch(tracker.getNode(Direction.EAST), 'R', 'Q') ||
            isMatch(tracker.getNode(Direction.NORTH), 'R', 'Q') ||
            isMatch(tracker.getNode(Direction.WEST), 'R', 'Q');

        if (orthogonalCondition) return true;

        // Original logic: Diagonal (1,3,5,7) check for 'B' or 'Q'
        return isMatch(tracker.getNode(Direction.NORTH_WEST), 'B', 'Q') ||
               isMatch(tracker.getNode(Direction.SOUTH_EAST), 'B', 'Q') ||
               isMatch(tracker.getNode(Direction.SOUTH_WEST), 'B', 'Q') ||
               isMatch(tracker.getNode(Direction.NORTH_EAST), 'B', 'Q');
    }

    private static boolean isMatch(ClosestNode node, char t1, char t2) {
        return node.getType() == t1 || node.getType() == t2;
    }
}

import java.util.Scanner;

/**
 * Represents a chess-based threat detection system.
 * Determines if a King is under threat from various pieces (Rooks, Bishops, Queens)
 * positioned on the same row, column, or diagonal.
 */
public class Chess {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int numPieces = scanner.nextInt();
        int kingX = scanner.nextInt();
        int kingY = scanner.nextInt();

        ChessGame game = new ChessGame(kingX, kingY);

        for (int i = 0; i < numPieces; i++) {
            String type = scanner.next();
            int x = scanner.nextInt();
            int y = scanner.nextInt();
            game.addPiece(type, x, y);
        }

        System.out.println(game.isKingThreatened() ? "YES" : "NO");
        scanner.close();
    }

    /**
     * Enum defining the 8 possible directions from the King.
     */
    enum Direction {
        NORTH(0, 1), SOUTH(0, -1), EAST(1, 0), WEST(-1, 0),
        NE(1, 1), NW(-1, 1), SE(1, -1), SW(-1, -1);

        final int dx, dy;

        Direction(int dx, int dy) {
            this.dx = dx;
            this.dy = dy;
        }

        /**
         * Determines the direction based on relative coordinates.
         */
        static Direction getDirection(int dx, int dy) {
            if (dx == 0 && dy > 0) return NORTH;
            if (dx == 0 && dy < 0) return SOUTH;
            if (dx > 0 && dy == 0) return EAST;
            if (dx < 0 && dy == 0) return WEST;
            if (dx > 0 && dy > 0) return NE;
            if (dx < 0 && dy > 0) return NW;
            if (dx > 0 && dy < 0) return SE;
            if (dx < 0 && dy < 0) return SW;
            return null;
        }
    }

    /**
     * Tracks the closest piece in a specific direction and whether it poses a threat.
     */
    static class DirectionTracker {
        private int minDistance = Integer.MAX_VALUE;
        private boolean isThreatening = false;

        public void update(int distance, boolean canThreaten) {
            if (distance < minDistance) {
                minDistance = distance;
                isThreatening = canThreaten;
            }
        }

        public boolean isThreatening() {
            return isThreatening;
        }
    }

    /**
     * Encapsulates the logic of the chess board and threat detection.
     */
    static class ChessGame {
        private final int kingX;
        private final int kingY;
        private final DirectionTracker[] directionTrackers;

        public ChessGame(int kingX, int kingY) {
            this.kingX = kingX;
            this.kingY = kingY;
            this.directionTrackers = new DirectionTracker[Direction.values().length];
            for (int i = 0; i < directionTrackers.length; i++) {
                directionTrackers[i] = new DirectionTracker();
            }
        }

        /**
         * Processes a piece and updates the direction trackers if the piece is on a relevant path.
         */
        public void addPiece(String type, int x, int y) {
            int dx = x - kingX;
            int dy = y - kingY;

            // If the piece is on the same spot as the king, ignore it
            if (dx == 0 && dy == 0) return;

            Direction dir = Direction.getDirection(dx, dy);
            if (dir == null) return;

            int distance = Math.max(Math.abs(dx), Math.abs(dy));
            boolean isThreat = calculateThreat(type, dir);

            directionTrackers[dir.ordinal()].update(distance, isThreat);
        }

        /**
         * Logic to determine if a piece of a certain type threatens in a given direction.
         * Orthogonal: Rooks (R) and Queens (Q) threaten.
         * Diagonal: Bishops (B) and Queens (Q) threaten.
         */
        private boolean calculateThreat(String type, Direction dir) {
            boolean isOrthogonal = (dir.dx == 0 || dir.dy == 0);
            if (isOrthogonal) {
                // A piece is a threat orthogonally if it's not a Bishop
                return !type.equals("B");
            } else {
                // A piece is a threat diagonally if it's not a Rook
                return !type.equals("R");
            }
        }

        public boolean isKingThreatened() {
            for (DirectionTracker tracker : directionTrackers) {
                if (tracker.isThreatening()) {
                    return true;
                }
            }
            return false;
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * A refactored solution to determine if a king is in checkmate
 * based on the positions and types of surrounding black pieces.
 */
public class Main {
    public static void main(String[] args) {
        FastReader in = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        ChessSolver solver = new ChessSolver();
        solver.solve(in, out);

        out.close();
    }

    static class ChessSolver {
        /**
         * Directions mapped to an index 0-7:
         * 0: North, 1: NorthEast, 2: East, 3: SouthEast, 
         * 4: South, 5: SouthWest, 6: West, 7: NorthWest
         */
        private static final int NUM_DIRECTIONS = 8;

        public void solve(FastReader in, PrintWriter out) {
            long numberOfBlackPieces = in.nextLong();
            Point king = new Point('K', in.nextLong(), in.nextLong());

            // Stores the closest piece found so far in each of the 8 directions
            Point[] closestPieces = new Point[NUM_DIRECTIONS];

            for (long i = 0; i < numberOfBlackPieces; i++) {
                char type = in.next().charAt(0);
                long x = in.nextLong();
                long y = in.nextLong();
                Point piece = new Point(type, x, y);

                long dx = x - king.x;
                long dy = y - king.y;

                // A piece only matters if it's on the same row, column, or diagonal
                if (isOnAttackLine(dx, dy)) {
                    int dirIndex = getDirectionIndex(dx, dy);
                    if (dirIndex != -1) {
                        updateClosestPiece(closestPieces, dirIndex, piece, king);
                    }
                }
            }

            out.println(isCheckmate(closestPieces) ? "YES" : "NO");
        }

        private boolean isOnAttackLine(long dx, long dy) {
            return dx == 0 || dy == 0 || Math.abs(dx) == Math.abs(dy);
        }

        private int getDirectionIndex(long dx, long dy) {
            if (dx == 0 && dy > 0) return 0;          // North
            if (dx > 0 && dy > 0) return 1;          // NorthEast
            if (dx > 0 && dy == 0) return 2;          // East
            if (dx > 0 && dy < 0) return 3;          // SouthEast
            if (dx == 0 && dy < 0) return 4;          // South
            if (dx < 0 && dy < 0) return 5;          // SouthWest
            if (dx < 0 && dy == 0) return 6;          // West
            if (dx < 0 && dy > 0) return 7;          // NorthWest
            return -1;
        }

        private void updateClosestPiece(Point[] closest, int index, Point newPiece, Point king) {
            if (closest[index] == null || newPiece.getSquaredDistance(king) < closest[index].getSquaredDistance(king)) {
                closest[index] = newPiece;
            }
        }

        private boolean isCheckmate(Point[] closestPieces) {
            for (int i = 0; i < NUM_DIRECTIONS; i++) {
                Point p = closestPieces[i];
                if (p == null) continue;

                // Even indices (0, 2, 4, 6) are orthogonal, odd indices (1, 3, 5, 7) are diagonal
                boolean isDiagonalDirection = (i % 2 != 0);

                if (isDiagonalDirection) {
                    // Diagonal attackers: Queen or Bishop
                    if (p.type == 'Q' || p.type == 'B') return true;
                } else {
                    // Orthogonal attackers: Queen or Rook
                    if (p.type == 'Q' || p.type == 'R') return true;
                }
            }
            return false;
        }
    }

    static class Point {
        final char type;
        final long x;
        final long y;

        Point(char type, long x, long y) {
            this.type = type;
            this.x = x;
            this.y = y;
        }

        /**
         * Returns the squared Euclidean distance to avoid expensive and 
         * precision-sensitive square root operations.
         */
        long getSquaredDistance(Point other) {
            long dx = this.x - other.x;
            long dy = this.y - other.y;
            return (dx * dx) + (dy * dy);
        }
    }

    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public long nextLong() {
            return Long.parseLong(next());
        }
    }
}

import java.util.Scanner;

/**
 * PieceProximityAnalyzer determines if a specific piece configuration 
 * satisfies proximity conditions relative to a target coordinate.
 */
public class PieceProximityAnalyzer {

    /**
     * Represents the 8 possible directions/relationships relative to a target.
     */
    enum Direction {
        SOUTH, NORTH, WEST, EAST, 
        NORTH_WEST, NORTH_EAST, SOUTH_WEST, SOUTH_EAST;

        /**
         * Determines the direction of a piece relative to the target coordinates.
         * 
         * @param px Piece X coordinate
         * @param py Piece Y coordinate
         * @param tx Target X coordinate
         * @param ty Target Y coordinate
         * @return The Direction enum, or null if the piece is not in a valid direction.
         */
        public static Direction fromCoords(long px, long py, long tx, long ty) {
            if (px == tx) {
                return py < ty ? SOUTH : NORTH;
            }
            if (py == ty) {
                return px < tx ? WEST : EAST;
            }
            if (Math.abs(px - tx) == Math.abs(py - ty)) {
                if (px < tx && py > ty) return NORTH_WEST;
                if (px > tx && py > ty) return NORTH_EAST;
                if (px < tx && py < ty) return SOUTH_WEST;
                return SOUTH_EAST; // px > tx && py < ty
            }
            return null;
        }
    }

    /**
     * Represents the type of game piece.
     */
    enum PieceType {
        RED('R'), QUEEN('Q'), BLACK('B'), OTHER(' ');

        private final char id;

        PieceType(char id) {
            this.id = id;
        }

        public static PieceType fromChar(char c) {
            for (PieceType type : PieceType.values()) {
                if (type.id == c) return type;
            }
            return OTHER;
        }
    }

    /**
     * Represents a game piece with a type and position.
     */
    static class Piece {
        private final PieceType type;
        private final long x;
        private final long y;

        Piece(char id, long x, long y) {
            this.type = PieceType.fromChar(id);
            this.x = x;
            this.y = y;
        }

        public PieceType getType() {
            return type;
        }

        /**
         * Calculates the squared distance to a target. 
         * Squared distance is used to avoid unnecessary Math.sqrt calls.
         */
        public double distanceSquared(long tx, long ty) {
            double dx = (double) this.x - tx;
            double dy = (double) this.y - ty;
            return dx * dx + dy * dy;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }

        int n = scanner.nextInt();
        long targetX = scanner.nextLong();
        long targetY = scanner.nextLong();

        Piece[] closestPieces = new Piece[Direction.values().length];
        double[] minDistanceSq = new double[Direction.values().length];

        // Initialize minimum distances to infinity
        for (int i = 0; i < minDistanceSq.length; i++) {
            minDistanceSq[i] = Double.MAX_VALUE;
        }

        for (int i = 0; i < n; i++) {
            char id = scanner.next().charAt(0);
            long x = scanner.nextLong();
            long y = scanner.nextLong();
            Piece piece = new Piece(id, x, y);

            Direction dir = Direction.fromCoords(x, y, targetX, targetY);
            if (dir != null) {
                double distSq = piece.distanceSquared(targetX, targetY);
                int dirIndex = dir.ordinal();
                if (distSq < minDistanceSq[dirIndex]) {
                    minDistanceSq[dirIndex] = distSq;
                    closestPieces[dirIndex] = piece;
                }
            }
        }

        boolean isWinningConditionMet = evaluateWinningCondition(closestPieces);
        System.out.println(isWinningConditionMet ? "YES" : "NO");

        scanner.close();
    }

    /**
     * Evaluates the specific rules for winning based on the closest pieces in each direction.
     * 
     * @param closest The array of closest pieces per direction.
     * @return true if the condition is met, false otherwise.
     */
    private static boolean evaluateWinningCondition(Piece[] closest) {
        // Rule 1: Any closest piece in Cardinal directions (SOUTH, NORTH, WEST, EAST) 
        // is RED or QUEEN.
        for (int i = 0; i < 4; i++) {
            if (closest[i] != null) {
                PieceType type = closest[i].getType();
                if (type == PieceType.RED || type == PieceType.QUEEN) {
                    return true;
                }
            }
        }

        // Rule 2: Any closest piece in Diagonal directions (NW, NE, SW, SE) 
        // is QUEEN or BLACK.
        for (int i = 4; i < 8; i++) {
            if (closest[i] != null) {
                PieceType type = closest[i].getType();
                if (type == PieceType.QUEEN || type == PieceType.BLACK) {
                    return true;
                }
            }
        }

        return false;
    }
}

import java.io.*;
import java.util.*;
import java.util.function.Predicate;
import java.util.function.ToIntFunction;

/**
 * A solution to determine if a king on a chessboard is threatened by 
 * any pieces (Rook, Bishop, or Queen) along its horizontal, vertical, 
 * or diagonal lines.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            int numPieces = reader.nextInt();
            int kingX = reader.nextInt();
            int kingY = reader.nextInt();

            List<Piece> pieces = new ArrayList<>(numPieces);
            for (int i = 0; i < numPieces; i++) {
                char type = reader.nextChar();
                int x = reader.nextInt();
                int y = reader.nextInt();
                pieces.add(new Piece(type, x, y));
            }

            ChessProblem problem = new ChessProblem();
            boolean isKingBeaten = problem.isKingThreatened(kingX, kingY, pieces);

            writer.println(isKingBeaten ? "YES" : "NO");
        } catch (Exception e) {
            // Handle potential input errors
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Represents a single chess piece on the board.
     */
    static class Piece {
        final char type;
        final int x;
        final int y;

        Piece(char type, int x, int y) {
            this.type = type;
            this.x = x;
            this.y = y;
        }

        /**
         * A piece is a rook-style threat if it is a Rook or a Queen.
         */
        boolean isRookThreat() {
            return type == 'R' || type == 'Q';
        }

        /**
         * A piece is a bishop-style threat if it is a Bishop or a Queen.
         */
        boolean isBishopThreat() {
            return type == 'B' || type == 'Q';
        }
    }

    /**
     * Contains the core logic for calculating chess threats.
     */
    static class ChessProblem {

        /**
         * Checks if the king is threatened by checking the 4 lines of movement:
         * 1. Horizontal (Constant Y)
         * 2. Vertical (Constant X)
         * 3. Main Diagonal (Constant X - Y)
         * 4. Anti-Diagonal (Constant X + Y)
         */
        public boolean isKingThreatened(int kingX, int kingY, List<Piece> pieces) {
            // Check Rook-style lines (Horizontal and Vertical)
            if (checkLine(pieces, p -> p.y == kingY, p -> p.x, kingX, Piece::isRookThreat)) return true;
            if (checkLine(pieces, p -> p.x == kingX, p -> p.y, kingY, Piece::isRookThreat)) return true;

            // Check Bishop-style lines (Diagonals)
            // For diagonals, we use X as the coordinate to determine "closeness" to the king
            if (checkLine(pieces, p -> (p.x - p.y) == (kingX - kingY), p -> p.x, kingX, Piece::isBishopThreat)) return true;
            if (checkLine(pieces, p -> (p.x + p.y) == (kingX + kingY), p -> p.x, kingX, Piece::isBishopThreat)) return true;

            return false;
        }

        /**
         * Evaluates a specific line of pieces to see if the closest piece to the king is a threat.
         *
         * @param pieces          All pieces on the board.
         * @param lineFilter      Predicate to determine if a piece belongs to the line being checked.
         * @param coordExtractor  Function to extract the relevant coordinate along that line.
         * @param kingCoord       The king's coordinate on that specific line.
         * @param threatPredicate Predicate to check if a piece is capable of attacking.
         * @return true if the king is threatened on this line.
         */
        private boolean checkLine(List<Piece> pieces, 
                                  Predicate<Piece> lineFilter, 
                                  ToIntFunction<Piece> coordExtractor, 
                                  int kingCoord, 
                                  Predicate<Piece> threatPredicate) {

            Piece closestLower = null;
            Piece closestHigher = null;

            for (Piece piece : pieces) {
                if (lineFilter.test(piece)) {
                    int pieceCoord = coordExtractor.applyAsInt(piece);

                    if (pieceCoord < kingCoord) {
                        // Looking for the piece with the largest coordinate that is still less than the king
                        if (closestLower == null || pieceCoord > coordExtractor.applyAsInt(closestLower)) {
                            closestLower = piece;
                        }
                    } else if (pieceCoord > kingCoord) {
                        // Looking for the piece with the smallest coordinate that is still greater than the king
                        if (closestHigher == null || pieceCoord < coordExtractor.applyAsInt(closestHigher)) {
                            closestHigher = piece;
                        }
                    }
                }
            }

            return (closestLower != null && threatPredicate.test(closestLower)) ||
                   (closestHigher != null && threatPredicate.test(closestHigher));
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public char nextChar() {
            return next().charAt(0);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

/**
 * A refactored solution to a coordinate-based geometric problem.
 * The program determines if any point of specific types lies within 
 * the boundaries established by other points on axes or diagonals.
 */
public class CoordinateCollisionResolver {

    private static final long INF = Long.MAX_VALUE - 100;

    public static void main(String[] args) {
        try {
            new CoordinateCollisionResolver().solve();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /**
     * Represents a point on a 2D plane.
     */
    private record Point(long x, long y) {}

    /**
     * Defines the types of points available in the problem.
     */
    private enum PointType {
        B, R, OTHER
    }

    /**
     * Fast I/O reader to handle large inputs efficiently.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader() {
            this.reader = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }

    /**
     * Stores and manages boundaries along the cardinal axes (Horizontal/Vertical).
     */
    private static class AxisBoundaries {
        long up = INF, down = INF, left = INF, right = INF;

        void update(Point p, long x0, long y0) {
            if (p.x == x0) {
                if (p.y > y0) {
                    up = Math.min(up, p.y - y0);
                } else {
                    down = Math.min(down, y0 - p.y);
                }
            }
            if (p.y == y0) {
                if (p.x > x0) {
                    right = Math.min(right, p.x - x0);
                } else {
                    left = Math.min(left, x0 - p.x);
                }
            }
        }

        boolean isWithin(Point p, long x0, long y0) {
            if (p.x == x0) {
                long deltaY = p.y - y0;
                return deltaY > -down && deltaY < up;
            }
            if (p.y == y0) {
                long deltaX = p.x - x0;
                return deltaX > -left && deltaX < right;
            }
            return false;
        }
    }

    /**
     * Stores and manages boundaries along the diagonals (45-degree lines).
     */
    private static class DiagonalBoundaries {
        long upLeft = INF, upRight = INF, downLeft = INF, downRight = INF;

        void update(Point p, long x0, long y0) {
            // Diagonal 1: x - y = constant
            if (p.x - p.y == x0 - y0) {
                if (p.x > x0) {
                    upRight = Math.min(upRight, p.x - x0);
                } else {
                    downLeft = Math.min(downLeft, x0 - p.x);
                }
            }
            // Diagonal 2: x + y = constant
            if (p.x + p.y == x0 + y0) {
                if (p.x > x0) {
                    downRight = Math.min(downRight, p.x - x0);
                } else {
                    upLeft = Math.min(upLeft, x0 - p.x);
                }
            }
        }

        boolean isWithin(Point p, long x0, long y0) {
            // Check diagonal 1
            if (p.x - p.y == x0 - y0) {
                long deltaX = p.x - x0;
                return deltaX > -downLeft && deltaX < upRight;
            }
            // Check diagonal 2
            if (p.x + p.y == x0 + y0) {
                long deltaX = p.x - x0;
                return deltaX > -upLeft && deltaX < downRight;
            }
            return false;
        }
    }

    public void solve() throws IOException {
        FastReader fr = new FastReader();

        int n = fr.nextInt();
        long x0 = fr.nextLong();
        long y0 = fr.nextLong();

        List<Point> bPoints = new ArrayList<>(); // Type B
        List<Point> rPoints = new ArrayList<>(); // Type R
        List<Point> otherPoints = new ArrayList<>(); // Type Other

        for (int i = 0; i < n; i++) {
            String typeStr = fr.next();
            long x = fr.nextLong();
            long y = fr.nextLong();
            Point p = new Point(x, y);

            switch (typeStr) {
                case "B" -> bPoints.add(p);
                case "R" -> rPoints.add(p);
                default -> otherPoints.add(p);
            }
        }

        AxisBoundaries axisBounds = new AxisBoundaries();
        DiagonalBoundaries diagBounds = new DiagonalBoundaries();

        // Type B points define the Axis boundaries
        for (Point p : bPoints) {
            axisBounds.update(p, x0, y0);
        }

        // Type R points define the Diagonal boundaries
        for (Point p : rPoints) {
            diagBounds.update(p, x0, y0);
        }

        boolean result = checkResult(bPoints, rPoints, otherPoints, x0, y0, axisBounds, diagBounds);

        System.out.println(result ? "YES" : "NO");
    }

    /**
     * Evaluates the condition for the existence of a valid point.
     */
    private boolean checkResult(List<Point> bPoints, List<Point> rPoints, List<Point> otherPoints,
                                long x0, long y0, AxisBoundaries axisBounds, DiagonalBoundaries diagBounds) {

        // B points are valid if they fall within Diagonal boundaries (defined by R)
        for (Point p : bPoints) {
            if (diagBounds.isWithin(p, x0, y0)) return true;
        }

        // R points are valid if they fall within Axis boundaries (defined by B)
        for (Point p : rPoints) {
            if (axisBounds.isWithin(p, x0, y0)) return true;
        }

        // Other points are valid if they fall in either boundary set
        for (Point p : otherPoints) {
            if (diagBounds.isWithin(p, x0, y0) || axisBounds.isWithin(p, x0, y0)) {
                return true;
            }
        }

        return false;
    }
}

import java.util.*;

/**
 * A utility to detect if a target position on a chessboard is threatened 
 * by any given chess pieces.
 */
public class ChessThreatDetector {

    /**
     * Represents the 8 possible directions a piece can move on a chessboard.
     */
    public enum Direction {
        UP(0, 1), 
        DOWN(0, -1), 
        LEFT(-1, 0), 
        RIGHT(1, 0),
        UP_RIGHT(1, 1), 
        DOWN_LEFT(-1, -1), 
        DOWN_RIGHT(1, -1), 
        UP_LEFT(-1, 1);

        private final int dx;
        private final int dy;

        Direction(int dx, int dy) {
            this.dx = dx;
            this.dy = dy;
        }

        /**
         * Determines the direction given the relative distance (dx, dy) from a target.
         * 
         * @param dx Relative X distance
         * @param dy Relative Y distance
         * @return The corresponding Direction, or null if not in a valid direction.
         */
        public static Direction getDirection(int dx, int dy) {
            if (dx == 0 && dy > 0) return UP;
            if (dx == 0 && dy < 0) return DOWN;
            if (dy == 0 && dx > 0) return RIGHT;
            if (dy == 0 && dx < 0) return LEFT;
            if (dx > 0 && dy > 0) return UP_RIGHT;
            if (dx < 0 && dy < 0) return DOWN_LEFT;
            if (dx > 0 && dy < 0) return DOWN_RIGHT;
            if (dx < 0 && dy > 0) return UP_LEFT;
            return null;
        }
    }

    /**
     * Represents a chess piece.
     */
    public static class Piece {
        final char type;
        final int x;
        final int y;

        public Piece(char type, int x, int y) {
            this.type = type;
            this.x = x;
            this.y = y;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int numberOfPieces = scanner.nextInt();

        if (!scanner.hasNextInt()) {
            return;
        }
        int targetX = scanner.nextInt();
        int targetY = scanner.nextInt();

        // Stores the closest piece found in each of the 8 directions
        Map<Direction, Piece> closestPiecesInDirection = new EnumMap<>(Direction.class);
        // Stores the distance of the closest piece in each direction
        Map<Direction, Integer> minDistanceInDirection = new EnumMap<>(Direction.class);

        for (int i = 0; i < numberOfPieces; i++) {
            if (!scanner.hasNext()) break;

            char type = scanner.next().charAt(0);
            int px = scanner.nextInt();
            int py = scanner.nextInt();

            Piece piece = new Piece(type, px, py);
            updateClosestPieces(piece, targetX, targetY, closestPiecesInDirection, minDistanceInDirection);
        }

        boolean isThreatened = checkThreat(closestPiecesInDirection);
        System.out.println(isThreatened ? "YES" : "NO");

        scanner.close();
    }

    /**
     * Updates the tracking maps if the current piece is the closest one found in its direction.
     */
    private static void updateClosestPieces(Piece piece, int targetX, int targetY, 
                                            Map<Direction, Piece> closestPieces, 
                                            Map<Direction, Integer> minDistances) {
        int dx = piece.x - targetX;
        int dy = piece.y - targetY;

        // Ignore if the piece is at the exact same position as the target
        if (dx == 0 && dy == 0) {
            return;
        }

        Direction dir = Direction.getDirection(dx, dy);
        if (dir != null) {
            // In chess movement (orthogonal/diagonal), Chebyshev distance is a valid proxy
            int distance = Math.max(Math.abs(dx), Math.abs(dy));

            if (!minDistances.containsKey(dir) || distance < minDistances.get(dir)) {
                minDistances.put(dir, distance);
                closestPieces.put(dir, piece);
            }
        }
    }

    /**
     * Evaluates if the target is threatened based on the closest pieces in all directions.
     */
    private static boolean checkThreat(Map<Direction, Piece> closestPieces) {
        // 1. Check Orthogonal directions: Rook ('R') or Queen ('Q')
        for (Direction dir : EnumSet.of(Direction.UP, Direction.DOWN, Direction.LEFT, Direction.RIGHT)) {
            Piece p = closestPieces.get(dir);
            if (p != null && (p.type == 'Q' || p.type == 'R')) {
                return true;
            }
        }

        // 2. Check Diagonal directions: Bishop ('B') or Queen ('Q')
        for (Direction dir : EnumSet.of(Direction.UP_RIGHT, Direction.DOWN_LEFT, Direction.DOWN_RIGHT, Direction.UP_LEFT)) {
            Piece p = closestPieces.get(dir);
            if (p != null && (p.type == 'Q' || p.type == 'B')) {
                return true;
            }
        }

        return false;
    }
}

import java.util.Scanner;

/**
 * A program to determine if a king on a chessboard is under attack 
 * by the closest piece in any of the 8 cardinal or ordinal directions.
 */
public class AntonAndChess {

    /**
     * Represents the 8 possible directions a chess piece can move 
     * to reach the king in a straight or diagonal line.
     */
    private enum Direction {
        RIGHT(1, 0, true),
        LEFT(-1, 0, true),
        UP(0, 1, true),
        DOWN(0, -1, true),
        UP_RIGHT(1, 1, false),
        UP_LEFT(-1, 1, false),
        DOWN_RIGHT(1, -1, false),
        DOWN_LEFT(-1, -1, false);

        final int dx, dy;
        final boolean isStraight;

        Direction(int dx, int dy, boolean isStraight) {
            this.dx = dx;
            this.dy = dy;
            this.isStraight = isStraight;
        }

        /**
         * Returns the Direction matching the sign of the relative movement.
         */
        static Direction fromOffsets(int dx, int dy) {
            for (Direction d : values()) {
                if (d.dx == dx && d.dy == dy) {
                    return d;
                }
            }
            return null;
        }
    }

    /**
     * Represents a chess piece.
     */
    private record Piece(char type, long x, long y) {}

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int pieceCount = scanner.nextInt();
        long kingX = scanner.nextLong();
        long kingY = scanner.nextLong();

        // We track the closest piece found in each of the 8 directions
        Direction[] directions = Direction.values();
        Piece[] closestPieces = new Piece[directions.length];
        long[] minDistanceToKing = new long[directions.length];

        // Initialize distances to infinity
        for (int i = 0; i < directions.length; i++) {
            minDistanceToKing[i] = Long.MAX_VALUE;
        }

        // Process each piece on the board
        for (int i = 0; i < pieceCount; i++) {
            char type = scanner.next().charAt(0);
            long px = scanner.nextLong();
            long py = scanner.nextLong();

            // Calculate direction vector (-1, 0, or 1)
            int dirX = Long.compare(px - kingX, 0);
            int dirY = Long.compare(py - kingY, 0);

            Direction dir = Direction.fromOffsets(dirX, dirY);

            // If the piece is not in one of the 8 directions, skip it
            if (dir == null) {
                continue;
            }

            // Chebyshev distance is appropriate for chess movement (king/queen/etc)
            long distance = Math.max(Math.abs(px - kingX), Math.abs(py - kingY));

            int dirIndex = dir.ordinal();
            if (distance < minDistanceToKing[dirIndex]) {
                minDistanceToKing[dirIndex] = distance;
                closestPieces[dirIndex] = new Piece(type, px, py);
            }
        }

        System.out.println(isKingUnderAttack(closestPieces) ? "YES" : "NO");
        scanner.close();
    }

    /**
     * Checks if any of the closest pieces found in the 8 directions 
     * are capable of attacking the king.
     */
    private static boolean isKingUnderAttack(Piece[] closestPieces) {
        Direction[] directions = Direction.values();

        for (int i = 0; i < directions.length; i++) {
            Piece piece = closestPieces[i];
            if (piece == null) {
                continue;
            }

            Direction dir = directions[i];
            char type = piece.type;

            if (dir.isStraight) {
                // Rooks and Queens attack straight lines
                if (type == 'Q' || type == 'R') {
                    return true;
                }
            } else {
                // Bishops and Queens attack diagonals
                if (type == 'Q' || type == 'B') {
                    return true;
                }
            }
        }
        return false;
    }
}

