import java.util.*;

/**
 * Refactored solution for determining if a central city is reachable 
 * from the nearest cities in 8 specific directions.
 */
public class CF734D {

    /**
     * Represents the 8 valid directions (Cardinal and Diagonal) relative to the center.
     */
    enum Direction {
        EAST(1, 0, true),
        NORTH(0, 1, true),
        WEST(-1, 0, true),
        SOUTH(0, -1, true),
        NORTH_EAST(1, 1, false),
        NORTH_WEST(-1, 1, false),
        SOUTH_WEST(-1, -1, false),
        SOUTH_EAST(1, -1, false);

        private final int dx;
        private final int dy;
        private final boolean isCardinal;

        Direction(int dx, int dy, boolean isCardinal) {
            this.dx = dx;
            this.dy = dy;
            this.isCardinal = isCardinal;
        }

        /**
         * Validates if a specific color allows movement towards the center.
         * Cardinal directions: Red ('R') or Queen ('Q') are valid.
         * Diagonal directions: Blue ('B') or Queen ('Q') are valid.
         */
        public boolean isValidColor(char color) {
            if (color == 'Q') return true;
            return isCardinal ? color == 'R' : color == 'B';
        }

        /**
         * Identifies the direction based on relative coordinates.
         * @param dx relative x-coordinate
         * @param dy relative y-coordinate
         * @return The matching Direction, or null if the city is not on a valid path.
         */
        public static Direction fromRelativeCoords(int dx, int dy) {
            if (dx == 0 && dy == 0) return null;

            // Check Cardinal Directions (one axis is zero)
            if (dy == 0) return dx > 0 ? EAST : WEST;
            if (dx == 0) return dy > 0 ? NORTH : SOUTH;

            // Check Diagonal Directions (absolute values are equal)
            if (Math.abs(dx) == Math.abs(dy)) {
                if (dx > 0 && dy > 0) return NORTH_EAST;
                if (dx < 0 && dy > 0) return NORTH_WEST;
                if (dx < 0 && dy < 0) return SOUTH_WEST;
                if (dx > 0 && dy < 0) return SOUTH_EAST;
            }

            return null;
        }
    }

    /**
     * Maintains the state of the closest city encountered so far for a direction.
     */
    static class ClosestCity {
        int distance = Integer.MAX_VALUE;
        char color = ' ';

        void updateIfCloser(int newDistance, char newColor) {
            if (newDistance < this.distance) {
                this.distance = newDistance;
                this.color = newColor;
            }
        }
    }

    /**
     * Optimized reader for faster input processing.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) {
        FastReader fr = new FastReader(System.in);

        String nInput = fr.next();
        if (nInput == null) return;
        int n = Integer.parseInt(nInput);

        int x0 = fr.nextInt();
        int y0 = fr.nextInt();

        // Map to store the closest city for every possible direction
        Map<Direction, ClosestCity> closestCitiesMap = new EnumMap<>(Direction.class);
        for (Direction dir : Direction.values()) {
            closestCitiesMap.put(dir, new ClosestCity());
        }

        for (int i = 0; i < n; i++) {
            char color = fr.next().charAt(0);
            int x = fr.nextInt();
            int y = fr.nextInt();

            int dx = x - x0;
            int dy = y - y0;

            Direction dir = Direction.fromRelativeCoords(dx, dy);
            if (dir != null) {
                // For cardinal and diagonal lines, distance is max(|dx|, |dy|)
                int dist = Math.max(Math.abs(dx), Math.abs(dy));
                closestCitiesMap.get(dir).updateIfCloser(dist, color);
            }
        }

        boolean canReachCenter = checkReachability(closestCitiesMap);
        System.out.println(canReachCenter ? "YES" : "NO");
    }

    /**
     * Iterates through all directions to see if any closest city allows 
     * access to the central coordinate.
     */
    private static boolean checkReachability(Map<Direction, ClosestCity> closestCitiesMap) {
        for (Map.Entry<Direction, ClosestCity> entry : closestCitiesMap.entrySet()) {
            Direction dir = entry.getKey();
            ClosestCity closest = entry.getValue();

            if (closest.color != ' ' && dir.isValidColor(closest.color)) {
                return true;
            }
        }
        return false;
    }
}

