/**
 * Refactored solution for the figure placement problem.
 * Determines if a central position can be "attacked" by any piece 
 * based on its proximity and direction.
 */
public class P734D {

    /**
     * Represents the 8 possible directions a piece can be placed.
     * Encapsulates the logic for piece type validation.
     */
    enum Direction {
        // Cardinal directions (Rook/Queen allowed)
        RIGHT(true, 'R', 'Q'),
        LEFT(true, 'R', 'Q'),
        UP(true, 'R', 'Q'),
        DOWN(true, 'R', 'Q'),

        // Diagonal directions (Bishop/Queen allowed)
        UP_RIGHT(false, 'B', 'Q'),
        DOWN_RIGHT(false, 'B', 'Q'),
        UP_LEFT(false, 'B', 'Q'),
        DOWN_LEFT(false, 'B', 'Q');

        private final char type1;
        private final char type2;

        Direction(boolean isCardinal, char type1, char type2) {
            this.type1 = type1;
            this.type2 = type2;
        }

        /**
         * Checks if the given piece type is allowed to win in this direction.
         */
        public boolean isWinningPiece(char type) {
            return type == type1 || type == type2;
        }
    }

    /**
     * Represents a figure placed on the grid.
     */
    static class Figure implements Comparable<Figure> {
        final char type;
        final long distance;

        Figure(char type, long distance) {
            this.type = type;
            this.distance = distance;
        }

        @Override
        public int compareTo(Figure other) {
            return Long.compare(this.distance, other.distance);
        }
    }

    /**
     * Main logic execution.
     */
    public void solve() throws IOException {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        int n = reader.nextInt();
        int x0 = reader.nextInt();
        int y0 = reader.nextInt();

        // Maps each direction to a list of figures found in that direction
        Map<Direction, List<Figure>> directionMap = new EnumMap<>(Direction.class);
        for (Direction dir : Direction.values()) {
            directionMap.put(dir, new ArrayList<>());
        }

        for (int i = 0; i < n; i++) {
            char type = reader.next().charAt(0);
            int x = reader.nextInt();
            int y = reader.nextInt();

            int dx = x - x0;
            int dy = y - y0;

            Direction dir = determineDirection(dx, dy);
            if (dir != null) {
                // Using Manhattan distance for sorting as per original logic
                long distance = Math.abs((long) dx) + Math.abs((long) dy);
                directionMap.get(dir).add(new Figure(type, distance));
            }
        }

        boolean canWin = checkVictory(directionMap);
        out.println(canWin ? "YES" : "NO");
        out.flush();
        out.close();
    }

    /**
     * Determines which direction a coordinate (dx, dy) falls into.
     */
    private Direction determineDirection(int dx, int dy) {
        if (dy == 0) {
            return dx > 0 ? Direction.RIGHT : Direction.LEFT;
        } else if (dx == 0) {
            return dy > 0 ? Direction.UP : Direction.DOWN;
        } else if (Math.abs(dx) == Math.abs(dy)) {
            if (dx > 0) {
                return dy > 0 ? Direction.UP_RIGHT : Direction.DOWN_RIGHT;
            } else {
                return dy > 0 ? Direction.UP_LEFT : Direction.DOWN_LEFT;
            }
        }
        return null;
    }

    /**
     * Checks if any direction has a winning piece as its closest figure.
     */
    private boolean checkVictory(Map<Direction, List<Figure>> directionMap) {
        for (Direction dir : Direction.values()) {
            List<Figure> figures = directionMap.get(dir);
            if (!figures.isEmpty()) {
                Collections.sort(figures);
                if (dir.isWinningPiece(figures.get(0).type)) {
                    return true;
                }
            }
        }
        return false;
    }

    public static void main(String[] args) throws IOException {
        new P734D().solve();
    }

    /**
     * High-performance input reader.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }
}

import java.util.*;

/**
 * A solution to determine if any chess piece can attack a target square on a board.
 */
public class Solution {

    /**
     * Represents a chess piece on the board.
     */
    private static class Piece {
        final char type;
        final int x;
        final int y;

        Piece(char type, int x, int y) {
            this.type = type;
            this.x = x;
            this.y = y;
        }
    }

    /**
     * Represents a direction vector from the target square.
     */
    private static class Direction {
        final int dx;
        final int dy;
        final boolean isDiagonal;

        Direction(int dx, int dy) {
            this.dx = dx;
            this.dy = dy;
            // A direction is diagonal if the absolute changes in x and y are equal
            this.isDiagonal = Math.abs(dx) == Math.abs(dy);
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            Direction direction = (Direction) o;
            return dx == direction.dx && dy == direction.dy;
        }

        @Override
        public int hashCode() {
            return Objects.hash(dx, dy);
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int numberOfPieces = scanner.nextInt();
        int targetX = scanner.nextInt();
        int targetY = scanner.nextInt();

        // Map to store the closest piece found in each of the 8 possible directions
        Map<Direction, Piece> closestPiecesByDirection = new HashMap<>();

        for (int i = 0; i < numberOfPieces; i++) {
            char type = scanner.next().charAt(0);
            int x = scanner.nextInt();
            int y = scanner.nextInt();

            processPiece(closestPiecesByDirection, new Piece(type, x, y), targetX, targetY);
        }

        if (isTargetUnderAttack(closestPiecesByDirection)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Determines the direction of a piece relative to the target and updates
     * the closest piece found so far in that direction.
     */
    private static void processPiece(Map<Direction, Piece> closestPieces, Piece piece, int targetX, int targetY) {
        int dx = Integer.compare(piece.x, targetX);
        int dy = Integer.compare(piece.y, targetY);

        // Check if the piece is on the same row, column, or diagonal, and is not the target itself
        boolean isStraight = (dx == 0 || dy == 0);
        boolean isDiagonal = (Math.abs(dx) == Math.abs(dy));
        boolean isNotTarget = !(dx == 0 && dy == 0);

        if (isNotTarget && (isStraight || isDiagonal)) {
            Direction dir = new Direction(dx, dy);
            Piece currentClosest = closestPieces.get(dir);

            if (currentClosest == null || isCloser(piece, currentClosest, targetX, targetY)) {
                closestPieces.put(dir, piece);
            }
        }
    }

    /**
     * Compares two pieces to see which one is closer to the target.
     */
    private static boolean isCloser(Piece p1, Piece p2, int targetX, int targetY) {
        // Manhattan distance is sufficient for comparison when pieces are on the same line/diagonal
        int dist1 = Math.abs(p1.x - targetX) + Math.abs(p1.y - targetY);
        int dist2 = Math.abs(p2.x - targetX) + Math.abs(p2.y - targetY);
        return dist1 < dist2;
    }

    /**
     * Checks if the closest piece in any direction can attack the target square.
     */
    private static boolean isTargetUnderAttack(Map<Direction, Piece> closestPieces) {
        for (Map.Entry<Direction, Piece> entry : closestPieces.entrySet()) {
            Direction dir = entry.getKey();
            Piece piece = entry.getValue();

            if (dir.isDiagonal) {
                // Bishops and Queens attack diagonally
                if (piece.type == 'B' || piece.type == 'Q') {
                    return true;
                }
            } else {
                // Rooks and Queens attack straight lines (rows/columns)
                if (piece.type == 'R' || piece.type == 'Q') {
                    return true;
                }
            }
        }
        return false;
    }
}

