                isAttacked(sameX, king.y, p -> p.y, 'R', 'Q') ||
                // Check horizontal line (same Y) for Rooks/Queens
                isAttacked(sameY, king.x, p -> p.x, 'R', 'Q') ||
                // Check anti-diagonal (same sum) for Bishops/Queens
                isAttacked(sameSum, king.diff, p -> p.diff, 'B', 'Q') ||
                // Check main diagonal (same diff) for Bishops/Queens
                isAttacked(sameDiff, king.sum, p -> p.sum, 'B', 'Q');

            out.println(isUnderAttack ? YES : NO);
        }

        /**
         * Checks if any piece in a specific group is an attacker closest to the king's coordinate.
         * 
         * @param pieces The list of pieces on the same line.
         * @param targetCoord The coordinate of the king on that line.
         * @param coordExtractor Function to extract the relevant coordinate from a piece.
         * @param attackers The types of pieces that can attack on this line.
         * @return true if an attacker is found in the immediate vicinity of the king.
         */
        private boolean isAttacked(List<Piece> pieces, int targetCoord, 
                                   ToIntFunction<Piece> coordExtractor, 
                                   char... attackers) {
            if (pieces.isEmpty()) {
                return false;
            }

            // Sort pieces by their coordinate on this line
            pieces.sort(Comparator.comparingInt(coordExtractor));

            // Find the index of the largest coordinate <= targetCoord
            int index = -1;
            for (int i = 0; i < pieces.size(); i++) {
                if (coordExtractor.applyAsInt(pieces.get(i)) <= targetCoord) {
                    index = i;
                } else {
                    break;
                }
            }

            // Check the piece at 'index' and the piece at 'index + 1' (the two closest neighbors)
            for (int i = index; i <= index + 1; i++) {
                if (i >= 0 && i < pieces.size()) {
                    char type = pieces.get(i).type;
                    for (char attacker : attackers) {
                        if (type == attacker) {
                            return true;
                        }
                    }
                }
            }

            return false;
        }
    }

    /**
     * Fast I/O utility for reading input.
     */
    static class FastReader implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public char nextChar() throws IOException {
            return next().charAt(0);
        }

        @Override
        public void close() throws IOException {
            reader.close();
        }
