/**
 * Determines if any piece is positioned such that it can attack the center point (x0, y0)
 * without any other pieces blocking the line of sight.
 */
public class ChessAttackDetector {

    private static final char QUEEN = 'Q';
    private static final char ROOK = 'R';
    private static final char BISHOP = 'B';

    /**
     * Represents the 8 possible directions of attack on a chessboard.
     */
    enum Direction {
        NORTH(0, 1, false),
        SOUTH(0, -1, false),
        EAST(1, 0, false),
        WEST(-1, 0, false),
        NORTH_EAST(1, 1, true),
        NORTH_WEST(-1, 1, true),
        SOUTH_EAST(1, -1, true),
        SOUTH_WEST(-1, -1, true);

        private final int signX;
        private final int signY;
        private final boolean isDiagonal;

        Direction(int signX, int signY, boolean isDiagonal) {
            this.signX = signX;
            this.signY = signY;
            this.isDiagonal = isDiagonal;
        }

        /**
         * Maps a relative displacement (dx, dy) to a specific Direction.
         */
        public static Direction fromDelta(int dx, int dy) {
            int sx = Integer.compare(dx, 0);
            int sy = Integer.compare(dy, 0);

            for (Direction dir : values()) {
                if (dir.signX == sx && dir.signY == sy) {
                    return dir;
                }
            }
            return null;
        }
    }

    /**
     * Tracks the closest piece found in a specific direction.
     */
    static class PieceTracker {
        char pieceType = ' ';
        long minDistance = Long.MAX_VALUE;

        void update(char type, long distance) {
            if (distance < minDistance) {
                minDistance = distance;
                pieceType = type;
            }
        }

        boolean canAttack(boolean isDiagonal) {
            if (isDiagonal) {
                return pieceType == BISHOP || pieceType == QUEEN;
            } else {
                return pieceType == ROOK || pieceType == QUEEN;
            }
        }
    }

    public static void main(String[] args) throws IOException {
        FastReader reader = new FastReader(System.in);

        int n = reader.nextInt();
        int x0 = reader.nextInt();
        int y0 = reader.nextInt();

        // Use an EnumMap to store the closest piece found in each of the 8 directions
        Map<Direction, PieceTracker> trackers = new EnumMap<>(Direction.class);
        for (Direction dir : Direction.values()) {
            trackers.put(dir, new PieceTracker());
        }

        for (int i = 0; i < n; i++) {
            char pieceChar = reader.next().charAt(0);
            int x = reader.nextInt();
            int y = reader.nextInt();

            int dx = x - x0;
            int dy = y - y0;

            // A piece is relevant only if it's on the same row, column, or diagonal
            if (dx == 0 || dy == 0 || Math.abs(dx) == Math.abs(dy)) {
                Direction dir = Direction.fromDelta(dx, dy);
                if (dir != null) {
                    // Chebyshev distance works for both axial and diagonal steps in this context
                    long distance = Math.max(Math.abs(dx), Math.abs(dy));
                    trackers.get(dir).update(pieceChar, distance);
                }
            }
        }

        // Check if any of the closest pieces in any direction can attack the center
        boolean isAttacked = false;
        for (Map.Entry<Direction, PieceTracker> entry : trackers.entrySet()) {
            if (entry.getValue().canAttack(entry.getKey().isDiagonal)) {
                isAttacked = true;
                break;
            }
        }

        System.out.println(isAttacked ? "YES" : "NO");
    }

    /**
     * Fast I/O utility for efficient reading.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        public double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * PieceDetector determines if any piece of a certain type 
 * is the closest object in specific directions from a starting point.
 */
public class PieceDetector {

    private static final long INF = Long.MAX_VALUE;

    /**
     * Represents the eight directions (cardinal and diagonal) 
     * relative to a starting point.
     */
    private enum Direction {
        NORTH, SOUTH, EAST, WEST, // Cardinal
        NW, SE, SW, NE            // Diagonal
    }

    /**
     * Holds the state of the closest piece found in a specific direction.
     */
    private static class RayResult {
        long minDistance = INF;
        char pieceType = 'P';

        void update(long distance, char type) {
            if (distance < minDistance) {
                minDistance = distance;
                pieceType = type;
            }
        }
    }

    /**
     * Optimized scanner for faster input reading.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        public void close() throws IOException {
            br.close();
        }
    }

    /**
     * Main execution logic.
     */
    public void solve() throws IOException {
        FastScanner scanner = new FastScanner(System.in);

        int numPieces;
        try {
            numPieces = scanner.nextInt();
        } catch (Exception e) {
            return;
        }

        long startX = scanner.nextLong();
        long startY = scanner.nextLong();

        // Initialize results for all 8 possible directions
        RayResult[] rayResults = new RayResult[Direction.values().length];
        for (int i = 0; i < rayResults.length; i++) {
            rayResults[i] = new RayResult();
        }

        for (int i = 0; i < numPieces; i++) {
            char type = scanner.next().charAt(0);
            long x = scanner.nextLong();
            long y = scanner.nextLong();

            Direction dir = getDirection(x, y, startX, startY);
            if (dir != null) {
                long distance = calculateManhattanDistance(x, y, startX, startY);
                rayResults[dir.ordinal()].update(distance, type);
            }
        }

        System.out.println(checkWinningCondition(rayResults) ? "YES" : "NO");
        scanner.close();
    }

    /**
     * Determines which ray (if any) the given point lies on relative to the start.
     */
    private Direction getDirection(long x, long y, long sx, long sy) {
        if (x == sx) {
            return y > sy ? Direction.NORTH : Direction.SOUTH;
        }
        if (y == sy) {
            return x > sx ? Direction.EAST : Direction.WEST;
        }
        // Diagonal: Sum of coordinates is constant (Anti-diagonal)
        if (x + y == sx + sy) {
            return x < sx ? Direction.NW : Direction.SE;
        }
        // Diagonal: Difference of coordinates is constant (Main diagonal)
        if (x - y == sx - sy) {
            return x < sx ? Direction.SW : Direction.NE;
        }
        return null;
    }

    /**
     * Calculates distance using Manhattan metric (appropriate for these lines).
     */
    private long calculateManhattanDistance(long x, long y, long sx, long sy) {
        return Math.abs(x - sx) + Math.abs(y - sy);
    }

    /**
     * Evaluates if the closest pieces in any valid direction meet the criteria.
     */
    private boolean checkWinningCondition(RayResult[] rays) {
        // Check cardinal directions (NORTH, SOUTH, EAST, WEST)
        for (int i = 0; i < 4; i++) {
            char type = rays[i].pieceType;
            if (type == 'Q' || type == 'R') return true;
        }
        // Check diagonal directions (NW, SE, SW, NE)
        for (int i = 4; i < 8; i++) {
            char type = rays[i].pieceType;
            if (type == 'Q' || type == 'B') return true;
        }
        return false;
    }

    public static void main(String[] args) throws IOException {
        new PieceDetector().solve();
    }
}

import java.io.*;
