/**
 * Refactored solution for finding if any direction is controlled by 
 * a specific color (Red for axes, Blue for diagonals, or Queen for both).
 */
public class CF379Div2D {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        Solver solver = new Solver();
        solver.solve(reader, writer);

        writer.close();
    }

    static class Solver {
        /**
         * Represents the closest marker found in a specific direction.
         */
        static class DirectionMarker {
            char color = '?';
            int distance = Integer.MAX_VALUE;

            void update(char newColor, int newDistance) {
                this.color = newColor;
                this.distance = newDistance;
            }
        }

        /**
         * Utility to map dx, dy coordinates to one of the 8 directions.
         */
        static class DirectionMapper {
            // Direction mapping:
            // 0: Down (Axis), 1: Bottom-Right (Diag), 2: Right (Axis), 3: Top-Right (Diag),
            // 4: Up (Axis), 5: Top-Left (Diag), 6: Left (Axis), 7: Bottom-Left (Diag)
            public static int getDirectionIndex(int dx, int dy) {
                if (dx == 0 && dy < 0) return 0;
                if (dx == 0 && dy > 0) return 4;
                if (dy == 0 && dx < 0) return 6;
                if (dy == 0 && dx > 0) return 2;
                if (dx == -dy && dy < 0) return 1;
                if (dx == -dy && dy > 0) return 5;
                if (dx == dy && dx < 0) return 7;
                if (dx == dy && dx > 0) return 3;
                return -1;
            }
        }

        public void solve(FastReader in, PrintWriter out) {
            int n = in.nextInt();
            int centerX = in.nextInt();
            int centerY = in.nextInt();

            DirectionMarker[] markers = new DirectionMarker[8];
            for (int i = 0; i < 8; i++) {
                markers[i] = new DirectionMarker();
            }

            for (int i = 0; i < n; i++) {
                char color = in.nextChar();
                int targetX = in.nextInt();
                int targetY = in.nextInt();

                int dx = targetX - centerX;
                int dy = targetY - centerY;

                int dirIndex = DirectionMapper.getDirectionIndex(dx, dy);

                if (dirIndex != -1) {
                    // Chebyshev distance
                    int distance = Math.max(Math.abs(dx), Math.abs(dy));

                    // Update if it's the first marker in this direction or if it's closer
                    if (markers[dirIndex].color == '?' || distance < markers[dirIndex].distance) {
                        markers[dirIndex].update(color, distance);
                    }
                }
            }

            if (isWinningConditionMet(markers)) {
                out.print("YES");
            } else {
                out.print("NO");
            }
        }

        private boolean isWinningConditionMet(DirectionMarker[] markers) {
            for (int i = 0; i < 8; i++) {
                char c = markers[i].color;
                if (c == 'Q') return true;

                // Even indices (0, 2, 4, 6) are Axes: check for Red
                if (i % 2 == 0 && c == 'R') return true;

                // Odd indices (1, 3, 5, 7) are Diagonals: check for Blue
                if (i % 2 != 0 && c == 'B') return true;
            }
            return false;
        }
    }

    /**
     * Efficient input reader for competitive programming.
     */
    static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream input) {
            br = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public char nextChar() {
            return next().charAt(0);
        }
    }
}

