/**
 * Refactored solution for the point direction problem.
 * The program determines if any point in specific directions relative to an origin
 * satisfies color-based requirements.
 */
public class Main {

    public static void main(String[] args) {
        FastReader sc = new FastReader();

        int n = sc.nextInt();
        int originX = sc.nextInt();
        int originY = sc.nextInt();

        // Store only the closest point found for each of the 8 possible directions
        Point[] closestPoints = new Point[Direction.values().length];

        for (int i = 0; i < n; i++) {
            char type = sc.next().charAt(0);
            int targetX = sc.nextInt();
            int targetY = sc.nextInt();

            int dx = targetX - originX;
            int dy = targetY - originY;

            Direction dir = Direction.getDirection(dx, dy);
            if (dir != null) {
                // Manhattan distance is used as a metric for "closeness" along a ray
                int distance = Math.abs(dx) + Math.abs(dy);
                Point newPoint = new Point(targetX, targetY, type, distance);
                int dirIdx = dir.ordinal();

                if (closestPoints[dirIdx] == null || distance < closestPoints[dirIdx].distance) {
                    closestPoints[dirIdx] = newPoint;
                }
            }
        }

        boolean isPossible = checkWinningCondition(closestPoints);
        System.out.println(isPossible ? "YES" : "NO");
    }

    private static boolean checkWinningCondition(Point[] closestPoints) {
        for (int i = 0; i < closestPoints.length; i++) {
            Point p = closestPoints[i];
            if (p != null) {
                Direction dir = Direction.values()[i];
                if (dir.isWinningColor(p.type)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Represents a point with its coordinates, color type, and distance from origin.
     */
    static class Point {
        final int x, y;
        final char type;
        final int distance;

        Point(int x, int y, char type, int distance) {
            this.x = x;
            this.y = y;
            this.type = type;
            this.distance = distance;
        }
    }

    /**
     * Defines the 8 possible directions and the logic associated with each.
     */
    enum Direction {
        BOTTOM_LEFT(Kind.DIAGONAL),
        LEFT(Kind.CARDINAL),
        TOP_LEFT(Kind.DIAGONAL),
        BOTTOM(Kind.CARDINAL),
        TOP(Kind.CARDINAL),
        BOTTOM_RIGHT(Kind.DIAGONAL),
        RIGHT(Kind.CARDINAL),
        TOP_RIGHT(Kind.DIAGONAL);

        enum Kind { DIAGONAL, CARDINAL }

        private final Kind kind;

        Direction(Kind kind) {
            this.kind = kind;
        }

        /**
         * Identifies which direction a relative offset (dx, dy) belongs to.
         */
        static Direction getDirection(int dx, int dy) {
            boolean isDiagonal = Math.abs(dx) == Math.abs(dy);

            if (dx < 0 && dy < 0 && isDiagonal) return BOTTOM_LEFT;
            if (dx < 0 && dy == 0) return LEFT;
            if (dx < 0 && dy > 0 && isDiagonal) return TOP_LEFT;
            if (dx == 0 && dy < 0) return BOTTOM;
            if (dx == 0 && dy > 0) return TOP;
            if (dx > 0 && dy < 0 && isDiagonal) return BOTTOM_RIGHT;
            if (dx > 0 && dy == 0) return RIGHT;
            if (dx > 0 && dy > 0 && isDiagonal) return TOP_RIGHT;

            return null;
        }

        /**
         * Validates if the point's color is a "winning" color for this direction.
         */
        boolean isWinningColor(char type) {
            if (type == 'Q') return true; // 'Q' wins in any direction
            if (this.kind == Kind.DIAGONAL) {
                return type == 'B'; // Diagonals look for 'B'
            } else {
                return type == 'R'; // Cardinals look for 'R'
            }
        }
    }

    /**
     * Helper class for efficient input reading.
     */
    static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;

/**
 * A program to determine if a King is in check based on the positions 
 * of other chess pieces on a board.
 */
public class AntonChess {

    // Piece Type Constants
    private static final String QUEEN = "Q";
    private static final String ROOK = "R";
    private static final String BISHOP = "B";
    private static final String NONE = "none";

    /**
     * Represents the 8 possible directions a piece can attack from.
     */
    enum Direction {
        ORTHO_UP(0, -1, true),
        ORTHO_DOWN(0, 1, true),
        ORTHO_LEFT(-1, 0, true),
        ORTHO_RIGHT(1, 0, true),
        DIA_UP_LEFT(-1, -1, false),
        DIA_UP_RIGHT(1, -1, false),
        DIA_DOWN_LEFT(-1, 1, false),
        DIA_DOWN_RIGHT(1, 1, false);

        private final int dx;
        private final int dy;
        private final boolean isOrthogonal;

        Direction(int dx, int dy, boolean isOrthogonal) {
            this.dx = dx;
            this.dy = dy;
            this.isOrthogonal = isOrthogonal;
        }

        public boolean isOrthogonal() {
            return isOrthogonal;
        }
    }

    /**
     * Holds information about the closest piece found in a specific direction.
     */
    private static class ClosestPiece {
        String type = NONE;
        long distance = Long.MAX_VALUE;

        void updateIfCloser(String type, long distance) {
            if (distance < this.distance) {
                this.type = type;
                this.distance = distance;
            }
        }
    }

    /**
     * Manages the state of the chess board and checks for the King's status.
     */
    private static class ChessGame {
        private final long kingX;
        private final long kingY;
        private final Map<Direction, ClosestPiece> closestPiecesInDirections;

        public ChessGame(long kingX, long kingY) {
            this.kingX = kingX;
            this.kingY = kingY;
            this.closestPiecesInDirections = new EnumMap<>(Direction.class);
            for (Direction dir : Direction.values()) {
                closestPiecesInDirections.put(dir, new ClosestPiece());
            }
        }

        public void processPiece(String type, long pieceX, long pieceY) {
            long dx = pieceX - kingX;
            long dy = pieceY - kingY;

            // Check if the piece is on the same row, column, or diagonal
            boolean isOrthogonal = (dx == 0 || dy == 0);
            boolean isDiagonal = (Math.abs(dx) == Math.abs(dy));

            if (!isOrthogonal && !isDiagonal) {
                return;
            }

            Direction direction = determineDirection(dx, dy);
            if (direction != null) {
                long distance = Math.max(Math.abs(dx), Math.abs(dy));
                closestPiecesInDirections.get(direction).updateIfCloser(type, distance);
            }
        }

        private Direction determineDirection(long dx, long dy) {
            if (dx == 0) {
                return (dy < 0) ? Direction.ORTHO_UP : Direction.ORTHO_DOWN;
            } else if (dy == 0) {
                return (dx < 0) ? Direction.ORTHO_LEFT : Direction.ORTHO_RIGHT;
            } else {
                if (dx < 0 && dy < 0) return Direction.DIA_UP_LEFT;
                if (dx > 0 && dy < 0) return Direction.DIA_UP_RIGHT;
                if (dx < 0 && dy > 0) return Direction.DIA_DOWN_LEFT;
                if (dx > 0 && dy > 0) return Direction.DIA_DOWN_RIGHT;
            }
            return null;
        }

        public boolean isKingInCheck() {
            for (Map.Entry<Direction, ClosestPiece> entry : closestPiecesInDirections.entrySet()) {
                Direction dir = entry.getKey();
                String type = entry.getValue().type;

                if (dir.isOrthogonal()) {
                    if (type.equals(ROOK) || type.equals(QUEEN)) return true;
                } else {
                    if (type.equals(BISHOP) || type.equals(QUEEN)) return true;
                }
            }
            return false;
        }
    }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextLong()) return;

            long numPieces = scanner.nextLong();
            long kingX = scanner.nextLong();
            long kingY = scanner.nextLong();

            ChessGame game = new ChessGame(kingX, kingY);

            for (int i = 0; i < numPieces; i++) {
                String type = scanner.next();
                long pieceX = scanner.nextLong();
                long pieceY = scanner.nextLong();
                game.processPiece(type, pieceX, pieceY);
            }

            System.out.println(game.isKingInCheck() ? "YES" : "NO");
        }
    }
}

