/**
 * Refactored solution for the Codechef problem.
 * The program determines if there's a "gap" in the boundaries formed by different entity types.
 */
public class Codechef {

    public static void main(String[] args) {
        FastReader fr = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = fr.nextInt();
            int xk = fr.nextInt();
            int yk = fr.nextInt();

            BoundaryTracker tracker = new BoundaryTracker(xk, yk);

            for (int i = 0; i < n; i++) {
                char type = fr.nextChar();
                int x = fr.nextInt();
                int y = fr.nextInt();
                tracker.update(type, x, y);
            }

            out.println(tracker.hasGap() ? "YES" : "NO");

        } catch (Exception e) {
            // In competitive programming, we often swallow exceptions or handle them simply
        } finally {
            out.close();
        }
    }

    /**
     * Tracks the closest boundaries for different types of entities (Black, Red, and Queen)
     * across horizontal, vertical, and diagonal lines relative to a center point (xk, yk).
     */
    static class BoundaryTracker {
        private final int xk, yk;

        // Black-oriented boundaries
        private int blackLeftX = Integer.MIN_VALUE;
        private int blackRightX = Integer.MAX_VALUE;
        private int blackUpY = Integer.MAX_VALUE;
        private int blackDownY = Integer.MIN_VALUE;
        private int blackLeftDiagSumX = Integer.MIN_VALUE;
        private int blackRightDiagSumX = Integer.MAX_VALUE;
        private int blackLeftDiagDiffX = Integer.MIN_VALUE;
        private int blackRightDiagDiffX = Integer.MAX_VALUE;

        // Red/Queen-oriented boundaries
        private int redLeftX = Integer.MIN_VALUE;
        private int redRightX = Integer.MAX_VALUE;
        private int redUpY = Integer.MAX_VALUE;
        private int redDownY = Integer.MIN_VALUE;
        private int redLeftDiagSumX = Integer.MIN_VALUE;
        private int redRightDiagSumX = Integer.MAX_VALUE;
        private int redLeftDiagDiffX = Integer.MIN_VALUE;
        private int redRightDiagDiffX = Integer.MAX_VALUE;

        public BoundaryTracker(int xk, int yk) {
            this.xk = xk;
            this.yk = yk;
        }

        public void update(char type, int x, int y) {
            switch (type) {
                case 'B':
                    updateBlack(x, y);
                    break;
                case 'R':
                    updateRed(x, y);
                    break;
                case 'Q':
                    updateQueen(x, y);
                    break;
            }
        }

        private void updateBlack(int x, int y) {
            if (y == yk && x < xk) blackLeftX = Math.max(blackLeftX, x);
            else if (y == yk && x > xk) blackRightX = Math.min(blackRightX, x);
            else if (x + y == xk + yk && x < xk) blackLeftDiagSumX = Math.max(blackLeftDiagSumX, x);
            else if (x + y == xk + yk && x > xk) blackRightDiagSumX = Math.min(blackRightDiagSumX, x);
            else if (x - y == xk - yk && x < xk) blackLeftDiagDiffX = Math.max(blackLeftDiagDiffX, x);
            else if (x - y == xk - yk && x > xk) blackRightDiagDiffX = Math.min(blackRightDiagDiffX, x);
            else if (x == xk && y < yk) blackDownY = Math.max(blackDownY, y);
            else if (x == xk && y > yk) blackUpY = Math.min(blackUpY, y);
        }

        private void updateRed(int x, int y) {
            if (y == yk && x < xk) redLeftX = Math.max(redLeftX, x);
            else if (y == yk && x > xk) redRightX = Math.min(redRightX, x);
            else if (x + y == xk + yk && x < xk) redLeftDiagSumX = Math.max(redLeftDiagSumX, x);
            else if (x + y == xk + yk && x > xk) redRightDiagSumX = Math.min(redRightDiagSumX, x);
            else if (x - y == xk - yk && x < xk) redLeftDiagDiffX = Math.max(redLeftDiagDiffX, x);
            else if (x - y == xk - yk && x > xk) redRightDiagDiffX = Math.min(redRightDiagDiffX, x);
            else if (x == xk && y < yk) redDownY = Math.max(redDownY, y);
            else if (x == xk && y > yk) redUpY = Math.min(redUpY, y);
        }

        private void updateQueen(int x, int y) {
            // Queen affects both Red and Black boundary sets
            if (y == yk && x < xk) redLeftX = Math.max(redLeftX, x);
            else if (y == yk && x > xk) redRightX = Math.min(redRightX, x);
            else if (x == xk && y < yk) redDownY = Math.max(redDownY, y);
            else if (x == xk && y > yk) redUpY = Math.min(redUpY, y);
            else if (x + y == xk + yk && x < xk) blackLeftDiagSumX = Math.max(blackLeftDiagSumX, x);
            else if (x + y == xk + yk && x > xk) blackRightDiagSumX = Math.min(blackRightDiagSumX, x);
            else if (x - y == xk - yk && x < xk) blackLeftDiagDiffX = Math.max(blackLeftDiagDiffX, x);
            else if (x - y == xk - yk && x > xk) redRightDiagDiffX = Math.min(redRightDiagDiffX, x);
        }

        /**
         * Checks if any boundary has a gap between the Black and Red/Queen entities.
         */
        public boolean hasGap() {
            return blackLeftX < redLeftX ||
                   redRightX < blackRightX ||
                   redUpY < blackUpY ||
                   redDownY > blackDownY ||
                   blackLeftDiagSumX > redLeftDiagSumX ||
                   blackRightDiagSumX < redRightDiagSumX ||
                   blackLeftDiagDiffX > redLeftDiagDiffX ||
                   blackRightDiagDiffX < redRightDiagDiffX;
        }
    }

    /**
     * Utility class for fast input parsing.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public char nextChar() {
            return next().charAt(0);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.*;

/**
 * A program to determine if a King is in check in a chess-like game.
 * A King is in check if the closest piece in any of the 8 cardinal/ordinal
 * directions is an attacker (Rook/Queen for straight lines, Bishop/Queen for diagonals).
 */
public class Main {

    /**
     * Represents a normalized direction vector (e.g., (1, 0) for East).
     */
    private record Direction(int dx, int dy) {}

    /**
     * Represents a piece's metadata found in a specific direction.
     */
    private record PieceInfo(int distance, boolean isAttacker) {}

    public static void main(String[] args) {
        FastReader reader = new FastReader();

        int n = reader.nextInt();
        if (n < 0) return;

        int kingX = reader.nextInt();
        int kingY = reader.nextInt();

        // Maps each direction to a list of pieces located along that path.
        Map<Direction, List<PieceInfo>> directionMap = new HashMap<>();

        for (int i = 0; i < n; i++) {
            String typeStr = reader.next();
            if (typeStr == null) break;

            char type = typeStr.charAt(0);
            int x = reader.nextInt();
            int y = reader.nextInt();

            int deltaX = kingX - x;
            int deltaY = kingY - y;

            // Ignore pieces at the same position as the king
            if (deltaX == 0 && deltaY == 0) {
                continue;
            }

            // Only consider pieces that lie on one of the 8 valid chess directions
            if (isValidChessDirection(deltaX, deltaY)) {
                Direction dir = new Direction(
                    Integer.compare(deltaX, 0),
                    Integer.compare(deltaY, 0)
                );

                int distance = Math.max(Math.abs(deltaX), Math.abs(deltaY));
                boolean isAttacker = checkIsAttacker(type, dir.dx, dir.dy);

                directionMap.computeIfAbsent(dir, k -> new ArrayList<>())
                            .add(new PieceInfo(distance, isAttacker));
            }
        }

        boolean isKingInCheck = evaluateCheck(directionMap);
        System.out.println(isKingInCheck ? "YES" : "NO");
    }

    /**
     * Validates if the vector (dx, dy) is horizontal, vertical, or diagonal.
     */
    private static boolean isValidChessDirection(int dx, int dy) {
        return dx == 0 || dy == 0 || Math.abs(dx) == Math.abs(dy);
    }

    /**
     * Determines if a piece type can attack in a specific normalized direction.
     */
    private static boolean checkIsAttacker(char type, int dx, int dy) {
        boolean isDiagonal = (dx != 0 && dy != 0);
        if (isDiagonal) {
            return type == 'B' || type == 'Q';
        } else {
            return type == 'R' || type == 'Q';
        }
    }

    /**
     * Checks if any direction contains an attacker as the closest piece.
     * In chess, the closest piece in a line of sight blocks pieces behind it.
     */
    private static boolean evaluateCheck(Map<Direction, List<PieceInfo>> directionMap) {
        for (List<PieceInfo> candidates : directionMap.values()) {
            // Sort by distance to identify the piece closest to the king
            candidates.sort(Comparator.comparingInt(PieceInfo::distance));

            // If the closest piece in this direction is an attacker, the king is in check
            if (!candidates.isEmpty() && candidates.get(0).isAttacker()) {
                return true;
            }
        }
        return false;
    }

    /**
     * Fast I/O utility for high-performance input reading.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader() {
            reader = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            return next == null ? -1 : Integer.parseInt(next);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to determine if any piece on a chessboard can attack a specific origin point.
 * The logic assumes pieces can only attack the origin if they are the closest piece 
 * in their respective line of sight (cardinal or diagonal).
 */
public class Main {
    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        ChessAttackSolver solver = new ChessAttackSolver();
        solver.solve(reader, writer);

        writer.close();
    }

    /**
     * Represents the type of chess piece.
     */
    enum PieceType {
        QUEEN('Q'),
        BISHOP('B'),
        ROOK('R'),
        UNKNOWN('\0');

        private final char symbol;

        PieceType(char symbol) {
            this.symbol = symbol;
        }

        public static PieceType fromChar(char c) {
            for (PieceType type : values()) {
                if (type.symbol == c) return type;
            }
            return UNKNOWN;
        }
    }

    /**
     * Represents the 8 possible directions of movement (cardinal and diagonal).
     */
    enum Direction {
        NORTH(0, 1, false),
        NORTH_EAST(1, 1, true),
        EAST(1, 0, false),
        SOUTH_EAST(1, -1, true),
        SOUTH(0, -1, false),
        SOUTH_WEST(-1, -1, true),
        WEST(-1, 0, false),
        NORTH_WEST(-1, 1, true);

        private final int dx;
        private final int dy;
        private final boolean isDiagonal;

        Direction(int dx, int dy, boolean isDiagonal) {
            this.dx = dx;
            this.dy = dy;
            this.isDiagonal = isDiagonal;
        }

        /**
         * Maps relative coordinates to a Direction.
         * @param dx relative x-offset
         * @param dy relative y-offset
         * @return The Direction, or null if the offsets do not form a valid direction.
         */
        public static Direction fromOffsets(int dx, int dy) {
            if (dx == 0 && dy > 0) return NORTH;
            if (dx > 0 && dy > 0 && dx == dy) return NORTH_EAST;
            if (dx > 0 && dy == 0) return EAST;
            if (dx > 0 && dy < 0 && dx == -dy) return SOUTH_EAST;
            if (dx == 0 && dy < 0) return SOUTH;
            if (dx < 0 && dy < 0 && dx == dy) return SOUTH_WEST;
            if (dx < 0 && dy == 0) return WEST;
            if (dx < 0 && dy > 0 && -dx == dy) return NORTH_WEST;
            return null;
        }
    }

    /**
     * Represents a chess piece with its properties and distance from origin.
     */
    record Piece(PieceType type, int distance) {}

    /**
     * Core logic for solving the chess attack problem.
     */
    static class ChessAttackSolver {

        public void solve(FastReader reader, PrintWriter writer) {
            int pieceCount = reader.nextInt();
            int originX = reader.nextInt();
            int originY = reader.nextInt();

            // Map to store the closest piece found in each direction
            Map<Direction, Piece> closestPiecesInDirections = new EnumMap<>(Direction.class);

            for (int i = 0; i < pieceCount; i++) {
                PieceType type = PieceType.fromChar(reader.next().charAt(0));
                int x = reader.nextInt();
                int y = reader.nextInt();

                int relX = x - originX;
                int relY = y - originY;

                Direction direction = Direction.fromOffsets(relX, relY);

                if (direction != null) {
                    // Using Chebyshev distance as per original implementation
                    int distance = Math.max(Math.abs(relX), Math.abs(relY));
                    updateClosestPiece(closestPiecesInDirections, direction, new Piece(type, distance));
                }
            }

            if (canAnyPieceAttack(closestPiecesInDirections)) {
                writer.println("YES");
            } else {
                writer.println("NO");
            }
        }

        private void updateClosestPiece(Map<Direction, Piece> map, Direction dir, Piece newPiece) {
            if (!map.containsKey(dir) || newPiece.distance() < map.get(dir).distance()) {
                map.put(dir, newPiece);
            }
        }

        private boolean canAnyPieceAttack(Map<Direction, Piece> closestPieces) {
            for (Map.Entry<Direction, Piece> entry : closestPieces.entrySet()) {
                Direction dir = entry.getKey();
                Piece piece = entry.getValue();

                if (isAttacking(piece.type(), dir)) {
                    return true;
                }
            }
            return false;
        }

        private boolean isAttacking(PieceType type, Direction dir) {
            return switch (type) {
                case QUEEN -> true;
                case BISHOP -> dir.isDiagonal;
                case ROOK -> !dir.isDiagonal;
                default -> false;
            };
        }
    }

    /**
     * Utility class for fast input reading.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            this.reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            return next != null ? Integer.parseInt(next) : 0;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Represents the coordinates on a 2D grid.
 */
record Position(int x, int y) {
    public int distanceTo(Position other) {
        // Using Chebyshev distance as it is sufficient for finding the closest piece 
        // on a cardinal/ordinal line.
        return Math.max(Math.abs(this.x - other.x), Math.abs(this.y - other.y));
    }
}

/**
 * Represents the type of chess piece.
 */
enum PieceType {
    QUEEN('Q'),
    ROOK('R'),
    BISHOP('B'),
    UNKNOWN('X');

    private final char symbol;

    PieceType(char symbol) {
        this.symbol = symbol;
    }

    public static PieceType fromChar(char c) {
        return switch (c) {
            case 'Q' -> QUEEN;
            case 'R' -> ROOK;
            case 'B' -> BISHOP;
            default -> UNKNOWN;
        };
    }

    /**
     * Determines if this piece type can attack in a given direction.
     */
    public boolean canAttack(Direction direction) {
        return switch (this) {
            case QUEEN -> true;
            case ROOK -> direction.isCardinal();
            case BISHOP -> direction.isDiagonal();
            default -> false;
        };
    }
}

/**
 * Represents the 8 possible directions of movement on a chess board.
 */
enum Direction {
    EAST(1, 0, true),
    NORTH_EAST(1, 1, false),
    NORTH(0, 1, true),
    NORTH_WEST(-1, 1, false),
    WEST(-1, 0, true),
    SOUTH_WEST(-1, -1, false),
    SOUTH(0, -1, true),
    SOUTH_EAST(1, -1, false);

    private final int dx;
    private final int dy;
    private final boolean cardinal;

    private static final Direction[][] DIRECTION_MAP = new Direction[3][3];

    static {
        for (Direction d : Direction.values()) {
            DIRECTION_MAP[d.dx + 1][d.dy + 1] = d;
        }
    }

    Direction(int dx, int dy, boolean cardinal) {
        this.dx = dx;
        this.dy = dy;
        this.cardinal = cardinal;
    }

    public boolean isCardinal() {
        return cardinal;
    }

    public boolean isDiagonal() {
        return !cardinal;
    }

    /**
     * Maps the relative movement (dx, dy) to a Direction enum.
     * Returns null if the movement is not a valid cardinal or diagonal direction.
     */
    public static Direction fromDelta(int dx, int dy) {
        int signX = Integer.compare(dx, 0);
        int signY = Integer.compare(dy, 0);
        return DIRECTION_MAP[signX + 1][signY + 1];
    }
}

/**
 * Represents a chess piece on the board.
 */
record Piece(PieceType type, Position position) {}

/**
 * Contains the logic to determine if the king is in check.
 */
class ChessChecker {

    public boolean isKingInCheck(Position kingPos, Piece[] pieces) {
        // Tracks the closest piece found in each of the 8 directions
        Piece[] closestPieces = new Piece[Direction.values().length];

        for (Piece piece : pieces) {
            int dx = piece.position().x() - kingPos.x();
            int dy = piece.position().y() - kingPos.y();

            // Skip if the piece is at the same position as the king
            if (dx == 0 && dy == 0) continue;

            Direction dir = Direction.fromDelta(dx, dy);
            if (dir != null) {
                updateClosestPiece(closestPieces, dir, piece, kingPos);
            }
        }

        return isAnyClosestPieceAttacking(closestPieces);
    }

    private void updateClosestPiece(Piece[] closestPieces, Direction dir, Piece newPiece, Position kingPos) {
        int dirIdx = dir.ordinal();
        if (closestPieces[dirIdx] == null || 
            newPiece.position().distanceTo(kingPos) < closestPieces[dirIdx].position().distanceTo(kingPos)) {
            closestPieces[dirIdx] = newPiece;
        }
    }

    private boolean isAnyClosestPieceAttacking(Piece[] closestPieces) {
        for (int i = 0; i < closestPieces.length; i++) {
            Piece piece = closestPieces[i];
            if (piece != null) {
                Direction dir = Direction.values()[i];
                if (piece.type().canAttack(dir)) {
                    return true;
                }
            }
        }
        return false;
    }
}

