public class ChessCheck {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        try {
            int numPieces = reader.nextInt();
            int kingX = reader.nextInt();
            int kingY = reader.nextInt();
            Position kingPos = new Position(kingX, kingY);

            Piece[] pieces = new Piece[numPieces];
            for (int i = 0; i < numPieces; i++) {
                char typeChar = reader.next().charAt(0);
                int px = reader.nextInt();
                int py = reader.nextInt();
                pieces[i] = new Piece(PieceType.fromChar(typeChar), new Position(px, py));
            }

            ChessChecker checker = new ChessChecker();
            if (checker.isKingInCheck(kingPos, pieces)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        } catch (Exception e) {
            // In a production environment, use proper logging
            System.err.println("An error occurred during processing: " + e.getMessage());
        }
    }
}

import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

/**
 * A refactored program to determine if a King is in check in a chess-like environment.
 */
public class ChessCheck {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        // Input Parsing
        int pieceCount = scanner.nextInt();
        int kingX = scanner.nextInt();
        int kingY = scanner.nextInt();

        ChessEngine engine = new ChessEngine(kingX, kingY);

        for (int i = 0; i < pieceCount; i++) {
            char typeChar = scanner.next().charAt(0);
            int px = scanner.nextInt();
            int py = scanner.nextInt();
            engine.processPiece(typeChar, px, py);
        }

        // Output Result
        if (engine.isKingInCheck()) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }
}

/**
 * Represents the movement capabilities of different piece types.
 */
enum PieceType {
    QUEEN, ROOK, BISHOP;

    public static PieceType fromChar(char c) {
        return switch (c) {
            case 'Q' -> QUEEN;
            case 'R' -> ROOK;
            case 'B' -> BISHOP;
            default -> throw new IllegalArgumentException("Invalid piece type: " + c);
        };
    }
}

/**
 * Represents a normalized direction vector on the chessboard.
 */
record Direction(int dx, int dy) {
    /**
     * Returns true if the direction is strictly horizontal or vertical.
     */
    public boolean isCardinal() {
        return (dx != 0 && dy == 0) || (dx == 0 && dy != 0);
    }

    /**
     * Returns true if the direction is strictly diagonal.
     */
    public boolean isDiagonal() {
        return Math.abs(dx) == 1 && Math.abs(dy) == 1;
    }

    /**
     * Calculates the normalized direction vector from one point to another.
     */
    public static Direction fromCoordinates(int fromX, int fromY, int toX, int toY) {
        int dx = Integer.compare(toX, fromX);
        int dy = Integer.compare(toY, fromY);
        return new Direction(dx, dy);
    }
}

/**
 * Represents a chess piece with its type and position.
 */
record Piece(PieceType type, int x, int y) {
    public double distanceTo(int targetX, int targetY) {
        return Math.sqrt(Math.pow(x - targetX, 2) + Math.pow(y - targetY, 2));
    }
}

/**
 * Core logic engine that tracks the closest pieces relative to the King.
 */
class ChessEngine {
    private final int kingX;
    private final int kingY;
    // Maps a direction to the closest piece found in that direction.
    private final Map<Direction, Piece> closestPiecesPerDirection = new HashMap<>();

    public ChessEngine(int kingX, int kingY) {
        this.kingX = kingX;
        this.kingY = kingY;
    }

    /**
     * Processes a piece and updates the closest piece tracking if the piece is on a valid line of sight.
     */
    public void processPiece(char typeChar, int px, int py) {
        int dx = px - kingX;
        int dy = py - kingY;

        // A piece can only check the king if it is on the same row, column, or diagonal.
        if (isLineOfSight(dx, dy)) {
            Direction dir = Direction.fromCoordinates(kingX, kingY, px, py);

            // Avoid processing if the piece is on the same coordinate as the king.
            if (dir.dx() == 0 && dir.dy() == 0) {
                return;
            }

            Piece piece = new Piece(PieceType.fromChar(typeChar), px, py);

            // We only care about the piece closest to the King in this specific direction.
            if (isCloserThanExisting(dir, piece)) {
                closestPiecesPerDirection.put(dir, piece);
            }
        }
    }

    private boolean isLineOfSight(int dx, int dy) {
        return dx == 0 || dy == 0 || Math.abs(dx) == Math.abs(dy);
    }

    private boolean isCloserThanExisting(Direction dir, Piece newPiece) {
        if (!closestPiecesPerDirection.containsKey(dir)) {
            return true;
        }
        return newPiece.distanceTo(kingX, kingY) < 
               closestPiecesPerDirection.get(dir).distanceTo(kingX, kingY);
    }

    /**
     * Evaluates if any of the closest pieces in any direction results in a check.
     */
    public boolean isKingInCheck() {
        for (Map.Entry<Direction, Piece> entry : closestPiecesPerDirection.entrySet()) {
            Direction dir = entry.getKey();
            Piece piece = entry.getValue();

            if (piece.type() == PieceType.QUEEN) {
                return true;
            } 
            if (piece.type() == PieceType.ROOK && dir.isCardinal()) {
                return true;
            } 
            if (piece.type() == PieceType.BISHOP && dir.isDiagonal()) {
                return true;
            }
        }
        return false;
    }
}

import java.io.*;
import java.util.*;

/**
 * Solution for determining if specific geometric conditions are met by a set of figures.
 */
public class Solution {

    private static final char COLOR_BLUE = 'B';
    private static final char COLOR_RED = 'R';

    public static void main(String[] args) {
        try {
            new Solution().run();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /**
     * Initializes the input and output streams and executes the solver.
     */
    public void run() throws IOException {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));

        try {
            solve(reader, out);
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Core logic of the program.
     */
    private void solve(FastReader reader, PrintWriter out) throws IOException {
        int n = reader.nextInt();
        long originX = reader.nextLong();
        long originY = reader.nextLong();

        Figure[] figures = new Figure[n];
        for (int i = 0; i < n; i++) {
            char color = reader.next().charAt(0);
            int x = reader.nextInt();
            int y = reader.nextInt();
            // Manhattan distance calculation with long promotion to prevent overflow
            long distance = Math.abs((long) x - originX) + Math.abs((long) y - originY);
            figures[i] = new Figure(color, x, y, distance);
        }

        // Sort figures by distance ascending
        Arrays.sort(figures);

        long occupiedDirectionsMask = 0;

        for (Figure figure : figures) {
            int x = figure.x;
            int y = figure.y;

            long directionMask = getDirectionMask(x, y, originX, originY);
            if (directionMask == 0) {
                continue;
            }

            // If this specific sector or axis is already marked as "visited" by a previous figure, skip
            if ((occupiedDirectionsMask & directionMask) != 0) {
                continue;
            }

            boolean isOnAxis = (x == originX || y == originY);
            boolean isOnDiagonal = Math.abs((long) x - originX) == Math.abs((long) y - originY);

            // Mark this direction as occupied if the figure lies on an axis or diagonal
            if (isOnAxis || isOnDiagonal) {
                occupiedDirectionsMask |= directionMask;
            }

            // Condition 1: Any non-blue figure on the axis returns YES
            if (figure.color != COLOR_BLUE && isOnAxis) {
                out.println("YES");
                return;
            }

            // Condition 2: Any non-red figure on the diagonal returns YES
            if (figure.color != COLOR_RED && isOnDiagonal) {
                out.println("YES");
                return;
            }
        }

        out.println("NO");
    }

    /**
     * Maps the geometric direction of a point relative to an origin into a bitmask.
     * This preserves the original bitmask logic for consistent behavior.
     */
    private long getDirectionMask(int x, int y, long originX, long originY) {
        int xDir = 0; // 1 if x > originX, 2 if x < originX
        if (x > originX) xDir = 1;
        else if (x < originX) xDir = 2;

        int yDir = 0; // 3 if y > originY, 4 if y < originY
        if (y > originY) yDir = 3;
        else if (y < originY) yDir = 4;

        if (xDir == 0 && yDir == 0) {
            return 0;
        }

        if (xDir != 0 && yDir != 0) {
            // Quadrant logic
            int quadrant;
            if (xDir == 1) { // x > originX
                quadrant = (yDir == 3) ? 5 : 6;
            } else { // x < originX
                quadrant = (yDir == 3) ? 7 : 8;
            }
            return 1L << quadrant;
        } else {
            // Axial direction logic
            int axisIndex;
            if (xDir != 0) {
                axisIndex = xDir; // 1 or 2
            } else {
                axisIndex = yDir; // 3 or 4
            }
            return 1L << (axisIndex - 1);
        }
    }

    /**
     * Represents a single figure with its properties.
     */
    private static class Figure implements Comparable<Figure> {
        final char color;
        final int x;
        final int y;
        final long distance;

        Figure(char color, int x, int y, long distance) {
            this.color = color;
            this.x = x;
            this.y = y;
            this.distance = distance;
        }

        @Override
        public int compareTo(Figure other) {
            return Long.compare(this.distance, other.distance);
        }
    }

    /**
     * Fast I/O utility class.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for identifying if forbidden characters appear
 * at the closest points in specific directions from a starting coordinate.
 */
public class Main {

    public static void main(String[] args) {
        InputStream inputStream = System.in;

        // Handle development testing mode via command line arguments
        if (args.length >= 2 && "devTesting".equals(args[0])) {
            try {
                inputStream = new FileInputStream(args[1]);
            } catch (FileNotFoundException e) {
                System.err.println("Error: Test file not found: " + args[1]);
                return;
            }
        }

        try (FastReader reader = new FastReader(inputStream);
             PrintWriter out = new PrintWriter(System.out)) {

            ProblemSolver solver = new ProblemSolver();
            solver.solve(reader, out);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * Represents the 8 specific rays/directions from the origin point.
     * Encapsulates the index and the forbidden characters for each direction.
     */
    enum Direction {
        RIGHT(0, 'Q', 'R'),
        TOP_RIGHT(1, 'B', 'Q'),
        UP(2, 'Q', 'R'),
        TOP_LEFT(3, 'B', 'Q'),
        LEFT(4, 'Q', 'R'),
        BOTTOM_LEFT(5, 'B', 'Q'),
        DOWN(6, 'Q', 'R'),
        BOTTOM_RIGHT(7, 'B', 'Q');

        final int index;
        final char forbidden1;
        final char forbidden2;

        Direction(int index, char forbidden1, char forbidden2) {
            this.index = index;
            this.forbidden1 = forbidden1;
            this.forbidden2 = forbidden2;
        }

        /**
         * Determines the direction index based on the relative displacement (dx, dy).
         * @return The corresponding Direction enum, or null if the point is not on a valid ray.
         */
        static Direction fromDelta(long dx, long dy) {
            if (dx > 0 && dy == 0) return RIGHT;
            if (dx > 0 && dx == dy) return TOP_RIGHT;
            if (dx == 0 && dy > 0) return UP;
            if (dx < 0 && dx == -dy) return TOP_LEFT;
            if (dx < 0 && dy == 0) return LEFT;
            if (dx < 0 && dx == dy) return BOTTOM_LEFT;
            if (dx == 0 && dy < 0) return DOWN;
            if (dx > 0 && dx == -dy) return BOTTOM_RIGHT;
            return null;
        }

        boolean isForbidden(char c) {
            return c == forbidden1 || c == forbidden2;
        }
    }

    /**
     * Contains the core logic for processing the points and solving the task.
     */
    static class ProblemSolver {

        public void solve(FastReader in, PrintWriter out) {
            int n = in.nextInt();
            long x0 = in.nextLong();
            long y0 = in.nextLong();

            // Track the minimum distance and the character found for each of the 8 directions
            long[] minDistances = new long[8];
            Arrays.fill(minDistances, Long.MAX_VALUE);
            char[] closestChars = new char[8];

            for (int i = 0; i < n; i++) {
                char ch = in.next().charAt(0);
                long xi = in.nextLong();
                long yi = in.nextLong();

                long dx = xi - x0;
                long dy = yi - y0;

                Direction dir = Direction.fromDelta(dx, dy);
                if (dir != null) {
                    // Distance is the magnitude of the non-zero displacement
                    long distance = Math.max(Math.abs(dx), Math.abs(dy));
                    if (distance < minDistances[dir.index]) {
                        minDistances[dir.index] = distance;
                        closestChars[dir.index] = ch;
                    }
                }
            }

            boolean foundForbidden = false;
            for (int i = 0; i < 8; i++) {
                Direction dir = Direction.values()[i];
                if (dir.isForbidden(closestChars[i])) {
                    foundForbidden = true;
                    break;
                }
            }

            // The original logic: print "YES" if forbidden characters are found, otherwise "NO"
            out.println(foundForbidden ? "YES" : "NO");
        }
    }

    /**
     * High-performance input reader.
     */
    static class FastReader implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        @Override
        public void close() throws IOException {
            reader.close();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.EnumMap;
import java.util.Map;
import java.util.Optional;
import java.util.StringTokenizer;

/**
 * Represents the type of chess piece and its movement capabilities.
 */
enum PieceType {
    QUEEN, ROOK, BISHOP, KING;

    /**
     * Maps a character representation to a PieceType.
     */
    public static PieceType fromChar(char c) {
        return switch (c) {
            case 'Q' -> QUEEN;
            case 'R' -> ROOK;
            case 'B' -> BISHOP;
            case 'K' -> KING;
            default -> throw new IllegalArgumentException("Unknown piece type: " + c);
        };
    }

    /**
     * Determines if this piece type can attack in the given direction.
     */
    public boolean canAttack(Direction direction) {
        return switch (this) {
            case QUEEN -> true;
            case ROOK -> direction.isOrthogonal();
            case BISHOP -> direction.isDiagonal();
            case KING -> false; // In this context, we check long-range attackers
        };
    }
}

/**
 * Represents the 8 possible directions on a chessboard.
 */
enum Direction {
    NORTH(0, 1),
    NORTH_EAST(1, 1),
    EAST(1, 0),
    SOUTH_EAST(1, -1),
    SOUTH(0, -1),
    SOUTH_WEST(-1, -1),
    WEST(-1, 0),
    NORTH_WEST(-1, 1);

    private final int dx;
    private final int dy;

    Direction(int dx, int dy) {
        this.dx = dx;
        this.dy = dy;
    }

    public boolean isOrthogonal() {
        return dx == 0 || dy == 0;
    }

    public boolean isDiagonal() {
        return Math.abs(dx) == Math.abs(dy);
    }

    /**
     * Maps coordinate deltas to a Direction enum.
     */
    public static Optional<Direction> fromOffsets(int dx, int dy) {
        int stepX = Integer.compare(dx, 0);
        int stepY = Integer.compare(dy, 0);

        for (Direction dir : values()) {
            if (dir.dx == stepX && dir.dy == stepY) {
                return Optional.of(dir);
            }
        }
        return Optional.empty();
    }
}

/**
 * Represents a piece on the board.
 */
class Piece {
    private final int x;
    private final int y;
    private final PieceType type;

    public Piece(int x, int y, PieceType type) {
        this.x = x;
        this.y = y;
        this.type = type;
    }

    public int getX() { return x; }
    public int getY() { return y; }
    public PieceType getType() { return type; }

    public long getManhattanDistance(Piece other) {
        return (long) Math.abs(this.x - other.x) + Math.abs(this.y - other.y);
    }

    public Optional<Direction> getDirectionTo(Piece other) {
        return Direction.fromOffsets(other.x - this.x, other.y - this.y);
    }
}

/**
 * Logic engine to determine if the King is under attack.
 */
class ChessEngine {

    public boolean isKingInCheck(Piece king, Piece[] otherPieces) {
        // Maps each direction to the nearest piece found so far
        Map<Direction, Piece> nearestPieces = new EnumMap<>(Direction.class);
        Map<Direction, Long> nearestDistances = new EnumMap<>(Direction.class);

        for (Piece piece : otherPieces) {
            Optional<Direction> directionOpt = king.getDirectionTo(piece);

            if (directionOpt.isPresent()) {
                Direction dir = directionOpt.get();
                long distance = king.getManhattanDistance(piece);

                if (!nearestDistances.containsKey(dir) || distance < nearestDistances.get(dir)) {
                    nearestDistances.put(dir, distance);
                    nearestPieces.put(dir, piece);
                }
            }
        }

        // Check if any of the nearest pieces in any direction can attack the king
        return nearestPieces.entrySet().stream().anyMatch(entry -> {
            Direction dir = entry.getKey();
            Piece nearest = entry.getValue();
            return nearest.getType().canAttack(dir);
        });
    }
}

public class Main {
    public static void main(String[] args) {
        try {
            FastReader reader = new FastReader();
            int numOfPieces = reader.nextInt();

            // King input: X Y K
            int kingX = reader.nextInt();
            int kingY = reader.nextInt();
            reader.next(); // consume 'K'
            Piece king = new Piece(kingX, kingY, PieceType.KING);

            Piece[] otherPieces = new Piece[numOfPieces];
            for (int i = 0; i < numOfPieces; i++) {
                // Piece input: Type X Y
                char typeChar = reader.next().charAt(0);
                int px = reader.nextInt();
                int py = reader.nextInt();
                otherPieces[i] = new Piece(px, py, PieceType.fromChar(typeChar));
            }

            ChessEngine engine = new ChessEngine();
            boolean isCheck = engine.isKingInCheck(king, otherPieces);

            System.out.println(isCheck ? "YES" : "NO");

        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Helper class for efficient input reading.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;
import java.util.function.Predicate;
import java.util.function.ToIntFunction;

/**
 * Main class to entry the program.
 */
public class Main {
    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        TaskSolver solver = new TaskSolver();
        solver.solve(in, out);

        out.close();
    }

    /**
     * Represents a point in a 2D coordinate system with a specific type.
     */
    static class Point {
        final char type;
        final int x;
        final int y;

        Point(char type, int x, int y) {
            this.type = type;
            this.x = x;
            this.y = y;
        }
    }

    /**
     * Contains the logic for solving the specific task.
     */
    static class TaskSolver {

        public void solve(InputReader in, PrintWriter out) {
            final int n = in.nextInt();
            final int startX = in.nextInt();
            final int startY = in.nextInt();

            Point[] points = new Point[n];
            for (int i = 0; i < n; i++) {
                points[i] = new Point(in.next().charAt(0), in.nextInt(), in.nextInt());
            }

            // Define type predicates for different movement modes
            Predicate<Character> orthogonalTypeAllowed = t -> t == 'R' || t == 'Q';
            Predicate<Character> diagonalTypeAllowed = t -> t == 'B' || t == 'Q';

            // 1. Check Vertical Line (x is constant)
            boolean found = isReachable(points, 
                    p -> p.x == startX, 
                    p -> p.y, 
                    startY, 
                    orthogonalTypeAllowed);

            // 2. Check Horizontal Line (y is constant)
            if (!found) {
                found = isReachable(points, 
                        p -> p.y == startY, 
                        p -> p.x, 
                        startX, 
                        orthogonalTypeAllowed);
            }

            // 3. Check Diagonal Line (y - x is constant)
            if (!found) {
                found = isReachable(points, 
                        p -> (p.y - p.x) == (startY - startX), 
                        p -> p.x, 
                        startX, 
                        diagonalTypeAllowed);
            }

            // 4. Check Anti-Diagonal Line (y + x is constant)
            if (!found) {
                found = isReachable(points, 
                        p -> (p.y + p.x) == (startY + startX), 
                        p -> p.x, 
                        startX, 
                        diagonalTypeAllowed);
            }

            out.println(found ? "YES" : "NO");
        }

        /**
         * Searches for the closest point on a specific line in both directions.
         * 
         * @param pts              The array of points to search through.
         * @param onLine           Predicate to determine if a point lies on the target line.
         * @param coordExtractor   Function to extract the relevant coordinate (x or y) for distance comparison.
         * @param targetCoord      The coordinate value of the starting point on the extracted axis.
         * @param typePredicate    Predicate to check if the found point's type is valid for this direction.
         * @return true if a valid point is found, false otherwise.
         */
        private boolean isReachable(Point[] pts, 
                                    Predicate<Point> onLine, 
                                    ToIntFunction<Point> coordExtractor, 
                                    int targetCoord, 
                                    Predicate<Character> typePredicate) {

            Point closestAbove = null;
            Point closestBelowOrAt = null;

            for (Point p : pts) {
                if (onLine.test(p)) {
                    int val = coordExtractor.applyAsInt(p);

                    if (val > targetCoord) {
                        // Find the smallest value that is greater than the target
                        if (closestAbove == null || val < coordExtractor.applyAsInt(closestAbove)) {
                            closestAbove = p;
                        }
                    } else {
                        // Find the largest value that is less than or equal to the target
                        if (closestBelowOrAt == null || val > coordExtractor.applyAsInt(closestBelowOrAt)) {
                            closestBelowOrAt = p;
                        }
                    }
                }
            }

            boolean aboveValid = closestAbove != null && typePredicate.test(closestAbove.type);
            boolean belowValid = closestBelowOrAt != null && typePredicate.test(closestBelowOrAt.type);

            return aboveValid || belowValid;
        }
    }

    /**
     * Fast I/O reader for efficient input processing.
     */
    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

/**
 * A program to determine if a central point can "see" specific types of targets 
 * in cardinal or diagonal directions based on proximity.
 */
public class TargetDirectionFinder {

    private static final long INF = Long.MAX_VALUE;

    // Directional Indices
    private static final int DOWN = 0;
    private static final int LEFT = 1;
    private static final int RIGHT = 2;
    private static final int UP = 3;
    private static final int DOWN_RIGHT = 4;
    private static final int UP_RIGHT = 5;
    private static final int UP_LEFT = 6;
    private static final int DOWN_LEFT = 7;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextLong()) {
            return;
        }

        long numTargets = scanner.nextLong();
        long centerX = scanner.nextLong();
        long centerY = scanner.nextLong();

        // Arrays to store the closest target information for each of the 8 directions
        String[] closestTypes = new String[8];
        long[] minDistances = new long[8];

        // Initialize tracking arrays
        for (int i = 0; i < 8; i++) {
            minDistances[i] = INF;
            closestTypes[i] = "*"; // Placeholder for no target found
        }

        for (int i = 0; i < numTargets; i++) {
            String type = scanner.next();
            long targetX = scanner.nextLong();
            long targetY = scanner.nextLong();

            processTarget(centerX, centerY, targetX, targetY, type, minDistances, closestTypes);
        }

        if (isMatchFound(closestTypes)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Determines the direction of a target relative to the center and updates 
     * the closest target trackers if the new target is nearer.
     */
    private static void processTarget(long cx, long cy, long tx, long ty, String type, 
                                      long[] minDistances, String[] closestTypes) {
        long dx = tx - cx;
        long dy = ty - cy;

        int direction = -1;
        long distance = 0;

        // Check for Cardinal Directions (Vertical or Horizontal)
        if (dx == 0 && dy != 0) {
            direction = (dy > 0) ? UP : DOWN;
            distance = Math.abs(dy);
        } else if (dy == 0 && dx != 0) {
            direction = (dx > 0) ? RIGHT : LEFT;
            distance = Math.abs(dx);
        } 
        // Check for Diagonal Directions
        else if (Math.abs(dx) == Math.abs(dy)) {
            if (dx > 0 && dy < 0) {
                direction = DOWN_RIGHT;
            } else if (dx > 0 && dy > 0) {
                direction = UP_RIGHT;
            } else if (dx < 0 && dy > 0) {
                direction = UP_LEFT;
            } else if (dx < 0 && dy < 0) {
                direction = DOWN_LEFT;
            }
            distance = Math.abs(dx);
        }

        // If target is in a valid direction and is the closest one seen so far
        if (direction != -1 && distance < minDistances[direction]) {
            minDistances[direction] = distance;
            closestTypes[direction] = type;
        }
    }

    /**
     * Evaluates if any of the closest targets meet the search criteria.
     * Cardinal directions: search for 'R' or 'Q'
     * Diagonal directions: search for 'B' or 'Q'
     */
    private static boolean isMatchFound(String[] closestTypes) {
        // Check Cardinal directions (0-3)
        for (int i = 0; i <= 3; i++) {
            if (closestTypes[i].contains("R") || closestTypes[i].contains("Q")) {
                return true;
            }
        }

        // Check Diagonal directions (4-7)
        for (int i = 4; i <= 7; i++) {
            if (closestTypes[i].contains("B") || closestTypes[i].contains("Q")) {
                return true;
            }
        }

        return false;
    }
}

import java.util.*;
import java.io.*;

/**
 * Anton and Chess
 * Determines if a King at (kx, ky) is blocked in all 8 directions by pieces.
 * Rooks ('R') block horizontal and vertical paths.
 * Bishops ('B') block diagonal paths.
 */
public class AntonandChess {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            solve(scanner, out);
        } catch (Exception e) {
            // In a real-world scenario, use a logger.
            e.printStackTrace();
        } finally {
            scanner.close();
            out.close();
        }
    }

    private static void solve(FastScanner scanner, PrintWriter out) {
        int n = scanner.nextInt();
        int kingX = scanner.nextInt();
        int kingY = scanner.nextInt();

        // Array to store the closest piece found in each of the 8 directions.
        Piece[] closestPieces = new Piece[8];

        for (int i = 0; i < n; i++) {
            char type = scanner.nextChar();
            int px = scanner.nextInt();
            int py = scanner.nextInt();

            int dx = px - kingX;
            int dy = py - kingY;

            // Skip if the piece is at the same location as the king.
            if (dx == 0 && dy == 0) continue;

            int dirIdx = getDirectionIndex(dx, dy);

            // If the piece is in one of the 8 valid directions, track the closest one.
            if (dirIdx != -1) {
                int distance = Math.max(Math.abs(dx), Math.abs(dy));
                if (closestPieces[dirIdx] == null || distance < closestPieces[dirIdx].distance) {
                    closestPieces[dirIdx] = new Piece(type, distance);
                }
            }
        }

        // Check if all 8 directions are blocked by the correct piece type.
        boolean isBlocked = true;
        for (int i = 0; i < 8; i++) {
            Piece closest = closestPieces[i];
            if (closest == null || closest.type != DIRECTIONS[i].requiredType) {
                isBlocked = false;
                break;
            }
        }

        // If blocked, the King cannot move ("NO"). Otherwise, "YES".
        out.println(isBlocked ? "NO" : "YES");
    }

    /**
     * Returns the index of the direction based on relative dx and dy.
     * 0-3: Horizontal/Vertical, 4-7: Diagonals.
     */
    private static int getDirectionIndex(int dx, int dy) {
        if (dx == 0) { // Vertical
            return (dy > 0) ? 0 : 1;
        } else if (dy == 0) { // Horizontal
            return (dx > 0) ? 2 : 3;
        } else if (Math.abs(dx) == Math.abs(dy)) { // Diagonal
            if (dx > 0 && dy > 0) return 4;      // Up-Right
            if (dx > 0 && dy < 0) return 5;      // Down-Right
            if (dx < 0 && dy > 0) return 6;      // Up-Left
            if (dx < 0 && dy < 0) return 7;      // Down-Left
        }
        return -1;
    }

    // Definition of the 8 directions and the piece required to block them.
    private static final Direction[] DIRECTIONS = {
        new Direction(0, 1, 'R'),   // Up
        new Direction(0, -1, 'R'),  // Down
        new Direction(1, 0, 'R'),   // Right
        new Direction(-1, 0, 'R'),  // Left
        new Direction(1, 1, 'B'),   // Up-Right
        new Direction(1, -1, 'B'),  // Down-Right
        new Direction(-1, 1, 'B'),  // Up-Left
        new Direction(-1, -1, 'B')  // Down-Left
    };

    private static class Direction {
        final int dx, dy;
        final char requiredType;

        Direction(int dx, int dy, char requiredType) {
            this.dx = dx;
            this.dy = dy;
            this.requiredType = requiredType;
        }
    }

    private static class Piece {
        final char type;
        final int distance;

        Piece(char type, int distance) {
            this.type = type;
            this.distance = distance;
        }
    }

    /**
     * Optimized reader for fast I/O performance.
     */
    static class FastScanner implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public char nextChar() {
            return next().charAt(0);
        }

        @Override
        public void close() throws IOException {
            reader.close();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves a chess-based positioning problem to determine if specific 
 * pieces are blocking views in cardinal or diagonal directions.
 */
public class ChessProblemSolver {

    public enum PieceType {
        ROOK('R'),
        BISHOP('B');

        private final char symbol;

        PieceType(char symbol) {
            this.symbol = symbol;
        }

        public static PieceType fromChar(char c) {
            for (PieceType type : PieceType.values()) {
                if (type.symbol == c) {
                    return type;
                }
            }
            throw new IllegalArgumentException("Unknown piece type: " + c);
        }
    }

    /**
     * Represents a piece on the board relative to the starting position.
     */
    private static class Piece {
        final long dx;
        final long dy;
        final PieceType type;
        final long distance;

        Piece(long dx, long dy, PieceType type) {
            this.dx = dx;
            this.dy = dy;
            this.type = type;
            // Manhattan distance is sufficient for pieces on straight/diagonal lines
            this.distance = Math.abs(dx) + Math.abs(dy);
        }
    }

    /**
     * Tracks the closest piece in four specific directions.
     */
    private static class DirectionalTracker {
        private final Piece[] closestPieces = new Piece[4];

        public void update(int directionIndex, Piece piece) {
            if (directionIndex < 0 || directionIndex >= 4) {
                return;
            }
            if (closestPieces[directionIndex] == null || piece.distance < closestPieces[directionIndex].distance) {
                closestPieces[directionIndex] = piece;
            }
        }

        public Piece[] getClosestPieces() {
            return closestPieces;
        }
    }

    public void solve(FastScanner in, PrintWriter out) {
        int n = in.nextInt();
        long startX = in.nextLong();
        long startY = in.nextLong();

        DirectionalTracker rookTracker = new DirectionalTracker();
        DirectionalTracker bishopTracker = new DirectionalTracker();

        for (int i = 0; i < n; i++) {
            PieceType type = PieceType.fromChar(in.next().charAt(0));
            long absX = in.nextLong();
            long absY = in.nextLong();

            long dx = absX - startX;
            long dy = absY - startY;

            if (isCardinal(dx, dy)) {
                int dirIdx = getRookDirectionIndex(dx, dy);
                rookTracker.update(dirIdx, new Piece(dx, dy, type));
            } else if (isDiagonal(dx, dy)) {
                int dirIdx = getBishopDirectionIndex(dx, dy);
                bishopTracker.update(dirIdx, new Piece(dx, dy, type));
            }
        }

        if (checkDiagonalCondition(bishopTracker) || checkCardinalCondition(rookTracker)) {
            out.println("YES");
        } else {
            out.println("NO");
        }
    }

    private boolean isCardinal(long dx, long dy) {
        return dx == 0 || dy == 0;
    }

    private boolean isDiagonal(long dx, long dy) {
        return Math.abs(dx) == Math.abs(dy);
    }

    private int getRookDirectionIndex(long dx, long dy) {
        if (dx < 0) return 0;
        if (dx > 0) return 1;
        if (dy < 0) return 2;
        if (dy > 0) return 3;
        return -1;
    }

    private int getBishopDirectionIndex(long dx, long dy) {
        if (dx > 0 && dy > 0) return 0;
        if (dx > 0 && dy < 0) return 1;
        if (dx < 0 && dy > 0) return 2;
        if (dx < 0 && dy < 0) return 3;
        return -1;
    }

    private boolean checkDiagonalCondition(DirectionalTracker tracker) {
        for (Piece piece : tracker.getClosestPieces()) {
            // If any piece on a diagonal is a Bishop, return true
            if (piece != null && piece.type == PieceType.BISHOP) {
                return true;
            }
        }
        return false;
    }

    private boolean checkCardinalCondition(DirectionalTracker tracker) {
        for (Piece piece : tracker.getClosestPieces()) {
            // If any piece on a cardinal line is a Rook, return true
            if (piece != null && piece.type == PieceType.ROOK) {
                return true;
            }
        }
        return false;
    }

    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        new ChessProblemSolver().solve(in, out);
        out.close();
    }

    /**
     * High-performance input reader.
     */
    private static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int bufferLength = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private boolean hasNextByte() {
            if (ptr < bufferLength) return true;
            ptr = 0;
            try {
                bufferLength = in.read(buffer);
            } catch (IOException e) {
                return false;
            }
            return bufferLength > 0;
        }

        private int readByte() {
            return hasNextByte() ? buffer[ptr++] : -1;
        }

        private boolean isPrintableChar(int c) {
            return 33 <= c && c <= 126;
        }

        private void skipUnprintable() {
            while (hasNextByte() && !isPrintableChar(buffer[ptr])) {
                ptr++;
            }
        }

        public boolean hasNext() {
            skipUnprintable();
            return hasNextByte();
        }

        public String next() {
            if (!hasNext()) throw new NoSuchElementException();
            StringBuilder sb = new StringBuilder();
            int b = readByte();
            while (isPrintableChar(b)) {
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }

        public int nextInt() {
            return (int) nextLong();
        }

        public long nextLong() {
            if (!hasNext()) throw new NoSuchElementException();
            long n = 0;
            boolean minus = false;
            int b = readByte();
            if (b == '-') {
                minus = true;
                b = readByte();
            }
            if (b < '0' || b > '9') {
                throw new NumberFormatException();
            }
            while (true) {
                if (b >= '0' && b <= '9') {
                    n *= 10;
                    n += b - '0';
                } else if (b == -1 || !isPrintableChar(b)) {
                    return minus ? -n : n;
                } else {
                    throw new NumberFormatException();
                }
                b = readByte();
            }
        }
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Represents a coordinate on the chessboard.
 */
class Position {
    private final long x;
    private final long y;

    public Position(long x, long y) {
        this.x = x;
        this.y = y;
    }

    public long getX() { return x; }
    public long getY() { return y; }

    public long getSum() { return x + y; }
    public long getDiff() { return y - x; }
}

/**
 * Service responsible for calculating chess piece attack patterns.
 */
class AttackService {

    /**
     * Checks if the king is under attack by any bishop or rook.
     */
    public boolean isKingInCheck(Position king, List<Position> rooks, List<Position> bishops) {
        return isBishopAttacking(king, bishops, rooks) || isRookAttacking(king, rooks, bishops);
    }

    private boolean isBishopAttacking(Position king, List<Position> bishops, List<Position> rooks) {
        for (Position bishop : bishops) {
            if (isOnSameDiagonal(king, bishop)) {
                if (!isBlockedByRook(king, bishop, rooks)) {
                    return true;
                }
            }
        }
        return false;
    }

    private boolean isRookAttacking(Position king, List<Position> rooks, List<Position> bishops) {
        for (Position rook : rooks) {
            if (isOnSameStraightLine(king, rook)) {
                if (!isBlockedByBishop(king, rook, bishops)) {
                    return true;
                }
            }
        }
        return false;
    }

    private boolean isOnSameDiagonal(Position p1, Position p2) {
        return p1.getDiff() == p2.getDiff() || p1.getSum() == p2.getSum();
    }

    private boolean isOnSameStraightLine(Position p1, Position p2) {
        return p1.getX() == p2.getX() || p1.getY() == p2.getY();
    }

    private boolean isBlockedByRook(Position king, Position bishop, List<Position> rooks) {
        for (Position rook : rooks) {
            // A rook blocks a bishop if it's on the same diagonal AND between the king and bishop
            if (rook.getDiff() == bishop.getDiff() || rook.getSum() == bishop.getSum()) {
                // We only care about the diagonal that the bishop and king are actually on
                if (king.getDiff() == bishop.getDiff() && rook.getDiff() == bishop.getDiff()) {
                    if (isBetween(rook.getX(), king.getX(), bishop.getX())) return true;
                }
                if (king.getSum() == bishop.getSum() && rook.getSum() == bishop.getSum()) {
                    if (isBetween(rook.getX(), king.getX(), bishop.getX())) return true;
                }
            }
        }
        return false;
    }

    private boolean isBlockedByBishop(Position king, Position rook, List<Position> bishops) {
        for (Position bishop : bishops) {
            // A bishop blocks a rook if it's on the same row/column AND between the king and rook
            if (king.getX() == rook.getX() && bishop.getX() == king.getX()) {
                if (isBetween(bishop.getY(), king.getY(), rook.getY())) return true;
            }
            if (king.getY() == rook.getY() && bishop.getY() == king.getY()) {
                if (isBetween(bishop.getX(), king.getX(), rook.getX())) return true;
            }
        }
        return false;
    }

    /**
     * Checks if the target value is strictly between start and end.
     * Using comparison instead of multiplication to prevent long overflow.
     */
    private boolean isBetween(long target, long start, long end) {
        return (target > Math.min(start, end)) && (target < Math.max(start, end));
    }
}

/**
 * Main application class to handle input and run the simulation.
 */
public class ChessGame {
    private final List<Position> rooks = new ArrayList<>();
    private final List<Position> bishops = new ArrayList<>();
    private Position king;
    private final AttackService attackService = new AttackService();

    public static void main(String[] args) {
        ChessGame game = new ChessGame();
        game.run();
    }

    public void run() {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) return;

        int n = scanner.nextInt();
        long kingX = scanner.nextLong();
        long kingY = scanner.nextLong();
        this.king = new Position(kingX, kingY);

        for (int i = 0; i < n; i++) {
            String type = scanner.next();
            long x = scanner.nextLong();
            long y = scanner.nextLong();
            addPiece(type, x, y);
        }

        boolean inCheck = attackService.isKingInCheck(king, rooks, bishops);
        System.out.println(inCheck ? "YES" : "NO");
        scanner.close();
    }

    private void addPiece(String type, long x, long y) {
        Position pos = new Position(x, y);
        char firstChar = type.charAt(0);

        if (firstChar == 'R') {
            rooks.add(pos);
        } else if (firstChar == 'B') {
            bishops.add(pos);
        } else {
            // Handles 'Q' (Queen) or any other type by adding both behaviors
            rooks.add(pos);
            bishops.add(pos);
        }
    }
}

import java.util.*;

/**
 * Represents a Chess game logic to determine if a target position 
 * is under attack by any given chess pieces.
 */
public class Chess {

    /**
     * Represents the different types of chess pieces.
     */
    public enum PieceType {
        ROOK, BISHOP, QUEEN;

        public static PieceType fromString(String typeStr) {
            return switch (typeStr) {
                case "R" -> ROOK;
                case "B" -> BISHOP;
                case "Q" -> QUEEN;
                default -> throw new IllegalArgumentException("Unknown piece type: " + typeStr);
            };
        }

        /**
         * Determines if this piece type can attack a target based on relative distance.
         */
        public boolean canAttack(int deltaRow, int deltaCol) {
            boolean isSameRowOrCol = (deltaRow == 0 || deltaCol == 0);
            boolean isSameDiagonal = (Math.abs(deltaRow) == Math.abs(deltaCol));

            return switch (this) {
                case ROOK -> isSameRowOrCol;
                case BISHOP -> isSameDiagonal;
                case QUEEN -> isSameRowOrCol || isSameDiagonal;
            };
        }
    }

    /**
     * Immutable representation of a coordinate on the board.
     */
    static record Position(int row, int col) {}

    /**
     * Represents a direction vector (normalized).
     */
    static record Direction(int dr, int dc) {}

    /**
     * Represents a chess piece with its type and position.
     */
    static record Piece(PieceType type, Position pos) {}

    /**
     * Container to track the closest piece found in a specific direction.
     */
    static class ClosestPieceInfo {
        final Piece piece;
        final long distance;

        ClosestPieceInfo(Piece piece, long distance) {
            this.piece = piece;
            this.distance = distance;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int pieceCount = scanner.nextInt();
        int targetRow = scanner.nextInt();
        int targetCol = scanner.nextInt();

        // Map to store the closest piece encountered for each of the 8 directions
        Map<Direction, ClosestPieceInfo> closestPiecesByDirection = new HashMap<>();

        for (int i = 0; i < pieceCount; i++) {
            PieceType type = PieceType.fromString(scanner.next());
            int pRow = scanner.nextInt();
            int pCol = scanner.nextInt();
            Position pPos = new Position(pRow, pCol);

            int deltaRow = pRow - targetRow;
            int deltaCol = pCol - targetCol;

            // Skip if the piece is on the same square as the target
            if (deltaRow == 0 && deltaCol == 0) {
                continue;
            }

            // A direction is valid in chess if it is horizontal, vertical, or diagonal
            boolean isVerticalOrHorizontal = (deltaRow == 0 || deltaCol == 0);
            boolean isDiagonal = (Math.abs(deltaRow) == Math.abs(deltaCol));

            if (isVerticalOrHorizontal || isDiagonal) {
                Direction dir = new Direction(
                    Integer.compare(deltaRow, 0),
                    Integer.compare(deltaCol, 0)
                );

                long distance = Math.max(Math.abs(deltaRow), Math.abs(deltaCol));

                // Only keep the closest piece in this direction (as others might be blocked)
                if (!closestPiecesByDirection.containsKey(dir) || 
                     distance < closestPiecesByDirection.get(dir).distance) {
                    closestPiecesByDirection.put(dir, new ClosestPieceInfo(new Piece(type, pPos), distance));
                }
            }
        }

        boolean isUnderAttack = checkIsUnderAttack(closestPiecesByDirection, targetRow, targetCol);
        System.out.println(isUnderAttack ? "YES" : "NO");

        scanner.close();
    }

    /**
     * Iterates through the closest pieces in all directions to see if any can attack the target.
     */
    private static boolean checkIsUnderAttack(Map<Direction, ClosestPieceInfo> closestMap, int tr, int tc) {
        for (ClosestPieceInfo info : closestMap.values()) {
            Piece piece = info.piece;
            int deltaRow = Math.abs(piece.pos().row() - tr);
            int deltaCol = Math.abs(piece.pos().col() - tc);

            if (piece.type().canAttack(deltaRow, deltaCol)) {
                return true;
            }
        }
        return false;
    }
}

import java.io.*;
import java.util.*;

/**
 * A refactored solution to determine if a king is under attack 
 * by chess pieces on a 2D plane.
 */
public class Main {
    public static void main(String[] args) {
        try {
            FastScanner scanner = new FastScanner(System.in);
            ChessGame game = new ChessGame(scanner);
            game.run();
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }
}

enum PieceType {
    ROOK('R'),
    BISHOP('B'),
    QUEEN('Q'),
    KING('F');

    private final char symbol;

    PieceType(char symbol) {
        this.symbol = symbol;
    }

    public static PieceType fromChar(char c) {
        for (PieceType type : PieceType.values()) {
            if (type.symbol == c) {
                return type;
            }
        }
        return KING; // Default fallback
    }
}

class ChessPiece {
    private final int id;
    private final PieceType type;
    private int x;
    private int y;

    public ChessPiece(int id, PieceType type, int x, int y) {
        this.id = id;
        this.type = type;
        this.x = x;
        this.y = y;
    }

    /**
     * Performs a 90-degree rotation of the piece's coordinates.
     */
    public void rotate() {
        int tempX = x;
        x = -y;
        y = tempX;
    }

    public int getId() { return id; }
    public PieceType getType() { return type; }
    public int getX() { return x; }
    public int getY() { return y; }
}

class ChessGame {
    private final FastScanner scanner;

    public ChessGame(FastScanner scanner) {
        this.scanner = scanner;
    }

    public void run() throws IOException {
        int n = scanner.nextInt();

        // Read King: Format is [Type] [X] [Y]
        PieceType kingType = PieceType.fromChar(scanner.next().charAt(0));
        int kingX = scanner.nextInt();
        int kingY = scanner.nextInt();
        ChessPiece king = new ChessPiece(0, kingType, kingX, kingY);

        // Read other figures
        List<ChessPiece> figures = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            PieceType type = PieceType.fromChar(scanner.next().charAt(0));
            int x = scanner.nextInt();
            int y = scanner.nextInt();
            figures.add(new ChessPiece(i + 1, type, x, y));
        }

        if (isKingUnderAttack(king, figures)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    private boolean isKingUnderAttack(ChessPiece king, List<ChessPiece> figures) {
        // Comparator for TreeSet: sort by Y, then by ID to prevent losing pieces with same Y
        Comparator<ChessPiece> pieceComparator = Comparator
                .comparingInt(ChessPiece::getY)
                .thenComparingInt(ChessPiece::getId);

        // Rotate the board 4 times to cover all 8 directions via vertical/diagonal checks
        for (int rotation = 0; rotation < 4; rotation++) {
            king.rotate();
            for (ChessPiece figure : figures) {
                figure.rotate();
            }

            if (checkCurrentOrientation(king, figures, pieceComparator)) {
                return true;
            }
        }
        return false;
    }

    private boolean checkCurrentOrientation(ChessPiece king, List<ChessPiece> figures, Comparator<ChessPiece> comparator) {
        Map<Integer, TreeSet<ChessPiece>> verticalLines = new HashMap<>();
        Map<Integer, TreeSet<ChessPiece>> diagonalLines = new HashMap<>();

        for (ChessPiece f : figures) {
            verticalLines.computeIfAbsent(f.getX(), k -> new TreeSet<>(comparator)).add(f);
            diagonalLines.computeIfAbsent(f.getX() - f.getY(), k -> new TreeSet<>(comparator)).add(f);
        }

        // 1. Check vertical line (Vertical scan covers horizontal after rotations)
        TreeSet<ChessPiece> vLine = verticalLines.get(king.getX());
        if (vLine != null) {
            ChessPiece nearest = vLine.lower(king);
            if (nearest != null && (nearest.getType() == PieceType.ROOK || nearest.getType() == PieceType.QUEEN)) {
                return true;
            }
        }

        // 2. Check diagonal line (Diagonal scan covers anti-diagonal after rotations)
        TreeSet<ChessPiece> dLine = diagonalLines.get(king.getX() - king.getY());
        if (dLine != null) {
            ChessPiece nearest = dLine.lower(king);
            if (nearest != null && (nearest.getType() == PieceType.BISHOP || nearest.getType() == PieceType.QUEEN)) {
                return true;
            }
        }

        return false;
    }
}

class FastScanner {
    private final BufferedReader br;
    private StringTokenizer st;

    public FastScanner(InputStream in) {
        br = new BufferedReader(new InputStreamReader(in));
    }

    public String next() throws IOException {
        while (st == null || !st.hasMoreElements()) {
            String line = br.readLine();
            if (line == null) return null;
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }

    public int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    public long nextLong() throws IOException {
        return Long.parseLong(next());
    }

    public double nextDouble() throws IOException {
        return Double.parseDouble(next().replace(',', '.'));
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution to determine if a King is in check on a chessboard.
 */
public class ChessGame {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            int n = reader.nextInt();
            long kingX = reader.nextLong();
            long kingY = reader.nextLong();

            ChessGame game = new ChessGame();
            game.loadPieces(reader, n, kingX, kingY);

            if (game.isKingInCheck()) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            out.close();
        }
    }

    private final Map<Direction, ChessPiece> closestPiecesInDirection = new EnumMap<>(Direction.class);

    /**
     * Reads pieces and stores only the closest piece in each of the 8 valid directions.
     */
    public void loadPieces(FastReader reader, int n, long kingX, long kingY) throws IOException {
        for (int i = 0; i < n; i++) {
            String typeStr = reader.next();
            PieceType type = PieceType.fromChar(typeStr.charAt(0));
            long x = reader.nextLong();
            long y = reader.nextLong();

            long dx = x - kingX;
            long dy = y - kingY;

            Direction dir = Direction.getDirection(dx, dy);
            if (dir != Direction.NONE) {
                ChessPiece piece = new ChessPiece(type, dx, dy);
                updateClosestPiece(dir, piece);
            }
        }
    }

    private void updateClosestPiece(Direction dir, ChessPiece newPiece) {
        ChessPiece existing = closestPiecesInDirection.get(dir);
        if (existing == null || newPiece.getDistance() < existing.getDistance()) {
            closestPiecesInDirection.put(dir, newPiece);
        }
    }

    /**
     * Checks if any of the closest pieces in the 8 directions can attack the King.
     */
    public boolean isKingInCheck() {
        for (Map.Entry<Direction, ChessPiece> entry : closestPiecesInDirection.entrySet()) {
            Direction dir = entry.getKey();
            ChessPiece piece = entry.getValue();
            if (piece.getType().canAttack(dir)) {
                return true;
            }
        }
        return false;
    }

    // --- Domain Models ---

    enum PieceType {
        ROOK('R'), BISHOP('B'), QUEEN('Q');

        private final char symbol;

        PieceType(char symbol) {
            this.symbol = symbol;
        }

        public static PieceType fromChar(char c) {
            for (PieceType type : PieceType.values()) {
                if (type.symbol == c) return type;
            }
            throw new IllegalArgumentException("Unknown piece type: " + c);
        }

        public boolean canAttack(Direction dir) {
            return switch (this) {
                case QUEEN -> true;
                case ROOK -> dir.isCardinal();
                case BISHOP -> !dir.isCardinal();
            };
        }
    }

    enum Direction {
        LEFT(true), RIGHT(true), UP(true), DOWN(true),
        UP_LEFT(false), UP_RIGHT(false), DOWN_LEFT(false), DOWN_RIGHT(false),
        NONE(false);

        private final boolean cardinal;

        Direction(boolean cardinal) {
            this.cardinal = cardinal;
        }

        public boolean isCardinal() {
            return cardinal;
        }

        public static Direction getDirection(long dx, long dy) {
            if (dy == 0) {
                return dx < 0 ? LEFT : (dx > 0 ? RIGHT : NONE);
            }
            if (dx == 0) {
                return dy < 0 ? DOWN : (dy > 0 ? UP : NONE);
            }
            if (dx == dy) {
                return dx < 0 ? DOWN_LEFT : UP_RIGHT;
            }
            if (dx == -dy) {
                return dx < 0 ? UP_LEFT : DOWN_RIGHT;
            }
            return NONE;
        }
    }

    static class ChessPiece {
        private final PieceType type;
        private final long dx;
        private final long dy;
        private final long distance;

        public ChessPiece(PieceType type, long dx, long dy) {
            this.type = type;
            this.dx = dx;
            this.dy = dy;
            // Using Chebyshev distance since we only care about the 8 cardinal/intercardinal directions
            this.distance = Math.max(Math.abs(dx), Math.abs(dy));
        }

        public PieceType getType() { return type; }
        public long getDistance() { return distance; }
    }

    // --- Utilities ---

    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }
}

import java.util.Scanner;

/**
 * Refactored solution for the Anton Potions problem.
 * This version focuses on maintainability by using Enums to represent scenarios 
 * and a dedicated Candidate class to track extreme values.
 */
public class AntonPotions {

    /**
     * Represents the possible types of potions.
     */
    enum PotionType {
        RED, BLUE, GREEN, QUEEN, UNKNOWN;

        public static PotionType fromChar(char c) {
            return switch (c) {
                case 'R' -> RED;
                case 'B' -> BLUE;
                case 'G' -> GREEN;
                case 'Q' -> QUEEN;
                default -> UNKNOWN;
            };
        }
    }

    /**
     * Defines the 8 specific boundary scenarios we are tracking.
     * Each scenario knows if it is looking for a maximum or minimum value
     * and whether it belongs to the "Even" index group (Red/Queen) 
     * or "Odd" index group (Blue/Queen) from the original logic.
     */
    enum Scenario {
        IK_J_LESS(true, true),      // Max J where i == targetI, j < targetJ
        DIFF_I_LESS(true, false),   // Max I where i-j == diff, i < targetI
        JK_I_LESS(true, true),      // Max I where j == targetJ, i < targetI
        SUM_I_LESS(true, false),    // Max I where i+j == sum, i < targetI
        IK_J_MORE(false, true),     // Min J where i == targetI, j > targetJ
        DIFF_I_MORE(false, false),  // Min I where i-j == diff, i > targetI
        JK_I_MORE(false, true),     // Min I where j == targetJ, i > targetI
        SUM_I_MORE(false, false);   // Min I where i+j == sum, i > targetI

        final boolean findMax;
        final boolean isRedGroup; // Corresponds to the parity logic in the original code

        Scenario(boolean findMax, boolean isRedGroup) {
            this.findMax = findMax;
            this.isRedGroup = isRedGroup;
        }
    }

    /**
     * Tracks the "best" potion found so far for a specific scenario.
     */
    static class Candidate {
        private int bestValue;
        private PotionType type = PotionType.UNKNOWN;
        private boolean initialized = false;
        private final boolean findMax;

        public Candidate(boolean findMax) {
            this.findMax = findMax;
        }

        /**
         * Updates the candidate if the new value is "better" (higher for max, lower for min).
         */
        public void update(int value, PotionType type) {
            if (!initialized || (findMax ? value > this.bestValue : value < this.bestValue)) {
                this.bestValue = value;
                this.type = type;
                this.initialized = true;
            }
        }

        public PotionType getType() {
            return type;
        }
    }

    /**
     * Manages the collection of candidates for all scenarios.
     */
    static class PotionTracker {
        private final Candidate[] scenarioCandidates;

        public PotionTracker() {
            this.scenarioCandidates = new Candidate[Scenario.values().length];
            for (int i = 0; i < Scenario.values().length; i++) {
                scenarioCandidates[i] = new Candidate(Scenario.values()[i].findMax);
            }
        }

        public void updateScenario(Scenario scenario, int value, PotionType type) {
            scenarioCandidates[scenario.ordinal()].update(value, type);
        }

        public boolean hasWinningPotion() {
            for (Scenario s : Scenario.values()) {
                PotionType foundType = scenarioCandidates[s.ordinal()].getType();

                if (foundType == PotionType.QUEEN) return true;
                if (s.isRedGroup && foundType == PotionType.RED) return true;
                if (!s.isRedGroup && foundType == PotionType.BLUE) return true;
            }
            return false;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        if (!sc.hasNextInt()) return;

        int n = sc.nextInt();
        int targetI = sc.nextInt();
        int targetJ = sc.nextInt();

        int difference = targetI - targetJ;
        int sum = targetI + targetJ;

        PotionTracker tracker = new PotionTracker();

        for (int k = 0; k < n; k++) {
            char typeChar = sc.next().charAt(0);
            int valI = sc.nextInt();
            int valJ = sc.nextInt();
            PotionType type = PotionType.fromChar(typeChar);

            processPotion(tracker, type, valI, valJ, targetI, targetJ, difference, sum);
        }

        System.out.println(tracker.hasWinningPotion() ? "YES" : "NO");
        sc.close();
    }

    /**
     * Evaluates a single potion and updates the tracker if it meets any boundary criteria.
     * The order of if-else mimics the original precedence.
     */
    private static void processPotion(PotionTracker tracker, PotionType type, int i, int j, 
                                     int targetI, int targetJ, int diff, int sum) {
        if (i == targetI) {
            if (j < targetJ) {
                tracker.updateScenario(Scenario.IK_J_LESS, j, type);
            } else if (j > targetJ) {
                tracker.updateScenario(Scenario.IK_J_MORE, j, type);
            }
        } else if (j == targetJ) {
            if (i < targetI) {
                tracker.updateScenario(Scenario.JK_I_LESS, i, type);
            } else if (i > targetI) {
                tracker.updateScenario(Scenario.JK_I_MORE, i, type);
            }
        } else if (i - j == diff) {
            if (i < targetI) {
                tracker.updateScenario(Scenario.DIFF_I_LESS, i, type);
            } else if (i > targetI) {
                tracker.updateScenario(Scenario.DIFF_I_MORE, i, type);
            }
        } else if (i + j == sum) {
            if (i < targetI) {
                tracker.updateScenario(Scenario.SUM_I_LESS, i, type);
            } else if (i > targetI) {
                tracker.updateScenario(Scenario.SUM_I_MORE, i, type);
            }
        }
    }
}

import java.util.*;

/**
 * This program determines if a target position on a grid is under attack 
 * by any chess pieces. A piece can only attack if it is the closest piece 
 * in a valid direction (horizontal, vertical, or diagonal) from the target.
 */
public class Main {

    // Constants for piece types to avoid magic characters throughout the code
    private static final char QUEEN = 'Q';
    private static final char ROOK = 'R';
    private static final char BISHOP = 'B';

    /**
     * Represents a direction vector (dx, dy) where dx and dy are in {-1, 0, 1}.
     */
    private record Direction(int dx, int dy) {}

    /**
     * Tracks the details of the closest piece found in a specific direction.
     */
    private static class ClosestPiece {
        char type;
        int distance = Integer.MAX_VALUE;

        /**
         * Updates the stored piece if the provided piece is closer to the target.
         */
        void updateIfCloser(char type, int distance) {
            if (distance < this.distance) {
                this.distance = distance;
                this.type = type;
            }
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int numberOfPieces = scanner.nextInt();
        int targetX = scanner.nextInt();
        int targetY = scanner.nextInt();

        // Map to store the closest piece found for each of the 8 possible directions
        Map<Direction, ClosestPiece> closestPiecesByDirection = new HashMap<>();

        for (int i = 0; i < numberOfPieces; i++) {
            char type = scanner.next().charAt(0);
            int pieceX = scanner.nextInt();
            int pieceY = scanner.nextInt();

            int dx = pieceX - targetX;
            int dy = pieceY - targetY;

            // A piece can only attack if it's on a straight or diagonal line 
            // and not occupying the same square as the target.
            if (dx != 0 || dy != 0) {
                if (isOnLineOfSight(dx, dy)) {
                    Direction dir = getDirection(dx, dy);
                    int distance = Math.max(Math.abs(dx), Math.abs(dy));

                    closestPiecesByDirection
                            .computeIfAbsent(dir, k -> new ClosestPiece())
                            .updateIfCloser(type, distance);
                }
            }
        }

        boolean isAttacked = isTargetUnderAttack(closestPiecesByDirection);
        System.out.println(isAttacked ? "YES" : "NO");

        scanner.close();
    }

    /**
     * Checks if a point (dx, dy) lies on a horizontal, vertical, or 45-degree diagonal line.
     */
    private static boolean isOnLineOfSight(int dx, int dy) {
        return dx == 0 || dy == 0 || Math.abs(dx) == Math.abs(dy);
    }

    /**
     * Converts a relative distance into a normalized direction vector.
     */
    private static Direction getDirection(int dx, int dy) {
        return new Direction(Integer.compare(dx, 0), Integer.compare(dy, 0));
    }

    /**
     * Iterates through the closest pieces in all directions to see if any can attack.
     */
    private static boolean isTargetUnderAttack(Map<Direction, ClosestPiece> closestPieces) {
        for (var entry : closestPieces.entrySet()) {
            Direction dir = entry.getKey();
            ClosestPiece piece = entry.getValue();

            if (piece.type == QUEEN) {
                return true;
            }
            if (isStraightLine(dir) && piece.type == ROOK) {
                return true;
            }
            if (isDiagonalLine(dir) && piece.type == BISHOP) {
                return true;
            }
        }
        return false;
    }

    private static boolean isStraightLine(Direction dir) {
        return dir.dx == 0 || dir.dy == 0;
    }

    private static boolean isDiagonalLine(Direction dir) {
        return dir.dx != 0 && dir.dy != 0;
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to determine if the nearest piece in any cardinal or diagonal direction 
 * from a target point allows for a valid move (Rook, Bishop, or Queen).
 */
public class PieceMovementTracker {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        try {
            int n = reader.nextInt();
            Point target = new Point("", reader.nextInt(), reader.nextInt());

            List<Point> points = new ArrayList<>(n);
            for (int i = 0; i < n; i++) {
                String label = reader.next();
                int x = reader.nextInt();
                int y = reader.nextInt();
                points.add(new Point(label, x, y));
            }

            if (canMakeMove(points, target)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        } catch (Exception e) {
            // In a production environment, use a logger.
        }
    }

    /**
     * Evaluates the movement conditions based on the closest points in 8 directions.
     */
    private static boolean canMakeMove(List<Point> points, Point target) {
        DirectionTracker tracker = new DirectionTracker();

        for (Point p : points) {
            tracker.updateClosest(p, target);
        }

        // Condition 1: Is the closest cardinal piece a Rook (R) or Queen (Q)?
        boolean cardinalMatch = tracker.isClosestCardinalValid(Set.of("R", "Q"));

        // Condition 2: Is the closest diagonal piece a Bishop (B) or Queen (Q)?
        boolean diagonalMatch = tracker.isClosestDiagonalValid(Set.of("B", "Q"));

        return cardinalMatch || diagonalMatch;
    }

    /**
     * Represents a geometric point with a label.
     */
    static class Point {
        final String label;
        final int x;
        final int y;

        Point(String label, int x, int y) {
            this.label = label;
            this.x = x;
            this.y = y;
        }
    }

    /**
     * Represents the 8 possible directions from a point.
     */
    enum Direction {
        NORTH, SOUTH, EAST, WEST, 
        NORTH_EAST, NORTH_WEST, SOUTH_EAST, SOUTH_WEST
    }

    /**
     * Tracks the closest point found so far for each of the 8 directions.
     */
    static class DirectionTracker {
        private final Map<Direction, ClosestInfo> closestPoints = new EnumMap<>(Direction.class);

        DirectionTracker() {
            for (Direction d : Direction.values()) {
                closestPoints.put(d, new ClosestInfo());
            }
        }

        void updateClosest(Point p, Point target) {
            long dx = (long) p.x - target.x;
            long dy = (long) p.y - target.y;

            if (dx == 0 && dy == 0) return; // Same position

            Direction dir = null;
            if (dx == 0) { // Vertical
                dir = (dy > 0) ? Direction.NORTH : Direction.SOUTH;
            } else if (dy == 0) { // Horizontal
                dir = (dx > 0) ? Direction.EAST : Direction.WEST;
            } else if (Math.abs(dx) == Math.abs(dy)) { // Diagonal
                if (dx > 0 && dy > 0) dir = Direction.NORTH_EAST;
                else if (dx < 0 && dy > 0) dir = Direction.NORTH_WEST;
                else if (dx > 0 && dy < 0) dir = Direction.SOUTH_EAST;
                else dir = Direction.SOUTH_WEST;
            }

            if (dir != null) {
                long distance = Math.max(Math.abs(dx), Math.abs(dy));
                closestPoints.get(dir).update(distance, p.label);
            }
        }

        boolean isClosestCardinalValid(Set<String> validLabels) {
            return StreamOfDirections(Direction.NORTH, Direction.SOUTH, Direction.EAST, Direction.WEST)
                    .anyMatch(d -> validLabels.contains(closestPoints.get(d).label));
        }

        boolean isClosestDiagonalValid(Set<String> validLabels) {
            return StreamOfDirections(Direction.NORTH_EAST, Direction.NORTH_WEST, Direction.SOUTH_EAST, Direction.SOUTH_WEST)
                    .anyMatch(d -> validLabels.contains(closestPoints.get(d).label));
        }

        private java.util.stream.Stream<Direction> StreamOfDirections(Direction... dirs) {
            return Arrays.stream(dirs);
        }

        private static class ClosestInfo {
            long minDistance = Long.MAX_VALUE;
            String label = "";

            void update(long distance, String newLabel) {
                if (distance < minDistance) {
                    minDistance = distance;
                    label = newLabel;
                }
            }
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to detect if any chess pieces are in a position to "fight" 
 * (attack) a specific target coordinate.
 */
public class ChessBattleDetector {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        try {
            BattleDetector detector = new BattleDetector(reader);
            detector.solve();
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
            System.exit(1);
        }
    }

    /**
     * Represents the types of chess pieces.
     */
    enum PieceType {
        ROOK('R'),
        BISHOP('B'),
        QUEEN('Q'),
        OTHER('?');

        private final char symbol;

        PieceType(char symbol) {
            this.symbol = symbol;
        }

        public static PieceType fromChar(char c) {
            for (PieceType type : PieceType.values()) {
                if (type.symbol == c) return type;
            }
            return OTHER;
        }
    }

    /**
     * Represents the 8 possible directions relative to a target.
     */
    enum Direction {
        STRAIGHT_LEFT, STRAIGHT_RIGHT, STRAIGHT_UP, STRAIGHT_DOWN,
        DIAG_1_LEFT, DIAG_1_RIGHT, DIAG_2_LEFT, DIAG_2_RIGHT,
        NONE;

        public boolean isStraight() {
            return this.ordinal() >= 0 && this.ordinal() <= 3;
        }

        public boolean isDiagonal() {
            return this.ordinal() >= 4 && this.ordinal() <= 7;
        }
    }

    /**
     * Represents a chess piece on the board.
     */
    static class Figure {
        final PieceType type;
        final int x;
        final int y;

        Figure(PieceType type, int x, int y) {
            this.type = type;
            this.x = x;
            this.y = y;
        }
    }

    /**
     * Core logic for detecting piece attacks.
     */
    static class BattleDetector {
        private final FastReader reader;
        private final Map<Direction, Figure> nearestPieces = new EnumMap<>(Direction.class);
        private int targetX;
        private int targetY;

        BattleDetector(FastReader reader) {
            this.reader = reader;
        }

        public void solve() throws IOException {
            int n = reader.nextInt();
            this.targetX = reader.nextInt();
            this.targetY = reader.nextInt();

            for (int i = 0; i < n; i++) {
                char typeChar = reader.next().charAt(0);
                int x = reader.nextInt();
                int y = reader.nextInt();

                Figure currentFigure = new Figure(PieceType.fromChar(typeChar), x, y);
                Direction dir = calculateDirection(currentFigure);

                if (dir != Direction.NONE) {
                    updateNearest(dir, currentFigure);
                }
            }

            System.out.println(isFightDetected() ? "YES" : "NO");
        }

        private Direction calculateDirection(Figure figure) {
            int dx = figure.x - targetX;
            int dy = figure.y - targetY;

            // Horizontal
            if (figure.y == targetY) {
                return dx < 0 ? Direction.STRAIGHT_LEFT : Direction.STRAIGHT_RIGHT;
            }
            // Vertical
            if (figure.x == targetX) {
                return dy < 0 ? Direction.STRAIGHT_UP : Direction.STRAIGHT_DOWN;
            }
            // Diagonal (x - y = constant)
            if (figure.x - figure.y == targetX - targetY) {
                return dx < 0 ? Direction.DIAG_1_LEFT : Direction.DIAG_1_RIGHT;
            }
            // Anti-Diagonal (x + y = constant)
            if (figure.x + figure.y == targetX + targetY) {
                return dx < 0 ? Direction.DIAG_2_LEFT : Direction.DIAG_2_RIGHT;
            }

            return Direction.NONE;
        }

        private void updateNearest(Direction dir, Figure figure) {
            Figure existing = nearestPieces.get(dir);
            if (existing == null || getChebyshevDistance(figure) < getChebyshevDistance(existing)) {
                nearestPieces.put(dir, figure);
            }
        }

        private int getChebyshevDistance(Figure f) {
            return Math.max(Math.abs(f.x - targetX), Math.abs(f.y - targetY));
        }

        private boolean isFightDetected() {
            for (Map.Entry<Direction, Figure> entry : nearestPieces.entrySet()) {
                Direction dir = entry.getKey();
                Figure f = entry.getValue();

                if (dir.isStraight()) {
                    if (f.type == PieceType.ROOK || f.type == PieceType.QUEEN) return true;
                } else if (dir.isDiagonal()) {
                    if (f.type == PieceType.BISHOP || f.type == PieceType.QUEEN) return true;
                }
            }
            return false;
        }
    }

    /**
     * Utility class for fast input reading.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to determine if a King is under attack by any chess piece on a board.
 * Refactored for maintainability, readability, and object-oriented design.
 */
public class Main {

    public static void main(String[] args) throws IOException {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = reader.nextInt();
        Position kingPos = new Position(reader.nextLong(), reader.nextLong());

        // Map to store the closest piece found in each of the 8 directions
        Map<Direction, Piece> closestPiecesInDirections = new EnumMap<>(Direction.class);

        for (int i = 0; i < n; i++) {
            char typeChar = reader.nextChar();
            long x = reader.nextLong();
            long y = reader.nextLong();

            Piece currentPiece = new Piece(PieceType.fromChar(typeChar), new Position(x, y));
            Direction dir = Direction.fromDelta(x - kingPos.x(), y - kingPos.y());

            if (dir != null) {
                Piece existingClosest = closestPiecesInDirections.get(dir);
                if (existingClosest == null || currentPiece.distanceTo(kingPos) < existingClosest.distanceTo(kingPos)) {
                    closestPiecesInDirections.put(dir, currentPiece);
                }
            }
        }

        boolean isUnderAttack = false;
        for (Map.Entry<Direction, Piece> entry : closestPiecesInDirections.entrySet()) {
            if (entry.getValue().type().canAttack(entry.getKey().isDiagonal())) {
                isUnderAttack = true;
                break;
            }
        }

        out.println(isUnderAttack ? "YES" : "NO");
        out.flush();
        out.close();
    }

    /**
     * Represents a coordinate on the board.
     */
    record Position(long x, long y) {}

    /**
     * Represents the types of chess pieces.
     */
    enum PieceType {
        ROOK('R'), BISHOP('B'), QUEEN('Q'), KING('K'), NONE('N');

        private final char symbol;

        PieceType(char symbol) {
            this.symbol = symbol;
        }

        public static PieceType fromChar(char c) {
            for (PieceType type : values()) {
                if (type.symbol == c) return type;
            }
            return NONE;
        }

        /**
         * Logic defining which pieces can attack in which movement patterns.
         */
        public boolean canAttack(boolean isDiagonal) {
            if (this == NONE) return false;
            if (isDiagonal) {
                return this == BISHOP || this == QUEEN || this == KING;
            } else {
                return this == ROOK || this == QUEEN || this == KING;
            }
        }
    }

    /**
     * Represents the 8 directions a piece can move relative to the king.
     */
    enum Direction {
        UP(false), DOWN(false), LEFT(false), RIGHT(false),
        UR(true), DL(true), DR(true), UL(true);

        private final boolean diagonal;

        Direction(boolean diagonal) {
            this.diagonal = diagonal;
        }

        public boolean isDiagonal() {
            return diagonal;
        }

        /**
         * Determines direction based on Delta X and Delta Y.
         */
        public static Direction fromDelta(long dx, long dy) {
            if (dx == 0 && dy > 0) return UP;
            if (dx == 0 && dy < 0) return DOWN;
            if (dy == 0 && dx > 0) return RIGHT;
            if (dy == 0 && dx < 0) return LEFT;

            // Diagonal Check: |dx| == |dy|
            if (dx == dy) {
                return (dx > 0) ? DR : UL;
            } else if (dx == -dy) {
                return (dx > 0) ? UR : DL;
            }

            return null;
        }
    }

    /**
     * Represents a chess piece on the board.
     */
    record Piece(PieceType type, Position pos) {
        public long distanceTo(Position target) {
            return Math.abs(this.pos.x() - target.x()) + Math.abs(this.pos.y() - target.y());
        }
    }

    /**
     * Fast I/O utility for competitive programming contexts.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        public char nextChar() throws IOException {
            return next().charAt(0);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A simulation of a directional game where pieces (Black, Red, or Queen) 
 * are placed on a grid relative to an origin.
 */
public class DirectionalGame {

    private static final int NUM_DIRECTIONS = 8;
    private static final int CARDINAL_DIRECTIONS_COUNT = 4;

    public static void main(String[] args) {
        try (FastReader reader = new FastReader(System.in);
             PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)))) {
            solve(reader, writer);
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Core logic for processing the game input and determining the winner.
     */
    public static void solve(FastReader reader, PrintWriter writer) throws IOException {
        int n = reader.nextInt();
        int originX = reader.nextInt();
        int originY = reader.nextInt();

        int[] blackMinDistances = new int[NUM_DIRECTIONS];
        int[] redMinDistances = new int[NUM_DIRECTIONS];

        Arrays.fill(blackMinDistances, Integer.MAX_VALUE);
        Arrays.fill(redMinDistances, Integer.MAX_VALUE);

        for (int i = 0; i < n; i++) {
            char type = reader.next().charAt(0);
            int x = reader.nextInt();
            int y = reader.nextInt();

            int direction = calculateDirectionIndex(x, y, originX, originY);

            // If the point is not in one of the 8 valid directions, skip it
            if (direction == -1) {
                continue;
            }

            int distance = calculateChebyshevDistance(x, y, originX, originY);

            if (isBlackPiece(type, direction)) {
                blackMinDistances[direction] = Math.min(blackMinDistances[direction], distance);
            } else if (isRedPiece(type, direction)) {
                redMinDistances[direction] = Math.min(redMinDistances[direction], distance);
            }
        }

        boolean isWinningConditionMet = evaluateWinningCondition(blackMinDistances, redMinDistances);
        writer.println(isWinningConditionMet ? "YES" : "NO");
    }

    /**
     * A Queen's team is determined by the direction it faces:
     * Cardinal directions (0-3) belong to Red, Diagonals (4-7) belong to Black.
     */
    private static boolean isBlackPiece(char type, int direction) {
        return type == 'B' || (type == 'Q' && direction >= CARDINAL_DIRECTIONS_COUNT);
    }

    private static boolean isRedPiece(char type, int direction) {
        return type == 'R' || (type == 'Q' && direction < CARDINAL_DIRECTIONS_COUNT);
    }

    /**
     * Evaluates if Red is closer in any cardinal direction 
     * OR if Black is closer in any diagonal direction.
     */
    private static boolean evaluateWinningCondition(int[] blackMinDist, int[] redMinDist) {
        // Check Cardinal directions for Red
        for (int i = 0; i < CARDINAL_DIRECTIONS_COUNT; i++) {
            if (redMinDist[i] < blackMinDist[i]) {
                return true;
            }
        }
        // Check Diagonal directions for Black
        for (int i = CARDINAL_DIRECTIONS_COUNT; i < NUM_DIRECTIONS; i++) {
            if (blackMinDist[i] < redMinDist[i]) {
                return true;
            }
        }
        return false;
    }

    /**
     * Maps a point to one of 8 direction indices.
     * 0-3: Cardinal (+x, -x, +y, -y)
     * 4-7: Diagonal (+x+y, +x-y, -x+y, -x-y)
     */
    private static int calculateDirectionIndex(int x, int y, int x0, int y0) {
        if (y == y0) {
            return x > x0 ? 0 : 1;
        } else if (x == x0) {
            return y > y0 ? 2 : 3;
        } else if (Math.abs(x - x0) == Math.abs(y - y0)) {
            int dx = x - x0;
            int dy = y - y0;
            if (dx > 0) {
                return dy > 0 ? 4 : 5;
            } else {
                return dy > 0 ? 6 : 7;
            }
        }
        return -1;
    }

    /**
     * Calculates the Chebyshev distance between two points.
     */
    private static int calculateChebyshevDistance(int x, int y, int x0, int y0) {
        return Math.max(Math.abs(x - x0), Math.abs(y - y0));
    }

    /**
     * Fast I/O utility class.
     */
    protected static class FastReader implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            this.reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        public double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }

        @Override
        public void close() throws IOException {
            reader.close();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * AntonChess2 refactored for maintainability and code quality.
 * Determines if a target square on a chessboard is being attacked by the nearest piece in any direction.
 */
public class AntonChess2 {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(new BufferedReader(new InputStreamReader(System.in)));
        PrintWriter out = new PrintWriter(System.out);

        try {
            ChessGame game = new ChessGame(scanner);
            boolean isAttacked = game.solve();
            out.println(isAttacked ? "YES" : "NO");
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.close();
        }
    }

    enum PieceType {
        QUEEN, ROOK, BISHOP;

        public static PieceType fromChar(char c) {
            return switch (c) {
                case 'Q' -> QUEEN;
                case 'R' -> ROOK;
                case 'B' -> BISHOP;
                default -> throw new IllegalArgumentException("Invalid piece type: " + c);
            };
        }

        public boolean canAttackCardinal() {
            return this == QUEEN || this == ROOK;
        }

        public boolean canAttackDiagonal() {
            return this == QUEEN || this == BISHOP;
        }
    }

    enum Direction {
        NORTH(0, -1, true),
        SOUTH(0, 1, true),
        WEST(-1, 0, true),
        EAST(1, 0, true),
        NORTH_WEST(-1, -1, false),
        SOUTH_EAST(1, 1, false),
        NORTH_EAST(-1, 1, false),
        SOUTH_WEST(1, -1, false);

        private final int dx;
        private final int dy;
        private final boolean isCardinal;

        Direction(int dx, int dy, boolean isCardinal) {
            this.dx = dx;
            this.dy = dy;
            this.isCardinal = isCardinal;
        }

        /**
         * Determines the direction from a starting point to a target point.
         * @param dx difference in x
         * @param dy difference in y
         * @return The Direction enum, or null if not in one of the 8 valid directions.
         */
        public static Direction fromDelta(int dx, int dy) {
            if (dx == 0) {
                return dy < 0 ? NORTH : SOUTH;
            } else if (dy == 0) {
                return dx < 0 ? WEST : EAST;
            } else if (Math.abs(dx) == Math.abs(dy)) {
                if (dx < 0 && dy < 0) return NORTH_WEST;
                if (dx > 0 && dy > 0) return SOUTH_EAST;
                if (dx < 0 && dy > 0) return NORTH_EAST;
                if (dx > 0 && dy < 0) return SOUTH_WEST;
            }
            return null;
        }

        public boolean isCardinal() {
            return isCardinal;
        }
    }

    static class Piece {
        final PieceType type;
        final int x;
        final int y;

        Piece(PieceType type, int x, int y) {
            this.type = type;
            this.x = x;
            this.y = y;
        }

        int getDistanceTo(int targetX, int targetY) {
            return Math.max(Math.abs(x - targetX), Math.abs(y - targetY));
        }
    }

    static class ChessGame {
        private final FastScanner scanner;

        ChessGame(FastScanner scanner) {
            this.scanner = scanner;
        }

        public boolean solve() {
            int n = scanner.nextInt();
            int targetX = scanner.nextInt();
            int targetY = scanner.nextInt();

            Piece[] closestPiecesInDirection = new Piece[Direction.values().length];

            for (int i = 0; i < n; i++) {
                PieceType type = PieceType.fromChar(scanner.nextChar());
                int x = scanner.nextInt();
                int y = scanner.nextInt();
                Piece piece = new Piece(type, x, y);

                int dx = x - targetX;
                int dy = y - targetY;

                Direction dir = Direction.fromDelta(dx, dy);
                if (dir != null) {
                    updateClosestPiece(closestPiecesInDirection, dir, piece, targetX, targetY);
                }
            }

            return isTargetUnderAttack(closestPiecesInDirection, targetX, targetY);
        }

        private void updateClosestPiece(Piece[] closestPieces, Direction dir, Piece newPiece, int tx, int ty) {
            int index = dir.ordinal();
            if (closestPieces[index] == null || 
                newPiece.getDistanceTo(tx, ty) < closestPieces[index].getDistanceTo(tx, ty)) {
                closestPieces[index] = newPiece;
            }
        }

        private boolean isTargetUnderAttack(Piece[] closestPieces, int tx, int ty) {
            for (Piece piece : closestPieces) {
                if (piece == null) continue;

                // Re-calculate direction to determine if piece is cardinal or diagonal relative to target
                int dx = piece.x - tx;
                int dy = piece.y - ty;
                Direction dir = Direction.fromDelta(dx, dy);

                if (dir != null && dir.isCardinal()) {
                    if (piece.type.canAttackCardinal()) return true;
                } else if (dir != null) {
                    if (piece.type.canAttackDiagonal()) return true;
                }
            }
            return false;
        }
    }

    /**
     * Fast utility for reading input.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(BufferedReader reader) {
            this.reader = reader;
        }

        public String nextToken() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(nextToken());
        }

        public char nextChar() {
            return nextToken().charAt(0);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * ChessThreatDetector identifies if a target position (x0, y0) is threatened 
 * by the closest piece in any of the 8 cardinal or intercardinal directions.
 */
public class ChessThreatDetector {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            solve(reader, writer);
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            writer.flush();
            writer.close();
        }
    }

    private static void solve(FastReader reader, PrintWriter writer) throws IOException {
        int n = (int) reader.nextLong();
        long targetX = reader.nextLong();
        long targetY = reader.nextLong();

        // Map each direction to a PriorityQueue to track the closest piece in that direction
        Map<Direction, PriorityQueue<Piece>> directionQueues = new EnumMap<>(Direction.class);
        for (Direction dir : Direction.values()) {
            directionQueues.put(dir, new PriorityQueue<>());
        }

        for (int i = 0; i < n; i++) {
            String type = reader.next();
            long x = reader.nextLong();
            long y = reader.nextLong();

            Direction dir = getDirection(targetX, targetY, x, y);
            if (dir != null) {
                long distance = Math.abs(x - targetX);
                directionQueues.get(dir).add(new Piece(x, y, distance, type));
            }
        }

        boolean isThreatened = checkThreats(directionQueues);
        writer.println(isThreatened ? "YES" : "NO");
    }

    /**
     * Determines the direction of a piece relative to the target position.
     * Returns null if the piece is not on a valid line of sight (orthogonal or diagonal).
     */
    private static Direction getDirection(long targetX, long targetY, long x, long y) {
        long dx = x - targetX;
        long dy = y - targetY;

        if (dx == 0 && dy == 0) return null;

        // Check Orthogonal directions
        if (dx == 0) {
            return (dy > 0) ? Direction.NORTH : Direction.SOUTH;
        }
        if (dy == 0) {
            return (dx > 0) ? Direction.EAST : Direction.WEST;
        }

        // Check Diagonal directions
        if (Math.abs(dx) == Math.abs(dy)) {
            if (dx > 0 && dy > 0) return Direction.NORTH_EAST;
            if (dx > 0 && dy < 0) return Direction.SOUTH_EAST;
            if (dx < 0 && dy > 0) return Direction.NORTH_WEST;
            if (dx < 0 && dy < 0) return Direction.SOUTH_WEST;
        }

        return null;
    }

    /**
     * Evaluates if the closest piece in any direction is a piece capable of attacking the target.
     */
    private static boolean checkThreats(Map<Direction, PriorityQueue<Piece>> directionQueues) {
        for (Map.Entry<Direction, PriorityQueue<Piece>> entry : directionQueues.entrySet()) {
            PriorityQueue<Piece> pq = entry.getValue();
            if (!pq.isEmpty()) {
                Direction dir = entry.getKey();
                Piece closestPiece = pq.peek();
                if (closestPiece.type.equals(dir.threatType1) || 
                    closestPiece.type.equals(dir.threatType2)) {
                    return true;
                }
            }
        }
        return false;
    }

    enum Direction {
        // Orthogonal directions (Rook or Queen can attack)
        NORTH(false, "R", "Q"),
        SOUTH(false, "R", "Q"),
        EAST(false, "R", "Q"),
        WEST(false, "R", "Q"),
        // Diagonal directions (Bishop or Queen can attack)
        NORTH_EAST(true, "B", "Q"),
        NORTH_WEST(true, "B", "Q"),
        SOUTH_EAST(true, "B", "Q"),
        SOUTH_WEST(true, "B", "Q");

        final boolean isDiagonal;
        final String threatType1;
        final String threatType2;

        Direction(boolean isDiagonal, String type1, String type2) {
            this.isDiagonal = isDiagonal;
            this.threatType1 = type1;
            this.threatType2 = type2;
        }
    }

    static class Piece implements Comparable<Piece> {
        final long x;
        final long y;
        final long distance;
        final String type;

        Piece(long x, long y, long distance, String type) {
            this.x = x;
            this.y = y;
            this.distance = distance;
            this.type = type;
        }

        @Override
        public int compareTo(Piece other) {
            return Long.compare(this.distance, other.distance);
        }
    }

    /**
     * Fast I/O utility for reading input efficiently.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * Solves the chess safety problem by analyzing if a White King can 
 * capture a Black piece in a direction that is not yet "blocked" 
 * by other pieces.
 */
public class ChessGameSolver {

    public enum PieceType {
        BISHOP, ROOK, QUEEN;

        public static PieceType fromChar(char c) {
            if (c == 'B') return BISHOP;
            if (c == 'R') return ROOK;
            return QUEEN;
        }
    }

    public enum Direction {
        SOUTH_WEST,   // 1
        WEST,         // 2
        NORTH_WEST,   // 3
        NORTH,        // 4
        NORTH_EAST,   // 5
        EAST,         // 6
        SOUTH_EAST,   // 7
        SOUTH         // 8
    }

    /**
     * Represents a piece on the chessboard.
     */
    private static final class ChessPiece {
        private final PieceType type;
        private final int x;
        private final int y;

        public ChessPiece(PieceType type, int x, int y) {
            this.type = type;
            this.x = x;
            this.y = y;
        }

        public PieceType getType() { return type; }
        public int getX() { return x; }
        public int getY() { return y; }

        public long getManhattanDistance(ChessPiece other) {
            return Math.abs((long) this.x - other.x) + Math.abs((long) this.y - other.y);
        }
    }

    /**
     * Handles the logic of the chess game simulation.
     */
    private static final class ChessGame {
        private final ChessPiece whiteKing;
        private final List<ChessPiece> blackPieces;

        public ChessGame(ChessPiece whiteKing, List<ChessPiece> blackPieces) {
            this.whiteKing = whiteKing;
            this.blackPieces = new ArrayList<>(blackPieces);
            sortPiecesByProximity();
        }

        private void sortPiecesByProximity() {
            blackPieces.sort(Comparator
                .comparingLong((ChessPiece p) -> p.getManhattanDistance(whiteKing))
                .thenComparingInt(ChessPiece::getX)
                .thenComparingInt(ChessPiece::getY));
        }

        public boolean canKingCaptureUnprotectedPiece() {
            Set<Direction> visitedDirections = new HashSet<>();

            for (ChessPiece piece : blackPieces) {
                Optional<Direction> direction = getDirectionFromKing(piece);

                if (direction.isPresent()) {
                    Direction dir = direction.get();
                    // If we haven't encountered this direction yet
                    if (!visitedDirections.contains(dir)) {
                        // If the piece is currently attacking the king, the king can "beat" it
                        if (isPieceAttackingKing(piece)) {
                            return true;
                        }
                        // Otherwise, mark this direction as "visited"
                        visitedDirections.add(dir);
                    }
                }
            }
            return false;
        }

        private Optional<Direction> getDirectionFromKing(ChessPiece piece) {
            int dx = piece.getX() - whiteKing.getX();
            int dy = piece.getY() - whiteKing.getY();

            if (dx == 0) {
                return dy > 0 ? Optional.of(Direction.NORTH) : Optional.of(Direction.SOUTH);
            } else if (dy == 0) {
                return dx > 0 ? Optional.of(Direction.EAST) : Optional.of(Direction.WEST);
            } else if (Math.abs(dx) == Math.abs(dy)) {
                if (dx > 0 && dy > 0) return Optional.of(Direction.NORTH_EAST);
                if (dx > 0 && dy < 0) return Optional.of(Direction.SOUTH_EAST);
                if (dx < 0 && dy > 0) return Optional.of(Direction.NORTH_WEST);
                return Optional.of(Direction.SOUTH_WEST);
            }
            return Optional.empty();
        }

        private boolean isPieceAttackingKing(ChessPiece piece) {
            int dx = Math.abs(whiteKing.getX() - piece.getX());
            int dy = Math.abs(whiteKing.getY() - piece.getY());

            return switch (piece.getType()) {
                case BISHOP -> dx == dy;
                case ROOK -> dx == 0 || dy == 0;
                case QUEEN -> dx == dy || dx == 0 || dy == 0;
            };
        }
    }

    public static void main(String[] args) {
        try (Scanner reader = new Scanner(System.in);
             PrintWriter writer = new PrintWriter(System.out)) {

            if (!reader.hasNextInt()) return;

            int pieceCount = reader.nextInt();
            int kingX = reader.nextInt();
            int kingY = reader.nextInt();

            ChessPiece whiteKing = new ChessPiece(PieceType.QUEEN, kingX, kingY);
            List<ChessPiece> blackPieces = new ArrayList<>();

            for (int i = 0; i < pieceCount; i++) {
                char typeChar = reader.next().charAt(0);
                int x = reader.nextInt();
                int y = reader.nextInt();
                blackPieces.add(new ChessPiece(PieceType.fromChar(typeChar), x, y));
            }

            ChessGame game = new ChessGame(whiteKing, blackPieces);
            boolean result = game.canKingCaptureUnprotectedPiece();

            writer.println(result ? "YES" : "NO");
        }
    }
}

