/**
 * Represents the types of chess pieces that can pose a threat.
 */
enum PieceType {
    BISHOP('B'),
    ROOK('R'),
    QUEEN('Q'),
    NONE('Z');

    private final char symbol;

    PieceType(char symbol) {
        this.symbol = symbol;
    }

    public static PieceType fromChar(char c) {
        for (PieceType type : PieceType.values()) {
            if (type.symbol == c) {
                return type;
            }
        }
        return NONE;
    }
}

/**
 * Contains the logic to determine if a King is under threat from surrounding pieces.
 */
class ThreatDetector {
    // The 8 possible directions a piece can move from the King (Orthogonal and Diagonal)
    private static final int[] DIRECTION_X = {0, 0, 1, 1, 1, -1, -1, -1};
    private static final int[] DIRECTION_Y = {-1, 1, -1, 0, 1, -1, 0, 1};
    private static final int NUM_DIRECTIONS = 8;

    public void solve(FastReader reader, PrintWriter out) {
        int numPieces = reader.nextInt();
        long kingX = reader.nextLong();
        long kingY = reader.nextLong();

        long[] minDistances = new long[NUM_DIRECTIONS];
        PieceType[] nearestPieceTypes = new PieceType[NUM_DIRECTIONS];

        Arrays.fill(minDistances, Long.MAX_VALUE);
        Arrays.fill(nearestPieceTypes, PieceType.NONE);

        for (int i = 0; i < numPieces; i++) {
            PieceType type = PieceType.fromChar(reader.next().charAt(0));
            long pieceX = reader.nextLong();
            long pieceY = reader.nextLong();

            long diffX = pieceX - kingX;
            long diffY = pieceY - kingY;

            // If the piece is on the same tile as the king, we skip it
            if (diffX == 0 && diffY == 0) continue;

            int dirIdx = getDirectionIndex(diffX, diffY);
            if (dirIdx != -1) {
                long distance = Math.abs(diffX) + Math.abs(diffY);
                if (distance < minDistances[dirIdx]) {
                    minDistances[dirIdx] = distance;
                    nearestPieceTypes[dirIdx] = type;
                }
            }
        }

        if (isKingThreatened(nearestPieceTypes)) {
            out.println("YES");
        } else {
            out.println("NO");
        }
    }

    /**
     * Determines if the king is under threat based on the nearest piece in each direction.
     */
    private boolean isKingThreatened(PieceType[] nearestPieceTypes) {
        for (int i = 0; i < NUM_DIRECTIONS; i++) {
            PieceType type = nearestPieceTypes[i];
            if (type == PieceType.NONE) continue;

            boolean isDiagonal = (DIRECTION_X[i] != 0 && DIRECTION_Y[i] != 0);

            if (isDiagonal) {
                // Bishops and Queens threaten diagonally
                if (type == PieceType.BISHOP || type == PieceType.QUEEN) {
                    return true;
                }
            } else {
                // Rooks and Queens threaten orthogonally
                if (type == PieceType.ROOK || type == PieceType.QUEEN) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Finds which direction index the relative offset (dx, dy) belongs to.
     */
    private int getDirectionIndex(long dx, long dy) {
        long[] normalized = getNormalizedDirection(dx, dy);
        for (int i = 0; i < NUM_DIRECTIONS; i++) {
            if (DIRECTION_X[i] == normalized[0] && DIRECTION_Y[i] == normalized[1]) {
                return i;
            }
        }
        return -1;
    }

    /**
     * Reduces a vector to its simplest integer direction components using GCD.
     */
    private long[] getNormalizedDirection(long dx, long dy) {
        long common = gcd(Math.abs(dx), Math.abs(dy));
        return new long[]{dx / common, dy / common};
    }

    private long gcd(long a, long b) {
        while (b != 0) {
            a %= b;
            long temp = a;
            a = b;
            b = temp;
        }
        return a;
    }
}

