import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Solves the Anton and Chess problem by determining if the King's movement 
 * is blocked by a piece of the wrong color in any of the 8 cardinal/diagonal directions.
 */
public class AntonAndChess {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        try {
            int numberOfPieces = reader.nextInt();
            long kingX = reader.nextLong();
            long kingY = reader.nextLong();

            ChessProblem problem = new ChessProblem(kingX, kingY);

            for (int i = 0; i < numberOfPieces; i++) {
                char color = reader.nextString().charAt(0);
                long pieceX = reader.nextLong();
                long pieceY = reader.nextLong();
                problem.addPiece(color, pieceX, pieceY);
            }

            System.out.println(problem.isMovementBlocked() ? "YES" : "NO");
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /**
     * Represents a chess piece found in a specific direction.
     */
    static class Piece {
        private final char color;
        private final long distance;

        public Piece(char color, long distance) {
            this.color = color;
            this.distance = distance;
        }

        public char getColor() {
            return color;
        }

        public long getDistance() {
            return distance;
        }
    }

    /**
     * Represents one of the 8 possible directions a piece can be in relative to the King.
     */
    static class Direction {
        private final int dx;
        private final int dy;
        private final char expectedColor;

        public Direction(int dx, int dy, char expectedColor) {
            this.dx = dx;
            this.dy = dy;
            this.expectedColor = expectedColor;
        }

        /**
         * Checks if a piece at relative coordinates (rx, ry) lies in this direction.
         */
        public boolean matches(long rx, long ry) {
            // Check if the piece is collinear with the direction vector
            if (rx * dy != ry * dx) {
                return false;
            }
            // Check if the piece is in the correct quadrant/direction (sign check)
            if (dx != 0 && Long.signum(rx) != Long.signum(dx)) {
                return false;
            }
            if (dy != 0 && Long.signum(ry) != Long.signum(dy)) {
                return false;
            }
            // Ensure the piece isn't at the same position as the king
            return rx != 0 || ry != 0;
        }

        public char getExpectedColor() {
            return expectedColor;
        }
    }

    /**
     * Core logic engine for the chess problem.
     */
    static class ChessProblem {
        private final long kingX;
        private final long kingY;
        private final Piece[] closestPiecesByDirection;
        private final Direction[] directions;

        public ChessProblem(long kingX, long kingY) {
            this.kingX = kingX;
            this.kingY = kingY;
            this.closestPiecesByDirection = new Piece[8];
            this.directions = new Direction[]{
                new Direction(0, 1, 'B'),   // North
                new Direction(1, 0, 'B'),   // East
                new Direction(0, -1, 'B'),  // South
                new Direction(-1, 0, 'B'),  // West
                new Direction(1, 1, 'R'),   // NE
                new Direction(1, -1, 'R'),  // SE
                new Direction(-1, 1, 'R'),  // NW
                new Direction(-1, -1, 'R')  // SW
            };
        }

        public void addPiece(char color, long pieceX, long pieceY) {
            long relX = pieceX - kingX;
            long relY = pieceY - kingY;
            long distance = Math.max(Math.abs(relX), Math.abs(relY));

            for (int i = 0; i < directions.length; i++) {
                if (directions[i].matches(relX, relY)) {
                    if (closestPiecesByDirection[i] == null || distance < closestPiecesByDirection[i].getDistance()) {
                        closestPiecesByDirection[i] = new Piece(color, distance);
                    }
                }
            }
        }

        public boolean isMovementBlocked() {
            for (int i = 0; i < directions.length; i++) {
                Piece closest = closestPiecesByDirection[i];
                if (closest != null && closest.getColor() != directions[i].getExpectedColor()) {
                    return true;
                }
            }
            return false;
        }
    }

    /**
     * Utility class for fast I/O operations.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(java.io.InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String nextString() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(nextString());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(nextString());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A program that determines if a central coordinate (the origin) is under attack
 * by the closest chess pieces located on the cardinal or diagonal axes.
 */
public class ChessAttackChecker {

    /**
     * Represents the types of chess pieces that can move in straight lines.
     */
    enum PieceType {
        QUEEN, ROOK, BISHOP, UNKNOWN;

        /**
         * Maps a character representation to a PieceType.
         */
        static PieceType fromChar(char c) {
            return switch (c) {
                case 'Q' -> QUEEN;
                case 'R' -> ROOK;
                case 'B' -> BISHOP;
                default -> UNKNOWN;
            };
        }
    }

    /**
     * Represents the 8 valid directions (cardinal and diagonal) from the origin.
     */
    enum Direction {
        NE, E, SE, S, SW, W, NW, N, NONE;

        /**
         * Maps relative coordinates to a Direction. 
         * Returns NONE if the coordinate does not lie on an axis or diagonal.
         */
        static Direction fromCoords(long x, long y) {
            if (x > 0 && x == y) return NE;
            if (x > 0 && y == 0) return E;
            if (x > 0 && x == -y) return SE;
            if (x == 0 && y < 0) return S;
            if (x < 0 && x == y) return SW;
            if (x < 0 && y == 0) return W;
            if (x < 0 && x == -y) return NW;
            if (x == 0 && y > 0) return N;
            return NONE;
        }

        boolean isAxis() {
            return this == E || this == W || this == N || this == S;
        }

        boolean isDiagonal() {
            return this == NE || this == SE || this == SW || this == NW;
        }
    }

    /**
     * Represents a piece found at a certain distance from the origin.
     */
    record Piece(PieceType type, long distance) {}

    /**
     * Logic engine to track the closest pieces in each direction and evaluate attacks.
     */
    static class AttackAnalyzer {
        // Stores the closest piece found for each specific direction.
        private final Map<Direction, Piece> closestPieces = new EnumMap<>(Direction.class);

        /**
         * Processes a new piece. If the piece is closer to the origin in its direction
         * than any previously recorded piece, it becomes the new reference for that direction.
         */
        public void addPiece(char typeChar, long relX, long relY) {
            Direction dir = Direction.fromCoords(relX, relY);
            if (dir == Direction.NONE) return;

            PieceType type = PieceType.fromChar(typeChar);
            // Manhattan distance is a valid proxy for closeness on these specific lines.
            long distance = Math.abs(relX) + Math.abs(relY);

            Piece currentClosest = closestPieces.get(dir);
            if (currentClosest == null || distance < currentClosest.distance()) {
                closestPieces.put(dir, new Piece(type, distance));
            }
        }

        /**
         * Evaluates if the origin is currently under attack.
         */
        public boolean isOriginAttacked() {
            for (var entry : closestPieces.entrySet()) {
                Direction dir = entry.getKey();
                Piece piece = entry.getValue();

                if (piece.type() == PieceType.QUEEN) {
                    return true;
                }
                if (piece.type() == PieceType.ROOK && dir.isAxis()) {
                    return true;
                }
                if (piece.type() == PieceType.BISHOP && dir.isDiagonal()) {
                    return true;
                }
            }
            return false;
        }
    }

    public static void main(String[] args) {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter pw = new PrintWriter(new OutputStreamWriter(System.out))) {

            String line = br.readLine();
            if (line == null || line.trim().isEmpty()) return;
            int n = Integer.parseInt(line.trim());

            line = br.readLine();
            if (line == null || line.trim().isEmpty()) return;
            String[] centerCoords = line.trim().split("\\s+");
            long centerX = Long.parseLong(centerCoords[0]);
            long centerY = Long.parseLong(centerCoords[1]);

            AttackAnalyzer analyzer = new AttackAnalyzer();

            for (int i = 0; i < n; i++) {
                line = br.readLine();
                if (line == null) break;
                String[] parts = line.trim().split("\\s+");
                if (parts.length < 3) continue;

                char type = parts[0].charAt(0);
                long px = Long.parseLong(parts[1]);
                long py = Long.parseLong(parts[2]);

                // Calculate relative coordinates to the center point.
                analyzer.addPiece(type, px - centerX, py - centerY);
            }

            pw.println(analyzer.isOriginAttacked() ? "YES" : "NO");
            pw.flush();

        } catch (IOException | NumberFormatException e) {
            // In a production environment, replace with a proper logging framework.
            System.err.println("Error processing input: " + e.getMessage());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A program that determines if any "danger" type point is the closest point 
 * in any of the 8 cardinal or diagonal directions relative to a starting position.
 */
public class Main {

    // Danger type constants
    private static final String TYPE_RED = "R";
    private static final String TYPE_QUEEN = "Q";
    private static final String TYPE_BLUE = "B";

    /**
     * Represents the 8 directions around a central point.
     */
    private enum Direction {
        UP, DOWN, LEFT, RIGHT, 
        UP_LEFT, UP_RIGHT, DOWN_LEFT, DOWN_RIGHT
    }

    /**
     * Represents a point in 2D space with a specific type.
     */
    private static class Point {
        final String type;
        final long x;
        final long y;

        Point(String type, long x, long y) {
            this.type = type;
            this.x = x;
            this.y = y;
        }
    }

    /**
     * Tracks the nearest point found in a specific direction.
     */
    private static class DirectionTracker {
        Point nearestPoint = null;
        long minDistance = Long.MAX_VALUE;

        void update(Point point, long distance) {
            if (distance < minDistance) {
                minDistance = distance;
                nearestPoint = point;
            }
        }
    }

    /**
     * Main logic to process input and solve the problem.
     */
    public void solve(InputReader in, PrintWriter out) {
        int n = in.nextInt();
        long x0 = in.nextLong();
        long y0 = in.nextLong();

        Point[] points = new Point[n];
        for (int i = 0; i < n; i++) {
            points[i] = new Point(in.next(), in.nextLong(), in.nextLong());
        }

        // Initialize trackers for all 8 directions
        Map<Direction, DirectionTracker> trackers = new EnumMap<>(Direction.class);
        for (Direction d : Direction.values()) {
            trackers.put(d, new DirectionTracker());
        }

        // Single pass to find the nearest point in every direction
        for (Point p : points) {
            long dx = p.x - x0;
            long dy = p.y - y0;

            // Skip the starting point itself
            if (dx == 0 && dy == 0) continue;

            // 1. Check Cardinal Directions (Horizontal and Vertical)
            if (dx == 0) { // Vertical movement
                if (dy > 0) {
                    trackers.get(Direction.UP).update(p, dy);
                } else {
                    trackers.get(Direction.DOWN).update(p, Math.abs(dy));
                }
            } else if (dy == 0) { // Horizontal movement
                if (dx > 0) {
                    trackers.get(Direction.RIGHT).update(p, dx);
                } else {
                    trackers.get(Direction.LEFT).update(p, Math.abs(dx));
                }
            }

            // 2. Check Diagonal Directions
            if (Math.abs(dx) == Math.abs(dy)) {
                long dist = Math.abs(dx);
                if (dx < 0 && dy > 0) {
                    trackers.get(Direction.UP_LEFT).update(p, dist);
                } else if (dx > 0 && dy > 0) {
                    trackers.get(Direction.UP_RIGHT).update(p, dist);
                } else if (dx < 0 && dy < 0) {
                    trackers.get(Direction.DOWN_LEFT).update(p, dist);
                } else if (dx > 0 && dy < 0) {
                    trackers.get(Direction.DOWN_RIGHT).update(p, dist);
                }
            }
        }

        if (isDangerPresent(trackers)) {
            out.println("YES");
        } else {
            out.println("NO");
        }
    }

    /**
     * Checks if the nearest points in relevant directions contain danger types.
     */
    private boolean isDangerPresent(Map<Direction, DirectionTracker> trackers) {
        // Cardinal directions are dangerous if they are Red ('R') or Queen ('Q')
        Direction[] cardinalDirs = {Direction.UP, Direction.DOWN, Direction.LEFT, Direction.RIGHT};
        for (Direction d : cardinalDirs) {
            Point p = trackers.get(d).nearestPoint;
            if (p != null && (TYPE_RED.equals(p.type) || TYPE_QUEEN.equals(p.type))) {
                return true;
            }
        }

        // Diagonal directions are dangerous if they are Blue ('B') or Queen ('Q')
        Direction[] diagonalDirs = {
            Direction.UP_LEFT, Direction.UP_RIGHT, 
            Direction.DOWN_LEFT, Direction.DOWN_RIGHT
        };
        for (Direction d : diagonalDirs) {
            Point p = trackers.get(d).nearestPoint;
            if (p != null && (TYPE_BLUE.equals(p.type) || TYPE_QUEEN.equals(p.type))) {
                return true;
            }
        }

        return false;
    }

    public static void main(String[] args) {
        try (InputReader in = new InputReader(System.in);
             PrintWriter out = new PrintWriter(System.out)) {
            new Main().solve(in, out);
        }
    }

    /**
     * Utility class for fast input reading.
     */
    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * ChessAttackChecker determines if a given position (x, y) is under attack
 * by any pieces in the input list based on standard chess movement rules:
 * - Rooks and Queens attack horizontally and vertically.
 * - Bishops and Queens attack diagonally.
 */
public class ChessAttackChecker {

    // Standard Chess Piece Types
    private static final char QUEEN = 'Q';
    private static final char ROOK = 'R';
    private static final char BISHOP = 'B';

    // Directional metadata: 0-3 are Orthogonal (Rook/Queen), 4-7 are Diagonal (Bishop/Queen)
    private static final boolean[] IS_DIAGONAL_DIRECTION = {
        false, false, false, false, // Orthogonal
        true,  true,  true,  true   // Diagonal
    };

    /**
     * Represents the closest piece found in a specific direction.
     */
    static class ClosestPiece {
        char type = ' ';
        int distance = Integer.MAX_VALUE;

        /**
         * Updates the stored piece if the new piece is closer than the current one.
         */
        void updateIfCloser(char type, int distance) {
            if (distance < this.distance) {
                this.distance = distance;
                this.type = type;
            }
        }
    }

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        try {
            int n = reader.nextInt();
            int startX = reader.nextInt();
            int startY = reader.nextInt();

            // We track the closest piece in 8 possible directions
            ClosestPiece[] directions = new ClosestPiece[8];
            for (int i = 0; i < 8; i++) {
                directions[i] = new ClosestPiece();
            }

            for (int i = 0; i < n; i++) {
                char pieceType = reader.nextChar();
                int tx = reader.nextInt();
                int ty = reader.nextInt();

                int dx = tx - startX;
                int dy = ty - startY;

                int dirIdx = getDirectionIndex(dx, dy);
                if (dirIdx != -1) {
                    // Using Chebyshev distance as a proxy for distance in these directions
                    int dist = Math.max(Math.abs(dx), Math.abs(dy));
                    directions[dirIdx].updateIfCloser(pieceType, dist);
                }
            }

            if (isPositionUnderAttack(directions)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }

        } catch (Exception e) {
            // In a production environment, use a proper logger
        }
    }

    /**
     * Maps the relative coordinates (dx, dy) to a direction index 0-7.
     * 0-3: Orthogonal (Up, Down, Right, Left)
     * 4-7: Diagonal (UR, DR, UL, DL)
     */
    private static int getDirectionIndex(int dx, int dy) {
        if (dx == 0 && dy > 0) return 0;  // Vertical Up
        if (dx == 0 && dy < 0) return 1;  // Vertical Down
        if (dx > 0 && dy == 0) return 2;  // Horizontal Right
        if (dx < 0 && dy == 0) return 3;  // Horizontal Left
        if (dx > 0 && dy > 0) return 4;   // Diagonal UR
        if (dx > 0 && dy < 0) return 5;   // Diagonal DR
        if (dx < 0 && dy > 0) return 6;   // Diagonal UL
        if (dx < 0 && dy < 0) return 7;   // Diagonal DL
        return -1; // Not in a valid attacking line (e.g., same position)
    }

    /**
     * Checks if the closest piece in any direction can attack the start position.
     */
    private static boolean isPositionUnderAttack(ClosestPiece[] directions) {
        for (int i = 0; i < 8; i++) {
            char type = directions[i].type;
            if (type == ' ') continue;

            if (IS_DIAGONAL_DIRECTION[i]) {
                // Diagonal lines are attacked by Bishops or Queens
                if (type == BISHOP || type == QUEEN) return true;
            } else {
                // Orthogonal lines are attacked by Rooks or Queens
                if (type == ROOK || type == QUEEN) return true;
            }
        }
        return false;
    }

    /**
     * Efficient reader for handling large inputs.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public char nextChar() {
            return next().charAt(0);
        }
    }
}

import java.util.*;

/**
 * A refactored version of the Anton and Chess program.
 * This program determines if a chess piece (King) can move based on the 
 * closest piece found in any of the 8 possible directions.
 */
public class AntonAndChess {

    private static final char RED = 'R';
    private static final char BLACK = 'B';

    /**
     * Represents the 8 possible movement directions for a King.
     */
    private enum Direction {
        UP(0, 1), DOWN(0, -1), LEFT(-1, 0), RIGHT(1, 0),
        UL(-1, 1), UR(1, 1), DL(-1, -1), DR(1, -1);

        private final int dx;
        private final int dy;

        Direction(int dx, int dy) {
            this.dx = dx;
            this.dy = dy;
        }

        /**
         * Determines the Direction enum based on relative coordinate changes.
         * 
         * @param deltaX Change in x-coordinate.
         * @param deltaY Change in y-coordinate.
         * @return The corresponding Direction, or null if the move is invalid.
         */
        public static Direction fromDelta(int deltaX, int deltaY) {
            int signX = Integer.compare(deltaX, 0);
            int signY = Integer.compare(deltaY, 0);

            for (Direction dir : values()) {
                if (dir.dx == signX && dir.dy == signY) {
                    return dir;
                }
            }
            return null;
        }

        public boolean isDiagonal() {
            return dx != 0 && dy != 0;
        }
    }

    /**
     * Represents a chess piece on the board.
     */
    private static class Piece {
        final char color;
        final int x;
        final int y;

        Piece(char color, int x, int y) {
            this.color = color;
            this.x = x;
            this.y = y;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int n = scanner.nextInt();
        int targetX = scanner.nextInt();
        int targetY = scanner.nextInt();

        solve(n, targetX, targetY, scanner);
        scanner.close();
    }

    /**
     * Processes the input and executes the game logic.
     */
    private static void solve(int n, int targetX, int targetY, Scanner scanner) {
        // Stores the closest piece found for each of the 8 directions.
        Map<Direction, Piece> closestPieces = new EnumMap<>(Direction.class);
        // Stores the minimum distance found for each direction to compare proximity.
        Map<Direction, Integer> minDistanceMap = new EnumMap<>(Direction.class);

        for (int i = 0; i < n; i++) {
            char color = scanner.next().charAt(0);
            int px = scanner.nextInt();
            int py = scanner.nextInt();

            int dx = px - targetX;
            int dy = py - targetY;

            // Check if the piece lies on the same row, column, or diagonal.
            if (isMovementPath(dx, dy)) {
                Direction dir = Direction.fromDelta(dx, dy);
                if (dir != null) {
                    int distance = Math.max(Math.abs(dx), Math.abs(dy));

                    // Update if this piece is the closest one found so far in this direction.
                    if (distance < minDistanceMap.getOrDefault(dir, Integer.MAX_VALUE)) {
                        minDistanceMap.put(dir, distance);
                        closestPieces.put(dir, new Piece(color, px, py));
                    }
                }
            }
        }

        boolean canMove = evaluateMovementPossibility(closestPieces);
        System.out.println(canMove ? "YES" : "NO");
    }

    /**
     * Validates if the piece is in a valid direction (straight or diagonal).
     */
    private static boolean isMovementPath(int dx, int dy) {
        return dx == 0 || dy == 0 || Math.abs(dx) == Math.abs(dy);
    }

    /**
     * Evaluates the closest pieces to determine if any allow a valid move.
     * Logic follows the original requirement: 
     * - On diagonals, a move is valid if the closest piece is not RED.
     * - On straight lines, a move is valid if the closest piece is not BLACK.
     */
    private static boolean evaluateMovementPossibility(Map<Direction, Piece> closestPieces) {
        for (Map.Entry<Direction, Piece> entry : closestPieces.entrySet()) {
            Direction dir = entry.getKey();
            Piece piece = entry.getValue();

            if (dir.isDiagonal()) {
                if (piece.color != RED) {
                    return true;
                }
            } else {
                if (piece.color != BLACK) {
                    return true;
                }
            }
        }
        return false;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.StringTokenizer;

/**
 * A program that determines if at least one direction from a target point 
 * is "safe" based on the type of the closest obstacle in that direction.
 */
public class DirectionalObstacleTracker {

    // Constants representing obstacle types
    private static final char TYPE_RED = 'R';
    private static final char TYPE_BLUE = 'B';

    public static void main(String[] args) {
        FastReader reader = new FastReader();

        try {
            // Read number of obstacles
            String nInput = reader.next();
            if (nInput == null) return;
            int obstacleCount = Integer.parseInt(nInput);

            // Read target coordinates
            int targetX = reader.nextInt();
            int targetY = reader.nextInt();

            DirectionalTracker tracker = new DirectionalTracker();

            // Process each obstacle
            for (int i = 0; i < obstacleCount; i++) {
                char type = reader.next().charAt(0);
                int obsX = reader.nextInt();
                int obsY = reader.nextInt();

                tracker.processObstacle(type, obsX, obsY, targetX, targetY);
            }

            // Output result
            System.out.println(tracker.isAnyDirectionSafe() ? "YES" : "NO");

        } catch (Exception e) {
            // In a production environment, use a logger to record the error.
            // For this implementation, we exit gracefully on parsing errors.
        }
    }

    /**
     * DirectionalTracker maintains information about the closest obstacle 
     * found in each of the 8 cardinal and intercardinal directions.
     */
    private static class DirectionalTracker {
        private static final int NUM_DIRECTIONS = 9; // 8 directions + 1 center point
        private final int[] minDistance = new int[NUM_DIRECTIONS];
        private final boolean[] isSafeDirection = new boolean[NUM_DIRECTIONS];

        public DirectionalTracker() {
            Arrays.fill(minDistance, Integer.MAX_VALUE);
        }

        /**
         * Evaluates an obstacle and updates the tracker if this obstacle 
         * is the closest one found so far in its respective direction.
         */
        public void processObstacle(char type, int obsX, int obsY, int targetX, int targetY) {
            int deltaX = targetX - obsX;
            int deltaY = targetY - obsY;

            int absX = Math.abs(deltaX);
            int absY = Math.abs(deltaY);

            // An obstacle is relevant only if it lies on the same row, column, or diagonal.
            if (deltaX == 0 || deltaY == 0 || absX == absY) {
                int signX = Integer.compare(deltaX, 0);
                int signY = Integer.compare(deltaY, 0);
                int dirIndex = calculateDirectionIndex(signX, signY);
                int distance = Math.max(absX, absY);

                if (distance < minDistance[dirIndex]) {
                    minDistance[dirIndex] = distance;

                    // Safety Logic:
                    // If on a diagonal, Blue is considered "safe".
                    // If on a straight axis, Red is considered "safe".
                    boolean isDiagonal = (absX == absY);
                    isSafeDirection[dirIndex] = isDiagonal ? (type != TYPE_RED) : (type != TYPE_BLUE);
                }
            }
        }

        /**
         * Maps direction vectors (dx, dy) where dx, dy ∈ {-1, 0, 1} 
         * to a unique index from 0 to 8.
         */
        private int calculateDirectionIndex(int dx, int dy) {
            return (dy * 3) + dx + 4;
        }

        /**
         * @return true if at least one direction is considered safe.
         */
        public boolean isAnyDirectionSafe() {
            for (boolean safe : isSafeDirection) {
                if (safe) return true;
            }
            return false;
        }
    }

    /**
     * Fast utility for reading input from System.in using BufferedReader and StringTokenizer.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader() {
            this.reader = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            return (next != null) ? Integer.parseInt(next) : 0;
        }
    }
}

import java.util.*;

/**
 * InfiniteChess determines if a King is in check on an infinite chessboard.
 * A King is in check if the closest piece in any of the 8 cardinal or 
 * ordinal directions is an attacking piece.
 */
public class InfiniteChess {

    /**
     * Represents the types of chess pieces and their movement capabilities.
     */
    public enum PieceType {
        KING('K', false, false),
        QUEEN('Q', true, true),
        ROOK('R', true, false),
        BISHOP('B', false, true);

        private final char letter;
        private final boolean movesInLines;
        private final boolean movesInDiagonals;

        private static final Map<Character, PieceType> BY_LETTER = new HashMap<>();

        static {
            for (PieceType type : values()) {
                BY_LETTER.put(type.letter, type);
            }
        }

        PieceType(char letter, boolean movesInLines, boolean movesInDiagonals) {
            this.letter = letter;
            this.movesInLines = movesInLines;
            this.movesInDiagonals = movesInDiagonals;
        }

        public static PieceType fromChar(char letter) {
            return BY_LETTER.get(letter);
        }

        /**
         * Determines if this piece type can attack a target at (kx, ky) from (px, py).
         */
        public boolean attacks(long kx, long ky, long px, long py) {
            long dx = px - kx;
            long dy = py - ky;

            boolean isLine = (dx == 0 || dy == 0);
            boolean isDiagonal = (Math.abs(dx) == Math.abs(dy));

            return (movesInLines && isLine) || (movesInDiagonals && isDiagonal);
        }
    }

    /**
     * Represents the 8 directions on a 2D plane.
     */
    public enum Direction {
        UP(0, 1), DOWN(0, -1), LEFT(-1, 0), RIGHT(1, 0),
        UP_LEFT(-1, 1), UP_RIGHT(1, 1), DOWN_LEFT(-1, -1), DOWN_RIGHT(1, -1);

        private final int dx;
        private final int dy;

        Direction(int dx, int dy) {
            this.dx = dx;
            this.dy = dy;
        }

        /**
         * Maps coordinate differences to a Direction enum constant.
         */
        public static Direction fromDelta(long dx, long dy) {
            int sx = Long.compare(dx, 0);
            int sy = Long.compare(dy, 0);

            // If dx and dy are both 0, the piece is on the same square as the king
            if (sx == 0 && sy == 0) return null;

            for (Direction d : values()) {
                if (d.dx == sx && d.dy == sy) {
                    return d;
                }
            }
            return null;
        }
    }

    /**
     * Represents a piece on the board with its type and coordinates.
     */
    public static class Piece {
        private final PieceType type;
        private final long x;
        private final long y;

        public Piece(PieceType type, long x, long y) {
            this.type = type;
            this.x = x;
            this.y = y;
        }

        public PieceType getType() { return type; }
        public long getX() { return x; }
        public long getY() { return y; }

        @Override
        public String toString() {
            return type.letter + "(" + x + "," + y + ")";
        }
    }

    /**
     * Determines if the king is in check.
     * This method iterates through all pieces exactly once.
     * Time Complexity: O(N)
     * Space Complexity: O(1) (fixed size arrays for 8 directions)
     */
    public static boolean isKingInCheck(Piece king, List<Piece> pieces) {
        int dirCount = Direction.values().length;
        Piece[] closestInDirection = new Piece[dirCount];
        long[] minDistanceInDirection = new long[dirCount];
        Arrays.fill(minDistanceInDirection, Long.MAX_VALUE);

        for (Piece p : pieces) {
            long dx = p.getX() - king.getX();
            long dy = p.getY() - king.getY();

            Direction dir = Direction.fromDelta(dx, dy);
            if (dir == null) continue;

            // Using Chebyshev distance as a proxy for distance on lines/diagonals
            long dist = Math.max(Math.abs(dx), Math.abs(dy));
            int dirIdx = dir.ordinal();

            if (dist < minDistanceInDirection[dirIdx]) {
                minDistanceInDirection[dirIdx] = dist;
                closestInDirection[dirIdx] = p;
            }
        }

        // Check if the closest piece in any direction is an attacker
        for (Piece closest : closestInDirection) {
            if (closest != null && closest.getType().attacks(king.getX(), king.getY(), closest.getX(), closest.getY())) {
                return true;
            }
        }

        return false;
    }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;

            int n = scanner.nextInt();
            long kx = scanner.nextLong();
            long ky = scanner.nextLong();
            Piece king = new Piece(PieceType.KING, kx, ky);

            List<Piece> pieces = new ArrayList<>(n);
            for (int i = 0; i < n; i++) {
                String typeStr = scanner.next();
                char typeChar = typeStr.charAt(0);
                long px = scanner.nextLong();
                long py = scanner.nextLong();

                PieceType type = PieceType.fromChar(typeChar);
                if (type != null) {
                    pieces.add(new Piece(type, px, py));
                }
            }

            if (isKingInCheck(king, pieces)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        } catch (NoSuchElementException e) {
            // Handle cases with malformed or insufficient input
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.EnumMap;
import java.util.Map;
import java.util.StringTokenizer;

/**
 * A program to detect if a target position on a grid is under threat 
 * by specific chess pieces (Rook, Bishop, or Queen) in the nearest direction.
 */
public class ChessThreatDetector {

    public enum Direction {
        TOP(0, 1, true),
        BOTTOM(0, -1, true),
        LEFT(-1, 0, true),
        RIGHT(1, 0, true),
        TOP_LEFT(-1, 1, false),
        TOP_RIGHT(1, 1, false),
        BOTTOM_LEFT(-1, -1, false),
        BOTTOM_RIGHT(1, -1, false);

        final int dx;
        final int dy;
        final boolean isCardinal;

        Direction(int dx, int dy, boolean isCardinal) {
            this.dx = dx;
            this.dy = dy;
            this.isCardinal = isCardinal;
        }

        /**
         * Determines the direction based on the relative coordinate offset.
         */
        public static Direction fromOffset(int dx, int dy) {
            if (dx == 0) {
                return dy > 0 ? TOP : BOTTOM;
            } else if (dy == 0) {
                return dx > 0 ? RIGHT : LEFT;
            } else if (Math.abs(dx) == Math.abs(dy)) {
                if (dx > 0 && dy > 0) return TOP_RIGHT;
                if (dx < 0 && dy < 0) return BOTTOM_LEFT;
                if (dx > 0 && dy < 0) return BOTTOM_RIGHT;
                return TOP_LEFT;
            }
            return null;
        }
    }

    /**
     * Represents the closest piece found in a specific direction.
     */
    private static class ClosestPiece {
        char type;
        int distance;

        ClosestPiece(char type, int distance) {
            this.type = type;
            this.distance = distance;
        }
    }

    public static void main(String[] args) {
        FastReader reader = new FastReader();

        try {
            int n = reader.nextInt();
            int targetX = reader.nextInt();
            int targetY = reader.nextInt();

            Map<Direction, ClosestPiece> closestPieces = new EnumMap<>(Direction.class);

            for (int i = 0; i < n; i++) {
                char type = reader.next().charAt(0);
                int x = reader.nextInt();
                int y = reader.nextInt();

                int dx = x - targetX;
                int dy = y - targetY;

                Direction dir = Direction.fromOffset(dx, dy);
                if (dir != null) {
                    int distance = Math.max(Math.abs(dx), Math.abs(dy));
                    updateClosestPiece(closestPieces, dir, type, distance);
                }
            }

            if (isUnderThreat(closestPieces)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }

        } catch (Exception e) {
            // Handle potential input errors gracefully
        }
    }

    /**
     * Updates the map with the piece if it is closer than the currently recorded one.
     */
    private static void updateClosestPiece(Map<Direction, ClosestPiece> map, Direction dir, char type, int distance) {
        if (!map.containsKey(dir) || distance < map.get(dir).distance) {
            map.put(dir, new ClosestPiece(type, distance));
        }
    }

    /**
     * Checks if any of the closest pieces satisfy the threat conditions:
     * - Rook (R) in cardinal directions.
     * - Bishop (B) in diagonal directions.
     * - Queen (Q) in any direction.
     */
    private static boolean isUnderThreat(Map<Direction, ClosestPiece> closestPieces) {
        for (Map.Entry<Direction, ClosestPiece> entry : closestPieces.entrySet()) {
            Direction dir = entry.getKey();
            ClosestPiece piece = entry.getValue();

            if (piece.type == 'Q') {
                return true;
            } else if (piece.type == 'R' && dir.isCardinal) {
                return true;
            } else if (piece.type == 'B' && !dir.isCardinal) {
                return true;
            }
        }
        return false;
    }

    /**
     * Efficient reader for large inputs.
     */
    private static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader() {
            reader = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

/**
 * A program to determine if a 4x4 grid contains a "winning" segment.
 * A winning segment is defined as three consecutive cells in a line 
 * (horizontal, vertical, or diagonal) containing exactly two 'x's and one '.'.
 */
public class Main {

    private static final int GRID_SIZE = 4;
    private static final char PLAYER_CHAR = 'x';
    private static final char EMPTY_CHAR = '.';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] grid = readGrid(scanner, GRID_SIZE);
        scanner.close();

        if (hasWinningSegment(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Reads the grid from standard input.
     */
    private static char[][] readGrid(Scanner scanner, int size) {
        char[][] grid = new char[size][size];
        for (int i = 0; i < size; i++) {
            if (scanner.hasNext()) {
                grid[i] = scanner.next().toCharArray();
            }
        }
        return grid;
    }

    /**
     * Iterates through all possible 3-cell segments in the grid.
     * Checks horizontal, vertical, and both diagonal directions.
     */
    private static boolean hasWinningSegment(char[][] grid) {
        // Direction vectors: horizontal, vertical, diagonal down-right, diagonal down-left
        int[] dRow = {0, 1, 1, 1};
        int[] dCol = {1, 0, 1, -1};

        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                // Try all 4 directions from the current cell
                for (int dir = 0; dir < 4; dir++) {
                    int r2 = r + dRow[dir];
                    int c2 = c + dCol[dir];
                    int r3 = r + 2 * dRow[dir];
                    int c3 = c + 2 * dCol[dir];

                    // If the end of the 3-cell segment is within bounds, check the pattern
                    if (isWithinBounds(r3, c3)) {
                        if (isPatternMatch(grid[r][c], grid[r2][c2], grid[r3][c3])) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a segment of three cells contains exactly two 'x' and one '.'.
     */
    private static boolean isPatternMatch(char c1, char c2, char c3) {
        int xCount = 0;
        int dotCount = 0;
        char[] segment = {c1, c2, c3};

        for (char cell : segment) {
            if (cell == PLAYER_CHAR) {
                xCount++;
            } else if (cell == EMPTY_CHAR) {
                dotCount++;
            }
        }

        return xCount == 2 && dotCount == 1;
    }

    /**
     * Validates if a coordinate is within the grid boundaries.
     */
    private static boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
    }
}

import java.util.Scanner;

/**
 * A utility to analyze a 4x4 Tic-Tac-Toe board to determine if a player 'x'
 * can win in a single move.
 */
public class TicTacToeAnalyzer {

    private static final int GRID_SIZE = 4;
    private static final int WIN_LENGTH = 3;
    private static final char PLAYER_CHAR = 'x';
    private static final char EMPTY_CHAR = '.';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] board = new char[GRID_SIZE][GRID_SIZE];

        try {
            // Read the 4x4 grid
            for (int i = 0; i < GRID_SIZE; i++) {
                String line = scanner.next();
                if (line.length() < GRID_SIZE) {
                    throw new IllegalArgumentException("Each row must have " + GRID_SIZE + " characters.");
                }
                for (int j = 0; j < GRID_SIZE; j++) {
                    board[i][j] = line.charAt(j);
                }
            }

            // Output result
            if (canWinInOneMove(board)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }

        } catch (Exception e) {
            System.err.println("Error processing input: " + e.getMessage());
        } finally {
            scanner.close();
        }
    }

    /**
     * Determines if there is any valid 3-length line (horizontal, vertical, 
     * or diagonal) that contains exactly two 'x's and one empty space.
     *
     * @param board The 4x4 character grid.
     * @return true if a winning move is possible, false otherwise.
     */
    public static boolean canWinInOneMove(char[][] board) {
        // 1. Check all possible horizontal segments of length 3
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c <= GRID_SIZE - WIN_LENGTH; c++) {
                if (isWinningPattern(board[r][c], board[r][c + 1], board[r][c + 2])) {
                    return true;
                }
            }
        }

        // 2. Check all possible vertical segments of length 3
        for (int c = 0; c < GRID_SIZE; c++) {
            for (int r = 0; r <= GRID_SIZE - WIN_LENGTH; r++) {
                if (isWinningPattern(board[r][c], board[r + 1][c], board[r + 2][c])) {
                    return true;
                }
            }
        }

        // 3. Check all possible Down-Right diagonal segments of length 3
        for (int r = 0; r <= GRID_SIZE - WIN_LENGTH; r++) {
            for (int c = 0; c <= GRID_SIZE - WIN_LENGTH; c++) {
                if (isWinningPattern(board[r][c], board[r + 1][c + 1], board[r + 2][c + 2])) {
                    return true;
                }
            }
        }

        // 4. Check all possible Down-Left diagonal segments of length 3
        for (int r = 0; r <= GRID_SIZE - WIN_LENGTH; r++) {
            for (int c = WIN_LENGTH - 1; c < GRID_SIZE; c++) {
                if (isWinningPattern(board[r][c], board[r + 1][c - 1], board[r + 2][c - 2])) {
                    return true;
                }
            }
        }

        return false;
    }

    /**
     * Evaluates if a triplet of cells qualifies as a winning pattern.
     * A winning pattern consists of exactly two 'x' characters and one '.'.
     *
     * @param c1 First cell character.
     * @param c2 Second cell character.
     * @param c3 Third cell character.
     * @return true if the pattern is a match.
     */
    private static boolean isWinningPattern(char c1, char c2, char c3) {
        int playerCounter = 0;
        int emptyCounter = 0;

        char[] cells = {c1, c2, c3};
        for (char cell : cells) {
            if (cell == PLAYER_CHAR) {
                playerCounter++;
            } else if (cell == EMPTY_CHAR) {
                emptyCounter++;
            }
        }

        // A winning move is possible if there are 2 'x's and 1 empty spot
        return playerCounter == 2 && emptyCounter == 1;
    }
}

import java.util.Scanner;

/**
 * A program to analyze a 4x4 Tic-Tac-Toe board for a specific winning pattern.
 * The pattern is defined as exactly two 'x' marks and one empty '.' spot
 * appearing consecutively in a row, column, or diagonal.
 */
public class TicTacToe {

    // Constants to improve maintainability and remove magic numbers
    private static final int BOARD_SIZE = 4;
    private static final int WIN_LENGTH = 3;
    private static final char MARK_X = 'x';
    private static final char EMPTY_SPOT = '.';

    public static void main(String[] args) {
        char[][] board = readBoard();

        if (hasWinningPattern(board)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Reads the 4x4 grid from standard input.
     * 
     * @return A 2D character array representing the board.
     */
    private static char[][] readBoard() {
        Scanner scanner = new Scanner(System.in);
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];

        for (int i = 0; i < BOARD_SIZE; i++) {
            if (scanner.hasNextLine()) {
                String line = scanner.nextLine();
                for (int j = 0; j < BOARD_SIZE; j++) {
                    // Ensure we don't crash if the input line is shorter than BOARD_SIZE
                    board[i][j] = (j < line.length()) ? line.charAt(j) : ' ';
                }
            }
        }
        // Note: In a production environment, we would use try-with-resources for the scanner
        return board;
    }

    /**
     * Scans the entire board for the target pattern using directional vectors.
     * 
     * @param board The 2D character array.
     * @return true if the pattern is found, false otherwise.
     */
    private static boolean hasWinningPattern(char[][] board) {
        // Possible movement vectors: {row_delta, col_delta}
        int[][] directions = {
            {0, 1},  // Horizontal
            {1, 0},  // Vertical
            {1, 1},  // Diagonal (Top-Left to Bottom-Right)
            {1, -1}  // Diagonal (Top-Right to Bottom-Left)
        };

        for (int r = 0; r < BOARD_SIZE; r++) {
            for (int c = 0; c < BOARD_SIZE; c++) {
                for (int[] dir : directions) {
                    if (isValidSequence(r, c, dir[0], dir[1])) {
                        if (isPatternMatch(board, r, c, dir[0], dir[1])) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Validates if a sequence of WIN_LENGTH starting at (r, c) in direction (dr, dc)
     * stays within the bounds of the board.
     */
    private static boolean isValidSequence(int r, int c, int dr, int dc) {
        int endR = r + (WIN_LENGTH - 1) * dr;
        int endC = c + (WIN_LENGTH - 1) * dc;

        return endR >= 0 && endR < BOARD_SIZE &&
               endC >= 0 && endC < BOARD_SIZE;
    }

    /**
     * Checks if the sequence of cells contains exactly two 'x' and one '.'.
     * 
     * @param board The 2D character array.
     * @param r Starting row.
     * @param c Starting column.
     * @param dr Row direction delta.
     * @param dc Column direction delta.
     * @return true if the pattern matches.
     */
    private static boolean isPatternMatch(char[][] board, int r, int c, int dr, int dc) {
        int xCount = 0;
        int dotCount = 0;

        for (int i = 0; i < WIN_LENGTH; i++) {
            char current = board[r + i * dr][c + i * dc];
            if (current == MARK_X) {
                xCount++;
            } else if (current == EMPTY_SPOT) {
                dotCount++;
            }
        }

        return xCount == 2 && dotCount == 1;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * Application to detect winning patterns in a grid.
 */
public class Main {
    private static final int BOARD_SIZE = 4;

    public static void main(String[] args) {
        char[][] board = readBoard(BOARD_SIZE);

        if (board == null) {
            System.out.println("Invalid input.");
            return;
        }

        if (BoardAnalyzer.hasWinningPattern(board)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Reads the board from standard input.
     * @param size The dimension of the square board.
     * @return A 2D char array representing the board.
     */
    private static char[][] readBoard(int size) {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            char[][] board = new char[size][size];
            for (int i = 0; i < size; i++) {
                String line = br.readLine();
                if (line == null) return null;

                // Ensure we only take the characters up to the board size
                char[] row = line.toCharArray();
                for (int j = 0; j < size; j++) {
                    board[i][j] = (j < row.length) ? row[j] : ' ';
                }
            }
            return board;
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
            return null;
        }
    }
}

/**
 * Logic handler for analyzing board patterns.
 */
class BoardAnalyzer {
    private static final int WINDOW_SIZE = 3;
    private static final char TARGET_X = 'x';
    private static final char TARGET_DOT = '.';

    private static final int REQ_X_COUNT = 2;
    private static final int REQ_DOT_COUNT = 1;

    /**
     * Checks if the board contains any 3x3 subgrid that has a winning line.
     * @param board The 4x4 character board.
     * @return true if a winning pattern is found.
     */
    public static boolean hasWinningPattern(char[][] board) {
        int maxStart = board.length - WINDOW_SIZE;

        // Iterate through all possible top-left corners of a 3x3 window
        for (int row = 0; row <= maxStart; row++) {
            for (int col = 0; col <= maxStart; col++) {
                if (isWinningWindow(board, row, col)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Checks if a specific 3x3 window contains a winning row, column, or diagonal.
     */
    private static boolean isWinningWindow(char[][] board, int r, int c) {
        // Check Rows
        for (int i = 0; i < WINDOW_SIZE; i++) {
            if (isWinningLine(board[r + i][c], board[r + i][c + 1], board[r + i][c + 2])) {
                return true;
            }
        }

        // Check Columns
        for (int j = 0; j < WINDOW_SIZE; j++) {
            if (isWinningLine(board[r][c + j], board[r + 1][c + j], board[r + 2][c + j])) {
                return true;
            }
        }

        // Check Main Diagonal (Top-Left to Bottom-Right)
        if (isWinningLine(board[r][c], board[r + 1][c + 1], board[r + 2][c + 2])) {
            return true;
        }

        // Check Anti-Diagonal (Top-Right to Bottom-Left)
        if (isWinningLine(board[r][c + 2], board[r + 1][c + 1], board[r + 2][c])) {
            return true;
        }

        return false;
    }

    /**
     * Determines if a sequence of three characters meets the winning criteria.
     */
    private static boolean isWinningLine(char c1, char c2, char c3) {
        int xCount = 0;
        int dotCount = 0;

        char[] line = {c1, c2, c3};
        for (char cell : line) {
            if (cell == TARGET_X) {
                xCount++;
            } else if (cell == TARGET_DOT) {
                dotCount++;
            }
        }

        return xCount == REQ_X_COUNT && dotCount == REQ_DOT_COUNT;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * A program that detects if a specific pattern exists in a 4x4 grid.
 * The pattern is defined as a line of 3 cells containing exactly two 'x's and one '.'
 */
public class Main {

    private static final int GRID_SIZE = 4;
    private static final int LINE_LENGTH = 3;
    private static final int REQUIRED_X_COUNT = 2;
    private static final int REQUIRED_DOT_COUNT = 1;

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        char[][] grid = readGrid(reader, GRID_SIZE);

        if (hasWinningPattern(grid)) {
            writer.println("YES");
        } else {
            writer.println("NO");
        }

        writer.flush();
        writer.close();
    }

    /**
     * Reads the grid from the input stream.
     */
    private static char[][] readGrid(FastReader reader, int size) {
        char[][] grid = new char[size][size];
        for (int i = 0; i < size; i++) {
            grid[i] = reader.next().toCharArray();
        }
        return grid;
    }

    /**
     * Scans the grid for the winning pattern in all directions.
     */
    private static boolean hasWinningPattern(char[][] grid) {
        // Direction vectors: Horizontal, Vertical, Diagonal Down-Right, Diagonal Down-Left
        int[][] directions = {
            {0, 1},  // Horizontal
            {1, 0},  // Vertical
            {1, 1},  // Diagonal Down-Right
            {1, -1}  // Diagonal Down-Left
        };

        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                for (int[] dir : directions) {
                    if (checkLineAt(grid, r, c, dir[0], dir[1])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a line starting at (startRow, startCol) moving in direction (dr, dc)
     * satisfies the winning condition.
     */
    private static boolean checkLineAt(char[][] grid, int startRow, int startCol, int dr, int dc) {
        int xCount = 0;
        int dotCount = 0;

        for (int i = 0; i < LINE_LENGTH; i++) {
            int currR = startRow + (i * dr);
            int currC = startCol + (i * dc);

            if (isOutOfBounds(currR, currC)) {
                return false;
            }

            char cell = grid[currR][currC];
            if (cell == 'x') {
                xCount++;
            } else if (cell == '.') {
                dotCount++;
            }
        }

        return xCount == REQUIRED_X_COUNT && dotCount == REQUIRED_DOT_COUNT;
    }

    private static boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= GRID_SIZE || c < 0 || c >= GRID_SIZE;
    }

    /**
     * Utility class for fast I/O operations.
     */
    public static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A utility to find specific character patterns within a 4x4 grid.
 * The pattern is defined as a sequence of 3 cells (horizontal, vertical, or diagonal)
 * that contains no 'o' characters and at most one '.' character.
 */
public class PatternFinder {

    private static final int GRID_SIZE = 4;
    private static final int SEQUENCE_LENGTH = 3;

    // Represents the 8 possible directions: N, NE, E, SE, S, SW, W, NW
    private static final int[] ROW_DELTAS = {-1, -1, 0, 1, 1, 1, 0, -1};
    private static final int[] COL_DELTAS = {0, 1, 1, 1, 0, -1, -1, -1};

    public static void main(String[] args) {
        PatternFinder finder = new PatternFinder();
        finder.run();
    }

    /**
     * Entry point for the application logic.
     */
    public void run() {
        InputReader reader = new InputReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            solve(reader, writer);
        } finally {
            writer.close();
        }
    }

    /**
     * Orchestrates the reading of the grid and the execution of the pattern search.
     */
    private void solve(InputReader reader, PrintWriter writer) {
        char[][] grid = readGrid(reader);

        if (containsValidSequence(grid)) {
            writer.println("YES");
        } else {
            writer.println("NO");
        }
    }

    /**
     * Reads the grid from the input source.
     */
    private char[][] readGrid(InputReader reader) {
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            String row = reader.next();
            if (row != null) {
                grid[i] = row.toCharArray();
            }
        }
        return grid;
    }

    /**
     * Iterates through every cell and every direction to find a valid pattern.
     * 
     * @param grid The 2D grid to search.
     * @return true if a valid sequence is found, false otherwise.
     */
    private boolean containsValidSequence(char[][] grid) {
        for (int row = 0; row < GRID_SIZE; row++) {
            for (int col = 0; col < GRID_SIZE; col++) {
                for (int dir = 0; dir < 8; dir++) {
                    if (isPatternAt(grid, row, col, ROW_DELTAS[dir], COL_DELTAS[dir])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a valid sequence starts at the given coordinate and moves in a specific direction.
     * 
     * @param grid The 2D grid.
     * @param startRow Starting row index.
     * @param startCol Starting column index.
     * @param rowDelta Change in row per step.
     * @param colDelta Change in column per step.
     * @return true if the sequence meets the criteria.
     */
    private boolean isPatternAt(char[][] grid, int startRow, int startCol, int rowDelta, int colDelta) {
        int dotCount = 0;

        for (int k = 0; k < SEQUENCE_LENGTH; k++) {
            int currRow = startRow + (k * rowDelta);
            int currCol = startCol + (k * colDelta);

            // 1. Boundary Check
            if (isOutOfBounds(currRow, currCol)) {
                return false;
            }

            char cell = grid[currRow][currCol];

            // 2. Validity Check: Pattern cannot contain 'o'
            if (cell == 'o') {
                return false;
            } 

            // 3. Count dots for the requirement (at most one '.')
            if (cell == '.') {
                dotCount++;
            }
        }

        return dotCount <= 1;
    }

    private boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= GRID_SIZE || c < 0 || c >= GRID_SIZE;
    }

    /**
     * Fast I/O utility for reading input.
     */
    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * A refactored solution to check for specific patterns in a 4x4 grid.
 * The goal is to find any 3 consecutive cells (horizontal, vertical, or diagonal)
 * that contain exactly two 'x' cells and one empty cell.
 */
public class Main {

    public static void main(String[] args) {
        try (InputReader reader = new InputReader(System.in);
             OutputWriter writer = new OutputWriter(System.out)) {

            GameEngine engine = new GameEngine();
            engine.solve(reader, writer);

        } catch (IOException e) {
            System.err.println("An error occurred during I/O operations: " + e.getMessage());
        }
    }

    /**
     * Contains the core game logic and rule evaluation.
     */
    static class GameEngine {
        private static final int GRID_SIZE = 4;
        private static final int SEQUENCE_LENGTH = 3;
        private static final int TARGET_SUM = 2;

        // Cell values used to calculate the sum for pattern matching
        private static final int VAL_X = 1;
        private static final int VAL_O = -11;
        private static final int VAL_EMPTY = 0;

        // Directions to check: Horizontal, Vertical, Diagonal Down-Right, Diagonal Down-Left
        private static final int[][] DIRECTIONS = {
            {0, 1},  // Horizontal
            {1, 0},  // Vertical
            {1, 1},  // Diagonal Down-Right
            {1, -1}  // Diagonal Down-Left
        };

        public void solve(InputReader reader, OutputWriter writer) {
            int[][] grid = parseGrid(reader);
            boolean isPatternFound = checkPatternExists(grid);
            writer.printLine(isPatternFound ? "YES" : "NO");
        }

        private int[][] parseGrid(InputReader reader) {
            int[][] grid = new int[GRID_SIZE][GRID_SIZE];
            for (int i = 0; i < GRID_SIZE; i++) {
                String line = reader.next();
                if (line == null) break;

                for (int j = 0; j < GRID_SIZE; j++) {
                    char cell = line.charAt(j);
                    grid[i][j] = mapCharToValue(cell);
                }
            }
            return grid;
        }

        private int mapCharToValue(char c) {
            if (c == 'x') return VAL_X;
            if (c == 'o') return VAL_O;
            return VAL_EMPTY;
        }

        private boolean checkPatternExists(int[][] grid) {
            for (int r = 0; r < GRID_SIZE; r++) {
                for (int c = 0; c < GRID_SIZE; c++) {
                    for (int[] dir : DIRECTIONS) {
                        if (isWinningSequence(grid, r, c, dir[0], dir[1])) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        private boolean isWinningSequence(int[][] grid, int row, int col, int dr, int dc) {
            // Calculate the end position of the sequence
            int endRow = row + (SEQUENCE_LENGTH - 1) * dr;
            int endCol = col + (SEQUENCE_LENGTH - 1) * dc;

            // Boundary check
            if (endRow < 0 || endRow >= GRID_SIZE || endCol < 0 || endCol >= GRID_SIZE) {
                return false;
            }

            int sum = 0;
            for (int i = 0; i < SEQUENCE_LENGTH; i++) {
                sum += grid[row + i * dr][col + i * dc];
            }

            // The sum is 2 only if the sequence contains exactly two 'x' (1+1) and one empty (0)
            return sum == TARGET_SUM;
        }
    }

    /**
     * Fast I/O reader for handling input streams.
     */
    static class InputReader implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream inputStream) {
            this.reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            try {
                while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                }
                return tokenizer.nextToken();
            } catch (IOException e) {
                return null;
            }
        }

        @Override
        public void close() throws IOException {
            reader.close();
        }
    }

    /**
     * Efficient output writer for handling output streams.
     */
    static class OutputWriter implements AutoCloseable {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public void printLine(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                writer.print(objects[i]);
                if (i < objects.length - 1) {
                    writer.print(' ');
                }
            }
            writer.println();
        }

        @Override
        public void close() {
            writer.close();
        }
    }
}

import java.io.PrintWriter;
import java.util.Scanner;
import java.util.Set;

/**
 * A program to detect if specific Tic-Tac-Toe patterns exist within a 4x4 grid.
 */
public class Main {

    public static void main(String[] args) {
        // Using try-with-resources to ensure the Scanner and PrintWriter are closed automatically
        try (Scanner sc = new Scanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            GridSolver solver = new GridSolver();
            solver.solve(sc, out);
        } catch (Exception e) {
            System.err.println("An error occurred during execution: " + e.getMessage());
        }
    }

    /**
     * Logic for solving the pattern detection problem.
     */
    static class GridSolver {
        private static final int GRID_SIZE = 4;
        private static final int WINDOW_SIZE = 3;

        // The patterns we are looking for in any 3-length segment
        private static final Set<String> TARGET_PATTERNS = Set.of(".xx", "xx.", "x.x");

        // Possible movement directions: Horizontal, Vertical, Diagonal (Down-Right), Diagonal (Down-Left)
        private static final int[][] DIRECTIONS = {
            {0, 1},  // Horizontal
            {1, 0},  // Vertical
            {1, 1},  // Diagonal Down-Right
            {1, -1}  // Diagonal Down-Left
        };

        /**
         * Reads input, checks for patterns, and prints the result.
         */
        public void solve(Scanner in, PrintWriter out) {
            char[][] grid = readGrid(in);
            boolean found = containsTargetPattern(grid);
            out.println(found ? "YES" : "NO");
        }

        /**
         * Reads a 4x4 grid from the scanner.
         */
        private char[][] readGrid(Scanner in) {
            char[][] grid = new char[GRID_SIZE][GRID_SIZE];
            for (int i = 0; i < GRID_SIZE; i++) {
                if (in.hasNext()) {
                    grid[i] = in.next().toCharArray();
                }
            }
            return grid;
        }

        /**
         * Iterates through every possible starting cell and direction to find a pattern.
         */
        private boolean containsTargetPattern(char[][] grid) {
            for (int r = 0; r < GRID_SIZE; r++) {
                for (int c = 0; c < GRID_SIZE; c++) {
                    for (int[] dir : DIRECTIONS) {
                        if (canExtractSegment(r, c, dir)) {
                            String segment = extractSegment(r, c, dir, grid);
                            if (TARGET_PATTERNS.contains(segment)) {
                                return true;
                            }
                        }
                    }
                }
            }
            return false;
        }

        /**
         * Checks if a segment of WINDOW_SIZE can be extracted starting from (r, c) in direction dir.
         */
        private boolean canExtractSegment(int r, int c, int[] dir) {
            int endR = r + (WINDOW_SIZE - 1) * dir[0];
            int endC = c + (WINDOW_SIZE - 1) * dir[1];
            return endR >= 0 && endR < GRID_SIZE && endC >= 0 && endC < GRID_SIZE;
        }

        /**
         * Extracts a string segment of length WINDOW_SIZE from the grid.
         */
        private String extractSegment(int r, int c, int[] dir, char[][] grid) {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < WINDOW_SIZE; i++) {
                int currR = r + i * dir[0];
                int currC = c + i * dir[1];
                sb.append(grid[currR][currC]);
            }
            return sb.toString();
        }
    }
}

import java.util.Scanner;
import java.util.Set;

/**
 * A utility to detect specific winning patterns in a 4x4 grid.
 * A winning pattern is defined as any 3-character sequence 
 * consisting of exactly two 'x' characters and one '.' character.
 */
public class PatternMatcher {

    private static final int GRID_SIZE = 4;
    private static final Set<String> WINNING_PATTERNS = Set.of("x.x", ".xx", "xx.");

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            char[][] grid = readGrid(scanner);

            if (hasWinningSequence(grid)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        } catch (Exception e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Reads 4 lines of input to construct a 4x4 grid.
     */
    private static char[][] readGrid(Scanner scanner) {
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            String line = scanner.nextLine();
            for (int j = 0; j < GRID_SIZE; j++) {
                grid[i][j] = line.charAt(j);
            }
        }
        return grid;
    }

    /**
     * Orchestrates the search for winning sequences across rows, columns, 
     * diagonals, and sub-diagonals.
     */
    private static boolean hasWinningSequence(char[][] grid) {
        // Check Rows
        for (int i = 0; i < GRID_SIZE; i++) {
            if (isValid(getRow(grid, i))) return true;
        }

        // Check Columns
        for (int j = 0; j < GRID_SIZE; j++) {
            if (isValid(getCol(grid, j))) return true;
        }

        // Check Main Diagonals
        if (isValid(getMainDiagonal(grid))) return true;
        if (isValid(getAntiDiagonal(grid))) return true;

        // Check specific 3-length sub-diagonals
        if (isValid(getSubDiagonal1(grid))) return true; // bottom-left sub-diag
        if (isValid(getSubDiagonal2(grid))) return true; // top-right sub-diag
        if (isValid(getSubDiagonal3(grid))) return true; // top-left anti-sub-diag
        if (isValid(getSubDiagonal4(grid))) return true; // bottom-right anti-sub-diag

        return false;
    }

    /**
     * Validates if a sequence of length 3 or 4 contains a winning 3-character pattern.
     */
    private static boolean isValid(String sequence) {
        if (sequence.length() == 3) {
            return WINNING_PATTERNS.contains(sequence);
        } else if (sequence.length() == 4) {
            // A 4-length sequence is valid if either its prefix or suffix of 3 matches
            return WINNING_PATTERNS.contains(sequence.substring(0, 3)) ||
                   WINNING_PATTERNS.contains(sequence.substring(1));
        }
        return false;
    }

    // --- Grid Extraction Helpers ---

    private static String getRow(char[][] grid, int row) {
        return new String(grid[row]);
    }

    private static String getCol(char[][] grid, int col) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < GRID_SIZE; i++) {
            sb.append(grid[i][col]);
        }
        return sb.toString();
    }

    private static String getMainDiagonal(char[][] grid) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < GRID_SIZE; i++) {
            sb.append(grid[i][i]);
        }
        return sb.toString();
    }

    private static String getAntiDiagonal(char[][] grid) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < GRID_SIZE; i++) {
            sb.append(grid[i][GRID_SIZE - 1 - i]);
        }
        return sb.toString();
    }

    private static String getSubDiagonal1(char[][] grid) {
        return new String(new char[]{grid[1][0], grid[2][1], grid[3][2]});
    }

    private static String getSubDiagonal2(char[][] grid) {
        return new String(new char[]{grid[0][1], grid[1][2], grid[2][3]});
    }

    private static String getSubDiagonal3(char[][] grid) {
        return new String(new char[]{grid[0][2], grid[1][1], grid[2][0]});
    }

    private static String getSubDiagonal4(char[][] grid) {
        return new String(new char[]{grid[1][3], grid[2][2], grid[3][1]});
    }
}

