/**
 * Represents the Tic-Tac-Toe board and contains the logic 
 * to evaluate winning conditions.
 */
class TicTacToeBoard {
    private final char[][] grid;
    private static final int SIZE = 4;
    private static final char PLAYER = 'x';
    private static final char EMPTY = '.';

    public TicTacToeBoard(char[][] grid) {
        this.grid = grid;
    }

    /**
     * Evaluates if there is any sequence of 3 cells that contains 
     * exactly two 'x's and one empty cell.
     *
     * @return true if a winning move exists, false otherwise.
     */
    public boolean canWinWithNextMove() {
        for (int r = 0; r < SIZE; r++) {
            for (int c = 0; c < SIZE; c++) {
                if (isWinningSequenceAt(r, c)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Checks all four directions (Horizontal, Vertical, and both Diagonals)
     * for a winning window of 3 starting from the given coordinate.
     */
    private boolean isWinningSequenceAt(int r, int c) {
        return isWinningWindow(r, c, r, c + 1, r, c + 2) ||             // Horizontal
               isWinningWindow(r, c, r + 1, c, r + 2, c) ||             // Vertical
               isWinningWindow(r, c, r + 1, c + 1, r + 2, c + 2) ||     // Diagonal Down-Right
               isWinningWindow(r, c, r + 1, c - 1, r + 2, c - 2);       // Diagonal Down-Left
    }

    /**
     * Validates if a specific 3-cell window satisfies the winning condition:
     * exactly two 'x' players and one empty cell.
     */
    private boolean isWinningWindow(int r1, int c1, int r2, int c2, int r3, int c3) {
        // Boundary check to ensure the window is within the 4x4 grid
        if (isOutOfBounds(r1, c1) || isOutOfBounds(r2, c2) || isOutOfBounds(r3, c3)) {
            return false;
        }

        int xCount = 0;
        int emptyCount = 0;

        char[] window = {grid[r1][c1], grid[r2][c2], grid[r3][c3]};

        for (char cell : window) {
            if (cell == PLAYER) {
                xCount++;
            } else if (cell == EMPTY) {
                emptyCount++;
            }
        }

        // A win is possible if we have two 'x's and one empty space to fill
        return xCount == 2 && emptyCount == 1;
    }

    private boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= SIZE || c < 0 || c >= SIZE;
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver that determines if a 4x4 grid can form a sequence of three 
 * consecutive 'x' characters (horizontal, vertical, or diagonal) 
 * by placing exactly one additional 'x' in an empty '.' cell.
 */
public class GridPatternSolver {

    private static final int GRID_SIZE = 4;
    private static final char TARGET_CHAR = 'x';
    private static final char EMPTY_CHAR = '.';

    // Direction vectors representing: Horizontal, Vertical, Diagonal (\), and Diagonal (/)
    private static final int[][] DIRECTIONS = {
        {0, 1},  // Horizontal
        {1, 0},  // Vertical
        {1, 1},  // Diagonal Down-Right
        {1, -1}  // Diagonal Down-Left
    };

    public static void main(String[] args) {
        try {
            GridPatternSolver solver = new GridPatternSolver();
            solver.solve();
        } catch (IOException e) {
            System.err.println("An error occurred while reading input: " + e.getMessage());
        }
    }

    /**
     * Orchestrates the reading of input and the execution of the solver logic.
     */
    public void solve() throws IOException {
        FastReader reader = new FastReader(System.in);
        char[][] grid = readGrid(reader);

        if (canFormSequenceWithOneMove(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Reads a 4x4 grid from the input source.
     */
    private char[][] readGrid(FastReader reader) throws IOException {
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            String line = reader.readLine();
            if (line == null || line.isEmpty()) {
                throw new IOException("Invalid input format: line is null or empty.");
            }
            grid[i] = line.toCharArray();
        }
        return grid;
    }

    /**
     * Iterates through every empty cell, attempts to place an 'x', 
     * and checks if it creates a sequence of three.
     * 
     * @param grid The current state of the 4x4 grid.
     * @return true if a sequence can be formed, false otherwise.
     */
    private boolean canFormSequenceWithOneMove(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                if (grid[r][c] == EMPTY_CHAR) {
                    // Place the character
                    grid[r][c] = TARGET_CHAR;

                    if (containsAnySequence(grid)) {
                        // Backtrack before returning true
                        grid[r][c] = EMPTY_CHAR;
                        return true;
                    }

                    // Backtrack to restore state for next attempt
                    grid[r][c] = EMPTY_CHAR;
                }
            }
        }
        return false;
    }

    /**
     * Checks if the provided grid contains any sequence of three 'x's 
     * in any valid direction.
     */
    private boolean containsAnySequence(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                // We only need to check if this cell can be the center of a sequence
                if (grid[r][c] == TARGET_CHAR) {
                    for (int[] dir : DIRECTIONS) {
                        if (isSequenceAtCenter(grid, r, c, dir[0], dir[1])) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Validates if a sequence of three 'x' characters exists 
     * with the given coordinates as the center cell.
     */
    private boolean isSequenceAtCenter(char[][] grid, int r, int c, int dr, int dc) {
        int rPrev = r - dr;
        int cPrev = c - dc;
        int rNext = r + dr;
        int cNext = c + dc;

        return isWithinBounds(rPrev, cPrev) && grid[rPrev][cPrev] == TARGET_CHAR &&
               isWithinBounds(rNext, cNext) && grid[rNext][cNext] == TARGET_CHAR;
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
    }

    /**
     * A lightweight wrapper for BufferedReader to handle input efficiently.
     */
    private static class FastReader {
        private final BufferedReader reader;

        public FastReader(InputStream inputStream) {
            this.reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String readLine() throws IOException {
            return reader.readLine();
        }
    }
}

import java.util.Scanner;

/**
 * A game engine to determine if the current player in a Tic-Tac-Toe variant 
 * can win in their next move.
 */
public class TicTacToeGame {

    private static final char PLAYER_X = 'x';
    private static final char PLAYER_O = 'o';
    private static final char EMPTY_CELL = '.';
    private static final int WINNING_THRESHOLD = 3;
    private static final int BOARD_SIZE = 4;

    /**
     * Entry point of the program.
     * @param args Command line arguments.
     */
    public static void main(String[] args) {
        TicTacToeGame game = new TicTacToeGame();
        game.run();
    }

    /**
     * Orchestrates the game flow: reading the board, identifying the next player,
     * and determining if they can win.
     */
    public void run() {
        char[][] board = readBoardFromConsole();
        if (board == null) {
            return;
        }

        try {
            char nextPlayer = identifyNextPlayer(board);
            if (canWinInNextMove(board, nextPlayer)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        } catch (IllegalStateException e) {
            System.err.println("Error: " + e.getMessage());
        }
    }

    /**
     * Reads the board configuration from standard input.
     * 
     * @return A 2D char array representing the board.
     */
    private char[][] readBoardFromConsole() {
        try (Scanner scanner = new Scanner(System.in)) {
            char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
            for (int i = 0; i < BOARD_SIZE; i++) {
                if (scanner.hasNextLine()) {
                    String line = scanner.nextLine();
                    char[] rowChars = line.toCharArray();
                    for (int j = 0; j < BOARD_SIZE; j++) {
                        // Fill board, handling potential short input lines
                        board[i][j] = (j < rowChars.length) ? rowChars[j] : EMPTY_CELL;
                    }
                }
            }
            return board;
        } catch (Exception e) {
            return null;
        }
    }

    /**
     * Determines whose turn it is based on the count of 'x' and 'o'.
     * 
     * @param board The current game board.
     * @return The character representing the next player.
     * @throws IllegalStateException if the board state is invalid.
     */
    private char identifyNextPlayer(char[][] board) {
        int xCount = 0;
        int oCount = 0;

        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                if (board[i][j] == PLAYER_X) xCount++;
                else if (board[i][j] == PLAYER_O) oCount++;
            }
        }

        if (xCount == oCount) {
            return PLAYER_X;
        } else if (xCount == oCount + 1) {
            return PLAYER_O;
        } else {
            throw new IllegalStateException("Impossible board state: turn count mismatch.");
        }
    }

    /**
     * Checks if the specified player can win by placing one piece in an empty cell.
     * 
     * @param board The current game board.
     * @param player The player whose turn it is.
     * @return true if a winning move exists, false otherwise.
     */
    private boolean canWinInNextMove(char[][] board, char player) {
        for (int r = 0; r < BOARD_SIZE; r++) {
            for (int c = 0; c < BOARD_SIZE; c++) {
                if (board[r][c] == EMPTY_CELL) {
                    // Simulate move
                    board[r][c] = player;

                    if (hasWinningLine(board, player)) {
                        board[r][c] = EMPTY_CELL; // Backtrack
                        return true;
                    }

                    // Backtrack
                    board[r][c] = EMPTY_CELL;
                }
            }
        }
        return false;
    }

    /**
     * Checks if the specified player currently has a winning sequence on the board.
     * 
     * @param board The current game board.
     * @param player The player to check for.
     * @return true if the player has a winning line.
     */
    private boolean hasWinningLine(char[][] board, char player) {
        for (int r = 0; r < BOARD_SIZE; r++) {
            for (int c = 0; c < BOARD_SIZE; c++) {
                if (checkWinningSequenceFromCell(board, r, c, player)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Checks all four directions from a specific cell to see if a winning 
     * sequence starts there.
     * 
     * @param board The current game board.
     * @param r Starting row.
     * @param c Starting column.
     * @param player The player being checked.
     * @return true if a winning sequence is found in any direction.
     */
    private boolean checkWinningSequenceFromCell(char[][] board, int r, int c, char player) {
        // Directions: Horizontal, Vertical, Diagonal Down-Right, Diagonal Up-Right
        int[][] directions = {
            {0, 1},  
            {1, 0},  
            {1, 1},  
            {-1, 1}  
        };

        for (int[] dir : directions) {
            if (countConsecutive(board, r, c, player, dir[0], dir[1]) >= WINNING_THRESHOLD) {
                return true;
            }
        }
        return false;
    }

    /**
     * Counts consecutive pieces of the same player in a given direction.
     * 
     * @param board The current game board.
     * @param r Starting row.
     * @param c Starting column.
     * @param player The player piece to count.
     * @param deltaRow The row step direction.
     * @param deltaCol The column step direction.
     * @return The count of consecutive pieces.
     */
    private int countConsecutive(char[][] board, int r, int c, char player, int deltaRow, int deltaCol) {
        int count = 0;
        int currR = r;
        int currC = c;

        while (isWithinBounds(board, currR, currC) && board[currR][currC] == player) {
            count++;
            currR += deltaRow;
            currC += deltaCol;
        }
        return count;
    }

    private boolean isWithinBounds(char[][] board, int r, int c) {
        return r >= 0 && r < BOARD_SIZE && c >= 0 && c < BOARD_SIZE;
    }
}

import java.util.Scanner;

/**
 * A program that detects a specific pattern in a 4x4 grid.
 * The pattern is defined as a sequence of three cells in any straight line 
 * (horizontal, vertical, or diagonal) where the first cell is 'x' and 
 * the subsequent two cells contain exactly one 'x' and one '.'.
 */
public class Main {

    private static final int GRID_SIZE = 4;
    private static final char TARGET_X = 'x';
    private static final char TARGET_DOT = '.';

    // Represents the 8 possible directions: vertical, horizontal, and diagonal
    private static final int[][] DIRECTIONS = {
        {1, 0},  // Down
        {-1, 0}, // Up
        {0, 1},  // Right
        {0, -1}, // Left
        {1, 1},  // Down-Right
        {-1, -1},// Up-Left
        {1, -1}, // Down-Left
        {-1, 1}  // Up-Right
    };

    public static void main(String[] args) {
        char[][] grid = readGrid();
        if (hasPattern(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Reads a 4x4 grid from standard input.
     */
    private static char[][] readGrid() {
        Scanner scanner = new Scanner(System.in);
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];

        for (int i = 0; i < GRID_SIZE; i++) {
            if (scanner.hasNextLine()) {
                grid[i] = scanner.nextLine().toCharArray();
            }
        }
        return grid;
    }

    /**
     * Scans the grid to find the specified pattern.
     * @param grid The 4x4 character grid.
     * @return true if the pattern is found, false otherwise.
     */
    private static boolean hasPattern(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                // The pattern must start with an 'x'
                if (grid[r][c] == TARGET_X) {
                    if (checkDirectionsFromCell(grid, r, c)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks all 8 directions from a specific cell to see if the pattern follows.
     */
    private static boolean checkDirectionsFromCell(char[][] grid, int r, int c) {
        for (int[] dir : DIRECTIONS) {
            int dr = dir[0];
            int dc = dir[1];

            // Calculate the position of the 3rd cell in this direction
            int endR = r + (2 * dr);
            int endC = c + (2 * dc);

            // Check if the 3rd cell is within grid boundaries
            if (isWithinBounds(endR, endC)) {
                char next1 = grid[r + dr][c + dc];
                char next2 = grid[endR][endC];

                if (isPatternMatch(next1, next2)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Determines if the next two cells in a line match the pattern: (x, .) or (., x).
     */
    private static boolean isPatternMatch(char cell1, char cell2) {
        boolean pattern1 = (cell1 == TARGET_X && cell2 == TARGET_DOT);
        boolean pattern2 = (cell1 == TARGET_DOT && cell2 == TARGET_X);
        return pattern1 || pattern2;
    }

    /**
     * Validates if the given coordinates are within the grid dimensions.
     */
    private static boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
    }
}

import java.util.Scanner;

/**
 * A utility to detect if a specific sequence of characters exists in a 4x4 grid.
 * The sequence is defined by the sum of the Unicode values of three adjacent characters.
 */
public class GridSequenceFinder {

    private static final int GRID_SIZE = 4;
    private static final int SEQUENCE_LENGTH = 3;
    private static final int TARGET_SUM = 286;

    // Direction vectors for: Horizontal, Vertical, Diagonal (Down-Right), and Anti-Diagonal (Up-Right)
    private static final int[][] DIRECTIONS = {
        {0, 1},  // Horizontal
        {1, 0},  // Vertical
        {1, 1},  // Diagonal
        {-1, 1}  // Anti-Diagonal
    };

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            char[][] grid = readGrid(scanner, GRID_SIZE);

            if (hasTargetSequence(grid)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        } catch (Exception e) {
            System.err.println("Error processing input: " + e.getMessage());
        }
    }

    /**
     * Reads the grid input from the user.
     */
    private static char[][] readGrid(Scanner scanner, int size) {
        char[][] grid = new char[size][size];
        for (int i = 0; i < size; i++) {
            String line = scanner.nextLine();
            // Fill the grid based on the input line characters
            for (int j = 0; j < size; j++) {
                grid[i][j] = line.charAt(j);
            }
        }
        return grid;
    }

    /**
     * Scans the grid for any sequence of length 3 in any of the 4 allowed directions
     * that sums up to the TARGET_SUM.
     */
    private static boolean hasTargetSequence(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                for (int[] direction : DIRECTIONS) {
                    if (checkSequenceAt(grid, r, c, direction[0], direction[1])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a sequence starting at (row, col) in a specific direction 
     * matches the target sum.
     */
    private static boolean checkSequenceAt(char[][] grid, int row, int col, int dr, int dc) {
        int currentSum = 0;

        for (int i = 0; i < SEQUENCE_LENGTH; i++) {
            int nextR = row + (i * dr);
            int nextC = col + (i * dc);

            if (!isValidCoordinate(nextR, nextC)) {
                return false;
            }
            currentSum += grid[nextR][nextC];
        }

        return currentSum == TARGET_SUM;
    }

    /**
     * Ensures the coordinates are within the grid boundaries.
     */
    private static boolean isValidCoordinate(int r, int c) {
        return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
    }
}

import java.util.Arrays;
import java.util.List;
import java.util.Scanner;

/**
 * Evaluates a 4x4 game grid to determine if a winning pattern exists.
 * Winning patterns are defined as 3-character sequences: "xx.", "x.x", or ".xx".
 */
public class TicTacToeEvaluator {

    private static final int GRID_SIZE = 4;
    private static final int PATTERN_LENGTH = 3;
    private static final List<String> WIN_PATTERNS = Arrays.asList("xx.", "x.x", ".xx");

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];

        try {
            // Populate the grid from user input
            for (int i = 0; i < GRID_SIZE; i++) {
                if (scanner.hasNextLine()) {
                    String line = scanner.nextLine();
                    grid[i] = line.toCharArray();
                }
            }

            if (hasWinningPattern(grid)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        } catch (Exception e) {
            System.err.println("Error reading input: " + e.getMessage());
        } finally {
            scanner.close();
        }
    }

    /**
     * Scans the grid for any winning patterns in rows, columns, or diagonals.
     *
     * @param grid The 2D character array representing the game board.
     * @return true if a winning pattern is found, false otherwise.
     */
    private static boolean hasWinningPattern(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {

                // Check Horizontal segment starting at (r, c)
                if (c + PATTERN_LENGTH <= GRID_SIZE) {
                    if (isPatternMatch(grid[r][c], grid[r][c + 1], grid[r][c + 2])) {
                        return true;
                    }
                }

                // Check Vertical segment starting at (r, c)
                if (r + PATTERN_LENGTH <= GRID_SIZE) {
                    if (isPatternMatch(grid[r][c], grid[r + 1][c], grid[r + 2][c])) {
                        return true;
                    }
                }

                // Check Diagonal (\) segment starting at (r, c)
                if (r + PATTERN_LENGTH <= GRID_SIZE && c + PATTERN_LENGTH <= GRID_SIZE) {
                    if (isPatternMatch(grid[r][c], grid[r + 1][c + 1], grid[r + 2][c + 2])) {
                        return true;
                    }
                }

                // Check Anti-Diagonal (/) segment starting at (r, c)
                if (r + PATTERN_LENGTH <= GRID_SIZE && c - (PATTERN_LENGTH - 1) >= 0) {
                    if (isPatternMatch(grid[r][c], grid[r + 1][c - 1], grid[r + 2][c - 2])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Validates if a specific 3-character segment matches any of the winning patterns.
     */
    private static boolean isPatternMatch(char a, char b, char c) {
        String segment = "" + a + b + c;
        for (String pattern : WIN_PATTERNS) {
            if (segment.equals(pattern)) {
                return true;
            }
        }
        return false;
    }
}

import java.util.List;
import java.util.Scanner;

/**
 * A program to determine if a single move can create a line of three 'x's 
 * on a 4x4 grid.
 */
public class Main {
    private static final int GRID_SIZE = 4;

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            char[][] grid = readGridFromInput(scanner, GRID_SIZE);
            GameEngine engine = new GameEngine(grid);

            if (engine.canWinWithOneMove()) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /**
     * Reads the grid from the standard input.
     */
    private static char[][] readGridFromInput(Scanner scanner, int size) {
        char[][] grid = new char[size][size];
        for (int i = 0; i < size; i++) {
            String line = scanner.hasNextLine() ? scanner.nextLine().trim() : "";
            for (int j = 0; j < size; j++) {
                // Ensure we don't throw IndexOutOfBounds if the input line is short
                grid[i][j] = (j < line.length()) ? line.charAt(j) : '.';
            }
        }
        return grid;
    }

    /**
     * Represents a movement direction in the grid.
     */
    private record Direction(int rowDelta, int colDelta) {}

    /**
     * Handles the logic of the grid game.
     */
    static class GameEngine {
        private static final List<Direction> DIRECTIONS = List.of(
                new Direction(0, 1),   // East
                new Direction(0, -1),  // West
                new Direction(1, 0),   // South
                new Direction(-1, 0),  // North
                new Direction(1, 1),   // South-East
                new Direction(1, -1),  // South-West
                new Direction(-1, 1),  // North-East
                new Direction(-1, -1)  // North-West
        );

        private final char[][] grid;
        private final int size;

        public GameEngine(char[][] grid) {
            this.grid = grid;
            this.size = grid.length;
        }

        /**
         * Checks if placing one 'x' in an empty spot results in a line of three 'x's.
         */
        public boolean canWinWithOneMove() {
            for (int r = 0; r < size; r++) {
                for (int c = 0; c < size; c++) {
                    if (grid[r][c] == '.') {
                        // Try placing an 'x'
                        grid[r][c] = 'x';

                        if (hasThreeInARow()) {
                            return true;
                        }

                        // Backtrack
                        grid[r][c] = '.';
                    }
                }
            }
            return false;
        }

        /**
         * Scans the entire board to see if any line of three 'x's exists.
         */
        private boolean hasThreeInARow() {
            for (int r = 0; r < size; r++) {
                for (int c = 0; c < size; c++) {
                    if (grid[r][c] == 'x' && checkLineStartingAt(r, c)) {
                        return true;
                    }
                }
            }
            return false;
        }

        /**
         * Checks if a line of three 'x's starts from the given coordinate in any direction.
         */
        private boolean checkLineStartingAt(int startRow, int startCol) {
            for (Direction dir : DIRECTIONS) {
                int count = 0;
                for (int step = 0; step < 3; step++) {
                    int currentRow = startRow + (dir.rowDelta() * step);
                    int currentCol = startCol + (dir.colDelta() * step);

                    if (isValidMove(currentRow, currentCol) && grid[currentRow][currentCol] == 'x') {
                        count++;
                    } else {
                        break;
                    }
                }
                if (count == 3) {
                    return true;
                }
            }
            return false;
        }

        private boolean isValidMove(int r, int c) {
            return r >= 0 && r < size && c >= 0 && c < size;
        }
    }
}

import java.util.Scanner;

/**
 * A utility to detect specific character patterns within a 2D grid.
 * The pattern sought is exactly two 'x' characters and one '.' character
 * in a consecutive sequence of three.
 */
public class GridPatternDetector {

    // Constants to replace "magic numbers" for better maintainability
    private static final int GRID_SIZE = 4;
    private static final int SEQUENCE_LENGTH = 3;

    // Direction vectors representing: Horizontal, Vertical, Diagonal Down-Right, Diagonal Down-Left
    private static final int[][] DIRECTIONS = {
        {0, 1},  // Horizontal
        {1, 0},  // Vertical
        {1, 1},  // Diagonal Down-Right
        {1, -1}  // Diagonal Down-Left
    };

    private final char[][] grid;

    public GridPatternDetector(char[][] grid) {
        this.grid = grid;
    }

    /**
     * Scans the grid for the winning pattern.
     * @return true if a sequence of 3 contains exactly two 'x' and one '.'
     */
    public boolean hasWinningPattern() {
        for (int row = 0; row < GRID_SIZE; row++) {
            for (int col = 0; col < GRID_SIZE; col++) {
                if (checkAllDirectionsFrom(row, col)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Checks all possible directions starting from a specific cell.
     */
    private boolean checkAllDirectionsFrom(int row, int col) {
        for (int[] dir : DIRECTIONS) {
            if (isPatternMatch(row, col, dir[0], dir[1])) {
                return true;
            }
        }
        return false;
    }

    /**
     * Evaluates a sequence starting at (startRow, startCol) following the direction vector.
     */
    private boolean isPatternMatch(int startRow, int startCol, int rowDelta, int colDelta) {
        int xCount = 0;
        int dotCount = 0;

        for (int i = 0; i < SEQUENCE_LENGTH; i++) {
            int currentRow = startRow + (i * rowDelta);
            int currentCol = startCol + (i * colDelta);

            // If the sequence goes out of the grid bounds, it's not a valid sequence
            if (isOutOfBounds(currentRow, currentCol)) {
                return false;
            }

            char cell = grid[currentRow][currentCol];
            if (cell == 'x') {
                xCount++;
            } else if (cell == '.') {
                dotCount++;
            }
        }

        // The requirement: exactly two 'x' and one '.'
        return xCount == 2 && dotCount == 1;
    }

    private boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= GRID_SIZE || c < 0 || c >= GRID_SIZE;
    }

    public static void main(String[] args) {
        char[][] grid = readGridFromConsole();

        if (grid == null) {
            System.err.println("Invalid input provided.");
            return;
        }

        GridPatternDetector detector = new GridPatternDetector(grid);
        System.out.println(detector.hasWinningPattern() ? "YES" : "NO");
    }

    /**
     * Reads the 4x4 grid from standard input.
     */
    private static char[][] readGridFromConsole() {
        Scanner sc = new Scanner(System.in);
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];

        try {
            for (int i = 0; i < GRID_SIZE; i++) {
                if (!sc.hasNext()) break;
                String line = sc.next();
                // Fill the row based on the input string
                for (int j = 0; j < GRID_SIZE; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }
            return grid;
        } catch (Exception e) {
            return null;
        } finally {
            sc.close();
        }
    }
}

import java.util.Scanner;

/**
 * A solver for a 4x4 Tic-Tac-Toe style game to determine if a player
 * can win in a single move.
 */
public class TicTacToeSolver {

    private static final int GRID_SIZE = 4;
    private static final char PLAYER_CHAR = 'x';
    private static final char EMPTY_CHAR = '.';

    private final char[][] grid;

    /**
     * Constructs a solver with the provided game board.
     * @param grid A 2D array representing the game state.
     */
    public TicTacToeSolver(char[][] grid) {
        this.grid = grid;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];

        try {
            for (int i = 0; i < GRID_SIZE; i++) {
                String row = scanner.next();
                for (int j = 0; j < GRID_SIZE; j++) {
                    grid[i][j] = row.charAt(j);
                }
            }

            TicTacToeSolver solver = new TicTacToeSolver(grid);
            if (solver.canWin()) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        } catch (Exception e) {
            System.err.println("Error reading input: " + e.getMessage());
        } finally {
            scanner.close();
        }
    }

    /**
     * Determines if the player can win in exactly one move.
     * A win is possible if there exists a sequence of 3 cells in a line 
     * (horizontal, vertical, or diagonal) containing exactly two player 
     * characters and one empty space.
     *
     * @return true if a win is possible, false otherwise.
     */
    public boolean canWin() {
        // Directional vectors: {row_delta, col_delta}
        // 1. Horizontal (0, 1)
        // 2. Vertical (1, 0)
        // 3. Diagonal Down-Right (1, 1)
        // 4. Diagonal Down-Left (1, -1)
        int[][] directions = {
            {0, 1}, 
            {1, 0}, 
            {1, 1}, 
            {1, -1}
        };

        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                for (int[] dir : directions) {
                    int dr = dir[0];
                    int dc = dir[1];

                    if (isValidSegment(r, c, dr, dc)) {
                        if (isWinningSegment(r, c, dr, dc)) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a 3-cell segment starting at (r, c) in direction (dr, dc)
     * stays within the bounds of the grid.
     */
    private boolean isValidSegment(int r, int c, int dr, int dc) {
        int endR = r + 2 * dr;
        int endC = c + 2 * dc;

        return endR >= 0 && endR < GRID_SIZE && 
               endC >= 0 && endC < GRID_SIZE;
    }

    /**
     * Evaluates a 3-cell segment to see if it contains exactly two 'x's 
     * and one empty '.' cell.
     */
    private boolean isWinningSegment(int r, int c, int dr, int dc) {
        int playerXCount = 0;
        int emptyCount = 0;

        for (int i = 0; i < 3; i++) {
            char cell = grid[r + i * dr][c + i * dc];
            if (cell == PLAYER_CHAR) {
                playerXCount++;
            } else if (cell == EMPTY_CHAR) {
                emptyCount++;
            }
        }

        // A win is possible if we have 2 'x's and 1 '.' in a line of 3
        return playerXCount == 2 && emptyCount == 1;
    }
}

import java.util.Scanner;

/**
 * A program to determine if a Tic-Tac-Toe game on a 4x4 board 
 * has a winner (3 in a row).
 */
public class IlyaTicTacToegame {

    private static final int BOARD_SIZE = 4;
    private static final int WIN_COUNT = 3;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] grid = new char[BOARD_SIZE][BOARD_SIZE];

        try {
            for (int i = 0; i < BOARD_SIZE; i++) {
                String line = scanner.next();
                if (line.length() != BOARD_SIZE) {
                    throw new IllegalArgumentException("Each row must be exactly " + BOARD_SIZE + " characters.");
                }
                grid[i] = line.toCharArray();
            }

            TicTacToeBoard board = new TicTacToeBoard(grid);
            System.out.println(board.hasWinner() ? "YES" : "NO");

        } catch (Exception e) {
            System.err.println("Error reading input: " + e.getMessage());
        } finally {
            scanner.close();
        }
    }

    /**
     * Represents the Tic-Tac-Toe game board and its logic.
     */
    static class TicTacToeBoard {
        private final char[][] grid;

        public TicTacToeBoard(char[][] grid) {
            this.grid = grid;
        }

        /**
         * Checks if any player has achieved the winning condition.
         * @return true if a winner is found, false otherwise.
         */
        public boolean hasWinner() {
            for (int r = 0; r < BOARD_SIZE; r++) {
                for (int c = 0; c < BOARD_SIZE; c++) {
                    char currentPlayer = grid[r][c];

                    // Skip empty cells (assuming '.' or ' ' represents empty)
                    if (currentPlayer == '.' || currentPlayer == ' ') {
                        continue;
                    }

                    // Check all 4 possible directions from this cell
                    for (Direction dir : Direction.values()) {
                        if (checkSequence(r, c, currentPlayer, dir)) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        /**
         * Checks if a sequence of WIN_COUNT exists in a specific direction.
         */
        private boolean checkSequence(int startRow, int startCol, char player, Direction dir) {
            int count = 0;
            for (int i = 0; i < WIN_COUNT; i++) {
                int currentRow = startRow + (i * dir.rowDelta);
                int currentCol = startCol + (i * dir.colDelta);

                if (isWithinBounds(currentRow, currentCol) && grid[currentRow][currentCol] == player) {
                    count++;
                } else {
                    break;
                }
            }
            return count == WIN_COUNT;
        }

        private boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < BOARD_SIZE && c >= 0 && c < BOARD_SIZE;
        }
    }

    /**
     * Defines the movement vectors for checking lines.
     */
    enum Direction {
        HORIZONTAL(0, 1),
        VERTICAL(1, 0),
        DIAGONAL_DOWN_RIGHT(1, 1),
        DIAGONAL_DOWN_LEFT(1, -1);

        final int rowDelta;
        final int colDelta;

        Direction(int rowDelta, int colDelta) {
            this.rowDelta = rowDelta;
            this.colDelta = colDelta;
        }
    }
}

import java.util.Scanner;

/**
 * A program to determine if a '.' cell in a grid is part of a 
 * 3-in-a-row sequence of 'x' characters (horizontally, vertically, or diagonally).
 */
public class Main {

    private static final int GRID_SIZE = 4;
    private static final char EMPTY_CELL = '.';
    private static final char WALL_CELL = 'x';

    // Direction vectors representing: Horizontal, Vertical, Diagonal (\), Diagonal (/)
    private static final int[][] DIRECTIONS = {
        {0, 1},  // Horizontal
        {1, 0},  // Vertical
        {1, 1},  // Diagonal (\)
        {1, -1}  // Diagonal (/)
    };

    public static void main(String[] args) {
        char[][] maze = readMazeFromInput();
        MazeSolver solver = new MazeSolver(maze);

        if (solver.hasWinningSequence()) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Reads a square grid of size GRID_SIZE from standard input.
     */
    private static char[][] readMazeFromInput() {
        Scanner sc = new Scanner(System.in);
        char[][] maze = new char[GRID_SIZE][GRID_SIZE];

        for (int i = 0; i < GRID_SIZE; i++) {
            if (sc.hasNext()) {
                String line = sc.next();
                for (int j = 0; j < GRID_SIZE; j++) {
                    maze[i][j] = line.charAt(j);
                }
            }
        }
        sc.close();
        return maze;
    }

    /**
     * Logic engine for analyzing the maze.
     */
    static class MazeSolver {
        private final char[][] grid;
        private final int rows;
        private final int cols;

        public MazeSolver(char[][] grid) {
            this.grid = grid;
            this.rows = grid.length;
            this.cols = grid[0].length;
        }

        /**
         * Iterates through the grid to find if any '.' cell meets the condition.
         * @return true if a valid sequence is found.
         */
        public boolean hasWinningSequence() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == EMPTY_CELL && isPartOfLine(r, c)) {
                        return true;
                    }
                }
            }
            return false;
        }

        /**
         * Checks all 8 directions around a cell to see if it forms a line of 3.
         * A line is valid if the current cell is '.' and the other two are 'x'.
         */
        private boolean isPartOfLine(int r, int c) {
            for (int[] dir : DIRECTIONS) {
                int dr = dir[0];
                int dc = dir[1];

                // Case 1: The current cell is at the start: [ . , x , x ]
                if (isWall(r + dr, c + dc) && isWall(r + 2 * dr, c + 2 * dc)) {
                    return true;
                }

                // Case 2: The current cell is in the middle: [ x , . , x ]
                if (isWall(r - dr, c - dc) && isWall(r + dr, c + dc)) {
                    return true;
                }

                // Case 3: The current cell is at the end: [ x , x , . ]
                if (isWall(r - dr, c - dc) && isWall(r - 2 * dr, c - 2 * dc)) {
                    return true;
                }
            }
            return false;
        }

        /**
         * Safely checks if a coordinate contains a wall character.
         */
        private boolean isWall(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] == WALL_CELL;
        }
    }
}

import java.util.Scanner;

/**
 * Represents a game board of a specific size.
 */
class GameBoard {
    public static final int SIZE = 4;
    public static final char EMPTY = '.';
    public static final char PLAYER_X = 'x';

    private final char[][] grid;

    public GameBoard(char[][] inputGrid) {
        this.grid = new char[SIZE][SIZE];
        for (int i = 0; i < SIZE; i++) {
            System.arraycopy(inputGrid[i], 0, this.grid[i], 0, SIZE);
        }
    }

    public char getCell(int row, int col) {
        return grid[row][col];
    }

    public void setCell(int row, int col, char value) {
        grid[row][col] = value;
    }

    public int getSize() {
        return SIZE;
    }
}

/**
 * Handles the logic for determining win conditions on a GameBoard.
 */
class WinEvaluator {
    private static final int WIN_THRESHOLD = 3;

    // Direction vectors for: Horizontal, Vertical, Diagonal (Down-Right), Diagonal (Down-Left)
    private static final int[][] DIRECTIONS = {
        {0, 1},  
        {1, 0},  
        {1, 1},  
        {1, -1}  
    };

    private final GameBoard board;

    public WinEvaluator(GameBoard board) {
        this.board = board;
    }

    /**
     * Checks if placing one more 'x' in an empty cell results in a win.
     */
    public boolean canWinInOneMove() {
        for (int r = 0; r < board.getSize(); r++) {
            for (int c = 0; c < board.getSize(); c++) {
                if (board.getCell(r, c) == GameBoard.EMPTY) {
                    if (tryMoveAndCheckWin(r, c)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    private boolean tryMoveAndCheckWin(int row, int col) {
        board.setCell(row, col, GameBoard.PLAYER_X);
        boolean wins = hasWinningSequence();
        board.setCell(row, col, GameBoard.EMPTY); // Backtrack
        return wins;
    }

    /**
     * Scans the board for any sequence of PLAYER_X that meets the win threshold.
     */
    private boolean hasWinningSequence() {
        for (int r = 0; r < board.getSize(); r++) {
            for (int c = 0; c < board.getSize(); c++) {
                if (board.getCell(r, c) == GameBoard.PLAYER_X) {
                    if (checkDirectionsFrom(r, c)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    private boolean checkDirectionsFrom(int row, int col) {
        for (int[] dir : DIRECTIONS) {
            if (isSequencePresent(row, col, dir[0], dir[1])) {
                return true;
            }
        }
        return false;
    }

    private boolean isSequencePresent(int startRow, int startCol, int dr, int dc) {
        for (int i = 1; i < WIN_THRESHOLD; i++) {
            int nextR = startRow + (dr * i);
            int nextC = startCol + (dc * i);

            if (isOutOfBounds(nextR, nextC) || board.getCell(nextR, nextC) != GameBoard.PLAYER_X) {
                return false;
            }
        }
        return true;
    }

    private boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= board.getSize() || c < 0 || c >= board.getSize();
    }
}

