import java.util.Scanner;

/**
 * A class to represent a Tic-Tac-Toe style board and check for winning conditions.
 */
public class TicTacToe {

    private static final int BOARD_SIZE = 4;
    private static final int WIN_CONDITION = 3;
    private static final char PLAYER_X = 'x';

    private final char[][] board;

    /**
     * Initializes the game board with the provided grid.
     * @param board A 2D char array representing the game state.
     */
    public TicTacToe(char[][] board) {
        this.board = board;
    }

    /**
     * Checks if the specified player has achieved the winning condition.
     * 
     * @param player The character representing the player (e.g., 'x').
     * @return true if the player has a consecutive sequence of WIN_CONDITION, false otherwise.
     */
    public boolean hasWinner(char player) {
        // Directions: {row_delta, col_delta}
        // Horizontal, Vertical, Diagonal (Down-Right), Diagonal (Down-Left)
        int[][] directions = {
            {0, 1},  
            {1, 0},  
            {1, 1},  
            {1, -1}  
        };

        for (int row = 0; row < BOARD_SIZE; row++) {
            for (int col = 0; col < BOARD_SIZE; col++) {
                if (board[row][col] == player) {
                    for (int[] dir : directions) {
                        if (checkSequence(row, col, dir[0], dir[1], player)) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a sequence of the same player exists in a specific direction.
     */
    private boolean checkSequence(int startRow, int startCol, int dRow, int dCol, char player) {
        for (int i = 1; i < WIN_CONDITION; i++) {
            int nextRow = startRow + (i * dRow);
            int nextCol = startCol + (i * dCol);

            if (isOutOfBounds(nextRow, nextCol) || board[nextRow][nextCol] != player) {
                return false;
            }
        }
        return true;
    }

    private boolean isOutOfBounds(int row, int col) {
        return row < 0 || row >= BOARD_SIZE || col < 0 || col >= BOARD_SIZE;
    }

    public static void main(String[] args) {
        char[][] inputBoard = new char[BOARD_SIZE][BOARD_SIZE];

        try (Scanner scanner = new Scanner(System.in)) {
            for (int i = 0; i < BOARD_SIZE; i++) {
                if (scanner.hasNextLine()) {
                    String line = scanner.nextLine();
                    for (int j = 0; j < BOARD_SIZE && j < line.length(); j++) {
                        inputBoard[i][j] = line.charAt(j);
                    }
                }
            }
        } catch (Exception e) {
            System.err.println("Error reading input: " + e.getMessage());
            return;
        }

        TicTacToe game = new TicTacToe(inputBoard);

        if (game.hasWinner(PLAYER_X)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }
}

import java.util.Scanner;

/**
 * A utility to determine if a move can complete a line of three 'x' characters
 * on a 4x4 grid.
 */
public class GridWinDetector {

    private static final int GRID_SIZE = 4;
    private static final char TARGET_CHAR = 'x';
    private static final char EMPTY_CHAR = '.';

    // Directional vectors for: Horizontal, Vertical, Diagonal (\), and Diagonal (/)
    private static final int[][] DIRECTIONS = {
        {0, 1},  // Horizontal
        {1, 0},  // Vertical
        {1, 1},  // Diagonal \
        {1, -1}  // Diagonal /
    };

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] grid = readGrid(scanner, GRID_SIZE);

        if (canAchieveWin(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Reads a square grid of characters from standard input.
     */
    private static char[][] readGrid(Scanner scanner, int size) {
        char[][] grid = new char[size][size];
        for (int i = 0; i < size; i++) {
            String line = scanner.next();
            for (int j = 0; j < size; j++) {
                grid[i][j] = line.charAt(j);
            }
        }
        return grid;
    }

    /**
     * Iterates through the grid to find an empty cell that, if filled with 'x',
     * would create a sequence of three 'x's.
     */
    private static boolean canAchieveWin(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                if (grid[r][c] == EMPTY_CHAR) {
                    if (isWinningMove(grid, r, c)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if placing a TARGET_CHAR at (row, col) completes a line of three.
     */
    private static boolean isWinningMove(char[][] grid, int row, int col) {
        for (int[] dir : DIRECTIONS) {
            int dr = dir[0];
            int dc = dir[1];

            // A cell can occupy three possible positions in a 3-in-a-row sequence:
            // 1. The cell is at the start: (row, col), (row+dr, col+dc), (row+2dr, col+2dc)
            // 2. The cell is in the middle: (row-dr, col-dc), (row, col), (row+dr, col+dc)
            // 3. The cell is at the end: (row-2dr, col-2dc), (row-dr, col-dc), (row, col)
            if (checkSequence(grid, row + dr, col + dc, row + 2 * dr, col + 2 * dc) ||
                checkSequence(grid, row - dr, col - dc, row + dr, col + dc) ||
                checkSequence(grid, row - 2 * dr, col - 2 * dc, row - dr, col - dc)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Verifies if two specific cells in the grid contain the TARGET_CHAR.
     */
    private static boolean checkSequence(char[][] grid, int r1, int c1, int r2, int c2) {
        return isWithinBounds(grid, r1, c1) && 
               isWithinBounds(grid, r2, c2) && 
               grid[r1][c1] == TARGET_CHAR && 
               grid[r2][c2] == TARGET_CHAR;
    }

    /**
     * Ensures coordinates are within the grid boundaries.
     */
    private static boolean isWithinBounds(char[][] grid, int r, int c) {
        return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
    }
}

import java.io.*;
import java.util.*;

/**
 * A utility class for high-performance input reading.
 */
class FastReader {
    private BufferedReader reader;
    private StringTokenizer tokenizer;

    public FastReader() {
        this.reader = new BufferedReader(new InputStreamReader(System.in));
    }

    /**
     * Attempts to initialize reading from "input.txt", falls back to System.in.
     */
    public void init() {
        try {
            File file = new File("input.txt");
            if (file.exists()) {
                this.reader = new BufferedReader(new FileReader(file));
            }
        } catch (FileNotFoundException e) {
            // Fallback to System.in is already handled by constructor
        }
    }

    public String next() {
        while (tokenizer == null || !tokenizer.hasMoreElements()) {
            try {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line, " :");
            } catch (IOException e) {
                return null;
            }
        }
        return tokenizer.nextToken();
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }

    public char[] nextCharArray() {
        String s = next();
        return (s != null) ? s.toCharArray() : new char[0];
    }
}

/**
 * Utility to monitor execution time and memory usage.
 */
class PerformanceProfiler {
    private final long startTime;
    private final long startMemory;

    public PerformanceProfiler() {
        this.startTime = System.currentTimeMillis();
        this.startMemory = Runtime.getRuntime().totalMemory() - Runtime.getRuntime().freeMemory();
    }

    public void printStats() {
        long endTime = System.currentTimeMillis();
        long endMemory = Runtime.getRuntime().totalMemory() - Runtime.getRuntime().freeMemory();

        System.err.println("Execution Time: " + (endTime - startTime) + " ms");
        System.err.println("Memory Used: " + ((endMemory - startMemory) / 1024) + " KB");
    }
}

/**
 * Contains the core business logic for the grid pattern problem.
 */
class GridPatternSolver {
    private static final int GRID_SIZE = 4;
    private static final int SEQUENCE_LENGTH = 3;

    // 8 directions: Horizontal, Vertical, and Diagonal
    private static final int[] ROW_DIRECTIONS = {0, 1, 0, -1, 1, -1, -1, 1};
    private static final int[] COL_DIRECTIONS = {1, 0, -1, 0, 1, -1, 1, -1};

    private final char[][] grid;

    public GridPatternSolver(char[][] grid) {
        this.grid = grid;
    }

    /**
     * Checks if there is a sequence of 3 cells containing exactly two 'x's and one '.'.
     */
    public boolean hasTargetPattern() {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                if (checkFromCell(r, c)) {
                    return true;
                }
            }
        }
        return false;
    }

    private boolean checkFromCell(int startRow, int startCol) {
        for (int dir = 0; dir < 8; dir++) {
            int xCount = 0;
            int dotCount = 0;
            boolean sequenceValid = true;

            for (int k = 0; k < SEQUENCE_LENGTH; k++) {
                int currR = startRow + ROW_DIRECTIONS[dir] * k;
                int currC = startCol + COL_DIRECTIONS[dir] * k;

                if (isWithinBounds(currR, currC)) {
                    if (grid[currR][currC] == 'x') {
                        xCount++;
                    } else if (grid[currR][currC] == '.') {
                        dotCount++;
                    }
                } else {
                    sequenceValid = false;
                    break;
                }
            }

            if (sequenceValid && xCount == 2 && dotCount == 1) {
                return true;
            }
        }
        return false;
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
    }
}

/**
 * Main entry point that orchestrates the execution.
 */
public class Template implements Runnable {

    @Override
    public void run() {
        FastReader reader = new FastReader();
        reader.init();

        // Use try-with-resources for automatic resource management
        try (PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)))) {
            char[][] grid = new char[4][4];
            for (int i = 0; i < 4; i++) {
                grid[i] = reader.nextCharArray();
            }

            GridPatternSolver solver = new GridPatternSolver(grid);
            if (solver.hasTargetPattern()) {
                out.println("YES");
            } else {
                out.println("NO");
            }
            out.flush();

            // Only print profiling info if not running in a typical Online Judge environment
            if (System.getProperty("ONLINE_JUDGE") == null) {
                new PerformanceProfiler().printStats();
            }

        } catch (Exception e) {
            e.printStackTrace();
            System.exit(1);
        }
    }

    public static void main(String[] args) {
        // Custom stack size for deep recursion scenarios (typical in competitive programming)
        long stackSize = 200 * 1024 * 1024; 
        Thread thread = new Thread(null, new Template(), "solver-thread", stackSize);
        thread.start();
    }
}

import java.util.Scanner;

/**
 * A utility to determine if a 4x4 grid can contain a sequence of three 'x' characters 
 * either in its current state or by placing exactly one additional 'x'.
 */
public class GridGame {

    private static final int GRID_SIZE = 4;
    private static final int WIN_LENGTH = 3;
    private static final char PLAYER_CHAR = 'x';
    private static final char EMPTY_CHAR = '.';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] grid = readGrid(scanner, GRID_SIZE);
        scanner.close();

        if (canAchieveWin(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Reads the grid from standard input.
     */
    private static char[][] readGrid(Scanner scanner, int size) {
        char[][] grid = new char[size][size];
        for (int i = 0; i < size; i++) {
            if (scanner.hasNextLine()) {
                String line = scanner.nextLine();
                // Ensure we don't exceed line length if input is malformed
                for (int j = 0; j < size; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }
        }
        return grid;
    }

    /**
     * Determines if the win condition is already met or can be met by adding one 'x'.
     */
    private static boolean canAchieveWin(char[][] grid) {
        // 1. Check if the grid already contains a winning sequence
        if (hasWinningSequence(grid)) {
            return true;
        }

        // 2. Try placing one 'x' in every empty cell to see if it creates a sequence
        for (int i = 0; i < GRID_SIZE; i++) {
            for (int j = 0; j < GRID_SIZE; j++) {
                if (grid[i][j] == EMPTY_CHAR) {
                    grid[i][j] = PLAYER_CHAR;
                    if (hasWinningSequence(grid)) {
                        return true;
                    }
                    // Backtrack: restore the cell to empty
                    grid[i][j] = EMPTY_CHAR;
                }
            }
        }

        return false;
    }

    /**
     * Scans the grid for any sequence of PLAYER_CHAR of length WIN_LENGTH 
     * in horizontal, vertical, or diagonal directions.
     */
    private static boolean hasWinningSequence(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                // Optimization: Only start checking if current cell is the target character
                if (grid[r][c] == PLAYER_CHAR) {
                    if (checkDirections(grid, r, c)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks all four possible directions from a starting cell to find a sequence.
     */
    private static boolean checkDirections(char[][] grid, int r, int c) {
        // Horizontal (Right)
        if (isSequence(grid, r, c, 0, 1)) return true;

        // Vertical (Down)
        if (isSequence(grid, r, c, 1, 0)) return true;

        // Diagonal (Down-Right)
        if (isSequence(grid, r, c, 1, 1)) return true;

        // Diagonal (Down-Left)
        if (isSequence(grid, r, c, 1, -1)) return true;

        return false;
    }

    /**
     * Helper to check if a sequence of WIN_LENGTH exists starting from (r, c) 
     * moving in direction (dr, dc).
     */
    private static boolean isSequence(char[][] grid, int r, int c, int dr, int dc) {
        for (int step = 1; step < WIN_LENGTH; step++) {
            int nextR = r + (dr * step);
            int nextC = c + (dc * step);

            // Check bounds
            if (nextR < 0 || nextR >= GRID_SIZE || nextC < 0 || nextC >= GRID_SIZE) {
                return false;
            }

            // Check if character matches
            if (grid[nextR][nextC] != PLAYER_CHAR) {
                return false;
            }
        }
        return true;
    }
}

