        }

        // The original logic handles a single test case (t=1)
        char[][] grid = readGrid(scanner);

        if (grid != null && hasValidPattern(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Reads a 4x4 grid from the input.
     */
    private static char[][] readGrid(Scanner scanner) {
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            if (scanner.hasNext()) {
                grid[i] = scanner.next().toCharArray();
            }
        }
        return grid;
    }

    /**
     * Iterates through every cell and every direction to find a valid pattern.
     * @param grid The 4x4 character grid.
     * @return true if a pattern of exactly two 'x's is found in any 3-cell sequence.
     */
    private static boolean hasValidPattern(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                for (int[] direction : DIRECTIONS) {
                    if (checkPatternAt(grid, r, c, direction[0], direction[1])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks a specific sequence of cells starting from (r, c) in a given direction.
     * 
     * @param grid The grid.
     * @param r Starting row.
     * @param c Starting column.
     * @param dr Row direction offset.
     * @param dc Column direction offset.
     * @return true if the sequence exists and contains exactly two 'x's.
     */
    private static boolean checkPatternAt(char[][] grid, int r, int c, int dr, int dc) {
        int xCount = 0;

        for (int step = 0; step < SEQUENCE_LENGTH; step++) {
            int nr = r + (step * dr);
            int nc = c + (step * dc);

            if (isOutOfBounds(nr, nc)) {
                return false;
            }

            if (grid[nr][nc] == TARGET_CHAR) {
                xCount++;
            }
        }

        // The pattern matches if there are exactly two 'x's in the 3-cell sequence
        return xCount == 2;
    }

    /**
     * Bounds checking helper.
     */
    private static boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= GRID_SIZE || c < 0 || c >= GRID_SIZE;
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to determine if placing a single 'x' in a 4x4 grid 
 * can create a line of at least three 'x's.
 */
public class Main {
    // Constants to improve maintainability and avoid magic numbers
    private static final int GRID_SIZE = 4;
    private static final int WINNING_LINE_LENGTH = 3;

    public static void main(String[] args) {
        InputStream inputStream = System.in;

        // Handle devTesting mode: if the first argument is "devTesting", 
        // use the second argument as the input file path.
        if (args.length >= 2 && "devTesting".equals(args[0])) {
            try {
                inputStream = new FileInputStream(args[1]);
            } catch (FileNotFoundException e) {
                throw new RuntimeException("Failed to open testing file: " + args[1], e);
            }
        }

        FastReader reader = new FastReader(inputStream);
        PrintWriter out = new PrintWriter(System.out);

        try {
            GameSolver solver = new GameSolver();
            solver.solve(reader, out);
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Encapsulates the logic for the grid-based game.
     */
    static class GameSolver {
        private final char[][] grid = new char[GRID_SIZE][GRID_SIZE];

        // Directional vectors representing: Horizontal, Vertical, Diagonal (Down-Right), and Diagonal (Down-Left)
        private static final int[][] DIRECTIONS = {
            {0, 1},  // Horizontal
            {1, 0},  // Vertical
            {1, 1},  // Diagonal Down-Right
            {1, -1}  // Diagonal Down-Left
        };

        /**
         * Orchestrates the reading of the grid and the execution of the solver.
         */
        public void solve(FastReader reader, PrintWriter out) {
            if (!readGrid(reader)) {
                return;
            }

            if (canAchieveWinningLine()) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        }

        private boolean readGrid(FastReader reader) {
            for (int i = 0; i < GRID_SIZE; i++) {
                String row = reader.next();
                if (row == null) return false;
                grid[i] = row.toCharArray();
            }
            return true;
        }

        /**
         * Iterates through every empty cell ('.') and simulates placing an 'x'
         * to see if it satisfies the winning condition.
         */
        private boolean canAchieveWinningLine() {
            for (int r = 0; r < GRID_SIZE; r++) {
                for (int c = 0; c < GRID_SIZE; c++) {
                    if (grid[r][c] == '.') {
                        // Try placing 'x'
                        grid[r][c] = 'x';

                        if (isWinningMove(r, c)) {
                            grid[r][c] = '.'; // Backtrack before returning
                            return true;
                        }

                        // Backtrack to restore original state
                        grid[r][c] = '.';
                    }
                }
            }
            return false;
        }

        /**
         * Checks if the 'x' placed at the specified coordinate completes a line.
         */
        private boolean isWinningMove(int r, int c) {
            for (int[] direction : DIRECTIONS) {
                int lineCount = 1; // Start with the 'x' we just placed

                // Check consecutive 'x's in the positive direction
                lineCount += countConsecutiveInDirection(r, c, direction[0], direction[1]);

                // Check consecutive 'x's in the opposite direction
                lineCount += countConsecutiveInDirection(r, c, -direction[0], -direction[1]);

                if (lineCount >= WINNING_LINE_LENGTH) {
                    return true;
                }
            }
            return false;
        }

        /**
         * Counts how many consecutive 'x's exist in a specific direction from (r, c).
         */
        private int countConsecutiveInDirection(int r, int c, int dr, int dc) {
            int count = 0;
            int nextR = r + dr;
            int nextC = c + dc;

            while (isWithinBounds(nextR, nextC) && grid[nextR][nextC] == 'x') {
                count++;
                nextR += dr;
                nextC += dc;
            }
            return count;
        }

        private boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
        }
    }

    /**
     * Utility class for efficient input reading.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input stream", e);
                }
            }
            return tokenizer.nextToken();
        }
    }
}

