 * A solver for a 4x4 grid game where the goal is to identify if a 
 * winning move (completing a line of 3 'x's) is possible.
 */
public class GridGameSolver {

    private static final int GRID_SIZE = 4;
    private static final int WINNING_LINE_LENGTH = 3;

    // Direction vectors for: Horizontal, Vertical, Diagonal Down-Right, Diagonal Down-Left
    private static final int[][] DIRECTIONS = {
        {0, 1},  
        {1, 0},  
        {1, 1},  
        {1, -1}  
    };

    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];

        try {
            for (int i = 0; i < GRID_SIZE; i++) {
                String row = sc.next();
                if (row == null) break;
                grid[i] = row.toCharArray();
            }

            if (canAchieveWinningLine(grid)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        } catch (Exception e) {
            // In a production environment, use a proper logger
            e.printStackTrace();
        }
    }

    /**
     * Iterates through all possible starting positions and directions to 
     * find a sequence of cells that satisfies the winning condition.
     */
    private static boolean canAchieveWinningLine(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                for (int[] direction : DIRECTIONS) {
                    if (isWinningSequence(grid, r, c, direction[0], direction[1])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a sequence of a specific length starting from (r, c) 
     * in a given direction contains exactly two 'x's and one '.'.
     */
    private static boolean isWinningSequence(char[][] grid, int r, int c, int dr, int dc) {
        int xCount = 0;
        int dotCount = 0;

        for (int i = 0; i < WINNING_LINE_LENGTH; i++) {
            int nr = r + (i * dr);
            int nc = c + (i * dc);

            // Check bounds
            if (nr < 0 || nr >= GRID_SIZE || nc < 0 || nc >= GRID_SIZE) {
                return false;
            }

            if (grid[nr][nc] == 'x') {
                xCount++;
            } else if (grid[nr][nc] == '.') {
                dotCount++;
            }
        }

        // A winning move is possible if there are exactly 2 'x's and 1 '.' in the sequence
        return xCount == 2 && dotCount == 1;
    }

    /**
     * Utility class for fast I/O operations.
     */
    public static class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

/**
 * A program to determine if a single move can result in a win 
 * (3 in a row) on a 4x4 grid.
 */
public class Solution {

    private static final int BOARD_SIZE = 4;
    private static final int WIN_CONDITION = 3;
    private static final char EMPTY_CELL = '.';
    private static final char FILLED_CELL = 'x';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] initialGrid = readGrid(scanner);

        Board board = new Board(initialGrid);

        if (board.canWinWithOneMove()) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Reads the board input from the console.
     */
    private static char[][] readGrid(Scanner scanner) {
        char[][] grid = new char[BOARD_SIZE][BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i++) {
            String line = scanner.next();
            for (int j = 0; j < BOARD_SIZE; j++) {
                grid[i][j] = line.charAt(j);
            }
        }
        return grid;
    }

    /**
     * Represents the game board and its logic.
     */
    static class Board {
        private final char[][] grid;

        public Board(char[][] initialGrid) {
            this.grid = new char[BOARD_SIZE][BOARD_SIZE];
            for (int i = 0; i < BOARD_SIZE; i++) {
                System.arraycopy(initialGrid[i], 0, this.grid[i], 0, BOARD_SIZE);
            }
        }

        /**
         * Iterates through all empty cells to see if placing an 'x' results in a win.
         * @return true if a winning move is possible.
         */
        public boolean canWinWithOneMove() {
            for (int r = 0; r < BOARD_SIZE; r++) {
                for (int c = 0; c < BOARD_SIZE; c++) {
                    if (grid[r][c] == EMPTY_CELL) {
                        if (tryMove(r, c)) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        /**
         * Temporarily places a cell and checks if the board state meets the win condition.
         */
        private boolean tryMove(int row, int col) {
            grid[row][col] = FILLED_CELL;
            boolean isWin = checkWinCondition();
            grid[row][col] = EMPTY_CELL; // Backtrack
            return isWin;
        }

        /**
         * Uses direction vectors to check for any sequence of length WIN_CONDITION.
         */
        private boolean checkWinCondition() {
            // Direction vectors: {row_delta, col_delta}
            // Covers: Horizontal, Vertical, Diagonal Down-Right, Diagonal Down-Left
            int[][] directions = {
                {0, 1},  
                {1, 0},  
                {1, 1},  
                {1, -1}  
            };

            for (int r = 0; r < BOARD_SIZE; r++) {
                for (int c = 0; c < BOARD_SIZE; c++) {
                    if (grid[r][c] == FILLED_CELL) {
                        for (int[] dir : directions) {
                            if (isSequenceFound(r, c, dir[0], dir[1])) {
                                return true;
                            }
                        }
                    }
                }
            }
            return false;
        }

        /**
         * Checks if a sequence of filled cells exists starting from (startR, startC) 
         * moving in the direction (dr, dc).
         */
        private boolean isSequenceFound(int startR, int startC, int dr, int dc) {
            for (int step = 1; step < WIN_CONDITION; step++) {
                int nr = startR + (dr * step);
                int nc = startC + (dc * step);

                if (isOutOfBounds(nr, nc) || grid[nr][nc] != FILLED_CELL) {
                    return false;
                }
            }
            return true;
        }

        private boolean isOutOfBounds(int r, int c) {
            return r < 0 || r >= BOARD_SIZE || c < 0 || c >= BOARD_SIZE;
        }
    }
}

import java.util.Scanner;

/**
 * A utility to analyze a 4x4 grid to find specific patterns of 'x' and '.' characters.
 * The program identifies if there is a line of three cells that consists of 
 * exactly two 'x' characters and one '.' character (i.e., ".xx", "xx.", or "x.x").
 */
public class GridPatternAnalyzer {

    private static final int GRID_SIZE = 4;
    private static final char X_CHAR = 'x';
    private static final char EMPTY_CHAR = '.';

    // Directions: Horizontal, Vertical, and Diagonal
    private static final int[] ROW_OFFSETS = {0, 0, 1, -1, 1, 1, -1, -1};
    private static final int[] COL_OFFSETS = {1, -1, 0, 0, 1, -1, 1, -1};

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] grid = readGrid(scanner, GRID_SIZE);
        scanner.close();

        if (hasTargetPattern(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Reads the grid from the input.
     */
    private static char[][] readGrid(Scanner scanner, int size) {
        char[][] grid = new char[size][size];
        for (int i = 0; i < size; i++) {
            String line = scanner.next();
            grid[i] = line.toCharArray();
        }
        return grid;
    }

    /**
     * Searches the grid for the target patterns: ".xx", "xx.", or "x.x".
     * 
     * @param grid The 4x4 character grid.
     * @return true if any pattern is found, false otherwise.
     */
    private static boolean hasTargetPattern(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                for (int i = 0; i < ROW_OFFSETS.length; i++) {
                    int dr = ROW_OFFSETS[i];
                    int dc = COL_OFFSETS[i];

                    // Pattern 1: Check for ".xx" (This also covers "xx." when direction is reversed)
                    if (checkCell(grid, r, c, EMPTY_CHAR) &&
                        checkCell(grid, r + dr, c + dc, X_CHAR) &&
                        checkCell(grid, r + 2 * dr, c + 2 * dc, X_CHAR)) {
                        return true;
                    }

                    // Pattern 2: Check for "x.x"
                    if (checkCell(grid, r, c, X_CHAR) &&
                        checkCell(grid, r + dr, c + dc, EMPTY_CHAR) &&
                        checkCell(grid, r + 2 * dr, c + 2 * dc, X_CHAR)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Validates if a specific cell matches the expected character and is within bounds.
     */
    private static boolean checkCell(char[][] grid, int r, int c, char expected) {
        return r >= 0 && r < GRID_SIZE && 
               c >= 0 && c < GRID_SIZE && 
               grid[r][c] == expected;
    }
}

