     * Reads the 4x4 grid from standard input.
     */
    private void readGrid(Scanner scanner) {
        for (int i = 0; i < GRID_SIZE; i++) {
            if (scanner.hasNext()) {
                String line = scanner.next();
                for (int j = 0; j < GRID_SIZE && j < line.length(); j++) {
                    grid[i * GRID_SIZE + j] = line.charAt(j);
                }
            }
        }
    }

    /**
     * Checks all possible lines of 3 in the 4x4 grid.
     * This includes horizontal, vertical, and diagonal segments.
     * 
     * @return true if a line of 3 winning characters is found.
     */
    private boolean checkWinningConfiguration() {
        // All possible segments of length 3 in a 4x4 grid
        int[][] winLines = {
            // Horizontal segments
            {0, 1, 2}, {1, 2, 3}, {4, 5, 6}, {5, 6, 7}, 
            {8, 9, 10}, {9, 10, 11}, {12, 13, 14}, {13, 14, 15},

            // Vertical segments
            {0, 4, 8}, {4, 8, 12}, {1, 5, 9}, {5, 9, 13}, 
            {2, 6, 10}, {6, 10, 14}, {3, 7, 11}, {7, 11, 15},

            // Diagonal segments (top-left to bottom-right)
            {0, 5, 10}, {5, 10, 15}, {1, 6, 11}, {4, 9, 14},

            // Diagonal segments (top-right to bottom-left)
            {3, 6, 9}, {6, 9, 12}, {2, 5, 8}, {7, 10, 13}
        };

        for (int[] line : winLines) {
            if (isLineWinning(line)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Helper to check if a specific set of indices contains the winning character.
     */
    private boolean isLineWinning(int[] indices) {
        for (int index : indices) {
            if (grid[index] != WINNING_CHAR) {
                return false;
            }
        }
        return true;
    }

    /**
     * Outputs the result to standard output.
     */
    private void printResult(boolean isWinning) {
        System.out.println(isWinning ? "YES" : "NO");
    }
}

import java.util.Scanner;

/**
 * Analyzes a 4x4 game board to detect if any sequence of 3 cells 
 * contains exactly two 'x' players and one empty cell.
 */
public class TicTacToeAnalyzer {

    // Constants to improve maintainability
    private static final int GRID_SIZE = 4;
    private static final int SEQUENCE_LENGTH = 3;

    private static final int PLAYER_X = 1;
    private static final int PLAYER_O = -1;
    private static final int EMPTY_CELL = 0;

    private static final int REQUIRED_X_COUNT = 2;
    private static final int REQUIRED_EMPTY_COUNT = 1;

    public static void main(String[] args) {
        TicTacToeAnalyzer analyzer = new TicTacToeAnalyzer();
        analyzer.run();
    }

    /**
     * Orchestrates the program execution.
     */
    public void run() {
        int[][] grid = readGridFromConsole();

        if (hasWinningPattern(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Reads the 4x4 grid from standard input.
     * @return A 2D integer array representing the board.
     */
    private int[][] readGridFromConsole() {
        Scanner scanner = new Scanner(System.in);
        int[][] grid = new int[GRID_SIZE][GRID_SIZE];

        for (int i = 0; i < GRID_SIZE; i++) {
            String rowString = scanner.next();
            for (int j = 0; j < GRID_SIZE; j++) {
                grid[i][j] = mapCharToValue(rowString.charAt(j));
            }
        }
        return grid;
    }

    /**
     * Maps the character input to integer values used for logic.
     */
    private int mapCharToValue(char c) {
        switch (c) {
            case 'x': return PLAYER_X;
            case 'o': return PLAYER_O;
            case '.': return EMPTY_CELL;
            default:  return EMPTY_CELL;
        }
    }

    /**
     * Iterates through every cell and every direction to find the target pattern.
     * @param grid The 2D game board.
     * @return true if the pattern is found, false otherwise.
     */
    private boolean hasWinningPattern(int[][] grid) {
        // Direction vectors: {rowDelta, colDelta}
        // Horizontal, Vertical, Diagonal Down-Right, Diagonal Down-Left
        int[][] directions = {
            {0, 1}, 
            {1, 0}, 
            {1, 1}, 
            {1, -1}
        };

        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                for (int[] dir : directions) {
                    if (checkLinePattern(grid, r, c, dir[0], dir[1])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a sequence of cells starting from (startR, startC) in a specific 
     * direction matches the winning criteria.
     */
    private boolean checkLinePattern(int[][] grid, int startR, int startC, int dr, int dc) {
        int xCount = 0;
        int emptyCount = 0;

        for (int step = 0; step < SEQUENCE_LENGTH; step++) {
            int currR = startR + (step * dr);
            int currC = startC + (step * dc);

            // If the sequence goes out of bounds, it's not a valid line
            if (isOutOfBounds(currR, currC)) {
                return false;
            }

            int cellValue = grid[currR][currC];
            if (cellValue == PLAYER_X) {
                xCount++;
            } else if (cellValue == EMPTY_CELL) {
                emptyCount++;
            }
        }

        return xCount == REQUIRED_X_COUNT && emptyCount == REQUIRED_EMPTY_COUNT;
    }

    /**
     * Helper to validate grid boundaries.
     */
    private boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= GRID_SIZE || c < 0 || c >= GRID_SIZE;
    }
}

