            for (int x = 0; x < GRID_SIZE; x++) {
                grid[y][x] = rowString.charAt(x);
            }
        }
        return grid;
    }

    /**
     * Iterates through the grid to find an empty cell, places a player cell,
     * and checks if that results in a win.
     */
    private boolean canWinByPlacingOne(char[][] grid) {
        for (int y = 0; y < GRID_SIZE; y++) {
            for (int x = 0; x < GRID_SIZE; x++) {
                if (grid[y][x] == EMPTY_CELL) {
                    // Try placing the piece
                    grid[y][x] = PLAYER_CELL;

                    if (hasWinningSequence(grid)) {
                        return true;
                    }

                    // Backtrack
                    grid[y][x] = EMPTY_CELL;
                }
            }
        }
        return false;
    }

    /**
     * Checks if the current grid state contains a winning sequence.
     */
    private boolean hasWinningSequence(char[][] grid) {
        for (int y = 0; y < GRID_SIZE; y++) {
            for (int x = 0; x < GRID_SIZE; x++) {
                if (grid[y][x] == PLAYER_CELL) {
                    if (checkAllDirections(grid, y, x)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks all 4 possible directions from a specific cell to find a winning sequence.
     */
    private boolean checkAllDirections(char[][] grid, int startY, int startX) {
        for (int[] direction : DIRECTIONS) {
            if (isSequencePresent(grid, startY, startX, direction[0], direction[1])) {
                return true;
            }
        }
        return false;
    }

    /**
     * Validates if a sequence of the required length exists in a specific direction.
     */
    private boolean isSequencePresent(char[][] grid, int startY, int startX, int deltaY, int deltaX) {
        int count = 0;
        for (int i = 0; i < WINNING_SEQUENCE_LENGTH; i++) {
            int currentY = startY + (i * deltaY);
            int currentX = startX + (i * deltaX);

            if (isValidPosition(currentY, currentX) && grid[currentY][currentX] == PLAYER_CELL) {
                count++;
            } else {
                break;
            }
        }
        return count == WINNING_SEQUENCE_LENGTH;
    }

    private boolean isValidPosition(int y, int x) {
        return y >= 0 && y < GRID_SIZE && x >= 0 && x < GRID_SIZE;
    }
}

import java.util.Scanner;

/**
 * A program that detects specific patterns in a 4x4 grid.
 * Patterns: [X, X, .], [., X, X], or [X, ., X] in any straight line.
 */
public class Main {

    private static final int GRID_SIZE = 4;

    // Directional vectors for: Horizontal, Vertical, Diagonal (\), and Anti-Diagonal (/)
    private static final int[][] DIRECTIONS = {
            {0, 1},
            {1, 0},
            {1, 1},
            {1, -1}
    };

    /**
     * Represents the possible states of a cell in the grid.
     */
    enum Cell {
        O, X, DOT;

        /**
         * Converts a character input into a Cell enum.
         * @param c The character from the input string.
         * @return The corresponding Cell.
         */
        static Cell fromChar(char c) {
            switch (c) {
                case 'x': return X;
                case 'o': return O;
                case '.': return DOT;
                default:
                    throw new IllegalArgumentException("Invalid cell character: " + c);
            }
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        try {
            Cell[][] grid = parseGrid(scanner);
            boolean found = containsPattern(grid);
            System.out.println(found ? "YES" : "NO");
        } catch (Exception e) {
            // In a production environment, use a proper logging framework.
            System.err.println("Error processing input: " + e.getMessage());
        } finally {
            scanner.close();
        }
    }

    /**
     * Reads the 4x4 grid from standard input.
     */
    private static Cell[][] parseGrid(Scanner scanner) {
        Cell[][] grid = new Cell[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            if (!scanner.hasNextLine()) {
                throw new RuntimeException("Input ended prematurely.");
            }
            String line = scanner.nextLine();
            for (int j = 0; j < GRID_SIZE; j++) {
                grid[i][j] = Cell.fromChar(line.charAt(j));
            }
        }
        return grid;
    }

    /**
     * Iterates through the grid to find any matching patterns in any direction.
     */
    private static boolean containsPattern(Cell[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                for (int[] dir : DIRECTIONS) {
                    if (isPatternAtCell(grid, r, c, dir)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a specific cell acts as the middle of a valid pattern in a given direction.
     */
    private static boolean isPatternAtCell(Cell[][] grid, int r, int c, int[] dir) {
        int rPrev = r - dir[0];
        int cPrev = c - dir[1];
        int rNext = r + dir[0];
        int cNext = c + dir[1];

        // Ensure the neighbors (the ends of the 3-cell triplet) are within bounds
        if (isOutOfBounds(rPrev, cPrev) || isOutOfBounds(rNext, cNext)) {
            return false;
        }

        return isPatternMatch(grid[rPrev][cPrev], grid[r][c], grid[rNext][cNext]);
    }

    /**
     * Determines if a sequence of three cells matches the required patterns:
     * 1. [X, X, .]
     * 2. [., X, X]
     * 3. [X, ., X]
     */
    private static boolean isPatternMatch(Cell p1, Cell p2, Cell p3) {
        // Pattern type 1 & 2: Middle element is 'X'
        if (p2 == Cell.X) {
            return (p1 == Cell.X && p3 == Cell.DOT) || (p1 == Cell.DOT && p3 == Cell.X);
        }
        // Pattern type 3: Middle element is '.'
        if (p2 == Cell.DOT) {
            return p1 == Cell.X && p3 == Cell.X;
        }
        return false;
    }

    private static boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= GRID_SIZE || c < 0 || c >= GRID_SIZE;
    }
}

import java.util.*;
import java.io.*;

/**
 * Solution for the Berland Crossword problem.
 * The goal is to determine if there exists a straight line of 3 cells 
 * (horizontal, vertical, or diagonal) that covers all 'x' characters 
 * present in a 4x4 grid.
 */
public class Main {

    private static final int GRID_SIZE = 4;
    private static final char TARGET_CHAR = 'x';

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        char[][] grid = reader.readGrid(GRID_SIZE);

        if (canCoverAllX(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Orchestrates the search for a valid 3-cell segment.
     * 
     * @param grid The 4x4 character grid.
     * @return true if a segment exists that covers all 'x's, false otherwise.
     */
    private static boolean canCoverAllX(char[][] grid) {
        List<Point> xPositions = findXPositions(grid);

        // If there are no 'x's in the grid, any 3-cell segment covers all 'x's.
        if (xPositions.isEmpty()) {
            return true;
        }

        // Define the 4 possible directions for a straight line: 
        // {row_delta, col_delta}
        int[][] directions = {
            {0, 1},  // Horizontal
            {1, 0},  // Vertical
            {1, 1},  // Diagonal Down-Right
            {1, -1}  // Diagonal Down-Left
        };

        // Iterate through every cell as a potential starting point for a segment
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                for (int[] dir : directions) {
                    if (isSegmentValid(r, c, dir[0], dir[1], xPositions)) {
                        return true;
                    }
                }
            }
        }

        return false;
    }

    /**
     * Checks if a 3-cell segment starting at (startR, startC) in direction (dr, dc)
     * contains all the target 'x' coordinates.
     */
    private static boolean isSegmentValid(int startR, int startC, int dr, int dc, List<Point> xPositions) {
        Set<Point> segmentPoints = new HashSet<>();

        for (int i = 0; i < 3; i++) {
            int currR = startR + (i * dr);
            int currC = startC + (i * dc);

            // Ensure the segment cell is within the grid boundaries
            if (isOutOfBounds(currR, currC)) {
                return false;
            }
            segmentPoints.add(new Point(currR, currC));
        }

        // Check if every 'x' position in the grid is part of this segment
        for (Point xPos : xPositions) {
            if (!segmentPoints.contains(xPos)) {
                return false;
            }
        }

        return true;
    }

    private static boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= GRID_SIZE || c < 0 || c >= GRID_SIZE;
    }

    private static List<Point> findXPositions(char[][] grid) {
        List<Point> positions = new ArrayList<>();
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                if (grid[r][c] == TARGET_CHAR) {
                    positions.add(new Point(r, c));
                }
            }
        }
        return positions;
    }

    /**
     * Immutable representation of a grid coordinate.
     */
    private static final class Point {
        private final int r;
        private final int c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Point)) return false;
            Point point = (Point) o;
            return r == point.r && c == point.c;
        }

        @Override
        public int hashCode() {
            return Objects.hash(r, c);
        }
    }

    /**
     * Utility class for efficient input reading.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public char[][] readGrid(int size) {
            char[][] grid = new char[size][size];
            for (int i = 0; i < size; i++) {
                String line = next();
                if (line == null) break;
                for (int j = 0; j < size; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }
            return grid;
        }
    }
}

