/**
 * Represents the game logic for a grid-based connection game.
 */
class GridGame {
    private static final char EMPTY = '.';
    private static final char PLAYER_X = 'x';

    private final int gridSize;
    private final int winningLength;
    private char[][] grid;

    /**
     * @param gridSize The dimensions of the square grid.
     * @param winningLength The number of consecutive pieces required to win.
     */
    public GridGame(int gridSize, int winningLength) {
        this.gridSize = gridSize;
        this.winningLength = winningLength;
        this.grid = new char[gridSize][gridSize];
    }

    /**
     * Reads the grid from the provided scanner.
     * @param scanner The scanner to read from.
     */
    public void loadGrid(Scanner scanner) {
        for (int i = 0; i < gridSize; i++) {
            String line = scanner.next();
            if (line.length() < gridSize) {
                throw new IllegalArgumentException("Input row length mismatch.");
            }
            grid[i] = line.toCharArray();
        }
    }

    /**
     * Iterates through all empty cells and checks if placing an 'x' 
     * results in a win.
     * 
     * @return true if a move exists that creates a winning sequence.
     */
    public boolean canWinWithOneMove() {
        for (int r = 0; r < gridSize; r++) {
            for (int c = 0; c < gridSize; c++) {
                if (grid[r][c] == EMPTY) {
                    // Try placing the piece
                    grid[r][c] = PLAYER_X;

                    if (hasWinningSequence()) {
                        return true;
                    }

                    // Backtrack: restore the cell
                    grid[r][c] = EMPTY;
                }
            }
        }
        return false;
    }

    /**
     * Checks if there is any sequence of PLAYER_X of length winningLength 
     * in any direction on the current grid.
     */
    private boolean hasWinningSequence() {
        // Directions: {row_delta, col_delta}
        // Horizontal, Vertical, Diagonal Down-Right, Diagonal Down-Left
        int[][] directions = {
            {0, 1},
            {1, 0},
            {1, 1},
            {1, -1}
        };

        for (int r = 0; r < gridSize; r++) {
            for (int c = 0; c < gridSize; c++) {
                for (int[] dir : directions) {
                    if (checkSequenceAt(r, c, dir[0], dir[1])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a winning sequence starts at (startR, startC) in the given direction.
     */
    private boolean checkSequenceAt(int startR, int startC, int dr, int dc) {
        for (int i = 0; i < winningLength; i++) {
            int currR = startR + (i * dr);
            int currC = startC + (i * dc);

            if (!isValidPosition(currR, currC) || grid[currR][currC] != PLAYER_X) {
                return false;
            }
        }
        return true;
    }

    private boolean isValidPosition(int r, int c) {
        return r >= 0 && r < gridSize && c >= 0 && c < gridSize;
    }
}

import java.util.Scanner;

/**
 * Solution to detect if a '.' cell in a 4x4 grid is part of a 3-cell 
 * straight line consisting of two 'x' cells and one '.' cell.
 */
public class Solution {

    private static final int GRID_SIZE = 4;
    private static final char TARGET_CHAR = 'x';
    private static final char EMPTY_CHAR = '.';

    // Direction vectors representing the four possible axes:
    // Horizontal, Vertical, Diagonal (Down-Right), and Diagonal (Down-Left)
    private static final int[][] DIRECTIONS = {
            {0, 1},  // Horizontal
            {1, 0},  // Vertical
            {1, 1},  // Diagonal Down-Right
            {1, -1}  // Diagonal Down-Left
    };

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] board = readBoard(scanner);

        if (findPattern(board)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Reads the 4x4 grid from standard input.
     * 
     * @param scanner The scanner to read from.
     * @return A 2D char array representing the board.
     */
    private static char[][] readBoard(Scanner scanner) {
        char[][] board = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            if (scanner.hasNextLine()) {
                String line = scanner.nextLine().trim();
                for (int j = 0; j < GRID_SIZE && j < line.length(); j++) {
                    board[i][j] = line.charAt(j);
                }
            }
        }
        return board;
    }

    /**
     * Iterates through the board to find if any empty cell satisfies the pattern.
     * 
     * @param board The 4x4 game board.
     * @return true if the pattern is found, false otherwise.
     */
    private static boolean findPattern(char[][] board) {
        for (int i = 0; i < GRID_SIZE; i++) {
            for (int j = 0; j < GRID_SIZE; j++) {
                // The pattern must involve an empty cell '.'
                if (board[i][j] == EMPTY_CHAR) {
                    if (isCellPartOfPattern(board, i, j)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if the empty cell at (row, col) is part of a triplet of 
     * three consecutive cells that contain exactly two 'x' characters.
     * 
     * @param board The 4x4 game board.
     * @param row The row index of the empty cell.
     * @param col The column index of the empty cell.
     * @return true if the cell is part of a valid sequence.
     */
    private static boolean isCellPartOfPattern(char[][] board, int row, int col) {
        for (int[] dir : DIRECTIONS) {
            int dr = dir[0];
            int dc = dir[1];

            // A triplet containing the current '.' cell can have three configurations:
            // 1. [X, X, .] -> The '.' is the third element in the sequence
            if (isX(board, row - 2 * dr, col - 2 * dc) && isX(board, row - dr, col - dc)) {
                return true;
            }

            // 2. [X, ., X] -> The '.' is the middle element in the sequence
            if (isX(board, row - dr, col - dc) && isX(board, row + dr, col + dc)) {
                return true;
            }

            // 3. [., X, X] -> The '.' is the first element in the sequence
            if (isX(board, row + dr, col + dc) && isX(board, row + 2 * dr, col + 2 * dc)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Safely checks if a cell at a given coordinate contains the target 'x'.
     * Handles boundary checks automatically.
     * 
     * @param board The 4x4 game board.
     * @param r Row index.
     * @param c Column index.
     * @return true if the cell is within bounds and contains 'x'.
     */
    private static boolean isX(char[][] board, int r, int c) {
        return r >= 0 && r < GRID_SIZE && 
               c >= 0 && c < GRID_SIZE && 
               board[r][c] == TARGET_CHAR;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * A utility to determine if placing a single marker in an empty cell 
 * of a grid creates a line of three consecutive markers.
 */
public class GridPatternMatcher {

    private static final int GRID_SIZE = 4;
    private static final char EMPTY_CELL = '.';
    private static final char MARKER = 'x';
    private static final String SUCCESS_MESSAGE = "YES";
    private static final String FAILURE_MESSAGE = "NO";

    // Direction vectors for 8 possible movements: 
    // N, S, E, W, NE, NW, SE, SW
    private static final int[] ROW_DIRECTIONS = {0, 0, 1, -1, 1, 1, -1, -1};
    private static final int[] COL_DIRECTIONS = {1, -1, 0, 0, 1, -1, 1, -1};

    public static void main(String[] args) {
        try {
            FastReader reader = new FastReader(System.in);
            char[][] grid = readGrid(reader);

            if (canFormThreeInARow(grid)) {
                System.out.println(SUCCESS_MESSAGE);
            } else {
                System.out.println(FAILURE_MESSAGE);
            }
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Reads the 4x4 grid from the input.
     */
    private static char[][] readGrid(FastReader reader) throws IOException {
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            String rowString = reader.next();
            for (int j = 0; j < GRID_SIZE; j++) {
                grid[i][j] = rowString.charAt(j);
            }
        }
        return grid;
    }

    /**
     * Iterates through the grid to find an empty cell that, when filled,
     * creates a sequence of three markers in any direction.
     */
    private static boolean canFormThreeInARow(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                if (grid[r][c] == EMPTY_CELL) {
                    // Tentatively place a marker
                    grid[r][c] = MARKER;

                    if (hasThreeInARow(grid)) {
                        return true;
                    }

                    // Backtrack: remove the marker
                    grid[r][c] = EMPTY_CELL;
                }
            }
        }
        return false;
    }

    /**
     * Checks if there is any line of three consecutive markers in the grid.
     */
    private static boolean hasThreeInARow(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                // Only start checking from a cell that contains a marker
                if (grid[r][c] == MARKER) {
                    for (int dir = 0; dir < 8; dir++) {
                        if (checkDirection(grid, r, c, ROW_DIRECTIONS[dir], COL_DIRECTIONS[dir])) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a line of three markers exists starting from (row, col) in a specific direction.
     */
    private static boolean checkDirection(char[][] grid, int row, int col, int dr, int dc) {
        for (int step = 0; step < 3; step++) {
            int targetRow = row + (step * dr);
            int targetCol = col + (step * dc);

            if (!isWithinBounds(targetRow, targetCol) || grid[targetRow][targetCol] != MARKER) {
                return false;
            }
        }
        return true;
    }

    private static boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
    }

    /**
     * Fast I/O utility for efficient reading.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) {
                    return null;
                }
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }
    }
}

import java.util.Scanner;

/**
 * A utility to detect specific patterns in a 4x4 grid.
 * The pattern is defined as a sequence of three adjacent cells 
 * (horizontal, vertical, or diagonal) containing exactly two 'x' characters and one '.' character.
 */
public class GridPatternMatcher {

    private static final int GRID_SIZE = 4;
    private static final char TARGET_X = 'x';
    private static final char TARGET_DOT = '.';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] grid = readGrid(scanner, GRID_SIZE);
        scanner.close();

        if (hasTargetPattern(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Reads a square grid from the standard input.
     */
    private static char[][] readGrid(Scanner scanner, int size) {
        char[][] grid = new char[size][size];
        for (int i = 0; i < size; i++) {
            if (scanner.hasNext()) {
                String row = scanner.next();
                for (int j = 0; j < size; j++) {
                    grid[i][j] = row.charAt(j);
                }
            }
        }
        return grid;
    }

    /**
     * Iterates through the grid and checks all possible 3-cell sequences in all directions.
     */
    private static boolean hasTargetPattern(char[][] grid) {
        // Direction vectors: Horizontal, Vertical, Diagonal (down-right), Anti-diagonal (down-left)
        int[] dr = {0, 1, 1, 1};
        int[] dc = {1, 0, 1, -1};

        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                for (int d = 0; d < 4; d++) {
                    if (checkSequenceAt(grid, r, c, dr[d], dc[d])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a sequence of three cells starting from (r, c) in direction (dr, dc) 
     * matches the required pattern.
     */
    private static boolean checkSequenceAt(char[][] grid, int r, int c, int dr, int dc) {
        int rEnd = r + 2 * dr;
        int cEnd = c + 2 * dc;

        // Ensure the entire sequence of three cells is within grid boundaries
        if (isWithinBounds(rEnd, cEnd)) {
            return matchesPattern(
                grid[r][c], 
                grid[r + dr][c + dc], 
                grid[rEnd][cEnd]
            );
        }
        return false;
    }

    /**
     * Determines if the three provided characters match the criteria:
     * exactly two 'x' and one '.'.
     */
    private static boolean matchesPattern(char c1, char c2, char c3) {
        int xCount = 0;
        int dotCount = 0;
        char[] trio = {c1, c2, c3};

        for (char ch : trio) {
            if (ch == TARGET_X) {
                xCount++;
            } else if (ch == TARGET_DOT) {
                dotCount++;
            }
        }

        return xCount == 2 && dotCount == 1;
    }

    /**
     * Validates if the given coordinates are inside the grid.
     */
    private static boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
    }
}

import java.util.Scanner;

/**
 * A utility to determine if a player can win a 4x4 grid-based game
 * by placing a single piece to complete a line of three.
 */
public class WinConditionChecker {

    private static final int GRID_SIZE = 4;
    private static final int WIN_LENGTH = 3;
    private static final char EMPTY_CELL = '.';
    private static final char PLAYER_PIECE = 'x';

    // Directional vectors for: Horizontal, Vertical, Diagonal (Down-Right), Diagonal (Down-Left)
    private static final int[][] DIRECTIONS = {
            {0, 1},  // Horizontal
            {1, 0},  // Vertical
            {1, 1},  // Diagonal Down-Right
            {1, -1}  // Diagonal Down-Left
    };

    public static void main(String[] args) {
        char[][] board = readBoard();

        if (canWinWithOneMove(board)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Reads a 4x4 grid from standard input.
     */
    private static char[][] readBoard() {
        Scanner scanner = new Scanner(System.in);
        char[][] board = new char[GRID_SIZE][GRID_SIZE];

        for (int i = 0; i < GRID_SIZE; i++) {
            String rowInput = scanner.next();
            for (int j = 0; j < GRID_SIZE; j++) {
                board[i][j] = rowInput.charAt(j);
            }
        }
        return board;
    }

    /**
     * Iterates through every empty cell to see if placing a piece there
     * results in a winning condition.
     */
    private static boolean canWinWithOneMove(char[][] board) {
        for (int i = 0; i < GRID_SIZE; i++) {
            for (int j = 0; j < GRID_SIZE; j++) {
                if (board[i][j] == EMPTY_CELL) {
                    // Try placing the piece
                    board[i][j] = PLAYER_PIECE;

                    if (hasWinningLine(board)) {
                        // Clean up before returning true (though not strictly necessary here)
                        board[i][j] = EMPTY_CELL;
                        return true;
                    }

                    // Backtrack (reset cell)
                    board[i][j] = EMPTY_CELL;
                }
            }
        }
        return false;
    }

    /**
     * Scans the entire board to check if any line of the required length exists.
     */
    private static boolean hasWinningLine(char[][] board) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                // Optimization: only start checking if the current cell is a piece
                if (board[r][c] == PLAYER_PIECE) {
                    if (checkAllDirections(board, r, c)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a winning line starts from the given coordinates in any direction.
     */
    private static boolean checkAllDirections(char[][] board, int row, int col) {
        for (int[] direction : DIRECTIONS) {
            if (isLinePresent(board, row, col, direction[0], direction[1])) {
                return true;
            }
        }
        return false;
    }

    /**
     * Checks if a continuous line of pieces exists in a specific direction.
     */
    private static boolean isLinePresent(char[][] board, int row, int col, int dr, int dc) {
        for (int step = 1; step < WIN_LENGTH; step++) {
            int nextRow = row + (dr * step);
            int nextCol = col + (dc * step);

            if (isOutOfBounds(nextRow, nextCol) || board[nextRow][nextCol] != PLAYER_PIECE) {
                return false;
            }
        }
        return true;
    }

    private static boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= GRID_SIZE || c < 0 || c >= GRID_SIZE;
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * GridPatternMatcher scans a 4x4 grid for specific character patterns 
 * within rows, columns, and diagonals.
 */
public class GridPatternMatcher {

    private static final int GRID_SIZE = 4;
    private static final String PATTERN_A = "xx.";
    private static final String PATTERN_B = ".xx";
    private static final String PATTERN_C = "x.x";

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] grid = readGrid(scanner);
        scanner.close();

        if (hasMatchingPattern(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Reads a 4x4 grid from the standard input.
     */
    private static char[][] readGrid(Scanner scanner) {
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            if (scanner.hasNext()) {
                String line = scanner.next();
                // Ensure we handle cases where input might be shorter than expected
                for (int j = 0; j < GRID_SIZE && j < line.length(); j++) {
                    grid[i][j] = line.charAt(j);
                }
            }
        }
        return grid;
    }

    /**
     * Orchestrates the search across all possible lines in the grid.
     */
    private static boolean hasMatchingPattern(char[][] grid) {
        List<String> linesToSearch = new ArrayList<>();

        // 1. Add Rows
        for (int i = 0; i < GRID_SIZE; i++) {
            linesToSearch.add(new String(grid[i]));
        }

        // 2. Add Columns
        for (int j = 0; j < GRID_SIZE; j++) {
            StringBuilder col = new StringBuilder();
            for (int i = 0; i < GRID_SIZE; i++) {
                col.append(grid[i][j]);
            }
            linesToSearch.add(col.toString());
        }

        // 3. Add Diagonals (Main diagonals and sub-diagonals)
        // Main diagonals (Length 4)
        linesToSearch.add(getDiagonal(grid, 0, 0, 1, 1));
        linesToSearch.add(getDiagonal(grid, 0, 3, 1, -1));

        // Left-leaning sub-diagonals (Length 3)
        linesToSearch.add(getDiagonal(grid, 1, 0, 1, 1));
        linesToSearch.add(getDiagonal(grid, 0, 1, 1, 1));

        // Right-leaning sub-diagonals (Length 3)
        linesToSearch.add(getDiagonal(grid, 0, 2, 1, -1));
        linesToSearch.add(getDiagonal(grid, 1, 3, 1, -1));

        // Evaluate all collected lines
        for (String line : linesToSearch) {
            if (containsTargetPattern(line)) {
                return true;
            }
        }

        return false;
    }

    /**
     * Extracts a diagonal string based on a starting point and direction.
     * 
     * @param grid The character grid.
     * @param startRow Starting row index.
     * @param startCol Starting column index.
     * @param rowStep Direction to move in rows (1 or -1).
     * @param colStep Direction to move in columns (1 or -1).
     * @return A string representing the diagonal.
     */
    private static String getDiagonal(char[][] grid, int startRow, int startCol, int rowStep, int colStep) {
        StringBuilder sb = new StringBuilder();
        int r = startRow;
        int c = startCol;

        // We attempt to collect up to 4 characters, constrained by grid boundaries
        for (int i = 0; i < 4; i++) {
            if (r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE) {
                sb.append(grid[r][c]);
                r += rowStep;
                c += colStep;
            } else {
                break;
            }
        }
        return sb.toString();
    }

    /**
     * Checks if a string contains any of the target patterns.
     */
    private static boolean containsTargetPattern(String sequence) {
        return sequence.contains(PATTERN_A) || 
               sequence.contains(PATTERN_B) || 
               sequence.contains(PATTERN_C);
    }
}

import java.util.Scanner;

/**
 * A class that represents a 4x4 grid game and determines if a winning move
 * can be made by placing a single 'x' in an empty '.' cell.
 */
class GridGame {
    private static final int GRID_SIZE = 4;
    private static final char EMPTY = '.';
    private static final char PLAYER_PIECE = 'x';
    private static final int WINNING_COUNT = 3;

    private final char[][] grid = new char[GRID_SIZE][GRID_SIZE];

    // Directions represented as [rowDelta, colDelta]
    // Horizontal, Vertical, Diagonal, Anti-Diagonal
    private static final int[][] DIRECTIONS = {
        {0, 1}, 
        {1, 0}, 
        {1, 1}, 
        {1, -1}
    };

    public GridGame(char[][] initialGrid) {
        for (int i = 0; i < GRID_SIZE; i++) {
            System.arraycopy(initialGrid[i], 0, this.grid[i], 0, GRID_SIZE);
        }
    }

    /**
     * Checks if placing a single 'x' in any empty cell results in 
     * at least three consecutive 'x's in any direction.
     * 
     * @return true if a winning move exists, false otherwise.
     */
    public boolean canWinWithOneMove() {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                if (grid[r][c] == EMPTY) {
                    if (tryMoveAndCheckWin(r, c)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    private boolean tryMoveAndCheckWin(int row, int col) {
        // Place the piece
        grid[row][col] = PLAYER_PIECE;

        boolean winFound = isWinningPosition(row, col);

        // Backtrack: restore the cell to empty
        grid[row][col] = EMPTY;

        return winFound;
    }

    private boolean isWinningPosition(int row, int col) {
        for (int[] dir : DIRECTIONS) {
            int dr = dir[0];
            int dc = dir[1];

            // Count consecutive pieces in the current direction and the opposite direction
            int count = 1 // The piece we just placed
                      + countConsecutive(row, col, dr, dc) 
                      + countConsecutive(row, col, -dr, -dc);

            if (count >= WINNING_COUNT) {
                return true;
            }
        }
        return false;
    }

    /**
     * Counts consecutive pieces starting from the neighbor of (row, col) 
     * in the specified direction.
     */
    private int countConsecutive(int row, int col, int dr, int dc) {
        int count = 0;
        int currR = row + dr;
        int currC = col + dc;

        while (isWithinBounds(currR, currC) && grid[currR][currC] == PLAYER_PIECE) {
            count++;
            currR += dr;
            currC += dc;
        }
        return count;
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
    }
}

