import java.util.Scanner;

/**
 * A solver for a Tic-Tac-Toe variant on a 4x4 grid.
 * The goal is to determine if placing exactly one 'x' on a '.' cell
 * creates a sequence of three 'x's in a row, column, or diagonal.
 */
public class TicTacToeSolver {

    private static final int GRID_SIZE = 4;
    private static final int WIN_LENGTH = 3;
    private static final char EMPTY_CELL = '.';
    private static final char PLAYER_PIECE = 'x';

    public static void main(String[] args) {
        TicTacToeSolver solver = new TicTacToeSolver();
        solver.run();
    }

    /**
     * Orchestrates the program flow.
     */
    public void run() {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNext()) {
            scanner.close();
            return;
        }

        char[][] board = readBoard(scanner);

        if (canWinInOneMove(board)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Reads the grid from standard input.
     * 
     * @param scanner The input scanner.
     * @return A 2D array representing the board.
     */
    private char[][] readBoard(Scanner scanner) {
        char[][] board = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            String row = scanner.next();
            for (int j = 0; j < GRID_SIZE; j++) {
                board[i][j] = row.charAt(j);
            }
        }
        return board;
    }

    /**
     * Tries placing a piece in every possible empty cell to see if it results in a win.
     * 
     * @param board The current state of the board.
     * @return true if any move leads to a win, false otherwise.
     */
    private boolean canWinInOneMove(char[][] board) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                if (board[r][c] == EMPTY_CELL) {
                    // Try placing the piece
                    board[r][c] = PLAYER_PIECE;

                    if (hasWinningSequence(board)) {
                        return true;
                    }

                    // Backtrack: revert the cell to empty for the next iteration
                    board[r][c] = EMPTY_CELL;
                }
            }
        }
        return false;
    }

    /**
     * Checks if the board contains any sequence of length WIN_LENGTH.
     * 
     * @param board The board to check.
     * @return true if a winning sequence is found.
     */
    private boolean hasWinningSequence(char[][] board) {
        // Direction vectors: {rowDelta, colDelta}
        // This covers Horizontal, Vertical, Diagonal Down-Right, and Diagonal Down-Left
        int[][] directions = {
            {0, 1},  
            {1, 0},  
            {1, 1},  
            {1, -1}  
        };

        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                // Optimization: only start checking if the current cell is the player's piece
                if (board[r][c] != PLAYER_PIECE) {
                    continue;
                }

                for (int[] dir : directions) {
                    if (checkDirection(board, r, c, dir[0], dir[1])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Validates if a sequence of pieces exists starting from (r, c) in a given direction.
     * 
     * @param board The board to check.
     * @param r Starting row.
     * @param c Starting column.
     * @param dr Row delta (direction).
     * @param dc Column delta (direction).
     * @return true if the sequence is complete.
     */
    private boolean checkDirection(char[][] board, int r, int c, int dr, int dc) {
        for (int i = 1; i < WIN_LENGTH; i++) {
            int nextR = r + (i * dr);
            int nextC = c + (i * dc);

            if (isOutOfBounds(nextR, nextC) || board[nextR][nextC] != PLAYER_PIECE) {
                return false;
            }
        }
        return true;
    }

    /**
     * Helper to check if coordinates are within the grid boundaries.
     */
    private boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= GRID_SIZE || c < 0 || c >= GRID_SIZE;
    }
}

import java.util.Scanner;

/**
 * A utility to determine if a 4x4 grid contains a sequence of 3 characters 
 * (consisting of 'x' or '.') where at most one character is a '.'.
 */
public class GridPatternMatcher {

    private static final int GRID_SIZE = 4;
    private static final int TARGET_SEQUENCE_LENGTH = 3;

    // Directions: Horizontal, Vertical, and the two Diagonals
    private static final int[][] DIRECTIONS = {
        {0, 1},  // Horizontal (Right)
        {1, 0},  // Vertical (Down)
        {1, 1},  // Diagonal (Down-Right)
        {1, -1}  // Diagonal (Down-Left)
    };

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] grid = readGrid(scanner);

        if (grid != null && containsPattern(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Reads a GRID_SIZE x GRID_SIZE grid from the scanner.
     * @param scanner The input source.
     * @return A 2D char array representing the grid.
     */
    private static char[][] readGrid(Scanner scanner) {
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            if (scanner.hasNext()) {
                String line = scanner.next();
                // Ensure we don't crash if the input line is shorter than expected
                for (int j = 0; j < GRID_SIZE; j++) {
                    grid[i][j] = (j < line.length()) ? line.charAt(j) : ' ';
                }
            }
        }
        return grid;
    }

    /**
     * Iterates through every cell and direction to find a valid sequence.
     * @param grid The 2D grid.
     * @return true if a pattern is found, false otherwise.
     */
    private static boolean containsPattern(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                for (int[] direction : DIRECTIONS) {
                    if (isValidSequence(grid, r, c, direction[0], direction[1])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a sequence of a specific length starting at (startR, startC) 
     * in a given direction meets the criteria.
     * @param grid The 2D grid.
     * @param startR Starting row index.
     * @param startC Starting column index.
     * @param dr Row direction offset.
     * @param dc Column direction offset.
     * @return true if the sequence is valid (contains only 'x' or '.', and max one '.').
     */
    private static boolean isValidSequence(char[][] grid, int startR, int startC, int dr, int dc) {
        int dotCount = 0;

        for (int i = 0; i < TARGET_SEQUENCE_LENGTH; i++) {
            int currR = startR + (i * dr);
            int currC = startC + (i * dc);

            // Boundary Check
            if (isOutOfBounds(currR, currC)) {
                return false;
            }

            char cell = grid[currR][currC];
            if (cell == '.') {
                dotCount++;
            } else if (cell != 'x') {
                // If the cell is neither 'x' nor '.', the sequence is invalid
                return false;
            }

            // Optimization: Exit early if we have too many dots
            if (dotCount > 1) {
                return false;
            }
        }

        return true;
    }

    /**
     * Checks if a coordinate is outside the grid boundaries.
     */
    private static boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= GRID_SIZE || c < 0 || c >= GRID_SIZE;
    }
}

