/**
 * A utility to detect if a 4x4 grid contains a winning pattern:
 * A sequence of 3 characters (horizontal, vertical, or diagonal)
 * consisting of exactly two 'x's and one '.'
 */
public class GridPatternMatcher {

    private static final int GRID_SIZE = 4;
    private static final int SEQUENCE_LENGTH = 3;
    private static final char TARGET_X = 'x';
    private static final char TARGET_DOT = '.';

    // Direction vectors representing: Horizontal, Vertical, Diagonal Down-Right, Diagonal Down-Left
    private static final int[][] DIRECTIONS = {
        {0, 1},  // Horizontal
        {1, 0},  // Vertical
        {1, 1},  // Diagonal Down-Right
        {1, -1}  // Diagonal Down-Left
    };

    public static void main(String[] args) {
        char[][] grid = readGrid();

        if (hasWinningPattern(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Reads a 4x4 grid from standard input.
     * 
     * @return A 2D char array representing the grid.
     */
    private static char[][] readGrid() {
        Scanner scanner = new Scanner(System.in);
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];

        for (int i = 0; i < GRID_SIZE; i++) {
            if (scanner.hasNext()) {
                // Using next() to skip whitespace and handle individual lines
                grid[i] = scanner.next().toCharArray();
            }
        }
        scanner.close();
        return grid;
    }

    /**
     * Iterates through every cell in the grid and checks all possible directions
     * for the winning pattern.
     * 
     * @param grid The 4x4 character grid.
     * @return true if a pattern is found, false otherwise.
     */
    private static boolean hasWinningPattern(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                for (int[] direction : DIRECTIONS) {
                    if (isPatternAt(grid, r, c, direction[0], direction[1])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a specific sequence of 3 characters starting from (startR, startC)
     * in the given direction matches the winning criteria.
     * 
     * @param grid The grid to check.
     * @param startR Starting row index.
     * @param startC Starting column index.
     * @param dr Row direction delta.
     * @param dc Column direction delta.
     * @return true if the sequence contains exactly two 'x's and one '.'.
     */
    private static boolean isPatternAt(char[][] grid, int startR, int startC, int dr, int dc) {
        int xCount = 0;
        int dotCount = 0;

        for (int i = 0; i < SEQUENCE_LENGTH; i++) {
            int currR = startR + (i * dr);
            int currC = startC + (i * dc);

            // Boundary check: If the sequence goes out of bounds, it's not a valid line
            if (isOutOfBounds(currR, currC)) {
                return false;
            }

            char cell = grid[currR][currC];
            if (cell == TARGET_X) {
                xCount++;
            } else if (cell == TARGET_DOT) {
                dotCount++;
            }
        }

        return xCount == 2 && dotCount == 1;
    }

    /**
     * Helper to verify if a coordinate is within the grid boundaries.
     */
    private static boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= GRID_SIZE || c < 0 || c >= GRID_SIZE;
    }
}

