        private boolean canWinWithOneMove(char[][] grid) {
            for (int r = 0; r < GRID_SIZE; r++) {
                for (int c = 0; c < GRID_SIZE; c++) {
                    // Only attempt to place an 'x' in empty cells
                    if (grid[r][c] == '.') {
                        grid[r][c] = 'x';
                        if (hasThreeInARow(grid)) {
                            grid[r][c] = '.'; // Backtrack
                            return true;
                        }
                        grid[r][c] = '.'; // Backtrack
                    }
                }
            }
            return false;
        }

        /**
         * Scans the grid to see if any direction contains the target sequence length.
         */
        private boolean hasThreeInARow(char[][] grid) {
            for (int r = 0; r < GRID_SIZE; r++) {
                for (int c = 0; c < GRID_SIZE; c++) {
                    if (grid[r][c] == 'x') {
                        if (checkAllDirections(grid, r, c)) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        private boolean checkAllDirections(char[][] grid, int row, int col) {
            for (int[] dir : DIRECTIONS) {
                if (isSequencePresent(grid, row, col, dir[0], dir[1])) {
                    return true;
                }
            }
            return false;
        }

        private boolean isSequencePresent(char[][] grid, int startR, int startC, int dr, int dc) {
            for (int step = 1; step < WIN_SEQUENCE_LENGTH; step++) {
                int nextR = startR + (dr * step);
                int nextC = startC + (dc * step);

                if (!isWithinBounds(nextR, nextC) || grid[nextR][nextC] != 'x') {
                    return false;
                }
            }
            return true;
        }

        private boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
        }
    }

    /**
     * Optimized reader for fast I/O operations.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }
    }
}

