/**
 * A refactored solution to solve the grid-based pattern matching problem.
 * The goal is to find a sequence of length 3 that contains either 
 * exactly three 'x's or exactly two 'x's and one '.'.
 */
public class Main {

    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        FastPrinter out = new FastPrinter(System.out);

        BoardSolver solver = new BoardSolver();
        solver.solve(in, out);

        out.close();
    }

    static class BoardSolver {
        private static final int GRID_SIZE = 4;
        private static final int WIN_LENGTH = 3;
        private static final char X = 'x';
        private static final char DOT = '.';

        // Direction vectors: Horizontal, Vertical, Diagonal Down-Right, Diagonal Down-Left
        private final int[] dRow = {0, 1, 1, 1};
        private final int[] dCol = {1, 0, 1, -1};

        public void solve(FastScanner in, FastPrinter out) {
            char[][] board = readBoard(in);

            if (hasWinningSequence(board)) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        }

        private char[][] readBoard(FastScanner in) {
            char[][] board = new char[GRID_SIZE][GRID_SIZE];
            for (int i = 0; i < GRID_SIZE; i++) {
                String row = in.next();
                if (row != null) {
                    for (int j = 0; j < GRID_SIZE; j++) {
                        board[i][j] = row.charAt(j);
                    }
                }
            }
            return board;
        }

        private boolean hasWinningSequence(char[][] board) {
            for (int r = 0; r < GRID_SIZE; r++) {
                for (int c = 0; c < GRID_SIZE; c++) {
                    // Check all 4 directions from the current cell
                    for (int d = 0; d < 4; d++) {
                        if (isWinningLine(board, r, c, dRow[d], dCol[d])) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        private boolean isWinningLine(char[][] board, int startR, int startC, int dr, int dc) {
            int xCount = 0;
            int dotCount = 0;

            for (int k = 0; k < WIN_LENGTH; k++) {
                int currR = startR + k * dr;
                int currC = startC + k * dc;

                // Check boundaries
                if (currR < 0 || currR >= GRID_SIZE || currC < 0 || currC >= GRID_SIZE) {
                    return false;
                }

                if (board[currR][currC] == X) {
                    xCount++;
                } else if (board[currR][currC] == DOT) {
                    dotCount++;
                }
            }

            // A line is a winner if it's [x, x, x] or [x, x, .] (in any order)
            return (xCount == 3 && dotCount == 0) || (xCount == 2 && dotCount == 1);
        }
    }

    /**
     * High-performance scanner for reading input.
     */
    static class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }
    }

    /**
     * High-performance printer for writing output.
     */
    static class FastPrinter extends PrintWriter {
        public FastPrinter(OutputStream out) {
            super(out);
        }
    }
}

