/**
 * A program to determine if placing one additional 'x' on a 4x4 grid
 * results in three 'x's in a row (horizontally, vertically, or diagonally).
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        TicTacToeSolver solver = new TicTacToeSolver();
        solver.solve(reader, writer);

        writer.flush();
        writer.close();
    }

    static class TicTacToeSolver {
        private static final int GRID_SIZE = 4;
        private static final int WIN_CONDITION = 3;
        private static final char PLAYER_X = 'x';
        private static final char EMPTY_CELL = '.';

        // Direction vectors for: horizontal, vertical, diagonal down-right, diagonal down-left
        private static final int[][] DIRECTIONS = {
            {0, 1},  // Horizontal
            {1, 0},  // Vertical
            {1, 1},  // Diagonal Down-Right
            {1, -1}  // Diagonal Down-Left
        };

        /**
         * Reads the board and determines if a single move can create a win.
         */
        public void solve(FastReader in, PrintWriter out) {
            char[][] board = new char[GRID_SIZE][GRID_SIZE];

            for (int i = 0; i < GRID_SIZE; i++) {
                board[i] = in.next().toCharArray();
            }

            if (canWinWithOneMove(board)) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        }

        /**
         * Attempts to place one 'x' in every empty cell to see if it completes a row.
         */
        private boolean canWinWithOneMove(char[][] board) {
            for (int r = 0; r < GRID_SIZE; r++) {
                for (int c = 0; c < GRID_SIZE; c++) {
                    if (board[r][c] == EMPTY_CELL) {
                        // Try placing the piece
                        board[r][c] = PLAYER_X;

                        if (isWinningConfiguration(board)) {
                            // Backtrack before returning true
                            board[r][c] = EMPTY_CELL;
                            return true;
                        }

                        // Backtrack
                        board[r][c] = EMPTY_CELL;
                    }
                }
            }
            return false;
        }

        /**
         * Checks if there are at least WIN_CONDITION 'x's in any direction.
         */
        private boolean isWinningConfiguration(char[][] board) {
            for (int r = 0; r < GRID_SIZE; r++) {
                for (int c = 0; c < GRID_SIZE; c++) {
                    if (board[r][c] == PLAYER_X) {
                        if (checkAllDirections(board, r, c)) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        /**
         * Checks all 4 possible winning directions starting from a specific cell.
         */
        private boolean checkAllDirections(char[][] board, int row, int col) {
            for (int[] dir : DIRECTIONS) {
                int count = 1; // Start with the current cell

                for (int step = 1; step < WIN_CONDITION; step++) {
                    int nextR = row + (dir[0] * step);
                    int nextC = col + (dir[1] * step);

                    if (isValid(nextR, nextC) && board[nextR][nextC] == PLAYER_X) {
                        count++;
                    } else {
                        break;
                    }
                }

                if (count >= WIN_CONDITION) {
                    return true;
                }
            }
            return false;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
        }
    }

    /**
     * Efficient utility class for reading input.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

/**
 * A solver for a grid-based game where the goal is to determine if 
 * placing a single 'x' can create a sequence of three consecutive 'x's 
 * horizontally, vertically, or diagonally.
 */
public class GridGameSolver {

    private static final int GRID_SIZE = 4;
    private static final int WIN_CONDITION_LENGTH = 3;
    private static final char EMPTY = '.';
    private static final char PLAYER_PIECE = 'x';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] grid = readGrid(scanner, GRID_SIZE);
        scanner.close();

        if (canWinWithOneMove(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Reads the grid input from the scanner.
     */
    private static char[][] readGrid(Scanner sc, int size) {
        char[][] grid = new char[size][size];
        for (int i = 0; i < size; i++) {
            String line = sc.next();
            for (int j = 0; j < size; j++) {
                grid[i][j] = line.charAt(j);
            }
        }
        return grid;
    }

    /**
     * Iterates through all empty cells, simulates placing a piece, 
     * and checks if that results in a win.
     */
    public static boolean canWinWithOneMove(char[][] grid) {
        int size = grid.length;

        for (int r = 0; r < size; r++) {
            for (int c = 0; c < size; c++) {
                if (grid[r][c] == EMPTY) {
                    // Simulate move
                    grid[r][c] = PLAYER_PIECE;

                    if (hasThreeConsecutive(grid)) {
                        return true;
                    }

                    // Backtrack (undo move)
                    grid[r][c] = EMPTY;
                }
            }
        }
        return false;
    }

    /**
     * Checks if there are three consecutive player pieces anywhere in the grid.
     */
    private static boolean hasThreeConsecutive(char[][] grid) {
        int size = grid.length;

        // Direction vectors: {rowDelta, colDelta}
        // Covers: Horizontal, Vertical, Diagonal Down-Right, Diagonal Down-Left
        int[][] directions = {
            {0, 1},  // Horizontal
            {1, 0},  // Vertical
            {1, 1},  // Diagonal \
            {1, -1}  // Diagonal /
        };

        for (int r = 0; r < size; r++) {
            for (int c = 0; c < size; c++) {
                for (int[] dir : directions) {
                    if (checkSequence(grid, r, c, dir[0], dir[1])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a sequence of length WIN_CONDITION_LENGTH exists starting from (r, c)
     * moving in direction (dr, dc).
     */
    private static boolean checkSequence(char[][] grid, int r, int c, int dr, int dc) {
        int size = grid.length;

        // Check if the end of the required sequence is within bounds
        int endR = r + (WIN_CONDITION_LENGTH - 1) * dr;
        int endC = c + (WIN_CONDITION_LENGTH - 1) * dc;

        if (endR < 0 || endR >= size || endC < 0 || endC >= size) {
            return false;
        }

        // Verify all cells in the sequence match the player piece
        for (int i = 0; i < WIN_CONDITION_LENGTH; i++) {
            if (grid[r + i * dr][c + i * dc] != PLAYER_PIECE) {
                return false;
            }
        }

        return true;
    }
}

