/**
 * GridPatternSolver determines if a 4x4 grid contains a sequence of 
 * three consecutive cells (horizontal, vertical, or diagonal) 
 * that contains exactly two 'x' characters and one '.' character.
 */
public class GridPatternSolver {
    private static final int GRID_SIZE = 4;
    private static final char X_CHAR = 'x';
    private static final char DOT_CHAR = '.';

    public static void main(String[] args) {
        try {
            FastScanner scanner = new FastScanner(System.in);
            char[][] grid = scanner.readGrid(GRID_SIZE);

            if (hasValidPattern(grid)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Scans the grid for any 3-length segment containing exactly two 'x's and one '.'.
     * 
     * @param grid The 4x4 character grid.
     * @return true if a valid pattern is found, false otherwise.
     */
    private static boolean hasValidPattern(char[][] grid) {
        // Directions representing: Horizontal, Vertical, Diagonal (Down-Right), Diagonal (Down-Left)
        int[][] directions = {
            {0, 1},  // Horizontal
            {1, 0},  // Vertical
            {1, 1},  // Diagonal Down-Right
            {1, -1}  // Diagonal Down-Left
        };

        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                for (int[] dir : directions) {
                    if (isPatternMatch(grid, r, c, dir[0], dir[1])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a 3-length segment starting at (r, c) in direction (dr, dc)
     * contains exactly two 'x' and one '.'.
     */
    private static boolean isPatternMatch(char[][] grid, int r, int c, int dr, int dc) {
        // Calculate the end position of a 3-cell segment
        int endR = r + 2 * dr;
        int endC = c + 2 * dc;

        // Ensure the segment stays within the grid boundaries
        if (endR < 0 || endR >= GRID_SIZE || endC < 0 || endC >= GRID_SIZE) {
            return false;
        }

        int xCount = 0;
        int dotCount = 0;

        for (int i = 0; i < 3; i++) {
            char current = grid[r + i * dr][c + i * dc];
            if (current == X_CHAR) {
                xCount++;
            } else if (current == DOT_CHAR) {
                dotCount++;
            }
        }

        // A valid segment must have exactly two 'x' and one '.'
        return xCount == 2 && dotCount == 1;
    }
}

/**
 * FastScanner is a utility class for efficient input reading.
 */
class FastScanner {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    public FastScanner(InputStream is) {
        this.reader = new BufferedReader(new InputStreamReader(is));
    }

    public String next() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreElements()) {
            String line = reader.readLine();
            if (line == null) return null;
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    /**
     * Reads a square grid of characters from the input.
     * 
     * @param size The dimension of the square grid.
     * @return A 2D char array representing the grid.
     * @throws IOException If an I/O error occurs.
     */
    public char[][] readGrid(int size) throws IOException {
