        for (int i = 0; i < size; i++) {
            String line = reader.readLine();
            if (line == null) throw new IOException("Unexpected end of input");
            grid[i] = line.toCharArray();
        }
        return grid;
    }
}

import java.util.Scanner;

/**
 * A program to determine if a 4x4 Tic-Tac-Toe board contains 
 * a winning sequence of three 'x' characters.
 */
public class Main {

    private static final int BOARD_SIZE = 4;
    private static final int WIN_LENGTH = 3;
    private static final char PLAYER_X = 'x';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // The original code structure suggested one test case.
        // This logic can easily be wrapped in a loop if needed.
        try {
            TicTacToeBoard board = readBoard(scanner);
            if (board != null) {
                boolean isWin = board.hasWinningSequence(WIN_LENGTH, PLAYER_X);
                System.out.println(isWin ? "YES" : "NO");
            }
        } finally {
            scanner.close();
        }
    }

    /**
     * Reads the 4x4 grid from the scanner.
     * 
     * @param scanner The input source.
     * @return A TicTacToeBoard object, or null if input is invalid.
     */
    private static TicTacToeBoard readBoard(Scanner scanner) {
        char[][] grid = new char[BOARD_SIZE][BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (!scanner.hasNext()) return null;
            String line = scanner.next();
            for (int j = 0; j < BOARD_SIZE; j++) {
                if (j < line.length()) {
                    grid[i][j] = line.charAt(j);
                } else {
                    grid[i][j] = '.'; // Default to empty if line is short
                }
            }
        }
        return new TicTacToeBoard(grid);
    }

    /**
     * Represents the Tic-Tac-Toe game board and its rules.
     */
    static class TicTacToeBoard {
        private final char[][] grid;
        private final int size;

        public TicTacToeBoard(char[][] grid) {
            this.grid = grid;
            this.size = grid.length;
        }

        /**
         * Checks if there is a sequence of the specified length for the given player.
         * Searches horizontally, vertically, and diagonally.
         */
        public boolean hasWinningSequence(int winLength, char player) {
            // Possible movement directions: {rowDelta, colDelta}
            int[][] directions = {
                {0, 1},  // Horizontal
                {1, 0},  // Vertical
                {1, 1},  // Diagonal Down-Right
                {1, -1}  // Diagonal Down-Left
            };

            for (int r = 0; r < size; r++) {
                for (int c = 0; c < size; c++) {
                    // Optimization: only start checking if current cell matches player
                    if (grid[r][c] == player) {
                        for (int[] dir : directions) {
                            if (checkDirection(r, c, dir[0], dir[1], winLength, player)) {
                                return true;
                            }
                        }
                    }
                }
            }
            return false;
        }

        /**
         * Checks a specific direction from a starting point.
         */
        private boolean checkDirection(int startR, int startC, int dr, int dc, int length, char player) {
            for (int step = 1; step < length; step++) {
                int nextR = startR + (dr * step);
                int nextC = startC + (dc * step);

                if (!isWithinBounds(nextR, nextC) || grid[nextR][nextC] != player) {
                    return false;
                }
            }
            return true;
        }

        private boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < size && c >= 0 && c < size;
        }
    }
}

import java.util.Scanner;

/**
 * A solver for a 4x4 Tic-Tac-Toe variant where the goal is to find 
 * if the current player can win in a single move by completing a line of 3.
 */
public class TicTacToeSolver {

    private static final int BOARD_SIZE = 4;
    private static final int WIN_LENGTH = 3;
    private static final char PLAYER_X = 'x';
    private static final char PLAYER_O = 'o';
    private static final char EMPTY = '.';

    public static void main(String[] args) {
        TicTacToeSolver solver = new TicTacToeSolver();
        solver.run();
    }

    /**
     * Orchestrates the input, processing, and output of the program.
     */
    public void run() {
        Scanner scanner = new Scanner(System.in);

        char[][] board = readBoard(scanner);
        char nextPlayer = determineNextPlayer(board);

        boolean canWin = canPlayerWinInOneMove(board, nextPlayer);
        System.out.println(canWin ? "YES" : "NO");

        scanner.close();
    }

    /**
     * Reads the 4x4 grid from standard input.
     */
    private char[][] readBoard(Scanner scanner) {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i++) {
            String rowInput = scanner.next();
            for (int j = 0; j < BOARD_SIZE; j++) {
                board[i][j] = rowInput.charAt(j);
            }
        }
        return board;
    }

    /**
     * Determines which player's turn it is based on the count of symbols.
     * Assumes 'x' starts first.
     */
    private char determineNextPlayer(char[][] board) {
        int countX = 0;
        int countO = 0;

        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                if (board[i][j] == PLAYER_X) {
                    countX++;
                } else if (board[i][j] == PLAYER_O) {
                    countO++;
                }
            }
        }
        return (countX == countO) ? PLAYER_X : PLAYER_O;
    }

    /**
     * Iterates through all empty cells to see if placing the next player's 
     * symbol results in a win.
     */
    private boolean canPlayerWinInOneMove(char[][] board, char player) {
        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                if (board[i][j] == EMPTY) {
                    // Try move
                    board[i][j] = player;

                    if (hasWinningLine(board, player)) {
                        board[i][j] = EMPTY; // Backtrack
                        return true;
                    }

                    // Backtrack
                    board[i][j] = EMPTY;
                }
            }
        }
        return false;
    }

    /**
     * Checks if the given player has any line of length WIN_LENGTH.
     */
    private boolean hasWinningLine(char[][] board, char player) {
        // Direction vectors: Horizontal, Vertical, Diagonal Down-Right, Diagonal Down-Left
        int[][] directions = {
            {0, 1},  
            {1, 0},  
            {1, 1},  
            {1, -1}  
        };

        for (int r = 0; r < BOARD_SIZE; r++) {
            for (int c = 0; c < BOARD_SIZE; c++) {
                // Optimization: only check lines starting from the player's symbol
                if (board[r][c] != player) {
                    continue;
                }

                for (int[] dir : directions) {
                    if (checkDirection(board, r, c, dir[0], dir[1], player)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a continuous line of the specified player exists in a given direction.
     */
    private boolean checkDirection(char[][] board, int row, int col, int dRow, int dCol, char player) {
        for (int step = 1; step < WIN_LENGTH; step++) {
            int nextR = row + (dRow * step);
            int nextC = col + (dCol * step);

            if (!isValidPosition(nextR, nextC) || board[nextR][nextC] != player) {
                return false;
            }
        }
        return true;
    }

    private boolean isValidPosition(int r, int c) {
        return r >= 0 && r < BOARD_SIZE && c >= 0 && c < BOARD_SIZE;
    }
}

