/**
 * A solver for a Tic-Tac-Toe style puzzle on a 4x4 grid.
 * The goal is to determine if placing exactly one 'x' in an empty spot ('.')
 * results in at least three 'x's in a row (horizontally, vertically, or diagonally).
 */
public class Main {

    public static void main(String[] args) {
        try (Scanner in = new Scanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            TicTacToeSolver solver = new TicTacToeSolver();
            solver.solve(in, out);
            out.flush();
        }
    }

    /**
     * Handles the game logic and rules.
     */
    static class TicTacToeSolver {
        private static final int BOARD_SIZE = 4;
        private static final int WIN_CONDITION_LENGTH = 3;

        // Directions represented as row and column offsets: 
        // {row_offset, col_offset}
        private static final int[][] DIRECTIONS = {
            {0, 1},  // Horizontal
            {1, 0},  // Vertical
            {1, 1},  // Diagonal Down-Right
            {1, -1}  // Diagonal Down-Left
        };

        /**
         * Reads the board and determines if it can be won by adding one 'x'.
         */
        public void solve(Scanner in, PrintWriter out) {
            char[][] board = readBoard(in);

            if (canWinByAddingOne(board)) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        }

        private char[][] readBoard(Scanner in) {
            char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
            for (int i = 0; i < BOARD_SIZE; i++) {
                String line = in.next();
                board[i] = line.toCharArray();
            }
            return board;
        }

        /**
         * Iterates through all empty cells, simulates placing an 'x', 
         * and checks if that creates a winning condition.
         */
        private boolean canWinByAddingOne(char[][] board) {
            for (int r = 0; r < BOARD_SIZE; r++) {
                for (int c = 0; c < BOARD_SIZE; c++) {
                    if (board[r][c] == '.') {
                        // Simulate move
                        board[r][c] = 'x';

                        if (isWinning(board)) {
                            // Backtrack (optional here since we return, but good practice)
                            board[r][c] = '.';
                            return true;
                        }

                        // Backtrack
                        board[r][c] = '.';
                    }
                }
            }
            return false;
        }

        /**
         * Checks if there is any sequence of 'x's of the required length in any direction.
         */
        private boolean isWinning(char[][] board) {
            for (int r = 0; r < BOARD_SIZE; r++) {
                for (int c = 0; c < BOARD_SIZE; c++) {
                    // Optimization: only start checking if current cell is 'x'
                    if (board[r][c] == 'x') {
                        if (checkAllDirections(board, r, c)) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        /**
         * Checks all possible winning directions from a specific starting cell.
         */
        private boolean checkAllDirections(char[][] board, int row, int col) {
            for (int[] direction : DIRECTIONS) {
                if (isValidSequence(board, row, col, direction[0], direction[1])) {
                    return true;
                }
            }
            return false;
        }

        /**
         * Checks if a sequence of 'x's exists in a specific direction.
         */
        private boolean isValidSequence(char[][] board, int startR, int startC, int dr, int dc) {
            for (int i = 0; i < WIN_CONDITION_LENGTH; i++) {
                int currR = startR + (i * dr);
                int currC = startC + (i * dc);

                if (!isWithinBounds(currR, currC) || board[currR][currC] != 'x') {
                    return false;
                }
            }
            return true;
        }

        private boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < BOARD_SIZE && c >= 0 && c < BOARD_SIZE;
        }
    }
}

import java.io.PrintWriter;
import java.util.Scanner;

/**
 * Analyzes a 4x4 game board to determine if a specific winning pattern exists.
 * A winning pattern is defined as any three consecutive cells (horizontal, vertical, 
 * or diagonal) containing exactly two 'x' characters and one '.' character.
 */
public class TicTacToePatternMatcher {

    private static final int GRID_SIZE = 4;
    private static final int SEQUENCE_LENGTH = 3;
    private static final char PLAYER_CHAR = 'x';
    private static final char EMPTY_CHAR = '.';

    public static void main(String[] args) {
        // Use try-with-resources to ensure automatic closing of IO streams
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter writer = new PrintWriter(System.out)) {

            char[][] grid = readGrid(scanner);

            if (hasWinningSequence(grid)) {
                writer.println("YES");
            } else {
                writer.println("NO");
            }
        } catch (Exception e) {
            // In a production environment, use a proper logging framework.
            System.err.println("An error occurred: " + e.getMessage());
        }
    }

    /**
     * Reads the 4x4 grid from the user input.
     * 
     * @param scanner The scanner instance reading from System.in
     * @return A 2D character array representing the grid
     */
    private static char[][] readGrid(Scanner scanner) {
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            if (scanner.hasNextLine()) {
                grid[i] = scanner.nextLine().toCharArray();
            }
        }
        return grid;
    }

    /**
     * Scans the grid for any sequence of 3 cells that matches the winning pattern.
     * 
     * @param grid The 2D character array representing the board
     * @return true if a winning sequence is found, false otherwise
     */
    private static boolean hasWinningSequence(char[][] grid) {
        // Directions represent {row_delta, column_delta}
        // 0: Horizontal, 1: Vertical, 2: Diagonal Down-Right, 3: Diagonal Down-Left
        int[][] directions = {
            {0, 1},  
            {1, 0},  
            {1, 1},  
            {1, -1}  
        };

        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                for (int[] dir : directions) {
                    if (isSequenceWithinBounds(r, c, dir[0], dir[1])) {
                        if (isTargetPattern(grid, r, c, dir[0], dir[1])) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a sequence of a specific length starting at (r, c) 
     * in direction (dr, dc) stays within the grid boundaries.
     */
    private static boolean isSequenceWithinBounds(int r, int c, int dr, int dc) {
        int endR = r + (SEQUENCE_LENGTH - 1) * dr;
        int endC = c + (SEQUENCE_LENGTH - 1) * dc;

        return endR >= 0 && endR < GRID_SIZE && 
               endC >= 0 && endC < GRID_SIZE;
    }

    /**
     * Evaluates if the sequence of cells starting at (r, c) in direction (dr, dc)
     * contains exactly two PLAYER_CHARs and one EMPTY_CHAR.
     */
    private static boolean isTargetPattern(char[][] grid, int r, int c, int dr, int dc) {
        int playerCounter = 0;
        int emptyCounter = 0;

        for (int i = 0; i < SEQUENCE_LENGTH; i++) {
            char cell = grid[r + i * dr][c + i * dc];
            if (cell == PLAYER_CHAR) {
                playerCounter++;
            } else if (cell == EMPTY_CHAR) {
                emptyCounter++;
            }
        }

        // The pattern is a win if it has exactly 2 'x' and 1 '.'
        return playerCounter == 2 && emptyCounter == 1;
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Main entry point for the program.
 * Orchestrates the input, processing, and output.
 */
public class Main {
    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            GameSolver solver = new GameSolver(reader);
            solver.solve(writer);
        } finally {
            writer.close();
        }
    }
}

/**
 * Handles the logic of reading the board and detecting the winning pattern.
 */
class GameSolver {
    private static final int GRID_SIZE = 4;
    private final FastReader reader;

    // Cell Type Constants
    private static final int TYPE_X = 1;
    private static final int TYPE_O = 2;
    private static final int TYPE_OTHER = 3;

    // Directions for triplet checking: {row_delta, col_delta}
    // Covers: Horizontal, Vertical, Diagonal Down-Right, Diagonal Down-Left
    private static final int[][] DIRECTIONS = {
        {0, 1},  // Horizontal
        {1, 0},  // Vertical
        {1, 1},  // Diagonal Down-Right
        {1, -1}  // Diagonal Down-Left
    };

    public GameSolver(FastReader reader) {
        this.reader = reader;
    }

    public void solve(PrintWriter out) {
        int[][] board = readBoard();

        if (hasWinningPattern(board)) {
            out.println("YES");
        } else {
            out.println("NO");
        }
    }

    /**
     * Reads the 4x4 grid from input.
     */
    private int[][] readBoard() {
        int[][] board = new int[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            String line = reader.next();
            for (int j = 0; j < GRID_SIZE; j++) {
                char c = line.charAt(j);
                if (c == 'x') {
                    board[i][j] = TYPE_X;
                } else if (c == 'o') {
                    board[i][j] = TYPE_O;
                } else {
                    board[i][j] = TYPE_OTHER;
                }
            }
        }
        return board;
    }

    /**
     * Scans the board for any sequence of 3 cells containing 
     * exactly two 'X's and one 'OTHER'.
     */
    private boolean hasWinningPattern(int[][] board) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                for (int[] dir : DIRECTIONS) {
                    if (checkTriplet(board, r, c, dir[0], dir[1])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a triplet starting at (r, c) in direction (dr, dc) 
     * meets the winning criteria.
     */
    private boolean checkTriplet(int[][] board, int r, int c, int dr, int dc) {
        int r2 = r + dr;
        int c2 = c + dc;
        int r3 = r + 2 * dr;
        int c3 = c + 2 * dc;

        // Ensure all three cells are within grid boundaries
        if (isWithinBounds(r3, c3)) {
            int v1 = board[r][c];
            int v2 = board[r2][c2];
            int v3 = board[r3][c3];

            return isWinningCombination(v1, v2, v3);
        }
        return false;
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
    }

    /**
     * Criteria: Triplet must contain exactly two TYPE_X and one TYPE_OTHER.
     */
    private boolean isWinningCombination(int v1, int v2, int v3) {
        int countX = 0;
        int countOther = 0;

        int[] values = {v1, v2, v3};
        for (int val : values) {
            if (val == TYPE_X) {
                countX++;
            } else if (val == TYPE_OTHER) {
                countOther++;
            }
        }

        return countX == 2 && countOther == 1;
    }
}

/**
 * Efficient input reader for fast I/O operations.
 */
class FastReader {
    private BufferedReader reader;
    private StringTokenizer tokenizer;

    public FastReader(InputStream inputStream) {
        reader = new BufferedReader(new InputStreamReader(inputStream));
    }

    public String next() {
        while (tokenizer == null || !tokenizer.hasMoreElements()) {
            try {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                throw new RuntimeException("Error reading input", e);
            }
        }
        return tokenizer.nextToken();
    }
}

import java.util.Scanner;

/**
 * A utility to determine if a specific pattern can be completed in a 4x4 grid.
 * Specifically, it checks if placing an 'x' in an empty '.' cell 
 * results in a sequence of at least 3 'x' characters in any direction.
 */
public class GridPatternChecker {

    private static final int GRID_SIZE = 4;
    private static final int TARGET_SEQUENCE_LENGTH = 3;
    private static final char EMPTY_CELL = '.';
    private static final char FILLED_CELL = 'x';

    // Direction vectors for: Horizontal, Vertical, Diagonal, and Anti-Diagonal
    private static final int[][] DIRECTIONS = {
            {0, 1},  // Horizontal
            {1, 0},  // Vertical
            {1, 1},  // Diagonal (Top-left to bottom-right)
            {1, -1}  // Anti-Diagonal (Top-right to bottom-left)
    };

    private final char[][] grid = new char[GRID_SIZE][GRID_SIZE];

    public static void main(String[] args) {
        GridPatternChecker checker = new GridPatternChecker();
        checker.run();
    }

    /**
     * Orchestrates the reading of input, processing, and output.
     */
    public void run() {
        Scanner scanner = new Scanner(System.in);

        if (readGrid(scanner)) {
            if (canCompletePattern()) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }

        scanner.close();
    }

    /**
     * Reads the 4x4 grid from the scanner.
     * 
     * @param scanner The scanner instance to read from.
     * @return true if the grid was read successfully.
     */
    private boolean readGrid(Scanner scanner) {
        try {
            for (int i = 0; i < GRID_SIZE; i++) {
                String line = scanner.next();
                if (line.length() != GRID_SIZE) {
                    return false;
                }
                grid[i] = line.toCharArray();
            }
            return true;
        } catch (Exception e) {
            return false;
        }
    }

    /**
     * Iterates through the grid to find an empty cell that can complete a sequence.
     * 
     * @return true if a sequence of 3 'x's can be formed.
     */
    private boolean canCompletePattern() {
        for (int row = 0; row < GRID_SIZE; row++) {
            for (int col = 0; col < GRID_SIZE; col++) {
                if (grid[row][col] == EMPTY_CELL) {
                    if (canFormSequenceAt(row, col)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if placing a cell at (row, col) creates a sequence of 
     * the required length in any of the four possible directions.
     */
    private boolean canFormSequenceAt(int row, int col) {
        for (int[] direction : DIRECTIONS) {
            int dr = direction[0];
            int dc = direction[1];

            // Start with 1 to represent the current cell being filled
            int count = 1;
            count += countConsecutive(row, col, dr, dc); // Count in positive direction
            count += countConsecutive(row, col, -dr, -dc); // Count in negative direction

            if (count >= TARGET_SEQUENCE_LENGTH) {
                return true;
            }
        }
        return false;
    }

    /**
     * Counts how many consecutive FILLED_CELLs exist in a specific direction.
     * 
     * @param row Starting row index.
     * @param col Starting column index.
     * @param dr Directional row step.
     * @param dc Directional column step.
     * @return The number of consecutive filled cells found.
     */
    private int countConsecutive(int row, int col, int dr, int dc) {
        int count = 0;
        int currentRow = row + dr;
        int currentCol = col + dc;

        while (isWithinBounds(currentRow, currentCol) && grid[currentRow][currentCol] == FILLED_CELL) {
            count++;
            currentRow += dr;
            currentCol += dc;
        }
        return count;
    }

    /**
     * Validates if the given coordinates are within the grid boundaries.
     */
    private boolean isWithinBounds(int row, int col) {
        return row >= 0 && row < GRID_SIZE && col >= 0 && col < GRID_SIZE;
    }
}

import java.util.Scanner;

/**
 * A solver that determines if a 4x4 grid can achieve three-in-a-row 
 * by placing a single 'x' in an empty '.' cell.
 */
public class TicTacToeSolver {

    private static final int GRID_SIZE = 4;
    private static final char EMPTY_CELL = '.';
    private static final char MARK = 'x';

    public static void main(String[] args) {
        TicTacToeSolver solver = new TicTacToeSolver();
        solver.execute();
    }

    /**
     * Orchestrates the program flow: reading input, processing logic, and printing results.
     */
    public void execute() {
        char[][] grid = readGridFromConsole();

        if (canWinWithOneMove(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Reads the 4x4 grid from standard input.
     * 
     * @return A 2D array representing the grid.
     */
    private char[][] readGridFromConsole() {
        Scanner scanner = new Scanner(System.in);
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];

        for (int i = 0; i < GRID_SIZE; i++) {
            if (scanner.hasNext()) {
                String rowString = scanner.next();
                for (int j = 0; j < GRID_SIZE; j++) {
                    grid[i][j] = rowString.charAt(j);
                }
            }
        }
        return grid;
    }

    /**
     * Iterates through every empty cell to see if placing a mark there results in a win.
     * 
     * @param grid The current state of the grid.
     * @return true if any valid move creates a three-in-a-row.
     */
    private boolean canWinWithOneMove(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                if (grid[r][c] == EMPTY_CELL) {
                    if (simulateMoveAndCheckWin(grid, r, c)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Temporarily places a mark in a cell and checks if the grid now contains a win.
     * 
     * @param grid The grid to modify.
     * @param row The row index.
     * @param col The column index.
     * @return true if the move resulted in a win.
     */
    private boolean simulateMoveAndCheckWin(char[][] grid, int row, int col) {
        char originalValue = grid[row][col];
        grid[row][col] = MARK;

        boolean isWin = hasThreeInARow(grid);

        // Backtrack to restore grid state
        grid[row][col] = originalValue;
        return isWin;
    }

    /**
     * Scans the entire grid to check if any three-in-a-row sequence exists.
     * 
     * @param grid The grid to check.
     * @return true if a sequence is found.
     */
    private boolean hasThreeInARow(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                if (isMidpointOfWinningLine(grid, r, c)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Checks if the cell at (r, c) acts as the center of a horizontal, 
     * vertical, or diagonal line of three 'x' marks.
     */
    private boolean isMidpointOfWinningLine(char[][] grid, int r, int c) {
        if (grid[r][c] != MARK) {
            return false;
        }

        // Check all 4 directions: Vertical, Horizontal, Diagonal \, Diagonal /
        return isPartOfLine(grid, r, c, -1, 0, 1, 0) || 
               isPartOfLine(grid, r, c, 0, -1, 0, 1) || 
               isPartOfLine(grid, r, c, -1, -1, 1, 1) || 
               isPartOfLine(grid, r, c, -1, 1, 1, -1);
    }

    /**
     * Validates if a line of three exists passing through (r, c) using given offsets.
     */
    private boolean isPartOfLine(char[][] grid, int r, int c, int dr1, int dc1, int dr2, int dc2) {
        int r1 = r + dr1, c1 = c + dc1;
        int r2 = r + dr2, c2 = c + dc2;

        return isWithinBounds(r1, c1) && isWithinBounds(r2, c2) &&
               grid[r1][c1] == MARK && grid[r2][c2] == MARK;
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
    }
}

import java.util.Scanner;

/**
 * A solution to determine if a 4x4 grid contains a specific winning pattern:
 * exactly two 'x' characters and one '.' character in any line of length 3
 * (horizontal, vertical, or diagonal).
 */
public class PatternMatcher {

    private static final int GRID_SIZE = 4;
    private static final int PATTERN_LENGTH = 3;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] grid = readGrid(scanner);

        if (hasWinningPattern(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Reads a 4x4 grid from the input.
     */
    private static char[][] readGrid(Scanner scanner) {
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            if (scanner.hasNext()) {
                grid[i] = scanner.next().toCharArray();
            }
        }
        return grid;
    }

    /**
     * Iterates through the grid to find any line of length 3 that matches the pattern.
     */
    private static boolean hasWinningPattern(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {

                // Check Horizontal pattern starting at (r, c)
                if (c + PATTERN_LENGTH <= GRID_SIZE) {
                    if (isValidPattern(grid[r][c], grid[r][c + 1], grid[r][c + 2])) {
                        return true;
                    }
                }

                // Check Vertical pattern starting at (r, c)
                if (r + PATTERN_LENGTH <= GRID_SIZE) {
                    if (isValidPattern(grid[r][c], grid[r + 1][c], grid[r + 2][c])) {
                        return true;
                    }
                }

                // Check Diagonal Down-Right pattern starting at (r, c)
                if (r + PATTERN_LENGTH <= GRID_SIZE && c + PATTERN_LENGTH <= GRID_SIZE) {
                    if (isValidPattern(grid[r][c], grid[r + 1][c + 1], grid[r + 2][c + 2])) {
                        return true;
                    }
                }

                // Check Diagonal Down-Left pattern starting at (r, c)
                if (r + PATTERN_LENGTH <= GRID_SIZE && c - (PATTERN_LENGTH - 1) >= 0) {
                    if (isValidPattern(grid[r][c], grid[r + 1][c - 1], grid[r + 2][c - 2])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if the three provided characters consist of exactly two 'x's and one '.'.
     */
    private static boolean isValidPattern(char c1, char c2, char c3) {
        int xCount = 0;
        int dotCount = 0;
        char[] line = {c1, c2, c3};

        for (char cell : line) {
            if (cell == 'x') {
                xCount++;
            } else if (cell == '.') {
                dotCount++;
            }
        }

        return xCount == 2 && dotCount == 1;
    }
}

import java.util.Scanner;

/**
 * PatternMatcher identifies if a 4x4 grid contains a sequence 
 * of 3 consecutive cells consisting of exactly two 'x's and one '.'.
 */
public class PatternMatcher {

    private static final int GRID_SIZE = 4;
    private static final int SEQUENCE_LENGTH = 3;
    private static final int TARGET_X_COUNT = 2;
    private static final int TARGET_DOT_COUNT = 1;

    // Direction vectors for: Horizontal, Vertical, Diagonal (down-right), Anti-Diagonal (down-left)
    private static final int[][] DIRECTIONS = {
        {0, 1},  
        {1, 0},  
        {1, 1},  
        {1, -1}  
    };

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] grid = readGrid(scanner, GRID_SIZE);

        boolean isPatternFound = hasWinningSequence(grid);

        System.out.println(isPatternFound ? "YES" : "NO");
        scanner.close();
    }

    /**
     * Reads the grid from the standard input.
     */
    private static char[][] readGrid(Scanner scanner, int size) {
        char[][] grid = new char[size][size];
        for (int i = 0; i < size; i++) {
            if (scanner.hasNext()) {
                grid[i] = scanner.next().toCharArray();
            }
        }
        return grid;
    }

    /**
     * Iterates through the grid to find any valid sequence in any direction.
     */
    private static boolean hasWinningSequence(char[][] grid) {
        for (int row = 0; row < GRID_SIZE; row++) {
            for (int col = 0; col < GRID_SIZE; col++) {
                for (int[] direction : DIRECTIONS) {
                    if (isWithinBounds(grid, row, col, direction)) {
                        if (isTargetSequence(grid, row, col, direction)) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a sequence of SEQUENCE_LENGTH can be formed starting from (row, col) 
     * in the given direction without going out of bounds.
     */
    private static boolean isWithinBounds(char[][] grid, int row, int col, int[] direction) {
        int dr = direction[0];
        int dc = direction[1];

        int endRow = row + (SEQUENCE_LENGTH - 1) * dr;
        int endCol = col + (SEQUENCE_LENGTH - 1) * dc;

        return endRow >= 0 && endRow < GRID_SIZE && 
               endCol >= 0 && endCol < GRID_SIZE;
    }

    /**
     * Counts 'x' and '.' in a specific sequence and checks if they meet the target counts.
     */
    private static boolean isTargetSequence(char[][] grid, int row, int col, int[] direction) {
        int xCount = 0;
        int dotCount = 0;
        int dr = direction[0];
        int dc = direction[1];

        for (int k = 0; k < SEQUENCE_LENGTH; k++) {
            char currentChar = grid[row + k * dr][col + k * dc];
            if (currentChar == 'x') {
                xCount++;
            } else if (currentChar == '.') {
                dotCount++;
            }
        }

        return xCount == TARGET_X_COUNT && dotCount == TARGET_DOT_COUNT;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.Reader;
import java.util.StringTokenizer;

/**
 * A utility to detect if a 4x4 grid contains a specific winning pattern:
 * A sequence of 3 cells (horizontal, vertical, or diagonal) consisting 
 * of exactly two 'x' characters and one '.' character.
 */
public class TicTacToePatternMatcher {

    private static final int GRID_SIZE = 4;
    private static final int SEQUENCE_LENGTH = 3;
    private static final char TARGET_X = 'x';
    private static final char TARGET_DOT = '.';

    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        char[][] grid = new char[GRID_SIZE][];

        try {
            for (int i = 0; i < GRID_SIZE; i++) {
                grid[i] = sc.next().toCharArray();
            }
        } catch (Exception e) {
            System.err.println("Error reading input: " + e.getMessage());
            return;
        }

        if (hasWinningPattern(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Iterates through the grid to find if any valid sequence matches the criteria.
     * 
     * @param grid The 4x4 character grid.
     * @return true if a winning sequence is found, false otherwise.
     */
    private static boolean hasWinningPattern(char[][] grid) {
        // Directions: {row_delta, col_delta}
        // Horizontal, Vertical, Diagonal Down-Right, Diagonal Down-Left
        int[][] directions = {
            {0, 1}, 
            {1, 0}, 
            {1, 1}, 
            {1, -1}
        };

        for (int row = 0; row < GRID_SIZE; row++) {
            for (int col = 0; col < GRID_SIZE; col++) {
                for (int[] dir : directions) {
                    if (isValidSequence(grid, row, col, dir[0], dir[1])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a sequence of length SEQUENCE_LENGTH starting from (startRow, startCol)
     * in a specific direction meets the win criteria.
     */
    private static boolean isValidSequence(char[][] grid, int startRow, int startCol, int dr, int dc) {
        int xCount = 0;
        int dotCount = 0;

        for (int i = 0; i < SEQUENCE_LENGTH; i++) {
            int currentRow = startRow + (i * dr);
            int currentCol = startCol + (i * dc);

            // Boundary Check
            if (isOutOfBounds(currentRow, currentCol)) {
                return false;
            }

            char cell = grid[currentRow][currentCol];
            if (cell == TARGET_X) {
                xCount++;
            } else if (cell == TARGET_DOT) {
                dotCount++;
            }
        }

        return xCount == 2 && dotCount == 1;
    }

    private static boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= GRID_SIZE || c < 0 || c >= GRID_SIZE;
    }

    /**
     * FastScanner utility for efficient input reading.
     */
    public static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            this(new InputStreamReader(System.in));
        }

        public FastScanner(Reader in) {
            br = new BufferedReader(in);
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.util.Scanner;

/**
 * A solver for a grid-based game. The goal is to determine if placing 
 * a single 'x' in an empty '.' cell can create a line of at least 
 * 3 'x's in any direction (horizontal, vertical, or diagonal).
 */
public class GridGameSolver {

    private static final int GRID_SIZE = 4;
    private static final char EMPTY = '.';
    private static final char FILLED = 'x';
    private static final int TARGET_SEQUENCE_LENGTH = 3;

    private final char[][] grid;

    public GridGameSolver(char[][] grid) {
        this.grid = grid;
    }

    /**
     * Iterates through the grid to find if any empty cell can be filled to win.
     * 
     * @return true if a winning move is possible, false otherwise.
     */
    public boolean canWinWithOneMove() {
        for (int row = 0; row < GRID_SIZE; row++) {
            for (int col = 0; col < GRID_SIZE; col++) {
                if (grid[row][col] == EMPTY) {
                    if (isWinningMove(row, col)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Temporarily places a 'x' in the specified cell and checks if it 
     * completes a winning sequence.
     */
    private boolean isWinningMove(int row, int col) {
        // Place the piece
        grid[row][col] = FILLED;

        // Check all axes passing through this cell
        boolean winFound = checkAllAxes(row, col);

        // Backtrack: restore the cell to empty for subsequent checks
        grid[row][col] = EMPTY;

        return winFound;
    }

    /**
     * Checks the four axes (horizontal, vertical, and two diagonals) 
     * passing through the given coordinates.
     */
    private boolean checkAllAxes(int row, int col) {
        // Direction vectors for: Horizontal, Vertical, Main Diagonal (\), Anti-Diagonal (/)
        int[][] directions = {
            {0, 1},  
            {1, 0},  
            {1, 1},  
            {1, -1}  
        };

        for (int[] dir : directions) {
            int dr = dir[0];
            int dc = dir[1];

            // Total length = current cell (1) + consecutive cells in positive direction + 
            //                consecutive cells in negative direction.
            int totalSequence = 1 
                    + countConsecutive(row, col, dr, dc) 
                    + countConsecutive(row, col, -dr, -dc);

            if (totalSequence >= TARGET_SEQUENCE_LENGTH) {
                return true;
            }
        }
        return false;
    }

    /**
     * Counts how many consecutive FILLED cells exist starting from (row, col) 
     * moving in the direction (dr, dc), excluding the starting cell itself.
     */
    private int countConsecutive(int row, int col, int dr, int dc) {
        int count = 0;
        int currentRow = row + dr;
        int currentCol = col + dc;

        while (isWithinBounds(currentRow, currentCol) && grid[currentRow][currentCol] == FILLED) {
            count++;
            currentRow += dr;
            currentCol += dc;
        }
        return count;
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
    }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            char[][] inputGrid = new char[GRID_SIZE][GRID_SIZE];

            for (int i = 0; i < GRID_SIZE; i++) {
                if (scanner.hasNext()) {
                    inputGrid[i] = scanner.next().toCharArray();
                }
            }

            GridGameSolver solver = new GridGameSolver(inputGrid);

            if (solver.canWinWithOneMove()) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        } catch (Exception e) {
            // Silently handle or log errors as per application requirements
        }
    }
}

