/**
 * Represents the 4x4 game board and encapsulates grid-related operations.
 */
class Board {
    public static final int GRID_SIZE = 4;
    public static final int WIN_LENGTH = 3;

    private static final int CELL_X = 1;
    private static final int CELL_O = 2;
    private static final int CELL_EMPTY = 0;

    private final int[][] grid = new int[GRID_SIZE][GRID_SIZE];

    /**
     * Populates the grid based on character input.
     * 'x' -> X, 'o' -> O, anything else -> EMPTY.
     */
    public void setCell(int row, int col, char val) {
        if (val == 'x') {
            grid[row][col] = CELL_X;
        } else if (val == 'o') {
            grid[row][col] = CELL_O;
        } else {
            grid[row][col] = CELL_EMPTY;
        }
    }

    public int getCellValue(int row, int col) {
        return grid[row][col];
    }

    public int getXCount(int[] segment) {
        int count = 0;
        for (int val : segment) {
            if (val == CELL_X) count++;
        }
        return count;
    }

    public int getEmptyCount(int[] segment) {
        int count = 0;
        for (int val : segment) {
            if (val == CELL_EMPTY) count++;
        }
        return count;
    }

    /**
     * Returns all possible continuous segments of the specified WIN_LENGTH
     * in rows, columns, and both diagonal directions.
     */
    public List<int[]> getAllSegments() {
        List<int[]> segments = new ArrayList<>();

        // Horizontal segments
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c <= GRID_SIZE - WIN_LENGTH; c++) {
                segments.add(getSegment(r, c, 0, 1));
            }
        }

        // Vertical segments
        for (int c = 0; c < GRID_SIZE; c++) {
            for (int r = 0; r <= GRID_SIZE - WIN_LENGTH; r++) {
                segments.add(getSegment(r, c, 1, 0));
            }
        }

        // Diagonal (Down-Right) segments
        for (int r = 0; r <= GRID_SIZE - WIN_LENGTH; r++) {
            for (int c = 0; c <= GRID_SIZE - WIN_LENGTH; c++) {
                segments.add(getSegment(r, c, 1, 1));
            }
        }

        // Diagonal (Down-Left) segments
        for (int r = 0; r <= GRID_SIZE - WIN_LENGTH; r++) {
            for (int c = WIN_LENGTH - 1; c < GRID_SIZE; c++) {
                segments.add(getSegment(r, c, 1, -1));
            }
        }

        return segments;
    }

    private int[] getSegment(int startR, int startC, int deltaR, int deltaC) {
        int[] segment = new int[WIN_LENGTH];
        for (int i = 0; i < WIN_LENGTH; i++) {
            segment[i] = grid[startR + (i * deltaR)][startC + (i * deltaC)];
        }
        return segment;
    }
}

/**
 * Handles the logic for determining if the winning condition is met.
 */
class GridSolver {
    private final FastReader reader;

    public GridSolver(FastReader reader) {
        this.reader = reader;
    }

    public void solve(PrintWriter out) {
        Board board = new Board();

        // Input reading
        for (int i = 0; i < Board.GRID_SIZE; i++) {
            for (int j = 0; j < Board.GRID_SIZE; j++) {
                board.setCell(i, j, reader.readCharacter());
            }
        }

        // Logical evaluation
        if (isWinConditionMet(board)) {
            out.println("YES");
        } else {
            out.println("NO");
        }
    }

    /**
     * A win is defined as any segment of length 3 containing 
     * exactly two 'x' and one empty cell.
     */
    private boolean isWinConditionMet(Board board) {
        for (int[] segment : board.getAllSegments()) {
            if (board.getXCount(segment) == 2 && board.getEmptyCount(segment) == 1) {
                return true;
            }
        }
        return false;
    }
}

/**
 * A utility class for fast input reading.
 */
class FastReader {
    private final InputStream stream;
    private final byte[] buffer = new byte[1024];
    private int pointer = 0;
    private int bytesRead = 0;

    public FastReader(InputStream stream) {
        this.stream = stream;
    }

    private int readByte() {
        if (pointer >= bytesRead) {
            pointer = 0;
            try {
                bytesRead = stream.read(buffer);
            } catch (IOException e) {
                return -1;
            }
            if (bytesRead <= 0) return -1;
        }
        return buffer[pointer++] & 0xFF;
    }

    public char readCharacter() {
        int c = readByte();
        while (c != -1 && isWhitespace(c)) {
            c = readByte();
        }
        return (char) c;
    }

    private boolean isWhitespace(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t';
    }
}

import java.util.Scanner;

/**
 * A solver for a "Connect Three" style game on a 4x4 grid.
 * The goal is to determine if placing a single 'x' in an empty '.' cell
 * can create a sequence of three 'x's in a row (horizontally, vertically, or diagonally).
 */
public class ConnectThreeSolver {

    private static final int GRID_SIZE = 4;
    private static final int WIN_SEQUENCE_LENGTH = 3;
    private static final char EMPTY_CELL = '.';
    private static final char PLAYER_PIECE = 'x';

    // Direction vectors for: Horizontal, Vertical, Diagonal Down-Right, Diagonal Down-Left
    private static final int[][] DIRECTIONS = {
        {0, 1},  // Horizontal
        {1, 0},  // Vertical
        {1, 1},  // Diagonal Down-Right
        {1, -1}  // Diagonal Down-Left
    };

    public static void main(String[] args) {
        ConnectThreeSolver solver = new ConnectThreeSolver();
        solver.run();
    }

    /**
     * Orchestrates the input, processing, and output of the program.
     */
    public void run() {
        try (Scanner scanner = new Scanner(System.in)) {
            char[][] grid = readGrid(scanner);

            if (canWinInOneMove(grid)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        } catch (Exception e) {
            System.err.println("Error processing input: " + e.getMessage());
        }
    }

    /**
     * Reads the 4x4 grid from standard input.
     */
    private char[][] readGrid(Scanner scanner) {
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            String rowString = scanner.next();
            for (int j = 0; j < GRID_SIZE; j++) {
                grid[i][j] = rowString.charAt(j);
            }
        }
        return grid;
    }

    /**
     * Iterates through every empty cell and simulates placing a piece.
     * @return true if any placement results in a win.
     */
    private boolean canWinInOneMove(char[][] grid) {
        for (int i = 0; i < GRID_SIZE; i++) {
            for (int j = 0; j < GRID_SIZE; j++) {
                if (grid[i][j] == EMPTY_CELL) {
                    // Simulate move
                    grid[i][j] = PLAYER_PIECE;

                    if (hasWinningSequence(grid)) {
                        // Backtrack before returning true
                        grid[i][j] = EMPTY_CELL;
                        return true;
                    }

                    // Backtrack
                    grid[i][j] = EMPTY_CELL;
                }
            }
        }
        return false;
    }

    /**
     * Checks if the current grid state contains the required winning sequence.
     */
    private boolean hasWinningSequence(char[][] grid) {
        for (int i = 0; i < GRID_SIZE; i++) {
            for (int j = 0; j < GRID_SIZE; j++) {
                if (grid[i][j] == PLAYER_PIECE) {
                    if (checkAllDirections(grid, i, j)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a starting piece at (row, col) begins a winning sequence 
     * in any of the allowed directions.
     */
    private boolean checkAllDirections(char[][] grid, int row, int col) {
        for (int[] dir : DIRECTIONS) {
            int dr = dir[0];
            int dc = dir[1];

            if (isSequenceFound(grid, row, col, dr, dc)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Validates if a sequence of the required length exists starting from (r, c)
     * moving in direction (dr, dc).
     */
    private boolean isSequenceFound(char[][] grid, int r, int c, int dr, int dc) {
        for (int step = 1; step < WIN_SEQUENCE_LENGTH; step++) {
            int nextR = r + (dr * step);
            int nextC = c + (dc * step);

            if (!isValidPosition(nextR, nextC) || grid[nextR][nextC] != PLAYER_PIECE) {
                return false;
            }
        }
        return true;
    }

    private boolean isValidPosition(int r, int c) {
        return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
    }
}

import java.util.*;

/**
 * This program analyzes a 4x4 grid to determine if any row, column, 
 * or diagonal contains a specific pattern of 'x' and '.' characters.
 */
public class GridPatternMatcher {

    private static final int GRID_SIZE = 4;
    private static final String[] TARGET_PATTERNS = {"x.x", "xx.", ".xx"};

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];

        if (readGrid(scanner, grid)) {
            if (containsTargetPattern(grid)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }

        scanner.close();
    }

    /**
     * Reads the 4x4 grid from the scanner.
     * @return true if input was successfully read, false otherwise.
     */
    private static boolean readGrid(Scanner scanner, char[][] grid) {
        try {
            for (int i = 0; i < GRID_SIZE; i++) {
                if (!scanner.hasNext()) return false;
                String line = scanner.next();
                if (line.length() < GRID_SIZE) return false;
                grid[i] = line.toCharArray();
            }
            return true;
        } catch (Exception e) {
            return false;
        }
    }

    /**
     * Checks if any extracted line (row, column, or diagonal) contains the target patterns.
     * @param grid The 4x4 character grid.
     * @return true if a pattern is found, false otherwise.
     */
    private static boolean containsTargetPattern(char[][] grid) {
        List<String> allLines = extractAllLines(grid);

        for (String line : allLines) {
            for (String pattern : TARGET_PATTERNS) {
                if (line.contains(pattern)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Collects all possible lines of interest from the grid:
     * Rows, Columns, Main Diagonals (size 4), and Minor Diagonals (size 3).
     * @param grid The 4x4 character grid.
     * @return A list of strings representing the lines.
     */
    private static List<String> extractAllLines(char[][] grid) {
        List<String> lines = new ArrayList<>();

        // 1. Extract Rows
        for (int i = 0; i < GRID_SIZE; i++) {
            lines.add(new String(grid[i]));
        }

        // 2. Extract Columns
        for (int j = 0; j < GRID_SIZE; j++) {
            StringBuilder colBuilder = new StringBuilder();
            for (int i = 0; i < GRID_SIZE; i++) {
                colBuilder.append(grid[i][j]);
            }
            lines.add(colBuilder.toString());
        }

        // 3. Extract Main Diagonals (Length 4)
        lines.add(getDiagonal(grid, 0, 0, 1, 1, 4));  // Top-left to bottom-right
        lines.add(getDiagonal(grid, 0, 3, 1, -1, 4)); // Top-right to bottom-left

        // 4. Extract Minor Diagonals (Length 3)
        lines.add(getDiagonal(grid, 1, 0, 1, 1, 3));  // Bottom-left offset
        lines.add(getDiagonal(grid, 0, 1, 1, 1, 3));  // Top-row offset
        lines.add(getDiagonal(grid, 0, 2, 1, -1, 3)); // Top-row offset anti
        lines.add(getDiagonal(grid, 1, 3, 1, -1, 3)); // Bottom-right offset anti

        return lines;
    }

    /**
     * Helper method to extract a diagonal string based on starting position and direction.
     * @param grid The 4x4 grid.
     * @param startRow Starting row index.
     * @param startCol Starting column index.
     * @param rowStep Direction of row movement (+1 or -1).
     * @param colStep Direction of column movement (+1 or -1).
     * @param length Number of characters to extract.
     * @return A string representing the diagonal segment.
     */
    private static String getDiagonal(char[][] grid, int startRow, int startCol, 
                                     int rowStep, int colStep, int length) {
        StringBuilder sb = new StringBuilder();
        int currentRow = startRow;
        int currentCol = startCol;

        for (int i = 0; i < length; i++) {
            if (isWithinBounds(currentRow, currentCol)) {
                sb.append(grid[currentRow][currentCol]);
                currentRow += rowStep;
                currentCol += colStep;
            } else {
                break;
            }
        }
        return sb.toString();
    }

    private static boolean isWithinBounds(int row, int col) {
        return row >= 0 && row < GRID_SIZE && col >= 0 && col < GRID_SIZE;
    }
}

import java.util.Scanner;

/**
 * This program checks for a specific pattern within a 4x4 grid.
 * The pattern consists of two 'x' characters and one '.' character 
 * appearing in a straight line (horizontal, vertical, or diagonal).
 */
public class GridPatternMatcher {

    private static final int GRID_SIZE = 4;

    // Cell representations
    private static final int CELL_EMPTY = 0; // '.'
    private static final int CELL_X = 1;     // 'x'
    private static final int CELL_O = 2;     // 'o'

    // Direction vectors for 8 possible movements (N, NE, E, SE, S, SW, W, NW)
    private static final int[] DR = {0, 1, 1, 1, 0, -1, -1, -1};
    private static final int[] DC = {1, 1, 0, -1, -1, -1, 0, 1};

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        int[][] grid = parseGrid(scanner);

        if (containsTargetPattern(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Reads the 4x4 grid from standard input and converts characters to integer constants.
     */
    private static int[][] parseGrid(Scanner scanner) {
        int[][] grid = new int[GRID_SIZE][GRID_SIZE];

        for (int i = 0; i < GRID_SIZE; i++) {
            if (!scanner.hasNext()) break;
            String line = scanner.next();
            for (int j = 0; j < GRID_SIZE; j++) {
                char c = line.charAt(j);
                if (c == 'x') {
                    grid[i][j] = CELL_X;
                } else if (c == 'o') {
                    grid[i][j] = CELL_O;
                } else if (c == '.') {
                    grid[i][j] = CELL_EMPTY;
                }
            }
        }
        return grid;
    }

    /**
     * Iterates through the grid to find if any 'x' is part of the target pattern.
     */
    private static boolean containsTargetPattern(int[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                // The original logic specifically triggers the check from an 'x' cell
                if (grid[r][c] == CELL_X) {
                    if (isPatternAt(r, c, grid)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks all 8 directions from a specific cell to see if the next two 
     * cells contain exactly one 'x' and one '.'.
     */
    private static boolean isPatternAt(int row, int col, int[][] grid) {
        for (int i = 0; i < 8; i++) {
            int r1 = row + DR[i];
            int c1 = col + DC[i];
            int r2 = row + 2 * DR[i];
            int c2 = col + 2 * DC[i];

            // Ensure both subsequent cells in the direction are within grid boundaries
            if (isWithinBounds(r1, c1) && isWithinBounds(r2, c2)) {
                int val1 = grid[r1][c1];
                int val2 = grid[r2][c2];

                // The pattern sought is: [X, '.', X] or [X, X, '.']
                // This is equivalent to checking if the next two cells are {0, 1} in any order.
                if (isMatchingSequence(val1, val2)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Determines if two cells match the requirement of being one 'x' and one '.'.
     */
    private static boolean isMatchingSequence(int val1, int val2) {
        boolean pattern01 = (val1 == CELL_EMPTY && val2 == CELL_X);
        boolean pattern10 = (val1 == CELL_X && val2 == CELL_EMPTY);
        return pattern01 || pattern10;
    }

    private static boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
    }
}

import java.util.Scanner;

/**
 * A solver for a grid-based game where the goal is to determine if 
 * placing a single additional piece can create a line of three pieces.
 */
public class GridGameSolver {

    private static final int GRID_SIZE = 4;
    private static final int WINNING_SEQUENCE_LENGTH = 3;
    private static final char EMPTY_CELL = '.';
    private static final char PLAYER_CELL = 'x';

    /**
     * Directions to check for a winning sequence:
     * Horizontal, Vertical, Diagonal Down-Right, Diagonal Down-Left
     */
    private static final int[][] DIRECTIONS = {
        {0, 1},  // Horizontal
        {1, 0},  // Vertical
        {1, 1},  // Diagonal Down-Right
        {1, -1}  // Diagonal Down-Left
    };

    public static void main(String[] args) {
        GridGameSolver solver = new GridGameSolver();
        solver.run();
    }

    /**
     * Handles the execution flow: reading input, processing logic, and printing results.
     */
    public void run() {
        char[][] grid = readGrid();
        if (canAchieveWin(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Reads a GRID_SIZE x GRID_SIZE character array from standard input.
     */
    private char[][] readGrid() {
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        try (Scanner scanner = new Scanner(System.in)) {
            for (int i = 0; i < GRID_SIZE; i++) {
                if (scanner.hasNextLine()) {
                    grid[i] = scanner.nextLine().toCharArray();
                }
            }
        }
        return grid;
    }

    /**
     * Iterates through the grid to see if changing one '.' to 'x' results in a win.
     * 
     * @param grid The current state of the board.
     * @return true if a single move creates a winning line, false otherwise.
     */
    private boolean canAchieveWin(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                if (grid[r][c] == EMPTY_CELL) {
                    // Try placing a piece
                    grid[r][c] = PLAYER_CELL;

                    if (hasWinningLine(grid)) {
                        return true;
                    }

                    // Backtrack (undo move)
                    grid[r][c] = EMPTY_CELL;
                }
            }
        }
        return false;
    }

    /**
     * Checks if the current grid contains any sequence of 3 player pieces in a row, column, or diagonal.
     * 
     * @param grid The current state of the board.
     * @return true if a sequence of WINNING_SEQUENCE_LENGTH is found.
     */
    private boolean hasWinningLine(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                if (grid[r][c] == PLAYER_CELL) {
                    if (checkAllDirections(grid, r, c)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks all 4 possible directions from a starting cell for a winning sequence.
     */
    private boolean checkAllDirections(char[][] grid, int row, int col) {
        for (int[] direction : DIRECTIONS) {
            int dRow = direction[0];
            int dCol = direction[1];

            if (isSequenceAt(grid, row, col, dRow, dCol)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Checks if a sequence of PLAYER_CELL exists starting from (row, col) in a specific direction.
     */
    private boolean isSequenceAt(char[][] grid, int row, int col, int dRow, int dCol) {
        for (int step = 1; step < WINNING_SEQUENCE_LENGTH; step++) {
            int nextR = row + (dRow * step);
            int nextC = col + (dCol * step);

            if (!isValidCoordinate(nextR, nextC) || grid[nextR][nextC] != PLAYER_CELL) {
                return false;
            }
        }
        return true;
    }

    private boolean isValidCoordinate(int r, int c) {
        return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
    }
}

