/**
 * A program that determines if a 4x4 grid can contain a sequence of 3 'x' characters
 * by placing exactly one 'x' in an empty '.' cell.
 */
public class Main {

    private static final int GRID_SIZE = 4;
    private static final int SEQUENCE_LENGTH = 3;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        char[][] grid = readGrid(scanner);

        if (canAchieveSequenceWithOneMove(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Reads the 4x4 grid from the input.
     */
    private static char[][] readGrid(Scanner scanner) {
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            if (scanner.hasNext()) {
                grid[i] = scanner.next().toCharArray();
            }
        }
        return grid;
    }

    /**
     * Iterates through all empty cells and checks if placing an 'x' 
     * creates a winning sequence.
     */
    private static boolean canAchieveSequenceWithOneMove(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                if (grid[r][c] == '.') {
                    // Try placing the marker
                    grid[r][c] = 'x';

                    if (hasAnyWinningSequence(grid)) {
                        // Clean up before returning
                        grid[r][c] = '.';
                        return true;
                    }

                    // Backtrack: remove the marker to try the next cell
                    grid[r][c] = '.';
                }
            }
        }
        return false;
    }

    /**
     * Checks the entire grid to see if any line of 'x' matches the required sequence length.
     */
    private static boolean hasAnyWinningSequence(char[][] grid) {
        // Directional vectors representing: Horizontal, Vertical, Diagonal (\), and Anti-diagonal (/)
        final int[][] DIRECTIONS = {
            {0, 1},  
            {1, 0},  
            {1, 1},  
            {-1, 1}  
        };

        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                for (int[] dir : DIRECTIONS) {
                    if (isSequencePresentAt(grid, r, c, dir[0], dir[1])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a sequence of 'x' exists starting from (startR, startC) 
     * in the direction (dr, dc).
     */
    private static boolean isSequencePresentAt(char[][] grid, int startR, int startC, int dr, int dc) {
        for (int i = 0; i < SEQUENCE_LENGTH; i++) {
            int currentR = startR + (dr * i);
            int currentC = startC + (dc * i);

            if (!isWithinBounds(currentR, currentC) || grid[currentR][currentC] != 'x') {
                return false;
            }
        }
        return true;
    }

    /**
     * Helper to ensure coordinates are within the grid boundaries.
     */
    private static boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
    }
}

import java.util.Scanner;

/**
 * A utility to check if a 4x4 grid can be completed to form a line of three 'x's
 * by placing a single 'x' in an empty '.' cell.
 */
public class GridPatternChecker {

    private static final int GRID_SIZE = 4;
    private static final char EMPTY = '.';
    private static final char PLAYER_PIECE = 'x';

    public static void main(String[] args) {
        GridPatternChecker checker = new GridPatternChecker();
        checker.run();
    }

    /**
     * Orchestrates the input reading, logic execution, and output.
     */
    public void run() {
        Scanner scanner = new Scanner(System.in);
        char[][] grid = readGrid(scanner);
        scanner.close();

        if (canCompleteLine(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Reads a 4x4 grid from the standard input.
     */
    private char[][] readGrid(Scanner scanner) {
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            String line = scanner.next();
            for (int j = 0; j < GRID_SIZE; j++) {
                grid[i][j] = line.charAt(j);
            }
        }
        return grid;
    }

    /**
     * Determines if placing one 'x' in any '.' cell results in a line of three 'x's.
     * 
     * @param grid The current state of the 4x4 grid.
     * @return true if a line of three can be formed, false otherwise.
     */
    private boolean canCompleteLine(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                // Only attempt to place a piece in an empty cell
                if (grid[r][c] == EMPTY) {
                    grid[r][c] = PLAYER_PIECE; // Try placing the piece

                    if (hasThreeInARow(grid)) {
                        return true;
                    }

                    grid[r][c] = EMPTY; // Backtrack
                }
            }
        }
        return false;
    }

    /**
     * Checks the grid for any sequence of three 'x's in horizontal, 
     * vertical, or diagonal directions.
     */
    private boolean hasThreeInARow(char[][] grid) {
        // Direction vectors: Horizontal, Vertical, Diagonal Down-Right, Diagonal Down-Left
        final int[] dr = {0, 1, 1, 1};
        final int[] dc = {1, 0, 1, -1};

        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                // Optimization: only start checking if current cell is 'x'
                if (grid[r][c] != PLAYER_PIECE) {
                    continue;
                }

                for (int d = 0; d < 4; d++) {
                    if (checkDirection(grid, r, c, dr[d], dc[d])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a line of three 'x's starts from (r, c) in a specific direction.
     */
    private boolean checkDirection(char[][] grid, int r, int c, int dr, int dc) {
        int r2 = r + dr;
        int c2 = c + dc;
        int r3 = r + 2 * dr;
        int c3 = c + 2 * dc;

        return isWithinBounds(r3, c3) &&
               grid[r2][c2] == PLAYER_PIECE &&
               grid[r3][c3] == PLAYER_PIECE;
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
    }
}

import java.util.Scanner;

/**
 * CF390B Refactored
 * 
 * This program checks a 10x10 grid for a specific winning pattern 
 * (two 'x's and one '.') within its central 4x4 subgrid.
 */
public class CF390B {

    private static final int GRID_SIZE = 10;
    private static final int SUBGRID_START = 4;
    private static final int SUBGRID_END = 7;

    // Represents the 8 possible directions: Horizontal, Vertical, and Diagonal
    private static final int[][] DIRECTIONS = {
        {0, 1},   // Right
        {1, 1},   // Down-Right
        {1, 0},   // Down
        {1, -1},  // Down-Left
        {0, -1},  // Left
        {-1, -1}, // Up-Left
        {-1, 0},  // Up
        {-1, 1}   // Up-Right
    };

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] grid = readGrid(scanner, GRID_SIZE);

        if (grid == null) {
            return;
        }

        boolean foundPattern = searchForWin(grid);
        System.out.println(foundPattern ? "YES" : "NO");

        scanner.close();
    }

    /**
     * Reads the grid from standard input.
     * 
     * @param scanner The scanner to read from.
     * @param size The dimensions of the square grid.
     * @return A 2D char array representing the grid.
     */
    private static char[][] readGrid(Scanner scanner, int size) {
        char[][] grid = new char[size][size];
        for (int i = 0; i < size; i++) {
            if (scanner.hasNextLine()) {
                String line = scanner.nextLine();
                for (int j = 0; j < size; j++) {
                    if (j < line.length()) {
                        grid[i][j] = line.charAt(j);
                    } else {
                        grid[i][j] = ' '; // Padding for malformed lines
                    }
                }
            }
        }
        return grid;
    }

    /**
     * Iterates through the target subgrid to find an 'x' that starts a winning line.
     * 
     * @param grid The game board.
     * @return true if a winning pattern is found, false otherwise.
     */
    private static boolean searchForWin(char[][] grid) {
        for (int row = SUBGRID_START; row <= SUBGRID_END; row++) {
            for (int col = SUBGRID_START; col <= SUBGRID_END; col++) {
                // We only look for patterns starting from an 'x'
                if (grid[row][col] == 'x') {
                    if (checkAllDirections(grid, row, col)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks all 8 directions from a specific cell for a winning pattern.
     */
    private static boolean checkAllDirections(char[][] grid, int row, int col) {
        for (int[] direction : DIRECTIONS) {
            int dr = direction[0];
            int dc = direction[1];
            if (isWinningLineInDirection(grid, row, col, dr, dc)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Checks if a line of 3 cells in a given direction contains exactly 
     * two 'x' characters and one '.' character.
     * 
     * @param grid The game board.
     * @param row Starting row.
     * @param col Starting column.
     * @param dr Row direction delta.
     * @param dc Column direction delta.
     * @return true if the pattern is matched.
     */
    private static boolean isWinningLineInDirection(char[][] grid, int row, int col, int dr, int dc) {
        int xCount = 0;
        int dotCount = 0;

        for (int step = 0; step < 3; step++) {
            int currentRow = row + (dr * step);
            int currentCol = col + (dc * step);

            if (isOutOfBounds(currentRow, currentCol, grid.length)) {
                return false;
            }

            char cell = grid[currentRow][currentCol];
            if (cell == 'x') {
                xCount++;
            } else if (cell == '.') {
                dotCount++;
            }
        }

        return xCount == 2 && dotCount == 1;
    }

    /**
     * Validates if the given coordinates are within the grid boundaries.
     */
    private static boolean isOutOfBounds(int r, int c, int size) {
        return r < 0 || r >= size || c < 0 || c >= size;
    }
}

