/**
 * A utility to determine if a player can complete a line of 3 'x's 
 * on a 4x4 grid by placing a single additional 'x'.
 */
public class GridWinChecker {

    private static final int GRID_SIZE = 4;
    private static final int WIN_LENGTH = 3;
    private static final char FILLED_CHAR = 'x';
    private static final char EMPTY_CHAR = '.';

