        }

        scanner.close();
    }

    /**
     * Reads the 4x4 grid from standard input.
     */
    private static char[][] readGrid(Scanner scanner) {
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            if (scanner.hasNext()) {
                grid[i] = scanner.next().toCharArray();
            }
        }
        return grid;
    }

    /**
     * Simulates placing one 'x' in every empty cell to see if it results in a win.
     * 
     * @param grid The current state of the grid.
     * @return true if a winning move is possible.
     */
    private static boolean canWinWithOneMove(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                if (grid[r][c] == EMPTY_CHAR) {
                    // Try placing an 'x'
                    grid[r][c] = FILLED_CHAR;

                    if (hasWinningSequence(grid)) {
                        // Backtrack before returning
                        grid[r][c] = EMPTY_CHAR;
                        return true;
                    }

                    // Backtrack
                    grid[r][c] = EMPTY_CHAR;
                }
            }
        }
        return false;
    }

    /**
     * Checks the entire grid for any sequence of 'x's of the required length.
     * 
     * @param grid The current state of the grid.
     * @return true if a winning sequence is found.
     */
    private static boolean hasWinningSequence(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                if (grid[r][c] == FILLED_CHAR) {
                    for (int[] direction : DIRECTIONS) {
                        if (isSequenceAt(grid, r, c, direction[0], direction[1])) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a winning sequence starts from a specific cell in a specific direction.
     * 
     * @param grid The grid to check.
     * @param row Starting row index.
     * @param col Starting column index.
     * @param dr Row direction delta.
     * @param dc Column direction delta.
     * @return true if the sequence of FILLED_CHAR exists in this direction.
     */
    private static boolean isSequenceAt(char[][] grid, int row, int col, int dr, int dc) {
        int consecutiveCount = 0;
        for (int i = 0; i < WIN_LENGTH; i++) {
            int currentRow = row + (dr * i);
            int currentCol = col + (dc * i);

            if (isValidPosition(currentRow, currentCol) && grid[currentRow][currentCol] == FILLED_CHAR) {
                consecutiveCount++;
            } else {
                break;
            }
        }
        return consecutiveCount == WIN_LENGTH;
    }

    /**
     * Validates if the given coordinates are within the grid boundaries.
     */
    private static boolean isValidPosition(int r, int c) {
        return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
    }
}

import java.util.Scanner;

/**
 * GridPatternMatcher searches for a specific pattern within a 4x4 grid.
 * The pattern is defined as a straight line of 3 cells (horizontal, vertical, or diagonal)
 * containing exactly two 'x' characters and one '.' character.
 */
public class GridPatternMatcher {

    private static final int GRID_SIZE = 4;
    private static final int PATTERN_LENGTH = 3;
    private static final char TARGET_CHAR = 'x';
    private static final char EMPTY_CHAR = '.';

    // Directions represent the 8 possible movements: cardinal (N, S, E, W) and diagonal (NE, NW, SE, SW)
    private static final int[] DIRECTION_X = {1, 0, -1, 0, 1, -1, 1, -1};
    private static final int[] DIRECTION_Y = {0, 1, 0, -1, 1, -1, -1, 1};

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] grid = readGrid(scanner);

        if (grid != null && containsPattern(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Reads a GRID_SIZE x GRID_SIZE grid from the scanner.
     *
     * @param scanner The input scanner.
     * @return A 2D char array representing the grid, or null if input is invalid.
     */
    private static char[][] readGrid(Scanner scanner) {
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        try {
            for (int i = 0; i < GRID_SIZE; i++) {
                if (!scanner.hasNext()) {
                    return null;
                }
                String line = scanner.next();
                if (line.length() < GRID_SIZE) {
                    return null;
                }
                grid[i] = line.toCharArray();
            }
            return grid;
        } catch (Exception e) {
            return null;
        }
    }

    /**
     * Iterates through every cell in the grid to find the pattern.
     *
     * @param grid The 2D character grid.
     * @return true if the pattern is found, false otherwise.
     */
    private static boolean containsPattern(char[][] grid) {
        for (int row = 0; row < GRID_SIZE; row++) {
            for (int col = 0; col < GRID_SIZE; col++) {
                if (checkDirectionsFromCell(grid, row, col)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Checks all 8 possible directions from a specific cell.
     *
     * @param grid The 2D character grid.
     * @param row The starting row index.
     * @param col The starting column index.
     * @return true if the pattern is found in any direction.
     */
    private static boolean checkDirectionsFromCell(char[][] grid, int row, int col) {
        for (int i = 0; i < DIRECTION_X.length; i++) {
            if (isPatternInDirection(grid, row, col, DIRECTION_X[i], DIRECTION_Y[i])) {
                return true;
            }
        }
        return false;
    }

    /**
     * Checks if a valid pattern exists in a specific direction starting from (row, col).
     * The pattern requires exactly two TARGET_CHARs and one EMPTY_CHAR in a line.
     *
     * @param grid The 2D character grid.
     * @param row The starting row index.
     * @param col The starting column index.
     * @param dr The row direction increment.
     * @param dc The column direction increment.
     * @return true if the pattern matches.
     */
    private static boolean isPatternInDirection(char[][] grid, int row, int col, int dr, int dc) {
        int targetCount = 0;
        int emptyCount = 0;

        for (int step = 0; step < PATTERN_LENGTH; step++) {
            int currentR = row + (dr * step);
            int currentC = col + (dc * step);

            if (isOutOfBounds(currentR, currentC)) {
                // If the required sequence length goes out of bounds, this direction is invalid.
                return false;
            }

            char cellValue = grid[currentR][currentC];
            if (cellValue == TARGET_CHAR) {
                targetCount++;
            } else if (cellValue == EMPTY_CHAR) {
                emptyCount++;
            }
        }

        // The condition requires exactly 2 'x' and 1 '.' in the 3-cell sequence.
        return targetCount == 2 && emptyCount == 1;
    }

    /**
     * Checks if the given coordinates are outside the grid boundaries.
     *
     * @param r The row index.
     * @param c The column index.
     * @return true if out of bounds, false otherwise.
     */
    private static boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= GRID_SIZE || c < 0 || c >= GRID_SIZE;
    }
}

import java.util.Scanner;

/**
 * A solver to determine if a player can win a Tic-Tac-Toe style game 
 * on a 4x4 grid by placing a single 'x' in an empty cell.
 */
public class Solution {

    private static final int GRID_SIZE = 4;
    private static final int WIN_CONDITION_LENGTH = 3;
    private static final char EMPTY_CELL = '.';
    private static final char PLAYER_X = 'x';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNext()) {
            scanner.close();
            return;
        }

        char[][] grid = readGrid(scanner);
        boolean canWin = canPlayerWinInOneMove(grid);

        System.out.println(canWin ? "YES" : "NO");

        scanner.close();
    }

    /**
     * Reads the grid from standard input.
     */
    private static char[][] readGrid(Scanner scanner) {
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            if (scanner.hasNext()) {
                grid[i] = scanner.next().toCharArray();
            }
        }
        return grid;
    }

    /**
     * Iterates through all empty cells, simulates a move, and checks if it results in a win.
     * 
     * @param grid The current state of the board.
     * @return true if any single move results in a winning sequence.
     */
    private static boolean canPlayerWinInOneMove(char[][] grid) {
        Board board = new Board(grid);

        for (int row = 0; row < GRID_SIZE; row++) {
            for (int col = 0; col < GRID_SIZE; col++) {
                if (board.getCell(row, col) == EMPTY_CELL) {
                    // Simulate placing PLAYER_X
                    board.setCell(row, col, PLAYER_X);

                    if (board.hasWinningLine()) {
                        return true;
                    }

                    // Backtrack: reset the cell to empty for the next iteration
                    board.setCell(row, col, EMPTY_CELL);
                }
            }
        }
        return false;
    }

    /**
     * Encapsulates the board state and provides methods to validate game rules.
     */
    private static class Board {
        private final char[][] grid;

        public Board(char[][] grid) {
            this.grid = grid;
        }

        public char getCell(int row, int col) {
            return grid[row][col];
        }

        public void setCell(int row, int col, char value) {
            grid[row][col] = value;
        }

        /**
         * Checks if any winning line exists anywhere on the board.
         */
        public boolean hasWinningLine() {
            for (int row = 0; row < GRID_SIZE; row++) {
                for (int col = 0; col < GRID_SIZE; col++) {
                    for (Direction direction : Direction.values()) {
                        if (isWinningSequenceAt(row, col, direction)) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        /**
         * Checks if a winning sequence starts from the given coordinates in a specific direction.
         */
        private boolean isWinningSequenceAt(int startRow, int startCol, Direction direction) {
            for (int step = 0; step < WIN_CONDITION_LENGTH; step++) {
                int currentRow = startRow + (direction.deltaRow * step);
                int currentCol = startCol + (direction.deltaCol * step);

                if (isOutOfBounds(currentRow, currentCol) || grid[currentRow][currentCol] != PLAYER_X) {
                    return false;
                }
            }
            return true;
        }

        private boolean isOutOfBounds(int row, int col) {
            return row < 0 || row >= GRID_SIZE || col < 0 || col >= GRID_SIZE;
        }
    }

    /**
     * Represents the 8 possible directions on a 2D grid.
     */
    private enum Direction {
        NORTH(-1, 0),
        NORTH_EAST(-1, 1),
        EAST(0, 1),
        SOUTH_EAST(1, 1),
        SOUTH(1, 0),
        SOUTH_WEST(1, -1),
        WEST(0, -1),
        NORTH_WEST(-1, -1);

        private final int deltaRow;
        private final int deltaCol;

        Direction(int deltaRow, int deltaCol) {
            this.deltaRow = deltaRow;
            this.deltaCol = deltaCol;
        }
    }
}

