                        return true;
                    }

                    // Revert move (backtrack)
                    board[r][c] = '.';
                }
            }
        }
        return false;
    }

    /**
     * Scans the board to see if any streak of 3 'x's exists.
     */
    private static boolean isWinningBoard(char[][] board) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                // If current cell is not 'x', it can't be the start of a winning streak
                if (board[r][c] != 'x') {
                    continue;
                }

                for (int[] direction : DIRECTIONS) {
                    if (checkStreak(board, r, c, direction[0], direction[1])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a specific direction from (startRow, startCol) forms a winning streak.
     */
    private static boolean checkStreak(char[][] board, int startRow, int startCol, int dr, int dc) {
        for (int i = 1; i < WIN_STREAK; i++) {
            int nextRow = startRow + (i * dr);
            int nextCol = startCol + (i * dc);

            if (isOutOfBounds(nextRow, nextCol) || board[nextRow][nextCol] != 'x') {
                return false;
            }
        }
        return true;
    }

    private static boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= GRID_SIZE || c < 0 || c >= GRID_SIZE;
    }
}

import java.util.Scanner;

/**
 * A refactored TicTacToe checker that identifies if a specific pattern
 * (exactly two 'x's and one '.') exists in specific triplets within a 4x4 grid.
 */
public class TicTacToe {

    private static final int BOARD_SIZE = 4;
    private static final char PLAYER_X = 'x';
    private static final char EMPTY = '.';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] board = readBoard(scanner);

        if (checkWinCondition(board)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Reads the 4x4 board from standard input.
     */
    private static char[][] readBoard(Scanner scanner) {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (scanner.hasNext()) {
                String line = scanner.next();
                for (int j = 0; j < BOARD_SIZE && j < line.length(); j++) {
                    board[i][j] = line.charAt(j);
                }
            }
        }
        return board;
    }

    /**
     * Evaluates if any row, column, or specific diagonal triplet matches the pattern.
     */
    private static boolean checkWinCondition(char[][] board) {
        return hasRowMatch(board) || 
               hasColMatch(board) || 
               hasDiagonalMatch(board);
    }

    /**
     * Checks rows for the specific triplet pattern defined in the original logic.
     */
    private static boolean hasRowMatch(char[][] board) {
        for (int i = 0; i < BOARD_SIZE; i++) {
            // Checks triplets (0,1,2) and (3,1,2) within the current row
            if (isPatternMatch(board[i][0], board[i][1], board[i][2]) ||
                isPatternMatch(board[i][3], board[i][1], board[i][2])) {
                return true;
            }
        }
        return false;
    }

    /**
     * Checks columns for the specific triplet pattern defined in the original logic.
     */
    private static boolean hasColMatch(char[][] board) {
        for (int j = 0; j < BOARD_SIZE; j++) {
            // Checks triplets (0,1,2) and (3,1,2) within the current column
            if (isPatternMatch(board[0][j], board[1][j], board[2][j]) ||
                isPatternMatch(board[3][j], board[1][j], board[2][j])) {
                return true;
            }
        }
        return false;
    }

    /**
     * Checks the specific set of non-standard diagonal triplets provided in the original code.
     */
    private static boolean hasDiagonalMatch(char[][] board) {
        return isPatternMatch(board[2][0], board[1][1], board[0][2]) ||
               isPatternMatch(board[3][0], board[2][1], board[1][2]) ||
               isPatternMatch(board[0][3], board[2][1], board[1][2]) ||
               isPatternMatch(board[3][1], board[2][2], board[1][3]) ||
               isPatternMatch(board[0][1], board[1][2], board[2][3]) ||
               isPatternMatch(board[0][0], board[1][1], board[2][2]) ||
               isPatternMatch(board[3][3], board[1][1], board[2][2]) ||
               isPatternMatch(board[1][0], board[2][1], board[3][2]);
    }

    /**
     * Determines if a triplet consists of exactly two 'x' characters and one empty '.' character.
     */
    private static boolean isPatternMatch(char a, char b, char c) {
        int xCount = 0;
        int dotCount = 0;

        char[] triplet = {a, b, c};
        for (char ch : triplet) {
            if (ch == PLAYER_X) {
                xCount++;
            } else if (ch == EMPTY) {
                dotCount++;
            }
        }

        return xCount == 2 && dotCount == 1;
    }
}

import java.io.File;
import java.io.FileNotFoundException;
import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * GridPatternChecker analyzes a 4x4 grid to find specific winning patterns.
 * The target patterns are sequences of three characters containing exactly 
 * two 'x's and one '.' in configurations: "xx.", "x.x", or ".xx".
 */
public class GridPatternChecker {

    private static final int GRID_SIZE = 4;
    private static final String[] WINNING_PATTERNS = {"xx.", "x.x", ".xx"};

    public static void main(String[] args) {
        String filePath = (args.length > 0) ? args[0] : null;
        GridPatternChecker checker = new GridPatternChecker();
        checker.run(filePath);
    }

    /**
     * Orchestrates the reading of input and the execution of the checker logic.
     * @param filePath The path to the input file, or null to read from System.in.
     */
    public void run(String filePath) {
        try (Scanner scanner = (filePath == null) 
                ? new Scanner(System.in) 
                : new Scanner(new File(filePath))) {

            if (!scanner.hasNextLine()) {
                return;
            }

            char[][] grid = readGrid(scanner);
            if (grid != null) {
                boolean isMatchFound = checkGridForPatterns(grid);
                System.out.print(isMatchFound ? "YES" : "NO");
            }

        } catch (FileNotFoundException e) {
            System.err.println("Error: Input file not found: " + e.getMessage());
        } catch (Exception e) {
            System.err.println("An unexpected error occurred: " + e.getMessage());
        }
    }

    /**
     * Reads 4 lines of input into a 2D character array.
     */
    private char[][] readGrid(Scanner scanner) {
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            if (scanner.hasNextLine()) {
                String line = scanner.nextLine().trim();
                for (int j = 0; j < GRID_SIZE; j++) {
                    // Fill grid with character or a space if the line is too short
                    grid[i][j] = (j < line.length()) ? line.charAt(j) : ' ';
                }
            }
        }
        return grid;
    }

    /**
     * Collects all relevant lines (rows, columns, and diagonals) and checks them.
     */
    private boolean checkGridForPatterns(char[][] grid) {
        List<String> allLines = collectRelevantLines(grid);
        for (String line : allLines) {
            if (containsWinningPattern(line)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Gathers all rows, columns, and specific diagonal segments used in the original logic.
     */
    private List<String> collectRelevantLines(char[][] grid) {
        List<String> lines = new ArrayList<>();

        // 1. Rows
        for (int i = 0; i < GRID_SIZE; i++) {
            lines.add(new String(grid[i]));
        }

        // 2. Columns
        for (int j = 0; j < GRID_SIZE; j++) {
            StringBuilder col = new StringBuilder();
            for (int i = 0; i < GRID_SIZE; i++) {
                col.append(grid[i][j]);
            }
            lines.add(col.toString());
        }

        // 3. Main Diagonals (Length 4)
        lines.add(getDiagonal(grid, 0, 0, 1, 1));  // Top-left to bottom-right
        lines.add(getDiagonal(grid, 0, 3, 1, -1)); // Top-right to bottom-left

        // 4. Off-diagonals (Length 3)
        lines.add(getDiagonal(grid, 1, 0, 1, 1));  // Diagonal starting at (1,0)
        lines.add(getDiagonal(grid, 0, 1, 1, 1));  // Diagonal starting at (0,1)
        lines.add(getDiagonal(grid, 0, 2, 1, -1)); // Diagonal starting at (0,2)
        lines.add(getDiagonal(grid, 1, 3, 1, -1)); // Diagonal starting at (1,3)

        return lines;
    }

    /**
     * Helper to traverse the grid in a specific direction to extract a diagonal string.
     * 
     * @param grid The 2D array.
     * @param startR Starting row index.
     * @param startC Starting column index.
     * @param dr Row direction increment (1 or -1).
     * @param dc Column direction increment (1 or -1).
     * @return A string representation of the extracted diagonal.
     */
    private String getDiagonal(char[][] grid, int startR, int startC, int dr, int dc) {
        StringBuilder sb = new StringBuilder();
        int r = startR;
        int c = startC;
        while (r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE) {
            sb.append(grid[r][c]);
            r += dr;
            c += dc;
        }
        return sb.toString();
    }

    /**
     * Checks if a string contains any of the predefined winning patterns.
     */
    private boolean containsWinningPattern(String line) {
        for (String pattern : WINNING_PATTERNS) {
            if (line.contains(pattern)) {
                return true;
            }
        }
        return false;
    }
}

import java.util.Scanner;

/**
 * A utility to analyze a 4x4 grid and determine if placing an 'x' 
 * in any empty '.' cell would result in three 'x's forming a line.
 */
public class Main {

    private static final int GRID_SIZE = 4;
    private static final int TARGET_LENGTH = 3;

    // Direction vectors to check: Horizontal, Vertical, Diagonal Down-Right, Diagonal Down-Left
    private static final int[][] DIRECTIONS = {
        {0, 1},  // Horizontal
        {1, 0},  // Vertical
        {1, 1},  // Diagonal Down-Right
        {1, -1}  // Diagonal Down-Left
    };

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];

        // Load input grid
        for (int i = 0; i < GRID_SIZE; i++) {
            String line = scanner.next();
            for (int j = 0; j < GRID_SIZE; j++) {
                grid[i][j] = line.charAt(j);
            }
        }

        if (canFormTripletByPlacingX(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Iterates through the grid to find empty cells. 
     * Temporarily places an 'x' to see if it creates a three-in-a-row.
     *
     * @param grid The current 4x4 character grid.
     * @return true if any single placement creates a triplet, false otherwise.
     */
    private static boolean canFormTripletByPlacingX(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                if (grid[r][c] == '.') {
                    // Tentatively place an 'x'
                    grid[r][c] = 'x';

                    if (containsThreeInARow(grid)) {
                        return true;
                    }

                    // Backtrack: revert the change
                    grid[r][c] = '.';
                }
            }
        }
        return false;
    }

    /**
     * Checks the entire grid for any sequence of three 'x's in a line.
     *
     * @param grid The current grid.
     * @return true if a triplet is found.
     */
    private static boolean containsThreeInARow(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                if (grid[r][c] == 'x') {
                    for (int[] dir : DIRECTIONS) {
                        if (isTripletInDirection(grid, r, c, dir[0], dir[1])) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a triplet exists starting from (row, col) moving in a specific direction.
     *
     * @param grid The grid to check.
     * @param r Starting row index.
     * @param c Starting column index.
     * @param dr Row direction delta.
     * @param dc Column direction delta.
     * @return true if a sequence of TARGET_LENGTH 'x's is found.
     */
    private static boolean isTripletInDirection(char[][] grid, int r, int c, int dr, int dc) {
        for (int i = 1; i < TARGET_LENGTH; i++) {
            int nextR = r + (dr * i);
            int nextC = c + (dc * i);

            if (isOutOfBounds(nextR, nextC) || grid[nextR][nextC] != 'x') {
                return false;
            }
        }
        return true;
    }

    private static boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= GRID_SIZE || c < 0 || c >= GRID_SIZE;
    }
}

import java.util.Scanner;

/**
 * A program to determine if a 4x4 grid contains a winning sequence.
 * A winning sequence is defined as 3 consecutive cells (horizontal, vertical, or diagonal)
 * containing at least two 'x' characters and no characters other than 'x' or '.'.
 */
public class Main {

    private static final int GRID_SIZE = 4;
    private static final int WIN_LENGTH = 3;
    private static final int MIN_X_REQUIRED = 2;

    // Direction vectors for: Horizontal, Vertical, Diagonal Down-Right, Diagonal Down-Left
    private static final int[][] DIRECTIONS = {
        {0, 1},  // Horizontal
        {1, 0},  // Vertical
        {1, 1},  // Diagonal Down-Right
        {1, -1}  // Diagonal Down-Left
    };

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];

        try {
            // Load the grid from input
            for (int i = 0; i < GRID_SIZE; i++) {
                if (scanner.hasNext()) {
                    grid[i] = scanner.next().toCharArray();
                }
            }

            // Check for win and output result
            if (hasWinningSequence(grid)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        } finally {
            scanner.close();
        }
    }

    /**
     * Iterates through every cell in the grid and checks all possible directions
     * to see if a winning sequence starts at that cell.
     *
     * @param grid The 2D character array representing the game board.
     * @return true if a winning sequence is found, false otherwise.
     */
    private static boolean hasWinningSequence(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                for (int[] direction : DIRECTIONS) {
                    if (isWinningLine(grid, r, c, direction[0], direction[1])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a specific line of cells starting from (startR, startC) 
     * in direction (dr, dc) meets the winning criteria.
     *
     * @param grid The 2D character array.
     * @param startR Starting row index.
     * @param startC Starting column index.
     * @param dr Row direction increment.
     * @param dc Column direction increment.
     * @return true if the line is a win, false otherwise.
     */
    private static boolean isWinningLine(char[][] grid, int startR, int startC, int dr, int dc) {
        int xCount = 0;

        for (int i = 0; i < WIN_LENGTH; i++) {
            int currR = startR + (i * dr);
            int currC = startC + (i * dc);

            // Check bounds
            if (isOutOfBounds(currR, currC)) {
                return false;
            }

            char cell = grid[currR][currC];

            if (cell == 'x') {
                xCount++;
            } else if (cell != '.') {
                // If the cell is neither 'x' nor '.', this sequence cannot be a win
                return false;
            }
        }

        // A win requires at least MIN_X_REQUIRED 'x's within the sequence
        return xCount >= MIN_X_REQUIRED;
    }

    /**
     * Helper to verify if a coordinate is outside the grid boundaries.
     */
    private static boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= GRID_SIZE || c < 0 || c >= GRID_SIZE;
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * A solver for a 4x4 grid puzzle where the goal is to determine if placing 
 * exactly one 'x' in an empty '.' cell can create a sequence of 3 'x's 
 * horizontally, vertically, or diagonally.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        PuzzleSolver solver = new PuzzleSolver();
        solver.solve(reader, writer);

        writer.close();
    }

    static class PuzzleSolver {
        private static final int GRID_SIZE = 4;
        private static final int WIN_LENGTH = 3;

        // Direction vectors for: Horizontal, Vertical, Diagonal Down-Right, Diagonal Down-Left
        private static final int[] DR = {0, 1, 1, 1};
        private static final int[] DC = {1, 0, 1, -1};

        public void solve(FastReader reader, PrintWriter writer) {
            char[][] grid = new char[GRID_SIZE][GRID_SIZE];

            // Load the grid
            for (int i = 0; i < GRID_SIZE; i++) {
                String row = reader.next();
                if (row == null) break;
                grid[i] = row.toCharArray();
            }

            boolean possible = false;

            // Try placing exactly one 'x' in every empty '.' cell
            for (int r = 0; r < GRID_SIZE; r++) {
                for (int c = 0; c < GRID_SIZE; c++) {
                    if (grid[r][c] == '.') {
                        grid[r][c] = 'x'; // Try the move
                        if (isWinningConditionMet(grid)) {
                            possible = true;
                            break;
                        }
                        grid[r][c] = '.'; // Backtrack
                    }
                }
                if (possible) break;
            }

            writer.println(possible ? "YES" : "NO");
        }

        /**
         * Checks if the current grid state contains any sequence of 'x's 
         * of the required winning length in any direction.
         */
        private boolean isWinningConditionMet(char[][] grid) {
            for (int r = 0; r < GRID_SIZE; r++) {
                for (int c = 0; c < GRID_SIZE; c++) {
                    if (grid[r][c] == 'x') {
                        // Check all 4 directions from this cell
                        for (int dir = 0; dir < 4; dir++) {
                            if (checkSequence(grid, r, c, DR[dir], DC[dir])) {
                                return true;
                            }
                        }
                    }
                }
            }
            return false;
        }

        /**
         * Checks if a winning sequence exists starting from (startR, startC) 
         * moving in direction (dr, dc).
         */
        private boolean checkSequence(char[][] grid, int startR, int startC, int dr, int dc) {
            for (int step = 0; step < WIN_LENGTH; step++) {
                int currR = startR + (step * dr);
                int currC = startC + (step * dc);

                if (!isWithinBounds(currR, currC) || grid[currR][currC] != 'x') {
                    return false;
                }
            }
            return true;
        }

        private boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
        }
    }

    /**
     * Fast I/O reader for efficient input processing.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }
    }
}

import java.util.Scanner;

/**
 * A program to determine if a player can complete a winning line 
 * on a 4x4 grid.
 */
public class Main {
    private static final int GRID_SIZE = 4;
    private static final int WINNING_LENGTH = 3;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];

        int xCount = 0;
        int oCount = 0;

        // 1. Input Parsing
        try {
            for (int i = 0; i < GRID_SIZE; i++) {
                if (!scanner.hasNext()) break;
                String row = scanner.next();
                for (int j = 0; j < GRID_SIZE; j++) {
                    char cell = row.charAt(j);
                    grid[i][j] = cell;
                    if (cell == 'x') {
                        xCount++;
                    } else if (cell == 'o') {
                        oCount++;
                    }
                }
            }

            // 2. Logic Execution
            Board board = new Board(grid);

            // Determine which player we are checking. 
            // We check the player who has the most pieces.
            char targetPlayer = (xCount >= oCount) ? 'x' : 'o';

            // 3. Output Result
            if (board.canFormWinningLine(targetPlayer)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        } finally {
            scanner.close();
        }
    }

    /**
     * Represents the game board and encapsulates the win-condition logic.
     */
    private static class Board {
        private final char[][] grid;

        // Directional vectors for checking lines: {rowDelta, colDelta}
        private static final int[][] DIRECTIONS = {
            {0, 1},  // Horizontal
            {1, 0},  // Vertical
            {1, 1},  // Diagonal Down-Right
            {1, -1}  // Diagonal Down-Left
        };

        public Board(char[][] grid) {
            this.grid = grid;
        }

        /**
         * Iterates through the board to see if the target player can form a line.
         * 
         * @param player The character representing the player ('x' or 'o').
         * @return true if a line of WINNING_LENGTH can be formed.
         */
        public boolean canFormWinningLine(char player) {
            for (int r = 0; r < GRID_SIZE; r++) {
                for (int c = 0; c < GRID_SIZE; c++) {
                    for (int[] direction : DIRECTIONS) {
                        if (isSequencePossible(r, c, direction[0], direction[1], player)) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        /**
         * Checks if a line of winning length can be formed starting from (startR, startC)
         * in a specific direction.
         */
        private boolean isSequencePossible(int startR, int startC, int dr, int dc, char player) {
            int playerPieces = 0;
            int emptySpaces = 0;

            for (int i = 0; i < WINNING_LENGTH; i++) {
                int currentRow = startR + (i * dr);
                int currentCol = startC + (i * dc);

                if (isOutOfBounds(currentRow, currentCol)) {
                    return false;
                }

                char cell = grid[currentRow][currentCol];
                if (cell == player) {
                    playerPieces++;
                } else if (cell == '.') {
                    emptySpaces++;
                } else {
                    // Cell contains the opponent's piece, so this line is blocked
                    return false;
                }
            }

            // A line is valid if it contains the player's pieces and 
            // at most one empty space (meaning the player can win in one move).
            return emptySpaces <= 1;
        }

        private boolean isOutOfBounds(int r, int c) {
            return r < 0 || r >= GRID_SIZE || c < 0 || c >= GRID_SIZE;
        }
    }
}

import java.util.Scanner;

/**
 * A utility to detect specific patterns in a 4x4 grid.
 * The target pattern is a sequence of three characters containing 
 * exactly two 'x's and one '.' in any of the three possible positions:
 * ".xx", "x.x", or "xx.".
 */
public class GridPatternMatcher {

    private static final int GRID_SIZE = 4;
    private static final char X = 'x';
    private static final char DOT = '.';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] grid = readGrid(scanner, GRID_SIZE);
        scanner.close();

        if (hasWinningPattern(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Reads the grid from standard input.
     */
    private static char[][] readGrid(Scanner scanner, int size) {
        char[][] grid = new char[size][size];
        for (int i = 0; i < size; i++) {
            if (scanner.hasNextLine()) {
                String line = scanner.nextLine().trim();
                // Ensure we only take up to 'size' characters in case of trailing spaces
                grid[i] = line.toCharArray();
            }
