        return grid;
    }

    /**
     * Orchestrates the search for the pattern in all directions.
     */
    private static boolean hasWinningPattern(char[][] grid) {
        return checkHorizontal(grid) ||
               checkVertical(grid) ||
               checkDiagonals(grid);
    }

    private static boolean checkHorizontal(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c <= GRID_SIZE - 3; c++) {
                if (isTargetPattern(grid[r][c], grid[r][c + 1], grid[r][c + 2])) {
                    return true;
                }
            }
        }
        return false;
    }

    private static boolean checkVertical(char[][] grid) {
        for (int r = 0; r <= GRID_SIZE - 3; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                if (isTargetPattern(grid[r][c], grid[r + 1][c], grid[r + 2][c])) {
                    return true;
                }
            }
        }
        return false;
    }

    private static boolean checkDiagonals(char[][] grid) {
        // Down-Right diagonals
        for (int r = 0; r <= GRID_SIZE - 3; r++) {
            for (int c = 0; c <= GRID_SIZE - 3; c++) {
                if (isTargetPattern(grid[r][c], grid[r + 1][c + 1], grid[r + 2][c + 2])) {
                    return true;
                }
            }
        }

        // Down-Left diagonals
        for (int r = 0; r <= GRID_SIZE - 3; r++) {
            for (int c = 2; c < GRID_SIZE; c++) {
                if (isTargetPattern(grid[r][c], grid[r + 1][c - 1], grid[r + 2][c - 2])) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Validates if the three characters match the patterns: ".xx", "x.x", or "xx.".
     */
    private static boolean isTargetPattern(char a, char b, char c) {
        // Pattern: .xx
        if (a == DOT && b == X && c == X) return true;
        // Pattern: x.x
        if (a == X && b == DOT && c == X) return true;
        // Pattern: xx.
        if (a == X && b == X && c == DOT) return true;

        return false;
    }
}

import java.util.Scanner;

/**
 * A refactored program to determine if a 4x4 grid contains a "winning" segment.
 * A segment of length 3 is considered winning if it contains:
 * - Exactly 3 'x' characters
 * - OR exactly 2 'x' characters and 0 'o' characters.
 */
public class Main {
    private static final int GRID_SIZE = 4;
    private static final int WIN_LENGTH = 3;

    // Directions to check: Horizontal, Vertical, Diagonal (Down-Right), Diagonal (Down-Left)
    private static final int[] DR = {0, 1, 1, 1};
    private static final int[] DC = {1, 0, 1, -1};

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        try {
            char[][] grid = readGrid(scanner);
            if (grid != null) {
                if (hasWinningSegment(grid)) {
                    System.out.println("YES");
                } else {
                    System.out.println("NO");
                }
            }
        } catch (Exception e) {
            System.err.println("An error occurred while processing the grid: " + e.getMessage());
        } finally {
            scanner.close();
        }
    }

    /**
     * Reads the 4x4 grid from standard input.
     * @param scanner The scanner to read from.
     * @return A 2D char array representing the grid, or null if input is invalid.
     */
    private static char[][] readGrid(Scanner scanner) {
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            if (!scanner.hasNext()) {
                return null;
            }
            String line = scanner.next();
            if (line.length() < GRID_SIZE) {
                return null;
            }
            for (int j = 0; j < GRID_SIZE; j++) {
                grid[i][j] = line.charAt(j);
            }
        }
        return grid;
    }

    /**
     * Scans the grid for any segment of WIN_LENGTH that satisfies the winning condition.
     * @param grid The 2D character array.
     * @return true if a winning segment is found.
     */
    private static boolean hasWinningSegment(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                for (int d = 0; d < 4; d++) {
                    if (canFitSegment(r, c, DR[d], DC[d])) {
                        if (isWinning(grid, r, c, DR[d], DC[d])) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a segment of length WIN_LENGTH starting at (r, c) in direction (dr, dc)
     * remains within the boundaries of the grid.
     */
    private static boolean canFitSegment(int r, int c, int dr, int dc) {
        int endR = r + (WIN_LENGTH - 1) * dr;
        int endC = c + (WIN_LENGTH - 1) * dc;
        return endR >= 0 && endR < GRID_SIZE && endC >= 0 && endC < GRID_SIZE;
    }

    /**
     * Evaluates the specific winning condition for a segment.
     * Condition: (count of 'x' == 3) OR (count of 'x' == 2 AND count of 'o' == 0).
     */
    private static boolean isWinning(char[][] grid, int r, int c, int dr, int dc) {
        int xCount = 0;
        int oCount = 0;

        for (int i = 0; i < WIN_LENGTH; i++) {
            char cell = grid[r + i * dr][c + i * dc];
            if (cell == 'x') {
                xCount++;
            } else if (cell == 'o') {
                oCount++;
            }
        }

        return xCount == 3 || (xCount == 2 && oCount == 0);
    }
}

import java.io.*;
import java.util.*;

/**
 * A refactored version of the grid game solver.
 * The goal is to determine if the current player can complete a line of 3 in a 4x4 grid.
 */
public class Main {

    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        OutputWriter out = new OutputWriter(System.out);

        GameSolver solver = new GameSolver();
        solver.solve(in, out);

        out.close();
    }

    static class GameSolver {
        private static final int GRID_SIZE = 4;
        private static final int WINNING_LENGTH = 3;

        // Direction vectors for: Vertical, Horizontal, Diagonal (down-right), Diagonal (down-left)
        private static final int[] DIR_X = {1, 0, 1, 1};
        private static final int[] DIR_Y = {0, 1, 1, -1};

        public void solve(InputReader in, OutputWriter out) {
            char[][] grid = new char[GRID_SIZE][];
            int countX = 0;
            int countO = 0;

            // Read the 4x4 grid and count existing pieces
            for (int i = 0; i < GRID_SIZE; i++) {
                grid[i] = in.nextChars();
                countX += countOccurrences(grid[i], 'x');
                countO += countOccurrences(grid[i], 'o');
            }

            // Determine whose turn it is. 
            // If counts are equal, it's 'x's turn; otherwise, it's 'o's turn.
            char currentPlayer = (countX == countO) ? 'x' : 'o';

            if (canWinInOneMove(grid, currentPlayer)) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        }

        private int countOccurrences(char[] row, char target) {
            int count = 0;
            for (char c : row) {
                if (c == target) {
                    count++;
                }
            }
            return count;
        }

        /**
         * Checks if placing the currentPlayer's piece in any empty '.' cell 
         * results in a sequence of at least WINNING_LENGTH.
         */
        private boolean canWinInOneMove(char[][] grid, char player) {
            for (int r = 0; r < GRID_SIZE; r++) {
                for (int c = 0; c < GRID_SIZE; c++) {
                    if (grid[r][c] == '.') {
                        if (wouldCompleteLine(grid, r, c, player)) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        /**
         * Simulates placing a piece at (row, col) and checks all 4 axes for a winning line.
         */
        private boolean wouldCompleteLine(char[][] grid, int row, int col, char player) {
            for (int i = 0; i < 4; i++) {
                int lineLength = 1; // The piece we are about to place

                // Check in the positive direction along the axis
                lineLength += countInDirection(grid, row, col, DIR_X[i], DIR_Y[i], player);
                // Check in the negative direction along the axis
                lineLength += countInDirection(grid, row, col, -DIR_X[i], -DIR_Y[i], player);

                if (lineLength >= WINNING_LENGTH) {
                    return true;
                }
            }
            return false;
        }

        /**
         * Counts how many consecutive pieces of the same player exist in a specific direction.
         */
        private int countInDirection(char[][] grid, int row, int col, int dx, int dy, char player) {
            int count = 0;
            int r = row + dx;
            int c = col + dy;

            while (r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE && grid[r][c] == player) {
                count++;
                r += dx;
                c += dy;
            }
            return count;
        }
    }

    /**
     * Fast I/O utility for reading input.
     */
    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream inputStream) {
            this.reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public char[] nextChars() {
            String s = next();
            return (s == null) ? new char[0] : s.toCharArray();
        }
    }

    /**
     * Fast I/O utility for writing output.
     */
    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public void println(String message) {
            writer.println(message);
        }

        public void close() {
            writer.close();
        }
    }
}

import java.util.Scanner;

/**
 * A program to determine if 'x' can win a 4x4 Tic-Tac-Toe game 
 * in exactly one move.
 */
public class IllyaTicTacToe {

    private static final int BOARD_SIZE = 4;
    private static final int WIN_CONDITION = 3;
    private static final char PLAYER_X = 'x';
    private static final char EMPTY_CELL = '.';

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            char[][] initialGrid = readGrid(scanner);
            TicTacToeBoard board = new TicTacToeBoard(initialGrid);

            if (canXWinInOneMove(board)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /**
     * Reads the 4x4 grid from standard input.
     */
    private static char[][] readGrid(Scanner scanner) {
        char[][] grid = new char[BOARD_SIZE][BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i++) {
            String line = scanner.next();
            for (int j = 0; j < BOARD_SIZE; j++) {
                grid[i][j] = line.charAt(j);
            }
        }
        return grid;
    }

    /**
     * Simulates placing an 'x' in every empty cell to see if any move results in a win.
     */
    private static boolean canXWinInOneMove(TicTacToeBoard board) {
        for (int r = 0; r < BOARD_SIZE; r++) {
            for (int c = 0; c < BOARD_SIZE; c++) {
                if (board.getCellValue(r, c) == EMPTY_CELL) {
                    board.placeMark(r, c, PLAYER_X);

                    if (board.hasWinningSequence()) {
                        return true;
                    }

                    // Backtrack: reset the cell for the next simulation
                    board.placeMark(r, c, EMPTY_CELL);
                }
            }
        }
        return false;
    }

    /**
     * Represents the Tic-Tac-Toe board and its logic.
     */
    static class TicTacToeBoard {
        private final char[][] grid;

        public TicTacToeBoard(char[][] initialGrid) {
            // Deep copy the input grid to prevent external mutation
            this.grid = new char[BOARD_SIZE][BOARD_SIZE];
            for (int i = 0; i < BOARD_SIZE; i++) {
                System.arraycopy(initialGrid[i], 0, this.grid[i], 0, BOARD_SIZE);
            }
        }

        public char getCellValue(int row, int col) {
            return grid[row][col];
        }

        public void placeMark(int row, int col, char mark) {
            grid[row][col] = mark;
        }

        /**
         * Checks if there is any sequence of 3 'x' marks in a row, column, or diagonal.
         */
        public boolean hasWinningSequence() {
            for (int r = 0; r < BOARD_SIZE; r++) {
                for (int c = 0; c < BOARD_SIZE; c++) {
                    if (grid[r][c] == PLAYER_X) {
                        if (checkAllDirections(r, c)) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        private boolean checkAllDirections(int r, int c) {
            // Directions: {rowDelta, colDelta}
            int[][] directions = {
                {0, 1},  // Horizontal
                {1, 0},  // Vertical
                {1, 1},  // Diagonal Down-Right
                {1, -1}  // Diagonal Down-Left
            };

            for (int[] dir : directions) {
                if (isSequencePresent(r, c, dir[0], dir[1])) {
                    return true;
                }
            }
            return false;
        }

        private boolean isSequencePresent(int startR, int startC, int dr, int dc) {
            int count = 0;
            for (int i = 0; i < WIN_CONDITION; i++) {
                int currR = startR + (dr * i);
                int currC = startC + (dc * i);

                if (isValidPosition(currR, currC) && grid[currR][currC] == PLAYER_X) {
                    count++;
                } else {
                    break;
                }
            }
            return count == WIN_CONDITION;
        }

        private boolean isValidPosition(int r, int c) {
            return r >= 0 && r < BOARD_SIZE && c >= 0 && c < BOARD_SIZE;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the TinkoffB problem.
 * The goal is to determine if the 'S' (start) and 'T' (target) can "see" each other
 * through a shared intersection point in their horizontal or vertical sightlines.
 */
public class TinkoffB {

    // Represents a coordinate on the grid
    static class Point {
        final int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Point)) return false;
            Point point = (Point) o;
            return r == point.r && c == point.c;
        }

        @Override
        public int hashCode() {
            return Objects.hash(r, c);
        }
    }

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);

        int rows = sc.nextInt();
        int cols = sc.nextInt();

        char[][] grid = new char[rows][cols];
        Point startPos = null;
        Point targetPos = null;

        // Parse grid and locate 'S' and 'T'
        for (int r = 0; r < rows; r++) {
            String line = sc.next();
            for (int c = 0; c < cols; c++) {
                grid[r][c] = line.charAt(c);
                if (grid[r][c] == 'S') {
                    startPos = new Point(r, c);
                } else if (grid[r][c] == 'T') {
                    targetPos = new Point(r, c);
                }
            }
        }

        if (startPos == null || targetPos == null) {
            System.out.println("NO");
            return;
        }

        if (canSeeEachOther(grid, rows, cols, startPos, targetPos)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Determines if the start and target points have intersecting sightlines.
     */
    private static boolean canSeeEachOther(char[][] grid, int rows, int cols, Point start, Point target) {
        // Calculate all cells visible from the start position (horizontal and vertical)
        boolean[][] startSightline = computeSightline(grid, rows, cols, start);

        // Check if any cell visible from the target position is also in the start sightline
        return isTargetVisible(grid, rows, cols, target, startSightline);
    }

    /**
     * Generates a visibility map for a given point.
     * @return A 2D boolean array where true represents a cell visible from the source.
     */
    private static boolean[][] computeSightline(char[][] grid, int rows, int cols, Point p) {
        boolean[][] visible = new boolean[rows][cols];
        visible[p.r][p.c] = true;

        // Directions: Right, Left, Down, Up
        int[][] directions = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

        for (int[] d : directions) {
            int nr = p.r + d[0];
            int nc = p.c + d[1];

            while (isValid(nr, nc, rows, cols) && grid[nr][nc] != '*') {
                visible[nr][nc] = true;
                nr += d[0];
                nc += d[1];
            }
        }
        return visible;
    }

    /**
     * Checks if any cell in the target's sightline intersects with the start's sightline.
     */
    private static boolean isTargetVisible(char[][] grid, int rows, int cols, Point target, boolean[][] startSightline) {
        // Check if target itself is in start sightline
        if (startSightline[target.r][target.c]) return true;

        int[][] directions = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

        for (int[] d : directions) {
            int nr = target.r + d[0];
            int nc = target.c + d[1];

            while (isValid(nr, nc, rows, cols) && grid[nr][nc] != '*') {
                if (startSightline[nr][nc]) {
                    return true;
                }
                nr += d[0];
                nc += d[1];
            }
        }
        return false;
    }

    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * High-performance scanner for fast I/O.
     */
    public static class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;

/**
 * ProblemB refactored for maintainability and performance.
 * This program determines if a target 'T' can be reached from start 'S' 
 * on a grid with a maximum of 2 turns.
 */
public class ProblemB {

    private static final char START_CHAR = 'S';
    private static final char TARGET_CHAR = 'T';
    private static final char OBSTACLE_CHAR = '*';
    private static final int MAX_TURNS = 2;

    // Directional offsets: Up, Down, Left, Right
    private static final int[][] DIRECTIONS = {
            {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    /**
     * Represents the current state of the search.
     */
    private static class State {
        final int r, c, dirIdx, turns;

        State(int r, int c, int dirIdx, int turns) {
            this.r = r;
            this.c = c;
            this.dirIdx = dirIdx;
            this.turns = turns;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        if (!sc.hasNextInt()) {
            sc.close();
            return;
        }

        int rows = sc.nextInt();
        int cols = sc.nextInt();

        char[][] board = new char[rows][cols];
        int startR = -1, startC = -1;
        int targetR = -1, targetC = -1;

        for (int i = 0; i < rows; i++) {
            String line = sc.next();
            for (int j = 0; j < cols; j++) {
                board[i][j] = line.charAt(j);
                if (board[i][j] == START_CHAR) {
                    startR = i;
                    startC = j;
                } else if (board[i][j] == TARGET_CHAR) {
                    targetR = i;
                    targetC = j;
                }
            }
        }
        sc.close();

        if (canReachTarget(board, rows, cols, startR, startC, targetR, targetC)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Uses BFS to find if the target is reachable within the turn limit.
     * 
     * @return true if a valid path exists, false otherwise.
     */
    private static boolean canReachTarget(char[][] board, int rows, int cols, 
                                          int startR, int startC, 
                                          int targetR, int targetC) {
        // Boundary cases
        if (startR == -1 || targetR == -1) return false;
        if (startR == targetR && startC == targetC) return true;

        // visited[row][col][directionIndex][turnsCount]
        // We track turns up to MAX_TURNS (0, 1, or 2)
        boolean[][][][] visited = new boolean[rows][cols][4][MAX_TURNS + 1];
        Queue<State> queue = new LinkedList<>();

        // Initialize BFS by attempting to move in all 4 directions from the start
        for (int i = 0; i < 4; i++) {
            int nr = startR + DIRECTIONS[i][0];
            int nc = startC + DIRECTIONS[i][1];

            if (isValid(nr, nc, rows, cols) && board[nr][nc] != OBSTACLE_CHAR) {
                if (board[nr][nc] == TARGET_CHAR) return true;

                visited[nr][nc][i][0] = true;
                queue.add(new State(nr, nc, i, 0));
            }
        }

        while (!queue.isEmpty()) {
            State curr = queue.poll();

            for (int i = 0; i < 4; i++) {
                int nr = curr.r + DIRECTIONS[i][0];
                int nc = curr.c + DIRECTIONS[i][1];

                // If direction index changes, it counts as a turn
                int nextTurns = (i == curr.dirIdx) ? curr.turns : curr.turns + 1;

                if (isValid(nr, nc, rows, cols) 
                        && board[nr][nc] != OBSTACLE_CHAR 
                        && nextTurns <= MAX_TURNS) {

                    if (board[nr][nc] == TARGET_CHAR) {
                        return true;
                    }

                    if (!visited[nr][nc][i][nextTurns]) {
                        visited[nr][nc][i][nextTurns] = true;
                        queue.add(new State(nr, nc, i, nextTurns));
                    }
                }
            }
        }

        return false;
    }

    /**
     * Checks if a coordinate is within the grid boundaries.
     */
    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

import java.io.*;
