/**
 * A solution to find if a target can be reached from a starting point 
 * on a grid with a limited number of turns.
 */
public class Solution {

    // Directional offsets: Up, Right, Down, Left
    private static final int[] ROW_DIRECTIONS = {-1, 0, 1, 0};
    private static final int[] COL_DIRECTIONS = {0, 1, 0, -1};
    private static final int MAX_TURNS = 2;

    /**
     * Represents a specific state in the grid search.
     */
    private static class State {
        final int row;
        final int col;
        final int direction;
        final int turns;

        State(int row, int col, int direction, int turns) {
            this.row = row;
            this.col = col;
            this.direction = direction;
            this.turns = turns;
        }
    }

    /**
     * Efficient input reader for large datasets.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /**
     * Main execution logic.
     */
    public void run() throws IOException {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        String nInput = reader.next();
        if (nInput == null) {
            out.close();
            return;
        }

        int rows = Integer.parseInt(nInput);
        int cols = reader.nextInt();

        char[][] grid = new char[rows][cols];
        int startRow = -1, startCol = -1;
        int targetRow = -1, targetCol = -1;

        // Parse the grid and locate Start (S) and Target (T)
        for (int i = 0; i < rows; i++) {
            String line = reader.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] == 'S') {
                    startRow = i;
                    startCol = j;
                } else if (grid[i][j] == 'T') {
                    targetRow = i;
                    targetCol = j;
                }
            }
        }

        boolean possible = canReachTarget(rows, cols, grid, startRow, startCol, targetRow, targetCol);
        out.println(possible ? "YES" : "NO");
        out.flush();
        out.close();
    }

    /**
     * Uses Breadth-First Search to find if the target is reachable within MAX_TURNS.
     */
    private boolean canReachTarget(int rows, int cols, char[][] grid, 
                                   int startRow, int startCol, 
                                   int targetRow, int targetCol) {

        // visited[turns][direction][row][col]
        // Tracks if we have visited a cell with a specific direction and turn count.
        boolean[][][][] visited = new boolean[MAX_TURNS + 1][4][rows][cols];
        Deque<State> queue = new ArrayDeque<>();

        // Initial states: From S, we can attempt to move in any of the 4 directions.
        // Choosing an initial direction does not count as a turn.
        for (int d = 0; d < 4; d++) {
            visited[0][d][startRow][startCol] = true;
            queue.add(new State(startRow, startCol, d, 0));
        }

        while (!queue.isEmpty()) {
            State current = queue.poll();

            // Target Check
            if (current.row == targetRow && current.col == targetCol) {
                return true;
            }

            // 1. Continue Straight
            int nextRow = current.row + ROW_DIRECTIONS[current.direction];
            int nextCol = current.col + COL_DIRECTIONS[current.direction];

            if (isValid(nextRow, nextCol, rows, cols, grid) && 
                !visited[current.turns][current.direction][nextRow][nextCol]) {

                visited[current.turns][current.direction][nextRow][nextCol] = true;
                queue.add(new State(nextRow, nextCol, current.direction, current.turns));
            }

            // 2. Change Direction (Turn)
            if (current.turns < MAX_TURNS) {
                for (int nextDir = 0; nextDir < 4; nextDir++) {
                    // Skip if it's the same direction (already handled by "Straight" logic)
                    if (nextDir == current.direction) continue;

                    int turnRow = current.row + ROW_DIRECTIONS[nextDir];
                    int turnCol = current.col + COL_DIRECTIONS[nextDir];

                    if (isValid(turnRow, turnCol, rows, cols, grid) && 
                        !visited[current.turns + 1][nextDir][turnRow][turnCol]) {

                        visited[current.turns + 1][nextDir][turnRow][turnCol] = true;
                        queue.add(new State(turnRow, turnCol, nextDir, current.turns + 1));
                    }
                }
            }
        }

        return false;
    }

    /**
     * Validates if a move is within bounds and not an obstacle.
     */
    private boolean isValid(int r, int c, int rows, int cols, char[][] grid) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] != '*';
    }

    public static void main(String[] args) {
        try {
            new Solution().run();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver that determines if a target 'T' is reachable from a starting point 'S'
 * in a 2D grid using straight-line (rook-like) moves, without hitting walls '*'.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            String rowsStr = reader.next();
            String colsStr = reader.next();

            if (rowsStr == null || colsStr == null) {
                return;
            }

            int rows = Integer.parseInt(rowsStr);
            int cols = Integer.parseInt(colsStr);

            if (rows <= 0 || cols <= 0) {
                out.println("NO");
                return;
            }

            char[][] grid = new char[rows][cols];
            int startRow = -1, startCol = -1;
            int targetRow = -1, targetCol = -1;

            // Parse the grid and locate 'S' and 'T'
            for (int i = 0; i < rows; i++) {
                String line = reader.nextLine();
                if (line == null) break;

                for (int j = 0; j < cols; j++) {
                    if (j < line.length()) {
                        grid[i][j] = line.charAt(j);
                    } else {
                        grid[i][j] = ' '; // Padding for incomplete lines
                    }

                    if (grid[i][j] == 'S') {
                        startRow = i;
                        startCol = j;
                    } else if (grid[i][j] == 'T') {
                        targetRow = i;
                        targetCol = j;
                    }
                }
            }

            // Check reachability and output result
            if (startRow != -1 && targetRow != -1 && isReachable(grid, startRow, startCol, targetRow, targetCol)) {
                out.println("YES");
            } else {
                out.println("NO");
            }

        } catch (NumberFormatException e) {
            // Handle potential parsing errors gracefully
        } finally {
            out.close();
        }
    }

    /**
     * Uses Breadth-First Search to find if the target cell is reachable 
     * from the starting cell using rook moves (straight lines).
     *
     * @param grid The 2D character grid.
     * @param startR Starting row coordinate.
     * @param startC Starting column coordinate.
     * @param targetR Target row coordinate.
     * @param targetC Target column coordinate.
     * @return true if target is reachable, false otherwise.
     */
    private static boolean isReachable(char[][] grid, int startR, int startC, int targetR, int targetC) {
        int rows = grid.length;
        int cols = grid[0].length;
        boolean[][] visited = new boolean[rows][cols];
        Queue<int[]> queue = new LinkedList<>();

        queue.add(new int[]{startR, startC});
        visited[startR][startC] = true;

        // Directional vectors for Up, Down, Left, Right
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int r = current[0];
            int c = current[1];

            // If we reached the target, stop searching
            if (r == targetR && c == targetC) {
                return true;
            }

            // Explore in all 4 directions
            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i];
                int nc = c + dc[i];

                // Continue moving in a straight line until hitting a wall or grid boundary
                while (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] != '*') {
                    if (nr == targetR && nc == targetC) {
                        return true;
                    }

                    // If this cell hasn't been visited, add it to queue to explore from its perspective
                    if (!visited[nr][nc]) {
                        visited[nr][nc] = true;
                        queue.add(new int[]{nr, nc});
                    }

                    // Move further in the current direction
                    nr += dr[i];
                    nc += dc[i];
                }
            }
        }

        return false;
    }

    /**
     * Fast I/O utility class for efficient input reading.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public String nextLine() {
            // If there's a remaining part of a line in the tokenizer, consume it first
            if (tokenizer != null && tokenizer.hasMoreElements()) {
                StringBuilder sb = new StringBuilder();
                while (tokenizer.hasMoreElements()) {
                    sb.append(tokenizer.nextToken());
                    if (tokenizer.hasMoreElements()) sb.append(" ");
                }
                tokenizer = null;
                return sb.toString();
            }
            try {
                return reader.readLine();
            } catch (IOException e) {
                return null;
            }
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver for finding the minimum path distance between starting points 'S' 
 * and target points 'T' in a grid with obstacles '*'.
 * Movement rules:
 * - From 'S': Only straight horizontal or vertical lines.
 * - From 'T': At most one 90-degree turn allowed.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        GridSolver solver = new GridSolver();
        solver.solve(reader, out);

        out.close();
    }

    static class GridSolver {
        private static final int INF = 1_000_000_000;
        private static final char START_CHAR = 'S';
        private static final char TARGET_CHAR = 'T';
        private static final char OBSTACLE_CHAR = '*';

        // Cardinal directions: Up, Down, Left, Right
        private final int[] DR = {-1, 1, 0, 0};
        private final int[] DC = {0, 0, -1, 1};

        public void solve(FastReader in, PrintWriter out) {
            int rows = in.nextInt();
            int cols = in.nextInt();
            char[][] grid = new char[rows][cols];
            List<int[]> startPoints = new ArrayList<>();
            List<int[]> targetPoints = new ArrayList<>();

            for (int i = 0; i < rows; i++) {
                String line = in.next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                    if (grid[i][j] == START_CHAR) {
                        startPoints.add(new int[]{i, j});
                    } else if (grid[i][j] == TARGET_CHAR) {
                        targetPoints.add(new int[]{i, j});
                    }
                }
            }

            int[][] distFromStart = new int[rows][cols];
            int[][] distFromTarget = new int[rows][cols];

            initializeDistanceMatrix(distFromStart, rows, cols);
            initializeDistanceMatrix(distFromTarget, rows, cols);

            // Calculate distances based on specific movement constraints
            for (int[] pos : startPoints) {
                computeStraightDistances(grid, pos, distFromStart, rows, cols);
            }
            for (int[] pos : targetPoints) {
                computeOneTurnDistances(grid, pos, distFromTarget, rows, cols);
            }

            long minTotalDistance = findMinPath(distFromStart, distFromTarget, rows, cols);

            if (minTotalDistance >= INF) {
                out.println("NO");
            } else {
                out.println("YES");
            }
        }

        private void initializeDistanceMatrix(int[][] matrix, int rows, int cols) {
            for (int i = 0; i < rows; i++) {
                Arrays.fill(matrix[i], INF);
            }
        }

        /**
         * Calculates distances using only straight lines (no turns).
         */
        private void computeStraightDistances(char[][] grid, int[] start, int[][] dists, int rows, int cols) {
            int r = start[0];
            int c = start[1];
            dists[r][c] = 0;

            for (int d = 0; d < 4; d++) {
                int nr = r + DR[d];
                int nc = c + DC[d];
                int step = 1;
                while (isValid(nr, nc, rows, cols) && grid[nr][nc] != OBSTACLE_CHAR) {
                    if (step < dists[nr][nc]) {
                        dists[nr][nc] = step;
                    }
                    nr += DR[d];
                    nc += DC[d];
                    step++;
                }
            }
        }

        /**
         * Calculates distances allowing at most one 90-degree turn.
         */
        private void computeOneTurnDistances(char[][] grid, int[] start, int[][] dists, int rows, int cols) {
            int r = start[0];
            int c = start[1];
            dists[r][c] = 0;

            for (int d = 0; d < 4; d++) {
                int nr = r + DR[d];
                int nc = c + DC[d];
                int straightSteps = 1;

                while (isValid(nr, nc, rows, cols) && grid[nr][nc] != OBSTACLE_CHAR) {
                    // Case: 0 turns (straight line)
                    if (straightSteps < dists[nr][nc]) {
                        dists[nr][nc] = straightSteps;
                    }

                    // Case: 1 turn (perpendicular movement)
                    // If moving vertically (d < 2), perpendicular is horizontal (d=2,3) and vice-versa
                    int perpStart = (d < 2) ? 2 : 0;
                    for (int pd = perpStart; pd < perpStart + 2; pd++) {
                        int nnr = nr + DR[pd];
                        int nnc = nc + DC[pd];
                        int turnSteps = straightSteps + 1;

                        while (isValid(nnr, nnc, rows, cols) && grid[nnr][nnc] != OBSTACLE_CHAR) {
                            if (turnSteps < dists[nnr][nnc]) {
                                dists[nnr][nnc] = turnSteps;
                            }
                            nnr += DR[pd];
                            nnc += DC[pd];
                            turnSteps++;
                        }
                    }

                    nr += DR[d];
                    nc += DC[d];
                    straightSteps++;
                }
            }
        }

        private long findMinPath(int[][] dists1, int[][] dists2, int rows, int cols) {
            long minVal = INF;
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    // Use long to prevent potential overflow during addition
                    long sum = (long) dists1[i][j] + (long) dists2[i][j];
                    if (sum < minVal) {
                        minVal = sum;
                    }
                }
            }
            return minVal;
        }

        private boolean isValid(int r, int c, int rows, int cols) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * Faster input reading utility.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A refactored solution to find if a target 'T' is reachable from start 'S'
 * in a grid with a maximum of 2 turns, avoiding obstacles '*'.
 */
public class Main {

    public static void main(String[] args) {
        try {
            InputReader reader = new InputReader(System.in);

            int rows = reader.nextInt();
            int cols = reader.nextInt();

            if (rows <= 0 || cols <= 0) {
                System.out.println("NO");
                return;
            }

            char[][] grid = new char[rows][cols];
            int startRow = -1;
            int startCol = -1;

            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                    if (grid[i][j] == 'S') {
                        startRow = i;
                        startCol = j;
                    }
                }
            }

            if (startRow == -1) {
                System.out.println("NO");
                return;
            }

            boolean isPossible = solve(grid, rows, cols, startRow, startCol);
            System.out.println(isPossible ? "YES" : "NO");

        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /**
     * Executes a Breadth-First Search to determine if the target is reachable
     * within the turn constraint.
     *
     * @param grid     The 2D grid character array.
     * @param rows     Number of rows in the grid.
     * @param cols     Number of columns in the grid.
     * @param startR   Starting row index.
     * @param startC   Starting column index.
     * @return true if target 'T' is reachable within 2 turns, false otherwise.
     */
    private static boolean solve(char[][] grid, int rows, int cols, int startR, int startC) {
        // minTurns[r][c][dir] stores the minimum turns to reach (r, c) facing direction 'dir'.
        int[][][] minTurns = new int[rows][cols][Direction.values().length];
        for (int[][] layer : minTurns) {
            for (int[] cell : layer) {
                Arrays.fill(cell, Integer.MAX_VALUE);
            }
        }

        Queue<State> queue = new ArrayDeque<>();

        // Initialize BFS: Starting at 'S', we can face any direction with 0 turns.
        for (Direction dir : Direction.values()) {
            minTurns[startR][startC][dir.ordinal()] = 0;
            queue.add(new State(startR, startC, dir.ordinal(), 0));
        }

        while (!queue.isEmpty()) {
            State current = queue.poll();

            // If we reached the target cell, return true immediately.
            if (grid[current.r][current.c] == 'T') {
                return true;
            }

            // Explore all potential directions for the next move.
            for (Direction nextDir : Direction.values()) {
                int nextR = current.r + nextDir.dr;
                int nextC = current.c + nextDir.dc;

                // A turn is counted if the next direction differs from the current direction.
                int newTurns = current.turns + (nextDir.ordinal() == current.dir ? 0 : 1);

                if (isWithinBounds(nextR, nextC, rows, cols) 
                        && grid[nextR][nextC] != '*' 
                        && newTurns <= 2) {

                    // If this path is more efficient than previously found paths to this cell/direction.
                    if (newTurns < minTurns[nextR][nextC][nextDir.ordinal()]) {
                        minTurns[nextR][nextC][nextDir.ordinal()] = newTurns;
                        queue.add(new State(nextR, nextC, nextDir.ordinal(), newTurns));
                    }
                }
            }
        }

        return false;
    }

    private static boolean isWithinBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Represents possible movement directions in the grid.
     */
    private enum Direction {
        UP(-1, 0), 
        RIGHT(0, 1), 
        DOWN(1, 0), 
        LEFT(0, -1);

        final int dr, dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }
    }

    /**
     * Represents a specific state in the BFS traversal.
     */
    private static class State {
        final int r, c, dir, turns;

        State(int r, int c, int dir, int turns) {
            this.r = r;
            this.c = c;
            this.dir = dir;
            this.turns = turns;
        }
    }

    /**
     * Helper class for high-performance input reading.
     */
    private static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

