/**
 * A solution to determine if a grid containing Start (S), Target (T), 
 * Obstacles (*), and Empty (.) cells has conflicting influence zones 
 * in any row or column.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            GridSolver solver = new GridSolver(reader);
            boolean result = solver.solve();
            // The original logic printed "YES" if a conflict was found.
            // We maintain that specific (though unusual) behavior here.
            writer.println(result ? "YES" : "NO");
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            writer.flush();
            writer.close();
        }
    }
