class GridSolver {
    private static final int OBSTACLE = -2;
    private static final int EMPTY = -1;
    private static final int START_ZONE = 0;
    private static final int TARGET_ZONE = 1;
    private static final int NO_ZONE = -2;

    private final FastReader reader;

    public GridSolver(FastReader reader) {
        this.reader = reader;
    }

    /**
     * Executes the core logic: reads grid, propagates influence, and checks for conflicts.
     * @return true if a conflict was found, false otherwise.
     */
    public boolean solve() {
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        char[][] gridChars = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            gridChars[i] = reader.next().toCharArray();
        }

        int[][] influenceGrid = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            Arrays.fill(influenceGrid[i], EMPTY);
        }

        // Mark obstacles
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (gridChars[i][j] == '*') {
                    influenceGrid[i][j] = OBSTACLE;
                }
            }
        }

        // Propagate influence from S and T cells
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (gridChars[i][j] == 'S' || gridChars[i][j] == 'T') {
                    int type = (gridChars[i][j] == 'T') ? TARGET_ZONE : START_ZONE;
                    propagateInfluence(gridChars, influenceGrid, i, j, type);
                }
            }
        }

        // Check for conflicts in rows and columns
        return hasConflict(influenceGrid, rows, cols);
    }

    /**
     * Spreads the influence of a Start or Target cell in four directions through empty cells.
     */
    private void propagateInfluence(char[][] grid, int[][] influence, int r, int c, int type) {
        int rows = grid.length;
        int cols = grid[0].length;

        influence[r][c] = type;

        // Up
        for (int k = r - 1; k >= 0 && grid[k][c] == '.'; k--) {
            influence[k][c] = type;
        }
        // Down
        for (int k = r + 1; k < rows && grid[k][c] == '.'; k++) {
            influence[k][c] = type;
        }
        // Left
        for (int k = c - 1; k >= 0 && grid[r][k] == '.'; k--) {
            influence[r][k] = type;
        }
        // Right
        for (int k = c + 1; k < cols && grid[r][k] == '.'; k++) {
            influence[r][k] = type;
        }
    }

    /**
     * Checks all rows and columns for a conflict (presence of both Start and Target zones 
     * in the same segment between obstacles).
     */
    private boolean hasConflict(int[][] influence, int rows, int cols) {
        // Check Rows
        for (int i = 0; i < rows; i++) {
            if (isLineConflicting(influence, i, cols, true)) return true;
        }
        // Check Columns
        for (int j = 0; j < cols; j++) {
            if (isLineConflicting(influence, j, rows, false)) return true;
        }
        return false;
    }

    private boolean isLineConflicting(int[][] influence, int index, int length, boolean isRow) {
        int lastZoneSeen = NO_ZONE;

        for (int i = 0; i < length; i++) {
            int currentVal = isRow ? influence[index][i] : influence[i][index];

            if (currentVal == OBSTACLE) {
                lastZoneSeen = NO_ZONE;
            } else if (currentVal == EMPTY) {
                continue;
            } else {
                // currentVal is START_ZONE or TARGET_ZONE
                if (lastZoneSeen != NO_ZONE && lastZoneSeen != currentVal) {
                    return true; // Conflict: different zones found in same segment
                }
                lastZoneSeen = currentVal;
            }
        }
        return false;
    }
}

