            e.printStackTrace();
        }
    }

    /**
     * Solves the task of determining if a connection exists between 'S' and 'T'
     * via straight-line visibility paths.
     */
    static class GridVisibilitySolver {
        private static final int[] ROW_DIRECTIONS = {-1, 0, 1, 0};
        private static final int[] COL_DIRECTIONS = {0, -1, 0, 1};
        private static final char OBSTACLE = '*';
        private static final char START_CHAR = 'S';
        private static final char TARGET_CHAR = 'T';

        /**
         * Orchestrates the solving process.
         */
        public void solve(FastReader in, FastWriter out) throws IOException {
            int rows = in.nextInt();
            int cols = in.nextInt();
            char[][] grid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                grid[i] = in.next().toCharArray();
            }

            // visibilityFromS[r][c] is true if cell (r, c) is in line-of-sight of an 'S'
            boolean[][] visibilityFromS = computeVisibility(grid, rows, cols, START_CHAR);
            // visibilityFromT[r][c] is true if cell (r, c) is in line-of-sight of a 'T'
            boolean[][] visibilityFromT = computeVisibility(grid, rows, cols, TARGET_CHAR);

            if (checkConnectivity(grid, rows, cols, visibilityFromS, visibilityFromT)) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        }

        /**
         * Computes a visibility map for a given character type (e.g., 'S' or 'T').
         */
        private boolean[][] computeVisibility(char[][] grid, int rows, int cols, char target) {
            boolean[][] visibilityMap = new boolean[rows][cols];

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == target) {
                        markVisibleCells(grid, rows, cols, i, j, visibilityMap);
                    }
                }
            }
            return visibilityMap;
        }

        /**
         * Traverses in 4 directions from a point and marks all reachable cells in the map.
         */
        private void markVisibleCells(char[][] grid, int rows, int cols, int startRow, int startCol, boolean[][] map) {
            for (int k = 0; k < 4; k++) {
                int currRow = startRow;
                int currCol = startCol;

                while (isValid(rows, cols, currRow, currCol) && grid[currRow][currCol] != OBSTACLE) {
                    map[currRow][currCol] = true;
                    currRow += ROW_DIRECTIONS[k];
                    currCol += COL_DIRECTIONS[k];
                }
            }
        }

        /**
         * Checks if any cell visible from 'S' can see any cell visible from 'T' in a straight line.
         */
        private boolean checkConnectivity(char[][] grid, int rows, int cols, 
                                          boolean[][] visS, boolean[][] visT) {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (visS[i][j]) {
                        // From a cell visible from S, check if we can see any cell visible from T
                        if (canSeeVisibleTarget(grid, rows, cols, i, j, visT)) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        private boolean canSeeVisibleTarget(char[][] grid, int rows, int cols, int r, int c, boolean[][] visT) {
            for (int k = 0; k < 4; k++) {
                int currRow = r;
                int currCol = c;
                while (isValid(rows, cols, currRow, currCol) && grid[currRow][currCol] != OBSTACLE) {
                    if (visT[currRow][currCol]) {
                        return true;
                    }
                    currRow += ROW_DIRECTIONS[k];
                    currCol += COL_DIRECTIONS[k];
                }
            }
            return false;
        }

        private boolean isValid(int rows, int cols, int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * High-performance input reader for fast I/O.
     */
    static class FastReader implements AutoCloseable {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int pointer = 0;
        private int bytesRead = 0;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() throws IOException {
            if (pointer == bytesRead) {
                pointer = 0;
                bytesRead = stream.read(buffer);
                if (bytesRead <= 0) return -1;
            }
            return buffer[pointer++] & 0xFF;
        }

        public int nextInt() throws IOException {
            int c = read();
            while (c != -1 && isWhitespace(c)) c = read();
            if (c == -1) throw new InputMismatchException();

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int res = 0;
            while (c >= '0' && c <= '9') {
                res = res * 10 + (c - '0');
                c = read();
            }
            return res * sign;
        }

        public String next() throws IOException {
            int c = read();
            while (c != -1 && isWhitespace(c)) c = read();
            if (c == -1) return "";

            StringBuilder sb = new StringBuilder();
            while (c != -1 && !isWhitespace(c)) {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        private boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        @Override
        public void close() throws IOException {
            stream.close();
        }
    }

    /**
     * High-performance output writer for fast I/O.
     */
    static class FastWriter implements AutoCloseable {
        private final PrintWriter writer;

        public FastWriter(OutputStream outputStream) {
            this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i > 0) writer.print(' ');
                writer.print(objects[i]);
            }
        }

        public void println(Object... objects) {
            print(objects);
            writer.println();
        }

        @Override
        public void close() {
            writer.close();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver for finding a path in a maze with a limited number of allowed turns.
 */
public class MazeSolver {

    // Directional vectors for: Down, Right, Up, Left
    private static final int[][] DIRECTIONS = {
        {1, 0}, {0, 1}, {-1, 0}, {0, -1}
    };
    private static final int INITIAL_TURNS = 2;

    private final int rows;
    private final int cols;
    private final char[][] grid;

    private int startRow, startCol;
    private int targetRow, targetCol;

    public MazeSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        findStartAndTarget();
    }

    /**
     * Locates the start ('S') and target ('T') positions in the grid.
     */
    private void findStartAndTarget() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 'S') {
                    startRow = i;
                    startCol = j;
                } else if (grid[i][j] == 'T') {
                    targetRow = i;
                    targetCol = j;
                }
            }
        }
    }

    /**
     * Represents a single state in the BFS traversal.
     */
    private static class State {
        final int r, c, direction, remainingTurns;

        State(int r, int c, int direction, int remainingTurns) {
            this.r = r;
            this.c = c;
            this.direction = direction;
            this.remainingTurns = remainingTurns;
        }
    }

    /**
     * Performs a Breadth-First Search to determine if the target is reachable.
     * 
     * @return true if a valid path exists, false otherwise.
     */
    public boolean solve() {
        // visited[row][col][direction][remainingTurns]
        boolean[][][][] visited = new boolean[rows][cols][4][INITIAL_TURNS + 1];
        Queue<State> queue = new LinkedList<>();

        // Initial movement: Move one step from the starting position in all possible directions
        for (int i = 0; i < 4; i++) {
            int nr = startRow + DIRECTIONS[i][0];
            int nc = startCol + DIRECTIONS[i][1];

            if (isValidMove(nr, nc)) {
                visited[nr][nc][i][INITIAL_TURNS] = true;
                queue.add(new State(nr, nc, i, INITIAL_TURNS));
            }
        }

        while (!queue.isEmpty()) {
            State current = queue.poll();

            if (current.r == targetRow && current.c == targetCol) {
                return true;
            }

            for (int i = 0; i < 4; i++) {
                int nr = current.r + DIRECTIONS[i][0];
                int nc = current.c + DIRECTIONS[i][1];

                if (isValidMove(nr, nc)) {
                    if (i == current.direction) {
                        // Moving in the same direction: turns do not decrease
                        if (!visited[nr][nc][i][current.remainingTurns]) {
                            visited[nr][nc][i][current.remainingTurns] = true;
                            queue.add(new State(nr, nc, i, current.remainingTurns));
                        }
                    } else if (i == (current.direction + 2) % 4) {
                        // Attempting to move in the exact opposite direction: prohibited
                        continue;
                    } else if (current.remainingTurns > 0) {
                        // Turning: consumes one turn
                        int nextTurns = current.remainingTurns - 1;
                        if (!visited[nr][nc][i][nextTurns]) {
                            visited[nr][nc][i][nextTurns] = true;
                            queue.add(new State(nr, nc, i, nextTurns));
                        }
                    }
                }
            }
        }

        return false;
    }

    private boolean isValidMove(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] != '*';
    }

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        int n = reader.nextInt();
        int m = reader.nextInt();
        if (n <= 0 || m <= 0) {
            System.out.println("NO");
            return;
        }

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = reader.next().toCharArray();
        }

        MazeSolver solver = new MazeSolver(n, m, grid);
        if (solver.solve()) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.*;

/**
 * Refactored solution for the "Igor and his way to work" problem.
 * Finds if a path exists from 'S' to 'T' with at most 2 turns (3 straight segments).
 */
public class IgorAndHisWayToWork {

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        try {
            String dimensionsLine = reader.readLine();
            if (dimensionsLine == null) return;

            String[] dimensions = dimensionsLine.split("\\s+");
            int rows = Integer.parseInt(dimensions[0]);
            int cols = Integer.parseInt(dimensions[1]);

            char[][] labyrinth = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                labyrinth[i] = reader.readLine().toCharArray();
            }

            LabyrinthSolver solver = new LabyrinthSolver(rows, cols, labyrinth);
            boolean possible = solver.solve();

            System.out.println(possible ? "YES" : "NO");
        } catch (IOException | NumberFormatException e) {
            System.err.println("Error processing input: " + e.getMessage());
        }
    }

    /**
     * Encapsulates the pathfinding logic.
     */
    static class LabyrinthSolver {
        private final int rows;
        private final int cols;
        private final char[][] grid;

        // Directional movement offsets
        private enum Direction {
            UP(-1, 0), DOWN(1, 0), LEFT(0, -1), RIGHT(0, 1);

            final int dr, dc;

            Direction(int dr, int dc) {
                this.dr = dr;
                this.dc = dc;
            }
        }

        // Represents a state in the BFS
        private static class Node {
            final int r, c, turnsRemaining;

            Node(int r, int c, int turnsRemaining) {
                this.r = r;
                this.c = c;
                this.turnsRemaining = turnsRemaining;
            }
        }

        public LabyrinthSolver(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
        }

        public boolean solve() {
            int startR = -1, startC = -1;

            // Locate starting point 'S'
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == 'S') {
                        startR = i;
                        startC = j;
                        break;
                    }
                }
            }

            if (startR == -1) return false;

            // visited[row][col][turns_remaining]
            // We allow at most 2 turns (3 segments). 
            // We start with 2 turns available to be "used".
            boolean[][][] visited = new boolean[rows][cols][3];
            Queue<Node> queue = new LinkedList<>();

            // Initial state: at 'S' with 2 turns left to use
            queue.add(new Node(startR, startC, 2));
            visited[startR][startC][2] = true;

            while (!queue.isEmpty()) {
                Node current = queue.poll();

                // Try moving in all 4 directions (shooting rays)
                for (Direction dir : Direction.values()) {
                    int nr = current.r + dir.dr;
                    int nc = current.c + dir.dc;

                    // Continue moving in the same direction (straight line)
                    while (isValid(nr, nc) && grid[nr][nc] != '*') {
                        if (grid[nr][nc] == 'T') {
                            return true; // Target found
                        }

                        if (grid[nr][nc] == '.') {
                            // If we land on a '.', we can potentially turn here.
                            // A turn uses up 1 from turnsRemaining.
                            int nextTurns = current.turnsRemaining - 1;
                            if (nextTurns >= 0 && !visited[nr][nc][nextTurns]) {
                                visited[nr][nc][nextTurns] = true;
                                queue.add(new Node(nr, nc, nextTurns));
                            }
                        }

                        // Continue the ray
                        nr += dir.dr;
                        nc += dir.dc;
                    }
                }
            }

            return false;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * Helper class for faster input reading.
     */
    static class FastReader {
        private final BufferedReader reader;

        public FastReader() {
            reader = new BufferedReader(new InputStreamReader(System.in));
        }

        public String readLine() throws IOException {
            return reader.readLine();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver for finding paths in a grid with a limited number of direction changes.
 */
public class Main {
    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        GridPathfinder solver = new GridPathfinder();
        solver.solve(reader, out);

        out.flush();
        out.close();
    }

    static class GridPathfinder {
        private static final int MAX_DIRECTION_CHANGES = 3;
        private static final int NUM_DIRECTIONS = 4;

        // Directions: Right, Left, Down, Up
        private static final int[] COL_OFFSETS = {1, -1, 0, 0};
        private static final int[] ROW_OFFSETS = {0, 0, 1, -1};

        /**
         * Represents a specific state in the BFS traversal.
         * 
         * @param row          Current row index
         * @param col          Current column index
         * @param lastDirection The direction the agent was facing when entering this cell
         * @param changes      Total number of direction changes made so far
         */
        private record State(int row, int col, int lastDirection, int changes) {}

        public void solve(FastReader reader, PrintWriter out) {
            int numRows = reader.nextInt();
            int numCols = reader.nextInt();
            if (numRows <= 0 || numCols <= 0) return;

            char[][] grid = new char[numRows][numCols];
            for (int i = 0; i < numRows; i++) {
                grid[i] = reader.nextRow(numCols);
            }

            // visited[row][col][direction][changes]
            boolean[][][][] visited = new boolean[numRows][numCols][NUM_DIRECTIONS][MAX_DIRECTION_CHANGES];
            Queue<State> queue = new LinkedList<>();

            // Initialize BFS with all starting positions 'S'
            for (int r = 0; r < numRows; r++) {
                for (int c = 0; c < numCols; c++) {
                    if (grid[r][c] == 'S') {
                        // For a starting point, we can face any direction without a "change" cost
                        for (int dir = 0; dir < NUM_DIRECTIONS; dir++) {
                            visited[r][c][dir][0] = true;
                            queue.add(new State(r, c, dir, 0));
                        }
                    }
                }
            }

            // Perform Breadth-First Search
            while (!queue.isEmpty()) {
                State current = queue.poll();

                for (int dir = 0; dir < NUM_DIRECTIONS; dir++) {
                    int nextRow = current.row + ROW_OFFSETS[dir];
                    int nextCol = current.col + COL_OFFSETS[dir];
                    int nextChanges = current.changes + (current.lastDirection == dir ? 0 : 1);

                    if (isValidMove(nextRow, nextCol, nextChanges, numRows, numCols, grid, visited, dir)) {
                        visited[nextRow][nextCol][dir][nextChanges] = true;
                        queue.add(new State(nextRow, nextCol, dir, nextChanges));
                    }
                }
            }

            // Check reachability for all target positions 'T'
            for (int r = 0; r < numRows; r++) {
                for (int c = 0; c < numCols; c++) {
                    if (grid[r][c] == 'T') {
                        out.println(isReachable(r, c, visited) ? "YES" : "NO");
                    }
                }
            }
        }

        private boolean isValidMove(int r, int c, int changes, int rows, int cols, 
                                    char[][] grid, boolean[][][][] visited, int dir) {
            return r >= 0 && r < rows && 
                   c >= 0 && c < cols && 
                   grid[r][c] != '*' && 
                   changes < MAX_DIRECTION_CHANGES && 
                   !visited[r][c][dir][changes];
        }

        private boolean isReachable(int r, int c, boolean[][][][] visited) {
            for (int dir = 0; dir < NUM_DIRECTIONS; dir++) {
                for (int changes = 0; changes < MAX_DIRECTION_CHANGES; changes++) {
                    if (visited[r][c][dir][changes]) {
                        return true;
                    }
                }
            }
            return false;
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        /**
         * Reads a row of characters specifically to handle grid input.
         */
        public char[] nextRow(int expectedLength) {
            String line = next();
            if (line == null) return new char[0];
            char[] row = line.toCharArray();
            // Ensure the row length matches the expected grid width
            if (row.length < expectedLength) {
                return Arrays.copyOf(row, expectedLength);
            }
            return row;
        }
    }
}

