/**
 * Represents a coordinate in the 2D grid.
 */
final class Coordinate {
    final int row;
    final int col;

    Coordinate(int row, int col) {
        this.row = row;
        this.col = col;
    }
}

/**
 * Encapsulates the grid data and boundary logic.
 */
final class Grid {
    private final int rows;
    private final int cols;
    private final char[][] cells;

    Grid(int rows, int cols, char[][] cells) {
        this.rows = rows;
        this.cols = cols;
        this.cells = cells;
    }

    public int getRows() { return rows; }
    public int getCols() { return cols; }
    public char get(int r, int c) { return cells[r][c]; }
    public boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Finds the first occurrence of a specific character in the grid.
     */
    public Coordinate findPoint(char target) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (cells[r][c] == target) {
                    return new Coordinate(r, c);
                }
            }
        }
        return null;
    }
}

/**
 * Logic to solve the path intersection problem.
 */
final class PathFinder {
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    private final Grid grid;

    PathFinder(Grid grid) {
        this.grid = grid;
    }

    /**
     * Executes the core logic to determine if S and T paths intersect.
     */
    public String solve() {
        Coordinate start = grid.findPoint('S');
        Coordinate target = grid.findPoint('T');

        if (start == null || target == null) {
            return "NO";
        }

        boolean[][] routeS = markStraightLinePaths(start);
        boolean[][] routeT = markStraightLinePaths(target);

        if (hasIntersection(routeS, routeT)) {
            return "YES";
        }

        return "NO";
    }

    /**
     * Marks all cells reachable from a given point via straight cardinal lines.
     */
    private boolean[][] markStraightLinePaths(Coordinate start) {
        int rows = grid.getRows();
        int cols = grid.getCols();
        boolean[][] reachable = new boolean[rows][cols];

        reachable[start.row][start.col] = true;

        for (int d = 0; d < 4; d++) {
            int r = start.row + DR[d];
            int c = start.col + DC[d];
            while (grid.isValid(r, c) && grid.get(r, c) != '*') {
                reachable[r][c] = true;
                r += DR[d];
                c += DC[d];
            }
        }
        return reachable;
    }

    /**
     * Checks if any straight-line path from S intersects any straight-line path from T.
     * Optimized to O(Rows * Cols) using segment scanning.
     */
    private boolean hasIntersection(boolean[][] routeS, boolean[][] routeT) {
        int rows = grid.getRows();
        int cols = grid.getCols();

        // Check horizontal intersections
        for (int r = 0; r < rows; r++) {
            boolean hasS = false;
            boolean hasT = false;
            for (int c = 0; c < cols; c++) {
                if (grid.get(r, c) == '*') {
                    hasS = false;
                    hasT = false;
                } else {
                    if (routeS[r][c]) hasS = true;
                    if (routeT[r][c]) hasT = true;
                    if (hasS && hasT) return true;
                }
            }
        }

        // Check vertical intersections
        for (int c = 0; c < cols; c++) {
            boolean hasS = false;
            boolean hasT = false;
            for (int r = 0; r < rows; r++) {
                if (grid.get(r, c) == '*') {
                    hasS = false;
                    hasT = false;
                } else {
                    if (routeS[r][c]) hasS = true;
                    if (routeT[r][c]) hasT = true;
                    if (hasS && hasT) return true;
                }
            }
        }

        return false;
    }
}

/**
 * Utility class for high-performance input reading.
 */
final class FastScanner {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    public FastScanner(InputStream stream) {
