import java.io.*;
import java.util.*;

/**
 * A solution to determine if two points (S and T) in a grid can "see" each other
 * either directly or via a shared visibility segment.
 */
public class Main {

    public static void main(String[] args) {
        new Runner().run();
    }

    private static class Runner {
        void run() {
            try (FastReader reader = new FastReader(System.in);
                 PrintWriter out = new PrintWriter(System.out)) {

                int n = reader.nextInt();
                int m = reader.nextInt();
                char[][] matrix = reader.readGrid(n, m);

                Grid grid = new Grid(matrix, n, m);
                Solver solver = new Solver(grid);

                out.println(solver.solve() ? "YES" : "NO");

            } catch (Exception e) {
                e.printStackTrace();
            }
        }
    }

    /**
     * Represents a coordinate in the grid.
     */
    private record Point(int x, int y) {}

    /**
     * Encapsulates the grid data and basic spatial queries.
     */
    private static class Grid {
        private final char[][] cells;
        private final int rows;
        private final int cols;
        private Point startPos;
        private Point targetPos;

        Grid(char[][] cells, int rows, int cols) {
            this.cells = cells;
            this.rows = rows;
            this.cols = cols;
            findSpecialPoints();
        }

        private void findSpecialPoints() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (cells[i][j] == 'S') {
                        startPos = new Point(i, j);
                    } else if (cells[i][j] == 'T') {
                        targetPos = new Point(i, j);
                    }
                }
            }
        }

        public boolean isObstacle(int r, int c) {
            return cells[r][c] == '*';
        }

        public boolean isInBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        /**
         * Returns all cells reachable from a point in a straight line 
         * (up, down, left, right) until an obstacle or boundary is hit.
         */
        public Set<Point> getReachableCells(Point origin) {
            Set<Point> reachable = new HashSet<>();
            if (origin == null) return reachable;

            reachable.add(origin);
            int[] dx = {0, 0, 1, -1};
            int[] dy = {1, -1, 0, 0};

            for (int i = 0; i < 4; i++) {
                int nx = origin.x + dx[i];
                int ny = origin.y + dy[i];
                while (isInBounds(nx, ny) && !isObstacle(nx, ny)) {
                    reachable.add(new Point(nx, ny));
                    nx += dx[i];
                    ny += dy[i];
                }
            }
            return reachable;
        }

        /**
         * Checks if the path between two points in the same row or column is unobstructed.
         */
        public boolean isPathClear(int r1, int c1, int r2, int c2) {
            int minR = Math.min(r1, r2);
            int maxR = Math.max(r1, r2);
            int minC = Math.min(c1, c2);
            int maxC = Math.max(c1, c2);

            if (r1 == r2) { // Horizontal check
                for (int j = minC + 1; j < maxC; j++) {
                    if (isObstacle(r1, j)) return false;
                }
            } else { // Vertical check
                for (int i = minR + 1; i < maxR; i++) {
                    if (isObstacle(i, c1)) return false;
                }
            }
            return true;
        }

        public int getRows() { return rows; }
        public int getCols() { return cols; }
        public Point getStartPos() { return startPos; }
        public Point getTargetPos() { return targetPos; }
    }

    /**
     * Contains the core logic to solve the problem.
     */
    private static class Solver {
        private final Grid grid;

        Solver(Grid grid) {
            this.grid = grid;
        }

        public boolean solve() {
            Point s = grid.getStartPos();
            Point t = grid.getTargetPos();

            Set<Point> reachableFromS = grid.getReachableCells(s);
            Set<Point> reachableFromT = grid.getReachableCells(t);

            // 1. Direct Intersection: Do S and T's lines of sight intersect?
            for (Point p : reachableFromS) {
                if (reachableFromT.contains(p)) return true;
            }

            // 2. Indirect Intersection: Check rows (excluding S and T rows)
            for (int i = 0; i < grid.getRows(); i++) {
                if (i == s.x || i == t.x) continue;

                // Check if an S-reachable cell and a T-reachable cell exist in this row
                // and if they have a clear line of sight between them.
                if (grid.isInBounds(i, s.y) && grid.isInBounds(i, t.y)) {
                    if (reachableFromS.contains(new Point(i, s.y)) && 
                        reachableFromT.contains(new Point(i, t.y))) {
                        if (grid.isPathClear(i, s.y, i, t.y)) return true;
                    }
                }
            }

            // 3. Indirect Intersection: Check columns (excluding S and T columns)
            for (int j = 0; j < grid.getCols(); j++) {
                if (j == s.y || j == t.y) continue;

                if (grid.isInBounds(s.x, j) && grid.isInBounds(t.x, j)) {
                    if (reachableFromS.contains(new Point(s.x, j)) && 
                        reachableFromT.contains(new Point(t.x, j))) {
                        if (grid.isPathClear(s.x, j, t.x, j)) return true;
                    }
                }
            }

            return false;
        }
    }

    /**
     * Optimized reader for fast I/O operations.
     */
    private static class FastReader implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastReader(InputStream is) {
            this.reader = new BufferedReader(new InputStreamReader(is));
        }

        String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        char[][] readGrid(int n, int m) throws IOException {
            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                String line = next();
                for (int j = 0; j < m; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }
            return grid;
        }

        @Override
        public void close() throws IOException {
            reader.close();
        }
    }
}

