/**
 * Solves the maze pathfinding problem using a Dijkstra-based approach 
 * to minimize direction changes (turns).
 */
class MazeSolver {
    // Directional offsets: Right, Left, Down, Up
    private static final int[] ROW_OFFSETS = {0, 0, 1, -1};
    private static final int[] COL_OFFSETS = {1, -1, 0, 0};

    // Maximum allowed direction changes (turns) based on original logic
    private static final int MAX_TURNS = 2;

    /**
     * Represents a state in the search space.
     */
    private static final class State {
        private final int row;
        private final int col;
        private final int direction;
        private final int turnCount;

        public State(int row, int col, int direction, int turnCount) {
            this.row = row;
            this.col = col;
            this.direction = direction;
            this.turnCount = turnCount;
        }

        public int getRow() { return row; }
        public int getCol() { return col; }
        public int getDirection() { return direction; }
        public int getTurnCount() { return turnCount; }
    }

    public void solve(FastReader reader, FastWriter writer) throws IOException {
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        char[][] grid = new char[rows][cols];
        PriorityQueue<State> priorityQueue = new PriorityQueue<>(Comparator.comparingInt(State::getTurnCount));
        boolean[][] visited = new boolean[rows][cols];

        for (int i = 0; i < rows; i++) {
            String line = reader.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] == 'S') {
                    // Starting state: direction -1 and turnCount -1 to allow the first move to count as 0 turns
                    priorityQueue.offer(new State(i, j, -1, -1));
                }
            }
        }

        while (!priorityQueue.isEmpty()) {
            State current = priorityQueue.poll();

            if (visited[current.getRow()][current.getCol()]) {
                continue;
            }
            visited[current.getRow()][current.getCol()] = true;

            // Check if target is reached
            if (grid[current.getRow()][current.getCol()] == 'T') {
                writer.print("YES");
                return;
            }

            exploreNeighbors(current, grid, visited, priorityQueue, rows, cols);
        }

        writer.print("NO");
    }

    private void exploreNeighbors(State current, char[][] grid, boolean[][] visited, 
                                  PriorityQueue<State> pq, int rows, int cols) {
        for (int i = 0; i < 4; i++) {
            int nextRow = current.getRow() + ROW_OFFSETS[i];
            int nextCol = current.getCol() + COL_OFFSETS[i];

            if (isWithinBounds(nextRow, nextCol, rows, cols) && 
                grid[nextRow][nextCol] != '*' && 
                !visited[nextRow][nextCol]) {

                if (current.getDirection() == i) {
                    // Moving in the same direction: turn count remains the same
                    pq.offer(new State(nextRow, nextCol, i, current.getTurnCount()));
                } else if (current.getTurnCount() < MAX_TURNS) {
                    // Changing direction: increment turn count if limit not reached
                    pq.offer(new State(nextRow, nextCol, i, current.getTurnCount() + 1));
                }
            }
        }
    }

    private boolean isWithinBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

