import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * MazeSolver determines if a target 'T' can be reached from a starting position 'S'
 * in a grid containing obstacles '*', allowing for at most one turn (straight lines).
 */
public class MazeSolver {

    /**
     * Represents a 2D coordinate in the grid.
     */
    private static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            boolean[][] obstacles = new boolean[rows][cols];
            Point startPosition = null;
            Point targetPosition = null;

            // Parse the grid and identify key positions
            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                for (int j = 0; j < cols; j++) {
                    char cell = line.charAt(j);
                    if (cell == 'S') {
                        startPosition = new Point(i, j);
                    } else if (cell == 'T') {
                        targetPosition = new Point(i, j);
                    } else if (cell == '*') {
                        obstacles[i][j] = true;
                    }
                }
            }

            if (canReachTarget(rows, cols, obstacles, startPosition, targetPosition)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }

        } catch (Exception e) {
            // In a production environment, use a proper logging framework
            e.printStackTrace();
        }
    }

    /**
     * Core logic to determine if S and T can see each other or share a common line of sight.
     */
    private static boolean canReachTarget(int rows, int cols, boolean[][] obstacles, 
                                          Point start, Point target) {
        if (start == null || target == null) {
            return false;
        }

        // Map out all cells reachable from the start in straight lines
        boolean[][] reachableFromStart = getReachableCells(start, rows, cols, obstacles);

        // Map out all cells reachable from the target in straight lines
        boolean[][] reachableFromTarget = getReachableCells(target, rows, cols, obstacles);

        // If there is any cell reachable by both S and T, a path exists (direct or one turn)
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (reachableFromStart[i][j] && reachableFromTarget[i][j]) {
                    return true;
                }
            }
        }

        return false;
    }

    /**
     * Calculates all cells reachable from a given point via straight lines 
     * until an obstacle or grid boundary is hit.
     */
    private static boolean[][] getReachableCells(Point origin, int rows, int cols, boolean[][] obstacles) {
        boolean[][] reachable = new boolean[rows][cols];
        int[][] directions = {
            {0, 1},  // Right
            {0, -1}, // Left
            {1, 0},  // Down
            {-1, 0}  // Up
        };

        // The origin itself is considered reachable
        reachable[origin.row][origin.col] = true;

        for (int[] dir : directions) {
            int currentRow = origin.row + dir[0];
            int currentCol = origin.col + dir[1];

            while (isWithinBounds(currentRow, currentCol, rows, cols) && !obstacles[currentRow][currentCol]) {
                reachable[currentRow][currentCol] = true;
                currentRow += dir[0];
                currentCol += dir[1];
            }
        }

        return reachable;
    }

    private static boolean isWithinBounds(int r, int c, int maxR, int maxC) {
        return r >= 0 && r < maxR && c >= 0 && c < maxC;
    }

    /**
     * Fast I/O utility for efficient reading of large inputs.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

/**
 * The Pathfinder class determines if a target cell 'T' can be reached from a start cell 'S'
 * by moving in a straight line in one of the four cardinal directions without hitting a wall.
 */
public class Pathfinder {

    /**
     * Represents the possible types of cells within the grid.
     */
    private enum CellType {
        EMPTY,
        WALL,
        TARGET,
        START
    }

    /**
     * Represents the four cardinal directions and their coordinate offsets.
     */
    private enum Direction {
        DOWN(1, 0),
        RIGHT(0, 1),
        UP(-1, 0),
        LEFT(0, -1);

        private final int deltaRow;
        private final int deltaCol;

        Direction(int deltaRow, int deltaCol) {
            this.deltaRow = deltaRow;
            this.deltaCol = deltaCol;
        }
    }

    private final int rows;
    private final int cols;
    private final CellType[][] grid;
    private final boolean[][][] visited;

    /**
     * Initializes the Pathfinder with a grid of characters.
     *
     * @param rows     Number of rows in the grid.
     * @param cols     Number of columns in the grid.
     * @param gridData Array of strings representing the grid rows.
     */
    public Pathfinder(int rows, int cols, String[] gridData) {
        this.rows = rows;
        this.cols = cols;
        this.grid = new CellType[rows][cols];
        this.visited = new boolean[rows][cols][Direction.values().length];
        initializeGrid(gridData);
    }

    private void initializeGrid(String[] gridData) {
        for (int r = 0; r < rows; r++) {
            String line = gridData[r];
            for (int c = 0; c < cols; c++) {
                grid[r][c] = mapCharToCellType(line.charAt(c));
            }
        }
    }

    private CellType mapCharToCellType(char c) {
        switch (c) {
            case '.': return CellType.EMPTY;
            case '*': return CellType.WALL;
            case 'T': return CellType.TARGET;
            case 'S': return CellType.START;
            default:  return CellType.EMPTY;
        }
    }

    /**
     * Attempts to find a path from the starting position to any target cell.
     *
     * @return true if a straight-line path exists, false otherwise.
     */
    public boolean canFindPath() {
        int startRow = -1;
        int startCol = -1;

        // Locate the starting position 'S'
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == CellType.START) {
                    startRow = r;
                    startCol = c;
                    break;
                }
            }
            if (startRow != -1) break;
        }

        if (startRow == -1) {
            return false;
        }

        // Explore starting in each of the four directions
        for (Direction dir : Direction.values()) {
            if (explore(startRow, startCol, dir)) {
                return true;
            }
        }

        return false;
    }

    /**
     * A recursive depth-first search that explores the grid in a single direction.
     *
     * @param r     Current row index.
     * @param c     Current column index.
     * @param dir   The direction of movement.
     * @return true if the target is found in this path.
     */
    private boolean explore(int r, int c, Direction dir) {
        // 1. Boundary checks
        if (r < 0 || r >= rows || c < 0 || c >= cols) {
            return false;
        }

        // 2. Obstacle check
        if (grid[r][c] == CellType.WALL) {
            return false;
        }

        // 3. Memoization to prevent redundant processing
        if (visited[r][c][dir.ordinal()]) {
            return false;
        }
        visited[r][c][dir.ordinal()] = true;

        // 4. Success condition: target found
        if (grid[r][c] == CellType.TARGET) {
            return true;
        }

        // 5. Continue movement in the same direction
        return explore(r + dir.deltaRow, c + dir.deltaCol, dir);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int n = scanner.nextInt();
        int m = scanner.nextInt();

        String[] gridLines = new String[n];
        for (int i = 0; i < n; i++) {
            gridLines[i] = scanner.next();
        }

        Pathfinder pathfinder = new Pathfinder(n, m, gridLines);

        if (pathfinder.canFindPath()) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }
}

import java.io.*;
import java.util.*;

/**
 * A solution to find if a target can be reached within a maximum number of turns.
 * Uses a 0-1 BFS algorithm (via Deque) to find the shortest path in terms of direction changes.
 */
public class Main {

    public static void main(String[] args) {
        try (FastReader in = new FastReader(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            PathfinderSolver solver = new PathfinderSolver();
            solver.solve(in, out);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    static class PathfinderSolver {
        private static final int MAX_ALLOWED_TURNS = 2;

        public void solve(FastReader in, PrintWriter out) throws IOException {
            int rows = in.nextInt();
            int cols = in.nextInt();

            Grid grid = new Grid(in.nextCharacterMap(rows, cols));
            if (grid.getStart() == null || grid.getTarget() == null) {
                out.println("NO");
                return;
            }

            boolean reachable = canReachTarget(grid, MAX_ALLOWED_TURNS);
            out.println(reachable ? "YES" : "NO");
        }

        private boolean canReachTarget(Grid grid, int maxTurns) {
            int n = grid.getRows();
            int m = grid.getCols();

            // Directions: Down, Right, Up, Left
            int[] dr = {1, 0, -1, 0};
            int[] dc = {0, 1, 0, -1};

            // dist[direction][row][col] stores the minimum turns to reach (row, col) facing 'direction'
            int[][][] minTurns = new int[4][n][m];
            for (int i = 0; i < 4; i++) {
                for (int r = 0; r < n; r++) {
                    Arrays.fill(minTurns[i][r], Integer.MAX_VALUE);
                }
            }

            Deque<State> deque = new ArrayDeque<>();
            Point start = grid.getStart();

            // Initialize: Starting at 'S' allows moving in any initial direction with 0 turns
            for (int d = 0; d < 4; d++) {
                minTurns[d][start.row][start.col] = 0;
                deque.addLast(new State(start.row, start.col, d));
            }

            while (!deque.isEmpty()) {
                State current = deque.pollFirst();
                int r = current.row;
                int c = current.col;
                int dir = current.direction;

                // If we reached the target
                if (grid.isTarget(r, c)) {
                    if (minTurns[dir][r][c] <= maxTurns) {
                        return true;
                    }
                }

                for (int k = 0; k < 4; k++) {
                    int nr = r + dr[k];
                    int nc = c + dc[k];

                    // Check boundaries and if the cell is walkable
                    if (grid.isValidMove(nr, nc)) {
                        int cost = (k == dir) ? 0 : 1;
                        int newTurns = minTurns[dir][r][c] + cost;

                        if (newTurns < minTurns[k][nr][nc]) {
                            minTurns[k][nr][nc] = newTurns;

                            // 0-1 BFS logic: 0-weight edges go to front, 1-weight edges to back
                            if (cost == 0) {
                                deque.addFirst(new State(nr, nc, k));
                            } else {
                                deque.addLast(new State(nr, nc, k));
                            }
                        }
                    }
                }
            }

            return false;
        }
    }

    /**
     * Represents a coordinate in the grid.
     */
    static class Point {
        final int row, col;
        Point(int r, int c) { this.row = r; this.col = c; }
    }

    /**
     * Represents the state in the BFS queue.
     */
    static class State {
        final int row, col, direction;
        State(int r, int c, int d) {
            this.row = r;
            this.col = c;
            this.direction = d;
        }
    }

    /**
     * Handles the grid data and spatial queries.
     */
    static class Grid {
        private final char[][] map;
        private final int rows;
        private final int cols;
        private Point start;
        private Point target;

        Grid(char[][] map) {
            this.map = map;
            this.rows = map.length;
            this.cols = map[0].length;
            findSpecialPoints();
        }

        private void findSpecialPoints() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (map[i][j] == 'S') {
                        start = new Point(i, j);
                    } else if (map[i][j] == 'T') {
                        target = new Point(i, j);
                    }
                }
            }
        }

        public boolean isValidMove(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols && (map[r][c] == '.' || map[r][c] == 'T');
        }

        public boolean isTarget(int r, int c) {
            return target != null && r == target.row && c == target.col;
        }

        public int getRows() { return rows; }
        public int getCols() { return cols; }
        public Point getStart() { return start; }
        public Point getTarget() { return target; }
    }

    /**
     * High-performance input reader.
     */
    static class FastReader implements AutoCloseable {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int curChar;
        private int numChars;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() throws IOException {
            if (numChars == -1) throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                numChars = stream.read(buffer);
                if (numChars <= 0) return -1;
            }
            return buffer[curChar++];
        }

        public int nextInt() throws IOException {
            int c = read();
            while (isSpaceChar(c)) c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c == ',') c = read(); // Handle comma-separated input
                if (c < '0' || c > '9') throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public char[][] nextCharacterMap(int n, int m) throws IOException {
            char[][] map = new char[n][m];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    map[i][j] = nextChar();
                }
            }
            return map;
        }

        private char nextChar() throws IOException {
            int c = read();
            while (isSpaceChar(c)) c = read();
            return (char) c;
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        @Override
        public void close() throws IOException {
            stream.close();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to determine if a target 'T' can be reached from a start 'S' 
 * on a grid with a limited number of direction changes (turns).
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            char[][] gridData = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                gridData[i] = reader.next().toCharArray();
            }

            Grid grid = new Grid(gridData);
            Pathfinder pathfinder = new Pathfinder(grid);

            // The threshold of turns allowed is 2
            boolean reachable = pathfinder.canReachTargetWithinTurns(2);

            out.println(reachable ? "YES" : "NO");
        } catch (Exception e) {
            // In a real production environment, use a proper logger
            e.printStackTrace();
        } finally {
            out.close();
        }
    }

    /**
     * Represents the movement directions on the grid.
     */
    enum Direction {
        NORTH(-1, 0), SOUTH(1, 0), EAST(0, 1), WEST(0, -1);

        final int rowDelta;
        final int colDelta;

        Direction(int rowDelta, int colDelta) {
            this.rowDelta = rowDelta;
            this.colDelta = colDelta;
        }

        public static Direction fromOrdinal(int ordinal) {
            return values()[ordinal];
        }
    }

    /**
     * A coordinate on the grid.
     */
    record Point(int row, int col) {}

    /**
     * The state in our BFS: current position and the direction we arrived from.
     */
    record State(int row, int col, Direction direction) {}

    /**
     * Encapsulates the grid data and provides boundary/obstacle checks.
     */
    static class Grid {
        private final char[][] data;
        private final int rows;
        private final int cols;
        private Point start;
        private Point end;

        private static final char START_CHAR = 'S';
        private static final char END_CHAR = 'T';
        private static final char BLOCK_CHAR = '*';

        public Grid(char[][] data) {
            this.data = data;
            this.rows = data.length;
            this.cols = data[0].length;
            findSpecialPoints();
        }

        private void findSpecialPoints() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (data[r][c] == START_CHAR) {
                        start = new Point(r, c);
                    } else if (data[r][c] == END_CHAR) {
                        end = new Point(r, c);
                    }
                }
            }
        }

        public boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols && data[r][c] != BLOCK_CHAR;
        }

        public Point getStart() { return start; }
        public Point getEnd() { return end; }
        public int getRows() { return rows; }
        public int getCols() { return cols; }
    }

    /**
     * Implements the pathfinding logic using 0-1 BFS.
     */
    static class Pathfinder {
        private final Grid grid;
        private static final int INF = Integer.MAX_VALUE;

        public Pathfinder(Grid grid) {
            this.grid = grid;
        }

        /**
         * Uses 0-1 BFS to find the minimum direction changes required.
         * A 0-1 BFS is used because moving straight has cost 0, and turning has cost 1.
         */
        public boolean canReachTargetWithinTurns(int maxTurns) {
            Point start = grid.getStart();
            Point end = grid.getEnd();

            if (start == null || end == null) return false;

            // minTurns[row][col][direction_ordinal]
            int[][][] minTurns = new int[grid.getRows()][grid.getCols()][Direction.values().length];
            for (int[][] row : minTurns) {
                for (int[] cell : row) {
                    Arrays.fill(cell, INF);
                }
            }

            Deque<State> deque = new ArrayDeque<>();

            // Initialization: From start, we can pick any direction with 0 turns.
            for (Direction d : Direction.values()) {
                minTurns[start.row()][start.col()][d.ordinal()] = 0;
                deque.addFirst(new State(start.row(), start.col(), d));
            }

            while (!deque.isEmpty()) {
                State curr = deque.removeFirst();
                int r = curr.row();
                int c = curr.col();
                Direction d = curr.direction();
                int currentCost = minTurns[r][c][d.ordinal()];

                if (currentCost > maxTurns) continue;
                if (r == end.row() && c == end.col()) return true;

                // Option 1: Continue in the same direction (Cost 0)
                int nr = r + d.rowDelta;
                int nc = c + d.colDelta;
                if (grid.isValid(nr, nc) && minTurns[nr][nc][d.ordinal()] > currentCost) {
                    minTurns[nr][nc][d.ordinal()] = currentCost;
                    deque.addFirst(new State(nr, nc, d));
                }

                // Option 2: Turn to a different direction (Cost 1)
                for (Direction nextDir : Direction.values()) {
                    if (nextDir == d) continue;

                    int tr = r + nextDir.rowDelta;
                    int tc = c + nextDir.colDelta;

                    if (grid.isValid(tr, tc) && minTurns[tr][tc][nextDir.ordinal()] > currentCost + 1) {
                        minTurns[tr][tc][nextDir.ordinal()] = currentCost + 1;
                        deque.addLast(new State(tr, tc, nextDir));
                    }
                }
            }

            return false;
        }
    }

    /**
     * Fast I/O utility.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

/**
 * A solution to a grid-based propagation problem.
 * The program determines if a "power" can reach a target "Home" (S) 
 * starting from an "Office" (T) or through intermediate power levels.
 */
public class Solution {
    // Cell Type Constants
    private static final int CELL_OFFICE = 0;
    private static final int CELL_PATH_OR_HOME = 4;
    private static final int CELL_OBSTACLE = -1;

    // Power Level Constants
    private static final int POWER_LEVEL_1 = 1;
    private static final int POWER_LEVEL_2 = 2;

    // Cardinal directions for ray-casting: Down, Up, Right, Left
    private static final int[][] DIRECTIONS = {
        {1, 0}, {-1, 0}, {0, 1}, {0, -1}
    };

    private final int rows;
    private final int cols;
    private final int[][] grid;
    private int homeRow;
    private int homeCol;
    private int officeRow;
    private int officeCol;

    /**
     * Initializes the solver with grid dimensions and state.
     */
    public Solution(int rows, int cols, int[][] grid, int homeRow, int homeCol, int officeRow, int officeCol) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.homeRow = homeRow;
        this.homeCol = homeCol;
        this.officeRow = officeRow;
        this.officeCol = officeCol;
    }

    /**
     * Orchestrates the propagation phases to find if the home is reachable.
     * 
     * @return "YES" if the home is reached, "NO" otherwise.
     */
    public String solve() {
        // Phase 1: Attempt propagation starting from the Office
        if (spreadPower(officeRow, officeCol)) {
            return "YES";
        }

        // Phase 2: Attempt propagation from all cells that were marked with Power Level 1
        if (tryPropagationFromLevel(POWER_LEVEL_1)) {
            return "YES";
        }

        // Phase 3: Attempt propagation from all cells that were marked with Power Level 2
        if (tryPropagationFromLevel(POWER_LEVEL_2)) {
            return "YES";
        }

        return "NO";
    }

    /**
     * Scans the grid for all cells containing a specific power level and attempts to spread from them.
     */
    private boolean tryPropagationFromLevel(int level) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == level) {
                    if (spreadPower(r, c)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Casts a "beam" in four cardinal directions from the starting point.
     * The beam continues through cells as long as they meet the power threshold.
     *
     * @param startRow The starting row of the beam
     * @param startCol The starting column of the beam
     * @return true if the beam hits the home coordinates, false otherwise.
     */
    private boolean spreadPower(int startRow, int startCol) {
        int newPower = grid[startRow][startCol] + 1;

        for (int[] dir : DIRECTIONS) {
            int r = startRow + dir[0];
            int c = startCol + dir[1];

            // Continue moving in the direction while within bounds and power is sufficient
            while (isWithinBounds(r, c) && grid[r][c] >= newPower) {
                if (r == homeRow && c == homeCol) {
                    return true;
                }
                // Mark the cell with the new power level
                grid[r][c] = newPower;
                r += dir[0];
                c += dir[1];
            }
        }
        return false;
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Entry point: Handles input parsing and triggers the solver.
     */
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int m = scanner.nextInt();
        int n = scanner.nextInt();
        scanner.nextLine(); // Consume the newline character

        int[][] grid = new int[m][n];
        int hR = -1, hC = -1, oR = -1, oC = -1;

        for (int i = 0; i < m; i++) {
            if (!scanner.hasNextLine()) break;
            String line = scanner.nextLine();
            for (int j = 0; j < n; j++) {
                char character = line.charAt(j);
                if (character == 'T') {
                    grid[i][j] = CELL_OFFICE;
                    oR = i;
                    oC = j;
                } else if (character == 'S') {
                    grid[i][j] = CELL_PATH_OR_HOME;
                    hR = i;
                    hC = j;
                } else if (character == '.') {
                    grid[i][j] = CELL_PATH_OR_HOME;
                } else {
                    grid[i][j] = CELL_OBSTACLE;
                }
            }
        }

        Solution solution = new Solution(m, n, grid, hR, hC, oR, oC);
        System.out.print(solution.solve());

        scanner.close();
    }
}

import java.io.*;
import java.util.*;

/**
 * A refactored implementation of a grid-based pathfinding algorithm.
 * The goal is to determine if a target 'T' is reachable from a starting point 'S'
 * while allowing a maximum of two direction changes (turns).
 */
public class Main {

    // Directions: 0: Up, 1: Left, 2: Down, 3: Right
    private static final int[] DR = {-1, 0, 1, 0};
    private static final int[] DC = {0, -1, 0, 1};

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        Solver solver = new Solver(reader);
        solver.solve();
    }

    /**
     * Logic controller for the problem.
     */
    static class Solver {
        private final FastReader reader;

        Solver(FastReader reader) {
            this.reader = reader;
        }

        /**
         * Reads the input and initiates the search.
         */
        public void solve() {
            String firstLine = reader.readLine();
            if (firstLine == null || firstLine.trim().isEmpty()) {
                return;
            }

            StringTokenizer st = new StringTokenizer(firstLine);
            if (!st.hasMoreTokens()) return;

            int rows = Integer.parseInt(st.nextToken());
            int cols = Integer.parseInt(st.nextToken());

            char[][] map = new char[rows][cols];
            int startR = -1, startC = -1;

            for (int i = 0; i < rows; i++) {
                String line = reader.readLine();
                if (line == null) break;
                map[i] = line.toCharArray();
                for (int j = 0; j < cols; j++) {
                    if (map[i][j] == 'S') {
                        startR = i;
                        startC = j;
                    }
                }
            }

            if (startR == -1) {
                System.out.println("NO");
                return;
            }

            if (canReachTarget(map, rows, cols, startR, startC)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }

        /**
         * Performs a Breadth-First Search to find if the target is reachable.
         * 
         * @param map The grid map.
         * @param rows Number of rows.
         * @param cols Number of columns.
         * @param startR Starting row index.
         * @param startC Starting column index.
         * @return true if 'T' is reachable with <= 2 turns, false otherwise.
         */
        private boolean canReachTarget(char[][] map, int rows, int cols, int startR, int startC) {
            // visited[row][col][direction][turns]
            // Turns allowed: 0, 1, or 2.
            boolean[][][][] visited = new boolean[rows][cols][4][3];
            Deque<State> queue = new ArrayDeque<>();

            // Edge case: check if start is already target
            if (map[startR][startC] == 'T') {
                return true;
            }

            // Initial expansion: the first move from the starting cell sets the initial direction 
            // and doesn't count as a turn (turns = 0).
            for (int d = 0; d < 4; d++) {
                int nr = startR + DR[d];
                int nc = startC + DC[d];

                if (isValid(nr, nc, rows, cols, map)) {
                    if (!visited[nr][nc][d][0]) {
                        visited[nr][nc][d][0] = true;
                        queue.add(new State(nr, nc, d, 0));
                    }
                }
            }

            while (!queue.isEmpty()) {
                State curr = queue.poll();

                if (map[curr.r][curr.c] == 'T') {
                    return true;
                }

                for (int e = 0; e < 4; e++) {
                    int nr = curr.r + DR[e];
                    int nc = curr.c + DC[e];

                    if (isValid(nr, nc, rows, cols, map)) {
                        // If the new direction is different from current direction, it's a turn.
                        int nextTurns = (e == curr.dir) ? curr.turns : curr.turns + 1;

                        // Constraints:
                        // 1. Maximum of 2 turns allowed.
                        // 2. If we have already made 2 turns, we cannot turn again.
                        if (nextTurns <= 2) {
                            if (curr.turns == 2 && e != curr.dir) {
                                continue;
                            }

                            if (!visited[nr][nc][e][nextTurns]) {
                                visited[nr][nc][e][nextTurns] = true;
                                queue.add(new State(nr, nc, e, nextTurns));
                            }
                        }
                    }
                }
            }

            return false;
        }

        private boolean isValid(int r, int c, int rows, int cols, char[][] map) {
            return r >= 0 && r < rows && c >= 0 && c < cols && map[r][c] != '*';
        }
    }

    /**
     * Represents a state in the BFS.
     */
    static class State {
        final int r, c, dir, turns;

        State(int r, int c, int dir, int turns) {
            this.r = r;
            this.c = c;
            this.dir = dir;
            this.turns = turns;
        }
    }

    /**
     * Utility for efficient input reading.
     */
    static class FastReader {
        private final BufferedReader br;

        public FastReader(InputStream in) {
            this.br = new BufferedReader(new InputStreamReader(in));
        }

        public String readLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                return null;
            }
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A professional implementation of a grid-based pathfinding problem.
 * The goal is to determine if a source 'S' can reach a target 'T' 
 * by moving in straight lines, changing direction only at empty '.' cells.
 */
public class GridPathfinder {

    private static final int[][] DIRECTIONS = {
        {0, 1}, {0, -1}, {1, 0}, {-1, 0}
    };

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private int startRow, startCol, targetRow, targetCol;

    public GridPathfinder(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        findSpecialPoints();
    }

    private void findSpecialPoints() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 'S') {
                    startRow = r;
                    startCol = c;
                } else if (grid[r][c] == 'T') {
                    targetRow = r;
                    targetCol = c;
                }
            }
        }
    }

    /**
     * Executes the pathfinding logic.
     * @return true if the target is reachable, false otherwise.
     */
    public boolean canReachTarget() {
        // 1. Pre-calculate cells that are on a direct line-of-sight from the target.
        boolean[][] targetLines = computeLineOfSight(targetRow, targetCol, '.', 'T');

        // 2. Check if the source can see the target directly.
        if (canSeeDirectly(startRow, startCol, targetRow, targetCol)) {
            return true;
        }

        // 3. Pre-calculate cells that are on a direct line-of-sight from the source.
        boolean[][] sourceLines = computeLineOfSight(startRow, startCol, '.', 'S');

        // 4. If any cell reachable from source is also on a line-of-sight from target, we win.
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (sourceLines[r][c] && targetLines[r][c]) {
                    return true;
                }
            }
        }

        // 5. Perform BFS to find if we can connect source lines to target lines via '.' cells.
        return performBFS(sourceLines, targetLines);
    }

    private boolean performBFS(boolean[][] sourceLines, boolean[][] targetLines) {
        Queue<Point> queue = new ArrayDeque<>();
        boolean[][] visited = new boolean[rows][cols];

        // Initialize queue with all valid cells reachable from the source in straight lines.
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (sourceLines[r][c]) {
                    queue.add(new Point(r, c));
                    visited[r][c] = true;
                }
            }
        }

        while (!queue.isEmpty()) {
            Point curr = queue.poll();

            for (int[] dir : DIRECTIONS) {
                int r = curr.row;
                int c = curr.col;

                // Move in a straight line as long as we encounter '.'
                while (true) {
                    int nextR = r + dir[0];
                    int nextC = c + dir[1];

                    if (!isValid(nextR, nextC)) break;

                    char cell = grid[nextR][nextC];

                    // If we hit the target or a cell on the target's line-of-sight, return success.
                    if (cell == 'T' || targetLines[nextR][nextC]) {
                        return true;
                    }

                    // We can only pass through and change direction at '.' cells.
                    if (cell == '.') {
                        r = nextR;
                        c = nextC;
                        if (!visited[r][c]) {
                            visited[r][c] = true;
                            queue.add(new Point(r, c));
                        }
                    } else {
                        // Hit an obstacle or 'S'.
                        break;
                    }
                }
            }
        }
        return false;
    }

    private boolean[][] computeLineOfSight(int r, int c, char allowed1, char allowed2) {
        boolean[][] lines = new boolean[rows][cols];
        lines[r][c] = true;

        for (int[] dir : DIRECTIONS) {
            int currR = r;
            int currC = c;
            while (true) {
                int nextR = currR + dir[0];
                int nextC = currC + dir[1];

                if (isValid(nextR, nextC)) {
                    char cell = grid[nextR][nextC];
                    if (cell == allowed1 || cell == allowed2) {
                        currR = nextR;
                        currC = nextC;
                        lines[currR][currC] = true;
                        continue;
                    }
                }
                break;
            }
        }
        return lines;
    }

    private boolean canSeeDirectly(int r1, int c1, int r2, int c2) {
        if (r1 != r2 && c1 != c2) return false;

        int dr = Integer.compare(r2, r1);
        int dc = Integer.compare(c2, c1);

        int currR = r1 + dr;
        int currC = c1 + dc;

        while (currR != r2 || currC != c2) {
            char cell = grid[currR][currC];
            if (cell != '.' && cell != 'S' && cell != 'T') return false;
            currR += dr;
            currC += dc;
        }
        return true;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private record Point(int row, int col) {}

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        String nStr = reader.next();
        if (nStr == null) return;
        int n = Integer.parseInt(nStr);
        int m = reader.nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = reader.next().toCharArray();
        }

        GridPathfinder pathfinder = new GridPathfinder(n, m, grid);
        System.out.println(pathfinder.canReachTarget() ? "YES" : "NO");
    }

    /**
     * High-performance input reader.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * MazeSolver finds if a target 'T' can be reached from a start 'S' 
 * with a maximum of 2 turns in a grid containing obstacles '*'.
 */
public class MazeSolver {

    // Directional movement vectors: Up, Right, Down, Left
    private static final int[][] DIRECTIONS = {
        {-1, 0}, // Up
        {0, 1},  // Right
        {1, 0},  // Down
        {0, -1}  // Left
    };

    private static final int MAX_ALLOWED_TURNS = 2;

    /**
     * Represents a coordinate point in the 2D grid.
     */
    private static class Point {
        final int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Represents the state of the BFS traversal.
     */
    private static class State {
        final int r, c, direction, turns;

        State(int r, int c, int direction, int turns) {
            this.r = r;
            this.c = c;
            this.direction = direction;
            this.turns = turns;
        }
    }

    public static void main(String[] args) {
        try {
            solveMaze();
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    private static void solveMaze() throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String firstLine = reader.readLine();
        if (firstLine == null) return;

        StringTokenizer st = new StringTokenizer(firstLine);
        int rows = Integer.parseInt(st.nextToken());
        int cols = Integer.parseInt(st.nextToken());

        char[][] grid = new char[rows][cols];
        Point start = null;
        Point target = null;

        for (int i = 0; i < rows; i++) {
            String rowStr = reader.readLine();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = rowStr.charAt(j);
                if (grid[i][j] == 'S') {
                    start = new Point(i, j);
                } else if (grid[i][j] == 'T') {
                    target = new Point(i, j);
                }
            }
        }

        if (canReachTarget(rows, cols, grid, start, target)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Uses 0-1 BFS to determine if the target is reachable within the turn limit.
     */
    private static boolean canReachTarget(int rows, int cols, char[][] grid, Point start, Point target) {
        if (start == null || target == null) return false;
        if (start.r == target.r && start.c == target.c) return true;

        // dist[r][c][dir] stores the minimum turns to reach (r, c) while facing 'dir'
        int[][][] dist = new int[rows][cols][4];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                Arrays.fill(dist[i][j], Integer.MAX_VALUE);
            }
        }

        // Deque for 0-1 BFS: 0-cost moves (same direction) go to front, 1-cost moves go to back
        Deque<State> deque = new ArrayDeque<>();

        // Initialize the BFS by moving from the start in all 4 directions.
        // The first direction chosen is free (0 turns).
        for (int d = 0; d < 4; d++) {
            int nr = start.r + DIRECTIONS[d][0];
            int nc = start.c + DIRECTIONS[d][1];

            if (isValid(nr, nc, rows, cols) && grid[nr][nc] != '*') {
                dist[nr][nc][d] = 0;
                deque.addLast(new State(nr, nc, d, 0));
            }
        }

        while (!deque.isEmpty()) {
            State curr = deque.removeFirst();

            // If we've found a better way to this state already, skip
            if (curr.turns > dist[curr.r][curr.c][curr.direction]) continue;

            // If we reached the target within turn limits
            if (curr.r == target.r && curr.c == target.c) return true;

            // Explore all 4 possible directions for the next move
            for (int d = 0; d < 4; d++) {
                int nr = curr.r + DIRECTIONS[d][0];
                int nc = curr.c + DIRECTIONS[d][1];

                if (isValid(nr, nc, rows, cols) && grid[nr][nc] != '*') {
                    // If the direction changes, it's a turn (cost 1)
                    int turnCost = (d == curr.direction) ? 0 : 1;
                    int newTurns = curr.turns + turnCost;

                    if (newTurns <= MAX_ALLOWED_TURNS && newTurns < dist[nr][nc][d]) {
                        dist[nr][nc][d] = newTurns;
                        if (turnCost == 0) {
                            deque.addFirst(new State(nr, nc, d, newTurns));
                        } else {
                            deque.addLast(new State(nr, nc, d, newTurns));
                        }
                    }
                }
            }
        }

        return false;
    }

    /**
     * Checks if the given coordinates are within the grid boundaries.
     */
    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.LinkedList;
import java.util.Queue;
import java.util.StringTokenizer;

/**
 * Solves the pathfinding problem on a grid with a limited number of turns.
 */
public class TinkoffB {

    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        Solver solver = new Solver();

        solver.solve(in, out);

        out.close();
    }

    static class Solver {
        // Direction offsets: North, East, South, West
        private static final int[] DR = {-1, 0, 1, 0};
        private static final int[] DC = {0, 1, 0, -1};

        private static final char OBSTACLE = '*';
        private static final char START_NODE = 'S';
        private static final char TARGET_NODE = 'T';
        private static final char PATH = '.';

        // Maximum turns allowed (as per original logic: 2)
        private static final int MAX_TURNS = 2;

        public void solve(InputReader in, PrintWriter out) {
            int rows = in.nextInt();
            int cols = in.nextInt();

            char[][] grid = new char[rows][cols];
            int startR = 0, startC = 0;
            int targetR = 0, targetC = 0;

            for (int i = 0; i < rows; i++) {
                String rowString = in.next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = rowString.charAt(j);
                    if (grid[i][j] == START_NODE) {
                        startR = i;
                        startC = j;
                    } else if (grid[i][j] == TARGET_NODE) {
                        targetR = i;
                        targetC = j;
                    }
                }
            }

            if (canReachTarget(grid, rows, cols, startR, startC, targetR, targetC)) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        }

        private boolean canReachTarget(char[][] grid, int rows, int cols, 
                                       int startR, int startC, int targetR, int targetC) {

            // Special case: start is target
            if (startR == targetR && startC == targetC) return true;

            // visited[row][col][direction][remaining_turns]
            boolean[][][][] visited = new boolean[rows][cols][4][MAX_TURNS + 1];
            Queue<State> queue = new LinkedList<>();

            // Initialize BFS: starting at S, we can face any direction with full turns remaining
            for (int dir = 0; dir < 4; dir++) {
                visited[startR][startC][dir][MAX_TURNS] = true;
                queue.add(new State(startR, startC, MAX_TURNS, dir));
            }

            while (!queue.isEmpty()) {
                State current = queue.poll();

                for (int i = 0; i < 4; i++) {
                    int nextR = current.r + DR[i];
                    int nextC = current.c + DC[i];

                    if (isValidMove(grid, rows, cols, nextR, nextC)) {
                        // If moving in the same direction, no turn cost. Otherwise, cost is 1.
                        int turnsRemaining = (i == current.dir) ? current.turnsLeft : current.turnsLeft - 1;

                        if (turnsRemaining >= 0 && !visited[nextR][nextC][i][turnsRemaining]) {
                            // If we reached the target
                            if (nextR == targetR && nextC == targetC) {
                                return true;
                            }

                            visited[nextR][nextC][i][turnsRemaining] = true;
                            queue.add(new State(nextR, nextC, turnsRemaining, i));
                        }
                    }
                }
            }

            return false;
        }

        private boolean isValidMove(char[][] grid, int rows, int cols, int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] != OBSTACLE;
        }

        /**
         * Represents a single state in the BFS traversal.
         */
        private static class State {
            final int r;
            final int c;
            final int turnsLeft;
            final int dir;

            State(int r, int c, int turnsLeft, int dir) {
                this.r = r;
                this.c = c;
                this.turnsLeft = turnsLeft;
                this.dir = dir;
            }
        }
    }

    /**
     * Fast I/O Reader.
     */
    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Solution for the "Igor and his way to work" problem.
 * Finds if a path exists from 'S' to 'T' with at most 2 turns.
 */
public class IgorAndHisWayToWork {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        try {
            String firstVal = reader.next();
            if (firstVal == null) return;

            int rows = Integer.parseInt(firstVal);
            int cols = reader.nextInt();

            Grid grid = new Grid(rows, cols, reader);
            Pathfinder pathfinder = new Pathfinder(grid);

            boolean canReach = pathfinder.solve();
            System.out.println(canReach ? "YES" : "NO");
        } catch (IOException | NumberFormatException e) {
            // In a production environment, use a logger.
        }
    }

    /**
     * Represents the road map and key coordinates.
     */
    static class Grid {
        final int rows;
        final int cols;
        final char[][] map;
        int startX, startY;
        int targetX, targetY;

        Grid(int rows, int cols, FastReader reader) throws IOException {
            this.rows = rows;
            this.cols = cols;
            this.map = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                if (line == null) break;
                for (int j = 0; j < cols; j++) {
                    map[i][j] = line.charAt(j);
                    if (map[i][j] == 'S') {
                        startX = i;
                        startY = j;
                    } else if (map[i][j] == 'T') {
                        targetX = i;
                        targetY = j;
                    }
                }
            }
        }
    }

    /**
     * Enum to handle direction-based movement and turn logic.
     */
    enum Direction {
        RIGHT(0, 1),
        LEFT(0, -1),
        UP(-1, 0),
        DOWN(1, 0);

        final int dr;
        final int dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }

        /**
         * Determines if another direction is a 90-degree turn.
         */
        public boolean isPerpendicular(Direction other) {
            return (this == RIGHT || this == LEFT) ? (other == UP || other == DOWN)
                    : (other == RIGHT || other == LEFT);
        }
    }

    /**
     * Encapsulates the pathfinding algorithm logic.
     */
    static class Pathfinder {
        private final Grid grid;
        // visited[row][col][turns_made][direction_index]
        private final boolean[][][][] visited;

        Pathfinder(Grid grid) {
            this.grid = grid;
            // Turns can be 0, 1, or 2.
            this.visited = new boolean[grid.rows][grid.cols][3][Direction.values().length];
        }

        /**
         * Attempts to find a path by trying all four initial directions.
         */
        public boolean solve() {
            for (Direction dir : Direction.values()) {
                if (dfs(grid.startX, grid.startY, 0, dir)) {
                    return true;
                }
            }
            return false;
        }

        private boolean dfs(int r, int c, int turns, Direction dir) {
            // Base Case: Target reached
            if (r == grid.targetX && c == grid.targetY) {
                return true;
            }

            // Base Case: Out of bounds, obstacle, or already visited this state
            if (isInvalid(r, c) || visited[r][c][turns][dir.ordinal()]) {
                return false;
            }

            // Mark current state as visited
            visited[r][c][turns][dir.ordinal()] = true;

            // 1. Option: Move Straight
            int nextR = r + dir.dr;
            int nextC = c + dir.dc;
            if (isValidPosition(nextR, nextC) && grid.map[nextR][nextC] != '*') {
                if (dfs(nextR, nextC, turns, dir)) {
                    return true;
                }
            }

            // 2. Option: Turn (if we haven't exceeded the turn limit)
            if (turns < 2) {
                for (Direction nextDir : Direction.values()) {
                    if (dir.isPerpendicular(nextDir)) {
                        int turnR = r + nextDir.dr;
                        int turnC = c + nextDir.dc;
                        if (isValidPosition(turnR, turnC) && grid.map[turnR][turnC] != '*') {
                            if (dfs(turnR, turnC, turns + 1, nextDir)) {
                                return true;
                            }
                        }
                    }
                }
            }

            return false;
        }

        private boolean isInvalid(int r, int c) {
            return r < 0 || r >= grid.rows || c < 0 || c >= grid.cols || grid.map[r][c] == '*';
        }

        private boolean isValidPosition(int r, int c) {
            return r >= 0 && r < grid.rows && c >= 0 && c < grid.cols;
        }
    }

    /**
     * Utility class for fast input reading.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream s) {
            br = new BufferedReader(new InputStreamReader(s));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.StringTokenizer;

/**
 * A program to determine if a path exists in a maze from a starting point 'S'
 * to a target 'T' with a limited number of direction changes.
 */
public class MazeSolverApp {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] grid = new char[rows][cols];

            int startRow = 0;
            int startCol = 0;

            for (int i = 0; i < rows; i++) {
                String rowString = reader.next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = rowString.charAt(j);
                    if (grid[i][j] == 'S') {
                        startRow = i;
                        startCol = j;
                    }
                }
            }

            MazeSolver solver = new MazeSolver(grid, rows, cols, startRow, startCol);
            if (solver.canReachTarget()) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }

        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Represents the four possible movement directions in the grid.
     */
    enum Direction {
        NORTH(-1, 0),
        SOUTH(1, 0),
        WEST(0, -1),
        EAST(0, 1);

        final int dr;
        final int dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }
    }

    /**
     * Handles the pathfinding logic using Depth First Search (DFS) with memoization.
     */
    static class MazeSolver {
        private static final int MAX_TURNS = 2;
        private static final int UNVISITED = -1;
        private static final int POSSIBLE = 1;
        private static final int IMPOSSIBLE = 0;

        private final char[][] maze;
        private final int rows;
        private final int cols;
        private final int startRow;
        private final int startCol;

        // Memoization table: [row][col][direction_index][turns_taken]
        private final int[][][][] memo;
        private final boolean[][] visited;

        public MazeSolver(char[][] maze, int rows, int cols, int startRow, int startCol) {
            this.maze = maze;
            this.rows = rows;
            this.cols = cols;
            this.startRow = startRow;
            this.startCol = startCol;
            this.visited = new boolean[rows][cols];
            this.memo = new int[rows][cols][Direction.values().length][MAX_TURNS + 1];
            initializeMemo();
        }

        private void initializeMemo() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    for (int d = 0; d < Direction.values().length; d++) {
                        Arrays.fill(memo[i][j][d], UNVISITED);
                    }
                }
            }
        }

        /**
         * Starts the search by attempting to move in all 4 directions from the start.
         */
        public boolean canReachTarget() {
            // Edge case: Start is already the target
            if (maze[startRow][startCol] == 'T') {
                return true;
            }

            Direction[] directions = Direction.values();
            for (int i = 0; i < directions.length; i++) {
                int nr = startRow + directions[i].dr;
                int nc = startCol + directions[i].dc;

                // Initial movement doesn't count as a "turn"
                if (isValidMove(nr, nc) && dfs(nr, nc, i, 0)) {
                    return true;
                }
            }
            return false;
        }

        private boolean dfs(int r, int c, int dirIdx, int turnsTaken) {
            // Base cases: Out of bounds, wall, or too many turns
            if (!isValidMove(r, c) || maze[r][c] == '*' || turnsTaken > MAX_TURNS) {
                return false;
            }

            // Found target
            if (maze[r][c] == 'T') {
                return true;
            }

            // Return memoized result if available
            if (memo[r][c][dirIdx][turnsTaken] != UNVISITED) {
                return memo[r][c][dirIdx][turnsTaken] == POSSIBLE;
            }

            visited[r][c] = true;
            boolean found = false;
            Direction[] directions = Direction.values();

            for (int i = 0; i < directions.length; i++) {
                int nr = r + directions[i].dr;
                int nc = c + directions[i].dc;

                if (isValidMove(nr, nc) && maze[nr][nc] != '*' && !visited[nr][nc]) {
                    int nextTurns = (i == dirIdx) ? turnsTaken : turnsTaken + 1;

                    if (nextTurns <= MAX_TURNS && dfs(nr, nc, i, nextTurns)) {
                        found = true;
                        break;
                    }
                }
            }

            visited[r][c] = false; // Backtrack
            memo[r][c][dirIdx][turnsTaken] = found ? POSSIBLE : IMPOSSIBLE;
            return found;
        }

        private boolean isValidMove(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * Optimized reader for fast input processing.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solver for the Tinkoff grid traversal puzzle.
 * The goal is to determine if a target position 'T' is reachable from 'S'
 * within a maximum path cost of 2, where switching between movement modes 
 * (horizontal vs vertical) incurs a cost.
 */
public class TinkoffB {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            Grid grid = new Grid(rows, cols, reader);
            Pathfinder solver = new Pathfinder(grid);

            if (solver.isTargetReachable()) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        } catch (Exception e) {
            // In a real production environment, use a logger
            e.printStackTrace();
        }
    }

    /**
     * Represents the game grid and identifies key positions.
     */
    private static class Grid {
        private final int rows;
        private final int cols;
        private final char[][] matrix;
        private int startRow, startCol;
        private int targetRow, targetCol;

        public Grid(int rows, int cols, FastReader reader) {
            this.rows = rows;
            this.cols = cols;
            this.matrix = new char[rows][cols];
            parseGrid(reader);
        }

        private void parseGrid(FastReader reader) {
            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                for (int j = 0; j < cols; j++) {
                    matrix[i][j] = line.charAt(j);
                    if (matrix[i][j] == 'S') {
                        startRow = i;
                        startCol = j;
                    } else if (matrix[i][j] == 'T') {
                        targetRow = i;
                        targetCol = j;
                    }
                }
            }
        }

        public boolean isObstacle(int r, int c) {
            return r < 0 || r >= rows || c < 0 || c >= cols || matrix[r][c] == '*';
        }

        public int getRows() { return rows; }
        public int getCols() { return cols; }
        public int getStartRow() { return startRow; }
        public int getStartCol() { return startCol; }
        public int getTargetRow() { return targetRow; }
        public int getTargetCol() { return targetCol; }
    }

    /**
     * Represents a state in the BFS: position and the current movement mode.
     */
    private static class State {
        final int row;
        final int col;
        final int mode;

        State(int row, int col, int mode) {
            this.row = row;
            this.col = col;
            this.mode = mode;
        }
    }

    /**
     * Logic for calculating the shortest path using 0-1 BFS.
     */
    private static class Pathfinder {
        private static final int INF = 10;
        private static final int MAX_ALLOWED_COST = 2;

        // Mode 0: Horizontal movement (Left, Right)
        // Mode 1: Vertical movement (Up, Down)
        private static final int[][] ROW_OFFSETS = {
            {0, 0},   // Mode 0
            {-1, 1}   // Mode 1
        };
        private static final int[][] COL_OFFSETS = {
            {-1, 1},  // Mode 0
            {0, 0}    // Mode 1
        };

        private final Grid grid;

        public Pathfinder(Grid grid) {
            this.grid = grid;
        }

        public boolean isTargetReachable() {
            int R = grid.getRows();
            int C = grid.getCols();
            int[][][] minCosts = new int[2][R][C];

            // Initialize distances with infinity
            for (int m = 0; m < 2; m++) {
                for (int i = 0; i < R; i++) {
                    Arrays.fill(minCosts[m][i], INF);
                }
            }

            Deque<State> deque = new ArrayDeque<>();

            // Starting conditions: we can start in either mode at cost 0
            int sR = grid.getStartRow();
            int sC = grid.getStartCol();

            minCosts[0][sR][sC] = 0;
            minCosts[1][sR][sC] = 0;
            deque.addLast(new State(sR, sC, 0));
            deque.addLast(new State(sR, sC, 1));

            while (!deque.isEmpty()) {
                State curr = deque.pollFirst();
                int r = curr.row;
                int c = curr.col;
                int mode = curr.mode;
                int currentDist = minCosts[mode][r][c];

                // 1. Try moving in the CURRENT mode (Cost 0)
                for (int k = 0; k < 2; k++) {
                    int nr = r + ROW_OFFSETS[mode][k];
                    int nc = c + COL_OFFSETS[mode][k];

                    if (!grid.isObstacle(nr, nc)) {
                        if (minCosts[mode][nr][nc] > currentDist) {
                            minCosts[mode][nr][nc] = currentDist;
                            deque.addFirst(new State(nr, nc, mode));
                        }
                    }
                }

                // 2. Try switching to the OTHER mode and moving (Cost 1)
                if (currentDist < MAX_ALLOWED_COST) {
                    int nextMode = mode ^ 1;
                    for (int k = 0; k < 2; k++) {
                        int nr = r + ROW_OFFSETS[nextMode][k];
                        int nc = c + COL_OFFSETS[nextMode][k];

                        if (!grid.isObstacle(nr, nc)) {
                            if (minCosts[nextMode][nr][nc] > currentDist + 1) {
                                minCosts[nextMode][nr][nc] = currentDist + 1;
                                deque.addLast(new State(nr, nc, nextMode));
                            }
                        }
                    }
                }
            }

            // Check if target is reached within the allowed cost in either mode
            int tR = grid.getTargetRow();
            int tC = grid.getTargetCol();
            return minCosts[0][tR][tC] <= MAX_ALLOWED_COST || 
                   minCosts[1][tR][tC] <= MAX_ALLOWED_COST;
        }
    }

    /**
     * Fast I/O utility for efficient reading.
     */
    private static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A solution to determine if a target 'T' can be reached from a start 'S' 
 * in a grid with at most 2 turns.
 * 
 * A "turn" is a change in direction. 
 * 0 turns = 1 straight line
 * 1 turn  = 2 straight lines
 * 2 turns = 3 straight lines
 */
public class GridPathfinder {

    /**
     * Represents a 2D coordinate in the grid.
     */
    private static class Point {
        final int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    private static final int INF = Integer.MAX_VALUE;

    public static void main(String[] args) {
        try {
            Solution solution = new Solution();
            solution.run();
        } catch (IOException e) {
            System.err.println("An error occurred while reading input: " + e.getMessage());
        }
    }

    private static class Solution {

        public void run() throws IOException {
            BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
            String firstLine = reader.readLine();
            if (firstLine == null) return;

            StringTokenizer st = new StringTokenizer(firstLine);
            int rows = Integer.parseInt(st.nextToken());
            int cols = Integer.parseInt(st.nextToken());

            char[][] grid = new char[rows][cols];
            Point start = null;
            Point target = null;

            for (int i = 0; i < rows; i++) {
                String line = reader.readLine();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                    if (grid[i][j] == 'S') {
                        start = new Point(i, j);
                    } else if (grid[i][j] == 'T') {
                        target = new Point(i, j);
                    }
                }
            }

            if (start == null || target == null) {
                System.out.println("NO");
                return;
            }

            if (canReachTargetWithLimitedTurns(rows, cols, grid, start, target)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }

        /**
         * Uses Breadth-First Search to find the minimum number of straight lines 
         * required to reach the target.
         * 
         * @return true if target is reachable in 3 or fewer straight lines (2 turns).
         */
        private boolean canReachTargetWithLimitedTurns(int rows, int cols, char[][] grid, Point start, Point target) {
            int[][] distance = new int[rows][cols];
            for (int[] row : distance) {
                Arrays.fill(row, INF);
            }

            // ArrayDeque is generally faster than LinkedList for Queue operations in Java
            Queue<Point> queue = new ArrayDeque<>();

            // dist 0: Start position
            // dist 1: Cells reachable in 1st straight line (0 turns)
            // dist 2: Cells reachable in 2nd straight line (1 turn)
            // dist 3: Cells reachable in 3rd straight line (2 turns)
            distance[start.r][start.c] = 0;
            queue.add(start);

            // Direction vectors for Up, Down, Left, Right
            int[] dr = {-1, 1, 0, 0};
            int[] dc = {0, 0, -1, 1};

            while (!queue.isEmpty()) {
                Point current = queue.poll();
                int currentDist = distance[current.r][current.c];

                // Optimization: If we've already reached the 3-line limit, 
                // we don't explore further from this cell.
                if (currentDist >= 3) {
                    continue;
                }

                for (int i = 0; i < 4; i++) {
                    int nr = current.r + dr[i];
                    int nc = current.c + dc[i];

                    // Continue moving in a straight line in direction i
                    while (isWithinBounds(nr, nc, rows, cols) && isTraversable(grid[nr][nc])) {

                        if (distance[nr][nc] > currentDist + 1) {
                            // Found a shorter path to this cell
                            distance[nr][nc] = currentDist + 1;
                            queue.add(new Point(nr, nc));
                        } else if (distance[nr][nc] <= currentDist) {
                            // We hit a cell already reached by a more efficient or equal path.
                            // Any further cells in this direction would have been covered 
                            // by that previous path.
                            break;
                        }
                        // Note: if distance[nr][nc] == currentDist + 1, we don't add to queue 
                        // but we do continue the 'while' loop to check further cells in this line.

                        nr += dr[i];
                        nc += dc[i];
                    }
                }
            }

            return distance[target.r][target.c] <= 3;
        }

        private boolean isWithinBounds(int r, int c, int rows, int cols) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        private boolean isTraversable(char cell) {
            // 'S' (Start), 'T' (Target), and '.' (Empty) are all traversable.
            return cell == 'S' || cell == 'T' || cell == '.';
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A refactored solution for the grid visibility problem.
 * The goal is to determine if there is a direct line of sight or an intersection
 * between start (S) and target (T) points in a grid with walls (*).
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        FastWriter writer = new FastWriter(System.out);

        try {
            GridSolver solver = new GridSolver();
            solver.solve(reader, writer);
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    /**
     * Core logic for solving the grid problem.
     */
    static class GridSolver {
        private static final char START_NODE = 'S';
        private static final char TARGET_NODE = 'T';
        private static final char WALL = '*';
        private static final char EMPTY = '.';

        private static final char MARKER_START = '$';
        private static final char MARKER_TARGET = '#';

        private static final int[] DR = {1, 0, -1, 0};
        private static final int[] DC = {0, -1, 0, 1};

        public void solve(FastReader in, FastWriter out) throws IOException {
            int rows = in.readInt();
            int cols = in.readInt();
            char[][] grid = in.readGrid(rows, cols);

            if (isPathFound(grid, rows, cols)) {
                out.printLine("YES");
            } else {
                out.printLine("NO");
            }
        }

        private boolean isPathFound(char[][] grid, int rows, int cols) {
            // Step 1: Ray casting to mark visible paths from S and T
            if (castRays(grid, rows, cols)) {
                return true;
            }

            // Step 2: Check for intersections in rows
            for (int i = 0; i < rows; i++) {
                if (checkLine(grid[i])) {
                    return true;
                }
            }

            // Step 3: Check for intersections in columns
            for (int j = 0; j < cols; j++) {
                char[] column = new char[rows];
                for (int i = 0; i < rows; i++) {
                    column[i] = grid[i][j];
                }
                if (checkLine(column)) {
                    return true;
                }
            }

            return false;
        }

        /**
         * Projects visibility from every 'S' and 'T' node.
         * Returns true if a direct line of sight is found between S and T.
         */
        private boolean castRays(char[][] grid, int rows, int cols) {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == START_NODE || grid[r][c] == TARGET_NODE) {
                        char marker = (grid[r][c] == START_NODE) ? MARKER_START : MARKER_TARGET;

                        for (int d = 0; d < 4; d++) {
                            int nr = r + DR[d];
                            int nc = c + DC[d];

                            while (isValid(nr, nc, rows, cols) && grid[nr][nc] != WALL) {
                                // If we hit an S, T, or an existing marker, a connection is made
                                if (grid[nr][nc] != EMPTY) {
                                    return true;
                                }
                                grid[nr][nc] = marker;
                                nr += DR[d];
                                nc += DC[d];
                            }
                        }
                    }
                }
            }
            return false;
        }

        /**
         * Checks if a single line (row or column) contains both start and target markers
         * within a continuous segment (not blocked by walls).
         */
        private boolean checkLine(char[] line) {
            boolean hasStartMarker = false;
            boolean hasTargetMarker = false;

            for (char cell : line) {
                if (cell == WALL) {
                    hasStartMarker = false;
                    hasTargetMarker = false;
                } else if (cell == MARKER_START) {
                    hasStartMarker = true;
                } else if (cell == MARKER_TARGET) {
                    hasTargetMarker = true;
                }

                if (hasStartMarker && hasTargetMarker) {
                    return true;
                }
            }
            return false;
        }

        private boolean isValid(int r, int c, int rows, int cols) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * Fast I/O implementation for reading input.
     */
    static class FastReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int curChar;
        private int numChars;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() throws IOException {
            if (numChars == -1) throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                numChars = stream.read(buffer);
                if (numChars <= 0) return -1;
            }
            return buffer[curChar++];
        }

        public int readInt() throws IOException {
            int c = read();
            while (isWhitespace(c)) c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res = res * 10 + (c - '0');
                c = read();
            } while (!isWhitespace(c));
            return res * sgn;
        }

        public char[] readCharArray(int size) throws IOException {
            char[] arr = new char[size];
            for (int i = 0; i < size; i++) {
                int c = read();
                while (isWhitespace(c)) c = read();
                arr[i] = (char) c;
            }
            return arr;
        }

        public char[][] readGrid(int rows, int cols) throws IOException {
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = readCharArray(cols);
            }
            return grid;
        }

        private boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }

    /**
     * Fast I/O implementation for writing output.
     */
    static class FastWriter {
        private final PrintWriter writer;

        public FastWriter(OutputStream outputStream) {
            this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public void printLine(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                writer.print(objects[i]);
                if (i < objects.length - 1) writer.print(' ');
            }
            writer.println();
        }

        public void close() {
            writer.close();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.StringTokenizer;

/**
 * A pathfinding solver that finds if a target 'T' is reachable from a start 'S'
 * in a grid, given a limited number of direction changes (turns) allowed.
 */
public class GridPathfinder {

    private static final char START_CHAR = 'S';
    private static final char TARGET_CHAR = 'T';
    private static final char OBSTACLE_CHAR = '*';
    private static final int INITIAL_TURNS = 2;

    /**
     * Represents the possible movement directions in the grid.
     */
    enum Direction {
        RIGHT(0, 1),
        LEFT(0, -1),
        UP(-1, 0),
        DOWN(1, 0);

        final int rowOffset;
        final int colOffset;

        Direction(int rowOffset, int colOffset) {
            this.rowOffset = rowOffset;
            this.colOffset = colOffset;
        }
    }

    /**
     * Represents the current state of the search in the BFS.
     */
    static class State {
        final int row;
        final int col;
        final Direction direction;
        final int remainingTurns;

        State(int row, int col, Direction direction, int remainingTurns) {
            this.row = row;
            this.col = col;
            this.direction = direction;
            this.remainingTurns = remainingTurns;
        }
    }

    public static void main(String[] args) {
        InputReader reader = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] grid = reader.nextGrid(rows, cols);

            GridPathfinder pathfinder = new GridPathfinder();
            boolean possible = pathfinder.canReachTarget(grid, rows, cols);

            out.println(possible ? "YES" : "NO");
        } catch (Exception e) {
            // In a production environment, use a proper logging framework
            e.printStackTrace();
        } finally {
            out.close();
        }
    }

    /**
     * Performs a Breadth-First Search to determine if the target is reachable.
     */
    public boolean canReachTarget(char[][] grid, int rows, int cols) {
        int startRow = -1, startCol = -1;
        int targetRow = -1, targetCol = -1;

        // Find S and T coordinates
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == START_CHAR) {
                    startRow = i;
                    startCol = j;
                } else if (grid[i][j] == TARGET_CHAR) {
                    targetRow = i;
                    targetCol = j;
                }
            }
        }

        if (startRow == -1 || targetRow == -1) return false;

        // visited[row][col][direction_index][remaining_turns]
        // turns can be 0, 1, or 2 (size 3)
        boolean[][][][] visited = new boolean[rows][cols][Direction.values().length][INITIAL_TURNS + 1];
        Deque<State> queue = new ArrayDeque<>();

        // Initial states: The agent can start facing any of the 4 directions without consuming a turn
        for (Direction dir : Direction.values()) {
            visited[startRow][startCol][dir.ordinal()][INITIAL_TURNS] = true;
            queue.add(new State(startRow, startCol, dir, INITIAL_TURNS));
        }

        while (!queue.isEmpty()) {
            State current = queue.poll();

            if (current.row == targetRow && current.col == targetCol) {
                return true;
            }

            for (Direction nextDir : Direction.values()) {
                int nextRow = current.row + nextDir.rowOffset;
                int nextCol = current.col + nextDir.colOffset;

                // Validate bounds and obstacles
                if (isOutOfBounds(nextRow, nextCol, rows, cols) || grid[nextRow][nextCol] == OBSTACLE_CHAR) {
                    continue;
                }

                // Calculate turn cost
                int nextTurns = current.remainingTurns;
                if (nextDir != current.direction) {
                    nextTurns--;
                }

                // Check if this state is valid and not yet visited
                if (nextTurns >= 0 && !visited[nextRow][nextCol][nextDir.ordinal()][nextTurns]) {
                    visited[nextRow][nextCol][nextDir.ordinal()][nextTurns] = true;
                    queue.add(new State(nextRow, nextCol, nextDir, nextTurns));
                }
            }
        }

        return false;
    }

    private boolean isOutOfBounds(int r, int c, int rows, int cols) {
        return r < 0 || r >= rows || c < 0 || c >= cols;
    }

    /**
     * Fast I/O utility class.
     */
    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(java.io.InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public char[][] nextGrid(int rows, int cols) {
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = next().toCharArray();
            }
            return grid;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to determine if a target 'T' is reachable from a starting point 'S' 
 * in a grid, given a limited number of direction changes (turns).
 */
public class GridPathfinder {

    // Directional vectors: Down, Right, Up, Left
    private static final int[] DR = {1, 0, -1, 0};
    private static final int[] DC = {0, 1, 0, -1};

    private static final char START_CHAR = 'S';
    private static final char TARGET_CHAR = 'T';
    private static final char OBSTACLE_CHAR = '*';
    private static final int MAX_TURNS = 2;

    private final int rows;
    private final int cols;
    private final char[][] grid;

    public GridPathfinder(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
    }

    /**
     * Represents a unique state in the search space.
     */
    private static class State {
        final int r, c, dir, turnsLeft;

        State(int r, int c, int dir, int turnsLeft) {
            this.r = r;
            this.c = c;
            this.dir = dir;
            this.turnsLeft = turnsLeft;
        }
    }

    /**
     * Solves the reachability problem using Breadth-First Search (BFS).
     * 
     * @return true if target 'T' is reachable from any 'S', false otherwise.
     */
    public boolean solve() {
        // visited[row][col][direction][turns_remaining]
        // Using a 4D array to track visited states to prevent redundant processing.
        boolean[][][][] visited = new boolean[rows][cols][4][MAX_TURNS + 1];
        Deque<State> queue = new ArrayDeque<>();

        // Initialize search from all starting positions 'S'
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == START_CHAR) {
                    // If the starting cell is also the target
                    if (grid[i][j] == TARGET_CHAR) return true;

                    // Initial states: starting at 'S' facing any direction with max turns
                    for (int d = 0; d < 4; d++) {
                        visited[i][j][d][MAX_TURNS] = true;
                        queue.add(new State(i, j, d, MAX_TURNS));
                    }
                }
            }
        }

        while (!queue.isEmpty()) {
            State current = queue.poll();

            // Target check
            if (grid[current.r][current.c] == TARGET_CHAR) {
                return true;
            }

            // Transition 1: Move forward in the current direction
            int nextR = current.r + DR[current.dir];
            int nextC = current.c + DC[current.dir];

            if (isValid(nextR, nextC) && !visited[nextR][nextC][current.dir][current.turnsLeft]) {
                visited[nextR][nextC][current.dir][current.turnsLeft] = true;
                queue.add(new State(nextR, nextC, current.dir, current.turnsLeft));
            }

            // Transition 2: Change direction at the current cell (consumes 1 turn)
            if (current.turnsLeft > 0) {
                for (int newDir = 0; newDir < 4; newDir++) {
                    if (newDir != current.dir && !visited[current.r][current.c][newDir][current.turnsLeft - 1]) {
                        visited[current.r][current.c][newDir][current.turnsLeft - 1] = true;
                        queue.add(new State(current.r, current.c, newDir, current.turnsLeft - 1));
                    }
                }
            }
        }

        return false;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] != OBSTACLE_CHAR;
    }

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            // Handling input. Assuming 't' is provided as number of test cases.
            String tInput = reader.next();
            if (tInput != null) {
                int t = Integer.parseInt(tInput);
                while (t-- > 0) {
                    int n = reader.nextInt();
                    int m = reader.nextInt();
                    char[][] grid = new char[n][m];
                    for (int i = 0; i < n; i++) {
                        grid[i] = reader.next().toCharArray();
                    }

                    GridPathfinder pathfinder = new GridPathfinder(n, m, grid);
                    writer.println(pathfinder.solve() ? "YES" : "NO");
                }
            }
        } catch (Exception e) {
            // Error handling
        } finally {
            writer.close();
        }
    }

    /**
     * Utility class for fast I/O.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A refactored solution for the grid connectivity problem.
 * The goal is to determine if a path exists between 'S' and 'T' 
 * following specific L-shaped or T-shaped movement constraints.
 */
public class Main {
    public static void main(String[] args) {
        try (InputStream inputStream = System.in;
             PrintWriter out = new PrintWriter(System.out)) {

            FastReader reader = new FastReader(inputStream);
            Solver solver = new Solver();
            solver.solve(reader, out);

        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * Represents the different types of cells in the grid.
     */
    enum CellType {
        WALL(0),
        START(1),
        PATH(99),
        TARGET(99);

        private final int value;

        CellType(int value) {
            this.value = value;
        }

        public int getValue() {
            return value;
        }

        public static CellType fromInt(int val) {
            for (CellType type : values()) {
                if (type.value == val) return type;
            }
            return WALL;
        }
    }

    /**
     * Simple record to represent a 2D coordinate.
     */
    record Point(int row, int col) {}

    /**
     * Encapsulates the grid data and provides helper methods for traversal.
     */
    static class Grid {
        private final int[][] cells;
        private final int rows;
        private final int cols;

        public Grid(int rows, int cols) {
            this.rows = rows;
            this.cols = cols;
            this.cells = new int[rows][cols];
        }

        public void setCell(int r, int c, CellType type) {
            cells[r][c] = type.getValue();
        }

        public boolean isTraversable(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols && cells[r][c] > 0;
        }

        public int getRows() { return rows; }
        public int getCols() { return cols; }

        /**
         * Finds the contiguous range of traversable cells in a row containing the given column.
         */
        public int[] getHorizontalRange(int r, int c) {
            int left = c;
            while (left > 0 && isTraversable(r, left - 1)) {
                left--;
            }
            int right = c;
            while (right < cols - 1 && isTraversable(r, right + 1)) {
                right++;
            }
            return new int[]{left, right};
        }

        /**
         * Finds the contiguous range of traversable cells in a column containing the given row.
         */
        public int[] getVerticalRange(int c, int r) {
            int top = r;
            while (top > 0 && isTraversable(top - 1, c)) {
                top--;
            }
            int bottom = r;
            while (bottom < rows - 1 && isTraversable(bottom + 1, c)) {
                bottom++;
            }
            return new int[]{top, bottom};
        }
    }

    static class Solver {

        public void solve(FastReader in, PrintWriter out) {
            int rows = in.nextInt();
            int cols = in.nextInt();
            Grid grid = new Grid(rows, cols);

            Point startPoint = null;
            Point targetPoint = null;

            for (int i = 0; i < rows; i++) {
                String line = in.next();
                for (int j = 0; j < cols; j++) {
                    char c = line.charAt(j);
                    if (c == 'S') {
                        startPoint = new Point(i, j);
                        grid.setCell(i, j, CellType.START);
                    } else if (c == 'T') {
                        targetPoint = new Point(i, j);
                        grid.setCell(i, j, CellType.TARGET);
                    } else if (c == '.') {
                        grid.setCell(i, j, CellType.PATH);
                    } else {
                        grid.setCell(i, j, CellType.WALL);
                    }
                }
            }

            if (startPoint == null || targetPoint == null) {
                out.println("NO");
                return;
            }

            if (checkConnectivity(grid, startPoint, targetPoint)) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        }

        private boolean checkConnectivity(Grid grid, Point start, Point target) {
            // 1. Check for paths that move horizontally in the start/target rows, then vertically.
            // This finds paths that look like 'L' or 'T' shapes centered on vertical columns.
            int[] startRowRange = grid.getHorizontalRange(start.row(), start.col());
            int[] targetRowRange = grid.getHorizontalRange(target.row(), target.col());

            int overlapStartCol = Math.max(startRowRange[0], targetRowRange[0]);
            int overlapEndCol = Math.min(startRowRange[1], targetRowRange[1]);

            for (int c = overlapStartCol; c <= overlapEndCol; c++) {
                if (isVerticalSegmentTraversable(grid, c, start.row(), target.row())) {
                    return true;
                }
            }

            // 2. Check for paths that move vertically in the start/target columns, then horizontally.
            int[] startColRange = grid.getVerticalRange(start.col(), start.row());
            int[] targetColRange = grid.getVerticalRange(target.col(), target.row());

            int overlapStartRow = Math.max(startColRange[0], targetColRange[0]);
            int overlapEndRow = Math.min(startColRange[1], targetColRange[1]);

            for (int r = overlapStartRow; r <= overlapEndRow; r++) {
                if (isHorizontalSegmentTraversable(grid, r, start.col(), target.col())) {
                    return true;
                }
            }

            return false;
        }

        private boolean isVerticalSegmentTraversable(Grid grid, int col, int r1, int r2) {
            int minR = Math.min(r1, r2);
            int maxR = Math.max(r1, r2);
            for (int r = minR; r <= maxR; r++) {
                if (!grid.isTraversable(r, col)) return false;
            }
            return true;
        }

        private boolean isHorizontalSegmentTraversable(Grid grid, int row, int c1, int c2) {
            int minC = Math.min(c1, c2);
            int maxC = Math.max(c1, c2);
            for (int c = minC; c <= maxC; c++) {
                if (!grid.isTraversable(row, c)) return false;
            }
            return true;
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

