            if (startR == targetR && startC == targetC) return true;
            boolean[][][][] visited = new boolean[rows][cols][4][MAX_TURNS + 1];
            Queue<State> queue = new LinkedList<>();
            queue.add(new State(startR, startC, -1, 0));

            while (!queue.isEmpty()) {
                State curr = queue.poll();
                if (curr.r == targetR && curr.c == targetC) return true;

                for (int i = 0; i < 4; i++) {
                    Direction d = Direction.values()[i];
                    int nr = curr.r + d.dr;
                    int nc = curr.c + d.dc;

                    if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] != '*') {
                        int nextTurns = (curr.dirIdx == -1) ? 0 : (curr.dirIdx == i ? curr.turns : curr.turns + 1);
                        if (nextTurns <= MAX_TURNS && !visited[nr][nc][i][nextTurns]) {
                            visited[nr][nc][i][nextTurns] = true;
                            queue.add(new State(nr, nc, i, nextTurns));
                        }
                    }
                }
            }
