import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * PathIntersectionFinder analyzes a grid to determine if paths originating from 
 * specific markers ('S' and 'T') intersect within a specific expansion threshold.
 */
public class PathIntersectionFinder {

    // Direction vectors for cardinal movement: Right, Left, Down, Up
    private static final int[] ROW_DIRECTIONS = {0, 0, 1, -1};
    private static final int[] COL_DIRECTIONS = {1, -1, 0, 0};
    private static final char WALL = '*';
    private static final char MARKER_S = 'S';
    private static final char MARKER_T = 'T';

    public static void main(String[] args) {
        try {
            new PathIntersectionFinder().run();
        } catch (IOException e) {
            // In a production environment, use a logging framework.
            e.printStackTrace();
        }
    }

    /**
     * Initializes the environment and starts the program execution.
     */
    public void run() throws IOException {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        // Read grid dimensions
        String firstToken = reader.next();
        if (firstToken == null) {
            writer.close();
            return;
        }

        int rows = Integer.parseInt(firstToken);
        int cols = reader.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = reader.next().toCharArray();
        }

        if (hasValidIntersection(grid, rows, cols)) {
            writer.println("YES");
        } else {
            writer.println("NO");
        }

        writer.flush();
        writer.close();
    }

    /**
     * Determines if there is a cell where the reachability of 'S' and 'T' 
     * satisfies the intersection criteria.
     * 
     * @param grid The input character grid.
     * @param rows Number of rows.
     * @param cols Number of columns.
     * @return true if a valid intersection point is found.
     */
    private boolean hasValidIntersection(char[][] grid, int rows, int cols) {
        int[][] reachabilityS = calculateReachabilityMap(grid, rows, cols, MARKER_S);
        int[][] reachabilityT = calculateReachabilityMap(grid, rows, cols, MARKER_T);

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int levelS = reachabilityS[i][j];
                int levelT = reachabilityT[i][j];

                // Intersection condition: both markers can reach the cell,
                // and the combined expansion level is less than 4.
                if (levelS > 0 && levelT > 0 && (levelS + levelT < 4)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Computates a 2D integer map representing how "far" (in terms of expansion steps)
     * a target character can reach a cell via cardinal lines.
     */
    private int[][] calculateReachabilityMap(char[][] grid, int rows, int cols, char target) {
        int[][] reachMap = new int[rows][cols];

        // Pass 1: Mark cells directly reachable in cardinal directions from the target
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == target) {
                    markCardinalPaths(grid, reachMap, r, c, 1, rows, cols);
                }
            }
        }

        // Pass 2: Mark cells reachable from the cells identified in Pass 1
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (reachMap[r][c] == 1) {
                    markCardinalPaths(grid, reachMap, r, c, 2, rows, cols);
                }
            }
        }

        return reachMap;
    }

    /**
     * Expands outward from a starting cell in four directions until a wall is hit.
     * 
     * @param grid The original grid containing walls.
     * @param reachMap The map being updated with reachability levels.
     * @param startR Starting row.
     * @param startC Starting column.
     * @param level The reachability level to assign (e.g., 1 or 2).
     * @param rows Total rows.
     * @param cols Total columns.
     */
    private void markCardinalPaths(char[][] grid, int[][] reachMap, int startR, int startC, int level, int rows, int cols) {
        for (int d = 0; d < 4; d++) {
            int r = startR;
            int c = startC;

            while (r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] != WALL) {
                // Only update the map if the cell hasn't been reached by a previous pass.
                // This ensures that level 1 cells stay level 1, and level 0 cells become level 2.
                if (reachMap[r][c] == 0) {
                    reachMap[r][c] = level;
                }
                r += ROW_DIRECTIONS[d];
                c += COL_DIRECTIONS[d];
            }
        }
    }

    /**
     * A fast input reader to handle large volumes of data efficiently.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(java.io.InputStream input) {
            this.reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) {
                    return null;
                }
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            String token = next();
            return (token != null) ? Integer.parseInt(token) : 0;
        }
    }
}

