/**
 * Represents a state in the Breadth-First Search.
 */
class MazeState {
    final int row;
    final int col;
    final int directionIndex;
    final int turnsTaken;

    public MazeState(int row, int col, int directionIndex, int turnsTaken) {
        this.row = row;
        this.col = col;
        this.directionIndex = directionIndex;
        this.turnsTaken = turnsTaken;
    }
}

/**
 * Enum to handle grid movement logic.
 */
enum Direction {
    DOWN(1, 0), RIGHT(0, 1), UP(-1, 0), LEFT(0, -1);

    final int dr;
    final int dc;

    Direction(int dr, int dc) {
        this.dr = dr;
        this.dc = dc;
    }

    static Direction[] values() {
        return Direction.values();
    }
}

class MazeSolver {
    private static final int MAX_TURNS = 2;

    private final char[][] grid;
    private final int rows;
    private final int cols;
    private int startRow = -1;
    private int startCol = -1;

    public MazeSolver(char[][] grid, int rows, int cols) {
        this.grid = grid;
        this.rows = rows;
        this.cols = cols;
        findStart();
    }

    private void findStart() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 'S') {
                    startRow = r;
                    startCol = c;
                    return;
                }
            }
        }
    }

    /**
     * Executes a BFS to find if the target 'T' is reachable within turn constraints.
     */
    public boolean canReachTarget() {
        if (startRow == -1) return false;

        // visited[turns][direction][row][col]
        boolean[][][][] visited = new boolean[MAX_TURNS + 1][4][rows][cols];
        Deque<MazeState> queue = new ArrayDeque<>();

        // Initial state: we can start moving in any of the 4 directions without it counting as a turn.
        for (int d = 0; d < 4; d++) {
            visited[0][d][startRow][startCol] = true;
            queue.add(new MazeState(startRow, startCol, d, 0));
        }

        Direction[] dirs = Direction.values();

        while (!queue.isEmpty()) {
            MazeState current = queue.poll();

            // Check if we reached the target
            if (grid[current.row][current.col] == 'T') {
                return true;
            }

            for (int i = 0; i < 4; i++) {
                Direction nextDir = dirs[i];
                int nextRow = current.row + nextDir.dr;
                int nextCol = current.col + nextDir.dc;

                // Calculate turns: if the direction changes, increment turn count
                int nextTurns = current.turnsTaken + (i == current.directionIndex ? 0 : 1);

                if (isValidMove(nextRow, nextCol, nextTurns)) {
                    if (!visited[nextTurns][i][nextRow][nextCol]) {
                        visited[nextTurns][i][nextRow][nextCol] = true;
                        queue.add(new MazeState(nextRow, nextCol, i, nextTurns));
                    }
                }
            }
        }

        return false;
    }

    private boolean isValidMove(int r, int c, int turns) {
        return turns <= MAX_TURNS &&
               r >= 0 && r < rows &&
               c >= 0 && c < cols &&
               grid[r][c] != '*';
    }
}

/**
 * High-performance input reader.
 */
class FastReader {
    private BufferedReader reader;
    private StringTokenizer tokenizer;

    public FastReader(InputStream stream) {
        reader = new BufferedReader(new InputStreamReader(stream));
    }

    public String next() {
        while (tokenizer == null || !tokenizer.hasMoreElements()) {
            try {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                return null;
            }
        }
        return tokenizer.nextToken();
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }

    public char[][] readGrid(int rows, int cols) {
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = next();
            if (line == null) throw new RuntimeException("Unexpected end of input");
            grid[i] = line.toCharArray();
            if (grid[i].length != cols) {
                throw new IllegalArgumentException("Row length mismatch. Expected " + cols);
            }
        }
        return grid;
    }
}

import java.util.*;
import java.io.*;

/**
 * IgorWayToWork solves the problem of finding if a path exists between 
 * a start 'S' and target 'T' on a grid with a maximum of 2 turns allowed.
 */
public class IgorWayToWork {

    private static final int MAX_TURNS = 2;

    /**
     * Represents directions in the grid.
     */
    private enum Direction {
        UP(-1, 0),
        DOWN(1, 0),
        LEFT(0, -1),
        RIGHT(0, 1);

        final int dr;
        final int dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }
    }

    /**
     * Represents a state in our BFS traversal.
     */
    private static class State {
        final int row;
        final int col;
        final Direction dir;
        final int turns;

        State(int row, int col, Direction dir, int turns) {
            this.row = row;
            this.col = col;
            this.dir = dir;
            this.turns = turns;
        }
    }

    /**
     * Core logic for finding the path.
     */
    public boolean solve(int n, int m, boolean[][] grid, int startR, int startC, int targetR, int targetC) {
        if (startR == targetR && startC == targetC) {
            return true;
        }

        // visited[row][col][direction_index][turn_count]
        boolean[][][][] visited = new boolean[n][m][Direction.values().length][MAX_TURNS + 1];
        Queue<State> queue = new LinkedList<>();

        // Initial moves from the starting point (no turns yet)
        for (Direction d : Direction.values()) {
            int nr = startR + d.dr;
            int nc = startC + d.dc;

            if (isValid(nr, nc, n, m, grid)) {
                visited[nr][nc][d.ordinal()][0] = true;
                queue.add(new State(nr, nc, d, 0));
            }
        }

        while (!queue.isEmpty()) {
            State curr = queue.poll();

            if (curr.row == targetR && curr.col == targetC) {
                return true;
            }

            // Option 1: Move forward in the same direction
            int nextR = curr.row + curr.dir.dr;
            int nextC = curr.col + curr.dir.dc;

            if (isValid(nextR, nextC, n, m, grid) && !visited[nextR][nextC][curr.dir.ordinal()][curr.turns]) {
                visited[nextR][nextC][curr.dir.ordinal()][curr.turns] = true;
                queue.add(new State(nextR, nextC, curr.dir, curr.turns));
            }

            // Option 2: Try turning (if turns remaining)
            if (curr.turns < MAX_TURNS) {
                for (Direction nextDir : Direction.values()) {
                    // If it's a different direction, it's a turn
                    if (nextDir != curr.dir) {
                        int tr = curr.row + nextDir.dr;
                        int tc = curr.col + nextDir.dc;

                        if (isValid(tr, tc, n, m, grid) && !visited[tr][tc][nextDir.ordinal()][curr.turns + 1]) {
                            visited[tr][tc][nextDir.ordinal()][curr.turns + 1] = true;
                            queue.add(new State(tr, tc, nextDir, curr.turns + 1));
                        }
                    }
                }
            }
        }

        return false;
    }

    private boolean isValid(int r, int c, int n, int m, boolean[][] grid) {
        return r >= 0 && r < n && c >= 0 && c < m && grid[r][c];
    }

    /**
     * Handles reading input and executing the solver.
     */
    public void run(BufferedReader br, PrintWriter pw) throws IOException {
        String line = br.readLine();
        if (line == null) return;

        StringTokenizer st = new StringTokenizer(line);
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());

        boolean[][] grid = new boolean[n][m];
        int startR = -1, startC = -1, targetR = -1, targetC = -1;

        for (int i = 0; i < n; i++) {
            String rowStr = br.readLine();
            for (int j = 0; j < m; j++) {
                char c = rowStr.charAt(j);
                if (c != '*') {
                    grid[i][j] = true;
                    if (c == 'S') {
                        startR = i;
                        startC = j;
                    } else if (c == 'T') {
                        targetR = i;
                        targetC = j;
                    }
                }
            }
        }

        boolean result = solve(n, m, grid, startR, startC, targetR, targetC);
        pw.println(result ? "YES" : "NO");
    }

    public static void main(String[] args) throws IOException {
        IgorWayToWork solver = new IgorWayToWork();

        // Defaulting to Standard I/O
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        solver.run(br, pw);
        pw.flush();
        pw.close();
    }
}

import java.util.*;

/**
 * Represents the possible directions Igor can move.
 */
enum Direction {
    UP(-1, 0),
    DOWN(1, 0),
    LEFT(0, -1),
    RIGHT(0, 1);

    private final int deltaRow;
    private final int deltaCol;

    Direction(int deltaRow, int deltaCol) {
        this.deltaRow = deltaRow;
        this.deltaCol = deltaCol;
    }

    public int getDeltaRow() { return deltaRow; }
    public int getDeltaCol() { return deltaCol; }

    public static Direction fromChar(char c) {
        return switch (c) {
            case 'U' -> UP;
            case 'D' -> DOWN;
            case 'L' -> LEFT;
            case 'R' -> RIGHT;
            default -> throw new IllegalArgumentException("Invalid direction: " + c);
        };
    }
}

/**
 * Represents a coordinate on the grid.
 */
record Position(int row, int col) {}

/**
 * Represents the state of the search at a specific point.
 */
record SearchState(Position pos, Direction direction, int turns) {}

/**
 * Encapsulates the grid map and its properties.
 */
class Grid {
    public static final char START = 'S';
    public static final char TARGET = 'T';
    public static final char WALL = '*';

    private final char[][] cells;
    private final int rows;
    private final int cols;

    public Grid(int rows, int cols, char[][] cells) {
        this.rows = rows;
        this.cols = cols;
        this.cells = cells;
    }

    public int getRows() { return rows; }
    public int getCols() { return cols; }

    public char getCell(int r, int c) {
        return cells[r][c];
    }

    public boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    public boolean isWalkable(int r, int c) {
        return isWithinBounds(r, c) && cells[r][c] != WALL;
    }

    public Position findCharacter(char target) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (cells[i][j] == target) {
                    return new Position(i, j);
                }
            }
        }
        return null;
    }
}

/**
 * Logic for finding if a path exists with a turn constraint.
 */
class PathFinder {
    private static final int MAX_TURNS = 2;
    private final Grid grid;

    public PathFinder(Grid grid) {
        this.grid = grid;
    }

    /**
     * Uses BFS to determine if the target can be reached with at most 2 turns.
     */
    public boolean canReachTarget() {
        Position start = grid.findCharacter(Grid.START);
        if (start == null) return false;

        // State: [row][col][direction_ordinal][turns]
        boolean[][][][] visited = new boolean[grid.getRows()][grid.getCols()][Direction.values().length][MAX_TURNS + 1];
        Queue<SearchState> queue = new LinkedList<>();

        // Initialize queue with moves from the starting position
        for (Direction dir : Direction.values()) {
            int nr = start.row() + dir.getDeltaRow();
            int nc = start.col() + dir.getDeltaCol();

            if (grid.isWalkable(nr, nc)) {
                queue.add(new SearchState(new Position(nr, nc), dir, 0));
                visited[nr][nc][dir.ordinal()][0] = true;
            }
        }

        while (!queue.isEmpty()) {
            SearchState current = queue.poll();

            if (grid.getCell(current.pos().row(), current.pos().col()) == Grid.TARGET) {
                return true;
            }

            for (Direction nextDir : Direction.values()) {
                int nextRow = current.pos().row() + nextDir.getDeltaRow();
                int nextCol = current.pos().col() + nextDir.getDeltaCol();

                if (!grid.isWalkable(nextRow, nextCol)) continue;

                int nextTurns = current.turns() + (nextDir == current.direction() ? 0 : 1);

                if (nextTurns <= MAX_TURNS && !visited[nextRow][nextCol][nextDir.ordinal()][nextTurns]) {
                    visited[nextRow][nextCol][nextDir.ordinal()][nextTurns] = true;
                    queue.add(new SearchState(new Position(nextRow, nextCol), nextDir, nextTurns));
                }
            }
        }

        return false;
    }
}

