import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.*;

/**
 * A pathfinder that finds if a target can be reached within a specific turn limit.
 */
public class GridPathfinder {

    private static final int MAX_ALLOWED_TURNS = 2;

    /**
     * Represents the movement directions in the grid.
     */
    private enum Direction {
        DOWN(1, 0),
        UP(-1, 0),
        RIGHT(0, 1),
        LEFT(0, -1);

        final int dx, dy;

        Direction(int dx, int dy) {
            this.dx = dx;
            this.dy = dy;
        }
    }

    /**
     * Represents a specific state in the BFS traversal.
     */
    private static class State {
        final int x;
        final int y;
        final int turns;
        final Direction direction;

        State(int x, int y, int turns, Direction direction) {
            this.x = x;
            this.y = y;
            this.turns = turns;
            this.direction = direction;
        }
    }

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int startX, startY;
    private final int endX, endY;

    public GridPathfinder(int rows, int cols, char[][] grid, int startX, int startY, int endX, int endY) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.startX = startX;
        this.startY = startY;
        this.endX = endX;
        this.endY = endY;
    }

    /**
     * Executes a BFS to find if a path exists within the turn constraints.
     * 
     * @return true if the target is reachable within MAX_ALLOWED_TURNS, false otherwise.
     */
    public boolean solve() {
        // minTurnsAtState[row][col][direction_ordinal]
        int[][][] minTurnsAtState = new int[rows][cols][Direction.values().length];
        for (int[][] row : minTurnsAtState) {
            for (int[] col : row) {
                Arrays.fill(col, Integer.MAX_VALUE);
            }
        }

        Queue<State> queue = new LinkedList<>();

        // Initial state: no direction yet, 0 turns
        queue.add(new State(startX, startY, 0, null));

        while (!queue.isEmpty()) {
            State current = queue.poll();

            if (current.x == endX && current.y == endY) {
                return true;
            }

            for (Direction nextDir : Direction.values()) {
                int nextX = current.x + nextDir.dx;
                int nextY = current.y + nextDir.dy;

                if (isValidMove(nextX, nextY)) {
                    int nextTurns = calculateTurns(current, nextDir);

                    if (nextTurns <= MAX_ALLOWED_TURNS) {
                        int dirIdx = nextDir.ordinal();
                        // Only proceed if this state offers a path with fewer turns than previously found
                        if (nextTurns < minTurnsAtState[nextX][nextY][dirIdx]) {
                            minTurnsAtState[nextX][nextY][dirIdx] = nextTurns;
                            queue.add(new State(nextX, nextY, nextTurns, nextDir));
                        }
                    }
                }
            }
        }

        return false;
    }

    private boolean isValidMove(int x, int y) {
        return x >= 0 && x < rows && y >= 0 && y < cols && grid[x][y] != '*';
    }

    private int calculateTurns(State current, Direction nextDir) {
        // If it's the first move (direction is null), no turn is counted.
        if (current.direction == null) {
            return 0;
        }
        // If direction changes, increment turn count.
        return (current.direction == nextDir) ? current.turns : current.turns + 1;
    }

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        try {
            int n = reader.nextInt();
            int m = reader.nextInt();
            char[][] grid = new char[n][m];
            int startX = 0, startY = 0, endX = 0, endY = 0;

            for (int i = 0; i < n; i++) {
                String rowStr = reader.next();
                for (int j = 0; j < m; j++) {
                    grid[i][j] = rowStr.charAt(j);
                    if (grid[i][j] == 'S') {
                        startX = i;
                        startY = j;
                    } else if (grid[i][j] == 'T') {
                        endX = i;
                        endY = j;
                    }
                }
            }

            GridPathfinder pathfinder = new GridPathfinder(n, m, grid, startX, startY, endX, endY);
            if (pathfinder.solve()) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }

        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Utility class for fast I/O operations.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to determine if a "staircase" or "Z-shaped" path exists 
 * between a start point 'S' and a target point 'T' in a 2D grid.
 */
public class Abood2D {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            char[][] gridData = new char[rows][cols];
            Point start = null;
            Point target = null;

            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                for (int j = 0; j < cols; j++) {
                    gridData[i][j] = line.charAt(j);
                    if (gridData[i][j] == 'S') {
                        start = new Point(i, j);
                    } else if (gridData[i][j] == 'T') {
                        target = new Point(i, j);
                    }
                }
            }

            if (start == null || target == null) {
                System.out.println("NO");
                return;
            }

            MazeGrid grid = new MazeGrid(gridData);
            MazeSolver solver = new MazeSolver(grid, start, target);

            if (solver.canReachTarget()) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }

        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Represents a coordinate in the 2D grid.
     */
    static class Point {
        final int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Represents a 1D range (either a row span or column span).
     */
    static class Range {
        final int min, max;

        Range(int min, int max) {
            this.min = min;
            this.max = max;
        }

        /**
         * Returns the intersection of this range and another.
         * Returns an empty range if no intersection exists.
         */
        Range intersect(Range other) {
            int newMin = Math.max(this.min, other.min);
            int newMax = Math.min(this.max, other.max);
            if (newMin > newMax) {
                return new Range(0, -1);
            }
            return new Range(newMin, newMax);
        }

        boolean isEmpty() {
            return min > max;
        }
    }

    /**
     * Handles grid-specific operations like boundary checking and path validation.
     */
    static class MazeGrid {
        private final char[][] cells;
        private final int rows;
        private final int cols;

        MazeGrid(char[][] cells) {
            this.cells = cells;
            this.rows = cells.length;
            this.cols = cells[0].length;
        }

        boolean isCellWalkable(int r, int c) {
            if (r < 0 || r >= rows || c < 0 || c >= cols) return false;
            char ch = cells[r][c];
            return ch == '.' || ch == 'S' || ch == 'T';
        }

        /**
         * Checks if a straight horizontal or vertical path is clear of obstacles.
         */
        boolean isPathClear(int r1, int c1, int r2, int c2) {
            if (r1 == r2) { // Horizontal movement
                int startCol = Math.min(c1, c2);
                int endCol = Math.max(c1, c2);
                for (int j = startCol; j <= endCol; j++) {
                    if (!isCellWalkable(r1, j)) return false;
                }
                return true;
            } else if (c1 == c2) { // Vertical movement
                int startRow = Math.min(r1, r2);
                int endRow = Math.max(r1, r2);
                for (int i = startRow; i <= endRow; i++) {
                    if (!isCellWalkable(i, c1)) return false;
                }
                return true;
            }
            return false;
        }

        /**
         * Finds the horizontal range reachable from a point by moving through '.' only.
         */
        Range getHorizontalDotReach(int r, int c) {
            int left = c;
            while (left > 0 && cells[r][left - 1] == '.') {
                left--;
            }
            int right = c;
            while (right < cols - 1 && cells[r][right + 1] == '.') {
                right++;
            }
            return new Range(left, right);
        }

        /**
         * Finds the vertical range reachable from a point by moving through '.' only.
         */
        Range getVerticalDotReach(int r, int c) {
            int top = r;
            while (top > 0 && cells[top - 1][c] == '.') {
                top--;
            }
            int bottom = r;
            while (bottom < rows - 1 && cells[bottom + 1][c] == '.') {
                bottom++;
            }
            return new Range(top, bottom);
        }
    }

    /**
     * Contains the core logic to solve the maze problem.
     */
    static class MazeSolver {
        private final MazeGrid grid;
        private final Point start;
        private final Point target;

        MazeSolver(MazeGrid grid, Point start, Point target) {
            this.grid = grid;
            this.start = start;
            this.target = target;
        }

        public boolean canReachTarget() {
            // Case 1: Check for path: Start -(H)-> (start.r, c) -(V)-> (target.r, c) -(H)-> Target
            // This exists if there is a column 'c' in the horizontal dot-reach of both S and T,
            // and the vertical segment at column 'c' is clear.
            Range sHorizReach = grid.getHorizontalDotReach(start.r, start.c);
            Range tHorizReach = grid.getHorizontalDotReach(target.r, target.c);
            Range colIntersection = sHorizReach.intersect(tHorizReach);

            for (int c = colIntersection.min; c <= colIntersection.max; c++) {
                if (grid.isPathClear(start.r, c, target.r, c)) {
                    return true;
                }
            }

            // Case 2: Check for path: Start -(V)-> (r, start.c) -(H)-> (r, target.c) -(V)-> Target
            // This exists if there is a row 'r' in the vertical dot-reach of both S and T,
            // and the horizontal segment at row 'r' is clear.
            Range sVertReach = grid.getVerticalDotReach(start.r, start.c);
            Range tVertReach = grid.getVerticalDotReach(target.r, target.c);
            Range rowIntersection = sVertReach.intersect(tVertReach);

            for (int r = rowIntersection.min; r <= rowIntersection.max; r++) {
                if (grid.isPathClear(r, start.c, r, target.c)) {
                    return true;
                }
            }

            return false;
        }
    }

    /**
     * Utility class for fast input parsing.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

