/**
 * Represents directions on the grid.
 */
enum Direction {
    UP(-1, 0),
    DOWN(1, 0),
    LEFT(0, -1),
    RIGHT(0, 1);

    final int dr;
    final int dc;

    Direction(int dr, int dc) {
        this.dr = dr;
        this.dc = dc;
    }
}

/**
 * Represents the current state of the pathfinder during traversal.
 */
class State {
    final int row;
    final int col;
    final Direction direction;
    final int turns;

    State(int row, int col, Direction direction, int turns) {
        this.row = row;
        this.col = col;
        this.direction = direction;
        this.turns = turns;
    }
}

/**
 * Logic for navigating the grid and enforcing turn constraints.
 */
class GridPathfinder {
    private static final int MAX_ALLOWED_TURNS = 2;
    private final char[][] grid;
    private final int rows;
    private final int cols;
    private final int[][][] minTurnsToReach; // [row][col][direction_ordinal]

    public GridPathfinder(char[][] grid, int rows, int cols) {
        this.grid = grid;
        this.rows = rows;
        this.cols = cols;
        this.minTurnsToReach = new int[rows][cols][Direction.values().length];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                Arrays.fill(minTurnsToReach[i][j], Integer.MAX_VALUE);
            }
        }
    }

    /**
     * Performs a BFS to determine if target 'T' is reachable within turn constraints.
     */
    public boolean canReachTarget(int startRow, int startCol) {
        if (startRow == -1) return false;

        Queue<State> queue = new ArrayDeque<>();

        // Initial state: At 'S' with no direction and 0 turns
        queue.add(new State(startRow, startCol, null, 0));

        while (!queue.isEmpty()) {
            State current = queue.poll();

            for (Direction dir : Direction.values()) {
                int nextRow = current.row + dir.dr;
                int nextCol = current.col + dir.dc;

                if (isOutOfBounds(nextRow, nextCol)) {
                    continue;
                }

                // Calculate turns: if direction changes from the current state, increment turns
                // (The first move from 'S' counts as 0 turns)
                int nextTurns = (current.direction == null || current.direction == dir) 
                                ? current.turns 
                                : current.turns + 1;

                if (nextTurns > MAX_ALLOWED_TURNS) {
                    continue;
                }

                // Check if we reached the target
                if (grid[nextRow][nextCol] == 'T') {
                    return true;
                }

                // If it's a traversable path, check if this move is optimal
                if (grid[nextRow][nextCol] == '.') {
                    int dirIdx = dir.ordinal();
                    if (nextTurns < minTurnsToReach[nextRow][nextCol][dirIdx]) {
                        minTurnsToReach[nextRow][nextCol][dirIdx] = nextTurns;
                        queue.add(new State(nextRow, nextCol, dir, nextTurns));
                    }
                }
            }
        }

        return false;
    }

    private boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= rows || c < 0 || c >= cols;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * A solver for finding a path in a grid from a starting point 'S' 
 * to a target point 'T' with a limited number of turns.
 */
public class MazeSolver {

    private static final int MAX_TURNS = 2;
    private static final int DIRECTIONS_COUNT = 4;

    // Directions: Right, Down, Left, Up
    private static final int[] DX = {0, 1, 0, -1};
    private static final int[] DY = {1, 0, -1, 0};

    private final char[][] grid;
    private final int rows;
    private final int cols;
    private final boolean[][][][] visited; // [row][col][direction][turnsLeft]

    private int startRow = -1;
    private int startCol = -1;

    public MazeSolver(char[][] grid) {
        this.grid = grid;
        this.rows = grid.length;
        this.cols = grid[0].length;
        this.visited = new boolean[rows][cols][DIRECTIONS_COUNT][MAX_TURNS + 1];
        findStart();
    }

    private void findStart() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 'S') {
                    startRow = i;
                    startCol = j;
                    return;
                }
            }
        }
    }

    /**
     * Solves the maze and returns true if the target 'T' is reachable.
     */
    public boolean solve() {
        if (startRow == -1) return false;

        // Try starting in all 4 directions. 
        // We pass all 4 to ensure the first move doesn't count as a turn.
        for (int dir = 0; dir < DIRECTIONS_COUNT; dir++) {
            if (dfs(startRow, startCol, dir, MAX_TURNS)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Depth-First Search to navigate the maze.
     * 
     * @param r Current row
     * @param c Current column
     * @param incomingDir The direction used to arrive at the current cell
     * @param turnsLeft Number of turns remaining
     * @return true if target is found
     */
    private boolean dfs(int r, int c, int incomingDir, int turnsLeft) {
        if (grid[r][c] == 'T') {
            return true;
        }

        if (visited[r][c][incomingDir][turnsLeft]) {
            return false;
        }
        visited[r][c][incomingDir][turnsLeft] = true;

        for (int i = 0; i < DIRECTIONS_COUNT; i++) {
            int nr = r + DX[i];
            int nc = c + DY[i];

            if (isValidMove(nr, nc)) {
                // If we change direction, we consume one turn
                int nextTurns = (i == incomingDir) ? turnsLeft : turnsLeft - 1;

                if (nextTurns >= 0) {
                    if (dfs(nr, nc, i, nextTurns)) {
                        return true;
                    }
                }
            }
        }

        return false;
    }

    private boolean isValidMove(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] != '*';
    }

    public static void main(String[] args) {
        try (PrintWriter out = new PrintWriter(System.out);
             FastReader in = new FastReader()) {

            int n = in.nextInt();
            int m = in.nextInt();
            if (n <= 0 || m <= 0) {
                out.println("NO");
                return;
            }

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                String line = in.next();
                grid[i] = line.toCharArray();
            }

            MazeSolver solver = new MazeSolver(grid);
            if (solver.solve()) {
                out.println("YES");
            } else {
                out.println("NO");
            }

        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader() {
            this.reader = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        @Override
        public void close() throws IOException {
            reader.close();
        }
    }
}

import java.io.PrintWriter;
