import java.util.Scanner;

/**
 * A solver for finding if a path exists between 'S' and 'T' in a grid 
 * with a maximum allowed number of direction changes (turns).
 */
public class GridTurnFinder {

    private static final int INF = 1_000_000_000;
    private static final int MAX_ALLOWED_TURNS = 2;

    /**
     * Represents the type of movement performed to reach a cell.
     */
    private enum MovementType {
        HORIZONTAL,
        VERTICAL
    }

    /**
     * Represents a state in the BFS: current position and the direction used to get there.
     */
    private static class State {
        final int row;
        final int col;
        final MovementType lastMoveType;

        State(int row, int col, MovementType lastMoveType) {
            this.row = row;
            this.col = col;
            this.lastMoveType = lastMoveType;
        }
    }

    /**
     * Represents the grid layout and metadata.
     */
    private static class Grid {
        final int rows;
        final int cols;
        final boolean[][] isWalkable;
        int startRow = -1, startCol = -1;
        int targetRow = -1, targetCol = -1;

        Grid(int rows, int cols, Scanner sc) {
            this.rows = rows;
            this.cols = cols;
            this.isWalkable = new boolean[rows][cols];
            parseGrid(sc);
        }

        private void parseGrid(Scanner sc) {
            for (int r = 0; r < rows; r++) {
                String line = sc.next();
                for (int c = 0; c < cols; c++) {
                    char ch = line.charAt(c);
                    // '*' is a wall, everything else is walkable
                    isWalkable[r][c] = (ch != '*');

                    if (ch == 'S') {
                        startRow = r;
                        startCol = c;
                    } else if (ch == 'T') {
                        targetRow = r;
                        targetCol = c;
                    }
                }
            }
        }
    }

    /**
     * Executes the solve logic.
     */
    public void solve(Scanner in, PrintWriter out) {
        if (!in.hasNextInt()) return;

        int n = in.nextInt();
        int m = in.nextInt();
        Grid grid = new Grid(n, m, in);

        int minTurns = findMinTurns(grid);

        if (minTurns <= MAX_ALLOWED_TURNS) {
            out.println("YES");
        } else {
            out.println("NO");
        }
    }

    /**
     * Performs a 0-1 BFS to find the minimum number of turns required.
     */
    private int findMinTurns(Grid grid) {
        // dist[row][col][MovementType index]
        int[][][] dist = new int[grid.rows][grid.cols][2];
        for (int r = 0; r < grid.rows; r++) {
            for (int c = 0; c < grid.cols; c++) {
                Arrays.fill(dist[r][c], INF);
            }
        }

        Deque<State> deque = new ArrayDeque<>();

        // To ensure the first move doesn't count as a "turn", we initialize 
        // the starting position for both movement types with 0 cost.
        dist[grid.startRow][grid.startCol][MovementType.HORIZONTAL.ordinal()] = 0;
        dist[grid.startRow][grid.startCol][MovementType.VERTICAL.ordinal()] = 0;

        deque.addLast(new State(grid.startRow, grid.startCol, MovementType.HORIZONTAL));
        deque.addLast(new State(grid.startRow, grid.startCol, MovementType.VERTICAL));

        // Directional vectors: Up, Down, Left, Right
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};
        MovementType[] moveDirections = {
            MovementType.VERTICAL,   // Up
            MovementType.VERTICAL,   // Down
            MovementType.HORIZONTAL, // Left
            MovementType.HORIZONTAL  // Right
        };

        while (!deque.isEmpty()) {
            State current = deque.removeFirst();
            int r = current.row;
            int c = current.col;
            MovementType type = current.lastMoveType;
            int currentDist = dist[r][c][type.ordinal()];

            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i];
                int nc = c + dc[i];

                if (isWithinBoundsAndWalkable(nr, nc, grid)) {
                    MovementType nextMoveType = moveDirections[i];
                    int turnCost = (nextMoveType == type) ? 0 : 1;

                    if (dist[nr][nc][nextMoveType.ordinal()] > currentDist + turnCost) {
                        dist[nr][nc][nextMoveType.ordinal()] = currentDist + turnCost;

                        // 0-1 BFS optimization: 0-weight edges to front, 1-weight to back
                        if (turnCost == 0) {
                            deque.addFirst(new State(nr, nc, nextMoveType));
                        } else {
                            deque.addLast(new State(nr, nc, nextMoveType));
                        }
                    }
                }
            }
        }

        // The answer is the minimum distance to the target cell across both movement types
        return Math.min(
            dist[grid.targetRow][grid.targetCol][MovementType.HORIZONTAL.ordinal()],
            dist[grid.targetRow][grid.targetCol][MovementType.VERTICAL.ordinal()]
        );
    }

    private boolean isWithinBoundsAndWalkable(int r, int c, Grid grid) {
        return r >= 0 && r < grid.rows && c >= 0 && c < grid.cols && grid.isWalkable[r][c];
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        new GridTurnFinder().solve(in, out);

        in.close();
        out.close();
    }
}

import java.util.*;

/**
 * GridPathfinder finds if a path exists between a starting point 'T' 
 * and a target point 'S' in a grid with obstacles '*' with a maximum of 2 turns.
 */
public class GridPathfinder {

    private enum Direction {
        UP(-1, 0),
        DOWN(1, 0),
        LEFT(0, -1),
        RIGHT(0, 1);

        final int dr;
        final int dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }
    }

    private final char[][] grid;
    private final int rows;
    private final int cols;
    private final int startRow;
    private final int startCol;
    private final int targetRow;
    private final int targetCol;

    public GridPathfinder(char[][] grid, int rows, int cols, 
                          int startRow, int startCol, 
                          int targetRow, int targetCol) {
        this.grid = grid;
        this.rows = rows;
        this.cols = cols;
        this.startRow = startRow;
        this.startCol = startCol;
        this.targetRow = targetRow;
        this.targetCol = targetCol;
    }

    /**
     * Orchestrates the pathfinding search.
     * @return true if a path is found within the turn limit.
     */
    public boolean canReachTarget() {
        // Immediate check if start and target are the same
        if (startRow == targetRow && startCol == targetCol) {
            return true;
        }

        // The original logic starts by picking an initial direction.
        // We attempt to start the path from the target 'T' moving in any of the 4 directions.
        for (Direction dir : Direction.values()) {
            if (dfs(targetRow, targetCol, 0, dir)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Depth First Search to explore paths.
     * 
     * @param r Current row
     * @param c Current column
     * @param turns Number of direction changes made so far
     * @param currentDir The direction used to arrive at the current cell
     * @return true if the path reaches 'S'
     */
    private boolean dfs(int r, int c, int turns, Direction currentDir) {
        // Base case: target reached
        if (r == startRow && c == startCol) {
            return true;
        }

        // Base case: turn limit exceeded (original logic allowed up to 2 turns)
        if (turns >= 3) {
            return false;
        }

        for (Direction nextDir : Direction.values()) {
            int nr = r + nextDir.dr;
            int nc = c + nextDir.dc;

            if (isValidMove(nr, nc)) {
                // If the direction changes, increment the turn count
                int nextTurns = (nextDir == currentDir) ? turns : turns + 1;

                // Constraint: Max 2 turns allowed (which means max 3 segments)
                if (nextTurns <= 2) {
                    if (dfs(nr, nc, nextTurns, nextDir)) {
                        return true;
                    }
                }
            }
        }

        return false;
    }

    private boolean isValidMove(int r, int c) {
        return r >= 0 && r < rows && 
               c >= 0 && c < cols && 
               grid[r][c] != '*';
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        scanner.nextLine(); // consume newline

        char[][] grid = new char[rows][cols];
        int startR = -1, startC = -1;
        int targetR = -1, targetC = -1;

        for (int i = 0; i < rows; i++) {
            String line = scanner.nextLine();
            grid[i] = line.toCharArray();
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 'S') {
                    startR = i;
                    startC = j;
                } else if (grid[i][j] == 'T') {
                    targetR = i;
                    targetC = j;
                }
            }
        }

        GridPathfinder pathfinder = new GridPathfinder(grid, rows, cols, 
                                                      startR, startC, 
                                                      targetR, targetC);

        if (pathfinder.canReachTarget()) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }
}

import java.util.*;
import java.io.*;

/**
 * A utility class to find if a target 'T' is reachable from a start 'S'
 * in a grid with a maximum number of allowed turns.
 */
public class GridPathfinder {

    // Directional movement constants: North, South, West, East
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};
    private static final int MAX_ALLOWED_TURNS = 2;

    private final int rows;
    private final int cols;
    private final char[][] grid;

    /**
     * Represents the current state during the BFS traversal.
     */
    private static class State {
        final int r, c, direction, turns;

        State(int r, int c, int direction, int turns) {
            this.r = r;
            this.c = c;
            this.direction = direction;
            this.turns = turns;
        }
    }

    public GridPathfinder(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
    }

    /**
     * Determines if the target 'T' is reachable from 'S' within the turn limit.
     * Uses 0-1 BFS (via Deque) to optimize for pathfinding with zero/one costs.
     *
     * @param startR Starting row index
     * @param startC Starting column index
     * @return true if target is reachable, false otherwise
     */
    public boolean isTargetReachable(int startR, int startC) {
        if (grid[startR][startC] == 'T') {
            return true;
        }

        // minTurns[row][col][direction] stores the minimum turns used to reach a cell facing a specific direction
        int[][][] minTurns = new int[rows][cols][4];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                Arrays.fill(minTurns[i][j], Integer.MAX_VALUE);
            }
        }

        Deque<State> deque = new ArrayDeque<>();

        // Initialize BFS by moving from the starting point in all 4 directions
        for (int d = 0; d < 4; d++) {
            int nr = startR + DR[d];
            int nc = startC + DC[d];

            if (isValid(nr, nc) && grid[nr][nc] != '*') {
                minTurns[nr][nc][d] = 0;
                deque.addLast(new State(nr, nc, d, 0));
            }
        }

        while (!deque.isEmpty()) {
            State curr = deque.removeFirst();

            // Optimization: if we found a better path to this state already, skip
            if (curr.turns > minTurns[curr.r][curr.c][curr.direction]) {
                continue;
            }

            // Target reached
            if (grid[curr.r][curr.c] == 'T') {
                return true;
            }

            // Explore neighbors
            for (int d = 0; d < 4; d++) {
                int nr = curr.r + DR[d];
                int nc = curr.c + DC[d];

                if (isValid(nr, nc) && grid[nr][nc] != '*') {
                    // If direction changes, it counts as a turn
                    int nextTurns = (d == curr.direction) ? curr.turns : curr.turns + 1;

                    if (nextTurns <= MAX_ALLOWED_TURNS && nextTurns < minTurns[nr][nc][d]) {
                        minTurns[nr][nc][d] = nextTurns;
                        State nextState = new State(nr, nc, d, nextTurns);

                        // 0-1 BFS: same direction (cost 0) goes to front, change (cost 1) goes to back
                        if (d == curr.direction) {
                            deque.addFirst(nextState);
                        } else {
                            deque.addLast(nextState);
                        }
                    }
                }
            }
        }

        return false;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Fast I/O Reader
     */
    private static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) {
        FastReader reader = new FastReader();

        String rowsStr = reader.next();
        if (rowsStr == null) return;
        int n = Integer.parseInt(rowsStr);
        int m = reader.nextInt();

        char[][] grid = new char[n][m];
        int startR = 0, startC = 0;

        for (int i = 0; i < n; i++) {
            String line = reader.next();
            for (int j = 0; j < m; j++) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] == 'S') {
                    startR = i;
                    startC = j;
                }
            }
        }

        GridPathfinder pathfinder = new GridPathfinder(n, m, grid);
        boolean found = pathfinder.isTargetReachable(startR, startC);

        System.out.println(found ? "YES" : "NO");
    }
}

