class GridSolver {
    private final FastReader reader;
    private final PrintWriter writer;
    private char[][] grid;
    private int[][] visibilityMap;
    private int rows;
    private int cols;
    private boolean intersectionFound;

    public GridSolver(InputStream inputStream, OutputStream outputStream) {
        this.reader = new FastReader(inputStream);
        this.writer = new PrintWriter(new OutputStreamWriter(outputStream));
    }

    public void solve() {
        rows = reader.nextInt();
        cols = reader.nextInt();
        grid = new char[rows][cols];
        visibilityMap = new int[rows][cols];
        intersectionFound = false;

        int startRow = -1, startCol = -1;
        int targetRow = -1, targetCol = -1;

        for (int i = 0; i < rows; i++) {
            String line = reader.next();
            grid[i] = line.toCharArray();
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 'S') {
                    startRow = i;
                    startCol = j;
                } else if (grid[i][j] == 'T') {
                    targetRow = i;
                    targetCol = j;
                }
            }
        }

        markStartVisibility(startRow, startCol);
        markTargetVisibility(targetRow, targetCol);

        // Final condition check based on original problem logic
        // b[tx][ty] % 10 == 5 handles the specific case where the target 
        // is reached via multiple paths from 'T' itself.
        boolean result = (visibilityMap[targetRow][targetCol] % 10 == 1) ||
                         (visibilityMap[targetRow][targetCol] % 10 == 5) ||
                         intersectionFound;

        writer.println(result ? "YES" : "NO");
        writer.flush();
        writer.close();
    }

    /**
     * Marks visibility from the start point 'S' in four cardinal directions.
     */
    private void markStartVisibility(int r, int c) {
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        // Mark directions (excluding the cell itself to prevent double counting before final set)
        for (int i = 0; i < 4; i++) {
            // The original logic treated 'up' and 'down' differently for S
            // but effectively marks all reachable cells in straight lines.
            // We replicate the loop offsets used in the original code.
            int nr = r + dr[i];
            int nc = c + dc[i];

            // Replicating exact original loop behavior for Start
            if (i == 0 && dr[i] == 0) continue; // skip if duplicate logic

            // To match the original logic precisely:
            // S Right/Down/Left/Up loops
        }

        // The original code had specific loops for S. Let's replicate exactly:
        // Right
        for (int j = 0; j < cols - c; j++) {
            if (grid[r][c + j] != '*') visibilityMap[r][c + j] += 1;
            else break;
        }
        // Left
        for (int j = 1; j <= c; j++) {
            if (grid[r][c - j] != '*') visibilityMap[r][c - j] += 1;
            else break;
        }
        // Up
        for (int j = 1; j <= r; j++) {
            if (grid[r - j][c] != '*') visibilityMap[r - j][c] += 1;
            else break;
        }
        // Down
        for (int j = 0; j < rows - r; j++) {
            if (grid[r + j][c] != '*') visibilityMap[r + j][c] += 1;
            else break;
        }

        visibilityMap[r][c] = 1;
    }

    /**
     * Marks visibility from the target point 'T' and detects intersections.
     */
    private void markTargetVisibility(int r, int c) {
        // Horizontal paths from T
        // Right
        for (int j = 0; j < cols - c; j++) {
            int currC = c + j;
            if (grid[r][currC] == '*') break;
            visibilityMap[r][currC] += 2;
            if (checkVerticalIntersection(r, currC)) intersectionFound = true;
        }
        // Left
        for (int j = 1; j <= c; j++) {
            int currC = c - j;
            if (grid[r][currC] == '*') break;
            visibilityMap[r][currC] += 2;
            if (checkVerticalIntersection(r, currC)) intersectionFound = true;
        }

        // Vertical paths from T
        // Up
        for (int i = 1; i <= r; i++) {
            int currR = r - i;
            if (grid[currR][c] == '*') break;
            visibilityMap[currR][c] += 2;
            if (checkHorizontalIntersection(currR, c)) intersectionFound = true;
        }
        // Down
        for (int i = 0; i < rows - r; i++) {
            int currR = r + i;
            if (grid[currR][c] == '*') break;
            visibilityMap[currR][c] += 2;
            if (checkHorizontalIntersection(currR, c)) intersectionFound = true;
        }
    }

    private boolean checkVerticalIntersection(int r, int c) {
        // Check Upward from current row
        for (int i = 0; i <= r; i++) {
            if (grid[r - i][c] != '*' && visibilityMap[r - i][c] == 1) return true;
            else if (grid[r - i][c] == '*') break;
        }
        // Check Downward from current row
        for (int i = 0; i < rows - r; i++) {
            if (grid[r + i][c] != '*' && visibilityMap[r + i][c] == 1) return true;
            else if (grid[r + i][c] == '*') break;
        }
        return false;
    }

    private boolean checkHorizontalIntersection(int r, int c) {
        // Check Leftward from current col
        for (int j = 0; j <= c; j++) {
            if (grid[r][c - j] != '*' && visibilityMap[r][c - j] == 1) return true;
            else if (grid[r][c - j] == '*') break;
        }
        // Check Rightward from current col
        for (int j = 0; j < cols - c; j++) {
            if (grid[r][c + j] != '*' && visibilityMap[r][c + j] == 1) return true;
            else if (grid[r][c + j] == '*') break;
        }
        return false;
    }

    /**
     * Helper class for fast I/O operations.
     */
    private static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.*;

/**
 * GridPathfinder determines if a path exists from a starting point 'S' to a target 'T' 
 * in a grid, subject to a constraint on the maximum number of direction changes allowed.
 * 
 * Complexity:
 * Time: O(N * M * D * K), where N, M are grid dimensions, D is number of directions, 
 *       and K is max direction changes.
 * Space: O(N * M * D * K) for the visited state tracking.
 */
public class GridPathfinder {

    private static final int MAX_DIRECTION_CHANGES = 2;

    /**
     * Represents the four possible movement directions in the grid.
     */
    private enum Direction {
        UP(-1, 0),
        RIGHT(0, 1),
        DOWN(1, 0),
        LEFT(0, -1);

        final int dr, dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }
    }

    /**
     * Represents a state in the Breadth-First Search (BFS) traversal.
     */
    private static class State {
        final int row;
        final int col;
        final Direction direction;
        final int turns;

        State(int row, int col, Direction direction, int turns) {
            this.row = row;
            this.col = col;
            this.direction = direction;
            this.turns = turns;
        }
    }

    public static void main(String[] args) {
        try {
            run();
        } catch (IOException e) {
            System.err.println("An error occurred while reading input: " + e.getMessage());
        }
    }

    /**
     * Orchestrates the input reading and initiates the pathfinding logic.
     */
    private static void run() throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String firstLine = reader.readLine();
        if (firstLine == null) return;

        StringTokenizer st = new StringTokenizer(firstLine);
        if (!st.hasMoreTokens()) return;

        int rows = Integer.parseInt(st.nextToken());
        int cols = Integer.parseInt(st.nextToken());

        char[][] grid = new char[rows][cols];
        int startRow = -1;
        int startCol = -1;

        for (int i = 0; i < rows; i++) {
            String line = reader.readLine();
            if (line == null) break;
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] == 'S') {
                    startRow = i;
                    startCol = j;
                }
            }
        }

        if (startRow != -1 && canReachTarget(grid, rows, cols, startRow, startCol)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Uses Breadth-First Search (BFS) to find if the target 'T' is reachable from 'S' 
     * within the allowed number of direction changes.
     *
     * @param grid      The grid containing 'S', 'T', '*', and '.'.
     * @param rows      The number of rows in the grid.
     * @param cols      The number of columns in the grid.
     * @param startRow  The row index of the starting point 'S'.
     * @param startCol  The column index of the starting point 'S'.
     * @return true if a valid path exists, false otherwise.
     */
    private static boolean canReachTarget(char[][] grid, int rows, int cols, int startRow, int startCol) {
        // Edge case: The starting position is the target
        if (grid[startRow][startCol] == 'T') {
            return true;
        }

        // visited[row][col][direction_ordinal][turn_count]
        // This ensures we don't process the same coordinate with the same direction and turn count twice.
        boolean[][][][] visited = new boolean[rows][cols][Direction.values().length][MAX_DIRECTION_CHANGES + 1];
        Queue<State> queue = new LinkedList<>();

        // Initialize queue by moving in all 4 directions from the start point 'S'
        for (Direction dir : Direction.values()) {
            int nextR = startRow + dir.dr;
            int nextC = startCol + dir.dc;

            if (isValid(nextR, nextC, rows, cols) && grid[nextR][nextC] != '*') {
                if (grid[nextR][nextC] == 'T') {
                    return true;
                }
                // The first movement establishes the initial direction and starts with 0 direction changes.
                if (!visited[nextR][nextC][dir.ordinal()][0]) {
                    visited[nextR][nextC][dir.ordinal()][0] = true;
                    queue.add(new State(nextR, nextC, dir, 0));
                }
            }
        }

        while (!queue.isEmpty()) {
            State current = queue.poll();

            for (Direction nextDir : Direction.values()) {
                int nextR = current.row + nextDir.dr;
                int nextC = current.col + nextDir.dc;

                // A turn is counted if the direction of movement changes
                int nextTurns = (nextDir == current.direction) ? current.turns : current.turns + 1;

                // Check bounds, obstacles, and the maximum allowed direction changes
                if (isValid(nextR, nextC, rows, cols) 
                        && grid[nextR][nextC] != '*' 
                        && nextTurns <= MAX_DIRECTION_CHANGES) {

                    // Goal check
                    if (grid[nextR][nextC] == 'T') {
                        return true;
                    }

                    // State check (Memoization)
                    if (!visited[nextR][nextC][nextDir.ordinal()][nextTurns]) {
                        visited[nextR][nextC][nextDir.ordinal()][nextTurns] = true;
                        queue.add(new State(nextR, nextC, nextDir, nextTurns));
                    }
                }
            }
        }

        return false;
    }

    /**
     * Validates if the given coordinates are within the grid boundaries.
     */
    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;
import java.util.StringTokenizer;

/**
 * A solver that determines if a target can be reached on a grid 
 * with a limited number of direction changes (turns).
 */
public class GridTurnSolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] grid = reader.readGrid(rows, cols);

            GridNavigator navigator = new GridNavigator(rows, cols, grid);
            boolean possible = navigator.canReachTargetWithMaxTurns(2);

            writer.println(possible ? "YES" : "NO");
        } catch (Exception e) {
            e.printStackTrace();
            System.exit(1);
        } finally {
            writer.close();
        }
    }

    /**
     * Represents a single state in the BFS: position and current direction.
     */
    private static class State {
        final int row;
        final int col;
        final int direction;

        State(int row, int col, int direction) {
            this.row = row;
            this.col = col;
            this.direction = direction;
        }
    }

    private static class GridNavigator {
        private static final int[] DR = {-1, 0, 1, 0}; // North, East, South, West
        private static final int[] DC = {0, 1, 0, -1};
        private static final int NUM_DIRECTIONS = 4;

        private final int rows;
        private final int cols;
        private final boolean[][] walkabilityMap;
        private final int startRow, startCol;
        private final int targetRow, targetCol;

        public GridNavigator(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.walkabilityMap = new boolean[rows][cols];

            int si = -1, sj = -1, ei = -1, ej = -1;

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    char c = grid[i][j];
                    if (c == '.' || c == 'S' || c == 'T') {
                        walkabilityMap[i][j] = true;
                    }
                    if (c == 'S') {
                        si = i; sj = j;
                    } else if (c == 'T') {
                        ei = i; ej = j;
                    }
                }
            }
            this.startRow = si;
            this.startCol = sj;
            this.targetRow = ei;
            this.targetCol = ej;
        }

        /**
         * Uses 0-1 BFS to find the minimum turns required to reach the target.
         * 
         * @param maxAllowedTurns The maximum number of direction changes allowed.
         * @return true if the target is reachable within the turn limit.
         */
        public boolean canReachTargetWithMaxTurns(int maxAllowedTurns) {
            // turns[dir][r][c] stores the min turns to reach (r, c) facing 'dir'
            int[][][] turns = new int[NUM_DIRECTIONS][rows][cols];
            for (int d = 0; d < NUM_DIRECTIONS; d++) {
                for (int i = 0; i < rows; i++) {
                    Arrays.fill(turns[d][i], Integer.MAX_VALUE);
                }
            }

            Deque<State> deque = new ArrayDeque<>();

            // Initialize: at start, we can face any direction with 0 turns
            for (int d = 0; d < NUM_DIRECTIONS; d++) {
                turns[d][startRow][startCol] = 0;
                deque.addLast(new State(startRow, startCol, d));
            }

            while (!deque.isEmpty()) {
                State current = deque.removeFirst();
                int r = current.row;
                int c = current.col;
                int d = current.direction;
                int currentTurns = turns[d][r][c];

                // Optimization: if we exceed the limit, this path is invalid for our query
                if (currentTurns > maxAllowedTurns) {
                    continue;
                }

                // 1. Try moving forward in the SAME direction (cost 0)
                int nr = r + DR[d];
                int nc = c + DC[d];
                if (isValidMove(nr, nc) && turns[d][nr][nc] > currentTurns) {
                    turns[d][nr][nc] = currentTurns;
                    deque.addFirst(new State(nr, nc, d));
                }

                // 2. Try changing to a DIFFERENT direction (cost 1)
                for (int nd = 0; nd < NUM_DIRECTIONS; nd++) {
                    if (nd != d && turns[nd][r][c] > currentTurns + 1) {
                        turns[nd][r][c] = currentTurns + 1;
                        deque.addLast(new State(r, c, nd));
                    }
                }
            }

            // Check if any direction at the target cell meets the turn criteria
            int minTurnsAtTarget = Integer.MAX_VALUE;
            for (int d = 0; d < NUM_DIRECTIONS; d++) {
                minTurnsAtTarget = Math.min(minTurnsAtTarget, turns[d][targetRow][targetCol]);
            }

            return minTurnsAtTarget <= maxAllowedTurns;
        }

        private boolean isValidMove(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols && walkabilityMap[r][c];
        }
    }

    /**
     * Utility class for fast I/O operations.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(java.io.InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public char[][] readGrid(int rows, int cols) throws IOException {
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }
            return grid;
        }
    }
}

import java.util.*;

/**
 * A program to find the minimum number of turns required to navigate a maze.
 * The goal is to reach a target 'T' from a starting point 'S' with at most 2 turns.
 */
public class MazeNavigator {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        Maze maze = new Maze(rows, cols);
        for (int i = 1; i <= rows; i++) {
            String line = scanner.next();
            for (int j = 1; j <= cols; j++) {
                char cell = line.charAt(j - 1);
                maze.setCell(i, j, cell);
            }
        }

        Pathfinder pathfinder = new Pathfinder(maze);
        boolean canReachWithMinimalTurns = pathfinder.findPath();

        System.out.println(canReachWithMinimalTurns ? "YES" : "NO");
        scanner.close();
    }

    /**
     * Represents the grid layout and its properties.
     */
    static class Maze {
        private final int rows;
        private final int cols;
        private final char[][] grid;
        private int startRow, startCol;
        private int targetRow, targetCol;

        private static final char WALL = '*';
        private static final char START = 'S';
        private static final char TARGET = 'T';

        public Maze(int rows, int cols) {
            this.rows = rows;
            this.cols = cols;
            // Padding of 1 to avoid boundary checks during traversal
            this.grid = new char[rows + 2][cols + 2];
            // Initialize grid with walls to provide a safe buffer
            for (int i = 0; i < rows + 2; i++) {
                Arrays.fill(grid[i], WALL);
            }
        }

        public void setCell(int r, int c, char value) {
            grid[r][c] = value;
            if (value == START) {
                startRow = r;
                startCol = c;
            } else if (value == TARGET) {
                targetRow = r;
                targetCol = c;
            }
        }

        public boolean isTraversable(int r, int c) {
            return grid[r][c] != WALL;
        }

        public int getRows() { return rows; }
        public int getCols() { return cols; }
        public int getStartRow() { return startRow; }
        public int getStartCol() { return startCol; }
        public int getTargetRow() { return targetRow; }
        public int getTargetCol() { return targetCol; }
    }

    /**
     * Represents directions of movement.
     */
    enum Direction {
        EAST(0, 1), SOUTH(1, 0), WEST(0, -1), NORTH(-1, 0);

        final int rowDelta;
        final int colDelta;

        Direction(int rowDelta, int colDelta) {
            this.rowDelta = rowDelta;
            this.colDelta = colDelta;
        }

        public static Direction fromOrdinal(int ordinal) {
            return values()[ordinal];
        }
    }

    /**
     * Represents a state in the Dijkstra search.
     */
    static class State implements Comparable<State> {
        final int row;
        final int col;
        final Direction direction;
        final int turns;

        public State(int row, int col, Direction direction, int turns) {
            this.row = row;
            this.col = col;
            this.direction = direction;
            this.turns = turns;
        }

        @Override
        public int compareTo(State other) {
            return Integer.compare(this.turns, other.turns);
        }
    }

    /**
     * Logic to find the shortest path (in terms of turns) using Dijkstra's algorithm.
     */
    static class Pathfinder {
        private final Maze maze;
        private static final int MAX_ALLOWED_TURNS = 2;
        private static final int INF = Integer.MAX_VALUE / 3;

        public Pathfinder(Maze maze) {
            this.maze = maze;
        }

        public boolean findPath() {
            // dist[direction_ordinal][row][col]
            int[][][] minTurns = new int[Direction.values().length][maze.getRows() + 2][maze.getCols() + 2];
            for (int[][] plane : minTurns) {
                for (int[] row : plane) {
                    Arrays.fill(row, INF);
                }
            }

            PriorityQueue<State> pq = new PriorityQueue<>();

            // Initialize starting positions for all directions
            for (Direction dir : Direction.values()) {
                minTurns[dir.ordinal()][maze.getStartRow()][maze.getStartCol()] = 0;
                pq.add(new State(maze.getStartRow(), maze.getStartCol(), dir, 0));
            }

            while (!pq.isEmpty()) {
                State current = pq.poll();

                if (current.turns > minTurns[current.direction.ordinal()][current.row][current.col]) {
                    continue;
                }

                // If we reached the target within turn limits
                if (current.row == maze.getTargetRow() && current.col == maze.getTargetCol()) {
                    if (current.turns <= MAX_ALLOWED_TURNS) {
                        return true;
                    }
                }

                // Explore all possible directions (including turning)
                for (Direction nextDir : Direction.values()) {
                    int nextRow = current.row + nextDir.rowDelta;
                    int nextCol = current.col + nextDir.colDelta;

                    if (maze.isTraversable(nextRow, nextCol)) {
                        // Cost is 1 if direction changes, 0 if continuing straight
                        int turnCost = (nextDir == current.direction) ? 0 : 1;
                        int newTurns = current.turns + turnCost;

                        if (newTurns < minTurns[nextDir.ordinal()][nextRow][nextCol]) {
                            minTurns[nextDir.ordinal()][nextRow][nextCol] = newTurns;
                            pq.add(new State(nextRow, nextCol, nextDir, newTurns));
                        }
                    }
                }
            }

            return false;
        }
    }
}

import java.util.Scanner;

/**
 * GridPathfinder solves the problem of finding a path from 'S' (Start) to 'T' (Target)
 * on a grid with a limited number of allowed direction changes (turns).
 */
public class GridPathfinder {

    private static final char START_CHAR = 'S';
    private static final char TARGET_CHAR = 'T';
    private static final char WALL_CHAR = '*';

    // Direction vectors: Up, Down, Left, Right
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    private final char[][] grid;
    private final int rows;
    private final int cols;

    // Memoization table: [direction][row][col][turns_taken]
    // Using byte for memory efficiency: 0 = unvisited, 1 = true, 2 = false
    private final byte[][][][] memo;
    private final boolean[][] visited;

    public GridPathfinder(char[][] grid) {
        this.grid = grid;
        this.rows = grid.length;
        this.cols = grid[0].length;
        this.memo = new byte[4][rows][cols][4];
        this.visited = new boolean[rows][cols];
    }

    /**
     * Orchestrates the pathfinding process.
     * @return true if a valid path exists, false otherwise.
     */
    public boolean solve() {
        int startR = -1;
        int startC = -1;

        // Locate the starting position
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == START_CHAR) {
                    startR = r;
                    startC = c;
                    break;
                }
            }
            if (startR != -1) break;
        }

        if (startR == -1) {
            return false;
        }

        // Try starting the path in all 4 possible directions
        for (int d = 0; d < 4; d++) {
            if (dfs(d, startR, startC, 0)) {
                return true;
            }
        }

        return false;
    }

    /**
     * Depth First Search to explore paths with turn constraints.
     * 
     * @param dir The direction used to arrive at the current cell.
     * @param r Current row index.
     * @param c Current column index.
     * @param turns Number of direction changes made so far.
     * @return true if the target is reachable from this state.
     */
    private boolean dfs(int dir, int r, int c, int turns) {
        // Constraint: Max 2 turns allowed (meaning max 3 straight segments)
        if (turns > 2) {
            return false;
        }

        // Base case: Target reached
        if (grid[r][c] == TARGET_CHAR) {
            return true;
        }

        // Memoization check
        if (memo[dir][r][c][turns] != 0) {
            return memo[dir][r][c][turns] == 1;
        }

        visited[r][c] = true;
        boolean canReach = false;

        // Explore all 4 neighbors
        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];

            if (isValidMove(nr, nc)) {
                int nextTurns = (dir == i) ? turns : turns + 1;
                if (dfs(i, nr, nc, nextTurns)) {
                    canReach = true;
                    break;
                }
            }
        }

        // Backtrack and store result in memo
        visited[r][c] = false;
        memo[dir][r][c][turns] = (byte) (canReach ? 1 : 2);
        return canReach;
    }

    private boolean isValidMove(int r, int c) {
        return r >= 0 && r < rows && 
               c >= 0 && c < cols && 
               grid[r][c] != WALL_CHAR && 
               !visited[r][c];
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int r = scanner.nextInt();
        int c = scanner.nextInt();
        scanner.nextLine(); // Consume the newline character left by nextInt()

        char[][] grid = new char[r][c];
        for (int i = 0; i < r; i++) {
            String line = scanner.nextLine();
            grid[i] = line.toCharArray();
        }

        GridPathfinder pathfinder = new GridPathfinder(grid);
        if (pathfinder.solve()) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * IgorToWork solves the problem of finding if a path exists from a starting point 'S' 
 * to a target point 'T' in a grid with obstacles '*' using at most 2 turns.
 */
public class IgorToWork {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] grid = reader.readGrid(rows, cols);

            MazeSolver solver = new MazeSolver(grid, rows, cols);

            if (solver.canReachTarget()) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }

        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Utility class for fast I/O operations.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
            tokenizer = new StringTokenizer("");
        }

        public String next() throws IOException {
            while (!tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public char[][] readGrid(int rows, int cols) throws IOException {
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = next();
                if (line != null) {
                    grid[i] = line.toCharArray();
                }
            }
            return grid;
        }
    }

    /**
     * Core logic for solving the maze traversal problem.
     */
    static class MazeSolver {
        private final char[][] grid;
        private final int rows;
        private final int cols;
        private final int startRow, startCol;
        private final int targetRow, targetCol;

        // Directions: North, West, South, East
        private static final int[] ROW_DIRECTIONS = {-1, 0, 1, 0};
        private static final int[] COL_DIRECTIONS = {0, -1, 0, 1};
        private static final int MAX_TURNS = 2;

        // Memoization table: [direction][turns_taken][row][col]
        private final boolean[][][][] visited;

        public MazeSolver(char[][] grid, int rows, int cols) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
            this.visited = new boolean[4][MAX_TURNS + 1][rows][cols];

            // Initialize start and target coordinates
            int sR = -1, sC = -1, tR = -1, tC = -1;
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == 'S') {
                        sR = r;
                        sC = c;
                    } else if (grid[r][c] == 'T') {
                        tR = r;
                        tC = c;
                    }
                }
            }
            this.startRow = sR;
            this.startCol = sC;
            this.targetRow = tR;
            this.targetCol = tC;
        }

        /**
         * Initiates the search for a valid path.
         * @return true if a path exists within the turn limit.
         */
        public boolean canReachTarget() {
            if (startRow == -1 || targetRow == -1) return false;

            // Try starting in each of the 4 possible directions
            for (int d = 0; d < 4; d++) {
                if (dfs(startRow, startCol, 0, d)) {
                    return true;
                }
            }
            return false;
        }

        /**
         * Depth First Search to explore the grid.
         * 
         * @param r Current row
         * @param c Current column
         * @param turns Number of turns taken so far
         * @param currentDir Direction used to arrive at the current cell
         * @return true if target is reachable
         */
        private boolean dfs(int r, int c, int turns, int currentDir) {
            // 1. Boundary and Obstacle Checks
            if (r < 0 || r >= rows || c < 0 || c >= cols || grid[r][c] == '*') {
                return false;
            }

            // 2. Turn Limit Check
            if (turns > MAX_TURNS) {
                return false;
            }

            // 3. Target Check
            if (r == targetRow && c == targetCol) {
                return true;
            }

            // 4. Memoization Check
            if (visited[currentDir][turns][r][c]) {
                return false;
            }

            // 5. Explore adjacent cells
            for (int d = 0; d < 4; d++) {
                int nextRow = r + ROW_DIRECTIONS[d];
                int nextCol = c + COL_DIRECTIONS[d];
                int nextTurns = turns + (d == currentDir ? 0 : 1);

                if (dfs(nextRow, nextCol, nextTurns, d)) {
                    return true;
                }
            }

            // Mark this state as explored and unsuccessful
            visited[currentDir][turns][r][c] = true;
            return false;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * MazeSolver finds if a target 'T' can be reached from a start 'S'
 * within a limited number of direction changes (turns) in a grid.
 */
public class MazeSolver {

    private static final char START_CHAR = 'S';
    private static final char TARGET_CHAR = 'T';
    private static final char WALL_CHAR = '*';
    private static final int MAX_ALLOWED_TURNS = 3;

    // Directional offsets: Down, Up, Left, Right
    private static final int[] ROW_OFFSETS = {1, -1, 0, 0};
    private static final int[] COL_OFFSETS = {0, 0, -1, 1};

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] grid = new char[rows][cols];

            int startRow = -1;
            int startCol = -1;

            for (int i = 0; i < rows; i++) {
                String line = reader.nextLine();
                grid[i] = line.toCharArray();
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == START_CHAR) {
                        startRow = i;
                        startCol = j;
                    }
                }
            }

            if (startRow != -1 && canReachTarget(grid, rows, cols, startRow, startCol)) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        } catch (Exception e) {
            // In a production environment, use a logger
            e.printStackTrace();
        } finally {
            out.close();
        }
    }

    /**
     * Performs a 0-1 BFS to find if the target is reachable within the turn limit.
     * A turn is defined as changing the current direction of movement.
     */
    private static boolean canReachTarget(char[][] grid, int rows, int cols, int startR, int startC) {
        Deque<Node> deque = new ArrayDeque<>();
        boolean[][][] visited = new boolean[rows][cols][4];

        // We try starting the journey by facing each of the 4 possible directions.
        // The first move in a direction doesn't count as a "turn".
        for (int dir = 0; dir < 4; dir++) {
            Node startNode = new Node(startR, startC, dir, 0);
            deque.addLast(startNode);
            // We don't mark the starting cell as visited for all directions yet,
            // but we allow the BFS to process from here.
        }

        while (!deque.isEmpty()) {
            Node current = deque.pollFirst();

            // Check if we reached the target
            if (grid[current.r][current.c] == TARGET_CHAR) {
                if (current.turns < MAX_ALLOWED_TURNS) {
                    return true;
                }
                continue; 
            }

            for (int i = 0; i < 4; i++) {
                int nextR = current.r + ROW_OFFSETS[i];
                int nextC = current.c + COL_OFFSETS[i];

                if (isValidMove(grid, rows, cols, nextR, nextC)) {
                    int nextTurns = current.turns + (i == current.dir ? 0 : 1);

                    // If turn count is within limit and we haven't visited this state (pos + dir)
                    if (nextTurns < MAX_ALLOWED_TURNS && !visited[nextR][nextC][i]) {
                        // If we reach the target, we don't mark it visited in a way 
                        // that prevents other paths from checking the turn condition.
                        if (grid[nextR][nextC] != TARGET_CHAR) {
                            visited[nextR][nextC][i] = true;
                        }

                        Node nextNode = new Node(nextR, nextC, i, nextTurns);

                        // 0-1 BFS: If weight is 0 (same direction), add to front. Else add to back.
                        if (i == current.dir) {
                            deque.addFirst(nextNode);
                        } else {
                            deque.addLast(nextNode);
                        }
                    }
                }
            }
        }

        return false;
    }

    private static boolean isValidMove(char[][] grid, int rows, int cols, int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] != WALL_CHAR;
    }

    /**
     * Represents a state in the BFS traversal.
     */
    private static class Node {
        final int r, c, dir, turns;

        Node(int r, int c, int dir, int turns) {
            this.r = r;
            this.c = c;
            this.dir = dir;
            this.turns = turns;
        }
    }

    /**
     * Efficient input reader for competitive programming scenarios.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public String nextLine() {
            if (tokenizer != null && tokenizer.hasMoreElements()) {
                StringBuilder sb = new StringBuilder();
                while (tokenizer.hasMoreElements()) {
                    sb.append(tokenizer.nextToken());
                    if (tokenizer.hasMoreElements()) sb.append(" ");
                }
                tokenizer = null;
                return sb.toString();
            }
            try {
                return reader.readLine();
            } catch (IOException e) {
                return null;
            }
        }
    }
}

import java.util.*;

/**
 * A program that determines if a target 'T' can be reached from a start 'S'
 * within a maximum of 2 direction changes in a grid.
 */
public class TurnPathfinder {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        char[][] grid = new char[rows][cols];

        int startRow = -1;
        int startCol = -1;

        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] == 'S') {
                    startRow = i;
                    startCol = j;
                }
            }
        }

        GridNavigator navigator = new GridNavigator(grid, rows, cols);
        boolean reachable = navigator.canReachTargetWithMaxTurns(startRow, startCol, 2);

        System.out.println(reachable ? "YES" : "NO");
        scanner.close();
    }

    /**
     * Handles the navigation logic within the grid.
     */
    static class GridNavigator {
        private final char[][] grid;
        private final int rows;
        private final int cols;

        private static final char OBSTACLE = '*';
        private static final char TARGET = 'T';
        private static final char START = 'S';

        public GridNavigator(char[][] grid, int rows, int cols) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
        }

        /**
         * Uses 0-1 BFS to find the minimum number of turns required to reach the target.
         * 
         * @param startR Starting row index
         * @param startC Starting column index
         * @param maxTurns Maximum allowed direction changes
         * @return true if target is reachable within maxTurns, false otherwise
         */
        public boolean canReachTargetWithMaxTurns(int startR, int startC, int maxTurns) {
            // minTurnsAtState[row][col][direction] stores minimum turns to reach cell 
            // while facing a specific direction.
            int[][][] minTurnsAtState = new int[rows][cols][Direction.values().length];
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    Arrays.fill(minTurnsAtState[i][j], Integer.MAX_VALUE);
                }
            }

            Deque<State> deque = new ArrayDeque<>();

            // Initialize starting position: facing any direction costs 0 turns.
            for (Direction dir : Direction.values()) {
                minTurnsAtState[startR][startC][dir.ordinal()] = 0;
                deque.addLast(new State(startR, startC, dir, 0));
            }

            while (!deque.isEmpty()) {
                State current = deque.pollFirst();

                // If we reached target within allowed turns
                if (grid[current.row][current.col] == TARGET && current.turns <= maxTurns) {
                    return true;
                }

                // If we already found a better way to this state, skip
                if (current.turns > minTurnsAtState[current.row][current.col][current.direction.ordinal()]) {
                    continue;
                }

                for (Direction nextDir : Direction.values()) {
                    int nextRow = current.row + nextDir.dr;
                    int nextCol = current.col + nextDir.dc;

                    if (isValidMove(nextRow, nextCol)) {
                        int turnCost = (nextDir == current.direction) ? 0 : 1;
                        int newTurns = current.turns + turnCost;

                        if (newTurns <= maxTurns && newTurns < minTurnsAtState[nextRow][nextCol][nextDir.ordinal()]) {
                            minTurnsAtState[nextRow][nextCol][nextDir.ordinal()] = newTurns;

                            // 0-1 BFS optimization: 0-weight edges to front, 1-weight to back
                            if (turnCost == 0) {
                                deque.addFirst(new State(nextRow, nextCol, nextDir, newTurns));
                            } else {
                                deque.addLast(new State(nextRow, nextCol, nextDir, newTurns));
                            }
                        }
                    }
                }
            }

            return false;
        }

        private boolean isValidMove(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] != OBSTACLE;
        }
    }

    /**
     * Represents a specific movement direction and its coordinate offsets.
     */
    enum Direction {
        RIGHT(0, 1), DOWN(1, 0), UP(-1, 0), LEFT(0, -1);

        final int dr, dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }
    }

    /**
     * Represents the state of the navigator at a specific point in time.
     */
    static class State {
        final int row;
        final int col;
        final Direction direction;
        final int turns;

        State(int row, int col, Direction direction, int turns) {
            this.row = row;
            this.col = col;
            this.direction = direction;
            this.turns = turns;
        }
    }
}

import java.util.Scanner;

/**
 * A program to find if a path exists in a grid from 'S' to 'T'
 * with a limited number of turns allowed.
 */
public class GridPathfinder {

    // The maximum number of turns allowed is 2 (resulting in up to 3 straight segments).
    private static final int MAX_TURNS = 2;

    /**
     * Represents the four possible movement directions in the grid.
     */
    private enum Direction {
        UP(0, -1),
        RIGHT(1, 0),
        DOWN(0, 1),
        LEFT(-1, 0);

        final int dx, dy;

        Direction(int dx, int dy) {
            this.dx = dx;
            this.dy = dy;
        }
    }

    private final int rows;
    private final int cols;
    private final char[][] grid;

    /**
     * Memoization table to store states that have already been explored and failed.
     * State is defined by: [row][column][current_turn_count][direction_index].
     */
    private final boolean[][][][] failedStates;

    public GridPathfinder(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.failedStates = new boolean[rows][cols][MAX_TURNS + 1][Direction.values().length];
    }

    /**
     * Initiates the pathfinding search from the starting position.
     *
     * @param startR The starting row index.
     * @param startC The starting column index.
     * @return true if the target 'T' is reachable, false otherwise.
     */
    public boolean findPath(int startR, int startC) {
        // Attempt to move in all 4 initial directions from the starting cell.
        for (Direction d : Direction.values()) {
            if (dfs(startR, startC, 0, d)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Depth-First Search to explore paths.
     *
     * @param r The current row index.
     * @param c The current column index.
     * @param turn The number of turns made so far.
     * @param dir The direction the search is currently attempting to move.
     * @return true if the target 'T' is reached.
     */
    private boolean dfs(int r, int c, int turn, Direction dir) {
        int nextR = r + dir.dy;
        int nextC = c + dir.dx;

        // 1. Boundary Check
        if (nextR < 0 || nextR >= rows || nextC < 0 || nextC >= cols) {
            return false;
        }

        // 2. Obstacle Check
        if (grid[nextR][nextC] == '*') {
            return false;
        }

        // 3. Target Check
        if (grid[nextR][nextC] == 'T') {
            return true;
        }

        // 4. Memoization Check
        // We check if this specific state (position, turn count, and direction) has already failed.
        int dirIdx = dir.ordinal();
        if (failedStates[r][c][turn][dirIdx]) {
            return false;
        }

        // Mark this state as explored.
        failedStates[r][c][turn][dirIdx] = true;

        // 5. Path Tracking (Backtracking)
        // Mark the next cell as visited in the current path to prevent cycles.
        char originalChar = grid[nextR][nextC];
        grid[nextR][nextC] = '*';

        // Option A: Continue moving in the same direction (no turn increment).
        if (dfs(nextR, nextC, turn, dir)) {
            return true;
        }

        // Option B: Turn to a different direction (if turns are still available).
        if (turn < MAX_TURNS) {
            for (Direction nextDir : Direction.values()) {
                if (nextDir != dir) {
                    if (dfs(nextR, nextC, turn + 1, nextDir)) {
                        return true;
                    }
                }
            }
        }

        // Backtrack: Restore the cell for other potential search paths.
        grid[nextR][nextC] = originalChar;

        return false;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }

        int n = scanner.nextInt(); // Rows
        int m = scanner.nextInt(); // Columns
        scanner.nextLine();        // Consume the leftover newline character

        char[][] grid = new char[n][m];
        int startR = -1;
        int startC = -1;

        for (int i = 0; i < n; i++) {
            String line = scanner.nextLine();
            for (int j = 0; j < m; j++) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] == 'S') {
                    startR = i;
                    startC = j;
                }
            }
        }

        // Perform the search if a starting point was found.
        if (startR != -1 && startC != -1) {
            GridPathfinder pathfinder = new GridPathfinder(n, m, grid);
            if (pathfinder.findPath(startR, startC)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }
}

import java.io.*;
import java.util.*;

/**
 * A solution to find if a path exists between a start and target point 
 * in a grid with a maximum number of turns allowed.
 */
public class PathfindingSolution {

    private static final int MAX_ALLOWED_TURNS = 2;

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            char[][] grid = new char[rows][cols];
            int startRow = -1, startCol = -1;
            int targetRow = -1, targetCol = -1;

            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                    if (grid[i][j] == 'S') {
                        startRow = i;
                        startCol = j;
                    } else if (grid[i][j] == 'T') {
                        targetRow = i;
                        targetCol = j;
                    }
                }
            }

            PathFinder pathFinder = new PathFinder(grid, rows, cols);
            boolean isReachable = pathFinder.canReachTarget(startRow, startCol, targetRow, targetCol);

            out.println(isReachable ? "YES" : "NO");

        } catch (IOException e) {
            out.println("ERROR: " + e.getMessage());
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Represents the possible movement directions in the grid.
     */
    enum Direction {
        DOWN(1, 0),
        RIGHT(0, 1),
        UP(-1, 0),
        LEFT(0, -1);

        final int dr, dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }

        public static Direction fromOrdinal(int ordinal) {
            return Direction.values()[ordinal];
        }
    }

    /**
     * Represents the state of the search at a specific cell.
     */
    static class State {
        final int r, c;
        final Direction dir;
        final int turns;

        State(int r, int c, Direction dir, int turns) {
            this.r = r;
            this.c = c;
            this.dir = dir;
            this.turns = turns;
        }
    }

    /**
     * Logic for navigating the grid.
     */
    static class PathFinder {
        private final char[][] grid;
        private final int rows;
        private final int cols;

        public PathFinder(char[][] grid, int rows, int cols) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
        }

        /**
         * Uses 0-1 BFS to find if the target is reachable within MAX_ALLOWED_TURNS.
         */
        public boolean canReachTarget(int startRow, int startCol, int targetRow, int targetCol) {
            if (startRow == targetRow && startCol == targetCol) {
                return true;
            }

            // minTurnsAtState[row][col][direction_ordinal]
            int[][][] minTurnsAtState = new int[rows][cols][Direction.values().length];
            for (int[][] row : minTurnsAtState) {
                for (int[] cell : row) {
                    Arrays.fill(cell, Integer.MAX_VALUE);
                }
            }

            Deque<State> deque = new ArrayDeque<>();

            // Initialize search by moving in all 4 directions from the starting point
            for (Direction d : Direction.values()) {
                int nr = startRow + d.dr;
                int nc = startCol + d.dc;

                if (isValid(nr, nc)) {
                    minTurnsAtState[nr][nc][d.ordinal()] = 0;
                    deque.addLast(new State(nr, nc, d, 0));
                }
            }

            while (!deque.isEmpty()) {
                State current = deque.pollFirst();

                if (current.r == targetRow && current.c == targetCol) {
                    return true;
                }

                // If we found a better way to reach this state already, skip
                if (current.turns > minTurnsAtState[current.r][current.c][current.dir.ordinal()]) {
                    continue;
                }

                for (Direction nextDir : Direction.values()) {
                    int nr = current.r + nextDir.dr;
                    int nc = current.c + nextDir.dc;

                    if (isValid(nr, nc)) {
                        int turnCost = (nextDir == current.dir) ? 0 : 1;
                        int nextTurns = current.turns + turnCost;

                        if (nextTurns <= MAX_ALLOWED_TURNS && nextTurns < minTurnsAtState[nr][nc][nextDir.ordinal()]) {
                            minTurnsAtState[nr][nc][nextDir.ordinal()] = nextTurns;

                            // 0-1 BFS logic: 
                            // If cost is 0 (straight), add to front to process immediately.
                            // If cost is 1 (turn), add to back.
                            if (turnCost == 0) {
                                deque.addFirst(new State(nr, nc, nextDir, nextTurns));
                            } else {
                                deque.addLast(new State(nr, nc, nextDir, nextTurns));
                            }
                        }
                    }
                }
            }

            return false;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] != '*';
        }
    }

    /**
     * Utility for fast input reading.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the Grid Reachability Problem.
 * The goal is to determine if a target cell 'T' can be reached from a starting cell 'S'
 * via signal propagation along rows and columns within 3 moves.
 */
public class GridReachabilitySolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] grid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            GridSolver solver = new GridSolver(grid, rows, cols);
            boolean isTargetReachable = solver.solve(3);

            out.println(isTargetReachable ? "YES" : "NO");
        } catch (Exception e) {
            // In a production environment, use a logger.
            e.printStackTrace();
        } finally {
            out.close();
        }
    }

    /**
     * Handles the logic of the grid-based signal propagation.
     */
    static class GridSolver {
        private static final char START_CHAR = 'S';
        private static final char TARGET_CHAR = 'T';
        private static final char OBSTACLE_CHAR = '*';

        private final char[][] grid;
        private final int rows;
        private final int cols;

        public GridSolver(char[][] grid, int rows, int cols) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
        }

        /**
         * Simulates the propagation for a specific number of moves.
         * 
         * @param maxMoves The number of propagation steps to perform.
         * @return true if the target 'T' is reachable.
         */
        public boolean solve(int maxMoves) {
            boolean[][] reachable = initializeReachability();

            for (int move = 0; move < maxMoves; move++) {
                reachable = performPropagationStep(reachable);
            }

            return checkTargetReached(reachable);
        }

        private boolean[][] initializeReachability() {
            boolean[][] reachable = new boolean[rows][cols];
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == START_CHAR) {
                        reachable[i][j] = true;
                    }
                }
            }
            return reachable;
        }

        /**
         * Performs one full move consisting of horizontal and vertical sweeps.
         */
        private boolean[][] performPropagationStep(boolean[][] currentReachable) {
            boolean[][] nextReachable = new boolean[rows][cols];

            // 1. Horizontal sweeps (Left-to-Right and Right-to-Left)
            for (int r = 0; r < rows; r++) {
                sweepLine(currentReachable, nextReachable, r, true);  // L -> R
                sweepLine(currentReachable, nextReachable, r, false); // R -> L
            }

            // 2. Vertical sweeps (Top-to-Bottom and Bottom-to-Top)
            for (int c = 0; c < cols; c++) {
                sweepLineVertical(currentReachable, nextReachable, c, true);  // T -> B
                sweepLineVertical(currentReachable, nextReachable, c, false); // B -> T
            }

            return nextReachable;
        }

        private void sweepLine(boolean[][] current, boolean[][] next, int row, boolean forward) {
            boolean signalActive = false;
            if (forward) {
                for (int c = 0; c < cols; c++) {
                    signalActive = updateSignal(current[row][c], grid[row][c], signalActive);
                    if (signalActive) next[row][c] = true;
                }
            } else {
                for (int c = cols - 1; c >= 0; c--) {
                    signalActive = updateSignal(current[row][c], grid[row][c], signalActive);
                    if (signalActive) next[row][c] = true;
                }
            }
        }

        private void sweepLineVertical(boolean[][] current, boolean[][] next, int col, boolean forward) {
            boolean signalActive = false;
            if (forward) {
                for (int r = 0; r < rows; r++) {
                    signalActive = updateSignal(current[r][col], grid[r][col], signalActive);
                    if (signalActive) next[r][col] = true;
                }
            } else {
                for (int r = rows - 1; r >= 0; r--) {
                    signalActive = updateSignal(current[r][col], grid[r][col], signalActive);
                    if (signalActive) next[r][col] = true;
                }
            }
        }

        private boolean updateSignal(boolean cellIsReachable, char cellChar, boolean currentSignal) {
            // Signal activates if the cell itself was reachable or if it's being passed through
            boolean active = currentSignal || cellIsReachable;
            // Signal is blocked by obstacles
            if (cellChar == OBSTACLE_CHAR) {
                active = false;
            }
            return active;
        }

        private boolean checkTargetReached(boolean[][] reachable) {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (reachable[i][j] && grid[i][j] == TARGET_CHAR) {
                        return true;
                    }
                }
            }
            return false;
        }
    }

    /**
     * Fast I/O utility for efficient reading of input data.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Solves a maze navigation problem to determine if a target 'T' can be reached 
 * from a starting point 'S' with a maximum of 2 turns.
 */
public class MazeSolver {

    private static final int MAX_TURNS = 2;
    private static final int DIRECTION_NONE = 4;

    // Direction vectors: Down, Up, Right, Left
    private static final int[] DR = {1, -1, 0, 0};
    private static final int[] DC = {0, 0, 1, -1};

    private final int rows;
    private final int cols;
    private final char[][] maze;
    private final boolean[][][][] visited;

    public MazeSolver(int rows, int cols, char[][] maze) {
        this.rows = rows;
        this.cols = cols;
        this.maze = maze;
        // visited[row][col][turnsUsed][lastDirection]
        this.visited = new boolean[rows][cols][MAX_TURNS + 1][5];
    }

    /**
     * Initiates the Depth First Search to find the target.
     */
    public boolean solve() {
        int startRow = -1;
        int startCol = -1;

        // Find starting position 'S'
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (maze[i][j] == 'S') {
                    startRow = i;
                    startCol = j;
                    break;
                }
            }
        }

        if (startRow == -1) return false;

        return dfs(startRow, startCol, 0, DIRECTION_NONE);
    }

    private boolean dfs(int r, int c, int turns, int lastDir) {
        // Base Case: Target reached
        if (maze[r][c] == 'T') {
            return true;
        }

        // Memoization: If this state has been visited, prune this branch
        if (visited[r][c][turns][lastDir]) {
            return false;
        }
        visited[r][c][turns][lastDir] = true;

        for (int i = 0; i < 4; i++) {
            int nextR = r + DR[i];
            int nextC = c + DC[i];

            if (isValidMove(nextR, nextC, turns, lastDir, i)) {
                int nextTurns = turns + (isTurn(lastDir, i) ? 1 : 0);
                if (dfs(nextR, nextC, nextTurns, i)) {
                    return true;
                }
            }
        }

        return false;
    }

    private boolean isValidMove(int r, int c, int currentTurns, int lastDir, int nextDir) {
        // Check boundaries
        if (r < 0 || r >= rows || c < 0 || c >= cols) {
            return false;
        }
        // Check obstacles
        if (maze[r][c] == '*') {
            return false;
        }
        // Check turn limit
        if (isTurn(lastDir, nextDir) && currentTurns >= MAX_TURNS) {
            return false;
        }
        return true;
    }

    /**
     * Determines if changing from lastDir to nextDir constitutes a turn.
     * A turn occurs when moving from vertical to horizontal or vice versa.
     */
    private boolean isTurn(int lastDir, int nextDir) {
        if (lastDir == DIRECTION_NONE) {
            return false;
        }
        boolean lastWasVertical = (lastDir == 0 || lastDir == 1);
        boolean nextIsVertical = (nextDir == 0 || nextDir == 1);
        return lastWasVertical != nextIsVertical;
    }

    public static void main(String[] args) {
        try (FastScanner sc = new FastScanner(System.in)) {
            int n = sc.nextInt();
            int m = sc.nextInt();
            char[][] grid = new char[n][m];

            for (int i = 0; i < n; i++) {
                grid[i] = sc.next().toCharArray();
            }

            MazeSolver solver = new MazeSolver(n, m, grid);
            System.out.println(solver.solve() ? "YES" : "NO");
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * Efficient input reader for large datasets.
     */
    static class FastScanner implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(java.io.InputStream is) {
            this.reader = new BufferedReader(new InputStreamReader(is));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        @Override
        public void close() throws IOException {
            reader.close();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A refactored solution to find the minimum number of straight-line segments 
 * required to travel from a starting point to a target point in a maze.
 * 
 * This implementation uses a 0-1 Breadth-First Search (BFS) to efficiently 
 * find the shortest path in terms of direction changes (segments).
 */
public class MazeSolver {

    private static final int[] DIRECTION_ROW = {0, 1, 0, -1};
    private static final int[] DIRECTION_COL = {1, 0, -1, 0};
    private static final int MAX_SEGMENTS_ALLOWED = 3;

    public static void main(String[] args) {
        try {
            InputReader in = new InputReader(System.in);
            PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

            int rows = in.nextInt();
            int cols = in.nextInt();

            boolean[][] grid = new boolean[rows][cols];
            int startRow = -1, startCol = -1;
            int targetRow = -1, targetCol = -1;

            for (int i = 0; i < rows; i++) {
                String line = in.next();
                for (int j = 0; j < cols; j++) {
                    char cell = line.charAt(j);
                    if (cell == 'S') {
                        startRow = i;
                        startCol = j;
                        grid[i][j] = true;
                    } else if (cell == 'T') {
                        targetRow = i;
                        targetCol = j;
                        grid[i][j] = true;
                    } else if (cell == '.') {
                        grid[i][j] = true;
                    } else if (cell == '*') {
                        grid[i][j] = false;
                    }
                }
            }

            if (canReachTarget(rows, cols, grid, startRow, startCol, targetRow, targetCol)) {
                out.println("YES");
            } else {
                out.println("NO");
            }

            out.flush();
            out.close();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * Determines if the target can be reached from the start using at most 
     * MAX_SEGMENTS_ALLOWED segments.
     *
     * @param rows Total number of rows in the maze.
     * @param cols Total number of columns in the maze.
     * @param grid A boolean grid where true represents a walkable cell.
     * @param startR Starting row index.
     * @param startC Starting column index.
     * @param targetR Target row index.
     * @param targetC Target column index.
     * @return true if reachable within the segment limit, false otherwise.
     */
    private static boolean canReachTarget(int rows, int cols, boolean[][] grid, 
                                          int startR, int startC, 
                                          int targetR, int targetC) {

        if (startR == targetR && startC == targetC) {
            return true;
        }

        // dist[r][c][dir] stores the minimum segments used to reach cell (r, c) 
        // arriving via direction 'dir'.
        int[][][] dist = new int[rows][cols][4];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                Arrays.fill(dist[i][j], Integer.MAX_VALUE);
            }
        }

        Deque<State> deque = new ArrayDeque<>();

        // Initialization: Starting from S, explore the first segment in all 4 directions.
        for (int d = 0; d < 4; d++) {
            int nr = startR + DIRECTION_ROW[d];
            int nc = startC + DIRECTION_COL[d];

            if (isValid(nr, nc, rows, cols, grid)) {
                dist[nr][nc][d] = 1;
                deque.addLast(new State(nr, nc, d, 1));
            }
        }

        while (!deque.isEmpty()) {
            State curr = deque.removeFirst();

            // If we reached the target, check if it's within the segment budget.
            if (curr.r == targetR && curr.c == targetC) {
                if (curr.segments <= MAX_SEGMENTS_ALLOWED) {
                    return true;
                }
                // Even if we reach the target, we continue to see if other paths are shorter.
                continue; 
            }

            // Pruning: if current segments already exceed the allowed limit, stop exploring this path.
            if (curr.segments >= MAX_SEGMENTS_ALLOWED) {
                continue;
            }

            // Optimization: if we found a better way to reach this state already, skip.
            if (curr.segments > dist[curr.r][curr.c][curr.dir]) {
                continue;
            }

            // Option 1: Continue in the same direction (Cost = 0 additional segments).
            int nrSame = curr.r + DIRECTION_ROW[curr.dir];
            int ncSame = curr.c + DIRECTION_COL[curr.dir];
            if (isValid(nrSame, ncSame, rows, cols, grid)) {
                if (dist[nrSame][ncSame][curr.dir] > curr.segments) {
                    dist[nrSame][ncSame][curr.dir] = curr.segments;
                    deque.addFirst(new State(nrSame, ncSame, curr.dir, curr.segments));
                }
            }

            // Option 2: Turn to a different direction (Cost = 1 additional segment).
            for (int d = 0; d < 4; d++) {
                if (d == curr.dir) continue;

                int nrTurn = curr.r + DIRECTION_ROW[d];
                int ncTurn = curr.c + DIRECTION_COL[d];

                if (isValid(nrTurn, ncTurn, rows, cols, grid)) {
                    int nextSegments = curr.segments + 1;
                    if (nextSegments <= MAX_SEGMENTS_ALLOWED && dist[nrTurn][ncTurn][d] > nextSegments) {
                        dist[nrTurn][ncTurn][d] = nextSegments;
                        deque.addLast(new State(nrTurn, ncTurn, d, nextSegments));
                    }
                }
            }
        }

        return false;
    }

    private static boolean isValid(int r, int c, int rows, int cols, boolean[][] grid) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c];
    }

    /**
     * Represents a state in the BFS traversal.
     */
    private static class State {
        final int r, c, dir, segments;

        State(int r, int c, int dir, int segments) {
            this.r = r;
            this.c = c;
            this.dir = dir;
            this.segments = segments;
        }
    }

    /**
     * Fast I/O utility class.
     */
    private static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;

/**
 * A program that finds if a target 'T' is reachable from a start 'S' 
 * on a grid with a specific constraint on the number of turns allowed.
 */
public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        Grid grid = new Grid(rows, cols);
        int startX = 0, startY = 0, endX = 0, endY = 0;

        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            for (int j = 0; j < cols; j++) {
                char cell = line.charAt(j);
                if (cell == 'S') {
                    startX = i;
                    startY = j;
                    grid.setWalkable(i, j, true);
                } else if (cell == 'T') {
                    endX = i;
                    endY = j;
                    grid.setWalkable(i, j, true);
                } else if (cell == '.') {
                    grid.setWalkable(i, j, true);
                } else {
                    grid.setWalkable(i, j, false);
                }
            }
        }

        Pathfinder pathfinder = new Pathfinder(grid);
        boolean isReachable = pathfinder.findPath(startX, startY, endX, endY);

        System.out.println(isReachable ? "YES" : "NO");
        scanner.close();
    }
}

/**
 * Represents the traversable grid.
 */
class Grid {
    private final int rows;
    private final int cols;
    private final boolean[][] walkable;

    public Grid(int rows, int cols) {
        this.rows = rows;
        this.cols = cols;
        this.walkable = new boolean[rows][cols];
    }

    public void setWalkable(int r, int c, boolean isWalkable) {
        walkable[r][c] = isWalkable;
    }

    public boolean isWalkable(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols && walkable[r][c];
    }

    public int getRows() {
        return rows;
    }

    public int getCols() {
        return cols;
    }
}

/**
 * Represents the state of the search at a specific point.
 */
class State {
    final int x;
    final int y;
    final int direction;
    final int turnCount;

    public State(int x, int y, int direction, int turnCount) {
        this.x = x;
        this.y = y;
        this.direction = direction;
        this.turnCount = turnCount;
    }
}

/**
 * Handles the BFS pathfinding logic.
 */
class Pathfinder {
    // Direction vectors: Right, Down, Left, Up
    private static final int[][] DIRECTIONS = {
        {0, 1}, 
        {1, 0}, 
        {0, -1}, 
        {-1, 0}
    };

    private final Grid grid;

    public Pathfinder(Grid grid) {
        this.grid = grid;
    }

    /**
     * Performs a BFS to determine if the end coordinate is reachable.
     * 
     * @param sx Start X coordinate
     * @param sy Start Y coordinate
     * @param ex End X coordinate
     * @param ey End Y coordinate
     * @return true if target is reached, false otherwise
     */
    public boolean findPath(int sx, int sy, int ex, int ey) {
        int rows = grid.getRows();
        int cols = grid.getCols();

        // minTurns[x][y] tracks the minimum turns required to reach a cell.
        int[][] minTurns = new int[rows][cols];
        for (int[] row : minTurns) {
            Arrays.fill(row, Integer.MAX_VALUE);
        }

        Deque<State> queue = new ArrayDeque<>();

        // Initialize starting position for all 4 possible initial directions
        minTurns[sx][sy] = 0;
        for (int d = 0; d < 4; d++) {
            queue.add(new State(sx, sy, d, 0));
        }

        while (!queue.isEmpty()) {
            State current = queue.poll();

            // Target reached check
            if (current.x == ex && current.y == ey) {
                return true;
            }

            // 1. Attempt to move forward in the current direction
            int nextX = current.x + DIRECTIONS[current.direction][0];
            int nextY = current.y + DIRECTIONS[current.direction][1];

            if (grid.isWalkable(nextX, nextY) && minTurns[nextX][nextY] >= current.turnCount) {
                minTurns[nextX][nextY] = current.turnCount;
                queue.add(new State(nextX, nextY, current.direction, current.turnCount));
            }

            // 2. Attempt to turn (only allowed if current turn count < 2)
            if (current.turnCount < 2) {
                // Possible turns are clockwise (p+1) and counter-clockwise (p-1)
                int[] turnDirections = {
                    (current.direction + 1) % 4,
                    (current.direction + 3) % 4
                };

                for (int nextDir : turnDirections) {
                    int tx = current.x + DIRECTIONS[nextDir][0];
                    int ty = current.y + DIRECTIONS[nextDir][1];

                    if (grid.isWalkable(tx, ty) && minTurns[tx][ty] >= current.turnCount + 1) {
                        minTurns[tx][ty] = current.turnCount + 1;
                        queue.add(new State(tx, ty, nextDir, current.turnCount + 1));
                    }
                }
            }
        }

        return false;
    }
}

import java.io.*;
import java.util.*;

/**
 * A refactored solution for the grid navigation problem.
 * This program determines if a target 'T' is reachable from a start 'S' 
 * within a limited number of direction changes (turns).
 */
public class Main {

    public static void main(String[] args) {
        try (InputStream inputStream = System.in;
             PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)))) {

            FastReader reader = new FastReader(inputStream);
            GridSolver solver = new GridSolver();
            solver.solve(reader, out);

        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * Handles the core logic of the grid navigation problem.
     */
    static class GridSolver {
        // Directions: Right, Down, Left, Up
        private static final int[] DR = {0, 1, 0, -1};
        private static final int[] DC = {1, 0, -1, 0};

        // Memoization states
        private static final byte UNVISITED = 0;
        private static final byte REACHABLE = 1;
        private static final byte UNREACHABLE = 2;

        private char[][] grid;
        private int rows;
        private int cols;
        private byte[][][][] memo;

        /**
         * Solves a single test case.
         * 
         * @param in  The fast input reader.
         * @param out The print writer for output.
         */
        public void solve(FastReader in, PrintWriter out) {
            this.rows = in.nextInt();
            this.cols = in.nextInt();
            this.grid = new char[rows][cols];

            int startRow = -1;
            int startCol = -1;

            for (int i = 0; i < rows; i++) {
                String line = in.next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                    if (grid[i][j] == 'S') {
                        startRow = i;
                        startCol = j;
                    }
                }
            }

            // If no starting position is found, target is unreachable
            if (startRow == -1) {
                out.println("NO");
                return;
            }

            // Memoization table: [row][col][direction][turns_left]
            // Max turns is 2, so size 3 is sufficient.
            this.memo = new byte[rows][cols][4][3];

            // Try starting in all 4 possible directions.
            // The first direction doesn't cost a turn, but subsequent changes do.
            boolean possible = false;
            for (int d = 0; d < 4; d++) {
                if (canReachTarget(startRow, startCol, d, 2)) {
                    possible = true;
                    break;
                }
            }

            out.println(possible ? "YES" : "NO");
        }

        /**
         * Depth-First Search with memoization to find if the target is reachable.
         *
         * @param r          Current row.
         * @param c          Current column.
         * @param currentDir The direction we are currently facing.
         * @param turnsLeft  Remaining turns allowed.
         * @return true if the target 'T' is reachable from this state.
         */
        private boolean canReachTarget(int r, int c, int currentDir, int turnsLeft) {
            // Boundary and obstacle checks
            if (r < 0 || r >= rows || c < 0 || c >= cols || grid[r][c] == '*') {
                return false;
            }

            // Check if target reached
            if (grid[r][c] == 'T') {
                return true;
            }

            // Check memoization table
            if (memo[r][c][currentDir][turnsLeft] != UNVISITED) {
                return memo[r][c][currentDir][turnsLeft] == REACHABLE;
            }

            boolean reachable = false;

            // Explore all 4 possible next directions
            for (int d = 0; d < 4; d++) {
                int nextR = r + DR[d];
                int nextC = c + DC[d];

                // If the direction is different from current, it costs one turn
                int nextTurns = (d == currentDir) ? turnsLeft : turnsLeft - 1;

                if (nextTurns >= 0) {
                    if (canReachTarget(nextR, nextC, d, nextTurns)) {
                        reachable = true;
                        break;
                    }
                }
            }

            // Store result in memo table
            memo[r][c][currentDir][turnsLeft] = (byte) (reachable ? REACHABLE : UNREACHABLE);
            return reachable;
        }
    }

    /**
     * High-performance input reader for reading large amounts of data.
     */
    static class FastReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024 * 8];
        private int curChar;
        private int numChars;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (numChars == -1) return -1;
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buffer);
                } catch (IOException e) {
                    return -1;
                }
                if (numChars <= 0) return -1;
            }
            return buffer[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res = res * 10 + (c - '0');
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * MazePathfinder solves a grid-based pathfinding problem where movement is constrained
 * by a maximum number of turns allowed.
 */
public class MazePathfinder {

    // Directional movement vectors: Right, Down, Left, Up
    private static final int[] ROW_OFFSETS = {0, 1, 0, -1};
    private static final int[] COL_OFFSETS = {1, 0, -1, 0};
    // Unique identifiers for directions to track turns
    private static final int[] DIRECTION_IDS = {1, 2, 3, 4};
    private static final int START_DIRECTION = 0;
    private static final int MAX_ALLOWED_TURNS = 3;

    private final FastReader reader;
    private int rows;
    private int cols;
    private char[][] grid;
    private int[][] minTurnsToCell;

    public MazePathfinder(InputStream inputStream) {
        this.reader = new FastReader(inputStream);
    }

    /**
     * Represents a specific state in the BFS traversal.
     */
    private static class State {
        final int row;
        final int col;
        final int turnCount;
        final int lastDirection;

        State(int row, int col, int turnCount, int lastDirection) {
            this.row = row;
            this.col = col;
            this.turnCount = turnCount;
            this.lastDirection = lastDirection;
        }
    }

    /**
     * Executes the pathfinding logic.
     * @return true if a target 'T' is reachable within turn constraints, false otherwise.
     */
    public boolean solve() {
        String firstLine = reader.next();
        if (firstLine == null) return false;

        rows = Integer.parseInt(firstLine);
        cols = reader.nextInt();

        grid = new char[rows][cols];
        minTurnsToCell = new int[rows][cols];

        int startRow = 0;
        int startCol = 0;

        for (int i = 0; i < rows; i++) {
            String rowString = reader.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = rowString.charAt(j);
                minTurnsToCell[i][j] = MAX_ALLOWED_TURNS; // Initialize with threshold
                if (grid[i][j] == 'S') {
                    startRow = i;
                    startCol = j;
                }
            }
        }

        Queue<State> queue = new LinkedList<>();
        queue.add(new State(startRow, startCol, 0, START_DIRECTION));

        while (!queue.isEmpty()) {
            State current = queue.poll();

            for (int i = 0; i < 4; i++) {
                int dirId = DIRECTION_IDS[i];

                // Original constraint: Cannot move in the same direction twice consecutively
                if (current.lastDirection == dirId) {
                    continue;
                }

                int nextRow = current.row + ROW_OFFSETS[i];
                int nextCol = current.col + COL_OFFSETS[i];

                if (isValidMove(nextRow, nextCol)) {
                    // Calculate turns: if moving from start or continuing direction, turns stay same.
                    // (Note: dirId != current.lastDirection is guaranteed by the check above)
                    int nextTurnCount = (current.lastDirection == START_DIRECTION || current.lastDirection == dirId) 
                                        ? current.turnCount 
                                        : current.turnCount + 1;

                    if (nextTurnCount < MAX_ALLOWED_TURNS) {
                        if (grid[nextRow][nextCol] == 'T') {
                            return true;
                        }

                        if (minTurnsToCell[nextRow][nextCol] >= nextTurnCount) {
                            minTurnsToCell[nextRow][nextCol] = nextTurnCount;
                            queue.add(new State(nextRow, nextCol, nextTurnCount, dirId));
                        }
                    }
                }
            }
        }

        return false;
    }

    private boolean isValidMove(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] != '*';
    }

    public static void main(String[] args) {
        MazePathfinder pathfinder = new MazePathfinder(System.in);
        if (pathfinder.solve()) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Utility class for fast I/O operations.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

