/**
 * A solution to find if a path exists in a grid from 'S' to 'T' 
 * with at most 2 turns.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] grid = new char[rows][cols];

            int startR = -1, startC = -1;
            int targetR = -1, targetC = -1;

            for (int r = 0; r < rows; r++) {
                String line = reader.next();
                for (int c = 0; c < cols; c++) {
                    grid[r][c] = line.charAt(c);
                    if (grid[r][c] == 'S') {
                        startR = r;
                        startC = c;
                    } else if (grid[r][c] == 'T') {
                        targetR = r;
                        targetC = c;
                    }
                }
            }

            GridPathfinder solver = new GridPathfinder(rows, cols, grid);
            if (solver.canReachTarget(startR, startC, targetR, targetC)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /**
     * Core logic for finding the path using Breadth-First Search.
     */
    static class GridPathfinder {
        private final int rows;
        private final int cols;
        private final char[][] grid;

        // Directions: Right, Left, Up, Down
        private static final int[] DR = {0, 0, -1, 1};
        private static final int[] DC = {1, -1, 0, 0};
        private static final int MAX_TURNS = 2;

        public GridPathfinder(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
        }

        /**
         * Performs BFS to check if the target is reachable within the turn constraint.
         * 
         * @param startR Starting row index
         * @param startC Starting column index
         * @param targetR Target row index
         * @param targetC Target column index
         * @return true if target is reachable, false otherwise
         */
        public boolean canReachTarget(int startR, int startC, int targetR, int targetC) {
            // Immediate exit if start is the target
            if (startR == targetR && startC == targetC) {
                return true;
            }

            // visited[r][c][dir * 3 + turns]
            // Total states per cell: 4 directions * 3 possible turn counts (0, 1, 2) = 12
            boolean[][][] visited = new boolean[rows][cols][12];

            // Use a primitive array for the queue to minimize memory usage and GC overhead.
            // Maximum number of states is rows * cols * 12.
            int[] queue = new int[rows * cols * 12 + 1];
            int head = 0;
            int tail = 0;

            // Initialize the BFS by considering all 4 possible initial directions.
            // Moving in the first chosen direction does not count as a turn.
            for (int d = 0; d < 4; d++) {
                int state = encode(startR, startC, d, 0);
                visited[startR][startC][d * 3 + 0] = true;
                queue[tail++] = state;
            }

            while (head < tail) {
                int currState = queue[head++];

                int r = getR(currState);
                int c = getC(currState);
                int dir = getDir(currState);
                int turns = getTurns(currState);

                // Explore all 4 possible directions from the current cell
                for (int d = 0; d < 4; d++) {
                    int nr = r + DR[d];
                    int nc = c + DC[d];
                    int nTurns = (d == dir) ? turns : turns + 1;

                    // Check movement constraints
                    if (isValidMove(nr, nc, nTurns)) {
                        // Check if we reached the target
                        if (nr == targetR && nc == targetC) {
                            return true;
                        }

                        int nextState = encode(nr, nc, d, nTurns);
                        int visitedIdx = d * 3 + nTurns;

                        if (!visited[nr][nc][visitedIdx]) {
                            visited[nr][nc][visitedIdx] = true;
                            queue[tail++] = nextState;
                        }
                    }
                }
            }

            return false;
        }

        private boolean isValidMove(int r, int c, int turns) {
            return r >= 0 && r < rows && c >= 0 && c < cols 
                    && grid[r][c] != '*' && turns <= MAX_TURNS;
        }

        /**
         * State Encoding: ((position * 4 + direction) * 3 + turns)
         * This compresses the state into a single integer for performance.
         */
        private int encode(int r, int c, int dir, int turns) {
            int pos = r * cols + c;
            return ((pos * 4 + dir) * 3 + turns);
        }

        private int getR(int state) {
            int pos = state / 12;
            return pos / cols;
        }

        private int getC(int state) {
            int pos = state / 12;
            return pos % cols;
        }

        private int getDir(int state) {
            return (state / 3) % 4;
        }

        private int getTurns(int state) {
            return state % 3;
        }
    }

    /**
     * Fast I/O helper to handle large inputs efficiently.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            String next = next();
            return next != null ? Integer.parseInt(next) : 0;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * GridPathfinder solves the problem of determining if a start point 'S' 
 * and a target point 'T' can be connected via two intermediate points 
 * on straight-line paths that do not cross any obstacles '*'.
 */
public class GridPathfinder {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = reader.nextInt();
            int m = reader.nextInt();
            char[][] gridData = new char[n][m];

            Point startPoint = null;
            Point targetPoint = null;

            for (int i = 0; i < n; i++) {
                String line = reader.next();
                for (int j = 0; j < m; j++) {
                    gridData[i][j] = line.charAt(j);
                    if (gridData[i][j] == 'S') {
                        startPoint = new Point(i, j);
                    } else if (gridData[i][j] == 'T') {
                        targetPoint = new Point(i, j);
                    }
                }
            }

            if (startPoint == null || targetPoint == null) {
                out.println("NO");
            } else {
                Grid grid = new Grid(gridData, n, m);
                if (solve(grid, startPoint, targetPoint)) {
                    out.println("YES");
                } else {
                    out.println("NO");
                }
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.close();
        }
    }

    private static boolean solve(Grid grid, Point start, Point target) {
        List<Point> reachableFromStart = grid.getReachablePointsOnRays(start);
        List<Point> reachableFromTarget = grid.getReachablePointsOnRays(target);

        for (Point p1 : reachableFromStart) {
            for (Point p2 : reachableFromTarget) {
                if (grid.isPathClear(p1, p2)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Represents a coordinate in the 2D grid.
     */
    static class Point {
        final int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Handles grid data, obstacle detection, and prefix sum calculations.
     */
    static class Grid {
        private final int rows, cols;
        private final boolean[][] obstacles;
        private final int[][] rowPrefixSums;
        private final int[][] colPrefixSums;

        Grid(char[][] data, int rows, int cols) {
            this.rows = rows;
            this.cols = cols;
            this.obstacles = new boolean[rows][cols];
            this.rowPrefixSums = new int[rows][cols];
            this.colPrefixSums = new int[cols][rows];

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (data[i][j] == '*') {
                        obstacles[i][j] = true;
                    }
                    // Prefix sum for rows
                    rowPrefixSums[i][j] = (j > 0 ? rowPrefixSums[i][j - 1] : 0) + (obstacles[i][j] ? 1 : 0);
                }
            }

            for (int j = 0; j < cols; j++) {
                for (int i = 0; i < rows; i++) {
                    // Prefix sum for columns
                    colPrefixSums[j][i] = (i > 0 ? colPrefixSums[j][i - 1] : 0) + (obstacles[i][j] ? 1 : 0);
                }
            }
        }

        boolean isObstacle(int r, int c) {
            return obstacles[r][c];
        }

        /**
         * Checks if a straight-line path between two points is clear of obstacles.
         */
        boolean isPathClear(Point p1, Point p2) {
            if (p1.r == p2.r) { // Same row
                int cMin = Math.min(p1.c, p2.c);
                int cMax = Math.max(p1.c, p2.c);
                return getRowObstacleCount(p1.r, cMin, cMax) == 0;
            } else if (p1.c == p2.c) { // Same column
                int rMin = Math.min(p1.r, p2.r);
                int rMax = Math.max(p1.r, p2.r);
                return getColObstacleCount(p1.c, rMin, rMax) == 0;
            }
            return false;
        }

        private int getRowObstacleCount(int r, int c1, int c2) {
            return rowPrefixSums[r][c2] - (c1 > 0 ? rowPrefixSums[r][c1 - 1] : 0);
        }

        private int getColObstacleCount(int c, int r1, int r2) {
            return colPrefixSums[c][r2] - (r1 > 0 ? colPrefixSums[c][r1 - 1] : 0);
        }

        /**
         * Finds all points reachable from a starting point by moving in one of the 4 cardinal directions.
         */
        List<Point> getReachablePointsOnRays(Point start) {
            List<Point> points = new ArrayList<>();
            int[] dr = {1, -1, 0, 0};
            int[] dc = {0, 0, 1, -1};

            // Include the start point itself
            points.add(start);

            for (int i = 0; i < 4; i++) {
                int currR = start.r + dr[i];
                int currC = start.c + dc[i];

                while (isValid(currR, currC) && !obstacles[currR][currC]) {
                    points.add(new Point(currR, currC));
                    currR += dr[i];
                    currC += dc[i];
                }
            }
            return points;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * Utility class for fast input reading.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

