/**
 * Represents the movement directions in the grid.
 */
enum Direction {
    UP(-1, 0),
    RIGHT(0, 1),
    DOWN(1, 0),
    LEFT(0, -1);

    final int rowOffset;
    final int colOffset;

    Direction(int rowOffset, int colOffset) {
        this.rowOffset = rowOffset;
        this.colOffset = colOffset;
    }

    static Direction[] values() {
        return new Direction[]{UP, RIGHT, DOWN, LEFT};
    }
}

/**
 * Encapsulates the grid data and provides boundary/obstacle checks.
 */
class Grid {
    private final char[][] cells;
    private final int rows;
    private final int cols;
    private int startRow, startCol;
    private int targetRow, targetCol;

    public Grid(char[][] cells) {
        this.cells = cells;
        this.rows = cells.length;
        this.cols = cells[0].length;
        findSpecialCells();
    }

    private void findSpecialCells() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (cells[r][c] == 'S') {
                    startRow = r;
                    startCol = c;
                } else if (cells[r][c] == 'T') {
                    targetRow = r;
                    targetCol = c;
                }
            }
        }
    }

    public boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols && cells[r][c] != '*';
    }

    public int getRows() { return rows; }
    public int getCols() { return cols; }
    public int getStartRow() { return startRow; }
    public int getStartCol() { return startCol; }
    public int getTargetRow() { return targetRow; }
    public int getTargetCol() { return targetCol; }
}

/**
 * Represents a specific state in the search algorithm.
 */
class SearchState {
    final int row;
    final int col;
    final Direction direction;
    final int turns;

    public SearchState(int row, int col, Direction direction, int turns) {
        this.row = row;
        this.col = col;
        this.direction = direction;
        this.turns = turns;
    }
}

/**
 * Contains the logic to solve the pathfinding problem.
 */
class GridPathfinder {
    private final Grid grid;
    private static final int MAX_TURNS = 2; // Based on original logic (turns <= 1 allows next turn)

    public GridPathfinder(Grid grid) {
        this.grid = grid;
    }

    /**
     * Uses 0-1 BFS to determine if the target is reachable within the turn limit.
     */
    public boolean canReachTarget() {
        Deque<SearchState> deque = new ArrayDeque<>();

        // Visited state: [row][col][direction_ordinal]
        boolean[][][] visited = new boolean[grid.getRows()][grid.getCols()][Direction.values().length];

        // Initialize search from start position in all 4 directions
        for (Direction dir : Direction.values()) {
            deque.addLast(new SearchState(grid.getStartRow(), grid.getStartCol(), dir, 0));
        }

        while (!deque.isEmpty()) {
            SearchState current = deque.pollFirst();

            if (current.row == grid.getTargetRow() && current.col == grid.getTargetCol()) {
                return true;
            }

            int dirIdx = current.direction.ordinal();
            if (visited[current.row][current.col][dirIdx]) {
                continue;
            }
            visited[current.row][current.col][dirIdx] = true;

            for (Direction nextDir : Direction.values()) {
                int nextRow = current.row + nextDir.rowOffset;
                int nextCol = current.col + nextDir.colOffset;

                if (grid.isValid(nextRow, nextCol)) {
                    if (nextDir == current.direction) {
                        // Weight 0: Moving in the same direction
                        deque.addFirst(new SearchState(nextRow, nextCol, nextDir, current.turns));
                    } else {
                        // Weight 1: Making a turn (only if within turn limit)
                        if (current.turns < MAX_TURNS) {
                            deque.addLast(new SearchState(nextRow, nextCol, nextDir, current.turns + 1));
                        }
                    }
                }
            }
        }

        return false;
    }
}

/**
 * High-performance input reader.
 */
class FastReader {
    private final InputStream inputStream;
    private final byte[] buffer = new byte[1024];
    private int pointer = 0;
    private int bufferLength = 0;

    public FastReader(InputStream inputStream) {
        this.inputStream = inputStream;
    }

    private int readByte() {
        if (pointer >= bufferLength) {
            pointer = 0;
            try {
                bufferLength = inputStream.read(buffer);
            } catch (IOException e) {
                return -1;
            }
            if (bufferLength <= 0) return -1;
        }
        return buffer[pointer++] & 0xFF;
    }

    public int nextInt() {
        int c = readByte();
        while (c != -1 && c <= 32) c = readByte();
        if (c == -1) return 0;
        int sign = 1;
        if (c == '-') {
            sign = -1;
            c = readByte();
        }
        int res = 0;
        while (c >= '0' && c <= '9') {
            res = res * 10 + (c - '0');
            c = readByte();
        }
        return res * sign;
    }

    public char[][] readGrid(int rows, int cols) {
        char[][] grid = new char[rows][cols];
        int r = 0;
        while (r < rows) {
            int c = 0;
            // Skip whitespace/newlines to find start of row
            int charVal = readByte();
            while (charVal != -1 && charVal <= 32) charVal = readByte();

            while (charVal != -1 && charVal > 32 && c < cols) {
                grid[r][c++] = (char) charVal;
                charVal = readByte();
            }
            r++;
        }
        return grid;
    }
}

/**
 * High-performance output writer.
 */
class FastWriter {
    private final PrintWriter writer;

    public FastWriter(OutputStream outputStream) {
        this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
    }

    public void printLine(Object obj) {
        writer.println(obj);
    }

    public void close() {
        writer.close();
    }
}

