/**
 * A utility class to find if a path exists in a grid from a start point 'S' 
 * to a target point 'T' with a maximum of 2 turns.
 */
public class Codechef {

    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int rows = in.nextInt();
            int cols = in.nextInt();

            GridPathfinder pathfinder = new GridPathfinder(rows, cols, in);
            if (pathfinder.solve()) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            out.close();
        }
    }

    static class GridPathfinder {
        private final int rows;
        private final int cols;
        private final int[][] grid; // 0 for passable, 1 for obstacle (*)
        private final boolean[][][] visited; // [row][col][turns]

        private int startRow, startCol;
        private int targetRow, targetCol;

        // Direction vectors: 0: Right, 1: Down, 2: Left, 3: Up
        private final int[] dr = {0, 1, 0, -1};
        private final int[] dc = {1, 0, -1, 0};

        public GridPathfinder(int rows, int cols, FastScanner in) throws IOException {
            this.rows = rows;
            this.cols = cols;
            this.grid = new int[rows][cols];
            this.visited = new boolean[rows][cols][3];

            for (int i = 0; i < rows; i++) {
                String line = in.next();
                for (int j = 0; j < cols; j++) {
                    char cell = line.charAt(j);
                    if (cell == '*') {
                        grid[i][j] = 1;
                    } else if (cell == 'S') {
                        startRow = i;
                        startCol = j;
                        grid[i][j] = 0;
                    } else if (cell == 'T') {
                        targetRow = i;
                        targetCol = j;
                        grid[i][j] = 0;
                    } else {
                        grid[i][j] = 0;
                    }
                }
            }
        }

        /**
         * Initiates the search for a valid path.
         * @return true if target is reachable within 2 turns, false otherwise.
         */
        public boolean solve() {
            // We try starting in all 4 possible directions from the start point.
            // The first movement determines the initial direction and does not count as a turn.
            for (int d = 0; d < 4; d++) {
                if (dfs(startRow, startCol, d, 0)) {
                    return true;
                }
            }
            return false;
        }

        private boolean dfs(int r, int c, int currentDir, int turns) {
            // Base Case: Target reached
            if (r == targetRow && c == targetCol) {
                return true;
            }

            // Pruning: Too many turns or already visited this state
            if (turns > 2 || visited[r][c][turns]) {
                return false;
            }

            visited[r][c][turns] = true;

            for (int d = 0; d < 4; d++) {
                int nr = r + dr[d];
                int nc = c + dc[d];

                // Check boundaries and obstacles
                if (isValidMove(nr, nc)) {
                    // If direction changes, increment turn count
                    int nextTurns = (d == currentDir) ? turns : turns + 1;

                    if (nextTurns <= 2) {
                        if (dfs(nr, nc, d, nextTurns)) {
                            return true;
                        }
                    }
                }
            }

            return false;
        }

        private boolean isValidMove(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] == 0;
        }
    }

    /**
     * Fast I/O class for efficient reading of input.
     */
    static class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String s = br.readLine();
                if (s == null) return null;
                st = new StringTokenizer(s);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

