/**
 * Logic for determining if a specific pattern exists in a 10x10 grid.
 * The pattern is defined as a segment of 5 containing exactly 4 'X's and 1 '.'.
 */
class FiveInARowGame {
    private static final int GRID_SIZE = 10;
    private static final int SEGMENT_LENGTH = 5;
    private static final int TARGET_X_COUNT = 4;
    private static final int TARGET_DOT_COUNT = 1;

    private final char[][] grid = new char[GRID_SIZE][GRID_SIZE];

    /**
     * Loads the grid from user input.
     * @param scanner The scanner to read from.
     */
    public void loadGrid(Scanner scanner) {
        for (int i = 0; i < GRID_SIZE; i++) {
            if (scanner.hasNext()) {
                String rowInput = scanner.next();
                for (int j = 0; j < GRID_SIZE && j < rowInput.length(); j++) {
                    grid[i][j] = rowInput.charAt(j);
                }
            }
        }
    }

    /**
     * Scans the entire grid for any segment that satisfies the winning condition.
     * @return true if a winning segment is found.
     */
    public boolean isWinningSegmentFound() {
        // Direction vectors: {rowDelta, colDelta}
        // Horizontal, Vertical, Primary Diagonal, Secondary Diagonal
        int[][] directions = {
            {0, 1},  // Horizontal
            {1, 0},  // Vertical
            {1, 1},  // Primary Diagonal (\)
            {1, -1}  // Secondary Diagonal (/)
        };

        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                for (int[] dir : directions) {
                    if (isValidSegment(r, c, dir[0], dir[1])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a segment starting at (startRow, startCol) in a specific 
     * direction meets the target X and Dot counts.
     */
    private boolean isValidSegment(int startRow, int startCol, int rowDelta, int colDelta) {
        int xCount = 0;
        int dotCount = 0;

        for (int i = 0; i < SEGMENT_LENGTH; i++) {
            int currentRow = startRow + (i * rowDelta);
            int currentCol = startCol + (i * colDelta);

            // Boundary check
            if (isOutOfBounds(currentRow, currentCol)) {
                return false;
            }

            char cell = grid[currentRow][currentCol];
            if (cell == 'X') {
                xCount++;
            } else if (cell == '.') {
                dotCount++;
            }
        }

        return xCount == TARGET_X_COUNT && dotCount == TARGET_DOT_COUNT;
    }

    private boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= GRID_SIZE || c < 0 || c >= GRID_SIZE;
    }
}

