class GridAnalyzer {
    private final char[][] grid;
    private final int size;

    // Direction vectors representing the 4 axes: 
    // Horizontal, Vertical, Diagonal (top-left to bottom-right), Diagonal (top-right to bottom-left)
    private static final int[][] AXES = {
        {0, 1},  // Horizontal
        {1, 0},  // Vertical
        {1, 1},  // Diagonal 1
        {1, -1}  // Diagonal 2
    };

    public GridAnalyzer(char[][] grid) {
        this.grid = grid;
        this.size = grid.length;
    }

    /**
     * Iterates through every empty cell and checks if placing an 'X' 
     * meets the target length requirement.
     */
    public boolean canFormLineOfLength(int targetLength) {
        for (int r = 0; r < size; r++) {
            for (int c = 0; c < size; c++) {
                if (grid[r][c] == '.') {
                    if (getMaxLineLengthAt(r, c) >= targetLength) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Calculates the longest possible line passing through (row, col) 
     * across all 4 axes.
     */
    private int getMaxLineLengthAt(int row, int col) {
        int maxLineAtCell = 0;

        for (int[] axis : AXES) {
            int dRow = axis[0];
            int dCol = axis[1];

            // Calculate consecutive 'X's in both directions of the current axis
            int count = 1 // The '.' we are converting to 'X'
                    + countConsecutive(row, col, dRow, dCol)
                    + countConsecutive(row, col, -dRow, -dCol);

            maxLineAtCell = Math.max(maxLineAtCell, count);
        }

        return maxLineAtCell;
    }

    /**
     * Counts consecutive 'X' characters starting from the neighbor of (row, col)
     * in the specified direction.
     */
    private int countConsecutive(int row, int col, int dRow, int dCol) {
        int count = 0;
        int r = row + dRow;
        int c = col + dCol;

        while (isValid(r, c) && grid[r][c] == 'X') {
            count++;
            r += dRow;
            c += dCol;
        }
        return count;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < size && c >= 0 && c < size;
    }
}

import java.util.Scanner;

/**
 * A program to determine if a 10x10 grid contains a sequence of five 'X's,
 * either in its current state or by placing a single 'X' in an empty '.' cell.
 */
public class Main {

    private static final int GRID_SIZE = 10;
    private static final int WIN_SEQUENCE_LENGTH = 5;
    private static final char TARGET_CHAR = 'X';
    private static final char EMPTY_CHAR = '.';

    // Directions to check: Horizontal, Vertical, Diagonal Down-Right, Diagonal Down-Left
    private static final int[][] DIRECTIONS = {
        {0, 1},  // Horizontal
        {1, 0},  // Vertical
        {1, 1},  // Diagonal Down-Right
        {1, -1}  // Diagonal Down-Left
    };

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            char[][] grid = readGridFromInput(scanner);
            Solver solver = new Solver(grid);
            System.out.println(solver.solve());
        } catch (Exception e) {
            // In a production environment, use a logger and handle specific exceptions
            System.err.println("An error occurred while processing the grid: " + e.getMessage());
        }
    }

    /**
     * Reads the 10x10 grid from the standard input.
     */
    private static char[][] readGridFromInput(Scanner scanner) {
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            if (scanner.hasNext()) {
                String line = scanner.next();
                for (int j = 0; j < GRID_SIZE; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }
        }
        return grid;
    }

    /**
     * Engine responsible for calculating the winning state.
     */
    static class Solver {
        private final char[][] grid;

        Solver(char[][] grid) {
            this.grid = grid;
        }

        /**
         * Executes the core logic to find if a win is possible.
         * @return "YES" if a win exists or can be created, otherwise "NO".
         */
        public String solve() {
            // Case 1: Already has a winning sequence
            if (hasWinningSequence()) {
                return "YES";
            }

            // Case 2: Can we create a winning sequence by adding one 'X'?
            for (int r = 0; r < GRID_SIZE; r++) {
                for (int c = 0; c < GRID_SIZE; c++) {
                    if (grid[r][c] == EMPTY_CHAR) {
                        if (tryPlacingAndCheck(r, c)) {
                            return "YES";
                        }
                    }
                }
            }

            return "NO";
        }

        /**
         * Temporarily places a character and checks the board state.
         * This implements a simple backtracking step.
         */
        private boolean tryPlacingAndCheck(int row, int col) {
            grid[row][col] = TARGET_CHAR;
            boolean isWinning = hasWinningSequence();
            grid[row][col] = EMPTY_CHAR; // Backtrack
            return isWinning;
        }

        /**
         * Scans the entire grid for any winning sequence.
         */
        private boolean hasWinningSequence() {
            for (int r = 0; r < GRID_SIZE; r++) {
                for (int c = 0; c < GRID_SIZE; c++) {
                    if (grid[r][c] == TARGET_CHAR) {
                        if (checkAllDirections(r, c)) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        /**
         * Checks if a winning sequence starts from a specific cell in any direction.
         */
        private boolean checkAllDirections(int r, int c) {
            for (int[] direction : DIRECTIONS) {
                if (isWinningPath(r, c, direction[0], direction[1])) {
                    return true;
                }
            }
            return false;
        }

        /**
         * Checks if there is a continuous sequence of TARGET_CHAR in a specific direction.
         */
        private boolean isWinningPath(int startR, int startC, int rowOffset, int colOffset) {
            for (int step = 1; step < WIN_SEQUENCE_LENGTH; step++) {
                int nextR = startR + (step * rowOffset);
                int nextC = startC + (step * colOffset);

                if (!isWithinBounds(nextR, nextC) || grid[nextR][nextC] != TARGET_CHAR) {
                    return false;
                }
            }
            return true;
        }

        private boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
        }
    }
}

import java.util.Scanner;

/**
 * A solver to determine if placing a single 'X' on a 10x10 grid
 * results in a winning sequence of 5.
 */
public class GomokuSolver {

    private static final int GRID_SIZE = 10;
    private static final int WIN_SEQUENCE_LENGTH = 5;

    private static final int EMPTY = 0;
    private static final int PLAYER_X = 1;
    private static final int PLAYER_O = 2;

    // Direction vectors: {row_delta, col_delta}
    // Represents: Horizontal, Vertical, Diagonal Down-Right, Diagonal Down-Left
    private static final int[][] DIRECTIONS = {
        {0, 1},  // Horizontal
        {1, 0},  // Vertical
        {1, 1},  // Diagonal (\)
        {1, -1}  // Diagonal (/)
    };

    private final int[][] grid = new int[GRID_SIZE][GRID_SIZE];

    public static void main(String[] args) {
        GomokuSolver solver = new GomokuSolver();
        solver.run();
    }

    /**
     * Orchestrates the input reading, logic execution, and output.
     */
    public void run() {
        try (Scanner scanner = new Scanner(System.in)) {
            parseInput(scanner);

            if (canWinWithOneMove()) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        } catch (Exception e) {
            System.err.println("Error processing input: " + e.getMessage());
        }
    }

    /**
     * Reads the 10x10 grid from standard input.
     */
    private void parseInput(Scanner scanner) {
        for (int i = 0; i < GRID_SIZE; i++) {
            if (!scanner.hasNextLine()) break;
            String line = scanner.nextLine();
            for (int j = 0; j < GRID_SIZE; j++) {
                char cell = line.charAt(j);
                if (cell == 'X') {
                    grid[i][j] = PLAYER_X;
                } else if (cell == 'O') {
                    grid[i][j] = PLAYER_O;
                } else {
                    grid[i][j] = EMPTY;
                }
            }
        }
    }

    /**
     * Iterates through the grid to find an empty cell where placing 'X' 
     * creates a win.
     */
    private boolean canWinWithOneMove() {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                if (grid[r][c] == EMPTY) {
                    // Temporarily place X
                    grid[r][c] = PLAYER_X;

                    if (checkWinAt(r, c)) {
                        return true; // Win found
                    }

                    // Backtrack
                    grid[r][c] = EMPTY;
                }
            }
        }
        return false;
    }

    /**
     * Checks if the piece placed at (row, col) completes a win sequence.
     */
    private boolean checkWinAt(int row, int col) {
        for (int[] direction : DIRECTIONS) {
            int count = 1; // Start with the piece just placed

            // Check in the positive direction of the vector
            count += countConsecutive(row, col, direction[0], direction[1]);

            // Check in the negative direction of the vector
            count += countConsecutive(row, col, -direction[0], -direction[1]);

            if (count >= WIN_SEQUENCE_LENGTH) {
                return true;
            }
        }
        return false;
    }

    /**
     * Counts how many consecutive pieces of the same type exist in a specific direction.
     */
    private int countConsecutive(int row, int col, int dr, int dc) {
        int count = 0;
        int r = row + dr;
        int c = col + dc;

        while (isWithinBounds(r, c) && grid[r][c] == PLAYER_X) {
            count++;
            r += dr;
            c += dc;

            // Optimization: stop if we already met the win condition
            if (count >= WIN_SEQUENCE_LENGTH) break;
        }
        return count;
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Main class to execute the Grid Game Solver.
 */
public class Main {
    public static void main(String[] args) {
        try (FastReader in = new FastReader(System.in);
             FastWriter out = new FastWriter(System.out)) {

            GridGameSolver solver = new GridGameSolver();
            solver.solve(in, out);

        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * Core logic for solving the grid puzzle.
     */
    static class GridGameSolver {
        private static final int GRID_SIZE = 10;
        private static final int WINNING_LENGTH = 5;

        // Directional offsets for 8 neighbors
        private final int[] DX = {-1, -1, -1, 0, 1, 1, 1, 0};
        private final int[] DY = {-1, 0, 1, 1, 1, 0, -1, -1};

        /**
         * Attempts to place one 'X' in an empty '.' spot to create a winning line.
         */
        public void solve(FastReader in, FastWriter out) {
            char[][] grid = GridUtils.readGrid(in, GRID_SIZE, GRID_SIZE);

            for (int r = 0; r < GRID_SIZE; r++) {
                for (int c = 0; c < GRID_SIZE; c++) {
                    if (grid[r][c] == '.') {
                        // Try placing an 'X'
                        grid[r][c] = 'X';
                        if (hasWinningLine(grid)) {
                            out.println("YES");
                            return;
                        }
                        // Backtrack
                        grid[r][c] = '.';
                    }
                }
            }
            out.println("NO");
        }

        private boolean hasWinningLine(char[][] grid) {
            for (int r = 0; r < GRID_SIZE; r++) {
                for (int c = 0; c < GRID_SIZE; c++) {
                    // Only check directions if the current cell is part of a potential line
                    if (grid[r][c] == 'X') {
                        for (int d = 0; d < 8; d++) {
                            if (checkDirection(grid, r, c, d)) {
                                return true;
                            }
                        }
                    }
                }
            }
            return false;
        }

        private boolean checkDirection(char[][] grid, int startR, int startC, int dir) {
            int currR = startR;
            int currC = startC;

            for (int i = 0; i < WINNING_LENGTH; i++) {
                if (!isInsideGrid(currR, currC) || grid[currR][currC] != 'X') {
                    return false;
                }
                currR += DX[dir];
                currC += DY[dir];
            }
            return true;
        }

        private boolean isInsideGrid(int r, int c) {
            return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
        }
    }

    /**
     * Utilities for grid-based I/O operations.
     */
    static class GridUtils {
        public static char[][] readGrid(FastReader in, int rows, int cols) {
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = in.next();
                if (line != null) {
                    grid[i] = line.toCharArray();
                }
            }
            return grid;
        }
    }

    /**
     * High-performance reader for efficient input processing.
     */
    static class FastReader implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        @Override
        public void close() throws IOException {
            reader.close();
        }
    }

    /**
     * High-performance writer for efficient output processing.
     */
    static class FastWriter implements AutoCloseable {
        private final PrintWriter writer;

        public FastWriter(OutputStream outputStream) {
            this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public void println(Object message) {
            writer.println(message);
        }

        @Override
        public void close() {
            writer.flush();
            writer.close();
        }
    }
}

import java.util.Scanner;

/**
 * A utility to check if a 10x10 grid contains a winning line of 'X's.
 * A winning line is defined as 5 consecutive cells containing at least 4 'X's.
 */
public class GridScanner {

    private static final int GRID_SIZE = 10;
    private static final int WIN_LENGTH = 5;
    private static final int REQUIRED_X_COUNT = 4;
    private static final char TARGET_CHAR = 'X';
    private static final char WILDCARD_CHAR = '.';

    // Direction vectors representing: Horizontal, Vertical, Diagonal Down-Right, Diagonal Up-Right
    private static final int[][] DIRECTIONS = {
        {0, 1},  // Right
        {1, 0},  // Down
        {1, 1},  // Down-Right
        {-1, 1}  // Up-Right
    };

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] grid = readGrid(scanner);

        if (hasWinningLine(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Reads a 10x10 grid from standard input.
     */
    private static char[][] readGrid(Scanner scanner) {
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            if (scanner.hasNext()) {
                grid[i] = scanner.next().toCharArray();
            }
        }
        return grid;
    }

    /**
     * Iterates through every cell and every direction to find a winning line.
     */
    private static boolean hasWinningLine(char[][] grid) {
        for (int row = 0; row < GRID_SIZE; row++) {
            for (int col = 0; col < GRID_SIZE; col++) {
                for (int[] dir : DIRECTIONS) {
                    if (canFormLine(row, col, dir[0], dir[1])) {
                        if (checkLine(grid, row, col, dir[0], dir[1])) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a line of WIN_LENGTH can be formed starting from (row, col) 
     * in the given direction without going out of bounds.
     */
    private static boolean canFormLine(int row, int col, int dr, int dc) {
        int endRow = row + (WIN_LENGTH - 1) * dr;
        int endCol = col + (WIN_LENGTH - 1) * dc;

        return endRow >= 0 && endRow < GRID_SIZE &&
               endCol >= 0 && endCol < GRID_SIZE;
    }

    /**
     * Counts 'X's in a specific line. Returns true if the line meets win requirements.
     */
    private static boolean checkLine(char[][] grid, int row, int col, int dr, int dc) {
        int xCount = 0;
        int dotCount = 0;

        for (int k = 0; k < WIN_LENGTH; k++) {
            int currR = row + k * dr;
            int currC = col + k * dc;
            char cell = grid[currR][currC];

            if (cell == TARGET_CHAR) {
                xCount++;
            } else if (cell == WILDCARD_CHAR) {
                dotCount++;
            }
        }

        // A win is defined as 5 cells where either all are X 
        // or 4 are X and 1 is the wildcard ('.').
        return (xCount == WIN_LENGTH) || (xCount == WIN_LENGTH - 1 && dotCount == 1);
    }
}

