/**
 * Handles the logic of traversing a 2D grid and extracting lines for analysis.
 */
class GridAnalyzer {

    private final char[][] grid;
    private final int size;

    public GridAnalyzer(char[][] grid) {
        this.grid = grid;
        this.size = grid.length;
    }

    /**
     * Checks if any extracted line (row, column, or diagonal) contains any of the patterns.
     */
    public boolean containsTargetPattern(Set<String> patterns) {
        List<String> allLines = extractAllLines();
        for (String line : allLines) {
            for (String pattern : patterns) {
                if (line.contains(pattern)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Collects all maximal rows, columns, diagonals, and anti-diagonals.
     */
    private List<String> extractAllLines() {
        List<String> lines = new ArrayList<>();

        lines.addAll(extractRows());
        lines.addAll(extractColumns());
        lines.addAll(extractDiagonals());
        lines.addAll(extractAntiDiagonals());

        return lines;
    }

    private List<String> extractRows() {
        List<String> rows = new ArrayList<>();
        for (int i = 0; i < size; i++) {
            rows.add(new String(grid[i]));
        }
        return rows;
    }

    private List<String> extractColumns() {
        List<String> cols = new ArrayList<>();
        for (int j = 0; j < size; j++) {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < size; i++) {
                sb.append(grid[i][j]);
            }
            cols.add(sb.toString());
        }
        return cols;
    }

    /**
     * Extracts all diagonals from top-left to bottom-right.
     * A diagonal is defined by the property: (row - col) = constant.
     */
    private List<String> extractDiagonals() {
        List<String> diagonals = new ArrayList<>();
        for (int k = -(size - 1); k < size; k++) {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < size; i++) {
                int j = i - k;
                if (j >= 0 && j < size) {
                    sb.append(grid[i][j]);
                }
            }
            if (sb.length() >= 5) {
                diagonals.add(sb.toString());
            }
        }
        return diagonals;
    }

    /**
     * Extracts all anti-diagonals from top-right to bottom-left.
     * An anti-diagonal is defined by the property: (row + col) = constant.
     */
    private List<String> extractAntiDiagonals() {
        List<String> antiDiagonals = new ArrayList<>();
        for (int k = 0; k <= 2 * (size - 1); k++) {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < size; i++) {
                int j = k - i;
                if (j >= 0 && j < size) {
                    sb.append(grid[i][j]);
                }
            }
            if (sb.length() >= 5) {
                antiDiagonals.add(sb.toString());
            }
        }
        return antiDiagonals;
    }
}

import java.util.Scanner;

/**
 * GridPatternMatcher searches for a specific pattern in a 10x10 grid.
 * The winning condition is defined as finding a straight line of 5 cells 
 * containing exactly four 'X' characters and one '.' character.
 */
public class GridPatternMatcher {

    private static final int GRID_SIZE = 10;
    private static final int WINDOW_SIZE = 5;
    private static final int TARGET_X_COUNT = 4;
    private static final int TARGET_DOT_COUNT = 1;

    // The 8 possible directions in a 2D grid: N, NE, E, SE, S, SW, W, NW
    private static final int[][] DIRECTIONS = {
        {-1, 0},  // North
        {-1, 1},  // North-East
        {0, 1},   // East
        {1, 1},   // South-East
        {1, 0},   // South
        {1, -1},  // South-West
        {0, -1},  // West
        {-1, -1}  // North-West
    };

    public static void main(String[] args) {
        char[][] grid = readGridFromConsole();

        if (grid == null) {
            return;
        }

        if (containsWinningPattern(grid)) {
            System.out.print("YES");
        } else {
            System.out.print("NO");
        }
    }

    /**
     * Reads the 10x10 grid from standard input.
     * @return A 2D char array representing the grid, or null if input is invalid.
     */
    private static char[][] readGridFromConsole() {
        Scanner scanner = new Scanner(System.in);
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];

        try {
            for (int i = 0; i < GRID_SIZE; i++) {
                if (!scanner.hasNext()) break;
                String row = scanner.next();
                if (row.length() < GRID_SIZE) {
                    return null;
                }
                for (int j = 0; j < GRID_SIZE; j++) {
                    grid[i][j] = row.charAt(j);
                }
            }
        } catch (Exception e) {
            return null;
        } finally {
            scanner.close();
        }
        return grid;
    }

    /**
     * Iterates through every cell and direction to find the target pattern.
     * @param grid The 10x10 game field.
     * @return true if the pattern is found, false otherwise.
     */
    private static boolean containsWinningPattern(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                for (int[] direction : DIRECTIONS) {
                    if (isValidPatternWindow(grid, r, c, direction[0], direction[1])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a specific sequence of cells starting from (startR, startC) 
     * in a given direction matches the required pattern.
     * 
     * @param grid The game field.
     * @param startR Starting row index.
     * @param startC Starting column index.
     * @param dr Row direction delta.
     * @param dc Column direction delta.
     * @return true if the window contains exactly 4 'X's and 1 '.'.
     */
    private static boolean isValidPatternWindow(char[][] grid, int startR, int startC, int dr, int dc) {
        int xCount = 0;
        int dotCount = 0;

        for (int i = 0; i < WINDOW_SIZE; i++) {
            int currR = startR + (i * dr);
            int currC = startC + (i * dc);

            if (isOutOfBounds(currR, currC)) {
                return false;
            }

            char cell = grid[currR][currC];
            if (cell == 'X') {
                xCount++;
            } else if (cell == '.') {
                dotCount++;
            } else {
                // If we hit any other character, this sequence is invalid
                return false;
            }
        }

        return xCount == TARGET_X_COUNT && dotCount == TARGET_DOT_COUNT;
    }

    /**
     * Helper to check if coordinates are within the grid boundaries.
     */
    private static boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= GRID_SIZE || c < 0 || c >= GRID_SIZE;
    }
}

