class GridAnalyzer {
    private static final int GRID_SIZE = 10;
    private final char[][] grid;

    // Direction vectors for the 4 axes: Horizontal, Vertical, Diagonal(\), Diagonal(/)
    private static final int[][] DIRECTIONS = {
        {0, 1},  // Horizontal
        {1, 0},  // Vertical
        {1, 1},  // Diagonal Down-Right
        {1, -1}  // Diagonal Down-Left
    };

    public GridAnalyzer(char[][] grid) {
        this.grid = grid;
    }

    /**
     * Checks if there is any '.' cell that, if converted to 'X', 
     * would create a continuous line of at least 5 'X's.
     */
    public boolean canFormFiveInARow() {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                if (grid[r][c] == '.') {
                    if (completesALine(r, c)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks all four axes passing through the given cell (row, col).
     */
    private boolean completesALine(int row, int col) {
        for (int[] dir : DIRECTIONS) {
            int dr = dir[0];
            int dc = dir[1];

            // Count 'X's in both directions along the current axis
            int count = countConsecutive(row, col, dr, dc) + 
                        countConsecutive(row, col, -dr, -dc);

            // If sum of 'X's is 4, adding the current '.' makes a line of 5
            if (count >= 4) {
                return true;
            }
        }
        return false;
    }

    /**
     * Counts how many consecutive 'X's exist starting from the cell 
     * adjacent to (row, col) in the direction (dr, dc).
     */
    private int countConsecutive(int row, int col, int dr, int dc) {
        int count = 0;
        int r = row + dr;
        int c = col + dc;

        while (isWithinBounds(r, c) && grid[r][c] == 'X') {
            count++;
            r += dr;
            c += dc;
        }
        return count;
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
    }
}

