/**
 * A utility to detect a specific pattern in a 10x10 grid.
 * The pattern is defined as a sequence of 5 characters containing 
 * exactly one '.' and four 'X's.
 */
public class GridPatternChecker {

    private static final int GRID_SIZE = 10;
    private static final int PATTERN_LENGTH = 5;

    // Direction vectors for: Horizontal, Vertical, Diagonal (Down-Right), Diagonal (Down-Left)
    private static final int[] DR = {0, 1, 1, 1};
    private static final int[] DC = {1, 0, 1, -1};

    public static void main(String[] args) {
        GridPatternChecker checker = new GridPatternChecker();
        checker.run();
    }

    /**
     * Orchestrates the reading of input and the execution of the search.
     */
    public void run() {
        Scanner scanner = new Scanner(System.in);
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];

        try {
            for (int i = 0; i < GRID_SIZE; i++) {
                String line = scanner.next();
                if (line.length() < GRID_SIZE) {
                    // Handle potential malformed input
                    break;
                }
                grid[i] = line.toCharArray();
            }

            if (containsPattern(grid)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        } catch (Exception e) {
            // In a production environment, use a logger
            System.err.println("Error processing input: " + e.getMessage());
        } finally {
            scanner.close();
        }
    }

    /**
     * Iterates through every cell in the grid and checks all four directions.
     * 
     * @param grid The 10x10 character grid.
     * @return true if the pattern is found, false otherwise.
     */
    private boolean containsPattern(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                for (int dir = 0; dir < 4; dir++) {
                    if (isValidPatternAt(grid, r, c, DR[dir], DC[dir])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a valid pattern exists starting from (r, c) moving in direction (dr, dc).
     * A valid pattern must be exactly PATTERN_LENGTH long and contain one '.' and four 'X's.
     * 
     * @param grid The grid to search.
     * @param r Starting row.
     * @param c Starting column.
     * @param dr Row direction vector.
     * @param dc Column direction vector.
     * @return true if the segment matches the pattern.
     */
    private boolean isValidPatternAt(char[][] grid, int r, int c, int dr, int dc) {
        int dotCount = 0;
        int xCount = 0;

        for (int i = 0; i < PATTERN_LENGTH; i++) {
            int currR = r + (i * dr);
            int currC = c + (i * dc);

            // Check boundaries
            if (isOutOfBounds(currR, currC)) {
                return false;
            }

            char cell = grid[currR][currC];
            if (cell == '.') {
                dotCount++;
            } else if (cell == 'X') {
                xCount++;
            }
        }

        // The pattern requires exactly one '.' and four 'X's within the 5-length segment
        return dotCount == 1 && xCount == 4;
    }

    /**
     * Helper to check if coordinates are within the grid boundaries.
     */
    private boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= GRID_SIZE || c < 0 || c >= GRID_SIZE;
    }
}

