/**
 * A program to determine if a single move can result in a win in a 10x10 Connect Five game.
 */
public class ConnectFiveGame {

    private static final int GRID_SIZE = 10;
    private static final int WIN_CONDITION = 5;

    // Direction vectors representing: Horizontal, Vertical, Diagonal Down-Right, Diagonal Down-Left
    private static final int[][] DIRECTIONS = {
        {0, 1},  // Horizontal
        {1, 0},  // Vertical
        {1, 1},  // Diagonal Down-Right
        {1, -1}  // Diagonal Down-Left
    };

    private final char[][] board;

    public ConnectFiveGame(char[][] board) {
        this.board = board;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] board = new char[GRID_SIZE][GRID_SIZE];

        // Initialize the board from input
        for (int i = 0; i < GRID_SIZE; i++) {
            if (scanner.hasNext()) {
                String line = scanner.next();
                for (int j = 0; j < GRID_SIZE; j++) {
                    board[i][j] = line.charAt(j);
                }
            }
        }

        ConnectFiveGame game = new ConnectFiveGame(board);

        if (game.canWinWithOneMove()) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Iterates through all empty cells, simulates placing an 'X', 
     * and checks if that move results in a win.
     * 
     * @return true if any move results in 5 in a row.
     */
    public boolean canWinWithOneMove() {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                if (board[r][c] == '.') {
                    // Simulate move
                    board[r][c] = 'X';

                    if (hasFiveInARow()) {
                        board[r][c] = '.'; // Backtrack (though not strictly necessary here due to return)
                        return true;
                    }

                    // Backtrack
                    board[r][c] = '.';
                }
            }
        }
        return false;
    }

    /**
     * Scans the entire board to check if any sequence of 5 'X's exists.
     * 
     * @return true if a winning sequence is found.
     */
    private boolean hasFiveInARow() {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                if (board[r][c] == 'X') {
                    if (isSequenceStartingAt(r, c)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a sequence of 'X's of length WIN_CONDITION starts at the given coordinates
     * in any of the four defined directions.
     * 
     * @param row starting row index
     * @param col starting column index
     * @return true if a sequence is found.
     */
    private boolean isSequenceStartingAt(int row, int col) {
        for (int[] direction : DIRECTIONS) {
            int dr = direction[0];
            int dc = direction[1];

            boolean sequenceFound = true;
            for (int step = 1; step < WIN_CONDITION; step++) {
                int nextRow = row + (dr * step);
                int nextCol = col + (dc * step);

                if (!isValid(nextRow, nextCol) || board[nextRow][nextCol] != 'X') {
                    sequenceFound = false;
                    break;
                }
            }

            if (sequenceFound) {
                return true;
            }
        }
        return false;
    }

    /**
     * Validates if the given coordinates are within the board boundaries.
     */
    private boolean isValid(int r, int c) {
        return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
    }
}

import java.io.*;
import java.util.*;

/**
 * A program that determines if a 10x10 grid can result in a 5-in-a-row sequence
 * of 'X's by changing exactly one '.' to 'X'.
 */
public class Main {
    private static final int GRID_SIZE = 10;
    private static final int WIN_LENGTH = 5;
    private static final char EMPTY = '.';
    private static final char FILLED = 'X';

    // Direction vectors for: Horizontal, Vertical, Diagonal Down-Right, Diagonal Down-Left
    private static final int[][] DIRECTIONS = {
            {0, 1},
            {1, 0},
            {1, 1},
            {1, -1}
    };

    public static void main(String[] args) throws IOException {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            String line = in.next();
            if (line != null) {
                grid[i] = line.toCharArray();
            }
        }

        String result = canAchieveWin(grid) ? "YES" : "NO";
        out.println(result);
        out.close();
    }

    /**
     * Checks if changing exactly one '.' to 'X' creates a winning sequence.
     * 
     * @param grid The current state of the board.
     * @return true if a win is possible, false otherwise.
     */
    private static boolean canAchieveWin(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                if (grid[r][c] == EMPTY) {
                    // Try placing an 'X'
                    grid[r][c] = FILLED;

                    if (hasWinningSequence(grid)) {
                        grid[r][c] = EMPTY; // Restore state before returning
                        return true;
                    }

                    // Backtrack
                    grid[r][c] = EMPTY;
                }
            }
        }
        return false;
    }

    /**
     * Scans the entire grid for any sequence of 5 consecutive 'X's.
     * 
     * @param grid The current state of the board.
     * @return true if a winning sequence exists.
     */
    private static boolean hasWinningSequence(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                for (int[] dir : DIRECTIONS) {
                    if (isSequenceAt(grid, r, c, dir[0], dir[1])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a winning sequence starts at the given position in a specific direction.
     * 
     * @param grid The board.
     * @param r Starting row.
     * @param c Starting column.
     * @param dr Direction row delta.
     * @param dc Direction column delta.
     * @return true if a sequence of length WIN_LENGTH is found.
     */
    private static boolean isSequenceAt(char[][] grid, int r, int c, int dr, int dc) {
        for (int i = 0; i < WIN_LENGTH; i++) {
            int currR = r + (i * dr);
            int currC = c + (i * dc);

            if (isOutOfBounds(currR, currC) || grid[currR][currC] != FILLED) {
                return false;
            }
        }
        return true;
    }

    private static boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= GRID_SIZE || c < 0 || c >= GRID_SIZE;
    }
}

/**
 * Utility class for fast I/O operations.
 */
class FastScanner {
    private final BufferedReader br;
    private StringTokenizer tokenizer;

    public FastScanner(InputStream is) {
        br = new BufferedReader(new InputStreamReader(is));
    }

    public String next() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) {
                return null;
            }
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    public int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    public long nextLong() throws IOException {
        return Long.parseLong(next());
    }

    public double nextDouble() throws IOException {
        return Double.parseDouble(next());
    }
}

