/**
 * A utility to analyze a 10x10 grid and determine if any empty cell ('.')
 * acts as a center for at least 4 'X' characters in a straight line 
 * (horizontal, vertical, or diagonal).
 */
public class GridPatternAnalyzer {

    private static final int GRID_SIZE = 10;
    private static final char EMPTY_CELL = '.';
    private static final char TARGET_X = 'X';
    private static final int REQUIRED_X_COUNT = 4;

    // Directional vectors for: Horizontal, Vertical, Diagonal \, Diagonal /
    private static final int[][] DIRECTIONS = {
        {0, 1},  // Horizontal
        {1, 0},  // Vertical
        {1, 1},  // Diagonal (Top-Left to Bottom-Right)
        {1, -1}  // Diagonal (Top-Right to Bottom-Left)
    };

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] grid = readGrid(scanner);
        scanner.close();

        if (hasWinningPattern(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Reads a 10x10 grid from the standard input.
     */
    private static char[][] readGrid(Scanner scanner) {
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            if (scanner.hasNext()) {
                grid[i] = scanner.next().toCharArray();
            }
        }
        return grid;
    }

    /**
     * Iterates through the grid to find if any '.' cell meets the requirement.
     * 
     * @param grid The 10x10 character grid.
     * @return true if a valid pattern is found, false otherwise.
     */
    private static boolean hasWinningPattern(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                if (grid[r][c] == EMPTY_CELL) {
                    if (checkAllDirections(grid, r, c)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks all four possible axes (H, V, D1, D2) passing through a specific cell.
     */
    private static boolean checkAllDirections(char[][] grid, int row, int col) {
        for (int[] dir : DIRECTIONS) {
            int dr = dir[0];
            int dc = dir[1];

            // Count 'X's in both the positive and negative directions of the axis
            int count = countXInDirection(grid, row, col, dr, dc) 
                      + countXInDirection(grid, row, col, -dr, -dc);

            if (count >= REQUIRED_X_COUNT) {
                return true;
            }
        }
        return false;
    }

    /**
     * Counts consecutive 'X' characters starting from (row, col) 
     * moving in the direction (dr, dc).
     */
    private static int countXInDirection(char[][] grid, int row, int col, int dr, int dc) {
        int count = 0;
        int nextR = row + dr;
        int nextC = col + dc;

        while (isWithinBounds(nextR, nextC) && grid[nextR][nextC] == TARGET_X) {
            count++;
            nextR += dr;
            nextC += dc;
        }
        return count;
    }

    /**
     * Checks if the given coordinates are within the grid boundaries.
     */
    private static boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
    }
}

import java.util.Scanner;

/**
 * A solver for the Tic-Tac-Toe/Connect-Five style problem on a 10x10 grid.
 * The goal is to determine if placing one 'X' can create a line of 5 'X's.
 */
public class TicTacToeSolver {

    private static final int GRID_SIZE = 10;
    private static final int WIN_SEQUENCE_LENGTH = 5;

    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = 'O';
    private static final char EMPTY = '.';

    /**
     * Direction vectors used to traverse the grid in four directions:
     * {row_delta, col_delta}
     * 1. Vertical (Down)
     * 2. Horizontal (Right)
     * 3. Diagonal (Down-Right)
     * 4. Diagonal (Down-Left)
     */
    private static final int[][] DIRECTIONS = {
        {1, 0},
        {0, 1},
        {1, 1},
        {1, -1}
    };

    private final char[][] grid = new char[GRID_SIZE][GRID_SIZE];

    public static void main(String[] args) {
        TicTacToeSolver solver = new TicTacToeSolver();
        solver.solve();
    }

    /**
     * Orchestrates the reading of input and the checking of the win condition.
     */
    public void solve() {
        Scanner scanner = new Scanner(System.in);

        if (!loadBoard(scanner)) {
            scanner.close();
            return;
        }

        if (canAchieveWinWithOneMove()) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Reads the 10x10 grid from the input scanner.
     * Handles various input formats (space-separated or continuous lines).
     * 
     * @param scanner The scanner to read from.
     * @return true if the board was loaded successfully, false otherwise.
     */
    private boolean loadBoard(Scanner scanner) {
        try {
            int cellsRead = 0;
            int totalCells = GRID_SIZE * GRID_SIZE;

            while (cellsRead < totalCells && scanner.hasNext()) {
                String token = scanner.next();
                for (int i = 0; i < token.length() && cellsRead < totalCells; i++) {
                    int row = cellsRead / GRID_SIZE;
                    int col = cellsRead % GRID_SIZE;
                    grid[row][col] = token.charAt(i);
                    cellsRead++;
                }
            }
            return cellsRead == totalCells;
        } catch (Exception e) {
            return false;
        }
    }

    /**
     * Iterates through every empty cell, simulates placing an 'X',
     * and checks if it results in a win.
     * 
     * @return true if a win can be achieved by adding one 'X'.
     */
    private boolean canAchieveWinWithOneMove() {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                if (grid[r][c] == EMPTY) {
                    // Simulate move
                    grid[r][c] = PLAYER_X;

                    if (hasWinningLine()) {
                        grid[r][c] = EMPTY; // Backtrack before returning
                        return true;
                    }

                    // Backtrack
                    grid[r][c] = EMPTY;
                }
            }
        }
        return false;
    }

    /**
     * Checks the entire board for any sequence of PLAYER_X of length WIN_SEQUENCE_LENGTH.
     * 
     * @return true if a winning line exists.
     */
    private boolean hasWinningLine() {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                if (grid[r][c] == PLAYER_X) {
                    if (checkAllDirectionsFrom(r, c)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a winning sequence starts from the given cell in any of the allowed directions.
     * 
     * @param row Starting row index.
     * @param col Starting column index.
     * @return true if a sequence of length WIN_SEQUENCE_LENGTH is found.
     */
    private boolean checkAllDirectionsFrom(int row, int col) {
        for (int[] direction : DIRECTIONS) {
            if (isSequencePresent(row, col, direction[0], direction[1])) {
                return true;
            }
        }
        return false;
    }

    /**
     * Validates if a sequence of PLAYER_X of the required length exists 
     * in a specific direction.
     * 
     * @param startRow Starting row index.
     * @param startCol Starting column index.
     * @param rowDelta Change in row per step.
     * @param colDelta Change in column per step.
     * @return true if the sequence is complete and within bounds.
     */
    private boolean isSequencePresent(int startRow, int startCol, int rowDelta, int colDelta) {
        for (int step = 1; step < WIN_SEQUENCE_LENGTH; step++) {
            int currentRow = startRow + (rowDelta * step);
            int currentCol = startCol + (colDelta * step);

            if (isOutOfBounds(currentRow, currentCol) || grid[currentRow][currentCol] != PLAYER_X) {
                return false;
            }
        }
        return true;
    }

    /**
     * Checks if the given coordinates are within the grid boundaries.
     */
    private boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= GRID_SIZE || c < 0 || c >= GRID_SIZE;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * GridPathFinder searches for a specific pattern in a 10x10 grid.
 * The pattern is a straight line of 5 cells starting from an 'X' 
 * that contains at most one '.' (empty space) and no 'O' (obstacles).
 */
public class GridPathFinder {

    private static final int GRID_SIZE = 10;
    private static final int TARGET_PATH_LENGTH = 5;
    // The number of steps to take after the initial 'X'
    private static final int STEPS_TO_CHECK = TARGET_PATH_LENGTH - 1;

    // Direction vectors for 8 directions: Up-Left, Up, Up-Right, Left, Right, Down-Left, Down, Down-Right
    private static final int[] DR = {-1, -1, -1, 0, 0, 1, 1, 1};
    private static final int[] DC = {-1, 0, 1, -1, 1, -1, 0, 1};

    public static void main(String[] args) {
        FastReader reader = new FastReader();

        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        try {
            for (int i = 0; i < GRID_SIZE; i++) {
                String line = reader.next();
                if (line != null) {
                    grid[i] = line.toCharArray();
                }
            }
        } catch (Exception e) {
            System.err.println("Error reading input: " + e.getMessage());
            return;
        }

        try (PrintWriter writer = new PrintWriter(System.out)) {
            if (canFindPath(grid)) {
                writer.println("YES");
            } else {
                writer.println("NO");
            }
        }
    }

    /**
     * Iterates through the grid to find if any 'X' can initiate a valid path.
     * 
     * @param grid The 10x10 character grid.
     * @return true if a valid path is found, false otherwise.
     */
    private static boolean canFindPath(char[][] grid) {
        for (int row = 0; row < GRID_SIZE; row++) {
            for (int col = 0; col < GRID_SIZE; col++) {
                if (grid[row][col] == 'X') {
                    if (checkAllDirections(grid, row, col)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks all 8 possible directions from a starting cell.
     */
    private static boolean checkAllDirections(char[][] grid, int row, int col) {
        for (int dir = 0; dir < 8; dir++) {
            if (isValidPath(grid, row, col, DR[dir], DC[dir])) {
                return true;
            }
        }
        return false;
    }

    /**
     * Checks if a path in a specific direction meets the criteria.
     * Criteria: Path length of 5, contains at most one '.', and zero 'O'.
     */
    private static boolean isValidPath(char[][] grid, int startRow, int startCol, int dr, int dc) {
        int dotsFound = 0;

        for (int step = 1; step <= STEPS_TO_CHECK; step++) {
            int nr = startRow + (dr * step);
            int nc = startCol + (dc * step);

            // Boundary check
            if (nr < 0 || nr >= GRID_SIZE || nc < 0 || nc >= GRID_SIZE) {
                return false;
            }

            char cell = grid[nr][nc];

            if (cell == 'O') {
                return false; // Obstacle encountered
            } else if (cell == '.') {
                dotsFound++;
                if (dotsFound > 1) {
                    return false; // Too many empty spaces
                }
            }
            // 'X' and other characters are treated as valid path components
        }

        return true;
    }

    /**
     * FastReader utility class for efficient input parsing.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }
    }
}

import java.io.InputStream;
import java.io.PrintStream;
import java.util.Scanner;

/**
 * A solver that determines if a 10x10 grid contains a winning sequence.
 * A winning sequence is defined as 5 consecutive cells that do not contain 'O'
 * and contain at least 4 'X' characters.
 */
public class Main {

    private static final int GRID_SIZE = 10;
    private static final int SEQUENCE_LENGTH = 5;
    private static final int REQUIRED_X_COUNT = 4;

    // Direction vectors for: Horizontal, Vertical, Diagonal (Down-Right), Diagonal (Down-Left)
    private static final int[][] DIRECTIONS = {
        {0, 1},  // Horizontal
        {1, 0},  // Vertical
        {1, 1},  // Diagonal Down-Right
        {1, -1}  // Diagonal Down-Left
    };

    /**
     * Reads the input grid and prints the result of the sequence check.
     * 
     * @param is The input stream.
     * @param ps The output stream.
     */
    public void solve(InputStream is, PrintStream ps) {
        Scanner scanner = new Scanner(is);

        if (!scanner.hasNext()) {
            return;
        }

        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        try {
            for (int i = 0; i < GRID_SIZE; i++) {
                String line = scanner.next();
                grid[i] = line.toCharArray();
            }
        } catch (Exception e) {
            ps.println("Error reading input grid.");
            return;
        }

        if (hasWinningSequence(grid)) {
            ps.println("YES");
        } else {
            ps.println("NO");
        }
    }

    /**
     * Iterates through every cell in the grid and checks all possible directions
     * for a winning sequence.
     * 
     * @param grid The 10x10 character grid.
     * @return true if a winning sequence is found, false otherwise.
     */
    private boolean hasWinningSequence(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                for (int[] direction : DIRECTIONS) {
                    if (checkSequence(grid, r, c, direction[0], direction[1])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a sequence of a specific length starting from (r, c) 
     * in direction (dr, dc) meets the winning criteria.
     * 
     * @param grid The character grid.
     * @param r Starting row index.
     * @param c Starting column index.
     * @param dr Delta row.
     * @param dc Delta column.
     * @return true if the sequence is valid and meets requirements.
     */
    private boolean checkSequence(char[][] grid, int r, int c, int dr, int dc) {
        int xCount = 0;

        for (int i = 0; i < SEQUENCE_LENGTH; i++) {
            int nr = r + (i * dr);
            int nc = c + (i * dc);

            // 1. Check boundary conditions
            if (isOutOfBounds(nr, nc)) {
                return false;
            }

            // 2. A winning sequence cannot contain 'O'
            if (grid[nr][nc] == 'O') {
                return false;
            }

            // 3. Count 'X's
            if (grid[nr][nc] == 'X') {
                xCount++;
            }
        }

        // 4. Check if the 'X' requirement is met
        return xCount >= REQUIRED_X_COUNT;
    }

    private boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= GRID_SIZE || c < 0 || c >= GRID_SIZE;
    }

    public static void main(String[] args) {
        Main program = new Main();
        program.solve(System.in, System.out);
    }
}

import java.util.Scanner;

/**
 * A solver for a Gomoku-style game on a 10x10 grid.
 * The goal is to determine if placing a single 'X' in an empty '.' cell 
 * can create a sequence of at least 5 'X's in a row, column, or diagonal.
 */
public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        GomokuSolver solver = new GomokuSolver();

        solver.solve(scanner);

        scanner.close();
    }
}

class GomokuSolver {
    private static final int GRID_SIZE = 10;
    private static final int WINNING_SEQUENCE_LENGTH = 5;

    // To get a sequence of 5, we need to find 4 existing 'X's around a '.'
    private static final int REQUIRED_NEIGHBORS = WINNING_SEQUENCE_LENGTH - 1;

    // Direction vectors for: Horizontal, Vertical, Diagonal (\), and Anti-Diagonal (/)
    private static final int[][] DIRECTIONS = {
        {0, 1},  // Horizontal
        {1, 0},  // Vertical
        {1, 1},  // Diagonal Down-Right
        {1, -1}  // Diagonal Down-Left
    };

    /**
     * Reads the grid from the scanner and prints the result.
     */
    public void solve(Scanner scanner) {
        char[][] grid = readGrid(scanner);

        if (canFormWinningLine(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Reads a 10x10 grid from input.
     */
    private char[][] readGrid(Scanner scanner) {
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            String line = scanner.next();
            grid[i] = line.toCharArray();
        }
        return grid;
    }

    /**
     * Iterates through every cell to check if placing an 'X' in a '.' cell results in a win.
     */
    private boolean canFormWinningLine(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                if (grid[r][c] == '.' && checkWinningMove(grid, r, c)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Checks if placing an 'X' at grid[r][c] completes a sequence of 5 in any direction.
     */
    private boolean checkWinningMove(char[][] grid, int r, int c) {
        for (int[] dir : DIRECTIONS) {
            int dr = dir[0];
            int dc = dir[1];

            // Count 'X's in both directions of the current axis
            int count = countConsecutive(grid, r, c, dr, dc) 
                      + countConsecutive(grid, r, c, -dr, -dc);

            if (count >= REQUIRED_NEIGHBORS) {
                return true;
            }
        }
        return false;
    }

    /**
     * Counts how many consecutive 'X's exist starting from (r, c) in direction (dr, dc).
     * Does not include the starting cell itself.
     */
    private int countConsecutive(char[][] grid, int r, int c, int dr, int dc) {
        int count = 0;
        int nextR = r + dr;
        int nextC = c + dc;

        while (isWithinBounds(nextR, nextC) && grid[nextR][nextC] == 'X') {
            count++;
            nextR += dr;
            nextC += dc;
        }
        return count;
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
    }
}

