        scanner.close();

        boolean isWinner = checkForWin(board);
        System.out.println(isWinner ? "YES" : "NO");
    }

    /**
     * Reads the 10x10 grid from the standard input.
     */
    private static char[][] readBoard(Scanner scanner) {
        char[][] board = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            if (scanner.hasNext()) {
                String row = scanner.next();
                for (int j = 0; j < GRID_SIZE; j++) {
                    // Basic safety check for input length
                    board[i][j] = (j < row.length()) ? row.charAt(j) : ' ';
                }
            }
        }
        return board;
    }

    /**
     * Iterates through every cell in the grid and checks all directions for a winning sequence.
     */
    private static boolean checkForWin(char[][] board) {
        for (int row = 0; row < GRID_SIZE; row++) {
            for (int col = 0; col < GRID_SIZE; col++) {
                for (int[] direction : DIRECTIONS) {
                    if (isWinningSequenceAt(board, row, col, direction[0], direction[1])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a winning sequence starts at (startRow, startCol) moving in direction (dr, dc).
     */
    private static boolean isWinningSequenceAt(char[][] board, int startRow, int startCol, int dr, int dc) {
        int xCount = 0;
        int dotCount = 0;

        for (int i = 0; i < WIN_LENGTH; i++) {
            int currentRow = startRow + (i * dr);
            int currentCol = startCol + (i * dc);

            // If the sequence goes out of bounds, it's not a valid line
            if (isOutOfBounds(currentRow, currentCol)) {
                return false;
            }

            char cell = board[currentRow][currentCol];

            if (cell == PLAYER_PIECE) {
                xCount++;
            } else if (cell == WILD_CARD) {
                dotCount++;
            } else if (cell == OPPONENT_PIECE) {
                // Sequence is blocked by an opponent piece
                return false;
            } else {
                // Invalid character found
                return false;
            }
        }

        // Check if the sequence meets the win criteria
        return xCount == REQUIRED_X_COUNT && dotCount == REQUIRED_DOT_COUNT;
    }

    /**
     * Helper to validate if a coordinate is within the grid boundaries.
     */
    private static boolean isOutOfBounds(int row, int col) {
        return row < 0 || row >= GRID_SIZE || col < 0 || col >= GRID_SIZE;
    }
}

import java.util.Scanner;

/**
 * A program to detect if a "ship" of a specified length exists within a 10x10 grid.
 * The ship can be oriented horizontally, vertically, or diagonally.
 */
public class Main {

    // Grid configuration constants
    private static final int GRID_SIZE = 10;
    private static final int SHIP_LENGTH = 5;
    private static final char SHIP_CHAR = 'X';

    // Directional vectors for searching: {row_delta, column_delta}
    // Includes Horizontal, Vertical, Diagonal (Down-Right), and Anti-diagonal (Down-Left)
    private static final int[][] DIRECTIONS = {
        {0, 1},  // Horizontal
        {1, 0},  // Vertical
        {1, 1},  // Diagonal
        {1, -1}  // Anti-diagonal
    };

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // The original code was configured for 1 test case
        int numberOfTests = 1;

        for (int t = 0; t < numberOfTests; t++) {
            if (!scanner.hasNext()) {
                break;
            }

            boolean found = solve(scanner);
            System.out.println(found ? "YES" : "NO");
        }

        scanner.close();
    }

    /**
     * Coordinates the parsing and the ship detection logic.
     * 
     * @param sc The scanner for reading input.
     * @return true if a ship of SHIP_LENGTH is found, false otherwise.
     */
    private static boolean solve(Scanner sc) {
        boolean[][] grid = parseGrid(sc);
        return findShip(grid);
    }

    /**
     * Reads the 10x10 grid from the input.
     * 
     * @param sc The scanner for reading input.
     * @return A 2D boolean array where true represents a ship character.
     */
    private static boolean[][] parseGrid(Scanner sc) {
        boolean[][] grid = new boolean[GRID_SIZE][GRID_SIZE];

        for (int i = 0; i < GRID_SIZE; i++) {
            String line = sc.next();
            for (int j = 0; j < GRID_SIZE; j++) {
                // We only care if the character is the ship identifier 'X'
                grid[i][j] = (line.charAt(j) == SHIP_CHAR);
            }
        }
        return grid;
    }

    /**
     * Iterates through every cell in the grid to find the start of a ship.
     * 
     * @param grid The 2D grid to search.
     * @return true if a ship is found.
     */
    private static boolean findShip(boolean[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                // Optimization: Only attempt to check directions if the current cell is a ship part
                if (grid[r][c]) {
                    for (int[] direction : DIRECTIONS) {
                        if (isShipAt(grid, r, c, direction[0], direction[1])) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a ship of SHIP_LENGTH exists starting from a specific coordinate in a given direction.
     * 
     * @param grid The 2D grid.
     * @param startR Starting row index.
     * @param startC Starting column index.
     * @param dr Row direction delta.
     * @param dc Column direction delta.
     * @return true if the full length of the ship is found in this direction.
     */
    private static boolean isShipAt(boolean[][] grid, int startR, int startC, int dr, int dc) {
        for (int step = 0; step < SHIP_LENGTH; step++) {
            int currentRow = startR + (step * dr);
            int currentCol = startC + (step * dc);

            if (isOutOfBounds(currentRow, currentCol) || !grid[currentRow][currentCol]) {
                return false;
            }
        }
        return true;
    }

    /**
     * Validates if a given coordinate is within the grid boundaries.
     */
    private static boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= GRID_SIZE || c < 0 || c >= GRID_SIZE;
    }
}

import java.util.Scanner;

/**
 * A program to determine if a 10x10 Tic-Tac-Toe style board 
 * contains a winning sequence of 5 'X's (allowing at most one empty '.')
 */
public class Main {

    private static final int BOARD_SIZE = 10;
    private static final int WIN_LENGTH = 5;
    private static final char PLAYER_X = 'X';
    private static final char EMPTY_DOT = '.';
    private static final char PLAYER_O = 'O';

    public static void main(String[] args) {
        char[][] board = readBoard();
        if (hasWinningSequence(board)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Reads the 10x10 board from standard input.
     */
    private static char[][] readBoard() {
        Scanner sc = new Scanner(System.in);
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];

        for (int i = 0; i < BOARD_SIZE; i++) {
            if (sc.hasNext()) {
                String line = sc.next();
                for (int j = 0; j < BOARD_SIZE; j++) {
                    board[i][j] = line.charAt(j);
                }
            }
        }
        sc.close();
        return board;
    }

    /**
     * Scans the board for any winning sequence in all 4 directions.
     */
    private static boolean hasWinningSequence(char[][] board) {
        // Direction vectors: Horizontal, Vertical, Diagonal Down-Right, Diagonal Down-Left
        int[] dr = {0, 1, 1, 1};
        int[] dc = {1, 0, 1, -1};

        for (int r = 0; r < BOARD_SIZE; r++) {
            for (int c = 0; c < BOARD_SIZE; c++) {
                // From every cell, check all 4 possible directions
                for (int dir = 0; dir < 4; dir++) {
                    if (isWinningPath(board, r, c, dr[dir], dc[dir])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a sequence of WIN_LENGTH starting from (startR, startC) 
     * in direction (dr, dc) satisfies the winning condition.
     */
    private static boolean isWinningPath(char[][] board, int startR, int startC, int dr, int dc) {
        int xCount = 0;
        int dotCount = 0;

        for (int i = 0; i < WIN_LENGTH; i++) {
            int currR = startR + (i * dr);
            int currC = startC + (i * dc);

            // Check bounds
            if (isOutOfBounds(currR, currC)) {
                return false;
            }

            char cell = board[currR][currC];
            if (cell == PLAYER_X) {
                xCount++;
            } else if (cell == EMPTY_DOT) {
                dotCount++;
            } else if (cell == PLAYER_O) {
                // If an 'O' is encountered, this specific path cannot be a win for 'X'
                return false;
            }
        }

        // Winning condition: Sequence is 5 cells long and contains at most one empty dot
        // Since we only increment counts for X and dot, if an 'O' was present, 
        // xCount + dotCount would be less than 5.
        return (xCount + dotCount == WIN_LENGTH) && (dotCount < 2);
    }

    private static boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= BOARD_SIZE || c < 0 || c >= BOARD_SIZE;
    }
}

import java.util.Scanner;

/**
 * A solver to determine if a 10x10 grid can contain a line of 5 'X' characters
 * by adding at most one 'X' to a '.' cell.
 */
public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        GridPatternSolver solver = new GridPatternSolver();

        solver.solve(scanner);

        scanner.close();
    }
}

class GridPatternSolver {
    private static final int BOARD_SIZE = 10;
    private static final int WIN_LENGTH = 5;
    private static final char EMPTY = '.';
    private static final char FILLED = 'X';

    /**
     * Reads the board and outputs the result.
     * @param scanner The input source.
     */
    public void solve(Scanner scanner) {
        char[][] board = readBoard(scanner);

        if (canAchieveWin(board)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Reads a 10x10 character grid from the scanner.
     */
    private char[][] readBoard(Scanner scanner) {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i++) {
            String line = scanner.next();
            for (int j = 0; j < BOARD_SIZE; j++) {
                board[i][j] = line.charAt(j);
            }
        }
        return board;
    }

    /**
     * Attempts to place one 'X' in every possible '.' location to see
     * if any resulting board contains a line of 5 'X's.
     */
    private boolean canAchieveWin(char[][] board) {
        for (int r = 0; r < BOARD_SIZE; r++) {
            for (int c = 0; c < BOARD_SIZE; c++) {
                if (board[r][c] == EMPTY) {
                    // Try placing an 'X'
                    board[r][c] = FILLED;

                    if (hasFiveInARow(board)) {
                        // Backtrack and return immediately if win found
                        board[r][c] = EMPTY;
                        return true;
                    }

                    // Backtrack
                    board[r][c] = EMPTY;
                }
            }
        }
        return false;
    }

    /**
     * Scans the entire board for any horizontal, vertical, or diagonal line of 5 'X's.
     */
    private boolean hasFiveInARow(char[][] board) {
        for (int r = 0; r < BOARD_SIZE; r++) {
            for (int c = 0; c < BOARD_SIZE; c++) {
                if (checkHorizontal(board, r, c)) return true;
                if (checkVertical(board, r, c)) return true;
                if (checkDiagonalDownRight(board, r, c)) return true;
                if (checkDiagonalDownLeft(board, r, c)) return true;
            }
        }
        return false;
    }

    private boolean checkHorizontal(char[][] board, int r, int c) {
        if (c + WIN_LENGTH > BOARD_SIZE) return false;
        for (int i = 0; i < WIN_LENGTH; i++) {
            if (board[r][c + i] != FILLED) return false;
        }
        return true;
    }

    private boolean checkVertical(char[][] board, int r, int c) {
        if (r + WIN_LENGTH > BOARD_SIZE) return false;
        for (int i = 0; i < WIN_LENGTH; i++) {
            if (board[r + i][c] != FILLED) return false;
        }
        return true;
    }

    private boolean checkDiagonalDownRight(char[][] board, int r, int c) {
        if (r + WIN_LENGTH > BOARD_SIZE || c + WIN_LENGTH > BOARD_SIZE) return false;
        for (int i = 0; i < WIN_LENGTH; i++) {
            if (board[r + i][c + i] != FILLED) return false;
        }
        return true;
    }

    private boolean checkDiagonalDownLeft(char[][] board, int r, int c) {
        if (r + WIN_LENGTH > BOARD_SIZE || c - (WIN_LENGTH - 1) < 0) return false;
        for (int i = 0; i < WIN_LENGTH; i++) {
            if (board[r + i][c - i] != FILLED) return false;
        }
        return true;
    }
}

import java.util.Scanner;

/**
 * A program that analyzes a 10x10 grid to find a specific pattern:
 * A sequence of 5 cells in any of the 8 directions containing 
 * exactly four 'X' characters and one '.' character.
 */
public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        try {
            char[][] grid = readGrid(scanner, 10);
            GridPatternMatcher matcher = new GridPatternMatcher(grid);

            if (matcher.hasTargetPattern()) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        } catch (Exception e) {
            System.err.println("Error processing grid: " + e.getMessage());
        } finally {
            scanner.close();
        }
    }

    /**
     * Reads a square grid from the input scanner.
     */
    private static char[][] readGrid(Scanner scanner, int size) {
        char[][] grid = new char[size][size];
        for (int i = 0; i < size; i++) {
            if (scanner.hasNextLine()) {
                String line = scanner.nextLine();
                for (int j = 0; j < size; j++) {
                    // Handle cases where lines might be shorter than expected
                    grid[i][j] = (j < line.length()) ? line.charAt(j) : ' ';
                }
            }
        }
        return grid;
    }
}

/**
 * Logic engine to detect patterns within a 2D character array.
 */
class GridPatternMatcher {
    private static final int GRID_SIZE = 10;
    private static final int SEQUENCE_LENGTH = 5;
    private static final int TARGET_X_COUNT = 4;
    private static final int TARGET_DOT_COUNT = 1;

    // Direction vectors representing 8 possible movements:
    // N, S, W, E, NW, NE, SW, SE
    private static final int[] DR = {-1, 1, 0, 0, -1, -1, 1, 1};
    private static final int[] DC = {0, 0, -1, 1, 1, -1, -1, 1};

    private final char[][] grid;

    public GridPatternMatcher(char[][] grid) {
        this.grid = grid;
    }

    /**
     * Scans the entire grid to find if the pattern exists.
     * @return true if the pattern is found.
     */
    public boolean hasTargetPattern() {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                if (checkAllDirectionsFrom(r, c)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Checks all 8 directions starting from a specific cell.
     */
    private boolean checkAllDirectionsFrom(int row, int col) {
        for (int i = 0; i < DR.length; i++) {
            if (isPatternInDirection(row, col, DR[i], DC[i])) {
                return true;
            }
        }
        return false;
    }

    /**
     * Validates if a sequence of cells in a specific direction matches the pattern.
     */
    private boolean isPatternInDirection(int startR, int startC, int dR, int dC) {
        int xCount = 0;
        int dotCount = 0;

        for (int step = 0; step < SEQUENCE_LENGTH; step++) {
            int currR = startR + (step * dR);
            int currC = startC + (step * dC);

            if (!isWithinBounds(currR, currC)) {
                return false;
            }

            char cell = grid[currR][currC];
            if (cell == 'X') {
                xCount++;
            } else if (cell == '.') {
                dotCount++;
            }
        }

        return xCount == TARGET_X_COUNT && dotCount == TARGET_DOT_COUNT;
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
    }
}

import java.util.*;
import java.io.*;

/**
 * A utility to analyze a 10x10 grid to determine if a player can win 
 * by placing a single piece ('X') in an empty slot ('.').
 */
public class ConnectFiveAnalyzer {

    private static final int GRID_SIZE = 10;
    private static final int WINNING_LENGTH = 5;

    // Direction vectors representing: Horizontal, Vertical, Diagonal (top-left to bottom-right), 
    // and Anti-Diagonal (top-right to bottom-left).
    private static final int[][] DIRECTIONS = {
        {0, 1},  // Horizontal
        {1, 0},  // Vertical
        {1, 1},  // Diagonal
        {1, -1}  // Anti-Diagonal
    };

    private FastScanner scanner;
    private PrintWriter writer;

    public void run() {
        scanner = new FastScanner();
        writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            char[][] grid = readGrid();
            if (canWinByPlacingPiece(grid)) {
                writer.println("YES");
            } else {
                writer.println("NO");
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    /**
     * Reads the 10x10 grid from input.
     */
    private char[][] readGrid() {
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            String line = scanner.next();
            for (int j = 0; j < GRID_SIZE; j++) {
                grid[i][j] = line.charAt(j);
            }
        }
        return grid;
    }

    /**
     * Iterates through the grid to find if any empty cell ('.') 
     * can complete a line of 'X's of the winning length.
     */
    private boolean canWinByPlacingPiece(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                if (grid[r][c] == '.') {
                    if (checkWinningMove(grid, r, c)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks all 4 directions from a specific cell to see if placing an 'X'
     * results in a sequence of winning length.
     */
    private boolean checkWinningMove(char[][] grid, int row, int col) {
        for (int[] dir : DIRECTIONS) {
            int dr = dir[0];
            int dc = dir[1];

            // Count 'X's in the positive direction and negative direction from the current cell
            int count = 1; // Start with 1 to represent the piece we are placing
            count += countConsecutive(grid, row, col, dr, dc);
            count += countConsecutive(grid, row, col, -dr, -dc);

            if (count >= WINNING_LENGTH) {
                return true;
            }
        }
        return false;
    }

    /**
     * Counts consecutive 'X' characters in a specific direction.
     */
    private int countConsecutive(char[][] grid, int row, int col, int dr, int dc) {
        int count = 0;
        int currR = row + dr;
        int currC = col + dc;

        while (isInBounds(currR, currC) && grid[currR][currC] == 'X') {
            count++;
            currR += dr;
            currC += dc;
        }
        return count;
    }

    private boolean isInBounds(int r, int c) {
        return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
    }

    public static void main(String[] args) {
        new ConnectFiveAnalyzer().run();
    }

    /**
     * Optimized scanner for fast I/O operations.
     */
    static class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }
    }
}

import java.util.Scanner;

/**
 * ConnectFive: A program to determine if a winning move (5 in a row) 
 * can be made on a 10x10 grid.
 */
public class ConnectFive {

    private static final int GRID_SIZE = 10;
    private static final int WINNING_LENGTH = 5;

    // Direction vectors for the four axes: Horizontal, Vertical, Diagonal (\), Diagonal (/)
    private static final int[][] DIRECTIONS = {
        {0, 1},  // Horizontal
        {1, 0},  // Vertical
        {1, 1},  // Diagonal Down-Right
        {1, -1}  // Diagonal Down-Left
    };

    public static void main(String[] args) {
        ConnectFive game = new ConnectFive();
        game.run();
    }

    /**
     * Orchestrates the input, logic, and output.
     */
    public void run() {
        char[][] grid = readGrid();
        if (canWin(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Reads the 10x10 grid from standard input.
     * @return A 2D char array representing the grid.
     */
    private char[][] readGrid() {
        Scanner scanner = new Scanner(System.in);
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];

        for (int i = 0; i < GRID_SIZE; i++) {
            if (scanner.hasNext()) {
                String line = scanner.next();
                for (int j = 0; j < GRID_SIZE; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }
        }
        return grid;
    }

    /**
     * Scans the grid to see if placing an 'X' in any '.' cell creates a winning line.
     * @param grid The current state of the board.
     * @return true if a winning move is possible, false otherwise.
     */
    private boolean canWin(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                // We can only place an 'X' in an empty '.' cell
                if (grid[r][c] == '.') {
                    if (checkWinningMove(grid, r, c)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if placing an 'X' at the specified coordinate results in 5 in a row.
     */
    private boolean checkWinningMove(char[][] grid, int row, int col) {
        for (int[] direction : DIRECTIONS) {
            int dr = direction[0];
            int dc = direction[1];

            // Count consecutive 'X's in the positive direction and the negative direction
            int countInDirection = countConsecutive(grid, row, col, dr, dc);
            int countInOppositeDirection = countConsecutive(grid, row, col, -dr, -dc);

            // Total length = existing in dir1 + existing in dir2 + the new 'X' we just placed
            // We need total length >= WINNING_LENGTH, which means (count1 + count2) >= 4
            if (countInDirection + countInOppositeDirection >= WINNING_LENGTH - 1) {
                return true;
            }
        }
        return false;
    }

    /**
     * Counts consecutive 'X' characters in a specific direction starting from a given cell.
     * 
     * @param grid The board.
     * @param row Starting row index.
     * @param col Starting column index.
     * @param dr Row direction (-1, 0, or 1).
     * @param dc Column direction (-1, 0, or 1).
     * @return The number of consecutive 'X' characters found.
     */
    private int countConsecutive(char[][] grid, int row, int col, int dr, int dc) {
        int count = 0;
        int currentRow = row + dr;
        int currentCol = col + dc;

        while (isWithinBounds(currentRow, currentCol) && grid[currentRow][currentCol] == 'X') {
            count++;
            currentRow += dr;
            currentCol += dc;
        }

        return count;
    }

    /**
     * Validates if the given coordinates are within the grid boundaries.
     */
    private boolean isWithinBounds(int row, int col) {
        return row >= 0 && row < GRID_SIZE && col >= 0 && col < GRID_SIZE;
    }
}

import java.util.Scanner;

/**
 * FiveInRow determines if a 10x10 board can form a "five-in-a-row" 
 * by placing a single 'X' in an available '.' spot.
 */
public class FiveInRow {

    private static final int BOARD_SIZE = 10;
    private static final int WIN_LENGTH = 5;
    private static final char PLAYER_X = 'X';
    private static final char EMPTY_SPOT = '.';

    private final char[][] board;

    /**
     * Initializes the game with a 2D character array representing the board.
     * @param board a 10x10 grid of characters.
     */
    public FiveInRow(char[][] board) {
        this.board = board;
    }

    /**
     * Scans the board to see if any sequence of 5 cells can be completed 
     * to form a row of 5 'X's.
     * 
     * @return true if a win can be formed, false otherwise.
     */
    public boolean canFormFiveInRow() {
        for (int row = 0; row < BOARD_SIZE; row++) {
            for (int col = 0; col < BOARD_SIZE; col++) {
                // We check 4 directions: Horizontal, Vertical, Diagonal Down-Right, and Diagonal Down-Left.
                // These 4 directions, when applied to every cell, cover all possible lines of 5.
                if (checkDirection(row, col, 0, 1) ||  // Horizontal
                    checkDirection(row, col, 1, 0) ||  // Vertical
                    checkDirection(row, col, 1, 1) ||  // Diagonal Down-Right
                    checkDirection(row, col, 1, -1)) { // Diagonal Down-Left
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Checks a specific direction from a starting point to see if it contains
     * exactly 4 'X's and 1 '.' within a window of WIN_LENGTH.
     */
    private boolean checkDirection(int startRow, int startCol, int rowDelta, int colDelta) {
        int xCount = 0;
        int dotCount = 0;

        for (int i = 0; i < WIN_LENGTH; i++) {
            int currentRow = startRow + (i * rowDelta);
            int currentCol = startCol + (i * colDelta);

            if (isOutOfBounds(currentRow, currentCol)) {
                return false;
            }

            char cell = board[currentRow][currentCol];
            if (cell == PLAYER_X) {
                xCount++;
            } else if (cell == EMPTY_SPOT) {
                dotCount++;
            } else {
                // If the cell contains 'O' or any other character, this line is invalid.
                return false;
            }
        }

        // To be able to form a row of 5, we must have exactly 4 'X's and 1 empty spot.
        return xCount == 4 && dotCount == 1;
    }

    private boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= BOARD_SIZE || c < 0 || c >= BOARD_SIZE;
    }

    /**
     * Entry point of the program. Handles input reading and output.
     */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            char[][] board = readBoard(scanner);
            FiveInRow game = new FiveInRow(board);

            System.out.println(game.canFormFiveInRow() ? "YES" : "NO");
        } catch (Exception e) {
            // Standard error handling for production-grade software
            System.err.println("Error processing input: " + e.getMessage());
        }
    }

    /**
     * Reads a 10x10 board from the scanner.
     */
    private static char[][] readBoard(Scanner scanner) {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (scanner.hasNext()) {
                String line = scanner.next();
                for (int j = 0; j < BOARD_SIZE; j++) {
                    board[i][j] = line.charAt(j);
                }
            }
        }
        return board;
    }
}

