            if (scanner.hasNext()) {
                grid[i] = scanner.next().toCharArray();
            }
        }
        return grid;
    }

    /**
     * Scans the entire grid for any winning sequence in any of the 4 directions.
     */
    private static boolean hasWinningSequence(char[][] grid) {
        // Directions: {rowDelta, colDelta}
        // Horizontal, Vertical, Diagonal Down-Right, Diagonal Up-Right
        int[][] directions = {
            {0, 1},  
            {1, 0},  
            {1, 1},  
            {-1, 1}  
        };

        for (int r = 0; r < BOARD_SIZE; r++) {
            for (int c = 0; c < BOARD_SIZE; c++) {
                for (int[] dir : directions) {
                    if (isSequenceWinning(grid, r, c, dir[0], dir[1])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a sequence of WIN_LENGTH starting from (startRow, startCol) 
     * in the given direction meets the winning criteria.
     */
    private static boolean isSequenceWinning(char[][] grid, int startRow, int startCol, int dr, int dc) {
        int xCount = 0;
        int dotCount = 0;

        for (int i = 0; i < WIN_LENGTH; i++) {
            int currentRow = startRow + (i * dr);
            int currentCol = startCol + (i * dc);

            // Check bounds
            if (isOutOfBounds(currentRow, currentCol)) {
                return false;
            }

            char cell = grid[currentRow][currentCol];
            if (cell == PLAYER_PIECE) {
                xCount++;
            } else if (cell == WILD_CARD) {
                dotCount++;
            }
        }

        // A sequence is winning if it's all 'X's, or 4 'X's and 1 '.'
        return (xCount == WIN_LENGTH) || (xCount == WIN_LENGTH - 1 && dotCount == 1);
    }

