import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * A program that searches a 10x10 grid for a specific pattern:
 * A sequence of 5 consecutive cells (horizontal, vertical, or diagonal)
 * containing exactly 4 'X' characters and 1 '.' character.
 */
public class GridPatternMatcher {

    private static final int GRID_SIZE = 10;
    private static final int PATTERN_LENGTH = 5;
    private static final int REQUIRED_X = 4;
    private static final int REQUIRED_DOT = 1;

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        Solver solver = new Solver(reader);
        solver.solve(out);

        out.flush();
        out.close();
    }

    static class Solver {
        private final FastReader reader;

        public Solver(FastReader reader) {
            this.reader = reader;
        }

        public void solve(PrintWriter out) {
            char[][] grid = readGrid();

            if (containsPattern(grid)) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        }

        private char[][] readGrid() {
            char[][] grid = new char[GRID_SIZE][GRID_SIZE];
            for (int i = 0; i < GRID_SIZE; i++) {
                grid[i] = reader.next().toCharArray();
            }
            return grid;
        }

        /**
         * Scans the grid in all 4 directions (Horizontal, Vertical, and 2 Diagonals)
         * to find the target pattern.
         */
        private boolean containsPattern(char[][] grid) {
            // Direction vectors: {row_delta, col_delta}
            // {0, 1} -> Horizontal
            // {1, 0} -> Vertical
            // {1, 1} -> Diagonal (Down-Right)
            // {1, -1} -> Diagonal (Down-Left)
            int[][] directions = {
                {0, 1}, 
                {1, 0}, 
                {1, 1}, 
                {1, -1}
            };

            for (int r = 0; r < GRID_SIZE; r++) {
                for (int c = 0; c < GRID_SIZE; c++) {
                    for (int[] dir : directions) {
                        if (isPatternAt(grid, r, c, dir[0], dir[1])) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        /**
         * Checks if the pattern starts at (startRow, startCol) and extends 
         * in the given direction.
         */
        private boolean isPatternAt(char[][] grid, int startRow, int startCol, int dr, int dc) {
            int countX = 0;
            int countDot = 0;

            for (int step = 0; step < PATTERN_LENGTH; step++) {
                int currR = startRow + (step * dr);
                int currC = startCol + (step * dc);

                // Check grid boundaries
                if (currR < 0 || currR >= GRID_SIZE || currC < 0 || currC >= GRID_SIZE) {
                    return false;
                }

                if (grid[currR][currC] == 'X') {
                    countX++;
                } else if (grid[currR][currC] == '.') {
                    countDot++;
                }
            }

            return countX == REQUIRED_X && countDot == REQUIRED_DOT;
        }
    }

    /**
     * Utility class for efficient input reading.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(java.io.InputStream inputStream) {
            br = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }
    }
}

import java.util.Scanner;

/**
 * A solver for determining if a single move can complete a line of five 
 * consecutive 'X's on a 10x10 grid.
 */
public class ConnectFiveSolver {

    private static final int GRID_SIZE = 10;
    private static final int WIN_CONDITION = 5;
    private static final char EMPTY = '.';
    private static final char PLAYER_X = 'X';

    private final char[][] grid;

    public ConnectFiveSolver() {
        this.grid = new char[GRID_SIZE][GRID_SIZE];
    }

    public static void main(String[] args) {
        ConnectFiveSolver solver = new ConnectFiveSolver();
        solver.execute();
    }

    /**
     * Orchestrates the input, processing, and output.
     */
    public void execute() {
        if (loadGridFromInput()) {
            boolean canWin = checkIfMovePossible();
            System.out.println(canWin ? "YES" : "NO");
        }
    }

    /**
     * Reads the 10x10 grid from standard input.
     * @return true if input was successfully loaded.
     */
    private boolean loadGridFromInput() {
        try (Scanner scanner = new Scanner(System.in)) {
            for (int i = 0; i < GRID_SIZE; i++) {
                if (scanner.hasNext()) {
                    String line = scanner.next();
                    if (line.length() >= GRID_SIZE) {
                        for (int j = 0; j < GRID_SIZE; j++) {
                            grid[i][j] = line.charAt(j);
                        }
                    }
                }
            }
            return true;
        } catch (Exception e) {
            return false;
        }
    }

    /**
     * Iterates through every empty cell and tests if placing an 'X'
     * completes a winning line.
     * 
     * @return true if any single move results in a win.
     */
    private boolean checkIfMovePossible() {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                if (grid[r][c] == EMPTY) {
                    // Try placing a piece
                    grid[r][c] = PLAYER_X;

                    if (hasWinningLine()) {
                        return true;
                    }

                    // Backtrack: remove the piece
                    grid[r][c] = EMPTY;
                }
            }
        }
        return false;
    }

    /**
     * Scans the board to check if any direction contains a sequence 
     * of 'X's equal to the WIN_CONDITION.
     * 
     * @return true if a winning line exists.
     */
    private boolean hasWinningLine() {
        // Direction vectors: Horizontal, Vertical, Diagonal Down-Right, Diagonal Down-Left
        int[] rowOffsets = {0, 1, 1, 1};
        int[] colOffsets = {1, 0, 1, -1};

        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                if (grid[r][c] == PLAYER_X) {
                    for (int dir = 0; dir < 4; dir++) {
                        if (checkDirection(r, c, rowOffsets[dir], colOffsets[dir])) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if there is a continuous line of PLAYER_X in a specific direction.
     * 
     * @param startR Starting row index.
     * @param startC Starting column index.
     * @param dr Row direction offset.
     * @param dc Column direction offset.
     * @return true if the sequence length meets the WIN_CONDITION.
     */
    private boolean checkDirection(int startR, int startC, int dr, int dc) {
        int count = 0;
        for (int step = 0; step < WIN_CONDITION; step++) {
            int currR = startR + (dr * step);
            int currC = startC + (dc * step);

            if (isWithinBounds(currR, currC) && grid[currR][currC] == PLAYER_X) {
                count++;
            } else {
                break;
            }
        }
        return count == WIN_CONDITION;
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
    }
}

import java.util.Scanner;

/**
 * A solver for a grid-based game where the goal is to find if placing 
 * a single piece can create a line of five consecutive 'X's.
 */
public class ConnectFiveSolver {

    private static final int GRID_SIZE = 10;
    private static final int WIN_LENGTH = 5;
    private static final char EMPTY_CELL = '.';
    private static final char FILLED_CELL = 'X';

    // Direction vectors for: Horizontal, Vertical, Diagonal Down-Right, Diagonal Down-Left
    private static final int[][] DIRECTIONS = {
        {0, 1},  // Horizontal
        {1, 0},  // Vertical
        {1, 1},  // Diagonal \
        {1, -1}  // Diagonal /
    };

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] grid = readGrid(scanner);
        scanner.close();

        if (canWinWithOneMove(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Reads a 10x10 grid from the input.
     */
    private static char[][] readGrid(Scanner scanner) {
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            if (scanner.hasNextLine()) {
                String line = scanner.nextLine();
                for (int j = 0; j < GRID_SIZE; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }
        }
        return grid;
    }

    /**
     * Iterates through every empty cell, simulates placing an 'X', 
     * and checks if that move results in a win.
     */
    private static boolean canWinWithOneMove(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                if (grid[r][c] == EMPTY_CELL) {
                    // Simulate move
                    grid[r][c] = FILLED_CELL;

                    if (hasWinningLine(grid)) {
                        // Backtrack before returning
                        grid[r][c] = EMPTY_CELL;
                        return true;
                    }

                    // Backtrack
                    grid[r][c] = EMPTY_CELL;
                }
            }
        }
        return false;
    }

    /**
     * Checks the entire grid to see if any line of 5 consecutive 'X's exists.
     */
    private static boolean hasWinningLine(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                // Optimization: Only start checking if the current cell is an 'X'
                if (grid[r][c] == FILLED_CELL) {
                    for (int[] direction : DIRECTIONS) {
                        if (checkDirection(grid, r, c, direction[0], direction[1])) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if there is a sequence of WIN_LENGTH 'X's starting from (row, col) 
     * moving in the specified (deltaRow, deltaCol) direction.
     */
    private static boolean checkDirection(char[][] grid, int row, int col, int deltaRow, int deltaCol) {
        int count = 0;
        for (int step = 0; step < WIN_LENGTH; step++) {
            int nextR = row + (step * deltaRow);
            int nextC = col + (step * deltaCol);

            if (isWithinBounds(nextR, nextC) && grid[nextR][nextC] == FILLED_CELL) {
                count++;
            } else {
                break;
            }
        }
        return count == WIN_LENGTH;
    }

    private static boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
    }
}

import java.util.Scanner;

/**
 * A program to determine if a 10x10 grid contains a winning sequence.
 * A winning sequence is defined as 4 or more consecutive cells that are not 'O',
 * where at least 4 of those cells are 'X'.
 */
public class Main {

    private static final int GRID_SIZE = 10;
    private static final int WIN_THRESHOLD = 4;
    private static final char OBSTACLE = 'O';
    private static final char PLAYER_PIECE = 'X';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] grid = readGrid(scanner);
        scanner.close();

        if (hasWinningSequence(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Reads the 10x10 grid from standard input.
     */
    private static char[][] readGrid(Scanner scanner) {
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            if (scanner.hasNextLine()) {
                String line = scanner.nextLine();
                for (int j = 0; j < GRID_SIZE; j++) {
                    // Default to a space if the line is shorter than expected
                    grid[i][j] = (j < line.length()) ? line.charAt(j) : ' ';
                }
            }
        }
        return grid;
    }

    /**
     * Iterates through the grid to find any winning line.
     */
    private static boolean hasWinningSequence(char[][] grid) {
        // Directions to check: Horizontal, Vertical, Diagonal (\), and Anti-Diagonal (/)
        int[][] directions = {
            {0, 1},  // Right
            {1, 0},  // Down
            {1, 1},  // Down-Right
            {1, -1}  // Down-Left
        };

        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                // Skip cells that are obstacles
                if (grid[r][c] == OBSTACLE) {
                    continue;
                }

                // Check every direction from the current cell
                for (int[] dir : directions) {
                    if (checkDirection(grid, r, c, dir[0], dir[1])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks a specific direction from a starting point to see if it forms a winning sequence.
     * A win is 4+ consecutive non-obstacle cells containing 4+ 'X' pieces.
     */
    private static boolean checkDirection(char[][] grid, int startRow, int startCol, int dr, int dc) {
        int consecutiveNonObstacleCount = 0;
        int playerPieceCount = 0;

        int currentRow = startRow;
        int currentCol = startCol;

        // Traverse the grid in the given direction
        while (isWithinBounds(currentRow, currentCol) && grid[currentRow][currentCol] != OBSTACLE) {
            consecutiveNonObstacleCount++;
            if (grid[currentRow][currentCol] == PLAYER_PIECE) {
                playerPieceCount++;
            }

            currentRow += dr;
            currentCol += dc;

            // Optimization: If we've found a win, return immediately
            if (consecutiveNonObstacleCount >= WIN_THRESHOLD && playerPieceCount >= WIN_THRESHOLD) {
                return true;
            }
        }

        // Re-check condition after loop for edge cases where sequence length is 4 or 5
        return consecutiveNonObstacleCount >= WIN_THRESHOLD && playerPieceCount >= WIN_THRESHOLD;
    }

    /**
     * Ensures the coordinates are within the grid boundaries.
     */
    private static boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
    }
}

import java.util.Scanner;

/**
 * A utility to detect specific patterns of 'X' characters in a 2D grid.
 */
public class PatternDetector {

    private static final int GRID_SIZE = 10;
    private static final int REQUIRED_X_COUNT = 4;
    private static final char EMPTY_CELL = '.';
    private static final char X_CELL = 'X';

    // Direction vectors for: Horizontal, Vertical, Diagonal (\), Diagonal (/)
    private static final int[][] DIRECTIONS = {
        {0, 1},  // Horizontal axis
        {1, 0},  // Vertical axis
        {1, 1},  // Top-left to bottom-right diagonal
        {1, -1}  // Top-right to bottom-left diagonal
    };

    private final char[][] grid;

    public PatternDetector(char[][] grid) {
        this.grid = grid;
    }

    /**
     * Scans the grid to see if any empty cell '.' serves as a center point
     * for a line of at least REQUIRED_X_COUNT 'X' cells in any direction.
     *
     * @return true if the pattern is found, false otherwise.
     */
    public boolean hasPattern() {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                if (grid[r][c] == EMPTY_CELL) {
                    if (checkDirectionsAt(r, c)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks all 4 axes passing through the given cell.
     */
    private boolean checkDirectionsAt(int row, int col) {
        for (int[] dir : DIRECTIONS) {
            int dr = dir[0];
            int dc = dir[1];

            // Count 'X's in both directions of the current axis
            int count = countConsecutive(row, col, dr, dc) + 
                        countConsecutive(row, col, -dr, -dc);

            if (count >= REQUIRED_X_COUNT) {
                return true;
            }
        }
        return false;
    }

    /**
     * Counts consecutive 'X' cells starting from the cell adjacent to (startR, startC)
     * in the direction of (dr, dc).
     */
    private int countConsecutive(int startR, int startC, int dr, int dc) {
        int count = 0;
        int r = startR + dr;
        int c = startC + dc;

        while (isWithinBounds(r, c) && grid[r][c] == X_CELL) {
            count++;
            r += dr;
            c += dc;
        }
        return count;
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];

        try {
            // Initialize grid from input
            for (int i = 0; i < GRID_SIZE; i++) {
                String line = scanner.next();
                grid[i] = line.toCharArray();
            }

            PatternDetector detector = new PatternDetector(grid);

            if (detector.hasPattern()) {
                System.out.print("YES");
            } else {
                System.out.print("NO");
            }
        } catch (Exception e) {
            // In a real-world scenario, handle or log exceptions appropriately
            System.err.println("Error processing grid: " + e.getMessage());
        } finally {
            scanner.close();
        }
    }
}

