            }
        }
        return grid;
    }

    /**
     * Iterates through every cell and every direction to find a winning sequence.
     */
    private static boolean checkWinningCondition(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                for (int[] direction : DIRECTIONS) {
                    if (isWinningSequenceAt(grid, r, c, direction[0], direction[1])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a valid sequence of length 5 starts at (startRow, startCol) 
     * moving in direction (dr, dc).
     */
    private static boolean isWinningSequenceAt(char[][] grid, int startRow, int startCol, int dr, int dc) {
        int xCount = 0;
        int dotCount = 0;

        for (int i = 0; i < SEQUENCE_LENGTH; i++) {
            int currentRow = startRow + (i * dr);
            int currentCol = startCol + (i * dc);

            // Check bounds
            if (isOutOfBounds(currentRow, currentCol)) {
                return false;
            }

            char cell = grid[currentRow][currentCol];
            if (cell == TARGET_X) {
                xCount++;
            } else if (cell == TARGET_DOT) {
                dotCount++;
            } else {
                // If we encounter any other character, this sequence is invalid
                return false;
            }
        }

        return xCount == REQUIRED_X_COUNT && dotCount == REQUIRED_DOT_COUNT;
