/**
 * A solver that determines if a 10x10 grid can be turned into a 
 * "five-in-a-row" game by replacing exactly one '.' with an 'X'.
 */
public class FiveInARowSolver {

    private static final int GRID_SIZE = 10;
    private static final int LINE_LENGTH = 5;
    private static final char TARGET_CHAR = 'X';
    private static final char EMPTY_CHAR = '.';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] grid = readGrid(scanner);
        scanner.close();

        if (canCompleteFiveInARow(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Reads a 10x10 grid from the scanner.
     */
    private static char[][] readGrid(Scanner scanner) {
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            if (scanner.hasNextLine()) {
                String line = scanner.nextLine();
                for (int j = 0; j < GRID_SIZE; j++) {
                    // Handle potential short lines to prevent IndexOutOfBounds
                    grid[i][j] = (j < line.length()) ? line.charAt(j) : ' ';
                }
            }
        }
        return grid;
    }

    /**
     * Checks if there exists any 5-length segment (horizontal, vertical, or diagonal)
     * that contains exactly four 'X's and one '.'.
     */
    private static boolean canCompleteFiveInARow(char[][] grid) {
        // Directions to check: 
        // [row_delta, col_delta]
        // 1. Horizontal (0, 1)
        // 2. Vertical (1, 0)
        // 3. Diagonal Down-Right (1, 1)
        // 4. Diagonal Down-Left (1, -1)
        int[][] directions = {
            {0, 1},
            {1, 0},
            {1, 1},
            {1, -1}
        };

        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                for (int[] dir : directions) {
                    if (isWinningSegment(grid, r, c, dir[0], dir[1])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Validates if a specific segment of length 5 starting at (r, c) 
     * in direction (dr, dc) can form a line of five 'X's.
     */
    private static boolean isWinningSegment(char[][] grid, int r, int c, int dr, int dc) {
        int xCount = 0;
        int dotCount = 0;

        for (int i = 0; i < LINE_LENGTH; i++) {
            int nr = r + (i * dr);
            int nc = c + (i * dc);

            // Check bounds
            if (nr < 0 || nr >= GRID_SIZE || nc < 0 || nc >= GRID_SIZE) {
                return false;
            }

            if (grid[nr][nc] == TARGET_CHAR) {
                xCount++;
            } else if (grid[nr][nc] == EMPTY_CHAR) {
                dotCount++;
            } else {
                // If the segment contains any other character, it's invalid
                return false;
            }
        }

        // A segment is a winner if it has 4 'X's and 1 '.'
        return xCount == 4 && dotCount == 1;
    }
}

