import java.util.Scanner;

/**
 * A program to determine if a move on a 10x10 checkerboard 
 * can complete a sequence of at least 4 'X' characters.
 */
public class Main {

    private static final int GRID_SIZE = 10;
    private static final int WIN_THRESHOLD = 4;
    private static final char EMPTY_CELL = '.';
    private static final char PLAYER_PIECE = 'X';

    // Direction vectors representing: Horizontal, Vertical, Diagonal Down-Right, Diagonal Down-Left
    private static final int[][] DIRECTIONS = {
            {0, 1},
            {1, 0},
            {1, 1},
            {1, -1}
    };

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        while (scanner.hasNext()) {
            char[][] board = readBoard(scanner);
            if (board == null) break;

            if (hasWinningMove(board)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
        scanner.close();
    }

    /**
     * Reads the 10x10 grid from the scanner.
     */
    private static char[][] readBoard(Scanner scanner) {
        char[][] board = new char[GRID_SIZE][GRID_SIZE];
        try {
            for (int i = 0; i < GRID_SIZE; i++) {
                String line = scanner.next();
                for (int j = 0; j < GRID_SIZE; j++) {
                    board[i][j] = line.charAt(j);
                }
            }
        } catch (Exception e) {
            return null;
        }
        return board;
    }

    /**
     * Scans the board for an empty cell that, if filled, 
     * would create a line of at least WIN_THRESHOLD player pieces.
     */
    private static boolean hasWinningMove(char[][] board) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                if (board[r][c] == EMPTY_CELL) {
                    if (checkDirectionsAt(board, r, c)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks all 4 axes (Horizontal, Vertical, and two Diagonals) 
     * passing through the given cell.
     */
    private static boolean checkDirectionsAt(char[][] board, int row, int col) {
        for (int[] dir : DIRECTIONS) {
            int dr = dir[0];
            int dc = dir[1];

            // Count consecutive pieces in both directions along the current axis
            int count = countConsecutive(board, row, col, dr, dc)
                      + countConsecutive(board, row, col, -dr, -dc);

            if (count >= WIN_THRESHOLD) {
                return true;
            }
        }
        return false;
    }

    /**
     * Counts how many consecutive PLAYER_PIECE characters exist 
     * starting from the cell adjacent to (r, c) in direction (dr, dc).
     */
    private static int countConsecutive(char[][] board, int r, int c, int dr, int dc) {
        int count = 0;
        int currR = r + dr;
        int currC = c + dc;

        while (isWithinBounds(currR, currC) && board[currR][currC] == PLAYER_PIECE) {
            count++;
            currR += dr;
            currC += dc;
        }
        return count;
    }

    private static boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
    }
}

import java.io.*;
