/**
 * A solver for a game where we check if a 10x10 grid of 'X' and '.'
 * can form a line of 4 'X's by replacing exactly one '.' with an 'X'.
 */
public class XOXGameSolver {

    private static final int GRID_SIZE = 10;
    private static final int WIN_LENGTH = 4;

    private final char[][] grid = new char[GRID_SIZE][GRID_SIZE];

    public static void main(String[] args) {
        XOXGameSolver solver = new XOXGameSolver();
        solver.run();
    }

    /**
     * Orchestrates the reading, solving, and printing processes.
     */
    public void run() {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            loadGrid(reader);
            if (canWinByReplacingOneDot()) {
                writer.println("YES");
            } else {
                writer.println("NO");
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    /**
     * Reads the 10x10 grid from the input stream.
     */
    private void loadGrid(FastReader reader) {
        for (int i = 0; i < GRID_SIZE; i++) {
            String line = reader.next();
            if (line == null) break;
            grid[i] = line.toCharArray();
        }
    }

    /**
     * Iterates through all possible directions and segments to find a winning line.
     */
    private boolean canWinByReplacingOneDot() {
        // Directions: Horizontal, Vertical, Diagonal (\), Diagonal (/)
        int[][] directions = {
            {0, 1},  // Horizontal
            {1, 0},  // Vertical
            {1, 1},  // Diagonal Down-Right
            {1, -1}  // Diagonal Down-Left
        };

        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                for (int[] dir : directions) {
                    if (isValidSegment(r, c, dir[0], dir[1])) {
                        if (isWinningSegment(r, c, dir[0], dir[1])) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a segment of WIN_LENGTH starting at (r, c) in direction (dr, dc) 
     * stays within the grid boundaries.
     */
    private boolean isValidSegment(int r, int c, int dr, int dc) {
        int endR = r + (WIN_LENGTH - 1) * dr;
        int endC = c + (WIN_LENGTH - 1) * dc;
        return endR >= 0 && endR < GRID_SIZE && endC >= 0 && endC < GRID_SIZE;
    }

    /**
     * A segment is a winner if it contains exactly (WIN_LENGTH - 1) 'X's 
     * and exactly one '.'.
     */
    private boolean isWinningSegment(int r, int c, int dr, int dc) {
        int xCount = 0;
        int dotCount = 0;

        for (int i = 0; i < WIN_LENGTH; i++) {
            char cell = grid[r + i * dr][c + i * dc];
            if (cell == 'X') {
                xCount++;
            } else if (cell == '.') {
                dotCount++;
            }
        }

        return xCount == (WIN_LENGTH - 1) && dotCount == 1;
    }

    /**
     * Optimized reader for fast I/O operations.
     */
    static class FastReader {
