import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * A utility to find if any '.' cell in a grid is part of a 
 * continuous line of at least 5 cells (1 '.' and 4 'X's).
 */
public class GridPatternMatcher {

    private static final char TARGET_EMPTY = '.';
    private static final char TARGET_FILL = 'X';
    private static final int REQUIRED_X_COUNT = 4;

    // Directions representing: Horizontal, Vertical, Diagonal, Anti-Diagonal
    private static final int[][] DIRECTIONS = {
        {0, 1},  // Horizontal
        {1, 0},  // Vertical
        {1, 1},  // Diagonal (\)
        {1, -1}  // Anti-Diagonal (/)
    };

    public static void main(String[] args) {
        GridPatternMatcher matcher = new GridPatternMatcher(System.in, System.out);
        matcher.run();
    }

    private final FastReader reader;
    private final PrintWriter out;

    public GridPatternMatcher(InputStream inputStream, java.io.OutputStream outputStream) {
        this.reader = new FastReader(inputStream);
        this.out = new PrintWriter(outputStream);
    }

    /**
     * Orchestrates the reading of input and execution of the logic.
     */
    public void run() {
        try {
            solve();
        } catch (Exception e) {
            // In a production environment, use a logger here
            e.printStackTrace();
        } finally {
            out.close();
        }
    }

    private void solve() {
        // Read grid size N
        String nInput = reader.next();
        if (nInput == null) return;
        int n = Integer.parseInt(nInput);

        char[][] grid = new char[n][n];
        for (int i = 0; i < n; i++) {
            grid[i] = reader.next().toCharArray();
        }

        if (hasPattern(grid, n)) {
            out.println("YES");
        } else {
            out.println("NO");
        }
    }

    /**
     * Iterates through the grid to find if any empty cell meets the pattern criteria.
     */
    private boolean hasPattern(char[][] grid, int n) {
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == TARGET_EMPTY) {
                    if (isPartOfLine(grid, n, r, c)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if the cell at (row, col) is part of a line of 'X's in any direction.
     */
    private boolean isPartOfLine(char[][] grid, int n, int row, int col) {
        for (int[] dir : DIRECTIONS) {
            if (countConsecutiveX(grid, n, row, col, dir[0], dir[1]) >= REQUIRED_X_COUNT) {
                return true;
            }
        }
        return false;
    }

    /**
     * Counts consecutive 'X' characters in both directions of a given vector.
     */
    private int countConsecutiveX(char[][] grid, int n, int row, int col, int dr, int dc) {
        int count = 0;

        // Check in the positive direction
        count += countInDirection(grid, n, row, col, dr, dc);
        // Check in the negative direction
        count += countInDirection(grid, n, row, col, -dr, -dc);

        return count;
    }

    private int countInDirection(char[][] grid, int n, int row, int col, int dr, int dc) {
        int count = 0;
        int r = row + dr;
        int c = col + dc;

        while (r >= 0 && r < n && c >= 0 && c < n && grid[r][c] == TARGET_FILL) {
            count++;
            r += dr;
            c += dc;
        }
        return count;
    }

    /**
     * Optimized reader for fast I/O performance.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            this.reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }
    }
}

import java.util.Scanner;

/**
 * A program that analyzes a 10x10 grid to find if a '.' cell 
 * is part of a continuous line of at least 5 'X' characters 
 * (including the '.' itself).
 */
public class Main {

    private static final int GRID_SIZE = 10;
    private static final int TARGET_LENGTH = 5;
    private static final char EMPTY_CELL = '.';
    private static final char FILLED_CELL = 'X';

    public static void main(String[] args) {
        char[][] grid = readGrid();

        if (hasWinningLine(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Reads the 10x10 grid from standard input.
     */
    private static char[][] readGrid() {
        Scanner scanner = new Scanner(System.in);
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];

        for (int i = 0; i < GRID_SIZE; i++) {
            if (scanner.hasNext()) {
                String line = scanner.next();
                for (int j = 0; j < GRID_SIZE; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }
        }
        scanner.close();
        return grid;
    }

    /**
     * Iterates through the grid to find if any empty cell satisfies the winning condition.
     */
    private static boolean hasWinningLine(char[][] grid) {
        // Direction vectors for: Horizontal, Vertical, Diagonal (\), Anti-Diagonal (/)
        int[] dr = {0, 1, 1, 1};
        int[] dc = {1, 0, 1, -1};

        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                if (grid[r][c] == EMPTY_CELL) {
                    if (checkAllDirections(grid, r, c, dr, dc)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks all four possible axes passing through a specific cell.
     */
    private static boolean checkAllDirections(char[][] grid, int r, int c, int[] dr, int[] dc) {
        for (int i = 0; i < dr.length; i++) {
            // The total length is the cell itself (1) + count in positive direction + count in negative direction
            int lineLength = 1 
                + countConsecutiveX(grid, r, c, dr[i], dc[i]) 
                + countConsecutiveX(grid, r, c, -dr[i], -dc[i]);

            if (lineLength >= TARGET_LENGTH) {
                return true;
            }
        }
        return false;
    }

    /**
     * Counts how many consecutive 'X' cells exist in a given direction.
     */
    private static int countConsecutiveX(char[][] grid, int r, int c, int dr, int dc) {
        int count = 0;
        int currR = r + dr;
        int currC = c + dc;

        while (isInBounds(grid, currR, currC) && grid[currR][currC] == FILLED_CELL) {
            count++;
            currR += dr;
            currC += dc;
        }
        return count;
    }

    /**
     * Checks if the given coordinates are within the grid boundaries.
     */
    private static boolean isInBounds(char[][] grid, int r, int c) {
        return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
    }
}

import java.util.Scanner;

/**
 * A class to evaluate a 10x10 Gomoku-style grid for a winning sequence.
 * A winning sequence is defined as 5 consecutive 'X's, or 4 'X's and 1 '.' (wildcard).
 */
public class GomokuGame {

    private static final int GRID_SIZE = 10;
    private static final int WIN_LENGTH = 5;
    private static final char PLAYER_PIECE = 'X';
    private static final char WILD_CARD = '.';

    private final char[][] grid;

    /**
     * Initializes the game with a specific grid.
     * @param grid A 10x10 character array representing the game board.
     */
    public GomokuGame(char[][] grid) {
        this.grid = grid;
    }

    /**
     * Checks if there is any winning sequence in the grid.
     *
     * @return true if a winning sequence exists, false otherwise.
     */
    public boolean hasWinningSequence() {
        // Direction vectors representing: 
        // {row_delta, col_delta}
        // We only need 4 directions to cover all possible lines:
        // Horizontal, Vertical, Diagonal (Down-Right), and Diagonal (Down-Left).
        int[][] directions = {
            {0, 1},  // Horizontal
            {1, 0},  // Vertical
            {1, 1},  // Diagonal Down-Right
            {1, -1}  // Diagonal Down-Left
        };

        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                for (int[] dir : directions) {
                    if (isWinningSequenceAt(r, c, dir[0], dir[1])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a winning sequence starts at the given coordinates in a specific direction.
     * 
     * @param startRow Starting row index.
     * @param startCol Starting column index.
     * @param dr Row direction delta.
     * @param dc Column direction delta.
     * @return true if the sequence starting here meets the winning criteria.
     */
    private boolean isWinningSequenceAt(int startRow, int startCol, int dr, int dc) {
        int xCount = 0;
        int wildcardCount = 0;

        for (int i = 0; i < WIN_LENGTH; i++) {
            int currentRow = startRow + (i * dr);
            int currentCol = startCol + (i * dc);

            // Boundary check: ensure the sequence stays within the 10x10 grid
            if (!isWithinBounds(currentRow, currentCol)) {
                return false;
            }

            char cell = grid[currentRow][currentCol];
            if (cell == PLAYER_PIECE) {
                xCount++;
            } else if (cell == WILD_CARD) {
                wildcardCount++;
            } else {
                // If the cell is neither 'X' nor '.', this sequence cannot be a win
                return false;
            }
        }

        // Win condition: Exactly 5 'X's OR exactly 4 'X's and 1 wildcard
        return xCount == WIN_LENGTH || (xCount == WIN_LENGTH - 1 && wildcardCount == 1);
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
    }

    /**
     * Entry point for the program. Handles input and outputs the result.
     */
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] inputGrid = new char[GRID_SIZE][GRID_SIZE];

        try {
            // Load the grid from standard input
            for (int i = 0; i < GRID_SIZE; i++) {
                if (scanner.hasNext()) {
                    String line = scanner.next();
                    for (int j = 0; j < GRID_SIZE; j++) {
                        inputGrid[i][j] = line.charAt(j);
                    }
                }
            }

            GomokuGame game = new GomokuGame(inputGrid);

            if (game.hasWinningSequence()) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        } catch (Exception e) {
            // Catch potential input errors and default to "NO"
            System.out.println("NO");
        } finally {
            scanner.close();
        }
    }
}

import java.util.Scanner;

/**
 * Represents the logic for a 5-in-a-row game where Alice (X) 
 * attempts to win in a single move.
 */
public class AliceGame {

    // Constants to replace "Magic Numbers"
    private static final int BOARD_SIZE = 10;
    private static final int WIN_LENGTH = 5;
    private static final char ALICE_CHAR = 'X';
    private static final char OPPONENT_CHAR = 'O';

    // Direction vectors: {row_delta, col_delta}
    // Covers: Horizontal, Vertical, Diagonal Down-Right, Diagonal Down-Left
    private static final int[][] DIRECTIONS = {
            {0, 1},  // Horizontal
            {1, 0},  // Vertical
            {1, 1},  // Diagonal Down-Right
            {1, -1}  // Diagonal Down-Left
    };

    private final char[][] playField;

    public AliceGame(char[][] playField) {
        this.playField = playField;
    }

    /**
     * Determines if Alice can complete a line of 5 'X's by placing one more.
     * 
     * @return true if a win is possible in one move.
     */
    public boolean canAliceWinInOneMove() {
        for (int r = 0; r < BOARD_SIZE; r++) {
            for (int c = 0; c < BOARD_SIZE; c++) {
                if (checkAllDirections(r, c)) {
                    return true;
                }
            }
        }
        return false;
    }

    private boolean checkAllDirections(int row, int col) {
        for (int[] direction : DIRECTIONS) {
            if (isWinningWindowPossible(row, col, direction[0], direction[1])) {
                return true;
            }
        }
        return false;
    }

    /**
     * Checks if a specific window of length WIN_LENGTH starting at (row, col) 
     * in a given direction contains exactly 4 Alice pieces and 1 empty space.
     */
    private boolean isWinningWindowPossible(int startRow, int startCol, int rowDelta, int colDelta) {
        int aliceCount = 0;
        int emptyCount = 0;

        for (int i = 0; i < WIN_LENGTH; i++) {
            int currRow = startRow + (i * rowDelta);
            int currCol = startCol + (i * colDelta);

            if (isOutOfBounds(currRow, currCol)) {
                return false;
            }

            char cell = playField[currRow][currCol];

            if (cell == ALICE_CHAR) {
                aliceCount++;
            } else if (cell != OPPONENT_CHAR) {
                // Any character that isn't 'X' or 'O' is considered an empty spot
                emptyCount++;
            } else {
                // If the opponent's piece is in this window, Alice cannot win here
                return false;
            }
        }

        // Alice wins in one move if the window has 4 of her pieces and 1 gap
        return aliceCount == 4 && emptyCount == 1;
    }

    private boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= BOARD_SIZE || c < 0 || c >= BOARD_SIZE;
    }

    public static void main(String[] args) {
        char[][] board = readBoardFromInput(10);
        AliceGame game = new AliceGame(board);

        // Output the final result
        System.out.println(game.canAliceWinInOneMove() ? "YES" : "NO");
    }

    /**
     * Handles the input logic separately from the game logic.
     */
    private static char[][] readBoardFromInput(int size) {
        char[][] board = new char[size][];
        try (Scanner scanner = new Scanner(System.in)) {
            for (int i = 0; i < size; i++) {
                if (scanner.hasNextLine()) {
                    board[i] = scanner.nextLine().toCharArray();
                }
            }
        }
        return board;
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to detect if a 10x10 grid contains a line of 5 characters 
 * consisting of exactly four 'X's and one '.' in any direction (H, V, or Diagonal).
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            // The problem specifies a 10x10 grid
            final int GRID_SIZE = 10;
            String[] grid = reader.readStrings(GRID_SIZE);

            PatternMatcher matcher = new PatternMatcher(grid);
            if (matcher.hasValidPattern()) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        } catch (Exception e) {
            // In a production environment, use a proper logging framework
            e.printStackTrace();
        } finally {
            out.close();
        }
    }

    /**
     * Encapsulates the logic for searching patterns within the grid.
     */
    static class PatternMatcher {
        private static final int LINE_LENGTH = 5;
        private static final int REQUIRED_X_COUNT = 4;
        private static final int REQUIRED_DOT_COUNT = 1;
        private static final int GRID_SIZE = 10;

        private final String[] grid;

        public PatternMatcher(String[] grid) {
            this.grid = grid;
        }

        /**
         * Iterates through every cell and direction to find a valid sequence.
         * @return true if a valid pattern is found, false otherwise.
         */
        public boolean hasValidPattern() {
            for (int r = 0; r < GRID_SIZE; r++) {
                for (int c = 0; c < GRID_SIZE; c++) {
                    for (Direction dir : Direction.values()) {
                        if (isValidSequence(r, c, dir)) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        /**
         * Checks if a sequence starting at (startR, startC) in the given direction
         * meets the requirement of 4 'X's and 1 '.'.
         */
        private boolean isValidSequence(int startR, int startC, Direction dir) {
            int xCount = 0;
            int dotCount = 0;

            for (int k = 0; k < LINE_LENGTH; k++) {
                int currR = startR + (k * dir.dr);
                int currC = startC + (k * dir.dc);

                // Check boundaries
                if (isOutOfBounds(currR, currC)) {
                    return false;
                }

                char cell = grid[currR].charAt(currC);
                if (cell == 'X') {
                    xCount++;
                } else if (cell == '.') {
                    dotCount++;
                }
            }

            return xCount == REQUIRED_X_COUNT && dotCount == REQUIRED_DOT_COUNT;
        }

        private boolean isOutOfBounds(int r, int c) {
            return r < 0 || r >= GRID_SIZE || c < 0 || c >= GRID_SIZE;
        }
    }

    /**
     * Represents possible movement directions in the grid.
     */
    enum Direction {
        HORIZONTAL(0, 1),
        VERTICAL(1, 0),
        DIAGONAL_DOWN_RIGHT(1, 1),
        DIAGONAL_DOWN_LEFT(1, -1);

        final int dr; // delta row
        final int dc; // delta column

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }
    }

    /**
     * Optimized reader for handling input more efficiently.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            this.reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public String[] readStrings(int count) {
            String[] strings = new String[count];
            for (int i = 0; i < count; i++) {
                strings[i] = next();
            }
            return strings;
        }
    }
}

import java.util.Scanner;

/**
 * A solver for a "Five in a Row" game on a 10x10 grid.
 * The program determines if placing a single 'X' in an empty '.' spot 
 * can result in five 'X's in a row, column, or diagonal.
 */
public class FiveInARowGame {

    private static final int GRID_SIZE = 10;
    private static final int WIN_SEQUENCE = 5;

    // Direction vectors for: Horizontal, Vertical, Diagonal (Down-Right), Diagonal (Down-Left)
    private static final int[][] DIRECTIONS = {
        {0, 1},  // Horizontal
        {1, 0},  // Vertical
        {1, 1},  // Diagonal Down-Right
        {1, -1}  // Diagonal Down-Left
    };

    private final char[][] grid;

    public FiveInARowGame(char[][] grid) {
        this.grid = grid;
    }

    /**
     * Iterates through every empty cell and checks if placing an 'X' creates a win.
     * 
     * @return true if a win is possible in one move, false otherwise.
     */
    public boolean canWinInOneMove() {
        for (int row = 0; row < GRID_SIZE; row++) {
            for (int col = 0; col < GRID_SIZE; col++) {
                if (grid[row][col] == '.') {
                    // Try placing an 'X'
                    grid[row][col] = 'X';

                    if (checkWin()) {
                        // Clean up before returning
                        grid[row][col] = '.'; 
                        return true;
                    }

                    // Backtrack: reset the cell to '.'
                    grid[row][col] = '.';
                }
            }
        }
        return false;
    }

    /**
     * Scans the entire grid to see if any five 'X's form a sequence.
     * 
     * @return true if a win sequence exists.
     */
    private boolean checkWin() {
        for (int row = 0; row < GRID_SIZE; row++) {
            for (int col = 0; col < GRID_SIZE; col++) {
                if (grid[row][col] == 'X') {
                    if (hasSequenceInAnyDirection(row, col)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a sequence of length WIN_SEQUENCE starts at (row, col) 
     * in any of the predefined directions.
     */
    private boolean hasSequenceInAnyDirection(int row, int col) {
        for (int[] direction : DIRECTIONS) {
            if (isSequencePresent(row, col, direction[0], direction[1])) {
                return true;
            }
        }
        return false;
    }

    /**
     * Checks if a winning sequence exists starting from a specific cell in a specific direction.
     */
    private boolean isSequencePresent(int startRow, int startCol, int rowDelta, int colDelta) {
        for (int i = 0; i < WIN_SEQUENCE; i++) {
            int currentRow = startRow + (i * rowDelta);
            int currentCol = startCol + (i * colDelta);

            if (isOutOfBounds(currentRow, currentCol) || grid[currentRow][currentCol] != 'X') {
                return false;
            }
        }
        return true;
    }

    private boolean isOutOfBounds(int row, int col) {
        return row < 0 || row >= GRID_SIZE || col < 0 || col >= GRID_SIZE;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] inputGrid = new char[GRID_SIZE][GRID_SIZE];

        try {
            // Reading the 10x10 grid
            // This approach works whether the input is one string per line or character-separated
            for (int i = 0; i < GRID_SIZE; i++) {
                for (int j = 0; j < GRID_SIZE; j++) {
                    String token = scanner.next();
                    inputGrid[i][j] = token.charAt(0);
                }
            }

            FiveInARowGame game = new FiveInARowGame(inputGrid);

            if (game.canWinInOneMove()) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }

        } catch (Exception e) {
            // In a real production environment, use a logging framework
            System.err.println("Error reading input: " + e.getMessage());
        } finally {
            scanner.close();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to determine if a single move (placing an 'X' in a '.')
 * can complete a line of 5 consecutive 'X's in a 10x10 grid.
 */
public class Main {

    private static final int GRID_SIZE = 10;
    private static final int REQUIRED_X_COUNT = 4; // 4 'X's + the new 'X' makes 5

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        GridSolver solver = new GridSolver(reader);
        solver.solve(writer);

        writer.close();
    }

    static class GridSolver {
        private final FastReader reader;
        private final char[][] grid = new char[GRID_SIZE][GRID_SIZE];

        // Direction vectors representing: Horizontal, Vertical, Diagonal (\), Diagonal (/)
        private static final int[][] DIRECTIONS = {
            {0, 1},  // Horizontal
            {1, 0},  // Vertical
            {1, 1},  // Diagonal \
            {1, -1}  // Diagonal /
        };

        public GridSolver(FastReader reader) {
            this.reader = reader;
        }

        public void solve(PrintWriter out) {
            loadGrid();

            if (canCompleteFiveInARow()) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        }

        private void loadGrid() {
            for (int i = 0; i < GRID_SIZE; i++) {
                String row = reader.next();
                for (int j = 0; j < GRID_SIZE; j++) {
                    grid[i][j] = row.charAt(j);
                }
            }
        }

        private boolean canCompleteFiveInARow() {
            for (int r = 0; r < GRID_SIZE; r++) {
                for (int c = 0; c < GRID_SIZE; c++) {
                    // We only care about empty cells ('.')
                    if (grid[r][c] == '.') {
                        if (checkAllDirections(r, c)) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        private boolean checkAllDirections(int row, int col) {
            for (int[] dir : DIRECTIONS) {
                int dr = dir[0];
                int dc = dir[1];

                // Count 'X's in the positive direction
                int countForward = countConsecutive(row, col, dr, dc);
                // Count 'X's in the opposite direction
                int countBackward = countConsecutive(row, col, -dr, -dc);

                if (countForward + countBackward >= REQUIRED_X_COUNT) {
                    return true;
                }
            }
            return false;
        }

        /**
         * Counts how many 'X's are in a specific direction starting from (startRow, startCol).
         * Does not include the cell at (startRow, startCol) itself.
         */
        private int countConsecutive(int startRow, int startCol, int dr, int dc) {
            int count = 0;
            int r = startRow + dr;
            int c = startCol + dc;

            while (isWithinBounds(r, c) && grid[r][c] == 'X') {
                count++;
                r += dr;
                c += dc;
            }
            return count;
        }

        private boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
        }
    }

    /**
     * Utility class for fast I/O operations.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

/**
 * A program to determine if a player has achieved a "five-in-a-row" 
 * sequence on a 10x10 grid, allowing for minimal empty spaces.
 */
public class FiveInARow {

    private static final int GRID_SIZE = 10;
    private static final int WIN_SEQUENCE_LENGTH = 5;

    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = 'O';
    private static final char EMPTY_SPOT = '.';

    // Directional vectors for 8 possible directions (horizontal, vertical, diagonal)
    private static final int[] ROW_OFFSETS = {-1, 1, 0, 1, 1, -1, 0, -1};
    private static final int[] COL_OFFSETS = {-1, 0, 1, 1, -1, 1, -1, 0};

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] grid = readGrid(scanner);
        scanner.close();

        if (hasWinningSequence(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Reads a 10x10 grid from the input stream.
     */
    private static char[][] readGrid(Scanner scanner) {
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            if (scanner.hasNext()) {
                String line = scanner.next();
                for (int j = 0; j < GRID_SIZE; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }
        }
        return grid;
    }

    /**
     * Iterates through the grid to find any winning sequence of X's.
     */
    private static boolean hasWinningSequence(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                // A sequence must start with an 'X'
                if (grid[r][c] == PLAYER_X) {
                    for (int dir = 0; dir < 8; dir++) {
                        if (isWinningLine(grid, r, c, ROW_OFFSETS[dir], COL_OFFSETS[dir])) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Validates if a winning sequence exists starting from (startR, startC) 
     * in a specific direction.
     * 
     * A valid sequence must:
     * 1. Consist of exactly 5 cells within bounds.
     * 2. Have 'X' in the first two positions.
     * 3. Contain no 'O' characters.
     * 4. Contain at most one '.' in the subsequent three positions.
     */
    private static boolean isWinningLine(char[][] grid, int startR, int startC, int dr, int dc) {
        // Check the second cell in the sequence
        int r2 = startR + dr;
        int c2 = startC + dc;
        if (!isWithinBounds(r2, c2) || grid[r2][c2] != PLAYER_X) {
            return false;
        }

        int dotCount = 0;

        // Check the remaining 3 cells (to complete a sequence of 5)
        for (int step = 2; step < WIN_SEQUENCE_LENGTH; step++) {
            int nr = startR + (step * dr);
            int nc = startC + (step * dc);

            if (!isWithinBounds(nr, nc)) {
                return false;
            }

            char cell = grid[nr][nc];

            if (cell == PLAYER_O) {
                return false;
            }

            if (cell == EMPTY_SPOT) {
                dotCount++;
            }

            // If we encounter more than one empty spot in these three cells, it's invalid
            if (dotCount >= 2) {
                return false;
            }
        }

        return true;
    }

    private static boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
    }
}

import java.io.PrintWriter;
import java.util.Scanner;

/**
 * Main entry point for the pattern detection program.
 */
public class Main {
    private static final int GRID_SIZE = 10;

    public static void main(String[] args) {
        // Using try-with-resources to ensure streams are closed automatically
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter writer = new PrintWriter(System.out)) {

            GridSolver solver = new GridSolver(GRID_SIZE);
            solver.readBoard(scanner);

            if (solver.canFormPatternByPlacingOneX()) {
                writer.print("YES");
            } else {
                writer.print("NO");
            }
            writer.flush();
        } catch (Exception e) {
            System.err.println("An error occurred during execution: " + e.getMessage());
        }
    }

    /**
     * Handles the logic for processing the grid and detecting specific patterns.
     */
    static class GridSolver {
        // The number of additional 'X' cells required in a direction to complete a pattern
        private static final int PATTERN_STEPS = 4;

        // Directional vectors for the 8 possible neighbors (N, NE, E, SE, S, SW, W, NW)
        private static final int[] DR = {-1, -1, -1, 0, 0, 1, 1, 1};
        private static final int[] DC = {-1, 0, 1, -1, 1, -1, 0, 1};

        private final int size;
        private final char[][] board;

        public GridSolver(int size) {
            this.size = size;
            this.board = new char[size][size];
        }

        /**
         * Reads the character grid from the input source.
         */
        public void readBoard(Scanner scanner) {
            for (int i = 0; i < size; i++) {
                if (scanner.hasNext()) {
                    board[i] = scanner.next().toCharArray();
                }
            }
        }

        /**
         * Iterates through every empty cell ('.') and checks if changing it to 'X'
         * results in a valid pattern existing anywhere on the board.
         * 
         * @return true if a pattern is formed, false otherwise.
         */
        public boolean canFormPatternByPlacingOneX() {
            for (int r = 0; r < size; r++) {
                for (int c = 0; c < size; c++) {
                    if (board[r][c] == '.') {
                        // Try placing an 'X'
                        board[r][c] = 'X';

                        if (containsAnyPattern()) {
                            board[r][c] = '.'; // Restore state
                            return true;
                        }

                        // Backtrack: restore the cell to '.'
                        board[r][c] = '.';
                    }
                }
            }
            return false;
        }

        /**
         * Scans the entire board to see if any 'X' is the start of a pattern.
         */
        private boolean containsAnyPattern() {
            for (int r = 0; r < size; r++) {
                for (int c = 0; c < size; c++) {
                    if (board[r][c] == 'X') {
                        if (isStartOfPattern(r, c)) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        /**
         * Checks if the 'X' at (row, col) starts a pattern in any of the 8 directions.
         */
        private boolean isStartOfPattern(int row, int col) {
            for (int i = 0; i < 8; i++) {
                if (checkDirection(row, col, DR[i], DC[i])) {
                    return true;
                }
            }
            return false;
        }

        /**
         * Checks if a sequence of 'X's extends from (r, c) in the given direction.
         */
        private boolean checkDirection(int r, int c, int dr, int dc) {
            for (int step = 1; step <= PATTERN_STEPS; step++) {
                int nr = r + (dr * step);
                int nc = c + (dc * step);

                if (isOutOfBounds(nr, nc) || board[nr][nc] != 'X') {
                    return false;
                }
            }
            return true;
        }

        private boolean isOutOfBounds(int r, int c) {
            return r < 0 || r >= size || c < 0 || c >= size;
        }
    }
}

import java.util.Scanner;

/**
 * A program that detects if a specific pattern (5 consecutive 'X's) 
 * exists in a 2D grid.
 */
public class Main {

    // Configuration constants
    private static final int GRID_SIZE = 20;
    private static final int DATA_START_INDEX = 5;
    private static final int DATA_SIZE = 10;
    private static final int WIN_LENGTH = 5;
    private static final char TARGET_CHAR = 'X';
    private static final char FILL_CHAR = 'O';

    public static void main(String[] args) {
        Main application = new Main();
        application.run();
    }

    /**
     * Orchestrates the execution flow: initialization, input, processing, and output.
     */
    public void run() {
        char[][] grid = initializeGrid();
        fillGridWithInput(grid);

        if (hasWinningPattern(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Creates a 20x20 grid initialized with the default filler character.
     */
    private char[][] initializeGrid() {
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            for (int j = 0; j < GRID_SIZE; j++) {
                grid[i][j] = FILL_CHAR;
            }
        }
        return grid;
    }

    /**
     * Reads 10 lines of input and places them into the designated 10x10 area of the grid.
     */
    private void fillGridWithInput(char[][] grid) {
        Scanner scanner = new Scanner(System.in);
        for (int i = DATA_START_INDEX; i < DATA_START_INDEX + DATA_SIZE; i++) {
            if (scanner.hasNext()) {
                String line = scanner.next();
                for (int j = 0; j < DATA_SIZE; j++) {
                    // Ensure we don't overflow if the input line is shorter than expected
                    if (j < line.length()) {
                        grid[i][DATA_START_INDEX + j] = line.charAt(j);
                    }
                }
            }
        }
        scanner.close();
    }

    /**
     * Scans the entire grid for the winning pattern in all directions.
     */
    private boolean hasWinningPattern(char[][] grid) {
        // Direction vectors: {row_delta, col_delta}
        // 1. Horizontal, 2. Vertical, 3. Diagonal (Down-Right), 4. Diagonal (Down-Left)
        int[][] directions = {
            {0, 1},
            {1, 0},
            {1, 1},
            {1, -1}
        };

        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                for (int[] dir : directions) {
                    if (checkDirection(grid, r, c, dir[0], dir[1])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a sequence of length WIN_LENGTH exists starting from (row, col) 
     * moving in direction (dRow, dCol).
     */
    private boolean checkDirection(char[][] grid, int row, int col, int dRow, int dCol) {
        for (int step = 0; step < WIN_LENGTH; step++) {
            int currentRow = row + (step * dRow);
            int currentCol = col + (step * dCol);

            if (isOutOfBounds(currentRow, currentCol) || grid[currentRow][currentCol] != TARGET_CHAR) {
                return false;
            }
        }
        return true;
    }

    /**
     * Boundary check for the grid.
     */
    private boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= GRID_SIZE || c < 0 || c >= GRID_SIZE;
    }
}

import java.util.Scanner;

/**
 * A utility to check if a 10x10 grid contains a specific winning pattern:
 * 4 'X' characters and 1 '.' character in a contiguous line of 5 cells.
 */
public class Solution {

    private static final int GRID_SIZE = 10;
    private static final int SEQUENCE_LENGTH = 5;
    private static final int REQUIRED_X_COUNT = 4;
    private static final int REQUIRED_DOT_COUNT = 1;

    // Direction vectors representing: Horizontal, Vertical, Diagonal (Down-Right), Diagonal (Down-Left)
    private static final int[][] DIRECTIONS = {
        {0, 1},  // Horizontal
        {1, 0},  // Vertical
        {1, 1},  // Diagonal Down-Right (\)
        {1, -1}  // Diagonal Down-Left (/)
    };

    public static void main(String[] args) {
        char[][] grid = readGrid();

        if (grid != null && hasWinningPattern(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Reads a 10x10 grid from standard input.
     * @return A 2D char array representing the grid.
     */
    private static char[][] readGrid() {
        Scanner scanner = new Scanner(System.in);
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];

        try {
            for (int i = 0; i < GRID_SIZE; i++) {
                if (scanner.hasNextLine()) {
                    String line = scanner.nextLine();
                    // Fill the row, handling potential input length issues
                    for (int j = 0; j < GRID_SIZE; j++) {
                        grid[i][j] = line.charAt(j);
                    }
                }
            }
            return grid;
        } catch (Exception e) {
            return null;
        } finally {
            scanner.close();
        }
    }

    /**
     * Iterates through every cell in the grid and checks all 4 directions for the pattern.
     * @param grid The 10x10 grid to analyze.
     * @return true if the pattern is found, false otherwise.
     */
    private static boolean hasWinningPattern(char[][] grid) {
        for (int row = 0; row < GRID_SIZE; row++) {
            for (int col = 0; col < GRID_SIZE; col++) {
                for (int[] direction : DIRECTIONS) {
                    if (checkSequenceAt(grid, row, col, direction[0], direction[1])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a sequence of a specific length starting from (startRow, startCol)
     * in a given direction matches the required 'X' and '.' counts.
     */
    private static boolean checkSequenceAt(char[][] grid, int startRow, int startCol, int deltaRow, int deltaCol) {
        int countX = 0;
        int countDot = 0;

        for (int step = 0; step < SEQUENCE_LENGTH; step++) {
            int currentRow = startRow + (step * deltaRow);
            int currentCol = startCol + (step * deltaCol);

            // Boundary check
            if (isOutOfBounds(currentRow, currentCol)) {
                return false;
            }

            char cell = grid[currentRow][currentCol];
            if (cell == 'X') {
                countX++;
            } else if (cell == '.') {
                countDot++;
            }
        }

        return countX == REQUIRED_X_COUNT && countDot == REQUIRED_DOT_COUNT;
    }

    /**
     * Helper to check if coordinates are within the grid boundaries.
     */
    private static boolean isOutOfBounds(int row, int col) {
        return row < 0 || row >= GRID_SIZE || col < 0 || col >= GRID_SIZE;
    }
}

import java.util.Scanner;

/**
 * Solves the problem of finding a valid segment (a line of 5 characters) 
 * in a grid that contains at most one '.' character.
 */
public class CrossFinder {

    private static final int GRID_SIZE = 10;
    private static final int SEGMENT_LENGTH = 5;

    // Direction vectors for: Horizontal Right, Vertical Down, Diagonal Down-Right, Diagonal Down-Left
    private static final int[] DR = {0, 1, 1, 1};
    private static final int[] DC = {1, 0, 1, -1};

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];

        try {
            // Input reading
            for (int i = 0; i < GRID_SIZE; i++) {
                if (scanner.hasNext()) {
                    grid[i] = scanner.next().toCharArray();
                }
            }

            if (hasValidSegment(grid)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        } catch (Exception e) {
            System.err.println("Error reading input: " + e.getMessage());
        } finally {
            scanner.close();
        }
    }

    /**
     * Iterates through every cell in the grid and checks all four directions 
     * to see if a valid segment starts there.
     * 
     * @param grid The 2D character array.
     * @return true if a valid segment is found, false otherwise.
     */
    private static boolean hasValidSegment(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                for (int dir = 0; dir < 4; dir++) {
                    if (checkDirection(grid, r, c, DR[dir], DC[dir])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a segment of a specific length starting from (startR, startC) 
     * and moving in direction (dr, dc) is valid.
     * A segment is valid if it contains at most one '.' character.
     * 
     * @param grid The 2D character array.
     * @param startR Starting row index.
     * @param startC Starting column index.
     * @param dr Directional row increment.
     * @param dc Directional column increment.
     * @return true if the segment is within bounds and valid.
     */
    private static boolean checkDirection(char[][] grid, int startR, int startC, int dr, int dc) {
        int dotCount = 0;

        for (int i = 0; i < SEGMENT_LENGTH; i++) {
            int currR = startR + (i * dr);
            int currC = startC + (i * dc);

            if (isOutOfBounds(currR, currC)) {
                return false;
            }

            if (grid[currR][currC] == '.') {
                dotCount++;
                if (dotCount > 1) {
                    return false;
                }
            }
        }

        return true;
    }

    /**
     * Helper to check if coordinates are within the grid boundaries.
     */
    private static boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= GRID_SIZE || c < 0 || c >= GRID_SIZE;
    }
}

import java.io.*;
import java.util.InputMismatchException;

/**
 * A program to determine if placing a single 'X' on a 10x10 grid
 * of '.' and 'X' can result in five consecutive 'X's in a row, column, or diagonal.
 */
public class Main {

    public static void main(String[] args) {
        try (FastReader in = new FastReader(System.in);
             FastWriter out = new FastWriter(System.out)) {

            GridGameSolver solver = new GridGameSolver();
            solver.solve(in, out);

        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * Logic engine for the grid game.
     */
    static class GridGameSolver {
        private static final int GRID_SIZE = 10;
        private static final int WIN_LENGTH = 5;

        // Directions to check: Horizontal, Vertical, Diagonal Down-Right, Diagonal Down-Left
        private static final int[][] DIRECTIONS = {
            {0, 1},  // Horizontal
            {1, 0},  // Vertical
            {1, 1},  // Diagonal Down-Right
            {1, -1}  // Diagonal Down-Left
        };

        public void solve(FastReader in, FastWriter out) throws IOException {
            char[][] grid = new char[GRID_SIZE][GRID_SIZE];

            for (int i = 0; i < GRID_SIZE; i++) {
                String line = in.nextString();
                if (line == null || line.length() < GRID_SIZE) {
                    throw new IOException("Invalid input grid format.");
                }
                grid[i] = line.toCharArray();
            }

            if (canCreateWin(grid)) {
                out.print("YES");
            } else {
                out.print("NO");
            }
        }

        /**
         * Iterates through the grid to find a '.' that, if replaced by 'X', completes a win.
         */
        private boolean canCreateWin(char[][] grid) {
            for (int r = 0; r < GRID_SIZE; r++) {
                for (int c = 0; c < GRID_SIZE; c++) {
                    if (grid[r][c] == '.') {
                        // Try placing an 'X'
                        grid[r][c] = 'X';
                        if (isWinningPosition(grid, r, c)) {
                            return true;
                        }
                        // Backtrack
                        grid[r][c] = '.';
                    }
                }
            }
            return false;
        }

        /**
         * Checks if the 'X' placed at (row, col) completes a line of WIN_LENGTH.
         */
        private boolean isWinningPosition(char[][] grid, int row, int col) {
            for (int[] dir : DIRECTIONS) {
                int dr = dir[0];
                int dc = dir[1];

                // Count consecutive 'X's in the positive direction and the negative direction
                int count = 1; // Start with the 'X' we just placed
                count += countConsecutive(grid, row, col, dr, dc);
                count += countConsecutive(grid, row, col, -dr, -dc);

                if (count >= WIN_LENGTH) {
                    return true;
                }
            }
            return false;
        }

        /**
         * Counts consecutive 'X's starting from (row, col) in a specific direction.
         */
        private int countConsecutive(char[][] grid, int row, int col, int dr, int dc) {
            int count = 0;
            int currR = row + dr;
            int currC = col + dc;

            while (isValid(currR, currC) && grid[currR][currC] == 'X') {
                count++;
                currR += dr;
                currC += dc;
            }
            return count;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
        }
    }

    /**
     * High-performance input reader.
     */
    static class FastReader implements AutoCloseable {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int pointer = 0;
        private int bytesRead = 0;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() throws IOException {
            if (pointer >= bytesRead) {
                pointer = 0;
                bytesRead = stream.read(buffer);
                if (bytesRead <= 0) return -1;
            }
            return buffer[pointer++] & 0xFF;
        }

        public String nextString() throws IOException {
            int b = readByte();
            while (b != -1 && isWhitespace(b)) {
                b = readByte();
            }
            if (b == -1) return null;

            StringBuilder sb = new StringBuilder();
            while (b != -1 && !isWhitespace(b)) {
                sb.append((char) b);
                b = readByte();
            }
            return sb.toString();
        }

        private boolean isWhitespace(int b) {
            return b == ' ' || b == '\n' || b == '\r' || b == '\t' || b == -1;
        }

        @Override
        public void close() throws IOException {
            stream.close();
        }
    }

    /**
     * High-performance output writer.
     */
    static class FastWriter implements AutoCloseable {
        private final PrintWriter writer;

        public FastWriter(OutputStream outputStream) {
            this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public void print(Object obj) {
            writer.print(obj);
        }

        @Override
        public void close() {
            writer.flush();
            writer.close();
        }
    }
}

