     * @param scanner The scanner to read from.
     * @param size The dimension of the square grid.
     * @return A 2D array representing the grid.
     */
    private static char[][] readGrid(Scanner scanner, int size) {
        char[][] grid = new char[size][size];
        for (int i = 0; i < size; i++) {
            if (scanner.hasNext()) {
                String line = scanner.next();
                for (int j = 0; j < size && j < line.length(); j++) {
                    grid[i][j] = line.charAt(j);
                }
            }
        }
        return grid;
    }

    /**
     * Scans the entire grid to see if any direction starting from any cell 
     * matches the target pattern.
     * 
     * @param grid The 2D character array.
     * @return true if the pattern is found, false otherwise.
     */
    private static boolean containsPattern(char[][] grid) {
        for (int r = 0; r < BOARD_SIZE; r++) {
            for (int c = 0; c < BOARD_SIZE; c++) {
                for (int[] direction : DIRECTIONS) {
                    if (isPatternAt(grid, r, c, direction[0], direction[1])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if the target pattern exists starting at a specific cell 
     * and moving in a specific direction.
     * 
     * @param grid The 2D character array.
     * @param startR Starting row index.
     * @param startC Starting column index.
     * @param dr Row direction delta.
     * @param dc Column direction delta.
     * @return true if the sequence matches the required counts.
     */
    private static boolean isPatternAt(char[][] grid, int startR, int startC, int dr, int dc) {
        int xCount = 0;
        int otherCount = 0;

        for (int k = 0; k < PATTERN_LENGTH; k++) {
            int r = startR + (k * dr);
            int c = startC + (k * dc);

            if (isOutOfBounds(r, c)) {
                return false;
            }

            char cell = grid[r][c];
            if (cell == TARGET_X) {
                xCount++;
            } else if (cell != TARGET_O) {
                // This counts characters that are neither 'X' nor 'O'
                otherCount++;
            }
        }

        return xCount == REQUIRED_X_COUNT && otherCount == REQUIRED_OTHER_COUNT;
    }

    /**
     * Validates if the given coordinates are within the grid boundaries.
     */
    private static boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= BOARD_SIZE || c < 0 || c >= BOARD_SIZE;
    }
}

import java.util.Scanner;

/**
 * A program to detect winning sequences in a 10x10 grid.
 * A winning sequence is defined as any 5 consecutive cells 
 * containing exactly four 'X's and one '.' (empty space).
 */
public class Game {

    private static final int GRID_SIZE = 10;
    private static final int WIN_LENGTH = 5;
    private static final char PLAYER_CHAR = 'X';
    private static final char EMPTY_CHAR = '.';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] grid = readGrid(scanner);
        scanner.close();

        if (hasWinningSequence(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Reads a 10x10 grid from the standard input.
     */
    private static char[][] readGrid(Scanner scanner) {
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            String rowInput = scanner.next();
            for (int j = 0; j < GRID_SIZE; j++) {
                grid[i][j] = rowInput.charAt(j);
            }
        }
        return grid;
    }

    /**
     * Scans the grid in all directions to find any winning sequence.
     */
    private static boolean hasWinningSequence(char[][] grid) {
        // Directions: {row_delta, col_delta}
        int[][] directions = {
            {0, 1},  // Horizontal
            {1, 0},  // Vertical
            {1, 1},  // Diagonal Down-Right
            {1, -1}  // Diagonal Down-Left
        };

        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                for (int[] dir : directions) {
                    if (isWinningPath(grid, r, c, dir[0], dir[1])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a sequence of length WIN_LENGTH starting at (r, c) 
     * in the given direction satisfies the winning condition.
     */
    private static boolean isWinningPath(char[][] grid, int r, int c, int dr, int dc) {
        // Calculate the end coordinates of the sequence
        int endR = r + (WIN_LENGTH - 1) * dr;
        int endC = c + (WIN_LENGTH - 1) * dc;

        // Boundary check: ensure the sequence is within the grid
        if (endR < 0 || endR >= GRID_SIZE || endC < 0 || endC >= GRID_SIZE) {
            return false;
        }

        char[] sequence = new char[WIN_LENGTH];
        for (int i = 0; i < WIN_LENGTH; i++) {
            sequence[i] = grid[r + i * dr][c + i * dc];
        }

        return isValidWinningPattern(sequence);
    }

    /**
     * Validates if the sequence consists of exactly 4 'X's and 1 '.'.
     */
    private static boolean isValidWinningPattern(char[] sequence) {
        int xCount = 0;
        int emptyCount = 0;

        for (char cell : sequence) {
            if (cell == PLAYER_CHAR) {
                xCount++;
            } else if (cell == EMPTY_CHAR) {
                emptyCount++;
            }
        }

        return xCount == 4 && emptyCount == 1;
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * A program to detect a specific pattern within a 10x10 grid.
 * The pattern is a sequence of 5 cells in a straight line (horizontal, vertical, or diagonal)
 * that contains no 'O' characters and at most one '.' character.
 */
public class Main {

    public static void main(String[] args) {
        try (InputReader in = new InputReader(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            PatternFinder solver = new PatternFinder(in);
            boolean found = solver.findPattern();

            out.println(found ? "YES" : "NO");
            out.flush();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    static class PatternFinder {
        private static final int GRID_SIZE = 10;
        private static final int PATTERN_LENGTH = 5;
        private static final int MAX_ALLOWED_DOTS = 1;
        private static final char EMPTY_CELL = '.';
        private static final char OBSTACLE = 'O';

        private final char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        private final InputReader inputReader;

        public PatternFinder(InputReader inputReader) {
            this.inputReader = inputReader;
        }

        /**
         * Reads the grid from input and attempts to find the pattern.
         * @return true if the pattern is found, false otherwise.
         */
        public boolean findPattern() {
            readGrid();
            return searchGrid();
        }

        private void readGrid() {
            for (int i = 0; i < GRID_SIZE; i++) {
                String row = inputReader.next();
                for (int j = 0; j < GRID_SIZE; j++) {
                    grid[i][j] = row.charAt(j);
                }
            }
        }

        private boolean searchGrid() {
            for (int x = 0; x < GRID_SIZE; x++) {
                for (int y = 0; y < GRID_SIZE; y++) {
                    if (checkAllDirectionsFrom(x, y)) {
                        return true;
                    }
                }
            }
            return false;
        }

        private boolean checkAllDirectionsFrom(int startX, int startY) {
            // Check all 8 directions around the current cell
            for (int dirX = -1; dirX <= 1; dirX++) {
                for (int dirY = -1; dirY <= 1; dirY++) {
                    if (dirX == 0 && dirY == 0) {
                        continue;
                    }
                    if (isValidPatternInDirection(startX, startY, dirX, dirY)) {
                        return true;
                    }
                }
            }
            return false;
        }

        private boolean isValidPatternInDirection(int startX, int startY, int dirX, int dirY) {
            int dotsFound = 0;

            for (int step = 0; step < PATTERN_LENGTH; step++) {
                int currX = startX + (step * dirX);
                int currY = startY + (step * dirY);

                if (isOutOfBounds(currX, currY)) {
                    return false;
                }

                char cell = grid[currX][currY];

                if (cell == OBSTACLE) {
                    return false;
                }

                if (cell == EMPTY_CELL) {
                    dotsFound++;
                }

                if (dotsFound > MAX_ALLOWED_DOTS) {
                    return false;
                }
            }

            return true;
        }

        private boolean isOutOfBounds(int x, int y) {
            return x < 0 || x >= GRID_SIZE || y < 0 || y >= GRID_SIZE;
        }
    }

    /**
     * Fast I/O reader for efficient character processing.
     */
    static class InputReader implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        @Override
        public void close() throws IOException {
            reader.close();
        }
    }
}

import java.util.Scanner;

/**
 * A program to determine if a single 'X' can be placed in an empty cell ('.')
 * to create a line of five consecutive 'X's in a 10x10 grid.
 */
public class FiveInARowGame {

    private static final int GRID_SIZE = 10;
    private static final int WINNING_COUNT = 5;
    private static final char X_MARK = 'X';
    private static final char EMPTY_CELL = '.';

    // Directions defined as {row_delta, col_delta}
    // 1. Horizontal, 2. Vertical, 3. Diagonal Down-Right, 4. Diagonal Down-Left
    private static final int[][] DIRECTIONS = {
            {0, 1},
            {1, 0},
            {1, 1},
            {1, -1}
    };

    private final char[][] grid = new char[GRID_SIZE][GRID_SIZE];

    public static void main(String[] args) {
        FiveInARowGame game = new FiveInARowGame();
        game.execute();
    }

    /**
     * Main execution flow of the program.
     */
    public void execute() {
        Scanner scanner = new Scanner(System.in);

        if (loadGrid(scanner)) {
            if (canWinByPlacingX()) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }

        scanner.close();
    }

    /**
     * Reads the 10x10 grid from the scanner.
     * 
     * @param scanner The input scanner.
     * @return true if the grid was loaded successfully, false otherwise.
     */
    private boolean loadGrid(Scanner scanner) {
        for (int i = 0; i < GRID_SIZE; i++) {
            if (scanner.hasNext()) {
                String rowString = scanner.next();
                if (rowString.length() < GRID_SIZE) {
                    return false;
                }
                for (int j = 0; j < GRID_SIZE; j++) {
                    grid[i][j] = rowString.charAt(j);
                }
            } else {
                return false;
            }
        }
        return true;
    }

    /**
     * Iterates through the grid to find an empty cell that would complete a win.
     * 
     * @return true if a winning move exists.
     */
    private boolean canWinByPlacingX() {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                if (grid[r][c] == EMPTY_CELL) {
                    if (checkWinAt(r, c)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if placing an 'X' at the specified coordinates completes 
     * a line of 5 'X's in any direction.
     * 
     * @param row The row index.
     * @param col The column index.
     * @return true if a win is achieved.
     */
    private boolean checkWinAt(int row, int col) {
        for (int[] direction : DIRECTIONS) {
            int dr = direction[0];
            int dc = direction[1];

            // Start with 1 (the 'X' we are placing at the current cell)
            // and add consecutive 'X's found in both directions of the current axis.
            int count = 1 
                    + countConsecutive(row, col, dr, dc) 
                    + countConsecutive(row, col, -dr, -dc);

            if (count >= WINNING_COUNT) {
                return true;
            }
        }
        return false;
    }

    /**
     * Counts how many consecutive 'X' marks exist in a specific direction.
     * 
     * @param row Starting row.
     * @param col Starting column.
     * @param dr Row delta for direction.
     * @param dc Column delta for direction.
     * @return The number of consecutive 'X' marks found.
     */
    private int countConsecutive(int row, int col, int dr, int dc) {
        int count = 0;
        int currentRow = row + dr;
        int currentCol = col + dc;

        while (isWithinBounds(currentRow, currentCol) && grid[currentRow][currentCol] == X_MARK) {
            count++;
            currentRow += dr;
            currentCol += dc;
        }
        return count;
    }

    /**
     * Validates if the coordinates are within the grid boundaries.
     * 
     * @param r Row index.
     * @param c Column index.
     * @return true if valid.
     */
    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
    }
}

import java.util.Scanner;

/**
 * A utility to detect if a specific character sequence exists in a 10x10 grid.
 * The winning sequence is defined as exactly one '.' and four 'X' characters 
 * in a straight line (horizontal, vertical, or diagonal).
 */
public class SequenceChecker {

    // Configuration constants
    private static final int GRID_SIZE = 10;
    private static final int WIN_LENGTH = 5;
    private static final char DOT = '.';
    private static final char X_CHAR = 'X';

    // Direction vectors for searching: {rowDelta, colDelta}
    // 1. Horizontal (0, 1)
    // 2. Vertical (1, 0)
    // 3. Diagonal Down-Right (1, 1)
    // 4. Diagonal Down-Left (1, -1)
    private static final int[][] DIRECTIONS = {
        {0, 1},
        {1, 0},
        {1, 1},
        {1, -1}
    };

    public static void main(String[] args) {
        char[][] grid = readGridFromConsole();

        if (grid == null) {
            return;
        }

        if (hasWinningSequence(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Reads the 10x10 grid from standard input.
     * 
     * @return A 2D character array representing the grid, or null if input fails.
     */
    private static char[][] readGridFromConsole() {
        Scanner scanner = new Scanner(System.in);
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];

        try {
            for (int i = 0; i < GRID_SIZE; i++) {
                if (!scanner.hasNext()) break;
                String line = scanner.next();
                for (int j = 0; j < GRID_SIZE; j++) {
                    // Handle cases where input line might be shorter than GRID_SIZE
                    grid[i][j] = (j < line.length()) ? line.charAt(j) : ' ';
                }
            }
        } catch (Exception e) {
            System.err.println("Error reading input: " + e.getMessage());
            return null;
        } finally {
            scanner.close();
        }
        return grid;
    }

    /**
     * Iterates through every cell in the grid and checks all possible directions
     * for a winning sequence.
     * 
     * @param grid The 2D grid to analyze.
     * @return true if a winning sequence is found.
     */
    private static boolean hasWinningSequence(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                for (int[] direction : DIRECTIONS) {
                    if (checkSequenceAt(grid, r, c, direction[0], direction[1])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a valid winning sequence starts at (startRow, startCol) 
     * and extends in the given direction.
     * 
     * @param grid The 2D grid.
     * @param startRow The starting row index.
     * @param startCol The starting column index.
     * @param dr The row direction delta.
     * @param dc The column direction delta.
     * @return true if the sequence matches the winning criteria.
     */
    private static boolean checkSequenceAt(char[][] grid, int startRow, int startCol, int dr, int dc) {
        int dotCount = 0;
        int xCount = 0;

        for (int i = 0; i < WIN_LENGTH; i++) {
            int currentRow = startRow + (i * dr);
            int currentCol = startCol + (i * dc);

            // If the sequence goes out of bounds, it's not a valid line of WIN_LENGTH
            if (!isWithinBounds(currentRow, currentCol)) {
                return false;
            }

            char cell = grid[currentRow][currentCol];
            if (cell == DOT) {
                dotCount++;
            } else if (cell == X_CHAR) {
                xCount++;
            }
        }

        // Winning condition: Exactly one '.' and four 'X's
        return dotCount == 1 && xCount == 4;
    }

    /**
     * Validates if the given coordinates are within the grid boundaries.
     */
    private static boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
    }
}

import java.util.Scanner;

/**
 * A solver for finding if a single move can complete a winning streak 
 * of 5 consecutive 'X' marks in a 10x10 grid.
 */
public class EduRound25B {

    private static final int GRID_SIZE = 10;
    private static final int WINNING_STREAK = 5;
    private static final char EMPTY = '.';
    private static final char PLAYER_MARK = 'X';

