class GomokuGame {
    private final char[][] grid;
    private final int size;

    // Directions represented as (row_delta, col_delta)
    // Horizontal, Vertical, Diagonal Down-Right, Diagonal Down-Left
    private static final int[][] DIRECTIONS = {
        {0, 1},
        {1, 0},
        {1, 1},
        {1, -1}
    };

    public GomokuGame(char[][] grid) {
        this.grid = grid;
        this.size = grid.length;
    }

    /**
     * Iterates through every empty cell to see if placing an 'X' 
     * results in a winning condition.
     */
    public boolean canWinInOneMove() {
        for (int r = 0; r < size; r++) {
            for (int c = 0; c < size; c++) {
                if (grid[r][c] == '.') {
                    if (isWinningMove(r, c)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Temporarily places a mark and checks all directions for a winning streak.
     */
    private boolean isWinningMove(int row, int col) {
        // Place mark temporarily
        grid[row][col] = 'X';

        boolean winFound = false;
        for (int[] direction : DIRECTIONS) {
            if (checkStreakInDirection(row, col, direction[0], direction[1])) {
                winFound = true;
                break;
            }
        }

        // Backtrack: restore the cell to empty
        grid[row][col] = '.';
        return winFound;
    }

    /**
     * Counts consecutive 'X' marks in both the positive and negative 
     * directions of a given vector.
     */
    private boolean checkStreakInDirection(int row, int col, int dRow, int dCol) {
        int count = 1; // Start with the mark we just placed
        count += countConsecutive(row, col, dRow, dCol);
        count += countConsecutive(row, col, -dRow, -dCol);

        return count >= 5;
    }

    /**
     * Counts how many consecutive 'X' marks exist starting from (row, col)
     * moving in the specified direction.
     */
    private int countConsecutive(int row, int col, int dRow, int dCol) {
        int count = 0;
        int currentRow = row + dRow;
        int currentCol = col + dCol;

        while (isInBounds(currentRow, currentCol) && grid[currentRow][currentCol] == 'X') {
            count++;
            currentRow += dRow;
            currentCol += dCol;
        }
        return count;
    }

    private boolean isInBounds(int r, int c) {
        return r >= 0 && r < size && c >= 0 && c < size;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * A program to detect if a winning sequence (4 'X's and 1 '.') exists 
 * in a 10x10 grid in any of the four primary directions.
 */
public class FiveInARow {

    private static final int GRID_SIZE = 10;
    private static final int SEQUENCE_LENGTH = 5;
    private static final char PLAYER_CHAR = 'X';
    private static final char EMPTY_CHAR = '.';
    private static final char SKIP_CHAR = '0';

    private static final int REQUIRED_X_COUNT = 4;
    private static final int REQUIRED_DOT_COUNT = 1;

    // Direction vectors: {row_delta, col_delta}
    // Represents: Horizontal, Vertical, Diagonal (Down-Right), Reverse Diagonal (Down-Left)
    private static final int[][] DIRECTIONS = {
            {0, 1},  // Horizontal
            {1, 0},  // Vertical
            {1, 1},  // Diagonal
            {1, -1}  // Reverse Diagonal
    };

    public static void main(String[] args) {
        char[][] grid = readGrid();

        if (grid == null) {
            return;
        }

        if (hasWinningSequence(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Reads the 10x10 grid from standard input.
     * @return A 2D char array representing the grid, or null if an error occurs.
     */
    private static char[][] readGrid() {
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            for (int i = 0; i < GRID_SIZE; i++) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                // Convert line to char array, handling potential length mismatches
                char[] row = line.toCharArray();
                for (int j = 0; j < GRID_SIZE; j++) {
                    grid[i][j] = (j < row.length) ? row[j] : ' ';
                }
            }
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
            return null;
        }
        return grid;
    }

    /**
     * Scans the grid to find if any cell starts a winning sequence.
     * @param grid The 2D character grid.
     * @return true if a sequence is found, false otherwise.
     */
    private static boolean hasWinningSequence(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                // According to original logic, skip cells containing '0'
                if (grid[r][c] != SKIP_CHAR) {
                    if (checkAllDirections(grid, r, c)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks all four possible directions from a specific starting cell.
     */
    private static boolean checkAllDirections(char[][] grid, int row, int col) {
        for (int[] dir : DIRECTIONS) {
            if (isWinningSequenceInDirection(grid, row, col, dir[0], dir[1])) {
                return true;
            }
        }
        return false;
    }

    /**
     * Traverses in a specific direction to count 'X's and '.'s.
     * 
     * @param grid The 2D character grid.
     * @param startRow Starting row index.
     * @param startCol Starting column index.
     * @param dr Row direction delta.
     * @param dc Column direction delta.
     * @return true if the sequence matches the required counts.
     */
    private static boolean isWinningSequenceInDirection(char[][] grid, int startRow, int startCol, int dr, int dc) {
        int xCount = 0;
        int dotCount = 0;

        for (int step = 0; step < SEQUENCE_LENGTH; step++) {
            int currR = startRow + (step * dr);
            int currC = startCol + (step * dc);

            // Boundary Check
            if (isOutOfBounds(currR, currC)) {
                return false;
            }

            char cell = grid[currR][currC];
            if (cell == PLAYER_CHAR) {
                xCount++;
            } else if (cell == EMPTY_CHAR) {
                dotCount++;
            }
        }

        return xCount == REQUIRED_X_COUNT && dotCount == REQUIRED_DOT_COUNT;
    }

    /**
     * Checks if the given coordinates are within the grid boundaries.
     */
    private static boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= GRID_SIZE || c < 0 || c >= GRID_SIZE;
