/**
 * Represents the game board.
 */
class Board {
    private final char[][] grid;
    private final int size;

    public Board(char[][] grid) {
        this.grid = grid;
        this.size = grid.length;
    }

    public int getSize() {
        return size;
    }

    public char getCell(int row, int col) {
        if (isWithinBounds(row, col)) {
            return grid[row][col];
        }
        return '\0'; // Null character if out of bounds
    }

    public boolean isWithinBounds(int row, int col) {
        return row >= 0 && row < size && col >= 0 && col < size;
    }
}

/**
 * Logic for detecting winning patterns on a Board.
 */
class WinDetector {
    private final Board board;

    // Direction vectors for: Horizontal, Vertical, Diagonal (Down-Right), Diagonal (Down-Left)
    private static final int[][] DIRECTIONS = {
        {0, 1},  // Horizontal
        {1, 0},  // Vertical
        {1, 1},  // Diagonal Down-Right
        {1, -1}  // Diagonal Down-Left
    };

    public WinDetector(Board board) {
        this.board = board;
    }

    /**
     * Scans the board to find a sequence of a specific length of a specific character.
     */
    public boolean hasWinningSequence(int length, char target) {
        for (int r = 0; r < board.getSize(); r++) {
            for (int c = 0; c < board.getSize(); c++) {
                // Only start checking if the current cell matches the target
                if (board.getCell(r, c) == target) {
                    if (checkAllDirections(r, c, length, target)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    private boolean checkAllDirections(int startRow, int startCol, int length, char target) {
        for (int[] direction : DIRECTIONS) {
            if (countConsecutive(startRow, startCol, direction[0], direction[1], length, target) == length) {
                return true;
            }
        }
        return false;
    }

    private int countConsecutive(int row, int col, int rowDir, int colDir, int maxLen, char target) {
        int count = 0;
        for (int i = 0; i < maxLen; i++) {
            int nextRow = row + (i * rowDir);
            int nextCol = col + (i * colDir);

            if (board.isWithinBounds(nextRow, nextCol) && board.getCell(nextRow, nextCol) == target) {
                count++;
            } else {
                break;
            }
        }
        return count;
    }
}

