/**
 * A solver to determine if a 10x10 grid can form a sequence of 5 'X's 
 * in a row (horizontally, vertically, or diagonally) by changing exactly 
 * one '.' to an 'X'.
 */
public class GridPatternSolver {

    private static final int GRID_SIZE = 10;
    private static final int WIN_LENGTH = 5;
    private static final char TARGET_CHAR = 'X';
    private static final char EMPTY_CHAR = '.';

    // Directional vectors for: Horizontal, Vertical, Diagonal (Down-Right), Diagonal (Down-Left)
    private static final int[][] DIRECTIONS = {
            {0, 1},  // Horizontal
            {1, 0},  // Vertical
            {1, 1},  // Diagonal Down-Right
            {1, -1}  // Diagonal Down-Left
    };

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        char[][] grid = scanner.nextGrid(GRID_SIZE, GRID_SIZE);
        boolean result = solve(grid);

        out.println(result ? "YES" : "NO");
        out.close();
    }

    /**
     * Iterates through every empty cell, tries placing an 'X', 
     * and checks if the winning condition is met.
     */
    private static boolean solve(char[][] grid) {
        for (int i = 0; i < GRID_SIZE; i++) {
            for (int j = 0; j < GRID_SIZE; j++) {
                if (grid[i][j] == EMPTY_CHAR) {
                    grid[i][j] = TARGET_CHAR;
                    if (hasFiveInARow(grid)) {
                        return true;
                    }
                    // Backtrack
                    grid[i][j] = EMPTY_CHAR;
                }
            }
        }
        return false;
    }

    /**
     * Checks if there is any sequence of TARGET_CHAR of length WIN_LENGTH 
     * in any of the allowed directions.
     */
    private static boolean hasFiveInARow(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                if (grid[r][c] == TARGET_CHAR) {
                    for (int[] dir : DIRECTIONS) {
                        if (checkDirection(grid, r, c, dir[0], dir[1])) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a continuous line of WIN_LENGTH exists starting from (row, col) 
     * moving in direction (dr, dc).
     */
    private static boolean checkDirection(char[][] grid, int row, int col, int dr, int dc) {
        for (int step = 0; step < WIN_LENGTH; step++) {
            int nr = row + (dr * step);
            int nc = col + (dc * step);

            if (!isValid(nr, nc) || grid[nr][nc] != TARGET_CHAR) {
                return false;
            }
        }
        return true;
    }

    private static boolean isValid(int r, int c) {
        return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
    }

    /**
     * Utility class for fast I/O operations.
     */
    static class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public char[][] nextGrid(int rows, int cols) {
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = next().toCharArray();
            }
            return grid;
        }
    }
}

