class GridGame {
    private static final int GRID_SIZE = 10;
    private static final int WIN_THRESHOLD = 5;

    // Directions: Horizontal, Vertical, Diagonal Down-Right, Diagonal Down-Left
    private static final int[][] DIRECTIONS = {
        {0, 1}, 
        {1, 0}, 
        {1, 1}, 
        {1, -1}
    };

    /**
     * Reads the grid and determines if a win is possible.
     */
    public void solve(FastReader reader, PrintWriter writer) {
        char[][] grid = new char[GRID_SIZE][];
        for (int i = 0; i < GRID_SIZE; i++) {
            grid[i] = reader.nextCharArray(GRID_SIZE);
        }

        if (canAchieveWin(grid)) {
            writer.println("YES");
        } else {
            writer.println("NO");
        }
    }

    /**
     * Iterates through every empty cell to see if placing an 'X' creates a win.
     */
    private boolean canAchieveWin(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                if (grid[r][c] == '.') {
                    // Try placing an 'X'
                    grid[r][c] = 'X';

                    if (hasFiveInARow(grid)) {
                        // Backtrack before returning
                        grid[r][c] = '.';
                        return true;
                    }

                    // Backtrack if no win found
                    grid[r][c] = '.';
                }
            }
        }
        return false;
    }

    /**
     * Checks the entire grid for any sequence of 'X's meeting the win threshold.
     */
    private boolean hasFiveInARow(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                if (grid[r][c] == 'X') {
                    for (int[] dir : DIRECTIONS) {
                        if (countConsecutive(grid, r, c, dir[0], dir[1]) >= WIN_THRESHOLD) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Counts how many 'X's exist consecutively in a specific direction.
     */
    private int countConsecutive(char[][] grid, int row, int col, int dr, int dc) {
        int count = 0;
        int r = row;
        int c = col;

        while (isValid(r, c) && grid[r][c] == 'X') {
            count++;
            r += dr;
            c += dc;
            // Optimization: stop if we've already reached the threshold
            if (count >= WIN_THRESHOLD) break;
        }
        return count;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
    }
}

