                    grid[r][c] = 'X';

                    if (hasFiveConsecutiveX(grid)) {
                        // Backtrack before returning
                        grid[r][c] = '.';
                        return true;
                    }

                    // Backtrack
                    grid[r][c] = '.';
                }
            }
        }
        return false;
    }

    /**
     * Checks if the current grid contains at least one sequence of 5 consecutive 'X's.
     */
    private boolean hasFiveConsecutiveX(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                // Optimization: only start checking from an 'X'
                if (grid[r][c] == 'X') {
                    for (int dir = 0; dir < 4; dir++) {
                        if (checkDirection(grid, r, c, DX[dir], DY[dir])) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a sequence of length TARGET_SEQUENCE exists starting from (r, c) 
     * moving in the direction (dr, dc).
     */
    private boolean checkDirection(char[][] grid, int r, int c, int dr, int dc) {
        int consecutiveCount = 0;

        for (int step = 0; step < TARGET_SEQUENCE; step++) {
            int nextR = r + (dr * step);
            int nextC = c + (dc * step);

            if (isWithinBounds(nextR, nextC) && grid[nextR][nextC] == 'X') {
                consecutiveCount++;
            } else {
                break;
            }
        }

        return consecutiveCount == TARGET_SEQUENCE;
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
    }
}

