/**
 * A program to determine if placing a single 'X' on a 10x10 grid 
 * can create a line of five consecutive 'X's.
 */
public class FiveInARowSolver {

    private static final int GRID_SIZE = 10;
    private static final int WIN_LENGTH = 5;

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];

        try {
            for (int i = 0; i < GRID_SIZE; i++) {
                String row = reader.next();
                if (row == null) break;
                grid[i] = row.toCharArray();
            }

            GameLogic logic = new GameLogic(grid);
            if (logic.canWinWithOneMove()) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        } catch (Exception e) {
            System.err.println("Error processing input: " + e.getMessage());
        }
    }

    /**
     * Contains the core game logic for checking win conditions.
     */
    static class GameLogic {
        private final char[][] grid;

        public GameLogic(char[][] grid) {
            this.grid = grid;
        }

        /**
         * Iterates through every cell in the grid. If the cell is empty ('.'),
         * temporarily places an 'X' and checks if a win condition is met.
         */
        public boolean canWinWithOneMove() {
            for (int r = 0; r < GRID_SIZE; r++) {
                for (int c = 0; c < GRID_SIZE; c++) {
                    if (grid[r][c] == '.') {
                        grid[r][c] = 'X'; // Try placing X
                        if (hasWinningLine()) {
                            grid[r][c] = '.'; // Backtrack
                            return true;
                        }
                        grid[r][c] = '.'; // Backtrack
                    }
                }
            }
            return false;
        }

        /**
         * Checks if the current grid state contains 5 consecutive 'X's 
         * in any direction (horizontal, vertical, or diagonal).
         */
        private boolean hasWinningLine() {
            // Direction vectors: {row_delta, col_delta}
            // Covers: Horizontal, Vertical, Diagonal Down-Right, Diagonal Down-Left
            int[][] directions = {
                {0, 1},  // Horizontal
                {1, 0},  // Vertical
                {1, 1},  // Diagonal Down-Right
                {1, -1}  // Diagonal Down-Left
            };

            for (int r = 0; r < GRID_SIZE; r++) {
                for (int c = 0; c < GRID_SIZE; c++) {
                    if (grid[r][c] != 'X') continue;

                    for (int[] dir : directions) {
                        if (checkDirection(r, c, dir[0], dir[1])) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        private boolean checkDirection(int startR, int startC, int dr, int dc) {
            for (int i = 1; i < WIN_LENGTH; i++) {
                int nr = startR + (i * dr);
                int nc = startC + (i * dc);

                if (isOutOfBounds(nr, nc) || grid[nr][nc] != 'X') {
                    return false;
                }
            }
            return true;
        }

        private boolean isOutOfBounds(int r, int c) {
            return r < 0 || r >= GRID_SIZE || c < 0 || c >= GRID_SIZE;
        }
    }

    /**
     * Efficient utility class for reading input.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
