/**
 * A utility to check if a 10x10 grid contains a winning sequence 
 * of 5 characters consisting of exactly 4 'X's and 1 '.' (empty spot).
 */
public class GridWinChecker {

    private static final int GRID_SIZE = 10;
    private static final int SEQUENCE_LENGTH = 5;
    private static final char TARGET_X = 'X';
    private static final char TARGET_EMPTY = '.';

    // Direction vectors: {rowDelta, colDelta}
    // Covers: Vertical, Horizontal, Diagonal Down-Right, Diagonal Down-Left
    private static final int[][] DIRECTIONS = {
        {1, 0},  // Vertical
        {0, 1},  // Horizontal
        {1, 1},  // Diagonal Down-Right
        {1, -1}  // Diagonal Down-Left
    };

    public static void main(String[] args) {
        FastReader sc = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        char[][] grid = readGrid(sc, GRID_SIZE);

        if (hasWinningSequence(grid)) {
            out.println("YES");
        } else {
            out.println("NO");
        }

        out.flush();
        out.close();
    }

    /**
     * Reads the grid from the input stream.
     */
    private static char[][] readGrid(FastReader sc, int size) {
        char[][] grid = new char[size][size];
        for (int i = 0; i < size; i++) {
            String line = sc.next();
            for (int j = 0; j < size; j++) {
                grid[i][j] = line.charAt(j);
            }
        }
        return grid;
    }

    /**
     * Scans the grid to find if any direction contains a winning sequence.
     */
    private static boolean hasWinningSequence(char[][] grid) {
        for (int row = 0; row < GRID_SIZE; row++) {
            for (int col = 0; col < GRID_SIZE; col++) {
                for (int[] dir : DIRECTIONS) {
                    if (isWinningSequenceAt(grid, row, col, dir[0], dir[1])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a sequence starting at (startRow, startCol) in direction (dr, dc)
     * meets the winning criteria: exactly 4 'X's and 1 empty spot.
     */
    private static boolean isWinningSequenceAt(char[][] grid, int startRow, int startCol, int dr, int dc) {
        int xCount = 0;
        int emptyCount = 0;

        for (int step = 0; step < SEQUENCE_LENGTH; step++) {
            int currentRow = startRow + (step * dr);
            int currentCol = startCol + (step * dc);

            if (isOutOfBounds(currentRow, currentCol)) {
                return false;
            }

            char cell = grid[currentRow][currentCol];
            if (cell == TARGET_X) {
                xCount++;
            } else if (cell == TARGET_EMPTY) {
                emptyCount++;
            }
        }

        return xCount == 4 && emptyCount == 1;
    }

    private static boolean isOutOfBounds(int row, int col) {
        return row < 0 || row >= GRID_SIZE || col < 0 || col >= GRID_SIZE;
    }

    /**
     * Fast I/O reader for efficient input processing.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }
    }
}

