        /**
         * A win in one move is possible if there exists a 5-cell segment 
         * containing either 5 'X's or 4 'X's and 1 empty cell.
         */
        public boolean canWinInOneMove() {
            for (int r = 0; r < board.getSize(); r++) {
                for (int c = 0; c < board.getSize(); c++) {
                    for (Direction dir : Direction.values()) {
                        if (isWinningSegment(r, c, dir)) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        private boolean isWinningSegment(int startRow, int startCol, Direction dir) {
            int xCount = 0;
            int emptyCount = 0;

            for (int i = 0; i < 5; i++) {
                int currRow = startRow + (i * dir.getRowDelta());
                int currCol = startCol + (i * dir.getColDelta());

                if (!board.isWithinBounds(currRow, currCol)) {
                    return false;
                }

                char cell = board.getCell(currRow, currCol);
                if (cell == CROSS) {
                    xCount++;
                } else if (cell == EMPTY) {
                    emptyCount++;
                } else {
                    // If we hit an 'O', this segment cannot result in an 'X' win
                    return false;
                }
            }

            // Win condition: 5 in a row (already won) or 4 in a row with 1 gap
            return (xCount == 5) || (xCount == 4 && emptyCount == 1);
        }
    }
}

import java.util.Scanner;

/**
 * A program to detect if a specific pattern exists in a grid.
 * The pattern is a sequence of 5 cells where exactly one cell is '.' 
 * and no cells are 'O'.
 */
public class B425 {

    private static final int ROWS = 10;
    private static final int COLS = 6;
    private static final int SEQUENCE_LENGTH = 5;
    private static final char EMPTY_CELL = '.';
    private static final char OBSTACLE = 'O';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] grid = new char[ROWS][COLS];

        try {
            for (int i = 0; i < ROWS; i++) {
                String line = scanner.next();
                grid[i] = line.toCharArray();
            }

            GridSearcher searcher = new GridSearcher(grid);
            if (searcher.hasWinningSequence()) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        } catch (Exception e) {
            // In a real-world scenario, use a logger. 
            // For this refactor, we ensure the program fails gracefully.
            System.err.println("Error processing grid: " + e.getMessage());
        } finally {
            scanner.close();
        }
    }

    /**
     * Encapsulates the logic for searching the grid for specific patterns.
     */
    static class GridSearcher {
        private final char[][] grid;
        private final int rows;
        private final int cols;

        // Direction vectors for: Horizontal, Vertical, Diagonal Down-Right, Diagonal Up-Right
        private static final int[][] DIRECTIONS = {
            {0, 1},  // Horizontal
            {1, 0},  // Vertical
            {1, 1},  // Diagonal Down-Right
            {-1, 1}  // Diagonal Up-Right
        };

        public GridSearcher(char[][] grid) {
            this.grid = grid;
            this.rows = grid.length;
            this.cols = grid[0].length;
        }

        /**
         * Iterates through every cell and every direction to find a valid sequence.
         * @return true if a valid sequence is found.
         */
        public boolean hasWinningSequence() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    for (int[] dir : DIRECTIONS) {
                        if (isValidSequence(r, c, dir[0], dir[1])) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        /**
         * Checks if a sequence starting at (startRow, startCol) in a specific 
         * direction meets the criteria.
         */
        private boolean isValidSequence(int startRow, int startCol, int dRow, int dCol) {
            int dotCount = 0;

            for (int i = 0; i < SEQUENCE_LENGTH; i++) {
                int currR = startRow + (i * dRow);
                int currC = startCol + (i * dCol);

                if (isOutOfBounds(currR, currC)) {
                    return false;
                }

                char cell = grid[currR][currC];

                if (cell == OBSTACLE) {
                    return false;
                }
                if (cell == EMPTY_CELL) {
                    dotCount++;
                }
            }

            // A valid sequence must contain exactly one empty cell ('.')
            return dotCount == 1;
        }

        private boolean isOutOfBounds(int r, int c) {
            return r < 0 || r >= rows || c < 0 || c >= cols;
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A program that detects if a 10x10 grid contains a specific pattern:
 * A center empty cell ('.') with at least 4 consecutive 'X' cells 
 * extending in two opposite directions (forming a line of 5).
 */
public class Main {

    private static final int GRID_SIZE = 10;
    private static final char EMPTY_CELL = '.';
    private static final char OBSTACLE_CELL = 'X';
    private static final int REQUIRED_PATTERN_LENGTH = 5;

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            char[][] grid = readGrid(scanner, GRID_SIZE);
            GridAnalyzer analyzer = new GridAnalyzer(grid, GRID_SIZE);

            if (analyzer.containsPattern()) {
                writer.println("YES");
            } else {
                writer.println("NO");
            }
        } catch (Exception e) {
            // In a production environment, use a logger.
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    private static char[][] readGrid(FastScanner scanner, int size) {
        char[][] grid = new char[size][size];
        for (int i = 0; i < size; i++) {
            grid[i] = scanner.next().toCharArray();
        }
        return grid;
    }

    /**
     * Encapsulates the logic for analyzing the grid pattern.
     */
    static class GridAnalyzer {
        private final char[][] grid;
        private final int size;

        // Represents a pair of opposite directions (e.g., North and South)
        private static final int[][][] DIRECTION_PAIRS = {
            {{1, 0}, {-1, 0}},  // Vertical
            {{0, 1}, {0, -1}},  // Horizontal
            {{1, 1}, {-1, -1}}, // Diagonal Down-Right
            {{1, -1}, {-1, 1}}  // Diagonal Down-Left
        };

        public GridAnalyzer(char[][] grid, int size) {
            this.grid = grid;
            this.size = size;
        }

        /**
         * Iterates through the grid to find if any empty cell acts as the 
         * center of the required pattern.
         */
        public boolean containsPattern() {
            for (int r = 0; r < size; r++) {
                for (int c = 0; c < size; c++) {
                    if (grid[r][c] == EMPTY_CELL && isCenterOfPattern(r, c)) {
                        return true;
                    }
                }
            }
            return false;
        }

        private boolean isCenterOfPattern(int row, int col) {
            for (int[][] pair : DIRECTION_PAIRS) {
                int countDir1 = countConsecutiveObstacles(row, col, pair[0][0], pair[0][1]);
                int countDir2 = countConsecutiveObstacles(row, col, pair[1][0], pair[1][1]);

                // Total length = obstacles in dir1 + obstacles in dir2 + the center cell
                if (countDir1 + countDir2 + 1 >= REQUIRED_PATTERN_LENGTH) {
                    return true;
                }
            }
            return false;
        }

        private int countConsecutiveObstacles(int startRow, int startCol, int dr, int dc) {
            int count = 0;
            int currR = startRow + dr;
            int currC = startCol + dc;

            while (isWithinBounds(currR, currC) && grid[currR][currC] == OBSTACLE_CELL) {
                count++;
                currR += dr;
                currC += dc;
            }
            return count;
        }

        private boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < size && c >= 0 && c < size;
        }
    }

    /**
     * Utility class for fast I/O operations.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }
    }
}

import java.util.Scanner;

/**
 * A program to determine if there are five 'X's in a row on a 10x10 grid,
 * allowing for at most one '.' (dot) within the sequence.
 */
public class FiveInRow {

    private static final int GRID_SIZE = 10;
    private static final int WIN_LENGTH = 5;
    private static final int MAX_DOTS_ALLOWED = 1;

    // Direction vectors: {row_delta, col_delta}
    // Represents: Horizontal, Vertical, Diagonal Down-Right, Diagonal Down-Left
    private static final int[][] DIRECTIONS = {
        {0, 1},
        {1, 0},
        {1, 1},
        {1, -1}
    };

    public static void main(String[] args) {
        char[][] board = readBoard();

        if (hasWinningSequence(board)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Reads a 10x10 grid from standard input.
     * @return A 2D char array representing the grid.
     */
    private static char[][] readBoard() {
        Scanner sc = new Scanner(System.in);
        char[][] board = new char[GRID_SIZE][GRID_SIZE];

        for (int i = 0; i < GRID_SIZE; i++) {
            if (sc.hasNextLine()) {
                String line = sc.nextLine();
                // Ensure we handle potential input length mismatches gracefully
                for (int j = 0; j < GRID_SIZE; j++) {
                    board[i][j] = (j < line.length()) ? line.charAt(j) : '.';
                }
            }
        }
        return board;
    }

    /**
     * Iterates through every cell in the grid to find a winning sequence.
     * @param board The 2D grid.
     * @return true if a winning sequence is found.
     */
    private static boolean hasWinningSequence(char[][] board) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                // Check all 4 directions from the current cell
                for (int[] direction : DIRECTIONS) {
                    if (isWinAt(board, r, c, direction[0], direction[1])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a winning sequence of length WIN_LENGTH starts at (startR, startC)
     * and moves in the direction (dr, dc).
     * 
     * @param board The 2D grid.
     * @param startR Starting row index.
     * @param startC Starting column index.
     * @param dr Row direction delta.
     * @param dc Column direction delta.
     * @return true if the sequence contains at most one dot and the rest are 'X'.
     */
    private static boolean isWinAt(char[][] board, int startR, int startC, int dr, int dc) {
        int dotsInSequence = 0;
        int xCount = 0;

        for (int i = 0; i < WIN_LENGTH; i++) {
            int currR = startR + (i * dr);
            int currC = startC + (i * dc);

            // 1. Check bounds
            if (isOutOfBounds(currR, currC)) {
                return false;
            }

            // 2. Count dots and X's
            char cell = board[currR][currC];
            if (cell == '.') {
                dotsInSequence++;
            } else if (cell == 'X') {
                xCount++;
            }

            // 3. Optimization: If dots exceed limit, stop checking this direction
            if (dotsInSequence > MAX_DOTS_ALLOWED) {
                return false;
            }
        }

        // A win is valid if it meets the dot limit and has the required number of 'X's
        return dotsInSequence <= MAX_DOTS_ALLOWED && xCount >= (WIN_LENGTH - dotsInSequence);
    }

    private static boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= GRID_SIZE || c < 0 || c >= GRID_SIZE;
    }
}

