/**
 * Logic for solving the grid sequence problem.
 */
class GridSequenceSolver {
    private static final int GRID_SIZE = 10;
    private static final int TARGET_SEQUENCE_LENGTH = 5;
    private static final char EMPTY_CELL = '.';
    private static final char TARGET_CHAR = 'X';

    /**
     * Attempts to place one TARGET_CHAR in an EMPTY_CELL to create a sequence of length TARGET_SEQUENCE_LENGTH.
     */
    public void solve(FastReader in, FastWriter out) {
        char[][] grid = new char[GRID_SIZE][];

        for (int i = 0; i < GRID_SIZE; i++) {
            grid[i] = in.next().toCharArray();
        }

        if (canFormSequence(grid)) {
            out.printLine("YES");
        } else {
            out.printLine("NO");
        }
    }

    private boolean canFormSequence(char[][] grid) {
        for (int row = 0; row < GRID_SIZE; row++) {
            for (int col = 0; col < grid[row].length; col++) {
                // Try placing a target character in an empty cell
                if (grid[row][col] == EMPTY_CELL) {
                    grid[row][col] = TARGET_CHAR;
                    if (hasTargetSequence(grid)) {
                        return true;
                    }
                    // Backtrack
                    grid[row][col] = EMPTY_CELL;
                }
            }
        }
        return false;
    }

    private boolean hasTargetSequence(char[][] grid) {
        for (int row = 0; row < GRID_SIZE; row++) {
            for (int col = 0; col < grid[row].length; col++) {
                if (grid[row][col] == TARGET_CHAR) {
                    // Check all 8 directions from this cell
                    for (Direction dir : Direction.values()) {
                        if (countConsecutive(grid, row, col, dir) >= TARGET_SEQUENCE_LENGTH) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Iteratively counts how many consecutive TARGET_CHARs exist in a specific direction.
     */
    private int countConsecutive(char[][] grid, int startRow, int startCol, Direction dir) {
        int count = 0;
        int currentRow = startRow;
        int currentCol = startCol;

        while (isValidCell(grid, currentRow, currentCol) && grid[currentRow][currentCol] == TARGET_CHAR) {
            count++;
            currentRow += dir.dr;
            currentCol += dir.dc;
        }
        return count;
    }

    private boolean isValidCell(char[][] grid, int row, int col) {
        return row >= 0 && row < GRID_SIZE && col >= 0 && col < grid[0].length;
    }
}

/**
 * Represents the 8 possible movement directions in a 2D grid.
 */
enum Direction {
    N(1, 0), NE(1, 1), E(0, 1), SE(-1, 1), 
    S(-1, 0), SW(-1, -1), W(0, -1), NW(1, -1);

    final int dr;
    final int dc;

    Direction(int dr, int dc) {
        this.dr = dr;
        this.dc = dc;
    }
}

/**
 * High-performance reader for fast input processing.
 */
class FastReader {
    private BufferedReader reader;
    private StringTokenizer tokenizer;

    public FastReader(InputStream stream) {
        reader = new BufferedReader(new InputStreamReader(stream));
    }

    public String next() {
        while (tokenizer == null || !tokenizer.hasMoreElements()) {
            try {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                throw new RuntimeException("Error reading input", e);
            }
        }
        return tokenizer.nextToken();
    }
}

/**
 * High-performance writer for efficient output.
 */
class FastWriter {
    private final PrintWriter writer;

    public FastWriter(OutputStream outputStream) {
        this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
    }

    public void printLine(Object... objects) {
        for (int i = 0; i < objects.length; i++) {
            writer.print(objects[i]);
            if (i < objects.length - 1) {
                writer.print(" ");
            }
        }
        writer.println();
    }

    public void close() {
        writer.close();
    }
}

import java.util.Scanner;

/**
 * A program to determine if there are five consecutive identical characters
 * in a 10x10 grid, checking horizontally, vertically, and diagonally.
 */
public class FiveInARow {

    private static final int GRID_SIZE = 10;
    private static final int WINNING_LENGTH = 5;

    // Direction vectors representing the four directions to check:
    // {row_delta, col_delta}
    // 1. Horizontal (Right)
    // 2. Vertical (Down)
    // 3. Diagonal (Down-Right)
    // 4. Diagonal (Down-Left)
    private static final int[][] DIRECTIONS = {
        {0, 1},
        {1, 0},
        {1, 1},
        {1, -1}
    };

    public static void main(String[] args) {
        char[][] grid = readGridFromInput();

        if (hasWinner(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Reads the 10x10 grid from standard input.
     * 
     * @return A 2D array representing the grid.
     */
    private static char[][] readGridFromInput() {
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        try (Scanner scanner = new Scanner(System.in)) {
            for (int i = 0; i < GRID_SIZE; i++) {
                if (scanner.hasNextLine()) {
                    String line = scanner.nextLine();
                    for (int j = 0; j < GRID_SIZE; j++) {
                        // If the line is shorter than the grid width, pad with a space
                        if (j < line.length()) {
                            grid[i][j] = line.charAt(j);
                        } else {
                            grid[i][j] = ' ';
                        }
                    }
                }
            }
        }
        return grid;
    }

    /**
     * Iterates through the grid to check if any cell starts a winning sequence.
     * 
     * @param grid The 2D character array.
     * @return true if a sequence of five identical characters is found.
     */
    private static boolean hasWinner(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                // Skip "empty" cells if necessary (e.g., if space is a background char)
                if (grid[r][c] == ' ' || grid[r][c] == '.') {
                    continue;
                }

                for (int[] dir : DIRECTIONS) {
                    if (isSequenceMatch(grid, r, c, dir[0], dir[1])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a sequence of identical characters exists starting from (row, col) 
     * moving in the specified direction.
     * 
     * @param grid The 2D character array.
     * @param row Starting row index.
     * @param col Starting column index.
     * @param rowDelta Change in row per step.
     * @param colDelta Change in column per step.
     * @return true if a sequence of WINNING_LENGTH is found.
     */
    private static boolean isSequenceMatch(char[][] grid, int row, int col, int rowDelta, int colDelta) {
        char target = grid[row][col];

        for (int i = 1; i < WINNING_LENGTH; i++) {
            int nextRow = row + (i * rowDelta);
            int nextCol = col + (i * colDelta);

            if (!isWithinBounds(nextRow, nextCol) || grid[nextRow][nextCol] != target) {
                return false;
            }
        }
        return true;
    }

    /**
     * Validates if the given coordinates are within the grid boundaries.
     * 
     * @param r Row index.
     * @param c Column index.
     * @return true if the coordinates are valid.
     */
    private static boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
    }
}

import java.util.Scanner;

/**
 * GridPatternChecker determines if a 10x10 grid contains a specific pattern:
 * A '.' cell that is part of a straight line of at least 5 cells 
 * (where the '.' cell counts as one and the others must be 'X').
 */
public class GridPatternChecker {

    private static final int GRID_SIZE = 10;
    private static final int REQUIRED_LINE_LENGTH = 5;
    private static final char EMPTY_CELL = '.';
    private static final char X_CELL = 'X';

    // Direction vectors for: Horizontal, Vertical, Diagonal (top-left to bottom-right), Diagonal (top-right to bottom-left)
    private static final int[][] DIRECTIONS = {
        {0, 1},  // Horizontal
        {1, 0},  // Vertical
        {1, 1},  // Diagonal 1
        {1, -1}  // Diagonal 2
    };

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] grid = readGrid(scanner, GRID_SIZE);
        scanner.close();

        if (hasPattern(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Reads the grid from standard input.
     */
    private static char[][] readGrid(Scanner scanner, int size) {
        char[][] grid = new char[size][size];
        for (int i = 0; i < size; i++) {
            String line = scanner.next();
            grid[i] = line.toCharArray();
        }
        return grid;
    }

    /**
     * Iterates through the grid to find if any EMPTY_CELL satisfies the pattern.
     */
    private static boolean hasPattern(char[][] grid) {
        for (int row = 0; row < GRID_SIZE; row++) {
            for (int col = 0; col < GRID_SIZE; col++) {
                if (grid[row][col] == EMPTY_CELL) {
                    if (checkAllDirections(grid, row, col)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if the cell at (row, col) forms a line of length >= REQUIRED_LINE_LENGTH
     * in any of the four possible axes.
     */
    private static boolean checkAllDirections(char[][] grid, int row, int col) {
        for (int[] direction : DIRECTIONS) {
            int count = countConsecutiveInLine(grid, row, col, direction[0], direction[1]);
            if (count >= REQUIRED_LINE_LENGTH) {
                return true;
            }
        }
        return false;
    }

    /**
     * Counts how many 'X' cells exist in both directions of a given axis, 
     * starting from the given cell.
     */
    private static int countConsecutiveInLine(char[][] grid, int row, int col, int dr, int dc) {
        // Start with 1 to include the EMPTY_CELL itself
        int count = 1;

        // Check in the positive direction (e.g., right, down, etc.)
        count += countInDirection(grid, row, col, dr, dc);

        // Check in the negative direction (e.g., left, up, etc.)
        count += countInDirection(grid, row, col, -dr, -dc);

        return count;
    }

    /**
     * Helper to count consecutive 'X' cells in a specific direction.
     */
    private static int countInDirection(char[][] grid, int startRow, int startCol, int dr, int dc) {
        int count = 0;
        int currentRow = startRow + dr;
        int currentCol = startCol + dc;

        while (isWithinBounds(currentRow, currentCol) && grid[currentRow][currentCol] == X_CELL) {
            count++;
            currentRow += dr;
            currentCol += dc;
        }
        return count;
    }

    private static boolean isWithinBounds(int row, int col) {
        return row >= 0 && row < GRID_SIZE && col >= 0 && col < GRID_SIZE;
    }
}

import java.util.Scanner;

/**
 * A solver for the "Five in a Row" game on a 10x10 grid.
 * The goal is to determine if placing a single 'X' can create a sequence of 5 'X's
 * horizontally, vertically, or diagonally.
 */
public class FiveInARowSolver {

    private static final int GRID_SIZE = 10;
    private static final int WIN_LENGTH = 5;
    private static final char PLAYER_X = 'X';
    private static final char EMPTY_SPOT = '.';

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            char[][] grid = readGrid(scanner);

            if (canAchieveWin(grid)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        } catch (Exception e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Reads the 10x10 grid from standard input.
     */
    private static char[][] readGrid(Scanner scanner) {
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        for (int r = 0; r < GRID_SIZE; r++) {
            String line = scanner.next();
            for (int c = 0; c < GRID_SIZE; c++) {
                grid[r][c] = line.charAt(c);
            }
        }
        return grid;
    }

    /**
     * Attempts to place one 'X' in every available '.' spot to see if a win is possible.
     */
    private static boolean canAchieveWin(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                if (grid[r][c] == EMPTY_SPOT) {
                    // Try placing an X
                    grid[r][c] = PLAYER_X;

                    if (hasWinningSequence(grid)) {
                        return true;
                    }

                    // Backtrack: restore the empty spot
                    grid[r][c] = EMPTY_SPOT;
                }
            }
        }
        return false;
    }

    /**
     * Scans the grid to check if any sequence of 5 'X's exists.
     */
    private static boolean hasWinningSequence(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                // Optimization: only start checking if the current cell is an 'X'
                if (grid[r][c] == PLAYER_X) {
                    // Check all four possible directions:
                    // Horizontal, Vertical, Diagonal Down-Right, Diagonal Down-Left
                    if (checkDirection(grid, r, c, 0, 1) || 
                        checkDirection(grid, r, c, 1, 0) || 
                        checkDirection(grid, r, c, 1, 1) || 
                        checkDirection(grid, r, c, 1, -1)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a sequence of WIN_LENGTH exists starting from (row, col) 
     * moving in the direction (dr, dc).
     */
    private static boolean checkDirection(char[][] grid, int row, int col, int dr, int dc) {
        for (int i = 0; i < WIN_LENGTH; i++) {
            int currR = row + (i * dr);
            int currC = col + (i * dc);

            if (!isValidPosition(currR, currC) || grid[currR][currC] != PLAYER_X) {
                return false;
            }
        }
        return true;
    }

    private static boolean isValidPosition(int r, int c) {
        return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * A utility to detect specific winning patterns in a 10x10 grid.
 * A winning pattern is defined as exactly four 'X's and one '.' in a sequence of length 5.
 */
public class GridPatternChecker {

    private static final int GRID_SIZE = 10;
    private static final int SEQUENCE_LENGTH = 5;
    private static final int REQUIRED_X_COUNT = 4;
    private static final int REQUIRED_DOT_COUNT = 1;

    // Direction vectors for: Horizontal, Vertical, Diagonal Down-Right, Diagonal Down-Left
    private static final int[] ROW_DIRECTIONS = {0, 1, 1, 1};
    private static final int[] COL_DIRECTIONS = {1, 0, 1, -1};

    private final FastScanner scanner;
    private final PrintWriter writer;

    public GridPatternChecker(InputStream inputStream, PrintStream outputStream) {
        this.scanner = new FastScanner(inputStream);
        this.writer = new PrintWriter(outputStream);
    }

    /**
     * Main execution logic to read input and determine if a winning pattern exists.
     */
    public void run() throws IOException {
        char[][] grid = readGrid();
        boolean containsPattern = hasWinningPattern(grid);
        writer.println(containsPattern ? "YES" : "NO");
        writer.flush();
    }

    private char[][] readGrid() throws IOException {
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            grid[i] = scanner.next().toCharArray();
        }
        return grid;
    }

    /**
     * Iterates through every cell and every direction to find a winning sequence.
     */
    private boolean hasWinningPattern(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                for (int dir = 0; dir < 4; dir++) {
                    if (isWinningSequenceAt(grid, r, c, ROW_DIRECTIONS[dir], COL_DIRECTIONS[dir])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a sequence starting at (startRow, startCol) in direction (dr, dc)
     * matches the winning criteria.
     */
    private boolean isWinningSequenceAt(char[][] grid, int startRow, int startCol, int dr, int dc) {
        int endRow = startRow + (SEQUENCE_LENGTH - 1) * dr;
        int endCol = startCol + (SEQUENCE_LENGTH - 1) * dc;

        // Boundary check: Ensure the entire sequence stays within the grid
        if (endRow < 0 || endRow >= GRID_SIZE || endCol < 0 || endCol >= GRID_SIZE) {
            return false;
        }

        int xCount = 0;
        int dotCount = 0;

        for (int k = 0; k < SEQUENCE_LENGTH; k++) {
            char current = grid[startRow + k * dr][startCol + k * dc];
            if (current == 'X') {
                xCount++;
            } else if (current == '.') {
                dotCount++;
            }
        }

        return xCount == REQUIRED_X_COUNT && dotCount == REQUIRED_DOT_COUNT;
    }

    public static void main(String[] args) {
        try {
            GridPatternChecker checker = new GridPatternChecker(System.in, System.out);
            checker.run();
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Fast I/O utility class.
     */
    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream inputStream) {
            this.reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }
    }
}

import java.util.Scanner;

/**
 * A program to detect a specific pattern in a 10x10 grid.
 * The pattern consists of 5 consecutive cells containing exactly 4 'X' characters and 1 '.' character.
 */
public class GridPatternFinder {

    private static final int GRID_SIZE = 10;
    private static final int PATTERN_LENGTH = 5;
    private static final int REQUIRED_X_COUNT = 4;
    private static final int REQUIRED_DOT_COUNT = 1;

    // Directions to search: Horizontal, Down-Left Diagonal, Vertical, Down-Right Diagonal
    private static final int[][] DIRECTIONS = {
            {0, 1},  // Horizontal (Right)
            {1, -1}, // Diagonal (Down-Left)
            {1, 0},  // Vertical (Down)
            {1, 1}   // Diagonal (Down-Right)
    };

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] grid = readGrid(scanner, GRID_SIZE);

        if (containsPattern(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Reads a square grid from the input scanner.
     */
    private static char[][] readGrid(Scanner scanner, int size) {
        char[][] grid = new char[size][size];
        for (int i = 0; i < size; i++) {
            if (scanner.hasNext()) {
                grid[i] = scanner.next().toCharArray();
            }
        }
        return grid;
    }

    /**
     * Iterates through the grid to find if the required pattern exists.
     * 
     * @param grid The 2D character array to search.
     * @return true if the pattern is found, false otherwise.
     */
    public static boolean containsPattern(char[][] grid) {
        for (int row = 0; row < GRID_SIZE; row++) {
            for (int col = 0; col < GRID_SIZE; col++) {
                if (searchFromCell(grid, row, col)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Checks all directions starting from a specific cell.
     */
    private static boolean searchFromCell(char[][] grid, int row, int col) {
        for (int[] direction : DIRECTIONS) {
            if (isPatternMatch(grid, row, col, direction[0], direction[1])) {
                return true;
            }
        }
        return false;
    }

    /**
     * Validates if the sequence of cells in a given direction matches the target pattern.
     */
    private static boolean isPatternMatch(char[][] grid, int startRow, int startCol, int rowDelta, int colDelta) {
        int xCount = 0;
        int dotCount = 0;

        for (int step = 0; step < PATTERN_LENGTH; step++) {
            int currentRow = startRow + (step * rowDelta);
            int currentCol = startCol + (step * colDelta);

            // Check if the next cell is within grid boundaries
            if (isOutOfBounds(currentRow, currentCol)) {
                return false;
            }

            char cell = grid[currentRow][currentCol];
            if (cell == 'X') {
                xCount++;
            } else if (cell == '.') {
                dotCount++;
            }
        }

        return xCount == REQUIRED_X_COUNT && dotCount == REQUIRED_DOT_COUNT;
    }

    private static boolean isOutOfBounds(int row, int col) {
        return row < 0 || row >= GRID_SIZE || col < 0 || col >= GRID_SIZE;
    }
}

import java.util.Scanner;

/**
 * Analyzes a grid to find a specific pattern: a '.' character 
 * that acts as a center for at least 4 'X' characters in a straight line 
 * (horizontal, vertical, or diagonal).
 */
public class GridPatternAnalyzer {

    private static final int GRID_SIZE = 10;
    private static final char EMPTY_CELL = '.';
    private static final char FILLED_CELL = 'X';
    private static final int MIN_REQUIRED_X_COUNT = 4;

    // Direction pairs represent opposite directions: {dr1, dc1, dr2, dc2}
    // This allows us to check both sides of a center point in one pass.
    private static final int[][] DIRECTION_PAIRS = {
            {0, 1, 0, -1},   // Horizontal
            {1, 0, -1, 0},   // Vertical
            {1, 1, -1, -1},  // Main Diagonal (\)
            {1, -1, -1, 1}   // Anti-Diagonal (/)
    };

    private final char[][] grid;

    public GridPatternAnalyzer(char[][] grid) {
        this.grid = grid;
    }

    /**
     * Scans the grid for the target pattern.
     * @return true if the pattern is found, false otherwise.
     */
    public boolean containsPattern() {
        for (int row = 0; row < GRID_SIZE; row++) {
            for (int col = 0; col < GRID_SIZE; col++) {
                if (grid[row][col] == EMPTY_CELL) {
                    if (isCenterOfPattern(row, col)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if the cell at (row, col) satisfies the pattern requirement
     * across any of the four possible axes.
     */
    private boolean isCenterOfPattern(int row, int col) {
        for (int[] pair : DIRECTION_PAIRS) {
            int countSideA = countConsecutive(row, col, pair[0], pair[1]);
            int countSideB = countConsecutive(row, col, pair[2], pair[3]);

            if (countSideA + countSideB >= MIN_REQUIRED_X_COUNT) {
                return true;
            }
        }
        return false;
    }

    /**
     * Counts how many consecutive FILLED_CELLs exist starting from 
     * the neighbor of (row, col) in the specified direction.
     */
    private int countConsecutive(int row, int col, int dr, int dc) {
        int count = 0;
        int currentRow = row + dr;
        int currentCol = col + dc;

        while (isValid(currentRow, currentCol) && grid[currentRow][currentCol] == FILLED_CELL) {
            count++;
            currentRow += dr;
            currentCol += dc;
        }
        return count;
    }

    private boolean isValid(int row, int col) {
        return row >= 0 && row < GRID_SIZE && col >= 0 && col < GRID_SIZE;
    }

    /**
     * Entry point for the application.
     */
    public static void main(String[] args) {
        char[][] grid = readGridFromInput();
        GridPatternAnalyzer analyzer = new GridPatternAnalyzer(grid);

        if (analyzer.containsPattern()) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    private static char[][] readGridFromInput() {
        Scanner scanner = new Scanner(System.in);
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];

        for (int i = 0; i < GRID_SIZE; i++) {
            if (scanner.hasNext()) {
                String line = scanner.next();
                // Ensure we handle cases where input might not be exactly GRID_SIZE long
                for (int j = 0; j < GRID_SIZE; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }
        }
        scanner.close();
        return grid;
    }
}

import java.util.Scanner;

/**
 * A utility to determine if a single move (placing an 'X' on a '.')
 * can complete a line of 5 consecutive 'X's in a 10x10 grid.
 */
public class GridWinChecker {

    private static final int GRID_SIZE = 10;
    private static final int REQUIRED_X_COUNT = 4; // 4 'X's + the current '.' = 5

    // Represents the 4 axes: Horizontal, Vertical, and the two Diagonals
    // Each pair of directions represents an axis (e.g., {0,1} and {0,-1} is horizontal)
    private static final int[][] DIRECTIONS = {
            {0, 1},  // Horizontal
            {1, 0},  // Vertical
            {1, 1},  // Diagonal Down-Right
            {1, -1}  // Diagonal Down-Left
    };

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] grid = readGrid(scanner);
        scanner.close();

        if (canCompleteLine(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Reads the 10x10 grid from standard input.
     */
    private static char[][] readGrid(Scanner scanner) {
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            String line = scanner.nextLine();
            // Ensure we handle lines that might be shorter than expected safely
            for (int j = 0; j < GRID_SIZE; j++) {
                grid[i][j] = (j < line.length()) ? line.charAt(j) : ' ';
            }
        }
        return grid;
    }

    /**
     * Iterates through the grid to find if any '.' can become a winning 'X'.
     */
    private static boolean canCompleteLine(char[][] grid) {
        for (int row = 0; row < GRID_SIZE; row++) {
            for (int col = 0; col < GRID_SIZE; col++) {
                if (grid[row][col] == '.') {
                    if (isWinningMove(grid, row, col)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks all 4 axes passing through the given cell to see if they form a line.
     */
    private static boolean isWinningMove(char[][] grid, int row, int col) {
        for (int[] direction : DIRECTIONS) {
            int dirX = direction[0];
            int dirY = direction[1];

            // Count 'X's in the positive direction of the axis
            int countForward = countConsecutiveX(grid, row, col, dirX, dirY);
            // Count 'X's in the negative direction of the axis
            int countBackward = countConsecutiveX(grid, row, col, -dirX, -dirY);

            if (countForward + countBackward >= REQUIRED_X_COUNT) {
                return true;
            }
        }
        return false;
    }

    /**
     * Counts consecutive 'X' characters in a specific direction.
     * 
     * @param grid The game board
     * @param r Starting row
     * @param c Starting column
     * @param dr Row direction delta
     * @param dc Column direction delta
     * @return Number of consecutive 'X's found
     */
    private static int countConsecutiveX(char[][] grid, int r, int c, int dr, int dc) {
        int count = 0;
        int nextR = r + dr;
        int nextC = c + dc;

        while (isValid(nextR, nextC) && grid[nextR][nextC] == 'X') {
            count++;
            nextR += dr;
            nextC += dc;
        }
        return count;
    }

    /**
     * Bounds checking for grid access.
     */
    private static boolean isValid(int r, int c) {
        return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
    }
}

import java.util.*;

/**
 * Validates if a color matrix follows a specific pattern where colors (R, G, B)
 * form uniform, equal-sized, contiguous stripes either horizontally or vertically.
 */
public class ColorMatrixValidator {

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            char[][] matrix = readMatrix(scanner, rows, cols);

            if (isValidPattern(matrix)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /**
     * Reads the matrix from the scanner.
     */
    private static char[][] readMatrix(Scanner scanner, int n, int m) {
        char[][] matrix = new char[n][m];
        for (int i = 0; i < n; i++) {
            String line = scanner.next();
            for (int j = 0; j < m; j++) {
                matrix[i][j] = line.charAt(j);
            }
        }
        return matrix;
    }

    /**
     * Determines if the matrix satisfies the pattern requirement in either 
     * row-wise or column-wise orientation.
     */
    private static boolean isValidPattern(char[][] matrix) {
        List<Character> rowStripes = extractStripes(matrix, true);
        if (rowStripes != null && isValidSequence(rowStripes)) {
            return true;
        }

        List<Character> colStripes = extractStripes(matrix, false);
        return colStripes != null && isValidSequence(colStripes);
    }

    /**
     * Extracts a sequence of colors representing uniform rows or columns.
     * @param isRow If true, extracts row colors; if false, extracts column colors.
     * @return A list of colors if all rows/cols are uniform, otherwise null.
     */
    private static List<Character> extractStripes(char[][] matrix, boolean isRow) {
        int numRows = matrix.length;
        int numCols = matrix[0].length;
        List<Character> stripes = new ArrayList<>();

        if (isRow) {
            for (int i = 0; i < numRows; i++) {
                char color = matrix[i][0];
                for (int j = 1; j < numCols; j++) {
                    if (matrix[i][j] != color) return null;
                }
                stripes.add(color);
            }
        } else {
            for (int j = 0; j < numCols; j++) {
                char color = matrix[0][j];
                for (int i = 1; i < numRows; i++) {
                    if (matrix[i][j] != color) return null;
                }
                stripes.add(color);
            }
        }
        return stripes;
    }

    /**
     * Validates that the sequence contains R, G, and B in equal, 
     * contiguous, non-interleaved blocks.
     */
    private static boolean isValidSequence(List<Character> sequence) {
        Map<Character, List<Integer>> colorIndices = new HashMap<>();
        colorIndices.put('R', new ArrayList<>());
        colorIndices.put('G', new ArrayList<>());
        colorIndices.put('B', new ArrayList<>());

        for (int i = 0; i < sequence.size(); i++) {
            char color = sequence.get(i);
            if (!colorIndices.containsKey(color)) {
                return false; // Invalid color detected
            }
            colorIndices.get(color).add(i);
        }

        List<Integer> rIndices = colorIndices.get('R');
        List<Integer> gIndices = colorIndices.get('G');
        List<Integer> bIndices = colorIndices.get('B');

        // 1. Check if all colors are present and have equal counts
        if (rIndices.isEmpty() || rIndices.size() != gIndices.size() || gIndices.size() != bIndices.size()) {
            return false;
        }

        // 2. Check if each color forms a single contiguous block
        if (!isContiguous(rIndices) || !isContiguous(gIndices) || !isContiguous(bIndices)) {
            return false;
        }

        // 3. Check if the blocks are non-overlapping 
        // (Contiguity + Equal Counts + Total Count Check naturally handles this)
        int totalColorStripes = rIndices.size() + gIndices.size() + bIndices.size();
        return totalColorStripes == sequence.size();
    }

    /**
     * Checks if a list of indices forms a contiguous range.
     */
    private static boolean isContiguous(List<Integer> indices) {
        if (indices.isEmpty()) return false;
        int min = indices.get(0);
        int max = indices.get(indices.size() - 1);
        // For sorted indices, max - min + 1 must equal the number of elements
        return (max - min + 1) == indices.size();
    }
}

import java.util.Scanner;

/**
 * A utility to analyze a grid of colors (R, G, B) to determine if it follows
 * specific striped patterns of equal color distribution.
 */
public class GridPatternChecker {

    private static final char RED = 'R';
    private static final char GREEN = 'G';
    private static final char BLUE = 'B';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        scanner.nextLine(); // Consume the newline character

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.nextLine();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
            }
        }

        boolean isPatternValid = checkPattern(grid, rows, cols);
        System.out.println(isPatternValid ? "YES" : "NO");

        scanner.close();
    }

    /**
     * Determines if the grid meets the specific pattern requirements:
     * Either all rows are identical and the row pattern is three equal color blocks,
     * or all columns are identical and the column pattern is three equal color blocks.
     */
    private static boolean checkPattern(char[][] grid, int rows, int cols) {
        boolean isRowHeterogeneous = isRowHeterogeneous(grid, rows, cols);
        boolean isColHeterogeneous = isColHeterogeneous(grid, rows, cols);

        // If there is variation in both directions, it's not a simple striped pattern.
        if (isRowHeterogeneous && isColHeterogeneous) {
            return false;
        }

        // If rows have variation but columns are uniform, all rows are identical.
        // We check the pattern of the single unique row.
        if (isRowHeterogeneous) {
            return hasEqualThreeBlocks(grid[0]);
        }

        // If columns have variation but rows are uniform, all columns are identical.
        // We check the pattern of the single unique column.
        if (isColHeterogeneous) {
            char[] firstColumn = new char[rows];
            for (int i = 0; i < rows; i++) {
                firstColumn[i] = grid[i][0];
            }
            return hasEqualThreeBlocks(firstColumn);
        }

        // If both are uniform, the grid contains only one color, which cannot satisfy the requirement.
        return false;
    }

    /**
     * Checks if any row in the grid contains different characters.
     */
    private static boolean isRowHeterogeneous(char[][] grid, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 1; j < cols; j++) {
                if (grid[i][j] != grid[i][j - 1]) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Checks if any column in the grid contains different characters.
     */
    private static boolean isColHeterogeneous(char[][] grid, int rows, int cols) {
        for (int j = 0; j < cols; j++) {
            for (int i = 1; i < rows; i++) {
                if (grid[i][j] != grid[i - 1][j]) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Validates if a sequence consists of exactly three contiguous blocks of 
     * R, G, and B, where each block has an equal length.
     * 
     * Note: This replicates the specific counting logic of the original program.
     */
    private static boolean hasEqualThreeBlocks(char[] sequence) {
        int redCount = 0;
        int greenCount = 0;
        int blueCount = 0;
        char lastChar = '\0';

        for (char c : sequence) {
            if (c == RED) {
                // Increment if it's the same color block or the first time we see this color
                if (lastChar == RED || redCount == 0) {
                    redCount++;
                    lastChar = RED;
                }
            } else if (c == GREEN) {
                if (lastChar == GREEN || greenCount == 0) {
                    greenCount++;
                    lastChar = GREEN;
                }
            } else if (c == BLUE) {
                if (lastChar == BLUE || blueCount == 0) {
                    blueCount++;
                    lastChar = BLUE;
                }
            }
        }

        // The pattern is valid if counts are equal, non-zero, and cover the whole sequence.
        boolean countsAreEqual = (redCount > 0 && redCount == greenCount && greenCount == blueCount);
        boolean coversFullSequence = (redCount + greenCount + blueCount == sequence.length);

        return countsAreEqual && coversFullSequence;
    }
}

