            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Checks if the grid satisfies either the horizontal or vertical pattern requirements.
     */
    private static boolean hasValidPattern(int[][] grid, int rows, int cols) {
        return checkHorizontalBands(grid, rows, cols) || checkVerticalBands(grid, rows, cols);
    }

    /**
     * Checks if the grid is composed of 3 equal horizontal bands of different digits.
     */
    private static boolean checkHorizontalBands(int[][] grid, int rows, int cols) {
        if (rows % 3 != 0) {
            return false;
        }

        int bandSize = rows / 3;
        Set<Integer> uniqueDigits = new HashSet<>();

        for (int band = 0; band < 3; band++) {
            int startRow = band * bandSize;
            int expectedDigit = grid[startRow][0];
            uniqueDigits.add(expectedDigit);

            for (int i = startRow; i < startRow + bandSize; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] != expectedDigit) {
                        return false;
                    }
                }
            }
        }

        return uniqueDigits.size() == 3;
    }

    /**
     * Checks if the grid is composed of 3 equal vertical bands of different digits.
     */
    private static boolean checkVerticalBands(int[][] grid, int rows, int cols) {
        if (cols % 3 != 0) {
            return false;
        }

        int bandSize = cols / 3;
        Set<Integer> uniqueDigits = new HashSet<>();

        for (int band = 0; band < 3; band++) {
            int startCol = band * bandSize;
            int expectedDigit = grid[0][startCol];
            uniqueDigits.add(expectedDigit);

            for (int j = startCol; j < startCol + bandSize; j++) {
                for (int i = 0; i < rows; i++) {
                    if (grid[i][j] != expectedDigit) {
                        return false;
                    }
                }
            }
        }

        return uniqueDigits.size() == 3;
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
