/**
 * A program to determine if a given character grid represents a valid flag.
 * A valid flag consists of three horizontal or three vertical stripes 
 * of uniform color, where each stripe has a unique color.
 */
public class Main {

    public static void main(String[] args) {
        try (InputStream inputStream = System.in;
             PrintWriter out = new PrintWriter(System.out)) {

            FastReader reader = new FastReader(inputStream);
            FlagSolver solver = new FlagSolver();
            solver.solve(reader, out);

        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * Contains the logic to solve the flag validation problem.
     */
    static class FlagSolver {
        private static final int REQUIRED_STRIPES = 3;

        /**
         * Reads the grid dimensions and content, then determines if the grid is a valid flag.
         */
        public void solve(FastReader reader, PrintWriter out) {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] grid = reader.nextCharMatrix(rows, cols);

            boolean isValid = false;

            // A flag can be valid either horizontally or vertically
            if (rows % REQUIRED_STRIPES == 0) {
                isValid |= hasHorizontalStripes(grid, rows, cols);
            }

            if (cols % REQUIRED_STRIPES == 0) {
                isValid |= hasVerticalStripes(grid, rows, cols);
            }

            out.println(isValid ? "YES" : "NO");
        }

        /**
         * Checks if the grid is composed of 3 unique horizontal stripes.
         */
        private boolean hasHorizontalStripes(char[][] grid, int rows, int cols) {
            int stripeHeight = rows / REQUIRED_STRIPES;
            Set<Character> seenColors = new HashSet<>();

            for (int s = 0; s < REQUIRED_STRIPES; s++) {
                int startRow = s * stripeHeight;
                char stripeColor = grid[startRow][0];

                // If the color has already been used in a previous stripe, it's invalid
                if (!seenColors.add(stripeColor)) {
                    return false;
                }

                // Verify all cells in the current horizontal stripe match the stripe color
                for (int r = startRow; r < startRow + stripeHeight; r++) {
                    for (int c = 0; c < cols; c++) {
                        if (grid[r][c] != stripeColor) {
                            return false;
                        }
                    }
                }
            }
            return seenColors.size() == REQUIRED_STRIPES;
        }

        /**
         * Checks if the grid is composed of 3 unique vertical stripes.
         */
        private boolean hasVerticalStripes(char[][] grid, int rows, int cols) {
            int stripeWidth = cols / REQUIRED_STRIPES;
            Set<Character> seenColors = new HashSet<>();

            for (int s = 0; s < REQUIRED_STRIPES; s++) {
                int startCol = s * stripeWidth;
                char stripeColor = grid[0][startCol];

                // If the color has already been used in a previous stripe, it's invalid
                if (!seenColors.add(stripeColor)) {
                    return false;
                }

                // Verify all cells in the current vertical stripe match the stripe color
                for (int c = startCol; c < startCol + stripeWidth; c++) {
                    for (int r = 0; r < rows; r++) {
                        if (grid[r][c] != stripeColor) {
                            return false;
                        }
                    }
                }
            }
            return seenColors.size() == REQUIRED_STRIPES;
        }
    }

    /**
     * A high-performance reader for reading primitive types and character arrays.
     */
    static class FastReader {
        private final InputStream in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int len = 0;

        public FastReader(InputStream in) {
            this.in = in;
        }

        private int read() {
            if (ptr < len) {
                return buffer[ptr++] & 0xFF;
            }
            ptr = 0;
            try {
                len = in.read(buffer);
            } catch (IOException e) {
                len = -1;
            }
            if (len <= 0) {
                return -1;
            }
            return buffer[ptr++] & 0xFF;
        }

        private int skipWhitespace() {
            int b = read();
            while (b != -1 && b <= 32) {
                b = read();
            }
            return b;
        }

        public int nextInt() {
            int b = skipWhitespace();
            if (b == -1) return 0;

            boolean negative = false;
            if (b == '-') {
                negative = true;
                b = read();
            }

            int result = 0;
            while (b >= '0' && b <= '9') {
                result = result * 10 + (b - '0');
                b = read();
            }
            return negative ? -result : result;
        }

        public char[] nextCharArray(int n) {
            int b = skipWhitespace();
            if (b == -1) return new char[0];

            char[] buf = new char[n];
            int p = 0;
            while (p < n && b > 32) {
                buf[p++] = (char) b;
                b = read();
            }
            return p == n ? buf : Arrays.copyOf(buf, p);
        }

        public char[][] nextCharMatrix(int n, int m) {
            char[][] matrix = new char[n][];
            for (int i = 0; i < n; i++) {
                matrix[i] = nextCharArray(m);
            }
            return matrix;
        }
    }
}

import java.util.Scanner;

/**
 * A program to determine if a grid represents a flag of Barland.
 * A flag is valid if it consists of three equal-sized horizontal stripes 
 * of three different colors, or three equal-sized vertical stripes 
 * of three different colors.
 */
public class FlagOfBarland {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Validate input availability
        if (!scanner.hasNextInt()) {
            return;
        }
        int rows = scanner.nextInt();

        if (!scanner.hasNextInt()) {
            return;
        }
        int cols = scanner.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            if (scanner.hasNext()) {
                grid[i] = scanner.next().toCharArray();
            }
        }

        if (isValidFlag(grid, rows, cols)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Orchestrates the check for either horizontal or vertical stripe patterns.
     * 
     * @param grid The 2D character array representing the flag.
     * @param rows Number of rows in the grid.
     * @param cols Number of columns in the grid.
     * @return true if the flag meets the criteria, false otherwise.
     */
    private static boolean isValidFlag(char[][] grid, int rows, int cols) {
        return checkHorizontalStripes(grid, rows, cols) || 
               checkVerticalStripes(grid, rows, cols);
    }

    /**
     * Checks if the grid is composed of 3 uniform horizontal stripes of distinct colors.
     */
    private static boolean checkHorizontalStripes(char[][] grid, int rows, int cols) {
        if (rows % 3 != 0) {
            return false;
        }

        int stripeHeight = rows / 3;
        char color1 = grid[0][0];
        char color2 = grid[stripeHeight][0];
        char color3 = grid[2 * stripeHeight][0];

        // Requirement: The three stripes must have distinct colors
        if (color1 == color2 || color2 == color3 || color1 == color3) {
            return false;
        }

        // Check if each stripe segment is uniform in color
        return isUniform(grid, 0, stripeHeight - 1, 0, cols - 1, color1) &&
               isUniform(grid, stripeHeight, 2 * stripeHeight - 1, 0, cols - 1, color2) &&
               isUniform(grid, 2 * stripeHeight, rows - 1, 0, cols - 1, color3);
    }

    /**
     * Checks if the grid is composed of 3 uniform vertical stripes of distinct colors.
     */
    private static boolean checkVerticalStripes(char[][] grid, int rows, int cols) {
        if (cols % 3 != 0) {
            return false;
        }

        int stripeWidth = cols / 3;
        char color1 = grid[0][0];
        char color2 = grid[0][stripeWidth];
        char color3 = grid[0][2 * stripeWidth];

        // Requirement: The three stripes must have distinct colors
        if (color1 == color2 || color2 == color3 || color1 == color3) {
            return false;
        }

        // Check if each stripe segment is uniform in color
        return isUniform(grid, 0, rows - 1, 0, stripeWidth - 1, color1) &&
               isUniform(grid, 0, rows - 1, stripeWidth, 2 * stripeWidth - 1, color2) &&
               isUniform(grid, 0, rows - 1, 2 * stripeWidth, cols - 1, color3);
    }

    /**
     * Validates that a specific rectangular area in the grid is filled with a single target color.
     *
     * @param grid The 2D array.
     * @param rowStart Starting row index (inclusive).
     * @param rowEnd Ending row index (inclusive).
     * @param colStart Starting column index (inclusive).
     * @param colEnd Ending column index (inclusive).
     * @param targetColor The color that the area must consist of.
     * @return true if the area is uniform, false otherwise.
     */
    private static boolean isUniform(char[][] grid, int rowStart, int rowEnd, 
                                     int colStart, int colEnd, char targetColor) {
        for (int r = rowStart; r <= rowEnd; r++) {
            for (int c = colStart; c <= colEnd; c++) {
                if (grid[r][c] != targetColor) {
                    return false;
                }
            }
        }
        return true;
    }
}

