/**
 * GridPatternChecker determines if a grid can be divided into three equal 
 * rectangular strips (either horizontal or vertical) such that each strip 
 * is monochromatic and all three strips have distinct colors.
 */
public class GridPatternChecker {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int rowCount = reader.nextInt();
            int columnCount = reader.nextInt();

            char[][] grid = new char[rowCount][columnCount];
            for (int i = 0; i < rowCount; i++) {
                grid[i] = reader.next().toCharArray();
            }

            if (isValidPattern(grid, rowCount, columnCount)) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        } catch (Exception e) {
            // In a production environment, use a proper logger
            out.println("NO");
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Checks if the grid satisfies the pattern requirements either horizontally or vertically.
     */
    private static boolean isValidPattern(char[][] grid, int rows, int cols) {
        // Check horizontal strips
        if (rows % 3 == 0 && checkStrips(grid, rows, cols, true)) {
            return true;
        }

        // Check vertical strips
        if (cols % 3 == 0 && checkStrips(grid, rows, cols, false)) {
            return true;
        }

        return false;
    }

    /**
     * Evaluates if the grid can be split into 3 monochromatic strips.
     * 
     * @param horizontal if true, checks horizontal strips; if false, checks vertical.
     * @return true if the pattern matches.
     */
    private static boolean checkStrips(char[][] grid, int rows, int cols, boolean horizontal) {
        Set<Character> foundColors = new HashSet<>();
        int stripSize = horizontal ? (rows / 3) : (cols / 3);

        for (int stripIdx = 0; stripIdx < 3; stripIdx++) {
            int start = stripIdx * stripSize;
            int end = (stripIdx + 1) * stripSize - 1;

            if (horizontal) {
                if (!isUniform(grid, start, end, 0, cols - 1)) {
                    return false;
                }
                foundColors.add(grid[start][0]);
            } else {
                if (!isUniform(grid, 0, rows - 1, start, end)) {
                    return false;
                }
                foundColors.add(grid[0][start]);
            }
        }

        // The problem implies three different colors must be present
        return foundColors.size() == 3;
    }

    /**
     * Verifies if a specific rectangular sub-section of the grid is monochromatic.
     */
    private static boolean isUniform(char[][] grid, int rStart, int rEnd, int cStart, int cEnd) {
        char color = grid[rStart][cStart];
        for (int i = rStart; i <= rEnd; i++) {
            for (int j = cStart; j <= cEnd; j++) {
                if (grid[i][j] != color) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
            tokenizer = new StringTokenizer("");
        }

        public String next() throws IOException {
            while (!tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        public double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }
}

