/**
 * A refactored solution to determine if a grid represents a valid Flag of Berland.
 * A valid flag consists of three distinct colored stripes (Red, Green, Blue)
 * arranged either horizontally or vertically.
 */
public class FlagOfBerland {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        int rows = reader.nextInt();
        int cols = reader.nextInt();

        // Edge case: A flag must have at least 3 lines (rows or columns) to have 3 stripes
        if (rows <= 0 || cols <= 0) {
            System.out.println("NO");
            return;
        }

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = reader.next().toCharArray();
        }

        // The flag is valid if either the horizontal stripes or vertical stripes match the pattern
        if (checkOrientation(grid, true) || checkOrientation(grid, false)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Validates if the grid forms a valid flag in the specified orientation.
     *
     * @param grid        The 2D character array representing the flag.
     * @param isHorizontal True to check rows as stripes, false to check columns.
     * @return True if the orientation forms a valid 3-color stripe pattern.
     */
    private static boolean checkOrientation(char[][] grid, boolean isHorizontal) {
        int numLines = isHorizontal ? grid.length : grid[0].length;
        int lineLength = isHorizontal ? grid[0].length : grid.length;

        List<Character> colorSequence = new ArrayList<>();

        for (int i = 0; i < numLines; i++) {
            char stripeColor = getMonochromaticColor(grid, i, isHorizontal, lineLength);

            // If a line is not monochromatic, it cannot be a valid stripe
            if (stripeColor == '\0') {
                return false;
            }
            colorSequence.add(stripeColor);
        }

        return isValidColorPattern(colorSequence);
    }

    /**
     * Checks if a specific line (row or column) is monochromatic.
     *
     * @return The character color if monochromatic, '\0' otherwise.
     */
    private static char getMonochromaticColor(char[][] grid, int lineIndex, boolean isHorizontal, int lineLength) {
        char firstChar = isHorizontal ? grid[lineIndex][0] : grid[0][lineIndex];

        for (int j = 0; j < lineLength; j++) {
            char currentChar = isHorizontal ? grid[lineIndex][j] : grid[j][lineIndex];
            if (currentChar != firstChar) {
                return '\0';
            }
        }
        return firstChar;
    }

    /**
     * Validates that the sequence of colors consists of exactly three distinct 
     * contiguous blocks of 'R', 'G', and 'B'.
     */
    private static boolean isValidColorPattern(List<Character> sequence) {
        if (sequence.isEmpty()) {
            return false;
        }

        // 1. Compress consecutive identical colors (e.g., [R, R, G, B, B] -> [R, G, B])
        List<Character> compressed = new ArrayList<>();
        compressed.add(sequence.get(0));
        for (int i = 1; i < sequence.size(); i++) {
            if (sequence.get(i) != sequence.get(i - 1)) {
                compressed.add(sequence.get(i));
            }
        }

        // 2. A valid flag must have exactly 3 color blocks
        if (compressed.size() != 3) {
            return false;
        }

        // 3. The three blocks must contain the colors R, G, and B
        Set<Character> uniqueColors = new HashSet<>(compressed);
        return uniqueColors.size() == 3 &&
               uniqueColors.contains('R') &&
               uniqueColors.contains('G') &&
               uniqueColors.contains('B');
    }

