/**
 * Contains the core logic for analyzing the grid pattern.
 */
class GridPatternSolver {

    private static final int REQUIRED_BANDS = 3;

    /**
     * Reads input and determines if the grid follows the specified pattern.
     */
    public void solve(FastReader in, PrintWriter out) throws IOException {
        int rowCount = in.nextInt();
        int colCount = in.nextInt();
        char[][] grid = new char[rowCount][colCount];

        for (int i = 0; i < rowCount; i++) {
            grid[i] = in.next().toCharArray();
        }

        if (hasValidPattern(grid)) {
            out.println("YES");
        } else {
            out.println("NO");
        }
    }

    /**
     * Checks if the grid contains either three horizontal bands or three vertical bands
     * of distinct colors.
     */
    private boolean hasValidPattern(char[][] grid) {
        return hasValidBands(grid, true) || hasValidBands(grid, false);
    }

    /**
     * Validates if the grid is divided into three equal bands of distinct colors.
     * 
     * @param grid The 2D character array.
     * @param checkHorizontal If true, checks for horizontal bands (rows). 
     *                        If false, checks for vertical bands (columns).
     * @return true if the pattern is valid.
     */
    private boolean hasValidBands(char[][] grid, boolean checkHorizontal) {
        int rows = grid.length;
        int cols = grid[0].length;

        int dimensionToDivide = checkHorizontal ? rows : cols;
        if (dimensionToDivide % REQUIRED_BANDS != 0) {
            return false;
        }

        int bandSize = dimensionToDivide / REQUIRED_BANDS;
        char[] bandColors = new char[REQUIRED_BANDS];

        for (int b = 0; b < REQUIRED_BANDS; b++) {
            int offset = b * bandSize;

            // Determine the color of the current band by looking at the first cell in the band
            char bandColor = checkHorizontal ? grid[offset][0] : grid[0][offset];
            bandColors[b] = bandColor;

            // Verify every cell within this specific band matches the band color
            if (checkHorizontal) {
                for (int r = offset; r < offset + bandSize; r++) {
                    for (int c = 0; c < cols; c++) {
                        if (grid[r][c] != bandColor) return false;
                    }
                }
            } else {
                for (int r = 0; r < rows; r++) {
                    for (int c = offset; c < offset + bandSize; c++) {
                        if (grid[r][c] != bandColor) return false;
                    }
                }
            }
        }

        // Ensure all three bands have different colors
        return isDistinct(bandColors[0], bandColors[1]) &&
               isDistinct(bandColors[1], bandColors[2]) &&
               isDistinct(bandColors[0], bandColors[2]);
    }

    private boolean isDistinct(char c1, char c2) {
        return c1 != c2;
    }
}

