    /**
     * Contains the core logic for validating the flag patterns.
     */
    static class BerlandFlagChecker {

        public void solve(FastReader reader, PrintWriter writer) throws IOException {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] grid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            boolean isValid = checkHorizontalStripes(grid, rows, cols) || 
                              checkVerticalStripes(grid, rows, cols);

            writer.println(isValid ? "YES" : "NO");
        }

        /**
         * Checks if the grid is composed of three distinct horizontal color stripes.
         */
        private boolean checkHorizontalStripes(char[][] grid, int rows, int cols) {
            if (rows % 3 != 0) {
                return false;
            }

            int segmentSize = rows / 3;
            char color1 = grid[0][0];
            char color2 = grid[segmentSize][0];
            char color3 = grid[2 * segmentSize][0];

            // The three colors must be distinct
            if (color1 == color2 || color2 == color3 || color1 == color3) {
                return false;
            }

            for (int r = 0; r < rows; r++) {
                char expectedColor = getExpectedColorForRow(r, segmentSize, color1, color2, color3);
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] != expectedColor) {
                        return false;
                    }
                }
            }

            return true;
        }

        /**
         * Checks if the grid is composed of three distinct vertical color stripes.
         */
        private boolean checkVerticalStripes(char[][] grid, int rows, int cols) {
            if (cols % 3 != 0) {
                return false;
            }

            int segmentSize = cols / 3;
            char color1 = grid[0][0];
            char color2 = grid[0][segmentSize];
            char color3 = grid[0][2 * segmentSize];

            // The three colors must be distinct
            if (color1 == color2 || color2 == color3 || color1 == color3) {
                return false;
            }

            for (int c = 0; c < cols; c++) {
                char expectedColor = getExpectedColorForColumn(c, segmentSize, color1, color2, color3);
                for (int r = 0; r < rows; r++) {
                    if (grid[r][c] != expectedColor) {
                        return false;
                    }
                }
            }

            return true;
        }

        private char getExpectedColorForRow(int row, int segmentSize, char c1, char c2, char c3) {
            if (row < segmentSize) return c1;
            if (row < 2 * segmentSize) return c2;
            return c3;
        }

        private char getExpectedColorForColumn(int col, int segmentSize, char c1, char c2, char c3) {
            if (col < segmentSize) return c1;
            if (col < 2 * segmentSize) return c2;
            return c3;
        }
    }

    /**
     * A fast I/O reader for efficient data processing.
     */
    static class FastReader implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            this.reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        @Override
        public void close() throws IOException {
            reader.close();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * This program determines if a grid of colored characters (B, R, G) 
 * can be divided into three equal-sized stripes of different colors, 
 * either horizontally or vertically.
 */
public class ColorStripesChecker {

    private static final char COLOR_B = 'B';
    private static final char COLOR_R = 'R';
    private static final char COLOR_G = 'G';

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            String line = reader.readLine();
            while (line != null && !line.trim().isEmpty()) {
                StringTokenizer st = new StringTokenizer(line);
                if (!st.hasMoreTokens()) break;

                int rows = Integer.parseInt(st.nextToken());
                int cols = Integer.parseInt(st.nextToken());

                char[][] grid = new char[rows][cols];
                for (int i = 0; i < rows; i++) {
                    String rowString = reader.readLine();
                    for (int j = 0; j < cols; j++) {
                        // Handle cases where the input row might be shorter than expected
                        grid[i][j] = (j < rowString.length()) ? rowString.charAt(j) : ' ';
                    }
                }

                if (isPatternPresent(grid, rows, cols)) {
                    out.println("YES");
                } else {
                    out.println("NO");
                }

                line = reader.readLine();
            }
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        } finally {
            out.close();
        }
    }

    /**
     * Checks if the pattern exists either horizontally or vertically.
     */
    private static boolean isPatternPresent(char[][] grid, int rows, int cols) {
        return hasValidStripes(grid, rows, cols, true) || 
               hasValidStripes(grid, rows, cols, false);
    }

    /**
     * Validates if the grid contains three equal stripes of B, R, and G.
     * 
     * @param grid The 2D character array.
     * @param rows Number of rows.
     * @param cols Number of columns.
     * @param horizontal If true, checks rows; if false, checks columns.
     * @return true if the pattern is found.
     */
    private static boolean hasValidStripes(char[][] grid, int rows, int cols, boolean horizontal) {
        int dimension = horizontal ? rows : cols;
        int otherDimension = horizontal ? cols : rows;

        // Pattern requires exactly 3 equal stripes
        if (dimension % 3 != 0) {
            return false;
        }

        int stripeSize = dimension / 3;
        char[] stripeColors = new char[3];

        for (int i = 0; i < 3; i++) {
            int startIdx = i * stripeSize;
            int endIdx = (i + 1) * stripeSize;

            // Determine the target color for this stripe based on its first cell
            char targetColor = horizontal ? grid[startIdx][0] : grid[0][startIdx];

            // Validate if the color is one of the required colors
            if (!isValidColor(targetColor)) {
                return false;
            }

            // Ensure every cell within this stripe matches the target color
            if (!isStripeUniform(grid, startIdx, endIdx, otherDimension, horizontal, targetColor)) {
                return false;
            }

            stripeColors[i] = targetColor;
        }

        // Ensure all three stripes have distinct colors from {B, R, G}
        return hasUniqueColors(stripeColors);
    }

    /**
     * Checks if all cells in a specific stripe match the target color.
     */
    private static boolean isStripeUniform(char[][] grid, int start, int end, int otherDim, 
                                           boolean horizontal, char color) {
        for (int i = start; i < end; i++) {
            for (int j = 0; j < otherDim; j++) {
                char cell = horizontal ? grid[i][j] : grid[j][i];
                if (cell != color) {
                    return false;
                }
            }
        }
        return true;
    }

    private static boolean isValidColor(char c) {
        return c == COLOR_B || c == COLOR_R || c == COLOR_G;
    }

    private static boolean hasUniqueColors(char[] colors) {
        return colors[0] != colors[1] && 
               colors[1] != colors[2] && 
               colors[0] != colors[2];
    }

    /**
     * Helper class for efficient input reading.
     */
    static class FastReader {
        private BufferedReader reader;

        public FastReader(java.io.InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String readLine() throws IOException {
            return reader.readLine();
        }
    }
}

