class GridPatternChecker {
    private final char[][] grid;
    private final int rowCount;
    private final int colCount;

    public GridPatternChecker(char[][] grid) {
        this.grid = grid;
        this.rowCount = grid.length;
        this.colCount = grid[0].length;
    }

    /**
     * Checks if the grid satisfies either the horizontal or vertical band pattern.
     */
    public boolean isValidPattern() {
        return checkHorizontalPattern() || checkVerticalPattern();
    }

    /**
     * Validates if the grid is divided into 3 equal horizontal bands,
     * where each band consists of a single unique character.
     */
    private boolean checkHorizontalPattern() {
        if (rowCount % 3 != 0) {
            return false;
        }

        int bandHeight = rowCount / 3;
        char band1Char = grid[0][0];
        char band2Char = grid[bandHeight][0];
        char band3Char = grid[bandHeight * 2][0];

        // Requirement: The characters of the three bands must be distinct
        if (band1Char == band2Char || band1Char == band3Char || band2Char == band3Char) {
            return false;
        }

        return isUniform(0, bandHeight, 0, colCount, band1Char) &&
               isUniform(bandHeight, bandHeight * 2, 0, colCount, band2Char) &&
               isUniform(bandHeight * 2, rowCount, 0, colCount, band3Char);
    }

    /**
     * Validates if the grid is divided into 3 equal vertical bands,
     * where each band consists of a single unique character.
     */
    private boolean checkVerticalPattern() {
        if (colCount % 3 != 0) {
            return false;
        }

        int bandWidth = colCount / 3;
        char band1Char = grid[0][0];
        char band2Char = grid[0][bandWidth];
        char band3Char = grid[0][bandWidth * 2];

        // Requirement: The characters of the three bands must be distinct
        if (band1Char == band2Char || band1Char == band3Char || band2Char == band3Char) {
            return false;
        }

        return isUniform(0, rowCount, 0, bandWidth, band1Char) &&
               isUniform(0, rowCount, bandWidth, bandWidth * 2, band2Char) &&
               isUniform(0, rowCount, bandWidth * 2, colCount, band3Char);
    }

    /**
     * Helper to check if a rectangular sub-region of the grid is filled with a specific character.
     * 
     * @param startRow Starting row index (inclusive)
     * @param endRow   Ending row index (exclusive)
     * @param startCol Starting column index (inclusive)
     * @param endCol   Ending column index (exclusive)
     * @param target   The character the region should contain
     * @return true if all cells in the range match the target character
     */
    private boolean isUniform(int startRow, int endRow, int startCol, int endCol, char target) {
        for (int r = startRow; r < endRow; r++) {
            for (int c = startCol; c < endCol; c++) {
                if (grid[r][c] != target) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.util.Scanner;

/**
 * A utility to validate if a given grid represents a valid flag.
 * A valid flag must have three distinct colored stripes, either horizontally or vertically.
 */
public class FlagValidator {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        scanner.nextLine(); // Consume the leftover newline

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.nextLine().toCharArray();
        }

        if (isValidFlag(grid, rows, cols)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Determines if the grid satisfies either the horizontal or vertical stripe pattern.
     */
    private static boolean isValidFlag(char[][] grid, int rows, int cols) {
        return isHorizontalStripePattern(grid, rows, cols) || 
               isVerticalStripePattern(grid, rows, cols);
    }

    /**
     * Checks if the flag consists of three distinct horizontal stripes.
     */
    private static boolean isHorizontalStripePattern(char[][] grid, int rows, int cols) {
        if (rows % 3 != 0) {
            return false;
        }

        int stripeHeight = rows / 3;
        char color1 = grid[0][0];
        char color2 = grid[stripeHeight][0];
        char color3 = grid[2 * stripeHeight][0];

        // Stripes must have distinct colors
        if (color1 == color2 || color1 == color3 || color2 == color3) {
            return false;
        }

        // Verify each stripe is uniform
        return isRegionUniform(grid, 0, stripeHeight - 1, 0, cols - 1, color1) &&
               isRegionUniform(grid, stripeHeight, 2 * stripeHeight - 1, 0, cols - 1, color2) &&
               isRegionUniform(grid, 2 * stripeHeight, rows - 1, 0, cols - 1, color3);
    }

    /**
     * Checks if the flag consists of three distinct vertical stripes.
     */
    private static boolean isVerticalStripePattern(char[][] grid, int rows, int cols) {
        if (cols % 3 != 0) {
            return false;
        }

        int stripeWidth = cols / 3;
        char color1 = grid[0][0];
        char color2 = grid[0][stripeWidth];
        char color3 = grid[0][2 * stripeWidth];

        // Stripes must have distinct colors
        if (color1 == color2 || color1 == color3 || color2 == color3) {
            return false;
        }

        // Verify each stripe is uniform
        return isRegionUniform(grid, 0, rows - 1, 0, stripeWidth - 1, color1) &&
               isRegionUniform(grid, 0, rows - 1, stripeWidth, 2 * stripeWidth - 1, color2) &&
               isRegionUniform(grid, 0, rows - 1, 2 * stripeWidth, cols - 1, color3);
    }

    /**
     * Checks if all characters within a specified rectangular region match the expected color.
     *
     * @param grid The grid to check.
     * @param rStart Starting row index.
     * @param rEnd Ending row index.
     * @param cStart Starting column index.
     * @param cEnd Ending column index.
     * @param expectedColor The color that the entire region must contain.
     * @return true if the region is uniform, false otherwise.
     */
    private static boolean isRegionUniform(char[][] grid, int rStart, int rEnd, int cStart, int cEnd, char expectedColor) {
        for (int i = rStart; i <= rEnd; i++) {
            for (int j = cStart; j <= cEnd; j++) {
                if (grid[i][j] != expectedColor) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.util.*;

/**
 * This program checks if a grid of characters follows a specific pattern:
 * The grid must be divisible into three equal blocks (either rows or columns),
 * where each block consists of a single color (R, G, or B), and all three 
 * blocks must have different colors.
 */
public class Main {

    private static final Set<Character> VALID_COLORS = Set.of('R', 'G', 'B');

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        String[] grid = new String[rows];
        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.next();
        }

        if (isPatternValid(grid)) {
            System.out.println("YES");
        } else {
            // If row pattern fails, transpose the grid and check for column pattern
            String[] columns = transpose(grid, rows, cols);
            if (isPatternValid(columns)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }

        scanner.close();
    }

    /**
     * Validates if the given array of strings (rows or columns) forms 
     * three distinct color blocks.
     *
     * @param lines An array of strings representing either rows or columns.
     * @return true if the pattern is valid, false otherwise.
     */
    private static boolean isPatternValid(String[] lines) {
        int totalLines = lines.length;

        // Pattern must be divisible into 3 equal parts
        if (totalLines % 3 != 0) {
            return false;
        }

        int blockSize = totalLines / 3;
        String[] blockPatterns = new String[3];
        blockPatterns[0] = lines[0];
        blockPatterns[1] = lines[blockSize];
        blockPatterns[2] = lines[2 * blockSize];

        // 1. Check if the representative strings of the three blocks are valid color stripes
        if (!isValidColorStripe(blockPatterns[0]) ||
            !isValidColorStripe(blockPatterns[1]) ||
            !isValidColorStripe(blockPatterns[2])) {
            return false;
        }

        // 2. Check if all three blocks have distinct colors
        if (blockPatterns[0].equals(blockPatterns[1]) ||
            blockPatterns[1].equals(blockPatterns[2]) ||
            blockPatterns[0].equals(blockPatterns[2])) {
            return false;
        }

        // 3. Verify that every line within a block is identical to its block's pattern
        for (int i = 0; i < 3; i++) {
            String expectedPattern = blockPatterns[i];
            for (int j = 0; j < blockSize; j++) {
                if (!lines[i * blockSize + j].equals(expectedPattern)) {
                    return false;
                }
            }
        }

        return true;
    }

    /**
     * Checks if a string consists entirely of a single valid color character (R, G, or B).
     *
     * @param s The string to check.
     * @return true if the string is a uniform stripe of R, G, or B.
     */
    private static boolean isValidColorStripe(String s) {
        if (s == null || s.isEmpty()) {
            return false;
        }

        char color = s.charAt(0);
        if (!VALID_COLORS.contains(color)) {
            return false;
        }

        for (int i = 1; i < s.length(); i++) {
            if (s.charAt(i) != color) {
                return false;
            }
        }
        return true;
    }

    /**
     * Transposes a 2D grid (array of strings) into its column representation.
     *
     * @param grid The original row-based grid.
     * @param rows Number of rows.
     * @param cols Number of columns.
     * @return An array of strings where each string represents a column.
     */
    private static String[] transpose(String[] grid, int rows, int cols) {
        String[] transposed = new String[cols];
        for (int j = 0; j < cols; j++) {
            StringBuilder columnBuilder = new StringBuilder();
            for (int i = 0; i < rows; i++) {
                columnBuilder.append(grid[i].charAt(j));
            }
            transposed[j] = columnBuilder.toString();
        }
        return transposed;
    }
}

import java.util.Scanner;

/**
 * A utility class to determine if a grid pattern consists of three 
 * equal-sized stripes of alternating colors (ABA pattern).
 */
public class FlagPatternSolver {

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            char[][] grid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                String rowString = scanner.next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = rowString.charAt(j);
                }
            }

            if (isValidFlagPattern(grid, rows, cols)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /**
     * Checks if the grid matches either a horizontal or vertical stripe pattern.
     */
    public static boolean isValidFlagPattern(char[][] grid, int rows, int cols) {
        return isHorizontalStripePattern(grid, rows, cols) || 
               isVerticalStripePattern(grid, rows, cols);
    }

    /**
     * Validates if the grid is divided into 3 equal horizontal stripes: Color A, Color B, Color A.
     */
    private static boolean isHorizontalStripePattern(char[][] grid, int rows, int cols) {
        if (rows % 3 != 0) {
            return false;
        }

        int stripeHeight = rows / 3;
        char color1 = grid[0][0];
        char color2 = grid[stripeHeight][0];

        // The pattern must be ABA, so color1 must not equal color2
        if (color1 == color2) {
            return false;
        }

        // Check Block 1 (Top)
        if (!isAreaUniform(grid, 0, stripeHeight - 1, 0, cols - 1, color1)) {
            return false;
        }
        // Check Block 2 (Middle)
        if (!isAreaUniform(grid, stripeHeight, 2 * stripeHeight - 1, 0, cols - 1, color2)) {
            return false;
        }
        // Check Block 3 (Bottom)
        if (!isAreaUniform(grid, 2 * stripeHeight, rows - 1, 0, cols - 1, color1)) {
            return false;
        }

        return true;
    }

    /**
     * Validates if the grid is divided into 3 equal vertical stripes: Color A, Color B, Color A.
     */
    private static boolean isVerticalStripePattern(char[][] grid, int rows, int cols) {
        if (cols % 3 != 0) {
            return false;
        }

        int stripeWidth = cols / 3;
        char color1 = grid[0][0];
        char color2 = grid[0][stripeWidth];

        // The pattern must be ABA, so color1 must not equal color2
        if (color1 == color2) {
            return false;
        }

        // Check Block 1 (Left)
        if (!isAreaUniform(grid, 0, rows - 1, 0, stripeWidth - 1, color1)) {
            return false;
        }
        // Check Block 2 (Middle)
        if (!isAreaUniform(grid, 0, rows - 1, stripeWidth, 2 * stripeWidth - 1, color2)) {
            return false;
        }
        // Check Block 3 (Right)
        if (!isAreaUniform(grid, 0, rows - 1, 2 * stripeWidth, cols - 1, color1)) {
            return false;
        }

        return true;
    }

    /**
     * Helper to check if all cells within a specific rectangular boundary match a color.
     */
    private static boolean isAreaUniform(char[][] grid, int rowStart, int rowEnd, 
                                         int colStart, int colEnd, char expectedColor) {
        for (int i = rowStart; i <= rowEnd; i++) {
            for (int j = colStart; j <= colEnd; j++) {
                if (grid[i][j] != expectedColor) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to determine if a grid of colors (R, G, B) can be partitioned 
 * into three equal monochromatic rectangular bands either horizontally or vertically.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            GridSolver solver = new GridSolver(reader);
            solver.solve(writer);
        } catch (Exception e) {
            // In a production environment, use a proper logging framework
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    /**
     * Handles the core logic of the grid problem.
     */
    static class GridSolver {
        private final FastReader reader;

        public GridSolver(FastReader reader) {
            this.reader = reader;
        }

        public void solve(PrintWriter writer) {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            if (isValidSolution(grid, rows, cols)) {
                writer.println("YES");
            } else {
                writer.println("NO");
            }
        }

        private boolean isValidSolution(char[][] grid, int rows, int cols) {
            int totalCells = rows * cols;

            // Condition 1: Total cells must be divisible by 3
            if (totalCells % 3 != 0) {
                return false;
            }

            int targetColorCount = totalCells / 3;

            // Condition 2: Counts of R, G, and B must be exactly equal
            if (!hasEqualColorDistribution(grid, rows, cols, targetColorCount)) {
                return false;
            }

            // Condition 3: Check for valid horizontal or vertical split
            return canSplitHorizontally(grid, rows, cols) || canSplitVertically(grid, rows, cols);
        }

        private boolean hasEqualColorDistribution(char[][] grid, int rows, int cols, int target) {
            int rCount = 0, gCount = 0, bCount = 0;

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == 'R') rCount++;
                    else if (grid[i][j] == 'G') gCount++;
                    else if (grid[i][j] == 'B') bCount++;
                }
            }
            return rCount == target && gCount == target && bCount == target;
        }

        private boolean canSplitHorizontally(char[][] grid, int rows, int cols) {
            if (rows % 3 != 0) return false;

            int segmentHeight = rows / 3;
            return isSegmentUniform(grid, 0, segmentHeight, 0, cols) &&
                   isSegmentUniform(grid, segmentHeight, 2 * segmentHeight, 0, cols) &&
                   isSegmentUniform(grid, 2 * segmentHeight, rows, 0, cols);
        }

        private boolean canSplitVertically(char[][] grid, int rows, int cols) {
            if (cols % 3 != 0) return false;

            int segmentWidth = cols / 3;
            return isSegmentUniform(grid, 0, rows, 0, segmentWidth) &&
                   isSegmentUniform(grid, 0, rows, segmentWidth, 2 * segmentWidth) &&
                   isSegmentUniform(grid, 0, rows, 2 * segmentWidth, cols);
        }

        /**
         * Checks if a specific rectangular sub-section of the grid is monochromatic.
         */
        private boolean isSegmentUniform(char[][] grid, int rStart, int rEnd, int cStart, int cEnd) {
            char color = grid[rStart][cStart];
            for (int i = rStart; i < rEnd; i++) {
                for (int j = cStart; j < cEnd; j++) {
                    if (grid[i][j] != color) {
                        return false;
                    }
                }
            }
            return true;
        }
    }

    /**
     * High-performance input reader for large datasets.
     */
    static class FastReader {
        private final InputStream inputStream;
        private final byte[] buffer = new byte[1024];
        private int pointer = 0;
        private int bufferLength = 0;

        public FastReader(InputStream inputStream) {
            this.inputStream = inputStream;
        }

        private byte read() {
            if (pointer >= bufferLength) {
                pointer = 0;
                try {
                    bufferLength = inputStream.read(buffer);
                } catch (IOException e) {
                    return -1;
                }
                if (bufferLength <= 0) return -1;
            }
            return buffer[pointer++];
        }

        public int nextInt() {
            int c = read();
            while (c >= 0 && c <= 32) c = read();
            if (c == -1) return -1;
            int neg = 1;
            if (c == '-') {
                neg = -1;
                c = read();
            }
            int res = 0;
            while (c > 32) {
                res = res * 10 + (c - '0');
                c = read();
            }
            return res * neg;
        }

        public String next() {
            int c = read();
            while (c >= 0 && c <= 32) c = read();
            if (c == -1) return null;
            StringBuilder sb = new StringBuilder();
            while (c > 32) {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }
    }
}

import java.util.Scanner;
import java.util.Set;

/**
 * A utility to validate if a given grid represents a valid Flag of Berland.
 * A valid flag consists of three equal-sized bands of different colors (Red, Green, Blue),
 * oriented either horizontally or vertically.
 */
public class FlagOfBerland {

    private static final Set<Character> VALID_COLORS = Set.of('R', 'G', 'B');

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;

            int rowCount = scanner.nextInt();
            int colCount = scanner.nextInt();
            scanner.nextLine(); // Consume newline

            char[][] grid = new char[rowCount][colCount];
            for (int i = 0; i < rowCount; i++) {
                grid[i] = scanner.nextLine().toCharArray();
            }

            if (isValidBerlandFlag(grid, rowCount, colCount)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /**
     * Determines if the grid follows the Berland flag rules.
     */
    private static boolean isValidBerlandFlag(char[][] grid, int rows, int cols) {
        if (isFirstRowUniform(grid, rows, cols)) {
            return checkHorizontalFlag(grid, rows, cols);
        } else {
            return checkVerticalFlag(grid, rows, cols);
        }
    }

    /**
     * Checks if the first row consists of the same character.
     * This helps distinguish between horizontal and vertical band orientations.
     */
    private static boolean isFirstRowUniform(char[][] grid, int rows, int cols) {
        if (cols <= 1) return true;
        char firstChar = grid[0][0];
        for (int j = 1; j < cols; j++) {
            if (grid[0][j] != firstChar) {
                return false;
            }
        }
        return true;
    }

    /**
     * Validates a flag with horizontal bands.
     */
    private static boolean checkHorizontalFlag(char[][] grid, int rows, int cols) {
        if (rows % 3 != 0) return false;

        int bandSize = rows / 3;
        char[] bandColors = new char[3];
        bandColors[0] = grid[0][0];
        bandColors[1] = grid[bandSize][0];
        bandColors[2] = grid[2 * bandSize][0];

        return validateBands(grid, rows, cols, bandColors, true);
    }

    /**
     * Validates a flag with vertical bands.
     */
    private static boolean checkVerticalFlag(char[][] grid, int rows, int cols) {
        if (cols % 3 != 0) return false;

        int bandSize = cols / 3;
        char[] bandColors = new char[3];
        bandColors[0] = grid[0][0];
        bandColors[1] = grid[0][bandSize];
        bandColors[2] = grid[0][2 * bandSize];

        return validateBands(grid, rows, cols, bandColors, false);
    }

    /**
     * Validates that the grid is composed of exactly three bands of distinct RGB colors.
     * 
     * @param isHorizontal direction of the bands
     * @param bandColors the colors expected in each of the 3 bands
     */
    private static boolean validateBands(char[][] grid, int rows, int cols, char[] bandColors, boolean isHorizontal) {
        // 1. Check if colors are valid (R, G, B) and distinct
        if (!areColorsValidAndDistinct(bandColors)) {
            return false;
        }

        // 2. Check if every cell in the grid matches its corresponding band color
        int bandSize = isHorizontal ? rows / 3 : cols / 3;

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                char expectedColor;
                if (isHorizontal) {
                    int bandIndex = i / bandSize;
                    expectedColor = bandColors[bandIndex];
                } else {
                    int bandIndex = j / bandSize;
                    expectedColor = bandColors[bandIndex];
                }

                if (grid[i][j] != expectedColor) {
                    return false;
                }
            }
        }

        return true;
    }

    /**
     * Ensures that the three provided colors are 'R', 'G', and 'B' and are all different.
     */
    private static boolean areColorsValidAndDistinct(char[] colors) {
        Set<Character> uniqueColors = Set.of(colors[0], colors[1], colors[2]);

        if (uniqueColors.size() != 3) {
            return false;
        }

        for (char c : uniqueColors) {
            if (!VALID_COLORS.contains(c)) {
                return false;
            }
        }

        return true;
    }
}

