/**
 * Main entry point for the Grid Pattern Solver application.
 */
public class Main {
    public static void main(String[] args) {
        try (FastReader reader = new FastReader(System.in);
             PrintWriter writer = new PrintWriter(System.out)) {

            GridPatternSolver solver = new GridPatternSolver(reader, writer);
            solver.solve();

        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }
}

/**
 * Contains the logic to determine if the grid satisfies the specific 3-strip pattern.
 */
class GridPatternSolver {
    private final FastReader reader;
    private final PrintWriter writer;

    public GridPatternSolver(FastReader reader, PrintWriter writer) {
        this.reader = reader;
        this.writer = writer;
    }

    public void solve() throws IOException {
        int[] dimensions = reader.readIntArray();
        if (dimensions.length < 2) return;

        int rows = dimensions[0];
        int cols = dimensions[1];

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = reader.readLine().trim().toCharArray();
        }

        if (canSolveVerticalStrips(grid, rows, cols) || canSolveHorizontalStrips(grid, rows, cols)) {
            writer.println("YES");
        } else {
            writer.println("NO");
        }
    }

    /**
     * Checks if the grid can be divided into 3 equal vertical strips,
     * where each strip is uniform and all three strips have unique characters.
     */
    private boolean canSolveVerticalStrips(char[][] grid, int rows, int cols) {
        if (rows % 3 != 0) return false;

        int stripSize = rows / 3;
        char[] stripChars = new char[3];

        // Determine the required character for each strip based on the first column
        for (int k = 0; k < 3; k++) {
            stripChars[k] = grid[k * stripSize][0];
        }

        // Requirement: All three strips must have distinct characters
        if (stripChars[0] == stripChars[1] || 
            stripChars[1] == stripChars[2] || 
            stripChars[0] == stripChars[2]) {
            return false;
        }

        // Requirement: Every cell in a strip must match that strip's character
        for (int k = 0; k < 3; k++) {
            char target = stripChars[k];
            for (int i = k * stripSize; i < (k + 1) * stripSize; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] != target) return false;
                }
            }
        }
        return true;
    }

    /**
     * Checks if the grid can be divided into 3 equal horizontal strips,
     * where each strip is uniform and all three strips have unique characters.
     */
    private boolean canSolveHorizontalStrips(char[][] grid, int rows, int cols) {
        if (cols % 3 != 0) return false;

        int stripSize = cols / 3;
        char[] stripChars = new char[3];

        // Determine the required character for each strip based on the first row
        for (int k = 0; k < 3; k++) {
            stripChars[k] = grid[0][k * stripSize];
        }

        // Requirement: All three strips must have distinct characters
        if (stripChars[0] == stripChars[1] || 
            stripChars[1] == stripChars[2] || 
            stripChars[0] == stripChars[2]) {
            return false;
        }

        // Requirement: Every cell in a strip must match that strip's character
        for (int k = 0; k < 3; k++) {
            char target = stripChars[k];
            for (int i = 0; i < rows; i++) {
                for (int j = k * stripSize; j < (k + 1) * stripSize; j++) {
                    if (grid[i][j] != target) return false;
                }
            }
        }
        return true;
    }
}

/**
 * High-performance input reader.
 */
class FastReader implements AutoCloseable {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    public FastReader(InputStream inputStream) {
        this.reader = new BufferedReader(new InputStreamReader(inputStream));
    }

    public String readLine() throws IOException {
        return reader.readLine();
    }

    public int[] readIntArray() throws IOException {
        String line = reader.readLine();
        if (line == null) return new int[0];
        StringTokenizer st = new StringTokenizer(line);
        int[] res = new int[st.countTokens()];
        for (int i = 0; i < res.length; i++) {
            res[i] = Integer.parseInt(st.nextToken());
        }
        return res;
    }

    @Override
    public void close() throws IOException {
        reader.close();
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Analyzes a grid of colors to determine if it follows a specific pattern:
 * Either all rows are monochromatic and form three contiguous color blocks 
 * of equal size (R, G, B), or all columns follow the same rule.
 */
public class GridPatternValidator {

    private static final char COLOR_R = 'R';
    private static final char COLOR_G = 'G';
    private static final char COLOR_B = 'B';

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int rowCount = scanner.nextInt();
            int colCount = scanner.nextInt();
            scanner.nextLine(); // Consume the remaining newline

            String[] grid = new String[rowCount];
            for (int i = 0; i < rowCount; i++) {
                grid[i] = scanner.nextLine();
            }

            if (isValidPattern(grid, rowCount, colCount)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /**
     * Checks if the grid is valid either by row-wise or column-wise patterns.
     */
    private static boolean isValidPattern(String[] grid, int rowCount, int colCount) {
        return isRowPatternValid(grid, rowCount, colCount) || 
               isColumnPatternValid(grid, rowCount, colCount);
    }

    /**
     * Validates if the rows satisfy the requirement: 
     * All rows are monochromatic and colors form 3 equal contiguous blocks.
     */
    private static boolean isRowPatternValid(String[] grid, int rowCount, int colCount) {
        List<Character> rowColors = new ArrayList<>();

        for (int i = 0; i < rowCount; i++) {
            char color = grid[i].charAt(0);
            if (!isMonochromatic(grid[i], color)) {
                return false;
            }
            rowColors.add(color);
        }

        return isColorSequenceValid(rowColors);
    }

    /**
     * Validates if the columns satisfy the requirement: 
     * All columns are monochromatic and colors form 3 equal contiguous blocks.
     */
    private static boolean isColumnPatternValid(String[] grid, int rowCount, int colCount) {
        List<Character> colColors = new ArrayList<>();

        for (int j = 0; j < colCount; j++) {
            char color = grid[0].charAt(j);
            for (int i = 1; i < rowCount; i++) {
                if (grid[i].charAt(j) != color) {
                    return false;
                }
            }
            colColors.add(color);
        }

        return isColorSequenceValid(colColors);
    }

    /**
     * Checks if a specific string consists of only one repeated character.
     */
    private static boolean isMonochromatic(String line, char color) {
        for (int i = 0; i < line.length(); i++) {
            if (line.charAt(i) != color) {
                return false;
            }
        }
        return true;
    }

    /**
     * Checks if the sequence of colors contains an equal number of R, G, and B,
     * and that each color forms exactly one contiguous block.
     */
    private static boolean isColorSequenceValid(List<Character> sequence) {
        int size = sequence.size();
        if (size == 0 || size % 3 != 0) {
            return false;
        }

        int targetCount = size / 3;
        int rCount = 0, gCount = 0, bCount = 0;

        for (char c : sequence) {
            if (c == COLOR_R) rCount++;
            else if (c == COLOR_G) gCount++;
            else if (c == COLOR_B) bCount++;
        }

        // Verify equal counts of R, G, and B
        if (rCount != targetCount || gCount != targetCount || bCount != targetCount) {
            return false;
        }

        // Verify that there are exactly 3 contiguous color blocks
        int colorBlocks = 1;
        for (int i = 1; i < size; i++) {
            if (sequence.get(i) != sequence.get(i - 1)) {
                colorBlocks++;
            }
        }

        return colorBlocks == 3;
    }
}

import java.util.Scanner;

/**
 * A utility class to determine if a given grid represents a valid 
 * tricolor flag with either horizontal or vertical stripes.
 */
public class FlagPatternChecker {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rowCount = scanner.nextInt();
        int colCount = scanner.nextInt();
        String[] grid = new String[rowCount];

        for (int i = 0; i < rowCount; i++) {
            grid[i] = scanner.next();
        }

        if (isValidFlag(grid, rowCount, colCount)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Checks if the grid satisfies either the horizontal or vertical stripe pattern.
     */
    private static boolean isValidFlag(String[] grid, int rows, int cols) {
        return hasHorizontalStripes(grid, rows, cols) || 
               hasVerticalStripes(grid, rows, cols);
    }

    /**
     * Validates if the grid is divided into three equal horizontal stripes 
     * of distinct colors.
     */
    private static boolean hasHorizontalStripes(String[] grid, int rows, int cols) {
        if (rows % 3 != 0) {
            return false;
        }

        int stripeHeight = rows / 3;
        char color1 = grid[0].charAt(0);
        char color2 = grid[stripeHeight].charAt(0);
        char color3 = grid[2 * stripeHeight].charAt(0);

        // All three colors must be distinct
        if (color1 == color2 || color2 == color3 || color1 == color3) {
            return false;
        }

        return isRegionUniform(grid, 0, stripeHeight, 0, cols, color1) &&
               isRegionUniform(grid, stripeHeight, 2 * stripeHeight, 0, cols, color2) &&
               isRegionUniform(grid, 2 * stripeHeight, rows, 0, cols, color3);
    }

    /**
     * Validates if the grid is divided into three equal vertical stripes 
     * of distinct colors.
     */
    private static boolean hasVerticalStripes(String[] grid, int rows, int cols) {
        if (cols % 3 != 0) {
            return false;
        }

        int stripeWidth = cols / 3;
        char color1 = grid[0].charAt(0);
        char color2 = grid[0].charAt(stripeWidth);
        char color3 = grid[0].charAt(2 * stripeWidth);

        // All three colors must be distinct
        if (color1 == color2 || color2 == color3 || color1 == color3) {
            return false;
        }

        return isRegionUniform(grid, 0, rows, 0, stripeWidth, color1) &&
               isRegionUniform(grid, 0, rows, stripeWidth, 2 * stripeWidth, color2) &&
               isRegionUniform(grid, 0, rows, 2 * stripeWidth, cols, color3);
    }

    /**
     * Helper method to check if a rectangular sub-section of the grid 
     * consists entirely of a single target color.
     *
     * @param grid The grid array.
     * @param rowStart Starting row index (inclusive).
     * @param rowEnd Ending row index (exclusive).
     * @param colStart Starting column index (inclusive).
     * @param colEnd Ending column index (exclusive).
     * @param targetColor The color that the region must match.
     * @return true if the region is uniform, false otherwise.
     */
    private static boolean isRegionUniform(String[] grid, int rowStart, int rowEnd, 
                                           int colStart, int colEnd, char targetColor) {
        for (int r = rowStart; r < rowEnd; r++) {
            for (int c = colStart; c < colEnd; c++) {
                if (grid[r].charAt(c) != targetColor) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.util.HashSet;
import java.util.Scanner;
import java.util.Set;

/**
 * BerlandFlag determines if a given grid represents a valid Berland flag.
 * A valid flag consists of three equal-sized horizontal or vertical bands,
 * where each band is a single color, and all three colors (R, G, B) are used.
 */
public class BerlandFlag {

    private static final char COLOR_RED = 'R';
    private static final char COLOR_GREEN = 'G';
    private static final char COLOR_BLUE = 'B';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        char[][] grid = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            grid[i] = line.toCharArray();
        }

        if (isValidFlag(grid, rows, cols)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Checks if the flag matches either a horizontal or vertical pattern.
     */
    private static boolean isValidFlag(char[][] grid, int rows, int cols) {
        return isHorizontalPattern(grid, rows, cols) || isVerticalPattern(grid, rows, cols);
    }

    /**
     * Validates if the grid is composed of 3 equal horizontal bands of R, G, and B.
     */
    private static boolean isHorizontalPattern(char[][] grid, int rows, int cols) {
        if (rows % 3 != 0) {
            return false;
        }

        int bandHeight = rows / 3;
        Set<Character> foundColors = new HashSet<>();

        for (int band = 0; band < 3; band++) {
            int startRow = band * bandHeight;
            char bandColor = grid[startRow][0];

            if (!isValidColor(bandColor)) {
                return false;
            }
            foundColors.add(bandColor);

            // Verify all cells in this horizontal band match the band color
            for (int r = startRow; r < startRow + bandHeight; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] != bandColor) {
                        return false;
                    }
                }
            }
        }

        return foundColors.size() == 3;
    }

    /**
     * Validates if the grid is composed of 3 equal vertical bands of R, G, and B.
     */
    private static boolean isVerticalPattern(char[][] grid, int rows, int cols) {
        if (cols % 3 != 0) {
            return false;
        }

        int bandWidth = cols / 3;
        Set<Character> foundColors = new HashSet<>();

        for (int band = 0; band < 3; band++) {
            int startCol = band * bandWidth;
            char bandColor = grid[0][startCol];

            if (!isValidColor(bandColor)) {
                return false;
            }
            foundColors.add(bandColor);

            // Verify all cells in this vertical band match the band color
            for (int c = startCol; c < startCol + bandWidth; c++) {
                for (int r = 0; r < rows; r++) {
                    if (grid[r][c] != bandColor) {
                        return false;
                    }
                }
            }
        }

        return foundColors.size() == 3;
    }

    /**
     * Ensures the character is one of the allowed colors.
     */
    private static boolean isValidColor(char c) {
        return c == COLOR_RED || c == COLOR_GREEN || c == COLOR_BLUE;
    }
}

import java.util.Scanner;

/**
 * A program to validate if a given grid represents a Berland Flag.
 * A Berland Flag must consist of exactly three horizontal or three vertical stripes,
 * where each stripe is a single color and all three stripes have distinct colors.
 */
public class BerlandFlag {

    public static void main(String[] args) {
