/**
 * Logic provider for validating the Berland Flag rules.
 */
class FlagValidator {
    private final int rows;
    private final int cols;
    private final char[][] grid;

    public FlagValidator(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
    }

    /**
     * A flag is valid if it follows either the horizontal stripe pattern or the vertical stripe pattern.
     */
    public boolean isValid() {
        return isValidHorizontalPattern() || isValidVerticalPattern();
    }

    private boolean isValidHorizontalPattern() {
        if (rows % 3 != 0) {
            return false;
        }

        int stripeHeight = rows / 3;
        char color1 = grid[0][0];
        char color2 = grid[stripeHeight][0];
        char color3 = grid[2 * stripeHeight][0];

        if (!areColorsDistinct(color1, color2, color3)) {
            return false;
        }

        return isStripeUniform(0, stripeHeight, 0, cols, color1) &&
               isStripeUniform(stripeHeight, 2 * stripeHeight, 0, cols, color2) &&
               isStripeUniform(2 * stripeHeight, rows, 0, cols, color3);
    }

    private boolean isValidVerticalPattern() {
        if (cols % 3 != 0) {
            return false;
        }

        int stripeWidth = cols / 3;
        char color1 = grid[0][0];
        char color2 = grid[0][stripeWidth];
        char color3 = grid[0][2 * stripeWidth];

        if (!areColorsDistinct(color1, color2, color3)) {
            return false;
        }

        return isStripeUniform(0, rows, 0, stripeWidth, color1) &&
               isStripeUniform(0, rows, stripeWidth, 2 * stripeWidth, color2) &&
               isStripeUniform(0, rows, 2 * stripeWidth, cols, color3);
    }

    /**
     * Checks if three colors are unique.
     */
    private boolean areColorsDistinct(char c1, char c2, char c3) {
        return c1 != c2 && c1 != c3 && c2 != c3;
    }

    /**
     * Checks if all cells within the specified rectangular bounds match the expected color.
     */
    private boolean isStripeUniform(int startRow, int endRow, int startCol, int endCol, char expectedColor) {
        for (int i = startRow; i < endRow; i++) {
            for (int j = startCol; j < endCol; j++) {
                if (grid[i][j] != expectedColor) {
                    return false;
                }
            }
        }
        return true;
    }
}

