/**
 * Service class responsible for validating if a flag follows 
 * the three-stripe pattern with distinct colors R, G, and B.
 */
class FlagValidator {
    private static final Set<Character> REQUIRED_COLORS = Set.of('R', 'G', 'B');

    /**
     * Validates if the flag is either composed of 3 horizontal 
     * or 3 vertical stripes.
     */
    public boolean isValid(Flag flag) {
        return isHorizontalPattern(flag) || isVerticalPattern(flag);
    }

    private boolean isHorizontalPattern(Flag flag) {
        if (flag.getRows() % 3 != 0) {
            return false;
        }

        int stripeHeight = flag.getRows() / 3;
        Set<Character> stripeColors = new HashSet<>();

        for (int i = 0; i < 3; i++) {
            int startRow = i * stripeHeight;
            int endRow = startRow + stripeHeight - 1;
            char stripeColor = flag.getPixel(startRow, 0);

            if (!isRegionUniform(flag, startRow, endRow, 0, flag.getCols() - 1, stripeColor)) {
                return false;
            }
            stripeColors.add(stripeColor);
        }

        return hasValidColors(stripeColors);
    }

    private boolean isVerticalPattern(Flag flag) {
        if (flag.getCols() % 3 != 0) {
            return false;
        }

        int stripeWidth = flag.getCols() / 3;
        Set<Character> stripeColors = new HashSet<>();

        for (int i = 0; i < 3; i++) {
            int startCol = i * stripeWidth;
            int endCol = startCol + stripeWidth - 1;
            char stripeColor = flag.getPixel(0, startCol);

            if (!isRegionUniform(flag, 0, flag.getRows() - 1, startCol, endCol, stripeColor)) {
                return false;
            }
            stripeColors.add(stripeColor);
        }

        return hasValidColors(stripeColors);
    }

    /**
     * Checks if all pixels within a specified rectangular region match the expected color.
     */
    private boolean isRegionUniform(Flag flag, int r1, int r2, int c1, int c2, char color) {
        for (int r = r1; r <= r2; r++) {
            for (int c = c1; c <= c2; c++) {
                if (flag.getPixel(r, c) != color) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Ensures the collected colors are exactly 'R', 'G', and 'B'.
     */
    private boolean hasValidColors(Set<Character> colors) {
        return colors.size() == 3 && colors.equals(REQUIRED_COLORS);
    }
}

