import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * A program to determine if a grid of characters forms a valid pattern 
 * consisting of three equal-sized blocks of Red (R), Green (G), and Blue (B) 
 * arranged either by rows or by columns.
 */
public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }

        int rowCount = scanner.nextInt();
        int colCount = scanner.nextInt();
        scanner.nextLine(); // Consume the leftover newline

        char[][] grid = new char[rowCount][colCount];
        int redCount = 0;
        int greenCount = 0;
        int blueCount = 0;

        // Read the grid and count total occurrences of each color
        for (int i = 0; i < rowCount; i++) {
            String line = scanner.nextLine();
            grid[i] = line.toCharArray();
            for (char color : grid[i]) {
                if (color == 'R') redCount++;
                else if (color == 'G') greenCount++;
                else if (color == 'B') blueCount++;
            }
        }

        if (isPatternValid(grid, rowCount, colCount, redCount, greenCount, blueCount)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Checks if the grid satisfies the 3-color pattern requirement 
     * via either rows or columns.
     */
    private static boolean isPatternValid(char[][] grid, int rows, int cols, int r, int g, int b) {
        // Check row-based pattern
        List<Integer> rowGroups = getRowGroupSizes(grid, rows, cols);
        if (rowGroups != null && isValidGrouping(rowGroups, r, g, b)) {
            return true;
        }

        // Check column-based pattern
        List<Integer> colGroups = getColGroupSizes(grid, rows, cols);
        if (colGroups != null && isValidGrouping(colGroups, r, g, b)) {
            return true;
        }

        return false;
    }

    /**
     * Validates if every row is uniform and returns the sizes of color blocks.
     * @return List of block sizes, or null if any row is not uniform.
     */
    private static List<Integer> getRowGroupSizes(char[][] grid, int rows, int cols) {
        // 1. Verify row uniformity
        for (int i = 0; i < rows; i++) {
            char firstCharInRow = grid[i][0];
            for (int j = 1; j < cols; j++) {
                if (grid[i][j] != firstCharInRow) {
                    return null;
                }
            }
        }

        // 2. Group consecutive identical rows
        List<Integer> groupSizes = new ArrayList<>();
        int currentGroupSize = 1;
        for (int i = 1; i < rows; i++) {
            if (grid[i][0] == grid[i - 1][0]) {
                currentGroupSize++;
            } else {
                groupSizes.add(currentGroupSize);
                currentGroupSize = 1;
            }
        }
        groupSizes.add(currentGroupSize);
        return groupSizes;
    }

    /**
     * Validates if every column is uniform and returns the sizes of color blocks.
     * @return List of block sizes, or null if any column is not uniform.
     */
    private static List<Integer> getColGroupSizes(char[][] grid, int rows, int cols) {
        // 1. Verify column uniformity
        for (int j = 0; j < cols; j++) {
            char firstCharInCol = grid[0][j];
            for (int i = 1; i < rows; i++) {
                if (grid[i][j] != firstCharInCol) {
                    return null;
                }
            }
        }

        // 2. Group consecutive identical columns
        List<Integer> groupSizes = new ArrayList<>();
        int currentGroupSize = 1;
        for (int j = 1; j < cols; j++) {
            if (grid[0][j] == grid[0][j - 1]) {
                currentGroupSize++;
            } else {
                groupSizes.add(currentGroupSize);
                currentGroupSize = 1;
            }
        }
        groupSizes.add(currentGroupSize);
        return groupSizes;
    }

    /**
     * Validates if the color groups satisfy the problem constraints:
     * exactly 3 groups, all groups equal in size, and equal total color counts.
     */
    private static boolean isValidGrouping(List<Integer> groupSizes, int r, int g, int b) {
        if (groupSizes.size() != 3) {
            return false;
        }

        // Ensure all three blocks are of equal size
        boolean equalBlocks = groupSizes.get(0).equals(groupSizes.get(1)) 
                           && groupSizes.get(1).equals(groupSizes.get(2));

        // Ensure total counts for R, G, and B are balanced
        boolean balancedColors = (r == g && g == b);

        return equalBlocks && balancedColors;
    }
}

