/**
 * ColorStripChecker determines if a grid of colored cells (R, G, B)
 * is organized into three equal-sized, contiguous strips, either 
 * horizontally or vertically.
 */
public class ColorStripChecker {

    private static final char COLOR_RED = 'R';
    private static final char COLOR_GREEN = 'G';
    private static final char COLOR_BLUE = 'B';

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] grid = new char[rows][cols];

            int countR = 0, countG = 0, countB = 0;

            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                if (line == null) break;
                for (int j = 0; j < cols; j++) {
                    char color = line.charAt(j);
                    grid[i][j] = color;

                    // Count occurrences to ensure equal distribution
                    if (color == COLOR_RED) countR++;
                    else if (color == COLOR_GREEN) countG++;
                    else if (color == COLOR_BLUE) countB++;
                }
            }

            // Rule 1: For a valid strip configuration, all colors must have an equal count.
            if (countR != countG || countG != countB) {
                System.out.println("NO");
                return;
            }

            // Rule 2: Check if the grid forms valid horizontal or vertical stripes.
            if (isValidHorizontal(grid, rows, cols) || isValidVertical(grid, rows, cols)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }

        } catch (Exception e) {
            // In a production environment, use a proper logging framework.
        }
    }

    /**
     * Validates if the grid is composed of three horizontal strips of equal height.
     * 
     * @param grid The 2D character array representing the grid.
     * @param rows Total number of rows.
     * @param cols Total number of columns.
     * @return true if the grid forms three valid horizontal stripes.
     */
    private static boolean isValidHorizontal(char[][] grid, int rows, int cols) {
        if (rows % 3 != 0) {
            return false;
        }

        int stripHeight = rows / 3;
        char[] stripeColors = new char[3];

        for (int segment = 0; segment < 3; segment++) {
            int startRow = segment * stripHeight;
            char segmentColor = grid[startRow][0];
            stripeColors[segment] = segmentColor;

            // Verify that every cell in this row segment matches the color of the first cell.
            for (int i = startRow; i < startRow + stripHeight; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] != segmentColor) {
                        return false;
                    }
                }
            }
        }

        // Ensure the three identified stripes are composed of three distinct colors.
        return isDistinct(stripeColors);
    }

    /**
     * Validates if the grid is composed of three vertical strips of equal width.
     * 
     * @param grid The 2D character array representing the grid.
     * @param rows Total number of rows.
     * @param cols Total number of columns.
     * @return true if the grid forms three valid vertical stripes.
     */
    private static boolean isValidVertical(char[][] grid, int rows, int cols) {
        if (cols % 3 != 0) {
            return false;
        }

        int stripWidth = cols / 3;
        char[] stripeColors = new char[3];

        for (int segment = 0; segment < 3; segment++) {
            int startCol = segment * stripWidth;
            char segmentColor = grid[0][startCol];
            stripeColors[segment] = segmentColor;

            // Verify that every cell in this column segment matches the color of the first cell.
            for (int j = startCol; j < startCol + stripWidth; j++) {
                for (int i = 0; i < rows; i++) {
                    if (grid[i][j] != segmentColor) {
                        return false;
                    }
                }
            }
        }

        // Ensure the three identified stripes are composed of three distinct colors.
        return isDistinct(stripeColors);
    }

    /**
     * Helper to check if an array of 3 colors contains only unique elements.
     */
    private static boolean isDistinct(char[] colors) {
        return colors[0] != colors[1] && 
               colors[1] != colors[2] && 
               colors[0] != colors[2];
    }

    /**
     * FastReader utility for efficient input reading using BufferedReader.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            return next != null ? Integer.parseInt(next) : 0;
        }
    }
}

