/**
 * A refactored solution to solve the grid pattern problem.
 * The grid is considered valid if it follows a repeating block pattern 
 * (k R's, k G's, k B's in any order) either horizontally or vertically.
 */
public class Main {

    public static void main(String[] args) {
        FastReader in = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            String nInput = in.next();
            if (nInput == null) return;

            int n = Integer.parseInt(nInput);
            int m = in.nextInt();

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                String row = in.next();
                if (row != null) {
                    grid[i] = row.toCharArray();
                }
            }

            GridPatternSolver solver = new GridPatternSolver(grid);

            // The grid is valid if it satisfies either the row-wise or column-wise pattern.
            if (solver.hasValidRowPattern() || solver.hasValidColumnPattern()) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        } catch (Exception e) {
            // In a competitive programming context, errors are usually handled silently.
        } finally {
            out.close();
        }
    }

    /**
     * Encapsulates the logic for validating the grid against specific color patterns.
     */
    static class GridPatternSolver {
        private final char[][] grid;
        private final int rows;
        private final int cols;

        public GridPatternSolver(char[][] grid) {
            this.grid = grid;
            this.rows = grid.length;
            this.cols = (rows > 0) ? grid[0].length : 0;
        }

        /**
         * Checks if all rows are identical and the row follows a valid RGB cycle pattern.
         * (A pattern of k R's, k G's, and k B's in some order).
         */
        public boolean hasValidRowPattern() {
            if (rows == 0 || cols == 0) return false;

            char[] firstRow = grid[0];
            if (!isValidCycle(firstRow)) {
                return false;
            }

            for (int i = 1; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] != firstRow[j]) {
                        return false;
                    }
                }
            }
            return true;
        }

        /**
         * Checks if all columns are identical and the column follows a valid RGB cycle pattern.
         */
        public boolean hasValidColumnPattern() {
            if (rows == 0 || cols == 0) return false;

            char[] firstCol = new char[rows];
            for (int i = 0; i < rows; i++) {
                firstCol[i] = grid[i][0];
            }

            if (!isValidCycle(firstCol)) {
                return false;
            }

            for (int j = 1; j < cols; j++) {
                for (int i = 0; i < rows; i++) {
                    if (grid[i][j] != firstCol[i]) {
                        return false;
                    }
                }
            }
            return true;
        }

        /**
         * Validates if a sequence consists of three equal-sized blocks of distinct R, G, and B colors.
         * 
         * @param sequence The array of characters to validate.
         * @return true if the sequence is a valid periodic block pattern.
         */
        private boolean isValidCycle(char[] sequence) {
            int len = sequence.length;
            if (len == 0 || len % 3 != 0) {
                return false;
            }

            int k = len / 3;
            char color1 = sequence[0];
            char color2 = sequence[k];
            char color3 = sequence[2 * k];

            // 1. Ensure the three segment colors are valid (R, G, or B) and distinct.
            if (!isRGB(color1) || !isRGB(color2) || !isRGB(color3)) return false;
            if (color1 == color2 || color2 == color3 || color1 == color3) return false;

            // 2. Verify that each segment contains only its designated color.
            for (int i = 0; i < k; i++) {
                if (sequence[i] != color1) return false;
            }
            for (int i = k; i < 2 * k; i++) {
                if (sequence[i] != color2) return false;
            }
            for (int i = 2 * k; i < 3 * k; i++) {
                if (sequence[i] != color3) return false;
            }

            return true;
        }

        private boolean isRGB(char c) {
            return c == 'R' || c == 'G' || c == 'B';
        }
    }

    /**
     * Fast I/O utility for efficient reading of large inputs.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            return (next != null) ? Integer.parseInt(next) : 0;
        }
    }
}

