/**
 * A program that validates if a color grid (containing 'R', 'G', 'B')
 * is composed of three equal-sized, contiguous stripes of color,
 * either horizontally or vertically.
 */
public class ColorGridValidator {

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int numRows = scanner.nextInt();
            scanner.nextLine(); // Consume the leftover newline

            char[][] grid = new char[numRows][];
            for (int i = 0; i < numRows; i++) {
                grid[i] = scanner.nextLine().toCharArray();
            }

            if (isValidPattern(grid)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        } catch (Exception e) {
            // Catching exceptions to mirror the original program's 
            // behavior of outputting "NO" on unexpected input/errors.
            System.out.println("NO");
        }
    }

    /**
     * Determines if the provided grid meets the stripe pattern requirements.
     * 
     * @param grid The 2D array representing the color grid.
     * @return true if the grid is valid, false otherwise.
     */
    private static boolean isValidPattern(char[][] grid) {
        if (grid == null || grid.length == 0 || grid[0].length == 0) {
            return false;
        }

        // Rule 1: Total counts of R, G, and B must be equal and non-zero.
        if (!hasBalancedColors(grid)) {
            return false;
        }

        // Rule 2: The grid must follow either a horizontal or a vertical stripe pattern.
        return checkHorizontalStripes(grid) || checkVerticalStripes(grid);
    }

    /**
     * Validates that the total number of 'R', 'G', and 'B' cells are equal.
     */
    private static boolean hasBalancedColors(char[][] grid) {
        int rCount = 0, gCount = 0, bCount = 0;

        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == 'R') rCount++;
                else if (cell == 'G') gCount++;
                else if (cell == 'B') bCount++;
            }
        }

        return rCount > 0 && rCount == gCount && gCount == bCount;
    }

    /**
     * Checks if the grid is divided into three equal-sized horizontal monochromatic bands.
     */
    private static boolean checkHorizontalStripes(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;

        if (rows % 3 != 0) {
            return false;
        }

        int stripeSize = rows / 3;
        char lastColor = '\0';

        for (int stripeIdx = 0; stripeIdx < 3; stripeIdx++) {
            int startRow = stripeIdx * stripeSize;
            char currentColor = grid[startRow][0];

            // Stripes must be a different color than the previous stripe
            if (stripeIdx > 0 && currentColor == lastColor) {
                return false;
            }

            // Verify every cell in this horizontal block matches the current stripe color
            for (int r = startRow; r < startRow + stripeSize; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] != currentColor) {
                        return false;
                    }
                }
            }
            lastColor = currentColor;
        }
        return true;
    }

    /**
     * Checks if the grid is divided into three equal-sized vertical monochromatic bands.
     */
    private static boolean checkVerticalStripes(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;

        if (cols % 3 != 0) {
            return false;
        }

        int stripeSize = cols / 3;
        char lastColor = '\0';

        for (int stripeIdx = 0; stripeIdx < 3; stripeIdx++) {
            int startCol = stripeIdx * stripeSize;
            char currentColor = grid[0][startCol];

            // Stripes must be a different color than the previous stripe
            if (stripeIdx > 0 && currentColor == lastColor) {
                return false;
            }

            // Verify every cell in this vertical block matches the current stripe color
            for (int c = startCol; c < startCol + stripeSize; c++) {
                for (int r = 0; r < rows; r++) {
                    if (grid[r][c] != currentColor) {
                        return false;
                    }
                }
            }
            lastColor = currentColor;
        }
        return true;
    }
}

