 */
public class Solution {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        char[][] grid = readGrid(scanner, rows, cols);

        if (canSplitHorizontally(grid) || canSplitVertically(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Reads the grid input from the scanner.
     */
    private static char[][] readGrid(Scanner scanner, int rows, int cols) {
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String rowString = scanner.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = rowString.charAt(j);
            }
        }
        return grid;
    }

    /**
     * Checks if the grid can be divided into three equal horizontal bands
     * of distinct characters.
     */
    private static boolean canSplitHorizontally(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;

        if (rows % 3 != 0) {
            return false;
        }

        int bandSize = rows / 3;
        char charBand1 = grid[0][0];
        char charBand2 = grid[bandSize][0];
        char charBand3 = grid[2 * bandSize][0];

        // Bands must consist of three distinct characters
        if (charBand1 == charBand2 || charBand2 == charBand3 || charBand1 == charBand3) {
            return false;
        }

        return isUniform(grid, 0, bandSize - 1, 0, cols - 1, charBand1) &&
               isUniform(grid, bandSize, 2 * bandSize - 1, 0, cols - 1, charBand2) &&
               isUniform(grid, 2 * bandSize, rows - 1, 0, cols - 1, charBand3);
    }

    /**
     * Checks if the grid can be divided into three equal vertical bands
     * of distinct characters.
     */
    private static boolean canSplitVertically(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;

        if (cols % 3 != 0) {
            return false;
        }

        int bandSize = cols / 3;
        char charBand1 = grid[0][0];
        char charBand2 = grid[0][bandSize];
        char charBand3 = grid[0][2 * bandSize];

        // Bands must consist of three distinct characters
        if (charBand1 == charBand2 || charBand2 == charBand3 || charBand1 == charBand3) {
            return false;
        }

        return isUniform(grid, 0, rows - 1, 0, bandSize - 1, charBand1) &&
               isUniform(grid, 0, rows - 1, bandSize, 2 * bandSize - 1, charBand2) &&
               isUniform(grid, 0, rows - 1, 2 * bandSize, cols - 1, charBand3);
    }

    /**
     * Helper method to verify if all characters within a specific rectangular 
     * boundary of the grid match the target character.
     */
    private static boolean isUniform(char[][] grid, int rStart, int rEnd, int cStart, int cEnd, char target) {
        for (int i = rStart; i <= rEnd; i++) {
            for (int j = cStart; j <= cEnd; j++) {
                if (grid[i][j] != target) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.util.Scanner;

/**
 * A program to determine if a grid follows a specific "striped" pattern.
 * A pattern is valid if the grid is divided into 3 equal bands (either horizontal or vertical),
 * where each band is composed of a single, unique color/character.
 */
public class HelloWorld {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] data = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            data[i] = scanner.next().toCharArray();
        }

        Grid grid = new Grid(data, rows, cols);
        System.out.println(analyzePattern(grid) ? "YES" : "NO");

        scanner.close();
    }

    /**
     * Orchestrates the pattern analysis based on the input grid.
     * 
     * @param grid The grid to analyze.
     * @return true if the grid meets the stripe requirements.
     */
    private static boolean analyzePattern(Grid grid) {
        // Fast-fail if neither dimension can support 3 equal bands
        if (grid.rows % 3 != 0 && grid.cols % 3 != 0) {
            return false;
        }

        // The original logic branches based on whether the first row is uniform.
        // If the first row is uniform, we look for horizontal stripes.
        // Otherwise, we look for vertical stripes.
        if (grid.isRowUniform(0)) {
            return grid.rows % 3 == 0 && isHorizontalStriped(grid);
        } else {
            return grid.cols % 3 == 0 && isVerticalStriped(grid);
        }
    }

    /**
     * Checks if the grid consists of 3 horizontal bands of distinct colors.
     */
    private static boolean isHorizontalStriped(Grid grid) {
        int bandHeight = grid.rows / 3;
        char[] bandColors = new char[3];

        for (int b = 0; b < 3; b++) {
            int startRow = b * bandHeight;
            char color = grid.get(startRow, 0);
            bandColors[b] = color;

            // Ensure every cell in this horizontal band is the same color
            for (int r = startRow; r < startRow + bandHeight; r++) {
                if (!grid.isRowUniform(r, color)) {
                    return false;
                }
            }
        }

        return areColorsDistinct(bandColors);
    }

    /**
     * Checks if the grid consists of 3 vertical bands of distinct colors.
     */
    private static boolean isVerticalStriped(Grid grid) {
        int bandWidth = grid.cols / 3;
        char[] bandColors = new char[3];

        for (int b = 0; b < 3; b++) {
            int startCol = b * bandWidth;
            char color = grid.get(0, startCol);
            bandColors[b] = color;

            // Ensure every cell in this vertical band is the same color
            for (int c = startCol; c < startCol + bandWidth; c++) {
                if (!grid.isColumnUniform(c, color)) {
                    return false;
                }
            }
        }

        return areColorsDistinct(bandColors);
    }

    private static boolean areColorsDistinct(char[] colors) {
        return colors[0] != colors[1] && 
               colors[1] != colors[2] && 
               colors[0] != colors[2];
    }

    /**
     * Represents the grid data and provides geometric queries.
     */
    private static class Grid {
        private final char[][] cells;
        private final int rows;
        private final int cols;

        public Grid(char[][] cells, int rows, int cols) {
            this.cells = cells;
            this.rows = rows;
            this.cols = cols;
        }

        public char get(int r, int c) {
            return cells[r][c];
        }

        public boolean isRowUniform(int rowIndex) {
            return isRowUniform(rowIndex, cells[rowIndex][0]);
        }

        public boolean isRowUniform(int rowIndex, char expectedColor) {
            for (int c = 0; c < cols; c++) {
                if (cells[rowIndex][c] != expectedColor) {
                    return false;
                }
            }
            return true;
        }

        public boolean isColumnUniform(int colIndex, char expectedColor) {
            for (int r = 0; r < rows; r++) {
                if (cells[r][colIndex] != expectedColor) {
                    return false;
                }
            }
            return true;
        }
    }
}

