/**
 * Contains the logic to determine if the grid follows the required 3-band pattern.
 */
class GridPatternSolver {

    /**
     * Solves the grid problem by checking both horizontal and vertical patterns.
     * 
     * @param reader The input reader.
     * @return true if a valid 3-band pattern is found, false otherwise.
     * @throws IOException if an I/O error occurs.
     */
    public boolean solve(FastReader reader) throws IOException {
        int rows = reader.nextInt();
        int cols = reader.nextInt();
        char[][] grid = reader.nextCharTable(rows, cols);

        return checkHorizontalPattern(grid, rows, cols) || checkVerticalPattern(grid, rows, cols);
    }

    /**
     * Checks if the grid can be divided into 3 horizontal bands of uniform, distinct colors.
     */
    private boolean checkHorizontalPattern(char[][] grid, int rows, int cols) {
        if (rows % 3 != 0) {
            return false;
        }

        int bandSize = rows / 3;
        char[] colors = {
            grid[0][0],
            grid[bandSize][0],
            grid[2 * bandSize][0]
        };

        if (!hasThreeDistinctColors(colors)) {
            return false;
        }

        for (int i = 0; i < 3; i++) {
            if (!isBandUniform(grid, i * bandSize, (i + 1) * bandSize, 0, cols, colors[i])) {
                return false;
            }
        }

        return true;
    }

    /**
     * Checks if the grid can be divided into 3 vertical bands of uniform, distinct colors.
     */
    private boolean checkVerticalPattern(char[][] grid, int rows, int cols) {
        if (cols % 3 != 0) {
            return false;
        }

        int bandSize = cols / 3;
        char[] colors = {
            grid[0][0],
            grid[0][bandSize],
            grid[0][2 * bandSize]
        };

        if (!hasThreeDistinctColors(colors)) {
            return false;
        }

        for (int i = 0; i < 3; i++) {
            if (!isBandUniform(grid, 0, rows, i * bandSize, (i + 1) * bandSize, colors[i])) {
                return false;
            }
        }

        return true;
    }

    /**
     * Verifies if all cells within a specified rectangular sub-section of the grid match a target color.
     */
    private boolean isBandUniform(char[][] grid, int rowStart, int rowEnd, int colStart, int colEnd, char targetColor) {
        for (int r = rowStart; r < rowEnd; r++) {
            for (int c = colStart; c < colEnd; c++) {
                if (grid[r][c] != targetColor) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Checks if the provided array contains three unique characters.
     */
    private boolean hasThreeDistinctColors(char[] colors) {
        return colors[0] != colors[1] && colors[1] != colors[2] && colors[0] != colors[2];
    }
}

/**
 * A utility class for fast I/O operations.
 */
class FastReader {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    public FastReader(InputStream in) {
        this.reader = new BufferedReader(new InputStreamReader(in));
    }

    public String next() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            String line = reader.readLine();
            if (line == null) return null;
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    public int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    public char[][] nextCharTable(int rows, int columns) throws IOException {
        char[][] table = new char[rows][columns];
        for (int i = 0; i < rows; i++) {
            String line = next();
            if (line == null) throw new IOException("Unexpected end of input");
            table[i] = line.toCharArray();

            if (table[i].length != columns) {
                throw new IllegalArgumentException("Row " + i + " does not match expected column count.");
            }
        }
        return table;
    }
}

