/**
 * A refactored solution to determine if a grid can be partitioned into three 
 * equal-sized stripes (either horizontal or vertical) of distinct colors.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            GridPatternSolver solver = new GridPatternSolver(reader);
            solver.solve(writer);
        } finally {
            writer.close();
        }
    }

    /**
     * Handles the core logic of analyzing the grid patterns.
     */
    static class GridPatternSolver {
        private final FastReader reader;

        public GridPatternSolver(FastReader reader) {
            this.reader = reader;
        }

        /**
         * Orchestrates the grid reading and pattern checking.
         * 
         * @param out The PrintWriter to output the result.
         */
        public void solve(PrintWriter out) {
            int rowCount = reader.nextInt();
            int colCount = reader.nextInt();
            char[][] grid = new char[rowCount][];

            for (int i = 0; i < rowCount; i++) {
                grid[i] = reader.next().toCharArray();
            }

            if (hasValidStripes(rowCount, colCount, grid)) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        }

        /**
         * Checks both vertical and horizontal stripe patterns.
         */
        private boolean hasValidStripes(int rows, int cols, char[][] grid) {
            return checkHorizontalStripes(rows, cols, grid) || 
                   checkVerticalStripes(rows, cols, grid);
        }

        /**
         * Checks if the grid can be split into 3 horizontal stripes of different colors.
         */
        private boolean checkHorizontalStripes(int rows, int cols, char[][] grid) {
            if (rows % 3 != 0) {
                return false;
            }

            int stripeHeight = rows / 3;
            char[] stripeColors = new char[3];

            // Determine potential colors from the first cell of each stripe
            stripeColors[0] = grid[0][0];
            stripeColors[1] = grid[stripeHeight][0];
            stripeColors[2] = grid[2 * stripeHeight][0];

            if (!areColorsDistinct(stripeColors)) {
                return false;
            }

            for (int i = 0; i < 3; i++) {
                int startRow = i * stripeHeight;
                int endRow = (i + 1) * stripeHeight;
                if (!isRegionUniform(grid, startRow, endRow, 0, cols, stripeColors[i])) {
                    return false;
                }
            }
            return true;
        }

        /**
         * Checks if the grid can be split into 3 vertical stripes of different colors.
         */
        private boolean checkVerticalStripes(int rows, int cols, char[][] grid) {
            if (cols % 3 != 0) {
                return false;
            }

            int stripeWidth = cols / 3;
            char[] stripeColors = new char[3];

            // Determine potential colors from the first cell of each stripe
            stripeColors[0] = grid[0][0];
            stripeColors[1] = grid[0][stripeWidth];
            stripeColors[2] = grid[0][2 * stripeWidth];

            if (!areColorsDistinct(stripeColors)) {
                return false;
            }

            for (int i = 0; i < 3; i++) {
                int startCol = i * stripeWidth;
                int endCol = (i + 1) * stripeWidth;
                if (!isRegionUniform(grid, 0, rows, startCol, endCol, stripeColors[i])) {
                    return false;
                }
            }
            return true;
        }

        /**
         * Validates if a specific rectangular region in the grid is composed of a single color.
         */
        private boolean isRegionUniform(char[][] grid, int rStart, int rEnd, int cStart, int cEnd, char color) {
            for (int r = rStart; r < rEnd; r++) {
                for (int c = cStart; c < cEnd; c++) {
                    if (grid[r][c] != color) {
                        return false;
                    }
                }
            }
            return true;
        }

        /**
         * Checks if all provided colors in an array are unique.
         */
        private boolean areColorsDistinct(char[] colors) {
            return colors[0] != colors[1] && 
                   colors[1] != colors[2] && 
                   colors[0] != colors[2];
        }
    }

    /**
     * Utility class for fast input reading.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

/**
 * A program to determine if a given grid of characters represents 
 * a "Flag of Berland" (either 3 horizontal or 3 vertical stripes of distinct colors).
 */
public class FlagofBerland {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int rowCount = scanner.nextInt();

        if (!scanner.hasNextInt()) return;
        int colCount = scanner.nextInt();

        char[][] grid = readGrid(scanner, rowCount, colCount);
        scanner.close();

        if (isValidFlag(grid, rowCount, colCount)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Reads the grid input into a 2D char array.
     */
    private static char[][] readGrid(Scanner scanner, int rows, int cols) {
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
            }
        }
        return grid;
    }

    /**
     * Checks if the grid matches either a horizontal or vertical flag pattern.
     */
    private static boolean isValidFlag(char[][] grid, int rows, int cols) {
        return isHorizontalPattern(grid, rows, cols) || isVerticalPattern(grid, rows, cols);
    }

    /**
     * Validates if the flag consists of 3 equal-sized horizontal color bands.
     */
    private static boolean isHorizontalPattern(char[][] grid, int rows, int cols) {
        if (rows % 3 != 0) {
            return false;
        }

        int stripeSize = rows / 3;
        char color1 = grid[0][0];
        char color2 = grid[stripeSize][0];
        char color3 = grid[2 * stripeSize][0];

        // Check if the three colors are distinct
        if (color1 == color2 || color1 == color3 || color2 == color3) {
            return false;
        }

        // Verify every cell in the grid belongs to the correct stripe
        for (int r = 0; r < rows; r++) {
            char expectedColor = getExpectedColor(r, stripeSize, color1, color2, color3);
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] != expectedColor) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Validates if the flag consists of 3 equal-sized vertical color bands.
     */
    private static boolean isVerticalPattern(char[][] grid, int rows, int cols) {
        if (cols % 3 != 0) {
            return false;
        }

        int stripeSize = cols / 3;
        char color1 = grid[0][0];
        char color2 = grid[0][stripeSize];
        char color3 = grid[0][2 * stripeSize];

        // Check if the three colors are distinct
        if (color1 == color2 || color1 == color3 || color2 == color3) {
            return false;
        }

        // Verify every cell in the grid belongs to the correct stripe
        for (int c = 0; c < cols; c++) {
            char expectedColor = getExpectedColor(c, stripeSize, color1, color2, color3);
            for (int r = 0; r < rows; r++) {
                if (grid[r][c] != expectedColor) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Helper to determine which color should be present based on the current index.
     */
    private static char getExpectedColor(int index, int stripeSize, char c1, char c2, char c3) {
        int stripeIndex = index / stripeSize;
        switch (stripeIndex) {
            case 0: return c1;
            case 1: return c2;
            case 2: return c3;
            default: return ' '; // Should not be reachable
        }
    }
}

import java.util.*;

/**
 * A utility to check if a grid of colored cells (R, G, B) follows a specific 
 * pattern: either all rows or all columns must be uniform in color, 
 * and the counts of Red, Green, and Blue lines must be equal.
 */
public class PatternChecker {

    private static final char RED = 'R';
    private static final char GREEN = 'G';
    private static final char BLUE = 'B';

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;

            int rowCount = scanner.nextInt();
            int colCount = scanner.nextInt();
            char[][] grid = new char[rowCount][colCount];

            for (int i = 0; i < rowCount; i++) {
                grid[i] = scanner.next().toCharArray();
            }

            if (isPatternValid(grid, rowCount, colCount)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /**
     * Checks if the grid satisfies the pattern in either row-major or column-major orientation.
     */
    private static boolean isPatternValid(char[][] grid, int rows, int cols) {
        return checkOrientation(grid, rows, cols, true) || 
               checkOrientation(grid, rows, cols, false);
    }

    /**
     * Validates the grid based on the provided orientation.
     * 
     * @param rowWise If true, checks rows; if false, checks columns.
     * @return true if the orientation satisfies the pattern requirements.
     */
    private static boolean checkOrientation(char[][] grid, int rows, int cols, boolean rowWise) {
        int numLines = rowWise ? rows : cols;
        int lineLength = rowWise ? cols : rows;

        Map<Character, Integer> colorCounts = new HashMap<>();
        Set<Character> seenColors = new HashSet<>();
        char lastColor = '\0';

        for (int i = 0; i < numLines; i++) {
            char lineColor = getUniformLineColor(grid, i, rowWise, lineLength);

            // If a line is not uniform, this orientation is invalid.
            if (lineColor == '\0') {
                return false;
            }

            // We only process R, G, and B colors for the equality requirement.
            if (isTargetColor(lineColor)) {
                // Check for contiguous blocks: if we see a color again, 
                // it must be the same as the previous color seen.
                if (seenColors.contains(lineColor) && lineColor != lastColor) {
                    return false;
                }

                seenColors.add(lineColor);
                colorCounts.put(lineColor, colorCounts.getOrDefault(lineColor, 0) + 1);
                lastColor = lineColor;
            }
        }

        return hasEqualColorCounts(colorCounts);
    }

    /**
     * Determines if a line (row or column) is uniform and returns its color.
     * 
     * @return The character if uniform, or '\0' if the line is not uniform.
     */
    private static char getUniformLineColor(char[][] grid, int index, boolean rowWise, int length) {
        char firstChar = rowWise ? grid[index][0] : grid[0][index];
        for (int i = 0; i < length; i++) {
            char currentChar = rowWise ? grid[index][i] : grid[i][index];
            if (currentChar != firstChar) {
                return '\0';
            }
        }
        return firstChar;
    }

    private static boolean isTargetColor(char c) {
        return c == RED || c == GREEN || c == BLUE;
    }

    /**
     * Ensures that the counts of Red, Green, and Blue are all identical.
     */
    private static boolean hasEqualColorCounts(Map<Character, Integer> counts) {
        int r = counts.getOrDefault(RED, 0);
        int g = counts.getOrDefault(GREEN, 0);
        int b = counts.getOrDefault(BLUE, 0);
        return r == g && r == b;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * GridPatternMatcher encapsulates the logic to determine if a 2D character grid
 * can be partitioned into three distinct, equal-sized stripes (either horizontally
 * or vertically).
 */
class GridPatternMatcher {
    private final char[][] grid;
    private final int rows;
    private final int cols;

    public GridPatternMatcher(char[][] grid, int rows, int cols) {
        this.grid = grid;
        this.rows = rows;
        this.cols = cols;
    }

    /**
     * Checks if the grid consists of three equal-height horizontal stripes,
     * where each stripe is composed of a single character, and all three
     * characters are distinct.
     *
     * @return true if the horizontal stripe pattern is found, false otherwise.
     */
    public boolean hasHorizontalStripes() {
        if (rows % 3 != 0) {
            return false;
        }

        int stripeHeight = rows / 3;
        char[] stripeChars = new char[3];

        for (int s = 0; s < 3; s++) {
            int startRow = s * stripeHeight;
            char expectedChar = grid[startRow][0];
            stripeChars[s] = expectedChar;

            for (int i = startRow; i < startRow + stripeHeight; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] != expectedChar) {
                        return false;
                    }
                }
            }
        }

        return areCharsDistinct(stripeChars);
    }

    /**
     * Checks if the grid consists of three equal-width vertical stripes,
     * where each stripe is composed of a single character, and all three
     * characters are distinct.
     *
     * @return true if the vertical stripe pattern is found, false otherwise.
     */
    public boolean hasVerticalStripes() {
        if (cols % 3 != 0) {
            return false;
        }

        int stripeWidth = cols / 3;
        char[] stripeChars = new char[3];

        for (int s = 0; s < 3; s++) {
            int startCol = s * stripeWidth;
            char expectedChar = grid[0][startCol];
            stripeChars[s] = expectedChar;

            for (int i = 0; i < rows; i++) {
                for (int j = startCol; j < startCol + stripeWidth; j++) {
                    if (grid[i][j] != expectedChar) {
                        return false;
                    }
                }
            }
        }

        return areCharsDistinct(stripeChars);
    }

    /**
     * Verifies that the three characters used for the stripes are unique.
     */
    private boolean areCharsDistinct(char[] chars) {
        return chars[0] != chars[1] && 
               chars[1] != chars[2] && 
               chars[0] != chars[2];
    }
}

/**
 * Main entry point for the grid pattern validation program.
