import java.util.Scanner;

/**
 * A utility to validate if a grid follows a specific color pattern.
 * A pattern is valid if it consists of three contiguous blocks of equal counts 
 * of 'R', 'G', and 'B' characters, either in rows or in columns.
 */
public class GridPatternValidator {

    private static final char COLOR_R = 'R';
    private static final char COLOR_G = 'G';
    private static final char COLOR_B = 'B';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }

        int height = scanner.nextInt();
        int width = scanner.nextInt();
        char[][] grid = new char[height][width];

        for (int i = 0; i < height; i++) {
            String rowString = scanner.next();
            for (int j = 0; j < width; j++) {
                grid[i][j] = rowString.charAt(j);
            }
        }

        if (isPatternSatisfied(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Checks if the grid satisfies the color pattern requirement either row-wise or column-wise.
     * 
     * @param grid The 2D character array representing the grid.
     * @return true if the pattern is satisfied in either orientation.
     */
    private static boolean isPatternSatisfied(char[][] grid) {
        return validateOrientation(grid, true) || validateOrientation(grid, false);
    }

    /**
     * Validates the grid in a specific orientation.
     * 
     * @param grid The 2D character array.
     * @param checkRows If true, validates rows. If false, validates columns.
     * @return true if the orientation is uniform and its sequence follows the pattern.
     */
    private static boolean validateOrientation(char[][] grid, boolean checkRows) {
        int rows = grid.length;
        int cols = grid[0].length;

        if (checkRows) {
            char[] sequence = new char[rows];
            for (int i = 0; i < rows; i++) {
                char rowChar = grid[i][0];
                if (!isRowUniform(grid[i], rowChar)) {
                    return false;
                }
                sequence[i] = rowChar;
            }
            return isSequencePatternValid(sequence);
        } else {
            char[] sequence = new char[cols];
            for (int j = 0; j < cols; j++) {
                char colChar = grid[0][j];
                if (!isColumnUniform(grid, j, colChar)) {
                    return false;
                }
                sequence[j] = colChar;
            }
            return isSequencePatternValid(sequence);
        }
    }

    /**
     * Checks if all elements in a row are identical to the expected character.
     */
    private static boolean isRowUniform(char[] row, char expected) {
        for (char c : row) {
            if (c != expected) return false;
        }
        return true;
    }

    /**
     * Checks if all elements in a column are identical to the expected character.
     */
    private static boolean isColumnUniform(char[][] grid, int colIndex, char expected) {
        for (int i = 0; i < grid.length; i++) {
            if (grid[i][colIndex] != expected) return false;
        }
        return true;
    }

    /**
     * Validates if the sequence of characters contains exactly three 
     * contiguous blocks of equal counts of 'R', 'G', and 'B'.
     * 
     * @param sequence The array of representative characters for each line.
     * @return true if the sequence follows the required RGB pattern.
     */
    private static boolean isSequencePatternValid(char[] sequence) {
        int redCount = 0, greenCount = 0, blueCount = 0;
        int contiguousBlocks = 1;

        for (int i = 0; i < sequence.length; i++) {
            char currentColor = sequence[i];

            // Increment counts
            if (currentColor == COLOR_R) redCount++;
            else if (currentColor == COLOR_G) greenCount++;
            else if (currentColor == COLOR_B) blueCount++;
            else return false; // Invalid character detected

            // Count transitions between different colors
            if (i > 0 && currentColor != sequence[i - 1]) {
                contiguousBlocks++;
            }
        }

        // Requirement: Exactly 3 blocks, all colors present, and all counts equal
        return contiguousBlocks == 3 &&
               redCount > 0 &&
               redCount == greenCount &&
               greenCount == blueCount;
    }
}

import java.util.Scanner;

/**
 * FlagOfBerland checks if a given grid of colors forms a valid Berland flag.
 * A valid flag consists of three equal-sized stripes of 'R', 'G', and 'B' 
 * in any order, either arranged horizontally or vertically.
 */
public class FlagOfBerland {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        char[][] grid = new char[rows][cols];

        // Read the grid row by row
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            grid[i] = line.toCharArray();
        }

        if (isFlagValid(rows, cols, grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Determines if the grid meets the criteria for a valid flag.
     */
    private static boolean isFlagValid(int rows, int cols, char[][] grid) {
        return checkHorizontalStripes(rows, cols, grid) || 
               checkVerticalStripes(rows, cols, grid);
    }

    /**
     * Validates if the grid contains three equal-sized horizontal stripes.
     */
    private static boolean checkHorizontalStripes(int rows, int cols, char[][] grid) {
        if (rows % 3 != 0) {
            return false;
        }

        int stripeHeight = rows / 3;
        char[] stripeColors = new char[3];

        for (int i = 0; i < 3; i++) {
            int startRow = i * stripeHeight;
            int endRow = (i + 1) * stripeHeight - 1;

            // Identify the expected color for this stripe from its first cell
            char color = grid[startRow][0];
            stripeColors[i] = color;

            // Ensure every cell in this horizontal stripe matches the color
            if (!isRegionUniform(grid, startRow, endRow, 0, cols - 1, color)) {
                return false;
            }
        }

        return containsRgbColors(stripeColors);
    }

    /**
     * Validates if the grid contains three equal-sized vertical stripes.
     */
    private static boolean checkVerticalStripes(int rows, int cols, char[][] grid) {
        if (cols % 3 != 0) {
            return false;
        }

        int stripeWidth = cols / 3;
        char[] stripeColors = new char[3];

        for (int j = 0; j < 3; j++) {
            int startCol = j * stripeWidth;
            int endCol = (j + 1) * stripeWidth - 1;

            // Identify the expected color for this stripe from its first cell
            char color = grid[0][startCol];
            stripeColors[j] = color;

            // Ensure every cell in this vertical stripe matches the color
            if (!isRegionUniform(grid, 0, rows - 1, startCol, endCol, color)) {
                return false;
            }
        }

        return containsRgbColors(stripeColors);
    }

    /**
     * Checks if all cells within a specific rectangular boundary are the same color.
     */
    private static boolean isRegionUniform(char[][] grid, int rStart, int rEnd, int cStart, int cEnd, char color) {
        for (int r = rStart; r <= rEnd; r++) {
            for (int c = cStart; c <= cEnd; c++) {
                if (grid[r][c] != color) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Verifies that the provided color set contains exactly 'R', 'G', and 'B'.
     */
    private static boolean containsRgbColors(char[] colors) {
        boolean hasR = false;
        boolean hasG = false;
        boolean hasB = false;

        for (char c : colors) {
            if (c == 'R') hasR = true;
            else if (c == 'G') hasG = true;
            else if (c == 'B') hasB = true;
            else return false; // Invalid color found
        }

        return hasR && hasG && hasB;
    }
}

