/**
 * Contains logic to analyze the grid for specific banding patterns.
 */
class GridSolver {

    /**
     * Determines if the grid can be partitioned into three uniform bands
     * either horizontally or vertically.
     *
     * @param grid The character grid to analyze.
     * @param rows Number of rows in the grid.
     * @param cols Number of columns in the grid.
     * @return true if the grid meets the partitioning criteria, false otherwise.
     */
    public boolean canBePartitioned(char[][] grid, int rows, int cols) {
        return checkHorizontalBands(grid, rows, cols) || 
               checkVerticalBands(grid, rows, cols);
    }

    /**
     * Checks if the grid can be split into 3 horizontal bands of equal height,
     * where each band is uniform and all three bands have different characters.
     */
    private boolean checkHorizontalBands(char[][] grid, int rows, int cols) {
        if (rows % 3 != 0) {
            return false;
        }

        int bandHeight = rows / 3;
        char band1Char = grid[0][0];
        char band2Char = grid[bandHeight][0];
        char band3Char = grid[2 * bandHeight][0];

        // Rule: All three bands must consist of distinct characters
        if (band1Char == band2Char || band2Char == band3Char || band1Char == band3Char) {
            return false;
        }

        return isBandUniform(grid, 0, bandHeight - 1, 0, cols - 1, band1Char) &&
               isBandUniform(grid, bandHeight, 2 * bandHeight - 1, 0, cols - 1, band2Char) &&
               isBandUniform(grid, 2 * bandHeight, rows - 1, 0, cols - 1, band3Char);
    }

    /**
     * Checks if the grid can be split into 3 vertical bands of equal width,
     * where each band is uniform and all three bands have different characters.
     */
    private boolean checkVerticalBands(char[][] grid, int rows, int cols) {
        if (cols % 3 != 0) {
            return false;
        }

        int bandWidth = cols / 3;
        char band1Char = grid[0][0];
        char band2Char = grid[0][bandWidth];
        char band3Char = grid[0][2 * bandWidth];

        // Rule: All three bands must consist of distinct characters
        if (band1Char == band2Char || band2Char == band3Char || band1Char == band3Char) {
            return false;
        }

        return isBandUniform(grid, 0, rows - 1, 0, bandWidth - 1, band1Char) &&
               isBandUniform(grid, 0, rows - 1, bandWidth, 2 * bandWidth - 1, band2Char) &&
               isBandUniform(grid, 0, rows - 1, 2 * bandWidth, cols - 1, band3Char);
    }

    /**
     * Helper method to verify if a specific rectangular sub-section of the grid
     * is composed entirely of a single character.
     */
    private boolean isBandUniform(char[][] grid, int startRow, int endRow, int startCol, int endCol, char expectedChar) {
        for (int i = startRow; i <= endRow; i++) {
            for (int j = startCol; j <= endCol; j++) {
                if (grid[i][j] != expectedChar) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.util.*;

/**
 * A utility to validate if a given grid represents a valid Berland Flag.
 * A valid flag consists of three equal-sized stripes (either horizontal or vertical)
 * of three different colors: Red (R), Green (G), and Blue (B).
 */
public class FlagofBerland {

    private static final char RED = 'R';
    private static final char GREEN = 'G';
    private static final char BLUE = 'B';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            grid[i] = line.toCharArray();
        }

        if (isValidFlag(grid, rows, cols)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Orchestrates the validation of the flag.
     */
    private static boolean isValidFlag(char[][] grid, int rows, int cols) {
        return checkHorizontalStripes(grid, rows, cols) || 
               checkVerticalStripes(grid, rows, cols);
    }

    /**
     * Checks if the flag is composed of three equal horizontal stripes.
     */
    private static boolean checkHorizontalStripes(char[][] grid, int rows, int cols) {
        if (rows % 3 != 0) {
            return false;
        }

        int stripeHeight = rows / 3;
        char[] colors = new char[3];

        for (int i = 0; i < 3; i++) {
            int startRow = i * stripeHeight;
            int endRow = (i + 1) * stripeHeight - 1;
            colors[i] = getUniformColor(grid, startRow, endRow, 0, cols - 1);

            if (colors[i] == '\0') {
                return false;
            }
        }

        return hasThreeDistinctBerlandColors(colors);
    }

    /**
     * Checks if the flag is composed of three equal vertical stripes.
     */
    private static boolean checkVerticalStripes(char[][] grid, int rows, int cols) {
        if (cols % 3 != 0) {
            return false;
        }

        int stripeWidth = cols / 3;
        char[] colors = new char[3];

        for (int i = 0; i < 3; i++) {
            int startCol = i * stripeWidth;
            int endCol = (i + 1) * stripeWidth - 1;
            colors[i] = getUniformColor(grid, 0, rows - 1, startCol, endCol);

            if (colors[i] == '\0') {
                return false;
            }
        }

        return hasThreeDistinctBerlandColors(colors);
    }

    /**
     * Validates if a specific rectangular region in the grid consists of 
     * a single, valid Berland color.
     * 
     * @return The color character if valid, otherwise '\0'.
     */
    private static char getUniformColor(char[][] grid, int rStart, int rEnd, int cStart, int cEnd) {
        char color = grid[rStart][cStart];

        // Check if the starting color is one of the valid Berland colors
        if (color != RED && color != GREEN && color != BLUE) {
            return '\0';
        }

        // Ensure every cell in the specified range matches the starting color
        for (int r = rStart; r <= rEnd; r++) {
            for (int c = cStart; c <= cEnd; c++) {
                if (grid[r][c] != color) {
                    return '\0';
                }
            }
        }

        return color;
    }

    /**
     * Checks if the provided array of colors contains exactly 'R', 'G', and 'B'.
     */
    private static boolean hasThreeDistinctBerlandColors(char[] colors) {
        Set<Character> colorSet = new HashSet<>();
        for (char c : colors) {
            colorSet.add(c);
        }
        // If the set size is 3 and we already validated that individual colors are R, G, or B,
        // then the set must contain exactly {R, G, B}.
        return colorSet.size() == 3;
    }
}

import java.util.*;
import java.io.*;

/**
 * A utility to validate if a grid is composed of three identical, 
 * non-overlapping rectangular regions of distinct colors.
 */
public class ColorGridValidator {

    private enum Color {
        RED('R'), BLUE('B'), GREEN('G');

        final char symbol;

        Color(char symbol) {
            this.symbol = symbol;
        }

        /**
         * Maps a character to its corresponding Color enum.
         * Defaults to GREEN for any character that isn't 'R' or 'B'.
         */
        static Color fromChar(char c) {
            if (c == 'R') return RED;
            if (c == 'B') return BLUE;
            return GREEN;
        }
    }

    /**
     * Represents the boundaries of a rectangular area within the grid.
     */
    private static class BoundingBox {
        int minRow = Integer.MAX_VALUE;
        int maxRow = Integer.MIN_VALUE;
        int minCol = Integer.MAX_VALUE;
        int maxCol = Integer.MIN_VALUE;
        boolean exists = false;

        void update(int row, int col) {
            minRow = Math.min(minRow, row);
            maxRow = Math.max(maxRow, row);
            minCol = Math.min(minCol, col);
            maxCol = Math.max(maxCol, col);
            exists = true;
        }

        int getHeight() {
            return exists ? (maxRow - minRow + 1) : 0;
        }

        int getWidth() {
            return exists ? (maxCol - minCol + 1) : 0;
        }
    }

    public static void main(String[] args) {
        try {
            run();
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    private static void run() throws IOException {
        FastReader sc = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        // Read grid dimensions
        String firstLine = sc.next();
        if (firstLine == null) return;

        int rows = Integer.parseInt(firstLine);
        int cols = sc.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = sc.next().toCharArray();
        }

        // 1. Find bounding boxes for all three colors
        BoundingBox[] colorBoxes = findBoundingBoxes(grid, rows, cols);

        // 2. Validate the grid based on the found boxes
        if (isValidPattern(colorBoxes, grid)) {
            out.println("YES");
        } else {
            out.println("NO");
        }

        out.flush();
        out.close();
    }

    private static BoundingBox[] findBoundingBoxes(char[][] grid, int rows, int cols) {
        BoundingBox[] boxes = new BoundingBox[3];
        for (int i = 0; i < 3; i++) {
            boxes[i] = new BoundingBox();
        }

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                Color color = Color.fromChar(grid[r][c]);
                boxes[color.ordinal()].update(r, c);
            }
        }
        return boxes;
    }

    private static boolean isValidPattern(BoundingBox[] boxes, char[][] grid) {
        // Ensure all colors were actually found in the grid
        for (BoundingBox box : boxes) {
            if (!box.exists) return false;
        }

        // Ensure all bounding boxes have the same dimensions
        int targetHeight = boxes[0].getHeight();
        int targetWidth = boxes[0].getWidth();

        for (int i = 1; i < 3; i++) {
            if (boxes[i].getHeight() != targetHeight || boxes[i].getWidth() != targetWidth) {
                return false;
            }
        }

        // Ensure the interior of every bounding box contains only its assigned color
        for (int i = 0; i < 3; i++) {
            char expectedColor = Color.values()[i].symbol;
            if (!isBoxFilledWithColor(boxes[i], grid, expectedColor)) {
                return false;
            }
        }

        return true;
    }

    private static boolean isBoxFilledWithColor(BoundingBox box, char[][] grid, char color) {
        for (int r = box.minRow; r <= box.maxRow; r++) {
            for (int c = box.minCol; c <= box.maxCol; c++) {
                if (grid[r][c] != color) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Efficient input reader for large datasets.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

