     * Checks if the grid matches either the horizontal or vertical stripe pattern.
     * 
     * @param grid The 2D grid of characters.
     * @param rows Number of rows in the grid.
     * @param cols Number of columns in the grid.
     * @return true if a valid pattern is found, false otherwise.
     */
    private static boolean hasValidPattern(String[] grid, int rows, int cols) {
        return checkHorizontalStripes(grid, rows, cols) || checkVerticalStripes(grid, rows, cols);
    }

    /**
     * Validates if the grid is composed of three equal horizontal blocks,
     * where each block consists of a single unique color.
     */
    private static boolean checkHorizontalStripes(String[] grid, int rows, int cols) {
        if (rows % 3 != 0) {
            return false;
        }

        int segmentHeight = rows / 3;
        char[] segmentColors = new char[3];

        for (int i = 0; i < 3; i++) {
            int startRow = i * segmentHeight;
            char color = grid[startRow].charAt(0);
            segmentColors[i] = color;

            // Check if the entire segment is uniform with the detected color
            if (!isSegmentUniform(grid, startRow, startRow + segmentHeight, 0, cols, color)) {
                return false;
            }
        }

        return areColorsDistinct(segmentColors);
    }

    /**
     * Validates if the grid is composed of three equal vertical blocks,
     * where each block consists of a single unique color.
     */
    private static boolean checkVerticalStripes(String[] grid, int rows, int cols) {
        if (cols % 3 != 0) {
            return false;
        }

        int segmentWidth = cols / 3;
        char[] segmentColors = new char[3];

        for (int i = 0; i < 3; i++) {
            int startCol = i * segmentWidth;
            char color = grid[0].charAt(startCol);
            segmentColors[i] = color;

            // Check if the entire segment is uniform with the detected color
            if (!isSegmentUniform(grid, 0, rows, startCol, startCol + segmentWidth, color)) {
                return false;
            }
        }

        return areColorsDistinct(segmentColors);
    }

    /**
     * Verifies if all cells within a specified rectangular region 
     * of the grid match the target color.
     *
     * @param grid The 2D grid.
     * @param startRow Starting row index (inclusive).
     * @param endRow Ending row index (exclusive).
     * @param startCol Starting column index (inclusive).
     * @param endCol Ending column index (exclusive).
     * @param targetColor The color to validate against.
     * @return true if the region is uniform, false otherwise.
     */
    private static boolean isSegmentUniform(String[] grid, int startRow, int endRow, 
                                            int startCol, int endCol, char targetColor) {
        for (int r = startRow; r < endRow; r++) {
            for (int c = startCol; c < endCol; c++) {
                if (grid[r].charAt(c) != targetColor) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Ensures that the three segments identified have three different colors.
     * 
     * @param colors An array of 3 characters.
     * @return true if all colors are unique.
     */
    private static boolean areColorsDistinct(char[] colors) {
        return colors[0] != colors[1] && 
               colors[1] != colors[2] && 
               colors[0] != colors[2];
    }
}

import java.io.*;
import java.util.*;

/**
 * GridPatternChecker verifies if a grid satisfies a specific pattern:
 * 1. Each row (or column) consists of a single color.
 * 2. The total number of rows (or columns) for each color ('R', 'G', 'B') is equal.
 * 3. Colors appear in contiguous blocks (e.g., all Red rows, then all Green, then all Blue).
 */
public class GridPatternChecker {

    public static void main(String[] args) {
        FastReader sc = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            String nStr = sc.next();
            if (nStr == null) return;
            int n = Integer.parseInt(nStr);
            int m = sc.nextInt();

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                grid[i] = sc.next().toCharArray();
            }

            // Check if the pattern holds for rows OR for columns (transposed grid)
            if (isPatternValid(grid) || isPatternValid(transpose(grid))) {
                out.println("YES");
            } else {
                out.println("NO");
            }

        } catch (Exception e) {
            System.err.println("An error occurred: " + e.getMessage());
        } finally {
            out.close();
        }
    }

    /**
     * Validates the grid pattern.
     * 
     * @param grid The 2D character array to check.
     * @return true if the pattern is valid, false otherwise.
     */
    private static boolean isPatternValid(char[][] grid) {
        if (grid == null || grid.length == 0) return false;

        int rows = grid.length;
        int cols = grid[0].length;

        int countR = 0, countG = 0, countB = 0;
        char lastColor = '\0';
        int colorSegments = 0;

        for (int i = 0; i < rows; i++) {
            char rowColor = grid[i][0];

            // 1. Check if the entire row is monochromatic
            for (int j = 1; j < cols; j++) {
                if (grid[i][j] != rowColor) {
                    return false;
                }
            }

            // 2. Update counts for each color
            if (rowColor == 'R') {
                countR++;
            } else if (rowColor == 'G') {
                countG++;
            } else if (rowColor == 'B') {
                countB++;
            } else {
                return false; // Invalid character encountered
            }

            // 3. Detect color changes to ensure contiguity
            if (rowColor != lastColor) {
                colorSegments++;
                lastColor = rowColor;
            }
        }

        // Final checks:
        // - Each color must appear in an equal number of rows.
        // - There must be at least one of each color (based on problem context).
        // - There should be at most 3 color segments (one for each color).
        boolean equalDistribution = (countR > 0 && countR == countG && countG == countB);
        boolean isContiguous = (colorSegments <= 3);

        return equalDistribution && isContiguous;
    }

    /**
     * Creates a transposed version of the input grid.
     * 
     * @param grid The original grid.
     * @return The transposed grid.
     */
    private static char[][] transpose(char[][] grid) {
        int n = grid.length;
        int m = grid[0].length;
        char[][] transposed = new char[m][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                transposed[j][i] = grid[i][j];
            }
        }
        return transposed;
    }

    /**
     * Optimized reader for large input datasets.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Arrays;
import java.util.HashSet;
import java.util.Scanner;
import java.util.Set;

/**
 * A utility to determine if a grid of colors (R, G, B) can be partitioned 
 * into three equal bands (either horizontally or vertically) such that 
 * each band contains exactly one unique color and the three bands 
 * together represent a permutation of {R, G, B}.
 */
public class GridPatternChecker {

    private static final Set<Character> REQUIRED_COLORS = new HashSet<>(Arrays.asList('R', 'G', 'B'));

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        char[][] grid = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        boolean isPatternValid = validateGrid(grid, rows, cols);
        System.out.println(isPatternValid ? "YES" : "NO");

        scanner.close();
    }

    /**
     * Orchestrates the validation of the grid by checking both 
     * horizontal and vertical band possibilities.
     */
    private static boolean validateGrid(char[][] grid, int rows, int cols) {
        // Try horizontal partition if the number of rows is divisible by 3
        if (rows % 3 == 0 && checkBands(grid, rows, cols, true)) {
            return true;
        }

        // Try vertical partition if the number of columns is divisible by 3
        if (cols % 3 == 0 && checkBands(grid, rows, cols, false)) {
            return true;
        }

        return false;
    }

    /**
     * Validates if the grid can be divided into 3 bands of a single color,
     * where the three colors form a permutation of R, G, and B.
     *
     * @param grid        The 2D character array representing the grid.
     * @param rows        Total rows in the grid.
     * @param cols        Total columns in the grid.
     * @param isHorizontal If true, checks horizontal bands; if false, checks vertical bands.
     * @return true if the band pattern is valid, false otherwise.
     */
    private static boolean checkBands(char[][] grid, int rows, int cols, boolean isHorizontal) {
        int numBands = 3;
        int bandSize = isHorizontal ? rows / 3 : cols / 3;
        Set<Character> bandColors = new HashSet<>();

        for (int b = 0; b < numBands; b++) {
            Set<Character> uniqueColorsInCurrentBand = new HashSet<>();

            // Define the boundaries and iteration limits for the current band
            int startOffset = b * bandSize;
            int limit = isHorizontal ? cols : rows;

            for (int i = 0; i < bandSize; i++) {
                for (int j = 0; j < limit; j++) {
                    char color = isHorizontal 
                            ? grid[startOffset + i][j] 
                            : grid[j][startOffset + i];
                    uniqueColorsInCurrentBand.add(color);
                }
            }

            // Requirement 1: Each band must contain exactly one unique color
            if (uniqueColorsInCurrentBand.size() != 1) {
                return false;
            }

            // Add the single color found in this band to our set of band colors
            bandColors.add(uniqueColorsInCurrentBand.iterator().next());
        }

        // Requirement 2: The set of colors from the three bands must be {R, G, B}
        return bandColors.equals(REQUIRED_COLORS);
    }
}

import java.util.Scanner;

/**
 * FlagPatternValidator determines if a given grid (flag) follows 
 * a specific pattern of three distinct, uniform horizontal or vertical stripes.
 */
public class FlagPatternValidator {

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = scanner.next().toCharArray();
            }

            if (isValidFlag(grid)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /**
     * Validates whether the grid meets the stripe requirements either 
     * horizontally or vertically.
     *
     * @param grid The 2D character array representing the flag.
     * @return true if the flag pattern is valid, false otherwise.
     */
    private static boolean isValidFlag(char[][] grid) {
        // Check for horizontal stripes
        if (checkHorizontalStripes(grid)) {
            return true;
        }

        // Check for vertical stripes by transposing the grid and checking horizontal stripes again
        char[][] transposedGrid = transpose(grid);
        return checkHorizontalStripes(transposedGrid);
    }

    /**
     * Checks if the grid consists of three equal-height horizontal stripes,
     * where each stripe is a single uniform character and all three 
     * stripe characters are unique from one another.
     *
     * @param grid The 2D character array to check.
     * @return true if the horizontal stripe pattern is valid.
     */
    private static boolean checkHorizontalStripes(char[][] grid) {
        int rows = grid.length;
        if (rows == 0) {
            return false;
        }
        int cols = grid[0].length;

        // The pattern requires exactly three equal-height stripes
        if (rows % 3 != 0) {
            return false;
        }

        int stripeHeight = rows / 3;
        char[] stripeColors = new char[3];

        for (int stripeIdx = 0; stripeIdx < 3; stripeIdx++) {
            int startRow = stripeIdx * stripeHeight;
            char color = grid[startRow][0];

            // Verify that every cell in this stripe segment is the same color
            for (int r = startRow; r < startRow + stripeHeight; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] != color) {
                        return false;
                    }
                }
            }
            stripeColors[stripeIdx] = color;
        }

        // Ensure all three stripe colors are distinct
        return isDistinct(stripeColors);
    }

    /**
     * Helper to check if all elements in the array are unique.
     * 
     * @param colors Array of three characters.
     * @return true if all characters are different.
     */
    private static boolean isDistinct(char[] colors) {
        return colors[0] != colors[1] && 
               colors[1] != colors[2] && 
               colors[0] != colors[2];
    }

    /**
     * Transposes a 2D character array.
     *
     * @param matrix The original matrix.
     * @return A new matrix where rows and columns are swapped.
     */
    private static char[][] transpose(char[][] matrix) {
        int rows = matrix.length;
        int cols = matrix[0].length;
        char[][] transposed = new char[cols][rows];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                transposed[j][i] = matrix[i][j];
            }
        }
        return transposed;
    }
}

import java.util.*;
import java.io.*;

/**
 * Solves the "Flag of Berland" problem by verifying if three distinct colors
 * ('R', 'G', 'B') form identical rectangular regions within a grid.
 */
public class FlagOfBerland {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        FlagSolver solver = new FlagSolver(reader);
        solver.solve();
    }

    /**
     * Represents a rectangular area defined by its boundaries.
     */
    record Rectangle(int minRow, int maxRow, int minCol, int maxCol) {
        @Override
        public String toString() {
            return String.format("Rect[R:%d-%d, C:%d-%d]", minRow, maxRow, minCol, maxCol);
        }
    }

    static class FlagSolver {
        private final FastReader reader;

        public FlagSolver(FastReader reader) {
            this.reader = reader;
        }

        public void solve() {
            int n = reader.nextInt();
            int m = reader.nextInt();
            if (n <= 0 || m <= 0) {
                System.out.println("NO");
                return;
            }

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                String line = reader.next();
                if (line == null) break;
                for (int j = 0; j < m; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }

            Rectangle rectR = findRectangle(grid, n, m, 'R');
            Rectangle rectG = findRectangle(grid, n, m, 'G');
            Rectangle rectB = findRectangle(grid, n, m, 'B');

            if (isValidFlag(rectR, rectG, rectB)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }

        /**
         * Finds the bounding box of a specific color and verifies that the color
         * forms a solid, perfect rectangle with no other instances of that color outside it.
         */
        private Rectangle findRectangle(char[][] grid, int n, int m, char color) {
            int minRow = n, maxRow = -1;
            int minCol = m, maxCol = -1;
            int count = 0;

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == color) {
                        minRow = Math.min(minRow, i);
                        maxRow = Math.max(maxRow, i);
                        minCol = Math.min(minCol, j);
                        maxCol = Math.max(maxCol, j);
                        count++;
                    }
                }
            }

            // If the color wasn't found
            if (count == 0) {
                return null;
            }

            // Calculate dimensions of the bounding box
            int height = maxRow - minRow + 1;
            int width = maxCol - minCol + 1;

            // Check if the number of cells found matches the area of the bounding box.
            // If they match, it guarantees the color is a solid rectangle and 
            // no cells of this color exist outside this specific boundary.
            if (count == height * width) {
                return new Rectangle(minRow, maxRow, minCol, maxCol);
            }

            return null;
        }

        private boolean isValidFlag(Rectangle r, Rectangle g, Rectangle b) {
            return r != null && g != null && b != null 
                    && r.equals(g) 
                    && g.equals(b);
        }
    }

    /**
     * Optimized reader for fast I/O operations.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            return next != null ? Integer.parseInt(next) : 0;
        }
    }
}

