/**
 * Contains the business logic for determining if a grid represents a valid flag.
 */
class FlagSolver {

    /**
     * Reads the grid and determines if it is a valid horizontal or vertical flag.
     */
    public void solve(FastReader in, PrintWriter out) {
        int rowCount = in.nextInt();
        int colCount = in.nextInt();

        char[][] grid = new char[rowCount][colCount];
        for (int i = 0; i < rowCount; i++) {
            grid[i] = in.next().toCharArray();
        }

        if (isHorizontalFlag(grid) || isVerticalFlag(grid)) {
            out.println("YES");
        } else {
            out.println("NO");
        }
    }

    /**
     * Checks if the grid consists of three equal-height horizontal monochromatic stripes.
     */
    private boolean isHorizontalFlag(char[][] grid) {
        int rowCount = grid.length;
        int colCount = grid[0].length;

        if (rowCount % 3 != 0) {
            return false;
        }

        char[] colorSequence = new char[rowCount];
        for (int i = 0; i < rowCount; i++) {
            char rowColor = grid[i][0];
            // Check if the entire row is monochromatic
            for (int j = 1; j < colCount; j++) {
                if (grid[i][j] != rowColor) {
                    return false;
                }
            }
            colorSequence[i] = rowColor;
        }

        return isValidStripePattern(colorSequence);
    }

    /**
     * Checks if the grid consists of three equal-width vertical monochromatic stripes.
     */
    private boolean isVerticalFlag(char[][] grid) {
        int rowCount = grid.length;
        int colCount = grid[0].length;

        if (colCount % 3 != 0) {
            return false;
        }

        char[] colorSequence = new char[colCount];
        for (int j = 0; j < colCount; j++) {
            char colColor = grid[0][j];
            // Check if the entire column is monochromatic
            for (int i = 1; i < rowCount; i++) {
                if (grid[i][j] != colColor) {
                    return false;
                }
            }
            colorSequence[j] = colColor;
        }

        return isValidStripePattern(colorSequence);
    }

    /**
     * Validates that a sequence of colors consists of three distinct colors,
     * each appearing in exactly one-third of the sequence.
     */
    private boolean isValidStripePattern(char[] sequence) {
        int n = sequence.length;
        int segmentLen = n / 3;

        char color1 = sequence[0];
        char color2 = sequence[segmentLen];
        char color3 = sequence[2 * segmentLen];

        // Colors must be distinct
        if (color1 == color2 || color2 == color3 || color1 == color3) {
            return false;
        }

        // Check first segment
        for (int i = 0; i < segmentLen; i++) {
            if (sequence[i] != color1) return false;
        }
        // Check second segment
        for (int i = segmentLen; i < 2 * segmentLen; i++) {
            if (sequence[i] != color2) return false;
        }
        // Check third segment
        for (int i = 2 * segmentLen; i < n; i++) {
            if (sequence[i] != color3) return false;
        }

        return true;
    }
}

