import java.util.*;
import java.io.*;

/**
 * Solves the grid division problem: determines if a grid can be divided into three
 * equal monochromatic parts (either horizontally or vertically) such that each 
 * part consists of a different character.
 */
public class Main {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        GridSolver solver = new GridSolver(scanner);
        solver.solve(out);

        out.close();
    }

    static class GridSolver {
        private final FastScanner scanner;

        public GridSolver(FastScanner scanner) {
            this.scanner = scanner;
        }

        public void solve(PrintWriter out) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            char[][] grid = new char[rows][];
            for (int i = 0; i < rows; i++) {
                grid[i] = scanner.next().toCharArray();
            }

            boolean possible = checkHorizontalSplit(grid, rows, cols) || 
                               checkVerticalSplit(grid, rows, cols);

            out.println(possible ? "YES" : "NO");
        }

        /**
         * Checks if the grid can be divided into 3 equal horizontal bands.
         */
        private boolean checkHorizontalSplit(char[][] grid, int rows, int cols) {
            if (rows % 3 != 0) {
                return false;
            }

            int blockSize = rows / 3;

            // Get the character representing each of the three bands
            char charBand1 = grid[0][0];
            char charBand2 = grid[blockSize][0];
            char charBand3 = grid[2 * blockSize][0];

            // Requirement 1: All three bands must have different characters
            if (!areDistinct(charBand1, charBand2, charBand3)) {
                return false;
            }

            // Requirement 2: Each band must be monochromatic
            return isRegionUniform(grid, 0, blockSize - 1, 0, cols - 1) &&
                   isRegionUniform(grid, blockSize, 2 * blockSize - 1, 0, cols - 1) &&
                   isRegionUniform(grid, 2 * blockSize, rows - 1, 0, cols - 1);
        }

        /**
         * Checks if the grid can be divided into 3 equal vertical bands.
         */
        private boolean checkVerticalSplit(char[][] grid, int rows, int cols) {
            if (cols % 3 != 0) {
                return false;
            }

            int blockSize = cols / 3;

            // Get the character representing each of the three bands
            char charBand1 = grid[0][0];
            char charBand2 = grid[0][blockSize];
            char charBand3 = grid[0][2 * blockSize];

            // Requirement 1: All three bands must have different characters
            if (!areDistinct(charBand1, charBand2, charBand3)) {
                return false;
            }

            // Requirement 2: Each band must be monochromatic
            return isRegionUniform(grid, 0, rows - 1, 0, blockSize - 1) &&
                   isRegionUniform(grid, 0, rows - 1, blockSize, 2 * blockSize - 1) &&
                   isRegionUniform(grid, 0, rows - 1, 2 * blockSize, cols - 1);
        }

        /**
         * Verifies if all cells within the specified rectangular bounds contain the same character.
         */
        private boolean isRegionUniform(char[][] grid, int rStart, int rEnd, int cStart, int cEnd) {
            char target = grid[rStart][cStart];
            for (int r = rStart; r <= rEnd; r++) {
                for (int c = cStart; c <= cEnd; c++) {
                    if (grid[r][c] != target) {
                        return false;
                    }
                }
            }
            return true;
        }

        private boolean areDistinct(char a, char b, char c) {
            return a != b && b != c && a != c;
        }
    }

    /**
     * Utility class for high-performance input reading.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            this.br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }
    }
}

