/**
 * A solution to determine if a grid of colors ('R', 'G', 'B') is composed 
 * of three distinct colored stripes either horizontally or vertically.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] grid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            PatternSolver solver = new PatternSolver(grid);
            if (solver.hasValidPattern()) {
                writer.println("YES");
            } else {
                writer.println("NO");
            }
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Contains the core logic for analyzing the grid patterns.
     */
    static class PatternSolver {
        private final char[][] grid;

        public PatternSolver(char[][] grid) {
            this.grid = grid;
        }

        /**
         * Checks if the grid is valid either horizontally or vertically.
         */
        public boolean hasValidPattern() {
            return isValidPattern(grid) || isValidPattern(transpose(grid));
        }

        /**
         * Checks if the provided grid is divided into 3 horizontal stripes,
         * each consisting of a single, unique color from {'R', 'G', 'B'}.
         */
        private boolean isValidPattern(char[][] currentGrid) {
            int rows = currentGrid.length;
            int cols = currentGrid[0].length;

            if (rows % 3 != 0) {
                return false;
            }

            int stripeHeight = rows / 3;
            Set<Character> seenColors = new HashSet<>();

            for (int i = 0; i < 3; i++) {
                int startRow = i * stripeHeight;
                char stripeColor = currentGrid[startRow][0];

                if (!isValidColor(stripeColor) || !seenColors.add(stripeColor)) {
                    return false;
                }

                // Verify every cell in the current stripe matches the stripe's color
                for (int r = startRow; r < startRow + stripeHeight; r++) {
                    for (int c = 0; c < cols; c++) {
                        if (currentGrid[r][c] != stripeColor) {
                            return false;
                        }
                    }
                }
            }

            // Ensure all three required colors were present
            return seenColors.size() == 3;
        }

        private boolean isValidColor(char c) {
            return c == 'R' || c == 'G' || c == 'B';
        }

        /**
         * Returns a new grid that is the transpose of the input grid.
         */
        private char[][] transpose(char[][] matrix) {
            int rows = matrix.length;
            int cols = matrix[0].length;
            char[][] transposed = new char[cols][rows];

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    transposed[j][i] = matrix[i][j];
                }
            }
            return transposed;
        }
    }

    /**
     * Efficient reader for fast I/O operations.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

