import java.util.Set;

/**
 * Main class to execute the grid pattern solver.
 */
public class Main {
    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        GridPatternSolver solver = new GridPatternSolver();
        solver.solve(reader, writer);

        writer.close();
    }

    /**
     * Contains the business logic for determining if the grid 
     * follows the required color stripe pattern.
     */
    static class GridPatternSolver {

        /**
         * Reads input and prints the result of the pattern check.
         */
        public void solve(FastReader in, PrintWriter out) {
            int rows = in.readInt();
            int cols = in.readInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = in.readCharacter();
                }
            }

            if (hasHorizontalStripes(grid) || hasVerticalStripes(grid)) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        }

        /**
         * Checks if the grid is composed of three equal horizontal bands,
         * each consisting of a single unique color (R, G, or B).
         */
        private boolean hasHorizontalStripes(char[][] grid) {
            int rows = grid.length;
            int cols = grid[0].length;

            if (rows % 3 != 0) {
                return false;
            }

            int bandHeight = rows / 3;
            Set<Character> colorsFound = new HashSet<>();

            for (int band = 0; band < 3; band++) {
                int startRow = band * bandHeight;
                char bandColor = grid[startRow][0];
                colorsFound.add(bandColor);

                for (int r = startRow; r < startRow + bandHeight; r++) {
                    for (int c = 0; c < cols; c++) {
                        if (grid[r][c] != bandColor) {
                            return false;
                        }
                    }
                }
            }

            return isValidColorSet(colorsFound);
        }

        /**
         * Checks if the grid is composed of three equal vertical bands,
         * each consisting of a single unique color (R, G, or B).
         */
        private boolean hasVerticalStripes(char[][] grid) {
            int rows = grid.length;
            int cols = grid[0].length;

            if (cols % 3 != 0) {
                return false;
            }

            int bandWidth = cols / 3;
            Set<Character> colorsFound = new HashSet<>();

            for (int band = 0; band < 3; band++) {
                int startCol = band * bandWidth;
                char bandColor = grid[0][startCol];
                colorsFound.add(bandColor);

                for (int c = startCol; c < startCol + bandWidth; c++) {
                    for (int r = 0; r < rows; r++) {
                        if (grid[r][c] != bandColor) {
                            return false;
                        }
                    }
                }
            }

            return isValidColorSet(colorsFound);
        }

        /**
         * Validates if the set of colors found contains exactly R, G, and B.
         */
        private boolean isValidColorSet(Set<Character> colors) {
            return colors.size() == 3 &&
                   colors.contains('R') &&
                   colors.contains('G') &&
                   colors.contains('B');
        }
    }

    /**
     * A fast I/O reader for handling large inputs efficiently.
     */
    static class FastReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int currentChar;
        private int numChars;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (currentChar >= numChars) {
                currentChar = 0;
                try {
                    numChars = stream.read(buffer);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buffer[currentChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public char readCharacter() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            return (char) c;
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

