        } catch (IOException | NumberFormatException e) {
            // In a production environment, use a logger.
            System.err.println("Error processing input: " + e.getMessage());
        }
    }

    /**
     * Analyzes a grid to determine if it can be divided into three equal bands
     * (either horizontally or vertically) where each band contains exactly 
     * one of the colors: Red, Green, or Blue.
     */
    private static class GridPatternAnalyzer {
        private final char[][] grid;
        private final int rows;
        private final int cols;

        private static final Set<Character> REQUIRED_COLORS = Set.of('R', 'G', 'B');

        public GridPatternAnalyzer(char[][] grid) {
            this.grid = grid;
            this.rows = grid.length;
            this.cols = (grid.length > 0) ? grid[0].length : 0;
        }

        /**
         * Checks if the grid satisfies the pattern requirement either horizontally or vertically.
         * @return true if a valid pattern is found.
         */
        public boolean isValidPattern() {
            return checkHorizontalBands() || checkVerticalBands();
        }

        /**
         * Checks if the grid can be split into 3 equal horizontal strips.
         */
        private boolean checkHorizontalBands() {
            if (rows == 0 || rows % 3 != 0) {
                return false;
            }

            int bandHeight = rows / 3;
            Set<Character> foundColors = new HashSet<>();

            for (int b = 0; b < 3; b++) {
                int startRow = b * bandHeight;
                // We assume the first cell of the band defines the required color for that band
                char bandColor = grid[startRow][0];
                foundColors.add(bandColor);

                // Verify all cells in this horizontal band match the band color
                for (int r = startRow; r < startRow + bandHeight; r++) {
                    for (int c = 0; c < cols; c++) {
                        if (grid[r][c] != bandColor) {
                            return false;
                        }
                    }
                }
            }

            return foundColors.equals(REQUIRED_COLORS);
        }

        /**
         * Checks if the grid can be split into 3 equal vertical strips.
         */
        private boolean checkVerticalBands() {
            if (cols == 0 || cols % 3 != 0) {
                return false;
            }

            int bandWidth = cols / 3;
            Set<Character> foundColors = new HashSet<>();

            for (int b = 0; b < 3; b++) {
                int startCol = b * bandWidth;
                // We assume the first cell of the band defines the required color for that band
                char bandColor = grid[0][startCol];
                foundColors.add(bandColor);

                // Verify all cells in this vertical band match the band color
                for (int r = 0; r < rows; r++) {
                    for (int c = startCol; c < startCol + bandWidth; c++) {
                        if (grid[r][c] != bandColor) {
                            return false;
                        }
                    }
                }
            }

            return foundColors.equals(REQUIRED_COLORS);
        }
    }
}

import java.util.Scanner;

/**
 * The Works class evaluates whether a given grid of colors (R, G, B) 
 * forms a valid horizontal or vertical flag.
 * A valid flag must have an equal distribution of R, G, and B colors
 * and follow a specific three-segment pattern.
 */
public class Works {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String rowString = scanner.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = rowString.charAt(j);
            }
        }

        if (isValidFlag(rows, cols, grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Determines if the grid meets all criteria for being a valid flag.
     */
    private static boolean isValidFlag(int rows, int cols, char[][] grid) {
        return isColorsBalanced(rows, cols, grid) &&
               (isHorizontalFlag(rows, cols, grid) || isVerticalFlag(rows, cols, grid));
    }

    /**
     * Checks if the total count of 'R', 'G', and 'B' are equal.
     */
    private static boolean isColorsBalanced(int rows, int cols, char[][] grid) {
        int rCount = 0, gCount = 0, bCount = 0;

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                switch (grid[i][j]) {
                    case 'R': rCount++; break;
                    case 'G': gCount++; break;
                    case 'B': bCount++; break;
                }
            }
        }
        // A flag must contain all three colors in equal amounts
        return rCount > 0 && rCount == gCount && gCount == bCount;
    }

    /**
     * A horizontal flag: all rows are identical, and each row 
     * consists of 3 equal color segments.
     */
    private static boolean isHorizontalFlag(int rows, int cols, char[][] grid) {
        if (cols % 3 != 0) {
            return false;
        }

        int segmentLen = cols / 3;

        // 1. All rows must be identical to the first row
        for (int i = 1; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] != grid[0][j]) {
                    return false;
                }
            }
        }

        // 2. The first row must consist of 3 uniform segments
        return checkPatternUniformity(grid[0], segmentLen);
    }

    /**
     * A vertical flag: all columns are identical, and each column 
     * consists of 3 equal color segments.
     */
    private static boolean isVerticalFlag(int rows, int cols, char[][] grid) {
        if (rows % 3 != 0) {
            return false;
        }

        int segmentLen = rows / 3;

        // 1. All columns must be identical to the first column
        // This implies every cell in a row is the same as the first cell in that row
        for (int i = 0; i < rows; i++) {
            for (int j = 1; j < cols; j++) {
                if (grid[i][j] != grid[i][0]) {
                    return false;
                }
            }
        }

        // 2. The first column must consist of 3 uniform segments
        char[] firstColumn = new char[rows];
        for (int i = 0; i < rows; i++) {
            firstColumn[i] = grid[i][0];
        }

        return checkPatternUniformity(firstColumn, segmentLen);
    }

    /**
     * Verifies that a 1D array (a row or column) is divided into 
     * three distinct, uniform segments.
     */
    private static boolean checkPatternUniformity(char[] line, int segmentLen) {
        return isUniform(line, 0, segmentLen) &&
               isUniform(line, segmentLen, 2 * segmentLen) &&
               isUniform(line, 2 * segmentLen, 3 * segmentLen);
    }

    /**
     * Checks if a specific range within an array is composed of the same character.
     */
    private static boolean isUniform(char[] line, int start, int end) {
        char color = line[start];
        for (int i = start + 1; i < end; i++) {
            if (line[i] != color) {
                return false;
            }
        }
        return true;
    }
}

