/**
 * Handles the logic of analyzing the grid for specific character patterns.
 */
class GridAnalyzer {
    private final FastReader reader;

    public GridAnalyzer(FastReader reader) {
        this.reader = reader;
    }

    /**
     * Orchestrates the grid reading and pattern checking.
     * @return true if the grid satisfies the 3-band pattern.
     */
    public boolean solve() throws IOException {
        int rowCount = reader.readInt();
        int colCount = reader.readInt();
        char[][] grid = new char[rowCount][];

        for (int i = 0; i < rowCount; i++) {
            grid[i] = reader.readCharArray();
        }

        return checkRowPattern(grid, rowCount, colCount) || 
               checkColumnPattern(grid, rowCount, colCount);
    }

    private boolean checkRowPattern(char[][] grid, int rows, int cols) {
        if (rows % 3 != 0) return false;
        int segmentSize = rows / 3;

        Set<Character> band1 = collectCharsInRange(grid, 0, segmentSize, true);
        Set<Character> band2 = collectCharsInRange(grid, segmentSize, 2 * segmentSize, true);
        Set<Character> band3 = collectCharsInRange(grid, 2 * segmentSize, rows, true);

        return isValidThreeBandPattern(band1, band2, band3);
    }

    private boolean checkColumnPattern(char[][] grid, int rows, int cols) {
        if (cols % 3 != 0) return false;
        int segmentSize = cols / 3;

        Set<Character> band1 = collectCharsInRange(grid, 0, segmentSize, false);
        Set<Character> band2 = collectCharsInRange(grid, segmentSize, 2 * segmentSize, false);
        Set<Character> band3 = collectCharsInRange(grid, 2 * segmentSize, cols, false);

        return isValidThreeBandPattern(band1, band2, band3);
    }

    /**
     * Validates if the three sets of characters meet the criteria:
     * 1. Each band contains exactly one unique character.
     * 2. There are exactly three distinct characters across all bands.
     */
    private boolean isValidThreeBandPattern(Set<Character> s1, Set<Character> s2, Set<Character> s3) {
        if (s1.size() != 1 || s2.size() != 1 || s3.size() != 1) {
            return false;
        }

        Set<Character> combined = new HashSet<>(s1);
        combined.addAll(s2);
        combined.addAll(s3);

        return combined.size() == 3;
    }

    /**
     * Collects unique characters within a specific range of rows or columns.
     * 
     * @param grid The input grid.
     * @param start The starting index of the range.
     * @param end The ending index of the range.
     * @param isRowRange If true, iterates through rows; if false, iterates through columns.
     * @return A set of unique characters found in the specified range.
     */
    private Set<Character> collectCharsInRange(char[][] grid, int start, int end, boolean isRowRange) {
        Set<Character> uniqueChars = new HashSet<>();
        int rowCount = grid.length;
        int colCount = grid[0].length;

        if (isRowRange) {
            for (int i = start; i < end; i++) {
                for (char c : grid[i]) {
                    uniqueChars.add(c);
                }
            }
        } else {
            for (int j = start; j < end; j++) {
                for (int i = 0; i < rowCount; i++) {
                    uniqueChars.add(grid[i][j]);
                }
            }
        }
        return uniqueChars;
    }
}

