import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.InputMismatchException;

/**
 * Refactored solution for the Grid Pattern problem.
 * The goal is to determine if a grid of characters can be partitioned into 
 * three equal blocks of rows (or columns) such that each block consists 
 * of a single repeated character and the three blocks are distinct.
 */
public class GridPatternSolver {

    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        Solver solver = new Solver();
        solver.solve(in, out);

        out.close();
    }

    static class Solver {

        /**
         * Solves the main task.
         * 
         * @param in  The input reader.
         * @param out The output writer.
         */
        public void solve(InputReader in, PrintWriter out) {
            int rows = in.nextInt();
            int cols = in.nextInt();

            String[] grid = new String[rows];
            for (int i = 0; i < rows; i++) {
                grid[i] = in.next();
            }

            if (isPatternValid(grid)) {
                out.println("YES");
            } else if (cols % 3 == 0 && isPatternValid(transpose(grid, rows, cols))) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        }

        /**
         * Checks if the provided grid follows the 3-block pattern:
         * 1. The number of rows must be divisible by 3.
         * 2. The grid must be divided into 3 equal segments of rows.
         * 3. Every row within a segment must be identical.
         * 4. Each segment's row must consist of only one unique character.
         * 5. The three segments must use different characters.
         * 
         * @param grid The array of strings representing the grid.
         * @return true if the pattern is valid, false otherwise.
         */
        private boolean isPatternValid(String[] grid) {
            int n = grid.length;
            if (n % 3 != 0) {
                return false;
            }

            int segmentSize = n / 3;
            String s1 = grid[0];
            String s2 = grid[segmentSize];
            String s3 = grid[2 * segmentSize];

            // Condition: Each segment's representative must be uniform (all same characters)
            if (!isUniform(s1) || !isUniform(s2) || !isUniform(s3)) {
                return false;
            }

            // Condition: All three segments must be distinct
            if (s1.equals(s2) || s2.equals(s3) || s1.equals(s3)) {
                return false;
            }

            // Condition: All rows in each segment must be identical to the segment's representative
            for (int i = 0; i < segmentSize; i++) {
                if (!grid[i].equals(s1)) return false;
                if (!grid[segmentSize + i].equals(s2)) return false;
                if (!grid[2 * segmentSize + i].equals(s3)) return false;
            }

            return true;
        }

        /**
         * Checks if a string consists of only one repeated character.
         */
        private boolean isUniform(String s) {
            if (s == null || s.isEmpty()) {
                return true;
            }
            char firstChar = s.charAt(0);
            for (int i = 1; i < s.length(); i++) {
                if (s.charAt(i) != firstChar) {
                    return false;
                }
            }
            return true;
        }

        /**
         * Transposes the grid (converts rows to columns).
         * 
         * @param grid The original grid.
         * @param rows Number of rows in the original grid.
         * @param cols Number of columns in the original grid.
         * @return A new array of strings representing the transposed grid.
         */
        private String[] transpose(String[] grid, int rows, int cols) {
            String[] transposed = new String[cols];
            for (int c = 0; c < cols; c++) {
                StringBuilder sb = new StringBuilder(rows);
                for (int r = 0; r < rows; r++) {
                    sb.append(grid[r].charAt(c));
                }
                transposed[c] = sb.toString();
            }
            return transposed;
        }
    }

    /**
     * High-performance input reader for large datasets.
     */
    static class InputReader {
        private final InputStream stream;
        private final byte[] buf = new byte[8192];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (numChars == -1) throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) return -1;
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

