    /**
     * Validates the grid based on the requirements:
     * 1. Equal number of R, G, and B characters.
     * 2. The grid must be composed of 3 identical-sized horizontal or vertical bands.
     */
    private static boolean isValidPattern(char[][] grid, int rows, int cols) {
        // 1. Check if counts of R, G, and B are equal
        if (!hasEqualColorCounts(grid, rows, cols)) {
            return false;
        }

        // 2. Check for Horizontal Band Pattern (3 horizontal stripes)
        if (rows % 3 == 0 && isHorizontalPattern(grid, rows, cols)) {
            return true;
        }

        // 3. Check for Vertical Band Pattern (3 vertical stripes)
        if (cols % 3 == 0 && isVerticalPattern(grid, rows, cols)) {
            return true;
        }

        return false;
    }

    private static boolean hasEqualColorCounts(char[][] grid, int rows, int cols) {
        int r = 0, g = 0, b = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 'R') r++;
                else if (grid[i][j] == 'G') g++;
                else if (grid[i][j] == 'B') b++;
            }
        }
        return r > 0 && r == g && g == b;
    }

    /**
     * Checks if the grid consists of 3 horizontal bands of equal height.
     */
    private static boolean isHorizontalPattern(char[][] grid, int rows, int cols) {
        int bandHeight = rows / 3;
        char color1 = grid[0][0];
        char color2 = grid[bandHeight][0];
        char color3 = grid[2 * bandHeight][0];

        // Colors must be distinct
        if (color1 == color2 || color2 == color3 || color1 == color3) {
            return false;
        }

        for (int i = 0; i < rows; i++) {
            char expectedColor;
            if (i < bandHeight) {
                expectedColor = color1;
            } else if (i < 2 * bandHeight) {
                expectedColor = color2;
            } else {
                expectedColor = color3;
            }

            for (int j = 0; j < cols; j++) {
                if (grid[i][j] != expectedColor) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Checks if the grid consists of 3 vertical bands of equal width.
     */
    private static boolean isVerticalPattern(char[][] grid, int rows, int cols) {
        int bandWidth = cols / 3;
        char color1 = grid[0][0];
        char color2 = grid[0][bandWidth];
        char color3 = grid[0][2 * bandWidth];

        // Colors must be distinct
        if (color1 == color2 || color2 == color3 || color1 == color3) {
            return false;
        }

        for (int j = 0; j < cols; j++) {
            char expectedColor;
            if (j < bandWidth) {
                expectedColor = color1;
            } else if (j < 2 * bandWidth) {
                expectedColor = color2;
            } else {
                expectedColor = color3;
            }

            for (int i = 0; i < rows; i++) {
                if (grid[i][j] != expectedColor) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * A utility class for fast input reading.
 */
class FastReader {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    public FastReader(InputStream input) {
        reader = new BufferedReader(new InputStreamReader(input));
    }

    public String next() {
        while (tokenizer == null || !tokenizer.hasMoreElements()) {
            try {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                throw new RuntimeException("Error reading input", e);
            }
        }
        return tokenizer.nextToken();
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }
}

/**
 * Represents a grid of colors and provides methods to analyze its patterns.
 */
class ColorGrid {
    private static final int BLOCK_PARTITIONS = 3;

    private final char[][] grid;
    private final int rowCount;
    private final int colCount;

    public ColorGrid(int rowCount, int colCount, FastReader reader) {
        this.rowCount = rowCount;
        this.colCount = colCount;
        this.grid = new char[rowCount][colCount];
        for (int i = 0; i < rowCount; i++) {
            String rowString = reader.next();
            this.grid[i] = rowString.toCharArray();
        }
    }

    /**
     * Determines if the grid can be partitioned into three monochromatic stripes
     * either horizontally or vertically, given that color counts are balanced.
     */
    public boolean satisfiesPatternRequirement() {
        if (!hasEqualColorCounts()) {
            return false;
        }
        return canBeSplitHorizontally() || canBeSplitVertically();
    }

    private boolean hasEqualColorCounts() {
        int redCount = 0;
        int greenCount = 0;
        int blueCount = 0;

        for (int i = 0; i < rowCount; i++) {
            for (int j = 0; j < colCount; j++) {
                char color = grid[i][j];
                if (color == 'R') redCount++;
                else if (color == 'G') greenCount++;
                else if (color == 'B') blueCount++;
            }
        }
        return redCount == greenCount && greenCount == blueCount;
    }

    private boolean canBeSplitHorizontally() {
        if (rowCount % BLOCK_PARTITIONS != 0) {
            return false;
        }

        int blockSize = rowCount / BLOCK_PARTITIONS;
        return isMonochromaticBlock(0, blockSize, true) &&
               isMonochromaticBlock(blockSize, blockSize, true) &&
               isMonochromaticBlock(2 * blockSize, blockSize, true);
    }

    private boolean canBeSplitVertically() {
        if (colCount % BLOCK_PARTITIONS != 0) {
            return false;
        }

        int blockSize = colCount / BLOCK_PARTITIONS;
        return isMonochromaticBlock(0, blockSize, false) &&
               isMonochromaticBlock(blockSize, blockSize, false) &&
               isMonochromaticBlock(2 * blockSize, blockSize, false);
    }

    /**
     * Checks if a specific block of the grid is composed of a single color.
     * 
     * @param startOffset The starting index for the check.
     * @param size The number of rows/cols to check.
     * @param isHorizontal True if checking a horizontal slice, false for vertical.
     * @return true if the block is monochromatic.
     */
    private boolean isMonochromaticBlock(int startOffset, int size, boolean isHorizontal) {
        if (isHorizontal) {
            char targetColor = grid[startOffset][0];
            for (int i = startOffset; i < startOffset + size; i++) {
                for (int j = 0; j < colCount; j++) {
                    if (grid[i][j] != targetColor) return false;
                }
            }
        } else {
            char targetColor = grid[0][startOffset];
            for (int i = 0; i < rowCount; i++) {
                for (int j = startOffset; j < startOffset + size; j++) {
                    if (grid[i][j] != targetColor) return false;
                }
            }
        }
        return true;
    }
}

/**
 * Entry point for the application.
 */
public class Main {
    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            int n = reader.nextInt();
            int m = reader.nextInt();

            ColorGrid colorGrid = new ColorGrid(n, m, reader);

            if (colorGrid.satisfiesPatternRequirement()) {
                writer.println("YES");
            } else {
                writer.println("NO");
            }
        } catch (Exception e) {
            // In a real production environment, use a logger.
            // For competitive programming, we let it fail or print error.
        } finally {
            writer.flush();
            writer.close();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Solves the Flag Pattern problem by determining if a grid follows 
 * a row-wise or column-wise uniform pattern.
 */
public class FlagPatternSolver {

    private static final int REQUIRED_SEGMENTS = 3;

    private final char[][] grid;
    private final int rows;
    private final int cols;

    public FlagPatternSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
    }

    /**
     * Main entry point for solving the pattern logic.
     * @return "YES" if a valid pattern is found, "NO" otherwise.
     */
    public String solve() {
        if (isPatternValid(true) || isPatternValid(false)) {
            return "YES";
        }
        return "NO";
    }

    /**
     * Validates if the grid follows a pattern along the specified orientation.
     * 
     * @param checkRows If true, checks for row-wise patterns; 
     *                  if false, checks for column-wise patterns.
     * @return true if the pattern is valid.
     */
    private boolean isPatternValid(boolean checkRows) {
        int primaryDim = checkRows ? rows : cols;
        int secondaryDim = checkRows ? cols : rows;

        // A valid pattern must be divisible into exactly 3 segments
        if (primaryDim % REQUIRED_SEGMENTS != 0) {
            return false;
        }

        int segmentSize = primaryDim / REQUIRED_SEGMENTS;
        char[] segmentChars = new char[REQUIRED_SEGMENTS];

        for (int k = 0; k < REQUIRED_SEGMENTS; k++) {
            int startIdx = k * segmentSize;

            // Identify the characteristic character for this segment
            segmentChars[k] = checkRows ? grid[startIdx][0] : grid[0][startIdx];

            // Verify that every cell in this segment matches the characteristic character
            if (!isSegmentUniform(startIdx, segmentSize, segmentChars[k], checkRows, secondaryDim)) {
                return false;
            }
        }

        // Ensure the characters of the three segments are distinct
        return areDistinct(segmentChars);
    }

    /**
     * Checks if all cells within a specific segment of the grid are uniform.
     */
    private boolean isSegmentUniform(int startIdx, int segmentSize, char target, boolean checkRows, int secondaryDim) {
        for (int i = 0; i < segmentSize; i++) {
            for (int j = 0; j < secondaryDim; j++) {
                int r = checkRows ? (startIdx + i) : j;
                int c = checkRows ? j : (startIdx + i);

                if (grid[r][c] != target) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Checks if the provided array of characters contains only unique elements.
     */
    private boolean areDistinct(char[] chars) {
        return chars[0] != chars[1] && 
               chars[0] != chars[2] && 
               chars[1] != chars[2];
    }

    /**
     * Handles I/O operations and orchestrates the solver.
     */
    public static void main(String[] args) {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String line = br.readLine();
            if (line == null) return;

            StringTokenizer st = new StringTokenizer(line);
            int n = Integer.parseInt(st.nextToken());
            int m = Integer.parseInt(st.nextToken());

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                grid[i] = br.readLine().toCharArray();
            }

            FlagPatternSolver solver = new FlagPatternSolver(n, m, grid);
            System.out.println(solver.solve());

        } catch (IOException | NumberFormatException e) {
            // In a production environment, use a logger
            System.err.println("Error processing input: " + e.getMessage());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * A program that validates if a grid of colors follows a specific pattern:
 * 1. The grid must be partitionable into monochromatic rows OR monochromatic columns.
 * 2. A color cannot reappear once the sequence has transitioned to a different color.
 * 3. The counts of 'R', 'G', and 'B' must be equal.
 */
public class GridColorValidator {

    public static void main(String[] args) {
        FastReader fr = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            // Parse dimensions
            String nStr = fr.next();
            String mStr = fr.next();
            if (nStr == null || mStr == null) return;

            int numRows = Integer.parseInt(nStr);
            int numCols = Integer.parseInt(mStr);

            char[][] grid = new char[numRows][numCols];

            // Populate the grid
            for (int i = 0; i < numRows; i++) {
                String row = fr.next();
                if (row != null) {
                    grid[i] = row.toCharArray();
                }
            }

            // Check if the criteria are met for either rows or columns
            boolean rowPatternValid = isValidPattern(grid, numRows, numCols, true);
            boolean colPatternValid = isValidPattern(grid, numRows, numCols, false);

            if (rowPatternValid || colPatternValid) {
                out.println("YES");
            } else {
                out.println("NO");
            }

        } catch (IOException | NumberFormatException e) {
            // In a real-world scenario, use a logger here.
        } finally {
            out.close();
        }
    }

    /**
     * Validates the grid for monochromaticity, color transition rules, and color balance.
     *
     * @param grid       The character grid.
     * @param numRows    The number of rows in the grid.
     * @param numCols    The number of columns in the grid.
     * @param checkRows  True to validate rows, false to validate columns.
     * @return true if the pattern is valid and color counts are equal.
     */
    private static boolean isValidPattern(char[][] grid, int numRows, int numCols, boolean checkRows) {
        int primaryDim = checkRows ? numRows : numCols;
        int secondaryDim = checkRows ? numCols : numRows;

        int[] colorCounts = new int[26];
        boolean[] colorStopped = new boolean[26];
        char lastColor = ' ';

        for (int i = 0; i < primaryDim; i++) {
            char currentColor = ' ';

            // 1. Verify that the current row (or column) is monochromatic
            for (int j = 0; j < secondaryDim; j++) {
                char cell = checkRows ? grid[i][j] : grid[j][i];
                if (j == 0) {
                    currentColor = cell;
                } else if (cell != currentColor) {
                    return false; // Violates monochromaticity
                }
            }

            // 2. Verify color transition rule (no reappearance of a previous color)
            if (i > 0 && currentColor != lastColor) {
                // The previous color has now "stopped"
                colorStopped[lastColor - 'A'] = true;
            }

            // If the current color was previously marked as stopped, the sequence is invalid
            if (colorStopped[currentColor - 'A']) {
                return false;
            }

            // 3. Update color statistics
            colorCounts[currentColor - 'A']++;
            lastColor = currentColor;
        }

        // 4. Ensure 'R', 'G', and 'B' colors are equally represented
        return isBalanced(colorCounts);
    }

    /**
     * Checks if the counts for R, G, and B characters are equal.
     */
    private static boolean isBalanced(int[] colorCounts) {
        int r = colorCounts['R' - 'A'];
        int g = colorCounts['G' - 'A'];
        int b = colorCounts['B' - 'A'];
        return r == g && g == b;
    }

    /**
     * Optimized reader for faster input processing.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            this.reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.HashSet;
import java.util.StringTokenizer;
import java.util.Set;

/**
 * A program to determine if a character grid can be divided into three equal 
 * horizontal or vertical blocks, where each block consists of a single 
 * unique character and all three blocks use different characters.
 */
public class GridPatternChecker {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int rowCount = reader.nextInt();
            int colCount = reader.nextInt();

            char[][] grid = new char[rowCount][colCount];
            for (int i = 0; i < rowCount; i++) {
                grid[i] = reader.nextLine().toCharArray();
            }

            if (hasValidPattern(grid) || hasValidPattern(transpose(grid))) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            out.close();
        }
    }

    /**
     * Checks if the grid satisfies the pattern: three equal segments 
     * of rows, each segment containing only one type of character, 
     * and all three segments having different characters.
     */
    private static boolean hasValidPattern(char[][] grid) {
        int rowCount = grid.length;
        if (rowCount == 0) return false;
        int colCount = grid[0].length;

        // The grid must be divisible into 3 equal parts
        if (rowCount % 3 != 0) {
            return false;
        }

        int segmentSize = rowCount / 3;
        Set<Character> uniqueSegmentChars = new HashSet<>();

        for (int segment = 0; segment < 3; segment++) {
            int startRow = segment * segmentSize;
            int endRow = startRow + segmentSize;

            // Identify the character that must fill this entire segment
            char requiredChar = grid[startRow][0];

            // Verify every cell in the segment matches the required character
            for (int i = startRow; i < endRow; i++) {
                for (int j = 0; j < colCount; j++) {
                    if (grid[i][j] != requiredChar) {
                        return false;
                    }
                }
            }
            uniqueSegmentChars.add(requiredChar);
        }

        // The pattern is valid only if all three segments use different characters
        return uniqueSegmentChars.size() == 3;
    }

    /**
     * Performs a matrix transposition (swaps rows and columns).
     */
    private static char[][] transpose(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        char[][] transposed = new char[cols][rows];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                transposed[j][i] = grid[i][j];
            }
        }
        return transposed;
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public String nextLine() throws IOException {
            return reader.readLine();
        }
    }
}

import java.util.Scanner;

/**
 * This program analyzes a grid of characters ('R', 'G', 'B') to determine if it
 * follows a specific uniform pattern.
 */
public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rowCount = scanner.nextInt();
        int colCount = scanner.nextInt();
        scanner.nextLine(); // Consume the remaining newline character

        String[] grid = new String[rowCount];
        for (int i = 0; i < rowCount; i++) {
            grid[i] = scanner.nextLine();
        }

        if (isValidGridPattern(grid, rowCount, colCount)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Orchestrates the validation logic for the grid.
     * 
     * @param grid The 2D array of characters.
     * @param rows Number of rows.
     * @param cols Number of columns.
     * @return true if the grid satisfies the pattern requirements.
     */
    private static boolean isValidGridPattern(String[] grid, int rows, int cols) {
        boolean allRowsUniform = true;
        for (String row : grid) {
            if (!isUniform(row)) {
                allRowsUniform = false;
                break;
            }
        }

        boolean allColsUniform = true;
        for (int j = 0; j < cols; j++) {
            if (!isColumnUniform(grid, j)) {
                allColsUniform = false;
                break;
            }
        }

        // If neither rows nor columns are uniform, the pattern is invalid.
        if (!allRowsUniform && !allColsUniform) {
            return false;
        }

        // If all rows are uniform, the grid's pattern is determined by the vertical sequence.
        if (allRowsUniform) {
            return isValidSequence(getVerticalSequence(grid, rows));
        } 

        // If all columns are uniform (and we passed the first check), the pattern 
        // is determined by the horizontal sequence of the first row.
        return isValidSequence(grid[0]);
    }

    /**
     * Checks if all characters in a string are the same.
     */
    private static boolean isUniform(String s) {
        if (s == null || s.isEmpty()) {
            return true;
        }
        char first = s.charAt(0);
        for (int i = 1; i < s.length(); i++) {
            if (s.charAt(i) != first) {
                return false;
            }
        }
        return true;
    }

    /**
     * Checks if all characters in a specific column of the grid are the same.
     */
    private static boolean isColumnUniform(String[] grid, int colIndex) {
        if (grid.length == 0) {
            return true;
        }
        char first = grid[0].charAt(colIndex);
        for (int i = 1; i < grid.length; i++) {
            if (grid[i].charAt(colIndex) != first) {
                return false;
            }
        }
        return true;
    }

    /**
     * Extracts the first character of every row to form a vertical sequence.
     */
    private static String getVerticalSequence(String[] grid, int rows) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < rows; i++) {
            sb.append(grid[i].charAt(0));
        }
        return sb.toString();
    }

    /**
     * Validates the color sequence.
     * A valid sequence must have an equal count of R, G, and B, and 
     * no color can reappear in the sequence of transitions.
     */
    private static boolean isValidSequence(String sequence) {
        int rCount = 0, gCount = 0, bCount = 0;
        boolean rSeenInTransition = false;
        boolean gSeenInTransition = false;
        boolean bSeenInTransition = false;

        for (int i = 0; i < sequence.length(); i++) {
            char current = sequence.charAt(i);

            // 1. Count occurrences
            if (current == 'R') rCount++;
            else if (current == 'G') gCount++;
            else if (current == 'B') bCount++;

            // 2. Check for repeating color transitions
            if (i > 0) {
                char previous = sequence.charAt(i - 1);
                if (current != previous) {
                    // The 'previous' color has finished its contiguous block.
                    // We track if this color has already finished a block before.
                    if (previous == 'R') {
                        if (rSeenInTransition) return false;
                        rSeenInTransition = true;
                    } else if (previous == 'G') {
                        if (gSeenInTransition) return false;
                        gSeenInTransition = true;
                    } else if (previous == 'B') {
                        if (bSeenInTransition) return false;
                        bSeenInTransition = true;
                    }
                }
            }
        }

        // Final requirement: Equal counts of all colors
        return rCount == gCount && gCount == bCount;
    }
}

import java.util.*;
import java.io.*;

/**
 * Solution to determine if a grid can be partitioned into three equal strips 
 * (either horizontally or vertically) such that each strip contains exactly 
 * one unique color and the three colors are 'R', 'G', and 'B'.
 */
public class CFEdu26B {

    private static final char RED = 'R';
    private static final char GREEN = 'G';
    private static final char BLUE = 'B';

    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int numRows = in.nextInt();
        int numCols = in.nextInt();
        char[][] grid = new char[numRows][numCols];

        for (int i = 0; i < numRows; i++) {
            String row = in.next();
            for (int j = 0; j < numCols; j++) {
                grid[i][j] = row.charAt(j);
            }
        }

        boolean isPossible = false;

        // Check horizontal strips if rows are divisible by 3
        if (numRows % 3 == 0) {
            if (checkHorizontalStrips(grid, numRows, numCols)) {
                isPossible = true;
            }
        }

        // Check vertical strips if columns are divisible by 3
        if (!isPossible && numCols % 3 == 0) {
            if (checkVerticalStrips(grid, numRows, numCols)) {
                isPossible = true;
            }
        }

        out.println(isPossible ? "YES" : "NO");
        out.close();
    }

    private static boolean checkHorizontalStrips(char[][] grid, int numRows, int numCols) {
        int stripSize = numRows / 3;
        Set<Character> strip1 = new HashSet<>();
        Set<Character> strip2 = new HashSet<>();
        Set<Character> strip3 = new HashSet<>();

        for (int i = 0; i < stripSize; i++) {
            for (int j = 0; j < numCols; j++) {
                strip1.add(grid[i][j]);
            }
        }
        for (int i = stripSize; i < 2 * stripSize; i++) {
            for (int j = 0; j < numCols; j++) {
                strip2.add(grid[i][j]);
            }
        }
        for (int i = 2 * stripSize; i < numRows; i++) {
            for (int j = 0; j < numCols; j++) {
                strip3.add(grid[i][j]);
            }
        }

        return isRGBPermutation(strip1, strip2, strip3);
    }

    private static boolean checkVerticalStrips(char[][] grid, int numRows, int numCols) {
        int stripSize = numCols / 3;
        Set<Character> strip1 = new HashSet<>();
        Set<Character> strip2 = new HashSet<>();
        Set<Character> strip3 = new HashSet<>();

        for (int j = 0; j < stripSize; j++) {
            for (int i = 0; i < numRows; i++) {
                strip1.add(grid[i][j]);
            }
        }
        for (int j = stripSize; j < 2 * stripSize; j++) {
            for (int i = 0; i < numRows; i++) {
                strip2.add(grid[i][j]);
            }
        }
        for (int j = 2 * stripSize; j < numCols; j++) {
            for (int i = 0; i < numRows; i++) {
                strip3.add(grid[i][j]);
            }
        }

        return isRGBPermutation(strip1, strip2, strip3);
    }

    /**
     * Validates if the three sets of characters represent a permutation of R, G, and B.
     */
    private static boolean isRGBPermutation(Set<Character> s1, Set<Character> s2, Set<Character> s3) {
        // Each strip must contain exactly one unique color
        if (s1.size() != 1 || s2.size() != 1 || s3.size() != 1) {
            return false;
        }

        // The three colors combined must be exactly R, G, and B
        Set<Character> distinctColors = new HashSet<>();
        distinctColors.add(s1.iterator().next());
        distinctColors.add(s2.iterator().next());
        distinctColors.add(s3.iterator().next());

        return distinctColors.size() == 3 
                && distinctColors.contains(RED) 
                && distinctColors.contains(GREEN) 
                && distinctColors.contains(BLUE);
    }

    /**
     * Efficient input reader for fast I/O.
     */
    static class InputReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream inputstream) {
            reader = new BufferedReader(new InputStreamReader(inputstream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }
    }
}

import java.util.Scanner;

/**
 * GridPatternChecker determines if a grid of colors can be represented
 * as a series of uniform horizontal or vertical stripes where each color
 * (Red, Green, Blue) appears an equal number of times.
 */
public class GridPatternChecker {

    private static final char RED = 'R';
    private static final char GREEN = 'G';
    private static final char BLUE = 'B';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        // If neither dimension is a multiple of 3, a valid pattern is mathematically impossible
        if (rows % 3 != 0 && cols % 3 != 0) {
            System.out.println("NO");
            return;
        }

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            grid[i] = line.toCharArray();
        }

        if (isPatternValid(grid, rows, cols)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Orchestrates the check for both horizontal and vertical stripe patterns.
     */
    private static boolean isPatternValid(char[][] grid, int rows, int cols) {
        // Check for valid horizontal stripes (where each row is a single color)
        if (rows % 3 == 0) {
            char[] horizontalStripes = getHorizontalStripes(grid, rows, cols);
            if (horizontalStripes != null && isValidSequence(horizontalStripes)) {
                return true;
            }
        }

        // Check for valid vertical stripes (where each column is a single color)
        if (cols % 3 == 0) {
            char[] verticalStripes = getVerticalStripes(grid, rows, cols);
            if (verticalStripes != null && isValidSequence(verticalStripes)) {
                return true;
            }
        }

        return false;
    }

    /**
     * Extracts the color of each row. Returns null if any row is not uniform.
     */
    private static char[] getHorizontalStripes(char[][] grid, int rows, int cols) {
        char[] stripes = new char[rows];
        for (int i = 0; i < rows; i++) {
            char rowColor = grid[i][0];
            for (int j = 1; j < cols; j++) {
                if (grid[i][j] != rowColor) {
                    return null;
                }
            }
            stripes[i] = rowColor;
        }
        return stripes;
    }

    /**
     * Extracts the color of each column. Returns null if any column is not uniform.
     */
    private static char[] getVerticalStripes(char[][] grid, int rows, int cols) {
        char[] stripes = new char[cols];
        for (int j = 0; j < cols; j++) {
            char colColor = grid[0][j];
            for (int i = 1; i < rows; i++) {
                if (grid[i][j] != colColor) {
                    return null;
                }
            }
            stripes[j] = colColor;
        }
        return stripes;
    }

    /**
     * Validates that the sequence of colors contains equal amounts of R, G, and B,
     * and that colors appear in contiguous blocks (exactly 2 color transitions).
     */
    private static boolean isValidSequence(char[] sequence) {
        int rCount = 0, gCount = 0, bCount = 0;
        int transitions = 0;

        for (int i = 0; i < sequence.length; i++) {
            char currentColor = sequence[i];

            if (currentColor == RED) rCount++;
            else if (currentColor == GREEN) gCount++;
            else if (currentColor == BLUE) bCount++;

            if (i > 0 && currentColor != sequence[i - 1]) {
                transitions++;
            }
        }

        // To be valid, all colors must be present in equal amounts,
        // and there must be exactly 2 transitions (e.g., RRR -> GGG -> BBB)
        boolean equalCounts = (rCount > 0 && rCount == gCount && gCount == bCount);
        return equalCounts && transitions == 2;
    }
}

import java.util.Scanner;

/**
 * Validates whether a 2D grid represents a flag.
 * A flag consists of three equal-sized stripes (horizontal or vertical)
 * where each stripe is a single color, and all three colors are distinct.
 */
public class FlagValidator {

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = scanner.next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }

            if (isValidFlag(grid)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /**
     * Orchestrates the validation logic for both horizontal and vertical orientations.
     */
    public static boolean isValidFlag(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;

        return isVerticalStripeFlag(grid, rows, cols) || isHorizontalStripeFlag(grid, rows, cols);
    }

    /**
     * Checks if the flag consists of three vertical stripes.
     */
    private static boolean isVerticalStripeFlag(char[][] grid, int rows, int cols) {
        if (cols % 3 != 0) {
            return false;
        }

        int stripeWidth = cols / 3;
        char color1 = grid[0][0];
        char color2 = grid[0][stripeWidth];
        char color3 = grid[0][2 * stripeWidth];

        // Colors must be distinct
        if (color1 == color2 || color2 == color3 || color1 == color3) {
            return false;
        }

        // Each vertical stripe must be uniform
        return isUniformRegion(grid, 0, rows, 0, stripeWidth) &&
               isUniformRegion(grid, 0, rows, stripeWidth, 2 * stripeWidth) &&
               isUniformRegion(grid, 0, rows, 2 * stripeWidth, cols);
    }

    /**
     * Checks if the flag consists of three horizontal stripes.
     */
    private static boolean isHorizontalStripeFlag(char[][] grid, int rows, int cols) {
        if (rows % 3 != 0) {
            return false;
        }

        int stripeHeight = rows / 3;
        char color1 = grid[0][0];
        char color2 = grid[stripeHeight][0];
        char color3 = grid[2 * stripeHeight][0];

        // Colors must be distinct
        if (color1 == color2 || color2 == color3 || color1 == color3) {
            return false;
        }

        // Each horizontal stripe must be uniform
        return isUniformRegion(grid, 0, stripeHeight, 0, cols) &&
               isUniformRegion(grid, stripeHeight, 2 * stripeHeight, 0, cols) &&
               isUniformRegion(grid, 2 * stripeHeight, rows, 0, cols);
    }

    /**
     * Checks if all characters within a specified rectangular boundary are the same.
     * 
     * @param grid The 2D array to check.
     * @param startRow Starting row index (inclusive).
     * @param endRow Ending row index (exclusive).
     * @param startCol Starting column index (inclusive).
     * @param endCol Ending column index (exclusive).
     * @return true if the region is uniform, false otherwise.
     */
    private static boolean isUniformRegion(char[][] grid, int startRow, int endRow, int startCol, int endCol) {
        char targetColor = grid[startRow][startCol];
        for (int i = startRow; i < endRow; i++) {
            for (int j = startCol; j < endCol; j++) {
                if (grid[i][j] != targetColor) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.util.Scanner;
import java.io.PrintWriter;

/**
 * Main class to execute the grid pattern solving logic.
 */
public class Main {
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter writer = new PrintWriter(System.out)) {

            GridPatternSolver solver = new GridPatternSolver();
            solver.solve(scanner, writer);
        }
    }

    /**
     * Logic for solving the grid pattern problem.
     */
    static class GridPatternSolver {

        private static final String RESULT_YES = "YES";
        private static final String RESULT_NO = "NO";

        /**
         * Reads input, evaluates the grid, and writes the result.
         * 
         * @param in   The scanner for input.
         * @param out  The writer for output.
         */
        public void solve(Scanner in, PrintWriter out) {
            if (!in.hasNextInt()) return;

            int rowCount = in.nextInt();
            int colCount = in.nextInt();
            char[][] grid = readGrid(in, rowCount, colCount);

            if (isPatternPresent(rowCount, colCount, grid)) {
                out.println(RESULT_YES);
            } else {
                out.println(RESULT_NO);
            }
        }

        /**
         * Checks if the grid satisfies either the horizontal or vertical monochromatic block pattern.
         */
        private boolean isPatternPresent(int rows, int cols, char[][] grid) {
            return (rows % 3 == 0 && checkHorizontalPattern(rows, cols, grid)) ||
                   (cols % 3 == 0 && checkVerticalPattern(rows, cols, grid));
        }

        /**
         * Reads the character grid from the scanner.
         */
        private char[][] readGrid(Scanner in, int rows, int cols) {
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = in.next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }
            return grid;
        }

        /**
         * Checks if the grid is composed of 3 horizontal bands of different monochromatic characters.
         */
        private boolean checkHorizontalPattern(int rows, int cols, char[][] grid) {
            int blockSize = rows / 3;
            char[] blockCharacters = new char[3];

            for (int b = 0; b < 3; b++) {
                int startRow = b * blockSize;
                char expectedChar = grid[startRow][0];
                blockCharacters[b] = expectedChar;

                // Verify every cell in this horizontal block matches the expected character
                for (int r = startRow; r < startRow + blockSize; r++) {
                    for (int c = 0; c < cols; c++) {
                        if (grid[r][c] != expectedChar) {
                            return false;
                        }
                    }
                }
            }

            return areCharactersUnique(blockCharacters);
        }

        /**
         * Checks if the grid is composed of 3 vertical bands of different monochromatic characters.
         */
        private boolean checkVerticalPattern(int rows, int cols, char[][] grid) {
            int blockSize = cols / 3;
            char[] blockCharacters = new char[3];

            for (int b = 0; b < 3; b++) {
                int startCol = b * blockSize;
                char expectedChar = grid[0][startCol];
                blockCharacters[b] = expectedChar;

                // Verify every cell in this vertical block matches the expected character
                for (int r = 0; r < rows; r++) {
                    for (int c = startCol; c < startCol + blockSize; c++) {
                        if (grid[r][c] != expectedChar) {
                            return false;
                        }
                    }
                }
            }

            return areCharactersUnique(blockCharacters);
        }

        /**
         * Ensures that the three detected block characters are distinct.
         */
        private boolean areCharactersUnique(char[] chars) {
            return chars[0] != chars[1] && 
                   chars[1] != chars[2] && 
                   chars[0] != chars[2];
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * Solves the problem of determining if a grid of colors (R, G, B) 
 * can be partitioned into three equal-sized monochromatic blocks 
 * either horizontally or vertically.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        int rows = reader.nextInt();
        int cols = reader.nextInt();

        if (rows <= 0 || cols <= 0) {
            System.out.println("NO");
            return;
        }

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = reader.nextLine().toCharArray();
        }

        GridAnalyzer analyzer = new GridAnalyzer(grid, rows, cols);

        if (analyzer.canBePartitioned()) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Handles the logic for analyzing the grid partitions.
     */
    static class GridAnalyzer {
        private final char[][] grid;
        private final int rows;
        private final int cols;

        public GridAnalyzer(char[][] grid, int rows, int cols) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
        }

        public boolean canBePartitioned() {
            return checkHorizontalSplit() || checkVerticalSplit();
        }

        private boolean checkHorizontalSplit() {
            if (rows % 3 != 0) return false;

            int blockSize = rows / 3;
            char[] colors = new char[3];

            for (int segment = 0; segment < 3; segment++) {
                int startRow = segment * blockSize;
                int endRow = startRow + blockSize;

                char segmentColor = grid[startRow][0];
                if (!isUniform(startRow, endRow, 0, cols, segmentColor)) {
                    return false;
                }
                colors[segment] = segmentColor;
            }

            return areColorsDistinct(colors);
        }

        private boolean checkVerticalSplit() {
            if (cols % 3 != 0) return false;

            int blockSize = cols / 3;
            char[] colors = new char[3];

            for (int segment = 0; segment < 3; segment++) {
                int startCol = segment * blockSize;
                int endCol = startCol + blockSize;

                char segmentColor = grid[0][startCol];
                if (!isUniform(0, rows, startCol, endCol, segmentColor)) {
                    return false;
                }
                colors[segment] = segmentColor;
            }

            return areColorsDistinct(colors);
        }

        /**
         * Checks if a rectangular sub-section of the grid is filled with a single color.
         */
        private boolean isUniform(int rStart, int rEnd, int cStart, int cEnd, char color) {
            for (int i = rStart; i < rEnd; i++) {
                for (int j = cStart; j < cEnd; j++) {
                    if (grid[i][j] != color) {
                        return false;
                    }
                }
            }
            return true;
        }

        /**
         * Ensures that all segments in the partition have different colors.
         */
        private boolean areColorsDistinct(char[] colors) {
            return colors[0] != colors[1] && colors[1] != colors[2] && colors[0] != colors[2];
        }
    }

    /**
     * Utility class for fast input reading.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public String nextLine() {
            String str = "";
            try {
                str = reader.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to determine if a grid follows a specific striped pattern 
 * of 'R', 'G', and 'B' blocks.
 */
public class Main {
    public static void main(String[] args) {
        FastReader in = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        GridPatternSolver solver = new GridPatternSolver();
        solver.solve(in, out);

        out.close();
    }

    static class GridPatternSolver {

        /**
         * Orchestrates the logic to solve the grid pattern problem.
         */
        public void solve(FastReader in, PrintWriter out) {
            int rowCount = in.nextInt();
            int colCount = in.nextInt();
            char[][] grid = new char[rowCount][colCount];

            for (int i = 0; i < rowCount; i++) {
                grid[i] = in.next().toCharArray();
            }

            if (isFirstRowUniform(grid, colCount)) {
                // If the first row is uniform, we look for horizontal stripes 
                // (columns follow the pattern, and all columns are identical).
                if (rowCount % 3 == 0 && 
                    isValidRgbPattern(getColumnString(grid, 0, rowCount)) && 
                    areAllColumnsIdentical(grid, rowCount, colCount)) {
                    out.println("YES");
                } else {
                    out.println("NO");
                }
            } else {
                // If the first row is not uniform, we look for vertical stripes 
                // (rows follow the pattern, and all rows are identical).
                if (colCount % 3 == 0 && 
                    isValidRgbPattern(getRowString(grid, 0, colCount)) && 
                    areAllRowsIdentical(grid, rowCount, colCount)) {
                    out.println("YES");
                } else {
                    out.println("NO");
                }
            }
        }

        private boolean isFirstRowUniform(char[][] grid, int colCount) {
            char firstChar = grid[0][0];
            for (int j = 1; j < colCount; j++) {
                if (grid[0][j] != firstChar) {
                    return false;
                }
            }
            return true;
        }

        private String getRowString(char[][] grid, int rowIndex, int colCount) {
            return new String(grid[rowIndex]);
        }

        private String getColumnString(char[][] grid, int colIndex, int rowCount) {
            StringBuilder sb = new StringBuilder(rowCount);
            for (int i = 0; i < rowCount; i++) {
                sb.append(grid[i][colIndex]);
            }
            return sb.toString();
        }

        private boolean areAllColumnsIdentical(char[][] grid, int rowCount, int colCount) {
            for (int j = 1; j < colCount; j++) {
                for (int i = 0; i < rowCount; i++) {
                    if (grid[i][j] != grid[i][0]) {
                        return false;
                    }
                }
            }
            return true;
        }

        private boolean areAllRowsIdentical(char[][] grid, int rowCount, int colCount) {
            for (int i = 1; i < rowCount; i++) {
                for (int j = 0; j < colCount; j++) {
                    if (grid[i][j] != grid[0][j]) {
                        return false;
                    }
                }
            }
            return true;
        }

        /**
         * Validates if a string consists of three contiguous blocks of 'R', 'G', and 'B'
         * each with a length of exactly s.length() / 3.
         */
        private boolean isValidRgbPattern(String s) {
            int len = s.length();
            if (len % 3 != 0) return false;
            int blockSize = len / 3;

            return checkContiguousBlock(s, 'R', blockSize) &&
                   checkContiguousBlock(s, 'G', blockSize) &&
                   checkContiguousBlock(s, 'B', blockSize);
        }

        private boolean checkContiguousBlock(String s, char target, int blockSize) {
            int firstIdx = s.indexOf(target);
            int lastIdx = s.lastIndexOf(target);

            // If char not found or the span of the char is not exactly the blockSize
            if (firstIdx == -1 || (lastIdx - firstIdx + 1) != blockSize) {
                return false;
            }

            // Verify that every character in that span is actually the target character
            for (int i = firstIdx; i <= lastIdx; i++) {
                if (s.charAt(i) != target) return false;
            }

            return true;
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in), 1 << 20);
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

/**
 * A utility class to validate if a grid represents a valid Berland flag.
 * A valid flag consists of horizontal or vertical stripes of three colors (R, G, B),
 * where each color is contiguous and all three colors appear in equal quantities.
 */
public class BerlandFlag {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        char[][] grid = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            String rowString = scanner.next();
            grid[i] = rowString.toCharArray();
        }

        if (isValidFlag(grid, rows, cols)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Determines if the provided grid meets the Berland flag criteria.
     */
    private static boolean isValidFlag(char[][] grid, int rows, int cols) {
        // Check for vertical stripes (All rows are identical)
        if (areRowsIdentical(grid, rows, cols)) {
            if (isPatternValid(grid[0])) {
                return true;
            }
        }

        // Check for horizontal stripes (All columns are identical)
        if (areColsIdentical(grid, rows, cols)) {
            char[] firstCol = new char[rows];
            for (int i = 0; i < rows; i++) {
                firstCol[i] = grid[i][0];
            }
            if (isPatternValid(firstCol)) {
                return true;
            }
        }

        return false;
    }

    /**
     * Checks if every row in the grid is identical to the first row.
     */
    private static boolean areRowsIdentical(char[][] grid, int rows, int cols) {
        for (int i = 1; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] != grid[0][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Checks if every column in the grid is identical to the first column.
     */
    private static boolean areColsIdentical(char[][] grid, int rows, int cols) {
        for (int j = 1; j < cols; j++) {
            for (int i = 0; i < rows; i++) {
                if (grid[i][j] != grid[i][0]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Validates if a single strip (row or column) follows the R-G-B pattern:
     * 1. Contains only R, G, and B.
     * 2. Each color appears exactly 1/3 of the time.
     * 3. Each color forms a single contiguous block (exactly 2 color transitions).
     */
    private static boolean isPatternValid(char[] strip) {
        int length = strip.length;
        if (length % 3 != 0) {
            return false;
        }

        int countR = 0, countG = 0, countB = 0;
        int transitions = 0;

        for (int i = 0; i < length; i++) {
            char currentColor = strip[i];

            // Count colors
            if (currentColor == 'R') countR++;
            else if (currentColor == 'G') countG++;
            else if (currentColor == 'B') countB++;
            else return false; // Invalid character found

            // Count color transitions
            if (i > 0 && currentColor != strip[i - 1]) {
                transitions++;
            }
        }

        int expectedCount = length / 3;
        boolean countsAreEqual = (countR == expectedCount && 
                                  countG == expectedCount && 
                                  countB == expectedCount);

        // A valid strip must have exactly 2 transitions (e.g., R->G and G->B)
        return countsAreEqual && transitions == 2;
    }
}

