/**
 * Entry point for the Flag of Berland problem.
 * Orchestrates input reading, validation, and output.
 */
public class FlagOfBerland {

    public static void main(String[] args) {
        try (FastReader reader = new FastReader(System.in);
             PrintWriter writer = new PrintWriter(System.out)) {

            int rows = reader.nextInt();
            int cols = reader.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            FlagValidator validator = new FlagValidator();
            boolean isValid = validator.isValid(rows, cols, grid);

            writer.println(isValid ? "YES" : "NO");
            writer.flush();

        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * Contains the core logic for validating the Berland Flag rules.
     */
    static class FlagValidator {

        /**
         * Validates if the grid represents a valid flag (3 equal stripes of distinct colors).
         */
        public boolean isValid(int rows, int cols, char[][] grid) {
            return checkHorizontalStripes(rows, cols, grid) || 
                   checkVerticalStripes(rows, cols, grid);
        }

        private boolean checkHorizontalStripes(int rows, int cols, char[][] grid) {
            if (rows % 3 != 0) {
                return false;
            }

            int stripeHeight = rows / 3;
            char color1 = grid[0][0];
            char color2 = grid[stripeHeight][0];
            char color3 = grid[2 * stripeHeight][0];

            if (!areColorsDistinct(color1, color2, color3)) {
                return false;
            }

            return isStripeUniform(grid, 0, stripeHeight - 1, 0, cols - 1, color1) &&
                   isStripeUniform(grid, stripeHeight, 2 * stripeHeight - 1, 0, cols - 1, color2) &&
                   isStripeUniform(grid, 2 * stripeHeight, rows - 1, 0, cols - 1, color3);
        }

        private boolean checkVerticalStripes(int rows, int cols, char[][] grid) {
            if (cols % 3 != 0) {
                return false;
            }

            int stripeWidth = cols / 3;
            char color1 = grid[0][0];
            char color2 = grid[0][stripeWidth];
            char color3 = grid[0][2 * stripeWidth];

            if (!areColorsDistinct(color1, color2, color3)) {
                return false;
            }

            return isStripeUniform(grid, 0, rows - 1, 0, stripeWidth - 1, color1) &&
                   isStripeUniform(grid, 0, rows - 1, stripeWidth, 2 * stripeWidth - 1, color2) &&
                   isStripeUniform(grid, 0, rows - 1, 2 * stripeWidth, cols - 1, color3);
        }

        /**
         * Checks if a specific rectangular sub-section of the grid is filled with a single color.
         */
        private boolean isStripeUniform(char[][] grid, int rStart, int rEnd, int cStart, int cEnd, char expectedColor) {
            for (int r = rStart; r <= rEnd; r++) {
                for (int c = cStart; c <= cEnd; c++) {
                    if (grid[r][c] != expectedColor) {
                        return false;
                    }
                }
            }
            return true;
        }

        private boolean areColorsDistinct(char c1, char c2, char c3) {
            return c1 != c2 && c2 != c3 && c1 != c3;
        }
    }

    /**
     * High-performance input reader for large datasets.
     */
    static class FastReader implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        @Override
        public void close() throws IOException {
            reader.close();
        }
    }
}

