/**
 * Represents the dimensions of a rectangular area found in the grid.
 */
class BoundingBox {
    private final int height;
    private final int width;
    private final boolean isValid;

    private BoundingBox(int height, int width, boolean isValid) {
        this.height = height;
        this.width = width;
        this.isValid = isValid;
    }

    public static BoundingBox valid(int height, int width) {
        return new BoundingBox(height, width, true);
    }

    public static BoundingBox invalid() {
        return new BoundingBox(0, 0, false);
    }

    public int getHeight() { return height; }
    public int getWidth() { return width; }
    public boolean isValid() { return isValid; }

    public boolean hasSameDimensionsAs(BoundingBox other) {
        if (!this.isValid || !other.isValid) return false;
        return this.height == other.height && this.width == other.width;
    }
}

/**
 * Handles the logic for analyzing the color grid.
 */
class ColorGridAnalyzer {
    private final FastReader reader;
    private char[][] grid;
    private int rowCount;
    private int colCount;

    public ColorGridAnalyzer(FastReader reader) {
        this.reader = reader;
    }

    /**
     * Performs the grid analysis.
     * @return true if all colors ('R', 'G', 'B') form solid rectangles of the same dimensions.
     */
    public boolean analyze() {
        rowCount = reader.nextInt();
        colCount = reader.nextInt();
        grid = new char[rowCount][colCount];

        for (int i = 0; i < rowCount; i++) {
            grid[i] = reader.next().toCharArray();
        }

        BoundingBox redBox = calculateBoundingBox('R');
        BoundingBox greenBox = calculateBoundingBox('G');
        BoundingBox blueBox = calculateBoundingBox('B');

        // The condition requires all colors to be present, valid, and identical in size.
        return redBox.isValid() && 
               redBox.hasSameDimensionsAs(greenBox) && 
               greenBox.hasSameDimensionsAs(blueBox);
    }

    /**
     * Finds the bounding box of a specific color and verifies if it forms a solid rectangle.
     */
    private BoundingBox calculateBoundingBox(char targetColor) {
        int minRow = Integer.MAX_VALUE, maxRow = Integer.MIN_VALUE;
        int minCol = Integer.MAX_VALUE, maxCol = Integer.MIN_VALUE;
        int colorCount = 0;

        for (int i = 0; i < rowCount; i++) {
            for (int j = 0; j < colCount; j++) {
                if (grid[i][j] == targetColor) {
                    colorCount++;
                    minRow = Math.min(minRow, i);
                    maxRow = Math.max(maxRow, i);
                    minCol = Math.min(minCol, j);
                    maxCol = Math.max(maxCol, j);
                }
            }
        }

        if (colorCount == 0) {
            return BoundingBox.invalid();
        }

        int height = maxRow - minRow + 1;
        int width = maxCol - minCol + 1;

        // A color forms a solid rectangle if the area of its bounding box 
        // equals the total count of that color's occurrences.
        if (height * width == colorCount) {
            return BoundingBox.valid(height, width);
        } else {
            return BoundingBox.invalid();
        }
    }
}

