/**
 * Handles the core logic of validating grid patterns.
 */
class PatternSolver {

    /**
     * Orchestrates the solving process: reads input, checks the grid,
     * potentially transposes it, and checks again.
     */
    public void solve(FastScanner scanner, PrintWriter out) {
        int rowCount = scanner.nextInt();
        // The original code consumed an extra token after the integer.
        // We maintain this to preserve identical input consumption behavior.
        String unusedMetadata = scanner.next();

        char[][] grid = new char[rowCount][];
        for (int i = 0; i < rowCount; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        if (isThreeBlockPattern(grid) || isThreeBlockPattern(transpose(grid))) {
            out.println("YES");
        } else {
            out.println("NO");
        }
    }

    /**
     * Checks if the grid consists of three equal horizontal blocks,
     * where each block contains only one unique character,
     * and the characters used in the three blocks are all distinct.
     */
    private boolean isThreeBlockPattern(char[][] grid) {
        int rowCount = grid.length;
        if (rowCount == 0) return false;
        int colCount = grid[0].length;

        if (rowCount % 3 != 0) {
            return false;
        }

        int blockSize = rowCount / 3;
        char[] blockCharacters = new char[3];

        for (int blockIdx = 0; blockIdx < 3; blockIdx++) {
            int startRow = blockIdx * blockSize;
            char targetChar = grid[startRow][0];
            blockCharacters[blockIdx] = targetChar;

            // Validate that every cell in this block matches the block's character
            for (int r = startRow; r < startRow + blockSize; r++) {
                for (int c = 0; c < colCount; c++) {
                    if (grid[r][c] != targetChar) {
                        return false;
                    }
                }
            }
        }

        // Validate that the three block characters are unique from each other
        return blockCharacters[0] != blockCharacters[1] &&
               blockCharacters[0] != blockCharacters[2] &&
               blockCharacters[1] != blockCharacters[2];
    }

    /**
     * Returns a new 2D array that is the transpose of the input grid.
     */
    private char[][] transpose(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        char[][] transposed = new char[cols][rows];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                transposed[j][i] = grid[i][j];
            }
        }
        return transposed;
    }
}

