import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Set;

/**
 * Analyzes a color grid to determine if it can be divided into three 
 * equal-sized rectangular bands of different colors (Red, Green, Blue).
 */
public class ColorGridPatternChecker {

    private static final Set<Character> REQUIRED_COLORS = Set.of('R', 'G', 'B');
    private static final char INVALID_COLOR = '\0';

    public static void main(String[] args) {
        try {
            FastReader reader = new FastReader();
            int[] dimensions = reader.readIntArray();

            if (dimensions.length < 2) {
                System.out.println("NO");
                return;
            }

            int width = dimensions[1];
            int height = dimensions[0];

            char[][] grid = reader.readGrid(height);

            if (isValidPattern(grid, width, height)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }

        } catch (Exception e) {
            // In a production environment, use a logger.
            System.out.println("NO");
        }
    }

    /**
     * Orchestrates the pattern detection logic.
     */
    private static boolean isValidPattern(char[][] grid, int width, int height) {
        // Requirement: Total area must be divisible by 3
        if ((width * height) % 3 != 0) {
            return false;
        }

        // Determine orientation based on whether the first row is uniform
        if (isRowUniform(grid[0])) {
            return checkHorizontalStripes(grid, width, height);
        } else {
            return checkVerticalStripes(grid, width, height);
        }
    }

    private static boolean isRowUniform(char[] row) {
        if (row.length == 0) return true;
        char first = row[0];
        for (char c : row) {
            if (c != first) return false;
        }
        return true;
    }

    /**
     * Checks if the grid is composed of three horizontal bands.
     */
    private static boolean checkHorizontalStripes(char[][] grid, int width, int height) {
        if (height % 3 != 0) return false;

        int bandHeight = height / 3;
        char color1 = getUniformColor(grid, 0, bandHeight, 0, width);
        char color2 = getUniformColor(grid, bandHeight, 2 * bandHeight, 0, width);
        char color3 = getUniformColor(grid, 2 * bandHeight, height, 0, width);

        return hasRequiredRGB(color1, color2, color3);
    }

    /**
     * Checks if the grid is composed of three vertical bands.
     */
    private static boolean checkVerticalStripes(char[][] grid, int width, int height) {
        if (width % 3 != 0) return false;

        int bandWidth = width / 3;
        char color1 = getUniformColor(grid, 0, height, 0, bandWidth);
        char color2 = getUniformColor(grid, 0, height, bandWidth, 2 * bandWidth);
        char color3 = getUniformColor(grid, 0, height, 2 * bandWidth, width);

        return hasRequiredRGB(color1, color2, color3);
    }

    /**
     * Extracts the color of a rectangular region if that region is uniform.
     * 
     * @return The character color if uniform, otherwise INVALID_COLOR.
     */
    private static char getUniformColor(char[][] grid, int rowStart, int rowEnd, int colStart, int colEnd) {
        char color = grid[rowStart][colStart];
        for (int r = rowStart; r < rowEnd; r++) {
            for (int c = colStart; c < colEnd; c++) {
                if (grid[r][c] != color) {
                    return INVALID_COLOR;
                }
            }
        }
        return color;
    }

    private static boolean hasRequiredRGB(char c1, char c2, char c3) {
        return REQUIRED_COLORS.contains(c1) && 
               REQUIRED_COLORS.contains(c2) && 
               REQUIRED_COLORS.contains(c3) && 
               c1 != c2 && c2 != c3 && c1 != c3;
    }

    /**
     * Utility class for efficient input reading.
     */
    static class FastReader {
        private final BufferedReader reader;

        public FastReader() {
            this.reader = new BufferedReader(new InputStreamReader(System.in));
        }

        public int[] readIntArray() throws IOException {
            String line = reader.readLine();
            if (line == null) return new int[0];
            String[] parts = line.trim().split("\\s+");
            int[] result = new int[parts.length];
            for (int i = 0; i < parts.length; i++) {
                result[i] = Integer.parseInt(parts[i]);
            }
            return result;
        }

        public char[][] readGrid(int height) throws IOException {
            char[][] grid = new char[height][];
            for (int i = 0; i < height; i++) {
                grid[i] = reader.readLine().toCharArray();
            }
            return grid;
        }
    }
}

