/**
 * GridColorPartition determines if a grid of 'R', 'G', and 'B' characters
 * can be partitioned into three equal-sized monochromatic strips 
 * (either horizontally or vertically) such that each strip consists 
 * of a different color.
 */
public class GridColorPartition {

    public static void main(String[] args) {
        new GridColorPartition().execute();
    }

    /**
     * Entry point for the program.
     */
    public void execute() {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            String nStr = reader.next();
            String mStr = reader.next();
            if (nStr == null || mStr == null) return;

            int rows = Integer.parseInt(nStr);
            int cols = Integer.parseInt(mStr);

            String[] grid = new String[rows];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next();
            }

            if (canPartition(rows, cols, grid)) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        } catch (Exception e) {
            // In a production environment, log the exception properly.
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Checks if the grid can be partitioned either horizontally or vertically.
     */
    private boolean canPartition(int rows, int cols, String[] grid) {
        // A partition is only possible if at least one dimension is divisible by 3
        if (rows % 3 != 0 && cols % 3 != 0) {
            return false;
        }

        // Try horizontal slicing (rows divided into 3 equal bands)
        if (rows % 3 == 0 && checkSlices(rows, cols, grid, true)) {
            return true;
        }

        // Try vertical slicing (columns divided into 3 equal bands)
        if (cols % 3 == 0 && checkSlices(rows, cols, grid, false)) {
            return true;
        }

        return false;
    }

    /**
     * Iterates through three equal slices of the grid and verifies that 
     * each slice is monochromatic and uses a unique color.
     *
     * @param rows        Total rows in the grid
     * @param cols        Total columns in the grid
     * @param grid        The grid data
     * @param isHorizontal True to slice by rows, false to slice by columns
     * @return True if three distinct monochromatic slices are found
     */
    private boolean checkSlices(int rows, int cols, String[] grid, boolean isHorizontal) {
        int totalSlices = 3;
        int sliceDimension = isHorizontal ? rows : cols;
        int sliceSize = sliceDimension / 3;

        Set<Character> uniqueColorsFound = new HashSet<>();

        for (int i = 0; i < totalSlices; i++) {
            int start = i * sliceSize;
            int end = (i + 1) * sliceSize;

            Character sliceColor = getMonochromaticColor(start, end, rows, cols, grid, isHorizontal);

            // If the slice is not monochromatic or the color was already used in another slice
            if (sliceColor == null || !uniqueColorsFound.add(sliceColor)) {
                return false;
            }
        }

        // The set must contain exactly 3 colors (R, G, and B)
        return uniqueColorsFound.size() == 3;
    }

    /**
     * Traverses a specific slice of the grid to check if it contains only one character.
     *
     * @return The color of the slice if monochromatic, otherwise null.
     */
    private Character getMonochromaticColor(int start, int end, int rows, int cols, String[] grid, boolean isHorizontal) {
        char detectedColor = 0;

        if (isHorizontal) {
            for (int r = start; r < end; r++) {
                for (int c = 0; c < cols; c++) {
                    char current = grid[r].charAt(c);
                    if (detectedColor == 0) {
                        detectedColor = current;
                    } else if (detectedColor != current) {
                        return null;
                    }
                }
            }
        } else {
            for (int c = start; c < end; c++) {
                for (int r = 0; r < rows; r++) {
                    char current = grid[r].charAt(c);
                    if (detectedColor == 0) {
                        detectedColor = current;
                    } else if (detectedColor != current) {
                        return null;
                    }
                }
            }
        }
        return detectedColor == 0 ? null : detectedColor;
    }

    /**
     * Fast I/O helper class.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }
    }
}

import java.util.Scanner;

/**
 * Analyzes a 2D grid to determine if it can be divided into three equal 
 * monochromatic bands (either horizontally or vertically) where each 
 * band has a unique color.
 */
public class GridPatternAnalyzer {

    private static final int REQUIRED_BANDS = 3;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        char[][] grid = readGrid(scanner, rows, cols);

        if (hasValidPattern(grid, rows, cols)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Reads the grid dimensions from the scanner.
     */
    private static char[][] readGrid(Scanner scanner, int rows, int cols) {
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.next().toCharArray();
        }
        return grid;
    }

    /**
     * Orchestrates the pattern check.
     */
    private static boolean hasValidPattern(char[][] grid, int rows, int cols) {
        return checkHorizontalPattern(grid, rows, cols) || 
               checkVerticalPattern(grid, rows, cols);
    }

    /**
     * Checks if the grid can be split into 3 equal horizontal stripes.
     */
    private static boolean checkHorizontalPattern(char[][] grid, int rows, int cols) {
        if (rows % REQUIRED_BANDS != 0) {
            return false;
        }

        int bandHeight = rows / REQUIRED_BANDS;

        // Identify the expected color of each band based on its first cell
        char color1 = grid[0][0];
        char color2 = grid[bandHeight][0];
        char color3 = grid[2 * bandHeight][0];

        if (!areColorsDistinct(color1, color2, color3)) {
            return false;
        }

        return isBandUniform(grid, 0, bandHeight - 1, 0, cols - 1, color1) &&
               isBandUniform(grid, bandHeight, 2 * bandHeight - 1, 0, cols - 1, color2) &&
               isBandUniform(grid, 2 * bandHeight, rows - 1, 0, cols - 1, color3);
    }

    /**
     * Checks if the grid can be split into 3 equal vertical stripes.
     */
    private static boolean checkVerticalPattern(char[][] grid, int rows, int cols) {
        if (cols % REQUIRED_BANDS != 0) {
            return false;
        }

        int bandWidth = cols / REQUIRED_BANDS;

        // Identify the expected color of each band based on its first cell
        char color1 = grid[0][0];
        char color2 = grid[0][bandWidth];
        char color3 = grid[0][2 * bandWidth];

        if (!areColorsDistinct(color1, color2, color3)) {
            return false;
        }

        return isBandUniform(grid, 0, rows - 1, 0, bandWidth - 1, color1) &&
               isBandUniform(grid, 0, rows - 1, bandWidth, 2 * bandWidth - 1, color2) &&
               isBandUniform(grid, 0, rows - 1, 2 * bandWidth, cols - 1, color3);
    }

    /**
     * Verifies that all characters within the specified rectangular bounds match the target color.
     */
    private static boolean isBandUniform(char[][] grid, int rStart, int rEnd, int cStart, int cEnd, char targetColor) {
        for (int i = rStart; i <= rEnd; i++) {
            for (int j = cStart; j <= cEnd; j++) {
                if (grid[i][j] != targetColor) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Ensures that the three provided colors are all different from one another.
     */
    private static boolean areColorsDistinct(char c1, char c2, char c3) {
        return c1 != c2 && c1 != c3 && c2 != c3;
    }
}

import java.util.HashSet;
import java.util.Scanner;
import java.util.Set;

/**
 * FlagOfBerland determines if a grid represents a valid Berland flag.
 * A valid flag consists of three equal-sized horizontal or vertical bands,
 * each consisting of a single color, and the three colors must be exactly Red, Green, and Blue.
 */
public class FlagOfBerland {

    private static final char COLOR_RED = 'R';
    private static final char COLOR_GREEN = 'G';
    private static final char COLOR_BLUE = 'B';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        scanner.nextLine(); // Consume the newline character

        String[] grid = new String[rows];
        for (int i = 0; i < rows; i++) {
            if (scanner.hasNextLine()) {
                grid[i] = scanner.nextLine();
            }
        }

        if (isValidFlag(grid, rows, cols)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Determines if the grid satisfies the criteria for a Berland flag.
     * 
     * @param grid The 2D grid of characters.
     * @param rows Number of rows in the grid.
     * @param cols Number of columns in the grid.
     * @return true if the grid is a valid flag, false otherwise.
     */
    private static boolean isValidFlag(String[] grid, int rows, int cols) {
        boolean horizontalPattern = (rows % 3 == 0) && checkHorizontalPattern(grid, rows, cols);
        boolean verticalPattern = (cols % 3 == 0) && checkVerticalPattern(grid, rows, cols);

        return horizontalPattern || verticalPattern;
    }

    /**
     * Checks if the grid is composed of three equal-sized horizontal bands of single colors.
     */
    private static boolean checkHorizontalPattern(String[] grid, int rows, int cols) {
        int bandHeight = rows / 3;
        char[] bandColors = new char[3];

        for (int b = 0; b < 3; b++) {
            int startRow = b * bandHeight;
            char color = grid[startRow].charAt(0);
            bandColors[b] = color;

            // Validate that every cell within this band matches the band's color
            for (int r = startRow; r < startRow + bandHeight; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r].charAt(c) != color) {
                        return false;
                    }
                }
            }
        }

        return hasRequiredColors(bandColors);
    }

    /**
     * Checks if the grid is composed of three equal-sized vertical bands of single colors.
     */
    private static boolean checkVerticalPattern(String[] grid, int rows, int cols) {
        int bandWidth = cols / 3;
        char[] bandColors = new char[3];

        for (int b = 0; b < 3; b++) {
            int startCol = b * bandWidth;
            char color = grid[0].charAt(startCol);
            bandColors[b] = color;

            // Validate that every cell within this band matches the band's color
            for (int c = startCol; c < startCol + bandWidth; c++) {
                for (int r = 0; r < rows; r++) {
                    if (grid[r].charAt(c) != color) {
                        return false;
                    }
                }
            }
        }

        return hasRequiredColors(bandColors);
    }

    /**
     * Validates that the provided array of colors contains exactly 'R', 'G', and 'B'.
     * 
     * @param colors An array of the colors found in the three bands.
     * @return true if the colors are a permutation of {R, G, B}.
     */
    private static boolean hasRequiredColors(char[] colors) {
        Set<Character> colorSet = new HashSet<>();
        for (char c : colors) {
            if (c != COLOR_RED && c != COLOR_GREEN && c != COLOR_BLUE) {
                return false;
            }
            colorSet.add(c);
        }
        // A valid flag must have 3 distinct colors from the set {R, G, B}
        return colorSet.size() == 3;
    }
}

