/**
 * GridPatternChecker determines if a character grid can be partitioned into 
 * three equal-sized bands (either horizontally or vertically) where each 
 * band consists of a single uniform color and all three bands have distinct colors.
 */
public class GridPatternChecker {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rowCount = scanner.nextInt();
        int colCount = scanner.nextInt();

        char[][] grid = new char[rowCount][colCount];
        for (int i = 0; i < rowCount; i++) {
            String rowString = scanner.next();
            grid[i] = rowString.toCharArray();
        }

        boolean isValid = checkPatterns(grid, rowCount, colCount);
        System.out.println(isValid ? "YES" : "NO");

        scanner.close();
    }

    /**
     * Evaluates if the grid satisfies the band requirements in either direction.
     */
    private static boolean checkPatterns(char[][] grid, int rows, int cols) {
        // Check horizontal bands if rows are divisible by 3
        if (rows % 3 == 0 && isHorizontalPattern(grid, rows, cols)) {
            return true;
        }

        // Check vertical bands if columns are divisible by 3
        if (cols % 3 == 0 && isVerticalPattern(grid, rows, cols)) {
            return true;
        }

        return false;
    }

    /**
     * Checks if the grid is composed of three horizontal bands of uniform color.
     */
    private static boolean isHorizontalPattern(char[][] grid, int rows, int cols) {
        int bandSize = rows / 3;
        char[] bandColors = new char[3];

        for (int b = 0; b < 3; b++) {
            int startRow = b * bandSize;
            bandColors[b] = grid[startRow][0];

            for (int r = startRow; r < startRow + bandSize; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] != bandColors[b]) {
                        return false;
                    }
                }
            }
        }

        return areColorsDistinct(bandColors);
    }

    /**
     * Checks if the grid is composed of three vertical bands of uniform color.
     */
    private static boolean isVerticalPattern(char[][] grid, int rows, int cols) {
        int bandSize = cols / 3;
        char[] bandColors = new char[3];

        for (int b = 0; b < 3; b++) {
            int startCol = b * bandSize;
            bandColors[b] = grid[0][startCol];

            for (int c = startCol; c < startCol + bandSize; c++) {
                for (int r = 0; r < rows; r++) {
                    if (grid[r][c] != bandColors[b]) {
                        return false;
                    }
                }
            }
        }

        return areColorsDistinct(bandColors);
    }

    /**
     * Verifies that the three provided colors are unique.
     */
    private static boolean areColorsDistinct(char[] colors) {
        return colors[0] != colors[1] && 
               colors[1] != colors[2] && 
               colors[0] != colors[2];
    }
}

