/**
 * Main entry point for the Grid Pattern Solver.
 */
public class Main {
    public static void main(String[] args) {
        try (FastReader in = new FastReader(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            PatternSolver solver = new PatternSolver();
            solver.solve(in, out);

        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}

/**
 * Logic for determining if a grid follows a specific strip pattern.
 */
class PatternSolver {

    /**
     * Solves the problem by checking both the original grid and its transpose.
     */
    public void solve(FastReader in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();

        char[][] matrix = new char[n][m];
        for (int i = 0; i < n; i++) {
            matrix[i] = in.next().toCharArray();
        }

        if (hasThreeUniformStrips(matrix) || hasThreeUniformStrips(transpose(matrix))) {
            out.println("YES");
        } else {
            out.println("NO");
        }
    }

    /**
     * Checks if the matrix is composed of three horizontal strips,
     * where each strip is uniform and the three strips have distinct characters.
     */
    private boolean hasThreeUniformStrips(char[][] matrix) {
        int rows = matrix.length;
        int cols = matrix[0].length;

        if (rows % 3 != 0) {
            return false;
        }

        int segmentHeight = rows / 3;
        char[] stripChars = new char[3];

        for (int s = 0; s < 3; s++) {
            int startRow = s * segmentHeight;
            char targetChar = matrix[startRow][0];
            stripChars[s] = targetChar;

            // Verify all characters in the current segment match the target character
            for (int r = startRow; r < startRow + segmentHeight; r++) {
                for (int c = 0; c < cols; c++) {
                    if (matrix[r][c] != targetChar) {
                        return false;
                    }
                }
            }
        }

        // Verify that the three segments use three different characters
        return stripChars[0] != stripChars[1] &&
               stripChars[1] != stripChars[2] &&
               stripChars[0] != stripChars[2];
    }

    /**
     * Returns a new matrix that is the transpose of the input matrix.
     */
    private char[][] transpose(char[][] matrix) {
        int r = matrix.length;
        int c = matrix[0].length;
        char[][] transposed = new char[c][r];
        for (int i = 0; i < r; i++) {
            for (int j = 0; j < c; j++) {
                transposed[j][i] = matrix[i][j];
            }
        }
        return transposed;
    }
}

/**
 * Efficient reader for large input streams.
 */
class FastReader implements Closeable {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    public FastReader(InputStream stream) {
        this.reader = new BufferedReader(new InputStreamReader(stream), 32768);
    }

    public String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                throw new RuntimeException("Error reading input", e);
            }
        }
        return tokenizer.nextToken();
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }

    public long nextLong() {
        return Long.parseLong(next());
    }

    @Override
    public void close() throws IOException {
        reader.close();
    }
}

import java.util.Scanner;

/**
 * This program determines if a given grid of colors (R, G, B)
 * is composed of three horizontal or three vertical stripes
 * of equal thickness, where each stripe is a unique color.
 */
public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rowCount = scanner.nextInt();
        int colCount = scanner.nextInt();

        char[][] grid = new char[rowCount][colCount];
        for (int i = 0; i < rowCount; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        if (isValidPattern(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Orchestrates the pattern checking logic.
     *
     * @param grid The 2D character array representing the color grid.
     * @return true if a valid stripe pattern is found, false otherwise.
     */
    public static boolean isValidPattern(char[][] grid) {
        if (grid == null || grid.length == 0 || grid[0].length == 0) {
            return false;
        }

        return hasHorizontalStripes(grid) || hasVerticalStripes(grid);
    }

    /**
     * Checks if the grid consists of three horizontal bands of equal height,
     * where each band contains exactly one unique color (R, G, or B).
     */
    private static boolean hasHorizontalStripes(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;

        // For three equal stripes, the number of rows must be divisible by 3
        if (rows % 3 != 0) {
            return false;
        }

        int blockSize = rows / 3;
        char[] stripeColors = new char[3];

        for (int b = 0; b < 3; b++) {
            int startRow = b * blockSize;
            // Determine the color of the current stripe band
            char stripeColor = grid[startRow][0];
            stripeColors[b] = stripeColor;

            // Validate that every cell in this row-block is the same color
            for (int i = startRow; i < startRow + blockSize; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] != stripeColor) {
                        return false;
                    }
                }
            }
        }

        return isRGBPermutation(stripeColors);
    }

    /**
     * Checks if the grid consists of three vertical bands of equal width,
     * where each band contains exactly one unique color (R, G, or B).
     */
    private static boolean hasVerticalStripes(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;

        // For three equal stripes, the number of columns must be divisible by 3
        if (cols % 3 != 0) {
            return false;
        }

        int blockSize = cols / 3;
        char[] stripeColors = new char[3];

        for (int b = 0; b < 3; b++) {
            int startCol = b * blockSize;
            // Determine the color of the current stripe band
            char stripeColor = grid[0][startCol];
            stripeColors[b] = stripeColor;

            // Validate that every cell in this column-block is the same color
            for (int j = startCol; j < startCol + blockSize; j++) {
                for (int i = 0; i < rows; i++) {
                    if (grid[i][j] != stripeColor) {
                        return false;
                    }
                }
            }
        }

        return isRGBPermutation(stripeColors);
    }

    /**
     * Verifies that the identified stripe colors represent a permutation of 'R', 'G', and 'B'.
     *
     * @param colors An array containing the color of each of the three stripes.
     * @return true if the colors are R, G, and B in any order.
     */
    private static boolean isRGBPermutation(char[] colors) {
        boolean hasR = false;
        boolean hasG = false;
        boolean hasB = false;

        for (char c : colors) {
            if (c == 'R') hasR = true;
            else if (c == 'G') hasG = true;
            else if (c == 'B') hasB = true;
        }

        return hasR && hasG && hasB;
    }
}

import java.util.Scanner;

/**
 * A utility class to analyze if a grid follows a specific banding pattern.
 * The pattern requires the grid to be divisible into 3 equal bands 
 * (either horizontally or vertically) where each band consists of 
 * a single unique character.
 */
class MatrixPatternMatcher {

    private final char[][] grid;
    private final int rows;
    private final int cols;

    public MatrixPatternMatcher(char[][] grid, int rows, int cols) {
        this.grid = grid;
        this.rows = rows;
        this.cols = cols;
    }

    /**
     * Determines if the grid matches the required pattern.
     * @return true if the grid has 3 distinct uniform horizontal or vertical bands.
     */
    public boolean isPatternValid() {
        return hasHorizontalPattern() || hasVerticalPattern();
    }

    private boolean hasHorizontalPattern() {
        if (rows % 3 != 0) {
            return false;
        }

        int bandSize = rows / 3;

        char band1 = getUniformChar(0, bandSize - 1, 0, cols - 1);
        char band2 = getUniformChar(bandSize, 2 * bandSize - 1, 0, cols - 1);
        char band3 = getUniformChar(2 * bandSize, rows - 1, 0, cols - 1);

        return areCharsDistinct(band1, band2, band3);
    }

    private boolean hasVerticalPattern() {
        if (cols % 3 != 0) {
            return false;
        }

        int bandSize = cols / 3;

        char band1 = getUniformChar(0, rows - 1, 0, bandSize - 1);
        char band2 = getUniformChar(0, rows - 1, bandSize, 2 * bandSize - 1);
        char band3 = getUniformChar(0, rows - 1, 2 * bandSize, cols - 1);

        return areCharsDistinct(band1, band2, band3);
    }

    /**
     * Checks if all characters within the specified sub-grid boundaries are the same.
     * 
     * @return The character if the sub-grid is uniform, otherwise '\0'.
     */
    private char getUniformChar(int rowStart, int rowEnd, int colStart, int colEnd) {
        char target = grid[rowStart][colStart];
        for (int i = rowStart; i <= rowEnd; i++) {
            for (int j = colStart; j <= colEnd; j++) {
                if (grid[i][j] != target) {
                    return '\0';
                }
            }
        }
        return target;
    }

    /**
     * Validates that three characters are not null and are all unique from one another.
     */
    private boolean areCharsDistinct(char c1, char c2, char c3) {
        if (c1 == '\0' || c2 == '\0' || c3 == '\0') {
            return false;
        }
        return (c1 != c2) && (c2 != c3) && (c1 != c3);
    }
}

