import java.util.HashSet;
import java.util.Scanner;
import java.util.Set;

/**
 * Analyzes a grid of characters to determine if it follows a specific 
 * banded pattern (either 3 horizontal bands or 3 vertical bands).
 */
class GridPatternChecker {

    /**
     * Checks if the grid matches either the horizontal or vertical pattern.
     *
     * @param grid The 2D character array representing the grid.
     * @param rows Number of rows in the grid.
     * @param cols Number of columns in the grid.
     * @return true if the pattern is valid, false otherwise.
     */
    public boolean hasValidPattern(char[][] grid, int rows, int cols) {
        return checkHorizontalPattern(grid, rows, cols) || 
               checkVerticalPattern(grid, rows, cols);
    }

    /**
     * Checks if the grid consists of 3 horizontal bands, where each band 
     * is monochromatic and all three bands have different characters.
     */
    private boolean checkHorizontalPattern(char[][] grid, int rows, int cols) {
        if (rows % 3 != 0) {
            return false;
        }

        int bandHeight = rows / 3;
        Set<Character> distinctCharacters = new HashSet<>();

        for (int band = 0; band < 3; band++) {
            int startRow = band * bandHeight;
            int endRow = startRow + bandHeight;

            // Pick the character of the current band from the first cell of the band
            char bandChar = grid[startRow][0];

            if (!isRegionUniform(grid, startRow, endRow, 0, cols, bandChar)) {
                return false;
            }
            distinctCharacters.add(bandChar);
        }

        return distinctCharacters.size() == 3;
    }

    /**
     * Checks if the grid consists of 3 vertical bands, where each band 
     * is monochromatic and all three bands have different characters.
     */
    private boolean checkVerticalPattern(char[][] grid, int rows, int cols) {
        if (cols % 3 != 0) {
            return false;
        }

        int bandWidth = cols / 3;
        Set<Character> distinctCharacters = new HashSet<>();

        for (int band = 0; band < 3; band++) {
            int startCol = band * bandWidth;
            int endCol = startCol + bandWidth;

            // Pick the character of the current band from the first cell of the band
            char bandChar = grid[0][startCol];

            if (!isRegionUniform(grid, 0, rows, startCol, endCol, bandChar)) {
                return false;
            }
            distinctCharacters.add(bandChar);
        }

        return distinctCharacters.size() == 3;
    }

    /**
     * Verifies if all characters within a specific rectangular region of the grid 
     * match the provided target character.
     */
    private boolean isRegionUniform(char[][] grid, int startRow, int endRow, 
                                    int startCol, int endCol, char target) {
        for (int r = startRow; r < endRow; r++) {
            for (int c = startCol; c < endCol; c++) {
                if (grid[r][c] != target) {
                    return false;
                }
            }
        }
        return true;
    }
}

