import java.util.*;

/**
 * A program to determine if a grid of colors forms a valid 3-stripe pattern,
 * either horizontally or vertically.
 */
public class Main {

    private static final Set<Character> REQUIRED_COLORS = Set.of('R', 'G', 'B');

    /**
     * Represents a continuous block of the same color.
     */
    private static class Stripe {
        final char color;
        final int thickness;

        Stripe(char color, int thickness) {
            this.color = color;
            this.thickness = thickness;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int rowCount = scanner.nextInt();
        int colCount = scanner.nextInt();
        scanner.nextLine(); // Consume newline

        char[][] grid = new char[rowCount][colCount];
        for (int i = 0; i < rowCount; i++) {
            String line = scanner.nextLine();
            grid[i] = line.toCharArray();
        }

        if (isPatternValid(grid, rowCount, colCount)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Checks if the grid follows the 3-stripe pattern horizontally or vertically.
     */
    public static boolean isPatternValid(char[][] grid, int rows, int cols) {
        return checkStripes(grid, rows, cols, true) || checkStripes(grid, rows, cols, false);
    }

    /**
     * Generic logic to extract and validate stripes.
     * 
     * @param horizontal true if checking horizontal stripes (rows), false for vertical (cols).
     */
    private static boolean checkStripes(char[][] grid, int rows, int cols, boolean horizontal) {
        List<Stripe> stripes = new ArrayList<>();

        if (horizontal) {
            for (int i = 0; i < rows; ) {
                if (!isRowUniform(grid, i, cols)) return false;

                char color = grid[i][0];
                int start = i;
                while (i < rows && grid[i][0] == color) {
                    if (!isRowUniform(grid, i, cols)) return false;
                    i++;
                }
                stripes.add(new Stripe(color, i - start));
            }
        } else {
            for (int j = 0; j < cols; ) {
                if (!isColumnUniform(grid, j, rows)) return false;

                char color = grid[0][j];
                int start = j;
                while (j < cols && grid[0][j] == color) {
                    if (!isColumnUniform(grid, j, rows)) return false;
                    j++;
                }
                stripes.add(new Stripe(color, j - start));
            }
        }

        return validateStripeList(stripes);
    }

    /**
     * Validates that there are exactly 3 stripes, they have the same thickness,
     * and they consist of the three unique colors R, G, and B.
     */
    private static boolean validateStripeList(List<Stripe> stripes) {
        if (stripes.size() != 3) {
            return false;
        }

        int requiredThickness = stripes.get(0).thickness;
        Set<Character> foundColors = new HashSet<>();

        for (Stripe stripe : stripes) {
            if (stripe.thickness != requiredThickness) {
                return false;
            }
            foundColors.add(stripe.color);
        }

        return foundColors.equals(REQUIRED_COLORS);
    }

    private static boolean isRowUniform(char[][] grid, int row, int cols) {
        char firstChar = grid[row][0];
        for (int j = 1; j < cols; j++) {
            if (grid[row][j] != firstChar) return false;
        }
        return true;
    }

    private static boolean isColumnUniform(char[][] grid, int col, int rows) {
        char firstChar = grid[0][col];
        for (int i = 1; i < rows; i++) {
            if (grid[i][col] != firstChar) return false;
        }
        return true;
    }
}

