/**
 * A refactored solution to find the largest integer 'x' such that every integer 
 * from 1 to 'x' can be formed by picking exactly one digit from a unique set 
 * among 'n' provided sets of digits.
 */
public class Codeforces {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int numberOfSets = scanner.nextInt();
        List<Set<Integer>> digitSets = new ArrayList<>();

        // Read the n sets of digits
        for (int i = 0; i < numberOfSets; i++) {
            Set<Integer> currentSet = new HashSet<>();
            for (int j = 0; j < 6; j++) {
                if (scanner.hasNextInt()) {
                    currentSet.add(scanner.nextInt());
                }
            }
            digitSets.add(currentSet);
        }

        int lastValidNumber = 0;
        int currentNumber = 1;

        // Incrementally check each number starting from 1
        // The loop terminates at the first number that cannot be formed
        while (canFormNumber(currentNumber, digitSets)) {
            lastValidNumber = currentNumber;
            currentNumber++;
        }

        System.out.println(lastValidNumber);
        scanner.close();
    }

    /**
     * Determines if a number can be formed using the available digit sets.
     * A number can be formed if each of its digits can be assigned to a unique set.
     *
     * @param number The integer to check.
     * @param sets   The list of available digit sets.
     * @return true if the number can be formed, false otherwise.
     */
    private static boolean canFormNumber(int number, List<Set<Integer>> sets) {
        List<Integer> digits = extractDigits(number);

        // If the number has more digits than there are available sets, 
        // it is impossible to assign each digit to a unique set.
        if (digits.size() > sets.size()) {
            return false;
        }

        // Use backtracking to find a valid assignment of digits to sets
        return canAssignDigits(0, digits, sets, new boolean[sets.size()]);
    }

    /**
     * Backtracking helper function to attempt assigning each digit to a unique set.
     *
     * @param digitIndex  The current digit being processed.
     * @param digits      The list of digits in the number.
     * @param sets        The available digit sets.
     * @param usedSets    A boolean array tracking which sets have already been used.
     * @return true if a valid assignment is found.
     */
    private static boolean canAssignDigits(int digitIndex, List<Integer> digits, 
                                           List<Set<Integer>> sets, boolean[] usedSets) {
        // Base case: All digits have been successfully assigned
        if (digitIndex == digits.size()) {
            return true;
        }

        int currentDigit = digits.get(digitIndex);

        // Try assigning the current digit to every available set
        for (int i = 0; i < sets.size(); i++) {
            if (!usedSets[i] && sets.get(i).contains(currentDigit)) {
                usedSets[i] = true; // Tentatively use this set

                if (canAssignDigits(digitIndex + 1, digits, sets, usedSets)) {
                    return true;
                }

                usedSets[i] = false; // Backtrack
            }
        }

        return false;
    }

    /**
     * Helper method to decompose an integer into its constituent digits.
     *
     * @param number The integer to decompose.
     * @return A list of digits in their natural order.
     */
    private static List<Integer> extractDigits(int number) {
        List<Integer> digits = new ArrayList<>();
        String numStr = Integer.toString(number);
        for (char c : numStr.toCharArray()) {
            digits.add(Character.getNumericValue(c));
        }
        return digits;
    }
}

