/**
 * A refactored solution to find the largest integer X such that all 
 * integers from 1 to X satisfy a specific digit-to-set assignment property.
 */
public class Main {

    public static void main(String[] args) {
        try {
            FastScanner sc = new FastScanner(System.in);
            int n = sc.nextInt();

            if (n <= 0) {
                System.out.println(0);
                return;
            }

            // Store sets of available digits
            Set<Integer>[] digitSets = new HashSet[n];
            for (int i = 0; i < n; i++) {
                digitSets[i] = new HashSet<>();
                for (int j = 0; j < 6; j++) {
                    digitSets[i].add(sc.nextInt());
                }
            }

            // Find the largest number X such that all numbers from 1 to X are valid.
            // The original logic limits the search range based on the number of sets.
            int limit = (int) Math.pow(10, n);
            int result = 0;

            for (int currentNum = 1; currentNum < limit; currentNum++) {
                if (isValid(currentNum, digitSets)) {
                    result = currentNum;
                } else {
                    // As soon as we find an invalid number, we stop.
                    break;
                }
            }

            System.out.println(result);

        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /**
     * Checks if a number is "valid" based on whether its digits can be 
     * uniquely assigned to the provided sets.
     */
    private static boolean isValid(int num, Set<Integer>[] digitSets) {
        List<Integer> digits = getDigits(num);

        // A number cannot be valid if it has more digits than available sets.
        if (digits.size() > digitSets.length) {
            return false;
        }

        return canMatchDigitsToSets(digits, digitSets, 0, new boolean[digitSets.length]);
    }

    /**
     * Extracts digits from an integer.
     */
    private static List<Integer> getDigits(int num) {
        List<Integer> digits = new ArrayList<>();
        int temp = num;
        while (temp > 0) {
            digits.add(temp % 10);
            temp /= 10;
        }
        return digits;
    }

    /**
     * Backtracking algorithm to check if digits can be assigned to distinct sets.
     * 
     * @param digits The list of digits to assign.
     * @param sets The available sets of digits.
     * @param digitIdx The current digit we are trying to assign.
     * @param usedSets Boolean array to track which sets have already been used.
     * @return true if a valid assignment exists, false otherwise.
     */
    private static boolean canMatchDigitsToSets(List<Integer> digits, Set<Integer>[] sets, int digitIdx, boolean[] usedSets) {
        // Base case: all digits have been successfully assigned.
        if (digitIdx == digits.size()) {
            return true;
        }

        int currentDigit = digits.get(digitIdx);

        for (int i = 0; i < sets.length; i++) {
            // If the set hasn't been used and contains the current digit
            if (!usedSets[i] && sets[i].contains(currentDigit)) {
                usedSets[i] = true; // Tentatively assign set i to current digit
                if (canMatchDigitsToSets(digits, sets, digitIdx + 1, usedSets)) {
                    return true;
                }
                usedSets[i] = false; // Backtrack
            }
        }

        return false;
    }

    /**
     * Fast I/O utility class.
     */
    static class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream i) {
            br = new BufferedReader(new InputStreamReader(i));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

