/**
 * A utility to determine the maximum consecutive integer sequence starting from 1
 * that can be formed by picking unique digits from provided sets.
 */
public class DigitCombinationSolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        // Read the number of sets
        int numSets = reader.nextInt();
        if (numSets <= 0) {
            System.out.println(0);
            return;
        }

        // Initialize the sets with input data
        List<Set<Integer>> digitSets = new ArrayList<>(numSets);
        for (int i = 0; i < numSets; i++) {
            Set<Integer> currentSet = new HashSet<>();
            for (int j = 0; j < 6; j++) {
                currentSet.add(reader.nextInt());
            }
            digitSets.add(currentSet);
        }

        // Find the largest X such that all numbers from 1 to X are "possible"
        int result = findMaxConsecutivePossible(digitSets);
        System.out.println(result);
    }

    /**
     * Iterates through integers starting from 1 to find the first integer 
     * that cannot be formed using the rules.
     * 
     * @param digitSets The available sets of digits.
     * @return The last successful integer in the sequence.
     */
    private static int findMaxConsecutivePossible(List<Set<Integer>> digitSets) {
        int current = 1;
        while (canFormNumber(current, digitSets)) {
            current++;
        }
        return current - 1;
    }

    /**
     * Checks if a number can be formed such that each of its digits 
     * is taken from a unique set.
     * 
     * @param number The number to check.
     * @param digitSets The available sets of digits.
     * @return true if possible, false otherwise.
     */
    private static boolean canFormNumber(int number, List<Set<Integer>> digitSets) {
        int[] digits = extractDigits(number);

        // If the number has more digits than available sets, it's impossible
        if (digits.length > digitSets.size()) {
            return false;
        }

        // Use backtracking to try and match each digit to a unique set
        return backtrackMatch(0, digits, digitSets, new boolean[digitSets.size()]);
    }

    /**
     * Core backtracking logic to assign digits to unique sets.
     */
    private static boolean backtrackMatch(int digitIdx, int[] digits, 
                                          List<Set<Integer>> digitSets, boolean[] setUsed) {
        // Base case: All digits have been successfully assigned to a set
        if (digitIdx == digits.length) {
            return true;
        }

        for (int i = 0; i < digitSets.size(); i++) {
            // If this set hasn't been used yet and contains the current digit
            if (!setUsed[i] && digitSets.get(i).contains(digits[digitIdx])) {
                setUsed[i] = true; // Tentatively assign set

                if (backtrackMatch(digitIdx + 1, digits, digitSets, setUsed)) {
                    return true;
                }

                setUsed[i] = false; // Backtrack
            }
        }
        return false;
    }

    /**
     * Converts an integer into an array of its component digits.
     */
    private static int[] extractDigits(int number) {
        if (number == 0) return new int[]{0};

        String s = Integer.toString(number);
        int[] digits = new int[s.length()];
        for (int i = 0; i < s.length(); i++) {
            digits[i] = s.charAt(i) - '0';
        }
        return digits;
    }

    /**
     * High-performance input reader.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A program that generates numbers by inserting digits into existing numbers
 * and counts the length of the consecutive sequence starting from 1.
 */
public class Main {

    private static final int MAX_VALUE_LIMIT = 1007;

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        // Read the number of cycles
        int numCycles = reader.nextInt();
        if (numCycles <= 0) {
            System.out.println(0);
            return;
        }

        // Set to store all unique numbers found so far
        Set<Integer> foundNumbers = new HashSet<>();

        for (int i = 0; i < numCycles; i++) {
            // Temporary list to hold numbers generated within the current cycle
            // to ensure we only use numbers from previous cycles for insertion.
            List<Integer> newlyGeneratedInCycle = new ArrayList<>();

            for (int j = 0; j < 6; j++) {
                int digit = reader.nextInt();

                // Rule 1: The digit itself is a new number
                newlyGeneratedInCycle.add(digit);

                // Rule 2: The digit can be inserted into any number found in previous cycles
                for (int existingNum : foundNumbers) {
                    String numStr = String.valueOf(existingNum);

                    // Try inserting the digit at every possible position (including start and end)
                    for (int pos = 0; pos <= numStr.length(); pos++) {
                        String combinedStr = numStr.substring(0, pos) + digit + numStr.substring(pos);

                        try {
                            int val = Integer.parseInt(combinedStr);
                            // Only track numbers within our practical limit
                            if (val < MAX_VALUE_LIMIT) {
                                newlyGeneratedInCycle.add(val);
                            }
                        } catch (NumberFormatException e) {
                            // In case of integer overflow, skip this value
                        }
                    }
                }
            }
            // Merge all numbers found in this cycle into our main set
            foundNumbers.addAll(newlyGeneratedInCycle);
        }

        System.out.println(countConsecutiveSequence(foundNumbers));
    }

    /**
     * Counts how many consecutive integers starting from 1 are present in the set.
     * 
     * @param numbers The set of found numbers.
     * @return The count of consecutive integers starting from 1.
     */
    private static int countConsecutiveSequence(Set<Integer> numbers) {
        int count = 0;
        int current = 1;
        while (numbers.contains(current)) {
            count++;
            current++;
        }
        return count;
    }

    /**
     * Efficient reader for fast I/O operations.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            return next != null ? Integer.parseInt(next) : 0;
        }

        public long nextLong() {
            String next = next();
            return next != null ? Long.parseLong(next) : 0L;
        }

        public double nextDouble() {
            String next = next();
            return next != null ? Double.parseDouble(next) : 0.0;
        }
    }
}

import java.util.Scanner;

/**
 * This class solves the problem of finding the largest consecutive integer 
 * starting from 1 that can be formed by selecting one face from each of 
 * the provided n dice, where each digit of the integer is represented 
 * by a unique die.
 */
public class DiceSequenceSolver {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }

        int numberOfDice = scanner.nextInt();
        int[][] diceFaces = new int[numberOfDice][6];

        for (int i = 0; i < numberOfDice; i++) {
            for (int j = 0; j < 6; j++) {
                if (scanner.hasNextInt()) {
                    diceFaces[i][j] = scanner.nextInt();
                }
            }
        }

        int result = findLargestConsecutiveNumber(diceFaces);
        System.out.println(result);

        scanner.close();
    }

    /**
     * Finds the largest consecutive integer starting from 1 that can be 
     * formed using the provided dice faces.
     * 
     * @param diceFaces A 2D array where each row represents a die and 
     *                  its 6 faces.
     * @return The largest consecutive integer found before a gap occurs.
     */
    private static int findLargestConsecutiveNumber(int[][] diceFaces) {
        int currentNumber = 1;
        int n = diceFaces.length;

        while (true) {
            boolean[] usedDice = new boolean[n];
            // If the current number cannot be formed, the previous number (currentNumber - 1)
            // was the last one in the consecutive sequence that could be formed.
            if (!canFormNumber(currentNumber, diceFaces, usedDice)) {
                return currentNumber - 1;
            }
            currentNumber++;
        }
    }

    /**
     * A recursive backtracking method to determine if a number can be formed.
     * Each digit of the number must be mapped to a unique die index.
     * 
     * @param number      The number currently being checked.
     * @param diceFaces   The available dice faces.
     * @param usedDice    A boolean array tracking which dice have already been assigned to a digit.
     * @return True if the number can be formed using unique dice for each digit, false otherwise.
     */
    private static boolean canFormNumber(int number, int[][] diceFaces, boolean[] usedDice) {
        // Base case: If the number has been fully decomposed into digits.
        if (number == 0) {
            return true;
        }

        int digit = number % 10;

        // Attempt to assign the current digit to every available die.
        for (int i = 0; i < diceFaces.length; i++) {
            if (!usedDice[i] && hasFaceValue(diceFaces[i], digit)) {
                // Mark die as used
                usedDice[i] = true;

                // Recurse to check the next digit (number / 10)
                if (canFormNumber(number / 10, diceFaces, usedDice)) {
                    return true;
                }

                // Backtrack: Unmark the die to allow other permutations to be explored
                usedDice[i] = false;
            }
        }

        return false;
    }

    /**
     * Checks if a specific die contains a given digit/value.
     * 
     * @param faces The 6 faces of a single die.
     * @param value The value to search for.
     * @return True if the value exists on the die, false otherwise.
     */
    private static boolean hasFaceValue(int[] faces, int value) {
        for (int face : faces) {
            if (face == value) {
                return true;
            }
        }
        return false;
    }
}

import java.util.Scanner;

/**
 * A program to find the smallest non-negative integer that cannot be formed
 * by selecting exactly one face from each of the given n dice.
 * 
 * A number X is considered formable if its n-digit representation (including 
 * leading zeros) can have its digits matched to the n dice such that each 
 * digit is available on its assigned die.
 */
public class DiceProblemSolver {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }

        int n = scanner.nextInt();
        boolean[][] dice = new boolean[n][10];

        // Load dice face availability
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < 6; j++) {
                if (scanner.hasNextInt()) {
                    int face = scanner.nextInt();
                    if (face >= 0 && face <= 9) {
                        dice[i][face] = true;
                    }
                }
            }
        }

        int result = findSmallestNonFormable(n, dice);
        System.out.println(result);

        scanner.close();
    }

    /**
     * Iterates through non-negative integers to find the first one that cannot be formed.
     * 
     * @param n The number of dice provided.
     * @param dice A boolean matrix where dice[i][d] is true if die i has digit d.
     * @return The smallest non-negative integer that cannot be formed.
     */
    private static int findSmallestNonFormable(int n, boolean[][] dice) {
        // The maximum number we check is 10^n - 1 (all n-digit combinations).
        // We use long to prevent overflow during the power calculation.
        long limit = (long) Math.pow(10, n);

        for (int i = 0; i < limit; i++) {
            if (!isFormable(i, n, dice)) {
                return i;
            }
        }

        // If all possible n-digit numbers are formable, return the first (n+1)-digit number.
        return (int) limit;
    }

    /**
     * Determines if a target integer can be formed by picking one digit from each die.
     * 
     * @param target The integer to check.
     * @param n The number of dice.
     * @param dice The availability of digits on each die.
     * @return true if the number is formable, false otherwise.
     */
    private static boolean isFormable(int target, int n, boolean[][] dice) {
        int[] digits = new int[n];
        int temp = target;

        // Extract digits into an array of size n, effectively handling leading zeros.
        // e.g., if n=3 and target=5, digits = [0, 0, 5]
        for (int i = n - 1; i >= 0; i--) {
            digits[i] = temp % 10;
            temp /= 10;
        }

        // Use backtracking to solve the bipartite matching problem between digits and dice.
        return canMatch(digits, 0, new boolean[n], dice);
    }

    /**
     * Recursive backtracking helper to match digits to unique dice.
     * 
     * @param digits The n digits of the number being tested.
     * @param digitIdx The index of the digit currently being assigned to a die.
     * @param usedDice A tracking array to ensure each die is used exactly once.
     * @param dice The availability of digits on each die.
     * @return true if a valid assignment for all digits is found.
     */
    private static boolean canMatch(int[] digits, int digitIdx, boolean[] usedDice, boolean[][] dice) {
        // Base case: all digits have been successfully assigned to a die.
        if (digitIdx == digits.length) {
            return true;
        }

        // Try assigning the current digit to every available die.
        for (int dieIdx = 0; dieIdx < dice.length; dieIdx++) {
            if (!usedDice[dieIdx] && dice[dieIdx][digits[digitIdx]]) {
                usedDice[dieIdx] = true;
                if (canMatch(digits, digitIdx + 1, usedDice, dice)) {
                    return true;
                }
                // Backtrack: unmark the die to try other permutations.
                usedDice[dieIdx] = false;
            }
        }

        return false;
    }
}

import java.util.*;
import java.io.*;

/**
 * Represents a single die with 6 faces.
 */
class Die {
    private final int[] faces;

    public Die(int[] faces) {
        if (faces.length != 6) {
            throw new IllegalArgumentException("A die must have exactly 6 faces.");
        }
        this.faces = faces;
    }

    public int[] getFaces() {
        return faces;
    }
}

/**
 * Solver to find the largest consecutive integer sequence starting from 1
 * that can be formed by concatenating faces of any subset of dice.
 */
class DiceSolver {
    private final List<Die> dice;
    private final Set<Integer> formedNumbers;

    public DiceSolver(List<Die> dice) {
        this.dice = dice;
        this.formedNumbers = new HashSet<>();
    }

    /**
     * Orchestrates the number generation and finding the result.
     * @return The largest X such that 1, 2, ..., X can all be formed.
     */
    public int solve() {
        generateAllPossibleNumbers(0, new boolean[dice.size()]);
        return findLargestConsecutiveSequence();
    }

    /**
     * Uses backtracking to explore all permutations of all subsets of dice.
     * 
     * @param currentNumber The number formed by the current path of dice.
     * @param usedDice A boolean array tracking which dice are currently in the sequence.
     */
    private void generateAllPossibleNumbers(int currentNumber, boolean[] usedDice) {
        // If we have formed a number, add it to our set.
        if (currentNumber > 0) {
            formedNumbers.add(currentNumber);
        }

        // Stop recursion if number is too large (prevents unnecessary work and overflow).
        // Given the constraints of the original problem (max 3 dice), 1000 is a safe boundary.
        if (currentNumber >= 1000) {
            return;
        }

        for (int i = 0; i < dice.size(); i++) {
            if (!usedDice[i]) {
                usedDice[i] = true;
                for (int face : dice.get(i).getFaces()) {
                    // Form the next number by concatenating the face (e.g., 1 -> 12)
                    int nextNumber = currentNumber * 10 + face;
                    generateAllPossibleNumbers(nextNumber, usedDice);
                }
                // Backtrack
                usedDice[i] = false;
            }
        }
    }

    /**
     * Finds the largest X such that all numbers from 1 to X are present in the set.
     */
    private int findLargestConsecutiveSequence() {
        int x = 0;
        while (formedNumbers.contains(x + 1)) {
            x++;
        }
        return x;
    }
}

public class Main {
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter writer = new PrintWriter(System.out)) {

            if (!scanner.hasNextInt()) return;

            int n = scanner.nextInt();
            List<Die> dice = new ArrayList<>();

            for (int i = 0; i < n; i++) {
                int[] faces = new int[6];
                for (int j = 0; j < 6; j++) {
                    faces[j] = scanner.nextInt();
                }
                dice.add(new Die(faces));
            }

            DiceSolver solver = new DiceSolver(dice);
            int result = solver.solve();

            writer.println(result);
            writer.flush();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}

import java.util.Scanner;

/**
 * A solver that finds the largest number whose digits can be represented 
 * by selecting at most three distinct sets of digits from a provided collection.
 */
public class DigitCombinationSolver {

    private static final int MAX_DIGITS_ALLOWED = 3;
    private static final int DIGITS_PER_SET = 6;
    private static final int MAX_SEARCH_LIMIT = 1000; // Based on original 3-loop logic

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int numSets = scanner.nextInt();
            boolean[][] digitExistsInSet = readDigitSets(scanner, numSets);

            int largestNumber = findLargestRepresentableNumber(numSets, digitExistsInSet);
            System.out.println(largestNumber);
        }
    }

    /**
     * Reads the input digit sets and maps them to a boolean lookup table 
     * for O(1) digit verification.
     * 
     * @param scanner The input scanner.
     * @param numSets The number of sets to read.
     * @return A 2D boolean array where [setIndex][digit] is true if the digit exists in that set.
     */
    private static boolean[][] readDigitSets(Scanner scanner, int numSets) {
        boolean[][] digitExistsInSet = new boolean[numSets][10];
        for (int i = 0; i < numSets; i++) {
            for (int j = 0; j < DIGITS_PER_SET; j++) {
                if (scanner.hasNextInt()) {
                    int digit = scanner.nextInt();
                    if (digit >= 0 && digit <= 9) {
                        digitExistsInSet[i][digit] = true;
                    }
                }
            }
        }
        return digitExistsInSet;
    }

    /**
     * Iterates through numbers to find the largest one satisfyng the condition.
     */
    private static int findLargestRepresentableNumber(int numSets, boolean[][] digitExistsInSet) {
        int currentNumber = 1;

        // We check numbers sequentially. The original logic allows a maximum of 3 digits.
        while (currentNumber < MAX_SEARCH_LIMIT && canRepresent(currentNumber, numSets, digitExistsInSet)) {
            currentNumber++;
        }

        // Return the last successful number. If 1 failed, returns 0.
        return currentNumber - 1;
    }

    /**
     * Determines if the digits of a number can be matched to at most 3 distinct sets.
     */
    private static boolean canRepresent(int number, int numSets, boolean[][] digitExistsInSet) {
        int[] digits = getDigits(number);
        int len = digits.length;

        // The original code's logic limits representation to a maximum of 3 distinct sets (i, j, z).
        if (len > MAX_DIGITS_ALLOWED) {
            return false;
        }

        // Attempt to find distinct indices i, j, k for the digits
        for (int i = 0; i < numSets; i++) {
            if (digitExistsInSet[i][digits[0]]) {
                if (len == 1) return true;

                for (int j = 0; j < numSets; j++) {
                    if (i == j) continue; // Indices must be distinct
                    if (digitExistsInSet[j][digits[1]]) {
                        if (len == 2) return true;

                        for (int k = 0; k < numSets; k++) {
                            if (k == i || k == j) continue; // Indices must be distinct
                            if (digitExistsInSet[k][digits[2]]) {
                                return true;
                            }
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Extracts digits from a number.
     * 
     * @param number The number to decompose.
     * @return An array of digits from least significant to most significant.
     */
    private static int[] getDigits(int number) {
        if (number == 0) return new int[]{0};

        int temp = number;
        int count = (int) Math.floor(Math.log10(number) + 1);
        int[] digits = new int[count];

        for (int i = 0; i < count; i++) {
            digits[i] = temp % 10;
            temp /= 10;
        }
        return digits;
    }
}

import java.util.*;
import java.io.*;

/**
 * The DiceCombinations class calculates the largest consecutive integer 
 * starting from 0 that can be represented by either a single die face 
 * or a two-digit combination of faces from two different dice.
 */
public class DiceCombinations {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            String firstLine = reader.next();
            if (firstLine == null) return;

            int n = Integer.parseInt(firstLine);
            int[][] diceFaces = new int[n][6];

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < 6; j++) {
                    diceFaces[i][j] = reader.nextInt();
                }
            }

            int result = findLargestConsecutiveRepresentable(n, diceFaces);
            out.println(result);
        } catch (Exception e) {
            // In a production environment, use a proper logging framework
            System.err.println("Error processing input: " + e.getMessage());
        } finally {
            out.close();
        }
    }

    /**
     * Finds the largest integer x such that all integers in the range [0, x] 
     * are representable by the given dice.
     *
     * @param n         The number of dice.
     * @param diceFaces A 2D array where diceFaces[i] contains the 6 faces of die i.
     * @return The largest consecutive integer starting from 0.
     */
    private static int findLargestConsecutiveRepresentable(int n, int[][] diceFaces) {
        if (n <= 0) return 0;

        BitSet representableNumbers = new BitSet();

        // Per original implementation logic, 0 is always considered representable.
        representableNumbers.set(0);

        // 1. Add all single-digit faces to the representable set.
        for (int i = 0; i < n; i++) {
            for (int face : diceFaces[i]) {
                representableNumbers.set(face);
            }
        }

        // 2. Add all two-digit numbers formed by combining faces from two different dice.
        // This generalizes the original n=2 and n=3 logic to work for any n >= 2.
        if (n >= 2) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (i == j) continue; // Cannot use the same die for both digits

                    for (int faceI : diceFaces[i]) {
                        for (int faceJ : diceFaces[j]) {
                            int combinedValue = (faceI * 10) + faceJ;
                            representableNumbers.set(combinedValue);
                        }
                    }
                }
            }
        }

        // Find the first integer that cannot be represented.
        int firstMissing = representableNumbers.nextClearBit(0);

        // The original code returned (firstMissing - 1). 
        // This effectively returns the end of the contiguous sequence starting at 0.
        return firstMissing - 1;
    }

    /**
     * FastReader provides efficient parsing of input using BufferedReader and StringTokenizer.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String next = next();
            return next != null ? Integer.parseInt(next) : 0;
        }
    }
}

import java.util.Scanner;
import java.util.Arrays;

/**
 * A solver that finds the largest integer 'i' such that all integers from 1 to 'i'
 * satisfy specific digit-to-constraint mapping requirements based on permutations.
 */
public class ConstraintSatisfactionSolver {

    // All possible permutations of indices {0, 1, 2}
    private static final int[][] PERMUTATIONS = {
        {0, 1, 2}, {0, 2, 1}, {1, 0, 2},
        {1, 2, 0}, {2, 0, 1}, {2, 1, 0}
    };

    public static void main(String[] args) {
        ConstraintSatisfactionSolver solver = new ConstraintSatisfactionSolver();
        solver.execute();
    }

    /**
     * Orchestrates the reading of input, processing, and output.
     */
    public void execute() {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int numConstraints = scanner.nextInt();
        scanner.nextLine(); // Consume the remaining newline character

        int[][] constraints = new int[numConstraints][];
        for (int i = 0; i < numConstraints; i++) {
            if (scanner.hasNextLine()) {
                constraints[i] = parseIntegerArray(scanner.nextLine());
            }
        }

        int result = solve(constraints, numConstraints);
        System.out.println(result);

        scanner.close();
    }

    /**
     * Finds the maximum consecutive integer starting from 1 that satisfies the constraints.
     * 
     * @param constraints The allowed digit sets for each constraint index.
     * @param n The number of constraints provided.
     * @return The largest integer 'i' where all integers in [1, i] are "possible".
     */
    private int solve(int[][] constraints, int n) {
        // The limit is 10^n as per the original logic.
        long limit = (long) Math.pow(10, n);
        int maxPossibleValue = 0;

        for (int i = 1; i < limit; i++) {
            if (isPossible(i, constraints)) {
                maxPossibleValue = i;
            } else {
                // Break as soon as we find an integer that doesn't satisfy the condition
                break;
            }
        }
        return maxPossibleValue;
    }

    /**
     * Checks if a given number satisfies the permutation-based constraints.
     * 
     * @param number The integer to check.
     * @param constraints The allowed digit sets.
     * @return true if a valid permutation exists for the number's digits.
     */
    private boolean isPossible(int number, int[][] constraints) {
        int[] digits = getDigits(number);
        int digitCount = digits.length;

        for (int[] permutation : PERMUTATIONS) {
            boolean matchFound = true;

            for (int digitIdx = 0; digitIdx < digitCount; digitIdx++) {
                int constraintIdx = permutation[digitIdx];

                // If the permutation asks for a constraint index that doesn't exist, it's invalid
                if (constraintIdx >= constraints.length) {
                    matchFound = false;
                    break;
                }

                // Check if the digit at this position is allowed by the assigned constraint
                if (!contains(constraints[constraintIdx], digits[digitIdx])) {
                    matchFound = false;
                    break;
                }
            }

            if (matchFound) {
                return true;
            }
        }
        return false;
    }

    /**
     * Converts an integer into an array of its constituent digits.
     */
    private int[] getDigits(int number) {
        String s = Integer.toString(number);
        int[] digits = new int[s.length()];
        for (int i = 0; i < s.length(); i++) {
            digits[i] = s.charAt(i) - '0';
        }
        return digits;
    }

    /**
     * Helper to check if an array contains a specific value.
     */
    private boolean contains(int[] array, int target) {
        for (int val : array) {
            if (val == target) {
                return true;
            }
        }
        return false;
    }

    /**
     * Parses a space-separated string of integers into an array.
     */
    private int[] parseIntegerArray(String line) {
        line = line.trim();
        if (line.isEmpty()) {
            return new int[0];
        }
        String[] parts = line.split("\\s+");
        int[] result = new int[parts.length];
        for (int i = 0; i < parts.length; i++) {
            result[i] = Integer.parseInt(parts[i]);
        }
        return result;
    }
}

import java.util.Scanner;

/**
 * DigitCombinationSolver finds the largest number X such that X can be 
 * constructed by selecting one digit from each provided row of a matrix.
 */
public class DigitCombinationSolver {

    private static final int COLUMNS_PER_ROW = 6;
    private static final int MAX_INDEX_VALUE = 5;

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int rowCount = scanner.nextInt();
            int[][] digitMatrix = new int[rowCount][COLUMNS_PER_ROW];

            for (int i = 0; i < rowCount; i++) {
                for (int j = 0; j < COLUMNS_PER_ROW; j++) {
                    digitMatrix[i][j] = scanner.nextInt();
                }
            }

            int result = solve(rowCount, digitMatrix);
            System.out.println(result);
        }
    }

    /**
     * Iterates through integers starting from 1 to find the largest constructible number.
     */
    private static int solve(int rowCount, int[][] digitMatrix) {
        int x = 1;
        double upperLimit = Math.pow(10, rowCount);

        while (x < upperLimit) {
            if (!isXPossible(x, rowCount, digitMatrix)) {
                return x - 1;
            }
            x++;
        }
        return x - 1;
    }

    /**
     * Checks if there is any combination of row elements that can form the number x.
     */
    private static boolean isXPossible(int x, int rowCount, int[][] digitMatrix) {
        int[] currentIndices = new int[rowCount];
        CombinationGenerator generator = new CombinationGenerator(MAX_INDEX_VALUE);

        do {
            // Extract the specific digits selected by the current index combination
            int[] selectedDigits = new int[rowCount];
            for (int i = 0; i < rowCount; i++) {
                selectedDigits[i] = digitMatrix[i][currentIndices[i]];
            }

            // Check if the number x can be formed using a subset of these selected digits
            if (NumberMatcher.canForm(x, selectedDigits)) {
                return true;
            }
        } while (generator.next(currentIndices));

        return false;
    }

    /**
     * Handles the generation of combinations for the row indices.
     */
    private static class CombinationGenerator {
        private final int maxValue;

        public CombinationGenerator(int maxValue) {
            this.maxValue = maxValue;
        }

        /**
         * Generates the next combination of indices in a base-N fashion.
         * 
         * @param indices The array to be updated with the next combination.
         * @return true if a next combination exists, false otherwise.
         */
        public boolean next(int[] indices) {
            int i = indices.length - 1;
            while (i >= 0 && indices[i] == maxValue) {
                indices[i] = 0;
                i--;
            }

            if (i < 0) {
                return false;
            }

            indices[i]++;
            return true;
        }
    }

    /**
     * Utilities for validating if a target number can be formed by given digits.
     */
    private static class NumberMatcher {

        /**
         * Determines if the target integer can be formed by a subset of the available digits.
         * Each digit in the target must correspond to a unique index in the availableDigits array.
         */
        public static boolean canForm(int target, int[] availableDigits) {
            String targetStr = Integer.toString(target);
            int[] targetDigits = new int[targetStr.length()];
            for (int i = 0; i < targetStr.length(); i++) {
                targetDigits[i] = targetStr.charAt(i) - '0';
            }

            return matchRecursive(targetDigits, 0, availableDigits, new boolean[availableDigits.length]);
        }

        private static boolean matchRecursive(int[] target, int targetIdx, int[] available, boolean[] used) {
            if (targetIdx == target.length) {
                return true;
            }

            for (int i = 0; i < available.length; i++) {
                if (!used[i] && available[i] == target[targetIdx]) {
                    used[i] = true;
                    if (matchRecursive(target, targetIdx + 1, available, used)) {
                        return true;
                    }
                    used[i] = false; // Backtrack
                }
            }
            return false;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A refactored solution to determine the largest number X such that all 
 * numbers from 0 to X can be formed using the digits on provided cubes.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        CubeSolver solver = new CubeSolver();
        solver.solve(reader, writer);

        writer.flush();
        writer.close();
    }

    /**
     * Contains the core business logic for solving the cube digit problem.
     */
    static class CubeSolver {
        private static final int MAX_NUMBER = 1000;
        private static final int FACES_PER_CUBE = 6;

        public void solve(FastReader in, PrintWriter out) {
            int n = in.nextInt();
            if (n <= 0) {
                out.println(-1);
                return;
            }

            int[][] cubes = readCubes(n, in);
            boolean[] possible = computePossibleNumbers(n, cubes);

            // Find the first number that cannot be formed
            for (int i = 0; i < MAX_NUMBER; i++) {
                if (!possible[i]) {
                    out.println(i - 1);
                    return;
                }
            }
        }

        private int[][] readCubes(int n, FastReader in) {
            int[][] cubes = new int[n][FACES_PER_CUBE];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < FACES_PER_CUBE; j++) {
                    cubes[i][j] = in.nextInt();
                }
            }
            return cubes;
        }

        private boolean[] computePossibleNumbers(int n, int[][] cubes) {
            boolean[] possible = new boolean[MAX_NUMBER];
            possible[0] = true;

            // 1-digit numbers: Pick any 1 cube
            for (int i = 0; i < n; i++) {
                for (int f = 0; f < FACES_PER_CUBE; f++) {
                    int digit = cubes[i][f];
                    if (digit < MAX_NUMBER) possible[digit] = true;
                }
            }

            // 2-digit numbers: Pick 2 distinct cubes
            if (n >= 2) {
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < n; j++) {
                        if (i == j) continue;
                        for (int f1 = 0; f1 < FACES_PER_CUBE; f1++) {
                            int d1 = cubes[i][f1] * 10;
                            for (int f2 = 0; f2 < FACES_PER_CUBE; f2++) {
                                int num = d1 + cubes[j][f2];
                                if (num < MAX_NUMBER) possible[num] = true;
                            }
                        }
                    }
                }
            }

            // 3-digit numbers: Pick 3 distinct cubes
            if (n >= 3) {
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < n; j++) {
                        if (i == j) continue;
                        for (int k = 0; k < n; k++) {
                            if (k == i || k == j) continue;
                            for (int f1 = 0; f1 < FACES_PER_CUBE; f1++) {
                                int d1 = cubes[i][f1] * 100;
                                for (int f2 = 0; f2 < FACES_PER_CUBE; f2++) {
                                    int d2 = d1 + cubes[j][f2] * 10;
                                    for (int f3 = 0; f3 < FACES_PER_CUBE; f3++) {
                                        int num = d2 + cubes[k][f3];
                                        if (num < MAX_NUMBER) possible[num] = true;
                                    }
                                }
                            }
                        }
                    }
                }
            }
            return possible;
        }
    }

    /**
     * Efficient input reader using BufferedReader and StringTokenizer.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String next = next();
            return next == null ? -1 : Integer.parseInt(next);
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * DigitCombinationSolver finds the smallest positive integer that cannot be formed
 * by selecting distinct rows from a given set of numbers and picking one digit from each.
 */
public class DigitCombinationSolver {

    private static final int MAX_TARGET = 999;
    private static final int MAX_ROWS_PER_DIGIT = 3;

    public static void main(String[] args) {
        try {
            new DigitCombinationSolver().run();
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    public void run() throws IOException {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        solve(reader, out);

        out.flush();
        out.close();
    }

    private void solve(FastReader reader, PrintWriter out) throws IOException {
        int n = reader.nextInt();
        if (n <= 0) {
            out.println(0);
            return;
        }

        // Map each digit (0-9) to a list of up to 3 unique row indices containing it.
        // We only need 3 indices because the maximum number of digits we need to match is 3.
        List<Integer>[] digitToRows = new ArrayList[10];
        for (int i = 0; i < 10; i++) {
            digitToRows[i] = new ArrayList<>();
        }

        for (int i = 0; i < n; i++) {
            Set<Integer> digitsInThisRow = new HashSet<>();
            for (int j = 0; j < 6; j++) {
                int val = reader.nextInt();
                addDigitsToSet(val, digitsInThisRow);
            }

            for (int digit : digitsInThisRow) {
                if (digitToRows[digit].size() < MAX_ROWS_PER_DIGIT) {
                    digitToRows[digit].add(i);
                }
            }
        }

        // Find the first number in [1, 999] that cannot be formed using distinct rows.
        for (int i = 1; i <= MAX_TARGET; i++) {
            if (!canForm(i, digitToRows)) {
                out.println(i - 1);
                return;
            }
        }
    }

    /**
     * Checks if the number x can be formed using distinct rows from the digitToRows map.
     */
    private boolean canForm(int x, List<Integer>[] digitToRows) {
        List<Integer> digits = getDigitsList(x);
        int numDigits = digits.size();

        if (numDigits == 1) {
            return !digitToRows[digits.get(0)].isEmpty();
        } 

        if (numDigits == 2) {
            int d1 = digits.get(0);
            int d2 = digits.get(1);
            for (int r1 : digitToRows[d1]) {
                for (int r2 : digitToRows[d2]) {
                    if (r1 != r2) return true;
                }
            }
        } 

        if (numDigits == 3) {
            int d1 = digits.get(0);
            int d2 = digits.get(1);
            int d3 = digits.get(2);
            for (int r1 : digitToRows[d1]) {
                for (int r2 : digitToRows[d2]) {
                    if (r1 == r2) continue;
                    for (int r3 : digitToRows[d3]) {
                        if (r3 != r1 && r3 != r2) return true;
                    }
                }
            }
        }

        return false;
    }

    private void addDigitsToSet(int val, Set<Integer> set) {
        if (val == 0) {
            set.add(0);
            return;
        }
        int temp = Math.abs(val);
        while (temp > 0) {
            set.add(temp % 10);
            temp /= 10;
        }
    }

    private List<Integer> getDigitsList(int x) {
        List<Integer> digits = new ArrayList<>();
        String s = Integer.toString(x);
        for (char c : s.toCharArray()) {
            digits.add(c - '0');
        }
        return digits;
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        public double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to find the longest consecutive sequence of integers 
 * starting from 1 that can be formed by combining digits from different sets.
 */
public class Main {

    private static final int DIGITS_PER_SET = 6;

    public static void main(String[] args) {
        FastReader input = new FastReader(System.in);
        PrintWriter output = new PrintWriter(System.out);

        Solver solver = new Solver();
        solver.solve(input, output);

        output.flush();
        output.close();
    }

    static class Solver {

        public void solve(FastReader in, PrintWriter out) {
            int numSets = in.nextInt();
            if (numSets <= 0) {
                out.print(0);
                return;
            }

            // Read the sets of digits
            int[][] digitSets = readDigitSets(in, numSets);

            // Generate all possible 2-digit numbers from different sets
            Set<Integer> availableNumbers = generateNumberPool(digitSets);

            // Find the maximum consecutive integer starting from 1
            int maxConsecutiveSequence = findMaxConsecutive(availableNumbers);

            out.print(maxConsecutiveSequence);
        }

        /**
         * Reads the input into a 2D array representing sets of digits.
         */
        private int[][] readDigitSets(FastReader in, int numSets) {
            int[][] digitSets = new int[numSets][DIGITS_PER_SET];
            for (int i = 0; i < numSets; i++) {
                for (int j = 0; j < DIGITS_PER_SET; j++) {
                    digitSets[i][j] = in.nextInt();
                }
            }
            return digitSets;
        }

        /**
         * Creates a pool of all possible 2-digit numbers formed by 
         * picking one digit from set 'i' and one from set 'j' (where i != j).
         */
        private Set<Integer> generateNumberPool(int[][] digitSets) {
            Set<Integer> pool = new HashSet<>();
            int numSets = digitSets.length;

            for (int i = 0; i < numSets; i++) {
                for (int j = 0; j < numSets; j++) {
                    // We must pick digits from two different sets
                    if (i == j) continue;

                    for (int digitFromI : digitSets[i]) {
                        for (int digitFromJ : digitSets[j]) {
                            int combinedNumber = (digitFromI * 10) + digitFromJ;
                            pool.add(combinedNumber);
                        }
                    }
                }
            }
            return pool;
        }

        /**
         * Finds the largest k such that {1, 2, ..., k} are all present in the set.
         */
        private int findMaxConsecutive(Set<Integer> pool) {
            int current = 1;
            while (pool.contains(current)) {
                current++;
            }
            // Subtract 1 because the loop breaks on the first missing number
            return current - 1;
        }
    }

    /**
     * Utility class for fast I/O operations.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

