import java.util.*;

/**
 * A program that finds the largest integer in a continuous sequence 
 * starting from 1 such that each digit of the integer can be 
 * supplied by a unique input set.
 */
public class DigitSequenceFinder {

    /**
     * Represents a collection of digits provided by the user.
     */
    static class DigitSet {
        private final Set<Integer> digits = new HashSet<>();

        public DigitSet(int[] inputDigits) {
            for (int digit : inputDigits) {
                digits.add(digit);
            }
        }

        public boolean contains(int digit) {
            return digits.contains(digit);
        }
    }

    /**
     * Handles the logic of validating whether a number can be formed 
     * using the available DigitSets.
     */
    static class DigitValidator {
        private final int totalSets;
        // Inverted index: maps a digit (0-9) to a list of indices of DigitSets containing it.
        private final List<Integer>[] digitToSetIndices;

        @SuppressWarnings("unchecked")
        public DigitValidator(List<DigitSet> digitSets) {
            this.totalSets = digitSets.size();
            this.digitToSetIndices = new List[10];
            for (int i = 0; i < 10; i++) {
                digitToSetIndices[i] = new ArrayList<>();
            }

            // Pre-calculate which sets contain which digits for O(1) access during validation
            for (int i = 0; i < totalSets; i++) {
                for (int d = 0; d <= 9; d++) {
                    if (digitSets.get(i).contains(d)) {
                        digitToSetIndices[d].add(i);
                    }
                }
            }
        }

        /**
         * Checks if a number can be formed where each digit comes from a distinct set.
         * 
         * @param number The number to validate.
         * @return true if the number can be formed using distinct sets.
         */
        public boolean canForm(int number) {
            List<Integer> digits = extractDigits(number);
            return backtrack(digits, 0, new boolean[totalSets]);
        }

        private List<Integer> extractDigits(int number) {
            List<Integer> digits = new ArrayList<>();
            if (number == 0) {
                digits.add(0);
                return digits;
            }
            int temp = number;
            while (temp > 0) {
                digits.add(temp % 10);
                temp /= 10;
            }
            return digits;
        }

        /**
         * A backtracking approach to find a valid assignment of digits to unique sets.
         */
        private boolean backtrack(List<Integer> digits, int digitIdx, boolean[] usedSets) {
            // Base case: All digits have been successfully assigned to a unique set
            if (digitIdx == digits.size()) {
                return true;
            }

            int currentDigit = digits.get(digitIdx);

            // Only iterate over sets that are known to contain the required digit
            for (int setIdx : digitToSetIndices[currentDigit]) {
                if (!usedSets[setIdx]) {
                    usedSets[setIdx] = true; // Tentatively assign this set
                    if (backtrack(digits, digitIdx + 1, usedSets)) {
                        return true;
                    }
                    usedSets[setIdx] = false; // Backtrack (unassign)
                }
            }

            return false;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int n = scanner.nextInt();
        List<DigitSet> digitSets = new ArrayList<>(n);

        for (int i = 0; i < n; i++) {
            int[] inputArr = new int[6];
            for (int j = 0; j < 6; j++) {
                if (scanner.hasNextInt()) {
                    inputArr[j] = scanner.nextInt();
                }
            }
            digitSets.add(new DigitSet(inputArr));
        }

        DigitValidator validator = new DigitValidator(digitSets);

        // The problem asks for the largest integer in a continuous sequence 
        // starting from 1. We iterate upwards until a number cannot be formed.
        int maxSequenceValue = 0;
        // Based on the original code logic, we check up to 999.
        for (int k = 1; k < 1000; k++) {
            if (validator.canForm(k)) {
                maxSequenceValue = k;
            } else {
                break;
            }
        }

        System.out.println(maxSequenceValue);
        scanner.close();
    }
}

import java.util.*;

/**
 * A program to find the largest integer i (up to 999) such that all numbers 
 * from 1 to i can be formed using the given set of dice.
 */
public class Main {

    private static final int MAX_SEARCH_LIMIT = 999;
    private static final int FACES_PER_DIE = 6;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int n = scanner.nextInt();
        List<Die> dice = new ArrayList<>();
        boolean containsOne = false;

        // Read dice input
        for (int i = 0; i < n; i++) {
            int[] faceValues = new int[FACES_PER_DIE];
            for (int j = 0; j < FACES_PER_DIE; j++) {
                faceValues[j] = scanner.nextInt();
                if (faceValues[j] == 1) {
                    containsOne = true;
                }
            }
            dice.add(new Die(faceValues));
        }

        // Special condition from original code: 
        // If no die contains the face '1', output 0.
        if (!containsOne) {
            System.out.println(0);
            return;
        }

        int maxFormable = solve(dice);
        System.out.println(maxFormable);
    }

    /**
     * Finds the largest integer i such that all numbers from 1 to i can be formed.
     * 
     * @param dice The list of available dice.
     * @return The largest successful integer found.
     */
    private static int solve(List<Die> dice) {
        int lastSuccessful = 1; 

        for (int i = 1; i <= MAX_SEARCH_LIMIT; i++) {
            if (canFormNumber(i, dice)) {
                lastSuccessful = i;
            } else {
                // Stop as soon as a number cannot be formed
                break;
            }
        }
        return lastSuccessful;
    }

    /**
     * Determines if a specific number can be formed using the available dice.
     */
    private static boolean canFormNumber(int number, List<Die> dice) {
        int[] digits = getDigits(number);

        // If number has more digits than available dice, it cannot be formed.
        if (digits.length > dice.size()) {
            return false;
        }

        return backtrack(digits, 0, new boolean[dice.size()], dice);
    }

    /**
     * Recursively attempts to match each digit of a number to a unique die.
     */
    private static boolean backtrack(int[] digits, int digitIdx, boolean[] usedDice, List<Die> dice) {
        // Base case: all digits have been successfully matched to a die.
        if (digitIdx == digits.length) {
            return true;
        }

        for (int i = 0; i < dice.size(); i++) {
            if (!usedDice[i] && dice.get(i).hasFace(digits[digitIdx])) {
                usedDice[i] = true; // Tentatively use this die
                if (backtrack(digits, digitIdx + 1, usedDice, dice)) {
                    return true;
                }
                usedDice[i] = false; // Backtrack
            }
        }

        return false;
    }

    /**
     * Converts an integer into an array of its individual digits.
     */
    private static int[] getDigits(int number) {
        String numStr = Integer.toString(number);
        int[] digits = new int[numStr.length()];
        for (int i = 0; i < numStr.length(); i++) {
            digits[i] = numStr.charAt(i) - '0';
        }
        return digits;
    }

    /**
     * Represents a single 6-sided die.
     */
    static class Die {
        private final boolean[] faces = new boolean[10];

        public Die(int[] faceValues) {
            for (int val : faceValues) {
                if (val >= 0 && val <= 9) {
                    faces[val] = true;
                }
            }
        }

        public boolean hasFace(int value) {
            return value >= 0 && value <= 9 && faces[value];
        }
    }
}

