/**
 * A program to find the largest integer X such that all integers from 1 to X 
 * can be represented by selecting a unique row from a given matrix for each digit.
 */
public class Main {

    private static final int MAX_SEARCH_LIMIT = 1000;

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        try {
            int n = reader.nextInt();
            if (n <= 0) {
                System.out.println(0);
                return;
            }

            // The problem specifies a matrix of n rows and 6 columns
            int columns = 6;
            int[][] matrix = reader.nextInt2D(n, columns);

            DigitMatcher matcher = new DigitMatcher(matrix);
            int result = solve(matcher);

            System.out.println(result);
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Iterates through numbers starting from 1 to find the first number 
     * that cannot be formed using the rules.
     */
    private static int solve(DigitMatcher matcher) {
        int i = 1;
        for (; i < MAX_SEARCH_LIMIT; i++) {
            if (!matcher.canFormNumber(i)) {
                break;
            }
        }
        // The loop breaks at the first number that fails, 
        // so the last successful number was i - 1.
        return i - 1;
    }
}

/**
 * Handles the logic of checking if a number's digits can be matched
 * to unique rows in the provided matrix.
 */
class DigitMatcher {
    private final int[][] matrix;
    private final int rowCount;

    public DigitMatcher(int[][] matrix) {
        this.matrix = matrix;
        this.rowCount = matrix.length;
    }

    /**
     * Checks if the digits of the given number can be uniquely assigned to rows.
     * This is treated as a bipartite matching problem.
     */
    public boolean canFormNumber(int number) {
        int[] digits = extractDigits(number);
        int digitCount = digits.length;

        // adjacencyMatrix[digitIndex][rowIndex] is true if rowIndex contains the digit
        boolean[][] adjacencyMatrix = new boolean[digitCount][rowCount];

        for (int d = 0; d < digitCount; d++) {
            for (int r = 0; r < rowCount; r++) {
                if (containsDigit(matrix[r], digits[d])) {
                    adjacencyMatrix[d][r] = true;
                }
            }
        }

        return canMatch(0, adjacencyMatrix, new boolean[rowCount]);
    }

    private int[] extractDigits(int number) {
        if (number == 0) return new int[]{0};

        List<Integer> digitList = new ArrayList<>();
        int temp = number;
        while (temp > 0) {
            digitList.add(temp % 10);
            temp /= 10;
        }

        // Convert List to primitive array
        int[] digits = new int[digitList.size()];
        for (int i = 0; i < digitList.size(); i++) {
            digits[i] = digitList.get(i);
        }
        return digits;
    }

    private boolean containsDigit(int[] row, int digit) {
        for (int val : row) {
            if (val == digit) return true;
        }
        return false;
    }

    /**
     * Backtracking algorithm to find a valid matching in the bipartite graph.
     */
    private boolean canMatch(int digitIndex, boolean[][] adjacencyMatrix, boolean[] rowVisited) {
        // If all digits have been successfully matched
        if (digitIndex == adjacencyMatrix.length) {
            return true;
        }

        for (int r = 0; r < rowCount; r++) {
            // If this row contains the current digit and hasn't been used for another digit
            if (adjacencyMatrix[digitIndex][r] && !rowVisited[r]) {
                rowVisited[r] = true;
                if (canMatch(digitIndex + 1, adjacencyMatrix, rowVisited)) {
                    return true;
                }
                rowVisited[r] = false; // Backtrack
            }
        }

        return false;
    }
}

/**
 * A lightweight, fast alternative to java.util.Scanner for competitive programming.
 */
class FastReader {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    public FastReader(InputStream input) {
        reader = new BufferedReader(new InputStreamReader(input));
    }

    public String next() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreElements()) {
            String line = reader.readLine();
            if (line == null) return null;
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    public int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    public int[][] nextInt2D(int rows, int cols) throws IOException {
        int[][] array = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                array[i][j] = nextInt();
            }
        }
        return array;
    }
}

