/**
 * A solution to find the smallest positive integer that cannot be formed
 * using digits from a given number of sets, following specific rules:
 * 1. A number's length is limited by the number of available sets.
 * 2. Each digit in the number must come from a distinct set.
 * 3. The leading digit cannot be zero.
 */
public class Solution {

    private static final int DIGITS_PER_SET = 6;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int numSets = scanner.nextInt();
        List<int[]> digitSets = readDigitSets(scanner, numSets);

        // Generate all possible numbers that can be formed using the rules
        Set<Integer> formedNumbers = new HashSet<>();
        generateNumbers(0, 0, 0, numSets, digitSets, formedNumbers);

        // Find the smallest positive integer not present in the set
        int smallestMissing = findSmallestMissing(formedNumbers);
        System.out.println(smallestMissing);

        scanner.close();
    }

    /**
     * Reads N sets of digits from the input.
     */
    private static List<int[]> readDigitSets(Scanner scanner, int n) {
        List<int[]> digitSets = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            int[] currentSet = new int[DIGITS_PER_SET];
            for (int j = 0; j < DIGITS_PER_SET; j++) {
                if (scanner.hasNextInt()) {
                    currentSet[j] = scanner.nextInt();
                }
            }
            digitSets.add(currentSet);
        }
        return digitSets;
    }

    /**
     * Recursively generates all possible numbers using backtracking.
     * 
     * @param currentVal    The number being constructed.
     * @param usedSetsMask  A bitmask representing which sets have already been used.
     * @param currentDepth  The current number of digits in the number.
     * @param totalSets     The total number of sets provided in input.
     * @param digitSets     The available digits in each set.
     * @param formedNumbers The set of all valid numbers discovered.
     */
    private static void generateNumbers(int currentVal, 
                                        int usedSetsMask, 
                                        int currentDepth, 
                                        int totalSets, 
                                        List<int[]> digitSets, 
                                        Set<Integer> formedNumbers) {

        // If we've formed a valid number (depth > 0), add it to our collection
        if (currentDepth > 0) {
            formedNumbers.add(currentVal);
        }

        // Base case: We cannot form a number longer than the number of sets available
        if (currentDepth == totalSets) {
            return;
        }

        for (int i = 0; i < totalSets; i++) {
            // Check if the i-th set has been used for the current number construction
            if (((usedSetsMask >> i) & 1) == 0) {
                for (int digit : digitSets.get(i)) {
                    // Rule: A multi-digit number cannot have a leading zero
                    if (currentDepth == 0 && digit == 0) {
                        continue;
                    }

                    // Calculate new value and recurse to the next digit depth
                    int nextVal = (currentVal * 10) + digit;
                    generateNumbers(nextVal, 
                                    usedSetsMask | (1 << i), 
                                    currentDepth + 1, 
                                    totalSets, 
                                    digitSets, 
                                    formedNumbers);
                }
            }
        }
    }

    /**
     * Iterates starting from 1 to find the first integer not found in the set.
     */
    private static int findSmallestMissing(Set<Integer> formedNumbers) {
        int missing = 1;
        while (formedNumbers.contains(missing)) {
            missing++;
        }
        return missing;
    }
}

