/**
 * Solves the problem of finding the largest integer k such that 
 * all integers from 1 to k can be formed by concatenating digits 
 * from up to three different rows in the provided input matrix.
 */
public class NumberSequenceSolver {

    private static final int DIGITS_PER_ROW = 6;
    private static final int MAX_CHECK_RANGE = 10000;

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        solve(reader, writer);

        writer.flush();
        writer.close();
    }

    private static void solve(FastReader reader, PrintWriter writer) {
        int n = reader.nextInt();
        if (n <= 0) {
            writer.println(0);
            return;
        }

        int[][] digitMatrix = new int[n][DIGITS_PER_ROW];

        // Read input matrix
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < DIGITS_PER_ROW; j++) {
                digitMatrix[i][j] = reader.nextInt();
            }
        }

        boolean[] isPresent = new boolean[MAX_CHECK_RANGE];

        // 1. Mark all single-digit numbers from the rows
        for (int i = 0; i < n; i++) {
            for (int v1 = 0; v1 < DIGITS_PER_ROW; v1++) {
                markPresent(isPresent, digitMatrix[i][v1]);
            }
        }

        // 2. Mark all two-digit numbers (formed by digits from two different rows)
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i == j) continue;

                for (int v1 = 0; v1 < DIGITS_PER_ROW; v1++) {
                    for (int v2 = 0; v2 < DIGITS_PER_ROW; v2++) {
                        int combined = (digitMatrix[i][v1] * 10) + digitMatrix[j][v2];
                        markPresent(isPresent, combined);
                    }
                }
            }
        }

        // 3. Mark all three-digit numbers (formed by digits from three different rows)
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i == j) continue;
                for (int k = 0; k < n; k++) {
                    if (k == i || k == j) continue;

                    for (int v1 = 0; v1 < DIGITS_PER_ROW; v1++) {
                        for (int v2 = 0; v2 < DIGITS_PER_ROW; v2++) {
                            for (int v3 = 0; v3 < DIGITS_PER_ROW; v3++) {
                                int combined = (digitMatrix[i][v1] * 100) 
                                             + (digitMatrix[j][v2] * 10) 
                                             + digitMatrix[k][v3];
                                markPresent(isPresent, combined);
                            }
                        }
                    }
                }
            }
        }

        // Find the largest k such that 1, 2, ..., k are all present
        int maxConsecutive = 0;
        for (int x = 1; x < MAX_CHECK_RANGE; x++) {
            if (isPresent[x]) {
                maxConsecutive = x;
            } else {
                break;
            }
        }

        writer.println(maxConsecutive);
    }

    /**
     * Safely marks a number as present if it falls within the tracking array bounds.
     */
    private static void markPresent(boolean[] isPresent, int value) {
        if (value >= 0 && value < MAX_CHECK_RANGE) {
            isPresent[value] = true;
        }
    }

    /**
     * Fast I/O utility for efficient reading of large input sets.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

