/**
 * Handles the core logic of finding the first available digit or digit pair
 * based on occupancy constraints.
 */
class DigitAvailabilitySolver {
    private static final int MAX_DIGITS = 10;
    private static final int NUM_SLOTS = 3;
    private static final int MAX_CHECK_VALUE = 100;

    /**
     * Solves the problem by reading occupancy constraints and finding the 
     * smallest non-conflicting number.
     * 
     * @param in  The fast reader for input.
     * @param out The print writer for output.
     */
    public void solve(FastReader in, PrintWriter out) {
        int numSlots = in.nextInt();
        // occupancyMap[digit][slot] is true if the digit is occupied in that specific slot.
        boolean[][] occupancyMap = new boolean[MAX_DIGITS][NUM_SLOTS];

        // Populate occupancy constraints.
        // Based on original logic: n represents the number of slots being filled.
        for (int slot = 0; slot < numSlots; slot++) {
            // Each slot has 6 digit-occupancy declarations.
            for (int j = 0; j < 6; j++) {
                int digit = in.nextInt();
                // Ensure input is within valid bounds to prevent ArrayIndexOutOfBounds
                if (digit >= 0 && digit < MAX_DIGITS && slot < NUM_SLOTS) {
                    occupancyMap[digit][slot] = true;
                }
            }
        }

        // Iterate through numbers 1 to 99 to find the first available one.
        for (int i = 1; i < MAX_CHECK_VALUE; i++) {
            if (isAvailable(i, occupancyMap)) {
                out.println(i - 1);
                return;
            }
        }

        // If no number 1-99 is available, default to 99 as per original logic.
        out.println(MAX_CHECK_VALUE - 1);
    }

    /**
     * Checks if a number (1-99) is available based on digit occupancy rules.
     */
    private boolean isAvailable(int number, boolean[][] occupancyMap) {
        if (number < 10) {
            return isSingleDigitAvailable(number, occupancyMap);
        } else {
            int firstDigit = number % 10;
            int secondDigit = number / 10;
            return isDoubleDigitAvailable(firstDigit, secondDigit, occupancyMap);
        }
    }

    /**
     * A single digit is available if it is not occupied in any of the slots.
     */
    private boolean isSingleDigitAvailable(int digit, boolean[][] occupancyMap) {
        for (int slot = 0; slot < NUM_SLOTS; slot++) {
            if (occupancyMap[digit][slot]) {
                return false;
            }
        }
        return true;
    }

    /**
     * A two-digit number is available if there is no conflict where 
     * digit1 is in slot A and digit2 is in slot B (where A != B).
     */
    private boolean isDoubleDigitAvailable(int d1, int d2, boolean[][] occupancyMap) {
        // The original logic checked all pairs (s1, s2) where s1 != s2.
        // We check if there is any combination of different slots that are both occupied.
        for (int s1 = 0; s1 < NUM_SLOTS; s1++) {
            for (int s2 = 0; s2 < NUM_SLOTS; s2++) {
                if (s1 != s2) {
                    if (occupancyMap[d1][s1] && occupancyMap[d2][s2]) {
                        return false;
                    }
                }
            }
        }
        return true;
    }
}

/**
 * High-performance reader for parsing integers from an InputStream.
 */
class FastReader implements AutoCloseable {
    private static final int BUFFER_SIZE = 1 << 16;
    private final InputStream din;
    private final byte[] buffer;
    private int bufferPointer;
    private int bytesRead;

    public FastReader(InputStream inputStream) {
        this.din = inputStream;
        this.buffer = new byte[BUFFER_SIZE];
        this.bufferPointer = 0;
        this.bytesRead = 0;
    }

    /**
     * Reads the next integer from the input stream.
     */
    public int nextInt() {
        int ret = 0;
        try {
            byte c = read();
            while (c <= ' ') {
                c = read();
            }
            boolean neg = (c == '-');
            if (neg) {
                c = read();
            }
            do {
                ret = ret * 10 + c - '0';
            } while ((c = read()) >= '0' && c <= '9');

            return neg ? -ret : ret;
        } catch (IOException e) {
            return 0;
        }
    }

    private void fillBuffer() throws IOException {
        bytesRead = din.read(buffer, bufferPointer = 0, BUFFER_SIZE);
        if (bytesRead == -1) {
            buffer[0] = -1;
        }
    }

    private byte read() throws IOException {
        if (bufferPointer == bytesRead) {
            fillBuffer();
        }
        return buffer[bufferPointer++];
    }

    @Override
    public void close() throws IOException {
        din.close();
    }
}

