    }

    static class CubesSolver {
        private static final int FACES_PER_DIE = 6;

        /**
         * Solves the problem by generating all possible combinations of numbers
         * that can be formed using 1, 2, or 3 dice.
         *
         * @param n       The number of dice available.
         * @param in      The input reader.
         * @param out     The output writer.
         */
        public void solve(int n, FastReader in, PrintWriter out) {
            int[][] dice = new int[n][FACES_PER_DIE];

            // Read dice faces
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < FACES_PER_DIE; j++) {
                    dice[i][j] = in.nextInt();
                }
            }

            Set<Integer> reachableNumbers = new HashSet<>();

            // 1-digit numbers: use one die
            for (int i = 0; i < n; i++) {
                for (int f = 0; f < FACES_PER_DIE; f++) {
                    reachableNumbers.add(dice[i][f]);
                }
            }

            // 2-digit numbers: use two different dice
            if (n >= 2) {
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < n; j++) {
                        if (i == j) continue;
                        for (int f1 = 0; f1 < FACES_PER_DIE; f1++) {
                            for (int f2 = 0; f2 < FACES_PER_DIE; f2++) {
                                int val = dice[i][f1] * 10 + dice[j][f2];
                                reachableNumbers.add(val);
                            }
                        }
                    }
                }
            }

            // 3-digit numbers: use three different dice
            if (n >= 3) {
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < n; j++) {
                        for (int k = 0; k < n; k++) {
                            if (i == j || j == k || i == k) continue;
                            for (int f1 = 0; f1 < FACES_PER_DIE; f1++) {
                                for (int f2 = 0; f2 < FACES_PER_DIE; f2++) {
                                    for (int f3 = 0; f3 < FACES_PER_DIE; f3++) {
                                        int val = dice[i][f1] * 100 + dice[j][f2] * 10 + dice[k][f3];
                                        reachableNumbers.add(val);
                                    }
                                }
                            }
                        }
                    }
                }
            }

            // Find the smallest positive integer not in the set
            int smallestMissing = 1;
            while (reachableNumbers.contains(smallestMissing)) {
                smallestMissing++;
            }
            out.println(smallestMissing);
        }
    }

    /**
     * Fast I/O reader using BufferedReader and StringTokenizer.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            return next != null ? Integer.parseInt(next) : 0;
        }
    }
}

