/**
 * Refactored solution to find the smallest non-negative integer X
 * such that no permutation of its n digits can be matched to the n given sets.
 */
public class Main {

    public static void main(String[] args) {
        FastScanner fs = new FastScanner(System.in);

        // Read n - the number of sets/digits
        String nInput = fs.next();
        if (nInput == null) return;
        int n = Integer.parseInt(nInput);

        // forbidden[i][d] is true if digit d belongs to set i
        boolean[][] isDigitInSet = new boolean[n][10];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < 6; j++) {
                int digit = fs.nextInt();
                if (digit >= 0 && digit <= 9) {
                    isDigitInSet[i][digit] = true;
                }
            }
        }

        // Iterate through all possible n-digit numbers (0 to 10^n - 1)
        // We use long to prevent overflow for larger values of n
        long maxRange = (long) Math.pow(10, n);
        for (long x = 0; x < maxRange; x++) {
            int[] digits = getNDigits(x, n);

            // A number is "invalid" if its digits can be perfectly matched to the sets.
            // We want the first (smallest) number where a perfect matching is IMPOSSIBLE.
            if (!canFormPerfectMatching(digits, isDigitInSet)) {
                System.out.println(x);
                return;
            }
        }

        // If no such number is found within the n-digit range, output the max possible value.
        System.out.println(maxRange - 1);
    }

    /**
     * Extracts the n digits of a number x, including leading zeros to ensure
     * the resulting array always has length n.
     *
     * @param x The number to extract digits from.
     * @param n The desired number of digits.
     * @return An array of n digits.
     */
    private static int[] getNDigits(long x, int n) {
        int[] digits = new int[n];
        for (int i = n - 1; i >= 0; i--) {
            digits[i] = (int) (x % 10);
            x /= 10;
        }
        return digits;
    }

    /**
     * Determines if there exists a perfect matching between the digits 
     * and the available sets using a backtracking algorithm.
     *
     * @param digits The digits of the current number.
     * @param isDigitInSet The adjacency matrix representing which digits are in which sets.
     * @return true if a perfect matching exists, false otherwise.
     */
    private static boolean canFormPerfectMatching(int[] digits, boolean[][] isDigitInSet) {
        int n = digits.length;
        return backtrack(0, digits, isDigitInSet, new boolean[n]);
    }

    /**
     * Recursive backtracking to find a valid assignment of digits to sets.
     *
     * @param digitIdx Current index in the digits array being matched.
     * @param digits The array of digits.
     * @param isDigitInSet The adjacency matrix.
     * @param setUsed Tracks which sets have already been assigned a digit.
     * @return true if a complete matching is found.
     */
    private static boolean backtrack(int digitIdx, int[] digits, boolean[][] isDigitInSet, boolean[] setUsed) {
        if (digitIdx == digits.length) {
            return true;
        }

        for (int s = 0; s < isDigitInSet.length; s++) {
            // If set 's' is not yet used and the current digit is valid for set 's'
            if (!setUsed[s] && isDigitInSet[s][digits[digitIdx]]) {
                setUsed[s] = true;
                if (backtrack(digitIdx + 1, digits, isDigitInSet, setUsed)) {
                    return true;
                }
                setUsed[s] = false; // Backtrack
            }
        }
        return false;
    }

    /**
     * Fast I/O utility class for efficient reading of input.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String s = next();
            return (s == null) ? 0 : Integer.parseInt(s);
        }
    }
}

