/**
 * This program finds the smallest positive integer X such that X cannot be formed 
 * by selecting one digit from each of K distinct people, where K is the number 
 * of digits in X and K <= N (the total number of people).
 */
public class B887 {

    private static final int MAX_SEARCH_LIMIT = 1000;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int n = scanner.nextInt();
        // availability[i][d] is true if person i possesses digit d
        boolean[][] availability = new boolean[n][10];

        // Each person provides 6 digits according to the original specification
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < 6; j++) {
                if (scanner.hasNextInt()) {
                    int digit = scanner.nextInt();
                    if (digit >= 0 && digit <= 9) {
                        availability[i][digit] = true;
                    }
                }
            }
        }

        int result = findSmallestMissingNumber(n, availability);
        System.out.println(result);

        scanner.close();
    }

    /**
     * Iterates through positive integers to find the first one that cannot be formed.
     * 
     * @param n Number of people available.
     * @param availability 2D array indicating digit availability per person.
     * @return The value (X - 1) as per the original program's output logic.
     */
    private static int findSmallestMissingNumber(int n, boolean[][] availability) {
        for (int x = 1; x <= MAX_SEARCH_LIMIT; x++) {
            if (!isFormable(x, n, availability)) {
                return x - 1;
            }
        }

        // Fallback for cases where all numbers up to the limit are formable.
        // This mimics the original program's behavior for n=1, 2, and 3.
        if (n == 1) return 9;
        if (n == 2) return 99;
        return 999;
    }

    /**
     * Determines if a number X can be formed using K distinct people 
     * where K is the number of digits in X.
     */
    private static boolean isFormable(int x, int n, boolean[][] availability) {
        List<Integer> digits = getDigits(x);
        int k = digits.size();

        // If the number of digits exceeds the number of available people, it cannot be formed.
        if (k > n) {
            return false;
        }

        // Use backtracking to check if a valid matching exists between digits and people.
        return canMatch(digits, 0, new boolean[n], availability);
    }

    /**
     * A backtracking algorithm to solve the bipartite matching problem:
     * Can we assign each digit in the list to a unique person?
     */
    private static boolean canMatch(List<Integer> digits, int digitIdx, boolean[] personUsed, boolean[][] availability) {
        // Base case: all digits have been successfully assigned to a person.
        if (digitIdx == digits.size()) {
            return true;
        }

        int currentDigit = digits.get(digitIdx);
        int totalPeople = availability.length;

        for (int p = 0; p < totalPeople; p++) {
            // If person 'p' is not yet used and has the required digit
            if (!personUsed[p] && availability[p][currentDigit]) {
                personUsed[p] = true; // Tentatively assign person p to this digit

                if (canMatch(digits, digitIdx + 1, personUsed, availability)) {
                    return true;
                }

                personUsed[p] = false; // Backtrack: unassign person p
            }
        }

        return false;
    }

    /**
     * Converts an integer into a list of its component digits.
     */
    private static List<Integer> getDigits(int x) {
        List<Integer> digits = new ArrayList<>();
        String s = Integer.toString(x);
        for (int i = 0; i < s.length(); i++) {
            digits.add(Character.getNumericValue(s.charAt(i)));
        }
        return digits;
    }
}

