/**
 * Refactored solution to find the largest number i such that every number 
 * from 1 to i has its digits present in distinct sets.
 */
public final class Solution {

    public static void main(String[] args) {
        FastReader sc = new FastReader(System.in);

        // Read the number of sets
        String nStr = sc.next();
        if (nStr == null) return;
        int n = Integer.parseInt(nStr);

        if (n <= 0) {
            System.out.println(0);
            return;
        }

        // digitToSets[d] stores the indices of sets that contain digit d.
        // This allows us to jump directly to relevant sets during matching.
        List<Integer>[] digitToSets = new ArrayList[10];
        for (int i = 0; i < 10; i++) {
            digitToSets[i] = new ArrayList<>();
        }

        // Use a boolean array to prevent adding the same set index 
        // multiple times for the same digit.
        boolean[][] hasDigit = new boolean[10][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < 6; j++) {
                int val = sc.nextInt();
                // We only care about values that are single digits (0-9)
                if (val >= 0 && val <= 9) {
                    if (!hasDigit[val][i]) {
                        digitToSets[val].add(i);
                        hasDigit[val][i] = true;
                    }
                }
            }
        }

        int maxFound = 0;
        // Iterate through numbers 1 to 998. 
        // The problem logic stops at the first number that cannot be satisfied.
        for (int i = 1; i < 999; i++) {
            if (canMatchDigits(i, digitToSets)) {
                maxFound = i;
            } else {
                break;
            }
        }

        System.out.println(maxFound);
    }

    /**
     * Determines if the digits of a given number can be mapped to 
     * unique (distinct) sets.
     * 
     * @param num The number to check.
     * @param digitToSets Pre-processed mapping of digits to set indices.
     * @return true if a valid assignment of digits to sets exists.
     */
    private static boolean canMatchDigits(int num, List<Integer>[] digitToSets) {
        List<Integer> digits = new ArrayList<>();
        int temp = num;
        while (temp > 0) {
            digits.add(temp % 10);
            temp /= 10;
        }

        // Optimization: To find a matching for k elements, we only need to 
        // consider at most k candidate sets for each element.
        List<List<Integer>> limitedCandidateSets = new ArrayList<>();
        for (int d : digits) {
            List<Integer> limited = new ArrayList<>();
            int count = 0;
            for (int setIdx : digitToSets[d]) {
                limited.add(setIdx);
                if (++count == digits.size()) break;
            }
            limitedCandidateSets.add(limited);
        }

        return backtrack(limitedCandidateSets, 0, new HashSet<>());
    }

    /**
     * A backtracking algorithm to solve the bipartite matching problem for a small number of digits.
     * 
     * @param limitedSets The candidate sets for each digit.
     * @param idx The current digit index being processed.
     * @param usedSets A set containing indices of sets already assigned to previous digits.
     * @return true if a successful assignment is found.
     */
    private static boolean backtrack(List<List<Integer>> limitedSets, int idx, Set<Integer> usedSets) {
        if (idx == limitedSets.size()) {
            return true;
        }

        for (int setIdx : limitedSets.get(idx)) {
            if (!usedSets.contains(setIdx)) {
                usedSets.add(setIdx);
                if (backtrack(limitedSets, idx + 1, usedSets)) {
                    return true;
                }
                usedSets.remove(setIdx);
            }
        }
        return false;
    }

    /**
     * Fast I/O utility class for efficient input reading.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            return next == null ? 0 : Integer.parseInt(next);
        }
    }
}

