/**
 * A solution to find the smallest non-negative integer that cannot be formed
 * by selecting a subset of dice and concatenating one face from each selected die.
 */
public class DiceChallenge {

    private static final int MAX_POSSIBLE_VALUE = 1000;
    private static final int FACES_PER_DIE = 6;

    private final int numberOfDice;
    private final int[][] diceFaces;
    private final boolean[] canMake = new boolean[MAX_POSSIBLE_VALUE];

    /**
     * Initializes the solver with the given dice data.
     *
     * @param numberOfDice The number of dice available.
     * @param diceFaces    A 2D array where diceFaces[i][j] is the j-th face of the i-th die.
     */
    public DiceChallenge(int numberOfDice, int[][] diceFaces) {
        this.numberOfDice = numberOfDice;
        this.diceFaces = diceFaces;
    }

    /**
     * Orchestrates the generation of possible numbers and finds the smallest missing one.
     */
    public void solve() {
        // Generate all possible numbers using recursion
        generatePossibleNumbers(0, 0);

        // Find the smallest non-negative integer not marked as possible
        for (int i = 0; i < MAX_POSSIBLE_VALUE; i++) {
            if (!canMake[i]) {
                System.out.println(i);
                return;
            }
        }
    }

    /**
     * Uses backtracking to explore all permutations of all subsets of dice.
     *
     * @param mask        A bitmask representing the dice already used in the current combination.
     * @param currentVal  The integer value formed by the current sequence of dice faces.
     */
    private void generatePossibleNumbers(int mask, int currentVal) {
        for (int i = 0; i < numberOfDice; i++) {
            // Check if the i-th die has already been used in this combination
            if (((mask >> i) & 1) == 0) {
                for (int face : diceFaces[i]) {
                    // Calculate the next number. 
                    // If mask is 0, this is the first die being picked.
                    int nextVal = (mask == 0) ? face : (currentVal * 10 + face);

                    // Only continue if the number is within our tracking bounds
                    if (nextVal < MAX_POSSIBLE_VALUE) {
                        canMake[nextVal] = true;
                        // Recurse by adding the current die to the mask
                        generatePossibleNumbers(mask | (1 << i), nextVal);
                    }
                }
            }
        }
    }

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        String nInput = reader.next();
        if (nInput == null) return;

        int n = Integer.parseInt(nInput);
        int[][] faces = new int[n][FACES_PER_DIE];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < FACES_PER_DIE; j++) {
                faces[i][j] = reader.nextInt();
            }
        }

        DiceChallenge challenge = new DiceChallenge(n, faces);
        challenge.solve();
    }

    /**
     * A high-performance input reader for processing large datasets efficiently.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

