/**
 * DigitCombinationSolver solves the problem of finding the largest integer x 
 * such that all integers from 1 to x can be formed by picking at most one 
 * digit from each of the provided rows of digits.
 */
public class DigitCombinationSolver {

    private static final int MAX_POSSIBLE_VALUE = 1000;

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        // Read the number of rows
        int numRows = reader.nextInt();
        if (numRows <= 0) {
            System.out.println(0);
            return;
        }

        // Read the digit rows (each row has 6 digits)
        int[][] digitRows = new int[numRows][6];
        for (int i = 0; i < numRows; i++) {
            for (int j = 0; j < 6; j++) {
                digitRows[i][j] = reader.nextInt();
            }
        }

        // Determine all possible numbers that can be formed
        boolean[] possibleNumbers = new boolean[MAX_POSSIBLE_VALUE];
        generatePossibleNumbers(0, new boolean[numRows], digitRows, possibleNumbers);

        // Find the largest consecutive integer sequence starting from 1
        int maxConsecutive = findMaxConsecutive(possibleNumbers);
        System.out.println(maxConsecutive);
    }

    /**
     * Recursively generates all possible numbers using at most one digit per row.
     * 
     * @param currentNum    The number built so far.
     * @param usedRows      Boolean array to track which rows have already contributed a digit.
     * @param digitRows     The input 2D array containing digits.
     * @param possibleFlags Array to mark numbers that can be formed.
     */
    private static void generatePossibleNumbers(int currentNum, boolean[] usedRows, 
                                                int[][] digitRows, boolean[] possibleFlags) {
        // If a valid number has been formed, mark it
        if (currentNum > 0) {
            possibleFlags[currentNum] = true;
        }

        // Since we only have at most 3 rows, the maximum number is 999.
        // Stop recursion if we exceed the bounds or cannot add more digits.
        if (currentNum >= 100 || usedRows.length == 0) {
            return;
        }

        for (int i = 0; i < digitRows.length; i++) {
            if (!usedRows[i]) {
                usedRows[i] = true; // Mark row as used

                for (int digit : digitRows[i]) {
                    // Prevent numbers from starting with 0 (e.g., "05" is just 5)
                    if (currentNum == 0 && digit == 0) {
                        continue;
                    }

                    int nextNum = currentNum * 10 + digit;
                    if (nextNum < MAX_POSSIBLE_VALUE) {
                        generatePossibleNumbers(nextNum, usedRows, digitRows, possibleFlags);
                    }
                }

                usedRows[i] = false; // Backtrack: unmark row for other permutations
            }
        }
    }

    /**
     * Finds the highest value x such that 1, 2, ..., x are all present in the flags.
     */
    private static int findMaxConsecutive(boolean[] possibleFlags) {
        int result = 0;
        for (int i = 1; i < MAX_POSSIBLE_VALUE; i++) {
            if (possibleFlags[i]) {
                result = i;
            } else {
                break;
            }
        }
        return result;
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream inputStream) {
            br = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

